"../src/lib/calls/p2P/byteBuf.ts","../src/lib/calls/p2P/sctpSignaling.ts","../src/lib/calls/p2P/fallbackMedia.ts","../src/lib/calls/p2P/utils.ts","../src/lib/calls/callInstance.ts","../src/environment/conferenceCallSupport.ts","../src/lib/calls/callsController.ts","../src/lib/rlottie/rlottieIcon.ts","../src/components/superIcon.ts","../src/components/groupCall/microphoneIcon.ts","../src/components/groupCall/participantMutedIcon.ts","../src/components/groupCall/participantStatus.ts","../src/components/groupCall/participantsList.ts","../src/components/call/videoCanvasBlur.ts","../src/components/groupCall/participantVideo.ts","../src/components/groupCall/participantVideos.ts","../src/components/groupCall/participants.ts","../src/components/groupCall/description.ts","../src/components/groupCall/title.ts","../src/components/call/button.ts","../src/helpers/toggleClassName.ts","../src/lib/calls/e2e/emojiFingerprint.ts","../src/components/conferenceCall/fingerprintBadge.tsx","../src/components/rtmp/outputDevicePopup.tsx","../src/components/call/microphoneLevelMeter.tsx","../src/lib/calls/applyDeviceToActiveCall.ts","../src/components/call/cameraSection.tsx","../src/components/call/settingsPopup.tsx","../src/components/groupCall/index.tsx","../src/components/groupCall/microphoneIconMini.ts","../src/components/call/description.ts","../src/components/call/index.ts","../src/components/rtmp/description.ts","../src/helpers/dom/videoToImage.ts","../src/components/rtmp/assets/recordAudio.svg","../src/components/rtmp/assets/videoVertical.svg","../src/components/rtmp/assets/videoHorizontal.svg","../src/components/rtmp/recordPopup.tsx","../src/components/rtmp/adminStreamPopup.tsx","../src/components/appMediaViewerRtmp.ts","../src/components/topbarCall.tsx","../src/helpers/files/getFilesFromEvent.ts","../src/components/popups/giftPremium.ts","../src/components/popups/webApp.ts","../src/helpers/dom/getSelectedNodes.ts","../src/lib/appManagers/utils/useLockScreenShortcut.ts","../src/components/playbackRateButton.ts","../src/components/sidebarRight/tabs/savedMusic.tsx","../src/components/chat/audio.tsx","../src/lib/appImManager.ts","../src/components/appMediaViewer.ts","../src/components/premium/promoSlideTab.ts","../src/components/premium/limitsFeature.ts","../src/components/premium/upgradedStoriesFeature.ts","../src/components/premium/premiumStickersCarousel.ts","../src/components/premium/featuresCarousel.ts","../src/components/premium/featureSlideTab.ts","../src/components/popups/premium.ts","../src/components/generateTitleIcons.ts","../src/components/peerTitle.ts","../src/components/wrappers/peerTitle.tsx","../src/components/popups/deleteDialog.ts","../src/components/popups/chatPreview.tsx","../src/components/dialogsContextMenu.ts","../src/components/sendingStatus.ts","../src/components/stories/list.tsx","../src/stores/promo.ts","../src/components/popups/passkey.tsx","../src/components/sidebarLeft/pendingSuggestion.tsx","../src/components/autonomousDialogList/constants.ts","../src/components/archiveDialog.tsx","../src/components/groupCallActiveIcon.ts","../src/components/autonomousDialogList/dialogs.ts","../src/components/forumTab/register.ts","../src/components/forumTab/forumTab.ts","../src/components/autonomousDialogList/botforumTopics.ts","../src/components/forumTab/botforumTab.ts","../src/components/autonomousDialogList/forumTopics.ts","../src/components/forumTab/groupForumTab.ts","../src/components/forumTab/monoforumTab.ts","../src/components/forumTab/fillRegister.ts","../src/components/archiveDialogContextMenu.ts","../src/lib/appDialogsManager.ts"],"sourcesContent":["import {doubleRaf} from '@helpers/schedulers';\n\nexport default function fixSafariStickyInput(input: HTMLElement) {\n  input.style.transform = 'translateY(-99999px)';\n  /* input.style.position = 'fixed';\n  input.style.top = '-99999px';\n  input.style.left = '0'; */\n  input.focus();\n\n  // setTimeout(() => {\n  doubleRaf().then(() => {\n    // fastSmoothScroll(findUpClassName(input, 'scrollable-y') || window as any, document.activeElement as HTMLElement, 'start', 4, undefined, FocusDirection.Static);\n    /* input.style.position = '';\n    input.style.top = ''; */\n    input.style.transform = '';\n    // fastSmoothScroll(findUpClassName(input, 'scrollable-y') || window as any, document.activeElement as HTMLElement, 'start', 4, undefined, FocusDirection.Static);\n\n    /* setTimeout(() => {\n      fastSmoothScroll(findUpClassName(input, 'scrollable-y') || window as any, document.activeElement as HTMLElement, 'start', 4);\n    }, 50); */\n  });\n  // }, 0);\n}\n","import {_i18n} from '@lib/langPack';\n\nexport default function generateFakeIcon(isScam?: boolean) {\n  const span = document.createElement('span');\n  span.classList.add('badge-fake');\n  _i18n(span, isScam ? 'ScamMessage' : 'FakeMessage');\n  return span;\n}\n","import Icon from '@components/icon';\n\nexport default function generatePremiumIcon() {\n  const span = Icon('star', 'premium-icon');\n  return span;\n}\n","export default function generateVerifiedIcon() {\n  const span = document.createElement('span');\n  span.classList.add('verified-icon');\n\n  const size = 26; // 24\n  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n  svg.setAttributeNS(null, 'viewBox', `0 0 ${size} ${size}`);\n  svg.setAttributeNS(null, 'width', `${size}`);\n  svg.setAttributeNS(null, 'height', `${size}`);\n  svg.classList.add('verified-icon-svg');\n\n  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n  use.setAttributeNS(null, 'href', '#verified-icon-background');\n  use.classList.add('verified-icon-background');\n\n  const use2 = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n  use2.setAttributeNS(null, 'href', '#verified-icon-check');\n  use2.classList.add('verified-icon-check');\n\n  // svg.append(use, use2);\n  svg.append(use2, use);\n\n  span.append(svg);\n\n  return span;\n  // const span = document.createElement('span');\n  // span.classList.add('verified-icon', 'tgico-verified_filled');\n  // return span;\n}\n","import type ListenerSetter from '@helpers/listenerSetter';\nimport ripple from '@components/ripple';\nimport {LangPackKey, _i18n} from '@lib/langPack';\nimport getDeepProperty from '@helpers/object/getDeepProperty';\nimport rootScope from '@lib/rootScope';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\n\nexport type CheckboxFieldColor = 'white' | 'secondary';\n\nexport type CheckboxFieldOptions = {\n  text?: LangPackKey,\n  textArgs?: any[],\n  name?: string,\n  round?: boolean,\n  color?: CheckboxFieldColor,\n  toggle?: boolean,\n  stateKey?: string,\n  stateValues?: any[],\n  stateValueReverse?: boolean,\n  disabled?: boolean,\n  checked?: boolean,\n  restriction?: boolean,\n  withRipple?: boolean,\n  withHover?: boolean,\n  listenerSetter?: ListenerSetter,\n  asRadio?: boolean\n};\nexport default class CheckboxField {\n  public input: HTMLInputElement;\n  public label: HTMLLabelElement;\n  public span: HTMLSpanElement;\n  public listenerSetter: ListenerSetter;\n\n  constructor(options: CheckboxFieldOptions = {}) {\n    const label = this.label = document.createElement('label');\n    label.classList.add('checkbox-field');\n\n    if(options.restriction && !options.toggle) {\n      label.classList.add('checkbox-field-restriction');\n    }\n\n    if(options.round) {\n      label.classList.add('checkbox-field-round');\n    }\n\n    if(options.color && options.color !== 'secondary') {\n      label.classList.add('checkbox-color-' + options.color);\n    }\n\n    if(options.disabled) {\n      this.toggleDisability(true);\n    }\n\n    this.listenerSetter = options.listenerSetter;\n\n    const input = this.input = document.createElement('input');\n    input.classList.add('checkbox-field-input');\n    input.type = options.asRadio ? 'radio' : 'checkbox';\n    if(options.name) {\n      input[options.asRadio ? 'name' : 'id'] = 'input-' + options.name;\n    }\n\n    if(options.checked) {\n      input.checked = true;\n    }\n\n    if(options.stateKey) {\n      let loaded = options.checked !== undefined;\n      const onChange = () => {\n        if(!loaded) {\n          return;\n        }\n\n        let value: any;\n        if(options.stateValues) {\n          value = options.stateValues[input.checked ? 1 : 0];\n        } else {\n          value = input.checked;\n\n          if(options.stateValueReverse) {\n            value = !value;\n          }\n        }\n\n        rootScope.managers.appStateManager.setByKey(options.stateKey, value);\n      };\n\n      !loaded && apiManagerProxy.getState().then((state) => {\n        loaded = true;\n        const stateValue = getDeepProperty(state, options.stateKey);\n        let checked: boolean;\n        if(options.stateValues) {\n          checked = options.stateValues.indexOf(stateValue) === 1;\n        } else {\n          checked = stateValue;\n\n          if(options.stateValueReverse) {\n            checked = !checked;\n          }\n        }\n\n        this.setValueSilently(checked);\n      });\n\n      if(options.listenerSetter) options.listenerSetter.add(input)('change', onChange);\n      else input.addEventListener('change', onChange);\n    }\n\n    let span: HTMLSpanElement;\n    if(options.text) {\n      span = this.span = document.createElement('span');\n      span.classList.add('checkbox-caption');\n      _i18n(span, options.text, options.textArgs);\n    } else {\n      label.classList.add('checkbox-without-caption');\n    }\n\n    label.append(input);\n\n    if(options.toggle) {\n      label.classList.add('checkbox-field-toggle');\n\n      if(options.restriction) {\n        label.classList.add('checkbox-field-toggle-restriction');\n      }\n\n      const toggle = document.createElement('div');\n      toggle.classList.add('checkbox-toggle');\n      const circle = document.createElement('div');\n      circle.classList.add('checkbox-toggle-circle');\n      toggle.append(circle);\n      label.append(toggle);\n    } else {\n      const box = document.createElement('div');\n      box.classList.add('checkbox-box');\n\n      const checkSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n      checkSvg.classList.add('checkbox-box-check');\n      checkSvg.setAttributeNS(null, 'viewBox', '0 0 24 24');\n      const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n      use.setAttributeNS(null, 'href', '#check');\n      use.setAttributeNS(null, 'x', '-1');\n      checkSvg.append(use);\n\n      const bg = document.createElement('div');\n      bg.classList.add('checkbox-box-background');\n\n      const border = document.createElement('div');\n      border.classList.add('checkbox-box-border');\n\n      box.append(border, bg, checkSvg);\n\n      label.append(box);\n    }\n\n    if(span) {\n      label.append(span);\n    }\n\n    if(options.withRipple) {\n      label.classList.add('checkbox-ripple', 'hover-effect');\n      ripple(label);\n      // label.prepend(input);\n    } else if(options.withHover) {\n      label.classList.add('hover-effect');\n    }\n  }\n\n  get checked() {\n    return this.input.checked;\n  }\n\n  set checked(checked: boolean) {\n    /* if(this.checked === checked) {\n      return;\n    } */\n\n    this.setValueSilently(checked);\n    simulateEvent(this.input, 'change');\n  }\n\n  public setValueSilently(checked: boolean) {\n    this.input.checked = checked;\n  }\n\n  public isDisabled() {\n    return this.label.classList.contains('checkbox-disabled');\n  }\n\n  public toggleDisability(disable: boolean) {\n    this.label.classList.toggle('checkbox-disabled', disable);\n    this.input.disabled = disable;\n    return () => this.toggleDisability(!disable);\n  }\n}\n","import simulateEvent from '@helpers/dom/dispatchEvent';\nimport getDeepProperty from '@helpers/object/getDeepProperty';\nimport {LangPackKey, _i18n} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport Icon from '@components/icon';\n\nexport default class RadioField {\n  public input: HTMLInputElement;\n  public label: HTMLLabelElement;\n  public main: HTMLElement;\n  public lockIcon: HTMLElement;\n\n  constructor(options: {\n    text?: string,\n    textElement?: HTMLElement | DocumentFragment,\n    langKey?: LangPackKey,\n    name: string,\n    value?: string,\n    valueForState?: any,\n    stateKey?: string,\n    alignRight?: boolean\n  }) {\n    const label = this.label = document.createElement('label');\n    label.classList.add('radio-field');\n\n    if(options.alignRight) {\n      label.classList.add('radio-field-right');\n    }\n\n    const input = this.input = document.createElement('input');\n    input.type = 'radio';\n    /* input.id =  */input.name = 'input-radio-' + options.name;\n\n    if(options.value !== undefined) {\n      input.value = options.value;\n\n      const getValueForState = () => 'valueForState' in options ? options.valueForState : options.value;\n\n      if(options.stateKey) {\n        apiManagerProxy.getState().then((state) => {\n          input.checked = getDeepProperty(state, options.stateKey) === getValueForState();\n        });\n\n        input.addEventListener('change', () => {\n          rootScope.managers.appStateManager.setByKey(options.stateKey, getValueForState());\n        });\n      }\n    }\n\n    const main = this.main = document.createElement('div');\n    main.classList.add('radio-field-main');\n\n    if(options.textElement) {\n      main.append(options.textElement);\n    } else if(options.text) {\n      main.textContent = options.text;\n      /* const caption = document.createElement('div');\n      caption.classList.add('radio-field-main-caption');\n      caption.innerHTML = text;\n\n      if(subtitle) {\n        label.classList.add('radio-field-with-subtitle');\n        caption.insertAdjacentHTML('beforeend', `<div class=\"radio-field-main-subtitle\">${subtitle}</div>`);\n      }\n\n      main.append(caption); */\n    } else if(options.langKey) {\n      _i18n(main, options.langKey);\n    }\n\n    label.append(input, main);\n  }\n\n  get checked() {\n    return this.input.checked;\n  }\n\n  set checked(checked: boolean) {\n    this.setValueSilently(checked);\n    simulateEvent(this.input, 'change');\n  }\n\n  get locked() {\n    return !!this.lockIcon;\n  }\n\n  set locked(locked: boolean) {\n    if(!locked) {\n      this.lockIcon?.remove();\n      this.lockIcon = undefined;\n      this.main.classList.remove('is-locked');\n      return;\n    }\n\n    if(this.lockIcon) {\n      return;\n    }\n\n    this.main.prepend(this.lockIcon = Icon('premium_lock', 'radio-field-lock'));\n    this.main.classList.add('is-locked');\n  }\n\n  public setValueSilently(checked: boolean) {\n    this.input.checked = checked;\n  }\n}\n","export default function RadioForm(radios: {container: HTMLElement, input: HTMLInputElement}[], onChange: (value: string, event: Event) => void) {\n  const form = document.createElement('form');\n\n  radios.forEach((r) => {\n    const {container, input} = r;\n    form.append(container);\n    input.addEventListener('change', (e) => {\n      if(input.checked) {\n        onChange(input.value, e);\n      }\n    });\n  });\n\n  return form;\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport mediaSizes from '@helpers/mediaSizes';\nimport OverlayClickHandler from '@helpers/overlayClickHandler';\nimport overlayCounter from '@helpers/overlayCounter';\nimport pause from '@helpers/schedulers/pause';\n\ntype AdditionalMenuItem = {\n  level: number,\n  element: HTMLElement,\n  triggerElement: HTMLElement,\n  close: () => void,\n}\n\nclass ContextMenuController extends OverlayClickHandler {\n  protected additionalMenus: AdditionalMenuItem[] = [];\n  protected menuOpenTarget: HTMLElement;\n\n  constructor() {\n    super('menu', true);\n\n    mediaSizes.addEventListener('resize', () => {\n      if(this.element) {\n        this.close();\n      }\n\n      /* if(openedMenu && (openedMenu.style.top || openedMenu.style.left)) {\n        const rect = openedMenu.getBoundingClientRect();\n        const {innerWidth, innerHeight} = window;\n\n        console.log(innerWidth, innerHeight, rect);\n      } */\n    });\n  }\n\n  public isOpened() {\n    return !!this.element;\n  }\n\n  private onMouseMove = (e: MouseEvent) => {\n    const allMenus = [\n      ...[...this.additionalMenus].reverse(),\n      {\n        triggerElement: undefined,\n        level: 0,\n        element: this.element,\n        close: () => this.close()\n      }\n    ];\n\n    function isFartherThan(element: HTMLElement, distance: number) {\n      const {clientX, clientY} = e;\n\n      const rect = element.getBoundingClientRect();\n\n      const diffX = clientX >= rect.right ? clientX - rect.right : rect.left - clientX;\n      const diffY = clientY >= rect.bottom ? clientY - rect.bottom : rect.top - clientY;\n\n      return diffX >= distance || diffY >= distance;\n    }\n\n    for(const item of allMenus) {\n      if(item.triggerElement && !isFartherThan(item.triggerElement, 40)) break;\n\n      if(isFartherThan(item.element, item.level === 0 ? 100 : 40)) {\n        this.closeAndRemoveMenu(item);\n      } else {\n        break;\n      }\n    }\n  };\n\n  protected closeAndRemoveMenu(item: AdditionalMenuItem) {\n    item.close();\n    const idx = this.additionalMenus.indexOf(item);\n    if(idx > -1) {\n      for(let i = idx + 1; i < this.additionalMenus.length; i++) {\n        this.additionalMenus[i].close();\n      }\n      this.additionalMenus.splice(idx);\n    }\n  }\n\n  public closeMenusByLevel(level: number) {\n    this.additionalMenus.filter((menu) => menu.level >= level).forEach((item) => {\n      item.close();\n    });\n\n    this.additionalMenus = this.additionalMenus.filter((menu) => menu.level < level);\n  }\n\n  public close(e?: MouseEvent | TouchEvent) {\n    if(e && (e.target as HTMLElement).classList.contains('btn-menu')) {\n      return;\n    }\n\n    if(this.element) {\n      this.element.classList.remove('active');\n      this.menuOpenTarget?.classList.remove('menu-open');\n      this.menuOpenTarget = undefined;\n\n      if(this.element.classList.contains('night')) {\n        const element = this.element;\n        setTimeout(() => {\n          if(element.classList.contains('active')) {\n            return;\n          }\n\n          element.classList.remove('night');\n        }, 400);\n      }\n    }\n\n    this.additionalMenus.forEach((menu) => {\n      menu.close();\n    });\n\n    this.additionalMenus = [];\n\n    super.close();\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.realmWindow.removeEventListener('mousemove', this.onMouseMove);\n    }\n  }\n\n  protected shouldApplyNight(triggerElement?: HTMLElement) {\n    if(overlayCounter.isDarkOverlayActive) return true;\n    const nightAncestor = triggerElement && findUpClassName(triggerElement, 'night');\n    return !!nightAncestor && nightAncestor !== document.documentElement;\n  }\n\n  public openBtnMenu(element: HTMLElement, onClose?: () => void, triggerElement?: HTMLElement) {\n    if(this.shouldApplyNight(triggerElement)) {\n      element.classList.add('night');\n    }\n\n    super.open(element);\n\n    this.element.classList.add('active', 'was-open');\n    this.menuOpenTarget = triggerElement ?? this.element.parentElement;\n    this.menuOpenTarget?.classList.add('menu-open');\n\n    if(onClose) {\n      this.addEventListener('toggle', onClose, {once: true});\n    }\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.realmWindow.addEventListener('mousemove', this.onMouseMove);\n    }\n  }\n\n  public addAdditionalMenu(element: HTMLElement, triggerElement: HTMLElement, level: number, onClose?: () => void) {\n    if(!this.element) return;\n\n    this.closeMenusByLevel(level);\n\n    this.additionalMenus.push({\n      element,\n      triggerElement,\n      level,\n      close: () => {\n        element.classList.remove('active');\n        pause(400).then(() => element.remove());\n        onClose();\n      }\n    });\n    if(this.shouldApplyNight(triggerElement)) {\n      element.classList.add('night');\n    }\n    element.classList.add('active', 'was-open');\n\n    if(onClose) {\n      this.addEventListener('toggle', onClose, {once: true});\n    }\n  }\n}\n\nconst contextMenuController = new ContextMenuController();\nexport default contextMenuController;\n","import sequentialDom from '@helpers/sequentialDom';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\n\nconst UNMOUNT_THUMBS = true;\n\nexport default function renderMediaWithFadeIn({\n  container,\n  media,\n  url,\n  needFadeIn,\n  aspecter = container,\n  thumbImage,\n  fadeInElement = media as any,\n  onRender,\n  onRenderFinish,\n  useRenderCache\n}: {\n  container: HTMLElement,\n  media: Parameters<typeof renderImageFromUrlPromise>[0],\n  url: string,\n  needFadeIn: boolean,\n  aspecter?: HTMLElement,\n  thumbImage?: HTMLElement,\n  fadeInElement?: HTMLElement,\n  onRender?: () => void,\n  onRenderFinish?: () => void,\n  useRenderCache?: boolean\n}) {\n  if(needFadeIn) {\n    fadeInElement.classList.add('fade-in');\n  }\n\n  const promise = renderImageFromUrlPromise(media, url, useRenderCache).then(() => {\n    return sequentialDom.mutateElement(container, () => {\n      aspecter?.append(media);\n\n      if(needFadeIn) {\n        onRender?.();\n        fadeInElement.addEventListener('animationend', () => {\n          sequentialDom.mutate(() => {\n            fadeInElement.classList.remove('fade-in');\n            UNMOUNT_THUMBS && thumbImage?.remove();\n            container.classList.add('no-background');\n            onRenderFinish?.();\n          });\n        }, {once: true});\n      } else {\n        UNMOUNT_THUMBS && thumbImage?.remove();\n        container.classList.add('no-background');\n        onRender?.();\n        onRenderFinish?.();\n      }\n    });\n  });\n\n  // recordPromise(promise, 'renderImageWithFadeIn');\n\n  return promise;\n}\n","import liteMode from '@helpers/liteMode';\n\nconst $TRANSITION_RAF = Symbol('RAF'),\n  $TRANSITION_TIMEOUT = Symbol('TIMEOUT');\n\ntype SetTransitionOptions = {\n  element: HTMLElement,\n  className: string,\n  forwards: boolean,\n  duration: number,\n  onTransitionEnd?: () => void,\n  useRafs?: number,\n  onTransitionStart?: () => void\n};\nconst SetTransition = (options: SetTransitionOptions) => {\n  const {element, className, forwards, duration, onTransitionEnd, onTransitionStart, useRafs} = options;\n  const classNames = className && className.split(' ');\n  const timeout: number = (element as any)[$TRANSITION_TIMEOUT];\n  const raf: number = (element as any)[$TRANSITION_RAF];\n  if(timeout !== undefined) {\n    clearTimeout(+timeout);\n  }\n\n  // useRafs = undefined;\n  // duration = 0;\n\n  if(raf !== undefined) {\n    window.cancelAnimationFrame(+raf);\n    if(!useRafs) {\n      delete (element as any)[$TRANSITION_RAF];\n    }\n  }\n\n  // if(forwards && className && element.classList.contains(className) && !element.classList.contains('animating')) {\n  //   return;\n  // }\n\n  if(useRafs && liteMode.isAvailable('animations') && duration) {\n    (element as any)[$TRANSITION_RAF] = '' + window.requestAnimationFrame(() => {\n      delete (element as any)[$TRANSITION_RAF];\n      SetTransition({\n        ...options,\n        useRafs: useRafs - 1\n      });\n    });\n\n    return;\n  }\n\n  if(forwards && className) {\n    element.classList.add(...classNames);\n  }\n\n  const afterTimeout = () => {\n    delete (element as any)[$TRANSITION_TIMEOUT];\n    if(!forwards && className) {\n      element.classList.remove('backwards', ...classNames);\n    }\n\n    element.classList.remove('animating');\n\n    onTransitionEnd?.();\n  };\n\n  onTransitionStart?.();\n  element.classList.toggle('forwards', forwards);\n  if(!liteMode.isAvailable('animations') || !duration) {\n    element.classList.remove('animating', 'backwards');\n    afterTimeout();\n    return;\n  }\n\n  element.classList.add('animating');\n\n  element.classList.toggle('backwards', !forwards);\n  (element as any)[$TRANSITION_TIMEOUT] = '' + setTimeout(afterTimeout, duration);\n};\n\nexport default SetTransition;\n","import {CancellablePromise} from '@helpers/cancellablePromise';\nimport SetTransition from '@components/singleTransition';\nimport {fastRaf} from '@helpers/schedulers';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport safeAssign from '@helpers/object/safeAssign';\n\nconst TRANSITION_TIME = 200;\n\nexport default class ProgressivePreloader {\n  public preloader: HTMLDivElement;\n  public circle: SVGCircleElement;\n  private cancelSvg: SVGSVGElement;\n  private downloadSvg: HTMLElement;\n\n  private tempId = 0;\n  public detached = true;\n\n  public promise: CancellablePromise<any> = null;\n\n  public isUpload = false;\n  private cancelable = true;\n  private streamable = false;\n  private rtmp = false;\n  private tryAgainOnFail = true;\n  private attachMethod: 'append' | 'prepend' = 'append';\n\n  public loadFunc: (e?: Event) => any;\n\n  public totalLength: number;\n\n  constructor(options?: Partial<{\n    isUpload: ProgressivePreloader['isUpload'],\n    cancelable: ProgressivePreloader['cancelable'],\n    streamable: ProgressivePreloader['streamable'],\n    rtmp: ProgressivePreloader['rtmp'],\n    tryAgainOnFail: ProgressivePreloader['tryAgainOnFail'],\n    attachMethod: ProgressivePreloader['attachMethod']\n  }>) {\n    if(options) {\n      safeAssign(this, options);\n    }\n\n    if(this.isUpload) {\n      this.tryAgainOnFail = false;\n    }\n  }\n\n  public constructContainer(options: Partial<{\n    color: 'transparent',\n    bold: boolean\n  }> = {}) {\n    if(!this.preloader) {\n      this.preloader = document.createElement('div');\n      if(this.rtmp) {\n        this.preloader.classList.add('preloader-container-rtmp');\n      } else {\n        this.preloader.classList.add('preloader-container');\n      }\n\n      if(options.color) {\n        this.preloader.classList.add('preloader-' + options.color);\n      }\n\n      if(options.bold) {\n        this.preloader.classList.add('preloader-bold');\n      }\n\n      if(this.streamable) {\n        this.preloader.classList.add('preloader-streamable');\n      }\n    }\n  }\n\n  public constructDownloadIcon() {\n    this.constructContainer();\n  }\n\n  public construct() {\n    this.construct = null;\n\n    this.constructContainer();\n\n    if(this.rtmp) {\n      this.preloader.innerHTML = `\n      <div class=\"loading-wrap is-loading\">\n        <div class=\"loading\"></div>\n        <div class=\"loading_bezel-wrap\">\n          <div class=\"loading\"></div>\n        </div>\n      </div>`;\n    } else {\n      this.preloader.innerHTML = `\n      <div class=\"you-spin-me-round\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-circular\" viewBox=\"${this.streamable ? '25 25 50 50' : '27 27 54 54'}\">\n      <circle class=\"preloader-path-new\" cx=\"${this.streamable ? '50' : '54'}\" cy=\"${this.streamable ? '50' : '54'}\" r=\"${this.streamable ? 19 : 24}\" fill=\"none\" stroke-miterlimit=\"10\"/>\n      </svg>\n      </div>`;\n    }\n\n    if(this.streamable) {\n      this.totalLength = 118.61124420166016;\n    } else {\n      this.totalLength = 149.82473754882812;\n    }\n\n    if(this.cancelable) {\n      this.preloader.innerHTML += `\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-close\" viewBox=\"0 0 24 24\">\n        <g fill=\"none\" fill-rule=\"evenodd\">\n          <polygon points=\"0 0 24 0 24 24 0 24\"/>\n          <path fill=\"#000\" fill-rule=\"nonzero\" d=\"M5.20970461,5.38710056 L5.29289322,5.29289322 C5.65337718,4.93240926 6.22060824,4.90467972 6.61289944,5.20970461 L6.70710678,5.29289322 L12,10.585 L17.2928932,5.29289322 C17.6834175,4.90236893 18.3165825,4.90236893 18.7071068,5.29289322 C19.0976311,5.68341751 19.0976311,6.31658249 18.7071068,6.70710678 L13.415,12 L18.7071068,17.2928932 C19.0675907,17.6533772 19.0953203,18.2206082 18.7902954,18.6128994 L18.7071068,18.7071068 C18.3466228,19.0675907 17.7793918,19.0953203 17.3871006,18.7902954 L17.2928932,18.7071068 L12,13.415 L6.70710678,18.7071068 C6.31658249,19.0976311 5.68341751,19.0976311 5.29289322,18.7071068 C4.90236893,18.3165825 4.90236893,17.6834175 5.29289322,17.2928932 L10.585,12 L5.29289322,6.70710678 C4.93240926,6.34662282 4.90467972,5.77939176 5.20970461,5.38710056 L5.29289322,5.29289322 L5.20970461,5.38710056 Z\"/>\n        </g>\n      </svg>\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-download\" viewBox=\"0 0 24 24\">\n        <g fill=\"none\" fill-rule=\"evenodd\">\n          <polygon points=\"0 0 24 0 24 24 0 24\"/>\n          <path fill=\"#000\" fill-rule=\"nonzero\" d=\"M5,19 L19,19 C19.5522847,19 20,19.4477153 20,20 C20,20.5128358 19.6139598,20.9355072 19.1166211,20.9932723 L19,21 L5,21 C4.44771525,21 4,20.5522847 4,20 C4,19.4871642 4.38604019,19.0644928 4.88337887,19.0067277 L5,19 L19,19 L5,19 Z M11.8833789,3.00672773 L12,3 C12.5128358,3 12.9355072,3.38604019 12.9932723,3.88337887 L13,4 L13,13.585 L16.2928932,10.2928932 C16.6533772,9.93240926 17.2206082,9.90467972 17.6128994,10.2097046 L17.7071068,10.2928932 C18.0675907,10.6533772 18.0953203,11.2206082 17.7902954,11.6128994 L17.7071068,11.7071068 L12.7071068,16.7071068 C12.3466228,17.0675907 11.7793918,17.0953203 11.3871006,16.7902954 L11.2928932,16.7071068 L6.29289322,11.7071068 C5.90236893,11.3165825 5.90236893,10.6834175 6.29289322,10.2928932 C6.65337718,9.93240926 7.22060824,9.90467972 7.61289944,10.2097046 L7.70710678,10.2928932 L11,13.585 L11,4 C11,3.48716416 11.3860402,3.06449284 11.8833789,3.00672773 L12,3 L11.8833789,3.00672773 Z\"/>\n        </g>\n      </svg>`;\n\n      this.downloadSvg = this.preloader.lastElementChild as HTMLElement;\n      this.cancelSvg = this.downloadSvg.previousElementSibling as any;\n    } else {\n      this.preloader.classList.add('preloader-swing');\n    }\n\n    this.circle = this.preloader.firstElementChild.firstElementChild.firstElementChild as SVGCircleElement;\n\n    if(this.cancelable) {\n      attachClickEvent(this.preloader, this.onClick);\n    }\n  }\n\n  public onClick = (e?: Event) => {\n    if(e) {\n      cancelEvent(e);\n    }\n\n    if(this.preloader.classList.contains('manual')) {\n      this.loadFunc?.(e);\n    } else {\n      this.promise?.cancel?.();\n    }\n  };\n\n  public setDownloadFunction(func: ProgressivePreloader['loadFunc']) {\n    this.loadFunc = func;\n  }\n\n  public setManual() {\n    this.preloader.classList.add('manual');\n    this.setProgress(0);\n  }\n\n  public attachPromise(promise: CancellablePromise<any>) {\n    if(this.isUpload && this.promise) return;\n\n    this.promise = promise;\n\n    const tempId = --this.tempId;\n    const startTime = Date.now();\n\n    const onEnd = (err: Error) => {\n      promise.notify = promise.notifyAll = null;\n\n      if(tempId !== this.tempId) {\n        return;\n      }\n\n      const elapsedTime = Date.now() - startTime;\n\n      // console.log('[PP]: end', this.detached, performance.now());\n\n      if(!err && this.cancelable) {\n        this.setProgress(100);\n\n        const delay = TRANSITION_TIME * 0.75;\n\n        if(elapsedTime < delay) {\n          this.detach();\n        } else {\n          setTimeout(() => { // * wait for transition complete\n            if(tempId === this.tempId) {\n              this.detach();\n            }\n          }, delay);\n        }\n      } else {\n        if(this.tryAgainOnFail) {\n          this.attach(this.preloader.parentElement);\n          fastRaf(() => {\n            this.setManual();\n          });\n        } else {\n          this.detach();\n        }\n      }\n\n      this.promise = promise = null;\n    };\n\n    promise\n    .then(() => onEnd(null))\n    .catch((err) => onEnd(err));\n\n    promise.addNotifyListener?.((details: {done: number, total: number}) => {\n      /* if(details.done >= details.total) {\n        onEnd();\n      } */\n\n      if(tempId !== this.tempId) return;\n\n      // console.log('preloader download', promise, details);\n      const percents = details.done / details.total * 100;\n      this.setProgress(percents);\n    });\n  }\n\n  public attach(elem: Element, reset = false, promise?: CancellablePromise<any>) {\n    if(!this.detached && (!this.preloader || !this.preloader.classList.contains('manual'))) {\n      return;\n    }\n\n    this.construct?.();\n\n    if(this.preloader.parentElement) {\n      this.preloader.classList.remove('manual');\n    }\n\n    this.detached = false;\n\n    if(promise/*  && false */) {\n      this.attachPromise(promise);\n    }\n\n    let useRafs = 0;\n    if(this.detached || this.preloader.parentElement !== elem) {\n      useRafs = isInDOM(this.preloader) ? 1 : 2;\n      if(this.preloader.parentElement !== elem) {\n        elem[this.attachMethod](this.preloader);\n      }\n    }\n\n    SetTransition({\n      element: this.preloader,\n      className: 'is-visible',\n      forwards: true,\n      duration: TRANSITION_TIME,\n      useRafs\n    });\n\n    if(this.cancelable && reset) {\n      this.setProgress(0);\n    }\n  }\n\n  public detach() {\n    if(this.detached) {\n      return;\n    }\n    // return;\n\n    this.detached = true;\n\n    // return;\n\n    if(this.preloader?.parentElement) {\n      /* setTimeout(() =>  */// fastRaf(() => {\n      /* if(!this.detached) return;\n        this.detached = true; */\n\n      // fastRaf(() => {\n      // console.log('[PP]: detach after rAF', this.detached, performance.now());\n\n      // if(!this.detached || !this.preloader.parentElement) {\n      //   return;\n      // }\n\n      SetTransition({\n        element: this.preloader,\n        className: 'is-visible',\n        forwards: false,\n        duration: TRANSITION_TIME,\n        onTransitionEnd: () => {\n          this.preloader.remove();\n        },\n        useRafs: 1\n      });\n      // });\n      // })/* , 5e3) */;\n    }\n  }\n\n  public setProgress(percents: number) {\n    if(!this.totalLength && !isInDOM(this.circle)) {\n      return;\n    }\n\n    if(percents === 0) {\n      this.circle.style.strokeDasharray = '';\n      return;\n    }\n\n    try {\n      this.totalLength ||= this.circle.getTotalLength();\n\n      // console.log('setProgress', (percents / 100 * totalLength));\n      this.circle.style.strokeDasharray = '' + Math.max(5, percents / 100 * this.totalLength) + ', ' + this.totalLength;\n    } catch(err) {}\n  }\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type {MyPhoto} from '@appManagers/appPhotosManager';\nimport type {ThumbCache} from '@lib/storages/thumbs';\nimport {THUMB_TYPE_FULL} from '@appManagers/constants';\nimport getImageFromStrippedThumb from '@helpers/getImageFromStrippedThumb';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {PhotoSize} from '@layer';\n\nexport default function getMediaThumbIfNeeded({\n  photo,\n  cacheContext,\n  useBlur,\n  ignoreCache,\n  onlyStripped\n}: {\n  photo: MyPhoto | MyDocument,\n  cacheContext: ThumbCache,\n  useBlur: boolean | number,\n  ignoreCache?: boolean,\n  onlyStripped?: boolean\n}) {\n  const isVideo = (['video', 'gif'] as MyDocument['type'][]).includes((photo as MyDocument).type);\n  if(!cacheContext.downloaded || isVideo || ignoreCache) {\n    if(\n      photo._ === 'document' &&\n      cacheContext.downloaded &&\n      !ignoreCache &&\n      (!isVideo || cacheContext.type !== THUMB_TYPE_FULL)\n    ) {\n      return null;\n    }\n\n    const sizes = (photo as MyPhoto).sizes || (photo as MyDocument).thumbs;\n    const length = sizes?.length;\n    if(!length) {\n      return null;\n    }\n\n    let currentSizeIndex = -1;\n    if(!onlyStripped) for(let i = length - 1; i >= 0; --i) {\n      const size = sizes[i];\n      if(size.type === cacheContext.type) {\n        currentSizeIndex = i;\n      } else if(currentSizeIndex) {\n        const cacheContext = apiManagerProxy.getCacheContext(photo, size.type);\n        if(cacheContext.downloaded) {\n          return getImageFromStrippedThumb(photo, size as PhotoSize.photoCachedSize, false, cacheContext.url);\n        }\n      }\n    }\n\n    const thumb = sizes.find((size) => size._ === 'photoStrippedSize');\n    if(thumb && ('bytes' in thumb)) {\n      return getImageFromStrippedThumb(photo, thumb as any, useBlur);\n    }\n  }\n\n  return null;\n}\n","import {Message, MessageMedia, PhotoSize, WebDocument} from '@layer';\nimport {REPLIES_HIDDEN_CHANNEL_ID} from '@appManagers/constants';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport {MediaSize, makeMediaSize} from '@helpers/mediaSize';\nimport isWebDocument from '@appManagers/utils/webDocs/isWebDocument';\n\nexport const EXPAND_TEXT_WIDTH = 320;\nexport const MIN_IMAGE_WIDTH = 120;\nexport const MIN_SIDE_SIZE = 200;\nexport const MIN_VIDEO_SIDE_SIZE = 368;\n\nexport default function setAttachmentSize({\n  photo,\n  element,\n  boxWidth,\n  boxHeight,\n  noZoom = true,\n  message,\n  pushDocumentSize,\n  photoSize,\n  size,\n  canHaveVideoPlayer,\n  noMinSize\n}: {\n  photo?: MyPhoto | MyDocument | WebDocument,\n  element: HTMLElement | SVGForeignObjectElement,\n  boxWidth: number,\n  boxHeight: number,\n  noZoom?: boolean,\n  message?: Message.message,\n  pushDocumentSize?: boolean,\n  photoSize?: ReturnType<typeof choosePhotoSize>,\n  size?: MediaSize,\n  canHaveVideoPlayer?: boolean,\n  noMinSize?: boolean\n}) {\n  const _isWebDocument = isWebDocument(photo);\n  // if(_isWebDocument && pushDocumentSize === undefined) {\n  //   pushDocumentSize = true;\n  // }\n\n  if(!photoSize && !size) {\n    photoSize = choosePhotoSize(photo, boxWidth, boxHeight, undefined, pushDocumentSize);\n  }\n  // console.log('setAttachmentSize', photo, photo.sizes[0].bytes, div);\n\n  const isDocument = photo?._ === 'document';\n  if(size) {\n\n  } else if(isDocument || _isWebDocument) {\n    size = makeMediaSize(\n      photo.w || (photoSize as PhotoSize.photoSize).w || 512,\n      photo.h || (photoSize as PhotoSize.photoSize).h || 512\n    );\n  } else {\n    size = makeMediaSize(\n      (photoSize as PhotoSize.photoSize).w || 100,\n      (photoSize as PhotoSize.photoSize).h || 100\n    );\n  }\n\n  let boxSize = makeMediaSize(boxWidth, boxHeight);\n\n  boxSize = size = size.aspect(boxSize, noZoom);\n\n  let isFit = true;\n  if(!noMinSize && (!isDocument || ['video', 'gif'].includes(photo.type) || _isWebDocument)) {\n    const minSideSize = MIN_SIDE_SIZE;\n    if(boxSize.width < minSideSize && boxSize.height < minSideSize) { // make at least one side this big\n      boxSize = size = size.aspectCovered(makeMediaSize(minSideSize, minSideSize));\n    }\n\n    if(message &&\n      (message.message ||\n        message.factcheck ||\n        message.reply_to_mid ||\n        (message.media as MessageMedia.messageMediaWebPage).webpage ||\n        (message.replies && message.replies.pFlags.comments && message.replies.channel_id.toChatId() !== REPLIES_HIDDEN_CHANNEL_ID)\n      )\n    ) { // make sure that bubble block is human-readable\n      if(boxSize.width < EXPAND_TEXT_WIDTH) {\n        boxSize = makeMediaSize(EXPAND_TEXT_WIDTH, boxSize.height);\n        isFit = false;\n      }\n    }\n\n    const minWidth = (photo as MyDocument)?.type === 'video' && canHaveVideoPlayer ? MIN_VIDEO_SIDE_SIZE : MIN_IMAGE_WIDTH;\n    if(/* isFit &&  */boxSize.width < minWidth && message) { // if image is too narrow\n      boxSize = makeMediaSize(minWidth, boxSize.height);\n      isFit = false;\n    }\n  }\n\n  // if(element instanceof SVGForeignObjectElement) {\n  //   element.setAttributeNS(null, 'width', '' + w);\n  //   element.setAttributeNS(null, 'height', '' + h);\n\n  //   //console.log('set dimensions to svg element:', element, w, h);\n  // } else {\n  element.style.width = boxSize.width + 'px';\n  element.style.height = boxSize.height + 'px';\n  // }\n\n  return {photoSize, size, isFit};\n}\n","import renderMediaWithFadeIn from '@helpers/dom/renderMediaWithFadeIn';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {InputWebFileLocation, Message, PhotoSize, VideoSize, WebDocument} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport rootScope from '@lib/rootScope';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport ProgressivePreloader from '@components/preloader';\nimport blur from '@helpers/blur';\nimport {AppManagers} from '@lib/managers';\nimport getMediaThumbIfNeeded from '@helpers/getStrippedThumbIfNeeded';\nimport setAttachmentSize from '@helpers/setAttachmentSize';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport type {ThumbCache} from '@lib/storages/thumbs';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport isWebDocument from '@appManagers/utils/webDocs/isWebDocument';\nimport createVideo from '@helpers/dom/createVideo';\nimport noop from '@helpers/noop';\nimport {THUMB_TYPE_FULL} from '@appManagers/constants';\nimport {Middleware} from '@helpers/middleware';\nimport liteMode from '@helpers/liteMode';\nimport isWebFileLocation from '@appManagers/utils/webFiles/isWebFileLocation';\nimport apiManagerProxy from '@lib/apiManagerProxy';\n\nexport default async function wrapPhoto({photo, message, container, boxWidth, boxHeight, withTail, isOut, lazyLoadQueue, middleware, size, withoutPreloader, loadPromises, autoDownloadSize, noBlur, noThumb, noFadeIn, blurAfter, managers = rootScope.managers, processUrl, fadeInElement, onRender, onRenderFinish, useBlur, useRenderCache, canHaveVideoPlayer, uploadingFileName}: {\n  photo: MyPhoto | MyDocument | WebDocument | InputWebFileLocation,\n  message?: Message.message | Message.messageService,\n  container?: HTMLElement,\n  boxWidth?: number,\n  boxHeight?: number,\n  withTail?: boolean,\n  isOut?: boolean,\n  lazyLoadQueue?: LazyLoadQueue | false,\n  middleware?: Middleware,\n  size?: PhotoSize | Extract<VideoSize, VideoSize.videoSize>,\n  withoutPreloader?: boolean,\n  loadPromises?: Promise<any>[],\n  autoDownloadSize?: number,\n  noBlur?: boolean,\n  noThumb?: boolean,\n  noFadeIn?: boolean,\n  blurAfter?: boolean,\n  managers?: AppManagers,\n  processUrl?: (url: string) => Promise<string>,\n  fadeInElement?: HTMLElement,\n  onRender?: () => void,\n  onRenderFinish?: () => void,\n  useBlur?: boolean | number,\n  useRenderCache?: boolean,\n  canHaveVideoPlayer?: boolean,\n  uploadingFileName?: string\n}) {\n  const ret = {\n    loadPromises: {\n      thumb: Promise.resolve() as Promise<any>,\n      full: Promise.resolve() as Promise<any>\n    },\n    images: {\n      thumb: null as HTMLImageElement | HTMLCanvasElement,\n      full: null as HTMLVideoElement | HTMLImageElement\n    },\n    preloader: null as ProgressivePreloader,\n    aspecter: null as HTMLElement\n  };\n\n  if(!container) {\n    withoutPreloader = true;\n    lazyLoadQueue = undefined;\n  }\n\n  const isWebFile = isWebFileLocation(photo);\n  const isDocument = photo._ === 'document';\n  const isImageFromDocument = isDocument && photo.mime_type.startsWith('image/') && !size;\n  const isWebDoc = isWebDocument(photo);\n  if(\n    !((photo as MyPhoto).sizes || (photo as MyDocument).thumbs) &&\n    !isWebDoc &&\n    !isImageFromDocument &&\n    !isWebFile\n  ) {\n    if(boxWidth && boxHeight && !size && isDocument) {\n      setAttachmentSize({\n        photo,\n        element: container,\n        boxWidth,\n        boxHeight,\n        message: message as Message.message,\n        canHaveVideoPlayer\n      });\n    }\n\n    return ret;\n  }\n\n  let noAutoDownload = autoDownloadSize === 0;\n\n  if(!size) {\n    if(boxWidth === undefined) boxWidth = mediaSizes.active.regular.width;\n    if(boxHeight === undefined) boxHeight = mediaSizes.active.regular.height;\n  }\n\n  container && container.classList.add('media-container');\n  let aspecter = container;\n\n  let isFit = true;\n  let loadThumbPromise: Promise<any> = Promise.resolve();\n  let thumbImage: HTMLImageElement | HTMLCanvasElement;\n  // let image: HTMLImageElement;\n  let cacheContext: ThumbCache;\n  // if(withTail) {\n  //   image = wrapMediaWithTail(photo, message, container, boxWidth, boxHeight, isOut);\n  // } else {\n\n  if(boxWidth && boxHeight && !size && !isWebFile && container) { // !album\n    const set = setAttachmentSize({\n      photo,\n      element: container,\n      boxWidth,\n      boxHeight,\n      message: message as Message.message,\n      photoSize: isImageFromDocument ? {\n        _: 'photoSize',\n        w: photo.w,\n        h: photo.h,\n        size: photo.size,\n        type: THUMB_TYPE_FULL\n      } : undefined,\n      canHaveVideoPlayer\n    });\n    size = set.photoSize;\n    isFit = set.isFit;\n    cacheContext = apiManagerProxy.getCacheContext(photo, size.type);\n\n    if(!isFit && !isWebDoc) {\n      aspecter = document.createElement('div');\n      aspecter.classList.add('media-container-aspecter');\n      aspecter.style.width = set.size.width + 'px';\n      aspecter.style.height = set.size.height + 'px';\n\n      const gotThumb = getMediaThumbIfNeeded({\n        photo,\n        cacheContext,\n        useBlur: useBlur !== undefined ? useBlur : !noBlur,\n        ignoreCache: true,\n        onlyStripped: true\n      });\n      if(gotThumb) {\n        loadThumbPromise = gotThumb.loadPromise;\n        const thumbImage = gotThumb.image; // local scope\n        thumbImage.classList.add('media-photo');\n        container.append(thumbImage);\n      } else {\n        const res = await wrapPhoto({\n          container,\n          message,\n          photo,\n          boxWidth: 0,\n          boxHeight: 0,\n          size,\n          lazyLoadQueue,\n          isOut,\n          loadPromises,\n          middleware,\n          withoutPreloader: true,\n          withTail,\n          autoDownloadSize,\n          noBlur,\n          noThumb: true,\n          blurAfter: true,\n          managers\n          // noFadeIn: true\n        });\n        const thumbImage = res.images.full;\n        thumbImage.classList.add('media-photo', 'thumbnail');\n        // container.append(thumbImage);\n      }\n\n      container.classList.add('media-container-fitted');\n      container.append(aspecter);\n    }\n  } else {\n    if(!size && !isWebFile) {\n      size = choosePhotoSize(photo, boxWidth, boxHeight, true);\n    }\n\n    cacheContext = apiManagerProxy.getCacheContext(photo, size?.type);\n  }\n\n  if(!noThumb && !isWebDoc && !isWebFile && aspecter) {\n    const gotThumb = getMediaThumbIfNeeded({\n      photo,\n      cacheContext,\n      useBlur: useBlur !== undefined ? useBlur : !noBlur\n    });\n\n    if(gotThumb) {\n      loadThumbPromise = Promise.all([loadThumbPromise, gotThumb.loadPromise]);\n      ret.loadPromises.thumb = ret.loadPromises.full = loadThumbPromise;\n      thumbImage = ret.images.thumb = gotThumb.image;\n      thumbImage.classList.add('media-photo');\n      aspecter.append(thumbImage);\n    }\n  }\n  // }\n\n  ret.aspecter = aspecter;\n\n  if((size?._ === 'photoSizeEmpty' && isDocument) || (size as PhotoSize.photoStrippedSize)?.bytes) {\n    return ret;\n  }\n\n  let media: HTMLVideoElement | HTMLImageElement;\n  if(size?._ === 'videoSize') {\n    media = ret.images.full = createVideo({middleware});\n    media.autoplay = true;\n    media.loop = true;\n    media.muted = true;\n    media.classList.add('media-photo');\n  } else {\n    media = ret.images.full = new Image();\n    media.classList.add('media-photo');\n  }\n\n  // console.log('wrapPhoto downloaded:', photo, photo.downloaded, container);\n\n  const needFadeIn = (thumbImage || !cacheContext.downloaded) && liteMode.isAvailable('animations') && !noFadeIn;\n\n  let preloader: ProgressivePreloader;\n  uploadingFileName ??= (message as Message.message)?.uploadingFileName?.[0];\n  if(!withoutPreloader) {\n    if(!cacheContext.downloaded || uploadingFileName) {\n      preloader = new ProgressivePreloader({\n        attachMethod: 'prepend',\n        isUpload: !!uploadingFileName\n      });\n    }\n\n    if(uploadingFileName) { // means upload\n      preloader.attachPromise(appDownloadManager.getUpload(uploadingFileName));\n      preloader.attach(container);\n      noAutoDownload = undefined;\n    }\n  }\n\n\n  const getDownloadPromise = () => {\n    // const promise = isGif && !size ?\n    //   managers.appDocsManager.downloadDoc(photo, /* undefined,  */lazyLoadQueue?.queueId) :\n    //   managers.appPhotosManager.preloadPhoto(photo, size, lazyLoadQueue?.queueId, noAutoDownload);\n    const haveToDownload = isImageFromDocument && !size;\n    const promise = appDownloadManager.downloadMediaURL({\n      media: photo,\n      thumb: size,\n      queueId: lazyLoadQueue && lazyLoadQueue.queueId,\n      onlyCache: haveToDownload ? undefined : noAutoDownload\n    });\n\n    return promise;\n  };\n\n  const renderOnLoad = (url: string) => {\n    return renderMediaWithFadeIn({\n      container,\n      media,\n      url,\n      needFadeIn,\n      aspecter,\n      thumbImage,\n      fadeInElement,\n      onRender,\n      onRenderFinish,\n      useRenderCache\n    });\n  };\n\n  const onLoad = async(url: string) => {\n    if(middleware && !middleware()) return;\n\n    if(processUrl) {\n      url = await processUrl(url);\n    }\n\n    if(blurAfter) {\n      // downscale to a tiny thumbnail before blurring so the upscaled side-fill looks like\n      // frosted glass (matches the official clients), instead of a weak blur on the full image\n      const result = blur(url, 10, 2, 48);\n      return result.promise.then(() => {\n        // image = result.canvas;\n        return renderOnLoad(result.canvas.toDataURL());\n      });\n    }\n\n    return renderOnLoad(url);\n  };\n\n  let loadPromise: Promise<any>;\n  const canAttachPreloader = (\n    !isWebFile &&\n    (size as PhotoSize.photoSize).w >= 150 &&\n    (size as PhotoSize.photoSize).h >= 150\n  ) || noAutoDownload;\n  const load = async() => {\n    if(noAutoDownload && !withoutPreloader && preloader) {\n      preloader.construct();\n      preloader.setManual();\n    }\n\n    const promise = getDownloadPromise();\n    const cacheContext = apiManagerProxy.getCacheContext(photo, size?.type);\n    if(\n      preloader &&\n      !cacheContext.downloaded &&\n      !withoutPreloader &&\n      canAttachPreloader\n    ) {\n      preloader.attach(container, false, promise);\n    }\n\n    noAutoDownload = undefined;\n\n    const renderPromise = promise.then(onLoad);\n    renderPromise.catch(noop);\n    return {download: promise, render: renderPromise};\n  };\n\n  if(preloader) {\n    preloader.setDownloadFunction(load);\n  }\n\n  if(cacheContext.downloaded) {\n    loadThumbPromise = loadPromise = (await load()).render;\n  } else {\n    if(!lazyLoadQueue) loadPromise = (await load()).render;\n    /* else if(noAutoDownload) {\n      preloader.construct();\n      preloader.setManual();\n      preloader.attach(container);\n    } */ else lazyLoadQueue.push({div: container, load: () => load().then(({download}) => download)});\n  }\n\n  if(loadPromises && loadThumbPromise) {\n    loadPromises.push(loadThumbPromise);\n  }\n\n  // const perf = performance.now();\n  // ! do not uncomment this, won't be able to modify element before the thumb is loaded\n  // await loadThumbPromise;\n  ret.loadPromises.thumb = loadThumbPromise;\n  ret.loadPromises.full = loadPromise || Promise.resolve();\n  ret.preloader = preloader;\n\n  // const elapsedTime = performance.now() - perf;\n  // if(elapsedTime > 4) {\n  //   console.log('wrapping photo thumb time', elapsedTime, photo, size);\n  // }\n\n  return ret;\n}\n\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport customProperties from '@helpers/dom/customProperties';\nimport textToSvgURL from '@helpers/textToSvgURL';\nimport rootScope from '@lib/rootScope';\nimport wrapPhoto from '@components/wrappers/photo';\n\nlet addedThemeListener = false;\nexport default function wrapAttachBotIcon({\n  doc,\n  element: iconElement,\n  size,\n  textColor,\n  strokeWidth\n}: {\n  doc: MyDocument,\n  element: HTMLElement,\n  size: number,\n  textColor: () => string,\n  strokeWidth: () => number\n}) {\n  iconElement.classList.add('is-external');\n\n  if(!addedThemeListener) {\n    addedThemeListener = true;\n\n    rootScope.addEventListener('theme_changed', () => {\n      const elements = document.querySelectorAll<HTMLElement>('.is-external');\n      elements.forEach((element) => {\n        const set = (element as any).set;\n        set?.(true);\n      });\n    });\n  }\n\n  const set = async(manual?: boolean) => {\n    const svg: SVGSVGElement = (iconElement as any).svg;\n    const color = customProperties.getProperty(textColor());\n    svg.querySelectorAll('path').forEach((path) => {\n      path.setAttributeNS(null, 'fill', color);\n      path.style.stroke = color;\n      path.style.strokeWidth = strokeWidth() + 'px';\n    });\n\n    const url = await textToSvgURL(svg.outerHTML);\n    if(!manual) {\n      return url;\n    }\n\n    ((iconElement as any).image as HTMLImageElement).src = url;\n  };\n\n  const originalPromise = wrapPhoto({\n    container: iconElement,\n    photo: doc,\n    boxWidth: size,\n    boxHeight: size,\n    withoutPreloader: true,\n    noFadeIn: true,\n    noBlur: true,\n    processUrl: async(url) => {\n      const text = await (await fetch(url)).text();\n      const doc = new DOMParser().parseFromString(text, 'image/svg+xml');\n      const svg = doc.firstElementChild as HTMLElement;\n      (iconElement as any).svg = svg;\n      (iconElement as any).set = set;\n      return set();\n    }\n  });\n\n  return originalPromise.then(async(ret) => {\n    iconElement.style.width = iconElement.style.height = '';\n    (iconElement as any).image = ret.images.full;\n    await ret.loadPromises.thumb;\n    return originalPromise;\n  });\n}\n","import wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport getAbbreviation from '@lib/richTextProcessor/getAbbreviation';\n\nexport default function wrapAbbreviation(str: string, onlyFirst?: boolean) {\n  const {text, entities} = getAbbreviation(str, onlyFirst);\n  return wrapEmojiText(text, undefined, entities);\n}\n","import {Chat, User} from '@layer';\nimport wrapAbbreviation from '@lib/richTextProcessor/wrapAbbreviation';\n\nexport default function getPeerInitials(peer: Chat | User) {\n  let str = '';\n  if(peer) {\n    str = (peer as Chat.chat).title ?? [\n      (peer as User.user).first_name,\n      (peer as User.user).last_name\n    ].filter(Boolean).join(' ');\n  }\n\n  return wrapAbbreviation(str);\n}\n","import {hexaToHsla} from '@helpers/color';\nimport {TOPIC_COLORS} from '@appManagers/constants';\nimport wrapAbbreviation from '@lib/richTextProcessor/wrapAbbreviation';\n\nlet svg: SVGSVGElement, span: HTMLElement, defs: HTMLElement;\nconst hadColors: Map<number, string> = new Map();\nexport default function topicAvatar(color: number, content: string) {\n  if(!svg) {\n    defs = document.getElementById('svg-defs') as HTMLElement;\n\n    const ns = 'http://www.w3.org/2000/svg';\n\n    svg = document.createElementNS(ns, 'svg');\n    svg.setAttributeNS(null, 'width', '26');\n    svg.setAttributeNS(null, 'height', '26');\n    svg.setAttributeNS(null, 'viewBox', '0 0 26 26');\n    svg.classList.add('topic-icon-svg');\n\n    const use = document.createElementNS(ns, 'use');\n    use.setAttributeNS(null, 'href', '#topic-icon');\n    svg.append(use);\n\n    span = document.createElement('span');\n    span.classList.add('topic-icon', 'avatar-like');\n\n    const contentSpan = document.createElement('span');\n    contentSpan.classList.add('topic-icon-content');\n    span.append(svg, contentSpan);\n  }\n\n  if(!color) {\n    console.error('NO TOPIC ICON COLOR!');\n    color = TOPIC_COLORS[0];\n  }\n\n  if(!content) {\n    console.error('NO TOPIC NAME!');\n    content = '';\n  }\n\n  const hex = color.toString(16);\n\n  const gradientId = `topic-icon-gradient-${color}`;\n  let strokeColor = hadColors.get(color);\n  if(!strokeColor) {\n    const {h, s, l, a} = hexaToHsla('#' + hex);\n    defs.insertAdjacentHTML('beforeend', `\n      <linearGradient id=\"${gradientId}\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\">\n        <stop style=\"stop-color: #${hex};\" offset=\"0%\" />\n        <stop style=\"stop-color: hsla(${h}, ${s}%, ${Math.max(0, l - 30)}%, ${a});\" offset=\"100%\" />\n      </linearGradient>\n    `);\n\n    hadColors.set(color, strokeColor = `hsla(${h}, ${s}%, ${Math.max(0, l - 40)}%, ${a})`);\n  }\n\n  const clone = span.cloneNode(true) as typeof span;\n  (clone.firstElementChild as HTMLElement).style.fill = `url(#${gradientId})`;\n  // (clone.firstElementChild as HTMLElement).style.stroke = `var(--peer-avatar-${color}-filled)`;\n  (clone.firstElementChild as HTMLElement).style.stroke = strokeColor;\n  clone.lastElementChild.append(wrapAbbreviation(content, true));\n  return clone;\n}\n","import {MessageEntity} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\n\nexport default function wrapCustomEmoji({\n  docIds,\n  loadPromises,\n  middleware,\n  lazyLoadQueue,\n  customEmojiSize,\n  animationGroup,\n  textColor\n}: {\n  docIds: DocId[],\n  loadPromises?: Promise<any>[]\n} & WrapSomethingOptions) {\n  const text = ' '.repeat(docIds.length);\n  const entities: MessageEntity[] = [];\n  docIds.forEach((docId, idx) => {\n    entities.push({\n      _: 'messageEntityCustomEmoji',\n      offset: idx,\n      length: 1,\n      document_id: docId\n    });\n  });\n\n  const wrapped = wrapRichText(text, {\n    entities,\n    loadPromises,\n    animationGroup,\n    customEmojiSize,\n    middleware,\n    lazyLoadQueue,\n    textColor\n  });\n\n  return wrapped;\n}\n\nexport function wrapCustomEmojiAwaited(options: Parameters<typeof wrapCustomEmoji>[0]) {\n  const loadPromises: Promise<any>[] = options.loadPromises ??= [];\n  const wrapped = wrapCustomEmoji(options);\n  return Promise.all(loadPromises).then(() => wrapped);\n}\n","import {InputGroupCall, Message, MessageAction} from '@layer';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport noop from '@helpers/noop';\n\nexport default function wrapJoinVoiceChatAnchor(message: Message.messageService) {\n  const action = message.action as\n    | MessageAction.messageActionInviteToGroupCall\n    | MessageAction.messageActionConferenceCall\n    | MessageAction.messageActionGroupCall;\n\n  // 1-on-1 chats with a User peer mean this is a TdE2E conference invite —\n  // legacy voice chats only live in chats/channels. Route the invite straight\n  // into `appImManager.joinConference` — the single conference-join policy entry\n  // point, which owns the support gate, the leave-current-call confirmation and\n  // the dead-link error UX — via `inputGroupCallInviteMessage`, the canonical\n  // form for joining from a service message (see tdesktop\n  // window_session_controller.cpp:993 and calls_group_call.cpp:4254).\n  if(message.peerId.isUser()) {\n    const inviteInput: InputGroupCall.inputGroupCallInviteMessage = {\n      _: 'inputGroupCallInviteMessage',\n      msg_id: getServerMessageId(message.mid)\n    };\n\n    const a = document.createElement('a');\n    a.classList.add('anchor-join-conference');\n    // Lazy import — keep it dynamic. `joinVoiceChatAnchor` sits on the message-\n    // render path, which is itself inside `appImManager`'s static import graph;\n    // a top-level `import appImManager` here closes a cycle that crashes page\n    // load with a `Row` TDZ (\"Cannot access 'Row' before initialization\").\n    // Resolving it at click-time (appImManager is long loaded by then) keeps the\n    // single conference-join entry point without the cycle. `.catch(noop)` drops\n    // the benign leave-current-call cancel — every join error is toasted inside.\n    attachClickEvent(a, () => {\n      import('@lib/appImManager').then(({default: appImManager}) => appImManager.joinConference(inviteInput)).catch(noop);\n    });\n    return a;\n  }\n\n  // Legacy voice/video chat in a group/channel — keep the existing tg://\n  // URL flow which routes through appImManager.joinGroupCall. Only the\n  // messageActionGroupCall / messageActionInviteToGroupCall variants carry\n  // an InputGroupCall on their `call` field; messageActionConferenceCall\n  // does not (and never appears for a chat peer in current servers).\n  const call = (action as MessageAction.messageActionInviteToGroupCall).call as InputGroupCall.inputGroupCall;\n  if(!call || call._ !== 'inputGroupCall') {\n    return document.createElement('span');\n  }\n\n  const {onclick, url} = wrapUrl(\n    `tg://voicechat?chat_id=${message.peerId.toChatId()}&id=${call.id}&access_hash=${call.access_hash}`\n  );\n  if(!onclick) {\n    return document.createElement('span');\n  }\n\n  const a = document.createElement('a');\n  a.href = url;\n  a.setAttribute('onclick', onclick + '(this)');\n  return a;\n}\n","export default function partition<T>(arr: T[], callback: (item: T, idx: number, arr: T[]) => boolean) {\n  const good: T[] = [], bad: T[] = [];\n  for(let i = 0, length = arr.length; i < length; ++i) {\n    const item = arr[i];\n    (callback(item, i, arr) ? good : bad).push(item);\n  }\n\n  return [good, bad];\n}\n","export default function htmlToDocumentFragment(html: string | DocumentFragment) {\n  if(html instanceof DocumentFragment) return html;\n  const template = document.createElement('template');\n  html = html.trim(); // Never return a text node of whitespace as the result\n  template.innerHTML = html;\n  return template.content;\n}\n","// credits to https://github.com/sindresorhus/escape-string-regexp/blob/master/index.js\nexport default function escapeRegExp(str: string) {\n  return str\n  .replace(/[|\\\\{}()[\\]^$+*?.]/g, '\\\\$&')\n  .replace(/-/g, '\\\\x2d');\n}\n","import {isRestricted, isSensitive} from '@helpers/restrictions';\nimport {Message} from '@layer';\n\nexport default function isMessageRestricted(message: Message.message) {\n  return !!(message.restriction_reason && isRestricted(message.restriction_reason));\n}\n\nexport function isMessageSensitive(message: Message) {\n  return (message._ === 'message' && message.restriction_reason != null && isSensitive(message.restriction_reason));\n}\n","import {TextWithEntities} from '@layer';\nimport mergeEntities from '@lib/richTextProcessor/mergeEntities';\nimport wrapMessageEntities from '@lib/richTextProcessor/wrapMessageEntities';\n\nexport default function wrapTextWithEntities(textWithEntities: TextWithEntities): TextWithEntities {\n  const {message, entities, myEntities} = wrapMessageEntities(textWithEntities.text, textWithEntities.entities);\n  const totalEntities = mergeEntities(entities, myEntities.filter((entity) => entity._ === 'messageEntityCustomEmoji' || entity._ === 'messageEntityEmoji'));\n  return {_: 'textWithEntities', text: message, entities: totalEntities};\n}\n","import {AckedResult} from '@lib/superMessagePort';\nimport {Modify} from '@types';\n\nexport default async function modifyAckedResult<T>(acked: AckedResult<T>): Promise<Modify<AckedResult<T>, {result: T | Promise<T>}>> {\n  return {\n    cached: acked.cached,\n    result: acked.cached ? await acked.result : acked.result\n  };\n}\n\nexport function modifyAckedPromise<T>(promise: Promise<AckedResult<T>>) {\n  return promise.then(modifyAckedResult);\n}\n","import {createMemo, createRoot, Accessor, onCleanup} from 'solid-js';\n\ntype T = Partial<{\n  count: number,\n  factory: () => any,\n  value: any,\n  dispose: () => void\n}>;\n\nconst cache = new Map<string, T>();\n\nexport default function useDynamicCachedValue<T>(cacheKey: Accessor<string>, factory: () => T): Accessor<T> {\n  return createMemo(() => {\n    const currentKey = cacheKey();\n    let entry = cache.get(currentKey);\n\n    if(!entry) {\n      entry = {count: 0, factory};\n      entry.value = createRoot((dispose) => {\n        entry.dispose = dispose;\n        return factory();\n      });\n      cache.set(currentKey, entry);\n    }\n\n    ++entry.count;\n\n    onCleanup(() => {\n      if(!--entry.count) {\n        entry.dispose();\n        cache.delete(currentKey);\n      }\n    });\n\n    return entry.value;\n  });\n}\n","import {createStore, reconcile, unwrap} from 'solid-js/store';\nimport {ChatFull, UserFull} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport useDynamicCachedValue from '@helpers/solid/useDynamicCachedValue';\nimport {onCleanup} from 'solid-js';\nimport {PEER_FULL_TTL} from '@appManagers/constants';\n\ntype PeerFull = ChatFull | UserFull;\n\nconst [state, setState] = createStore<{[peerId: PeerId]: PeerFull}>({});\nconst expirations = new Map<PeerId, number>();\n\nconst requestFullPeer = (peerId: PeerId, overwrite?: boolean) => {\n  rootScope.managers.appProfileManager.getProfileByPeerId(\n    peerId,\n    overwrite\n  ).then((fullPeer) => {\n    if(overwrite !== false) {\n      expirations.set(peerId, Date.now() + PEER_FULL_TTL);\n    }\n\n    setState(peerId, reconcile(fullPeer));\n  });\n};\n\nrootScope.addEventListener('peer_full_update', requestFullPeer);\n\nfunction _useFullPeer(peerId: PeerId) {\n  const fullPeer = () => state[peerId];\n\n  const expiration = expirations.get(peerId);\n  if(!expiration || !fullPeer()) {\n    requestFullPeer(peerId, false);\n  }\n\n  const delay = (expiration || 0) - Date.now();\n  const timeout = delay > 0 ? setTimeout(() => {\n    requestFullPeer(peerId, true);\n  }, delay) : 0;\n\n  const interval = setInterval(() => {\n    requestFullPeer(peerId, true);\n  }, PEER_FULL_TTL);\n\n  onCleanup(() => {\n    clearInterval(interval);\n    clearTimeout(timeout);\n  });\n\n  return fullPeer;\n}\n\nexport function useFullPeer(peerId: PeerId) {\n  return useDynamicCachedValue(\n    () => _useFullPeer.name + '-' + peerId,\n    () => _useFullPeer(peerId)\n  )();\n}\n\n/** Sync read of the cached fullPeer (no fetch, no reactive subscription). */\nexport function getCachedFullPeer(peerId: PeerId): PeerFull | undefined {\n  return unwrap(state[peerId]);\n}\n","import deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\n\nlet worker: Worker;\nlet promises: CancellablePromise<TranslatableLanguageISO>[];\n\nexport default function detectLanguage(text: string): Promise<TranslatableLanguageISO> {\n  if(!worker) {\n    worker = new Worker(new URL('./tinyld.worker.ts', import.meta.url), {type: 'module'});\n    worker.addEventListener('message', (e) => {\n      const {lang} = e.data;\n      const promise = promises.shift();\n      promise.resolve(lang);\n    });\n\n    promises = [];\n  }\n\n  const deferred = deferredPromise<TranslatableLanguageISO>();\n  promises.push(deferred);\n  worker.postMessage({text});\n  return deferred;\n}\n","import {createMemo, batch, untrack, createRoot, createEffect, on, Accessor} from 'solid-js';\nimport {createStore, SetStoreFunction} from 'solid-js/store';\nimport {Message} from '@layer';\nimport I18n from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport detectLanguage from '@lib/tinyld/detect';\nimport {useAppSettings} from '@stores/appSettings';\n\n// https://core.telegram.org/api/translation\nexport const MIN_TOTAL_PROCESSED_MESSAGES = 8;\nexport const MIN_FOREIGN_PERCENTAGE = 0.65;\n\ntype TT = {\n  messages: {[mid: number]: TranslatableLanguageISO},\n  languages: {[lang: string]: number},\n  language: TranslatableLanguageISO,\n  total: number,\n  totalForeign: number,\n  isFull?: boolean\n};\n\ntype T = {\n  [peerId: PeerId]: TT\n};\n\nlet state: T, setState: SetStoreFunction<T>, myLanguages: Accessor<Set<TranslatableLanguageISO>>;\nlet _createStore = () => {\n  _createStore = undefined;\n  [state, setState] = createStore({});\n\n  createRoot(() => {\n    const [appSettings] = useAppSettings();\n    myLanguages = createMemo(() => {\n      const myLanguages = new Set(\n        appSettings.translations.doNotTranslate.concat(\n          navigator.language.split('-')[0] as TranslatableLanguageISO,\n          I18n.langCodeNormalized()\n        )\n      );\n\n      return myLanguages;\n    });\n\n    createEffect(on(\n      myLanguages,\n      (myLanguages) => batch(() => {\n        for(const peerId in state) {\n          const current = state[peerId];\n          if(!current) {\n            continue;\n          }\n\n          let newTotalForeign = 0;\n          for(const lang in current.languages) {\n            if(!myLanguages.has(lang as TranslatableLanguageISO)) {\n              newTotalForeign += current.languages[lang];\n            }\n          }\n\n          setState(peerId.toPeerId(), 'totalForeign', newTotalForeign);\n        }\n      }),\n      {defer: true}\n    ));\n  });\n};\n\nfunction createEmpty(): TT {\n  return {\n    messages: {},\n    languages: {},\n    language: undefined,\n    total: 0,\n    totalForeign: 0\n  };\n}\n\nexport function setPeerLanguageLoaded(peerId: PeerId) {\n  _createStore?.();\n  if(!untrack(() => state[peerId])) {\n    setState(peerId, createEmpty());\n  }\n  setState(peerId, 'isFull', true);\n}\n\nexport async function processMessageForTranslation(peerId: PeerId, mid: number) {\n  _createStore?.();\n  if(state[peerId] && state[peerId].messages[mid]) {\n    return;\n  }\n\n  const message = apiManagerProxy.getMessageByPeer(peerId, mid);\n  const text = (message as Message.message)?.message;\n  if(!text) {\n    return;\n  }\n\n  const lang = await detectLanguage(text);\n  const isForeign = !myLanguages().has(lang);\n  batch(() => {\n    let previous = untrack(() => state[peerId]);\n    if(!previous) {\n      setState(peerId, previous = createEmpty());\n    } else if(previous.messages[mid]) {\n      return;\n    }\n\n    const newLanguageLength = (previous.languages[lang] ?? 0) + 1;\n    const newTotal = previous.total + 1;\n    const newTotalForeign = previous.totalForeign + (isForeign ? 1 : 0);\n    setState(peerId, 'messages', mid, lang);\n    setState(peerId, 'languages', lang, newLanguageLength);\n    setState(peerId, 'total', newTotal);\n    if(isForeign) setState(peerId, 'totalForeign', newTotalForeign);\n\n    const previousLanguage = previous.language;\n    if((previous.languages[previousLanguage] || 0) < newLanguageLength) {\n      setState(peerId, 'language', lang);\n    }\n  });\n}\n\nexport default function usePeerLanguage(peerId: () => PeerId, onlyIfForeign?: boolean) {\n  return createMemo(() => {\n    const _peerId = peerId();\n    if(!_peerId) {\n      return;\n    }\n\n    _createStore?.();\n    const current = state[_peerId];\n    if(current && current.total < MIN_TOTAL_PROCESSED_MESSAGES && !current.isFull) {\n      return;\n    }\n\n    if(onlyIfForeign && current && (current.totalForeign / current.total) < MIN_FOREIGN_PERCENTAGE) {\n      return;\n    }\n\n    return current?.language;\n  });\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\n\nconst [premium, setPremium] = createRoot(() => createSignal(rootScope.premium));\n\nconst onAuth = () => {\n  rootScope.managers.rootScope.getPremium().then(setPremium);\n};\n\nrootScope.addEventListener('premium_toggle', setPremium);\nif(rootScope.myId) {\n  onAuth();\n} else {\n  rootScope.addEventListener('user_auth', onAuth);\n}\n\nexport default function usePremium() {\n  return premium;\n}\n","import {useFullPeer} from '@stores/fullPeers';\nimport {createEffect, createMemo} from 'solid-js';\nimport usePeerLanguage from '@stores/peerLanguage';\nimport useDynamicCachedValue from '@helpers/solid/useDynamicCachedValue';\nimport I18n from '@lib/langPack';\nimport usePremium from '@stores/premium';\nimport {useAppSettings} from '@stores/appSettings';\nimport {usePeer} from '@stores/peers';\nimport {Chat} from '@layer';\nimport {useAppState} from '@stores/appState';\n\nfunction _usePeerTranslation(peerId: PeerId) {\n  const [appSettings, setAppSettings] = useAppSettings();\n  const [appState] = useAppState();\n\n  const fullPeer = useFullPeer(peerId);\n  const peer = usePeer(() => peerId);\n  const peerLanguage = usePeerLanguage(() => peerId, true);\n  const isPremium = usePremium();\n\n  const areTranslationsAvailable = (manual?: boolean) => {\n    if(appState.appConfig.freeze_since_date) {\n      return false;\n    }\n\n    const appConfig = appState?.appConfig;\n    if((manual ? appConfig?.translations_manual_enabled : appConfig?.translations_auto_enabled) !== 'enabled') {\n      return false;\n    }\n\n    return true;\n  };\n\n  const canTranslate = (manual?: boolean) => {\n    if(!areTranslationsAvailable(manual)) {\n      return false;\n    }\n\n    if(manual) {\n      return true;\n    }\n\n    return isPremium() || (!!peer() && !!(peer() as Chat.channel).pFlags.autotranslation);\n  };\n\n  const shouldShow = createMemo<boolean | undefined>(() => {\n    if(!canTranslate() || !peerLanguage() || !appSettings.translations.enabled) {\n      return;\n    }\n\n    const _fullPeer = fullPeer();\n    if(\n      (!_fullPeer || _fullPeer.pFlags.translations_disabled) ||\n      appSettings.translations.doNotTranslate.includes(peerLanguage())\n    ) {\n      return false;\n    }\n\n    return true;\n  });\n\n  const ret = {\n    peerLanguage,\n    language: (): TranslatableLanguageISO => (appSettings.translations.peers[peerId] || I18n.langCodeNormalized()) as any,\n    setLanguage: (lang: string) => setAppSettings('translations', 'peers', peerId, lang),\n    enabled: createMemo(() => !!(canTranslate() && appSettings.translations.enabled && appSettings.translations.enabledPeers[peerId]) && shouldShow()),\n    toggle: (enabled: boolean) => setAppSettings('translations', 'enabledPeers', peerId, enabled ? true : undefined),\n    shouldShow,\n    canTranslate,\n    areTranslationsAvailable\n  } as const;\n\n  createEffect(() => {\n    if(ret.shouldShow() === false && ret.enabled()) {\n      ret.toggle(false);\n    }\n  });\n\n  return ret;\n}\n\nexport default function usePeerTranslation(peerId: PeerId) {\n  return useDynamicCachedValue(() => usePeerTranslation.name + '-' + peerId, () => _usePeerTranslation(peerId))();\n}\n","import deferredPromise from '@helpers/cancellablePromise';\nimport {Middleware} from '@helpers/middleware';\nimport {modifyAckedPromise} from '@helpers/modifyAckedResult';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport {Message, TextWithEntities} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {createRoot, createSignal, createMemo, onCleanup, createEffect, Accessor, untrack} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport SuperIntersectionObserver from '@helpers/dom/superIntersectionObserver';\nimport {processMessageForTranslation} from '@stores/peerLanguage';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\n\nconst USE_OBSERVER = false;\n\nexport function TranslatableMessageTsx(props: {\n  peerId: PeerId,\n  message?: Message.message,\n  textWithEntities?: TextWithEntities,\n  richTextOptions?: Parameters<typeof wrapRichText>[1],\n  observer?: SuperIntersectionObserver,\n  observeElement?: HTMLElement,\n  container?: HTMLElement,\n  enabled?: boolean,\n  summarizing?: Accessor<boolean>,\n  onTranslation?: (callback: () => void) => void,\n  onTextWithEntities?: (textWithEntities: TextWithEntities) => TextWithEntities,\n  onFragment?: (fragment: DocumentFragment) => DocumentFragment,\n  onError?: (error: ApiError) => void\n}) {\n  const useObserver = USE_OBSERVER && props.observer && props.enabled === undefined;\n  const [visible, setVisible] = createSignal(!useObserver);\n  const wasVisible = createMemo<boolean>((prev) => prev || visible());\n  const [textWithEntities, setTextWithEntities] = createSignal<TextWithEntities>();\n  const translation = usePeerTranslation(props.peerId);\n  const deferred = deferredPromise<void>();\n  let originalText: TextWithEntities = props.textWithEntities;\n  let first = true, hadText = false;\n\n  const dontShowOriginalFirst = props.enabled;\n  const container = props.container ?? document.createElement('span');\n  container.classList.add('translatable-message');\n\n  if(props.message) {\n    processMessageForTranslation(props.peerId, props.message.mid);\n    originalText = {\n      _: 'textWithEntities',\n      text: props.message.message,\n      entities: props.message.totalEntities\n    };\n  }\n\n  if(props.richTextOptions?.loadPromises) {\n    props.richTextOptions.loadPromises.push(deferred);\n  }\n\n  const translate = (lang: string, onlyCache?: boolean) => {\n    return modifyAckedPromise(rootScope.managers.acknowledged.appTranslationsManager.translateText({\n      ...(props.message ? {\n        peerId: props.message.peerId,\n        mid: props.message.mid\n      } : {\n        text: props.textWithEntities\n      }),\n      lang,\n      onlyCache\n    }));\n  };\n\n  const summarizeText = (lang?: string) => {\n    return modifyAckedPromise(rootScope.managers.acknowledged.appTranslationsManager.summarizeText({\n      peerId: props.peerId,\n      mid: props.message.mid,\n      lang\n    }));\n  };\n\n  const setOriginalText = (loading?: boolean) => {\n    setTextWithEntities(originalText);\n    container.classList.toggle('text-loading', !!loading);\n  };\n\n  if(props.observer && props.observeElement && useObserver) {\n    const onVisible = (entry: IntersectionObserverEntry) => {\n      setVisible(entry.isIntersecting);\n    };\n\n    props.observer.observe(props.observeElement, onVisible);\n    onCleanup(() => {\n      props.observer.unobserve(props.observeElement, onVisible);\n    });\n  }\n\n  createEffect(async() => {\n    const middleware = createMiddleware().get();\n    const _first = first;\n    first = false;\n\n    const summarizing = props.summarizing?.();\n\n    // if the message is invisible and it's not the first time we're opening the chat\n    if(!summarizing && ((!translation.enabled() && !props.enabled) || (!wasVisible() && !_first))) {\n      setOriginalText();\n      return;\n    }\n\n    const r = await (summarizing ?\n      summarizeText(translation.enabled() ? translation.language() : undefined) :\n      translate(translation.language(), _first && useObserver));\n    if(!middleware()) {\n      return;\n    }\n\n    if(!r.cached) {\n      if(!dontShowOriginalFirst && !untrack(textWithEntities)) {\n        setOriginalText(true);\n      } else {\n        container.classList.add('text-loading');\n      }\n    } else if(!r.result) {\n      setOriginalText();\n      return;\n    }\n\n    try {\n      const textWithEntities$ = await r.result;\n      if(!middleware()) {\n        return;\n      }\n\n      if(!textWithEntities$) {\n        setOriginalText();\n        return;\n      }\n\n      setTextWithEntities(textWithEntities$);\n    } catch(err) {\n      if(!middleware()) {\n        return;\n      }\n\n      setOriginalText();\n      props.onError?.(err as ApiError);\n    }\n  });\n\n  createEffect(() => {\n    let r = textWithEntities();\n    if(!r) {\n      return;\n    }\n\n    if(props.onTextWithEntities) {\n      r = props.onTextWithEntities(r);\n    }\n\n    if(originalText !== r || !props.message) {\n      r = wrapTextWithEntities(r);\n    }\n\n    const middleware = createMiddleware().get();\n    const loadPromises: Promise<any>[] = [];\n    let wrapped = wrapRichText(r.text, {\n      ...(props.richTextOptions || {}),\n      loadPromises,\n      entities: r.entities\n    });\n\n    Promise.all(loadPromises).then(() => {\n      if(!middleware()) return;\n\n      const set = () => {\n        if(!middleware()) return;\n        deferred.resolve();\n\n        if(props.onFragment) {\n          wrapped = props.onFragment(wrapped);\n        }\n\n        container.replaceChildren(wrapped);\n        if(hadText || dontShowOriginalFirst) container.classList.remove('text-loading');\n        hadText = true;\n      };\n\n      if(hadText && props.onTranslation) {\n        props.onTranslation(set);\n        return;\n      }\n\n      set();\n    });\n  });\n\n  return container;\n}\n\nexport default function TranslatableMessage(props: Parameters<typeof TranslatableMessageTsx>[0] & {middleware: Middleware}) {\n  return createRoot((dispose) => {\n    props.middleware.onDestroy(dispose);\n    return TranslatableMessageTsx(props);\n  });\n}\n","import type {MyMessage} from '@appManagers/appMessagesManager';\nimport wrapMessageActionTextNewUnsafe from '@components/wrappers/messageActionTextNewUnsafe';\n\nexport type WrapMessageActionTextOptions = {\n  message: MyMessage,\n  plain?: boolean,\n  noLinks?: boolean,\n  noTextFormat?: boolean\n} & WrapSomethingOptions;\n\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions & {plain: true}): Promise<string>;\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions & {plain?: false}): Promise<HTMLElement>;\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions): Promise<string | HTMLElement>;\n\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions): Promise<string | HTMLElement> {\n  try {\n    return await wrapMessageActionTextNewUnsafe(options);\n  } catch(err) {\n    console.error('wrapMessageActionTextNewUnsafe error:', err);\n    return options.plain ? '' : document.createElement('span');\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// Inline math (`$x$`) is carried through the markdown / RichText pipeline as a base64-encoded source\n// wrapped in STX (\\x02) sentinels. base64 contains no markdown-special characters, so the LaTeX\n// source survives the emphasis / escape passes and parseMarkdown untouched; the IV later decodes &\n// renders it with Temml (see instantViewMath). Mirrors how WebA (telegram-tt) renders `textMath`.\n\nconst STX = '\\x02';\n\nexport const MATH_MARKER_RE = /\\x02([A-Za-z0-9+/=]+)\\x02/g;\n\nfunction toBase64(s: string): string {\n  const bytes = new TextEncoder().encode(s);\n  let bin = '';\n  for(let i = 0; i < bytes.length; ++i) {\n    bin += String.fromCharCode(bytes[i]);\n  }\n  return btoa(bin);\n}\n\nfunction fromBase64(b64: string): string {\n  const bin = atob(b64);\n  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));\n  return new TextDecoder().decode(bytes);\n}\n\nexport function encodeInlineMath(source: string): string {\n  return STX + toBase64(source) + STX;\n}\n\nexport function decodeInlineMath(encoded: string): string {\n  return fromBase64(encoded);\n}\n","import {RichText, TextWithEntities, MessageEntity} from '@layer';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\nimport {encodeInlineMath} from '@helpers/math/mathMarker';\n\ntype Options = {\n  webPageId: Long,\n  url: string,\n  randomId: string\n};\n\nexport default function wrapTelegramRichText(\n  richText: RichText,\n  options?: Options\n): TextWithEntities {\n  const textWithEntities = wrapTextWithEntities(processRichText(richText, options));\n\n  // if(!options) {\n  //   return textWithEntities;\n  // }\n\n  // * convert textUrl to textAnchor\n  // textWithEntities.entities.forEach((entity) => {\n  //   if(entity._ === 'messageEntityTextUrl') {\n  //     try {\n  //       let url = new URL(entity.url);\n  //       if(url.protocol !== 'tg:' || url.host !== 'iv') {\n  //         return;\n  //       }\n\n  //       url = new URL(decodeURIComponent(url.searchParams.get('url')));\n  //       const hash = url.hash;\n  //       url.hash = '';\n  //       if(url.toString() === options.url) {\n  //         debugger;\n  //       }\n  //     } catch(err) {}\n  //   }\n  // });\n\n  return textWithEntities;\n}\n\nfunction processRichText(richText: RichText, options: Options): TextWithEntities {\n  switch(richText._) {\n    case 'textEmpty':\n      return {\n        _: 'textWithEntities',\n        text: '',\n        entities: []\n      };\n    case 'textPlain':\n      return {\n        _: 'textWithEntities',\n        text: richText.text,\n        entities: []\n      };\n    case 'textConcat': {\n      let text = '';\n      const entities: MessageEntity[] = [];\n      for(const part of richText.texts) {\n        const partResult = processRichText(part, options);\n        for(const entity of partResult.entities) {\n          entities.push({\n            ...entity,\n            offset: entity.offset + text.length\n          });\n        }\n        text += partResult.text;\n      }\n      return {\n        _: 'textWithEntities',\n        text,\n        entities\n      };\n    }\n    case 'textBold':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBold',\n        offset,\n        length\n      }), options);\n    case 'textItalic':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityItalic',\n        offset,\n        length\n      }), options);\n    case 'textUnderline':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityUnderline',\n        offset,\n        length\n      }), options);\n    case 'textStrike':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityStrike',\n        offset,\n        length\n      }), options);\n    case 'textFixed':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityCode',\n        offset,\n        length\n      }), options);\n    case 'textUrl':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityTextUrl',\n        offset,\n        length,\n        url: richText.webpage_id ?\n          'tg://iv?url=' + encodeURIComponent(richText.url) :\n          richText.url,\n        safe: !!richText.webpage_id\n      }), options);\n    case 'textEmail':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityEmail',\n        offset,\n        length\n      }), options);\n    case 'textMarked':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityHighlight',\n        offset,\n        length\n      }), options);\n    case 'textPhone':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityPhone',\n        offset,\n        length\n      }), options);\n    case 'textMath':\n      // Carry inline math as a base64 marker (like master's markdown path) so the IV's\n      // RichTextRenderer -> hydrateInlineMath() renders it with Temml. Consumers that want plain\n      // text (e.g. reply/search summaries) decode the marker back to the raw LaTeX source.\n      return {\n        _: 'textWithEntities',\n        text: encodeInlineMath(richText.source),\n        entities: []\n      };\n    case 'textImage':\n      return wrapEntity({_: 'textPlain', text: '\\x01'}, (offset, length) => ({\n        _: 'messageEntityCustomEmoji',\n        document_id: richText.document_id,\n        offset,\n        length,\n        w: richText.w,\n        h: richText.h\n      }), options);\n    case 'textCustomEmoji':\n      return wrapEntity({_: 'textPlain', text: richText.alt || '\\x01'}, (offset, length) => ({\n        _: 'messageEntityCustomEmoji',\n        document_id: richText.document_id,\n        offset,\n        length\n      }), options);\n    case 'textSpoiler':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySpoiler',\n        offset,\n        length\n      }), options);\n    case 'textMention':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityMention',\n        offset,\n        length\n      }), options);\n    case 'textHashtag':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityHashtag',\n        offset,\n        length\n      }), options);\n    case 'textBotCommand':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBotCommand',\n        offset,\n        length\n      }), options);\n    case 'textCashtag':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityCashtag',\n        offset,\n        length\n      }), options);\n    case 'textAutoUrl':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityUrl',\n        offset,\n        length\n      }), options);\n    case 'textAutoEmail':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityEmail',\n        offset,\n        length\n      }), options);\n    case 'textAutoPhone':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityPhone',\n        offset,\n        length\n      }), options);\n    case 'textBankCard':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBankCard',\n        offset,\n        length\n      }), options);\n    case 'textMentionName':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityMentionName',\n        offset,\n        length,\n        user_id: richText.user_id\n      }), options);\n    case 'textDate':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityFormattedDate',\n        pFlags: richText.pFlags,\n        offset,\n        length,\n        date: richText.date\n      }), options);\n    case 'textSubscript':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySubscript',\n        offset,\n        length\n      } as any), options);\n    case 'textSuperscript':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySuperscript',\n        offset,\n        length\n      } as any), options);\n    case 'textAnchor': {\n      // const url = options?.url && new URL(options.url);\n      // if(url) url.hash = richText.name;\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityAnchor',\n        offset,\n        length,\n        name: (options?.randomId || '') + richText.name\n        // url: 'tg://iv?' + (url ?\n        //   'url=' + encodeURIComponent(url.toString()) :\n        //   'anchor=' + encodeURIComponent('#' + richText.name)\n        // )\n      }), options);\n    }\n    default:\n      return {\n        _: 'textWithEntities',\n        text: '',\n        entities: []\n      };\n  }\n}\n\nfunction wrapEntity(\n  innerRichText: RichText,\n  createEntity: (offset: number, length: number) => MessageEntity,\n  options: Options\n): TextWithEntities {\n  const innerResult = processRichText(innerRichText, options);\n  const entity = createEntity(0, innerResult.text.length);\n  return {\n    _: 'textWithEntities',\n    text: innerResult.text,\n    entities: [entity, ...innerResult.entities]\n  };\n}\n","import {MessageEntity, Page, PageBlock, PageCaption, RichMessage, RichText, TextWithEntities} from '@layer';\nimport wrapTelegramRichText from '@lib/richTextProcessor/wrapTelegramRichText';\nimport {MATH_MARKER_RE, decodeInlineMath} from '@helpers/math/mathMarker';\n\nconst emptyRichText: RichText = {_: 'textEmpty'};\n\ntype Summary = TextWithEntities.textWithEntities;\n\nexport function richMessageToPage(richMessage: RichMessage): Page.page {\n  return {\n    _: 'page',\n    pFlags: {\n      rtl: richMessage.pFlags.rtl,\n      part: richMessage.pFlags.part\n    },\n    url: '',\n    blocks: richMessage.blocks || [],\n    photos: richMessage.photos || [],\n    documents: richMessage.documents || [],\n    views: 0\n  };\n}\n\nexport function isRichMessagePart(richMessage: RichMessage) {\n  return !!richMessage.pFlags.part;\n}\n\nexport function flattenRichMessageSummary(richMessage?: RichMessage, maxLength = 100): Summary {\n  if(!richMessage) {\n    return emptySummary();\n  }\n\n  const summary = emptySummary();\n  appendBlocks(summary, richMessage.blocks || []);\n\n  if(maxLength && summary.text.length > maxLength) {\n    // Hard-truncate to maxLength. Don't use limitSymbols() here: it trims *leading* whitespace,\n    // which would shift every entity offset out of alignment (and its soft +10 slack means it\n    // wouldn't actually cut at maxLength). trimEnd() only can't move earlier offsets. Clamp entities\n    // to the cut boundary (before the ellipsis) so none spills over.\n    const truncated = summary.text.slice(0, maxLength).trimEnd();\n    summary.text = truncated + '...';\n    summary.entities = summary.entities.filter((entity) => entity.offset < truncated.length);\n    for(const entity of summary.entities) {\n      entity.length = Math.min(entity.length, truncated.length - entity.offset);\n    }\n  }\n\n  return summary;\n}\n\nexport function flattenRichMessageSummaryText(richMessage?: RichMessage, maxLength?: number) {\n  return flattenRichMessageSummary(richMessage, maxLength).text;\n}\n\nfunction emptySummary(): Summary {\n  return {\n    _: 'textWithEntities',\n    text: '',\n    entities: []\n  };\n}\n\nfunction appendBlocks(summary: Summary, blocks: PageBlock[], prefix = '') {\n  for(const block of blocks) {\n    appendBlock(summary, block, prefix);\n  }\n}\n\nfunction appendBlock(summary: Summary, block: PageBlock, prefix = '') {\n  switch(block._) {\n    case 'pageBlockTitle':\n    case 'pageBlockSubtitle':\n    case 'pageBlockHeader':\n    case 'pageBlockSubheader':\n    case 'pageBlockParagraph':\n    case 'pageBlockPreformatted':\n    case 'pageBlockFooter':\n    case 'pageBlockKicker':\n    case 'pageBlockHeading1':\n    case 'pageBlockHeading2':\n    case 'pageBlockHeading3':\n    case 'pageBlockHeading4':\n    case 'pageBlockHeading5':\n    case 'pageBlockHeading6':\n    case 'pageBlockThinking':\n      appendRichTextLine(summary, block.text, prefix);\n      break;\n    case 'pageBlockMath':\n      appendPlainLine(summary, block.source, prefix);\n      break;\n    case 'pageBlockBlockquote':\n    case 'pageBlockPullquote':\n      appendRichTextLine(summary, block.text, prefix);\n      appendRichTextLine(summary, block.caption, prefix);\n      break;\n    case 'pageBlockBlockquoteBlocks':\n      appendBlocks(summary, block.blocks, prefix);\n      appendRichTextLine(summary, block.caption, prefix);\n      break;\n    case 'pageBlockList':\n      block.items.forEach((item) => {\n        const itemPrefix = prefix + '- ';\n        if(item._ === 'pageListItemText') {\n          appendRichTextLine(summary, item.text, itemPrefix);\n        } else {\n          appendBlocks(summary, item.blocks, itemPrefix);\n        }\n      });\n      break;\n    case 'pageBlockOrderedList':\n      block.items.forEach((item, index) => {\n        const start = block.start ?? (block.pFlags.reversed ? block.items.length : 1);\n        const num = item.num || `${block.pFlags.reversed ? start - index : start + index}`;\n        const itemPrefix = `${prefix}${num}. `;\n        if(item._ === 'pageListOrderedItemText') {\n          appendRichTextLine(summary, item.text, itemPrefix);\n        } else {\n          appendBlocks(summary, item.blocks, itemPrefix);\n        }\n      });\n      break;\n    case 'pageBlockTable':\n      appendRichTextLine(summary, block.title, prefix);\n      for(const row of block.rows) {\n        appendTextWithEntitiesLine(summary, joinCells(row.cells.map((cell) => cell.text || emptyRichText)), prefix);\n      }\n      break;\n    case 'pageBlockDetails':\n      appendRichTextLine(summary, block.title, prefix);\n      appendBlocks(summary, block.blocks, prefix);\n      break;\n    case 'pageBlockPhoto':\n      appendCaptionOrFallback(summary, block.caption, 'Photo', prefix);\n      break;\n    case 'pageBlockVideo':\n      appendCaptionOrFallback(summary, block.caption, 'Video', prefix);\n      break;\n    case 'pageBlockAudio':\n      appendCaptionOrFallback(summary, block.caption, 'Audio', prefix);\n      break;\n    case 'pageBlockMap':\n      appendCaptionOrFallback(summary, block.caption, 'Location', prefix);\n      break;\n    case 'pageBlockEmbed':\n    case 'pageBlockEmbedPost':\n      appendCaptionOrFallback(summary, block.caption, 'Embed', prefix);\n      break;\n    case 'pageBlockCollage':\n    case 'pageBlockSlideshow':\n      appendCaptionOrFallback(summary, block.caption, 'Media', prefix);\n      if(isSummaryEmpty(summary)) {\n        appendBlocks(summary, block.items, prefix);\n      }\n      break;\n    case 'pageBlockCover':\n      appendBlock(summary, block.cover, prefix);\n      break;\n    case 'pageBlockRelatedArticles':\n      appendRichTextLine(summary, block.title, prefix);\n      for(const article of block.articles) {\n        appendPlainLine(summary, article.title, prefix);\n        appendPlainLine(summary, article.description, prefix);\n      }\n      break;\n    case 'pageBlockUnsupported':\n      appendPlainLine(summary, 'Unsupported block', prefix);\n      break;\n    case 'pageBlockDivider':\n    case 'pageBlockAnchor':\n    case 'pageBlockChannel':\n      break;\n    default:\n      appendPlainLine(summary, `Unsupported block: ${(block as PageBlock)._}`, prefix);\n      break;\n  }\n}\n\nfunction appendCaptionOrFallback(summary: Summary, caption: PageCaption, fallback: string, prefix = '') {\n  const before = summary.text;\n  appendRichTextLine(summary, caption?.text || emptyRichText, prefix);\n  if(summary.text === before) {\n    appendPlainLine(summary, fallback, prefix);\n  }\n}\n\nfunction appendRichTextLine(summary: Summary, richText: RichText, prefix = '') {\n  appendTextWithEntitiesLine(summary, wrapSummaryRichText(richText), prefix);\n}\n\n// wrapTelegramRichText carries inline math (`textMath`) as an opaque `\\x02<base64>\\x02` marker for the\n// IV's Temml renderer. Summaries are plain text, so decode markers back to the raw LaTeX source and\n// shift any following entities by the length delta so their offsets stay aligned.\nfunction wrapSummaryRichText(richText: RichText): TextWithEntities {\n  const textWithEntities = wrapTelegramRichText(richText);\n  const {text} = textWithEntities;\n  if(!text.includes('\\x02')) {\n    return textWithEntities;\n  }\n\n  let out = '';\n  let last = 0;\n  const shifts: Array<{from: number, delta: number}> = [];\n  for(const match of text.matchAll(MATH_MARKER_RE)) {\n    const source = decodeInlineMath(match[1]);\n    out += text.slice(last, match.index) + source;\n    const markerEnd = match.index + match[0].length;\n    shifts.push({from: markerEnd, delta: source.length - match[0].length});\n    last = markerEnd;\n  }\n  out += text.slice(last);\n\n  const shiftOffset = (offset: number) => {\n    let delta = 0;\n    for(const shift of shifts) {\n      if(offset >= shift.from) delta += shift.delta;\n    }\n    return offset + delta;\n  };\n\n  return {\n    _: 'textWithEntities',\n    text: out,\n    entities: (textWithEntities.entities || []).map((entity) => ({...entity, offset: shiftOffset(entity.offset)}))\n  };\n}\n\nfunction appendTextWithEntitiesLine(summary: Summary, textWithEntities: TextWithEntities, prefix = '') {\n  if(!textWithEntities.text.trim()) {\n    return;\n  }\n\n  const lineStart = summary.text ? summary.text.length + 1 : 0;\n  if(summary.text) {\n    summary.text += '\\n';\n  }\n\n  summary.text += prefix + textWithEntities.text;\n  appendEntities(summary, textWithEntities.entities, lineStart + prefix.length);\n}\n\nfunction appendPlainLine(summary: Summary, text: string, prefix = '') {\n  if(!text?.trim()) {\n    return;\n  }\n\n  appendTextWithEntitiesLine(summary, {\n    _: 'textWithEntities',\n    text,\n    entities: []\n  }, prefix);\n}\n\nfunction appendEntities(summary: Summary, entities: MessageEntity[], offset: number) {\n  for(const entity of entities || []) {\n    summary.entities.push({\n      ...entity,\n      offset: entity.offset + offset\n    });\n  }\n}\n\nfunction joinCells(cells: RichText[]): TextWithEntities {\n  const joined = emptySummary();\n  for(const [index, cell] of cells.entries()) {\n    const textWithEntities = wrapSummaryRichText(cell);\n    const offset = joined.text.length + (index ? 1 : 0);\n    if(index) {\n      joined.text += '\\t';\n    }\n\n    joined.text += textWithEntities.text;\n    appendEntities(joined, textWithEntities.entities, offset);\n  }\n\n  return joined;\n}\n\nfunction isSummaryEmpty(summary: Summary) {\n  return !summary.text.trim();\n}\n","import partition from '@helpers/array/partition';\nimport assumeType from '@helpers/assumeType';\nimport {formatDate} from '@helpers/date';\nimport htmlToDocumentFragment from '@helpers/dom/htmlToDocumentFragment';\nimport {getRestrictionReason} from '@helpers/restrictions';\nimport escapeRegExp from '@helpers/string/escapeRegExp';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport {Message, DocumentAttribute, DraftMessage, MessageMedia, Document, Photo} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyDraftMessage} from '@appManagers/appDraftsManager';\nimport {MyMessage} from '@appManagers/appMessagesManager';\nimport isMessageRestricted from '@appManagers/utils/messages/isMessageRestricted';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {LangPackKey, i18n, UNSUPPORTED_LANG_PACK_KEY, FormatterArguments} from '@lib/langPack';\nimport {SERVICE_PEER_ID, VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport parseEntities from '@lib/richTextProcessor/parseEntities';\nimport sortEntities from '@lib/richTextProcessor/sortEntities';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapPlainText from '@lib/richTextProcessor/wrapPlainText';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\nimport rootScope from '@lib/rootScope';\nimport {Modify} from '@types';\nimport Icon from '@components/icon';\nimport TranslatableMessage from '@components/translatableMessage';\nimport wrapMessageActionTextNew, {WrapMessageActionTextOptions} from '@components/wrappers/messageActionTextNew';\nimport {wrapMessageGiveawayResults} from '@components/wrappers/messageActionTextNewUnsafe';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {flattenRichMessageSummary} from '@lib/richMessage';\n\nexport type WrapMessageForReplyOptions = Modify<WrapMessageActionTextOptions, {\n  message: MyMessage | MyDraftMessage\n}> & {\n  text?: string,\n  usingMids?: number[],\n  highlightWord?: string,\n  withoutMediaType?: boolean,\n  canTranslate?: boolean\n};\n\nexport default async function wrapMessageForReply<T extends WrapMessageForReplyOptions>(\n  options: T\n): Promise<T['plain'] extends true ? string : DocumentFragment> {\n  options.text ??= (options.message as Message.message).message;\n  if(!options.plain && options.highlightWord) {\n    options.highlightWord = options.highlightWord.trim();\n  }\n\n  const {message, usingMids, plain, highlightWord, withoutMediaType} = options;\n\n  const parts: (Node | string)[] = [];\n\n  let hasGroupedKey = false;\n  const addPart = (langKey: LangPackKey, part?: string | HTMLElement | DocumentFragment, args?: FormatterArguments) => {\n    if(langKey) {\n      if(part === undefined && hasGroupedKey) {\n        return;\n      }\n\n      part = plain ? I18n.format(langKey, true, args) : i18n(langKey, args);\n    }\n\n    if(plain) {\n      parts.push(part);\n    } else {\n      const el = document.createElement('span');\n      if(typeof(part) === 'string') el.innerHTML = part;\n      else el.append(part);\n      parts.push(el);\n    }\n  };\n\n  const managers = options.managers || rootScope.managers;\n  const appMessagesManager = managers.appMessagesManager;\n\n  const getMyId = () => options.managers ? options.managers.rootScope.getMyId() : rootScope.myId;\n\n  const isRestricted = isMessageRestricted(message as any);\n  const isSelfDestructingMedia = !!((message as Message.message).media as MessageMedia.messageMediaPhoto)?.ttl_seconds;\n\n  const someRichTextOptions: WrapRichTextOptions = {\n    ...options,\n    noLinebreaks: true,\n    noLinks: true,\n    noTextFormat: true\n  };\n\n  let entities = (message as Message.message).totalEntities ?? (message as DraftMessage.draftMessage).entities;\n  const applyRichMessageSummary = () => {\n    const richMessage = (message as Message.message).rich_message;\n    if(!richMessage) {\n      return false;\n    }\n\n    const summary = flattenRichMessageSummary(richMessage);\n    options.text = summary.text;\n    entities = summary.entities;\n    return true;\n  };\n\n  if((message as Message.message).media && !isRestricted) {\n    assumeType<Message.message>(message);\n    let usingFullGrouped = true;\n    if(message.grouped_id) {\n      if(usingMids) {\n        const mids = await appMessagesManager.getMidsByMessage(message);\n        if(usingMids.length === mids.length) {\n          for(const mid of mids) {\n            if(!usingMids.includes(mid)) {\n              usingFullGrouped = false;\n              break;\n            }\n          }\n        } else {\n          usingFullGrouped = false;\n        }\n      }\n\n      if(usingFullGrouped) {\n        const groupedText = await appMessagesManager.getGroupedText(message.grouped_id);\n        options.text = groupedText?.message || '';\n        entities = groupedText?.totalEntities || [];\n\n        if(!withoutMediaType) {\n          addPart('AttachAlbum');\n          hasGroupedKey = true;\n        }\n      }\n    } else {\n      usingFullGrouped = false;\n    }\n\n    async function addSelfDestructingMediaPart(\n      langPackKeyPart: 'Photo' | 'Video' | 'Voice' | 'Round',\n      media: Photo | Document\n    ) {\n      const {out} = (message as Message.message).pFlags;\n      addPart(\n        `SelfDestructingOnMobile.${langPackKeyPart}${!media ? '.Expired' : (out ? '.You' : '')}`,\n        undefined,\n        [!out && await wrapPeerTitle({peerId: (message as Message.message).fromId})]\n      );\n      options.text = '';\n      entities = [];\n    }\n\n    let i = 1;\n    if((!usingFullGrouped && !withoutMediaType) || !options.text || isSelfDestructingMedia) {\n      const media = message.media;\n      switch(media?._) {\n        case 'messageMediaPhoto':\n          if(isSelfDestructingMedia) {\n            await addSelfDestructingMediaPart('Photo', media.photo);\n          } else {\n            addPart('AttachPhoto');\n          }\n          break;\n        case 'messageMediaDice':\n          addPart(undefined, plain ? media.emoticon : wrapEmojiText(media.emoticon));\n          break;\n        case 'messageMediaVenue': {\n          options.text = media.title;\n          addPart('AttachLocation');\n          break;\n        }\n        case 'messageMediaGeo':\n          addPart('AttachLocation');\n          break;\n        case 'messageMediaGeoLive':\n          addPart('AttachLiveLocation');\n          break;\n        case 'messageMediaPoll':\n          const pre = '📊' + ' ';\n          if(plain) {\n            const f = pre + media.poll.question.text;\n            addPart(undefined, f);\n          } else {\n            const textWithEntities = wrapTextWithEntities(media.poll.question);\n            const fragment = wrapRichText(textWithEntities.text, {...someRichTextOptions, entities: textWithEntities.entities});\n            fragment.prepend(wrapEmojiText(pre));\n            addPart(undefined, fragment);\n          }\n          break;\n        case 'messageMediaContact':\n          addPart('AttachContact');\n          break;\n        case 'messageMediaGame': {\n          const f = '🎮' + ' ' + media.game.title;\n          addPart(undefined, plain ? f : wrapEmojiText(f));\n          break;\n        }\n        case 'messageMediaDocument': {\n          const document = media.document as MyDocument;\n\n          if(document?.type === 'video' || media.pFlags.video) {\n            if(isSelfDestructingMedia) {\n              await addSelfDestructingMediaPart('Video', document);\n            } else {\n              addPart('AttachVideo');\n            }\n          } else if(document?.type === 'voice' || media.pFlags.voice) {\n            if(isSelfDestructingMedia) {\n              await addSelfDestructingMediaPart('Voice', document);\n            } else {\n              addPart('AttachAudio');\n            }\n          } else if(document?.type === 'round' || media.pFlags.round) {\n            if(isSelfDestructingMedia) {\n              await addSelfDestructingMediaPart('Round', document);\n            } else {\n              addPart('AttachRound');\n            }\n          } else if(document.type === 'gif') {\n            addPart('AttachGif');\n          } else if(document.type === 'sticker') {\n            const i = parts.length;\n            if(document.stickerEmojiRaw) {\n              const f = document.stickerEmojiRaw + ' ';\n              addPart(undefined, plain ? f : wrapEmojiText(f));\n            }\n\n            addPart('AttachSticker');\n\n            // will combine two parts into one\n            const p = parts.splice(i, 2);\n            if(plain) parts.push((p[0] as string) + (p[1] ? p[1] as string : ''));\n            else {\n              const span = window.document.createElement('span');\n              span.append(...p);\n              parts.push(span);\n            }\n\n            options.text = '';\n          } else if(document.type === 'audio') {\n            const attribute = document.attributes.find((attribute) => attribute._ === 'documentAttributeAudio' && (attribute.title || attribute.performer)) as DocumentAttribute.documentAttributeAudio;\n            const f = '🎵' + ' ' + (attribute ? [attribute.title, attribute.performer].filter(Boolean).join(' - ') : document.file_name);\n            addPart(undefined, plain ? f : wrapEmojiText(f));\n          } else {\n            addPart(undefined, plain ? document.file_name : wrapEmojiText(document.file_name));\n          }\n\n          break;\n        }\n\n        case 'messageMediaInvoice': {\n          if(media.extended_media?._ === 'messageExtendedMediaPreview') {\n            addPart(undefined, plain ? media.description : wrapEmojiText(media.description));\n          } else {\n            addPart(undefined, plain ? media.title : wrapEmojiText(media.title));\n          }\n\n          break;\n        }\n\n        case 'messageMediaUnsupported': {\n          if(applyRichMessageSummary()) {\n            break;\n          }\n\n          addPart(UNSUPPORTED_LANG_PACK_KEY);\n          break;\n        }\n\n        case 'messageMediaStory': {\n          if(media.pFlags.via_mention) {\n            const storyPeerId = getPeerId(media.peer);\n            const isMyStory = storyPeerId === await getMyId();\n            addPart(\n              isMyStory ? 'StoryMentionYou' : 'StoryMention',\n              undefined,\n              [await wrapPeerTitle({peerId: isMyStory ? message.peerId : storyPeerId, plainText: plain})]\n            )\n          } else {\n            addPart('Story');\n          }\n\n          break;\n        }\n\n        // @ts-ignore\n        case 'inputMediaWebPage':\n        case 'messageMediaPhotoExternal':\n        case 'messageMediaDocumentExternal':\n        case 'messageMediaWebPage': {\n          break;\n        }\n\n        case 'messageMediaGiveaway': {\n          const date = formatDate(new Date(media.until_date * 1000));\n          addPart('Giveaway.ToBeSelectedFull', undefined, [i18n('Giveaway.ToBeSelected', [media.quantity, plain ? date.textContent : date])]);\n          break;\n        }\n\n        case 'messageMediaGiveawayResults': {\n          const {langPackKey, args} = wrapMessageGiveawayResults(media, plain);\n          addPart(langPackKey, undefined, args);\n          break;\n        }\n\n        case 'messageMediaPaidMedia': {\n          const extendedMedia = media.extended_media;\n          const [photos, videos] = partition(extendedMedia, (media) => {\n            if(media._ === 'messageExtendedMediaPreview') {\n              return media.video_duration === undefined;\n            }\n\n            return media.media._ === 'messageMediaPhoto';\n          });\n\n          if(!plain) {\n            i += 2;\n            addPart(undefined, Icon('star', 'xtr-icon'));\n            addPart(undefined, ' ');\n          }\n\n          const length = photos.length + videos.length;\n          if(length < 2) {\n            addPart(photos.length ? 'AttachPhoto' : 'AttachVideo');\n            break;\n          }\n\n          addPart(\n            photos.length && videos.length ? 'Media' : photos.length ? 'Photos' : 'Videos', undefined,\n            [length]\n          );\n          break;\n        }\n\n        case 'messageMediaToDo': {\n          addPart(undefined, plain ? media.todo.title.text : wrapEmojiText(media.todo.title.text, false, media.todo.title.entities));\n          break;\n        }\n\n        default:\n          if(applyRichMessageSummary()) {\n            break;\n          }\n\n          addPart(UNSUPPORTED_LANG_PACK_KEY);\n          options.text = '';\n          // messageText += media._;\n          // /////appMessagesManager.log.warn('Got unknown media type!', message);\n          break;\n      }\n    }\n\n    const length = parts.length;\n    for(; i < length; i += 2) {\n      parts.splice(i, 0, ', ');\n    }\n\n    if(options.text && length) {\n      parts.push(', ');\n    }\n  }\n\n  if((message as Message.messageService).action) {\n    const actionWrapped = await wrapMessageActionTextNew({\n      ...(options as Modify<typeof options, {message: Message.messageService}>),\n      noLinks: true,\n      noTextFormat: true\n    });\n\n    if(actionWrapped) {\n      addPart(undefined, actionWrapped);\n    }\n  }\n\n  if(isRestricted) {\n    options.text = getRestrictionReason((message as Message.message).restriction_reason).text;\n    entities = [];\n  }\n\n  if(options.text) {\n    options.text = limitSymbols(options.text, 100);\n\n    entities ??= parseEntities(options.text);\n\n    if(plain) {\n      parts.push(wrapPlainText(options.text, entities));\n    } else {\n      // let entities = parseEntities(text.replace(/\\n/g, ' '));\n\n      if(highlightWord) {\n        let found = false;\n        let match: any;\n        const regExp = new RegExp(escapeRegExp(highlightWord), 'gi');\n        entities = entities.slice(); // fix leaving highlight entity\n        while((match = regExp.exec(options.text)) !== null) {\n          entities.push({_: 'messageEntityHighlight', length: highlightWord.length, offset: match.index});\n          found = true;\n        }\n\n        if(found) {\n          sortEntities(entities);\n        }\n      }\n\n      const messagePeerId = (message as Message.message).peerId;\n      const shouldHideCode = [SERVICE_PEER_ID, VERIFICATION_CODES_BOT_ID].includes(messagePeerId);\n      const codeRegex = messagePeerId === SERVICE_PEER_ID ? /[\\d\\-]{5,7}/ : /[\\d\\-]{3,8}/;\n\n      if(shouldHideCode &&\n        (message as Message.message).fromId === (message as Message.message).peerId) {\n        const match = options.text.match(codeRegex);\n        if(match) {\n          entities = entities.slice();\n          entities.push({\n            _: 'messageEntitySpoiler',\n            offset: match.index,\n            length: match[0].length\n          });\n\n          sortEntities(entities);\n        }\n      }\n\n      let what: DocumentFragment | HTMLElement;\n      if(options.canTranslate) {\n        what = TranslatableMessage({\n          peerId: (message as Message.message).peerId,\n          message: message as Message.message,\n          richTextOptions: someRichTextOptions,\n          middleware: options.middleware,\n          onTextWithEntities: (textWithEntities) => {\n            return {\n              ...textWithEntities,\n              text: limitSymbols(textWithEntities.text, 100)\n            };\n          }\n        });\n      } else {\n        what = wrapRichText(options.text, {\n          ...someRichTextOptions,\n          entities\n        });\n\n        what = htmlToDocumentFragment(what);\n      }\n\n      parts.push(what);\n    }\n  }\n\n  if(plain) {\n    return parts.join('') as any;\n  } else {\n    const fragment = document.createDocumentFragment();\n    fragment.append(...parts);\n    return fragment as any;\n  }\n}\n","import {MessageAction, PaymentsCheckedGiftCode} from '@layer';\n\nexport default function shouldDisplayGiftCodeAsGift(action: MessageAction.messageActionGiftCode | PaymentsCheckedGiftCode) {\n  if(action._ === 'payments.checkedGiftCode') {\n    return !action.from_id;\n  }\n\n  return (action.amount || action.crypto_amount) !== undefined;\n}\n","import {MessageAction} from '@layer';\nimport {FormatterArgument, LangPackKey} from '@lib/langPack';\n\ntype Result = {\n  langPackKey: LangPackKey;\n  args: FormatterArgument[];\n};\n\nexport function getPriceChangedActionMessageLangParams(action: MessageAction.messageActionPaidMessagesPrice, isBroadcast: boolean, peerTitle?: () => Promise<FormatterArgument>): Promise<Result>;\nexport function getPriceChangedActionMessageLangParams(action: MessageAction.messageActionPaidMessagesPrice, isBroadcast: boolean, peerTitle?: () => FormatterArgument): Result;\n\nexport function getPriceChangedActionMessageLangParams(action: MessageAction.messageActionPaidMessagesPrice, isBroadcast: boolean, peerTitle?: () => Promise<FormatterArgument> | FormatterArgument): Promise<Result> | Result {\n  const isFree = !+action?.stars;\n  const allowedDirectMessages = action?.pFlags?.broadcast_messages_allowed;\n\n  if(isBroadcast) {\n    const peerTitleResult = peerTitle();\n    const langPackKey: LangPackKey = allowedDirectMessages ?\n      (isFree ? 'PaidMessages.ChannelPriceChangedFree' : 'PaidMessages.ChannelPriceChanged') :\n      'PaidMessages.ChannelPriceDisabled';\n\n    if(peerTitleResult instanceof Promise) {\n      return (async() => ({\n        langPackKey,\n        args: isFree ? [await peerTitleResult] : [+action.stars, await peerTitleResult]\n      }))();\n    }\n\n    return {\n      langPackKey,\n      args: isFree ? [peerTitleResult] : [+action.stars, peerTitleResult]\n    }\n  } else {\n    return {\n      langPackKey: isFree ? 'PaidMessages.GroupPriceChangedFree' : 'PaidMessages.GroupPriceChanged',\n      args: [+action.stars]\n    };\n  }\n}\n","import numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {StarGift} from '@layer';\n\nexport function getCollectibleName(gift: StarGift.starGiftUnique) {\n  return `${gift.title} #${numberThousandSplitter(gift.num, ',')}`\n}\n","import type {MessageEntity} from '@layer';\n\nconst ATOMIC: ReadonlySet<MessageEntity['_']> = new Set([\n  'messageEntityMention',\n  'messageEntityMentionName',\n  'inputMessageEntityMentionName',\n  'messageEntityHashtag',\n  'messageEntityCashtag',\n  'messageEntityBotCommand',\n  'messageEntityUrl',\n  'messageEntityTextUrl',\n  'messageEntityEmail',\n  'messageEntityPhone',\n  'messageEntityBankCard',\n  'messageEntityCustomEmoji',\n  'messageEntityEmoji',\n  'messageEntityImage',\n  'messageEntityTimestamp',\n  'messageEntityFormattedDate',\n  'messageEntityAnchor',\n  'messageEntityDiffReplace'\n]);\n\nconst ZERO_LENGTH: ReadonlySet<MessageEntity['_']> = new Set([\n  'messageEntityLinebreak',\n  'messageEntityCaret'\n]);\n\n/** Sorted UTF-16 indices of every grapheme boundary, including 0 and text.length. */\nfunction graphemeBoundaries(text: string): number[] {\n  const seg = new Intl.Segmenter(undefined, {granularity: 'grapheme'});\n  const out: number[] = [];\n  for(const {index} of seg.segment(text)) out.push(index);\n  out.push(text.length);\n  return out;\n}\n\n/** Smallest boundary >= i. */\nfunction snapUp(boundaries: number[], i: number): number {\n  let lo = 0, hi = boundaries.length - 1;\n  while(lo < hi) {\n    const mid = (lo + hi) >>> 1;\n    if(boundaries[mid] < i) lo = mid + 1;\n    else hi = mid;\n  }\n  return boundaries[lo];\n}\n\n/** Largest boundary <= i. */\nfunction snapDown(boundaries: number[], i: number): number {\n  let lo = 0, hi = boundaries.length - 1;\n  while(lo < hi) {\n    const mid = (lo + hi + 1) >>> 1;\n    if(boundaries[mid] > i) hi = mid - 1;\n    else lo = mid;\n  }\n  return boundaries[lo];\n}\n\n/**\n * Slices `text` over the UTF-16 range `[from, to)` while preserving entity\n * integrity. Boundaries are snapped inward to the nearest grapheme cluster so\n * surrogate pairs and emoji sequences are never split. Entities are clipped\n * to the resulting range; atomic entities (mentions, links, custom emoji,\n * etc.) are dropped if a boundary falls inside them. Returns the sliced text,\n * the adjusted entities, and the actual `from`/`to` used after snapping.\n */\nexport function sliceTextWithEntities(\n  text: string,\n  entities: MessageEntity[],\n  from: number,\n  to: number\n): {text: string, entities: MessageEntity[], from: number, to: number} {\n  from = Math.max(0, Math.min(from, text.length));\n  to = Math.max(0, Math.min(to, text.length));\n  if(to < from) to = from;\n\n  const boundaries = graphemeBoundaries(text);\n  const start = snapUp(boundaries, from);\n  let end = snapDown(boundaries, to);\n  if(end < start) end = start;\n\n  const slicedText = text.slice(start, end);\n\n  const out: MessageEntity[] = [];\n  for(const e of entities) {\n    const eStart = e.offset ?? 0;\n    const eLen = e.length ?? 0;\n    const eEnd = eStart + eLen;\n\n    if(ZERO_LENGTH.has(e._)) {\n      if(eStart >= start && eStart <= end) {\n        out.push({...e, offset: eStart - start, length: 0});\n      }\n      continue;\n    }\n\n    if(eEnd <= start || eStart >= end) continue;\n\n    const fullyInside = eStart >= start && eEnd <= end;\n    if(!fullyInside && ATOMIC.has(e._)) continue;\n\n    const newStart = Math.max(eStart, start);\n    const newEnd = Math.min(eEnd, end);\n    out.push({...e, offset: newStart - start, length: newEnd - newStart});\n  }\n\n  return {text: slicedText, entities: out, from: start, to: end};\n}\n","import {MessageEntity} from '@layer';\nimport {sliceTextWithEntities} from '@lib/richTextProcessor/sliceTextWithEntities';\n\n/**\n * Uses Unicode horizontal ellipsis (U+2026) instead of \"...\"\n * for better typography, line breaking, and internationalization.\n */\nconst ELLIPSIS = '…';\n\nexport function truncateTextWithEntities(\n  text: string,\n  entities: MessageEntity[],\n  n: number\n): {text: string, entities: MessageEntity[]} {\n  if(text.length <= n) {\n    return {text, entities};\n  }\n\n  if(n <= ELLIPSIS.length) {\n    // Not enough room for content + ellipsis; just return as much ellipsis as fits.\n    return {text: ELLIPSIS.slice(0, Math.max(0, n)), entities: []};\n  }\n\n  const budget = n - ELLIPSIS.length;\n  const sliced = sliceTextWithEntities(text, entities, 0, budget);\n\n  return {\n    text: sliced.text + ELLIPSIS,\n    entities: sliced.entities\n  };\n}\n","import indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {formatTime, ONE_DAY} from '@helpers/date';\nimport htmlToSpan from '@helpers/dom/htmlToSpan';\nimport setInnerHTML, {setDirection} from '@helpers/dom/setInnerHTML';\nimport {wrapCallDuration} from '@components/wrappers/wrapDuration';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {ForumTopic, Message, MessageAction, MessageEntity, MessageMedia, MessageReplyHeader, StarGift, TextWithEntities} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {FormatterArgument, FormatterArguments, i18n, join, langPack, LangPackKey, _i18n} from '@lib/langPack';\nimport {GENERAL_TOPIC_ID} from '@appManagers/constants';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapPlainText from '@lib/richTextProcessor/wrapPlainText';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport rootScope from '@lib/rootScope';\nimport topicAvatar from '@components/topicAvatar';\nimport {wrapCustomEmojiAwaited} from '@components/wrappers/customEmoji';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport wrapJoinVoiceChatAnchor from '@components/wrappers/joinVoiceChatAnchor';\nimport {WrapMessageActionTextOptions} from '@components/wrappers/messageActionTextNew';\nimport wrapMessageForReply, {WrapMessageForReplyOptions} from '@components/wrappers/messageForReply';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport shouldDisplayGiftCodeAsGift from '@helpers/shouldDisplayGiftCodeAsGift';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport Icon from '@components/icon';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport {getPriceChangedActionMessageLangParams} from '@lib/lang';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\nimport {truncateTextWithEntities} from '@lib/richTextProcessor/truncateTextWithEntities';\n\nasync function wrapLinkToMessage(options: WrapMessageForReplyOptions) {\n  const wrapped = await wrapMessageForReply(options);\n\n  if(options.plain) {\n    return wrapped;\n  }\n\n  const a = document.createElement('i');\n  a.dataset.savedFrom = (options.message as Message.message).peerId + '_' + (options.message as Message.message).mid;\n  a.append(wrapped);\n  setDirection(a);\n  return a;\n}\n\nfunction wrapSomeText(text: string, plain: boolean, entities?: MessageEntity[]) {\n  return plain ? text : htmlToSpan(wrapEmojiText(text, false, entities));\n}\n\nfunction joinTexts(texts: (string | HTMLElement)[], params: {\n  delimiter: string,\n  wrap?: (text: string | HTMLElement) => string | HTMLElement,\n  prepend?: string,\n  append?: string\n}) {\n  const {delimiter, prepend, append} = params\n  const fragment = document.createDocumentFragment()\n  let first = true\n  for(const it of texts) {\n    if(first) {\n      first = false\n    } else {\n      fragment.append(delimiter)\n    }\n\n    if(prepend) {\n      fragment.append(prepend)\n    }\n    if(params.wrap) {\n      fragment.append(params.wrap(it));\n    } else {\n      fragment.append(it);\n    }\n    if(append) {\n      fragment.append(append)\n    }\n  }\n  return fragment\n}\n\nconst TODO_JOIN_OPTIONS: Parameters<typeof joinTexts>[1] = {\n  delimiter: ', ',\n  prepend: '\"',\n  append: '\"',\n  wrap: el => {\n    const b = document.createElement('b');\n    b.append(el);\n    return b;\n  }\n};\n\nconst MAX_ANSWER_TEXT_LENGTH = 20;\n\ntype WrapTopicIconOptions = {\n  topic: Pick<ForumTopic.forumTopic, 'icon_color' | 'icon_emoji_id' | 'title' | 'id'>,\n  plain?: boolean\n} & WrapSomethingOptions;\n\nexport async function wrapTopicIcon(options: WrapTopicIconOptions & {plain: true}): Promise<string>;\nexport async function wrapTopicIcon(options: WrapTopicIconOptions & {plain?: false}): Promise<HTMLElement | DocumentFragment>;\nexport async function wrapTopicIcon(options: WrapTopicIconOptions): Promise<string | HTMLElement | DocumentFragment>;\n\nexport async function wrapTopicIcon(options: WrapTopicIconOptions): Promise<string | HTMLElement | DocumentFragment> {\n  const topic = options.topic;\n\n  let iconEmojiId = topic?.icon_emoji_id;\n  if(topic?.id === GENERAL_TOPIC_ID) {\n    iconEmojiId = '5390854796011906616';\n  }\n\n  if(!iconEmojiId) {\n    if(options.plain) return '' as any;\n\n    // if(topic?.id === GENERAL_TOPIC_ID) {\n    //   const span = document.createElement('span');\n    //   span.innerHTML = `\n    //   <svg class=\"topic-icon-general\" width=\"22\" height=\"22\" viewBox=\"0 0 22 22\" xmlns=\"http://www.w3.org/2000/svg\">\n    //     <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M11.2788 4.3654C11.4806 3.65912 11.0717 2.92299 10.3654 2.72119C9.65911 2.5194 8.92297 2.92836 8.72118 3.63464L7.85393 6.67H6C5.26546 6.67 4.67 7.26546 4.67 8C4.67 8.73454 5.26546 9.33 6 9.33H7.09393L6.13965 12.67H4C3.26546 12.67 2.67 13.2655 2.67 14C2.67 14.7345 3.26546 15.33 4 15.33H5.37965L4.72118 17.6346C4.51938 18.3409 4.92835 19.0771 5.63463 19.2788C6.3409 19.4806 7.07704 19.0717 7.27883 18.3654L8.14609 15.33H11.3796L10.7212 17.6346C10.5194 18.3409 10.9283 19.0771 11.6346 19.2788C12.3409 19.4806 13.077 19.0717 13.2788 18.3654L14.1461 15.33H16C16.7345 15.33 17.33 14.7345 17.33 14C17.33 13.2655 16.7345 12.67 16 12.67H14.9061L15.8604 9.33H18C18.7345 9.33 19.33 8.73454 19.33 8C19.33 7.26546 18.7345 6.67 18 6.67H16.6204L17.2788 4.3654C17.4806 3.65912 17.0717 2.92299 16.3654 2.72119C15.6591 2.5194 14.923 2.92836 14.7212 3.63464L13.8539 6.67H10.6204L11.2788 4.3654ZM9.86037 9.33L8.90609 12.67H12.1396L13.0939 9.33H9.86037Z\"/>\n    //   </svg>\n    //   `;\n\n    //   span.classList.add('topic-icon');\n\n    //   return span as any;\n    // }\n\n    return topicAvatar(topic?.icon_color, topic?.title) as any;\n  }\n\n  return options.plain ?\n    rootScope.managers.appEmojiManager.getCustomEmojiDocument(iconEmojiId).then((doc) => doc.stickerEmojiRaw) :\n    wrapCustomEmojiAwaited({\n      ...options,\n      docIds: [iconEmojiId]\n    }).then((fragment) => {\n      fragment.lastElementChild.classList.add('topic-icon');\n      return fragment;\n    });\n}\n\nfunction wrapMessageActionTopicIcon(options: WrapMessageActionTextOptions) {\n  const action = ((options.message as Message.messageService).action as MessageAction.messageActionTopicCreate);\n  return wrapTopicIcon({\n    ...options,\n    topic: action as any as ForumTopic.forumTopic\n  });\n}\n\nasync function wrapMessageActionTopicIconAndName(options: WrapMessageActionTextOptions) {\n  const action = ((options.message as Message.messageService).action as MessageAction.messageActionTopicCreate);\n  const span = document.createElement('span');\n  span.classList.add('topic-name');\n  span.append(await wrapMessageActionTopicIcon(options), wrapSomeText(action.title, options.plain));\n  return span;\n}\n\nexport function wrapMessageGiveawayResults(action: MessageAction.messageActionGiveawayResults | MessageMedia.messageMediaGiveawayResults, plain?: boolean) {\n  let langPackKey: LangPackKey = 'Giveaway.Results';\n  let args: FormatterArguments = [action.winners_count];\n\n  const setCombined = (addLangPackKey: LangPackKey, addArgs?: FormatterArguments) => {\n    args = [\n      plain ?\n        I18n.format(langPackKey, true, args as FormatterArguments) :\n        i18n(langPackKey, args as FormatterArguments)\n    ];\n\n    langPackKey = 'Giveaway.Results.Combined';\n    args.push(\n      plain ?\n        I18n.format(addLangPackKey, true, addArgs) :\n        i18n(addLangPackKey, addArgs)\n    );\n  };\n\n  if(!action.winners_count) {\n    langPackKey = (action as MessageAction.messageActionGiveawayResults).pFlags.stars ? 'Giveaway.Results.NoWinners.Stars' : 'Giveaway.Results.NoWinners';\n    args = [action.unclaimed_count];\n  } else if(action.unclaimed_count) {\n    setCombined('Giveaway.Results.Unclaimed', [action.unclaimed_count]);\n  }\n\n  return {langPackKey, args};\n}\n\nexport default async function wrapMessageActionTextNewUnsafe(options: WrapMessageActionTextOptions) {\n  const {plain, message, noLinks} = options;\n  const element: HTMLElement = plain ? undefined : document.createElement('span');\n  const action = 'action' in message && message.action;\n\n  // this.log('message action:', action);\n\n  if(action._ === 'messageActionCustomAction' && action.message) {\n    const unsafeMessage = action.message;\n    if(plain) {\n      return wrapPlainText(unsafeMessage);\n    } else {\n      setInnerHTML(element, wrapRichText(unsafeMessage, {noLinebreaks: true}));\n      return element;\n    }\n  } else {\n    let _ = action._;\n    // let suffix = '';\n    let langPackKey: LangPackKey;\n    let icon: HTMLElement | undefined;\n    let args: Array<FormatterArgument | Promise<FormatterArgument>>;\n\n    const managers = rootScope.managers;\n\n    const getNameDivHTML = (peerId: PeerId, plain: boolean) => {\n      return plain ? getPeerTitle({peerId, plainText: plain}) : wrapPeerTitle({peerId});\n    };\n\n    const wrapTruncatedText = (text: string, entities: MessageEntity[] | undefined, maxLength: number) => {\n      const truncated = truncateTextWithEntities(text, entities, maxLength);\n\n      if(plain) {\n        return wrapPlainText(truncated.text, truncated.entities);\n      } else {\n        return htmlToSpan(wrapEmojiText(truncated.text, false, truncated.entities));\n      }\n    };\n\n    const getSeveralNameDivHTML = async(peerIds: PeerId[], plain: boolean) => {\n      if(peerIds.length === 1) {\n        return getNameDivHTML(peerIds[0], plain);\n      }\n\n      const joined = join(\n        await Promise.all(peerIds.map((peerId) => getNameDivHTML(peerId, plain))),\n        false,\n        plain\n      );\n\n      if(plain) {\n        return Array.isArray(joined) ? joined.join('') : joined;\n      } else {\n        const fragment = document.createElement('span');\n        fragment.append(...joined);\n        args.push(fragment);\n        return fragment;\n      }\n    };\n\n    switch(action._) {\n      case 'messageActionPhoneCall': {\n        _ += '.' + (action as any).type;\n\n        args = [wrapCallDuration(action.duration, plain)];\n        break;\n      }\n\n      case 'messageActionGroupCall': {\n        _ += '.' + (action as any).type;\n\n        args = [];\n        if(!_.endsWith('You') && !message.pFlags.post) {\n          args.push(getNameDivHTML(message.fromId, plain));\n        }\n\n        if(action.duration !== undefined) {\n          args.push(wrapCallDuration(action.duration, plain));\n        } else if(noLinks) {\n          args.push('');\n        } else {\n          args.push(wrapJoinVoiceChatAnchor(message as any));\n        }\n\n        break;\n      }\n\n      case 'messageActionInviteToGroupCall': {\n        const peerIds = [message.fromId, action.users[0].toPeerId()];\n        let a = 'Chat.Service.VoiceChatInvitation';\n        const myId = rootScope.myId;\n        if(peerIds[0] === myId) a += 'ByYou';\n        else if(peerIds[1] === myId) a += 'ForYou';\n        indexOfAndSplice(peerIds, myId);\n\n        langPackKey = a as LangPackKey;\n        args = peerIds.map((peerId) => getNameDivHTML(peerId, plain));\n        args.push(noLinks ? '' : wrapJoinVoiceChatAnchor(message as any));\n        break;\n      }\n\n      case 'messageActionConferenceCall': {\n        // tdesktop renders this as a media bubble (MediaCall) with state\n        // Invitation / Active / Missed / Hangup. We render service text +\n        // a Join anchor while the call is still joinable. The Join anchor\n        // resolves the conference via inputGroupCallInviteMessage(msg_id).\n        const isMissed = !!action.pFlags.missed;\n        const hasDuration = action.duration !== undefined;\n        const isJoinable = !isMissed && !hasDuration;\n        const isOut = !!message.pFlags.out;\n\n        if(isMissed) {\n          langPackKey = 'Chat.Service.ConferenceCall.Missed';\n          args = [];\n        } else if(hasDuration) {\n          langPackKey = 'Chat.Service.ConferenceCall.Ended';\n          args = [wrapCallDuration(action.duration, plain)];\n        } else {\n          langPackKey = isOut ?\n            'Chat.Service.ConferenceCall.Outgoing' :\n            'Chat.Service.ConferenceCall.Incoming';\n          args = [noLinks || !isJoinable ? '' : wrapJoinVoiceChatAnchor(message as any)];\n        }\n        break;\n      }\n\n      case 'messageActionGroupCallScheduled': {\n        const today = new Date();\n        const date = new Date(action.schedule_date * 1000);\n        const daysToStart = (date.getTime() - today.getTime()) / 86400e3;\n        const tomorrowDate = new Date(today);\n        tomorrowDate.setDate(tomorrowDate.getDate() + 1);\n\n        const isBroadcast = await managers.appPeersManager.isBroadcast(message.peerId);\n        langPackKey = isBroadcast ? 'ChatList.Service.VoiceChatScheduled.Channel' : 'ChatList.Service.VoiceChatScheduled';\n        args = [];\n        const myId = rootScope.myId;\n        if(message.fromId === myId) {\n          langPackKey += 'You';\n        } else if(!isBroadcast) {\n          args.push(getNameDivHTML(message.fromId, plain));\n        }\n\n        let k: LangPackKey;\n        const _args: FormatterArguments = [];\n        if(daysToStart < 1 && date.getDate() === today.getDate()) {\n          k = 'TodayAtFormattedWithToday';\n        } else if(daysToStart < 2 && date.getDate() === tomorrowDate.getDate()) {\n          k = 'Time.TomorrowAt';\n        } else {\n          k = 'formatDateAtTime';\n          _args.push(new I18n.IntlDateElement({\n            date,\n            options: {\n              day: '2-digit',\n              month: '2-digit',\n              year: '2-digit'\n            }\n          }).element);\n        }\n\n        _args.push(formatTime(date));\n        const t = i18n(k, _args);\n        args.push(t);\n\n        break;\n      }\n\n      case 'messageActionChatCreate': {\n        const myId = rootScope.myId;\n        if(message.fromId === myId) {\n          _ += 'You';\n        } else {\n          args = [getNameDivHTML(message.fromId, plain)];\n        }\n\n        break;\n      }\n\n      case 'messageActionGameScore': {\n        const fromMe = message.fromId === rootScope.myId;\n        args = [];\n        if(!fromMe) {\n          args.push(getNameDivHTML(message.fromId, plain));\n        }\n        args.push('' + action.score);\n\n        let gameTitle: string | undefined;\n        if(message.reply_to_mid) {\n          const gameMessage = await managers.appMessagesManager.getMessageByPeer(message.peerId, message.reply_to_mid);\n          const media = (gameMessage as Message.message)?.media;\n          if(media?._ === 'messageMediaGame' && media.game?._ === 'game') {\n            gameTitle = media.game.title;\n          } else if(!gameMessage) {\n            managers.appMessagesManager.fetchMessageReplyTo(message);\n          }\n        }\n\n        if(gameTitle) {\n          if(plain) {\n            args.push(wrapSomeText(gameTitle, plain));\n          } else {\n            const link = document.createElement('i');\n            link.classList.add('is-game-link');\n            link.dataset.savedFrom = message.peerId + '_' + message.reply_to_mid;\n            link.append(wrapSomeText(gameTitle, false));\n            setDirection(link);\n            args.push(link);\n          }\n          langPackKey = fromMe ? 'ActionYouScoredInGame' : 'ActionUserScoredInGame';\n        } else {\n          langPackKey = fromMe ? 'ActionYouScored' : 'ActionUserScored';\n        }\n        break;\n      }\n\n      case 'messageActionPinMessage': {\n        const peerId = message.peerId;\n        const pinnedMessage = await managers.appMessagesManager.getMessageByPeer(peerId, message.reply_to_mid);\n\n        args = [\n          getNameDivHTML(message.fromId, plain)\n        ];\n\n        if(!pinnedMessage/*  || true */) {\n          langPackKey = 'ActionPinnedNoText';\n\n          if(message.reply_to_mid) { // refresh original message\n            managers.appMessagesManager.fetchMessageReplyTo(message);\n          }\n        } else {\n          args.push(wrapLinkToMessage({\n            ...options,\n            message: pinnedMessage\n          }));\n        }\n\n        break;\n      }\n\n      case 'messageActionChatJoinedByRequest': {\n        const isBroadcast = await managers.appPeersManager.isBroadcast(message.peerId);\n        if(message.pFlags.out) {\n          langPackKey = isBroadcast ? 'RequestToJoinChannelApproved' : 'RequestToJoinGroupApproved';\n        } else {\n          langPackKey = isBroadcast ? 'ChatService.UserJoinedChannelByRequest' : 'ChatService.UserJoinedGroupByRequest';\n          args = [getNameDivHTML(message.fromId, plain)];\n        }\n        break;\n      }\n\n      case 'messageActionGiveawayLaunch': {\n        langPackKey = action.stars ? 'BoostingStarsGiveawayJustStarted' : 'BoostingGiveawayJustStarted';\n        args = [getNameDivHTML(message.fromId, plain)];\n\n        if(action.stars) {\n          args.unshift(+action.stars);\n        }\n        break;\n      }\n\n      case 'messageActionContactSignUp':\n      case 'messageActionChatReturn':\n      case 'messageActionChatLeave':\n      case 'messageActionChatJoined':\n      case 'messageActionChatEditPhoto':\n      case 'messageActionChatDeletePhoto':\n      case 'messageActionChatEditVideo':\n      case 'messageActionChatJoinedByLink':\n      case 'messageActionChannelEditVideo':\n      case 'messageActionChannelDeletePhoto': {\n        args = [getNameDivHTML(message.fromId, plain)];\n        break;\n      }\n\n      case 'messageActionSuggestProfilePhoto': {\n        const isOutgoing = message.fromId === rootScope.myId;\n        langPackKey = isOutgoing ?\n          'Action.YouSuggestedProfilePhoto' :\n          'Action.SuggestedProfilePhoto';\n        args = isOutgoing ? [getNameDivHTML(message.peerId, plain)] : [getNameDivHTML(message.fromId, plain)];\n        break;\n      }\n\n      case 'messageActionChannelEditTitle':\n      case 'messageActionChatEditTitle': {\n        args = [];\n        if(action._ === 'messageActionChatEditTitle') {\n          args.push(getNameDivHTML(message.fromId, plain));\n        }\n\n        args.push(wrapSomeText(action.title, plain));\n        break;\n      }\n\n      case 'messageActionChatDeleteUser':\n      case 'messageActionChatAddUsers':\n      case 'messageActionChatAddUser': {\n        const users = (action as MessageAction.messageActionChatAddUser).users ||\n          [(action as MessageAction.messageActionChatDeleteUser).user_id];\n\n        args = [getNameDivHTML(message.fromId, plain)];\n\n        const peerIds = users.map((userId) => userId.toPeerId(false));\n        args.push(getSeveralNameDivHTML(peerIds, plain));\n        break;\n      }\n\n      case 'messageActionBotAllowed': {\n        if(action.pFlags?.attach_menu) {\n          langPackKey = 'ActionAttachMenuBotAllowed';\n          break;\n        } else if(action.pFlags?.from_request) {\n          langPackKey = 'ActionBotAllowedRequest';\n          break;\n        } else if(!action.domain) {\n          break;\n        }\n\n        const anchorHTML = wrapRichText(action.domain, {\n          entities: [{\n            _: 'messageEntityUrl',\n            length: action.domain.length,\n            offset: 0\n          }],\n          noLinks\n        });\n\n        const node = htmlToSpan(anchorHTML);\n\n        args = [node];\n        break;\n      }\n\n      case 'messageActionPaymentSent': {\n        const isRecurringInit = action.pFlags.recurring_init;\n        const isRecurringUsed = action.pFlags.recurring_used;\n        langPackKey = isRecurringUsed ? 'Chat.Service.PaymentSentRecurringUsedNoTitle' : (isRecurringInit ? 'Chat.Service.PaymentSentRecurringInitNoTitle' : 'Chat.Service.PaymentSent1NoTitle');\n        const price = paymentsWrapCurrencyAmount(action.total_amount, action.currency, undefined, undefined, plain);\n        args = [price, getNameDivHTML(message.peerId, plain)];\n\n        if(message.reply_to_mid) {\n          const replyTo = message.reply_to as MessageReplyHeader.messageReplyHeader;\n          const invoiceMessage = await managers.appMessagesManager.getMessageByPeer(\n            replyTo?.reply_to_peer_id ? getPeerId(replyTo.reply_to_peer_id) : message.peerId,\n            message.reply_to_mid\n          );\n\n          if(!invoiceMessage) {\n            managers.appMessagesManager.fetchMessageReplyTo(message);\n          } else {\n            langPackKey = isRecurringUsed ? 'Chat.Service.PaymentSentRecurringUsed' : (isRecurringInit ? 'Chat.Service.PaymentSentRecurringInit' : 'Chat.Service.PaymentSent1');\n            args.push(wrapLinkToMessage({\n              ...options,\n              message: invoiceMessage\n            }).then((el) => {\n              if(el instanceof HTMLElement) {\n                el.classList.add('is-receipt-link');\n              }\n\n              return el;\n            }));\n          }\n        }\n\n        break;\n      }\n\n      case 'messageActionPaymentRefunded': {\n        const price = paymentsWrapCurrencyAmount(action.total_amount, action.currency, undefined, undefined, plain);\n        args = [getNameDivHTML(message.fromId, plain), price];\n        langPackKey = 'Chat.Service.Refund';\n        break;\n      }\n\n      case 'messageActionSetMessagesTTL': {\n        args = [];\n\n        const isBroadcast = await managers.appPeersManager.isBroadcast(message.peerId);\n        if(action.period) {\n          if(isBroadcast) {\n            langPackKey = 'ActionTTLChannelChanged';\n          } else if(message.fromId === rootScope.myId) {\n            langPackKey = 'ActionTTLYouChanged';\n          } else {\n            langPackKey = 'ActionTTLChanged';\n            args.push(await getNameDivHTML(message.fromId, plain));\n          }\n\n          let duration: ReturnType<typeof wrapCallDuration>;\n          if(action.period > 1814400) {\n            let key: LangPackKey;\n            const args: FormatterArguments = [];\n            const year = 31536000;\n            if(action.period >= year) {\n              key = 'Years';\n              args.push(action.period / year | 0);\n            } else {\n              key = 'Months';\n              args.push(action.period / (ONE_DAY * 30) | 0);\n            }\n\n            duration = plain ? I18n.format(key, true, args) : i18n(key, args);\n          } else {\n            duration = wrapCallDuration(action.period, plain);\n          }\n\n          args.push(duration);\n        } else {\n          if(isBroadcast) {\n            langPackKey = 'ActionTTLChannelDisabled';\n          } else if(message.fromId === rootScope.myId) {\n            langPackKey = 'ActionTTLYouDisabled';\n          } else {\n            langPackKey = 'ActionTTLDisabled';\n            args.push(getNameDivHTML(message.fromId, plain));\n          }\n        }\n        break;\n      }\n\n      case 'messageActionTopicEdit': {\n        let iconElement: (typeof args)[0];\n        let titleElement: typeof iconElement;\n        let authorElement: ReturnType<typeof getNameDivHTML>;\n        const isMe = !!message.pFlags.out;\n        const isIconChanged = action.icon_emoji_id !== undefined;\n        const isIconRemoved = isIconChanged && !+action.icon_emoji_id;\n        const isTitleChanged = action.title !== undefined;\n        const isHiddenChanged = action.hidden !== undefined;\n\n        if(!isMe) {\n          authorElement = getNameDivHTML(message.fromId, plain);\n        }\n\n        if(isTitleChanged) {\n          titleElement = wrapSomeText(action.title, plain);\n        }\n\n        if(isIconChanged && !isIconRemoved) {\n          iconElement = wrapMessageActionTopicIcon(options);\n        }\n\n        args = authorElement ? [authorElement] : [];\n\n        if(action.closed) {\n          langPackKey = isMe ? 'Chat.Service.Group.TopicEdited.You.Paused' : 'Chat.Service.Group.TopicEdited.Paused';\n        } else if(action.closed === false) {\n          langPackKey = isMe ? 'Chat.Service.Group.TopicEdited.You.Resumed' : 'Chat.Service.Group.TopicEdited.Resumed';\n        } else if(isIconRemoved && isTitleChanged) {\n          langPackKey = isMe ? 'Chat.Service.TopicEdited.You.Mixed.IconRemoved' : 'Chat.Service.TopicEdited.Mixed.IconRemoved';\n          args.push(titleElement);\n        } else if(isIconChanged && isTitleChanged) {\n          langPackKey = isMe ? 'Chat.Service.TopicEdited.You.Mixed' : 'Chat.Service.TopicEdited.Mixed';\n          args.push(wrapMessageActionTopicIconAndName(options));\n        } else if(isIconRemoved) {\n          langPackKey = isMe ? 'Chat.Service.Group.TopicEdited.You.Icon.Removed' : 'Chat.Service.Group.TopicEdited.Icon.Removed';\n        } else if(isTitleChanged) {\n          langPackKey = isMe ? 'Chat.Service.Group.TopicEdited.You.Title' : 'Chat.Service.Group.TopicEdited.Title';\n          args.push(titleElement);\n        } else if(isIconChanged) {\n          langPackKey = isMe ? 'Chat.Service.Group.TopicEdited.You.Icon' : 'Chat.Service.Group.TopicEdited.Icon';\n          args.push(iconElement);\n        } else if(isHiddenChanged) {\n          langPackKey = isMe ?\n            (action.hidden ? 'Chat.Service.Group.TopicEdited.You.Hided' : 'Chat.Service.Group.TopicEdited.You.Unhided') :\n            (action.hidden ? 'Chat.Service.Group.TopicEdited.Hided' : 'Chat.Service.Group.TopicEdited.Unhided');\n        }\n\n        break;\n      }\n\n      case 'messageActionTopicCreate': {\n        args = [wrapMessageActionTopicIconAndName(options)];\n        langPackKey = 'TopicWasCreatedAction';\n        break;\n      }\n\n      case 'messageActionSetChatTheme': {\n        const isMe = !!message.pFlags.out;\n        let authorElement: ReturnType<typeof getNameDivHTML>;\n        if(!isMe) {\n          authorElement = getNameDivHTML(message.fromId, plain);\n        }\n\n        args = authorElement ? [authorElement] : [];\n\n        const theme = action.theme;\n        if(theme._ === 'chatThemeUniqueGift') {\n          // * unsupported now\n        } else if(theme.emoticon) {\n          args.push(wrapSomeText(theme.emoticon, plain));\n          langPackKey = isMe ? 'ChatThemeChangedYou' : 'ChatThemeChangedTo';\n        } else {\n          langPackKey = isMe ? 'ChatThemeDisabledYou' : 'ChatThemeDisabled';\n        }\n        break;\n      }\n\n      case 'messageActionPrizeStars': {\n        langPackKey = 'BoostingReceivedGiftNoName';\n        break;\n      }\n\n      case 'messageActionGiftStars':\n      case 'messageActionGiftCode':\n      case 'messageActionGiftTon':\n      case 'messageActionGiftPremium': {\n        const isGiftCode = action._ === 'messageActionGiftCode';\n        if(isGiftCode && !shouldDisplayGiftCodeAsGift(action)) {\n          langPackKey = 'BoostingReceivedGiftNoName';\n          if(action.boost_peer) {\n            langPackKey = 'BoostingReceivedGiftFrom';\n            args = [getNameDivHTML(getPeerId(action.boost_peer), plain)];\n          }\n\n          break;\n        }\n\n        const isMe = !!message.pFlags.out && !isGiftCode;\n        let authorElement: ReturnType<typeof getNameDivHTML>;\n        if(!isMe) {\n          authorElement = getNameDivHTML(message.fromId, plain);\n        }\n\n        args = authorElement ? [authorElement] : [];\n\n        args.push(paymentsWrapCurrencyAmount(action.amount, action.currency, false, true, plain));\n\n        langPackKey = isMe ? 'ActionGiftOutbound' : 'ActionGiftInbound';\n\n        break;\n      }\n\n      case 'messageActionWebViewDataSent': {\n        langPackKey = 'ActionBotWebViewData';\n        args = [wrapSomeText(action.text, plain)];\n        break;\n      }\n\n      case 'messageActionRequestedPeer': {\n        langPackKey = 'Chat.Service.PeerRequested';\n        args = [\n          getSeveralNameDivHTML(action.peers.map((peer) => getPeerId(peer)), plain),\n          getNameDivHTML(message.peerId, plain)\n        ];\n        break;\n      }\n\n      case 'messageActionGiveawayResults': {\n        const r = wrapMessageGiveawayResults(action, plain);\n        langPackKey = r.langPackKey;\n        args = r.args;\n        break;\n      }\n\n      case 'messageActionSetChatWallPaper': {\n        const isUser = message.peerId.isUser();\n        args = [\n          getNameDivHTML(isUser ? message.peerId : message.fromId, plain)\n        ];\n\n        if(isUser) {\n          if(message.pFlags.out) {\n            langPackKey = action.pFlags.for_both ?\n              'ActionSetWallpaperForThisChatSelfBoth' : (\n                action.pFlags.same ?\n                  'ActionSetSameWallpaperForThisChatSelf' :\n                  'ActionSetWallpaperForThisChatSelf'\n              );\n          } else {\n            langPackKey = action.pFlags.for_both ?\n              'ActionSetWallpaperForThisChatBoth' : (\n                action.pFlags.same ?\n                  'ActionSetSameWallpaperForThisChat' :\n                  'ActionSetWallpaperForThisChat'\n              );\n          }\n\n          break;\n        }\n\n        const isBroadcast = await managers.appPeersManager.isBroadcast(message.peerId);\n        if(isBroadcast) {\n          langPackKey = 'ActionSetWallpaperForThisChannel';\n          break;\n        }\n\n        langPackKey = message.fromId === message.peerId ?\n          'ActionSetWallpaperForThisGroup' :\n          'ActionSetWallpaperForThisGroupByUser';\n\n        break;\n      }\n\n      case 'messageActionPaidMessagesPrice': {\n        const isBroadcast = await managers.appChatsManager.isBroadcast(message.fromId?.toChatId());\n        const result = await getPriceChangedActionMessageLangParams(action, isBroadcast, () => getNameDivHTML(message.fromId, plain));\n        langPackKey = result.langPackKey;\n        args = result.args;\n        break;\n      }\n\n      case 'messageActionPaidMessagesRefunded': {\n        langPackKey = 'PaidMessages.StarsRefundedShort';\n        args = [+action.stars];\n        break;\n      }\n      case 'messageActionStarGift':\n        if(message.peerId === rootScope.myId) {\n          langPackKey = 'StarGiftSentMessageSelf';\n          args = [(action.gift as StarGift.starGift).stars];\n        } else if(message.pFlags.out) {\n          langPackKey = action.pFlags.upgrade_separate ? 'StarGiftSentMessagePrepaidOutgoing' : 'StarGiftSentMessageOutgoing';\n          args = [(action.gift as StarGift.starGift).stars];\n        } else {\n          langPackKey = action.pFlags.upgrade_separate ? 'StarGiftSentMessagePrepaidIncoming' : 'StarGiftSentMessageIncoming';\n          args = [getNameDivHTML(message.fromId, plain), (action.gift as StarGift.starGift).stars];\n        }\n        break;\n      case 'messageActionStarGiftUnique':\n        if(!message.pFlags.out && action.resale_amount) {\n          langPackKey = action.resale_amount._ === 'starsTonAmount' ? 'StarGiftSentMessageSelfTon' : 'StarGiftSentMessageSelf';\n          args = [formatStarsAmount(action.resale_amount)];\n        } else if(message.peerId === rootScope.myId) {\n          langPackKey = action.pFlags.upgrade ? 'ActionGiftUpgradedSelf' : 'ActionGiftTransferredSelf';\n        } else {\n          if(action.pFlags.upgrade) {\n            langPackKey = message.pFlags.out ? 'ActionGiftUpgradedOutbound' : 'ActionGiftUpgradedInbound';\n          } else if(message.pFlags.out && action.pFlags.from_offer) {\n            langPackKey = 'ActionGiftSold';\n          } else {\n            langPackKey = message.pFlags.out ? 'ActionGiftTransferredOutbound' : 'ActionGiftTransferredInbound';\n          }\n          args = [getNameDivHTML(message.peerId, plain)];\n        }\n        break;\n\n      case 'messageActionTodoAppendTasks': {\n        let listMsg = await managers.appMessagesManager.getMessageByPeer(message.peerId, message.reply_to_mid);\n        if(!listMsg) {\n          listMsg = await managers.appMessagesManager.fetchMessageReplyTo(message) as Message.message;\n        }\n\n        icon = Icon('checklist_add');\n\n        if(listMsg?._ === 'message' && listMsg.media._ === 'messageMediaToDo') {\n          if(action.list.length === 1) {\n            langPackKey = `ChecklistAddedTask${message.pFlags.out ? 'You' : ''}`;\n            args = [\n              message.pFlags.out ? undefined : getNameDivHTML(message.fromId, plain),\n              wrapSomeText(action.list[0].title.text, plain, action.list[0].title.entities),\n              wrapSomeText(listMsg.media.todo.title.text, plain, listMsg.media.todo.title.entities)\n            ];\n          } else {\n            langPackKey = `ChecklistAddedTaskMany${message.pFlags.out ? 'You' : ''}`;\n            args = [\n              message.pFlags.out ? undefined : getNameDivHTML(message.fromId, plain),\n              joinTexts(action.list.map((it) => wrapSomeText(it.title.text, plain, it.title.entities)), TODO_JOIN_OPTIONS),\n              wrapSomeText(listMsg.media.todo.title.text, plain, listMsg.media.todo.title.entities)\n            ];\n          }\n        }\n        break;\n      }\n      case 'messageActionTodoCompletions': {\n        let listMsg = await managers.appMessagesManager.getMessageByPeer(message.peerId, message.reply_to_mid);\n        if(!listMsg) {\n          listMsg = await managers.appMessagesManager.fetchMessageReplyTo(message) as Message.message;\n        }\n\n        if(listMsg?._ === 'message' && listMsg.media._ === 'messageMediaToDo') {\n          const list = listMsg.media.todo;\n          const itemsMap = new Map<number, TextWithEntities>();\n          for(const it of list.list) {\n            itemsMap.set(it.id, it.title);\n          }\n\n          const completed = action.completed.map((it) => itemsMap.get(it)).filter(Boolean);\n          const incompleted = action.incompleted.map((it) => itemsMap.get(it)).filter(Boolean);\n\n          if(completed.length === 0) {\n            icon = Icon('checklist_undone');\n            langPackKey = `ChecklistMarkedUndone${message.pFlags.out ? 'You' : ''}`;\n            args = [\n              message.pFlags.out ? undefined : getNameDivHTML(message.fromId, plain),\n              joinTexts(incompleted.map((it) => wrapSomeText(it.text, plain, it.entities)), TODO_JOIN_OPTIONS)\n            ];\n            break;\n          }\n\n          if(incompleted.length === 0) {\n            icon = Icon('checklist_done');\n            langPackKey = `ChecklistMarkedDone${message.pFlags.out ? 'You' : ''}`;\n            args = [\n              message.pFlags.out ? undefined : getNameDivHTML(message.fromId, plain),\n              joinTexts(completed.map((it) => wrapSomeText(it.text, plain, it.entities)), TODO_JOIN_OPTIONS)\n            ];\n            break;\n          }\n\n          icon = Icon('checklist_done');\n          langPackKey = `ChecklistMarkedMixed${message.pFlags.out ? 'You' : ''}`;\n          args = [\n            message.pFlags.out ? undefined : getNameDivHTML(message.fromId, plain),\n            joinTexts(completed.map((it) => wrapSomeText(it.text, plain, it.entities)), TODO_JOIN_OPTIONS),\n            joinTexts(incompleted.map((it) => wrapSomeText(it.text, plain, it.entities)), TODO_JOIN_OPTIONS)\n          ];\n        }\n\n        break;\n      }\n      case 'messageActionChannelCreate': {\n        const chat = message?.peerId ? apiManagerProxy.getChat(message.peerId) : undefined;\n\n        if(chat?._ === 'channel' && chat?.pFlags?.monoforum) langPackKey = 'ActionCreateDirectMessages';\n\n        break;\n      }\n      case 'messageActionSuggestedPostApproval': {\n        if(action.pFlags.balance_too_low) {\n          langPackKey = 'SuggestedPosts.BalanceTooLow';\n          args = [wrapEmojiText('❌')];\n        } else if(action.pFlags.rejected) {\n          langPackKey = 'SuggestedPosts.GenericRejectedPost';\n          args = [wrapEmojiText('❌')];\n        } else {\n          langPackKey = 'SuggestedPosts.AgreementReached';\n          args = [wrapEmojiText('🤝')];\n        }\n        break;\n      }\n      case 'messageActionSuggestedPostSuccess': {\n        langPackKey = 'SuggestedPosts.PostSuccess';\n        args = [wrapEmojiText('✅'), i18n('Stars', [numberThousandSplitterForStars(action.price.amount)])];\n        break;\n      }\n      case 'messageActionSuggestedPostRefund': {\n        langPackKey = 'SuggestedPosts.GenericRefund';\n        break;\n      }\n      case 'messageActionSuggestBirthday': {\n        langPackKey = message.pFlags.out ? 'BirthdaySuggestOutgoing' : 'BirthdaySuggestIncoming';\n        args = [getNameDivHTML(message.peerId, plain)];\n\n        break\n      }\n      case 'messageActionStarGiftPurchaseOffer': {\n        langPackKey = message.pFlags.out ? 'StarGiftOffer.Outgoing' : 'StarGiftOffer.Incoming';\n        args = [\n          getNameDivHTML(message.peerId, plain),\n          i18n('Stars', [numberThousandSplitterForStars(action.price.amount)]),\n          getCollectibleName(action.gift as StarGift.starGiftUnique)\n        ];\n        break;\n      }\n      case 'messageActionStarGiftPurchaseOfferDeclined':\n        if(action.pFlags.expired) {\n          langPackKey = 'StarGiftOffer.ExpiredFull';\n        } else {\n          langPackKey = message.pFlags.out ? 'StarGiftOffer.RejectedFullOutgoing' : 'StarGiftOffer.RejectedFullIncoming';\n        }\n        args = [\n          getNameDivHTML(message.peerId, plain),\n          i18n('Stars', [numberThousandSplitterForStars(action.price.amount)]),\n          getCollectibleName(action.gift as StarGift.starGiftUnique)\n        ];\n        break;\n      case 'messageActionNewCreatorPending': {\n        langPackKey = 'Chat.Service.NewCreatorPending';\n        args = [\n          getNameDivHTML(action.new_creator_id.toPeerId(), plain),\n          getNameDivHTML(message.fromId, plain)\n        ];\n        break;\n      }\n      case 'messageActionChangeCreator': {\n        langPackKey = 'Chat.Service.ChangeCreator';\n        args = [\n          getNameDivHTML(message.fromId, plain),\n          getNameDivHTML(action.new_creator_id.toPeerId(), plain)\n        ];\n        break;\n      }\n      case 'messageActionBoostApply': {\n        langPackKey = 'UserBoostedGroup';\n        args = [\n          getNameDivHTML(message.fromId, plain),\n          action.boosts\n        ];\n        break;\n      }\n      case 'messageActionNoForwardsToggle': {\n        if(action.new_value === action.prev_value) {\n          langPackKey = action.new_value ? 'SharingStillEnabled' : 'SharingStillDisabled';\n        } else {\n          langPackKey = `Chat.Service.NoForwardsToggle${message.pFlags.out ? '.You' : ''}.${action.new_value ? 'Enabled' : 'Disabled'}` as const;\n        }\n        args = [getNameDivHTML(message.fromId, plain)];\n        break;\n      }\n      case 'messageActionNoForwardsRequest': {\n        if(action.pFlags.expired) {\n          langPackKey = 'EnableSharingRequested.Expired';\n        } else {\n          langPackKey = `Chat.Service.NoForwardsRequest${message.pFlags.out ? '.You' : ''}.${action.new_value ? 'Enable' : 'Disable'}` as const;\n          args = [getNameDivHTML(message.fromId, plain)];\n        }\n        break;\n      }\n      case 'messageActionPollAppendAnswer': {\n        const truncatedAnswerText = wrapTruncatedText(action.answer.text.text, action.answer.text.entities, MAX_ANSWER_TEXT_LENGTH);\n\n        if(message.pFlags.out) {\n          langPackKey = 'Chat.Poll.OptionAddedMe';\n          args = [truncatedAnswerText];\n        } else {\n          langPackKey = 'Chat.Poll.OptionAdded';\n          args = [getNameDivHTML(message.fromId, plain), truncatedAnswerText];\n        }\n        break;\n      }\n      case 'messageActionPollDeleteAnswer': {\n        const truncatedAnswerText = wrapTruncatedText(action.answer.text.text, action.answer.text.entities, MAX_ANSWER_TEXT_LENGTH);\n        if(message.pFlags.out) {\n          langPackKey = 'Chat.Poll.OptionDeletedMe';\n          args = [truncatedAnswerText];\n        } else {\n          langPackKey = 'Chat.Poll.OptionDeleted';\n          args = [getNameDivHTML(message.fromId, plain), truncatedAnswerText];\n        }\n        break;\n      }\n      case 'messageActionManagedBotCreated': {\n        langPackKey = 'CreateBot.BotWasCreated';\n        args = [getNameDivHTML(action.bot_id.toPeerId(), plain)];\n        break;\n      }\n      default:\n        langPackKey = (langPack[_] || `[${action._}]`) as any;\n        break;\n    }\n\n    if(!langPackKey) {\n      langPackKey = langPack[_];\n      if(langPackKey === undefined) {\n        langPackKey = '[' + _ + ']' as any;\n      }\n    }\n\n    const waited = args && await Promise.all(args);\n\n    if(plain) {\n      return I18n.format(langPackKey, true, waited);\n    } else {\n      // if(waited && noLinks) {\n      //   waited = waited.map((arg) => arg instanceof HTMLAnchorElement ? arg.textContent : arg);\n      // }\n\n      const res = _i18n(element, langPackKey, waited);\n      if(icon) {\n        icon.classList.add('message-action-icon')\n        res.prepend(icon);\n      }\n      return res;\n    }\n\n    // str = !langPackKey || langPackKey[0].toUpperCase() === langPackKey[0] ? langPackKey : getNameDivHTML(message.fromId) + langPackKey + (suffix ? ' ' : '');\n  }\n}\n","export default function documentFragmentToNodes(fragment: DocumentFragment) {\n  const nodes: (Node | string)[] = new Array(fragment.childNodes.length);\n  let node = fragment.firstChild;\n  let i = 0;\n  while(node) {\n    nodes[i++] = node.nodeType === node.TEXT_NODE ? node.nodeValue : node;\n    node = node.nextSibling;\n  }\n  return nodes;\n}\n","export type DashedCircleSection = {\n  color: CanvasFillStrokeStyles['strokeStyle'],\n  length: number,\n  lineWidth: number\n};\nexport default class DashedCircle {\n  public canvas: HTMLCanvasElement;\n  public context: CanvasRenderingContext2D;\n  public dpr: number;\n\n  private width: number;\n  private height: number;\n  private centerX: number;\n  private centerY: number;\n  private radius: number;\n  private gapLength: number;\n  private totalLength: number;\n  private startAngle: number;\n\n  constructor() {\n    this.canvas = document.createElement('canvas');\n    this.context = this.canvas.getContext('2d');\n    this.dpr = window.devicePixelRatio;\n  }\n\n  public prepare(options: {\n    radius: number,\n    gap: number,\n    width: number,\n    height: number\n  }) {\n    this.canvas.width = this.width = options.width * this.dpr;\n    this.canvas.height = this.height = options.height * this.dpr;\n\n    this.centerX = this.width / 2;\n    this.centerY = this.height / 2;\n    this.radius = options.radius * this.dpr - 0.5;\n    this.gapLength = options.gap * this.dpr;\n    this.totalLength = Math.PI * this.radius * 2;\n    // this.startAngle = -1.5 + this.gapLength * 0 / this.totalLength;\n    this.startAngle = -1.5;\n  }\n\n  public render(sections: DashedCircleSection[]) {\n    this.context.clearRect(0, 0, this.width, this.height);\n\n    const totalSegments = sections.reduce((acc, section) => acc + section.length, 0);\n    const totalSections = sections.length;\n    this.context.lineCap = 'round';\n    if(sections.length === 1 && sections[0].length === 1) {\n      this.context.setLineDash([]);\n    } else {\n      this.context.setLineDash([this.totalLength / totalSegments - this.gapLength, this.gapLength]);\n    }\n\n    let partSum = 0;\n    for(let i = 0; i < totalSections; ++i) {\n      const section = sections[i];\n      const part = section.length / totalSegments;\n      const sectionStartAngle = this.startAngle + partSum * 2 * Math.PI;\n      const sectionEndAngle = sectionStartAngle + part * 2 * Math.PI;\n\n      this.context.beginPath();\n      this.context.arc(\n        this.centerX,\n        this.centerY,\n        this.radius,\n        sectionStartAngle,\n        sectionEndAngle,\n        false\n      );\n      this.context.strokeStyle = section.color;\n      this.context.lineWidth = section.lineWidth * this.dpr;\n      this.context.stroke();\n\n      partSum += part;\n    }\n  };\n}\n","import {subscribeOn} from '@helpers/solid/subscribeOn';\nimport themeController from '@helpers/themeController';\nimport rootScope from '@lib/rootScope';\nimport {createSignal} from 'solid-js';\n\nexport default function useIsNightTheme() {\n  const [isNight, setIsNight] = createSignal<boolean>(themeController.isNight());\n  subscribeOn(rootScope)('theme_changed', () => {\n    setIsNight(themeController.isNight());\n  });\n  return isNight;\n}\n","import classNames from '@helpers/string/classNames';\n\nfunction Path1(props: {stroke?: boolean}) {\n  return (\n    <path class={props.stroke && 'currency-star-icon-stroke'} d=\"M8.7221 7.50194L11.1473 2.67049C11.4277 2.11345 12.106 1.88988 12.6593 2.17029C12.8753 2.28018 13.0496 2.45828 13.1595 2.67807L15.452 7.339C15.6377 7.72173 16.0053 7.97941 16.4259 8.02867L21.2195 8.60465C21.8712 8.68423 22.3373 9.27916 22.2615 9.93473C22.2274 10.2038 22.1062 10.4539 21.9129 10.6433L18.1198 14.3835C17.9644 14.535 17.8924 14.7472 17.9189 14.9632L18.5517 20.0107C18.6427 20.7345 18.1311 21.3938 17.4111 21.4848C17.1383 21.5189 16.8655 21.4696 16.623 21.337L12.6176 19.1467C12.3258 18.9876 11.9772 18.9838 11.6854 19.1353L7.53223 21.265C6.94867 21.5643 6.23627 21.3294 5.93691 20.742C5.82322 20.5222 5.78533 20.2759 5.81944 20.0334L6.14911 17.7143C6.31205 16.5813 7.01309 15.5961 8.02864 15.0769L12.6365 12.7237C12.7578 12.6631 12.807 12.5115 12.7464 12.3865C12.6972 12.2917 12.5948 12.2349 12.4887 12.25L6.85015 13.061C5.98996 13.1822 5.1184 12.9397 4.4401 12.3865L2.56436 10.8555C2.03006 10.4198 1.9429 9.624 2.37868 9.08591C2.58331 8.83581 2.87509 8.67286 3.1934 8.63118L8.00591 8.01351C8.31285 7.97183 8.58189 7.78236 8.7221 7.50194Z\" fill=\"url(#paint0_linear_6651_5783)\"/>\n  );\n}\n\nexport default function currencyStarIcon(props: {class?: string, stroke?: boolean} = {}) {\n  return (\n    <svg class={classNames('currency-star-icon', props.class)} width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      {pr