efaultOptionsArgs): Option[] => [\n  {\n    value: 0,\n    label: offLabel\n  },\n  makeOption(oneDayInSeconds, 1, DurationType.Days),\n  makeOption(oneWeekInSeconds, 1, DurationType.Weeks),\n  makeOption(oneMonthInSeconds, 1, DurationType.Months)\n];\n\nexport const customTimeOptions: DetailedOption[] = [\n  makeOption(oneDayInSeconds, 1, DurationType.Days),\n  makeOption(oneDayInSeconds * 2, 2, DurationType.Days),\n  makeOption(oneDayInSeconds * 3, 3, DurationType.Days),\n  makeOption(oneDayInSeconds * 4, 4, DurationType.Days),\n  makeOption(oneDayInSeconds * 5, 5, DurationType.Days),\n  makeOption(oneDayInSeconds * 6, 6, DurationType.Days),\n  makeOption(oneWeekInSeconds, 1, DurationType.Weeks),\n  makeOption(oneWeekInSeconds * 2, 2, DurationType.Weeks),\n  makeOption(oneWeekInSeconds * 3, 3, DurationType.Weeks),\n  makeOption(oneMonthInSeconds, 1, DurationType.Months),\n  makeOption(oneMonthInSeconds * 2, 2, DurationType.Months),\n  makeOption(oneMonthInSeconds * 3, 3, DurationType.Months),\n  makeOption(oneMonthInSeconds * 4, 4, DurationType.Months),\n  makeOption(oneMonthInSeconds * 5, 5, DurationType.Months),\n  makeOption(oneMonthInSeconds * 6, 6, DurationType.Months),\n  makeOption(oneYearInSeconds, 1, DurationType.Years)\n];\n\nexport const allTimeOptionsForAutoDeleteIcon = [\n  makeOption(oneHourInSeconds, 1, DurationType.Hours),\n  makeOption(oneHourInSeconds * 2, 2, DurationType.Hours),\n  makeOption(oneHourInSeconds * 3, 3, DurationType.Hours),\n  makeOption(oneHourInSeconds * 4, 4, DurationType.Hours),\n  makeOption(oneHourInSeconds * 5, 5, DurationType.Hours),\n  makeOption(oneHourInSeconds * 6, 6, DurationType.Hours),\n  makeOption(oneHourInSeconds * 7, 7, DurationType.Hours),\n  makeOption(oneHourInSeconds * 8, 8, DurationType.Hours),\n  ...customTimeOptions\n];\n\nexport function findBestMatchingOption<T extends Option>(period: number, options: T[]) {\n  const threshold = 0.1;\n  const isCloseTo = (period: number, targetPeriod: number) => targetPeriod > 0 && Math.abs(period - targetPeriod) / targetPeriod < threshold;\n\n  for(const option of options) {\n    if(isCloseTo(period, option.value)) return option;\n  }\n\n  return null;\n}\n\nexport function findMatchingCustomOption(period: number) {\n  return findBestMatchingOption(period, customTimeOptions);\n}\n\nexport function findMatchingAutoDeleteIconOption(period: number) {\n  return findBestMatchingOption(period, allTimeOptionsForAutoDeleteIcon);\n}\n\nexport function findExistingOrCreateCustomOption(period: number): Option {\n  return findMatchingCustomOption(period) || {\n    label: () => wrapFormattedDuration(formatDuration(period)),\n    value: period\n  };\n}\n","import {DurationType} from '@helpers/formatDuration';\nimport Icon, {OverlayedIcon} from './icon';\nimport {findMatchingAutoDeleteIconOption} from './sidebarLeft/tabs/autoDeleteMessages/options';\n\nconst shiftedIcons = [DurationType.Days, DurationType.Years]\n\nconst typeToIcon: Partial<Record<DurationType, Icon>> = {\n  [DurationType.Hours]: 'auto_delete_circle_hours',\n  [DurationType.Days]: 'auto_delete_circle_days',\n  [DurationType.Weeks]: 'auto_delete_circle_weeks',\n  [DurationType.Months]: 'auto_delete_circle_months',\n  [DurationType.Years]: 'auto_delete_circle_years'\n};\n\nconst durationToIcon: Partial<Record<number, Icon>> = {\n  1: 'auto_delete_circle_1',\n  2: 'auto_delete_circle_2',\n  3: 'auto_delete_circle_3',\n  4: 'auto_delete_circle_4',\n  5: 'auto_delete_circle_5',\n  6: 'auto_delete_circle_6',\n  7: 'auto_delete_circle_7',\n  8: 'auto_delete_circle_8'\n};\n\nexport function createAutoDeleteIcon(period?: number) {\n  const defaultResult = () => Icon('auto_delete_circle_clock');\n\n  if(!period) return defaultResult();\n\n  const option = findMatchingAutoDeleteIconOption(period);\n  if(!option) return defaultResult();\n\n  const durationIcon = durationToIcon[option.duration];\n  const typeIcon = typeToIcon[option.type];\n\n  if(!durationIcon || !typeIcon) return defaultResult();\n\n  const isShifted = shiftedIcons.includes(option.type);\n\n  return OverlayedIcon(\n    [\n      'auto_delete_circle_empty',\n      {\n        icon: durationIcon,\n        className: isShifted ? 'auto-delete-icon--shifted' : undefined\n      },\n      {\n        icon: typeIcon,\n        className: isShifted ? 'auto-delete-icon--shifted' : undefined\n      }\n    ],\n  );\n}\n","// Creates a muted, looping, inline <video> set up to autoplay an avatar clip.\n//\n// IMPORTANT: every autoplay-relevant property/attribute is set BEFORE assigning\n// `src`. Chrome evaluates the autoplay policy the moment the source starts\n// loading — if `muted` isn't already true at that point, autoplay is blocked\n// (the element then only plays on an explicit play()). Setting src last (and\n// retrying play() on canplay/loadeddata) makes muted autoplay reliable.\n//\n// `startTime` (seconds) is the animated profile photo's video_start_ts: official\n// clients begin playback at that frame so the moving clip continues the static\n// cover, then native-loop back to 0 (tdesktop video_userpic_player.cpp:138,\n// iOS PeerAvatarImageGalleryItem.swift:365). We seek to it once metadata is in.\nexport default function createLoopingMutedVideo(url: string, className?: string, startTime?: number) {\n  const v = document.createElement('video');\n  if(className) v.className = className;\n\n  v.muted = true;\n  v.loop = true;\n  v.playsInline = true;\n  v.preload = 'auto';\n  v.setAttribute('muted', '');\n  v.setAttribute('playsinline', '');\n  v.setAttribute('disableremoteplayback', '');\n\n  const tryPlay = () => {\n    v.play().catch(() => {});\n  };\n\n  const seekTo = startTime > 0 ? startTime : 0;\n\n  if(seekTo) {\n    // Don't autoplay from 0 — seek to video_start_ts first (once the duration is\n    // known), then play; native loop wraps subsequent passes back to 0.\n    v.addEventListener('loadedmetadata', () => {\n      try {\n        v.currentTime = Math.min(seekTo, v.duration || seekTo);\n      } catch{}\n      tryPlay();\n      // Flag it as autoplay only AFTER the seek — setting it before src (like the\n      // no-seek branch) would make the browser start at frame 0 and flash it\n      // before the cover frame. The flag itself is just a marker so a pause/resume\n      // manager (e.g. animationIntersector) knows the clip is meant to be playing.\n      v.autoplay = true;\n    }, {once: true});\n    v.addEventListener('canplay', tryPlay, {once: true}); // backstop\n  } else {\n    v.autoplay = true;\n    v.addEventListener('loadeddata', tryPlay, {once: true});\n    v.addEventListener('canplay', tryPlay, {once: true});\n  }\n\n  v.src = url; // assign last so the autoplay policy sees muted=true\n  if(!seekTo) tryPlay();\n\n  return v;\n}\n","import type LazyLoadQueue from '@components/lazyLoadQueue';\nimport type {PeerPhotoSize} from '@appManagers/appAvatarsManager';\nimport type {StoriesSegment, StoriesSegments} from '@appManagers/appStoriesManager';\nimport {getMiddleware, type Middleware} from '@helpers/middleware';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {\n  createSignal,\n  createEffect,\n  createMemo,\n  onCleanup,\n  JSX,\n  createRoot,\n  Show,\n  Accessor,\n  on,\n  createComputed\n} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport {NULL_PEER_ID, REPLIES_PEER_ID, HIDDEN_PEER_ID} from '@appManagers/constants';\nimport {Chat, ChatPhoto, PhotoSize, User, UserProfilePhoto} from '@layer';\nimport {getPeerAvatarColorByPeer} from '@appManagers/utils/peers/getPeerColorById';\nimport getPeerPhoto from '@appManagers/utils/peers/getPeerPhoto';\nimport wrapAbbreviation from '@lib/richTextProcessor/wrapAbbreviation';\nimport getPeerInitials from '@components/wrappers/getPeerInitials';\nimport liteMode from '@helpers/liteMode';\nimport renderImageFromUrl, {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport getPreviewURLFromBytes from '@helpers/bytes/getPreviewURLFromBytes';\nimport classNames from '@helpers/string/classNames';\nimport {wrapTopicIcon} from '@components/wrappers/messageActionTextNewUnsafe';\nimport {Modify} from '@types';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport DashedCircle, {DashedCircleSection} from '@helpers/canvas/dashedCircle';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {AckedResult} from '@lib/superMessagePort';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport callbackify from '@helpers/callbackify';\nimport Icon from '@components/icon';\nimport wrapPhoto from '@components/wrappers/photo';\nimport customProperties from '@helpers/dom/customProperties';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\nimport currencyStarIcon from '@components/currencyStarIcon';\nimport type {ActiveAccountNumber} from '@lib/accounts/types';\nimport {getCurrentAccount} from '@lib/accounts/getCurrentAccount';\nimport {appSettings} from '@stores/appSettings';\nimport {createAutoDeleteIcon} from '@components/autoDeleteIcon';\nimport {resolveElements} from '@solid-primitives/refs';\nimport toArray from '@helpers/array/toArray';\nimport computeLockColor from '@helpers/computeLockColor';\nimport createLoopingMutedVideo from '@helpers/dom/createLoopingMutedVideo';\nimport animationIntersector from '@components/animationIntersector';\n\nconst FADE_IN_DURATION = 200;\nconst TEST_SWAPPING = 0;\n\nconst avatarsMap: Map<string, Set<ReturnType<typeof AvatarNew>>> = new Map();\nconst believeMe: Map<string, Set<ReturnType<typeof AvatarNew>>> = new Map();\nconst seen: Set<PeerId> = new Set();\n\nfunction getAvatarQueueKey(peerId: PeerId, threadId?: number) {\n  return peerId + (threadId ? '_' + threadId : '');\n}\n\nconst onAvatarUpdate = ({peerId, threadId}: {peerId: PeerId, threadId?: number}) => {\n  const key = getAvatarQueueKey(peerId, threadId);\n  const set = avatarsMap.get(key);\n  if(!set?.size) {\n    return;\n  }\n\n  for(const avatar of set) {\n    avatar.render();\n  }\n};\n\nconst onAvatarStoriesUpdate = ({peerId}: {peerId: PeerId}) => {\n  const key = getAvatarQueueKey(peerId);\n  const set = avatarsMap.get(key);\n  if(!set?.size) {\n    return;\n  }\n\n  for(const avatar of set) {\n    avatar.updateStoriesSegments();\n  }\n};\n\nrootScope.addEventListener('avatar_update', onAvatarUpdate);\nrootScope.addEventListener('peer_title_edit', async(data) => {\n  if(!data.threadId && (await rootScope.managers.appAvatarsManager.isAvatarCached(data.peerId))) return;\n\n  onAvatarUpdate(data);\n});\n\nrootScope.addEventListener('peer_stories', ({peerId}) => {\n  onAvatarStoriesUpdate({peerId});\n});\nrootScope.addEventListener('stories_read', onAvatarStoriesUpdate);\nrootScope.addEventListener('story_deleted', onAvatarStoriesUpdate);\nrootScope.addEventListener('story_new', onAvatarStoriesUpdate);\n\n\nconst getStoriesSegments = async(peerId: PeerId, storyId?: number): Promise<AckedResult<StoriesSegments>> => {\n  if(storyId) {\n    const storyUnreadType = await rootScope.managers.appStoriesManager.getUnreadType(peerId, storyId);\n\n    const segments: StoriesSegments = [{\n      length: 1,\n      type: storyUnreadType\n    }];\n\n    return {\n      cached: true,\n      result: Promise.resolve(segments)\n    };\n  }\n\n  return rootScope.managers.acknowledged.appStoriesManager.getPeerStoriesSegments(peerId);\n};\n\nconst createUnreadGradient = (context: CanvasRenderingContext2D, size: number, dpr: number) => {\n  const gradient = context.createLinearGradient(\n    size * 0.9156 * dpr,\n    size * -0.05695821429 * dpr,\n    size * 0.1342364286 * dpr,\n    size * 1.02370714286 * dpr\n  );\n  gradient.addColorStop(0, customProperties.getProperty('avatar-color-story-unread-from'));\n  gradient.addColorStop(1, customProperties.getProperty('avatar-color-story-unread-to'));\n  return gradient;\n};\n\nconst createCloseGradient = (context: CanvasRenderingContext2D, size: number, dpr: number) => {\n  const gradient = context.createLinearGradient(\n    size * 0.5 * dpr,\n    size * 0 * dpr,\n    size * 0.5 * dpr,\n    size * 1 * dpr\n  );\n  gradient.addColorStop(0, customProperties.getProperty('avatar-color-story-close-from'));\n  gradient.addColorStop(1, customProperties.getProperty('avatar-color-story-close-to'));\n  return gradient;\n};\n\nexport function findUpAvatar(target: Element | EventTarget) {\n  let avatar = findUpClassName(target, 'avatar');\n  if(avatar) avatar = findUpClassName(avatar, 'has-stories') || avatar;\n  return avatar;\n}\n\nasync function loadAvatarVideoOverlay(\n  peerId: PeerId,\n  photo: UserProfilePhoto.userProfilePhoto | ChatPhoto.chatPhoto,\n  node: HTMLElement,\n  middleware: Middleware,\n  videoSize: PeerPhotoSize = 'photo_video'\n): Promise<HTMLVideoElement | undefined> {\n  // Load the URL and the video_start_ts (cover/start frame) in parallel so\n  // playback can begin at that frame, matching the static cover.\n  const [url, videoStartTs] = await Promise.all([\n    Promise.resolve(apiManagerProxy.loadAvatar(peerId, photo, videoSize)),\n    rootScope.managers.appAvatarsManager.getAvatarVideoStartTs(peerId, photo, videoSize === 'photo_video_full').catch((): number => undefined)\n  ]);\n  if(!url || !middleware()) return undefined;\n\n  // Muted-autoplay setup with src assigned last (see helper) — retry on\n  // canplay/loadeddata covers the \"interrupted by a new load request\" reject.\n  const v = createLoopingMutedVideo(url, 'avatar-photo avatar-video', videoStartTs);\n\n  // Don't animate while the avatar isn't visible — scrolled off the chat list,\n  // or sitting in the right sidebar while it's slid closed (the column is moved\n  // off-screen with a transform but stays mounted). Hand the <video> to the\n  // app-wide animation intersector instead of an ad-hoc IntersectionObserver:\n  // it pauses on off-screen / blur / idle / lite-mode and resumes when visible,\n  // and stays correct across Document-PiP window moves. Observe the <video>\n  // itself (like wrappers/video.ts) so it auto-unregisters when swapped/removed.\n  animationIntersector.addAnimation({\n    animation: v,\n    observeElement: v,\n    type: 'video'\n  });\n\n  middleware.onDestroy(() => {\n    animationIntersector.removeAnimationByPlayer(v);\n    v.pause();\n    v.src = '';\n    v.load();\n  });\n\n  return v;\n}\n\nconst calculateSegmentsDimensions = (s: number) => {\n  const willBeSize = Math.round(s * (1 - 6 / 54));\n  const totalSvgSize = s * (1 + 2 / 54);\n  const multiplier = s / 54;\n  const strokeWidth = 2 * multiplier;\n\n  return {\n    size: s,\n    willBeSize,\n    totalSvgSize,\n    multiplier,\n    strokeWidth\n  };\n};\n\nexport function wrapPhotoToAvatar(\n  avatarElem: ReturnType<typeof avatarNew>,\n  photo: Parameters<typeof wrapPhoto>[0]['photo'],\n  boxSize: number = 100,\n  photoSize?: PhotoSize\n) {\n  // The profile re-mounts its avatar several times while peer data loads. If the\n  // full photo is already cached, skip the appearance fade so the re-mounts are\n  // seamless instead of replaying the fade-in (avatar \"blinking\" away and back).\n  // The first, uncached load still fades in normally.\n  const cacheContext = apiManagerProxy.getCacheContext(photo as any, photoSize?.type);\n  return wrapPhoto({\n    container: avatarElem.node,\n    message: null,\n    photo,\n    boxHeight: boxSize,\n    boxWidth: boxSize,\n    withoutPreloader: true,\n    size: photoSize,\n    noFadeIn: !!cacheContext?.downloaded\n  }).then((result) => {\n    avatarElem.node.classList.replace('media-container', 'avatar-relative');\n    avatarElem.node.style.width = avatarElem.node.style.height = '';\n    [result.images.thumb, result.images.full].forEach((image) => {\n      if(!image) {\n        return;\n      }\n\n      image.classList.replace('media-photo', 'avatar-photo');\n    });\n\n    if(result.images.thumb) {\n      result.images.thumb.classList.add('avatar-photo-thumbnail');\n    }\n\n    // For photos that include a video variant (animated profile photo), overlay\n    // a muted looping <video> on top of the still image once it is loaded.\n    if((photo as any)?.video_sizes?.length) {\n      attachAvatarVideoFromPhoto(avatarElem.node, photo as any);\n    }\n\n    return result.loadPromises.thumb;\n  });\n}\n\nasync function attachAvatarVideoFromPhoto(container: HTMLElement, photo: import('@layer').Photo.photo) {\n  const [{default: chooseProfileVideoSize}, {default: appDownloadManager}] = await Promise.all([\n    import('@appManagers/utils/photos/chooseProfileVideoSize'),\n    import('@lib/appDownloadManager')\n  ]);\n  const videoSize = chooseProfileVideoSize(photo, 'full');\n  if(!videoSize) return;\n\n  const url = await appDownloadManager.downloadMediaURL({\n    media: photo,\n    thumb: videoSize\n  });\n\n  const v = createLoopingMutedVideo(url, 'avatar-photo avatar-video', videoSize.video_start_ts);\n  container.appendChild(v);\n\n  // Same as loadAvatarVideoOverlay: pause this looping avatar video whenever it\n  // isn't visible (e.g. the profile carousel in the right sidebar while it's\n  // closed, or a service-message bubble scrolled out of the chat) via the\n  // app-wide intersector. No middleware here — it auto-unregisters once the\n  // observed <video> leaves the DOM.\n  animationIntersector.addAnimation({\n    animation: v,\n    observeElement: v,\n    type: 'video'\n  });\n}\n\nexport function StoriesSegments(props: {\n  size: number,\n  colors: Partial<{\n    read: string\n  }>,\n  simple?: boolean,\n  isStoryFolded?: Accessor<boolean>,\n}) {\n  const [storiesSegments, setStoriesSegments] = createSignal<StoriesSegments>();\n  const storyDimensions: Accessor<ReturnType<typeof calculateSegmentsDimensions>> = createMemo((previousDimensions) => {\n    if(storiesSegments() === undefined) {\n      return;\n    }\n\n    if(previousDimensions?.size === props.size) {\n      return previousDimensions;\n    }\n\n    return calculateSegmentsDimensions(props.size as number);\n  });\n  const storiesCircle = createMemo(() => {\n    // if(isStoryFolded()) {\n    //   return;\n    // }\n\n    const dimensions = storyDimensions();\n    if(!dimensions) {\n      return;\n    }\n\n    let simple: JSX.Element;\n    if(props.isStoryFolded !== undefined || props.simple) {\n      const status = createMemo(() => {\n        const segments = storiesSegments();\n        const firstCloseSegment = segments.find((segment) => segment.type === 'close');\n        const segment = firstCloseSegment || segments.find((segment) => segment.type === 'unread') || segments[0];\n        return segment.type;\n      });\n\n      simple = (\n        <div\n          class=\"avatar-stories-simple\"\n          classList={{['is-' + status()]: true}}\n        >\n\n        </div>\n      );\n      if(props.simple) return simple;\n    }\n\n    const segmentToSection = (segment: StoriesSegment, unreadAsClose?: boolean): DashedCircleSection => {\n      if(segment.type === 'read') {\n        return {\n          color: props.colors?.read || customProperties.getProperty('avatar-color-story-read'),\n          length: segment.length,\n          lineWidth: dimensions.strokeWidth / 2\n        };\n      }\n\n      if(segment.type === 'close' || unreadAsClose) {\n        return {\n          color: closeGradient ??= createCloseGradient(context, canvas.width, dpr),\n          length: segment.length,\n          lineWidth: dimensions.strokeWidth\n        };\n      } else {\n        return {\n          color: unreadGradient ??= createUnreadGradient(context, canvas.width, dpr),\n          length: segment.length,\n          lineWidth: dimensions.strokeWidth\n        };\n      }\n    };\n\n    const dashedCircle = new DashedCircle();\n    const {canvas, context, dpr} = dashedCircle;\n    dashedCircle.prepare({\n      radius: dimensions.size / 2,\n      gap: 4 * dimensions.multiplier,\n      width: dimensions.totalSvgSize,\n      height: dimensions.totalSvgSize\n    });\n\n    let unreadGradient: CanvasGradient, closeGradient: CanvasGradient;\n    canvas.style.setProperty('--offset', `${(dimensions.totalSvgSize - dimensions.size) / -2}px`);\n    canvas.classList.add('avatar-stories-svg');\n\n    const render = () => {\n      const segments = storiesSegments();\n      const firstCloseSegment = segments.find((segment) => segment.type === 'close');\n      let sections = segments.map((segment) => segmentToSection(segment, !!firstCloseSegment));\n      const totalLength = sections.reduce((sum, section) => sum + section.length, 0);\n      if(totalLength > 30) {\n        sections = sections.map((section) => ({\n          ...section,\n          length: Math.floor(section.length / totalLength * 30)\n        })).filter((section) => section.length > 0);\n      }\n\n      dashedCircle.render(sections);\n    };\n\n    const isNightTheme = useIsNightTheme();\n    createEffect(on(\n      [isNightTheme, storiesSegments],\n      () => {\n        unreadGradient = closeGradient = undefined;\n        render();\n      }\n    ));\n\n    return simple ? (\n      <>\n        {canvas}\n        {simple}\n      </>\n    ) : canvas;\n  });\n\n  return {setStoriesSegments, storyDimensions, storiesCircle};\n}\n\nexport const AvatarNew = (props: {\n  accountNumber?: ActiveAccountNumber,\n  peerId?: PeerId,\n  threadId?: number,\n  isDialog?: boolean,\n  isBig?: boolean,\n  withVideoAvatar?: boolean,\n  noFadeIn?: boolean,\n  isSubscribed?: boolean,\n  peerTitle?: string,\n  lazyLoadQueue?: LazyLoadQueue | false,\n  wrapOptions?: WrapSomethingOptions,\n  withStories?: boolean,\n  storyId?: number,\n  useCache?: boolean,\n  size: number | 'full',\n  props?: JSX.HTMLAttributes<HTMLDivElement>,\n  storyColors?: Parameters<typeof StoriesSegments>[0]['colors'],\n  peer?: Chat.channel | Chat.chat | User.user,\n  isStoryFolded?: Accessor<boolean>,\n  processImageOnLoad?: (image: HTMLImageElement) => void,\n  meAsNotes?: boolean,\n  asAllChats?: boolean,\n  autoDeletePeriod?: number,\n  onStoriesStatus?: (has: boolean) => void,\n  class?: string\n}) => {\n  const [ready, setReady] = createSignal(false);\n  const [icon, setIcon] = createSignal<Icon>();\n  const [media, setMedia] = createSignal<JSX.Element>();\n  const [video, setVideo] = createSignal<JSX.Element>();\n  const [thumb, setThumb] = createSignal<JSX.Element>();\n  const [abbreviature, setAbbreviature] = createSignal<JSX.Element>();\n  const [color, setColor] = createSignal<string>();\n  const [isForum, setIsForum] = createSignal(false);\n  const [isTopic, setIsTopic] = createSignal(false);\n  const [isMonoforum, setIsMonoforum] = createSignal(false);\n  const [isSubscribed, setIsSubscribed] = createSignal(false);\n  const {setStoriesSegments, storyDimensions, storiesCircle} = StoriesSegments({\n    size: props.size as number,\n    colors: props.storyColors,\n    isStoryFolded: props.isStoryFolded\n  });\n\n  const [autoDeletePeriod, setAutoDeletePeriod] = createSignal<number>();\n\n  createComputed(() => setAutoDeletePeriod(props.autoDeletePeriod ?? 0));\n\n  const autoDeletePeriodBackground = createMemo(() => {\n    if(!autoDeletePeriod()) return;\n\n    const mediaElement = toArray(resolveElements(media, (el) => el instanceof HTMLImageElement)())[0];\n    if(!mediaElement) return;\n\n    const smallSize = 20;\n\n    const canvas = document.createElement('canvas');\n    canvas.width = smallSize;\n    canvas.height = smallSize;\n\n    const imgW = mediaElement.naturalWidth;\n    const imgH = mediaElement.naturalHeight;\n\n    const ctx = canvas.getContext('2d');\n    ctx.drawImage(\n      mediaElement,\n      imgW * 0.75, imgH * 0.75, imgW * 0.25, imgH * 0.25,\n      0, 0, smallSize, smallSize\n    );\n\n    return computeLockColor(canvas);\n  });\n\n  const readyPromise = deferredPromise<void>();\n  const readyThumbPromise = deferredPromise<void>();\n  const myId = rootScope.myId;\n  const managers = rootScope.managers;\n  const middlewareHelper = props.wrapOptions?.middleware ? props.wrapOptions.middleware.create() : getMiddleware();\n  let addedToQueue = false, lastRenderPromise: ReturnType<typeof _render>;\n\n  onCleanup(() => {\n    lastRenderPromise = undefined;\n    middlewareHelper.destroy();\n    readyPromise.resolve();\n    cleanLastKey();\n\n    (props.lazyLoadQueue as LazyLoadQueue)?.delete({div: node});\n  });\n\n  // const owner = getOwner();\n\n  const _setMedia = (media?: JSX.Element) => {\n    setMedia(media);\n    setReady(true);\n    readyPromise.resolve();\n    readyThumbPromise.resolve();\n  };\n\n  const _setThumb = (thumb?: JSX.Element) => {\n    setThumb(thumb);\n    setReady(true);\n    readyThumbPromise.resolve();\n  };\n\n  const getKey = () => getAvatarQueueKey(props.peerId, props.threadId);\n  const cleanLastKey = () => {\n    if(!lastKey) {\n      return;\n    }\n\n    const set = believeMe.get(lastKey);\n    if(set) {\n      set.delete(this);\n      if(!set.size) {\n        believeMe.delete(lastKey);\n      }\n    }\n\n    const avatarsSet = avatarsMap.get(lastKey);\n    if(!avatarsSet?.delete(ret)) {\n      return;\n    }\n\n    if(!avatarsSet.size) {\n      avatarsMap.delete(lastKey);\n    }\n  };\n\n  const putAvatar = async(options: {\n    photo: UserProfilePhoto.userProfilePhoto | ChatPhoto.chatPhoto,\n    size: PeerPhotoSize,\n    onlyThumb?: boolean\n  }) => {\n    const middleware = middlewareHelper.get();\n    const {peerId, useCache} = props;\n    const {photo, size} = options;\n    // Drop any previously rendered video overlay — the new avatar load will\n    // re-issue the lazy video fetch if this photo also has a video variant.\n    // Must clear for the FINAL size of this avatar (photo_big for big avatars,\n    // photo_small for dialog/topbar), otherwise a recycled small avatar keeps\n    // playing the previous peer's video.\n    const finalSizeForClear: PeerPhotoSize = props.isBig ? 'photo_big' : 'photo_small';\n    if(size === finalSizeForClear) setVideo();\n    const result = apiManagerProxy.loadAvatar(peerId, photo, size, props.accountNumber);\n    const loadPromise = result;\n    const cached = !(result instanceof Promise);\n\n    const animate = !cached && liteMode.isAvailable('animations') && !props.noFadeIn;\n    let image: HTMLImageElement;\n    const element = image = document.createElement('img');\n    element.className = classNames('avatar-photo', animate && 'fade-in');\n\n    let renderThumbPromise: Promise<void>;\n    let callback: () => void;\n    let thumbImage: HTMLImageElement, thumbElement: JSX.Element;\n    if(cached) {\n      callback = () => {\n        if(!middleware()) {\n          return;\n        }\n\n        _setMedia(element);\n      };\n    } else {\n      if(size === 'photo_big') { // let's load small photo first\n        const res = await putAvatar({photo, size: 'photo_small'});\n        if(!middleware()) {\n          return;\n        }\n\n        renderThumbPromise = res.loadThumbPromise || res.loadPromise;\n        thumbImage = res.thumbImage;\n      } else if(photo.stripped_thumb) {\n        thumbElement = thumbImage = document.createElement('img');\n        thumbImage.className = 'avatar-photo avatar-photo-thumbnail';\n        const url = getPreviewURLFromBytes(photo.stripped_thumb);\n        renderThumbPromise = renderImageFromUrlPromise(\n          thumbImage,\n          url,\n          props.useCache,\n          props.processImageOnLoad\n        ).then(() => {\n          if(media() || !middleware()) {\n            return;\n          }\n\n          _setThumb(thumbElement);\n        });\n      }\n\n      callback = () => {\n        if(!middleware()) {\n          return;\n        }\n\n        _setMedia(element);\n        if(animate) {\n          setTimeout(() => {\n            image.classList.remove('fade-in');\n            setThumb();\n          }, animate ? FADE_IN_DURATION : 0);\n        } else {\n          setThumb();\n        }\n      };\n    }\n\n    const renderPromise = callbackify(loadPromise, (url) => {\n      const result = renderImageFromUrl(image, url, undefined, useCache, props.processImageOnLoad);\n      callbackify(result, callback);\n      return result instanceof Promise ? result : Promise.resolve(result);\n    });\n\n    // After the static image loads, if the photo has a video variant, lazily\n    // load and overlay the looping muted video. Played in the profile (isBig)\n    // and in opted-in surfaces (chat list / topbar via withVideoAvatar), but\n    // NOT in message bubbles. Gated by lite-mode video so power-saving disables\n    // it everywhere. The final loaded size is photo_big for big avatars and\n    // photo_small otherwise — guard on it so we trigger exactly once.\n    //\n    // In the small surfaces (chat list / topbar) a video avatar animates ONLY for a\n    // Premium USER — matching Telegram Android exactly. ImageReceiver.setForUserOrChat\n    // sets a videoLocation only when isPremiumUser(user) && has_video; its chat branch\n    // sets no video at all. So in the list/topbar non-Premium users, bots (bots can't\n    // hold Premium) and groups/channels are all STATIC — only Premium users animate.\n    // The big profile (isBig) and the avatar viewer are separate, ungated paths and\n    // animate for everyone. Owner Premium is read synchronously from the cached peers\n    // mirror, so this adds no request to the avatar-render path.\n    const finalSize: PeerPhotoSize = props.isBig ? 'photo_big' : 'photo_small';\n    const photoHasVideo = (photo._ === 'userProfilePhoto' || photo._ === 'chatPhoto') && photo.pFlags?.has_video;\n    const ownerIsPremiumUser = photo._ === 'userProfilePhoto' && !!peerId &&\n      !!apiManagerProxy.getUser(peerId.toUserId())?.pFlags?.premium;\n    const wantsVideo = (props.isBig || (props.withVideoAvatar && ownerIsPremiumUser)) &&\n      liteMode.isAvailable('video');\n    if(wantsVideo && photoHasVideo && size === finalSize) {\n      Promise.resolve(renderPromise).then(() => {\n        if(!middleware()) return;\n        // Big profile avatar gets the full-quality video ('u'); chat list /\n        // topbar use the small preview ('p') to save bandwidth.\n        const videoSize: PeerPhotoSize = props.isBig ? 'photo_video_full' : 'photo_video';\n        loadAvatarVideoOverlay(peerId, photo, node, middleware, videoSize).then((videoElement) => {\n          if(!middleware() || !videoElement) return;\n          setVideo(videoElement);\n        });\n      });\n    }\n\n    return {\n      cached,\n      loadPromise: renderPromise,\n      loadThumbPromise: cached ? renderPromise : renderThumbPromise || Promise.resolve(),\n      thumbImage,\n      thumbElement,\n      image,\n      element\n    };\n  };\n\n  const set = ({\n    abbreviature,\n    icon,\n    color,\n    isForum,\n    isTopic,\n    isSubscribed,\n    isMonoforum,\n    storiesSegments\n  }: {\n    abbreviature?: JSX.Element,\n    icon?: Icon,\n    color?: string,\n    isForum?: boolean,\n    isTopic?: boolean,\n    isSubscribed?: boolean,\n    isMonoforum?: boolean,\n    storiesSegments?: StoriesSegments\n  }) => {\n    setThumb();\n    setMedia();\n    setVideo();\n    setIcon(icon);\n    setAbbreviature(abbreviature);\n    setColor(color);\n    setIsForum(isForum);\n    setIsTopic(isTopic);\n    setIsSubscribed(isSubscribed);\n    setIsMonoforum(isMonoforum);\n    setStoriesSegments(storiesSegments);\n  };\n\n  const updateStoriesSegments = async() => {\n    if(!props.withStories || (props.peerId === rootScope.myId && props.isDialog)) {\n      return;\n    }\n\n    const segments = await (await getStoriesSegments(props.peerId, props.storyId)).result;\n    if(lastRenderPromise) {\n      const result = await lastRenderPromise;\n      await result?.loadThumbPromise;\n    }\n    setStoriesSegments(segments);\n  };\n\n  const _render = async(onlyThumb?: boolean) => {\n    const middleware = middlewareHelper.get();\n    const {isDialog, withStories, storyId, isBig, peerTitle: title, wrapOptions} = props;\n\n    let {peerId, threadId} = props;\n    if(title !== undefined) {\n      peerId = NULL_PEER_ID;\n    }\n\n    if(props.asAllChats) {\n      set({\n        icon: 'round_chats_filled'\n      });\n      return;\n    }\n\n    if(peerId === myId && isDialog) {\n      set({\n        icon: props.meAsNotes ? 'mynotes' : 'saved',\n        isForum: !props.meAsNotes && appSettings.savedAsForum\n      });\n\n      !props.meAsNotes && createRoot((dispose) => {\n        createEffect(\n          on(\n            () => appSettings.savedAsForum,\n            setIsForum,\n            {defer: true}\n          )\n        );\n\n        middleware.onDestroy(dispose);\n      });\n      return;\n    }\n\n    // * fix monoforum\n    if(threadId && apiManagerProxy.isMonoforum(peerId)) {\n      peerId = threadId;\n      threadId = undefined;\n    }\n\n    const peer = props.peer ?? apiManagerProxy.getPeer(peerId);\n    if(title) {\n      const color = getPeerAvatarColorByPeer(peer);\n      const abbr = wrapAbbreviation(title);\n      set({\n        abbreviature: documentFragmentToNodes(abbr),\n        color\n      });\n      return;\n    }\n\n    if(threadId) {\n      const topic = await managers.dialogsStorage.getForumTopic(peerId, threadId);\n      set({isTopic: true});\n\n      return wrapTopicIcon({\n        ...wrapOptions,\n        middleware,\n        topic,\n        lazyLoadQueue: false\n      }).then((icon) => {\n        _setMedia(icon);\n        return undefined as ReturnType<typeof putAvatar>;\n      });\n    }\n\n    if(!middleware()) {\n      return;\n    }\n\n    if(peerId !== NULL_PEER_ID && peerId.isUser() && (peer as User.user)?.pFlags?.deleted) {\n      set({color: 'archive', icon: 'deletedaccount'});\n      return;\n    }\n\n    const _isForum = !!(peer as Chat.channel)?.pFlags?.forum;\n    const _isSubscribed = props.isSubscribed ?? !!(peer as Chat.channel)?.subscription_until_date;\n    const storiesSegmentsResult = withStories && ((peer as User.user | Chat.channel)?.stories_max_id || storyId) && await getStoriesSegments(peerId, storyId);\n    const storiesSegments = storiesSegmentsResult?.cached ? await storiesSegmentsResult.result : undefined;\n    if(!middleware()) {\n      return;\n    }\n\n    const size: PeerPhotoSize = isBig ? 'photo_big' : 'photo_small';\n\n    const linkedMonoforumPeer = peer?._ === 'channel' && peer.pFlags?.monoforum && peer.linked_monoforum_id ? await managers.appChatsManager.getChat(peer.linked_monoforum_id.toPeerId?.()) : undefined;\n\n    const photo = getPeerPhoto(linkedMonoforumPeer || peer);\n    const avatarAvailable = !!photo;\n    const avatarRendered = avatarAvailable && !!media(); // if avatar isn't available, let's reset it\n    const sameAccount = props.accountNumber === getCurrentAccount();\n    let isAvatarCached = sameAccount && avatarAvailable && apiManagerProxy.isAvatarCached(peerId, size);\n    // A big avatar's photo_big often isn't cached on first open, but the small\n    // thumb usually is (loaded by the chat list). Treat it as cached so we render\n    // that thumb instantly instead of flashing the colour placeholder while\n    // photo_big downloads (the visible \"blink\" when opening/switching profiles).\n    if(!isAvatarCached && isBig && avatarAvailable && sameAccount) {\n      isAvatarCached = apiManagerProxy.isAvatarCached(peerId, 'photo_small');\n    }\n    if(!middleware()) {\n      return;\n    }\n\n    let isSet = false;\n    if(!avatarRendered && !isAvatarCached) {\n      let color: string;\n      if(peerId && (peerId !== myId || !isDialog)) {\n        color = getPeerAvatarColorByPeer(peer);\n      }\n\n      if(peerId === REPLIES_PEER_ID) {\n        set({color, icon: 'reply_filled'});\n        return;\n      }\n\n      if(peerId === HIDDEN_PEER_ID) {\n        set({color: 'violet', icon: 'author_hidden'});\n        return;\n      }\n\n      const abbr = /* title ? wrapAbbreviation(title) :  */getPeerInitials(peer);\n      set({\n        abbreviature: documentFragmentToNodes(abbr),\n        color,\n        isForum: _isForum,\n        isSubscribed: _isSubscribed,\n        isMonoforum: !!linkedMonoforumPeer,\n        storiesSegments\n      });\n      isSet = true;\n      // return Promise.resolve(true);\n    }\n\n    if(storiesSegmentsResult && !storiesSegmentsResult.cached) {\n      updateStoriesSegments();\n    }\n\n    if(avatarAvailable/*  && false */) {\n      const promise = putAvatar({photo, size, onlyThumb});\n      if(isSet) {\n        return promise;\n      }\n\n      const changeSegments = !!storiesSegments;\n      const changeForum = _isForum !== isForum();\n      const changeIsSubcribed = _isSubscribed !== isSubscribed();\n      promise.then(({loadThumbPromise}) => loadThumbPromise).then(() => {\n        if(!middleware()) {\n          return;\n        }\n\n        if(changeSegments) {\n          setStoriesSegments(storiesSegments);\n        }\n\n        if(changeForum) {\n          setIsForum(_isForum);\n        }\n\n        if(changeIsSubcribed) {\n          setIsSubscribed(_isSubscribed);\n        }\n\n        if(TEST_SWAPPING && peerId === TEST_SWAPPING) {\n          let i = true;\n          setInterval(() => {\n            i = !i;\n            setStoriesSegments(i ? undefined : storiesSegments);\n            console.log(media());\n          }, 3e3);\n        }\n      });\n      // recordPromise(promise, 'putAvatar-' + peerId);\n      return promise;\n    }\n  };\n\n  const processResult = (result: Awaited<ReturnType<typeof _render>>) => {\n    if(!result && !isTopic()) {\n      _setMedia();\n    }\n\n    lastRenderPromise = undefined;\n    return result;\n  };\n\n  let lastKey: string;\n  const render = async(_props?: Modify<typeof props, {size?: never, peerId?: PeerId}>) => {\n    const key = getKey();\n    if(key !== lastKey) {\n      cleanLastKey();\n      lastKey = key;\n\n      let set = avatarsMap.get(key);\n      if(!set) {\n        avatarsMap.set(key, set = new Set());\n      }\n      set.add(ret);\n    }\n\n    if(_props?.peerId !== undefined && props.peerId !== _props.peerId) {\n      node.dataset.peerId = '' + _props.peerId;\n    }\n\n    if(_props) Object.assign(props, _props);\n    middlewareHelper.clean();\n    const middleware = middlewareHelper.get();\n\n    if(props.lazyLoadQueue) {\n      if(!seen.has(props.peerId)) {\n        if(addedToQueue) return;\n        addedToQueue = true;\n\n        const key = getKey();\n        let set = believeMe.get(key);\n        if(!set) {\n          believeMe.set(key, set = new Set());\n        }\n\n        set.add(ret);\n\n        props.lazyLoadQueue.push({\n          div: node,\n          load: () => {\n            seen.add(props.peerId);\n            return render();\n          }\n        });\n\n        const promise = lastRenderPromise = _render(true);\n        const result = await promise;\n        if(!middleware()) {\n          return;\n        }\n\n        return processResult(result);\n      } else if(addedToQueue) {\n        props.lazyLoadQueue.delete({div: node});\n      }\n    }\n\n    seen.add(props.peerId);\n\n    const promise = lastRenderPromise = _render();\n\n    const set = believeMe.get(key);\n    if(set) {\n      set.delete(ret);\n      const arr = Array.from(set);\n      believeMe.delete(key);\n\n      for(let i = 0, length = arr.length; i < length; ++i) {\n        arr[i].render();\n      }\n    }\n\n    const result = await promise;\n    if(!middleware()) {\n      return;\n    }\n\n    if(addedToQueue) {\n      addedToQueue = false;\n    }\n\n    return processResult(result);\n  };\n\n  if(props.onStoriesStatus) {\n    createEffect(() => {\n      props.onStoriesStatus(!!storyDimensions());\n    });\n  }\n\n  const innerClassList = (): JSX.CustomAttributes<HTMLDivElement>['classList'] => {\n    return {\n      'is-forum': isForum(),\n      'is-topic': isTopic(),\n      'is-monoforum': isMonoforum(),\n      'is-relative': !!autoDeletePeriod(),\n      // The video overlay is absolutely positioned (inset: 0); without a\n      // positioning context it would anchor to the wrong ancestor.\n      'avatar-relative': !!thumb() || isSubscribed() || !!video()\n    };\n  };\n\n  const classList = (): JSX.CustomAttributes<HTMLDivElement>['classList'] => {\n    return {\n      ...(!storiesCircle() && innerClassList()),\n      'has-stories': !!storyDimensions()\n    };\n  };\n\n  const style = (): JSX.HTMLAttributes<HTMLDivElement>['style'] => {\n    const dimensions = storyDimensions();\n    return {\n      'padding': dimensions ? (dimensions.size - dimensions.willBeSize) / 2 + 'px' : undefined,\n      '--size': isTopic() && props.wrapOptions?.customEmojiSize?.width ? props.wrapOptions.customEmojiSize.width + 'px' : undefined\n    };\n  };\n\n  const inner = (\n    <>\n      {icon() && Icon(icon(), 'avatar-icon', 'avatar-icon-' + icon())}\n      {thumb()}\n      {[media(), abbreviature()].find(Boolean)}\n      {video()}\n      {isSubscribed() && currencyStarIcon({class: 'avatar-star', stroke: true})}\n      {autoDeletePeriod() && (\n        <div\n          class=\"avatar-auto-delete-timer\"\n        >\n          <Show when={autoDeletePeriodBackground() || color()}>\n            <div\n              class=\"avatar-auto-delete-timer__background\"\n              classList={{\n                'avatar-auto-delete-timer__background--color': !!color()\n              }}\n              style={{\n                background: autoDeletePeriodBackground() ? `url(${autoDeletePeriodBackground()})` : undefined\n              }}\n            />\n          </Show>\n          <div class=\"avatar-auto-delete-timer__icon\">\n            {createAutoDeleteIcon(autoDeletePeriod())}\n          </div>\n        </div>\n      )}\n    </>\n  );\n\n  // ! if I remove first inner div, then it will be broken\n  const wtf = (\n    <Show when={storyDimensions()} fallback={inner}>\n      <div>\n        {storiesCircle()}\n        {props.isStoryFolded !== undefined && <div class=\"avatar-background\"></div>}\n        <div\n          class={`avatar avatar-like avatar-${storyDimensions().willBeSize} avatar-gradient`}\n          classList={innerClassList()}\n          data-color={color()}\n        >\n          {inner}\n        </div>\n      </div>\n    </Show>\n  );\n\n  let node: HTMLDivElement;\n  const element = (\n    <div\n      ref={node}\n      class={`avatar avatar-like avatar-${props.size} avatar-gradient ${props.class ?? ''}`}\n      classList={classList()}\n      data-color={color()}\n      data-peer-id={props.peerId}\n      data-thread-id={props.threadId}\n      data-story-id={props.storyId}\n      style={style()}\n      {...(props.props || {})}\n    >\n      {wtf}\n    </div>\n  );\n\n  const ret = {\n    element,\n    ready,\n    readyPromise,\n    readyThumbPromise,\n    node,\n    render,\n    setIcon,\n    setStoriesSegments,\n    setIsSubscribed,\n    setAutoDeletePeriod,\n    updateStoriesSegments,\n    set,\n    color\n  };\n\n  if(\n    props.peerId !== undefined ||\n    props.peerTitle !== undefined ||\n    props.peer !== undefined\n  ) {\n    render();\n  }\n\n  // let resolved = false;\n  // readyThumbPromise.finally(() => {\n  //   resolved = true;\n  // });\n  // setTimeout(() => {\n  //   if(!resolved) {\n  //     console.error('wtf');\n  //     readyThumbPromise.resolve();\n  //   }\n  // }, 1e3);\n\n  return ret;\n};\n\nexport function AvatarNewTsx(props: Parameters<typeof AvatarNew>[0] & {class?: string}) {\n  const el = AvatarNew(props);\n  createEffect(on(() => props.peerId, () => {\n    el.render()\n  }));\n  return el.element;\n}\n\nexport function avatarNew(props: {\n  middleware: Middleware\n} & Parameters<typeof AvatarNew>[0]) {\n  return createRoot((dispose) => {\n    props.middleware.onDestroy(dispose);\n    (props.wrapOptions ??= {}).middleware = props.middleware;\n    return AvatarNew(props);\n  });\n}\n","import flatten from '@helpers/array/flatten';\nimport contextMenuController from '@helpers/contextMenuController';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {AttachClickOptions, attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {_i18n, FormatterArguments, i18n, LangPackKey} from '@lib/langPack';\nimport CheckboxField from '@components/checkboxField';\nimport {Chat, Document, User} from '@layer';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport ripple from '@components/ripple';\nimport Icon from '@components/icon';\nimport RadioForm from '@components/radioForm';\nimport wrapAttachBotIcon from '@components/wrappers/attachBotIcon';\nimport {createRoot} from 'solid-js';\nimport {AvatarNew} from '@components/avatarNew';\nimport {ActiveAccountNumber} from '@lib/accounts/types';\n\ntype ButtonMenuItemInner = Omit<Parameters<typeof ButtonMenuSync>[0], 'listenerSetter'>;\ntype AvatarInfo = {\n  accountNumber?: ActiveAccountNumber,\n  peerId?: PeerId,\n  peer?: Chat.channel | Chat.chat | User.user,\n  active?: boolean\n};\n\nexport type ButtonMenuItemOptions = {\n  id?: any;\n  icon?: Icon,\n  iconElement?: HTMLElement;\n  emptyIcon?: boolean,\n  iconDoc?: Document.document,\n  avatarInfo?: AvatarInfo,\n  danger?: boolean,\n  new?: boolean,\n  className?: string,\n  text?: LangPackKey,\n  textArgs?: FormatterArguments,\n  regularText?: Parameters<typeof setInnerHTML>[1],\n  onClick: (e: MouseEvent | TouchEvent) => any,\n  checkForClose?: () => boolean,\n  element?: HTMLElement,\n  textElement?: HTMLElement,\n  options?: AttachClickOptions,\n  checkboxField?: CheckboxField,\n  noCheckboxClickListener?: boolean,\n  keepOpen?: boolean,\n  separator?: boolean | HTMLElement,\n  separatorDown?: boolean,\n  multiline?: boolean,\n  secondary?: boolean,\n  loadPromise?: Promise<any>,\n  waitForAnimation?: boolean,\n  radioGroup?: string,\n  inner?: (() => MaybePromise<ButtonMenuItemInner>) | ButtonMenuItemInner,\n  dispose?: () => void,\n  onOpen?: () => void,\n  onClose?: () => void\n  /* , cancelEvent?: true */\n};\n\nexport type ButtonMenuItemOptionsVerifiable = ButtonMenuItemOptions & {\n  verify?: () => boolean | Promise<boolean>\n};\n\nexport function ButtonMenuItem(options: ButtonMenuItemOptions) {\n  if(options.element) return [options.separator as HTMLElement, options.element].filter(Boolean);\n\n  const {\n    icon,\n    iconDoc,\n    iconElement,\n    avatarInfo,\n    className,\n    text,\n    onClick,\n    checkboxField,\n    noCheckboxClickListener,\n    emptyIcon\n  } = options;\n  const el = document.createElement('div');\n  const iconSplitted = icon?.split(' ');\n  el.className = 'btn-menu-item rp-overflow' +\n    (iconSplitted?.length > 1 ? ' ' + iconSplitted.slice(1).join(' ') : '') +\n    (className ? ' ' + className : '') +\n    (options.danger ? ' danger' : '');\n\n  if(IS_MOBILE) {\n    ripple(el);\n  }\n\n  if(iconElement) {\n    iconElement.classList.add('btn-menu-item-icon');\n    el.append(iconElement);\n  } else if(iconSplitted) {\n    el.append(Icon(iconSplitted[0] as Icon, 'btn-menu-item-icon'));\n  } else if(emptyIcon) {\n    const iconPlaceholder = document.createElement('span');\n    iconPlaceholder.classList.add('btn-menu-item-icon');\n    el.append(iconPlaceholder);\n  }\n\n  let textElement = options.textElement;\n  if(!textElement) {\n    textElement = options.textElement = text ? i18n(text, options.textArgs) : document.createElement('span');\n    if(options.regularText) {\n      setInnerHTML(textElement, options.regularText);\n      textElement.dir = '';\n    }\n  }\n\n  if(iconDoc) {\n    const iconElement = document.createElement('span');\n    iconElement.classList.add('btn-menu-item-icon');\n    el.append(iconElement);\n\n    const isMobile = () => document.documentElement.classList.contains('is-mobile');\n\n    options.loadPromise = wrapAttachBotIcon({\n      doc: iconDoc,\n      element: iconElement,\n      size: 24,\n      textColor: () => isMobile() ? 'secondary-text-color' : 'primary-text-color',\n      strokeWidth: () => isMobile() ? .625 : .375\n    });\n  }\n\n  if(avatarInfo) {\n    const avatar = createRoot((dispose) => {\n      options.dispose = dispose;\n      return AvatarNew({\n        size: /* avatarInfo.active ? 22 :  */24,\n        ...avatarInfo\n      });\n    });\n    avatar.node.classList.add('btn-menu-item-icon', 'is-external', 'btn-menu-item-avatar');\n    if(avatarInfo.active) {\n      avatar.node.classList.add('active');\n    }\n    el.append(avatar.node);\n  }\n\n  textElement.classList.add('btn-menu-item-text');\n  el.append(textElement);\n\n  if(options.new) {\n    const badge = document.createElement('span');\n    badge.classList.add('btn-menu-item-badge');\n    _i18n(badge, 'New');\n    el.append(badge);\n  }\n\n  const keepOpen = !!checkboxField || !!options.keepOpen;\n\n  // * cancel mobile keyboard close\n  onClick && attachClickEvent(el, /* CLICK_EVENT_NAME !== 'click' || keepOpen ? */ /* async */(e) => {\n    cancelEvent(e);\n\n    const menu = findUpClassName(e.target, 'btn-menu');\n    if(menu && !menu.classList.contains('active')) {\n      return;\n    }\n\n    // let closed = false;\n    // if(!keepOpen && !options.checkForClose) {\n    //   closed = true;\n    //   contextMenuController.close();\n    // }\n\n    // wait for closing animation\n    // if(options.waitForAnimation && rootScope.settings.animationsEnabled && !options.checkForClose) {\n    //   await pause(125);\n    // }\n\n    onClick(e);\n    if(options.checkForClose?.() === false) {\n      return;\n    }\n\n    if(!keepOpen/*  && !closed */) {\n      contextMenuController.close();\n    }\n\n    if(checkboxField && !noCheckboxClickListener/*  && result !== false */) {\n      checkboxField.checked = checkboxField.input.type === 'radio' ? true : !checkboxField.checked;\n    }\n  }/*  : onClick */, options.options);\n\n  if(checkboxField) {\n    el.append(checkboxField.label);\n    el.classList.add('has-checkbox')\n  }\n\n  if(options.separator === true || options.separatorDown) {\n    options.separator = document.createElement('hr');\n  }\n\n  if(options.secondary) {\n    el.classList.add('is-secondary');\n    options.multiline = true;\n  }\n\n  if(options.multiline) {\n    el.classList.add('is-multiline');\n  }\n\n  if(options.inner) {\n    el.append(Icon('next', 'btn-menu-item-icon', 'btn-menu-item-icon-right'));\n    el.classList.add('has-inner');\n    (el as any).inner = options.inner;\n  }\n\n  const ret: HTMLElement[] = [options.element = el];\n\n  if(options.separator) {\n    ret[options.separatorDown ? 'push' : 'unshift'](options.separator as HTMLElement);\n  }\n\n  return ret.filter(Boolean);\n}\n\nexport function ButtonMenuSync({listenerSetter, buttons, radioGroups}: {\n  buttons: ButtonMenuItemOptions[],\n  radioGroups?: {\n    name: string,\n    onChange: (value: string, e: Event) => any,\n    checked: number // idx\n  }[],\n  listenerSetter?: ListenerSetter\n}) {\n  const el: HTMLElement = document.createElement('div');\n  el.classList.add('btn-menu');\n\n  if(radioGroups) {\n    buttons.forEach((b) => {\n      if(!b.radioGroup) {\n        return;\n      }\n\n      b.checkboxField ??= new CheckboxField();\n    });\n  }\n\n  if(listenerSetter) {\n    buttons.forEach((b) => {\n      (b.options ??= {}).listenerSetter = listenerSetter;\n    });\n  }\n\n  const items = buttons.map(ButtonMenuItem);\n  el.append(...flatten(items));\n\n  if(radioGroups) {\n    radioGroups.forEach((group) => {\n      const elements = buttons.filter((button) => button.radioGroup === group.name);\n\n      const hr = document.createElement('hr');\n      elements[0].element.replaceWith(hr);\n\n      const container = RadioForm(elements.map((e, idx) => {\n        const input = e.checkboxField.input;\n        input.type = 'radio';\n        input.name = group.name;\n        input.value = '' + +(idx === group.checked);\n        input.checked = idx === group.checked;\n        return {\n          container: e.element,\n          input: e.checkboxField.input\n        };\n      }), group.onChange);\n\n      hr.before(container);\n      container.append(hr);\n    });\n  }\n\n  return el;\n}\n\nexport default async function ButtonMenu(options: Parameters<typeof ButtonMenuSync>[0]) {\n  const el = ButtonMenuSync(options);\n  await Promise.all(options.buttons.map(({loadPromise}) => loadPromise));\n  return el;\n}\n","type K = boolean;\nexport default async function filterAsync<T>(arr: T[], callback: (item: T, idx: number, arr: T[]) => Promise<K> | K) {\n  const promises = arr.map(async(item, idx, arr) => {\n    if(await callback(item, idx, arr)) {\n      return item;\n    }\n  });\n\n  return (await Promise.all(promises)).filter(Boolean);\n}\n","import type {ButtonMenuDirection} from '@components/buttonMenuToggle';\nimport mediaSizes from '@helpers/mediaSizes';\nimport I18n from '@lib/langPack';\nimport clamp from './number/clamp';\nimport {getAppWindow} from '@helpers/appWindow';\n\nexport type MenuPositionPadding = {\n  top?: number,\n  right?: number,\n  bottom?: number,\n  left?: number\n};\n\nconst PADDING_TOP = 8;\nconst PADDING_BOTTOM = PADDING_TOP;\nconst PADDING_LEFT = 8;\nconst PADDING_RIGHT = PADDING_LEFT;\n\nexport const DEFAULT_MENU_WINDOW_MARGIN = 16;\n\nexport type MenuHorizontalDirection = 'left' | 'right';\n\nexport type FloatingMenuSide = 'top' | 'left' | 'right' | 'bottom';\nexport type FloatingMenuAlignment = 'start' | 'center' | 'end';\nexport type FloatingMenuDirection = `${FloatingMenuSide}-${FloatingMenuAlignment}`;\n\nconst OPPOSITE_SIDE: Record<FloatingMenuSide, FloatingMenuSide> = {\n  top: 'bottom',\n  bottom: 'top',\n  left: 'right',\n  right: 'left'\n};\n\nfunction canFitSide(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  side: FloatingMenuSide,\n  mainOffset: number\n) {\n  const margin = DEFAULT_MENU_WINDOW_MARGIN;\n  switch(side) {\n    case 'right':\n      return triggerBcr.right + mainOffset + menu.clientWidth + margin <= getAppWindow().innerWidth;\n    case 'left':\n      return triggerBcr.left - mainOffset - menu.clientWidth - margin >= 0;\n    case 'bottom':\n      return triggerBcr.bottom + mainOffset + menu.clientHeight + margin <= getAppWindow().innerHeight;\n    case 'top':\n      return triggerBcr.top - mainOffset - menu.clientHeight - margin >= 0;\n  }\n}\n\n/**\n * Positions a floating menu next to a trigger element.\n * - `side` is the side of the trigger the menu opens on.\n * - `alignment` aligns the menu along the perpendicular axis.\n * - `offset` is `[x, y]`. The component along the main axis acts as a gap from the trigger,\n *   the perpendicular component nudges along the alignment axis.\n *\n * Sets `left`, `top`, and `transformOrigin` on `menu`. Returns the actually used direction\n * (the side may flip to the opposite if the menu doesn't fit).\n */\nexport function positionFloatingMenu(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: FloatingMenuDirection,\n  offset: [number, number] = [0, 0]\n): FloatingMenuDirection {\n  const [requestedSide, alignment] = direction.split('-') as [FloatingMenuSide, FloatingMenuAlignment];\n\n  const isHorizontalSide = requestedSide === 'left' || requestedSide === 'right';\n  const mainOffset = isHorizontalSide ? offset[0] : offset[1];\n  const crossOffset = isHorizontalSide ? offset[1] : offset[0];\n\n  // Flip side if it doesn't fit and the opposite does (mirrors the original right/left logic).\n  const opposite = OPPOSITE_SIDE[requestedSide];\n  const side: FloatingMenuSide = canFitSide(triggerBcr, menu, requestedSide, mainOffset) ||\n      !canFitSide(triggerBcr, menu, opposite, mainOffset) ?\n    requestedSide :\n    opposite;\n\n  const margin = DEFAULT_MENU_WINDOW_MARGIN;\n  const menuW = menu.clientWidth;\n  const menuH = menu.clientHeight;\n\n  // Main-axis position.\n  let left: number;\n  let top: number;\n\n  if(side === 'right' || side === 'left') {\n    if(side === 'right') {\n      left = triggerBcr.right + mainOffset;\n    } else {\n      left = triggerBcr.left - mainOffset - menuW;\n    }\n    left = clamp(left, margin, getAppWindow().innerWidth - menuW - margin);\n\n    // Cross axis: vertical.\n    if(alignment === 'start') {\n      top = triggerBcr.top + crossOffset;\n    } else if(alignment === 'center') {\n      top = triggerBcr.top + triggerBcr.height / 2 - menuH / 2 + crossOffset;\n    } else {\n      top = triggerBcr.bottom - menuH - crossOffset;\n    }\n    top = clamp(top, margin, getAppWindow().innerHeight - menuH - margin);\n  } else {\n    if(side === 'bottom') {\n      top = triggerBcr.bottom + mainOffset;\n    } else {\n      top = triggerBcr.top - mainOffset - menuH;\n    }\n    top = clamp(top, margin, getAppWindow().innerHeight - menuH - margin);\n\n    // Cross axis: horizontal.\n    if(alignment === 'start') {\n      left = triggerBcr.left + crossOffset;\n    } else if(alignment === 'center') {\n      left = triggerBcr.left + triggerBcr.width / 2 - menuW / 2 + crossOffset;\n    } else {\n      left = triggerBcr.right - menuW - crossOffset;\n    }\n    left = clamp(left, margin, getAppWindow().innerWidth - menuW - margin);\n  }\n\n  // Transform origin: corner/edge closest to the trigger.\n  let originX: string;\n  let originY: string;\n  const alignmentToPercent = alignment === 'start' ? '0' : alignment === 'center' ? '50%' : '100%';\n\n  if(side === 'right' || side === 'left') {\n    originX = side === 'right' ? '0' : '100%';\n    originY = alignmentToPercent;\n  } else {\n    originY = side === 'bottom' ? '0' : '100%';\n    originX = alignmentToPercent;\n  }\n\n  menu.style.left = left + 'px';\n  menu.style.top = top + 'px';\n  menu.style.transformOrigin = `${originX} ${originY}`;\n\n  return `${side}-${alignment}` as FloatingMenuDirection;\n}\n\nexport function getMenuTopPositionForStartDirection(triggerBcr: DOMRect, menu: HTMLElement, offset: [number, number]) {\n  let top = triggerBcr.top + offset[1];\n  const bottom = top + menu.clientHeight;\n  if(bottom + DEFAULT_MENU_WINDOW_MARGIN > getAppWindow().innerHeight) top -= bottom - getAppWindow().innerHeight + DEFAULT_MENU_WINDOW_MARGIN;\n  top = Math.max(top, DEFAULT_MENU_WINDOW_MARGIN);\n\n  return top;\n}\n\nexport function canMenuFitDirection(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: MenuHorizontalDirection,\n  offset: [number, number]\n) {\n  if(direction === 'right') {\n    const left = triggerBcr.right + offset[0];\n    return left + menu.clientWidth + DEFAULT_MENU_WINDOW_MARGIN <= getAppWindow().innerWidth;\n  }\n\n  const right = triggerBcr.left - offset[0];\n  return right - menu.clientWidth - DEFAULT_MENU_WINDOW_MARGIN >= 0;\n}\n\nexport function getMenuLeftPositionForDirection(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: MenuHorizontalDirection,\n  offset: [number, number]\n) {\n  if(direction === 'right') {\n    let left = triggerBcr.right + offset[0];\n    const right = left + menu.clientWidth;\n    if(right + DEFAULT_MENU_WINDOW_MARGIN > getAppWindow().innerWidth) left -= right - getAppWindow().innerWidth + DEFAULT_MENU_WINDOW_MARGIN;\n    return left;\n  }\n\n  const right = triggerBcr.left - offset[0];\n  let left = right - menu.clientWidth;\n  if(left - DEFAULT_MENU_WINDOW_MARGIN < 0) left = DEFAULT_MENU_WINDOW_MARGIN;\n  return left;\n}\n\nexport default function positionMenu(e: MouseEvent | Touch | TouchEvent, elem: HTMLElement, side?: 'left' | 'right' | 'center', additionalPadding?: MenuPositionPadding) {\n  if((e as TouchEvent).touches) {\n    e = (e as TouchEvent).touches[0];\n  }\n\n  const {pageX, pageY} = e as Touch;\n  // let {clientX, clientY} = e;\n\n  // * side mean the OPEN side\n\n  const getScrollWidthFromElement = (Array.from(elem.children) as HTMLElement[]).find((element) => element.classList.contains('btn-menu-items') || (element.classList.contains('btn-menu-item') && !element.classList.contains('hide'))) || elem;\n\n  let {scrollWidth: menuWidth} = getScrollWidthFromElement;\n  const {scrollHeight: menuHeight} = elem;\n  // let {innerWidth: windowWidth, innerHeight: windowHeight} = window;\n  const rect = getAppWindow().document.body.getBoundingClientRect();\n  const windowWidth = rect.width;\n  const windowHeight = rect.height;\n\n  menuWidth += getScrollWidthFromElement.offsetLeft * 2;\n\n  let paddingTop = PADDING_TOP, paddingRight = PADDING_RIGHT, paddingBottom = PADDING_BOTTOM, paddingLeft = PADDING_LEFT;\n  if(additionalPadding) {\n    if(additionalPadding.top) paddingTop += additionalPadding.top;\n    if(additionalPadding.right) paddingRight += additionalPadding.right;\n    if(additionalPadding.bottom) paddingBottom += additionalPadding.bottom;\n    if(additionalPadding.left) paddingLeft += additionalPadding.left;\n  }\n\n  if(I18n.getIsRTL()) side = mediaSizes.isMobile ? 'left' : 'right';\n  else side = mediaSizes.isMobile ? 'right' : 'left';\n  let verticalSide: 'top' /* | 'bottom' */ | 'center' = 'top';\n\n  const maxTop = windowHeight - menuHeight - paddingBottom;\n  const maxLeft = windowWidth - menuWidth - paddingRight;\n  const minTop = paddingTop;\n  const minLeft = paddingLeft;\n\n  const getSides = () => {\n    return {\n      x: {\n        left: pageX,\n        right: Math.min(maxLeft, pageX - menuWidth)\n      },\n      intermediateX: side === 'right' ? minLeft : maxLeft,\n      // intermediateX: clientX < windowWidth / 2 ? PADDING_LEFT : windowWidth - menuWidth - PADDING_LEFT,\n      y: {\n        top: pageY,\n        bottom: pageY - menuHeight\n      },\n      // intermediateY: verticalSide === 'top' ? paddingTop : windowHeight - menuHeight - paddingTop,\n      // intermediateY: pageY < (windowHeight / 2) ? paddingTop : windowHeight - menuHeight - paddingBottom,\n      intermediateY: maxTop\n    };\n  };\n\n  const sides = getSides();\n\n  const possibleSides = {\n    x: {\n      left: (sides.x.left + menuWidth + paddingRight) <= windowWidth,\n      right: sides.x.right >= paddingLeft\n    },\n    y: {\n      top: (sides.y.top + menuHeight + paddingBottom) <= windowHeight,\n      bottom: (sides.y.bottom - paddingBottom) >= paddingBottom\n    }\n  };\n\n  /* if(side === undefined) {\n    if((clientX + menuWidth + PADDING_LEFT) > windowWidth) {\n      side = 'right';\n    }\n  } */\n\n  {\n    /* const x = sides.x;\n\n    const s = Object.keys(x) as (keyof typeof possibleSides.x)[];\n    if(side) {\n      s.findAndSplice((s) => s === side);\n      s.unshift(side);\n    }\n\n    const possibleSide = s.find((s) => possibleSides.x[s]); */\n    // let left: number;\n    /* if(possibleSide) {\n      left = x[possibleSide];\n      side = possibleSide;\n    } else {\n      left = sides.intermediateX;\n      side = undefined;\n    } */\n    const left = possibleSides.x[side] ? sides.x[side] : (side = 'center', sides.intermediateX);\n\n    elem.style.left = left + 'px';\n  }\n\n  /* if((clientY + menuHeight + PADDING_TOP) > windowHeight) {\n    elem.style.top = clamp(clientY - menuHeight, PADDING_TOP, windowHeight - menuHeight - PADDING_TOP) + 'px';\n    // elem.style.top = (innerHeight - scrollHeight - PADDING_TOP) + 'px';\n    verticalSide = 'bottom';\n  } else {\n    elem.style.top = Math.max(PADDING_TOP, clientY) + 'px';\n    verticalSide = 'top';\n  } */\n\n  {\n    const top = possibleSides.y[verticalSide] ? sides.y[verticalSide] : (verticalSide = 'center', sides.intermediateY);\n\n    elem.style.top = top + 'px';\n  }\n\n  elem.className = elem.className.replace(/(top|center|bottom)-(left|center|right)/g, '');\n  elem.classList.add(\n    // (verticalSide === 'center' ? verticalSide : (verticalSide === 'bottom' ? 'top' : 'bottom')) +\n    (verticalSide === 'center' ? verticalSide : 'bottom') +\n    '-' +\n    (side === 'center' ? side : ((I18n.getIsRTL() ? side === 'right' : side === 'left') ? 'right' : 'left')));\n\n  return {\n    width: menuWidth,\n    height: menuHeight\n  };\n}\n\nexport function positionMenuTrigger(trigger: HTMLElement, menu: HTMLElement, direction: ButtonMenuDirection, additionalPadding?: MenuPositionPadding) {\n  const triggerRect = trigger.getBoundingClientRect();\n\n  const [directionX, directionY] = direction.split('-');\n\n  if(directionX === 'bottom') {\n    const top = triggerRect.top + triggerRect.height + (additionalPadding?.top ?? 0);\n    menu.style.top = `${Math.max(top, additionalPadding?.top ?? 0)}px`\n  } else {\n    const bottom = getAppWindow().innerHeight - triggerRect.top + (additionalPadding?.bottom ?? 0)\n    menu.style.bottom = `${Math.max(bottom, additionalPadding?.bottom ?? 0)}px`\n  }\n\n  if(directionY === 'right' || directionY === 'center') {\n    const left = triggerRect.left + (additionalPadding?.left ?? 0);\n    menu.style.left = `${Math.max(left, additionalPadding?.left ?? 0)}px`\n  } else {\n    const right = getAppWindow().innerWidth - triggerRect.left - triggerRect.width - (additionalPadding?.right ?? 0)\n    menu.style.right = `${Math.max(right, additionalPadding?.right ?? 0)}px`\n  }\n\n  if(directionY === 'center') {\n    menu.style.setProperty('--parent-half-width', (trigger.clientWidth / 2) + 'px');\n  }\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {IS_APPLE} from '@environment/userAgent';\nimport contextMenuController from '@helpers/contextMenuController';\nimport ListenerSetter, {ListenerOptions} from '@helpers/listenerSetter';\nimport cancelEvent from '@helpers/dom/cancelEvent';\n\nlet _cancelContextMenuOpening = false, _cancelContextMenuOpeningTimeout = 0;\nexport function cancelContextMenuOpening() {\n  if(_cancelContextMenuOpeningTimeout) {\n    clearTimeout(_cancelContextMenuOpeningTimeout);\n  }\n\n  _cancelContextMenuOpeningTimeout = window.setTimeout(() => {\n    _cancelContextMenuOpeningTimeout = 0;\n    _cancelContextMenuOpening = false;\n  }, .4e3);\n\n  _cancelContextMenuOpening = true;\n}\n\nexport function attachContextMenuListener({\n  element,\n  callback,\n  listenerSetter,\n  listenerOptions\n}: {\n  element: HTMLElement,\n  callback: (e: TouchEvent | MouseEvent) => void,\n  listenerSetter?: ListenerSetter,\n  listenerOptions?: ListenerOptions\n}) {\n  const add = listenerSetter ? listenerSetter.add(element) : element.addEventListener.bind(element);\n  const remove = listenerSetter ? listenerSetter.removeManual.bind(listenerSetter, element) : element.removeEventListener.bind(element);\n\n  // can't cancel further events coming after 'contextmenu' event\n  if((IS_APPLE && IS_TOUCH_SUPPORTED) || listenerOptions) {\n    let timeout: number;\n\n    const options: EventListenerOptions = {\n      ...(listenerOptions || {}),\n      capture: true\n    };\n\n    const onCancel = () => {\n      clearTimeout(timeout);\n      // @ts-ignore\n      remove('touchmove', onCancel, options);\n      // @ts-ignore\n      remove('touchend', onCancel, options);\n      // @ts-ignore\n      remove('touchcancel', onCancel, options);\n    };\n\n    add('touchstart', (e: TouchEvent) => {\n      if(e.touches.length > 1) {\n        onCancel();\n        return;\n      }\n\n      add('touchmove', onCancel, options);\n      add('touchend', onCancel, options);\n      add('touchcancel', onCancel, options);\n\n      timeout = window.setTimeout(() => {\n        if(_cancelContextMenuOpening) {\n          onCancel();\n          return;\n        }\n\n        callback(e);\n        onCancel();\n\n        if(contextMenuController.isOpened()) {\n          add('touchend', cancelEvent, {once: true}); // * fix instant closing\n        }\n      }, .4e3);\n    }, listenerOptions);\n\n    /* if(!isSafari) {\n      add('contextmenu', (e: any) => {\n        cancelEvent(e);\n      }, {passive: false, capture: true});\n    } */\n  } else {\n    add('contextmenu', IS_TOUCH_SUPPORTED ? (e: any) => {\n      callback(e);\n\n      if(contextMenuController.isOpened()) {\n        add('touchend', cancelEvent, {once: true}); // * fix instant closing\n      }\n    } : callback, listenerOptions);\n  }\n}\n","import ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '@helpers/array/filterAsync';\nimport callbackify from '@helpers/callbackify';\nimport contextMenuController from '@helpers/contextMenuController';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport positionMenu from '@helpers/positionMenu';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {logger} from '@lib/logger';\nimport {getOverlayRoot} from '@helpers/appWindow';\n\nconst log = logger('createContextMenu');\n\nexport default function createContextMenu<T extends ButtonMenuItemOptionsVerifiable>({\n  buttons,\n  findElement,\n  listenTo,\n  appendTo,\n  filterButtons,\n  onOpen,\n  onClose,\n  onCloseAfter,\n  onElementReady,\n  onOpenBefore,\n  listenerSetter: attachListenerSetter,\n  middleware,\n  listenForClick\n}: {\n  buttons: T[],\n  findElement?: (e: MouseEvent | TouchEvent) => HTMLElement,\n  listenTo: HTMLElement,\n  appendTo?: HTMLElement,\n  filterButtons?: (buttons: T[]) => Promise<T[]>,\n  onOpen?: (e: Event, target: HTMLElement) => any,\n  onClose?: () => any,\n  onCloseAfter?: () => any,\n  onOpenBefore?: () => any,\n  onElementReady?: (element: HTMLElement) => void,\n  listenerSetter?: ListenerSetter,\n  middleware?: Middleware,\n  listenForClick?: boolean\n}) {\n  attachListenerSetter ??= new ListenerSetter();\n  const listenerSetter = new ListenerSetter();\n  const middlewareHelper = middleware ? middleware.create() : getMiddleware();\n  let element: HTMLElement;\n\n  const open = (e: MouseEvent | TouchEvent) => {\n    const target = findElement ? findElement(e as any) : listenTo;\n    if(!target) {\n      return;\n    }\n\n    let _element = element;\n    // Duck-type instead of `instanceof MouseEvent`: the event from a Document PiP window is a\n    // pip-realm MouseEvent, which is NOT `instanceof` the main realm's MouseEvent (cross-realm\n    // instanceof is always false) — so the native context menu wasn't being suppressed in the pip.\n    if('preventDefault' in e) (e as any).preventDefault();\n    if(_element && _element.classList.contains('active')) {\n      return false;\n    }\n    if('cancelBubble' in e) (e as any).cancelBubble = true;\n\n    const r = async() => {\n      try {\n        await onOpen?.(e, target);\n      } catch(e) {\n        if(e instanceof Error) {\n          log.error('Error opening context menu:', e);\n        } else {\n          log('Opening context menu was blocked, reason:', e);\n        }\n        onClose?.();\n        return;\n      }\n\n      const initResult = await init();\n      if(!initResult) {\n        onClose?.();\n        return;\n      }\n\n      target.classList.add('menu-open');\n\n      _element = initResult.element;\n      const {cleanup, destroy} = initResult;\n\n      positionMenu(e, _element);\n      contextMenuController.openBtnMenu(_element, () => {\n        target.classList.remove('menu-open');\n        onClose?.();\n        cleanup();\n\n        setTimeout(() => {\n          onCloseAfter?.();\n          destroy();\n        }, 300);\n      }, target);\n    };\n\n    r();\n  };\n\n  attachContextMenuListener({\n    element: listenTo,\n    callback: open,\n    listenerSetter: attachListenerSetter\n  });\n\n  const cleanup = () => {\n    listenerSetter.removeAll();\n    middlewareHelper.clean();\n  };\n\n  const destroy = () => {\n    cleanup();\n    attachListenerSetter.removeAll();\n  };\n\n  const init = async() => {\n    cleanup();\n\n    buttons.forEach((button) => button.element = undefined);\n    const f = filterButtons || ((buttons: T[]) => filterAsync(buttons, (button) => {\n      return button?.verify ? callbackify(button.verify(), (result) => result ?? false) : true;\n    }));\n\n    const filteredButtons = await f(buttons);\n    if(!filteredButtons.length) {\n      return;\n    }\n\n    const _element = element = await ButtonMenu({\n      buttons: filteredButtons,\n      listenerSetter\n    });\n    _element.classList.add('contextmenu');\n\n    await onOpenBefore?.();\n    onElementReady?.(_element);\n\n    // Resolve lazily at open time so a context menu opened while the client is popped out lands in\n    // the Document PiP window's body (the active overlay realm), not the background tab.\n    (appendTo ?? getOverlayRoot()).append(_element);\n\n    return {\n      element: _element,\n      cleanup,\n      destroy: () => {\n        _element.remove();\n      }\n    };\n  };\n\n  if(middleware) {\n    middleware.onDestroy(() => {\n      destroy();\n    });\n  }\n\n  if(listenForClick) {\n    attachClickEvent(listenTo, open, {listenerSetter: attachListenerSetter});\n  }\n\n  return {element, destroy, open};\n}\n","import type {SliderSuperTab} from '@components/slider';\nimport type {SliderSuperTabEventable, SliderSuperTabEventableConstructable} from '@components/sliderTab';\nimport CheckboxField, {CheckboxFieldOptions} from '@components/checkboxField';\nimport RadioField from '@components/radioField';\nimport ripple from '@components/ripple';\nimport RadioForm from '@components/radioForm';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport setInnerHTML, {setDirection} from '@helpers/dom/setInnerHTML';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport Button from '@components/button';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport SidebarSlider from '@components/slider';\nimport Icon from '@components/icon';\n\ntype K = string | HTMLElement | DocumentFragment | true;\n\nconst setContent = (element: HTMLElement, content: K) => {\n  if(content === true) {\n\n  } else if(typeof(content) === 'string') {\n    setInnerHTML(element, content);\n  } else {\n    element.append(content);\n  }\n};\n\nexport type RowMediaSizeType = 'small' | 'medium' | 'big' | 'abitbigger' | 'bigger' | '40';\n\ntype ConstructorP<T> = T extends {\n  new (...args: any[]): infer U;\n} ? U : never;\n\nexport default class Row<T extends SliderSuperTabEventableConstructable = any> {\n  public container: HTMLElement;\n  public titleRow: HTMLElement;\n  public titleRight: HTMLElement;\n  public media: HTMLElement;\n\n  public subtitleRow: HTMLElement;\n  public subtitleRight: HTMLElement;\n\n  public checkboxField: CheckboxField;\n  public radioField: RadioField;\n\n  public freezed = false;\n\n  public buttonRight: HTMLElement;\n\n  private _title: HTMLElement;\n  private _subtitle: HTMLElement;\n  private _midtitle: HTMLElement;\n\n  public openContextMenu: ReturnType<typeof createContextMenu>['open'];\n\n  constructor(options: Partial<{\n    icon: Icon,\n    iconClasses: string[],\n    subtitle: K,\n    subtitleLangKey: LangPackKey,\n    subtitleLangArgs: any[],\n    subtitleRight: K,\n    radioField: Row['radioField'],\n    checkboxField: Row['checkboxField'],\n    checkboxFieldOptions: CheckboxFieldOptions,\n    withCheckboxSubtitle: boolean,\n    title: K,\n    titleLangKey: LangPackKey,\n    titleLangArgs: any[],\n    titleRight: K,\n    titleRightSecondary: K,\n    clickable: boolean | ((e: MouseEvent) => void),\n    navigationTab: {\n      constructor: T,\n      slider: SidebarSlider,\n      getInitArgs?: () => Promise<Parameters<ConstructorP<T>['init']>[0]> | Parameters<ConstructorP<T>['init']>[0]\n      args?: any\n    },\n    havePadding: boolean,\n    noRipple: boolean,\n    noWrap: boolean,\n    listenerSetter: ListenerSetter,\n    buttonRight?: HTMLElement | boolean,\n    buttonRightLangKey: LangPackKey,\n    rightContent?: HTMLElement,\n    rightTextContent?: string,\n    asLink: boolean,\n    contextMenu: Omit<Parameters<typeof createContextMenu>[0], 'findElement' | 'listenTo' | 'listenerSetter'>,\n    asLabel: boolean,\n    checkboxKeys: [LangPackKey, LangPackKey],\n  }> = {}) {\n    if(options.checkboxFieldOptions) {\n      options.checkboxField = new CheckboxField({\n        listenerSetter: options.listenerSetter,\n        ...options.checkboxFieldOptions\n      });\n    }\n\n    const tagName = options.asLink ? 'a' : (options.radioField || options.checkboxField || options.asLabel ? 'label' : 'div');\n    this.container = document.createElement(tagName);\n    this.container.classList.add('row', 'no-subtitle');\n\n    if(options.noWrap) {\n      this.container.classList.add('no-wrap');\n    }\n\n    if(options.subtitle || options.subtitleLangKey) {\n      const subtitle = this.subtitle;\n      if(options.subtitleLangKey) {\n        subtitle.append(i18n(options.subtitleLangKey, options.subtitleLangArgs));\n      } else {\n        setContent(subtitle, options.subtitle);\n      }\n\n      if(options.noWrap) subtitle.classList.add('no-wrap');\n\n      if(options.subtitleRight) {\n        this.container.append(this.subtitleRow = this.createRow());\n        this.subtitleRow.classList.add('row-subtitle-row');\n        const subtitleRight = this.subtitleRight = document.createElement('div');\n        subtitleRight.classList.add('row-subtitle', 'row-subtitle-right');\n\n        setContent(subtitleRight, options.subtitleRight);\n        this.subtitleRow.append(subtitle, subtitleRight);\n      }\n    }\n\n    let havePadding = !!options.havePadding;\n    if(options.radioField || options.checkboxField) {\n      if(options.radioField) {\n        this.radioField = options.radioField;\n        this.container.append(this.radioField.label);\n        havePadding = true;\n      }\n\n      if(options.checkboxField) {\n        this.checkboxField = options.checkboxField;\n\n        const isToggle = options.checkboxField.label.classList.contains('checkbox-field-toggle');\n        if(isToggle) {\n          this.container.classList.add('row-with-toggle');\n          options.titleRight = this.checkboxField.label;\n        } else {\n          havePadding = true;\n          if(!this.checkboxField.span) {\n            this.checkboxField.label.classList.add('checkbox-field-absolute');\n          }\n          this.container.append(this.checkboxField.label);\n        }\n\n        if(options.withCheckboxSubtitle && !isToggle) {\n          options.checkboxKeys ??= ['Checkbox.Enabled', 'Checkbox.Disabled'];\n          const [enabledKey, disabledKey] = options.checkboxKeys;\n          const onChange = () => {\n            replaceContent(this.subtitle, i18n(this.checkboxField.checked ? enabledKey : disabledKey));\n          };\n\n          if(options.listenerSetter) options.listenerSetter.add(this.checkboxField.input)('change', onChange);\n          else this.checkboxField.input.addEventListener('change', onChange);\n        }\n      }\n\n      const i = options.radioField || options.checkboxField;\n      i.label.classList.add('disable-hover');\n    }\n\n    if(options.title || options.titleLangKey || options.titleRight || options.titleRightSecondary) {\n      let c: HTMLElement;\n      const titleRightContent = options.titleRight || options.titleRightSecondary;\n      if(titleRightContent) {\n        this.container.append(c = this.titleRow = this.createRow());\n        this.titleRow.classList.add('row-title-row');\n      } else {\n        c = this.container;\n      }\n\n      this._title = this.createTitle();\n      if(options.noWrap) this.title.classList.add('no-wrap');\n      if(options.title) {\n        setContent(this.title, options.title);\n      } else if(options.titleLangKey) {\n        this.title.append(i18n(options.titleLangKey, options.titleLangArgs));\n      }\n\n      c.append(this.title);\n\n      if(titleRightContent) {\n        const titleRight = this.titleRight = document.createElement('div');\n        titleRight.classList.add('row-title', 'row-title-right');\n\n        if(options.titleRightSecondary) {\n          titleRight.classList.add('row-title-right-secondary');\n        }\n\n        setContent(titleRight, titleRightContent);\n        c.append(titleRight);\n      }\n    }\n\n    if(options.icon) {\n      havePadding = true;\n      // this.title.classList.add('tgico', 'tgico-' + options.icon);\n      if(options.iconClasses?.length) {\n        this.container.append(Icon(options.icon, 'row-icon', ...options.iconClasses));\n      } else {\n        this.container.append(Icon(options.icon, 'row-icon'));\n      }\n      this.container.classList.add('row-with-icon');\n    }\n\n    if(havePadding) {\n      this.container.classList.add('row-with-padding');\n    }\n\n    if(options.navigationTab) {\n      let getInitArgs = options.navigationTab.getInitArgs;\n      if(!getInitArgs) {\n        const g = (options.navigationTab.constructor as any as typeof SliderSuperTab).getInitArgs;\n        if(g) {\n          // @ts-ignore\n          getInitArgs = () => g();\n        }\n      }\n\n      let args = options.navigationTab.args ?? getInitArgs?.();\n\n      options.clickable = async() => {\n        if(args instanceof Promise) {\n          args = await args;\n        }\n\n        // if(!Array.isArray(args)) {\n        //   args = [args];\n        // }\n\n        const tab = options.navigationTab.slider.createTab(options.navigationTab.constructor as any);\n        tab.open(args);\n\n        const eventListener = (tab as SliderSuperTabEventable).eventListener;\n        if(eventListener && getInitArgs) {\n          eventListener.addEventListener('destroyAfter', (promise) => {\n            args = promise.then(() => getInitArgs() as any);\n          });\n        }\n      };\n    }\n\n    if(options.clickable || options.radioField || options.checkboxField) {\n      if(typeof(options.clickable) === 'function') {\n        attachClickEvent(this.container, (e) => {\n          if(this.freezed) return;\n          (options.clickable as any)(e);\n        }, {listenerSetter: options.listenerSetter});\n      }\n\n      this.container.classList.add('row-clickable', 'hover-effect');\n\n      if(!options.noRipple) {\n        ripple(this.container);\n      }\n\n      /* if(options.radioField || options.checkboxField) {\n        this.container.prepend(this.container.lastElementChild);\n      } */\n    }\n\n    if(options.buttonRight || options.buttonRightLangKey) {\n      options.rightContent = this.buttonRight = options.buttonRight instanceof HTMLElement ?\n        options.buttonRight :\n        Button('btn-primary btn-color-primary btn-control-small', {text: options.buttonRightLangKey});\n    }\n\n    if(options.rightTextContent) {\n      options.rightContent = document.createElement('span');\n      options.rightContent.classList.add('row-title-right-secondary');\n      options.rightContent.textContent = options.rightTextContent;\n    }\n\n    if(options.rightContent) {\n      options.rightContent.classList.add('row-right');\n      this.container.classList.add('row-grid');\n      this.container.append(options.rightContent);\n    }\n\n    if(options.contextMenu) {\n      const {open} = createContextMenu({\n        ...options.contextMenu,\n        listenTo: this.container,\n        listenerSetter: options.listenerSetter\n      });\n\n      this.openContextMenu = open;\n    }\n  }\n\n  public get title() {\n    return this._title;\n  }\n\n  public get subtitle() {\n    return this._subtitle ??= this.createSubtitle();\n  }\n\n  public get midtitle() {\n    return this._midtitle ??= this.createMidtitle();\n  }\n\n  private createRow() {\n    const c = document.createElement('div');\n    c.classList.add('row-row');\n    return c;\n  }\n\n  public createTitle() {\n    const title = document.createElement('div');\n    title.classList.add('row-title');\n    setDirection(title);\n    return title;\n  }\n\n  private createSubtitle() {\n    const subtitle = document.createElement('div');\n    subtitle.classList.add('row-subtitle');\n    setDirection(subtitle);\n    if(this.title) this.title.after(subtitle);\n    else this.container.prepend(subtitle);\n    this.container.classList.remove('no-subtitle');\n    return subtitle;\n  }\n\n  private createMidtitle() {\n    const midtitle = document.createElement('div');\n    midtitle.classList.add('row-midtitle');\n    this.subtitle.parentElement.insertBefore(midtitle, this.subtitle);\n    return midtitle;\n  }\n\n  public createMedia(size?: RowMediaSizeType) {\n    const media = document.createElement('div');\n    return this.applyMediaElement(media, size);\n  }\n\n  public applyMediaElement(media: HTMLElement, size?: RowMediaSizeType) {\n    this.container.classList.add('row-with-padding');\n\n    this.media = media;\n    media.classList.add('row-media');\n\n    if(size) {\n      media.classList.add('row-media-' + size);\n    }\n\n    this.container.append(media);\n\n    return media;\n  }\n\n  public isDisabled() {\n    return this.container.classList.contains('is-disabled');\n  }\n\n  public toggleDisability(disable = !this.container.classList.contains('is-disabled')) {\n    this.container.classList.toggle('is-disabled', disable);\n    return () => this.toggleDisability(!disable);\n  }\n\n  public disableWithPromise(promise: Promise<any>) {\n    const toggle = this.toggleDisability(true);\n    promise.finally(() => {\n      toggle();\n    });\n  }\n\n  public makeSortable() {\n    const sortIcon = Icon('menu', 'row-sortable-icon');\n    this.container.classList.add('row-sortable');\n    this.container.append(sortIcon);\n  }\n\n  public toggleSorting(enabled?: boolean) {\n    this.container.classList.toggle('cant-sort', !enabled);\n  }\n}\n\nexport const CreateRowFromCheckboxField = (checkboxField: CheckboxField) => {\n  return new Row({checkboxField, listenerSetter: checkboxField.listenerSetter});\n};\n\nexport const RadioFormFromRows = (rows: Row[], onChange: (value: string) => void) => {\n  return RadioForm(rows.map((r) => ({container: r.container, input: r.radioField.input})), onChange);\n};\n\nexport const RadioFormFromValues = (values: {\n  langPackKey?: LangPackKey,\n  value: number | string,\n  checked?: boolean,\n  textElement?: ConstructorParameters<typeof RadioField>[0]['textElement']\n}[], onChange: Parameters<typeof RadioFormFromRows>[1], fireInit?: boolean) => {\n  const name = 'name-' + (Math.random() * 0x7FFFFF | 0);\n  let checkedRadioField: RadioField;\n  const rows = values.map(({langPackKey, value, checked, textElement}) => {\n    const row = new Row({\n      radioField: new RadioField({\n        textElement,\n        langKey: langPackKey,\n        name,\n        value: '' + value\n      })\n    });\n\n    if(checked) {\n      checkedRadioField = row.radioField;\n    }\n\n    return row;\n  });\n\n  const form = RadioFormFromRows(rows, onChange);\n  if(checkedRadioField) {\n    if(fireInit) checkedRadioField.checked = true;\n    else checkedRadioField.setValueSilently(true);\n  }\n  return form;\n};\n","import {i18n, LangPackKey} from '@lib/langPack';\n\nexport default function formatBytes(bytes: number, decimals: number | 'auto' = 'auto') {\n  if(bytes === 0) return i18n('FileSize.B', [0]);\n\n  const strictDecimals = decimals === 'auto';\n\n  const k = 1024;\n  const sizes: LangPackKey[] = ['FileSize.B', 'FileSize.KB', 'FileSize.MB', 'FileSize.GB', 'FileSize.TB', 'FileSize.PB'];\n  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1);\n  const _decimals = decimals === 'auto' ? Math.max(0, i - 1) : decimals;\n\n  const dm = Math.max(0, _decimals);\n\n  const fixed = (bytes / Math.pow(k, i)).toFixed(dm);\n  return i18n(sizes[i], [strictDecimals ? fixed : parseFloat(fixed)]);\n}\n","import {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport {Document} from '@layer';\nimport {ApiLimitType} from '@appManagers/apiManagerMethods';\nimport {AppManagers} from '@lib/managers';\nimport formatBytes from '@helpers/formatBytes';\n\nexport interface PremiumPromoFeature {\n  feature: PremiumPromoFeatureType;\n  icon: Icon;\n  titleLangKey: LangPackKey;\n  subtitleLangKey: LangPackKey;\n  actionTitleLangKey?: LangPackKey;\n  actionIcon?: Icon;\n  headerLangKey?: LangPackKey;\n  titleLangArgs?: FormatterArguments;\n  subtitleLangArgs?: FormatterArguments;\n  _titleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n  _subtitleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n  videoPosition?: 'bottom' | 'top';\n  video?: Document.document;\n  wrappedVideo?: any;\n  type?: string;\n  content?: Array<{\n    titleLangKey?: LangPackKey,\n    titleLangArgs?: FormatterArguments,\n    _titleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n    subtitleLangKey?: LangPackKey,\n    subtitleLangArgs?: FormatterArguments,\n    _subtitleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>,\n    iconColor?: string,\n    icon?: Icon,\n    backgroundColor?: string,\n    limitType?: ApiLimitType,\n    name?: string,\n    free?: number,\n    premium?: number\n  }>;\n  new?: boolean,\n  builded?: boolean\n}\n\nexport const PREMIUM_FEATURES_COLORS: string[] = [\n  '#ef6922',\n  '#e95a2c',\n  '#e74e33',\n  '#e3433c',\n  '#db374b',\n  '#cb3e6d',\n  '#bc4395',\n  '#ab4ac4',\n  '#9b4fed',\n  '#8958ff',\n  '#676bff',\n  '#5b79ff',\n  '#4492ff',\n  '#429bd5',\n  '#41a6a5',\n  '#3eb26d',\n  '#3dbd4a'\n];\n\nconst stories: PremiumPromoFeature = {\n  feature: 'stories',\n  icon: 'stories',\n  titleLangKey: 'Premium.Boarding.Stories.Title',\n  subtitleLangKey: 'Premium.Boarding.Stories.Info',\n  type: 'upgraded-stories',\n  content: [{\n    titleLangKey: 'PremiumStoriesPriority',\n    subtitleLangKey: 'PremiumStoriesPriorityDescription',\n    iconColor: '#0079FE',\n    icon: 'multistories'\n  }, {\n    titleLangKey: 'PremiumStoriesStealth',\n    subtitleLangKey: 'PremiumStoriesStealthDescription',\n    iconColor: '#7889FE',\n    icon: 'eyecross_outline'\n  }, {\n    titleLangKey: 'PremiumStoriesViews',\n    subtitleLangKey: 'PremiumStoriesViewsDescription',\n    iconColor: '#A45FE6',\n    icon: 'eye'\n  }, {\n    titleLangKey: 'PremiumStoriesExpiration',\n    subtitleLangKey: 'PremiumStoriesExpirationDescription',\n    iconColor: '#C355AE',\n    icon: 'timer'\n  }, {\n    titleLangKey: 'PremiumStoriesSaveToGallery',\n    subtitleLangKey: 'PremiumStoriesSaveToGalleryDescription',\n    iconColor: '#E85D43',\n    icon: 'arrowcircle'\n  }, {\n    titleLangKey: 'PremiumStoriesCaption',\n    subtitleLangKey: 'PremiumStoriesCaptionDescription',\n    iconColor: '#F1822A',\n    icon: 'list'\n  }, {\n    titleLangKey: 'PremiumStoriesFormatting',\n    subtitleLangKey: 'PremiumStoriesFormattingDescription',\n    iconColor: '#E6AC19',\n    icon: 'limit_link'\n  }]\n};\n\nconst wrapGetLimitArgument = (limitType: ApiLimitType) => (managers: AppManagers) => managers.apiManager.getLimit(limitType, true).then((limit) => [limit]);\n\nconst doubleLimits: PremiumPromoFeature = {\n  feature: 'double_limits',\n  icon: 'premium_limits',\n  titleLangKey: 'Premium.Boarding.Double.Title',\n  subtitleLangKey: 'Premium.Boarding.Double.Info',\n  headerLangKey: 'Premium.Boarding.Double.Title',\n  _subtitleLangArgs: (managers) => Promise.all(\n    (['channels', 'folders', 'pin', 'links'] as ApiLimitType[]).map((type) => {\n      return managers.apiManager.getLimit(type, true);\n    })\n  ),\n  type: 'limits',\n  content: [{\n    titleLangKey: 'GroupsAndChannelsLimitTitle',\n    subtitleLangKey: 'GroupsAndChannelsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('channels'),\n    limitType: 'channels',\n    backgroundColor: '#5B9FFF'\n  }, {\n    titleLangKey: 'PinChatsLimitTitle',\n    subtitleLangKey: 'PinChatsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('pin'),\n    limitType: 'pin',\n    backgroundColor: '#7889FE'\n  }, {\n    titleLangKey: 'PublicLinksLimitTitle',\n    subtitleLangKey: 'PublicLinksLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('links'),\n    limitType: 'links',\n    backgroundColor: '#9376FF'\n  }, {\n    titleLangKey: 'SavedGifsLimitTitle',\n    subtitleLangKey: 'SavedGifsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('gifs'),\n    limitType: 'gifs',\n    backgroundColor: '#AB63F2'\n  }, {\n    titleLangKey: 'FavoriteStickersLimitTitle',\n    subtitleLangKey: 'FavoriteStickersLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('favedStickers'),\n    limitType: 'favedStickers',\n    backgroundColor: '#C456AE'\n  }, {\n    titleLangKey: 'BioLimitTitle',\n    subtitleLangKey: 'BioLimitSubtitle',\n    limitType: 'bio',\n    backgroundColor: '#CE569A'\n  }, {\n    titleLangKey: 'CaptionsLimitTitle',\n    subtitleLangKey: 'CaptionsLimitSubtitle',\n    limitType: 'caption',\n    backgroundColor: '#DA5786'\n  }, {\n    titleLangKey: 'FoldersLimitTitle',\n    subtitleLangKey: 'FoldersLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('folders'),\n    limitType: 'folders',\n    backgroundColor: '#DB496F'\n  }, {\n    titleLangKey: 'ChatPerFolderLimitTitle',\n    subtitleLangKey: 'ChatPerFolderLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('folderPeers'),\n    limitType: 'folderPeers',\n    backgroundColor: '#E85D43'\n  }, {\n    titleLangKey: 'ConnectedAccountsLimitTitle',\n    subtitleLangKey: 'ConnectedAccountsLimitSubtitle',\n    subtitleLangArgs: [4],\n    free: 3,\n    premium: 4,\n    backgroundColor: '#F1822A'\n  }]\n};\n\nconst formatParts = (parts: number) => formatBytes(parts * 1.024 * 512 * 1024, 0);\n\nexport const PREMIUM_FEATURES: {[type in PremiumPromoFeatureType]?: PremiumPromoFeature} = {\n  stories: stories,\n  double_limits: doubleLimits,\n  voice_to_text: {\n    feature: 'voice_to_text',\n    icon: 'premium_transcription',\n    titleLangKey: 'Premium.Boarding.Voice.Title',\n    subtitleLangKey: 'Premium.Boarding.Voice.Info',\n    videoPosition: 'top'\n  },\n  faster_download: {\n    feature: 'faster_download',\n    icon: 'premium_speed',\n    titleLangKey: 'Premium.Boarding.Download.Title',\n    subtitleLangKey: 'Premium.Boarding.Download.Info',\n    videoPosition: 'top'\n  },\n  translations: {\n    feature: 'translations',\n    icon: 'premium_translate',\n    titleLangKey: 'Premium.Boarding.Translate.Title',\n    subtitleLangKey: 'Premium.Boarding.Translate.Info',\n    videoPosition: 'top'\n  },\n  animated_emoji: {\n    feature: 'animated_emoji',\n    icon: 'premium_emoji',\n    titleLangKey: 'Premium.Boarding.Emoji.Title',\n    subtitleLangKey: 'Premium.Boarding.Emoji.Info'\n  },\n  more_upload: {\n    feature: 'more_upload',\n    icon: 'premium_filesize',\n    titleLangKey: 'Premium.Boarding.FileSize.Title',\n    _titleLangArgs: (managers) => managers.apiManager.getLimit('uploadFileParts', true).then((parts) => [formatParts(parts)]),\n    subtitleLangKey: 'Premium.Boarding.FileSize.Info',\n    _subtitleLangArgs: (managers) => Promise.all(\n      [false, true].map(async(isPremium) => {\n        const parts = await managers.apiManager.getLimit('uploadFileParts', isPremium);\n        return formatParts(parts);\n      })\n    )\n  },\n  emoji_status: {\n    feature: 'emoji_status',\n    icon: 'premium_status',\n    titleLangKey: 'Premium.Boarding.Status.Title',\n    subtitleLangKey: 'Premium.Boarding.Status.Info',\n    videoPosition: 'top'\n  },\n  peer_colors: {\n    feature: 'peer_colors',\n    icon: 'premium_colors',\n    titleLangKey: 'Premium.Promo.Colors.Title',\n    subtitleLangKey: 'Premium.Promo.Colors.Subtitle',\n    videoPosition: 'top'\n  },\n  wallpapers: {\n    feature: 'wallpapers',\n    icon: 'premium_wallpaper',\n    titleLangKey: 'Premium.Promo.Wallpaper.Title',\n    subtitleLangKey: 'Premium.Promo.Wallpaper.Subtitle',\n    videoPosition: 'top',\n    new: true\n  },\n  profile_badge: {\n    feature: 'profile_badge',\n    icon: 'star',\n    titleLangKey: 'Premium.Boarding.Badge.Title',\n    subtitleLangKey: 'Premium.Boarding.Badge.Info',\n    videoPosition: 'top'\n  },\n  advanced_chat_management: {\n    feature: 'advanced_chat_management',\n    icon: 'premium_management',\n    titleLangKey: 'Premium.Boarding.Chats.Title',\n    subtitleLangKey: 'Premium.Boarding.Chats.Info',\n    videoPosition: 'top'\n  },\n  no_ads: {\n    feature: 'no_ads',\n    icon: 'premium_noads',\n    titleLangKey: 'Premium.Boarding.NoAds.Title',\n    subtitleLangKey: 'Premium.Boarding.NoAds.Info'\n    // actionTitleLangKey: 'Premium.Boarding.NoAds.Action',\n    // actionIcon: 'premium_badge'\n  },\n  infinite_reactions: {\n    feature: 'infinite_reactions',\n    icon: 'premium_reactions',\n    titleLangKey: 'Premium.Boarding.ReactionsNew.Title',\n    subtitleLangKey: 'Premium.Boarding.ReactionsNew.Info',\n    videoPosition: 'top'\n    // actionIcon: 'premium_unlock'\n  },\n  animated_userpics: {\n    feature: 'animated_userpics',\n    icon: 'premium_avatars',\n    titleLangKey: 'Premium.Boarding.Avatar.Title',\n    subtitleLangKey: 'Premium.Boarding.Avatar.Info',\n    videoPosition: 'top'\n  },\n  premium_stickers: {\n    feature: 'premium_stickers',\n    icon: 'premium_stickers',\n    titleLangKey: 'Premium.Boarding.Stickers.Title',\n    subtitleLangKey: 'Premium.Boarding.Stickers.Info',\n    // actionIcon: 'premium_unlock',\n    type: 'premium-stickers'\n  },\n  last_seen: {\n    feature: 'last_seen',\n    icon: 'premium_lastseen',\n    titleLangKey: 'PremiumPreviewLastSeen',\n    subtitleLangKey: 'PremiumPreviewLastSeenDescription',\n    new: true\n  },\n  message_privacy: {\n    feature: 'message_privacy',\n    icon: 'premium_privacy',\n    titleLangKey: 'PremiumPreviewMessagePrivacy',\n    subtitleLangKey: 'PremiumPreviewMessagePrivacyDescription',\n    new: true\n  },\n  saved_tags: {\n    feature: 'saved_tags',\n    icon: 'premium_tags',\n    titleLangKey: 'PremiumPreviewTags',\n    subtitleLangKey: 'PremiumPreviewTagsDescription2'\n  },\n  pm_noforwards: {\n    feature: 'pm_noforwards',\n    icon: 'sharingoff_filled',\n    titleLangKey: 'Premium.Boarding.NoForwards.Title',\n    subtitleLangKey: 'Premium.Boarding.NoForwards.Info',\n    videoPosition: 'top'\n  }\n};\n","import type {Message, MessageAction} from '@layer';\nimport type {HistoryResult, MyMessage} from '@appManagers/appMessagesManager';\nimport forEachReverse from '@helpers/array/forEachReverse';\n\nexport default function filterChatPhotosMessages(value: HistoryResult) {\n  forEachReverse(value.messages, (message, idx, arr) => {\n    if(!((message as Message.messageService).action as MessageAction.messageActionChatEditPhoto).photo) {\n      arr.splice(idx, 1);\n      if(value.count !== undefined) {\n        --value.count;\n      }\n    }\n  });\n}\n","import forEachReverse from '@helpers/array/forEachReverse';\nimport safeAssign from '@helpers/object/safeAssign';\n\nexport type ListLoaderOptions<T extends {}, P extends {}> = {\n  loadMore: ListLoader<T, P>['loadMore'],\n  loadCount?: ListLoader<T, P>['loadCount'],\n  loadWhenLeft?: ListLoader<T, P>['loadWhenLeft'],\n  processItem?: ListLoader<T, P>['processItem'],\n  onJump?: ListLoader<T, P>['onJump'],\n  onLoadedMore?: ListLoader<T, P>['onLoadedMore']\n};\n\nexport type ListLoaderResult<T extends {}> = {count: number, items: any[]};\nexport default class ListLoader<T extends {}, P extends {}> {\n  public current: T;\n  public previous: T[] = [];\n  public next: T[] = [];\n  public count: number;\n  public reverse = false; // reverse means next = higher msgid\n\n  protected loadMore: (anchor: T, older: boolean, loadCount: number) => Promise<ListLoaderResult<T>>;\n  protected processItem: (item: P) => T | Promise<T>;\n  protected loadCount = 50;\n  protected loadWhenLeft = 20;\n\n  public onJump: (item: T, older: boolean) => void;\n  public onLoadedMore: () => void;\n\n  protected loadedAllUp = false;\n  protected loadedAllDown = false;\n  protected loadPromiseUp: Promise<void>;\n  protected loadPromiseDown: Promise<void>;\n\n  constructor(options: ListLoaderOptions<T, P>) {\n    safeAssign(this, options);\n  }\n\n  public setTargets(previous: T[], next: T[], reverse: boolean) {\n    this.previous = previous;\n    this.next = next;\n    this.reverse = reverse;\n  }\n\n  public get index() {\n    return this.count !== undefined ? this.previous.length : -1;\n  }\n\n  /* public filter(callback: (item: T, idx: number, arr: T[]) => boolean) {\n    const filter = (item: T, idx: number, arr: T[]) => {\n      if(!callback(item, idx, arr)) {\n        arr.splice(idx, 1);\n      }\n    };\n\n    forEachReverse(this.previous, filter);\n    forEachReverse(this.next, filter);\n  } */\n\n  public reset(loadedAll = false) {\n    this.current = undefined;\n    this.previous = [];\n    this.next = [];\n    this.setLoaded(true, loadedAll);\n    this.setLoaded(false, loadedAll);\n  }\n\n  public go(length: number, dispatchJump = true) {\n    let items: T[], item: T;\n    if(length > 0) {\n      items = this.next.splice(0, length);\n      item = items.pop();\n      if(!item) {\n        return;\n      }\n\n      if(this.current !== undefined) items.unshift(this.current);\n      this.previous.push(...items);\n    } else {\n      items = this.previous.splice(Math.max(0, this.previous.length + length), -length);\n      item = items.shift();\n      if(!item) {\n        return;\n      }\n\n      if(this.current !== undefined) items.push(this.current);\n      this.next.unshift(...items);\n    }\n\n    this.current = item;\n\n    if(this.next.length < this.loadWhenLeft) {\n      this.load(!this.reverse);\n    }\n\n    if(this.previous.length < this.loadWhenLeft) {\n      this.load(this.reverse);\n    }\n\n    dispatchJump && this.onJump?.(item, length > 0);\n    return this.current;\n  }\n\n  protected unsetCurrent(toPrevious: boolean) {\n    if(toPrevious) this.previous.push(this.current);\n    else this.next.unshift(this.current);\n\n    this.current = undefined;\n  }\n\n  public goUnsafe(length: number, dispatchJump?: boolean) {\n    const leftLength = length > 0 ? Math.max(0, length - this.next.length) : Math.min(0, length + this.previous.length);\n    const item = this.go(length, leftLength ? false : dispatchJump);\n\n    /* if(length > 0 ? this.loadedAllUp : this.loadedAllDown) {\n      this.unsetCurrent(length > 0);\n    } */\n\n    return {\n      item: !leftLength ? item : undefined,\n      leftLength\n    };\n  }\n\n  protected setLoaded(down: boolean, value: boolean) {\n    const isChanged = (down ? this.loadedAllDown : this.loadedAllUp) !== value;\n    if(!isChanged) {\n      return false;\n    }\n\n    if(down) this.loadedAllDown = value;\n    else this.loadedAllUp = value;\n\n    if(!value) {\n      if(down) this.loadPromiseDown = null;\n      else this.loadPromiseUp = null;\n    }\n\n    return true;\n  }\n\n  // нет смысла делать проверку для reverse и loadMediaPromise\n  public load(older: boolean) {\n    if(older ? this.loadedAllDown : this.loadedAllUp) return Promise.resolve();\n\n    let promise = older ? this.loadPromiseDown : this.loadPromiseUp;\n    if(promise) return promise;\n\n    let anchor: T;\n    if(older) {\n      anchor = this.reverse ? this.previous[0] : this.next[this.next.length - 1];\n    } else {\n      anchor = this.reverse ? this.next[this.next.length - 1] : this.previous[0];\n    }\n\n    anchor ??= this.current;\n    promise = this.loadMore(anchor, older, this.loadCount).then(async(result) => {\n      if((older ? this.loadPromiseDown : this.loadPromiseUp) !== promise) {\n        return;\n      }\n\n      if(result.items.length < this.loadCount) {\n        this.setLoaded(older, true);\n      }\n\n      if(this.count === undefined) {\n        this.count = result.count || result.items.length;\n      }\n\n      const processedArr: (Promise<any> | any)[] = [];\n      const method = older && !this.reverse ? result.items.forEach.bind(result.items) : forEachReverse.bind(null, result.items);\n      method((item: any) => {\n        const processed = this.processItem ? this.processItem(item) : item;\n\n        if(!processed) return;\n        processedArr.push(processed);\n      });\n\n      const results = (await Promise.all(processedArr)).filter(Boolean);\n      if((older ? this.loadPromiseDown : this.loadPromiseUp) !== promise) {\n        return;\n      }\n\n      if(older) {\n        if(this.reverse) this.previous.unshift(...results);\n        else this.next.push(...results);\n      } else {\n        if(this.reverse) this.next.push(...results);\n        else this.previous.unshift(...results);\n      }\n\n      this.onLoadedMore?.();\n    }, () => {}).then(() => {\n      if(older) this.loadPromiseDown = null;\n      else this.loadPromiseUp = null;\n    });\n\n    if(older) this.loadPromiseDown = promise;\n    else this.loadPromiseUp = promise;\n\n    return promise;\n  }\n}\n","import type {MediaSearchContext} from '@components/appMediaPlaybackController';\nimport type {SearchSuperContext} from '@components/appSearchSuper';\nimport type {Message} from '@layer';\nimport type {MessagesStorageKey, MyMessage} from '@appManagers/appMessagesManager';\nimport {AppManagers} from '@lib/managers';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport filterChatPhotosMessages from '@helpers/filterChatPhotosMessages';\nimport ListLoader, {ListLoaderOptions} from '@helpers/listLoader';\n\nexport default class SearchListLoader<Item extends {mid: number, peerId: PeerId}> extends ListLoader<Item, Message.message> {\n  public searchContext: MediaSearchContext;\n  public onEmptied: () => void;\n\n  private otherSideLoader: SearchListLoader<Item>;\n  private managers: AppManagers;\n\n  constructor(options: Omit<ListLoaderOptions<Item, Message.message>, 'loadMore'> & {\n    onEmptied?: () => void,\n    isInner?: boolean,\n    managers?: AppManagers\n  } = {}) {\n    super({\n      ...options,\n      loadMore: async(anchor, older, loadCount) => {\n        const backLimit = older ? 0 : loadCount;\n        let offsetId = anchor?.mid ?? this.searchContext.maxId;\n\n        if(!older) offsetId = await this.managers.appMessagesIdsManager.incrementMessageId(offsetId, 1);\n\n        const peerId = this.searchContext.peerId || anchor?.peerId;\n\n        return this.managers.appMessagesManager.getHistory({\n          ...this.searchContext,\n          peerId,\n          offsetId,\n          offsetPeerId: !peerId ? anchor?.peerId : undefined,\n          limit: backLimit ? 0 : loadCount,\n          backLimit\n        }).then((value) => {\n          /* if(DEBUG) {\n            this.log('loaded more media by maxId:', maxId, value, older, this.reverse);\n          } */\n\n          if(this.searchContext.inputFilter._ === 'inputMessagesFilterChatPhotos') {\n            filterChatPhotosMessages(value);\n          }\n\n          if(value.nextRate) {\n            this.searchContext.nextRate = value.nextRate;\n          }\n\n          if(!value.messages) {\n            value.messages = value.history.map((mid) => apiManagerProxy.getMessageByPeer(peerId, mid));\n          }\n\n          return {count: value.count, items: value.messages};\n        });\n      },\n      processItem: async(message) => {\n        const filtered = await this.filterMids([message.mid]);\n        if(!filtered.length) {\n          return;\n        }\n\n        return options.processItem(message);\n      }\n    });\n\n    this.managers ??= rootScope.managers;\n    rootScope.addEventListener('history_delete', this.onHistoryDelete);\n    rootScope.addEventListener('history_multiappend', this.onHistoryMultiappend);\n    rootScope.addEventListener('message_sent', this.onMessageSent);\n\n    if(!options.isInner) {\n      this.otherSideLoader = new SearchListLoader({\n        ...options,\n        isInner: true\n      });\n\n      // this.otherSideLoader.onLoadedMore = () => {\n\n      // };\n    }\n  }\n\n  protected async filterMids(mids: number[]) {\n    const storageKey: MessagesStorageKey = `${this.searchContext.peerId}_${this.searchContext.isScheduled ? 'scheduled' : 'history'}`;\n    let filtered = (await this.managers.appMessagesManager.filterMessagesByInputFilterFromStorage(this.searchContext.inputFilter._, mids, storageKey, mids.length)) as Message.message[];\n    if(this.searchContext.skipSensitive) {\n      filtered = filtered.filter((message) => !isMessageSensitive(message));\n    }\n    return filtered;\n  }\n\n  protected onHistoryDelete = ({peerId, msgs}: BroadcastEvents['history_delete']) => {\n    const shouldBeDeleted = (item: Item) => item.peerId === peerId && msgs.has(item.mid);\n    const filter = (item: Item, idx: number, arr: Item[]) => {\n      if(shouldBeDeleted(item)) {\n        arr.splice(idx, 1);\n      }\n    };\n\n    forEachReverse(this.previous, filter);\n    forEachReverse(this.next, filter);\n\n    if(this.current && shouldBeDeleted(this.current)) {\n      this.current = undefined;\n      /* if(this.go(1)) {\n        this.previous.splice(this.previous.length - 1, 1);\n      } else if(this.go(-1)) {\n        this.next.splice(0, 1);\n      } else  */if(this.onEmptied) {\n        this.onEmptied();\n      }\n    }\n  };\n\n  protected onHistoryMultiappend = async(message: Message.message | Message.messageService) => {\n    const {searchContext} = this;\n    if(searchContext.folderId !== undefined) {\n      return;\n    }\n\n    // because it's reversed\n    if(!this.loadedAllUp || this.loadPromiseUp) {\n      return;\n    }\n\n    if(message.peerId !== searchContext.peerId) {\n      return;\n    }\n\n    const filtered = await this.filterMids([message.mid]);\n    if(this.searchContext !== searchContext) return;\n    const targets = (await Promise.all(filtered.map((message) => this.processItem(message)))).filter(Boolean);\n    if(this.searchContext !== searchContext) return;\n    if(!targets.length) {\n      return;\n    }\n\n    // * it can be already added because of `message_sent`\n    const allTargets = this.previous.concat(this.next, this.current ? [this.current] : []);\n    if(allTargets.some((item) => item?.mid === message.mid)) {\n      return;\n    }\n\n    if(!this.current) {\n      this.previous.push(...targets);\n    } else {\n      this.next.push(...targets);\n    }\n  };\n\n  protected onMessageSent = ({message}: {message: MyMessage}) => {\n    this.onHistoryMultiappend(message);\n  };\n\n  public setSearchContext(context: SearchSuperContext) {\n    this.searchContext = context;\n\n    if(this.searchContext.folderId !== undefined) {\n      this.loadedAllUp = true;\n\n      if(this.searchContext.nextRate === undefined) {\n        this.loadedAllDown = true;\n      }\n    }\n\n    if(this.searchContext.inputFilter._ === 'inputMessagesFilterChatPhotos') {\n      this.loadedAllUp = true;\n    }\n\n    if(this.searchContext.useSearch === false) {\n      this.loadedAllDown = this.loadedAllUp = true;\n    }\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.setSearchContext(context);\n    }\n  }\n\n  public reset() {\n    super.reset();\n    this.searchContext = undefined;\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.reset();\n    }\n  }\n\n  public getPrevious(withOtherSide?: boolean) {\n    let previous = this.previous;\n\n    if(this.otherSideLoader && withOtherSide) {\n      previous = previous.concat(this.otherSideLoader.previous);\n    }\n\n    return previous;\n  }\n\n  public getNext(withOtherSide?: boolean) {\n    let next = this.next;\n\n    if(this.otherSideLoader && withOtherSide) {\n      next = next.concat(this.otherSideLoader.next);\n    }\n\n    return next;\n  }\n\n  public getCurrent() {\n    return this.current || this.otherSideLoader?.current;\n  }\n\n  private goToOtherEnd(length: number) {\n    if(length > 0) return this.go(-this.previous.length);\n    else return this.go(this.next.length);\n  }\n\n  public goRound(length: number, dispatchJump?: boolean) {\n    let ret: ReturnType<SearchListLoader<Item>['goUnsafe']>;\n\n    if(this.otherSideLoader?.current) {\n      ret = this.otherSideLoader.goUnsafe(length, dispatchJump);\n      if(ret.item) {\n        return ret.item;\n      }\n\n      length = ret.leftLength;\n      if(!(length > 0 ? this.otherSideLoader.next : this.otherSideLoader.previous).length) {\n        const loaded = length > 0 ? this.otherSideLoader.loadedAllUp : this.otherSideLoader.loadedAllDown;\n        if(!loaded) { // do not reset anything until it's loaded\n          return;\n        }\n\n        // if other side is loaded too will start from its begin\n        if((length > 0 && (this.otherSideLoader.searchContext.maxId === 1 || this.otherSideLoader.loadedAllDown)) ||\n          (length < 0 && (this.otherSideLoader.searchContext.maxId === 0 || this.otherSideLoader.loadedAllUp))) {\n          return this.otherSideLoader.goToOtherEnd(length);\n        }\n\n        this.otherSideLoader.unsetCurrent(length > 0);\n      }\n    }\n\n    ret = this.goUnsafe(length, dispatchJump);\n    if(!ret.item) {\n      if(this.loadedAllUp && this.loadedAllDown) { // just use the same loader if the list is too short\n        return this.goToOtherEnd(length);\n      } else if(this.otherSideLoader) {\n        length = ret.leftLength;\n        ret = this.otherSideLoader.goUnsafe(length, dispatchJump);\n\n        if(ret.item) {\n          this.unsetCurrent(length > 0);\n        }\n      }\n    }\n\n    return ret?.item;\n  }\n\n  // public setTargets(previous: Item[], next: Item[], reverse: boolean) {\n  //   super.setTargets(previous, next, reverse);\n  // }\n\n  public setCurrent(item: Item) {\n    this.current = item;\n  }\n\n  protected setLoaded(down: boolean, value: boolean) {\n    const changed = super.setLoaded(down, value);\n\n    if(changed &&\n      this.otherSideLoader &&\n      value &&\n      this.searchContext?.useSearch !== false/*  &&\n      (this.reverse ? this.loadedAllUp : this.loadedAllDown) */) {\n      const reverse = this.loadedAllUp;\n      this.otherSideLoader.setSearchContext({\n        ...this.searchContext,\n        maxId: reverse ? 1 : 0\n      });\n\n      // these 'reverse' are different, not a mistake here.\n      this.otherSideLoader.reverse = this.reverse;\n      this.otherSideLoader.setLoaded(reverse, true);\n      this.otherSideLoader.load(!reverse);\n    }\n\n    return changed;\n  }\n\n  public cleanup() {\n    this.reset();\n    rootScope.removeEventListener('history_delete', this.onHistoryDelete);\n    rootScope.removeEventListener('history_multiappend', this.onHistoryMultiappend);\n    rootScope.removeEventListener('message_sent', this.onMessageSent);\n    this.onEmptied = undefined;\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.cleanup();\n      this.otherSideLoader = undefined;\n    }\n  }\n}\n","import PopupElement, {addCancelButton, PopupButton, PopupOptions} from '.';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport CheckboxField, {CheckboxFieldOptions} from '@components/checkboxField';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {avatarNew} from '@components/avatarNew';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport rootScope from '@lib/rootScope';\nimport InputField from '@components/inputField';\n\nexport type PopupPeerButton = Omit<PopupButton, 'callback'> & Partial<{callback: PopupPeerButtonCallback, onlyWithCheckbox: PopupPeerCheckboxOptions}>;\nexport type PopupPeerButtonCallbackCheckboxes = Set<LangPackKey>;\nexport type PopupPeerButtonCallback = (e: MouseEvent, checkboxes?: PopupPeerButtonCallbackCheckboxes) => void;\nexport type PopupPeerCheckboxOptions = CheckboxFieldOptions & {checkboxField?: CheckboxField};\n\nexport type PopupPeerOptions = Omit<PopupOptions, 'buttons' | 'title'> & Partial<{\n  peerId: PeerId,\n  threadId: number,\n  title: string | HTMLElement | DocumentFragment,\n  titleLangKey: LangPackKey,\n  titleLangArgs: any[],\n  noTitle: boolean,\n  description: Parameters<typeof setInnerHTML>[1] | true,\n  descriptionRaw: string,\n  descriptionLangKey: LangPackKey,\n  descriptionLangArgs: any[],\n  buttons: Array<PopupPeerButton>,\n  checkboxes: Array<PopupPeerCheckboxOptions>,\n  inputField: InputField,\n  old: boolean\n}>;\nexport default class PopupPeer extends PopupElement {\n  protected description: HTMLParagraphElement;\n  private inputField?: InputField;\n\n  constructor(private className: string, options: PopupPeerOptions = {}) {\n    super('popup-peer' + (className ? ' ' + className : ''), {\n      overlayClosable: true,\n      ...options,\n      title: true,\n      buttons: options.buttons && addCancelButton(options.buttons)\n    });\n\n    if(options.peerId) {\n      const isSavedDialog = !!(options.peerId === rootScope.myId && options.threadId);\n      const {node} = avatarNew({\n        middleware: this.middlewareHelper.get(),\n        size: 32,\n        isDialog: true,\n        peerId: isSavedDialog ? options.threadId : options.peerId,\n        threadId: isSavedDialog ? undefined : options.threadId,\n        meAsNotes: isSavedDialog\n      });\n      this.header.prepend(node);\n    }\n\n    if(!options.noTitle) {\n      if(options.titleLangKey || !options.title) {\n        this.title.append(i18n(options.titleLangKey || 'AppName', options.titleLangArgs));\n      } else if(options.title instanceof HTMLElement || options.title instanceof DocumentFragment) {\n        this.title.append(options.title);\n      } else this.title.innerText = options.title || '';\n    }\n\n    const fragment = document.createDocumentFragment();\n\n    if(options.descriptionLangKey || options.description || options.descriptionRaw) {\n      const p = this.description = document.createElement('p');\n      p.classList.add('popup-description');\n      if(options.descriptionLangKey) p.append(i18n(options.descriptionLangKey, options.descriptionLangArgs));\n      else if(options.description && options.description !== true) setInnerHTML(p, options.description);\n      else if(options.descriptionRaw) p.append(wrapEmojiText(options.descriptionRaw));\n\n      fragment.append(p);\n    }\n\n    if(options.inputField) {\n      this.inputField = options.inputField;\n      fragment.append(options.inputField.container);\n      const button = options.buttons.find((button) => !button.isCancel);\n      toggleDisability([button.element], !options.inputField.isValid());\n    }\n\n    if(options.checkboxes) {\n      this.container.classList.add('have-checkbox');\n\n      options.checkboxes.forEach((o) => {\n        o.withRipple = true;\n        const checkboxField = new CheckboxField(o);\n        o.checkboxField = checkboxField;\n        fragment.append(checkboxField.label);\n      });\n\n      options.buttons.forEach((button) => {\n        if(button.callback) {\n          const original = button.callback;\n          button.callback = (e) => {\n            const c: Set<LangPackKey> = new Set();\n            options.checkboxes.forEach((o) => {\n              if(o.checkboxField.checked) {\n                c.add(o.text);\n              }\n            });\n            original(e, c);\n          };\n        }\n\n        const checkbox = button.onlyWithCheckbox;\n        if(checkbox) {\n          const onChange = () => {\n            toggleDisability([button.element], !checkbox.checkboxField.checked);\n          };\n          this.listenerSetter.add(checkbox.checkboxField.input)('change', onChange);\n          onChange();\n        }\n      });\n    }\n\n    if(options.inputField) {\n      const button = options.buttons.find((button) => !button.isCancel);\n      this.listenerSetter.add(options.inputField.input)('input', () => {\n        toggleDisability([button.element], !options.inputField.isValid());\n      });\n    }\n\n    this.header.after(fragment);\n  }\n\n  public show(animate?: boolean): void {\n    super.show(animate);\n    this.inputField?.input.focus();\n  }\n}\n","import classNames from '@helpers/string/classNames';\nimport PopupElement, {addCancelButton} from '@components/popups';\nimport PopupPeer, {PopupPeerCheckboxOptions, PopupPeerOptions} from '@components/popups/peer';\n\nexport type ConfirmationPopupRejectReason = 'canceled' | 'closed';\n\n// type PopupConfirmationOptions = Pick<PopupPeerOptions, 'titleLangKey'>;\nexport type PopupConfirmationOptions = PopupPeerOptions & {\n  button: PopupPeerOptions['buttons'][0],\n  checkbox?: PopupPeerOptions['checkboxes'][0],\n  inputField?: PopupPeerOptions['inputField'],\n  rejectWithReason?: boolean,\n  className?: string;\n  onPopup?: (popup: PopupPeer) => void;\n};\n\nexport default function confirmationPopup<T extends PopupConfirmationOptions>(\n  options: T\n): Promise<T['checkboxes'] extends PopupPeerCheckboxOptions[] ? Array<boolean> : (T['checkbox'] extends PopupPeerCheckboxOptions ? boolean : void)> {\n  return new Promise<any>((resolve, reject: (reason?: ConfirmationPopupRejectReason) => void) => {\n    const {button, checkbox, rejectWithReason} = options;\n    button.callback = (e, set) => {\n      if(checkbox || !set) {\n        resolve(set ? !!set.size : undefined);\n      } else {\n        resolve(options.checkboxes.map((checkbox) => set.has(checkbox.text)));\n      }\n    };\n\n    const buttons = addCancelButton(options.buttons || [button]);\n    const cancelButton = buttons.find((button) => button.isCancel);\n    cancelButton.callback = () => {\n      reject(rejectWithReason ? 'canceled' : undefined);\n    };\n\n    options.buttons = buttons;\n    options.checkboxes ??= checkbox && [checkbox];\n\n    const popup = PopupElement.createPopup(PopupPeer, classNames('popup-confirmation', options.className), options);\n\n    options.onPopup?.(popup);\n\n    popup.addEventListener('closeAfterTimeout', () => {\n      reject(rejectWithReason ? 'closed' : undefined);\n    });\n\n    popup.show();\n  });\n}\n","import {JSX, ParentComponent, Ref, splitProps} from 'solid-js';\nimport {LangPackKey, FormatterArguments, i18n} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\n\nexport type SectionOptions = {\n  name?: LangPackKey | HTMLElement | DocumentFragment | JSX.Element,\n  nameArgs?: FormatterArguments,\n  nameRight?: JSX.Element,\n  nameRef?: Ref<HTMLDivElement>,\n  caption?: LangPackKey | Exclude<JSX.Element, string>,\n  captionArgs?: FormatterArguments,\n  captionOld?: boolean,\n  captionRef?: Ref<HTMLDivElement>,\n  noDelimiter?: boolean,\n  noShadow?: boolean,\n  noMarginBottom?: boolean,\n  class?: JSX.HTMLAttributes<HTMLDivElement>['class'],\n  innerClass?: string,\n  contentProps?: JSX.HTMLAttributes<HTMLDivElement>,\n  ref?: Ref<HTMLDivElement>\n};\n\nconst className = 'sidebar-left-section';\nconst SectionContent: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {\n  return (\n    <div ref={props.ref} class={classNames(className + '-content', props.class)}>\n      {props.children}\n    </div>\n  );\n};\nconst SectionCaption = (props: Pick<SectionOptions, 'caption' | 'captionArgs' | 'captionRef'>) => {\n  return (\n    <SectionContent ref={props.captionRef} class={className + '-caption'}>\n      {typeof props.caption === 'string' ?\n        i18n(props.caption, props.captionArgs) :\n        props.caption}\n    </SectionContent>\n  );\n};\nconst Section: ParentComponent<SectionOptions & JSX.HTMLAttributes<HTMLDivElement>> = (props) => {\n  const [, rest] = splitProps(props, ['name', 'nameRef', 'nameArgs', 'nameRight', 'innerClass', 'caption', 'captionArgs', 'captionOld', 'captionRef', 'noDelimiter', 'noShadow', 'class', 'contentProps']);\n  return (\n    <div\n      class={classNames(className + '-container', props.class)}\n      ref={props.ref}\n      {...rest}\n    >\n      <div\n        class={classNames(\n          className,\n          props.noShadow && 'no-shadow',\n          props.noDelimiter && 'no-delimiter',\n          props.innerClass,\n          props.noMarginBottom && 'no-margin-bottom'\n        )}\n      >\n        <SectionContent {...props.contentProps}>\n          {props.name && (\n            <div ref={props.nameRef} class={classNames('sidebar-left-h2', className + '-name')}>\n              {typeof(props.name) === 'string' ? i18n(props.name as LangPackKey, props.nameArgs) : props.name}\n              {props.nameRight && <div class={className + '-name-right'}>{props.nameRight}</div>}\n            </div>\n          )}\n          {props.children}\n        </SectionContent>\n        {props.caption && props.captionOld && <SectionCaption {...props} />}\n      </div>\n      {props.caption && !props.captionOld && <SectionCaption {...props} />}\n    </div>\n  );\n}\n\nexport default Section;\n","import appDialogsManager, {AppDialogsManager} from '@lib/appDialogsManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport Section from '@components/section';\nimport {createMemo, createRoot, createSignal, JSX, Show} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {Middleware} from '@helpers/middleware';\nimport Scrollable from '@components/scrollable2';\n\nexport type SearchGroupType = 'contacts' | 'globalContacts' | 'messages' | string;\n\nexport type SearchGroup = ReturnType<typeof createSearchGroup>;\n\nexport function createSearchGroup(options: {\n  name?: LangPackKey | boolean,\n  type: string,\n  clearable?: boolean,\n  className?: string,\n  clickable?: boolean,\n  autonomous?: boolean,\n  onFound?: Parameters<AppDialogsManager['setListClickListener']>[0]['onFound'],\n  noIcons?: boolean,\n  middleware?: Middleware,\n  scrollableX?: boolean\n}) {\n  const {\n    name,\n    type,\n    clearable = true,\n    className,\n    clickable = true,\n    autonomous = true,\n    onFound,\n    noIcons,\n    middleware,\n    scrollableX\n  } = options;\n\n  const NameRight = (props: {\n    children: JSX.Element,\n    onClick?: () => void\n  }) => {\n    return (\n      <span\n        class=\"cursor-pointer hover-underline\"\n        onClick={props.onClick}\n      >\n        {props.children}\n      </span>\n    );\n  };\n\n  const [hide, setHide] = createSignal(true);\n  const [showingMore, setShowingMore] = createSignal(false);\n  const [showMoreClassName, setShowMoreClassName] = createSignal<string>();\n  const [_nameRight, setNameRight] = createSignal<Parameters<typeof NameRight>[0]>();\n  const nameRight = createMemo(() => {\n    const _ = _nameRight();\n    if(_) {\n      return NameRight(_);\n    }\n\n    const toggleClassName = showMoreClassName();\n    if(!toggleClassName) {\n      return;\n    }\n\n    return (\n      <NameRight\n        onClick={() => {\n          setShowingMore((v) => !v);\n        }}\n      >\n        {i18n(showingMore() ? 'Separator.ShowLess' : 'Separator.ShowMore')}\n      </NameRight>\n    );\n  });\n  const list = appDialogsManager.createChatList();\n  let container: HTMLDivElement;\n  let nameEl: HTMLDivElement;\n  let placeholder: HTMLElement;\n\n  createRoot((dispose) => {\n    <Section\n      name={name}\n      nameRef={(ref) => nameEl = ref}\n      nameRight={nameRight()}\n      class={classNames(\n        'search-group',\n        'search-group-' + type,\n        className,\n        hide() && 'hide',\n        showMoreClassName() && !showingMore() && showMoreClassName(),\n        scrollableX && 'search-group-with-scroll'\n      )}\n      ref={(ref) => container = ref}\n      innerClass=\"search-group-inner\"\n      contentProps={{\n        class: 'search-group-content'\n      }}\n    >\n      <Show when={scrollableX} fallback={list}>\n        <Scrollable\n          class=\"search-group-scrollable-x\"\n          axis=\"x\"\n        >\n          {list}\n        </Scrollable>\n      </Show>\n    </Section>;\n\n    middleware?.onClean(dispose);\n  });\n\n  if(clickable) {\n    appDialogsManager.setListClickListener({\n      list,\n      onFound,\n      withContext: undefined,\n      autonomous\n    });\n  }\n\n  const group = {\n    container,\n    list,\n    nameEl,\n    autonomous,\n    noIcons,\n    createPlaceholder: undefined as () => HTMLElement,\n    get placeholder() {\n      return placeholder;\n    },\n    addPlaceholder(el: HTMLElement) {\n      group.removePlaceholder();\n      placeholder = el;\n      container.append(el);\n    },\n    removePlaceholder() {\n      placeholder?.remove();\n      placeholder = undefined;\n    },\n    clear() {\n      setHide(true);\n      group.removePlaceholder();\n      if(clearable) {\n        Array.from(list.children).forEach((el) => {\n          const dialogElement = (el as any).dialogElement;\n          if(dialogElement) dialogElement?.remove();\n          else el.remove();\n        });\n      }\n    },\n    setActive() {\n      setHide(false);\n    },\n    toggle() {\n      if(list.childElementCount) {\n        group.setActive();\n      } else {\n        group.clear();\n      }\n    },\n    needShowMoreButton(toggleClassName = 'is-short-5') {\n      setShowMoreClassName(toggleClassName);\n    },\n    setNameRight\n  };\n\n  return group;\n}\n","import App from '@config/app';\nimport DEBUG from '@config/debug';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport {ConnectionStatus} from '@lib/mtproto/connectionStatus';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {AppManagers} from '@lib/managers';\nimport singleInstance from '@lib/singleInstance';\nimport InputSearch from '@components/inputSearch';\n\nconst NO_STATUS = false;\nconst TEST_DBLCLICK = false;\nconst HAVE_RECONNECT_BUTTON = false;\n\nexport default class ConnectionStatusComponent {\n  public static CHANGE_STATE_DELAY = 400;\n  public static INITIAL_DELAY = 2000;\n  public static ANIMATION_DURATION = 250;\n\n  private hadConnect = false;\n  private retryAt: number;\n  private connecting = false;\n  private timedOut = false;\n  private updating = false;\n\n  private log: ReturnType<typeof logger>;\n\n  private setFirstConnectionTimeout: number;\n  private setStateTimeout: number;\n\n  private managers: AppManagers;\n  private inputSearch: InputSearch;\n  private rAF: number;\n\n  public construct(\n    managers: AppManagers,\n    chatsContainer: HTMLElement,\n    inputSearch: InputSearch\n  ) {\n    this.managers = managers;\n    this.inputSearch = inputSearch;\n    this.log = logger('CS', undefined, undefined);\n    this.inputSearch.setPlaceholder('Search');\n\n    rootScope.addEventListener('connection_status_change', (status) => {\n      // console.log(status);\n\n      this.setConnectionStatus();\n    });\n\n    rootScope.addEventListener('state_synchronizing', () => {\n      this.updating = true;\n      DEBUG && this.log('updating', this.updating);\n      this.setState();\n    });\n\n    rootScope.addEventListener('state_synchronized', () => {\n      DEBUG && this.log('state_synchronized');\n      this.updating = false;\n      DEBUG && this.log('updating', this.updating);\n      this.setState();\n    });\n\n    this.setFirstConnectionTimeout = window.setTimeout(\n      this.setConnectionStatus,\n      ConnectionStatusComponent.INITIAL_DELAY\n    );\n\n    if(TEST_DBLCLICK) {\n      let bool = true;\n      document.addEventListener('dblclick', () => {\n        this.setConnectionStatus(bool ? (\n            bool = false,\n            ConnectionStatus.Closed\n          ) : (\n            bool = true,\n            this.updating = false,\n            ConnectionStatus.Connected\n          )\n        );\n      });\n    }\n  }\n\n  private setConnectionStatus = (overrideStatus?: ConnectionStatus) => {\n    Promise.all([\n      rootScope.managers.apiManager.getBaseDcId(),\n      rootScope.managers.rootScope.getConnectionStatus()\n    ]).then(([baseDcId, connectionStatus]) => {\n      if(!baseDcId) {\n        baseDcId = App.baseDcId;\n      }\n\n      if(this.setFirstConnectionTimeout) {\n        clearTimeout(this.setFirstConnectionTimeout);\n        this.setFirstConnectionTimeout = 0;\n      }\n\n      const status = connectionStatus['NET-' + baseDcId];\n      const online = status && (overrideStatus ?? status.status) === ConnectionStatus.Connected;\n\n      if(this.connecting && online) {\n        this.managers.apiUpdatesManager.forceGetDifference();\n      }\n\n      if(online && !this.hadConnect) {\n        this.hadConnect = true;\n      }\n\n      this.timedOut = status && (overrideStatus ?? status.status) === ConnectionStatus.TimedOut;\n      this.connecting = !online;\n      this.retryAt = status && status.retryAt;\n      DEBUG && this.log('connecting', this.connecting);\n      this.setState();\n    });\n  };\n\n  private wrapSetStatusText = (...args: Parameters<InputSearch['setPlaceholder']>) => {\n    return () => {\n      return this.inputSearch.setPlaceholder(...args);\n    };\n  };\n\n  private getA(langPackKey: LangPackKey, callback: () => void) {\n    const a = document.createElement('a');\n    a.classList.add('force-reconnect');\n    a.append(i18n(langPackKey));\n    attachClickEvent(a, (e) => {\n      cancelEvent(e);\n      callback();\n    });\n\n    return a;\n  }\n\n  private setState = () => {\n    if(singleInstance.deactivatedReason) {\n      return;\n    }\n\n    let setText: () => void;\n    if(this.connecting) {\n      if(this.timedOut) {\n        // const a = this.getA('ConnectionStatus.ForceReconnect', () => this.managers.networkerFactory.forceReconnect());\n        // setText = this.wrapSetStatusText('ConnectionStatus.TimedOut', [a]);\n        setText = this.wrapSetStatusText('Updating');\n      } else if(this.hadConnect) {\n        if(this.retryAt !== undefined) {\n          const timerSpan = document.createElement('span');\n          const retryAt = this.retryAt;\n          const setTime = () => {\n            const now = Date.now();\n            timerSpan.innerText = '' + Math.max(0, Math.round((retryAt - now) / 1000));\n            if(now > retryAt) {\n              clearInterval(interval);\n            }\n          };\n          const interval = setInterval(setTime, 1e3);\n          setTime();\n\n          if(HAVE_RECONNECT_BUTTON) {\n            const a = this.getA('ConnectionStatus.Reconnect', () => this.managers.networkerFactory.forceReconnectTimeout());\n            setText = this.wrapSetStatusText('ConnectionStatus.ReconnectIn', [timerSpan, a]);\n          } else {\n            setText = this.wrapSetStatusText('ConnectionStatus.ReconnectInPlain', [timerSpan]);\n          }\n        } else {\n          setText = this.wrapSetStatusText('ConnectionStatus.Reconnecting');\n        }\n      } else {\n        setText = this.wrapSetStatusText('ConnectionStatus.Waiting');\n      }\n    } else if(this.updating) {\n      setText = this.wrapSetStatusText('Updating');\n    } else {\n      setText = this.wrapSetStatusText('Search');\n    }\n\n    DEBUG && this.log('setState', this.connecting || this.updating);\n    if(this.rAF) window.cancelAnimationFrame(this.rAF);\n    this.rAF = window.requestAnimationFrame(() => {\n      this.rAF = 0;\n      if(this.setStateTimeout) clearTimeout(this.setStateTimeout);\n\n      const wasVisible = this.inputSearch.isLoading();\n      const cb = () => {\n        if(NO_STATUS) {\n          return;\n        }\n\n        setText();\n        const isConnecting = this.connecting || this.updating;\n        this.inputSearch.toggleLoading(isConnecting);\n        this.setStateTimeout = 0;\n        DEBUG && this.log('setState: isShown:', isConnecting);\n      };\n\n      if(wasVisible) {\n        cb();\n      } else {\n        this.setStateTimeout = window.setTimeout(cb, ConnectionStatusComponent.CHANGE_STATE_DELAY);\n      }\n    });\n  };\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport ButtonIcon from '@components/buttonIcon';\nimport ConnectionStatusComponent from '@components/connectionStatus';\nimport Icon from '@components/icon';\nimport InputField from '@components/inputField';\nimport ProgressivePreloader from '@components/preloader';\nimport SetTransition from '@components/singleTransition';\nimport classNames from '@helpers/string/classNames';\n\nexport default class InputSearch {\n  public container: HTMLElement;\n  public input: HTMLInputElement;\n  public inputField: InputField;\n  public clearBtn: HTMLElement;\n  public searchIcon: HTMLElement;\n  public backBtn: HTMLElement;\n\n  public prevValue = '';\n  public timeout = 0;\n  public onChange: (value: string) => void;\n  public onClear: (e?: MouseEvent, wasEmpty?: boolean) => void;\n  public onDebounce: (start: boolean) => void;\n  public onBack: () => void;\n  public onEnter: (value: string) => void;\n\n  private statusPreloader: ProgressivePreloader;\n  private currentLangPackKey: LangPackKey;\n  public currentPlaceholder: HTMLElement;\n\n  private listenerSetter: ListenerSetter;\n  private debounceTime: number;\n  private verifyDebounce: (value: string, prevValue: string) => boolean;\n\n  private alwaysShowClear: boolean;\n  private arrowBack: boolean;\n  private noPlaceholderAnimation: boolean;\n\n  constructor(options: {\n    placeholder?: LangPackKey,\n    onChange?: (value: string) => void,\n    onClear?: InputSearch['onClear'],\n    onFocusChange?: (isFocused: boolean) => void,\n    onDebounce?: (start: boolean) => void,\n    onBack?: () => void,\n    onEnter?: (value: string) => void,\n    alwaysShowClear?: boolean,\n    noBorder?: boolean,\n    noFocusEffect?: boolean,\n    debounceTime?: number,\n    verifyDebounce?: (value: string, prevValue: string) => boolean,\n    arrowBack?: boolean,\n    oldStyle?: boolean,\n    noPlaceholderAnimation?: boolean\n  } = {}) {\n    this.inputField = new InputField({\n      // placeholder,\n      plainText: true,\n      withBorder: !options.noBorder\n    });\n\n    this.listenerSetter = new ListenerSetter();\n    this.container = this.inputField.container;\n    this.container.classList.remove('input-field');\n    this.container.classList.add('input-search');\n\n    if(options.oldStyle) {\n      this.container.classList.add('old-style');\n    }\n\n    this.onChange = options.onChange;\n    this.onClear = options.onClear;\n    this.onDebounce = options.onDebounce;\n    this.onBack = options.onBack;\n    this.onEnter = options.onEnter;\n    this.debounceTime = options.debounceTime ?? 300;\n    this.verifyDebounce = options.verifyDebounce;\n    this.alwaysShowClear = options.alwaysShowClear;\n    this.noPlaceholderAnimation = options.noPlaceholderAnimation;\n\n    const input = this.input = this.inputField.input as HTMLInputElement;\n    input.classList.add('input-search-input');\n\n    if(!options.noFocusEffect) {\n      input.classList.add('with-focus-effect');\n    }\n\n    const searchIcon = this.searchIcon = this.createIcon('search', 'input-search-icon');\n    const clearBtn = this.clearBtn = this.createButtonIcon('close', 'input-search-clear');\n\n    this.listenerSetter.add(input)('input', this.onInput);\n    this.listenerSetter.add(input)('keydown', this.onKeyDown);\n    attachClickEvent(clearBtn, this.onClearClick, {listenerSetter: this.listenerSetter, cancelMouseDown: true});\n\n    if(options.placeholder) {\n      (input as HTMLInputElement).placeholder = ' ';\n      this.setPlaceholder(options.placeholder);\n    }\n\n    if(options.onFocusChange) {\n      this.listenerSetter.add(input)('focusin', () => {\n        options.onFocusChange?.(true);\n      });\n\n      this.listenerSetter.add(input)('focusout', () => {\n        options.onFocusChange?.(false);\n      });\n    }\n\n    this.container.append(searchIcon, clearBtn);\n\n    this.setArrowBack(options.arrowBack);\n  }\n\n  public setArrowBack = (arrowBack: boolean) => {\n    if(this.arrowBack === arrowBack) return;\n    this.arrowBack = arrowBack;\n\n    this.container.classList.toggle('with-arrow-back', arrowBack);\n\n    if(arrowBack && !this.backBtn) {\n      this.backBtn = this.createButtonIcon('arrow_prev', 'input-search-icon', 'input-search-back');\n      this.container.append(this.backBtn);\n      attachClickEvent(this.backBtn, this.onBack, {listenerSetter: this.listenerSetter, cancelMouseDown: true});\n    }\n\n    this.searchIcon.classList.toggle('hide', arrowBack);\n    this.backBtn && this.backBtn.classList.toggle('hide', !arrowBack);\n    this.clearBtn.classList.toggle('always-visible', !arrowBack && !!this.alwaysShowClear);\n  };\n\n  public createButtonIcon(icon: Icon, ...args: string[]) {\n    args ??= [];\n    args.push('input-search-part', 'input-search-button');\n    return ButtonIcon(icon + ' ' + args.join(' '), {noRipple: true});\n  }\n\n  public createIcon(icon: Icon, ...args: string[]) {\n    return Icon(icon, 'input-search-part', ...args);\n  }\n\n  public isLoading() {\n    return this.container.classList.contains('is-connecting');\n  }\n\n  public toggleLoading(loading: boolean) {\n    const another = this.arrowBack ? this.clearBtn : this.searchIcon;\n    if(!this.statusPreloader) {\n      this.statusPreloader = new ProgressivePreloader({cancelable: false});\n      this.statusPreloader.constructContainer({color: 'transparent', bold: true});\n      this.statusPreloader.construct?.();\n      this.statusPreloader.preloader.classList.add('is-visible', 'will-animate');\n      another.classList.add('will-animate');\n    }\n\n    if(loading && !this.statusPreloader.preloader.parentElement) {\n      this.container.append(this.statusPreloader.preloader);\n    }\n\n    this.statusPreloader.preloader.classList.toggle('is-hiding', !loading);\n    another.classList.toggle('is-hiding', loading || (another === this.clearBtn && this.inputField.isEmpty()));\n    SetTransition({\n      element: this.container,\n      className: 'is-connecting',\n      forwards: loading,\n      duration: ConnectionStatusComponent.ANIMATION_DURATION,\n      onTransitionEnd: loading ? undefined : () => {\n        this.statusPreloader.preloader.remove();\n      }\n      // useRafs: this.statusPreloader.preloader.isConnected ? 0 : 2\n    });\n  }\n\n  public setPlaceholder = (langPackKey: LangPackKey, args?: any[]) => {\n    if(this.currentLangPackKey === langPackKey) return;\n    this.currentLangPackKey = langPackKey;\n\n    const oldPlaceholder = this.currentPlaceholder;\n    if(oldPlaceholder) {\n      SetTransition({\n        element: oldPlaceholder,\n        className: 'is-hiding',\n        forwards: true,\n        duration: ConnectionStatusComponent.ANIMATION_DURATION,\n        onTransitionEnd: () => {\n          oldPlaceholder.remove();\n        }\n      });\n    }\n\n    this.currentPlaceholder = i18n(langPackKey, args);\n    this.currentPlaceholder.classList.add(...[\n      'input-search-placeholder',\n      !this.noPlaceholderAnimation && 'will-animate'\n    ].filter(Boolean));\n    this.container.append(this.currentPlaceholder);\n  };\n\n  onInput = () => {\n    if(!this.onChange) return;\n\n    const {value, prevValue} = this;\n    if(value === prevValue) {\n      return;\n    }\n\n    this.prevValue = value;\n    if(this.verifyDebounce?.(value, prevValue) === false) {\n      this.clearTimeout(false);\n      this.onChange(value);\n      return;\n    }\n\n    this.clearTimeout(true);\n    this.timeout = window.setTimeout(() => {\n      this.onDebounce?.(false);\n      this.onChange(value);\n    }, this.debounceTime);\n  };\n\n  onKeyDown = (e: KeyboardEvent) => {\n    if(e.key !== 'Enter' || !this.onEnter) return;\n    const value = this.value;\n    if(!value) return;\n    this.onEnter(value);\n  };\n\n  onClearClick = (e?: MouseEvent) => {\n    const isEmpty = this.inputField.isEmpty();\n    this.value = '';\n    this.onChange?.('');\n    this.onClear?.(e, isEmpty);\n  };\n\n  clearTimeout = (debounceStart: boolean) => {\n    clearTimeout(this.timeout);\n    this.onDebounce?.(debounceStart);\n  };\n\n  get value() {\n    return this.inputField.value;\n  }\n\n  set value(value: string) {\n    this.prevValue = value;\n    this.clearTimeout(false);\n    this.inputField.value = value;\n  }\n\n  public remove() {\n    this.clearTimeout(false);\n    this.verifyDebounce = undefined;\n    this.listenerSetter.removeAll();\n  }\n}\n","import EventListenerBase, {EventListenerListeners} from '@helpers/eventListenerBase';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport {AppManagers} from '@lib/managers';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport ButtonIcon from '@components/buttonIcon';\nimport Scrollable from '@components/scrollable';\nimport SidebarSlider from '@components/slider';\n\nexport interface SliderSuperTabConstructable<T extends SliderSuperTab = any> {\n  new(slider: SidebarSlider, destroyable: boolean): T;\n}\n\nexport interface SliderSuperTabEventableConstructable {\n  new(slider: SidebarSlider, destroyable: boolean): SliderSuperTabEventable;\n}\n\nexport default class SliderSuperTab {\n  public static getInitArgs?(...args: any[]): any;\n  public static noSame?: boolean;\n\n  public container: HTMLElement;\n\n  public header: HTMLElement;\n  public closeBtn: HTMLElement;\n  public title: HTMLElement;\n\n  public content: HTMLElement;\n  public scrollable: Scrollable;\n\n  public slider: SidebarSlider;\n  public destroyable: boolean;\n  public listenerSetter: ListenerSetter;\n\n  public managers: AppManagers;\n  public middlewareHelper: MiddlewareHelper;\n\n  public isConfirmationNeededOnClose: () => void | boolean | Promise<any>; // should return boolean instantly or `Promise` from `confirmationPopup`\n\n  constructor(slider: SidebarSlider, destroyable?: boolean) {\n    this._constructor(slider, destroyable);\n  }\n\n  public _constructor(slider: SidebarSlider, destroyable = true): any {\n    this.slider = slider;\n    this.middlewareHelper = slider ? slider.getMiddleware().create() : getMiddleware();\n    this.destroyable = destroyable;\n\n    this.container = document.createElement('div');\n    this.container.classList.add('tabs-tab', 'sidebar-slider-item');\n\n    // * Header\n    this.header = document.createElement('div');\n    this.header.classList.add('sidebar-header');\n\n    this.closeBtn = ButtonIcon('left sidebar-close-button', {noRipple: true});\n    this.title = document.createElement('div');\n    this.title.classList.add('sidebar-header__title');\n    this.header.append(this.closeBtn, this.title);\n\n    // * Content\n    this.content = document.createElement('div');\n    this.content.classList.add('sidebar-content');\n\n    this.scrollable = new Scrollable(this.content, undefined, undefined, true);\n    this.scrollable.attachBorderListeners(this.container);\n\n    this.container.append(this.header, this.content);\n\n    this.slider?.addTab(this);\n\n    this.listenerSetter = new ListenerSetter();\n  }\n\n  public close() {\n    return this.slider.closeTab(this);\n  }\n\n  public async open(...args: Parameters<typeof this['init']>) {\n    if(this.init) {\n      try {\n        const result = this.init(...args);\n        this.init = null;\n\n        if(result instanceof Promise) {\n          await result;\n        }\n      } catch(err) {\n        console.error('open tab error', err);\n      }\n    }\n\n    this.slider.selectTab(this);\n  }\n\n  public init(...args: any[]): Promise<any> | any {\n\n  }\n\n  protected onOpen() {}\n  protected onOpenAfterTimeout() {}\n  protected onClose() {}\n\n  protected onCloseAfterTimeout() {\n    if(this.destroyable) { // ! WARNING, пока что это будет работать только с самой последней внутренней вкладкой !\n      this.slider?.deleteTab(this);\n      this.container.remove();\n      this.scrollable.destroy();\n      this.listenerSetter?.removeAll();\n      this.middlewareHelper?.destroy();\n    }\n  }\n\n  protected setTitle(key: LangPackKey) {\n    this.title.replaceChildren(i18n(key));\n  }\n}\n\nexport class SliderSuperTabEventable<T extends EventListenerListeners = {}> extends SliderSuperTab {\n  public eventListener: EventListenerBase<{\n    destroy: () => void | Promise<any>,\n    destroyAfter: (promise: Promise<void>) => void,\n    close: () => void\n  } & T>;\n\n  constructor(slider: SidebarSlider) {\n    super(slider);\n    this.eventListener = new EventListenerBase();\n  }\n\n  onClose() {\n    // @ts-ignore\n    this.eventListener.dispatchEvent('close');\n  }\n\n  onCloseAfterTimeout() {\n    // @ts-ignore\n    const results = this.eventListener.dispatchResultableEvent('destroy');\n    // @ts-ignore\n    this.eventListener.dispatchEvent('destroyAfter', Promise.all(results).then(noop, noop));\n    this.eventListener.cleanup();\n    return super.onCloseAfterTimeout();\n  }\n}\n\n/* // @ts-ignore\ninterface SliderSuperEventsTab extends SliderSuperTab, EventListenerBase<{}> {\n  superConstructor: (...args: any[]) => any;\n}\nclass SliderSuperEventsTab implements SliderSuperEventsTab {\n  constructor(slider: SidebarSlider) {\n    this.superConstructor([slider, true]);\n  }\n}\napplyMixins(SliderSuperEventsTab, [SliderSuperTab, EventListenerBase]);\n\n(window as any).lol = SliderSuperEventsTab\n\nexport {SliderSuperEventsTab}; */\n","import {horizontalMenu} from '@components/horizontalMenu';\nimport TransitionSlider from '@components/transition';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport SliderSuperTab, {SliderSuperTabConstructable} from '@components/sliderTab';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport {MaybePromise} from '@types';\n\nconst TRANSITION_TIME = 250;\n\nexport {SliderSuperTab};\n\nexport type SidebarSliderOptions = {\n  sidebarEl: SidebarSlider['sidebarEl'],\n  tabs?: SidebarSlider['tabs'],\n  canHideFirst?: SidebarSlider['canHideFirst'],\n  navigationType: SidebarSlider['navigationType']\n}\n\nexport default class SidebarSlider {\n  protected _selectTab: ReturnType<typeof horizontalMenu>;\n  protected historyTabIds: (number | SliderSuperTab)[] = []; // * key is any, since right sidebar is ugly nowz\n  protected tabsContainer: HTMLElement;\n  public sidebarEl: HTMLElement;\n  protected tabs: Map<any, SliderSuperTab>; // * key is any, since right sidebar is ugly now\n  private canHideFirst = false;\n  private navigationType: NavigationItem['type'];\n  protected managers: AppManagers;\n  protected middlewareHelper: MiddlewareHelper;\n  public onOpenTab: () => MaybePromise<void>;\n  public onTabsCountChange?: () => void;\n\n  constructor(options: SidebarSliderOptions) {\n    safeAssign(this, options);\n\n    this.tabs ??= new Map();\n\n    this.tabsContainer = this.sidebarEl.querySelector('.sidebar-slider');\n    this._selectTab = TransitionSlider({\n      content: this.tabsContainer,\n      type: 'navigation',\n      transitionTime: TRANSITION_TIME\n    });\n    if(!this.canHideFirst) {\n      this._selectTab(0);\n    }\n\n    this.middlewareHelper = getMiddleware();\n\n    // Array.from(this.sidebarEl.querySelectorAll('.sidebar-close-button') as any as HTMLElement[]).forEach((el) => {\n    //   attachClickEvent(el, this.onCloseBtnClick);\n    // });\n  }\n\n  public getMiddleware() {\n    return this.middlewareHelper.get();\n  }\n\n  public onCloseBtnClick = () => {\n    const item = appNavigationController.findItemByType(this.navigationType);\n    if(item) {\n      appNavigationController.back(this.navigationType);\n      this.onTabsCountChange?.();\n    } else if(this.historyTabIds.length) {\n      this.closeTab(this.historyTabIds[this.historyTabIds.length - 1]);\n    }\n    // this.closeTab();\n  };\n\n  public closeTab = (id?: number | SliderSuperTab, animate?: boolean, isNavigation?: boolean) => {\n    if(id !== undefined && this.historyTabIds[this.historyTabIds.length - 1] !== id) {\n      this.removeTabFromHistory(id);\n      return false;\n    }\n\n    // console.log('sidebar-close-button click:', this.historyTabIDs);\n    const closingId = this.historyTabIds.pop(); // pop current\n    this.onCloseTab(closingId, animate, isNavigation);\n\n    const tab = this.historyTabIds[this.historyTabIds.length - 1];\n    this._selectTab(tab !== undefined ? (tab instanceof SliderSuperTab ? tab.container : tab) : (this.canHideFirst ? -1 : 0), animate);\n    return true;\n  };\n\n  protected pushNavigationItem(tab: SliderSuperTab) {\n    const navigationItem: NavigationItem = {\n      type: this.navigationType,\n      onPop: (canAnimate) => {\n        if(tab.isConfirmationNeededOnClose) {\n          const result = tab.isConfirmationNeededOnClose();\n          if(result) {\n            Promise.resolve(result).then(() => {\n              appNavigationController.removeItem(navigationItem);\n              this.onTabsCountChange?.();\n\n              this.closeTab(undefined, undefined, true);\n            }, () => {});\n\n            return false;\n          }\n        }\n\n        this.closeTab(undefined, canAnimate, true);\n        this.onTabsCountChange?.();\n        return true;\n      }\n    };\n\n    // if(!this.canHideFirst || this.historyTabIds.length) {\n    appNavigationController.pushItem(navigationItem);\n    this.onTabsCountChange?.();\n    // }\n  }\n\n  public async selectTab(id: number | SliderSuperTab) {\n    /* if(id instanceof SliderSuperTab) {\n      id = id.id;\n    } */\n\n    if(this.historyTabIds[this.historyTabIds.length - 1] === id) {\n      return false;\n    }\n\n    const tab: SliderSuperTab = id instanceof SliderSuperTab ? id : this.tabs.get(id);\n    this.onOpenTab && await this.onOpenTab();\n\n    if(tab) {\n      // @ts-ignore\n      tab.onOpen?.();\n\n      // @ts-ignore\n      if(tab.onOpenAfterTimeout) {\n        setTimeout(() => {\n          // @ts-ignore\n          tab.onOpenAfterTimeout();\n        }, TRANSITION_TIME);\n      }\n    }\n\n    this.pushNavigationItem(tab);\n\n    this.historyTabIds.push(id);\n    this._selectTab(id instanceof SliderSuperTab ? id.container : id);\n    return true;\n  }\n\n  public removeTabFromHistory(id: number | SliderSuperTab) {\n    indexOfAndSplice(this.historyTabIds, id);\n    this.onCloseTab(id, undefined);\n  }\n\n  public closeAllTabs() {\n    const hasTabs = this.hasTabsInNavigation();\n    for(let i = this.historyTabIds.length - 1; i >= 0; --i) {\n      const tabId = this.historyTabIds[i];\n      const tab = tabId instanceof SliderSuperTab ? tabId : this.tabs.get(tabId);\n      tab.close();\n    }\n    return hasTabs;\n  }\n\n  // Close the open tabs from the top of the stack down, the same way the back\n  // arrow does — each tab that needs confirmation (isConfirmationNeededOnClose)\n  // gets to show its popup. If the user declines (the confirmation rejects),\n  // stop and return false; the declined tab and everything beneath it stay open.\n  // Unlike closeAllTabs, which force-closes every tab and ignores confirmation.\n  public async closeAllTabsNaturally(): Promise<boolean> {\n    while(this.historyTabIds.length) {\n      const tabId = this.historyTabIds[this.historyTabIds.length - 1];\n      const tab = tabId instanceof SliderSuperTab ? tabId : this.tabs.get(tabId);\n\n      const confirmation = tab?.isConfirmationNeededOnClose?.();\n      if(confirmation) {\n        const confirmed = await Promise.resolve(confirmation).then(() => true, () => false);\n        if(!confirmed) {\n          return false;\n        }\n\n        // The stack may have shifted while the popup was open; re-evaluate.\n        if(this.historyTabIds[this.historyTabIds.length - 1] !== tabId) {\n          continue;\n        }\n      }\n\n      this.closeTab(tabId, undefined, false);\n    }\n\n    return true;\n  }\n\n  public sliceTabsUntilTab(tabConstructor: SliderSuperTabConstructable, preserveTab: SliderSuperTab) {\n    for(let i = this.historyTabIds.length - 1; i >= 0; --i) {\n      const tab = this.historyTabIds[i];\n      if(tab === preserveTab) continue;\n      else if(tab instanceof tabConstructor) {\n        break;\n      }\n\n      this.removeTabFromHistory(tab);\n      // appNavigationController.removeByType(this.navigationType, true);\n    }\n  }\n\n  public getTab<T extends SliderSuperTab>(tabConstructor: SliderSuperTabConstructable<T>) {\n    return this.historyTabIds.find((t) => t instanceof tabConstructor) as T;\n  }\n\n  public getHistory() {\n    return this.historyTabIds;\n  }\n\n  public isTabExists(tabConstructor: SliderSuperTabConstructable) {\n    return !!this.getTab(tabConstructor);\n  }\n\n  protected onCloseTab(id: number | SliderSuperTab, animate: boolean, isNavigation?: boolean) {\n    if(!isNavigation) {\n      appNavigationController.removeByType(this.navigationType, true);\n      this.onTabsCountChange?.();\n    }\n\n    const tab: SliderSuperTab = id instanceof SliderSuperTab ? id : this.tabs.get(id);\n    if(tab) {\n      try {\n        // @ts-ignore\n        tab.onClose?.();\n      } catch(err) {\n        console.error('tab onClose error', tab);\n      }\n\n      // @ts-ignore\n      if(tab.onCloseAfterTimeout) {\n        setTimeout(() => {\n          // @ts-ignore\n          tab.onCloseAfterTimeout();\n        }, TRANSITION_TIME + 30);\n      }\n    }\n  }\n\n  public addTab(tab: SliderSuperTab) {\n    if(!tab.container.parentElement) {\n      this.tabsContainer.append(tab.container);\n\n      if(tab.closeBtn) {\n        tab.closeBtn.addEventListener('click', this.onCloseBtnClick);\n      }\n    }\n  }\n\n  public deleteTab(tab: SliderSuperTab) {\n    this.tabs.delete(tab);\n  }\n\n  public createTab<T extends SliderSuperTab>(\n    ctor: SliderSuperTabConstructable<T>,\n    destroyable = true,\n    doNotAppend?: boolean\n  ) {\n    if(\n      (ctor as any).noSame &&\n      this.historyTabIds[this.historyTabIds.length - 1] instanceof ctor\n    ) {\n      return this.historyTabIds[this.historyTabIds.length - 1] as T;\n    }\n\n    const tab = new ctor(doNotAppend ? undefined : this, destroyable);\n    tab.managers = this.managers;\n    return tab;\n  }\n\n  public hasTabsInNavigation() {\n    return !!appNavigationController.findItemByType(this.navigationType);\n  }\n}\n","import TransitionSlider from '@components/transition';\nimport {ScrollableX} from '@components/scrollable';\nimport {fastRaf} from '@helpers/schedulers';\nimport fastSmoothScroll, {FocusDirection} from '@helpers/fastSmoothScroll';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport whichChild from '@helpers/dom/whichChild';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport liteMode from '@helpers/liteMode';\nimport {ScrollableContextValue} from '@components/scrollable2';\n\ntype OnChangeArgs = {\n  element: HTMLElement;\n  active: boolean;\n};\n\ntype Args = {\n  tabs: HTMLElement;\n  content: HTMLElement,\n  onClick?: (id: number, tabContent: HTMLDivElement, animate: boolean) => void | boolean | Promise<void | boolean>;\n  onTransitionEnd?: () => void;\n  transitionTime?: number;\n  scrollableX?: ScrollableX | ScrollableContextValue;\n  listenerSetter?: ListenerSetter;\n  onChange?: (args: OnChangeArgs) => void;\n};\n\nexport type SelectTargetArgs = {\n  target: HTMLElement;\n  id: number;\n  animate?: boolean;\n  tabs: HTMLElement;\n  content?: HTMLElement;\n  onClick?: Args['onClick'];\n  scrollableX?: Args['scrollableX'];\n  transitionTime?: number;\n  prevId?: number;\n  selectTab?: (id: number, animate: boolean) => void;\n  onChange?: (args: OnChangeArgs) => void;\n};\n\nexport async function selectTarget({\n  target,\n  id,\n  animate = true,\n  tabs,\n  content,\n  onClick,\n  scrollableX,\n  transitionTime = 200,\n  prevId = -1,\n  selectTab,\n  onChange\n}: SelectTargetArgs) {\n  if(onClick) {\n    const tabContent = content?.children[id] as HTMLDivElement;\n    const result1 = onClick(id, tabContent, animate);\n    const canChange = result1 instanceof Promise ? await result1 : result1;\n    if(canChange === false) {\n      return;\n    }\n  }\n\n  if(scrollableX) {\n    const containerEl = scrollableX.container;\n    // Skip the scroll round-trip when there's no actual scrolling to do:\n    //   - row has no horizontal overflow (every tab is already visible)\n    //   - selecting the first tab while already at scrollLeft 0 (you can't\n    //     scroll past the start to \"center\" it, so fastSmoothScroll\n    //     clamps path to 0 and no-ops anyway)\n    // Common at the moment the search panel opens — `selectTab(0)` runs\n    // against a row whose scroll position is the default 0.\n    const noOverflow = containerEl.scrollWidth <= containerEl.clientWidth;\n    const isFirstAndAtStart = id === 0 && containerEl.scrollLeft === 0;\n    if(!noOverflow && !isFirstAndAtStart) {\n      fastSmoothScroll({\n        container: containerEl,\n        element: target.parentElement.children[id] as HTMLElement,\n        position: 'center',\n        forceDirection: animate ? undefined : FocusDirection.Static,\n        forceDuration: transitionTime,\n        axis: 'x'\n      });\n    }\n  }\n\n  if(!liteMode.isAvailable('animations')) {\n    animate = false;\n  }\n\n  if(target.classList.contains('active') || id === prevId) {\n    return false;\n  }\n\n  const mutateCallback = animate ? fastRaf : (cb: () => void) => cb();\n\n  const prev = tabs.querySelector(tabs.firstElementChild.tagName.toLowerCase() + '.active') as HTMLElement;\n  if(prev) {\n    mutateCallback(() => {\n      prev.classList.remove('active');\n      onChange?.({element: prev, active: false});\n    });\n  }\n\n  // a great stripe from Jolly Cobra\n  if(prevId !== -1 && animate) {\n    const selector = '.menu-horizontal-div-item-background';\n    mutateCallback(() => {\n      const indicator = target.querySelector(selector)! as HTMLElement;\n      const currentIndicator = target.parentElement.children[prevId].querySelector(selector)! as HTMLElement;\n\n      currentIndicator.classList.remove('animate');\n      indicator.classList.remove('animate');\n\n      const shiftLeft = currentIndicator.parentElement.offsetLeft - indicator.parentElement.offsetLeft;\n      const clientWidth = indicator.clientWidth;\n      const scaleFactor = currentIndicator.clientWidth / clientWidth;\n      indicator.style.transform = `translate3d(${shiftLeft}px, 0, 0)`;\n      indicator.style.width = `${clientWidth * scaleFactor}px`;\n\n      fastRaf(() => {\n        indicator.classList.add('animate');\n        indicator.style.transform = 'none';\n        indicator.style.width = '';\n      });\n    });\n  }\n\n  mutateCallback(() => {\n    target.classList.add('active');\n    onChange?.({element: target, active: true});\n  });\n\n  selectTab?.(id, animate);\n}\n\nexport function horizontalMenuObjArgs({tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange}: Args) {\n  return horizontalMenu(tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange);\n}\n\nexport function horizontalMenu(\n  tabs: Args['tabs'],\n  content: Args['content'],\n  onClick?: Args['onClick'],\n  onTransitionEnd?: Args['onTransitionEnd'],\n  transitionTime: Args['transitionTime'] = 200,\n  scrollableX?: Args['scrollableX'],\n  listenerSetter?: Args['listenerSetter'],\n  onChange?: Args['onChange']\n) {\n  const _selectTab = TransitionSlider({\n    content,\n    type: tabs || content.dataset.animation === 'tabs' ? 'tabs' : 'navigation',\n    transitionTime,\n    onTransitionEnd,\n    listenerSetter\n  });\n\n  if(!tabs) {\n    return _selectTab;\n  }\n\n  const _selectTarget = (target: HTMLElement, id: number, animate = true) => {\n    return selectTarget({\n      target,\n      id,\n      animate,\n      tabs,\n      content,\n      onClick,\n      scrollableX,\n      transitionTime,\n      prevId: _selectTab.prevId(),\n      selectTab: _selectTab,\n      onChange\n    });\n  };\n\n  const proxy = new Proxy(_selectTab, {\n    apply: (target, that, args) => {\n      const animate = args[1] !== undefined ? args[1] : true;\n\n      let id: number, el: HTMLElement;\n      if(args[0] instanceof HTMLElement) {\n        id = whichChild(args[0]);\n        el = args[0];\n      } else {\n        id = +args[0];\n        el = (tabs.querySelector(`[data-tab=\"${id}\"]`) || tabs.children[id]) as HTMLElement;\n      }\n\n      // The tabs row can be rendered reactively (folder tabs only exist once the\n      // folders store hydrates), while callers select a tab as soon as the row\n      // element itself is mounted — so `id` may have no element yet. Selecting a\n      // tab that isn't in the DOM throws on `target.classList`; skip instead, the\n      // caller re-selects once the tabs are in.\n      if(!el) return;\n\n      _selectTarget(el, id, animate);\n    }\n  });\n\n  attachClickEvent(tabs, (e) => {\n    let target = e.target as HTMLElement;\n    target = findUpAsChild(target, tabs);\n    if(!target) return false;\n\n    let id: number;\n    if(target.dataset.tab) {\n      id = +target.dataset.tab;\n      if(id === -1) {\n        return false;\n      }\n    } else {\n      id = whichChild(target);\n    }\n\n    _selectTarget(target, id);\n  }, {listenerSetter});\n\n  return proxy;\n}\n","import whichChild from '@helpers/dom/whichChild';\n\nexport default function positionElementByIndex(element: HTMLElement, container: HTMLElement, pos: number, prevPos?: number) {\n  if(prevPos === undefined) {\n    prevPos = element.parentElement === container ? whichChild(element) : -1;\n  }\n\n  if(prevPos === pos) {\n    return false;\n  } else if(prevPos !== -1 && prevPos < pos) { // was higher\n    pos += 1;\n  }\n\n  if(!pos) {\n    container.prepend(element);\n  } else if(container.childElementCount > pos) {\n    container.insertBefore(element, container.children[pos]);\n  } else {\n    container.append(element);\n  }\n\n  return true;\n}\n","import makeError from '@helpers/makeError';\n\nconst error = makeError('MIDDLEWARE');\nexport default function middlewarePromise(middleware: () => boolean, throwWhat: any = error) {\n  return <T>(promise: T): T => {\n    if(!(promise instanceof Promise)) {\n      if(promise instanceof Error) {\n        throw promise;\n      } else {\n        return promise;\n      }\n    }\n\n    return (promise as any as Promise<any>).then((result) => {\n      if(!middleware()) {\n        throw throwWhat;\n      }\n\n      return result;\n    }) as any;\n  };\n}\n","import {logger, LogTypes} from '@lib/logger';\nimport insertInDescendSortedArray from '@helpers/array/insertInDescendSortedArray';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport safeAssign from '@helpers/object/safeAssign';\nimport pause from '@helpers/schedulers/pause';\n\nexport type SortedElementBase<T = any> = {\n  id: T,\n  index: number\n};\n\nlet id = 0;\n\nexport class BatchProcessor<Item extends any = any> {\n  protected queue: MaybePromise<Item>[];\n  protected promise: Promise<void>;\n\n  protected middlewareHelper: MiddlewareHelper;\n  protected log: ReturnType<typeof logger>;\n\n  protected process: (batch: Item[], m: ReturnType<typeof middlewarePromise>, log: BatchProcessor['log']) => Promise<any>;\n  protected possibleError: any;\n\n  constructor(options: {\n    log?: BatchProcessor['log'],\n    // middleware: MiddlewareHelper,\n    process: BatchProcessor<Item>['process'],\n    possibleError?: BatchProcessor['possibleError']\n  }) {\n    safeAssign(this, options);\n\n    this.queue = [];\n    this.middlewareHelper ??= getMiddleware();\n\n    const prefix = 'BATCH-PROCESSOR-' + ++id;\n    const logTypes = LogTypes.Log | LogTypes.Warn | LogTypes.Error;\n    if(this.log) {\n      this.log = this.log.bindPrefix(prefix, logTypes);\n    } else {\n      this.log = logger(prefix, logTypes);\n    }\n  }\n\n  public get queuePromise() {\n    return this.promise;\n  }\n\n  public clear() {\n    this.log('clear');\n    this.queue.length = 0;\n    this.promise = undefined;\n    this.middlewareHelper.clean();\n  }\n\n  public addToQueue(item: BatchProcessor<Item>['queue'][0]) {\n    this.queue.push(item);\n    return this.setQueue();\n  }\n\n  protected setQueue() {\n    if(!this.queue.length) {\n      return Promise.resolve();\n    }\n\n    if(this.promise) {\n      return this.promise;\n    }\n\n    const middleware = this.middlewareHelper.get();\n    const log = this.log.bindPrefix('queue');\n    const m = middlewarePromise(middleware, this.possibleError);\n\n    const processQueue = async(): Promise<void> => {\n      log('start', this.queue.length);\n\n      const queue = this.queue.splice(0, this.queue.length);\n\n      const perf = performance.now();\n      const promises = queue.map((promise) => {\n        if(promise instanceof Promise) {\n          promise.then((details) => {\n            log('render item time', performance.now() - perf, details);\n          });\n        }\n\n        return promise;\n      });\n\n      const renderedQueue = await m(Promise.all(promises));\n      await m(this.process(renderedQueue, m, log));\n\n      log('queue rendered');\n\n      if(this.queue.length) {\n        log('have new items to render');\n        return processQueue();\n      } else {\n        log('end');\n      }\n    };\n\n    log('setting pause');\n    const promise = this.promise = m(pause(0))\n    .then(\n      () => processQueue().catch((err: ApiError) => {\n        if(err !== this.possibleError) {\n          log.error('process queue error', err);\n        }\n\n        throw err;\n      }),\n      (err) => {\n        log('pause has been cleared');\n        throw err;\n      }\n    )\n    .finally(() => {\n      if(this.promise === promise) {\n        this.promise = undefined;\n      }\n    });\n\n    return promise;\n  }\n}\n\nexport default class SortedList<SortedElement extends SortedElementBase, SortedElementId = SortedElement['id']> {\n  protected elements: Map<SortedElementId, SortedElement>;\n  protected sorted: Array<SortedElement>;\n\n  protected getIndex: (element: SortedElement) => Promise<number> | number;\n  protected onDelete: (element: SortedElement) => void;\n  protected onUpdate: (element: SortedElement) => void;\n  protected onSort: (element: SortedElement, idx: number) => void;\n  protected onElementCreate: (base: SortedElementBase) => Promise<SortedElement> | SortedElement;\n\n  protected updateElementWith = (callback: () => void) => callback();\n  protected updateListWith = (callback: (canUpdate: boolean | undefined) => void) => callback(true);\n\n  protected middlewareHelper: MiddlewareHelper;\n\n  protected batchProcessor: BatchProcessor<SortedElement>;\n\n  protected log: ReturnType<typeof logger>;\n\n  constructor(options: {\n    getIndex: SortedList<SortedElement>['getIndex'],\n    onDelete?: SortedList<SortedElement>['onDelete'],\n    onUpdate?: SortedList<SortedElement>['onUpdate'],\n    onSort?: SortedList<SortedElement>['onSort'],\n    onElementCreate: SortedList<SortedElement>['onElementCreate'],\n\n    updateElementWith?: SortedList<SortedElement>['updateElementWith'],\n    updateListWith?: SortedList<SortedElement>['updateListWith'],\n\n    log?: SortedList<SortedElement>['log'],\n\n    middleware?: Middleware\n  }) {\n    safeAssign(this, options);\n\n    this.elements = new Map();\n    this.sorted = [];\n    this.middlewareHelper = options.middleware?.create() || getMiddleware();\n\n    this.batchProcessor = new BatchProcessor<SortedElement>({\n      log: this.log,\n      process: async(batch, m, log) => {\n        // const elements = await Promise.all(batch.map((element) => this.onElementCreate(element)));\n        const elements = batch;\n        const promises = elements.map((element) => this.update(element.id, element));\n        await m(Promise.all(promises));\n      }\n    });\n  }\n\n  public clear() {\n    this.batchProcessor.clear();\n    this.middlewareHelper.clean();\n    this.elements.clear();\n    this.sorted.length = 0;\n  }\n\n  protected _updateList() {\n    this.elements.forEach((element) => {\n      this.update(element.id);\n    });\n\n    if(this.onSort) {\n      this.sorted.forEach((element, idx) => {\n        this.onSort(element, idx);\n      });\n    }\n  }\n\n  public updateList(callback?: (updated: boolean) => void) {\n    const middleware = this.middlewareHelper.get();\n    this.updateListWith((canUpdate) => {\n      if(!middleware() || (canUpdate !== undefined && !canUpdate)) {\n        callback?.(false);\n        return;\n      }\n\n      this._updateList();\n\n      callback?.(true);\n    });\n  }\n\n  public has(id: SortedElementId) {\n    return this.elements.has(id);\n  }\n\n  public get(id: SortedElementId) {\n    return this.elements.get(id);\n  }\n\n  public getAll() {\n    return this.elements;\n  }\n\n  public async add(id: SortedElementId) {\n    const element = this.get(id);\n    if(element) {\n      return;\n      // return element;\n    }\n\n    const base: SortedElementBase = {\n      id,\n      index: 0\n    };\n\n    this.elements.set(id, base as SortedElement);\n    let result = this.onElementCreate(base);\n    if(result instanceof Promise) {\n      let processed = false;\n      result = Promise.race([\n        result.then((result) => {\n          processed = true;\n          return result;\n        }),\n        pause(1000).then(() => {\n          if(!processed) {\n            console.error('loadPromises are still pending?', base);\n            return base as any;\n          }\n        })\n      ]);\n    }\n    return this.batchProcessor.addToQueue(result);\n\n    // return element;\n  }\n\n  public delete(id: SortedElementId, noScheduler?: boolean) {\n    const element = this.elements.get(id);\n    if(!element) {\n      return false;\n    }\n\n    this.elements.delete(id);\n\n    const idx = this.sorted.indexOf(element);\n    if(idx !== -1) {\n      this.sorted.splice(idx, 1);\n    }\n\n    if(this.onDelete) {\n      if(noScheduler) {\n        this.onDelete(element);\n      } else {\n        const middleware = this.middlewareHelper.get();\n        this.updateElementWith(() => {\n          if(!middleware()) {\n            return;\n          }\n\n          this.onDelete(element);\n        });\n      }\n    }\n\n    return true;\n  }\n\n  public async update(id: SortedElementId, element = this.get(id)) {\n    if(!element) {\n      return;\n    }\n\n    element.index = await this.getIndex(element);\n    if(this.get(id) !== element) {\n      return;\n    }\n\n    this.onUpdate?.(element);\n\n    const idx = insertInDescendSortedArray(this.sorted, element, 'index');\n    this.onSort(element, idx);\n  }\n}\n","import {formatFullSentTimeRaw} from '@helpers/date';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {User} from '@layer';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {REPLIES_PEER_ID, SERVICE_PEER_ID} from '@appManagers/constants';\n\nexport default function getUserStatusString(user: User.user): HTMLElement {\n  if(!user) {\n    return document.createElement('span');\n  }\n\n  let key: LangPackKey;\n  let args: any[];\n\n  switch(user.id) {\n    case REPLIES_PEER_ID.toUserId():\n      key = 'Peer.RepliesNotifications';\n      break;\n    case SERVICE_PEER_ID.toUserId():\n      key = 'Peer.ServiceNotifications';\n      break;\n    default: {\n      if(user.pFlags.bot) {\n        if(user.bot_active_users === undefined) {\n          key = 'Bot';\n          break;\n        }\n\n        key = 'BotUsers';\n        args = [numberThousandSplitter(user.bot_active_users)];\n        break;\n      }\n\n      if(user.pFlags.support) {\n        key = 'SupportStatus';\n        break;\n      }\n\n      switch(user.status?._) {\n        case 'userStatusRecently': {\n          key = 'Lately';\n          break;\n        }\n\n        case 'userStatusLastWeek': {\n          key = 'WithinAWeek';\n          break;\n        }\n\n        case 'userStatusLastMonth': {\n          key = 'WithinAMonth';\n          break;\n        }\n\n        case 'userStatusOffline': {\n          const date = user.status.was_online;\n          const today = new Date();\n          const now = today.getTime() / 1000 | 0;\n\n          const diff = now - date;\n          if(diff < 60) {\n            key = 'Peer.Status.justNow';\n          } else if(diff < 3600) {\n            key = 'Peer.Status.minAgo';\n            const c = diff / 60 | 0;\n            args = [c];\n          } else if(diff < 86400 && today.getDate() === new Date(date * 1000).getDate()) {\n            key = 'LastSeen.HoursAgo';\n            const c = diff / 3600 | 0;\n            args = [c];\n          } else {\n            key = 'Peer.Status.LastSeenAt';\n            const {dateEl, timeEl} = formatFullSentTimeRaw(date);\n            args = [dateEl, timeEl];\n          }\n\n          break;\n        }\n\n        case 'userStatusOnline': {\n          key = 'Online';\n          break;\n        }\n\n        default: {\n          key = 'ALongTimeAgo';\n          break;\n        }\n      }\n\n      break;\n    }\n  }\n\n  return i18n(key, args);\n}\n","import callbackify from '@helpers/callbackify';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {Chat, ChatFull} from '@layer';\nimport getParticipantsCount from '@appManagers/utils/chats/getParticipantsCount';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\n\nfunction _getChatMembersString(chat: Chat, chatFull: ChatFull) {\n  let count: number;\n  if(chatFull) {\n    count = getParticipantsCount(chatFull);\n  } else {\n    count = (chat as Chat.chat).participants_count || (chat as any).participants?.participants.length;\n  }\n\n  const isBroadcast = (chat as Chat.channel).pFlags.broadcast;\n  count = count || 1;\n\n  const key: LangPackKey = isBroadcast ? 'Peer.Status.Subscribers' : 'Peer.Status.Member';\n  return i18n(key, [numberThousandSplitter(count)]);\n}\n\nexport default function getChatMembersString(\n  chatId: ChatId,\n  managers = rootScope.managers,\n  chat?: Chat,\n  onlySync?: boolean,\n  chatFull?: ChatFull\n) {\n  chat ??= apiManagerProxy.getChat(chatId);\n  if(chat._ === 'chatForbidden') {\n    return i18n('YouWereKicked');\n  }\n\n  if(onlySync) {\n    return _getChatMembersString(chat, undefined);\n  }\n\n  const result = chatFull || managers.appProfileManager.getCachedFullChat(chatId);\n  return callbackify(result, (chatFull) => _getChatMembersString(chat, chatFull));\n}\n","import {ChannelParticipant, ChatParticipant} from '@layer';\n\nexport default function getParticipantRank(participant: ChannelParticipant | ChatParticipant) {\n  return (participant as ChannelParticipant.channelParticipantAdmin).rank ||\n    (participant._ === 'channelParticipantAdmin' || participant._ === 'chatParticipantAdmin' ? 2 :\n      (participant._ === 'chatParticipantCreator' || participant._ === 'channelParticipantCreator' ? 1 : undefined));\n}\n","import getParticipantRank from '@appManagers/utils/chats/getParticipantRank';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\n\nexport default function wrapParticipantRank(rank: Parameters<typeof getParticipantRank>[0] | ReturnType<typeof getParticipantRank> | 0) {\n  if(typeof(rank) === 'object') {\n    rank = getParticipantRank(rank);\n  }\n\n  return typeof(rank) === 'number' ?\n    i18n(!rank ? 'Chat.ChannelBadge' : (rank === 1 ? 'Chat.OwnerBadge' : 'ChatAdmin')) :\n    wrapEmojiText(rank);\n}\n","import type LazyLoadQueue from '@components/lazyLoadQueue';\nimport appDialogsManager, {AppDialogsManager, DialogDom, DialogElement, DialogElementSize} from '@lib/appDialogsManager';\nimport {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {fastRaf} from '@helpers/schedulers';\nimport SortedList, {SortedElementBase} from '@helpers/sortedList';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport getUserStatusString from '@components/wrappers/getUserStatusString';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport wrapParticipantRank from '@components/wrappers/participantRank';\nimport getParticipantRank from '@appManagers/utils/chats/getParticipantRank';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\n\ninterface SortedUser extends SortedElementBase<PeerId> {\n  dom: DialogDom,\n  dialogElement: DialogElement\n}\n\nexport default class SortedUserList extends SortedList<SortedUser> {\n  protected static SORT_INTERVAL = 30e3;\n  public list: HTMLUListElement;\n  public ranks: Map<PeerId, ReturnType<typeof getParticipantRank>> = new Map();\n\n  protected lazyLoadQueue: LazyLoadQueue;\n  protected avatarSize: DialogElementSize = 'abitbigger';\n  protected rippleEnabled = true;\n  protected autonomous = true;\n  protected createChatListOptions: Parameters<AppDialogsManager['createChatList']>[0];\n  protected onListLengthChange: () => void;\n  protected managers: AppManagers;\n\n  constructor(options: Partial<{\n    lazyLoadQueue: SortedUserList['lazyLoadQueue'],\n    avatarSize: SortedUserList['avatarSize'],\n    rippleEnabled: SortedUserList['rippleEnabled'],\n    createChatListOptions: SortedUserList['createChatListOptions'],\n    autonomous: SortedUserList['autonomous'],\n    onListLengthChange: SortedUserList['onListLengthChange'],\n    getIndex: SortedUserList['getIndex'],\n    onUpdate: SortedUserList['onUpdate']\n  }> & {\n    managers: SortedUserList['managers'],\n    middleware: Middleware\n  }) {\n    super({\n      getIndex: options.getIndex || ((element) => element.id.isAnyChat() ? 0 : this.managers.appUsersManager.getUserStatusForSort(element.id)),\n      onDelete: (element) => {\n        element.dialogElement.remove();\n        this.onListLengthChange?.();\n      },\n      onUpdate: options.onUpdate || (async(element) => {\n        if(element.id.isAnyChat()) {\n          const status = await getChatMembersString(element.id.toChatId(), this.managers);\n          replaceContent(element.dom.lastMessageSpan, status);\n        } else {\n          const status = getUserStatusString(await this.managers.appUsersManager.getUser(element.id));\n          replaceContent(element.dom.lastMessageSpan, status);\n\n          const rank = this.ranks.get(element.id);\n          element.dialogElement.titleRight.replaceChildren(...(rank ? [wrapParticipantRank(rank)] : []));\n        }\n      }),\n      onSort: (element, idx) => {\n        const willChangeLength = element.dom.listEl.parentElement !== this.list;\n        positionElementByIndex(element.dom.listEl, this.list, idx);\n\n        if(willChangeLength && this.onListLengthChange) {\n          this.onListLengthChange();\n        }\n      },\n      onElementCreate: (base) => {\n        const dialogElement = appDialogsManager.addDialogNew({\n          peerId: base.id,\n          container: false,\n          avatarSize: this.avatarSize,\n          autonomous: this.autonomous,\n          meAsSaved: false,\n          rippleEnabled: this.rippleEnabled,\n          wrapOptions: {\n            lazyLoadQueue: this.lazyLoadQueue,\n            middleware: this.middlewareHelper.get()\n          },\n          withStories: true\n        });\n\n        const rank = this.ranks.get(base.id);\n        dialogElement.titleRight.replaceChildren(...[rank ? wrapParticipantRank(rank) : undefined].filter(Boolean));\n\n        (base as SortedUser).dom = dialogElement.dom;\n        (base as SortedUser).dialogElement = dialogElement;\n        return base as SortedUser;\n      },\n      updateElementWith: fastRaf,\n      updateListWith: async(callback) => {\n        if(!Array.from(this.elements.values()).some((element) => element.id.isUser())) {\n          return callback(false);\n        }\n\n        if(!isInDOM(this.list)) {\n          return callback(false);\n        }\n\n        await getHeavyAnimationPromise();\n\n        if(!isInDOM(this.list)) {\n          return callback(false);\n        }\n\n        callback(true);\n      },\n      middleware: options.middleware\n    });\n\n    safeAssign(this, options);\n\n    this.list = appDialogsManager.createChatList(this.createChatListOptions);\n\n    let timeout: number;\n    const doTimeout = () => {\n      timeout = window.setTimeout(() => {\n        this.updateList((good) => {\n          if(good) {\n            doTimeout();\n          }\n        });\n      }, SortedUserList.SORT_INTERVAL);\n    };\n\n    doTimeout();\n  }\n}\n","import ListLoader from '@helpers/listLoader';\n\nexport default class EmptyListLoader<T> extends ListLoader<T, any> {\n  constructor() {\n    super({\n      loadMore: () => {\n        return Promise.resolve({count: 0, items: []});\n      }\n    });\n\n    this.loadedAllDown = true;\n    this.loadedAllUp = true;\n  }\n}\n","import {InputDocument} from '@layer';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport getDocumentInput from '@appManagers/utils/docs/getDocumentInput';\nimport ListenerSetter from './listenerSetter';\n\n/**\n * Tracks how much of a music track the user actually listened to and reports it via\n * `messages.reportMusicListen`. The listened duration is the total of the UNIQUE track positions\n * the user covered (re-listening the same segment isn't counted twice, and seek jumps are excluded)\n * — matching the Android client.\n *\n * Driven by {@link AppMediaPlaybackController}: call {@link onPlay} on each `play` event (passing the\n * controller's playing details) and {@link finish} on `stop`. A session begins when a music track\n * starts and is finalized — and reported, when long enough — on track switch, stop, or a pause\n * longer than {@link MUSIC_LISTEN_PAUSE_LIMIT}.\n */\n\n// A pause longer than this ends the current listen; resuming afterwards counts as a new one.\nconst MUSIC_LISTEN_PAUSE_LIMIT = 60e3;\n// The server ignores reports shorter than this many seconds, so we don't bother sending them.\nconst MUSIC_LISTEN_MIN_DURATION = 3;\n\ntype MusicListenSession = {\n  inputDoc: InputDocument.inputDocument,\n  media: HTMLMediaElement,\n  listeners: ListenerSetter,\n  ranges: {from: number, to: number}[],\n  rangeStart: number,\n  lastPosition: number\n};\n\ntype PlayDetails = {\n  doc?: MyDocument,\n  media?: HTMLMediaElement\n};\n\nexport default class MusicListenTracker {\n  // `ranges` holds the merged covered intervals (seconds), `rangeStart` is the open interval's start\n  // (-1 when none), `lastPosition` is the last observed playback position (used to close ranges\n  // across seeks/stop).\n  private session: MusicListenSession;\n  private pauseTimeout: number;\n\n  constructor(private onReport: (inputDoc: InputDocument.inputDocument, listenedDuration: number) => void) {}\n\n  public onPlay(details: PlayDetails) {\n    // Only music is tracked — switching away from music to a voice/round/video finalizes any session.\n    if(details?.doc?.type !== 'audio') {\n      this.finish();\n      return;\n    }\n\n    const inputDoc = getDocumentInput(details.doc) as InputDocument.inputDocument;\n    const session = this.session;\n    if(session && session.inputDoc.id === inputDoc.id && session.media === details.media) {\n      // Same track still playing (e.g. resume) — the media-level listeners handle it.\n      return;\n    }\n\n    // A different track started — finalize the previous listen and begin a fresh one.\n    this.finish();\n    this.startSession(inputDoc, details.media);\n  }\n\n  // Settles the current listen and reports it (when long enough), then clears it. Called when a\n  // track ends, the user switches tracks, the player is closed, or a pause lasts longer than\n  // MUSIC_LISTEN_PAUSE_LIMIT.\n  public finish() {\n    this.clearPauseTimeout();\n\n    const session = this.session;\n    if(!session) {\n      return;\n    }\n\n    this.session = undefined;\n    session.listeners.removeAll();\n\n    // Close a still-open interval at the last known position. `media.currentTime` is unreliable\n    // here — `stop()` resets it to 0 before dispatching the event — so use `lastPosition`.\n    this.closeRange(session, session.lastPosition);\n\n    let total = 0;\n    for(const range of session.ranges) {\n      total += range.to - range.from;\n    }\n\n    const listenedDuration = Math.floor(total);\n    if(listenedDuration < MUSIC_LISTEN_MIN_DURATION) {\n      return;\n    }\n\n    this.onReport(session.inputDoc, listenedDuration);\n  }\n\n  private startSession(inputDoc: InputDocument.inputDocument, media: HTMLMediaElement) {\n    const listeners = new ListenerSetter();\n    const session: MusicListenSession = this.session = {\n      inputDoc,\n      media,\n      listeners,\n      ranges: [],\n      rangeStart: -1,\n      lastPosition: media.currentTime\n    };\n\n    // The media is already playing when the controller's `play` event reaches us, so open the\n    // first interval right away; later play/pause/seek transitions adjust it.\n    if(!media.paused) {\n      this.openRange(media.currentTime);\n    }\n\n    listeners.add(media)('timeupdate', () => {\n      session.lastPosition = media.currentTime;\n    });\n\n    listeners.add(media)('play', () => {\n      this.clearPauseTimeout();\n      this.openRange(media.currentTime);\n    });\n\n    listeners.add(media)('pause', () => {\n      // `stop()` resets currentTime to 0 before this async event fires, so fall back to the last\n      // tracked position; on a genuine user pause currentTime is accurate and slightly ahead.\n      this.closeRange(session, Math.max(session.lastPosition, media.currentTime));\n      this.clearPauseTimeout();\n      this.pauseTimeout = window.setTimeout(() => {\n        this.pauseTimeout = undefined;\n        this.finish();\n      }, MUSIC_LISTEN_PAUSE_LIMIT);\n    });\n\n    listeners.add(media)('seeking', () => {\n      // Close the interval at the pre-seek position, then reopen at the new one if still playing.\n      this.closeRange(session, session.lastPosition);\n      this.clearPauseTimeout();\n      if(!media.paused) {\n        this.openRange(media.currentTime);\n      }\n      session.lastPosition = media.currentTime;\n    });\n  }\n\n  // Opens a covered interval at the given position (no-op if one is already open).\n  private openRange(position: number) {\n    const session = this.session;\n    if(session && session.rangeStart < 0) {\n      session.rangeStart = position;\n    }\n  }\n\n  // Closes the open interval at the given position and merges it into the covered ranges.\n  private closeRange(session: MusicListenSession, position: number) {\n    if(session.rangeStart < 0) {\n      return;\n    }\n\n    const from = session.rangeStart;\n    session.rangeStart = -1;\n    if(position <= from) {\n      return;\n    }\n\n    // Insert sorted by `from`, then merge any overlapping/touching neighbours.\n    const ranges = session.ranges;\n    let idx = 0;\n    while(idx < ranges.length && ranges[idx].from <= from) idx++;\n    ranges.splice(idx, 0, {from, to: position});\n    for(let i = Math.max(0, idx - 1); i < ranges.length - 1;) {\n      const cur = ranges[i], next = ranges[i + 1];\n      if(cur.to >= next.from) {\n        cur.to = Math.max(cur.to, next.to);\n        ranges.splice(i + 1, 1);\n      } else {\n        i++;\n      }\n    }\n  }\n\n  private clearPauseTimeout() {\n    if(this.pauseTimeout !== undefined) {\n      clearTimeout(this.pauseTimeout);\n      this.pauseTimeout = undefined;\n    }\n  }\n}\n","import {MessageExtendedMedia, Photo, PhotoSize} from '@layer';\n\nexport default function generatePhotoForExtendedMediaPreview(media: MessageExtendedMedia.messageExtendedMediaPreview): Photo.photo {\n  let thumb = media.thumb as PhotoSize.photoStrippedSize;\n  if(thumb) {\n    thumb.w = media.w;\n    thumb.h = media.h;\n  } else {\n    thumb = {\n      _: 'photoStrippedSize',\n      bytes: new Uint8Array([1, 24, 30, 197, 162, 138, 40, 0, 162, 138, 40, 0, 162, 138, 40, 0, 162, 138, 40, 3]),\n      type: 'i',\n      w: 1,\n      h: 1\n    };\n  }\n\n  return {\n    _: 'photo',\n    access_hash: '',\n    pFlags: {},\n    date: 0,\n    dc_id: 0,\n    file_reference: [],\n    id: 0,\n    sizes: [thumb]\n  };\n}\n","import toArray from '@helpers/array/toArray';\nimport {Document, Game, Message, MessageAction, MessageExtendedMedia, MessageMedia, Photo, StoryItem, WebPage} from '@layer';\nimport generatePhotoForExtendedMediaPreview from '@appManagers/utils/photos/generatePhotoForExtendedMediaPreview';\n\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner: true, index?: number): Photo.photo | Document.document;\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner?: false, index?: number): Photo.photo | Document.document | Game.game | WebPage.webPage;\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner = false, index?: number): Photo.photo | Document.document | Game.game | WebPage.webPage {\n  if(!message) return;\n\n  let media: any;\n  if((message as Message.messageService).action) {\n    media = ((message as Message.messageService).action as MessageAction.messageActionChannelEditPhoto).photo;\n  } else if((message as Message.message).media) {\n    let messageMedia = (message as Message.message).media;\n    const extendedMedia = (messageMedia as MessageMedia.messageMediaInvoice | MessageMedia.messageMediaPaidMedia).extended_media;\n    if((messageMedia as MessageMedia.messageMediaWebPage).webpage) {\n      messageMedia = (messageMedia as MessageMedia.messageMediaWebPage).webpage as any as MessageMedia;\n    } else if(extendedMedia) {\n      const media = toArray(extendedMedia)[index ?? 0];\n      messageMedia = (media as MessageExtendedMedia.messageExtendedMedia).media;\n      if(!messageMedia) {\n        return generatePhotoForExtendedMediaPreview(media as MessageExtendedMedia.messageExtendedMediaPreview);\n      }\n    }\n\n    media = /* (messageMedia as MessageMedia.messageMediaDocument).alt_document || */\n      (messageMedia as MessageMedia.messageMediaDocument).document ||\n      (messageMedia as MessageMedia.messageMediaPhoto).photo ||\n      (onlyInner ? undefined : (messageMedia as MessageMedia.messageMediaGame).game || messageMedia);\n  }\n\n  return media as any;\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type {SearchSuperContext} from '@components/appSearchSuper';\nimport rootScope from '@lib/rootScope';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {IS_APPLE, IS_SAFARI} from '@environment/userAgent';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {getAppWindow} from '@helpers/appWindow';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\nimport {Document, DocumentAttribute, Message, PhotoSize} from '@layer';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport I18n from '@lib/langPack';\nimport SearchListLoader from '@helpers/searchListLoader';\nimport copy from '@helpers/object/copy';\nimport deepEqual from '@helpers/object/deepEqual';\nimport clamp from '@helpers/number/clamp';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport MusicListenTracker from '@helpers/musicListenTracker';\nimport {AppManagers} from '@lib/managers';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport animationIntersector from '@components/animationIntersector';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport ListLoader, {ListLoaderOptions} from '../helpers/listLoader';\n\n// TODO: Safari: проверить стрим, включить его и сразу попробовать включить видео или другую песню\n// TODO: Safari: попробовать замаскировать подгрузку последнего чанка\n// TODO: Safari: пофиксить момент, когда заканчивается песня и пытаешься включить её заново - прогресс сразу в конце\n\nexport type MediaItem = {mid: number, peerId: PeerId};\n\nconst SHOULD_USE_SAFARI_FIX = (() => {\n  try {\n    return IS_SAFARI && +navigator.userAgent.match(/ Version\\/(\\d+)/)[1] < 14;\n  } catch(err) {\n    return false;\n  }\n})();\n\nconst SEEK_OFFSET = 10;\n\nexport type MediaSearchContext = SearchSuperContext & Partial<{\n  isScheduled: boolean,\n  skipSensitive: boolean,\n  useSearch: boolean\n}>;\n\ntype MediaDetails = {\n  peerId: PeerId,\n  mid: number,\n  /**\n   * Effective key under which the media is stored in `this.media` / `this.scheduled`.\n   * Equals `mid + (slot ?? 0)` — see `AddMediaArgs.slot`.\n   */\n  storageKey: number,\n  docId: DocId,\n  doc: MyDocument,\n  message: Message.message,\n  clean?: boolean,\n  isScheduled?: boolean,\n  isSingle?: boolean\n};\n\nexport type MediaListLoader = ListLoader<MediaItem, Message.message> & {\n  goRound: (length: number, dispatchJump?: boolean) => void\n  getPrevious: (withOtherSide?: boolean) => MediaItem[]\n  getNext: (withOtherSide?: boolean) => MediaItem[]\n  cleanup: () => void\n  setCurrent: (item: MediaItem) => void\n  repositionTo?: (mid: number, peerId: PeerId) => boolean\n};\nexport type MediaListLoaderOptions = Omit<ListLoaderOptions<MediaItem, Message.message>, 'loadMore'> & {\n  onEmptied?: () => void,\n};\nexport type MediaListLoaderFactory = (options: MediaListLoaderOptions) => MediaListLoader;\n\nexport type PlaybackMediaType = 'voice' | 'video' | 'audio';\n\nexport type AddMediaArgs = {\n  message: Message.message;\n  autoload: boolean;\n  clean?: boolean;\n  /**\n   * Optional pre-extracted document. When provided, it overrides the default\n   * extraction from `message.media`. Useful when the document lives in a\n   * sibling field of the message (e.g. poll `solution_media`).\n   */\n  doc?: MyDocument;\n  /**\n   * Optional disambiguator added to `mid` when forming the storage key, so\n   * multiple media elements can coexist under the same `(peerId, mid)` pair.\n   * Used for sibling-media-on-the-same-message scenarios (e.g. poll\n   * description vs. explanation documents).\n   *\n   * Use small fractional values (e.g. `0.1`, `0.2`); `0` / undefined means\n   * the standard storage key equal to `mid`.\n   *\n   * Note: slotted entries are intentionally not reachable via `getMedia` /\n   * `playItem` (the playlist flow), since they're not part of a playlist.\n   */\n  slot?: number;\n};\n\nexport class AppMediaPlaybackController extends EventListenerBase<{\n  play: (details: ReturnType<AppMediaPlaybackController['getPlayingDetails']>) => void,\n  singleMedia: (media: HTMLMediaElement) => void,\n  pause: () => void,\n  playbackParams: (params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) => void,\n  stop: () => void,\n  toggleVideoAutoplaySound: (value: boolean) => void\n}> {\n  private container: HTMLElement;\n  private media: Map<PeerId, Map<number, HTMLMediaElement>> = new Map();\n  private scheduled: AppMediaPlaybackController['media'] = new Map();\n  private mediaDetails: Map<HTMLMediaElement, MediaDetails> = new Map();\n  private playingMedia: HTMLMediaElement;\n  private playingMediaType: PlaybackMediaType;\n\n  private waitingMediaForLoad: Map<PeerId, Map<number, CancellablePromise<void>>> = new Map();\n  private waitingScheduledMediaForLoad: AppMediaPlaybackController['waitingMediaForLoad'] = new Map();\n  private waitingDocumentsForLoad: {[docId: string]: Set<HTMLMediaElement>} = {};\n\n  public willBePlayedMedia: HTMLMediaElement;\n  private searchContext: MediaSearchContext;\n\n  private listLoader: MediaListLoader;\n  private listLoaderFactory: MediaListLoaderFactory;\n\n  public volume: number;\n  /**\n   * Voice/round-only boost added on top of the shared `volume` (WebAudio gain, see\n   * {@link applyVolumeToMedia}). The 0–100% slider range maps to the shared `volume`\n   * (common with video/music); the 100–200% range maps to this boost, so amplifying a\n   * voice never bleeds into video/music. Both `volume` and `boost` are clamped to [0, 1];\n   * effective voice volume = `volume + boost` ∈ [0, 2].\n   */\n  public boost: number;\n  public muted: boolean;\n  public playbackRate: number;\n  public loop: boolean;\n  public round: boolean;\n  private _volume: number;\n  private _boost: number;\n  private _muted: boolean;\n  private _playbackRate: number;\n  private _loop: boolean;\n  private _round: boolean;\n  private lockedSwitchers: boolean;\n  private playbackRates: Record<PlaybackMediaType, number> = {\n    voice: 1,\n    video: 1,\n    audio: 1\n  };\n\n  private pip: HTMLVideoElement;\n  private managers: AppManagers;\n  private skipMediaPlayEvent: boolean;\n\n  private gainAudioContext: AudioContext;\n  private mediaGainMap: WeakMap<HTMLMediaElement, {source: MediaElementAudioSourceNode, gain: GainNode, limiter: DynamicsCompressorNode}> = new WeakMap();\n\n  // Music-listen reporting (messages.reportMusicListen) — owned by MusicListenTracker; the\n  // controller just forwards the play/stop events below.\n  private musicListenTracker: MusicListenTracker;\n\n  construct(managers: AppManagers) {\n    this.managers = managers;\n    this.musicListenTracker = new MusicListenTracker((inputDoc, listenedDuration) => {\n      // Fire-and-forget analytics — swallow errors (e.g. a stale file_reference) so they don't surface.\n      this.managers.appMessagesManager.reportMusicListen(inputDoc, listenedDuration).catch(() => {});\n    });\n    this.container = document.createElement('div');\n    // this.container.style.cssText = 'position: absolute; top: -10000px; left: -10000px;';\n    this.container.style.cssText = 'display: none;';\n    document.body.append(this.container);\n\n    if(navigator.mediaSession) {\n      const actions: {[action in MediaSessionAction]?: MediaSessionActionHandler} = {\n        play: this.browserPlay,\n        pause: this.browserPause,\n        stop: this.browserStop,\n        seekbackward: this.browserSeekBackward,\n        seekforward: this.browserSeekForward,\n        seekto: this.browserSeekTo,\n        previoustrack: this.browserPrevious,\n        nexttrack: this.browserNext\n      };\n\n      for(const action in actions) {\n        try {\n          navigator.mediaSession.setActionHandler(action as MediaSessionAction, actions[action as MediaSessionAction]);\n        } catch(err) {\n          console.warn('MediaSession action is not supported:', action);\n        }\n      }\n    }\n\n    rootScope.addEventListener('document_downloaded', (docId) => {\n      const set = this.waitingDocumentsForLoad[docId];\n      if(set) {\n        for(const media of set) {\n          this.onMediaDocumentLoad(media);\n        }\n      }\n    });\n\n    rootScope.addEventListener('media_play', () => {\n      if(this.skipMediaPlayEvent) {\n        this.skipMediaPlayEvent = false;\n        return;\n      }\n\n      if(!this.pause() && this.pip) {\n        this.pip.pause();\n      }\n    });\n\n    const properties: {[key: PropertyKey]: PropertyDescriptor} = {};\n    const keys = [\n      'volume' as const,\n      'boost' as const,\n      'muted' as const,\n      'playbackRate' as const,\n      'loop' as const,\n      'round' as const\n    ];\n    keys.forEach((key) => {\n      const _key = ('_' + key) as `_${typeof key}`;\n      properties[key] = {\n        get: () => this[_key],\n        set: (value: number | boolean) => {\n          // Shared master volume and the voice-only boost both stay in [0, 1]; their sum\n          // (effective voice volume) tops out at 200%, the boost never touches video/music.\n          if(key === 'volume' || key === 'boost') {\n            value = clamp(value as number, 0, 1);\n          }\n\n          if(this[_key] === value) {\n            return;\n          }\n\n          // @ts-ignore\n          this[_key] = value;\n          if(this.playingMedia && (key !== 'loop' || this.playingMediaType === 'audio') && key !== 'round') {\n            if(key === 'volume' || key === 'muted' || key === 'boost') {\n              this.applyVolumeToMedia(this.playingMedia, this.getVolumeForType(this.playingMediaType), this.muted, this.playingMediaType);\n            } else {\n              // @ts-ignore\n              this.playingMedia[key] = value;\n            }\n          }\n\n          if(key === 'playbackRate' && this.playingMediaType !== undefined) {\n            this.playbackRates[this.playingMediaType] = value as number;\n          }\n\n          this.dispatchPlaybackParams();\n        }\n      };\n    });\n    Object.defineProperties(this, properties);\n\n    this.addEventListener('play', (details) => {\n      if(details.doc.type === 'round') {\n        animationIntersector.toggleMediaPause(false);\n      }\n\n      this.musicListenTracker.onPlay(details);\n    });\n\n    this.addEventListener('pause', () => {\n      animationIntersector.toggleMediaPause(true);\n    });\n\n    this.addEventListener('stop', () => {\n      this.musicListenTracker.finish();\n    });\n  }\n\n  private dispatchPlaybackParams() {\n    this.dispatchEvent('playbackParams', this.getPlaybackParams());\n  }\n\n  private getOrCreateMediaGain(media: HTMLMediaElement) {\n    let entry = this.mediaGainMap.get(media);\n    if(entry) return entry;\n\n    try {\n      const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext;\n      if(!AC) return undefined;\n      if(!this.gainAudioContext) this.gainAudioContext = new AC();\n      const ctx = this.gainAudioContext;\n\n      const source = ctx.createMediaElementSource(media);\n      const gain = ctx.createGain();\n      // Brick-wall limiter after the gain — keeps amplified peaks below 0 dB so quadratic\n      // boosts raise perceived loudness instead of just clipping to the same ceiling.\n      const limiter = ctx.createDynamicsCompressor();\n      limiter.threshold.value = -1;\n      limiter.knee.value = 0;\n      limiter.ratio.value = 20;\n      limiter.attack.value = 0;\n      limiter.release.value = 0.05;\n      source.connect(gain);\n      gain.connect(limiter);\n      limiter.connect(ctx.destination);\n      entry = {source, gain, limiter};\n      this.mediaGainMap.set(media, entry);\n\n      if(ctx.state === 'suspended') ctx.resume().catch(() => {});\n\n      return entry;\n    } catch(e) {\n      return undefined;\n    }\n  }\n\n  /**\n   * Volume to feed playback for a given media type: voice/round add their boost on top of\n   * the shared master, everything else uses the shared master alone.\n   */\n  private getVolumeForType(mediaType: PlaybackMediaType) {\n    return mediaType === 'voice' ? clamp(this._volume + this._boost, 0, 2) : this._volume;\n  }\n\n  private applyVolumeToMedia(\n    media: HTMLMediaElement,\n    volume: number,\n    muted: boolean,\n    mediaType: PlaybackMediaType\n  ) {\n    if(mediaType === 'voice') {\n      const entry = this.getOrCreateMediaGain(media);\n      if(entry) {\n        if(this.gainAudioContext?.state === 'suspended') this.gainAudioContext.resume().catch(() => {});\n        // Below 100% linear (natural volume control), above 100% quadratic so the slider\n        // delivers perceptual loudness, not just a 2× peak multiplier (e.g. 200% → 4× ≈ +12 dB).\n        const amp = volume <= 1 ? volume : volume * volume;\n        const target = muted ? 0 : amp;\n        try {\n          entry.gain.gain.setTargetAtTime(target, this.gainAudioContext.currentTime, 0.01);\n        } catch(e) {\n          entry.gain.gain.value = target;\n        }\n        media.volume = 1;\n        media.muted = muted;\n        return;\n      }\n    }\n\n    media.volume = Math.min(volume, 1);\n    media.muted = muted;\n  }\n\n  public getPlaybackParams() {\n    const {volume, boost, muted, playbackRate, playbackRates, loop, round} = this;\n    return {\n      volume,\n      boost,\n      muted,\n      playbackRate,\n      playbackRates,\n      loop,\n      round\n    };\n  }\n\n  public setPlaybackParams(params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) {\n    this.playbackRates = params.playbackRates;\n    this._volume = clamp(params.volume ?? 1, 0, 1);\n    // Older states (and the buggy >100% writes this fixes) stored the voice boost inside\n    // `volume`, so when `boost` is absent recover it from the part of `volume` above 100%.\n    // `volume` itself stays clamped to the [0, 1] media range.\n    this._boost = clamp(params.boost ?? Math.max((params.volume ?? 1) - 1, 0), 0, 1);\n    this._muted = params.muted;\n    this._playbackRate = params.playbackRate;\n    this._loop = params.loop;\n    this._round = params.round;\n  }\n\n  public seekBackward = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, Math.max(0, media.currentTime - (details.seekOffset || SEEK_OFFSET)));\n    }\n  };\n\n  public seekForward = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, Math.min(media.duration, media.currentTime + (details.seekOffset || SEEK_OFFSET)));\n    }\n  };\n\n  public seekTo = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, details.seekTime);\n    }\n  };\n\n  public addMedia(args: AddMediaArgs): HTMLMediaElement {\n    const {message, autoload, clean, doc: docOverride, slot} = args;\n    const {peerId, mid} = message;\n    const storageKey = mid + (slot ?? 0);\n\n    const isScheduled = !!message.pFlags.is_scheduled;\n    const s = isScheduled ? this.scheduled : this.media;\n    let storage = s.get(message.peerId);\n    if(!storage) {\n      s.set(message.peerId, storage = new Map());\n    }\n\n    let media = storage.get(storageKey);\n    if(media) {\n      return media;\n    }\n\n    const doc = docOverride ?? (getMediaFromMessage(message, true) as Document.document);\n    storage.set(storageKey, media = document.createElement(doc.type === 'round' || doc.type === 'video' ? 'video' : 'audio'));\n    // const source = document.createElement('source');\n    // source.type = doc.type === 'voice' && !opusDecodeController.isPlaySupported() ? 'audio/wav' : doc.mime_type;\n\n    if(doc.type === 'round') {\n      media.setAttribute('playsinline', 'true');\n      // media.muted = true;\n    }\n\n    const details: MediaDetails = {\n      peerId,\n      mid,\n      storageKey,\n      docId: doc.id,\n      doc,\n      message,\n      clean,\n      isScheduled: message.pFlags.is_scheduled\n    };\n\n    this.mediaDetails.set(media, details);\n\n    // media.autoplay = true;\n    media.volume = 1;\n    // media.append(source);\n\n    this.container.append(media);\n\n    media.addEventListener('play', this.onPlay);\n    media.addEventListener('pause', this.onPause);\n    media.addEventListener('ended', this.onEnded);\n\n    if(doc.type !== 'audio' && message?.pFlags.media_unread && message.fromId !== rootScope.myId) {\n      media.addEventListener('timeupdate', () => {\n        this.managers.appMessagesManager.readMessages(peerId, [mid]);\n      }, {once: true});\n    }\n\n    /* const onError = (e: Event) => {\n      //console.log('appMediaPlaybackController: video onError', e);\n\n      if(this.nextMid === mid) {\n        this.loadSiblingsMedia(peerId, doc.type as MediaType, mid).then(() => {\n          if(this.nextMid && storage[this.nextMid]) {\n            storage[this.nextMid].play();\n          }\n        });\n      }\n    };\n\n    media.addEventListener('error', onError); */\n\n    const deferred = deferredPromise<void>();\n    if(autoload) {\n      deferred.resolve();\n    } else {\n      const w = message.pFlags.is_scheduled ? this.waitingScheduledMediaForLoad : this.waitingMediaForLoad;\n      let waitingStorage = w.get(peerId);\n      if(!waitingStorage) {\n        w.set(peerId, waitingStorage = new Map());\n      }\n\n      waitingStorage.set(storageKey, deferred);\n    }\n\n    deferred.then(() => {\n      // media.autoplay = true;\n      // console.log('will set media url:', media, doc, doc.type, doc.url);\n\n      if(doc.supportsStreaming || (apiManagerProxy.getCacheContext(doc)).url) {\n        this.onMediaDocumentLoad(media);\n      } else {\n        let set = this.waitingDocumentsForLoad[doc.id];\n        if(!set) {\n          set = this.waitingDocumentsForLoad[doc.id] = new Set();\n        }\n\n        set.add(media);\n        appDownloadManager.downloadMediaURL({media: doc});\n      }\n    }/* , onError */);\n\n    return media;\n  }\n\n  public getMedia(peerId: PeerId, mid: number, isScheduled?: boolean) {\n    const s = (isScheduled ? this.scheduled : this.media).get(peerId);\n    return s?.get(mid);\n  }\n\n  private onMediaDocumentLoad = async(media: HTMLMediaElement) => {\n    const details = this.mediaDetails.get(media);\n    const doc = await this.managers.appDocsManager.getDoc(details.docId);\n    if(doc.type === 'audio' && doc.supportsStreaming && SHOULD_USE_SAFARI_FIX) {\n      this.handleSafariStreamable(media);\n    }\n\n    // setTimeout(() => {\n    const cacheContext = apiManagerProxy.getCacheContext(doc);\n    media.src = cacheContext.url;\n\n    if(this.playingMedia === media) {\n      media.playbackRate = this.playbackRate;\n\n      if(doc.type === 'audio') {\n        media.loop = this.loop;\n      }\n    }\n    // }, doc.supportsStreaming ? 500e3 : 0);\n\n    const set = this.waitingDocumentsForLoad[doc.id];\n    if(set) {\n      set.delete(media);\n\n      if(!set.size) {\n        delete this.waitingDocumentsForLoad[doc.id];\n      }\n    }\n  };\n\n  // safari подгрузит последний чанк и песня включится,\n  // при этом этот чанк нельзя руками отдать из SW, потому что браузер тогда теряется\n  private handleSafariStreamable(media: HTMLMediaElement) {\n    media.addEventListener('play', () => {\n      /* if(media.readyState === 4) { // https://developer.mozilla.org/ru/docs/Web/API/XMLHttpRequest/readyState\n        return;\n      } */\n\n      // media.volume = 0;\n      const currentTime = media.currentTime;\n      // this.setSafariBuffering(media, true);\n\n      media.addEventListener('progress', () => {\n        setCurrentTime(media, media.duration - 1);\n\n        media.addEventListener('progress', () => {\n          setCurrentTime(media, currentTime);\n          // media.volume = 1;\n          // this.setSafariBuffering(media, false);\n\n          if(!media.paused) {\n            media.play()/* .catch(() => {}) */;\n          }\n        }, {once: true});\n      }, {once: true});\n    }/* , {once: true} */);\n  }\n\n  public resolveWaitingForLoadMedia(peerId: PeerId, mid: number, isScheduled?: boolean, slot?: number) {\n    const w = isScheduled ? this.waitingScheduledMediaForLoad : this.waitingMediaForLoad;\n    const storage = w.get(peerId);\n    if(!storage) {\n      return;\n    }\n\n    const storageKey = mid + (slot ?? 0);\n    const promise = storage.get(storageKey);\n    if(promise) {\n      promise.resolve();\n      storage.delete(storageKey);\n\n      if(!storage.size) {\n        w.delete(peerId);\n      }\n    }\n  }\n\n  /**\n   * Only for audio\n   */\n  public isSafariBuffering(media: HTMLMediaElement) {\n    // @ts-ignore\n    return !!media.safariBuffering;\n  }\n\n  private setSafariBuffering(media: HTMLMediaElement, value: boolean) {\n    // @ts-ignore\n    media.safariBuffering = value;\n  }\n\n  private async setNewMediadata(message: Message.message, playingMedia = this.playingMedia) {\n    if(getAppWindow().document.pictureInPictureElement) {\n      return;\n    }\n\n    await onMediaLoad(playingMedia, undefined, false); // have to wait for load, otherwise on macOS won't set\n\n    const doc = getMediaFromMessage(message, true) as MyDocument;\n    if(!doc) return; // live\n\n    const artwork: MediaImage[] = [];\n\n    const isVoice = doc.type === 'voice' || doc.type === 'round';\n    let title = '', artist = '';\n\n    if(doc.thumbs?.length) {\n      const size = doc.thumbs[doc.thumbs.length - 1];\n      if(!(size as PhotoSize.photoStrippedSize).bytes) {\n        const cacheContext = apiManagerProxy.getCacheContext(doc, size.type);\n\n        if(cacheContext.url) {\n          artwork.push({\n            src: cacheContext.url,\n            sizes: `${(size as PhotoSize.photoSize).w}x${(size as PhotoSize.photoSize).h}`,\n            type: 'image/jpeg'\n          });\n        } else {\n          const download = appDownloadManager.downloadMediaURL({media: doc, thumb: size});\n          download.then(() => {\n            if(this.playingMedia !== playingMedia || !cacheContext.url) {\n              return;\n            }\n\n            this.setNewMediadata(message);\n          });\n        }\n      }\n    } else if(isVoice) {\n      const peerId = message.fromId || message.peerId;\n      const peerPhoto = await this.managers.appPeersManager.getPeerPhoto(peerId);\n      if(peerPhoto) {\n        // const result = this.managers.appAvatarsManager.loadAvatar(peerId, peerPhoto, 'photo_small');\n        // if(result.cached) {\n        //   const url = await result.loadPromise;\n        //   artwork.push({\n        //     src: url,\n        //     sizes: '160x160',\n        //     type: 'image/jpeg'\n        //   });\n        // } else {\n        //   result.loadPromise.then((url) => {\n        //     if(this.playingMedia !== playingMedia || !url) {\n        //       return;\n        //     }\n\n        //     this.setNewMediadata(message);\n        //   });\n        // }\n      }\n\n      title = await getPeerTitle({peerId, plainText: true, onlyFirstName: false});\n      artist = I18n.format(doc.type === 'voice' ? 'AttachAudio' : 'AttachRound', true);\n    }\n\n    if(!isVoice) {\n      const attribute = doc.attributes.find((attribute) => attribute._ === 'documentAttributeAudio') as DocumentAttribute.documentAttributeAudio;\n      title = attribute?.title ?? doc.file_name;\n      artist = attribute?.performer;\n    }\n\n    if(!artwork.length) {\n      if(IS_APPLE) {\n        if(IS_TOUCH_SUPPORTED) {\n          artwork.push({\n            src: `assets/img/apple-touch-icon-precomposed.png`,\n            sizes: '180x180',\n            type: 'image/png'\n          });\n        } else {\n          artwork.push({\n            src: `assets/img/apple-touch-icon.png`,\n            sizes: '180x180',\n            type: 'image/png'\n          });\n        }\n      } else {\n        [72, 96, 144, 192, 256, 384, 512].forEach((size) => {\n          const sizes = `${size}x${size}`;\n          artwork.push({\n            src: `assets/img/android-chrome-${sizes}.png`,\n            sizes,\n            type: 'image/png'\n          });\n        });\n      }\n    }\n\n    const metadata = new MediaMetadata({\n      title,\n      artist,\n      artwork\n    });\n\n    navigator.mediaSession.metadata = metadata;\n  }\n\n  public setCurrentMediadata() {\n    const {playingMedia} = this;\n    if(!playingMedia) return;\n    const message = this.getMessageByMedia(playingMedia);\n    this.setNewMediadata(message, playingMedia);\n  }\n\n  private getMessageByMedia(media: HTMLMediaElement): Message.message {\n    const details = this.mediaDetails.get(media);\n    return details?.message;\n    // const {peerId, mid} = details;\n    // const message = details.isScheduled ?\n    //   this.managers.appMessagesManager.getScheduledMessageByPeer(peerId, mid) :\n    //   this.managers.appMessagesManager.getMessageByPeer(peerId, mid);\n    // return message;\n  }\n\n  public getPlayingDetails() {\n    const {playingMedia} = this;\n    if(!playingMedia) {\n      return;\n    }\n\n    const message = this.getMessageByMedia(playingMedia);\n    if(!message) {\n      return;\n    }\n\n    const details = this.mediaDetails.get(playingMedia);\n\n    return {\n      doc: details?.doc || getMediaFromMessage(message, true) as MyDocument,\n      message,\n      media: playingMedia,\n      isSavedMusic: Boolean(message.pFlags.fakeForSavedMusic),\n      /**\n       * True when the media was added with a non-zero `slot` (e.g. poll\n       * description / explanation audio). Such media is played in isolation:\n       * its list loader is empty, so next/previous navigation and looping\n       * are not meaningful.\n       */\n      isSlotted: !!details && details.storageKey !== details.mid,\n      playbackParams: this.getPlaybackParams()\n    };\n  }\n\n  private onPlay = (e?: Event) => {\n    const media = e.target as HTMLMediaElement;\n    const details = this.mediaDetails.get(media);\n    const {peerId, mid} = details;\n\n    // console.log('appMediaPlaybackController: video playing', this.currentPeerId, this.playingMedia, media);\n\n    const pip = this.pip;\n    if(pip) {\n      pip.pause();\n    }\n\n    const message = this.getMessageByMedia(media);\n\n    const previousMedia = this.playingMedia;\n    if(previousMedia !== media) {\n      this.stop();\n      this.setMedia(media, message);\n\n      const verify = (element: MediaItem) => element.mid === mid && element.peerId === peerId;\n      const listLoader = this.listLoader;\n      const current = listLoader.current;\n      if(!current || !verify(current)) {\n        let jumpLength: number;\n\n        for(const withOtherSide of [false, true]) {\n          const previous = listLoader.getPrevious(withOtherSide);\n\n          let idx = previous.findIndex(verify);\n          if(idx !== -1) {\n            jumpLength = -(previous.length - idx);\n          } else {\n            const next = listLoader.getNext(withOtherSide);\n            idx = next.findIndex(verify);\n            if(idx !== -1) {\n              jumpLength = idx + 1;\n            }\n          }\n\n          if(jumpLength !== undefined) {\n            break;\n          }\n        }\n\n        if(jumpLength) {\n          this.go(jumpLength, false);\n        } else if(!listLoader.repositionTo?.(mid, peerId)) {\n          this.setTargets({peerId, mid});\n        }\n      }\n    }\n\n    // audio_pause не успеет сработать без таймаута\n    setTimeout(() => {\n      if(this.playingMedia !== media) {\n        return;\n      }\n\n      this.dispatchEvent('play', this.getPlayingDetails());\n      this.pauseMediaInOtherTabs();\n    }, 0);\n  };\n\n  private onPause = (e?: Event) => {\n    /* const target = e.target as HTMLMediaElement;\n    if(!isInDOM(target)) {\n      this.container.append(target);\n      target.play();\n      return;\n    } */\n\n    // if(this.pip) {\n    //   this.pip.play();\n    // }\n\n    this.dispatchEvent('pause');\n  };\n\n  private onEnded = (e?: Event) => {\n    if(e && !e.isTrusted) {\n      return;\n    }\n\n    this.onPause(e);\n\n    // console.log('on media end');\n\n    const listLoader = this.listLoader;\n    if(\n      this.lockedSwitchers ||\n      (!this.round && listLoader.current && !listLoader.getNext(false).length) ||\n      !listLoader.getNext(true).length ||\n      !this.next()\n    ) {\n      this.stop();\n      this.dispatchEvent('stop');\n    }\n  };\n\n  public pauseMediaInOtherTabs() {\n    this.skipMediaPlayEvent = true;\n    rootScope.dispatchEvent('media_play');\n  }\n\n  // public get pip() {\n  //   return document.pictureInPictureElement as HTMLVideoElement;\n  // }\n\n  public toggle(play?: boolean, media = this.playingMedia) {\n    if(!media) {\n      return false;\n    }\n\n    if(play === undefined) {\n      play = media.paused;\n    }\n\n    if(media.paused !== play) {\n      return false;\n    }\n\n    if(play) {\n      media.play();\n    } else {\n      media.pause();\n    }\n\n    return true;\n  }\n\n  public getPlayingMedia() {\n    return this.playingMedia;\n  }\n\n  /**\n   * Slider value for the global-only selector (pinned audio plate) bound to whatever is\n   * playing: voice shows `volume + boost` (its 0–200% range), everything else the shared\n   * master `volume`.\n   */\n  public getGlobalSliderVolume() {\n    return this.getVolumeForType(this.playingMediaType);\n  }\n\n  /**\n   * Apply a global-only selector value. For voice the 0–100% part sets the shared master\n   * (common with video/music) and the 100–200% part sets the voice-only boost, so the\n   * boost stays out of `volume`. For everything else it just sets the shared master.\n   */\n  public setGlobalSliderVolume(value: number) {\n    if(this.playingMediaType === 'voice') {\n      this.boost = Math.max(value - 1, 0);\n      this.volume = Math.min(value, 1);\n    } else {\n      this.volume = value;\n    }\n  }\n\n  public play = () => {\n    return this.toggle(true);\n  };\n\n  public pause = () => {\n    return this.toggle(false);\n  };\n\n  public stop = (media = this.playingMedia, force?: boolean) => {\n    if(!media) {\n      return false;\n    }\n\n    if(!media.paused) {\n      media.pause();\n    }\n\n    setCurrentTime(media, 0);\n    simulateEvent(media, 'ended'); // ! important, will be used to hide controls for audio element\n\n    if(media === this.playingMedia) {\n      const details = this.mediaDetails.get(media);\n      if(details?.clean) {\n        media.src = '';\n        const peerId = details.peerId;\n        const s = details.isScheduled ? this.scheduled : this.media;\n        const storage = s.get(peerId);\n        if(storage) {\n          storage.delete(details.storageKey);\n\n          if(!storage.size) {\n            s.delete(peerId);\n          }\n        }\n\n        media.remove();\n\n        this.mediaDetails.delete(media);\n      }\n\n      this.playingMedia = undefined;\n      this.playingMediaType = undefined;\n    }\n\n    if(force) {\n      this.dispatchEvent('stop');\n    }\n\n    return true;\n  };\n\n  public playItem = (item: MediaItem) => {\n    const {peerId, mid} = item;\n    const isScheduled = this.searchContext.isScheduled;\n    const media = this.getMedia(peerId, mid, isScheduled);\n\n    /* if(isSafari) {\n      media.autoplay = true;\n    } */\n\n    media.play();\n\n    setTimeout(() => {\n      this.resolveWaitingForLoadMedia(peerId, mid, isScheduled);\n    }, 0);\n  };\n\n  public go = (length: number, dispatchJump?: boolean) => {\n    const listLoader = this.listLoader;\n    if(this.lockedSwitchers || !listLoader) {\n      return;\n    }\n\n    if(this.playingMediaType === 'audio') {\n      return listLoader.goRound(length, dispatchJump);\n    } else {\n      return listLoader.go(length, dispatchJump);\n    }\n  };\n\n  private bindBrowserCallback(cb: (video: HTMLVideoElement, details: MediaSessionActionDetails) => void) {\n    const handler: MediaSessionActionHandler = (details) => {\n      cb(this.pip, details);\n    };\n\n    return handler;\n  }\n\n  public browserPlay = this.bindBrowserCallback((video) => this.toggle(true, video));\n  public browserPause = this.bindBrowserCallback((video) => this.toggle(false, video));\n  public browserStop = this.bindBrowserCallback((video) => this.stop(video));\n  public browserSeekBackward = this.bindBrowserCallback((video, details) => this.seekBackward(details, video));\n  public browserSeekForward = this.bindBrowserCallback((video, details) => this.seekForward(details, video));\n  public browserSeekTo = this.bindBrowserCallback((video, details) => this.seekTo(details, video));\n  public browserNext = this.bindBrowserCallback((video) => video || this.next());\n  public browserPrevious = this.bindBrowserCallback((video) => video ? this.seekToStart(video) : this.previous());\n\n  public next = () => {\n    return this.go(1);\n  };\n\n  public previous = () => {\n    if(this.seekToStart(this.playingMedia)) {\n      return;\n    }\n\n    return this.go(-1);\n  };\n\n  public seekToStart(media: HTMLMediaElement) {\n    if(media?.currentTime > 5) {\n      setCurrentTime(media, 0);\n      this.toggle(true, media);\n      return true;\n    }\n\n    return false;\n  }\n\n  public willBePlayed(media: HTMLMediaElement) {\n    this.willBePlayedMedia = media;\n  }\n\n  public getListLoaderFactory() {\n    return this.listLoaderFactory;\n  }\n\n  public setSearchContext(context: MediaSearchContext) {\n    if(deepEqual(this.searchContext, context)) {\n      return false;\n    }\n\n    this.searchContext = copy(context); // {_: type === 'audio' ? 'inputMessagesFilterMusic' : 'inputMessagesFilterRoundVoice'}\n    return true;\n  }\n\n  public getSearchContext() {\n    return this.searchContext;\n  }\n\n  private static defaultLoaderFactory: MediaListLoaderFactory = (options: MediaListLoaderOptions) => new SearchListLoader(options);\n\n  public setTargets(\n    current: MediaItem,\n    prev?: MediaItem[],\n    next?: MediaItem[],\n    loaderFactory: MediaListLoaderFactory = AppMediaPlaybackController.defaultLoaderFactory\n  ) {\n    let listLoader = this.listLoader;\n    if(!listLoader || this.listLoaderFactory !== loaderFactory) {\n      listLoader?.cleanup();\n\n      listLoader = this.listLoader = loaderFactory({\n        loadCount: 10,\n        loadWhenLeft: 5,\n        processItem: (message: Message.message) => {\n          this.addMedia({message, autoload: false});\n          return {peerId: message.peerId, mid: message.mid};\n        },\n        onJump: (item, older) => {\n          this.playItem(item);\n        },\n        onEmptied: () => {\n          this.dispatchEvent('stop');\n          this.stop();\n        }\n      });\n      this.listLoaderFactory = loaderFactory;\n    } else {\n      listLoader.reset();\n    }\n\n\n    if(listLoader instanceof SearchListLoader) {\n      const reverse = this.searchContext.folderId !== undefined ? false : true;\n      listLoader.setSearchContext(this.searchContext);\n      if(prev) {\n        listLoader.setTargets(prev, next, reverse);\n      } else {\n        listLoader.reverse = reverse;\n      }\n    }\n\n    listLoader.setCurrent(current);\n\n    listLoader.load(true);\n    listLoader.load(false);\n  }\n\n  private getPlaybackMediaTypeFromMessage(message: Message.message) {\n    const doc = getMediaFromMessage(message, true) as MyDocument;\n    let mediaType: PlaybackMediaType = 'audio';\n    if(doc?.type) {\n      if(doc.type === 'voice' || doc.type === 'round') {\n        mediaType = 'voice';\n      } else if(doc.type === 'video') {\n        mediaType = 'video';\n      }\n    }\n\n    return mediaType;\n  }\n\n  public setMedia(media: HTMLMediaElement, message: Message.message, standalone?: boolean) {\n    const mediaType = this.getPlaybackMediaTypeFromMessage(message);\n\n    this._playbackRate = this.playbackRates[mediaType];\n\n    this.playingMedia = media;\n    this.playingMediaType = mediaType;\n    if(!standalone) {\n      this.applyVolumeToMedia(this.playingMedia, this.getVolumeForType(mediaType), this.muted, mediaType);\n      this.playingMedia.playbackRate = this.playbackRate;\n      if(mediaType === 'audio') {\n        this.playingMedia.loop = this.loop;\n      }\n    }\n\n    if('mediaSession' in navigator) {\n      this.setNewMediadata(message);\n    }\n  }\n\n  public setSingleMedia({\n    media,\n    message,\n    standalone\n  }: {\n    media?: HTMLMediaElement,\n    message?: Message.message,\n    standalone?: boolean\n  } = {}) {\n    const playingMedia = this.playingMedia;\n\n    const wasPlaying = this.pause();\n\n    let onPlay: () => void;\n    if(media) {\n      onPlay = () => {\n        const pip = this.pip;\n        if(pip) {\n          pip.pause();\n        }\n\n        this.pauseMediaInOtherTabs();\n      };\n\n      if(!media.paused) {\n        onPlay();\n      }\n\n      media.addEventListener('play', onPlay);\n    } else { // maybe it's voice recording\n      this.pauseMediaInOtherTabs();\n    }\n\n    this.willBePlayed(undefined);\n    if(media) this.setMedia(media, message, standalone);\n    else this.playingMedia = undefined;\n    this.toggleSwitchers(false);\n\n    this.dispatchEvent('singleMedia', media);\n\n    return (playPaused = wasPlaying) => {\n      this.toggleSwitchers(true);\n\n      if(playingMedia) {\n        if(this.mediaDetails.get(playingMedia)) {\n          this.setMedia(playingMedia, this.getMessageByMedia(playingMedia));\n        } else {\n          this.next() || this.previous();\n        }\n      }\n\n      // If it's still not cleaned\n      if(this.playingMedia === media) {\n        this.playingMedia = undefined;\n        this.playingMediaType = undefined;\n      }\n\n      if(media) {\n        media.removeEventListener('play', onPlay);\n      }\n\n      // I don't remember what it was for\n      // if(media && this.playingMedia === media) {\n      //   this.stop();\n      // }\n\n      if(playPaused) {\n        this.play();\n      }\n    };\n  }\n\n  public toggleSwitchers(enabled: boolean) {\n    this.lockedSwitchers = !enabled;\n  }\n\n  public setPictureInPicture(video: HTMLVideoElement) {\n    this.pip = video;\n\n    // let wasPlaying = this.pause();\n\n    const listenerSetter = new ListenerSetter();\n    listenerSetter.add(video)('leavepictureinpicture', () => {\n      if(this.pip !== video) {\n        return;\n      }\n\n      this.pip = undefined;\n      // if(wasPlaying) {\n      //   this.play();\n      // }\n\n      listenerSetter.removeAll();\n    }, {once: true});\n\n    listenerSetter.add(video)('play', (e) => {\n      if(this.playingMedia !== video) {\n        this.pause();\n      }\n\n      this.pauseMediaInOtherTabs();\n      // if(this.pause()) {\n      //   listenerSetter.add(video)('pause', () => {\n      //     this.play();\n      //   }, {once: true});\n      // }\n    });\n  }\n}\n\nconst appMediaPlaybackController = new AppMediaPlaybackController();\nMOUNT_CLASS_TO.appMediaPlaybackController = appMediaPlaybackController;\nexport default appMediaPlaybackController;\n","import contextMenuController from '@helpers/contextMenuController';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {AttachClickOptions, CLICK_EVENT_NAME, hasMouseMovedSinceDown} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '@helpers/array/filterAsync';\nimport {doubleRaf} from '@helpers/schedulers';\nimport callbackify from '@helpers/callbackify';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {MenuPositionPadding, positionMenuTrigger} from '@helpers/positionMenu';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {getFullScreenElement} from '@helpers/dom/fullScreen';\n\n// TODO: refactor for attachClickEvent, because if move finger after touchstart, it will start anyway\nexport function ButtonMenuToggleHandler({\n  el,\n  onOpen,\n  options,\n  onClose\n}: {\n  el: HTMLElement,\n  onOpen?: (e: Event) => any,\n  options?: AttachClickOptions,\n  onClose?: () => void\n}) {\n  const add = options?.listenerSetter ? options.listenerSetter.add(el) : el.addEventListener.bind(el);\n\n  add(CLICK_EVENT_NAME, (e: Event) => {\n    if(!el.classList.contains('btn-menu-toggle') || hasMouseMovedSinceDown(e)) return false;\n\n    cancelEvent(e);\n\n    if(el.classList.contains('menu-open')) {\n      if(e.target && (e.target as HTMLElement).classList.contains('btn-menu')) {\n        return;\n      }\n\n      contextMenuController.close();\n    } else {\n      const result = onOpen?.(e);\n      const open = (element?: HTMLElement) => {\n        const openedMenu = element ?? el.querySelector('.btn-menu') as HTMLDivElement;\n        if(!openedMenu) {\n          return;\n        }\n\n        contextMenuController.openBtnMenu(openedMenu, onClose, el);\n      };\n\n      callbackify(result, open);\n    }\n  });\n}\n\nexport function filterButtonMenuItems(buttons: ButtonMenuItemOptionsVerifiable[]) {\n  return filterAsync(buttons, (button) => button?.verify ? button.verify() ?? false : true);\n}\n\nexport type ButtonMenuDirection = 'bottom-left' | 'bottom-right' | 'bottom-center' | 'top-left' | 'top-right'\n\nexport default function ButtonMenuToggle({\n  buttonOptions,\n  listenerSetter: attachListenerSetter,\n  container,\n  direction,\n  buttons,\n  onOpenBefore,\n  onOpen,\n  onClose,\n  onCloseAfter,\n  noIcon,\n  icon = 'more',\n  appendTo,\n  positionPadding\n}: {\n  buttonOptions?: Parameters<typeof ButtonIcon>[1],\n  listenerSetter?: ListenerSetter,\n  container?: HTMLElement\n  appendTo?: HTMLElement,\n  direction: ButtonMenuDirection,\n  buttons: ButtonMenuItemOptionsVerifiable[],\n  onOpenBefore?: (e: Event) => any,\n  onOpen?: (e: Event, element: HTMLElement) => any,\n  onClose?: () => void,\n  onCloseAfter?: () => void,\n  noIcon?: boolean,\n  icon?: (string & {}) | Icon,\n  positionPadding?: MenuPositionPadding\n}) {\n  if(buttonOptions) {\n    buttonOptions.asDiv = true;\n  }\n\n  const button = container ?? ButtonIcon(noIcon ? undefined : icon, buttonOptions);\n  const autoPosition = !appendTo;\n  button.classList.add('btn-menu-toggle');\n\n  const listenerSetter = new ListenerSetter();\n\n  const clearCloseTimeout = () => {\n    clearTimeout(closeTimeout);\n    closeTimeout = undefined;\n  };\n\n  // * fix translation by deleting text elements on close\n  const canDeleteTextElementsOnClose = buttons.filter((button) => !button.textElement);\n  const previousButtons = buttons.slice();\n\n  let element: HTMLElement, closeTimeout: number, tempId = 0;\n  ButtonMenuToggleHandler({\n    el: button,\n    onOpen: async(e) => {\n      const _tempId = ++tempId;\n      await onOpenBefore?.(e);\n      if(_tempId !== tempId) return;\n      if(closeTimeout) {\n        clearCloseTimeout();\n        if(element?.isConnected) {\n          return element;\n        }\n      }\n\n      const filteredButtons = await filterButtonMenuItems(buttons);\n      if(_tempId !== tempId) return;\n      if(!filteredButtons.length) {\n        return;\n      }\n\n      const newButtons = filteredButtons.slice().filter((button) => !previousButtons.includes(button));\n      previousButtons.push(...newButtons);\n      canDeleteTextElementsOnClose.push(...newButtons.filter((button) => !button.textElement));\n\n      const _element = element = await ButtonMenu({\n        buttons: filteredButtons,\n        listenerSetter\n      });\n      if(_tempId !== tempId) return;\n      _element.classList.add(direction);\n      if(direction === 'bottom-center') {\n        _element.style.setProperty('--parent-half-width', ((container ?? button).clientWidth / 2) + 'px');\n      }\n\n      await onOpen?.(e, _element);\n      if(_tempId !== tempId) return;\n\n      // Resolve the mount lazily so a menu opened while the client is popped out lands in the active\n      // window's body (the Document PiP window), not the background tab. While an element is fullscreen\n      // the browser paints ONLY the fullscreen subtree (its top layer), so a menu mounted on document.body\n      // would be invisible — mount it inside the fullscreen element when the trigger lives there (e.g. the\n      // video player's playback-rate / quality / live menus).\n      const fullScreenElement = getFullScreenElement();\n      const mountTarget = appendTo ??\n        (fullScreenElement?.contains(button) ? fullScreenElement : getOverlayRoot());\n      mountTarget.append(_element);\n      if(autoPosition) {\n        positionMenuTrigger(button, _element, direction, positionPadding ?? {top: 8, bottom: 8});\n      }\n      await doubleRaf();\n      if(_tempId !== tempId) {\n        _element.remove();\n      }\n\n      return _element\n    },\n    options: {\n      listenerSetter: attachListenerSetter\n    },\n    onClose: () => {\n      ++tempId;\n      clearCloseTimeout();\n      onClose?.();\n\n      closeTimeout = window.setTimeout(() => {\n        onCloseAfter?.();\n        closeTimeout = undefined;\n        listenerSetter.removeAll();\n        buttons.forEach((button) => {\n          try {button.dispose?.();} catch{}\n          button.element = undefined;\n        });\n        canDeleteTextElementsOnClose.forEach((button) => delete button.textElement);\n        element.remove();\n      }, 300);\n    }\n  });\n\n  return button;\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\nexport default class ControlsHover extends EventListenerBase<{\n  toggleControls: (show: boolean) => void\n}> {\n  protected hideControlsTimeout: number;\n  protected controlsLocked: boolean;\n\n  protected canHideControls: () => boolean;\n  protected canShowControls: () => boolean;\n  protected element: HTMLElement;\n  protected listenerSetter: ListenerSetter;\n  protected showOnLeaveToClassName: string | string[];\n  protected ignoreClickClassName: string;\n\n  constructor() {\n    super(false);\n    this.hideControlsTimeout = 0;\n  }\n\n  public setup(options: {\n    element: HTMLElement,\n    listenerSetter: ListenerSetter,\n    canHideControls?: () => boolean,\n    canShowControls?: () => boolean,\n    showOnLeaveToClassName?: string | string[],\n    ignoreClickClassName?: string\n  }) {\n    safeAssign(this, options);\n\n    const {listenerSetter, element} = this;\n\n    if(IS_TOUCH_SUPPORTED) {\n      listenerSetter.add(element)('click', (e) => {\n        if(this.ignoreClickClassName && findUpClassName(e.target, this.ignoreClickClassName)) {\n          return;\n        }\n\n        this.toggleControls();\n      });\n\n      /* listenerSetter.add(player)('touchstart', () => {\n        showControls(false);\n      });\n\n      listenerSetter.add(player)('touchend', () => {\n        if(player.classList.contains('is-playing')) {\n          showControls();\n        }\n      }); */\n    } else {\n      listenerSetter.add(element)('mousemove', () => {\n        this.showControls();\n      });\n\n      listenerSetter.add(element)('mouseenter', () => {\n        this.showControls(false);\n      });\n\n      listenerSetter.add(element)('mouseleave', (e) => {\n        // Leaving onto floating chrome (caption / topbar) must not start the hide —\n        // those elements live outside the player, so hiding here would yank them from\n        // under the cursor and bounce mouseenter↔mouseleave forever.\n        const showOnLeaveClassNames = Array.isArray(this.showOnLeaveToClassName) ? this.showOnLeaveToClassName : [this.showOnLeaveToClassName];\n        if(e.relatedTarget && showOnLeaveClassNames.some((className) => className && findUpClassName(e.relatedTarget, className))) {\n          this.showControls(false);\n          return;\n        }\n\n        this.hideControls();\n      });\n    }\n  }\n\n  public hideControls = (setHideTimeout = false) => {\n    if(setHideTimeout) {\n      if(!this.hideControlsTimeout) {\n        this.hideControlsTimeout = window.setTimeout(this.hideControls, 3e3);\n      }\n\n      return;\n    }\n\n    clearTimeout(this.hideControlsTimeout);\n    this.hideControlsTimeout = 0;\n\n    const isShown = this.element.classList.contains('show-controls');\n    if(this.controlsLocked !== false) {\n      if((this.canHideControls ? !this.canHideControls() : false) || !isShown || this.controlsLocked) {\n        return;\n      }\n    } else if(!isShown) {\n      return;\n    }\n\n    this.dispatchEvent('toggleControls', false);\n    this.element.classList.remove('show-controls');\n  };\n\n  public showControls = (setHideTimeout = true) => {\n    if(!(this.canShowControls?.() ?? true)) return;\n\n    if(this.hideControlsTimeout) {\n      clearTimeout(this.hideControlsTimeout);\n      this.hideControlsTimeout = 0;\n    } else if(!this.element.classList.contains('show-controls') && this.controlsLocked !== false) {\n      this.dispatchEvent('toggleControls', true);\n      this.element.classList.add('show-controls');\n    }\n\n    if(!setHideTimeout || this.controlsLocked) {\n      return;\n    }\n\n    this.hideControlsTimeout = window.setTimeout(this.hideControls, 3e3);\n  };\n\n  public toggleControls = (show?: boolean) => {\n    const isShown = this.element.classList.contains('show-controls');\n\n    if(show === undefined) {\n      if(isShown) this.hideControls();\n      else this.showControls();\n    } else if(show === isShown) return;\n    else if(show === false) this.hideControls();\n    else this.showControls();\n  };\n\n  public lockControls(visible: boolean) {\n    if(this.controlsLocked === visible) {\n      return;\n    }\n\n    this.controlsLocked = visible;\n    this.element.classList.toggle('disable-hover', visible === false);\n    this.toggleControls(visible);\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// Document Picture-in-Picture lets an arbitrary DOM subtree (not just a <video>) live in an\n// always-on-top OS window — https://developer.chrome.com/docs/web-platform/document-picture-in-picture.\n// Chromium-only as of 2026; absent everywhere else, so the chat-PiP entry point is gated on this.\nconst DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED = typeof window !== 'undefined' &&\n  'documentPictureInPicture' in window &&\n  typeof window.documentPictureInPicture?.requestWindow === 'function';\n\nexport default DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED;\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n/**\n * A Document Picture-in-Picture window starts as a blank document — none of the app's CSS reaches it.\n * This clones every stylesheet from `source` into `target` and keeps them live:\n *  - `<style>`/`<link>` additions & removals (Vite HMR, themeController's appended night-`<style>`);\n *  - the `<html>` class + inline style (the `.night` toggle, theme CSS custom properties, and the\n *    JS-owned layout vars `--vh` / `--chat-width` / `--left-column-width` …) mirrored on every change;\n *  - the `<body>` class (`has-chat`, `right-column-floats`, `is-mobile`, …).\n *\n * Per-source-sheet node mapping means unchanged sheets are never re-created, so theme/layout updates\n * don't flash the whole PiP. Returns a disposer that stops every observer.\n */\nexport default function mirrorDocumentStyles(source: Document, target: Document): () => void {\n  // Maps a source stylesheet's owner node -> the cloned node we maintain in `target.head`.\n  const mirrored = new Map<Node, HTMLStyleElement | HTMLLinkElement>();\n\n  const syncSheets = () => {\n    const seen = new Set<Node>();\n\n    for(const sheet of Array.from(source.styleSheets)) {\n      const owner = sheet.ownerNode;\n      if(!owner) continue;\n      seen.add(owner);\n\n      let node = mirrored.get(owner);\n      let cssText: string | undefined;\n      try {\n        cssText = Array.from(sheet.cssRules).map((rule) => rule.cssText).join('\\n');\n      } catch{\n        // Cross-origin sheet — cssRules throws. Re-link it by href instead of inlining.\n      }\n\n      if(cssText !== undefined) {\n        if(!node || node.tagName !== 'STYLE') {\n          node?.remove();\n          node = target.createElement('style');\n          mirrored.set(owner, node);\n          target.head.append(node);\n        }\n        if(sheet.media?.mediaText) node.media = sheet.media.mediaText;\n        if(node.textContent !== cssText) node.textContent = cssText;\n      } else {\n        const href = (sheet.ownerNode as HTMLLinkElement).href;\n        if(!href) continue;\n        if(!node || node.tagName !== 'LINK') {\n          node?.remove();\n          node = target.createElement('link');\n          (node as HTMLLinkElement).rel = 'stylesheet';\n          mirrored.set(owner, node);\n          target.head.append(node);\n        }\n        if(sheet.media?.mediaText) node.media = sheet.media.mediaText;\n        if((node as HTMLLinkElement).href !== href) (node as HTMLLinkElement).href = href;\n      }\n    }\n\n    for(const [owner, node] of mirrored) {\n      if(!seen.has(owner)) {\n        node.remove();\n        mirrored.delete(owner);\n      }\n    }\n  };\n\n  const copyAttributes = (from: Element, to: Element, names: string[]) => {\n    for(const name of names) {\n      const value = from.getAttribute(name);\n      if(value === null) to.removeAttribute(name);\n      else if(to.getAttribute(name) !== value) to.setAttribute(name, value);\n    }\n  };\n\n  const syncRoot = () => copyAttributes(source.documentElement, target.documentElement, ['class', 'style', 'dir', 'lang']);\n  const syncBody = () => copyAttributes(source.body, target.body, ['class']);\n\n  syncSheets();\n  syncRoot();\n  syncBody();\n\n  let scheduled = false;\n  const scheduleSheets = () => {\n    if(scheduled) return;\n    scheduled = true;\n    Promise.resolve().then(() => {\n      scheduled = false;\n      syncSheets();\n    });\n  };\n\n  // textContent of an existing <style> mutates as a childList change on that descendant.\n  const headObserver = new MutationObserver(scheduleSheets);\n  headObserver.observe(source.head, {childList: true, subtree: true, characterData: true});\n\n  const rootObserver = new MutationObserver(syncRoot);\n  rootObserver.observe(source.documentElement, {attributes: true, attributeFilter: ['class', 'style', 'dir', 'lang']});\n\n  const bodyObserver = new MutationObserver(syncBody);\n  bodyObserver.observe(source.body, {attributes: true, attributeFilter: ['class']});\n\n  return () => {\n    headObserver.disconnect();\n    rootObserver.disconnect();\n    bodyObserver.disconnect();\n    mirrored.clear();\n  };\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport classNames from '@helpers/string/classNames';\nimport styles from './clientPipPlaceholder.module.scss';\n\n/**\n * Shown in the now-empty tab while the client is popped out into a Document Picture-in-Picture window,\n * so the tab doesn't read as a blank page. The button brings the client back without the user having\n * to find the PiP window's own close control.\n */\nexport default function ClientPipPlaceholder(props: {onReturn: () => void}) {\n  return (\n    <div class={styles.screen}>\n      <div class={styles.content}>\n        <div class={styles.title}>\n          <I18nTsx key=\"ClientPip.PlaceholderTitle\" />\n        </div>\n        <div class={styles.description}>\n          <I18nTsx key=\"ClientPip.PlaceholderDescription\" />\n        </div>\n        <button\n          class={classNames('btn-primary', 'btn-color-primary', styles.button)}\n          onClick={() => props.onReturn()}\n        >\n          <I18nTsx key=\"ClientPip.ReturnToTab\" />\n        </button>\n      </div>\n    </div>\n  );\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED from '@environment/documentPictureInPictureSupport';\nimport {setAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport mirrorDocumentStyles from '@helpers/dom/mirrorDocumentStyles';\nimport appChatBackground from '@components/chat/bubbles/chatBackground';\nimport {delegateEvents, render} from 'solid-js/web';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {logger} from '@lib/logger';\nimport ClientPipPlaceholder from '@components/clientPipPlaceholder';\n\nconst log = logger('CLIENT-PIP');\n\n// The whole IM page (`.whole.page-chats` → #main-columns → the sidebars/list/chat). Moving this whole\n// subtree — not just #main-columns — keeps every `.page-chats`-scoped and `body.*`-scoped layout rule\n// matching (the columns collapse if #main-columns is orphaned from its .page-chats ancestor).\nconst APP_ROOT_ID = 'page-chats';\nconst PIP_WIDTH = 430;\nconst PIP_HEIGHT = 760;\n\ntype PipState = {\n  pipWindow: Window,\n  moved: {node: Element, placeholder: Comment}[],\n  placeholderScreen: HTMLElement,\n  disposePlaceholder: () => void,\n  disposeStyles: () => void,\n  cleanup: () => void\n};\n\nlet state: PipState | undefined;\n\nexport function isClientPipOpen() {\n  return !!state;\n}\n\n/**\n * Move the WHOLE live client (`#main-columns`) into `pipWindow`'s document — same app instance, so\n * it's instant (no boot). Pure DOM move + style mirror + metrics rebind; parameterized by the target\n * window so the headless harness can drive it with a plain iframe (which has a real viewport, unlike\n * the 0×0 preview tab). Returns false if already popped out or the shell is missing.\n */\nexport function moveAppToWindow(pipWindow: Window, onReturn: () => void = moveAppBack): boolean {\n  if(state) return false;\n  const appRoot = document.getElementById(APP_ROOT_ID);\n  if(!appRoot) return false;\n\n  const doc = pipWindow.document;\n  const disposeStyles = mirrorDocumentStyles(document, doc);\n\n  // The pip document is bare — give html/body the resets the app shell expects to fill.\n  const reset = doc.createElement('style');\n  reset.textContent = 'html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden}';\n  doc.head.append(reset);\n  doc.title = document.title;\n\n  // Point the metrics layer (windowSize / mediaSizes / updateColumnWidths / --vh) at the pip window\n  // BEFORE the move, so the very first layout pass sizes for the pip viewport instead of the tab's.\n  setAppWindow(pipWindow);\n\n  // Move every top-level app node — the #page-chats shell AND the body-level overlay roots (stories\n  // viewer, audio player, media-recording stage, sidebar drawer overlay, svg defs) — so overlays\n  // opened in the pip have their roots there too. Each leaves a placeholder comment so it returns to\n  // the exact same spot. Skip <script>s and the pip target itself (the harness iframe is in the body).\n  const moved: {node: Element, placeholder: Comment}[] = [];\n  Array.from(document.body.children).forEach((node) => {\n    if(node.tagName === 'SCRIPT') return;\n    if((node as HTMLIFrameElement).contentWindow === pipWindow) return;\n    const placeholder = document.createComment('client-pip');\n    node.before(placeholder);\n    doc.body.append(node); // cross-document adopt; listeners & state survive\n    moved.push({node, placeholder});\n  });\n\n  // Solid delegates onClick/onInput/etc. to the MAIN document (`delegateEvents` defaults to\n  // `window.document`), running ONE handler that walks up from the target to the node's `$$click`\n  // prop. The moved nodes keep those props, but the handler isn't on the pip document — so every\n  // Solid `onClick` is dead in the pip until we install the same delegated handlers there. (The\n  // event-name Set lives at the documented `_$DX_DELEGATE` key.)\n  const delegated = (document as any)['_$DX_DELEGATE'] as Set<string> | undefined;\n  if(delegated?.size) delegateEvents([...delegated], doc);\n\n  // Shown in the now-empty tab so it doesn't read as a blank page; the button brings the client back\n  // without the user having to find the pip window's own close control.\n  const placeholderScreen = document.createElement('div');\n  document.body.append(placeholderScreen);\n  const disposePlaceholder = render(() => <ClientPipPlaceholder onReturn={onReturn} />, placeholderScreen);\n\n  state = {pipWindow, moved, placeholderScreen, disposePlaceholder, disposeStyles, cleanup: () => {}};\n\n  // The wallpaper canvas/gradient renderer doesn't survive the cross-document move — rebuild it fresh\n  // in the pip document.\n  appChatBackground.reRender();\n\n  return true;\n}\n\n/** Move the client back into the main tab and tear down the pip plumbing. */\nexport function moveAppBack(): void {\n  if(!state) return;\n  const {moved, placeholderScreen, disposePlaceholder, disposeStyles, cleanup} = state;\n  cleanup();\n  disposePlaceholder();\n  placeholderScreen.remove();\n  setAppWindow(window); // rebind metrics to the tab before the move so it reflows for the real viewport\n  moved.forEach(({node, placeholder}) => placeholder.replaceWith(node));\n\n  // Same as on the way out — the wallpaper canvas didn't survive moving back; rebuild it in the tab.\n  appChatBackground.reRender();\n\n  disposeStyles();\n  state = undefined;\n}\n\n/**\n * Return the client to the tab AND dismiss the pip window. Mirrors the internal `closePip` closure wired\n * to the pip's own pagehide/visibility auto-return; exported so the \"Exit Picture-in-Picture\" menu entry\n * (and any other in-app affordance) can close the pip without the user reaching for the OS chrome.\n */\nexport function closeClientPip(): void {\n  const pipWindow = state?.pipWindow;\n  moveAppBack();\n  try {\n    pipWindow?.close();\n  } catch{}\n}\n\n/**\n * Pop the whole client out into an always-on-top Document Picture-in-Picture window. MUST be called\n * from a user gesture (the topbar button) so `requestWindow` is permitted. Auto-returns: once the tab\n * has actually been left and is then re-shown, the app moves back and the pip closes.\n */\nexport default async function openClientPip(): Promise<void> {\n  if(!DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED) return;\n  if(state) {\n    try {\n      state.pipWindow.focus();\n    } catch{}\n    return;\n  }\n\n  let pipWindow: Window;\n  try {\n    pipWindow = await window.documentPictureInPicture!.requestWindow({width: PIP_WIDTH, height: PIP_HEIGHT});\n  } catch(err) {\n    log.error('requestWindow failed', err);\n    return;\n  }\n\n  const closePip = () => {\n    moveAppBack();\n    try {\n      pipWindow.close();\n    } catch{}\n  };\n\n  if(!moveAppToWindow(pipWindow, closePip)) {\n    try {\n      pipWindow.close();\n    } catch{}\n    return;\n  }\n\n  let leftTab = false;\n  const onVisibility = () => {\n    if(document.visibilityState === 'hidden') leftTab = true;\n    else if(leftTab) closePip();\n  };\n\n  state.cleanup = () => {\n    document.removeEventListener('visibilitychange', onVisibility);\n    pipWindow.removeEventListener('pagehide', closePip);\n  };\n\n  document.addEventListener('visibilitychange', onVisibility);\n  // Dismissing via the OS chrome fires `pagehide`, not our close().\n  pipWindow.addEventListener('pagehide', closePip);\n}\n\n// Expose the core for the headless harness — a plain iframe (real viewport) stands in for the pip\n// window, letting the move + metrics-rebind be validated where requestWindow can't run.\nMOUNT_CLASS_TO && ((MOUNT_CLASS_TO as any).clientPip = {moveAppToWindow, moveAppBack, closeClientPip, openClientPip, isClientPipOpen, getOverlayRoot});\n","export type GrabEvent = {x: number, y: number, isTouch?: boolean, event: TouchEvent | MouseEvent};\n\nexport default function attachGrabListeners(element: HTMLElement,\n  onStart: (position: GrabEvent) => void,\n  onMove: (position: GrabEvent) => void,\n  onEnd?: (position: GrabEvent) => void) {\n  // The grab MOVE/END track on `element.ownerDocument`, not the global `document`: while the client is\n  // popped into a Document PiP window the element lives in THAT document, so a main-`document` move/up\n  // listener never fires there and the drag (RangeSelector sliders — volume, seek bar — colorPicker,\n  // etc.) sticks. ownerDocument is the element's current window and can't change mid-drag.\n  // * Mouse\n  const onMouseMove = (event: MouseEvent) => {\n    onMove({x: event.pageX, y: event.pageY, event});\n  };\n\n  const onMouseUp = (event: MouseEvent) => {\n    element.ownerDocument.removeEventListener('mousemove', onMouseMove);\n    element.addEventListener('mousedown', onMouseDown, {once: true});\n    onEnd?.({x: event.pageX, y: event.pageY, event});\n  };\n\n  const onMouseDown = (event: MouseEvent) => {\n    if(event.button !== 0) {\n      element.addEventListener('mousedown', onMouseDown, {once: true});\n      return;\n    }\n\n    onStart({x: event.pageX, y: event.pageY, event});\n    onMouseMove(event);\n\n    element.ownerDocument.addEventListener('mousemove', onMouseMove);\n    element.ownerDocument.addEventListener('mouseup', onMouseUp, {once: true});\n  };\n\n  element.addEventListener('mousedown', onMouseDown, {once: true});\n\n  // * Touch\n  const onTouchMove = (event: TouchEvent) => {\n    event.preventDefault();\n    onMove({x: event.touches[0].clientX, y: event.touches[0].clientY, isTouch: true, event});\n  };\n\n  const onTouchEnd = (event: TouchEvent) => {\n    element.ownerDocument.removeEventListener('touchmove', onTouchMove);\n    element.addEventListener('touchstart', onTouchStart, {passive: false, once: true});\n    const touch = event.touches[0] || event.changedTouches[0];\n    onEnd?.({x: touch.clientX, y: touch.clientY, isTouch: true, event});\n  };\n\n  const onTouchStart = (event: TouchEvent) => {\n    onStart({x: event.touches[0].clientX, y: event.touches[0].clientY, isTouch: true, event});\n    onTouchMove(event);\n\n    element.ownerDocument.addEventListener('touchmove', onTouchMove, {passive: false});\n    element.ownerDocument.addEventListener('touchend', onTouchEnd, {passive: false, once: true});\n  };\n\n  element.addEventListener('touchstart', onTouchStart, {passive: false, once: true});\n\n  return () => {\n    element.removeEventListener('mousedown', onMouseDown);\n    element.ownerDocument.removeEventListener('mousemove', onMouseMove);\n    element.ownerDocument.removeEventListener('mouseup', onMouseUp);\n\n    element.removeEventListener('touchstart', onTouchStart);\n    element.ownerDocument.removeEventListener('touchmove', onTouchMove);\n    element.ownerDocument.removeEventListener('touchend', onTouchEnd);\n  };\n}\n","import attachGrabListeners, {GrabEvent} from '@helpers/dom/attachGrabListeners';\nimport clamp from '@helpers/number/clamp';\nimport safeAssign from '@helpers/object/safeAssign';\nimport I18n from '@lib/langPack';\n\nexport default class RangeSelector {\n  public container: HTMLDivElement;\n  protected filled: HTMLDivElement;\n  protected seek: HTMLInputElement;\n\n  public mousedown = false;\n  protected rect: DOMRect;\n  protected _removeListeners: () => void;\n\n  private events: Partial<{\n    // onMouseMove: ProgressLine['onMouseMove'],\n    onMouseDown: RangeSelector['onMouseDown'],\n    onMouseUp: RangeSelector['onMouseUp'],\n    onScrub: (value: number) => void\n  }> = {};\n\n  protected decimals: number;\n\n  protected step: number;\n  protected min: number;\n  protected max: number;\n  protected withTransition = false;\n  protected useTransform = false;\n  protected useProperty = false;\n  protected vertical = false;\n  protected offsetAxisValue = 0;\n\n  constructor(\n    options: {\n      step: RangeSelector['step'],\n      min?: RangeSelector['min'],\n      max?: RangeSelector['max'],\n      withTransition?: RangeSelector['withTransition'],\n      useTransform?: RangeSelector['useTransform'],\n      vertical?: RangeSelector['vertical'],\n      useProperty?: RangeSelector['useProperty'],\n      offsetAxisValue?: RangeSelector['offsetAxisValue']\n    },\n    value = 0\n  ) {\n    safeAssign(this, options);\n\n    this.container = document.createElement('div');\n    this.container.classList.add('progress-line');\n\n    // there is no sense in using transition with transform, because it is updating every frame\n    if(this.useTransform) {\n      this.container.classList.add('use-transform');\n    } else if(this.withTransition) {\n      this.container.classList.add('with-transition');\n    }\n\n    this.filled = document.createElement('div');\n    this.filled.classList.add('progress-line__filled');\n\n    const seek = this.seek = document.createElement('input');\n    seek.classList.add('progress-line__seek');\n    seek.type = 'range';\n    seek.step = '' + this.step;\n    this.setMinMax(this.min, this.max);\n    seek.value = '' + value;\n\n    if(value) {\n      this.setProgress(value);\n    }\n\n    const stepStr = '' + this.step;\n    const index = stepStr.indexOf('.');\n    this.decimals = index === -1 ? 0 : stepStr.length - index - 1;\n\n    this.container.append(this.filled, seek);\n  }\n\n  public setMinMax(min?: number, max?: number) {\n    this.min = min ?? (this.min ??= 0);\n    this.max = max ?? (this.max ??= 0);\n    this.seek.min = '' + min;\n    this.seek.max = '' + max;\n  }\n\n  get value() {\n    return +this.seek.value;\n  }\n\n  public setHandlers(events: RangeSelector['events']) {\n    this.events = events;\n  }\n\n  protected onMouseMove = (event: GrabEvent) => {\n    this.scrub(event);\n  };\n\n  protected onMouseDown = (event: GrabEvent) => {\n    this.rect = this.container.getBoundingClientRect();\n    this.mousedown = true;\n    this.scrub(event);\n    this.container.classList.add('is-focused');\n    this.events?.onMouseDown && this.events.onMouseDown(event);\n  };\n\n  protected onMouseUp = (event: GrabEvent) => {\n    this.mousedown = false;\n    this.container.classList.remove('is-focused');\n    this.events?.onMouseUp && this.events.onMouseUp(event);\n  };\n\n  public setListeners() {\n    this.seek.addEventListener('input', this.onInput);\n    this._removeListeners = attachGrabListeners(this.container, this.onMouseDown, this.onMouseMove, this.onMouseUp);\n  }\n\n  public onInput = () => {\n    const value = +this.seek.value;\n    this.setFilled(value);\n    this.events?.onScrub && this.events.onScrub(value);\n  };\n\n  public setProgress(value: number) {\n    this.seek.value = '' + value;\n    this.setFilled(+this.seek.value); // clamp\n  }\n\n  public addProgress(value: number) {\n    this.seek.value = '' + (+this.seek.value + value);\n    this.setFilled(+this.seek.value); // clamp\n  }\n\n  public setFilled(value: number) {\n    let percents = (value - this.min) / (this.max - this.min);\n    percents = clamp(percents, 0, 1);\n\n    // using scaleX and width even with vertical because it will be rotated\n    if(this.useTransform) {\n      this.filled.style.transform = `scaleX(${percents})`;\n    } else if(this.useProperty) {\n      this.container.style.setProperty('--progress', '' + percents);\n    } else {\n      this.filled.style.width = (percents * 100) + '%';\n    }\n  }\n\n  /**\n   * Make sure rect is set\n   * @returns value [0..1]\n   */\n  protected getValueByEvent(event: GrabEvent) {\n    let rectMax = this.vertical ? this.rect.height : this.rect.width;\n\n    if(this.offsetAxisValue) {\n      rectMax -= this.offsetAxisValue;\n    }\n\n    let offsetAxisValue = clamp(\n      this.vertical ?\n        -(event.y - this.rect.bottom) :\n        event.x - this.rect.left - this.offsetAxisValue / 2/*  - 30 */,\n      0,\n      rectMax\n    );\n\n    if(!this.vertical && I18n.getIsRTL()) {\n      offsetAxisValue = rectMax - offsetAxisValue;\n    }\n\n    return offsetAxisValue / rectMax;\n  }\n\n  protected scrub(event: GrabEvent, snapValue?: (value: number) => number) {\n    let value = this.min + (this.getValueByEvent(event) * (this.max - this.min));\n\n    if((value - this.min) < ((this.max - this.min) / 2)) {\n      value -= this.step / 10;\n    }\n\n    value = +value.toFixed(this.decimals);\n    value = clamp(value, this.min, this.max);\n    if(snapValue) value = snapValue(value);\n\n    // this.seek.value = '' + value;\n    // this.onInput();\n\n    this.setProgress(value);\n    this.events?.onScrub && this.events.onScrub(value);\n\n    return value;\n  }\n\n  public removeListeners() {\n    if(this._removeListeners) {\n      this._removeListeners();\n      this._removeListeners = null;\n    }\n\n    this.seek.removeEventListener('input', this.onInput);\n\n    this.events = {};\n  }\n}\n","import {getOverlayRoot} from '@helpers/appWindow';\nimport createElementFromMarkup from '@helpers/createElementFromMarkup';\nimport {GrabEvent} from '@helpers/dom/attachGrabListeners';\nimport safePlay from '@helpers/dom/safePlay';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {VideoTimestamp} from '@components/appMediaViewerBase';\nimport RangeSelector from '@components/rangeSelector';\nimport {observeResize} from '@components/resizeObserver';\n\nconst MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH = 7; // -2px padding will be 5px\n\ntype VideoTimestampSegment = {\n  time: number;\n  left: number;\n  right: number;\n}\n\nexport default class MediaProgressLine extends RangeSelector {\n  protected filledContainer?: HTMLDivElement;\n  protected filledLoad: HTMLDivElement;\n\n  protected currentTimeInfoElement?: HTMLDivElement;\n  protected currentTimeElement?: HTMLDivElement;\n  protected currentSegmentElement?: HTMLDivElement;\n\n  protected progressRAF: number;\n\n  protected media: HTMLMediaElement;\n  protected streamable: boolean;\n\n  protected static svgClipPathIdSeed = 0;\n  protected usedClipPathId: number;\n  protected clipPathSvg: SVGSVGElement;\n\n  protected segments: VideoTimestampSegment[] = [];\n  // protected lastOnPlayTime: number;\n  // protected lastOnPlayCurrentTime: number;\n\n  protected unobserveResize?: () => void;\n  protected activeSegmentIdx: number;\n  protected hoverRAF: number;\n\n  constructor(protected options: {\n    withTransition?: boolean,\n    useTransform?: boolean,\n    onSeekStart?: () => void,\n    onSeekEnd?: () => void,\n    onTimeUpdate?: (time: number) => void,\n    onHover?: (progress: number) => void,\n    onPointerOut?: () => void,\n    videoTimestamps?: VideoTimestamp[],\n    withTime?: boolean,\n    appendToTimeElement?: HTMLElement\n  } = {}) {\n    super({\n      step: 1000 / 60 / 1000,\n      min: 0,\n      max: 1,\n      withTransition: options.withTransition,\n      useTransform: options.useTransform\n    }, 0);\n  }\n\n  public setMedia({\n    media,\n    streamable,\n    duration\n  }: {\n    media: HTMLMediaElement,\n    streamable?: boolean,\n    duration?: number\n  }) {\n    if(this.media) {\n      this.removeListeners();\n    }\n\n    if(streamable && !this.filledLoad) {\n      this.filledLoad = document.createElement('div');\n      this.filledLoad.classList.add('progress-line__filled', 'progress-line__loaded');\n      this.container.prepend(this.filledLoad);\n      // this.setLoadProgress();\n    } else if(this.filledLoad) {\n      this.filledLoad.classList.toggle('hide', !streamable);\n    }\n\n    this.media = media;\n    this.streamable = streamable;\n    if(!media.paused || media.currentTime > 0) {\n      this.onPlay();\n    }\n\n    this.setTimestampsClipPath();\n\n    let wasPlaying = false;\n    this.setSeekMax(duration);\n    this.setListeners();\n    this.setHandlers({\n      onMouseDown: () => {\n        wasPlaying = !this.media.paused;\n        wasPlaying && this.media.pause();\n        this.options?.onSeekStart?.();\n        this.container.classList.add('media-progress-line--seeking');\n      },\n\n      onMouseUp: (e) => {\n        // cancelEvent(e.event);\n        wasPlaying && safePlay(this.media);\n        this.options?.onSeekEnd?.();\n        this.container.classList.remove('media-progress-line--seeking');\n      }\n    });\n  }\n\n  protected initResizeObserver() {\n    this.unobserveResize?.();\n    this.unobserveResize = observeResize(this.filledContainer, () => {\n      this.setTimestampsClipPath();\n    });\n  }\n\n  protected onHover = (e: MouseEvent) => {\n    if(this.hoverRAF) {\n      return;\n    }\n\n    if(this.options.onHover) {\n      this.rect = this.container.getBoundingClientRect();\n      this.options.onHover(this.getValueByEvent({x: e.pageX, y: e.pageY, event: e}));\n    }\n\n    if(!this.filledContainer) {\n      return;\n    }\n\n    if(this.activeSegmentIdx !== undefined) {\n      this.toggleSegment(this.activeSegmentIdx, false);\n    }\n\n    const bcr = this.filledContainer.getBoundingClientRect();\n    const x = e.clientX - bcr.left;\n\n    const segmentIdx = this.segments.findIndex((segment) => segment.left <= x && x <= segment.right);\n    if(segmentIdx >= 0) {\n      this.activeSegmentIdx = segmentIdx;\n      this.toggleSegment(segmentIdx, true);\n    }\n\n    this.updateTimeAndSegment(x, bcr.width);\n  }\n\n  protected onPointerOut = () => {\n    this.options.onPointerOut?.();\n\n    if(this.filledContainer) {\n      this.toggleSegment(this.activeSegmentIdx, false);\n      this.activeSegmentIdx = undefined;\n    }\n  }\n\n  protected toggleSegment(idx: number, active: boolean) {\n    const element = this.clipPathSvg?.querySelector(`rect:nth-child(${idx + 1})`);\n    if(!element) {\n      return;\n    }\n\n    if(active) element.setAttribute('data-active', 'true');\n    else element.removeAttribute('data-active');\n  }\n\n  protected wrapProgressLinesInContainer() {\n    if(this.filledContainer) {\n      return;\n    }\n\n    this.container.classList.add('media-progress-line');\n\n    this.filledContainer = document.createElement('div');\n    this.filledContainer.classList.add('media-progress-line__filled-container');\n\n    const thumb = document.createElement('div');\n    thumb.classList.add('media-progress-line__thumb');\n\n    this.currentTimeInfoElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-time-info');\n\n    this.currentTimeElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-time');\n\n    this.currentSegmentElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-segment');\n\n    this.currentTimeInfoElement.append(...[\n      this.options.appendToTimeElement,\n      this.currentSegmentElement,\n      this.currentTimeElement\n    ].filter(Boolean));\n\n    this.filledContainer.append(this.filled, this.filledLoad);\n\n    this.container.prepend(this.filledContainer);\n    this.container.append(thumb, this.currentTimeInfoElement);\n\n    this.initResizeObserver();\n  }\n\n  protected clearTimeAndSegment() {\n    this.currentTimeElement.textContent = '';\n    this.currentSegmentElement.textContent = '';\n  }\n\n  protected updateTimeAndSegment(x: number, width: number) {\n    if(!this.media || !this.currentTimeInfoElement) {\n      return;\n    }\n\n    if(x < 0 || x > width) {\n      this.clearTimeAndSegment();\n      return;\n    }\n\n    const formattedTime = toHHMMSS(x / width * this.media.duration | 0);\n    this.currentTimeElement.textContent = formattedTime;\n\n    if(this.segments?.length > 0) {\n      const segment = this.segments.find((segment) => segment.left <= x && x <= segment.right);\n      const timestamp = this.options.videoTimestamps?.find((timestamp) => timestamp.time === segment.time);\n      this.currentSegmentElement.textContent = limitSymbols(timestamp?.text || '', 24, 27);\n    }\n\n    const infoBcr = this.currentTimeInfoElement.getBoundingClientRect();\n\n    const pushFromRight = Math.min(0, width - (x + infoBcr.width / 2));\n    const pushFromLeft = Math.max(0, infoBcr.width / 2 - x);\n\n    this.currentTimeInfoElement.style.setProperty('--current-time-info-x', x + pushFromLeft + pushFromRight + 'px');\n  }\n\n  protected setTimestampsClipPath() {\n    this.removeClipPathFromDOM();\n    this.segments = [];\n\n    if(!this.options.videoTimestamps?.length && !this.options.withTime) {\n      return;\n    }\n\n    this.wrapProgressLinesInContainer();\n\n    const bcr = this.filledContainer.getBoundingClientRect();\n    const totalWidth = bcr.width;\n\n    const segments = this.segments = this.getTimestampSegments(totalWidth);\n    if(!segments?.length) {\n      return;\n    }\n\n    const margin = 1;\n\n    const rects = segments.map((segment) => `<rect x=\"${\n      (segment.left + margin).toFixed(2)\n    }\" width=\"${\n      (segment.right - segment.left - 2 * margin).toFixed(2)\n    }\" rx=\"1\" />`);// }\"\n\n    this.usedClipPathId = ++MediaProgressLine.svgClipPathIdSeed;\n\n    const svgId = `media-progress-line-clip-path-svg-${MediaProgressLine.svgClipPathIdSeed}`;\n    const clipPathId = `media-progress-line-clip-path-${MediaProgressLine.svgClipPathIdSeed}`;\n\n    this.removeClipPathFromDOM();\n\n    this.clipPathSvg = createElementFromMarkup(`\n      <svg width=\"0\" height=\"0\" class=\"media-progress-line-clip-path-svg\" id=\"${svgId}\">\n        <clipPath id=\"${clipPathId}\">\n          ${rects.join('\\n')}\n        </clipPath>\n      </svg>\n    `);\n\n    getOverlayRoot().append(this.clipPathSvg);\n\n    this.filledContainer.style.clipPath = `url(#${clipPathId})`;\n  }\n\n  protected getTimestampSegments(totalWidth: number) {\n    const {videoTimestamps} = this.options;\n    if(!videoTimestamps?.length || !this.filledContainer) {\n      return [];\n    }\n\n    const duration = this.media.duration;\n    if(!duration) {\n      return [];\n    }\n\n    const timePoints = videoTimestamps.map(({time}) => time)\n    .filter((time) => time >= 0 && time <= duration)\n    .sort((a, b) => a - b);\n\n    if(timePoints[0] !== 0) timePoints.unshift(0);\n    timePoints.push(duration);\n\n    const result: VideoTimestampSegment[] = [];\n\n    let prevRight = 0;\n    for(let i = 0; i < timePoints.length - 1; i++) {\n      const left = Math.max(prevRight, timePoints[i] / duration * totalWidth);\n      let right = timePoints[i + 1] / duration * totalWidth;\n\n      if(right <= left) {\n        continue;\n      }\n\n      right = Math.max(right, left + MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH);\n      prevRight = right;\n\n      if(right + MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH >= totalWidth) right = totalWidth;\n\n      result.push({\n        left,\n        right,\n        time: timePoints[i]\n      });\n\n      if(right === totalWidth) {\n        break;\n      }\n    }\n\n    return result;\n  }\n\n  public removeClipPathFromDOM() {\n    this.clipPathSvg?.remove();\n  }\n\n  protected onLoadedData = () => {\n    this.setSeekMax();\n    this.setTimestampsClipPath();\n  };\n\n  protected onEnded = () => {\n    this.setProgress();\n  };\n\n  protected onPlay = () => {\n    const r = () => {\n      this.setProgress();\n\n      this.progressRAF = this.media.paused ? undefined : window.requestAnimationFrame(r);\n    };\n\n    if(this.progressRAF) {\n      window.cancelAnimationFrame(this.progressRAF);\n      this.progressRAF = undefined;\n    }\n\n    if(this.streamable) {\n      this.setLoadProgress();\n    }\n\n    // this.lastOnPlayTime = Date.now();\n    // this.lastOnPlayCurrentTime = this.media.currentTime;\n    r();\n    // this.progressRAF = window.requestAnimationFrame(r);\n  };\n\n  protected onTimeUpdate = () => {\n    if(this.media.paused) {\n      this.setProgress();\n\n      if(this.streamable) {\n        this.setLoadProgress();\n      }\n    }\n  };\n\n  protected onProgress = (e: Event) => {\n    this.setLoadProgress();\n  };\n\n  protected scrub(e: GrabEvent) {\n    let scrubTime = super.scrub(e, this.snapScrubValue);\n    // avoid `ended` when scrubbing to the end\n    if(this.media.duration && scrubTime >= this.media.duration) {\n      scrubTime = this.media.duration - 0.1;\n    }\n    setCurrentTime(this.media, scrubTime);\n    return scrubTime;\n  }\n\n  protected snapScrubValue = (value: number) => {\n    if(!this.segments?.length) {\n      return value;\n    }\n\n    const totalWidth = this.segments[this.segments.length - 1].right;\n    const x = value / this.media.duration * totalWidth;\n    for(const segment of this.segments) {\n      if(segment.left - 2 <= x && x <= segment.left + 3) {\n        return segment.time;\n      }\n    }\n\n    return value;\n  }\n\n  protected setLoadProgress() {\n    if(appMediaPlaybackController.isSafariBuffering(this.media)) {\n      return;\n    }\n\n    const buf = this.media.buffered;\n    const numRanges = buf.length;\n\n    const currentTime = this.media.currentTime;\n    let nearestStart = 0, end = 0;\n    for(let i = 0; i < numRanges; ++i) {\n      const start = buf.start(i);\n      if(currentTime >= start && start >= nearestStart) {\n        nearestStart = start;\n        end = buf.end(i);\n      }\n\n      // console.log('onProgress range:', i, buf.start(i), buf.end(i), this.media);\n    }\n\n    // console.log('onProgress correct range:', nearestStart, end, this.media);\n\n    const percents = this.max ? end / this.max : 0;\n    this.filledLoad.style.width = (percents * 100) + '%';\n    // this.filledLoad.style.transform = 'scaleX(' + percents + ')';\n  }\n\n  protected setSeekMax(duration?: number) {\n    const realDuration = this.media.duration || 0;\n    if(duration === undefined || realDuration) duration = realDuration;\n    if(this.max = duration) {\n      this.seek.setAttribute('max', '' + this.max);\n    } else {\n      this.media.addEventListener('loadeddata', this.onLoadedData);\n    }\n  }\n\n  public setProgress() {\n    if(appMediaPlaybackController.isSafariBuffering(this.media)) {\n      return;\n    }\n\n    // fix jumping progress on play\n    // let currentTime: number;\n    // const diff = (Date.now() - this.lastOnPlayTime) / 1000;\n    // if(!this.media.paused && this.lastOnPlayTime && diff <= 1) {\n    //   currentTime = this.lastOnPlayCurrentTime + diff;\n    // } else {\n    //   currentTime = this.media.currentTime;\n    // }\n\n    const currentTime = this.media.currentTime;\n    this.options.onTimeUpdate?.(currentTime);\n    super.setProgress(currentTime);\n\n    this.container.style.setProperty('--progress', currentTime / this.media.duration + '');\n  }\n\n  public setListeners() {\n    super.setListeners();\n    this.media.addEventListener('ended', this.onEnded);\n    this.media.addEventListener('play', this.onPlay);\n    this.media.addEventListener('pause', this.onTimeUpdate);\n    this.media.addEventListener('timeupdate', this.onTimeUpdate);\n    this.streamable && this.media.addEventListener('progress', this.onProgress);\n\n    if(this.options.onHover || this.options.videoTimestamps || this.options.withTime) {\n      this.container.addEventListener('pointermove', this.onHover);\n      this.container.addEventListener('pointerout', this.onPointerOut);\n    }\n  }\n\n  public removeListeners() {\n    super.removeListeners();\n\n    if(this.media) {\n      this.media.removeEventListener('loadeddata', this.onLoadedData);\n      this.media.removeEventListener('ended', this.onEnded);\n      this.media.removeEventListener('play', this.onPlay);\n      this.media.removeEventListener('pause', this.onTimeUpdate);\n      this.media.removeEventListener('timeupdate', this.onTimeUpdate);\n      this.streamable && this.media.removeEventListener('progress', this.onProgress);\n    }\n\n    this.container.removeEventListener('pointermove', this.onHover);\n    this.container.removeEventListener('pointerout', this.onPointerOut);\n\n    if(this.progressRAF) {\n      window.cancelAnimationFrame(this.progressRAF);\n      this.progressRAF = undefined;\n    }\n  }\n\n  public cleanup() {\n    this.removeClipPathFromDOM();\n    this.removeListeners();\n    this.unobserveResize?.();\n    this.segments = [];\n  }\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {_tgico} from '@helpers/tgico';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {replaceButtonIcon} from '@components/button';\nimport RangeSelector from '@components/rangeSelector';\n\nconst className = 'player-volume';\n\nexport default class VolumeSelector extends RangeSelector {\n  private static ICONS: Icon[] = ['volume_off', 'volume_mute', 'volume_down', 'volume_up'];\n  public btn: HTMLElement;\n  protected icon: HTMLSpanElement;\n  protected listenerSetter: ListenerSetter;\n  protected vertical: boolean;\n  protected media: HTMLMediaElement;\n  protected useGlobalVolume: 'auto' | 'no-init';\n  protected onVolumeChange: (type: 'global' | 'click') => void;\n  protected ignoreGlobalEvents: boolean;\n\n  constructor(options: {\n    listenerSetter: ListenerSetter,\n    useGlobalVolume?: VolumeSelector['useGlobalVolume'],\n    vertical?: boolean,\n    media?: HTMLMediaElement,\n    maxVolume?: number,\n    onVolumeChange?: VolumeSelector['onVolumeChange']\n  }) {\n    super({\n      step: 0.01,\n      min: 0,\n      max: options.maxVolume ?? 1,\n      vertical: options.vertical\n    }, 1);\n\n    safeAssign(this, options);\n\n    this.setListeners();\n    this.setHandlers({\n      onScrub: (_value) => {\n        const value = Math.max(Math.min(_value, this.max), 0);\n\n        if(this.useGlobalVolume) {\n          this.modifyGlobal(() => {\n            appMediaPlaybackController.muted = false;\n            this.writeGlobalVolume(value);\n          });\n        }\n\n        this.setVolume({volume: value, muted: false, eventType: 'click'});\n      }\n\n      /* onMouseUp: (e) => {\n        cancelEvent(e.event);\n      } */\n    });\n\n    const btn = this.btn = document.createElement('div');\n    btn.classList.add('btn-icon', className);\n\n    attachClickEvent(btn, (e) => {\n      if(!findUpClassName(e.target, className + '__icon') && e.target !== this.btn) {\n        return;\n      }\n\n      this.onMuteClick(e);\n    }, {listenerSetter: this.listenerSetter});\n\n    if(this.useGlobalVolume) {\n      this.listenerSetter.add(appMediaPlaybackController)('playbackParams', (params) => {\n        if(this.ignoreGlobalEvents) {\n          return;\n        }\n\n        this.setVolume({volume: this.readGlobalVolume(), muted: params.muted, eventType: 'global'});\n      });\n\n      if(this.useGlobalVolume === 'no-init') {\n        this.setVolume({volume: this.readGlobalVolume(), muted: this.media.muted});\n      } else {\n        this.setGlobalVolume();\n      }\n    } else if(this.media) {\n      this.setVolume({volume: this.media.volume, muted: this.media.muted});\n    }\n\n    btn.append(this.container);\n  }\n\n  public removeListeners() {\n    super.removeListeners();\n    this.onVolumeChange = undefined;\n  }\n\n  private modifyGlobal(callback: () => void) {\n    this.ignoreGlobalEvents = true;\n    callback();\n    this.ignoreGlobalEvents = false;\n  }\n\n  private onMuteClick(e?: Event) {\n    e && cancelEvent(e);\n\n    const globalMuted = appMediaPlaybackController.muted;\n    const {volume, muted} = this.media ?? {};\n\n    if(this.useGlobalVolume) {\n      this.modifyGlobal(() => {\n        appMediaPlaybackController.muted = !globalMuted;\n      });\n    }\n\n    this.setVolume({\n      volume: volume ?? this.readGlobalVolume(),\n      muted: !(muted ?? globalMuted),\n      eventType: 'click'\n    });\n  }\n\n  /**\n   * Read the global volume this selector tracks. A selector bound to a concrete media\n   * element (the video player) always follows the shared master `volume`. The global-only\n   * selector (pinned audio plate) follows the playing media: for voice that's `volume +\n   * boost` (its 0–200% range), so the boost shows on the slider without leaking elsewhere.\n   */\n  protected readGlobalVolume() {\n    return this.media ? appMediaPlaybackController.volume : appMediaPlaybackController.getGlobalSliderVolume();\n  }\n\n  /**\n   * Write a slider value back to the controller. With a local media element it sets the\n   * shared master directly; the global-only selector routes through the controller, which\n   * splits a voice value into shared master (0–100%) + voice-only boost (100–200%).\n   */\n  protected writeGlobalVolume(value: number) {\n    if(this.media) {\n      appMediaPlaybackController.volume = value;\n    } else {\n      appMediaPlaybackController.setGlobalSliderVolume(value);\n    }\n  }\n\n  public setVolume = ({volume, muted, eventType}: {volume: number, muted: boolean, eventType?: 'global' | 'click'}) => {\n    let iconIndex: number;\n    if(!volume || muted) {\n      iconIndex = 0;\n    } else if(volume > .5) {\n      iconIndex = 3;\n    } else if(volume > 0 && volume < .25) {\n      iconIndex = 1;\n    } else {\n      iconIndex = 2;\n    }\n\n    const newIcon = replaceButtonIcon(this.btn, VolumeSelector.ICONS[iconIndex]);\n    newIcon.classList.add(className + '__icon');\n\n    if(this.media) {\n      // HTMLMediaElement only accepts [0, 1]; the master volume is already clamped, but a\n      // boosted voice value (or a stale persisted >1) must never reach the element directly.\n      this.media.volume = Math.min(volume, 1);\n      this.media.muted = muted;\n    }\n\n    if(!this.mousedown) {\n      this.setProgress(muted ? 0 : volume);\n    }\n\n    eventType && this.onVolumeChange?.(eventType);\n  };\n\n  public setGlobalVolume = (eventType?: Parameters<VolumeSelector['setVolume']>[0]['eventType']) => {\n    const volume = this.readGlobalVolume();\n    const muted = appMediaPlaybackController.muted;\n    return this.setVolume({volume, muted, eventType});\n  };\n\n  public setMaxVolume = (max: number) => {\n    if(this.max === max) return;\n    this.max = max;\n    this.seek.max = '' + max;\n    this.setFilled(+this.seek.value);\n  };\n}\n","export default function createCanvasStream({width = 0, height = 0, image}: Partial<{width: number, height: number, image: CanvasImageSource}> = {}) {\n  const canvas = document.createElement('canvas');\n  canvas.width = width;\n  canvas.height = height;\n  const stream = canvas.captureStream();\n  stream.getVideoTracks()[0].enabled = true;\n  const context = canvas.getContext('2d');\n  if(image) {\n    context.drawImage(image, 0, 0, width, height);\n    context.globalAlpha = 0.5;\n    context.fillStyle = '#000';\n    context.fillRect(0, 0, width, height);\n  } else {\n    context.fillRect(0, 0, width, height);\n  }\n  return stream;\n}\n","import {HlsStandardResolutionHeight} from '@lib/hls/types';\n\nexport function snapQualityHeight(height: number) {\n  const standardHeights: HlsStandardResolutionHeight[] = [480, 720, 1080];\n\n  const threshold1 = (standardHeights[1] - standardHeights[0]) / 2;\n  if(height < standardHeights[0] + threshold1) return standardHeights[0];\n\n  const threshold2 = (standardHeights[2] - standardHeights[1]) / 2;\n  if(height < standardHeights[1] + threshold2) return standardHeights[1];\n\n  return standardHeights[2];\n}\n","import {createEffect, createMemo, createSignal, Show, JSX} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport type {Level} from 'hls.js';\n\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport Icon from '@components/icon';\nimport deferredPromise from '@helpers/cancellablePromise';\n\nimport {hlsInstancesByVideo} from '@lib/hls/hlsInstancesByVideo';\nimport {HlsStandardResolutionHeight} from '@lib/hls/types';\nimport {snapQualityHeight} from '@lib/hls/snapQualityHeight';\nimport {i18n, LangPackKey} from '@lib/langPack';\n\ntype QualityLevelsSwitchButtonProps = {\n  video: HTMLVideoElement;\n  skin: string;\n  onMenuToggle?: (open: boolean) => void;\n};\n\ntype InternalQualityLevelsSwitchButtonProps = QualityLevelsSwitchButtonProps & {\n  controlsRef: (value: QualityLevelsSwitchButtonControls) => void;\n}\n\ntype QualityLevelsSwitchButtonControls = {\n  loadQualityLevels: () => Promise<void>;\n  isMenuOpen: () => boolean;\n}\n\nfunction QualityLevelsSwitchButton(props: InternalQualityLevelsSwitchButtonProps) {\n  const [qualityLevelsMenuButtons, setQualityLevelsMenuButtons] = createSignal<ButtonMenuItemOptionsVerifiable[]>([]);\n\n  const [selectedHeight, setSelectedHeight] = createSignal<HlsStandardResolutionHeight>();\n  const [qualityLevelsLoaded, setQualityLevelsLoaded] = createSignal(false);\n\n  const controls: QualityLevelsSwitchButtonControls = {\n    loadQualityLevels: async() => {\n      setQualityLevelsLoaded(true);\n    },\n    isMenuOpen: () => {\n      return qualityLevelsButton().classList.contains('menu-open');\n    }\n  };\n\n  props.controlsRef(controls);\n\n  // Uncomment during development\n  // createEffect(() => {\n  //   setQualityLevelsLoaded(true);\n  // });\n\n  createEffect(() => {\n    if(qualityLevelsLoaded()) (async() => {\n      const options = await getButtonMenuQualityOptions(props.video, setSelectedHeight);\n      setQualityLevelsMenuButtons(options);\n    })();\n  });\n\n  createEffect(() => {\n    if(qualityLevelsLoaded()) {\n      qualityLevelsMenuButtons().forEach((btn) => btn.icon = undefined);\n      const selectedMenuButton = qualityLevelsMenuButtons().find((btn) => btn.id === (selectedHeight() || 'auto'));\n      if(selectedMenuButton) selectedMenuButton.icon = 'check';\n    }\n  });\n\n  const qualityLevelsButton = createMemo(() => ButtonMenuToggle({\n    icon: `settings ${props.skin}__button checkable-button-menu quality-levels-switch-button`,\n    buttons: qualityLevelsMenuButtons(),\n    direction: 'top-left',\n    onOpen: () => {\n      props.onMenuToggle?.(true);\n    },\n    onClose: () => {\n      props.onMenuToggle?.(false);\n    }\n  }));\n\n  createEffect(() => {\n    qualityLevelsButton()?.append(HdSvg() as HTMLElement);\n  });\n\n  createEffect(() => {\n    const isHd = selectedHeight() === 1080;\n\n    qualityLevelsButton()?.querySelector('.tgico')?.replaceWith(Icon(isHd ? 'settings_clipped_corner' : 'settings'));\n    qualityLevelsButton()?.classList.toggle('quality-levels-switch-button--is-hd', isHd);\n  });\n\n  return <Show when={qualityLevelsMenuButtons().length > 0}>{qualityLevelsButton()}</Show>;\n}\n\nexport function createQualityLevelsSwitchButton(props: QualityLevelsSwitchButtonProps) {\n  const element = document.createElement('div');\n  let controls: QualityLevelsSwitchButtonControls;\n\n  const dispose = render(\n    () => (\n      <QualityLevelsSwitchButton\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n\nexport function ButtonMenuItemWithAuxiliaryText(mainText: LangPackKey, additionalText: JSX.Element) {\n  return  (\n    <span class=\"btn-menu-item-with-auxiliary-text\">\n      {i18n(mainText)}\n      <span class=\"btn-menu-item-auxiliary-text\">{additionalText}</span>\n    </span>\n  );\n}\n\nexport function ButtonMenuItemQualityText(height: HlsStandardResolutionHeight) {\n  return ButtonMenuItemWithAuxiliaryText(`Hls.ResolutionHeightName${height}`, `${height}p`);\n}\n\nasync function getButtonMenuQualityOptions(\n  video: HTMLVideoElement,\n  onHeightSelect: (level?: HlsStandardResolutionHeight) => void\n) {\n  const hls = hlsInstancesByVideo.get(video);\n  if(!hls) return [];\n\n  const deferredLevels = deferredPromise<Level[]>();\n\n  const {default: Hls} = await import('hls.js');\n\n  if(hls.levels && hls.levels.length > 0) {\n    deferredLevels.resolve(hls.levels);\n  } else hls.on(Hls.Events.MANIFEST_PARSED, (_, data) => {\n    deferredLevels.resolve(data.levels);\n  });\n\n  const levels = await deferredLevels;\n\n  const availableHeights = Array.from(new Set(levels.map((level) => snapQualityHeight(level.height))))\n  .sort((a, b) => b - a);\n\n  const qualityButtons = availableHeights.map((height): ButtonMenuItemOptionsVerifiable => {\n    const levelsOfThisHeight = levels.filter((level) => snapQualityHeight(level.height) === height)\n    .sort((a, b) => a.bitrate - b.bitrate);\n\n    const onClick = () => {\n      let optimalLevel = levelsOfThisHeight[0];\n      for(const level of levelsOfThisHeight) {\n        if(level.bitrate < hls.bandwidthEstimate) optimalLevel = level;\n      }\n      const idx = levels.indexOf(optimalLevel);\n\n      hls.currentLevel = idx;\n      onHeightSelect(height);\n      // hls.autoLevelCapping = idx;\n    }\n\n    return {\n      id: height,\n      emptyIcon: true,\n      regularText: ButtonMenuItemQualityText(height) as HTMLElement,\n      onClick\n    };\n  });\n\n  const result: ButtonMenuItemOptionsVerifiable[] = [\n    {\n      id: 'auto',\n      text: 'Hls.ResolutionHeightAuto',\n      emptyIcon: true,\n      onClick: () => {\n        hls.currentLevel = -1;\n        onHeightSelect();\n      // hls.autoLevelCapping = -1;\n      }\n    },\n    ...qualityButtons\n  ];\n\n  return result;\n}\n\nfunction HdSvg() {\n  return (\n    <svg class='quality-levels-switch-button__hd-icon' width=\"14\" height=\"10\" viewBox=\"0 0 14 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"14\" height=\"10\" rx=\"2\" fill=\"currentColor\"/>\n      <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M3.5 2.5C3.5 2.08579 3.16421 1.75 2.75 1.75C2.33579 1.75 2 2.08579 2 2.5V5V7.5C2 7.91421 2.33579 8.25 2.75 8.25C3.16421 8.25 3.5 7.91421 3.5 7.5V5.75H5V7.5C5 7.91421 5.33579 8.25 5.75 8.25C6.16421 8.25 6.5 7.91421 6.5 7.5V5V2.5C6.5 2.08579 6.16421 1.75 5.75 1.75C5.33579 1.75 5 2.08579 5 2.5V4.25H3.5V2.5ZM8.25 1.75C7.83579 1.75 7.5 2.08579 7.5 2.5V7.5C7.5 7.91421 7.83579 8.25 8.25 8.25H9.75C11.2688 8.25 12.5 7.01878 12.5 5.5V4.5C12.5 2.98122 11.2688 1.75 9.75 1.75H8.25ZM9.75 6.75H9V3.25H9.75C10.4404 3.25 11 3.80964 11 4.5V5.5C11 6.19036 10.4404 6.75 9.75 6.75Z\" fill=\"black\"/>\n    </svg>\n  );\n}\n","import {createEffect, createSignal} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport Icon from '@components/icon';\n\ntype PlaybackRateButtonProps = {\n  skin: string;\n  onMenuToggle: (open: boolean) => void;\n};\n\ntype InternalPlaybackRateButtonProps = PlaybackRateButtonProps & {\n  controlsRef: (value: PlaybackRateButtonControls) => void;\n}\n\ntype PlaybackRateButtonControls = {\n  setPlayBackRate: (value: number | ((val: number) => number)) => void;\n  changeRateByAmount: (amount: number) => void;\n  isMenuOpen: () => boolean;\n}\n\nconst rates = [0.5, 1, 1.5, 2, 3];\nconst MAX_RATE = 5;\n\nconst geometricFontMap: Record<string, Icon> = {\n  '0': 'geometric_digit_0',\n  '1': 'geometric_digit_1',\n  '2': 'geometric_digit_2',\n  '3': 'geometric_digit_3',\n  '4': 'geometric_digit_4',\n  '5': 'geometric_digit_5',\n  '6': 'geometric_digit_6',\n  '7': 'geometric_digit_7',\n  '8': 'geometric_digit_8',\n  '9': 'geometric_digit_9',\n  'x': 'geometric_letter_x',\n  '.': 'geometric_dot'\n};\n\nfunction PlaybackRateButton(props: InternalPlaybackRateButtonProps) {\n  const [selectedRate, setSelectedRate] = createSignal<number>(appMediaPlaybackController.playbackRate || 1);\n\n  const controls: PlaybackRateButtonControls = {\n    setPlayBackRate: setSelectedRate,\n    changeRateByAmount: (amount) => {\n      const newValue = selectedRate() + amount;\n      if(newValue < 1) {\n        setSelectedRate(0.5);\n      } else {\n        setSelectedRate(Math.min(MAX_RATE, Math.round(newValue - 0.01)));\n      }\n      appMediaPlaybackController.playbackRate = selectedRate();\n    },\n    isMenuOpen: () => {\n      return playbackRateButton.classList.contains('menu-open');\n    }\n  };\n\n  props.controlsRef(controls);\n\n  const buttons: ButtonMenuItemOptionsVerifiable[] = rates.map((rate) => ({\n    id: rate.toFixed(1),\n    emptyIcon: true,\n    onClick: () => {\n      appMediaPlaybackController.playbackRate = rate;\n      setSelectedRate(rate);\n    },\n    text: rate === 1 ? 'PlaybackRateNormal' : undefined,\n    regularText: rate !== 1 ? rate + 'x' : undefined\n  }));\n\n  createEffect(() => {\n    buttons.forEach((btn) => btn.icon = undefined);\n    const button = buttons.find((btn) => btn.id === selectedRate().toFixed(1));\n    if(button) button.icon = 'check';\n  });\n\n  createEffect(() => {\n    const cls = 'playback-speed-icon-floating';\n    playbackRateButton.querySelector(`.${cls}`)?.remove();\n\n    const rateAsString = selectedRate().toFixed(1).replace(/\\.0$/, 'x');\n\n    const icons = rateAsString.split('').map((char) => ({\n      char: char === '.' ? 'dot': char,\n      icon: geometricFontMap[char]\n    })).filter(Boolean);\n\n    const rateElement = document.createElement('span');\n    rateElement.classList.add(cls);\n\n    rateElement.append(...icons.map((({char, icon}) => Icon(icon, 'geometric-font-icon', `geometric-font-icon--${char}`))));\n\n    playbackRateButton.append(rateElement);\n  });\n\n  const playbackRateButton = ButtonMenuToggle({\n    icon: `mediaspeed_empty ${props.skin}__button`,\n    buttons,\n    direction: 'top-left',\n    onOpen: () => {\n      props.onMenuToggle?.(true);\n    },\n    onClose: () => {\n      props.onMenuToggle?.(false);\n    }\n  });\n\n  createEffect(() => {\n    playbackRateButton?.classList.add('checkable-button-menu', 'playback-rate-button-menu');\n  });\n\n  return <>{playbackRateButton}</>;\n}\n\nexport function createPlaybackRateButton(props: PlaybackRateButtonProps) {\n  const element = document.createElement('div');\n  let controls: PlaybackRateButtonControls;\n\n  const dispose = render(\n    () => (\n      <PlaybackRateButton\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n","import {batch, createEffect, createSignal, onCleanup, onMount, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {bindActiveWindowListener} from '@helpers/appWindow';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {IconTsx} from '@components/iconTsx';\nimport clamp from '@helpers/number/clamp';\nimport {IS_MOBILE} from '@environment/userAgent';\n\nimport {i18n} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\n\ntype SpeedDragHandlerProps = {\n  video: HTMLVideoElement;\n  onShowSpeed: () => void;\n  onHideSpeed: () => void;\n};\n\ntype InternalSpeedDragHandlerProps = SpeedDragHandlerProps & {\n  controlsRef: (value: SpeedDragHandlerControls) => void;\n};\n\ntype SpeedDragHandlerControls = {\n  isChangingSpeed: () => boolean;\n};\n\n\nconst HIDE_TIP_MOUSE_MOVE_THRESHOLD = 2;\nconst SHOW_TIP_TIMEOUT = 200;\nconst HIDE_TIP_TIMEOUT = 1500;\n\nconst SPEED_PER_PX = 1 / 100;\nconst SPEED_MULTIPLIER_WHEN_BELOW_ONE = 0.2;\nconst MAX_SPEED = 5;\nconst MIN_SPEED = 0.2;\n\n\nexport function SpeedDragHandler(props: InternalSpeedDragHandlerProps) {\n  const [currentSpeed, setCurrentSpeed] = createSignal(appMediaPlaybackController.playbackRate);\n\n  const [showSpeed, setShowSpeed] = createSignal(false);\n  const [hideSpeedTip, setHideSpeedTip] = createSignal(true);\n  const [mouseCoords, setMouseCoords] = createSignal<[number, number]>([0, 0]);\n\n  const controls: SpeedDragHandlerControls = {\n    isChangingSpeed: () => showSpeed()\n  };\n  props.controlsRef(controls);\n\n  let speedTipRef: HTMLDivElement;\n\n  const listenerSetter = new ListenerSetter();\n\n  onMount(() => {\n    let initialMousePosition: [number, number];\n    let showTimeout = 0;\n    let initialSpeed = 1;\n    let additionalSpeed = 0;\n\n    function show() {\n      const rect = props.video.getBoundingClientRect();\n\n      batch(() => {\n        setShowSpeed(true);\n        setMouseCoords([\n          initialMousePosition[0] - rect.left,\n          initialMousePosition[1] - rect.top\n        ]);\n      });\n\n      if(additionalSpeed) {\n        appMediaPlaybackController.playbackRate = Math.min(initialSpeed + additionalSpeed, MAX_SPEED);\n      }\n\n      window.setTimeout(() => {\n        if(!speedTipRef) return;\n        const speedTipRect = speedTipRef.getBoundingClientRect();\n        if(\n          speedTipRect.left < rect.left ||\n          speedTipRect.top < rect.top ||\n          speedTipRect.right > rect.right ||\n          speedTipRect.bottom > rect.bottom\n        ) {\n          setHideSpeedTip(true);\n        } else {\n          setHideSpeedTip(false);\n        }\n\n        setTimeout(() => {\n          if(!hideSpeedTip()) setHideSpeedTip(true);\n        }, HIDE_TIP_TIMEOUT);\n      }, 0);\n    }\n\n    listenerSetter.add(props.video)('pointerdown', (e) => {\n      if(props.video.paused) return;\n\n      initialMousePosition = [e.clientX, e.clientY];\n      initialSpeed = appMediaPlaybackController.playbackRate;\n\n      if(!IS_MOBILE && areSpeedsEqual(initialSpeed, 1)) {\n        additionalSpeed = 1;\n      }\n      if(IS_MOBILE) {\n        additionalSpeed = initialSpeed;\n      }\n\n      showTimeout = window.setTimeout(() => {\n        show();\n      }, SHOW_TIP_TIMEOUT);\n    });\n\n    // The drag (speed change) and release (revert) track on the WINDOW — follow whichever window the\n    // app is in (the tab, or the Document PiP window), else in the PiP the pointermove/pointerup fire\n    // on the PiP window, never arrive, and the speed neither changes on drag nor reverts on release.\n    const disposePointerMove = bindActiveWindowListener((w) => w, 'pointermove', (e) => {\n      if(!initialMousePosition || IS_MOBILE) return;\n\n      const moveX = e.clientX - initialMousePosition[0];\n\n      const startSpeed = initialSpeed + additionalSpeed;\n      const changedSpeed = moveX * SPEED_PER_PX;\n\n      let newSpeed: number;\n\n      if(startSpeed < 1) {\n        const borrowedUnits = Math.min((1 - startSpeed) / SPEED_MULTIPLIER_WHEN_BELOW_ONE, changedSpeed);\n\n        newSpeed = startSpeed +\n          borrowedUnits * SPEED_MULTIPLIER_WHEN_BELOW_ONE +\n          Math.max(0, changedSpeed - borrowedUnits);\n        //\n      } else if(startSpeed + changedSpeed < 1) {\n        newSpeed = 1 - (1 - startSpeed - changedSpeed) * SPEED_MULTIPLIER_WHEN_BELOW_ONE;\n      } else {\n        newSpeed = startSpeed + changedSpeed;\n      }\n\n      newSpeed = clamp(newSpeed, MIN_SPEED, MAX_SPEED);\n\n      if(!areSpeedsEqual(appMediaPlaybackController.playbackRate, newSpeed)) {\n        appMediaPlaybackController.playbackRate = newSpeed;\n      }\n\n      if(!initialMousePosition || hideSpeedTip()) return;\n\n      const move = Math.hypot(\n        moveX,\n        e.clientY - initialMousePosition[1]\n      );\n\n      if(move > HIDE_TIP_MOUSE_MOVE_THRESHOLD) {\n        setHideSpeedTip(true);\n        window.clearTimeout(showTimeout);\n        setShowSpeed(true);\n      };\n    });\n\n    const disposePointerUp = bindActiveWindowListener((w) => w, 'pointerup', () => {\n      if(!initialMousePosition) return;\n\n      window.clearTimeout(showTimeout);\n      batch(() => {\n        setHideSpeedTip(true);\n        setShowSpeed(false);\n        setMouseCoords([0, 0]);\n      });\n      initialMousePosition = undefined;\n\n      if(additionalSpeed) {\n        appMediaPlaybackController.playbackRate = initialSpeed;\n      }\n      additionalSpeed = 0;\n    });\n\n    listenerSetter.add(appMediaPlaybackController)('playbackParams', () => {\n      setCurrentSpeed(appMediaPlaybackController.playbackRate);\n    });\n\n    onCleanup(() => {\n      disposePointerMove();\n      disposePointerUp();\n    });\n  });\n\n  createEffect(() => {\n    if(showSpeed()) {\n      props.onShowSpeed();\n      if(props.video) {\n        props.video.dataset.startedChangingSpeed = 'true';\n        props.video.dataset.wasChangingSpeed = 'true';\n        setTimeout(() => {\n          delete props.video.dataset.startedChangingSpeed;\n        }, 100);\n      }\n\n      onCleanup(() => {\n        props.onHideSpeed();\n\n        if(props.video) {\n          setTimeout(() => {\n            delete props.video.dataset.wasChangingSpeed;\n          }, 100);\n        }\n      });\n    }\n  });\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n\n  const formattedSpeed = () => currentSpeed().toFixed(1).replace(/\\.0$/, '');\n\n  return (\n    <Show when={showSpeed()}>\n      <div\n        class=\"speed-drag-handler__speed\"\n        style={{\n          '--animation-duration-multiplier': currentSpeed()\n        }}\n      >\n        <div class=\"speed-drag-handler__speed-number\">\n          {formattedSpeed()}x\n        </div>\n        <div class=\"speed-drag-handler__speed-arrows\">\n          <SpeedArrowRight />\n          <SpeedArrowRight class=\"speed-drag-handler__speed-arrow-right-last\" />\n        </div>\n      </div>\n\n      <div\n        ref={speedTipRef}\n        class=\"speed-drag-handler__speed-tip\"\n        classList={{\n          'speed-drag-handler__speed-tip--visible': !hideSpeedTip() && !IS_MOBILE\n        }}\n        style={{\n          '--left': mouseCoords()[0] + 'px',\n          '--top': mouseCoords()[1] + 'px'\n        }}\n      >\n        <div class=\"speed-drag-handler__speed-tip-arrows\">\n          <IconTsx icon=\"arrow_prev\" />\n          <IconTsx icon=\"arrow_next\" />\n        </div>\n        <div class=\"speed-drag-handler__speed-tip-description\">\n          {i18n('PlaybackRateDragTip')}\n        </div>\n      </div>\n    </Show>\n  );\n}\n\n\nexport function createSpeedDragHandler(props: SpeedDragHandlerProps) {\n  const element = document.createElement('div');\n  let controls: SpeedDragHandlerControls;\n\n  const dispose = render(\n    () => (\n      <SpeedDragHandler\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n\nfunction areSpeedsEqual(a: number, b: number) {\n  return a.toFixed(1) === b.toFixed(1);\n}\n\nfunction SpeedArrowRight(props: {class?: string}) {\n  return (\n    <svg class={classNames('speed-drag-handler__speed-arrow-right', props.class)} width=\"8\" height=\"11\" viewBox=\"0 0 8 11\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <path opacity=\"0.7\" d=\"M0 1.5V9.5C0 10.324 0.940764 10.7944 1.6 10.3L6.93333 6.3C7.46667 5.9 7.46667 5.1 6.93333 4.7L1.6 0.7C0.940764 0.205573 0 0.675955 0 1.5Z\" fill=\"currentColor\"/>\n    </svg>\n  );\n}\n","import {Accessor, createEffect, createMemo} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport styles from './preview.module.scss';\nimport classNames from '@helpers/string/classNames';\n\nexport type StoryboardFrame = {\n  time: number, // * frame time in seconds (float)\n  top: number,\n  left: number\n};\n\nexport type Storyboard = {\n  image: HTMLImageElement,\n  frameWidth: number,\n  frameHeight: number,\n  frames: StoryboardFrame[]\n};\n\nexport type PreviewProps = {\n  storyboard: Accessor<Storyboard>,\n  visible: Accessor<boolean>,\n  time: Accessor<number>\n};\n\nfunction Preview(props: PreviewProps) {\n  createEffect<StoryboardFrame>((prevFrame) => {\n    const storyboard = props.storyboard();\n    if(!props.visible() || !storyboard) {\n      return;\n    }\n\n    const time = props.time();\n    const frame = storyboard.frames.find((frame) => time <= frame.time) ||\n      storyboard.frames[storyboard.frames.length - 1];\n    if(prevFrame === frame) {\n      return prevFrame;\n    }\n\n    const {width, height} = canvasRef;\n    const context = canvasRef.getContext('2d');\n    context.clearRect(0, 0, width, height);\n    context.drawImage(\n      storyboard.image,\n      frame.left,\n      frame.top,\n      storyboard.frameWidth,\n      storyboard.frameHeight,\n      0,\n      0,\n      width,\n      height\n    );\n\n    return frame;\n  });\n\n  let canvasRef: HTMLCanvasElement;\n  return (\n    <canvas\n      ref={canvasRef}\n      // class={classNames(styles.PreviewCanvas, props.visible() && styles.Visible)}\n      width={props.storyboard()?.frameWidth}\n      height={props.storyboard()?.frameHeight}\n      style={props.storyboard() && {\n        width: `${props.storyboard().frameWidth * 1.5}px`,\n        height: `${props.storyboard().frameHeight * 1.5}px`\n      }}\n    />\n  );\n}\n\nexport function createPreview(props: PreviewProps) {\n  const element = document.createElement('div');\n  element.classList.add(styles.Preview);\n\n  const dispose = render(\n    () => {\n      createEffect(() => {\n        element.classList.toggle('hide', !props.storyboard());\n      });\n\n      return (\n        <Preview {...props} />\n      );\n    },\n    element\n  );\n\n  return {\n    element,\n    dispose\n  };\n}\n","import appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {IS_APPLE_MOBILE, IS_MOBILE} from '@environment/userAgent';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport ListenerSetter, {Listener} from '@helpers/listenerSetter';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport ControlsHover from '@helpers/dom/controlsHover';\nimport {addFullScreenListener, cancelFullScreen, getFullScreenElement, isFullScreen, requestFullScreen} from '@helpers/dom/fullScreen';\nimport {isClientPipOpen} from '@components/clientPip';\nimport {toastNew} from '@components/toast';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport MediaProgressLine from '@components/mediaProgressLine';\nimport VolumeSelector from '@components/volumeSelector';\nimport debounce from '@helpers/schedulers/debounce';\nimport overlayCounter from '@helpers/overlayCounter';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport safePlay from '@helpers/dom/safePlay';\nimport ButtonIcon from '@components/buttonIcon';\nimport Button from '@components/button';\nimport Icon from '@components/icon';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport {i18n} from '@lib/langPack';\nimport {numberThousandSplitterForWatching} from '@helpers/number/numberThousandSplitter';\nimport createCanvasStream from '@helpers/canvas/createCanvasStream';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {VideoTimestamp} from '@components/appMediaViewerBase';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {Accessor, createSignal, Setter} from 'solid-js';\n\nimport {createQualityLevelsSwitchButton} from './qualityLevelsSwitchButton';\nimport {createPlaybackRateButton} from './playbackRateButton';\nimport {createSpeedDragHandler} from './speedDragHandler';\nimport {createPreview} from './preview';\n\n\nexport default class VideoPlayer extends ControlsHover {\n  public video: HTMLVideoElement;\n  protected wrapper: HTMLElement;\n  protected progress: MediaProgressLine;\n  protected skin: 'default';\n  protected live: boolean;\n\n  protected listenerSetter: ListenerSetter;\n\n  protected playbackRateButton: ReturnType<typeof createPlaybackRateButton>;\n  protected speedDragHandler: ReturnType<typeof createSpeedDragHandler>;\n  protected qualityLevelsButton: ReturnType<typeof createQualityLevelsSwitchButton>;\n  protected preview: ReturnType<typeof createPreview>;\n\n  protected pipButton: HTMLElement;\n  protected liveMenuButton: HTMLElement;\n  protected toggles: HTMLElement[];\n  protected mainToggle: HTMLElement;\n  protected controls: HTMLElement;\n  protected gradient: HTMLElement;\n  public liveEl: HTMLElement;\n\n  /* protected videoParent: HTMLElement;\n  protected videoWhichChild: number; */\n\n  protected onMenuToggle?: (open: boolean) => void;\n  // Fired while the seek-bar time preview (.media-progress-line__current-time-info)\n  // is shown/hidden, so the host can hide chrome that would stack with it (caption).\n  protected onTimePreviewToggle?: (visible: boolean) => void;\n  protected onPip?: (pip: boolean) => void;\n  protected onPipClose?: () => void;\n  protected onVolumeChange: VolumeSelector['onVolumeChange'];\n  protected onFullScreen: (active: boolean) => void;\n  protected onFullScreenToPip: () => void;\n\n  protected canPause: boolean;\n  protected canSeek: boolean;\n\n  protected _inPip = false;\n\n  protected _width: number;\n  protected _height: number;\n\n  protected emptyPipVideo: HTMLVideoElement;\n  protected debouncedPip: (pip: boolean) => void;\n  protected debouncePipTime: number;\n  public emptyPipVideoSource: CanvasImageSource;\n\n  protected listenKeyboardEvents: 'always' | 'fullscreen';\n  protected hadContainer: boolean;\n  protected useGlobalVolume: VolumeSelector['useGlobalVolume'];\n  public volumeSelector: VolumeSelector;\n  protected isPlaying: boolean;\n  protected shouldEnableSoundOnClick: () => boolean;\n\n  protected previewParams: Parameters<typeof createPreview>[0];\n  protected previewVisible: Accessor<boolean>;\n  protected previewSetVisible: Setter<boolean>;\n  protected previewTime: Accessor<number>;\n  protected previewSetTime: Setter<number>;\n\n  constructor({\n    video,\n    container,\n    play = false,\n    streamable = false,\n    duration,\n    live,\n    width,\n    height,\n    videoTimestamps,\n    onMenuToggle,\n    onTimePreviewToggle,\n    onPip,\n    onPipClose,\n    listenKeyboardEvents,\n    useGlobalVolume,\n    onVolumeChange,\n    onFullScreen,\n    onFullScreenToPip,\n    shouldEnableSoundOnClick,\n    storyboard\n  }: {\n    video: HTMLVideoElement,\n    container?: HTMLElement,\n    play?: boolean,\n    streamable?: boolean,\n    duration?: number,\n    live?: boolean,\n    width?: number,\n    height?: number,\n    videoTimestamps?: VideoTimestamp[],\n    onMenuToggle?: VideoPlayer['onMenuToggle'],\n    onTimePreviewToggle?: VideoPlayer['onTimePreviewToggle'],\n    onPip?: VideoPlayer['onPip'],\n    onPipClose?: VideoPlayer['onPipClose'],\n    listenKeyboardEvents?: VideoPlayer['listenKeyboardEvents'],\n    useGlobalVolume?: VolumeSelector['useGlobalVolume'],\n    onVolumeChange?: VideoPlayer['onVolumeChange'],\n    onFullScreen?: (active: boolean) => void,\n    onFullScreenToPip?: VideoPlayer['onFullScreenToPip'],\n    shouldEnableSoundOnClick?: VideoPlayer['shouldEnableSoundOnClick'],\n    storyboard?: Parameters<typeof createPreview>[0]['storyboard']\n  }) {\n    super();\n\n    this.video = video;\n    this.video.classList.add('ckin__video');\n    this.wrapper = container ?? document.createElement('div');\n    this.wrapper.classList.add('ckin__player');\n    this.live = live;\n    this.canPause = !live;\n    this.canSeek = !live;\n    this._width = width;\n    this._height = height;\n\n    this.onMenuToggle = onMenuToggle;\n    this.onTimePreviewToggle = onTimePreviewToggle;\n    this.onPip = onPip;\n    this.onPipClose = onPipClose;\n    this.onVolumeChange = onVolumeChange;\n    this.onFullScreen = onFullScreen;\n    this.onFullScreenToPip = onFullScreenToPip;\n\n    this.listenKeyboardEvents = listenKeyboardEvents;\n    this.hadContainer = !!container;\n    this.useGlobalVolume = useGlobalVolume;\n    this.shouldEnableSoundOnClick = shouldEnableSoundOnClick;\n\n    if(storyboard) {\n      [this.previewVisible, this.previewSetVisible] = createSignal(false);\n      [this.previewTime, this.previewSetTime] = createSignal(0);\n      this.previewParams = {\n        storyboard,\n        visible: this.previewVisible,\n        time: this.previewTime\n      };\n    }\n\n    this.video.playbackRate = appMediaPlaybackController.playbackRate;\n\n    this.listenerSetter = new ListenerSetter();\n\n    this.setup({\n      element: this.wrapper,\n      listenerSetter: this.listenerSetter,\n      canHideControls: () => {\n        if(this.video.paused) return false;\n        if(this.playbackRateButton?.controls.isMenuOpen()) return false;\n        if(this.qualityLevelsButton?.controls.isMenuOpen()) return false;\n\n        return true;\n      },\n      canShowControls: () => {\n        if(this.speedDragHandler?.controls.isChangingSpeed()) return false;\n        return true;\n      },\n      showOnLeaveToClassName: ['media-viewer-caption', 'media-viewer-topbar'],\n      ignoreClickClassName: 'ckin__controls'\n    });\n\n    if(!this.hadContainer) {\n      video.parentNode.insertBefore(this.wrapper, video);\n      this.wrapper.appendChild(video);\n    }\n\n    this.skin = 'default';\n\n    this.stylePlayer(duration);\n\n    if(this.skin === 'default' && !live) {\n      const controls = this.controls = this.wrapper.querySelector('.default__controls.ckin__controls') as HTMLDivElement;\n      this.gradient = this.controls.previousElementSibling as HTMLElement;\n\n      if(this.previewParams) {\n        this.preview = createPreview(this.previewParams);\n      }\n\n      const debouncedToggleControls = debounce((show: boolean) => {\n        this.wrapper.classList.toggle('show-time', show);\n      }, 200, false, true);\n\n      this.addEventListener('toggleControls', debouncedToggleControls);\n\n      this.progress = new MediaProgressLine({\n        videoTimestamps,\n        withTime: true,\n        appendToTimeElement: this.preview?.element,\n        onSeekStart: () => {\n          this.wrapper.classList.add('is-seeking');\n        },\n        onSeekEnd: () => {\n          this.wrapper.classList.remove('is-seeking');\n        },\n        onHover: (value) => {\n          if(this.previewParams) {\n            this.previewSetTime(value * this.video.duration);\n            this.previewSetVisible(true);\n          }\n          this.onTimePreviewToggle?.(true);\n        },\n        onPointerOut: () => {\n          if(this.previewParams) {\n            this.previewSetVisible(false);\n          }\n          this.onTimePreviewToggle?.(false);\n        }\n      });\n      this.progress.setMedia({\n        media: video,\n        streamable,\n        duration\n      });\n      controls.prepend(this.progress.container);\n    }\n\n    if(play/*  && video.paused */) {\n      video.play().catch((err: Error) => {\n        if(err.name === 'NotAllowedError') {\n          video.muted = true;\n          video.autoplay = true;\n          safePlay(video);\n        }\n      }).finally(() => { // due to autoplay, play will not call\n        this.setIsPlaying(!this.video.paused);\n      });\n    } else {\n      this.setIsPlaying(!this.video.paused);\n    }\n  }\n\n  public get width() {\n    return this.video.videoWidth || this._width;\n  }\n\n  public get height() {\n    return this.video.videoHeight || this._height;\n  }\n\n  private setIsPlaying(isPlaying: boolean) {\n    if(this.isPlaying === isPlaying) {\n      return;\n    }\n\n    this.isPlaying = isPlaying;\n\n    this.toggleActivity(isPlaying);\n\n    if(this.live && !isPlaying) {\n      return;\n    }\n\n    this.wrapper.classList.toggle('is-playing', isPlaying);\n    this.toggles.forEach((toggle) => {\n      toggle.replaceChildren(Icon(isPlaying ? 'pause' : 'play'));\n    });\n  }\n\n  private stylePlayer(initDuration: number) {\n    const {wrapper, video, skin, listenerSetter, live} = this;\n\n    wrapper.classList.add(skin);\n    if(live) wrapper.classList.add(`${skin}-live`);\n\n    const html = this.buildControls();\n    wrapper.insertAdjacentHTML('beforeend', html);\n    let timeDuration: HTMLElement;\n\n    const onPlayCallbacks: (() => void)[] = [], onPauseCallbacks: (() => void)[] = [];\n    if(skin === 'default') {\n      if(this.canPause) {\n        const mainToggle = this.mainToggle = Button(`${skin}__button--big toggle`, {noRipple: true, icon: 'play'});\n        wrapper.firstElementChild.after(mainToggle);\n      }\n\n      const leftControls = wrapper.querySelector('.left-controls') as HTMLElement;\n      if(live) {\n        this.toggles = [];\n      } else {\n        const leftToggle = ButtonIcon(` ${skin}__button toggle`, {noRipple: true});\n        leftControls.prepend(leftToggle);\n        this.toggles = [leftToggle];\n      }\n\n      const rightControls = wrapper.querySelector('.right-controls') as HTMLElement;\n      if(!live) {\n        this.playbackRateButton = createPlaybackRateButton({skin: this.skin, onMenuToggle: this.onMenuToggle});\n      }\n      if(!IS_MOBILE && document.pictureInPictureEnabled) {\n        this.pipButton = ButtonIcon(`pip ${skin}__button`, {noRipple: true});\n      }\n      const fullScreenButton = ButtonIcon(` ${skin}__button`, {noRipple: true});\n\n      rightControls.append(...[\n        this.playbackRateButton?.element,\n        this.createQualityLevelsButton(),\n        this.pipButton,\n        fullScreenButton\n      ].filter(Boolean));\n\n      const timeElapsed = wrapper.querySelector('.ckin__time-elapsed');\n      timeDuration = wrapper.querySelector('.ckin__time-duration') as HTMLElement;\n\n      const volumeSelector = this.volumeSelector = new VolumeSelector({\n        listenerSetter,\n        vertical: false,\n        media: video,\n        useGlobalVolume: this.useGlobalVolume,\n        onVolumeChange: this.onVolumeChange\n      });\n\n      volumeSelector.btn.classList.remove('btn-icon');\n      if(timeElapsed) {\n        timeElapsed.parentElement.before(volumeSelector.btn);\n      } else {\n        leftControls.lastElementChild.before(volumeSelector.btn);\n      }\n\n      this.toggles.forEach((button) => {\n        attachClickEvent(button, () => {\n          this.togglePlay();\n        }, {listenerSetter: this.listenerSetter});\n      });\n\n      if(this.pipButton) {\n        attachClickEvent(this.pipButton, this.requestPictureInPicture, {listenerSetter: this.listenerSetter});\n\n        this.debouncePipTime = 20;\n        this.debouncedPip = debounce(this._onPip, this.debouncePipTime, false, true);\n\n        this.addPipListeners(video);\n      }\n\n      if(!IS_TOUCH_SUPPORTED) {\n        if(this.canPause) {\n          attachClickEvent(video, () => {\n            if(this.checkInteraction() || video.dataset.wasChangingSpeed) {\n              return;\n            }\n\n            this.togglePlay();\n          }, {listenerSetter: this.listenerSetter});\n        }\n\n        if(this.listenKeyboardEvents) listenerSetter.add(getAppWindow().document)('keydown', (e: KeyboardEvent) => {\n          if(\n            overlayCounter.overlaysActive > 1 ||\n            getAppWindow().document.pictureInPictureElement === video ||\n            (this.listenKeyboardEvents === 'fullscreen' && !this.isFullScreen())\n          ) { // forward popup is active, etc\n            return;\n          }\n\n          const {key, code} = e;\n\n          let good = true;\n          if(code === 'KeyF') {\n            this.toggleFullScreen();\n          } else if(code === 'KeyM') {\n            appMediaPlaybackController.muted = !appMediaPlaybackController.muted;\n          } else if(code === 'Space' && this.canPause) {\n            this.togglePlay();\n          } else if(e.altKey && (code === 'Equal' || code === 'Minus') && this.canSeek) {\n            const add = code === 'Equal' ? 1 : -1;\n            this.playbackRateButton.controls.changeRateByAmount(add);\n          } else if(wrapper.classList.contains('ckin__fullscreen') && (key === 'ArrowLeft' || key === 'ArrowRight') && this.canSeek) {\n            if(key === 'ArrowLeft') appMediaPlaybackController.seekBackward({action: 'seekbackward'});\n            else appMediaPlaybackController.seekForward({action: 'seekforward'});\n          } else {\n            good = false;\n          }\n\n          if(good) {\n            cancelEvent(e);\n            return false;\n          }\n        });\n      }\n\n      if(this.canPause) {\n        this.speedDragHandler = createSpeedDragHandler({\n          video: this.video,\n          onShowSpeed: () => {\n            this.hideControls();\n          },\n          onHideSpeed: () => {\n            this.showControls();\n          }\n        });\n        this.wrapper.append(this.speedDragHandler.element);\n\n        listenerSetter.add(video)('contextmenu', (e) => {\n          e.preventDefault();\n        });\n      }\n\n      listenerSetter.add(video)('dblclick', () => {\n        if(!IS_TOUCH_SUPPORTED) {\n          this.toggleFullScreen();\n        }\n      });\n\n      attachClickEvent(fullScreenButton, () => {\n        this.toggleFullScreen();\n      }, {listenerSetter: this.listenerSetter});\n\n      addFullScreenListener(wrapper, () => this._onFullScreen(fullScreenButton), listenerSetter);\n      this._onFullScreen(fullScreenButton, true);\n\n      if(timeElapsed) {\n        listenerSetter.add(video)('timeupdate', () => {\n          if(!video.paused && !this.isPlaying) {\n            console.warn('video: fixing missing play event');\n            simulateEvent(video, 'play');\n          }\n\n          timeElapsed.textContent = toHHMMSS(video.currentTime | 0);\n        });\n      }\n\n      const onPlay = () => {\n        wrapper.classList.add('played');\n\n        if(!IS_TOUCH_SUPPORTED && !live) {\n          onPlayCallbacks.push(() => {\n            this.hideControls(true);\n          });\n        }\n\n        indexOfAndSplice(onPlayCallbacks, onPlay);\n      };\n\n      if(this.hadContainer) {\n        onPlay();\n      }\n\n      onPlayCallbacks.push(onPlay);\n      onPauseCallbacks.push(() => {\n        this.showControls(false);\n      });\n\n      listenerSetter.add(appMediaPlaybackController)('playbackParams', () => {\n        if(this.video.dataset.startedChangingSpeed) return;\n        this.playbackRateButton.controls.setPlayBackRate(appMediaPlaybackController.playbackRate);\n      });\n\n      if(live) {\n        this.liveEl = i18n('Rtmp.MediaViewer.Live');\n        this.liveEl.classList.add('controls-live');\n        leftControls.prepend(this.liveEl);\n      }\n    }\n\n    listenerSetter.add(video)('play', () => {\n      this.setIsPlaying(true);\n      onPlayCallbacks.forEach((cb) => cb());\n    });\n\n    listenerSetter.add(video)('pause', () => {\n      this.setIsPlaying(false);\n      onPauseCallbacks.forEach((cb) => cb());\n    });\n\n    if(timeDuration) {\n      if(video.duration || initDuration) {\n        timeDuration.textContent = toHHMMSS(Math.round(video.duration || initDuration));\n      } else {\n        onMediaLoad(video).then(() => {\n          timeDuration.textContent = toHHMMSS(Math.round(video.duration));\n        });\n      }\n    }\n  }\n\n  private createQualityLevelsButton() {\n    this.qualityLevelsButton = createQualityLevelsSwitchButton({skin: this.skin, video: this.video, onMenuToggle: this.onMenuToggle});\n\n    return this.qualityLevelsButton.element;\n  }\n\n  public async loadQualityLevels() {\n    this.qualityLevelsButton?.controls.loadQualityLevels();\n  }\n\n  protected checkInteraction() {\n    if(this.shouldEnableSoundOnClick?.()) {\n      this.volumeSelector.setVolume({volume: 1, muted: false});\n      return true;\n    }\n\n    return false;\n  }\n\n  protected _onPip = (pip: boolean) => {\n    this._inPip = pip;\n    this.wrapper.style.visibility = pip ? 'hidden': '';\n    this.onPip?.(pip);\n  };\n\n  protected onEnterPictureInPictureLeave = (e: Event) => {\n    const onPause = () => {\n      clearTimeout(timeout);\n      this.onPipClose?.();\n    };\n    const listener = this.listenerSetter.add(e.target)('pause', onPause, {once: true}) as any as Listener;\n    const timeout = setTimeout(() => {\n      this.listenerSetter.remove(listener);\n    }, this.debouncePipTime);\n  };\n\n  protected onEnterPictureInPicture = (e: Event) => {\n    this.debouncedPip(true);\n    this.listenerSetter.add(e.target)('leavepictureinpicture', this.onEnterPictureInPictureLeave, {once: true});\n  };\n\n  protected onLeavePictureInPicture = () => {\n    this.debouncedPip(false);\n  };\n\n  protected addPipListeners(video: HTMLVideoElement) {\n    this.listenerSetter.add(video)('enterpictureinpicture', this.onEnterPictureInPicture);\n    this.listenerSetter.add(video)('leavepictureinpicture', this.onLeavePictureInPicture);\n  }\n\n  public requestPictureInPicture = async() => {\n    if(this.video.duration) {\n      if(this.isFullScreen()) {\n        this.onFullScreenToPip?.();\n      }\n\n      this.video.requestPictureInPicture();\n      this.checkInteraction();\n      return;\n    }\n\n    if(!this.emptyPipVideo) {\n      const {width, height} = this;\n      this.emptyPipVideo = document.createElement('video');\n      this.emptyPipVideo.autoplay = true;\n      this.emptyPipVideo.muted = true;\n      this.emptyPipVideo.playsInline = true;\n      this.emptyPipVideo.style.position = 'absolute';\n      this.emptyPipVideo.style.visibility = 'hidden';\n      getOverlayRoot().prepend(this.emptyPipVideo);\n      this.emptyPipVideo.srcObject = createCanvasStream({width, height, image: this.emptyPipVideoSource});\n      this.addPipListeners(this.emptyPipVideo);\n    }\n\n    await onMediaLoad(this.emptyPipVideo);\n    this.emptyPipVideo.requestPictureInPicture();\n\n    onMediaLoad(this.video).then(() => {\n      if(getAppWindow().document.pictureInPictureElement === this.emptyPipVideo) {\n        getAppWindow().document.exitPictureInPicture();\n        this.video.requestPictureInPicture();\n      }\n    });\n  };\n\n  protected togglePlay(isPaused = this.video.paused) {\n    this.video[isPaused ? 'play' : 'pause']();\n  }\n\n  private buildControls() {\n    const skin = this.skin;\n\n    if(skin === 'default') {\n      const time = this.live ? `\n      <span class=\"left-controls-watching\"></span>\n      ` : `\n      <time class=\"ckin__time-elapsed\">0:00</time>\n      <span> / </span>\n      <time class=\"ckin__time-duration\">0:00</time>\n      `\n\n      return `\n      <div class=\"${skin}__gradient-bottom ckin__controls\"></div>\n      <div class=\"${skin}__controls ckin__controls\">\n        <div class=\"bottom-controls night\">\n          <div class=\"left-controls\">\n            <div class=\"ckin__time\">\n              ${time}\n            </div>\n          </div>\n          <div class=\"right-controls\"></div>\n        </div>\n      </div>`;\n    }\n  }\n\n  public cancelFullScreen() {\n    if(getFullScreenElement() === this.wrapper) {\n      this.toggleFullScreen();\n    }\n  }\n\n  protected toggleFullScreen() {\n    const player = this.wrapper;\n\n    // * https://caniuse.com/#feat=fullscreen\n    if(IS_APPLE_MOBILE) {\n      const video = this.video as any;\n      video.webkitEnterFullscreen();\n      video.enterFullscreen();\n      return;\n    }\n\n    if(!isFullScreen()) {\n      /* const videoParent = this.video.parentElement;\n      const videoWhichChild = whichChild(this.video);\n      const needVideoRemount = videoParent !== player;\n\n      if(needVideoRemount) {\n        this.videoParent = videoParent;\n        this.videoWhichChild = videoWhichChild;\n        player.prepend(this.video);\n      } */\n\n      // Fullscreen genuinely can't be entered while the client is popped into a Document PiP window:\n      // the Fullscreen API is disabled there by spec, AND Chrome won't carry the click's user-activation\n      // from the PiP window over to the tab — so there's no single gesture that can fullscreen the tab's\n      // video either. Rather than silently fail (or close PiP with nothing to show for it), tell the user\n      // to return to the tab first. Outside PiP this branch is a no-op.\n      if(isClientPipOpen()) {\n        toastNew({langPackKey: 'ClientPip.FullscreenHint'});\n        return;\n      }\n\n      requestFullScreen(player);\n      this.checkInteraction();\n    } else {\n      /* if(this.videoParent) {\n        const {videoWhichChild, videoParent} = this;\n        if(!videoWhichChild) {\n          videoParent.prepend(this.video);\n        } else {\n          videoParent.insertBefore(this.video, videoParent.children[videoWhichChild]);\n        }\n\n        this.videoParent = null;\n        this.videoWhichChild = -1;\n      } */\n\n      cancelFullScreen();\n    }\n  }\n\n  private toggleActivity(active: boolean) {\n    apiManagerProxy.invokeVoid('toggleUninteruptableActivity', {\n      activity: 'UsingVideoPlayer',\n      active\n    });\n  }\n\n  public isFullScreen() {\n    return isFullScreen();\n  }\n\n  protected _onFullScreen(fullScreenButton: HTMLElement, noEvent?: boolean) {\n    const isFull = isFullScreen();\n    this.wrapper.classList.toggle('ckin__fullscreen', isFull);\n    if(!isFull) {\n      fullScreenButton.replaceChildren(Icon('fullscreen'));\n      fullScreenButton.setAttribute('title', 'Full Screen');\n    } else {\n      fullScreenButton.replaceChildren(Icon('smallscreen'));\n      fullScreenButton.setAttribute('title', 'Exit Full Screen');\n    }\n\n    !noEvent && this.onFullScreen?.(isFull);\n  }\n\n  public dimBackground() {\n    this.wrapper.classList.add('dim-background');\n  }\n\n  public setTimestamp(timestamp: number) {\n    setCurrentTime(this.video, timestamp);\n    this.togglePlay(true);\n  }\n\n  public cleanup() {\n    super.cleanup();\n    this.listenerSetter.removeAll();\n    this.progress?.removeListeners();\n    this.volumeSelector?.removeListeners();\n    this.qualityLevelsButton?.dispose();\n    this.playbackRateButton?.dispose();\n    this.speedDragHandler?.dispose();\n    this.preview?.dispose();\n    this.onMenuToggle =\n      this.onTimePreviewToggle =\n      this.onPip =\n      this.onVolumeChange =\n      this.onFullScreen =\n      this.onFullScreenToPip =\n      this.shouldEnableSoundOnClick =\n      undefined;\n\n    this.progress?.cleanup();\n\n    this.toggleActivity(false);\n  }\n\n  public unmount() {\n    [this.mainToggle, this.gradient, this.controls].forEach((element) => {\n      element.remove();\n    });\n  }\n\n  public setupLiveMenu(buttons: ButtonMenuItemOptionsVerifiable[]) {\n    this.liveMenuButton = ButtonMenuToggle({\n      direction: 'top-left',\n      buttons: buttons,\n      buttonOptions: {\n        noRipple: true\n      }\n    });\n    this.wrapper.querySelector('.right-controls').prepend(this.liveMenuButton);\n  }\n\n  public updateLiveViewersCount(count: number) {\n    this.wrapper.querySelector('.left-controls-watching').replaceChildren(i18n('Rtmp.Watching', [numberThousandSplitterForWatching(Math.max(1, count))]));\n  }\n\n  get inPip() {\n    return this._inPip;\n  }\n}\n","// * zoom part from WebZ\n// * https://github.com/Ajaxy/telegram-tt/blob/069f4f5b2f2c7c22529ccced876842e7f9cb81f4/src/util/captureEvents.ts\n\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport safeAssign from '@helpers/object/safeAssign';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {Middleware} from '@helpers/middleware';\nimport ListenerSetter, {Listener, ListenerOptions} from '@helpers/listenerSetter';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport pause from '@helpers/schedulers/pause';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport clamp from '@helpers/number/clamp';\nimport debounce from '@helpers/schedulers/debounce';\nimport {logger} from '@lib/logger';\nimport isSwipingBackSafari from '@helpers/dom/isSwipingBackSafari';\nimport windowSize from '@helpers/windowSize';\n\ntype E = {\n  clientX: number,\n  clientY: number,\n  target: EventTarget,\n  button?: number,\n  type?: string\n};\n\ntype EE = E | (Exclude<E, 'clientX' | 'clientY'> & {\n  touches: E[]\n});\n\nexport const getEvent = (e: EE) => {\n  return 'touches' in e ? e.touches[0] : e;\n};\n\nfunction getDistance(a: Touch, b?: Touch) {\n  if(!b) return 0;\n  return Math.hypot((b.pageX - a.pageX), (b.pageY - a.pageY));\n}\n\nfunction getTouchCenter(a: Touch, b: Touch) {\n  return {\n    x: (a.pageX + b.pageX) / 2,\n    y: (a.pageY + b.pageY) / 2\n  };\n}\n\n// The swipe move/end track on the swiped element's OWN document (`this.element.ownerDocument`) rather\n// than a fixed main-`document` ref: while the client is popped into a Document PiP window the element\n// (stories viewer, media-viewer pan, reorder, …) lives there, so a main-document listener never sees\n// the gesture and the swipe sticks. Equals `document` when not popped out, so behaviour is unchanged.\nlet RESET_GLOBAL = false;\ncontextMenuController.addEventListener('toggle', (visible) => {\n  RESET_GLOBAL = visible;\n});\n\nexport type SwipeHandlerOptions = {\n  element: SwipeHandler['element'],\n  onSwipe: SwipeHandler['onSwipe'],\n  verifyTouchTarget?: SwipeHandler['verifyTouchTarget'],\n  onFirstSwipe?: SwipeHandler['onFirstSwipe'],\n  onReset?: SwipeHandler['onReset'],\n  onStart?: SwipeHandler['onStart'],\n  onZoom?: SwipeHandler['onZoom'],\n  onDrag?: SwipeHandler['onDrag'],\n  onDoubleClick?: SwipeHandler['onDoubleClick'],\n  cursor?: SwipeHandler['cursor'],\n  cancelEvent?: SwipeHandler['cancelEvent'],\n  listenerOptions?: SwipeHandler['listenerOptions'],\n  setCursorTo?: HTMLElement,\n  middleware?: Middleware,\n  withDelay?: boolean,\n  minZoom?: number,\n  maxZoom?: number\n};\n\nconst TOUCH_MOVE_OPTIONS: ListenerOptions = {passive: false};\nconst MOUSE_MOVE_OPTIONS: ListenerOptions = false as any;\nconst WHEEL_OPTIONS: ListenerOptions = {capture: true, passive: false};\n\nexport type ZoomDetails = {\n  zoom?: number;\n  zoomFactor?: number;\n  zoomAdd?: number;\n  initialCenterX: number;\n  initialCenterY: number;\n  dragOffsetX: number;\n  dragOffsetY: number;\n  currentCenterX: number;\n  currentCenterY: number;\n};\n\nexport default class SwipeHandler {\n  private element: HTMLElement;\n  private onSwipe: (xDiff: number, yDiff: number, e: EE, cancelDrag?: (x: boolean, y: boolean) => void) => boolean | void;\n  private verifyTouchTarget: (evt: EE) => boolean | Promise<boolean>;\n  private onFirstSwipe: (e: EE) => void;\n  private onReset: (e?: Event) => void;\n  private onStart: () => void;\n  private onZoom: (details: ZoomDetails) => void;\n  private onDrag: (e: EE, captureEvent: E, details: {dragOffsetX: number, dragOffsetY: number}, cancelDrag: (x: boolean, y: boolean) => void) => void;\n  private onDoubleClick: (details: {centerX: number, centerY: number}) => void;\n  private cursor: 'grabbing' | 'move' | 'row-resize' | 'col-resize' | 'nesw-resize' | 'nwse-resize' | 'ne-resize' | 'se-resize' | 'sw-resize' | 'nw-resize' | 'n-resize' | 'e-resize' | 's-resize' | 'w-resize' | '';\n  private cancelEvent: boolean;\n  private listenerOptions: ListenerOptions;\n  private setCursorTo: HTMLElement;\n\n  private isMouseDown: boolean;\n  private tempId: number;\n  private endListener: Listener;\n\n  private hadMove: boolean;\n  private eventUp: E;\n  private xDown: number;\n  private yDown: number;\n  private xAdded: number;\n  private yAdded: number;\n\n  private withDelay: boolean;\n  private listenerSetter: ListenerSetter;\n\n  private initialDistance: number;\n  private initialTouchCenter: ReturnType<typeof getTouchCenter>;\n  private initialDragOffset: {x: number, y: number};\n  private isDragCanceled: {x: boolean, y: boolean};\n  private wheelZoom: number;\n  private releaseWheelDrag: ReturnType<typeof debounce<(e: Event) => void>>;\n  private releaseWheelZoom: ReturnType<typeof debounce<(e: Event) => void>>;\n\n  private log: ReturnType<typeof logger>;\n\n  constructor(options: SwipeHandlerOptions) {\n    safeAssign(this, options);\n\n    this.log = logger('SWIPE-HANDLER');\n    this.cursor ??= 'grabbing';\n    this.cancelEvent ??= true;\n    // this.listenerOptions ??= false as any;\n    this.listenerOptions ??= TOUCH_MOVE_OPTIONS;\n\n    this.setCursorTo ??= this.element;\n    this.listenerSetter = new ListenerSetter();\n    this.setListeners();\n\n    this.resetValues();\n    this.tempId = 0;\n\n    options.middleware?.onDestroy(() => {\n      this.reset();\n      this.removeListeners();\n    });\n\n    this.releaseWheelDrag = debounce(this.reset, 150, false);\n    this.releaseWheelZoom = debounce(this.reset, 150, false);\n  }\n\n  public setListeners() {\n    if(!IS_TOUCH_SUPPORTED) {\n      // @ts-ignore\n      this.listenerSetter.add(this.element)('mousedown', this.handleStart, this.listenerOptions);\n      // The gesture-end listener (`mouseup`/`touchend`) is bound lazily in `handleStart` — see the\n      // note there — not here, so its target document is resolved while the element is live.\n\n      if(this.onZoom || this.onDoubleClick) {\n        this.listenerSetter.add(this.element)('wheel', this.handleWheel, WHEEL_OPTIONS);\n      }\n    } else {\n      if(this.withDelay) {\n        attachContextMenuListener({\n          element: this.element,\n          callback: (e) => {\n            cancelEvent(e);\n            // @ts-ignore\n            this.handleStart(e);\n          },\n          listenerSetter: this.listenerSetter,\n          listenerOptions: this.listenerOptions\n        });\n      } else {\n        // @ts-ignore\n        this.listenerSetter.add(this.element)('touchstart', this.handleStart, this.listenerOptions);\n      }\n\n      if(this.onDoubleClick) {\n        this.listenerSetter.add(this.element)('dblclick', (e) => {\n          this.onDoubleClick({centerX: e.pageX, centerY: e.pageY});\n        });\n      }\n\n      // `touchend` is bound lazily in `handleStart` (see the note there), not here.\n    }\n  }\n\n  public removeListeners() {\n    this.log('remove listeners');\n    this.reset();\n    this.listenerSetter.removeAll();\n  }\n\n  public setCursor(cursor: SwipeHandler['cursor'] = '') {\n    this.cursor = cursor;\n\n    if(!IS_TOUCH_SUPPORTED && this.hadMove) {\n      this.setCursorTo.style.setProperty('cursor', this.cursor, 'important');\n    }\n  }\n\n  public add(x: number, y: number) {\n    this.xAdded = x;\n    this.yAdded = y;\n    this.handleMove({\n      clientX: this.eventUp.clientX,\n      clientY: this.eventUp.clientY,\n      target: this.eventUp.target\n    });\n  }\n\n  protected resetValues() {\n    ++this.tempId;\n    this.hadMove = false;\n    this.xAdded = this.yAdded = 0;\n    this.xDown =\n      this.yDown =\n      this.eventUp =\n      this.isMouseDown =\n      undefined;\n\n    if(this.onZoom) {\n      this.initialDistance = 0;\n      this.initialTouchCenter = {\n        x: windowSize.width / 2,\n        y: windowSize.height / 2\n      };\n      this.initialDragOffset = {x: 0, y: 0};\n      this.isDragCanceled = {x: false, y: false};\n      this.wheelZoom = 1;\n    }\n  }\n\n  public reset = (e?: Event) => {\n    this.log('reset');\n    /* if(e) {\n      cancelEvent(e);\n    } */\n\n    if(IS_TOUCH_SUPPORTED) {\n      this.listenerSetter.removeManual(this.element.ownerDocument, 'touchmove', this.handleMove, TOUCH_MOVE_OPTIONS);\n    } else {\n      this.listenerSetter.removeManual(this.element.ownerDocument, 'mousemove', this.handleMove, MOUSE_MOVE_OPTIONS);\n      this.setCursorTo.style.cursor = '';\n    }\n\n    if(this.endListener) {\n      this.listenerSetter.remove(this.endListener);\n      this.endListener = undefined;\n    }\n\n    if(this.hadMove) {\n      this.onReset?.(e);\n    }\n\n    this.releaseWheelDrag?.clearTimeout();\n    this.releaseWheelZoom?.clearTimeout();\n\n    this.resetValues();\n  };\n\n  protected setHadMove(_e: EE) {\n    if(!this.hadMove) {\n      this.log('had move');\n      this.hadMove = true;\n      this.setCursorTo.style.setProperty('cursor', this.cursor, 'important');\n      this.onFirstSwipe?.(_e);\n    }\n  }\n\n  protected dispatchOnSwipe(...args: Parameters<SwipeHandlerOptions['onSwipe']>) {\n    const onSwipeResult = this.onSwipe(...args);\n    if(onSwipeResult !== undefined && onSwipeResult) {\n      this.reset();\n    }\n  }\n\n  protected handleStart = async(_e: EE) => {\n    this.log('start');\n\n    if(this.isMouseDown) {\n      const touches = (_e as any as TouchEvent).touches;\n      if(touches?.length === 2) {\n        this.initialDistance = getDistance(touches[0], touches[1]);\n        this.initialTouchCenter = getTouchCenter(touches[0], touches[1]);\n      }\n\n      return;\n    }\n\n    const e = getEvent(_e);\n    if(![0, 1].includes(Math.max(0, e.button ?? 0))) {\n      return;\n    }\n\n    if(e.button === 1) {\n      cancelEvent(_e as any);\n    }\n\n    if(isSwipingBackSafari(_e as any)) {\n      return;\n    }\n\n    const tempId = ++this.tempId;\n\n    // Bind the gesture-end listener to the element's CURRENT document now — while the element is live\n    // in the DOM — rather than at construction. A JSX element cloned from a <template> is initially\n    // owned by the inert template-contents document (about:blank); binding `mouseup`/`touchend` to\n    // that document at construction means the real release event (which fires on the main — or\n    // Document-PiP — document the element actually lives in) is never seen, so the gesture would pause\n    // on press but never resume on release. Resolving `ownerDocument` here keeps PiP support intact.\n    // Done before the (possibly async) verify so a release during verification still cancels cleanly.\n    if(this.endListener) {\n      this.listenerSetter.remove(this.endListener);\n    }\n    // @ts-ignore\n    this.endListener = this.listenerSetter.add(this.element.ownerDocument)(\n      IS_TOUCH_SUPPORTED ? 'touchend' : 'mouseup',\n      this.reset\n    ) as any as Listener;\n\n    const verifyResult = this.verifyTouchTarget?.(_e);\n    if(verifyResult !== undefined) {\n      let result: any;\n      if(verifyResult instanceof Promise) {\n        // const tempId = this.tempId;\n        result = await verifyResult;\n\n        if(this.tempId !== tempId) {\n          return;\n        }\n      } else {\n        result = verifyResult;\n      }\n\n      if(!result) {\n        return this.reset();\n      }\n    }\n\n    this.isMouseDown = true;\n\n    if(this.withDelay && !IS_TOUCH_SUPPORTED) {\n      const options = {...MOUSE_MOVE_OPTIONS, once: true};\n      const deferred = deferredPromise<void>();\n      const cb = () => deferred.resolve();\n      const listener = this.listenerSetter.add(this.element.ownerDocument)('mousemove', cb, options) as any as Listener;\n\n      await Promise.race([\n        pause(300),\n        deferred\n      ]);\n\n      deferred.resolve();\n      this.listenerSetter.remove(listener);\n\n      if(this.tempId !== tempId) {\n        return;\n      }\n    }\n\n    this.xDown = e.clientX;\n    this.yDown = e.clientY;\n    this.eventUp = e;\n\n    if(IS_TOUCH_SUPPORTED) {\n      // @ts-ignore\n      this.listenerSetter.add(this.element.ownerDocument)('touchmove', this.handleMove, TOUCH_MOVE_OPTIONS);\n    } else {\n      // @ts-ignore\n      this.listenerSetter.add(this.element.ownerDocument)('mousemove', this.handleMove, MOUSE_MOVE_OPTIONS);\n    }\n\n    if(this.onStart) {\n      this.onStart();\n\n      // have to initiate move instantly\n      this.hadMove = true;\n      this.handleMove(e);\n    }\n  };\n\n  protected handleMove = (_e: EE) => {\n    if(this.xDown === undefined || this.yDown === undefined || RESET_GLOBAL) {\n      this.reset();\n      return;\n    }\n\n    if(this.cancelEvent) {\n      cancelEvent(_e as any);\n    }\n\n    if(this.releaseWheelDrag?.isDebounced() || this.releaseWheelZoom?.isDebounced()) {\n      return;\n    }\n\n    this.log('move');\n\n    const e = this.eventUp = getEvent(_e);\n    const xUp = e.clientX;\n    const yUp = e.clientY;\n\n    const xDiff = xUp - this.xDown + this.xAdded;\n    const yDiff = yUp - this.yDown + this.yAdded;\n\n    if(!this.hadMove) {\n      if(!xDiff && !yDiff) {\n        return;\n      }\n\n      this.setHadMove(_e);\n    }\n\n    const touches = (_e as any as TouchEvent).touches;\n    if(this.onZoom && this.initialDistance > 0 && touches.length === 2) {\n      const endDistance = getDistance(touches[0], touches[1]);\n      const touchCenter = getTouchCenter(touches[0], touches[1]);\n      const dragOffsetX = touchCenter.x - this.initialTouchCenter.x;\n      const dragOffsetY = touchCenter.y - this.initialTouchCenter.y;\n      const zoomFactor = endDistance / this.initialDistance;\n      const details: ZoomDetails = {\n        zoomFactor,\n        initialCenterX: this.initialTouchCenter.x,\n        initialCenterY: this.initialTouchCenter.y,\n        dragOffsetX,\n        dragOffsetY,\n        currentCenterX: touchCenter.x,\n        currentCenterY: touchCenter.y\n      };\n\n      this.onZoom(details);\n    }\n\n    this.dispatchOnSwipe(xDiff, yDiff, _e);\n  };\n\n  protected handleWheel = (e: WheelEvent) => {\n    if(!this.hadMove && this.verifyTouchTarget) {\n      const result = this.verifyTouchTarget(e);\n      if(result !== undefined && !result) {\n        this.reset(e);\n        return;\n      }\n    }\n\n    cancelEvent(e);\n\n    this.log('wheel');\n\n    if(this.onDoubleClick && Object.is(e.deltaX, -0) && Object.is(e.deltaY, -0) && e.ctrlKey) {\n      this.onWheelCapture(e);\n      this.onDoubleClick({centerX: e.pageX, centerY: e.pageY});\n      this.reset();\n      return;\n    }\n\n    const metaKeyPressed = e.metaKey || e.ctrlKey || e.shiftKey;\n    if(metaKeyPressed) {\n      // * fix zooming while dragging is in inertia\n      if(this.releaseWheelDrag?.isDebounced()) {\n        this.reset();\n      }\n\n      this.onWheelZoom(e);\n    } else {\n      this.handleWheelDrag(e);\n    }\n  };\n\n  protected handleWheelDrag = (e: WheelEvent) => {\n    this.log('wheel drag');\n\n    this.onWheelCapture(e);\n    // Ignore wheel inertia if drag is canceled in this direction\n    if(!this.isDragCanceled.x || Math.sign(this.initialDragOffset.x) === Math.sign(e.deltaX)) {\n      this.initialDragOffset.x -= e.deltaX;\n    }\n    if(!this.isDragCanceled.y || Math.sign(this.initialDragOffset.y) === Math.sign(e.deltaY)) {\n      this.initialDragOffset.y -= e.deltaY;\n    }\n    const {x, y} = this.initialDragOffset;\n    this.releaseWheelDrag(e);\n    this.dispatchOnSwipe(x, y, e, (dx, dy) => {\n      this.isDragCanceled = {x: dx, y: dy};\n    });\n  };\n\n  protected onWheelCapture = (e: WheelEvent) => {\n    if(this.hadMove) return;\n    this.log('wheel capture');\n    this.handleStart(e);\n    this.setHadMove(e);\n    this.initialTouchCenter = {x: e.x, y: e.y};\n  };\n\n  protected onWheelZoom = (e: WheelEvent) => {\n    if(!this.onZoom) return;\n    this.log('wheel zoom');\n    this.onWheelCapture(e);\n    const dragOffsetX = e.x - this.initialTouchCenter.x;\n    const dragOffsetY = e.y - this.initialTouchCenter.y;\n    const delta = clamp(e.deltaY, -25, 25);\n    this.wheelZoom -= delta * 0.01;\n    const details: ZoomDetails = {\n      zoomAdd: this.wheelZoom - 1,\n      initialCenterX: this.initialTouchCenter.x,\n      initialCenterY: this.initialTouchCenter.y,\n      dragOffsetX,\n      dragOffsetY,\n      currentCenterX: e.x,\n      currentCenterY: e.y\n    };\n    this.onZoom(details);\n    this.releaseWheelZoom(e);\n  }\n}\n","// generate a path's arc data parameter\n\nimport {MOUNT_CLASS_TO} from '@config/debug';\n\n// http://www.w3.org/TR/SVG/paths.html#PathDataEllipticalArcCommands\nfunction arcParameter(rx: number, ry: number, xAxisRotation: number, largeArcFlag: number, sweepFlag: number, x: number, y: number) {\n  return [rx, ',', ry, ' ',\n    xAxisRotation, ' ',\n    largeArcFlag, ',',\n    sweepFlag, ' ',\n    x, ',', y].join('');\n}\n\nexport default function generatePathData(x: number, y: number, width: number, height: number, tl: number, tr: number, br: number, bl: number) {\n  const data: string[] = [];\n\n  // start point in top-middle of the rectangle\n  data.push('M' + (x + width / 2) + ',' + y);\n\n  // next we go to the right\n  data.push('H' + (x + width - tr));\n\n  if(tr > 0) {\n    // now we draw the arc in the top-right corner\n    data.push('A' + arcParameter(tr, tr, 0, 0, 1, (x + width), (y + tr)));\n  }\n\n  // next we go down\n  data.push('V' + (y + height - br));\n\n  if(br > 0) {\n    // now we draw the arc in the lower-right corner\n    data.push('A' + arcParameter(br, br, 0, 0, 1, (x + width - br), (y + height)));\n  }\n\n  // now we go to the left\n  data.push('H' + (x + bl));\n\n  if(bl > 0) {\n    // now we draw the arc in the lower-left corner\n    data.push('A' + arcParameter(bl, bl, 0, 0, 1, (x + 0), (y + height - bl)));\n  }\n\n  // next we go up\n  data.push('V' + (y + tl));\n\n  if(tl > 0) {\n    // now we draw the arc in the top-left corner\n    data.push('A' + arcParameter(tl, tl, 0, 0, 1, (x + tl), (y + 0)));\n  }\n\n  // and we close the path\n  data.push('Z');\n\n  return data.join(' ');\n}\n\nMOUNT_CLASS_TO.generatePathData = generatePathData;\n","export default function isBetween(num: number, min: number, max: number) {\n  return num >= min && num <= max;\n}\n","import {IS_SAFARI} from '@environment/userAgent';\nimport {InputGroupCall} from '@layer';\nimport apiManagerProxy from '@lib/apiManagerProxy';\n\nexport function getRtmpStreamUrl(call: InputGroupCall): string {\n  const base = `/rtmp/${encodeURIComponent(JSON.stringify(call))}`;\n\n  if(IS_SAFARI) return `${base}?hls=playlist&t=${Date.now()}`;\n  return `${base}?t=${Date.now()}`;\n}\n\nexport function getRtmpShareUrl(peerId: PeerId) {\n  const chat = apiManagerProxy.getChat(peerId);\n  if(chat._ !== 'channel') throw new Error('Not a channel');\n\n  if(chat.username || chat.usernames?.length) {\n    const username = chat.username || chat.usernames[0];\n    return `https://t.me/${username}?livestream`;\n  }\n\n  return `https://t.me/c/${chat.id}?livestream`;\n}\n","import {getEnvironment} from '@environment/utils';\nimport assumeType from '@helpers/assumeType';\nimport {Document, DocumentAttribute} from '@layer';\n\nimport {isDocumentHlsQualityFile} from '@lib/hls/common';\n\nconst QUALITY_FILE_NAME_PREFIX = 'mtproto:';\n\nconst FALLBACK_BANDWIDTH = 1_000_000;\nconst FALLBACK_WIDTH = 1280;\nconst FALLBACK_HEIGHT = 720;\n\nexport function createHlsVideoSource(\n  // message: Message.message\n  altDocs: Document.document[]\n): string | null {\n  // const altDocs = getAltDocsFromMessage(message);\n\n  let qualityEntries = getQualityFilesEntries(altDocs);\n\n  if(!getEnvironment().IS_AV1_SUPPORTED) {\n    qualityEntries = qualityEntries.filter((entry) => entry.codec !== 'av01');\n  }\n\n  if(!qualityEntries.length) return null;\n\n  qualityEntries.sort((a, b) => a.bandwidth - b.bandwidth);\n\n\n  let hlsFileSource = '#EXTM3U\\n';\n\n  for(const qualityEntry of qualityEntries) {\n    const {w, h, bandwidth, url} = qualityEntry;\n\n    hlsFileSource += `#EXT-X-STREAM-INF:BANDWIDTH=${bandwidth},RESOLUTION=${w}x${h}\\n`;\n    hlsFileSource += url + '\\n';\n  }\n\n  hlsFileSource += '\\n#EXT-X-ENDLIST';\n\n  return hlsFileSource;\n}\n\nexport function getQualityFilesEntries(altDocs: Document.document[]) {\n  if(!altDocs?.length) return [];\n\n  const videoAttributes = getVideoAttributesFromAltDocs(altDocs);\n  const qualityURLs = getQualityURLsFromAltDocs(altDocs);\n\n  return Object.entries(videoAttributes).map(([id, attr]) => {\n    const {w = FALLBACK_WIDTH, h = FALLBACK_HEIGHT, duration = 0, video_codec: codec} = attr;\n    const {size} = altDocs.find((doc) => doc.id.toString() === id);\n\n    const bandwidth = (duration > 0 ? size / duration * 8 : FALLBACK_BANDWIDTH) | 0;\n\n    return {\n      id,\n      w,\n      h,\n      duration,\n      bandwidth,\n      url: qualityURLs[id],\n      codec\n    };\n  });\n}\n\nfunction getVideoAttributesFromAltDocs(altDocs: Document.document[]) {\n  const result: {[docId: DocId]: DocumentAttribute.documentAttributeVideo} = {};\n\n  for(const doc of altDocs) {\n    const videoAttribute = doc?.attributes?.find((attr) => attr._ === 'documentAttributeVideo');\n    if(!videoAttribute) continue;\n    assumeType<DocumentAttribute.documentAttributeVideo>(videoAttribute);\n\n    result[doc.id] = videoAttribute;\n  }\n\n  return result;\n}\n\nfunction getQualityURLsFromAltDocs(altDocs: Document.document[]) {\n  const result: {[docId: DocId]: string} = {};\n\n  for(const doc of altDocs) {\n    if(!isDocumentHlsQualityFile(doc)) continue;\n\n    result[getTargetDocIdForQualityFile(doc)] = getURLForQualityFile(doc);\n  }\n\n  return result;\n}\n\nfunction getURLForQualityFile(doc: Document.document) {\n  return `hls_quality_file/${doc.id}`;\n}\n\nfunction getTargetDocIdForQualityFile(doc: Document.document) {\n  const fileNameAttribute = doc.attributes?.find((attr) => attr._ === 'documentAttributeFilename');\n  assumeType<DocumentAttribute.documentAttributeFilename>(fileNameAttribute);\n\n  const rawFileName = doc.file_name || fileNameAttribute?.file_name;\n\n  return rawFileName?.slice(QUALITY_FILE_NAME_PREFIX.length);\n}\n","import readBlobAs from '@helpers/blob/readBlobAs';\n\nexport default function readBlobAsText(blob: Blob) {\n  return readBlobAs(blob, 'readAsText');\n}\n","export default function cloneDOMRect(rect: DOMRect): DOMRectEditable {\n  return {\n    width: rect.width,\n    height: rect.height,\n    top: rect.top,\n    right: rect.right,\n    bottom: rect.bottom,\n    left: rect.left\n  };\n}\n","// * zoom part from WebZ\n// * https://github.com/Ajaxy/telegram-tt/blob/069f4f5b2f2c7c22529ccced876842e7f9cb81f4/src/components/mediaViewer/MediaViewerSlides.tsx\n\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport type {MyPhoto} from '@appManagers/appPhotosManager';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport mediaSizes from '@helpers/mediaSizes';\nimport calcImageInBox from '@helpers/calcImageInBox';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {IS_MOBILE, IS_MOBILE_SAFARI, IS_SAFARI} from '@environment/userAgent';\nimport {logger} from '@lib/logger';\nimport VideoPlayer from '@lib/mediaPlayer';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector from '@components/animationIntersector';\nimport appMediaPlaybackController, {AppMediaPlaybackController} from '@components/appMediaPlaybackController';\nimport ButtonIcon from '@components/buttonIcon';\nimport {ButtonMenuItemOptions, ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport ProgressivePreloader from '@components/preloader';\nimport SwipeHandler, {ZoomDetails} from '@components/swipeHandler';\nimport {formatFullSentTime} from '@helpers/date';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport {InputGroupCall, Message, MessageMedia, PhotoSize} from '@layer';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport renderImageFromUrl, {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport generatePathData from '@helpers/generatePathData';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {doubleRaf, fastRaf} from '@helpers/schedulers';\nimport RangeSelector from '@components/rangeSelector';\nimport windowSize from '@helpers/windowSize';\nimport ListLoader from '@helpers/listLoader';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {MyMessage} from '@appManagers/appMessagesManager';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport {isFullScreen} from '@helpers/dom/fullScreen';\nimport {attachClickEvent, hasMouseMovedSinceDown} from '@helpers/dom/clickEvent';\nimport SearchListLoader from '@helpers/searchListLoader';\nimport createVideo from '@helpers/dom/createVideo';\nimport {AppManagers} from '@lib/managers';\nimport getMediaThumbIfNeeded from '@helpers/getStrippedThumbIfNeeded';\nimport setAttachmentSize from '@helpers/setAttachmentSize';\nimport wrapEmojiText from '@richTextProcessor/wrapEmojiText';\nimport LazyLoadQueueBase from '@components/lazyLoadQueueBase';\nimport overlayCounter from '@helpers/overlayCounter';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {toastNew} from '@components/toast';\nimport clamp from '@helpers/number/clamp';\nimport debounce from '@helpers/schedulers/debounce';\nimport isBetween from '@helpers/number/isBetween';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport liteMode from '@helpers/liteMode';\nimport {avatarNew, findUpAvatar} from '@components/avatarNew';\nimport {Middleware, MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport onMediaLoad, {shouldIgnoreVideoError} from '@helpers/onMediaLoad';\nimport handleVideoLeak from '@helpers/dom/handleVideoLeak';\nimport Icon from '@components/icon';\nimport {replaceButtonIcon} from '@components/button';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport {MediaSize} from '@helpers/mediaSize';\nimport {getRtmpStreamUrl} from '@lib/rtmp/url';\nimport boxBlurCanvasRGB from '@vendor/fastBlur';\nimport {i18n} from '@lib/langPack';\nimport {getQualityFilesEntries} from '@lib/hls/createHlsVideoSource';\nimport {snapQualityHeight} from '@lib/hls/snapQualityHeight';\nimport {ButtonMenuItemWithAuxiliaryText} from '@lib/mediaPlayer/qualityLevelsSwitchButton';\nimport formatBytes from '@helpers/formatBytes';\nimport getDocumentURL from '@appManagers/utils/docs/getDocumentURL';\nimport assumeType from '@helpers/assumeType';\nimport {createRoot, createResource, createEffect, createMemo} from 'solid-js';\nimport readBlobAsText from '@helpers/blob/readBlobAsText';\nimport {Storyboard, StoryboardFrame} from '@lib/mediaPlayer/preview';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport cloneDOMRect from '../helpers/dom/cloneDOMRect';\n\nconst ZOOM_STEP = 0.5;\nconst ZOOM_INITIAL_VALUE = 1;\nconst ZOOM_MIN_VALUE = 0.5;\nconst ZOOM_MAX_VALUE = 4;\n\nconst OPEN_TRANSITION_TIME = 200;\nconst MOVE_TRANSITION_TIME = 350;\n\n// Vertical reserves around the media (px). Single source of truth for layout —\n// mediaBoxSize math and the inline positioning applied by applyCenterStyles /\n// applyLayoutVariables are derived from these. Same reserves apply to live\n// streams and regular videos — chrome (topbar / controls) behaves identically.\nconst RESERVE_TOP_DESKTOP = 80;\nconst RESERVE_BOTTOM_DESKTOP = 110;\n// On mobile the player fills the whole viewport (no reserve); topbar/controls\n// float over the media and auto-hide together.\nconst RESERVE_TOP_MOBILE = 0;\nconst RESERVE_BOTTOM_MOBILE = 0;\n\n// Min displayed width for videos that get a player UI.\nconst VIDEO_MIN_WIDTH = 420;\n\nexport const MEDIA_VIEWER_CLASSNAME = 'media-viewer';\n\ntype Transform = {\n  x: number;\n  y: number;\n  scale: number;\n};\n\nexport type VideoTimestamp = {\n  time: number;\n  text?: string;\n};\n\nfunction prepareStoryboard({\n  message,\n  middleware\n}: {\n  message?: Message.message,\n  middleware: Middleware\n}) {\n  if(!message?.media) {\n    return;\n  }\n\n  const altDocuments = (message.media as MessageMedia.messageMediaDocument).alt_documents as MyDocument[] || [];\n  const mapDoc = altDocuments.find((d) => d.mime_type === 'application/x-tgstoryboardmap');\n  if(!mapDoc) {\n    return;\n  }\n\n  const docId = mapDoc.file_name.split(':')[1];\n  const doc = altDocuments.find((d) => d.id === docId);\n\n  if(!doc) {\n    return;\n  }\n\n  return createRoot((dispose) => {\n    middleware.onClean(dispose);\n    const [imageFileURL] = createResource(doc, () => {\n      return appDownloadManager.downloadMediaURL({media: doc});\n    });\n\n    const [image] = createResource(imageFileURL, async(url) => {\n      if(!url) {\n        return;\n      }\n\n      const image = new Image();\n      await renderImageFromUrlPromise(image, url, false);\n      return image;\n    });\n\n    const [mapFile] = createResource(mapDoc, () => {\n      return appDownloadManager.downloadMedia({media: mapDoc});\n    });\n\n    const [map] = createResource(mapFile, async(file) => {\n      if(!file) {\n        return;\n      }\n\n      const text = await readBlobAsText(file);\n      const lines = text.split('\\n');\n      const fileNameLine = lines.shift();\n      const frameWidth = +lines.shift().split('=').pop();\n      const frameHeight = +lines.shift().split('=').pop();\n      if(!lines[lines.length - 1].trim()) {\n        lines.pop();\n      }\n      const frames: StoryboardFrame[] = lines.map((line) => {\n        const [time, left, top] = line.split(',').map(Number);\n        return {time, left, top};\n      });\n      return {frameWidth, frameHeight, frames};\n    });\n\n    const storyboard = createMemo<Storyboard>(() => {\n      const image$ = image();\n      const map$ = map();\n      return image$ && map$ ? {\n        image: image$,\n        ...map$\n      } : undefined;\n    });\n\n    return storyboard;\n  });\n}\n\nexport default class AppMediaViewerBase<\n  ContentAdditionType extends string,\n  ButtonsAdditionType extends string,\n  TargetType extends {element: HTMLElement\n}> extends EventListenerBase<{\n  setMoverBefore: () => void,\n  setMoverAfter: () => void\n}> {\n  protected wholeDiv: HTMLElement;\n  protected overlaysDiv: HTMLElement;\n  protected author: {\n    avatarEl: ReturnType<typeof avatarNew>,\n    avatarMiddlewareHelper?: MiddlewareHelper,\n    container: HTMLElement,\n    nameEl: HTMLElement,\n    date: HTMLElement\n  } = {} as any;\n  protected content: {[k in 'main' | 'container' | 'media' | 'mover' | ContentAdditionType]: HTMLElement} = {} as any;\n  protected buttons: {[k in 'download' | 'close' | 'prev' | 'next' | 'mobile-close' | 'zoomin' | 'rotate' | ButtonsAdditionType]: HTMLElement} = {} as any;\n  protected topbar: HTMLElement;\n  protected moversContainer: HTMLElement;\n\n  protected tempId = 0;\n  protected preloader: ProgressivePreloader = null;\n  protected preloaderStreamable: ProgressivePreloader = null;\n\n  protected log: ReturnType<typeof logger>;\n\n  protected isFirstOpen = true;\n\n  // protected pageEl = document.getElementById('page-chats') as HTMLDivElement;\n\n  protected setMoverPromise: Promise<void>;\n  protected setMoverAnimationPromise: Promise<void>;\n\n  protected lazyLoadQueue: LazyLoadQueueBase;\n\n  protected highlightSwitchersTimeout: number;\n\n  protected streamEnded: boolean = false;\n\n  protected downloadQualityMenuOptions: ButtonMenuItemOptionsVerifiable[] = [];\n  protected get hasQualityOptions() {\n    return this.downloadQualityMenuOptions.length > 0;\n  }\n\n  protected onDownloadClick: (e: MouseEvent | TouchEvent, docId?: DocId) => void;\n  protected onPrevClick: (target: TargetType) => void;\n  protected onNextClick: (target: TargetType) => void;\n\n  protected disposeSolid?: () => void;\n\n  protected videoPlayer: VideoPlayer;\n  protected adminPanel: HTMLDivElement;\n\n  protected zoomElements: {\n    container: HTMLElement,\n    btnOut: HTMLElement,\n    btnIn: HTMLElement,\n    rangeSelector: RangeSelector\n  } = {} as any;\n  protected transform: Transform = {x: 0, y: 0, scale: ZOOM_INITIAL_VALUE};\n  // Accumulated rotation in degrees (multiples of 90, counterclockwise = negative).\n  // Lives on moversContainer alongside the zoom/pan transform; reset per media.\n  protected rotation: number = 0;\n  protected isZooming: boolean;\n  protected isGesturingNow: boolean;\n  protected isZoomingNow: boolean;\n  protected draggingType: 'wheel' | 'touchmove' | 'mousemove';\n  protected initialContentRect: DOMRect;\n  protected live: boolean;\n\n  protected ctrlKeyDown: boolean;\n  protected releaseSingleMedia: ReturnType<AppMediaPlaybackController['setSingleMedia']>;\n  protected navigationItem: NavigationItem;\n\n  protected managers: AppManagers;\n  protected swipeHandler: SwipeHandler;\n  protected closing: boolean;\n\n  protected lastTransform: Transform = this.transform;\n  protected lastZoomCenter: {x: number, y: number} = this.transform;\n  protected lastDragOffset: {x: number, y: number} = this.transform;\n  protected lastDragDelta: {x: number, y: number} = this.transform;\n  protected lastGestureTime: number;\n  protected clampZoomDebounced: ReturnType<typeof debounce<() => void>>;\n  protected ignoreNextClick: boolean;\n\n  protected middlewareHelper: MiddlewareHelper;\n\n  protected overlayActive: boolean;\n\n  protected videoTimestamps: VideoTimestamp[] = [];\n\n  get target() {\n    return this.listLoader.current;\n  }\n\n  set target(value) {\n    this.listLoader.current = value;\n  }\n\n  constructor(\n    protected listLoader: ListLoader<TargetType, any>,\n    topButtons: Array<keyof AppMediaViewerBase<ContentAdditionType, ButtonsAdditionType, TargetType>['buttons']>,\n    protected extraHeightPadding = 0\n  ) {\n    super(false);\n\n    this.managers = rootScope.managers;\n    this.middlewareHelper = getMiddleware();\n\n    this.log = logger('AMV');\n    this.preloader = new ProgressivePreloader();\n    this.preloaderStreamable = new ProgressivePreloader({\n      cancelable: false,\n      streamable: true\n    });\n    this.preloader.construct();\n    this.preloaderStreamable.construct();\n    this.lazyLoadQueue = new LazyLoadQueueBase();\n\n    this.wholeDiv = document.createElement('div');\n    this.wholeDiv.classList.add(MEDIA_VIEWER_CLASSNAME + '-whole');\n\n    this.overlaysDiv = document.createElement('div');\n    this.overlaysDiv.classList.add('overlays');\n    this.overlayActive = false;\n\n    const mainDiv = document.createElement('div');\n    mainDiv.classList.add(MEDIA_VIEWER_CLASSNAME);\n\n    const topbar = this.topbar = document.createElement('div');\n    topbar.classList.add(MEDIA_VIEWER_CLASSNAME + '-topbar', MEDIA_VIEWER_CLASSNAME + '-appear');\n\n    const topbarLeft = document.createElement('div');\n    topbarLeft.classList.add(MEDIA_VIEWER_CLASSNAME + '-topbar-left');\n\n    this.buttons['mobile-close'] = ButtonIcon('close', {onlyMobile: true});\n\n    // * author\n    this.author.container = document.createElement('div');\n    this.author.container.classList.add(MEDIA_VIEWER_CLASSNAME + '-author', 'no-select');\n    const authorRight = document.createElement('div');\n    authorRight.classList.add(MEDIA_VIEWER_CLASSNAME + '-author-right');\n\n    this.author.nameEl = document.createElement('div');\n    this.author.nameEl.classList.add(MEDIA_VIEWER_CLASSNAME + '-name');\n\n    this.author.date = document.createElement('div');\n    this.author.date.classList.add(MEDIA_VIEWER_CLASSNAME + '-date');\n\n    authorRight.append(this.author.nameEl, this.author.date);\n\n    this.author.container.append(authorRight);\n\n    // * buttons\n    const buttonsDiv = document.createElement('div');\n    buttonsDiv.classList.add(MEDIA_VIEWER_CLASSNAME + '-buttons');\n\n    topButtons.concat(['download', 'rotate', 'zoomin', 'close']).forEach((name) => {\n      // The rotate button turns the image counterclockwise (matching Telegram\n      // Desktop), so it carries the left-pointing glyph while keeping the plain\n      // `rotate` key in this.buttons.\n      const icon: Icon = name === 'rotate' ? 'rotate_left' : name as Icon;\n      const button = ButtonIcon(icon, {noRipple: true});\n      this.buttons[name] = button;\n      buttonsDiv.append(button);\n    });\n\n    // * zoom\n    this.zoomElements.container = document.createElement('div');\n    this.zoomElements.container.classList.add('zoom-container');\n\n    this.zoomElements.btnOut = ButtonIcon('zoomout', {noRipple: true});\n    attachClickEvent(this.zoomElements.btnOut, () => this.addZoomStep(false));\n    this.zoomElements.btnIn = ButtonIcon('zoomin', {noRipple: true});\n    attachClickEvent(this.zoomElements.btnIn, () => this.addZoomStep(true));\n\n    this.zoomElements.rangeSelector = new RangeSelector({\n      step: 0.01,\n      min: ZOOM_MIN_VALUE,\n      max: ZOOM_MAX_VALUE,\n      withTransition: true\n    }, ZOOM_INITIAL_VALUE);\n    this.zoomElements.rangeSelector.setListeners();\n    this.zoomElements.rangeSelector.setHandlers({\n      onScrub: (value) => {\n        const add = value - this.transform.scale;\n        this.addZoom(add);\n        this.clampZoomDebounced?.clearTimeout();\n      },\n      onMouseDown: () => {\n        this.onSwipeFirst();\n      },\n      onMouseUp: () => {\n        this.onSwipeReset();\n      }\n    });\n\n    this.zoomElements.container.append(this.zoomElements.btnOut, this.zoomElements.rangeSelector.container, this.zoomElements.btnIn);\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.wholeDiv.append(this.zoomElements.container);\n    }\n\n    // * content\n    this.content.main = document.createElement('div');\n    this.content.main.classList.add(MEDIA_VIEWER_CLASSNAME + '-content');\n\n    this.content.container = document.createElement('div');\n    this.content.container.classList.add(MEDIA_VIEWER_CLASSNAME + '-container');\n\n    this.content.media = document.createElement('div');\n    this.content.media.classList.add(MEDIA_VIEWER_CLASSNAME + '-media');\n\n    this.content.container.append(this.content.media);\n\n    this.content.main.append(this.content.container);\n    mainDiv.append(this.content.main);\n    this.overlaysDiv.append(mainDiv);\n    // * overlays end\n\n    topbarLeft.append(this.buttons['mobile-close'], this.author.container);\n    topbar.append(topbarLeft, buttonsDiv);\n\n    this.buttons.prev = document.createElement('div');\n    this.buttons.prev.className = `${MEDIA_VIEWER_CLASSNAME}-switcher ${MEDIA_VIEWER_CLASSNAME}-switcher-left`;\n    this.buttons.prev.append(Icon('previous', `${MEDIA_VIEWER_CLASSNAME}-sibling-button`, `${MEDIA_VIEWER_CLASSNAME}-prev-button`));\n\n    this.buttons.next = document.createElement('div');\n    this.buttons.next.className = `${MEDIA_VIEWER_CLASSNAME}-switcher ${MEDIA_VIEWER_CLASSNAME}-switcher-right`;\n    this.buttons.next.append(Icon('next', `${MEDIA_VIEWER_CLASSNAME}-sibling-button`, `${MEDIA_VIEWER_CLASSNAME}-next-button`));\n\n    this.moversContainer = document.createElement('div');\n    this.moversContainer.classList.add(MEDIA_VIEWER_CLASSNAME + '-movers');\n\n    this.moversContainer.append(this.buttons.prev, this.buttons.next);\n\n    this.wholeDiv.append(this.overlaysDiv, /* this.buttons.prev, this.buttons.next, */ this.topbar, this.moversContainer);\n\n    // * constructing html end\n\n    this.listLoader.onLoadedMore = () => {\n      this.buttons.prev.classList.toggle('hide', !this.listLoader.previous.length);\n      this.buttons.next.classList.toggle('hide', !this.listLoader.next.length);\n    };\n\n    this.setNewMover();\n  }\n\n  protected setListeners() {\n    attachClickEvent(this.buttons.download, (e) => {\n      if(this.hasQualityOptions) return;\n      this.onDownloadClick(e);\n    });\n    this.buttons.download.classList.add('quality-download-options-button-menu');\n    ButtonMenuToggle({\n      container: this.buttons.download,\n      buttons: this.downloadQualityMenuOptions,\n      direction: 'bottom-left'\n    });\n\n    [this.buttons.close, this.buttons['mobile-close'], this.preloaderStreamable.preloader].forEach((el) => {\n      attachClickEvent(el, this.close.bind(this));\n    });\n\n    ([[-1, this.buttons.prev], [1, this.buttons.next]] as [number, HTMLElement][]).forEach(([moveLength, button]) => {\n      // attachClickEvent(button, (e) => {\n      button.addEventListener('click', (e) => {\n        cancelEvent(e);\n        if(this.setMoverPromise) return;\n\n        this.listLoader.go(moveLength);\n      });\n    });\n\n    attachClickEvent(this.buttons.zoomin, () => {\n      if(this.isZooming) this.resetZoom();\n      else {\n        this.addZoomStep(true);\n      }\n    });\n\n    attachClickEvent(this.buttons.rotate, () => this.rotateMedia());\n\n    // ! cannot use the function because it'll cancel slide event on touch devices\n    // attachClickEvent(this.wholeDiv, this.onClick);\n    this.wholeDiv.addEventListener('click', this.onClick);\n\n    this.listLoader.onJump = (item, older) => {\n      if(older) this.onNextClick(item);\n      else this.onPrevClick(item);\n    };\n\n    const adjustPosition = (xDiff: number, yDiff: number) => {\n      const [x, y] = [xDiff - this.lastDragOffset.x, yDiff - this.lastDragOffset.y];\n      const [transform, inBoundsX, inBoundsY] = this.calculateOffsetBoundaries({\n        x: this.transform.x + x,\n        y: this.transform.y + y,\n        scale: this.transform.scale\n      });\n\n      this.lastDragDelta = {\n        x,\n        y\n      };\n\n      this.lastDragOffset = {\n        x: xDiff,\n        y: yDiff\n      };\n\n      this.setTransform(transform);\n\n      return {inBoundsX, inBoundsY};\n    };\n\n    const setLastGestureTime = debounce(() => {\n      this.lastGestureTime = Date.now();\n    }, 500, false, true);\n\n    this.clampZoomDebounced = debounce(() => {\n      this.onSwipeReset();\n    }, 300, false, true);\n\n    this.swipeHandler = new SwipeHandler({\n      element: this.wholeDiv,\n      onReset: this.onSwipeReset,\n      onFirstSwipe: this.onSwipeFirst as any,\n      onSwipe: (xDiff, yDiff, e, cancelDrag) => {\n        if(isFullScreen()) {\n          return;\n        }\n\n        if(this.isZooming && !this.isZoomingNow) {\n          setLastGestureTime();\n\n          this.draggingType = e.type as any;\n          const {inBoundsX, inBoundsY} = adjustPosition(xDiff, yDiff);\n          cancelDrag?.(!inBoundsX, !inBoundsY);\n\n          return;\n        }\n\n        if(this.isZoomingNow || !IS_TOUCH_SUPPORTED) {\n          return;\n        }\n\n        const percents = Math.abs(xDiff) / windowSize.width;\n        if(percents > .2 || Math.abs(xDiff) > 125) {\n          if(xDiff > 0) {\n            this.buttons.prev.click();\n          } else {\n            this.buttons.next.click();\n          }\n\n          return true;\n        }\n\n        const percentsY = Math.abs(yDiff) / windowSize.height;\n        if(percentsY > .2 || Math.abs(yDiff) > 125) {\n          this.close();\n          return true;\n        }\n\n        return false;\n      },\n      onZoom: this.onZoom,\n      onDoubleClick: ({centerX, centerY}) => {\n        if(this.isZooming) {\n          this.resetZoom();\n        } else {\n          const scale = ZOOM_INITIAL_VALUE + 2;\n          this.changeZoomByPosition(centerX, centerY, scale);\n        }\n      },\n      verifyTouchTarget: (e) => {\n        // * Fix for seek input\n        if(isFullScreen() ||\n          findUpAsChild(e.target as HTMLElement, this.zoomElements.container) ||\n          findUpClassName(e.target, 'ckin__controls') ||\n          findUpClassName(e.target, 'media-viewer-caption') ||\n          (findUpClassName(e.target, 'media-viewer-topbar') && e.type !== 'wheel')) {\n          return false;\n        }\n\n        return true;\n      },\n      cursor: ''\n      // cursor: 'move'\n    });\n  }\n\n  protected onSwipeFirst = (e?: MouseEvent | TouchEvent | WheelEvent) => {\n    this.lastDragOffset = this.lastDragDelta = {x: 0, y: 0};\n    this.lastTransform = {...this.transform};\n    if(e?.type !== 'wheel' || !this.ctrlKeyDown) { // keep transition for real mouse wheel\n      this.moversContainer.classList.add('no-transition');\n      this.zoomElements.rangeSelector.container.classList.remove('with-transition');\n    }\n    this.isGesturingNow = true;\n    this.lastGestureTime = Date.now();\n    this.clampZoomDebounced.clearTimeout();\n\n    if(!this.lastTransform.x && !this.lastTransform.y && !this.isZooming) {\n      this.initialContentRect = this.content.media.getBoundingClientRect();\n    }\n  };\n\n  protected onSwipeReset = (e?: Event) => {\n    // move\n    this.moversContainer.classList.remove('no-transition');\n    this.zoomElements.rangeSelector.container.classList.add('with-transition');\n    this.clampZoomDebounced.clearTimeout();\n\n    if(e?.type === 'mouseup' && this.draggingType === 'mousemove') {\n      this.ignoreNextClick = true;\n    }\n\n    const {draggingType} = this;\n    this.isZoomingNow = false;\n    this.isGesturingNow = false;\n    this.draggingType = undefined;\n\n    if(this.closing) {\n      return;\n    }\n\n    if(this.transform.scale > ZOOM_INITIAL_VALUE) {\n      // Get current content boundaries\n      const s1 = Math.min(this.transform.scale, ZOOM_MAX_VALUE);\n      const scaleFactor = s1 / this.transform.scale;\n\n      // Calculate new position based on the last zoom center to keep the zoom center\n      // at the same position when bouncing back from max zoom\n      let x1 = this.transform.x * scaleFactor + (this.lastZoomCenter.x - scaleFactor * this.lastZoomCenter.x);\n      let y1 = this.transform.y * scaleFactor + (this.lastZoomCenter.y - scaleFactor * this.lastZoomCenter.y);\n\n      // If scale didn't change, we need to add inertia to pan gesture\n      if(draggingType && draggingType !== 'wheel' && this.lastTransform.scale === this.transform.scale) {\n        // Arbitrary pan velocity coefficient\n        const k = 0.1;\n\n        // Calculate user gesture velocity\n        const elapsedTime = Math.max(1, Date.now() - this.lastGestureTime);\n        const Vx = Math.abs(this.lastDragOffset.x) / elapsedTime;\n        const Vy = Math.abs(this.lastDragOffset.y) / elapsedTime;\n\n        // Add extra distance based on gesture velocity and last pan delta\n        x1 -= Math.abs(this.lastDragOffset.x) * Vx * k * -this.lastDragDelta.x;\n        y1 -= Math.abs(this.lastDragOffset.y) * Vy * k * -this.lastDragDelta.y;\n      }\n\n      const [transform] = this.calculateOffsetBoundaries({x: x1, y: y1, scale: s1});\n      this.lastTransform = transform;\n      this.setTransform(transform);\n    } else if(this.transform.scale < ZOOM_INITIAL_VALUE) {\n      this.resetZoom();\n    }\n  };\n\n  protected onZoom = ({\n    initialCenterX,\n    initialCenterY,\n    zoom,\n    zoomAdd,\n    currentCenterX,\n    currentCenterY,\n    dragOffsetX,\n    dragOffsetY,\n    zoomFactor\n  }: ZoomDetails) => {\n    initialCenterX ||= windowSize.width / 2;\n    initialCenterY ||= windowSize.height / 2;\n    currentCenterX ||= windowSize.width / 2;\n    currentCenterY ||= windowSize.height / 2;\n\n    this.isZoomingNow = true;\n\n    const zoomMaxBounceValue = ZOOM_MAX_VALUE * 3;\n    const scale = zoomAdd !== undefined ? clamp(this.lastTransform.scale + zoomAdd, ZOOM_MIN_VALUE, zoomMaxBounceValue) : (zoom ?? clamp(this.lastTransform.scale * zoomFactor, ZOOM_MIN_VALUE, zoomMaxBounceValue));\n    const scaleFactor = scale / this.lastTransform.scale;\n    const offsetX = Math.abs(Math.min(this.lastTransform.x, 0));\n    const offsetY = Math.abs(Math.min(this.lastTransform.y, 0));\n\n    // Save last zoom center for bounce back effect\n    this.lastZoomCenter = {\n      x: currentCenterX,\n      y: currentCenterY\n    };\n\n    // Calculate new center relative to the shifted image\n    const scaledCenterX = offsetX + initialCenterX;\n    const scaledCenterY = offsetY + initialCenterY;\n\n    const {scaleOffsetX, scaleOffsetY} = this.calculateScaleOffset({x: scaledCenterX, y: scaledCenterY, scale: scaleFactor});\n\n    const [transform] = this.calculateOffsetBoundaries({\n      x: this.lastTransform.x + scaleOffsetX + dragOffsetX,\n      y: this.lastTransform.y + scaleOffsetY + dragOffsetY,\n      scale\n    });\n\n    this.setTransform(transform);\n  };\n\n  protected changeZoomByPosition(x: number, y: number, scale: number) {\n    const {scaleOffsetX, scaleOffsetY} = this.calculateScaleOffset({x, y, scale});\n    const transform = this.calculateOffsetBoundaries({\n      x: scaleOffsetX,\n      y: scaleOffsetY,\n      scale\n    })[0];\n\n    this.setTransform(transform);\n  }\n\n  protected setTransform(transform: Transform) {\n    this.transform = transform;\n    this.changeZoom(transform.scale);\n  }\n\n  // Calculate how much we need to shift the image to keep the zoom center at the same position\n  protected calculateScaleOffset({x, y, scale}: {\n    x: number,\n    y: number,\n    scale: number\n  }) {\n    return {\n      scaleOffsetX: x - scale * x,\n      scaleOffsetY: y - scale * y\n    };\n  }\n\n  protected toggleZoom(enable?: boolean) {\n    const isVisible = this.isZooming;\n    const auto = enable === undefined;\n    if(this.zoomElements.rangeSelector.mousedown || this.ctrlKeyDown) {\n      enable = true;\n    }\n\n    enable ??= !isVisible;\n\n    if(isVisible === enable) {\n      return;\n    }\n\n    replaceButtonIcon(this.buttons.zoomin, !enable ? 'zoomin' : 'zoomout');\n    this.zoomElements.container.classList.toggle('is-visible', this.isZooming = enable);\n    this.wholeDiv.classList.toggle('is-zooming', enable);\n\n    if(auto || !enable) {\n      const zoomValue = enable ? this.transform.scale : ZOOM_INITIAL_VALUE;\n      this.setZoomValue(zoomValue);\n      this.zoomElements.rangeSelector.setProgress(zoomValue);\n    }\n\n    // Keep the controls hidden if still rotated even when zoom turns off.\n    this.updateVideoControlsLock();\n  }\n\n  protected addZoomStep(add: boolean) {\n    this.addZoom(ZOOM_STEP * (add ? 1 : -1));\n  }\n\n  protected resetZoom() {\n    this.setTransform({\n      x: 0,\n      y: 0,\n      scale: ZOOM_INITIAL_VALUE\n    });\n  }\n\n  protected changeZoom(value = this.transform.scale) {\n    this.transform.scale = value;\n    this.zoomElements.rangeSelector.setProgress(value);\n    this.setZoomValue(value);\n  }\n\n  protected addZoom(value: number) {\n    this.lastTransform = this.transform;\n    this.onZoom({\n      zoomAdd: value,\n      currentCenterX: 0,\n      currentCenterY: 0,\n      initialCenterX: 0,\n      initialCenterY: 0,\n      dragOffsetX: 0,\n      dragOffsetY: 0\n    });\n    this.lastTransform = this.transform;\n    this.clampZoomDebounced();\n  }\n\n  protected getZoomBounce() {\n    return this.isGesturingNow && IS_TOUCH_SUPPORTED ? 50 : 0;\n  }\n\n  protected calculateOffsetBoundaries = (\n    {x, y, scale}: Transform,\n    offsetTop = 0\n  ): [Transform, boolean, boolean] => {\n    if(!this.initialContentRect) return [{x, y, scale}, true, true];\n    // Get current content boundaries\n    let inBoundsX = true;\n    let inBoundsY = true;\n\n    const {minX, maxX, minY, maxY} = this.getZoomBoundaries(scale, offsetTop);\n\n    inBoundsX = isBetween(x, maxX, minX);\n    x = clamp(x, maxX, minX);\n\n    inBoundsY = isBetween(y, maxY, minY);\n    y = clamp(y, maxY, minY);\n\n    return [{x, y, scale}, inBoundsX, inBoundsY];\n  };\n\n  protected getZoomBoundaries(scale = this.transform.scale, offsetTop = 0) {\n    if(!this.initialContentRect) {\n      return {minX: 0, maxX: 0, minY: 0, maxY: 0};\n    }\n\n    const centerX = (windowSize.width - windowSize.width * scale) / 2;\n    const centerY = (windowSize.height - windowSize.height * scale) / 2;\n\n    // Pan/zoom act on the rotated+refit box in screen space, so the boundaries are\n    // computed from that box (= initialContentRect when unrotated).\n    const rect = this.getDisplayRect();\n    const minX = Math.max(-rect.left * scale, centerX);\n    const maxX = windowSize.width - rect.right * scale;\n\n    const minY = Math.max(-rect.top * scale + offsetTop, centerY);\n    const maxY = windowSize.height - rect.bottom * scale;\n\n    return {minX, maxX, minY, maxY};\n  }\n\n  protected setZoomValue = (value = this.transform.scale) => {\n    this.initialContentRect ??= this.content.media.getBoundingClientRect();\n\n    // this.zoomValue = value;\n    if(value === ZOOM_INITIAL_VALUE) {\n      this.transform.x = 0;\n      this.transform.y = 0;\n    }\n\n    this.applyMoversTransform(value);\n\n    this.zoomElements.btnOut.classList.toggle('inactive', value <= ZOOM_MIN_VALUE);\n    this.zoomElements.btnIn.classList.toggle('inactive', value >= ZOOM_MAX_VALUE);\n\n    this.toggleZoom(value !== ZOOM_INITIAL_VALUE);\n  };\n\n  protected applyMoversTransform(scaleValue = this.transform.scale) {\n    this.moversContainer.style.transform = this.buildMoversTransform(scaleValue);\n  }\n\n  // Composes the moversContainer transform. Order matters: zoom/pan (origin 0 0)\n  // are the OUTER (screen-space) transforms and the rotate+orientation-refit is the\n  // INNER one, applied to the media around its own center. Keeping pan/zoom in\n  // screen space means a drag maps straight to the on-screen axes even when rotated\n  // (so a sideways→horizontal photo pans left-right, not up-down) and the boundary\n  // math only needs the rotated bounding box (getDisplayRect). The rotate wrapper is\n  // ALWAYS emitted (identity when rotation is 0 — the translate(C)…translate(-C)\n  // pair cancels through it at every interpolation step, so a zoom is animated and\n  // rendered exactly as before) so that the FIRST turn interpolates the transform\n  // function-by-function instead of matrix-decomposing from a bare zoom (which slid\n  // the image off before settling).\n  protected buildMoversTransform(scaleValue = this.transform.scale) {\n    const {x, y} = this.transform;\n    const fit = this.getRotationFitScale();\n    const {x: cx, y: cy} = this.getMediaCenter();\n    return `translate3d(${x.toFixed(3)}px, ${y.toFixed(3)}px, 0px) scale(${scaleValue.toFixed(3)}) ` +\n      `translate(${cx.toFixed(3)}px, ${cy.toFixed(3)}px) rotate(${this.rotation}deg) scale(${fit.toFixed(5)}) translate(${(-cx).toFixed(3)}px, ${(-cy).toFixed(3)}px)`;\n  }\n\n  // The media's center on screen at rest (pre zoom/pan). With the rotation applied\n  // as the inner transform, this is the pivot the media turns around — constant, not\n  // dependent on the current zoom/pan.\n  protected getMediaCenter() {\n    const rect = this.initialContentRect ?? this.content.media.getBoundingClientRect();\n    return {\n      x: rect.left + rect.width / 2,\n      y: rect.top + rect.height / 2\n    };\n  }\n\n  // After a 90°/270° turn the media's bounding box has width/height swapped; scale\n  // it so the rotated box fits (and fills) the available viewport in the new\n  // orientation — same behaviour as Telegram Desktop. 0°/180° keep the box, so fit\n  // is 1. Independent of zoom (zoom multiplies on top in screen space).\n  protected getRotationFitScale(rotation = this.rotation) {\n    const normalized = ((rotation % 360) + 360) % 360;\n    if(normalized !== 90 && normalized !== 270) {\n      return 1;\n    }\n\n    const rect = this.initialContentRect ?? this.content.media.getBoundingClientRect();\n    const {width, height} = rect;\n    if(!width || !height) {\n      return 1;\n    }\n\n    const box = this.mediaBoxSize;\n    return Math.min(box.width / height, box.height / width);\n  }\n\n  // The media's on-screen bounding box AFTER rotation + orientation-refit (still in\n  // the pre-zoom frame). Pan/zoom apply to THIS box in screen space, so the zoom\n  // boundaries derive from it directly. Unrotated → just initialContentRect.\n  protected getDisplayRect(): DOMRectMinified & {width: number, height: number} {\n    const rect = this.initialContentRect ?? this.content.media.getBoundingClientRect();\n    if(!this.rotation) {\n      return rect;\n    }\n\n    const normalized = ((this.rotation % 360) + 360) % 360;\n    const swap = normalized === 90 || normalized === 270;\n    const fit = this.getRotationFitScale();\n    const cx = rect.left + rect.width / 2;\n    const cy = rect.top + rect.height / 2;\n    const width = (swap ? rect.height : rect.width) * fit;\n    const height = (swap ? rect.width : rect.height) * fit;\n    return {\n      left: cx - width / 2,\n      right: cx + width / 2,\n      top: cy - height / 2,\n      bottom: cy + height / 2,\n      width,\n      height\n    };\n  }\n\n  protected rotateMedia() {\n    // Prime the transition ONLY on the first transform application (moversContainer\n    // still on its CSS default, no inline transform): commit an identity-structured\n    // transform so the first turn interpolates rotate/scale function-by-function\n    // instead of matrix-decomposing from the bare default (which slid the image off\n    // before settling). Once an inline transform exists (after any zoom/rotate) it's\n    // already in that form — re-priming here would add `no-transition` mid-flight and\n    // snap a still-animating turn to its target.\n    if(!this.moversContainer.style.transform) {\n      this.moversContainer.classList.add('no-transition');\n      this.applyMoversTransform();\n      void this.moversContainer.offsetLeft; // reflow to commit the primed state\n      this.moversContainer.classList.remove('no-transition');\n    }\n\n    this.rotation -= 90; // counterclockwise, matching Telegram Desktop\n    this.applyMoversTransform();\n    this.updateVideoControlsLock();\n  }\n\n  // True when the media is visually turned (any non-360° multiple). −360° reads as\n  // upright, so compare the normalized angle, not the raw accumulator.\n  protected isRotated() {\n    return (((this.rotation % 360) + 360) % 360) !== 0;\n  }\n\n  // A video's player chrome lives inside moversContainer, so it would scale/turn with\n  // the frame. Mirror what zoom already does — lock the controls hidden while zoomed\n  // OR rotated, restore auto-hide otherwise. (Keyboard controls keep working via the\n  // player's `listenKeyboardEvents: 'always'`, so playback is still controllable.)\n  protected updateVideoControlsLock() {\n    if(!this.videoPlayer) {\n      return;\n    }\n\n    this.videoPlayer.lockControls(this.isZooming || this.isRotated() ? false : undefined);\n  }\n\n  protected setBtnMenuToggle(buttons: ButtonMenuItemOptionsVerifiable[]) {\n    const btnMenuToggle = ButtonMenuToggle({buttonOptions: {onlyMobile: true}, direction: 'bottom-left', buttons});\n    this.topbar.append(btnMenuToggle);\n  }\n\n  public close(e?: MouseEvent) {\n    this.disposeSolid?.();\n\n    if(e) {\n      cancelEvent(e);\n    }\n\n    if(this.closing) {\n      return this.setMoverAnimationPromise;\n    }\n\n    if(this.setMoverAnimationPromise) return Promise.reject();\n\n    this.closing = true;\n    this.swipeHandler?.removeListeners();\n\n    if(this.navigationItem) {\n      appNavigationController.removeItem(this.navigationItem);\n    }\n\n    this.lazyLoadQueue.clear();\n    this.author.avatarMiddlewareHelper?.destroy();\n\n    const promise = this.setMoverToTarget(this.target?.element, true).then(({onAnimationEnd}) => onAnimationEnd);\n\n    this.listLoader.reset();\n    (this.listLoader as SearchListLoader<any>).cleanup && (this.listLoader as SearchListLoader<any>).cleanup();\n    this.setMoverPromise = null;\n    this.tempId = -1;\n    if((window as any).appMediaViewer === this) {\n      (window as any).appMediaViewer = undefined;\n    }\n\n    /* if(appSidebarRight.historyTabIDs.slice(-1)[0] === AppSidebarRight.SLIDERITEMSIDS.forward) {\n      promise.then(() => {\n        appSidebarRight.forwardTab.closeBtn.click();\n      });\n    } */\n\n    this.removeGlobalListeners();\n\n    promise.finally(() => {\n      this.wholeDiv.remove();\n      this.toggleOverlay(false);\n      this.middlewareHelper.destroy();\n    });\n\n    return promise;\n  }\n\n  protected toggleOverlay(active: boolean) {\n    if(this.overlayActive === active) {\n      return;\n    }\n\n    this.overlayActive = active;\n    overlayCounter.isDarkOverlayActive = active;\n    animationIntersector.checkAnimations2(active);\n  }\n\n  protected toggleGlobalListeners(active: boolean) {\n    if(active) this.setGlobalListeners();\n    else this.removeGlobalListeners();\n  }\n\n  protected removeGlobalListeners() {\n    getAppWindow().removeEventListener('keydown', this.onKeyDown);\n    getAppWindow().removeEventListener('keyup', this.onKeyUp);\n    mediaSizes.removeEventListener('resize', this.applyLayoutVariables);\n  }\n\n  protected setGlobalListeners() {\n    // Keyboard nav (arrows / space / Esc) on the active window — the viewer opens in whichever window\n    // the app is in (the tab, or the Document PiP window); a main-`window` listener is dead in the PiP.\n 