rnType<AppMediaPlaybackController['setSingleMedia']>/* , _onAnotherSingleMedia: () => void */;\n    // const detachClickEvent = attachClickEvent(button, (e) => {\n    //   cancelEvent(e);\n    //   toggle();\n    // });\n\n    const onIntersection: IntersectionCallback = (entry) => {\n      if(!entry.isIntersecting) {\n        destroyPlayer();\n      }\n\n      if(!entry.isIntersecting && !video.muted) {\n        // toggle(false);\n        onMuted();\n      }\n    };\n\n    container.classList.add('media-video-container', 'media-video-mini');\n    observer.observe(video, onIntersection);\n\n    const destroyPlayer = () => {\n      debouncedDestroy.clearTimeout();\n      if(\n        !videoPlayer ||\n        !middleware() ||\n        isFullScreen() ||\n        videoPlayer.inPip\n      ) {\n        return;\n      }\n\n      videoPlayer.unmount();\n      videoPlayer.cleanup();\n      videoPlayer = undefined;\n      setShowControlsOn.classList.remove('show-controls');\n    };\n\n    const debouncedDestroy = debounce(destroyPlayer, 1000, false, true);\n\n    let videoPlayer: VideoPlayer, releasePromise: CancellablePromise<void>/* , changedVolume = false */;\n    container.onMiniVideoMouseMove = (e: MouseEvent) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      const toggleReleasePromise = (active: boolean) => {\n        if(active) releasePromise = deferredPromise();\n        else releasePromise?.resolve();\n      };\n\n      const onLock = (active: boolean) => {\n        if(ignoreNextEvents && ignoreNextEvents--) {\n          return;\n        }\n\n        const animationItem = animationIntersector.getAnimations(video)[0];\n        animationIntersector.toggleItemLock(animationItem, active);\n        toggleReleasePromise(active);\n      };\n\n      let ignoreNextEvents = 0;\n      videoPlayer = new VideoPlayer({\n        video,\n        container,\n        duration: video.duration,\n        streamable: true,\n        listenKeyboardEvents: 'fullscreen',\n        useGlobalVolume: 'no-init',\n        // shouldEnableSoundOnClick: () => !changedVolume,\n        onVolumeChange: (type) => {\n          const noVolume = !video.volume || video.muted;\n          let newValue: boolean;\n          if(noVolume) {\n            newValue = turnedObserverOn = false;\n          } else if(type === 'click') {\n            newValue = turnedObserverOn = true;\n          }\n\n          if(newValue !== turnedObserverOn && newValue !== undefined) {\n            appMediaPlaybackController.dispatchEvent('toggleVideoAutoplaySound', newValue);\n          }\n\n          // changedVolume = true;\n          // (!video.volume || video.muted ? mute : unmute)();\n        },\n        onFullScreen: (active) => {\n          onLock(active);\n          overlayCounter.isDarkOverlayActive = active;\n        },\n        onFullScreenToPip: () => {\n          ignoreNextEvents = 2;\n        },\n        onPip: onLock/* ,\n        onPipClose: () => {\n          if(!setShowControlsOn.classList.contains('show-controls')) {\n            debouncedDestroy();\n          }\n        } */\n      });\n\n      videoPlayer.volumeSelector.setVolume({muted: !turnedObserverOn, volume: video.volume});\n\n      videoPlayer.addEventListener('toggleControls', (show) => {\n        setShowControlsOn.classList.toggle('show-controls', show);\n        if(show) {\n          debouncedDestroy.clearTimeout();\n        } else {\n          debouncedDestroy();\n        }\n      });\n    };\n\n    // * mute video when other media is playing\n    const onAutoplaySound = (enabled: boolean) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      video.muted = appMediaPlaybackController.muted;\n      video.volume = Math.min(appMediaPlaybackController.volume, 1);\n    };\n\n    const onSingleMedia = (media: HTMLMediaElement) => {\n      if(media !== video && !video.muted) {\n        if(videoPlayer) {\n          videoPlayer.volumeSelector.setVolume({muted: true, volume: video.volume});\n        } else {\n          video.muted = true;\n        }\n      }\n    };\n\n    const onPlaybackMediaParams = (params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      video.muted = turnedObserverOn ? params.muted : true;\n      video.playbackRate = params.playbackRate;\n      video.volume = Math.min(params.volume, 1);\n    };\n\n    appMediaPlaybackController.addEventListener('toggleVideoAutoplaySound', onAutoplaySound);\n    // appMediaPlaybackController.addEventListener('singleMedia', onSingleMedia);\n    appMediaPlaybackController.addEventListener('playbackParams', onPlaybackMediaParams);\n\n    middleware.onClean(() => {\n      // detachClickEvent();\n      releaseSingleMedia?.();\n      observer.unobserve(video, onIntersection);\n      delete container.onMiniVideoMouseMove;\n      appMediaPlaybackController.removeEventListener('toggleVideoAutoplaySound', onAutoplaySound);\n      // appMediaPlaybackController.removeEventListener('singleMedia', onSingleMedia);\n      appMediaPlaybackController.removeEventListener('playbackParams', onPlaybackMediaParams);\n    });\n\n    originalMiddleware.onClean(async() => {\n      await releasePromise;\n      myMiddlewareHelper.destroy();\n    });\n  } : undefined;\n\n  return res;\n}\n","import {createEffect, createMemo, createRoot} from 'solid-js';\nimport {useAppConfig, useAppState} from '@stores/appState';\nimport {ignoreRestrictionReasons} from '@helpers/restrictions';\n\nexport default function useContentSettings() {\n  const appConfig = useAppConfig();\n  const [appState] = useAppState();\n\n  const contentSettings = createMemo(() => appState.accountContentSettings.value);\n  const sensitiveEnabled = createMemo(() => (contentSettings() && contentSettings().pFlags.sensitive_enabled) ?? false);\n  const sensitiveCanChange = createMemo(() => (contentSettings() && contentSettings().pFlags.sensitive_can_change) ?? false);\n  const ignoreRestrictionReasons = createMemo(() => appConfig.ignore_restriction_reasons ?? []);\n  const needAgeVerification = createMemo(() => appConfig.need_age_video_verification ?? false);\n  const ageVerified = createMemo(() => !!appState.ageVerification);\n\n  return {\n    sensitiveEnabled,\n    sensitiveCanChange,\n    needAgeVerification,\n    ageVerified,\n    ignoreRestrictionReasons\n  };\n}\n\n// * handle settings changes\ncreateRoot(() => {\n  const contentSettings = useContentSettings();\n  createEffect(() => {\n    ignoreRestrictionReasons(contentSettings.ignoreRestrictionReasons());\n  });\n});\n","import PopupElement from '.';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport safeAssign from '@helpers/object/safeAssign';\nimport appImManager from '@lib/appImManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport useContentSettings from '@stores/contentSettings';\nimport Button from '@components/buttonTsx';\nimport styles from '@components/popups/ageVerification.module.scss';\n\nexport class AgeVerificationPopup extends PopupElement {\n  private onVerify: (verified: boolean) => void;\n\n  constructor(options: {\n    onVerify: (verified: boolean) => void\n  }) {\n    super(styles.popup, {\n      title: 'AgeVerification.Title',\n      body: true,\n      closable: true,\n      overlayClosable: true\n    })\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  _switchedToWebApp = false;\n\n  private async construct() {\n    const appConfig = await this.managers.apiManager.getAppConfig();\n    this.appendSolidBody(() => this._construct({appConfig}));\n  }\n\n  protected _construct({appConfig}: {appConfig: MTAppConfig}) {\n    let textKey: LangPackKey;\n    if(appConfig.verify_age_country === 'GB') {\n      textKey = 'AgeVerification.TextGB';\n    } else {\n      textKey = 'AgeVerification.Text';\n    }\n\n    const handleVerify = async() => {\n      const bot = await this.managers.appUsersManager.resolveUserByUsername(\n        appConfig.verify_age_bot_username ?? 'TelegramAge'\n      );\n      this._switchedToWebApp = true;\n      this.destroy();\n      appImManager.openWebApp({\n        botId: bot.id,\n        main: true,\n        noConfirmation: true,\n        forcePopup: true,\n        onClose: () => {\n          this.onVerify(!!useContentSettings().ageVerified());\n        }\n      });\n    };\n\n    return (\n      <>\n        <div class={styles.text}>\n          {i18n(textKey)}\n        </div>\n        <Button class={`${styles.button} btn-color-primary btn-primary`} onClick={handleVerify}>\n          {i18n('AgeVerification.Action')}\n        </Button>\n      </>\n    );\n  }\n\n  static create(): Promise<boolean> {\n    const promise = deferredPromise<boolean>();\n    const popup = PopupElement.createPopup(AgeVerificationPopup, {\n      onVerify: (verified) => promise.resolve(verified)\n    });\n\n    popup.addEventListener('close', () => {\n      if(!popup._switchedToWebApp) {\n        promise.resolve(false);\n      }\n    });\n    popup.show();\n\n    return promise;\n  }\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport safePlay from '@helpers/dom/safePlay';\nimport getImageFromStrippedThumb from '@helpers/getImageFromStrippedThumb';\nimport {Document, Photo, PhotoSize} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport useContentSettings from '@stores/contentSettings';\nimport confirmationPopup from '@components/confirmationPopup';\nimport DotRenderer from '@components/dotRenderer';\nimport Icon from '@components/icon';\nimport {AgeVerificationPopup} from '@components/popups/ageVerification';\nimport SetTransition from '@components/singleTransition';\nimport {toastNew} from '@components/toast';\n\nconst sensitiveSpoilers = new Set<HTMLElement>();\n\nexport function clearSensitiveSpoilers() {\n  for(const spoiler of sensitiveSpoilers) {\n    toggleMediaSpoiler({\n      mediaSpoiler: spoiler,\n      reveal: true,\n      destroyAfter: true\n    });\n  }\n  sensitiveSpoilers.clear();\n}\n\nexport function toggleMediaSpoiler(options: {\n  mediaSpoiler: HTMLElement,\n  reveal: boolean,\n  destroyAfter?: boolean\n}) {\n  const {mediaSpoiler, reveal, destroyAfter} = options;\n  SetTransition({\n    element: mediaSpoiler,\n    forwards: reveal,\n    className: 'is-revealing',\n    duration: 250,\n    onTransitionEnd: () => {\n      if(reveal && destroyAfter) {\n        mediaSpoiler.remove();\n        mediaSpoiler.middlewareHelper.destroy();\n      }\n    }\n  });\n}\n\n\nfunction revealSpoilerWithAnimation(options: {\n  mediaSpoiler: HTMLElement,\n  event: Event\n}) {\n  const {mediaSpoiler, event} = options;\n\n  const thumbnailCanvas = mediaSpoiler.querySelector('canvas.media-spoiler-thumbnail') as HTMLCanvasElement;\n  const canvas = mediaSpoiler.querySelector('canvas.canvas-dots') as HTMLElement;\n\n  const controls = DotRenderer.getImageSpoilerByElement(canvas);\n\n  if(!controls || !thumbnailCanvas) return false;\n\n  const result = controls.revealWithAnimation(event, thumbnailCanvas);\n  if(!result) return false;\n\n  return result.then(() => {\n    mediaSpoiler?.remove?.();\n    mediaSpoiler?.middlewareHelper?.destroy?.();\n  });\n}\n\nexport function onMediaSpoilerClick(options: {\n  mediaSpoiler: HTMLElement,\n  event: Event\n}) {\n  const {mediaSpoiler, event} = options;\n  const contentSettings = useContentSettings();\n  cancelEvent(event);\n\n  if(mediaSpoiler.classList.contains('is-revealing') || mediaSpoiler.dataset.isRevealing) {\n    return;\n  }\n\n  if(mediaSpoiler.dataset.isSensitive) {\n    if(!contentSettings.sensitiveCanChange()) {\n      toastNew({langPackKey: 'SensitiveContentUnavailable'});\n      return;\n    }\n\n    if(contentSettings.needAgeVerification() && !contentSettings.ageVerified()) {\n      AgeVerificationPopup.create().then((verified) => {\n        if(verified) {\n          clearSensitiveSpoilers();\n        }\n      });\n      return;\n    }\n\n    confirmationPopup({\n      titleLangKey: '18Plus',\n      descriptionLangKey: 'SensitiveContentDesc',\n      button: {\n        langKey: 'SensitiveContentConfirm'\n      },\n      checkbox: {\n        text: 'SensitiveContentRemember'\n      }\n    }).then((remember) => {\n      if(remember) {\n        rootScope.managers.appPrivacyManager.setContentSettings({sensitive_enabled: true});\n        clearSensitiveSpoilers();\n        return\n      }\n\n      delete mediaSpoiler.dataset.isSensitive;\n      onMediaSpoilerClick(options);\n    })\n    return;\n  }\n\n  const video = mediaSpoiler.parentElement.querySelector('video');\n  if(video && !mediaSpoiler.parentElement.querySelector('.video-play')) {\n    video.autoplay = true;\n    safePlay(video);\n  }\n\n  if(revealSpoilerWithAnimation({mediaSpoiler, event})) {\n    mediaSpoiler.dataset.isRevealing = 'true';\n    return;\n  }\n\n  toggleMediaSpoiler({\n    mediaSpoiler,\n    reveal: true,\n    destroyAfter: true\n  });\n}\n\nfunction wrapMediaSpoilerWithImage(options: {\n  image: Awaited<ReturnType<typeof getImageFromStrippedThumb>>['image']\n} & Parameters<typeof DotRenderer['create']>[0]) {\n  const {middleware, image} = options;\n  if(!middleware()) {\n    return;\n  }\n\n  image.classList.add('media-spoiler-thumbnail');\n\n  const container = document.createElement('div');\n  container.classList.add('media-spoiler-container');\n  container.middlewareHelper = middleware.create();\n\n  const {canvas, readyResult} = DotRenderer.create({\n    ...options,\n    middleware: container.middlewareHelper.get()\n  });\n\n  container.append(image, canvas);\n\n  return {container, readyResult};\n}\n\nexport function hasSensitiveSpoiler(container: HTMLElement) {\n  return container.querySelector('.media-spoiler-container[data-is-sensitive]') != null;\n}\n\nexport default async function wrapMediaSpoiler(\n  options: Omit<Parameters<typeof wrapMediaSpoilerWithImage>[0], 'image'> & {\n    media: Document.document | Photo.photo,\n    sensitive?: boolean\n  }\n) {\n  const {media, sensitive} = options;\n  const sizes = (media as Photo.photo).sizes || (media as Document.document).thumbs;\n  const thumb = sizes.find((size) => size._ === 'photoStrippedSize') as PhotoSize.photoStrippedSize;\n  if(!thumb) {\n    return;\n  }\n\n  const {image, loadPromise} = getImageFromStrippedThumb(media, thumb, true);\n  await loadPromise;\n\n  const {container, readyResult} = wrapMediaSpoilerWithImage({\n    ...options,\n    image\n  });\n\n  if(sensitive) {\n    const div = document.createElement('div');\n    div.classList.add('sensitive-content-warning');\n    div.replaceChildren(Icon('eyecross_outline'), i18n('18Plus'));\n    container.prepend(div);\n    container.dataset.isSensitive = 'true';\n    sensitiveSpoilers.add(container);\n    options.middleware.onClean(() => {\n      sensitiveSpoilers.delete(container);\n    });\n  }\n\n  if(readyResult instanceof Promise) {\n    await readyResult;\n  }\n\n  return container;\n}\n","import {Middleware} from '@helpers/middleware';\nimport {Document, Message, MessageMedia, Photo, WebPage, VideoSize, StoryItem, MessageReplyHeader, MessageEntity} from '@layer';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport DivAndCaption from '@components/divAndCaption';\nimport wrapMessageForReply from '@components/wrappers/messageForReply';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapSticker from '@components/wrappers/sticker';\nimport wrapVideo from '@components/wrappers/video';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport {WrapReplyOptions} from '@components/wrappers/reply';\nimport {Modify} from '@types';\nimport {i18n} from '@lib/langPack';\nimport Icon from '@components/icon';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport compareUint8Arrays from '@helpers/bytes/compareUint8Arrays';\n\nconst MEDIA_SIZE = 32;\n\nexport type WrapReplyMediaOptions = {\n  message?: Message.message | Message.messageService,\n  storyItem?: StoryItem.storyItem,\n  replyHeader?: MessageReplyHeader,\n  mediaEl: HTMLElement,\n  size?: number,\n  isSensitive?: boolean,\n  middleware?: Middleware,\n  lazyLoadQueue?: false | LazyLoadQueue,\n  loadPromises?: Promise<any>[],\n  animationGroup?: WrapRichTextOptions['animationGroup']\n};\n\n/**\n * Render a small thumbnail of the media attached to a message (or story item)\n * into `mediaEl`. Handles photos, videos (via thumbs), stickers, gifs, and\n * round videos. Returns `{setMedia, isRound}` describing whether anything was\n * inserted and whether it should be drawn as a circle.\n *\n * Extracted from `wrapReplyDivAndCaption` so the same render can be reused\n * outside of reply-style previews (e.g. day cells in the date-picker calendar).\n */\nexport async function wrapReplyMedia({\n  message,\n  storyItem,\n  replyHeader,\n  mediaEl,\n  size = MEDIA_SIZE,\n  isSensitive,\n  middleware,\n  lazyLoadQueue,\n  loadPromises,\n  animationGroup\n}: WrapReplyMediaOptions): Promise<{setMedia: boolean, isRound: boolean}> {\n  loadPromises ??= [];\n\n  let messageMedia: MessageMedia | WebPage.webPage = storyItem?.media ||\n    (message as Message.message)?.media ||\n    (replyHeader?._ === 'messageReplyHeader' && replyHeader.reply_media);\n\n  if(messageMedia?._ === 'messageMediaStory') {\n    storyItem = messageMedia.story as StoryItem.storyItem;\n    messageMedia = storyItem?.media;\n  }\n\n  let setMedia = false, isRound = false;\n  if(!messageMedia || !mediaEl || (messageMedia as MessageMedia.messageMediaPhoto).ttl_seconds) {\n    return {setMedia, isRound};\n  }\n\n  messageMedia = (messageMedia as MessageMedia.messageMediaWebPage).webpage as WebPage.webPage || messageMedia;\n  const photo = (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo;\n  const document = (messageMedia as MessageMedia.messageMediaDocument).document as Document.document;\n  const spoiler = (messageMedia as MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument)?.pFlags?.spoiler;\n\n  if(!photo && !(document && document.thumbs?.length)) {\n    return {setMedia, isRound};\n  }\n\n  if(document?.type === 'sticker') {\n    await wrapSticker({\n      doc: document,\n      div: mediaEl,\n      lazyLoadQueue: lazyLoadQueue || undefined,\n      group: animationGroup,\n      width: size,\n      height: size,\n      middleware,\n      loadPromises\n    });\n    setMedia = true;\n  } else if(document?.type === 'gif' && document.video_thumbs) {\n    setMedia = true;\n    await wrapVideo({\n      doc: document,\n      container: mediaEl,\n      boxWidth: size,\n      boxHeight: size,\n      lazyLoadQueue: lazyLoadQueue || undefined,\n      noPlayButton: true,\n      noInfo: true,\n      middleware,\n      loadPromises,\n      withoutPreloader: true,\n      videoSize: document.video_thumbs[0] as Extract<VideoSize, VideoSize.videoSize>,\n      group: animationGroup\n    });\n  } else {\n    const m = photo || document;\n    isRound = document?.type === 'round';\n\n    try {\n      await wrapPhoto({\n        photo: m,\n        container: mediaEl,\n        boxWidth: size,\n        boxHeight: size,\n        size: choosePhotoSize(m, size, size),\n        middleware,\n        lazyLoadQueue,\n        noBlur: true,\n        withoutPreloader: true,\n        loadPromises\n      });\n\n      if(spoiler || isSensitive) {\n        const spoilerEl = await wrapMediaSpoiler({\n          media: m,\n          width: size,\n          height: size,\n          multiply: 0.1,\n          middleware,\n          animationGroup\n        });\n        mediaEl.append(spoilerEl);\n      }\n\n      setMedia = true;\n    } catch(err) {\n\n    }\n  }\n\n  return {setMedia, isRound};\n}\n\nexport async function wrapReplyDivAndCaption(options: {\n  title?: string | HTMLElement | DocumentFragment,\n  titleEl: HTMLElement,\n  subtitle?: string | HTMLElement | DocumentFragment,\n  subtitleEl: HTMLElement,\n  message: Message.message | Message.messageService,\n  storyItem?: StoryItem.storyItem,\n  mediaEl: HTMLElement,\n  isStoryExpired?: boolean,\n  isSensitive?: boolean,\n  middleware?: Middleware,\n  lazyLoadQueue?: false | LazyLoadQueue,\n  replyHeader?: MessageReplyHeader,\n  quote?: {text: string, entities?: MessageEntity[]},\n  withoutMediaType?: boolean,\n  canTranslate?: boolean\n} & WrapRichTextOptions) {\n  options.loadPromises ||= [];\n\n  const {titleEl, subtitleEl, mediaEl, message, loadPromises, animationGroup, middleware, lazyLoadQueue, replyHeader} = options;\n  let {storyItem, quote} = options;\n  let quoteIcon: HTMLElement | undefined;\n\n  let wrappedTitle = options.title;\n  if(wrappedTitle !== undefined) {\n    if(typeof(wrappedTitle) === 'string') {\n      wrappedTitle = limitSymbols(wrappedTitle, 140);\n      wrappedTitle = wrapEmojiText(wrappedTitle);\n    }\n\n    replaceContent(titleEl, wrappedTitle);\n  } else if(options.isStoryExpired) {\n    const icon = Icon('bomb', 'expired-story-icon');\n    titleEl.append(icon, i18n('ExpiredStory'));\n  }\n\n  const isMessageReply = replyHeader?._ === 'messageReplyHeader';\n\n  if(isMessageReply && replyHeader.quote_text) {\n    quote ??= {\n      text: replyHeader.quote_text,\n      entities: replyHeader.quote_entities\n    };\n  }\n\n  if(isMessageReply && replyHeader.poll_option && message?._ === 'message' && message.media?._ === 'messageMediaPoll') {\n    const pollOption = message.media.poll.answers.find(answer => answer._ === 'pollAnswer' && compareUint8Arrays(replyHeader.poll_option, answer.option));\n    if(pollOption) {\n      quoteIcon = Icon('checkround_filled', 'inline-icon', 'inline-icon-left');\n      quote ??= {\n        text: pollOption.text.text,\n        entities: pollOption.text.entities\n      };\n    }\n  }\n\n  const mediaChildren = mediaEl ? Array.from(mediaEl.children).slice() : [];\n  const {setMedia, isRound} = await wrapReplyMedia({\n    message,\n    storyItem,\n    replyHeader,\n    mediaEl,\n    isSensitive: options.isSensitive,\n    middleware,\n    lazyLoadQueue,\n    loadPromises,\n    animationGroup\n  });\n\n  if(options.subtitle !== undefined) {\n    let wrappedSubtitle = options.subtitle;\n    if(typeof(wrappedSubtitle) === 'string') {\n      wrappedSubtitle = limitSymbols(wrappedSubtitle, 140);\n      wrappedSubtitle = wrapEmojiText(wrappedSubtitle);\n    }\n\n    replaceContent(subtitleEl, wrappedSubtitle || '');\n  } else if(storyItem && options.storyItem) {\n    subtitleEl.replaceChildren(i18n('Story'));\n  } else if(options.isStoryExpired) {\n    const icon = Icon('bomb', 'expired-story-icon');\n    subtitleEl.replaceChildren(icon, i18n('ExpiredStory'));\n  } else if(quote) {\n    const fragment = wrapRichText(limitSymbols(quote.text, 200), {\n      ...options,\n      noLinebreaks: true,\n      entities: quote.entities,\n      noLinks: true\n      // noTextFormat: true\n    });\n\n    subtitleEl.replaceChildren(...[quoteIcon, fragment].filter(Boolean));\n  } else if(message) {\n    const fragment = await wrapMessageForReply(options);\n    subtitleEl.replaceChildren(fragment);\n  }\n\n  // if(options.isStoryExpired) {\n  //   setMedia = true;\n  // }\n\n  Promise.all(loadPromises).then(() => {\n    if(middleware && !middleware()) return;\n    mediaChildren.forEach((child) => child.remove());\n\n    if(mediaEl) {\n      mediaEl.classList.toggle('is-round', isRound);\n    }\n  });\n\n  return setMedia;\n}\n\nexport default class ReplyContainer extends DivAndCaption<(options: WrapReplyOptions) => Promise<void>> {\n  private mediaEl: HTMLElement;\n\n  constructor(protected className: string) {\n    super(className, async(options) => {\n      if(!this.mediaEl) {\n        this.mediaEl = document.createElement('div');\n        this.mediaEl.classList.add(this.className + '-media');\n      }\n\n      const isMediaSet = await wrapReplyDivAndCaption({\n        ...(options as Modify<typeof options, {message: Message.message | Message.messageService}>),\n        isSensitive: options.isChatSensitive || (options.message && isMessageSensitive(options.message)),\n        titleEl: this.title,\n        subtitleEl: this.subtitle,\n        mediaEl: this.mediaEl\n      });\n\n      if(options.isStoryExpired) {\n        // this.mediaEl.classList.add('is-expired-story', 'tgico-clock');\n        this.container.classList.add('is-expired-story');\n      }\n\n      this.container.classList.toggle('is-media', isMediaSet);\n      if(isMediaSet) {\n        this.content.prepend(this.mediaEl);\n      } else {\n        this.mediaEl.remove();\n      }\n    });\n  }\n}\n","import {createSignal, createEffect, on, JSX, onCleanup, catchError} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport rootScope from '@lib/rootScope';\nimport {Photo, StoryItem, Document, MessageMedia, Message} from '@layer';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapVideo from '@components/wrappers/video';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {AnimationItemGroup} from '@components/animationIntersector';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {ChatAutoDownloadSettings} from '@hooks/useAutoDownloadSettings';\n\nlet processing = false;\nconst pollStories = () => {\n  if(processing) return;\n  const promises: PromiseLike<any>[] = [];\n  wrappedStories.forEach((map, peerId) => {\n    const ids = [...map.keys()];\n    const promise = rootScope.managers.appStoriesManager.getStoriesById(peerId, ids, true).then(() => {\n      ids.forEach((id) => {\n        if(!map.get(id).mounted) {\n          map.delete(id);\n          if(!map.size) {\n            wrappedStories.delete(peerId);\n          }\n        }\n      });\n    });\n\n    promises.push(promise);\n  });\n\n  Promise.all(promises).then(() => {\n    processing = false;\n  });\n};\n\nconst wrappedStories: Map<PeerId, Map<number, {mounted: number}>> = new Map();\n(window as any).wrappedStories = wrappedStories;\nsetInterval(pollStories, 300e3);\n\ntype CommonProperties = {\n  peerId: PeerId,\n  message?: Message.message,\n  boxWidth?: number,\n  boxHeight?: number,\n  withPreloader?: boolean,\n  noInfo?: boolean,\n  group?: AnimationItemGroup,\n  lazyLoadQueue?: LazyLoadQueue,\n  autoDownload?: ChatAutoDownloadSettings,\n  canAutoplay?: boolean,\n  noAspecter?: boolean\n};\n\nexport const wrapStoryMedia = (props: {\n  storyItem: StoryItem.storyItem,\n  forPreview?: boolean,\n  forViewer?: boolean,\n  containerProps?: JSX.HTMLAttributes<HTMLDivElement>,\n  childrenClassName?: string,\n  noPlayButton?: boolean,\n  onlyPreview?: boolean,\n  useBlur?: boolean | number\n} & CommonProperties) => {\n  const [thumb, setThumb] = createSignal<HTMLImageElement | HTMLCanvasElement>();\n  const [media, setMedia] = createSignal<HTMLImageElement | HTMLVideoElement>();\n  const [ready, setReady] = createSignal(false);\n\n  let map = wrappedStories.get(props.peerId);\n  if(!map) {\n    wrappedStories.set(props.peerId, map = new Map());\n  }\n\n  let c = map.get(props.storyItem.id);\n  if(!c) {\n    map.set(props.storyItem.id, c = {mounted: 0});\n  }\n  ++c.mounted;\n  onCleanup(() => {\n    --c.mounted;\n  });\n\n  const messageMedia = unwrap(props.storyItem.media);\n  const middleware = createMiddleware().get();\n\n  let div: HTMLDivElement;\n  const container = <div ref={div} {...(props.containerProps || {})}></div>;\n\n  const setChildrenClassName = (wrapped: {images: {thumb: HTMLElement, full: HTMLElement}}, className: string) => {\n    [\n      wrapped.images.thumb,\n      wrapped.images.full\n    ].filter(Boolean).forEach((image) => {\n      image.classList.add(className);\n    });\n  };\n\n  const wrappers = {\n    photo: (messageMedia: MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument) => {\n      const photo = (messageMedia as MessageMedia.messageMediaDocument).document as Document.document || (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo;\n      const result = wrapPhoto({\n        ...props,\n        container: div,\n        photo,\n        middleware,\n        ...(props.forPreview && {\n          ...(props.noAspecter && {\n            size: choosePhotoSize(photo, 150, 200)\n          }),\n          // size: choosePhotoSize(photo, 150, 200),\n          useRenderCache: false\n        }),\n        ...(props.forViewer && {\n          size: choosePhotoSize(photo, Infinity, Infinity),\n          // noBlur: true,\n          noFadeIn: true\n          // noThumb: true\n        }),\n        withoutPreloader: !props.withPreloader\n      });\n\n      result.then(async(result) => {\n        if(!middleware()) return;\n        if(props.childrenClassName) setChildrenClassName(result, props.childrenClassName);\n        await result.loadPromises.thumb;\n        if(!middleware()) return;\n        setThumb(result.images.thumb);\n        setReady(true);\n        await result.loadPromises.full;\n        if(!middleware()) return;\n        setMedia(result.images.full);\n      });\n\n      return result;\n    },\n\n    video: (messageMedia: MessageMedia.messageMediaDocument) => {\n      const document = messageMedia.document as Document.document;\n      const altDocument = messageMedia.alt_documents?.[0] as Document.document; // Supposedly there is only one alt document for stories\n      const result = wrapVideo({\n        ...props,\n        container: div,\n        doc: document,\n        altDoc: altDocument,\n        // ignoreStreaming: true,\n        middleware,\n        ...(props.forViewer && {\n          // noPreview: true,\n          noInfo: true,\n          // noPlayButton: true,\n          noAutoplayAttribute: true\n        }),\n        ...(props.forPreview && {\n          ...(props.noAspecter && {\n            photoSize: choosePhotoSize(document, 200, 200, false)\n          }),\n          onlyPreview: true\n        }),\n        withoutPreloader: !props.withPreloader\n      });\n\n      result.then(async(result) => {\n        if(!middleware()) return;\n        if(props.childrenClassName) {\n          if(result?.thumb) setChildrenClassName(result.thumb, props.childrenClassName);\n          if(result?.video) result.video.classList.add(props.childrenClassName);\n        }\n        if(result?.thumb) await result.thumb.loadPromises.thumb;\n        if(!middleware()) return;\n        if(result?.thumb) setThumb(result.thumb.images.full as any || result.thumb.images.thumb);\n        setReady(true);\n        const video = result?.video;\n        if(video && props.forViewer) {\n          video.loop = false;\n          video.muted = true;\n\n          if(IS_SAFARI) { // * force Safari to load the video\n            video.load();\n          }\n        }\n        await result?.loadPromise;\n        if(!middleware()) return;\n\n        setMedia(video);\n      });\n\n      return result;\n    }\n  };\n\n  let mediaResult: ReturnType<typeof wrapPhoto | typeof wrapVideo>;\n  switch(messageMedia._) {\n    case 'messageMediaPhoto': {\n      mediaResult = wrappers.photo(messageMedia);\n      break;\n    }\n\n    case 'messageMediaDocument': {\n      // if(!props.group && props.forPreview) {\n      //   mediaResult = wrappers.photo(messageMedia);\n      // } else {\n      mediaResult = wrappers.video(messageMedia);\n      // }\n\n      break;\n    }\n  }\n\n  return {container, div, media, mediaResult, thumb, ready};\n};\n\nexport const StoryPreview = (props: {\n  storyId: number,\n  loadPromises?: Promise<any>[],\n  onExpiredStory?: () => void,\n} & CommonProperties) => {\n  let {loadPromises} = props;\n  if(loadPromises) {\n    delete props.loadPromises;\n  }\n\n  const loadPromise: CancellablePromise<void> = loadPromises && deferredPromise();\n  loadPromises?.push(loadPromise);\n  loadPromises = undefined;\n\n  const [storyItem, setStoryItem] = createSignal<StoryItem.storyItem>(undefined, {equals: false});\n  const [f, setF] = createSignal<JSX.Element>();\n\n  rootScope.managers.acknowledged.appStoriesManager.getStoryById(props.peerId, props.storyId)\n  .then(async(result) => {\n    if(!result.cached) {\n      loadPromise?.resolve();\n    }\n\n    const storyItem = await result.result;\n    setStoryItem(storyItem);\n  });\n\n  const onStoryItem = (storyItem: StoryItem.storyItem) => {\n    if(!storyItem) {\n      props.onExpiredStory?.();\n      loadPromise.resolve();\n      return;\n    }\n\n    onCleanup(() => {\n      loadPromise?.reject();\n    });\n\n    // catchError(() => {\n    //   wrapStoryMedia({\n    //     ...props,\n    //     storyItem,\n    //     forPreview: true\n    //   });\n    // }, (err) => {\n    //   console.error('error', err);\n    // });\n\n    const {container, ready} = wrapStoryMedia({\n      ...props,\n      storyItem,\n      forPreview: true\n    });\n\n    createEffect(\n      on(\n        () => ready(),\n        () => {\n          loadPromise?.resolve();\n          setF(container);\n        },\n        {defer: true}\n      )\n    );\n  };\n\n  createEffect(\n    on(\n      () => storyItem(),\n      onStoryItem,\n      {defer: true}\n    )\n  );\n\n  return (\n    <>{f}</>\n  );\n};\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\n\n// CRM session state for the signed-in agent, exposed as two default-false\n// signals so every gate fails closed until the CRM confirms otherwise:\n// - isCrmLoggedIn: the agent has a live CRM session (enabled + baseUrl + token).\n//   Drives the chatlist gate — no conversations are shown without a session.\n// - isCrmSuperAdmin: the session's user has the superadmin role. Gates the\n//   sensitive extras (active sessions, phone numbers, usernames, contacts).\n// - isCrmReadOnly: the session's user is an onboarding trainee — reading only.\n// Kept fresh by AppCrmManager.refreshMe() on app start + login; every persist()\n// there fires crm_config_update, which re-reads both flags here. A 401 fires\n// crm_auth_required, flipping both back to false.\nconst [isCrmLoggedIn, setIsCrmLoggedIn] = createRoot(() => createSignal(false));\nconst [isCrmSuperAdmin, setIsCrmSuperAdmin] = createRoot(() => createSignal(false));\n// Onboarding trainee: read the department's conversations, change nothing. Drives\n// every write affordance in the UI (composer, context menu, CRM actions) and\n// forces peek mode, so not even a read receipt leaves this session.\nconst [isCrmReadOnly, setIsCrmReadOnly] = createRoot(() => createSignal(false));\n// The signed-in agent's own CRM id (undefined when logged out). Used to match\n// per-agent sensitive-reveal approvals — see the sensitive-message workflow.\nconst [crmUserId, setCrmUserId] = createRoot(() => createSignal<number | undefined>(undefined));\n// Whether revealing sensitive content needs superadmin approval. Defaults true\n// (fail-safe): approval is assumed required until /config says otherwise.\nconst [requireSensitiveApproval, setRequireSensitiveApproval] = createRoot(() => createSignal(true));\n\nconst refresh = () => {\n  rootScope.managers.appCrmManager.getConfig().then((config) => {\n    const loggedIn = !!(config.enabled && config.baseUrl && config.token);\n    setIsCrmLoggedIn(loggedIn);\n    setIsCrmSuperAdmin(loggedIn && !!config.user?.is_super_admin);\n    setIsCrmReadOnly(loggedIn && !!config.user?.is_read_only);\n    setCrmUserId(loggedIn ? config.user?.id : undefined);\n    setRequireSensitiveApproval(config.requireSensitiveApproval !== false);\n  }, () => {\n    setIsCrmLoggedIn(false);\n    setIsCrmSuperAdmin(false);\n    setIsCrmReadOnly(false);\n    setCrmUserId(undefined);\n    setRequireSensitiveApproval(true);\n  });\n};\n\nrootScope.addEventListener('crm_config_update', refresh);\nrootScope.addEventListener('crm_auth_required', refresh);\nif(rootScope.myId) {\n  refresh();\n} else {\n  rootScope.addEventListener('user_auth', refresh);\n}\n\nexport function useIsCrmLoggedIn() {\n  return isCrmLoggedIn;\n}\n\n// True only while a read-only session is signed in. Note this is the UI half of\n// the gate: the managers refuse the write themselves (isReadOnlyCached) and the\n// CRM refuses its own writes, so a missed button is not a hole.\nexport function useIsCrmReadOnly() {\n  return isCrmReadOnly;\n}\n\nexport function useCrmUserId() {\n  return crmUserId;\n}\n\nexport function useSensitiveRequireApproval() {\n  return requireSensitiveApproval;\n}\n\nexport default function useIsCrmSuperAdmin() {\n  return isCrmSuperAdmin;\n}\n","export default function easeOutCubic(t: number, b: number, c: number, d: number) {\n  return t >= d ? b + c : easeOutCubicApply(t / d, c) + b;\n}\n\nexport function easeOutCubicApply(v: number, c: number) {\n  return c * (--v * v * v + 1);\n}\n","// Live waveform extractor for voice messages.\n// Taps the same MediaStream the Opus encoder is reading from and computes peaks\n// from raw Float32 PCM, mirroring the algorithm used by iOS / Android / tdesktop:\n//   * per-chunk amplitude = peak (max abs)\n//   * adaptive log-step downsampling (iOS-style) to keep ≤ 200 buckets in memory\n//   * final pass: peak = max(sum*1.8/N, 2500); value = min(31, min(s, peak)*31/peak)\n//   * 5-bit LSB-first packing across byte boundaries\n\nexport const WAVEFORM_SAMPLES_COUNT = 100;\nexport const WAVEFORM_BYTES_LENGTH = Math.ceil(WAVEFORM_SAMPLES_COUNT * 5 / 8); // 63\nconst DOWNSAMPLE_THRESHOLD = WAVEFORM_SAMPLES_COUNT * 2; // 200\n\n// ScriptProcessorNode is deprecated but present in every browser Telegram Web\n// targets — opus-recorder uses it too, so this adds no compatibility risk.\n// Migrating both to AudioWorkletNode would be a separate, larger change.\nconst SCRIPT_PROCESSOR_BUFFER_LENGTH = 4096;\n\nfunction connectSilentSink(context: BaseAudioContext, node: AudioNode) {\n  const sink = context.createGain();\n  sink.gain.value = 0;\n  node.connect(sink);\n  sink.connect(context.destination);\n  return sink;\n}\n\nexport default class VoiceWaveformAnalyser {\n  private sourceNode: AudioNode;\n  private scriptProcessor: ScriptProcessorNode;\n  private silentSink: GainNode;\n  private peaks: number[];\n  private currentPeak: number;\n  private currentPeakCount: number;\n  private peakCompressionFactor: number;\n  private finished: boolean;\n  private paused: boolean;\n\n  constructor(sourceNode?: AudioNode) {\n    this.peaks = [];\n    this.currentPeak = 0;\n    this.currentPeakCount = 0;\n    this.peakCompressionFactor = 1;\n    this.finished = false;\n    this.paused = false;\n\n    if(!sourceNode) return;\n\n    this.sourceNode = sourceNode;\n    const context = sourceNode.context;\n    this.scriptProcessor = context.createScriptProcessor(SCRIPT_PROCESSOR_BUFFER_LENGTH, 1, 1);\n    this.scriptProcessor.onaudioprocess = this.onAudioProcess;\n    sourceNode.connect(this.scriptProcessor);\n    this.silentSink = connectSilentSink(context, this.scriptProcessor);\n  }\n\n  public setPaused(paused: boolean) {\n    this.paused = paused;\n  }\n\n  // Snapshot of the current per-bucket peaks (raw int amplitudes ~0..32767).\n  // Used by the recording UI to show the full waveform during pause/playback\n  // — the visualizer reads this and normalizes it for canvas rendering.\n  public getCurrentPeaks(): number[] {\n    return this.peaks.slice();\n  }\n\n  public feed(samples: Float32Array) {\n    if(this.finished || this.paused) return;\n    this.processChannel(samples);\n  }\n\n  private onAudioProcess = (e: AudioProcessingEvent) => {\n    if(this.finished || this.paused) return;\n    this.processChannel(e.inputBuffer.getChannelData(0));\n  };\n\n  private processChannel(channel: Float32Array) {\n    const len = channel.length;\n    let peak = this.currentPeak;\n    let count = this.currentPeakCount;\n\n    for(let i = 0; i < len; ++i) {\n      const sample = Math.abs(channel[i]) * 32767;\n      if(sample > peak) peak = sample;\n      if(++count === this.peakCompressionFactor) {\n        this.peaks.push(peak);\n        peak = 0;\n        count = 0;\n\n        if(this.peaks.length >= DOWNSAMPLE_THRESHOLD) {\n          for(let j = 0; j < WAVEFORM_SAMPLES_COUNT; ++j) {\n            const a = this.peaks[j * 2];\n            const b = this.peaks[j * 2 + 1];\n            this.peaks[j] = a > b ? a : b;\n          }\n          this.peaks.length = WAVEFORM_SAMPLES_COUNT;\n          this.peakCompressionFactor *= 2;\n        }\n      }\n    }\n\n    this.currentPeak = peak;\n    this.currentPeakCount = count;\n  }\n\n  public finish(): Uint8Array {\n    if(this.finished) return new Uint8Array(WAVEFORM_BYTES_LENGTH);\n    this.finished = true;\n\n    try {\n      this.sourceNode?.disconnect(this.scriptProcessor);\n    } catch(e) {}\n    try {\n      this.scriptProcessor?.disconnect();\n      this.silentSink?.disconnect();\n    } catch(e) {}\n    if(this.scriptProcessor) this.scriptProcessor.onaudioprocess = null;\n\n    const peaks = this.peaks.slice(0, WAVEFORM_SAMPLES_COUNT);\n    while(peaks.length < WAVEFORM_SAMPLES_COUNT) peaks.push(0);\n\n    let sum = 0;\n    for(let i = 0; i < peaks.length; ++i) sum += peaks[i];\n    let normPeak = sum * 1.8 / peaks.length;\n    if(normPeak < 2500) normPeak = 2500;\n\n    const result = new Uint8Array(WAVEFORM_BYTES_LENGTH);\n    for(let i = 0; i < peaks.length; ++i) {\n      const clamped = peaks[i] < normPeak ? peaks[i] : normPeak;\n      const v = Math.min(31, (clamped * 31 / normPeak) | 0);\n      const bitOffset = i * 5;\n      const byteIndex = bitOffset >> 3;\n      const bitShift = bitOffset & 7;\n      result[byteIndex] |= (v << bitShift) & 0xFF;\n      if(bitShift > 3 && byteIndex + 1 < result.length) {\n        result[byteIndex + 1] |= (v >> (8 - bitShift)) & 0xFF;\n      }\n    }\n\n    return result;\n  }\n}\n","// Live amplitude tap used by the recording UI to draw the in-progress waveform.\n// Independent of VoiceWaveformAnalyser (which produces the 63-byte payload sent\n// with the message): this one emits a steady stream of unprocessed peaks at a\n// fixed window, so the UI can scroll bars without the iOS-style log compression\n// the message waveform applies.\n\nconst BUFFER_LENGTH = 2048; // ~43ms at 48kHz\n\nfunction connectSilentSink(context: BaseAudioContext, node: AudioNode) {\n  const sink = context.createGain();\n  sink.gain.value = 0;\n  node.connect(sink);\n  sink.connect(context.destination);\n  return sink;\n}\n\nexport default class LiveWaveformAnalyser {\n  private sourceNode: AudioNode;\n  private scriptProcessor: ScriptProcessorNode;\n  private silentSink: GainNode;\n  private finished = false;\n  private paused = false;\n\n  public onpeak: (peak: number) => void = () => {};\n\n  constructor(sourceNode?: AudioNode) {\n    if(!sourceNode) return;\n\n    this.sourceNode = sourceNode;\n    const ctx = sourceNode.context;\n    this.scriptProcessor = ctx.createScriptProcessor(BUFFER_LENGTH, 1, 1);\n    this.scriptProcessor.onaudioprocess = this.onAudioProcess;\n    sourceNode.connect(this.scriptProcessor);\n    this.silentSink = connectSilentSink(ctx, this.scriptProcessor);\n  }\n\n  public setPaused(paused: boolean) {\n    this.paused = paused;\n  }\n\n  public feed(samples: Float32Array) {\n    if(this.finished || this.paused) return;\n    this.emitPeak(samples);\n  }\n\n  private onAudioProcess = (e: AudioProcessingEvent) => {\n    if(this.finished || this.paused) return;\n    this.emitPeak(e.inputBuffer.getChannelData(0));\n  };\n\n  private emitPeak(channel: Float32Array) {\n    let peak = 0;\n    for(let i = 0; i < channel.length; ++i) {\n      const v = Math.abs(channel[i]);\n      if(v > peak) peak = v;\n    }\n    this.onpeak(peak);\n  }\n\n  public destroy() {\n    if(this.finished) return;\n    this.finished = true;\n    try {\n      this.sourceNode?.disconnect(this.scriptProcessor);\n    } catch(e) {}\n    try {\n      this.scriptProcessor?.disconnect();\n      this.silentSink?.disconnect();\n    } catch(e) {}\n    if(this.scriptProcessor) this.scriptProcessor.onaudioprocess = null;\n  }\n}\n","// OGG container muxer for Opus packets, per RFC 7845 (Opus-in-Ogg) and RFC 3533 (Ogg).\n// Used to wrap raw Opus packets emitted by WebCodecs AudioEncoder into the\n// `audio/ogg;codecs=opus` container that Telegram expects for voice messages.\n\nconst OGG_CRC_TABLE = (() => {\n  const table = new Uint32Array(256);\n  for(let i = 0; i < 256; ++i) {\n    let r = i << 24;\n    for(let j = 0; j < 8; ++j) {\n      r = (r & 0x80000000) ? (((r << 1) >>> 0) ^ 0x04C11DB7) : ((r << 1) >>> 0);\n    }\n    table[i] = r >>> 0;\n  }\n  return table;\n})();\n\nfunction oggCrc(bytes: Uint8Array): number {\n  let crc = 0;\n  for(let i = 0; i < bytes.length; ++i) {\n    crc = (((crc << 8) >>> 0) ^ OGG_CRC_TABLE[((crc >>> 24) ^ bytes[i]) & 0xFF]) >>> 0;\n  }\n  return crc >>> 0;\n}\n\n// Default OpusHead used when the encoder did not provide a description.\n// Pre-skip 312 samples is the libopus default for a fresh encoder at 48kHz.\nfunction buildOpusHead(channels: number, inputSampleRate: number, preSkip: number): Uint8Array {\n  const head = new Uint8Array(19);\n  const view = new DataView(head.buffer);\n  head.set([0x4F, 0x70, 0x75, 0x73, 0x48, 0x65, 0x61, 0x64], 0); // 'OpusHead'\n  head[8] = 1;\n  head[9] = channels;\n  view.setUint16(10, preSkip, true);\n  view.setUint32(12, inputSampleRate, true);\n  view.setInt16(16, 0, true);\n  head[18] = 0;\n  return head;\n}\n\nfunction buildOpusTags(vendor: string): Uint8Array {\n  const enc = new TextEncoder();\n  const v = enc.encode(vendor);\n  const tags = new Uint8Array(8 + 4 + v.length + 4);\n  const view = new DataView(tags.buffer);\n  tags.set([0x4F, 0x70, 0x75, 0x73, 0x54, 0x61, 0x67, 0x73], 0); // 'OpusTags'\n  view.setUint32(8, v.length, true);\n  tags.set(v, 12);\n  view.setUint32(12 + v.length, 0, true); // 0 user comments\n  return tags;\n}\n\nconst OGG_HEADER_TYPE_CONTINUED = 0x01;\nconst OGG_HEADER_TYPE_BOS = 0x02;\nconst OGG_HEADER_TYPE_EOS = 0x04;\n\nconst MAX_PAGE_SEGMENTS = 255;\nconst MAX_SEGMENT_LEN = 255;\n\nexport interface OggOpusWriterOptions {\n  channels: number;\n  inputSampleRate: number;\n  vendor?: string;\n  preSkip?: number;\n  serialNumber?: number;\n  pageGranularitySamples?: number;\n}\n\nexport default class OggOpusWriter {\n  private channels: number;\n  private inputSampleRate: number;\n  private vendor: string;\n  private preSkip: number;\n  private serial: number;\n  private pageGranularitySamples: number;\n\n  private pageSequence = 0;\n  private granulePosition = 0;\n  private pageBuffer: Uint8Array[] = [];\n  private samplesInCurrentPage = 0;\n  private chunks: Uint8Array[] = [];\n  private headersWritten = false;\n  private finalized = false;\n\n  constructor(options: OggOpusWriterOptions) {\n    this.channels = options.channels;\n    this.inputSampleRate = options.inputSampleRate;\n    this.vendor = options.vendor ?? 'tweb';\n    this.preSkip = options.preSkip ?? 312;\n    this.serial = options.serialNumber ?? ((Math.random() * 0xFFFFFFFF) >>> 0);\n    this.pageGranularitySamples = options.pageGranularitySamples ?? 48000;\n  }\n\n  // Optional: replace the default OpusHead with the one the encoder provided\n  // (via EncodedAudioChunkMetadata.decoderConfig.description). Must be called\n  // before any writePacket().\n  public setOpusHead(opusHead: Uint8Array) {\n    if(this.headersWritten) return;\n    this.writeHeaderPagesWith(opusHead);\n  }\n\n  private ensureHeadersWritten() {\n    if(this.headersWritten) return;\n    this.writeHeaderPagesWith(buildOpusHead(this.channels, this.inputSampleRate, this.preSkip));\n  }\n\n  private writeHeaderPagesWith(opusHead: Uint8Array) {\n    this.emitPage([opusHead], 0, OGG_HEADER_TYPE_BOS);\n    this.emitPage([buildOpusTags(this.vendor)], 0, 0);\n    this.headersWritten = true;\n  }\n\n  public writePacket(packet: Uint8Array, durationSamples: number) {\n    if(this.finalized) return;\n    this.ensureHeadersWritten();\n\n    this.pageBuffer.push(packet);\n    this.samplesInCurrentPage += durationSamples;\n    this.granulePosition += durationSamples;\n\n    if(this.shouldFlushPage()) {\n      this.flushDataPage(false);\n    }\n  }\n\n  private shouldFlushPage(): boolean {\n    if(this.pageBuffer.length >= MAX_PAGE_SEGMENTS) return true;\n    if(this.samplesInCurrentPage >= this.pageGranularitySamples) return true;\n\n    let segmentCount = 0;\n    for(let i = 0; i < this.pageBuffer.length; ++i) {\n      segmentCount += Math.floor(this.pageBuffer[i].length / MAX_SEGMENT_LEN) + 1;\n      if(segmentCount >= MAX_PAGE_SEGMENTS) return true;\n    }\n    return false;\n  }\n\n  private flushDataPage(eos: boolean) {\n    if(!this.pageBuffer.length) {\n      if(eos) this.emitPage([], this.granulePosition, OGG_HEADER_TYPE_EOS);\n      return;\n    }\n    this.emitPage(this.pageBuffer, this.granulePosition, eos ? OGG_HEADER_TYPE_EOS : 0);\n    this.pageBuffer = [];\n    this.samplesInCurrentPage = 0;\n  }\n\n  private emitPage(packets: Uint8Array[], granulePos: number, headerType: number) {\n    const page = this.buildPage(packets, granulePos, headerType, this.pageSequence++);\n    this.chunks.push(page);\n  }\n\n  private buildPage(packets: Uint8Array[], granulePos: number, headerType: number, pageSequence: number): Uint8Array {\n    const segments: number[] = [];\n    let payloadLen = 0;\n    for(let i = 0; i < packets.length; ++i) {\n      const len = packets[i].length;\n      const full = Math.floor(len / MAX_SEGMENT_LEN);\n      for(let j = 0; j < full; ++j) segments.push(MAX_SEGMENT_LEN);\n      segments.push(len % MAX_SEGMENT_LEN);\n      payloadLen += len;\n    }\n\n    const segCount = segments.length;\n    const page = new Uint8Array(27 + segCount + payloadLen);\n    const view = new DataView(page.buffer);\n\n    page.set([0x4F, 0x67, 0x67, 0x53], 0); // 'OggS'\n    page[4] = 0;\n    page[5] = headerType;\n    view.setUint32(6, (granulePos >>> 0), true);\n    view.setUint32(10, (Math.floor(granulePos / 0x100000000) >>> 0), true);\n    view.setUint32(14, this.serial, true);\n    view.setUint32(18, pageSequence, true);\n    view.setUint32(22, 0, true);\n    page[26] = segCount;\n    for(let i = 0; i < segCount; ++i) page[27 + i] = segments[i];\n\n    let off = 27 + segCount;\n    for(let i = 0; i < packets.length; ++i) {\n      page.set(packets[i], off);\n      off += packets[i].length;\n    }\n\n    view.setUint32(22, oggCrc(page), true);\n    return page;\n  }\n\n  public finalize(): Uint8Array {\n    if(this.finalized) return this.concat();\n    this.ensureHeadersWritten();\n    this.flushDataPage(true);\n    this.finalized = true;\n    return this.concat();\n  }\n\n  // Build a playable OGG snapshot of everything written so far without mutating\n  // internal state. The snapshot always closes with an EOS page (carrying any\n  // pending packets) so decoders read the correct duration; the live writer\n  // keeps its state and continues from where it left off on the next packet.\n  public snapshot(): Uint8Array {\n    if(!this.headersWritten) return new Uint8Array(0);\n\n    const extraPage = this.buildPage(this.pageBuffer, this.granulePosition, OGG_HEADER_TYPE_EOS, this.pageSequence);\n\n    let total = extraPage.length;\n    for(let i = 0; i < this.chunks.length; ++i) total += this.chunks[i].length;\n\n    const out = new Uint8Array(total);\n    let off = 0;\n    for(let i = 0; i < this.chunks.length; ++i) {\n      out.set(this.chunks[i], off);\n      off += this.chunks[i].length;\n    }\n    out.set(extraPage, off);\n    return out;\n  }\n\n  private concat(): Uint8Array {\n    let total = 0;\n    for(let i = 0; i < this.chunks.length; ++i) total += this.chunks[i].length;\n    const out = new Uint8Array(total);\n    let off = 0;\n    for(let i = 0; i < this.chunks.length; ++i) {\n      out.set(this.chunks[i], off);\n      off += this.chunks[i].length;\n    }\n    return out;\n  }\n}\n","import {appSettings, setAppSettings} from '@stores/appSettings';\nimport {logger} from '@lib/logger';\n\nconst log = logger('getStream');\n\n// The single chokepoint for call-related `getUserMedia` calls. Every call\n// path (P2P + group + previews) goes through here, so the stale-device-id\n// recovery logic lives in exactly one place.\n//\n// Two browsers raise different names for the same \"deviceId.exact no longer\n// matches a physical device\" condition: Chromium / Safari say\n// `OverconstrainedError`, Firefox says `NotFoundError`.\nfunction isMissingDeviceError(err: unknown): boolean {\n  if(!err || typeof err !== 'object') return false;\n  const name = (err as {name?: unknown}).name;\n  return name === 'OverconstrainedError' || name === 'NotFoundError';\n}\n\ntype StrippedConstraint<T> = {value: T, stripped: boolean};\nfunction stripDeviceId<T extends boolean | MediaTrackConstraints | undefined>(\n  constraint: T\n): StrippedConstraint<T> {\n  if(!constraint || typeof constraint !== 'object') return {value: constraint, stripped: false};\n  if(!('deviceId' in constraint)) return {value: constraint, stripped: false};\n  const {deviceId: _, ...rest} = constraint as MediaTrackConstraints & {deviceId?: unknown};\n  return {value: rest as T, stripped: true};\n}\n\nfunction applyMuted(stream: MediaStream, muted: boolean | undefined): MediaStream {\n  if(muted !== undefined) {\n    stream.getTracks().forEach((t) => t.enabled = !muted);\n  }\n  return stream;\n}\n\n// Acquire a media stream for the call subsystem with self-healing fallback\n// when the persisted device id is stale.\n//\n// Recovery uses an **incremental** retry so a working preference isn't\n// thrown out alongside a dead one:\n//   1. Try the requested constraints unchanged.\n//   2. If they fail with the missing-device error AND both audio and video\n//      asked for an exact deviceId, retry keeping audio's deviceId but\n//      dropping video's. On success the camera was the culprit — clear\n//      cameraId, keep microphoneId.\n//   3. Otherwise (single-deviceId failure, or step 2 also failed) drop the\n//      deviceId from each constraint that had one, clear the matching\n//      appSettings field, and retry. The call falls back to OS defaults for\n//      whichever kind was bad and the call carries on.\n//\n// `muted` is only honoured if explicitly provided — leaving it `undefined`\n// means \"don't touch track enabled flags\" (callers that don't care about\n// muted state can skip the second argument).\nexport default async function getStream(\n  constraints: MediaStreamConstraints,\n  muted?: boolean\n): Promise<MediaStream> {\n  try {\n    return applyMuted(await navigator.mediaDevices.getUserMedia(constraints), muted);\n  } catch(err) {\n    if(!isMissingDeviceError(err)) throw err;\n\n    const audio = stripDeviceId(constraints.audio);\n    const video = stripDeviceId(constraints.video);\n\n    // Nothing to fall back FROM — propagate the original error so the caller\n    // surfaces it (this is a real \"no device at all\" condition, not a stale\n    // persisted choice).\n    if(!audio.stripped && !video.stripped) throw err;\n\n    log.warn('saved device id is stale, attempting fallback', {audioHadDeviceId: audio.stripped, videoHadDeviceId: video.stripped, error: (err as {name?: string})?.name});\n\n    // Both had deviceId — try keeping audio first; if that succeeds, the\n    // camera was the only stale device and the mic preference survives.\n    if(audio.stripped && video.stripped) {\n      try {\n        const stream = await navigator.mediaDevices.getUserMedia({\n          audio: constraints.audio,\n          video: video.value\n        });\n        if(appSettings.callDevices?.cameraId) {\n          setAppSettings('callDevices', 'cameraId', '');\n        }\n        log('camera device was stale; kept microphone, cleared cameraId');\n        return applyMuted(stream, muted);\n      } catch(err2) {\n        if(!isMissingDeviceError(err2)) throw err2;\n        // audio.deviceId was also bad — fall through to the dual-clear path.\n      }\n    }\n\n    if(audio.stripped && appSettings.callDevices?.microphoneId) {\n      setAppSettings('callDevices', 'microphoneId', '');\n    }\n    if(video.stripped && appSettings.callDevices?.cameraId) {\n      setAppSettings('callDevices', 'cameraId', '');\n    }\n\n    log.warn('clearing stale device id(s), retrying on OS defaults', {clearedMicrophone: audio.stripped, clearedCamera: video.stripped});\n\n    return applyMuted(await navigator.mediaDevices.getUserMedia({\n      audio: audio.value,\n      video: video.value\n    }), muted);\n  }\n}\n\n(window as any).getStream = getStream;\n","// Native voice recorder built on the standard web platform — no WASM:\n//   getUserMedia → AudioContext(48k) → AudioWorklet (PCM tap) →\n//     WebCodecs AudioEncoder (opus) → OGG/Opus muxer.\n//\n// Mirrors the parts of the opus-recorder API that input.ts uses, so the\n// caller can swap implementations without conditionals at the use site.\n\nimport OggOpusWriter from './oggOpusWriter';\nimport isNativeVoiceRecorderSupported from './isNativeSupported';\nimport getStream from '@lib/calls/helpers/getStream';\nimport {IS_MOBILE} from '@environment/userAgent';\n\nexport {isNativeVoiceRecorderSupported};\n\nconst WORKLET_SOURCE = `\nclass VoiceCaptureProcessor extends AudioWorkletProcessor {\n  constructor(options) {\n    super();\n    const opts = (options && options.processorOptions) || {};\n    this.bufferSize = opts.bufferSize || 2048;\n    this.buffer = new Float32Array(this.bufferSize);\n    this.bufferIndex = 0;\n  }\n  process(inputs) {\n    const input = inputs[0];\n    if(!input || !input[0] || input[0].length === 0) return true;\n    const channel = input[0];\n    let i = 0;\n    while(i < channel.length) {\n      const remaining = this.bufferSize - this.bufferIndex;\n      const toCopy = remaining < (channel.length - i) ? remaining : (channel.length - i);\n      this.buffer.set(channel.subarray(i, i + toCopy), this.bufferIndex);\n      this.bufferIndex += toCopy;\n      i += toCopy;\n      if(this.bufferIndex === this.bufferSize) {\n        const out = this.buffer;\n        this.buffer = new Float32Array(this.bufferSize);\n        this.bufferIndex = 0;\n        this.port.postMessage(out, [out.buffer]);\n      }\n    }\n    return true;\n  }\n}\nregisterProcessor('voice-capture-processor', VoiceCaptureProcessor);\n`;\n\nconst WORKLET_PROCESSOR_NAME = 'voice-capture-processor';\n// Larger capture windows on mobile cut main-thread postMessage/encode churn,\n// which otherwise starves the audio graph on low-end PWA installs.\nconst WORKLET_BUFFER_SIZE = IS_MOBILE ? 4096 : 2048;\nconst ENCODER_SAMPLE_RATE = 48000;\nconst DEFAULT_BITRATE = 96000;\nconst DEFAULT_FRAME_DURATION_US = 20000;\nconst DEFAULT_OPUS_FRAME_SAMPLES = (DEFAULT_FRAME_DURATION_US * ENCODER_SAMPLE_RATE) / 1_000_000;\n\nexport interface NativeVoiceRecorderConfig {\n  encoderSampleRate?: number;\n  numberOfChannels?: number;\n  encoderBitRate?: number;\n  mediaTrackConstraints?: boolean | MediaTrackConstraints;\n}\n\ntype State = 'inactive' | 'recording' | 'paused';\n\nexport default class NativeVoiceRecorder {\n  public sourceNode: MediaStreamAudioSourceNode;\n  public state: State = 'inactive';\n\n  public onstart: () => void = () => {};\n  public onstop: () => void = () => {};\n  public onpause: () => void = () => {};\n  public onresume: () => void = () => {};\n  public ondataavailable: (data: Uint8Array) => void = () => {};\n\n  private config: Required<Pick<NativeVoiceRecorderConfig, 'encoderSampleRate' | 'numberOfChannels' | 'encoderBitRate'>> & {\n    mediaTrackConstraints: boolean | MediaTrackConstraints\n  };\n\n  private stream: MediaStream;\n  private audioContext: AudioContext;\n  private workletNode: AudioWorkletNode;\n  private encoder: AudioEncoder;\n  private writer: OggOpusWriter;\n  private workletUrl: string;\n  private silentSink: GainNode;\n  private encoderTimestampUs = 0;\n  private opusHeadCaptured = false;\n  public notifySamples: (samples: Float32Array) => void;\n\n  static isSupported = isNativeVoiceRecorderSupported;\n\n  constructor(config: NativeVoiceRecorderConfig = {}) {\n    this.config = {\n      encoderSampleRate: config.encoderSampleRate ?? ENCODER_SAMPLE_RATE,\n      numberOfChannels: config.numberOfChannels ?? 1,\n      encoderBitRate: config.encoderBitRate ?? DEFAULT_BITRATE,\n      mediaTrackConstraints: config.mediaTrackConstraints ?? true\n    };\n  }\n\n  // Choose the microphone to record with (empty/undefined = OS default). The\n  // caller passes the user's pick from Settings → Speakers and Camera\n  // (appSettings.callDevices.microphoneId), same source as calls. Applied on the\n  // next start().\n  public setMicrophoneId(microphoneId?: string) {\n    this.config.mediaTrackConstraints = microphoneId ? {deviceId: {exact: microphoneId}} : true;\n  }\n\n  public async start(): Promise<void> {\n    if(this.state !== 'inactive') return;\n\n    // Reuse the call stack's getUserMedia chokepoint: if the selected mic is\n    // gone it strips the deviceId, clears the stale appSettings.callDevices.\n    // microphoneId and retries on the OS default — same self-healing as calls.\n    const audioConstraints: MediaTrackConstraints = typeof this.config.mediaTrackConstraints === 'object' ? this.config.mediaTrackConstraints : {};\n    // Voice notes are not calls — skip the heavy in-call DSP stack (AEC/AGC)\n    // that can pump and clip on low-end mobile hardware.\n    this.stream = await getStream({\n      audio: {\n        ...audioConstraints,\n        channelCount: 1,\n        sampleRate: {ideal: this.config.encoderSampleRate},\n        noiseSuppression: false,\n        echoCancellation: false,\n        autoGainControl: false\n      }\n    });\n\n    this.audioContext = new AudioContext({sampleRate: this.config.encoderSampleRate});\n    if(this.audioContext.state === 'suspended') {\n      await this.audioContext.resume();\n    }\n    this.sourceNode = this.audioContext.createMediaStreamSource(this.stream);\n\n    const blob = new Blob([WORKLET_SOURCE], {type: 'application/javascript'});\n    this.workletUrl = URL.createObjectURL(blob);\n    await this.audioContext.audioWorklet.addModule(this.workletUrl);\n\n    this.workletNode = new AudioWorkletNode(this.audioContext, WORKLET_PROCESSOR_NAME, {\n      numberOfInputs: 1,\n      numberOfOutputs: 1,\n      outputChannelCount: [this.config.numberOfChannels],\n      processorOptions: {bufferSize: WORKLET_BUFFER_SIZE}\n    });\n\n    this.writer = new OggOpusWriter({\n      channels: this.config.numberOfChannels,\n      inputSampleRate: this.config.encoderSampleRate\n    });\n\n    this.encoder = new AudioEncoder({\n      output: (chunk, metadata) => this.onEncoderChunk(chunk, metadata),\n      error: (err) => console.error('[NativeVoiceRecorder] encoder error:', err)\n    });\n\n    this.encoder.configure({\n      codec: 'opus',\n      sampleRate: this.config.encoderSampleRate,\n      numberOfChannels: this.config.numberOfChannels,\n      bitrate: this.config.encoderBitRate\n    });\n\n    this.workletNode.port.onmessage = (e: MessageEvent<Float32Array>) => this.onWorkletMessage(e.data);\n\n    this.silentSink = this.audioContext.createGain();\n    this.silentSink.gain.value = 0;\n\n    this.sourceNode.connect(this.workletNode);\n    // AudioWorkletNode needs a downstream consumer for process() to be called.\n    this.workletNode.connect(this.silentSink);\n    this.silentSink.connect(this.audioContext.destination);\n\n    this.state = 'recording';\n    this.encoderTimestampUs = 0;\n    this.opusHeadCaptured = false;\n    this.onstart();\n  }\n\n  private onWorkletMessage(samples: Float32Array) {\n    if(this.state !== 'recording') return;\n    if(this.notifySamples) this.notifySamples(samples);\n    const numberOfFrames = samples.length / this.config.numberOfChannels;\n    const audioData = new AudioData({\n      format: 'f32-planar',\n      sampleRate: this.config.encoderSampleRate,\n      numberOfFrames,\n      numberOfChannels: this.config.numberOfChannels,\n      timestamp: this.encoderTimestampUs,\n      data: new Float32Array(samples)\n    });\n    this.encoderTimestampUs += (numberOfFrames * 1_000_000) / this.config.encoderSampleRate;\n    try {\n      this.encoder.encode(audioData);\n    } catch(err) {\n      console.error('[NativeVoiceRecorder] encode error:', err);\n    }\n    audioData.close();\n  }\n\n  private onEncoderChunk(chunk: EncodedAudioChunk, metadata?: EncodedAudioChunkMetadata) {\n    if(!this.opusHeadCaptured && metadata?.decoderConfig?.description) {\n      const desc = metadata.decoderConfig.description;\n      let bytes: Uint8Array;\n      if(desc instanceof ArrayBuffer) {\n        bytes = new Uint8Array(desc);\n      } else {\n        const view = desc as ArrayBufferView;\n        bytes = new Uint8Array(view.buffer as ArrayBuffer, view.byteOffset, view.byteLength);\n      }\n      this.writer.setOpusHead(bytes);\n      this.opusHeadCaptured = true;\n    }\n\n    const data = new Uint8Array(chunk.byteLength);\n    chunk.copyTo(data);\n\n    const durationUs = chunk.duration ?? DEFAULT_FRAME_DURATION_US;\n    const durationSamples = Math.round((durationUs * ENCODER_SAMPLE_RATE) / 1_000_000) || DEFAULT_OPUS_FRAME_SAMPLES;\n    this.writer.writePacket(data, durationSamples);\n  }\n\n  // Pause keeps the worklet → encoder pipeline wired up but ignores incoming\n  // PCM samples. The encoder is flushed so the OGG snapshot is playable.\n  public async pause(): Promise<void> {\n    if(this.state !== 'recording') return;\n    this.state = 'paused';\n    if(this.encoder && this.encoder.state !== 'closed') {\n      try {\n        await this.encoder.flush();\n      } catch(e) {}\n    }\n    this.onpause();\n  }\n\n  public resume(): void {\n    if(this.state !== 'paused') return;\n    this.state = 'recording';\n    this.onresume();\n  }\n\n  // Build a playable OGG of everything captured so far without ending the\n  // recording. Used to preview the in-progress voice message during pause.\n  public getSnapshot(): Uint8Array {\n    return this.writer ? this.writer.snapshot() : new Uint8Array(0);\n  }\n\n  public async stop(): Promise<void> {\n    if(this.state === 'inactive') return;\n    this.state = 'inactive';\n\n    try {\n      this.sourceNode?.disconnect();\n    } catch(e) {}\n    try {\n      this.silentSink?.disconnect();\n    } catch(e) {}\n    if(this.workletNode) {\n      try {\n        this.workletNode.disconnect();\n      } catch(e) {}\n      this.workletNode.port.onmessage = null;\n    }\n\n    if(this.stream) {\n      this.stream.getTracks().forEach((t) => t.stop());\n    }\n\n    if(this.encoder && this.encoder.state !== 'closed') {\n      try {\n        await this.encoder.flush();\n      } catch(e) {\n        console.error('[NativeVoiceRecorder] flush error:', e);\n      }\n      try {\n        this.encoder.close();\n      } catch(e) {}\n    }\n\n    const ogg = this.writer ? this.writer.finalize() : new Uint8Array(0);\n\n    if(this.workletUrl) {\n      URL.revokeObjectURL(this.workletUrl);\n      this.workletUrl = undefined;\n    }\n\n    if(this.audioContext && this.audioContext.state !== 'closed') {\n      try {\n        await this.audioContext.close();\n      } catch(e) {}\n    }\n\n    this.ondataavailable(ogg);\n    this.onstop();\n  }\n}\n","import simulateEvent from '@helpers/dom/dispatchEvent';\n\nexport default function stopTrack(track: MediaStreamTrack) {\n  track.stop();\n  simulateEvent(track, 'ended');\n}\n","import getStream from '@lib/calls/helpers/getStream';\nimport stopTrack from '@lib/calls/helpers/stopTrack';\n\nexport type StreamAcquisition = {\n  // Resolves to the live stream, or `undefined` if dispose() was called before\n  // (or while) getUserMedia resolved. Rejects only on a real acquisition error\n  // that happened while the stream was still wanted — once disposed, a rejection\n  // is swallowed and surfaces as `undefined` instead.\n  promise: Promise<MediaStream>,\n  // Release the acquisition. Stops the stream's tracks if it has already\n  // resolved; otherwise flags it so the stream is stopped the instant it\n  // resolves. Idempotent, and safe to call before the stream exists.\n  dispose: () => void\n};\n\n// `getStream` (getUserMedia under it) CAN'T be cancelled: by the time the\n// promise resolves the device is already captured. So if the owner — a Solid\n// component, a recorder — is torn down (close popup, switch chat) WHILE the\n// acquire is in flight, the resolved stream is orphaned and the camera/mic\n// stays live forever (hardware indicator stuck on): teardown ran before there\n// was a stream to stop.\n//\n// This wraps `getStream` as a disposable handle. Crucially it returns\n// SYNCHRONOUSLY — the caller gets `dispose` before the `await`, so it can wire\n// it into its teardown (Solid `onCleanup`, a class release()/cleanup()...)\n// up-front, closing the window. dispose() owns the stream's tracks: stops them\n// now if resolved, or the moment they resolve if not. Owners WITHOUT\n// authoritative lifecycle state should acquire camera/mic through here instead\n// of raw `getStream` (the call instances do have such state and guard inline\n// with `isClosing`, so they stay on `getStream`).\nexport default function acquireStream(\n  constraints: MediaStreamConstraints,\n  muted?: boolean\n): StreamAcquisition {\n  let disposed = false;\n  let acquired: MediaStream | undefined;\n\n  const promise = (async() => {\n    let stream: MediaStream;\n    try {\n      stream = await getStream(constraints, muted);\n    } catch(err) {\n      // The owner already walked away — its error handler is gone, so swallow\n      // the rejection and resolve like a (benign) disposed acquire rather than\n      // surfacing a stale error / leaving it unhandled.\n      if(disposed) return undefined;\n      throw err;\n    }\n\n    // Torn down while getUserMedia was resolving — stop the orphaned stream and\n    // hand back nothing.\n    if(disposed) {\n      stream.getTracks().forEach((track) => stopTrack(track));\n      return undefined;\n    }\n\n    acquired = stream;\n    return stream;\n  })();\n\n  const dispose = () => {\n    disposed = true;\n    if(acquired) {\n      acquired.getTracks().forEach((track) => stopTrack(track));\n      acquired = undefined;\n    }\n  };\n\n  return {promise, dispose};\n}\n","// Native round-video-note recorder.\n//\n//   getUserMedia(video + audio) → center-cropped square <canvas> (drawn per\n//   camera frame) → canvas.captureStream() + the mic track → MediaRecorder\n//   (mp4/avc1+aac, or webm/vp9|vp8+opus fallback) → Blob.\n//\n// Why the canvas: round notes are SQUARE (iOS/Desktop 400×400, Android 384×384;\n// we use the larger, 400). Cameras only output rectangular feeds (640×480,\n// 1280×720…), and MediaRecorder would otherwise encode that rectangle — so the\n// sent file would neither be square nor match the documentAttributeVideo w/h.\n// Drawing a centre-cropped square onto a fixed-size canvas guarantees the\n// encoded video is exactly `width`×`height`, matching the official clients.\n//\n// `stream` stays the RAW camera+mic stream (the chat input shows it in the\n// preview circle and taps its audio for the waveform); the MediaRecorder\n// records the canvas stream instead.\n//\n// Paused preview: round notes are sent as mp4 (the only container every\n// recipient — incl. iOS/macOS — can play), but Chrome's mp4 MediaRecorder emits\n// data ONLY at stop(), so the mid-recording snapshot the paused preview plays\n// would be empty. To keep preview working \"like voice\" we run a SECOND, webm\n// recorder on the same stream purely for getSnapshot() (webm timeslice chunks\n// are independently playable). The sent file is always the mp4 one.\n//\n// Mirrors the parts of the NativeVoiceRecorder API that input.ts uses (state,\n// onstart/onstop/onpause/onresume/ondataavailable, getSnapshot).\n\nimport {IS_APPLE_MOBILE, IS_SAFARI} from '@environment/userAgent';\nimport acquireStream, {StreamAcquisition} from '@lib/calls/helpers/acquireStream';\n\nexport interface NativeVideoRecorderConfig {\n  // Square output dimensions written to the encoded file. 400 = the larger of\n  // iOS (400) and Android (384), matching what other clients send.\n  width?: number;\n  height?: number;\n  videoBitsPerSecond?: number;\n  audioBitsPerSecond?: number;\n  frameRate?: number;\n  facingMode?: 'user' | 'environment';\n  videoDeviceId?: string;\n  audioDeviceId?: string;\n}\n\ntype State = 'inactive' | 'recording' | 'paused';\n\n// Codec preferences, ordered most → least preferred. mp4/h264 matches what\n// official clients send; webm is the universal fallback in browsers without\n// MP4 in MediaRecorder (older Chrome/Firefox).\nconst MIME_CANDIDATES = [\n  'video/mp4;codecs=avc1.42E01E,mp4a.40.2',\n  'video/mp4',\n  'video/webm;codecs=vp9,opus',\n  'video/webm;codecs=vp8,opus',\n  'video/webm'\n];\n\nfunction pickMimeType(): string | undefined {\n  if(typeof MediaRecorder === 'undefined') return undefined;\n  for(const mime of MIME_CANDIDATES) {\n    try {\n      if(MediaRecorder.isTypeSupported(mime)) return mime;\n    } catch(e) {}\n  }\n  // No candidate matched — return undefined (not '') so isNativeVideoRecorderSupported\n  // correctly reports unsupported on a UA with MediaRecorder but no usable codec.\n  return undefined;\n}\n\n// Streamable container for the paused-preview snapshot. Chrome's mp4\n// MediaRecorder emits a playable file ONLY at stop() (no mid-stream chunks), so\n// when the sent file is mp4 we run a SECOND, parallel recorder in webm — whose\n// timeslice chunks ARE independently decodable — purely to back the \"play what\n// you've recorded so far\" preview. Nothing here is sent.\nconst PREVIEW_MIME_CANDIDATES = [\n  'video/webm;codecs=vp9,opus',\n  'video/webm;codecs=vp8,opus',\n  'video/webm'\n];\n\nfunction pickPreviewMimeType(): string | undefined {\n  if(typeof MediaRecorder === 'undefined') return undefined;\n  for(const mime of PREVIEW_MIME_CANDIDATES) {\n    try {\n      if(MediaRecorder.isTypeSupported(mime)) return mime;\n    } catch(e) {}\n  }\n  return undefined;\n}\n\nexport function isNativeVideoRecorderSupported(): boolean {\n  if(typeof MediaRecorder === 'undefined') return false;\n  if(!navigator?.mediaDevices?.getUserMedia) return false;\n  if(typeof HTMLCanvasElement === 'undefined' || !HTMLCanvasElement.prototype.captureStream) return false;\n  // WebKit (Safari + all iOS browsers) exposes canvas.captureStream and an mp4\n  // MediaRecorder, but the canvas-captured video track is broken — invalid\n  // frames and a possible hang on stop() (WebKit bug #181663). Disable video\n  // notes there; getActiveRecordingMediaType() falls back to voice.\n  if(IS_SAFARI || IS_APPLE_MOBILE) return false;\n  return pickMimeType() !== undefined;\n}\n\nexport default class NativeVideoRecorder {\n  // Raw camera+mic stream — the chat input renders this in the preview circle\n  // and taps its audio for the waveform. NOT what gets recorded (see canvas).\n  public stream: MediaStream;\n  public state: State = 'inactive';\n  public mimeType: string;\n\n  public onstart: () => void = () => {};\n  public onstop: () => void = () => {};\n  public onpause: () => void = () => {};\n  public onresume: () => void = () => {};\n  public ondataavailable: (blob: Blob) => void = () => {};\n\n  private config: Required<Omit<NativeVideoRecorderConfig, 'videoDeviceId' | 'audioDeviceId' | 'facingMode'>> & {\n    videoDeviceId?: string;\n    audioDeviceId?: string;\n    facingMode: 'user' | 'environment';\n  };\n\n  private mediaRecorder: MediaRecorder;\n  private chunks: Blob[] = [];\n  // Guards emitResult() so the blob is sent once — onstop and the stop()-error\n  // fallback can otherwise both fire.\n  private finished = false;\n\n  // Parallel webm recorder backing the paused-preview snapshot (see\n  // PREVIEW_MIME_CANDIDATES). Only created when the sent container (mp4) can't\n  // produce mid-stream playable data; when the sent file is already a\n  // streamable webm we timeslice the main recorder and read its chunks instead.\n  private previewRecorder: MediaRecorder;\n  private previewChunks: Blob[] = [];\n  private previewMimeType: string;\n  private snapshotContainer: string; // container of getSnapshot()'s blobs\n\n  // Square-crop pipeline.\n  private drawVideo: HTMLVideoElement;     // plays `stream`, source for the canvas\n  private canvas: HTMLCanvasElement;       // width×height square, encoded as-is\n  private canvasCtx: CanvasRenderingContext2D;\n  private canvasStream: MediaStream;       // canvas.captureStream() — video only\n  private drawing = false;\n  // Holds the in-flight / active camera+mic acquire. dispose() (called from\n  // releaseStream()) stops its tracks even if getUserMedia resolves DURING the\n  // up-to-1.5s warm-up, after a cancel / ChatRecording.destroy() — getUserMedia\n  // can't be cancelled, so without this the camera LED would stay on forever.\n  // See acquireStream.\n  private acquisition: StreamAcquisition | undefined;\n\n  static isSupported = isNativeVideoRecorderSupported;\n\n  constructor(config: NativeVideoRecorderConfig = {}) {\n    this.config = {\n      width: config.width ?? 400,\n      height: config.height ?? 400,\n      videoBitsPerSecond: config.videoBitsPerSecond ?? 1_200_000,\n      audioBitsPerSecond: config.audioBitsPerSecond ?? 64_000,\n      frameRate: config.frameRate ?? 30,\n      facingMode: config.facingMode ?? 'user',\n      videoDeviceId: config.videoDeviceId,\n      audioDeviceId: config.audioDeviceId\n    };\n  }\n\n  // Choose the camera/microphone to record with (empty/undefined = OS default).\n  // The caller passes the user's picks from Settings → Speakers and Camera\n  // (appSettings.callDevices.cameraId/microphoneId), same source as calls.\n  // Applied on the next start().\n  public setDeviceIds(videoDeviceId?: string, audioDeviceId?: string) {\n    this.config.videoDeviceId = videoDeviceId || undefined;\n    this.config.audioDeviceId = audioDeviceId || undefined;\n  }\n\n  public async start(): Promise<void> {\n    if(this.state !== 'inactive') return;\n\n    // The recorder is reused across recordings — drop prior chunks and release\n    // a stream the caller may have left alive for the stop animation.\n    this.chunks = [];\n    this.previewChunks = [];\n    this.finished = false;\n    this.releaseStream();\n\n    // Source a bit larger than the square output so the centre-crop stays sharp\n    // (`ideal`, never `min` — a hard min paired with `deviceId:{exact}` becomes\n    // OverconstrainedError). Honour the camera/mic the caller selected (Settings\n    // → Speakers and Camera) via videoDeviceId/audioDeviceId.\n    const video: MediaTrackConstraints = {\n      width: {ideal: 720},\n      height: {ideal: 720},\n      frameRate: {ideal: this.config.frameRate}\n    };\n    if(this.config.videoDeviceId) {\n      video.deviceId = {exact: this.config.videoDeviceId};\n    } else {\n      video.facingMode = this.config.facingMode;\n    }\n\n    const audio: MediaTrackConstraints = {};\n    if(this.config.audioDeviceId) {\n      audio.deviceId = {exact: this.config.audioDeviceId};\n    }\n\n    // Reuse the call stack's getUserMedia chokepoint: if a selected device is\n    // gone it strips the deviceId, clears the stale appSettings.callDevices.*\n    // entry and retries on the OS default — round notes get the exact same\n    // self-healing device fallback as calls.\n    const acquisition = this.acquisition = acquireStream({video, audio: Object.keys(audio).length ? audio : true});\n    const stream = await acquisition.promise;\n    // Released (cancel / ChatRecording.destroy()) while getUserMedia was\n    // resolving — dispose() already stopped the orphaned stream; bail so the\n    // camera doesn't go live with no owner.\n    if(!stream) return;\n    this.stream = stream;\n\n    // Off-DOM <video> that decodes the raw camera feed for the canvas.\n    this.drawVideo = document.createElement('video');\n    this.drawVideo.muted = true;\n    this.drawVideo.playsInline = true;\n    this.drawVideo.srcObject = this.stream;\n\n    this.canvas = document.createElement('canvas');\n    this.canvas.width = this.config.width;\n    this.canvas.height = this.config.height;\n    this.canvasCtx = this.canvas.getContext('2d', {willReadFrequently: true}) as CanvasRenderingContext2D;\n\n    await this.drawVideo.play().catch(() => {});\n\n    // Don't begin recording on the camera's black warm-up frames — wait until\n    // it outputs a visible (non-black) frame, so the clip doesn't start black.\n    await this.waitForVisibleFrame();\n    if(!this.stream) return; // released (cancel/destroy) while we waited\n\n    // Prime the canvas with the first real frame, then keep it fed.\n    this.drawCroppedFrame();\n    this.startDrawLoop();\n\n    this.mimeType = pickMimeType();\n    try {\n      this.canvasStream = this.canvas.captureStream(this.config.frameRate);\n      const videoTrack = this.canvasStream.getVideoTracks()[0];\n      if(!videoTrack || videoTrack.readyState !== 'live') {\n        // e.g. a broken canvas.captureStream — bail rather than record a black/empty clip.\n        throw new Error('canvas.captureStream produced no live video track');\n      }\n      const recordStream = new MediaStream([\n        videoTrack,\n        ...this.stream.getAudioTracks()\n      ]);\n\n      const options: MediaRecorderOptions = {\n        videoBitsPerSecond: this.config.videoBitsPerSecond,\n        audioBitsPerSecond: this.config.audioBitsPerSecond\n      };\n      if(this.mimeType) options.mimeType = this.mimeType;\n\n      this.mediaRecorder = new MediaRecorder(recordStream, options);\n      // Prefer the container WE requested (and verified) over the recorder's\n      // possibly-empty reported mimeType; drop `;codecs=…` so appMessagesManager's\n      // exact-string VIDEO_MIME_TYPES_SUPPORTED lookup matches.\n      const fullMime = this.mimeType || this.mediaRecorder.mimeType || 'video/webm';\n      this.mimeType = fullMime.split(';')[0].trim();\n\n      this.mediaRecorder.ondataavailable = (e) => {\n        if(e.data && e.data.size > 0) this.chunks.push(e.data);\n      };\n      // The stream is intentionally NOT released in emitResult — the caller keeps\n      // the preview alive through the fade-out and calls releaseStream() after.\n      this.mediaRecorder.onstop = () => this.emitResult();\n\n      // Paused-preview snapshot source. If the sent container is already a\n      // streamable webm, timeslice the main recorder and read its own chunks.\n      // Otherwise (mp4 — no mid-stream data) spin up a parallel webm recorder on\n      // the same stream whose timeslice chunks are independently playable.\n      const mainIsStreamable = this.mimeType.startsWith('video/webm');\n      if(mainIsStreamable) {\n        this.snapshotContainer = this.mimeType;\n      } else {\n        this.previewMimeType = pickPreviewMimeType();\n        if(this.previewMimeType) {\n          this.previewRecorder = new MediaRecorder(recordStream, {\n            mimeType: this.previewMimeType,\n            videoBitsPerSecond: this.config.videoBitsPerSecond,\n            audioBitsPerSecond: this.config.audioBitsPerSecond\n          });\n          this.snapshotContainer = (this.previewRecorder.mimeType || this.previewMimeType).split(';')[0].trim();\n          this.previewRecorder.ondataavailable = (e) => {\n            if(e.data && e.data.size > 0) this.previewChunks.push(e.data);\n          };\n        }\n      }\n\n      // mp4: one final chunk at stop() (no timeslice). Streamable webm: periodic\n      // chunks so getSnapshot() has playable data mid-recording.\n      this.mediaRecorder.start(mainIsStreamable ? 250 : undefined);\n      this.previewRecorder?.start(250);\n    } catch(err) {\n      this.releaseStream(); // tear down the half-initialised pipeline + camera\n      throw err;\n    }\n\n    this.state = 'recording';\n    this.onstart();\n  }\n\n  // Centre-crop the camera feed to a square and scale it into the output canvas.\n  private drawCroppedFrame() {\n    const v = this.drawVideo;\n    const ctx = this.canvasCtx;\n    if(!v || !ctx) return;\n    const vw = v.videoWidth, vh = v.videoHeight;\n    if(!vw || !vh) return;\n    const side = Math.min(vw, vh);\n    const sx = (vw - side) / 2;\n    const sy = (vh - side) / 2;\n    ctx.drawImage(v, sx, sy, side, side, 0, 0, this.config.width, this.config.height);\n  }\n\n  private startDrawLoop() {\n    if(this.drawing) return;\n    this.drawing = true;\n    // Drive draws with requestAnimationFrame, NOT requestVideoFrameCallback:\n    // rVFC only fires while the source <video> is actually being rendered, and\n    // ours is off-DOM (never appended) — and the tab may be unfocused — so rVFC\n    // can stay silent forever, freezing the canvas and yielding a ~1-frame clip.\n    // rAF keeps ticking regardless.\n    //\n    // Throttle to the capture frame rate: rAF fires at the display rate (~60fps)\n    // but canvas.captureStream(frameRate) only samples at config.frameRate (30),\n    // so drawing every tick just burns CPU on a redundant 720→400 drawImage and\n    // steals main-thread time from the encoder / live preview / waveform — which\n    // can drop the *captured* rate under load. Drawing at the capture rate keeps\n    // output fps identical while ~halving the crop work; under heavy load the\n    // gate is a no-op (ticks already arrive slower than the interval).\n    const minIntervalMs = 1000 / this.config.frameRate;\n    let lastDraw = 0;\n    const tick = (now: number) => {\n      if(!this.drawing) return;\n      if(now - lastDraw >= minIntervalMs - 1) {\n        lastDraw = now;\n        this.drawCroppedFrame();\n      }\n      requestAnimationFrame(tick);\n    };\n    requestAnimationFrame(tick);\n  }\n\n  // Resolves once the camera produces a non-black frame (or after a safety\n  // timeout / a few frames in a genuinely dark room). Samples the centre-crop\n  // canvas so the very first recorded frame is the visible one.\n  private waitForVisibleFrame(): Promise<void> {\n    return new Promise((resolve) => {\n      const v = this.drawVideo;\n      if(!v || !this.canvasCtx) {\n        resolve();\n        return;\n      }\n\n      let done = false;\n      let frames = 0;\n      const finish = () => {\n        if(done) return;\n        done = true;\n        clearTimeout(safety);\n        resolve();\n      };\n      const safety = setTimeout(finish, 1500);\n\n      // rAF, not rVFC — see startDrawLoop: rVFC never fires for our off-DOM /\n      // unfocused video, which would stall first-frame detection until the\n      // safety timeout and then start recording on a frozen canvas.\n      const schedule = () => requestAnimationFrame(check);\n\n      const check = () => {\n        if(done || !this.stream) {\n          finish();\n          return;\n        }\n        frames++;\n        let bright = false;\n        try {\n          this.drawCroppedFrame();\n          const sw = Math.min(16, this.canvas.width);\n          const data = this.canvasCtx.getImageData(0, 0, sw, sw).data;\n          let sum = 0;\n          for(let i = 0; i < data.length; i += 4) sum += data[i] + data[i + 1] + data[i + 2];\n          bright = sum / (sw * sw * 3) > 10; // 0..255 avg luminance\n        } catch(e) {\n          bright = true; // can't sample — don't block recording\n        }\n        // Give up after ~25 frames so a genuinely dark scene still records.\n        if(bright || frames >= 25) finish();\n        else schedule();\n      };\n\n      schedule();\n    });\n  }\n\n  public async pause(): Promise<void> {\n    if(this.state !== 'recording' || !this.mediaRecorder) return;\n    // Flush a pending chunk on whichever recorder backs getSnapshot() so the\n    // paused preview includes everything captured so far.\n    const snapshotRecorder = this.previewRecorder || this.mediaRecorder;\n    try {\n      snapshotRecorder.requestData?.();\n    } catch(e) {}\n    try {\n      this.previewRecorder?.pause();\n    } catch(e) {}\n    this.mediaRecorder.pause();\n    // Stop feeding the canvas while paused — no recorder is consuming it, so the\n    // rAF crop loop would just burn CPU/GPU for the whole (possibly long) pause.\n    this.drawing = false;\n    this.state = 'paused';\n    this.onpause();\n  }\n\n  public resume(): void {\n    if(this.state !== 'paused' || !this.mediaRecorder) return;\n    // Refresh the canvas and restart the crop loop before the recorders resume,\n    // so they don't capture a stale frozen frame.\n    this.drawCroppedFrame();\n    this.startDrawLoop();\n    try {\n      this.previewRecorder?.resume();\n    } catch(e) {}\n    this.mediaRecorder.resume();\n    this.state = 'recording';\n    this.onresume();\n  }\n\n  // A playable Blob of everything captured so far — for the paused preview.\n  // Sourced from the streamable (webm) chunks; mp4's own chunks aren't\n  // mid-stream playable. Undefined when no streamable source exists (e.g.\n  // mp4-only browsers) — the caller then just shows the frozen last frame.\n  public getSnapshot(): Blob | undefined {\n    const chunks = this.previewRecorder ? this.previewChunks : this.chunks;\n    if(!chunks.length || !this.snapshotContainer) return undefined;\n    return new Blob(chunks, {type: this.snapshotContainer});\n  }\n\n  public stop(): void {\n    if(this.state === 'inactive' || !this.mediaRecorder) return;\n    this.state = 'inactive';\n    try {\n      this.previewRecorder?.stop();\n    } catch(e) {}\n    try {\n      this.mediaRecorder.stop(); // → onstop → emitResult()\n    } catch(e) {\n      this.emitResult(); // stop() threw and onstop won't fire — emit directly\n    }\n  }\n\n  // Emit the recorded blob + fire onstop exactly once, whether triggered by the\n  // recorder's onstop or the stop()-error fallback. The camera stream is NOT\n  // released here — the caller fades the preview out and calls releaseStream().\n  private emitResult() {\n    if(this.finished) return;\n    this.finished = true;\n    const blob = new Blob(this.chunks, {type: this.mimeType});\n    this.ondataavailable(blob);\n    this.onstop();\n  }\n\n  // Stop the camera/mic + canvas pipeline. Public so the caller can keep the\n  // preview visible during the stop animation and release afterwards.\n  // Idempotent.\n  public releaseStream() {\n    this.drawing = false;\n    // Stops the camera+mic stream — including one still awaiting getUserMedia\n    // (see start()), which dispose() stops the instant it resolves.\n    this.acquisition?.dispose();\n    this.acquisition = undefined;\n\n    if(this.previewRecorder) {\n      try {\n        if(this.previewRecorder.state !== 'inactive') this.previewRecorder.stop();\n      } catch(e) {}\n      this.previewRecorder.ondataavailable = null;\n      this.previewRecorder = undefined;\n    }\n    this.previewChunks = [];\n\n    if(this.mediaRecorder) {\n      try {\n        if(this.mediaRecorder.state !== 'inactive') this.mediaRecorder.stop();\n      } catch(e) {}\n      this.mediaRecorder.ondataavailable = null;\n      this.mediaRecorder.onstop = null;\n      this.mediaRecorder = undefined;\n    }\n    // Free the recorded blob array (can be several MB) instead of holding it\n    // until the next start(). The sent Blob was already built in emitResult().\n    this.chunks = [];\n\n    if(this.canvasStream) {\n      this.canvasStream.getTracks().forEach((t) => {\n        try {\n          t.stop();\n        } catch(e) {}\n      });\n      this.canvasStream = undefined;\n    }\n\n    if(this.drawVideo) {\n      try {\n        this.drawVideo.pause();\n      } catch(e) {}\n      this.drawVideo.srcObject = null;\n      this.drawVideo = undefined;\n    }\n    this.canvas = undefined;\n    this.canvasCtx = undefined;\n\n    // `this.stream` is the acquisition's stream; dispose() above stopped its\n    // tracks.\n    this.stream = undefined;\n  }\n}\n","// Canvas renderer for the in-input voice recording waveform.\n//   * During recording: bars push in from the right and scroll left once the\n//     visible window fills. Each bar is one normalized peak.\n//   * During pause/playback: peaks are frozen and a vertical playhead overlay\n//     splits \"played\" (dim) from \"remaining\" (bright) bars.\n\nconst BAR_WIDTH = 3;\nconst BAR_GAP = 3;\nconst BAR_RADIUS = 1.5;\nconst MIN_BAR_HEIGHT = 3;\n\nexport interface LiveWaveformOptions {\n  height?: number;\n  width?: number;\n  // CSS custom property names to read colors from the canvas element. Falls back\n  // to the resolved `color` if the var is empty.\n  activeColorVar?: string;\n  inactiveColorVar?: string;\n}\n\nexport default class LiveWaveform {\n  public element: HTMLCanvasElement;\n  private ctx: CanvasRenderingContext2D;\n  private peaks: number[] = [];\n  // Lifetime peak — used as the normalization reference. Speech of the same\n  // loudness renders at the same height because the reference doesn't shrink\n  // between syllables. A new louder peak rescales the reference upward; old\n  // bars already rendered keep their drawn height (we don't repaint them).\n  private maxPeak = 0.05;\n  private capacity = 0;\n  private cssWidth = 0;\n  private cssHeight = 0;\n  private dpr = 1;\n  private progress: number | undefined;\n  private activeColorVar: string;\n  private inactiveColorVar: string;\n  private rafScheduled = false;\n  private resizeObserver?: ResizeObserver;\n  // Called when the user clicks on the waveform. Argument is a 0..1 position\n  // along the bars (left edge = 0, right edge = 1). Only invoked while\n  // setSeekable(true) has been called — by convention the panel only enables\n  // seeking during playback.\n  public onSeek?: (progress: number) => void;\n  private seekable = false;\n\n  constructor(opts: LiveWaveformOptions = {}) {\n    this.element = document.createElement('canvas');\n    this.element.classList.add('voice-recording-waveform');\n    this.ctx = this.element.getContext('2d');\n    this.activeColorVar = opts.activeColorVar || '--primary-color';\n    this.inactiveColorVar = opts.inactiveColorVar || '--secondary-color';\n\n    this.cssHeight = opts.height ?? 36;\n    if(opts.width) this.cssWidth = opts.width;\n\n    this.resizeObserver = new ResizeObserver(() => {\n      this.measureAndResize();\n      this.draw();\n    });\n    this.resizeObserver.observe(this.element);\n\n    this.element.addEventListener('click', this.onClick);\n  }\n\n  private onClick = (e: MouseEvent) => {\n    if(!this.seekable || !this.onSeek) return;\n    const rect = this.element.getBoundingClientRect();\n    if(rect.width <= 0) return;\n    const x = e.clientX - rect.left;\n    const progress = Math.max(0, Math.min(1, x / rect.width));\n    this.onSeek(progress);\n  };\n\n  public setSeekable(seekable: boolean) {\n    this.seekable = seekable;\n    this.element.style.cursor = seekable ? 'pointer' : '';\n  }\n\n  private measureAndResize() {\n    const rect = this.element.getBoundingClientRect();\n    if(rect.width <= 0) return;\n\n    this.cssWidth = rect.width;\n    this.cssHeight = rect.height;\n    this.dpr = window.devicePixelRatio || 1;\n    this.element.width = Math.round(this.cssWidth * this.dpr);\n    this.element.height = Math.round(this.cssHeight * this.dpr);\n    this.capacity = Math.max(1, Math.floor((this.cssWidth + BAR_GAP) / (BAR_WIDTH + BAR_GAP)));\n\n    // Trim oldest peaks if window shrinks below current buffer.\n    if(this.peaks.length > this.capacity) {\n      this.peaks.splice(0, this.peaks.length - this.capacity);\n    }\n  }\n\n  public pushPeak(value: number) {\n    if(value > this.maxPeak) this.maxPeak = value;\n    const denom = Math.max(this.maxPeak, 0.02);\n    const normalized = Math.min(1, value / denom);\n    this.peaks.push(normalized);\n    if(this.peaks.length > this.capacity) {\n      this.peaks.splice(0, this.peaks.length - this.capacity);\n    }\n    this.scheduleDraw();\n  }\n\n  // Replace the entire peak buffer (used when computing the full waveform from\n  // recorded audio for the pause/playback view).\n  public setPeaks(peaks: ArrayLike<number>) {\n    const fitted: number[] = [];\n    if(this.capacity <= 0) this.measureAndResize();\n    const cap = this.capacity || 1;\n    if(peaks.length <= cap) {\n      for(let i = 0; i < peaks.length; ++i) fitted.push(peaks[i]);\n    } else {\n      const ratio = peaks.length / cap;\n      for(let i = 0; i < cap; ++i) {\n        const start = Math.floor(i * ratio);\n        const end = Math.floor((i + 1) * ratio);\n        let peak = 0;\n        for(let j = start; j < end && j < peaks.length; ++j) {\n          if(peaks[j] > peak) peak = peaks[j];\n        }\n        fitted.push(peak);\n      }\n    }\n    let max = 0.001;\n    for(let i = 0; i < fitted.length; ++i) if(fitted[i] > max) max = fitted[i];\n    for(let i = 0; i < fitted.length; ++i) fitted[i] = Math.min(1, fitted[i] / max);\n\n    this.peaks = fitted;\n    this.scheduleDraw();\n  }\n\n  public setProgress(progress: number | undefined) {\n    this.progress = progress;\n    this.scheduleDraw();\n  }\n\n  public clear() {\n    this.peaks = [];\n    this.maxPeak = 0.05;\n    this.progress = undefined;\n    this.scheduleDraw();\n  }\n\n  private scheduleDraw() {\n    if(this.rafScheduled) return;\n    this.rafScheduled = true;\n    requestAnimationFrame(() => {\n      this.rafScheduled = false;\n      this.draw();\n    });\n  }\n\n  private draw() {\n    if(!this.cssWidth) this.measureAndResize();\n    const w = this.cssWidth;\n    const h = this.cssHeight;\n    if(!w || !h) return;\n    const ctx = this.ctx;\n    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);\n    ctx.clearRect(0, 0, w, h);\n\n    if(!this.peaks.length) return;\n\n    const stride = BAR_WIDTH + BAR_GAP;\n    const totalWidth = this.peaks.length * stride - BAR_GAP;\n    // Align bars to the right edge so live recording grows from the right.\n    const startX = Math.max(0, w - totalWidth);\n    const midY = h / 2;\n\n    const computed = getComputedStyle(this.element);\n    const activeColor = computed.getPropertyValue(this.activeColorVar).trim() || computed.color;\n    ctx.fillStyle = activeColor;\n\n    // Progress overlay is only used during playback. Without progress every\n    // bar is primary (recording / paused-preview look). With progress set,\n    // bars left of the playhead stay primary and bars to the right fade to\n    // 30% (matches how the standard voice-message bubble draws unplayed bars).\n    const hasProgress = this.progress != null;\n    const progressPx = hasProgress ?\n      startX + Math.max(0, Math.min(1, this.progress)) * totalWidth :\n      Infinity;\n\n    for(let i = 0; i < this.peaks.length; ++i) {\n      const x = startX + i * stride;\n      if(x + BAR_WIDTH < 0) continue;\n      const peak = this.peaks[i];\n      const barH = Math.max(MIN_BAR_HEIGHT, Math.min(h, peak * h));\n      const y = midY - barH / 2;\n\n      ctx.globalAlpha = !hasProgress || x + BAR_WIDTH / 2 <= progressPx ? 1 : 0.3;\n\n      if((ctx as any).roundRect) {\n        ctx.beginPath();\n        (ctx as any).roundRect(x, y, BAR_WIDTH, barH, BAR_RADIUS);\n        ctx.fill();\n      } else {\n        ctx.fillRect(x, y, BAR_WIDTH, barH);\n      }\n    }\n\n    ctx.globalAlpha = 1;\n  }\n\n  public destroy() {\n    this.resizeObserver?.disconnect();\n    this.resizeObserver = undefined;\n    this.element.removeEventListener('click', this.onClick);\n    this.peaks = [];\n  }\n}\n","// Self-contained recording UI overlay shown in the chat input while the user\n// is recording (or has paused) a voice message. The whole subtree lives inside\n// one absolutely-positioned container so the chat input can fade or slide it\n// in/out atomically.\n//\n// Layout while recording:\n//   [trash] [● red dot] [waveform .....................] [timer] [pause]\n// Layout while paused / playing back:\n//   [trash] [play/pause] [waveform .....................] [timer] [microphone]\n//\n// External wiring:\n//   * pushPeak()           — call for every live amplitude during recording.\n//   * setPeaks()           — replace buffer with the full recording (used for\n//                            the static playback view once paused).\n//   * setTimer()           — update the timer text (MM:SS,CS).\n//   * setMode()            — switch between recording / paused (+ playing).\n//   * setPlaybackProgress  — drives the playhead overlay during playback.\n//   * onCancel             — discard recording.\n//   * onPauseToggle        — pause while recording / resume recording while paused.\n//   * onPlayToggle         — playback / pause playback (paused mode only).\n\nimport Icon from '@components/icon';\nimport Button from '@components/button';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport LiveWaveform from './liveWaveform';\n\nexport interface VoiceRecordingPanelOptions {\n  onCancel: () => void;\n  onPauseToggle: () => void;\n  onPlayToggle: () => void;\n  onSeek: (progress: number) => void;\n}\n\nexport type VoiceRecordingMode = 'recording' | 'paused';\n\nexport default class VoiceRecordingPanel {\n  public element: HTMLDivElement;\n  public waveform: LiveWaveform;\n\n  private btnCancel: HTMLButtonElement;\n  // Pill container that holds the lead + waveform on a tinted background.\n  private pillEl: HTMLDivElement;\n  // Left-of-waveform slot — red dot while recording, play/pause while paused.\n  private leadEl: HTMLDivElement;\n  private dotEl: HTMLDivElement;\n  private btnPlayToggle: HTMLButtonElement;\n  private playPlayIcon: HTMLElement;\n  private playPauseIcon: HTMLElement;\n  // Right-of-timer slot — pause while recording, microphone while paused.\n  private btnPauseToggle: HTMLButtonElement;\n  private pauseIconRecord: HTMLElement;\n  private pauseIconMic: HTMLElement;\n\n  private timerEl: HTMLSpanElement;\n  private listenerSetter = new ListenerSetter();\n  private mode: VoiceRecordingMode = 'recording';\n  private isPlaying = false;\n\n  constructor(opts: VoiceRecordingPanelOptions) {\n    this.element = document.createElement('div');\n    this.element.classList.add('voice-recording-panel');\n\n    this.btnCancel = Button('btn-icon voice-recording-cancel danger');\n    this.btnCancel.append(Icon('delete', 'voice-recording-cancel-icon'));\n\n    this.leadEl = document.createElement('div');\n    this.leadEl.classList.add('voice-recording-lead');\n\n    this.dotEl = document.createElement('div');\n    this.dotEl.classList.add('voice-recording-dot');\n\n    this.btnPlayToggle = Button('btn-icon voice-recording-play');\n    this.playPlayIcon = Icon('play', 'voice-recording-play-icon', 'voice-recording-play-icon--play');\n    this.playPauseIcon = Icon('pause', 'voice-recording-play-icon', 'voice-recording-play-icon--pause');\n    this.btnPlayToggle.append(this.playPlayIcon, this.playPauseIcon);\n\n    this.leadEl.append(this.dotEl, this.btnPlayToggle);\n\n    this.waveform = new LiveWaveform();\n\n    this.timerEl = document.createElement('span');\n    this.timerEl.classList.add('voice-recording-timer');\n    this.timerEl.textContent = '0:00,0';\n\n    this.btnPauseToggle = Button('btn-icon voice-recording-pause-toggle');\n    this.pauseIconRecord = Icon('pause', 'voice-recording-pause-icon', 'voice-recording-pause-icon--pause');\n    this.pauseIconMic = Icon('microphone', 'voice-recording-pause-icon', 'voice-recording-pause-icon--mic');\n    this.btnPauseToggle.append(this.pauseIconRecord, this.pauseIconMic);\n\n    this.pillEl = document.createElement('div');\n    this.pillEl.classList.add('voice-recording-pill');\n    this.pillEl.append(this.leadEl, this.waveform.element, this.timerEl);\n\n    this.element.append(\n      this.btnCancel,\n      this.pillEl,\n      this.btnPauseToggle\n    );\n\n    attachClickEvent(this.btnCancel, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onCancel();\n    }, {listenerSetter: this.listenerSetter});\n\n    attachClickEvent(this.btnPauseToggle, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onPauseToggle();\n    }, {listenerSetter: this.listenerSetter});\n\n    attachClickEvent(this.btnPlayToggle, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onPlayToggle();\n    }, {listenerSetter: this.listenerSetter});\n\n    this.waveform.onSeek = (progress) => opts.onSeek(progress);\n\n    this.setMode('recording');\n  }\n\n  public setMode(mode: VoiceRecordingMode) {\n    this.mode = mode;\n    this.element.classList.toggle('voice-recording-panel--paused', mode === 'paused');\n    this.element.classList.toggle('voice-recording-panel--recording', mode === 'recording');\n    if(mode === 'recording') {\n      this.setPlaying(false);\n      this.waveform.setProgress(undefined);\n    }\n  }\n\n  public getMode(): VoiceRecordingMode {\n    return this.mode;\n  }\n\n  public setPlaying(isPlaying: boolean) {\n    this.isPlaying = isPlaying;\n    this.element.classList.toggle('voice-recording-panel--playing', isPlaying);\n  }\n\n  public setSeekable(seekable: boolean) {\n    this.waveform.setSeekable(seekable);\n  }\n\n  public getIsPlaying() {\n    return this.isPlaying;\n  }\n\n  public setPlaybackProgress(progress: number | undefined) {\n    this.waveform.setProgress(progress);\n  }\n\n  public setTimer(text: string) {\n    if(this.timerEl.textContent !== text) this.timerEl.textContent = text;\n  }\n\n  public pushPeak(value: number) {\n    this.waveform.pushPeak(value);\n  }\n\n  public setPeaks(peaks: ArrayLike<number>) {\n    this.waveform.setPeaks(peaks);\n  }\n\n  public clearPeaks() {\n    this.waveform.clear();\n  }\n\n  public destroy() {\n    this.listenerSetter.removeAll();\n    this.waveform.destroy();\n    this.element.remove();\n  }\n}\n","// Just the visual for a round video note while recording: a 360x360 circular\n// camera preview centered on screen with a drop shadow (no dimming layer) and\n// the same SVG progress ring incoming round videos use (the shared ProgressRing\n// component, @components/progressRing).\n//\n// All recording *controls* (trash / waveform / timer / pause / preview / send)\n// are the regular VoiceRecordingPanel + send button that live in the chat input\n// — this owns none of them. ChatRecording drives the voice panel for video\n// exactly as for audio; this overlay is purely the кружок.\n//\n// Authored in Solid: reactive signals (mode / playing / progress) back the JSX,\n// and createVideoRecordingPanel() exposes the same imperative handle ChatRecording\n// drives (mirrors createProgressRing in progressRing.tsx).\n\nimport {Accessor, createRoot, createSignal, JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport ProgressRing from '@components/progressRing';\n\nconst STAGE_SIZE = 360;\n\nexport type VideoRecordingMode = 'recording' | 'paused';\n\nexport default function VideoRecordingPanel(props: {\n  mode: Accessor<VideoRecordingMode | undefined>,\n  playing: Accessor<boolean>,\n  progress: Accessor<number>,\n  // Refs fire synchronously while the body runs — that's how the handle below\n  // gets the real DOM nodes (calling the component returns the HMR wrapper, not\n  // the <div>). rootRef = the stage element to mount; ref = the preview <video>.\n  rootRef: (stage: HTMLDivElement) => void,\n  ref: (video: HTMLVideoElement) => void\n}): JSX.Element {\n  return (\n    <div\n      ref={props.rootRef}\n      class={classNames(\n        'video-recording-stage',\n        props.mode() === 'recording' && 'video-recording-stage--recording',\n        props.mode() === 'paused' && 'video-recording-stage--paused',\n        props.playing() && 'video-recording-stage--playing'\n      )}\n    >\n      <div\n        class=\"video-recording-circle\"\n        style={{width: STAGE_SIZE + 'px', height: STAGE_SIZE + 'px'}}\n      >\n        <video\n          class=\"video-recording-preview\"\n          ref={(el) => {\n            el.muted = true;\n            el.autoplay = true;\n            el.playsInline = true;\n            props.ref(el);\n          }}\n        />\n        <ProgressRing\n          size={STAGE_SIZE}\n          strokeOpacity={0.9}\n          class=\"video-recording-progress-ring\"\n          progress={props.progress()}\n        />\n      </div>\n    </div>\n  );\n}\n\nexport interface VideoRecordingPanelHandle {\n  element: HTMLDivElement;\n  readonly previewVideo: HTMLVideoElement;\n  setMode(mode: VideoRecordingMode): void;\n  getMode(): VideoRecordingMode | undefined;\n  startLivePreview(stream: MediaStream): void;\n  reset(): void;\n  setPlaying(isPlaying: boolean): void;\n  getIsPlaying(): boolean;\n  setProgress(progress: number): void;\n  destroy(): void;\n}\n\n// Imperative handle for the (non-Solid) ChatRecording controller. Owns its own\n// reactive root; destroy() disposes it.\nexport function createVideoRecordingPanel(): VideoRecordingPanelHandle {\n  return createRoot((dispose) => {\n    const [mode, setModeSignal] = createSignal<VideoRecordingMode | undefined>(undefined);\n    const [playing, setPlayingSignal] = createSignal(false);\n    const [progress, setProgressSignal] = createSignal(0);\n\n    let element: HTMLDivElement;\n    let previewVideo: HTMLVideoElement;\n    // Bumped on each startLivePreview()/reset() so a pending \"reveal on first\n    // frame\" callback from a superseded session is ignored.\n    let liveToken = 0;\n    let clearVideoTimer: number;\n\n    // Capture the real DOM nodes via refs (set synchronously while the body\n    // runs); the component's return value is the HMR wrapper, not the <div>.\n    VideoRecordingPanel({\n      mode,\n      playing,\n      progress,\n      rootRef: (stage) => element = stage,\n      ref: (video) => previewVideo = video\n    });\n\n    const setMode = (m: VideoRecordingMode) => {\n      // A fresh recording/preview is about to show — cancel any pending\n      // fade-out cleanup.\n      if(clearVideoTimer) {\n        clearTimeout(clearVideoTimer);\n        clearVideoTimer = undefined;\n      }\n      setModeSignal(m);\n      if(m === 'recording') setPlayingSignal(false);\n    };\n\n    const releasePreview = () => {\n      previewVideo.srcObject = null;\n      if(previewVideo.src) {\n        previewVideo.removeAttribute('src');\n        try {\n          previewVideo.load();\n        } catch(e) {}\n      }\n    };\n\n    // Attach the live camera stream and reveal the circle only once the first\n    // frame is actually painted — revealing immediately fades in a black circle\n    // while the camera spins up. Cancelled if reset() runs first.\n    const startLivePreview = (stream: MediaStream) => {\n      const token = ++liveToken;\n      previewVideo.srcObject = stream;\n      previewVideo.muted = true;\n      previewVideo.play().catch(() => {});\n\n      let safety: number;\n      const reveal = () => {\n        if(safety) {\n          clearTimeout(safety); // don't let the safety net fire after a real reveal\n          safety = undefined;\n        }\n        if(liveToken !== token) return; // a newer call / reset superseded us\n        setMode('recording');\n      };\n\n      const rvfc = previewVideo as HTMLVideoElement & {requestVideoFrameCallback?: (cb: () => void) => number};\n      if(typeof rvfc.requestVideoFrameCallback === 'function') {\n        rvfc.requestVideoFrameCallback(() => reveal());\n      } else {\n        previewVideo.addEventListener('loadeddata', reveal, {once: true});\n      }\n      // Safety net: reveal anyway if the frame callback never fires.\n      safety = window.setTimeout(reveal, 800);\n    };\n\n    // Hide the circle and release the preview. We DON'T clear the camera source\n    // immediately: dropping the mode class fades the stage out over its opacity\n    // transition while the last camera frame stays painted, so the brief\n    // camera-off black frame never shows. The source is released after the fade.\n    const reset = () => {\n      ++liveToken; // cancel any pending reveal-on-first-frame\n      setModeSignal(undefined);\n      setPlayingSignal(false);\n      setProgressSignal(0);\n\n      if(clearVideoTimer) clearTimeout(clearVideoTimer);\n      clearVideoTimer = window.setTimeout(() => {\n        clearVideoTimer = undefined;\n        releasePreview();\n      }, 250); // matches the .video-recording-stage opacity transition (.2s) + margin\n    };\n\n    return {\n      element,\n      get previewVideo() {\n        return previewVideo;\n      },\n      setMode,\n      getMode: () => mode(),\n      startLivePreview,\n      reset,\n      setPlaying: (isPlaying: boolean) => setPlayingSignal(isPlaying),\n      getIsPlaying: () => playing(),\n      setProgress: (value: number) => setProgressSignal(value),\n      destroy: () => {\n        if(clearVideoTimer) clearTimeout(clearVideoTimer);\n        releasePreview();\n        element.remove();\n        dispose();\n      }\n    };\n  });\n}\n","import ctx from '@environment/ctx';\nimport noop from '@helpers/noop';\n\n// It's better to use timeout instead of interval, because interval can be corrupted\nexport default function eachTimeout(callback: () => any, getNextTimeout: () => number, runFirst = true) {\n  const cancel = () => {\n    clearTimeout(timeout);\n  };\n\n  // replace callback to run noop and restore after\n  const _callback = callback;\n  if(!runFirst) {\n    callback = noop;\n  }\n\n  let timeout: number;\n  (function run() {\n    callback();\n    timeout = ctx.setTimeout(run, Math.max(0, getNextTimeout()));\n  })();\n\n  callback = _callback;\n\n  return cancel;\n}\n","import eachTimeout from '@helpers/eachTimeout';\n\n// It's better to use timeout instead of interval, because interval can be corrupted\nexport default function eachSecond(callback: () => any, runFirst?: boolean) {\n  return eachTimeout(callback, () => 1000 - new Date().getMilliseconds(), runFirst);\n}\n","import {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\n\nexport interface AnimatedSuperOptions {\n  duration?: number;\n}\n\nexport class AnimatedSuper {\n  static BASE_CLASS = 'animated-super';\n  static DEFAULT_DURATION = 200;\n  container: HTMLDivElement;\n  rows: {[index: string]: {element: HTMLElement, middleware: MiddlewareHelper, timeout?: number, new?: true}} = {};\n  clearTimeout: number;\n\n  duration: AnimatedSuperOptions['duration'];\n  constructor(options?: AnimatedSuperOptions) {\n    this.duration = options?.duration ?? AnimatedSuper.DEFAULT_DURATION;\n    this.container = document.createElement('div');\n    this.container.className = AnimatedSuper.BASE_CLASS;\n  }\n\n  public getRow(index: number, animateFirst = false) {\n    if(this.rows[index]) return this.rows[index].element;\n    const row = document.createElement('div');\n    const isFirst = !Object.keys(this.rows).length && !animateFirst;\n    row.className = AnimatedSuper.BASE_CLASS + '-row' + (isFirst ? '' : ' is-hiding hide');\n    this.rows[index] = {element: row, middleware: row.middlewareHelper = getMiddleware(), new: true};\n    this.container.append(row);\n    return row;\n  }\n\n  public clearRow(index: number) {\n    if(!this.rows[index]) return;\n    this.rows[index].element.remove();\n    this.rows[index].middleware.destroy();\n    delete this.rows[index];\n  }\n\n  public clearRows(currentIndex?: number) {\n    if(this.clearTimeout) clearTimeout(this.clearTimeout);\n    this.clearTimeout = window.setTimeout(() => {\n      for(const i in this.rows) {\n        if(+i === currentIndex) continue;\n        this.clearRow(+i);\n      }\n    }, this.duration);\n  }\n\n  public setNewRow(index: number, reflow = false) {\n    const row = this.rows[index];\n    if(row.new) {\n      if(reflow) {\n        row.element.classList.remove('hide');\n        void row.element.offsetLeft; // reflow\n      } else {\n        row.element.classList.remove('is-hiding', 'hide');\n      }\n\n      delete row.new;\n    }\n\n    this.clearRows(index);\n  }\n\n  public animate(index: number, previousIndex: number, fromTop = index > previousIndex, ignorePrevious = false) {\n    if(index === previousIndex) { // * handle if set index 0 and previousIndex 0\n      return this.setNewRow(index);\n    }\n\n    const row = this.rows[index];\n    const previousRow = this.rows[previousIndex];\n    if(!previousRow && !ignorePrevious) {\n      return this.setNewRow(index);\n    }\n\n    const sides = ['from-top', 'from-bottom'];\n    if(!fromTop) sides.reverse();\n\n    row.element.classList.add(sides[0]);\n    row.element.classList.remove(sides[1]);\n    if(previousRow) {\n      previousRow.element.classList.add(sides[1]);\n      previousRow.element.classList.remove(sides[0]);\n    }\n\n    if(row.new) {\n      this.setNewRow(index, true);\n    }\n\n    row.element.classList.toggle('is-hiding', false);\n    previousRow && previousRow.element.classList.toggle('is-hiding', true);\n\n    this.clearRows(index);\n  }\n\n  public destroy() {\n    for(const i in this.rows) {\n      this.clearRow(+i);\n    }\n  }\n}\n","import {fastRaf} from '@helpers/schedulers';\nimport {AnimatedSuper} from '@components/animatedSuper';\n\nexport interface AnimatedCounterOptions {\n  reverse?: boolean;\n  duration?: number;\n  prefix?: string;\n  calculateWidth?: ((text: string) => number) | true;\n}\n\nexport class AnimatedCounter {\n  static EMPTY_INDEX = -1;\n  static BASE_CLASS = 'animated-counter';\n  container: HTMLElement;\n  decimals: {\n    container: HTMLElement,\n    placeholder: HTMLElement,\n    animatedSuper: AnimatedSuper\n  }[] = [];\n  prefixContainer?: HTMLElement;\n  previousNumber = 0;\n  clearTimeout: number;\n\n  prefix?: AnimatedCounterOptions['prefix'];\n  reverse: AnimatedCounterOptions['reverse'];\n  duration: AnimatedCounterOptions['duration'];\n  calculateWidth?: AnimatedCounterOptions['calculateWidth'];\n\n  constructor(options: AnimatedCounterOptions) {\n    this.reverse = options.reverse;\n    this.duration = options.duration ?? AnimatedSuper.DEFAULT_DURATION;\n    this.container = document.createElement('div');\n    this.container.className = AnimatedCounter.BASE_CLASS;\n    this.calculateWidth = options.calculateWidth;\n\n    if(this.calculateWidth) {\n      this.container.classList.add('animated-counter-dynamic-width');\n    }\n\n    if(options.prefix) {\n      const prefixContainer = document.createElement('div');\n      prefixContainer.className = AnimatedCounter.BASE_CLASS + '-decimal-prefix';\n      prefixContainer.innerText = this.prefix = options.prefix;\n      this.container.append(prefixContainer);\n      this.prefixContainer = prefixContainer;\n    }\n  }\n\n  getDecimal(index: number) {\n    if(this.decimals[index]) return this.decimals[index];\n    const item = document.createElement('div');\n    item.className = AnimatedCounter.BASE_CLASS + '-decimal';\n\n    const placeholder = document.createElement('div');\n    placeholder.className = AnimatedCounter.BASE_CLASS + '-decimal-placeholder';\n\n    const animatedSuper = new AnimatedSuper({duration: this.duration});\n    animatedSuper.container.className = AnimatedCounter.BASE_CLASS + '-decimal-wrapper';\n\n    item.append(placeholder, animatedSuper.container);\n\n    this.container.append(item);\n\n    return this.decimals[index] = {container: item, placeholder, animatedSuper};\n  }\n\n  clear(number: number) {\n    if(this.clearTimeout) clearTimeout(this.clearTimeout);\n\n    const decimals = ('' + number).length;\n    if(decimals >= this.decimals.length) {\n      return;\n    }\n\n    this.clearTimeout = window.setTimeout(() => {\n      const byDecimal = this.decimals.splice(decimals, this.decimals.length - decimals);\n      byDecimal.forEach((decimal) => {\n        decimal.container.remove();\n      });\n    }, this.duration);\n  }\n\n  hideLeft(number: number) {\n    const decimals = ('' + number).length;\n    const byDecimal = this.decimals.slice(decimals);// this.decimals.splice(deleteCount, this.decimals.length - deleteCount);\n    byDecimal.forEach((decimal) => {\n      const previousDecimalNumber = +decimal.placeholder.innerText || 0;\n      const row = decimal.animatedSuper.getRow(AnimatedCounter.EMPTY_INDEX, true);\n      decimal.animatedSuper.animate(AnimatedCounter.EMPTY_INDEX, previousDecimalNumber, this.reverse ? number < this.previousNumber : number > this.previousNumber, true);\n    });\n\n    this.clear(number);\n  }\n\n  setCount(number: number, noRaf?: boolean) {\n    // this.prepareNumber(number);\n\n    const texts: string[] = [];\n    const nextRows: HTMLElement[] = [];\n    const previousByDecimal = Array.from('' + this.previousNumber).map((n) => +n);\n    const byDecimal = Array.from('' + number).map((n) => +n);\n    byDecimal.forEach((decimalNumber, idx) => {\n      const decimal = this.getDecimal(idx);\n      const row = decimal.animatedSuper.getRow(decimalNumber, true);\n      const previousDecimalNumber = previousByDecimal[idx] ?? AnimatedCounter.EMPTY_INDEX;\n      const text = '' + decimalNumber;\n      row.innerText = decimal.placeholder.innerText = text;\n      texts.push(text);\n      nextRows.push(row);\n      decimal.animatedSuper.animate(\n        decimalNumber,\n        previousDecimalNumber,\n        this.reverse ? number < this.previousNumber : number > this.previousNumber,\n        true\n      );\n    });\n\n    const setWidth = () => {\n      let width: number;\n      if(typeof(calculateWidth) === 'boolean') {\n        width = nextRows.reduce((sum, row) => sum + row.clientWidth, 0);\n        if(this.prefixContainer) {\n          width += this.prefixContainer.clientWidth;\n        }\n      } else {\n        const text = (this.prefix || '') + texts.join('');\n        width = calculateWidth(text);\n      }\n\n      this.container.style.setProperty('--width', width + 'px');\n    };\n\n    const {calculateWidth} = this;\n    if(calculateWidth) {\n      noRaf ? setWidth() : fastRaf(setWidth);\n    }\n\n    this.hideLeft(number);\n    // this.clear(number);\n    this.previousNumber = number;\n  }\n\n  destroy() {\n    this.decimals.forEach((decimal) => {\n      decimal.animatedSuper.destroy();\n    });\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {JSX} from 'solid-js';\n\nimport classNames from '@helpers/string/classNames';\nimport appImManager from '@lib/appImManager';\n\nimport showTooltip from '@components/tooltip';\n\ntype CurrentToast = {\n  hide: () => void,\n  closeOnPeerChange: boolean\n};\n\nlet current: CurrentToast;\nlet isListenerSet = false;\n\n/**\n * A toast docked just below the chat topbar (and floating pinned plates).\n *\n * Mounted on the .chat element (sibling to .topbar / .bubbles), NOT inside\n * .bubbles: .bubbles is a transformed z-index:1 stacking context that would\n * trap the toast below the topbar (z-index:2) and chat input. Docking is done\n * by the chat-toast class (see _chatToast.scss).\n *\n * Only one toast is shown at a time — showing a new one hides the previous.\n */\nexport default function showChatToast(options: {\n  textElement: HTMLElement | DocumentFragment,\n  title?: HTMLElement,\n  rightElement?: JSX.Element,\n  icon?: Icon,\n  class?: string,\n  duration?: number,\n  // 'slide' emerges from behind the topbar, 'fade' rises into place fading in\n  animation?: 'slide' | 'fade',\n  closeOnPeerChange?: boolean,\n  onHide?: () => void\n}) {\n  current?.hide();\n\n  if(!isListenerSet) {\n    isListenerSet = true;\n    appImManager.addEventListener('peer_changed', () => {\n      if(current?.closeOnPeerChange) {\n        current.hide();\n      }\n    });\n  }\n\n  options.title?.classList.add('text-bold');\n\n  const {close} = showTooltip({\n    element: appImManager.chat.container,\n    container: appImManager.chat.container,\n    mountOn: appImManager.chat.container,\n    relative: true,\n    vertical: 'top',\n    class: classNames('chat-toast', `chat-toast--${options.animation ?? 'slide'}`, options.class),\n    icon: options.icon,\n    textElement: options.title ?? options.textElement,\n    subtitleElement: options.title && options.textElement,\n    rightElement: options.rightElement,\n    onClose: () => {\n      if(current === entry) {\n        current = undefined;\n      }\n\n      options.onHide?.();\n    }\n  });\n\n  const entry: CurrentToast = current = {\n    hide: close,\n    closeOnPeerChange: options.closeOnPeerChange ?? true\n  };\n\n  if(options.duration) {\n    setTimeout(close, options.duration);\n  }\n\n  return {hide: close};\n}\n","import {Accessor, createEffect, createRoot, createSignal, onCleanup} from 'solid-js';\n\nimport {SEND_PAID_WITH_STARS_DELAY} from '@appManagers/constants';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\nimport eachSecond from '@helpers/eachSecond';\nimport {animate} from '@helpers/animation';\n\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport showChatToast from '@components/chat/chatToast';\n\n\ntype LangKeys = {\n  titleKey: LangPackKey;\n  subtitleKey: LangPackKey;\n};\n\nexport const paidReactionLangKeys: LangKeys = {\n  titleKey: 'PaidReaction.Sent',\n  subtitleKey: 'StarsSentText'\n};\n\nexport const paidMessagesLangKeys: LangKeys = {\n  titleKey: 'PaidMessages.MessagesSent',\n  subtitleKey: 'PaidMessages.YouPaidForMessages'\n};\n\n\nexport default function showUndoablePaidTooltip(props: {\n  sendTime: Accessor<number>;\n  titleCount: Accessor<number>;\n  subtitleCount: Accessor<number>;\n  onUndo: () => void;\n  wider?: boolean;\n} & LangKeys) {\n  createRoot((dispose) => {\n    const [secondsLeft, setSecondsLeft] = createSignal<number>();\n    const [progressCircumference, setProgressCircumference] = createSignal<number>();\n\n    const title = new I18n.IntlElement({key: props.titleKey});\n    const subtitle = new I18n.IntlElement({key: props.subtitleKey});\n\n    createEffect(() => {\n      title.compareAndUpdate({args: [props.titleCount()]});\n      subtitle.compareAndUpdate({args: [props.subtitleCount()]});\n    });\n\n    createEffect(() => {\n      if(!(!!props.sendTime())) {\n        dispose();\n        hide();\n      } else {\n        const disposeTimer = eachSecond(() => {\n          setSecondsLeft((props.sendTime() - Date.now()) / 1000 | 0);\n        });\n\n        animate(() => {\n          const progress = (props.sendTime() - Date.now()) / SEND_PAID_WITH_STARS_DELAY;\n          setProgressCircumference(progress * circumference);\n          return !cleaned;\n        });\n\n        let cleaned = false;\n        onCleanup(() => {\n          cleaned = true;\n          disposeTimer();\n        });\n      }\n    });\n\n    const size = 24;\n    const radius = 10;\n    const circumference = radius * 2 * Math.PI;\n\n    const countdown = new AnimatedCounter({reverse: false});\n    createEffect(() => countdown.setCount(secondsLeft()));\n\n    const {hide} = showChatToast({\n      animation: 'fade',\n      // the undo countdown outlives a chat switch — the send can still be aborted\n      closeOnPeerChange: false,\n      class: classNames('paid-reaction-tooltip', props.wider && 'paid-reaction-tooltip--a-little-wider'),\n      title: title.element,\n      textElement: subtitle.element,\n      rightElement: (\n        <span\n          class=\"tooltip-undo\"\n          onClick={() => void props.onUndo()}\n        >\n          {i18n('Undo')}\n          <span class=\"tooltip-undo-timer\">\n            <svg class=\"tooltip-undo-timer-svg\" width={size + 'px'} height={size + 'px'}>\n              <circle\n                cx={size / 2}\n                cy={size / 2}\n                r={radius}\n                class=\"tooltip-undo-timer-circle\"\n                transform={`rotate(-90, ${size / 2}, ${size / 2})`}\n                stroke-dasharray={`${progressCircumference()} ${circumference}`}\n              ></circle>\n            </svg>\n            <span class=\"tooltip-undo-timer-number\">\n              {countdown.container}\n            </span>\n          </span>\n        </span>\n      ),\n      icon: 'star'\n    });\n  });\n}\n","import {createRoot, createSignal} from 'solid-js';\n\nimport {setReservedStars} from '@stores/stars';\n\n\nconst createPendingUndoableMessage = () => createRoot(dispose => {\n  const [messageCount, setMessageCount] = createSignal(0);\n  const [sendTime, setSendTime] = createSignal(0);\n\n  const [reserved, setReserved] = createSignal(0);\n\n  let abortController = new AbortController;\n\n  return {\n    timeoutId: 0,\n\n    messageCount,\n    setMessageCount,\n    sendTime,\n    setSendTime,\n    reserved,\n    setReserved,\n\n    abort() {\n      abortController.abort();\n    },\n\n    get signal() {\n      return abortController.signal;\n    },\n\n    softReset() {\n      self.clearTimeout(this.timeoutId);\n      this.timeoutId = 0;\n\n      abortController = new AbortController;\n    },\n\n\n    resetGlobalReserved() {\n      setReservedStars(prev => prev - reserved());\n    },\n\n    reset() {\n      this.softReset();\n\n      setSendTime(0);\n      setMessageCount(0);\n\n      setReserved(0);\n    },\n\n    dispose\n  };\n});\n\nexport default createPendingUndoableMessage;\n","import {SEND_PAID_WITH_STARS_DELAY} from '@appManagers/constants';\nimport type {AppManagers} from '@lib/managers';\nimport useStars, {setReservedStars} from '@stores/stars';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport rootScope from '@lib/rootScope';\nimport {i18n} from '@lib/langPack';\nimport noop from '@helpers/noop';\n\nimport confirmationPopup from '@components/confirmationPopup';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport PopupStars from '@components/popups/stars';\nimport PopupElement from '@components/popups';\n\nimport showUndoablePaidTooltip, {paidMessagesLangKeys} from '@components/chat/undoablePaidTooltip';\nimport createPendingUndoableMessage from '@components/chat/pendingUndoableMessage';\nimport type Chat from '@components/chat/chat';\nimport {useAppState} from '@stores/appState';\n\n\ntype PassedDownArgs = {\n  peerId: PeerId;\n  messageCount: number;\n  starsAmount: number;\n};\n\nenum UserConfirmationResult {\n  /**\n   * In case 'Don't show again' was checked previously\n   */\n  Skipped,\n\n  Confirmed,\n  Rejected\n};\n\nexport type ConfirmedPaymentResult = {\n  starsAmount: number;\n  canUndo: boolean;\n};\n\n/**\n * `undefined` if no stars are needed, or a PAYMENT_REJECTED symbol if the users cancels the payment / doesn't have enough balance\n */\ntype PreparedPaymentResult = undefined | typeof PAYMENT_REJECTED | ConfirmedPaymentResult;\n\nexport const PAYMENT_REJECTED = Symbol('Payment rejected');\n\n\nexport default class PaidMessagesInterceptor {\n  private pendingUndoableMessage = createPendingUndoableMessage();\n\n  private static rawStars = useStars();\n\n  /**\n   * Mininum required params to make the message(s) undoable\n   *\n   * (Editable through global class attached to the window)\n   */\n  private static MIN_UNDO_SENDING_PARAMS = {\n    starsAmount: 100,\n    messageCount: 3\n  };\n  // private static MIN_UNDO_SENDING_PARAMS = {\n  //   starsAmount: 2,\n  //   messageCount: 3\n  // };\n\n  public static PaymentRejectedSymbol: typeof PAYMENT_REJECTED = PAYMENT_REJECTED;\n\n  constructor(private chat: Chat, private managers: AppManagers) {}\n\n  public dispose() {\n    this.pendingUndoableMessage.dispose();\n  }\n\n  private static get starsBalance() {\n    return +this.rawStars();\n  }\n\n  /**\n   * The starsAmount better be provided by this interceptor and then passed manually to the send method\n   * to make sure we don't accidentally send stars in a case that might have not been handled\n   */\n  public async prepareStarsForPayment(messageCount: number): Promise<PreparedPaymentResult> {\n    const {peerId, starsAmount} = this.chat\n\n    if(!starsAmount) return;\n\n    const totalStarsAmount = messageCount * starsAmount;\n\n    if(PaidMessagesInterceptor.starsBalance < totalStarsAmount)\n    {\n      this.pendingUndoableMessage.abort();\n      PopupElement.createPopup(PopupStars);\n      return PAYMENT_REJECTED;\n    }\n\n    const userConfirmation = await PaidMessagesInterceptor.checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain: true});\n    if(userConfirmation === UserConfirmationResult.Rejected) return PAYMENT_REJECTED;\n\n    const canUndo = (\n      PaidMessagesInterceptor.canUndoMessageSending({userConfirmation, messageCount, starsAmount}) ||\n      !!this.pendingUndoableMessage.messageCount() // Allow undo if there's some pending undoable messages already\n    );\n\n    if(canUndo)\n    {\n      setReservedStars(prev => prev + totalStarsAmount);\n      this.pendingUndoableMessage.setReserved(prev => prev + totalStarsAmount);\n\n      this.triggerUndoableMessages({peerId, messageCount, starsAmount});\n    }\n\n    return {starsAmount, canUndo};\n  }\n\n  private static canUndoMessageSending(args: {userConfirmation: UserConfirmationResult, messageCount: number, starsAmount: number}) {\n    const {messageCount, starsAmount, userConfirmation} = args;\n\n    if(UserConfirmationResult.Skipped !== userConfirmation) return false;\n\n    return (\n      starsAmount >= this.MIN_UNDO_SENDING_PARAMS.starsAmount ||\n      messageCount >= this.MIN_UNDO_SENDING_PARAMS.messageCount\n    );\n  }\n\n  /**\n   * Static method - to be used outside a chat instance\n   *\n   * The starsAmount better be provided by this interceptor and then passed manually to the send method\n   * to make sure we don't accidentally send stars in a case that might have not been handled\n   */\n  public static async prepareStarsForPayment(args: {messageCount: number, peerId: PeerId}): Promise<PreparedPaymentResult> {\n    const {peerId, messageCount} = args;\n\n    const starsAmount = await rootScope.managers.appPeersManager.getStarsAmount(peerId);\n\n    if(!starsAmount) return;\n\n    const totalStarsAmount = messageCount * starsAmount;\n\n    if(PaidMessagesInterceptor.starsBalance < totalStarsAmount)\n    {\n      PopupElement.createPopup(PopupStars);\n      return PAYMENT_REJECTED;\n    }\n\n    const userConfirmation = await PaidMessagesInterceptor.checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain: false});\n\n    if(userConfirmation === UserConfirmationResult.Rejected) return PAYMENT_REJECTED;\n\n\n    return {starsAmount, canUndo: false};\n  }\n\n  private static async checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain}: PassedDownArgs & {withDontShowAgain: boolean}) {\n    const totalStarsAmount = starsAmount * messageCount;\n\n    let onNotShowAgain = noop;\n\n    if(withDontShowAgain)\n    {\n      const {dontShowPaidMessageWarningFor = []} = await rootScope.managers.appStateManager.getState();\n      const shouldShowWarning = !dontShowPaidMessageWarningFor.includes(peerId);\n\n      if(!shouldShowWarning) return UserConfirmationResult.Skipped;\n\n      onNotShowAgain = () => {\n        const [, setAppState] = useAppState();\n        setAppState('dontShowPaidMessageWarningFor', [...dontShowPaidMessageWarningFor, peerId]);\n      };\n    }\n\n    try\n    {\n      const dontShowAgain = await confirmationPopup({\n        titleLangKey: 'ConfirmPayment',\n        descriptionLangKey: messageCount > 1 ?\n          'PaidMessages.UserChargesForMultipleMessageWarning' :\n          'PaidMessages.UserChargesForOneMessageWarning',\n        descriptionLangArgs: [\n          await wrapPeerTitle({peerId, onlyFirstName: true}),\n          i18n('Stars', [starsAmount]),\n          i18n('Stars', [totalStarsAmount]),\n          ...(messageCount > 1 ? [messageCount] : [])\n        ],\n        checkbox: withDontShowAgain ? {\n          text: 'DontAskAgain'\n        } : undefined,\n        button: {\n          langKey: 'PaidMessages.PayForMessages',\n          langArgs: [messageCount]\n        }\n      });\n\n      if(withDontShowAgain && dontShowAgain) onNotShowAgain();\n    }\n    catch\n    {\n      return UserConfirmationResult.Rejected;\n    }\n\n    return UserConfirmationResult.Confirmed;\n  }\n\n  private triggerUndoableMessages({peerId, messageCount, starsAmount}: PassedDownArgs) {\n    this.pendingUndoableMessage.setMessageCount(prev => prev + messageCount);\n    this.pendingUndoableMessage.setSendTime(Date.now() + SEND_PAID_WITH_STARS_DELAY);\n\n    if(!this.pendingUndoableMessage.timeoutId) {\n      showUndoablePaidTooltip({\n        sendTime: this.pendingUndoableMessage.sendTime,\n        titleCount: this.pendingUndoableMessage.messageCount,\n        subtitleCount: () => this.pendingUndoableMessage.messageCount() * starsAmount,\n        onUndo: () => void this.pendingUndoableMessage.abort(),\n        ...paidMessagesLangKeys\n      });\n    }\n\n    this.pendingUndoableMessage.softReset();\n\n    this.pendingUndoableMessage.signal.addEventListener('abort', () => {\n      this.managers.appMessagesManager.cancelQueuedPaidMessages(peerId);\n      this.pendingUndoableMessage.resetGlobalReserved();\n      this.pendingUndoableMessage.reset();\n    });\n\n    this.pendingUndoableMessage.timeoutId = self.setTimeout(() => {\n      this.managers.appMessagesManager.sendQueuedPaidMessages(peerId);\n      this.pendingUndoableMessage.reset();\n    }, SEND_PAID_WITH_STARS_DELAY);\n  }\n}\n\nMOUNT_CLASS_TO['PaidMessagesInterceptor'] = PaidMessagesInterceptor;\n","import type {MediaSize} from '@helpers/mediaSize';\nimport IS_IMAGE_BITMAP_SUPPORTED from '@environment/imageBitmapSupport';\n\nexport default function scaleMediaElement<T extends {\n  media: CanvasImageSource,\n  mediaSize?: MediaSize,\n  boxSize?: MediaSize,\n  quality?: number,\n  mimeType?: 'image/jpeg' | 'image/png',\n  size?: MediaSize,\n  toDataURL?: boolean\n}>(options: T): Promise<T['toDataURL'] extends true ? {url: string, size: MediaSize} : {blob: Blob, size: MediaSize}> {\n  return new Promise(async(resolve) => {\n    const canvas = document.createElement('canvas');\n    const size = options.size ?? options.mediaSize.aspectFitted(options.boxSize);\n    const dpr = window.devicePixelRatio && 1;\n    canvas.width = size.width * dpr;\n    canvas.height = size.height * dpr;\n    const ctx = canvas.getContext('2d');\n\n    let source: CanvasImageSource;\n    if(IS_IMAGE_BITMAP_SUPPORTED) {\n      source = await createImageBitmap(options.media, {resizeWidth: size.width, resizeHeight: size.height});\n    } else {\n      source = options.media;\n    }\n\n    ctx.drawImage(source, 0, 0, canvas.width, canvas.height);\n\n    if(IS_IMAGE_BITMAP_SUPPORTED) {\n      (source as ImageBitmap)?.close();\n    }\n\n    const mimeType = options.mimeType ?? 'image/jpeg';\n    const quality = options.quality ?? 1;\n    if(options.toDataURL) {\n      const url = canvas.toDataURL(mimeType, quality);\n      resolve({url, size} as any);\n    } else {\n      canvas.toBlob((blob) => {\n        resolve({blob, size} as any);\n      }, mimeType, quality);\n    }\n  });\n}\n","import createVideo from '@helpers/dom/createVideo';\nimport {getMiddleware} from '@helpers/middleware';\n\nexport default function preloadVideo(url: string) {\n  const middlewareHelper = getMiddleware();\n  const promise = new Promise<HTMLVideoElement>((resolve, reject) => {\n    const video = createVideo({middleware: middlewareHelper.get()});\n    video.volume = 0;\n    video.addEventListener('loadedmetadata', () => resolve(video), {once: true});\n    video.addEventListener('error', reject, {once: true});\n    video.src = url;\n  });\n\n  promise.finally(() => {\n    middlewareHelper.destroy();\n  });\n\n  return promise;\n}\n","import pause from '@helpers/schedulers/pause';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport scaleMediaElement from '@helpers/canvas/scaleMediaElement';\nimport preloadVideo from '@helpers/preloadVideo';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\n\n// iOS fits the uploaded video thumb into a square box (320), Android keeps the\n// frame size as-is; 720 matches the media editor's thumbnail cap and stays\n// sharp on retina bubbles (the old 320x240 box crippled portrait videos)\nconst POSTER_MAX_SIZE = 720;\n\nexport function createPosterFromMedia(media: HTMLVideoElement | HTMLImageElement) {\n  let width: number, height: number;\n  if(media instanceof HTMLVideoElement) {\n    width = media.videoWidth;\n    height = media.videoHeight;\n  } else {\n    width = media.naturalWidth;\n    height = media.naturalHeight;\n  }\n\n  return scaleMediaElement({\n    media,\n    mediaSize: makeMediaSize(width, height),\n    // clamp the box to the source so a smaller video is never upscaled\n    boxSize: makeMediaSize(Math.min(width, POSTER_MAX_SIZE), Math.min(height, POSTER_MAX_SIZE)),\n    quality: .9\n  });\n}\n\nexport function createPosterFromVideo(video: HTMLVideoElement): ReturnType<typeof createPosterFromMedia> {\n  return new Promise((resolve, reject) => {\n    video.onseeked = () => {\n      video.onseeked = () => {\n        createPosterFromMedia(video).then(resolve);\n\n        video.onseeked = undefined;\n      };\n\n      setCurrentTime(video, 0);\n    };\n\n    video.onerror = reject;\n    setCurrentTime(video, Math.min(video.duration, 1));\n  });\n}\n\nexport async function createPosterForVideo(url: string) {\n  const video = await preloadVideo(url);\n\n  return Promise.race([\n    pause(2000) as Promise<undefined>,\n    createPosterFromVideo(video)\n  ]);\n}\n\n\n","// ChatRecording — the voice + round-video-note recording collaborator extracted\n// out of ChatInput. Owns all recording state (recorders, waveform analysers, the\n// voice + video panels, playback) and every method that drives a recording\n// session. ChatInput keeps the send button / input row and delegates the\n// recording branches here.\n//\n// `import type ChatInput` is intentionally TYPE-ONLY to avoid a runtime import\n// cycle (ChatInput constructs this class at runtime).\n\nimport type ChatInput from '../input';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport {POSTING_NOT_ALLOWED_MAP} from '../input';\nimport {ChatType} from '../chatType';\nimport opusDecodeController from '@lib/opusDecodeController';\nimport VoiceWaveformAnalyser from '@helpers/voiceWaveformAnalyser';\nimport LiveWaveformAnalyser from '@helpers/voiceRecorder/liveWaveformAnalyser';\nimport NativeVoiceRecorder, {isNativeVoiceRecorderSupported} from '@helpers/voiceRecorder/nativeVoiceRecorder';\nimport NativeVideoRecorder, {isNativeVideoRecorderSupported} from '@helpers/videoRecorder/nativeVideoRecorder';\nimport VoiceRecordingPanel from '@components/chat/voiceRecording/voiceRecordingPanel';\nimport {createVideoRecordingPanel, VideoRecordingPanelHandle} from '@components/chat/recording/videoRecordingPanel';\nimport {appSettings} from '@stores/appSettings';\nimport {toast, toastNew} from '@components/toast';\nimport {Listener} from '@helpers/listenerSetter';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport {fastRaf} from '@helpers/schedulers';\nimport PopupPeer from '@components/popups/peer';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport PopupElement from '@components/popups';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {ChatRights} from '@appManagers/appChatsManager';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {createPosterFromMedia} from '@helpers/createPoster';\nimport type {MediaSize} from '@helpers/mediaSize';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\n\nconst RECORD_MIN_TIME = 500;\n// Max duration of a round video note. Matches the cap official clients enforce\n// (`60s`); the recorder stops automatically when the progress ring fills.\nconst VIDEO_RECORD_MAX_MS = 60_000;\n\n// Mirrors the module-local CLASS_NAME in input.ts (`'chat-input'`). The\n// outside-click guards installed while recording test the click target against\n// this class to decide whether a click is \"inside\" the chat input.\nconst CLASS_NAME = 'chat-input';\n\nexport default class ChatRecording {\n  private recorder: any;\n  private videoRecorder: NativeVideoRecorder;\n  private waveformAnalyser: VoiceWaveformAnalyser;\n  private liveWaveformAnalyser: LiveWaveformAnalyser;\n  public active = false;\n  // Which recorder is currently active during a recording session. When not\n  // recording, the user's persisted `recordingMediaType` setting dictates the\n  // icon shown on the send button; once a recording starts we capture the\n  // type here so toggle-mid-recording can't desync the UI.\n  private recordingType: 'voice' | 'video' = 'voice';\n  private recordPaused = false;\n  private recordCanceled = false;\n  private recordStartTime = 0;\n  private recordAccumulatedMs = 0;\n  private recordingOverlayListener: Listener;\n  private recordingNavigationItem: NavigationItem;\n  private voiceRecordingPanel: VoiceRecordingPanel;\n  private videoRecordingPanel: VideoRecordingPanelHandle;\n  private playbackAudio: HTMLAudioElement;\n  private playbackObjectUrl: string;\n  private playbackRafId: number;\n  private voiceMenuClickGuard: (e: MouseEvent) => void;\n  // Recorded blob URL used for paused-preview playback inside the round video\n  // panel. Revoked on stop() / send / cancel to release the captured frames.\n  private videoPlaybackObjectUrl: string;\n  // Audio tap for the live waveform during video recording. The MediaRecorder\n  // doesn't expose PCM, so we open a parallel AudioContext on a CLONE of the\n  // stream's audio track (tapping the original track that MediaRecorder is\n  // recording starves both consumers → silent recording + flat waveform).\n  private videoAudioContext: AudioContext;\n  private videoWaveformStream: MediaStream;\n  private videoPlaybackRafId: number;\n  // Set when a video recording hits VIDEO_RECORD_MAX_MS: recording stops at the\n  // cap and switches to the paused-preview state (iOS-style) — the user can\n  // preview + send/discard but cannot record further (resume is blocked).\n  private videoLimitReached = false;\n  // True from the moment a recording is requested until start() resolves —\n  // blocks a duplicate start during the camera warm-up wait.\n  private isStartingRecording = false;\n  // Set when a left-button long-press on the record button opens the mode-switch\n  // menu, so the click that ends the press doesn't also start a recording.\n  private recordModeLongPressed = false;\n\n  private releaseMediaPlayback: () => void;\n\n  constructor(private input: ChatInput) {\n    this.constructRecorder();\n\n    this.voiceRecordingPanel = new VoiceRecordingPanel({\n      onCancel: () => this.onCancelRecordClick(),\n      onPauseToggle: () => this.onPauseToggleClick(),\n      onPlayToggle: () => this.onPlayToggleClick(),\n      onSeek: (progress) => this.onPlaybackSeek(progress)\n    });\n    // The panel is an absolutely-positioned overlay inside the input row.\n    // It sits *under* btnSendContainer in DOM order so the send button stays\n    // on top while everything else (attach, input, emoji) is hidden via CSS.\n    this.input.newMessageWrapper.insertBefore(this.voiceRecordingPanel.element, this.input.btnSendContainer);\n\n    // Round-video-note panel — created here (and not next to the voice panel)\n    // because constructRecorder is what sets this.videoRecorder. The control\n    // bar slots into the input row the same way as voice; the dim overlay +\n    // 360x360 round preview is mounted into the chat container so it covers\n    // bubbles but stays under the input bar (which has a higher z-index).\n    if(this.videoRecorder) {\n      // Just the centered round preview — all recording controls stay in the\n      // chat input (the same voiceRecordingPanel + btn-send the voice flow\n      // uses). Mounted on <body> so it's reliably screen-centered.\n      this.videoRecordingPanel = createVideoRecordingPanel();\n      getOverlayRoot().append(this.videoRecordingPanel.element);\n    }\n\n    this.setupRecordingModeMenu();\n  }\n\n  private constructRecorder() {\n    const config = {\n      // encoderBitRate: 32,\n      // encoderPath: \"../dist/encoderWorker.min.js\",\n      encoderSampleRate: 48000,\n      monitorGain: 0,\n      numberOfChannels: 1,\n      recordingGain: 1,\n      reuseWorker: true\n    };\n\n    if(isNativeVoiceRecorderSupported()) {\n      try {\n        this.recorder = new NativeVoiceRecorder(config);\n      } catch(err) {\n        console.error('NativeVoiceRecorder constructor error:', err);\n      }\n    }\n\n    if(!this.recorder) {\n      const Recorder = (window as any).Recorder;\n      if(Recorder) try {\n        this.recorder = new Recorder(config);\n      } catch(err) {\n        console.error('Recorder constructor error:', err);\n      }\n    }\n\n    if(isNativeVideoRecorderSupported()) {\n      try {\n        this.videoRecorder = new NativeVideoRecorder({\n          width: 400,\n          height: 400,\n          frameRate: 30,\n          videoBitsPerSecond: 1_200_000,\n          audioBitsPerSecond: 64_000\n        });\n      } catch(err) {\n        console.error('NativeVideoRecorder constructor error:', err);\n      }\n    }\n\n    if(!this.recorder) {\n      return;\n    }\n\n    attachClickEvent(this.input.btnCancelRecord, this.onCancelRecordClick, {listenerSetter: this.input.listenerSetter});\n\n    this.recorder.onstop = () => {\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n\n      if(this.waveformAnalyser) {\n        this.waveformAnalyser.finish();\n        this.waveformAnalyser = undefined;\n      }\n      if(this.recorder instanceof NativeVoiceRecorder) {\n        this.recorder.notifySamples = undefined;\n      }\n      this.teardownLiveWaveform();\n      this.stopPlayback();\n      // Any menu-open click guard from the SendMenu is now meaningless —\n      // recording is over.\n      this.setVoiceRecordingMenuGuard(false);\n    };\n\n    this.recorder.ondataavailable = async(typedArray: Uint8Array) => {\n      if(this.releaseMediaPlayback) {\n        this.releaseMediaPlayback();\n        this.releaseMediaPlayback = undefined;\n      }\n\n      if(this.recordingOverlayListener) {\n        this.input.listenerSetter.remove(this.recordingOverlayListener);\n        this.recordingOverlayListener = undefined;\n      }\n\n      if(this.recordingNavigationItem) {\n        appNavigationController.removeItem(this.recordingNavigationItem);\n        this.recordingNavigationItem = undefined;\n      }\n\n      const waveform = this.waveformAnalyser?.finish();\n      this.waveformAnalyser = undefined;\n\n      if(this.recordCanceled) {\n        return;\n      }\n\n      const sendingParams = this.input.chat.getMessageSendingParams();\n\n      const preparedPaymentResult = await this.input.paidMessageInterceptor.prepareStarsForPayment(1);\n      if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n      sendingParams.confirmedPaymentResult = preparedPaymentResult;\n\n      const duration = this.getRecordingElapsedMs() / 1000 | 0;\n      const dataBlob = new Blob([typedArray as BlobPart], {type: 'audio/ogg'});\n      opusDecodeController.decode(typedArray, false).then((result) => {\n        opusDecodeController.setKeepAlive(false);\n\n        // тут objectURL ставится уже с audio/wav\n        this.input.managers.appMessagesManager.sendFile({\n          ...sendingParams,\n          file: dataBlob,\n          isVoiceMessage: true,\n          isMedia: true,\n          duration,\n          waveform,\n          objectURL: result.url,\n          clearDraft: true\n        });\n\n        this.input.onMessageSent(false, true);\n      });\n    };\n\n    if(this.videoRecorder) {\n      this.videoRecorder.onstop = () => {\n        this.setRecording(false);\n        this.videoLimitReached = false;\n        this.input.chatInput.classList.remove('is-locked');\n        this.stopVideoPlayback();\n        this.teardownVideoWaveform();\n        // Reset the voice panel (in place) + fade out the round preview. The\n        // camera is kept alive through the fade (see NativeVideoRecorder), so\n        // the last frame fades instead of cutting to black — release it after.\n        this.voiceRecordingPanel?.setMode('recording');\n        this.voiceRecordingPanel?.clearPeaks();\n        this.videoRecordingPanel?.reset();\n        setTimeout(() => this.videoRecorder?.releaseStream(), 300);\n        this.setVoiceRecordingMenuGuard(false);\n      };\n\n      this.videoRecorder.ondataavailable = async(blob: Blob) => {\n        if(this.releaseMediaPlayback) {\n          this.releaseMediaPlayback();\n          this.releaseMediaPlayback = undefined;\n        }\n\n        if(this.recordingOverlayListener) {\n          this.input.listenerSetter.remove(this.recordingOverlayListener);\n          this.recordingOverlayListener = undefined;\n        }\n\n        if(this.recordingNavigationItem) {\n          appNavigationController.removeItem(this.recordingNavigationItem);\n          this.recordingNavigationItem = undefined;\n        }\n\n        if(this.recordCanceled) {\n          return;\n        }\n\n        // Grab a poster from the still-live camera frame *before* anything\n        // awaits — gives the optimistic (uploading) bubble something to show\n        // instead of a black circle while the upload runs.\n        const thumbPromise = this.captureVideoPoster();\n\n        const sendingParams = this.input.chat.getMessageSendingParams();\n        const preparedPaymentResult = await this.input.paidMessageInterceptor.prepareStarsForPayment(1);\n        if(preparedPaymentResult === PAYMENT_REJECTED) return;\n        sendingParams.confirmedPaymentResult = preparedPaymentResult;\n\n        const duration = this.getRecordingElapsedMs() / 1000 | 0;\n        const thumb = await thumbPromise;\n        // The Blob already carries the recorder's mime type. We hand it to\n        // sendFile with isRoundMessage=true so the documentAttributeVideo flag\n        // gets `round_message=true` (see appMessagesManager.sendFile).\n        const objectURL = URL.createObjectURL(blob);\n        this.input.managers.appMessagesManager.sendFile({\n          ...sendingParams,\n          file: blob,\n          isRoundMessage: true,\n          isMedia: true,\n          duration,\n          // The capture is square at the configured size; appMessagesManager\n          // reads w/h off the file when omitted here, but providing them makes\n          // the optimistic message render correctly.\n          width: 400,\n          height: 400,\n          objectURL,\n          thumb,\n          clearDraft: true\n        });\n\n        this.input.onMessageSent(false, true);\n      };\n    }\n  }\n\n  private onCancelRecordClick = (e?: Event) => {\n    if(e) {\n      cancelEvent(e);\n    }\n\n    this.recordCanceled = true;\n    this.stopPlayback();\n    this.stopVideoPlayback();\n    this.getActiveRecorder()?.stop();\n    if(this.recordingType === 'voice') {\n      opusDecodeController.setKeepAlive(false);\n    }\n  };\n\n  private getRecordingElapsedMs() {\n    if(this.recordPaused) return this.recordAccumulatedMs;\n    return this.recordAccumulatedMs + (Date.now() - this.recordStartTime);\n  }\n\n  private teardownLiveWaveform() {\n    if(this.liveWaveformAnalyser) {\n      this.liveWaveformAnalyser.destroy();\n      this.liveWaveformAnalyser = undefined;\n    }\n  }\n\n  private onPauseToggleClick = () => {\n    if(!this.active) return;\n    if(this.recordingType === 'video') {\n      this.onVideoPauseToggleClick();\n      return;\n    }\n    if(!this.recorder) return;\n\n    if(this.recordPaused) {\n      // Resume recording from paused state. Keep the existing waveform —\n      // new live bars will push in from the right, gradually shifting the\n      // snapshot off to the left rather than starting from scratch.\n      this.stopPlayback();\n      if(typeof this.recorder.resume === 'function') {\n        this.recorder.resume();\n      }\n      this.recordPaused = false;\n      this.recordStartTime = Date.now();\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.setSeekable(false);\n      this.liveWaveformAnalyser?.setPaused(false);\n      this.waveformAnalyser?.setPaused(false);\n      this.startRecordingTimerLoop();\n    } else {\n      // Pause active recording. Replace the rolling live waveform with the\n      // full compressed peaks the analyser has accumulated so playback\n      // progress maps to the whole recording duration, not just the bars\n      // that happened to fit in the live window.\n      if(typeof this.recorder.pause !== 'function') return;\n      this.recordAccumulatedMs += Date.now() - this.recordStartTime;\n      this.recordPaused = true;\n      this.liveWaveformAnalyser?.setPaused(true);\n      this.waveformAnalyser?.setPaused(true);\n      const fullPeaks = this.waveformAnalyser?.getCurrentPeaks();\n      if(fullPeaks && fullPeaks.length) {\n        this.voiceRecordingPanel?.setPeaks(fullPeaks);\n      }\n      this.voiceRecordingPanel?.setMode('paused');\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setSeekable(true);\n      Promise.resolve(this.recorder.pause()).catch(() => {});\n    }\n  };\n\n  private onVideoPauseToggleClick() {\n    if(!this.videoRecorder) return;\n\n    if(this.recordPaused) {\n      // Max length hit — recording is locked at the cap. Keep the resume button\n      // but tell the user why pressing it does nothing.\n      if(this.videoLimitReached) {\n        toastNew({langPackKey: 'Chat.Input.Record.VideoLimitReached'});\n        return;\n      }\n      // Resume from paused state — discard any preview playback, restore the\n      // live camera feed in the preview <video>, and continue recording.\n      this.stopVideoPlayback();\n      this.videoRecorder.resume();\n      this.recordPaused = false;\n      this.recordStartTime = Date.now();\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.setSeekable(false);\n      this.liveWaveformAnalyser?.setPaused(false);\n      this.waveformAnalyser?.setPaused(false);\n      // Restore the live camera feed (reveals on its first frame).\n      this.videoRecordingPanel?.startLivePreview(this.videoRecorder.stream);\n      this.startVideoRecordingTimerLoop();\n    } else {\n      this.recordAccumulatedMs += Date.now() - this.recordStartTime;\n      this.recordPaused = true;\n      this.liveWaveformAnalyser?.setPaused(true);\n      this.waveformAnalyser?.setPaused(true);\n      // Freeze the waveform on the full-recording peaks, like voice.\n      const fullPeaks = this.waveformAnalyser?.getCurrentPeaks();\n      if(fullPeaks && fullPeaks.length) this.voiceRecordingPanel?.setPeaks(fullPeaks);\n      this.voiceRecordingPanel?.setMode('paused');\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setSeekable(true);\n      this.videoRecordingPanel?.setMode('paused');\n      Promise.resolve(this.videoRecorder.pause()).catch(() => {});\n    }\n  }\n\n  private onPlayToggleClick = () => {\n    if(!this.active || !this.recordPaused) return;\n    if(this.recordingType === 'video') {\n      this.onVideoPlayToggleClick();\n      return;\n    }\n    if(this.playbackAudio && !this.playbackAudio.paused) {\n      this.playbackAudio.pause();\n      return;\n    }\n    if(this.playbackAudio && this.playbackAudio.currentTime > 0 && this.playbackAudio.currentTime < this.playbackAudio.duration) {\n      this.playbackAudio.play().catch(() => {});\n      return;\n    }\n    this.startPlaybackFromSnapshot();\n  };\n\n  private onVideoPlayToggleClick() {\n    if(!this.videoRecordingPanel || !this.videoRecorder) return;\n    const video = this.videoRecordingPanel.previewVideo;\n    // If we already have a playable snapshot mounted in the <video>, just\n    // play/pause it directly. The first call swaps in the snapshot blob.\n    if(!video.srcObject && video.src) {\n      if(video.paused) {\n        video.play().catch(() => {});\n      } else {\n        video.pause();\n      }\n      return;\n    }\n    this.startVideoPlaybackFromSnapshot();\n  }\n\n  // The mid-recording snapshot is a non-finalized webm/mp4, so video.duration\n  // is usually Infinity/NaN — fall back to the elapsed recording time we\n  // already track for progress + seeking math.\n  private getVideoPreviewDurationSec() {\n    const video = this.videoRecordingPanel?.previewVideo;\n    if(video && video.duration && isFinite(video.duration)) return video.duration;\n    return this.recordAccumulatedMs / 1000;\n  }\n\n  private startVideoPlaybackFromSnapshot() {\n    const snapshot = this.videoRecorder?.getSnapshot();\n    if(!snapshot || !snapshot.size || !this.videoRecordingPanel) return;\n    this.stopVideoPlayback();\n    this.videoPlaybackObjectUrl = URL.createObjectURL(snapshot);\n    const video = this.videoRecordingPanel.previewVideo;\n    video.srcObject = null;\n    // Unmute for preview (it was muted while mirroring the live camera to\n    // avoid feedback). volume + removeAttribute guard against a sticky\n    // muted-autoplay state.\n    video.muted = false;\n    video.volume = 1;\n    video.removeAttribute('muted');\n    video.loop = false;\n    video.src = this.videoPlaybackObjectUrl;\n    // videoRecordingPanel.setPlaying toggles the preview un-mirror; the\n    // voiceRecordingPanel owns the play/pause icon + waveform playhead + timer.\n    const setPlaying = (p: boolean) => {\n      this.videoRecordingPanel?.setPlaying(p);\n      this.voiceRecordingPanel?.setPlaying(p);\n    };\n    // Per-frame tick — `timeupdate` only fires every ~250ms, which looks jerky;\n    // a rAF loop reading currentTime each frame keeps the timer/ring/playhead\n    // smooth.\n    const tick = () => {\n      if(this.videoPlaybackRafId === undefined) return;\n      const dur = this.getVideoPreviewDurationSec();\n      if(dur) {\n        const progress = Math.max(0, Math.min(1, video.currentTime / dur));\n        this.voiceRecordingPanel?.setPlaybackProgress(progress);\n        this.videoRecordingPanel?.setProgress(progress);\n        this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(video.currentTime * 1000));\n      }\n      this.videoPlaybackRafId = requestAnimationFrame(tick);\n    };\n    const startTick = () => {\n      if(this.videoPlaybackRafId === undefined) this.videoPlaybackRafId = requestAnimationFrame(tick);\n    };\n    const stopTick = () => {\n      if(this.videoPlaybackRafId !== undefined) {\n        cancelAnimationFrame(this.videoPlaybackRafId);\n        this.videoPlaybackRafId = undefined;\n      }\n    };\n    video.onplay = () => {\n      setPlaying(true);\n      startTick();\n    };\n    video.onpause = () => {\n      setPlaying(false);\n      stopTick();\n    };\n    video.onended = () => {\n      setPlaying(false);\n      stopTick();\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(this.recordAccumulatedMs));\n      // Restore the ring to the recorded fraction (its frozen-pause look).\n      this.videoRecordingPanel?.setProgress(this.recordAccumulatedMs / VIDEO_RECORD_MAX_MS);\n    };\n    video.play().catch(() => {\n      // Preview playback can reject on routine autoplay hiccups — just reset,\n      // no need to log (mirrors the voice flow's silent playback catch).\n      this.stopVideoPlayback();\n    });\n  }\n\n  private stopVideoPlayback() {\n    if(this.videoPlaybackRafId !== undefined) {\n      cancelAnimationFrame(this.videoPlaybackRafId);\n      this.videoPlaybackRafId = undefined;\n    }\n    if(!this.videoRecordingPanel) return;\n    const video = this.videoRecordingPanel.previewVideo;\n    try {\n      video.pause();\n    } catch(e) {}\n    video.onplay = null;\n    video.onpause = null;\n    video.onended = null;\n    video.muted = true;\n    if(this.videoPlaybackObjectUrl) {\n      try {\n        URL.revokeObjectURL(this.videoPlaybackObjectUrl);\n      } catch(e) {}\n      this.videoPlaybackObjectUrl = undefined;\n    }\n    if(video.src) {\n      video.removeAttribute('src');\n      try {\n        video.load();\n      } catch(e) {}\n    }\n    this.videoRecordingPanel.setPlaying(false);\n    this.voiceRecordingPanel?.setPlaying(false);\n  }\n\n  // Drives the timer text + progress-ring fill while a video recording is\n  // active. Pauses (returns without re-scheduling) when recording is paused,\n  // resumed by onVideoPauseToggleClick. At VIDEO_RECORD_MAX_MS the recording\n  // doesn't auto-send — it stops at the cap and drops into the paused-preview\n  // state (iOS-style): preview + send/discard, but no further recording.\n  private startVideoRecordingTimerLoop() {\n    const r = () => {\n      if(!this.active || this.recordPaused) return;\n      if(this.recordingType !== 'video') return;\n      const elapsed = this.getRecordingElapsedMs();\n      if(elapsed >= VIDEO_RECORD_MAX_MS) {\n        this.reachVideoLimit();\n        return;\n      }\n      // Timer text lives in the shared voice panel; the ring is the video\n      // overlay's own progress affordance.\n      if(!this.voiceRecordingPanel?.getIsPlaying()) {\n        this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(elapsed));\n      }\n      this.videoRecordingPanel?.setProgress(elapsed / VIDEO_RECORD_MAX_MS);\n      fastRaf(r);\n    };\n    r();\n  }\n\n  // Hit the max duration: lock the recording at the cap and switch to the\n  // paused-preview state. Resume is then blocked (see onVideoPauseToggleClick);\n  // the user can only preview, send or discard.\n  private reachVideoLimit() {\n    if(this.videoLimitReached) return;\n    this.videoLimitReached = true;\n    this.videoRecordingPanel?.setProgress(1);\n    // Enter the paused state (recordPaused is false here, so this pauses).\n    this.onVideoPauseToggleClick();\n    this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(VIDEO_RECORD_MAX_MS));\n  }\n\n  // Install / remove the document-level click guard that closes the SendMenu\n  // on the first click anywhere outside the menu while a voice recording is\n  // active. Without this guard, a left-click would close the menu and also\n  // hit the underlying button (cancel/pause/send) on the way through — every\n  // visible button while recording is its own action target. Capture phase so\n  // we beat the buttons' own bubble-phase click listeners.\n  public setVoiceRecordingMenuGuard(active: boolean) {\n    if(this.voiceMenuClickGuard) {\n      getAppWindow().document.removeEventListener('click', this.voiceMenuClickGuard, {capture: true});\n      this.voiceMenuClickGuard = undefined;\n    }\n    if(!active || !this.active) return;\n\n    this.voiceMenuClickGuard = (e: MouseEvent) => {\n      // Let clicks inside the menu through so menu items still work.\n      if(findUpClassName(e.target as HTMLElement, 'btn-menu')) return;\n      cancelEvent(e);\n      if(contextMenuController.isOpened()) contextMenuController.close();\n    };\n    // On the active window's document so the guard still works in a Document PiP window.\n    getAppWindow().document.addEventListener('click', this.voiceMenuClickGuard, {capture: true});\n  }\n\n  // Stop the recorder so its ondataavailable handler sends the voice file.\n  // Used by the send context menu (Silent / Schedule / SendWhenOnline) while\n  // recording — the menu just sets the relevant flag on the ChatInput and\n  // delegates to this helper to commit the recording. The actual silent /\n  // scheduleDate flags are read back from this.input by getMessageSendingParams.\n  // Stop + send the in-progress recording from the send button's context menu\n  // (Send Without Sound / Schedule / Send When Online). Must stop the ACTIVE\n  // recorder — voice OR video — not always the voice one, or sending a round\n  // video note from the menu does nothing. The silent/schedule flags are already\n  // set by the caller and picked up via getMessageSendingParams on send.\n  public finishRecordingFromMenu() {\n    if(!this.active) return;\n    this.stopPlayback();\n    this.stopVideoPlayback();\n    this.getActiveRecorder()?.stop();\n  }\n\n  // Click-to-seek from the waveform. progress is 0..1 along the bars.\n  // If audio hasn't been decoded yet we kick playback off at that offset.\n  private onPlaybackSeek(progress: number) {\n    if(!this.recordPaused) return;\n    // The shared voice panel's waveform seek is wired to this; for a video\n    // recording it should scrub the round-video preview instead of audio.\n    if(this.recordingType === 'video') {\n      this.onVideoPlaybackSeek(progress);\n      return;\n    }\n    if(this.playbackAudio && this.playbackAudio.duration && !isNaN(this.playbackAudio.duration)) {\n      const target = Math.max(0, Math.min(this.playbackAudio.duration, progress * this.playbackAudio.duration));\n      this.playbackAudio.currentTime = target;\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n      if(this.playbackAudio.paused) this.playbackAudio.play().catch(() => {});\n      return;\n    }\n    // No audio yet — start playback and seek once metadata is available.\n    this.startPlaybackFromSnapshot(progress);\n  }\n\n  private async startPlaybackFromSnapshot(seekProgress?: number) {\n    if(!this.recorder || typeof this.recorder.getSnapshot !== 'function') return;\n    const snapshot: Uint8Array = this.recorder.getSnapshot();\n    if(!snapshot || !snapshot.length) return;\n\n    // Tear down any prior playback before decoding the fresh snapshot.\n    this.stopPlayback();\n\n    try {\n      const {url} = await opusDecodeController.decode(snapshot, false);\n      this.playbackObjectUrl = url;\n    } catch(err) {\n      console.error('[ChatInput] voice playback decode error:', err);\n      return;\n    }\n    if(!this.recordPaused) {\n      // Recording was resumed while we were decoding — drop the result.\n      this.playbackObjectUrl && URL.revokeObjectURL(this.playbackObjectUrl);\n      this.playbackObjectUrl = undefined;\n      return;\n    }\n\n    const audio = this.playbackAudio = new Audio(this.playbackObjectUrl);\n    audio.preload = 'auto';\n\n    const onTick = () => {\n      if(this.playbackAudio !== audio) return;\n      if(!audio.duration || isNaN(audio.duration)) {\n        this.playbackRafId = requestAnimationFrame(onTick);\n        return;\n      }\n      const progress = audio.currentTime / audio.duration;\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n\n      const playedMs = audio.currentTime * 1000;\n      const playedSec = playedMs / 1000;\n      const ms = playedMs % 1000;\n      this.voiceRecordingPanel?.setTimer(toHHMMSS(playedSec) + ',' + ('00' + Math.round(ms / 10)).slice(-2));\n\n      this.playbackRafId = requestAnimationFrame(onTick);\n    };\n\n    audio.addEventListener('play', () => {\n      this.voiceRecordingPanel?.setPlaying(true);\n      cancelAnimationFrame(this.playbackRafId);\n      this.playbackRafId = requestAnimationFrame(onTick);\n    });\n    audio.addEventListener('pause', () => {\n      this.voiceRecordingPanel?.setPlaying(false);\n      cancelAnimationFrame(this.playbackRafId);\n    });\n    audio.addEventListener('ended', () => {\n      this.voiceRecordingPanel?.setPlaying(false);\n      // Clear the progress overlay so all bars return to the active primary\n      // colour after playback — same look as the just-paused state.\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(this.recordAccumulatedMs));\n      cancelAnimationFrame(this.playbackRafId);\n    });\n\n    if(seekProgress != null) {\n      const seek = () => {\n        if(audio.duration && !isNaN(audio.duration)) {\n          audio.currentTime = Math.max(0, Math.min(audio.duration, seekProgress * audio.duration));\n          this.voiceRecordingPanel?.setPlaybackProgress(seekProgress);\n          audio.removeEventListener('loadedmetadata', seek);\n        }\n      };\n      audio.addEventListener('loadedmetadata', seek);\n      seek();\n    }\n\n    audio.play().catch((err) => {\n      console.error('[ChatInput] voice playback play() error:', err);\n      this.stopPlayback();\n    });\n  }\n\n  private formatRecordingTimer(totalMs: number) {\n    const seconds = totalMs / 1000;\n    const ms = totalMs % 1000;\n    return toHHMMSS(seconds) + ',' + ('00' + Math.round(ms / 10)).slice(-2);\n  }\n\n  // The loop pauses (returns without re-scheduling) when recording is paused\n  // so we don't burn ~60 rAFs per second writing the same string to the DOM —\n  // resume() restarts it from onPauseToggleClick.\n  private startRecordingTimerLoop() {\n    const r = () => {\n      if(!this.active || this.recordPaused) return;\n      const elapsed = this.getRecordingElapsedMs();\n      const formatted = this.formatRecordingTimer(elapsed);\n      if(!this.voiceRecordingPanel?.getIsPlaying()) {\n        this.voiceRecordingPanel?.setTimer(formatted);\n      }\n      fastRaf(r);\n    };\n    r();\n  }\n\n  private stopPlayback() {\n    if(this.playbackRafId) {\n      cancelAnimationFrame(this.playbackRafId);\n      this.playbackRafId = undefined;\n    }\n    if(this.playbackAudio) {\n      try {\n        this.playbackAudio.pause();\n      } catch(e) {}\n      this.playbackAudio.src = '';\n      this.playbackAudio = undefined;\n    }\n    if(this.playbackObjectUrl) {\n      try {\n        URL.revokeObjectURL(this.playbackObjectUrl);\n      } catch(e) {}\n      this.playbackObjectUrl = undefined;\n    }\n    this.voiceRecordingPanel?.setPlaying(false);\n    this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n  }\n\n  private setRecording(value: boolean) {\n    if(this.active === value) {\n      return;\n    }\n\n    this.active = value;\n    this.input.inputState.set({isRecording: value});\n    this.input.setShrinking(this.active, ['is-recording']);\n    this.input.updateSendBtn();\n    this.input.onRecording?.(value);\n  }\n\n  // Swallow the click that ends a record-button long-press (it already opened\n  // the mode-switch menu). Returns true when the click should be ignored.\n  public consumeLongPressSuppression(): boolean {\n    if(this.recordModeLongPressed) {\n      this.recordModeLongPressed = false;\n      return true;\n    }\n    return false;\n  }\n\n  public hasAnyRecorder(): boolean {\n    return !!(this.recorder || this.videoRecorder);\n  }\n\n  // Whether the voice recorder specifically is available. Drives the send\n  // button's record/send icon choice (no voice recorder ⇒ never a record icon).\n  public hasVoiceRecorder(): boolean {\n    return !!this.recorder;\n  }\n\n  // Handle the send button's recording branch: stop+send (or cancel if too\n  // short). Called by ChatInput.onBtnSendClick when a recording is active.\n  public handleSendButtonClick() {\n    if(this.getRecordingElapsedMs() < RECORD_MIN_TIME) {\n      this.onCancelRecordClick();\n    } else {\n      this.stopPlayback();\n      this.getActiveRecorder()?.stop();\n    }\n  }\n\n  // Empty input + not recording: start a recording in the active media type.\n  public startActive() {\n    this.startRecordingNow(this.getActiveRecordingMediaType());\n  }\n\n  // Whether voice ↔ video can be switched right now: only in the idle\n  // record-button state (empty field, not recording / editing / forwarding) and\n  // when both recorders exist. Shared by the record-button context menu, the\n  // desktop long-press, and the attach-menu items.\n  public canSwitchRecordingMode(): boolean {\n    return this.input.isInputEmpty() &&\n      !this.active &&\n      !this.input.forwarding &&\n      !this.input.editMsgId &&\n      !this.input.suggestedPost?.hasMedia &&\n      this.input.chat.type !== ChatType.Stories &&\n      !!this.recorder &&\n      !!this.videoRecorder;\n  }\n\n  public setRecordingMediaType(type: 'voice' | 'video') {\n    this.input.chat.setAppSettings('recordingMediaType', type);\n    this.input.updateSendBtn();\n  }\n\n  private setupRecordingModeMenu() {\n    if(!this.recorder || !this.videoRecorder) return; // nothing to switch between\n\n    const contextMenu = createContextMenu({\n      buttons: [{\n        icon: 'microphone',\n        text: 'Chat.Input.Record.Voice',\n        onClick: () => this.setRecordingMediaType('voice'),\n        verify: () => this.canSwitchRecordingMode() && this.getActiveRecordingMediaType() !== 'voice'\n      }, {\n        icon: 'recordround',\n        text: 'Chat.Input.Record.Video',\n        onClick: () => this.setRecordingMediaType('video'),\n        verify: () => this.canSwitchRecordingMode() && this.getActiveRecordingMediaType() !== 'video'\n      }],\n      listenTo: this.input.btnSend,\n      listenerSetter: this.input.listenerSetter\n    });\n\n    // Desktop: hold the left mouse button on the record button (~400ms) to open\n    // the same switch menu — more discoverable than the right-click. Touch\n    // devices already get this via attachContextMenuListener (long-press →\n    // contextmenu) inside createContextMenu, so this is mouse-only.\n    if(!IS_TOUCH_SUPPORTED) {\n      let pressTimer: number;\n      const clearPressTimer = () => {\n        if(pressTimer) {\n          clearTimeout(pressTimer);\n          pressTimer = 0;\n        }\n      };\n\n      this.input.listenerSetter.add(this.input.btnSend)('mousedown', (e: MouseEvent) => {\n        this.recordModeLongPressed = false; // clear any stale flag from an aborted press\n        if(e.button !== 0 || !this.canSwitchRecordingMode()) return; // left button, idle record state\n        clearPressTimer();\n        pressTimer = window.setTimeout(() => {\n          pressTimer = 0;\n          this.recordModeLongPressed = true; // suppress the release click (see onBtnSendClick)\n          contextMenu.open(e);\n        }, 400);\n      });\n      this.input.listenerSetter.add(this.input.btnSend)('mouseup', clearPressTimer);\n      this.input.listenerSetter.add(this.input.btnSend)('mouseleave', clearPressTimer);\n    }\n  }\n\n  // The recording mode shown on the button. Locked to the active session's\n  // type while recording (so resuming / sending uses the matching recorder);\n  // otherwise driven by the persisted user preference.\n  public getActiveRecordingMediaType(): 'voice' | 'video' {\n    if(this.active) return this.recordingType;\n    const persisted = this.input.chat?.appSettings?.recordingMediaType ?? 'voice';\n    // If the persisted type isn't available on this device (e.g. no\n    // MediaRecorder support for video), silently fall back to voice.\n    if(persisted === 'video' && !this.videoRecorder) return 'voice';\n    if(persisted === 'voice' && !this.recorder) return 'video';\n    return persisted;\n  }\n\n  // Returns the recorder driving the current session (or undefined when not\n  // recording). Used by the click handler to stop+send regardless of type.\n  private getActiveRecorder(): {stop: () => void, pause?: () => void | Promise<void>, resume?: () => void, getSnapshot?: () => unknown} | undefined {\n    if(!this.active) return undefined;\n    return this.recordingType === 'video' ? this.videoRecorder : this.recorder;\n  }\n\n  private startRecordingNow(type: 'voice' | 'video') {\n    // `this.active` only flips true once start() resolves; for video that\n    // now includes waiting for the camera's first visible frame, a longer\n    // window in which a second click could kick off a duplicate recording.\n    // Guard it explicitly.\n    if(this.active || this.isStartingRecording) return;\n    if(type === 'video' && !this.videoRecorder) return;\n    this.isStartingRecording = true;\n    const promise = type === 'video' ? this.startVideoRecording() : this.startVoiceRecording();\n    Promise.resolve(promise).catch(() => {}).finally(() => {\n      this.isStartingRecording = false;\n    });\n  }\n\n  private async startVoiceRecording() {\n    const isAnyChat = this.input.chat.peerId.isAnyChat();\n    const flag: ChatRights = 'send_voices';\n    if(isAnyChat && !(await this.input.chat.canSend(flag))) {\n      toastNew({langPackKey: POSTING_NOT_ALLOWED_MAP[flag]});\n      return;\n    }\n\n    if(await this.input.showSlowModeTooltipIfNeeded()) {\n      return;\n    }\n\n    this.input.chatInput.classList.add('is-locked');\n    blurActiveElement();\n\n    let restricted = false;\n    if(!isAnyChat) {\n      const userFull = await this.input.managers.appProfileManager.getProfile(this.input.chat.peerId.toUserId());\n      if(userFull?.pFlags.voice_messages_forbidden) {\n        toastNew({\n          langPackKey: 'Chat.SendVoice.PrivacyError',\n          langPackArguments: [await wrapPeerTitle({peerId: this.input.chat.peerId})]\n        });\n        restricted = true;\n      }\n    }\n\n    if(restricted) {\n      this.input.chatInput.classList.remove('is-locked');\n      return;\n    }\n\n    this.recordingType = 'voice';\n\n    // Record with the microphone selected in Settings → Speakers and Camera\n    // (same appSettings.callDevices source as the call stack + the video note);\n    // empty ⇒ OS default. Read fresh each time, applied to whichever recorder\n    // backs this session: NativeVoiceRecorder via its setter, or the opus-recorder\n    // fallback by setting the `config.mediaTrackConstraints` its start() reads.\n    const microphoneId = appSettings.callDevices?.microphoneId;\n    if(this.recorder.setMicrophoneId) {\n      this.recorder.setMicrophoneId(microphoneId);\n    } else if(this.recorder.config) {\n      this.recorder.config.mediaTrackConstraints = microphoneId ? {deviceId: {exact: microphoneId}} : true;\n    }\n\n    this.recorder.start().then(() => {\n      this.releaseMediaPlayback = appMediaPlaybackController.setSingleMedia();\n      this.recordCanceled = false;\n      this.recordPaused = false;\n      this.recordAccumulatedMs = 0;\n\n      this.setRecording(true);\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.clearPeaks();\n      opusDecodeController.setKeepAlive(true);\n\n      const showDiscardPopup = () => {\n        PopupElement.createPopup(PopupPeer, 'popup-cancel-record', {\n          titleLangKey: 'DiscardVoiceMessageTitle',\n          descriptionLangKey: 'DiscardVoiceMessageDescription',\n          buttons: [{\n            langKey: 'DiscardVoiceMessageAction',\n            callback: () => {\n              simulateClickEvent(this.input.btnCancelRecord);\n            }\n          }, {\n            langKey: 'Continue',\n            isCancel: true\n          }]\n        }).show();\n      };\n\n      this.recordingOverlayListener = this.input.listenerSetter.add(getOverlayRoot())('mousedown', (e) => {\n        if(!findUpClassName(e.target, CLASS_NAME) && !findUpClassName(e.target, 'popup-cancel-record')) {\n          cancelEvent(e);\n          showDiscardPopup();\n        }\n      }, {capture: true, passive: false}) as any;\n\n      appNavigationController.pushItem(this.recordingNavigationItem = {\n        type: 'voice',\n        onPop: () => {\n          setTimeout(() => {\n            showDiscardPopup();\n          }, 0);\n\n          return false;\n        }\n      });\n\n      this.recordStartTime = Date.now();\n\n      if(this.recorder instanceof NativeVoiceRecorder) {\n        // Tap PCM from the capture worklet instead of adding two\n        // ScriptProcessors on the main thread — that path starves encoding on\n        // low-end mobile PWAs and shows up as crackling in the recording.\n        this.waveformAnalyser = new VoiceWaveformAnalyser();\n        this.liveWaveformAnalyser = new LiveWaveformAnalyser();\n        this.recorder.notifySamples = (samples) => {\n          this.waveformAnalyser?.feed(samples);\n          this.liveWaveformAnalyser?.feed(samples);\n        };\n      } else {\n        const sourceNode: MediaStreamAudioSourceNode = this.recorder.sourceNode;\n        this.waveformAnalyser = new VoiceWaveformAnalyser(sourceNode);\n        this.liveWaveformAnalyser = new LiveWaveformAnalyser(sourceNode);\n      }\n      this.liveWaveformAnalyser.onpeak = (peak) => {\n        this.voiceRecordingPanel?.pushPeak(peak);\n      };\n\n      this.startRecordingTimerLoop();\n    }).catch((e: Error) => {\n      switch(e.name as string) {\n        case 'NotAllowedError': {\n          toastNew({langPackKey: 'NoMicrophoneAccess'});\n          break;\n        }\n\n        case 'NotReadableError': {\n          toast(e.message);\n          break;\n        }\n\n        default:\n          console.error('Recorder start error:', e, e.name, e.message);\n          toast(e.message);\n          break;\n      }\n\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n    });\n  }\n\n  private async startVideoRecording() {\n    if(!this.videoRecorder) return;\n    const isAnyChat = this.input.chat.peerId.isAnyChat();\n    // Round video notes go through the same restriction set as voice (the\n    // server-side flag is shared; clients gate on `send_voices`).\n    const flag: ChatRights = 'send_voices';\n    if(isAnyChat && !(await this.input.chat.canSend(flag))) {\n      toastNew({langPackKey: POSTING_NOT_ALLOWED_MAP[flag]});\n      return;\n    }\n\n    if(await this.input.showSlowModeTooltipIfNeeded()) {\n      return;\n    }\n\n    this.input.chatInput.classList.add('is-locked');\n    blurActiveElement();\n\n    this.recordingType = 'video';\n\n    // Record with the camera + microphone the user selected in Settings →\n    // Speakers and Camera (the same appSettings.callDevices source the call\n    // stack reads); empty string ⇒ OS default. Read fresh each time so a change\n    // in settings takes effect on the next recording.\n    this.videoRecorder.setDeviceIds(appSettings.callDevices?.cameraId, appSettings.callDevices?.microphoneId);\n\n    try {\n      await this.videoRecorder.start();\n    } catch(e) {\n      const err = e as Error;\n      switch(err.name) {\n        case 'NotAllowedError':\n          toastNew({langPackKey: 'NoMicrophoneAccess'});\n          break;\n        case 'NotReadableError':\n          toast(err.message);\n          break;\n        default:\n          console.error('VideoRecorder start error:', err);\n          // err.message is empty for some errors (OverconstrainedError /\n          // NotFoundError) — fall back to the name so the toast isn't blank.\n          toast(err.message || err.name);\n          break;\n      }\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n      return;\n    }\n\n    this.releaseMediaPlayback = appMediaPlaybackController.setSingleMedia();\n    this.recordCanceled = false;\n    this.recordPaused = false;\n    this.recordAccumulatedMs = 0;\n    this.videoLimitReached = false;\n\n    // The recording bar is the regular voice panel, IN PLACE in the chat input.\n    // We just drive it for video; the only video-specific UI is the centered\n    // round preview (videoRecordingPanel).\n    this.setRecording(true);\n    this.voiceRecordingPanel?.setMode('recording');\n    this.voiceRecordingPanel?.clearPeaks();\n    this.videoRecordingPanel?.setProgress(0);\n\n    // Pipe the live camera into the 360x360 preview and reveal the circle only\n    // once the first frame is actually painted — revealing immediately would\n    // fade in a black circle while the camera spins up.\n    this.videoRecordingPanel?.startLivePreview(this.videoRecorder.stream);\n\n    // Live waveform: tap the captured audio track through a throwaway\n    // AudioContext (MediaRecorder gives us no PCM). Mirror the voice flow —\n    // feed normalized peaks into the (shared) voice panel's waveform.\n    this.setupVideoWaveform();\n\n    const showDiscardPopup = () => {\n      PopupElement.createPopup(PopupPeer, 'popup-cancel-record', {\n        titleLangKey: 'DiscardVoiceMessageTitle',\n        descriptionLangKey: 'DiscardVoiceMessageDescription',\n        buttons: [{\n          langKey: 'DiscardVoiceMessageAction',\n          callback: () => {\n            simulateClickEvent(this.input.btnCancelRecord);\n          }\n        }, {\n          langKey: 'Continue',\n          isCancel: true\n        }]\n      }).show();\n    };\n\n    this.recordingOverlayListener = this.input.listenerSetter.add(getOverlayRoot())('mousedown', (e) => {\n      // Same dismiss-on-outside-click guard as voice — clicks inside the chat\n      // input or the discard popup are allowed; everything else opens the\n      // discard confirmation.\n      if(\n        !findUpClassName(e.target, CLASS_NAME) &&\n        !findUpClassName(e.target, 'popup-cancel-record') &&\n        !findUpClassName(e.target, 'video-recording-stage') // clicking the preview circle isn't \"outside\"\n      ) {\n        cancelEvent(e);\n        showDiscardPopup();\n      }\n    }, {capture: true, passive: false}) as any;\n\n    appNavigationController.pushItem(this.recordingNavigationItem = {\n      type: 'voice',\n      onPop: () => {\n        setTimeout(() => {\n          showDiscardPopup();\n        }, 0);\n\n        return false;\n      }\n    });\n\n    this.recordStartTime = Date.now();\n    this.startVideoRecordingTimerLoop();\n  }\n\n  // Opens an AudioContext on the recording stream's audio track and routes it\n  // through the same analysers the voice flow uses, feeding the (shared) voice\n  // panel waveform. Torn down in teardownVideoWaveform (on stop). Best-effort —\n  // a waveform failure must not break the recording.\n  private setupVideoWaveform() {\n    if(!this.videoRecorder?.stream || !this.voiceRecordingPanel) return;\n    const audioTracks = this.videoRecorder.stream.getAudioTracks();\n    if(!audioTracks.length) return;\n    try {\n      this.videoAudioContext = new AudioContext();\n      // Created after `await getUserMedia`, i.e. outside the original click\n      // gesture, so it may start suspended — without resuming, the\n      // ScriptProcessor never fires and the waveform stays flat.\n      if(this.videoAudioContext.state === 'suspended') {\n        this.videoAudioContext.resume().catch(() => {});\n      }\n      // Tap a CLONE of the audio track, not the one MediaRecorder is recording.\n      // Sharing the single track between MediaRecorder and a Web Audio source\n      // makes one of them read silence (flat waveform + soundless recording);\n      // an independent clone feeds both with real audio.\n      this.videoWaveformStream = new MediaStream([audioTracks[0].clone()]);\n      const source = this.videoAudioContext.createMediaStreamSource(this.videoWaveformStream);\n      // Full-recording peaks for the frozen pause view, live peaks for the\n      // scrolling bars — same pair the voice recorder wires up.\n      this.waveformAnalyser = new VoiceWaveformAnalyser(source);\n      this.liveWaveformAnalyser = new LiveWaveformAnalyser(source);\n      this.liveWaveformAnalyser.onpeak = (peak) => {\n        if(this.recordingType === 'video') this.voiceRecordingPanel?.pushPeak(peak);\n      };\n    } catch(e) {\n      console.error('[ChatInput] video waveform setup error:', e);\n    }\n  }\n\n  private teardownVideoWaveform() {\n    this.teardownLiveWaveform();\n    if(this.waveformAnalyser) {\n      this.waveformAnalyser.finish();\n      this.waveformAnalyser = undefined;\n    }\n    if(this.videoWaveformStream) {\n      this.videoWaveformStream.getTracks().forEach((t) => t.stop());\n      this.videoWaveformStream = undefined;\n    }\n    if(this.videoAudioContext) {\n      const ctx = this.videoAudioContext;\n      this.videoAudioContext = undefined;\n      if(ctx.state !== 'closed') ctx.close().catch(() => {});\n    }\n  }\n\n  // Snapshot the current round-preview frame as a JPEG poster for the optimistic\n  // message. Must be called while the camera is still live (we keep it alive\n  // through the stop fade-out). Returns the {blob, url, size} shape sendFile's\n  // `thumb` expects, or undefined on failure (sending still works without it).\n  private async captureVideoPoster(): Promise<{blob: Blob, url: string, size: MediaSize} | undefined> {\n    const v = this.videoRecordingPanel?.previewVideo;\n    if(!v || !v.videoWidth || !v.videoHeight) return undefined;\n    try {\n      const poster = await createPosterFromMedia(v);\n      if(!poster?.blob) return undefined;\n      return {blob: poster.blob, url: URL.createObjectURL(poster.blob), size: poster.size};\n    } catch(e) {\n      return undefined;\n    }\n  }\n\n  private onVideoPlaybackSeek(progress: number) {\n    const video = this.videoRecordingPanel?.previewVideo;\n    if(!video) return;\n    const seekTo = () => {\n      const dur = this.getVideoPreviewDurationSec();\n      if(!dur) return;\n      video.currentTime = Math.max(0, Math.min(dur, progress * dur));\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n      this.videoRecordingPanel?.setProgress(progress);\n    };\n    // No preview mounted yet (still showing the live camera) — start playback\n    // and seek once it's loaded.\n    if(video.srcObject || !video.src) {\n      this.startVideoPlaybackFromSnapshot();\n      const onMeta = () => {\n        seekTo();\n        video.removeEventListener('loadedmetadata', onMeta);\n      };\n      video.addEventListener('loadedmetadata', onMeta);\n      return;\n    }\n    seekTo();\n    if(video.paused) video.play().catch(() => {});\n  }\n\n  public destroy() {\n    // The round-preview element lives on <body>, outside the input subtree, so\n    // tear it down explicitly. Also release the camera in case a recording (or\n    // its warm-up) is still in flight.\n    this.teardownVideoWaveform();\n    // stopVideoPlayback before the panel goes away: cancels the playback rAF and\n    // revokes videoPlaybackObjectUrl (it reads videoRecordingPanel.previewVideo).\n    this.stopVideoPlayback();\n    this.videoRecorder?.releaseStream();\n    // A recording in flight pushed a navigation item with an onPop discard popup;\n    // drop it so it doesn't linger / fire after the chat is gone.\n    if(this.recordingNavigationItem) {\n      appNavigationController.removeItem(this.recordingNavigationItem);\n      this.recordingNavigationItem = undefined;\n    }\n    this.videoRecordingPanel?.destroy();\n    this.videoRecordingPanel = undefined;\n  }\n}\n","import appDownloadManager from '@lib/appDownloadManager';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport {getEmojiToneIndex} from '@vendor/emoji';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {getMiddleware} from '@helpers/middleware';\nimport {saveLottiePreviewFromPlayer} from '@helpers/saveLottiePreview';\n\nexport default function preloadAnimatedEmojiSticker(emoji: string, width?: number, height?: number) {\n  return rootScope.managers.appStickersManager.preloadAnimatedEmojiSticker(emoji).then(({doc}) => {\n    if(!doc) {\n      return;\n    }\n\n    return appDownloadManager.downloadMedia({media: doc})\n    .then(async(blob) => {\n      const mediaSize = mediaSizes.active.emojiSticker;\n      const toneIndex = getEmojiToneIndex(emoji);\n      const middlewareHelper = getMiddleware();\n      const animation = await lottieLoader.loadAnimationWorker({\n        container: undefined,\n        animationData: blob,\n        width: width ?? mediaSize.width,\n        height: height ?? mediaSize.height,\n        name: 'doc' + doc.id,\n        autoplay: false,\n        loop: false,\n        toneIndex,\n        group: 'none',\n        middleware: middlewareHelper.get()\n      });\n\n      animation.addEventListener('firstFrame', () => {\n        saveLottiePreviewFromPlayer(doc, animation, toneIndex).finally(() => {\n          middlewareHelper.destroy();\n        });\n      }, {once: true});\n    });\n  });\n}\n","import indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport LazyLoadQueueIntersector, {LazyLoadElement} from '@components/lazyLoadQueueIntersector';\nimport VisibilityIntersector, {OnVisibilityChange} from '@components/visibilityIntersector';\n\nexport default class LazyLoadQueueRepeat extends LazyLoadQueueIntersector {\n  private elementsMap: Map<HTMLElement, LazyLoadElement> = new Map();\n\n  constructor(\n    parallelLimit?: number,\n    protected onVisibilityChange?: OnVisibilityChange,\n    options?: IntersectionObserverInit\n  ) {\n    super(parallelLimit);\n\n    this.intersector = new VisibilityIntersector((item) => {\n      const {target, visible} = item;\n\n      const queueItem = this.elementsMap.get(target);\n      queueItem.visible = visible;\n\n      if(visible) {\n        queueItem.wasSeen = true;\n        if(!this.queue.includes(queueItem)) {\n          this.queue.push(queueItem);\n        }\n      } else {\n        indexOfAndSplice(this.queue, queueItem);\n      }\n\n      this.onVisibilityChange?.(item);\n      this.setProcessQueueTimeout();\n    }, options);\n  }\n\n  public clear() {\n    super.clear();\n    this.elementsMap.clear();\n  }\n\n  /* public async processItem(item: LazyLoadElement) {\n    //await super.processItem(item);\n    await LazyLoadQueueBase.prototype.processItem.call(this, item);\n\n    if(this.lazyLoadMedia.length) {\n      this.processQueue();\n    }\n  } */\n\n  public observe(el: LazyLoadElement) {\n    this.elementsMap.set(el.div, el);\n    super.observe(el);\n  }\n\n  public unobserve(el: LazyLoadElement) {\n    this.elementsMap.delete(el.div);\n    super.unobserve(el);\n  }\n}\n","import mediaSizes from '@helpers/mediaSizes';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport LazyLoadQueueRepeat from '@components/lazyLoadQueueRepeat';\nimport wrapSticker from '@components/wrappers/sticker';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\n\nexport default class SuperStickerRenderer {\n  public lazyLoadQueue: LazyLoadQueueRepeat;\n  private animated: Set<HTMLElement> = new Set();\n  private regularLazyLoadQueue: LazyLoadQueue;\n  private group: AnimationItemGroup;\n  private managers: AppManagers;\n  private intersectionObserverInit: IntersectionObserverInit;\n  private visibleRenderOptions: Partial<Parameters<typeof wrapSticker>[0]>;\n  private withLock: boolean\n  private playOnHover: boolean\n\n  constructor(options: {\n    regularLazyLoadQueue: LazyLoadQueue;\n    group: AnimationItemGroup;\n    managers: AppManagers;\n    intersectionObserverInit?: SuperStickerRenderer['intersectionObserverInit'];\n    visibleRenderOptions?: SuperStickerRenderer['visibleRenderOptions'];\n    withLock?: boolean\n    playOnHover?: boolean\n  }) {\n    options.withLock ??= true;\n    safeAssign(this, options);\n\n    this.lazyLoadQueue = new LazyLoadQueueRepeat(undefined, ({target, visible}) => {\n      if(!visible) {\n        this.processInvisible(target);\n      }\n    }, this.intersectionObserverInit);\n  }\n\n  public clear() {\n    this.lazyLoadQueue.clear();\n    this.animated.forEach((element) => {\n      element.middlewareHelper?.destroy();\n    });\n    this.animated.clear();\n  }\n\n  public destroy() {\n    this.clear();\n  }\n\n  public renderSticker(\n    doc: MyDocument,\n    element?: HTMLElement,\n    loadPromises?: Promise<any>[],\n    middleware?: Middleware\n  ) {\n    if(!element) {\n      element = document.createElement('div');\n      element.classList.add('grid-item', 'super-sticker');\n      element.dataset.docId = '' + doc.id;\n\n      if(doc.animated) {\n        this.observeAnimated(element);\n      }\n    }\n\n    element.middlewareHelper ??= middleware ? middleware.create() : getMiddleware();\n\n    // * This will wrap only a thumb\n    /* !doc.animated &&  */ wrapSticker({\n      doc,\n      div: element,\n      lazyLoadQueue: this.regularLazyLoadQueue,\n      group: this.group,\n      onlyThumb: doc.animated,\n      loadPromises,\n      middleware: element.middlewareHelper.get(),\n      ...(doc.animated ? {} : this.visibleRenderOptions || {})\n    });\n\n    if(this.playOnHover) {\n      element.addEventListener('mouseenter', () => {\n        const renderer = this.rendererByElement.get(element);\n        if(renderer && 'playOrRestart' in renderer) {\n          renderer.playOrRestart()\n        }\n      })\n    }\n\n    return element;\n  }\n\n  public observeAnimated(element: HTMLElement) {\n    this.animated.add(element);\n    this.lazyLoadQueue.observe({\n      div: element,\n      load: this.processVisible\n    });\n  }\n\n  public unobserveAnimated(element: HTMLElement) {\n    element.middlewareHelper?.destroy();\n    this.animated.delete(element);\n    this.lazyLoadQueue.delete({div: element});\n  }\n\n  public deleteSticker(element: HTMLElement) {\n    return this.unobserveAnimated(element);\n  }\n\n  private checkAnimationContainer = (element: HTMLElement, visible: boolean) => {\n    // console.error('checkAnimationContainer', div, visible);\n    const players = animationIntersector.getAnimations(element);\n    players.forEach((player) => {\n      if(!visible) {\n        animationIntersector.removeAnimation(player);\n      } else {\n        animationIntersector.checkAnimation(player, false);\n      }\n    });\n  };\n\n  private rendererByElement = new WeakMap<HTMLElement, Awaited<Awaited<ReturnType<typeof wrapSticker>>['render']>>();\n  private processVisible = async(element: HTMLElement) => {\n    const docId = element.dataset.docId;\n    const doc = await this.managers.appDocsManager.getDoc(docId);\n\n    const size = mediaSizes.active.esgSticker.width;\n\n    element.middlewareHelper ??= getMiddleware();\n    element.middlewareHelper.clean();\n\n    // console.log('processVisibleDiv:', element);\n    const promise = wrapSticker({\n      doc,\n      div: element,\n      width: size,\n      height: size,\n      lazyLoadQueue: null,\n      group: this.group,\n      onlyThumb: false,\n      play: true,\n      loop: true,\n      withLock: this.withLock,\n      middleware: element.middlewareHelper.get(),\n      ...(this.visibleRenderOptions || {})\n    }).then(({render}) => render);\n\n    promise.then(() => {\n      // clearTimeout(timeout);\n      this.checkAnimationContainer(element, this.lazyLoadQueue.intersector.isVisible(element));\n    }, noop);\n\n    if(this.playOnHover) {\n      promise.then(renderer => {\n        this.rendererByElement.set(element, renderer);\n      });\n    }\n\n    /* let timeout = window.setTimeout(() => {\n      console.error('processVisibleDiv timeout', div, doc);\n    }, 1e3); */\n    return promise;\n  };\n\n  public processInvisible = async(element: HTMLElement) => {\n    const docId = element.dataset.docId;\n    const doc = await this.managers.appDocsManager.getDoc(docId);\n\n    // the await above is a real worker round-trip - the cell may be back on\n    // screen; demolishing it now would yank a live canvas (visible blink).\n    // Bail and leave the old player alive - the visible flip that brought the\n    // cell back already queued processVisible, which cleans and re-wraps. The\n    // dropdown 'closed' sweep clears visibility synchronously before these\n    // continuations run, so it still demolishes hidden cells.\n    if(this.lazyLoadQueue.intersector.isVisible(element)) {\n      return;\n    }\n\n    // console.log('STICKER INvisible:', /* div,  */docId);\n    this.checkAnimationContainer(element, false);\n\n    element.middlewareHelper?.clean();\n    // no replaceChildren - the thumb re-wrap adopts the dead canvas (pixels\n    // retained) as its bottom layer and retires it only under the decoded\n    // preview img (replacePreviousMedia), so a mis-timed demolition can never\n    // produce an empty/silhouette frame\n    this.renderSticker(doc, element as HTMLDivElement);\n  };\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {simulateClickEvent, attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport safePlay from '@helpers/dom/safePlay';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport {doubleRaf} from '@helpers/schedulers';\nimport pause from '@helpers/schedulers/pause';\nimport windowSize from '@helpers/windowSize';\nimport {DocumentAttribute} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport getStickerEffectThumb from '@appManagers/utils/stickers/getStickerEffectThumb';\nimport CustomEmojiElement from '@lib/customEmoji/element';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport RLottiePlayer from '@lib/rlottie/rlottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport {EMOJI_TEXT_COLOR} from '@components/emoticonsDropdown';\nimport SetTransition from '@components/singleTransition';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {STICKER_EFFECT_MULTIPLIER} from '@components/wrappers/sticker';\nimport wrapVideo from '@components/wrappers/video';\n\nlet hasViewer = false;\nexport default function attachStickerViewerListeners({listenTo, listenerSetter, selector, findTarget: originalFindTarget, getTextColor, additionalClass}: {\n  additionalClass?: string,\n  listenerSetter: ListenerSetter,\n  listenTo: HTMLElement,\n  selector?: string,\n  findTarget?: (e: MouseEvent) => HTMLElement,\n  getTextColor?: () => string\n}) {\n  if(IS_TOUCH_SUPPORTED) {\n    return;\n  }\n\n  const findTarget = (e: MouseEvent, checkForParent?: boolean) => {\n    let el: HTMLElement;\n    if(originalFindTarget) el = originalFindTarget(e);\n    else {\n      const s = selector || '.media-sticker-wrapper, .media-gif-wrapper';\n      el = (e.target as HTMLElement).closest(s) as HTMLElement;\n    }\n\n    return el && (!checkForParent || findUpAsChild(el, listenTo)) ? el : undefined;\n  };\n\n  const managers = rootScope.managers;\n\n  listenerSetter.add(listenTo)('mousedown', (e) => {\n    if(hasViewer || e.buttons > 1 || e.button !== 0) return;\n    let mediaContainer = findTarget(e);\n    if(!mediaContainer) {\n      return;\n    }\n\n    // const img: HTMLImageElement = mediaContainer.querySelector('img.media-sticker');\n\n    const docId = mediaContainer.dataset.docId;\n    if(!docId) {\n      return;\n    }\n\n    // The whole hold-drag-release gesture is tracked on document-level mousemove/mouseup + a post-\n    // release click-swallow, and timed by setTimeout/setInterval — all of which must use whichever\n    // window the app currently lives in (the tab, or the Document PiP window). Bound to the MAIN\n    // window, the viewer opens on hold but its mouseup/mousemove fire on the PiP document and never\n    // arrive, so it sticks open and can't switch stickers.\n    const activeWindow = getAppWindow();\n    const activeDocument = activeWindow.document;\n\n    const className = 'sticker-viewer';\n    const group: AnimationItemGroup = 'STICKER-VIEWER';\n    const openDuration = 200;\n    const switchDuration = 200;\n    const previousGroup = animationIntersector.getOnlyOnePlayableGroup();\n    const _middleware = getMiddleware();\n    let container: HTMLElement,\n      previousTransformer: HTMLElement,\n      isMouseUp = false;\n\n    const doThatSticker = async({mediaContainer, doc, middleware, lockGroups, isSwitching}: {\n      mediaContainer: HTMLElement,\n      doc: MyDocument,\n      middleware: Middleware,\n      lockGroups?: boolean,\n      isSwitching?: boolean\n    }) => {\n      const isGif = doc.type === 'gif';\n      const effectThumb = isGif ? undefined : getStickerEffectThumb(doc);\n      const mediaRect: DOMRect = mediaContainer.getBoundingClientRect();\n      const s = makeMediaSize(doc.w, doc.h);\n      const size = effectThumb ? 280 : (isGif ? Math.min(480, windowSize.height - 200) : 360);\n      const boxSize = makeMediaSize(size, size);\n      const fitted = mediaRect.width === mediaRect.height ? boxSize : s.aspectFitted(boxSize);\n\n      const bubble = findUpClassName(mediaContainer, 'bubble');\n      const isOut = bubble ? bubble.classList.contains('is-out') : true;\n\n      const transformer = document.createElement('div');\n      transformer.classList.add(className + '-transformer');\n      transformer.middlewareHelper = middleware.create();\n      middleware = transformer.middlewareHelper.get();\n\n      const stickerContainer = document.createElement('div');\n      stickerContainer.classList.add(className + '-sticker');\n      /* transformer.style.width =  */stickerContainer.style.width = fitted.width + 'px';\n      /* transformer.style.height =  */stickerContainer.style.height = fitted.height + 'px';\n\n      const stickerEmoji = document.createElement('div');\n      stickerEmoji.classList.add(className + '-emoji');\n      stickerEmoji.append(wrapEmojiText(doc.stickerEmojiRaw));\n\n      if(effectThumb) {\n        const margin = (size * STICKER_EFFECT_MULTIPLIER - size) / 3 * (isOut ? 1 : -1);\n        transformer.classList.add('has-effect');\n        // const property = `--margin-${isOut ? 'right' : 'left'}`;\n        // stickerContainer.style.setProperty(property, `${margin * 2}px`);\n        transformer.style.setProperty('--translateX', `${margin}px`);\n        stickerEmoji.style.setProperty('--translateX', `${-margin}px`);\n      }\n\n      const overflowElement = findUpClassName(mediaContainer, 'scrollable');\n      const visibleRect = getVisibleRect(mediaContainer, overflowElement, true, mediaRect);\n      if(visibleRect.overflow.vertical || visibleRect.overflow.horizontal) {\n        stickerContainer.classList.add('is-overflow');\n      }\n\n      // if(img) {\n      //   const ratio = img.naturalWidth / img.naturalHeight;\n      //   if((mediaRect.width / mediaRect.height).toFixed(1) !== ratio.toFixed(1)) {\n\n      //     mediaRect = mediaRect.toJSON();\n      //   }\n      // }\n\n      const rect = mediaContainer.getBoundingClientRect();\n      const scaleX = rect.width / fitted.width;\n      const scaleY = rect.height / fitted.height;\n      const transformX = rect.left - (windowSize.width - rect.width) / 2;\n      const transformY = rect.top - (windowSize.height - rect.height) / 2;\n      transformer.style.transform = `translate(${transformX}px, ${transformY}px) scale(${scaleX}, ${scaleY})`;\n      if(isSwitching) transformer.classList.add('is-switching', 'forwards');\n      transformer.append(stickerContainer, stickerEmoji);\n      container.append(transformer);\n\n      const attribute = doc.attributes.find((attribute) => attribute._ === 'documentAttributeCustomEmoji') as DocumentAttribute.documentAttributeCustomEmoji;\n\n      const o = isGif ? await wrapVideo({\n        doc,\n        container: stickerContainer,\n        group,\n        boxWidth: fitted.width,\n        boxHeight: fitted.height,\n        canAutoplay: true,\n        middleware,\n        noInfo: true\n        // noPreview: true\n      }).then(async(res) => (await res.loadPromise, res.video)) : await wrapSticker({\n        doc,\n        div: stickerContainer,\n        group,\n        width: fitted.width,\n        height: fitted.height,\n        play: false,\n        loop: true,\n        middleware,\n        managers,\n        needFadeIn: false,\n        isOut,\n        withThumb: false,\n        relativeEffect: true,\n        loopEffect: true,\n        textColor: attribute && attribute.pFlags.text_color ? getTextColor?.() || EMOJI_TEXT_COLOR : undefined\n      }).then(({render}) => render);\n      if(!middleware()) return;\n\n      if(!container.parentElement) {\n        getOverlayRoot().append(container);\n      }\n\n      const player = Array.isArray(o) ? o[0] : o;\n\n      const firstFramePromise = player instanceof RLottiePlayer ?\n        new Promise<void>((resolve) => player.addEventListener('firstFrame', resolve, {once: true})) :\n        Promise.resolve();\n      await Promise.all([firstFramePromise, doubleRaf()]);\n      await pause(0); // ! need it because firstFrame will be called just from the loop\n      if(!middleware()) return;\n\n      if(lockGroups) {\n        animationIntersector.setOnlyOnePlayableGroup(group);\n        animationIntersector.checkAnimations2(true);\n      }\n\n      if(player instanceof RLottiePlayer) {\n        const prevPlayer = mediaContainer instanceof CustomEmojiElement ?\n          mediaContainer.player as RLottiePlayer :\n          lottieLoader.getAnimation(mediaContainer);\n        if(prevPlayer) {\n          player.curFrame = prevPlayer.curFrame;\n          player.play();\n          await new Promise<void>((resolve) => {\n            let i = 0;\n            const c = () => {\n              if(++i === 2) {\n                resolve();\n                player.removeEventListener('enterFrame', c);\n              }\n            };\n\n            player.addEventListener('enterFrame', c);\n          });\n          if(!middleware()) return;\n          player.pause();\n        }\n      } else if(player instanceof HTMLVideoElement) {\n        const prevPlayer = mediaContainer.querySelector<HTMLVideoElement>('video');\n        if(prevPlayer) {\n          player.currentTime = prevPlayer.currentTime;\n        }\n      }\n\n      return {\n        ready: () => {\n          if(player instanceof RLottiePlayer || player instanceof HTMLVideoElement) {\n            safePlay(player);\n          }\n\n          if(effectThumb) {\n            simulateClickEvent(stickerContainer);\n          }\n        },\n        transformer\n      };\n    };\n\n    const timeout = activeWindow.setTimeout(async() => {\n      activeDocument.removeEventListener('mousemove', onMousePreMove);\n\n      container = document.createElement('div');\n      container.classList.add(className, additionalClass);\n      hasViewer = true;\n\n      const middleware = _middleware.get();\n      const doc = await managers.appDocsManager.getDoc(docId);\n      if(!middleware()) return;\n\n      let result: Awaited<ReturnType<typeof doThatSticker>>;\n      try {\n        result = await doThatSticker({\n          doc,\n          mediaContainer,\n          middleware,\n          lockGroups: true\n        });\n        if(!result) return;\n      } catch(err) {\n        return;\n      }\n\n      // * can't use middleware here\n      if(isMouseUp) {\n        return;\n      }\n\n      const {ready, transformer} = result;\n\n      previousTransformer = transformer;\n\n      SetTransition({\n        element: container,\n        className: 'is-visible',\n        forwards: true,\n        duration: openDuration,\n        onTransitionEnd: () => {\n          if(!middleware()) return;\n          ready();\n        }\n      });\n\n      activeDocument.addEventListener('mousemove', onMouseMove);\n    }, 125);\n\n    const onMouseMove = async(e: MouseEvent) => {\n      const newMediaContainer = findTarget(e, true);\n      if(!newMediaContainer || mediaContainer === newMediaContainer) {\n        return;\n      }\n\n      const docId = newMediaContainer.dataset.docId;\n      if(!docId) {\n        return;\n      }\n\n      mediaContainer = newMediaContainer;\n      _middleware.clean();\n      const middleware = _middleware.get();\n\n      const doc = await managers.appDocsManager.getDoc(docId);\n      if(!middleware()) return;\n\n      let r: Awaited<ReturnType<typeof doThatSticker>>;\n      try {\n        r = await doThatSticker({\n          doc,\n          mediaContainer,\n          middleware,\n          isSwitching: true\n        });\n        if(!r) return;\n      } catch(err) {\n        console.error('sticker viewer error', err);\n        return;\n      }\n\n      const {ready, transformer} = r;\n\n      const _previousTransformer = previousTransformer;\n      SetTransition({\n        element: _previousTransformer,\n        className: 'is-switching',\n        forwards: true,\n        duration: switchDuration,\n        onTransitionEnd: () => {\n          _previousTransformer.remove();\n          _previousTransformer.middlewareHelper.destroy();\n        }\n      });\n\n      previousTransformer = transformer;\n\n      SetTransition({\n        element: transformer,\n        className: 'is-switching',\n        forwards: false,\n        duration: switchDuration,\n        onTransitionEnd: () => {\n          if(!middleware()) return;\n          ready();\n        }\n      });\n    };\n\n    const onMousePreMove = (e: MouseEvent) => {\n      if(!findUpAsChild(e.target as HTMLElement, mediaContainer)) {\n        onMouseUp();\n      }\n    };\n\n    const onMouseUp = () => {\n      isMouseUp = true;\n      activeWindow.clearTimeout(timeout);\n      activeWindow.clearInterval(unmountInterval);\n      // _middleware.clean();\n\n      if(container) {\n        SetTransition({\n          element: container,\n          className: 'is-visible',\n          forwards: false,\n          duration: openDuration,\n          onTransitionEnd: () => {\n            container.remove();\n            animationIntersector.setOnlyOnePlayableGroup(previousGroup);\n            animationIntersector.checkAnimations2(false);\n            _middleware.destroy();\n            hasViewer = false;\n          }\n        });\n\n        attachClickEvent(activeDocument.body, cancelEvent, {capture: true, once: true});\n      }\n\n      activeDocument.removeEventListener('mousemove', onMousePreMove);\n      activeDocument.removeEventListener('mousemove', onMouseMove);\n      activeDocument.removeEventListener('mouseup', onMouseUp, {capture: true});\n    };\n\n    activeDocument.addEventListener('mousemove', onMousePreMove);\n    activeDocument.addEventListener('mouseup', onMouseUp, {once: true, capture: true});\n    const unmountInterval = activeWindow.setInterval(() => {\n      if(!isInDOM(mediaContainer)) {\n        onMouseUp();\n      }\n    }, 100);\n  });\n}\n","import fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\ntype ArrowKey = 'ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight';\nconst HANDLE_EVENT = 'keydown';\nconst ACTIVE_CLASS_NAME = 'active';\n\nconst AXIS_Y_KEYS: ArrowKey[] = ['ArrowUp', 'ArrowDown'];\nconst AXIS_X_KEYS: ArrowKey[] = ['ArrowLeft', 'ArrowRight'];\n\nconst PROPERTY_NEXT = 'nextElementSibling';\nconst PROPERTY_PREV = 'previousElementSibling';\nconst PROPERTY_FIRST = 'firstElementChild';\nconst PROPERTY_LAST = 'lastElementChild';\n\nexport type ListNavigationOptions = {\n  list: HTMLElement,\n  type: 'xy' | 'x' | 'y',\n  onSelect: (target: Element) => void | boolean | Promise<boolean>,\n  once?: boolean,\n  waitForKey?: string[],\n  activeClassName?: string,\n  cancelMouseDown?: boolean,\n  target?: Element\n};\n\nexport default function attachListNavigation({\n  list,\n  type,\n  onSelect,\n  once,\n  waitForKey,\n  activeClassName = ACTIVE_CLASS_NAME,\n  cancelMouseDown,\n  target\n}: ListNavigationOptions) {\n  let waitForKeySet = waitForKey?.length ? new Set(waitForKey) : undefined;\n  const keyNames = new Set(type === 'xy' ? AXIS_Y_KEYS.concat(AXIS_X_KEYS) : (type === 'x' ? AXIS_X_KEYS : AXIS_Y_KEYS));\n\n  const getCurrentTarget = () => {\n    return target || list.querySelector('.' + activeClassName) || list[PROPERTY_FIRST];\n  };\n\n  const setCurrentTarget = (_target: Element, scrollTo: boolean) => {\n    if(target === _target) {\n      return;\n    }\n\n    let hadTarget = false;\n    if(target) {\n      hadTarget = true;\n      target.classList.remove(activeClassName);\n    }\n\n    target = _target;\n    if(!target) return;\n    target.classList.add(activeClassName);\n\n    if(hadTarget && scrollable && scrollTo) {\n      fastSmoothScroll({\n        container: scrollable,\n        element: target as HTMLElement,\n        position: 'center',\n        forceDuration: 100,\n        axis: type === 'x' ? 'x' : 'y'\n      });\n    }\n  };\n\n  const getNextTargetX = (currentTarget: Element, isNext: boolean): Element => {\n    let nextTarget: Element;\n    if(isNext) nextTarget = currentTarget[PROPERTY_NEXT] || list[PROPERTY_FIRST];\n    else nextTarget = currentTarget[PROPERTY_PREV] || list[PROPERTY_LAST];\n\n    return nextTarget;\n  };\n\n  const getNextTargetY = (currentTarget: Element, isNext: boolean) => {\n    const property = isNext ? PROPERTY_NEXT : PROPERTY_PREV;\n    const endProperty = isNext ? PROPERTY_FIRST : PROPERTY_LAST;\n    const currentRect = currentTarget.getBoundingClientRect();\n\n    let nextTarget = currentTarget[property] || list[endProperty];\n    while(nextTarget !== currentTarget) {\n      const targetRect = nextTarget.getBoundingClientRect();\n      if(targetRect.x === currentRect.x && targetRect.y !== currentRect.y) {\n        break;\n      }\n\n      nextTarget = nextTarget[property] || list[endProperty];\n    }\n\n    return nextTarget;\n  };\n\n  let handleArrowKey: (currentTarget: Element, key: ArrowKey) => Element;\n  if(type === 'xy') { // flex-direction: row; flex-wrap: wrap;\n    handleArrowKey = (currentTarget, key) => {\n      if(key === 'ArrowUp' || key === 'ArrowDown') return getNextTargetY(currentTarget, key === 'ArrowDown');\n      else return getNextTargetX(currentTarget, key === 'ArrowRight');\n    };\n  } else { // flex-direction: row | column;\n    handleArrowKey = (currentTarget, key) => getNextTargetX(currentTarget, key === 'ArrowRight' || key === 'ArrowDown');\n  }\n\n  let onKeyDown = (e: KeyboardEvent) => {\n    const key = e.key;\n    if(!keyNames.has(key as any)) {\n      if(key === 'Enter' || (type !== 'xy' && key === 'Tab')) {\n        cancelEvent(e);\n        fireSelect(getCurrentTarget());\n      }\n\n      return;\n    }\n\n    cancelEvent(e);\n\n    if(list.childElementCount > 1) {\n      let currentTarget = getCurrentTarget();\n      currentTarget = handleArrowKey(currentTarget, key as any);\n      setCurrentTarget(currentTarget, true);\n    }\n  };\n\n  const scrollable = findUpClassName(list, 'scrollable');\n  list.classList.add('navigable-list');\n\n  const onMouseMove = (e: MouseEvent) => {\n    const target = findUpAsChild(e.target as HTMLElement, list) as HTMLElement;\n    if(!target) {\n      return;\n    }\n\n    setCurrentTarget(target, false);\n  };\n\n  const onClick = (e: Event) => {\n    cancelEvent(e); // cancel keyboard closening\n\n    const target = findUpAsChild(e.target as HTMLElement, list) as HTMLElement;\n    if(!target) {\n      return;\n    }\n\n    setCurrentTarget(target, false);\n    fireSelect(getCurrentTarget());\n  };\n\n  const fireSelect = async(target: Element) => {\n    const canContinue = await onSelect(target);\n    if(canContinue !== undefined ? !canContinue : once) {\n      detach();\n    }\n  };\n\n  let attached = false, detachClickEvent: () => void;\n  const attach = () => {\n    if(attached) return;\n    attached = true;\n    // const input = document.activeElement as HTMLElement;\n    // input.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n    document.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n    list.addEventListener('mousemove', onMouseMove, {passive: true});\n    if(cancelMouseDown) list.addEventListener('mousedown', cancelEvent);\n    detachClickEvent = attachClickEvent(list, onClick, {ignoreMove: cancelMouseDown});\n  };\n\n  const detach = () => {\n    if(!attached) return;\n    attached = false;\n    // input.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n    document.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n    list.removeEventListener('mousemove', onMouseMove);\n    if(cancelMouseDown) list.removeEventListener('mousedown', cancelEvent);\n    detachClickEvent();\n    detachClickEvent = undefined;\n  };\n\n  const resetTarget = () => {\n    if(waitForKeySet) return;\n    setCurrentTarget(list[PROPERTY_FIRST], false);\n  };\n\n  if(waitForKeySet) {\n    const _onKeyDown = onKeyDown;\n    onKeyDown = (e) => {\n      if(waitForKeySet.has(e.key)) {\n        cancelEvent(e);\n\n        document.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n        onKeyDown = _onKeyDown;\n        document.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n\n        waitForKeySet = undefined;\n        resetTarget();\n      }\n    };\n  } else if(!target) {\n    resetTarget();\n  }\n\n  attach();\n\n  return {\n    attach,\n    detach,\n    resetTarget\n  };\n}\n","import attachListNavigation, {ListNavigationOptions} from '@helpers/dom/attachListNavigation';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport rootScope from '@lib/rootScope';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport SetTransition from '@components/singleTransition';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport safeAssign from '@helpers/object/safeAssign';\nimport liteMode from '@helpers/liteMode';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\n\nexport default class AutocompleteHelper extends EventListenerBase<{\n  hidden: () => void,\n  visible: () => void,\n  hiding: () => void\n}> {\n  protected hidden = true;\n  public container: HTMLElement;\n  protected list: HTMLElement;\n  protected resetTarget: () => void;\n  protected attach: () => void;\n  protected detach: () => void;\n  protected init?(): void;\n\n  protected controller: AutocompleteHelperController;\n  protected listType: 'xy' | 'x' | 'y';\n  protected onSelect: ListNavigationOptions['onSelect'];\n  protected getNavigationList?: () => HTMLElement;\n  protected waitForKey?: string[];\n\n  protected navigationItem: NavigationItem;\n\n  // * helpers in this set are allowed to remain visible alongside this one\n  public siblings: Set<AutocompleteHelper> = new Set();\n  // * per-helper middleware so concurrent sibling helpers don't cancel each other\n  private middlewareHelper: MiddlewareHelper = getMiddleware();\n\n  constructor(options: {\n    appendTo: HTMLElement,\n    controller?: AutocompleteHelper['controller'],\n    listType: AutocompleteHelper['listType'],\n    onSelect: AutocompleteHelper['onSelect'],\n    waitForKey?: AutocompleteHelper['waitForKey'],\n    getNavigationList?: AutocompleteHelper['getNavigationList']\n  }) {\n    super(false);\n\n    safeAssign(this, options);\n\n    this.container = document.createElement('div');\n    this.container.classList.add('autocomplete-helper', 'z-depth-1');\n\n    options.appendTo.append(this.container);\n\n    this.attachNavigation();\n\n    this.controller?.addHelper(this);\n  }\n\n  public getMiddleware() {\n    this.middlewareHelper.clean();\n    return this.middlewareHelper.get();\n  }\n\n  public addSibling(other: AutocompleteHelper) {\n    this.siblings.add(other);\n    other.siblings.add(this);\n  }\n\n  public toggleListNavigation(enabled: boolean) {\n    if(enabled) {\n      this.attach?.();\n    } else {\n      this.detach?.();\n    }\n  }\n\n  protected onVisible = () => {\n    this.detach?.(); // it can be so because 'visible' calls before animation's end\n\n    const list = this.list;\n    const {attach, detach, resetTarget} = attachListNavigation({\n      list: this.getNavigationList?.() || list,\n      type: this.listType,\n      onSelect: this.onSelect,\n      once: true,\n      waitForKey: this.waitForKey\n    });\n\n    this.attach = attach;\n    this.detach = detach;\n    this.resetTarget = resetTarget;\n    if(!IS_MOBILE && !this.navigationItem) {\n      this.navigationItem = {\n        type: 'autocomplete-helper',\n        onPop: () => {\n          this.navigationItem = undefined;\n          this.toggle(true);\n        },\n        noBlurOnPop: true\n      };\n\n      appNavigationController.pushItem(this.navigationItem);\n    }\n\n    this.addEventListener('hidden', () => {\n      this.resetTarget = undefined;\n      this.attach = undefined;\n      this.detach = undefined;\n\n      list.replaceChildren();\n      detach();\n\n      if(this.navigationItem) {\n        appNavigationController.removeItem(this.navigationItem);\n        this.navigationItem = undefined;\n      }\n    }, {once: true});\n  };\n\n  protected attachNavigation() {\n    this.addEventListener('visible', this.onVisible);\n  }\n\n  public toggle(hide?: boolean, fromController = false, skipAnimation?: boolean) {\n    if(hide === undefined) {\n      hide = this.container.classList.contains('is-visible') && !this.container.classList.contains('backwards');\n    }\n\n    // * Cancel any in-flight suggestion load whenever we're hiding — including the\n    // * early-return paths below (not yet initialized, or already hidden). Otherwise a\n    // * slow request resolves later and shows the panel for input that was already\n    // * cleared, since both of those paths used to skip middlewareHelper.clean().\n    if(hide) {\n      this.middlewareHelper.clean();\n    }\n\n    if(this.init) {\n      return;\n    }\n\n    if(this.hidden === hide) {\n      if(!hide) {\n        this.dispatchEvent('visible'); // reset target and listener\n      }\n\n      return;\n    }\n\n    this.hidden = hide;\n\n    if(!hide) {\n      if(this.controller) {\n        // * preserve self + siblings so a sibling that's still loading isn't killed by us showing\n        const preserve = new Set<AutocompleteHelper>([this]);\n        this.siblings.forEach((sibling) => preserve.add(sibling));\n        this.controller.hideOtherHelpers(preserve);\n      }\n      this.dispatchEvent('visible'); // fire it before so target will be set\n    } else {\n      if(this.navigationItem) {\n        appNavigationController.removeItem(this.navigationItem);\n        this.navigationItem = undefined;\n      }\n\n      if(!fromController && this.controller) {\n        this.controller.hideOtherHelpers();\n      }\n\n      this.detach?.(); // force detach here\n    }\n\n    const useRafs = this.controller || hide ? 0 : 2;\n\n    if(hide) {\n      this.dispatchEvent('hiding');\n    }\n\n    SetTransition({\n      element: this.container,\n      className: 'is-visible',\n      forwards: !hide,\n      duration: liteMode.isAvailable('animations') && !skipAnimation ? 300 : 0,\n      onTransitionEnd: () => {\n        this.hidden && this.dispatchEvent('hidden');\n      },\n      useRafs\n    });\n  }\n}\n","import type Chat from '@components/chat/chat';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport mediaSizes from '@helpers/mediaSizes';\nimport preloadAnimatedEmojiSticker from '@helpers/preloadAnimatedEmojiSticker';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport Scrollable from '@components/scrollable';\nimport attachStickerViewerListeners from '@components/stickerViewer';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\n\nexport default class StickersHelper extends AutocompleteHelper {\n  private scrollable: Scrollable;\n  private onChangeScreen: () => void;\n  private listenerSetter: ListenerSetter;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    private chat: Chat,\n    private managers: AppManagers\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'xy',\n      onSelect: async(target) => {\n        return !(await this.chat.input.emoticonsDropdown.onMediaClick({target}, true));\n      },\n      waitForKey: ['ArrowUp', 'ArrowDown']\n    });\n\n    this.container.classList.add('stickers-helper');\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n\n      rootScope.dispatchEvent('choosing_sticker', true);\n    });\n\n    this.addEventListener('hidden', () => {\n      if(this.onChangeScreen) {\n        mediaSizes.removeEventListener('changeScreen', this.onChangeScreen);\n        this.onChangeScreen = undefined;\n\n        this.listenerSetter.removeAll();\n        this.listenerSetter = undefined;\n      }\n\n      rootScope.dispatchEvent('choosing_sticker', false);\n    });\n  }\n\n  public checkEmoticon(emoticon: string) {\n    const middleware = this.getMiddleware();\n\n    preloadAnimatedEmojiSticker(emoticon);\n    this.managers.appStickersManager.getStickersByEmoticon({\n      emoticon,\n      includeOurStickers: true,\n      includeServerStickers: this.chat.appSettings.stickers.suggest === 'all'\n    }).then((stickers) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(this.init) {\n        this.init();\n        this.init = null;\n      }\n\n      const container = this.list.cloneNode() as HTMLElement;\n\n      let ready: Promise<void>;\n\n      if(stickers.length) {\n        const lazyLoadQueue = new LazyLoadQueue();\n        const superStickerRenderer = new SuperStickerRenderer({\n          regularLazyLoadQueue: lazyLoadQueue,\n          group: this.chat.animationGroup,\n          managers: this.managers\n        });\n\n        ready = new Promise<void>((resolve) => {\n          const promises: Promise<any>[] = [];\n          stickers.forEach((sticker) => {\n            container.append(superStickerRenderer.renderSticker(sticker as MyDocument, undefined, promises));\n          });\n\n          (Promise.all(promises) as Promise<any>).finally(resolve);\n        });\n\n        middleware.onClean(() => {\n          lazyLoadQueue.clear();\n          setTimeout(() => superStickerRenderer.destroy(), 500); // * fix video flick\n        });\n      } else {\n        ready = Promise.resolve();\n      }\n\n      ready.then(() => {\n        this.list.replaceWith(container);\n        this.list = container;\n\n        if(!this.onChangeScreen) {\n          this.onChangeScreen = () => {\n            const width = (this.list.childElementCount * mediaSizes.active.esgSticker.width) + (this.list.childElementCount - 1 * 1);\n            this.list.style.width = width + 'px';\n          };\n          mediaSizes.addEventListener('changeScreen', this.onChangeScreen);\n\n          this.listenerSetter = new ListenerSetter();\n          attachStickerViewerListeners({listenTo: this.container, listenerSetter: this.listenerSetter});\n        }\n\n        this.onChangeScreen();\n\n        this.toggle(!stickers.length);\n        this.scrollable.scrollPosition = 0;\n      });\n    });\n  }\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add('stickers-helper-stickers', 'super-stickers');\n\n    this.container.append(this.list);\n\n    this.scrollable = new Scrollable(this.container);\n  }\n}\n","import {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\n/**\n * Marker class for the unified chat-input plate layout. Anything carrying this\n * class is one of the new uniform-width footer plates (as opposed to the bare\n * single buttons the control container used to hold).\n */\nexport const CHAT_INPUT_PLATE_CLASS = 'chat-input-plate';\n\n/**\n * Unified chat-input control plate.\n *\n * Every non-typing state of the chat-input footer — join channel, unblock,\n * bot start, pinned, message selection, … — renders through this single\n * layout instead of the bespoke per-state markup that used to live in the\n * control container and the selection wrapper.\n *\n * The layout mirrors the topbar translation plate (`translation.tsx`): an\n * optional icon button on each side and a centered main button —\n * `Button.Icon + Button + Button.Icon`. The side slots reserve symmetric\n * space even when empty so the centre button always stays centred, which\n * makes every plate exactly the same width as the message-input row. Plates\n * therefore cross-fade in place (opacity only) instead of morphing width.\n */\nexport default function ChatInputPlate(props: {\n  class?: string,\n  /** Optional leading icon button (`Button.Icon`). */\n  left?: JSX.Element,\n  /** Main centered button (`Button`). */\n  center: JSX.Element,\n  /** Optional trailing icon button (`Button.Icon`). */\n  right?: JSX.Element\n}): JSX.Element {\n  return (\n    <div class={classNames(CHAT_INPUT_PLATE_CLASS, 'rows-wrapper-row', props.class)}>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-side`}>{props.left}</div>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-center`}>{props.center}</div>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-side`}>{props.right}</div>\n    </div>\n  );\n}\n","import {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport styles from '@components/stargifts/stargiftBadge.module.scss';\nimport {StarGiftAttribute} from '@layer';\nimport {rgbIntToHex} from '@helpers/color';\n\nexport function StarGiftBadge(props: {\n  class?: string\n  textClass?: string\n  children: JSX.Element\n  backdropAttr?: StarGiftAttribute.starGiftAttributeBackdrop\n}) {\n  return (\n    <div\n      class={classNames(styles.badge, props.class)}\n      style={{\n        background: props.backdropAttr ?\n          `linear-gradient(180deg, ${rgbIntToHex(props.backdropAttr.center_color)} 0%, ${rgbIntToHex(props.backdropAttr.edge_color)} 100%)` :\n          undefined\n      }}\n    >\n      <div class={classNames(styles.text, props.textClass)}>\n        {props.children}\n      </div>\n    </div>\n  )\n}\n","import customProperties from '@helpers/dom/customProperties';\nimport {Middleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport pause from '@helpers/schedulers/pause';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {applyColorOnContext} from '@lib/rlottie/rlottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker';\n\nexport default async function wrapEmojiPattern({\n  docId,\n  middleware,\n  useHighlightingColor,\n  colorAsOut,\n  container,\n  color,\n  positions,\n  canvasWidth,\n  canvasHeight,\n  emojiSize,\n  onCacheStatus: onCacheStatus\n}: {\n  docId: DocId | MyDocument,\n  middleware: Middleware,\n  useHighlightingColor?: boolean,\n  colorAsOut?: boolean,\n  container?: HTMLElement,\n  color?: string,\n  positions: [x: number, y: number, size: number, alpha: number][],\n  canvasWidth: number,\n  canvasHeight: number,\n  emojiSize: number,\n  onCacheStatus?: (cached: boolean) => void\n}) {\n  let doc: MyDocument;\n  if(typeof docId  === 'object') {\n    doc = docId;\n  } else {\n    const result = await rootScope.managers.acknowledged.appEmojiManager.getCustomEmojiDocument(docId);\n    if(!result.cached) onCacheStatus?.(false);\n    doc = await result.result;\n  }\n\n  const d = document.createElement('div');\n  return wrapSticker({\n    doc,\n    div: d,\n    middleware,\n    width: emojiSize,\n    height: emojiSize,\n    // onlyThumb: true,\n    static: true,\n    withThumb: false,\n    exportLoad: 2,\n    useCache: false\n  }).then(({load, downloaded}) => {\n    onCacheStatus?.(downloaded);\n    return load();\n  }).then((result) => {\n    const image = (result as HTMLImageElement[])[0];\n    if(!image.naturalWidth) {\n      console.warn('should wait for image size', image);\n      return pause(100).then(() => image);\n    }\n    return image;\n  }).then((image) => {\n    const canvas = document.createElement('canvas');\n    canvas.classList.add('emoji-pattern-canvas');\n    canvas.style.width = `${canvasWidth}px`;\n    canvas.style.height = `${canvasHeight}px`;\n    const ctx = canvas.getContext('2d');\n    const dpr = canvas.dpr = window.devicePixelRatio;\n    canvas.width = canvasWidth * dpr;\n    canvas.height = canvasHeight * dpr;\n    positions.forEach(([x, y, size, alpha]) => {\n      ctx.globalAlpha = alpha;\n      ctx.drawImage(image, x * dpr, y * dpr, size * dpr, size * dpr);\n    });\n    ctx.globalAlpha = 1;\n\n    if(useHighlightingColor) {\n      color = '#ffffff';\n    } else if(colorAsOut) {\n      color = customProperties.getProperty('message-out-primary-color');\n    }\n\n    applyColorOnContext(ctx, color, 0, 0, canvas.width, canvas.height);\n    if(container) container.prepend(canvas);\n    return canvas;\n  }).catch(noop) as Promise<HTMLCanvasElement>;\n}\n","import {createEffect, createMemo, createSignal, JSX, on, onCleanup, onMount} from 'solid-js';\nimport {StarGiftAttribute} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport wrapEmojiPattern from '@components/wrappers/emojiPattern';\nimport {getMiddleware} from '@helpers/middleware';\nimport {rgbIntToHex} from '@helpers/color';\n\nconst MIN_OPACITY = .1;\nconst MID_OPACITY = .2;\nconst MAX_OPACITY = .3;\nconst CANVAS_WIDTH = 266;\nconst CANVAS_HEIGHT = 184;\n\nconst SMALL_CANVAS_WIDTH = 120;\nconst SMALL_CANVAS_HEIGHT = 120;\n\nimport styles from '@components/stargifts/stargiftBackdrop.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport {Transition} from '@vendor/solid-transition-group';\n\nconst POSITIONS: [number, number, number, number][] = [\n  [55, 47, 18, MAX_OPACITY],\n  [23, 26, 18, MID_OPACITY],\n  [0, 64, 18, MID_OPACITY],\n  [0, 165, 18, MIN_OPACITY],\n  [17, 125, 18, MID_OPACITY],\n  [58, 141, 22, MAX_OPACITY],\n  [81, 13, 24, MAX_OPACITY],\n  [38, 82, 26, MAX_OPACITY],\n  [187, 46, 18, MAX_OPACITY],\n  [219, 26, 18, MID_OPACITY],\n  [119, 5, 18, MAX_OPACITY],\n  [242, 64, 18, MID_OPACITY],\n  [245, 165, 18, MIN_OPACITY],\n  [225, 125, 18, MID_OPACITY],\n  [118, 151, 22, MAX_OPACITY],\n  [180, 141, 22, MAX_OPACITY],\n  [155, 13, 24, MAX_OPACITY],\n  [196, 82, 26, MAX_OPACITY]\n]\n\nconst POSITIONS_SMALL: [number, number, number, number][] = [\n  [49, 1, 20, MAX_OPACITY],\n  [93, 12, 20, MAX_OPACITY],\n  [99, 42, 20, MAX_OPACITY],\n  [89, 86, 20, MAX_OPACITY],\n  [49, 97, 20, MAX_OPACITY],\n  [9, 86, 20, MAX_OPACITY],\n  [0, 42, 20, MAX_OPACITY],\n  [5, 12, 20, MAX_OPACITY]\n];\n\nexport function StarGiftBackdrop(props: {\n  class?: string\n  small?: boolean\n  canvasClass?: string\n  backdrop: StarGiftAttribute.starGiftAttributeBackdrop\n  patternEmoji: MyDocument\n}) {\n  const middlewareHelper = getMiddleware();\n\n  const [patternCanvas, setPatternCanvas] = createSignal<HTMLCanvasElement>();\n\n  function render() {\n    const middleware = middlewareHelper.get();\n    const currentEmoji = props.patternEmoji;\n    wrapEmojiPattern({\n      docId: props.patternEmoji,\n      middleware,\n      canvasWidth: props.small ? SMALL_CANVAS_WIDTH : CANVAS_WIDTH,\n      canvasHeight: props.small ? SMALL_CANVAS_HEIGHT : CANVAS_HEIGHT,\n      emojiSize: 24,\n      positions: props.small ? POSITIONS_SMALL : POSITIONS,\n      color: rgbIntToHex(props.backdrop.pattern_color)\n    }).then((canvas) => {\n      if(!middleware()) return;\n      if(currentEmoji !== props.patternEmoji) return\n      canvas.classList.add(styles.canvas, props.canvasClass);\n      setPatternCanvas(canvas);\n    });\n  }\n\n  createEffect(on(() => [props.patternEmoji, props.backdrop], () => {\n    render();\n  }));\n\n  return (\n    <div\n      class={classNames(styles.wrap, props.class)}\n      style={{\n        '--stargift-backdrop-edge-color': rgbIntToHex(props.backdrop.edge_color),\n        '--stargift-backdrop-center-color': rgbIntToHex(props.backdrop.center_color)\n      }}\n    >\n      <Transition>\n        {patternCanvas()}\n      </Transition>\n      <div class={classNames(styles.halo, props.small && styles.haloSmall)} />\n    </div>\n  );\n}\n","import PopupElement, {addCancelButton, PopupButton} from '.';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {InputCheckPasswordSRP} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport {InputState} from '@components/inputField';\nimport PasswordInputField from '@components/passwordInputField';\nimport PopupPeer, {PopupPeerOptions} from '@components/popups/peer';\n\nexport async function passwordPopup<Result>(options: Omit<PopupPeerOptions, 'inputField'> & {\n  button?: Omit<PopupPeerOptions['buttons'][0], 'callback'>;\n  callback: (inputCheckPassword: InputCheckPasswordSRP) => Promise<Result>;\n}) {\n  let state = await rootScope.managers.passwordManager.getState();\n\n  const passwordInputField = new PasswordInputField({\n    labelText: state.hint ?? '',\n    onRawInput: () => {\n      passwordInputField.setState(InputState.Neutral);\n    }\n  });\n\n  let resolved = false;\n  const deferred = deferredPromise<Result>();\n\n  const buttonOptions: PopupButton = {\n    langKey: options.button?.langKey ?? 'Confirm',\n    langArgs: options.button?.langArgs ?? [],\n    callback: async() => {\n      buttonOptions.element.disabled = true\n      try {\n        const inputCheckPassword = await rootScope.managers.passwordManager.getInputCheckPassword(passwordInputField.value, state);\n        const result = await options.callback(inputCheckPassword);\n        deferred.resolve(result);\n        resolved = true;\n        return true\n      } catch(err) {\n        console.error(err)\n        if((err as ApiError).type === 'PASSWORD_HASH_INVALID') {\n          passwordInputField.setState(InputState.Error, 'PASSWORD_HASH_INVALID')\n        } else if((err as ApiError).type.startsWith('FLOOD_WAIT_')) {\n          passwordInputField.setState(InputState.Error, 'PasscodeLock.TooManyAttempts')\n        } else {\n          passwordInputField.setState(InputState.Error, 'Error.AnError')\n        }\n        state = await rootScope.managers.passwordManager.getState();\n        return false\n      } finally {\n        buttonOptions.element.disabled = false\n      }\n    }\n  }\n\n  const popup = PopupElement.createPopup(PopupPeer, 'popup-confirmation', {\n    ...options,\n    inputField: passwordInputField,\n    buttons: addCancelButton([buttonOptions])\n  })\n\n  popup.addEventListener('closeAfterTimeout', () => {\n    if(!resolved) {\n      deferred.reject();\n    }\n  });\n\n  popup.show()\n\n  return deferred;\n}\n","import classNames from '@helpers/string/classNames';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {IconTsx} from '@components/iconTsx';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport styles from '@components/stargifts/transferPreview.module.scss'\n\nexport function StarGiftTransferPreview(props: {\n  class?: string;\n  gift: MyStarGift\n  recipient: PeerId\n}) {\n  return (\n    <div class={classNames(styles.graph, props.class)}>\n      <div class={/* @once */ styles.giftWrap}>\n        <StarGiftBackdrop\n          backdrop={props.gift.collectibleAttributes?.backdrop}\n          patternEmoji={props.gift.collectibleAttributes?.pattern.document as MyDocument}\n          small\n          canvasClass={/* @once */ styles.giftBackdropCanvas}\n        />\n        <StickerTsx\n          sticker={props.gift.collectibleAttributes?.model.document as MyDocument}\n          width={48}\n          height={48}\n          autoStyle\n          extraOptions={{play: true, loop: true}}\n        />\n      </div>\n      <IconTsx icon=\"next\" />\n      <AvatarNewTsx\n        peerId={props.recipient}\n        size={60}\n      />\n    </div>\n  )\n}\n","import {JSX, splitProps} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport Icon from '@components/icon';\nimport ripple from '@components/ripple';\n\nexport const ButtonIconTsx = (inProps: {icon?: Icon, noRipple?: boolean} & JSX.ButtonHTMLAttributes<HTMLButtonElement>) => {\n  const [props, restProps] = splitProps(inProps, ['icon', 'class', 'children', 'noRipple']);\n\n  const btn = (\n    <button\n      class={classNames('btn-icon', props.class)}\n      {...restProps}\n      tabIndex={-1}\n    >\n      {props.icon && Icon(props.icon)}\n      {props.children}\n    </button>\n  );\n\n  if(!props.noRipple) ripple(btn as HTMLElement);\n\n  return btn;\n};\n","import {splitProps} from 'solid-js'\nimport ButtonMenuToggle from '@components/buttonMenuToggle'\nimport {attachClassName} from '@helpers/solid/classname'\n\nexport type ButtonMenuToggleProps = Parameters<typeof ButtonMenuToggle>[0] & {\n  class?: string\n}\n\nexport const ButtonMenuToggleTsx = (props: ButtonMenuToggleProps) => {\n  const [, rest] = splitProps(props, ['class'])\n  const res = ButtonMenuToggle(rest)\n\n  attachClassName(res, () => props.class)\n\n  return res\n}\n","import classNames from '@helpers/string/classNames';\nimport useStars from '@stores/stars';\nimport PopupStars, {StarsStar} from '@components/popups/stars';\nimport styles from '@components/popups/floatingStarsBalance.module.scss';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport PopupElement from '.';\nimport {i18n} from '@lib/langPack';\nimport {IconTsx} from '@components/iconTsx';\nimport {createResource} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport paymentsWrapCurrencyAmount, {formatNanoton, nanotonToJsNumber} from '@helpers/paymentsWrapCurrencyAmount';\n\nexport function FloatingStarsBalance(props: {\n  class?: string;\n  ton?: boolean;\n}) {\n  const balance = useStars();\n  const balanceTon = useStars(true);\n  const [appConfig] = createResource(() => rootScope.managers.apiManager.getAppConfig());\n\n  const converted = () => {\n    const rate = appConfig.latest?.ton_usd_rate;\n    if(!rate) return '...';\n\n    return paymentsWrapCurrencyAmount(nanotonToJsNumber(balanceTon()) * rate * 100, 'USD');\n  }\n\n  return (\n    <div class={classNames(styles.container, props.class)}>\n      <I18nTsx\n        key=\"StarsBalanceLong\"\n        args={props.ton ? [\n          <IconTsx icon=\"ton\" />,\n          <b>{formatNanoton(balanceTon())}</b>\n        ] : [\n          <StarsStar />,\n          <b>{balance()}</b>\n        ]}\n      />\n      {props.ton ? (\n        <div class={styles.tonUsd}>\n          ~{converted()}\n        </div>\n      ) : (\n        <a\n          class={styles.getMore}\n          onClick={() => PopupElement.createPopup(PopupStars)}\n        >\n          {i18n('GetMoreStars')}\n        </a>\n      )}\n    </div>\n  );\n}\n","import {createContext, createEffect, JSX, on, onCleanup, onMount, Ref, useContext} from 'solid-js';\n\nimport styles from '@components/chipTabs.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {fastRaf} from '@helpers/schedulers';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport Scrollable from '@components/scrollable2';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '../helpers/array/filterAsync';\n\ninterface ChipTabsContextValue {\n  value: string,\n  onClick: (event: MouseEvent, value: string) => void\n  updateCurrent: () => void\n}\n\nconst ChipTabsContext = createContext<ChipTabsContextValue>(null);\n\nexport function ChipTab(props: {\n  class?: string\n  children: JSX.Element\n  value: string\n}) {\n  const ctx = useContext(ChipTabsContext);\n  onCleanup(() => fastRaf(ctx.updateCurrent));\n  return (\n    <div\n      class={classNames(styles.chip, ctx.value === props.value && styles.active, props.class)}\n      onClick={(event: MouseEvent) => ctx.onClick(event, props.value)}\n      data-value={props.value}\n    >\n      {props.children}\n    </div>\n  )\n}\n\nexport function ChipTabs(props: {\n  class?: string\n  value: string,\n  view: 'surface' | 'secondary' | 'primary',\n  onChange: (value: string) => boolean | void,\n  contextMenuButtons?: (itemId: string) => MaybePromise<ButtonMenuItemOptionsVerifiable[]>,\n  children: JSX.Element\n  ref?: Ref<HTMLDivElement>\n  center?: boolean\n  needIntersectionObserver?: boolean\n}) {\n  let scrollable!: HTMLDivElement;\n  let chosenRef!: HTMLDivElement;\n\n  function updateChosen(categoryEl: HTMLElement, categoryRect: DOMRect) {\n    const scrollableRect = scrollable.getBoundingClientRect();\n    chosenRef.style.width = `${categoryRect.width}px`;\n    chosenRef.style.left = `${categoryRect.left - scrollableRect.left + scrollable.scrollLeft}px`;\n\n    const visibleRect = getVisibleRect(categoryEl, scrollable, false, categoryRect, undefined, true);\n    if(!visibleRect || visibleRect.overflow.horizontal) {\n      fastSmoothScroll({\n        element: categoryEl,\n        container: scrollable,\n        position: 'center',\n        axis: 'x'\n      });\n    }\n  }\n\n  function handleClick(event: MouseEvent, value: string) {\n    const result = props.onChange(value);\n    if(result === false) return;\n    const categoryEl = findUpClassName(event.target as HTMLElement, styles.chip);\n\n    fastRaf(() => {\n      const categoryRect = categoryEl.getBoundingClientRect();\n      updateChosen(categoryEl, categoryRect);\n    });\n  }\n\n  let updatedOnce = false\n  function updateCurrent() {\n    const categoryEl = scrollable.querySelector(`[data-value=\"${props.value}\"]`);\n    if(categoryEl) {\n      const rect = categoryEl.getBoundingClientRect();\n      if(rect.width === 0 && rect.height === 0) return;\n      updateChosen(categoryEl as HTMLElement, rect);\n    }\n    if(!updatedOnce) {\n      chosenRef.classList.add(styles.animate);\n      updatedOnce = true;\n    }\n  }\n\n  createEffect(on(() => props.value, () => fastRaf(updateCurrent)))\n\n  if(props.needIntersectionObserver) {\n    onMount(() => {\n      const observer = new IntersectionObserver((mutations) => {\n        mutations.forEach((mutation) => {\n          if(mutation.isIntersecting) {\n            updateCurrent();\n            observer.disconnect();\n          }\n        });\n      }, {\n        threshold: 1\n      });\n\n      observer.observe(scrollable.parentElement);\n\n      onCleanup(() => observer.disconnect());\n    })\n  }\n\n  if(props.contextMenuButtons) {\n    let chosenElement: HTMLElement;\n    onMount(() => {\n      createContextMenu({\n        listenTo: scrollable,\n        findElement: (event) => findUpClassName(event.target as HTMLElement, styles.chip),\n        onOpen: (event, target) => {\n          chosenElement = target;\n        },\n        buttons: [],\n        filterButtons: async() => {\n          const buttons = await props.contextMenuButtons(chosenElement.dataset.value)\n          return filterAsync(buttons, async(button) => {\n            return button?.verify ? (await button.verify()) ?? false : true;\n          })\n        }\n      })\n    })\n  }\n\n  return (\n    <ChipTabsContext.Provider\n      value={{\n        get value() {\n          return props.value;\n        },\n        onClick: handleClick,\n        updateCurrent\n      }}\n    >\n      <div\n        class={classNames(\n          props.class,\n          styles.container,\n          styles[props.view],\n          props.view === 'primary' && styles.primary,\n          props.center && styles.center\n        )}\n        ref={props.ref}\n      >\n        <Scrollable axis=\"x\" ref={scrollable}>\n          <div class={styles.chosen} ref={chosenRef} />\n          {props.children}\n        </Scrollable>\n      </div>\n    </ChipTabsContext.Provider>\n  )\n}\n","import {createEffect, createSignal, on} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport rootScope from '@lib/rootScope';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport styles from '@components/popups/buyResaleGift.module.scss';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {STARS_CURRENCY, TON_CURRENCY} from '@appManagers/constants';\nimport {StarGift} from '@layer';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {FloatingStarsBalance} from '@components/popups/floatingStarsBalance';\nimport PopupPayment from '@components/popups/payment';\nimport {StarGiftTransferPreview} from '@components/stargifts/transferPreview';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\n\nexport default class PopupBuyResaleGift extends PopupElement<{\n  finish: (result: boolean) => void\n}> {\n  private recipientId: PeerId;\n  private gift: MyStarGift;\n\n  private finished = false;\n  constructor(options: {\n    recipientId: PeerId,\n    gift: MyStarGift\n  }) {\n    super(styles.popup, {\n      overlayClosable: true,\n      body: true\n    });\n\n    this.addEventListener('close', () => {\n      if(!this.finished) {\n        this.dispatchEvent('finish', false);\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.header.remove()\n\n    this.construct()\n  }\n\n  protected async construct() {\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    const [ton, setTon] = createSignal(this.gift.resellOnlyTon ?? false);\n    const gift = this.gift.raw as StarGift.starGiftUnique;\n\n    createEffect(on(ton, (ton) => {\n      this.setButtons([\n        {\n          langKey: 'StarGiftResaleBuyConfirm',\n          langArgs: [\n              ton ?\n                paymentsWrapCurrencyAmount(this.gift.resellPriceTon, TON_CURRENCY) :\n                paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY)\n          ],\n          callback: async() => {\n            const popup = await PopupPayment.create({\n              inputInvoice: {\n                _: 'inputInvoiceStarGiftResale',\n                pFlags: {ton: ton ? true : undefined},\n                slug: gift.slug,\n                to_id: await rootScope.managers.appPeersManager.getInputPeerById(this.recipientId)\n              },\n              noShowIfStars: true,\n              purpose: 'stargift'\n            });\n\n            popup.addEventListener('finish', (result) => {\n              if(result === 'paid' || result === 'pending') {\n                this.finished = true;\n                this.dispatchEvent('finish', true);\n                this.hide()\n              }\n            });\n            return false;\n          }\n        },\n        {\n          langKey: 'Cancel',\n          callback: () => {\n            this.finished = true\n            this.dispatchEvent('finish', false);\n          }\n        }\n      ])\n    }))\n\n    return (\n      <>\n        {gift.pFlags.resale_ton_only ? (\n          <div class={/* @once */ styles.onlyTon}>\n            <I18nTsx key=\"StarGiftResaleOnlyTon\" />\n          </div>\n        ) : (\n          <ChipTabs\n            value={ton() ? 'ton' : 'stars'}\n            view=\"primary\"\n            onChange={(value) => setTon(value === 'ton')}\n          >\n            <ChipTab value=\"stars\">\n              <I18nTsx key=\"StarGiftResalePayInStars\" />\n            </ChipTab>\n            <ChipTab value=\"ton\">\n              <I18nTsx key=\"StarGiftResalePayInTon\" />\n            </ChipTab>\n          </ChipTabs>\n        )}\n\n        <StarGiftTransferPreview\n          class={/* @once */ styles.graph}\n          gift={this.gift}\n          recipient={this.recipientId}\n        />\n\n        <I18nTsx class={/* @once */ styles.title} key=\"ConfirmPayment\" />\n\n        <div class={/* @once */ styles.text}>\n          <I18nTsx\n            key={this.recipientId !== rootScope.myId ? 'StarGiftResaleBuyTextWithRecipient' : 'StarGiftResaleBuyText'}\n            args={[\n              <span>\n                {gift.title}\n                &nbsp;#{numberThousandSplitter(gift.num)}\n              </span>,\n              ton() ?\n                paymentsWrapCurrencyAmount(this.gift.resellPriceTon, TON_CURRENCY, false, false, true) :\n                paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY, false, false, true),\n              this.recipientId !== rootScope.myId && <PeerTitleTsx peerId={this.recipientId} />\n            ]}\n          />\n        </div>\n        <FloatingStarsBalance class={styles.starsBalance} ton={ton()} />\n      </>\n    )\n  }\n}\n","import {createEffect, createSignal, JSX, on, Signal, untrack} from 'solid-js';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport CheckboxField from '@components/checkboxField';\nimport {LangPackKey} from '@lib/langPack';\nimport {attachClassName} from '@helpers/solid/classname';\n\nexport default function CheckboxFieldTsx(props: {\n  class?: string,\n  text?: LangPackKey\n  signal?: Signal<boolean>,\n  checked?: boolean,\n  toggle?: boolean,\n  round?: boolean,\n  onChange?: (checked: boolean) => void,\n  stateKey?: string\n}): JSX.Element {\n  const [checked, setChecked] = props.signal ?? createSignal(props.checked ?? false);\n\n  const checkboxField = new CheckboxField({\n    text: props.text,\n    toggle: props.toggle,\n    round: props.round,\n    stateKey: props.stateKey,\n    checked: checked()\n  });\n\n  createEffect(on(checked, () => {\n    checkboxField.setValueSilently(checked());\n  }, {defer: true}));\n\n  createEffect(on(() => props.checked, (value) => {\n    if(value === undefined) {\n      return;\n    }\n\n    setChecked(value);\n  }));\n\n  subscribeOn(checkboxField.input)('change', () => {\n    setChecked(checkboxField.input.checked);\n    untrack(() => props.onChange(checked()));\n  });\n\n  attachClassName(checkboxField.label, () => props.class);\n\n  return checkboxField.label;\n}\n","import InputField, {InputFieldOptions} from '@components/inputField';\nimport currencyStarIcon from '@components/currencyStarIcon';\nimport Icon from '@components/icon';\nimport {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport {useAppConfig} from '@stores/appState';\nimport {createEffect, on} from 'solid-js';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {InputFieldTsx} from '@components/inputFieldTsx';\nimport {fastRaf} from '@helpers/schedulers';\n\nimport styles from '@components/stargifts/stargiftPriceInputField.module.scss';\n\nexport class StarGiftPriceInputFieldClass extends InputField {\n  private icon: HTMLElement;\n  private approxLabel: HTMLElement;\n\n  constructor(options: InputFieldOptions) {\n    super(options);\n\n    this.container.classList.add(styles.input)\n\n    this.icon = document.createElement('div')\n    this.icon.classList.add(styles.inputIcon)\n\n    this.approxLabel = document.createElement('div')\n    this.approxLabel.classList.add(styles.inputApproxLabel)\n\n    this.container.append(this.icon, this.approxLabel)\n\n    this.setIcon('stars')\n    this.setApproxText('≈$0.00')\n  }\n\n  public setIcon(icon: 'ton' | 'stars') {\n    if(icon === 'ton') {\n      this.icon.replaceChildren(Icon('ton'))\n    } else {\n      this.icon.replaceChildren(currencyStarIcon() as HTMLElement)\n    }\n  }\n\n  public setApproxText(text: string) {\n    this.approxLabel.textContent = text\n  }\n}\n\nexport function StarGiftPriceInputField(props: {\n  class?: string\n  label: LangPackKey\n  value: string\n  onValueChange: (value: string) => void\n  ton: boolean\n  disabled?: boolean\n  errorLabel?: LangPackKey\n  errorLabelOptions?: FormatterArguments\n  instanceRef?: (ref: StarGiftPriceInputFieldClass) => void\n}) {\n  const appConfig = useAppConfig()\n  let inputRef!: StarGiftPriceInputFieldClass\n\n  createEffect(on(() => [props.ton, props.value], ([ton, valueStr]) => {\n    if(ton) {\n      const float = Number(valueStr);\n      const usd = appConfig.ton_usd_rate * float;\n      inputRef.setApproxText(`≈${paymentsWrapCurrencyAmount(usd * 100, 'USD')}`);\n      return;\n    }\n\n    const value = +valueStr;\n    const usd = appConfig.stars_usd_sell_rate_x1000 / 1000 * value / 100;\n    inputRef.setApproxText(`≈${paymentsWrapCurrencyAmount(usd * 100, 'USD')}`);\n  }));\n\n  createEffect(on(() => props.ton, (ton, prev) => {\n    if(!inputRef) return;\n    inputRef.setIcon(ton ? 'ton' : 'stars');\n\n    if(prev !== undefined) {\n      props.onValueChange('');\n      fastRaf(() => {\n        inputRef.input.focus();\n      });\n    }\n  }));\n\n  return (\n    <InputFieldTsx\n      InputFieldClass={StarGiftPriceInputFieldClass}\n      value={props.value}\n      class={props.class}\n      plainText\n      onRawInput={(value) => {\n        let cleanValue = value.replace(/,/g, '.');\n        const parts = cleanValue.split('.');\n        if(parts.length > 2) cleanValue = parts[0] + '.' + parts.slice(1).join('');\n        cleanValue = cleanValue.replace(/[^0-9.]/g, '');\n\n        if(!props.ton) cleanValue = cleanValue.replace(/\\./g, '');\n        if(value !== cleanValue) {\n          inputRef.setValueSilently(cleanValue);\n        }\n        props.onValueChange(cleanValue);\n      }}\n      label={props.label}\n      errorLabel={props.errorLabel}\n      errorLabelOptions={props.errorLabelOptions}\n      disabled={props.disabled}\n      instanceRef={ref => {\n        inputRef = ref;\n        props.instanceRef?.(ref);\n      }}\n    />\n  )\n}\n","import {createEffect, createMemo, createSignal, JSX, on, onMount} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\n\nimport styles from '@components/popups/sellStarGift.module.scss';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport Row from '@components/rowTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {InputFieldTsx} from '@components/inputFieldTsx';\nimport {fastRaf} from '@helpers/schedulers';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {toastNew} from '@components/toast';\nimport {StarsAmount} from '@layer';\nimport paymentsWrapCurrencyAmount, {formatNanoton, nanotonToJsNumber, parseNanotonFromDecimal} from '@helpers/paymentsWrapCurrencyAmount';\nimport Section from '@components/section';\nimport {StarGiftPriceInputField} from '@components/stargifts/stargiftPriceInputField';\nimport bigInt from 'big-integer';\n\nexport default class PopupSellStarGift extends PopupElement<{\n  finish: (result: 'list' | 'unlist' | 'cancel') => void\n}> {\n  private gift: MyStarGift;\n  private allowUnlist?: boolean;\n\n  private finished = false;\n  private btnConfirmI18n: I18n.IntlElement\n  constructor(options: {\n    gift: MyStarGift,\n    allowUnlist?: boolean\n  }) {\n    super(styles.popup, {\n      closable: true,\n      overlayClosable: true,\n      title: 'StarGiftSellTitlePopup',\n      withConfirm: true,\n      withFooterConfirm: true,\n      body: true,\n      footer: true\n    });\n\n    this.addEventListener('close', () => {\n      if(!this.finished) {\n        this.dispatchEvent('finish', 'cancel');\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.btnConfirmI18n = new I18n.IntlElement({key: 'StarGiftSellButton'})\n    this.btnConfirm.replaceChildren(this.btnConfirmI18n.element)\n\n    this.construct()\n  }\n\n  protected async construct() {\n    const [appConfig, floorPrice] = await Promise.all([\n      this.managers.apiManager.getAppConfig(),\n      this.managers.appGiftsManager.getFloorPrice(this.gift.raw.title)\n    ])\n    this.appendSolid(() => this._construct({appConfig, floorPrice}));\n    this.show()\n  }\n\n  protected _construct({appConfig, floorPrice}: {appConfig: MTAppConfig, floorPrice?: Long}) {\n    const [ton, setTon] = createSignal(this.gift.resellOnlyTon ?? false);\n    const [sellAmount, setSellAmount] = createSignal('');\n\n    if(this.gift.resellOnlyTon && this.gift.resellPriceTon) {\n      setSellAmount(String(nanotonToJsNumber(this.gift.resellPriceTon)))\n    } else if(this.gift.resellPriceStars) {\n      setSellAmount(String(this.gift.resellPriceStars))\n    } else if(floorPrice) {\n      setSellAmount(String(bigInt.min(floorPrice, appConfig.stars_stargift_resale_amount_max)))\n    }\n\n    const [loading, setLoading] = createSignal(false);\n\n    const inputError = createMemo<[LangPackKey, any[]] | undefined>(() => {\n      const sellAmount$ = sellAmount();\n      if(!sellAmount$) return undefined;\n\n      if(ton()) {\n        const nanoton = parseNanotonFromDecimal(sellAmount$);\n        const min = appConfig.ton_stargift_resale_amount_min;\n        const max = appConfig.ton_stargift_resale_amount_max;\n        if(nanoton.lt(min)) {\n          return ['StarGiftMinSellAmountTon', [formatNanoton(min)]]\n        }\n\n        if(nanoton.gt(max)) {\n          return ['StarGiftMaxSellAmountTon', [formatNanoton(max)]]\n        }\n\n        return undefined\n      }\n\n      const value = +sellAmount$;\n      const min = appConfig.stars_stargift_resale_amount_min;\n      const max = appConfig.stars_stargift_resale_amount_max;\n\n      if(value < min) {\n        return ['StarGiftMinSellAmountStars', [min]]\n      }\n\n      if(value > max) {\n        return ['StarGiftMaxSellAmountStars', [max]]\n      }\n\n      return undefined\n    })\n\n    const afterCommission = createMemo(() => {\n      if(ton()) {\n        const nanoton = parseNanotonFromDecimal(sellAmount());\n        const commission = appConfig.ton_stargift_resale_commission_permille;\n        const nanotonAfter = nanoton.multiply(commission).divide(1000).toString();\n        return formatNanoton(nanotonAfter, 2);\n      }\n\n      const value = +sellAmount();\n      const commission = appConfig.stars_stargift_resale_commission_permille;\n      return Math.floor(value * (commission / 1000));\n    })\n\n    const percentage = () => (ton() ? appConfig.ton_stargift_resale_commission_permille : appConfig.stars_stargift_resale_commission_permille) / 10;\n\n    createEffect(on(() => [inputError(), sellAmount()], ([error, sellAmount]) => {\n      this.btnConfirm.toggleAttribute('disabled', !!error || (!sellAmount && !this.allowUnlist))\n      if(!sellAmount && this.allowUnlist) {\n        this.btnConfirmI18n.update({key: 'StarGiftUnlistButton'})\n      } else {\n        this.btnConfirmI18n.update({key: 'StarGiftSellButton'})\n      }\n    }))\n\n    let inputRef: HTMLElement\n\n    onMount(() => {\n      attachClickEvent(this.btnConfirm, () => {\n        setLoading(true)\n        let amount: StarsAmount | null\n        if(!sellAmount() && this.allowUnlist) {\n          amount = null\n        } else {\n          amount = ton() ? {\n            _: 'starsTonAmount',\n            amount: parseNanotonFromDecimal(sellAmount()).toString()\n          } : {\n            _: 'starsAmount',\n            amount: +sellAmount(),\n            nanos: 0\n          }\n        }\n\n        this.managers.appGiftsManager.updateResalePrice(this.gift.input, amount).then(() => {\n          this.dispatchEvent('finish', amount === null ? 'unlist' : 'list')\n          this.hide()\n        }).catch(() => {\n          toastNew({langPackKey: 'Error.AnError'})\n          setLoading(false)\n        })\n      })\n      fastRaf(() => {\n        inputRef.focus()\n      })\n    })\n\n    return (\n      <>\n        <Section\n          caption={\n            <I18nTsx\n              key={\n                sellAmount() ?\n                  ton() ? 'StarGiftYouWillReceiveTon' : 'StarGiftYouWillReceiveStars' :\n                  'StarGiftYouWillReceivePercent'\n              }\n              args={sellAmount() ? [String(afterCommission()), String(percentage())] : String(percentage())}\n            /> as Exclude<JSX.Element, string>\n          }\n        >\n          <StarGiftPriceInputField\n            class={styles.input}\n            label={ton() ? 'StarGiftSellTitleTon' : 'StarGiftSellTitleStars'}\n            value={sellAmount()}\n            onValueChange={setSellAmount}\n            ton={ton()}\n            errorLabel={inputError()?.[0]}\n            errorLabelOptions={inputError()?.[1]}\n            instanceRef={ref => { inputRef = ref.input }}\n            disabled={loading()}\n          />\n        </Section>\n        <Section caption=\"StarGiftOnlyAcceptTonInfo\">\n          <Row disabled={loading()}>\n            <Row.CheckboxField>\n              <CheckboxFieldTsx\n                checked={ton()}\n                text=\"StarGiftOnlyAcceptTon\"\n                onChange={setTon}\n              />\n            </Row.CheckboxField>\n          </Row>\n        </Section>\n      </>\n    )\n  }\n}\n","import {StarGift} from '@layer';\nimport {BroadcastEvents} from '@lib/rootScope';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\n\nexport function updateStarGift(gift: MyStarGift, update: BroadcastEvents['star_gift_update']) {\n  const {unsaved, converted, resalePrice, wearing, addCollectionId, removeCollectionId} = update;\n\n  if(unsaved !== undefined) {\n    gift.saved.pFlags.unsaved = unsaved ? true : undefined;\n  }\n  if(converted !== undefined) {\n    gift.isConverted = converted;\n  }\n\n  if(resalePrice !== undefined) {\n    if(resalePrice.length === 0) {\n      gift.resellPriceStars = null;\n      gift.resellPriceTon = null;\n      gift.resellOnlyTon = false;\n      const raw = gift.raw as StarGift.starGiftUnique;\n      raw.pFlags.resale_ton_only = undefined;\n      raw.resell_amount = undefined;\n    } else {\n      gift.resellOnlyTon = false;\n      for(const price of resalePrice) {\n        if(price._ === 'starsAmount') {\n          gift.resellPriceStars = price.amount;\n        } else if(price._ === 'starsTonAmount') {\n          gift.resellPriceTon = price.amount;\n          gift.resellOnlyTon = true;\n        }\n      }\n\n      const raw = gift.raw as StarGift.starGiftUnique;\n      raw.pFlags.resale_ton_only = gift.resellOnlyTon ? true : undefined;\n      raw.resell_amount = resalePrice;\n    }\n  }\n\n  if(wearing !== undefined) {\n    gift.isWearing = wearing;\n  }\n\n  if(addCollectionId !== undefined) {\n    const ids = gift.saved.collection_id ?? [];\n    if(!ids.includes(addCollectionId)) {\n      gift.saved.collection_id = [...ids, addCollectionId];\n    }\n  }\n\n  if(removeCollectionId !== undefined) {\n    const ids = gift.saved.collection_id;\n    if(ids) {\n      gift.saved.collection_id = ids.filter((id) => id !== removeCollectionId);\n      if(!gift.saved.collection_id.length) {\n        gift.saved.collection_id = undefined;\n      }\n    }\n  }\n}\n","import {createEffect, createMemo, createSignal, JSX, on, onMount} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\n\nimport styles from '@components/popups/starGiftValue.module.scss';\nimport {PaymentsUniqueStarGiftValueInfo, StarGift} from '@layer';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport Table, {TableButton, TableButtonWithTooltip, TableRow} from '@components/table';\nimport {formatFullSentTime} from '@helpers/date';\nimport {StarsStar} from '@components/popups/stars';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport bigInt from 'big-integer';\nimport {i18n} from '@lib/langPack';\nimport Button from '@components/buttonTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport PopupSendGift from '@components/popups/sendGift';\nimport rootScope from '@lib/rootScope';\n\nexport default class PopupStarGiftValue extends PopupElement {\n  private gift: MyStarGift;\n  private value: PaymentsUniqueStarGiftValueInfo;\n  constructor(options: {\n    gift: MyStarGift,\n    value: PaymentsUniqueStarGiftValueInfo\n  }) {\n    super(styles.popup, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      footer: false\n    });\n\n    this.header.remove()\n\n    safeAssign(this, options);\n\n    this.construct()\n  }\n\n  private construct() {\n    this.appendSolidBody(() => this._construct())\n  }\n\n  protected _construct() {\n    const value = this.value;\n    const gift = this.gift.raw as StarGift.starGiftUnique;\n\n    const tableContent = createMemo(() => {\n      const rows: TableRow[] = [];\n\n      if(value.initial_sale_date) {\n        rows.push([\n          'StarGiftInitialSale',\n          <span>{formatFullSentTime(value.initial_sale_date)}</span>\n        ]);\n      }\n\n      rows.push([\n        'StarGiftInitialPrice',\n        <span>\n          <StarsStar />\n          <I18nTsx\n            key=\"StarGiftInitialPriceValue\"\n            args={[\n              numberThousandSplitterForStars(value.initial_sale_stars),\n              paymentsWrapCurrencyAmount(value.initial_sale_price, value.currency)\n            ]}\n          />\n        </span>\n      ])\n\n      if(value.last_sale_date) {\n        rows.push([\n          'StarGiftLastSale',\n          <span>{formatFullSentTime(value.last_sale_date)}</span>\n        ]);\n      }\n\n      if(value.last_sale_price) {\n        const diff = bigInt(value.last_sale_price as string)\n        .minus(value.initial_sale_price)\n        .multiply(100)\n        .divide(value.initial_sale_price).toJSNumber()\n\n        rows.push([\n          'StarGiftLastPrice',\n          <>\n            <span>\n              <StarsStar />\n              {paymentsWrapCurrencyAmount(value.last_sale_price, value.currency)}\n            </span>\n            <TableButton>\n              {diff > 0 ? '+' : ''}{Math.round(diff)}%\n            </TableButton>\n          </>\n        ])\n      }\n\n      if(value.floor_price) {\n        rows.push([\n          'StarGiftMinimumPrice',\n          <>\n            {paymentsWrapCurrencyAmount(value.floor_price, value.currency)}\n            <TableButtonWithTooltip\n              tooltipTextElement={i18n('StarGiftMinimumPriceTooltip', [\n                paymentsWrapCurrencyAmount(value.floor_price, value.currency),\n                gift.title\n              ])}\n            >\n              ?\n            </TableButtonWithTooltip>\n          </>\n        ]);\n      }\n\n      if(value.average_price) {\n        rows.push([\n          'StarGiftAveragePrice',\n          <>\n            {paymentsWrapCurrencyAmount(value.average_price, value.currency)}\n            <TableButtonWithTooltip\n              tooltipTextElement={i18n('StarGiftAveragePriceTooltip', [\n                paymentsWrapCurrencyAmount(value.average_price, value.currency),\n                gift.title\n              ])}\n            >\n              ?\n            </TableButtonWithTooltip>\n          </>\n        ]);\n      }\n\n      return rows;\n    });\n\n    return (\n      <>\n        <ButtonIconTsx\n          class={/* @once */ styles.close}\n          icon=\"close\"\n          onClick={() => this.hide()}\n        />\n\n        <StickerTsx\n          class={/* @once */ styles.sticker}\n          sticker={this.gift.sticker}\n          width={120}\n          height={120}\n          autoStyle\n          extraOptions={{play: true, loop: false}}\n        />\n\n        <div class={/* @once */ styles.value}>\n          {paymentsWrapCurrencyAmount(value.value, value.currency)}\n        </div>\n\n        <I18nTsx\n          class={/* @once */ styles.about}\n          key={\n            value.pFlags.value_is_average ? 'StarGiftValueAboutAverage' :\n            value.pFlags.last_sale_on_fragment ? 'StarGiftValueAboutLastFragment' :\n            'StarGiftValueAboutLastTelegram'\n          }\n          args={[gift.title]}\n        />\n\n        <div class={/* @once */ styles.table}>\n          <Table\n            content={tableContent()}\n            cellClass=\"popup-star-gift-info-table-cell\"\n            footerClass={gift._ === 'starGiftUnique' ? 'popup-star-gift-info-footer-unique' : undefined}\n          />\n        </div>\n\n        <div class={/* @once */ styles.footer}>\n          {value.listed_count && (\n            <Button\n              class=\"rp-overflow btn-transparent primary\"\n              onClick={() => PopupElement.createPopup(PopupSendGift, {\n                peerId: rootScope.myId,\n                resaleParams: {\n                  giftId: gift.gift_id\n                }\n              })}\n            >\n              <I18nTsx\n                key=\"StarGiftViewResaleTelegram\"\n                args={[\n                  <span>\n                    {value.listed_count}\n                    <StickerTsx\n                      sticker={this.gift.sticker}\n                      width={24}\n                      height={24}\n                      autoStyle\n                      extraOptions={{play: false}}\n                    />\n                  </span>,\n                  <IconTsx icon=\"next\" />\n                ]}\n              />\n            </Button>\n          )}\n          {value.fragment_listed_count && (\n            <Button\n              class=\"rp-overflow btn-transparent primary\"\n              onClick={() => safeWindowOpen(value.fragment_listed_url)}\n            >\n              <I18nTsx\n                key=\"StarGiftViewResaleFragment\"\n                args={[\n                  <span>\n                    {value.fragment_listed_count}\n                    <StickerTsx\n                      sticker={this.gift.sticker}\n                      width={24}\n                      height={24}\n                      autoStyle\n                      extraOptions={{play: false}}\n                    />\n                  </span>,\n                  <IconTsx icon=\"next\" />\n                ]}\n              />\n            </Button>\n          )}\n        </div>\n      </>\n    )\n  }\n}\n","export default function createBadge(tag: 'span' | 'div', size: number, color: string) {\n  const badge = document.createElement(tag);\n  badge.className = `badge badge-${size} badge-${color} is-badge-empty`;\n  return badge;\n}\n","import {Middleware} from '@helpers/middleware';\nimport safeAssign from '@helpers/object/safeAssign';\nimport RangeSelector from '@components/rangeSelector';\n\ntype RangeStep<T extends any = any> = [HTMLElement | string, T];\nexport default class RangeStepsSelector<T extends any = any> {\n  public container: HTMLElement;\n  protected steps: RangeStep<T>[];\n  protected range: RangeSelector;\n  protected optionsElements: ReturnType<RangeStepsSelector['createOption']>[];\n\n  public middleware: Middleware;\n  public onValue: (value: T) => void;\n  public generateStep: (value: T) => RangeStep<T>;\n  public generateSteps: (values: T[]) => RangeStep<T>[];\n  protected noFirstLast: boolean;\n\n  constructor(options: {\n    middleware: RangeStepsSelector<T>['middleware'],\n    generateStep: RangeStepsSelector<T>['generateStep'],\n    generateSteps?: RangeStepsSelector<T>['generateSteps'],\n    onValue?: RangeStepsSelector<T>['onValue'],\n    noFirstLast?: boolean\n  }) {\n    safeAssign(this, options);\n\n    this.generateSteps ??= (values) => values.map(this.generateStep);\n\n    const container = this.container = document.createElement('div');\n    container.classList.add('range-setting-selector', 'range-steps-selector');\n\n    this.middleware.onClean(() => {\n      this.range.removeListeners();\n    });\n\n    const range = this.range = new RangeSelector({step: 1});\n    range.setListeners();\n    range.setHandlers({\n      onScrub: this.onIndex\n    });\n\n    container.append(range.container);\n  }\n\n  protected createOption(label: RangeStep[0], idx: number, maxIndex: number) {\n    const option = document.createElement('div');\n    option.classList.add('range-setting-selector-option');\n    const text = document.createElement('div');\n    text.classList.add('range-setting-selector-option-text');\n    text.replaceChildren(label);\n    option.append(text);\n    option.style.left = `${idx / maxIndex * 100}%`;\n\n    if(idx === 0 && !this.noFirstLast) option.classList.add('is-first');\n    else if(idx === maxIndex) {\n      option.style.left = '';\n      option.style.right = '0';\n      !this.noFirstLast && option.classList.add('is-last');\n    }\n\n    return {container: option, text};\n  }\n\n  public setSteps(steps: RangeStep[], index?: number) {\n    if(this.optionsElements) {\n      this.optionsElements.forEach(({container}) => container.remove());\n    }\n\n    const maxIndex = steps.length - 1;\n    this.range.setMinMax(0, maxIndex);\n    this.steps = steps;\n\n    this.optionsElements = steps.map(([label], idx) => {\n      const option = this.createOption(label, idx, maxIndex);\n      this.range.container.append(option.container);\n      return option;\n    });\n\n    if(index !== undefined) {\n      this.setIndex(index);\n    }\n  }\n\n  protected onIndex = (index: number) => {\n    this.onValue?.(this.steps[index][1]);\n    this.optionsElements.forEach(({container}, idx) => {\n      container.classList.toggle('active', index >= idx);\n      container.classList.toggle('is-chosen', index === idx);\n    });\n  };\n\n  public setIndex(index: number) {\n    this.range.setProgress(index);\n    this.onIndex(index);\n  }\n\n  public removeListeners() {\n    this.range.removeListeners();\n  }\n\n  public get value() {\n    return this.steps[this.range.value][1];\n  }\n}\n","import PopupElement, {createPopup} from '@components/popups/indexTsx';\nimport {batch, createEffect, createMemo, createSignal, For, JSX, onCleanup, onMount, Show} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport mediaSizes from '@helpers/mediaSizes';\nimport I18n, {i18n, LangPackKey, FormatterArguments} from '@lib/langPack';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport InputField from '@components/inputField';\nimport rootScope from '@lib/rootScope';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {formatTime, earliestSelectableMinuteMs} from '@helpers/date';\nimport suggestPostStyles from '@components/chat/suggestPostPopup/styles.module.scss';\nimport {wrapReplyMedia} from '@components/chat/replyContainer';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {Message, MessagesFilter} from '@layer';\nimport {ScrollableContextValue} from '@components/scrollable2';\n\nconst MILLIS_IN_MINUTE = 60 * 1000;\n\n// Layout constants — keep in sync with _datePicker.scss\n// CSS uses --date-picker-cell: 2.5rem and html font-size: 16px ⇒ 40px.\n// Grid row-gap: 0.25rem ⇒ 4px (only between cell rows; not above first row).\nconst CELL_HEIGHT = 40;\nconst MONTH_LABEL_HEIGHT = 40;\nconst WEEKDAY_HEIGHT = 40;\nconst ROW_GAP = 4;\nconst SCROLL_BUFFER_PX = 200; // extra rows rendered above/below viewport for smooth scrolling\n\nconst getMaxScheduleDate = () => {\n  const date = new Date();\n  date.setFullYear(date.getFullYear() + 1);\n  date.setDate(date.getDate() - 1);\n  return date;\n};\n\nconst checkDate = (date: Date, addMinutes?: number) => {\n  const ret = date.getTime() > getMaxScheduleDate().getTime() ? new Date() : date;\n  if(addMinutes) {\n    ret.setMinutes(ret.getMinutes() + addMinutes);\n  }\n  return ret;\n};\n\nconst monthKey = (d: Date) => `${d.getFullYear()}-${d.getMonth()}`;\nconst dayKey = (d: Date) => `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;\nconst dayKeyFromTimestamp = (ts: number) => {\n  const d = new Date(ts);\n  return dayKey(d);\n};\n\n// Weekend days for the user's locale, mapped to JS Date.getDay() convention\n// (0=Sun ... 6=Sat). Uses the Intl.Locale weekInfo extension when available\n// (Chrome 130+, Safari 17+, Firefox 124+) so locales like he-IL get Fri+Sat.\nlet weekendDaysCache: Set<number> | undefined;\nfunction getWeekendDays(): Set<number> {\n  if(weekendDaysCache) return weekendDaysCache;\n  try {\n    const langCode = I18n.getLastRequestedLangCode?.() || 'en';\n    const locale = new Intl.Locale(langCode) as Intl.Locale & {\n      weekInfo?: {weekend: number[]},\n      getWeekInfo?: () => {weekend: number[]}\n    };\n    const info = typeof locale.getWeekInfo === 'function' ? locale.getWeekInfo() : locale.weekInfo;\n    if(info && Array.isArray(info.weekend)) {\n      // Intl spec: 1=Mon ... 7=Sun. Map to JS getDay(): 7→0 (Sunday), others unchanged.\n      weekendDaysCache = new Set(info.weekend.map((d) => d % 7));\n      return weekendDaysCache;\n    }\n  } catch{}\n  weekendDaysCache = new Set([0, 6]);\n  return weekendDaysCache;\n}\nconst isWeekend = (date: Date) => getWeekendDays().has(date.getDay());\n\nexport type DatePickerPopupOptions = {\n  initDate: Date,\n  onPick: (timestamp: number) => void,\n  minDate?: Date,\n  maxDate?: Date,\n  withTime?: boolean,\n  addMinutes?: boolean,\n  btnConfirmLangKey?: LangPackKey,\n  btnDangerLangKey?: LangPackKey,\n  sendTodayLangKey?: LangPackKey,\n  sendDateLangKey?: LangPackKey,\n  minSendDateLangKey?: LangPackKey,\n  // suggest-post extra\n  minTimeDate?: Date,\n  // Slot for caller-provided extras inside the popup body, rendered AFTER the\n  // calendar scrollable. Used by feature-specific wrappers (e.g. the schedule\n  // sending popup adds a \"Repeat\" row here). Kept as a thunk so the JSX is\n  // evaluated lazily inside the popup's Solid context.\n  bodyAfter?: () => JSX.Element,\n  // Slot for caller-provided extra footer buttons, rendered AFTER the primary\n  // confirm button (e.g. \"Send when online\" secondary button).\n  footerAfter?: () => JSX.Element,\n  // — port: per-day media thumbnails (jump-to-date in chat) —\n  peerId?: PeerId,\n  threadId?: number,\n  mediaFilter?: MessagesFilter['_'],\n  // — port: multi-date (range) selection mode —\n  // `multiSelect` makes the popup OPEN already in range-pick mode.\n  // `canMultiSelect` shows the toggle button in the header (auto-on if onPickRange is set).\n  multiSelect?: boolean,\n  canMultiSelect?: boolean,\n  onPickRange?: (fromTimestamp: number, toTimestamp: number) => void,\n  // Override the primary footer button while multi-select is active. Lets a\n  // caller (e.g. jump-to-date in chat) replace the default \"Jump to Date\"\n  // primary action with a danger one like \"Clear History\" without leaking\n  // any of that domain logic into the picker itself.\n  multiSelectAction?: {\n    langKey: LangPackKey,\n    isDanger?: boolean,\n    // `to` defaults to `from` when only the start endpoint has been picked.\n    // Return value is forwarded to the footer button: a Promise pends the\n    // button (disabled while awaiting); a literal `false` keeps the popup open\n    // without hiding it on rejection.\n    callback: (fromTimestamp: number, toTimestamp: number) => unknown\n  }\n};\n\nexport const DATE_PICKER_POPUP_KIND = Symbol('date-picker-popup');\n\n// A grid cell is either a real day or an alignment spacer.\ntype CellModel =\n  | {kind: 'day', date: Date, timestamp: number, disabled: boolean}\n  | {kind: 'spacer', key: string};\n\ntype MonthSection = {\n  date: Date,             // first day of the month, time stripped\n  key: string,\n  cells: CellModel[],\n  rows: number,\n  height: number,\n  offset: number\n};\n\nexport default function showDatePickerPopup(opts: DatePickerPopupOptions): void {\n  const minDate = opts.minDate || new Date('2013-08-01T00:00:00');\n  minDate.setHours(0, 0, 0, 0);\n\n  const maxDate = opts.maxDate || (opts.withTime ? getMaxScheduleDate() : new Date());\n  maxDate.setHours(0, 0, 0, 0);\n\n  const initDate = checkDate(opts.initDate, opts.addMinutes ? 10 : undefined);\n  if(initDate < minDate) {\n    initDate.setFullYear(minDate.getFullYear(), minDate.getMonth(), minDate.getDate());\n  }\n\n  if(opts.minTimeDate) {\n    // Seed the inputs no lower than the earliest selectable minute, so the popup\n    // opens with Confirm enabled (the current minute's :00 may already be past).\n    const minInit = earliestSelectableMinuteMs(opts.minTimeDate.getTime(), Date.now());\n    if(initDate.getTime() < minInit) initDate.setTime(minInit);\n  }\n\n  const initHours = initDate.getHours();\n  const initMinutes = initDate.getMinutes();\n  initDate.setHours(0, 0, 0, 0);\n\n  function Inner() {\n    const listenerSetter = new ListenerSetter();\n\n    const [selectedDate, setSelectedDate] = createSignal<Date>(initDate);\n    const [selectionStart, setSelectionStart] = createSignal<Date | null>(null);\n    const [selectionEnd, setSelectionEnd] = createSignal<Date | null>(null);\n\n    // Runtime multi-select state. `multiSelect` opens the popup already in\n    // range mode. The toggle button is opt-in per-callsite via either\n    // `canMultiSelect: true` or by providing an `onPickRange` callback.\n    const [multiSelectActive, setMultiSelectActive] = createSignal(!!opts.multiSelect);\n    const showMultiSelectToggle = !!(opts.canMultiSelect || opts.onPickRange || opts.multiSelectAction);\n\n    function toggleMultiSelect() {\n      batch(() => {\n        const next = !multiSelectActive();\n        setMultiSelectActive(next);\n        // Clear any range / pick when toggling so the new mode starts fresh.\n        setSelectionStart(null);\n        setSelectionEnd(null);\n      });\n    }\n    const [hoursValue, setHoursValue] = createSignal(('0' + initHours).slice(-2));\n    const [minutesValue, setMinutesValue] = createSignal(('0' + initMinutes).slice(-2));\n\n    // Scroll state — fed from PopupElement.Scrollable's onScroll callback\n    const [scrollTop, setScrollTop] = createSignal(0);\n    const [viewportHeight, setViewportHeight] = createSignal(0);\n\n    // Per-day media cache (filled lazily as months scroll into view).\n    // Stores the most recent media-bearing message of each day; the cell\n    // renderer hands the whole message to wrapReplyMedia so photos, videos,\n    // gifs, stickers and round videos all draw correctly.\n    const [mediaByDay, setMediaByDay] = createSignal<Map<string, Message.message>>(new Map());\n    const requestedMonths = new Set<string>();\n\n    let scrollableContextRef: ScrollableContextValueOrUndefined;\n    let scrollableHostRef: HTMLDivElement | undefined;\n    let didInitialScroll = false;\n\n    const minMonth = new Date(minDate);\n    minMonth.setDate(1);\n    minMonth.setHours(0, 0, 0, 0);\n\n    const maxMonth = new Date(maxDate);\n    maxMonth.setDate(1);\n    maxMonth.setHours(0, 0, 0, 0);\n\n    // Time inputs (kept imperative — InputField is a legacy DOM construction helper)\n    let hoursInputField: InputField;\n    let minutesInputField: InputField;\n    if(opts.withTime) {\n      hoursInputField = new InputField({plainText: true});\n      minutesInputField = new InputField({plainText: true});\n      hoursInputField.setValueSilently(hoursValue());\n      minutesInputField.setValueSilently(minutesValue());\n\n      const handleTimeInput = (\n        max: number,\n        inputField: InputField,\n        setStateValue: (v: string) => void,\n        onInput: (length: number) => void,\n        onOverflow?: (number: number) => void\n      ) => {\n        const maxString = '' + max;\n        listenerSetter.add(inputField.input)('input', () => {\n          let value = inputField.value.replace(/\\D/g, '');\n          if(value.length > 2) {\n            value = value.slice(0, 2);\n          } else {\n            if((value.length === 1 && +value[0] > +maxString[0]) || (value.length === 2 && +value > max)) {\n              if(value.length === 2 && onOverflow) {\n                onOverflow(+value[1]);\n              }\n              value = '0' + value[0];\n            }\n          }\n          inputField.setValueSilently(value);\n          setStateValue(value);\n          onInput(value.length);\n        });\n      };\n\n      handleTimeInput(23, hoursInputField, setHoursValue, (length) => {\n        if(length === 2) minutesInputField.input.focus();\n      }, (number) => {\n        const next = (number + minutesInputField.value).slice(0, 2);\n        minutesInputField.setValueSilently(next);\n        setMinutesValue(next);\n      });\n      handleTimeInput(59, minutesInputField, setMinutesValue, (length) => {\n        if(!length) hoursInputField.input.focus();\n      });\n    }\n\n    // ─────────────────────────────────────────────────────────────────────────\n    // Build the chronological list of month sections (oldest → newest).\n    // Heights are pre-computed so we can virtualize without a layout pass.\n    // ─────────────────────────────────────────────────────────────────────────\n    const monthSections: MonthSection[] = (() => {\n      const list: MonthSection[] = [];\n      const cursor = new Date(minMonth);\n      let runningOffset = 0;\n\n      while(cursor <= maxMonth) {\n        const cells = buildMonthCells(cursor);\n        const rows = Math.ceil(cells.length / 7);\n        // row-gap only sits BETWEEN rows in the grid (not above the first row),\n        // so for `rows` rows we add `rows - 1` gaps.\n        const height =\n          MONTH_LABEL_HEIGHT +\n          WEEKDAY_HEIGHT +\n          rows * CELL_HEIGHT +\n          Math.max(0, rows - 1) * ROW_GAP;\n        list.push({\n          date: new Date(cursor),\n          key: monthKey(cursor),\n          cells,\n          rows,\n          height,\n          offset: runningOffset\n        });\n        runningOffset += height;\n        cursor.setMonth(cursor.getMonth() + 1);\n      }\n\n      return list;\n    })();\n\n    // Each month is a self-contained block: only its own days, with blank\n    // spacer cells filling the gaps before the 1st and after the last day.\n    function buildMonthCells(month: Date): CellModel[] {\n      const cells: CellModel[] = [];\n      const firstDate = new Date(month);\n      firstDate.setHours(0, 0, 0, 0);\n      const monthKeyStr = monthKey(firstDate);\n\n      // Leading padding (Mon-first week). Sunday=0 ⇒ 6 leading; Mon=1 ⇒ 0; etc.\n      let leading = firstDate.getDay() - 1;\n      if(leading === -1) leading = 6;\n\n      for(let i = 0; i < leading; ++i) {\n        cells.push({kind: 'spacer', key: `${monthKeyStr}-pre-${i}`});\n      }\n\n      // Days of the month.\n      const dayCursor = new Date(firstDate);\n      do {\n        cells.push({\n          kind: 'day',\n          date: new Date(dayCursor),\n          timestamp: dayCursor.getTime(),\n          disabled: dayCursor < minDate || dayCursor > maxDate\n        });\n        dayCursor.setDate(dayCursor.getDate() + 1);\n      } while(dayCursor.getDate() !== 1);\n\n      // Trailing padding to complete the final week row.\n      const remainder = cells.length % 7;\n      if(remainder) {\n        for(let i = remainder; i < 7; ++i) {\n          cells.push({kind: 'spacer', key: `${monthKeyStr}-post-${i}`});\n        }\n      }\n\n      return cells;\n    }\n\n    const totalHeight = monthSections.length ?\n      monthSections[monthSections.length - 1].offset + monthSections[monthSections.length - 1].height :\n      0;\n\n    const initialMonthIndex = Math.max(\n      0,\n      monthSections.findIndex((m) => m.key === monthKey(initDate))\n    );\n\n    // Visible window (for virtualization).\n    const visibleSections = createMemo(() => {\n      const top = scrollTop();\n      const bottom = top + Math.max(viewportHeight(), CELL_HEIGHT * 6);\n      const result: MonthSection[] = [];\n      for(const section of monthSections) {\n        const sectionBottom = section.offset + section.height;\n        if(sectionBottom < top - SCROLL_BUFFER_PX) continue;\n        if(section.offset > bottom + SCROLL_BUFFER_PX) break;\n        result.push(section);\n      }\n      return result;\n    });\n\n    // The \"currently focused\" month — drives the popup title and the up/down\n    // arrow targets. We match the section whose vertical span contains the\n    // VIEWPORT CENTER (same heuristic tdesktop's CalendarBox uses).\n    //\n    // Using the viewport's TOP edge (offset + height > scrollTop + 1) breaks\n    // at the bottom of the scroll: when the initial month is the last one, the\n    // browser clamps scrollTop to (scrollHeight − clientHeight), which lands\n    // INSIDE the second-to-last month — so the title would show that month and\n    // the up arrow would skip ahead by two.\n    const topMostSection = createMemo<MonthSection>(() => {\n      if(!monthSections.length) return undefined;\n      const top = scrollTop();\n      const vh = viewportHeight();\n      // Fall back to top-of-viewport while we don't have a measured height yet.\n      const probe = vh > 0 ? top + vh / 2 : top + 1;\n      for(const m of monthSections) {\n        if(m.offset + m.height > probe) return m;\n      }\n      return monthSections[monthSections.length - 1];\n    });\n\n    // ─── visible-month index helpers for the up/down arrows ────────────────\n    const isPrevDisabled = createMemo(() => {\n      const top = topMostSection();\n      return !top || top.key === monthSections[0]?.key;\n    });\n    const isNextDisabled = createMemo(() => {\n      const top = topMostSection();\n      return !top || top.key === monthSections[monthSections.length - 1]?.key;\n    });\n\n    function scrollToSection(section: MonthSection, smooth = true) {\n      if(!scrollableHostRef) return;\n      // Use the host element directly — Scrollable's setScrollPositionSilently\n      // would suppress the scroll event we need to update reactive state.\n      scrollableHostRef.scrollTo({\n        top: section.offset,\n        behavior: smooth ? 'smooth' : 'auto'\n      });\n    }\n\n    function onPrev() {\n      const top = topMostSection();\n      if(!top) return;\n      const idx = monthSections.indexOf(top);\n      if(idx > 0) scrollToSection(monthSections[idx - 1]);\n    }\n\n    function onNext() {\n      const top = topMostSection();\n      if(!top) return;\n      const idx = monthSections.indexOf(top);\n      if(idx < monthSections.length - 1) scrollToSection(monthSections[idx + 1]);\n    }\n\n    async function fetchMonthMedia(section: MonthSection) {\n      if(!opts.peerId) return;\n      if(requestedMonths.has(section.key)) return;\n\n      requestedMonths.add(section.key);\n\n      // Last day of the section's month (server returns messages ≤ offset_date).\n      const lastDay = new Date(section.date);\n      lastDay.setMonth(lastDay.getMonth() + 1);\n      lastDay.setDate(0);\n      lastDay.setHours(23, 59, 59, 999);\n\n      try {\n        const result = await rootScope.managers.appMessagesManager.getSearchResultsCalendar({\n          peerId: opts.peerId,\n          threadId: opts.threadId,\n          filter: {_: opts.mediaFilter || 'inputMessagesFilterPhotoVideo'} as MessagesFilter,\n          offsetDate: Math.floor(lastDay.getTime() / 1000)\n        });\n\n        if(!result.messages?.length) return;\n\n        const next = new Map(mediaByDay());\n        let added = 0;\n\n        for(const message of result.messages) {\n          if(message._ !== 'message') continue;\n          if(!message.media) continue;\n\n          const key = dayKeyFromTimestamp(message.date * 1000);\n          if(!next.has(key)) {\n            next.set(key, message);\n            ++added;\n          }\n        }\n\n        if(added) setMediaByDay(next);\n      } catch(err) {\n        // Swallow — the calendar still works without thumbnails.\n        // Re-mark as not-requested so a later visit may retry.\n        requestedMonths.delete(section.key);\n      }\n    }\n\n    // Kick off media fetches for any visible section we haven't requested yet.\n    createEffect(() => {\n      if(!opts.peerId) return;\n      const sections = visibleSections();\n      for(const section of sections) {\n        if(!requestedMonths.has(section.key)) {\n          fetchMonthMedia(section);\n        }\n      }\n    });\n\n    // ─── selected day count (multi-select only) ───────────────────────────\n    const selectedDayCount = createMemo<number>(() => {\n      const start = selectionStart();\n      if(!start) return 0;\n      const end = selectionEnd();\n      if(!end) return 1;\n      const ms = end.getTime() - start.getTime();\n      return Math.round(ms / (24 * 60 * 60 * 1000)) + 1;\n    });\n\n    // ─── title (month name, or \"N days selected\" when multi-select active) ─\n    const monthTitleEl = createMemo<JSX.Element>(() => {\n      if(multiSelectActive() && selectedDayCount() > 0) {\n        return i18n('Calendar.SelectedDays', [selectedDayCount()]);\n      }\n      const section = topMostSection();\n      const date = section ? section.date : initDate;\n      return new I18n.IntlDateElement({\n        date,\n        options: {\n          year: 'numeric',\n          month: opts.withTime && mediaSizes.isMobile ? 'short' : 'long'\n        }\n      }).element;\n    });\n\n    // ─── weekday names ─────────────────────────────────────────────────────\n    // Resolved as plain strings so the same names can be inserted into every\n    // month section. (HTMLElement nodes can only live in ONE place in the DOM,\n    // so reusing IntlDateElement-created nodes would leave all but the last\n    // section's weekday row visually empty.)\n    const weekdayInfo: Array<{name: string, weekend: boolean}> = (() => {\n      const cursor = new Date();\n      const day = cursor.getDay();\n      if(day !== 1) cursor.setHours(-24 * (day - 1));\n      const out: Array<{name: string, weekend: boolean}> = [];\n      for(let i = 0; i < 7; ++i) {\n        out.push({\n          name: new I18n.IntlDateElement({date: cursor, options: {weekday: 'narrow'}}).element.textContent,\n          weekend: isWeekend(cursor)\n        });\n        cursor.setDate(cursor.getDate() + 1);\n      }\n      return out;\n    })();\n\n    // ─── confirm label / disabled state ────────────────────────────────────\n    // Color of the primary footer button — danger only when a multi-select\n    // action explicitly opts into it (e.g. Clear History in chat).\n    const confirmColor = createMemo<'primary' | 'danger'>(() => {\n      if(multiSelectActive() && opts.multiSelectAction?.isDanger) return 'danger';\n      return 'primary';\n    });\n\n    const confirmLabel = createMemo<JSX.Element>(() => {\n      if(multiSelectActive() && opts.multiSelectAction) {\n        return i18n(opts.multiSelectAction.langKey);\n      }\n      if(opts.btnConfirmLangKey) return i18n(opts.btnConfirmLangKey);\n      if(multiSelectActive() && selectedDayCount() > 0) {\n        return i18n('Calendar.SelectedDays', [selectedDayCount()]);\n      }\n      if(!opts.withTime) return i18n('JumpToDate');\n\n      let key: LangPackKey;\n      const args: FormatterArguments = [];\n      const today = new Date();\n      today.setHours(0, 0, 0, 0);\n\n      const sendDate = new Date(selectedDate().getTime());\n      sendDate.setHours(+hoursValue() || 0, +minutesValue() || 0);\n\n      if(selectedDate().getTime() === today.getTime()) {\n        key = opts.sendTodayLangKey ?? 'Schedule.SendToday';\n      } else {\n        key = opts.sendDateLangKey ?? 'Schedule.SendDate';\n        const dateOptions: Intl.DateTimeFormatOptions = {month: 'short', day: 'numeric'};\n        if(sendDate.getFullYear() !== today.getFullYear()) {\n          dateOptions.year = 'numeric';\n        }\n        args.push(new I18n.IntlDateElement({date: sendDate, options: dateOptions}).element);\n      }\n\n      args.push(new I18n.IntlDateElement({\n        date: sendDate,\n        options: {minute: '2-digit', hour: '2-digit'}\n      }).element);\n\n      return i18n(key, args);\n    });\n\n    // A live clock so the minimum-time floor (the caption + the confirm guard)\n    // tracks real time instead of freezing at the moment the popup opened — the\n    // displayed \"Minimum send time\" would otherwise drift into the past. Minute\n    // granularity (the caption is HH:MM, the bound is minute-bucketed), so the\n    // dependent memos recompute at most once a minute, not every tick.\n    const [nowMinute, setNowMinute] = createSignal(Math.floor(Date.now() / MILLIS_IN_MINUTE));\n    if(opts.minTimeDate) {\n      const interval = setInterval(() => {\n        const minute = Math.floor(Date.now() / MILLIS_IN_MINUTE);\n        if(minute !== nowMinute()) setNowMinute(minute);\n      }, 1000);\n      onCleanup(() => clearInterval(interval));\n    }\n    const effectiveMinTime = createMemo(() => {\n      nowMinute(); // dependency: re-evaluate at each minute boundary\n      return opts.minTimeDate ?\n        new Date(earliestSelectableMinuteMs(opts.minTimeDate.getTime(), Date.now())) :\n        new Date();\n    });\n\n    const isConfirmDisabled = createMemo(() => {\n      if(multiSelectActive()) {\n        // multiSelectAction enables the button as soon as one day is picked\n        // (single-day range = same day for both endpoints). onPickRange wants\n        // an explicit two-endpoint range. With neither, fall back to single\n        // pick — also enabled with one click.\n        if(opts.onPickRange) {\n          return !selectionStart() || !selectionEnd();\n        }\n        return !selectionStart();\n      }\n      if(!opts.minTimeDate) return false;\n      const minTime = effectiveMinTime();\n      const sendDate = new Date(selectedDate().getTime());\n      sendDate.setHours(+hoursValue() || 0, +minutesValue() || 0);\n      return sendDate < new Date() ||\n        (sendDate.valueOf() / MILLIS_IN_MINUTE | 0) < (minTime.valueOf() / MILLIS_IN_MINUTE | 0);\n    });\n\n    const isMinTimeCaptionVisible = createMemo(() => {\n      if(!opts.minTimeDate) return true;\n      const minTime = effectiveMinTime();\n      const sendDate = new Date(selectedDate().getTime());\n      sendDate.setHours(+hoursValue() || 0, +minutesValue() || 0);\n      return sendDate.getDate() === minTime.getDate();\n    });\n\n    // ─── cell click handling ───────────────────────────────────────────────\n    function onCellClick(cell: CellModel) {\n      if(cell.kind !== 'day') return;\n      if(cell.disabled) return;\n\n      if(multiSelectActive()) {\n        batch(() => {\n          const start = selectionStart();\n          const end = selectionEnd();\n          if(!start || (start && end)) {\n            // First click, or third click after a complete pair → start a new range.\n            setSelectionStart(cell.date);\n            setSelectionEnd(null);\n          } else {\n            // Second click → close the range. Swap if user picked an earlier date.\n            if(cell.date < start) {\n              setSelectionStart(cell.date);\n              setSelectionEnd(start);\n            } else {\n              setSelectionEnd(cell.date);\n            }\n          }\n          setSelectedDate(cell.date);\n        });\n        return;\n      }\n\n      setSelectedDate(cell.date);\n    }\n\n    async function onConfirm() {\n      if(multiSelectActive()) {\n        const start = selectionStart();\n        if(!start) return;\n\n        // multiSelectAction takes priority: lets a caller fully replace the\n        // primary action while in multi-select (Clear History in chat, etc.).\n        // Single-day pick is treated as a 1-day range (to defaults to start).\n        if(opts.multiSelectAction) {\n          const end = selectionEnd() || start;\n          const from = new Date(start);\n          from.setHours(0, 0, 0, 0);\n          const to = new Date(end);\n          to.setHours(23, 59, 59, 999);\n          // Awaited so the footer button stays disabled while the (potentially\n          // async) action runs. The return value is intentionally discarded —\n          // PopupElement.Button.handleClick treats anything not literally\n          // `false` as success and hides the popup.\n          await opts.multiSelectAction.callback(from.getTime() / 1000 | 0, to.getTime() / 1000 | 0);\n          return;\n        }\n\n        if(opts.onPickRange) {\n          const end = selectionEnd();\n          if(!end) return;\n          const from = new Date(start);\n          from.setHours(0, 0, 0, 0);\n          const to = new Date(end);\n          to.setHours(23, 59, 59, 999);\n          return opts.onPickRange(from.getTime() / 1000 | 0, to.getTime() / 1000 | 0);\n        }\n\n        // Neither range nor action callback — fall back to single-pick on the start.\n        return opts.onPick(start.getTime() / 1000 | 0);\n      }\n\n      const date = new Date(selectedDate());\n      if(opts.withTime) {\n        date.setHours(+hoursValue() || 0, +minutesValue() || 0, 0, 0);\n      }\n      opts.onPick(date.getTime() / 1000 | 0);\n    }\n\n    function onDanger() {\n      opts.onPick(undefined);\n    }\n\n    // Footer (with the primary confirm button) is now ALWAYS rendered — the\n    // popup never auto-confirms on a single cell click, so the user always\n    // needs an explicit \"Jump to Date\" / \"Save\" / \"N days selected\" button to\n    // commit the pick. The two extra side buttons stay opt-in.\n\n    // ─── scroll plumbing ───────────────────────────────────────────────────\n    const onScroll = () => {\n      if(!scrollableContextRef) return;\n      setScrollTop(scrollableContextRef.scrollPosition);\n    };\n\n    onMount(() => {\n      // Defer to after first layout so the scrollable has its real dimensions.\n      queueMicrotask(() => {\n        if(scrollableContextRef) {\n          setViewportHeight(scrollableContextRef.clientSize);\n        }\n        if(!didInitialScroll && scrollableHostRef && monthSections[initialMonthIndex]) {\n          didInitialScroll = true;\n          scrollableHostRef.scrollTop = monthSections[initialMonthIndex].offset;\n          // setScrollTop manually because scrollTop assignment may not fire onScroll\n          // synchronously in all browsers.\n          if(scrollableContextRef) setScrollTop(scrollableContextRef.scrollPosition);\n        }\n      });\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    });\n\n    // ─── per-cell state derivation (only meaningful for kind: 'day' cells) ─\n    // In multi-select mode the visual is built from three classes:\n    //   .in-range          — solid bar background (covers endpoints + middle)\n    //   .range-edge-left   — round the left edge of the bar (row start or range start)\n    //   .range-edge-right  — round the right edge of the bar (row end or range end)\n    // .active is reserved for single-pick mode and the partial (start-only) state.\n    function isCellSelected(cell: CellModel & {kind: 'day'}): boolean {\n      if(multiSelectActive()) {\n        const start = selectionStart();\n        if(!start) return false;\n        // Both endpoints visually render as filled primary circles; the .in-range\n        // bar paints only the cells BETWEEN them (via the .range-edge-* clipping).\n        if(cell.date.getTime() === start.getTime()) return true;\n        const end = selectionEnd();\n        if(end && cell.date.getTime() === end.getTime()) return true;\n        return false;\n      }\n      return cell.timestamp === selectedDate().getTime();\n    }\n\n    function isCellInRange(cell: CellModel & {kind: 'day'}): boolean {\n      if(!multiSelectActive()) return false;\n      const start = selectionStart();\n      const end = selectionEnd();\n      if(!start || !end) return false;\n      return cell.date >= start && cell.date <= end;\n    }\n\n    function isCellRangeEdgeLeft(cell: CellModel & {kind: 'day'}, idx: number, cells: CellModel[]): boolean {\n      if(!isCellInRange(cell)) return false;\n      if(idx % 7 === 0) return true;\n      const prev = cells[idx - 1];\n      if(!prev || prev.kind !== 'day') return true;\n      return !isCellInRange(prev);\n    }\n\n    function isCellRangeEdgeRight(cell: CellModel & {kind: 'day'}, idx: number, cells: CellModel[]): boolean {\n      if(!isCellInRange(cell)) return false;\n      if(idx % 7 === 6) return true;\n      const next = cells[idx + 1];\n      if(!next || next.kind !== 'day') return true;\n      return !isCellInRange(next);\n    }\n\n    // The actual range start/end endpoints — different from edge-left/right,\n    // which also fire for row boundaries. Endpoints clip the bar at the cell\n    // center (where the .active circle sits); row-boundary non-endpoints round\n    // the bar's outer edge.\n    function isCellRangeStart(cell: CellModel & {kind: 'day'}): boolean {\n      if(!multiSelectActive()) return false;\n      const start = selectionStart();\n      const end = selectionEnd();\n      return !!(start && end && cell.date.getTime() === start.getTime());\n    }\n\n    function isCellRangeEnd(cell: CellModel & {kind: 'day'}): boolean {\n      if(!multiSelectActive()) return false;\n      const start = selectionStart();\n      const end = selectionEnd();\n      return !!(start && end && cell.date.getTime() === end.getTime());\n    }\n\n    function getCellMedia(cell: CellModel & {kind: 'day'}) {\n      return mediaByDay().get(dayKey(cell.date));\n    }\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title>\n            <div class=\"date-picker-month-title\">{monthTitleEl()}</div>\n          </PopupElement.Title>\n          <div class=\"date-picker-controls\">\n            <Show when={showMultiSelectToggle}>\n              <ButtonIconTsx\n                icon=\"select\"\n                class={classNames('date-picker-multiselect', 'primary', multiSelectActive() && 'is-active')}\n                noRipple\n                onClick={toggleMultiSelect}\n              />\n            </Show>\n            <ButtonIconTsx\n              icon=\"up\"\n              class={classNames('date-picker-prev', 'primary')}\n              noRipple\n              disabled={isPrevDisabled()}\n              onClick={onPrev}\n            />\n            <ButtonIconTsx\n              icon=\"down\"\n              class={classNames('date-picker-next', 'primary')}\n              noRipple\n              disabled={isNextDisabled()}\n              onClick={onNext}\n            />\n          </div>\n        </PopupElement.Header>\n\n        <PopupElement.Scrollable\n          class=\"date-picker-scrollable\"\n          ref={(el) => scrollableHostRef = el}\n          contextRef={(ctx) => scrollableContextRef = ctx}\n          onScroll={onScroll}\n          withBorders=\"both\"\n        >\n          <div class=\"date-picker-months\" style={{height: totalHeight + 'px'}}>\n            <For each={visibleSections()}>{(section) => (\n              <div\n                class=\"date-picker-month-section\"\n                style={{transform: `translateY(${section.offset}px)`, height: section.height + 'px'}}\n              >\n                <div class=\"date-picker-month-label\">\n                  {new I18n.IntlDateElement({\n                    date: section.date,\n                    options: {year: 'numeric', month: 'long'}\n                  }).element}\n                </div>\n                <div class=\"date-picker-weekdays\">\n                  <For each={weekdayInfo}>{(info) => (\n                    <div class={classNames('date-picker-weekday', info.weekend && 'danger')}>{info.name}</div>\n                  )}</For>\n                </div>\n                <div class=\"date-picker-month-grid\">\n                  <For each={section.cells}>{(cell, index) => {\n                    if(cell.kind === 'spacer') {\n                      return <div class=\"date-picker-spacer\" />;\n                    }\n\n                    const media = createMemo(() => getCellMedia(cell));\n                    const selected = createMemo(() => isCellSelected(cell));\n                    const inRange = createMemo(() => isCellInRange(cell));\n                    const edgeLeft = createMemo(() => isCellRangeEdgeLeft(cell, index(), section.cells));\n                    const edgeRight = createMemo(() => isCellRangeEdgeRight(cell, index(), section.cells));\n                    const rangeStart = createMemo(() => isCellRangeStart(cell));\n                    const rangeEnd = createMemo(() => isCellRangeEnd(cell));\n                    const cellWeekend = isWeekend(cell.date); // static per cell\n\n                    return (\n                      <button\n                        class={classNames(\n                          'btn-icon',\n                          'date-picker-month-date',\n                          selected() && 'active',\n                          inRange() && 'in-range',\n                          edgeLeft() && 'range-edge-left',\n                          edgeRight() && 'range-edge-right',\n                          rangeStart() && 'range-start',\n                          rangeEnd() && 'range-end',\n                          media() && 'with-media',\n                          // .danger uses !important globally — only apply when\n                          // it won't fight selection/range colors.\n                          cellWeekend && !selected() && !inRange() && 'danger'\n                        )}\n                        disabled={cell.disabled}\n                        onClick={() => onCellClick(cell)}\n                      >\n                        <Show when={media()}>\n                          <DayMediaThumb message={media()} size={CELL_HEIGHT} />\n                        </Show>\n                        <span class=\"date-picker-day-num\">{cell.date.getDate()}</span>\n                      </button>\n                    );\n                  }}</For>\n                </div>\n              </div>\n            )}</For>\n          </div>\n        </PopupElement.Scrollable>\n\n        <Show when={opts.withTime}>\n          <div class=\"date-picker-time\">\n            {hoursInputField.container}\n            <div class=\"date-picker-time-delimiter\">:</div>\n            {minutesInputField.container}\n          </div>\n        </Show>\n\n        <Show when={opts.minTimeDate}>\n          <div class={classNames(\n            suggestPostStyles.Caption,\n            suggestPostStyles.center,\n            !isMinTimeCaptionVisible() && 'hide'\n          )}>\n            {i18n(opts.minSendDateLangKey ?? 'SuggestedPosts.PublishingTime.MinSendTime', [formatTime(effectiveMinTime())])}\n          </div>\n        </Show>\n\n        <Show when={opts.bodyAfter}>\n          {opts.bodyAfter()}\n        </Show>\n\n        <PopupElement.Footer>\n          <PopupElement.FooterButton\n            color={confirmColor()}\n            class={classNames(opts.btnConfirmLangKey && 'text-uppercase')}\n            disabled={isConfirmDisabled()}\n            callback={onConfirm}\n          >\n            {confirmLabel()}\n          </PopupElement.FooterButton>\n\n          <Show when={opts.footerAfter}>\n            {opts.footerAfter()}\n          </Show>\n\n          <Show when={opts.btnDangerLangKey}>\n            <PopupElement.FooterButton\n              color=\"danger\"\n              class=\"popup-schedule-secondary text-uppercase\"\n              langKey={opts.btnDangerLangKey}\n              callback={onDanger}\n            />\n          </Show>\n        </PopupElement.Footer>\n      </>\n    );\n  }\n\n  createPopup(() => (\n    <PopupElement\n      class=\"popup-schedule popup-date-picker\"\n      closable\n      kind={DATE_PICKER_POPUP_KIND}\n      old\n    >\n      <Inner />\n    </PopupElement>\n  ));\n}\n\n// Local helper alias to keep the contextRef typing tidy.\ntype ScrollableContextValueOrUndefined = ScrollableContextValue | undefined;\n\n// Renders the media thumbnail for a single day cell using the shared reply-style\n// media renderer (so photos, videos, gifs, stickers and round videos all work).\n// `createMiddleware()` registers its own onCleanup so an unmount mid-fetch\n// cancels the pending wrap.\nfunction DayMediaThumb(props: {message: Message.message, size: number}) {\n  let containerRef: HTMLDivElement;\n  const middleware = createMiddleware().get();\n\n  onMount(() => {\n    wrapReplyMedia({\n      message: props.message,\n      mediaEl: containerRef,\n      size: props.size,\n      middleware\n    });\n  });\n\n  return <div ref={(el) => containerRef = el} class=\"date-picker-cell-photo\" />;\n}\n","import liteMode from '@helpers/liteMode';\n\nexport default function shake(element: HTMLElement) {\n  if(!liteMode.isAvailable('animations')) {\n    return;\n  }\n\n  const keyframes: Keyframe[] = [\n    {transform: 'translateX(0)'},\n    {transform: 'translateX(.25rem)'},\n    {transform: 'translateX(-.25rem)'},\n    {transform: 'translateX(0)'}\n  ];\n\n  element.animate([...keyframes, ...keyframes, ...keyframes], {\n    duration: 300,\n    iterations: 1,\n    easing: 'ease-in-out'\n  });\n}\n","import rootScope from '@lib/rootScope';\nimport {LangPackKey} from '@lib/langPack';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport appImManager from '@lib/appImManager';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {showSharingPickerPopup} from '@components/popups/pickUser';\n\n// Shared \"send a URL via the standard sharing picker\" helper. Subsumes the\n// near-identical onSelect handlers in giftLink.tsx, appMediaViewerRtmp.ts\n// (forward), sharedFolder.ts, and call/settingsPopup.tsx — each used to\n// open the picker, prep stars-payment for the single chosen peer, fire\n// `sendText`, and (sometimes) toast/open-chat. Now one helper does it all\n// and adds multi-select for free.\n//\n// Per-peer steps run sequentially: each `prepareStarsForPayment` may surface\n// its own confirmation flow, and concurrent prompts would stomp on each\n// other. A rejected payment skips that peer instead of aborting the whole\n// batch (matches the legacy single-peer behavior, which threw — effectively\n// the same: no message sent — but cleaner when multiple peers are queued).\nexport type ShareUrlOptions = {\n  url: string,\n  // Allow picking multiple recipients. Defaults to single-select.\n  multiSelect?: boolean,\n  // Single-recipient only: open the chat after sending. Ignored for multi.\n  openAfter?: boolean,\n  // Toast lang key when the URL went to one non-self peer. `%s` ← peer name.\n  // Falsy ⇒ no toast.\n  toastKey?: LangPackKey,\n  // Toast lang key when the recipient is the current user (Saved Messages).\n  // Falls back to `toastKey` if omitted.\n  toastKeyForSelf?: LangPackKey,\n  // Toast lang key when shared to multiple peers. `%d` ← count.\n  // Falls back to `toastKey` if omitted (count goes to the same slot).\n  toastKeyForMany?: LangPackKey\n};\n\nexport default function shareUrlToPeers(options: ShareUrlOptions): void {\n  showSharingPickerPopup({\n    multiSelect: options.multiSelect,\n    onSelect: async(chosen) => {\n      let sent = 0;\n      for(const {peerId, threadId, monoforumThreadId} of chosen) {\n        const preparedPayment = await PaidMessagesInterceptor.prepareStarsForPayment({\n          messageCount: 1,\n          peerId\n        });\n        if(preparedPayment === PAYMENT_REJECTED) continue;\n\n        rootScope.managers.appMessagesManager.sendText({\n          peerId,\n          threadId,\n          text: options.url,\n          replyToMonoforumPeerId: monoforumThreadId,\n          confirmedPaymentResult: preparedPayment\n        });\n\n        ++sent;\n      }\n\n      if(!sent) return;\n\n      const isMulti = chosen.length > 1;\n      const single = chosen[0];\n\n      if(!isMulti && options.openAfter) {\n        appImManager.setInnerPeer({peerId: single.peerId});\n        return;\n      }\n\n      if(isMulti) {\n        const key = options.toastKeyForMany || options.toastKey;\n        if(key) {\n          toastNew({langPackKey: key, langPackArguments: [sent]});\n        }\n      } else if(options.toastKey || options.toastKeyForSelf) {\n        const isSelf = single.peerId === rootScope.myId;\n        const key = isSelf ? (options.toastKeyForSelf || options.toastKey) : options.toastKey;\n        if(key) {\n          toastNew({\n            langPackKey: key,\n            langPackArguments: [await wrapPeerTitle({peerId: single.peerId})]\n          });\n        }\n      }\n    }\n  });\n}\n","import {copyTextToClipboard} from '@helpers/clipboard';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport wrapPlainText from '@lib/richTextProcessor/wrapPlainText';\nimport Button from '@components/button';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport shareUrlToPeers from '@components/popups/shareUrl';\nimport ripple from '@components/ripple';\nimport {toastNew} from '@components/toast';\n\nexport class InviteLink {\n  public container: HTMLDivElement;\n  public textElement: HTMLDivElement;\n  public button: HTMLButtonElement;\n  public buttonText: HTMLSpanElement;\n  public onButtonClick: () => void;\n\n  public url: string;\n\n  constructor({\n    buttons,\n    button,\n    onButtonClick,\n    listenerSetter,\n    url,\n    noRightButton,\n    onClick\n  }: {\n    buttons?: Parameters<typeof ButtonMenuToggle>[0]['buttons'],\n    button?: HTMLButtonElement | false,\n    onButtonClick?: () => void,\n    listenerSetter: ListenerSetter,\n    url?: string,\n    noRightButton?: boolean,\n    onClick?: () => void\n  }) {\n    this.onButtonClick = onButtonClick;\n\n    const linkContainer = this.container = document.createElement('div');\n    linkContainer.classList.add('invite-link-container');\n\n    const link = document.createElement('div');\n    link.classList.add('invite-link', 'rp-overflow');\n\n    const text = this.textElement = document.createElement('div');\n    text.classList.add('invite-link-text');\n\n    let rightButton: HTMLElement;\n    if(buttons) {\n      rightButton = ButtonMenuToggle({\n        buttons,\n        direction: 'bottom-left',\n        buttonOptions: {noRipple: true},\n        listenerSetter\n      });\n    } else if(!noRightButton) {\n      rightButton = ButtonIcon('copy', {noRipple: true});\n      attachClickEvent(rightButton, () => this.copyLink(), {listenerSetter});\n    }\n\n    if(rightButton) rightButton.classList.add('invite-link-menu');\n\n    if(!button && button !== false) {\n      button = Button('', {text: 'ShareLink'});\n      this.buttonText = button.lastElementChild as HTMLSpanElement;\n      attachClickEvent(button, () => {\n        if(this.onButtonClick) this.onButtonClick();\n        else this.shareLink();\n      }, {listenerSetter});\n    }\n\n    if(button) {\n      this.button = button;\n      button.className = 'btn-primary btn-color-primary invite-link-button';\n    }\n\n    if(url) this.setUrl(url);\n    ripple(link);\n    link.append(...[\n      text,\n      rightButton\n    ].filter(Boolean));\n\n    linkContainer.append(link, button || '');\n\n    attachClickEvent(link, onClick || (() => this.copyLink()), {listenerSetter});\n  }\n\n  public setUrl(url: string) {\n    let s = url;\n    if(s.includes('//')) {\n      s = url.split('//').slice(1).join('//');\n    }\n    this.textElement.replaceChildren(wrapPlainText(s));\n    this.url = url;\n  }\n\n  public copyLink = (url: string = this.url) => {\n    copyTextToClipboard(url);\n    toastNew({langPackKey: 'LinkCopied'});\n  };\n\n  public shareLink = (url: string = this.url) => {\n    shareUrlToPeers({url, openAfter: true});\n  };\n}\n","import {render} from 'solid-js/web';\nimport PopupElement from '.';\nimport {PaymentsCheckedGiftCode} from '@layer';\nimport renderImageFromUrl from '@helpers/dom/renderImageFromUrl';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {InviteLink} from '@components/sidebarLeft/tabs/inviteLink';\nimport {JSX} from 'solid-js';\nimport {formatDaysDuration, formatFullSentTime} from '@helpers/date';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport appImManager, {ChatSetPeerOptions} from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport PeerTitle from '@components/peerTitle';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport shareUrlToPeers from '@components/popups/shareUrl';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {toastNew} from '@components/toast';\nimport shouldDisplayGiftCodeAsGift from '@helpers/shouldDisplayGiftCodeAsGift';\nimport PopupPremium from '@components/popups/premium';\nimport confirmationPopup from '@components/confirmationPopup';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport DotRenderer from '@components/dotRenderer';\nimport themeController from '@helpers/themeController';\nimport Table, {TablePeer} from '@components/table';\n\nexport default class PopupGiftLink extends PopupElement {\n  private isInChat: boolean;\n\n  constructor(\n    private slug: string,\n    private stack?: ChatSetPeerOptions['stack'],\n    private checkedGiftCode?: PaymentsCheckedGiftCode\n  ) {\n    super('popup-boosts popup-gift-link', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      withConfirm: true,\n      scrollable: true,\n      floatingHeader: true,\n      footer: true,\n      title: true\n    });\n\n    this.isInChat = !!checkedGiftCode;\n    this.construct();\n  }\n\n  private _construct(dotsCanvas: HTMLElement) {\n    const isUsed = !!this.checkedGiftCode.used_date;\n    const titleLangKey: LangPackKey = isUsed ? 'BoostingUsedGiftLink' : 'BoostingGiftLink';\n    this.title.replaceChildren(i18n(titleLangKey));\n\n    const url = this.isInChat && !isUsed ? '' : 'https://t.me/giftcode/' + this.slug;\n\n    const inviteLink = new InviteLink({\n      button: false,\n      listenerSetter: this.listenerSetter,\n      url,\n      noRightButton: !url,\n      onClick: !url && (() => {\n        toastNew({langPackKey: 'BoostingOnlyRecipientCode'});\n      })\n    });\n\n    if(dotsCanvas) {\n      dotsCanvas.classList.add('invite-link-dots');\n      inviteLink.container.appendChild(dotsCanvas);\n    }\n\n    const makePeer = (peerId: PeerId) => (\n      <TablePeer\n        peerId={peerId}\n        onClick={() => {\n          this.hideWithCallback(() => {\n            appImManager.setInnerPeer({peerId});\n          });\n        }}\n      />\n    );\n\n    const isGiveaway = this.checkedGiftCode.pFlags.via_giveaway;\n\n    const fromPeerId = getPeerId(this.checkedGiftCode.from_id);\n    const toPeerId = this.checkedGiftCode.to_id && getPeerId(this.checkedGiftCode.to_id);\n\n    const giveawayAnchor = this.checkedGiftCode.giveaway_msg_id || isGiveaway ? document.createElement('a') : undefined;\n    if(giveawayAnchor) {\n      giveawayAnchor.href = '#';\n      giveawayAnchor.append(i18n('BoostingIncompleteGiveaway'));\n      attachClickEvent(giveawayAnchor, () => {\n        this.hideWithCallback(() => {\n          appImManager.setInnerPeer({\n            peerId: fromPeerId,\n            lastMsgId: this.checkedGiftCode.giveaway_msg_id\n          });\n        });\n      }, {listenerSetter: this.listenerSetter});\n    }\n\n    const reasonValue = toPeerId ? (\n      toPeerId === rootScope.myId ?\n        i18n('BoostingYouWereSelected') :\n        i18n('BoostingUserWasSelected', [new PeerTitle({peerId: toPeerId}).element])\n    ) : giveawayAnchor;\n\n    let content: [LangPackKey, JSX.Element][] = [\n      ['BoostingFrom', makePeer(fromPeerId)],\n      ['BoostingTo', toPeerId ? makePeer(toPeerId) : i18n('BoostingNoRecipient')],\n      ['BoostingGift', i18n('BoostingTelegramPremiumFor', [formatDaysDuration(this.checkedGiftCode.days)])],\n      !this.isInChat && ['BoostingReason', reasonValue],\n      ['BoostingDate', formatFullSentTime(this.checkedGiftCode.date, undefined, true)]\n    ];\n    content = content.filter(Boolean);\n\n    const shareLink = anchorCallback((e) => {\n      cancelEvent(e);\n      this.hideWithCallback(() => {\n        PopupGiftLink.shareGiftLink(url, true);\n      });\n    });\n\n    let img: HTMLImageElement;\n    const ret = (\n      <div class=\"popup-gift-link-wrapper\">\n        <div class=\"popup-gift-link-header\">\n          <img ref={img} class=\"popup-gift-link-image\" />\n          <div class=\"popup-gift-link-title\">{i18n(titleLangKey)}</div>\n          <div class=\"popup-gift-link-subtitle\">\n            {\n              isUsed ?\n                i18n('BoostingLinkUsed') :\n                i18n(\n                  toPeerId === rootScope.myId ? 'BoostingLinkAllows' : (toPeerId ? 'BoostingLinkAllowsToUser' : 'BoostingLinkAllowsAnyone'),\n                  toPeerId ? [new PeerTitle({peerId: toPeerId}).element] : undefined\n                )\n            }\n          </div>\n        </div>\n        {inviteLink.container}\n        <Table class=\"popup-gift-link-table\" boldKey content={content} />\n        {(!this.isInChat || !isUsed) && (\n          <div class=\"popup-gift-link-share\">\n            {isUsed ?\n              i18n('BoostingUsedLinkDate', [formatFullSentTime(this.checkedGiftCode.used_date, undefined, true)]) :\n              this.isInChat && !this.checkedGiftCode.slug ?\n                i18n('BoostingLinkNotActivated') :\n                i18n(toPeerId ? 'Giveaway.SendLinkToFriend' : 'Giveaway.SendLinkToAnyone', [shareLink])\n            }\n          </div>\n        )}\n      </div>\n    );\n\n    renderImageFromUrl(img, `assets/img/premium-star${window.devicePixelRatio > 1 ? '@2x' : ''}.png`);\n\n    const canUseLink = !this.isInChat && !isUsed;\n    this.btnConfirm.append(i18n(!canUseLink ? 'OK' : 'BoostingUseLink'));\n    this.btnConfirm.classList.add('popup-boosts-button');\n    this.footer.append(this.btnConfirm);\n    this.body.after(this.footer);\n    this.footer.classList.add('abitlarger');\n\n    attachClickEvent(this.btnConfirm, () => {\n      if(!canUseLink) {\n        this.hide();\n        return;\n      }\n\n      PopupGiftLink.applyGiftCode(this.slug, this.btnConfirm, this);\n    }, {listenerSetter: this.listenerSetter});\n\n    return ret;\n  }\n\n  private async construct() {\n    this.checkedGiftCode ??= await this.managers.appPaymentsManager.checkGiftCode(this.slug);\n    if(shouldDisplayGiftCodeAsGift(this.checkedGiftCode)) {\n      this.destroy();\n      PopupPremium.show({\n        gift: this.checkedGiftCode,\n        stack: this.stack\n      });\n      return;\n    }\n\n    let dotsCanvas: HTMLElement;\n    if(this.isInChat && !this.checkedGiftCode.used_date) {\n      const {canvas, readyResult} = DotRenderer.create({\n        width: 320,\n        height: 32,\n        middleware: this.middlewareHelper.get(),\n        animationGroup: 'STICKERS-POPUP',\n        config: {\n          particlesCount: 1000,\n          color: themeController.isNight() ? 0xffffff : 0x000000\n        }\n      });\n\n      await readyResult;\n      dotsCanvas = canvas;\n    }\n\n    const div = document.createElement('div');\n    this.scrollable.append(div, this.btnConfirm);\n    const dispose = render(() => this._construct(dotsCanvas), div);\n    this.addEventListener('closeAfterTimeout', dispose);\n    this.show();\n  }\n\n  public static shareGiftLink(url: string, openAfter?: boolean) {\n    shareUrlToPeers({\n      url,\n      openAfter,\n      toastKey: 'BoostingGiftLinkForwardedTo',\n      toastKeyForSelf: 'BoostingGiftLinkForwardedToSavedMsg'\n    });\n  }\n\n  public static async applyGiftCode(slug: string, button: HTMLElement, popup: PopupElement) {\n    const toggle = toggleDisability(button, true);\n    try {\n      await PopupElement.MANAGERS.appPaymentsManager.applyGiftCode(slug);\n      popup.hide();\n      toastNew({langPackKey: 'GiftLink.UseSuccess'});\n    } catch(err) {\n      if((err as ApiError).type.includes('PREMIUM_SUB_ACTIVE_UNTIL_')) {\n        popup.hide();\n        const timestamp = +(err as ApiError).type.split('_').pop();\n        let button: Parameters<typeof confirmationPopup>[0]['button'];\n        confirmationPopup({\n          titleLangKey: 'GiftPremiumActivateErrorTitle',\n          descriptionLangKey: 'GiftCode.Activation.After',\n          descriptionLangArgs: [\n            formatFullSentTime(timestamp),\n            anchorCallback(() => {\n              simulateClickEvent(button.element);\n              popup.hide();\n              this.shareGiftLink('https://t.me/giftcode/' + slug);\n            })\n          ],\n          button: button = {\n            langKey: 'OK',\n            isCancel: true\n          }\n        });\n      }\n\n      console.error('giftcode error', err);\n      toggle();\n    }\n  }\n}\n","import {Boost, PremiumBoostsStatus, PrepaidGiveaway} from '@layer';\nimport {LangPackKey, i18n, joinElementsWith} from '@lib/langPack';\nimport Section from '@components/section';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {Accessor, createMemo, createRoot, createSignal, For, JSX, onCleanup, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport Row from '@components/row';\nimport {avatarNew, AvatarNew} from '@components/avatarNew';\nimport LimitLine from '@components/limit';\nimport {LoadableList, StatisticsOverviewItems, createLoadableList, MoreButton, makeAbsStats} from '@components/sidebarRight/tabs/statistics';\nimport PopupBoostsViaGifts, {BoostsBadge} from '@components/popups/boostsViaGifts';\nimport Button from '@components/button';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport PopupElement from '@components/popups';\nimport {InviteLink} from '@components/sidebarLeft/tabs/inviteLink';\nimport {horizontalMenu} from '@components/horizontalMenu';\nimport classNames from '@helpers/string/classNames';\nimport {formatFullSentTime} from '@helpers/date';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport Icon from '@components/icon';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport rootScope from '@lib/rootScope';\nimport PopupGiftLink from '@components/popups/giftLink';\nimport {toastNew} from '@components/toast';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport appImManager from '@lib/appImManager';\nimport PopupPayment from '@components/popups/payment';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport PopupBoost from '@components/popups/boost';\nimport Tabs from '@components/tabs';\n\nconst getColorByMonths = (months: number) => {\n  return months === 12 ? 'red' : (months === 3 ? 'green' : 'blue');\n};\n\nconst getBoostsDays = (from: number, to: number) => Math.round((to - from) / 86400);\nconst getBoostMonths = (from: number, to: number) => Math.round(getBoostsDays(from, to) / 30);\n\nexport const CPrepaidGiveaway = (props: {\n  giveaway: PrepaidGiveaway,\n  appConfig: MTAppConfig,\n  clickable?: true | (() => void),\n  listenerSetter?: ListenerSetter\n}) => {\n  const {quantity} = props.giveaway;\n  const stars = (props.giveaway as PrepaidGiveaway.prepaidStarsGiveaway).stars;\n  const months = (props.giveaway as PrepaidGiveaway.prepaidGiveaway).months;\n  const boosts = stars ? (props.giveaway as PrepaidGiveaway.prepaidStarsGiveaway).boosts : (props.appConfig.giveaway_boosts_per_premium || 1) * quantity;\n  const row = new Row({\n    titleLangKey: stars ? 'Stars' : 'BoostingGiveawayMsgInfoPlural1',\n    titleLangArgs: [stars || quantity],\n    subtitleLangKey: stars ? 'Giveaway.Prepaid.For' : 'Giveaway.Prepaid.Subtitle',\n    subtitleLangArgs: [quantity, i18n('Giveaway.Prepaid.Period', [months])],\n    clickable: props.clickable,\n    listenerSetter: props.listenerSetter,\n    rightContent: BoostsBadge({boosts}) as HTMLElement\n  });\n\n  row.title.classList.add('text-bold');\n  const media = row.createMedia('abitbigger');\n  const avatar = AvatarNew({size: 42});\n  if(stars) {\n    avatar.set({icon: 'star', color: 'stars'});\n  } else {\n    avatar.set({icon: 'gift_premium', color: getColorByMonths(months)});\n  }\n  media.append(avatar.node);\n\n  return row.container;\n};\n\nexport default class AppBoostsTab extends SliderSuperTabEventable {\n  private peerId: PeerId;\n  private isBroadcast: boolean;\n  private targets: Map<HTMLElement, Boost>;\n  private canCreateGiveaway: boolean;\n\n  private _construct(\n    boostsStatus: PremiumBoostsStatus,\n    appConfig: MTAppConfig,\n    boostsList: Accessor<LoadableList>,\n    giftsBoostsList: Accessor<LoadableList>\n  ) {\n    const limitLine = new LimitLine({\n      progress: true,\n      hint: {\n        icon: 'boost',\n        noStartEnd: true\n      }\n    });\n\n    const isMaxLevel = boostsStatus.next_level_boosts === undefined;\n    const progress = isMaxLevel ?\n      1 :\n      (boostsStatus.boosts - boostsStatus.current_level_boosts) / (boostsStatus.next_level_boosts - boostsStatus.current_level_boosts);\n\n    limitLine.setProgress(\n      progress,\n      '' + boostsStatus.boosts,\n      {\n        from1: i18n('BoostsLevel', [boostsStatus.level]),\n        to1: i18n('BoostsLevel', [boostsStatus.level + 1]),\n        from2: i18n('BoostsLevel', [boostsStatus.level]),\n        to2: i18n('BoostsLevel', [boostsStatus.level + 1])\n      }\n    );\n\n    limitLine._setHintActive();\n\n    const url = boostsStatus.boost_url;\n\n    const inviteLink = new InviteLink({\n      listenerSetter: this.listenerSetter,\n      url\n    });\n\n    const boostsViaGiftsButton = Button('btn-primary btn-transparent primary', {icon: 'gift_premium', text: 'BoostingGetBoostsViaGifts'});\n    attachClickEvent(boostsViaGiftsButton, () => {\n      PopupElement.createPopup(PopupBoostsViaGifts, this.peerId);\n    }, {listenerSetter: this.listenerSetter});\n\n    const boostButton = Button('btn-primary btn-transparent primary', {icon: 'addboost', text: this.isBroadcast ? 'BoostChannel' : 'BoostGroup'});\n    attachClickEvent(boostButton, () => {\n      PopupElement.createPopup(PopupBoost, this.peerId);\n    }, {listenerSetter: this.listenerSetter});\n\n    const noBoostersHint = i18n('NoBoostersHint');\n    noBoostersHint.classList.add('boosts-no-boosters');\n\n    let tabs: HTMLDivElement, content: HTMLDivElement;\n\n    const MenuTab = (props: {\n      key: LangPackKey,\n      count: number\n    }) => {\n      return (\n        <Tabs.MenuTab class=\"boosts-users-tab\">{i18n(props.key, [props.count])}</Tabs.MenuTab>\n      );\n    };\n\n    const ContentTab = (props: {\n      list: LoadableList,\n      hide: boolean,\n      moreKey: LangPackKey\n    }) => {\n      return (\n        <Tabs.ContentTab\n          class={classNames('boosts-users-content', !props.list.count && 'is-empty')}\n          hide={props.hide}\n        >\n          <Show when={props.list.count} fallback={noBoostersHint}>\n            {props.list.rendered}\n            <Show when={!!props.list.loadMore}>\n              <MoreButton\n                count={props.list.count - props.list.rendered.length}\n                callback={() => props.list.loadMore()}\n                key={props.moreKey}\n              />\n            </Show>\n          </Show>\n        </Tabs.ContentTab>\n      );\n    };\n\n    const [tab, setTab] = createSignal(0);\n    const [prepaidGiveaways, setPrepaidGiveaways] = createSignal(boostsStatus.prepaid_giveaways?.slice() || [], {equals: false});\n    const onlyGiftedBoosts = createMemo(() => boostsStatus.gift_boosts === boostsStatus.boosts);\n    const showGifts = createMemo(() => !onlyGiftedBoosts() && !!giftsBoostsList().count);\n\n    const ret = (\n      <>\n        <Section>\n          {limitLine.container}\n          <StatisticsOverviewItems items={[{\n            title: 'BoostsLevel2',\n            value: makeAbsStats(boostsStatus.level),\n            includeZeroValue: true\n          }, {\n            title: 'PremiumSubscribers',\n            value: boostsStatus.premium_audience,\n            includeZeroValue: true,\n            describePercentage: true\n          }, {\n            title: 'BoostsExisting',\n            value: makeAbsStats(boostsStatus.boosts),\n            includeZeroValue: true\n          }, {\n            title: 'BoostsToLevel',\n            value: makeAbsStats(boostsStatus.next_level_boosts - boostsStatus.boosts)\n          }]} />\n        </Section>\n        {this.canCreateGiveaway && prepaidGiveaways().length && (\n          <Section name=\"Giveaway.Prepaid\" nameArgs={[1]} caption=\"BoostingSelectPaidGiveaway\">\n            <For each={prepaidGiveaways()}>{(prepaidGiveaway) => {\n              return (\n                <CPrepaidGiveaway\n                  giveaway={prepaidGiveaway}\n                  appConfig={appConfig}\n                  clickable={() => {\n                    PopupElement.createPopup(\n                      PopupBoostsViaGifts,\n                      this.peerId,\n                      prepaidGiveaway,\n                      () => {\n                        setPrepaidGiveaways((giveaways) => {\n                          indexOfAndSplice(giveaways, prepaidGiveaway);\n                          return giveaways;\n                        });\n                      }\n                    );\n                  }}\n                  listenerSetter={this.listenerSetter}\n                />\n              );\n            }}</For>\n          </Section>\n        )}\n        <Section class=\"boosts-users-container\">\n          <Tabs.Menu ref={tabs} class=\"boosts-users-tabs\">\n            <MenuTab key=\"BoostingBoostsCount\" count={boostsList().count} />\n            {showGifts() && <MenuTab key=\"BoostingGiftsCount\" count={giftsBoostsList().count} />}\n          </Tabs.Menu>\n          <Tabs.Content ref={content} class=\"boosts-users-contents\" onClick={async(e) => {\n            const target = findUpClassName(e.target, 'row');\n            const boost = this.targets.get(target);\n            if(!boost) {\n              return;\n            }\n\n            if(boost.stars) {\n              PopupPayment.create({\n                noPaymentForm: true,\n                transaction: {\n                  _: 'starsTransaction',\n                  date: boost.date,\n                  id: '',\n                  peer: {\n                    _: 'starsTransactionPeer',\n                    peer: {\n                      _: 'peerChannel',\n                      channel_id: this.peerId.toChatId()\n                    }\n                  },\n                  pFlags: {},\n                  amount: formatStarsAmount(boost.stars),\n                  giveaway_post_id: boost.giveaway_msg_id\n                },\n                boost\n              });\n              return;\n            }\n\n            const slug = boost.used_gift_slug;\n            const peerId = boost.user_id?.toPeerId(false);\n            if(peerId && !boost.pFlags.gift && !boost.pFlags.unclaimed && !boost.pFlags.giveaway) {\n              appImManager.setInnerPeer({peerId: boost.user_id.toPeerId(false)});\n            } else if(peerId && peerId !== rootScope.myId) {\n              PopupElement.createPopup(\n                PopupGiftLink,\n                slug,\n                undefined,\n                {\n                  _: 'payments.checkedGiftCode',\n                  chats: [],\n                  date: boost.date,\n                  days: getBoostsDays(boost.date, boost.expires),\n                  pFlags: {via_giveaway: boost.pFlags.giveaway || undefined},\n                  users: [],\n                  from_id: await this.managers.appPeersManager.getOutputPeer(this.peerId),\n                  giveaway_msg_id: boost.giveaway_msg_id,\n                  slug,\n                  to_id: peerId.toUserId(),\n                  used_date: slug ? 1 : undefined\n                }\n              );\n            } else if(slug) {\n              PopupElement.createPopup(PopupGiftLink, slug);\n            } else {\n              toastNew({langPackKey: 'BoostingRecipientWillBeSelected'});\n            }\n          }}>\n            <ContentTab list={boostsList()} hide={tab() !== 0} moreKey=\"BoostingShowMoreBoosts\" />\n            {showGifts() && <ContentTab list={giftsBoostsList()} hide={tab() !== 1} moreKey=\"BoostingShowMoreGifts\" />}\n          </Tabs.Content>\n        </Section>\n        <Section name=\"LinkForBoosting\" caption=\"BoostingShareThisLink\">\n          {inviteLink.container}\n        </Section>\n        <Section caption={this.canCreateGiveaway ? 'BoostingGetMoreBoosts' : undefined}>\n          {boostButton}\n          {this.canCreateGiveaway && boostsViaGiftsButton}\n        </Section>\n      </>\n    );\n\n    const selectTab = horizontalMenu(tabs, content, (index) => {\n      setTab(index);\n    }, undefined, undefined, undefined, this.listenerSetter);\n    selectTab(tab());\n\n    return ret;\n  }\n\n  private renderBoost = async(boost: Boost) => {\n    const boosts = 1 * (boost.multiplier || 1);\n    const months = getBoostMonths(boost.date, boost.expires);\n    let peerId = boost.user_id?.toPeerId(false);\n    if(peerId === rootScope.myId && boost.pFlags.unclaimed) {\n      peerId = undefined;\n    }\n\n    let badge: HTMLElement;\n    if(boosts > 1) {\n      badge = document.createElement('span');\n      badge.classList.add('boosts-user-boosts', 'boosts-user-badge');\n      badge.append(Icon('boost'), ` ${boosts}`);\n    }\n\n    let title: HTMLElement;\n    if(peerId) {\n      title = await wrapPeerTitle({peerId});\n      title.classList.add('boosts-user-name');\n    } else if(boost.stars) {\n      title = i18n('Stars', [boost.stars]);\n    } else {\n      title = i18n(boost.pFlags.unclaimed ? 'BoostingUnclaimed' : 'BoostingToBeDistributed');\n    }\n\n    let subtitle: HTMLElement;\n    if(peerId || boost.stars) {\n      subtitle = i18n('BoostsExpiration', [boosts, formatFullSentTime(boost.expires, undefined, true)]);\n    } else {\n      subtitle = document.createElement('span');\n      subtitle.append(\n        ...joinElementsWith([\n          i18n('BoostingShortMonths', [months]),\n          formatFullSentTime(boost.expires, undefined, true)\n        ], ' • ')\n      );\n    }\n\n    let rightContent: HTMLElement;\n    if(boost.pFlags.giveaway || boost.pFlags.gift) {\n      rightContent = document.createElement('span');\n      rightContent.classList.add('boosts-user-badge-right', 'boosts-user-badge');\n      rightContent.append(\n        Icon(boost.pFlags.giveaway ? 'gift_premium' : 'gift'),\n        i18n(boost.pFlags.giveaway ? 'BoostingGiveaway' : 'BoostingGift')\n      );\n\n      rightContent.classList.toggle('is-gift', !boost.pFlags.giveaway && !!boost.pFlags.gift);\n    }\n\n    const row = new Row({\n      title: true,\n      subtitle,\n      clickable: true,\n      noWrap: true,\n      rightContent\n    });\n\n    if(peerId) {\n      row.container.dataset.peerId = '' + peerId;\n    }\n\n    row.title.classList.add('boosts-user-title');\n    row.title.append(...[title, badge].filter(Boolean));\n    const media = row.createMedia('abitbigger');\n    const avatar = avatarNew({\n      peerId,\n      size: 42,\n      middleware: this.middlewareHelper.get()\n    });\n    media.append(avatar.node);\n\n    if(peerId) {\n      await avatar.readyThumbPromise;\n    } else if(boost.stars) {\n      avatar.set({\n        icon: 'star',\n        color: 'stars'\n      });\n    } else {\n      avatar.set({\n        icon: boost.pFlags.unclaimed ? 'deleteuser' : 'noncontacts',\n        color: getColorByMonths(months)\n      });\n    }\n\n    this.targets.set(row.container, boost);\n    return row.container;\n  };\n\n  public async init(peerId: PeerId) {\n    this.container.classList.add('boosts-container');\n\n    this.peerId = peerId;\n    this.isBroadcast = await this.managers.appPeersManager.isBroadcast(peerId);\n    this.targets = new Map();\n\n    this.setTitle('Boosts');\n\n    const createLoader = (gifts?: boolean) => {\n      const middleware = this.middlewareHelper.get();\n      let offset = '', isFirst = true;\n      const loadMore = async() => {\n        const limit = isFirst ? 20 : 100;\n        isFirst = false;\n        const boostsList = await this.managers.appBoostsManager.getBoostsList({peerId, offset, limit, gifts});\n        if(!middleware()) return;\n\n        const promises = boostsList.boosts.map(this.renderBoost);\n        const rendered = await Promise.all(promises);\n\n        setF((value) => {\n          value.count = boostsList.count;\n          offset = boostsList.next_offset;\n          if(!offset) {\n            value.loadMore = undefined;\n          }\n\n          value.rendered.push(...rendered);\n          return value;\n        });\n      };\n\n      const [f, setF] = createLoadableList({loadMore});\n      return f;\n    };\n\n    const [boostsList, giftsBoostsList] = createRoot((dispose) => {\n      const middleware = this.middlewareHelper.get();\n      middleware.onDestroy(dispose);\n      return [createLoader(false), createLoader(true)]\n    });\n\n    const [boostsStatus, appConfig, _, __, canCreateGiveaway] = await Promise.all([\n      this.managers.appBoostsManager.getBoostsStatus(peerId),\n      this.managers.apiManager.getAppConfig(),\n      boostsList().loadMore(),\n      giftsBoostsList().loadMore(),\n      this.managers.appChatsManager.hasRights(peerId.toChatId(), 'create_giveaway')\n    ]);\n\n    this.canCreateGiveaway = canCreateGiveaway;\n\n    const div = document.createElement('div');\n    this.scrollable.append(div);\n    const dispose = render(() => this._construct(boostsStatus, appConfig, boostsList, giftsBoostsList), div);\n    this.eventListener.addEventListener('destroy', dispose);\n  }\n}\n","// All arguments are UNIX timestamps in SECONDS (matching tsNow(true) and the\n// MTProto until_date field). The end date must be strictly in the future and no\n// later than now + giveaway_period_max — mirroring tdesktop's ChooseDateTimeBox\n// bounds (.min = now, .max = now + giveawayPeriodMax) and its collect() guard.\nexport default function isGiveawayUntilDateValid(untilDate: number, now: number, periodMax: number) {\n  return untilDate > now && untilDate <= now + periodMax;\n}\n","import PopupElement from '.';\nimport I18n, {FormatterArguments, LangPackKey, _i18n, i18n, join} from '@lib/langPack';\nimport Row from '@components/row';\nimport CheckboxField from '@components/checkboxField';\nimport Section from '@components/section';\nimport RangeStepsSelector from '@components/rangeStepsSelector';\nimport {Accessor, For, JSX, createEffect, createMemo, createSignal, untrack} from 'solid-js';\nimport tsNow from '@helpers/tsNow';\nimport showDatePickerPopup from '@components/popups/datePicker';\nimport {formatFullSentTime, formatMonthsDuration} from '@helpers/date';\nimport renderImageFromUrl from '@helpers/dom/renderImageFromUrl';\nimport Icon from '@components/icon';\nimport {AvatarNew} from '@components/avatarNew';\nimport Button from '@components/button';\nimport PeerTitle from '@components/peerTitle';\nimport {HelpCountry, InputInvoice, InputStorePaymentPurpose, PremiumGiftCodeOption, PrepaidGiveaway, StarsGiveawayOption, StarsGiveawayWinnersOption} from '@layer';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport PopupPremium from '@components/popups/premium';\nimport {premiumOptionsForm} from '@components/premium/promoSlideTab';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {filterCountries} from '@components/countryInputField';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {getCountryEmoji} from '@vendor/emoji';\nimport {toastNew} from '@components/toast';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {randomLong} from '@helpers/random';\nimport PopupPayment from '@components/popups/payment';\nimport shake from '@helpers/dom/shake';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {IconTsx} from '@components/iconTsx';\nimport {CPrepaidGiveaway} from '@components/sidebarRight/tabs/boosts';\nimport isObject from '@helpers/object/isObject';\nimport classNames from '@helpers/string/classNames';\nimport RowTsx from '@components/rowTsx';\nimport {StarsStackedStars} from '@components/popups/stars';\nimport numberThousandSplitter, {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport flatten from '@helpers/array/flatten';\nimport isGiveawayUntilDateValid from '@helpers/giveaway/isGiveawayUntilDateValid';\n\nexport const BoostsBadge = (props: {boosts: number}) => {\n  return (\n    <span class=\"popup-boosts-badge\">\n      <IconTsx icon=\"boost\" class=\"popup-boosts-badge-icon\" />\n      {props.boosts}\n    </span>\n  );\n};\n\nexport const BoostsConfirmButton = (props: {\n  button: HTMLElement,\n  langKey: Accessor<LangPackKey>,\n  langArgs?: Accessor<FormatterArguments>,\n  boosts: Accessor<number>\n}) => {\n  let s: HTMLSpanElement, ssss: HTMLSpanElement;\n  const ss = (<span ref={s} class=\"popup-boosts-button-text\">{i18n(props.langKey(), props.langArgs?.())}</span>);\n  const sss = (<span ref={ssss} class={classNames('popup-boosts-button-badge', !props.boosts() && 'hide')}><IconTsx icon=\"boost\" class=\"popup-boosts-button-badge-icon\" />{props.boosts()}</span>);\n  props.button.classList.add('popup-boosts-button');\n  props.button.append(s, ssss);\n};\n\nexport default class PopupBoostsViaGifts extends PopupElement {\n  private premiumGiftCodeOptions: PremiumGiftCodeOption[];\n  private starsOptions: StarsGiveawayOption[];\n  private appConfig: MTAppConfig;\n  private channelsLimit: number;\n  private subscribersLimit: number;\n  private countriesLimit: number;\n\n  constructor(\n    private peerId: PeerId,\n    private prepaidGiveaway?: PrepaidGiveaway,\n    private onCreated?: () => void\n  ) {\n    super('popup-boosts', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      title: 'BoostsViaGifts.Title',\n      floatingHeader: true,\n      footer: true,\n      withConfirm: true\n    });\n\n    this.construct();\n  }\n\n  private _construct() {\n    const [subscriptionsCount, setSubscriptionsCount] = createSignal(10);\n    const [expiration, setExpiration] = createSignal(tsNow(true) + 3 * 86400);\n    const [peerIds, setPeerIds] = createSignal<PeerId[]>([this.peerId]);\n    const [specificPeerIds, setSpecificPeerIds] = createSignal<PeerId[]>([]);\n    const [stars, setStars] = createSignal(this.prepaidGiveaway?._ === 'prepaidStarsGiveaway');\n    const [starsOption, setStarsOption] = createSignal<StarsGiveawayOption>(this.starsOptions?.[0]);\n    const [starsWinner, setStarsWinner] = createSignal<StarsGiveawayWinnersOption>(starsOption() && starsOption().winners[0]);\n    const [specific, setSpecific] = createSignal(false);\n    const [durationForm, setDurationForm] = createSignal<JSX.Element>();\n    const [option, setOption] = createSignal<PremiumGiftCodeOption>();\n    const [countries, setCountries] = createSignal<string[]>();\n    const [onlyNewSubscribers, setOnlyNewSubscribers] = createSignal(false);\n    const [additionalPrizes, setAdditionalPrizes] = createSignal(false);\n    const [additionalPrize, setAdditionalPrize] = createSignal('');\n    const [showPrizes, setShowPrizes] = createSignal(true);\n    const isPrepaid = createMemo(() => !!this.prepaidGiveaway);\n    const count = createMemo(() => stars() ? starsWinner().users : subscriptionsCount());\n    const boosts = createMemo(() => stars() ? starsOption().yearly_boosts : count() * (this.appConfig.giveaway_boosts_per_premium ?? 1));\n\n    let range: RangeStepsSelector<number>;\n    if(!isPrepaid()) {\n      range = new RangeStepsSelector({\n        generateStep: (value) => ['' + value, value],\n        onValue: (value) => {\n          if(stars()) {\n            setStarsWinner(starsOption().winners.find((winner) => winner.users === value));\n          } else {\n            setSubscriptionsCount(value);\n          }\n        },\n        middleware: this.middlewareHelper.get(),\n        noFirstLast: true\n      });\n\n      createEffect(() => {\n        if(stars()) {\n          const stepValues = starsOption().winners.map((winner) => winner.users);\n          const steps = range.generateSteps(stepValues);\n          const winner = untrack(starsWinner);\n          let index = stepValues.findIndex((v) => v >= winner.users);\n          if(index === -1) {\n            index = stepValues.length - 1;\n          } else if(stepValues[index] !== winner.users) {\n            index = Math.max(0, index - 1);\n          }\n          range.setSteps(steps, index);\n          return;\n        }\n\n        // const stepValues = filterUnique(this.premiumGiftCodeOptions.map((o) => o.users));\n        const stepValues = [1, 3, 5, 7, 10, 25, 50, 100].filter((v) => this.premiumGiftCodeOptions.some((o) => o.users === v));\n        const steps = range.generateSteps(stepValues);\n        const focusValue = untrack(subscriptionsCount);\n        range.setSteps(steps, stepValues.indexOf(focusValue));\n      });\n    } else {\n      setSubscriptionsCount(this.prepaidGiveaway.quantity);\n    }\n\n    const radioOptions: ConstructorParameters<typeof CheckboxField>[0] = {\n      round: true,\n      asRadio: true\n    };\n\n    const expirationRow = new Row({\n      titleLangKey: 'Ends',\n      titleRightSecondary: true,\n      clickable: () => {\n        const now = tsNow(true);\n        const minTimeDate = new Date(now * 1000);\n        const minDate = new Date(minTimeDate);\n        minDate.setHours(0, 0, 0, 0);\n        const maxDate = new Date((now + (this.appConfig.giveaway_period_max ?? 604800)) * 1000);\n        const initDate = new Date(expiration() * 1000);\n        showDatePickerPopup({\n          initDate,\n          withTime: true,\n          minDate,\n          minTimeDate,\n          onPick: (timestamp) => {\n            setExpiration(timestamp);\n          },\n          btnConfirmLangKey: 'Save',\n          maxDate\n        });\n      },\n      listenerSetter: this.listenerSetter\n    });\n\n    expirationRow.titleRight.classList.add('primary');\n\n    createEffect(() => {\n      expirationRow.titleRight.replaceChildren(formatFullSentTime(expiration()));\n    });\n\n    const updateSpecific = (specific: boolean) => {\n      setSubscriptionsCount(specific ? specificPeerIds().length : range?.value);\n      setSpecific(specific);\n      this.scrollable.updateThumb();\n    };\n\n    let img: HTMLImageElement;\n\n    let prepaidRowContainer: HTMLElement,\n      createRowContainer: HTMLElement,\n      starsRowContainer: HTMLElement;\n    if(this.prepaidGiveaway) {\n      prepaidRowContainer = CPrepaidGiveaway({\n        giveaway: this.prepaidGiveaway,\n        appConfig: this.appConfig\n      });\n    } else {\n      const createRow = new Row({\n        titleLangKey: 'BoostingPremium',\n        subtitle: true,\n        clickable: (e) => {\n          if(stars()) {\n            setStars(false);\n            return;\n          }\n\n          cancelEvent(e);\n          const popup = showPickUserPopup({\n            peerType: ['channelParticipants'],\n            peerId: this.peerId,\n            onSelect: (arr) => {\n              setSpecificPeerIds(arr.map(({peerId}) => peerId));\n              updateSpecific(true);\n              starsRow.checkboxField.setValueSilently(true);\n            },\n            multiSelect: true,\n            placeholder: 'SearchPlaceholder',\n            exceptSelf: true,\n            titleLangKey: 'Giveaway.Type.Specific.Modal.SelectUsers',\n            initial: specificPeerIds()\n          });\n\n          popup.selector.setLimit(this.subscribersLimit, () => {\n            toastNew({langPackKey: 'Giveaway.MaximumSubscribers', langPackArguments: [this.subscribersLimit]});\n          });\n        },\n        checkboxField: new CheckboxField({\n          ...radioOptions,\n          checked: !stars(),\n          name: 'giveaway-type'\n        }),\n        listenerSetter: this.listenerSetter\n      });\n\n      const createMedia = createRow.createMedia('abitbigger');\n      const createAvatar = AvatarNew({size: 42});\n      createAvatar.set({icon: 'gift_premium', color: 'premium'});\n      createMedia.append(createAvatar.node);\n      createRowContainer = createRow.container;\n\n      const starsRow = new Row({\n        titleLangKey: 'BoostingStars',\n        subtitleLangKey: 'BoostsViaGifts.CreateSubtitle',\n        clickable: (e) => {\n          setStars(true);\n        },\n        checkboxField: new CheckboxField({\n          ...radioOptions,\n          checked: stars(),\n          name: 'giveaway-type'\n        }),\n        listenerSetter: this.listenerSetter\n      });\n\n      createEffect(() => {\n        const peerIds = specificPeerIds();\n        const showTitles = !(!peerIds.length || peerIds.length > 2);\n        createRow.subtitle.classList.toggle('is-flex', !showTitles);\n        if(!showTitles) {\n          createRow.subtitle.replaceChildren(\n            i18n(peerIds.length > 2 ? 'Recipient' : 'BoostsViaGifts.CreateSubtitle', [peerIds.length]),\n            createNextIcon()\n          );\n        } else {\n          createRow.subtitle.classList.remove('is-flex');\n          const titles = peerIds.map((peerId) => {\n            const peerTitle = new PeerTitle({\n              peerId\n            });\n\n            return peerTitle.element;\n          });\n\n          createRow.subtitle.replaceChildren(...join(titles, false));\n        }\n      });\n\n      createRow.subtitle.classList.add('primary');\n\n      const specificMedia = starsRow.createMedia('abitbigger');\n      const specificAvatar = AvatarNew({size: 42});\n      specificAvatar.set({icon: 'star', color: 'stars'});\n      specificMedia.append(specificAvatar.node);\n      starsRowContainer = starsRow.container;\n\n      starsRowContainer.classList.add('popup-boosts-type');\n      createRowContainer.classList.add('popup-boosts-type', 'popup-boosts-specific');\n    }\n\n    const createNextIcon = () => Icon('next', 'popup-boosts-specific-next');\n\n    const premiumPromoAnchor = anchorCallback(() => {\n      PopupPremium.show();\n    });\n\n    let lastOptionIndex: number;\n    createEffect(() => {\n      const _count = subscriptionsCount();\n      const periods = new Map<number, PremiumGiftCodeOption>();\n      this.premiumGiftCodeOptions.forEach((option, _, arr) => {\n        const months = option.months;\n        if(periods.has(months)) {\n          return;\n        }\n\n        const sorted = arr.filter((o) => o.months === months).sort((a, b) => a.users - b.users);\n        const idx = sorted.findIndex((o) => o.users >= _count);\n        const nearestOption = sorted[idx] || sorted[sorted.length - 1];\n        periods.set(months, nearestOption);\n      });\n\n      const options = [...periods.values()].sort((a, b) => b.months - a.months);\n      const durationForm = premiumOptionsForm({\n        periodOptions: options,\n        onOption: (option) => {\n          lastOptionIndex = options.indexOf(option);\n          setOption(option);\n        },\n        checked: lastOptionIndex,\n        users: _count,\n        discountInTitle: true\n      });\n\n      setDurationForm(durationForm);\n    });\n\n    const addChannelButton = Button('btn btn-primary btn-transparent primary', {\n      icon: 'add',\n      text: 'AddChannel'\n    });\n\n    attachClickEvent(addChannelButton, async() => {\n      const toggle = toggleDisability(addChannelButton, true);\n      const popup = showPickUserPopup({\n        filterPeerTypeBy: ['isBroadcast'],\n        onSelect: (arr) => {\n          setPeerIds([this.peerId, ...arr.map(({peerId}) => peerId)]);\n        },\n        multiSelect: true,\n        placeholder: 'SearchPlaceholder',\n        titleLangKey: 'AddChannels',\n        initial: peerIds().filter((peerId) => peerId !== this.peerId),\n        excludePeerIds: new Set([this.peerId]),\n        onCloseAfterTimeout: () => toggle()\n      });\n\n      popup.selector.setLimit(this.channelsLimit, () => {\n        toastNew({langPackKey: 'BoostingSelectUpToWarningChannelsPlural', langPackArguments: [this.channelsLimit]});\n      });\n\n      const _add = popup.selector.add.bind(popup.selector);\n      let ignorePrivatePeerId: PeerId;\n      popup.selector.add = (options) => {\n        const peerId = options.key.toPeerId();\n        const chat = apiManagerProxy.getChat(peerId.toChatId());\n        if(\n          !getPeerActiveUsernames(chat)[0] &&\n          ignorePrivatePeerId !== peerId &&\n          popup.selector.getSelected().length < this.channelsLimit\n        ) {\n          confirmationPopup({\n            titleLangKey: 'BoostingGiveawayPrivateChannel',\n            descriptionLangKey: 'BoostingGiveawayPrivateChannelWarning',\n            button: {\n              langKey: 'Add'\n            }\n          }).then(() => {\n            ignorePrivatePeerId = peerId;\n            popup.selector.add({key: peerId});\n            popup.selector.toggleElementCheckboxByKey(peerId, true);\n            ignorePrivatePeerId = undefined;\n          });\n          return false;\n        }\n\n        return _add(options);\n      };\n    }, {listenerSetter: this.listenerSetter});\n\n    const getCountriesSubtitle = () => {\n      return (\n        <span class=\"primary is-flex\">\n          {i18n(countries() ? 'BoostingFromCountriesCount' : 'BoostingFromAllCountries', [countries()?.length])} {createNextIcon()}\n        </span>\n      ) as HTMLElement;\n    };\n\n    const onCountriesClick = (e: MouseEvent) => {\n      const container = findUpClassName(e.target, 'row');\n      const checkbox = container.querySelector('.checkbox-field-input') as HTMLInputElement;\n\n      if(!checkbox.checked) {\n        return;\n      }\n\n      let lastFiltered: Map<string, HelpCountry>;\n      const popup = showPickUserPopup({\n        peerType: ['custom'],\n        renderResultsFunc: (iso2s) => {\n          iso2s.forEach((iso2) => {\n            const country = lastFiltered.get(iso2 as any as string);\n            const emoji = getCountryEmoji(country.iso2);\n            const title = document.createDocumentFragment();\n            const emojiContainer = document.createElement('span');\n            emojiContainer.classList.add('selector-countries-emoji');\n            emojiContainer.append(wrapEmojiText(emoji))\n            title.append(emojiContainer, ' ', i18n(country.default_name as any));\n            const row = new Row({\n              title,\n              clickable: true,\n              havePadding: true\n            });\n\n            row.container.append(popup.selector.checkbox(popup.selector.selected.has(iso2)));\n            row.container.dataset.peerId = '' + iso2;\n            popup.selector.list.append(row.container);\n          });\n        },\n        placeholder: 'Search',\n        onSelect: (iso2s) => {\n          setCountries(iso2s.map(({peerId}) => peerId) as any as string[]);\n        },\n        multiSelect: true,\n        getMoreCustom: async(q) => {\n          const filtered = filterCountries(q, true);\n          lastFiltered = new Map();\n          return {\n            result: filtered.map((country) => {\n              lastFiltered.set(country.iso2, country);\n              return country.iso2;\n            }) as any,\n            isEnd: true\n          };\n        },\n        titleLangKey: 'BoostingSelectCountry',\n        checkboxSide: 'left',\n        noPlaceholder: true\n      });\n\n      const _add = popup.selector.add.bind(popup.selector);\n      popup.selector.add = ({key, scroll}) => {\n        const country = I18n.countriesList.find((country) => country.iso2 === key);\n        const ret = _add({\n          key: key,\n          title: i18n(country.default_name as any),\n          scroll\n        });\n        if(isObject(ret)) {\n          ret.avatar.render({peerTitle: getCountryEmoji(country.iso2)});\n        }\n        return ret;\n      };\n\n      popup.selector.searchSection.container.classList.add('is-countries');\n      popup.selector.container.classList.add('is-countries');\n      popup.selector.addInitial(countries());\n      popup.selector.setLimit(this.countriesLimit, () => {\n        toastNew({langPackKey: 'BoostingSelectUpToWarningCountriesPlural', langPackArguments: [this.countriesLimit]});\n      });\n    };\n\n    const notSpecific = (\n      <>\n        {!isPrepaid() && stars() && (\n          <Section\n            name=\"BoostingStarsOptions\"\n            caption=\"BoostingStarsOptionsInfo\"\n            captionOld={true}\n          >\n            <form>\n              <For each={this.starsOptions}>\n                {(option) => {\n                  const checkboxField = new CheckboxField({\n                    ...radioOptions,\n                    checked: starsOption() === option,\n                    name: 'giveaway-stars-quantity'\n                  });\n\n                  const subtitle = createMemo(() => {\n                    const winner = option.winners.find((winner) => winner.users === starsWinner().users);\n                    if(!winner) {\n                      return;\n                    }\n\n                    return i18n('BoostingStarOptionPerUser', [numberThousandSplitterForStars(+winner.per_user_stars)]);\n                  });\n\n                  return (\n                    <RowTsx\n                      class=\"popup-boosts-stars-row\"\n                      noRipple\n                      clickable={() => {\n                        setStarsOption(option);\n                      }}\n                    >\n                      <RowTsx.Title>\n                        <span class=\"popup-boosts-stars-amount text-bold\">\n                          <StarsStackedStars stars={+option.stars} size={18} />\n                          {' '}\n                          {i18n('Stars', [numberThousandSplitterForStars(+option.stars)])}\n                        </span>\n                      </RowTsx.Title>\n                      <RowTsx.Subtitle>{subtitle()}</RowTsx.Subtitle>\n                      <RowTsx.RightContent>{paymentsWrapCurrencyAmount(option.amount, option.currency)}</RowTsx.RightContent>\n                      <RowTsx.CheckboxField>{checkboxField.label}</RowTsx.CheckboxField>\n                    </RowTsx>\n                  );\n                }}\n              </For>\n            </form>\n          </Section>\n        )}\n        {!isPrepaid() && (\n          <Section\n            name={stars() ? 'BoostingStarsQuantityPrizes' : 'BoostsViaGifts.Quantity'}\n            nameRight={!stars() && <BoostsBadge boosts={boosts()} />}\n            caption={stars() ? 'BoostingStarsQuantityPrizesInfo' : 'BoostsViaGifts.QuantitySubtitle'}\n            captionOld={true}\n          >\n            {range.container}\n          </Section>\n        )}\n        <Section name=\"BoostsViaGifts.Channels\">\n          <For each={peerIds()}>{(peerId, idx) => {\n            const peerTitle = new PeerTitle();\n            peerTitle.update({peerId});\n            peerTitle.element.classList.add('text-bold');\n            let subtitleElement: HTMLSpanElement;\n            (\n              <span ref={subtitleElement}>\n                {idx() === 0 && i18n('BoostsViaGifts.ChannelSubscription', [boosts()])}\n                {idx() !== 0 && getChatMembersString(peerId.toChatId(), undefined, undefined, true) as HTMLElement}\n              </span>\n            );\n            const row = new Row({\n              title: peerTitle.element,\n              subtitle: subtitleElement,\n              ...(peerId !== this.peerId && {\n                clickable: (e) => {\n                  row.openContextMenu(e);\n                },\n                contextMenu: {\n                  buttons: [{\n                    icon: 'delete',\n                    danger: true,\n                    text: 'Remove',\n                    onClick: () => {\n                      setPeerIds((peerIds) => peerIds.filter((_peerId) => _peerId !== peerId));\n                    }\n                  }]\n                }\n              })\n            });\n            row.container.classList.add('popup-boosts-channel');\n            row.createMedia('abitbigger').append(AvatarNew({peerId, size: 42}).node);\n            return row.container;\n          }}</For>\n          {/* (peerIds().length - 1) < this.channelsLimit &&  */addChannelButton}\n        </Section>\n        <Section\n          name=\"BoostsViaGifts.Users\"\n          caption=\"BoostsViaGifts.UsersSubtitle\"\n          captionOld={true}\n        >\n          <form>\n            {new Row({\n              titleLangKey: 'AllSubscribers',\n              clickable: (e) => (setOnlyNewSubscribers(false), onCountriesClick(e)),\n              checkboxField: new CheckboxField({\n                ...radioOptions,\n                checked: true/* !onlyNewSubscribers() */,\n                name: 'giveaway-users'\n              }),\n              subtitle: getCountriesSubtitle(),\n              listenerSetter: this.listenerSetter\n            }).container}\n            {new Row({\n              titleLangKey: 'OnlyNewSubscribers',\n              clickable: (e) => (setOnlyNewSubscribers(true), onCountriesClick(e)),\n              checkboxField: new CheckboxField({\n                ...radioOptions,\n                // checked: onlyNewSubscribers(),\n                name: 'giveaway-users'\n              }),\n              subtitle: getCountriesSubtitle(),\n              listenerSetter: this.listenerSetter\n            }).container}\n          </form>\n        </Section>\n      </>\n    );\n\n    const additionalPrizeDiv = (\n      <div class=\"popup-boosts-additional-row\">\n        <div class=\"popup-boosts-additional-row-count\">{count()}</div>\n        <input\n          ref={(el) => {\n            _i18n(el, 'BoostsViaGifts.AdditionalPrizeLabel', undefined, 'placeholder');\n          }}\n          class=\"input-clear popup-boosts-additional-row-input\"\n          onInput={(e) => {\n            const target = e.target as HTMLInputElement;\n            let value = target.value;\n            const isOverflow = value.length > 128;\n            if(isOverflow) {\n              target.value = value = value.slice(0, 128);\n            }\n\n            setAdditionalPrize(value);\n            if(isOverflow) {\n              shake(target);\n            }\n          }}\n        />\n      </div>\n    );\n\n    const notSpecific2 = (\n      <>\n        <Section\n          caption={additionalPrizes() ? 'BoostsViaGifts.AdditionalPrizesSubtitle' : (stars() ? 'BoostingStarsGiveawayAdditionPrizeHint' : 'BoostsViaGifts.AdditionalPrizesSubtitleOff')}\n          captionArgs={additionalPrizes() ? (stars () ? [\n            i18n(\n              additionalPrize() ? 'BoostsViaGifts.AdditionalStarsPrizesDetailedWith' : 'BoostsViaGifts.AdditionalStarsPrizesDetailed',\n              [starsOption().stars, count(), additionalPrize()].filter(Boolean)\n            )\n          ] : [\n            i18n(\n              additionalPrize() ? 'BoostsViaGifts.AdditionalPrizesDetailedWith' : 'BoostsViaGifts.AdditionalPrizesDetailed',\n              [subscriptionsCount(), additionalPrize(), formatMonthsDuration(option().months, true)].filter(Boolean)\n            )\n          ]) : undefined}\n          captionOld={true}\n        >\n          {new Row({\n            titleLangKey: 'BoostsViaGifts.AdditionalPrizes',\n            clickable: () => {\n              setAdditionalPrizes((value) => !value);\n            },\n            checkboxField: new CheckboxField({\n              toggle: true,\n              checked: untrack(additionalPrizes)\n            }),\n            listenerSetter: this.listenerSetter\n          }).container}\n          {additionalPrizes() && additionalPrizeDiv}\n        </Section>\n        <Section\n          caption=\"BoostsViaGifts.ShowWinnersSubtitle\"\n          captionOld={true}\n        >\n          {new Row({\n            titleLangKey: 'BoostsViaGifts.ShowWinners',\n            clickable: () => {\n              setShowPrizes((value) => !value);\n            },\n            checkboxField: new CheckboxField({\n              toggle: true,\n              checked: untrack(showPrizes)\n            }),\n            listenerSetter: this.listenerSetter\n          }).container}\n        </Section>\n        <Section\n          name=\"BoostsViaGifts.End\"\n          caption={stars() ? 'BoostsViaGifts.Stars.EndSubtitle' : 'BoostsViaGifts.EndSubtitle'}\n          captionArgs={[count()]}\n          captionOld={true}\n        >\n          {expirationRow.container}\n        </Section>\n      </>\n    );\n\n    const ret = (\n      <>\n        <Section noDelimiter={true}>\n          <div class=\"popup-boosts-star-container\"><img class=\"popup-boosts-star\" ref={img} /></div>\n          <div class=\"popup-boosts-title\">{i18n('BoostsViaGifts.Title')}</div>\n          <div class=\"popup-boosts-subtitle\">{i18n(isPrepaid() && this.prepaidGiveaway._ === 'prepaidGiveaway' ? 'BoostingGetMoreBoosts' : 'BoostingGetMoreBoosts2')}</div>\n          {isPrepaid() && prepaidRowContainer}\n          {!isPrepaid() && (\n            <form>\n              {createRowContainer}\n              {starsRowContainer}\n            </form>\n          )}\n        </Section>\n        {!specific() && notSpecific}\n        {!isPrepaid() && !stars() && (\n          <Section\n            name=\"BoostsViaGifts.Duration\"\n            caption=\"BoostsViaGifts.DurationSubtitle\"\n            captionArgs={[premiumPromoAnchor]}\n            captionOld={true}\n          >\n            {durationForm()}\n          </Section>\n        )}\n        {!specific() && notSpecific2}\n      </>\n    );\n\n    renderImageFromUrl(img, `assets/img/premiumboostsstar${window.devicePixelRatio > 1 ? '@2x' : ''}.png`);\n\n    BoostsConfirmButton({\n      button: this.btnConfirm,\n      langKey: () => 'BoostsViaGifts.Start',\n      boosts\n    });\n    this.footer.append(this.btnConfirm);\n    this.body.after(this.footer);\n    this.footer.classList.add('abitlarger');\n\n    const createGiveawayStoreInput = async(): Promise<InputStorePaymentPurpose> => {\n      const peers = await Promise.all(peerIds().map((peerId) => this.managers.appPeersManager.getInputPeerById(peerId)));\n\n      const common = {\n        pFlags: {\n          only_new_subscribers: onlyNewSubscribers() || undefined,\n          winners_are_visible: showPrizes() || undefined\n        },\n        boost_peer: peers[0],\n        random_id: randomLong(),\n        until_date: expiration(),\n        additional_peers: peers.length > 1 ? peers.slice(1) : undefined,\n        countries_iso2: countries()?.length ? countries() : undefined,\n        prize_description: (additionalPrizes() && additionalPrize()) || undefined\n      };\n\n      if(stars()) {\n        return {\n          ...starsOption(),\n          ...common,\n          _: 'inputStorePaymentStarsGiveaway',\n          users: starsWinner().users\n        };\n      }\n\n      return {\n        ...option(),\n        ...common,\n        _: 'inputStorePaymentPremiumGiveaway'\n      };\n    };\n\n    const createSpecificStoreInput = async(): Promise<InputStorePaymentPurpose> => {\n      const {amount, currency} = option();\n      const users = await Promise.all(specificPeerIds().map((peerId) => this.managers.appUsersManager.getUserInput(peerId.toUserId())));\n      return {\n        _: 'inputStorePaymentPremiumGiftCode',\n        amount,\n        currency,\n        boost_peer: await this.managers.appPeersManager.getInputPeerById(this.peerId),\n        users\n      };\n    };\n\n    const continueWithPrepaid = async(purpose: InputStorePaymentPurpose) => {\n      await confirmationPopup({\n        titleLangKey: 'BoostingStartGiveawayConfirmTitle',\n        descriptionLangKey: 'BoostingStartGiveawayConfirmText',\n        button: {langKey: 'Start'}\n      });\n\n      return this.managers.appPaymentsManager.launchPrepaidGiveaway(\n        this.peerId,\n        this.prepaidGiveaway.id,\n        purpose\n      );\n    };\n\n    const continueWithCreating = async(purpose: InputStorePaymentPurpose) => {\n      const inputInvoice: InputInvoice = purpose._ === 'inputStorePaymentStarsGiveaway' ? {\n        _: 'inputInvoiceStars',\n        purpose\n      } : {\n        _: 'inputInvoicePremiumGiftCode',\n        purpose,\n        option: option()\n      };\n\n      const popup = await PopupPayment.create({inputInvoice});\n      await new Promise<void>((resolve, reject) => {\n        popup.addEventListener('finish', (result) => {\n          if(result === 'cancelled' || result === 'failed') {\n            reject();\n          } else {\n            resolve();\n          }\n        });\n      });\n    };\n\n    attachClickEvent(this.btnConfirm, async() => {\n      const toggle = toggleDisability(this.btnConfirm, true);\n\n      if(!specific()) {\n        const now = tsNow(true);\n        const periodMax = this.appConfig.giveaway_period_max ?? 604800;\n        if(!isGiveawayUntilDateValid(expiration(), now, periodMax)) {\n          toggle();\n          toastNew({langPackKey: 'BoostsViaGifts.InvalidEndDate'});\n          shake(expirationRow.container);\n          return;\n        }\n      }\n\n      try {\n        const purpose = await (specific() ? createSpecificStoreInput : createGiveawayStoreInput)();\n        let promise: Promise<any>;\n        if(isPrepaid()) {\n          promise = continueWithPrepaid(purpose);\n        } else {\n          promise = continueWithCreating(purpose);\n        }\n\n        await promise;\n\n        this.onCreated?.();\n        this.hide();\n      } catch(err) {\n        console.error('boosts via gifts error', err);\n        toggle();\n      }\n    }, {listenerSetter: this.listenerSetter});\n\n    return ret;\n  }\n\n  private async construct() {\n    const [giftCodeOptions, appConfig, starsOptions] = await Promise.all([\n      this.managers.appPaymentsManager.getPremiumGiftCodeOptions(this.peerId),\n      this.managers.apiManager.getAppConfig(),\n      this.managers.appPaymentsManager.getStarsGiveawayOptions()\n    ]);\n    this.premiumGiftCodeOptions = giftCodeOptions;\n    this.appConfig = appConfig;\n    this.starsOptions = starsOptions;\n    this.subscribersLimit = this.channelsLimit = appConfig.giveaway_add_peers_max ?? 10;\n    this.countriesLimit = appConfig.giveaway_countries_max ?? 10;\n    this.appendSolid(() => this._construct());\n    this.show();\n  }\n}\n","import {Accessor, For, JSX, createEffect, createMemo, createRoot, createSignal, onCleanup, untrack} from 'solid-js';\nimport {formatFullSentTime} from '@helpers/date';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {MyBoost, PremiumMyBoosts} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {i18n} from '@lib/langPack';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {BoostsConfirmButton} from '@components/popups/boostsViaGifts';\nimport PopupPeer from '@components/popups/peer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {AvatarNew} from '@components/avatarNew';\nimport classNames from '@helpers/string/classNames';\nimport filterUnique from '@helpers/array/filterUnique';\nimport {resolveElements} from '@solid-primitives/refs';\nimport liteMode from '@helpers/liteMode';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {hideToast, toastNew} from '@components/toast';\nimport tsNow from '@helpers/tsNow';\nimport {wrapLeftDuration} from '@components/wrappers/wrapDuration';\nimport {IconTsx} from '@components/iconTsx';\nimport {createListTransition} from '@vendor/createListTransition';\n\nconst className = 'popup-boost';\n\nexport default class PopupReassignBoost extends PopupPeer {\n  private selector: AppSelectPeers;\n\n  constructor(\n    private peerId: PeerId,\n    private myBoosts: PremiumMyBoosts,\n    private appConfig: MTAppConfig\n  ) {\n    super('popup-forward popup-chatlist-invite ' + className, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      description: true,\n      footer: true,\n      withConfirm: true\n    });\n\n    this.btnClose.remove();\n    this.header.remove();\n\n    createRoot((dispose) => {\n      this.middlewareHelper.get().onDestroy(dispose);\n      this.construct();\n    });\n  }\n\n  private async construct() {\n    const [selected, setSelected] = createSignal<MyBoost[]>([]);\n    const [count, setCount] = createSignal(0);\n    const map = new Map<string, MyBoost>();\n\n    const Avatars = () => {\n      const createAvatar = (props: {\n        peerId: PeerId,\n        right?: boolean\n      }) => {\n        const avatar = untrack(() => {\n          return AvatarNew({\n            peerId: props.peerId,\n            size: 60\n          });\n        });\n\n        avatar.node.classList.add(`${className}-avatars-avatar`);\n        avatar.node.append();\n        return avatar;\n      };\n\n      const avatar = createAvatar({peerId: this.peerId, right: true});\n      const peerIds = createMemo<PeerId[]>((previous) => {\n        const previosIndexes: Map<PeerId, number> = new Map();\n        previous?.forEach((peerId, index) => {\n          previosIndexes.set(peerId, index);\n        });\n        const current = filterUnique(selected().map((myBoost) => getPeerId(myBoost.peer)).reverse());\n        current.sort((a, b) => (previosIndexes.get(a) ?? 0) - (previosIndexes.get(b) ?? 0));\n        return current;\n      });\n\n      const offset = 26;\n\n      const realList = (\n        <For each={peerIds()}>{(peerId, index) => {\n          const {element} = createAvatar({peerId});\n          const diff = createMemo(() => peerIds().length - index() - 1);\n          return (\n            <div\n              class={`${className}-avatars-avatar-container`}\n              style={`--offset: ${diff() * -offset}px`}\n            >\n              {element}\n              <IconTsx icon=\"boostcircle\" class={classNames(`${className}-avatars-avatar-icon`, !diff() && 'is-visible')} />\n            </div>\n          );\n        }}</For>\n      );\n\n      const transitionList = createListTransition(resolveElements(() => realList).toArray, {\n        exitMethod: 'keep-index',\n        onChange: ({added, removed, finishRemoved}) => {\n          const options: KeyframeAnimationOptions = {duration: liteMode.isAvailable('animations') ? 200 : 0/* , fill: 'forwards' */, easing: 'ease-in-out'};\n          const keyframes: Keyframe[] = [{transform: 'translateX(var(--offset)) scale(0)'}, {transform: 'translateX(var(--offset)) scale(1)'}];\n          queueMicrotask(() => {\n            for(const element of added) {\n              element.animate(keyframes, options);\n            }\n\n            const reversedKeyframes = keyframes.slice().reverse();\n            const promises: Promise<any>[] = [];\n            for(const element of removed) {\n              const animation = element.animate(reversedKeyframes, options);\n              promises.push(animation.finished);\n            }\n\n            Promise.all(promises).then(() => finishRemoved(removed));\n          });\n        }\n      }) as unknown as JSX.Element;\n\n      return (\n        <div\n          class={classNames(`${className}-avatars`, peerIds().length && 'has-left')}\n          style={`transform: translateX(${Math.max(0, peerIds().length - 1) * (offset / 2)}px)`}\n        >\n          <div class={`${className}-avatars-left`}>\n            {transitionList}\n          </div>\n          <IconTsx icon=\"next\" class={`${className}-avatars-arrow`} />\n          <div class={`${className}-avatars-right`}>\n            {avatar.element}\n          </div>\n        </div>\n      );\n    };\n\n    this.description.before(\n      Avatars() as HTMLElement,\n      (<div class={`${className}-title`}>{i18n('Boost.Replace')}</div>) as HTMLElement\n    );\n\n    const leftTimes = new Map<string, Accessor<number>>();\n\n    this.selector = new AppSelectPeers({\n      middleware: this.middlewareHelper.get(),\n      appendTo: this.body,\n      onChange: (length) => {\n        setSelected(this.selector.getSelected().map((key) => map.get(key as any as string)));\n        setCount(length);\n      },\n      onFirstRender: () => {\n        this.show();\n      },\n      multiSelect: true,\n      noSearch: true,\n      sectionNameLangPackKey: 'BoostingRemoveBoostFrom',\n      avatarSize: 'abitbigger',\n      managers: this.managers,\n      peerType: [],\n      getSubtitleForElement: (key) => {\n        const myBoost = map.get(key as any as string);\n        return createRoot((dispose) => {\n          this.middlewareHelper.get().onDestroy(() => {\n            dispose();\n            clearInterval(interval);\n          });\n\n          const expirationSpan = i18n('BoostsExpiration', [1, formatFullSentTime(myBoost.expires, undefined, true)]);\n\n          const [timestamp, setTimestamp] = createSignal(tsNow(true));\n          const leftTime = createMemo<number>((prev) => {\n            const left = Math.max(0, (myBoost.cooldown_until_date || 0) - timestamp());\n            if(!left && prev !== undefined) {\n              clearInterval(interval);\n            }\n\n            return left;\n          });\n\n          leftTimes.set(key as any as string, leftTime);\n\n          const interval: number = leftTime() ? window.setInterval(() => {\n            setTimestamp(tsNow(true));\n          }, 1e3) : undefined;\n\n          return (\n            <span>\n              {leftTime() ? i18n('BoostingAvailableIn', [wrapLeftDuration(leftTime())]) : expirationSpan}\n            </span>\n          );\n        }) as HTMLElement;\n      },\n      getPeerIdFromKey: (key) => (key as any as string).split('_')[1].toPeerId(),\n      processElementAfter: (key, dialogElement) => {\n        const leftTime = leftTimes.get(key as any as string);\n        createRoot((dispose) => {\n          this.middlewareHelper.get().onDestroy(dispose);\n          createEffect(() => {\n            dialogElement.container.classList.toggle('is-unavailable', !!leftTime());\n          });\n        });\n      }\n    });\n\n    const _add = this.selector.add.bind(this.selector);\n    this.selector.add = (...args) => {\n      const element = this.selector.getElementByKey(args[0].key as any);\n      if(element.classList.contains('is-unavailable')) {\n        toastNew({\n          langPackKey: 'Boost.Reassign.Wait',\n          langPackArguments: [\n            i18n('MoreBoosts', [this.appConfig.boosts_per_sent_gift ?? 1]),\n            anchorCallback(() => {\n              hideToast();\n              this.hideWithCallback(() => {\n                appImManager.initGifting();\n              });\n            })\n          ]\n        });\n        return false;\n      }\n\n      return _add(...args);\n    };\n\n    const keys = this.myBoosts.my_boosts.map((myBoost) => {\n      const peerId = getPeerId(myBoost.peer);\n      if(peerId === this.peerId) {\n        return;\n      }\n\n      const key = 'S' + myBoost.slot + '_' + peerId;\n      map.set(key, myBoost);\n      return key;\n    }).filter(Boolean);\n    this.scrollable = this.selector.scrollable;\n    this.attachScrollableListeners();\n    this.selector.renderResultsFunc(keys as any as number[]);\n\n    let processing = false;\n    const onClick = async(e: MouseEvent) => {\n      cancelEvent(e);\n      processing = true;\n      const toggle = toggleDisability(this.btnConfirm, true);\n      try {\n        const slots = selected().map((myBoost) => myBoost.slot);\n        const uniquePeers = filterUnique(selected().map((myBoost) => getPeerId(myBoost.peer)));\n        await this.managers.appBoostsManager.applyBoost(this.peerId, slots);\n        this.hide();\n        toastNew({\n          langPackKey: 'BoostingReassignedFromPlural',\n          langPackArguments: [slots.length, i18n('BoostingFromOtherChannel', [uniquePeers.length])]\n        });\n      } catch(err) {\n        console.error('error replacing boosts', err);\n        toggle();\n      }\n      processing = false;\n    };\n\n    attachClickEvent(this.btnConfirm, onClick, {listenerSetter: this.listenerSetter});\n\n    BoostsConfirmButton({\n      button: this.btnConfirm,\n      langKey: () => 'Boost.Reassign',\n      langArgs: () => [count() || 1],\n      boosts: count\n    });\n\n    createEffect(() => {\n      if(processing) {\n        return;\n      }\n\n      toggleDisability(this.btnConfirm, !count());\n    });\n\n    this.description.append(\n      i18n(\n        'Boost.Reassign.Description',\n        [\n          await wrapPeerTitle({peerId: this.peerId}),\n          i18n(\n            'Boost.GiftPremium',\n            [\n              anchorCallback(() => {\n                this.hideWithCallback(() => {\n                  appImManager.initGifting();\n                });\n              })\n            ]\n          ),\n          i18n('Boost.Additional', [this.appConfig.boosts_per_sent_gift ?? 1])\n        ]\n      )\n    );\n\n    this.footer.append(this.btnConfirm);\n    this.body.after(this.footer);\n  }\n}\n","import PopupElement, {addCancelButton} from '.';\nimport createBadge from '@helpers/createBadge';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport formatDuration from '@helpers/formatDuration';\nimport {PremiumBoostsStatus} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {i18n} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport confirmationPopup from '@components/confirmationPopup';\nimport LimitLine from '@components/limit';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport PopupPeer from '@components/popups/peer';\nimport PopupPremium from '@components/popups/premium';\nimport PopupReassignBoost from '@components/popups/reassignBoost';\nimport {toastNew} from '@components/toast';\n\nconst className = 'popup-boost';\n\nexport default class PopupBoost extends PopupPeer {\n  constructor(\n    private peerId: PeerId\n  ) {\n    super(className, {\n      closable: true,\n      overlayClosable: true,\n      description: true,\n      old: true\n    });\n\n    this.btnClose.remove();\n    this.header.remove();\n\n    this.construct();\n  }\n\n  private async construct() {\n    let [boostsStatus, myBoosts, appConfig, isPremiumPurchaseBlocked, isBroadcast] = await Promise.all([\n      this.managers.appBoostsManager.getBoostsStatus(this.peerId).catch(() => undefined as PremiumBoostsStatus),\n      this.managers.appBoostsManager.getMyBoosts(),\n      this.managers.apiManager.getAppConfig(),\n      apiManagerProxy.isPremiumPurchaseBlocked(),\n      this.managers.appPeersManager.isBroadcast(this.peerId)\n    ]);\n\n    if(!boostsStatus) {\n      toastNew({langPackKey: 'CantBoostChat'});\n      this.hide();\n      return;\n    }\n\n    const entity = AppSelectPeers.renderEntity({\n      key: this.peerId,\n      middleware: this.middlewareHelper.get(),\n      avatarSize: 30\n    });\n\n    entity.element.classList.add(`${className}-entity`, 'selector-user-alone', 'hover-primary');\n\n    const entityBoosts = createBadge('span', 20, 'premium');\n    entityBoosts.classList.add(`${className}-entity-badge`);\n    entity.element.append(entityBoosts);\n\n    attachClickEvent(entity.element, () => {\n      this.hideWithCallback(() => {\n        appImManager.setInnerPeer({peerId: this.peerId});\n      });\n    }, {listenerSetter: this.listenerSetter});\n\n    const title = document.createElement('div');\n    title.classList.add(`${className}-title`);\n\n    const descriptionPeerTitle = await wrapPeerTitle({peerId: this.peerId});\n    await entity.avatar.readyThumbPromise;\n\n    let hasStories: boolean,\n      needBoostsForNextLevel: number,\n      isMaxLevel: boolean,\n      hasMyBoost: boolean,\n      updated = false;\n\n    const setBoostsStatus = (_boostsStatus: PremiumBoostsStatus) => {\n      boostsStatus = _boostsStatus;\n      hasStories = boostsStatus.level > 0 || boostsStatus.next_level_boosts === boostsStatus.boosts;\n      needBoostsForNextLevel = boostsStatus.next_level_boosts - boostsStatus.boosts;\n      isMaxLevel = boostsStatus.next_level_boosts === undefined;\n      hasMyBoost = !!boostsStatus.pFlags.my_boost;\n    };\n\n    const setTitle = () => {\n      if(hasMyBoost) {\n        title.replaceChildren(i18n(isBroadcast ? 'YouBoostedChannel' : 'YouBoostedGroup'));\n      } else if(isMaxLevel) {\n        title.replaceChildren(i18n('BoostsMaxLevelReached'));\n      } else if(hasStories) {\n        title.replaceChildren(i18n(isBroadcast ? 'HelpUpgradeChannel' : 'HelpUpgradeGroup'));\n      } else {\n        title.replaceChildren(i18n('Boost.EnableStoriesFor'));\n      }\n    };\n\n    const setDescription = () => {\n      if(updated && boostsStatus.level === 0 && hasStories) {\n        this.description.replaceChildren(\n          i18n(\n            isBroadcast ? 'Boost.DescriptionJustReachedLevel1' : 'Boost.DescriptionJustReachedLevel1.Group'\n          )\n        );\n      } else if(isMaxLevel || (updated && boostsStatus.level > 0)) {\n        this.description.replaceChildren(\n          i18n(\n            isBroadcast ? 'Boost.DescriptionJustReachedLevel' : 'Boost.DescriptionJustReachedLevel.Group',\n            [\n              boostsStatus.level,\n              i18n('Boost.StoriesCount', [boostsStatus.level + 1])\n            ]\n          )\n        );\n      } else if(hasStories) {\n        this.description.replaceChildren(\n          i18n(\n            'ChannelNeedBoostsDescriptionForNewFeatures',\n            [\n              descriptionPeerTitle,\n              i18n('MoreBoosts', [needBoostsForNextLevel])\n            ]\n          )\n        );\n      } else {\n        this.description.replaceChildren(\n          i18n(\n            isBroadcast ? 'ChannelNeedBoostsDescriptionLevel1' : 'GroupNeedBoostsDescriptionLevel1',\n            [\n              i18n('MoreBoosts', [needBoostsForNextLevel])\n            ]\n          )\n        );\n      }\n    };\n\n    const limitLine = new LimitLine({\n      progress: true,\n      hint: {\n        icon: 'boost',\n        noStartEnd: true\n      }\n    });\n    this.description.before(limitLine.container, title, entity.element);\n\n    const getGivenBoosts = () => {\n      return myBoosts.my_boosts.filter((myBoost) => getPeerId(myBoost.peer) === this.peerId);\n    };\n\n    const setInfo = () => {\n      const progress = isMaxLevel ?\n        1 :\n        (boostsStatus.boosts - boostsStatus.current_level_boosts) / (boostsStatus.next_level_boosts - boostsStatus.current_level_boosts);\n\n      limitLine.setProgress(\n        progress,\n        '' + boostsStatus.boosts,\n        {\n          from1: i18n('BoostsLevel', [boostsStatus.level]),\n          to1: i18n('BoostsLevel', [boostsStatus.level + 1]),\n          from2: i18n('BoostsLevel', [boostsStatus.level]),\n          to2: i18n('BoostsLevel', [boostsStatus.level + 1])\n        }\n      );\n      setTitle();\n      setDescription();\n      setButtons();\n      entityBoosts.textContent = `x${getGivenBoosts().length}`;\n      entityBoosts.classList.toggle('is-badge-empty', !hasMyBoost);\n    };\n\n    const setButtons = () => {\n      this.setButtons(addCancelButton([isMaxLevel || (getGivenBoosts().length === myBoosts.my_boosts.length && isPremiumPurchaseBlocked) ? {\n        langKey: 'OK',\n        isCancel: true\n      } : {\n        langKey: isBroadcast ? 'BoostChannel' : 'BoostGroup',\n        iconLeft: 'boost',\n        callback: onClick\n      }]));\n    };\n\n    const handleErrorType = (type: ErrorType) => {\n      if(type === 'PREMIUM_ACCOUNT_REQUIRED') {\n        showPremiumNeeded();\n      }/*  else if(type === 'BOOST_NOT_MODIFIED') {\n        showAlreadyBoosting();\n      } */ else if(type.includes('FLOOD_WAIT')) {\n        const wait = +type.split('_')[2];\n        confirmationPopup({\n          titleLangKey: 'CantBoostTooOften',\n          descriptionLangKey: 'CantBoostTooOftenDescription',\n          descriptionLangArgs: [wrapFormattedDuration(formatDuration(wait, 2), false)],\n          button: {\n            langKey: 'OK',\n            isCancel: true\n          }\n        });\n      } else if(type === 'PREMIUM_GIFTED_NOT_ALLOWED') {\n        confirmationPopup({\n          titleLangKey: 'CantBoostWithGiftedPremium',\n          descriptionLangKey: 'CantBoostWithGiftedPremiumDescription',\n          button: {\n            langKey: 'OK',\n            isCancel: true\n          }\n        });\n      }\n    };\n\n    const showPremiumNeeded = () => {\n      confirmationPopup({\n        titleLangKey: 'PremiumNeeded',\n        descriptionLangKey: 'PremiumNeededForBoosting',\n        button: {\n          langKey: 'Yes'\n        }\n      }).then(() => {\n        PopupPremium.show();\n      });\n    };\n\n    // const showAlreadyBoosting = () => {\n    //   confirmationPopup({\n    //     titleLangKey: 'Boost.Already',\n    //     descriptionLangKey: 'Boost.AlreadyDescription',\n    //     button: {\n    //       langKey: 'OK',\n    //       isCancel: true\n    //     }\n    //   });\n    // };\n\n    const onClick = async(e: MouseEvent) => {\n      cancelEvent(e);\n      try {\n        const givenBoosts = getGivenBoosts();\n        const availableBoost = myBoosts.my_boosts.find((myBoost) => !myBoost.peer);\n        let type: ApiError['type'];\n        if(!rootScope.premium) {\n          type = 'PREMIUM_ACCOUNT_REQUIRED';\n        } else if(givenBoosts.length === myBoosts.my_boosts.length) {\n          await confirmationPopup({\n            titleLangKey: 'BoostingMoreBoostsNeeded',\n            descriptionLangKey: 'Boost.GetMoreBoosts',\n            descriptionLangArgs: [\n              await wrapPeerTitle({peerId: this.peerId}),\n              appConfig.boosts_per_sent_gift ?? 1\n            ],\n            button: {\n              langKey: 'GiftPremium'\n            }\n          });\n\n          this.hideWithCallback(() => {\n            appImManager.initGifting();\n          });\n          return;\n        } else if(!availableBoost) {\n          this.hide();\n          PopupElement.createPopup(PopupReassignBoost, this.peerId, myBoosts, appConfig);\n          return;\n        }/*  else if(hasMyBoost) {\n          type = 'BOOST_NOT_MODIFIED';\n        } */\n\n        if(type) {\n          throw {type};\n        }\n\n        // const slots = [...givenBoosts, availableBoost].filter(Boolean).map((myBoost) => myBoost.slot);\n        await this.managers.appBoostsManager.applyBoost(\n          this.peerId,\n          [availableBoost.slot]\n        );\n\n        [myBoosts, boostsStatus] = await Promise.all([\n          this.managers.appBoostsManager.getMyBoosts(),\n          this.managers.appBoostsManager.getBoostsStatus(this.peerId)\n        ]);\n\n        updated = true;\n        setBoostsStatus(boostsStatus);\n        setInfo();\n      } catch(err) {\n        handleErrorType((err as ApiError).type);\n      }\n\n      return false;\n    };\n\n    setBoostsStatus(boostsStatus);\n    setInfo();\n    limitLine._setHintActive();\n\n    this.show();\n  }\n}\n","import PopupElement from '.';\nimport {StarGift} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport rootScope from '@lib/rootScope';\nimport {toastNew} from '@components/toast';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport safeAssign from '@helpers/object/safeAssign';\n\nimport styles from '@components/popups/starGiftWear.module.scss';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport Row from '@components/rowTsx';\nimport PopupPremium from '@components/popups/premium';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport classNames from '@helpers/string/classNames';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport PopupBoost from './boost';\n\nexport default class PopupStarGiftWear extends PopupElement {\n  private gift: MyStarGift;\n  private peerId: PeerId;\n\n  constructor(options: {\n    gift: MyStarGift,\n    peerId?: PeerId\n  }) {\n    super(styles.popup, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      footer: true,\n      withConfirm: 'StarGiftWearStart',\n      withFooterConfirm: true\n    });\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  private _construct() {\n    const {collectibleAttributes} = this.gift;\n    const gift = this.gift.raw as StarGift.starGiftUnique;\n\n    return (\n      <div class={/* @once */ styles.container}>\n        <div class={/* @once */ classNames(styles.header, 'profile-container need-white is-collapsed')}>\n          {gift._ === 'starGiftUnique' && (\n            <StarGiftBackdrop\n              class={/* @once */ styles.backdrop}\n              backdrop={collectibleAttributes.backdrop}\n              patternEmoji={collectibleAttributes.pattern.document as MyDocument}\n            />\n          )}\n          <ButtonIconTsx\n            class={/* @once */ styles.close}\n            icon=\"close\"\n            onClick={() => this.hide()}\n          />\n\n          <AvatarNewTsx\n            class={/* @once */ styles.avatar}\n            peerId={this.peerId}\n            size={120}\n          />\n\n          <div class=\"profile-avatars-info\">\n            <div class=\"profile-name\">\n              <PeerTitleTsx peerId={this.peerId} withIcons />\n              <StickerTsx\n                class=\"emoji-status\"\n                sticker={this.gift.sticker}\n                width={24}\n                height={24}\n                extraOptions={{play: true, loop: false}}\n              />\n            </div>\n            <div class=\"profile-subtitle\">\n              <span class=\"online\"><I18nTsx key=\"Online\" /></span>\n            </div>\n          </div>\n        </div>\n\n        <div class={/* @once */ styles.body}>\n          <I18nTsx\n            class={/* @once */ styles.title}\n            key=\"StarGiftWearTitle\"\n            args={[getCollectibleName(gift)]}\n          />\n          <I18nTsx class={/* @once */ styles.subtitle} key=\"StarGiftWearSubtitle\" />\n          <Row>\n            <Row.Icon icon=\"menu_feature_unique\" />\n            <Row.Title>\n              <I18nTsx key=\"StarGiftWearBenefit1Title\" />\n            </Row.Title>\n            <Row.Subtitle>\n              <I18nTsx key=\"StarGiftWearBenefit1Text\" />\n            </Row.Subtitle>\n          </Row>\n          <Row>\n            <Row.Icon icon=\"menu_feature_cover\" />\n            <Row.Title>\n              <I18nTsx key=\"StarGiftWearBenefit2Title\" />\n            </Row.Title>\n            <Row.Subtitle>\n              <I18nTsx key=\"StarGiftWearBenefit2Text\" />\n            </Row.Subtitle>\n          </Row>\n          <Row>\n            <Row.Icon icon=\"menu_verification\" />\n            <Row.Title>\n              <I18nTsx key=\"StarGiftWearBenefit3Title\" />\n            </Row.Title>\n            <Row.Subtitle>\n              <I18nTsx key=\"StarGiftWearBenefit3Text\" />\n            </Row.Subtitle>\n          </Row>\n        </div>\n      </div>\n    );\n  }\n\n  private async construct() {\n    this.peerId ||= rootScope.myId;\n    this.header.remove();\n    this.appendSolid(() => this._construct());\n\n    attachClickEvent(this.btnConfirm, async() => {\n      const promise = this.peerId === rootScope.myId ?\n        rootScope.managers.appUsersManager.updateEmojiStatus({\n          _: 'inputEmojiStatusCollectible',\n          collectible_id: this.gift.raw.id\n        }) :\n        rootScope.managers.apiManager.invokeApiSingleProcess({\n          method: 'channels.updateEmojiStatus',\n          params: {\n            channel: await rootScope.managers.appChatsManager.getChannelInput(this.peerId.toChatId()),\n            emoji_status: {\n              _: 'inputEmojiStatusCollectible',\n              collectible_id: this.gift.raw.id\n            }\n          }\n        }).then((updates) => {\n          rootScope.managers.apiUpdatesManager.processUpdateMessage(updates);\n        });\n\n      promise.then(() => {\n        this.hide();\n      }).catch((err: ApiError) => {\n        if(err.type === 'BOOSTS_REQUIRED') {\n          PopupElement.createPopup(PopupBoost, this.peerId);\n          return\n        }\n        toastNew({langPackKey: 'Error.AnError'});\n      });\n    });\n  }\n\n  static open(gift: MyStarGift, peerId?: PeerId) {\n    if(!rootScope.premium) {\n      PopupElement.createPopup(PopupPremium);\n      return false\n    }\n\n    PopupElement.createPopup(PopupStarGiftWear, {gift, peerId}).show();\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport Icon from '@components/icon';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport appImManager from '@lib/appImManager';\n\nconst hideQuizHint = (element: HTMLElement, onHide: () => void, timeout: number) => {\n  element.classList.remove('active');\n\n  clearTimeout(timeout);\n  setTimeout(() => {\n    onHide?.();\n    element.remove();\n\n    if(prevQuizHint === element && prevQuizHintOnHide === onHide && prevQuizHintTimeout === timeout) {\n      prevQuizHint = prevQuizHintOnHide = null;\n      prevQuizHintTimeout = 0;\n    }\n  }, 200);\n};\n\nlet prevQuizHint: HTMLElement, prevQuizHintOnHide: () => void, prevQuizHintTimeout: number;\nlet isListenerSet = false;\nexport const setQuizHint = (options: {\n  textElement: HTMLElement | DocumentFragment,\n  textRight?: HTMLElement | DocumentFragment,\n  title?: HTMLElement,\n  onHide?: () => void,\n  appendTo: HTMLElement,\n  from: 'top' | 'bottom',\n  duration?: number,\n  icon?: Icon,\n  class?: string,\n  canCloseOnPeerChange?: boolean\n}) => {\n  if(prevQuizHint) {\n    hideQuizHint(prevQuizHint, prevQuizHintOnHide, prevQuizHintTimeout);\n  }\n\n  const element = document.createElement('div');\n  element.classList.add('quiz-hint', 'from-' + options.from);\n  options.class && element.classList.add(options.class);\n\n  const container = document.createElement('div');\n  container.classList.add('quiz-hint-container');\n\n  let titleEl: HTMLElement;\n  if(options.title) {\n    titleEl = document.createElement('div');\n    titleEl.classList.add('quiz-hint-title');\n    titleEl.append(options.title);\n    container.classList.add('has-title');\n  }\n\n  const textEl = document.createElement('div');\n  textEl.classList.add('quiz-hint-text');\n\n  let textRightEl: HTMLElement;\n  if(options.textRight) {\n    textRightEl = document.createElement('div');\n    textRightEl.classList.add('quiz-hint-text-right');\n    textRightEl.append(options.textRight);\n    container.classList.add('has-right-text');\n  }\n\n  container.append(...[\n    options.icon && Icon(options.icon, 'quiz-hint-icon'),\n    titleEl,\n    textEl,\n    textRightEl\n  ].filter(Boolean));\n  element.append(container);\n\n  setInnerHTML(textEl, options.textElement);\n  options.appendTo.append(element);\n\n  void element.offsetLeft; // reflow\n  element.classList.add('active');\n\n  const hide = () => {\n    hideQuizHint(element, options.onHide, timeout);\n  };\n\n  prevQuizHint = element;\n  prevQuizHintOnHide = options.onHide;\n  const timeout = prevQuizHintTimeout = options.duration && window.setTimeout(hide, options.duration);\n\n  options.canCloseOnPeerChange ??= true;\n  if(!options.canCloseOnPeerChange)\n    element.dataset.dontCloseOnPeerChange = '1';\n\n  if(!isListenerSet) {\n    isListenerSet = true;\n    appImManager.addEventListener('peer_changed', () => {\n      if(prevQuizHint && prevQuizHint.dataset.dontCloseOnPeerChange !== '1') {\n        hideQuizHint(prevQuizHint, prevQuizHintOnHide, prevQuizHintTimeout);\n      }\n    });\n  }\n\n  return {hide};\n};\n","import getUnsafeRandomInt from '@helpers/number/getUnsafeRandomInt';\n\nexport function randomItem<T>(arr: T[]) {\n  return arr[getUnsafeRandomInt(0, arr.length - 1)];\n}\n\nexport function randomItemExcept<T>(arr: T[], except: T) {\n  const idx = arr.indexOf(except);\n  if(idx === -1) return randomItem(arr);\n\n  let num = getUnsafeRandomInt(0, arr.length - 1);\n  if(num === idx) {\n    num = idx + (Math.random() < 0.5 ? -1 : 1)\n    if(num < 0) num = arr.length - 1;\n    else if(num >= arr.length) num = 0;\n  }\n\n  return arr[num];\n}\n","import {createEffect, createSignal, JSX, on, onMount, Show} from 'solid-js'\nimport {IconTsx} from '@components/iconTsx'\nimport {doubleRaf} from '@helpers/schedulers'\nimport liteMode from '@helpers/liteMode'\nimport {animateSingle} from '@helpers/animation'\nimport {easeInOutSineApply} from '@helpers/easing/easeInOutSine'\nimport classNames from '@helpers/string/classNames'\nimport clamp from '@helpers/number/clamp'\nimport styles from '@components/limitLineTsx.module.scss';\nimport RangeSelector from '@components/rangeSelector'\nimport I18n from '@lib/langPack'\nimport {lerp} from '@helpers/lerp'\n\n\nexport function LimitLineTsx(props: {\n  class?: string\n  progress: number\n  reverse?: boolean\n  animateProgress?: boolean\n  progressFrom?: JSX.Element\n  progressTo?: JSX.Element\n  progressClass?: string\n  progressFilledClass?: string\n  onScrub?: (progress: number) => void\n  filledProgressElement?: HTMLElement\n  hint?: JSX.Element\n  hintIcon?: Icon\n  hintJustIcon?: boolean\n}) {\n  const [progress, setProgress] = createSignal(props.progress)\n  const [hintActive, setHintActive] = createSignal(false)\n\n  let containerRef!: HTMLDivElement\n  let hintRef!: HTMLDivElement;\n  let tailRef!: HTMLDivElement;\n  let tailContainerRef!: HTMLDivElement;\n\n  const isSlider = props.onScrub !== undefined\n  const isReverse = () => props.reverse ?? I18n.getIsRTL()\n\n  onMount(() => {\n    const resizeObserver = new ResizeObserver(updateHintPosition);\n    resizeObserver.observe(hintRef);\n    doubleRaf().then(() => {\n      setHintActive(true)\n      updateHintPosition()\n    })\n  })\n\n  function updateHintPosition() {\n    const hintWidth = hintRef.clientWidth; // ! not bounding rect so transform is not applied\n    const parentWidth = hintRef.parentElement.getBoundingClientRect().width;\n\n    const progress$ = progress()\n    let sliderTipPosition = progress$ * parentWidth\n    if(isSlider) {\n      // adjust for slider thumb (30 - thumb width + padding)\n      sliderTipPosition += 30 * (1 - progress$) - 15;\n    }\n    if(isReverse()) {\n      sliderTipPosition = parentWidth - sliderTipPosition;\n    }\n\n    // hint position\n    const hintLeft = sliderTipPosition - hintWidth / 2;\n    const hintPadding = isSlider ? 8 : 0;\n    const minHintLeft = hintPadding;\n    const maxHintLeft = parentWidth - hintWidth - hintPadding;\n    const hintLeftClamped = clamp(hintLeft, minHintLeft, maxHintLeft);\n    // for the second half align to the right to avoid issues with hidpi rendering\n    if(hintLeftClamped < parentWidth / 2) {\n      hintRef.style.setProperty('--left', hintLeftClamped + 'px');\n      hintRef.style.setProperty('--right', 'auto');\n    } else {\n      hintRef.style.setProperty('--left', 'auto');\n      hintRef.style.setProperty('--right', parentWidth - hintWidth - hintLeftClamped + 'px');\n    }\n\n    // tail position\n    const tailWidth = 46;\n    const halfTailWidth = tailWidth / 2;\n    const extra = 15;\n    const extraHalf = extra / 2;\n    const tailLeft = sliderTipPosition - halfTailWidth;\n    let tailLeft2 = tailLeft;\n    const tailLeftMin = isSlider ? -extra : -halfTailWidth;\n    const tailLeftMax = isSlider ? parentWidth - tailWidth + extra : parentWidth;\n    if(isSlider) {\n      if((tailLeftMax - tailLeft) < extra) {\n        tailLeft2 += lerp(0, extra, 1 - (tailLeftMax - tailLeft) / extra);\n      }\n      if(tailLeft < extraHalf) {\n        tailLeft2 -= lerp(0, extra, 1 - -(-extraHalf - tailLeft) / extra);\n      }\n    }\n\n    const tailLeftClamped = clamp(tailLeft2, tailLeftMin, tailLeftMax);\n    tailContainerRef.style.setProperty('--tail-left', (tailLeftClamped - hintLeftClamped) + 'px');\n    tailRef.style.setProperty('--tail-left-relative', String(clamp((sliderTipPosition - hintLeftClamped) / hintWidth, 0, 1)));\n\n    // tail clip\n    const cutoffStart = isSlider ? 8 : 0;\n    const tailCutoffLeft = tailLeft2 > cutoffStart ? 0 : clamp((Math.abs(tailLeft2 - cutoffStart) / tailWidth) * 100, 0, 50);\n    const tailRight = parentWidth - tailLeft2 - tailWidth;\n    const tailCutoffRight = tailRight > cutoffStart ? 0 : clamp((Math.abs(tailRight - cutoffStart) / tailWidth) * 100, 0, 50);\n    tailContainerRef.style.clipPath = `inset(0 ${tailCutoffRight}% 0 ${tailCutoffLeft}%)`;\n\n    // border rounding\n    const borderRadius = 24;\n    const roundingAt = isSlider ? 20 : 14;\n    const roundingStart = borderRadius - roundingAt;\n    const leftProgress = tailLeft2 < roundingAt ? Math.max(0, (roundingStart + tailLeft2)) / borderRadius : 1;\n    const rightProgress = tailRight < roundingAt ? Math.max(0, (roundingStart + tailRight)) / borderRadius : 1;\n\n    const radiusLeftBottom = leftProgress === 1 ? borderRadius : lerp(0, borderRadius, leftProgress);\n    const radiusRightBottom = rightProgress === 1 ? borderRadius : lerp(0, borderRadius, rightProgress);\n\n    hintRef.style.setProperty('--border-radius', `${borderRadius}px ${borderRadius}px ${radiusRightBottom}px ${radiusLeftBottom}px`);\n  }\n\n  let line: JSX.Element\n  let range: RangeSelector;\n  if(isSlider) {\n    range = new RangeSelector({\n      step: 0.0001,\n      min: 0,\n      max: 1,\n      useProperty: true,\n      offsetAxisValue: 30\n    }, progress());\n    range.setListeners();\n    range.setHandlers({\n      onScrub: props.onScrub\n    });\n    range.container.classList.add(styles.line, styles.slider);\n    line = range.container;\n\n    if(props.filledProgressElement) {\n      onMount(() => {\n        range.container.querySelector('.progress-line__filled').appendChild(props.filledProgressElement);\n      })\n    }\n  } else {\n    line = (\n      <div class={styles.line}>\n        <Show when={props.progressFrom || props.progressTo}>\n          <div class={classNames(styles.linePart, props.progressClass)}>\n            {props.progressFrom}\n            {props.progressTo}\n          </div>\n          <div class={classNames(`${styles.linePart} ${styles.lineFilled}`, props.progressFilledClass)}>\n            {props.progressFrom}\n            {props.progressTo}\n          </div>\n        </Show>\n      </div>\n    )\n  }\n\n  createEffect(on(() => props.progress, (val, prev) => {\n    if(prev !== undefined && liteMode.isAvailable('animations') && !isSlider && props.animateProgress !== false) {\n      const duration = 200;\n      const startTime = performance.now();\n      const diff = val - prev;\n\n      animateSingle(() => {\n        const v = clamp((performance.now() - startTime) / duration, 0, 1);\n        const eased = easeInOutSineApply(v, 1)\n        const value = prev + eased * diff;\n        setProgress(value);\n        updateHintPosition();\n\n        return v < 1;\n      }, containerRef);\n    } else {\n      setProgress(val);\n      updateHintPosition();\n      range?.setProgress(val);\n    }\n  }))\n\n  return (\n    <div\n      class={classNames(\n        styles.container,\n        props.hintJustIcon && styles.justIcon,\n        ('hint' in props || props.hintIcon) && styles.hasHint,\n        isReverse() && styles.reverse,\n        props.class\n      )}\n      style={{'--limit-progress': progress() * 100 + '%'}}\n      ref={containerRef}\n    >\n      <Show when={'hint' in props || props.hintIcon}>\n        <div\n          class={classNames(styles.hint, hintActive() && styles.active)}\n          ref={hintRef}\n        >\n          {props.hintIcon && <IconTsx icon={props.hintIcon} class={styles.hintIcon} />}\n          {props.hint}\n          <div class={styles.hintTailContainer} ref={tailContainerRef}>\n            <div class={styles.hintTail} ref={tailRef} />\n          </div>\n        </div>\n      </Show>\n\n      {line}\n    </div>\n  )\n}\n","export default function easeOutCirc(t: number, b: number, c: number, d: number) {\n  return t >= d ? b + c : easeOutCircApply(t / d, c) + b;\n}\n\nexport function easeOutCircApply(v: number, c: number) {\n  return c * Math.sqrt(1 - --v * v);\n}\n","import {createSignal, onCleanup} from 'solid-js';\nimport tsNow from '@helpers/tsNow';\n\nexport function createCurrentTime(options: {\n  fn?: () => number\n  updateInterval?: number\n  updateWrapper?: (fn: VoidFunction) => void\n} = {}) {\n  const {fn = tsNow, updateInterval = 30000, updateWrapper} = options;\n\n  const [time, setTime] = createSignal(fn());\n  const tick = updateWrapper ? () => {\n    updateWrapper(() => setTime(fn()));\n  } : () => {\n    setTime(fn());\n  }\n  const interval = setInterval(tick, updateInterval);\n\n  onCleanup(() => clearInterval(interval));\n\n  return time;\n}\n","import {createMemo, createSignal, onCleanup, onMount} from 'solid-js';\nimport tsNow from '@helpers/tsNow';\nimport {LimitLineTsx} from '@components/limitLineTsx';\nimport PopupElement, {createPopup} from '@components/popups/indexTsx';\n\nimport styles from '@components/popups/starGiftUpgradePrice.module.scss';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {StarGiftUpgradePreview} from '@appManagers/appGiftsManager';\nimport {easeOutCircApply} from '@helpers/easing/easeOutCirc';\nimport Table from '@components/table';\nimport {formatDate, formatDateAccordingToTodayNew, formatFullSentTime, formatTime} from '@helpers/date';\nimport {StarsStar} from '@components/popups/stars';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport I18n from '@lib/langPack';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport Scrollable from '@components/scrollable2';\nimport {fastRaf} from '@helpers/schedulers';\nimport {createCurrentTime} from '@helpers/solid/createCurrentTime';\n\nexport function createStarGiftUpgradePricePopup(props: {\n  preview: StarGiftUpgradePreview,\n}) {\n  const [show, setShow] = createSignal(false);\n\n  let minPrice = Infinity;\n  let maxPrice = 0;\n  for(const price of props.preview.prices) {\n    const val = Number(price.upgrade_stars);\n    if(val < minPrice) {\n      minPrice = val;\n    }\n    if(val > maxPrice) {\n      maxPrice = val;\n    }\n  }\n\n  const now = createCurrentTime({\n    fn: () => tsNow(true),\n    updateInterval: 1000\n  })\n  const currentPriceNext = createMemo(() => {\n    const now$ = now()\n    for(let i = props.preview.next_prices.length - 1; i >= 0; i--) {\n      if(props.preview.next_prices[i].date <= now$) {\n        return props.preview.next_prices[i];\n      }\n    }\n    return props.preview.next_prices[0];\n  })\n  const progress = () => easeOutCircApply((Number(currentPriceNext().upgrade_stars) - minPrice) / (maxPrice - minPrice), 1);\n\n  const currentPriceIdx = createMemo(() => {\n    const now$ = now()\n    for(let i = props.preview.prices.length - 1; i >= 0; i--) {\n      if(props.preview.prices[i].date <= now$) {\n        return i;\n      }\n    }\n    return 0;\n  })\n  const futurePrices = createMemo(() => props.preview.prices.slice(currentPriceIdx()))\n\n  function formatDateTime(unix: number) {\n    const date = new Date(unix * 1000);\n    return (\n      <>\n        {formatTime(date)}\n        {', '}\n        {new I18n.IntlDateElement({\n          date,\n          options: {\n            month: 'short',\n            day: 'numeric'\n          }\n        }).element}\n      </>\n    )\n  }\n\n  return createPopup(() => {\n    onMount(() => fastRaf(() => setShow(true)))\n    return (\n      <PopupElement class={styles.popup} containerClass={styles.popupContainer} show={show()}>\n        <PopupElement.Header class={styles.popupHeader}>\n          <PopupElement.CloseButton class={styles.popupCloseButton} />\n        </PopupElement.Header>\n        <PopupElement.Body class={styles.popupBody}>\n          <Scrollable>\n            <div class={styles.scrollableContent}>\n              <LimitLineTsx\n                class={styles.limitLine}\n                progress={progress()}\n                progressTo={<I18nTsx key=\"StarsCount\" args={[String(maxPrice)]} />}\n                progressFrom={<I18nTsx key=\"StarsCount\" args={[String(minPrice)]} />}\n                reverse\n                hint={(\n                  <span class={styles.limitLineHint}>\n                    {currentPriceNext().upgrade_stars}\n                  </span>\n                )}\n                hintIcon=\"star\"\n              />\n\n              <I18nTsx key=\"StarGiftUpgradePriceTitle\" class={styles.title} />\n              <I18nTsx key=\"StarGiftUpgradePriceSubtitle\" class={styles.subtitle} />\n\n              <Table\n                class={styles.table}\n                keyCellClass={styles.tableKeyCell}\n                content={futurePrices().map((it) => ([\n                  <span>\n                    {formatDateTime(it.date)}\n                  </span>,\n                  <span class={styles.tableValue}>\n                    <StarsStar />\n                    {numberThousandSplitterForStars(it.upgrade_stars)}\n                  </span>\n                ]))}\n              />\n\n              <I18nTsx key=\"StarGiftUpgradePriceAbout\" class={styles.about} />\n            </div>\n          </Scrollable>\n        </PopupElement.Body>\n\n        <PopupElement.Footer class={styles.popupFooter}>\n          <PopupElement.FooterButton\n            class={styles.popupButton}\n            iconLeft=\"okay\"\n            langKey=\"StarGiftUpgradePriceUnderstood\"\n            callback={() => setShow(false)}\n          />\n        </PopupElement.Footer>\n      </PopupElement>\n    );\n  })\n}\n","import {createEffect, createMemo, createSignal, onCleanup} from 'solid-js';\nimport PopupElement from '@components/popups/indexTsx';\nimport PopupElementOld from '@components/popups/index'\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {StarGiftAttribute} from '@layer';\nimport {randomItemExcept} from '@helpers/array/randomItem';\nimport {i18n} from '@lib/langPack';\nimport {IconTsx} from '@components/iconTsx';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport wrapSticker from '@components/wrappers/sticker';\nimport RLottiePlayer from '@lib/rlottie/rlottiePlayer';\nimport Row from '@components/rowTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport PopupPayment from '@components/popups/payment';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport rootScope from '@lib/rootScope';\nimport {createPopup} from '@components/popups/indexTsx';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport tsNow from '@helpers/tsNow';\nimport {wrapLeftDuration} from '@components/wrappers/wrapDuration';\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport {createStarGiftUpgradePricePopup} from '@components/popups/starGiftUpgradePrice';\nimport PopupStarGiftInfo from '@components/popups/starGiftInfo';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {createCurrentTime} from '@helpers/solid/createCurrentTime';\n\nexport default async function createStarGiftUpgradePopup(props: {\n  gift: MyStarGift,\n  descriptionForPeerId?: PeerId\n}) {\n  const [\n    preview,\n    peerTitle\n  ] = await Promise.all([\n    rootScope.managers.appGiftsManager.getUpgradePreview(props.gift.raw.id),\n    props.descriptionForPeerId ? wrapPeerTitle({peerId: props.descriptionForPeerId}) : undefined\n  ]);\n\n  const [show, setShow] = createSignal(true);\n  let upgradePromise: CancellablePromise<boolean> | undefined\n\n  const freeUpgrade = props.gift.isUpgradedBySender;\n  const canPrepay = props.gift.saved?.prepaid_upgrade_hash !== undefined;\n\n  const keepInfoSignal = createSignal(true);\n\n  const [model, setModel] = createSignal<StarGiftAttribute.starGiftAttributeModel>();\n  const [backdrop, setBackdrop] = createSignal<StarGiftAttribute.starGiftAttributeBackdrop>();\n  const [pattern, setPattern] = createSignal<StarGiftAttribute.starGiftAttributePattern>();\n\n  const randomize = () => {\n    setModel(v => randomItemExcept(preview.models, v));\n    setBackdrop(v => randomItemExcept(preview.backdrops, v));\n    setPattern(v => randomItemExcept(preview.patterns, v));\n  };\n  randomize();\n\n  async function handleUpgrade(): Promise<boolean> {\n    if(props.descriptionForPeerId && canPrepay) {\n      const deferred = deferredPromise<boolean>();\n      PopupPayment.create({\n        inputInvoice: {\n          _: 'inputInvoiceStarGiftPrepaidUpgrade',\n          hash: props.gift.saved?.prepaid_upgrade_hash,\n          peer: await rootScope.managers.appPeersManager.getInputPeerById(props.descriptionForPeerId)\n        },\n        noShowIfStars: true\n      }).then((popup) => {\n        popup.addEventListener('finish', (result) => {\n          deferred.resolve(result === 'paid');\n        });\n      });\n      return deferred;\n    }\n\n    upgradePromise = deferredPromise<boolean>();\n\n    if(freeUpgrade) {\n      await rootScope.managers.appGiftsManager.upgradeStarGift(\n        props.gift.input,\n        keepInfoSignal[0]()\n      );\n      return upgradePromise\n    }\n\n    PopupPayment.create({\n      inputInvoice: {\n        _: 'inputInvoiceStarGiftUpgrade',\n        stargift: props.gift.input,\n        pFlags: {\n          keep_original_details: keepInfoSignal[0]() ? true : undefined\n        }\n      },\n      noShowIfStars: true\n    }).then((popup) => {\n      popup.addEventListener('finish', (result) => {\n        if(result !== 'paid') {\n          upgradePromise.resolve(false);\n        }\n      });\n    });\n\n    return upgradePromise;\n  }\n\n  const now = createCurrentTime({\n    fn: () => tsNow(true),\n    updateInterval: 1000\n  })\n  const [nextPrices, setNextPrices] = createSignal(preview.next_prices)\n\n  const currentPriceIdx = createMemo(() => {\n    const now$ = now()\n    // the array is expected to be sorted by date ascending\n    const nextPrices$ = nextPrices()\n    for(let i = nextPrices$.length - 1; i >= 0; i--) {\n      if(nextPrices$[i].date <= now$) {\n        return i\n      }\n    }\n    return 0\n  })\n\n  const hasFuturePrices = () => currentPriceIdx() < nextPrices().length - 1\n\n  const currentPrice = () => nextPrices()[currentPriceIdx()]\n  const currentPriceRemains = () => {\n    const nextPrice = nextPrices()[currentPriceIdx() + 1]\n    return nextPrice ? nextPrice.date - now() : 0\n  }\n\n  const priceCounter = new AnimatedCounter({\n    reverse: true,\n    duration: 1000\n  })\n  createEffect(() => priceCounter.setCount(Number(currentPrice().upgrade_stars)))\n\n  createPopup(() => {\n    const middleware = createMiddleware()\n\n    createEffect(() => {\n      const model$ = model();\n\n      wrapSticker({\n        doc: model$.document as MyDocument,\n        div: stickerContainer,\n        width: 120,\n        height: 120,\n        play: true,\n        loop: false,\n        middleware: middleware.get()\n      }).then(({render}) => render).then((player_) => {\n        const player = player_ as RLottiePlayer;\n        player.playOrRestart();\n        player.addEventListener('enterFrame', (frameNo) => {\n          if(frameNo === player.maxFrame) {\n            player.stop(false);\n            randomize();\n          }\n        });\n      });\n    });\n\n    subscribeOn(rootScope)('star_gift_upgrade', (event) => {\n      if(!upgradePromise) return;\n      if(!(event.savedId === props.gift.saved?.saved_id || event.fromMsgId === props.gift.saved?.msg_id)) return\n\n      PopupElementOld.createPopup(PopupStarGiftInfo, {\n        gift: event.gift,\n        upgradeAnimation: preview\n      })\n      upgradePromise.resolve(true)\n    })\n\n    let stickerContainer!: HTMLDivElement;\n\n    return (\n      <PopupElement class=\"popup-star-gift-upgrade\" show={show()}>\n        <PopupElement.Body>\n          <div class=\"popup-star-gift-upgrade-container\">\n            <div class=\"popup-star-gift-upgrade-header\">\n              <StarGiftBackdrop\n                class=\"popup-star-gift-upgrade-backdrop\"\n                backdrop={backdrop()}\n                patternEmoji={pattern().document as MyDocument}\n              />\n              <ButtonIconTsx\n                class=\"popup-star-gift-upgrade-close\"\n                icon=\"close\"\n                onClick={() => setShow(false)}\n              />\n              <div\n                class=\"popup-star-gift-upgrade-sticker\"\n                ref={stickerContainer}\n              />\n              <div class=\"popup-star-gift-upgrade-title\">\n                {i18n(props.descriptionForPeerId ? 'StarGiftUpgradeTitleFor' : 'StarGiftUpgradeTitle')}\n              </div>\n              <div class=\"popup-star-gift-upgrade-subtitle\">\n                {i18n(props.descriptionForPeerId ? 'StarGiftUpgradeSubtitleFor' : 'StarGiftUpgradeSubtitle', [peerTitle])}\n              </div>\n            </div>\n            <div class=\"popup-star-gift-upgrade-body\">\n              <div class=\"popup-star-gift-upgrade-feature\">\n                <IconTsx class=\"popup-star-gift-upgrade-feature-icon\" icon=\"gem\" />\n                <div class=\"popup-star-gift-upgrade-feature-body\">\n                  <I18nTsx class=\"popup-star-gift-upgrade-feature-title\" key=\"StarGiftUpgradeUniqueTitle\" />\n                  <I18nTsx\n                    class=\"popup-star-gift-upgrade-feature-text\"\n                    key={props.descriptionForPeerId ? 'StarGiftUpgradeUniqueTextPrepaid' : 'StarGiftUpgradeUniqueText'}\n                    args={props.descriptionForPeerId ? [peerTitle.cloneNode(true)] : []}\n                  />\n                </div>\n              </div>\n              <div class=\"popup-star-gift-upgrade-feature\">\n                <IconTsx class=\"popup-star-gift-upgrade-feature-icon\" icon=\"gem_exchange\" />\n                <div class=\"popup-star-gift-upgrade-feature-body\">\n                  <I18nTsx class=\"popup-star-gift-upgrade-feature-title\" key=\"StarGiftUpgradeTransferableTitle\" />\n                  <I18nTsx\n                    class=\"popup-star-gift-upgrade-feature-text\"\n                    key={props.descriptionForPeerId ? 'StarGiftUpgradeTransferableTextPrepaid' : 'StarGiftUpgradeTransferableText'}\n                    args={props.descriptionForPeerId ? [peerTitle.cloneNode(true)] : []}\n                  />\n                </div>\n              </div>\n              <div class=\"popup-star-gift-upgrade-feature\">\n                <IconTsx class=\"popup-star-gift-upgrade-feature-icon\" icon=\"trade\" />\n                <div class=\"popup-star-gift-upgrade-feature-body\">\n                  <I18nTsx class=\"popup-star-gift-upgrade-feature-title\" key=\"StarGiftUpgradeTradableTitle\" />\n                  <I18nTsx\n                    class=\"popup-star-gift-upgrade-feature-text\"\n                    key={props.descriptionForPeerId ? 'StarGiftUpgradeTradableTextPrepaid' : 'StarGiftUpgradeTradableText'}\n                    args={props.descriptionForPeerId ? [peerTitle.cloneNode(true)] : []}\n                  />\n                </div>\n              </div>\n            </div>\n            {!props.descriptionForPeerId && (\n              <div class=\"popup-star-gift-upgrade-footer\">\n                <Row>\n                  <Row.CheckboxField>\n                    <CheckboxFieldTsx\n                      text=\"StarGiftUpgradeKeepInfo\"\n                      signal={keepInfoSignal}\n                    />\n                  </Row.CheckboxField>\n                </Row>\n              </div>\n            )}\n          </div>\n        </PopupElement.Body>\n        <PopupElement.Footer>\n          {props.descriptionForPeerId && !canPrepay ? (\n            <PopupElement.FooterButton\n              langKey=\"OK\"\n              callback={() => setShow(false)}\n            />\n          ) : (\n            <PopupElement.FooterButton callback={handleUpgrade}>\n              <I18nTsx\n                key={freeUpgrade ? 'StarGiftUpgradeFree' : props.descriptionForPeerId ? 'StarGiftUpgradePrepaid' : 'StarGiftUpgrade'}\n                args={freeUpgrade ? [] : [\n                  <span class=\"popup-star-gift-upgrade-price-wrap\">\n                    <IconTsx icon=\"star\" class=\"currency-star-icon\" />\n                    {priceCounter.container}\n                  </span>\n                ]}\n              />\n              {!freeUpgrade && hasFuturePrices() && (\n                <I18nTsx\n                  class=\"popup-star-gift-upgrade-price-decrease\"\n                  key=\"StarGiftPriceDecrease\"\n                  args={[wrapLeftDuration(currentPriceRemains())]}\n                />\n              )}\n            </PopupElement.FooterButton>\n          )}\n          {hasFuturePrices() && !canPrepay && (\n            <div\n              class=\"popup-star-gift-upgrade-price-decrease-link\"\n              onClick={() => createStarGiftUpgradePricePopup({preview})}\n            >\n              <I18nTsx key=\"StarGiftPriceDecreaseLink\" />\n              <IconTsx icon=\"next\" />\n            </div>\n          )}\n        </PopupElement.Footer>\n      </PopupElement>\n    );\n  })\n}\n","import {Ref, onCleanup} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\nimport styles from '@components/confetti.module.scss';\n\nconst COLORS = [\n  '#FF8724', // orange\n  '#CD89D0', // purple\n  '#1E9AFF', // blue\n  '#56CE6B', // green\n  '#E8BC2C'  // yellow/gold\n];\n\ntype ParticleShape = 'circle' | 'pill';\n\ninterface Particle {\n  x: number;\n  y: number;\n  vx: number;\n  vy: number;\n  color: string;\n  shape: ParticleShape;\n  size: number;\n  rotation: number;\n  rotationSpeed: number;\n  flickerFrequency: number;\n}\n\nconst GRAVITY = 800;\nconst AIR_RESISTANCE = 0.98;\n\nfunction createParticle(\n  x: number,\n  y: number,\n  vx: number,\n  vy: number,\n  size: number\n): Particle {\n  return {\n    x,\n    y,\n    vx,\n    vy,\n    color: COLORS[Math.floor(Math.random() * COLORS.length)],\n    shape: Math.random() > 0.5 ? 'circle' : 'pill',\n    size: size + Math.random() * size,\n    rotation: Math.random() * Math.PI * 2,\n    rotationSpeed: (Math.random() - 0.5) * 0.3,\n    flickerFrequency: 0.05 + Math.random() * 0.1\n  };\n}\n\nfunction drawParticle(\n  ctx: CanvasRenderingContext2D,\n  particle: Particle,\n  frameCount: number\n) {\n  const {x, y, color, shape, size, rotation, flickerFrequency} = particle;\n\n  const opacity = 0.7 + 0.3 * Math.abs(Math.sin(frameCount * flickerFrequency));\n\n  ctx.save();\n  ctx.translate(x, y);\n  ctx.rotate(rotation);\n  ctx.globalAlpha = opacity;\n  ctx.fillStyle = color;\n\n  if(shape === 'circle') {\n    ctx.beginPath();\n    ctx.arc(0, 0, size / 2, 0, Math.PI * 2);\n    ctx.fill();\n  } else {\n    const width = size * 0.5;\n    const height = size * 1.5;\n    const radius = width / 2;\n\n    ctx.beginPath();\n    ctx.moveTo(-width / 2, -height / 2 + radius);\n    ctx.arcTo(-width / 2, -height / 2, 0, -height / 2, radius);\n    ctx.arcTo(width / 2, -height / 2, width / 2, -height / 2 + radius, radius);\n    ctx.lineTo(width / 2, height / 2 - radius);\n    ctx.arcTo(width / 2, height / 2, 0, height / 2, radius);\n    ctx.arcTo(-width / 2, height / 2, -width / 2, height / 2 - radius, radius);\n    ctx.closePath();\n    ctx.fill();\n  }\n\n  ctx.restore();\n}\n\nexport type ConfettiMode = {\n  mode: 'poppers';\n  size?: number;\n  speedScale?: number;\n  count?: number;\n}\n\nexport interface ConfettiRef {\n  canvas: HTMLElement;\n  create(options: ConfettiMode): () => void;\n}\n\nexport function ConfettiContainer(props: {\n  ref: Ref<ConfettiRef>;\n  class?: string;\n  onEnd?: () => void;\n}) {\n  let canvas!: HTMLCanvasElement;\n  let ctx: CanvasRenderingContext2D;\n\n  const particles: Particle[] = [];\n  let frameCount = 0;\n  let lastTime = 0;\n  let animationId: number | null = null;\n  let width = 0;\n  let height = 0;\n  let dpr = 1;\n\n  const resizeCanvas = () => {\n    const rect = canvas.parentElement!.getBoundingClientRect();\n    dpr = window.devicePixelRatio || 1;\n    width = rect.width;\n    height = rect.height;\n    canvas.width = width * dpr;\n    canvas.height = height * dpr;\n    ctx.setTransform(1, 0, 0, 1, 0, 0);\n    ctx.scale(dpr, dpr);\n  };\n\n  const animate = (currentTime: number) => {\n    if(lastTime === 0) lastTime = currentTime;\n    const dt = (currentTime - lastTime) / 1000;\n    lastTime = currentTime;\n    frameCount++;\n\n    ctx.clearRect(0, 0, width, height);\n\n    for(let i = particles.length - 1; i >= 0; i--) {\n      const p = particles[i];\n\n      p.vy += GRAVITY * dt;\n      p.vx *= AIR_RESISTANCE;\n      p.x += p.vx * dt;\n      p.y += p.vy * dt;\n      p.rotation += p.rotationSpeed;\n\n      if(p.y > height + 50) {\n        particles.splice(i, 1);\n        continue;\n      }\n\n      drawParticle(ctx, p, frameCount);\n    }\n\n    if(particles.length > 0) {\n      animationId = requestAnimationFrame(animate);\n    } else {\n      props.onEnd?.();\n      animationId = null;\n    }\n  };\n\n  const startAnimation = () => {\n    if(animationId !== null) return;\n    lastTime = 0;\n    animationId = requestAnimationFrame(animate);\n  };\n\n  const create: ConfettiRef['create'] = (options) => {\n    const {mode} = options;\n\n    resizeCanvas();\n\n    if(mode === 'poppers') {\n      const {size = 6, speedScale = 1, count = 100} = options;\n      const leftSpawnX = -10;\n      const rightSpawnX = width + 10;\n      const spawnY = height / 2;\n      const spawnSpread = 50;\n\n      for(let i = 0; i < count / 2; i++) {\n        // -75deg to -15deg (centered at -45)\n        const leftAngle = -Math.PI / 4 + (Math.random() - 0.5) * Math.PI / 3;\n        const leftSpeed = (500 + Math.random() * 400) * speedScale;\n\n        particles.push(createParticle(\n          leftSpawnX,\n          spawnY + (Math.random() - 0.5) * spawnSpread,\n          Math.cos(leftAngle) * leftSpeed,\n          Math.sin(leftAngle) * leftSpeed,\n          size\n        ));\n\n        // -165deg to -105deg (centered at -135)\n        const rightAngle = -Math.PI * 3 / 4 + (Math.random() - 0.5) * Math.PI / 3;\n        const rightSpeed = (500 + Math.random() * 400) * speedScale;\n\n        particles.push(createParticle(\n          rightSpawnX,\n          spawnY + (Math.random() - 0.5) * spawnSpread,\n          Math.cos(rightAngle) * rightSpeed,\n          Math.sin(rightAngle) * rightSpeed,\n          size\n        ));\n      }\n    }\n\n    startAnimation();\n\n    return () => {\n      particles.length = 0;\n      if(animationId !== null) {\n        cancelAnimationFrame(animationId);\n        animationId = null;\n      }\n      ctx.clearRect(0, 0, width, height);\n    };\n  };\n\n  const setContainerRef = (el: HTMLDivElement) => {\n    (props.ref as any)({\n      canvas: el,\n      create\n    });\n  };\n\n  const setCanvasRef = (el: HTMLCanvasElement) => {\n    canvas = el;\n    ctx = el.getContext('2d')!;\n  };\n\n  onCleanup(() => {\n    if(animationId !== null) {\n      cancelAnimationFrame(animationId);\n    }\n  });\n\n  return (\n    <div\n      ref={setContainerRef}\n      class={classNames(styles.container, props.class)}\n    >\n      <canvas ref={setCanvasRef} class={styles.canvas} />\n    </div>\n  );\n}\n","import {Component, createEffect, createMemo, createSelector, createSignal, For, JSX, onCleanup, onMount} from 'solid-js';\nimport {Portal} from 'solid-js/web';\nimport {Transition} from 'solid-transition-group';\nimport {animateValue, simpleEasing} from '@helpers/animateValue';\nimport {keepMe} from '@helpers/keepMe';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ripple from '@components/ripple';\nimport styles from '@components/sidebarLeft/tabs/passcodeLock/inlineSelect.module.scss';\n\nkeepMe(ripple);\n\n\nconst InlineSelect: Component<{\n  isOpen?: boolean;\n  onClose?: () => void;\n  value: any;\n  onChange: (value: any) => void;\n  options: {value: any; label: () => JSX.Element}[];\n  parent: HTMLElement;\n}> = (props) => {\n  let valueEl: HTMLDivElement;\n\n  const value = createMemo(() => props.options.find((option) => option.value === props.value)?.label);\n\n  const [valueLabel, setValueLabel] = createSignal<JSX.Element>(); // Doesn't work without intermediary signal\n  createEffect(() => {\n    setValueLabel(value()());\n  });\n\n  const isSelected = createSelector(() => props.value);\n\n  const [selectEl, setSelectEl] = createSignal<HTMLDivElement>();\n\n  onMount(() => {\n    const listenerSetter = new ListenerSetter();\n    listenerSetter.add(window)('resize', () => {\n      if(props.isOpen) props.onClose?.();\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    });\n  });\n\n  const onEnter = (el: Element, done: () => void) => {\n    const selectEl = el.firstElementChild as HTMLElement;\n    const selectOptionEl = selectEl.querySelector(`.${styles.selected}`);\n\n    if(!selectOptionEl || !selectEl) {\n      // done();\n      return;\n    }\n\n    const valueRect = valueEl.getBoundingClientRect();\n    const selectRect = selectEl.getBoundingClientRect();\n    const selectedOptionRect = selectOptionEl.getBoundingClientRect();\n\n    const optionTop = selectedOptionRect.top - selectRect.top;\n    const optionBottom = optionTop + selectedOptionRect.height;\n    const distToOptionCenter = optionTop + selectedOptionRect.height / 2;\n\n    const x = valueRect.left + valueRect.width / 2;\n    let y = valueRect.top + valueRect.height / 2 - distToOptionCenter;\n\n    const isOverflowing = y + selectRect.height > window.innerHeight || y < 0;\n\n    if(isOverflowing) {\n      y +=\n        Math.max(0, -y) +\n        Math.min(0, window.innerHeight - (y + selectRect.height));\n    }\n\n    selectEl.style.setProperty('--x', '' + x);\n    selectEl.style.setProperty('--y', '' + y);\n\n\n    selectEl.animate({opacity: [0, 1]}, {duration: 120}).finished.then(() => {\n      if(isOverflowing) done();\n    });\n\n    if(isOverflowing) return;\n\n    const maxDist = Math.max(optionTop, selectRect.height - optionBottom);\n    const getPath = (dist: number) =>\n      `polygon(0% ${optionTop - dist}px, 100% ${optionTop - dist}px, 100% ${optionBottom + dist}px, 0px ${optionBottom + dist}px)`;\n\n    animateValue(\n      0,\n      maxDist,\n      400,\n      (dist) => {\n        selectEl.style.setProperty('clip-path', getPath(dist));\n      },\n      {\n        easing: simpleEasing,\n        onEnd: () => {\n          selectEl.style.removeProperty('clip-path');\n          done();\n        }\n      }\n    );\n  };\n\n  const onExit = async(el: Element, done: () => void) => {\n    const selectEl = el.firstElementChild as HTMLElement;\n\n    await selectEl.animate({opacity: [1, 0]}, {duration: 120}).finished;\n\n    done();\n  };\n\n  const onMouseMove = (e: MouseEvent) => {\n    const toCheck = [props.parent, selectEl()];\n    if(!toCheck.every(Boolean)) return;\n\n    const isOutside = toCheck.every((el) => {\n      const rect = el.getBoundingClientRect();\n      const max = Math.max(\n        rect.left - e.clientX,\n        e.clientX - rect.right,\n        rect.top - e.clientY,\n        e.clientY - rect.bottom\n      );\n\n      return max > 100;\n    });\n\n    if(isOutside) {\n      props.onClose?.();\n    }\n  };\n\n  return (\n    <>\n      <div ref={valueEl} class={styles.Value}>\n        {valueLabel()}\n      </div>\n\n      <Portal>\n        <Transition appear onEnter={onEnter} onExit={onExit}>\n          {props.isOpen && (\n            <div\n              class={styles.Overlay}\n              onClick={(e) => {\n                e.stopPropagation();\n                props.onClose?.();\n              }}\n              onMouseMove={onMouseMove}\n            >\n              <div class={styles.SelectClip}>\n                <div class={styles.Select} ref={setSelectEl}>\n                  <For each={props.options}>\n                    {(option) => (\n                      <div\n                        use:ripple\n                        class={styles.Option}\n                        classList={{\n                          [styles.selected]: isSelected(option.value)\n                        }}\n                        onClick={[props.onChange, option.value]}\n                      >\n                        <span>{option.label()}</span>\n                      </div>\n                    )}\n                  </For>\n                </div>\n              </div>\n            </div>\n          )}\n        </Transition>\n      </Portal>\n    </>\n  );\n};\n\nexport default InlineSelect;\n","import PopupElement, {createPopup} from '@components/popups/indexTsx';\nimport {createEffect, createMemo, createSignal, on, onMount, Show} from 'solid-js';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport Row from '@components/rowTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {InputFieldTsx} from '@components/inputFieldTsx';\nimport {fastRaf} from '@helpers/schedulers';\nimport paymentsWrapCurrencyAmount, {formatNanoton, parseNanotonFromDecimal} from '@helpers/paymentsWrapCurrencyAmount';\nimport Section from '@components/section';\nimport rootScope from '@lib/rootScope';\n\nimport {useAppConfig} from '@stores/appState';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {STARS_CURRENCY, TON_CURRENCY} from '@appManagers/constants';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\nimport {StarGift, StarsAmount} from '@layer';\nimport bigInt from 'big-integer';\nimport PopupElementOld from './index'\nimport styles from '@components/popups/createStarGiftOffer.module.scss';\nimport {StarGiftPriceInputField} from '@components/stargifts/stargiftPriceInputField';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\nimport InlineSelect from '@components/sidebarLeft/tabs/passcodeLock/inlineSelect';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {FloatingStarsBalance} from './floatingStarsBalance';\nimport PopupStars from './stars';\nimport formatStarsAmount from '../../lib/appManagers/utils/payments/formatStarsAmount';\n\nexport async function showCreateStarGiftOfferPopup(options: {\n  gift: MyStarGift\n  onFinish?: (result: 'created' | 'cancel') => void\n}) {\n  const gift = options.gift.raw as StarGift.starGiftUnique;\n  const peerTitle = await wrapPeerTitle({peerId: getPeerId(gift.owner_id), onlyFirstName: true})\n  const [show, setShow] = createSignal(true);\n\n  return createPopup(() => {\n    const appConfig = useAppConfig()\n    const [ton, setTon] = createSignal(false);\n    const [offerAmount, setOfferAmount] = createSignal('');\n    const [offerDuration, setOfferDuration] = createSignal(86400);\n    const [durationSelectOpen, setDurationSelectOpen] = createSignal(false);\n\n    const durationOptions = [\n      {value: 21600, label: () => i18n('Hours', [6])},\n      {value: 43200, label: () => i18n('Hours', [12])},\n      {value: 86400, label: () => i18n('Hours', [24])},\n      {value: 129600, label: () => i18n('Hours', [36])},\n      {value: 172800, label: () => i18n('Hours', [48])},\n      {value: 259200, label: () => i18n('Hours', [72])}\n    ];\n\n\n    let isCreated = false;\n    let inputRef!: HTMLElement;\n    let durationRowRef!: HTMLElement;\n\n    onMount(() => {\n      fastRaf(() => {\n        inputRef.focus();\n      });\n    });\n\n    const handleSubmit = async() => {\n      const starsAmount: StarsAmount = ton() ? {\n        _: 'starsTonAmount',\n        amount: parseNanotonFromDecimal(offerAmount()).toString()\n      } : {\n        _: 'starsAmount',\n        amount: +offerAmount(),\n        nanos: 0\n      }\n\n      try {\n        await rootScope.managers.appGiftsManager.createGiftOffer({\n          peerId: getPeerId(gift.owner_id),\n          slug: gift.slug,\n          amount: starsAmount,\n          duration: offerDuration()\n        });\n\n        isCreated = true;\n        options.onFinish?.('created')\n      } catch(err) {\n        if((err as ApiError).type === 'BALANCE_TOO_LOW') {\n          PopupElementOld.createPopup(PopupStars, {\n            itemPrice: starsAmount.amount,\n            ton: ton(),\n            onTopup: async() => {\n              await handleSubmit()\n            },\n            purpose: 'stargift'\n          });\n        }\n      }\n    }\n\n    const limits = createMemo(() => {\n      const minStars = gift.offer_min_stars;\n      const maxStars = Math.max(minStars * 2, appConfig.stars_stargift_resale_amount_max);\n\n      const minStarsUsd = appConfig.stars_usd_sell_rate_x1000 / 1000 * minStars / 100;\n      const minTonFromStars = parseNanotonFromDecimal(String(minStarsUsd / appConfig.ton_usd_rate));\n      const minTonFromConfig = bigInt(appConfig.ton_stargift_resale_amount_min);\n      const minTon = bigInt.max(minTonFromStars, minTonFromConfig);\n      const maxTon = bigInt.max(minTon.multiply(2), appConfig.ton_stargift_resale_amount_max);\n      return {minStars, maxStars, minTon, maxTon};\n    })\n\n    const inputError = createMemo<[LangPackKey, any[]] | undefined>(() => {\n      const offerAmount$ = offerAmount();\n      if(!offerAmount$) return undefined;\n\n      const {minStars, maxStars, minTon, maxTon} = limits();\n\n      if(ton()) {\n        const nanoton = parseNanotonFromDecimal(offerAmount$);\n        if(nanoton.lt(minTon)) {\n          return ['StarGiftMinSellAmountTon', [formatNanoton(minTon)]];\n        }\n\n        if(nanoton.gt(maxTon)) {\n          return ['StarGiftMaxSellAmountTon', [formatNanoton(maxTon)]];\n        }\n\n        return undefined;\n      }\n\n      const value = +offerAmount$;\n\n      if(value < minStars) {\n        return ['StarGiftMinSellAmountStars', [minStars]];\n      }\n\n      if(value > maxStars) {\n        return ['StarGiftMaxSellAmountStars', [maxStars]];\n      }\n\n      return undefined;\n    });\n\n    return (\n      <PopupElement\n        class={styles.popup}\n        containerClass={styles.popupContainer}\n        show={show()}\n        closable={true}\n        onClose={() => {\n          if(!isCreated) {\n            options.onFinish?.('cancel');\n          }\n        }}\n      >\n        <FloatingStarsBalance class={styles.balance} ton={ton()} />\n        <PopupElement.Header class={styles.popupHeader}>\n          <PopupElement.CloseButton />\n          <PopupElement.Title>\n            <I18nTsx key=\"StarGiftOffer.CreateOfferTitle\" />\n          </PopupElement.Title>\n        </PopupElement.Header>\n        <PopupElement.Body>\n          <Section\n            caption={ton() ? 'StarGiftOffer.CreateOfferSubtitleTON' : 'StarGiftOffer.CreateOfferSubtitleStars'}\n            captionArgs={[getCollectibleName(gift)]}\n          >\n            <ChipTabs\n              class={styles.chipTabs}\n              value={ton() ? 'ton' : 'stars'}\n              view=\"primary\"\n              onChange={(value) => setTon(value === 'ton')}\n            >\n              <ChipTab value=\"stars\">\n                <I18nTsx key=\"StarGiftOffer.CreateOfferStars\" />\n              </ChipTab>\n              <ChipTab value=\"ton\">\n                <I18nTsx key=\"StarGiftOffer.CreateOfferTON\" />\n              </ChipTab>\n            </ChipTabs>\n            <StarGiftPriceInputField\n              class={styles.input}\n              ton={ton()}\n              label={ton() ? 'StarGiftOffer.CreateOfferPlaceholderTON' : 'StarGiftOffer.CreateOfferPlacholderStars'}\n              value={offerAmount()}\n              onValueChange={setOfferAmount}\n              errorLabel={inputError()?.[0]}\n              errorLabelOptions={inputError()?.[1]}\n              instanceRef={ref => {\n                inputRef = ref.input;\n              }}\n            />\n          </Section>\n          <Section\n            caption={ton() ? 'StarGiftOffer.OfferDurationDescriptionTON' : 'StarGiftOffer.OfferDurationDescriptionStars'}\n            captionArgs={[peerTitle]}\n          >\n            <Row\n              ref={durationRowRef}\n              clickable={() => setDurationSelectOpen(v => !v)}\n            >\n              <Row.Title>\n                <I18nTsx key=\"StarGiftOffer.OfferDuration\" />\n              </Row.Title>\n              <Row.RightContent>\n                <InlineSelect\n                  value={offerDuration()}\n                  onChange={setOfferDuration}\n                  options={durationOptions}\n                  parent={durationRowRef}\n                  isOpen={durationSelectOpen()}\n                  onClose={() => setDurationSelectOpen(false)}\n                />\n              </Row.RightContent>\n            </Row>\n          </Section>\n        </PopupElement.Body>\n        <PopupElement.Footer class={styles.popupFooter}>\n          <PopupElement.FooterButton\n            disabled={!offerAmount() || inputError() !== undefined}\n            callback={handleSubmit}\n          >\n            <I18nTsx\n              key=\"StarGiftOffer.CreateOfferSubmit\"\n              args={[\n                ton() ?\n                  paymentsWrapCurrencyAmount(parseNanotonFromDecimal(offerAmount()).toString(), TON_CURRENCY) :\n                  paymentsWrapCurrencyAmount(offerAmount(), STARS_CURRENCY)\n              ]}\n            />\n          </PopupElement.FooterButton>\n        </PopupElement.Footer>\n      </PopupElement>\n    );\n  });\n}\n","import rootScope from '@lib/rootScope';\n\nexport async function getCanManagePeerGifts(peerId: PeerId): Promise<boolean> {\n  if(peerId === rootScope.myId) return true\n  return peerId.isAnyChat() && rootScope.managers.appChatsManager.hasRights(peerId.toChatId(), 'post_messages')\n}\n","import {createMemo, createSignal, Index, JSX, Match, onMount, Show, Switch} from 'solid-js';\nimport PopupElement from '.';\nimport {Peer, PaymentsUniqueStarGiftValueInfo, StarGift, StarGiftAttribute, StarGiftAttributeRarity} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {StarsStar} from '@components/popups/stars';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport Button from '@components/buttonTsx';\nimport {formatDate, formatFullSentTime} from '@helpers/date';\nimport appImManager from '@lib/appImManager';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport PopupSendGift from '@components/popups/sendGift';\nimport Table, {TableButton, TableButtonWithTooltip, TablePeer, TableRow} from '@components/table';\nimport {NULL_PEER_ID, STARS_CURRENCY, TON_CURRENCY} from '@appManagers/constants';\nimport rootScope from '@lib/rootScope';\nimport {toastNew} from '@components/toast';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport {ButtonMenuToggleTsx} from '@components/buttonMenuToggleTsx';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {showSharingPicker2Popup} from '@components/popups/pickUser';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport tsNow from '@helpers/tsNow';\nimport {useAppState} from '@stores/appState';\nimport transferStarGift from '@components/popups/transferStarGift';\nimport safeAssign from '@helpers/object/safeAssign';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport PopupBuyResaleGift from '@components/popups/buyResaleGift';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport formatDuration from '@helpers/formatDuration';\nimport PopupSellStarGift from '@components/popups/sellStarGift';\nimport {inputStarGiftEquals} from '@appManagers/utils/gifts/inputStarGiftEquals';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\nimport {updateStarGift} from '@appManagers/utils/gifts/updateStarGift';\nimport wrapMessageEntities from '@lib/richTextProcessor/wrapMessageEntities';\nimport PopupStarGiftValue from '@components/popups/starGiftValue';\nimport Icon from '@components/icon';\nimport PopupStarGiftWear from '@components/popups/starGiftWear';\nimport {setQuizHint} from '@components/quizHint';\nimport createStarGiftUpgradePopup from '@components/popups/starGiftUpgrade';\nimport classNames from '@helpers/string/classNames';\nimport PopupPayment from '@components/popups/payment';\nimport {StarGiftUpgradePreview} from '@appManagers/appGiftsManager';\nimport {rgbIntToHex} from '@helpers/color';\nimport wrapSticker from '@components/wrappers/sticker';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport RLottiePlayer from '@lib/rlottie/rlottiePlayer';\nimport {SimpleAnimation} from '@helpers/solid/animations';\nimport BezierEasing from '@vendor/bezierEasing';\nimport {AnimatedSuper} from '@components/animatedSuper';\nimport {ConfettiContainer, ConfettiRef} from '@components/confetti';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport {showCreateStarGiftOfferPopup} from '@components/popups/createStarGiftOffer';\nimport {getCanManagePeerGifts} from '@components/stargifts/canManageGifts';\n\nfunction AttributeTableButton(props: {rarity: StarGiftAttributeRarity}) {\n  if(props.rarity._ !== 'starGiftAttributeRarity') {\n    const map: Record<Exclude<StarGiftAttributeRarity['_'], 'starGiftAttributeRarity'>, {langKey: LangPackKey, color: string}> = {\n      'starGiftAttributeRarityUncommon': {langKey: 'StarGiftRarityUncommon', color: 'green'},\n      'starGiftAttributeRarityRare': {langKey: 'StarGiftRarityRare', color: 'blue'},\n      'starGiftAttributeRarityEpic': {langKey: 'StarGiftRarityEpic', color: 'violet'},\n      'starGiftAttributeRarityLegendary': {langKey: 'StarGiftRarityLegendary', color: 'gold'}\n    };\n\n    return (\n      <TableButtonWithTooltip\n        class={`rarity rarity-${map[props.rarity._].color} disable-hover`}\n      >\n        {i18n(map[props.rarity._].langKey)}\n      </TableButtonWithTooltip>\n    );\n  }\n\n  return (\n    <TableButtonWithTooltip\n      tooltipTextElement={i18n('StarGiftAttributeTooltip', [`${props.rarity.permille / 10}%`])}\n      tooltipClass=\"popup-star-gift-info-tooltip\"\n    >\n      {props.rarity.permille / 10}%\n    </TableButtonWithTooltip>\n  );\n}\n\nexport function AttributeValue(props: {name: string, rarity: StarGiftAttributeRarity, onClick?: () => void}) {\n  return (\n    <div class=\"popup-star-gift-info-attribute-value\">\n      {props.onClick ? (\n        <span class=\"popup-star-gift-info-attribute-clickable\" onClick={props.onClick}>\n          {props.name}\n        </span>\n      ) : props.name}\n      <AttributeTableButton rarity={props.rarity} />\n    </div>\n  )\n}\n\nconst attributeValueKeyFrames = (element: Element, removed: boolean) => [\n  {opacity: 0, transform: `translateY(${removed ? '-14px' : '14px'}) scaleY(0.5)`},\n  {opacity: 1, transform: 'translateY(0)'}\n]\n\nconst attributeIntervalEasing = BezierEasing(0.5, 0, 1, 1);\n\nfunction calculateEasedIntervals(count: number, duration: number): number[] {\n  const intervals: number[] = [];\n  for(let i = 0; i < count; i++) {\n    const t0 = i / count;\n    const t1 = (i + 1) / count;\n    const interval = (attributeIntervalEasing(t1) - attributeIntervalEasing(t0)) * duration;\n    intervals.push(interval);\n  }\n  return intervals;\n}\n\ntype AnimatedAttributeValueItem = {name: string, rarity: StarGiftAttributeRarity};\nfunction AnimatedAttributeValue(props: {\n  items: AnimatedAttributeValueItem[],\n  actual: AnimatedAttributeValueItem,\n  duration: number,\n  count: number,\n  onComplete?: () => void,\n  onClick?: () => void\n  started: boolean\n}) {\n  const [position, setPosition] = createSignal(0);\n\n  const items: AnimatedAttributeValueItem[] = [];\n  while(items.length < props.count - 1) {\n    const left = props.count - 1 - items.length;\n    items.push(...props.items.slice(0, left));\n  }\n  items.push(props.actual);\n\n  const intervals = calculateEasedIntervals(items.length, props.duration);\n\n  onMount(() => {\n    function scheduleNext(index: number) {\n      setTimeout(() => {\n        const nextIndex = index + 1;\n        setPosition(nextIndex);\n        if(nextIndex < items.length - 1) {\n          scheduleNext(nextIndex);\n        } else {\n          props.onComplete?.();\n        }\n      }, intervals[index]);\n    }\n\n    function scheduleRandom() {\n      let randomIndex = Math.floor(Math.random() * items.length);\n      if(position() === randomIndex) {\n        randomIndex = (randomIndex + 1) % items.length;\n      }\n      setPosition(randomIndex);\n\n      setTimeout(() => {\n        if(props.started) {\n          scheduleNext(0);\n        } else {\n          scheduleRandom();\n        }\n      }, 150);\n    }\n\n    if(props.started) {\n      scheduleNext(0);\n    } else {\n      scheduleRandom();\n    }\n  });\n\n  return (\n    <SimpleAnimation\n      keyframes={attributeValueKeyFrames}\n      mode=\"replacement\"\n      appear={true}\n    >\n      <Switch>\n        <Index each={items}>\n          {(item, index) => (\n            <Match when={index === position()}>\n              <AttributeValue\n                name={item().name}\n                rarity={item().rarity}\n                onClick={props.onClick}\n              />\n            </Match>\n          )}\n        </Index>\n      </Switch>\n    </SimpleAnimation>\n  )\n}\n\nfunction UpgradeAnimation(props: {\n  preview: StarGiftUpgradePreview,\n  actualModel: StarGiftAttribute.starGiftAttributeModel,\n  actualBackdrop: StarGiftAttribute.starGiftAttributeBackdrop,\n  confetti: ConfettiRef,\n  onReady: () => void,\n  onComplete: () => void\n}) {\n  const MODELS_COUNT = 20;\n  const BACKDROPS_COUNT = 5;\n  const MODEL_WIDTH = 120;\n  const MODEL_GAP = 100;\n  const MODELS_DURATION = 2000;\n  const BACKDROPS_DURATION = 700;\n\n  const models: StarGiftAttribute.starGiftAttributeModel[] = [];\n  while(models.length < MODELS_COUNT - 1) {\n    const left = MODELS_COUNT - 1 - models.length;\n    models.push(...props.preview.models.slice(0, left));\n  }\n  models.push(props.actualModel);\n\n  const backdrops: StarGiftAttribute.starGiftAttributeBackdrop[] = [];\n  while(backdrops.length < BACKDROPS_COUNT - 1) {\n    const left = BACKDROPS_COUNT - 1 - backdrops.length;\n    backdrops.push(...props.preview.backdrops.slice(0, left));\n  }\n  backdrops.push(props.actualBackdrop);\n\n  const totalSections = backdrops.length + 2;\n  const sectionSize = 100 / totalSections;\n  const colors = backdrops.map((b) => rgbIntToHex(b.edge_color));\n  const lastColor = colors[colors.length - 1];\n  const gradientStopsStr = [\n    // initial padding\n    `${colors[0]} 0%`, `${colors[0]} ${sectionSize}%`,\n    ...colors.flatMap((color, i) => {\n      const base = (i + 1) * sectionSize;\n      // 33% transition in, 34% solid, 33% transition out\n      return [`${color} ${base + sectionSize * 0.33}%`, `${color} ${base + sectionSize * 0.67}%`];\n    }),\n    // final padding\n    `${lastColor} ${(totalSections - 1) * sectionSize}%`, `${lastColor} 100%`\n  ].join(', ');\n\n  let modelsContainer!: HTMLDivElement;\n  let backdropEl!: HTMLDivElement;\n  const [loading, setLoading] = createSignal(true);\n\n  onMount(async() => {\n    const middleware = createMiddleware();\n\n    let lastPlayer: RLottiePlayer;\n    await Promise.all(models.map(async(model, idx) => {\n      const div = document.createElement('div');\n      const isLast = idx === models.length - 1;\n      div.classList.add('popup-star-gift-info-upgrade-model');\n      if(isLast) {\n        div.classList.add('last');\n      }\n      modelsContainer.appendChild(div);\n\n      return wrapSticker({\n        doc: model.document as MyDocument,\n        div,\n        width: MODEL_WIDTH,\n        height: MODEL_WIDTH,\n        play: false,\n        needFadeIn: false,\n        middleware: middleware.get()\n      }).then(({render}) => render).then((player) => {\n        if(isLast) {\n          lastPlayer = player as RLottiePlayer;\n        }\n      });\n    }));\n\n    props.onReady();\n    setLoading(false);\n\n    const containerWidth = modelsContainer.parentElement!.offsetWidth;\n    const totalModelsWidth = MODELS_COUNT * MODEL_WIDTH + (MODELS_COUNT - 1) * MODEL_GAP;\n    const startOffset = (containerWidth - MODEL_WIDTH) / 2;\n    const endOffset = -(totalModelsWidth - containerWidth + startOffset);\n    const containerCenter = containerWidth / 2;\n    const modelDivs = Array.from(modelsContainer.children) as HTMLDivElement[];\n\n    const animation = modelsContainer.animate([\n      {transform: `translateX(${startOffset}px)`},\n      {transform: `translateX(${endOffset}px)`}\n    ], {\n      duration: MODELS_DURATION,\n      easing: 'cubic-bezier(1.00,1.00,0.35,1.00)',\n      fill: 'forwards'\n    });\n\n    // 3d-ish scrolling animation\n    let rafId: number;\n    let finishing = false;\n    const updateModels = () => {\n      const containerRect = modelsContainer.parentElement!.getBoundingClientRect();\n      for(const div of modelDivs) {\n        const rect = div.getBoundingClientRect();\n        const modelCenter = rect.left + rect.width / 2 - containerRect.left;\n        const distFromCenter = Math.abs(modelCenter - containerCenter);\n        const t = Math.min(distFromCenter / containerCenter, 1);\n        const scaleY = 1 - t * 0.2;\n        const scaleX = 1 - t * 0.5;\n        div.style.transform = `scale(${scaleX}, ${scaleY})`;\n        if(!finishing) {\n          const opacity = 1 - t * 0.5;\n          div.style.opacity = `${opacity}`;\n        }\n      }\n      if(animation.playState === 'running') {\n        rafId = requestAnimationFrame(updateModels);\n      }\n    };\n    rafId = requestAnimationFrame(updateModels);\n    animation.addEventListener('finish', () => cancelAnimationFrame(rafId));\n\n    setTimeout(() => {\n      modelsContainer.classList.add('finishing');\n      finishing = true\n      lastPlayer.playOrRestart();\n      lastPlayer.addEventListener('enterFrame', (frameNo) => {\n        if(frameNo === lastPlayer.maxFrame) {\n          lastPlayer.stop(false);\n          middleware.destroy();\n          props.onComplete();\n        }\n      });\n    }, MODELS_DURATION - 500);\n    setTimeout(() => {\n      props.confetti.create({mode: 'poppers'});\n    }, MODELS_DURATION - 750);\n\n    setTimeout(() => backdropEl.animate([\n      {backgroundPosition: '0% 0%'},\n      {backgroundPosition: '100% 0%'}\n    ], {\n      duration: BACKDROPS_DURATION,\n      easing: 'linear',\n      fill: 'forwards'\n    }), 50);\n\n    setTimeout(() => {\n      backdropEl.classList.add('finishing');\n    }, BACKDROPS_DURATION - 200);\n  });\n\n  return (\n    <>\n      <div\n        ref={backdropEl}\n        class=\"popup-star-gift-info-upgrade-backdrops\"\n        style={{\n          'background': `linear-gradient(to right, ${gradientStopsStr})`,\n          'background-size': `${totalSections * 100}% 100%`\n        }}\n      />\n      <div class=\"popup-star-gift-info-upgrade-models-container\">\n        <Show when={loading()}>\n          <PreloaderTsx />\n        </Show>\n        <div ref={modelsContainer} class=\"popup-star-gift-info-upgrade-models\" style={{display: loading() ? 'none' : undefined}} />\n      </div>\n    </>\n  );\n}\n\nfunction AnimatedCollectibleNumber(props: {\n  targetNumber: number,\n  started: boolean\n}) {\n  let containerRef!: HTMLSpanElement;\n\n  onMount(() => {\n    const targetStr = String(props.targetNumber);\n    const digitCount = targetStr.length;\n\n    // ! cant use AnimatedCounter because of the comma separator\n    const digitAnimators: {animator: AnimatedSuper, placeholder: HTMLElement}[] = [];\n    for(let i = 0; i < digitCount; i++) {\n      const posFromRight = digitCount - i;\n      if(posFromRight < digitCount && posFromRight % 3 === 0) {\n        const comma = document.createElement('div');\n        comma.className = 'animated-counter-decimal';\n        comma.textContent = ',';\n        containerRef.appendChild(comma);\n      }\n\n      const item = document.createElement('div');\n      item.className = 'animated-counter-decimal';\n\n      const placeholder = document.createElement('div');\n      placeholder.className = 'animated-counter-decimal-placeholder';\n\n      const animator = new AnimatedSuper({duration: 100});\n      animator.container.className = 'animated-counter-decimal-wrapper';\n\n      item.append(placeholder, animator.container);\n      containerRef.appendChild(item);\n      digitAnimators.push({animator, placeholder});\n    }\n\n    const getRandomDigit = () => Math.floor(Math.random() * 10);\n\n    const setDigits = (lockedFromLeft: number, animate: boolean) => {\n      for(let i = 0; i < digitCount; i++) {\n        const {animator, placeholder} = digitAnimators[i];\n        let newDigit: number;\n        if(i < lockedFromLeft) {\n          newDigit = parseInt(targetStr[i]);\n        } else {\n          newDigit = getRandomDigit();\n          if(i === 0 && newDigit === 0) newDigit = 1\n        }\n\n        const previousDigit = animator.rows[Object.keys(animator.rows)[0]] ?\n          parseInt(Object.keys(animator.rows)[0]) : -1;\n\n        const row = animator.getRow(newDigit, animate);\n        row.textContent = placeholder.textContent = String(newDigit);\n\n        if(animate && previousDigit !== newDigit) {\n          animator.animate(newDigit, previousDigit, newDigit > previousDigit, true);\n        } else if(!animate) {\n          animator.setNewRow(newDigit);\n        }\n      }\n    };\n\n    setDigits(0, false);\n\n    const totalUpdates = 10;\n    const totalDuration = 2000;\n    const intervals = calculateEasedIntervals(totalUpdates, totalDuration);\n\n    let updateCount = 0;\n\n    function scheduleNext() {\n      setTimeout(() => {\n        updateCount++;\n\n        const progress = updateCount / totalUpdates;\n        const lockedDigits = Math.min(\n          digitCount,\n          Math.floor(progress * (digitCount + 1))\n        );\n\n        if(updateCount >= totalUpdates) {\n          setDigits(digitCount, true);\n        } else {\n          setDigits(lockedDigits, true);\n          scheduleNext();\n        }\n      }, intervals[updateCount]);\n    }\n\n    function scheduleRandom() {\n      setTimeout(() => {\n        setDigits(0, true)\n        if(props.started) {\n          scheduleNext();\n        } else {\n          scheduleRandom()\n        }\n      }, 150);\n    }\n\n    if(props.started) {\n      scheduleNext();\n    } else {\n      scheduleRandom()\n    }\n  });\n\n  return <span ref={containerRef} class=\"animated-counter\" />;\n}\n\nexport default class PopupStarGiftInfo extends PopupElement {\n  private gift: MyStarGift;\n  private resaleRecipient?: PeerId;\n  private onClickAway?: () => void;\n  private onAttributeClick?: (attribute: StarGiftAttribute.starGiftAttributeModel | StarGiftAttribute.starGiftAttributeBackdrop | StarGiftAttribute.starGiftAttributePattern) => void;\n  private upgradeAnimation?: StarGiftUpgradePreview;\n\n  private isResale: boolean\n  private canUpgrade: boolean\n\n  constructor(options: {\n    gift: MyStarGift,\n    onClickAway?: () => void,\n    resaleRecipient?: PeerId,\n    onAttributeClick?: (attribute: StarGiftAttribute.starGiftAttributeModel | StarGiftAttribute.starGiftAttributeBackdrop | StarGiftAttribute.starGiftAttributePattern) => void,\n    upgradeAnimation?: StarGiftUpgradePreview\n  }) {\n    super('popup-star-gift-info', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      footer: true,\n      withConfirm: 'OK',\n      withFooterConfirm: true\n    });\n\n    safeAssign(this, options);\n    this.isResale = this.gift.resellPriceStars !== undefined && getPeerId((this.gift.raw as StarGift.starGiftUnique).owner_id) !== rootScope.myId;\n    this.canUpgrade = this.gift.raw._ === 'starGift' && this.gift.saved?.pFlags.can_upgrade && (\n      this.gift.ownerId === rootScope.myId ||\n      this.gift.saved?.prepaid_upgrade_hash !== undefined\n    );\n\n    this.construct();\n  }\n\n  private _construct(props: {value: PaymentsUniqueStarGiftValueInfo | null, canManageGifts: boolean}) {\n    const {\n      saved,\n      raw: gift,\n      ownerId,\n      sticker,\n      isIncoming,\n      isConverted,\n      collectibleAttributes\n    } = this.gift;\n\n    const isUnavailable = !saved && (gift as StarGift.starGift).availability_remains === 0;\n    const fromId = saved ? getPeerId(saved.from_id) : NULL_PEER_ID;\n    const date = saved ? new Date(saved.date * 1000) : null;\n    const firstSaleDate = (gift as StarGift.starGift).first_sale_date ? (new Date((gift as StarGift.starGift).first_sale_date * 1000)) : null;\n    const lastSaleDate = (gift as StarGift.starGift).last_sale_date ? (new Date((gift as StarGift.starGift).last_sale_date * 1000)) : null;\n    const starsValue = (gift as StarGift.starGift).stars;\n\n    let input = this.gift.input;\n    if(!input && gift._ === 'starGiftUnique') {\n      input = {_: 'inputSavedStarGiftSlug', slug: gift.slug}\n    }\n    const ownerPeerId = this.gift.ownerId;\n    const isEditableUniqueGift = gift._ === 'starGiftUnique' && ownerPeerId !== undefined && props.canManageGifts;\n    const canSave = gift._ === 'starGift' && isIncoming && !isConverted || (isEditableUniqueGift && saved !== undefined)\n\n    const [isListed, setIsListed] = createSignal((gift as StarGift.starGiftUnique).resell_amount !== undefined);\n    const [resellOnlyTon, setResellOnlyTon] = createSignal(this.gift.resellOnlyTon);\n    const [resellPriceTon, setResellPriceTon] = createSignal(this.gift.resellPriceTon);\n    const [resellPriceStars, setResellPriceStars] = createSignal(this.gift.resellPriceStars);\n    const [isWearing, setIsWearing] = createSignal(this.gift.isWearing);\n    const [upgradeAnimationStarted, setUpgradeAnimationStarted] = createSignal(false);\n    const [upgradeAnimationComplete, setUpgradeAnimationComplete] = createSignal(!this.upgradeAnimation);\n\n    this.listenerSetter.add(rootScope)('star_gift_update', (event) => {\n      if(inputStarGiftEquals(this.gift, event.input)) {\n        if(event.resalePrice) {\n          setIsListed(event.resalePrice.length > 0);\n          updateStarGift(this.gift, event);\n          setResellOnlyTon(this.gift.resellOnlyTon);\n          setResellPriceTon(this.gift.resellPriceTon);\n          setResellPriceStars(this.gift.resellPriceStars);\n        }\n        if(event.wearing !== undefined) {\n          setIsWearing(event.wearing);\n          createSnackbar({\n            icon: event.wearing ? 'crown' : 'crownoff',\n            textElement: event.wearing ?\n              i18n('SetAsEmojiStatusInfo') :\n              i18n('StarGiftWearStopped', [getCollectibleName(gift as StarGift.starGiftUnique)])\n          });\n        }\n      }\n    })\n\n    this.listenerSetter.add(rootScope)('emoji_status_change', async() => {\n      const self = await rootScope.managers.appUsersManager.getSelf();\n      const wearingGiftId = self?.emoji_status?._ === 'emojiStatusCollectible' ? self.emoji_status.collectible_id : null;\n      setIsWearing(wearingGiftId === gift.id);\n    })\n\n    const handleAttributeClick = (attribute: StarGiftAttribute.starGiftAttributeModel | StarGiftAttribute.starGiftAttributeBackdrop | StarGiftAttribute.starGiftAttributePattern) => {\n      if(this.onAttributeClick) {\n        this.onAttributeClick(attribute);\n        return\n      }\n\n      PopupElement.createPopup(PopupSendGift, {\n        peerId: rootScope.myId,\n        resaleParams: {\n          giftId: (gift as StarGift.starGiftUnique).gift_id,\n          filter: attribute\n        }\n      })\n    }\n\n    let loading = false;\n    const toggleGiftHidden = () => {\n      if(loading) return;\n      loading = true;\n      this.managers.appGiftsManager.toggleGiftHidden(input, !saved.pFlags.unsaved).then(() => {\n        this.hide();\n      });\n    }\n\n    if(this.canUpgrade) {\n      attachClickEvent(this.btnConfirm, () => createStarGiftUpgradePopup({\n        gift: this.gift,\n        descriptionForPeerId: this.gift.ownerId === rootScope.myId ? undefined : this.gift.ownerId\n      }).then(() => this.hide()));\n    } else if(this.isResale) {\n      attachClickEvent(this.btnConfirm, () => {\n        const recipientId = this.resaleRecipient ?? rootScope.myId;\n        const popup = PopupElement.createPopup(PopupBuyResaleGift, {\n          recipientId,\n          gift: this.gift\n        })\n        const giftUnique = this.gift.raw as StarGift.starGiftUnique;\n        popup.show()\n        popup.addEventListener('finish', async(bought) => {\n          if(bought) {\n            this.hide();\n\n            const isSelf = recipientId === rootScope.myId;\n            if(isSelf) {\n              toastNew({\n                langPackKey: 'StarGiftResaleBoughtSelf',\n                langPackArguments: [`${giftUnique.title} #${numberThousandSplitter(giftUnique.num, ',')}`]\n              })\n            } else {\n              toastNew({\n                langPackKey: 'StarGiftResaleBoughtOther',\n                langPackArguments: [await wrapPeerTitle({peerId: recipientId, onlyFirstName: true})]\n              })\n            }\n          }\n        })\n      });\n    } else {\n      attachClickEvent(this.btnConfirm, () => this.hide());\n    }\n\n    const tableContent = createMemo(() => {\n      const rows: TableRow[] = [];\n\n      if(gift._ === 'starGiftUnique') {\n        if(gift.owner_id) {\n          rows.push([\n            'StarGiftOwner',\n            <TablePeer\n              peerId={getPeerId(gift.owner_id)}\n              onClick={() => {\n                appImManager.setInnerPeer({peerId: getPeerId(gift.owner_id)})\n                this.onClickAway?.()\n                this.hide()\n              }}\n            />\n          ]);\n        } else if(gift.owner_name) {\n          rows.push([\n            'StarGiftOwner',\n            gift.owner_name\n          ]);\n        }\n\n        rows.push([\n          'StarGiftModel',\n          this.upgradeAnimation ? (\n            <AnimatedAttributeValue\n              items={this.upgradeAnimation.models}\n              actual={collectibleAttributes.model}\n              duration={2000}\n              count={10}\n              onClick={() => handleAttributeClick(collectibleAttributes.model)}\n              started={upgradeAnimationStarted()}\n            />\n          ) : (\n            <AttributeValue\n              name={collectibleAttributes.model.name}\n              rarity={collectibleAttributes.model.rarity}\n              onClick={() => handleAttributeClick(collectibleAttributes.model)}\n            />\n          )\n        ]);\n\n        rows.push([\n          'StarGiftBackdrop',\n          this.upgradeAnimation ? (\n            <AnimatedAttributeValue\n              items={this.upgradeAnimation.backdrops}\n              actual={collectibleAttributes.backdrop}\n              duration={800}\n              count={4}\n              onClick={() => handleAttributeClick(collectibleAttributes.backdrop)}\n              started={upgradeAnimationStarted()}\n            />\n          ) : (\n            <AttributeValue\n              name={collectibleAttributes.backdrop.name}\n              rarity={collectibleAttributes.backdrop.rarity}\n              onClick={() => handleAttributeClick(collectibleAttributes.backdrop)}\n            />\n          )\n        ]);\n\n        rows.push([\n          'StarGiftPattern',\n          this.upgradeAnimation ? (\n            <AnimatedAttributeValue\n              items={this.upgradeAnimation.patterns}\n              actual={collectibleAttributes.pattern}\n              duration={1000}\n              count={5}\n              onClick={() => handleAttributeClick(collectibleAttributes.pattern)}\n              started={upgradeAnimationStarted()}\n            />\n          ) : (\n            <AttributeValue\n              name={collectibleAttributes.pattern.name}\n              rarity={collectibleAttributes.pattern.rarity}\n              onClick={() => handleAttributeClick(collectibleAttributes.pattern)}\n            />\n          )\n        ]);\n\n        rows.push([\n          'StarGiftAvailability',\n          i18n('StarGiftAvailabilityIssued', [\n            numberThousandSplitter(gift.availability_issued),\n            numberThousandSplitter(gift.availability_total)\n          ])\n        ]);\n\n        if(props.value) {\n          rows.push([\n            'StarGiftValue',\n            <>\n              ~{paymentsWrapCurrencyAmount(props.value.value, props.value.currency)}\n              <TableButton\n                text=\"StarGiftValueLearnMore\"\n                onClick={() => {\n                  PopupElement.createPopup(PopupStarGiftValue, {gift: this.gift, value: props.value}).show();\n                }}\n              />\n            </>\n          ]);\n        }\n\n        return rows;\n      }\n\n      if(fromId !== NULL_PEER_ID) {\n        rows.push([\n          'StarGiftFromShort',\n          <>\n            <TablePeer peerId={fromId} />\n            <TableButton\n              text=\"StarGiftSendInline\"\n              onClick={() => {\n                this.hide();\n                PopupElement.createPopup(PopupSendGift, {peerId: fromId});\n              }}\n            />\n          </>\n        ]);\n      }\n\n      if(date) {\n        rows.push([\n          'StarGiftDate',\n          <span>{formatFullSentTime(date.getTime() / 1000 | 0)}</span>\n        ]);\n      }\n\n      if(isUnavailable) {\n        if(firstSaleDate) {\n          rows.push([\n            'StarGiftUnavailableFirstSale',\n            <span>{formatFullSentTime(firstSaleDate.getTime() / 1000 | 0)}</span>\n          ]);\n        }\n\n        if(lastSaleDate) {\n          rows.push([\n            'StarGiftUnavailableLastSale',\n            <span>{formatFullSentTime(lastSaleDate.getTime() / 1000 | 0)}</span>\n          ]);\n        }\n      }\n\n      const canConvert = saved?.convert_stars &&\n        isIncoming &&\n        !isConverted &&\n        (tsNow(true) - (date.getTime() / 1000 | 0)) < useAppState()[0].appConfig.stargifts_convert_period_max;\n      rows.push([\n        'StarGiftValue',\n        <>\n          <StarsStar />\n          {starsValue}\n          {canConvert && (\n            <TableButton\n              text=\"StarGiftConvertButton\"\n              textArgs={[saved.convert_stars]}\n              onClick={() => {\n                rootScope.managers.appGiftsManager.convertGift(input)\n                .then(() => {\n                  this.hide()\n                }).catch(() => {\n                  toastNew({langPackKey: 'Error.AnError'})\n                })\n              }}\n            />\n          )}\n        </>\n      ]);\n\n      if(gift.availability_total > 0) {\n        rows.push([\n          'StarGiftAvailability',\n          i18n('StarGiftAvailabilityValue2', [\n            numberThousandSplitter((gift as StarGift.starGift).availability_remains ?? 0),\n            numberThousandSplitter(gift.availability_total)\n          ])\n        ]);\n      }\n\n      if(gift._ === 'starGift' && saved?.pFlags.can_upgrade) {\n        rows.push([\n          'StarGiftStatus',\n          i18n('StarGiftStatusNonUnique')\n        ]);\n      }\n\n      return rows;\n    })\n\n    const [originalDetails, setOriginalDetails] = createSignal(collectibleAttributes?.original);\n\n    const tableFooter = () => {\n      if(originalDetails()) {\n        const wrapPeer = (peer: Peer) => {\n          const peerId = getPeerId(peer);\n          return (\n            <PeerTitleTsx\n              peerId={peerId}\n              onlyFirstName\n              onClick={() => {\n                appImManager.setInnerPeer({peerId})\n                this.hide()\n              }}\n            />\n          );\n        };\n\n        let key: LangPackKey;\n        const args: JSX.Element[] = [];\n\n        if(collectibleAttributes.original.sender_id) {\n          key = collectibleAttributes.original.message ? 'StarGiftOriginalDetailsSenderComment' : 'StarGiftOriginalDetailsSender';\n          args.push(wrapPeer(collectibleAttributes.original.sender_id));\n        } else {\n          key = collectibleAttributes.original.message ? 'StarGiftOriginalDetailsComment' : 'StarGiftOriginalDetailsBasic';\n        }\n\n        args.push(wrapPeer(collectibleAttributes.original.recipient_id));\n        args.push(formatDate(new Date(collectibleAttributes.original.date * 1000)));\n\n        if(collectibleAttributes.original.message) {\n          const span = document.createElement('span');\n          const wrapped = wrapMessageEntities(collectibleAttributes.original.message.text, collectibleAttributes.original.message.entities)\n          span.append(wrapRichText(wrapped.message, {entities: wrapped.totalEntities}));\n          args.push(span);\n        }\n\n        return (\n          <div class={classNames('popup-star-gift-info-original', saved?.drop_original_details_stars && 'has-delete')}>\n            <I18nTsx key={key} args={args} />\n            {saved?.drop_original_details_stars && (\n              <ButtonIconTsx\n                icon=\"delete\"\n                onClick={async() => {\n                  const popup = await PopupPayment.create({\n                    inputInvoice: {\n                      _: 'inputInvoiceStarGiftDropOriginalDetails',\n                      stargift: input\n                    }\n                  });\n\n                  popup.addEventListener('finish', (result) => {\n                    if(result === 'paid') {\n                      setOriginalDetails(undefined);\n                      delete collectibleAttributes.original\n                    }\n                  });\n                }}\n              />\n            )}\n          </div>\n        )\n      }\n\n      if(saved?.message) {\n        return wrapRichText(saved.message.text, {entities: saved.message.entities});\n      }\n    }\n\n    const handleShare = () => {\n      showSharingPicker2Popup().then(({peerId, threadId, monoforumThreadId}) => {\n        rootScope.managers.appMessagesManager.sendText({peerId, threadId, replyToMonoforumPeerId: monoforumThreadId, text: 'https://t.me/nft/' + (gift as StarGift.starGiftUnique).slug});\n        appImManager.setInnerPeer({peerId, threadId, monoforumThreadId});\n        this.hide();\n      });\n    }\n\n    const handleSell = async(changePrice = false) => {\n      if(!isEditableUniqueGift || !saved) return;\n\n      if(isListed() && !changePrice) {\n        await confirmationPopup({\n          titleLangKey: 'StarGiftUnlistTitle',\n          titleLangArgs: [getCollectibleName(gift as StarGift.starGiftUnique)],\n          descriptionLangKey: 'StarGiftUnlistText',\n          button: {\n            langKey: 'StarGiftUnlistConfirm'\n          }\n        });\n        await this.managers.appGiftsManager.updateResalePrice(input, null);\n        createSnackbar({\n          icon: 'tag_alt_crossed',\n          textElement: i18n('StarGiftResaleRemoved', [getCollectibleName(gift as StarGift.starGiftUnique)])\n        })\n        return\n      }\n\n      const now = tsNow(true);\n      if(saved.can_resell_at !== undefined && saved.can_resell_at > now) {\n        toastNew({\n          langPackKey: 'StarGiftResaleCooldown',\n          langPackArguments: [wrapFormattedDuration(formatDuration(saved.can_resell_at - now, 2))]\n        });\n        return\n      }\n\n      const popup = PopupElement.createPopup(PopupSellStarGift, {gift: this.gift, allowUnlist: changePrice})\n      popup.addEventListener('finish', (result) => {\n        if(result !== 'cancel') {\n          createSnackbar({\n            icon: result === 'list' ? 'tag_alt' : 'tag_alt_crossed',\n            textElement: i18n(\n              result === 'list' ? 'StarGiftResaleListed' : 'StarGiftResaleRemoved',\n              [getCollectibleName(gift as StarGift.starGiftUnique)]\n            )\n          })\n        }\n      })\n    }\n\n    const createSnackbar = (params: Omit<Parameters<typeof setQuizHint>[0], 'appendTo' | 'from'>) => {\n      return setQuizHint({\n        class: 'popup-star-gift-info-snackbar',\n        appendTo: this.container,\n        from: 'bottom',\n        duration: 5000,\n        ...params\n      });\n    }\n\n    let stickerContainer!: HTMLDivElement;\n    onMount(() => {\n      if(isEditableUniqueGift) {\n        // ! preload options for resale floor price\n        this.managers.appGiftsManager.getStarGiftOptions().catch(() => {})\n      }\n\n      wrapSticker({\n        doc: sticker,\n        div: stickerContainer,\n        width: 120,\n        height: 120,\n        play: !this.upgradeAnimation,\n        needFadeIn: !!this.upgradeAnimation,\n        middleware: this.middlewareHelper.get()\n      })\n    })\n\n    let confetti!: ConfettiRef;\n\n    return (\n      <div class={`popup-star-gift-info-container ${gift._ === 'starGiftUnique' ? 'is-collectible' : ''}`}>\n        <ConfettiContainer ref={confetti} />\n        <div class=\"popup-star-gift-info-header\">\n          {gift._ === 'starGiftUnique' && (\n            <StarGiftBackdrop\n              class=\"popup-star-gift-info-backdrop\"\n              backdrop={collectibleAttributes.backdrop}\n              patternEmoji={collectibleAttributes.pattern.document as MyDocument}\n            />\n          )}\n          <div\n            class=\"popup-star-gift-info-sticker\"\n            classList={{hide: !upgradeAnimationComplete()}}\n            ref={stickerContainer}\n          />\n          {this.upgradeAnimation && !upgradeAnimationComplete() && (\n            <UpgradeAnimation\n              preview={this.upgradeAnimation}\n              actualModel={collectibleAttributes.model}\n              actualBackdrop={collectibleAttributes.backdrop}\n              onReady={() => setUpgradeAnimationStarted(true)}\n              onComplete={() => setUpgradeAnimationComplete(true)}\n              confetti={confetti}\n            />\n          )}\n          {isListed() && (\n            <button class=\"popup-star-gift-info-change-price\" onClick={() => handleSell(true)}>\n              {resellOnlyTon() ?\n                paymentsWrapCurrencyAmount(resellPriceTon(), TON_CURRENCY) :\n                paymentsWrapCurrencyAmount(resellPriceStars(), STARS_CURRENCY)}\n            </button>\n          )}\n          <ButtonIconTsx\n            class=\"popup-star-gift-info-close\"\n            icon=\"close\"\n            onClick={() => this.hide()}\n          />\n          <ButtonMenuToggleTsx\n            class=\"popup-star-gift-info-menu-toggle\"\n            icon=\"more\"\n            direction=\"bottom-left\"\n            buttons={[\n              {\n                icon: saved?.pFlags.pinned_to_top ? 'unpin' : 'pin',\n                text: saved?.pFlags.pinned_to_top ? 'StarGiftUnpin' : 'StarGiftPin',\n                verify: () => isEditableUniqueGift,\n                onClick: () => {\n                  if(ownerPeerId === undefined) return;\n                  this.managers.appGiftsManager.togglePinnedGift(input, ownerPeerId).then(() => {\n                    this.hide();\n                  });\n                }\n              },\n              {\n                icon: 'tag_alt_outline',\n                text: 'StarGiftChangePrice',\n                verify: () => isEditableUniqueGift && isListed(),\n                onClick: () => handleSell(true)\n              },\n              {\n                icon: 'tag_alt_outline',\n                text: 'StarGiftOffer.CreateOffer',\n                verify: () => gift._ === 'starGiftUnique' && gift.offer_min_stars !== undefined,\n                onClick: () => showCreateStarGiftOfferPopup({\n                  gift: this.gift,\n                  onFinish: (res) => res === 'created' && this.hide()\n                })\n              },\n              {\n                icon: 'forward',\n                text: 'ShareFile',\n                onClick: handleShare\n              },\n              {\n                icon: 'link',\n                text: 'CopyLink',\n                onClick: () => {\n                  copyTextToClipboard('https://t.me/nft/' + (gift as StarGift.starGiftUnique).slug);\n                  toastNew({langPackKey: 'LinkCopied'});\n                }\n              }\n            ]}\n          />\n\n          <div class=\"popup-star-gift-info-title\">\n            {gift._ === 'starGift' ?\n              i18n(isUnavailable ? 'StarGiftUnavailableTitle' : isIncoming ? 'StarGiftReceivedTitle' : 'StarGiftTitle') :\n              gift.title\n            }\n          </div>\n\n          <Show when={gift._ ==='starGift'}>\n            {isUnavailable ? (\n            <div class=\"popup-star-gift-info-subtitle-unavailable\">\n              {i18n('StarGiftUnavailableSubtitle')}\n            </div>\n          ) : (\n            <div class=\"popup-star-gift-info-price\">\n              <StarsStar />\n              {starsValue}\n            </div>\n          )}\n            {isIncoming && !isConverted && (\n              <div class=\"popup-star-gift-info-subtitle\">\n                {i18n('StarGiftReceivedSubtitle', [saved.convert_stars])}\n                {' '}\n                <a href=\"https://telegram.org/blog/telegram-stars\" target=\"_blank\">\n                  {i18n('StarGiftReceivedSubtitleLink')}\n                </a>\n              </div>\n            )}\n          </Show>\n\n          {gift._ === 'starGiftUnique' && (\n            <div class=\"popup-star-gift-info-subtitle\">\n              {\n                gift.released_by ?\n                  <I18nTsx\n                    key=\"StarGiftCollectibleNumWithAuthor\"\n                    args={[\n                      this.upgradeAnimation ? (\n                        <AnimatedCollectibleNumber targetNumber={gift.num} started={upgradeAnimationStarted()} />\n                      ) : numberThousandSplitter(gift.num, ','),\n                      <PeerTitleTsx\n                        peerId={getPeerId(gift.released_by)}\n                        username\n                        onClick={() => {\n                          appImManager.setInnerPeer({peerId: getPeerId(gift.released_by)})\n                          this.hide()\n                        }}\n                      />\n                    ]}\n                  /> :\n                  <I18nTsx\n                    key=\"StarGiftCollectibleNum\"\n                    args={[\n                      this.upgradeAnimation ? (\n                        <AnimatedCollectibleNumber targetNumber={gift.num} started={upgradeAnimationStarted()} />\n                      ) : numberThousandSplitter(gift.num, ',')\n                    ]}\n                  />\n              }\n            </div>\n          )}\n\n          {isEditableUniqueGift && (\n            <div class=\"popup-star-gift-info-actions\">\n              <Button\n                noRipple\n                class=\"popup-star-gift-info-action\"\n                icon=\"gem_transfer\"\n                text=\"StarGiftTransfer\"\n                onClick={() => transferStarGift(this.gift).then((ok) => {\n                  if(ok) {\n                    this.hide();\n                  }\n                })}\n              />\n              <Button\n                noRipple\n                class=\"popup-star-gift-info-action\"\n                icon={isWearing() ? 'crownoff' : 'crown'}\n                text={isWearing() ? 'StarGiftWearStop' : 'StarGiftWear'}\n                onClick={async() => {\n                  if(ownerPeerId === undefined) return;\n                  if(isWearing()) {\n                    if(ownerPeerId === rootScope.myId) {\n                      rootScope.managers.appUsersManager.updateEmojiStatus({_: 'emojiStatusEmpty'});\n                    } else {\n                      rootScope.managers.apiManager.invokeApiSingleProcess({\n                        method: 'channels.updateEmojiStatus',\n                        params: {\n                          channel: await rootScope.managers.appChatsManager.getChannelInput(ownerPeerId.toChatId()),\n                          emoji_status: {_: 'emojiStatusEmpty'}\n                        }\n                      }).then((updates) => {\n                        rootScope.managers.apiUpdatesManager.processUpdateMessage(updates);\n                      }).catch(() => {\n                        toastNew({langPackKey: 'Error.AnError'});\n                      });\n                    }\n                  } else {\n                    PopupStarGiftWear.open(this.gift, ownerPeerId)\n                  }\n                }}\n              />\n              <Button\n                noRipple\n                class=\"popup-star-gift-info-action\"\n                icon={isListed() ? 'tag_alt_crossed' : 'tag_alt'}\n                text={isListed() ? 'StarGiftUnlistButton' : 'StarGiftSell'}\n                onClick={() => handleSell()}\n              />\n            </div>\n          )}\n        </div>\n\n        <div class=\"popup-star-gift-info-table\">\n          <Table\n            content={tableContent()}\n            footer={tableFooter()}\n            cellClass=\"popup-star-gift-info-table-cell\"\n            footerClass={gift._ === 'starGiftUnique' ? 'popup-star-gift-info-footer-unique' : undefined}\n          />\n        </div>\n\n        {canSave && (\n          <div class=\"popup-star-gift-info-hint\">\n            {saved.pFlags.unsaved ? i18n('StarGiftHiddenHint') : i18n('StarGiftVisibleHint')}\n            {' '}\n            <a href=\"#\" onClick={toggleGiftHidden}>\n              {i18n(saved.pFlags.unsaved ? 'StarGiftVisibleShowLink' : 'StarGiftVisibleHideLink')}\n            </a>\n          </div>\n        )}\n\n        {saved.pFlags.name_hidden && (\n          <div class=\"popup-star-gift-info-hint\">\n            {i18n('StarGiftHiddenSender')}\n          </div>\n        )}\n      </div>\n    );\n  }\n\n  private async construct() {\n    this.header.remove();\n    const gift = this.gift.raw;\n    const [value, canManageGifts] = await Promise.all([\n      gift._ === 'starGiftUnique' ? this.managers.appGiftsManager.getGiftValue(gift.slug) : Promise.resolve(null),\n      this.gift.ownerId !== undefined ? getCanManagePeerGifts(this.gift.ownerId) : Promise.resolve(false)\n    ]);\n    this.appendSolid(() => this._construct({value, canManageGifts}));\n\n    if(this.isResale) {\n      const resaleRecipient = this.resaleRecipient ?? rootScope.myId;\n      this.btnConfirm.classList.add('popup-star-gift-info-resale-button');\n      this.btnConfirm.replaceChildren(\n        i18n(resaleRecipient !== rootScope.myId ? 'StarGiftResaleSend' : 'StarGiftResaleBuy', [\n          this.gift.resellOnlyTon ?\n            paymentsWrapCurrencyAmount(this.gift.resellPriceTon, TON_CURRENCY) :\n            paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY)\n        ])\n      )\n\n      if(this.gift.resellOnlyTon) {\n        this.btnConfirm.classList.add('popup-star-gift-info-resale-button-twoline');\n        const span = i18n('StarGiftResaleStarsAmount', [\n          paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY)\n        ])\n        span.classList.add('popup-star-gift-info-resale-stars-amount');\n        this.btnConfirm.append(span);\n      }\n    } else if(this.canUpgrade) {\n      this.btnConfirm.replaceChildren(\n        i18n(this.gift.saved?.prepaid_upgrade_hash ? 'StarGiftGiftUpgrade' : 'StarGiftStatusUpgrade'),\n        Icon('arrow_up_circle_fill')\n      )\n    }\n\n    this.show();\n  }\n}\n","import type {MyStarGift} from '@appManagers/appGiftsManager';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport rootScope from '@lib/rootScope';\nimport PopupPayment from '@components/popups/payment';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport {MessageAction, StarGift} from '@layer';\nimport {toastNew} from '@components/toast';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport formatDuration from '@helpers/formatDuration';\nimport tsNow from '@helpers/tsNow';\nimport PopupElementOld from '@components/popups/index';\nimport Row from '@components/row';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\nimport {passwordPopup} from '@components/popups/password';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport {createMemo, createSignal} from 'solid-js';\nimport PopupElement, {createPopup} from '@components/popups/indexTsx';\n\nimport styles from '@components/popups/transferStarGift.module.scss'\nimport {i18n} from '@lib/langPack';\nimport {StarGiftTransferPreview} from '@components/stargifts/transferPreview';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport Table, {TableRow} from '@components/table';\nimport {AttributeValue} from '@components/popups/starGiftInfo';\nimport paymentsWrapCurrencyAmount, {formatNanoton} from '@helpers/paymentsWrapCurrencyAmount';\nimport {FloatingStarsBalance} from '@components/popups/floatingStarsBalance';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {useAppConfig} from '@stores/appState';\nimport bigInt from 'big-integer';\nimport {STARS_CURRENCY, TON_CURRENCY} from '@appManagers/constants';\n\nexport function transferStarGiftConfirmationPopup(options: {\n  gift: MyStarGift,\n  recipient: PeerId,\n  fromOffer?: MessageAction.messageActionStarGiftPurchaseOffer\n  handleSubmit: () => MaybePromise<void>\n  handleCancel?: () => MaybePromise<void>\n}) {\n  const appConfig = useAppConfig()\n  const [show, setShow] = createSignal(false);\n  const isFreeTransfer = !options.fromOffer && Number(options.gift.saved?.transfer_stars ?? '0') === 0\n  let submitted = false\n\n  const tableContent = createMemo(() => {\n    const {gift: {raw: gift, collectibleAttributes}} = options\n    if(gift._ !== 'starGiftUnique') return []\n\n    const rows: TableRow[] = [\n      ['StarGiftModel', (\n        <AttributeValue\n          name={collectibleAttributes.model.name}\n          rarity={collectibleAttributes.model.rarity}\n        />\n      )],\n      ['StarGiftBackdrop', (\n        <AttributeValue\n          name={collectibleAttributes.backdrop.name}\n          rarity={collectibleAttributes.backdrop.rarity}\n        />\n      )],\n      ['StarGiftPattern', (\n        <AttributeValue\n          name={collectibleAttributes.pattern.name}\n          rarity={collectibleAttributes.pattern.rarity}\n        />\n      )]\n    ];\n\n    if(gift.value_amount) {\n      rows.push([\n        'StarGiftValue',\n        `~${paymentsWrapCurrencyAmount(gift.value_amount, gift.value_currency)}`\n      ]);\n    }\n\n    return rows\n  })\n\n  const popupText = () => {\n    if(options.fromOffer) {\n      let amount: HTMLElement\n      let amountAfterComission: HTMLElement\n\n      if(options.fromOffer.price._ === 'starsTonAmount') {\n        amount = i18n('SuggestedPosts.TONAmount', [formatNanoton(options.fromOffer.price.amount, 2)])\n        const commission = appConfig.ton_stargift_resale_commission_permille;\n        const nanotonAfter = bigInt(options.fromOffer.price.amount as number).multiply(commission).divide(1000).toString()\n        amountAfterComission = i18n('SuggestedPosts.TONAmount', [formatNanoton(nanotonAfter, 2)])\n      } else {\n        amount = i18n('Stars', [numberThousandSplitterForStars(options.fromOffer.price.amount)])\n        const commission = appConfig.stars_stargift_resale_commission_permille;\n        amountAfterComission = i18n('Stars', [numberThousandSplitterForStars(Math.floor(\n          Number(options.fromOffer.price.amount) * (commission / 1000))\n        )])\n      }\n\n      return (\n        <I18nTsx\n          class={styles.text}\n          key=\"StarGiftOffer.AcceptOfferText\"\n          args={[\n            getCollectibleName(options.gift.raw as StarGift.starGiftUnique),\n            <PeerTitleTsx peerId={options.recipient} onlyFirstName />,\n            amount,\n            amountAfterComission\n          ]}\n        />\n      )\n    }\n\n    return (\n      <I18nTsx\n        class={styles.text}\n        key={isFreeTransfer ? 'StarGiftConfirmFreeTransferText' : 'StarGiftConfirmTransferPopupText'}\n        args={[\n          getCollectibleName(options.gift.raw as StarGift.starGiftUnique),\n          <PeerTitleTsx peerId={options.recipient} onlyFirstName />,\n          i18n('Stars', [numberThousandSplitterForStars(options.gift.saved.transfer_stars)])\n        ]}\n      />\n    )\n  }\n\n  const submitButtonText = () => {\n    if(options.fromOffer) {\n      const ton = options.fromOffer.price._ === 'starsTonAmount'\n\n      return (\n        <I18nTsx\n          key=\"StarGiftOffer.AcceptOfferButton\"\n          args={[\n            paymentsWrapCurrencyAmount(options.fromOffer.price.amount, ton ? TON_CURRENCY : STARS_CURRENCY)\n          ]}\n        />\n      );\n    }\n\n    if(isFreeTransfer) return <I18nTsx key=\"StarGiftTransferFull\" />\n\n    return (\n      <I18nTsx\n        key=\"StarGiftTransferFullFor\"\n        args={[paymentsWrapCurrencyAmount(options.gift.saved.transfer_stars, STARS_CURRENCY)]}\n      />\n    )\n  }\n\n  createPopup(() => {\n    doubleRaf().then(() => setShow(true));\n    return (\n      <PopupElement\n        class={styles.popup}\n        containerClass={styles.popupContainer}\n        show={show()}\n        onClose={() => {\n          if(!submitted) {\n            options.handleCancel?.()\n          }\n        }}\n      >\n        <FloatingStarsBalance class={styles.starsBalance} />\n        <PopupElement.Body>\n          <StarGiftTransferPreview\n            class={styles.graph}\n            gift={options.gift}\n            recipient={options.recipient}\n          />\n\n          {popupText()}\n\n          <div class={styles.table}>\n            <Table content={tableContent()} />\n          </div>\n        </PopupElement.Body>\n        <PopupElement.Buttons class={styles.buttons}>\n          <PopupElement.Button callback={() => {\n            submitted = true\n            return options.handleSubmit()\n          }}>\n            {submitButtonText()}\n          </PopupElement.Button>\n          <PopupElement.Button cancel callback={() => {\n            submitted = true\n            options.handleCancel?.()\n          }}>\n            <I18nTsx key=\"Cancel\" />\n          </PopupElement.Button>\n        </PopupElement.Buttons>\n      </PopupElement>\n    )\n  })\n}\n\nexport default function transferStarGift(gift: MyStarGift, toPeerId?: PeerId): Promise<boolean> {\n  const {saved, input} = gift;\n  const raw = gift.raw as StarGift.starGiftUnique;\n\n  const now = tsNow(true);\n  if(saved.can_transfer_at !== undefined && saved.can_transfer_at > now) {\n    toastNew({\n      langPackKey: 'StarGiftTransferCooldown',\n      langPackArguments: [wrapFormattedDuration(formatDuration(saved.can_transfer_at - now, 2))]\n    });\n    return Promise.resolve(false);\n  }\n\n  const deferred = deferredPromise<boolean>();\n  let peerSelectorResolved = false;\n  async function handleSelection(peerId: PeerId | 'fragment') {\n    if(peerSelectorResolved) return;\n    peerSelectorResolved = true;\n\n    if(peerId === 'fragment') {\n      try {\n        await confirmationPopup({\n          titleLangKey: 'StarGiftFragmentTransferTitle',\n          descriptionLangKey: 'StarGiftFragmentTransferText',\n          descriptionLangArgs: [getCollectibleName(raw)],\n          button: {\n            langKey: 'StarGiftFragmentTransferConfirm'\n          }\n        })\n\n        const url = await passwordPopup({\n          titleLangKey: 'PleaseEnterCurrentPassword',\n          descriptionLangKey: 'StarGiftFragmentTransferPassword',\n          descriptionLangArgs: [getCollectibleName(raw)],\n          button: {\n            langKey: 'Confirm'\n          },\n          callback: (password) => rootScope.managers.apiManager.invokeApi('payments.getStarGiftWithdrawalUrl', {\n            stargift: input,\n            password: password\n          })\n        })\n\n        safeWindowOpen(url.url);\n\n        deferred.resolve(true);\n      } catch(e) {\n        deferred.resolve(false);\n      }\n      return\n    }\n\n    transferStarGiftConfirmationPopup({\n      gift,\n      recipient: peerId,\n      handleSubmit: async() => {\n        const inputPeer = await rootScope.managers.appPeersManager.getInputPeerById(peerId);\n\n        if(Number(saved?.transfer_stars ?? '0') === 0) {\n          await rootScope.managers.appGiftsManager.transferStarGift(gift.input, peerId, gift.ownerId);\n          deferred.resolve(true)\n        } else {\n          const popup = await PopupPayment.create({\n            inputInvoice: {\n              _: 'inputInvoiceStarGiftTransfer',\n              stargift: gift.input,\n              to_id: inputPeer\n            },\n            noShowIfStars: true\n          });\n\n          popup.addEventListener('finish', (result) => {\n            if(result === 'paid') {\n              if(gift.ownerId !== undefined) {\n                rootScope.dispatchEvent('star_gift_list_update', {peerId: gift.ownerId});\n              }\n              rootScope.dispatchEvent('star_gift_list_update', {peerId});\n              deferred.resolve(true);\n            } else {\n              deferred.resolve(false);\n            }\n          });\n        }\n      },\n      handleCancel: () => deferred.resolve(false)\n    })\n  }\n\n  if(toPeerId) {\n    handleSelection(toPeerId);\n    return deferred;\n  }\n\n  const isOwnedByChannel = gift.ownerId && gift.ownerId.isAnyChat();\n\n  const popup = showPickUserPopup({\n    placeholder: 'StarGiftTransferTo',\n    onSelect: ([{peerId}]) => handleSelection(peerId),\n    exceptSelf: !isOwnedByChannel,\n    selfPresence: 'StarGiftTransferToMyself',\n    filterPeerTypeBy: ['isRegularUser', 'isBroadcast'],\n    titleLangKey: 'StarGiftTransferTo',\n    onClose: () => {\n      if(!peerSelectorResolved) {\n        deferred.resolve(false);\n      }\n    }\n  });\n\n  if(saved.can_export_at !== undefined && saved.can_export_at < now) {\n    const fragmentRow = new Row({\n      titleLangKey: 'StarGiftFragmentTransferItem',\n      icon: 'ton',\n      clickable: () => {\n        handleSelection('fragment');\n        popup.hide();\n      }\n    });\n    popup.selector.list.before(fragmentRow.container);\n  }\n\n  return deferred;\n}\n","import contextMenuController from '@helpers/contextMenuController';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {FloatingMenuDirection, positionFloatingMenu} from '@helpers/positionMenu';\nimport {doubleRaf} from '@helpers/schedulers';\n\nexport type FloatingButtonMenuDirection = FloatingMenuDirection;\n\nexport type AttachFloatingButtonMenuOptions = {\n  element: HTMLElement;\n  triggerEvent: keyof HTMLElementEventMap;\n  direction: FloatingButtonMenuDirection;\n  level: number;\n  offset?: [number, number];\n  createMenu: () => HTMLElement | Promise<HTMLElement>;\n  canOpen?: () => boolean;\n  onClose?: () => void;\n};\n\nexport default function attachFloatingButtonMenu({\n  element,\n  triggerEvent,\n  direction,\n  level,\n  offset = [0, 0],\n  createMenu,\n  canOpen = () => true,\n  onClose: onCloseArg\n}: AttachFloatingButtonMenuOptions) {\n  let opened = false;\n  let hovered = false;\n  let requestId = 0;\n\n  const listener = (): void => void (async() => {\n    hovered = true;\n    if(opened || !canOpen()) return;\n    const currentRequestId = ++requestId;\n\n    const triggerBcr = element.getBoundingClientRect();\n\n    let menu: HTMLElement;\n    try {\n      menu = await createMenu();\n    } catch{}\n\n    if(\n      !menu ||\n      opened ||\n      currentRequestId !== requestId ||\n      !hovered ||\n      !canOpen()\n    ) {\n      return;\n    }\n\n    opened = true;\n\n    const onClose = async() => {\n      opened = false;\n      onCloseArg?.();\n    };\n\n    getOverlayRoot().append(menu);\n\n    positionFloatingMenu(triggerBcr, menu, direction, offset);\n\n    await doubleRaf();\n    contextMenuController.addAdditionalMenu(menu, element, level, onClose);\n  })();\n\n  const onMouseLeave = () => {\n    hovered = false;\n    ++requestId;\n  };\n\n  element.addEventListener(triggerEvent, listener);\n  if(triggerEvent === 'mouseenter') {\n    element.addEventListener('mouseleave', onMouseLeave);\n  }\n\n  return () => {\n    element.removeEventListener(triggerEvent, listener);\n    element.removeEventListener('mouseleave', onMouseLeave);\n  };\n}\n","import {CLICK_EVENT_NAME} from '@helpers/dom/clickEvent';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport pause from '@helpers/schedulers/pause';\nimport {i18n} from '@lib/langPack';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport attachFloatingButtonMenu, {FloatingButtonMenuDirection} from '@components/floatingButtonMenu';\nimport Icon from '@components/icon';\n\n\nlet submenuHelperIdSeed = 0;\n\nexport type CreateSubmenuArgs = {\n  middleware: Middleware;\n};\n\ntype CreateSubmenuTriggerArgs = {\n  options: Pick<ButtonMenuItemOptionsVerifiable, 'text' | 'regularText' | 'icon' | 'verify' | 'separator' | 'separatorDown' | 'onClose'>;\n  createSubmenu: (args: CreateSubmenuArgs) => MaybePromise<HTMLElement>;\n  direction?: FloatingButtonMenuDirection;\n};\n\nexport default function createSubmenuTrigger({\n  options,\n  createSubmenu,\n  direction = 'right-start'\n}: CreateSubmenuTriggerArgs) {\n  let\n    isDisabled = false,\n    currentMiddleware: MiddlewareHelper\n  ;\n\n  const onOpen = () => {\n    if(!menuBtnOptions.element) return;\n    currentMiddleware = getMiddleware();\n\n    menuBtnOptions.element.addEventListener(CLICK_EVENT_NAME, (e) => {\n      e.stopPropagation();\n    }, true);\n    menuBtnOptions.element.classList.add('submenu-trigger');\n\n    attachFloatingButtonMenu({\n      element: menuBtnOptions.element,\n      direction,\n      createMenu: async() => {\n        const menu = await createSubmenu({middleware: currentMiddleware.get()});\n        menu.classList.add('btn-menu-submenu');\n        return menu;\n      },\n      offset: [-5, -5],\n      level: 2,\n      triggerEvent: 'mouseenter',\n      canOpen: () => !isDisabled,\n      onClose: onClose\n    });\n  };\n\n  const onClose = async() => {\n    currentMiddleware?.destroy();\n    // Prevents hover from triggering when the menu is closing\n    isDisabled = true;\n    await pause(200);\n    isDisabled = false;\n  };\n\n  const menuBtnOptions: ButtonMenuItemOptionsVerifiable = {\n    ...options,\n\n    // * fix langpack\n    get regularText() {\n      const content = document.createElement('span');\n      content.classList.add('submenu-label');\n      const text = document.createElement('span');\n      text.classList.add('submenu-label-text');\n      text.append(options.regularText ?? i18n(options.text));\n      content.append(text, Icon('arrowhead'));\n      return content;\n    },\n    onClick: noop,\n    onOpen,\n    onClose,\n    id: submenuHelperIdSeed++\n  };\n\n  delete menuBtnOptions.text;\n\n  return menuBtnOptions;\n}\n","import {createMemo, For, onCleanup, onMount} from 'solid-js';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {StarsStar} from '@components/popups/stars';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {i18n} from '@lib/langPack';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport rootScope from '@lib/rootScope';\n\nimport styles from '@components/stargifts/stargiftsGrid.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport {StarGiftBadge} from '@components/stargifts/stargiftBadge';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {IconTsx} from '@components/iconTsx';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {changeBrightness, getRgbColorFromTelegramColor, rgbaToHexa, rgbIntToHex} from '@helpers/color';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {showSharingPicker2Popup} from '@components/popups/pickUser';\nimport appImManager from '@lib/appImManager';\nimport {StarGift, StarGiftCollection} from '@layer';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\nimport transferStarGift from '@components/popups/transferStarGift';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport tsNow from '@helpers/tsNow';\nimport PopupStarGiftWear from '@components/popups/starGiftWear';\nimport createSubmenuTrigger from '@components/createSubmenuTrigger';\nimport {ButtonMenuItemOptions, ButtonMenuItemOptionsVerifiable, ButtonMenuSync} from '@components/buttonMenu';\nimport CheckboxField from '@components/checkboxField';\n\nfunction StarGiftGridItem(props: {\n  item: MyStarGift,\n  view: 'profile' | 'list' | 'resale' | 'transfer'\n  profilePeerId?: PeerId\n  canManageGifts?: boolean\n  profileCollections?: StarGiftCollection[]\n  hasSelection?: boolean\n  selected?: boolean\n  onClick?: () => void\n  renderer: SuperStickerRenderer\n}) {\n  const profileCollections = createMemo(() => props.profileCollections ?? []);\n  let containerRef!: HTMLDivElement;\n  let stickerRef!: HTMLDivElement;\n\n  onMount(() => {\n    props.renderer.renderSticker(props.item.sticker, stickerRef);\n    props.renderer.observeAnimated(stickerRef);\n\n    if(props.view === 'profile' && !props.hasSelection) {\n      const {raw, saved, input, isIncoming, isWearing} = props.item;\n      const profilePeerId = props.profilePeerId ?? rootScope.myId;\n      const isEditableUniqueGift = Boolean(raw._ === 'starGiftUnique' && props.canManageGifts && saved);\n\n      const buttons: ButtonMenuItemOptionsVerifiable[] = [\n        {\n          icon: 'forward',\n          text: 'ShareFile',\n          verify: () => raw._ === 'starGiftUnique',\n          onClick: () => {\n            showSharingPicker2Popup().then(({peerId, threadId, monoforumThreadId}) => {\n              rootScope.managers.appMessagesManager.sendText({peerId, threadId, replyToMonoforumPeerId: monoforumThreadId, text: 'https://t.me/nft/' + (raw as StarGift.starGiftUnique).slug});\n              appImManager.setInnerPeer({peerId, threadId, monoforumThreadId});\n            });\n          }\n        },\n        {\n          icon: saved?.pFlags.pinned_to_top ? 'unpin' : 'pin',\n          text: saved?.pFlags.pinned_to_top ? 'StarGiftUnpin' : 'StarGiftPin',\n          verify: () => isEditableUniqueGift,\n          onClick: () => {\n            rootScope.managers.appGiftsManager.togglePinnedGift(input, profilePeerId);\n          }\n        },\n        {\n          icon: 'link',\n          text: 'CopyLink',\n          verify: () => raw._ === 'starGiftUnique',\n          onClick: () => {\n            copyTextToClipboard('https://t.me/nft/' + (raw as StarGift.starGiftUnique).slug);\n            toastNew({langPackKey: 'LinkCopied'});\n          }\n        },\n        {\n          icon: 'gem_transfer_outline',\n          text: 'StarGiftTransferFull',\n          verify: () => isEditableUniqueGift,\n          onClick: () => {\n            transferStarGift(props.item);\n          }\n        },\n        createSubmenuTrigger({\n          options: {\n            icon: 'folder',\n            text: 'StarGiftCollectionsAddToCollection',\n            verify: () => isEditableUniqueGift && profileCollections().length > 0\n          },\n          createSubmenu: () => {\n            if(!saved || !input || !props.profilePeerId || !profileCollections().length) {\n              return ButtonMenuSync({buttons: []});\n            }\n\n            const buttons: ButtonMenuItemOptions[] = profileCollections().map((collection) => {\n              const checkboxField = new CheckboxField({\n                checked: !!saved.collection_id?.includes(collection.collection_id)\n              });\n\n              return {\n                regularText: collection.title,\n                onClick: () => {\n                  const wasChecked = checkboxField.checked;\n                  checkboxField.checked = !wasChecked;\n                  rootScope.managers.appGiftsManager.updateCollection({\n                    peerId: props.profilePeerId,\n                    collectionId: collection.collection_id,\n                    [wasChecked ? 'delete' : 'add']: [input]\n                  }).catch(() => {\n                    checkboxField.checked = wasChecked;\n                    toastNew({langPackKey: 'Error.AnError'});\n                  });\n                },\n                checkboxField,\n                noCheckboxClickListener: true,\n                keepOpen: true\n              };\n            });\n\n            return ButtonMenuSync({buttons});\n          }\n        }),\n        {\n          icon: isWearing ? 'crownoff_outline' : 'crown_outline',\n          text: isWearing ? 'StarGiftWearStopFull' : 'StarGiftWearFull',\n          verify: () => isEditableUniqueGift,\n          onClick: async() => {\n            if(isWearing) {\n              if(profilePeerId === rootScope.myId) {\n                rootScope.managers.appUsersManager.updateEmojiStatus({_: 'emojiStatusEmpty'});\n              } else {\n                rootScope.managers.apiManager.invokeApiSingleProcess({\n                  method: 'channels.updateEmojiStatus',\n                  params: {\n                    channel: await rootScope.managers.appChatsManager.getChannelInput(profilePeerId.toChatId()),\n                    emoji_status: {_: 'emojiStatusEmpty'}\n                  }\n                }).then((updates) => {\n                  rootScope.managers.apiUpdatesManager.processUpdateMessage(updates);\n                }).catch(() => {\n                  toastNew({langPackKey: 'Error.AnError'});\n                });\n              }\n            } else {\n              PopupStarGiftWear.open(props.item, profilePeerId);\n            }\n          }\n        },\n        {\n          icon: saved.pFlags.unsaved ? 'eye' : 'eyecross_outline',\n          text: saved.pFlags.unsaved ? 'Show' : 'Hide',\n          verify: () => isIncoming || isEditableUniqueGift,\n          onClick: () => {\n            rootScope.managers.appGiftsManager.toggleGiftHidden(input, !saved.pFlags.unsaved);\n          }\n        }\n      ];\n\n      createContextMenu({\n        listenTo: containerRef,\n        buttons,\n        onElementReady: () => {\n          buttons.forEach((button) => button.onOpen?.());\n        }\n      })\n    }\n  })\n\n  const isPinned = () => props.item.saved?.pFlags.pinned_to_top;\n  const isPremium = () => props.view === 'list' && props.item.raw._ === 'starGift' && props.item.raw.pFlags.require_premium && props.item.raw.availability_remains > 0;\n  const isLocked = () => props.view === 'list' && props.item.raw._ === 'starGift' && props.item.raw.locked_until_date > tsNow(true);\n\n  return (\n    <div\n      class={/* @once */ classNames(\n        styles.gridItem,\n        {\n          profile: styles.viewProfile,\n          transfer: styles.viewTransfer,\n          list: styles.viewList,\n          resale: styles.viewResale\n        }[props.view],\n        isPremium() && styles.itemPremium\n      )}\n      style={{\n        '--overlay-color': rgbaToHexa(changeBrightness(getRgbColorFromTelegramColor(props.item.collectibleAttributes?.backdrop?.edge_color ?? 0), 0.9))\n      }}\n      onClick={props.onClick}\n      ref={containerRef}\n    >\n      {props.hasSelection && (\n        <CheckboxFieldTsx\n          round\n          class={/* @once */ styles.checkbox}\n          checked={props.selected}\n        />\n      )}\n\n      {isPremium() && (\n        <div class={/* @once */ styles.itemPremiumBackground} />\n      )}\n\n      {props.item.collectibleAttributes && (\n        <StarGiftBackdrop\n          class={/* @once */ styles.itemBackdrop}\n          small\n          backdrop={props.item.collectibleAttributes.backdrop}\n          patternEmoji={props.item.collectibleAttributes.pattern.document as MyDocument}\n        />\n      )}\n\n      {isPinned() && !props.item.resellOnlyTon && (\n        <IconTsx icon=\"pin2\" class={/* @once */ styles.itemPin} />\n      )}\n\n      {isLocked() && (\n        <IconTsx icon=\"time_lock\" class={/* @once */ styles.itemLock} />\n      )}\n\n      {props.item.resellOnlyTon && props.view !== 'transfer' && (\n        <div class={/* @once */ styles.tonIcon}>\n          <IconTsx icon=\"ton\" />\n        </div>\n      )}\n\n      {props.view === 'profile' && props.item.saved?.pFlags.unsaved && (\n        <IconTsx icon=\"hide\" class={/* @once */ styles.itemUnsaved} />\n      )}\n      <div\n        class={/* @once */ styles.itemSticker}\n        ref={stickerRef}\n      />\n\n      {props.view === 'list' && props.item.raw._ === 'starGift' && (\n        <div class={/* @once */ styles.itemPrice}>\n          {/* todo: huge performance hit */}\n          {/* {props.view === 'list' && (\n            <Sparkles mode='button' isDiv />\n          )} */}\n          <StarsStar />\n          <span>{\n            props.item.isResale && props.item.raw.resell_min_stars ?\n              `${numberThousandSplitterForStars(props.item.raw.resell_min_stars)}+` :\n              numberThousandSplitterForStars(props.item.raw.stars)\n          }</span>\n        </div>\n      )}\n\n      {props.item.resellPriceStars && props.view !== 'transfer' && (\n        <div class={/* @once */ styles.itemPrice}>\n          <IconTsx icon=\"star\" />\n          <span>{numberThousandSplitterForStars(props.item.resellPriceStars)}</span>\n        </div>\n      )}\n\n      {props.view === 'transfer' && (\n        <div class={/* @once */ styles.itemPrice}>\n          {i18n('StarGiftTransferFull')}\n        </div>\n      )}\n\n      {props.view === 'profile' && props.item.raw._ === 'starGift' && !props.hasSelection && (\n        <div class={/* @once */ styles.itemFrom}>\n          {props.item.saved.from_id && !props.item.saved.pFlags.name_hidden ? (\n            <AvatarNewTsx\n              peerId={getPeerId(props.item.saved.from_id)}\n              size={20}\n            />\n          ) : (\n            <div class={/* @once */ styles.itemFromAnonymous}>\n              <img src=\"assets/img/anon_paid_reaction.png\" alt=\"Anonymous\" />\n            </div>\n          )}\n        </div>\n      )}\n\n      {(() => {\n        const gift = props.item.raw;\n        if(gift._ !== 'starGift') {\n          if(props.view === 'profile' && props.item.resellPriceStars) {\n            return (\n              <StarGiftBadge class={/* @once */ styles.badgeResale}>\n                {i18n('StarGiftResaleBadgeProfile')}\n              </StarGiftBadge>\n            )\n          }\n\n          return (\n            <StarGiftBadge\n              class={/* @once */ styles.badgeUnique}\n              backdropAttr={props.item.collectibleAttributes.backdrop}\n            >\n              {isPinned() || props.view === 'resale' ? `#${gift.num}` : i18n('StarGiftLimitedBadgeNum', [formatNumber(gift.availability_total, 1)])}\n            </StarGiftBadge>\n          );\n        };\n\n        if(props.view === 'list' && props.item.isResale) {\n          return (\n            <StarGiftBadge class={/* @once */ styles.badgeResale}>\n              {i18n('StarGiftResaleBadge')}\n            </StarGiftBadge>\n          )\n        }\n\n        if(isPremium()) {\n          return (\n            <StarGiftBadge class={/* @once */ styles.badgePremium}>\n              {i18n('StarGiftPremiumBadge')}\n            </StarGiftBadge>\n          )\n        }\n\n        if(props.view === 'list' && gift.availability_remains === 0) {\n          return (\n            <StarGiftBadge class={/* @once */ styles.badgeSoldout}>\n              {i18n('StarGiftSoldOutBadge')}\n            </StarGiftBadge>\n          )\n        }\n\n        if(props.item.raw.availability_total) {\n          return (\n            <StarGiftBadge>\n              {props.view === 'list' ? i18n('StarGiftLimitedBadge') : i18n('StarGiftLimitedBadgeNum', [formatNumber(gift.availability_total, 1)])}\n            </StarGiftBadge>\n          )\n        }\n      })()}\n    </div>\n  );\n}\n\nexport function StarGiftsGrid(props: {\n  class?: string\n  items: MyStarGift[],\n  view: 'profile' | 'list' | 'resale' | 'transfer'\n  autoplay?: boolean\n  onClick?: (item: MyStarGift) => void\n  selected?: (item: MyStarGift) => boolean\n  profilePeerId?: PeerId\n  canManageGifts?: boolean\n  profileCollections?: StarGiftCollection[]\n  scrollParent: HTMLElement\n}) {\n  const lazyLoadQueue = new LazyLoadQueue();\n  const stickerRenderer = new SuperStickerRenderer({\n    regularLazyLoadQueue: lazyLoadQueue,\n    group: 'none',\n    managers: rootScope.managers,\n    intersectionObserverInit: {root: props.scrollParent},\n    visibleRenderOptions: {\n      loop: false,\n      play: props.autoplay ?? true,\n      width: 120,\n      height: 120\n    },\n    withLock: false,\n    playOnHover: true\n  });\n\n  onCleanup(() => {\n    stickerRenderer.destroy();\n    lazyLoadQueue.clear();\n  });\n\n  return (\n    <div class={classNames(styles.grid, props.class)}>\n      <For each={props.items}>\n        {(item) => (\n          <StarGiftGridItem\n            item={item}\n            view={props.view}\n            profilePeerId={props.profilePeerId}\n            canManageGifts={props.canManageGifts}\n            profileCollections={props.profileCollections}\n            hasSelection={/* @once */ props.selected !== undefined}\n            selected={props.selected?.(item)}\n            onClick={() => props.onClick?.(item)}\n            renderer={stickerRenderer}\n          />\n        )}\n      </For>\n    </div>\n  )\n}\n","import {JSX, onMount} from 'solid-js';\nimport {ChatBackground} from '@components/chat/bubbles/chatBackground';\nimport rootScope from '@lib/rootScope';\nimport themeController from '@helpers/themeController';\n\nimport classNames from '@helpers/string/classNames';\nimport styles from '@components/chat/bubbles/fakeBubbles.module.scss';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\n\nexport function FakeBubbles(props: {\n  children: JSX.Element\n  class?: string\n  contentClass?: string\n  peerId?: PeerId\n}) {\n  let container!: HTMLDivElement;\n\n  onMount(() => {\n    themeController.applyTheme(themeController.getTheme(), container);\n    subscribeOn(rootScope)('theme_changed', () => {\n      themeController.applyTheme(themeController.getTheme(), container);\n    })\n  })\n\n  return (\n    <div ref={container} class={classNames(styles.root, props.class)}>\n      <ChatBackground\n        managers={rootScope.managers}\n        themeController={themeController}\n        peerId={props.peerId}\n        onHighlightColor={hsla => themeController.applyHighlightingColor({hsla, element: container})}\n      />\n      <div class={classNames(styles.content, props.contentClass)}>\n        {props.children}\n      </div>\n    </div>\n  )\n}\n","import {createEffect, createResource, JSX, on} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {Message} from '@layer';\n\nimport styles from '@components/chat/bubbles/service.module.scss';\nimport wrapMessageActionTextNew from '@components/wrappers/messageActionTextNew';\n\nexport function ServiceBubble(props: {\n  class?: string\n  message: Message.messageService\n  children?: JSX.Element\n}) {\n  const [text, {refetch}] = createResource(() => wrapMessageActionTextNew({\n    message: props.message\n  }))\n  createEffect(on(() => props.message, refetch))\n\n  return (\n    <div class={classNames(styles.wrap, props.class)}>\n      <div class={/* @once */ styles.text}>\n        {text()}\n      </div>\n      {props.children}\n    </div>\n  )\n}\n","import {createEffect, on} from 'solid-js';\nimport {template} from 'solid-js/web';\n\nexport interface Sparkle {\n  x: number;\n  y: number;\n  translateX: number;\n  translateY: number;\n  scale: number;\n  delay: number;\n  minOpacity?: number;\n}\n\ninterface ContainerSize {\n  width: number;\n  height: number;\n}\n\nconst BUTTON_SPARKLES: Sparkle[] = [\n  {x: 20, y: 0, scale: 1, delay: 500},\n  {x: 15, y: 15, scale: 0.75, delay: 3500},\n  {x: 10, y: 35, scale: 0.75, delay: 4500},\n  {x: 20, y: 70, scale: 1.25, delay: 1500},\n  {x: 40, y: 10, scale: 1.25, delay: 0},\n  {x: 45, y: 60, scale: 0.75, delay: 3000},\n  {x: 60, y: -10, scale: 1, delay: 1000},\n  {x: 55, y: 40, scale: 0.75, delay: 3000},\n  {x: 70, y: 65, scale: 1, delay: 4500},\n  {x: 80, y: 10, scale: 0.75, delay: 1500},\n  {x: 80, y: 45, scale: 1.25, delay: 0}\n].map((it) => ({\n  ...it,\n  translateX: Math.cos(Math.atan2(-50 + it.y, -50 + it.x)) * 100,\n  translateY: Math.sin(Math.atan2(-50 + it.y, -50 + it.x)) * 100\n}));\n\nexport function generateProgressSparkle(): Sparkle {\n  return {\n    x: Math.random() * 100,\n    y: Math.random() * 100,\n    translateX: (Math.random() * 5 + 15) * 100,\n    translateY: (Math.random() * 10 - 5) * 100,\n    scale: (Math.random() * 0.5 + 0.5),\n    delay: Math.random() * 5000\n  };\n}\n\n\nconst sparkleTemplate = template(`<svg viewBox=\"0 0 7 7\" xmlns=\"http://www.w3.org/2000/svg\" height=\"1em\" width=\"1em\"><use href=\"#star-sparkle\"></use></svg>`);\nfunction renderSparkle(\n  sparkle: Sparkle,\n  {isDiv, containerSize, fixedScale}: {isDiv?: boolean, containerSize?: ContainerSize, fixedScale?: boolean} = {}\n) {\n  let element: HTMLElement;\n  if(isDiv) {\n    element = document.createElement('div');\n    element.textContent = '✦';\n  } else {\n    element = sparkleTemplate() as HTMLElement;\n  }\n\n  element.classList.add('sparkles-sparkle');\n  element.style.setProperty('--sparkle-tx', containerSize ? sparkle.translateX / 100 * containerSize.width + 'px' : sparkle.translateX + '%');\n  element.style.setProperty('--sparkle-ty', containerSize ? sparkle.translateY / 100 * containerSize.height + 'px' : sparkle.translateY + '%');\n  element.style.setProperty('--sparkle-scale', fixedScale ? sparkle.scale + '' : sparkle.scale * (Math.random() * 0.5 + 0.25) + '');\n  element.style.setProperty('--sparkle-rotate', (Math.random() * 90 - 45) * 4 + 'deg');\n  if(sparkle.minOpacity) element.style.setProperty('--sparkle-min-opacity', sparkle.minOpacity + '');\n  element.style.transform = `scale(${sparkle.scale})`;\n  element.style.top = containerSize ? sparkle.y / 100 * containerSize.height + 'px' : sparkle.y + '%';\n  element.style.left = containerSize ? sparkle.x / 100 * containerSize.width + 'px' : sparkle.x + '%';\n  element.style.animationDelay = '-' + sparkle.delay + 'ms';\n  return element;\n}\n\nexport type SparklesProps = Parameters<typeof renderSparkle>[1] &\n  ({mode: 'button', sparkles?: Sparkle[], duration?: number} | {mode: 'progress', count: number});\n\nexport function Sparkles(props: SparklesProps): HTMLDivElement {\n  const container = document.createElement('div');\n  container.classList.add('sparkles-container');\n\n  const sparkleOptions: Parameters<typeof renderSparkle>[1] = {\n    ...props\n  };\n\n  if(props.mode === 'button') {\n    if(props.duration) {\n      container.style.setProperty('--sparkles-duration', props.duration + 'ms');\n    }\n    container.append(...(props.sparkles || BUTTON_SPARKLES).map((sparkle) => renderSparkle(sparkle, sparkleOptions)));\n  } else {\n    createEffect(on(() => props.count, (next, prev = 0) => {\n      const diff = next - prev;\n      if(diff > 0) {\n        for(let i = 0; i < diff; i++) {\n          container.appendChild(renderSparkle(generateProgressSparkle(), sparkleOptions));\n        }\n      } else if(diff < 0) {\n        for(let i = 0; i < -diff; i++) {\n          const div = container.lastChild as HTMLDivElement;\n          div.remove();\n        }\n      }\n    }));\n  }\n\n  return container;\n}\n","import {createMemo} from 'solid-js';\nimport {StarGift, TextWithEntities} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport Button from '@components/buttonTsx';\nimport {StickerTsx, StickerTsxExtraOptions} from '@components/wrappers/sticker';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport styles from '@components/chat/bubbles/starGift.module.scss';\nimport stylesCommon from '@components/chat/bubbles/service.module.scss';\nimport {Sparkles} from '@components/sparkles';\nimport classNames from '@helpers/string/classNames';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {StarGiftBadge} from '@components/stargifts/stargiftBadge';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {simulateClickEvent} from '@helpers/dom/clickEvent';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {getCollectibleName} from '@appManagers/utils/gifts/getCollectibleName';\n\nexport function StarGiftBubble(props: {\n  gift: MyStarGift\n\n  fromId: PeerId\n  asUpgrade?: boolean;\n  asPrepaidUpgrade?: boolean;\n  ownerId?: PeerId;\n  message?: TextWithEntities;\n  wrapStickerOptions?: StickerTsxExtraOptions;\n  onViewClick?: () => void;\n}) {\n  const message = createMemo(() => {\n    if(props.gift.raw._ === 'starGiftUnique') {\n      return (\n        <div class={/* @once */ styles.uniqueGiftInfo}>\n          <div class={/* @once */ styles.uniqueGiftTitle}>\n            {getCollectibleName(props.gift.raw)}\n          </div>\n\n          <div class={/* @once */ styles.uniqueGiftProps}>\n            <I18nTsx class={/* @once */ styles.uniqueGiftPropName} key=\"StarGiftModel\" />\n            <div class={/* @once */ styles.uniqueGiftPropValue}>\n              {props.gift.collectibleAttributes.model.name}\n            </div>\n            <I18nTsx class={/* @once */ styles.uniqueGiftPropName} key=\"StarGiftBackdrop\" />\n            <div class={/* @once */ styles.uniqueGiftPropValue}>\n              {props.gift.collectibleAttributes.backdrop.name}\n            </div>\n            <I18nTsx class={/* @once */ styles.uniqueGiftPropName} key=\"StarGiftPattern\" />\n            <div class={/* @once */ styles.uniqueGiftPropValue}>\n              {props.gift.collectibleAttributes.pattern.name}\n            </div>\n          </div>\n        </div>\n      )\n    }\n\n    if(props.message) {\n      return wrapRichText(props.message.text, {entities: props.message.entities});\n    }\n\n    if(props.asUpgrade && props.ownerId) {\n      return (\n        <I18nTsx\n          key=\"StarGiftDefaultMessageUpgradeOut\"\n          args={<PeerTitleTsx peerId={props.ownerId} />}\n        />\n      )\n    }\n\n    if(props.asUpgrade) {\n      return <I18nTsx key=\"StarGiftDefaultMessageUpgrade\" />\n    }\n\n    if(props.gift.raw.convert_stars !== undefined && !props.gift.isUpgraded) {\n      return props.gift.isIncoming ? (\n        <I18nTsx\n          key=\"StarGiftDefaultMessageConvertable\"\n          args={<span>{props.gift.raw.convert_stars}</span>}\n        />\n      ) : (\n        <I18nTsx\n          key=\"StarGiftDefaultMessageConvertableOut\"\n          args={[\n            <PeerTitleTsx peerId={props.ownerId} />,\n            `${props.gift.raw.convert_stars}`\n          ]}\n        />\n      );\n    }\n\n    return props.gift.isIncoming ? (\n      <I18nTsx key=\"StarGiftDefaultMessage\" />\n    ) : (\n      <I18nTsx\n        key=\"StarGiftDefaultMessageOut\"\n        args={<PeerTitleTsx peerId={props.ownerId} />}\n      />\n    );\n  });\n\n  return (\n    <div class={/* @once */ classNames(\n      styles.bubble,\n      props.gift.raw._ === 'starGiftUnique' && styles.bubbleIsUnique,\n      stylesCommon.addon\n    )}>\n      {props.gift.raw.availability_total && (\n        <StarGiftBadge\n          class={/* @once */ styles.badge}\n          backdropAttr={props.gift.collectibleAttributes?.backdrop}\n        >\n          <I18nTsx\n            key=\"StarGiftLimitedBadgeNum\"\n            args={[formatNumber(props.gift.raw.availability_total, 1)]}\n          />\n        </StarGiftBadge>\n      )}\n      {props.gift.collectibleAttributes && (\n        <StarGiftBackdrop\n          class={/* @once */ styles.backdrop}\n          backdrop={props.gift.collectibleAttributes.backdrop}\n          patternEmoji={props.gift.collectibleAttributes.pattern.document as MyDocument}\n        />\n      )}\n      <StickerTsx\n        class={/* @once */ styles.sticker}\n        sticker={props.gift.sticker}\n        width={120}\n        height={120}\n        extraOptions={props.wrapStickerOptions}\n      />\n\n      <I18nTsx\n        key={props.asPrepaidUpgrade ? 'StarGiftUpgradeFrom' : 'StarGiftFrom'}\n        class={/* @once */ styles.from}\n        args={\n          <div class={/* @once */ styles.fromUser}>\n            <AvatarNewTsx peerId={props.fromId} size={16} />\n            <PeerTitleTsx peerId={props.fromId} />\n          </div>\n        }\n      />\n\n      <div class={/* @once */ styles.message}>\n        {message()}\n      </div>\n\n      {props.asUpgrade ? (\n        <Button\n          class={/* @once */ classNames('bubble-service-button', styles.upgradeButton)}\n          onClick={props.onViewClick}\n          iconAfter=\"unpack\"\n        >\n          <Sparkles mode=\"button\" isDiv />\n          <I18nTsx key=\"ActionGiftPremiumUnpack\" />\n        </Button>\n      ) : (\n        <Button\n          class='bubble-service-button'\n          onClick={props.onViewClick}\n        >\n          <Sparkles mode=\"button\" isDiv />\n          <I18nTsx key=\"ActionGiftPremiumView\" />\n        </Button>\n      )}\n    </div>\n  )\n}\n\nexport function UniqueStarGiftWebPageBox(props: {\n  gift: MyStarGift\n  wrapStickerOptions?: StickerTsxExtraOptions\n}) {\n  return (\n    <div\n      class={/* @once */ styles.webPageBox}\n      onClick={(evt) => simulateClickEvent(evt.target.closest('.webpage-quote'))}\n    >\n      <StarGiftBackdrop\n        class={/* @once */ styles.webPageBackdrop}\n        canvasClass={/* @once */ styles.webPageBackdropCanvas}\n        backdrop={props.gift.collectibleAttributes.backdrop}\n        patternEmoji={props.gift.collectibleAttributes.pattern.document as MyDocument}\n      />\n      <StickerTsx\n        class={/* @once */ styles.webPageSticker}\n        width={120}\n        height={120}\n        extraOptions={props.wrapStickerOptions}\n        sticker={props.gift.collectibleAttributes.model.document as MyDocument}\n      />\n    </div>\n  )\n}\n","import {JSX} from 'solid-js';\nimport liteMode from '@helpers/liteMode';\nimport lottieLoader, {LottieAssetName} from '@lib/rlottie/lottieLoader';\nimport Button from '@components/buttonTsx';\nimport LottieAnimation from '@components/lottieAnimation';\nimport {RLottieOptions} from '@lib/rlottie/rlottiePlayer';\n\nimport styles from '@components/chat/bubbles/premiumGift.module.scss';\nimport stylesCommon from '@components/chat/bubbles/service.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {StickerTsx} from '@components/wrappers/sticker';\n\nexport function PremiumGiftBubble(props: {\n  assetName?: LottieAssetName\n  sticker?: MyDocument\n  title: JSX.Element\n  subtitle: JSX.Element\n  buttonText?: JSX.Element\n  buttonCallback?: () => void\n  rlottieOptions?: Partial<RLottieOptions>\n}) {\n  return (\n    <div class={/* @once */ classNames(styles.bubble, stylesCommon.addon)}>\n      {props.sticker && (\n        <StickerTsx\n          sticker={props.sticker}\n          width={160}\n          height={160}\n          autoStyle={true}\n          class={styles.sticker}\n          extraOptions={{\n            play: liteMode.isAvailable('stickers_chat'),\n            middleware: props.rlottieOptions?.middleware\n          }}\n        />\n      )}\n      {props.assetName && (\n        <LottieAnimation\n          class={/* @once */ styles.sticker}\n          size={160}\n          name={props.assetName}\n          lottieLoader={lottieLoader}\n          rlottieOptions={{\n            autoplay: liteMode.isAvailable('stickers_chat'),\n            ...props.rlottieOptions\n          }}\n        />\n      )}\n\n      <span class=\"text-bold\">{props.title}</span>\n      <span class={/* @once */ styles.subtitle}>\n        {props.subtitle}\n      </span>\n      {props.buttonText && (\n        <Button\n          class=\"bubble-service-button\"\n          onClick={props.buttonCallback}\n        >\n          {props.buttonText}\n        </Button>\n      )}\n    </div>\n  );\n}\n","export function approxEquals(a: number, b: number, epsilon = 0.001) {\n  return Math.abs(a - b) < epsilon;\n}\n","import {resolveFirst} from '@solid-primitives/refs'\nimport {getOverlayRoot} from '@helpers/appWindow'\nimport {ComponentProps, createEffect, createMemo, createRoot, createSignal, For, JSX, on, onCleanup, onMount, Show, splitProps} from 'solid-js'\nimport {attachClickEvent} from '@helpers/dom/clickEvent'\nimport {IconTsx} from '@components/iconTsx'\nimport contextMenuController from '@helpers/contextMenuController'\nimport {ButtonMenuDirection} from '@components/buttonMenuToggle'\nimport {doubleRaf, fastRaf, fastRafPromise} from '@helpers/schedulers'\nimport {I18nTsx} from '@helpers/solid/i18n'\nimport {i18n} from '@lib/langPack'\nimport Scrollable from '@components/scrollable2'\nimport LazyLoadQueue from '@components/lazyLoadQueue'\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer'\nimport rootScope from '@lib/rootScope'\nimport clamp from '@helpers/number/clamp'\nimport classNames from '@helpers/string/classNames'\nimport {positionMenuTrigger} from '@helpers/positionMenu'\n\ntype HighlightPosition = {start: number, end: number}\nexport function ButtonMenuSelectText(props: {\n  text: string\n  highlight?: HighlightPosition\n}) {\n  function content(): JSX.Element {\n    if(!props.highlight) {\n      return props.text;\n    }\n\n    const {start, end} = props.highlight;\n    const parts: JSX.Element[] = [];\n\n    if(start > 0) {\n      parts.push(\n        <span class=\"btn-menu-select-text-faded\">\n          {props.text.slice(0, start)}\n        </span>\n      );\n    }\n\n    parts.push(props.text.slice(start, end));\n\n    if(end < props.text.length) {\n      parts.push(\n        <span class=\"btn-menu-select-text-faded\">\n          {props.text.slice(end)}\n        </span>\n      );\n    }\n\n    return parts;\n  }\n\n  return <>{content()}</>;\n}\n\nfunction ButtonMenuSelectInner<T>(props: {\n  class?: string\n  value: T[]\n  onValueChange: (value: T[]) => void\n  options: T[]\n  needStickerRenderer?: boolean\n  stickerOptions?: SuperStickerRenderer['visibleRenderOptions']\n  renderOption: (params: {\n    option: T,\n    chosen: boolean\n    stickerRenderer?: SuperStickerRenderer\n    highlight?: HighlightPosition\n    optionText?: string\n  }) => JSX.Element\n  optionSearchText?: (option: T) => string\n  optionKey: (option: T) => string\n  deselectAllOnFirstSelect?: boolean\n  single?: boolean\n}) {\n  const [search, setSearch] = createSignal('')\n\n  const hasSearch = !!props.optionSearchText;\n  const cleanForSearch = (text: string) => text.toLowerCase().replace(/[\\s+/\\\\_-]/g, '').trim()\n\n  type FilteredOption = {\n    option: T\n    highlight?: HighlightPosition\n  }\n  const filteredOptions = createMemo<FilteredOption[]>(() => {\n    const search$ = search();\n    const options = props.options;\n    if(search$ === '' || !hasSearch) {\n      return options.map(option => ({\n        option\n      }));\n    }\n\n    const cleanSearch = cleanForSearch(search$);\n    const results: FilteredOption[] = [];\n\n    for(const option of options) {\n      const optionText = props.optionSearchText(option);\n      const cleanOptionText = cleanForSearch(optionText);\n\n      const cleanIndex = cleanOptionText.indexOf(cleanSearch);\n      if(cleanIndex !== -1) {\n        let searchIndex = 0;\n        let optionIndex = 0;\n        let matchStart = -1;\n\n        while(searchIndex < cleanSearch.length && optionIndex < optionText.length) {\n          const cleanChar = cleanForSearch(optionText[optionIndex]);\n          if(cleanChar === cleanSearch[searchIndex]) {\n            if(matchStart === -1) {\n              matchStart = optionIndex;\n            }\n            searchIndex++;\n            if(searchIndex === cleanSearch.length) {\n              results.push({\n                option,\n                highlight: {start: matchStart, end: optionIndex + 1}\n              });\n              break;\n            }\n          } else if(matchStart !== -1) {\n            searchIndex = 0;\n            matchStart = -1;\n          }\n          optionIndex++;\n        }\n      }\n    }\n\n    return results;\n  })\n  const chosenKeys = createMemo(() => {\n    const chosen$ = props.value;\n    return new Set(chosen$.map(it => props.optionKey(it)))\n  })\n\n  let scrollable: HTMLDivElement;\n  const lazyLoadQueue = props.needStickerRenderer ? new LazyLoadQueue() : undefined;\n  const stickerRenderer = props.needStickerRenderer ? new SuperStickerRenderer({\n    regularLazyLoadQueue: lazyLoadQueue,\n    group: 'none',\n    managers: rootScope.managers,\n    intersectionObserverInit: {root: scrollable},\n    visibleRenderOptions: {\n      play: false,\n      width: 20,\n      height: 20,\n      ...props.stickerOptions\n    },\n    withLock: false\n  }) : undefined;\n\n  onCleanup(() => {\n    stickerRenderer?.destroy();\n    lazyLoadQueue?.clear();\n  });\n\n  let inputEl: HTMLInputElement;\n  onMount(() => doubleRaf().then(() => inputEl?.focus()))\n\n  return (\n    <div class={classNames('btn-menu', 'btn-menu-select', props.class)}>\n      <Show when={hasSearch}>\n        <div class=\"btn-menu-item btn-menu-search\">\n          <IconTsx icon=\"search\" class=\"btn-menu-item-icon\" />\n          <input\n            type=\"text\"\n            class=\"btn-menu-item-input\"\n            placeholder={i18n('Search').textContent}\n            value={search()}\n            onInput={e => setSearch(e.currentTarget.value)}\n            ref={inputEl}\n          />\n        </div>\n        <div class=\"btn-menu-search-delimiter\" />\n      </Show>\n      <div\n        class=\"btn-menu-search-scrollable\"\n        style={{height: `${10 + Math.min(1 + filteredOptions().length, 7.5) * 32}px`}}\n      >\n        <Scrollable axis=\"y\" ref={scrollable}>\n          <Show when={!props.single}>\n            <div\n              class=\"btn-menu-item\"\n              tabIndex=\"0\"\n              onClick={() => props.onValueChange(props.options)}\n            >\n              <IconTsx icon=\"checkround\" class=\"btn-menu-item-icon\" />\n              <I18nTsx class=\"btn-menu-item-text\" key='SelectAll2' />\n            </div>\n          </Show>\n          <For each={filteredOptions()}>\n            {filteredOption => (\n              <div\n                class=\"btn-menu-item\"\n                tabIndex=\"0\"\n                onClick={() => {\n                  const optionKey = props.optionKey(filteredOption.option)\n                  const wasChosen = chosenKeys().has(optionKey)\n\n                  if(props.deselectAllOnFirstSelect && props.value.length === props.options.length) {\n                    props.onValueChange([filteredOption.option])\n                    return\n                  }\n\n                  if(wasChosen) {\n                    props.onValueChange(props.value.filter(it => props.optionKey(it) !== optionKey))\n                  } else if(props.single) {\n                    props.onValueChange([filteredOption.option])\n                  } else {\n                    props.onValueChange([...props.value, filteredOption.option])\n                  }\n                }}\n              >\n                {props.renderOption({\n                  option: filteredOption.option,\n                  get chosen() {\n                    return chosenKeys().has(props.optionKey(filteredOption.option))\n                  },\n                  stickerRenderer,\n                  highlight: filteredOption.highlight,\n                  optionText: props.optionSearchText?.(filteredOption.option)\n                })}\n              </div>\n            )}\n          </For>\n        </Scrollable>\n      </div>\n    </div>\n  )\n}\n\nexport function createButtonMenuSelect<T>(props: ComponentProps<typeof ButtonMenuSelectInner<T>> & {\n  onToggleMenu?: (open: boolean) => void\n  direction: ButtonMenuDirection\n}) {\n  let dispose: () => void;\n  let closeTimeout: number;\n  let tempId = 0;\n  let opened = false\n\n  function close() {\n    if(opened) {\n      contextMenuController.close()\n      opened = false\n    }\n  }\n\n  async function open(triggerEl: HTMLElement) {\n    if(opened) return;\n    dispose?.()\n    const _tempId = ++tempId;\n\n    if(closeTimeout) {\n      clearTimeout(closeTimeout);\n      closeTimeout = undefined;\n      return;\n    }\n\n    await fastRafPromise();\n    if(_tempId !== tempId) return;\n\n    const el = createRoot((dispose_) => {\n      dispose = dispose_\n      const [, innerProps] = splitProps(props, ['direction', 'onToggleMenu'])\n\n      return <ButtonMenuSelectInner {...innerProps} />\n    })\n    const domEl = typeof el === 'function' ? (el as () => HTMLElement)() : el as HTMLElement\n\n    if(props.single) {\n      attachClickEvent(domEl, close)\n    }\n\n    props.onToggleMenu?.(true)\n    domEl.classList.add(props.direction)\n    positionMenuTrigger(triggerEl, domEl, props.direction, {top: 8})\n    getOverlayRoot().append(domEl)\n\n    await fastRafPromise();\n\n    contextMenuController.openBtnMenu(domEl, () => {\n      ++tempId;\n      clearTimeout(closeTimeout);\n      closeTimeout = undefined;\n\n      props.onToggleMenu?.(false)\n      opened = false\n      closeTimeout = window.setTimeout(() => {\n        closeTimeout = undefined;\n        domEl.remove();\n        dispose?.()\n      }, 300);\n    })\n    opened = true\n  }\n\n  onCleanup(() => {\n    dispose?.()\n  })\n\n  return {open, close}\n}\n\nexport function ButtonMenuSelect<T>(props: Parameters<typeof createButtonMenuSelect<T>>[0] & {\n  children: JSX.Element\n}) {\n  const children = resolveFirst(() => props.children, it => it instanceof HTMLElement)\n\n  const {open} = createButtonMenuSelect(props)\n\n  createEffect(on(children, (el: HTMLElement) => {\n    if(!el) return\n    const clean = attachClickEvent(el, (evt) => {\n      if((evt.target as HTMLElement).closest('.btn-menu')) return;\n      open(el)\n    })\n    onCleanup(clean)\n  }))\n\n  return children()\n}\n","import {AnyFunction} from '@types';\nimport {untrack} from 'solid-js';\n\nexport default function untrackActions<T extends Record<string, AnyFunction>>(actions: T) {\n  for(const action in actions) {\n    // @ts-ignore\n    const callback = actions[action];\n    // @ts-ignore\n    actions[action] = (...args: any[]) => {\n      // console.log('action', action, args);\n      return untrack(() => callback(...args));\n    };\n  }\n\n  return actions;\n}\n","import {createStore, unwrap} from 'solid-js/store';\nimport {StarGiftCollection} from '@layer';\nimport {batch, onMount} from 'solid-js';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport rootScope from '@lib/rootScope';\nimport createListenerSetter from '@helpers/solid/createListenerSetter';\nimport {updateStarGift} from '@appManagers/utils/gifts/updateStarGift';\nimport {inputStarGiftEquals} from '@appManagers/utils/gifts/inputStarGiftEquals';\nimport untrackActions from '@helpers/solid/untrackActions';\nimport setBooleanFlag from '@helpers/object/setBooleanFlag';\nimport {getCanManagePeerGifts} from '@components/stargifts/canManageGifts';\n\nexport const ALL_COLLECTIONS_ID = -1\n\ninterface StarGiftsFilters {\n  sort?: 'date' | 'value'\n  chosenCollection?: number\n  unlimited?: boolean\n  limited?: boolean\n  upgradable?: boolean\n  unique?: boolean\n  displayed?: boolean\n  hidden?: boolean\n}\n\nexport interface StarGiftsProfileStore extends Required<StarGiftsFilters> {\n  items: MyStarGift[]\n  collections: StarGiftCollection[] | undefined\n  loading: boolean\n  loaded: boolean\n  canManageGifts: boolean\n  hasCollections: boolean\n}\n\nexport interface StarGiftsProfileActions {\n  loadNext: (reload?: boolean) => Promise<void>\n  setFilters: (filters: StarGiftsFilters) => void\n  deleteCollection: (collectionId: number) => void\n  handleSwipe: (xDiff: number, setCollectionOverride?: (collectionId: number) => void) => boolean\n  updateCollection: (collection: StarGiftCollection, options?: {\n    switch: boolean\n    reload: boolean\n  }) => void\n}\n\n\nexport function createProfileGiftsStore(props: {\n  peerId: PeerId\n  initialFilters?: StarGiftsFilters\n  onCountChange?: (count: number) => void\n}): [StarGiftsProfileStore, StarGiftsProfileActions] {\n  const initialState: StarGiftsProfileStore = {\n    collections: undefined,\n    items: [],\n    loading: false,\n    loaded: false,\n    canManageGifts: props.peerId === rootScope.myId,\n\n    chosenCollection: ALL_COLLECTIONS_ID,\n    sort: 'date',\n    unlimited: true,\n    limited: true,\n    upgradable: true,\n    unique: true,\n    displayed: true,\n    hidden: true,\n    ...props.initialFilters,\n    get hasCollections() {\n      return store.collections !== undefined && store.collections.length > 0;\n    }\n  }\n  const [store, setStore] = createStore<StarGiftsProfileStore>(initialState);\n\n  let currentOffset = '';\n  let nextReqId = 0\n  let fetchedCanManageGifts = false;\n\n  const fetchCanManageGifts = () => getCanManagePeerGifts(props.peerId);\n\n  const collectionCache = new Map<number, {items: MyStarGift[], offset: string, loaded: boolean}>();\n\n  async function loadNext(reload = false) {\n    if(!reload && (store.loading || store.loaded)) return\n    setStore('loading', true);\n\n    const id = ++nextReqId\n    const collectionId = store.chosenCollection === ALL_COLLECTIONS_ID ? undefined : store.chosenCollection\n    const [res, canManageGifts] = await Promise.all([\n      rootScope.managers.appGiftsManager.getProfileGifts({\n        peerId: props.peerId,\n        offset: currentOffset,\n        sort: store.sort,\n        unlimited: store.unlimited,\n        limited: store.limited,\n        upgradable: store.upgradable,\n        unique: store.unique,\n        displayed: store.displayed,\n        hidden: store.hidden,\n        withCollections: store.collections === undefined,\n        collectionId,\n        limit: 99 // divisible by 3 to avoid grid jumping\n      }),\n      fetchedCanManageGifts ? Promise.resolve(store.canManageGifts) : fetchCanManageGifts()\n    ]);\n\n    if(id !== nextReqId) return;\n    currentOffset = res.next;\n    batch(() => {\n      if(!fetchedCanManageGifts) {\n        fetchedCanManageGifts = true;\n        setStore('canManageGifts', canManageGifts);\n      }\n\n      setStore('items', reload ? res.gifts : store.items.concat(res.gifts))\n      setStore('loaded', !res.next)\n      setStore('loading', false)\n      if(res.collections) {\n        setStore('collections', res.collections)\n      }\n    })\n    if(\n      collectionId === undefined &&\n      store.unlimited &&\n      store.limited &&\n      store.upgradable &&\n      store.unique &&\n      store.displayed &&\n      store.hidden\n    ) {\n      props.onCountChange?.(res.count);\n    }\n  }\n\n  function reload(background = false) {\n    currentOffset = ''\n    fetchedCanManageGifts = false\n    batch(() => {\n      setStore('loading', true)\n      setStore('loaded', false)\n      if(!background) {\n        setStore('items', [])\n      }\n    })\n    loadNext(true)\n  }\n\n  const actions: StarGiftsProfileActions = {\n    loadNext,\n    setFilters: (filters) => {\n      const onlyCollectionChange = Object.keys(filters).length === 1 && filters.chosenCollection !== undefined\n      const switchingCollection = onlyCollectionChange && filters.chosenCollection !== store.chosenCollection\n\n      if(!onlyCollectionChange) {\n        collectionCache.clear()\n      }\n\n      if(switchingCollection) {\n        // save current collection state\n        collectionCache.set(store.chosenCollection, {\n          items: unwrap(store.items),\n          offset: currentOffset,\n          loaded: store.loaded\n        })\n      }\n\n      setStore(filters)\n\n      if(switchingCollection) {\n        const cached = collectionCache.get(store.chosenCollection)\n        if(cached) {\n          currentOffset = cached.offset\n          batch(() => {\n            setStore('items', cached.items)\n            setStore('loaded', cached.loaded)\n            setStore('loading', false)\n          })\n          return\n        }\n      }\n\n      reload()\n    },\n    deleteCollection: (collectionId) => {\n      collectionCache.delete(collectionId)\n      const deletingChosenCollection = store.chosenCollection === collectionId\n\n      batch(() => {\n        if(deletingChosenCollection) {\n          setStore('chosenCollection', ALL_COLLECTIONS_ID)\n        }\n        setStore('collections', store.collections.filter((it) => it.collection_id !== collectionId))\n      })\n\n      if(deletingChosenCollection) {\n        reload()\n      }\n    },\n    updateCollection: (collection, options) => {\n      collectionCache.delete(collection.collection_id)\n      const needSwitch= options?.switch ?? true\n      let needReload = options?.reload ?? needSwitch\n\n      batch(() => {\n        const newArray = store.collections.slice();\n        const idx = newArray.findIndex((it) => it.collection_id === collection.collection_id);\n        if(idx !== -1) {\n          newArray[idx] = collection;\n        } else {\n          newArray.push(collection);\n        }\n        setStore('collections', newArray);\n        if(needSwitch) {\n          setStore('chosenCollection', collection.collection_id)\n          needReload = true\n        }\n      })\n      if(needReload) {\n        reload()\n      }\n    },\n    handleSwipe: (xDiff: number, setCollectionOverride?: (collectionId: number) => void) => {\n      if(!store.hasCollections) return false\n      const direction = xDiff > 0 ? 1 : -1\n\n      const collections$ = store.collections;\n      const chosenCollection$ = store.chosenCollection;\n      const currentIndex =\n        chosenCollection$ === ALL_COLLECTIONS_ID ? -1 :\n        collections$.findIndex((it) => it.collection_id === chosenCollection$);\n      const newIndex = currentIndex + direction;\n      if(newIndex < -1 || newIndex >= collections$.length) return false\n\n      const newCollectionId = newIndex === -1 ? ALL_COLLECTIONS_ID : collections$[newIndex].collection_id\n      if(setCollectionOverride) {\n        setCollectionOverride(newCollectionId)\n      } else {\n        actions.setFilters({chosenCollection: newCollectionId})\n      }\n\n      return true\n    }\n  }\n  untrackActions(actions as any);\n\n  const listenerSetter = createListenerSetter()\n  onMount(() => {\n    listenerSetter.add(rootScope)('star_gift_update', (event) => {\n      collectionCache.clear()\n      const items = unwrap(store.items);\n      const idx = items.findIndex((it) => inputStarGiftEquals(it, event.input));\n      if(idx !== -1) {\n        const newList = items.slice();\n        // create a new object to force re-render\n        const newItem = {...newList[idx]};\n        newList[idx] = newItem;\n\n        updateStarGift(newItem, event);\n\n        setStore('items', newList);\n      }\n    });\n\n    listenerSetter.add(rootScope)('pinned_stargifts', (event) => {\n      if(event.peerId !== props.peerId) return;\n      collectionCache.clear()\n\n      const items = unwrap(store.items).slice();\n      for(let i = 0; i < items.length; i++) {\n        const item = items[i];\n        const shouldBePinned = event.gifts.some((it) => inputStarGiftEquals(item, it))\n        const wasPinned = !!item.saved.pFlags.pinned_to_top\n\n        if(shouldBePinned !== wasPinned) {\n          items[i] = {...item} // force re-render\n          setBooleanFlag(items[i].saved.pFlags, 'pinned_to_top', shouldBePinned)\n        }\n      }\n\n      items.sort((a, b) => {\n        if(a.saved.pFlags.pinned_to_top && !b.saved.pFlags.pinned_to_top) return -1;\n        if(!a.saved.pFlags.pinned_to_top && b.saved.pFlags.pinned_to_top) return 1;\n        if(a.saved.pFlags.pinned_to_top && b.saved.pFlags.pinned_to_top) {\n          const idxA = event.gifts.findIndex((it) => inputStarGiftEquals(a, it))\n          const idxB = event.gifts.findIndex((it) => inputStarGiftEquals(b, it))\n          return idxA - idxB\n        };\n        return b.saved.date - a.saved.date;\n      })\n      setStore('items', items);\n    })\n\n    listenerSetter.add(rootScope)('star_gift_list_update', ({peerId}) => {\n      if(peerId !== props.peerId) return\n      collectionCache.clear()\n\n      // refetch list. wait a bit so that the server can process it.\n      setTimeout(() => {\n        currentOffset = ''\n        loadNext(true)\n      }, 500)\n    })\n  })\n\n  return [store, actions]\n}\n","import bigInt from 'big-integer';\nimport PopupElement from '.';\nimport {Chat, InputInvoice, Message, StarGift, StarGiftAttribute, StarGiftAttributeId, TextWithEntities, User} from '@layer';\nimport {MyPremiumGiftOption, MyStarGift} from '@appManagers/appGiftsManager';\nimport {STARS_CURRENCY} from '@appManagers/constants';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {Accessor, createEffect, createMemo, createSignal, For, on, onCleanup, onMount, Setter, Show} from 'solid-js';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport PopupStars, {StarsBalance, StarsStar} from '@components/popups/stars';\nimport LottieAnimation from '@components/lottieAnimation';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport classNames from '@helpers/string/classNames';\nimport {StarGiftsGrid} from '@components/stargifts/stargiftsGrid';\nimport {fastRaf} from '@helpers/schedulers';\nimport PopupStarGiftInfo from '@components/popups/starGiftInfo';\nimport {FakeBubbles} from '@components/chat/bubbles/fakeBubbles';\nimport {ServiceBubble} from '@components/chat/bubbles/service';\nimport {StarGiftBubble} from '@components/chat/bubbles/starGift';\nimport {InputFieldTsx} from '@components/inputFieldTsx';\nimport rootScope from '@lib/rootScope';\nimport Row from '@components/rowTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport Button from '@components/buttonTsx';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport {PremiumGiftBubble} from '@components/chat/bubbles/premiumGift';\nimport {formatMonthsDuration} from '@helpers/date';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {render} from 'solid-js/web';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport numberThousandSplitter, {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport PopupPayment from '@components/popups/payment';\nimport {TransitionSliderTsx} from '@components/transitionTsx';\nimport maybe2x from '@helpers/maybe2x';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {StarGiftBadge} from '@components/stargifts/stargiftBadge';\nimport Scrollable from '@components/scrollable2';\nimport {approxEquals} from '@helpers/number/approxEquals';\nimport {useAppState} from '@stores/appState';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport {IconTsx} from '@components/iconTsx';\nimport {ButtonMenuSelect, ButtonMenuSelectText} from '@components/buttonMenuSelect';\nimport {rgbIntToHex} from '@helpers/color';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport {FloatingStarsBalance} from '@components/popups/floatingStarsBalance';\nimport {positionMenuTrigger} from '@helpers/positionMenu';\nimport {Transition} from '@vendor/solid-transition-group';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {inputStarGiftEquals} from '@appManagers/utils/gifts/inputStarGiftEquals';\nimport {updateStarGift} from '@appManagers/utils/gifts/updateStarGift';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\nimport safeAssign from '@helpers/object/safeAssign';\nimport PopupPremium from '@components/popups/premium';\nimport tsNow from '@helpers/tsNow';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport createStarGiftUpgradePopup from '@components/popups/starGiftUpgrade';\nimport {createProfileGiftsStore, StarGiftsProfileActions, StarGiftsProfileStore} from '@components/stargifts/profileStore';\nimport transferStarGift from '@components/popups/transferStarGift';\nimport {unwrap} from 'solid-js/store';\n\nimport styles from '@components/popups/sendGift.module.scss';\nimport Animated from '@helpers/solid/animations';\n\ntype GiftOption = MyStarGift | MyPremiumGiftOption;\n\nfunction GiftOptionsPage(props: {\n  peer: User.user | Chat.channel\n  peerId: PeerId\n  premiumOptions: MyPremiumGiftOption[]\n  giftOptions: MyStarGift[]\n  onGiftChosen: (item: GiftOption) => void\n  onClose: () => void\n\n  profileStore: StarGiftsProfileStore\n  profileStoreActions: StarGiftsProfileActions\n}) {\n  const [isPinned, setIsPinned] = createSignal(false);\n  const isToSelf = props.peerId === rootScope.myId;\n\n  type CategoryName = 'All' | 'Owned' | 'Collectibles';\n  const [category, setCategory] = createSignal<CategoryName>('All');\n\n  let categoriesContainer!: HTMLDivElement;\n  let container!: HTMLDivElement;\n\n  const giftPremiumSection = props.peer._ === 'user' && !isToSelf && (\n    <>\n      <div class={styles.mainTitle}>\n        {i18n('GiftPremium')}\n      </div>\n      <div class={styles.mainSubtitle}>\n        <I18nTsx\n          key=\"GiftTelegramPremiumDescription\"\n          args={<PeerTitleTsx peerId={props.peerId} onlyFirstName={props.peer._ === 'user'} />}\n        />\n      </div>\n      <div class={styles.premiumOptionsContainer}>\n        <For each={props.premiumOptions}>\n          {(option) => {\n            return (\n              <div class={styles.premiumOption} onClick={() => props.onGiftChosen(option)}>\n                <LottieAnimation\n                  lottieLoader={lottieLoader}\n                  class={styles.premiumOptionSticker}\n                  name={`Gift${option.months}`}\n                  size={84}\n                />\n                <div class={styles.premiumOptionTitle}>\n                  {formatMonthsDuration(option.months, false)}\n                </div>\n                <div class={styles.premiumOptionSubtitle}>\n                  {i18n('PremiumStickersShort')}\n                </div>\n                <div class={styles.premiumOptionPrice}>\n                  {paymentsWrapCurrencyAmount(option.price, option.currency)}\n                </div>\n\n                {option.discountPercent && (\n                  <StarGiftBadge\n                    class={styles.premiumOptionBadge}\n                    textClass={styles.premiumOptionBadgeText}\n                  >\n                      -{Math.round(option.discountPercent)}%\n                  </StarGiftBadge>\n                )}\n\n                {option.priceStars && (\n                  <div class={styles.premiumOptionPriceStars}>\n                    {i18n('PremiumOr')}\n                    <div class={styles.premiumOptionPriceStarsInner}>\n                      <StarsStar />\n                      {numberThousandSplitterForStars(option.priceStars)}\n                    </div>\n                  </div>\n                )}\n              </div>\n            );\n          }}\n        </For>\n      </div>\n    </>\n  );\n\n  const handleCategoryChanged = (it: string) => {\n    const wasPinned = isPinned()\n    setCategory(it as CategoryName);\n\n    fastRaf(() => {\n      container.scrollTo({top: categoriesContainer.offsetTop - 56, behavior: wasPinned ? 'instant' : 'smooth'});\n    });\n  }\n\n  const filteredGiftOptions = createMemo(() => {\n    const category$ = category();\n    if(category$ === 'All') return props.giftOptions;\n    if(category$ === 'Collectibles') {\n      return props.giftOptions.filter((it) =>\n        ((it.raw as StarGift.starGift).availability_remains > 0 && (it.raw as StarGift.starGift).upgrade_stars !== undefined) ||\n        it.isResale\n      );\n    }\n    return unwrap(props.profileStore.items);\n  });\n\n  const handleGiftClick = async(item: MyStarGift) => {\n    if(category() === 'Owned') {\n      transferStarGift(item, props.peerId).then((result) => {\n        if(result) {\n          props.onClose();\n        }\n      });\n      return\n    }\n\n    const gift = item.raw as StarGift.starGift;\n    if(gift.availability_remains === 0 && !gift.resell_min_stars) {\n      PopupElement.createPopup(PopupStarGiftInfo, {gift: item});\n      return;\n    }\n\n    if(gift.pFlags.require_premium && !rootScope.premium) {\n      PopupPremium.show();\n      return;\n    }\n\n    if(gift.per_user_total && !gift.per_user_remains) {\n      toastNew({langPackKey: 'StarGiftLimitReached', langPackArguments: [gift.per_user_total]})\n      return\n    }\n\n    if(gift.locked_until_date > tsNow(true)) {\n      const result = await rootScope.managers.apiManager.invokeApi('payments.checkCanSendGift', {\n        gift_id: gift.id\n      })\n\n      if(result._ === 'payments.checkCanSendGiftResultFail') {\n        confirmationPopup({\n          button: {langKey: 'OK', isCancel: true},\n          description: wrapRichText(result.reason.text, {entities: result.reason.entities})\n        });\n        return;\n      }\n    }\n\n    props.onGiftChosen(item);\n  };\n\n  onMount(() => {\n    fastRaf(() => {\n      container.style.setProperty('--height', `${container.offsetHeight}px`);\n    });\n  });\n\n  return (\n    <Scrollable\n      ref={container}\n      onScroll={() => {\n        container.classList.toggle(styles.isScrolled, container.scrollTop > 0);\n\n        const containerRect = container.getBoundingClientRect();\n        const rect = categoriesContainer.getBoundingClientRect();\n        setIsPinned(approxEquals(rect.top - containerRect.top, 56, 0.1));\n      }}\n      onScrolledBottom={() => {\n        if(category() === 'Owned') {\n          props.profileStoreActions.loadNext();\n        }\n      }}\n    >\n      <div class={styles.mainContainer}>\n        <div class={styles.mainHeader}>\n          <ButtonIconTsx icon=\"close\" onClick={props.onClose} />\n          <div class=\"popup-title\">\n            {i18n('StarGiftSendGift')}\n          </div>\n        </div>\n\n        <div class={styles.recipientAvatar}>\n          <img\n            class={styles.recipientBackground}\n            src={`assets/img/${maybe2x('stars_pay')}.png`}\n          />\n          <AvatarNewTsx peerId={props.peerId} size={100} />\n        </div>\n\n        {giftPremiumSection}\n\n        <div class={styles.mainTitle}>\n          {isToSelf ? i18n('StarGiftSendGiftSelf') : i18n('StarGiftSendGift')}\n        </div>\n        <div class={styles.mainSubtitle}>\n          <I18nTsx\n            key={isToSelf ? 'SendStarGiftSubtitleSelf' : 'SendStarGiftSubtitle'}\n            args={isToSelf ? undefined : [<PeerTitleTsx peerId={props.peerId} onlyFirstName={props.peer._ === 'user'} />]}\n          />\n        </div>\n\n        <ChipTabs\n          value={category()}\n          onChange={handleCategoryChanged}\n          view={isPinned() ? 'secondary' : 'surface'}\n          class={classNames(styles.categoriesContainer, isPinned() && styles.categoriesContainerPinned)}\n          ref={categoriesContainer}\n          center\n        >\n          <ChipTab value=\"All\">\n            {i18n('StarGiftCategoryAll')}\n          </ChipTab>\n          <Show when={!isToSelf && props.profileStore.items.length > 0}>\n            <ChipTab value=\"Owned\">\n              {i18n('StarGiftCategoryOwned')}\n            </ChipTab>\n          </Show>\n          <ChipTab value=\"Collectibles\">\n            {i18n('StarGiftCategoryCollectibles')}\n          </ChipTab>\n        </ChipTabs>\n\n        <div class={styles.giftsGridContainer}>\n          <Show when={category() === 'Owned' && props.profileStore.loading}>\n            <PreloaderTsx />\n          </Show>\n          <StarGiftsGrid\n            items={filteredGiftOptions()}\n            view={category() === 'Owned' ? 'transfer' : 'list'}\n            scrollParent={container}\n            onClick={handleGiftClick}\n          />\n        </div>\n      </div>\n    </Scrollable>\n  );\n}\n\nfunction createSomeOrAll<T>(options: () => T[]) {\n  const [chosen, setChosen] = createSignal<T[] | null>(null);\n\n  return [\n    () => {\n      const chosen$ = chosen();\n      if(chosen$ === null) return options();\n      return chosen$;\n    },\n    (value: T[] | null) => {\n      if(value && (value.length === options().length || value.length === 0)) {\n        value = null;\n      }\n\n      setChosen(value);\n    },\n    () => chosen() !== null\n  ] as const\n}\n\nfunction ResaleOptionsPage(props: {\n  gift: MyStarGift\n  peerId: PeerId\n  isFirst: boolean\n  initialFilter?: StarGiftAttribute;\n  onBack: () => void\n  onClose: () => void\n}) {\n  const [total, setTotal] = createSignal<Long | null>(null);\n  const [sort, setSort] = createSignal<'price' | 'date' | 'num'>('price');\n  const [items, setItems] = createSignal<MyStarGift[]>([]);\n  const [loading, setLoading] = createSignal(true);\n\n  const [modelOptions, setModelOptions] = createSignal<StarGiftAttribute.starGiftAttributeModel[]>([]);\n  const [chosenModelOptions, setChosenModelOptions, hasChosenModelOptions] = createSomeOrAll(modelOptions);\n  const [modelPopupVisible, setModelPopupVisible] = createSignal(false);\n\n  const [patternOptions, setPatternOptions] = createSignal<StarGiftAttribute.starGiftAttributePattern[]>([]);\n  const [chosenPatternOptions, setChosenPatternOptions, hasChosenPatternOptions] = createSomeOrAll(patternOptions);\n  const [patternPopupVisible, setPatternPopupVisible] = createSignal(false);\n\n  const [backdropOptions, setBackdropOptions] = createSignal<StarGiftAttribute.starGiftAttributeBackdrop[]>([]);\n  const [chosenBackdropOptions, setChosenBackdropOptions, hasChosenBackdropOptions] = createSomeOrAll(backdropOptions);\n  const [backdropPopupVisible, setBackdropPopupVisible] = createSignal(false);\n\n  if(props.initialFilter) {\n    switch(props.initialFilter._) {\n      case 'starGiftAttributeModel':\n        setChosenModelOptions([props.initialFilter]);\n        break;\n      case 'starGiftAttributePattern':\n        setChosenPatternOptions([props.initialFilter]);\n        break;\n      case 'starGiftAttributeBackdrop':\n        setChosenBackdropOptions([props.initialFilter]);\n        break;\n    }\n  }\n\n  let offset = '';\n  let attributesHash: Long = 0;\n  let tempId = 0;\n  const countersMap = new Map<string, number>();\n\n  function getCounterKey(attribute: StarGiftAttributeId | StarGiftAttribute) {\n    switch(attribute._) {\n      case 'starGiftAttributeModel':\n      case 'starGiftAttributePattern':\n        return `model:${attribute.document.id}`;\n      case 'starGiftAttributeIdModel':\n      case 'starGiftAttributeIdPattern':\n        return `model:${attribute.document_id}`;\n      case 'starGiftAttributeIdBackdrop':\n      case 'starGiftAttributeBackdrop':\n        return `backdrop:${attribute.backdrop_id}`;\n    }\n  }\n\n  let lastRequestedOffset: string | null = null;\n  async function loadMore() {\n    const _tempId = tempId;\n    if(lastRequestedOffset === offset) return;\n    if(offset === undefined) return; // no more items\n    lastRequestedOffset = offset;\n\n    const filters: StarGiftAttributeId[] = [];\n    if(hasChosenModelOptions()) {\n      for(const option of chosenModelOptions()) {\n        filters.push({_: 'starGiftAttributeIdModel', document_id: option.document.id});\n      }\n    }\n    if(hasChosenPatternOptions()) {\n      for(const option of chosenPatternOptions()) {\n        filters.push({_: 'starGiftAttributeIdPattern', document_id: option.document.id});\n      }\n    }\n    if(hasChosenBackdropOptions()) {\n      for(const option of chosenBackdropOptions()) {\n        filters.push({_: 'starGiftAttributeIdBackdrop', backdrop_id: option.backdrop_id});\n      }\n    }\n\n    const res = await rootScope.managers.appGiftsManager.getResaleOptions({\n      giftId: props.gift.raw.id,\n      sort: sort(),\n      attributesHash,\n      filters,\n      offset\n    })\n\n    if(_tempId !== tempId) return;\n\n    if(res.counters) {\n      for(const it of res.counters) {\n        countersMap.set(getCounterKey(it.attribute), it.count);\n      }\n    }\n\n    if(res.attributes) {\n      // ! filter attributes with 0 counts because they dont work server-side\n      setModelOptions(res.attributes.models.filter(it => countersMap.get(getCounterKey(it)) ?? 0 > 0));\n      setPatternOptions(res.attributes.patterns.filter(it => countersMap.get(getCounterKey(it)) ?? 0 > 0));\n      setBackdropOptions(res.attributes.backdrops.filter(it => countersMap.get(getCounterKey(it)) ?? 0 > 0));\n      attributesHash = res.attributesHash;\n    }\n\n    setItems((prev) => [...prev, ...res.items]);\n    offset = res.next;\n    setTotal(res.count);\n    setLoading(false);\n  }\n\n  onMount(() => {\n    loadMore();\n  });\n\n  function loadFromStart() {\n    offset = ''\n    setItems([])\n    countersMap.clear()\n    attributesHash = 0;\n    lastRequestedOffset = null;\n    tempId += 1;\n    setLoading(true);\n\n    loadMore();\n  }\n\n  subscribeOn(rootScope)('star_gift_update', (event) => {\n    const idx = items().findIndex((it) => inputStarGiftEquals(it, event.input));\n    if(idx !== -1) {\n      if(event.resalePrice) {\n        loadFromStart();\n      } else {\n        updateStarGift(items()[idx], event);\n      }\n    }\n  })\n\n  createEffect(on(\n    () => [sort(), hasChosenModelOptions(), hasChosenPatternOptions(), hasChosenBackdropOptions()],\n    loadFromStart,\n    {defer: true}\n  ));\n\n  const SORT_OPTIONS: Record<'price' | 'date' | 'num', {icon: Icon, text: LangPackKey}> = {\n    price: {\n      icon: 'sort_price',\n      text: 'StarGiftResaleSortPriceShort'\n    },\n    date: {\n      icon: 'sort_date',\n      text: 'StarGiftResaleSortDateShort'\n    },\n    num: {\n      icon: 'sort_num',\n      text: 'StarGiftResaleSortNumShort'\n    }\n  };\n\n  let container!: HTMLDivElement\n\n  return (\n    <div class={styles.secondPageContainer}>\n      <div class={styles.resaleHeader}>\n        <div class={styles.resaleHeaderInner}>\n          <ButtonIconTsx\n            icon={props.isFirst ? 'close' : 'back'}\n            onClick={props.isFirst ? props.onClose : props.onBack}\n          />\n          <div class={`popup-title ${styles.resaleTitle}`}>\n            {props.gift.raw.title}\n            <I18nTsx\n              class={styles.resaleSubtitle}\n              key=\"StarGiftResaleSubtitle\"\n              args={[total() !== null ? numberThousandSplitter(total()) : '...']}\n            />\n          </div>\n        </div>\n        <div class={styles.resaleFilters}>\n          <Scrollable axis=\"x\">\n            <div\n              class={`${styles.resaleFilterChip} ${styles.resaleFilterChipSort} btn-menu-toggle`}\n              ref={(el) => {\n                ButtonMenuToggle({\n                  container: el,\n                  appendTo: getOverlayRoot(),\n                  onOpen: (e, menu) => {\n                    positionMenuTrigger(el, menu, 'bottom-right', {top: 8})\n                  },\n                  direction: 'bottom-right',\n                  buttons: [\n                    {\n                      icon: 'sort_price',\n                      text: 'StarGiftResaleSortPrice',\n                      onClick: () => setSort('price')\n                    },\n                    {\n                      icon: 'sort_date',\n                      text: 'StarGiftResaleSortDate',\n                      onClick: () => setSort('date')\n                    },\n                    {\n                      icon: 'sort_num',\n                      text: 'StarGiftResaleSortNum',\n                      onClick: () => setSort('num')\n                    }\n                  ]\n                })\n              }}\n            >\n              <IconTsx icon={SORT_OPTIONS[sort()].icon} />\n              <I18nTsx key={SORT_OPTIONS[sort()].text} />\n            </div>\n\n            <ButtonMenuSelect<StarGiftAttribute.starGiftAttributeModel>\n              class={styles.resaleFilterSelect}\n              value={chosenModelOptions()}\n              onValueChange={setChosenModelOptions}\n              options={modelOptions()}\n              deselectAllOnFirstSelect\n              needStickerRenderer\n              renderOption={(props) => {\n                let stickerRef: HTMLDivElement;\n                onMount(() => {\n                  props.stickerRenderer.renderSticker(props.option.document as any, stickerRef);\n                  props.stickerRenderer.observeAnimated(stickerRef);\n                })\n                return (\n                  <>\n                    <div class=\"btn-menu-item-icon\" ref={stickerRef} />\n                    <div class=\"btn-menu-item-text\">\n                      <ButtonMenuSelectText\n                        text={props.option.name}\n                        highlight={props.highlight}\n                      />\n                      <span class={styles.resaleFilterChipCount}>\n                        {' '}\n                        {countersMap.get(getCounterKey(props.option)) ?? 0}\n                      </span>\n                    </div>\n                    {props.chosen && <IconTsx icon=\"check\" class=\"btn-menu-item-icon-right\" />}\n                  </>\n                );\n              }}\n              optionSearchText={(it) => it.name}\n              optionKey={(it) => String(it.document.id)}\n              onToggleMenu={setModelPopupVisible}\n              direction=\"bottom-right\"\n            >\n              <div class={styles.resaleFilterChip}>\n                <I18nTsx\n                  key={hasChosenModelOptions() ? 'StarGiftNModels' : 'StarGiftModel'}\n                  args={[String(chosenModelOptions().length)]}\n                />\n                <IconTsx icon={modelPopupVisible() ? 'down_up' : 'up_down'} />\n              </div>\n            </ButtonMenuSelect>\n\n            <ButtonMenuSelect<StarGiftAttribute.starGiftAttributeBackdrop>\n              class={styles.resaleFilterSelect}\n              value={chosenBackdropOptions()}\n              onValueChange={setChosenBackdropOptions}\n              options={backdropOptions()}\n              deselectAllOnFirstSelect\n              renderOption={(props) => (\n                <>\n                  <div class=\"btn-menu-item-icon\">\n                    <div\n                      class={styles.resaleFilterChipBackdrop}\n                      style={{\n                        '--backdrop-center-color': rgbIntToHex(props.option.center_color),\n                        '--backdrop-edge-color': rgbIntToHex(props.option.edge_color)\n                      }}\n                    />\n                  </div>\n                  <div class=\"btn-menu-item-text\">\n                    <ButtonMenuSelectText\n                      text={props.option.name}\n                      highlight={props.highlight}\n                    />\n                    <span class={styles.resaleFilterChipCount}>\n                      {' '}\n                      {countersMap.get(getCounterKey(props.option)) ?? 0}\n                    </span>\n                  </div>\n                  {props.chosen && <IconTsx icon=\"check\" class=\"btn-menu-item-icon-right\" />}\n                </>\n              )}\n              optionSearchText={(it) => it.name}\n              optionKey={(it) => String(it.backdrop_id)}\n              onToggleMenu={setBackdropPopupVisible}\n              direction=\"bottom-left\"\n            >\n              <div class={styles.resaleFilterChip}>\n                <I18nTsx\n                  key={hasChosenBackdropOptions() ? 'StarGiftNBackdrops' : 'StarGiftBackdrop'}\n                  args={[String(chosenBackdropOptions().length)]}\n                />\n                <IconTsx icon={backdropPopupVisible() ? 'down_up' : 'up_down'} />\n              </div>\n            </ButtonMenuSelect>\n\n            <ButtonMenuSelect<StarGiftAttribute.starGiftAttributePattern>\n              class={styles.resaleFilterSelect}\n              value={chosenPatternOptions()}\n              onValueChange={setChosenPatternOptions}\n              options={patternOptions()}\n              deselectAllOnFirstSelect\n              needStickerRenderer\n              stickerOptions={{textColor: 'primary-text-color'}}\n              renderOption={(props) => {\n                let stickerRef: HTMLDivElement;\n                onMount(() => {\n                  props.stickerRenderer.renderSticker(props.option.document as any, stickerRef);\n                  props.stickerRenderer.observeAnimated(stickerRef);\n                })\n                return (\n                  <>\n                    <div class=\"btn-menu-item-icon\" ref={stickerRef} />\n                    <div class=\"btn-menu-item-text\">\n                      <ButtonMenuSelectText\n                        text={props.option.name}\n                        highlight={props.highlight}\n                      />\n                      <span class={styles.resaleFilterChipCount}>\n                        {' '}\n                        {countersMap.get(getCounterKey(props.option)) ?? 0}\n                      </span>\n                    </div>\n                    {props.chosen && <IconTsx icon=\"check\" class=\"btn-menu-item-icon-right\" />}\n                  </>\n                );\n              }}\n              optionSearchText={(it) => it.name}\n              optionKey={(it) => String(it.document.id)}\n              onToggleMenu={setPatternPopupVisible}\n              direction=\"bottom-left\"\n            >\n              <div class={styles.resaleFilterChip}>\n                <I18nTsx\n                  key={hasChosenPatternOptions() ? 'StarGiftNPatterns' : 'StarGiftPattern'}\n                  args={[String(chosenPatternOptions().length)]}\n                />\n                <IconTsx icon={patternPopupVisible() ? 'down_up' : 'up_down'} />\n              </div>\n            </ButtonMenuSelect>\n          </Scrollable>\n        </div>\n      </div>\n\n      <div class={styles.secondPageBody}>\n        <Scrollable ref={container} onScrolledBottom={loadMore}>\n          <Animated type=\"cross-fade\">\n            <Show\n              when={!loading() && items().length > 0}\n              fallback={loading() ? <PreloaderTsx /> : (\n                <div class={styles.emptyPlaceholder}>\n                  <I18nTsx key=\"StarGiftResaleNothingFound\" />\n                </div>\n              )}\n            >\n              <StarGiftsGrid\n                class={styles.resaleGrid}\n                items={items()}\n                view=\"resale\"\n                scrollParent={container}\n                autoplay={false} // ! todo: need shared canvas for decent performance\n                onClick={(item) => {\n                  const popup = PopupElement.createPopup(PopupStarGiftInfo, {\n                    gift: item,\n                    resaleRecipient: props.peerId,\n                    onClickAway: props.onClose,\n                    onAttributeClick: (attribute) => {\n                      switch(attribute._) {\n                        case 'starGiftAttributeModel':\n                          setChosenModelOptions([attribute]);\n                          break;\n                        case 'starGiftAttributeBackdrop':\n                          setChosenBackdropOptions([attribute]);\n                          break;\n                        case 'starGiftAttributePattern':\n                          setChosenPatternOptions([attribute]);\n                          break;\n                      }\n                      popup.hide();\n                    }\n                  })\n                }}\n              />\n            </Show>\n          </Animated>\n        </Scrollable>\n      </div>\n    </div>\n  );\n}\n\nfunction StarGiftLimitedProgress(props: {\n  gift: StarGift.starGift\n}) {\n  // NB: deliberately not reactive, gift won't change\n  const left = i18n('StarGiftLimitedLeft', [props.gift.availability_remains]);\n  left.classList.add(styles.limitedProgressLeft);\n\n  const progress = 100 * props.gift.availability_remains / props.gift.availability_total;\n\n  return (\n    <div class={styles.limitedProgressWrap}>\n      <div class={styles.limitedProgressBar}>\n        <div class={styles.limitedProgressProgress} style={{width: `${100 * props.gift.availability_remains / props.gift.availability_total}%`}} />\n        <div class={styles.limitedProgressText} style={{\n          'background-image': `linear-gradient(90deg, #fff ${progress}%, var(--secondary-text-color) ${progress}%)`\n        }}>\n          {left}\n          {i18n('StarGiftLimitedSold2', [props.gift.availability_total - props.gift.availability_remains])}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction ChosenGiftPage(props: {\n  peerId: PeerId\n  peerName: string\n  chosenGift: GiftOption\n  onBack: () => void\n  onClose: () => void\n}) {\n  const [textWithEntities, setTextWithEntities] = createSignal<TextWithEntities>();\n  const [anonymous, setAnonymous] = createSignal(false);\n  const [payWithStars, setPayWithStars] = createSignal(false);\n  const [withUpgrade, setWithUpgrade] = createSignal(false);\n  const [sending, setSending] = createSignal(false);\n\n  const message = createMemo<Message.messageService>(() => ({\n    _: 'messageService',\n    pFlags: {out: true},\n    id: 0,\n    peer_id: {_: 'peerUser', user_id: props.peerId.toUserId()},\n    date: 0,\n    action: props.chosenGift.type === 'stargift' ? {\n      _: 'messageActionStarGift',\n      gift: props.chosenGift.raw,\n      pFlags: {}\n    } : {\n      _: 'messageActionGiftPremium',\n      currency: payWithStars() ? STARS_CURRENCY : props.chosenGift.currency,\n      amount: payWithStars() ? props.chosenGift.priceStars : props.chosenGift.price,\n      days: props.chosenGift.months * 30\n    }\n  }));\n\n  async function handleSubmit() {\n    setSending(true);\n    let invoice: InputInvoice;\n    if(props.chosenGift.type === 'stargift') {\n      const peer = await rootScope.managers.appPeersManager.getInputPeerById(props.peerId)\n      invoice = {\n        _: 'inputInvoiceStarGift',\n        pFlags: {\n          hide_name: anonymous() ? true : undefined,\n          include_upgrade: withUpgrade() ? true : undefined\n        },\n        message: textWithEntities(),\n        peer,\n        gift_id: props.chosenGift.raw.id\n      };\n    } else {\n      const payWithStars$ = payWithStars();\n      const inputUser = await rootScope.managers.appUsersManager.getUserInput(props.peerId.toUserId());\n      if(payWithStars$) {\n        invoice = {\n          _: 'inputInvoicePremiumGiftStars',\n          user_id: inputUser,\n          months: props.chosenGift.months,\n          message: textWithEntities()\n        };\n      } else {\n        invoice = {\n          _: 'inputInvoicePremiumGiftCode',\n          purpose: {\n            _: 'inputStorePaymentPremiumGiftCode',\n            users: [inputUser],\n            currency: props.chosenGift.currency,\n            amount: props.chosenGift.price,\n            message: textWithEntities()\n          },\n          option: props.chosenGift.raw\n        };\n      }\n    }\n\n    try {\n      const popup = await PopupPayment.create({\n        inputInvoice: invoice,\n        noShowIfStars: true,\n        purpose: 'stargift'\n      });\n      popup.addEventListener('finish', (result) => {\n        if(result === 'paid' || result === 'pending') {\n          props.onClose();\n          if(\n            props.chosenGift.type === 'stargift' &&\n            props.chosenGift.raw._ === 'starGift' &&\n            props.chosenGift.raw.per_user_total &&\n            props.chosenGift.raw.per_user_remains\n          ) {\n            toastNew({\n              langPackKey: 'StarGiftLimitSent',\n              langPackArguments: [props.chosenGift.raw.per_user_remains - 1]\n            })\n          }\n        } else {\n          setSending(false);\n        }\n      });\n    } catch(err) {\n      setSending(false);\n      toastNew({langPackKey: 'Error.AnError'});\n      console.error('send gift error', err);\n    }\n  }\n\n  return (\n    <div class={styles.secondPageContainer}>\n      <div class={styles.secondPageHeader}>\n        <ButtonIconTsx\n          icon=\"back\"\n          onClick={props.onBack}\n        />\n        <div class=\"popup-title\">\n          {i18n('StarGiftSendGift')}\n        </div>\n        {StarsBalance()}\n      </div>\n\n      <div class={styles.secondPageBody}>\n        <Scrollable>\n          <FakeBubbles peerId={props.peerId} class={styles.bubblesContainer}>\n            <ServiceBubble message={message()}>\n              {props.chosenGift.type === 'stargift' ? (\n              <StarGiftBubble\n                gift={props.chosenGift}\n                fromId={rootScope.myId}\n                asUpgrade={withUpgrade()}\n                ownerId={props.peerId}\n                message={textWithEntities()}\n                wrapStickerOptions={{play: true, loop: false}}\n              />\n            ) : (\n              <PremiumGiftBubble\n                title={i18n('ActionGiftPremiumTitle2', [formatMonthsDuration(props.chosenGift.months, false)])}\n                subtitle={\n                  textWithEntities() ?\n                    wrapRichText(textWithEntities().text, {entities: textWithEntities().entities}) :\n                    i18n('ActionGiftPremiumSubtitle2')\n                }\n                buttonText={i18n('ActionGiftPremiumView')}\n                assetName={`Gift${props.chosenGift.months}`}\n              />\n            )}\n            </ServiceBubble>\n          </FakeBubbles>\n\n          <div class={styles.formSheet}>\n            {props.chosenGift.type === 'stargift' && (props.chosenGift.raw as StarGift.starGift).availability_total && (\n              <StarGiftLimitedProgress gift={props.chosenGift.raw as StarGift.starGift} />\n            )}\n            <InputFieldTsx\n              class={styles.formInput}\n              placeholder='StarGiftMessagePlaceholder'\n              instanceRef={(input) => {\n                input.input.addEventListener('input', () => {\n                  const value = getRichValueWithCaret(input.input, true)\n                  setTextWithEntities(value.value ? {\n                    _: 'textWithEntities',\n                    text: value.value,\n                    entities: value.entities\n                  } : undefined)\n                })\n              }}\n              maxLength={useAppState()[0].appConfig.stargifts_message_length_max}\n            />\n            {props.chosenGift.type === 'stargift' && (\n              <Row>\n                <Row.CheckboxFieldToggle>\n                  <CheckboxFieldTsx\n                    checked={anonymous()}\n                    toggle\n                    onChange={setAnonymous}\n                  />\n                </Row.CheckboxFieldToggle>\n                <Row.Title>{i18n('StarGiftHideMyName')}</Row.Title>\n              </Row>\n            )}\n            {'months' in props.chosenGift && props.chosenGift.priceStars && (\n              <Row>\n                <Row.CheckboxFieldToggle>\n                  <CheckboxFieldTsx\n                    checked={payWithStars()}\n                    toggle\n                    onChange={setPayWithStars}\n                  />\n                </Row.CheckboxFieldToggle>\n                <Row.Title>\n                  <I18nTsx\n                    key=\"PayWithStars\"\n                    args={[\n                      <StarsStar />,\n                      numberThousandSplitterForStars(props.chosenGift.priceStars)\n                    ]}\n                  />\n                </Row.Title>\n              </Row>\n            )}\n          </div>\n          <div class={styles.formHint}>\n            {props.chosenGift.type === 'stargift' ? i18n('StarGiftHideMyNameHint', [\n              wrapRichText(props.peerName),\n              wrapRichText(props.peerName)\n            ]) : ''}\n          </div>\n\n          {props.chosenGift.type === 'stargift' && (props.chosenGift.raw as StarGift.starGift).upgrade_stars && (\n            <>\n              <div class={styles.formSheet}>\n                <Row>\n                  <Row.CheckboxFieldToggle>\n                    <CheckboxFieldTsx\n                      checked={withUpgrade()}\n                      toggle\n                      onChange={setWithUpgrade}\n                    />\n                  </Row.CheckboxFieldToggle>\n                  <Row.Title>\n                    <I18nTsx\n                      key=\"StarGiftMakeUnique\"\n                      args={[\n                        <StarsStar />,\n                        numberThousandSplitterForStars((props.chosenGift.raw as StarGift.starGift).upgrade_stars)\n                      ]}\n                    >\n                    </I18nTsx>\n                  </Row.Title>\n                </Row>\n              </div>\n              <div class={styles.formHint}>\n                <I18nTsx\n                  key=\"StarGiftMakeUniqueHint\"\n                  args={[\n                    wrapRichText(props.peerName),\n                    (() => {\n                      const a = anchorCallback(() => createStarGiftUpgradePopup({\n                        gift: props.chosenGift as MyStarGift,\n                        descriptionForPeerId: props.peerId\n                      }));\n                      a.append(i18n('StarGiftMakeUniqueLink'));\n                      return a;\n                    })()\n                  ]}\n                />\n              </div>\n            </>\n          )}\n        </Scrollable>\n      </div>\n\n      <Button\n        class={`${styles.formSend} btn-primary btn-color-primary`}\n        onClick={handleSubmit}\n        disabled={sending()}\n      >\n        <I18nTsx\n          key=\"StarGiftSend\"\n          args={[(() => {\n            if(props.chosenGift.type === 'stargift') {\n              const gift = props.chosenGift.raw as StarGift.starGift;\n              let stars = gift.stars;\n              if(withUpgrade()) {\n                stars = bigInt(stars as string).add(gift.upgrade_stars).toString();\n              }\n              return paymentsWrapCurrencyAmount(stars, STARS_CURRENCY);\n            }\n\n            if(payWithStars()) {\n              return paymentsWrapCurrencyAmount(\n                props.chosenGift.priceStars,\n                STARS_CURRENCY\n              );\n            }\n\n            return paymentsWrapCurrencyAmount(\n              props.chosenGift.price,\n              props.chosenGift.currency\n            );\n          })()\n          ]}\n        />\n      </Button>\n    </div>\n  )\n}\n\nexport default class PopupSendGift extends PopupElement {\n  private chosenGift: Accessor<MyStarGift | MyPremiumGiftOption | undefined>;\n  private setChosenGift: Setter<MyStarGift | MyPremiumGiftOption>;\n\n  readonly peerId: PeerId;\n  readonly resaleParams?: {\n    giftId: Long;\n    filter?: StarGiftAttribute;\n  };\n\n  constructor(options: {\n    peerId: PeerId;\n    resaleParams?: PopupSendGift['resaleParams'];\n  }) {\n    super(styles.popup, {\n      title: 'StarGiftSendGift',\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      onBackClick: () => {\n        if(this.chosenGift()) {\n          this.setChosenGift(undefined);\n        }\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  private async construct() {\n    const [profileStore, profileStoreActions] = createProfileGiftsStore({\n      peerId: rootScope.myId,\n      initialFilters: {\n        unlimited: false,\n        limited: false,\n        upgradable: false\n      }\n    })\n    const [premiumOptions, giftOptions, peer] = await Promise.all([\n      this.peerId.isUser() ? this.managers.appGiftsManager.getPremiumGiftOptions() : [] as MyPremiumGiftOption[],\n      this.managers.appGiftsManager.getStarGiftOptions(),\n      this.managers.appPeersManager.getPeer(this.peerId),\n      !this.resaleParams && this.peerId !== rootScope.myId && profileStoreActions.loadNext()\n    ]);\n\n    const [chosenGift, setChosenGift] = createSignal<GiftOption>();\n    if(this.resaleParams) {\n      setChosenGift(giftOptions.find((it) => it.raw.id === this.resaleParams.giftId && it.isResale));\n    }\n    this.chosenGift = chosenGift;\n    this.setChosenGift = setChosenGift;\n\n    const [currentPage, setCurrentPage] = createSignal(this.resaleParams ? 2 : 0);\n\n    const secondPageNavigationItem: NavigationItem = {\n      type: 'left',\n      onPop: () => void setCurrentPage(0)\n    }\n\n    onCleanup(() => {\n      appNavigationController.removeItem(secondPageNavigationItem);\n    });\n\n    this.container.replaceChildren();\n    const dispose = render(() => (\n      <>\n        <TransitionSliderTsx\n          type=\"navigation\"\n          transitionTime={150}\n          animateFirst={false}\n          onTransitionStart={(id) => {\n            this.container.classList.toggle(styles.isChosenGift, id === 1);\n\n            if(id === 0) {\n              appNavigationController.removeItem(secondPageNavigationItem);\n            } else {\n              appNavigationController.pushItem(secondPageNavigationItem);\n            }\n          }}\n          onTransitionEnd={(id) => {\n            if(id === 0) {\n              this.setChosenGift(undefined);\n            }\n          }}\n          currentPage={currentPage()}\n        >\n          <GiftOptionsPage\n            peer={peer as User.user | Chat.channel}\n            peerId={this.peerId}\n            premiumOptions={premiumOptions}\n            giftOptions={giftOptions}\n            onGiftChosen={(option) => {\n              setChosenGift(option);\n              setCurrentPage((option as MyStarGift).isResale ? 2 : 1);\n            }}\n            onClose={() => this.hide()}\n            profileStore={profileStore}\n            profileStoreActions={profileStoreActions}\n          />\n          <Show when={chosenGift() !== undefined && !(chosenGift() as MyStarGift).isResale}>\n            <ChosenGiftPage\n              peerId={this.peerId}\n              peerName={peer._ === 'user' ? peer.first_name : peer.title}\n              chosenGift={chosenGift()}\n              onBack={() => setCurrentPage(0)}\n              onClose={() => this.hide()}\n            />\n          </Show>\n          <Show when={chosenGift() !== undefined && (chosenGift() as MyStarGift).isResale}>\n            <ResaleOptionsPage\n              gift={chosenGift() as MyStarGift}\n              peerId={this.peerId}\n              isFirst={this.resaleParams !== undefined}\n              onBack={() => setCurrentPage(0)}\n              onClose={() => this.hide()}\n              initialFilter={this.resaleParams?.filter}\n            />\n          </Show>\n        </TransitionSliderTsx>\n        <FloatingStarsBalance class={styles.starsBalance} />\n      </>\n    ), this.container);\n\n    this.addEventListener('closeAfterTimeout', dispose);\n    this.show();\n  }\n}\n","import {createSignal, Show} from 'solid-js';\nimport showDatePickerPopup from '@components/popups/datePicker';\nimport PopupElement from '@components/popups/indexTsx';\nimport Row from '@components/rowTsx';\nimport InlineSelect from '@components/sidebarLeft/tabs/passcodeLock/inlineSelect';\nimport {IconTsx} from '@components/iconTsx';\nimport {i18n} from '@lib/langPack';\nimport {hideToast, toastNew} from '@components/toast';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupPremium from '@components/popups/premium';\nimport {SEND_WHEN_ONLINE_TIMESTAMP} from '@appManagers/constants';\nimport rootScope from '@lib/rootScope';\n\nconst DAY = 86400;\nconst REPEAT_OPTIONS: {value: number, label: () => HTMLElement}[] = [\n  {value: 0, label: () => i18n('Never')},\n  {value: DAY, label: () => i18n('Schedule.Repeat.Daily')},\n  {value: 7 * DAY, label: () => i18n('Schedule.Repeat.Weekly')},\n  {value: 14 * DAY, label: () => i18n('Schedule.Repeat.Biweekly')},\n  {value: 30 * DAY, label: () => i18n('Schedule.Repeat.Monthly')},\n  {value: 91 * DAY, label: () => i18n('Schedule.Repeat.Every3Months')},\n  {value: 182 * DAY, label: () => i18n('Schedule.Repeat.Every6Months')},\n  {value: 365 * DAY, label: () => i18n('Schedule.Repeat.Yearly')}\n];\n\nexport type ScheduleSendingPopupOptions = {\n  initDate?: Date,\n  addMinutes?: boolean,\n  initRepeatPeriod?: number,\n  canSendWhenOnline?: boolean,\n  onPick: (timestamp: number, repeatPeriod?: number) => void\n};\n\n/**\n * Schedule-message variant of the date picker.\n *\n * Wraps {@link showDatePickerPopup} with two schedule-specific extras that\n * don't belong in the generic picker:\n *  - a \"Repeat\" row (premium-gated) that surfaces a recurring period selector\n *  - a \"Send when online\" secondary footer button that emits a sentinel\n *    {@link SEND_WHEN_ONLINE_TIMESTAMP}\n *\n * The picker stays domain-agnostic; everything specific to scheduling\n * messages lives here.\n */\nexport default function showScheduleSendingPopup(opts: ScheduleSendingPopupOptions): void {\n  // Plain mutable variable rather than a Solid signal — we only need to read\n  // it once at confirm time, and the RepeatRow component owns the reactive\n  // state internally for its own UI.\n  let selectedRepeatPeriod = opts.initRepeatPeriod || 0;\n\n  showDatePickerPopup({\n    initDate: opts.initDate ?? new Date(),\n    addMinutes: opts.addMinutes ?? (opts.initDate === undefined),\n    withTime: true,\n    onPick: (timestamp) => {\n      opts.onPick(timestamp, selectedRepeatPeriod || undefined);\n    },\n    bodyAfter: () => (\n      <RepeatRow\n        initValue={opts.initRepeatPeriod || 0}\n        onChange={(v) => selectedRepeatPeriod = v}\n      />\n    ),\n    footerAfter: opts.canSendWhenOnline ? () => (\n      <PopupElement.FooterButton\n        color=\"secondary\"\n        class=\"popup-schedule-secondary\"\n        langKey=\"Schedule.SendWhenOnline\"\n        callback={() => opts.onPick(SEND_WHEN_ONLINE_TIMESTAMP)}\n      />\n    ) : undefined\n  });\n}\n\nfunction RepeatRow(props: {initValue: number, onChange: (value: number) => void}) {\n  const [value, setValue] = createSignal(props.initValue);\n  const [selectOpen, setSelectOpen] = createSignal(false);\n  let rowEl: HTMLElement;\n\n  function onClick() {\n    if(!rootScope.premium) {\n      toastNew({\n        langPackKey: 'Schedule.Repeat.PremiumRequired',\n        langPackArguments: [\n          anchorCallback(() => {\n            hideToast();\n            PopupPremium.show();\n          })\n        ]\n      });\n      return;\n    }\n    setSelectOpen((v) => !v);\n  }\n\n  return (\n    <Row\n      ref={rowEl}\n      clickable={onClick}\n      class=\"popup-schedule-repeat\"\n    >\n      <Row.Title>{i18n('Schedule.Repeat')}</Row.Title>\n      <Row.RightContent>\n        <InlineSelect\n          value={value()}\n          onChange={(next: number) => {\n            setValue(next);\n            props.onChange(next);\n            setSelectOpen(false);\n          }}\n          options={REPEAT_OPTIONS}\n          parent={rowEl}\n          isOpen={selectOpen()}\n          onClose={() => setSelectOpen(false)}\n        />\n        <Show when={!rootScope.premium}>\n          <IconTsx icon=\"premium_lock\" class=\"primary\" />\n        </Show>\n      </Row.RightContent>\n    </Row>\n  );\n}\n","import {AdminLog} from '@appManagers/appChatsManager';\nimport {MyMessage} from '@appManagers/appMessagesManager';\nimport {VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {wrapSlowModeLeftDuration} from '@components/wrappers/wrapDuration';\nimport {formatFullSentTimeRaw, formatTime} from '@helpers/date';\nimport eachSecond from '@helpers/eachSecond';\nimport {Document, Message} from '@layer';\n\n\nexport function isMessageForVerificationBot(message: MyMessage) {\n  const isCorrectPeer = message.fromId === VERIFICATION_CODES_BOT_ID || getPeerId(message.peer_id) === VERIFICATION_CODES_BOT_ID;\n  return isCorrectPeer && message._ === 'message';\n}\n\nexport function isVerificationBot(peerId: PeerId) {\n  return peerId === VERIFICATION_CODES_BOT_ID;\n}\n\n// * a guest-chat message (a guest bot's reply routed into this chat) carries guestchat_via_from —\n// * the visitor (the user who invoked the bot); message.fromId stays the bot itself\nexport function isGuestChatMessage(message: MyMessage | AdminLog) {\n  return message._ === 'message' && !!message.guestchat_via_from;\n}\n\nexport function getGuestChatViaFromId(message: MyMessage | AdminLog): PeerId {\n  return message._ === 'message' && message.guestchat_via_from ? getPeerId(message.guestchat_via_from) : undefined;\n}\n\nexport function getMid(message: MyMessage | AdminLog) {\n  if(message._ === 'channelAdminLogEvent') return +message.id;\n  return message.mid;\n}\n\nexport function isMessage(message: Message | AdminLog) {\n  return message._ === 'message' || message._ === 'messageService';\n}\n\nexport function makeTime(date: Date, includeDate?: boolean) {\n  return includeDate ? formatFullSentTimeRaw(date.getTime() / 1000 | 0, {combined: true}).dateEl : formatTime(date);\n};\n\nexport function generateTail(asSpan?: boolean) {\n  if(asSpan) {\n    const span = document.createElement('span');\n    span.classList.add('bubble-tail');\n    return span;\n  }\n\n  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n  svg.setAttributeNS(null, 'viewBox', '0 0 11 20');\n  svg.setAttributeNS(null, 'width', '11');\n  svg.setAttributeNS(null, 'height', '20');\n  svg.classList.add('bubble-tail');\n\n  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n  use.setAttributeNS(null, 'href', '#message-tail-filled');\n  // use.classList.add('bubble-tail-use');\n\n  svg.append(use);\n\n  return svg;\n}\n\nexport function linkColor(el: string | Node) {\n  if(typeof el === 'string') {\n    const span = document.createElement('span');\n    span.textContent = el;\n    span.classList.add('link-color');\n    return span;\n  }\n\n  if(el instanceof HTMLElement) el.classList.add('link-color');\n\n  return el;\n}\n\n\nexport type AttachedMediaType = 'document' | 'media';\n\ntype CanUploadAsWhenEditingArgs = {\n  asWhat: AttachedMediaType;\n  message: Message.message | null | undefined;\n};\n\nconst allowedDocumentTypesAsGroup: Array<Document.document['type']> = ['audio', 'photo', 'pdf'];\nconst documentAsMediaTypes: Array<Document.document['type']> = ['gif', 'video'];\n\nexport const canUploadAsWhenEditing = ({asWhat, message}: CanUploadAsWhenEditingArgs) => {\n  if(!message || !message.media) return true;\n\n  const isGrouped = !!message.grouped_id;\n  if(!isGrouped) return true;\n\n  const currentMediaType = getMediaTypeForMessage(message);\n\n  return currentMediaType === asWhat;\n};\n\nexport const getMediaTypeForMessage = (message: Message.message | null | undefined): AttachedMediaType | null => {\n  if(!message || !message.media) return null;\n\n  if(message.media._ === 'messageMediaDocument') {\n    if(message.media.document?._ !== 'document') return null;\n    if(documentAsMediaTypes.includes(message.media.document.type)) return 'media';\n    if(message.media.document.type && !allowedDocumentTypesAsGroup.includes(message.media.document.type)) return null;\n\n    return 'document';\n  }\n\n  if(message.media._ === 'messageMediaPhoto') {\n    return 'media';\n  }\n\n  return null;\n};\n\nexport function slowModeTimer(getLeftDuration: () => number) {\n  const s = document.createElement('span');\n  const dispose = eachSecond(() => {\n    const leftDuration = getLeftDuration();\n    s.replaceChildren(wrapSlowModeLeftDuration(leftDuration));\n\n    if(!leftDuration) {\n      close();\n    }\n  }, true);\n  return {element: s, dispose};\n}\n","import Button from '@components/button';\n\nconst ButtonCorner = (options: Partial<{className: string, icon: Icon, noRipple: true, onlyMobile: true, asDiv: boolean}> = {}) => {\n  const button = Button('btn-circle btn-corner z-depth-1' + (options.className ? ' ' + options.className : ''), options);\n  button.tabIndex = -1;\n  return button;\n};\n\nexport default ButtonCorner;\n","import {getAppWindow} from '@helpers/appWindow';\n\nexport default function cancelSelection() {\n  const win = getAppWindow();\n  if(win.getSelection) {\n    if(win.getSelection().empty) {  // Chrome\n      win.getSelection().empty();\n    } else if(win.getSelection().removeAllRanges) {  // Firefox\n      win.getSelection().removeAllRanges();\n    }\n    // @ts-ignore\n  } else if(document.selection) {  // IE?\n    // @ts-ignore\n    document.selection.empty();\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// * What the message-input `keyup` listener needs to do for a given key press.\n// * - 'skip': the key cannot change content nor move the caret (pure modifiers,\n// *   locks, dead/IME-composition keys) — nothing to re-check, bail before any\n// *   DOM walk.\n// * - 'content-handled': the key changes content (typed char, Backspace, Delete,\n// *   Enter, ...) — the `input` event already fired BEFORE this `keyup` and the\n// *   input handler already re-parsed + called checkAutocomplete with the parsed\n// *   value, so `keyup` re-doing it is pure redundant work (it would bail at the\n// *   previousQuery guard anyway). Skip the re-walk.\n// * - 'caret-move': the key can move the caret WITHOUT firing an `input` event\n// *   (arrows, Home/End, PageUp/PageDown — including with a modifier held, e.g. Cmd/Option/\n// *   Ctrl + arrow for line/word navigation) — no input handler ran, so `keyup` must re-check\n// *   autocomplete (the query depends on caret position).\nexport type InputKeyupAction = 'skip' | 'content-handled' | 'caret-move';\n\n// * keys that move the caret but never emit an `input` event\nconst CARET_MOVE_KEYS = new Set<string>([\n  'ArrowLeft',\n  'ArrowRight',\n  'ArrowUp',\n  'ArrowDown',\n  'Home',\n  'End',\n  'PageUp',\n  'PageDown'\n]);\n\n// * single-char content keys handled here for completeness; the length-based\n// * branch below already covers every printable character (e.key is the char)\nconst CONTENT_EDIT_KEYS = new Set<string>([\n  'Backspace',\n  'Delete',\n  'Enter'\n]);\n\nexport default function classifyInputKeyup(e: Pick<KeyboardEvent, 'key' | 'ctrlKey' | 'metaKey' | 'altKey'>): InputKeyupAction {\n  const key = e.key;\n\n  // * caret-navigation keys move the caret WITHOUT firing an `input` event, so keyup is the\n  // * only chance to re-check autocomplete — and this holds even with a modifier held: Cmd+←/→\n  // * (macOS line start/end), Option+←/→ and Ctrl+←/→ (word jump) are caret moves, not text\n  // * entry. So this MUST be checked before the modifier-combo guard below.\n  if(CARET_MOVE_KEYS.has(key)) {\n    return 'caret-move';\n  }\n\n  // * a modifier combo (Ctrl/Meta/Alt held) is a shortcut, not text entry; markdown\n  // * shortcuts are applied in keydown and emit their own input event when they change\n  // * content, so keyup has nothing extra to do\n  if(e.ctrlKey || e.metaKey || e.altKey) {\n    return 'skip';\n  }\n\n  // * printable characters report a single-codepoint e.key (e.g. 'a', '本', ':') — these\n  // * always fire an `input` event, so the input handler already covered them\n  if(key && Array.from(key).length === 1) {\n    return 'content-handled';\n  }\n\n  if(CONTENT_EDIT_KEYS.has(key)) {\n    return 'content-handled';\n  }\n\n  // * everything else (Shift, Control, Alt, Meta, CapsLock, Tab, Escape, F-keys,\n  // * Dead, Process/IME composition keys, ...) changes neither content nor caret\n  return 'skip';\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// * The emoji-keyword index requires at least this many matched chars to return a hit\n// * (SearchIndex minChars=2 in appEmojiManager.searchEmojis). A shorter bare-word query\n// * can never produce a result, so searching it is a wasted SharedWorker round-trip.\nconst EMOJI_QUERY_MIN_CHARS = 2;\n\n// * Should the emoji autocomplete actually run a SharedWorker emoji search for this query?\n// *\n// * - A `:`-prefixed query (firstChar === ':') is an explicit emoji query — always search,\n// *   exactly as before (the user is deliberately typing `:foo`, suggestions appear as they\n// *   type even at one char).\n// * - A bare-word query (any other firstChar, e.g. typing prose) is searched as an emoji\n// *   keyword too — but only once it has enough chars to possibly match the index. A 1-char\n// *   bare token (every keystroke of normal prose: \"h\", \"w\", ...) can NEVER yield a result\n// *   (minChars=2), so we skip the round-trip; the helper ends up hidden either way.\n//\n// * `query` here is the trailing token extracted by AUTO_COMPLETE_REG_EXP, with only leading\n// * whitespace removed by the caller (`query.replace(/^\\s*/, '')`). A leading `:`, if any, is\n// * NOT stripped — it stays in both `query` and `firstChar` (= query[0]) — so we treat the raw\n// * length and special-case `firstChar === ':'` above.\nexport default function isPlausibleEmojiQuery(query: string, firstChar: string): boolean {\n  if(!query) {\n    return false;\n  }\n\n  // * explicit `:emoji` query — preserve the original always-search behavior\n  if(firstChar === ':') {\n    return true;\n  }\n\n  // * bare-word query — only worth a search once it can match the index\n  return query.length >= EMOJI_QUERY_MIN_CHARS;\n}\n","import type ChatInput from '@components/chat/input';\nimport type StickersHelper from '@components/chat/stickersHelper';\nimport {appendEmoji as wrapAppEmoji, getEmojiFromElement} from '@components/emoticonsDropdown/tabs/emoji';\nimport {ScrollableX} from '@components/scrollable';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport {AppManagers} from '@lib/managers';\nimport {CustomEmojiRendererElement} from '@lib/customEmoji/renderer';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport CustomEmojiElement from '@lib/customEmoji/element';\nimport attachStickerViewerListeners from '@components/stickerViewer';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport rootScope from '@lib/rootScope';\n\nexport default class EmojiHelper extends AutocompleteHelper {\n  private scrollable: ScrollableX;\n  private innerList: HTMLElement;\n  // * set when the helper is suggesting custom emoji for a regular emoji typed before the caret\n  private emoticon: string;\n  private stickersHelper: StickersHelper;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    private chatInput: ChatInput,\n    private managers: AppManagers\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'x',\n      onSelect: (target) => {\n        chatInput.onEmojiSelected(getEmojiFromElement(target as any), true, this.emoticon);\n      },\n      getNavigationList: () => this.innerList\n    });\n\n    this.container.classList.add('emoji-helper');\n  }\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add('emoji-helper-emojis', 'super-emojis');\n\n    this.container.append(this.list);\n\n    this.scrollable = new ScrollableX(this.container);\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n    });\n  }\n\n  private async renderEmojis(emojis: AppEmoji[], middleware: Middleware) {\n    const container = this.list.cloneNode() as HTMLElement;\n    const customEmojis: Parameters<CustomEmojiRendererElement['add']>[0]['addCustomEmojis'] = new Map();\n    const inner = this.innerList = document.createElement('span');\n    container.append(inner);\n\n    if(!rootScope.premium) {\n      emojis = emojis.filter((emoji) => this.chatInput.emoticonsDropdown.canUseEmoji(emoji, false));\n    }\n\n    emojis.forEach((emoji) => {\n      const wrapped = wrapAppEmoji(emoji, true);\n      inner.append(wrapped);\n\n      if(emoji.docId) {\n        const customEmojiElement = wrapped.firstElementChild as CustomEmojiElement;\n        // customEmojiElement.clear(false);\n        // const customEmojiElement = CustomEmojiElement.create(document.id);\n        customEmojis.set(customEmojiElement.docId, new Set([customEmojiElement]));\n      }\n    });\n\n    if(customEmojis.size) {\n      const _middleware = getMiddleware();\n      middleware.create().get().onClean(() => {\n        setTimeout(() => _middleware.destroy(), 500); // * fix video flick\n      });\n\n      const customEmojiRenderer = CustomEmojiRendererElement.create({\n        animationGroup: 'INLINE-HELPER',\n        customEmojiSize: mediaSizes.active.esgCustomEmoji,\n        textColor: 'primary-text-color',\n        observeResizeElement: false,\n        middleware: _middleware.get()\n      });\n\n      container.prepend(customEmojiRenderer);\n\n      customEmojiRenderer.setDimensionsFromRect({\n        width: (emojis.length * 42) + 8,\n        height: 42\n      });\n\n      const listenerSetter = new ListenerSetter();\n      middleware.onClean(() => {\n        listenerSetter.removeAll();\n        if(this.innerList === inner) {\n          this.innerList = undefined;\n        }\n      });\n      attachStickerViewerListeners({listenTo: this.container, listenerSetter});\n\n      await customEmojiRenderer.add({\n        addCustomEmojis: customEmojis\n      });\n    }\n\n    return container;\n  }\n\n  public async render(emojis: AppEmoji[], waitForKey: boolean, middleware: Middleware) {\n    if(this.init) {\n      if(!emojis.length) {\n        return;\n      }\n\n      this.init();\n      this.init = null;\n    }\n\n    if(!emojis.length) {\n      this.toggle(true);\n      return;\n    }\n\n    emojis = emojis.slice(0, 80);\n\n    const container = await this.renderEmojis(emojis, middleware);\n    if(!middleware()) {\n      return;\n    }\n\n    this.list.replaceWith(container);\n    this.list = container;\n    this.waitForKey = waitForKey ? ['ArrowUp', 'ArrowDown'] : undefined;\n\n    this.toggle(false);\n    this.scrollable.scrollPosition = 0;\n\n    /* window.requestAnimationFrame(() => {\n      this.container.style.width = (3 * 2) + (emojis.length * 44) + 'px';\n    }); */\n  }\n\n  public checkQuery(query: string, firstChar: string) {\n    const middleware = this.getMiddleware();\n    this.emoticon = undefined;\n    const q = query.replace(/^:/, '');\n    this.managers.appEmojiManager.prepareAndSearchEmojis({q, addCustom: true}).then(async(emojis) => {\n      if(!middleware()) {\n        return;\n      }\n\n      this.render(emojis, firstChar !== ':', middleware);\n      // console.log(emojis);\n    });\n  }\n\n  // * the two helpers can both be visible. emoji helper overlays on top of the stickers helper\n  // * via DOM order; we still need to hide it when the user scrolls the stickers panel so the\n  // * stickers underneath the strip are reachable\n  public attachStickersHelper(stickersHelper: StickersHelper) {\n    this.stickersHelper = stickersHelper;\n    stickersHelper.container.addEventListener('scroll', this.onStickersScroll, {passive: true, capture: true});\n  }\n\n  private onStickersScroll = () => {\n    // * fromController=true so the cascade in toggle() doesn't also hide the stickers panel\n    if(!this.hidden) {\n      this.toggle(true, true);\n    }\n  };\n\n  // * suggest custom emoji variants for a regular emoji typed right before the caret\n  public checkEmoticon(emoticon: string) {\n    const middleware = this.getMiddleware();\n    this.emoticon = emoticon;\n    this.managers.appEmojiManager.searchCustomEmoji(emoticon).then((emojiList) => {\n      if(!middleware()) {\n        return;\n      }\n\n      let emojis: AppEmoji[] = emojiList.document_id.map((docId) => ({docId, emoji: ''}));\n      // * the result is custom emoji only — drop the ones a non-premium user can't use here,\n      // * otherwise render() would show an empty strip instead of hiding it\n      if(!rootScope.premium) {\n        emojis = emojis.filter((emoji) => this.chatInput.emoticonsDropdown.canUseEmoji(emoji, false));\n      }\n\n      this.render(emojis, true, middleware);\n    });\n  }\n}\n","import setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {Middleware} from '@helpers/middleware';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {avatarNew} from '@components/avatarNew';\nimport PeerTitle from '@components/peerTitle';\nimport Scrollable from '@components/scrollable';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\n\nexport default class AutocompletePeerHelper extends AutocompleteHelper {\n  protected static BASE_CLASS = 'autocomplete-peer-helper';\n  protected static BASE_CLASS_LIST_ELEMENT = AutocompletePeerHelper.BASE_CLASS + '-list-element';\n  private scrollable: Scrollable;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    protected className: string,\n    onSelect: (target: Element) => boolean | void\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'y',\n      onSelect\n    });\n\n    this.container.classList.add(AutocompletePeerHelper.BASE_CLASS, className);\n  }\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add(AutocompletePeerHelper.BASE_CLASS + '-list', this.className + '-list');\n\n    this.container.append(this.list);\n\n    this.scrollable = new Scrollable(this.container);\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n    });\n  }\n\n  public render(\n    data: {peerId: PeerId, name?: string, description?: string}[],\n    middleware: Middleware,\n    doNotShow?: boolean\n  ) {\n    if(this.init) {\n      if(!data.length) {\n        return;\n      }\n\n      this.init();\n      this.init = null;\n    }\n\n    if(data.length) {\n      this.list.replaceChildren();\n      data.forEach((d) => {\n        const div = AutocompletePeerHelper.listElement({\n          className: this.className,\n          peerId: d.peerId,\n          name: d.name,\n          description: d.description,\n          middleware\n        });\n\n        this.list.append(div);\n      });\n    }\n\n    if(!doNotShow) {\n      this.toggle(!data.length);\n    }\n  }\n\n  public static listElement(options: {\n    className: string,\n    peerId: PeerId,\n    name?: string,\n    description?: string,\n    middleware: Middleware\n  }) {\n    const BASE = AutocompletePeerHelper.BASE_CLASS_LIST_ELEMENT;\n    options.className += '-list-element';\n\n    const div = document.createElement('div');\n    div.classList.add(BASE, options.className);\n    div.dataset.peerId = '' + options.peerId;\n\n    const {node} = avatarNew({\n      middleware: options.middleware,\n      isBig: false,\n      size: 30,\n      peerId: options.peerId\n    });\n    node.classList.add(BASE + '-avatar', options.className + '-avatar');\n\n    const name = document.createElement('div');\n    name.classList.add(BASE + '-name', options.className + '-name');\n    if(!options.name) {\n      name.append(new PeerTitle({\n        peerId: options.peerId,\n        dialog: false,\n        onlyFirstName: false,\n        plainText: false\n      }).element);\n    } else {\n      setInnerHTML(name, wrapEmojiText(options.name));\n    }\n\n    div.append(node, name);\n\n    if(options.description) {\n      const description = document.createElement('div');\n      description.classList.add(BASE + '-description', options.className + '-description');\n      setInnerHTML(description, wrapEmojiText(options.description));\n      div.append(description);\n    }\n\n    return div;\n  }\n}\n","import type ChatInput from '@components/chat/input';\nimport type {BotInfo, ChatFull, UserFull} from '@layer';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport AutocompletePeerHelper from '@components/chat/autocompletePeerHelper';\nimport SearchIndex from '@lib/searchIndex';\nimport {AppManagers} from '@lib/managers';\n\nexport function processPeerFullForCommands(peerId: PeerId, full: ChatFull.chatFull | ChatFull.channelFull | UserFull.userFull, query?: string) {\n  const botInfos: BotInfo.botInfo[] = [].concat(full.bot_info);\n  let index: SearchIndex<string>;\n\n  if(query !== undefined) {\n    index = new SearchIndex<string>({\n      ignoreCase: true\n    });\n  }\n\n  type T = {peerId: PeerId, name: string, description: string, index: number, command: string};\n  const commands: Map<string, T> = new Map();\n  botInfos.forEach((botInfo) => {\n    if(!botInfo.commands) {\n      return;\n    }\n\n    botInfo.commands.forEach(({command, description}, idx) => {\n      const c = '/' + command;\n      commands.set(command, {\n        peerId: botInfo.user_id ? botInfo.user_id.toPeerId(false) : peerId,\n        command: command,\n        name: c,\n        description: description,\n        index: idx\n      });\n\n      if(index) {\n        index.indexObject(command, c);\n      }\n    });\n  });\n\n  let out: T[];\n  if(!index) {\n    out = [...commands.values()];\n  } else {\n    const found = index.search(query);\n    out = Array.from(found).map((command) => commands.get(command));\n  }\n\n  out = out.sort((a, b) => commands.get(a.command).index - commands.get(b.command).index);\n\n  return out;\n}\n\nexport default class CommandsHelper extends AutocompletePeerHelper {\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    chatInput: ChatInput,\n    private managers: AppManagers\n  ) {\n    super(appendTo,\n      controller,\n      'commands-helper',\n      (target) => {\n        const innerHTML = target.querySelector(`.${AutocompletePeerHelper.BASE_CLASS_LIST_ELEMENT}-name`).innerHTML;\n        return chatInput.getReadyToSend(() => {\n          chatInput.messageInput.innerHTML = innerHTML;\n          chatInput.sendMessage(true);\n        });\n      }\n    );\n  }\n\n  public async checkQuery(query: string, peerId: PeerId) {\n    if(!(await this.managers.appUsersManager.isBot(peerId))) {\n      return false;\n    }\n\n    const middleware = this.controller.getMiddleware();\n    this.managers.appProfileManager.getProfileByPeerId(peerId).then((full) => {\n      if(!middleware()) {\n        return;\n      }\n\n      const filtered = processPeerFullForCommands(peerId, full, query);\n      this.render(filtered, middleware);\n      // console.log('found commands', found, filtered);\n    });\n\n    return true;\n  }\n}\n","import type ChatInput from '@components/chat/input';\nimport Scrollable from '@components/scrollable';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {Middleware} from '@helpers/middleware';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport {AppManagers} from '@lib/managers';\nimport {QuickReply} from '@lib/quickReplies/types';\nimport rootScope from '@lib/rootScope';\n\ntype HelperReply = {\n  id: string,\n  title: string,\n  text: string,\n  source?: 'crm',\n  // set for CRM templates that carry attached images, sent alongside the text\n  crmTemplateId?: number,\n  imageCount?: number\n};\n\n// * keep the combined local + CRM reply list warm so typing each `/` query doesn't re-hit the\n// * CRM network (getTemplates / getFaqs are uncached). refreshed on a short TTL and on the\n// * quick_replies_update event below.\nconst CACHE_TTL = 60_000;\n\nexport default class QuickRepliesHelper extends AutocompleteHelper {\n  private static BASE_CLASS = 'quick-replies-helper';\n  private static LIST_ELEMENT = QuickRepliesHelper.BASE_CLASS + '-list-element';\n\n  private scrollable: Scrollable;\n  // * the currently rendered, filtered replies — onSelect maps the chosen element back via its index\n  private rendered: HelperReply[];\n\n  private cache: HelperReply[];\n  private cacheTime: number;\n  private cachePromise: Promise<HelperReply[]>;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    private chatInput: ChatInput,\n    private managers: AppManagers\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'y',\n      onSelect: (target) => {\n        const index = +(target as HTMLElement).dataset.index;\n        const reply = this.rendered?.[index];\n        if(!reply) return;\n        // * isHelper=true replaces the typed `/query` token with the reply text; an\n        // * image-bearing CRM template additionally stages its images in the send-preview\n        this.chatInput.insertQuickReply({\n          text: reply.text,\n          crmTemplateId: reply.crmTemplateId,\n          hasImages: !!reply.imageCount,\n          isHelper: true\n        });\n      }\n    });\n\n    this.container.classList.add(QuickRepliesHelper.BASE_CLASS);\n\n    rootScope.addEventListener('quick_replies_update', this.invalidate);\n  }\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add(QuickRepliesHelper.BASE_CLASS + '-list');\n\n    this.container.append(this.list);\n\n    this.scrollable = new Scrollable(this.container);\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n    });\n  }\n\n  private invalidate = () => {\n    this.cache = undefined;\n    this.cacheTime = 0;\n    this.cachePromise = undefined;\n  };\n\n  private getReplies(): Promise<HelperReply[]> {\n    if(this.cache && (Date.now() - this.cacheTime) < CACHE_TTL) {\n      return Promise.resolve(this.cache);\n    }\n\n    return this.cachePromise ??= Promise.all([\n      this.managers.appQuickRepliesManager.getQuickReplies(),\n      this.managers.appCrmManager.getTemplates(),\n      this.managers.appCrmManager.getFaqs()\n    ]).then(([local, templates, faqs]) => {\n      const combined: HelperReply[] = [\n        ...local.map((r: QuickReply) => ({id: r.id, title: r.title, text: r.text})),\n        ...templates.map((t) => ({\n          id: 'crm-t-' + t.id,\n          title: t.name,\n          text: t.text,\n          source: 'crm' as const,\n          crmTemplateId: t.id,\n          imageCount: t.image_urls?.length || 0\n        })),\n        ...faqs.map((f) => ({id: 'crm-f-' + f.id, title: f.question, text: f.answer, source: 'crm' as const}))\n      ];\n\n      this.cache = combined;\n      this.cacheTime = Date.now();\n      this.cachePromise = undefined;\n      return combined;\n    }, (err) => {\n      this.cachePromise = undefined;\n      throw err;\n    });\n  }\n\n  private static filter(replies: HelperReply[], query: string) {\n    const q = query.trim().toLowerCase();\n    if(!q) return replies;\n    return replies.filter((reply) =>\n      reply.title.toLowerCase().includes(q) || reply.text.toLowerCase().includes(q)\n    );\n  }\n\n  public checkQuery(query: string) {\n    // * `query` is the full autocomplete token including the leading slash\n    const q = query.replace(/^\\//, '');\n\n    const middleware = this.getMiddleware();\n    this.getReplies().then((replies) => {\n      if(!middleware()) return;\n      this.render(QuickRepliesHelper.filter(replies, q), middleware);\n    }, () => {});\n\n    return true;\n  }\n\n  public render(replies: HelperReply[], middleware: Middleware) {\n    if(this.init) {\n      if(!replies.length) {\n        return;\n      }\n\n      this.init();\n      this.init = null;\n    }\n\n    this.rendered = replies;\n\n    if(!replies.length) {\n      this.toggle(true);\n      return;\n    }\n\n    this.list.replaceChildren();\n    replies.forEach((reply, index) => {\n      this.list.append(QuickRepliesHelper.listElement(reply, index));\n    });\n\n    this.toggle(false);\n    this.scrollable.scrollPosition = 0;\n  }\n\n  private static listElement(reply: HelperReply, index: number) {\n    const BASE = QuickRepliesHelper.LIST_ELEMENT;\n\n    const div = document.createElement('div');\n    div.classList.add(BASE);\n    div.dataset.index = '' + index;\n\n    const name = document.createElement('div');\n    name.classList.add(BASE + '-name');\n    setInnerHTML(name, wrapEmojiText(reply.title));\n\n    if(reply.source === 'crm') {\n      const badge = document.createElement('span');\n      badge.classList.add(BASE + '-badge');\n      badge.textContent = 'CRM';\n      name.append(badge);\n    }\n\n    if(reply.imageCount) {\n      const images = document.createElement('span');\n      images.classList.add(BASE + '-images');\n      images.textContent = (reply.imageCount > 1 ? reply.imageCount + ' ' : '') + '🖼';\n      name.append(images);\n    }\n\n    const text = document.createElement('div');\n    text.classList.add(BASE + '-text');\n    setInnerHTML(text, wrapEmojiText(reply.text));\n\n    div.append(name, text);\n\n    return div;\n  }\n}\n","import {getMiddleware} from '@helpers/middleware';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\n\nexport default class AutocompleteHelperController {\n  private helpers: Set<AutocompleteHelper> = new Set();\n  private middleware = getMiddleware();\n  /* private tempId = 0;\n\n  public incrementToggleCount() {\n    return ++this.tempId;\n  }\n\n  public getToggleCount() {\n    return this.tempId;\n  } */\n\n  public toggleListNavigation(enabled: boolean) {\n    for(const helper of this.helpers) {\n      helper.toggleListNavigation(enabled);\n    }\n  }\n\n  public destroy() {\n    this.middleware.destroy();\n    this.hideOtherHelpers();\n  }\n\n  public getMiddleware() {\n    this.middleware.clean();\n    return this.middleware.get();\n  }\n\n  public addHelper(helper: AutocompleteHelper) {\n    this.helpers.add(helper);\n  }\n\n  public hideOtherHelpers(preserveHelpers?: Set<AutocompleteHelper>) {\n    this.helpers.forEach((helper) => {\n      if(!preserveHelpers?.has(helper)) {\n        helper.toggle(true, true);\n      }\n    });\n\n    if(!preserveHelpers?.size) {\n      this.middleware.clean();\n    }\n  }\n}\n","import type ChatInput from '@components/chat/input';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport AutocompletePeerHelper from '@components/chat/autocompletePeerHelper';\nimport {AppManagers} from '@lib/managers';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport rootScope from '@lib/rootScope';\n\nexport default class MentionsHelper extends AutocompletePeerHelper {\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    chatInput: ChatInput,\n    private managers: AppManagers\n  ) {\n    super(\n      appendTo,\n      controller,\n      'mentions-helper',\n      (target) => {\n        const peerId = (target as HTMLElement).dataset.peerId.toPeerId();\n        chatInput.mentionUser(peerId, true);\n      }\n    );\n  }\n\n  public checkQuery(\n    query: string,\n    peerId: PeerId,\n    topMsgId: number,\n    global?: boolean,\n    includeGuestBots?: boolean\n  ) {\n    const trimmed = query.trim(); // check that there is no whitespace\n    if(query.length !== trimmed.length) return false;\n\n    const middleware = this.controller.getMiddleware();\n    this.managers.appProfileManager.getMentions(\n      peerId && peerId.toChatId(),\n      trimmed,\n      topMsgId,\n      global,\n      includeGuestBots\n    ).then(async(peerIds) => {\n      if(!middleware()) return;\n\n      peerIds = peerIds.filter((peerId) => peerId !== rootScope.myId);\n\n      // const username = trimmed.slice(1).toLowerCase();\n\n      const p = peerIds.map(async(peerId) => {\n        const user = await this.managers.appUsersManager.getUser(peerId);\n        const usernames = getPeerActiveUsernames(user);\n        // if(usernames.length && usernames.some((_username) => _username.toLowerCase() === username)) { // hide full matched suggestion\n        //   return;\n        // }\n\n        return {\n          peerId,\n          description: usernames[0] ? '@' + usernames[0] : undefined\n        };\n      });\n\n      const out = (await Promise.all(p)).filter(Boolean);\n      if(!middleware()) return;\n      this.render(out, middleware);\n    });\n\n    return true;\n  }\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {getAppWindow} from '@helpers/appWindow';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport safeAssign from '@helpers/object/safeAssign';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport rootScope from '@lib/rootScope';\nimport liteMode from '@helpers/liteMode';\n\nconst KEEP_OPEN = false;\nconst TOGGLE_TIMEOUT = 200;\nconst ANIMATION_DURATION = 200;\n\nexport type IgnoreMouseOutType = 'click' | 'menu' | 'popup' | 'tooltip';\ntype DropdownHoverTimeoutType = 'toggle' | 'done';\n\nexport default class DropdownHover extends EventListenerBase<{\n  open: () => Promise<any> | void,\n  openAfterLayout: () => void,\n  opened: () => any,\n  close: () => any,\n  closed: () => any\n}> {\n  protected element: HTMLElement;\n  protected forceClose: boolean;\n  protected inited: boolean;\n  protected ignoreMouseOut: Set<IgnoreMouseOutType>;\n  protected ignoreButtons: Set<HTMLElement>;\n  protected navigationItem: NavigationItem;\n  protected ignoreOutClickClassName: string;\n  protected suppressOutClick: boolean;\n  protected timeouts: {[type in DropdownHoverTimeoutType]?: number};\n  protected detachClickEvent: () => void;\n\n  constructor(options: {\n    element: DropdownHover['element'],\n    ignoreOutClickClassName?: string\n  }) {\n    super(false);\n    safeAssign(this, options);\n    this.forceClose = false;\n    this.inited = false;\n    this.ignoreMouseOut = new Set();\n    this.ignoreButtons = new Set();\n    this.timeouts = {};\n  }\n\n  public attachButtonListener(\n    button: HTMLElement,\n    listenerSetter: ListenerSetter\n  ) {\n    let firstTime = true;\n    if(IS_TOUCH_SUPPORTED) {\n      attachClickEvent(button, () => {\n        if(firstTime) {\n          firstTime = false;\n          this.toggle(true);\n        } else {\n          this.toggle();\n        }\n      }, {listenerSetter});\n    } else {\n      listenerSetter.add(button)('mouseover', (e) => {\n        if(firstTime) {\n          listenerSetter.add(button)('mouseout', (e) => {\n            this.clearTimeout('toggle');\n            this.onMouseOut(e);\n          });\n          firstTime = false;\n        }\n\n        this.setTimeout('toggle', () => {\n          this.toggle(true);\n        }, TOGGLE_TIMEOUT);\n      });\n\n      attachClickEvent(button, this.onButtonClick.bind(this, button), {listenerSetter});\n    }\n  }\n\n  public onButtonClick = (button?: HTMLElement, e?: MouseEvent) => {\n    const type: IgnoreMouseOutType = 'click';\n    const ignore = !this.ignoreMouseOut.has(type);\n\n    if(ignore && !this.ignoreMouseOut.size) {\n      button && this.ignoreButtons.add(button);\n      setTimeout(() => {\n        // Click-outside-to-close on the active window — the dropdown opens in whichever window the app\n        // is in (the tab, or the Document PiP window), so a main-`window` listener never sees the\n        // outside click there and the panel won't dismiss. Same `w` for add + detach so they match.\n        const w = getAppWindow();\n        if(this.suppressOutClick) {\n          const options: AddEventListenerOptions = {capture: true};\n          w.addEventListener('mousedown', this.onMouseDownOut, options);\n          w.addEventListener('click', this.onClickOut, options);\n          this.detachClickEvent = () => {\n            w.removeEventListener('mousedown', this.onMouseDownOut, options);\n            w.removeEventListener('click', this.onClickOut, options);\n          };\n        } else {\n          this.detachClickEvent = attachClickEvent(w, this.onClickOut, {capture: true});\n        }\n      }, 0);\n    }\n\n    this.setIgnoreMouseOut(type, ignore);\n    this.toggle(ignore);\n  };\n\n  protected isOutClickTarget(target: HTMLElement) {\n    return !findUpAsChild(target, this.element) &&\n      !Array.from(this.ignoreButtons).some((button) => findUpAsChild(target, button) || target === button) &&\n      this.ignoreMouseOut.size <= 1 &&\n      (!this.ignoreOutClickClassName || !findUpClassName(target, this.ignoreOutClickClassName));\n  }\n\n  protected onClickOut = (e: MouseEvent) => {\n    const target = e.target as HTMLElement;\n    if(e.isTrusted && this.isOutClickTarget(target)) {\n      if(this.suppressOutClick) {\n        e.stopImmediatePropagation();\n        e.preventDefault();\n      }\n\n      this.toggle(false);\n    }\n  };\n\n  // swallow the mousedown that precedes the out-click, otherwise handlers that\n  // act on mousedown (e.g. the chat list opening a peer) fire before we close\n  protected onMouseDownOut = (e: MouseEvent) => {\n    const target = e.target as HTMLElement;\n    if(e.isTrusted && this.isOutClickTarget(target)) {\n      e.stopImmediatePropagation();\n      e.preventDefault();\n    }\n  };\n\n  protected onMouseOut = (e: MouseEvent) => {\n    if(KEEP_OPEN || !this.isActive()) return;\n    this.clearTimeout('toggle');\n\n    if(this.ignoreMouseOut.size) {\n      return;\n    }\n\n    const toElement = (e as any).toElement as HTMLElement;\n    if(toElement && findUpAsChild(toElement, this.element)) {\n      return;\n    }\n\n    this.setTimeout('toggle', () => {\n      this.toggle(false);\n    }, TOGGLE_TIMEOUT);\n  };\n\n  protected clearTimeout(type: DropdownHoverTimeoutType) {\n    if(this.timeouts[type] !== undefined) {\n      clearTimeout(this.timeouts[type]);\n      delete this.timeouts[type];\n    }\n  }\n\n  protected setTimeout(type: DropdownHoverTimeoutType, cb: () => void, timeout: number) {\n    this.clearTimeout(type);\n    this.timeouts[type] = window.setTimeout(() => {\n      this.clearTimeout(type);\n      cb();\n    }, timeout);\n  }\n\n  public init() {\n    if(!IS_TOUCH_SUPPORTED) {\n      this.element.onmouseout = this.onMouseOut;\n      this.element.onmouseover = (e) => {\n        if(this.forceClose) {\n          return;\n        }\n\n        // console.log('onmouseover element');\n        this.clearTimeout('toggle');\n      };\n    }\n  }\n\n  public toggle = async(enable?: boolean) => {\n    // if(!this.element) return;\n    const willBeActive = (!!this.element.style.display && enable === undefined) || enable;\n    if(this.init) {\n      if(willBeActive) {\n        this.init();\n        this.init = null;\n      } else {\n        return;\n      }\n    }\n\n    if(willBeActive === this.isActive()) {\n      return;\n    }\n\n    const delay = IS_TOUCH_SUPPORTED || !liteMode.isAvailable('animations') ? 0 : ANIMATION_DURATION;\n    if((this.element.style.display && enable === undefined) || enable) {\n      const res = this.dispatchResultableEvent('open');\n      await Promise.all(res);\n\n      this.element.style.display = '';\n      void this.element.offsetLeft; // reflow\n      this.element.classList.add('active');\n\n      this.dispatchEvent('openAfterLayout');\n\n      appNavigationController.pushItem(this.navigationItem = {\n        type: 'dropdown',\n        onPop: () => {\n          this.toggle(false);\n        }\n      });\n\n      this.clearTimeout('toggle');\n      this.setTimeout('done', () => {\n        this.forceClose = false;\n        this.dispatchEvent('opened');\n      }, delay);\n\n      // ! can't use together with resizeObserver\n      /* if(isTouchSupported) {\n        const height = this.element.scrollHeight + appImManager.chat.input.inputContainer.scrollHeight - 10;\n        console.log('[ESG]: toggle: enable height', height);\n        appImManager.chat.bubbles.scrollable.scrollTop += height;\n      } */\n\n      /* if(touchSupport) {\n        this.restoreScroll();\n      } */\n    } else {\n      this.dispatchEvent('close');\n      this.ignoreMouseOut.clear();\n      this.ignoreButtons.clear();\n\n      this.element.classList.remove('active');\n\n      appNavigationController.removeItem(this.navigationItem);\n      this.detachClickEvent?.();\n      this.detachClickEvent = undefined;\n\n      this.clearTimeout('toggle');\n      this.setTimeout('done', () => {\n        this.element.style.display = 'none';\n        this.forceClose = false;\n        this.dispatchEvent('closed');\n      }, delay);\n\n      /* if(isTouchSupported) {\n        const scrollHeight = this.container.scrollHeight;\n        if(scrollHeight) {\n          const height = this.container.scrollHeight + appImManager.chat.input.inputContainer.scrollHeight - 10;\n          appImManager.chat.bubbles.scrollable.scrollTop -= height;\n        }\n      } */\n\n      /* if(touchSupport) {\n        this.restoreScroll();\n      } */\n    }\n\n    // animationIntersector.checkAnimations(false, EMOTICONSSTICKERGROUP);\n  };\n\n  public isActive() {\n    return this.element.classList.contains('active');\n  }\n\n  public setIgnoreMouseOut(type: IgnoreMouseOutType, ignore: boolean) {\n    ignore ? this.ignoreMouseOut.add(type) : this.ignoreMouseOut.delete(type);\n  }\n}\n","import {KeyboardButton, RequestPeerType, Chat as MTChat} from '@layer';\nimport {ChatRights} from '@appManagers/appChatsManager';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport {i18n, join} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport AppSelectPeers, {SelectSearchPeerType} from '@components/appSelectPeers';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {showPickUser2Popup} from '@components/popups/pickUser';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\n// Shows the peer picker described by a `keyboardButtonRequestPeer`, applies the\n// button's peer-type constraints and (for chats/channels) a confirmation step.\n// Resolves with the chosen peer ids; rejects if the user cancels the picker or\n// declines the confirmation. The `requestPeerTypeCreateBot` variant is handled\n// by the caller — this only covers the user/group/channel selection flow.\nexport default async function selectRequestPeers({\n  button,\n  requestingPeerId\n}: {\n  button: KeyboardButton.keyboardButtonRequestPeer,\n  requestingPeerId: PeerId\n}): Promise<PeerId[]> {\n  const peerType = button.peer_type;\n\n  if(peerType._ === 'requestPeerTypeCreateBot') {\n    throw new Error('REQUEST_PEER_CREATE_BOT_UNSUPPORTED');\n  }\n\n  const isRequestingUser = peerType._ === 'requestPeerTypeUser';\n  const isRequestingChannel = peerType._ === 'requestPeerTypeBroadcast';\n  const isRequestingGroup = peerType._ === 'requestPeerTypeChat';\n\n  let filterPeerTypeBy: AppSelectPeers['filterPeerTypeBy'];\n  const _peerType: SelectSearchPeerType[] = ['dialogs'];\n  if(isRequestingUser) {\n    filterPeerTypeBy = (peer) => {\n      if(peer._ !== 'user') {\n        return false;\n      }\n\n      if(peerType.bot !== undefined && peerType.bot !== !!peer.pFlags.bot) {\n        return false;\n      }\n\n      if(peerType.premium !== undefined && peerType.premium !== !!peer.pFlags.premium) {\n        return false;\n      }\n\n      return true;\n    };\n\n    _peerType.push('contacts');\n  } else {\n    let commonChatIds: ChatId[];\n    if(isRequestingGroup) {\n      const messagesChats = await rootScope.managers.appUsersManager.getCommonChats(requestingPeerId, 100);\n      commonChatIds = messagesChats.chats.map((chat) => chat.id);\n    }\n\n    filterPeerTypeBy = (peer) => {\n      if(peer._ !== 'channel' && (isRequestingChannel ? true : peer._ !== 'chat')) {\n        return false;\n      }\n\n      if(!!(peer as MTChat.channel).pFlags.broadcast !== isRequestingChannel) {\n        return false;\n      }\n\n      if(peerType.pFlags.creator && !(peer as MTChat.chat).pFlags.creator) {\n        return false;\n      }\n\n      if(peerType.has_username !== undefined && !!getPeerActiveUsernames(peer)[0] !== !!peerType.has_username) {\n        return false;\n      }\n\n      if((peerType as RequestPeerType.requestPeerTypeChat).forum !== undefined &&\n        (peerType as RequestPeerType.requestPeerTypeChat).forum !== !!(peer as MTChat.channel).pFlags.forum) {\n        return false;\n      }\n\n      if(peerType.user_admin_rights) {\n        for(const action in peerType.user_admin_rights.pFlags) {\n          if(!hasRights(peer as MTChat.channel, action as ChatRights)) {\n            return false;\n          }\n        }\n      }\n\n      if((peerType as RequestPeerType.requestPeerTypeChat).pFlags.bot_participant) {\n        if(!commonChatIds.includes(peer.id) && !hasRights(peer as MTChat.chat, 'invite_users')) {\n          return false;\n        }\n      }\n\n      return true;\n    };\n  }\n\n  const requestedPeerIds = await showPickUser2Popup({\n    peerType: _peerType,\n    filterPeerTypeBy,\n    multiSelect: true,\n    limit: button.max_quantity,\n    limitCallback: () => {\n      toastNew({\n        langPackKey: 'RequestPeer.MultipleLimit',\n        langPackArguments: [\n          i18n(\n            isRequestingUser ? 'RequestPeer.MultipleLimit.Users' : (isRequestingChannel ? 'RequestPeer.MultipleLimit.Channels' : 'RequestPeer.MultipleLimit.Groups'),\n            [button.max_quantity]\n          )\n        ]\n      });\n    },\n    titleLangKey: isRequestingUser ? 'RequestPeer.Title.Users' : (isRequestingChannel ? 'RequestPeer.Title.Channels' : 'RequestPeer.Title.Groups')\n  });\n\n  if(!isRequestingUser) {\n    type P = Parameters<typeof confirmationPopup>[0];\n    const requestedPeerTitles = await Promise.all(requestedPeerIds.map((peerId) => wrapPeerTitle({peerId})));\n    const joinedTitles = join(requestedPeerTitles, false);\n    let joinedTitlesElement: HTMLElement;\n    if(joinedTitles.length === 1) {\n      joinedTitlesElement = joinedTitles[0] as HTMLElement;\n    } else {\n      joinedTitlesElement = document.createElement('span');\n      joinedTitlesElement.append(...joinedTitles);\n    }\n    const descriptionLangArgs: P['descriptionLangArgs'] = [\n      joinedTitlesElement,\n      await wrapPeerTitle({peerId: requestingPeerId})\n    ];\n\n    const descriptionLangKey: P['descriptionLangKey'] = 'Chat.Service.PeerRequest.Confirm.Plain';\n\n    await confirmationPopup({\n      descriptionLangKey,\n      descriptionLangArgs,\n      button: {\n        langKey: 'Chat.Service.PeerRequest.Confirm.Ok'\n      }\n    });\n  }\n\n  return requestedPeerIds;\n}\n","import {children, createContext, createEffect, createMemo, createSignal, For, JSX, Ref, Show, useContext} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport wrapKeyboardButton from '@components/wrappers/keyboardButton';\nimport type Chat from '@components/chat/chat';\nimport {KeyboardButtonRow, Message} from '@layer';\nimport classNames from '@helpers/string/classNames';\nimport {IconTsx} from '@components/iconTsx';\nimport RippleElement from '@components/rippleElement';\n\ntype ContextValue = {\n  elements: () => JSX.Element[]\n};\nconst Context = createContext<ContextValue>();\n\nconst ReplyMarkupLayout = (props: {\n  children?: JSX.Element\n}) => {\n  const [elements, setElements] = createSignal<JSX.Element[]>([]);\n  const value: ContextValue = {\n    elements\n  };\n\n  const resolvedChildren = children(() => (\n    <Context.Provider value={value}>\n      {props.children}\n    </Context.Provider>\n  ));\n\n  createEffect<void>(() => void setElements(resolvedChildren.toArray()));\n\n  return (\n    <div class=\"reply-markup\">\n      {resolvedChildren()}\n    </div>\n  );\n};\n\ntype RowContextValue = {\n  isLast: boolean,\n  elements: () => JSX.Element[]\n};\nconst RowContext = createContext<RowContextValue>();\n\nReplyMarkupLayout.Row = (props: {\n  children: JSX.Element,\n  class?: string\n}) => {\n  const context = useContext(Context);\n  const [elements, setElements] = createSignal<JSX.Element[]>([]);\n  let ref: HTMLDivElement;\n  const value: RowContextValue = {\n    get isLast() {\n      return context.elements()[context.elements().length - 1] === ref;\n    },\n    elements\n  };\n\n  const resolvedChildren = children(() => (\n    <RowContext.Provider value={value}>\n      {props.children}\n    </RowContext.Provider>\n  ));\n\n  createEffect<void>(() => void setElements(resolvedChildren.toArray()));\n\n  return (\n    <div ref={ref} class={classNames('reply-markup-row', props.class)}>\n      {resolvedChildren()}\n    </div>\n  );\n};\n\nReplyMarkupLayout.Button = (props: {\n  onClick: (e: MouseEvent) => void,\n  children: JSX.Element,\n  class?: string,\n  textClass?: string,\n  icon?: Icon,\n  ref?: Ref<HTMLElement>,\n  as?: 'button' | 'a'\n}) => {\n  const rowContext = useContext(RowContext);\n  let ref: HTMLElement;\n  const isFirst = createMemo(() => rowContext.elements()[0] === ref);\n  const isLast = createMemo(() => rowContext.elements()[rowContext.elements().length - 1] === ref);\n  return (\n    <RippleElement\n      component={props.as || 'button'}\n      ref={(_ref: any) => {\n        ref = _ref;\n        (props.ref as any)?.(ref);\n      }}\n      class={classNames(\n        'reply-markup-button',\n        rowContext.isLast && isFirst() && 'is-first',\n        rowContext.isLast && isLast() && 'is-last',\n        props.class\n      )}\n      onClick={props.onClick}\n    >\n      <Show when={props.icon}>\n        <IconTsx icon={props.icon} class=\"reply-markup-button-icon\" />\n      </Show>\n      <span class={classNames('reply-markup-button-text', props.textClass)}>\n        {props.children}\n      </span>\n    </RippleElement>\n  );\n};\n\nReplyMarkupLayout.Inline = (props: {\n  rows: KeyboardButtonRow[],\n  chat?: Chat,\n  message?: Message.message,\n  wrapOptions?: WrapSomethingOptions\n}) => {\n  const rows = props.rows.filter((row) => row.buttons.length);\n\n  return (\n    <ReplyMarkupLayout>\n      <For each={rows}>\n        {(row) => (\n          <ReplyMarkupLayout.Row>\n            <For each={row.buttons}>\n              {(button) => {\n                return wrapKeyboardButton({\n                  button,\n                  chat: props.chat,\n                  message: props.message,\n                  wrapOptions: props.wrapOptions\n                });\n              }}\n            </For>\n          </ReplyMarkupLayout.Row>\n        )}\n      </For>\n    </ReplyMarkupLayout>\n  );\n};\n\nexport default ReplyMarkupLayout;\n\nexport function createInlineReplyMarkup(options: {\n  rows: KeyboardButtonRow[],\n  chat?: Chat,\n  message?: Message.message,\n  wrapOptions?: WrapSomethingOptions\n}): HTMLDivElement {\n  const container = document.createElement('div');\n  const dispose = render(() => (\n    <ReplyMarkupLayout.Inline\n      rows={options.rows}\n      chat={options.chat}\n      message={options.message}\n      wrapOptions={options.wrapOptions}\n    />\n  ), container);\n  options.wrapOptions.middleware.onDestroy(dispose);\n  return container.firstElementChild as HTMLDivElement || container as unknown as HTMLDivElement;\n}\n","import {Accessor, createMemo} from 'solid-js';\n\nexport const useMaxLengthError = (value: Accessor<string>, maxLength: Accessor<number>) => {\n  const threshold = () => Math.min(40, Math.round(maxLength() / 3));\n  const lengthLeft = () => maxLength() - value().length;\n  const shouldShowLengthLeft = createMemo(() => lengthLeft() < threshold());\n\n  return {\n    hasError: createMemo(() => value().length > maxLength()),\n    shouldShowLengthLeft,\n    lengthLeft\n  };\n};\n","import fieldSectionStyles from '@/scss/modulePartials/fieldSectionPanel.module.scss';\nimport styles from '@components/simpleFormField/styles.module.scss';\nimport {requestRAF} from '@helpers/solid/requestRAF';\nimport {useMaxLengthError} from '@helpers/solid/useMaxLengthError';\nimport classNames from '@helpers/string/classNames';\nimport {Accessor, batch, createContext, createEffect, createMemo, createSignal, JSX, onCleanup, onMount, ParentProps, Ref, Setter, Show, splitProps, useContext} from 'solid-js';\n\n\ntype SimpleFormFieldContextValue = {\n  input: Accessor<HTMLInputElement>;\n  setInput: Setter<HTMLInputElement>;\n  offsetElement: Accessor<HTMLElement>;\n  setOffsetElement: Setter<HTMLElement>;\n  value: Accessor<string>;\n  onChange: (value: string) => void;\n  forceFocused: Accessor<boolean>;\n  useSetForceFocused: () => (focused: boolean) => void;\n  forceError: Accessor<boolean>;\n  useSetForceError: () => (error: boolean) => void;\n};\n\nconst Context = createContext<SimpleFormFieldContextValue>();\n\nexport const useSimpleFormFieldContext = () => useContext(Context);\n\n\nconst SimpleFormField = (inProps: ParentProps<{\n  value?: string;\n  onChange?: (value: string) => void;\n\n  onClick?: JSX.EventHandler<HTMLDivElement, MouseEvent>;\n  isError?: boolean;\n  clickable?: boolean;\n  withEndButtonIcon?: boolean;\n  withStartButtonIcon?: boolean;\n  withMinHeight?: boolean;\n  solidBackground?: boolean;\n  hoverDisabled?: boolean;\n\n  isMarkupTooltipHost?: boolean;\n} & Omit<JSX.HTMLAttributes<HTMLDivElement>, 'onChange' | 'onClick'>>) => {\n  const [props, restProps] = splitProps(inProps, [\n    'value',\n    'onChange',\n    'isError',\n    'children',\n    'onClick',\n    'class',\n    'classList',\n    'clickable',\n    'withEndButtonIcon',\n    'withStartButtonIcon',\n    'withMinHeight',\n    'solidBackground',\n    'hoverDisabled',\n    'isMarkupTooltipHost'\n  ]);\n\n  const [input, setInput] = createSignal<HTMLInputElement>();\n  const [offsetElement, setOffsetElement] = createSignal<HTMLElement>();\n\n  const {value: forceFocused, useSetter: useSetForceFocused} = useForceState();\n  const {value: forceError, useSetter: useSetForceError} = useForceState();\n\n  const contextValue: SimpleFormFieldContextValue = {\n    input,\n    setInput,\n    offsetElement,\n    setOffsetElement,\n    value: () => props.value,\n    get onChange() {\n      return props.onChange;\n    },\n    forceFocused,\n    useSetForceFocused,\n    forceError,\n    useSetForceError\n  };\n\n  return (\n    <Context.Provider value={contextValue}>\n      <div\n        class={classNames(styles.Container, props.class)}\n        classList={{\n          [styles.error]: props.isError || forceError(),\n          [styles.clickable]: props.clickable,\n          [styles.withEndButtonIcon]: props.withEndButtonIcon,\n          [styles.withStartButtonIcon]: props.withStartButtonIcon,\n          [styles.fixedHeight]: !props.withMinHeight,\n          [styles.minHeight]: props.withMinHeight,\n          [styles.forceFocused]: forceFocused(),\n          [styles.solidBackground]: props.solidBackground,\n          [styles.hoverEnabled]: !props.hoverDisabled,\n          ...props.classList\n        }}\n        onClick={(...args) => {\n          contextValue.input()?.focus();\n          props.onClick?.(...args);\n        }}\n        data-markup-tooltip-host={props.isMarkupTooltipHost}\n        {...restProps}\n      >\n        <div class={styles.BorderThin} />\n        <div class={styles.BorderThick} />\n        {props.children}\n      </div>\n    </Context.Provider>\n  );\n};\n\nSimpleFormField.Input = (inProps: {\n  ref?: Ref<HTMLInputElement>;\n  forceFieldValue?: boolean;\n} & Omit<JSX.InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange' | 'onInput' | 'ref'>) => {\n  const [props, restProps] = splitProps(inProps, ['ref', 'class', 'forceFieldValue']);\n\n  const context = useSimpleFormFieldContext();\n\n  return (\n    <input\n      ref={(el) => batch(() => {\n        context.setInput(el);\n        context.setOffsetElement(el);\n        if(props.ref instanceof Function) props.ref(el);\n      })}\n      class={classNames(styles.Input, props.class)}\n      value={context.value()}\n      onInput={(e) => {\n        context.onChange(e.currentTarget.value)\n        if(props.forceFieldValue) context.input().value = context.value();\n      }}\n      {...restProps}\n    />\n  );\n};\n\nSimpleFormField.InputStub = (props: ParentProps<{\n  class?: string;\n}>) => {\n  const context = useSimpleFormFieldContext();\n\n  return (\n    <div\n      ref={context.setOffsetElement}\n      class={classNames(styles.InputStub, props.class)}\n    >\n      {props.children}\n    </div>\n  );\n};\n\nSimpleFormField.Label = (props: ParentProps<{\n  active?: boolean;\n  forceOffset?: number;\n  maxLength?: number;\n}>) => {\n  const context = useSimpleFormFieldContext();\n\n  const [offset, setOffset] = createSignal(0);\n  const [noTransition, setNoTransition] = createSignal(true);\n\n  onMount(() => {\n    if(props.forceOffset || !context.offsetElement()) return;\n    const parentElement = context.offsetElement().parentElement;\n    if(!parentElement) return;\n\n    const rect = parentElement.getBoundingClientRect();\n    const inputRect = context.offsetElement().getBoundingClientRect();\n    setOffset(inputRect.left - rect.left);\n  });\n\n  onMount(() => {\n    requestRAF(() => {\n      setNoTransition(false);\n    });\n  });\n\n  return (\n    <div\n      class={styles.Label}\n      classList={{\n        [styles.active]: props.active || !!context.value(),\n        [styles.noTransition]: noTransition()\n      }}\n      style={{\n        '--offset': `${props.forceOffset || offset()}px`\n      }}\n    >\n      {props.children}\n      <Show when={props.maxLength}>\n        <LabelMaxLength maxLength={props.maxLength} />\n      </Show>\n    </div>\n  );\n};\n\nconst LabelMaxLength = (props: { maxLength: number }) => {\n  const context = useSimpleFormFieldContext();\n\n  const {shouldShowLengthLeft, lengthLeft, hasError} = useMaxLengthError(context.value, () => props.maxLength);\n\n  const setForceError = context.useSetForceError();\n  createEffect(() => {\n    setForceError(hasError());\n  });\n\n  return (\n    <Show when={shouldShowLengthLeft()}>\n      {' '}({lengthLeft()})\n    </Show>\n  );\n};\n\ntype SideContentProps = JSX.HTMLAttributes<HTMLDivElement> & {\n  class?: string;\n  first?: boolean;\n  last?: boolean;\n  withFixedIcon?: boolean;\n};\n\nSimpleFormField.SideContent = (inProps: SideContentProps) => {\n  const [props, restProps] = splitProps(inProps, ['class', 'first', 'last', 'withFixedIcon', 'classList', 'children']);\n  return (\n    <div\n      class={classNames(styles.SideContent, props.class)}\n      classList={{\n        [styles.first]: props.first,\n        [styles.last]: props.last,\n        [styles.withFixedIcon]: props.withFixedIcon,\n        ...props.classList\n      }}\n      {...restProps}\n    >\n      {props.children}\n    </div>\n  );\n};\n\ntype WithLengthCounterProps = SideContentProps & {\n  showLengthLeft: boolean;\n  lengthLeft: number;\n};\n\nSimpleFormField.WithLengthCounter = (inProps: WithLengthCounterProps) => {\n  const [props, restProps] = splitProps(inProps, ['class', 'showLengthLeft', 'lengthLeft', 'children']);\n\n  return (\n    <SimpleFormField.SideContent\n      class={classNames(styles.withLimit, props.class)}\n      {...restProps}\n    >\n      {props.children}\n      <Show when={props.showLengthLeft}>\n        <div class={styles.lengthLeft}>\n          {props.lengthLeft}\n        </div>\n      </Show>\n    </SimpleFormField.SideContent>\n  );\n};\n\ntype WithAutoLengthCounterProps = SideContentProps & {\n  maxLength: number;\n};\n\nSimpleFormField.WithAutoLengthCounter = (inProps: WithAutoLengthCounterProps) => {\n  const [props, restProps] = splitProps(inProps, ['maxLength']);\n\n  const context = useSimpleFormFieldContext();\n\n  const {shouldShowLengthLeft, lengthLeft, hasError} = useMaxLengthError(context.value, () => props.maxLength);\n\n  const setForceError = context.useSetForceError();\n  createEffect(() => {\n    setForceError(hasError());\n  });\n\n  return (\n    <SimpleFormField.WithLengthCounter\n      showLengthLeft={shouldShowLengthLeft()}\n      lengthLeft={lengthLeft()}\n      {...restProps}\n    />\n  );\n};\n\nSimpleFormField.Section = (inProps: JSX.HTMLAttributes<HTMLDivElement>) => {\n  const [props, restProps] = splitProps(inProps, ['class']);\n\n  return (\n    <div class={classNames(fieldSectionStyles.fieldSectionPanel, props.class)} {...restProps} />\n  );\n};\n\nSimpleFormField.Caption = (inProps: JSX.HTMLAttributes<HTMLDivElement>) => {\n  const [props, restProps] = splitProps(inProps, ['class']);\n\n  return (\n    <div class={classNames(fieldSectionStyles.fieldSectionCaption, props.class)} {...restProps} />\n  );\n};\n\n/**\n * Aggregates a boolean state across multiple independent consumers.\n *\n * Each consumer obtains its own setter via `useSetter()`. The aggregated\n * `value` is `true` whenever at least one consumer has set its flag to `true`.\n * The setter is automatically reset on cleanup of the calling owner.\n */\nexport const useForceState = () => {\n  type ObjectRef = {};\n\n  const [refs, setRefs] = createSignal<ObjectRef[]>([]);\n\n  const value = createMemo(() => refs().length > 0);\n\n  const useSetter = () => {\n    const ref: ObjectRef = {};\n\n    const setter = (active: boolean) =>\n      setRefs(refs => {\n        const filtered = refs.filter((other) => other !== ref);\n        return active ? [...filtered, ref] : filtered;\n      });\n\n    onCleanup(() => {\n      setter(false);\n    });\n\n    return setter;\n  };\n\n  return {value, useSetter};\n};\n\nexport default SimpleFormField;\n","import noop from '@helpers/noop';\nimport {createMemo, createSignal} from 'solid-js';\n\n// ─── Types ────────────────────────────────────────────────────────────────────\n\nexport type MutationStatus = 'idle' | 'pending' | 'success' | 'error';\n\nexport interface MutationOptions<TData, TError, TVariables> {\n  /** Called before the mutation function fires. Useful for optimistic updates. */\n  onMutate?: (variables: TVariables) => void | Promise<void>;\n  /** Called when the mutation resolves successfully. */\n  onSuccess?: (data: TData, variables: TVariables) => void | Promise<void>;\n  /** Called when the mutation throws. */\n  onError?: (error: TError, variables: TVariables) => void | Promise<void>;\n  /** Always called after success or error. */\n  onSettled?: (\n    data: TData | undefined,\n    error: TError | undefined,\n    variables: TVariables\n  ) => void | Promise<void>;\n}\n\nexport interface MutationResult<TData, TError, TVariables> {\n  /** Fire-and-forget — errors are captured in state, not thrown. */\n  mutate: (variables: TVariables) => void;\n  /** Returns a promise — errors are both captured in state AND re-thrown. */\n  mutateAsync: (variables: TVariables) => Promise<TData>;\n  /** Resets all state back to idle. */\n  reset: () => void;\n\n  // — Reactive accessors —\n  data: () => TData | undefined;\n  error: () => TError | undefined;\n  status: () => MutationStatus;\n  isPending: () => boolean;\n  isSuccess: () => boolean;\n  isError: () => boolean;\n  isIdle: () => boolean;\n}\n\n// ─── Hook ─────────────────────────────────────────────────────────────────────\n\nexport function createMutation<TData, TError = Error, TVariables = void>(\n  mutationFn: (variables: TVariables) => Promise<TData>,\n  options: MutationOptions<TData, TError, TVariables> = {}\n): MutationResult<TData, TError, TVariables> {\n  const [status, setStatus] = createSignal<MutationStatus>('idle');\n  // Wrap in `() =>` setter form so SolidJS never treats a function-typed\n  // TData as a signal updater.\n  const [data, setData] = createSignal<TData | undefined>(undefined);\n  const [error, setError] = createSignal<TError | undefined>(undefined);\n\n  // Derived memos — reactive without extra function calls at the call site.\n  const isPending = createMemo(() => status() === 'pending');\n  const isSuccess = createMemo(() => status() === 'success');\n  const isError = createMemo(() => status() === 'error');\n  const isIdle = createMemo(() => status() === 'idle');\n\n  const reset = (): void => {\n    setStatus('idle');\n    setData(undefined);\n    setError(undefined);\n  };\n\n  const mutateAsync = async(variables: TVariables): Promise<TData> => {\n    setStatus('pending');\n    setData(undefined);\n    setError(undefined);\n\n    try {\n      await options.onMutate?.(variables);\n\n      const result = await mutationFn(variables);\n\n      setData(() => result); // `() =>` prevents functional-value pitfall\n      setStatus('success');\n\n      await options.onSuccess?.(result, variables);\n      await options.onSettled?.(result, undefined, variables);\n\n      return result;\n    } catch(err) {\n      const typedError = err as TError;\n\n      setError(() => typedError);\n      setStatus('error');\n\n      await options.onError?.(typedError, variables);\n      await options.onSettled?.(undefined, typedError, variables);\n\n      throw err; // re-throw so `mutateAsync` callers can handle it too\n    }\n  };\n\n  const mutate = (variables: TVariables): void => {\n    // Swallow the rejection — state already reflects it.\n    mutateAsync(variables).catch(noop);\n  };\n\n  return {\n    mutate,\n    mutateAsync,\n    reset,\n    data,\n    error,\n    status,\n    isPending,\n    isSuccess,\n    isError,\n    isIdle\n  };\n}\n","import styles from '@components/popups/createBot/createBot.module.scss';\nimport PopupElement from '@components/popups/indexTsx';\nimport SimpleFormField from '@components/simpleFormField';\nimport Space from '@components/space';\nimport {createMutation} from '@helpers/solid/createMutation';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {LangPackKey} from '@lib/langPack';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport {createComputed, createMemo, createSignal, on, onCleanup, Show} from 'solid-js';\n\n\nconst USERNAME_SUFFIX = 'bot';\nconst USERNAME_PREFIX = '@';\nconst MIN_USERNAME_LENGTH = 3;\nconst MAX_USERNAME_LENGTH = 29; // accounting for the trailing \"bot\" (32 total)\nconst MAX_BOT_NAME_LENGTH = 128;\nconst USERNAME_REGEX = /^[a-zA-Z][a-zA-Z0-9_]*$/;\n\ntype UsernameStatus =\n  | {state: 'idle'}\n  | {state: 'loading'}\n  | {state: 'available'}\n  | {state: 'error'}\n  | {state: 'taken'}\n  | {state: 'invalid'; reason: 'tooShort' | 'tooLong' | 'invalidChars' | 'mustStartLetter' | 'unknown'};\n\nexport type CreateBotPopupProps = {\n  requestingPeerId: PeerId\n  suggestedBotName?: string\n  suggestedUsername?: string\n  onCreate: (data: {name: string; username: string}) => MaybePromise<boolean>\n}\n\nconst CreateBotPopup = (props: CreateBotPopupProps) => {\n  const {PeerTitleTsx, AvatarNewTsx, rootScope} = useHotReloadGuard();\n\n  const [show, setShow] = createSignal(true);\n  const [botName, setBotName] = createSignal(props.suggestedBotName ?? '');\n  const [usernameValue, setUsernameValue] = createSignal(props.suggestedUsername ?? '');\n  const [usernameStatus, setUsernameStatus] = createSignal<UsernameStatus>({state: 'idle'});\n\n\n  const trimmedName = createMemo(() => botName().trim());\n  const nameError = createMemo(() => {\n    const name = trimmedName();\n    if(!name) return 'empty';\n    if(name.length > MAX_BOT_NAME_LENGTH) return 'tooLong';\n    return undefined;\n  });\n\n  const submitMutation = createMutation(async() => {\n    if(!isValid()) return false;\n    const ok = await props.onCreate({\n      name: trimmedName(),\n      username: fullUsername()\n    });\n    return ok;\n  })\n\n  function validateUsernameLocally(value: string): UsernameStatus | undefined {\n    if(!value) return {state: 'idle'};\n    if(!/^[a-zA-Z]/.test(value)) {\n      return {state: 'invalid', reason: 'mustStartLetter'};\n    }\n    if(!USERNAME_REGEX.test(value)) {\n      return {state: 'invalid', reason: 'invalidChars'};\n    }\n    if(value.length < MIN_USERNAME_LENGTH) {\n      return {state: 'invalid', reason: 'tooShort'};\n    }\n    if(value.length > MAX_USERNAME_LENGTH) {\n      return {state: 'invalid', reason: 'tooLong'};\n    }\n    return undefined;\n  }\n\n  // Constantly check username availability when it changes\n  createComputed(on(usernameValue, (value) => {\n    const localResult = validateUsernameLocally(value);\n    if(localResult) {\n      setUsernameStatus(localResult);\n      return;\n    }\n\n    setUsernameStatus({state: 'loading'});\n\n    let cancelled = false;\n\n    const timeout = self.setTimeout(async() => {\n      if(cancelled) return;\n\n      const fullUsername = value + USERNAME_SUFFIX;\n\n      const result = await rootScope.managers.appBotsManager.checkUsername(fullUsername);\n      if(cancelled) return;\n\n      if(usernameValue() !== value) return; // out-of-date result\n\n      if(result === 'invalid') {\n        setUsernameStatus({state: 'invalid', reason: 'unknown'});\n      } else {\n        setUsernameStatus({state: result});\n      }\n    }, 500);\n\n    onCleanup(() => {\n      cancelled = true;\n      self.clearTimeout(timeout);\n    });\n  }));\n\n  const fullUsername = createMemo(() => usernameValue() + USERNAME_SUFFIX);\n\n  const isValid = createMemo(() => {\n    return !nameError() && usernameStatus().state === 'available';\n  });\n\n  function handleUsernameChange(value: string) {\n    // Sanitize: lowercase, strip non-allowed chars, prevent typing the suffix manually\n    let cleaned = value.replace(/[^a-zA-Z0-9_]/g, '');\n    if(cleaned.length > MAX_USERNAME_LENGTH) {\n      cleaned = cleaned.slice(0, MAX_USERNAME_LENGTH);\n    }\n    setUsernameValue(cleaned);\n  }\n\n  const usernameStatusKey = createMemo((): LangPackKey => {\n    const s = usernameStatus();\n    switch(s.state) {\n      case 'idle': return 'CreateBot.Username.Caption';\n      case 'loading': return 'CreateBot.Username.Checking';\n      case 'available': return 'CreateBot.Username.Available';\n      case 'taken': return 'CreateBot.Username.Taken';\n      case 'invalid':\n        switch(s.reason) {\n          case 'tooShort': return 'CreateBot.Username.TooShort';\n          case 'tooLong': return 'CreateBot.Username.TooLong';\n          case 'mustStartLetter': return 'CreateBot.Username.MustStartLetter';\n          case 'invalidChars': return 'CreateBot.Username.InvalidChars';\n          case 'unknown': return 'CreateBot.Username.Invalid';\n        }\n        break;\n      case 'error': return 'CreateBot.Username.Error';\n    }\n  });\n\n  const usernameStatusClass = createMemo(() => {\n    const s = usernameStatus();\n    if(s.state === 'available') return styles.statusSuccess;\n    if(s.state === 'taken' || s.state === 'invalid') return styles.statusError;\n    if(s.state === 'loading') return styles.statusLoading;\n    return undefined;\n  });\n\n  return (\n    <PopupElement class={styles.popup} containerClass={styles.popupContainer} show={show()}>\n      <PopupElement.Header class={styles.popupHeader}>\n        <PopupElement.CloseButton class={styles.popupCloseButton} />\n      </PopupElement.Header>\n      <PopupElement.Body class={styles.popupBody}>\n        <div class={styles.header}>\n          <div class={styles.avatar}>\n            <AvatarNewTsx peerId={props.requestingPeerId} size={120} />\n          </div>\n\n          <I18nTsx class={styles.title} key=\"CreateBot.Title\" />\n\n          <div class={styles.subtitle}>\n            <I18nTsx\n              key=\"CreateBot.Description\"\n              args={[<PeerTitleTsx peerId={props.requestingPeerId} />]}\n            />\n          </div>\n        </div>\n\n        <div class={styles.section}>\n          <SimpleFormField\n            value={botName()}\n            onChange={setBotName}\n            isError={!!nameError() && botName().length > 0}\n          >\n            <SimpleFormField.Label>\n              <I18nTsx key=\"CreateBot.Name.Label\" />\n            </SimpleFormField.Label>\n            <SimpleFormField.Input\n              forceFieldValue\n              maxLength={MAX_BOT_NAME_LENGTH}\n            />\n          </SimpleFormField>\n        </div>\n\n        <div class={styles.caption}>\n          <I18nTsx key=\"CreateBot.Name.Caption\" />\n        </div>\n\n        <Space amount='1rem' />\n\n        <div class={styles.section}>\n          <SimpleFormField\n            class={styles.usernameField}\n            value={usernameValue()}\n            onChange={handleUsernameChange}\n            isError={usernameStatus().state === 'taken' || usernameStatus().state === 'invalid'}\n          >\n            <SimpleFormField.SideContent first last class={styles.usernameFieldHiddenPrefix}>\n              {USERNAME_PREFIX}\n            </SimpleFormField.SideContent>\n            <SimpleFormField.Label active>\n              <I18nTsx key=\"CreateBot.Username.Label\" />\n            </SimpleFormField.Label>\n            <SimpleFormField.Input\n              forceFieldValue\n              class={styles.usernameInput}\n              autocapitalize=\"off\"\n              autocomplete=\"off\"\n              spellcheck={false}\n            />\n            <div class={styles.usernameOverlay}>\n              <span class={styles.usernameOverlayPrefix}>{USERNAME_PREFIX}</span>\n              <span class={styles.usernameOverlayValue}>{usernameValue()}</span>\n              <span class={styles.usernameOverlaySuffix}>{USERNAME_SUFFIX}</span>\n            </div>\n          </SimpleFormField>\n        </div>\n\n        <div class={styles.caption}>\n          <Show\n            when={usernameStatus().state === 'available'}\n            fallback={\n              <Show when={usernameStatusKey()}>\n                <span class={usernameStatusClass()}>\n                  <I18nTsx key={usernameStatusKey()} />\n                </span>\n              </Show>\n            }\n          >\n            <I18nTsx\n              key=\"CreateBot.Link\"\n              args={[\n                <span class={styles.linkInfoLink}>\n                  t.me/{fullUsername()}\n                </span>\n              ]}\n            />\n          </Show>\n        </div>\n      </PopupElement.Body>\n      <PopupElement.Footer class={styles.popupFooter}>\n        <PopupElement.FooterButton\n          color='secondary'\n          langKey=\"Cancel\"\n          callback={() => {\n            setShow(false);\n            return true;\n          }}\n        />\n        <PopupElement.FooterButton\n          disabled={!isValid() || submitMutation.isPending()}\n          langKey=\"CreateBot.Create\"\n          callback={() => submitMutation.mutateAsync()}\n        />\n      </PopupElement.Footer>\n    </PopupElement>\n  );\n};\n\nexport default CreateBotPopup;\n","import {createPopup} from '@components/popups/indexTsx';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\nimport CreateBotPopup, {CreateBotPopupProps} from '@components/popups/createBot/CreateBotPopup';\n\nexport default function showCreateBotPopup(props: CreateBotPopupProps & {\n  HotReloadGuard: typeof SolidJSHotReloadGuardProvider\n}) {\n  const {HotReloadGuard, ...rest} = props;\n  createPopup(() => (\n    <HotReloadGuard>\n      <CreateBotPopup {...rest} />\n    </HotReloadGuard>\n  ));\n}\n","import {copyTextToClipboard} from '@helpers/clipboard';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport htmlToDocumentFragment from '@helpers/dom/htmlToDocumentFragment';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {KeyboardButton, Message, ReplyMarkup, InlineQueryPeerType} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport rootScope from '@lib/rootScope';\nimport Chat from '@components/chat/chat';\nimport {showPickUser3Popup} from '@components/popups/pickUser';\nimport selectRequestPeers from '@components/popups/requestPeer';\nimport {toast, toastNew} from '@components/toast';\nimport wrapCustomEmoji from '@components/wrappers/customEmoji';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport ReplyMarkupLayout from '@components/chat/bubbleParts/replyMarkupLayout';\nimport classNames from '@helpers/string/classNames';\nimport showCreateBotPopup from '@components/popups/createBot';\nimport confirmationPopup from '@components/confirmationPopup';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {wrapFormattedDuration} from './wrapDuration';\nimport formatDuration from '@helpers/formatDuration';\n\nexport type KeyboardButtonHandler = {\n  text: DocumentFragment | HTMLElement,\n  onClick?: (e: Event) => void,\n  icon?: Icon,\n  as: 'button' | 'a',\n  classNames: string[],\n  refCallbacks: ((ref: HTMLElement) => void)[],\n  bg?: 'success' | 'danger' | 'primary'\n};\n\nexport function getKeyboardButtonHandler({\n  button,\n  chat,\n  message,\n  replyMarkup,\n  wrapOptions,\n  className\n}: {\n  button: KeyboardButton,\n  chat: Chat,\n  message?: Message.message,\n  replyMarkup?: ReplyMarkup,\n  wrapOptions?: WrapSomethingOptions,\n  className?: string\n}): KeyboardButtonHandler | undefined {\n  let text: DocumentFragment | HTMLElement = wrapRichText(button.text, {noLinks: true, noLinebreaks: true});\n  let buttonEl: HTMLElement;\n  let icon: Icon;\n  let onClick: (e: Event) => void;\n  let as: 'button' | 'a' = 'button';\n  const refCallbacks: ((ref: HTMLElement) => void)[] = [(ref) => {\n    buttonEl = ref;\n  }];\n  const classNamesArr: string[] = [className].filter(Boolean);\n\n  const {peerId} = chat;\n  const messageMedia = message?.media;\n  const messageMid = (replyMarkup as ReplyMarkup.replyKeyboardMarkup)?.mid || message?.mid;\n  const botId = (replyMarkup as ReplyMarkup.replyKeyboardMarkup)?.fromId || message?.viaBotId || message?.fromId;\n\n  switch(button._) {\n    case 'keyboardButtonUrl': {\n      const r = wrapRichText(' ', {\n        entities: [{\n          _: 'messageEntityTextUrl',\n          length: 1,\n          offset: 0,\n          url: button.url\n        }]\n      });\n\n      const anchor = htmlToDocumentFragment(r).firstElementChild as HTMLAnchorElement;\n      as = 'a';\n      classNamesArr.push('is-link', anchor.className);\n      icon = 'arrow_next';\n\n      refCallbacks.push((ref) => {\n        anchor.getAttributeNames().forEach((name) => {\n          if(name !== 'class') {\n            ref.setAttribute(name, anchor.getAttribute(name));\n          }\n        });\n      });\n\n      break;\n    }\n\n    case 'keyboardButtonSwitchInline': {\n      classNamesArr.push('is-switch-inline');\n      icon = 'forward_filled';\n      onClick = (e) => {\n        cancelEvent(e);\n\n        let promise: Promise<PeerId>;\n        if(button.pFlags.same_peer) promise = Promise.resolve(peerId);\n        else promise = rootScope.managers.appInlineBotsManager.checkSwitchReturn(botId).then((peerId) => {\n          if(peerId) {\n            return peerId;\n          }\n\n          let types: TelegramChoosePeerType[];\n          if(button.peer_types) {\n            const map: {[type in InlineQueryPeerType['_']]?: TelegramChoosePeerType} = {\n              inlineQueryPeerTypePM: 'users',\n              inlineQueryPeerTypeBotPM: 'bots',\n              inlineQueryPeerTypeBroadcast: 'channels',\n              inlineQueryPeerTypeChat: 'groups',\n              inlineQueryPeerTypeMegagroup: 'groups'\n            };\n\n            types = button.peer_types.map((type) => map[type._]);\n          }\n\n          return showPickUser3Popup(types, ['send_inline']);\n        });\n\n        promise.then(async(chosenPeerId) => {\n          const threadId = peerId === chosenPeerId ? chat.threadId : undefined;\n          await chat.appImManager.setInnerPeer({peerId: chosenPeerId, threadId});\n          rootScope.managers.appInlineBotsManager.switchInlineQuery(chosenPeerId, threadId, botId, button.query);\n        });\n      };\n      break;\n    }\n\n    case 'keyboardButtonBuy': {\n      const mediaInvoice = messageMedia._ === 'messageMediaInvoice' ? messageMedia : undefined;\n      if(mediaInvoice?.extended_media) {\n        return;\n      }\n\n      classNamesArr.push('is-buy');\n      icon = 'card';\n\n      if(mediaInvoice?.receipt_msg_id) {\n        text = i18n('Message.ReplyActionButtonShowReceipt');\n        classNamesArr.push('is-receipt');\n      }\n\n      break;\n    }\n\n    case 'keyboardButtonUrlAuth': {\n      classNamesArr.push('is-url-auth');\n\n      const {url, button_id} = button;\n\n      onClick = () => {\n        const toggle = toggleDisability([buttonEl], true);\n        chat.appImManager.handleUrlAuth({\n          peerId,\n          mid: messageMid,\n          url,\n          buttonId: button_id\n        }).then(() => {\n          toggle();\n        });\n      };\n      break;\n    }\n\n    case 'keyboardButtonSimpleWebView':\n    case 'keyboardButtonWebView': {\n      classNamesArr.push('is-web-view');\n      icon = 'webview';\n\n      onClick = () => {\n        const toggle = toggleDisability([buttonEl], true);\n        chat.openWebApp({\n          botId,\n          url: button.url,\n          isSimpleWebView: button._ === 'keyboardButtonSimpleWebView',\n          buttonText: button.text\n        }).finally(() => {\n          toggle();\n        });\n      };\n      break;\n    }\n\n    case 'keyboardButtonRequestPhone': {\n      classNamesArr.push('is-request-phone');\n\n      onClick = () => {\n        chat.appImManager.requestPhone(peerId);\n      };\n      break;\n    }\n\n    case 'keyboardButtonCallback': {\n      onClick = () => {\n        rootScope.managers.appInlineBotsManager.callbackButtonClick(peerId, messageMid, button)\n        .then((callbackAnswer) => {\n          if(typeof callbackAnswer.message === 'string' && callbackAnswer.message.length) {\n            if(callbackAnswer.pFlags.alert) {\n              confirmationPopup({\n                description: wrapRichText(callbackAnswer.message, {noLinks: true}),\n                button: {langKey: 'OK', isCancel: true}\n              }).catch(() => {});\n            } else {\n              toast(wrapRichText(callbackAnswer.message, {noLinks: true, noLinebreaks: true}));\n            }\n          } else if(typeof callbackAnswer.url === 'string' && callbackAnswer.url.length) {\n            chat.appImManager.openUrl(callbackAnswer.url, true);\n          }\n        });\n      };\n\n      break;\n    }\n\n    case 'keyboardButtonGame': {\n      classNamesArr.push('is-game');\n      icon = 'play';\n\n      onClick = () => {\n        if(!message) return;\n        // Inline-sent game messages are not re-rendered after the server confirms.\n        // The bubble's data-mid is patched in place — re-read it so we use the\n        // server mid instead of the captured temp one.\n        const bubble = findUpClassName(buttonEl, 'bubble');\n        const currentMid = bubble && +bubble.dataset.mid;\n        const target = (currentMid && currentMid !== message.mid ?\n          chat.getMessageByPeer(message.peerId, currentMid) as Message.message :\n          undefined) || message;\n        chat.appImManager.playGame(target);\n      };\n\n      break;\n    }\n\n    case 'keyboardButtonRequestPeer': {\n      onClick = async() => {\n        const peerType = button.peer_type;\n\n        if(peerType._ === 'requestPeerTypeCreateBot') {\n          showCreateBotPopup({\n            requestingPeerId: peerId,\n            suggestedBotName: peerType.suggested_name,\n            suggestedUsername: peerType.suggested_username,\n            onCreate: async({name, username}) => {\n              try {\n                const createBotResult = await rootScope.managers.appBotsManager.createManagedBot({\n                  managerId: peerId,\n                  botName: name,\n                  username: username\n                });\n\n                if(createBotResult.status === 'wait') {\n                  toastNew({\n                    langPackKey: 'CreateBot.TooManyBotsCreated',\n                    langPackArguments: [wrapFormattedDuration(formatDuration(createBotResult.waitTime))]\n                  });\n                  return true; // Close it, wait time is long\n                }\n\n                if(createBotResult.status === 'error') {\n                  toastNew({\n                    langPackKey: 'CreateBot.FailedToCreate',\n                    langPackArguments: []\n                  });\n                  return false;\n                }\n\n                const user = createBotResult.user;\n\n                await rootScope.managers.appMessagesManager.sendBotRequestedPeer(\n                  peerId,\n                  button.button_id,\n                  [user.id.toPeerId()],\n                  {mid: messageMid}\n                );\n\n                return true;\n              } catch{\n                return false;\n              }\n            },\n            HotReloadGuard: SolidJSHotReloadGuardProvider\n          });\n          return;\n        }\n\n        let requestedPeerIds: PeerId[];\n        try {\n          requestedPeerIds = await selectRequestPeers({button, requestingPeerId: peerId});\n        } catch{\n          return;\n        }\n\n        rootScope.managers.appMessagesManager.sendBotRequestedPeer(\n          peerId,\n          button.button_id,\n          requestedPeerIds,\n          {mid: messageMid}\n        ).catch((err: ApiError) => {\n          if(err.type === 'CHAT_ADMIN_INVITE_REQUIRED') {\n            toastNew({\n              langPackKey: peerType._ === 'requestPeerTypeBroadcast' ? 'Error.RequestPeer.NoRights.Channel' : 'Error.RequestPeer.NoRights.Group'\n            });\n          }\n        });\n      };\n\n      break;\n    }\n\n    case 'keyboardButtonCopy': {\n      icon = 'copy';\n\n      onClick = () => {\n        copyTextToClipboard(button.copy_text);\n        toastNew({langPackKey: 'TextCopied'});\n      };\n      break;\n    }\n\n    default: {\n      if(!message) {\n        onClick = () => {\n          rootScope.managers.appMessagesManager.sendText({peerId, text: button.text});\n        };\n      }\n\n      break;\n    }\n  }\n\n  let bg: 'success' | 'danger' | 'primary';\n  if(button.style) {\n    if(button.style.pFlags.bg_success) bg = 'success';\n    else if(button.style.pFlags.bg_danger) bg = 'danger';\n    else if(button.style.pFlags.bg_primary) bg = 'primary';\n\n    if(bg) {\n      classNamesArr.push(\n        'reply-markup-button-bg',\n        `reply-markup-button-bg-${bg}`\n      );\n    }\n  }\n\n  if(button.style?.icon) {\n    let customEmojiSize = wrapOptions?.customEmojiSize;\n    if(customEmojiSize) {\n      customEmojiSize = makeMediaSize(\n        customEmojiSize.width - 2,\n        customEmojiSize.height - 2\n      );\n    }\n\n    text.prepend(\n      wrapCustomEmoji({\n        docIds: [button.style.icon],\n        ...wrapOptions,\n        textColor: bg ? 'white' : wrapOptions.textColor,\n        customEmojiSize\n      }),\n      ' '\n    );\n  }\n\n  return {\n    text,\n    onClick,\n    icon,\n    as,\n    classNames: classNamesArr,\n    refCallbacks,\n    bg\n  };\n}\n\nexport default function wrapKeyboardButton(options: {\n  button: KeyboardButton,\n  chat: Chat,\n  message?: Message.message,\n  replyMarkup?: ReplyMarkup,\n  wrapOptions?: WrapSomethingOptions,\n  onClick?: () => void,\n  className?: string\n}) {\n  const handler = getKeyboardButtonHandler(options);\n  if(!handler) return;\n\n  const {onClick: _onClick} = options;\n  return ReplyMarkupLayout.Button({\n    children: handler.text,\n    class: classNames(...handler.classNames),\n    onClick: _onClick ? (e) => (_onClick(), handler.onClick(e)) : handler.onClick,\n    icon: handler.icon,\n    ref: (ref) => {\n      handler.refCallbacks.forEach((cb) => cb(ref));\n    },\n    as: handler.as\n  });\n}\n","import type ChatInput from '@components/chat/input';\nimport DropdownHover from '@helpers/dropdownHover';\nimport {ReplyMarkup} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport ListenerSetter, {Listener} from '@helpers/listenerSetter';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport Scrollable from '@components/scrollable';\nimport wrapKeyboardButton from '@components/wrappers/keyboardButton';\nimport classNames from '@helpers/string/classNames';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport {createRoot, For, onCleanup} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport ReplyMarkupLayout from '@components/chat/bubbleParts/replyMarkupLayout';\n\nexport default class ReplyKeyboard extends DropdownHover {\n  private static BASE_CLASS = 'reply-keyboard';\n  private appendTo: HTMLElement;\n  private listenerSetter: ListenerSetter;\n  private managers: AppManagers;\n  private btnHover: HTMLElement;\n  private peerId: PeerId;\n  private touchListener: Listener;\n  private chatInput: ChatInput;\n  private scrollable: Scrollable;\n  private middlewareHelper: MiddlewareHelper;\n\n  constructor(options: {\n    listenerSetter: ListenerSetter,\n    managers: AppManagers,\n    appendTo: HTMLElement,\n    btnHover: HTMLElement,\n    chatInput: ChatInput,\n    middleware: Middleware\n  }) {\n    super({\n      element: document.createElement('div')\n    });\n\n    safeAssign(this, options);\n\n    this.element.classList.add(ReplyKeyboard.BASE_CLASS);\n    this.element.style.display = 'none';\n\n    this.scrollable = new Scrollable();\n    this.middlewareHelper = options.middleware.create();\n    this.element.append(this.scrollable.container);\n\n    this.attachButtonListener(this.btnHover, this.listenerSetter);\n    this.listenerSetter.add(rootScope)('history_reply_markup', async({peerId}) => {\n      if(this.peerId === peerId) {\n        if(this.checkAvailability() && this.isActive()) {\n          await this.render();\n        }\n\n        getHeavyAnimationPromise().then(() => {\n          this.checkForceReply();\n        });\n      }\n    });\n  }\n\n  public init() {\n    this.appendTo.append(this.element);\n\n    this.listenerSetter.add(this)('open', async() => {\n      await this.render();\n\n      if(IS_TOUCH_SUPPORTED) {\n        this.touchListener = this.listenerSetter.add(document.body)('touchstart', this.onBodyTouchStart, {passive: false, capture: true}) as any as Listener;\n        this.listenerSetter.add(this)('close', () => {\n          this.listenerSetter.remove(this.touchListener);\n        }, {once: true});\n      }\n    });\n\n    return super.init();\n  }\n\n  private onBodyTouchStart = (e: TouchEvent) => {\n    const target = e.touches[0].target as HTMLElement;\n    if(!findUpAsChild(target, this.element) && target !== this.btnHover) {\n      cancelEvent(e);\n      this.toggle(false);\n    }\n  };\n\n  public async checkForceReply() {\n    const replyMarkup = await this.getReplyMarkup();\n    if(replyMarkup._ === 'replyKeyboardForceReply' &&\n      !replyMarkup.pFlags.hidden &&\n      !replyMarkup.pFlags.used) {\n      replyMarkup.pFlags.used = true;\n      this.chatInput.initMessageReply({replyToMsgId: replyMarkup.mid});\n    }\n  }\n\n  private async getReplyMarkup(): Promise<ReplyMarkup> {\n    return this.chatInput.chat.historyStorageNoThreadId.replyMarkup ?? {\n      _: 'replyKeyboardHide',\n      pFlags: {}\n    };\n  }\n\n  public async render(replyMarkup?: ReplyMarkup.replyKeyboardMarkup) {\n    if(replyMarkup === undefined) {\n      replyMarkup = await this.getReplyMarkup() as any;\n    }\n\n    this.scrollable.replaceChildren();\n    this.middlewareHelper.clean();\n\n    const dispose = render(() => (\n      <ReplyMarkupLayout>\n        <For each={replyMarkup.rows}>\n          {(row) => (\n            <ReplyMarkupLayout.Row class={ReplyKeyboard.BASE_CLASS + '-row'}>\n              <For each={row.buttons}>\n                {(button) => (\n                  wrapKeyboardButton({\n                    button,\n                    chat: this.chatInput.chat,\n                    replyMarkup,\n                    wrapOptions: {\n                      textColor: 'primary-color'\n                    },\n                    onClick: () => {\n                      this.toggle(false);\n                    },\n                    className: classNames(ReplyKeyboard.BASE_CLASS + '-button', 'btn')\n                  })\n                )}\n              </For>\n            </ReplyMarkupLayout.Row>\n          )}\n        </For>\n      </ReplyMarkupLayout>\n    ), this.scrollable.container);\n    this.middlewareHelper.get().onDestroy(dispose);\n  }\n\n  public async checkAvailability(replyMarkup?: ReplyMarkup) {\n    if(replyMarkup === undefined) {\n      replyMarkup = await this.getReplyMarkup();\n    }\n\n    const hide = replyMarkup._ === 'replyKeyboardHide' || !(replyMarkup as ReplyMarkup.replyInlineMarkup).rows?.length;\n    this.btnHover.classList.toggle('hide', hide);\n\n    if(hide) {\n      this.toggle(false);\n    }\n\n    return !hide;\n  }\n\n  public setPeer(peerId: PeerId) {\n    this.peerId = peerId;\n\n    this.checkAvailability();\n    this.checkForceReply();\n  }\n}\n","import findAndSpliceAll from '@helpers/array/findAndSpliceAll';\nimport LazyLoadQueueIntersector, {LazyLoadElement} from '@components/lazyLoadQueueIntersector';\nimport VisibilityIntersector, {OnVisibilityChange} from '@components/visibilityIntersector';\n\nexport default class LazyLoadQueueRepeat2 extends LazyLoadQueueIntersector {\n  constructor(parallelLimit?: number, protected onVisibilityChange?: OnVisibilityChange) {\n    super(parallelLimit);\n\n    this.intersector = new VisibilityIntersector((item) => {\n      const {target, visible} = item;\n      const spliced = findAndSpliceAll(this.queue, (i) => i.div === target);\n      if(visible && spliced.length) {\n        spliced.forEach((item) => {\n          this.queue.unshift(item);\n        });\n      }\n\n      this.onVisibilityChange && this.onVisibilityChange(item);\n      this.setProcessQueueTimeout();\n    });\n  }\n\n  public observe(el: LazyLoadElement) {\n    super.observe(el);\n  }\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport Scrollable from '@components/scrollable';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport LazyLoadQueueRepeat2 from '@components/lazyLoadQueueRepeat2';\nimport wrapVideo from '@components/wrappers/video';\nimport noop from '@helpers/noop';\nimport {MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\n\nexport default class GifsMasonry {\n  public lazyLoadQueue: LazyLoadQueueRepeat2;\n  private scrollPromise: CancellablePromise<void> = Promise.resolve();\n  private timeout: number = 0;\n  private managers: AppManagers;\n  private middlewareHelper: MiddlewareHelper;\n  private map: Map<DocId, HTMLElement>;\n\n  constructor(\n    private element: HTMLElement,\n    private group: AnimationItemGroup,\n    private scrollable: Scrollable,\n    attach = true\n  ) {\n    this.managers = rootScope.managers;\n    this.middlewareHelper = getMiddleware();\n    this.map = new Map();\n\n    this.lazyLoadQueue = new LazyLoadQueueRepeat2(undefined, ({target, visible}) => {\n      if(visible) {\n        this.processVisibleDiv(target);\n      } else {\n        this.processInvisibleDiv(target);\n      }\n    });\n\n    if(attach) {\n      this.attach();\n    }\n  }\n\n  private onScroll = () => {\n    if(this.timeout) {\n      clearTimeout(this.timeout);\n    } else {\n      this.scrollPromise = deferredPromise<void>();\n      // animationIntersector.checkAnimations(true, group);\n    }\n\n    this.timeout = window.setTimeout(() => {\n      this.timeout = 0;\n      this.scrollPromise.resolve();\n      // animationIntersector.checkAnimations(false, group);\n    }, 150);\n  };\n\n  public attach() {\n    this.scrollable.container.addEventListener('scroll', this.onScroll);\n  }\n\n  public detach() {\n    this.clear();\n    this.scrollable.container.removeEventListener('scroll', this.onScroll);\n    this.middlewareHelper.destroy();\n  }\n\n  public clear() {\n    this.lazyLoadQueue.clear();\n  }\n\n  private processVisibleDiv(div: HTMLElement) {\n    const video = div.querySelector('video');\n    if(video) {\n      return;\n    }\n\n    const load = () => {\n      const docId = div.dataset.docId;\n      const promise = Promise.all([this.managers.appDocsManager.getDoc(docId), this.scrollPromise]).then(async([doc]) => {\n        if(!this.lazyLoadQueue.intersector.isVisible(div)) {\n          this.processInvisibleDiv(div);\n          return;\n        }\n\n        div.middlewareHelper.clean();\n        const middleware = div.middlewareHelper.get().create().get();\n        const res = await wrapVideo({\n          doc,\n          container: div as HTMLDivElement,\n          lazyLoadQueue: null,\n          // lazyLoadQueue: EmoticonsDropdown.lazyLoadQueue,\n          group: this.group,\n          noInfo: true,\n          noPreview: true,\n          middleware\n        });\n\n        const promise = res.loadPromise;\n        promise.finally(() => {\n          middleware.onDestroy(() => {\n            res.video?.remove();\n          });\n\n          if(!middleware() || !this.lazyLoadQueue.intersector.isVisible(div)) {\n            this.processInvisibleDiv(div);\n            return;\n          }\n\n          const thumb = div.querySelector('img, canvas');\n          thumb && thumb.classList.add('hide');\n        });\n\n        return promise;\n      });\n\n      return promise;\n    };\n\n    // return load();\n\n    this.lazyLoadQueue.push({div, load});\n  }\n\n  public processInvisibleDiv = (div: HTMLElement) => {\n    return this.scrollPromise.then(async() => {\n      // return;\n\n      if(this.lazyLoadQueue.intersector.isVisible(div)) {\n        return;\n      }\n\n      const thumb = div.querySelector('img, canvas');\n\n      if(thumb) {\n        thumb.classList.remove('hide');\n        await doubleRaf();\n      }\n\n      if(this.lazyLoadQueue.intersector.isVisible(div)) {\n        return;\n      }\n\n      div.middlewareHelper.clean();\n    });\n  };\n\n  public addBatch(docs: MyDocument[]) {\n    docs.forEach((doc) => this.add(doc));\n  }\n\n  public update(docs: MyDocument[]) {\n    for(const [docId] of this.map) {\n      if(!docs.some((doc) => doc.id === docId)) {\n        this.delete(docId);\n      }\n    }\n\n    this.addBatch(docs);\n    for(let i = 0, length = docs.length; i < length; ++i) {\n      const element = this.map.get(docs[i].id);\n      positionElementByIndex(element, this.element, i);\n    }\n  }\n\n  public add(doc: MyDocument, appendTo = this.element) {\n    if(this.map.has(doc.id)) {\n      return;\n    }\n\n    const div = document.createElement('div');\n    div.classList.add('gif', 'grid-item'/* , 'fade-in-transition' */);\n    // div.style.opacity = '0';\n    div.dataset.docId = '' + doc.id;\n    div.middlewareHelper = this.middlewareHelper.get().create();\n    this.map.set(doc.id, div);\n\n    appendTo.append(div);\n\n    this.lazyLoadQueue.observe({div, load: noop as any});\n\n    // let preloader = new ProgressivePreloader(div);\n\n    wrapVideo({\n      doc,\n      container: div as HTMLDivElement,\n      lazyLoadQueue: null,\n      noInfo: true,\n      onlyPreview: true,\n      middleware: div.middlewareHelper.get()\n    });\n  }\n\n  public delete(docId: DocId) {\n    const div = this.map.get(docId);\n    if(div) {\n      div.remove();\n      div.middlewareHelper.destroy();\n      this.map.delete(docId);\n    }\n  }\n}\n","import type Chat from '@components/chat/chat';\nimport debounce from '@helpers/schedulers/debounce';\nimport {WebDocument} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport Scrollable from '@components/scrollable';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport Button from '@components/button';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport assumeType from '@helpers/assumeType';\nimport GifsMasonry from '@components/gifsMasonry';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport mediaSizes from '@helpers/mediaSizes';\nimport readBlobAsDataURL from '@helpers/blob/readBlobAsDataURL';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport renderMediaWithFadeIn from '@helpers/dom/renderMediaWithFadeIn';\nimport {AppManagers} from '@lib/managers';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport generateQId from '@appManagers/utils/inlineBots/generateQId';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport {AnimationItemGroup} from '@components/animationIntersector';\nimport wrapPhoto from '@components/wrappers/photo';\nimport {i18n} from '@lib/langPack';\nimport {POSTING_NOT_ALLOWED_MAP} from '@components/chat/input';\nimport liteMode from '@helpers/liteMode';\n\nconst ANIMATION_GROUP: AnimationItemGroup = 'INLINE-HELPER';\n// const GRID_ITEMS = 5;\n\nexport default class InlineHelper extends AutocompleteHelper {\n  private scrollable: Scrollable;\n  private lazyLoadQueue: LazyLoadQueue;\n  private gifsMasonry: GifsMasonry;\n  private superStickerRenderer: SuperStickerRenderer;\n  private onChangeScreen: () => void;\n  public checkQuery: ReturnType<typeof debounce<InlineHelper['_checkQuery']>>;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    private chat: Chat,\n    private managers: AppManagers\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'xy',\n      waitForKey: ['ArrowUp', 'ArrowDown'],\n      onSelect: (target) => {\n        if(!target) return false; // can happen when there is only button\n        const {peerId, botId, queryId} = this.list.dataset;\n        return this.chat.input.getReadyToSend(() => {\n          const queryAndResultIds = generateQId(queryId, (target as HTMLElement).dataset.resultId);\n          this.managers.appInlineBotsManager.sendInlineResult(peerId.toPeerId(), botId, queryAndResultIds, {\n            ...this.chat.getMessageSendingParams(),\n            clearDraft: true\n          });\n\n          this.chat.input.onMessageSent(true, true);\n        });\n      }\n    });\n\n    this.container.classList.add('inline-helper');\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n    });\n\n    this.checkQuery = debounce(this._checkQuery, 200, true, true);\n\n    this.addEventListener('hidden', () => {\n      if(this.onChangeScreen) {\n        mediaSizes.removeEventListener('changeScreen', this.onChangeScreen);\n        this.onChangeScreen = undefined;\n      }\n    });\n  }\n\n  public _checkQuery = async(peerId: PeerId, username: string, query: string, canSendInline: boolean, allowGuestChat?: boolean) => {\n    const middleware = this.controller.getMiddleware();\n\n    const peer = await this.managers.appUsersManager.resolveUsername(username);\n    if(!middleware()) {\n      throw 'PEER_CHANGED';\n    }\n\n    if(peer._ !== 'user' || !peer.pFlags.bot) {\n      throw 'NOT_A_BOT';\n    }\n\n    // * a guest bot (bot_guestchat) is not an inline bot — a leading @guestbot is a plain, sendable\n    // * guest-chat message, so hide the inline panel and let the composer send the text as-is\n    if(allowGuestChat && peer.pFlags.bot_guestchat) {\n      this.toggle(false);\n      return {user: peer, renderPromise: Promise.resolve(), guestChat: true};\n    }\n\n    if(!canSendInline) {\n      if(!middleware()) {\n        throw 'PEER_CHANGED';\n      }\n\n      if(this.init) {\n        this.init();\n        this.init = null;\n      }\n\n      this.container.classList.add('cant-send');\n      this.toggle(false);\n      throw 'NO_INLINES';\n    }\n\n    const botId = peer.id;\n\n    const renderPromise = this.managers.appInlineBotsManager.getInlineResults(peerId, botId, query).then((botResults) => {\n      if(!middleware()) {\n        throw 'PEER_CHANGED';\n      }\n\n      if(this.init) {\n        this.init();\n        this.init = null;\n      }\n\n      const list = this.list.cloneNode() as HTMLElement;\n      list.dataset.peerId = '' + peerId;\n      list.dataset.botId = '' + botId;\n      list.dataset.queryId = '' + botResults.query_id;\n\n      const gifsMasonry = new GifsMasonry(null, ANIMATION_GROUP, this.scrollable, false);\n\n      this.lazyLoadQueue.clear();\n      this.superStickerRenderer.clear();\n\n      const loadPromises: Promise<any>[] = [];\n      const isGallery = !!botResults.pFlags.gallery;\n      // botResults.results.length = 3;\n      for(const item of botResults.results) {\n        const container = document.createElement('div');\n        container.classList.add('inline-helper-result');\n        container.dataset.resultId = item.id;\n\n        const preview = isGallery ? undefined : document.createElement('div');\n        if(preview) {\n          preview.classList.add('inline-helper-result-preview');\n\n          container.append(preview);\n        }\n\n        list.append(container);\n\n        if(!isGallery) {\n          preview.classList.add('empty');\n          setInnerHTML(preview, wrapEmojiText([...item.title.trim()][0]));\n\n          const title = document.createElement('div');\n          title.classList.add('inline-helper-result-title');\n          setInnerHTML(title, wrapEmojiText(item.title));\n\n          const description = document.createElement('div');\n          description.classList.add('inline-helper-result-description');\n          setInnerHTML(description, wrapRichText(item.description, {\n            noCommands: true,\n            noLinks: true\n          }));\n\n          container.append(title, description);\n\n          const separator = document.createElement('div');\n          separator.classList.add('inline-helper-separator');\n\n          list.append(separator);\n        } else {\n          container.classList.add('grid-item');\n        }\n\n        if(item._ === 'botInlineResult') {\n          // (preview || container).style.backgroundColor = '#ff00ff';\n          if(item.thumb && item.thumb.mime_type.indexOf('image/') === 0) {\n            let mediaContainer: HTMLElement;\n            if(preview) {\n              mediaContainer = document.createElement('div');\n              preview.append(mediaContainer);\n            } else {\n              mediaContainer = container;\n            }\n\n            mediaContainer.classList.add('media-container');\n            isGallery && mediaContainer.classList.add('no-border-radius');\n\n            this.lazyLoadQueue.push({\n              div: container,\n              load: () => {\n                return appDownloadManager.download({\n                  dcId: 4,\n                  location: {\n                    _: 'inputWebFileLocation',\n                    access_hash: (item.thumb as WebDocument.webDocument).access_hash,\n                    url: item.thumb.url\n                  },\n                  size: item.thumb.size,\n                  mimeType: item.thumb.mime_type\n                }).then((blob) => {\n                  const image = new Image();\n                  image.classList.add('media-photo');\n                  readBlobAsDataURL(blob).then((dataURL) => {\n                    renderMediaWithFadeIn({\n                      container: mediaContainer,\n                      media: image,\n                      url: dataURL,\n                      needFadeIn: liteMode.isAvailable('animations')\n                    });\n                  });\n                });\n              }\n            });\n          }\n        } else {\n          const media = item.document as MyDocument || item.photo as MyPhoto;\n          if((['sticker', 'gif'] as MyDocument['type'][]).includes((media as MyDocument)?.type) && isGallery) {\n            assumeType<MyDocument>(media);\n\n            if(media.type === 'gif') {\n              gifsMasonry.add(media, container);\n            } else if(media.type === 'sticker') {\n              container.classList.add('super-sticker');\n              this.superStickerRenderer.renderSticker(media, container, loadPromises);\n              if(media.animated) {\n                this.superStickerRenderer.observeAnimated(container);\n              }\n            }\n          } else if(media) {\n            const size = isGallery ? 48 : undefined;\n            isGallery && container.classList.add('no-border-radius');\n            wrapPhoto({\n              photo: media,\n              container: isGallery ? container : preview,\n              boxWidth: size,\n              boxHeight: size,\n              middleware,\n              lazyLoadQueue: this.lazyLoadQueue,\n              loadPromises\n            });\n          }\n        }\n      }\n\n      return Promise.all(loadPromises).then(() => {\n        if(!middleware()) {\n          gifsMasonry.clear();\n          return;\n        }\n\n        list.classList.toggle('is-gallery', isGallery);\n        list.classList.toggle('super-stickers', isGallery);\n        this.container.classList.toggle('is-gallery', isGallery);\n\n        /* if(isGallery) {\n          list.style.gridTemplateColumns = `repeat(${Math.min(botResults.results.length, 4)}, 1fr)`;\n        }\n\n        this.container.style.setProperty('width', isGallery ? `${Math.min(botResults.results.length, 4) * 25}%` : '', 'important'); */\n\n        const parent = this.list.parentElement;\n        parent.textContent = '';\n        const switchTo = botResults.switch_pm || botResults.switch_webview;\n        if(switchTo) {\n          const btnSwitchTo = Button('btn-primary btn-secondary btn-primary-transparent primary');\n          setInnerHTML(btnSwitchTo, wrapEmojiText(switchTo.text));\n          attachClickEvent(btnSwitchTo, async(e) => {\n            if(switchTo._ === 'inlineBotSwitchPM') {\n              await this.chat.appImManager.setInnerPeer({peerId});\n              this.managers.appInlineBotsManager.switchToPM(peerId, botId, switchTo.start_param);\n            } else {\n              this.chat.openWebApp({\n                botId,\n                url: switchTo.url,\n                isSimpleWebView: true,\n                buttonText: switchTo.text,\n                fromSwitchWebView: true\n              });\n            }\n          });\n          parent.append(btnSwitchTo);\n        }\n        parent.append(this.list = list);\n        this.container.classList.remove('cant-send');\n\n        this.gifsMasonry?.detach();\n        this.gifsMasonry = gifsMasonry;\n        gifsMasonry.attach();\n\n        if(!this.onChangeScreen) {\n          this.onChangeScreen = () => {\n            if(this.list.classList.contains('is-gallery')) {\n              const width = (this.list.childElementCount * mediaSizes.active.popupSticker.width) + (this.list.childElementCount - 1 * 1);\n              this.list.style.width = width + 'px';\n            } else {\n              this.list.style.width = '';\n            }\n          };\n          mediaSizes.addEventListener('changeScreen', this.onChangeScreen);\n        }\n\n        this.onChangeScreen();\n\n        this.toggle(!botResults.results.length && !switchTo);\n        this.scrollable.scrollPosition = 0;\n      });\n    });\n\n    return {user: peer, renderPromise, guestChat: false};\n  };\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add('inline-helper-results');\n\n    this.container.append(this.list);\n\n    this.scrollable = new Scrollable(this.container);\n    this.lazyLoadQueue = new LazyLoadQueue();\n    this.superStickerRenderer = new SuperStickerRenderer({\n      regularLazyLoadQueue: this.lazyLoadQueue,\n      group: ANIMATION_GROUP,\n      managers: this.managers\n    });\n\n    const span = i18n(POSTING_NOT_ALLOWED_MAP['send_inline']);\n    span.classList.add('inline-helper-cant-send');\n    this.container.append(span);\n  }\n}\n","import type ChatInput from '@components/chat/input';\nimport callbackify from '@helpers/callbackify';\nimport AutocompletePeerHelper from '@components/chat/autocompletePeerHelper';\nimport {processPeerFullForCommands} from '@components/chat/commandsHelper';\nimport {AppManagers} from '@lib/managers';\nimport {Middleware} from '@helpers/middleware';\n\nconst CLASS_NAME = 'bot-commands';\nexport default class ChatBotCommands extends AutocompletePeerHelper {\n  private userId: UserId;\n\n  constructor(\n    appendTo: HTMLElement,\n    chatInput: ChatInput,\n    private managers: AppManagers\n  ) {\n    super(appendTo, undefined, CLASS_NAME, (target) => {\n      const innerHTML = target.querySelector(`.${AutocompletePeerHelper.BASE_CLASS_LIST_ELEMENT}-name`).innerHTML;\n      return chatInput.getReadyToSend(() => {\n        chatInput.messageInput.innerHTML = innerHTML;\n        chatInput.sendMessage(true);\n        this.toggle(true);\n      });\n    });\n  }\n\n  public setUserId(userId: UserId, middleware: Middleware) {\n    if(this.userId === userId && this.list?.childElementCount) {\n      this.toggle(false);\n      return;\n    }\n\n    this.userId = userId;\n    return callbackify(this.managers.appProfileManager.getProfile(userId), (full) => {\n      if(!middleware()) return;\n      const filtered = processPeerFullForCommands(userId.toPeerId(false), full);\n\n      const PADDING_TOP = 8;\n      // const PADDING_BOTTOM = 8;\n      const PADDING_BOTTOM = 24;\n      const height = filtered.length * 50 + PADDING_TOP + PADDING_BOTTOM;\n      this.container.style.setProperty('--height', height + 'px');\n\n      this.render(filtered, middleware);\n\n      // this.container.style.top =\n    });\n  }\n}\n","import {createContext, useContext, ParentProps} from 'solid-js';\n\ntype PromiseCollectorContextValue = {\n  collect: (promise: Promise<any>) => void;\n};\n\nconst PromiseCollectorContext = createContext<PromiseCollectorContextValue>({\n  collect: () => {}\n});\n\ntype PromiseCollectorProps = {\n  onCollect: (promise: Promise<any>) => void;\n};\n\nexport const PromiseCollector = (props: ParentProps<PromiseCollectorProps>) => {\n  return (\n    <PromiseCollectorContext.Provider value={{collect: props.onCollect}}>\n      {props.children}\n    </PromiseCollectorContext.Provider>\n  );\n};\n\nPromiseCollector.createHelper = () => {\n  const promises: Promise<any>[] = [];\n\n  let collectPromise = (promise: Promise<any>) => {\n    promises.push(promise);\n  };\n\n  return {\n    onCollect: (promise: Promise<any>) => collectPromise(promise),\n    await: () => {\n      collectPromise = () => {}; // lose reference to the promises array\n      return Promise.all(promises);\n    }\n  };\n};\n\nexport const usePromiseCollector = () => useContext(PromiseCollectorContext);\n","import {createContext, ParentComponent, useContext} from 'solid-js';\nimport {InstanceOf} from '@types';\nimport type SliderSuperTab from '@components/sliderTab';\nimport {ProvidedTabs} from '@components/solidJsTabs/providedTabs';\n\n\nconst SuperTabContext = createContext<[SliderSuperTab, ProvidedTabs]>();\n\ntype SuperTabProviderProps = {\n  self: SliderSuperTab;\n};\n\nexport const SuperTabProvider: ParentComponent<SuperTabProviderProps> & {\n  allTabs: ProvidedTabs;\n} = (props) => {\n  return (\n    <SuperTabContext.Provider value={[props.self, SuperTabProvider.allTabs]}>\n      {props.children}\n    </SuperTabContext.Provider>\n  );\n};\n\nSuperTabProvider.allTabs = {} as ProvidedTabs; // will get reassigned in index.ts\n\nexport const useSuperTab = <TabClass extends typeof SliderSuperTab>() =>\n  useContext(SuperTabContext) as [InstanceOf<TabClass>, ProvidedTabs];\n","import {Component} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport {LangPackKey} from '@lib/langPack';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {InstanceOf} from '@types';\nimport {SliderSuperTab} from '@components/slider';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {EventListenerListeners} from '@helpers/eventListenerBase';\nimport {PromiseCollector} from '@components/solidJsTabs/promiseCollector';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\n\n\ntype ScaffoldSolidJSTabArgs<Payload> = {\n  title: LangPackKey | ((payload: Payload) => LangPackKey);\n  getComponentModule: () => Promise<{default: Component}>;\n  onOpenAfterTimeout?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n  onClose?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n  onCloseAfterTimeout?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n};\n\ntype ScaffoledClass<Payload = void> = new (...args: ConstructorParameters<typeof SliderSuperTab>) => SliderSuperTab & {\n  payload: Payload;\n  init(payload: Payload, overrideTitle?: LangPackKey): Promise<void>;\n};\n\nexport function scaffoldSolidJSTab<Payload = void>({\n  title,\n  getComponentModule,\n  onOpenAfterTimeout,\n  onClose,\n  onCloseAfterTimeout\n}: ScaffoldSolidJSTabArgs<Payload>): ScaffoledClass<Payload> {\n  return class extends SliderSuperTab {\n    public payload: Payload;\n\n    private dispose?: () => void;\n\n    public async init(payload: Payload, overrideTitle?: LangPackKey) {\n      this.setTitle(overrideTitle || (typeof title === 'function' ? title(payload) : title));\n      this.payload = payload;\n\n      const div = document.createElement('div');\n\n      const {default: Component} = await getComponentModule();\n\n      const promiseCollectorHelper = PromiseCollector.createHelper();\n\n      this.dispose = render(() => (\n        <SolidJSHotReloadGuardProvider>\n          <PromiseCollector onCollect={promiseCollectorHelper.onCollect}>\n            <SuperTabProvider self={this}>\n              <Component />\n            </SuperTabProvider>\n          </PromiseCollector>\n        </SolidJSHotReloadGuardProvider>\n      ), div);\n\n      this.scrollable.append(div);\n\n      await promiseCollectorHelper.await();\n    }\n\n    protected onClose() {\n      onClose?.call?.(this);\n    }\n\n    protected onCloseAfterTimeout() {\n      onCloseAfterTimeout?.call?.(this);\n      this.dispose?.();\n      super.onCloseAfterTimeout();\n    }\n\n    protected onOpenAfterTimeout() {\n      onOpenAfterTimeout?.call?.(this);\n    }\n  } as ScaffoledClass<Payload>;\n}\n\n\ntype ScaffoldSolidJSTabEventableArgs<Payload> = {\n  title: LangPackKey | ((payload: Payload) => LangPackKey);\n  getComponentModule: () => Promise<{default: Component}>;\n  onOpenAfterTimeout?: (this: InstanceOf<ScaffoledEventableClass<Payload>>) => void;\n};\n\ntype ScaffoledEventableClass<Payload = void, Events extends EventListenerListeners = {}> =\n  new (...args: ConstructorParameters<typeof SliderSuperTab>) => SliderSuperTabEventable<Events> & {\n    payload: Payload;\n    init(payload: Payload, overrideTitle?: LangPackKey): Promise<void>;\n  };\n\n/**\n * Same as {@link scaffoldSolidJSTab} but the tab instance is a\n * {@link SliderSuperTabEventable}, so the rendered Solid component can dispatch\n * through (and external openers can listen on) `tab.eventListener` — needed by\n * e.g. PrivacySection, which saves on the tab's `destroy` event.\n */\nexport function scaffoldSolidJSTabEventable<Payload = void, Events extends EventListenerListeners = {}>({\n  title,\n  getComponentModule,\n  onOpenAfterTimeout\n}: ScaffoldSolidJSTabEventableArgs<Payload>): ScaffoledEventableClass<Payload, Events> {\n  return class extends SliderSuperTabEventable<Events> {\n    public payload: Payload;\n\n    private dispose?: () => void;\n\n    public async init(payload: Payload, overrideTitle?: LangPackKey) {\n      this.setTitle(overrideTitle || (typeof title === 'function' ? title(payload) : title));\n      this.payload = payload;\n\n      const div = document.createElement('div');\n\n      const {default: Component} = await getComponentModule();\n\n      const promiseCollectorHelper = PromiseCollector.createHelper();\n\n      this.dispose = render(() => (\n        <SolidJSHotReloadGuardProvider>\n          <PromiseCollector onCollect={promiseCollectorHelper.onCollect}>\n            <SuperTabProvider self={this}>\n              <Component />\n            </SuperTabProvider>\n          </PromiseCollector>\n        </SolidJSHotReloadGuardProvider>\n      ), div);\n\n      this.scrollable.append(div);\n\n      await promiseCollectorHelper.await();\n    }\n\n    public onCloseAfterTimeout() {\n      this.dispose?.();\n      return super.onCloseAfterTimeout();\n    }\n\n    protected onOpenAfterTimeout() {\n      onOpenAfterTimeout?.call?.(this);\n    }\n  } as ScaffoledEventableClass<Payload, Events>;\n}\n","import tsNow from '@helpers/tsNow';\nimport {ChatInviteImporter, ExportedChatInvite} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport hasRights from '@lib/appManagers/utils/chats/hasRights';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport {InviteLink} from '@components/sidebarLeft/tabs/inviteLink';\n\nexport type ChatInvite = ExportedChatInvite.chatInviteExported;\n\nexport type ChatInviteActions = {\n  revokeLink: () => void,\n  deleteLink: () => void,\n  editLink: () => void\n};\n\nexport function isActiveInvite(invite: ChatInvite) {\n  if(invite.pFlags.revoked) {\n    return false;\n  }\n\n  if(invite.expire_date && invite.expire_date <= tsNow(true)) {\n    return false;\n  }\n\n  if(invite.usage_limit && invite.usage_limit <= (invite.usage || 0)) {\n    return false;\n  }\n\n  return true;\n}\n\nexport class ChatInviteLink extends InviteLink {\n  public subtitle: HTMLElement;\n\n  constructor(public options: ConstructorParameters<typeof InviteLink>[0] & {\n    actions: ChatInviteActions,\n    withSubtitle?: boolean\n  }) {\n    super({\n      ...options\n    });\n\n    if(options.withSubtitle) {\n      this.subtitle = document.createElement('div');\n      this.subtitle.classList.add('invite-link-subtitle', 'hide');\n      this.container.append(this.subtitle);\n    }\n  }\n\n  public setChatInvite(chatInvite: ChatInvite | string) {\n    const isUsername = typeof(chatInvite) === 'string';\n    const username = typeof(chatInvite) === 'string' ? chatInvite : undefined;\n    this.setUrl(isUsername ? 't.me/' + username : chatInvite.link);\n\n    if(this.subtitle) {\n      if(!isUsername && chatInvite?.usage) {\n        this.subtitle.replaceChildren(i18n('InviteLink.JoinedNew', [chatInvite.usage]));\n      }\n\n      this.subtitle.classList.toggle('hide', isUsername || !chatInvite?.usage);\n    }\n\n    let hasSomething: LangPackKey;\n    if(!isUsername) {\n      if(chatInvite.pFlags.revoked) {\n        this.onButtonClick = () => this.options.actions.deleteLink();\n        hasSomething = 'DeleteLink';\n      } else if(!isActiveInvite(chatInvite)) {\n        this.onButtonClick = () => this.options.actions.editLink();\n        hasSomething = 'InviteLinks.Reactivate';\n      }\n    }\n\n    if(!hasSomething) {\n      hasSomething = 'ShareLink';\n      this.onButtonClick = undefined;\n    }\n\n    this.buttonText.replaceChildren(i18n(hasSomething));\n  }\n}\n\nexport function getImportersLoader({\n  chatId,\n  managers,\n  link,\n  requested\n}: {\n  chatId: ChatId,\n  managers: AppManagers,\n  link?: string,\n  requested?: boolean\n}) {\n  const importers: ChatInviteImporter[] = [];\n  const importersMap: Map<PeerId, ChatInviteImporter> = new Map();\n  let lastQuery = '';\n  const load: AppSelectPeers['getMoreCustom'] = async(q) => {\n    if(lastQuery !== q) {\n      importers.length = 0;\n      importersMap.clear();\n      lastQuery = q;\n    }\n\n    const limit = 50;\n    const lastImporter = importers[importers.length - 1];\n    const result = await managers.appChatInvitesManager.getChatInviteImporters({\n      chatId,\n      limit,\n      link,\n      requested,\n      offsetDate: lastImporter?.date,\n      offsetUserId: lastImporter?.user_id,\n      q\n    });\n\n    importers.push(...result.importers);\n\n    return {\n      result: result.importers.map((importer) => {\n        const peerId = importer.user_id.toPeerId(false);\n        importersMap.set(peerId, importer);\n        return peerId;\n      }),\n      isEnd: result.importers.length < limit\n    };\n  };\n\n  const deleteImporter = (peerId: PeerId) => {\n    importers.splice(importers.findIndex((importer) => importer.user_id.toPeerId(false) === peerId), 1);\n    importersMap.delete(peerId);\n  };\n\n  return {\n    importers,\n    importersMap,\n    load,\n    deleteImporter\n  };\n}\n\nexport function getChatInviteLinksInitArgs(chatId: ChatId, adminId?: UserId) {\n  return {\n    animationData: !adminId && lottieLoader.loadAnimationFromURLManually('UtyanLinks'),\n    invites: rootScope.managers.appChatInvitesManager.getExportedChatInvites({chatId, adminId}),\n    invitesRevoked: rootScope.managers.appChatInvitesManager.getExportedChatInvites({chatId, adminId, revoked: true}),\n    adminsInvites: !adminId && hasRights(apiManagerProxy.getChat(chatId), 'change_type') && rootScope.managers.appChatInvitesManager.getAdminsWithInvites(chatId),\n    chatFull: rootScope.managers.appProfileManager.getChatFull(chatId)\n  };\n}\n","import PopupElement from '.';\nimport filterUnique from '@helpers/array/filterUnique';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport shake from '@helpers/dom/shake';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {ChatlistsChatlistInvite, ChatlistsChatlistUpdates, DialogFilter, Peer} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {i18n, _i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport Button from '@components/button';\nimport wrapFolderTitle from '@components/wrappers/folderTitle';\nimport showLimitPopup from '@components/popups/limit';\n\nconst CLASS_NAME = 'popup-chatlist-invite';\nexport default class PopupSharedFolderInvite extends PopupElement {\n  private selector: AppSelectPeers;\n  private chatlistInvite: ChatlistsChatlistInvite;\n  private slug: string;\n  private filter: DialogFilter.dialogFilterChatlist;\n  private deleting: boolean;\n  private updating: boolean;\n\n  constructor(options: Partial<{\n    chatlistInvite: PopupSharedFolderInvite['chatlistInvite'],\n    slug: PopupSharedFolderInvite['slug'],\n    filter: PopupSharedFolderInvite['filter'],\n    deleting: PopupSharedFolderInvite['deleting'],\n    updating: PopupSharedFolderInvite['updating']\n  }>) {\n    super('popup-forward ' + CLASS_NAME, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      footer: true,\n      title: true,\n      withConfirm: true\n    });\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  public async construct() {\n    const n = document.createElement('div');\n    n.classList.add('menu-horizontal-scrollable');\n\n    const nav = document.createElement('nav');\n    nav.classList.add('menu-horizontal-div');\n\n    const {chatlistInvite, deleting, updating} = this;\n    const isAlready = chatlistInvite?._ === 'chatlists.chatlistInviteAlready';\n    const isJoining = isAlready && !!chatlistInvite.missing_peers.length;\n    const filter = this.filter ??= isAlready ? await this.managers.filtersStorage.getFilter(chatlistInvite.filter_id) as DialogFilter.dialogFilterChatlist : undefined;\n\n    this.title.append(i18n(deleting ? 'SharedFolder.Link.TitleRemove' : (isJoining ? 'SharedFolder.Link.TitleAdd' : 'SharedFolder.Link.Title')));\n\n    let leaveSuggestionsPeerIds: PeerId[];\n    if(deleting) {\n      const peers = await this.managers.filtersStorage.getLeaveChatlistSuggestions(this.filter.id);\n      leaveSuggestionsPeerIds = peers.map((peer) => getPeerId(peer));\n    }\n\n    const makeItem = () => {\n      const item = document.createElement('div');\n      item.classList.add('menu-horizontal-div-item');\n      const i = document.createElement('i');\n      i.classList.add('menu-horizontal-div-item-background');\n      const span = document.createElement('span');\n      span.classList.add('menu-horizontal-div-item-span');\n      item.append(i, span);\n      nav.append(item);\n      return span;\n    };\n\n    makeItem().append(i18n('FilterAllChats'));\n    const activeItem = makeItem();\n    activeItem.parentElement.classList.add('active');\n    activeItem.append(\n      await wrapFolderTitle(filter ? filter.title : (chatlistInvite as ChatlistsChatlistInvite.chatlistsChatlistInvite).title, this.middlewareHelper.get())\n    );\n    makeItem().append(i18n('FilterPersonal'));\n\n    const shadow = document.createElement('div');\n    shadow.classList.add('inner-shadow', 'inner-shadow-inset');\n\n    n.append(nav, shadow);\n\n    const description = document.createElement('div');\n    description.classList.add(CLASS_NAME + '-description', 'subtitle');\n    let descriptionAddI18n: I18n.IntlElement, descriptionAddTitle: HTMLElement;\n    if(deleting) {\n      _i18n(description, 'SharedFolder.Link.DescriptionRemove', [await wrapFolderTitle(filter.title, this.middlewareHelper.get())]);\n    } else if(!isJoining) {\n      _i18n(description, isAlready ? 'SharedFolder.Link.DescriptionAlready' : 'SharedFolder.Link.Description');\n    } else {\n      descriptionAddI18n = new I18n.IntlElement();\n      descriptionAddTitle = document.createElement('span');\n      descriptionAddTitle.append(await wrapFolderTitle(filter.title, this.middlewareHelper.get()));\n    }\n\n    const counterI18n = new I18n.IntlElement();\n\n    const onSelectionChange = (length: number) => {\n      if(alreadyPeerIds && isJoining) {\n        length = Math.max(0, length - alreadyPeerIds.length);\n      }\n\n      counterI18n.update({\n        key: deleting ? 'SharedFolder.Link.ChatsRemove' : (isJoining ? 'SharedFolder.Link.ChatsAdd' : (isAlready ? 'SharedFolder.Link.ChatsAlready' : 'SharedFolder.Link.Chats')),\n        args: [i18n('Chats', [length])]\n      });\n\n      selectAllI18n?.update({\n        key: (shouldDeselect = length === peerIds.length) ? 'DeselectAll' : 'SelectAll'\n      });\n\n      descriptionAddI18n?.update({\n        key: 'SharedFolder.Link.DescriptionAdd',\n        args: [i18n('Chats', [length]), descriptionAddTitle]\n      });\n\n      if(selectAllI18n) {\n        if(length) addFolderText.dataset.badge = '' + length;\n        addFolderText.classList.toggle('has-badge', !!length);\n      }\n\n      if(deleting) {\n        addFolderI18n.update({\n          key: length ? 'SharedFolder.Link.Remove' : 'SharedFolder.Link.TitleRemove'\n        });\n      }\n\n      if(!deleting) {\n        toggleDisability([this.btnConfirm], !length);\n      }\n    };\n\n    let shouldDeselect: boolean;\n    this.selector = new AppSelectPeers({\n      middleware: this.middlewareHelper.get(),\n      appendTo: this.body,\n      onChange: onSelectionChange,\n      onFirstRender: () => {\n        this.show();\n        this.selector.checkForTriggers(); // ! due to zero height before mounting\n      },\n      multiSelect: true,\n      noSearch: true,\n      sectionNameLangPackKey: counterI18n.element,\n      avatarSize: 'abitbigger',\n      managers: this.managers,\n      peerType: [],\n      getSubtitleForElement: async(peerId) => {\n        if(alreadyPeerIds?.includes(peerId)) {\n          const isBroadcast = await this.managers.appPeersManager.isBroadcast(peerId);\n          return i18n(isBroadcast ? 'SharedFolder.Link.ChannelAlready' : 'SharedFolder.Link.ChatAlready');\n        }\n      },\n      processElementAfter: (peerId, dialogElement) => {\n        if(alreadyPeerIds?.includes(peerId)) {\n          dialogElement.dom.containerEl.classList.add('already');\n        }\n      }\n    });\n\n    let selectAllI18n: I18n.IntlElement;\n    if(!isAlready || isJoining) {\n      selectAllI18n = new I18n.IntlElement();\n      selectAllI18n.element.classList.add('sidebar-left-section-name-right');\n      this.selector.section.title.append(selectAllI18n.element);\n\n      attachClickEvent(selectAllI18n.element, () => {\n        if(shouldDeselect) {\n          this.selector.removeBatch(peerIds);\n        } else {\n          this.selector.addBatch(peerIds);\n        }\n      }, {listenerSetter: this.listenerSetter});\n    }\n\n    let peerIds: PeerId[];\n    if(chatlistInvite) {\n      const peers = isJoining ? chatlistInvite.missing_peers : (isAlready ? chatlistInvite.already_peers : chatlistInvite.peers);\n      peerIds = peers.map((peer) => getPeerId(peer));\n    } else {\n      peerIds = filter.includePeerIds;\n    }\n\n    let alreadyPeerIds: PeerId[];\n    if(isAlready) {\n      alreadyPeerIds = chatlistInvite.already_peers.map((peer) => getPeerId(peer));\n    }\n\n    if(alreadyPeerIds) {\n      const _remove = this.selector.remove.bind(this.selector);\n      this.selector.remove = (...args) => {\n        const peerId = args[0].toPeerId();\n        if(alreadyPeerIds.includes(peerId)) {\n          const container = this.selector.getElementByKey(peerId);\n          shake(container);\n          return false;\n        }\n\n        return _remove(...args);\n      };\n    }\n\n    this.scrollable = this.selector.scrollable;\n    this.attachScrollableListeners();\n\n    this.scrollable.prepend(n, description);\n\n    this.btnConfirm.classList.add(`${CLASS_NAME}-button`);\n    const addFolderI18n = new I18n.IntlElement({\n      key: deleting ? 'SharedFolder.Link.Remove' : (isJoining ? 'SharedFolder.Link.Join' : (isAlready ? 'OK' : 'SharedFolder.Link.Title'))\n    });\n    const addFolderText = addFolderI18n.element;\n    addFolderText.classList.add(`${CLASS_NAME}-button-text`);\n    this.btnConfirm.append(addFolderText);\n    this.footer.append(this.btnConfirm);\n\n    attachClickEvent(this.btnConfirm, () => {\n      if(isAlready && !isJoining) {\n        this.hide();\n        return;\n      }\n\n      let promise: Promise<any>;\n\n      const toggle = toggleDisability([this.btnConfirm], true);\n\n      const peerIds = [...this.selector.selected] as PeerId[];\n      if(updating) {\n        promise = this.managers.filtersStorage.joinChatlistUpdates(this.filter.id, peerIds);\n      } else if(chatlistInvite) {\n        promise = this.managers.filtersStorage.joinChatlistInvite(\n          this.slug,\n          peerIds\n        ).catch((error: ApiError) => {\n          if(error.type === 'DIALOG_FILTERS_TOO_MUCH') {\n            showLimitPopup('folders');\n            this.hide();\n          } else {\n            throw error;\n          }\n        });\n      } else {\n        promise = this.managers.filtersStorage.leaveChatlist(this.filter.id, peerIds);\n      }\n\n      promise.then(() => {\n        this.hide();\n      }, (error: ApiError) => {\n        toggle();\n        throw error;\n      });\n    }, {listenerSetter: this.listenerSetter});\n\n    const totalPeerIds = alreadyPeerIds ? peerIds.concat(alreadyPeerIds) : peerIds;\n    const initial = deleting ? leaveSuggestionsPeerIds : totalPeerIds\n    this.selector.addInitial(initial);\n    this.selector.renderResultsFunc(deleting ? filterUnique(leaveSuggestionsPeerIds.concat(totalPeerIds)) : totalPeerIds);\n\n    if(!initial.length) {\n      onSelectionChange(0);\n    }\n    // if(isAlready && !isJoining) {\n    //   this.selector.list.classList.add('disable-hover');\n    // }\n\n    this.body.after(this.footer);\n  }\n}\n","import {DialogFilter} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport confirmationPopup from '@components/confirmationPopup';\nimport PopupElement from '@components/popups';\nimport PopupSharedFolderInvite from '@components/popups/sharedFolderInvite';\n\nexport function getEditFolderInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('Folders_2')\n  };\n}\n\nexport async function deleteFolder(filterId: number) {\n  const filter = await rootScope.managers.filtersStorage.getFilter(filterId);\n  if(filter?._ === 'dialogFilterChatlist' && !filter.pFlags.has_my_invites) {\n    PopupElement.createPopup(PopupSharedFolderInvite, {\n      filter,\n      deleting: true\n    });\n\n    return;\n  }\n\n  await confirmationPopup({\n    titleLangKey: 'ChatList.Filter.Confirm.Remove.Header',\n    descriptionLangKey: (filter as DialogFilter.dialogFilterChatlist).pFlags.has_my_invites ? 'RemoveSharedFolder' : 'ChatList.Filter.Confirm.Remove.Text',\n    button: {\n      langKey: 'Delete',\n      isDanger: true\n    }\n  });\n\n  return rootScope.managers.filtersStorage.updateDialogFilter(\n    {\n      _: 'dialogFilter',\n      id: filterId\n    } as DialogFilter.dialogFilter,\n    true\n  );\n}\n","import {CancellablePromise} from '@helpers/cancellablePromise';\nimport {AccountPasskeys, AccountPassword, Authorization, ChannelParticipant, Chat, ChatFull, ChatParticipant, DialogFilter, ExportedChatlistInvite, GlobalPrivacySettings, Passkey, WebAuthorization} from '@layer';\nimport type SidebarSlider from '@components/slider';\nimport type {SliderSuperTab} from '@components/slider';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport type {MyDialogFilter} from '@lib/storages/filters';\nimport {FormatterArgument, LangPackKey} from '@lib/langPack';\nimport type {PasscodeActions} from '@lib/passcode/actions';\nimport {InstanceOf} from '@types';\nimport {SetStoreFunction} from 'solid-js/store';\nimport {scaffoldSolidJSTab, scaffoldSolidJSTabEventable} from '@components/solidJsTabs/scaffoldSolidJSTab';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\nimport rootScope from '@lib/rootScope';\nimport type {EditProfileTabPayload} from '@components/sidebarLeft/tabs/editProfile';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {ChatInvite, ChatInviteActions, getChatInviteLinksInitArgs} from '@components/sidebarRight/tabs/chatInviteLinkShared';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport {deleteFolder as deleteEditFolder, getEditFolderInitArgs} from '@components/sidebarLeft/tabs/editFolderShared';\n\n\nexport const AppPasscodeLockTab =\n  scaffoldSolidJSTab({\n    title: 'PasscodeLock.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/passcodeLock/mainTab'),\n    onOpenAfterTimeout: async function() {\n      // Remove the previous enter password tab\n      this.slider.sliceTabsUntilTab(\n        SuperTabProvider.allTabs.AppPrivacyAndSecurityTab,\n        this\n      );\n    }\n  });\n\n\ntype AppPasscodeEnterPasswordTabPayload = {\n  onSubmit: (passcode: string, tab: InstanceOf<typeof AppPasscodeEnterPasswordTab>, passcodeActions: PasscodeActions) => MaybePromise<void>;\n\n  inputLabel: LangPackKey;\n  buttonText: LangPackKey;\n};\n\nexport const AppPasscodeEnterPasswordTab =\n  scaffoldSolidJSTab<AppPasscodeEnterPasswordTabPayload>({\n    title: 'PasscodeLock.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/passcodeLock/enterPasswordTab')\n  });\n\n\ntype AppPrivacyMessagesTabPayload = {\n  onSaved: (globalPrivacy: CancellablePromise<GlobalPrivacySettings.globalPrivacySettings>) => void;\n};\n\nexport const AppPrivacyMessagesTab =\n  scaffoldSolidJSTab<AppPrivacyMessagesTabPayload>({\n    title: 'PrivacyMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/messages/tab')\n  });\n\n\ntype AppDirectMessagesTabPayload = {\n  chat: Chat.channel;\n};\n\nexport const AppDirectMessagesTab =\n  scaffoldSolidJSTab<AppDirectMessagesTabPayload>({\n    title: 'ChannelDirectMessages.Settings.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/channelDirectMessages')\n  });\n\n\nexport const AppNotificationsTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.NotificationSettingsViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/notifications')\n  });\n\n\nexport function getEditProfileInitArgs(): Omit<EditProfileTabPayload, 'focusOn'> {\n  return {\n    bioMaxLength: rootScope.managers.apiManager.getLimit('bio'),\n    user: rootScope.managers.appUsersManager.getSelf(),\n    userFull: rootScope.managers.appProfileManager.getProfile(rootScope.myId.toUserId())\n  };\n}\n\nexport const AppEditProfileTab =\n  scaffoldSolidJSTab<EditProfileTabPayload>({\n    title: 'EditAccount.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/editProfile')\n  });\n(AppEditProfileTab as any).noSame = true;\n\n\nexport const AppKeyboardShortcutsTab =\n  scaffoldSolidJSTab({\n    title: 'KeyboardShortcuts.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/keyboardShortcuts')\n  });\n\n\nexport const AppAgentMetricsTab =\n  scaffoldSolidJSTab({\n    title: 'AgentMetrics.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/agentMetrics')\n  });\n\n\nexport const AppQuickRepliesTab =\n  scaffoldSolidJSTab({\n    title: 'QuickReplies.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/quickReplies')\n  });\n\n\nexport const AppProjectTasksTab =\n  scaffoldSolidJSTab({\n    title: 'Tasks.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/projectTasks')\n  });\n\n\ntype AppAdminRecentActionsTabPayload = {\n  channelId: ChatId;\n  isBroadcast: boolean;\n};\n\nexport const AppAdminRecentActionsTab =\n  scaffoldSolidJSTab<AppAdminRecentActionsTabPayload>({\n    title: 'RecentActions',\n    getComponentModule: () => import('../sidebarRight/tabs/adminRecentActions')\n  });\n\n\ntype AppPasskeysTabPayload = {\n  passkeys: Passkey[],\n  setPasskeys: SetStoreFunction<Passkey[]>\n};\n\nexport const AppPasskeysTab =\n  scaffoldSolidJSTab<AppPasskeysTabPayload>({\n    title: 'Privacy.Passkeys',\n    getComponentModule: () => import('../sidebarLeft/tabs/passkeys')\n  });\n\ntype AppMessagesAutoDeleteTabPayload = {\n  period: number;\n  onSaved: (period: number) => void;\n};\n\nexport const AppMessagesAutoDeleteTab =\n  scaffoldSolidJSTab<AppMessagesAutoDeleteTabPayload>({\n    title: 'AutoDeleteMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDeleteMessages')\n  });\n\nexport const AppArchiveSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'ArchiveSettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/archiveSettingsTab')\n  });\n\nexport const AppGeneralSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.GeneralSettingsViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/generalSettings')\n  });\n\n\nexport const AppChatBackgroundTab =\n  scaffoldSolidJSTab({\n    title: 'ChatBackground',\n    getComponentModule: () => import('../sidebarLeft/tabs/background')\n  });\n\n\nexport const AppLanguageTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.LanguageViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/language')\n  });\n\n\nexport const AppSpeakersAndCameraTab =\n  scaffoldSolidJSTab({\n    title: 'AccountSettings.SpeakersAndCamera',\n    getComponentModule: () => import('../sidebarLeft/tabs/speakersAndCamera')\n  });\n\n\nexport const AppSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'Settings',\n    getComponentModule: () => import('../sidebarLeft/tabs/settings')\n  });\n\n\nexport const AppQuickReactionTab =\n  scaffoldSolidJSTab({\n    title: 'DoubleTapSetting',\n    getComponentModule: () => import('../sidebarLeft/tabs/quickReaction')\n  });\n\n\nexport const AppStickersAndEmojiTab =\n  scaffoldSolidJSTab({\n    title: 'StickersName',\n    getComponentModule: () => import('../sidebarLeft/tabs/stickersAndEmoji')\n  });\n\n\nexport const AppContactsTab =\n  scaffoldSolidJSTab({\n    title: 'Contacts',\n    getComponentModule: () => import('../sidebarLeft/tabs/contacts'),\n    onOpenAfterTimeout: function() {\n      (this as any)._focusOnOpen?.();\n    }\n  });\n(AppContactsTab as any).noSame = true;\n\n\nexport const AppPowerSavingTab =\n  scaffoldSolidJSTab({\n    title: 'LiteMode.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/powerSaving')\n  });\n\n\ntype AppBlockedUsersTabPayload = {\n  peerIds: PeerId[];\n};\n\nexport const AppBlockedUsersTab =\n  scaffoldSolidJSTab<AppBlockedUsersTabPayload>({\n    title: 'BlockedUsers',\n    getComponentModule: () => import('../sidebarLeft/tabs/blockedUsers'),\n    onOpenAfterTimeout: function() {\n      this.scrollable.onScroll();\n    }\n  });\n\n\nexport const AppNewChannelTab =\n  scaffoldSolidJSTab({\n    title: 'NewChannel',\n    getComponentModule: () => import('../sidebarLeft/tabs/newChannel')\n  });\n(AppNewChannelTab as any).noSame = true;\n\n\nexport const AppBackgroundColorTab =\n  scaffoldSolidJSTab({\n    title: 'SetColor',\n    getComponentModule: () => import('../sidebarLeft/tabs/backgroundColor')\n  });\n\n\ntype AppNewGroupTabPayload = {\n  peerIds: PeerId[],\n  isGeoChat?: boolean,\n  onCreate?: (chatId: ChatId) => void,\n  openAfter?: boolean,\n  title?: string,\n  asChannel?: boolean\n};\n\nexport const AppNewGroupTab =\n  scaffoldSolidJSTab<AppNewGroupTabPayload>({\n    title: 'NewGroup',\n    getComponentModule: () => import('../sidebarLeft/tabs/newGroup')\n  });\n(AppNewGroupTab as any).noSame = true;\n\n\n// ─── Privacy sub-tabs (eventable: PrivacySection saves on the tab's destroy event) ───\n\nexport const AppPrivacyAboutTab =\n  scaffoldSolidJSTabEventable({\n    title: 'UserBio',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/about')\n  });\n\nexport const AppPrivacyCallsTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.VoiceCalls',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/calls')\n  });\n\nexport const AppPrivacyVoicesTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyVoiceMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/voices')\n  });\n\nexport const AppPrivacyAddToGroupsTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.Groups',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/addToGroups')\n  });\n\nexport const AppPrivacyBirthdayTab =\n  scaffoldSolidJSTabEventable({\n    title: 'Birthday',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/birthday')\n  });\n\nexport const AppPrivacyForwardMessagesTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.Forwards',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/forwardMessages')\n  });\n\nexport const AppPrivacyProfilePhotoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyProfilePhoto',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/profilePhoto')\n  });\n\nexport const AppPrivacySavedMusicTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySavedMusic',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/savedMusic')\n  });\n\nexport const AppPrivacyPhoneNumberTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyPhone',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/phoneNumber')\n  });\n\ntype AppPrivacyGlobalTabEvents = {\n  privacy: (globalPrivacy: Promise<GlobalPrivacySettings>) => void\n};\n\nexport const AppPrivacyLastSeenTab =\n  scaffoldSolidJSTabEventable<GlobalPrivacySettings, AppPrivacyGlobalTabEvents>({\n    title: 'PrivacyLastSeen',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/lastSeen')\n  });\n\nexport const AppPrivacyGiftsTab =\n  scaffoldSolidJSTabEventable<GlobalPrivacySettings, AppPrivacyGlobalTabEvents>({\n    title: 'PrivacyGifts',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/gifts')\n  });\n\n\ntype AppActiveSessionsTabPayload = {\n  authorizations: Authorization.authorization[];\n};\n\nexport const AppActiveSessionsTab =\n  scaffoldSolidJSTabEventable<AppActiveSessionsTabPayload>({\n    title: 'SessionsTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/activeSessions')\n  });\n\nexport const AppActiveWebSessionsTab =\n  scaffoldSolidJSTabEventable<WebAuthorization[]>({\n    title: 'WebSessionsTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/activeWebSessions')\n  });\n\n\n// ─── Data and storage + its auto-download sub-tabs (all eventable) ───\n\nexport const AppAutoDownloadPhotoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadPhotos',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/photo')\n  });\n\nexport const AppAutoDownloadVideoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadVideos',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/video')\n  });\n\nexport const AppAutoDownloadFileTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadFiles',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/file')\n  });\n\nexport const AppDataAndStorageTab =\n  scaffoldSolidJSTabEventable({\n    title: 'DataSettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/dataAndStorage')\n  });\n\n\n// ─── Right sidebar ───\n\nexport const AppRemovedUsersTab =\n  scaffoldSolidJSTabEventable<ChatId>({\n    title: 'ChannelBlacklist',\n    getComponentModule: () => import('../sidebarRight/tabs/removedUsers')\n  });\n\nexport const AppGifsTab =\n  scaffoldSolidJSTab({\n    title: 'SearchGifsTitle',\n    getComponentModule: () => import('../sidebarRight/tabs/gifs')\n  });\n\nexport const AppChatRequestsTab =\n  scaffoldSolidJSTabEventable<ChatId, {finish: (changedLength: number) => void}>({\n    title: 'MemberRequests',\n    getComponentModule: () => import('../sidebarRight/tabs/chatRequests')\n  });\n\nexport const AppChatReactionsTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId}>({\n    title: 'Reactions',\n    getComponentModule: () => import('../sidebarRight/tabs/chatReactions')\n  });\n\nexport const AppChatMembersTab =\n  scaffoldSolidJSTabEventable<ChatId>({\n    title: 'GroupMembers',\n    getComponentModule: () => import('../sidebarRight/tabs/chatMembers')\n  });\n\nexport const AppChatAdministratorsTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId}>({\n    title: 'PeerInfo.Administrators',\n    getComponentModule: () => import('../sidebarRight/tabs/chatAdministrators')\n  });\n\nexport const AppEditBotTab =\n  scaffoldSolidJSTab<PeerId>({\n    title: 'EditBot.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/editBot')\n  });\n\nexport const AppEditContactTab =\n  scaffoldSolidJSTab<PeerId>({\n    title: 'Edit',\n    getComponentModule: () => import('../sidebarRight/tabs/editContact')\n  });\n\nexport const AppEditTopicTab =\n  scaffoldSolidJSTab<{peerId: PeerId, threadId?: number}>({\n    title: (p) => p.threadId ? 'ForumTopic.Title.Edit' : 'NewTopic',\n    getComponentModule: () => import('../sidebarRight/tabs/editTopic')\n  });\n\nexport const AppStickersTab =\n  scaffoldSolidJSTab({\n    title: 'StickersName',\n    getComponentModule: () => import('../sidebarRight/tabs/stickers')\n  });\n\nexport const AppChatDiscussionTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId, linkedChatId: ChatId}>({\n    title: 'DiscussionController.Channel.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/chatDiscussion')\n  });\n\nexport const AppChatTypeTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId, chatFull: ChatFull}>({\n    title: 'ChannelType',\n    getComponentModule: () => import('../sidebarRight/tabs/chatType')\n  });\n\ntype AppUserPermissionsTabPayload = {\n  participant: ChannelParticipant | ChatParticipant,\n  chatId: ChatId,\n  userId: UserId,\n  editingAdmin?: boolean\n};\n\nexport const AppUserPermissionsTab =\n  scaffoldSolidJSTabEventable<AppUserPermissionsTabPayload>({\n    title: (p) => p.editingAdmin ? 'EditAdmin' : 'UserRestrictions',\n    getComponentModule: () => import('../sidebarRight/tabs/userPermissions')\n  });\n\n// Replaces the legacy AppUserPermissionsTab.openTab static.\nexport function openUserPermissionsTab(\n  slider: SidebarSlider,\n  chatId: ChatId,\n  participant: ChatParticipant | ChannelParticipant,\n  isAdmin?: boolean\n) {\n  slider.createTab(AppUserPermissionsTab).open({\n    participant,\n    chatId,\n    userId: getParticipantPeerId(participant).toUserId(),\n    editingAdmin: isAdmin\n  });\n}\n\n\ntype AppIncludedChatsTabPayload = {\n  filter: MyDialogFilter,\n  type: 'included' | 'excluded',\n  onSetFilter: (filter: MyDialogFilter) => void\n};\n\nexport const AppIncludedChatsTab =\n  scaffoldSolidJSTab<AppIncludedChatsTabPayload>({\n    title: (p) => p.type === 'included' ? 'FilterAlwaysShow' : 'FilterNeverShow',\n    getComponentModule: () => import('../sidebarLeft/tabs/includedChats')\n  });\n\ntype AppSharedFolderTabPayload = {\n  filter: DialogFilter.dialogFilterChatlist,\n  chatlistInvite: ExportedChatlistInvite\n};\n\nexport const AppSharedFolderTab =\n  scaffoldSolidJSTabEventable<AppSharedFolderTabPayload, {\n    delete: () => void,\n    edit: (chatlistInvite: ExportedChatlistInvite) => void\n      }>({\n        title: 'SharedFolder.Edit.Title',\n        getComponentModule: () => import('../sidebarLeft/tabs/sharedFolder'),\n        onOpenAfterTimeout: function() {\n          (this as any)._onOpenAfterTimeout?.();\n        }\n      });\n\ntype AppGroupPermissionsTabPayload = {\n  chatId: ChatId\n};\n\nexport const AppGroupPermissionsTab =\n  scaffoldSolidJSTab<AppGroupPermissionsTabPayload>({\n    title: 'ChannelPermissions',\n    getComponentModule: () => import('../sidebarRight/tabs/groupPermissions/groupPermissions'),\n    onOpenAfterTimeout: function() {\n      this.scrollable.onScroll();\n    }\n  });\n\nconst getPrivacyAndSecurityInitArgs = (fromTab: SliderSuperTab) => ({\n  appConfig: fromTab.managers.apiManager.getAppConfig(),\n  globalPrivacy: fromTab.managers.appPrivacyManager.getGlobalPrivacySettings(),\n  webAuthorizations: fromTab.managers.appSeamlessLoginManager.getWebAuthorizations()\n});\n\ntype AppPrivacyAndSecurityTabPayload = ReturnType<typeof getPrivacyAndSecurityInitArgs>;\n\nexport const AppPrivacyAndSecurityTab =\n  scaffoldSolidJSTabEventable<AppPrivacyAndSecurityTabPayload>({\n    title: 'PrivacySettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacyAndSecurity')\n  });\n\n// Preload (appConfig / globalPrivacy / webAuthorizations) read off the constructor\n// by settings.tsx's makeSubTabConfig, matching the old static getInitArgs.\n(AppPrivacyAndSecurityTab as any).getInitArgs = getPrivacyAndSecurityInitArgs;\n\n\ntype AppEditChatInviteLinkTabPayload = {\n  chatId: ChatId,\n  invite?: ChatInvite\n};\n\nexport const AppEditChatInviteLinkTab =\n  scaffoldSolidJSTabEventable<AppEditChatInviteLinkTabPayload, {\n    finish: (chatInvite: ChatInvite) => void\n      }>({\n        title: (p) => p.invite ? 'InviteLinks.Edit' : 'NewLink',\n        getComponentModule: () => import('../sidebarRight/tabs/editChatInviteLink')\n      });\n\n\ntype AppChatInviteLinkTabPayload = {\n  chatId: ChatId,\n  chatInvite: ChatInvite,\n  menuButtons: ButtonMenuItemOptionsVerifiable[],\n  actions: ChatInviteActions,\n  onUpdate?: (chatInvite: ChatInvite) => void\n};\n\nexport const AppChatInviteLinkTab =\n  scaffoldSolidJSTabEventable<AppChatInviteLinkTabPayload>({\n    title: 'InviteLink',\n    getComponentModule: () => import('../sidebarRight/tabs/chatInviteLink')\n  });\n\n\ntype AppChatInviteLinksTabPayload = {\n  chatId: ChatId,\n  adminId?: UserId,\n  p?: ReturnType<typeof getChatInviteLinksInitArgs>\n};\n\n// getInitArgs is read directly (typed) by editChat's navigationTab, so expose it\n// on the constructor via Object.assign rather than an untyped property poke.\nexport const AppChatInviteLinksTab = Object.assign(\n  scaffoldSolidJSTabEventable<AppChatInviteLinksTabPayload>({\n    title: 'InviteLinks',\n    getComponentModule: () => import('../sidebarRight/tabs/chatInviteLinks')\n  }),\n  {getInitArgs: getChatInviteLinksInitArgs}\n);\n\n\ntype AppEditChatTabPayload = {\n  chatId: ChatId\n};\n\nexport const AppEditChatTab =\n  scaffoldSolidJSTab<AppEditChatTabPayload>({\n    title: 'Edit',\n    getComponentModule: () => import('../sidebarRight/tabs/editChat')\n  });\n\n\nfunction getChatFoldersInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('Folders_1'),\n    filters: rootScope.managers.filtersStorage.getDialogFilters()\n  };\n}\n\ntype AppChatFoldersTabPayload = ReturnType<typeof getChatFoldersInitArgs>;\n\n// getInitArgs is read both via makeSubTabConfig (any-cast) and directly (typed)\n// by foldersSidebarContent, so expose it on the constructor via Object.assign.\nexport const AppChatFoldersTab = Object.assign(\n  scaffoldSolidJSTab<AppChatFoldersTabPayload>({\n    title: 'ChatList.Filter.List.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/chatFolders'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  }),\n  {getInitArgs: getChatFoldersInitArgs}\n);\n\n\ntype AppEditFolderTabPayload = ReturnType<typeof getEditFolderInitArgs> & {\n  initFilter?: MyDialogFilter\n};\n\n// getInitArgs (preload) + deleteFolder (called from createFolderContextMenu and\n// chatFolders via the hot-reload guard) are exposed on the constructor.\nexport const AppEditFolderTab = Object.assign(\n  scaffoldSolidJSTab<AppEditFolderTabPayload>({\n    title: 'FilterHeaderEdit',\n    getComponentModule: () => import('../sidebarLeft/tabs/editFolder'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  }),\n  {\n    getInitArgs: getEditFolderInitArgs,\n    deleteFolder: deleteEditFolder\n  }\n);\n\n\nfunction getMyStoriesInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('UtyanStories')\n  };\n}\n\ntype AppMyStoriesTabPayload = ReturnType<typeof getMyStoriesInitArgs> & {\n  isArchive?: boolean,\n  chatId?: ChatId,\n  initialAlbumId?: number\n};\n\nexport const AppMyStoriesTab = Object.assign(\n  scaffoldSolidJSTab<AppMyStoriesTabPayload>({\n    title: (p) => p.isArchive ? 'MyStories.Archive' : 'MyStories.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/myStories')\n  }),\n  {getInitArgs: getMyStoriesInitArgs}\n);\n\n\nexport const AppArchivedTab =\n  scaffoldSolidJSTab({\n    title: 'ArchivedChats',\n    getComponentModule: () => import('../sidebarLeft/tabs/archivedTab'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onClose: function() {\n      (this as any)._onClose?.();\n    },\n    onCloseAfterTimeout: function() {\n      (this as any)._onCloseAfterTimeout?.();\n    }\n  });\n\n\n// ── 2FA wizard ──────────────────────────────────────────────────────────────\n\ntype AppTwoStepVerificationSetTabPayload = {\n  messageFor: 'password' | 'email'\n};\n\nexport const AppTwoStepVerificationSetTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationSetTabPayload>({\n    title: (p) => p.messageFor === 'password' ? 'TwoStepVerificationPasswordSet' : 'TwoStepVerificationEmailSet',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/passwordSet')\n  });\n\n\ntype AppTwoStepVerificationTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string\n};\n\nexport const AppTwoStepVerificationTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationTabPayload>({\n    title: 'TwoStepVerificationTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/index')\n  });\n\n\ntype AppTwoStepVerificationEnterPasswordTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  isFirst?: boolean\n};\n\nexport const AppTwoStepVerificationEnterPasswordTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEnterPasswordTabPayload>({\n    title: (p) => (!p.state.pFlags.has_password || p.plainPassword) ? 'PleaseEnterFirstPassword' : 'PleaseEnterCurrentPassword',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/enterPassword'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onClose: function() {\n      (this as any)._onClose?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationReEnterPasswordTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string\n};\n\nexport const AppTwoStepVerificationReEnterPasswordTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationReEnterPasswordTabPayload>({\n    title: 'PleaseReEnterPassword',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/reEnterPassword'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationHintTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string\n};\n\nexport const AppTwoStepVerificationHintTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationHintTabPayload>({\n    title: 'TwoStepAuth.SetupHintTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/hint'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationEmailTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string,\n  hint?: string,\n  isFirst?: boolean,\n  justSetPasssword?: boolean\n};\n\nexport const AppTwoStepVerificationEmailTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEmailTabPayload>({\n    title: 'RecoveryEmailTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/email'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationEmailConfirmationTabPayload = {\n  state: AccountPassword,\n  email: FormatterArgument,\n  length: number,\n  isFirst?: boolean,\n  forPasswordReset?: boolean,\n  justSetPasssword?: boolean\n};\n\nexport const AppTwoStepVerificationEmailConfirmationTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEmailConfirmationTabPayload>({\n    title: 'TwoStepAuth.RecoveryTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/emailConfirmation'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onCloseAfterTimeout: function() {\n      (this as any)._onCloseAfterTimeout?.();\n    }\n  });\n\n\ntype AppPrivateSearchTabPayload = {\n  peerId: PeerId,\n  threadId?: number,\n  onDatePick?: (timestamp: number) => void,\n  query?: string\n};\n\nexport const AppPrivateSearchTab =\n  scaffoldSolidJSTab<AppPrivateSearchTabPayload>({\n    title: 'Search',\n    getComponentModule: () => import('../sidebarRight/tabs/search'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\nexport type AppAddMembersExtraCategory = {\n  key: string;\n  icon: Icon;\n  text: LangPackKey;\n  statusLangKey?: LangPackKey;\n};\n\ntype AppAddMembersTabPayload = {\n  title: LangPackKey;\n  placeholder: LangPackKey;\n  type: 'channel' | 'chat' | 'privacy';\n  takeOut?: (peerIds: PeerId[], extras?: Set<string>) => Promise<any> | false | void;\n  skippable: boolean;\n  selectedPeerIds?: PeerId[];\n  selectedExtras?: Set<string>;\n  extraCategories?: ReadonlyArray<AppAddMembersExtraCategory>;\n  extraCategoriesSectionLangKey?: LangPackKey;\n  attachToPromise?: (promise: Promise<any>) => void;\n};\n\nexport const AppAddMembersTab =\n  scaffoldSolidJSTab<AppAddMembersTabPayload>({\n    title: 'GroupAddMembers',\n    getComponentModule: () => import('../sidebarLeft/tabs/addMembers')\n  });\n(AppAddMembersTab as any).noSame = true;\nconst _origAddMembersInit = (AppAddMembersTab.prototype as any).init;\n(AppAddMembersTab.prototype as any).init = function(payload: AppAddMembersTabPayload, overrideTitle?: LangPackKey) {\n  return _origAddMembersInit.call(this, payload, overrideTitle || payload.title);\n};\n","import {createEffect, createResource, createSignal, For, on, Show} from 'solid-js';\nimport PopupElement, {createPopup} from '@components/popups/indexTsx';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport I18n, {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport InputField from '@components/inputField';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport Row from '@components/rowTsx';\nimport Scrollable from '@components/scrollable2';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport {toast, toastNew} from '@components/toast';\nimport {CrmProject, CrmProjectMember} from '@lib/crm/types';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\n\nimport styles from './crmCreateTask.module.scss';\n\n/**\n * The CRM task composer: project, title, details, and who it goes to.\n *\n * Used from two places — \"turn this message into a task\" in a conversation\n * (which also carries the customer and the exact message), and \"assign to\n * someone else\" in the My Tasks panel, where there is no chat at all. Both need\n * the same thing: a task can go to OTHER agents, not only the person creating\n * it, and the full captured text survives even when the title has to be short.\n */\n\n// A task title is capped at 255 by the CRM, but a readable one is far shorter.\n// Longer captures keep their first line as the title and the whole text as the\n// description, so nothing the customer wrote is thrown away.\nconst TITLE_LIMIT = 120;\n\nconst splitCapture = (raw: string) => {\n  const text = raw.trim().replace(/\\s+/g, ' ');\n  if(text.length <= TITLE_LIMIT) return {title: text, description: ''};\n\n  // Prefer breaking on a word so the title does not end mid-word.\n  const cut = text.lastIndexOf(' ', TITLE_LIMIT);\n  return {\n    title: text.slice(0, cut > 40 ? cut : TITLE_LIMIT) + '…',\n    description: raw.trim()\n  };\n};\n\n// Prefer the CRM's own message (\"Some of the chosen assignees cannot access this\n// project.\") over a generic string, matching projectTasks/agentMetrics.\nconst showCrmError = (err: any) => {\n  const message = typeof err?.message === 'string' && !err.message.startsWith('CRM_') ? err.message : '';\n  if(message) toast(message);\n  else toastNew({langPackKey: 'Tasks.CreateFailed'});\n};\n\nexport type CrmTaskSourceProps = {\n  // The customer's chat. Provenance is attached only for user peers — the CRM\n  // resolves a customer by telegram chat id, which a channel/group id is not.\n  peerId?: PeerId,\n  mid?: number\n};\n\nexport default function showCrmCreateTaskPopup(props: CrmTaskSourceProps & {\n  // Prefilled title. Empty when composing from scratch in the tasks panel.\n  text?: string,\n  // Lets the caller refresh its own list; the popup owns no list of its own.\n  onCreated?: () => void\n}) {\n  const managers = rootScope.managers;\n  const initial = splitCapture(props.text || '');\n  const sourcePeerId = props.peerId?.isUser() ? props.peerId : undefined;\n\n  createPopup(() => {\n    const [projectId, setProjectId] = createSignal<number>();\n    const [selected, setSelected] = createSignal<Set<number>>(new Set());\n    const [busy, setBusy] = createSignal(false);\n\n    const [projects] = createResource(() => managers.appCrmManager.getProjects());\n\n    // Must be declared before the members resource below: createResource calls\n    // its source immediately, so referencing this later would hit the temporal\n    // dead zone and the picker would silently stay empty.\n    const resolvedProjectId = () => projectId() ?? projects()?.[0]?.id;\n\n    // Assignability is per project (see MobileProjectController::members), so the\n    // list reloads whenever the project changes — picking someone who cannot see\n    // the project is rejected by the CRM, not silently accepted. An undefined id\n    // (projects still loading) correctly skips the fetch and re-runs once they\n    // land, since createResource ignores a falsy source.\n    const [members] = createResource(\n      () => resolvedProjectId(),\n      (id: number) => managers.appCrmManager.getProjectMembers(id)\n    );\n\n    // Default to \"mine\": a task with nobody on it is invisible work. The server\n    // applies the same default, but preselecting makes it visible that handing\n    // the task to someone else means UNCHECKING yourself.\n    createEffect(on(members, (list) => {\n      if(!list) return;\n      const me = list.find((member) => member.is_me);\n      setSelected(new Set(me ? [me.id] : []));\n    }));\n\n    const toggle = (member: CrmProjectMember, checked: boolean) => {\n      const next = new Set(selected());\n      checked ? next.add(member.id) : next.delete(member.id);\n      setSelected(next);\n    };\n\n    const titleField = new InputField({\n      label: 'Tasks.NewTitle',\n      name: 'crm-task-title',\n      plainText: true,\n      maxLength: 255\n    });\n    titleField.setValueSilently(initial.title);\n\n    const [description, setDescription] = createSignal(initial.description);\n\n    const submit = async() => {\n      const title = titleField.value.trim();\n      const project = resolvedProjectId();\n\n      if(!project || !title) {\n        toastNew({langPackKey: 'Tasks.FillFields'});\n        return false;\n      }\n\n      setBusy(true);\n      try {\n        await managers.appCrmManager.createTask({\n          project_id: project,\n          title,\n          description: description().trim() || undefined,\n          assignee_user_ids: selected().size ? Array.from(selected()) : undefined,\n          source_peer_chat_id: sourcePeerId ? '' + sourcePeerId.toUserId() : undefined,\n          // Server message ids are what the CRM stores everywhere else\n          // (attributions, first-seen), so the coordinate matches those tables.\n          source_message_id: sourcePeerId && props.mid ? getServerMessageId(props.mid) : undefined\n        });\n        toastNew({langPackKey: 'Tasks.Created'});\n        props.onCreated?.();\n      } catch(err) {\n        showCrmError(err);\n        setBusy(false);\n        return false; // keep the popup open so the input is not lost\n      }\n\n      return true;\n    };\n\n    return (\n      <PopupElement class={styles.popup} containerClass={styles.container} show>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title><I18nTsx key=\"Tasks.New\" /></PopupElement.Title>\n        </PopupElement.Header>\n\n        <PopupElement.Body class={styles.body}>\n          <Show when={sourcePeerId}>\n            <div class={styles.customer}>\n              <span class={styles.label}>{i18n('Tasks.ForCustomer')}</span>\n              <PeerTitleTsx peerId={sourcePeerId} />\n            </div>\n          </Show>\n\n          <Show\n            when={projects()?.length}\n            fallback={<div class={styles.empty}>{i18n('Tasks.NoProjects')}</div>}\n          >\n            <Show when={projects().length > 1}>\n              <select\n                class={styles.select}\n                onChange={(e) => setProjectId(+e.currentTarget.value)}\n              >\n                <For each={projects()}>\n                  {(project: CrmProject) => <option value={project.id}>{project.name}</option>}\n                </For>\n              </select>\n            </Show>\n\n            {titleField.container}\n\n            <textarea\n              class={styles.textarea}\n              rows={3}\n              placeholder={I18n.format('Tasks.Details', true)}\n              value={description()}\n              onInput={(e) => setDescription(e.currentTarget.value)}\n            />\n\n            <div class={styles.label}>{i18n('Tasks.AssignTo')}</div>\n            <Show\n              when={members()?.length}\n              fallback={<div class={styles.empty}>{i18n('Tasks.NoMembers')}</div>}\n            >\n              <Scrollable class={styles.members}>\n                <For each={members()}>\n                  {(member: CrmProjectMember) => (\n                    <Row>\n                      <Row.CheckboxField>\n                        <CheckboxFieldTsx\n                          checked={selected().has(member.id)}\n                          onChange={(checked) => toggle(member, checked)}\n                        />\n                      </Row.CheckboxField>\n                      <Row.Title>{member.name}</Row.Title>\n                    </Row>\n                  )}\n                </For>\n              </Scrollable>\n            </Show>\n          </Show>\n        </PopupElement.Body>\n\n        <PopupElement.Buttons>\n          <PopupElement.FooterButton langKey=\"Cancel\" color=\"secondary\" cancel />\n          <PopupElement.FooterButton\n            langKey=\"Tasks.Add\"\n            disabled={busy() || !projects()?.length}\n            callback={submit}\n          />\n        </PopupElement.Buttons>\n      </PopupElement>\n    );\n  });\n}\n","import rootScope from '@lib/rootScope';\nimport {toastNew} from '@components/toast';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport appImManager from '@lib/appImManager';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {AppProjectTasksTab} from '@components/solidJsTabs/tabs';\nimport showCrmCreateTaskPopup, {CrmTaskSourceProps} from '@components/popups/crmCreateTask';\n\n/**\n * Capture a CRM task from inside a conversation — the \"/task <title>\" command in\n * the message input, and the \"create task\" entry in a message's context menu.\n *\n * The composer popup does the rest: which project, who it goes to (the agent who\n * triggered it by default, but any project member can be picked), and the\n * customer the message came from, which the CRM resolves from the chat id.\n */\n\n/**\n * Open the My Tasks panel.\n *\n * On mobile the left column sits BEHIND the open chat, so creating the tab alone\n * leaves it invisible until the user presses back. Closing the current chat\n * first is what actually reveals it — on desktop both columns are visible, so\n * closing the chat there would be destructive for no gain.\n */\nexport function openCrmTasksTab() {\n  if(mediaSizes.isMobile) {\n    appImManager.setPeer(); // closes the chat, revealing the left column\n  }\n\n  appSidebarLeft.createTab(AppProjectTasksTab).open();\n}\n\nexport default async function createCrmTaskFromText(rawTitle: string, source: CrmTaskSourceProps = {}) {\n  const title = rawTitle.trim();\n  if(!title) {\n    openCrmTasksTab();\n    return;\n  }\n\n  if(!(await rootScope.managers.appCrmManager.isConnected())) {\n    toastNew({langPackKey: 'Tasks.NotConnected'});\n    return;\n  }\n\n  showCrmCreateTaskPopup({...source, text: title});\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\n\n// UI-side mirror of the worker's open-ticket peer set (AppCrmManager keeps the\n// authoritative copy). It exists because `AutonomousDialogList.testDialogForFilter`\n// must answer SYNCHRONOUSLY — every manager call is an async worker proxy, so\n// asking `appCrmManager.hasOpenTicketForPeer()` there returns a Promise, which is\n// always truthy and silently lets every private chat into the Open Tickets folder.\n//\n// Kept fresh by the same two events the folder badge listens to, plus a direct\n// seed from the folder's dialogsFetcher (the fetcher's manager call resolves\n// before its `crm_open_tickets_update` reaches the UI thread, so seeding from\n// the result closes that gap instead of racing it).\nconst [openTicketPeerIds, setOpenTicketPeerIds] = createRoot(() => createSignal<ReadonlySet<PeerId>>(new Set()));\n\nexport function setCrmOpenTicketPeerIds(peerIds: PeerId[]) {\n  setOpenTicketPeerIds(new Set(peerIds));\n}\n\nexport function hasCrmOpenTicket(peerId: PeerId) {\n  return openTicketPeerIds().has(peerId);\n}\n\nrootScope.addEventListener('crm_open_tickets_update', ({peerIds}) => {\n  setCrmOpenTicketPeerIds(peerIds);\n});\n\nrootScope.addEventListener('crm_ticket_update', ({peerId, ticket}) => {\n  const isOpen = ticket?.status === 'open';\n  if(isOpen === openTicketPeerIds().has(peerId)) {\n    return;\n  }\n\n  const set = new Set(openTicketPeerIds());\n  isOpen ? set.add(peerId) : set.delete(peerId);\n  setOpenTicketPeerIds(set);\n});\n\n// A dropped CRM session must not leave a stale set behind — the folder is empty\n// for a signed-out agent anyway.\nrootScope.addEventListener('crm_auth_required', () => {\n  setOpenTicketPeerIds(new Set<PeerId>());\n});\n\nexport default function useCrmOpenTicketPeerIds() {\n  return openTicketPeerIds;\n}\n","import {DraftMessage} from '@layer';\nimport mergeEntities from '@lib/richTextProcessor/mergeEntities';\nimport parseEntities from '@lib/richTextProcessor/parseEntities';\nimport wrapDraftText from '@lib/richTextProcessor/wrapDraftText';\n\nexport default function wrapDraft(\n  draft: DraftMessage.draftMessage,\n  options?: Parameters<typeof wrapDraftText>[1]\n) {\n  const myEntities = parseEntities(draft.message);\n  const apiEntities = draft.entities || [];\n  const totalEntities = mergeEntities(apiEntities, myEntities); // ! only in this order, otherwise bold and emoji formatting won't work\n\n  return wrapDraftText(draft.message, {...options, entities: totalEntities});\n}\n","import indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport callbackify from '@helpers/callbackify';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport liteMode from '@helpers/liteMode';\nimport {getMiddleware} from '@helpers/middleware';\nimport {modifyAckedPromise} from '@helpers/modifyAckedResult';\nimport namedPromises from '@helpers/namedPromises';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {Chat} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {i18n} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {AckedResult} from '@lib/superMessagePort';\nimport rootScope from '@lib/rootScope';\nimport {avatarNew} from '@components/avatarNew';\nimport {ButtonMenuItemOptions, ButtonMenuSync} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport Icon from '@components/icon';\nimport PeerTitle from '@components/peerTitle';\nimport PopupPremium from '@components/popups/premium';\nimport SetTransition from '@components/singleTransition';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\n\nconst SEND_AS_ANIMATION_DURATION = 300;\n\nexport interface ChatSendAsOptions {\n  managers: AppManagers;\n  onReady: (container: HTMLElement, skipAnimation?: boolean) => void,\n  onChange: (sendAsPeerId: PeerId) => void\n  forPaidReaction?: boolean,\n  menuContainer?: HTMLElement\n  defaultPeerId?: PeerId\n}\n\nexport default class ChatSendAs {\n  private avatar: ReturnType<typeof avatarNew>;\n  private container: HTMLElement;\n  private closeBtn: HTMLElement;\n  private btnMenu: HTMLElement;\n  private sendAsPeers: {peerId: PeerId, needPremium?: boolean}[];\n  private sendAsPeerId: PeerId;\n  private updatingPromise: ReturnType<ChatSendAs['updateManual']>;\n  private middlewareHelper: ReturnType<typeof getMiddleware>;\n  private listenerSetter: ListenerSetter;\n  private peerId: PeerId;\n  private addedListener: boolean;\n  private buttons: ButtonMenuItemOptions[];\n\n  private managers: ChatSendAsOptions['managers'];\n  private onReady: ChatSendAsOptions['onReady'];\n  private onChange: ChatSendAsOptions['onChange'];\n  private forPaidReaction: ChatSendAsOptions['forPaidReaction'];\n  private menuContainer: ChatSendAsOptions['menuContainer'];\n  private defaultPeerId: ChatSendAsOptions['defaultPeerId'];\n\n  constructor(options: ChatSendAsOptions) {\n    safeAssign(this, options);\n    this.middlewareHelper = getMiddleware();\n    this.listenerSetter = new ListenerSetter();\n    this.construct();\n  }\n\n  private construct() {\n    this.container = document.createElement('div');\n    this.container.classList.add('new-message-send-as-container');\n\n    this.closeBtn = document.createElement('div');\n    this.closeBtn.classList.add('new-message-send-as-close', 'new-message-send-as-avatar');\n    this.closeBtn.append(Icon('close'));\n\n    const sendAsButtons: ButtonMenuItemOptions[] = [{\n      text: this.forPaidReaction ? 'SendReactionAsTitle' : 'SendMessageAsTitle',\n      onClick: undefined\n    }];\n\n    this.buttons = [];\n\n    let previousAvatar: ChatSendAs['avatar'];\n    const onSendAsMenuToggle = (visible: boolean) => {\n      if(this.forPaidReaction) {\n        return;\n      }\n      if(visible) {\n        previousAvatar = this.avatar;\n      }\n\n      const isChanged = this.avatar !== previousAvatar;\n      const useRafs = !visible && isChanged ? 2 : 0;\n\n      SetTransition({\n        element: this.closeBtn,\n        className: 'is-visible',\n        forwards: visible,\n        duration: SEND_AS_ANIMATION_DURATION,\n        useRafs\n      });\n      if(!isChanged) {\n        SetTransition({\n          element: previousAvatar.node,\n          className: 'is-visible',\n          forwards: !visible,\n          duration: SEND_AS_ANIMATION_DURATION,\n          useRafs\n        });\n      }\n    };\n\n    ButtonMenuToggle({\n      buttonOptions: {noRipple: true},\n      listenerSetter: this.listenerSetter,\n      container: this.menuContainer ?? this.container,\n      direction: this.forPaidReaction ? 'bottom-center' : 'top-right',\n      buttons: sendAsButtons,\n      onOpenBefore: () => {\n        onSendAsMenuToggle(true);\n      },\n      onOpen: (e, btnMenu) => {\n        sendAsButtons[0].element.classList.add('btn-menu-item-header');\n        this.btnMenu = btnMenu as any;\n        this.btnMenu.classList.add('scrollable', 'scrollable-y', 'new-message-send-as-menu');\n        this.btnMenu.append(...this.buttons.map((button) => button.element));\n      },\n      onClose: () => {\n        onSendAsMenuToggle(false);\n      },\n      onCloseAfter: () => {\n        this.btnMenu = undefined;\n      }\n    });\n\n    this.container.append(this.closeBtn);\n  }\n\n  private async updateButtons(peers: ChatSendAs['sendAsPeers']) {\n    const promises: Promise<ButtonMenuItemOptions>[] = peers.map(async(sendAsPeer, idx) => {\n      const textElement = document.createElement('div');\n\n      const {peerId: sendAsPeerId, needPremium} = sendAsPeer;\n\n      const subtitle = document.createElement('div');\n      subtitle.classList.add('btn-menu-item-subtitle');\n      if(sendAsPeerId.isUser()) {\n        subtitle.append(i18n('Chat.SendAs.PersonalAccount'));\n      } else if(sendAsPeerId === this.peerId && (apiManagerProxy.getPeer(this.peerId) as Chat.channel).pFlags.megagroup) {\n        subtitle.append(i18n('VoiceChat.DiscussionGroup'));\n      } else {\n        subtitle.append(await getChatMembersString(sendAsPeerId.toChatId()));\n      }\n\n      const title = document.createElement('div');\n      title.append(new PeerTitle({peerId: sendAsPeerId}).element);\n\n      if(needPremium) {\n        title.append(Icon('premium_lock', 'new-message-send-as-lock'));\n      }\n\n      textElement.append(\n        title,\n        subtitle\n      );\n\n      return {\n        onClick: idx ? async() => {\n          if(sendAsPeer.needPremium && !rootScope.premium) {\n            PopupPremium.show();\n            return;\n          }\n\n          const currentPeerId = this.peerId;\n          this.changeSendAsPeerId(sendAsPeerId);\n\n          const middleware = this.middlewareHelper.get();\n          const executeButtonsUpdate = () => {\n            if(this.sendAsPeerId !== sendAsPeerId || !middleware()) return;\n            const peers = this.sendAsPeers.slice();\n            const idx = peers.findIndex((peer) => peer.peerId === sendAsPeerId);\n            if(idx !== -1) peers.splice(idx, 1);\n            peers.unshift(sendAsPeer);\n            this.updateButtons(peers);\n          };\n\n          if(liteMode.isAvailable('animations')) {\n            setTimeout(executeButtonsUpdate, 250);\n          } else {\n            executeButtonsUpdate();\n          }\n\n          if(!this.forPaidReaction) {\n            this.managers.appMessagesManager.saveDefaultSendAs(currentPeerId, sendAsPeerId);\n          }\n        } : undefined,\n        textElement\n      };\n    });\n\n    const buttons = await Promise.all(promises);\n    const btnMenu = ButtonMenuSync({buttons}/* , this.listenerSetter */);\n    buttons.forEach((button, idx) => {\n      const {peerId} = peers[idx];\n      const avatar = avatarNew({\n        middleware: this.middlewareHelper.get(),\n        size: 26,\n        peerId\n      });\n      avatar.node.classList.add('btn-menu-item-icon', 'btn-menu-item-avatar');\n\n      if(!idx) {\n        avatar.node.classList.add('active');\n      }\n\n      button.element.prepend(avatar.node);\n    });\n\n    this.buttons = buttons;\n\n    // if already opened\n    this.btnMenu?.append(...this.buttons.map((button) => button.element));\n  }\n\n  private async updateAvatar(sendAsPeerId: PeerId, skipAnimation?: boolean) {\n    const previousAvatar = this.avatar;\n    if(previousAvatar) {\n      if(previousAvatar.node.dataset.peerId.toPeerId() === sendAsPeerId) {\n        return;\n      }\n    }\n\n    if(!previousAvatar) {\n      skipAnimation = true;\n    }\n\n    const useRafs = skipAnimation ? 0 : 2;\n    const duration = skipAnimation ? 0 : SEND_AS_ANIMATION_DURATION;\n    const avatar = this.avatar = avatarNew({\n      middleware: this.middlewareHelper.get(),\n      size: 40,\n      isDialog: false,\n      peerId: sendAsPeerId\n    });\n    avatar.node.classList.add('new-message-send-as-avatar');\n    await avatar.readyThumbPromise;\n\n    SetTransition({\n      element: avatar.node,\n      className: 'is-visible',\n      forwards: true,\n      duration,\n      useRafs\n    });\n    if(previousAvatar) {\n      SetTransition({\n        element: previousAvatar.node,\n        className: 'is-visible',\n        forwards: false,\n        duration,\n        onTransitionEnd: () => {\n          previousAvatar.node.remove();\n        },\n        useRafs\n      });\n    }\n\n    this.container.append(avatar.node);\n  }\n\n  private changeSendAsPeerId(sendAsPeerId: PeerId, skipAnimation?: boolean) {\n    this.sendAsPeerId = sendAsPeerId;\n    this.onChange(sendAsPeerId);\n    return this.updateAvatar(sendAsPeerId, skipAnimation);\n  }\n\n  private getDefaultSendAs(): Promise<AckedResult<PeerId>> {\n    if(this.forPaidReaction) {\n      return Promise.resolve({\n        cached: true,\n        result: Promise.resolve(this.defaultPeerId)\n      });\n    }\n\n    return this.managers.acknowledged.appProfileManager.getChannelFull(this.peerId.toChatId()).then((acked) => {\n      return {\n        cached: acked.cached,\n        result: acked.result.then((channelFull) => {\n          return channelFull.default_send_as ? getPeerId(channelFull.default_send_as) : undefined\n        })\n      };\n    });\n  }\n\n  public async updateManual(skipAnimation?: boolean): Promise<() => void> {\n    const peerId = this.peerId;\n\n    const {isChannel, isMonoforum} = await namedPromises({\n      isChannel: this.managers.appPeersManager.isChannel(peerId),\n      isMonoforum: this.managers.appPeersManager.isMonoforum(peerId)\n    });\n\n    if(this.updatingPromise || !isChannel || isMonoforum) {\n      return;\n    }\n\n    const middleware = this.middlewareHelper.get(() => {\n      return !this.updatingPromise || this.updatingPromise === updatingPromise;\n    });\n\n    const {container} = this;\n    const chatId = peerId.toChatId();\n    const result = (await modifyAckedPromise(this.getDefaultSendAs())).result;\n    // const result = Promise.resolve(this.getDefaultSendAs());\n\n    const wasSkippingAnimation = skipAnimation;\n    if(result instanceof Promise) {\n      skipAnimation = undefined;\n    }\n\n    const auto = wasSkippingAnimation && !skipAnimation;\n\n    const updatingPromise = this.updatingPromise = callbackify(result, async(sendAsPeerId) => {\n      if(!middleware() || sendAsPeerId === undefined) return;\n\n      await this.changeSendAsPeerId(sendAsPeerId, skipAnimation);\n      if(!middleware()) return;\n\n      Promise.all([\n        this.managers.appChatsManager.getSendAs(chatId, this.forPaidReaction),\n        apiManagerProxy.isPremiumFeaturesHidden()\n      ]).then(([sendAsPeers, isPremiumFeaturesHidden]) => {\n        if(!middleware()) return;\n\n        if(isPremiumFeaturesHidden) {\n          sendAsPeers = sendAsPeers.filter((sendAsPeer) => !sendAsPeer.pFlags.premium_required);\n        }\n\n        const peers: ChatSendAs['sendAsPeers'] = sendAsPeers.map((sendAsPeer) => {\n          return {\n            peerId: getPeerId(sendAsPeer.peer),\n            needPremium: sendAsPeer.pFlags.premium_required\n          }\n        });\n\n        const idx = peers.findIndex((peer) => peer.peerId === sendAsPeerId);\n        if(idx !== -1) {\n          const peer = peers.splice(idx, 1)[0];\n          peers.unshift(peer);\n        } else {\n          peers.unshift({peerId: sendAsPeerId});\n        }\n\n        // * save AFTER folding in the current peer — for paid reactions the personal account\n        // * isn't part of the server list and is injected above; slicing earlier dropped it from\n        // * the canonical pool, so it vanished on the first re-render triggered by a selection.\n        this.sendAsPeers = peers.slice();\n\n        this.updateButtons(peers);\n      });\n\n      const callback = () => {\n        this.onReady(container, skipAnimation);\n\n        if(!this.addedListener) {\n          this.listenerSetter.add(rootScope)('peer_full_update', (peerId) => {\n            if(this.peerId === peerId) {\n              this.update();\n            }\n          });\n\n          this.addedListener = true;\n        }\n      };\n\n      if(auto) {\n        callback();\n        return;\n      }\n\n      return callback;\n    });\n\n    updatingPromise.finally(() => {\n      if(this.updatingPromise === updatingPromise) {\n        this.updatingPromise = undefined;\n      }\n    });\n\n    if(!auto) {\n      return updatingPromise;\n    }\n  }\n\n  public update(skipAnimation?: boolean) {\n    return this.updateManual(skipAnimation).then((callback) => callback?.());\n  }\n\n  public setPeerId(peerId?: PeerId) {\n    /* if(this.avatar) {\n      this.avatar.remove();\n      this.avatar = undefined;\n    } */\n\n    this.middlewareHelper.clean();\n    this.updatingPromise = undefined;\n    this.peerId = peerId;\n  }\n\n  public getSendAsPeerId() {\n    return this.sendAsPeerId;\n  }\n\n  public destroy() {\n    this.container.remove();\n    this.setPeerId();\n    this.listenerSetter.removeAll();\n  }\n}\n","import {USING_BOMS} from '@helpers/dom/richInputHandler';\nimport BOM from '@helpers/string/bom';\nimport {_i18n} from '@lib/langPack';\nimport InputField, {InputFieldOptions} from '@components/inputField';\nimport SetTransition from '@components/singleTransition';\n\nconst USELESS_REG_EXP = new RegExp(`(<span>${BOM}</span>)|(<br\\/?>)`, 'g');\n\nexport default class InputFieldAnimated extends InputField {\n  public inputFake: HTMLElement;\n  public onChangeHeight: (height: number) => void;\n  // Owned by the consumer via setMaxHeight(). Single source of truth: the\n  // same number drives both `input.style.maxHeight` and the scrollHeight\n  // clamp in onFakeInput(), so the height we report upstream (e.g. via\n  // `--chat-input-height-surplus`) matches the visible input.\n  private maxHeight: number | undefined;\n\n  // public onLengthChange: (length: number, isOverflow: boolean) => void;\n  // protected wasInputFakeClientHeight: number;\n  // protected showScrollDebounced: () => void;\n\n  constructor(options?: InputFieldOptions) {\n    super(options);\n\n    this.input.addEventListener('input', () => {\n      this.updateInnerHTML();\n      this.onFakeInput();\n    });\n\n    // if(options.placeholder) {\n    //   _i18n(this.inputFake, options.placeholder, undefined, 'placeholder');\n    // }\n\n    this.input.classList.add('scrollable', 'scrollable-y', 'no-scrollbar');\n    // this.wasInputFakeClientHeight = 0;\n    // this.showScrollDebounced = debounce(() => this.input.classList.remove('no-scrollbar'), 150, false, true);\n    this.inputFake = document.createElement('div');\n    // this.inputFake.contentEditable = 'true';\n    this.inputFake.contentEditable = 'true';\n    this.inputFake.tabIndex = -1;\n    this.inputFake.className = this.input.className + ' input-field-input-fake';\n  }\n\n  public setMaxHeight(value: number | undefined) {\n    if(this.maxHeight === value) return;\n    this.maxHeight = value;\n    this.input.style.maxHeight = value !== undefined ? value + 'px' : '';\n    this.onFakeInput();\n  }\n\n  public onFakeInput(setHeight = true, noAnimation?: boolean) {\n    const {scrollHeight} = this.inputFake;\n    const newHeight = this.maxHeight !== undefined ? Math.min(scrollHeight, this.maxHeight) : scrollHeight;\n\n    noAnimation ??= !this.input.isContentEditable;\n\n    const currentHeight = +this.input.style.height.replace('px', '');\n    if(currentHeight === newHeight) {\n      return;\n    }\n\n    const TRANSITION_DURATION_FACTOR = 50;\n    const transitionDuration = noAnimation ? 0 : Math.round(\n      TRANSITION_DURATION_FACTOR * Math.log(Math.abs(newHeight - currentHeight))\n    );\n\n    // this.wasInputFakeClientHeight = clientHeight;\n    this.input.style.transitionDuration = `${transitionDuration}ms`;\n\n    if(setHeight) {\n      this.onChangeHeight?.(newHeight);\n      this.input.style.height = newHeight ? newHeight + 'px' : '';\n      (this.input as any).oldHeight = (this.input as any).newHeight;\n      (this.input as any).newHeight = newHeight;\n\n      Array.from(this.input.querySelectorAll('.quote-like')).forEach((element) => {\n        const scrollHeight = element.scrollHeight;\n        const computedStyle = getComputedStyle(element);\n        const lineHeight = parseFloat(computedStyle.lineHeight);\n        const paddingTop = parseFloat(computedStyle.paddingTop);\n        const paddingBottom = parseFloat(computedStyle.paddingBottom);\n        const lines = (scrollHeight - paddingTop - paddingBottom) / lineHeight;\n        element.classList.toggle('can-send-collapsed', lines > 3);\n      });\n    }\n\n    const className = 'is-changing-height';\n    SetTransition({\n      element: this.input,\n      className,\n      forwards: true,\n      duration: transitionDuration,\n      onTransitionEnd: () => {\n        this.input.classList.remove(className);\n        (this.input as any).oldHeight = (this.input as any).newHeight;\n      }\n    });\n  }\n\n  protected updateInnerHTML(innerHTML = this.input.innerHTML) {\n    innerHTML = innerHTML\n    .replace(/<custom-emoji-renderer-element.+\\/custom-emoji-renderer-element>/, '')\n    .replace(/(<custom-emoji-element.+?>).+?\\/custom-emoji-element>/g, '$1</custom-emoji-element>');\n\n    if(USING_BOMS) {\n      innerHTML = innerHTML.replace(USELESS_REG_EXP, '');\n    }\n\n    this.inputFake.innerHTML = innerHTML;\n  }\n\n  public setValueSilently(value: Parameters<InputField['setValueSilently']>[0], fromSet?: boolean) {\n    super.setValueSilently(value, fromSet);\n\n    this.updateInnerHTML();\n    if(!fromSet) {\n      this.onFakeInput();\n    }\n  }\n}\n","import {getRgbColorFromTelegramColor, rgbIntToHex} from '@helpers/color';\nimport themeController from '@helpers/themeController';\nimport {PeerColor} from '@layer';\nimport {getPeerColorsByPeer, makeColorsGradient, getPeerColorIndexByPeer} from '@appManagers/utils/peers/getPeerColorById';\nimport apiManagerProxy from '@lib/apiManagerProxy';\n\nexport function setPeerColorToElement({\n  peerId,\n  element,\n  messageHighlighting,\n  colorAsOut,\n  color\n}: {\n  peerId: PeerId,\n  element: HTMLElement,\n  messageHighlighting?: boolean,\n  colorAsOut?: boolean,\n  color?: PeerColor\n}) {\n  const colorProperty = '--peer-color-rgb';\n  const borderBackgroundProperty = '--peer-border-background';\n  // if(!peerId) {\n  //   element.style.removeProperty(colorProperty);\n  //   element.style.removeProperty(borderBackgroundProperty);\n  //   return;\n  // }\n\n  const peer = apiManagerProxy.getPeer(peerId);\n  if(!color && peer?._ === 'user') color = peer.color\n\n  let peerColorRgbValue: string, peerBorderBackgroundValue: string;\n  if(messageHighlighting || colorAsOut) {\n    const colors = getPeerColorsByPeer(peer);\n    const length = colors.length;\n    const property = messageHighlighting ? 'message-empty' : 'message-out';\n    peerColorRgbValue = `var(--${property}-primary-color-rgb)`;\n    peerBorderBackgroundValue = `var(--${property}-peer-${Math.max(1, length)}-border-background)`;\n  } else if(color?._ === 'peerColorCollectible') {\n    let colors = color.colors\n    let accentColor = color.accent_color\n    if(themeController.isNight()) {\n      if(color.dark_accent_color) accentColor = color.dark_accent_color\n      if(color.dark_colors) colors = color.dark_colors\n    }\n\n    peerColorRgbValue = getRgbColorFromTelegramColor(accentColor).join(', ')\n    peerBorderBackgroundValue = makeColorsGradient(colors.map(it => rgbIntToHex(it)))\n  } else {\n    const colorIndex = (color as PeerColor.peerColor)?.color ?? getPeerColorIndexByPeer(peer);\n    if(colorIndex === -1) {\n      element.style.removeProperty(colorProperty);\n      element.style.removeProperty(borderBackgroundProperty);\n      return;\n    }\n\n    peerColorRgbValue = `var(--peer-${colorIndex}-color-rgb)`;\n    peerBorderBackgroundValue = `var(--peer-${colorIndex}-border-background)`;\n  }\n\n  element.style.setProperty(colorProperty, peerColorRgbValue);\n  element.style.setProperty(borderBackgroundProperty, peerBorderBackgroundValue);\n}\n","import {rgbIntToHex} from '@helpers/color';\nimport type {PeerColor} from '@layer';\n\nexport type PeerColorLike = PeerColor.peerColor | PeerColor.peerColorCollectible;\n\n// * pure: pick the tint for the peer-color background-emoji pattern (replies/quotes/web pages)\nexport default function pickPatternEmojiColor(color: PeerColorLike, isNight: boolean, peerGradientColors: string[]) {\n  if(color?._ === 'peerColorCollectible') {\n    const val = isNight && color.dark_accent_color ? color.dark_accent_color : color.accent_color;\n    return rgbIntToHex(val);\n  }\n\n  return peerGradientColors[0];\n}\n","import themeController from '@helpers/themeController';\nimport {Middleware} from '@helpers/middleware';\nimport pickPatternEmojiColor, {PeerColorLike} from '@helpers/pickPatternEmojiColor';\nimport {Chat, User} from '@layer';\nimport {getPeerColorsByPeer} from '@appManagers/utils/peers/getPeerColorById';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport wrapEmojiPattern from '@components/wrappers/emojiPattern';\nimport wrapSticker from '@components/wrappers/sticker';\n\nexport type {PeerColorLike};\nexport {pickPatternEmojiColor};\n\n// * Background-emoji pattern geometry, ported 1:1 from tdesktop's FillBackgroundEmoji\n// * (Telegram/SourceFiles/history/view/history_view_reply.cpp:267 — the non-quote variant,\n// * shared there by replies, contacts AND web pages). tdesktop renders three cached emoji\n// * frame sizes (kSize1/2/3 = 12/16/20, reply.cpp:237-239) and lays out 9 instances, each\n// * anchored from the box's RIGHT edge (reply.cpp:296-310). Tuple = [distanceFromRight, top, sizeIndex, opacity].\nconst TDESKTOP_PATTERN_SIZES = [12, 16, 20];\nconst TDESKTOP_PATTERN: [xFromRight: number, y: number, sizeIndex: number, alpha: number][] = [\n  [28, 4, 2, .32],\n  [51, 15, 1, .32],\n  [64, -2, 0, .28],\n  [87, 11, 1, .24],\n  [125, -2, 2, .16],\n  [28, 31, 1, .24],\n  [72, 33, 2, .2],\n  [46, 52, 1, .24],\n  [24, 55, 2, .18]\n];\n\n// * The canvas is pinned to the box's right edge (CSS inset-inline-end: 0), so a right-anchored\n// * tdesktop x maps to a left-origin x of `width - distanceFromRight`. Width seats the leftmost\n// * emoji (125); height covers the lowest (55 + 20). The quote-like box's overflow:hidden then\n// * clips it to the real reply/webpage height — mirroring tdesktop's `if(y >= rect.height()) return`.\nexport const PEER_COLOR_PATTERN_CANVAS_WIDTH = 130;\nexport const PEER_COLOR_PATTERN_CANVAS_HEIGHT = 76;\nexport const PEER_COLOR_PATTERN_EMOJI_SIZE = 24; // source raster >= the largest draw size (20)\nexport const PEER_COLOR_PATTERN_POSITIONS: [x: number, y: number, size: number, alpha: number][] =\n  TDESKTOP_PATTERN.map(([xFromRight, y, sizeIndex, alpha]): [number, number, number, number] =>\n    [PEER_COLOR_PATTERN_CANVAS_WIDTH - xFromRight, y, TDESKTOP_PATTERN_SIZES[sizeIndex], alpha]);\n\nexport type WrapPeerColorPatternOptions = {\n  peerId: PeerId,\n  container: HTMLElement,\n  middleware?: Middleware,\n  colorAsOut?: boolean,\n  useHighlightingColor?: boolean,\n  positions?: [x: number, y: number, size: number, alpha: number][],\n  canvasWidth?: number,\n  canvasHeight?: number,\n  emojiSize?: number,\n  canvasClassName?: string,\n  withCollectible?: boolean\n};\n\n// * shared peer-color background-emoji pattern (replies, quotes, contacts, web pages)\nexport default function wrapPeerColorPattern(options: WrapPeerColorPatternOptions) {\n  const {peerId, container, middleware} = options;\n  const peer = apiManagerProxy.getPeer(peerId);\n  const color = (peer as User.user)?.color as PeerColorLike;\n  const docId = color?.background_emoji_id;\n  if(docId) {\n    const emojiColor = pickPatternEmojiColor(color, themeController.isNight(), getPeerColorsByPeer(peer as Chat | User));\n\n    wrapEmojiPattern({\n      docId,\n      container,\n      middleware,\n      color: emojiColor,\n      colorAsOut: options.colorAsOut,\n      useHighlightingColor: options.useHighlightingColor,\n      positions: options.positions || PEER_COLOR_PATTERN_POSITIONS,\n      canvasWidth: options.canvasWidth || PEER_COLOR_PATTERN_CANVAS_WIDTH,\n      canvasHeight: options.canvasHeight || PEER_COLOR_PATTERN_CANVAS_HEIGHT,\n      emojiSize: options.emojiSize || PEER_COLOR_PATTERN_EMOJI_SIZE\n    }).then((canvas) => {\n      if(middleware && !middleware()) return;\n      if(options.canvasClassName) canvas.classList.add(options.canvasClassName);\n    });\n  }\n\n  if(options.withCollectible && color?._ === 'peerColorCollectible') {\n    const div = document.createElement('div');\n    div.classList.add('reply-collectible');\n    container.classList.add('has-collectible');\n    container.appendChild(div);\n\n    rootScope.managers.appEmojiManager.getCustomEmojiDocument(color.gift_emoji_id).then((doc) => {\n      if(middleware && !middleware()) return;\n      if(!doc) return;\n\n      return wrapSticker({\n        doc,\n        div,\n        middleware,\n        width: 24,\n        height: 24\n      });\n    });\n  }\n}\n","import {setDirection} from '@helpers/dom/setInnerHTML';\nimport {Message, MessageEntity, MessageReplyHeader, StoryItem} from '@layer';\nimport ReplyContainer from '@components/chat/replyContainer';\nimport {setPeerColorToElement} from '@components/peerColors';\nimport ripple from '@components/ripple';\nimport wrapPeerColorPattern from '@components/wrappers/peerColorPattern';\n\nexport type WrapPinnedContainerOptions = {\n  title: string | HTMLElement | DocumentFragment,\n  subtitle?: WrapPinnedContainerOptions['title'],\n  message?: Message.message | Message.messageService,\n  storyItem?: StoryItem.storyItem,\n  isChatSensitive?: boolean,\n  savedMusicDocId?: DocId\n};\n\nexport type WrapReplyOptions = WrapPinnedContainerOptions & {\n  setColorPeerId?: PeerId,\n  useHighlightingColor?: boolean,\n  colorAsOut?: boolean,\n  isStoryExpired?: boolean,\n  isQuote?: boolean,\n  noBorder?: boolean,\n  replyHeader?: MessageReplyHeader,\n  quote?: {text: string, entities?: MessageEntity[]},\n  canTranslate?: boolean\n} & WrapSomethingOptions;\n\nexport default function wrapReply(options: WrapReplyOptions) {\n  const replyContainer = new ReplyContainer('reply');\n  const fillPromise = replyContainer.fill(options);\n\n  replyContainer.container.classList.add('quote-like', 'quote-like-hoverable', 'quote-like-border');\n  setDirection(replyContainer.container);\n  // replyContainer.border.classList.add('quote-like-border');\n  replyContainer.border.remove();\n  ripple(replyContainer.container);\n\n  if(options.isQuote) {\n    replyContainer.container.classList.add('quote-like-icon');\n    replyContainer.container.classList.add('reply-multiline');\n  }\n\n  if(options.noBorder) {\n    replyContainer.container.classList.remove('quote-like-border');\n  }\n\n  const {setColorPeerId} = options;\n  if(setColorPeerId !== undefined) {\n    setPeerColorToElement({\n      peerId: setColorPeerId,\n      element: replyContainer.container,\n      messageHighlighting: options.useHighlightingColor,\n      colorAsOut: options.colorAsOut\n    });\n\n    wrapPeerColorPattern({\n      peerId: setColorPeerId,\n      container: replyContainer.container,\n      middleware: options.middleware,\n      colorAsOut: options.colorAsOut,\n      useHighlightingColor: options.useHighlightingColor,\n      canvasClassName: 'reply-background-canvas',\n      withCollectible: true\n    });\n  }\n\n  if(!options.subtitle && !options.message) {\n    replyContainer.container.classList.add('reply-no-subtitle');\n    replyContainer.subtitle.remove();\n  }\n\n  return {container: replyContainer.container, fillPromise};\n}\n","import replaceContent from '@helpers/dom/replaceContent';\n\nexport default function setBadgeContent(badge: HTMLElement, content: Parameters<typeof replaceContent>[1]) {\n  replaceContent(badge, content);\n  badge.classList.toggle('is-badge-empty', !content);\n}\n","import {Message} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport ripple from '@components/ripple';\nimport I18n from '@lib/langPack';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport StackedAvatars from '@components/stackedAvatars';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {AppManagers} from '@lib/managers';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport type LazyLoadQueue from '@components/lazyLoadQueue';\nimport {MiddlewareHelper} from '@helpers/middleware';\nimport {_tgico} from '@helpers/tgico';\nimport Icon from '@components/icon';\n\nconst TAG_NAME = 'replies-element';\n\nrootScope.addEventListener('replies_updated', (message) => {\n  (Array.from(document.querySelectorAll(TAG_NAME + `[data-post-key=\"${message.peerId}_${message.mid}\"]`)) as RepliesElement[]).forEach((element) => {\n    element.message = message;\n    element.render();\n  });\n});\n\nexport default class RepliesElement extends HTMLElement {\n  public message: Message.message;\n  public type: 'footer' | 'beside';\n  public loadPromises: Promise<any>[];\n  public lazyLoadQueue: LazyLoadQueue;\n  public stackedAvatars: StackedAvatars;\n  public text: I18n.IntlElement;\n  public managers: AppManagers;\n  public middlewareHelper: MiddlewareHelper;\n\n  private updated = false;\n\n  constructor() {\n    super();\n    this.managers = rootScope.managers;\n  }\n\n  public init() {\n    this.render();\n    this.dataset.postKey = this.message.peerId + '_' + this.message.mid;\n    this.classList.add('replies', 'replies-' + this.type);\n  }\n\n  public render() {\n    const replies = this.message.replies;\n\n    if(this.type === 'footer') {\n      let leftPart: HTMLElement;\n      if(this.firstElementChild) {\n        leftPart = this.firstElementChild as HTMLElement;\n      }\n\n      if(replies?.recent_repliers) {\n        if(leftPart && !leftPart.classList.contains('replies-footer-avatars')) {\n          this.replaceChildren();\n          leftPart = null;\n        }\n\n        if(!this.stackedAvatars) {\n          this.stackedAvatars = new StackedAvatars({\n            lazyLoadQueue: this.lazyLoadQueue,\n            avatarSize: 30,\n            middleware: this.middlewareHelper.get()\n          });\n\n          this.stackedAvatars.container.classList.add('replies-footer-avatars');\n        }\n\n        leftPart = this.stackedAvatars.container;\n\n        this.stackedAvatars.render(replies.recent_repliers.map((peer) => getPeerId(peer)), this.loadPromises);\n      } else {\n        if(leftPart && !leftPart.classList.contains(_tgico('comments'))) {\n          leftPart.remove();\n          leftPart = null;\n        }\n\n        if(!leftPart) {\n          leftPart = Icon('comments', 'replies-footer-icon', 'replies-footer-icon-comments');\n        }\n      }\n\n      if(!leftPart.parentElement) {\n        this.prepend(leftPart);\n      }\n\n      if(!this.text) {\n        this.text = new I18n.IntlElement();\n      }\n\n      const text = this.text;\n      if(replies) {\n        if(replies.replies) {\n          text.compareAndUpdate({key: 'Comments', args: [replies.replies]});\n        } else {\n          text.compareAndUpdate({key: 'LeaveAComment'});\n        }\n      } else {\n        text.compareAndUpdate({key: 'ViewInChat'});\n      }\n\n      if(replies) {\n        // const historyStorage = appMessagesManager.getHistoryStorage(replies.channel_id.toPeerId(true));\n        let isUnread = false;\n        if(replies.replies) {\n          if(replies.read_max_id !== undefined && replies.max_id !== undefined) {\n            isUnread = replies.read_max_id < replies.max_id;\n          }/*  else {\n            isUnread = !historyStorage.readMaxId || historyStorage.readMaxId < (replies.max_id || 0);\n          } */\n        }\n        this.classList.toggle('is-unread', isUnread);\n      }\n\n      let textSpan = this.children[1] as HTMLElement;\n      if(!textSpan) {\n        textSpan = document.createElement('span');\n        textSpan.classList.add('replies-footer-text');\n\n        const iconSpan = Icon('next', 'replies-footer-icon', 'replies-footer-icon-next');\n\n        const rippleContainer = document.createElement('div');\n        ripple(rippleContainer);\n\n        this.append(textSpan, iconSpan, rippleContainer);\n      }\n\n      replaceContent(textSpan, text.element);\n    } else {\n      this.classList.add('bubble-beside-button');\n      this.innerHTML = `<span class=\"replies-beside-text\">${replies?.replies ? formatNumber(replies.replies, 0) : ''}</span>`;\n      this.prepend(Icon('commentssticker'));\n    }\n\n    if(replies && !this.updated && !this.message.pFlags.is_outgoing) {\n      this.managers.appMessagesManager.subscribeRepliesThread(this.message.peerId, this.message.mid);\n      this.managers.appMessagesManager.updateMessage(this.message.peerId, this.message.mid, 'replies_updated');\n      this.updated = true;\n    }\n\n    if(this.loadPromises) {\n      this.loadPromises = undefined;\n    }\n  }\n}\n\nif(!customElements.get(TAG_NAME)) {\n  customElements.define(TAG_NAME, RepliesElement);\n}\n","import type LazyLoadQueue from '@components/lazyLoadQueue';\nimport {formatFullSentTimeRaw, formatTime} from '@helpers/date';\nimport {getFullDate} from '@helpers/date/getFullDate';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {Middleware} from '@helpers/middleware';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {AvailableEffect, Message, MessageReplyHeader} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {i18n, _i18n, LangPackKey} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport Icon from '@components/icon';\nimport PeerTitle from '@components/peerTitle';\nimport wrapReply from '@components/wrappers/reply';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from './chatType';\nimport RepliesElement from '@components/chat/replies';\nimport ChatBubbles from '@components/chat/bubbles';\nimport getFwdFromName from '@appManagers/utils/messages/getFwdFromName';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport wrapSticker from '@components/wrappers/sticker';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport getStickerEffectThumb from '@appManagers/utils/stickers/getStickerEffectThumb';\nimport wrapStickerAnimation from '@components/wrappers/stickerAnimation';\nimport Scrollable from '@components/scrollable';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport numberThousandSplitter, {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport {makeTime} from '@components/chat/utils';\nimport {formatNanoton} from '@helpers/paymentsWrapCurrencyAmount';\n\nconst NBSP = '&nbsp;';\n\nconst DAY = 86400;\nconst SCHEDULE_REPEAT_MAP: {period: number, key: LangPackKey, args?: any[]}[] = [\n  {period: DAY, key: 'Schedule.Repeated.Daily'},\n  {period: 7 * DAY, key: 'Schedule.Repeated.Weekly'},\n  {period: 14 * DAY, key: 'Schedule.Repeated.Biweekly'},\n  {period: 30 * DAY, key: 'Schedule.Repeated.Monthly'},\n  {period: 91 * DAY, key: 'Schedule.Repeated.EveryMonth', args: [3]},\n  {period: 182 * DAY, key: 'Schedule.Repeated.EveryMonth', args: [6]},\n  {period: 365 * DAY, key: 'Schedule.Repeated.Yearly'}\n];\n\nconst makeScheduleRepeatPeriod = (period: number) => {\n  const entry = SCHEDULE_REPEAT_MAP.find((e) => e.period >= period) ?? SCHEDULE_REPEAT_MAP[SCHEDULE_REPEAT_MAP.length - 1];\n  const span = document.createElement('span');\n  span.classList.add('time-repeat', 'time-part');\n  span.append(i18n(entry.key, entry.args));\n  return span;\n};\n\nconst makeEdited = () => {\n  const edited = document.createElement('i');\n  edited.classList.add('time-edited', 'time-part');\n  _i18n(edited, 'EditedMessage');\n  return edited;\n};\n\nconst makeEffect = (props: {\n  onlyElement?: boolean,\n  docId?: DocId,\n  middleware?: Middleware,\n  loadPromises?: Promise<any>[]\n}) => {\n  const span = document.createElement('span');\n  span.classList.add('time-effect');\n  if(props.onlyElement) {\n    return span;\n  }\n\n  const deferred = deferredPromise<void>();\n\n  span.dataset.effectId = '' + props.docId;\n\n  rootScope.managers.acknowledged.appReactionsManager.getAvailableEffect(props.docId)\n  .then(async(result) => {\n    if(!result.cached) {\n      deferred.resolve();\n    }\n\n    const availableEffect = await result.result;\n    if(!availableEffect) {\n      deferred.resolve();\n      return;\n    }\n\n    const loadPromises: Promise<any>[] = [];\n    wrapSticker({\n      doc: await rootScope.managers.appDocsManager.getDoc(availableEffect.static_icon_id),\n      div: span,\n      middleware: props.middleware,\n      loadPromises,\n      width: 12,\n      height: 12\n    });\n\n    Promise.all(loadPromises).then(async() => {\n      if(result.cached) {\n        deferred.resolve();\n      }\n\n      // * preload effect\n      const {doc, thumb} = await getDocForEffect(availableEffect);\n      appDownloadManager.downloadMedia({\n        media: doc,\n        thumb\n      });\n    });\n  });\n\n  props.loadPromises?.push(deferred);\n\n  return span;\n};\n\nconst getDocForEffect = async(availableEffect: AvailableEffect) => {\n  const isPremiumEffect = !availableEffect.effect_animation_id;\n  const doc = await rootScope.managers.appDocsManager.getDoc(isPremiumEffect ? availableEffect.effect_sticker_id : availableEffect.effect_animation_id);\n  return {isPremiumEffect, doc, thumb: getStickerEffectThumb(doc)};\n};\n\nexport const fireMessageEffect = ({e, isOut, element, middleware, scrollable, effectId}: {\n  e?: Event,\n  isOut?: boolean,\n  element: HTMLElement,\n  middleware: Middleware,\n  scrollable?: Scrollable,\n  effectId: DocId\n}) => {\n  if(element.dataset.playing) {\n    e && cancelEvent(e);\n    return;\n  }\n\n  element.dataset.playing = '1';\n\n  rootScope.managers.appReactionsManager.getAvailableEffect(effectId).then(async(availableEffect) => {\n    const {doc, thumb: fullThumb} = await getDocForEffect(availableEffect);\n    if(!middleware()) return;\n\n    const {animationDiv} = wrapStickerAnimation({\n      doc,\n      middleware,\n      side: isOut ? 'right' : 'left',\n      size: 240,\n      target: element,\n      play: true,\n      scrollable,\n      fullThumb: getStickerEffectThumb(doc),\n      addOffsetX: 40,\n      onUnmount: () => {\n        delete element.dataset.playing;\n      }\n    });\n\n    if(isOut === false) {\n      animationDiv.classList.add('reflect-x');\n    }\n  });\n\n  e && cancelEvent(e);\n};\n\nexport const fireMessageEffectByBubble = ({timeEffect, bubble, e, scrollable}: {\n  timeEffect: HTMLElement,\n  bubble: HTMLElement,\n  e?: Event,\n  scrollable?: Scrollable\n}) => {\n  const effectId = timeEffect.dataset.effectId as DocId;\n  return fireMessageEffect({\n    element: timeEffect,\n    isOut: bubble.classList.contains('is-out'),\n    e,\n    scrollable,\n    effectId,\n    middleware: bubble.middlewareHelper.get()\n  });\n};\n\n// const makeSponsored = () => i18n('SponsoredMessage');\n\nexport namespace MessageRender {\n  /* export const setText = () => {\n\n  }; */\n\n  export const setTime = (options: {\n    chat: Chat,\n    chatType: ChatType,\n    message: Message.message | Message.messageService,\n    groupedMessagesCount?: number,\n    reactionsMessage?: Message.message | Message.messageService,\n    isOut: boolean,\n    middleware: Middleware,\n    loadPromises?: Promise<any>[]\n  }) => {\n    const {chatType, message, groupedMessagesCount} = options;\n    const isMessage = !('action' in message)/*  && !isSponsored */;\n    const includeDate = message.peerId === rootScope.myId && (!options.isOut/*  || !!options.chat.threadId */);\n    const args: (HTMLElement | string)[] = [];\n\n    let timestamp = message.date;\n    if(includeDate && isMessage && message.fwd_from) {\n      const fwdTime = message.fwd_from.saved_date || message.fwd_from.date;\n      timestamp = fwdTime || timestamp;\n    }\n    const date = new Date(timestamp * 1000);\n\n    let editedSpan: HTMLElement,\n      effectSpan: HTMLElement;\n    // sponsoredSpan: HTMLElement;\n    // reactionsElement: ReactionsElement,\n    // reactionsMessage: Message.message;\n\n    // const isSponsored = !!(message as Message.message).pFlags.sponsored;\n    // let hasReactions: boolean;\n\n    const fwdFrom = isMessage && message.fwd_from;\n    const time: HTMLElement = /* isSponsored ? undefined :  */makeTime(date, includeDate);\n\n    let title = /* isSponsored ? undefined :  */getFullDate(new Date(message.date * 1000));\n    if(isMessage) {\n      title += (message.edit_date && !message.pFlags.edit_hide ? `\\nEdited: ${getFullDate(new Date(message.edit_date * 1000))}` : '') +\n        (fwdFrom ? `\\nOriginal: ${getFullDate(new Date(fwdFrom.saved_date || fwdFrom.date * 1000))}` : '');\n\n      const messageMedia = message.media;\n      if(messageMedia?._ === 'messageMediaDice' && messageMedia.game_outcome) {\n        const span = document.createElement('span');\n        span.classList.add('time-dice');\n        span.textContent = formatNanoton(messageMedia.game_outcome.stake_ton_amount);\n\n        const icon = Icon('ton', 'time-icon', 'time-part');\n\n        args.push(span, icon);\n      }\n\n      if(message.views) {\n        const postViewsSpan = document.createElement('span');\n        postViewsSpan.classList.add('post-views');\n        postViewsSpan.textContent = formatNumber(message.views, 1);\n\n        const channelViews = Icon('channelviews', 'time-icon', 'time-part', 'time-icon-views');\n\n        title += '\\n' + I18n.format('ViewsTooltip', true, [numberThousandSplitter(message.views)]);\n        if(message.forwards) {\n          title += '\\n' + I18n.format('SharesTooltip', true, [numberThousandSplitter(message.forwards)]);\n        }\n\n        args.push(postViewsSpan, channelViews);\n      }\n\n      const postAuthor = options.chat.getPostAuthor(message);\n      if(postAuthor) {\n        const span = document.createElement('span');\n        span.classList.add('time-post-author');\n        setInnerHTML(span, wrapEmojiText(postAuthor));\n        span.insertAdjacentHTML('beforeend', '<span class=\"time-post-author-comma\">,' + NBSP + '</span>');\n        args.push(span);\n      }\n\n      if(message.edit_date && chatType !== ChatType.Scheduled && !message.pFlags.edit_hide) {\n        args.unshift(editedSpan = makeEdited());\n      }\n\n      if(chatType !== ChatType.Pinned && message.pFlags.pinned) {\n        const i = Icon('pinnedchat_filled', 'time-icon', 'time-pinned', 'time-part');\n        args.unshift(i);\n      }\n\n      if(message.effect) {\n        effectSpan = makeEffect({onlyElement: true});\n        args.push(effectSpan);\n      }\n\n      if(message.paid_message_stars && options.chat.isAnyGroup) {\n        const inlineStars = document.createElement('span');\n        inlineStars.classList.add('inline-stars', 'bubble-meta-inline-stars');\n        inlineStars.append(\n          numberThousandSplitterForStars(+message.paid_message_stars * Math.max(groupedMessagesCount || 0, 1)),\n          Icon('star', 'inline-stars-icon')\n        );\n        args.push(inlineStars)\n      }\n\n      // if(USER_REACTIONS_INLINE && message.peer_id._ === 'peerUser'/*  && message.reactions?.results?.length */) {\n      //   hasReactions = true;\n\n      //   reactionsMessage = options.reactionsMessage;\n      //   reactionsElement = new ReactionsElement();\n      //   reactionsElement.init(reactionsMessage, 'inline', true);\n      //   reactionsElement.render();\n      //   args.unshift(reactionsElement);\n      // }\n    }/*  else if(isSponsored) {\n      args.push(sponsoredSpan = makeSponsored());\n    } */\n\n    let repeatSpan: HTMLElement;\n    if(isMessage && message.schedule_repeat_period) {\n      repeatSpan = makeScheduleRepeatPeriod(message.schedule_repeat_period);\n      args.push(repeatSpan);\n    }\n\n    if(time) {\n      args.push(time);\n    }\n\n    const timeSpan = document.createElement('span');\n    timeSpan.classList.add('time');\n    // if(title) timeSpan.title = title;\n    timeSpan.append(...args);\n\n    const inner = document.createElement('div');\n    inner.classList.add('time-inner');\n    if(title) inner.title = title;\n\n    let clonedArgs = args;\n    if(editedSpan) {\n      clonedArgs[clonedArgs.indexOf(editedSpan)] = makeEdited();\n    }\n    // if(sponsoredSpan) {\n    //   clonedArgs[clonedArgs.indexOf(sponsoredSpan)] = makeSponsored();\n    // }\n    // if(reactionsElement) {\n    //   const _reactionsElement = clonedArgs[clonedArgs.indexOf(reactionsElement)] = new ReactionsElement();\n    //   _reactionsElement.init(reactionsMessage, 'inline');\n    //   _reactionsElement.render();\n    // }\n    if(repeatSpan) {\n      clonedArgs[clonedArgs.indexOf(repeatSpan)] = makeScheduleRepeatPeriod((message as Message.message).schedule_repeat_period);\n    }\n    if(effectSpan) {\n      clonedArgs[clonedArgs.indexOf(effectSpan)] = makeEffect({\n        docId: (message as Message.message).effect,\n        middleware: options.middleware,\n        loadPromises: options.loadPromises\n      });\n    }\n    clonedArgs = clonedArgs.map((a) => {\n      return a instanceof HTMLElement &&\n        !a.classList.contains('i18n') &&\n        !a.classList.contains('reactions') &&\n        !a.classList.contains('time-effect') ?\n          a.cloneNode(true) as HTMLElement :\n          a;\n    });\n    if(time) {\n      clonedArgs[clonedArgs.length - 1] = makeTime(date, includeDate); // clone time\n    }\n    inner.append(...clonedArgs);\n\n    timeSpan.append(inner);\n\n    return timeSpan;\n  };\n\n  export const renderReplies = ({bubble, bubbleContainer, message, messageDiv, loadPromises, lazyLoadQueue, middleware}: {\n    bubble: HTMLElement,\n    bubbleContainer: HTMLElement,\n    message: Message.message,\n    messageDiv: HTMLElement,\n    loadPromises?: Promise<any>[],\n    lazyLoadQueue?: LazyLoadQueue,\n    middleware: Middleware\n  }) => {\n    const isFooter = !bubble.classList.contains('sticker') &&\n      !bubble.classList.contains('emoji-big') &&\n      !bubble.classList.contains('round');\n    const repliesFooter = new RepliesElement();\n    repliesFooter.message = message;\n    repliesFooter.type = isFooter ? 'footer' : 'beside';\n    repliesFooter.loadPromises = loadPromises;\n    repliesFooter.lazyLoadQueue = lazyLoadQueue;\n    repliesFooter.middlewareHelper = middleware.create();\n    repliesFooter.init();\n    bubbleContainer.append(repliesFooter);\n    return isFooter;\n  };\n\n  export const setReply = async({chat, bubble, bubbleContainer, message, logId, appendCallback, middleware, lazyLoadQueue, needUpdate, isStandaloneMedia, isOut, fromUpdate}: {\n    chat: Chat,\n    bubble: HTMLElement,\n    bubbleContainer?: HTMLElement,\n    message: Message.message,\n    logId?: string | number,\n    appendCallback?: (container: HTMLElement) => void,\n    middleware: Middleware,\n    lazyLoadQueue: LazyLoadQueue,\n    needUpdate: ChatBubbles['needUpdate'],\n    isStandaloneMedia: boolean,\n    isOut: boolean,\n    fromUpdate?: boolean\n  }) => {\n    const isReplacing = !bubbleContainer;\n    if(isReplacing) {\n      bubbleContainer = bubble.querySelector('.bubble-content');\n    }\n\n    const currentReplyDiv = isReplacing ? bubbleContainer.querySelector('.reply') as HTMLElement : null;\n    const replyTo = message.reply_to;\n    if(!replyTo) {\n      currentReplyDiv?.remove();\n      bubble.classList.remove('is-reply');\n      return;\n    }\n\n    const isStoryReply = replyTo._ === 'messageReplyStoryHeader';\n\n    const replyToPeerId = isStoryReply ?\n      getPeerId(replyTo.peer) :\n      (\n        replyTo.reply_to_peer_id ?\n          getPeerId(replyTo.reply_to_peer_id) :\n          message.peerId\n      );\n\n    const originalMessage = !isStoryReply && apiManagerProxy.getMessageByPeer(replyToPeerId, message.reply_to_mid);\n    const originalStory = isStoryReply && await rootScope.managers.acknowledged.appStoriesManager.getStoryById(replyToPeerId, replyTo.story_id);\n    let originalPeerTitle: string | HTMLElement | DocumentFragment;\n\n    let isReplyFromAnotherPeer = false;\n    let titlePeerId: PeerId, setColorPeerId: PeerId, forUpdate: typeof needUpdate[0];\n\n    if(!fromUpdate) {\n      if(isStoryReply) {\n        needUpdate.push(forUpdate = {replyToPeerId, replyStoryId: replyTo.story_id, mid: message.mid, peerId: message.peerId, logId});\n      } else {\n        needUpdate.push(forUpdate = {replyToPeerId, replyMid: message.reply_to_mid, mid: message.mid, peerId: message.peerId, logId});\n      }\n\n      middleware.onClean(() => {\n        indexOfAndSplice(needUpdate, forUpdate);\n      });\n    }\n\n    if(isStoryReply) {\n      if(!originalStory.cached) {\n        rootScope.managers.appMessagesManager.fetchMessageReplyTo(message);\n        // needUpdate.push(forUpdate = {replyToPeerId, replyStoryId: replyTo.story_id, mid: message.mid, peerId: message.peerId});\n        originalPeerTitle = i18n('Loading');\n      } else {\n        titlePeerId = replyToPeerId;\n        originalPeerTitle = new PeerTitle({\n          peerId: titlePeerId,\n          dialog: false,\n          onlyFirstName: false,\n          plainText: false\n        }).element;\n      }\n    } else if(!originalMessage) {\n      // from different peer\n      if(replyTo.reply_from) {\n        isReplyFromAnotherPeer = true;\n        titlePeerId = getPeerId(replyTo.reply_from?.from_id || replyTo.reply_to_peer_id);\n        originalPeerTitle = new PeerTitle({\n          peerId: titlePeerId || undefined,\n          dialog: false,\n          onlyFirstName: false,\n          plainText: false,\n          fromName: getFwdFromName(replyTo.reply_from)\n        }).element;\n      } else if(replyTo.reply_to_msg_deleted) {\n        originalPeerTitle = i18n('DeletedMessage');\n      } else {\n        // needUpdate.push(forUpdate = {replyToPeerId, replyMid: message.reply_to_mid, mid: message.mid, peerId: message.peerId});\n        rootScope.managers.appMessagesManager.fetchMessageReplyTo(message);\n\n        originalPeerTitle = i18n('Loading');\n      }\n    } else {\n      isReplyFromAnotherPeer = !!replyTo.reply_from;\n      const originalMessageFwdFromId = (originalMessage as Message.message).fwdFromId;\n      titlePeerId = message.fwdFromId && message.fwdFromId === originalMessageFwdFromId ?\n        message.fwdFromId :\n        originalMessageFwdFromId || originalMessage.fromId;\n      setColorPeerId = message.fwdFromId && message.fwdFromId === originalMessageFwdFromId ?\n        undefined :\n        originalMessage.fromId;\n      originalPeerTitle = new PeerTitle({\n        peerId: titlePeerId,\n        dialog: false,\n        onlyFirstName: false,\n        plainText: false,\n        fromName: !titlePeerId ? getFwdFromName((originalMessage as Message.message).fwd_from) : undefined\n      }).element;\n    }\n\n    if(!isStoryReply && replyTo.reply_from) {\n      const fragment = document.createDocumentFragment();\n      let icon: HTMLElement;\n      if(replyTo.reply_from.channel_post) {\n        fragment.append(icon = Icon('newchannel_filled', 'with-margin'), originalPeerTitle);\n      } else if(replyTo.reply_to_peer_id) {\n        const groupPeerTitle = new PeerTitle({\n          peerId: getPeerId(replyTo.reply_to_peer_id),\n          dialog: false,\n          onlyFirstName: false,\n          plainText: false\n        }).element;\n\n        fragment.append(originalPeerTitle, ' ', icon = Icon('group_filled'), ' ', groupPeerTitle);\n      } else {\n        fragment.append(icon = Icon('newprivate_filled', 'with-margin'), originalPeerTitle);\n      }\n\n      if(icon) {\n        icon.classList.add('inline-icon', 'reply-title-icon');\n        originalPeerTitle = fragment;\n      }\n    }\n\n    const isStoryExpired = isStoryReply && originalStory.cached && !(await originalStory.result);\n    const {container, fillPromise} = wrapReply({\n      title: originalPeerTitle,\n      animationGroup: chat.animationGroup,\n      message: originalMessage || (isReplyFromAnotherPeer ? {\n        _: 'message',\n        pFlags: {},\n        id: 0,\n        date: 0,\n        message: '',\n        peer_id: undefined,\n        media: (replyTo as MessageReplyHeader.messageReplyHeader).reply_media\n      } : undefined),\n      isStoryExpired,\n      storyItem: originalStory?.cached && await originalStory.result,\n      setColorPeerId: setColorPeerId || titlePeerId,\n      textColor: 'primary-text-color',\n      isQuote: !isStoryReply ? replyTo.pFlags.quote : undefined,\n      middleware,\n      lazyLoadQueue,\n      replyHeader: replyTo,\n      useHighlightingColor: isStandaloneMedia,\n      colorAsOut: isOut,\n      canTranslate: originalMessage && !isReplyFromAnotherPeer ? !originalMessage.pFlags.out : undefined\n    });\n\n    await fillPromise;\n    if(currentReplyDiv) {\n      const saveClassNames = ['floating-part', 'mb-shorter'];\n      const classList = currentReplyDiv.classList;\n      saveClassNames.forEach((className) => {\n        if(classList.contains(className)) {\n          container.classList.add(className);\n        }\n      });\n      currentReplyDiv.replaceWith(container);\n    } else {\n      appendCallback(container);\n    }\n    // bubbleContainer.insertBefore(, nameContainer);\n    bubble.classList.add('is-reply');\n\n    return container;\n  };\n}\n","import {Accessor, createEffect, createMemo, createResource, createSignal, JSX} from 'solid-js';\nimport Animated from '@helpers/solid/animations';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport classNames from '@helpers/string/classNames';\nimport rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {fireMessageEffect} from '@components/chat/messageRender';\n\nexport default function SelectedEffect(props: {\n  effect: Accessor<DocId>\n}) {\n  const [element, setElement] = createSignal<JSX.Element>();\n  const lastElement = createMemo<JSX.Element>((prev) => element() || prev);\n  const [availableEffects] = createResource(async() => {\n    return rootScope.managers.appReactionsManager.getAvailableEffects();\n  });\n\n  createEffect(async() => {\n    const effect = props.effect();\n    if(!effect || !availableEffects()) {\n      setElement();\n      return;\n    }\n\n    const availableEffect = availableEffects().find((availableEffect) => availableEffect.id === effect);\n\n    let ref: HTMLDivElement;\n    const element = (<div class=\"btn-send-effect\" ref={ref}></div>);\n\n    const middlewareHelper = createMiddleware();\n    const middleware = middlewareHelper.get();\n    const loadPromises: Promise<any>[] = [];\n    wrapSticker({\n      doc: await rootScope.managers.appDocsManager.getDoc(availableEffect.static_icon_id),\n      div: ref,\n      middleware,\n      loadPromises,\n      width: 20,\n      height: 20\n    });\n\n    await Promise.all(loadPromises);\n\n    if(middleware()) {\n      setElement(element);\n    }\n\n    fireMessageEffect({\n      isOut: true,\n      effectId: effect,\n      element: ref,\n      middleware\n    });\n  });\n\n  return (\n    <div class={classNames('btn-send-effect-container', element() && 'is-visible')}>\n      <Animated type=\"cross-fade\">\n        {lastElement()}\n      </Animated>\n    </div>\n  );\n}\n","import {createSignal, For, onCleanup, onMount, Show, untrack, useContext} from 'solid-js';\nimport PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\n\nimport Chat from '@components/chat/chat';\nimport Button from '@components/buttonTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport InputField from '@components/inputField';\nimport Row from '@components/rowTsx';\nimport Section from '@components/section';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {toastNew} from '@components/toast';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport {fastRaf} from '@helpers/schedulers';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport classNames from '@helpers/string/classNames';\nimport {InputMedia, Message, MessageMedia, TodoItem} from '@layer';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {wrapEmojiTextWithEntities} from '@lib/richTextProcessor/wrapEmojiText';\n\nimport css from '@components/popups/checklist.module.scss';\n\nexport type ChecklistPopupOptions = {\n  chat: Chat,\n  editMessage?: Message.message & {media: MessageMedia.messageMediaToDo},\n  focusItemId?: number,\n  appending?: boolean\n};\n\nexport default function showChecklistPopup(options: ChecklistPopupOptions): void {\n  const {chat, editMessage, focusItemId, appending} = options;\n\n  const titleKey: LangPackKey = appending ? 'ChecklistAddTasks' :\n    editMessage ? 'EditChecklist' : 'NewChecklist';\n  const confirmKey: LangPackKey = editMessage ? 'Save' : 'Create';\n\n  type Item = {id: number, existing: boolean, field: InputField};\n\n  function Inner() {\n    const context = useContext(PopupContext);\n    const middleware = untrack(() => context.middlewareHelper).get();\n    const managers = untrack(() => context.managers);\n    const listenerSetter = new ListenerSetter();\n\n    onCleanup(() => listenerSetter.removeAll());\n\n    const [items, setItems] = createSignal<Item[]>([]);\n    const [valid, setValid] = createSignal(false);\n    const [pending, setPending] = createSignal(false);\n    const [titleInput, setTitleInput] = createSignal<InputField>();\n    const [maxItems, setMaxItems] = createSignal(10);\n    const [allowOthersToMarkAsDone, setAllowOthersToMarkAsDone] = createSignal(\n      editMessage?.media.todo.pFlags.others_can_complete ?? false\n    );\n    const [allowOthersToAddTasks, setAllowOthersToAddTasks] = createSignal(\n      editMessage?.media.todo.pFlags.others_can_append ?? false\n    );\n\n    let addItem: ((existing?: TodoItem) => void) | undefined;\n    let removeItem: ((id: number) => void) | undefined;\n    let handleConfirm: (() => Promise<void>) | undefined;\n\n    let btnConfirmEl!: HTMLButtonElement;\n\n    managers.apiManager.getAppConfig().then((appConfig) => {\n      if(!middleware()) return;\n\n      const itemLengthMax = appConfig.todo_item_length_max ?? 255;\n      setMaxItems(appConfig.todo_items_max ?? 10);\n\n      const _titleInput = new InputField({\n        placeholder: 'NewChecklist.TitlePlaceholder',\n        name: 'title',\n        canBeEdited: !appending\n      });\n\n      const updateConfirmButton = () => {\n        const ok = (() => {\n          if(!_titleInput.value) return false;\n          let items$ = items();\n          if(appending) {\n            items$ = items$.filter((v) => !v.existing);\n          }\n\n          if(items$.length === 0) return false;\n          return items$.every((v) => {\n            const val = v.field.value.trim();\n            return val.length > 0 && val.length <= itemLengthMax;\n          });\n        })();\n\n        setValid(ok);\n      };\n\n      listenerSetter.add(_titleInput.input)('input', updateConfirmButton);\n\n      addItem = (existing?: TodoItem) => {\n        if(items().length >= maxItems()) return;\n\n        const field = new InputField({\n          placeholder: 'NewChecklist.TaskPlaceholder',\n          name: 'item',\n          maxLength: itemLengthMax,\n          canBeEdited: !(existing && appending)\n        });\n        if(existing) {\n          field.setValueSilently(wrapEmojiTextWithEntities(existing.title), true);\n        }\n        listenerSetter.add(field.input)('input', updateConfirmButton);\n        setItems((v) => {\n          let id: number;\n          if(existing) id = existing.id;\n          else if(v.length > 0) id = v[v.length - 1].id + 1;\n          else id = 0;\n          return [...v, {id, existing: !!existing, field}];\n        });\n        updateConfirmButton();\n        if(!existing || existing.id === focusItemId) {\n          fastRaf(() => {\n            field.input.focus();\n          });\n        }\n      };\n\n      removeItem = (id: number) => {\n        setItems((v) => v.filter((it) => it.id !== id));\n        updateConfirmButton();\n      };\n\n      handleConfirm = async() => {\n        let promise: Promise<any>;\n        if(appending) {\n          const maxId = editMessage?.media.todo.list.reduce((max, item) => Math.max(max, item.id), 0) ?? 0;\n          const newItems = items().filter((v) => !v.existing);\n\n          promise = managers.appMessagesManager.appendTodo({\n            peerId: chat.peerId,\n            mid: editMessage.mid,\n            tasks: newItems.map((v, idx) => {\n              const richValue = getRichValueWithCaret(v.field.input, true, false);\n              return {\n                _: 'todoItem',\n                // ids must be consecutive when creating\n                id: maxId + idx + 1,\n                title: {\n                  _: 'textWithEntities',\n                  text: richValue.value,\n                  entities: richValue.entities\n                }\n              };\n            })\n          });\n        } else {\n          const title = getRichValueWithCaret(_titleInput.input, true, false);\n\n          const inputMedia: InputMedia = {\n            _: 'inputMediaTodo',\n            todo: {\n              _: 'todoList',\n              pFlags: {\n                others_can_append: allowOthersToAddTasks() ? true : undefined,\n                others_can_complete: allowOthersToMarkAsDone() ? true : undefined\n              },\n              title: {\n                _: 'textWithEntities',\n                text: title.value,\n                entities: title.entities\n              },\n              list: items().map((v, idx) => {\n                const richValue = getRichValueWithCaret(v.field.input, true, false);\n                return {\n                  _: 'todoItem',\n                  // ids must be consecutive when creating\n                  id: editMessage ? v.id : idx + 1,\n                  title: {\n                    _: 'textWithEntities',\n                    text: richValue.value,\n                    entities: richValue.entities\n                  }\n                };\n              })\n            }\n          };\n\n          if(editMessage) {\n            promise = managers.appMessagesManager.editMessage(editMessage, editMessage.message, {\n              newMedia: inputMedia\n            });\n          } else {\n            const sendingParams = chat.getMessageSendingParams();\n\n            const preparedPaymentResult = await chat.input.paidMessageInterceptor.prepareStarsForPayment(1);\n            if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n            sendingParams.confirmedPaymentResult = preparedPaymentResult;\n\n            context.hide();\n\n            managers.appMessagesManager.sendOther({\n              ...sendingParams,\n              inputMedia\n            });\n\n            if(chat.input.helperType === 'reply') {\n              chat.input.clearHelper();\n            }\n\n            chat.input.onMessageSent(false, false);\n          }\n        }\n\n        if(promise) {\n          setPending(true);\n          promise.then(() => {\n            setPending(false);\n            context.hide();\n          }).catch(() => {\n            setPending(false);\n            toastNew({langPackKey: 'Error.AnError'});\n          });\n        }\n      };\n\n      if(editMessage) {\n        _titleInput.setValueSilently(wrapEmojiTextWithEntities(editMessage.media.todo.title), true);\n        for(const item of editMessage.media.todo.list) {\n          addItem(item);\n        }\n        if(appending) addItem();\n      } else {\n        addItem();\n      }\n\n      setTitleInput(_titleInput);\n    });\n\n    onMount(() => {\n      attachClickEvent(btnConfirmEl, () => {\n        handleConfirm?.();\n      }, {listenerSetter});\n      context.setBtnConfirmOnEnter(btnConfirmEl);\n    });\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title title={titleKey} />\n          <button\n            ref={btnConfirmEl}\n            class=\"btn-primary btn-color-primary\"\n            disabled={!valid() || pending() || !titleInput()}\n          >\n            {i18n(confirmKey)}\n          </button>\n        </PopupElement.Header>\n        <PopupElement.Scrollable>\n          <Show when={titleInput()}>\n            <Section class={css.titleSection} noShadow noDelimiter>\n              {titleInput().container}\n            </Section>\n            <Section name=\"Checklist\">\n              <For each={items()}>\n                {(item, idx) => (\n                  <div\n                    class={classNames(\n                      css.item,\n                      idx() === 0 && css.itemFirst,\n                      idx() === items().length - 1 && css.itemLast\n                    )}\n                  >\n                    {item.field.container}\n                    {!(item.existing && appending) && (\n                      <ButtonIconTsx\n                        class={css.itemRemoveButton}\n                        icon=\"close\"\n                        onClick={() => removeItem?.(item.id)}\n                      />\n                    )}\n                  </div>\n                )}\n              </For>\n              <Show when={items().length < maxItems()}>\n                <Button\n                  class={`btn-transparent ${css.addTaskButton}`}\n                  icon=\"add\"\n                  onClick={() => addItem?.()}\n                  text=\"ChecklistAddTask\"\n                />\n              </Show>\n            </Section>\n\n            <Show when={!appending}>\n              <Section name=\"ChecklistOptions\">\n                <Row>\n                  <Row.CheckboxFieldToggle>\n                    <CheckboxFieldTsx\n                      checked={allowOthersToMarkAsDone()}\n                      toggle\n                      onChange={setAllowOthersToMarkAsDone}\n                    />\n                  </Row.CheckboxFieldToggle>\n                  <Row.Title><I18nTsx key=\"ChecklistAllowOthersDone\" /></Row.Title>\n                </Row>\n                <Row>\n                  <Row.CheckboxFieldToggle>\n                    <CheckboxFieldTsx\n                      checked={allowOthersToAddTasks()}\n                      toggle\n                      onChange={setAllowOthersToAddTasks}\n                    />\n                  </Row.CheckboxFieldToggle>\n                  <Row.Title><I18nTsx key=\"ChecklistAllowOthersAdd\" /></Row.Title>\n                </Row>\n              </Section>\n            </Show>\n          </Show>\n        </PopupElement.Scrollable>\n      </>\n    );\n  }\n\n  createPopup(() => (\n    <PopupElement class={`${css.popup} popup-new-media`}>\n      <Inner />\n    </PopupElement>\n  ));\n}\n","import PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\nimport {createMemo, createResource, createSignal, For, Show, untrack, useContext} from 'solid-js';\nimport InputField from '@components/inputField';\nimport Row from '@components/rowTsx';\nimport Scrollable from '@components/scrollable2';\nimport classNames from '@helpers/string/classNames';\nimport {i18n} from '@lib/langPack';\nimport {QuickReply} from '@lib/quickReplies/types';\nimport styles from './quickRepliesPicker.module.scss';\n\ntype PickerItem = QuickReply & {source?: 'crm', crmTemplateId?: number, imageCount?: number};\n\nexport default function showQuickRepliesPickerPopup(options: {\n  onSelect: (reply: PickerItem) => void\n}): void {\n  function Inner() {\n    const context = useContext(PopupContext);\n    const managers = untrack(() => context.managers);\n\n    const [items] = createResource(async(): Promise<PickerItem[]> => {\n      const [local, templates, faqs] = await Promise.all([\n        managers.appQuickRepliesManager.getQuickReplies(),\n        managers.appCrmManager.getTemplates(),\n        managers.appCrmManager.getFaqs()\n      ]);\n\n      const crm: PickerItem[] = [\n        ...templates.map((t) => ({\n          id: 'crm-t-' + t.id,\n          title: t.name,\n          text: t.text,\n          date: 0,\n          source: 'crm' as const,\n          crmTemplateId: t.id,\n          imageCount: t.image_urls?.length || 0\n        })),\n        ...faqs.map((f) => ({id: 'crm-f-' + f.id, title: f.question, text: f.answer, date: 0, source: 'crm' as const}))\n      ];\n\n      return [...local, ...crm];\n    });\n\n    const [query, setQuery] = createSignal('');\n\n    const searchInputField = new InputField({\n      label: 'Search',\n      name: 'quick-replies-search',\n      plainText: true\n    });\n    searchInputField.input.addEventListener('input', () => setQuery(searchInputField.value.trim().toLowerCase()));\n\n    const filtered = createMemo(() => {\n      const list = items() || [];\n      const q = query();\n      if(!q) return list;\n      return list.filter((reply) => {\n        return reply.title.toLowerCase().includes(q) || reply.text.toLowerCase().includes(q);\n      });\n    });\n\n    const select = (reply: PickerItem) => {\n      options.onSelect(reply);\n      context.hide();\n    };\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title title=\"QuickReplies.PickerTitle\" />\n        </PopupElement.Header>\n        <PopupElement.Body class={styles.body}>\n          <div class={styles.search}>{searchInputField.container}</div>\n          <Show\n            when={(items() || []).length}\n            fallback={<div class={styles.empty}>{i18n('QuickReplies.EmptyHint')}</div>}\n          >\n            <Scrollable class={styles.list}>\n              <For each={filtered()} fallback={<div class={styles.empty}>{i18n('QuickReplies.NoMatches')}</div>}>\n                {(reply) => (\n                  <Row clickable={() => select(reply)} class={styles.row}>\n                    <Row.Title>\n                      {reply.title}\n                      <Show when={reply.source === 'crm'}>\n                        <span class={styles.badge}>{i18n('QuickReplies.SourceCrm')}</span>\n                      </Show>\n                      <Show when={reply.imageCount}>\n                        <span class={styles.images}>{(reply.imageCount > 1 ? reply.imageCount + ' ' : '') + '🖼'}</span>\n                      </Show>\n                    </Row.Title>\n                    <Row.Subtitle>{reply.text}</Row.Subtitle>\n                  </Row>\n                )}\n              </For>\n            </Scrollable>\n          </Show>\n        </PopupElement.Body>\n      </>\n    );\n  }\n\n  createPopup(() => (\n    <PopupElement\n      class={classNames('popup-quick-replies-picker', styles.popup)}\n      closable\n      old\n    >\n      <Inner />\n    </PopupElement>\n  ));\n}\n","import {createSignal, For, JSX, Show} from 'solid-js';\nimport PopupElement from '@components/popups/indexTsx';\nimport Row from '@components/rowTsx';\nimport {createPopup} from '@components/popups/indexTsx';\nimport styles from '@components/popups/featureDetails.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport MediaHeader, {MediaHeaderStickerProps} from '@components/mediaHeader';\n\ninterface FeatureDetailsRow {\n  icon: Icon;\n  title: JSX.Element;\n  subtitle: JSX.Element;\n}\n\nexport interface FeatureDetailsButton {\n  text: JSX.Element;\n  onClick?: (close: () => void) => MaybePromise<boolean | void>;\n  isCancel?: boolean;\n  isSecondary?: boolean;\n}\n\ntype FeatureDetailsPopupProps = {\n  sticker: Omit<MediaHeaderStickerProps, 'onReady'>,\n  title?: JSX.Element,\n  subtitle?: JSX.Element,\n  subtitleSecondary?: boolean,\n  rows: FeatureDetailsRow[],\n  caption?: {\n    title?: JSX.Element,\n    subtitle?: JSX.Element\n  },\n  buttons: FeatureDetailsButton[],\n  onClose?: () => void\n};\n\nexport default function showFeatureDetailsPopup(props: FeatureDetailsPopupProps) {\n  const [show, setShow] = createSignal(false);\n  const close = () => setShow(false);\n\n  createPopup(() => (\n    <PopupElement\n      class={styles.popup}\n      containerClass={styles.popupContainer}\n      show={show()}\n      onClose={props.onClose}\n      old\n    >\n      <PopupElement.Header class={styles.popupHeader}>\n        <PopupElement.CloseButton class={styles.popupCloseButton} />\n      </PopupElement.Header>\n      <PopupElement.Body>\n        <MediaHeader>\n          <MediaHeader.Sticker {...props.sticker} onReady={() => setShow(true)} />\n          <Show when={props.title}>\n            <MediaHeader.Title>{props.title}</MediaHeader.Title>\n          </Show>\n          <Show when={props.subtitle}>\n            <MediaHeader.Subtitle secondary={props.subtitleSecondary}>{props.subtitle}</MediaHeader.Subtitle>\n          </Show>\n        </MediaHeader>\n        <For each={props.rows}>{({icon, title, subtitle}) => (\n          <Row class={styles.row}>\n            <Row.Icon class={classNames('primary', styles.rowIcon)} icon={icon} />\n            <Row.Title class=\"text-bold\">{title}</Row.Title>\n            <Row.Subtitle class={styles.rowSubtitle}>{subtitle}</Row.Subtitle>\n          </Row>\n        )}</For>\n        <Show when={props.caption}>\n          <div class={styles.caption}>\n            <Show when={props.caption.title}>\n              <div class={styles.captionTitle}>{props.caption.title}</div>\n            </Show>\n            <Show when={props.caption.subtitle}>\n              <div class={styles.captionSubtitle}>{props.caption.subtitle}</div>\n            </Show>\n          </div>\n        </Show>\n      </PopupElement.Body>\n      <PopupElement.Footer class={styles.popupFooter}>\n        <For each={props.buttons}>{(button) => (\n          <PopupElement.FooterButton\n            callback={button.onClick ? () => button.onClick?.(close) : close}\n            cancel={button.isCancel}\n            color={button.isSecondary ? 'secondary' : undefined}\n          >\n            {button.text}\n          </PopupElement.FooterButton>\n        )}</For>\n      </PopupElement.Footer>\n    </PopupElement>\n  ));\n\n  return close;\n}\n","import {i18n} from '@lib/langPack';\nimport {useAppConfig} from '@stores/appState';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {formatDate} from '@helpers/date';\nimport appImManager from '@lib/appImManager';\nimport showFeatureDetailsPopup from '@components/popups/featureDetails';\n\nconst TEST = false;\n\nexport default function showFrozenPopup() {\n  const appConfig = useAppConfig();\n  const url = TEST ? 'https://t.me/telegram' : appConfig.freeze_appeal_url;\n  const untilDate = TEST ? Date.now() + 86400e3 : appConfig.freeze_until_date * 1000;\n  const username = url.split('/').pop();\n\n  const onClick = () => {\n    appImManager.openUrl(url);\n  };\n\n  const anchor = anchorCallback(onClick, true);\n  anchor.innerText = '@' + username;\n\n  showFeatureDetailsPopup({\n    rows: [\n      {icon: 'hand', title: i18n('Frozen.Violation.Title'), subtitle: i18n('Frozen.Violation.Subtitle')},\n      {icon: 'lock', title: i18n('Frozen.ReadOnly.Title'), subtitle: i18n('Frozen.ReadOnly.Subtitle')},\n      {\n        icon: 'hourglass',\n        title: i18n('Frozen.Appeal.Title'),\n        subtitle: i18n('Frozen.Appeal.Subtitle', [anchor, formatDate(new Date(untilDate), {withTime: true})])\n      }\n    ],\n    sticker: {\n      name: 'UtyanRestricted',\n      size: 130\n    },\n    title: i18n('Frozen.Title'),\n    buttons: [{\n      text: i18n('Frozen.Button'),\n      onClick: (close) => {\n        close();\n        onClick();\n      }\n    }, {\n      text: i18n('Frozen.Ok'),\n      onClick: () => {},\n      isCancel: true,\n      isSecondary: true\n    }]\n  });\n}\n","import clamp from '@helpers/number/clamp';\nimport {createMemo, JSX, Show} from 'solid-js';\nimport {Dynamic} from 'solid-js/web';\n\n\ntype Props = {\n  class?: string;\n  progress: number;\n  stroke: string;\n  /**\n   * From 0 to 1\n   */\n  strokeThickness: number;\n  withText?: boolean;\n  /**\n   * Font size in SVG units (the viewBox is 120x120). Defaults to 30.\n   */\n  textSize?: number;\n  animate?: boolean;\n};\n\nconst diameter = 120;\nconst halfDiameter = diameter / 2;\n\nexport const ProgressCircleSVG = (props: Props) => {\n  const strokeWidth = createMemo(() => clamp(props.strokeThickness, 0, 1) * halfDiameter);\n\n  const radius = createMemo(() => halfDiameter - strokeWidth() - 2);\n  const circumference = createMemo(() => 2 * Math.PI * radius());\n\n  const strokeDashoffset = () => circumference() - props.progress * circumference();\n  const transition = () => props.animate ? 'stroke-dashoffset linear 0.2s' : undefined;\n\n  return (\n    <svg class={props.class} width=\"100%\" height=\"100%\" viewBox={`0 0 ${diameter} ${diameter}`}>\n      <circle\n        cx=\"60\"\n        cy=\"60\"\n        r={radius()}\n        fill=\"none\"\n        stroke={props.stroke}\n        stroke-width={strokeWidth() + ''}\n        stroke-dasharray={circumference() + ''}\n        stroke-dashoffset={strokeDashoffset()}\n        stroke-linecap=\"round\"\n        style={{\n          'transition': transition(),\n          'transform': 'rotate(-90deg)',\n          'transform-origin': '50% 50%'\n        }}\n      />\n      <Show when={props.withText}>\n        {/* Without using Dynamic, there is a weird parser error */}\n        <Dynamic\n          component='text'\n          x=\"50%\"\n          y=\"50%\"\n          dy=\".3em\"\n          text-anchor=\"middle\"\n          style={{\n            'font-size': `${props.textSize ?? 30}px`,\n            'font-weight': 'bolder',\n            'fill': 'white'\n          }}\n        >\n          {(props.progress * 100).toFixed(0)}%\n        </Dynamic>\n      </Show>\n    </svg>\n  );\n};\n","import {createEffect, createRoot, JSX, ParentProps, untrack} from 'solid-js';\nimport {createMutable, unwrap} from 'solid-js/store';\nimport {render} from 'solid-js/web';\nimport type SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\n\ntype Args<ObservedAttribute extends string, Props, Controls extends Object = {}> = {\n  name: string;\n  component: CustomElementComponent<ObservedAttribute, Props, Controls>;\n  observedAttributes?: ObservedAttribute[];\n  shadow?: boolean;\n}\n\nexport type PassedProps<Props extends Object = {}> = Props & {\n  readonly element: HTMLElement;\n};\n\ntype AttributesRecord<ObservedAttribute extends string> = Record<ObservedAttribute, string | undefined | null>;\ntype MutableStore<T extends Object> = T;\n\ntype CustomElementComponent<ObservedAttribute extends string, Props, Controls = {}> =\n  (props: PassedProps<MutableStore<Props>>, attributes: MutableStore<AttributesRecord<ObservedAttribute>>, controls: Controls) => JSX.Element;\n\nexport type DefinedSolidElement<ObservedAttribute extends string = string, Props extends Object = {}, Controls = {}> = ReturnType<typeof defineSolidElement<Props, ObservedAttribute, Controls>>;\n\n/**\n * Defines an HMR capable custom element with solid-js rendering\n *\n * Don't forget to add `if(import.meta.hot) import.meta.hot.accept();` in the file you're\n * declaring the component to take advantage of Hot Module Replacement\n *\n * Note that it might still need a refresh if you change other parameters except the component logic\n *\n * @example\n * // my-element.tsx\n * const MyElement = defineSolidElement({\n *   name: 'my-element',\n *   observedAttributes: ['size', 'something-else'],\n *   // props and attributes are reactive mutable stores, meaning you can also mutate them directly\n *   component: (props: {fancyProp: Date}, attributes, controls: {someAction: () => void}) => {\n *     // component logic in here\n *\n *     // expose some methods to the element\n *     controls.someAction = () => setInternalSignal('to something');\n *\n *     return <>...</>;\n *   }\n * });\n *\n * // used-in-file.ts\n *\n * // Some imports might break the HMR, so you can provide this hot reload guard to prevent page reload\n * import SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n *\n * const el = new MyElement;\n * el.feedProps({fancyProp: new Date});\n * el.HotReloadGuard = SolidJSHotReloadGuardProvider;\n *\n * // Append to DOM after feeding the props, unless it relies solely on attributes, or handles undefined props\n * otherElement.append(el);\n *\n * // Can use attributes if you want\n * el.setAttribute('size', '400');\n *\n * // Use internal methods through the `controls` property\n * el.controls.someAction();\n */\nexport default function defineSolidElement<Props extends Object, ObservedAttribute extends string, Controls = {}>({\n  name,\n  component,\n  observedAttributes = [],\n  shadow = false\n}: Args<ObservedAttribute, Props, Controls>) {\n  //\n  // When the module is hot replaced\n  if(customElements.get(name)) {\n    const previousElementClass = customElements.get(name) as typeof SolidElement;\n    previousElementClass.swapComponentFromHMR(component);\n    return previousElementClass;\n  }\n\n  let instances: (InstanceType<typeof SolidElement>)[];\n\n  if(import.meta.hot) {\n    instances = [];\n  }\n\n  const className = burgerToPascal(name);\n\n  const SolidElement = class extends HTMLElement {\n    private mountPoint: ShadowRoot | this;\n\n    private attributesStore: MutableStore<AttributesRecord<ObservedAttribute>>;\n    private propsStore: PassedProps<Props>;\n\n    private disposeContent?: () => void;\n    private disposeStores?: () => void;\n\n    /**\n     * Persist props when the component gets mounted / unmounted and allow initialization before the element\n     * is added to the DOM\n     */\n    private savedProps = ((self: typeof this) => ({\n      get element() {\n        return self;\n      }\n    } as unknown as PassedProps<Props>))(this);\n\n    public readonly controls = {} as Controls;\n\n    public HotReloadGuard?: typeof SolidJSHotReloadGuardProvider;\n\n    /**\n     * For HMR\n     */\n    public static Component = component;\n\n    public static swapComponentFromHMR(newComponent: CustomElementComponent<ObservedAttribute, Props, Controls>) {\n      if(import.meta.hot) {\n        SolidElement.Component = newComponent;\n        instances.forEach((instance) => {\n          instance?.mount?.();\n        });\n      }\n    }\n\n    static get observedAttributes() {\n      return observedAttributes;\n    }\n\n    constructor() {\n      super();\n\n      this.mountPoint = shadow ? this.attachShadow({mode: 'open'}) : this;\n    }\n\n    connectedCallback() {\n      this.mount();\n\n      if(import.meta.hot) {\n        instances.push(this);\n      }\n    }\n\n    disconnectedCallback() {\n      this.unmount();\n\n      if(import.meta.hot) {\n        const idx = instances.indexOf(this);\n        if(idx > -1) instances.splice(idx, 1);\n      }\n    }\n\n    attributeChangedCallback(name: ObservedAttribute, _oldValue: string, newValue: string) {\n      this.attributesStore[name] = newValue; // Let's hope this will not trigger infinite loops, as the values are compared before updates\n    }\n\n    public get props() {\n      if(this.disposeStores) {\n        return this.propsStore;\n      } else {\n        return this.savedProps;\n      }\n    }\n\n    public feedProps<Full extends boolean = true>(props: Full extends true ? Props : Partial<Props>) {\n      if(this.disposeStores) {\n        Object.assign(this.propsStore, props);\n      } else {\n        Object.assign(this.savedProps, props);\n      }\n    }\n\n    private initStores() {\n      createRoot(dispose => {\n        this.disposeStores = dispose;\n\n        this.propsStore = createMutable(this.savedProps);\n        this.attributesStore = createMutable({} as AttributesRecord<ObservedAttribute>);\n\n        createEffect(() => Object.keys(this.attributesStore).forEach(key => {\n          const attributeName = key as ObservedAttribute;\n          const value = this.attributesStore[attributeName];\n\n          if(this.getAttribute(attributeName) === this.attributesStore[attributeName]) return;\n\n          if(value === null || value === undefined) {\n            this.removeAttribute(attributeName);\n          } else {\n            this.setAttribute(attributeName, value);\n          }\n        }));\n      });\n    }\n\n    private mount() {\n      let savedAttributes: AttributesRecord<ObservedAttribute>;\n\n      // can happen only on hmr\n      if(this.disposeStores) savedAttributes = unwrap(this.attributesStore);\n\n      this.unmount();\n      const ComponentToMount = SolidElement.Component;\n\n      this.initStores();\n      if(savedAttributes) Object.assign(this.attributesStore, savedAttributes);\n\n      const Wrapper = this.HotReloadGuard || ((props: ParentProps) => <>{props.children}</>);\n\n      // JSX is mandatory here for cleanup to work!\n      this.disposeContent = render(() => <Wrapper>{untrack(() => ComponentToMount(this.propsStore, this.attributesStore, this.controls))}</Wrapper>, this.mountPoint);\n    }\n\n    private unmount() {\n      this.disposeContent?.();\n      this.disposeStores?.();\n\n      this.disposeStores = this.disposeContent = undefined;\n\n      this.mountPoint.replaceChildren(); // Don't leave trash in there\n    }\n\n    get [Symbol.toStringTag]() {\n      return className;\n    }\n  };\n\n  customElements.define(name, SolidElement);\n\n  return SolidElement;\n}\n\nfunction burgerToPascal(str: string) {\n  return str\n  .split('-')\n  .map(part => part.charAt(0).toUpperCase() + part.slice(1))\n  .join('');\n}\n","import {IconTsx} from '@components/iconTsx';\nimport {ProgressCircleSVG} from '@components/progressCircleSVG';\nimport ripple from '@components/ripple';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {attachHotClassName} from '@helpers/solid/classname';\nimport defineSolidElement, {PassedProps} from '@lib/solidjs/defineSolidElement';\nimport {createEffect, createSignal, onCleanup, Show} from 'solid-js';\nimport {Transition} from 'solid-transition-group';\nimport styles from './attachMenuButton.module.scss';\n\nif(import.meta.hot) import.meta.hot.accept();\n\n\ntype Props = {\n  isEditing?: boolean;\n  isLoading?: boolean;\n  loadingProgress?: number;\n  onCancel?: () => void;\n};\n\nconst AttachMenuButton = defineSolidElement({\n  name: 'attach-menu-button',\n  component: (props: PassedProps<Props>) => {\n    attachHotClassName(props.element, styles.Container, 'btn-menu-toggle', 'btn-icon');\n    ripple(props.element, () => true);\n\n    const [loadingContainer, setLoadingContainer] = createSignal<HTMLDivElement>();\n\n    createEffect(() => {\n      if(!props.isLoading) return;\n\n      props.element.classList.add(styles.disabled);\n      onCleanup(() => props.element.classList.remove(styles.disabled));\n    });\n\n    // Workaround around a workaround\n    createEffect(() => {\n      if(!loadingContainer()) return;\n\n      const clean = attachClickEvent(loadingContainer(), (e) => {\n        e.stopPropagation();\n        props.onCancel?.();\n      });\n\n      onCleanup(clean);\n    });\n\n    return (\n      <>\n        {/* <Transition name='fade' mode=\"outin\">*/}\n        <Show when={!props.isLoading}>\n          <IconTsx\n            class={`${styles.Icon} button-icon`}\n            classList={{\n              [styles.hidden]: props.isLoading\n            }}\n            icon={props.isEditing ? 'attach_edit' : 'attach'}\n          />\n        </Show>\n        <Show when={props.isLoading}>\n          <span ref={setLoadingContainer} class={styles.LoadingContainer}>\n            <IconTsx\n              class={`${styles.Icon} ${styles.close} button-icon`}\n              icon='close'\n            />\n            <ProgressCircleSVG\n              class={styles.Loader}\n              progress={props.loadingProgress}\n              strokeThickness={1 / 10}\n              stroke='currentColor'\n              animate\n            />\n          </span>\n        </Show>\n        {/* </Transition>*/}\n      </>\n    );\n  }\n});\n\nexport default AttachMenuButton;\n","export const BITRATE_TARGET_FPS = 30;\n\nexport const highResCodec = {\n  codec: 'avc1.4d4028',\n  width: 1920,\n  height: 1080,\n  bitrate: 20e6\n};\n\nexport const defaultCodec = {\n  codec: 'avc1.42001f',\n  width: 1280,\n  height: 720,\n  bitrate: 14e6\n};\n\nexport default function calcCodecAndBitrate(w: number, h: number, fps: typeof BITRATE_TARGET_FPS) {\n  const {codec, width, height, bitrate} = h > defaultCodec.height || w > defaultCodec.width ? highResCodec : defaultCodec;\n\n  return {\n    codec,\n    bitrate: w * h * fps / (width * height * BITRATE_TARGET_FPS) * bitrate\n  };\n}\n","import {defaultCodec, highResCodec} from '@components/mediaEditor/finalRender/calcCodecAndBitrate';\n\nlet\n  supportsVideo: Promise<boolean>,\n  supportsAudio: Promise<boolean>\n;\n\nexport const MAX_EDITABLE_VIDEO_SIZE = 100 * 1024 * 1024; // 100 MB\n\nexport const supportsVideoEncoding = () => supportsVideo ??= (async() => {\n  const configs: VideoEncoderConfig[] = [highResCodec, defaultCodec];\n\n  for(const config of configs) {\n    try {\n      const support = await VideoEncoder.isConfigSupported(config);\n      if(!support.supported) return false;\n    } catch{\n      return false;\n    }\n  }\n\n  return true;\n})();\n\nexport const supportsAudioEncoding = () => supportsAudio ??= (async() => {\n  const config: AudioEncoderConfig = {\n    codec: 'opus',\n    sampleRate: 48000,\n    numberOfChannels: 2,\n    bitrate: 128_000\n  };\n\n  try {\n    const support = await AudioEncoder.isConfigSupported(config);\n    return !!support.supported;\n  } catch{\n    return false;\n  }\n})();\n","/**\n * Doesn't do anything, just annotates that something is tracked (in solid-js)\n *\n * @example\n * track(() => [props.size, props.color]);\n */\nexport default function track(cb: () => any) {\n  cb();\n}\n","import {MessageEntity} from '@layer';\n\n\nexport default function trimRichText(text: string, entities: MessageEntity[]) {\n  entities = structuredClone(entities);\n  let prevLength = text.length;\n\n  // trim left\n  text = text.replace(/^\\s*/, '');\n  let diff = prevLength - text.length;\n\n  if(diff) {\n    entities.forEach((entity) => {\n      entity.offset = Math.max(0, entity.offset - diff);\n    });\n  }\n\n  prevLength = text.length;\n\n  // trim right\n  text = text.replace(/\\s*$/, '');\n  diff = prevLength - text.length;\n\n  if(diff) {\n    entities.forEach((entity) => {\n      // pull an entity whose offset fell into the trimmed trailing whitespace\n      // back inside the text, then clamp its length so it never overflows or\n      // goes negative\n      if(entity.offset > text.length) {\n        entity.offset = text.length;\n      }\n\n      if((entity.offset + entity.length) > text.length) {\n        entity.length = text.length - entity.offset;\n      }\n    });\n  }\n\n  // drop entities that ended up empty after trimming (they no longer reference\n  // any real text)\n  entities = entities.filter((entity) => entity.length > 0);\n\n  return {text, entities};\n}\n","import Button from '@components/buttonTsx';\nimport {OverlayedIcon} from '@components/icon';\nimport type InputField from '@components/inputField';\nimport {observeResize} from '@components/resizeObserver';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport track from '@helpers/solid/track';\nimport classNames from '@helpers/string/classNames';\nimport trimRichText from '@lib/richTextProcessor/trimRichText';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport {resolveFirst} from '@solid-primitives/refs';\nimport {LocalTextWithEntities} from '@types';\nimport {Accessor, createEffect, createMemo, createSignal, onCleanup} from 'solid-js';\nimport type ChatInput from '../input';\nimport {ChatType} from '../chatType';\nimport namedPromises from '@helpers/namedPromises';\n\nexport const defaultShouldShowFromHeight = 72;\n\ntype UseAiEditorButtonArgs = {\n  instance: ChatInput;\n  class?: string;\n  container: Accessor<HTMLDivElement>;\n  appendTo: () => HTMLDivElement;\n  inputField: () => InputField;\n  onApply: (text: LocalTextWithEntities) => void;\n  canSend: boolean;\n  shouldShowFromHeight?: Accessor<number>;\n  forceHidden?: Accessor<boolean>;\n};\n\nexport function useAiEditorButton({\n  instance,\n  inputField,\n  onApply,\n  class: className,\n  container,\n  appendTo,\n  canSend,\n  shouldShowFromHeight = () => defaultShouldShowFromHeight,\n  forceHidden = () => false\n}: UseAiEditorButtonArgs) {\n  const [containerHeight, setContainerHeight] = createSignal(0);\n  const canShowButton = createMemo(() => containerHeight() >= shouldShowFromHeight() && !forceHidden());\n\n  createEffect(() => {\n    if(!container()) return;\n\n    const unobserve = observeResize(container(), (entry) => {\n      setContainerHeight(entry.contentRect.height);\n    });\n\n    onCleanup(() => unobserve());\n  });\n\n  createEffect(() => {\n    track(canShowButton); // appendTo might not be reactive\n    if(!appendTo() || !inputField() || !canShowButton()) return;\n\n    createAiEditorButton({instance, appendTo: appendTo(), inputField: inputField(), onApply, class: className, canSend});\n  });\n}\n\ntype CreateAiEditorButtonArgs = {\n  instance: ChatInput;\n  appendTo: HTMLDivElement;\n  inputField: InputField;\n  onApply: (text: LocalTextWithEntities) => void;\n  canSend: boolean;\n  class?: string;\n};\n\nconst createAiEditorButton = ({instance, inputField, appendTo, onApply, class: className, canSend}: CreateAiEditorButtonArgs) => {\n  const {HotReloadGuard, rootScope} = useHotReloadGuard();\n\n  const icon = OverlayedIcon([\n    'ai_letters',\n    {icon: 'ai_star1', className: 'chat-input-ai-editor-button__star-1'},\n    {icon: 'ai_star2', className: 'chat-input-ai-editor-button__star-2'}\n  ], 'chat-input-ai-editor-button__icon');\n\n  const getInitialTones = async() => {\n    const ackedTones = await rootScope.managers.acknowledged.aiTonesManager.getTones();\n    return ackedTones.cached ? ackedTones.result : undefined;\n  };\n\n  const button = Button({\n    class: classNames('chat-input-ai-editor-button', className, 'btn-icon'),\n    children: icon,\n    onClick: async() => {\n      const {value, entities} = getRichValueWithCaret(inputField.input, true, false);\n\n      const {module: {openAiEditorPopup}, initialTones} = await namedPromises({\n        module: import('@components/popups/aiEditorPopup'),\n        initialTones: getInitialTones()\n      });\n\n      openAiEditorPopup({\n        peerId: instance.chat.peerId,\n        text: {\n          _: 'textWithEntities',\n          ...trimRichText(value, entities)\n        },\n        onApply,\n        canSendWhenOnline: instance.canSendWhenOnline,\n        isScheduled: instance.chat.type === ChatType.Scheduled,\n        onSend: !instance.chat.starsAmount && !instance.editMsgId && canSend ? async(text, options) => {\n          const sendingParams = {\n            ...instance.chat.getMessageSendingParams(),\n            // The AI editor manages its own send options, so override these fields\n            // outright instead of merging — otherwise the composer's pending\n            // silent/schedule/effect state (e.g. from a draft) leaks into the send\n            silent: options?.silent,\n            scheduleDate: options?.scheduleDate,\n            scheduleRepeatPeriod: options?.scheduleRepeatPeriod,\n            effect: options?.effect\n          };\n\n          const result = await instance.Class.sendMessageWithForward({\n            text,\n            slowModeParams: instance.getDefaultParamsForSlowModeTooltip(),\n            chatType: instance.chat.type,\n            paidMessageInterceptor: instance.paidMessageInterceptor,\n            sendingParams\n          });\n\n          if(result) instance.setInputValue('');\n        } : undefined,\n        initialTones\n      }, HotReloadGuard);\n    }\n  });\n\n  const child = resolveFirst(() => button);\n  const element = child();\n\n  appendTo.append(element);\n\n  onCleanup(() => {\n    element.remove();\n  });\n};\n","import {createEffect, onCleanup} from 'solid-js';\nimport type {ChatInputStateContext} from './index';\n\n\nexport default function useDirectMessages({instance, store}: ChatInputStateContext) {\n  createEffect(() => {\n    if(!store.isMonoforumAllChats) return;\n\n    instance.getPlaceholderParams().then((params) => instance.updateMessageInputPlaceholder(params));\n\n    if(store.isReplying) return;\n\n    instance.messageInputField?.input?.classList.add('hide');\n    instance.attachMenu?.classList.add('hide');\n    instance.messageInputField?.setHidden(true);\n    instance.btnToggleEmoticons?.setAttribute('disabled', '');\n    instance.btnSend?.setAttribute('disabled', '');\n    instance.btnSend?.classList.add('disabled');\n\n    instance.autocompleteHelperController.hideOtherHelpers();\n\n    onCleanup(() => {\n      instance.messageInputField?.input?.classList.remove('hide');\n      instance.attachMenu?.classList.remove('hide');\n      instance.messageInputField?.setHidden(false);\n      instance.btnToggleEmoticons?.removeAttribute('disabled');\n      instance.btnSend?.removeAttribute('disabled');\n      instance.btnSend?.classList.remove('disabled');\n    });\n  });\n\n  createEffect(() => {\n    instance.getPlaceholderParams().then((params) => instance.updateMessageInputPlaceholder(params));\n\n    if(!store.isSuggestingUneditablePostChange) return;\n\n    instance.messageInputField?.input?.classList.add('hide');\n    instance.messageInputField?.setHidden(true);\n    instance.btnToggleEmoticons?.setAttribute('disabled', '');\n    instance.autocompleteHelperController.hideOtherHelpers();\n\n    onCleanup(() => {\n      instance.messageInputField?.input?.classList.remove('hide');\n      instance.messageInputField?.setHidden(false);\n      instance.btnToggleEmoticons?.removeAttribute('disabled');\n    });\n  });\n\n  const canPaste = () => !store.isMonoforumAllChats || store.isReplying;\n\n  return {canPaste};\n}\n","import {createEffect, createMemo, on} from 'solid-js';\nimport type {ChatInputStateContext} from './index';\n\n\nexport default function useFileInput({instance, store}: ChatInputStateContext) {\n  const isMultiple = createMemo(() => !store.isEditing && !store.isSuggesting);\n\n  createEffect(() => {\n    if(!instance.fileInput) return;\n    instance.fileInput.multiple = isMultiple();\n  });\n\n  createEffect(on(() => store.isEditing, (isEditing) => {\n    instance.attachMenu.feedProps({\n      isEditing: isEditing\n    });\n  }, {\n    defer: true\n  }));\n}\n","import {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport {createEffect, createMemo} from 'solid-js';\nimport type {ChatInputStateContext} from './index';\n\n\nexport default function useStarsState({instance, store}: ChatInputStateContext) {\n  const canSend = createMemo(() => store.hasSendButton && !!store.starsAmount);\n  const hasSomethingToSend = createMemo(() => !!store.messageCount || !!store.forwarding || store.isRecording);\n\n  const isVisible = createMemo(() => canSend() && hasSomethingToSend());\n\n  const totalStarsAmount = createMemo(() => store.starsAmount * Math.max(1, store.forwarding + store.messageCount));\n  const forwardedMessagesStarsAmount = createMemo(() => store.starsAmount /* * Math.max(1, store.forwarding) */);\n\n  createEffect(() => {\n    if(!store.starsBadgeInited) return;\n    instance.starsBadge.classList.toggle('btn-send-stars-badge--active', isVisible());\n  });\n\n  createEffect(() => {\n    if(!store.starsBadgeInited) return;\n    instance.starsBadgeStars.innerText = !isNaN(totalStarsAmount()) ? numberThousandSplitterForStars(totalStarsAmount()) : '';\n  });\n\n  createEffect(() => {\n    if(!store.starsBadgeInited || !store.inputStarsCountEl || !forwardedMessagesStarsAmount()) return;\n\n    store.inputStarsCountEl.textContent = numberThousandSplitterForStars(forwardedMessagesStarsAmount());\n  });\n}\n","import wrapDraftText from '@lib/richTextProcessor/wrapDraftText';\nimport {createRoot} from 'solid-js';\nimport {createStore, SetStoreFunction} from 'solid-js/store';\nimport type ChatInput from '../input';\nimport {useAiEditorButton} from './useAiEditorButton';\nimport useDirectMessages from './useDirectMessages';\nimport useFileInput from './useFileInput';\nimport useStarsState from './useStarsState';\n\n\nexport interface ChatInputStateStore {\n  // * stars\n  starsBadgeInited: boolean;\n  inputStarsCountEl: null | HTMLElement;\n  hasSendButton: boolean;\n  isRecording: boolean;\n  messageCount: number;\n  forwarding: number;\n  starsAmount: number;\n\n  // * file input\n  isEditing: boolean;\n  isSuggesting: boolean;\n\n  // * direct messages\n  isMonoforumAllChats: boolean;\n  isReplying: boolean;\n  isSuggestingUneditablePostChange: boolean;\n\n  inputMessageContainerInited: boolean;\n}\n\nexport type ChatInputState = ReturnType<typeof createChatInputState>;\n\nexport type ChatInputStateContext = {\n  instance: ChatInput;\n  store: ChatInputStateStore;\n  setStore: SetStoreFunction<ChatInputStateStore>;\n};\n\nconst DEFAULT_STORE: ChatInputStateStore = {\n  starsBadgeInited: false,\n  inputStarsCountEl: null,\n  hasSendButton: false,\n  isRecording: false,\n  messageCount: 0,\n  forwarding: 0,\n  starsAmount: 0,\n\n  isEditing: false,\n  isSuggesting: false,\n\n  isMonoforumAllChats: false,\n  isReplying: false,\n  isSuggestingUneditablePostChange: false,\n\n  inputMessageContainerInited: false\n};\n\nexport default function createChatInputState(instance: ChatInput, initial: ChatInputStateStore = DEFAULT_STORE) {\n  return createRoot((dispose) => {\n    instance.getMiddleware()?.onDestroy(() => void dispose());\n\n    const [store, set] = createStore<ChatInputStateStore>({...initial});\n\n    const context: ChatInputStateContext = {instance, store, setStore: set};\n\n    useStarsState(context);\n    useFileInput(context);\n\n    const {canPaste} = useDirectMessages(context);\n\n    useAiEditorButton({\n      forceHidden: () => store.messageCount !== 1,\n      // Upstream additionally waits for the composer to grow to 72px, about three\n      // lines, before this appears. The line above already says there is exactly\n      // one message worth of text to rewrite — messageCount is 0 on an empty input\n      // and 2+ once the text splits — so the height check adds nothing except\n      // hiding the button from anyone writing a normal short reply.\n      shouldShowFromHeight: () => 0,\n      instance,\n      container: () => {\n        if(store.inputMessageContainerInited) return instance.inputMessageContainer;\n      },\n      inputField: () => instance.messageInputField,\n      onApply: (text) => {\n        const node = wrapDraftText(text.text, {\n          entities: text.entities,\n          middleware: instance.getMiddleware(),\n          wrappingForPeerId: instance.chat.peerId\n        });\n        instance.setInputValue(node, false, true);\n      },\n      appendTo: () => instance.newMessageWrapper,\n      canSend: true\n    });\n\n    return {store, set, canPaste, dispose};\n  });\n}\n","import {createRoot} from 'solid-js';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\n/**\n * If your function creates and returns computations (e.g. signals, effects, etc.), make sure it is wrapped in a `createRoot` call.\n */\nexport function runWithHotReloadGuard<T>(fn: () => T): T {\n  let result: T;\n\n  const dispose = createRoot((dispose) => {\n    (\n      <SolidJSHotReloadGuardProvider>\n        {void (result = fn())}\n      </SolidJSHotReloadGuardProvider>\n    );\n\n    return dispose;\n  });\n\n  dispose();\n\n  return result;\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport getDocumentInput from '@appManagers/utils/docs/getDocumentInput';\nimport type {MyDraftMessage} from '@appManagers/appDraftsManager';\nimport type {AppMessagesManager, MessageSendingParams, MyMessage, SuggestedPostPayload} from '@appManagers/appMessagesManager';\nimport type Chat from '@components/chat/chat';\nimport {AppImManager, APP_TABS} from '@lib/appImManager';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ChatRecording from '@components/chat/recording/chatRecording';\nimport {ButtonMenuItemOptions, ButtonMenuItemOptionsVerifiable, ButtonMenuSync} from '@components/buttonMenu';\nimport emoticonsDropdown, {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport showForwardPopup from '@components/popups/forward';\nimport PopupNewMedia, {getCurrentNewMediaPopup} from '@components/popups/newMedia';\nimport {toast, toastNew} from '@components/toast';\nimport {MessageEntity, DraftMessage, WebPage, Message, UserFull, AttachMenuPeerType, BotMenuButton, MessageMedia, InputReplyTo, Chat as MTChat, User, ChatFull, Dialog, PhotoSize, Photo, Document, TextWithEntities, GlobalPrivacySettings} from '@layer';\nimport StickersHelper from '@components/chat/stickersHelper';\nimport ChatInputPlate from '@components/chat/controlPlate';\nimport PopupSendGift from '@components/popups/sendGift';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport Button, {replaceButtonIcon} from '@components/button';\nimport showScheduleSendingPopup from '@components/popups/scheduleSendingPopup';\nimport SendMenu from '@components/chat/sendContextMenu';\nimport rootScope from '@lib/rootScope';\nimport {useIsCrmReadOnly} from '@stores/crmRole';\nimport PopupPinMessage from '@components/popups/unpinMessage';\nimport tsNow from '@helpers/tsNow';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport {IS_MOBILE, IS_MOBILE_SAFARI} from '@environment/userAgent';\nimport I18n, {FormatterArguments, i18n, join, LangPackKey} from '@lib/langPack';\nimport {AttachedMediaType, canUploadAsWhenEditing, generateTail, getMediaTypeForMessage, slowModeTimer} from '@components/chat/utils';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport ButtonCorner from '@components/buttonCorner';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport cancelSelection from '@helpers/dom/cancelSelection';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport isInputEmpty from '@helpers/dom/isInputEmpty';\nimport isSendShortcutPressed from '@helpers/dom/isSendShortcutPressed';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport classifyInputKeyup from '@helpers/dom/classifyInputKeyup';\nimport isPlausibleEmojiQuery from '@components/chat/isPlausibleEmojiQuery';\nimport EmojiHelper from '@components/chat/emojiHelper';\nimport CommandsHelper from '@components/chat/commandsHelper';\nimport QuickRepliesHelper from '@components/chat/quickRepliesHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport AutocompleteHelper from '@components/c