et.\n  let notesTicketId: number | null = null;\n\n  // Token to discard responses for a peer the user already navigated away from.\n  let currentPeerId: PeerId;\n  // Bumps on every load() so a stale in-flight response can't overwrite a newer one.\n  let loadGeneration = 0;\n\n  const openCrmLogin = () => showCrmLoginIfNeeded();\n\n  const plate = createTopbarPlate({\n    modifier: className,\n    height: 52,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: () => (\n      <CrmTicketPlateBody\n        ticket={ticket}\n        loadState={loadState}\n        busy={busy}\n        reconnectNeeded={reconnectNeeded}\n        onClose={() => closeTicket()}\n        onReconnect={openCrmLogin}\n        onRetry={() => load(currentPeerId, 0, true)}\n      />\n    )\n  });\n\n  const syncPlateVisibility = (found?: CrmTicketRef) => {\n    if(reconnectNeeded()) {\n      plate.setHidden(false);\n      return;\n    }\n    if(loadState() === 'loading' || loadState() === 'failed') {\n      plate.setHidden(false);\n      return;\n    }\n    plate.setHidden(!found || found.status !== 'open');\n  };\n\n  const hide = () => {\n    plate.setHidden(true);\n    setTicket(undefined);\n    setLoadState('idle');\n    setReconnectNeeded(false);\n  };\n\n  // Reflect a ticket: the bar shows ONLY for an open ticket (a closed ticket is\n  // terminal in this CRM — the next message opens a NEW ticket). Always emit the\n  // event so the timeline dividers stay in sync, even when the bar is hidden.\n  const apply = (peerId: PeerId, found?: CrmTicketRef) => {\n    if(peerId !== currentPeerId) return;\n    setTicket(found);\n    syncPlateVisibility(found);\n    rootScope.dispatchEvent('crm_ticket_update', {peerId, ticket: found});\n  };\n\n  const load = async(peerId: PeerId, attempt = 0, toastOnFailure = false) => {\n    if(!peerId?.isUser()) {\n      setLoadState('idle');\n      apply(peerId, undefined);\n      return;\n    }\n\n    const generation = ++loadGeneration;\n    const chatId = '' + peerId.toUserId();\n\n    const connected = await managers.appCrmManager.isConnected();\n    if(peerId !== currentPeerId || generation !== loadGeneration) return;\n\n    if(!connected) {\n      setReconnectNeeded(true);\n      setLoadState('idle');\n      plate.setHidden(false);\n      return;\n    }\n\n    setReconnectNeeded(false);\n    setLoadState('loading');\n    plate.setHidden(false);\n\n    const result = await managers.appCrmManager.getTicketByTelegram(chatId);\n    if(peerId !== currentPeerId || generation !== loadGeneration) return;\n\n    if(result.failed) {\n      if(attempt < LOAD_RETRIES) {\n        await pause(LOAD_RETRY_MS * (attempt + 1));\n        if(peerId === currentPeerId && generation === loadGeneration) {\n          return load(peerId, attempt + 1, toastOnFailure);\n        }\n        return;\n      }\n\n      setLoadState('failed');\n      setTicket(undefined);\n      plate.setHidden(false);\n      rootScope.dispatchEvent('crm_ticket_update', {peerId, ticket: undefined});\n      if(toastOnFailure) {\n        toastNew({langPackKey: 'Crm.Ticket.LoadFailed'});\n      }\n      return;\n    }\n\n    setLoadState('idle');\n    const found = result.noTicket ? undefined : result.ticket;\n    apply(peerId, found);\n  };\n\n  /** Cached backfill chats may never fire history_multiappend — retry once after open. */\n  const scheduleFollowUpLoad = (peerId: PeerId) => {\n    pause(FOLLOWUP_LOAD_MS).then(() => {\n      if(peerId !== currentPeerId) return;\n      const current = ticket();\n      if(current?.status === 'open') return;\n      if(loadState() === 'failed') return;\n      load(peerId);\n    });\n  };\n\n  // Per-message author map for the chat: every agent session labels outbound\n  // bubbles with who replied, even though all agents share one Telegram account.\n  const loadAttributions = (peerId: PeerId) => {\n    if(!peerId?.isUser()) {\n      crmRealtime.leave();\n      rootScope.dispatchEvent('crm_attributions_update', {peerId, attributions: {}});\n      return;\n    }\n\n    managers.appCrmManager.isConnected().then((connected) => {\n      if(peerId !== currentPeerId) return;\n      if(!connected) {\n        setReconnectNeeded(true);\n        plate.setHidden(false);\n        return;\n      }\n      crmRealtime.subscribePeer(peerId, '' + peerId.toUserId());\n      managers.appCrmManager.getAttributionsByTelegram('' + peerId.toUserId()).then((attributions) => {\n        if(peerId !== currentPeerId) return;\n        rootScope.dispatchEvent('crm_attributions_update', {peerId, attributions});\n      });\n    });\n  };\n\n  // Per-message FIRST VIEWER map: which agent displayed each customer message\n  // while it was still unread. Backfill on chat open; the `inbound.seen` push\n  // (on the attribution channel, subscribed above) keeps it live.\n  const loadFirstSeen = (peerId: PeerId) => {\n    if(!peerId?.isUser()) {\n      rootScope.dispatchEvent('crm_first_seen_update', {peerId, firstSeen: {}});\n      return;\n    }\n\n    managers.appCrmManager.isConnected().then((connected) => {\n      if(peerId !== currentPeerId || !connected) return;\n      managers.appCrmManager.getFirstSeenByTelegram('' + peerId.toUserId()).then((firstSeen) => {\n        if(peerId !== currentPeerId) return;\n        rootScope.dispatchEvent('crm_first_seen_update', {peerId, firstSeen});\n      });\n    });\n  };\n\n  // Sensitive-message reveal state: which blurred messages THIS agent may see,\n  // plus pending requests for superadmins. Backfill on chat open; the Reverb\n  // push (subscribed alongside attributions) keeps it live.\n  const loadSensitiveReveals = (peerId: PeerId) => {\n    if(!peerId?.isUser()) {\n      rootScope.dispatchEvent('crm_sensitive_reveals_update', {peerId, state: {approved: [], pending: []}});\n      return;\n    }\n\n    managers.appCrmManager.isConnected().then((connected) => {\n      if(peerId !== currentPeerId || !connected) return;\n      managers.appCrmManager.getSensitiveReveals('' + peerId.toUserId()).then((state) => {\n        if(peerId !== currentPeerId) return;\n        rootScope.dispatchEvent('crm_sensitive_reveals_update', {peerId, state});\n      });\n    });\n  };\n\n  // Internal agent notes for the chat: backfill on chat open; the Reverb push\n  // (subscribed alongside attributions) delivers a colleague's note live.\n  const applyNotes = (peerId: PeerId, list: CrmNote[]) => {\n    if(peerId !== currentPeerId) return;\n    setNotes(list);\n    rootScope.dispatchEvent('crm_notes_update', {peerId, notes: list});\n  };\n\n  const loadNotes = (peerId: PeerId) => {\n    if(!peerId?.isUser()) {\n      notesTicketId = null;\n      applyNotes(peerId, []);\n      return;\n    }\n\n    managers.appCrmManager.isConnected().then((connected) => {\n      if(peerId !== currentPeerId || !connected) return;\n      managers.appCrmManager.getNotesByTelegram('' + peerId.toUserId()).then((result) => {\n        if(peerId !== currentPeerId) return;\n        notesTicketId = result.ticketId;\n        applyNotes(peerId, result.notes);\n      });\n    });\n  };\n\n  // Merge a single live/optimistic note, dropping any existing row with the same\n  // id (the local optimistic append races the Reverb echo of our own note) and\n  // keeping the list ordered by creation time.\n  const mergeNote = (peerId: PeerId, note: CrmNote) => {\n    if(peerId !== currentPeerId || !note?.id) return;\n    const next = notes().filter((n) => n.id !== note.id);\n    next.push(note);\n    next.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());\n    applyNotes(peerId, next);\n  };\n\n  const dropNote = (peerId: PeerId, noteId: number) => {\n    if(peerId !== currentPeerId || !noteId) return;\n    const next = notes().filter((n) => n.id !== noteId);\n    if(next.length === notes().length) return;\n    applyNotes(peerId, next);\n  };\n\n  const addNote = async(text: string): Promise<CrmNote | undefined> => {\n    const value = (text || '').trim();\n    const peerId = currentPeerId;\n    if(!value || !peerId?.isUser()) return undefined;\n    try {\n      const note = await managers.appCrmManager.addNoteByTelegram('' + peerId.toUserId(), value);\n      if(!note) {\n        toastNew({langPackKey: 'Crm.Note.NoTicket'});\n        return undefined;\n      }\n      mergeNote(peerId, note);\n      return note;\n    } catch(err) {\n      const status = (err as Error & {status?: number})?.status;\n      toastNew({langPackKey: status === 404 ? 'Crm.Note.NoTicket' : 'Crm.Note.AddFailed'});\n      return undefined;\n    }\n  };\n\n  let claimedTicketId: number;\n\n  const setPeerId = (peerId: PeerId) => {\n    currentPeerId = peerId;\n    claimedTicketId = undefined;\n    notesTicketId = null;\n    setNotes([]);\n    loadGeneration++;\n    hide();\n    load(peerId);\n    scheduleFollowUpLoad(peerId);\n    loadAttributions(peerId);\n    loadFirstSeen(peerId);\n    loadSensitiveReveals(peerId);\n    loadNotes(peerId);\n  };\n\n  const maybeClaim = (peerId: PeerId) => {\n    if(!peerId?.isUser()) return;\n    const current = ticket();\n    if(current && current.status === 'open' && current.id === claimedTicketId) return;\n    if(current?.id) claimedTicketId = current.id;\n    managers.appCrmManager.claimTicketByTelegram('' + peerId.toUserId());\n  };\n\n  const attributeOutbound = (message: MyMessage) => {\n    const peerId = message.peerId;\n    if(!peerId?.isUser()) return;\n    const messageId = getServerMessageId(message.mid);\n    if(!messageId) return;\n    managers.appCrmManager.attributeOutboundMessage('' + peerId.toUserId(), messageId);\n  };\n\n  const refresh = debounce(() => {\n    load(currentPeerId);\n    loadAttributions(currentPeerId);\n    loadFirstSeen(currentPeerId);\n    loadSensitiveReveals(currentPeerId);\n    loadNotes(currentPeerId);\n  }, 800, false, true);\n\n  const onNotePush = ({peerId, note}: {peerId: PeerId, note: CrmNote}) => {\n    mergeNote(peerId, note);\n  };\n\n  const onNoteDeletePush = ({peerId, noteId}: {peerId: PeerId, noteId: number}) => {\n    dropNote(peerId, noteId);\n  };\n\n  const onChatMessage = (payload: MyMessage | {message: MyMessage}) => {\n    const message = (payload as {message: MyMessage})?.message ?? (payload as MyMessage);\n    if(message?.peerId && message.peerId === currentPeerId) refresh();\n  };\n\n  const onMessageSent = ({message}: {message: MyMessage}) => {\n    if(message?._ !== 'message' || !message.pFlags?.out || message.peerId !== currentPeerId) return;\n    maybeClaim(message.peerId);\n    attributeOutbound(message);\n  };\n\n  const onAuthRequired = () => {\n    if(!currentPeerId?.isUser()) return;\n    setReconnectNeeded(true);\n    setLoadState('idle');\n    plate.setHidden(false);\n  };\n\n  const onConfigUpdate = () => {\n    if(!currentPeerId?.isUser()) return;\n    setReconnectNeeded(false);\n    hide();\n    load(currentPeerId);\n    scheduleFollowUpLoad(currentPeerId);\n    loadAttributions(currentPeerId);\n    loadFirstSeen(currentPeerId);\n    loadSensitiveReveals(currentPeerId);\n    loadNotes(currentPeerId);\n  };\n\n  rootScope.addEventListener('history_multiappend', onChatMessage);\n  rootScope.addEventListener('message_sent', onChatMessage);\n  rootScope.addEventListener('message_sent', onMessageSent);\n  rootScope.addEventListener('crm_auth_required', onAuthRequired);\n  rootScope.addEventListener('crm_config_update', onConfigUpdate);\n  rootScope.addEventListener('crm_note_push', onNotePush);\n  rootScope.addEventListener('crm_note_delete_push', onNoteDeletePush);\n\n  const closeTicket = async() => {\n    const current = ticket();\n    if(!current || current.status !== 'open' || busy()) return;\n\n    const peerId = currentPeerId;\n    setBusy(true);\n    try {\n      await managers.appCrmManager.updateTicketStatus(current.id, 'closed');\n      if(peerId !== currentPeerId) return;\n      const event: CrmTicketEvent = {type: 'closed', at: new Date().toISOString()};\n      apply(peerId, {...current, status: 'closed', events: [...(current.events || []), event]});\n    } catch(err) {\n      const status = (err as Error & {status?: number})?.status;\n      toastNew({langPackKey: status === 403 ? 'Crm.Ticket.CloseForbidden' : 'Crm.Ticket.CloseFailed'});\n      if(peerId === currentPeerId) load(peerId, 0, true);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  return {\n    ...plate,\n    setPeerId,\n    hide,\n    getTicket: () => ticket(),\n    close: () => closeTicket(),\n    getNotes: () => notes(),\n    // Also true on notes alone: with cross-department sharing an agent can have\n    // no ticket of their own here and still have a colleague's shared note to read.\n    hasTicketForNotes: () => notesTicketId != null || ticket()?.status === 'open' || notes().length > 0,\n    addNote,\n    destroy: () => {\n      rootScope.removeEventListener('history_multiappend', onChatMessage);\n      rootScope.removeEventListener('message_sent', onChatMessage);\n      rootScope.removeEventListener('message_sent', onMessageSent);\n      rootScope.removeEventListener('crm_auth_required', onAuthRequired);\n      rootScope.removeEventListener('crm_config_update', onConfigUpdate);\n      rootScope.removeEventListener('crm_note_push', onNotePush);\n      rootScope.removeEventListener('crm_note_delete_push', onNoteDeletePush);\n      crmRealtime.leave();\n      plate.destroy();\n    }\n  };\n}\n","/**\n * Single place where every topbar floating plate (except the per-peer\n * `pinnedMessage` plate) is constructed, mounted, and torn down. Topbar\n * holds one `plates` field, lists/peers/destroy go through here.\n *\n * The pinned-message plate is excluded because it is recreated per peer\n * (its prepare/reveal lifecycle is driven from `topbar.setupPinnedMessageForPeer`).\n */\n\nimport type Chat from '@components/chat/chat';\nimport type ChatTopbar from '@components/chat/topbar';\nimport {AppManagers} from '@lib/managers';\nimport IS_LIVE_STREAM_SUPPORTED from '@environment/liveStreamSupport';\nimport createChatRequestsPlate, {ChatRequestsPlate} from '@components/chat/requests';\nimport createChatActionsPlate, {ChatActionsPlate} from '@components/chat/actions';\nimport createChatRemoveFeePlate, {ChatRemoveFeePlate} from '@components/chat/removeFee';\nimport createChatLivePlate, {ChatLivePlate} from '@components/chat/topbarLive/container';\nimport createChatTranslationPlate, {ChatTranslationPlate} from '@components/chat/translation';\nimport createChatSponsoredPlate, {ChatSponsoredPlate} from '@components/chat/topbarSponsored';\nimport createChatCrmTicketPlate, {ChatCrmTicketPlate} from '@components/chat/crmTicket';\nimport {TopbarPlateController} from '@components/chat/topbarPlate';\n\nexport type TopbarPlates = {\n  requests: ChatRequestsPlate,\n  actions: ChatActionsPlate,\n  removeFee: ChatRemoveFeePlate,\n  live: ChatLivePlate | undefined,\n  translation: ChatTranslationPlate,\n  sponsored: ChatSponsoredPlate,\n  crmTicket: ChatCrmTicketPlate,\n  /** Ordered list of all constructed plates. Used by `topbar.setFloating`. */\n  all: TopbarPlateController[],\n  /** Mount every plate's container into the given host. */\n  mount: (host: HTMLElement) => void,\n  destroy: () => void\n};\n\nexport function createTopbarPlates(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): TopbarPlates {\n  const requests = createChatRequestsPlate(topbar, chat, managers);\n  const actions = createChatActionsPlate(topbar, chat, managers);\n  const live = IS_LIVE_STREAM_SUPPORTED ? createChatLivePlate(topbar, chat, managers) : undefined;\n  const translation = createChatTranslationPlate(topbar, chat, managers);\n  const removeFee = createChatRemoveFeePlate(topbar, chat, managers);\n  const sponsored = createChatSponsoredPlate(topbar, chat, managers);\n  const crmTicket = createChatCrmTicketPlate(topbar, chat, managers);\n\n  // Order matches the visual stack inside `floatingPlatesWrapper`.\n  const all = [requests, actions, live, translation, removeFee, sponsored, crmTicket].filter(Boolean);\n\n  return {\n    requests,\n    actions,\n    removeFee,\n    live,\n    translation,\n    sponsored,\n    crmTicket,\n    all,\n    mount: (host) => host.append(...all.map((plate) => plate.container)),\n    destroy: () => all.forEach((plate) => plate.destroy())\n  };\n}\n","import showFeatureDetailsPopup from '@components/popups/featureDetails';\nimport {i18n} from '@lib/langPack';\n\nexport default function showNoForwardsPopup(onConfirm: () => void) {\n  showFeatureDetailsPopup({\n    title: i18n('DisableSharing'),\n    rows: [{\n      icon: 'sharingoff',\n      title: i18n('DisableSharing.Row1.Title'),\n      subtitle: i18n('DisableSharing.Row1.Subtitle')\n    }, {\n      icon: 'down_crossed',\n      title: i18n('DisableSharing.Row2.Title'),\n      subtitle: i18n('DisableSharing.Row2.Subtitle')\n    }],\n    buttons: [{\n      text: i18n('DisableSharing'),\n      onClick: onConfirm\n    }],\n    sticker: {\n      name: 'hand_stop'\n    }\n  });\n}\n","import {createEffect, createSignal, For, on, onCleanup, Show} from 'solid-js';\nimport Button from '@components/buttonTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport Scrollable from '@components/scrollable2';\nimport confirmationPopup from '@components/confirmationPopup';\nimport classNames from '@helpers/string/classNames';\nimport I18n, {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {CrmNote, CrmNoteVisibility} from '@lib/crm/types';\nimport {\n  addCrmNote,\n  canEditCrmNote,\n  deleteCrmNote,\n  isCrmNoteShared,\n  mergeCrmNote,\n  saveCrmNote,\n  sortCrmNotes\n} from '@lib/crm/notes';\nimport createCrmTaskFromText from '@lib/crm/createTask';\nimport {useIsCrmReadOnly} from '@stores/crmRole';\n\n// Internal-notes panel: agents leave context for each other on the customer's\n// ticket without messaging the customer. Self-contained so the SAME markup serves\n// both mounts — the topbar popup and the profile's shared-media tab — and either\n// one works on its own (it backfills from the CRM itself rather than borrowing the\n// chat plate's state).\n//\n// Cross-view sync rides the three rootScope events the chat plate already speaks:\n// `crm_notes_update` (a whole list, from a backfill or the plate) refreshes us,\n// `crm_note_push` (one note, from Reverb or from our own compose/edit) merges in,\n// and `crm_note_delete_push` removes one. Every write here goes through\n// @lib/crm/notes, which dispatches those same events — which is what keeps the\n// plate, the timeline chips, the popup and the sidebar tab consistent without any\n// of them owning the others.\nexport default function CrmNotesPanel(props: {\n  peerId: PeerId,\n  class?: string,\n  /** Give the list its own scroller (the popup). The sidebar tab scrolls as a whole. */\n  scroll?: boolean,\n  onCountChange?: (count: number) => void\n}) {\n  const [notes, setNotes] = createSignal<CrmNote[]>([]);\n  const [busy, setBusy] = createSignal(false);\n  const [text, setText] = createSignal('');\n  // Notes stay department-scoped unless the agent says otherwise — the toggle is\n  // for the occasional \"the other departments need to know this\", not the default.\n  const [shareAll, setShareAll] = createSignal(false);\n  // id of the note currently open for editing, plus its working copy.\n  const [editingId, setEditingId] = createSignal<number | undefined>();\n  const [editText, setEditText] = createSignal('');\n\n  const apply = (list: CrmNote[]) => {\n    setNotes(sortCrmNotes(list));\n    props.onCountChange?.(list.length);\n  };\n\n  // Bumps on every peer change so a stale response can't overwrite a newer one.\n  let generation = 0;\n  createEffect(on(() => props.peerId, (peerId) => {\n    const current = ++generation;\n    apply([]);\n    setText('');\n    setShareAll(false);\n    setEditingId(undefined);\n    if(!peerId?.isUser()) return;\n\n    rootScope.managers.appCrmManager.getNotesByTelegram('' + peerId.toUserId()).then((result) => {\n      if(generation !== current) return;\n      apply(result.notes || []);\n    });\n  }));\n\n  const onNotesUpdate = ({peerId, notes: list}: {peerId: PeerId, notes: CrmNote[]}) => {\n    if(peerId !== props.peerId) return;\n    apply(list || []);\n  };\n\n  const onNotePush = ({peerId, note}: {peerId: PeerId, note: CrmNote}) => {\n    if(peerId !== props.peerId) return;\n    apply(mergeCrmNote(notes(), note));\n  };\n\n  const onNoteDelete = ({peerId, noteId}: {peerId: PeerId, noteId: number}) => {\n    if(peerId !== props.peerId) return;\n    if(editingId() === noteId) setEditingId(undefined);\n    apply(notes().filter((n) => n.id !== noteId));\n  };\n\n  rootScope.addEventListener('crm_notes_update', onNotesUpdate);\n  rootScope.addEventListener('crm_note_push', onNotePush);\n  rootScope.addEventListener('crm_note_delete_push', onNoteDelete);\n  onCleanup(() => {\n    rootScope.removeEventListener('crm_notes_update', onNotesUpdate);\n    rootScope.removeEventListener('crm_note_push', onNotePush);\n    rootScope.removeEventListener('crm_note_delete_push', onNoteDelete);\n  });\n\n  const visibility = (): CrmNoteVisibility => shareAll() ? 'all' : 'department';\n\n  const submit = async() => {\n    const value = text().trim();\n    if(!value || busy()) return;\n\n    setBusy(true);\n    try {\n      const note = await addCrmNote(props.peerId, value, visibility());\n      if(note) {\n        setText('');\n        setShareAll(false);\n      }\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const startEdit = (note: CrmNote) => {\n    setEditingId(note.id);\n    setEditText(note.text || '');\n  };\n\n  const saveEdit = async(note: CrmNote) => {\n    const value = editText().trim();\n    if(!value || busy()) return;\n    if(value === note.text) {\n      setEditingId(undefined);\n      return;\n    }\n\n    setBusy(true);\n    try {\n      const saved = await saveCrmNote(props.peerId, note.id, {text: value});\n      if(saved) setEditingId(undefined);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const toggleShared = async(note: CrmNote, share: boolean) => {\n    if(busy()) return;\n    setBusy(true);\n    try {\n      await saveCrmNote(props.peerId, note.id, {visibility: share ? 'all' : 'department'});\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const remove = async(note: CrmNote) => {\n    try {\n      await confirmationPopup({\n        titleLangKey: 'Crm.Note.DeleteTitle',\n        descriptionLangKey: 'Crm.Note.DeleteConfirm',\n        button: {langKey: 'Delete', isDanger: true}\n      });\n    } catch(err) {\n      return; // dismissed — confirmationPopup rejects on cancel\n    }\n\n    setBusy(true);\n    try {\n      await deleteCrmNote(props.peerId, note.id);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  // Hand the note off as a task instead of leaving it for whoever reads next. The\n  // composer takes it from here; available on an inherited note too, since acting\n  // on another department's hand-off is the point of sharing it.\n  const convertToTask = (note: CrmNote) => {\n    createCrmTaskFromText(note.text || '', {peerId: props.peerId});\n  };\n\n  const formatTime = (iso: string) => {\n    const date = new Date(iso);\n    return isNaN(date.getTime()) ? '' : date.toLocaleString();\n  };\n\n  // Enter submits, Shift+Enter inserts a newline — mirrors composing a message.\n  const onComposeKeyDown = (e: KeyboardEvent) => {\n    if(e.key === 'Enter' && !e.shiftKey) {\n      e.preventDefault();\n      submit();\n    }\n  };\n\n  const onEditKeyDown = (e: KeyboardEvent, note: CrmNote) => {\n    if(e.key === 'Escape') {\n      e.preventDefault();\n      setEditingId(undefined);\n      return;\n    }\n\n    if(e.key === 'Enter' && !e.shiftKey) {\n      e.preventDefault();\n      saveEdit(note);\n    }\n  };\n\n  const noteItem = (note: CrmNote) => {\n    const editing = () => editingId() === note.id;\n    const editable = () => canEditCrmNote(note);\n\n    return (\n      <div class={classNames('crm-notes-item', note.is_foreign && 'crm-notes-item--foreign')}>\n        <div class=\"crm-notes-item-head\">\n          <span class=\"crm-notes-item-author\">{note.author_name}</span>\n          {/* Where a note came from only matters once it can travel: a shared note\n              reads differently depending on whether this is the department that\n              wrote it or one that inherited it. */}\n          <Show when={note.is_foreign && note.department_name}>\n            <span class=\"crm-notes-item-badge crm-notes-item-badge--foreign\">\n              {i18n('Crm.Note.FromDepartment', [note.department_name])}\n            </span>\n          </Show>\n          <Show when={!note.is_foreign && isCrmNoteShared(note)}>\n            <span class=\"crm-notes-item-badge\">{i18n('Crm.Note.SharedBadge')}</span>\n          </Show>\n          <span class=\"crm-notes-item-time\">\n            {formatTime(note.created_at)}\n            <Show when={note.edited_at}>\n              {' · '}{i18n('Crm.Note.Edited')}\n            </Show>\n          </span>\n          <Show when={!editing() && !useIsCrmReadOnly()()}>\n            <span class=\"crm-notes-item-actions\">\n              <button\n                class=\"crm-notes-item-action\"\n                title={I18n.format('Crm.Note.ConvertToTask', true)}\n                onClick={() => convertToTask(note)}\n              >\n                <IconTsx icon=\"check\" />\n              </button>\n              <Show when={editable()}>\n                <button\n                  class=\"crm-notes-item-action\"\n                  title={I18n.format('Edit', true)}\n                  onClick={() => startEdit(note)}\n                >\n                  <IconTsx icon=\"edit\" />\n                </button>\n                <button\n                  class=\"crm-notes-item-action crm-notes-item-action--danger\"\n                  title={I18n.format('Delete', true)}\n                  onClick={() => remove(note)}\n                >\n                  <IconTsx icon=\"delete\" />\n                </button>\n              </Show>\n            </span>\n          </Show>\n        </div>\n\n        <Show\n          when={editing()}\n          fallback={<div class=\"crm-notes-item-text\">{note.text}</div>}\n        >\n          <textarea\n            class=\"crm-notes-textarea\"\n            rows={3}\n            value={editText()}\n            disabled={busy()}\n            ref={(el) => queueMicrotask(() => el.focus())}\n            onInput={(e) => setEditText(e.currentTarget.value)}\n            onKeyDown={(e) => onEditKeyDown(e, note)}\n          />\n          <div class=\"crm-notes-item-edit-actions\">\n            <CheckboxFieldTsx\n              toggle\n              text=\"Crm.Note.ShareAllDepartments\"\n              checked={isCrmNoteShared(note)}\n              onChange={(checked) => toggleShared(note, checked)}\n            />\n            <div class=\"crm-notes-item-edit-buttons\">\n              <Button\n                class=\"btn-primary btn-transparent primary\"\n                onClick={() => setEditingId(undefined)}\n              >\n                {i18n('Cancel')}\n              </Button>\n              <Button\n                class=\"btn-primary btn-color-primary\"\n                disabled={busy() || !editText().trim()}\n                onClick={() => saveEdit(note)}\n              >\n                {i18n('Save')}\n              </Button>\n            </div>\n          </div>\n        </Show>\n      </div>\n    );\n  };\n\n  const list = () => <For each={notes()}>{noteItem}</For>;\n\n  return (\n    <div class={classNames('crm-notes', props.scroll && 'crm-notes--scroll', props.class)}>\n      <Show\n        when={notes().length}\n        fallback={<div class=\"crm-notes-empty\">{i18n('Crm.Note.None')}</div>}\n      >\n        <Show when={props.scroll} fallback={<div class=\"crm-notes-list\">{list()}</div>}>\n          <Scrollable class=\"crm-notes-list\">{list()}</Scrollable>\n        </Show>\n      </Show>\n      {/* Read-only trainees still READ their colleagues' notes — that is most of\n          the value during onboarding — they just have no way to add one. */}\n      <Show when={!useIsCrmReadOnly()()}>\n        <div class=\"crm-notes-compose\">\n          <textarea\n            class=\"crm-notes-textarea\"\n            rows={3}\n            placeholder={I18n.format('Crm.Note.Placeholder', true)}\n            value={text()}\n            disabled={busy()}\n            onInput={(e) => setText(e.currentTarget.value)}\n            onKeyDown={onComposeKeyDown}\n          />\n          <CheckboxFieldTsx\n            class=\"crm-notes-share\"\n            toggle\n            text=\"Crm.Note.ShareAllDepartments\"\n            checked={shareAll()}\n            onChange={setShareAll}\n          />\n          <Button\n            class=\"btn-primary btn-color-primary crm-notes-submit\"\n            disabled={busy() || !text().trim()}\n            onClick={submit}\n          >\n            {i18n('Crm.Note.Add')}\n          </Button>\n        </div>\n      </Show>\n    </div>\n  );\n}\n\n","import PopupElement from '.';\nimport CrmNotesPanel from '@components/crmNotesPanel';\n\n// Topbar route to the internal notes. The panel itself is shared with the\n// profile's shared-media \"Notes\" tab — see @components/crmNotesPanel.\nexport default class PopupCrmNotes extends PopupElement {\n  constructor(private peerId: PeerId) {\n    super('popup-crm-notes', {\n      title: 'Crm.Note.PanelTitle',\n      body: true,\n      closable: true\n    });\n\n    this.appendSolidBody(() => <CrmNotesPanel peerId={this.peerId} scroll />);\n    this.show();\n  }\n}\n\nexport function showCrmNotesPopup(peerId: PeerId) {\n  new PopupCrmNotes(peerId);\n}\n","import {createEffect, createSignal, For, on, onCleanup, Show} from 'solid-js';\nimport Scrollable from '@components/scrollable2';\nimport classNames from '@helpers/string/classNames';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {CrmContract, CrmContractsResult} from '@lib/crm/types';\n\n// The customer's contracts at andro.law, read through the CRM.\n//\n// Self-contained so the SAME markup serves both mounts, exactly like\n// @components/crmNotesPanel: the topbar popup and the profile's shared-media\n// \"Contracts\" tab. Read-only by design. Issuing a contract needs a template\n// form and a preflight round-trip against the customer's andro.law profile,\n// which belongs in the CRM panel, not in a chat client.\n//\n// There is no realtime channel for contracts and deliberately so: they change\n// when a customer signs something at andro.law, which the CRM only learns about\n// by asking. Reopening the panel is the refresh.\n\nconst EMPTY: CrmContractsResult = {\n  enabled: false,\n  hasAccount: false,\n  contracts: [],\n  counts: {total: 0, active: 0, awaiting_signature: 0, expiring_soon: 0}\n};\n\nexport default function CrmContractsPanel(props: {\n  peerId: PeerId,\n  class?: string,\n  /** Give the list its own scroller (the popup). The sidebar tab scrolls as a whole. */\n  scroll?: boolean,\n  onCountChange?: (count: number) => void\n}) {\n  const [result, setResult] = createSignal<CrmContractsResult>(EMPTY);\n  const [loading, setLoading] = createSignal(false);\n  // File id currently being fetched, so the row can show it is working. A cold\n  // contract is converted from .docx on andro.law's side and is not instant.\n  const [openingFileId, setOpeningFileId] = createSignal<number | undefined>();\n\n  // Bumps on every peer change so a slow response for the previous chat cannot\n  // overwrite a newer one.\n  let generation = 0;\n\n  createEffect(on(() => props.peerId, (peerId) => {\n    const current = ++generation;\n    setResult(EMPTY);\n    setOpeningFileId(undefined);\n\n    if(!peerId?.isUser()) {\n      props.onCountChange?.(0);\n      return;\n    }\n\n    setLoading(true);\n    rootScope.managers.appCrmManager.getContractsByTelegram('' + peerId.toUserId())\n    .then((contracts) => {\n      if(generation !== current) return;\n      setResult(contracts);\n      props.onCountChange?.(contracts.contracts.length);\n    })\n    .finally(() => {\n      if(generation === current) setLoading(false);\n    });\n  }));\n\n  // Any object URL still alive when the panel goes away.\n  const openedUrls: string[] = [];\n  onCleanup(() => {\n    openedUrls.forEach((url) => URL.revokeObjectURL(url));\n  });\n\n  const openPdf = async(contract: CrmContract) => {\n    if(contract.file_id === null || openingFileId() !== undefined) return;\n\n    setOpeningFileId(contract.file_id);\n    try {\n      const bytes = await rootScope.managers.appCrmManager\n      .getContractPdf('' + props.peerId.toUserId(), contract.file_id);\n\n      if(!bytes) return;\n\n      const url = URL.createObjectURL(new Blob([bytes], {type: 'application/pdf'}));\n      openedUrls.push(url);\n      // A new tab rather than a download: an agent almost always wants to read\n      // one clause and go back to the conversation.\n      window.open(url, '_blank', 'noopener');\n    } finally {\n      setOpeningFileId(undefined);\n    }\n  };\n\n  // Y-m-d already, so it is shown as it arrives rather than being pushed through\n  // a locale that would turn an unambiguous date into an ambiguous one.\n  const formatDate = (value: string | null) => value || '';\n\n  const list = () => (\n    <div class=\"crm-contracts-list\">\n      <For each={result().contracts}>{(contract) => (\n        <div class={classNames('crm-contracts-item', 'crm-contracts-item--' + contract.status_color)}>\n          <div class=\"crm-contracts-item-head\">\n            <span class=\"crm-contracts-item-title\">{contract.title || '#' + contract.id}</span>\n            <span class={classNames('crm-contracts-badge', 'crm-contracts-badge--' + contract.status_color)}>\n              {contract.status_label}\n            </span>\n          </div>\n\n          <div class=\"crm-contracts-item-meta\">\n            <span dir=\"ltr\">\n              {formatDate(contract.start_date)}\n              <Show when={contract.expiration_date} fallback={<> · {i18n('Crm.Contract.NoExpiry')}</>}>\n                {' → '}\n                <span class={classNames(contract.is_expired && 'crm-contracts-expired')}>\n                  {formatDate(contract.expiration_date)}\n                </span>\n              </Show>\n            </span>\n\n            <Show when={contract.awaits_signature}>\n              <span class=\"crm-contracts-awaiting\">{i18n('Crm.Contract.AwaitingSignature')}</span>\n            </Show>\n          </div>\n\n          <Show when={contract.file_id !== null}>\n            <button\n              class=\"crm-contracts-open\"\n              disabled={openingFileId() !== undefined}\n              onClick={() => openPdf(contract)}\n            >\n              {openingFileId() === contract.file_id ?\n                i18n('Crm.Contract.Opening') :\n                i18n('Crm.Contract.OpenPdf')}\n            </button>\n          </Show>\n        </div>\n      )}</For>\n    </div>\n  );\n\n  // One empty state per reason. They look the same to a reader but mean quite\n  // different things to an agent: \"we cannot ask\" is not \"they have none\".\n  const empty = () => {\n    if(loading()) return i18n('Crm.Contract.Loading');\n    if(!result().enabled) return i18n('Crm.Contract.Disabled');\n    if(!result().hasAccount) return i18n('Crm.Contract.NoAccount');\n    return i18n('Crm.Contract.None');\n  };\n\n  return (\n    <div class={classNames('crm-contracts', props.scroll && 'crm-contracts--scroll', props.class)}>\n      <Show when={result().hasAccount && result().counts.total > 0}>\n        <div class=\"crm-contracts-summary\">\n          <span>{i18n('Crm.Contract.CountActive', [result().counts.active])}</span>\n          <Show when={result().counts.awaiting_signature > 0}>\n            <span class=\"crm-contracts-summary-warning\">\n              {i18n('Crm.Contract.CountAwaiting', [result().counts.awaiting_signature])}\n            </span>\n          </Show>\n          <Show when={result().counts.expiring_soon > 0}>\n            <span class=\"crm-contracts-summary-danger\">\n              {i18n('Crm.Contract.CountExpiring', [result().counts.expiring_soon])}\n            </span>\n          </Show>\n        </div>\n      </Show>\n\n      <Show\n        when={result().contracts.length}\n        fallback={<div class=\"crm-contracts-empty\">{empty()}</div>}\n      >\n        <Show when={props.scroll} fallback={list()}>\n          <Scrollable class=\"crm-contracts-scrollable\">{list()}</Scrollable>\n        </Show>\n      </Show>\n    </div>\n  );\n}\n","import PopupElement from '.';\nimport CrmContractsPanel from '@components/crmContractsPanel';\n\n// Topbar route to the customer's andro.law contracts. The panel itself is shared\n// with the profile's shared-media \"Contracts\" tab: see\n// @components/crmContractsPanel.\nexport default class PopupCrmContracts extends PopupElement {\n  constructor(private peerId: PeerId) {\n    super('popup-crm-contracts', {\n      title: 'Crm.Contract.PanelTitle',\n      body: true,\n      closable: true\n    });\n\n    this.appendSolidBody(() => <CrmContractsPanel peerId={this.peerId} scroll />);\n    this.show();\n  }\n}\n\nexport function showCrmContractsPopup(peerId: PeerId) {\n  new PopupCrmContracts(peerId);\n}\n","import type {Channel} from '@appManagers/appChatsManager';\nimport type {AppSidebarRight} from '@components/sidebarRight';\nimport type Chat from '@components/chat/chat';\nimport {RIGHT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarRight';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport createChatPinnedMessage, {ChatPinnedMessageController} from '@components/chat/pinnedMessage';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport PopupDeleteDialog from '@components/popups/deleteDialog';\nimport appNavigationController from '@components/appNavigationController';\nimport {LEFT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarLeft';\nimport PeerTitle from '@components/peerTitle';\nimport I18n, {LangPackKey, i18n} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {toastNew} from '@components/toast';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {ChatFull, Chat as MTChat, GroupCall, Dialog, InputGroupCall, UserFull} from '@layer';\nimport {showSharingPickerPopup} from '@components/popups/pickUser';\nimport PopupPeer, {PopupPeerCheckboxOptions} from '@components/popups/peer';\nimport {AppEditContactTab} from '@components/solidJsTabs/tabs';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport IS_CALL_SUPPORTED from '@environment/callSupport';\nimport {CallType} from '@lib/calls/types';\nimport PopupMute from '@components/popups/mute';\nimport {AppManagers} from '@lib/managers';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {FOLDER_ID_ALL} from '@appManagers/constants';\nimport formatNumber from '@helpers/number/formatNumber';\nimport PopupElement from '@components/popups';\nimport {modifyAckedPromise} from '@helpers/modifyAckedResult';\nimport callbackify from '@helpers/callbackify';\nimport confirmationPopup from '@components/confirmationPopup';\nimport IS_LIVE_STREAM_SUPPORTED from '@environment/liveStreamSupport';\nimport {avatarNew, findUpAvatar} from '@components/avatarNew';\nimport {Middleware, MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport setBadgeContent from '@helpers/setBadgeContent';\nimport createBadge from '@helpers/createBadge';\nimport AppStatisticsTab from '@components/sidebarRight/tabs/statistics';\nimport {ChatType} from './chatType';\nimport AppBoostsTab from '@components/sidebarRight/tabs/boosts';\nimport {RtmpStartStreamPopup} from '@components/rtmp/adminPopup';\nimport assumeType from '@helpers/assumeType';\nimport PopupSendGift from '@components/popups/sendGift';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {openRemoveFeePopup} from '@components/chat/removeFee';\nimport {createTopbarPlates, TopbarPlates} from '@components/chat/topbarPlates';\nimport pause from '@helpers/schedulers/pause';\nimport appImManager from '@lib/appImManager';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport namedPromises from '@helpers/namedPromises';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {createEffect, createRoot, on, untrack} from 'solid-js';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {AppAdminRecentActionsTab} from '@components/solidJsTabs/tabs';\nimport {setAppSettings} from '@stores/appSettings';\nimport useIsCrmSuperAdmin, {useIsCrmReadOnly} from '@stores/crmRole';\nimport {wrapAsyncClickHandler} from '@helpers/wrapAsyncClickHandler';\nimport liteMode from '@helpers/liteMode';\nimport createSubmenuTrigger from '@components/createSubmenuTrigger';\nimport ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {getCachedFullPeer} from '@stores/fullPeers';\nimport Icon from '@components/icon';\nimport {getDefaultOptions} from '@components/sidebarLeft/tabs/autoDeleteMessages/options';\nimport {createAutoDeleteIcon} from '@components/autoDeleteIcon';\nimport PopupBoost from '@components/popups/boost';\nimport PopupPremium from '@components/popups/premium';\nimport showNoForwardsPopup from '@components/popups/noForwards';\nimport {showCrmNotesPopup} from '@components/popups/crmNotes';\nimport {showCrmContractsPopup} from '@components/popups/crmContracts';\nimport {openCrmTasksTab} from '@lib/crm/createTask';\n\ntype ButtonToVerify = {element?: HTMLElement, verify: () => boolean | Promise<boolean>};\n\nexport default class ChatTopbar {\n  public container: HTMLDivElement;\n  public floatingPlatesWrapper: HTMLDivElement;\n  private btnBack: HTMLButtonElement;\n  private btnBackBadge: HTMLElement;\n  private chatInfo: HTMLDivElement;\n  private avatar: ReturnType<typeof avatarNew>;\n  private avatarMiddlewareHelper: MiddlewareHelper;\n  private title: HTMLDivElement;\n  private crmTicketBadge: HTMLSpanElement;\n  private subtitle: HTMLDivElement;\n  private chatUtils: HTMLDivElement;\n  private btnCall: HTMLButtonElement;\n  private btnGroupCall: HTMLButtonElement;\n  private btnGroupCallMenu: HTMLElement;\n  private btnSearch: HTMLButtonElement;\n  private btnLogFilters: HTMLButtonElement;\n  private btnMore: HTMLElement;\n\n  private autoDeleteBtnMenuOptions: ButtonMenuItemOptionsVerifiable;\n\n  public plates: TopbarPlates;\n  public pinnedMessage: ChatPinnedMessageController;\n\n\n  public listenerSetter: ListenerSetter;\n\n  private menuButtons: Parameters<typeof ButtonMenuToggle>[0]['buttons'];\n  private buttonsToVerify: ButtonToVerify[];\n  private chatInfoContainer: HTMLDivElement;\n  private person: HTMLDivElement;\n\n  private titleMiddlewareHelper: MiddlewareHelper;\n  private status: ReturnType<ChatTopbar['createStatus']>;\n\n  constructor(\n    private chat: Chat,\n    public appSidebarRight: AppSidebarRight,\n    private managers: AppManagers\n  ) {\n    this.listenerSetter = new ListenerSetter();\n\n    this.menuButtons = [];\n    this.buttonsToVerify = [];\n  }\n\n  public construct() {\n    // this.chat.log.error('Topbar construction');\n\n    this.container = document.createElement('div');\n    this.container.classList.add('sidebar-header', 'topbar', 'hide');\n    this.container.dataset.floating = '0';\n\n    // Preview mode swaps the back arrow for a close icon — the popup wires this up to its\n    // own hide() via `chat.onPreviewClose`, and the folder back-unread badge is irrelevant\n    // here (there's no folder navigation behind a floating preview).\n    const backIcon = this.chat.isPreview ? 'close' : 'left';\n    this.btnBack = ButtonIcon(`${backIcon} sidebar-close-button`, {noRipple: true});\n    if(!this.chat.isPreview) {\n      this.btnBackBadge = createBadge('span', 20, 'primary');\n      this.btnBackBadge.classList.add('back-unread-badge');\n      this.btnBack.append(this.btnBackBadge);\n    }\n\n    // * chat info section\n    this.chatInfoContainer = document.createElement('div');\n    this.chatInfoContainer.classList.add('chat-info-container');\n\n    this.chatInfo = document.createElement('div');\n    this.chatInfo.classList.add('chat-info');\n\n    const person = this.person = document.createElement('div');\n    person.classList.add('person');\n\n    const content = document.createElement('div');\n    content.classList.add('content');\n\n    const top = document.createElement('div');\n    top.classList.add('top');\n\n    this.title = document.createElement('div');\n    this.title.classList.add('user-title');\n\n    this.crmTicketBadge = document.createElement('span');\n    this.crmTicketBadge.classList.add('topbar-crm-ticket-badge', 'hide');\n\n    top.append(this.title, this.crmTicketBadge);\n\n    const bottom = document.createElement('div');\n    bottom.classList.add('bottom');\n\n    if(this.subtitle) {\n      bottom.append(this.subtitle);\n    }\n\n    content.append(top, bottom);\n\n    person.append(content);\n    this.chatInfo.append(person);\n\n    // * chat utils section\n    this.chatUtils = document.createElement('div');\n    this.chatUtils.classList.add('chat-utils');\n\n    this.plates = createTopbarPlates(this, this.chat, this.managers);\n\n    if(this.menuButtons.length) {\n      this.btnMore = ButtonMenuToggle({\n        listenerSetter: this.listenerSetter,\n        direction: 'bottom-left',\n        buttons: this.menuButtons,\n        positionPadding: {top: 7},\n        onOpenBefore: async() => {\n          const hasAutoDeleteButton = await this.chat.canManageAutoDelete();\n          if(!hasAutoDeleteButton) return;\n\n          const period = await this.chat.getAutoDeletePeriod().then(ackedResult => ackedResult.result);\n          this.autoDeleteBtnMenuOptions.iconElement = createAutoDeleteIcon(period);\n        },\n        onOpen: async(e, element) => {\n          const deleteButton = this.menuButtons[this.menuButtons.length - 1];\n          if(deleteButton?.element) {\n            const deleteButtonText = await this.managers.appPeersManager.getDeleteButtonText(this.chat.monoforumThreadId || this.peerId);\n            deleteButton.element.lastChild.replaceWith(i18n(deleteButtonText));\n          }\n\n          this.autoDeleteBtnMenuOptions.onOpen?.();\n        },\n        onClose: () => {\n          this.autoDeleteBtnMenuOptions.onClose?.();\n        }\n      });\n    }\n\n    this.chatUtils.append(...[\n      // this.chatAudio ? this.chatAudio.divAndCaption.container : null,\n      // this.pinnedMessage ? this.pinnedMessage.pinnedMessageContainer.divAndCaption.container : null,\n      // btnJoin / btnMute / btnDirectMessages moved into the chat-input control plate (see input.ts).\n      this.btnCall,\n      this.btnGroupCall,\n      this.btnGroupCallMenu,\n      this.btnSearch,\n      this.btnLogFilters,\n      this.btnMore\n    ].filter(Boolean));\n\n    this.pushButtonToVerify(this.btnCall, this.verifyCallButton.bind(this, 'voice'));\n    this.pushButtonToVerify(this.btnGroupCall, this.verifyVideoChatButton.bind(this, 'nonadmin'));\n    this.pushButtonToVerify(this.btnGroupCallMenu, this.verifyRtmpButton.bind(this));\n\n    // Preview keeps only the basic header — avatar + title + subtitle. The chat-utils\n    // pane (search / menu buttons) and the floating-plates wrapper (call / pinned /\n    // translation / action bar) are built so the rest of the JS can call methods on\n    // them, but never attached to the live DOM tree. They sit detached, so nothing\n    // visible leaks into the popup.\n    this.chatInfoContainer.append(this.btnBack, this.chatInfo);\n    if(!this.chat.isPreview) this.chatInfoContainer.append(this.chatUtils);\n    this.container.append(this.chatInfoContainer);\n\n    this.floatingPlatesWrapper = document.createElement('div');\n    this.floatingPlatesWrapper.classList.add('topbar-floating-plates', 'hide');\n    if(!this.chat.isPreview) this.container.append(this.floatingPlatesWrapper);\n\n    if(this.pinnedMessage) {\n      this.appendPinnedMessage(this.pinnedMessage);\n    }\n\n    this.plates.mount(this.floatingPlatesWrapper);\n\n    // * construction end\n\n    // * fix topbar overflow section\n\n    this.listenerSetter.add(window)('resize', this.onResize);\n    this.listenerSetter.add(mediaSizes)('changeScreen', this.onChangeScreen);\n\n    attachClickEvent(this.container, (e) => {\n      if(\n        findUpClassName(e.target, 'topbar-search-container') ||\n        !(e.target as HTMLElement).isConnected ||\n        findUpClassName(e.target, 'chat-search-top')\n      ) {\n        return;\n      }\n\n      const container = findUpClassName(e.target, 'pinned-container');\n      blurActiveElement();\n      if(container) {\n        return;\n      } else {\n        const avatar = findUpAvatar(e.target);\n        if(mediaSizes.activeScreen === ScreenSize.medium && document.body.classList.contains(LEFT_COLUMN_ACTIVE_CLASSNAME)) {\n          onBtnBackClick();\n        } else if(avatar) {\n          if(avatar.classList.contains('has-stories')) {\n            return;\n          }\n\n          this.appSidebarRight.toggleSidebar(!document.body.classList.contains(RIGHT_COLUMN_ACTIVE_CLASSNAME));\n        } else {\n          this.appSidebarRight.toggleSidebar(true);\n        }\n      }\n    }, {listenerSetter: this.listenerSetter});\n\n    const onBtnBackClick = (e?: Event) => {\n      if(e) {\n        cancelEvent(e);\n      }\n\n      if(this.chat.isPreview) {\n        this.chat.onPreviewClose?.();\n        return;\n      }\n\n      if(this.chat.type === ChatType.Search) {\n        this.chat.resetSearch();\n        return;\n      }\n\n      this.chat.pop();\n    };\n\n    attachClickEvent(this.btnBack, onBtnBackClick, {listenerSetter: this.listenerSetter});\n  }\n\n  private pushButtonToVerify(element: HTMLElement, verify: ButtonToVerify['verify']) {\n    if(!element) {\n      return;\n    }\n\n    element.classList.add('hide');\n    this.buttonsToVerify.push({element, verify});\n  }\n\n  private verifyButtons = (e?: Event) => {\n    const isMenuOpen = !!e || !!(this.btnMore && this.btnMore.classList.contains('menu-open'));\n\n    e && cancelEvent(e);\n\n    const r = async() => {\n      const buttons = this.buttonsToVerify.concat(isMenuOpen ? this.menuButtons as any : []);\n      const results = await Promise.all(buttons.map(async(button) => {\n        return {\n          result: await button.verify(),\n          button\n        }\n      }));\n\n      results.forEach(({button, result}) => {\n        button.element?.classList.toggle('hide', !result);\n      });\n    };\n\n    r();\n  };\n\n  private verifyRtmpButton = async() => {\n    if(!this.chat.isBroadcast || this.chat.type !== ChatType.Chat) {\n      return false;\n    }\n\n    const currentGroupCall = groupCallsController.groupCall;\n    const chatId = this.peerId.toChatId();\n    if(currentGroupCall?.chatId === chatId) {\n      return false;\n    }\n\n    const chat = this.chat.peer as MTChat.channel | MTChat.chat;\n    if(!chat) {\n      return false;\n    }\n\n    const isCallActive = !!(chat as MTChat.chat).pFlags?.call_active;\n    if(isCallActive) {\n      return false;\n    }\n\n    return hasRights(chat, 'manage_call');\n  };\n\n  private verifyVideoChatButton = async(type?: 'group' | 'broadcast' | 'nonadmin') => {\n    if(\n      !IS_GROUP_CALL_SUPPORTED ||\n      this.peerId.isUser() ||\n      this.chat.type !== ChatType.Chat ||\n      this.chat.threadId\n    ) return false;\n\n    const currentGroupCall = groupCallsController.groupCall;\n    const chatId = this.peerId.toChatId();\n    if(currentGroupCall?.chatId === chatId) {\n      return false;\n    }\n\n    if(type) {\n      if(((type === 'group' && !this.chat.isAnyGroup)) ||\n        ((type === 'broadcast' && !this.chat.isBroadcast))) {\n        return false;\n      }\n    }\n\n    const chat = this.chat.peer as MTChat.channel | MTChat.chat;\n    const isCallActive = !!(chat as MTChat.chat).pFlags?.call_active;\n    const canManageCall = hasRights(chat, 'manage_call');\n    if(type === 'nonadmin' && canManageCall && this.chat.isBroadcast) {\n      return false; // * hide live stream top button\n    }\n    const needActiveCall = !canManageCall;\n    if(!isCallActive) {\n      return !needActiveCall;\n    }\n\n    const fullChat = await this.managers.appProfileManager.getChatFull(chatId);\n    const inputGroupCall = fullChat.call as InputGroupCall.inputGroupCall;\n    const groupCall = await this.managers.appGroupCallsManager.getGroupCallFull(\n      inputGroupCall.id\n    );\n    if(groupCall?._ !== 'groupCall') return false;\n\n    return !groupCall.pFlags.rtmp_stream;\n  };\n\n  private verifyCallButton = async(type?: CallType) => {\n    // Calls are CRM-superadmin-only: regular agents share the support account\n    // and must not place voice/video calls from it.\n    if(!useIsCrmSuperAdmin()()) return false;\n    if(!IS_CALL_SUPPORTED || !this.peerId.isUser() || this.chat.type !== ChatType.Chat) return false;\n    const userId = this.peerId.toUserId();\n    const userFull = await this.managers.appProfileManager.getCachedFullUser(userId);\n\n    return !!userFull && !!(type === 'voice' ? userFull.pFlags.phone_calls_available : userFull.pFlags.video_calls_available);\n  };\n\n  private verifyIfCanDeleteChat = async() => {\n    // Deleting a chat is CRM-superadmin-only: regular agents must not wipe\n    // conversation history from the shared support account.\n    if(!useIsCrmSuperAdmin()()) return false;\n\n    if(this.chat.isMonoforum) {\n      const chat = this.chat.peer;\n      return chat?._ === 'channel' && !chat?.pFlags?.creator && !chat?.pFlags?.left;\n    }\n\n    if(this.chat.type === ChatType.Saved) return true;\n\n    return (\n      this.chat.type === ChatType.Chat &&\n      !!(await this.managers.appMessagesManager.getDialogOnly(this.peerId))\n    );\n  }\n\n  public constructUtils() {\n    this.autoDeleteBtnMenuOptions = createSubmenuTrigger({\n      options: {\n        text: 'AutoDeleteMessagesShort',\n        separatorDown: true,\n        // Auto-delete is CRM-superadmin-only: regular agents must not change\n        // the shared support account's message-destruction timer.\n        verify: () => useIsCrmSuperAdmin()() && this.chat.canManageAutoDelete()\n      },\n      createSubmenu: this.createAutoDeleteSubmenu.bind(this),\n      direction: 'left-start'\n    });\n\n    const onBoostClick = async() => {\n      const {peerId} = this;\n      if(await this.managers.appProfileManager.canViewStatistics(peerId)) {\n        this.appSidebarRight.createTab(AppBoostsTab).open(this.peerId);\n        this.appSidebarRight.toggleSidebar(true);\n      } else {\n        PopupElement.createPopup(PopupBoost, this.peerId);\n      }\n    };\n\n    this.menuButtons = [this.autoDeleteBtnMenuOptions, {\n      icon: 'checkround',\n      text: 'Crm.Ticket.Close',\n      onClick: () => {\n        this.plates?.crmTicket.close();\n      },\n      // Reliable fallback for closing the ticket when the floating CRM plate is\n      // crowded out by other plates (pinned message / translate). Reads the plate's\n      // already-loaded ticket signal — no extra round-trip on menu open.\n      verify: () => !useIsCrmReadOnly()() && this.plates?.crmTicket.getTicket()?.status === 'open'\n    }, {\n      icon: 'readchats',\n      text: 'Crm.PeekMode.MarkRead',\n      onClick: () => {\n        this.chat.bubbles.markChatRead();\n      },\n      // Peek mode (\"Manual read\"): the chat was opened without sending a read\n      // receipt, so this is how the agent claims it. Only shown while there is\n      // actually something being held back.\n      verify: () => !!this.chat.bubbles?.hasHeldReads()\n    }, {\n      icon: 'clipboard',\n      text: 'Crm.Note.MenuButton',\n      onClick: () => {\n        showCrmNotesPopup(this.peerId);\n      },\n      // Internal notes for the customer's ticket. Shown whenever a ticket exists for\n      // this chat (reads the plate's already-loaded note state — no round-trip).\n      verify: () => !!this.peerId?.isUser() && !!this.plates?.crmTicket.hasTicketForNotes()\n    }, {\n      icon: 'document',\n      text: 'Crm.Contract.MenuButton',\n      onClick: () => {\n        showCrmContractsPopup(this.peerId);\n      },\n      // Shown for any 1-on-1 chat with a CRM session behind it, without a ticket\n      // check: contracts belong to the customer, not to a ticket, and a customer\n      // whose ticket was closed months ago is exactly who an agent asks about.\n      // The panel says \"no contracts account\" for itself when there is nothing.\n      verify: () => !!this.peerId?.isUser()\n    }, {\n      icon: 'check',\n      text: 'Tasks.Title',\n      onClick: () => {\n        openCrmTasksTab();\n      },\n      // In every chat, on every screen size: on mobile the left sidebar is\n      // hidden behind the chat, so this menu is the only one-tap route to the\n      // agent's tasks without typing \"/task\".\n      verify: () => rootScope.managers.appCrmManager.isConnected()\n    }, {\n      icon: 'search',\n      text: 'Search',\n      onClick: () => {\n        this.chat.initSearch();\n      },\n      verify: () => mediaSizes.isMobile\n    }, {\n      icon: 'filter',\n      text: 'FilterActions',\n      onClick: () => {\n        this.onFilterActionsClick();\n      },\n      verify: () => mediaSizes.isMobile && this.chat.type === ChatType.Logs\n    }, /* {\n      icon: 'pinlist',\n      text: 'Pinned Messages',\n      onClick: () => this.openPinned(false),\n      verify: () => mediaSizes.isMobile\n    }, */{\n      icon: 'mute',\n      text: 'ChatList.Context.Mute',\n      onClick: this.onMuteClick,\n      verify: async() => this.chat.type === ChatType.Chat && !this.chat.monoforumThreadId && rootScope.myId !== this.peerId && !(await this.managers.appNotificationsManager.isPeerLocalMuted({peerId: this.peerId, respectType: false, threadId: this.chat.threadId}))\n    }, {\n      icon: 'unmute',\n      text: 'ChatList.Context.Unmute',\n      onClick: this.onUnmuteClick,\n      verify: () => this.chat.type === ChatType.Chat && !this.chat.monoforumThreadId && rootScope.myId !== this.peerId && this.managers.appNotificationsManager.isPeerLocalMuted({peerId: this.peerId, respectType: false, threadId: this.chat.threadId})\n    }, {\n      icon: 'comments',\n      text: 'ViewDiscussion',\n      onClick: () => {\n        const middleware = this.chat.bubbles.getMiddleware();\n        Promise.resolve(this.managers.appProfileManager.getChannelFull(this.peerId.toChatId())).then((channelFull) => {\n          if(middleware() && channelFull.linked_chat_id) {\n            this.chat.appImManager.setInnerPeer({\n              peerId: channelFull.linked_chat_id.toPeerId(true)\n            });\n          }\n        });\n      },\n      verify: async() => {\n        const chatFull = await this.managers.appProfileManager.getCachedFullChat(this.peerId.toChatId());\n        return this.chat.type === ChatType.Chat && !!(chatFull as ChatFull.channelFull)?.linked_chat_id;\n      }\n    }, {\n      icon: 'phone',\n      text: 'Call',\n      onClick: this.onCallClick.bind(this, 'voice'),\n      verify: this.verifyCallButton.bind(this, 'voice')\n    }, {\n      icon: 'videocamera',\n      text: 'VideoCall',\n      onClick: this.onCallClick.bind(this, 'video'),\n      verify: this.verifyCallButton.bind(this, 'video')\n    }, {\n      icon: 'videochat',\n      text: 'PeerInfo.Action.LiveStream',\n      onClick: this.onJoinGroupCallClick,\n      verify: this.verifyVideoChatButton.bind(this, 'broadcast')\n    }, {\n      icon: 'videochat',\n      text: 'PeerInfo.Action.VoiceChat',\n      onClick: this.onJoinGroupCallClick,\n      verify: this.verifyVideoChatButton.bind(this, 'group')\n    }, {\n      icon: 'topics',\n      text: 'TopicViewAsTopics',\n      onClick: () => {\n        this.chat.appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      verify: async() => {\n        const dialog = await this.managers.appMessagesManager.getDialogOnly(this.peerId);\n        return !!(dialog && (dialog as Dialog.dialog).pFlags.view_forum_as_messages);\n      }\n    }, {\n      icon: 'topics',\n      text: 'SavedViewAsChats',\n      onClick: () => {\n        this.chat.appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      verify: () => this.peerId === rootScope.myId && !this.chat.threadId && !this.chat.appSettings.savedAsForum\n    }, {\n      icon: 'message',\n      text: 'ChannelDirectMessages.ViewChats',\n      onClick: () => {\n        appDialogsManager.toggleForumTabByPeerId(this.peerId, true);\n      },\n      verify: () => this.chat.isMonoforum && !this.chat.monoforumThreadId && this.chat.canManageDirectMessages && !mediaSizes.isLessThanFloatingLeftSidebar && !appDialogsManager.hasForumOpenFor(this.peerId)\n    }, {\n      icon: 'select',\n      text: 'Chat.Menu.SelectMessages',\n      onClick: () => {\n        const selection = this.chat.selection;\n        selection.toggleSelection(true, true);\n        if(this.chat.appSettings.chatContextMenuHintWasShown) {\n          return;\n        }\n\n        const original = selection.toggleByElement.bind(selection);\n        selection.toggleByElement = async(bubble) => {\n          this.chat.setAppSettings('chatContextMenuHintWasShown', true);\n          toastNew({langPackKey: 'Chat.Menu.Hint'});\n\n          selection.toggleByElement = original;\n          selection.toggleByElement(bubble);\n        };\n      },\n      verify: () => !this.chat.selection.isSelecting && !!this.chat.bubbles.getRenderedLength() && !(this.chat.type === ChatType.Logs)\n    }, {\n      icon: 'select',\n      text: 'Chat.Menu.ClearSelection',\n      onClick: () => {\n        this.chat.selection.cancelSelection();\n      },\n      verify: () => this.chat.selection.isSelecting\n    }, {\n      icon: 'adduser',\n      text: 'AddContact',\n      onClick: () => {\n        this.addContact();\n      },\n      // Contact editing is CRM-superadmin-only.\n      verify: async() => useIsCrmSuperAdmin()() && !this.chat.isBot && (this.chat.monoforumThreadId || this.peerId).isUser() && !(await this.managers.appPeersManager.isContact(this.chat.monoforumThreadId || this.peerId))\n    }, {\n      icon: 'forward',\n      text: 'ShareContact',\n      onClick: () => {\n        const contactPeerId = this.peerId;\n        showSharingPickerPopup({\n          onSelect: async(chosen) => {\n            const {peerId, monoforumThreadId} = chosen[0];\n            const preparedPaymentResult = await PaidMessagesInterceptor.prepareStarsForPayment({messageCount: 1, peerId});\n            if(preparedPaymentResult === PAYMENT_REJECTED) throw new Error();\n\n            const send = () => {\n              this.managers.appMessagesManager.sendContact({peerId, contactPeerId, confirmedPaymentResult: preparedPaymentResult, monoforumThreadId});\n              this.chat.appImManager.setInnerPeer({peerId});\n            };\n\n            if(preparedPaymentResult) return void send();\n\n            return new Promise((resolve, reject) => {\n              PopupElement.createPopup(PopupPeer, '', {\n                titleLangKey: 'SendMessageTitle',\n                descriptionLangKey: 'SendContactToGroupText',\n                descriptionLangArgs: [new PeerTitle({peerId, dialog: true}).element],\n                buttons: [{\n                  langKey: 'Send',\n                  callback: async() => {\n                    resolve();\n                    send();\n                  }\n                }, {\n                  langKey: 'Cancel',\n                  callback: () => {\n                    reject();\n                  },\n                  isCancel: true\n                }],\n                peerId,\n                overlayClosable: true\n              }).show();\n            });\n          }\n        });\n      },\n      verify: async() => rootScope.myId !== this.peerId && this.peerId.isUser() && (await this.managers.appPeersManager.isContact(this.peerId)) && !!(await this.managers.appUsersManager.getUser(this.peerId.toUserId())).phone\n    }, {\n      icon: 'gift',\n      text: 'Chat.Menu.SendGift',\n      onClick: () => PopupElement.createPopup(PopupSendGift, {peerId: this.peerId}),\n      verify: async() => (\n        this.chat.isChannel || (this.chat.peerId.isUser() && !this.chat.isBot && (await this.managers.appUsersManager.isRegularUser(this.peerId)))\n      ) && !(this.chat.type === ChatType.Logs)\n    }, {\n      icon: 'message',\n      text: 'ChannelDirectMessages.Manage',\n      onClick: () => this.onDirectMessagesClick(),\n      verify: () => this.chat.isChannel && this.chat.canManageDirectMessages && !this.chat.isMonoforum && !!(this.chat.peer as MTChat.channel).linked_monoforum_id && this.chat.type !== ChatType.Logs\n    }, {\n      icon: 'statistics',\n      text: 'Statistics',\n      onClick: () => {\n        this.appSidebarRight.createTab(AppStatisticsTab).open(this.peerId.toChatId());\n        this.appSidebarRight.toggleSidebar(true);\n      },\n      verify: () => !this.chat.monoforumThreadId && this.managers.appProfileManager.canViewStatistics(this.peerId)\n    }, {\n      icon: 'addboost',\n      text: 'BoostChannel',\n      onClick: onBoostClick,\n      verify: async() => this.chat.isBroadcast\n    }, {\n      icon: 'addboost',\n      text: 'BoostGroup',\n      onClick: onBoostClick,\n      verify: async() => this.chat.isMegagroup\n    }, {\n      icon: 'bots',\n      text: 'Settings',\n      onClick: () => {\n        // [ ] Bot with paid stars?\n        this.managers.appMessagesManager.sendText({peerId: this.peerId, text: '/settings'});\n      },\n      verify: async() => {\n        try {\n          const attachMenuBot = await this.managers.appAttachMenuBotsManager.getAttachMenuBot(this.peerId.toUserId());\n          return !!attachMenuBot?.pFlags?.has_settings;\n        } catch(err) {\n          return false;\n        }\n      }\n    }, {\n      icon: 'premium_translate',\n      text: 'Translate',\n      onClick: () => {\n        this.managers.appTranslationsManager.togglePeerTranslations(\n          this.peerId,\n          false\n        ).then(() => {\n          if(this.chat.peerTranslation.canTranslate()) {\n            this.chat.peerTranslation.toggle(true);\n          }\n        });\n      },\n      verify: async() => {\n        if(!this.chat.peerTranslation.areTranslationsAvailable()) {\n          return false;\n        }\n\n        const fullPeer = await this.managers.appProfileManager.getCachedProfileByPeerId(this.peerId);\n        return fullPeer && !!fullPeer.pFlags.translations_disabled;\n      }\n    }, {\n      icon: 'lock',\n      text: 'BlockUser',\n      onClick: () => {\n        this.blockUser();\n      },\n      verify: async() => {\n        if(!this.peerId.isUser()) return false;\n        const userFull = await this.managers.appProfileManager.getCachedFullUser(this.peerId.toUserId());\n        return this.peerId !== rootScope.myId && userFull && !userFull.pFlags?.blocked;\n      }\n    }, {\n      icon: 'lockoff',\n      text: 'Unblock',\n      onClick: () => {\n        this.managers.appUsersManager.toggleBlock(this.peerId, false).then(() => {\n          toastNew({langPackKey: 'UserUnblocked'});\n        });\n      },\n      verify: async() => {\n        const userFull = await this.managers.appProfileManager.getCachedFullUser(this.peerId.toUserId());\n        return !!userFull?.pFlags?.blocked;\n      }\n    }, {\n      icon: 'sharingoff',\n      text: 'DisableSharing',\n      onClick: () => {\n        if(!rootScope.premium) {\n          PopupPremium.show({feature: 'pm_noforwards'});\n          return;\n        }\n\n        const cb = () => this.managers.appProfileManager.toggleNoForwards(this.peerId, true);\n        if(this.chat.appSettings.seenTooltips.noForwards) {\n          cb();\n        } else {\n          showNoForwardsPopup(() => {\n            setAppSettings('seenTooltips', 'noForwards', true);\n            cb();\n          });\n        }\n      },\n      verify: async() => {\n        if(!this.peerId.isUser() || this.peerId === rootScope.myId || this.chat.isBot) return false;\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        if(!userFull) return false;\n        return !userFull.pFlags.noforwards_my_enabled && !userFull.pFlags.noforwards_peer_enabled;\n      }\n    }, {\n      icon: 'sharingon',\n      text: 'EnableSharing',\n      onClick: async() => {\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        const {peerId} = this;\n\n        if(userFull.pFlags.noforwards_peer_enabled) {\n          await confirmationPopup({\n            titleLangKey: 'EnableSharing',\n            descriptionLangKey: 'EnableSharingCaption',\n            descriptionLangArgs: [new PeerTitle({peerId}).element],\n            button: {\n              langKey: 'SendRequest'\n            }\n          });\n        }\n\n        this.managers.appProfileManager.toggleNoForwards(peerId, false);\n      },\n      verify: async() => {\n        if(!this.peerId.isUser() || this.peerId === rootScope.myId || this.chat.isBot) return false;\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        if(!userFull) return false;\n        return !!(userFull?.pFlags?.noforwards_my_enabled || userFull?.pFlags?.noforwards_peer_enabled);\n      }\n    }, {\n      icon: 'dollar_circle',\n      text: 'PaidMessages.ChargeFee',\n      onClick: () => this.onToggleFeeClick(true),\n      verify: () => this.verifyToggleFee(true)\n    }, {\n      icon: 'dollar_circle_x',\n      text: 'PaidMessages.RemoveFee',\n      onClick: () => this.onToggleFeeClick(false),\n      verify: () => this.verifyToggleFee(false)\n    }, {\n      icon: 'clipboard',\n      text: 'CompactDiffView',\n      onClick: wrapAsyncClickHandler(async() => {\n        if(!this.chat.popIfMoreThanOne()) {\n          await this.chat.setPeer({peerId: this.peerId});\n        }\n\n        setAppSettings('logsDiffView', true);\n\n        // awaiting this doesn't help\n        this.appSidebarRight.toggleSidebar(true, true);\n\n        if(liteMode.isAvailable('animations')) await pause(100);\n\n        this.appSidebarRight.createTab(AppAdminRecentActionsTab).open({\n          channelId: this.peerId.toChatId(),\n          isBroadcast: this.chat.isBroadcast\n        });\n      }),\n      verify: () => this.chat.type === ChatType.Logs\n    }, {\n      icon: 'delete',\n      danger: true,\n      text: 'Delete',\n      onClick: () => {\n        PopupElement.createPopup(\n          PopupDeleteDialog,\n          this.chat.monoforumThreadId || this.peerId,\n          undefined,\n          undefined,\n          this.chat.threadId,\n          this.chat.monoforumThreadId ? this.peerId : undefined\n        );\n      },\n      verify: this.verifyIfCanDeleteChat\n    }];\n\n    this.btnSearch = ButtonIcon('search');\n    this.attachClickEvent(this.btnSearch, (e) => {\n      this.chat.initSearch();\n    }, true);\n\n    this.btnLogFilters = ButtonIcon('filter');\n    this.attachClickEvent(this.btnLogFilters, () => {\n      this.onFilterActionsClick();\n    });\n  }\n\n  public addContact() {\n    if(!this.appSidebarRight.isTabExists(AppEditContactTab)) {\n      this.appSidebarRight.createTab(AppEditContactTab).open(this.peerId);\n\n      this.appSidebarRight.toggleSidebar(true);\n    }\n  }\n\n  public async blockUser(showReport?: boolean, showDelete?: boolean, onConfirmed?: (promise: Promise<any>) => void) {\n    const peerId = this.peerId;\n    const checkboxes: PopupPeerCheckboxOptions[] = [\n      showReport && {\n        text: 'DeleteReportSpam',\n        checked: true\n      },\n      showDelete && {\n        text: 'DeleteThisChat',\n        checked: true\n      }\n    ];\n\n    const checked = await confirmationPopup({\n      peerId,\n      titleLangKey: 'BlockUser',\n      descriptionLangKey: 'AreYouSureBlockContact2',\n      descriptionLangArgs: [new PeerTitle({peerId}).element],\n      button: {\n        langKey: 'BlockUser',\n        isDanger: true\n      },\n      checkboxes: checkboxes.filter(Boolean)\n    });\n\n    const [reportSpam, deleteChat] = Array.isArray(checked) ? checked : [];\n\n    const promise = Promise.all([\n      reportSpam && this.managers.appMessagesManager.reportSpam(peerId),\n      deleteChat && this.managers.appMessagesManager.flushHistory({peerId, justClear: false, revoke: true}),\n      this.managers.appUsersManager.toggleBlock(peerId, true)\n    ]);\n\n    onConfirmed?.(promise);\n\n    await promise;\n\n    toastNew({langPackKey: 'UserBlocked'});\n  }\n\n  public attachClickEvent(el: HTMLElement, cb: (e: MouseEvent) => void, noBlur?: boolean) {\n    attachClickEvent(el, (e) => {\n      cancelEvent(e);\n      !noBlur && blurActiveElement();\n      cb(e);\n    }, {listenerSetter: this.listenerSetter});\n  }\n\n  private onCallClick(type: CallType) {\n    this.chat.appImManager.callUser(this.peerId.toUserId(), type);\n  }\n\n  private verifyToggleFee = async(requirePayment: boolean) => {\n    if(!this.chat.monoforumThreadId) return;\n\n    const {chat, dialog} = await namedPromises({\n      chat: this.chat.peer,\n      dialog: this.managers.monoforumDialogsStorage.getDialogByParent(this.peerId, this.chat.monoforumThreadId)\n    });\n\n    if(chat?._ !== 'channel' || !chat?.send_paid_messages_stars) return false;\n\n    return requirePayment ? !!dialog?.pFlags?.nopaid_messages_exception : !dialog?.pFlags?.nopaid_messages_exception;\n  };\n\n  private onToggleFeeClick = async(requirePayment: boolean) => {\n    const peerId = this.chat.monoforumThreadId;\n    const parentPeerId = this.chat.peerId;\n    if(!peerId || !parentPeerId) return;\n\n    try {\n      await openRemoveFeePopup({peerId, parentPeerId, requirePayment, managers: this.managers})\n    } catch{}\n  }\n\n  private onJoinGroupCallClick = () => {\n    this.chat.appImManager.joinGroupCall(this.peerId);\n  };\n\n  private onFilterActionsClick = wrapAsyncClickHandler(async() => {\n    const {default: LogFiltersPopup} = await import('./logFiltersPopup');\n\n    new LogFiltersPopup({\n      channelId: this.peerId.toChatId(),\n      isBroadcast: this.chat.isBroadcast,\n      committedFilters: this.chat.bubbles.committedLogsFilters,\n      HotReloadGuard: SolidJSHotReloadGuardProvider,\n      onFinish: ({committedFilters}) => {\n        this.chat.bubbles.setLogFilters(committedFilters);\n      }\n    }).show();\n  })\n\n  private get peerId() {\n    return this.chat.peerId;\n  }\n\n  public constructPeerHelpers() {\n    this.subtitle = document.createElement('div');\n    this.subtitle.classList.add('info');\n\n    this.pinnedMessage = createChatPinnedMessage(this, this.chat, this.managers);\n\n    this.btnCall = ButtonIcon('phone');\n    this.btnGroupCall = ButtonIcon('videochat');\n    this.btnGroupCallMenu = ButtonMenuToggle({\n      listenerSetter: this.listenerSetter,\n      direction: 'bottom-left',\n      buttons: [{\n        icon: 'videochat',\n        text: 'Rtmp.Topbar.StartVideoChat',\n        onClick: this.onJoinGroupCallClick\n      }, {\n        icon: 'link',\n        text: 'Rtmp.Topbar.StreamWith',\n        onClick: () => {\n          PopupElement.createPopup(RtmpStartStreamPopup, {peerId: this.peerId}).show();\n        },\n        verify: () => IS_LIVE_STREAM_SUPPORTED\n      }],\n      icon: 'videochat'\n    });\n    this.attachClickEvent(this.btnCall, this.onCallClick.bind(this, 'voice'));\n    this.attachClickEvent(this.btnGroupCall, this.onJoinGroupCallClick);\n\n    this.listenerSetter.add(rootScope)('folder_unread', (folder) => {\n      if(!this.btnBackBadge || folder.id !== FOLDER_ID_ALL) {\n        return;\n      }\n\n      const size = folder.unreadUnmutedPeerIds.size;\n      setBadgeContent(this.btnBackBadge, size ? '' + formatNumber(size, 1) : '');\n      // this.btnBack.classList.remove('tgico-left', 'tgico-previous');\n      // this.btnBack.classList.add(size ? 'tgico-previous' : 'tgico-left');\n    });\n\n    this.listenerSetter.add(rootScope)('chat_update', (chatId) => {\n      if(this.peerId === chatId.toPeerId(true)) {\n        const chat = this.chat.peer as Channel/*  | Chat */;\n        if(!chat.pFlags.broadcast) {\n          return;\n        }\n\n        this.verifyButtons();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('peer_full_update', (peerId) => {\n      if(this.peerId === peerId) {\n        this.verifyButtons();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('crm_ticket_update', ({peerId, ticket}) => {\n      if(this.peerId !== peerId) return;\n      Promise.resolve(ticket?.status || rootScope.managers.appCrmManager.getTicketStatusCached(peerId))\n      .then((status) => this.setCrmTicketBadge(status));\n    });\n\n    this.listenerSetter.add(rootScope)('crm_open_tickets_update', () => {\n      if(!this.peerId?.isUser()) return;\n      Promise.resolve(rootScope.managers.appCrmManager.getTicketStatusCached(this.peerId))\n      .then((status) => this.setCrmTicketBadge(status));\n    });\n\n    this.listenerSetter.add(rootScope)('chat_requests', ({chatId, recentRequesters, requestsPending}) => {\n      if(this.peerId !== chatId.toPeerId(true)) {\n        return;\n      }\n\n      const middleware = this.chat.bubbles.getMiddleware();\n      this.plates.requests.set(\n        this.peerId,\n        recentRequesters.map((userId) => userId.toPeerId(false)),\n        requestsPending\n      ).then((callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n    });\n\n    this.listenerSetter.add(rootScope)('peer_settings', async({peerId, settings}) => {\n      if(this.peerId !== peerId) {\n        return;\n      }\n\n      const callback = this.plates.actions.set(peerId, settings);\n      callback();\n    });\n\n    this.listenerSetter.add(rootScope)('right_sidebar_toggle', () => {\n      this.setFloating(); // * to calculate sponsored height\n    });\n\n    this.chat.addEventListener('setPeer', (mid, isTopMessage) => {\n      const middleware = this.chat.bubbles.getMiddleware();\n      if(!middleware() || !this.pinnedMessage) return;\n\n      this.pinnedMessage.setUserHidden(!!this.chat.appState.hiddenPinnedMessages[this.chat.peerId]);\n\n      if(isTopMessage) {\n        this.pinnedMessage.unsetScrollDownListener();\n        this.pinnedMessage.testMid(mid, 0); // * because slider will not let get bubble by document.elementFromPoint\n      } else if(!this.pinnedMessage.isLocked()) {\n        this.pinnedMessage.handleFollowingPinnedMessage();\n        this.pinnedMessage.testMid(mid);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('peer_pinned_messages', ({peerId, mids}) => {\n      if(this.chat.type !== ChatType.Pinned || peerId !== this.peerId) {\n        return;\n      }\n\n      if(mids) {\n        this.setTitle();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_update', async({dialogs}) => {\n      if(!this.chat.isMonoforum || !this.chat.monoforumThreadId) return;\n\n      const found = dialogs.find(dialog => dialog.parentPeerId === this.chat.peerId && dialog.peerId === this.chat.monoforumThreadId);\n      if(!found) return;\n\n      const callback = await (await this.plates.removeFee.setPeerId(this.chat.peerId)).result;\n      callback();\n    });\n\n    this.listenerSetter.add(rootScope)('auto_delete_period_update', ({peerId, period}) => {\n      if(peerId !== this.peerId || this.chat.type !== ChatType.Chat) return;\n      this.avatar.setAutoDeletePeriod(period);\n    });\n\n    return this;\n  }\n\n  public openPinned(byCurrent: boolean) {\n    this.chat.appImManager.setInnerPeer({\n      peerId: this.peerId,\n      lastMsgId: byCurrent ? +this.pinnedMessage.container.dataset.mid : 0,\n      type: ChatType.Pinned\n    });\n  }\n\n  public onJoinClick = async(button: HTMLElement) => {\n    const middleware = this.chat.bubbles.getMiddleware();\n    button.setAttribute('disabled', 'true');\n\n    const chatId = this.peerId.toChatId();\n    let promise: Promise<any>;\n    if(await this.managers.appChatsManager.isChannel(chatId)) {\n      promise = this.managers.appChatsManager.joinChannel(chatId);\n    } else {\n      promise = this.managers.appChatsManager.addChatUser(chatId, rootScope.myId);\n    }\n\n    promise.catch((err) => {\n      assumeType<ApiError>(err);\n      switch(err.type) {\n        case 'INVITE_REQUEST_SENT': {\n          toastNew({langPackKey: 'Chat.SendJoinRequest.Info'});\n          return;\n        }\n      }\n\n      throw err;\n    }).finally(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      button.removeAttribute('disabled');\n    });\n  };\n\n  private canClickOnDirectMessagesBtn = true;\n  private onDirectMessagesClick = async() => {\n    if(!this.canClickOnDirectMessagesBtn || !this.peerId.isAnyChat()) return;\n    this.canClickOnDirectMessagesBtn = false;\n    pause(200).then(() => this.canClickOnDirectMessagesBtn = true);\n\n    const chat = this.chat.peer;\n    if(chat._ !== 'channel') return;\n\n    appImManager.setInnerPeer({\n      peerId: chat.linked_monoforum_id.toPeerId(true)\n    });\n  };\n\n  private onMuteClick = () => {\n    PopupElement.createPopup(PopupMute, this.peerId);\n  };\n\n  private onUnmuteClick = () => {\n    this.managers.appMessagesManager.togglePeerMute({peerId: this.peerId, threadId: this.chat.threadId});\n  };\n\n  private onResize = () => {\n    this.setFloating();\n  };\n\n  private onChangeScreen = (from: ScreenSize, to: ScreenSize) => {\n    this.onResize();\n  };\n\n  public destroy() {\n    // this.chat.log.error('Topbar destroying');\n    this.listenerSetter.removeAll();\n\n    this.status?.destroy();\n    this.titleMiddlewareHelper?.destroy();\n    this.avatarMiddlewareHelper?.destroy();\n    this.pinnedMessage?.destroy();\n    this.plates?.destroy();\n\n    delete this.pinnedMessage;\n    delete this.plates;\n  }\n\n  public cleanup() {\n    if(!this.chat.peerId) {\n      this.container.classList.add('hide');\n    }\n  }\n\n  private appendPinnedMessage(pinnedMessage: ChatPinnedMessageController) {\n    const container = pinnedMessage.container;\n    if(this.pinnedMessage && this.pinnedMessage !== pinnedMessage) {\n      this.pinnedMessage.container.replaceWith(container);\n    } else {\n      this.floatingPlatesWrapper.prepend(container);\n    }\n  }\n\n  private pinnedMessageSetupForPeerId: PeerId | undefined;\n  /**\n   * Plate swap deferred from `setupPinnedMessageForPeer` until the\n   * bubbles-mount moment inside `bubbles.setPeer`. `kind='install'`\n   * carries a detached new plate and (optionally) a `prepareInitialPromise`\n   * that resolves once the new plate's content is rendered — awaited\n   * by `revealPreparedPinnedMessage` with a timeout so plate and bubbles\n   * paint together. `kind='destroy'` means the new peer has no plate,\n   * but the old one must stay visible until bubbles swap.\n   */\n  private pendingPinnedSetup:\n    | {kind: 'install', newPlate: ChatPinnedMessageController, prepareInitialPromise?: Promise<void>}\n    | {kind: 'destroy'}\n    | null = null;\n\n  /**\n   * Prepare the pinned-message plate for the chat's current peer. Called\n   * from `finishPeerChange` alongside the other plates (after\n   * `onChangePeer` has updated `messagesStorageKey` / `this.type` /\n   * etc), so peer-derived lookups inside `prepareInitial` already point\n   * at the new peer.\n   *\n   * Does NOT touch the DOM — the change is staged into\n   * `pendingPinnedSetup` and applied atomically by\n   * `revealPreparedPinnedMessage` right before bubbles mount, so plate\n   * and bubbles paint in the same frame.\n   *\n   * Idempotent per peerId. Returns the `prepareInitial` promise (if\n   * any) so callers can await content readiness in parallel with the\n   * other `finishPeerChange` promises.\n   */\n  public setupPinnedMessageForPeer(): Promise<void> | undefined {\n    const peerId = this.chat.peerId;\n    if(this.pinnedMessageSetupForPeerId === peerId) {\n      return this.pendingPinnedSetup?.kind === 'install' ?\n        this.pendingPinnedSetup.prepareInitialPromise :\n        undefined;\n    }\n    this.pinnedMessageSetupForPeerId = peerId;\n\n    // Drop an orphaned pending plate from an even earlier peer change.\n    if(this.pendingPinnedSetup?.kind === 'install') {\n      this.pendingPinnedSetup.newPlate.destroy();\n    }\n    this.pendingPinnedSetup = null;\n\n    const isPinnedMessagesNeeded = this.chat.isPinnedMessagesNeeded();\n    const wantsPlate = isPinnedMessagesNeeded || this.chat.type === ChatType.Discussion;\n    if(!wantsPlate) {\n      if(this.pinnedMessage) {\n        this.pendingPinnedSetup = {kind: 'destroy'};\n      }\n      return;\n    }\n\n    const newPlate = createChatPinnedMessage(this, this.chat, this.managers);\n    let prepareInitialPromise: Promise<void> | undefined;\n\n    if(this.chat.type === ChatType.Discussion) {\n      newPlate.setStaticMessage(this.chat.threadId);\n    } else {\n      newPlate.setUserHidden(!!this.chat.appState.hiddenPinnedMessages[peerId]);\n      const savedPosition = this.chat.appImManager.getChatSavedPosition(this.chat);\n      const cachedFull = untrack(() => this.chat.fullPeer());\n      // Prefer the full saved plate state (mid + index + count) so the\n      // plate restores exactly the view the user left on — including the\n      // pin-list border indicator and counter. Fall back to fullPeer's\n      // `pinned_msg_id`, which is always the newest pin (index 0).\n      const hint = savedPosition?.pinnedMessages ||\n        (cachedFull?.pinned_msg_id ? {mid: cachedFull.pinned_msg_id, index: 0, count: 1} : undefined);\n      if(hint) {\n        prepareInitialPromise = newPlate.prepareInitial(hint);\n      }\n    }\n\n    this.pendingPinnedSetup = {kind: 'install', newPlate, prepareInitialPromise};\n    return prepareInitialPromise;\n  }\n\n  /**\n   * Apply the deferred plate change synchronously. Called from the\n   * `finishPeerChange` sync callback, *after* `Promise.all(promises)`\n   * already awaited `prepareInitialPromise` — so the new plate's content\n   * is in the DOM by now. The install + reveal lands in the same task as\n   * the surrounding bubbles work, painting together.\n   */\n  public revealPreparedPinnedMessage() {\n    const pending = this.pendingPinnedSetup;\n    if(!pending) {\n      this.pinnedMessage?.revealPrepared();\n      return;\n    }\n    this.pendingPinnedSetup = null;\n\n    const old = this.pinnedMessage;\n    if(pending.kind === 'install') {\n      this.appendPinnedMessage(pending.newPlate);\n      this.pinnedMessage = pending.newPlate;\n      pending.newPlate.revealPrepared();\n    } else {\n      this.pinnedMessage = undefined;\n    }\n    old?.destroy();\n    this.setFloating();\n  }\n\n  public async finishPeerChange(options: Parameters<Chat['finishPeerChange']>[0]) {\n    const {peerId, threadId, monoforumThreadId} = this.chat;\n    const {middleware} = options;\n\n    let newAvatar: ChatTopbar['avatar'], newAvatarMiddlewareHelper: ChatTopbar['avatarMiddlewareHelper'];\n    const isSaved = this.chat.type === ChatType.Saved;\n    const needArrowBack = this.chat.type === ChatType.Search;\n    if([ChatType.Chat, ChatType.Static, ChatType.Logs].includes(this.chat.type) || isSaved) {\n      const usePeerId = monoforumThreadId ||(isSaved ? threadId : peerId);\n      const useThreadId = isSaved ? undefined : threadId;\n      const avatar = this.avatar;\n\n\n      if(\n        !avatar ||\n        avatar.node.dataset.peerId.toPeerId() !== usePeerId ||\n        avatar.node.dataset.threadId !== (useThreadId ? '' + useThreadId : undefined) ||\n        peerId === rootScope.myId\n      ) {\n        newAvatar = avatarNew({\n          middleware: (newAvatarMiddlewareHelper = getMiddleware()).get(),\n          isDialog: true,\n          size: 40,\n          peerId: usePeerId,\n          threadId: useThreadId,\n          wrapOptions: {customEmojiSize: makeMediaSize(30, 30)},\n          withStories: true,\n          withVideoAvatar: true,\n          meAsNotes: isSaved\n        });\n        newAvatar.node.classList.add('person-avatar');\n      } else {\n        newAvatar = this.avatar;\n      }\n    }\n\n    this.status?.destroy();\n    const status = this.status = this.createStatus();\n\n    const promises = [\n      this.managers.appPeersManager.isBroadcast(peerId),\n      this.managers.appPeersManager.isAnyChat(peerId),\n      peerId.isAnyChat() ? this.chat.peer : undefined,\n      newAvatar?.readyThumbPromise,\n      this.setTitleManual(),\n      status?.prepare(true),\n      modifyAckedPromise(this.plates.requests.setPeerId(peerId)),\n      modifyAckedPromise(this.plates.actions.setPeerId(peerId)),\n      modifyAckedPromise(this.plates.removeFee.setPeerId(peerId)),\n      this.chat.type === ChatType.Chat ? await modifyAckedPromise(this.chat.getAutoDeletePeriod()) : undefined,\n      this.setupPinnedMessageForPeer()\n    ] as const;\n\n    const [\n      isBroadcast,\n      isAnyChat,\n      chat,\n      _,\n      setTitleCallback,\n      setStatusCallback,\n      setRequestsCallback,\n      setActionsCallback,\n      setChatRemoveFeeCallback,\n      autoDeletePeriod,\n      _pinnedReady\n    ] = await Promise.all(promises);\n\n    if(!middleware() && newAvatarMiddlewareHelper) {\n      newAvatarMiddlewareHelper.destroy();\n    }\n\n    return () => {\n      const canHaveSomeButtons = !(this.chat.type === ChatType.Pinned || this.chat.type === ChatType.Scheduled || this.chat.type === ChatType.Static || this.chat.type === ChatType.Logs);\n      const canHaveSearch = canHaveSomeButtons || this.chat.type === ChatType.Logs;\n\n      if(this.btnSearch) {\n        this.btnSearch.classList.toggle('hide', !canHaveSearch);\n      }\n\n      if(this.btnLogFilters) {\n        this.btnLogFilters.classList.toggle('hide', this.chat.type !== ChatType.Logs);\n      }\n\n      if(this.avatar !== newAvatar) {\n        if(newAvatar) {\n          this.person.prepend(newAvatar.node);\n        }\n\n        if(this.avatar) {\n          this.avatarMiddlewareHelper.destroy();\n          this.avatar.node.remove();\n        }\n\n        this.avatar = newAvatar;\n        this.avatarMiddlewareHelper = newAvatarMiddlewareHelper;\n        this.container.classList.toggle('has-avatar', !!newAvatar);\n      }\n\n      callbackify(autoDeletePeriod?.result, (value) => {\n        this.avatar?.setAutoDeletePeriod(value);\n      });\n\n      this.verifyButtons();\n\n      const canHaveMore = canHaveSomeButtons || this.chat.type === ChatType.Logs;\n\n      if(this.btnMore) {\n        this.btnMore.classList.toggle('hide', !canHaveMore);\n      }\n\n      this.revealPreparedPinnedMessage();\n      setTitleCallback();\n      setStatusCallback?.();\n\n      this.subtitle.classList.toggle('hide', !setStatusCallback);\n\n      this.container.classList.remove('hide');\n\n      if(setRequestsCallback.result instanceof Promise) {\n        this.plates.requests.unset(peerId);\n      }\n\n      if(setActionsCallback.result instanceof Promise) {\n        this.plates.actions.unset(peerId);\n      }\n\n      if(setChatRemoveFeeCallback.result instanceof Promise) {\n        this.plates.removeFee.hide();\n      }\n\n      this.plates.live?.setPeerId(peerId);\n      this.plates.translation.setPeerId(peerId);\n      this.plates.sponsored.setPeerId(peerId);\n      this.plates.crmTicket.setPeerId(peerId);\n      Promise.resolve(peerId.isUser() ? rootScope.managers.appCrmManager.getTicketStatusCached(peerId) : undefined)\n      .then((status) => this.setCrmTicketBadge(status));\n\n      callbackify(setRequestsCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      callbackify(setActionsCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      callbackify(setChatRemoveFeeCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      this.container.classList.toggle('show-back-button', needArrowBack);\n    };\n  }\n\n  private setCrmTicketBadge(status?: string) {\n    if(!this.crmTicketBadge) return;\n\n    if(!status || !this.peerId?.isUser()) {\n      this.crmTicketBadge.classList.add('hide');\n      this.crmTicketBadge.textContent = '';\n      delete this.crmTicketBadge.dataset.status;\n      return;\n    }\n\n    this.crmTicketBadge.textContent = status;\n    this.crmTicketBadge.dataset.status = status;\n    this.crmTicketBadge.classList.remove('hide');\n  }\n\n  public async setTitleManual(count?: number) {\n    const {peerId, threadId, monoforumThreadId} = this.chat;\n    let titleEl: HTMLElement, icons: Element[];\n    const oldMiddlewareHelper = this.titleMiddlewareHelper;\n    oldMiddlewareHelper?.destroy();\n    const middlewareHelper = this.titleMiddlewareHelper = getMiddleware();\n    const middleware = middlewareHelper.get();\n    if(this.chat.type === ChatType.Pinned) {\n      if(count === undefined) titleEl = i18n('Loading');\n      else titleEl = i18n('PinnedMessagesCount', [count]);\n\n      if(count === undefined) {\n        this.managers.appMessagesManager.getSearchCounters(\n          peerId,\n          [{_: 'inputMessagesFilterPinned'}],\n          false\n        ).then((result) => {\n          if(!middleware()) return;\n          const count = result[0].count;\n          this.setTitle(count);\n\n          // ! костыль х2, это нужно делать в другом месте\n          if(!count) {\n            this.chat.appImManager.setPeer(); // * close tab\n\n            // ! костыль, это скроет закреплённые сообщения сразу, вместо того, чтобы ждать пока анимация перехода закончится\n            const originalChat = this.chat.appImManager.chat;\n            if(originalChat.topbar.pinnedMessage) {\n              originalChat.topbar.pinnedMessage.setHidden(true);\n            }\n          }\n        });\n      }\n    } else if(this.chat.type === ChatType.Scheduled) {\n      titleEl = i18n(peerId === rootScope.myId ? 'Reminders' : 'ScheduledMessages');\n    } else if(this.chat.type === ChatType.Discussion) {\n      const el = this.messagesCounter({\n        middleware,\n        key: 'Chat.Title.Comments',\n        minusFirst: this.chat.isForum\n      });\n      if(count === undefined) {\n        const historyStorage = this.chat.getHistoryStorage();\n        if(!middleware()) return;\n        el.compareAndUpdate(typeof(historyStorage.count) !== 'number' ?\n          {key: 'Loading', args: undefined} :\n          {args: [historyStorage.count - (this.chat.isForum ? 1 : 0)]}\n        );\n      }\n\n      titleEl = el.element;\n    } else if(this.chat.type === ChatType.Chat || this.chat.type === ChatType.Saved || this.chat.type === ChatType.Static || this.chat.type === ChatType.Logs) {\n      const usePeerId = monoforumThreadId || (this.chat.type === ChatType.Saved ? threadId : peerId);\n\n      [titleEl/* , icons */] = await Promise.all([\n        wrapPeerTitle({\n          peerId: usePeerId,\n          dialog: true,\n          withIcons: !threadId,\n          threadId: threadId,\n          wrapOptions: {middleware},\n          meAsNotes: this.chat.type === ChatType.Saved\n        })\n        // generateTitleIcons(peerId)\n      ]);\n\n      if(!middleware()) {\n        return;\n      }\n    }\n\n    return () => {\n      replaceContent(this.title, titleEl);\n      // if(icons) {\n      //   this.title.append(...icons);\n      // }\n    };\n  }\n\n  public setTitle(count?: number) {\n    this.setTitleManual(count).then((setTitleCallback) => setTitleCallback());\n  }\n\n  public setFloating = () => {\n    // Preview omits `floatingPlatesWrapper` from the live DOM (see `construct`). The plate\n    // controllers still exist for the rest of the code, and a peer with a pinned message\n    // would mark the pinnedMessage plate visible — its hardcoded `height: 48` + TOPBAR_GAP\n    // would leak into `--pinned-floating-height` / `pinnedFloatingHeightPx` and inflate\n    // `bubbles-padding-top` from 56 to 112 above the first message. Bail early.\n    if(this.chat.isPreview) return;\n    const containers = [\n      this.pinnedMessage,\n      ...(this.plates?.all || [])\n    ].filter(Boolean);\n    const TOPBAR_GAP = 8;\n    const PLATE_DIVIDER = 1;\n\n    const visible = containers.filter((container) => container.isVisible());\n    const count = visible.length;\n\n    // Un-hide the wrapper BEFORE measuring any 'auto' plate height below. The\n    // wrapper is `display: none` while no plate is visible (count === 0), and an\n    // ancestor's `display: none` zeroes its descendants' offsetHeight — so the\n    // sponsored plate (the only `height: 'auto'` one), exactly when it is the\n    // plate that flips the count 0 → 1, would otherwise be measured at 0 and\n    // never reserve its padding-top, leaving it overlapping the chat content.\n    this.floatingPlatesWrapper.classList.toggle('hide', count === 0);\n\n    let platesHeight = 0;\n    for(const container of visible) {\n      platesHeight += container.height === 'auto' ? container.container.offsetHeight : container.height;\n    }\n\n    const floatingHeight = count > 0 ? platesHeight + Math.max(0, count - 1) * PLATE_DIVIDER + TOPBAR_GAP : 0;\n    this.container.dataset.floating = '' + count;\n    this.chat.container.style.setProperty(\n      '--pinned-floating-height',\n      `calc(${floatingHeight}px + var(--topbar-floating-call-height) + var(--topbar-floating-audio-height))`\n    );\n    this.chat.updatePinnedFloatingHeight(floatingHeight);\n  };\n\n  private messagesCounter({\n    middleware,\n    key,\n    minusFirst,\n    displayLoading\n  }: {\n    middleware: Middleware,\n    key: LangPackKey,\n    minusFirst?: boolean,\n    displayLoading?: boolean\n  }) {\n    const el = new I18n.IntlElement(displayLoading ? {\n      key: 'Loading'\n    } : {\n      key,\n      args: [1]\n    });\n\n    createRoot((dispose) => {\n      middleware.onDestroy(dispose);\n\n      createEffect(on(\n        () => [this.chat.historyStorage.count, this.chat.historyStorage.wasFetched] as const,\n        ([count]) => {\n          el.compareAndUpdate({key, args: [count - (minusFirst ? 1 : 0)]});\n        },\n        {defer: displayLoading ? !this.chat.historyStorage.wasFetched : true}\n      ));\n    });\n\n    return el;\n  }\n\n  private createStatus() {\n    if(!this.subtitle || (this.chat.type !== ChatType.Chat && this.chat.type !== ChatType.Saved)) return;\n    const middlewareHelper = getMiddleware();\n    const middleware = middlewareHelper.get();\n    const listenerSetter = new ListenerSetter();\n\n    let prepare: (needClear: boolean) => Promise<() => void>;\n    if(this.chat.type === ChatType.Saved || this.peerId === rootScope.myId) {\n      const el = this.messagesCounter({\n        middleware,\n        key: 'messages',\n        displayLoading: this.peerId === rootScope.myId\n      });\n\n      prepare = async() => {\n        const historyStorage = this.chat.getHistoryStorage();\n        el.compareAndUpdate({args: [historyStorage.count]});\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else if(this.chat.threadId) {\n      prepare = async() => {\n        const title = await wrapPeerTitle({peerId: this.peerId, dialog: true});\n        const span = i18n('TopicProfileStatus', [title]);\n\n        return () => replaceContent(this.subtitle, span);\n      };\n    } else if(this.chat.isMonoforum && this.chat.canManageDirectMessages && !this.chat.monoforumThreadId) {\n      listenerSetter.add(rootScope)('monoforum_dialogs_update', ({dialogs}) => {\n        if(!dialogs.find(dialog => dialog.parentPeerId === this.chat.peerId)) return;\n        setAuto();\n      });\n\n      listenerSetter.add(rootScope)('monoforum_dialogs_drop', () => {\n        setAuto();\n      });\n\n      prepare = async() => {\n        const ackedResult = await this.managers.acknowledged.monoforumDialogsStorage.getDialogs({parentPeerId: this.peerId, limit: 1});\n        const initialCount = ackedResult.cached ? (await ackedResult.result).count || 0 : '~';\n\n        const el = new I18n.IntlElement({\n          key: 'ChannelDirectMessages.ThreadsCount',\n          args: [initialCount]\n        });\n\n        if(!ackedResult.cached) ackedResult.result?.then(({count}) => el.compareAndUpdate({\n          key: 'ChannelDirectMessages.ThreadsCount',\n          args: [count]\n        }));\n\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else if(this.chat.isMonoforum) {\n      listenerSetter.add(rootScope)('history_multiappend', (message) => {\n        if(message.peerId !== this.chat.peerId) return;\n        if(this.chat.monoforumThreadId && getPeerId(message?.saved_peer_id) !== this.chat.monoforumThreadId) return;\n        setAuto();\n      });\n\n      listenerSetter.add(rootScope)('history_delete', ({peerId}) => {\n        if(peerId !== this.chat.peerId) return;\n        setAuto();\n      });\n\n      prepare = async() => {\n        const ackedResult = await this.managers.acknowledged.appMessagesManager.getHistory({\n          ...this.chat.requestHistoryOptionsPart,\n          fetchIfWasNotFetched: true,\n          limit: 1\n        });\n\n        const initialCount = ackedResult.cached ? (await ackedResult.result).count || 0 : '~';\n\n        const el = new I18n.IntlElement({\n          key: 'ChannelDirectMessages.MessagesCount',\n          args: [initialCount]\n        });\n\n        if(!ackedResult.cached) ackedResult.result?.then(({count}) => el.compareAndUpdate({\n          key: 'ChannelDirectMessages.MessagesCount',\n          args: [count]\n        }));\n\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else {\n      const peerId = this.peerId;\n\n      listenerSetter.add(rootScope)('peer_typings', ({peerId: _peerId}) => {\n        if(peerId === _peerId) {\n          setAuto();\n        }\n      });\n\n      listenerSetter.add(rootScope)('user_update', (userId) => {\n        if(peerId === userId.toPeerId()) {\n          setAuto();\n        }\n      });\n\n      const interval = window.setInterval(() => setAuto(), 60e3);\n\n      middleware.onDestroy(() => {\n        clearInterval(interval);\n      });\n\n      prepare = (needClear) => {\n        return this.chat.appImManager.setPeerStatus({\n          peerId,\n          element: this.subtitle,\n          needClear,\n          useWhitespace: false,\n          middleware\n        });\n      };\n    }\n\n    middleware.onDestroy(() => {\n      listenerSetter.removeAll();\n    });\n\n    const setAuto = () => {\n      prepare(false).then((callback) => middleware() && callback?.());\n    };\n\n    return {\n      prepare,\n      destroy: () => middlewareHelper.destroy()\n    };\n  }\n\n  private async createAutoDeleteSubmenu() {\n    const options = getDefaultOptions({\n      offLabel: () => i18n('Never')\n    });\n\n    const menu = await ButtonMenu({\n      buttons: [\n        ...options.map((option): ButtonMenuItemOptionsVerifiable => ({\n          iconElement: option.value === 0 ? Icon('auto_delete_circle_off') : createAutoDeleteIcon(option.value),\n          regularText: option.label(),\n          onClick: () => {\n            this.managers.appPrivacyManager.setAutoDeletePeriodFor(this.peerId, option.value);\n          }\n        })),\n        {\n          icon: 'tools',\n          text: 'Other',\n          onClick: () => this.chat.openAutoDeleteMessagesCustomTimePopup()\n        }\n      ]\n    });\n\n    return menu;\n  }\n}\n","export default function stringMiddleOverflow(str: string, maxLength: number) {\n  if(str.length <= maxLength) {\n    return str;\n  }\n\n  const ellipsis = '...';\n  const budget = Math.max(0, maxLength - ellipsis.length);\n  const headLength = budget - (budget >> 1); // ceil(budget / 2)\n  const tailLength = budget >> 1; // floor(budget / 2)\n  return str.slice(0, headLength) + ellipsis + (tailLength ? str.slice(-tailLength) : '');\n}\n","/**\n * Schedules a side effect to run in a microtask,\n * outside of the current reactive batch/effect.\n */\nexport default function deferSideEffect(callback: () => void) {\n  queueMicrotask(callback);\n}\n","import type {ReactionsContext} from '@appManagers/appReactionsManager';\nimport type {RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {createEffect, createSignal, onCleanup, JSX, createMemo, onMount, on, untrack, batch, Accessor} from 'solid-js';\nimport InputSearch from '@components/inputSearch';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport classNames from '@helpers/string/classNames';\nimport PopupElement from '@components/popups';\nimport showDatePickerPopup from '@components/popups/datePicker';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {ChannelsChannelParticipants, Message, MessageReactions, Reaction, ReactionCount, SavedReactionTag} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {createLoadableList} from '@components/sidebarRight/tabs/statistics';\nimport {Middleware, getMiddleware} from '@helpers/middleware';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport whichChild from '@helpers/dom/whichChild';\nimport appImManager from '@lib/appImManager';\nimport attachListNavigation from '@helpers/dom/attachListNavigation';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport I18n, {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport stringMiddleOverflow from '@helpers/string/stringMiddleOverflow';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport {FontFull} from '@config/font';\nimport Row from '@components/row';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport {avatarNew} from '@components/avatarNew';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport PeerTitle from '@components/peerTitle';\nimport ReactionsElement from '@components/chat/reactions';\nimport ReactionElement, {ReactionLayoutType} from '@components/chat/reaction';\nimport Scrollable from '@components/scrollable2';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport Icon from '@components/icon';\nimport PopupPremium from '@components/popups/premium';\nimport usePremium from '@stores/premium';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport Animated from '@helpers/solid/animations';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from './chatType';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport getHistoryStorageKey, {getHistoryStorageType} from '@appManagers/utils/messages/getHistoryStorageKey';\nimport {ScreenSize, useMediaSizes} from '@helpers/mediaSizes';\nimport ButtonCorner from '@components/buttonCorner';\nimport deferSideEffect from '@helpers/solid/deferSideEffect';\n\ntype SearchType = RequestHistoryOptions['hashtagType'];\nconst SEARCH_TYPES: SearchType[] = ['this', 'my', 'public'];\nconst DEFAULT_SEARCH_TYPE: SearchType = undefined;\n\ntype LoadOptions = {\n  middleware: Middleware,\n  peerId: PeerId,\n  threadId: number,\n  monoforumThreadId: PeerId,\n  query: string,\n  fromPeerId?: PeerId,\n  reaction?: Reaction,\n  searchType?: SearchType\n};\n\nconst renderHistoryResult = ({middleware, peerId, fromSavedDialog, messages, query, searchType/* , fromPeerId */}: LoadOptions & {fromSavedDialog: boolean, messages: (Message.message | Message.messageService)[]}) => {\n  const promises = messages.map(async(message) => {\n    const fromPeerId = message.fromId;\n    const loadPromises: Promise<any>[] = [];\n    const {dom} = appDialogsManager.addDialogAndSetLastMessage({\n      peerId: fromSavedDialog ? rootScope.myId : (fromPeerId || peerId),\n      container: false,\n      avatarSize: 'abitbigger',\n      meAsSaved: searchType === 'my',\n      message,\n      query,\n      // noIcons: this.noIcons,\n      wrapOptions: {\n        middleware\n      },\n      loadPromises,\n      threadId: fromSavedDialog ? ((message as Message.message).saved_peer_id ? getPeerId((message as Message.message).saved_peer_id) : rootScope.myId) : undefined,\n      autonomous: true\n    });\n\n    await Promise.all(loadPromises);\n    return dom.containerEl;\n  });\n\n  return Promise.all(promises);\n};\n\nconst createSearchLoader = (options: LoadOptions) => {\n  const {middleware, peerId, threadId, query, fromPeerId, reaction, searchType, monoforumThreadId} = options;\n  const fromSavedDialog = !!(peerId === rootScope.myId && threadId);\n  let lastMessage: Message.message | Message.messageService, loading = false, nextRate: number;\n  const loadMore = async() => {\n    if(loading) {\n      return;\n    }\n    loading = true;\n\n    const offsetId = lastMessage?.mid || 0;\n    const offsetPeerId = lastMessage?.peerId || NULL_PEER_ID;\n    const requestHistoryOptions: RequestHistoryOptions = {\n      peerId: searchType === 'this' || !searchType ? peerId : NULL_PEER_ID,\n      threadId: searchType === 'this' || !searchType ? threadId : undefined,\n      monoforumThreadId,\n      query,\n      inputFilter: {_: 'inputMessagesFilterEmpty'},\n      offsetId,\n      offsetPeerId,\n      limit: 30,\n      fromPeerId,\n      savedReaction: reaction ? [reaction as Reaction.reactionEmoji] : undefined,\n      nextRate,\n      isPublicHashtag: searchType === 'public',\n      isCacheableSearch: !!searchType,\n      hashtagType: searchType\n    };\n\n    const key = getHistoryStorageKey({type: getHistoryStorageType(requestHistoryOptions), ...requestHistoryOptions});\n    rootScope.managers.appMessagesManager.toggleHistoryKeySubscription(key, true);\n    onCleanup(() => {\n      rootScope.managers.appMessagesManager.toggleHistoryKeySubscription(key, false);\n    });\n\n    const result = await rootScope.managers.appMessagesManager.getHistory(requestHistoryOptions);\n    if(!middleware()) {\n      return;\n    }\n\n    let messages: Message.message[];\n    if(result.messages) {\n      messages = result.messages as Message.message[];\n      nextRate = result.nextRate;\n    } else {\n      messages = result.history.map((mid) => apiManagerProxy.getMessageByPeer(peerId, mid)) as Message.message[];\n    }\n\n    const rendered = await renderHistoryResult({...options, fromSavedDialog, messages});\n    if(!middleware()) {\n      return;\n    }\n\n    setF((value) => {\n      value.count = result.count;\n      value.values.push(...messages);\n      lastMessage = messages[messages.length - 1];\n      if(result.isEnd.top) {\n        value.loadMore = undefined;\n      }\n\n      value.rendered.push(...rendered);\n      return value;\n    });\n    loading = false;\n  };\n\n  const [f, setF] = createLoadableList<Message.message | Message.messageService>({loadMore});\n  return f;\n};\n\nconst createParticipantsLoader = (options: LoadOptions) => {\n  const {middleware, peerId, query} = options;\n  let loading = false, offset = 0;\n  const loadMore = async() => {\n    if(loading) {\n      return;\n    }\n    loading = true;\n\n    const result = await rootScope.managers.appProfileManager.getParticipants({\n      id: peerId.toChatId(),\n      filter: {_: 'channelParticipantsSearch', q: query},\n      limit: 30,\n      offset,\n      forMessagesSearch: true\n    });\n    if(!middleware()) {\n      return;\n    }\n\n    const peerIds = result.participants.map(getParticipantPeerId);\n    const promises = peerIds.map(async(peerId) => {\n      const title = await wrapPeerTitle({peerId});\n      const peer = apiManagerProxy.getPeer(peerId);\n      const username = getPeerActiveUsernames(peer)[0];\n      const row = new Row({\n        title: (\n          <span>\n            <b>{title}</b> {username && <span class=\"secondary\">{`@${username}`}</span>}\n          </span>\n        ) as HTMLElement,\n        clickable: true\n      });\n\n      row.container.classList.add('topbar-search-left-sender');\n\n      const size = 40;\n      const avatar = avatarNew({peerId, size, middleware});\n      row.createMedia(`${size}`).append(avatar.node);\n      await avatar.readyThumbPromise;\n\n      return row.container;\n    });\n\n    const rendered = await Promise.all(promises);\n    if(!middleware()) {\n      return;\n    }\n\n    setF((value) => {\n      value.count = (result as ChannelsChannelParticipants.channelsChannelParticipants).count ?? peerIds.length;\n      const newLength = value.values.push(...peerIds);\n      offset = newLength;\n      if(newLength >= value.count) {\n        value.loadMore = undefined;\n      }\n\n      value.rendered.push(...rendered);\n      return value;\n    });\n    loading = false;\n  };\n\n  const [f, setF] = createLoadableList<PeerId>({loadMore});\n  return f;\n};\n\nfunction SearchFooter(props: {\n  index: () => number,\n  count: () => number,\n  pickUserBtn: JSX.Element,\n  pickDateBtn: JSX.Element,\n  resultsShown: () => boolean,\n  onToggle: () => void,\n  choosingSender: () => boolean\n}) {\n  return (\n    <div class={classNames('chat-search-footer', props.choosingSender() && 'hide')}>\n      <div class=\"chat-search-footer-left\">\n        {props.pickDateBtn}\n        {props.pickUserBtn}\n        <span class={classNames('chat-search-footer-count', props.count() === undefined && 'hide')}>\n          {\n            props.count() === 0 ?\n              i18n('NoResult') :\n              props.resultsShown() ? i18n('messages', [props.count()]) : i18n('Of', [props.index() + 1, props.count()])\n          }\n        </span>\n      </div>\n      <div class={classNames('chat-search-footer-right', !props.count() && 'hide')}>\n        <span\n          class=\"chat-search-footer-type\"\n          onClick={() => props.onToggle()}\n        >\n          {i18n(props.resultsShown() ? 'SearchAsChat' : 'SearchAsList')}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nfunction SearchMobileResults(props: {\n  scrollable: JSX.Element\n}) {\n  return (\n    <div class=\"chat-search-results chatlist-container\">\n      {props.scrollable}\n    </div>\n  );\n}\n\nfunction SearchMobileTop(props: {\n  reactionsScrollable: JSX.Element,\n  searchTypesScrollable: JSX.Element,\n  hasReactions: () => boolean,\n  hasSearchTypes: () => boolean\n}) {\n  return (\n    <div class=\"chat-search-top\">\n      {props.hasSearchTypes() ? props.searchTypesScrollable : props.reactionsScrollable}\n    </div>\n  );\n}\n\nfunction SearchMobileButtons(props: {\n  index: () => number,\n  count: () => number,\n  chat: Chat,\n  onArrowButtonClick: (direction: 'up' | 'down') => void\n}) {\n  const makeButton = (icon: 'up' | 'down', onClick: () => void) => {\n    const btn = ButtonCorner({icon, className: 'bubbles-corner-button chat-secondary-button chat-search-go chat-search-go-' + icon});\n    const detach = attachClickEvent(btn, onClick);\n    onCleanup(detach);\n\n    const isEnd = createMemo(() => {\n      if(icon === 'down') {\n        return props.index() === 0;\n      } else {\n        return props.index() === props.count() - 1;\n      }\n    });\n\n    createEffect(() => {\n      btn.classList.toggle('is-end', isEnd());\n      btn.classList.toggle('hide', (props.count() || 0) < 2);\n    });\n\n    return btn;\n  };\n\n  const buttons = [\n    makeButton('up', props.onArrowButtonClick.bind(null, 'up')),\n    makeButton('down', props.onArrowButtonClick.bind(null, 'down'))\n  ];\n\n  props.chat.bubbles.container.after(...buttons);\n  onCleanup(() => {\n    buttons.forEach((button) => {\n      button.remove();\n    });\n  });\n}\n\nexport default function TopbarSearch(props: {\n  chat: Chat,\n  chatType: ChatType,\n  peerId: PeerId,\n  threadId?: number,\n  filterPeerId: Accessor<PeerId>,\n  canFilterSender?: boolean,\n  query?: Accessor<string>,\n  reaction?: Accessor<Reaction>,\n  onClose?: () => void,\n  onDatePick?: (timestamp: number) => void,\n  onActive?: (active: boolean, showingReactions: boolean, isSmallScreen: boolean) => void,\n  onSearchTypeChange?: () => void,\n  onValueChange?: (value: string) => void,\n  noList?: boolean\n}) {\n  const mediaSizes = useMediaSizes();\n  const isSmallScreen = createMemo(() => mediaSizes.activeScreen === ScreenSize.mobile);\n  const [isInputFocused, setIsInputFocused] = createSignal(false);\n  const [value, setValue] = createSignal<string>('');\n  const [count, setCount] = createSignal<number>();\n  const [totalCount, setTotalCount] = createSignal<number>();\n  const [list, setList] = createSignal<{element: HTMLElement, type: 'messages' | 'senders'}>();\n  const [messages, setMessages] = createSignal<(Message.message | Message.messageService)[]>();\n  const [sendersPeerIds, setSendersPeerIds] = createSignal<PeerId[]>();\n  const [loadMore, setLoadMore] = createSignal<() => Promise<void>>();\n  const [target, setTarget] = createSignal<HTMLElement>(undefined, {equals: false});\n  const [filteringSender, setFilteringSender] = createSignal<boolean>(false);\n  const [filterPeerId, setFilterPeerId] = createSignal<PeerId>();\n  const [senderInputEntity, setSenderInputEntity] = createSignal<HTMLElement>();\n  const [savedReactionTags, setSavedReactionTags] = createSignal<SavedReactionTag[]>(undefined, {equals: false});\n  const [reactionsElement, setReactionsElement] = createSignal<ReactionsElement>();\n  const [reaction, setReaction] = createSignal<Reaction>(undefined, {equals: false});\n  const [searchType, setSearchType] = createSignal<SearchType>(DEFAULT_SEARCH_TYPE);\n  const [showingSmallResults, setShowingSmallResults] = createSignal(false);\n  const choosingSender = createMemo(() => filteringSender() && !filterPeerId());\n  const shouldShowResults = createMemo(() => isSmallScreen() ? showingSmallResults() : isInputFocused());\n  const shouldHaveListNavigation = createMemo(() => (shouldShowResults() && count() && list()) || undefined);\n  const lookingHashtag = createMemo(() => {\n    if(filteringSender() || reaction()) return;\n    const _value = value();\n    return _value.startsWith('#') ? _value.slice(1) : undefined;\n  });\n  const isHashtag = createMemo(() => lookingHashtag() !== undefined);\n  const shouldShowReactions = createMemo(() => {\n    if(isHashtag()) return false;\n    const element = reactionsElement();\n    const tags = savedReactionTags();\n    return !!(element && tags?.length);\n  });\n  const shouldShowSearchTypes = createMemo(() => isHashtag());\n  const shouldShowFromPlaceholder = createMemo(() => (!isSmallScreen() || !filterPeerId()) && filteringSender());\n  const isActive = createMemo(() => isSmallScreen() || shouldShowReactions()/*  || shouldShowSearchTypes() */ || shouldShowResults());\n  const isPremium = usePremium();\n\n  if(props.onActive) {\n    createEffect(() => {\n      props.onActive(isActive(), shouldShowReactions(), isSmallScreen());\n    });\n\n    onCleanup(() => {\n      props.onActive(false, false, isSmallScreen());\n    });\n  }\n\n  createEffect(() => {\n    props.onValueChange?.(value());\n  });\n\n  // * full search replacement\n  createEffect(() => {\n    inputSearch.onChange(inputSearch.value = props.query());\n    setFilteringSender(!!props.filterPeerId());\n    setFilterPeerId(props.filterPeerId());\n    setReaction(props.reaction());\n\n    onMount(() => {\n      placeCaretAtEnd(inputSearch.input);\n    });\n  });\n\n  // * list navigation\n  createEffect(() => {\n    const {element} = shouldHaveListNavigation() || {};\n    if(!element) {\n      return;\n    }\n\n    const list = element.firstElementChild as HTMLElement;\n    const activeClassName = 'menu-open';\n    const el = list.querySelector(`.${activeClassName}`);\n    el && el.classList.remove(activeClassName);\n    const {detach} = attachListNavigation({\n      list,\n      type: 'y',\n      onSelect: (target) => {\n        const shouldBlur = !!(!filteringSender() || filterPeerId());\n        setTarget(target as HTMLElement);\n        if(shouldBlur) {\n          blurActiveElement();\n        }\n      },\n      activeClassName,\n      cancelMouseDown: true,\n      target: untrack(target)\n    });\n\n    onCleanup(() => {\n      detach();\n    });\n  });\n\n  const navigationItem: NavigationItem = {\n    type: 'topbar-search',\n    onPop: () => {\n      if(isInputFocused() && value()) {\n        blurActiveElement();\n        return false;\n      }\n\n      props.onClose?.();\n    }\n  };\n  appNavigationController.pushItem(navigationItem);\n  onCleanup(() => {\n    appNavigationController.removeItem(navigationItem);\n  });\n\n  const onInputClear: (e?: MouseEvent, wasEmpty?: boolean) => void = (e, wasEmpty = inputSearch.inputField.isEmpty()) => {\n    if(filterPeerId()) {\n      e && cancelEvent(e);\n      wasEmpty && setFilterPeerId(undefined);\n      return;\n    }\n\n    if(filteringSender()) {\n      e && cancelEvent(e);\n      wasEmpty && setFilteringSender(false);\n      return;\n    }\n\n    if(wasEmpty) {\n      if(isSmallScreen()) {\n        return;\n      }\n\n      props.onClose?.();\n    }\n  };\n\n  const inputSearch: InputSearch = new InputSearch({\n    placeholder: 'Search',\n    onChange: setValue,\n    onClear: onInputClear,\n    onFocusChange: setIsInputFocused,\n    onBack: () => {\n      props.onClose?.();\n    },\n    alwaysShowClear: true,\n    noBorder: true,\n    verifyDebounce: (value) => {\n      return value !== '#' &&\n        !inputSearch.container.classList.contains('show-placeholder') &&\n        !!value.trim(); // skip debounce for hashtag\n    },\n    arrowBack: isSmallScreen()\n  });\n  inputSearch.container.classList.add('topbar-search-input-container');\n  inputSearch.input.classList.add('topbar-search-input');\n  const onKeyDown = (e: KeyboardEvent) => {\n    if(e.key !== 'Backspace') {\n      return;\n    }\n\n    const isEmpty = inputSearch.inputField.isEmpty();\n    if(isEmpty && (filterPeerId() || filteringSender())) {\n      onInputClear(undefined, isEmpty);\n    }\n  };\n  subscribeOn(inputSearch.input)('keydown', onKeyDown);\n  onCleanup(() => {\n    inputSearch.remove();\n  });\n\n  const hashWidth = getTextWidth('#', FontFull);\n  const fromText = I18n.format('Search.From', true) + ' ';\n  const fromWidth = getTextWidth(fromText, FontFull);\n  const fromSpan = (<span class={classNames('topbar-search-input-from', shouldShowFromPlaceholder() && 'is-visible')}>{fromText}</span>);\n  inputSearch.container.append(fromSpan as HTMLElement);\n  createEffect<HTMLElement>((_element) => {\n    const filtering = filteringSender();\n    const _isHashtag = isHashtag();\n    if(_element) {\n      _element.classList.remove('scale-in');\n      void _element.offsetWidth;\n      _element.classList.add('scale-out');\n      setTimeout(() => {\n        _element.remove();\n      }, 200);\n    }\n\n    const element = senderInputEntity();\n    if(element) {\n      element.classList.add('topbar-search-input-entity', 'scale-in');\n      const detach = attachClickEvent(element, (e) => {\n        cancelEvent(e);\n        if(_isHashtag) {\n          setSearchType();\n        } else {\n          setFilterPeerId();\n        }\n      }, {cancelMouseDown: true});\n      onCleanup(detach);\n      inputSearch.container.append(element);\n    }\n\n    inputSearch.container.style.setProperty('--padding-placeholder', (shouldShowFromPlaceholder() ? fromWidth : 0) + 'px');\n    inputSearch.container.style.setProperty('--padding-hashtag', (_isHashtag ? hashWidth : 0) + 'px');\n    inputSearch.container.style.setProperty('--padding-sender', (element ? element.offsetWidth + 6 : 0) + 'px');\n    inputSearch.setPlaceholder(filtering && !element ? 'Search.Member' : (_isHashtag ? 'Search.Hashtag' : 'Search'));\n    return element;\n  });\n\n  // * keep placeholder while input is empty\n  createEffect(() => {\n    inputSearch.container.classList.toggle('show-placeholder', /* !value() ||  */lookingHashtag() === '');\n  });\n\n  const PeerEntity = (props: {\n    peerId?: PeerId | string,\n    fallbackIcon?: Icon,\n    title?: HTMLElement,\n    active?: Accessor<boolean>,\n    onPromises?: (promises: Promise<any>[]) => void,\n    onClick?: () => void,\n  }) => {\n    const middleware = createMiddleware().get();\n    const entity = untrack(() => AppSelectPeers.renderEntity({\n      key: props.peerId,\n      title: props.title,\n      fallbackIcon: props.fallbackIcon,\n      middleware,\n      avatarSize: 30,\n      meAsSaved: false\n    }));\n\n    if(props.active !== undefined) {\n      createEffect(() => {\n        entity.element.classList.toggle('active', props.active());\n      });\n    }\n\n    if(props.onClick) {\n      const detach = attachClickEvent(entity.element, (e) => {\n        cancelEvent(e);\n        props.onClick();\n      }, {cancelMouseDown: true});\n      onCleanup(detach);\n    }\n\n    if(props.onPromises) {\n      props.onPromises(entity.promises);\n    }\n\n    return entity.element;\n  };\n\n  const SearchTypeEntity = (_props: {\n    type: SearchType,\n    notList?: boolean,\n    onPromises?: (promises: Promise<any>[]) => void\n  }) => {\n    const peerId = _props.type === 'this' ? props.peerId : (_props.type === 'my' ? rootScope.myId : 'public');\n    const title = i18n(`Search.Types.${_props.type === 'this' ? 'ThisChat' : _props.type === 'my' ? 'MyMessages' : 'PublicPosts'}`);\n    return (\n      <PeerEntity\n        peerId={peerId}\n        title={title}\n        {...(!_props.notList && {\n          active: () => searchType() === _props.type,\n          onClick: () => setSearchType((type) => type === _props.type ? DEFAULT_SEARCH_TYPE : _props.type)\n        })}\n        fallbackIcon={_props.type === 'public' ? 'newchannel_filled' : undefined}\n        onPromises={_props.onPromises}\n      />\n    );\n  };\n\n  // * handle sender or search type entity\n  createEffect(async() => {\n    const peerId = filterPeerId();\n    const _searchType = searchType();\n    const middleware = createMiddleware().get();\n    let element: HTMLElement;\n    if(peerId || _searchType) {\n      element = await new Promise((resolve) => {\n        let element: HTMLDivElement;\n        const onPromises = async(promises: Promise<any>[]) => {\n          await Promise.all(promises);\n          return resolve(element);\n        };\n\n        if(_searchType) {\n          element = SearchTypeEntity({\n            type: _searchType,\n            notList: true,\n            onPromises\n          }) as HTMLDivElement;\n        } else {\n          element = PeerEntity({\n            peerId,\n            onPromises\n          });\n        }\n      });\n      if(!middleware()) {\n        return;\n      }\n    }\n\n    setSenderInputEntity(element);\n  });\n\n  const MIN_HEIGHT = 43;\n  const MAX_HEIGHT = 271;\n\n  const onArrowButtonClick = (direction: 'up' | 'down') => {\n    // let _target = scrollableDiv.querySelector<HTMLElement>('.active');\n    let _target = target();\n    if(!_target) {\n      _target = scrollableDiv.querySelector<HTMLElement>('.chatlist-chat');\n      setTarget(_target);\n      return;\n    }\n\n    if(direction === 'down') {\n      _target = _target.previousElementSibling as HTMLElement;\n    } else {\n      _target = _target.nextElementSibling as HTMLElement;\n    }\n\n    if(!_target || !_target.classList.contains('chatlist-chat')) {\n      return;\n    }\n\n    // set scroll position to center\n    const top = _target.offsetTop;\n    const clientHeight = MAX_HEIGHT;\n    scrollableDiv.scrollTop = top - clientHeight / 2 + _target.clientHeight / 2;\n\n    setTarget(_target);\n  };\n\n  const ArrowButton = ({direction}: {direction: 'up' | 'down'}) => {\n    return (\n      <ButtonIconTsx\n        icon={direction}\n        class={classNames(\n          'input-search-part',\n          'topbar-search-input-arrow',\n          (!count() || (filteringSender() && !filterPeerId())) && 'hide'\n        )}\n        noRipple\n        onClick={() => {\n          onArrowButtonClick(direction);\n        }}\n      />\n    );\n  };\n\n  const b = inputSearch.clearBtn.previousSibling;\n  let inputSearchTools: HTMLDivElement;\n  (<div ref={inputSearchTools} class=\"topbar-search-input-tools\">\n    {!isSmallScreen() && (\n      <>\n        <ArrowButton direction=\"up\" />\n        <ArrowButton direction=\"down\" />\n      </>\n    )}\n    {inputSearch.clearBtn}\n  </div>);\n  b.after(inputSearchTools);\n\n  const updateChatSearchContext = (searchType: SearchType, query: string) => {\n    appImManager.chat.setMessageId({\n      query: searchType && query || undefined,\n      isPublicHashtag: searchType === 'public' || undefined,\n      isCacheableSearch: !!searchType || undefined,\n      inputFilter: query && searchType ? {_: 'inputMessagesFilterEmpty'} : undefined,\n      type: query && searchType ? ChatType.Search : props.chatType,\n      hashtagType: searchType\n    });\n  };\n\n  // * search\n  createEffect<Partial<{searchType: SearchType, query: string}>>((prev) => {\n    if(props.noList) return;\n\n    prev ||= {};\n    const {peerId, threadId} = props;\n    const query = value();\n    const fromPeerId = filterPeerId();\n    const isSender = choosingSender();\n    const middleware = createMiddleware().get();\n    const isEmptyQuery = !query.trim() || query === '#';\n    const _isHashtag = isHashtag();\n    const _reaction = !isSender && reaction();\n    const _searchType = searchType();\n\n    // * reset search if it's not a hashtag anymore\n    if(_searchType && !query) {\n      setSearchType();\n      updateChatSearchContext(undefined, undefined);\n      return;\n    }\n\n    setLoadMore(() => undefined as any);\n    setMessages();\n    setSendersPeerIds();\n    setTarget();\n\n    const loader = (isSender ? createParticipantsLoader : createSearchLoader)({\n      middleware,\n      peerId,\n      threadId,\n      monoforumThreadId: props.chat.monoforumThreadId,\n      query,\n      fromPeerId,\n      reaction: _reaction,\n      searchType: _searchType\n    });\n\n    const isEmpty = createMemo(() => count() === 0 || (_isHashtag && count() === undefined));\n\n    let ref: HTMLDivElement;\n    const list = (\n      <div\n        ref={ref}\n        class={classNames(!untrack(isSmallScreen) && 'topbar-search-left-chatlist', 'chatlist', isEmpty() && 'is-empty')}\n      >\n        {isEmpty() ? (\n          <div class=\"topbar-search-left-results-empty\">\n            {_isHashtag && (count() === undefined ?\n              i18n('Search.HelpHashtag') :\n              i18n('Search.EmptyHashtag', [wrapEmojiText(stringMiddleOverflow(query, 18))]))}\n            {!_isHashtag && (fromPeerId ?\n              i18n('Search.EmptyFrom', [(() => {\n                const peerTitle = new PeerTitle({peerId: fromPeerId});\n                return peerTitle.element;\n              })()]) :\n              i18n('Search.Empty', [wrapEmojiText(stringMiddleOverflow(query, 18))])\n            )}\n          </div>\n        ) : (\n          <>\n            <div>\n              {loader().rendered}\n            </div>\n            {loader().rendered && <div class=\"topbar-search-left-results-padding\" />}\n          </>\n        )}\n      </div>\n    );\n\n    let first = true;\n    const onLoad = (firstElement?: HTMLElement) => {\n      if(first) {\n        inputSearch.toggleLoading(false);\n        setList({element: ref, type: isSender ? 'senders' : 'messages'});\n        scrollableDiv.scrollTop = 0;\n        first = false;\n\n        // * jump to first target\n        if(untrack(isSmallScreen) && !isSender) {\n          setTarget(untrack(messages) && firstElement);\n        }\n      }\n    };\n\n    if(_searchType !== prev.searchType || (_searchType && query !== prev.query)) {\n      props.onSearchTypeChange?.();\n      updateChatSearchContext(_searchType, query);\n    }\n\n    const current = {searchType: _searchType, query};\n\n    if(!isSender && !fromPeerId && !_reaction && isEmptyQuery) {\n      setCount();\n      setTotalCount();\n      onLoad();\n      return current;\n    }\n\n    createEffect(\n      on(\n        () => loader(),\n        ({rendered, values, count, loadMore}) => {\n          setCount(rendered.length);\n          setTotalCount(count);\n          setLoadMore(() => loadMore);\n          if(isSender) setSendersPeerIds(values as any);\n          else setMessages(values as any);\n          onLoad((rendered as HTMLElement[])[0]);\n        },\n        {defer: true}\n      )\n    );\n\n    inputSearch.toggleLoading(true);\n    untrack(() => loader().loadMore());\n    return current;\n  });\n\n  // * handle target change to jump to message\n  createEffect(\n    on(\n      target,\n      (target) => {\n        const idx = whichChild(target);\n        if(idx === -1) {\n          return;\n        }\n\n        if(choosingSender()) {\n          const peerId = sendersPeerIds()[idx];\n          batch(() => {\n            setFilterPeerId(peerId);\n            inputSearch.onChange(inputSearch.value = '');\n          });\n          return;\n        }\n\n        const previousActive = target.parentElement.querySelector('.active');\n        if(previousActive) {\n          previousActive.classList.remove('active');\n        }\n\n        target.classList.add('active');\n\n        setShowingSmallResults(false);\n\n        const message = messages()[idx];\n        deferSideEffect(() => {\n          appImManager.chat.setMessageId({\n            lastMsgId: message.mid,\n            lastMsgPeerId: message.peerId\n          });\n        });\n      },\n      {defer: true}\n    )\n  );\n\n  const tagToReactionCount = (tag: SavedReactionTag): ReactionCount => {\n    return {\n      _: 'reactionCount',\n      count: tag.count,\n      reaction: tag.reaction\n    };\n  };\n\n  const tagsToMessageReactions = (tags: SavedReactionTag[]): MessageReactions => {\n    return {\n      _: 'messageReactions',\n      pFlags: {reactions_as_tags: true},\n      results: tags.map(tagToReactionCount)\n    };\n  };\n\n  const onSavedTags = ({savedPeerId, tags}: BroadcastEvents['saved_tags']) => {\n    if(savedPeerId !== props.threadId) {\n      return;\n    }\n\n    setSavedReactionTags(tags);\n  };\n  subscribeOn(rootScope)('saved_tags', onSavedTags);\n\n  // * render saved reaction tags\n  createEffect<HTMLElement>((previousLock) => {\n    const tags = savedReactionTags();\n    const element = reactionsElement();\n    if(!tags || !element) {\n      return previousLock;\n    }\n\n    const reactionsContext: ReactionsContext = {\n      ...element.getContext(),\n      reactions: tagsToMessageReactions(tags)\n    };\n\n    // * set active\n    const _reaction = reaction();\n    let chosenReactionCount: ReactionCount;\n    if(_reaction) {\n      const reactionCount = reactionsContext.reactions.results.find((reactionCount) => reactionsEqual(reactionCount.reaction, _reaction));\n      if(reactionCount) {\n        chosenReactionCount = reactionCount;\n        reactionCount.chosen_order = 0;\n      }\n    }\n\n    previousLock?.remove();\n    element.update(reactionsContext);\n\n    if(chosenReactionCount) {\n      const reactionElement = element.getSorted().find((element) => reactionsEqual(element.reactionCount.reaction, _reaction));\n      fastSmoothScroll({\n        container: reactionsScrollableDiv,\n        element: reactionElement,\n        position: 'center',\n        axis: 'x'\n      });\n    }\n\n    const premium = isPremium();\n    element.classList.toggle('is-locked', !premium);\n    if(!premium) {\n      const icon: Icon = 'premium_lock';\n      const reaction = new ReactionElement();\n      reaction.init(ReactionLayoutType.Tag, createMiddleware().get());\n      reaction.reactionCount = {\n        _: 'reactionCount',\n        count: 1,\n        reaction: icon as any\n      };\n      reaction.setCanRenderAvatars(false);\n      reaction.renderCounter(undefined, i18n('Unlock'));\n      reaction.classList.add('reaction-tag-lock');\n\n      const allReactionsSticker = document.createElement('div');\n      allReactionsSticker.classList.add('reaction-sticker', 'reaction-sticker-icon');\n      allReactionsSticker.append(Icon(icon));\n      reaction.lastElementChild.before(allReactionsSticker);\n\n      element.prepend(reaction);\n      return reaction;\n    }\n  });\n\n  // * load saved reaction tags\n  createEffect(() => {\n    if(props.peerId !== rootScope.myId) {\n      setReactionsElement();\n      setSavedReactionTags();\n      return;\n    }\n\n    const realMiddleware = createMiddleware().get();\n    const middlewareHelper = getMiddleware();\n    onCleanup(() => {\n      setTimeout(() => {\n        middlewareHelper.destroy();\n      }, 400);\n    });\n    const reactionsElement = new ReactionsElement();\n    reactionsElement.init({\n      context: {peerId: props.peerId, mid: 0, reactions: tagsToMessageReactions([])},\n      type: ReactionLayoutType.Block,\n      middleware: middlewareHelper.get(),\n      forceCounter: true\n    });\n    reactionsElement.classList.remove('has-no-reactions');\n    reactionsElement.classList.add('topbar-search-left-reactions');\n\n    // * reactions listener\n    const detach = attachClickEvent(reactionsElement, (e) => {\n      const reactionElement = findUpClassName(e.target, 'reaction-tag') as ReactionElement;\n      if(!reactionElement) {\n        return;\n      }\n\n      if(!isPremium()) {\n        PopupPremium.show({feature: 'saved_tags'});\n        return;\n      }\n\n      const {reactionCount} = reactionElement;\n      const {reaction} = reactionCount;\n      setReaction((prev) => {\n        if(reactionsEqual(prev, reaction)) {\n          return;\n        }\n\n        return reaction;\n      });\n\n      placeCaretAtEnd(inputSearch.input);\n    }, {cancelMouseDown: true});\n    onCleanup(detach);\n\n    const get = () => {\n      rootScope.managers.appReactionsManager.getSavedReactionTags(props.threadId).then((tags) => {\n        // await pause(1000);\n        if(!realMiddleware()) {\n          return;\n        }\n\n        setReactionsElement(reactionsElement);\n        setSavedReactionTags(tags);\n      });\n    };\n\n    get();\n    rootScope.addEventListener('saved_tags_clear', get);\n    onCleanup(() => {\n      rootScope.removeEventListener('saved_tags_clear', get);\n    });\n  });\n\n  // * handle reaction changing\n  let first = true;\n  createEffect(on(\n    reaction,\n    (reaction) => {\n      if(first) {\n        first = false;\n\n        if(!reaction) {\n          return;\n        }\n      }\n\n      deferSideEffect(() => {\n        appImManager.chat.setMessageId({\n          savedReaction: reaction ? [reaction as Reaction.reactionCustomEmoji | Reaction.reactionEmoji] : undefined\n        });\n      });\n    }\n  ));\n\n  // * reset reaction on close\n  onCleanup(() => {\n    if(!reaction()) {\n      return;\n    }\n\n    deferSideEffect(() => {\n      appImManager.chat.setMessageId({\n        lastMsgId: undefined,\n        lastMsgPeerId: undefined,\n        mediaTimestamp: undefined,\n        savedReaction: undefined\n      });\n    });\n  });\n\n  // * reset search on close\n  onCleanup(() => {\n    if(appImManager.chat.type !== ChatType.Search) {\n      return;\n    }\n\n    updateChatSearchContext(undefined, undefined);\n  });\n\n  // * mobile search\n  createEffect(() => {\n    inputSearch.setArrowBack(isSmallScreen());\n    if(!isSmallScreen()) {\n      return;\n    }\n\n    const index = () => whichChild(target());\n\n    const footerElement = SearchFooter({\n      index,\n      count: totalCount,\n      pickUserBtn,\n      pickDateBtn,\n      resultsShown: shouldShowResults,\n      onToggle: () => {\n        setShowingSmallResults((prev) => !prev);\n      },\n      choosingSender\n    }) as HTMLElement;\n\n    const resultsElement = SearchMobileResults({\n      scrollable\n    }) as HTMLElement;\n\n    const topElement = SearchMobileTop({\n      reactionsScrollable,\n      searchTypesScrollable,\n      hasReactions: () => !!calculateReactionsHeight(),\n      hasSearchTypes: () => !!calculateSearchTypesHeight()\n    }) as HTMLElement;\n\n    SearchMobileButtons({\n      index,\n      count: totalCount,\n      chat: props.chat,\n      onArrowButtonClick\n    });\n\n    const onShowingSmallResultsChange = (value = showingSmallResults()) => {\n      props.chat.bubbles.container.classList.toggle('search-results-active', value);\n      props.chat.bubbles.updateGoDownVisibility();\n      resultsElement.classList.toggle('active', value);\n    };\n\n    const onTopActive = (value?: boolean) => {\n      value ??= !!(calculateReactionsHeight() || calculateSearchTypesHeight());\n      props.chat.topbar.container.classList.toggle('search-top-active', value);\n      resultsElement.classList.toggle('search-top-active', value);\n      if(value) container.after(topElement);\n      else topElement.remove();\n    };\n\n    createEffect(() => onShowingSmallResultsChange());\n    createEffect(() => onTopActive());\n\n    createEffect(() => {\n      if(choosingSender()) {\n        setShowingSmallResults(true);\n      } else if(!filteringSender()) {\n        setShowingSmallResults(false);\n      }\n    });\n\n    onCleanup(() => {\n      footerElement.remove();\n      setShowingSmallResults(false);\n      onShowingSmallResultsChange();\n      onTopActive(false);\n\n      setTimeout(() => {\n        resultsElement.remove();\n      }, 400);\n    });\n\n    props.chat.input.chatInput.before(resultsElement, footerElement);\n  });\n\n  const calculateResultsHeight = createMemo(() => {\n    if(!shouldShowResults()) {\n      return 0;\n    }\n\n    const length = count();\n    if(length === undefined && !isHashtag()) {\n      return 0;\n    }\n\n    const paddingVertical = 8 * 2;\n    let height: number;\n    if(!length) {\n      height = MIN_HEIGHT;\n    } else if(list().type === 'senders') {\n      height = 1 + paddingVertical + length * 48;\n    } else {\n      height = 1 + paddingVertical + length * 56;\n    }\n\n    return Math.min(MAX_HEIGHT, height);\n  });\n\n  const calculateReactionsHeight = createMemo(() => {\n    if(!isActive()) {\n      return 0;\n    }\n\n    return shouldShowReactions() ? 61 : 0;\n  });\n\n  const calculateSearchTypesHeight = createMemo(() => {\n    if(!isActive()) {\n      return 0;\n    }\n\n    return shouldShowSearchTypes() ? 61 : 0;\n  });\n\n  const pickUserBtn = props.canFilterSender && (\n    <ButtonIconTsx\n      class={classNames(!isSmallScreen() && 'topbar-search-right-filter-button')}\n      icon=\"newprivate\"\n      ref={(element) => {\n        const detach = attachClickEvent(element, (e) => {\n          cancelEvent(e);\n          inputSearch.onChange(inputSearch.value = '');\n          setFilteringSender(true);\n          placeCaretAtEnd(inputSearch.input, true);\n        }, {cancelMouseDown: true});\n        onCleanup(detach);\n      }}\n    />\n  );\n\n  const pickDateBtn = props.onDatePick && (\n    <ButtonIconTsx\n      icon=\"calendar\"\n      onClick={() => {\n        showDatePickerPopup({\n          initDate: new Date(),\n          onPick: props.onDatePick\n        });\n      }}\n    />\n  );\n\n  let scrollableDiv: HTMLDivElement;\n  const scrollable = (\n    <Scrollable\n      ref={scrollableDiv}\n      class={!isSmallScreen() ? 'topbar-search-left-results topbar-search-left-collapsable' : undefined}\n      style={!isSmallScreen() && calculateResultsHeight() ? {height: calculateResultsHeight() + 'px'} : undefined}\n      onScrolledBottom={() => {\n        loadMore()?.();\n      }}\n    >\n      {!isSmallScreen() && <div class=\"topbar-search-left-delimiter\"></div>}\n      <Animated type=\"cross-fade\">\n        {list()?.element}\n      </Animated>\n    </Scrollable>\n  );\n\n  let reactionsScrollableDiv: HTMLDivElement;\n  const reactionsScrollable = (\n    <Scrollable axis=\"x\" ref={reactionsScrollableDiv} class=\"topbar-search-left-reactions-scrollable\">\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n      {reactionsElement()}\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n    </Scrollable>\n  );\n\n  let searchTypesScrollableDiv: HTMLDivElement;\n  const searchTypesScrollable = (\n    <Scrollable axis=\"x\" ref={searchTypesScrollableDiv} class=\"topbar-search-left-reactions-scrollable\">\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n      <div class=\"topbar-search-left-search-types\">\n        {SEARCH_TYPES.map((type) => (<SearchTypeEntity type={type} />))}\n      </div>\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n    </Scrollable>\n  );\n\n  let container: HTMLDivElement;\n  return (\n    <div ref={container} class=\"topbar-search-container\">\n      <div\n        class={classNames('topbar-search-left-container', isActive() && 'is-focused')}\n        // style={calculateHeight() ? {height: calculateHeight() + 'px'} : undefined}\n      >\n        <div class=\"topbar-search-left-background\">\n          {/* <div class=\"topbar-search-left-background-shadow\"></div> */}\n        </div>\n        {inputSearch.container}\n        {/* shouldShowReactions() &&  */!isSmallScreen() && (\n          <div\n            class=\"topbar-search-left-reactions-container topbar-search-left-collapsable\"\n            style={calculateReactionsHeight() ? {height: calculateReactionsHeight() + 'px'} : undefined}\n          >\n            <div class=\"topbar-search-left-delimiter\"></div>\n            {reactionsScrollable}\n          </div>\n        )}\n        {/* shouldShowReactions() &&  */!isSmallScreen() && (\n          <div\n            class=\"topbar-search-left-reactions-container topbar-search-left-collapsable\"\n            style={calculateSearchTypesHeight() ? {height: calculateSearchTypesHeight() + 'px'} : undefined}\n          >\n            <div class=\"topbar-search-left-delimiter\"></div>\n            {searchTypesScrollable}\n          </div>\n        )}\n        {!isSmallScreen() && scrollable}\n      </div>\n      {!isSmallScreen() && (\n        <div class=\"topbar-search-right-container\">\n          {pickUserBtn && (\n            <div class={classNames('topbar-search-right-filter', (filteringSender() || isHashtag()) && 'is-hidden')}>\n              {pickUserBtn}\n            </div>\n          )}\n          {pickDateBtn && (\n            <div class={classNames('topbar-search-right-filter', isHashtag() && 'is-hidden')}>\n              {pickDateBtn}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n","import {i18n} from '@lib/langPack';\n\nimport showTooltip from '@components/tooltip';\nimport Button from '@components/buttonTsx';\n\nimport type Chat from '@components/chat/chat';\n\nimport styles from '@components/chat/priceChangedInterceptor/priceChangedTooltip.module.scss';\n\n\ntype ShowPriceChangedTooltipArgs = {\n  chat: Chat;\n  starsAmount: number;\n  onResend: () => void;\n};\n\nexport default function showPriceChangedTooltip({chat, starsAmount, onResend}: ShowPriceChangedTooltipArgs) {\n  return showTooltip({\n    element: chat.bubbles.container,\n    container: chat.bubbles.container,\n    mountOn: chat.bubbles.container,\n    relative: true,\n    vertical: 'top',\n    textElement: i18n('PaidMessages.PriceChanged', [i18n('Stars', [starsAmount])]),\n    rightElement: (\n      <Button\n        class={`btn ${styles.Button}`}\n        onClick={onResend}\n      >\n        {i18n('Resend')}\n      </Button>\n    ),\n    class: styles.Tooltip,\n    icon: 'sendingerror'\n  });\n}\n","import accumulate from '@helpers/array/accumulate';\nimport type ListenerSetter from '@helpers/listenerSetter';\nimport memoizeAsyncWithTTL from '@helpers/memoizeAsyncWithTTL';\nimport safeAssign from '@helpers/object/safeAssign';\nimport type {InputPeer} from '@layer';\nimport type {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport {setReservedStars} from '@stores/stars';\n\nimport type Chat from '@components/chat/chat';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\n\nimport showPriceChangedTooltip from '@components/chat/priceChangedInterceptor/priceChangedTooltip';\n\n\ntype PendingRequest = {\n  id: number;\n  messageCount: number;\n};\n\ntype ConstructorArgs = {\n  managers: AppManagers;\n  chat: Chat;\n  listenerSetter: ListenerSetter;\n};\n\ntype OpenedTooltip = {\n  close: () => void;\n  withStarsAmount: number;\n};\n\ntype OpenTooltipArgs = {\n  starsAmount: number;\n  messageCount: number;\n  requestId: number;\n};\n\ntype ConfirmResendArgs = {\n  pendingRequests: PendingRequest[];\n};\n\nclass PriceChangedInterceptor {\n  private chat: Chat;\n  private listenerSetter: ListenerSetter;\n  private managers: AppManagers;\n\n  private pendingRequests: PendingRequest[] = [];\n\n  private openedTooltip?: OpenedTooltip;\n\n  private getStarsAmountForUser: AppManagers['appUsersManager']['getStarsAmount'];\n\n  constructor(args: ConstructorArgs) {\n    safeAssign(this, args);\n\n    this.getStarsAmountForUser = memoizeAsyncWithTTL(\n      (userId: UserId) => this.managers.appUsersManager.getStarsAmount(userId, true),\n      (userId) => userId,\n      1_000\n    );\n  }\n\n  init() {\n    this.listenerSetter.add(rootScope)('insufficent_stars_for_message', async({requestId, messageCount, invokeApiArgs, reservedStars}) => {\n      reservedStars && setReservedStars(prev => Math.max(0, prev - reservedStars));\n\n      const apiCallParams = invokeApiArgs[1];\n\n      const peer = 'peer' in apiCallParams ? apiCallParams.peer : 'to_peer' in apiCallParams ? apiCallParams.to_peer : undefined;\n      if(!peer || !('allow_paid_stars' in apiCallParams)) return;\n\n      const peerId = await this.managers.appPeersManager.getPeerId(peer as InputPeer);\n      if(peerId !== this.chat.peerId) return;\n\n      const starsAmount = await this.getAndUpdateStarsAmountIfNecessary(peerId);\n\n      this.chat.updateStarsAmount(starsAmount);\n\n      this.handleNewRepayRequest({\n        starsAmount,\n        requestId,\n        messageCount\n      });\n    });\n\n    this.listenerSetter.add(rootScope)('fulfill_repaid_message', ({requestId}) => {\n      this.pendingRequests = this.pendingRequests.filter(r => r.id !== requestId);\n      if(!this.pendingRequests.length) this.closeTooltip();\n    });\n  }\n\n  private async getAndUpdateStarsAmountIfNecessary(peerId: PeerId) {\n    if(!peerId.isUser()) return this.managers.appPeersManager.getStarsAmount(peerId);\n\n    const starsAmount = await this.getStarsAmountForUser(peerId.toUserId());\n\n    await this.managers.appUsersManager.updateCachedUserFullStarsAmount(peerId.toUserId(), starsAmount);\n\n    return starsAmount;\n  }\n\n  private handleNewRepayRequest({starsAmount, messageCount, requestId}: OpenTooltipArgs) {\n    if(this.openedTooltip && this.openedTooltip.withStarsAmount !== starsAmount) {\n      this.closeTooltip();\n    }\n\n    if(!this.openedTooltip) this.openedTooltip = {\n      close: this.openTooltip(starsAmount),\n      withStarsAmount: starsAmount\n    }\n\n    this.pendingRequests.push({\n      id: requestId,\n      messageCount\n    });\n  }\n\n  private openTooltip(starsAmount: number) {\n    const onResend = () => {\n      this.confirmResend({\n        pendingRequests: [...this.pendingRequests]\n      });\n    };\n\n    const {close} = showPriceChangedTooltip({\n      starsAmount,\n      chat: this.chat,\n      onResend\n    });\n\n    return close;\n  }\n\n  private closeTooltip() {\n    this.openedTooltip?.close();\n    this.openedTooltip = undefined;\n  }\n\n  private async confirmResend({pendingRequests}: ConfirmResendArgs) {\n    const messageCount = accumulate(pendingRequests.map(r => r.messageCount), 0);\n\n    const preparedPaymentResult = await this.chat.input.paidMessageInterceptor.prepareStarsForPayment(messageCount);\n\n    if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n    await Promise.all(pendingRequests.map(({id}) => this.managers.appMessagesManager.confirmRepayRequest(id, preparedPaymentResult)));\n  }\n\n  cleanup() {\n    this.pendingRequests = [];\n    this.closeTooltip();\n  }\n}\n\nexport default PriceChangedInterceptor;\n","import type {StateSettings} from '@config/state';\nimport type {Chat} from '@layer';\nimport type {useAppSettings} from '@stores/appSettings';\nimport type {usePeer} from '@stores/peers';\n\nexport type ChatAutoDownloadSettings = {\n  photo: number,\n  video: number,\n  file: number\n};\n\nexport default function useAutoDownloadSettings(\n  peer: ReturnType<typeof usePeer<PeerId>>,\n  appSettings: ReturnType<typeof useAppSettings>[0]\n): ChatAutoDownloadSettings {\n  let type: keyof StateSettings['autoDownload'];\n\n  let photoSizeMax = 0, videoSizeMax = 0, fileSizeMax = 0;\n  if(!appSettings.autoDownloadNew.pFlags.disabled && peer) {\n    if(peer._ === 'user') {\n      if(peer.pFlags.contact) {\n        type = 'contacts';\n      } else {\n        type = 'private';\n      }\n    } else if((peer as Chat.channel).pFlags.broadcast) {\n      type = 'channels';\n    } else {\n      type = 'groups';\n    }\n\n    if(appSettings.autoDownload.photo[type]) photoSizeMax = appSettings.autoDownloadNew.photo_size_max;\n    if(appSettings.autoDownload.video[type]) videoSizeMax = appSettings.autoDownloadNew.video_size_max;\n    if(appSettings.autoDownload.file[type]) fileSizeMax = appSettings.autoDownloadNew.file_size_max;\n  }\n\n  return {\n    photo: photoSizeMax,\n    video: videoSizeMax,\n    file: fileSizeMax\n  };\n}\n","import type {AdminLog, ChatRights} from '@appManagers/appChatsManager';\nimport type {RequestWebViewOptions} from '@appManagers/appAttachMenuBotsManager';\nimport type {HistoryStorageKey, MessageSendingParams, MessagesStorageKey, MyMessage, RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {AppImManager, APP_TABS, ChatSetPeerOptions} from '@lib/appImManager';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {logger, LogTypes} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport {useIsCrmReadOnly} from '@stores/crmRole';\nimport appSidebarRight from '@components/sidebarRight';\nimport ChatBubbles, {FullMid, splitFullMid} from '@components/chat/bubbles';\nimport ChatContextMenu from '@components/chat/contextMenu';\nimport ChatInput from '@components/chat/input';\nimport ChatSelection from '@components/chat/selection';\nimport ChatTopbar from '@components/chat/topbar';\nimport {HIDDEN_PEER_ID, NULL_PEER_ID, REPLIES_HIDDEN_CHANNEL_ID, REPLIES_PEER_ID, SEND_PAID_WITH_STARS_DELAY, SERVICE_PEER_ID, VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport {AppPrivateSearchTab} from '@components/solidJsTabs/tabs';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport ChatSearch from '@components/chat/search';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ChatBackgroundGradientRenderer from '@components/chat/gradientRenderer';\nimport {ChatBackgroundTransition} from '@components/chat/bubbles/chatBackground';\nimport {AppManagers} from '@lib/managers';\nimport SlicedArray from '@helpers/slicedArray';\nimport themeController from '@helpers/themeController';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport noop from '@helpers/noop';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {Message, WallPaper, Chat as MTChat, Reaction, AvailableReaction, ChatFull, MessageEntity, PaymentsPaymentForm, InputPeer, ChatTheme, UserFull, User, StoriesStealthMode} from '@layer';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport deferredPromise, {CancellablePromise, bindPromiseToDeferred} from '@helpers/cancellablePromise';\nimport {isDialog} from '@appManagers/utils/dialogs/isDialog';\nimport getDialogKey from '@appManagers/utils/dialogs/getDialogKey';\nimport getHistoryStorageKey, {getHistoryStorageType} from '@appManagers/utils/messages/getHistoryStorageKey';\nimport isForwardOfForward from '@appManagers/utils/messages/isForwardOfForward';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {SendReactionOptions} from '@appManagers/appReactionsManager';\nimport {MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport {Accessor, createEffect, createMemo, createRoot, createSignal, on, onCleanup, Signal, untrack} from 'solid-js';\nimport TopbarSearch from '@components/chat/topbarSearch';\nimport createUnifiedSignal from '@helpers/solid/createUnifiedSignal';\nimport liteMode from '@helpers/liteMode';\nimport {useFullPeer} from '@stores/fullPeers';\nimport {useAppConfig, useAppState} from '@stores/appState';\nimport {unwrap} from 'solid-js/store';\nimport callbackify from '@helpers/callbackify';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\nimport useStars, {setReservedStars} from '@stores/stars';\nimport PopupElement from '@components/popups';\nimport PopupStars from '@components/popups/stars';\nimport {getPendingPaidReactionKey, PENDING_PAID_REACTION_SENT_ABORT_REASON, PENDING_PAID_REACTIONS} from '@components/chat/reactions';\nimport showUndoablePaidTooltip, {paidReactionLangKeys} from '@components/chat/undoablePaidTooltip';\nimport namedPromises from '@helpers/namedPromises';\nimport {getCurrentNewMediaPopup} from '@components/popups/newMedia';\nimport PriceChangedInterceptor from '@components/chat/priceChangedInterceptor';\nimport {isVerificationBot} from '@components/chat/utils';\nimport {isSensitive} from '@helpers/restrictions';\nimport {isTempId} from '@appManagers/utils/messages/isTempId';\nimport {usePeer} from '@stores/peers';\nimport {useAppSettings} from '@stores/appSettings';\nimport useHistoryStorage from '@stores/historyStorages';\nimport useAutoDownloadSettings, {ChatAutoDownloadSettings} from '@hooks/useAutoDownloadSettings';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport debounce from '@helpers/schedulers/debounce';\nimport appNavigationController from '@components/appNavigationController';\nimport {LEFT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarLeft';\nimport {AckedResult} from '@lib/superMessagePort';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport {ChatType} from '@components/chat/chatType';\nimport {animateSingle} from '@helpers/animation';\n\nexport type ChatSearchKeys = Pick<RequestHistoryOptions, 'query' | 'isCacheableSearch' | 'isPublicHashtag' | 'savedReaction' | 'fromPeerId' | 'inputFilter' | 'hashtagType'>;\nexport const CHAT_SEARCH_KEYS: (keyof ChatSearchKeys)[] = ['query', 'isCacheableSearch', 'isPublicHashtag', 'savedReaction', 'fromPeerId', 'inputFilter', 'hashtagType'];\n\nexport default class Chat extends EventListenerBase<{\n  setPeer: (mid: number, isTopMessage: boolean) => void\n}> {\n  public container: HTMLElement;\n  public bubblesViewport: HTMLElement;\n\n  public topbar: ChatTopbar;\n  public bubbles: ChatBubbles;\n  public input: ChatInput;\n  public selection: ChatSelection;\n  public contextMenu: ChatContextMenu;\n  public search: ChatSearch;\n\n  private priceChangedInterceptor: PriceChangedInterceptor;\n\n  public wasAlreadyUsed: boolean;\n  // public initPeerId = 0;\n\n  // * will be also used for RequestHistoryOptions\n  public peerId: PeerId;\n  public threadId: number;\n  public monoforumThreadId: number;\n  public savedReaction: (Reaction.reactionCustomEmoji | Reaction.reactionEmoji)[];\n  public isPublicHashtag: boolean;\n  public isCacheableSearch: boolean;\n  public query: string;\n  public inputFilter: RequestHistoryOptions['inputFilter'];\n  public hashtagType: 'this' | 'my' | 'public';\n  public peerIdSignal: Signal<PeerId>;\n  public chatPaddingTop: Signal<number>;\n  public chatPaddingBottom: Signal<number>;\n\n  public setPeerPromise: Promise<void>;\n  public peerChanged: boolean;\n\n  public log: ReturnType<typeof logger>;\n\n  public type: ChatType;\n  public messagesStorageKey: MessagesStorageKey;\n  public disposeHistoryStorage: () => void;\n  public isStandalone: boolean;\n\n  public noForwards: boolean;\n\n  /**\n   * Preview mode (Shift+Click on a dialog). The chat renders messages and background\n   * but performs no side effects — no readHistory / readMessages / incrementMessageViews,\n   * and no global background swap (the preview popup paints its own).\n   */\n  public isPreview: boolean;\n\n  /**\n   * Set by the preview popup before `setPeer` so the topbar's close button (rendered with a\n   * `close` icon instead of `back` in preview mode) tears down the popup instead of running\n   * `chat.pop()` against `appImManager.chat`.\n   */\n  public onPreviewClose?: () => void;\n\n  public inited: boolean;\n\n  public isRestricted: boolean;\n  public autoDownload: ChatAutoDownloadSettings;\n\n  public sharedMediaTab: AppSharedMediaTab;\n  public sharedMediaTabs: AppSharedMediaTab[];\n\n  public isBot: boolean;\n  public isChannel: boolean;\n  public isBroadcast: boolean;\n  public isLikeGroup: boolean;\n  public isAnyGroup: boolean;\n  public isMegagroup: boolean;\n  public isForum: boolean;\n  public isAllMessagesForum: boolean;\n  public isAnonymousSending: boolean;\n  public isUserBlocked: boolean;\n  public isPremiumRequired: boolean;\n  public isMonoforum: boolean;\n  public isBotforum: boolean;\n  public canManageDirectMessages: boolean;\n  public canManageBotforumTopics: boolean;\n  public isTemporaryThread: boolean;\n  public noInput: boolean;\n\n  public starsAmount: number | undefined;\n  public stealthMode: StoriesStealthMode | undefined;\n\n  public animationGroup: AnimationItemGroup;\n\n  public destroyPromise: CancellablePromise<void>;\n\n  public middlewareHelper: MiddlewareHelper;\n  public destroyMiddlewareHelper: MiddlewareHelper;\n\n  public searchSignal: ReturnType<typeof createUnifiedSignal<Parameters<Chat['initSearch']>[0]>>;\n\n  public currentTheme: Parameters<typeof themeController['getThemeSettings']>[0];\n  public currentWallPaper: WallPaper;\n  public preferredBackgroundTransition?: ChatBackgroundTransition;\n\n  /**\n   * Stashed by `_handleBackgrounds` on the peer-change publish: a bundle of the staging-slot\n   * reveal, container `--message-highlighting-color` apply and `applyContainerTheme` (when\n   * applicable). Invoked by `revealPreparedBackground` from `bubbles.setPeer` in the same sync\n   * block as `scrollable.replaceChildren`, so wallpaper flip, theme vars, and bubble mount land\n   * in one paint frame instead of two.\n   *\n   * `undefined` outside a peer change. Same-bg short-circuits store a no-op (still bundled with\n   * theme/hsla apply), so callers can always invoke unconditionally.\n   */\n  private pendingBackgroundReveal: (() => void) | undefined;\n  /**\n   * True when the currently-stored `pendingBackgroundReveal` carries an actual staging-slot\n   * flip (`reveal !== noop`). Same-bg short-circuits in subsequent publishes during the same\n   * peer-change scope must not downgrade a real flip to a noop one — without this flag,\n   * comparing the bundled callbacks against `noop` directly is impossible.\n   */\n  private pendingBackgroundRevealIsReal: boolean;\n  /**\n   * Set true once `revealPreparedBackground` runs. Lets `deferReveal` callbacks that arrive\n   * after the bubbles mount (not-cached wallpaper path) fire their bundled reveal inline\n   * instead of waiting forever in `pendingBackgroundReveal`.\n   */\n  private bubblesRevealCalled: boolean;\n\n  /**\n   * True while this chat is off-screen on mobile (the chat list or profile tab is shown instead\n   * of the chat). A theme/wallpaper that finishes loading in this window must NOT drive the\n   * global background — otherwise opening a chat, then backing out before its theme loads, still\n   * flips the background once the slow load lands. Reset on peer change, re-asserted when the\n   * chat returns on screen (see `setBackgroundHidden`). Driven by the `tab_changing` listener.\n   */\n  private backgroundHidden = false;\n\n  public ignoreSearchCleaning: boolean;\n\n  public stars: Accessor<Long>;\n  public appState: ReturnType<typeof useAppState>[0];\n  public setAppState: ReturnType<typeof useAppState>[1];\n  public appSettings: ReturnType<typeof useAppSettings>[0];\n  public setAppSettings: ReturnType<typeof useAppSettings>[1];\n  public appConfig: ReturnType<typeof useAppConfig>;\n  public peer: ReturnType<typeof usePeer<PeerId>>;\n  public historyStorage: ReturnType<typeof useHistoryStorage>;\n  public historyStorageNoThreadId: ReturnType<typeof useHistoryStorage>;\n  public peerTranslation: ReturnType<typeof usePeerTranslation>;\n  public fullPeer: Accessor<ChatFull | UserFull>;\n\n  public staticMessages: MyMessage[] = [];\n\n  // public requestHistoryOptionsPart: RequestHistoryOptions;\n\n  constructor(\n    public appImManager: AppImManager,\n    public managers: AppManagers,\n    public isMainChat: boolean,\n    public excludeParts: Partial<{\n      elements: boolean,\n      sharedMedia: boolean\n    }> = {}\n  ) {\n    super();\n\n    this.log = logger('CHAT', LogTypes.Log | LogTypes.Warn | LogTypes.Debug | LogTypes.Error);\n    // this.log = logger('CHAT', LogTypes.Warn | LogTypes.Error);\n    this.log.warn('constructor');\n\n    this.type = ChatType.Chat;\n    this.animationGroup = `chat-${Math.round(Math.random() * 65535)}`;\n    this.middlewareHelper = getMiddleware();\n    this.destroyMiddlewareHelper = getMiddleware();\n\n    if(!this.excludeParts.elements) {\n      this.container = document.createElement('div');\n      this.container.classList.add('chat', 'tabs-tab');\n    }\n\n    this.peerIdSignal = createSignal(this.peerId = NULL_PEER_ID);\n    this.chatPaddingTop = createSignal(0);\n    this.chatPaddingBottom = createSignal(0);\n    this.recomputePaddings();\n\n    this.sharedMediaTabs = [];\n\n    createRoot((dispose) => {\n      this.destroyMiddlewareHelper.onDestroy(dispose);\n      this.stars = useStars();\n      [this.appState, this.setAppState] = useAppState();\n      [this.appSettings, this.setAppSettings] = useAppSettings();\n      this.appConfig = useAppConfig();\n      this.fullPeer = createMemo(() => useFullPeer(this.peerIdSignal[0]())());\n    });\n  }\n\n  public get gradientRenderer(): ChatBackgroundGradientRenderer | undefined {\n    return this.appImManager.appChatBackground.getActiveGradientRenderer();\n  }\n\n  private chatInputSurplusPx = 0;\n  private pinnedFloatingHeightPx = 0;\n  private preservePaddingScrollAbort?: () => void;\n\n  public updateChatInputHeight(surplus: number) {\n    if(this.chatInputSurplusPx === surplus) return;\n    this.preservePaddingScroll();\n    this.chatInputSurplusPx = surplus;\n    this.container.style.setProperty('--chat-input-height-surplus', surplus + 'px');\n    this.recomputePaddings();\n  }\n\n  public updatePinnedFloatingHeight(value: number) {\n    if(this.pinnedFloatingHeightPx === value) return;\n    const delta = value - this.pinnedFloatingHeightPx;\n    this.pinnedFloatingHeightPx = value;\n    const scrollable = this.bubbles?.scrollable;\n    const wasAtEnd = scrollable?.isScrolledToEnd;\n    this.recomputePaddings();\n    // Mobile-faithful (verified against iOS ListView + Android ChatActivity):\n    // leave a mid-scroll position anchored. recomputePaddings grows the\n    // in-scroller paddingTop, and the browser's own scroll anchoring keeps the\n    // visible content put as it grows — so the plate slides in OVER the content\n    // (which scrolls under it) rather than shoving it down. Both mobile clients\n    // do exactly this; neither shifts the history when a top panel appears.\n    // Only re-pin when the chat was glued to the bottom, so the newest message\n    // stays in view — otherwise the grown paddingTop drifts it off the end.\n    if(scrollable && wasAtEnd && delta > 0) {\n      scrollable.setScrollPositionSilently(scrollable.scrollPosition + delta);\n    }\n  }\n\n  private preservePaddingScroll() {\n    if(\n      !this.bubbles ||\n      !this.bubbles.scrollable.isScrolledToEnd/*  ||\n      true */\n    ) return;\n    this.preservePaddingScrollAbort?.();\n    let finished = false;\n    const timeout = setTimeout(() => {\n      finished = true;\n    }, 250);\n    this.preservePaddingScrollAbort = () => {\n      finished = true;\n      clearTimeout(timeout);\n      this.preservePaddingScrollAbort = undefined;\n    };\n    animateSingle(() => {\n      if(finished) {\n        return false;\n      }\n\n      this.bubbles.scrollable.setScrollPositionSilently(99999);\n      return true;\n    }, this.bubbles.scrollable.container);\n\n    // const scrollSaver = this.bubbles.createScrollSaver(false);\n    // scrollSaver.save();\n    // const promise = new Promise<void>((resolve) => setTimeout(resolve, 250));\n    // this.bubbles.animateSomethingWithScroll(promise, scrollSaver);\n  }\n\n  // Hands scroll control to an imminent new-message reveal (renderNewMessage →\n  // scrollToEnd). Otherwise the pin above slams to the absolute bottom every frame\n  // and swallows the reveal animation — most visibly when forwarding a tall message,\n  // where the input helper collapse that triggers the pin coincides with the new bubble.\n  public cancelPreservePaddingScroll() {\n    this.preservePaddingScrollAbort?.();\n  }\n\n  public recomputePaddings() {\n    // const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);\n    const rem = 16;\n    // Main chat reserves 4.5rem above + 4rem below for the floating topbar / pinned-plate\n    // buffer and the chat-input plate. The preview shows neither — only the basic 3rem\n    // topbar — so collapse to topbar-height + 0.5rem (page-chats-padding) on each side.\n    // Handhelds drop those buffers too: the page inset shrinks to 8px so each floating\n    // plate's inner edge sits at 56px (3rem + 0.5rem). Collapse both spacers to sit flush\n    // (= --chat-padding-top / --chat-padding-bottom) instead of the wider desktop gap. Kept\n    // in sync across mobile<->desktop transitions by the 'changeScreen' listener in init().\n    const collapse = this.isPreview || mediaSizes.isMobile;\n    const topBase = collapse ? 3.5 : 4.5;\n    const bottomBase = collapse ? 3.5 : 4;\n    const top = Math.round(topBase * rem + this.pinnedFloatingHeightPx);\n    const bottom = Math.round(bottomBase * rem + this.chatInputSurplusPx);\n    this.chatPaddingTop[1](top);\n    this.chatPaddingBottom[1](bottom);\n    if(this.bubbles?.paddingTop) this.bubbles.paddingTop.style.height = top + 'px';\n    if(this.bubbles?.paddingBottom) this.bubbles.paddingBottom.style.height = bottom + 'px';\n    this.bubbles?.updateStickyIntersectorRootMargin?.();\n  }\n\n  public applyContainerTheme() {\n    if(!this.container) return;\n    const newTheme = this.currentTheme ?? themeController.getTheme();\n    themeController.applyTheme(newTheme, this.container);\n  }\n\n  public publishBackground(\n    transition: ChatBackgroundTransition = 'auto',\n    onCachedStatus?: (cached: boolean) => void,\n    deferReveal?: (reveal: () => void) => void\n  ): Promise<void> {\n    if(this !== this.appImManager.chat || this.backgroundHidden) {\n      onCachedStatus?.(true);\n      deferReveal?.(noop);\n      return Promise.resolve();\n    }\n\n    const finalTransition = this.preferredBackgroundTransition ?? transition;\n    this.preferredBackgroundTransition = undefined;\n\n    // When `deferReveal` is provided, stash the hsla and apply it as part of the bundled\n    // reveal — otherwise `--message-highlighting-color` lands on the container ahead of the\n    // staging-slot flip, and bubbles read the new highlighting color while the old wallpaper\n    // is still on screen.\n    let pendingHsla: string | undefined;\n    const applyPendingHsla = () => {\n      if(pendingHsla === undefined || !this.container) return;\n      themeController.applyHighlightingColor({hsla: pendingHsla, element: this.container});\n    };\n\n    return this.appImManager.appChatBackground.setBackground({\n      theme: this.currentTheme,\n      wallPaper: this.currentWallPaper,\n      transition: finalTransition,\n      onCachedStatus,\n      // Scope the canvas-computed hsla to this chat's container so each chat's\n      // bubbles see *their* highlighting color. Without this, root would carry\n      // the most recently opened chat's value and leak into other chats whose\n      // containers still inherit from `:root`.\n      onHighlightColor: (hsla) => {\n        if(deferReveal) {\n          pendingHsla = hsla;\n          return;\n        }\n        if(this.container) {\n          themeController.applyHighlightingColor({hsla, element: this.container});\n        }\n      },\n      deferReveal: deferReveal ? (slotReveal) => {\n        // Bundle slot flip and hsla apply into one callback — caller invokes them together,\n        // sync with the bubbles mount.\n        deferReveal(() => {\n          slotReveal();\n          applyPendingHsla();\n        });\n      } : undefined\n    });\n  }\n\n  private setBackgroundHidden(hidden: boolean) {\n    if(this.backgroundHidden === hidden) {\n      return;\n    }\n\n    this.backgroundHidden = hidden;\n    // Coming back on screen: re-assert our background. A theme that finished loading while we\n    // were off-screen had its publish suppressed by `publishBackground`'s guard; surface it now.\n    // `setBackground` short-circuits when the background is already current, so this is cheap.\n    if(!hidden && this === this.appImManager.chat && this.peerId) {\n      this.publishBackground('auto');\n    }\n  }\n\n  private _handleBackgrounds() {\n    const log = this.log.bindPrefix('handleBackgrounds');\n    const deferred = deferredPromise<() => void>();\n    // Wipe any leftover reveal from a previous peer change that errored out before\n    // `bubbles.setPeer` reached `revealPreparedBackground`.\n    this.pendingBackgroundReveal = undefined;\n    this.pendingBackgroundRevealIsReal = false;\n    this.bubblesRevealCalled = false;\n\n    const publish = () => {\n      const applyTheme = () => this.applyContainerTheme();\n      // First publish in this peer-change scope owns the staging-slot reveal — it's the one\n      // racing the bubbles mount. Later re-publishes (night toggle, fullPeer details update)\n      // happen well after bubbles are settled, so they reveal inline as before.\n      const isFirstPublish = !deferred.isFulfilled;\n\n      // For not-cached wallpapers, `onCachedStatus(false)` resolves the deferred early with\n      // `applyTheme` so `finishPeerChange` doesn't block on a slow image download — in that\n      // case `applyTheme` runs via `callbacks.forEach` and must not also run in the bundled\n      // reveal (would double-apply the heavy theme computation).\n      let themeOwnedByCallbacks = false;\n\n      const deferRevealCb = isFirstPublish ? (reveal: () => void) => {\n        const isReal = reveal !== noop;\n        // Bundle slot flip + theme apply so wallpaper, theme vars and `--message-highlighting-color`\n        // (set inside `publishBackground`'s wrapped `onHighlightColor` → bundled into `reveal`)\n        // all land in one sync block alongside the bubbles mount.\n        const bundled = themeOwnedByCallbacks ? reveal : () => {\n          reveal();\n          applyTheme();\n        };\n\n        // Late stage: bubbles already mounted (e.g. not-cached wallpaper path where\n        // `onCachedStatus(false)` resolved the deferred and bubbles ran ahead). Fire the\n        // bundled reveal now — the SCSS fade transition still animates the slot in.\n        if(this.bubblesRevealCalled) {\n          bundled();\n          return;\n        }\n\n        // Don't let a same-bg short-circuit (which hands back the `noop` sentinel) downgrade\n        // a real pending reveal from an earlier publish in this peer-change scope.\n        if(!isReal && this.pendingBackgroundRevealIsReal) {\n          return;\n        }\n        this.pendingBackgroundReveal = bundled;\n        this.pendingBackgroundRevealIsReal = isReal;\n      } : undefined;\n\n      const promise = this.publishBackground('auto', (cached) => {\n        if(!cached && !deferred.isFulfilled) {\n          // Cached canvas not ready yet — let `finishPeerChange` proceed without the bundled\n          // reveal (it'll fire late via `bubblesRevealCalled`); apply theme inline so bubbles\n          // mount against the new vars even before the wallpaper fades in.\n          themeOwnedByCallbacks = true;\n          deferred.resolve(applyTheme);\n        }\n      }, deferRevealCb);\n\n      promise.then(() => {\n        if(!deferred.isFulfilled) {\n          // Cached path: wallpaper fully staged. `applyTheme` is bundled into the reveal —\n          // resolve with `noop` so `callbacks.forEach` doesn't apply it ahead of the slot flip.\n          deferred.resolve(noop);\n        } else {\n          // Subsequent publishes (night toggle, peer details change): canvas\n          // already settled, just apply theme inline now that it's painted.\n          applyTheme();\n        }\n      });\n    };\n\n    const getThemeByEmoticon = (emoticon: string) => {\n      if(!emoticon) {\n        return;\n      }\n\n      const {accountThemes} = appState;\n      return accountThemes.themes?.find((theme) => theme.emoticon === emoticon);\n    };\n\n    const update = () => {\n      const _fullPeer = fullPeer();\n      let wallPaper: WallPaper;\n      let theme: Chat['currentTheme'];\n\n      if(_fullPeer) {\n        wallPaper = unwrap((_fullPeer as ChatFull.channelFull).wallpaper);\n        const emoticon = (_fullPeer as ChatFull.channelFull).theme_emoticon ||\n          ((_fullPeer as UserFull.userFull).theme as ChatTheme.chatTheme)?.emoticon ||\n          (wallPaper && wallPaper.settings?.emoticon);\n\n        theme = unwrap(getThemeByEmoticon(emoticon));\n        if(emoticon && theme) {\n          wallPaper = undefined;\n        }\n      }\n\n      this.currentTheme = theme;\n      this.currentWallPaper = wallPaper;\n\n      log('updating', _fullPeer, theme, wallPaper);\n      publish();\n\n      createEffect(on(isNightTheme, update, {defer: true}));\n    };\n\n    const isNightTheme = useIsNightTheme();\n    const fullPeer = useFullPeer(this.peerId);\n    const [appState] = useAppState();\n    createEffect(() => {\n      update();\n    });\n\n    // Defensive: when the global theme toggles (day↔night, accent change),\n    // chatBackground's own listener fires first and replaces props (dropping\n    // our per-chat onHighlightColor). Re-apply the container theme and copy\n    // the freshly-computed highlighting color from :root (where the canvas\n    // already wrote it) onto our container so per-chat bubbles see the new\n    // value instead of the stale cached one.\n    const onThemeChanged = async() => {\n      this.applyContainerTheme();\n      await this.appImManager.appChatBackground.getReadyPromise();\n      if(!this.container) return;\n      const rootHsla = getComputedStyle(document.documentElement).getPropertyValue('--message-highlighting-color').trim();\n      if(rootHsla) {\n        themeController.applyHighlightingColor({hsla: rootHsla, element: this.container});\n      }\n    };\n    rootScope.addEventListener('theme_changed', onThemeChanged);\n    onCleanup(() => rootScope.removeEventListener('theme_changed', onThemeChanged));\n\n    return deferred;\n  }\n\n  /**\n   * Run the pending wallpaper flip + theme apply + `--message-highlighting-color` apply\n   * bundle, if any, synchronously. Called from `bubbles.setPeer` in the same sync block as\n   * `scrollable.replaceChildren` so all chat-visual state lands with the bubbles mount in one\n   * paint frame instead of bleeding the new highlighting/wallpaper onto the old bubbles first.\n   *\n   * Idempotent: clears the pending bundle after invocation. Setting `bubblesRevealCalled`\n   * also flips `_handleBackgrounds` into late-stage mode for any `deferReveal` callback that\n   * arrives afterwards (not-cached wallpaper path).\n   */\n  public revealPreparedBackground() {\n    const reveal = this.pendingBackgroundReveal;\n    this.pendingBackgroundReveal = undefined;\n    this.pendingBackgroundRevealIsReal = false;\n    this.bubblesRevealCalled = true;\n    reveal?.();\n  }\n\n  private handleBackgrounds() {\n    if(this.type === ChatType.Stories || this.isPreview) {\n      return Promise.resolve(noop);\n    }\n\n    return createRoot((dispose) => {\n      this.middlewareHelper.get().onClean(dispose);\n      return this._handleBackgrounds();\n    });\n  }\n\n  public setType(type: ChatType) {\n    this.type = type;\n  }\n\n  public init(/* peerId: PeerId */) {\n    // this.initPeerId = peerId;\n\n    this.topbar = new ChatTopbar(this, appSidebarRight, this.managers);\n    this.bubbles = new ChatBubbles(this, this.managers);\n    this.input = new ChatInput(this, this.appImManager, this.managers, 'chat-input-main');\n    this.contextMenu = new ChatContextMenu(this, this.managers);\n    this.selection = new ChatSelection(this, this.bubbles, this.input, this.managers);\n\n    this.priceChangedInterceptor = new PriceChangedInterceptor({\n      chat: this,\n      listenerSetter: this.bubbles.listenerSetter,\n      managers: this.managers\n    });\n\n    this.topbar.constructUtils();\n    this.topbar.constructPeerHelpers();\n\n    this.topbar.construct();\n    this.input.construct();\n\n    this.bubbles.constructPeerHelpers();\n    this.input.constructPeerHelpers();\n\n    this.priceChangedInterceptor.init();\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.bubbles.setReactionsHoverListeners();\n    }\n\n    this.bubbles.attachContainerListeners();\n\n    this.bubblesViewport = document.createElement('div');\n    this.bubblesViewport.classList.add('bubbles-viewport', 'disable-hover');\n\n    this.container.append(this.topbar.container, this.bubbles.container, this.bubblesViewport, this.input.chatInput);\n\n    this.bubbles.listenerSetter.add(rootScope)('dialog_migrate', ({migrateFrom, migrateTo}) => {\n      if(this.peerId === migrateFrom) {\n        this.setPeer({peerId: migrateTo});\n      }\n    });\n\n    // Spacer heights depend on the screen (desktop reserves a wider floating-plate buffer\n    // than handheld), so recompute them when crossing the mobile boundary. See recomputePaddings().\n    this.bubbles.listenerSetter.add(mediaSizes)('changeScreen', () => {\n      this.recomputePaddings();\n    });\n\n    if(!this.isPreview) {\n      // Preview popup owns its own lifecycle — these callbacks talk to the main appImManager\n      // and would close the *real* chat behind the popup if the previewed dialog got dropped.\n      this.bubbles.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n        if(dialog.peerId === this.peerId && (isDialog(dialog) || this.threadId === getDialogKey(dialog))) {\n          this.appImManager.setPeer({isDeleting: true});\n        }\n      });\n\n      this.bubbles.listenerSetter.add(rootScope)('monoforum_dialogs_drop', ({ids, parentPeerId}) => {\n        if(parentPeerId === this.peerId && ids.includes(this.monoforumThreadId)) {\n          this.appImManager.setPeer({isDeleting: true});\n        }\n      });\n    }\n\n    this.bubbles.listenerSetter.add(rootScope)('chat_update', async(chatId) => {\n      const {peerId} = this;\n      if(peerId.isAnyChat() && peerId.toChatId() === chatId) {\n        const {\n          starsAmount,\n          isAnonymousSending,\n          canManageDirectMessages\n        } = await namedPromises({\n          starsAmount: this.managers.appChatsManager.getStarsAmount(chatId),\n          isAnonymousSending: this.managers.appMessagesManager.isAnonymousSending(peerId),\n          canManageDirectMessages: this.managers.appPeersManager.canManageDirectMessages(peerId)\n        });\n\n        if(peerId === this.peerId) {\n          this.canManageDirectMessages = canManageDirectMessages;\n          this.isAnonymousSending = isAnonymousSending;\n          this.updateStarsAmount(starsAmount);\n        }\n      }\n    });\n\n    this.bubbles.listenerSetter.add(rootScope)('botforum_pending_topic_created', ({peerId, tempId, newId}) => {\n      if(peerId !== this.peerId || (this.threadId && this.threadId !== tempId)) return;\n\n      !newId && this.input.clearInput();\n\n      this.setPeer({\n        peerId,\n        threadId: newId || tempId,\n        fromTemporaryThread: !!newId\n      });\n    });\n\n\n    const freezeObservers = (freeze: boolean) => {\n      const cb = () => {\n        this.bubbles.observer?.toggleObservingNew(freeze);\n        animationIntersector.toggleIntersectionGroup(this.animationGroup, freeze);\n        if(freeze) {\n          animationIntersector.checkAnimations(freeze, this.animationGroup);\n        }\n      };\n\n      if(!freeze) {\n        setTimeout(() => {\n          cb();\n        }, 400);\n      } else {\n        cb();\n      }\n    };\n\n    this.bubbles.listenerSetter.add(this.appImManager)('chat_changing', ({to}) => {\n      freezeObservers(to !== this);\n    });\n\n    this.bubbles.listenerSetter.add(this.appImManager)('tab_changing', (tabId) => {\n      const offScreenOnMobile = tabId !== APP_TABS.CHAT && mediaSizes.activeScreen === ScreenSize.mobile;\n      freezeObservers(this.appImManager.chat !== this || offScreenOnMobile);\n      this.setBackgroundHidden(offScreenOnMobile);\n    });\n\n    const setInChatQueryDebounced = debounce((query: string) => {\n      this.bubbles.setInChatQuery(query);\n    }, 300, false, true);\n\n    const hasInChatQuery = () => this.type === ChatType.Logs;\n\n    this.searchSignal = createUnifiedSignal();\n    createRoot((dispose) => {\n      this.middlewareHelper.get().onDestroy(dispose);\n\n      const animateElements = async(topbarSearch: HTMLElement, visible: boolean) => {\n        const animate = liteMode.isAvailable('animations')/*  && !this.setPeerPromise */;\n        const keyframes: Keyframe[] = [{opacity: 0}, {opacity: 1}];\n        const options: KeyframeAnimationOptions = {fill: 'forwards', duration: animate ? 200 : 0, easing: 'ease-in-out'};\n        if(!visible) {\n          keyframes.reverse();\n        }\n\n        const elements = this.topbar.container.querySelectorAll<HTMLElement>('.content, .chat-utils');\n\n        const promises: Promise<any>[] = [];\n        const promise = topbarSearch.animate(keyframes, options).finished;\n        keyframes.reverse();\n        const otherPromises = Array.from(elements).map((element) => element.animate(keyframes, options).finished);\n        promises.push(promise, ...otherPromises);\n        return Promise.all(promises);\n      };\n\n      const [needSearch, setNeedSearch] = createSignal(false);\n      const [query, setQuery] = createSignal('', {equals: false});\n      const [filterPeerId, setFilterPeerId] = createSignal<PeerId>(undefined, {equals: false});\n      const [reaction, setReaction] = createSignal<Reaction>(undefined, {equals: false});\n      createEffect<HTMLElement>((topbarSearch) => {\n        if(!needSearch()) {\n          if(!topbarSearch) {\n            return;\n          }\n\n          animateElements(topbarSearch, false).then(() => {\n            topbarSearch.remove();\n          });\n          return;\n        }\n\n        topbarSearch = untrack(() => TopbarSearch({\n          chat: this,\n          chatType: this.type,\n          peerId: this.peerId,\n          // TODO: Check here for monoforumThreadId\n          threadId: this.threadId,\n          canFilterSender: this.type !== ChatType.Logs && this.isAnyGroup,\n          query,\n          filterPeerId,\n          reaction,\n          noList: hasInChatQuery(),\n          onValueChange: hasInChatQuery() ? setInChatQueryDebounced : undefined,\n          onClose: () => {\n            this.searchSignal(undefined);\n            this.bubbles.setInChatQuery('');\n          },\n          onDatePick: this.type === ChatType.Logs ? undefined : (timestamp) => {\n            this.bubbles.onDatePick(timestamp);\n          },\n          onActive: (active, showingReactions, isSmallScreen) => {\n            const className = 'is-search-active';\n            const isActive = !!(active && (showingReactions || isSmallScreen));\n            const wasActive = this.container.classList.contains(className);\n            if(wasActive === isActive) {\n              return;\n            }\n\n            const scrollSaver = this.bubbles.createScrollSaver();\n            scrollSaver.save();\n            this.container.classList.toggle(className, !isSmallScreen && isActive);\n            this.topbar.container.classList.toggle('hide-pinned', isSmallScreen);\n            scrollSaver.restore();\n          },\n          onSearchTypeChange: () => {\n            this.ignoreSearchCleaning = true;\n          }\n        })) as HTMLElement;\n        this.topbar.container.append(topbarSearch);\n        animateElements(topbarSearch, true);\n        return topbarSearch;\n      });\n\n      createEffect(() => {\n        const s = this.searchSignal();\n        setQuery(s?.query);\n        setFilterPeerId(s?.filterPeerId);\n        setReaction(s?.reaction);\n        setNeedSearch(!!s);\n      });\n    });\n  }\n\n  public beforeDestroy() {\n    this.destroyPromise = deferredPromise();\n    this.bubbles.cleanup();\n    this.searchSignal?.(undefined);\n  }\n\n  public destroy() {\n    // const perf = performance.now();\n\n    this.destroyPromise?.resolve();\n    this.destroySharedMediaTab();\n    this.topbar?.destroy();\n    this.bubbles?.destroy();\n    this.input?.destroy();\n    this.contextMenu?.destroy();\n    this.selection?.attachListeners(undefined, undefined);\n    this.destroyMiddlewareHelper.destroy();\n\n    this.topbar =\n      this.bubbles =\n      this.input =\n      this.contextMenu =\n      this.selection =\n      undefined;\n\n    this.container?.remove();\n\n    this.changeHistoryStorageKey(undefined, undefined);\n\n    // this.log.error('Chat destroy time:', performance.now() - perf);\n  }\n\n  public cleanup(helperToo = true) {\n    this.input?.cleanup(helperToo);\n    this.topbar?.cleanup();\n    this.selection?.cleanup();\n    this.priceChangedInterceptor?.cleanup();\n\n    if(this.ignoreSearchCleaning) this.ignoreSearchCleaning = undefined;\n    else this.searchSignal?.(undefined);\n  }\n\n  public get isForumTopic() {\n    return !!(this.isForum && this.threadId);\n  }\n\n  public get isSensitive() {\n    return isSensitive((this.peer as User.user).restriction_reason || []);\n  }\n\n  public async onChangePeer(options: ChatSetPeerOptions, m: ReturnType<typeof middlewarePromise>) {\n    // spot\n    const {peerId, threadId} = options;\n\n    if(!this.excludeParts.elements) {\n      const searchTab = appSidebarRight.getTab(AppPrivateSearchTab);\n      searchTab?.close();\n    }\n\n    const isForum = apiManagerProxy.isForum(peerId);\n    const isBotforum = apiManagerProxy.isBotforum(peerId);\n    const canManageBotforumTopics = apiManagerProxy.canManageBotforumTopics(peerId);\n\n    if(threadId && !isForum && !isBotforum) {\n      options.type = options.peerId === rootScope.myId ? ChatType.Saved : ChatType.Discussion;\n    }\n\n    if(options.query) {\n      options.type = ChatType.Search;\n    }\n\n    const type = options.type ?? ChatType.Chat;\n    this.setType(type);\n\n    const {\n      noForwards,\n      isRestricted,\n      isLikeGroup,\n      isRealGroup,\n      isMegagroup,\n      isBroadcast,\n      isChannel,\n      isBot,\n      isAnonymousSending,\n      isUserBlocked,\n      isPremiumRequired,\n      starsAmount,\n      chat,\n      canManageDirectMessages\n    } = await m(namedPromises({\n      noForwards: this.managers.appPeersManager.noForwards(peerId),\n      isRestricted: this.managers.appPeersManager.isPeerRestricted(peerId),\n      isLikeGroup: this._isLikeGroup(peerId),\n      isRealGroup: this.managers.appPeersManager.isAnyGroup(peerId),\n      isMegagroup: this.managers.appPeersManager.isMegagroup(peerId),\n      isBroadcast: this.managers.appPeersManager.isBroadcast(peerId),\n      isChannel: this.managers.appPeersManager.isChannel(peerId),\n      isBot: this.managers.appPeersManager.isBot(peerId),\n      isAnonymousSending: this.managers.appMessagesManager.isAnonymousSending(peerId),\n      isUserBlocked: peerId.isUser() && this.managers.appProfileManager.isCachedUserBlocked(peerId),\n      isPremiumRequired: this.isPremiumRequiredToContact(peerId),\n      starsAmount: this.managers.acknowledged.appPeersManager.getStarsAmount(peerId),\n      chat: peerId.isAnyChat() && this.peer as MTChat,\n      canManageDirectMessages: this.managers.appPeersManager.canManageDirectMessages(peerId)\n    }, this.log));\n\n    // ! WARNING: TEMPORARY, HAVE TO GET TOPIC\n    if(isForum && threadId) {\n      await m(this.managers.dialogsStorage.getForumTopicOrReload(peerId, threadId));\n    }\n\n    this.noForwards = noForwards;\n    this.isLikeGroup = isLikeGroup;\n    this.isAnyGroup = isRealGroup;\n    this.isMegagroup = isMegagroup;\n    this.isBroadcast = isBroadcast;\n    this.isChannel = isChannel;\n    this.isBot = isBot;\n    this.isForum = isForum;\n    this.isAllMessagesForum = isForum && !threadId;\n    this.isAnonymousSending = isAnonymousSending;\n    this.isUserBlocked = isUserBlocked;\n    this.isPremiumRequired = isPremiumRequired;\n    this.isMonoforum = !!(chat?._ === 'channel' && chat?.pFlags?.monoforum);\n    this.isBotforum = isBotforum;\n    this.canManageDirectMessages = canManageDirectMessages;\n    this.canManageBotforumTopics = canManageBotforumTopics;\n\n    if(starsAmount.cached) {\n      this.starsAmount = await starsAmount.result;\n    } else {\n      const middleware = this.middlewareHelper.get();\n      starsAmount.result.then((starsAmount) => {\n        if(!middleware()) {\n          return;\n        }\n        this.updateStarsAmount(starsAmount);\n      });\n    }\n\n    this.isRestricted = isRestricted;\n\n    if(this.selection) {\n      this.selection.isScheduled = type === ChatType.Scheduled;\n    }\n\n    // NB: ChatType.Logs also has its own per-peer box (`${peerId}_logs`, via saveLogsMessage), but it's\n    // intentionally NOT mapped here — it stays `_history`. The logs view works through other paths (bubbles\n    // hold the message objects directly, and getMessageByPeer falls back to `… || _logs`), so wiring it to\n    // `_logs` here would need the whole admin-log read path re-verified. If that's ever done, the scheduled\n    // chokepoint in getMessage() can generalize to \"own-peer non-history box\".\n    this.messagesStorageKey = `${this.peerId}_${this.type === ChatType.Scheduled ? 'scheduled' : 'history'}`;\n\n    // this.container && this.container.classList.toggle('no-forwards', this.noForwards);\n\n    if(!this.excludeParts.sharedMedia) {\n      this.sharedMediaTab = appSidebarRight.createSharedMediaTab();\n      this.sharedMediaTabs.push(this.sharedMediaTab);\n      const linkedMonoforumId = (chat?._ === 'channel' && chat.pFlags?.monoforum && chat.linked_monoforum_id)?.toPeerId?.(true);\n      this.sharedMediaTab.setPeer(this.monoforumThreadId || linkedMonoforumId || peerId, threadId);\n    }\n\n    this.input?.clearHelper(); // костыль\n    this.selection?.cleanup(); // TODO: REFACTOR !!!!!!\n  }\n\n  public get requestHistoryOptionsPart(): RequestHistoryOptions {\n    const options: RequestHistoryOptions = {\n      peerId: this.peerId,\n      threadId: this.threadId,\n      monoforumThreadId: this.monoforumThreadId\n    };\n\n    CHAT_SEARCH_KEYS.forEach((key) => {\n      // @ts-ignore\n      options[key] = this[key];\n    });\n\n    if(this.hashtagType && this.hashtagType !== 'this') {\n      options.peerId = NULL_PEER_ID;\n      options.threadId = undefined;\n      options.monoforumThreadId = undefined;\n    }\n\n    return options;\n  }\n\n  public setPeer(options: ChatSetPeerOptions) {\n    const {peerId, threadId, monoforumThreadId, messages, type} = options;\n    if(!peerId) {\n      this.inited = undefined;\n    } else if(!this.inited) {\n      if(this.init) {\n        this.init(/* peerId */);\n        this.init = null;\n      }\n\n      this.inited = true;\n    }\n\n    const samePeer = this.appImManager.isSamePeer(this, options);\n    if(!samePeer) {\n      this.appImManager.dispatchEvent('peer_changing', this);\n      this.peerIdSignal[1](this.peerId = peerId || NULL_PEER_ID);\n      this.threadId = threadId;\n      this.monoforumThreadId = monoforumThreadId;\n      // `onChangePeer` (async) only assigns `isForum` after awaiting the topic reload. Set it\n      // synchronously here too so the `chat_update` listener in bubbles doesn't compare the new\n      // peer against a stale `isForum` mid-transition and reset us to the forum root — which would\n      // drop the threadId when opening a just-created topic in a cold (not-yet-warm) forum.\n      this.isForum = apiManagerProxy.isForum(this.peerId);\n      this.isTemporaryThread = isTempId(threadId);\n      this.noInput = [ChatType.Static, ChatType.Logs].includes(type);\n      this.middlewareHelper.clean();\n      // A fresh peer change always shows the chat next, so its background must publish normally;\n      // the off-screen suppression only guards a stale load from a peer we've already left.\n      this.backgroundHidden = false;\n\n      createRoot((dispose) => {\n        this.middlewareHelper.get().onClean(dispose);\n        this.peer = usePeer(peerId);\n        this.peerTranslation = usePeerTranslation(peerId);\n\n        createEffect(() => {\n          this.autoDownload = useAutoDownloadSettings(this.peer, this.appSettings);\n        });\n      });\n    } else if(this.setPeerPromise) {\n      return;\n    }\n\n    this.staticMessages = messages || [];\n\n    if(!peerId) {\n      this.peerIdSignal[1](this.peerId = 0);\n      let promise: Promise<any>;\n\n      if(this === this.appImManager.chat) {\n        this.currentTheme = undefined;\n        this.currentWallPaper = undefined;\n        promise = this.publishBackground('auto');\n      }\n\n      callbackify(promise, () => {\n        appSidebarRight.toggleSidebar(false);\n        this.cleanup(true);\n        this.bubbles.setPeer({peerId, samePeer: false, sameSearch: false});\n        this.appImManager.dispatchEvent('peer_changed', this);\n\n        if(!this.excludeParts.sharedMedia) {\n          appSidebarRight.replaceSharedMediaTab();\n          this.destroySharedMediaTab();\n          this.sharedMediaTab = undefined;\n        }\n      });\n\n      return;\n    }\n\n    this.peerChanged = samePeer;\n\n    let sameSearch = true;\n    if(!samePeer || CHAT_SEARCH_KEYS.some((key) => options.hasOwnProperty(key))) {\n      CHAT_SEARCH_KEYS.forEach((key) => {\n        // @ts-ignore\n        this[key] = options[key];\n      });\n      sameSearch = false;\n    }\n\n    const {requestHistoryOptionsPart} = this;\n    const forKey: Parameters<typeof getHistoryStorageKey>[0] = {\n      type: getHistoryStorageType(requestHistoryOptionsPart),\n      ...requestHistoryOptionsPart\n    };\n    this.changeHistoryStorageKey(\n      getHistoryStorageKey(forKey),\n      getHistoryStorageKey({...forKey, threadId: undefined})\n    );\n\n    if(options.fromTemporaryThread) {\n      return Promise.resolve({\n        cached: true,\n        promise: this.finishPeerChange({\n          peerId,\n          middleware: () => {\n            return this.peerId === peerId && this.threadId === threadId;\n          }\n        })\n      });\n    }\n\n    const bubblesSetPeerPromise = this.bubbles.setPeer({...options, samePeer, sameSearch});\n    const setPeerPromise = this.setPeerPromise = bubblesSetPeerPromise.then((result) => {\n      return result.promise;\n    }).catch(noop).finally(() => {\n      if(this.setPeerPromise === setPeerPromise) {\n        this.setPeerPromise = null;\n      }\n    });\n\n    return bubblesSetPeerPromise;\n  }\n\n  private changeHistoryStorageKey(key: HistoryStorageKey, keyNoThreadId: HistoryStorageKey) {\n    this.disposeHistoryStorage?.();\n    this.disposeHistoryStorage = undefined;\n    if(!key) {\n      return;\n    }\n\n    this.disposeHistoryStorage = createRoot((dispose) => {\n      this.historyStorage = useHistoryStorage(key);\n      this.historyStorageNoThreadId = useHistoryStorage(keyNoThreadId);\n\n      this.managers.appMessagesManager.toggleHistoryKeySubscription(key, true);\n      onCleanup(() => {\n        this.managers.appMessagesManager.toggleHistoryKeySubscription(key, false);\n      });\n\n      return dispose;\n    });\n  }\n\n  public destroySharedMediaTab(tab = this.sharedMediaTab) {\n    if(!tab) {\n      return;\n    }\n\n    indexOfAndSplice(this.sharedMediaTabs, tab);\n    tab.destroy();\n  }\n\n  public setMessageId(options: Partial<{\n    lastMsgId: number,\n    lastMsgPeerId: PeerId,\n    mediaTimestamp: number,\n    pollOption?: string | Uint8Array,\n    type: ChatType\n  } & ChatSearchKeys> = {}) {\n    return this.setPeer({\n      peerId: this.peerId,\n      threadId: this.threadId,\n      monoforumThreadId: this.monoforumThreadId,\n      ...options\n    });\n  }\n\n  public async finishPeerChange(options: {\n    peerId: PeerId,\n    isTarget?: boolean,\n    isJump?: boolean,\n    lastMsgId?: number,\n    startParam?: string,\n    middleware: () => boolean,\n    text?: string,\n    entities?: MessageEntity[]\n  }) {\n    if(this.peerChanged) return;\n\n    const peerId = this.peerId;\n    this.peerChanged = true;\n    this.wasAlreadyUsed = true;\n\n    const {middleware} = options;\n\n    this.cleanup(false);\n\n    const sharedMediaTab = this.sharedMediaTab;\n\n    const callbacksObj = await namedPromises({\n      topbar: this.topbar?.finishPeerChange(options),\n      bubbles: this.bubbles?.finishPeerChange(),\n      input: this.input?.finishPeerChange(options),\n      sharedMedia: sharedMediaTab?.fillProfileElements(),\n      backgrounds: this.handleBackgrounds()\n    }, this.log);\n\n    const callbacks = Object.values(callbacksObj);\n    sharedMediaTab?.loadSidebarMedia(true);\n\n    if(!middleware()) {\n      return;\n    }\n\n    callbacks.forEach((callback) => {\n      callback?.();\n    });\n\n    if(sharedMediaTab) {\n      appSidebarRight.replaceSharedMediaTab(sharedMediaTab);\n      this.sharedMediaTabs.filter((tab) => tab !== sharedMediaTab).forEach((tab) => this.destroySharedMediaTab(tab));\n    }\n\n    if(this.container) {\n      this.container.dataset.type = this.type === ChatType.Search ? 'chat' : this.type;\n      this.container.classList.toggle('can-click-date', [ChatType.Chat, ChatType.Discussion, ChatType.Saved].includes(this.type));\n    }\n\n    this.log.setPrefix('CHAT-' + peerId + '-' + this.type);\n\n    if(this.isMainChat) {\n      this.appImManager.dispatchEvent('peer_changed', this);\n    }\n  }\n\n  public getMessage(mid: number | FullMid) {\n    if(typeof(mid) === 'string') {\n      const {peerId, mid: _mid} = splitFullMid(mid);\n      // scheduled messages live in a separate per-peer storage; resolving a bare id via\n      // getMessageByPeer would hit history/global and return another chat's message, so for\n      // our own scheduled peer read from this chat's (scheduled) storage instead\n      if(this.type === ChatType.Scheduled && peerId === this.peerId) {\n        return apiManagerProxy.getMessageFromStorage(this.messagesStorageKey, _mid);\n      }\n\n      return apiManagerProxy.getMessageByPeer(peerId, _mid);\n    }\n\n    return apiManagerProxy.getMessageFromStorage(this.messagesStorageKey, mid);\n  }\n\n  public getMessageByPeer(peerId: PeerId, mid: number) {\n    if(!this.query) {\n      return this.getMessage(mid);\n    }\n\n    return apiManagerProxy.getMessageByPeer(peerId, mid);\n  }\n\n  public async getMidsByMid(peerId: PeerId, mid: number) {\n    return this.managers.appMessagesManager.getMidsByMessage(this.getMessageByPeer(peerId, mid));\n  }\n\n  public getHistoryStorage(ignoreThreadId?: boolean) {\n    return ignoreThreadId ? this.historyStorageNoThreadId : this.historyStorage;\n    // return useHistoryStorage(ignoreThreadId ? this.historyStorageKeyNoThreadId : this.historyStorageKey);\n    // return this.managers.appMessagesManager.getHistoryStorageTransferable({\n    //   ...this.requestHistoryOptionsPart,\n    //   threadId: ignoreThreadId ? undefined : this.threadId\n    // }).then((historyStorageTransferable) => {\n    //   return {\n    //     ...historyStorageTransferable,\n    //     history: SlicedArray.fromJSON<number>(historyStorageTransferable.historySerialized),\n    //     searchHistory: historyStorageTransferable.searchHistorySerialized && SlicedArray.fromJSON<string>(historyStorageTransferable.searchHistorySerialized)\n    //   };\n    // });\n  }\n\n  public hasMessages() {\n    const {history} = this.getHistoryStorage(true);\n    return !!history.length;\n  }\n\n  public getDialogOrTopic() {\n    return this.managers.dialogsStorage.getAnyDialog(this.peerId, (this.isForum || this.type === ChatType.Saved) && this.threadId);\n  }\n\n  public getHistoryMaxId() {\n    return this.getHistoryStorage().maxId;\n  }\n\n  // * used to define need of avatars\n  public async _isLikeGroup(peerId: PeerId) {\n    if(peerId === rootScope.myId) return true;\n    if(peerId === REPLIES_PEER_ID) return true;\n    if(this.type === ChatType.Search && this.hashtagType !== 'this') return true;\n    if(this.type === ChatType.Logs) return true;\n\n    const {isBotforum, isLikeGroup} = await namedPromises({\n      isLikeGroup: this.managers.appPeersManager.isLikeGroup(peerId),\n      isBotforum: this.managers.appPeersManager.isBotforum(peerId)\n    });\n\n    return !isBotforum && isLikeGroup;\n  }\n\n  public resetSearch() {\n    this.searchSignal?.(undefined);\n  }\n\n  public initSearch(options: {query?: string, filterPeerId?: PeerId, reaction?: Reaction} = {}): void {\n    if(!this.peerId) return;\n    options.query ||= '';\n    this.searchSignal(options);\n  }\n\n  public canSend(action?: ChatRights) {\n    // Read-only onboarding role: nothing may be sent, anywhere. Gating here turns\n    // off the composer and every affordance that asks first (attach menu, polls,\n    // stickers, reply, schedule...) in one place; the managers refuse the write\n    // itself as well, so a path that doesn't ask still can't send.\n    if(useIsCrmReadOnly()()) return Promise.resolve(false);\n    if(isVerificationBot(this.peerId)) return Promise.resolve(false);\n    if(this.type === ChatType.Saved && this.threadId !== this.peerId) {\n      return Promise.resolve(false);\n    }\n\n    return this.managers.appMessagesManager.canSendToPeer(this.peerId, this.threadId, action);\n  }\n\n  public isStartButtonNeeded() {\n    return Promise.all([\n      this.managers.appPeersManager.isBot(this.peerId),\n      this.managers.appMessagesManager.getDialogOnly(this.peerId),\n      this.getHistoryStorage(true),\n      this.peerId.isUser() ? this.managers.appProfileManager.isCachedUserBlocked(this.peerId.toUserId()) : undefined,\n      this.managers.appPeersManager.isBotforum(this.peerId)\n    ]).then(([isBot, dialog, historyStorage, isUserBlocked, isBotforum]) => {\n      if(!isBot || isVerificationBot(this.peerId) || isBotforum) {\n        return false;\n      }\n\n      return (!dialog && !historyStorage.history.length) || isUserBlocked;\n    });\n  }\n\n  public isPremiumRequiredToContact(peerId = this.peerId) {\n    if(!peerId.isUser()) {\n      return Promise.resolve(false);\n    }\n\n    return this.managers.appUsersManager.getRequirementToContact(peerId.toUserId(), true)\n    .then((requirement) => requirement?._ === 'requirementToContactPremium');\n  }\n\n  public getMessageSendingParams(): MessageSendingParams {\n    return {\n      peerId: this.peerId,\n      threadId: this.threadId,\n      updateStickersetOrder: this.appSettings.stickers.dynamicPackOrder,\n      ...(this.input && {\n        ...(this.input.getReplyTo() || false),\n        ...(this.input.suggestedPost ? {\n          replyToMsgId: this.input.suggestedPost.changeMid\n        } : {}),\n        scheduleDate: this.input.scheduleDate,\n        scheduleRepeatPeriod: this.input.scheduleRepeatPeriod,\n        silent: this.input.sendSilent,\n        sendAsPeerId: this.input.sendAsPeerId,\n        effect: this.input.effect(),\n        suggestedPost: this.input.suggestedPost\n      }),\n      replyToMonoforumPeerId: this.input?.suggestedPost?.monoforumThreadId || this.input?.getReplyTo()?.replyToMonoforumPeerId || this.monoforumThreadId,\n      savedReaction: this.savedReaction\n    };\n  }\n\n  public isOurMessage(message: Message.message | Message.messageService) {\n    if(this.isMegagroup) {\n      return !!message.pFlags.out;\n    }\n\n    if(message.fromId === rootScope.myId && !message.pFlags.post) {\n      return true;\n    }\n\n    if((message as Message.message).fwd_from?.pFlags?.saved_out) {\n      return true;\n      // const peer = apiManagerProxy.getPeer((message as Message.message).fwdFromId);\n      // return !(peer as MTChat.channel)?.pFlags?.broadcast;\n    }\n\n    return false;\n  }\n\n  public isOutMessage(message: Message.message | Message.messageService) {\n    const fwdFrom = (message as Message.message).fwd_from;\n    const isOut = this.isOurMessage(message) && (!fwdFrom || this.peerId !== rootScope.myId || this.threadId);\n    return !!isOut;\n  }\n\n  public isPinnedMessagesNeeded() {\n    return this.type === ChatType.Chat || (this.isForum && this.type !== ChatType.Static && this.type !== ChatType.Logs);\n  }\n\n  public isForwardOfForward(message: Message) {\n    // return isForwardOfForward(message);\n    let is = isForwardOfForward(message);\n    const fwdFrom = (message as Message.message).fwd_from;\n    if(\n      is &&\n      fwdFrom.saved_from_id &&\n      this.type === ChatType.Saved ? getPeerId(fwdFrom.saved_from_id) === this.threadId : false\n      // getPeerId(fwdFrom.saved_from_id) === (this.type === ChatType.Saved ? this.threadId : this.peerId)\n    ) {\n      is = false;\n    }\n\n    return is;\n  }\n\n  public getPostAuthor(message: Message.message) {\n    if(this.isLikeGroup) {\n      return;\n    }\n\n    const fwdFrom = message.fwd_from;\n    const isPost = !!(message.pFlags.post || (fwdFrom?.post_author && !this.isOutMessage(message)));\n    if(!isPost) {\n      return;\n    }\n\n    // if(isForwardOfForward(message) && !message.post_author) {\n    //   return;\n    // }\n\n    // return message.post_author || (fwdFrom && (this.type !== ChatType.Saved || message.fwdFromId !== this.threadId) && fwdFrom.post_author);\n    return message.post_author || fwdFrom?.post_author;\n  }\n\n  public async canGiftPremium() {\n    const peerId = this.peerId;\n    if(!peerId.isUser()) {\n      return false;\n    }\n\n    const [canGiftPremium, isPremiumPurchaseBlocked] = await Promise.all([\n      this.managers.appProfileManager.canGiftPremium(this.peerId.toUserId()),\n      apiManagerProxy.isPremiumPurchaseBlocked()\n    ]);\n\n    return peerId.isUser() && canGiftPremium && !isPremiumPurchaseBlocked;\n  }\n\n  public async openWebApp(options: Partial<RequestWebViewOptions>) {\n    Object.assign(options, this.getMessageSendingParams());\n    options.peerId ??= this.peerId;\n    return this.appImManager.openWebApp(options);\n  }\n\n  public async sendReaction(options: SendReactionOptions) {\n    // Read-only onboarding role: a reaction reaches the customer like any other\n    // write. Bail before the optimistic local update, so nothing flashes on\n    // screen as if it worked.\n    if(useIsCrmReadOnly()()) return;\n\n    const isPaidReaction = options.reaction._ === 'reactionPaid';\n    const count = options.count ?? 1;\n    if(isPaidReaction) {\n      const key = getPendingPaidReactionKey(options.message as Message.message);\n      let pending = PENDING_PAID_REACTIONS.get(key);\n      const hadPending = !!pending;\n      const requiredStars = (pending ? pending.count() : 0) + count;\n      if(+this.stars() < requiredStars) {\n        if(pending) {\n          pending.abortController.abort();\n        }\n\n        PopupElement.createPopup(PopupStars, {\n          itemPrice: count,\n          onTopup: () => {\n            this.sendReaction(options);\n          },\n          purpose: 'reaction',\n          peerId: this.peerId,\n          spendPurposePeerId: this.peerId\n        });\n\n        return;\n      }\n\n      if(!pending) {\n        const [count, setCount] = createSignal(0);\n        const [sendTime, setSendTime] = createSignal(0);\n        const abortController = new AbortController();\n        abortController.signal.addEventListener('abort', () => {\n          clearTimeout(pending.sendTimeout);\n          pending.setSendTime(0);\n          PENDING_PAID_REACTIONS.delete(key);\n\n          if(abortController.signal.reason !== PENDING_PAID_REACTION_SENT_ABORT_REASON) {\n            setReservedStars((reservedStars) => reservedStars - pending.count());\n          }\n\n          rootScope.dispatchEventSingle('messages_reactions', [{\n            message: this.getMessageByPeer(options.message.peerId, options.message.mid) as Message.message,\n            changedResults: [],\n            removedResults: []\n          }]);\n        });\n\n        PENDING_PAID_REACTIONS.set(key, pending = {\n          count,\n          setCount,\n          sendTime,\n          setSendTime,\n          sendTimeout: 0,\n          abortController\n        });\n      } else {\n        clearTimeout(pending.sendTimeout);\n      }\n\n      pending.setCount((_count) => _count + count);\n      pending.setSendTime(Date.now() + SEND_PAID_WITH_STARS_DELAY);\n      pending.sendTimeout = window.setTimeout(() => {\n        const count = pending.count();\n        pending.abortController.abort(PENDING_PAID_REACTION_SENT_ABORT_REASON);\n        this.managers.appReactionsManager.sendReaction({\n          ...options,\n          count\n        });\n      }, SEND_PAID_WITH_STARS_DELAY);\n\n      setReservedStars((reservedStars) => reservedStars + count);\n\n      if(!hadPending) {\n        showUndoablePaidTooltip({\n          titleCount: pending.count,\n          subtitleCount: pending.count,\n          sendTime: pending.sendTime,\n          onUndo: () => void pending.abortController.abort(),\n          ...paidReactionLangKeys\n        });\n      }\n    }\n\n    const messageReactions = await this.managers.appReactionsManager.sendReaction({\n      ...options,\n      count: isPaidReaction ? 0 : count,\n      onlyReturn: isPaidReaction\n    });\n\n    if(isPaidReaction) {\n      const {message} = options;\n      message.reactions = messageReactions;\n      rootScope.dispatchEventSingle('messages_reactions', [{\n        message: message as Message.message,\n        changedResults: [messageReactions.results[0]],\n        removedResults: []\n      }]);\n    }\n  }\n\n  public updateStarsAmount(starsAmount: number) {\n    this.starsAmount = starsAmount;\n    this.input.setStarsAmount(starsAmount);\n    getCurrentNewMediaPopup()?.setStarsAmount(starsAmount);\n  }\n\n  public async getAutoDeletePeriod(): Promise<AckedResult<number>> {\n    try {\n      const dialog = await this.managers.dialogsStorage.getDialogOnly(this.peerId);\n      if(dialog) return {\n        cached: true,\n        result: Promise.resolve(dialog.ttl_period)\n      };\n\n      const fullPeer = this.peerId.isUser() ?\n        await this.managers.acknowledged.appProfileManager.getProfile(this.peerId.toUserId()) :\n        await this.managers.acknowledged.appProfileManager.getChatFull(this.peerId.toChatId());\n\n      return {\n        cached: fullPeer.cached,\n        result: fullPeer.result.then((fullPeer) => fullPeer.ttl_period)\n      }\n    } catch{\n      return {\n        cached: true,\n        result: Promise.resolve(0)\n      };\n    }\n  }\n\n  public async openAutoDeleteMessagesCustomTimePopup() {\n    const {\n      popup: {default: AutoDeleteMessagesCustomTimePopup},\n      autoDeletePeriod\n    } = await namedPromises({\n      popup: import('../sidebarLeft/tabs/autoDeleteMessages/customTimePopup'),\n      autoDeletePeriod: this.getAutoDeletePeriod().then(ackedResult => ackedResult.result)\n    });\n\n    new AutoDeleteMessagesCustomTimePopup({\n      HotReloadGuard: SolidJSHotReloadGuardProvider,\n      descriptionLangKey: this.isBroadcast ? 'AutoDeleteMessages.InfoChannel' : 'AutoDeleteMessages.InfoChat',\n      period: autoDeletePeriod,\n      onFinish: (period) => {\n        this.managers.appPrivacyManager.setAutoDeletePeriodFor(this.peerId, period);\n      }\n    }).show();\n  }\n\n  public canManageAutoDelete = async() => {\n    const specialChats = [REPLIES_PEER_ID, REPLIES_HIDDEN_CHANNEL_ID.toPeerId(), VERIFICATION_CODES_BOT_ID, HIDDEN_PEER_ID, SERVICE_PEER_ID, rootScope.myId];\n    if(specialChats.includes(this.peerId)) return false;\n\n    if(this.peerId.isUser()) return true;\n\n    const {chat, isMonoforum}  = await namedPromises({\n      chat: this.managers.appChatsManager.getChat(this.peerId.toChatId()),\n      isMonoforum: this.managers.appChatsManager.isMonoforum(this.peerId.toChatId())\n    });\n\n    return !isMonoforum && hasRights(chat, 'change_info');\n  }\n\n  public toggleChatIfMedium() {\n    if(mediaSizes.activeScreen === ScreenSize.medium && document.body.classList.contains(LEFT_COLUMN_ACTIVE_CLASSNAME)) {\n      this.appImManager.setPeer({peerId: this.peerId});\n      return true;\n    }\n\n    return false;\n  }\n\n  public pop() {\n    if(this.toggleChatIfMedium()) return;\n\n    const isFirstChat = this.appImManager.chats.indexOf(this) === 0;\n    appNavigationController.back(isFirstChat ? 'im' : 'chat');\n  }\n\n  /**\n   * returns false if this is the only chat\n   */\n  public popIfMoreThanOne() {\n    if(this.toggleChatIfMedium()) return true;\n\n    const isFirstChat = this.appImManager.chats.indexOf(this) === 0;\n    if(isFirstChat) return false;\n\n    appNavigationController.back('chat');\n    return true;\n  }\n}\n","import {StoryItem} from '@layer';\n\nexport type StoryPrivacyType = 'public' | 'close' | 'contacts' | 'selected';\n\nexport default function getStoryPrivacyType(story: StoryItem.storyItem) {\n  let privacyType: StoryPrivacyType;\n  if(story.pFlags.close_friends) {\n    privacyType = 'close';\n  } else if(story.pFlags.public) {\n    privacyType = 'public';\n  } else if(story.pFlags.selected_contacts) {\n    privacyType = 'selected';\n  } else if(story.pFlags.contacts) {\n    privacyType = 'contacts';\n  } else if(story.privacy) {\n    if(story.privacy.some((privacyRule) => privacyRule._ === 'privacyValueAllowContacts')) {\n      privacyType = 'contacts';\n    } else {\n      privacyType = 'selected';\n    }\n  }\n\n  return privacyType;\n}\n","import type {StoriesListPosition, StoriesListType} from '@appManagers/appStoriesManager';\nimport {untrack, createEffect, on, createMemo, batch, onCleanup, createContext, ParentComponent, splitProps, useContext, getOwner, runWithOwner} from 'solid-js';\nimport {createStore, reconcile} from 'solid-js/store';\nimport mediaSizes from '@helpers/mediaSizes';\nimport clamp from '@helpers/number/clamp';\nimport windowSize from '@helpers/windowSize';\nimport {StoryItem, PeerStories, StoryAlbum, StoriesStealthMode} from '@layer';\nimport StoriesCacheType from '@appManagers/utils/stories/cacheType';\nimport insertStory from '@appManagers/utils/stories/insertStory';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport {STORY_DURATION} from '@components/stories/viewer';\nimport createListenerSetter from '../../helpers/solid/createListenerSetter';\nimport insertInDescendSortedArray from '@helpers/array/insertInDescendSortedArray';\nimport {AnyFunction} from '@types';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport AppStoriesManager from '@appManagers/appStoriesManager';\nimport untrackActions from '@helpers/solid/untrackActions';\n\nexport type NextPrevStory = () => void;\nexport type ChangeStoryParams = {\n  peer: StoriesContextPeerState;\n  index?: number;\n};\n\nexport type StoriesContextPeerState = {\n  peerId: PeerId,\n  stories: Array<StoryItem>,\n  albums?: Array<StoryAlbum>,\n  maxReadId?: number,\n  index?: number,\n  count: number\n};\n\nexport type StoriesSortingFreezeType = 'list' | 'viewer';\n\nexport type StoriesContextState = {\n  index: number,\n  paused: boolean,\n  ended: boolean,\n  muted: boolean,\n  loop: boolean,\n  buffering: boolean,\n  hideInterface: boolean,\n  playAfterGesture: boolean,\n  ready: boolean,\n  hasViewer: boolean,\n  startTime: number,\n  elapsedTime: number,\n  elapsedTimeOnPause: number,\n  changeTimeout: number,\n  storyDuration: number,\n  width: number,\n  height: number,\n  pinned: boolean,\n  archive: boolean,\n  stealthMode: StoriesStealthMode,\n  peers: StoriesContextPeerState[],\n  peer: StoriesContextPeerState,\n  freezedSorting: Set<StoriesSortingFreezeType>,\n  getNearestStory: (next: boolean, loop?: boolean, offsetIndex?: number, offsetPeer?: StoriesContextPeerState) => ChangeStoryParams,\n  albumId: number | undefined,\n  loaded: boolean,\n  canEdit: boolean\n};\n\nexport type StoriesContextActions = {\n  play: (storyDuration?: number) => void,\n  pause: (hideInterface?: boolean) => void,\n  toggle: (play?: boolean) => void,\n  stop: () => void,\n  restart: () => void,\n  previous: NextPrevStory,\n  next: NextPrevStory,\n  goToNearestStorySafe: (next: boolean) => void,\n  goToNearestStory: (next: boolean) => void,\n  set: (story: ChangeStoryParams) => void,\n  viewerReady: (ready: boolean) => void,\n  resetIndexes: () => void,\n  toggleMute: () => void,\n  toggleInterface: (hide: boolean) => void,\n  toggleSorting: (type: StoriesSortingFreezeType, freeze: boolean) => void,\n  load: () => Promise<boolean>,\n  setBuffering: (buffering: boolean) => void,\n  setLoop: (loop: boolean) => void,\n  setAlbumId: (albumId: number | undefined) => void,\n  handleSwipe: (xDiff: number, setAlbumOverride?: (albumId: number | undefined) => void) => boolean\n};\n\nexport type StoriesContextValue = [\n  state: StoriesContextState,\n  actions: StoriesContextActions\n];\n\ntype AlbumCacheItem = {\n  stories: StoryItem[],\n  loaded: boolean,\n  count: number\n};\n\nconst createPositions = (positions: Map<PeerId, StoriesListPosition> = new Map()) => {\n  // const [positions, setPositions] = createStore({} as {[peerId: PeerId]: StoriesListPosition});\n  const onPosition = ({peerId, position}: BroadcastEvents['stories_position']) => {\n    if(!position) {\n      positions.delete(peerId);\n      // setPositions(peerId, reconcile(position));\n    } else {\n      positions.set(peerId, position);\n      // setPositions(peerId,  position);\n    }\n  };\n\n  return {positions, onPosition};\n};\n\nconst {positions: globalPositions, onPosition} = createPositions();\nrootScope.addEventListener('stories_position', onPosition);\n\nexport const createStoriesStore = (props: {\n  peers?: StoriesContextPeerState[],\n  index?: number,\n  peerId?: PeerId,\n  needUpdates?: boolean,\n  pinned?: boolean,\n  archive?: boolean,\n  manualLoad?: boolean,\n  onLoad?: (fullLoad: boolean) => void,\n  initialAlbumId?: number,\n  singleStory?: boolean\n}): StoriesContextValue => {\n  const getNearestStory = (\n    next: boolean,\n    loop?: boolean,\n    offsetIndex = state.index,\n    offsetPeer = state.peers[offsetIndex]\n  ): ChangeStoryParams => {\n    const offset = next ? 1 : -1;\n    const newStoryIndex = offsetPeer.index + offset;\n    const isPeerEnd = next ? newStoryIndex >= offsetPeer.stories.length : newStoryIndex < 0;\n    const isLastPeer = next ? offsetIndex >= (state.peers.length - 1) : offsetIndex <= 0;\n    if(!isPeerEnd) {\n      return {\n        peer: offsetPeer,\n        index: newStoryIndex\n      };\n    } else if(!isLastPeer) {\n      const newPeer = state.peers[offsetIndex + offset];\n      return {\n        peer: newPeer,\n        index: newPeer.index\n      };\n    } else if(loop) {\n      const newPeer = state.peers[next ? 0 : state.peers.length - 1];\n      return {\n        peer: newPeer,\n        index: newPeer.index\n      };\n    }\n  };\n\n  const initialState: StoriesContextState = {\n    index: props.index || 0,\n    paused: true,\n    ended: false,\n    muted: true,\n    loop: false,\n    buffering: false,\n    hideInterface: false,\n    playAfterGesture: false,\n    ready: !!props.peers,\n    hasViewer: false,\n    startTime: 0,\n    get elapsedTime() {\n      return state.elapsedTimeOnPause || Date.now() - state.startTime;\n    },\n    elapsedTimeOnPause: 0,\n    changeTimeout: 0,\n    storyDuration: 0,\n    width: 0,\n    height: 0,\n    pinned: props.pinned,\n    archive: props.archive,\n    stealthMode: {_: 'storiesStealthMode'},\n    peers: props.peers || [],\n    get peer() {\n      return state.peers[state.index];\n    },\n    freezedSorting: new Set(),\n    getNearestStory,\n    albumId: props.initialAlbumId as number | undefined,\n    loaded: false,\n    canEdit: false\n  };\n\n  let loadState: string;\n  let loadPromise: Promise<boolean>;\n  const albumCache = new Map<number | undefined, AlbumCacheItem>();\n  const [state, setState] = createStore(initialState);\n  const singlePeerId = props.peerId || (props.peers && props.peers[0].peerId);\n  const currentListType: StoriesListType = props.archive ? 'archive' : 'stories';\n  const {positions, onPosition} = createPositions(new Map(globalPositions));\n  const postponedPositions: Array<BroadcastEvents['stories_position']> = [];\n\n  const getPeerInitialIndex = (peer: StoriesContextPeerState): number => {\n    const maxReadId = peer.maxReadId || 0;\n    const unreadIndex = peer.stories.findIndex((storyItem) => storyItem.id > maxReadId);\n    return Math.max(0, unreadIndex);\n  };\n\n  const getNearestStories = (next: boolean, count: number, loop?: boolean): ChangeStoryParams[] => {\n    let nearestStory: ChangeStoryParams | undefined;\n    const out: ChangeStoryParams[] = [];\n    for(let i = 0; i < count; ++i) {\n      nearestStory = state.getNearestStory(\n        next,\n        loop,\n        nearestStory?.peer ? state.peers.indexOf(nearestStory.peer) : undefined\n      );\n\n      if(!nearestStory) {\n        break;\n      }\n\n      out.push(nearestStory);\n    }\n\n    return out;\n  };\n\n  const checkForNearestSkipped = () => {\n    [\n      ...getNearestStories(true, 3, false),\n      ...getNearestStories(false, 3, false)\n    ].forEach((params) => {\n      const storyItem = params.peer.stories[params.index];\n      if(storyItem?._ === 'storyItemSkipped') {\n        rootScope.managers.appStoriesManager.getStoryById(params.peer.peerId, storyItem.id);\n      }\n    });\n  };\n\n  const load = (reload = false) => {\n    if(loadPromise && !reload) return loadPromise;\n    const doLoad = () => {\n      const {peerId, pinned, archive} = props;\n      if(peerId) {\n        if(pinned || archive) {\n          const {peer} = state;\n          const offsetId = peer && !reload ? peer.stories[peer.stories.length - 1].id : 0;\n          const loadCount = 30;\n          let promise: ReturnType<AppStoriesManager['getPinnedStories']> | ReturnType<AppStoriesManager['getStoriesArchive']> | ReturnType<AppStoriesManager['getAlbumStories']>;\n          let albumsPromise: ReturnType<AppStoriesManager['getAlbums']>;\n          if(state.albumId !== undefined) {\n            promise = rootScope.managers.appStoriesManager.getAlbumStories(peerId, state.albumId, loadCount, offsetId);\n            albumsPromise = !offsetId ? rootScope.managers.appStoriesManager.getAlbums(peerId) : undefined;\n          } else if(pinned) {\n            promise = rootScope.managers.appStoriesManager.getPinnedStories(peerId, loadCount, offsetId);\n            albumsPromise = !offsetId ? rootScope.managers.appStoriesManager.getAlbums(peerId) : undefined;\n          } else {\n            promise = rootScope.managers.appStoriesManager.getStoriesArchive(peerId, loadCount, offsetId);\n          }\n          return Promise.all([promise, albumsPromise]).then(([{count, stories: storyItems}, albums]) => {\n            if(!offsetId && !reload) {\n              const peer: StoriesContextPeerState = {\n                index: 0,\n                peerId,\n                stories: storyItems,\n                count,\n                albums\n              };\n\n              addPeers([peer]);\n              setState({ready: true, loaded: storyItems.length < loadCount});\n            } else {\n              batch(() => {\n                setState('peers', 0, 'stories', offsetId ? (stories) => [...stories, ...storyItems] : storyItems);\n                setState('peers', 0, 'count', count);\n                setState('loaded', storyItems.length < loadCount);\n              })\n            }\n\n            const loaded = state.loaded;\n            props.onLoad?.(loaded);\n            return loaded;\n          });\n        }\n\n        return rootScope.managers.appStoriesManager.getPeerStories(peerId).then((peerStories) => {\n          addPeerStories([peerStories]);\n          setState('loaded', true);\n          props.onLoad?.(true);\n          return true;\n        });\n      }\n\n      return rootScope.managers.appStoriesManager.getAllStories(\n        loadState ? true : undefined,\n        loadState,\n        archive\n      ).then((storiesAllStories) => {\n        loadState = storiesAllStories.state;\n        const loaded = !storiesAllStories.pFlags.has_more;\n        setState('loaded', loaded);\n        addPeerStories(storiesAllStories.peer_stories);\n\n        if(!loaded) {\n          // pause(5000).then(load);\n          load();\n        }\n\n        props.onLoad?.(loaded);\n        return loaded;\n      });\n    };\n    return loadPromise = doLoad().finally(() => loadPromise = undefined);\n  };\n\n  const actions: StoriesContextActions = {\n    set: (params) => {\n      if(!params) {\n        setState({ended: true});\n        return;\n      }\n\n      const peerIndex = state.peers.indexOf(params.peer);\n      // actions.stop(); // ! was working\n\n      if(params.index !== undefined) {\n        setState('peers', peerIndex, 'index', params.index);\n      }\n\n      actions.stop();\n\n      if(state.peer !== params.peer) {\n        setState({index: peerIndex});\n      }\n\n      // actions.stop(); // ! doesn't work when animations are disabled\n\n      // setTimeout(() => {\n      checkForNearestSkipped();\n      // }, 1e3);\n    },\n\n    pause: (hideInterface) => {\n      setState({paused: true, playAfterGesture: hideInterface && !state.paused});\n      actions.toggleInterface(hideInterface);\n    },\n\n    play: (storyDuration = state.storyDuration) => {\n      if(state.buffering || !state.hasViewer) {\n        return;\n      }\n\n      setState({paused: false, storyDuration});\n      actions.toggleInterface(false);\n    },\n\n    stop: () => {\n      // clearTimeout(changeTimeout);\n      actions.pause();\n      setState({startTime: 0, elapsedTimeOnPause: 0});\n    },\n\n    restart: () => {\n      setState({buffering: false});\n      actions.stop();\n      actions.play();\n    },\n\n    toggle: (play = state.paused) => {\n      if(play) {\n        actions.play();\n      } else {\n        actions.pause();\n      }\n    },\n\n    previous: () => actions.goToNearestStory(false),\n    next: () => actions.goToNearestStory(true),\n    goToNearestStorySafe: (next: boolean) => {\n      if(next) {\n        actions.next();\n        return;\n      }\n\n      const story = state.getNearestStory(next);\n      if(!story || (state.storyDuration !== STORY_DURATION && (state.elapsedTime / state.storyDuration) > 0.5)) {\n        actions.restart();\n      } else {\n        actions.set(story);\n      }\n    },\n    goToNearestStory: (next: boolean) => {\n      const story = state.getNearestStory(next);\n      actions.set(story);\n    },\n\n    viewerReady: (ready) => {\n      setState({hasViewer: ready, ended: false});\n    },\n\n    resetIndexes: () => {\n      setState('peers', {}, (peer) => {\n        return {index: getPeerInitialIndex(peer)};\n      });\n    },\n\n    toggleMute: () => {\n      setState({muted: !state.muted});\n    },\n\n    toggleInterface: (hide) => {\n      setState({hideInterface: hide});\n    },\n\n    toggleSorting: (type, freeze) => {\n      if(freeze) state.freezedSorting.add(type);\n      else {\n        state.freezedSorting.delete(type);\n\n        if(!state.freezedSorting.size) {\n          postponedPositions.splice(0, Infinity).forEach((data) => onStoriesPosition(data, true));\n        } else if(type === 'viewer') {\n          forEachReverse(postponedPositions, (data, idx) => {\n            if(data.position && data.position.type !== currentListType) {\n              postponedPositions.splice(idx, 1);\n              onStoriesPosition(data, true);\n            }\n          });\n        }\n      }\n    },\n\n    load,\n\n    setBuffering: (buffering) => {\n      setState({buffering});\n    },\n\n    setLoop: (loop) => {\n      setState({loop});\n    },\n\n    setAlbumId: (albumId) => {\n      if(state.albumId === albumId) return;\n      // save current album's data to cache\n      const peer = state.peers[0];\n      if(peer?.stories?.length) {\n        albumCache.set(state.albumId, {stories: peer.stories.slice(), loaded: state.loaded, count: peer.count});\n      }\n      // restore from cache if available\n      const cached = albumCache.get(albumId);\n      if(cached) {\n        batch(() => {\n          setState('albumId', albumId);\n          setState('peers', 0, 'stories', cached.stories);\n          setState('peers', 0, 'count', cached.count);\n          setState('loaded', cached.loaded);\n        });\n      } else {\n        batch(() => {\n          setState('albumId', albumId);\n          setState('peers', 0, 'stories', []);\n          setState('loaded', false);\n        });\n        load(true);\n      }\n    },\n\n    handleSwipe: (xDiff: number, setAlbumOverride?: (albumId: number | undefined) => void) => {\n      const albums = state.peers[0]?.albums;\n      if(!albums?.length) return false;\n\n      const direction = xDiff > 0 ? 1 : -1;\n      const currentAlbumId = state.albumId;\n      const currentIndex = currentAlbumId === undefined ? -1 :\n        albums.findIndex((a) => a.album_id === currentAlbumId);\n      const newIndex = currentIndex + direction;\n      if(newIndex < -1 || newIndex >= albums.length) return false;\n\n      const newAlbumId = newIndex === -1 ? undefined : albums[newIndex].album_id;\n      (setAlbumOverride ?? actions.setAlbumId)(newAlbumId);\n      return true;\n    }\n  };\n\n  untrackActions(actions);\n\n  const setChangeTimeout = () => {\n    clearTimeout(state.changeTimeout);\n    setState({\n      startTime: Date.now() - state.elapsedTimeOnPause,\n      changeTimeout: window.setTimeout(() => {\n        if(state.loop) {\n          actions.restart();\n        } else {\n          actions.next();\n        }\n      }, state.storyDuration - state.elapsedTimeOnPause)\n    });\n  };\n\n  createEffect( // * on pause or buffering\n    on(\n      createMemo(() => state.paused || state.buffering),\n      (paused) => {\n        if(paused) {\n          clearTimeout(state.changeTimeout);\n          setState({elapsedTimeOnPause: Date.now() - state.startTime});\n        } else {\n          setChangeTimeout();\n        }\n      },\n      {defer: true}\n    )\n  );\n\n  const listenerSetter = createListenerSetter();\n\n  // * size section\n  const calculateStoryHeight = () => {\n    return windowSize.height - 48 - 8 - 8 * 2 - 8;\n  };\n\n  const calculateStoryWidth = (height = calculateStoryHeight()) => {\n    const ratio = 9 / 16;\n    return Math.min(windowSize.width, height * ratio);\n  };\n\n  const calculateSize = () => {\n    const height = calculateStoryHeight();\n    return {width: calculateStoryWidth(height), height};\n  };\n\n  const onResize = () => {\n    setState(calculateSize());\n  };\n\n  createEffect(onResize);\n  // * size section end\n\n  const getPeerIndex = (peerId: PeerId, peers = state.peers) => {\n    return peers.findIndex((peer) => peer.peerId === peerId);\n  };\n\n  const userStoriesToPeer = (peerStories: PeerStories): StoriesContextPeerState => {\n    const peer: StoriesContextPeerState = {\n      // index: 0,\n      peerId: getPeerId(peerStories.peer),\n      stories: peerStories.stories,\n      maxReadId: peerStories.max_read_id,\n      count: peerStories.stories.length\n    };\n\n    peer.index = getPeerInitialIndex(peer);\n    return peer;\n  };\n\n  const addPeers = (addPeers: StoriesContextPeerState[]) => {\n    const modifyIndexes: {peerId: PeerId; index: number}[] = [];\n    let modifyCurrentIndex = state.index;\n\n    const peers = state.peers.slice();\n    const previousPeers = new Map(peers.map((peer, idx) => [peer.peerId, idx]));\n    const currentPeerId = state.peer?.peerId;\n    const currentIndex = previousPeers.get(currentPeerId) ?? -1;\n    for(const peer of addPeers) {\n      // const sortIndex = positions.get(peer.peerId).index;\n      // if(!sortIndex) {\n      //   continue;\n      // }\n\n      const previousPeerIdx = previousPeers.get(peer.peerId) ?? -1;\n      const previousPeer = peers[previousPeerIdx];\n      const newIndex = clamp(previousPeer?.index || getPeerInitialIndex(peer), 0, peer.stories.length - 1);\n\n      if(peer.index !== newIndex) {\n        modifyIndexes.push({peerId: peer.peerId, index: newIndex});\n        // peer.index = newIndex;\n      }\n\n      if(previousPeerIdx !== -1) {\n        peers[previousPeerIdx] = peer;\n      }\n\n      insertInDescendSortedArray(peers, peer, (peer) => {\n        const position = positions.get(peer.peerId);\n        return position?.index ?? 0;\n      }, previousPeerIdx);\n    }\n\n    if(currentIndex !== -1) {\n      const newCurrentIndex = getPeerIndex(currentPeerId, peers);\n      if(newCurrentIndex !== currentIndex) {\n        modifyCurrentIndex = newCurrentIndex;\n      }\n    }\n\n    batch(() => {\n      setState('peers', reconcile(peers, {key: 'peerId', merge: true}));\n      setState({\n        // peers,\n        index: modifyCurrentIndex\n      });\n\n      for(const {peerId, index} of modifyIndexes) {\n        const peerIndex = getPeerIndex(peerId, peers);\n        setState('peers', peerIndex, 'index', index);\n      }\n    });\n  };\n\n  const canAddPeer = (peerId: PeerId) => {\n    if(singlePeerId) {\n      return singlePeerId === peerId;\n    }\n\n    const position = positions.get(peerId);\n    if(!position) {\n      return false;\n    }\n\n    return position.type === currentListType;\n  };\n\n  const addPeerStories = (peerStories: PeerStories[]) => {\n    const peers = peerStories.map(userStoriesToPeer);\n    addPeers(peers);\n    setState({ready: true});\n  };\n\n  const deletePeer = (peerId: PeerId, peerIndex = getPeerIndex(peerId)) => {\n    if(peerIndex === -1) {\n      return;\n    }\n\n    const isActive = state.index === peerIndex;\n    batch(() => {\n      const newPeers = state.peers.slice();\n      newPeers.splice(peerIndex, 1);\n      const newIndex = state.index > peerIndex ? state.index - 1 : state.index;\n      setState({\n        peers: newPeers,\n        ...(newPeers.length ? {} : {ended: true}),\n        ...(newIndex < newPeers.length ? {index: newIndex} : {ended: true})\n      });\n\n      if(isActive) {\n        actions.restart();\n      }\n    });\n  };\n\n  const isStoryInAlbum = (story: StoryItem, albumId: number | undefined) => {\n    return albumId === undefined || story._ === 'storyItem' && !!story.albums?.includes(albumId);\n  };\n\n  const syncManagerSnapshot = (albumId: number | undefined, active: boolean) => {\n    if(singlePeerId === undefined) {\n      return;\n    }\n\n    const promise = albumId === undefined ?\n      rootScope.managers.appStoriesManager.getPinnedStoriesCacheSnapshot(singlePeerId) :\n      rootScope.managers.appStoriesManager.getAlbumStoriesCacheSnapshot(singlePeerId, albumId)\n\n    promise.then((snapshot) => {\n      if(active) {\n        const currentStoryId = state.peers[0]?.stories[state.peers[0]?.index || 0]?.id;\n        const preservedIndex = currentStoryId === undefined ? -1 : snapshot.stories.findIndex((story) => story.id === currentStoryId);\n        const nextIndex = preservedIndex !== -1 ?\n          preservedIndex :\n          Math.min(state.peers[0]?.index || 0, Math.max(0, snapshot.stories.length - 1));\n\n        batch(() => {\n          setState('peers', 0, 'stories', reconcile(snapshot.stories, {key: 'id', merge: true}));\n          setState('peers', 0, 'count', snapshot.count);\n          setState('peers', 0, 'index', nextIndex);\n          setState('loaded', snapshot.loaded);\n          setState({ended: !snapshot.stories.length});\n        });\n      } else {\n        albumCache.set(albumId, {\n          stories: snapshot.stories.slice(),\n          loaded: snapshot.loaded,\n          count: snapshot.count\n        });\n      }\n    });\n  };\n\n  const shouldRefreshAlbumSnapshot = (albumId: number, storyId: number, story?: StoryItem) => {\n    return albumCache.get(albumId)?.stories.some((item) => item.id === storyId) || !!(story && isStoryInAlbum(story, albumId));\n  };\n\n  const syncPinnedAlbumsFromManager = (peerId: PeerId, storyId: number, story?: StoryItem) => {\n    if(!singlePeerId || !props.pinned || peerId !== singlePeerId) {\n      return false;\n    }\n\n    const isActivePeer = state.peers[0]?.peerId === peerId;\n\n    if(albumCache.has(undefined)) {\n      syncManagerSnapshot(undefined, false);\n    }\n\n    if(isActivePeer) {\n      if(state.albumId === undefined) {\n        syncManagerSnapshot(undefined, true);\n      } else if(\n        state.peers[0]?.stories.some((item) => item.id === storyId) ||\n        !!(story && isStoryInAlbum(story, state.albumId))\n      ) {\n        syncManagerSnapshot(state.albumId, true);\n      }\n    }\n\n    for(const albumId of albumCache.keys()) {\n      if(albumId === undefined || albumId === state.albumId) {\n        continue;\n      }\n\n      if(shouldRefreshAlbumSnapshot(albumId, storyId, story)) {\n        syncManagerSnapshot(albumId, false);\n      }\n    }\n\n    return isActivePeer;\n  };\n\n  // * updates section\n  const onStoryUpdate = ({peerId, story, modifiedPinned, modifiedArchive, modifiedPinnedToTop}: BroadcastEvents['story_update']) => {\n    const peerIndex = getPeerIndex(peerId);\n    if(peerIndex === -1) {\n      return;\n    }\n\n    if(syncPinnedAlbumsFromManager(peerId, story.id, story)) {\n      return;\n    }\n\n    const peer = state.peers[peerIndex];\n    const storyIndex = peer.stories.findIndex((s) => s.id === story.id);\n    if(props.pinned && modifiedPinned) {\n      if(!(story as StoryItem.storyItem).pFlags.pinned) {\n        onStoryDeleted({peerId, id: story.id});\n      } else {\n        onStoryNew({peerId, story, cacheType: StoriesCacheType.Pinned, maxReadId: peer.maxReadId});\n      }\n\n      return;\n    }\n\n    // * change position of story\n    if(props.pinned && modifiedPinnedToTop) {\n      const pinnedIndex = (story as StoryItem.storyItem).pinnedIndex;\n      if( // * if story is unpinned and it should be far far away\n        pinnedIndex === undefined &&\n        story.id < peer.stories[peer.stories.length - 1].id &&\n        !state.loaded\n      ) {\n        onStoryDeleted({peerId, id: story.id});\n        return;\n      }\n\n      if(storyIndex === -1) {\n        onStoryNew({peerId, story, cacheType: StoriesCacheType.Pinned, maxReadId: peer.maxReadId});\n      } else {\n        setState('peers', peerIndex, 'stories', reconcile(((stories) => {\n          stories = stories.slice();\n          stories.splice(storyIndex, 1);\n          insertStory(stories, story, false, StoriesCacheType.Pinned);\n          return stories;\n        })(peer.stories), {key: 'id', merge: true}));\n      }\n      return;\n    }\n\n    if(storyIndex === -1) {\n      if(props.archive && singlePeerId && modifiedArchive) {\n        onStoryNew({peerId, story, cacheType: StoriesCacheType.Archive, maxReadId: peer.maxReadId});\n      }\n\n      return;\n    }\n\n    setState('peers', peerIndex, 'stories', storyIndex, reconcile(story));\n  };\n\n  const onStoriesStories = (peerStories: PeerStories) => {\n    const peerId = getPeerId(peerStories.peer);\n    if(!canAddPeer(peerId)) {\n      return;\n    }\n\n    addPeerStories([peerStories]);\n  };\n\n  const onStoryNew = ({peerId, story, cacheType, maxReadId}: BroadcastEvents['story_new']) => {\n    if(!canAddPeer(peerId)) {\n      return;\n    }\n\n    if(props.pinned && !(story as StoryItem.storyItem).pFlags?.pinned) {\n      return;\n    }\n\n    if(syncPinnedAlbumsFromManager(peerId, story.id, story)) {\n      return;\n    }\n\n    const peerIndex = getPeerIndex(peerId);\n    if(peerIndex === -1) {\n      const peer: StoriesContextPeerState = {\n        peerId,\n        stories: [story],\n        maxReadId,\n        count: 1\n      };\n      peer.index = getPeerInitialIndex(peer);\n      addPeers([peer]);\n      return;\n    }\n\n    const peer = state.peers[peerIndex];\n    const stories = peer.stories;\n    const storyIndex = stories.findIndex((s) => s.id === story.id);\n    if(storyIndex !== -1) {\n      setState('peers', peerIndex, 'stories', storyIndex, story);\n      return;\n    }\n\n    batch(() => {\n      const currentStoryIndex = state.peer.index;\n      let insertedAt: number;\n      setState('peers', peerIndex, 'stories', (stories) => {\n        stories = stories.slice();\n        insertedAt = insertStory(stories, story, false, cacheType);\n        return stories;\n      });\n\n      setState('peers', peerIndex, 'count', (count) => count + 1);\n\n      if(insertedAt <= currentStoryIndex) {\n        setState('peers', peerIndex, 'index', (index) => index + 1);\n      }\n    });\n  };\n\n  const onStoryDeleted = ({peerId, id}: {peerId: PeerId, id: number}) => {\n    if(syncPinnedAlbumsFromManager(peerId, id)) {\n      return;\n    }\n\n    const peerIndex = getPeerIndex(peerId);\n    if(peerIndex === -1) {\n      return;\n    }\n\n    const peer = state.peers[peerIndex];\n    const stories = peer.stories;\n    const storyIndex = stories.findIndex((s) => s.id === id);\n    if(storyIndex === -1) {\n      return;\n    }\n\n    if(stories.length === 1) {\n      deletePeer(peerId, peerIndex);\n      return;\n    }\n\n    batch(() => {\n      if(state.peer === peer && peer.index === storyIndex) {\n        actions.next();\n      }\n\n      setState('peers', peerIndex, 'stories', (stories) => {\n        stories = stories.slice();\n        stories.splice(storyIndex, 1);\n        return stories;\n      });\n\n      setState('peers', peerIndex, 'count', (count) => count - 1);\n\n      if(peer.index >= storyIndex) {\n        setState('peers', peerIndex, 'index', peer.index - 1);\n      }\n    });\n  };\n\n  const onStoriesRead = ({peerId, maxReadId}: BroadcastEvents['stories_read']) => {\n    const peerIndex = getPeerIndex(peerId);\n    if(peerIndex === -1) {\n      return;\n    }\n\n    setState('peers', peerIndex, 'maxReadId', maxReadId);\n  };\n\n  // const onUserStoriesHidden = ({userId, hidden}: BroadcastEvents['user_stories_hidden']) => {\n  //   const peerId = userId.toPeerId(false);\n  //   const peerIndex = getPeerIndex(peerId);\n  //   if(peerIndex === -1) {\n  //     return;\n  //   }\n\n  //   if((props.archive && !hidden) || (!props.archive && hidden)) {\n  //     deletePeer(peerId);\n  //   }\n  // };\n\n  const onStoriesPosition = (data: BroadcastEvents['stories_position'], ignoreFreezed?: boolean) => {\n    const {peerId, position} = data;\n    if(state.freezedSorting.size && !ignoreFreezed) {\n      const previousPosition = positions.get(peerId);\n      if(previousPosition?.type === position?.type || (state.hasViewer && previousPosition && position)) {\n        findAndSplice(postponedPositions, (data) => data.peerId === peerId);\n        postponedPositions.push(data);\n        return;\n      }\n    }\n\n    onPosition(data);\n\n    if(!canAddPeer(peerId)) {\n      deletePeer(peerId);\n      return;\n    }\n\n    const peer = state.peers.find((p) => p.peerId === peerId);\n    if(!peer) {\n      return;\n    }\n\n    addPeers([peer]);\n  };\n\n  const onStealthMode = (data: BroadcastEvents['stories_stealth_mode']) => {\n    setState('stealthMode', reconcile(data));\n  };\n\n  listenerSetter.add(rootScope)('story_update', onStoryUpdate);\n  listenerSetter.add(rootScope)('story_deleted', onStoryDeleted);\n  if(!props.archive && !props.pinned) {\n    listenerSetter.add(rootScope)('story_expired', onStoryDeleted);\n  }\n  if(!props.singleStory) {\n    listenerSetter.add(rootScope)('story_new', onStoryNew);\n  }\n  if(!singlePeerId || props.needUpdates) {\n    listenerSetter.add(rootScope)('stories_stories', onStoriesStories);\n    listenerSetter.add(rootScope)('stories_read', onStoriesRead);\n    // listenerSetter.add(rootScope)('user_stories_hidden', onUserStoriesHidden);\n    listenerSetter.add(rootScope)('stories_position', onStoriesPosition);\n  }\n  listenerSetter.add(rootScope)('stories_stealth_mode', onStealthMode);\n\n  if(singlePeerId && props.pinned) {\n    listenerSetter.add(rootScope)('story_album_created', ({peerId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      setState('peers', 0, 'albums', albums);\n    });\n\n    listenerSetter.add(rootScope)('story_album_deleted', ({peerId, albumId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      albumCache.delete(albumId);\n      if(state.albumId === albumId) {\n        if(albumCache.has(undefined)) {\n          syncManagerSnapshot(undefined, false);\n        }\n        actions.setAlbumId(undefined);\n        albumCache.delete(albumId);\n      }\n      setState('peers', 0, 'albums', albums);\n    });\n\n    listenerSetter.add(rootScope)('story_album_updated', ({peerId, albumId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      setState('peers', 0, 'albums', albums);\n\n      if(albumCache.has(undefined)) {\n        syncManagerSnapshot(undefined, false);\n      }\n\n      if(state.albumId === albumId) {\n        syncManagerSnapshot(albumId, true);\n      } else if(albumCache.has(albumId)) {\n        syncManagerSnapshot(albumId, false);\n      }\n    });\n  }\n\n  // * updates section end\n\n  if(!props.manualLoad) {\n    if(!state.ready) {\n      actions.load();\n    } else if(state.peer.index === undefined) {\n      actions.resetIndexes();\n    }\n  }\n\n  rootScope.managers.appStoriesManager.getStealthMode().then(onStealthMode);\n\n  if(singlePeerId) {\n    if(singlePeerId === rootScope.myId) {\n      setState({canEdit: true});\n    } else if(singlePeerId.isAnyChat()) {\n      rootScope.managers.appChatsManager.hasRights(singlePeerId.toChatId(), 'edit_stories').then((canEdit) => {\n        setState({canEdit});\n      });\n    }\n  }\n\n  return [state, actions];\n};\n\n// const storiesStore = createStoriesStore();\nexport const StoriesContext = createContext<StoriesContextValue>(/* storiesStore */);\nexport const StoriesProvider: ParentComponent<Parameters<typeof createStoriesStore>[0]> = (props) => {\n  const [, rest] = splitProps(props, ['peers', 'index', 'peerId', 'pinned', 'archive']);\n  return (\n    <StoriesContext.Provider value={createStoriesStore(props)}>\n      {props.children}\n    </StoriesContext.Provider>\n  );\n}\n\nexport const useStories = () => useContext(StoriesContext);\n","import type {PeerAvailableReactions} from '@appManagers/appReactionsManager';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {IS_MOBILE, IS_SAFARI} from '@environment/userAgent';\nimport filterUnique from '@helpers/array/filterUnique';\nimport assumeType from '@helpers/assumeType';\nimport callbackifyAll from '@helpers/callbackifyAll';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport liteMode from '@helpers/liteMode';\nimport {Middleware, getMiddleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport {fastRaf} from '@helpers/schedulers';\nimport {Message, AvailableReaction, Reaction, AvailableEffect, EmojiGroup} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport lottieLoader from '@lib/rlottie/lottieLoader';\nimport RLottiePlayer from '@lib/rlottie/rlottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport ButtonIcon from '@components/buttonIcon';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport EmojiTab from '@components/emoticonsDropdown/tabs/emoji';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {i18n} from '@lib/langPack';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupPremium from '@components/popups/premium';\nimport contextMenuController from '@helpers/contextMenuController';\nimport callbackify from '@helpers/callbackify';\nimport partition from '@helpers/array/partition';\nimport {PAID_REACTION_EMOJI_DOCID} from '@lib/customEmoji/constants';\nimport {StarsStar} from '@components/popups/stars';\nimport {cleanEmoji} from '@lib/richTextProcessor/fixEmoji';\n\nconst REACTIONS_CLASS_NAME = 'btn-menu-reactions';\nconst REACTION_CLASS_NAME = REACTIONS_CLASS_NAME + '-reaction';\n\nconst REACTIONS_MAX_LENGTH = 7;\nconst REACTION_SIZE = 28; // 36\nconst PADDING = 6;\nexport const REACTION_CONTAINER_SIZE = REACTION_SIZE + PADDING * 2;\n\nconst CAN_USE_TRANSFORM = !IS_SAFARI;\nconst SCALE_ON_HOVER = CAN_USE_TRANSFORM && false;\n\ntype ChatReactionsMenuPlayers = {\n  select?: RLottiePlayer,\n  appear?: RLottiePlayer,\n  selectWrapper: HTMLElement,\n  appearWrapper: HTMLElement,\n  reaction: Reaction\n};\nexport class ChatReactionsMenu {\n  public widthContainer: HTMLElement;\n  public container: HTMLElement;\n  private reactionsMap: Map<HTMLElement, ChatReactionsMenuPlayers>;\n  // private scrollable: ScrollableBase;\n  private animationGroup: AnimationItemGroup;\n  private middlewareHelper: ReturnType<typeof getMiddleware>;\n  private managers: AppManagers;\n  private onFinish: (reaction?: Reaction | Promise<Reaction>) => void;\n  private listenerSetter: ListenerSetter;\n  private size: number;\n  private openSide: 'top' | 'bottom';\n  private getOpenPosition: (hasMenu: boolean) => DOMRectEditable;\n  private noMoreButton: boolean;\n  private isTags: boolean;\n  private isEffects: boolean;\n  private reactions: Reaction[];\n  private availableReactions: AvailableReaction[];\n  private noPacks: boolean;\n  private noSearch: boolean;\n  public freeCustomEmoji: Set<DocId>;\n  public inited: boolean;\n\n  constructor(options: {\n    managers: AppManagers,\n    type: 'horizontal' | 'vertical',\n    middleware: Middleware,\n    onFinish: ChatReactionsMenu['onFinish'],\n    size?: ChatReactionsMenu['size'],\n    openSide?: ChatReactionsMenu['openSide'],\n    getOpenPosition: ChatReactionsMenu['getOpenPosition'],\n    noMoreButton?: boolean,\n    isTags?: boolean,\n    isEffects?: boolean\n  }) {\n    this.managers = options.managers;\n    this.middlewareHelper = options.middleware ? options.middleware.create() : getMiddleware();\n    this.onFinish = options.onFinish;\n    this.listenerSetter = new ListenerSetter();\n    this.size = options.size ?? REACTION_SIZE;\n    this.openSide = options.openSide ?? 'bottom';\n    this.getOpenPosition = options.getOpenPosition;\n    this.noMoreButton = options.noMoreButton;\n    this.isTags = options.isTags;\n    this.isEffects = options.isEffects;\n\n    this.middlewareHelper.get().onDestroy(() => {\n      this.listenerSetter.removeAll();\n    });\n\n    const widthContainer = this.widthContainer = document.createElement('div');\n    widthContainer.classList.add(\n      REACTIONS_CLASS_NAME + '-container',\n      REACTIONS_CLASS_NAME + '-container-' + options.type,\n      'btn-menu-transition'\n    );\n\n    if(this.isTags || this.isEffects) {\n      widthContainer.classList.add(REACTIONS_CLASS_NAME + '-container-' + 'tags');\n      const description = this.isEffects ? i18n('AddEffectMessageHint') : i18n(\n        rootScope.premium ? 'Reactions.Tag.Description' : 'Reactions.Tag.PremiumHint',\n        [\n          anchorCallback(() => {\n            contextMenuController.close();\n            PopupPremium.show({feature: 'saved_tags'});\n          })\n        ]\n      );\n      description.classList.add(REACTIONS_CLASS_NAME + '-description');\n      widthContainer.append(description);\n    }\n\n    const reactionsContainer = this.container = document.createElement('div');\n    reactionsContainer.classList.add(REACTIONS_CLASS_NAME/* , 'btn-menu-transition' */);\n\n    // const shadow = document.createElement('div');\n    // shadow.classList.add('inner-shadow');\n\n    // const reactionsScrollable = this.scrollable = type === 'vertical' ? new Scrollable(undefined) : new ScrollableX(undefined);\n    // reactionsContainer.append(reactionsScrollable.container/* , shadow */);\n    // reactionsScrollable.onAdditionalScroll = this.onScroll;\n    // reactionsScrollable.setListeners();\n    // reactionsScrollable.container.classList.add('no-scrollbar');\n\n    ['big'].forEach((type) => {\n      const bubble = document.createElement('div');\n      bubble.classList.add(\n        REACTIONS_CLASS_NAME + '-bubble',\n        REACTIONS_CLASS_NAME + '-bubble-' + type\n        // 'btn-menu-transition'\n      );\n      widthContainer.append(bubble);\n    });\n\n    this.reactionsMap = new Map();\n    this.animationGroup = `CHAT-MENU-REACTIONS-${Date.now()}`;\n    animationIntersector.setOverrideIdleGroup(this.animationGroup, true);\n\n    if(!IS_TOUCH_SUPPORTED) {\n      reactionsContainer.addEventListener('mousemove', this.onMouseMove);\n    }\n\n    attachClickEvent(reactionsContainer, (e) => {\n      const reactionDiv = findUpClassName(e.target, REACTION_CLASS_NAME);\n      if(!reactionDiv) return;\n\n      const players = this.reactionsMap.get(reactionDiv);\n      if(!players) return;\n\n      this.onFinish(players.reaction);\n    }, {listenerSetter: this.listenerSetter});\n\n    widthContainer.append(reactionsContainer);\n  }\n\n  private render = async(renderPromises: Promise<any>[], hasMore: boolean) => {\n    const middleware = this.middlewareHelper.get();\n    await Promise.all(renderPromises);\n    if(!middleware()) {\n      return;\n    }\n\n    if(hasMore && !this.noMoreButton) {\n      const moreButton = ButtonIcon(`${this.openSide === 'bottom' ? 'down' : 'up'} ${REACTIONS_CLASS_NAME}-more`, {noRipple: true});\n      this.container.append(moreButton);\n      attachClickEvent(\n        moreButton,\n        this.onMoreClick,\n        {listenerSetter: this.listenerSetter}\n      );\n    }\n\n    const setVisible = () => {\n      this.widthContainer.classList.add('is-visible');\n    };\n\n    return setVisible;\n  };\n\n  private renderReactions(\n    {type, reactions}: PeerAvailableReactions,\n    availableReactions: AvailableReaction[]\n  ) {\n    if(availableReactions) {\n      this.availableReactions = availableReactions;\n      this.freeCustomEmoji = new Set(\n        this.availableReactions\n        .map((availableReaction) => availableReaction.select_animation.id)\n        .concat(reactions.map((reaction) => this.reactionToDocId(reaction)))\n      );\n    }\n\n    const renderPromises = reactions.slice(0, REACTIONS_MAX_LENGTH).map((reaction) => {\n      const availableReaction = reaction._ === 'reactionEmoji' ? availableReactions.find((_reaction) => _reaction.reaction === reaction.emoticon) : undefined;\n      return this.renderReaction(reaction, availableReaction);\n    });\n\n    return this.render(renderPromises, reactions.length > REACTIONS_MAX_LENGTH);\n  }\n\n  private renderEffects(availableEffects: AvailableEffect[]) {\n    const renderPromises = availableEffects.slice(0, REACTIONS_MAX_LENGTH).map((availableEffect) => {\n      return this.renderReaction({_: 'reactionCustomEmoji', document_id: availableEffect.effect_sticker_id});\n    });\n\n    return this.render(renderPromises, availableEffects.length > REACTIONS_MAX_LENGTH);\n  }\n\n  private async prepareReactions(message?: Message.message | Message.messageService) {\n    const middleware = this.middlewareHelper.get();\n    const availableReactionsResult = apiManagerProxy.getAvailableReactions();\n    const peerAvailableReactionsResult = await this.managers.acknowledged.appReactionsManager.getAvailableReactionsByMessage(message);\n    const cached = !(availableReactionsResult instanceof Promise) && peerAvailableReactionsResult.cached;\n    const renderPromise = callbackifyAll([\n      peerAvailableReactionsResult.result,\n      availableReactionsResult\n    ], async([peerAvailableReactions, availableReactions]) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(peerAvailableReactions.type === 'chatReactionsNone') {\n        return;\n      }\n\n      this.reactions = peerAvailableReactions.reactions;\n      // At reactions_uniq_max the message can take no new distinct reaction, so hide the\n      // custom-emoji search/packs (like tdesktop/iOS/Android) — the grid is already narrowed\n      // to the present kinds; only piling onto those stays possible.\n      this.noPacks = this.noSearch = peerAvailableReactions.type !== 'chatReactionsAll' || !!peerAvailableReactions.atUniqCap;\n      return this.renderReactions(peerAvailableReactions, availableReactions);\n    });\n\n    return [cached, renderPromise] as const;\n  }\n\n  private async prepareEffects() {\n    const middleware = this.middlewareHelper.get();\n    const availableEffects = await this.managers.acknowledged.appReactionsManager.getAvailableEffects();\n    const {cached} = availableEffects;\n    const renderPromise = callbackify(\n      availableEffects.result,\n      async(availableEffects) => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.freeCustomEmoji = new Set(\n          availableEffects\n          .filter((availableEffect) => !availableEffect.pFlags.premium_required)\n          .map((availableEffect) => availableEffect.effect_sticker_id)\n        );\n\n        this.noPacks = true;\n\n        return this.renderEffects(availableEffects);\n      }\n    );\n\n    return [cached, renderPromise] as const;\n  }\n\n  public async init(message?: Message.message | Message.messageService) {\n    let cached: boolean, renderPromise: Promise<() => void>;\n    if(this.isEffects) {\n      [cached, renderPromise] = await this.prepareEffects();\n    } else {\n      [cached, renderPromise] = await this.prepareReactions(message);\n    }\n\n    if(cached) {\n      await renderPromise;\n    }\n\n    renderPromise.then((callback) => {\n      if(!callback) {\n        return;\n      }\n\n      if(cached) {\n        callback();\n      } else {\n        fastRaf(callback);\n      }\n    });\n\n    this.inited = true;\n  }\n\n  public cleanup() {\n    this.middlewareHelper.clean();\n    // this.scrollable.removeListeners();\n    this.reactionsMap.clear();\n    animationIntersector.setOverrideIdleGroup(this.animationGroup, false);\n    animationIntersector.checkAnimations(true, this.animationGroup, true);\n  }\n\n  // private onScroll = () => {\n  //   this.reactionsMap.forEach((players, div) => {\n  //     this.onScrollProcessItem(div, players);\n  //   });\n  // };\n\n  private reactionToDocId = (reaction: Reaction) => {\n    if(reaction._ === 'reactionPaid') return PAID_REACTION_EMOJI_DOCID;\n    let docId = (reaction as Reaction.reactionCustomEmoji).document_id;\n    if(!docId) {\n      const availableReaction = this.availableReactions.find((_reaction) => _reaction.reaction === (reaction as Reaction.reactionEmoji).emoticon);\n      docId = availableReaction.select_animation.id;\n    }\n\n    return docId;\n  };\n\n  private reactionsToDocIds = (reactions: Reaction[]) => {\n    return reactions.map(this.reactionToDocId);\n  };\n\n  private loadTags = () => {\n    const reactionsPromise = this.managers.appReactionsManager.getTagReactions()\n    .then(this.reactionsToDocIds);\n    return [reactionsPromise];\n  };\n\n  private loadEffects = () => {\n    const reactionsPromise = this.managers.appReactionsManager.getAvailableEffects()\n    .then((availableEffects) => {\n      return availableEffects.filter((availableEffect) => {\n        return !!availableEffect.effect_animation_id;\n      }).map((availableEffect) => availableEffect.effect_sticker_id);\n    }) as Promise<DocId[]>;\n    return [reactionsPromise];\n  };\n\n  private loadReactions = () => {\n    const topReactionsPromise = Promise.resolve(this.reactions)\n    // const topReactionsPromise = this.managers.appReactionsManager.getTopReactions()\n    .then(this.reactionsToDocIds);\n\n    const allRecentReactionsPromise = this.managers.appReactionsManager.getRecentReactions()\n    .then(this.reactionsToDocIds);\n\n    const topReactionsSlicedPromise = topReactionsPromise.then((docIds) => this.noPacks ? docIds : docIds.slice(0, 16));\n\n    const recentReactionsPromise = this.noPacks ? undefined : Promise.all([\n      topReactionsPromise,\n      allRecentReactionsPromise,\n      topReactionsSlicedPromise\n    ]).then(([topDocIds, recentDocIds, topSlicedDocIds]) => {\n      // filter recent reactions and add left top reactions\n      recentDocIds = recentDocIds.filter((docId) => !topSlicedDocIds.includes(docId));\n      recentDocIds.push(...topDocIds.slice(16));\n      return filterUnique(recentDocIds);\n    });\n\n    return [topReactionsSlicedPromise, recentReactionsPromise].filter(Boolean);\n  };\n\n  private onMoreClick = (e: MouseEvent) => {\n    cancelEvent(e);\n\n    const canShrink = this.noPacks && this.noSearch;\n\n    const emojiTab = new EmojiTab({\n      noRegularEmoji: true,\n      noPacks: this.noPacks,\n      noSearch: this.noSearch,\n      managers: this.managers,\n      mainSets: this.isTags ? this.loadTags : (this.isEffects ? this.loadEffects : this.loadReactions),\n      additionalLocalStickerSet: this.isEffects ? async() => {\n        const availableEffects = await this.managers.appReactionsManager.getAvailableEffects();\n        return (await this.splitAvailableEffects(availableEffects)).localStickerSet;\n      } : undefined,\n      onClick: async(emoji) => {\n        if(emoji.docId && emoji.emoji) {\n          const availableReactions = await apiManagerProxy.getAvailableReactions();\n          const hasNativeReaction = availableReactions.find((_reaction) => _reaction.select_animation?.id === emoji.docId);\n          if(hasNativeReaction) {\n            emoji.emoji = hasNativeReaction.reaction;\n            delete emoji.docId;\n          }\n        }\n\n        let reaction: Reaction;\n        if(emoji.docId === PAID_REACTION_EMOJI_DOCID) {\n          reaction = {_: 'reactionPaid'};\n        } else if(emoji.docId) {\n          reaction = {\n            _: 'reactionCustomEmoji',\n            document_id: emoji.docId\n          };\n        } else {\n          reaction = {\n            _: 'reactionEmoji',\n            emoticon: cleanEmoji(emoji.emoji) // * heart can be different, like '❤' and '❤️'\n          };\n        }\n\n        deferred.resolve(reaction);\n        emoticonsDropdown.hideAndDestroy();\n      },\n      freeCustomEmoji: this.freeCustomEmoji,\n      onReady: () => {\n        const element = emoticonsDropdown.getElement();\n        // element.style.setProperty('--width', element.offsetWidth + 'px');\n        if(canShrink) {\n          const container = element.querySelector<HTMLElement>('.emoticons-categories-container');\n          element.style.setProperty('--height', container.offsetHeight + 'px');\n        }\n      },\n      searchFetcher: this.isEffects ? async(q) => {\n        const availableEffects = await this.managers.appReactionsManager.searchAvailableEffects({q});\n        return this.splitAvailableEffects(availableEffects);\n      } : async(q) => {\n        const emojis = await this.managers.appEmojiManager.prepareAndSearchEmojis({q, limit: Infinity, minChars: 1, addCustom: true});\n        return {\n          emojis: emojis.filter((emoji) => {\n            if(!emoji.docId) {\n              if(this.availableReactions) {\n                return this.availableReactions.some((availableReaction) => availableReaction.reaction === emoji.emoji);\n              }\n\n              return false;\n            }\n\n            return true;\n          })\n        };\n      },\n      groupFetcher: this.isEffects ? async(emojiGroup) => {\n        const availableEffects = await this.managers.appReactionsManager.searchAvailableEffects({emoticon: (emojiGroup as EmojiGroup.emojiGroup).emoticons});\n        return this.splitAvailableEffects(availableEffects);\n      } : undefined,\n      showLocks: this.isEffects\n    });\n\n    const emoticonsDropdown = new EmoticonsDropdown({\n      tabsToRender: [emojiTab],\n      // Mount into the active app window's body (a function so it resolves lazily at open time):\n      // while the client is popped into a Document PiP window the reactions menu lives there, so a\n      // hardcoded main-`document.body` would render this emoji picker into the now-background tab.\n      customParentElement: getOverlayRoot,\n      getOpenPosition: () => this.getOpenPosition(!this.noPacks)\n    });\n\n    if(canShrink) {\n      emoticonsDropdown.getElement().classList.add('shrink');\n    }\n\n    if(this.isEffects) {\n      emoticonsDropdown.getElement().classList.add('smaller');\n    }\n\n    const deferred = deferredPromise<Reaction>();\n    this.onFinish(deferred);\n    emoticonsDropdown.addEventListener('closed', () => {\n      deferred.resolve(undefined);\n      emoticonsDropdown.hideAndDestroy();\n    });\n\n    emoticonsDropdown.onButtonClick();\n  };\n\n  private async splitAvailableEffects(availableEffects: AvailableEffect[]): ReturnType<EmojiTab['searchFetcher']> {\n    const [stickers, customEmojis] = partition(availableEffects, (availableEffect) => !availableEffect.effect_animation_id);\n    const docIds = stickers.map((availableEffect) => availableEffect.effect_sticker_id);\n    const docs = await Promise.all(docIds.map((docId) => this.managers.appDocsManager.getDoc(docId)));\n    return {\n      emojis: customEmojis.map((availableEffect) => {\n        return {\n          emoji: '',\n          docId: availableEffect.effect_sticker_id\n        }\n      }),\n      localStickerSet: {\n        title: 'StickerEffects',\n        stickers: docs\n      }\n    };\n  }\n\n  private canUseAnimations() {\n    return liteMode.isAvailable('animations') && liteMode.isAvailable('stickers_chat') && !IS_MOBILE;\n  }\n\n  private async renderReaction(reaction: Reaction, availableReaction?: AvailableReaction) {\n    const reactionDiv = document.createElement('div');\n    reactionDiv.classList.add(REACTION_CLASS_NAME);\n\n    const scaleContainer = document.createElement('div');\n    scaleContainer.classList.add(REACTION_CLASS_NAME + '-scale');\n\n    const appearWrapper = document.createElement('div');\n    let selectWrapper: HTMLElement;;\n    appearWrapper.classList.add(REACTION_CLASS_NAME + '-appear');\n\n    if(this.canUseAnimations()) {\n      selectWrapper = document.createElement('div');\n      selectWrapper.classList.add(REACTION_CLASS_NAME + '-select', 'hide');\n    }\n\n    const players: ChatReactionsMenuPlayers = {\n      selectWrapper,\n      appearWrapper,\n      reaction\n    };\n    this.reactionsMap.set(reactionDiv, players);\n\n    const middleware = this.middlewareHelper.get();\n\n    const hoverScale = IS_TOUCH_SUPPORTED || !SCALE_ON_HOVER ? 1 : 1.25;\n    const size = REACTION_SIZE * hoverScale;\n\n    const loadPromises: Promise<any>[] = [];\n    const options = {\n      width: size,\n      height: size,\n      skipRatio: 1,\n      needFadeIn: false,\n      withThumb: false,\n      group: this.animationGroup,\n      middleware,\n      loadPromises\n    };\n\n    const canUseAnimations = this.canUseAnimations();\n    const isPaidReaction = reaction._ === 'reactionPaid';\n\n    this.container.append(reactionDiv);\n    if(isPaidReaction && !canUseAnimations) {\n      appearWrapper.append(StarsStar() as HTMLElement);\n    } else if(isPaidReaction && canUseAnimations) {\n      const promise = lottieLoader.loadAnimationAsAsset({\n        container: appearWrapper,\n        loop: false,\n        autoplay: true,\n        width: size,\n        height: size,\n        skipRatio: 1,\n        middleware,\n        group: this.animationGroup\n      }, 'StarReactionAppear').then((player) => {\n        players.appear = player;\n\n        const selectLoadPromise = lottieLoader.loadAnimationAsAsset({\n          container: selectWrapper,\n          loop: false,\n          autoplay: false,\n          ...options\n        }, 'StarReactionSelect');\n\n        player.addEventListener('enterFrame', (frameNo) => {\n          if(player.maxFrame === frameNo) {\n            selectLoadPromise.then((selectPlayer) => {\n              assumeType<RLottiePlayer>(selectPlayer);\n              appearWrapper.classList.add('hide');\n              selectWrapper.classList.remove('hide');\n\n              players.select = selectPlayer;\n            }, noop);\n          }\n        });\n      });\n\n      loadPromises.push(promise);\n    } else if(!canUseAnimations || !availableReaction) {\n      delete options.needFadeIn;\n      delete options.withThumb;\n\n      const wrap = () => {\n        wrapSticker({\n          doc,\n          div: appearWrapper,\n          liteModeKey: false,\n          play: availableReaction === undefined ? true : undefined,\n          ...options\n        });\n      };\n\n      let doc = availableReaction?.static_icon, delay = false;\n      if(!doc) {\n        const result = await this.managers.acknowledged.appEmojiManager.getCustomEmojiDocument((reaction as Reaction.reactionCustomEmoji).document_id);\n        if(result.cached) {\n          doc = await result.result;\n        } else {\n          delete options.loadPromises;\n          delay = true;\n          result.result.then((_doc) => (doc = _doc, wrap()));\n        }\n      }\n\n      if(!delay) {\n        wrap();\n      }\n    } else {\n      let isFirst = true;\n      wrapSticker({\n        doc: availableReaction.appear_animation,\n        div: appearWrapper,\n        play: true,\n        liteModeKey: false,\n        ...options\n      }).then(({render}) => render).then((player) => {\n        assumeType<RLottiePlayer>(player);\n\n        players.appear = player;\n\n        player.addEventListener('enterFrame', (frameNo) => {\n          if(player.maxFrame === frameNo) {\n            selectLoadPromise.then((selectPlayer) => {\n              assumeType<RLottiePlayer>(selectPlayer);\n              appearWrapper.classList.add('hide');\n              selectWrapper.classList.remove('hide');\n\n              if(isFirst) {\n                players.select = selectPlayer;\n                isFirst = false;\n              }\n            }, noop);\n          }\n        });\n      }, noop);\n\n      const selectLoadPromise = wrapSticker({\n        doc: availableReaction.select_animation,\n        div: selectWrapper,\n        liteModeKey: false,\n        ...options\n      }).then(({render}) => render).then((player) => {\n        assumeType<RLottiePlayer>(player);\n\n        return lottieLoader.waitForFirstFrame(player);\n      }).catch(noop);\n    }\n\n    scaleContainer.append(appearWrapper);\n    selectWrapper && scaleContainer.append(selectWrapper);\n    reactionDiv.append(scaleContainer);\n    // this.scrollable.append(reactionDiv);\n\n    return Promise.all(loadPromises);\n  }\n\n  // private onScrollProcessItem(div: HTMLElement, players: ChatReactionsMenuPlayers) {\n  //   // return;\n\n  //   const scaleContainer = div.firstElementChild as HTMLElement;\n  //   const visibleRect = getVisibleRect(div, this.scrollable.container);\n  //   let transform: string;\n  //   if(!visibleRect) {\n  //     if(!players.appearWrapper.classList.contains('hide') || !players.appear) {\n  //       return;\n  //     }\n\n  //     if(players.select) {\n  //       players.select.stop();\n  //     }\n\n  //     players.appear.stop();\n  //     players.appear.autoplay = true;\n  //     players.appearWrapper.classList.remove('hide');\n  //     players.selectWrapper.classList.add('hide');\n\n  //     transform = '';\n  //   } else if(visibleRect.overflow.left || visibleRect.overflow.right) {\n  //     const diff = Math.abs(visibleRect.rect.left - visibleRect.rect.right);\n  //     const scale = Math.min(diff ** 2 / REACTION_CONTAINER_SIZE ** 2, 1);\n\n  //     transform = 'scale(' + scale + ')';\n  //   } else {\n  //     transform = '';\n  //   }\n\n  //   if(CAN_USE_TRANSFORM) {\n  //     scaleContainer.style.transform = transform;\n  //   }\n  // }\n\n  private onMouseMove = (e: MouseEvent) => {\n    const reactionDiv = findUpClassName(e.target, REACTION_CLASS_NAME);\n    if(!reactionDiv) {\n      return;\n    }\n\n    const players = this.reactionsMap.get(reactionDiv);\n    if(!players) {\n      return;\n    }\n\n    // do not play select animation when appearing\n    if(!players.appear?.paused) {\n      return;\n    }\n\n    const player = players.select;\n    if(!player) {\n      return;\n    }\n\n    if(player.paused) {\n      player.autoplay = true;\n      player.restart();\n    }\n  };\n}\n","export default function isTargetAnInput(target: HTMLElement) {\n  return !!target && (target.tagName === 'INPUT' && !['checkbox', 'radio'].includes((target as HTMLInputElement).type)) || target.isContentEditable;\n}\n","import {StoryItem, MediaArea} from '@layer';\n\nexport default function getStoryRepostInfo(story: StoryItem.storyItem) {\n  const fwdFrom = story.fwd_from;\n  let mediaAreaChannelPost: MediaArea.mediaAreaChannelPost;\n  if(!fwdFrom) {\n    mediaAreaChannelPost = (story.media_areas || []).find((mediaArea) => mediaArea._ === 'mediaAreaChannelPost') as MediaArea.mediaAreaChannelPost;\n    if(!mediaAreaChannelPost) {\n      return;\n    }\n  }\n\n  return {fwdFrom, mediaAreaChannelPost};\n}\n","import showFeatureDetailsPopup, {FeatureDetailsButton} from '@components/popups/featureDetails';\nimport {i18n} from '@lib/langPack';\nimport {useAppConfig} from '@stores/appState';\nimport {wrapStoriesStealthModeDuration} from '@components/wrappers/wrapDuration';\nimport usePremium from '@stores/premium';\nimport PopupPremium from '@components/popups/premium';\nimport rootScope from '@lib/rootScope';\nimport tsNow from '@helpers/tsNow';\nimport {slowModeTimer} from '@components/chat/utils';\nimport {onCleanup} from 'solid-js';\nimport createFeatureDetailsIconSticker from '@components/featureDetailsIconSticker';\n\nexport default async function showStoriesStealthModePopup(props: {\n  onActivate?: () => void,\n  onClose?: () => void\n} = {}) {\n  const appConfig = useAppConfig();\n  const isPremium = usePremium();\n\n  const stealthMode = await rootScope.managers.appStoriesManager.getStealthMode();\n  const getLeftCooldown = () => (stealthMode.cooldown_until_date || 0) - tsNow(true);\n\n  const getButton = (): FeatureDetailsButton => {\n    if(!isPremium()) {\n      return {\n        text: i18n('Stories.StealthMode.Unlock'),\n        onClick: () => {\n          PopupPremium.show({feature: 'stories'});\n        }\n      };\n    } else if(getLeftCooldown() > 0) {\n      const {element, dispose} = slowModeTimer(getLeftCooldown);\n      onCleanup(dispose);\n      return {\n        text: i18n('Stories.StealthMode.Cooldown', [element])\n      };\n    } else {\n      return {\n        text: i18n('Stories.StealthMode.Button'),\n        onClick: async() => {\n          const needToActivate = (stealthMode.active_until_date || 0) <= tsNow(true);\n          if(needToActivate) {\n            await rootScope.managers.appStoriesManager.activateStealthMode();\n          }\n\n          props.onActivate?.();\n        }\n      };\n    }\n  };\n\n  showFeatureDetailsPopup({\n    rows: [\n      {\n        icon: 'backward_5',\n        title: i18n('Stories.StealthMode.Row1.Title'),\n        subtitle: i18n('Stories.StealthMode.Row1.Subtitle', [\n          wrapStoriesStealthModeDuration(appConfig.stories_stealth_past_period)\n        ])\n      },\n      {\n        icon: 'forward_25',\n        title: i18n('Stories.StealthMode.Row2.Title'),\n        subtitle: i18n('Stories.StealthMode.Row2.Subtitle', [\n          wrapStoriesStealthModeDuration(appConfig.stories_stealth_future_period)\n        ])\n      }\n    ],\n    sticker: {\n      element: createFeatureDetailsIconSticker('eye2', 'background-gradient-stories')\n    },\n    title: i18n('Stories.StealthMode.Title'),\n    subtitle: i18n('Stories.StealthMode.Subtitle'),\n    get buttons() {\n      return [getButton()];\n    },\n    onClose: props.onClose\n  });\n}\n","import {StoryItem} from '../../layer';\nimport rootScope from '../../lib/rootScope';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '../chat/paidMessagesInterceptor';\nimport {showSharingPickerPopup} from '../popups/pickUser';\n\nexport function handleShareStory(options: {\n  story: StoryItem,\n  peerId: PeerId,\n  onClose?: () => void\n  onSend?: (toPeerId: PeerId) => void\n}) {\n  showSharingPickerPopup({\n    onSelect: async(chosen) => {\n      const {peerId, monoforumThreadId} = chosen[0];\n      const storyPeerId = options.peerId;\n\n      const preparedPaymentResult = await PaidMessagesInterceptor.prepareStarsForPayment({messageCount: 1, peerId});\n      if(preparedPaymentResult === PAYMENT_REJECTED) throw new Error();\n\n      const inputPeer = await rootScope.managers.appPeersManager.getInputPeerById(storyPeerId);\n      rootScope.managers.appMessagesManager.sendOther({\n        peerId,\n        inputMedia: {\n          _: 'inputMediaStory',\n          id: options.story.id,\n          peer: inputPeer\n        },\n        confirmedPaymentResult: preparedPaymentResult,\n        replyToMonoforumPeerId: monoforumThreadId\n      });\n\n      options.onSend?.(peerId);\n    },\n    chatRightsActions: ['send_media'],\n    onCloseAfterTimeout: options.onClose\n  });\n}\n","/* @refresh reload */\n\nimport {animateSingle, cancelAnimationByKey} from '@helpers/animation';\nimport {bindActiveWindowListener, getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport overlayCounter from '@helpers/overlayCounter';\nimport throttle from '@helpers/schedulers/throttle';\nimport classNames from '@helpers/string/classNames';\nimport windowSize from '@helpers/windowSize';\nimport {Document, DocumentAttribute, GeoPoint, MediaArea, MessageMedia, Reaction, StoryItem, StoryView, User, Chat as MTChat, AvailableReaction, MessageEntity, StoriesStealthMode} from '@layer';\nimport animationIntersector from '@components/animationIntersector';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport PeerTitle from '@components/peerTitle';\nimport SwipeHandler from '@components/swipeHandler';\nimport styles from '@components/stories/viewer.module.scss';\nimport {createSignal, createEffect, JSX, For, Accessor, onCleanup, createMemo, mergeProps, splitProps, untrack, on, getOwner, runWithOwner, createRoot, ParentProps, Signal, onMount, Setter, createReaction, Show, createRenderEffect} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport {assign, Portal} from 'solid-js/web';\nimport rootScope from '@lib/rootScope';\nimport {Middleware} from '@helpers/middleware';\nimport useIsCrmSuperAdmin from '@stores/crmRole';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport wrapMessageEntities from '@lib/richTextProcessor/wrapMessageEntities';\nimport tsNow from '@helpers/tsNow';\nimport {LangPackKey, i18n, joinElementsWith} from '@lib/langPack';\nimport formatDuration, {DurationType} from '@helpers/formatDuration';\nimport {easeOutCubicApply} from '@helpers/easing/easeOutCubic';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport {onMediaCaptionClick} from '@components/appMediaViewer';\nimport InputFieldAnimated from '@components/inputFieldAnimated';\nimport ChatInput from '@components/chat/input';\nimport appImManager from '@lib/appImManager';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from '@components/chat/chatType';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport emoticonsDropdown from '@components/emoticonsDropdown';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\nimport debounce from '@helpers/schedulers/debounce';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {formatDateAccordingToTodayNew, formatFullSentTime} from '@helpers/date';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport {AvatarNew, avatarNew} from '@components/avatarNew';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport {SERVICE_PEER_ID} from '@appManagers/constants';\nimport idleController from '@helpers/idleController';\nimport OverlayClickHandler from '@helpers/overlayClickHandler';\nimport getStoryPrivacyType, {StoryPrivacyType} from '@appManagers/utils/stories/privacyType';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport StackedAvatars from '@components/stackedAvatars';\nimport PopupElement from '@components/popups';\nimport {processDialogElementForReaction} from '@components/popups/reactedList';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport focusInput from '@helpers/dom/focusInput';\nimport {wrapStoryMedia} from '@components/stories/preview';\nimport {StoriesContextPeerState, useStories, StoriesProvider} from '@components/stories/store';\nimport createUnifiedSignal from '@helpers/solid/createUnifiedSignal';\nimport setBlankToAnchor from '@lib/richTextProcessor/setBlankToAnchor';\nimport liteMode from '@helpers/liteMode';\nimport Icon from '@components/icon';\nimport {ChatReactionsMenu} from '@components/chat/reactionsMenu';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport ReactionElement from '@components/chat/reaction';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport wrapSticker from '@components/wrappers/sticker';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport isTargetAnInput from '@helpers/dom/isTargetAnInput';\nimport {setQuizHint} from '@components/quizHint';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {resolveFirst} from '@solid-primitives/refs';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport formatNumber from '@helpers/number/formatNumber';\nimport callbackify from '@helpers/callbackify';\nimport {dispatchHeavyAnimationEvent} from '@hooks/useHeavyAnimationCheck';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport wrapReply from '@components/wrappers/reply';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport appSidebarRight from '@components/sidebarRight';\nimport AppStatisticsTab from '@components/sidebarRight/tabs/statistics';\nimport getStoryRepostInfo from '@appManagers/utils/stories/repostInfo';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport {Transition} from 'solid-transition-group';\nimport {TransitionGroup} from '@helpers/solid/transitionGroup';\nimport makeGoogleMapsUrl from '@helpers/makeGoogleMapsUrl';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport showTooltip from '@components/tooltip';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport {showStoryReport} from '@components/popups/reportAd';\nimport {useAppSettings} from '@stores/appSettings';\nimport showStoriesStealthModePopup from '@components/popups/storiesStealthMode';\nimport {useAppConfig} from '@stores/appState';\nimport {wrapStoriesStealthModeDuration} from '@components/wrappers/wrapDuration';\nimport {handleShareStory} from './share';\nimport createListenerSetter from '@helpers/solid/createListenerSetter';\n\nexport const STORY_DURATION = 5e3;\nconst STORY_HEADER_AVATAR_SIZE = 32;\nconst STORY_SCALE_SMALL = 0.33;\nconst STORIES_PRESERVE = 2;\nconst STORIES_PRESERVE_HIDDEN = 2;\nconst STORY_REPOST_ICON: Icon = 'storyrepost';\nlet CHANGELOG_PEER_ID = SERVICE_PEER_ID;\n\nrootScope.addEventListener('app_config', (appConfig) => {\n  const userId = appConfig.stories_changelog_user_id;\n  CHANGELOG_PEER_ID = userId ? userId.toPeerId(false) : SERVICE_PEER_ID;\n});\n\nconst x = new OverlayClickHandler(undefined, true);\n\nconst StorySlides = (props: {\n  state: StoriesContextPeerState,\n  index: Accessor<number>,\n  currentStory: Accessor<StoryItem>,\n  splitByDays?: boolean\n}) => {\n  let storyIndex: Accessor<number>, storiesForSlides: Accessor<StoryItem[]>;\n  if(props.splitByDays) {\n    const getStoryDateTimestamp = (storyItem: StoryItem.storyItem) => {\n      const timestamp = storyItem.date;\n      const date = new Date(timestamp * 1000);\n      date.setHours(0, 0, 0);\n      return date.getTime();\n    };\n\n    const storiesSplittedByDays = createMemo(() => {\n      const stories = props.state.stories;\n      const days: Record<number, StoryItem[]> = {};\n      (stories as StoryItem.storyItem[]).forEach((story) => {\n        const dateTimestamp = getStoryDateTimestamp(story);\n        (days[dateTimestamp] ??= []).push(story);\n      });\n      return days;\n    });\n\n    storiesForSlides = createMemo(() => {\n      const days = storiesSplittedByDays();\n      const story = props.currentStory();\n      const dateTimestamp = getStoryDateTimestamp(story as StoryItem.storyItem);\n      return days[dateTimestamp];\n    });\n\n    storyIndex = createMemo(() => {\n      const story = props.currentStory();\n      const stories = storiesForSlides();\n      // return props.state.index;\n      return stories.indexOf(story);\n    });\n  } else {\n    storiesForSlides = () => props.state.stories;\n    storyIndex = () => props.state.index;\n  }\n\n  const slides = (\n    <For each={storiesForSlides()}>\n      {(_, i) => <StorySlide {...mergeProps(props, {slideIndex: i, storyIndex})} />}\n    </For>\n  );\n\n  return slides;\n};\n\nconst StorySlide = (props: {\n  slideIndex: Accessor<number>,\n  state: StoriesContextPeerState,\n  storyIndex: Accessor<number>,\n  index: Accessor<number>\n}) => {\n  const [progress, setProgress] = createSignal(0);\n  const [stories] = useStories();\n\n  const calculateAndSetProgress = () => {\n    const elapsedTime = Date.now() - stories.startTime;\n    const progress = elapsedTime / stories.storyDuration;\n    setProgress(progress);\n  };\n\n  const onTick = () => {\n    if(\n      stories.peer !== props.state ||\n      props.storyIndex() !== props.slideIndex() ||\n      stories.paused\n    ) {\n      onPause();\n      return false;\n    }\n\n    // if(stories.paused) {\n    //   return true;\n    // }\n\n    calculateAndSetProgress();\n    return true;\n  };\n\n  const onPause = () => {\n    cancelAnimationByKey(ret);\n  };\n\n  const onPlay = () => {\n    animateSingle(onTick, ret);\n  };\n\n  createEffect(() => { // on peer change\n    if(stories.peer !== props.state) {\n      onPause();\n      return;\n    }\n\n    createEffect(on( // on story change\n      () => [props.storyIndex(), props.slideIndex()],\n      ([storyIndex, slideIndex]) => {\n        const isActive = storyIndex === slideIndex;\n        if(isActive) {\n          setProgress(undefined);\n\n          createEffect(() => { // on story toggle\n            if(stories.paused || stories.buffering) {\n              onPause();\n            } else {\n              onPlay();\n            }\n          });\n        } else {\n          onPause();\n          setProgress(storyIndex > slideIndex ? 1 : undefined);\n        }\n      })\n    );\n  });\n\n  const ret = (\n    <div\n      class={styles.ViewerStorySlidesSlide}\n      // classList={{[styles.active]: index() > slideIndex()}}\n      style={progress() !== undefined ? {'--progress': Math.min(100, progress() * 100) + '%'} : {}}\n    />\n  );\n\n  return ret;\n};\n\nconst DEFAULT_REACTION_EMOTICON = '❤';\nconst isDefaultReaction = (reaction: Reaction) => (reaction as Reaction.reactionEmoji)?.emoticon === DEFAULT_REACTION_EMOTICON;\n\nconst StoryInput = (props: {\n  state: StoriesContextPeerState,\n  currentStory: Accessor<StoryItem>,\n  isActive: Accessor<boolean>,\n  focusedSignal: Signal<boolean>,\n  inputEmptySignal: Signal<boolean>,\n  inputMenuOpenSignal: Signal<boolean>,\n  isPublic: Accessor<boolean>,\n  sendReaction: StorySendReaction,\n  shareStory: () => void,\n  reaction: Accessor<JSX.Element>,\n  onShareButtonClick: (e: MouseEvent, listenTo: HTMLElement) => void,\n  onMessageSent: () => void,\n  setInputReady: Setter<boolean>,\n  isFull: Accessor<boolean>\n}) => {\n  const [stories, actions] = useStories();\n  const [focused, setFocused] = props.focusedSignal;\n  const [inputEmpty, setInputEmpty] = props.inputEmptySignal;\n  const [inputMenuOpen, setInputMenuOpen] = props.inputMenuOpenSignal;\n  const [recording, setRecording] = createSignal(false);\n  const middlewareHelper = createMiddleware();\n  const middleware = middlewareHelper.get();\n\n  const chat = new Chat(appImManager, rootScope.managers, false, {elements: true, sharedMedia: true});\n  chat.setType(ChatType.Stories);\n  chat.isStandalone = true;\n\n  const onReactionClick = async() => {\n    const story = props.currentStory() as StoryItem.storyItem;\n    const isNewReaction = !story.sent_reaction;\n    const reaction: Reaction = !isNewReaction ? undefined : {_: 'reactionEmoji', emoticon: DEFAULT_REACTION_EMOTICON};\n    props.sendReaction({reaction, target: btnReactionEl});\n  };\n\n  let btnReactionEl: HTMLButtonElement;\n  const btnReaction = (\n    <ButtonIconTsx\n      ref={btnReactionEl}\n      onClick={onReactionClick}\n      tabIndex={-1}\n      class=\"btn-circle btn-reaction chat-input-secondary-button chat-secondary-button\"\n      noRipple={true}\n    >\n      {props.reaction()}\n    </ButtonIconTsx>\n  );\n\n  const input = chat.input = new ChatInput(chat, appImManager, rootScope.managers, 'stories-input');\n  input.noRipple = true;\n  input.btnReaction = btnReactionEl;\n  input.excludeParts = {\n    replyMarkup: true,\n    scheduled: true,\n    downButton: true,\n    reply: true,\n    forwardOptions: true,\n    mentionButton: true,\n    attachMenu: true,\n    commandsHelper: true,\n    botCommands: true,\n    emoticons: IS_MOBILE\n  };\n  input.globalMentions = true;\n  input.getMiddleware = (...args) => middleware.create().get(...args);\n\n  // const onMouseDown = (e: MouseEvent) => {\n  //   if(\n  //     focused() &&\n  //     !findUpClassName(e.target, styles.ViewerStoryPrivacy) &&\n  //     !findUpClassName(e.target, 'btn-icon') &&\n  //     !findUpClassName(e.target, styles.small) &&\n  //     !findUpAsChild(e.target as HTMLElement, input.emoticonsDropdown.getElement())\n  //   ) {\n  //     document.addEventListener('click', cancelEvent, {capture: true, once: true});\n  //   }\n\n  //   onFocusChange(false);\n  // };\n\n  const onClick = (e: MouseEvent) => {\n    // if(!inputEmpty()) {\n    //   return;\n    // }\n\n    const target = e.target as HTMLElement;\n    const good = !findUpClassName(target, styles.ViewerStoryReactions) && (\n      findUpClassName(target, styles.ViewerStory) ||\n      target.classList.contains(styles.Viewer)\n    );\n    if(!good) {\n      return;\n    }\n\n    cancelEvent(e);\n    setFocused(false);\n  };\n\n  onCleanup(() => {\n    if(navigationItem) {\n      appNavigationController.removeItem(navigationItem);\n      navigationItem = undefined;\n    }\n  });\n\n  let navigationItem: NavigationItem;\n  createEffect(\n    on(\n      () => focused(),\n      (focused) => {\n        if(focused) {\n          playAfterFocus = untrack(() => !stories.paused);\n          // document.addEventListener('mousedown', onMouseDown, {capture: true, once: true});\n          getAppWindow().document.addEventListener('click', onClick, {capture: true});\n          appNavigationController.pushItem(navigationItem = {\n            type: 'stories-focus',\n            onPop: () => {\n              setFocused(false);\n            }\n          });\n        } else {\n          // document.removeEventListener('mousedown', onMouseDown, {capture: true});\n          getAppWindow().document.removeEventListener('click', onClick, {capture: true});\n          appNavigationController.removeItem(navigationItem);\n          navigationItem = undefined;\n        }\n\n        actions.toggle(focused ? false : playAfterFocus);\n        input.freezeFocused(focused);\n        input.chatInput.classList.toggle('is-focused', focused);\n        // input.setShrinking(!focused);\n      },\n      {defer: true}\n    )\n  );\n\n  let playAfterFocus = false;\n  input.onFocusChange = (_focused: boolean) => {\n    if(input.emoticonsDropdown.isActive()) {\n      return;\n    }\n\n    if(!_focused) {\n      return;\n    }\n\n    setFocused(_focused);\n  };\n\n  let playAfter = false;\n  const onMenuToggle = (open: boolean) => {\n    if(open) {\n      playAfter = !stories.paused;\n    }\n\n    actions.toggle(open ? false : playAfter);\n    setInputMenuOpen(open);\n  };\n  input.onMenuToggle/*  = input.onRecording */ = onMenuToggle;\n  input.construct();\n  input.constructPeerHelpers();\n  // input.setShrinking(true);\n  // input.chatInput.classList.add(styles.hideOnSmall);\n  // input.rowsWrapper.classList.add('night');\n  input.messageInput.dataset.textColor = 'white';\n\n  createEffect(() => {\n    if(props.isActive()) {\n      const onOpen = (): void => (onMenuToggle(true)/* , setFocused(true) */, undefined);\n      const onClose = (): void => (onMenuToggle(false)/* , setFocused(false) */, undefined);\n      emoticonsDropdown.addEventListener('open', onOpen);\n      emoticonsDropdown.addEventListener('close', onClose);\n      emoticonsDropdown.chatInput = input;\n\n      onCleanup(() => {\n        emoticonsDropdown.removeEventListener('open', onOpen);\n        emoticonsDropdown.removeEventListener('close', onClose);\n      });\n    }\n  });\n\n  createEffect(() => {\n    input.chatInput.classList.toggle('is-private', !props.isPublic());\n    input.setCanForwardStory(props.isPublic());\n  });\n\n  createEffect(() => {\n    const [_focused, _recording, isPublic] = [focused(), recording(), props.isPublic()];\n    const isReactionButtonVisible = !_focused;\n    const isMainButtonVisible = _focused ? true : isPublic;\n    const isRecordingButtonVisible = _recording;\n    const visibleButtons = Math.min(2, [\n      isReactionButtonVisible,\n      isMainButtonVisible,\n      isRecordingButtonVisible\n    ].reduce((acc, v) => acc + +v, 0));\n    const chatInputSize = 48;\n    const chatInputBtnSendMargin = 8;\n    const chatInputPadding = props.isFull() ? 8 : 0;\n    const focusOffset = props.isFull() ? 0 : 135;\n    const width = stories.width - (chatInputSize + chatInputBtnSendMargin) * visibleButtons + (_focused ? focusOffset : 0) - chatInputPadding * 2;\n    input.rowsWrapper.style.setProperty('width', width + 'px', 'important');\n    input.chatInput.classList.toggle('is-focused', _focused);\n  });\n\n  const owner = getOwner();\n\n  chat.peerId = props.state.peerId;\n  chat.onChangePeer({\n    peerId: chat.peerId,\n    type: ChatType.Stories\n  }, middlewarePromise(middleware)).then(() => {\n    if(!middleware()) return;\n    return chat.finishPeerChange({\n      peerId: chat.peerId,\n      middleware\n    });\n  }).then(() => {\n    if(!middleware()) return;\n    props.setInputReady(true);\n\n    runWithOwner(owner, () => {\n      createEffect(() => {\n        input.setReplyTo({\n          replyToStoryId: props.currentStory().id\n        });\n      });\n\n      createEffect(async() => {\n        JSON.stringify(stories.stealthMode); // * track every key change\n        chat.stealthMode = stories.stealthMode;\n        input.updateMessageInputPlaceholder(await input.getPlaceholderParams());\n      });\n    });\n  });\n\n  onCleanup(() => {\n    input.onFocusChange =\n      input.onFileSelection =\n      input.onMenuToggle =\n      input.onRecording =\n      input.onUpdateSendBtn =\n      input.onMessageSent2 =\n      input.forwardStoryCallback =\n      undefined;\n    middlewareHelper.destroy();\n    chat.destroy();\n  });\n\n  input.onFileSelection = (promise) => {\n    onMenuToggle(true);\n    promise.finally(() => {\n      onMenuToggle(false);\n    });\n  };\n\n  input.onUpdateSendBtn = (icon) => {\n    setInputEmpty(icon === 'record' || icon === 'forward');\n  };\n\n  input.onMessageSent2 = () => {\n    blurActiveElement();\n    setFocused(false);\n    props.onMessageSent();\n  };\n\n  input.forwardStoryCallback = (e) => {\n    props.onShareButtonClick(e, input.btnSendContainer);\n  };\n\n  input.onRecording = (recording) => {\n    setRecording(recording);\n  };\n\n  return input.chatInput;\n};\n\nconst JOINER = ' • ';\n\nconst renderStoryReaction = async(props: {\n  reaction: Reaction,\n  uReaction: ReturnType<typeof createUnifiedSignal<JSX.Element>>,\n  div: HTMLDivElement,\n  size: number,\n  textColor: string,\n  play: boolean\n}) => {\n  let doc: Document.document;\n  const {reaction, div, size, textColor, play, uReaction} = props;\n  const isCustomEmoji = reaction._ === 'reactionCustomEmoji';\n  const middleware = createMiddleware().get();\n  uReaction(null);\n  let availableReaction: MaybePromise<AvailableReaction>;\n  if(isCustomEmoji) {\n    const result = await rootScope.managers.acknowledged.appEmojiManager.getCustomEmojiDocument(reaction.document_id);\n    if(!middleware()) return;\n    if(!result.cached) {\n      uReaction();\n    }\n\n    doc = await result.result;\n    availableReaction = apiManagerProxy.getReaction(doc.stickerEmojiRaw);\n  } else {\n    const availableReactionsResult = apiManagerProxy.getAvailableReactions();\n    if(availableReactionsResult instanceof Promise) {\n      uReaction();\n    }\n    const availableReactions = await availableReactionsResult;\n    if(!middleware()) return;\n    availableReaction = availableReactions.find((availableReaction) => reactionsEqual(reaction, availableReaction));\n    doc = /* availableReaction.center_icon ??  */play ? availableReaction.select_animation : availableReaction.static_icon;\n  }\n\n  // preload animation\n  availableReaction && callbackify(availableReaction, (availableReaction) => {\n    if(availableReaction?.around_animation) {\n      appDownloadManager.downloadMedia({\n        media: availableReaction.around_animation\n      });\n    }\n  });\n\n  const loadPromises: Promise<any>[] = [];\n  await wrapSticker({\n    div,\n    doc,\n    width: size,\n    height: size,\n    play,\n    // isCustomEmoji,\n    textColor,\n    middleware,\n    loadPromises,\n    loop: play || undefined\n  });\n\n  await Promise.all(loadPromises);\n  if(!middleware()) return;\n  uReaction(div);\n};\n\nconst StoryMediaArea = (props: {\n  story: StoryItem.storyItem,\n  mediaArea: MediaArea,\n  isActive: Accessor<boolean>,\n  setTooltipCloseCallback: Setter<() => void>,\n  setReady: Setter<boolean>,\n  sendReaction: StorySendReaction,\n  close: (callback?: () => void) => void,\n}) => {\n  const [stories, actions] = useStories();\n  const {x, y, w, h, rotation} = props.mediaArea.coordinates;\n  // const rotation = 10;\n  // const w = 100 / stories.width * 100;\n  // const h = 100 / stories.height * 100;\n  const playingMemo = createMemo((prev) => prev || (props.isActive() && stories.startTime));\n  const [children, setChildren] = createSignal<JSX.Element>();\n  const isLocation = createMemo(() => props.mediaArea._ === 'mediaAreaGeoPoint' || props.mediaArea._ === 'mediaAreaVenue');\n  const isReaction = createMemo(() => props.mediaArea._ === 'mediaAreaSuggestedReaction');\n  const isPost = createMemo(() => props.mediaArea._ === 'mediaAreaChannelPost');\n  const isLink = createMemo(() => props.mediaArea._ === 'mediaAreaUrl');\n\n  const onLocationClick = async() => {\n    const geoPoint = (props.mediaArea as MediaArea.mediaAreaGeoPoint).geo as GeoPoint.geoPoint;\n    const href = makeGoogleMapsUrl(geoPoint);\n\n    const onAnchorClick = async(e: MouseEvent) => {\n      if(ignoreClickEvent) {\n        ignoreClickEvent = false;\n        return;\n      }\n\n      hasPopup = true;\n      cancelEvent(e);\n      try {\n        await confirmationPopup({\n          descriptionLangKey: 'Popup.OpenInGoogleMaps',\n          button: {\n            langKey: 'Open'\n          }\n        });\n      } catch(err) {\n        if(wasPlaying) {\n          actions.play();\n        }\n\n        return;\n      }\n\n      ignoreClickEvent = true;\n      a.click();\n    };\n\n    let a: HTMLAnchorElement, ignoreClickEvent = false, hasPopup: boolean;\n    (\n      <a\n        ref={a}\n        href={href}\n        onClick={onAnchorClick}\n      >\n        {i18n('StoryViewLocation')}\n      </a>\n    );\n    setBlankToAnchor(a);\n    const wasPlaying = !stories.paused;\n    actions.pause();\n    const {close} = showTooltip({\n      element: div,\n      vertical: 'top',\n      textElement: a,\n      centerVertically: !!rotation,\n      onClose: () => {\n        if(hasPopup) {\n          hasPopup = false;\n          return;\n        }\n\n        if(wasPlaying) {\n          actions.play();\n        }\n      }\n    });\n    props.setTooltipCloseCallback(() => close);\n  };\n\n  const onReactionClick = () => {\n    const mediaArea = props.mediaArea as MediaArea.mediaAreaSuggestedReaction;\n    const size = stories.width * w / 100;\n    const multiplier = 2.6875;\n    props.sendReaction({\n      reaction: mediaArea.reaction,\n      target: div,\n      sizes: {\n        genericEffect: size * 0.375,\n        genericEffectSize: size * 1.5,\n        size,\n        effectSize: size * multiplier\n      },\n      textColor: mediaArea.pFlags.dark ? 'white' : undefined,\n      fireSame: true\n    });\n  };\n\n  const showNotCenteredTooltip = (_props: {\n    callback: () => void,\n    text: HTMLElement\n  }) => {\n    const a = anchorCallback(() => {\n      close();\n      _props.callback();\n    });\n    a.append(_props.text);\n    const wasPlaying = !stories.paused;\n    actions.pause();\n    const {close} = showTooltip({\n      element: div,\n      vertical: 'top',\n      textElement: a,\n      centerVertically: false,\n      onClose: () => {\n        if(wasPlaying) {\n          actions.play();\n        }\n      }\n    });\n    props.setTooltipCloseCallback(() => close);\n  };\n\n  const onPostClick = () => {\n    const openPost = () => {\n      props.close(() => {\n        const mediaArea = props.mediaArea as MediaArea.mediaAreaChannelPost;\n        appImManager.setInnerPeer({\n          peerId: mediaArea.channel_id.toPeerId(true),\n          lastMsgId: mediaArea.msg_id\n        });\n      });\n    };\n\n    showNotCenteredTooltip({\n      callback: openPost,\n      text: i18n('Story.ViewPost')\n    });\n  };\n\n  const onLinkClick = () => {\n    showNotCenteredTooltip({\n      callback: () => {\n        const url = (props.mediaArea as MediaArea.mediaAreaUrl).url;\n        if(wrapUrl(url).onclick) {\n          props.close(() => {\n            appImManager.openUrl(url);\n          });\n        } else {\n          safeWindowOpen(url);\n        }\n      },\n      text: i18n('OpenUrlTitle')\n    });\n  };\n\n  const onClick = (e: MouseEvent) => {\n    if(!props.isActive()) {\n      return;\n    }\n\n    cancelEvent(e);\n    onTypeClick(e);\n  };\n\n  const renderReaction = (mediaArea: MediaArea.mediaAreaSuggestedReaction) => {\n    const reaction = mediaArea.reaction;\n    const [count, setCount] = createSignal<number>(0);\n    const uReaction = createUnifiedSignal<JSX.Element>();\n    const size = stories.width * w / 100 * 0.72;\n\n    let div: HTMLDivElement;\n    (<div\n      ref={div}\n      class={classNames(\n        styles.ViewerStoryMediaAreaReactionInner,\n        count() && styles.hasCount\n      )}\n    />);\n\n    renderStoryReaction({\n      reaction,\n      uReaction,\n      div,\n      size,\n      textColor: mediaArea.pFlags.dark ? 'white' : undefined,\n      play: true\n    });\n\n    createRenderEffect(() => {\n      const views = props.story.views;\n      const reactions = views?.reactions;\n      const reactionCount = reactions?.find((reactionCount) => reactionsEqual(reactionCount.reaction, reaction));\n      setCount(reactionCount?.count ?? 0);\n    });\n\n    createEffect(() => {\n      const element = uReaction();\n      if(element === null) {\n        return;\n      }\n\n      setChildren((\n        <>\n          <div\n            class={classNames(\n              styles.ViewerStoryMediaAreaReactionBubbles,\n              mediaArea.pFlags.dark && styles.dark,\n              count() && styles.hasCount\n            )}\n          >\n            <div class={styles.ViewerStoryMediaAreaReactionBubble}></div>\n            <div class={classNames(styles.ViewerStoryMediaAreaReactionBubble, styles.small)}></div>\n          </div>\n          {element}\n          <div\n            class={classNames(\n              styles.ViewerStoryMediaAreaReactionCount,\n              mediaArea.pFlags.dark && styles.dark,\n              count() && styles.hasCount\n            )}\n            // style={{'font-size': size * .275 + 'px'}}\n            style={{'font-size': `calc(var(--stories-width) * ${w / 100 * 0.72 * .275})`}}\n          >\n            {count() ? formatNumber(count(), 1) : ''}\n          </div>\n        </>\n      ));\n      props.setReady(true);\n    });\n  };\n\n  let onTypeClick: (e: MouseEvent) => any;\n  if(isReaction()) {\n    onTypeClick = onReactionClick;\n    renderReaction(props.mediaArea as MediaArea.mediaAreaSuggestedReaction);\n  } else if(isLocation()) {\n    onTypeClick = onLocationClick;\n    props.setReady(true);\n  } else if(isPost()) {\n    onTypeClick = onPostClick;\n    props.setReady(true);\n  } else if(isLink()) {\n    onTypeClick = onLinkClick;\n    props.setReady(true);\n  } else {\n    props.setReady(true);\n  }\n\n  let div: HTMLDivElement;\n  return (\n    <div\n      ref={div}\n      class={classNames(\n        styles.ViewerStoryMediaArea,\n        ...(isLocation() ? [\n          playingMemo() && 'shimmer',\n          'shimmer-bright',\n          'shimmer-once'\n        ] : []),\n        ...(isReaction() ? [\n          styles.ViewerStoryMediaAreaReaction\n        ] : [])\n      )}\n      style={`left: ${x}%; top: ${y}%; width: ${w}%; height: ${h}%; --rotate: ${rotation}deg`}\n      onClick={onClick}\n    >\n      {children()}\n    </div>\n  );\n};\n\ntype StorySendReactionAnimation = {\n  reaction: Reaction | Promise<Reaction>,\n  target: HTMLElement,\n  sizes?: Parameters<(typeof ReactionElement)['fireAroundAnimation']>[0]['sizes'],\n  textColor?: string,\n  fireSame?: boolean\n};\ntype StorySendReaction = (params: StorySendReactionAnimation) => void;\n\nconst Stories = (props: {\n  state: StoriesContextPeerState,\n  index: Accessor<number>,\n  splitByDays?: boolean,\n  pinned?: boolean,\n  onReady?: () => void,\n  close: (callback?: () => void) => void,\n  peers: StoriesContextPeerState[],\n  isFull: Accessor<boolean>,\n  transitionSignal: Signal<boolean>\n}) => {\n  const avatar = AvatarNew({\n    size: STORY_HEADER_AVATAR_SIZE,\n    peerId: props.state.peerId,\n    isDialog: false\n  });\n  avatar.node.classList.add(styles.ViewerStoryHeaderAvatar);\n  const isMe = rootScope.myId === props.state.peerId;\n  const peerTitle = !isMe && new PeerTitle();\n  let peerTitleElement: HTMLElement;\n  if(peerTitle) {\n    peerTitle.update({peerId: props.state.peerId, dialog: false});\n    peerTitleElement = peerTitle.element;\n  } else {\n    peerTitleElement = i18n('YourStory');\n  }\n\n  peerTitleElement.classList.add(styles.ViewerStoryHeaderName);\n\n  const bindOnAnyPopupClose = (wasPlaying = !stories.paused) => () => onAnyPopupClose(wasPlaying);\n  const onAnyPopupClose = (wasPlaying: boolean) => {\n    if(wasPlaying) {\n      actions.play();\n    }\n  };\n\n  const onShareClick = (wasPlaying = !stories.paused) => {\n    actions.pause();\n    handleShareStory({\n      story: currentStory(),\n      peerId: props.state.peerId,\n      onSend: async(toPeerId: PeerId) => {\n        showMessageSentTooltip(\n          i18n(\n            toPeerId === rootScope.myId ? 'StorySharedToSavedMessages' : 'StorySharedTo',\n            [await wrapPeerTitle({peerId: toPeerId})]\n          )\n        )\n      },\n      onClose: bindOnAnyPopupClose(wasPlaying)\n    })\n  };\n\n  const onShareButtonClick = (e: MouseEvent, listenTo: HTMLElement) => {\n    const story = currentStory() as StoryItem.storyItem;\n    if(story.pFlags.noforwards) {\n      const {open} = createContextMenu({\n        buttons: [{\n          icon: 'link',\n          text: 'CopyLink',\n          onClick: copyLink\n        }],\n        listenTo: listenTo,\n        ...topMenuOptions\n      });\n      open(e);\n    } else {\n      onShareClick();\n    }\n  };\n\n  const avatarInfo = AvatarNew({\n    size: 162/* 54 */,\n    peerId: props.state.peerId,\n    isDialog: false,\n    withStories: true,\n    storyColors: {\n      read: 'rgba(255, 255, 255, .3)'\n    }\n  });\n  avatarInfo.node.classList.add(styles.ViewerStoryInfoAvatar);\n  let peerTitleInfoElement: HTMLElement;\n  if(isMe) {\n    peerTitleInfoElement = i18n('MyStory');\n  } else {\n    const peerTitleInfo = new PeerTitle();\n    peerTitleInfo.update({peerId: props.state.peerId, dialog: false, onlyFirstName: true});\n    peerTitleInfoElement = peerTitleInfo.element;\n  }\n  peerTitleInfoElement.classList.add(styles.ViewerStoryInfoName);\n\n  const [stories, actions] = useStories();\n  const [content, setContent] = createSignal<JSX.Element>();\n  const [videoDuration, setVideoDuration] = createSignal<number>();\n  const [caption, setCaption] = createSignal<JSX.Element>();\n  const [repost, setRepost] = createSignal<{reply: JSX.Element, header: JSX.Element}>();\n  const [reaction, setReaction] = createSignal<JSX.Element>();\n  const [captionOpacity, setCaptionOpacity] = createSignal(0);\n  const [captionActive, setCaptionActive] = createSignal(false);\n  const [date, setDate] = createSignal<{timestamp: number, edited?: boolean}>();\n  const [loading, setLoading] = createSignal(false);\n  const [canShareStory, setCanShareStory] = createSignal();\n  const focusedSignal = createSignal(false);\n  const sendingReactionSignal = createSignal<StorySendReactionAnimation>();\n  const inputEmptySignal = createSignal(true);\n  const inputMenuOpenSignal = createSignal(false);\n  const isPublicSignal = createSignal(false);\n  const [focused, setFocused] = focusedSignal;\n  const [sendingReaction, setSendingReaction] = sendingReactionSignal;\n  const [inputEmpty] = inputEmptySignal;\n  const [inputMenuOpen] = inputMenuOpenSignal;\n  const [isPublic, setIsPublic] = isPublicSignal;\n  const [noSound, setNoSound] = createSignal(false);\n  const [sliding, setSliding] = props.transitionSignal;\n  const [privacyType, setPrivacyType] = createSignal<StoryPrivacyType>();\n  const [mediaAreas, setMediaAreas] = createSignal<JSX.Element>();\n  const [stackedAvatars, setStackedAvatars] = createSignal<StackedAvatars>();\n  const [tooltipCloseCallback, setTooltipCloseCallback] = createSignal<VoidFunction>();\n  const [reactionsMenu, setReactionsMenu] = createSignal<ChatReactionsMenu>();\n  const currentStory = createMemo(() => props.state.stories[props.state.index]);\n  const isExpired = createMemo(() => {\n    const story = currentStory();\n    const expireDate = (story as StoryItem.storyItem).expire_date;\n    if(!expireDate) return false;\n    return expireDate <= tsNow(true);\n  });\n  const isActive = createMemo(() => stories.peer === props.state);\n  const [forceReaction, setForceReaction] = createSignal(false, {equals: false});\n\n  let currentStoryMiddleware: Middleware;\n  createEffect(() => {\n    currentStory();\n    currentStoryMiddleware = createMiddleware().get();\n  });\n\n  const fireReactionAnimation = (reaction: Reaction, params = untrack(() => sendingReaction())) => {\n    if(!params || params.target === storyDiv) {\n      return;\n    }\n\n    const sizes = params.sizes ?? {\n      genericEffect: 26,\n      genericEffectSize: 100,\n      size: 22 + 18,\n      effectSize: 80\n    };\n\n    ReactionElement.fireAroundAnimation({\n      middleware: params.fireSame ? currentStoryMiddleware : createMiddleware().get(),\n      reaction,\n      sizes,\n      stickerContainer: params.target,\n      cache: params.fireSame ? {} : params.target as any,\n      textColor: params.textColor\n    });\n  };\n\n  createEffect(() => {\n    const reaction = (currentStory() as StoryItem.storyItem).sent_reaction;\n    if(!reaction) {\n      return;\n    }\n\n    // ! DO NOT REMOVE ! it handles update, since I don't observe any property in reaction\n    (reaction as Reaction.reactionCustomEmoji)?.document_id;\n    forceReaction();\n    fireReactionAnimation(reaction);\n  });\n\n  const sendReaction: StorySendReaction = async(params) => {\n    let {reaction} = params;\n    const peerId = props.state.peerId;\n    const story = currentStory() as StoryItem.storyItem;\n    const storyId = story.id;\n    const sentReaction = story.sent_reaction;\n\n    // * wait for picker\n    if(reaction instanceof Promise) {\n      reaction = await reaction;\n      if(!reaction) {\n        return;\n      }\n    }\n\n    const isNewReaction = !reactionsEqual(sentReaction, reaction);\n    if(!isNewReaction && !params.fireSame) {\n      reaction = undefined;\n    }\n\n    setFocused(false);\n    setSendingReaction(params);\n\n    if(!isNewReaction && params.fireSame) {\n      setForceReaction(true);\n    }\n\n    await rootScope.managers.acknowledged.appStoriesManager.sendReaction(\n      peerId,\n      storyId,\n      unwrap(reaction as Reaction)\n    );\n    setSendingReaction();\n  };\n\n  const createReactionsMenu = () => {\n    const [inited, setInited] = createSignal(false);\n    const middleware = createMiddleware().get();\n    const menu = new ChatReactionsMenu({\n      managers: rootScope.managers,\n      type: 'horizontal',\n      middleware,\n      onFinish: (reaction) => sendReaction({reaction, target: storyDiv}),\n      size: 36,\n      openSide: 'top',\n      getOpenPosition: () => undefined,\n      noMoreButton: true\n    });\n\n    menu.widthContainer.classList.add(styles.ViewerStoryReactions);\n\n    menu.init().finally(() => {\n      setInited(true);\n    });\n\n    let timeout: number;\n    createEffect(() => {\n      if(!inited()) {\n        return;\n      }\n\n      const isVisible = shouldMenuBeVisible();\n      menu.widthContainer.classList.toggle('is-visible', isVisible);\n\n      if(!isVisible) {\n        timeout = window.setTimeout(() => {\n          setReactionsMenu();\n          menu.cleanup();\n        }, liteMode.isAvailable('animations') ? 200 : 0);\n      } else {\n        clearTimeout(timeout);\n      }\n    });\n\n    setReactionsMenu(menu);\n  };\n\n  const shouldMenuBeVisible = () => focused() && inputEmpty() && !inputMenuOpen();\n  const haveToCreateMenu = createMemo(() => {\n    return reactionsMenu() ? true : shouldMenuBeVisible();\n  });\n\n  createEffect(() => {\n    if(haveToCreateMenu()) {\n      createReactionsMenu();\n    }\n  });\n\n  const setVideoListeners = (video: HTMLVideoElement) => {\n    let cleaned = false;\n    onCleanup(() => {\n      cleaned = true;\n      video.pause();\n      // video.src = '';\n      // video.load();\n      video.removeEventListener('waiting', onWaiting);\n      video.removeEventListener('canplay', onCanPlay);\n    });\n\n    const onCanPlay = () => {\n      setLoading(false);\n      if(isActive()) {\n        actions.setBuffering(false);\n      }\n    };\n\n    const onWaiting = () => {\n      const loading = video.networkState === video.NETWORK_LOADING;\n      const isntEnoughData = video.readyState < video.HAVE_FUTURE_DATA;\n\n      if(loading && isntEnoughData) {\n        setLoading(true);\n        if(isActive()) {\n          actions.setBuffering(true);\n        }\n        video.addEventListener('canplay', onCanPlay, {once: true});\n      }\n    };\n\n    const reset = () => {\n      if(!video.currentTime) {\n        return;\n      }\n\n      setCurrentTime(video, 0);\n    };\n\n    video.addEventListener('waiting', onWaiting);\n\n    onCleanup(() => {\n      if(stories.buffering) {\n        actions.setBuffering(false);\n      }\n    });\n\n    // pause the video on viewer pause or story change\n    createEffect(() => {\n      if(stories.paused || !isActive()) {\n        video.pause();\n      } else {\n        video.play();\n      }\n    });\n\n    const onFirstActive = () => {\n      // seek to start on story change\n      createEffect(on(\n        () => [/* props.state.index,  */isActive()],\n        ([/* index,  */isActive]) => {\n          if(isActive) {\n            return;\n          }\n\n          reset();\n        }\n      ));\n\n      createEffect(() => {\n        video.muted = stories.muted;\n      });\n    };\n\n    if(isActive()) {\n      onFirstActive();\n    } else {\n      createReaction(onFirstActive)(() => isActive());\n    }\n\n    const story = untrack(() => currentStory());\n    createEffect(() => {\n      if(isActive() && !stories.startTime && currentStory() === story) {\n        reset();\n      }\n    });\n\n    if(!untrack(noSound)) {\n      const [appSettings, setAppSettings] = useAppSettings();\n      if(!cleaned && !appSettings.seenTooltips.storySound) {\n        const playingMemo = createMemo((prev) => prev || (isActive() && stories.startTime));\n        createEffect(() => {\n          if(playingMemo()) {\n            const {close} = showTooltip({\n              ...muteTooltipOptions,\n              textElement: i18n('Story.SoundTooltip')\n            });\n            setTooltipCloseCallback(() => close);\n          }\n        });\n\n        setAppSettings('seenTooltips', 'storySound', true);\n      }\n    }\n  };\n\n  const setStoryMeta = (story: StoryItem.storyItemSkipped | StoryItem.storyItem) => {\n    let privacyType = getStoryPrivacyType(story as StoryItem.storyItem);\n    if(/* !isMe &&  */privacyType === 'public') {\n      privacyType = undefined;\n    }\n\n    const messageMedia = unwrap((story as StoryItem.storyItem).media);\n    const document = (messageMedia as MessageMedia.messageMediaDocument)?.document as Document.document;\n    const videoAttribute = document && document.attributes.find((attribute) => attribute._ === 'documentAttributeVideo') as DocumentAttribute.documentAttributeVideo;\n    const noSound = videoAttribute ? !!videoAttribute.pFlags.nosound : false;\n    const videoDuration = videoAttribute?.duration;\n    const date = story.date;\n    const edited = (story as StoryItem.storyItem).pFlags.edited;\n    const isPublic = !!(story as StoryItem.storyItem).pFlags.public;\n    const peer = apiManagerProxy.getPeer(props.state.peerId);\n    const usernames = getPeerActiveUsernames(peer);\n\n    setPrivacyType(privacyType);\n    setDate({timestamp: date, edited});\n    setNoSound(noSound);\n    setVideoDuration(videoDuration && (videoDuration * 1000));\n    setIsPublic(isPublic);\n    setCanShareStory(isPublic && (!(story as StoryItem.storyItem).pFlags.noforwards || !!usernames[0]));\n    // shareButton.classList.toggle('hide', !isPublic);\n  };\n\n  const setStory = async(story: StoryItem) => {\n    setLoading(true);\n    if(story._ !== 'storyItem') {\n      setStackedAvatars();\n      setContent();\n      setCaption();\n      setReaction();\n      setMediaAreas();\n      setRepost();\n      setStoryMeta(story as StoryItem.storyItemSkipped);\n      rootScope.managers.appStoriesManager.getStoryById(props.state.peerId, story.id);\n      props.onReady?.();\n      return;\n    }\n\n    const middleware = createMiddleware().get();\n    const uStackedAvatars = isMe ? createUnifiedSignal<StackedAvatars>() : undefined;\n    const uCaption = createUnifiedSignal<JSX.Element>();\n    const uContent = createUnifiedSignal<JSX.Element>();\n    const uReaction = createUnifiedSignal<JSX.Element>();\n    const uMediaAreas = createUnifiedSignal<JSX.Element>();\n    const uRepost = createUnifiedSignal<{reply: JSX.Element, header: JSX.Element}>();\n    const recentViewersMemo = isMe ? createMemo<UserId[]>((previousRecentViewers) => {\n      const views = story.views;\n      const recentViewers = views?.recent_viewers;\n      if(previousRecentViewers?.join() === recentViewers?.join()) {\n        return previousRecentViewers;\n      }\n      return recentViewers;\n    }) : undefined;\n\n    const getRichTextOptions = (\n      peerId: PeerId,\n      entities: MessageEntity[],\n      loadPromises?: Promise<any>[]\n    ): WrapRichTextOptions => {\n      return {\n        entities,\n        middleware,\n        textColor: 'white',\n        loadPromises,\n        passMaskedLinks: CHANGELOG_PEER_ID === peerId\n      };\n    };\n\n    isMe && createEffect(async() => {\n      let stackedAvatars: StackedAvatars;\n      const recentViewers = recentViewersMemo();\n      if(recentViewers?.length) {\n        stackedAvatars = new StackedAvatars({\n          avatarSize: 30,\n          middleware\n        });\n\n        const peerIds = recentViewers.map((userId) => {\n          return userId.toPeerId(false);\n        });\n\n        uStackedAvatars(null);\n        await stackedAvatars.render(peerIds);\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      uStackedAvatars(stackedAvatars);\n    });\n\n    createEffect(async() => {\n      let captionNode: JSX.Element;\n      const {caption, entities} = story;\n      if(caption?.trim()) {\n        const loadPromises: Promise<any>[] = [];\n        const {message, totalEntities} = wrapMessageEntities(caption, entities?.slice());\n        const wrapped = wrapRichText(\n          message,\n          getRichTextOptions(props.state.peerId, totalEntities, loadPromises)\n        );\n\n        uCaption(null);\n        await Promise.all(loadPromises);\n        if(!middleware()) {\n          return;\n        }\n\n        captionNode = documentFragmentToNodes(wrapped);\n      }\n\n      uCaption(captionNode);\n    });\n\n    createEffect(() => {\n      const media = untrack(() => getMediaFromMessage(story));\n      const mediaId = media.id;\n      if(!mediaId) {\n        uContent();\n        return;\n      }\n\n      uContent(null);\n\n      const wrapped = wrapStoryMedia({\n        peerId: props.state.peerId,\n        storyItem: unwrap(story),\n        forViewer: true,\n        containerProps: {\n          class: styles.ViewerStoryContentMediaContainer\n        },\n        childrenClassName: styles.ViewerStoryContentMedia,\n        useBlur: 40\n      });\n\n      const onReady = () => {\n        uContent(wrapped.container);\n      };\n\n      const onLoad = () => {\n        if(!middleware()) {\n          return;\n        }\n\n        setLoading(false);\n        untrack(() => playOnOpen());\n        // props.onReady?.();\n      };\n\n      const onMedia = () => {\n        const media = wrapped.media();\n\n        if(media instanceof HTMLVideoElement) {\n          setVideoListeners(media);\n          onMediaLoad(media).then(onLoad);\n        } else {\n          onLoad();\n        }\n      };\n\n      createReaction(onReady)(() => wrapped.ready());\n      createReaction(onMedia)(() => wrapped.media());\n    });\n\n    createEffect(() => {\n      let reactionNode: JSX.Element;\n      const sentReaction = story.sent_reaction;\n      const isDefault = isDefaultReaction(sentReaction);\n      if(!sentReaction || isDefault) {\n        reactionNode = Icon('reactions_filled', ...['btn-reaction-icon', isDefault && 'btn-reaction-default'].filter(Boolean));\n        uReaction(reactionNode);\n      } else {\n        const div = document.createElement('div');\n        div.classList.add('btn-reaction-sticker', 'night');\n        renderStoryReaction({\n          reaction: sentReaction,\n          uReaction,\n          div,\n          size: 26,\n          textColor: 'white',\n          play: false\n        });\n      }\n    });\n\n    createEffect(() => {\n      if(!(story as StoryItem.storyItem).media_areas?.length) {\n        uMediaAreas();\n        return;\n      }\n\n      uMediaAreas(null);\n\n      const [allReady, setAllReady] = createSignal(false);\n      const [readyCount, setReadyCount] = createSignal(0);\n      const mediaAreas = (\n        <For each={(story as StoryItem.storyItem).media_areas}>\n          {(mediaArea) => {\n            const [ready, setReady] = createSignal(false);\n\n            createReaction(() => {\n              setReadyCount((count) => count + 1);\n              if(readyCount() === (story as StoryItem.storyItem).media_areas.length) {\n                setAllReady(true);\n              }\n            })(ready);\n\n            return (\n              <StoryMediaArea\n                story={story}\n                mediaArea={mediaArea}\n                isActive={isActive}\n                setTooltipCloseCallback={setTooltipCloseCallback}\n                setReady={setReady}\n                sendReaction={sendReaction}\n                close={props.close}\n              />\n            );\n          }}\n        </For>\n      );\n\n      createReaction(() => {\n        uMediaAreas(mediaAreas);\n      })(allReady);\n    });\n\n    createEffect(async() => {\n      const repostInfo = getStoryRepostInfo(story);\n      if(!repostInfo) {\n        uRepost();\n        return;\n      }\n\n      const {fwdFrom, mediaAreaChannelPost} = repostInfo;\n      uRepost(null);\n\n      const [headerContent, setHeaderContent] = createSignal<JSX.Element>();\n      const [subtitle, setSubtitle] = createSignal<JSX.Element>();\n\n      const ret: {reply: JSX.Element, header: JSX.Element} = {\n        header: (\n          <span class={styles.ViewerStoryHeaderRepost}>\n            {headerContent()}\n          </span>\n        )\n      } as any;\n\n      let fwdFromPeerId: PeerId, fwdFromName: string, fwdFromStoryId: number;\n      if(fwdFrom) {\n        fwdFromPeerId = fwdFrom.from && getPeerId(fwdFrom.from);\n        fwdFromName = fwdFrom.from_name;\n        fwdFromStoryId = fwdFrom.story_id;\n      } else {\n        fwdFromPeerId = mediaAreaChannelPost.channel_id.toPeerId(true);\n      }\n\n      const peerTitleOptions: Parameters<typeof wrapPeerTitle>[0] = {\n        peerId: fwdFromPeerId,\n        fromName: fwdFromName\n      };\n\n      const {node, readyThumbPromise} = avatarNew({\n        peerId: fwdFromPeerId,\n        peerTitle: fwdFromName,\n        size: 16,\n        // props: {\n        //   class: styles.ViewerStoryHeaderRepostAvatar\n        // },\n        middleware\n      });\n\n      const subtitleElement = (\n        <span>{subtitle()}</span>\n      );\n\n      const processStoryPromise = async(promise: Promise<StoryItem.storyItem>, cached: boolean) => {\n        const storyItem = await promise;\n        if(!middleware()) {\n          return;\n        }\n\n        if(cached && !storyItem.caption) {\n          setSubtitle(i18n('Story'));\n          return;\n        }\n\n        const loadPromises: Promise<any>[] = [];\n        const {message, totalEntities} = wrapMessageEntities(storyItem.caption, storyItem.entities?.slice());\n        const wrapped = wrapRichText(\n          message,\n          getRichTextOptions(fwdFromPeerId, totalEntities, loadPromises)\n        );\n        await Promise.all(loadPromises);\n        if(!middleware()) {\n          return;\n        }\n\n        setSubtitle(documentFragmentToNodes(wrapped));\n      };\n\n      const storyPromise = fwdFromStoryId && rootScope.managers.acknowledged.appStoriesManager.getStoryById(\n        fwdFromPeerId,\n        fwdFromStoryId\n      ).then(async(ackedResult) => {\n        const promise = processStoryPromise(ackedResult.result, ackedResult.cached);\n        if(!ackedResult.cached) {\n          setSubtitle(i18n('Story'));\n          return;\n        }\n\n        return promise;\n      });\n\n      const [reply, headerPeerTitle, headerAvatar] = await Promise.all([\n        wrapPeerTitle(peerTitleOptions).then(async(peerTitle) => {\n          const title = document.createDocumentFragment();\n          if(fwdFromPeerId) {\n            const isBroadcast = await rootScope.managers.appPeersManager.isBroadcast(fwdFromPeerId);\n            const icon = Icon(\n              isBroadcast ? 'newchannel_filled' : (fwdFromPeerId.isUser() ? 'newprivate_filled' : 'group_filled'),\n              'inline-icon',\n              'reply-title-icon',\n              'with-margin'\n            );\n            title.append(icon);\n          }\n\n          title.append(peerTitle);\n\n          if(fwdFromName || mediaAreaChannelPost) {\n            const container = document.createElement('div');\n            container.classList.add(styles.ViewerStoryRepostSmall);\n            container.append(title);\n            return container;\n          }\n\n          const {container, fillPromise} = wrapReply({\n            title,\n            subtitle: subtitleElement as HTMLElement,\n            useHighlightingColor: true,\n            setColorPeerId: fwdFromPeerId\n          });\n\n          await fillPromise;\n          return container;\n        }),\n        wrapPeerTitle(peerTitleOptions),\n        readyThumbPromise.then(() => node),\n        storyPromise\n      ]);\n      if(!middleware()) return;\n\n      headerPeerTitle.classList.add(styles.ViewerStoryHeaderRepostTitle);\n\n      reply.classList.add(styles.ViewerStoryRepost);\n      ret.reply = reply;\n      setHeaderContent([\n        Icon(STORY_REPOST_ICON, styles.ViewerStoryHeaderRepostIcon),\n        headerAvatar,\n        headerPeerTitle\n      ]);\n\n      uRepost(ret);\n    });\n\n    createEffect(\n      on(\n        () => [inputReady(), uStackedAvatars?.(), uCaption(), uContent(), uReaction?.(), uMediaAreas(), uRepost()] as const,\n        ([inputReady, ...u]) => {\n          if(!inputReady || u.some((v) => v === null)) {\n            return;\n          }\n\n          const [stackedAvatars, caption, content, reaction, mediaAreas, repost] = u;\n          setStackedAvatars(stackedAvatars);\n          setCaption(caption);\n          setContent(content);\n          setReaction(reaction);\n          setMediaAreas(mediaAreas);\n          setRepost(repost);\n          props.onReady?.();\n\n          createEffect(() => {\n            setStoryMeta(story);\n          });\n        },\n        {defer: true}\n      )\n    );\n  };\n\n  createEffect(() => { // on story change\n    const story = currentStory();\n    setCaptionOpacity(0);\n    setCaptionActive(false);\n\n    createEffect(() => {\n      setStory(story);\n    });\n    // createEffect(on( // on story update\n    //   () => story._,\n    //   () => {\n    //     setStory(unwrap(story), hasViewer);\n    //   }\n    // ));\n  });\n\n  const pollViewedStories = () => {\n    if(!pollViewedStoriesSet.size) {\n      return;\n    }\n\n    const ids = Array.from(pollViewedStoriesSet);\n    pollViewedStoriesSet.clear();\n    rootScope.managers.appStoriesManager.getStoriesById(props.state.peerId, ids, true);\n  };\n  const pollViewedStoriesSet: Set<number> = new Set();\n  let pollViewedStoriesInterval: number;\n  createEffect(() => {\n    if(isActive()) {\n      pollViewedStoriesInterval = window.setInterval(pollViewedStories, 60e3);\n\n      createEffect(() => {\n        pollViewedStoriesSet.add(currentStory().id);\n      });\n    } else {\n      clearInterval(pollViewedStoriesInterval);\n    }\n  });\n\n  const readStories = (maxId: number) => {\n    if(viewedStories.size) {\n      rootScope.managers.appStoriesManager.incrementStoryViews(props.state.peerId, Array.from(viewedStories));\n      viewedStories.clear();\n    }\n\n    rootScope.managers.appStoriesManager.readStories(props.state.peerId, maxId);\n  };\n\n  const viewedStories: Set<number> = new Set();\n  const readDebounced = debounce(readStories, 5e3, true, true);\n  createEffect(() => { // read stories\n    if(!isActive()) {\n      return;\n    }\n\n    let lastId: number;\n    createEffect(() => {\n      const story = currentStory();\n      if(props.pinned && untrack(() => isExpired())) viewedStories.add(story.id);\n      readDebounced(lastId = story.id);\n    });\n\n    onCleanup(() => {\n      if(!readDebounced.isDebounced()) {\n        return;\n      }\n\n      readDebounced.clearTimeout();\n      readStories(lastId);\n    });\n  });\n\n  const playOnOpen = () => {\n    if(!stories.hasViewer || untrack(() => !isActive())) {\n      return;\n    }\n\n    playOnReady();\n  };\n\n  createEffect(playOnOpen); // play on open\n\n  const slides = <StorySlides {...mergeProps(props, {currentStory})} />;\n\n  let shouldAddTranslateX = true;\n  const calculateTranslateX = () => {\n    let diff = diffToActive();\n    if(!diff) {\n      return '0px';\n    }\n\n    if(\n      shouldShow() &&\n      stories.hasViewer &&\n      fadeIn() &&\n      shouldAddTranslateX\n    ) {\n      if(diff > 0) ++diff;\n      else --diff;\n    }\n\n    const storyWidth = stories.width;\n    const MARGIN = 40;\n    const multiplier = diff > 0 ? 1 : -1;\n    const smallStoryWidth = storyWidth * STORY_SCALE_SMALL;\n    let offset = storyWidth * multiplier;\n    const distance = (storyWidth - smallStoryWidth) / 2 - MARGIN;\n    offset = (storyWidth - distance) * multiplier;\n    if(Math.abs(diff) !== 1) {\n      const d = diff - 1 * multiplier;\n      offset += d * smallStoryWidth + MARGIN * d;\n    }\n    return offset + 'px';\n  };\n\n  const playOnReady = () => {\n    if(untrack(() => loading())) {\n      return;\n    }\n\n    const activeVideoDuration = untrack(() => videoDuration());\n    // * add 0.001 just to differ video and photo stories\n    const storyDuration = activeVideoDuration ? activeVideoDuration + 0.001 : STORY_DURATION;\n    actions.play(storyDuration);\n  };\n\n  // let transitionPromise: CancellablePromise<void>;\n  const onTransitionStart = (e?: TransitionEvent) => {\n    if(e && e.target !== div) {\n      return;\n    }\n\n    setSliding(true);\n    // transitionPromise = deferredPromise();\n  };\n\n  const onTransitionEnd = (e?: TransitionEvent) => {\n    if(e && e.target !== div) {\n      return;\n    }\n\n    shouldAddTranslateX = true;\n    setSliding(false);\n    // transitionPromise?.resolve();\n    if(!isActive()) {\n      return;\n    }\n\n    playOnReady();\n  };\n\n  const toggleMute = (e: MouseEvent) => {\n    if(noSound()) {\n      const {close} = showTooltip({\n        ...muteTooltipOptions,\n        textElement: i18n('Story.NoSound')\n      });\n      setTooltipCloseCallback(() => close);\n      return;\n    }\n\n    actions.toggleMute();\n  };\n\n  let muteButtonButton: HTMLButtonElement;\n  const muteButton = (\n    <ButtonIconTsx\n      ref={muteButtonButton}\n      classList={{[styles.noSound]: noSound()}}\n      icon={stories.muted || noSound() ? 'speakerofffilled' : 'speakerfilled'}\n      onClick={toggleMute}\n    />\n  );\n\n  const copyLink = () => {\n    copyTextToClipboard(`https://t.me/${getPeerActiveUsernames(peer)[0]}/s/${currentStory().id}`);\n    toastNew({\n      langPackKey: 'LinkCopied'\n    });\n  };\n\n  const topMenuOptions: Partial<Parameters<typeof createContextMenu>[0]> = {\n    onOpenBefore: async() => {\n      peer = await rootScope.managers.appStoriesManager.getPeer(props.state.peerId);\n      story = currentStory() as StoryItem.storyItem;\n      peerId = props.state.peerId;\n    },\n    onOpen: () => {\n      wasPlaying = !stories.paused;\n      actions.pause();\n    },\n    onCloseAfter: () => {\n      if(wasPlaying && !ignoreOnClose) {\n        actions.play();\n      }\n\n      ignoreOnClose = false;\n    }\n  };\n\n  // * caption start\n\n  const CAPTION_ACTIVE_THRESHOLD = 0.2;\n  createEffect(() => {\n    if(!isActive()) {\n      return;\n    }\n\n    actions.setLoop(videoDuration() !== undefined && captionActive());\n  });\n\n  let wasPlayingBeforeCaption: boolean;\n  const onCaptionScrollTop = (scrollTop: number) => {\n    const progress = Math.min(1, scrollTop / 100);\n    const active = progress >= CAPTION_ACTIVE_THRESHOLD;\n    setCaptionOpacity(progress);\n    setCaptionActive(active);\n    // console.log('caption progress', progress);\n\n    if(videoDuration() !== undefined) {\n      return;\n    }\n\n    if(active) {\n      if(wasPlayingBeforeCaption === undefined) {\n        wasPlayingBeforeCaption = !stories.paused;\n        actions.pause();\n      }\n    } else if(wasPlayingBeforeCaption) {\n      wasPlayingBeforeCaption = undefined;\n      actions.play();\n    }\n  };\n\n  let captionScrollable: HTMLDivElement, captionText: HTMLDivElement, scrolling = false;\n  const onCaptionScroll = () => {\n    if(scrolling) {\n      return;\n    }\n\n    const scrollTop = captionScrollable.scrollTop;\n    onCaptionScrollTop(scrollTop);\n  };\n\n  const scrollPath = (path: number) => {\n    const target = Math.max(0, path);\n    const startTime = Date.now();\n    scrolling = true;\n\n    const story = currentStory();\n    animateSingle(() => {\n      if(currentStory() !== story) {\n        return false;\n      }\n\n      const t = Math.min(1, (Date.now() - startTime) / 300);\n      const value = easeOutCubicApply(t, 1);\n      const currentPath = path * (1 - value);\n      const scrollTop = Math.round(target - currentPath);\n      captionScrollable.scrollTop = scrollTop;\n      onCaptionScrollTop(scrollTop);\n\n      return t < 1;\n    }, captionScrollable).finally(() => {\n      scrolling = false;\n    });\n  };\n\n  const onCaptionClick = (e: MouseEvent) => {\n    if((captionScrollable.scrollHeight <= captionScrollable.clientHeight) || captionScrollable.scrollTop) {\n      return;\n    }\n\n    cancelEvent(e);\n    // const visibleTextHeight = captionScrollable.clientHeight - captionScrollable.clientWidth * 0.7 - 8;\n    const visibleTextHeight = 56;\n    const path = Math.min(captionText.scrollHeight - visibleTextHeight, captionScrollable.clientHeight - 60);\n    scrollPath(path);\n  };\n\n  const captionContainer = (\n    <div\n      ref={captionScrollable}\n      class={classNames(\n        'scrollable',\n        'scrollable-y',\n        'no-scrollbar',\n        styles.ViewerStoryCaption,\n        repost() && caption() && styles.hasReply\n      )}\n      onScroll={onCaptionScroll}\n    >\n      <div\n        ref={captionText}\n        class={classNames('spoilers-container', styles.ViewerStoryCaptionText)}\n        onClick={onCaptionClick}\n      >\n        <div class={styles.ViewerStoryCaptionTextCell} dir=\"auto\">\n          {repost()?.reply}\n          {caption()}\n        </div>\n      </div>\n    </div>\n  );\n\n  // * caption end\n\n  const contentItem = (\n    <div\n      class={styles.ViewerStoryContentItem}\n      style={captionOpacity() && {opacity: 1 - captionOpacity() * 0.5}}\n    >\n      {content()}\n    </div>\n  );\n\n  const getDateText = () => {\n    const {timestamp, edited} = date() || {};\n    if(!timestamp) {\n      return;\n    }\n\n    const elapsedTime = tsNow(true) - timestamp;\n    const formatted = formatDuration(elapsedTime);\n    const map: {[type in DurationType]?: LangPackKey} = {\n      [DurationType.Seconds]: 'StoryJustNow',\n      [DurationType.Minutes]: 'MinutesShortAgo',\n      [DurationType.Hours]: 'HoursShortAgo'\n      // [DurationType.Days]: 'DaysShortAgo'\n    };\n\n    // if(formatted[0].type === DurationType.Seconds) {\n    //   formatted[0] = {\n    //     type: DurationType.Minutes,\n    //     duration: 0\n    //   };\n    // }\n\n    const first = formatted[0];\n    const key = map[first.type];\n    const elements: (Node | string | (Node | string)[])[] = [];\n    if(!key) {\n      // return formatFullSentTime(timestamp);\n      // elements.push(getFullDate(new Date(timestamp * 1000), {shortYear: true}));\n      elements.push(<span>{documentFragmentToNodes(formatFullSentTime(timestamp))}</span> as any);\n    } else if(first.type === DurationType.Days && first.duration !== 1) {\n      elements.push(formatDateAccordingToTodayNew(new Date(timestamp * 1000)));\n    } else {\n      elements.push(i18n(key, [first.duration]));\n    }\n\n    if(edited) {\n      elements.push(i18n('EditedMessage'));\n    }\n\n    if(repost()) {\n      elements.unshift(repost().header as HTMLElement);\n    }\n\n    let joined: JSX.Element[] = joinElementsWith(elements, JOINER);\n    if(repost()) {\n      joined = [\n        joined[0],\n        <span class={styles.ViewerStoryHeaderSecondary}>{joined.slice(1)}</span>\n      ];\n    }\n\n    return joined;\n  };\n\n  const showMessageSentTooltip = (textElement: HTMLElement, peerId?: PeerId) => {\n    let a: HTMLAnchorElement;\n    if(peerId) {\n      a = document.createElement('a');\n      a.href = '#';\n      a.addEventListener('click', (e) => {\n        cancelEvent(e);\n        props.close(() => {\n          appImManager.setInnerPeer({peerId});\n        });\n      }, {capture: true, passive: false});\n      a.append(i18n('ViewInChat'));\n    }\n\n    setQuizHint({\n      textElement,\n      textRight: a,\n      appendTo: storyDiv,\n      from: 'bottom',\n      duration: 3000,\n      icon: 'checkround_filled'\n    });\n  };\n\n  const needStoryInput = props.state.peerId !== CHANGELOG_PEER_ID &&\n    props.state.peerId !== rootScope.myId &&\n    props.state.peerId.isUser();\n  const [inputReady, setInputReady] = createSignal(!needStoryInput);\n  const storyInput = needStoryInput &&\n    <StoryInput\n      {\n        ...mergeProps(props, {\n          currentStory,\n          isActive,\n          focusedSignal,\n          inputEmptySignal,\n          inputMenuOpenSignal,\n          sendReaction,\n          isPublic,\n          shareStory: onShareClick,\n          reaction,\n          onShareButtonClick,\n          onMessageSent: () => {\n            showMessageSentTooltip(i18n('Story.Tooltip.MessageSent'), props.state.peerId);\n          },\n          setInputReady\n        })\n      }\n    />;\n\n  // * top menu start\n\n  const isPeerArchived = async(visible: boolean) => {\n    const peerId = props.state.peerId;\n    if(peerId === rootScope.myId || peerId === CHANGELOG_PEER_ID) {\n      return false;\n    }\n\n    const [peer, isSubscribed] = await Promise.all([\n      rootScope.managers.appStoriesManager.getPeer(peerId),\n      rootScope.managers.appStoriesManager.isSubcribedToPeer(peerId)\n    ]);\n    const isHidden = !!peer.pFlags.stories_hidden;\n    return (visible ? !isHidden : isHidden) && isSubscribed;\n  };\n\n  const togglePeerHidden = async(hidden: boolean) => {\n    const peerId = props.state.peerId;\n    rootScope.managers.appStoriesManager.toggleStoriesHidden(peerId, hidden);\n    toastNew({\n      langPackKey: hidden ? 'StoriesMovedToContacts' : 'StoriesMovedToDialogs',\n      langPackArguments: [await wrapPeerTitle({peerId})]\n    });\n  };\n\n  const togglePinned = async(pinned: boolean) => {\n    const peerId = props.state.peerId;\n    rootScope.managers.appStoriesManager.togglePinned(peerId, currentStory().id, pinned).then(() => {\n      toastNew({\n        langPackKey: pinned ?\n          (peerId.isUser() ? 'StoryPinnedToProfile' : 'StoryPinnedToPosts') :\n          (peerId.isUser() ? 'StoryArchivedFromProfile' : 'StoryUnpinnedFromPosts')\n      });\n    });\n  };\n\n  let wasPlaying = false,\n    peer: User.user | MTChat.channel,\n    peerId: PeerId,\n    story: StoryItem.storyItem | StoryItem.storyItemSkipped,\n    ignoreOnClose = false;\n  const btnMenu = ButtonMenuToggle({\n    buttons: [{\n      icon: 'plusround',\n      text: 'Story.AddToProfile',\n      onClick: () => togglePinned(true),\n      verify: () => peerId === rootScope.myId && !(story as StoryItem.storyItem).pFlags?.pinned\n    }, {\n      icon: 'crossround',\n      text: 'Story.RemoveFromProfile',\n      onClick: () => togglePinned(false),\n      verify: () => peerId === rootScope.myId && !!(story as StoryItem.storyItem).pFlags?.pinned\n    }, {\n      icon: 'plusround',\n      text: 'SaveToPosts',\n      onClick: () => togglePinned(true),\n      verify: () => !peerId.isUser() && !(story as StoryItem.storyItem).pFlags?.pinned && rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'pin')\n    }, {\n      icon: 'crossround',\n      text: 'RemoveFromPosts',\n      onClick: () => togglePinned(false),\n      verify: () => !peerId.isUser() && !!(story as StoryItem.storyItem).pFlags?.pinned && rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'pin')\n    }, {\n      icon: 'forward',\n      text: 'ShareFile',\n      onClick: () => {\n        ignoreOnClose = true;\n        onShareClick(wasPlaying);\n      },\n      verify: () => {\n        return !!(story as StoryItem.storyItem)?.pFlags?.public && !(story as StoryItem.storyItem).pFlags.noforwards;\n      }\n    }, {\n      icon: 'link',\n      text: 'CopyLink',\n      onClick: copyLink,\n      verify: () => {\n        if(story._ !== 'storyItem') {\n          return false;\n        }\n\n        // const appConfig = await rootScope.managers.apiManager.getAppConfig();\n        return (story.pFlags.public/*  || appConfig.stories_export_nopublic_link */) && !!getPeerActiveUsernames(peer)[0];\n      }\n    }, {\n      icon: 'download',\n      text: 'MediaViewer.Context.Download',\n      onClick: () => {\n        const story = currentStory();\n        const media = getMediaFromMessage(story as StoryItem.storyItem, true);\n        if(!media) {\n          return;\n        }\n        appDownloadManager.downloadToDisc({media: unwrap(media)});\n      },\n      verify: () => {\n        if(props.state.peerId === rootScope.myId) {\n          return true;\n        }\n\n        const story = currentStory();\n        return !!(story?._ === 'storyItem' && !story.pFlags.noforwards && rootScope.premium);\n      }\n    }, {\n      icon: 'eyecross_outline',\n      text: 'Stories.StealthMode.View',\n      onClick: () => {\n        ignoreOnClose = true;\n        const appConfig = useAppConfig();\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        showStoriesStealthModePopup({\n          onActivate: () => {\n            setQuizHint({\n              title: i18n('Stories.StealthMode.Activated.Title'),\n              textElement: i18n('Stories.StealthMode.Activated.Subtitle', [\n                wrapStoriesStealthModeDuration(appConfig.stories_stealth_future_period),\n                wrapStoriesStealthModeDuration(appConfig.stories_stealth_past_period)\n              ]),\n              appendTo: storyDiv,\n              from: 'bottom',\n              duration: 8000,\n              icon: 'checkround_filled'\n            });\n          },\n          onClose: onAnyPopupClose\n        });\n      }\n    }, {\n      icon: 'archive',\n      text: 'ArchivePeerStories',\n      onClick: () => togglePeerHidden(true),\n      verify: () => isPeerArchived(true)\n    }, {\n      icon: 'unarchive',\n      text: 'UnarchiveStories',\n      onClick: () => togglePeerHidden(false),\n      verify: () => isPeerArchived(false)\n    }, {\n      icon: 'statistics',\n      text: 'ViewStatistics',\n      onClick: () => {\n        const storyId = currentStory().id;\n        props.close(() => {\n          setTimeout(() => {\n            appSidebarRight.createTab(AppStatisticsTab).open(peerId.toChatId(), undefined, storyId);\n            appSidebarRight.toggleSidebar(true);\n          }, 0);\n        });\n      },\n      verify: () => rootScope.managers.appProfileManager.canViewStatistics(peerId)\n    }, {\n      icon: 'delete danger' as Icon,\n      text: 'Delete',\n      onClick: async() => {\n        const id = currentStory().id;\n        const peerId = props.state.peerId;\n        ignoreOnClose = true;\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        try {\n          await confirmationPopup({\n            titleLangKey: 'DeleteStoryTitle',\n            descriptionLangKey: 'DeleteStorySubtitle',\n            button: {\n              langKey: 'Delete',\n              isDanger: true\n            }\n          });\n        } catch(err) {\n          onAnyPopupClose();\n          return;\n        }\n\n        rootScope.managers.appStoriesManager.deleteStories(peerId, [id]);\n      },\n      verify: () => rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'delete')\n    }, {\n      icon: 'flag',\n      className: 'danger',\n      text: 'ReportChat',\n      onClick: () => {\n        ignoreOnClose = true;\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        showStoryReport(props.state.peerId, [currentStory().id], onAnyPopupClose);\n      },\n      verify: () => !(story as StoryItem.storyItem).pFlags?.out && props.state.peerId !== CHANGELOG_PEER_ID\n      // separator: true\n    }],\n    direction: 'bottom-left',\n    ...topMenuOptions\n  });\n  btnMenu.classList.add('night');\n\n  // * top menu end\n\n  // * privacy icon start\n\n  const privacyIconMap: {[key in StoryPrivacyType]: Icon} = {\n    close: 'star_filled',\n    contacts: 'newprivate_filled',\n    public: 'newchannel_filled',\n    selected: 'newgroup_filled'\n  };\n\n  const onPrivacyIconClick = async() => {\n    const type = privacyType();\n    const peerTitle = await wrapPeerTitle({peerId: props.state.peerId, onlyFirstName: true});\n    const {close} = showTooltip({\n      container: headerDiv,\n      element: privacyIconElement,\n      vertical: 'bottom',\n      textElement: i18n(\n        type === 'close' ? 'StoryCloseFriendsHint' : (type === 'selected' ? 'StorySelectedContactsHint' : 'StoryContactsHint'),\n        [peerTitle]\n      ),\n      paddingX: 13\n    });\n\n    setTooltipCloseCallback(() => close);\n  };\n\n  createEffect(() => {\n    const close = tooltipCloseCallback();\n    if(!close) {\n      return;\n    }\n\n    onCleanup(close);\n\n    createEffect(\n      on(\n        () => [isActive(), currentStory()],\n        () => {\n          close();\n          setTooltipCloseCallback();\n        },\n        {defer: true}\n      )\n    );\n  });\n\n  let privacyIconElement: HTMLDivElement;\n  const privacyIcon = (\n    <div\n      ref={privacyIconElement}\n      class={classNames(\n        styles.ViewerStoryPrivacy,\n        'privacy-bg',\n        `privacy-bg-${privacyType()}`\n      )}\n      onClick={() => onPrivacyIconClick()}\n    >\n      {Icon(privacyIconMap[privacyType()])}\n    </div>\n  );\n\n  // * privacy icon end\n\n  // * my footer start\n\n  const getViews = isMe && (() => {\n    const story = currentStory();\n    if(story._ !== 'storyItem') {\n      return;\n    }\n\n    const viewsCount = story.views?.views_count ?? 0;\n    if(!viewsCount) {\n      const isExpired = story.expire_date <= tsNow(true);\n      if(isExpired) {\n        return i18n('NobodyViewsArchived');\n      } else {\n        return i18n('NobodyViews');\n      }\n    } else {\n      return i18n('Views', [viewsCount]);\n    }\n  });\n\n  const openViewsList = isMe && (() => {\n    let nextOffset: string;\n    const viewsMap: Map<PeerId, StoryView.storyView> = new Map();\n    const popup = showPickUserPopup({\n      titleLangKey: 'StoryViewers',\n      peerType: ['custom'],\n      getMoreCustom: (q) => {\n        const loadCount = 50;\n        return rootScope.managers.appStoriesManager.getStoryViewsList(\n          props.state.peerId,\n          currentStory().id,\n          loadCount,\n          nextOffset,\n          q\n        ).then(({nextOffset: _nextOffset, views}) => {\n          nextOffset = _nextOffset;\n          return {\n            result: views.map((storyView) => {\n              const peerId = storyView.user_id.toPeerId(false);\n              viewsMap.set(peerId, storyView);\n              return peerId;\n            }),\n            isEnd: !nextOffset\n          };\n        });\n      },\n      processElementAfter: (peerId, dialogElement) => {\n        const view = viewsMap.get(peerId);\n        return processDialogElementForReaction({\n          dialogElement,\n          peerId,\n          date: view.date,\n          isMine: true,\n          middleware: popup.selector.middlewareHelperLoader.get(),\n          reaction: view.reaction\n        });\n      },\n      onSelect: ([obj]) => {\n        props.close(() => {\n          appImManager.setInnerPeer(obj);\n        });\n      },\n      placeholder: 'SearchPlaceholder',\n      exceptSelf: true,\n      meAsSaved: false\n    });\n  });\n\n  const onDeleteClick = isMe && (async() => {\n    const peerId = props.state.peerId;\n    const storyId = currentStory().id;\n    await confirmationPopup({\n      titleLangKey: 'DeleteStoryTitle',\n      descriptionLangKey: 'DeleteStorySubtitle',\n      button: {\n        isDanger: true,\n        langKey: 'Delete'\n      }\n    });\n\n    rootScope.managers.appStoriesManager.deleteStories(peerId, [storyId]);\n  });\n\n  if(isMe) {\n    const viewedStories: Set<number> = new Set();\n    const getAround = 2;\n    let promise: Promise<any>;\n    const getStoriesViews = async() => {\n      if(promise) {\n        return;\n      }\n\n      const story = currentStory();\n      const index = props.state.stories.indexOf(story);\n      const slice = props.state.stories.slice(Math.max(0, index - getAround), index + getAround);\n      slice.forEach((story) => {\n        viewedStories.add(story.id);\n      });\n\n      const ids = Array.from(viewedStories);\n      viewedStories.clear();\n      promise = rootScope.managers.appStoriesManager.getStoriesViews(props.state.peerId, ids).then(() => {\n        promise = undefined;\n      });\n\n      // let's clear after last execution, not before viewer is closed\n      if(cleaned) {\n        clearInterval(interval);\n      }\n    };\n    const interval = setInterval(getStoriesViews, 10e3);\n\n    createEffect(() => {\n      const story = currentStory();\n      viewedStories.add(story.id);\n    });\n\n    let cleaned = false;\n    onCleanup(() => {\n      cleaned = true;\n    });\n\n    onMount(() => {\n      getStoriesViews();\n    });\n  }\n\n  let footerReactionElement: HTMLSpanElement;\n  const footer = (isMe || CHANGELOG_PEER_ID === props.state.peerId || !props.state.peerId.isUser()) && (\n    <div\n      class={classNames(\n        styles.ViewerStoryFooter,\n        styles.hideOnSmall,\n        rootScope.myId === props.state.peerId && styles.isMe,\n        CHANGELOG_PEER_ID === props.state.peerId && styles.isChangelog\n      )}\n    >\n      {isMe ? (\n        <>\n          <div class={styles.ViewerStoryFooterLeft} onClick={openViewsList}>\n            {stackedAvatars() && stackedAvatars().container}\n            {getViews()}\n          </div>\n          <div class={styles.ViewerStoryFooterRight}>\n            {/* Deleting stories is CRM-superadmin-only. */}\n            <Show when={useIsCrmSuperAdmin()()}>\n              <ButtonIconTsx icon=\"delete\" onClick={onDeleteClick} />\n            </Show>\n          </div>\n        </>\n      ) : (!props.state.peerId.isUser() ? (\n        <>\n          <div class={styles.ViewerStoryFooterLeft}>\n            <span class={styles.ViewerStoryFooterIcon}>\n              {Icon('eye1', styles.ViewerStoryFooterIconIcon)}\n              {formatNumber((currentStory() as StoryItem.storyItem).views?.views_count || 1, 1)}\n            </span>\n          </div>\n          <div class={styles.ViewerStoryFooterRight}>\n            {canShareStory() && (\n              <ButtonIconTsx\n                icon=\"forward\"\n                onClick={(e) => {\n                  onShareButtonClick(e, e.target as HTMLElement);\n                }}\n              />\n            )}\n            <span\n              ref={footerReactionElement}\n              class={classNames(\n                styles.ViewerStoryFooterIcon,\n                styles.ViewerStoryFooterReaction,\n                (currentStory() as StoryItem.storyItem).sent_reaction && styles.isReacted\n              )}\n              onClick={(e) => sendReaction({reaction: {_: 'reactionEmoji', emoticon: DEFAULT_REACTION_EMOTICON}, target: footerReactionElement.firstElementChild as HTMLElement})}\n            >\n              <IconTsx icon={(currentStory() as StoryItem.storyItem).sent_reaction ? 'reactions_filled' : 'reactions'} class={styles.ViewerStoryFooterIconIcon}></IconTsx>\n              {(currentStory() as StoryItem.storyItem).views?.reactions_count || 0}\n            </span>\n          </div>\n        </>\n      ) : i18n('StoryCantReply'))}\n    </div>\n  );\n\n  // * my footer end\n\n  createEffect(\n    on(\n      () => [isActive(), currentStory()],\n      () => {\n        if(liteMode.isAvailable('animations')) {\n          return;\n        }\n\n        untrack(() => {\n          onTransitionStart();\n          onTransitionEnd();\n        });\n      }\n    )\n  );\n\n  // createEffect(() => {\n  //   if(stories.peer && !liteMode.isAvailable('animations')) {\n  //     untrack(() => {\n  //       onTransitionStart();\n  //       onTransitionEnd();\n  //     });\n  //   }\n  // });\n\n  const onProfileClick = (e: MouseEvent) => {\n    // * I'm handling it elsewhere\n    if(findUpClassName(e.target, styles.ViewerStoryHeaderRepost)) {\n      return;\n    }\n\n    const peerId = props.state.peerId;\n    props.close(() => {\n      appImManager.setInnerPeer({peerId});\n    });\n  };\n\n  const diffToActive = createMemo(() => {\n    return props.index() - props.peers.indexOf(stories.peer);\n  });\n\n  const fromLeft = createMemo<boolean>((prev) => {\n    return sliding() ? prev : diffToActive() < 0;\n  });\n\n  const fromRight = createMemo<boolean>((prev) => {\n    return sliding() ? prev : diffToActive() > 0;\n  });\n\n  const [fadeIn, setFadeIn] = createSignal(false);\n\n  const shouldShow = createMemo((/* prev */) => {\n    const diff = Math.abs(diffToActive());\n    let shouldBeVisible: boolean;\n    if(/* props.isFull() &&  */!stories.hasViewer) {\n      shouldBeVisible = diff === 0;\n\n      if(!props.isFull() && diff <= STORIES_PRESERVE) {\n        shouldAddTranslateX = false;\n      }\n    } else {\n      shouldBeVisible = diff <= STORIES_PRESERVE;\n    }\n\n    // if(!shouldBeVisible && prev) {\n    //   return sliding();\n    // }\n\n    return shouldBeVisible;\n  });\n\n  createEffect<boolean>((prev) => {\n    if(!shouldShow()) {\n      // if(prev) {\n      setFadeIn(true);\n      // }\n\n      return true;\n    } else if(prev) {\n      setFadeIn(true);\n\n      doubleRaf().then(() => {\n        setFadeIn(false);\n      });\n\n      return true;\n    }\n  });\n\n  let div: HTMLDivElement, storyDiv: HTMLDivElement, headerDiv: HTMLDivElement;\n  const ret = (\n    <div\n      ref={div}\n      class={styles.ViewerStoryContainer}\n      classList={{\n        ...(props.isFull() ? {\n          [styles.fromLeft]: fromLeft(),\n          [styles.current]: isActive(),\n          [styles.fromRight]: fromRight()\n        } : {\n          [styles.small]: !isActive()\n        }),\n        [styles.hold]: stories.hideInterface && isActive(),\n        [styles.focused]: focused(),\n        [styles.fadeIn]: fadeIn()\n      }}\n      style={!props.isFull() && {\n        '--translateX': calculateTranslateX()\n      }}\n      onClick={(e) => {\n        if(!isActive()) {\n          actions.set({peer: props.state, index: props.state.index});\n        } else if(\n          findUpClassName(e.target, styles.ViewerStoryRepost) ||\n          findUpClassName(e.target, styles.ViewerStoryHeaderRepost)\n        ) {\n          const story = currentStory();\n          const repostInfo = getStoryRepostInfo(story as StoryItem.storyItem);\n          if(!repostInfo) {\n            toastNew({\n              langPackKey: 'HidAccount'\n            });\n            return;\n          }\n\n          const {fwdFrom, mediaAreaChannelPost} = repostInfo;\n          if(fwdFrom?.from || mediaAreaChannelPost) {\n            e.stopPropagation();\n            props.close(() => {\n              const peerId = fwdFrom ? getPeerId(fwdFrom.from) : mediaAreaChannelPost.channel_id.toPeerId(true);\n              if(fwdFrom?.story_id && !findUpClassName(e.target, styles.ViewerStoryHeaderRepost)) {\n                createStoriesViewerWithPeer({\n                  peerId,\n                  id: fwdFrom.story_id\n                });\n              } else {\n                appImManager.setInnerPeer({\n                  peerId,\n                  lastMsgId: mediaAreaChannelPost?.msg_id\n                });\n              }\n            });\n          }\n        } else if(\n          captionScrollable.scrollTop &&\n          !findUpAsChild(e.target, captionText) &&\n          !findUpClassName(e.target, styles.ViewerStoryHeader)\n        ) {\n          scrollPath(-captionScrollable.scrollTop);\n        } else if(\n          !stories.paused &&\n          !stories.hideInterface &&\n          !findUpAsChild(e.target, captionText) &&\n          !findUpClassName(e.target, styles.ViewerStoryHeader) &&\n          !findUpClassName(e.target, 'stories-input') &&\n          !findUpClassName(e.target, styles.ViewerStoryReactions) &&\n          findUpClassName(e.target, styles.ViewerStory)\n        ) {\n          const rect = div.getBoundingClientRect();\n          const next = e.clientX > (rect.left + rect.width / 3);\n          actions.goToNearestStorySafe(next);\n        }\n      }}\n      onTransitionStart={onTransitionStart}\n      onTransitionEnd={onTransitionEnd}\n    >\n      <div ref={storyDiv} class={classNames(styles.ViewerStory, loading() && isActive() && 'shimmer')}>\n        <div class={styles.ViewerStoryContent}>\n          {contentItem}\n        </div>\n        <div class={styles.hideOnSmall}>\n          <div class={classNames(styles.ViewerStoryShadow, caption() && styles.hasCaption)}></div>\n          <div class={styles.ViewerStorySlides}>\n            {slides}\n          </div>\n          <div ref={headerDiv} class={classNames(styles.ViewerStoryHeader, 'night')}>\n            <div class={styles.ViewerStoryHeaderLeft} onClick={onProfileClick}>\n              {avatar.element}\n              <div class={styles.ViewerStoryHeaderInfo}>\n                <div class={styles.ViewerStoryHeaderRow}>\n                  {peerTitleElement}\n                  {props.splitByDays && (\n                    <span class={styles.ViewerStoryHeaderSecondary}>\n                      {`${JOINER}${props.state.index + 1}/${props.state.stories.length}`}\n                    </span>\n                  )}\n                </div>\n                <div\n                  class={classNames(\n                    // styles.ViewerStoryHeaderRow,\n                    repost() ? styles.hasRepost : styles.ViewerStoryHeaderSecondary,\n                    styles.ViewerStoryHeaderTime\n                  )}\n                >\n                  {getDateText()}\n                </div>\n              </div>\n            </div>\n            <div class={styles.ViewerStoryHeaderRight}>\n              {privacyType() && privacyIcon}\n              <ButtonIconTsx\n                icon={stories.paused && !stories.playAfterGesture ? 'play' : 'pause'}\n                onClick={() => actions.toggle()}\n              />\n              {videoDuration() && muteButton}\n              {/* <ButtonIconTsx icon={'more'} /> */}\n              {btnMenu}\n              {props.isFull() && (\n                <ButtonIconTsx\n                  icon={'close'}\n                  onClick={() => props.close()}\n                />\n              )}\n            </div>\n          </div>\n          {(caption() || repost()) && captionContainer}\n          {mediaAreas() && (\n            <div\n              class={styles.ViewerStoryMediaAreas}\n              style={captionOpacity() && {'opacity': 1 - captionOpacity() * 0.5, 'z-index': 0}}\n            >\n              {mediaAreas()}\n            </div>\n          )}\n          {reactionsMenu()?.widthContainer}\n        </div>\n        {!props.isFull() && (\n          <div class={styles.ViewerStoryInfo}>\n            {avatarInfo.node}\n            {peerTitleInfoElement}\n          </div>\n        )}\n      </div>\n      {storyInput || footer}\n      {/* <MessageInputField /> */}\n    </div>\n  );\n\n  const muteTooltipOptions: Parameters<typeof showTooltip>[0] = {\n    container: headerDiv,\n    element: muteButtonButton,\n    vertical: 'bottom',\n    paddingX: 13\n  };\n\n  return (\n    <Show when={shouldShow()}>\n      {ret}\n    </Show>\n  );\n}\n\nexport default function StoriesViewer(props: {\n  onExit?: () => void,\n  target?: Accessor<Element>,\n  splitByDays?: boolean,\n  pinned?: boolean\n}) {\n  const [stories, actions] = useStories();\n  const [show, setShow] = createSignal(false);\n  const isFull = createMemo(() => {\n    return windowSize.height > windowSize.width ||\n      windowSize.width < (stories.width + 135 + 8 * 2) ||\n      stories.width === windowSize.width;\n  });\n  const wasShown = createMemo((shown) => shown || show());\n\n  // * fix `ended` property\n  actions.viewerReady(false);\n\n  const CANCELABLE_KEYS: Set<string> = new Set([\n    'ArrowRight',\n    'ArrowLeft',\n    'ArrowDown',\n    'Space'\n  ]);\n\n  const onKeyDown = (e: KeyboardEvent) => {\n    if(isTargetAnInput(getAppWindow().document.activeElement as HTMLElement)) {\n      throttledKeyDown.clear();\n      return;\n    }\n\n    const activeStoryContainer = getActiveStoryContainer();\n    if(animating || !!activeStoryContainer.querySelector('.is-recording')) {\n      throttledKeyDown.clear();\n      cancelEvent(e);\n      return;\n    }\n\n    if(CANCELABLE_KEYS.has(e.key) || CANCELABLE_KEYS.has(e.code)) {\n      cancelEvent(e);\n    } else {\n      const input = activeStoryContainer.querySelector<HTMLElement>('.input-message-input');\n      if(\n        input &&\n        !IS_TOUCH_SUPPORTED &&\n        input.isContentEditable &&\n        overlayCounter.overlaysActive === overlaysActive\n      ) {\n        focusInput(input, e);\n      }\n    }\n\n    if(e.key === 'ArrowDown') {\n      throttledKeyDown.clear();\n      close();\n      return;\n    }\n\n    throttledKeyDown(e);\n  };\n\n  const throttledKeyDown = throttle((e: KeyboardEvent) => {\n    if(e.key === 'ArrowRight') {\n      actions.goToNearestStorySafe(true);\n    } else if(e.key === 'ArrowLeft') {\n      actions.goToNearestStorySafe(false);\n    } else if(e.code === 'Space') {\n      actions.toggle();\n    }\n  }, 200, true);\n\n  // Follow the active window so the stories keyboard handler keeps firing when the overlay\n  // moves into a Document PiP window.\n  let disposeKeyDownListener: () => void;\n\n  emoticonsDropdown.getElement().classList.add('night');\n  emoticonsDropdown.setTextColor('white');\n\n  onCleanup(() => {\n    disposeKeyDownListener?.();\n    toggleOverlay(false);\n    swipeHandler.removeListeners();\n    appNavigationController.removeItem(navigationItem);\n\n    emoticonsDropdown.getElement().classList.remove('night');\n    emoticonsDropdown.setTextColor();\n    emoticonsDropdown.chatInput = undefined;\n  });\n\n  const close = (callback?: () => void) => {\n    callback && runWithOwner(owner, () => {\n      onCleanup(() => {\n        callback();\n      });\n    });\n\n    actions.viewerReady(false);\n    if(dispose) {\n      deferred = deferredPromise();\n      dispatchHeavyAnimationEvent(deferred, 1000);\n      dispose();\n      dispose = undefined;\n    }\n    actions.pause();\n    throttledKeyDown.clear();\n    setShow(false);\n    div.removeEventListener('click', onDivClick, {capture: true});\n  };\n\n  let div: HTMLDivElement, backgroundDiv: HTMLDivElement, closeButton: HTMLButtonElement;\n  let dispose: () => void; // * dispose listeners on close to avoid effects during animation\n  const ret = createRoot((_dispose) => {\n    dispose = _dispose;\n\n    createEffect(() => {\n      if(stories.ended) {\n        close();\n      }\n    });\n\n    const storiesReadiness: Set<PeerId> = new Set();\n    const storiesShouldBeReady: Set<PeerId> = new Set();\n    const perf = performance.now();\n    let wasReady = false;\n\n    const openOnReady = () => {\n      clearTimeout(timeout)\n      wasReady = true;\n      runWithOwner(owner, () => {\n        onMount(() => {\n          open();\n        });\n      });\n    };\n\n    const timeout = setTimeout(() => {\n      console.error('stories timeout');\n      stories.peers\n      .filter((peer) => storiesShouldBeReady.has(peer.peerId) && !storiesReadiness.has(peer.peerId))\n      .forEach((peer) => {\n        console.error('stories not ready', peer);\n      });\n      openOnReady();\n    }, 250);\n\n    const createStories = (peer: StoriesContextPeerState, index: Accessor<number>) => {\n      const onReady = () => {\n        storiesReadiness.add(peer.peerId);\n\n        if(wasReady) {\n          return;\n        }\n\n        // console.log('stories ready', peer.peerId, storiesReadiness.size, performance.now() - perf);\n\n        if(storiesReadiness.size === storiesShouldBeReady.size) {\n          openOnReady();\n        }\n      };\n\n      storiesShouldBeReady.add(peer.peerId);\n\n      const transitionSignal = createSignal(false);\n      const ret = (\n        <Stories\n          state={peer}\n          index={index}\n          splitByDays={props.splitByDays}\n          pinned={props.pinned}\n          onReady={onReady}\n          close={close}\n          peers={itemsToRender()}\n          isFull={isFull}\n          transitionSignal={transitionSignal}\n        />\n      );\n\n      const ref = resolveFirst(() => ret);\n      createEffect(() => {\n        const element = ref();\n        if(!element) {\n          return;\n        }\n\n        transitions.set(element, transitionSignal[0]);\n\n        onCleanup(() => {\n          transitions.delete(element);\n        });\n      });\n\n      return ret;\n    };\n\n    const preserve = STORIES_PRESERVE + STORIES_PRESERVE_HIDDEN;\n    const getItemsToRender = (index: number) => stories.peers.slice(Math.max(index - preserve, 0), Math.min(index + preserve + 1, stories.peers.length));\n    const itemsToRender = createMemo(() => getItemsToRender(stories.index));\n    const btnClose = <ButtonIconTsx ref={closeButton} icon={'close'} class={styles.ViewerClose} onClick={() => close()} />;\n    const transitions: WeakMap<Element, Accessor<boolean>> = new WeakMap();\n\n    return (\n      <div\n        ref={div}\n        class={classNames(\n          styles.Viewer,\n          !show() && styles.isInvisible,\n          isFull() && styles.isFull,\n          stories.hasViewer && styles.isReady\n        )}\n        onClick={(e) => {\n          if(animating) {\n            cancelEvent(e);\n            return;\n          }\n\n          if(e.target === div) {\n            close();\n          }\n        }}\n        style={{\n          '--stories-width': stories.width + 'px',\n          '--stories-height': stories.height + 'px'\n        }}\n      >\n        <div ref={backgroundDiv} class={styles.ViewerBackground} />\n        {!isFull() && btnClose}\n        {/* <For each={stories.peers}>{createStories}</For> */}\n        <TransitionGroup noWait={() => isFull()/*  || !stories.hasViewer */} transitions={transitions}>\n          <For each={itemsToRender()}>{createStories}</For>\n        </TransitionGroup>\n      </div>\n    );\n  });\n\n  let pauseTimeout: number;\n  const swipeHandler = new SwipeHandler({\n    element: div,\n    onSwipe: (xDiff, yDiff, e) => {\n      if(!(e instanceof TouchEvent)) {\n        return;\n      }\n\n      const jumpOn = Math.min(125, windowSize.width / 3);\n      const closeOn = Math.min(125, windowSize.height * 0.2);\n      if(yDiff > closeOn) {\n        close();\n        return true;\n      }\n\n      if(Math.abs(xDiff) < jumpOn) {\n        return false;\n      }\n\n      const peerIndex = stories.peers.indexOf(stories.peer);\n      const neighbourIndex = peerIndex + (xDiff < 0 ? 1 : -1);\n      const neighbour = stories.peers[neighbourIndex];\n      if(!neighbour) {\n        close();\n      } else {\n        actions.set({peer: neighbour});\n      }\n\n      return true;\n    },\n    verifyTouchTarget: (e) => {\n      return !findUpClassName(e.target, 'btn-icon') &&\n        !findUpClassName(e.target, 'btn-corner') &&\n        !findUpClassName(e.target, styles.ViewerStoryRepost) &&\n        !findUpClassName(e.target, styles.ViewerStoryMediaArea) &&\n        !findUpClassName(e.target, styles.ViewerStoryPrivacy) &&\n        !findUpClassName(e.target, styles.ViewerStoryCaptionText) &&\n        !findUpClassName(e.target, styles.ViewerStoryReactions) &&\n        !!findUpClassName(e.target, styles.ViewerStory) &&\n        !findUpClassName(e.target, styles.small) &&\n        !findUpClassName(e.target, styles.focused);\n    },\n    onStart: () => {\n      // if(stories.paused && !stories.hideInterface) {\n      //   return;\n      // }\n\n      pauseTimeout = window.setTimeout(() => {\n        actions.pause(true);\n      }, 200);\n    },\n    onReset: (e) => {\n      window.clearTimeout(pauseTimeout);\n      if(!e ||\n        !stories.paused ||\n        findUpClassName(e.target, 'btn-icon') ||\n        findUpClassName(e.target, styles.ViewerStoryPrivacy) ||\n        findUpClassName(e.target, 'btn-corner') ||\n        findUpClassName(e.target, styles.ViewerStoryReactions)) {\n        return;\n      }\n\n      const story = findUpClassName(e.target, styles.ViewerStory);\n      const caption = story?.querySelector('.' + styles.ViewerStoryCaption);\n      if(caption?.scrollTop) {\n        return;\n      }\n\n      if(story && stories.hideInterface) {\n        getAppWindow().document.addEventListener('click', cancelEvent, {capture: true, once: true});\n      }\n\n      const playStories = stories.playAfterGesture || !stories.hideInterface;\n      actions.toggleInterface(false);\n      if(playStories) {\n        actions.play();\n      }\n    }\n  });\n\n  let avatarFrom: ReturnType<typeof AvatarNew>;\n  const open = () => {\n    const target = props.target?.();\n    if(!target || !target.classList.contains('avatar')) {\n      setShow(true);\n      return;\n    }\n\n    avatarFrom = AvatarNew({\n      size: STORY_HEADER_AVATAR_SIZE,\n      isDialog: false,\n      useCache: false\n    });\n\n    avatarFrom.node.style.cssText = `position: absolute; visibility: hidden; z-index: 1000; transform-origin: top left;`;\n    getOverlayRoot().append(avatarFrom.node);\n\n    if(!untrack(() => show())) {\n      createEffect(() => {\n        if(avatarFrom.ready()) {\n          setShow(true);\n        }\n      });\n    }\n\n    createEffect(() => {\n      const peerId = stories.peer?.peerId;\n      if(!peerId || !avatarFrom) {\n        return;\n      }\n\n      untrack(() => {\n        avatarFrom.render({peerId});\n      });\n    });\n\n    onCleanup(() => {\n      if(!avatarFrom) {\n        return;\n      }\n\n      avatarFrom.node.remove();\n    });\n  };\n\n  const onDivClick = (e: MouseEvent) => {\n    if(animating) {\n      cancelEvent(e);\n    }\n\n    const story = findUpClassName(e.target, styles.ViewerStory);\n    const caption = story?.querySelector('.' + styles.ViewerStoryCaptionText) as HTMLElement;\n    const callback = caption && onMediaCaptionClick(caption, e);\n    if(!callback) {\n      return;\n    }\n\n    close(callback);\n    return false;\n  };\n\n  div.addEventListener('click', onDivClick, {capture: true});\n\n  const owner = getOwner();\n\n  const navigationItem: NavigationItem = {\n    type: 'stories',\n    onPop: () => {\n      if(animating) {\n        return false;\n      }\n\n      close();\n    }\n  };\n\n  appNavigationController.pushItem(navigationItem);\n\n  const getActiveStoryContainer = (el: Element = div) => {\n    return el.querySelector(`.${styles.ViewerStoryContainer}:not(.${styles.small})`) as HTMLElement;\n  };\n\n  const animate = (el: Element, forwards: boolean, done: () => void) => {\n    const container = getActiveStoryContainer(el);\n    if(!liteMode.isAvailable('animations') || !container) {\n      done();\n      return;\n    }\n\n    const containers = Array.from(el.querySelectorAll(`.${styles.ViewerStoryContainer}`));\n    let needAvatarOpacity: boolean;\n    const target = untrack(() => {\n      const target = props.target?.();\n      if(!target) {\n        return;\n      }\n\n      const overflowElement = findUpClassName(target, 'scrollable');\n      if(!overflowElement) {\n        return target;\n      }\n\n      const visibleRect = getVisibleRect(target as HTMLElement, overflowElement);\n      if(!visibleRect) {\n        if(avatarFrom) {\n          avatarFrom.node.remove();\n          avatarFrom = undefined;\n        }\n\n        return;\n      }\n\n      if(avatarFrom && (visibleRect.overflow.horizontal || visibleRect.overflow.vertical)) {\n        needAvatarOpacity = true;\n      }\n\n      return target;\n    });\n    const rectFrom = target && (target.querySelector('.avatar') || target).getBoundingClientRect();\n    const rectTo = container.getBoundingClientRect();\n    const borderRadius = avatarFrom ? '50%' : window.getComputedStyle(container).borderRadius;\n\n    // ! manually reverse the keyframes because Safari treats `direction: reverse` with lags\n    const makeKeyframes = (keyframes: Keyframe[]) => {\n      if(!forwards) {\n        keyframes.reverse();\n      }\n\n      return keyframes;\n    };\n\n    const options: KeyframeAnimationOptions = {\n      duration: 250,\n      easing: 'cubic-bezier(0.4, 0.0, 0.6, 1)'\n      // direction: forwards ? 'normal' : 'reverse'\n    };\n\n    // * animate avatar movement\n    let avatarAnimation: Animation, avatar: HTMLElement;\n    if(avatarFrom) {\n      avatar = container.querySelector<HTMLElement>(`.${styles.ViewerStoryHeaderAvatar}`);\n      avatar.style.visibility = 'hidden';\n      // const rectFrom = props.target.querySelector('.avatar').getBoundingClientRect();\n      const rectTo = avatar.getBoundingClientRect();\n      avatarFrom.node.style.top = `${rectFrom.top}px`;\n      avatarFrom.node.style.left = `${rectFrom.left}px`;\n      avatarFrom.node.style.visibility = '';\n      if(!avatarFrom.node.parentElement) {\n        getOverlayRoot().append(avatarFrom.node);\n      }\n      const translateX = rectTo.left - rectFrom.left;\n      const translateY = rectTo.top - rectFrom.top;\n\n      const keyframes: Keyframe[] = makeKeyframes([{\n        transform: `translate(0, 0) scale(${rectFrom.width / STORY_HEADER_AVATAR_SIZE})`\n      }, {\n        transform: `translate(${translateX}px, ${translateY}px) scale(1)`\n      }]);\n\n      if(needAvatarOpacity) {\n        keyframes[0].opacity = 0;\n        keyframes[1].opacity = 1;\n      }\n\n      avatarAnimation = avatarFrom.node.animate(keyframes, options);\n    }\n\n    const setOverflow = (overflow: boolean) => {\n      // container.style.overflow = overflow ? 'visible' : '';\n    };\n\n    if(!forwards) {\n      setOverflow(false);\n    }\n\n    // * animate main container\n    const translateX = rectFrom && rectFrom.left - (windowSize.width / 2) + rectFrom.width / 2;\n    const translateY = rectFrom && rectFrom.top - (windowSize.height / 2) + rectFrom.height / 2;\n    const containerAnimation = rectFrom && container.animate(makeKeyframes([{\n      borderRadius,\n      transform: `translate3d(${translateX}px, ${translateY}px, 0) scale3d(${rectFrom.width / rectTo.width}, ${rectFrom.height / rectTo.height}, 1)`,\n      opacity: 0\n    }, {\n      opacity: 1,\n      offset: 0.3\n    }, {\n      borderRadius: '0%',\n      transform: `translate3d(0, 0, 0) scale3d(1, 1, 1)`\n    }]), options);\n\n    // * animate simple opacity\n    const opacityAnimations = (containerAnimation ?\n      [backgroundDiv, !isFull() && closeButton].filter(Boolean) :\n      [container, el]\n    ).map((element) => {\n      return element.animate(makeKeyframes([{opacity: 0}, {opacity: 1}]), options);\n    });\n\n    // * animate small containers\n    const activeIndex = containers.indexOf(container);\n    containers.splice(activeIndex, 1);\n    const before = containers.slice(0, activeIndex);\n    const after = containers.slice(activeIndex);\n    const animateSmallContainers = (containers: Element[], next: boolean) => {\n      if(!rectFrom) {\n        return containers.map((container) => {\n          return container.animate(makeKeyframes([{opacity: 0}, {opacity: 1}]), options);\n        });\n      }\n\n      return containers.map((container, idx, arr) => {\n        const offsetX = (next ? idx + 1 : (arr.length - idx)) * 60 * (next ? -1 : 1);\n        return container.animate(makeKeyframes([{\n          transform: `translate3d(calc(var(--translateX) + ${offsetX}px), 0, 0) scale3d(${STORY_SCALE_SMALL / 2}, ${STORY_SCALE_SMALL / 2}, 1)`,\n          opacity: 0.001 // fix lag with fractal opacity so element should be prepared for animation\n        }, {\n          opacity: 0.001,\n          offset: 0.5\n        }, {\n          transform: `translate3d(var(--translateX), 0, 0) scale3d(${STORY_SCALE_SMALL}, ${STORY_SCALE_SMALL}, 1)`,\n          opacity: 1\n        }]), options);\n      })\n    };\n\n    const animations = [\n      ...opacityAnimations,\n      containerAnimation,\n      avatarAnimation,\n      ...animateSmallContainers(before, false),\n      ...animateSmallContainers(after, true)\n    ];\n\n    const promises = animations.map((animation) => animation?.finished);\n    return Promise.all(promises).then(() => {\n      if(avatarFrom) {\n        avatarFrom.node.remove();\n        avatar.style.visibility = '';\n      }\n\n      if(forwards) {\n        setOverflow(true);\n      }\n\n      done();\n    });\n  };\n\n  let overlaysActive: number;\n  const toggleOverlay = (active: boolean) => {\n    actions.toggleSorting('viewer', active);\n    overlayCounter.isDarkOverlayActive = active;\n    animationIntersector.checkAnimations2(active);\n\n    if(active) {\n      overlaysActive = overlayCounter.overlaysActive;\n    }\n  };\n\n  const listenerSetter = createListenerSetter();\n  let wasPlayingBeforeIdle: boolean;\n  listenerSetter.add(idleController)('change', (idle) => {\n    if(idle) {\n      wasPlayingBeforeIdle = !stories.paused;\n      actions.pause();\n      x.open();\n      return;\n    }\n\n    const onMouseDown = () => {\n      clearTimeout(timeout);\n    };\n\n    document.body.addEventListener('mousedown', onMouseDown, {once: true});\n    const timeout = setTimeout(() => {\n      document.body.removeEventListener('mousedown', onMouseDown);\n      x.close();\n    }, 100);\n\n    if(wasPlayingBeforeIdle) {\n      actions.play();\n    }\n  });\n\n  let wasPlayingBeforeOverlay: boolean;\n  listenerSetter.add(overlayCounter)('change', () => {\n    const active = overlayCounter.overlaysActive;\n    if(active > overlaysActive) {\n      wasPlayingBeforeOverlay = !stories.paused;\n      actions.pause();\n    } else if(active === overlaysActive && wasPlayingBeforeOverlay) {\n      actions.play();\n    }\n  });\n\n  let deferred: CancellablePromise<void> = deferredPromise<void>();\n\n  let animating = true;\n  return (\n    <Show when={wasShown()} fallback={ret}>\n      <Transition\n        onEnter={(el, done) => {\n          dispatchHeavyAnimationEvent(deferred, 1000);\n          disposeKeyDownListener = bindActiveWindowListener((w) => w.document.body, 'keydown', onKeyDown);\n          toggleOverlay(true);\n          animate(el, true, done);\n        }}\n        onAfterEnter={() => {\n          animating = false;\n          actions.viewerReady(true);\n          deferred.resolve();\n          // play();\n        }}\n        onExit={(el, done) => {\n          animating = true;\n          actions.viewerReady(false);\n          animate(el, false, done);\n        }}\n        onAfterExit={() => {\n          animating = false;\n          props.onExit?.();\n          stop();\n          deferred.resolve();\n        }}\n        appear\n      >\n        {show() && ret}\n      </Transition>\n    </Show>\n  );\n}\n\nexport const createStoriesViewerWithProvider = (\n  viewerProps: Parameters<typeof StoriesViewer>[0],\n  providerProps: Parameters<typeof StoriesProvider>[0]\n): JSX.Element => {\n  return createRoot((dispose) => {\n    const savedOnExit = viewerProps.onExit;\n    viewerProps.onExit = () => {\n      dispose();\n      savedOnExit?.();\n    };\n    return (\n      <StoriesProvider {...providerProps}>\n        {createStoriesViewer(viewerProps)}\n      </StoriesProvider>\n    );\n  });\n};\n\nexport const createStoriesViewer = (\n  props: Parameters<typeof StoriesViewer>[0] & Parameters<typeof StoriesProvider>[0]\n): JSX.Element => {\n  if(props.peers && !props.onExit) {\n    return createRoot((dispose) => {\n      props.onExit = () => dispose();\n      return (\n        <StoriesProvider peers={props.peers} index={props.index}>\n          {createStoriesViewer(props)}\n        </StoriesProvider>\n      );\n    });\n  }\n\n  return (\n    <Portal mount={document.getElementById('stories-viewer')}>\n      <StoriesViewer {...props} />\n    </Portal>\n  );\n};\n\nexport const createStoriesViewerWithStory = (\n  props: Omit<Parameters<typeof createStoriesViewer>[0], 'peers' | 'index'> & {\n    peerId: PeerId,\n    storyItem: StoryItem\n  }\n) => {\n  const [, rest] = splitProps(props, ['peerId', 'storyItem']);\n  return createStoriesViewer({\n    ...rest,\n    peers: [{\n      peerId: props.peerId,\n      stories: [props.storyItem],\n      index: 0,\n      count: 1\n    }],\n    index: 0\n  });\n};\n\nexport const createStoriesViewerWithPeer = async(\n  props: Omit<Parameters<typeof createStoriesViewer>[0], 'peers' | 'index'> & {\n    peerId: PeerId,\n    id?: number,\n  }\n): Promise<void> => {\n  const [, rest] = splitProps(props, ['peerId', 'id']);\n  const peerStories = await rootScope.managers.appStoriesManager.getPeerStories(props.peerId);\n  const storyIndex = props.id ? peerStories.stories.findIndex((story) => story.id === props.id) : undefined;\n  if(props.id) {\n    const storyItem = await rootScope.managers.appStoriesManager.getStoryById(props.peerId, props.id);\n    if(!storyItem) {\n      toastNew({langPackKey: 'Story.ExpiredToast'});\n      return;\n    }\n    // if(storyItem) { // own story can be missed in PeerStories\n    //   return createStoriesViewerWithPeer(props);\n    // }\n\n    createStoriesViewerWithStory({\n      ...rest,\n      peerId: props.peerId,\n      storyItem,\n      singleStory: true\n    });\n    return;\n  }\n\n  createStoriesViewer({\n    ...rest,\n    peers: [{\n      peerId: props.peerId,\n      stories: peerStories.stories,\n      maxReadId: peerStories.max_read_id,\n      index: storyIndex,\n      count: peerStories.stories.length\n    }],\n    index: 0\n  });\n};\n\n// export const openStories = (target?: Parameters<typeof StoriesViewer>[0]['target'], onExit?: () => void) => {\n//   const dispose = render(\n//     () => (\n//       <StoriesProvider stories={[]}>\n//         <StoriesViewer onExit={() => {dispose(); onExit?.();}} target={target} />\n//       </StoriesProvider>\n//     ),\n//     document.getElementById('stories-viewer')\n//   );\n// };\n","import type TChart from '@lib/tchart/chart';\nimport type {TChartData, TChatOriginalData} from '@lib/tchart/types';\nimport {Message, MessagesMessages, PostInteractionCounters, PublicForward, StatsAbsValueAndPrev, StatsBroadcastStats, StatsGraph, StatsGroupTopAdmin, StatsGroupTopInviter, StatsGroupTopPoster, StatsMegagroupStats, StatsMessageStats, StatsPercentValue, StatsPublicForwards, StatsStoryStats, StoryItem} from '@layer';\nimport I18n, {LangPackKey, i18n, join, joinElementsWith} from '@lib/langPack';\nimport Section from '@components/section';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {For, render} from 'solid-js/web';\nimport {Accessor, JSX, Show, createEffect, createRoot, createSignal, onMount} from 'solid-js';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {FontFamily} from '@config/font';\nimport {DcId, PickByType} from '@types';\nimport rootScope from '@lib/rootScope';\nimport customProperties from '@helpers/dom/customProperties';\nimport {hexToRgb, mixColors} from '@helpers/color';\nimport emptyPlaceholder from '@components/emptyPlaceholder';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport liteMode from '@helpers/liteMode';\nimport classNames from '@helpers/string/classNames';\nimport Icon from '@components/icon';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport Row from '@components/row';\nimport {wrapReplyDivAndCaption} from '@components/chat/replyContainer';\nimport {formatFullSentTime} from '@helpers/date';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {wrapStoryMedia} from '@components/stories/preview';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport Button from '@components/buttonTsx';\nimport themeController from '@helpers/themeController';\nimport assumeType from '@helpers/assumeType';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport appImManager from '@lib/appImManager';\nimport {createStoriesViewerWithPeer} from '@components/stories/viewer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {avatarNew} from '@components/avatarNew';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\nconst CHANNEL_GRAPHS_TITLES: {[key in keyof PickByType<StatsBroadcastStats, StatsGraph>]: LangPackKey} = {\n  growth_graph: 'GrowthChartTitle',\n  followers_graph: 'FollowersChartTitle',\n  mute_graph: 'Notifications',\n  top_hours_graph: 'TopHoursChartTitle',\n  views_by_source_graph: 'ViewsBySourceChartTitle',\n  new_followers_by_source_graph: 'NewFollowersBySourceChartTitle',\n  languages_graph: 'LanguagesChartTitle',\n  interactions_graph: 'InteractionsChartTitle',\n  iv_interactions_graph: 'IVInteractionsChartTitle',\n  reactions_by_emotion_graph: 'ReactionsByEmotionChartTitle',\n  story_interactions_graph: 'StoryInteractionsChartTitle',\n  story_reactions_by_emotion_graph: 'StoryReactionsByEmotionChartTitle'\n};\n\nconst GROUP_GRAPH_TITLES: {[key in keyof PickByType<StatsMegagroupStats, StatsGraph>]: LangPackKey} = {\n  growth_graph: 'GrowthChartTitle',\n  members_graph: 'GroupMembersChartTitle',\n  new_members_by_source_graph: 'NewMembersBySourceChartTitle',\n  languages_graph: 'MembersLanguageChartTitle',\n  messages_graph: 'MessagesChartTitle',\n  actions_graph: 'ActionsChartTitle',\n  top_hours_graph: 'TopHoursChartTitle',\n  weekdays_graph: 'TopDaysOfWeekChartTitle'\n};\n\nconst MESSAGE_GRAPH_TITLES: {[key in keyof PickByType<StatsMessageStats, StatsGraph>]: LangPackKey} = {\n  views_graph: 'ViewsAndSharesChartTitle',\n  reactions_by_emotion_graph: 'ReactionsByEmotionChartTitle'\n};\n\nconst STORY_GRAPH_TITLES = MESSAGE_GRAPH_TITLES;\n\nconst CHANNEL_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsBroadcastStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  followers: 'FollowersChartTitle',\n  enabled_notifications: 'EnabledNotifications',\n  views_per_post: 'ViewsPerPost',\n  views_per_story: 'ViewsPerStory',\n  shares_per_post: 'SharesPerPost',\n  shares_per_story: 'SharesPerStory',\n  reactions_per_post: 'ReactionsPerPost',\n  reactions_per_story: 'ReactionsPerStory'\n};\n\nconst GROUP_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsMegagroupStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  members: 'MembersOverviewTitle',\n  messages: 'MessagesOverview',\n  viewers: 'ViewingMembers',\n  posters: 'PostingMembers'\n};\n\nconst MESSAGE_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsMessageStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  views: 'StatisticViews',\n  public_shares: 'PublicShares',\n  reactions: 'Reactions',\n  private_shares: 'PrivateShares'\n};\n\nconst STORY_OVERVIEW_ITEMS = MESSAGE_OVERVIEW_ITEMS;\n\nlet TChartPromise: Promise<any>;\nlet _TChart: typeof TChart;\nfunction ensureTChart() {\n  return TChartPromise ??= import('../../../lib/tchart/chart').then((module) => {\n    _TChart = module.default;\n  });\n}\n\nfunction extractColor(color: string): string {\n  return color.substring(color.indexOf('#'));\n}\n\nexport const makeAbsStats = (value: number, approximate?: boolean): StatsAbsValueAndPrev => {\n  return {\n    _: 'statsAbsValueAndPrev',\n    current: value,\n    previous: 0,\n    approximate\n  };\n};\n\nexport type LoadableList<T extends any = any> = {rendered: (HTMLElement | JSX.Element)[], values: T[], left: number, count: number, loadMore?: () => Promise<void>};\nexport const createLoadableList = <T extends any = any>(props: Partial<LoadableList<T>> = {}) => {\n  return createSignal<LoadableList<T>>({\n    rendered: [],\n    values: [],\n    left: 0,\n    count: 0,\n    ...props\n  }, {equals: false});\n};\n\nexport const MoreButton = (props: {\n  count: number,\n  callback: Parameters<typeof Button>[0]['onClick'],\n  key?: LangPackKey\n}) => {\n  return (\n    <Button\n      text={props.key || 'PollResults.LoadMore'}\n      textArgs={[props.count]}\n      onClick={(e) => props.callback(e)}\n      class=\"btn btn-primary btn-transparent primary\"\n      icon=\"down\"\n    />\n  );\n};\n\nconst StatisticsOverviewItem = ({\n  value,\n  title,\n  includeZeroValue,\n  describePercentage\n}: {\n  value: StatsAbsValueAndPrev | StatsPercentValue,\n  title: LangPackKey,\n  includeZeroValue?: boolean,\n  describePercentage?: boolean\n}) => {\n  const isPercentage = value._ === 'statsPercentValue';\n  let v: JSX.Element;\n  if(isPercentage) {\n    const n = (value.part / value.total * 100).toFixed(2);\n    v = `${n}%`;\n\n    if(describePercentage) {\n      v = (\n        <>\n          {`≈${value.part} `}\n          <span class=\"statistics-overview-item-value-description\">\n            {v}\n          </span>\n        </>\n      );\n    }\n  } else {\n    v = formatNumber(value.current, 1);\n\n    if(value.approximate) {\n      v = '≈' + v;\n    }\n\n    if(!value.current && !value.previous && !includeZeroValue) {\n      return;\n    }\n\n    if(value.current !== value.previous && value.previous) {\n      const diff = value.current - value.previous;\n      const absDiff = Math.abs(diff);\n      const vv = `${diff > 0 ? '+' : '-'}${formatNumber(absDiff, 1)}`;\n      const p = +(Math.abs(1 - value.current / value.previous) * 100).toFixed(2);\n      const str = `${vv} (${p}%)`;\n      v = (\n        <>\n          {v}{' '}\n          <span\n            class={classNames('statistics-overview-item-value-description', diff > 0 ? 'green' : 'red')}\n          >\n            {str}\n          </span>\n        </>\n      );\n    }\n  }\n\n  return (\n    <div class=\"statistics-overview-item\">\n      <div class=\"statistics-overview-item-value\">\n        {v}\n      </div>\n      <div class=\"statistics-overview-item-name\">\n        {i18n(title)}\n      </div>\n    </div>\n  );\n};\n\nexport const StatisticsOverviewItems = (props: {\n  items: Parameters<typeof StatisticsOverviewItem>[0][]\n}) => {\n  return (\n    <div class=\"statistics-overview\">\n      <For each={props.items}>{StatisticsOverviewItem}</For>\n    </div>\n  );\n};\n\nexport default class AppStatisticsTab extends SliderSuperTabEventable {\n  private chatId: ChatId;\n  private mid: number;\n  private storyId: number;\n  private stats: StatsBroadcastStats | StatsMegagroupStats | StatsMessageStats | StatsStoryStats;\n  private messages: Map<number, Message.message>;\n  private stories: Map<number, StoryItem.storyItem>;\n  private dcId: DcId;\n  private openPromise: CancellablePromise<void>;\n  private isBroadcast: boolean;\n  private isMegagroup: boolean;\n  private isMessage: boolean;\n  private isStory: boolean;\n\n  protected onOpenAfterTimeout(): void {\n    this.openPromise.resolve();\n  }\n\n  private _construct(\n    recentPosts: {container: HTMLElement, postInteractionCounters: PostInteractionCounters}[],\n    topPosters: {container: HTMLElement, peerId: PeerId}[],\n    topAdmins: {container: HTMLElement, peerId: PeerId}[],\n    topInviters: {container: HTMLElement, peerId: PeerId}[],\n    publicForwards: Accessor<LoadableList>,\n    currentPost: (typeof recentPosts)[0]\n  ) {\n    const dateElement = new I18n.IntlDateElement({options: {}});\n    const getLabelDate: TChartData['getLabelDate'] = (value, options = {}) => {\n      options.displayYear ??= true;\n      options.isMonthShort ??= true;\n\n      const date = new Date(value);\n      dateElement.update({\n        date,\n        options: {\n          weekday: options.displayWeekDay ? options.isShort ? 'short' : 'long' : undefined,\n          year: options.displayYear ? 'numeric' : undefined,\n          hour: options.displayHours ? '2-digit' : undefined,\n          minute: options.displayHours ? '2-digit' : undefined,\n          month: options.isMonthShort ? 'short' : 'long',\n          day: 'numeric'\n        }\n      });\n\n      return dateElement.element.textContent;\n    };\n\n    const getLabelTime: TChartData['getLabelTime'] = (value: number) => {\n      const date = new Date(value);\n      dateElement.update({\n        date,\n        options: {\n          hour: '2-digit',\n          minute: '2-digit'\n        }\n      });\n\n      return dateElement.element.textContent;\n    };\n\n    const makeColors = () => {\n      const surface = customProperties.getProperty('surface-color');\n      const primary = customProperties.getProperty('primary-color');\n      const secondary = customProperties.getProperty('secondary-color');\n      const surfaceRgb = hexToRgb(surface);\n\n      const miniMask = mixColors(\n        hexToRgb(secondary),\n        mixColors(\n          hexToRgb(primary),\n          surfaceRgb,\n          0.1\n        ),\n        0.2\n      );\n\n      const miniFrame = mixColors(\n        hexToRgb(secondary),\n        mixColors(\n          hexToRgb(primary),\n          surfaceRgb,\n          0.3\n        ),\n        0.4\n      );\n\n      const colors: ConstructorParameters<typeof TChart>[0]['settings']['COLORS'] = {\n        primary: customProperties.getProperty('primary-color'),\n        secondary: customProperties.getProperty('secondary-color'),\n        background: surface,\n        backgroundRgb: surfaceRgb,\n        text: customProperties.getProperty('primary-text-color'),\n        dates: customProperties.getProperty('secondary-text-color'),\n        grid: `rgba(${hexToRgb(customProperties.getProperty('secondary-text-color')).join(', ')}, 0.2)`,\n        axis: {\n          x: customProperties.getProperty('secondary-text-color'),\n          y: customProperties.getProperty('secondary-text-color')\n        },\n        barsSelectionBackground: `rgba(${surfaceRgb.join(', ')}, 0.5)`,\n        miniMask: `rgba(${miniMask.join(', ')}, 0.6)`,\n        miniFrame: `rgb(${miniFrame.join(', ')})`\n      };\n\n      return colors;\n    };\n    let colors = makeColors();\n    this.listenerSetter.add(rootScope)('theme_changed', () => {\n      colors = makeColors();\n    });\n\n    const titles = this.isBroadcast ? CHANNEL_GRAPHS_TITLES : (this.isMegagroup ? GROUP_GRAPH_TITLES : (this.isStory ? STORY_GRAPH_TITLES : MESSAGE_GRAPH_TITLES));\n    const graphs: {statsGraph: StatsGraph.statsGraph, title: LangPackKey, percentage: boolean}[] = Object.keys(titles).map((key) => {\n      const statsGraph = this.stats[key as keyof typeof titles];\n      return statsGraph && {\n        statsGraph,\n        title: titles[key as keyof typeof titles],\n        percentage: (key as keyof typeof titles) === 'languages_graph'\n      };\n    }).filter(Boolean);\n    const renderGraph = ({statsGraph, title, percentage}: typeof graphs[0]) => {\n      onMount(() => {\n        let data: TChatOriginalData = JSON.parse(statsGraph.json.data);\n        // console.log('data', JSON.parse(statsGraph.json.data));\n\n        const prepareData = (data: TChatOriginalData, percentage?: boolean) => {\n          for(const i in data.colors) {\n            const color = data.colors[i];\n            data.colors[i] = extractColor(color);\n          }\n\n          if(percentage) for(const i in data.types) {\n            if(data.types[i] === 'bar') {\n              data.types[i] = 'area';\n            }\n          }\n\n          return data;\n        };\n\n        data = prepareData(data, percentage);\n\n        type T = ConstructorParameters<typeof TChart>[0]['data'];\n        const addOptions: Partial<T> = {\n          getLabelDate,\n          getLabelTime,\n          tooltipOnHover: true\n        };\n\n        const zoomToken = statsGraph.zoom_token;\n        const tChart = _TChart.render({\n          container,\n          data: {\n            ...data,\n            ...addOptions,\n            x_on_zoom: zoomToken ? async(x) => {\n              const statsGraph = await this.managers.appStatisticsManager.loadAsyncGraph(zoomToken, x, this.dcId);\n              if(statsGraph._ === 'statsGraphError') {\n                return;\n              }\n\n              // console.log('zoom data', JSON.parse((statsGraph as StatsGraph.statsGraph).json.data));\n\n              return {\n                ...prepareData(JSON.parse((statsGraph as StatsGraph.statsGraph).json.data), percentage),\n                ...addOptions\n              };\n            } : undefined\n          } as T,\n          settings: {\n            darkMode: themeController.isNight(),\n            ALL_LABEL: I18n.format('Chart.Tooltip.All', true),\n            DATES_SIDE: 'left',\n            DATES_WEIGHT: 'normal',\n            DATES_FONT_SIZE: 14,\n            ZOOM_TEXT: I18n.format('ZoomOut', true),\n            FONT: {\n              family: FontFamily,\n              bold: '500',\n              normal: '400'\n            },\n            COLORS: colors\n          }\n        });\n\n        const setStyles = () => {\n          const p: [property: string, value: string][] = [\n            ['primary-color', colors.primary],\n            ['background-color', colors.background],\n            ['background-color-rgb', colors.backgroundRgb.join(', ')],\n            ['text-color', colors.text],\n            ['secondary-color', colors.secondary],\n            ['font-family', FontFamily]\n          ];\n\n          p.forEach(([property, value]) => {\n            tChart.$wrapper.style.setProperty(`--tchart-${property}`, value);\n          });\n        };\n\n        setStyles();\n\n        this.listenerSetter.add(rootScope)('theme_changed', () => {\n          tChart.setDarkMode(themeController.isNight(), {...colors});\n          setStyles();\n        });\n      });\n\n      const titleElement = document.createElement('div');\n      const captionElement = document.createElement('div');\n      titleElement.classList.add('statistics-title');\n      const t = i18n(title);\n      t.classList.add('statistics-title-text');\n      titleElement.append(t);\n      // let zoomOutElement: HTMLElement;\n      // if(graph.zoomToken || graph.isPercentage) {\n      //   zoomOutElement = document.createElement('div');\n      //   zoomOutElement.classList.add('statistics-title-zoom');\n      //   zoomOutElement.append(Icon('zoomout', 'statistics-title-zoom-icon'), i18n('ZoomOut'));\n      //   titleElement.append(zoomOutElement);\n      // }\n      let container: HTMLDivElement;\n      return (\n        <Section name={titleElement} nameRight={captionElement}>\n          <div class=\"statistics-chart\" ref={container}></div>\n        </Section>\n      );\n    };\n\n    const overviewTitles = this.stats._ === 'stats.broadcastStats' ? CHANNEL_OVERVIEW_ITEMS : (this.isMegagroup ? GROUP_OVERVIEW_ITEMS : (this.isStory ? STORY_OVERVIEW_ITEMS : MESSAGE_OVERVIEW_ITEMS));\n    const overviewItems: {value: StatsAbsValueAndPrev | StatsPercentValue, title: LangPackKey}[] = Object.keys(overviewTitles).map((key) => {\n      const value = this.stats[key as keyof typeof overviewTitles];\n      return value && {\n        value,\n        title: overviewTitles[key as keyof typeof overviewTitles]\n      };\n    }).filter(Boolean);\n\n    const formatDateRange = (min: number, max: number) => {\n      return joinElementsWith([min, max].map((timestamp) => {\n        return new I18n.IntlDateElement({\n          date: new Date(timestamp * 1e3),\n          options: {\n            month: 'short',\n            day: 'numeric',\n            year: 'numeric'\n          }\n        }).element;\n      }), ' — ');\n    };\n\n    const period = (this.stats as StatsBroadcastStats).period;\n    const topPeersTitles: [LangPackKey, LangPackKey, LangPackKey] = ['TopMembers', 'TopAdmins', 'TopInviters'];\n    let postsContainer: HTMLDivElement;\n    const ret = (\n      <>\n        {currentPost && <Section>{currentPost.container}</Section>}\n        <Section name=\"StatisticOverview\" nameRight={period && formatDateRange(period.min_date, period.max_date)}>\n          <StatisticsOverviewItems items={overviewItems} />\n        </Section>\n        <For each={graphs}>{renderGraph}</For>\n        {recentPosts.length && <Section ref={postsContainer} name=\"RecentPosts\">\n          {recentPosts.map(({container}) => container)}\n        </Section>}\n        <For each={[topPosters, topAdmins, topInviters]}>{(topPeers, idx) => {\n          if(!topPeers.length) {\n            return;\n          }\n\n          topPeers = topPeers.slice();\n\n          const chatlist = appDialogsManager.createChatList();\n          chatlist.append(...topPeers.splice(0, 10).map(({container}) => container));\n          const [moreButton, setMoreButton] = createSignal<JSX.Element>(topPeers.length && MoreButton({\n            count: topPeers.length,\n            callback: () => {\n              setMoreButton(undefined);\n              chatlist.append(...topPeers.map(({container}) => container));\n            }\n          }));\n          return (\n            <Section name={topPeersTitles[idx()]} nameRight={period && formatDateRange(period.min_date, period.max_date)}>\n              {chatlist}\n              {moreButton()}\n            </Section>\n          );\n        }}</For>\n        {publicForwards().count && <Section name=\"PublicSharesCount\" nameArgs={[publicForwards().count]}>\n          <div\n            ref={(el) => {\n              appDialogsManager.setListClickListener({\n                list: el,\n                onFound: (target) => {\n                  const storyId = target.dataset.storyId;\n                  if(storyId) {\n                    createStoriesViewerWithPeer({\n                      target: () => target.querySelector('.avatar'),\n                      peerId: target.dataset.peerId.toPeerId(),\n                      id: +target.dataset.storyId\n                    });\n                    return false;\n                  }\n                },\n                withContext: undefined,\n                autonomous: undefined,\n                openInner: true\n              });\n            }}\n          >\n            {publicForwards().rendered}\n          </div>\n          <Show when={!!publicForwards().loadMore}>\n            <MoreButton\n              count={publicForwards().count - publicForwards().rendered.length}\n              callback={() => publicForwards().loadMore()}\n            />\n          </Show>\n        </Section>}\n      </>\n    );\n\n    if(postsContainer) {\n      const map: Map<HTMLElement, PostInteractionCounters> = new Map();\n      recentPosts.forEach(({container, postInteractionCounters}) => {\n        map.set(container, postInteractionCounters);\n      });\n\n      const findTarget = (e: MouseEvent | TouchEvent) => findUpClassName(e.target, 'statistics-post');\n      let counters: PostInteractionCounters;\n\n      const onOpenClick = () => {\n        this.slider.createTab(AppStatisticsTab).open(\n          this.chatId,\n          (counters as PostInteractionCounters.postInteractionCountersMessage).msg_id,\n          (counters as PostInteractionCounters.postInteractionCountersStory).story_id\n        );\n      };\n\n      attachClickEvent(postsContainer, (e) => {\n        counters = map.get(findTarget(e));\n        if(!counters) {\n          return;\n        }\n\n        onOpenClick();\n      }, {listenerSetter: this.listenerSetter});\n\n      createContextMenu({\n        buttons: [{\n          icon: 'statistics',\n          text: 'ViewStatistics',\n          onClick: onOpenClick\n        }, {\n          icon: 'message',\n          text: 'Message.Context.Goto',\n          onClick: () => {\n            appImManager.setInnerPeer({\n              peerId: this.chatId.toPeerId(true),\n              lastMsgId: (counters as PostInteractionCounters.postInteractionCountersMessage).msg_id\n            });\n          },\n          verify: () => counters._ === 'postInteractionCountersMessage'\n        }, {\n          icon: 'stories',\n          text: 'ViewStory',\n          onClick: () => {\n            createStoriesViewerWithPeer({\n              peerId: this.chatId.toPeerId(true),\n              id: (counters as PostInteractionCounters.postInteractionCountersStory).story_id\n            });\n          },\n          verify: () => counters._ === 'postInteractionCountersStory'\n        }],\n        listenTo: postsContainer,\n        listenerSetter: this.listenerSetter,\n        findElement: (e) => {\n          const target = findTarget(e);\n          counters = map.get(target);\n          return target;\n        },\n        middleware: this.middlewareHelper.get()\n      });\n    }\n\n    return ret;\n  }\n\n  private async renderRecentPost(\n    postInteractionCounters: PostInteractionCounters,\n    peerId: PeerId = this.chatId.toPeerId(true),\n    message?: Message.message,\n    storyItem?: StoryItem.storyItem,\n    noLabels?: boolean\n  ) {\n    const subtitleRightFragment = document.createDocumentFragment();\n    const a: [Icon, number][] = [\n      ['reactions', postInteractionCounters.reactions],\n      ['reply', postInteractionCounters.forwards]\n    ];\n\n    !noLabels && a.forEach(([icon, count]) => {\n      if(!count) {\n        return;\n      }\n\n      const i = Icon(icon, 'statistics-post-counter-icon');\n      if(icon === 'reply') {\n        i.classList.add('icon-reflect');\n      }\n\n      const e = document.createElement('span');\n      e.classList.add('statistics-post-counter');\n      e.append(i, formatNumber(count, 1));\n      subtitleRightFragment.append(e);\n    });\n\n    const row = new Row({\n      title: true,\n      titleRight: noLabels ? undefined : i18n('Views', [numberThousandSplitter(postInteractionCounters.views)]),\n      subtitle: true,\n      subtitleRight: noLabels ? undefined : subtitleRightFragment,\n      clickable: true,\n      noWrap: true,\n      asLink: !!(message || storyItem)\n    });\n\n    const {container} = row;\n    container.classList.add('statistics-post');\n\n    row.title.classList.add('statistics-post-title');\n\n    const middleware = this.middlewareHelper.get();\n    const mediaEl = document.createElement('div');\n    mediaEl.classList.add('statistics-post-media');\n    if(message || storyItem) {\n      const {node, readyThumbPromise, setStoriesSegments} = avatarNew({\n        middleware,\n        size: 42,\n        isDialog: true,\n        peerId\n      });\n\n      row.container.dataset.peerId = '' + peerId;\n      if(storyItem) {\n        setStoriesSegments([{length: 1, type: 'unread'}]);\n        row.container.dataset.storyId = '' + storyItem.id;\n      } else {\n        row.container.dataset.mid = '' + message.mid;\n      }\n\n      mediaEl.append(node);\n      await readyThumbPromise;\n      row.title.append(await wrapPeerTitle({peerId}));\n      row.subtitle.append(formatFullSentTime(message?.date || storyItem?.date));\n      row.applyMediaElement(mediaEl, 'abitbigger');\n    } else if(postInteractionCounters._ === 'postInteractionCountersMessage') {\n      container.classList.add('statistics-post-message');\n      message ||= this.messages.get(postInteractionCounters.msg_id);\n      const isMediaSet = await wrapReplyDivAndCaption({\n        titleEl: row.subtitle,\n        title: formatFullSentTime(message.date),\n        subtitleEl: row.title,\n        message,\n        mediaEl,\n        middleware,\n        withoutMediaType: true\n      });\n\n      if(!isMediaSet) {\n        const {node, readyThumbPromise} = avatarNew({middleware, peerId, size: 42});\n        mediaEl.append(node);\n        await readyThumbPromise;\n      }\n\n      row.applyMediaElement(mediaEl, 'abitbigger');\n    } else {\n      container.classList.add('statistics-post-story');\n      storyItem ||= this.stories.get(postInteractionCounters.story_id);\n      row.title.append(i18n('Story'));\n      row.subtitle.append(formatFullSentTime(storyItem.date));\n\n      const border = document.createElement('div');\n      border.classList.add('avatar-stories-simple', 'is-unread');\n      mediaEl.append(border);\n\n      await createRoot((dispose) => {\n        middleware.onDestroy(dispose);\n        const {ready, div} = wrapStoryMedia({\n          storyItem,\n          peerId: this.chatId.toPeerId(true),\n          forPreview: true,\n          noInfo: true,\n          withPreloader: false,\n          noAspecter: true\n        });\n\n        const deferred = deferredPromise<void>();\n\n        createEffect(() => {\n          if(ready()) {\n            mediaEl.append(div);\n            deferred.resolve();\n          }\n        });\n\n        return deferred;\n      });\n\n      row.applyMediaElement(mediaEl, 'abitbigger');\n    }\n\n    return {container, postInteractionCounters};\n  }\n\n  private renderPeer = async(peer: StatsGroupTopPoster | StatsGroupTopAdmin | StatsGroupTopInviter | Message.message) => {\n    const peerId = peer._ === 'message' ? peer.peerId : peer.user_id.toPeerId(false);\n    const loadPromises: Promise<any>[] = [];\n    const {dom} = appDialogsManager.addDialogNew({\n      peerId: peerId,\n      container: false,\n      rippleEnabled: true,\n      avatarSize: 'abitbigger',\n      loadPromises,\n      wrapOptions: {\n        middleware: this.middlewareHelper.get()\n      },\n      meAsSaved: false\n    });\n\n    let toJoin: Node[];\n    if(peer._ === 'message') {\n      toJoin = [\n        await getChatMembersString(peerId.toChatId()),\n        i18n('Views', [formatNumber(peer.views, 1)])\n      ];\n      dom.listEl.dataset.mid = '' + peer.mid;\n    } else if(peer._ === 'statsGroupTopPoster') {\n      toJoin = [\n        peer.messages && i18n('messages', [peer.messages]),\n        peer.avg_chars && i18n('CharactersPerMessage', [i18n('Characters', [peer.avg_chars])])\n      ];\n    } else if(peer._ === 'statsGroupTopAdmin') {\n      toJoin = [\n        peer.deleted && i18n('Deletions', [peer.deleted]),\n        peer.banned && i18n('Bans', [peer.banned]),\n        peer.kicked && i18n('Restrictions', [peer.kicked])\n      ];\n    } else {\n      toJoin = [\n        peer.invitations && i18n('Invitations', [peer.invitations])\n      ];\n    }\n\n    toJoin = toJoin.filter(Boolean);\n    if(toJoin.length) {\n      dom.lastMessageSpan.replaceChildren(...join(toJoin, false));\n    }\n\n    await Promise.all(loadPromises);\n    return {container: dom.listEl, peerId};\n  };\n\n  private renderPublicForward = async(publicForward: PublicForward) => {\n    if(publicForward._ === 'publicForwardMessage') {\n      const message = publicForward.message as Message.message;\n      return this.renderRecentPost({\n        _: 'postInteractionCountersMessage',\n        forwards: message.forwards,\n        msg_id: message.mid,\n        views: message.views,\n        reactions: message.reactions ? message.reactions.results.reduce((acc, v) => acc + v.count, 0) : 0\n      }, message.peerId, message);\n    }\n\n    const storyItem = publicForward.story as StoryItem.storyItem;\n    if(!storyItem) {\n      return;\n    }\n\n    const storyViews = storyItem.views;\n    return this.renderRecentPost({\n      _: 'postInteractionCountersStory',\n      forwards: storyViews?.forwards_count || 0,\n      story_id: storyItem.id,\n      views: storyViews?.views_count || 0,\n      reactions: storyViews?.reactions_count || 0\n    }, getPeerId(publicForward.peer), undefined, storyItem);\n  };\n\n  private async loadStats() {\n    const peerId = this.chatId.toPeerId(true);\n    const manager = this.managers.appStatisticsManager;\n    const loadLimit = 100;\n    const func = this.isBroadcast ? manager.getBroadcastStats : (this.isMegagroup ? manager.getMegagroupStats : (this.isStory ? manager.getStoryStats : manager.getMessageStats));\n    const postPromise = this.isMessage ? this.managers.appMessagesManager.reloadMessage(peerId, this.mid) : undefined;\n    const postPublicForwardsPromise = this.isMessage ? manager.getMessagePublicForwards({peerId, mid: this.mid, limit: loadLimit}) : undefined;\n    const storyPromise = this.isStory ? this.managers.appStoriesManager.getStoryById(peerId, this.storyId) : undefined;\n    const storyPublicForwardsPromise = this.isStory ? manager.getStoryPublicForwards({peerId, id: this.storyId, limit: loadLimit}) : undefined;\n    const {stats, dcId} = await func({\n      peerId,\n      dark: themeController.isNight(),\n      storyId: this.storyId,\n      mid: this.mid\n    });\n    this.stats = stats;\n    this.dcId = dcId;\n\n    const promises: PromiseLike<any>[] = [];\n    for(const key in stats) {\n      const value = stats[key as keyof typeof stats] as any as StatsGraph;\n      if(value._ === 'statsGraphAsync') {\n        const promise = manager.loadAsyncGraph(\n          value.token,\n          undefined,\n          dcId\n        ).then((statsGraph) => {\n          if(statsGraph._ === 'statsGraphError') {\n            delete stats[key as keyof typeof stats];\n            return;\n          }\n\n          stats[key as keyof typeof stats] = statsGraph as any;\n        });\n        promises.push(promise);\n      } else if(value._ === 'statsGraphError') {\n        delete stats[key as keyof typeof stats];\n      }\n    }\n\n    const recentPosts = (stats as StatsBroadcastStats).recent_posts_interactions || [];\n    recentPosts.forEach((postInteractionCounters) => {\n      let promise: PromiseLike<any>;\n      if(postInteractionCounters._ === 'postInteractionCountersMessage') {\n        promise = this.managers.appMessagesManager.reloadMessage(peerId, postInteractionCounters.msg_id)\n        .then((message) => {\n          if(!message) {\n            indexOfAndSplice(recentPosts, postInteractionCounters);\n            return;\n          }\n\n          this.messages.set(message.mid, message as Message.message);\n        });\n      } else {\n        promise = this.managers.appStoriesManager.getStoryById(peerId, postInteractionCounters.story_id)\n        .then((storyItem) => {\n          if(!storyItem) {\n            indexOfAndSplice(recentPosts, postInteractionCounters);\n            return;\n          }\n\n          this.stories.set(storyItem.id, storyItem);\n        });\n      }\n\n      promises.push(promise);\n    });\n\n    const renderedPublicForwards = Promise.all([\n      postPromise,\n      postPublicForwardsPromise,\n      storyPromise,\n      storyPublicForwardsPromise\n    ]).then(async([message, messagePublicForwards, storyItem, storyPublicForwards]) => {\n      const [f, setF] = createLoadableList();\n      if(!message && !storyItem) {\n        return f;\n      }\n\n      assumeType<StatsMessageStats | StatsStoryStats>(stats);\n\n      if(message) {\n        assumeType<Message.message>(message);\n        this.messages.set(message.mid, message);\n        const totalPublicForwards = messagePublicForwards.count;\n        stats.views = makeAbsStats(message.views);\n        stats.reactions = makeAbsStats(message.reactions ? message.reactions.results.reduce((acc, v) => acc + v.count, 0) : 0);\n        stats.public_shares = makeAbsStats(totalPublicForwards);\n        stats.private_shares = makeAbsStats(message.forwards - totalPublicForwards, true);\n\n        setF((value) => (value.count = totalPublicForwards, value));\n\n        let offset: string;\n        const r = async(statsPublicForwards: StatsPublicForwards.statsPublicForwards) => {\n          offset = statsPublicForwards.next_offset;\n\n          const promises = statsPublicForwards.forwards.map(this.renderPublicForward);\n          const rendered = await Promise.all(promises);\n          setF((value) => {\n            value.rendered.push(...rendered.map(({container}) => container));\n            value.loadMore = offset ? () => {\n              return manager.getMessagePublicForwards({\n                peerId,\n                mid: this.mid,\n                limit: loadLimit,\n                offset\n              }).then(r);\n            } : undefined;\n            return value;\n          });\n        };\n\n        await r(messagePublicForwards);\n      } else {\n        const totalPublicForwards = storyPublicForwards.count;\n        const storyViews = storyItem.views;\n        stats.views = makeAbsStats(storyViews.views_count);\n        stats.reactions = makeAbsStats(storyViews.reactions_count || 0);\n        stats.public_shares = makeAbsStats(totalPublicForwards);\n        stats.private_shares = makeAbsStats(Math.abs((storyViews.forwards_count || 0) - totalPublicForwards), true);\n\n        setF((value) => (value.count = totalPublicForwards, value));\n\n        let offset: string;\n        const r = async(statsPublicForwards: StatsPublicForwards.statsPublicForwards) => {\n          offset = statsPublicForwards.next_offset;\n\n          const promises = statsPublicForwards.forwards.map(this.renderPublicForward);\n          const rendered = await Promise.all(promises);\n          setF((value) => {\n            value.rendered.push(...rendered.map(({container}) => container));\n            value.loadMore = offset ? () => {\n              return manager.getStoryPublicForwards({\n                peerId,\n                id: storyItem.id,\n                limit: loadLimit,\n                offset\n              }).then(r);\n            } : undefined;\n            return value;\n          });\n        };\n\n        await r(storyPublicForwards);\n      }\n\n      return f;\n    });\n    promises.push(renderedPublicForwards);\n\n    const topPosters = (stats as StatsMegagroupStats).top_posters || [];\n    const topAdmins = (stats as StatsMegagroupStats).top_admins || [];\n    const topInvites = (stats as StatsMegagroupStats).top_inviters || [];\n    const renderedTopPosters = topPosters.map(this.renderPeer);\n    const renderedTopAdmins = topAdmins.map(this.renderPeer);\n    const renderedTopInviters = topInvites.map(this.renderPeer);\n\n    return Promise.all(promises).then(() => {\n      const recentPostsPromises = recentPosts.map((postInteractionCounters) => {\n        return this.renderRecentPost(postInteractionCounters);\n      });\n\n      const currentPostPromise = this.isMessage ? this.renderRecentPost({\n        _: 'postInteractionCountersMessage',\n        msg_id: this.mid,\n        forwards: 0,\n        reactions: 0,\n        views: 0\n      }, undefined, undefined, undefined, true) : undefined;\n\n      const promises = [\n        Promise.all(recentPostsPromises),\n        Promise.all(renderedTopPosters),\n        Promise.all(renderedTopAdmins),\n        Promise.all(renderedTopInviters),\n        renderedPublicForwards,\n        currentPostPromise\n      ] as const;\n\n      return Promise.all(promises);\n    });\n  }\n\n  public async init(chatId: ChatId, mid?: number, storyId?: number) {\n    this.container.classList.add('statistics-container');\n\n    this.chatId = chatId;\n    this.mid = mid;\n    this.storyId = storyId;\n    this.messages = new Map();\n    this.stories = new Map();\n    this.openPromise = deferredPromise<void>();\n\n    if(mid) {\n      this.isMessage = true;\n    } else if(storyId) {\n      this.isStory = true;\n    } else {\n      this.isBroadcast = await this.managers.appChatsManager.isBroadcast(chatId);\n      this.isMegagroup = await this.managers.appChatsManager.isMegagroup(chatId);\n    }\n\n    this.setTitle(this.isBroadcast ? 'Statistics' : (this.isMegagroup ? 'GroupStats.Title' : (this.isStory ? 'StoryStatistics' : 'PostStatistics')));\n\n    const promise = Promise.all([\n      ensureTChart(),\n      this.openPromise,\n      this.loadStats()\n    ]);\n\n    const [hide, setHide] = createSignal(false);\n\n    const element = await emptyPlaceholder({\n      title: () => i18n('LoadingStats'),\n      description: () => i18n('LoadingStatsDescription'),\n      assetName: 'StatsEmoji',\n      middleware: this.middlewareHelper.get(),\n      hide,\n      isFullSize: true\n    });\n\n    this.scrollable.append(element);\n    promise.then(async([_, __, loaded]) => {\n      const div = document.createElement('div');\n      this.scrollable.append(div);\n      const dispose = render(() => this._construct(...loaded), div);\n      this.eventListener.addEventListener('destroy', dispose);\n\n      if(liteMode.isAvailable('animations')) {\n        const keyframes: Keyframe[] = [{opacity: '1'}, {opacity: '0'}];\n        const options: KeyframeAnimationOptions = {duration: 200, fill: 'forwards', easing: 'ease-in-out'};\n        const animations = [\n          element.animate(keyframes, options),\n          div.animate(keyframes.slice().reverse(), options)\n        ];\n\n        await Promise.all(animations.map((animation) => animation.finished));\n      }\n\n      setHide(true);\n    });\n  }\n}\n","/* @refresh reload */\n\nimport PopupElement from '.';\nimport maybe2x from '@helpers/maybe2x';\nimport {InputInvoice, MessageMedia, PaymentsPaymentForm, Photo, Document, StarsTopupOption, StarsTransaction, StarsTransactionPeer, MessageExtendedMedia, ChatInvite, StarsSubscription, StarsGiftOption, InputStorePaymentPurpose, WebDocument} from '@layer';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport Section from '@components/section';\nimport {createMemo, createRoot, createSignal, For, JSX, Show, untrack} from 'solid-js';\nimport paymentsWrapCurrencyAmount, {formatNanoton} from '@helpers/paymentsWrapCurrencyAmount';\nimport classNames from '@helpers/string/classNames';\nimport PopupPayment from '@components/popups/payment';\nimport useStars, {prefetchStars} from '@stores/stars';\nimport safeAssign from '@helpers/object/safeAssign';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport {createLoadableList} from '@components/sidebarRight/tabs/statistics';\nimport Row from '@components/rowTsx';\nimport {formatFullSentTime} from '@helpers/date';\nimport {avatarNew} from '@components/avatarNew';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport Icon from '@components/icon';\nimport {Middleware} from '@helpers/middleware';\nimport generatePhotoForExtendedMediaPreview from '@appManagers/utils/photos/generatePhotoForExtendedMediaPreview';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport wrapPhoto from '@components/wrappers/photo';\nimport currencyStarIcon from '@components/currencyStarIcon';\nimport {wrapChatInviteAvatar, wrapChatInviteTitle} from '@components/popups/joinChatInvite';\nimport tsNow from '@helpers/tsNow';\nimport Button from '@components/buttonTsx';\nimport showPickUserPopup, {showContactPickerPopup} from '@components/popups/pickUser';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport rootScope from '@lib/rootScope';\nimport appImManager from '@lib/appImManager';\nimport {toastNew} from '@components/toast';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {MoreButton} from '@components/sidebarRight/tabs/statistics';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport bigInt from 'big-integer';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport {IconTsx} from '@components/iconTsx';\nimport Tabs from '@components/tabs';\nimport {GrowHeightReveal} from '@helpers/solid/animations';\n\nexport function StarsStrokeStar(props: {stroke?: boolean, style?: JSX.HTMLAttributes<HTMLDivElement>['style']}) {\n  return (\n    <svg class={classNames('stars-star-icon', 