ponents/rtmp/adminStreamPopup.tsx","../src/components/mediaViewer/rtmp.ts","../src/components/topbarCall.tsx","../src/components/call/conferenceJoinPopup.tsx","../src/helpers/files/getFilesFromEvent.ts","../src/components/popups/giftPremium.tsx","../src/components/popups/webApp.ts","../src/lib/calls/openRtmpCallViewer.ts","../src/helpers/dom/getSelectedNodes.ts","../src/lib/appManagers/utils/useLockScreenShortcut.ts","../src/components/playbackRateButton.ts","../src/components/chat/audio.tsx","../src/lib/appImManager.ts","../src/components/mediaViewer/index.ts","../src/components/premium/promoSlideTab.tsx","../src/components/premium/limitsFeature.ts","../src/components/premium/upgradedStoriesFeature.tsx","../src/components/premium/premiumStickersCarousel.ts","../src/components/premium/featuresCarousel.ts","../src/components/premium/featureSlideTab.ts","../src/components/popups/premium.ts","../src/components/generateTitleIcons.ts","../src/components/peerTitle.ts","../src/components/wrappers/peerTitle.tsx","../src/components/wrappers/messageForReply.ts","../src/components/wrappers/messageActionTextNewUnsafe.ts","../src/helpers/canvas/dashedCircle.ts","../src/components/avatarNew.tsx","../src/components/buttonMenu.ts"],"sourcesContent":["import {createEffect, createRoot, JSX, ParentProps, untrack} from 'solid-js';\nimport {createMutable, unwrap} from 'solid-js/store';\nimport {render} from 'solid-js/web';\nimport type SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\n\ntype Args<ObservedAttribute extends string, Props, Controls extends Object = {}> = {\n  name: string;\n  component: CustomElementComponent<ObservedAttribute, Props, Controls>;\n  observedAttributes?: ObservedAttribute[];\n  shadow?: boolean;\n}\n\nexport type PassedProps<Props extends Object = {}> = Props & {\n  readonly element: HTMLElement;\n};\n\ntype AttributesRecord<ObservedAttribute extends string> = Record<ObservedAttribute, string | undefined | null>;\ntype MutableStore<T extends Object> = T;\n\ntype CustomElementComponent<ObservedAttribute extends string, Props, Controls = {}> =\n  (props: PassedProps<MutableStore<Props>>, attributes: MutableStore<AttributesRecord<ObservedAttribute>>, controls: Controls) => JSX.Element;\n\nexport type DefinedSolidElement<ObservedAttribute extends string = string, Props extends Object = {}, Controls = {}> = ReturnType<typeof defineSolidElement<Props, ObservedAttribute, Controls>>;\n\n/**\n * Defines an HMR capable custom element with solid-js rendering\n *\n * Don't forget to add `if(import.meta.hot) import.meta.hot.accept();` in the file you're\n * declaring the component to take advantage of Hot Module Replacement\n *\n * Note that it might still need a refresh if you change other parameters except the component logic\n *\n * @example\n * // my-element.tsx\n * const MyElement = defineSolidElement({\n *   name: 'my-element',\n *   observedAttributes: ['size', 'something-else'],\n *   // props and attributes are reactive mutable stores, meaning you can also mutate them directly\n *   component: (props: {fancyProp: Date}, attributes, controls: {someAction: () => void}) => {\n *     // component logic in here\n *\n *     // expose some methods to the element\n *     controls.someAction = () => setInternalSignal('to something');\n *\n *     return <>...</>;\n *   }\n * });\n *\n * // used-in-file.ts\n *\n * // Some imports might break the HMR, so you can provide this hot reload guard to prevent page reload\n * import SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n *\n * const el = new MyElement;\n * el.feedProps({fancyProp: new Date});\n * el.HotReloadGuard = SolidJSHotReloadGuardProvider;\n *\n * // Append to DOM after feeding the props, unless it relies solely on attributes, or handles undefined props\n * otherElement.append(el);\n *\n * // Can use attributes if you want\n * el.setAttribute('size', '400');\n *\n * // Use internal methods through the `controls` property\n * el.controls.someAction();\n */\nexport default function defineSolidElement<Props extends Object, ObservedAttribute extends string, Controls = {}>({\n  name,\n  component,\n  observedAttributes = [],\n  shadow = false\n}: Args<ObservedAttribute, Props, Controls>) {\n  //\n  // When the module is hot replaced\n  if(customElements.get(name)) {\n    const previousElementClass = customElements.get(name) as typeof SolidElement;\n    previousElementClass.swapComponentFromHMR(component);\n    return previousElementClass;\n  }\n\n  let instances: (InstanceType<typeof SolidElement>)[];\n\n  if(import.meta.hot) {\n    instances = [];\n  }\n\n  const className = burgerToPascal(name);\n\n  const SolidElement = class extends HTMLElement {\n    private mountPoint: ShadowRoot | this;\n\n    private attributesStore: MutableStore<AttributesRecord<ObservedAttribute>>;\n    private propsStore: PassedProps<Props>;\n\n    private disposeContent?: () => void;\n    private disposeStores?: () => void;\n\n    /**\n     * Persist props when the component gets mounted / unmounted and allow initialization before the element\n     * is added to the DOM\n     */\n    private savedProps = ((self: typeof this) => ({\n      get element() {\n        return self;\n      }\n    } as unknown as PassedProps<Props>))(this);\n\n    public readonly controls = {} as Controls;\n\n    public HotReloadGuard?: typeof SolidJSHotReloadGuardProvider;\n\n    /**\n     * For HMR\n     */\n    public static Component = component;\n\n    public static swapComponentFromHMR(newComponent: CustomElementComponent<ObservedAttribute, Props, Controls>) {\n      if(import.meta.hot) {\n        SolidElement.Component = newComponent;\n        instances.forEach((instance) => {\n          instance?.mount?.();\n        });\n      }\n    }\n\n    static get observedAttributes() {\n      return observedAttributes;\n    }\n\n    constructor() {\n      super();\n\n      this.mountPoint = shadow ? this.attachShadow({mode: 'open'}) : this;\n    }\n\n    connectedCallback() {\n      this.mount();\n\n      if(import.meta.hot) {\n        instances.push(this);\n      }\n    }\n\n    disconnectedCallback() {\n      this.unmount();\n\n      if(import.meta.hot) {\n        const idx = instances.indexOf(this);\n        if(idx > -1) instances.splice(idx, 1);\n      }\n    }\n\n    attributeChangedCallback(name: ObservedAttribute, _oldValue: string, newValue: string) {\n      this.attributesStore[name] = newValue; // Let's hope this will not trigger infinite loops, as the values are compared before updates\n    }\n\n    public get props() {\n      if(this.disposeStores) {\n        return this.propsStore;\n      } else {\n        return this.savedProps;\n      }\n    }\n\n    public feedProps<Full extends boolean = true>(props: Full extends true ? Props : Partial<Props>) {\n      if(this.disposeStores) {\n        Object.assign(this.propsStore, props);\n      } else {\n        Object.assign(this.savedProps, props);\n      }\n    }\n\n    private initStores() {\n      createRoot(dispose => {\n        this.disposeStores = dispose;\n\n        this.propsStore = createMutable(this.savedProps);\n        this.attributesStore = createMutable({} as AttributesRecord<ObservedAttribute>);\n\n        createEffect(() => Object.keys(this.attributesStore).forEach(key => {\n          const attributeName = key as ObservedAttribute;\n          const value = this.attributesStore[attributeName];\n\n          if(this.getAttribute(attributeName) === this.attributesStore[attributeName]) return;\n\n          if(value === null || value === undefined) {\n            this.removeAttribute(attributeName);\n          } else {\n            this.setAttribute(attributeName, value);\n          }\n        }));\n      });\n    }\n\n    private mount() {\n      let savedAttributes: AttributesRecord<ObservedAttribute>;\n\n      // can happen only on hmr\n      if(this.disposeStores) savedAttributes = unwrap(this.attributesStore);\n\n      this.unmount();\n      const ComponentToMount = SolidElement.Component;\n\n      this.initStores();\n      if(savedAttributes) Object.assign(this.attributesStore, savedAttributes);\n\n      const Wrapper = this.HotReloadGuard || ((props: ParentProps) => <>{props.children}</>);\n\n      // JSX is mandatory here for cleanup to work!\n      this.disposeContent = render(() => <Wrapper>{untrack(() => ComponentToMount(this.propsStore, this.attributesStore, this.controls))}</Wrapper>, this.mountPoint);\n    }\n\n    private unmount() {\n      this.disposeContent?.();\n      this.disposeStores?.();\n\n      this.disposeStores = this.disposeContent = undefined;\n\n      this.mountPoint.replaceChildren(); // Don't leave trash in there\n    }\n\n    get [Symbol.toStringTag]() {\n      return className;\n    }\n  };\n\n  customElements.define(name, SolidElement);\n\n  return SolidElement;\n}\n\nfunction burgerToPascal(str: string) {\n  return str\n  .split('-')\n  .map(part => part.charAt(0).toUpperCase() + part.slice(1))\n  .join('');\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport mediaSizes from '@helpers/mediaSizes';\nimport OverlayClickHandler from '@helpers/overlayClickHandler';\nimport overlayCounter from '@helpers/overlayCounter';\nimport pause from '@helpers/schedulers/pause';\n\ntype AdditionalMenuItem = {\n  level: number,\n  element: HTMLElement,\n  triggerElement: HTMLElement,\n  close: () => void,\n}\n\nclass ContextMenuController extends OverlayClickHandler {\n  protected additionalMenus: AdditionalMenuItem[] = [];\n  protected menuOpenTarget: HTMLElement;\n\n  constructor() {\n    super('menu', true);\n\n    mediaSizes.addEventListener('resize', () => {\n      if(this.element) {\n        this.close();\n      }\n\n      /* if(openedMenu && (openedMenu.style.top || openedMenu.style.left)) {\n        const rect = openedMenu.getBoundingClientRect();\n        const {innerWidth, innerHeight} = window;\n\n        console.log(innerWidth, innerHeight, rect);\n      } */\n    });\n  }\n\n  public isOpened() {\n    return !!this.element;\n  }\n\n  /** Set for one open: see {@link keepNextOpenOnMouseMove}. */\n  private keepOpenOnMouseMove = false;\n  private keepOpenTimeout: number;\n\n  /**\n   * The next menu is opened away from the pointer — from a deep link rather than\n   * a click — so the first mouse move must not close it: there is nothing for the\n   * pointer to be moving away from yet.\n   */\n  public keepNextOpenOnMouseMove() {\n    this.keepOpenOnMouseMove = true;\n\n    // a click that opens nothing (a hidden trigger, a move since mousedown) would\n    // otherwise leave the flag for the next menu the user opens themselves\n    clearTimeout(this.keepOpenTimeout);\n    this.keepOpenTimeout = window.setTimeout(() => this.keepOpenOnMouseMove = false, 1000);\n  }\n\n  private onMouseMove = (e: MouseEvent) => {\n    const allMenus = [\n      ...[...this.additionalMenus].reverse(),\n      {\n        triggerElement: undefined,\n        level: 0,\n        element: this.element,\n        close: () => this.close()\n      }\n    ];\n\n    function isFartherThan(element: HTMLElement, distance: number) {\n      const {clientX, clientY} = e;\n\n      const rect = element.getBoundingClientRect();\n\n      const diffX = clientX >= rect.right ? clientX - rect.right : rect.left - clientX;\n      const diffY = clientY >= rect.bottom ? clientY - rect.bottom : rect.top - clientY;\n\n      return diffX >= distance || diffY >= distance;\n    }\n\n    for(const item of allMenus) {\n      if(item.triggerElement && !isFartherThan(item.triggerElement, 40)) break;\n\n      if(isFartherThan(item.element, item.level === 0 ? 100 : 40)) {\n        this.closeAndRemoveMenu(item);\n      } else {\n        break;\n      }\n    }\n  };\n\n  protected closeAndRemoveMenu(item: AdditionalMenuItem) {\n    item.close();\n    const idx = this.additionalMenus.indexOf(item);\n    if(idx > -1) {\n      for(let i = idx + 1; i < this.additionalMenus.length; i++) {\n        this.additionalMenus[i].close();\n      }\n      this.additionalMenus.splice(idx);\n    }\n  }\n\n  public closeMenusByLevel(level: number) {\n    this.additionalMenus.filter((menu) => menu.level >= level).forEach((item) => {\n      item.close();\n    });\n\n    this.additionalMenus = this.additionalMenus.filter((menu) => menu.level < level);\n  }\n\n  public close(e?: MouseEvent | TouchEvent) {\n    if(e && (e.target as HTMLElement).classList.contains('btn-menu')) {\n      return;\n    }\n\n    if(this.element) {\n      this.element.classList.remove('active');\n      this.menuOpenTarget?.classList.remove('menu-open');\n      this.menuOpenTarget = undefined;\n\n      if(this.element.classList.contains('night')) {\n        const element = this.element;\n        setTimeout(() => {\n          if(element.classList.contains('active')) {\n            return;\n          }\n\n          element.classList.remove('night');\n        }, 400);\n      }\n    }\n\n    this.additionalMenus.forEach((menu) => {\n      menu.close();\n    });\n\n    this.additionalMenus = [];\n\n    super.close();\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.realmWindow.removeEventListener('mousemove', this.onMouseMove);\n    }\n  }\n\n  protected shouldApplyNight(triggerElement?: HTMLElement) {\n    if(overlayCounter.isDarkOverlayActive) return true;\n    const nightAncestor = triggerElement && findUpClassName(triggerElement, 'night');\n    return !!nightAncestor && nightAncestor !== document.documentElement;\n  }\n\n  public openBtnMenu(element: HTMLElement, onClose?: () => void, triggerElement?: HTMLElement) {\n    if(this.shouldApplyNight(triggerElement)) {\n      element.classList.add('night');\n    }\n\n    super.open(element);\n\n    this.element.classList.add('active', 'was-open');\n    this.menuOpenTarget = triggerElement ?? this.element.parentElement;\n    this.menuOpenTarget?.classList.add('menu-open');\n\n    if(onClose) {\n      this.addEventListener('toggle', onClose, {once: true});\n    }\n\n    const keepOpen = this.keepOpenOnMouseMove;\n    this.keepOpenOnMouseMove = false;\n    clearTimeout(this.keepOpenTimeout);\n\n    if(!IS_TOUCH_SUPPORTED && !keepOpen) {\n      this.realmWindow.addEventListener('mousemove', this.onMouseMove);\n    }\n  }\n\n  public addAdditionalMenu(element: HTMLElement, triggerElement: HTMLElement, level: number, onClose?: () => void) {\n    if(!this.element) return;\n\n    this.closeMenusByLevel(level);\n\n    this.additionalMenus.push({\n      element,\n      triggerElement,\n      level,\n      close: () => {\n        element.classList.remove('active');\n        pause(400).then(() => element.remove());\n        onClose();\n      }\n    });\n    if(this.shouldApplyNight(triggerElement)) {\n      element.classList.add('night');\n    }\n    element.classList.add('active', 'was-open');\n\n    if(onClose) {\n      this.addEventListener('toggle', onClose, {once: true});\n    }\n  }\n}\n\nconst contextMenuController = new ContextMenuController();\nexport default contextMenuController;\n","import type ListenerSetter from '@helpers/listenerSetter';\nimport Icon from '@components/icon';\nimport getDeepProperty from '@helpers/object/getDeepProperty';\nimport rootScope from '@lib/rootScope';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\n\nexport type CheckboxFieldColor = 'white' | 'secondary';\n\n/**\n * A checkbox is only ever the control — it carries no label of its own. Anything the user reads\n * (caption, subtitle, icon) belongs to the `Row` that hosts it: `Row.Title` + `Row.CheckboxField`\n * in `rowTsx`, or the corresponding options in `rowTsxController` for imperative callers.\n */\nexport type CheckboxFieldOptions = {\n  name?: string,\n  round?: boolean,\n  color?: CheckboxFieldColor,\n  toggle?: boolean,\n  stateKey?: string,\n  stateValues?: any[],\n  stateValueReverse?: boolean,\n  disabled?: boolean,\n  checked?: boolean,\n  toggleLockIcon?: Icon,\n  restriction?: boolean,\n  listenerSetter?: ListenerSetter,\n  asRadio?: boolean\n};\nexport default class CheckboxField {\n  public input: HTMLInputElement;\n  public label: HTMLSpanElement;\n  public toggleCircle: HTMLElement;\n  public listenerSetter: ListenerSetter;\n\n  constructor(options: CheckboxFieldOptions = {}) {\n    const label = this.label = document.createElement('span');\n    label.classList.add('checkbox-field');\n\n    if(options.restriction && !options.toggle) {\n      label.classList.add('checkbox-field-restriction');\n    }\n\n    if(options.round) {\n      label.classList.add('checkbox-field-round');\n    }\n\n    if(options.color && options.color !== 'secondary') {\n      label.classList.add('checkbox-color-' + options.color);\n    }\n\n    if(options.disabled) {\n      this.toggleDisability(true);\n    }\n\n    this.listenerSetter = options.listenerSetter;\n\n    const input = this.input = document.createElement('input');\n    input.classList.add('checkbox-field-input');\n    input.type = options.asRadio ? 'radio' : 'checkbox';\n    if(options.name) {\n      input[options.asRadio ? 'name' : 'id'] = 'input-' + options.name;\n    }\n\n    if(options.checked) {\n      input.checked = true;\n    }\n\n    if(options.stateKey) {\n      let loaded = options.checked !== undefined;\n      const onChange = () => {\n        if(!loaded) {\n          return;\n        }\n\n        let value: any;\n        if(options.stateValues) {\n          value = options.stateValues[input.checked ? 1 : 0];\n        } else {\n          value = input.checked;\n\n          if(options.stateValueReverse) {\n            value = !value;\n          }\n        }\n\n        rootScope.managers.appStateManager.setByKey(options.stateKey, value);\n      };\n\n      !loaded && apiManagerProxy.getState().then((state) => {\n        loaded = true;\n        const stateValue = getDeepProperty(state, options.stateKey);\n        let checked: boolean;\n        if(options.stateValues) {\n          checked = options.stateValues.indexOf(stateValue) === 1;\n        } else {\n          checked = stateValue;\n\n          if(options.stateValueReverse) {\n            checked = !checked;\n          }\n        }\n\n        this.setValueSilently(checked);\n      });\n\n      if(options.listenerSetter) options.listenerSetter.add(input)('change', onChange);\n      else input.addEventListener('change', onChange);\n    }\n\n    label.append(input);\n\n    if(options.toggle) {\n      label.classList.add('checkbox-field-toggle');\n\n      if(options.restriction) {\n        label.classList.add('checkbox-field-toggle-restriction');\n      }\n\n      const toggle = document.createElement('div');\n      toggle.classList.add('checkbox-toggle');\n      const circle = this.toggleCircle = document.createElement('div');\n      circle.classList.add('checkbox-toggle-circle');\n      toggle.append(circle);\n      label.append(toggle);\n\n      this.setToggleLockIcon(options.toggleLockIcon);\n    } else {\n      const box = document.createElement('div');\n      box.classList.add('checkbox-box');\n\n      const checkSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n      checkSvg.classList.add('checkbox-box-check');\n      checkSvg.setAttributeNS(null, 'viewBox', '0 0 24 24');\n      const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n      use.setAttributeNS(null, 'href', '#check');\n      use.setAttributeNS(null, 'x', '-1');\n      checkSvg.append(use);\n\n      const bg = document.createElement('div');\n      bg.classList.add('checkbox-box-background');\n\n      const border = document.createElement('div');\n      border.classList.add('checkbox-box-border');\n\n      box.append(border, bg, checkSvg);\n\n      label.append(box);\n    }\n  }\n\n  get checked() {\n    return this.input.checked;\n  }\n\n  set checked(checked: boolean) {\n    /* if(this.checked === checked) {\n      return;\n    } */\n\n    this.setValueSilently(checked);\n    simulateEvent(this.input, 'change');\n  }\n\n  /** Puts a lock inside the toggle's circle, or clears it when no icon is given. Toggle-only. */\n  public setToggleLockIcon(icon?: Icon) {\n    const circle = this.toggleCircle;\n    if(!circle) {\n      return;\n    }\n\n    circle.classList.toggle('with-lock', !!icon);\n    circle.replaceChildren(...(icon ? [Icon(icon)] : []));\n  }\n\n  public setValueSilently(checked: boolean) {\n    this.input.checked = checked;\n  }\n\n  public isDisabled() {\n    return this.label.classList.contains('checkbox-disabled');\n  }\n\n  public toggleDisability(disable: boolean) {\n    this.label.classList.toggle('checkbox-disabled', disable);\n    this.input.disabled = disable;\n    return () => this.toggleDisability(!disable);\n  }\n}\n","export default function RadioForm(radios: {container: HTMLElement, input: HTMLInputElement}[], onChange: (value: string, event: Event) => void) {\n  const form = document.createElement('form');\n\n  radios.forEach((r) => {\n    const {container, input} = r;\n    form.append(container);\n    input.addEventListener('change', (e) => {\n      if(input.checked) {\n        onChange(input.value, e);\n      }\n    });\n  });\n\n  return form;\n}\n","import sequentialDom from '@helpers/sequentialDom';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\n\nconst UNMOUNT_THUMBS = true;\n\nexport default function renderMediaWithFadeIn({\n  container,\n  media,\n  url,\n  needFadeIn,\n  aspecter = container,\n  thumbImage,\n  fadeInElement = media as any,\n  onRender,\n  onRenderFinish,\n  useRenderCache\n}: {\n  container: HTMLElement,\n  media: Parameters<typeof renderImageFromUrlPromise>[0],\n  url: string,\n  needFadeIn: boolean,\n  aspecter?: HTMLElement,\n  thumbImage?: HTMLElement,\n  fadeInElement?: HTMLElement,\n  onRender?: () => void,\n  onRenderFinish?: () => void,\n  useRenderCache?: boolean\n}) {\n  if(needFadeIn) {\n    fadeInElement.classList.add('fade-in');\n  }\n\n  const promise = renderImageFromUrlPromise(media, url, useRenderCache).then(() => {\n    return sequentialDom.mutateElement(container, () => {\n      aspecter?.append(media);\n\n      if(needFadeIn) {\n        onRender?.();\n        fadeInElement.addEventListener('animationend', () => {\n          sequentialDom.mutate(() => {\n            fadeInElement.classList.remove('fade-in');\n            UNMOUNT_THUMBS && thumbImage?.remove();\n            container.classList.add('no-background');\n            onRenderFinish?.();\n          });\n        }, {once: true});\n      } else {\n        UNMOUNT_THUMBS && thumbImage?.remove();\n        container.classList.add('no-background');\n        onRender?.();\n        onRenderFinish?.();\n      }\n    });\n  });\n\n  // recordPromise(promise, 'renderImageWithFadeIn');\n\n  return promise;\n}\n","import liteMode from '@helpers/liteMode';\n\nconst $TRANSITION_RAF = Symbol('RAF'),\n  $TRANSITION_TIMEOUT = Symbol('TIMEOUT');\n\ntype SetTransitionOptions = {\n  element: HTMLElement,\n  className: string,\n  forwards: boolean,\n  duration: number,\n  onTransitionEnd?: () => void,\n  useRafs?: number,\n  onTransitionStart?: () => void\n};\nconst SetTransition = (options: SetTransitionOptions) => {\n  const {element, className, forwards, duration, onTransitionEnd, onTransitionStart, useRafs} = options;\n  const classNames = className && className.split(' ');\n  const timeout: number = (element as any)[$TRANSITION_TIMEOUT];\n  const raf: number = (element as any)[$TRANSITION_RAF];\n  if(timeout !== undefined) {\n    clearTimeout(+timeout);\n  }\n\n  // useRafs = undefined;\n  // duration = 0;\n\n  if(raf !== undefined) {\n    window.cancelAnimationFrame(+raf);\n    if(!useRafs) {\n      delete (element as any)[$TRANSITION_RAF];\n    }\n  }\n\n  // if(forwards && className && element.classList.contains(className) && !element.classList.contains('animating')) {\n  //   return;\n  // }\n\n  if(useRafs && liteMode.isAvailable('animations') && duration) {\n    (element as any)[$TRANSITION_RAF] = '' + window.requestAnimationFrame(() => {\n      delete (element as any)[$TRANSITION_RAF];\n      SetTransition({\n        ...options,\n        useRafs: useRafs - 1\n      });\n    });\n\n    return;\n  }\n\n  if(forwards && className) {\n    element.classList.add(...classNames);\n  }\n\n  const afterTimeout = () => {\n    delete (element as any)[$TRANSITION_TIMEOUT];\n    if(!forwards && className) {\n      element.classList.remove('backwards', ...classNames);\n    }\n\n    element.classList.remove('animating');\n\n    onTransitionEnd?.();\n  };\n\n  onTransitionStart?.();\n  element.classList.toggle('forwards', forwards);\n  if(!liteMode.isAvailable('animations') || !duration) {\n    element.classList.remove('animating', 'backwards');\n    afterTimeout();\n    return;\n  }\n\n  element.classList.add('animating');\n\n  element.classList.toggle('backwards', !forwards);\n  (element as any)[$TRANSITION_TIMEOUT] = '' + setTimeout(afterTimeout, duration);\n};\n\nexport default SetTransition;\n","import {CancellablePromise} from '@helpers/cancellablePromise';\nimport SetTransition from '@components/singleTransition';\nimport {fastRaf} from '@helpers/schedulers';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport safeAssign from '@helpers/object/safeAssign';\n\nconst TRANSITION_TIME = 200;\n\nexport default class ProgressivePreloader {\n  public preloader: HTMLDivElement;\n  public circle: SVGCircleElement;\n  private cancelSvg: SVGSVGElement;\n  private downloadSvg: HTMLElement;\n\n  private tempId = 0;\n  public detached = true;\n\n  public promise: CancellablePromise<any> = null;\n\n  public isUpload = false;\n  private cancelable = true;\n  private streamable = false;\n  private rtmp = false;\n  private tryAgainOnFail = true;\n  private attachMethod: 'append' | 'prepend' = 'append';\n\n  public loadFunc: (e?: Event) => any;\n\n  public totalLength: number;\n\n  constructor(options?: Partial<{\n    isUpload: ProgressivePreloader['isUpload'],\n    cancelable: ProgressivePreloader['cancelable'],\n    streamable: ProgressivePreloader['streamable'],\n    rtmp: ProgressivePreloader['rtmp'],\n    tryAgainOnFail: ProgressivePreloader['tryAgainOnFail'],\n    attachMethod: ProgressivePreloader['attachMethod']\n  }>) {\n    if(options) {\n      safeAssign(this, options);\n    }\n\n    if(this.isUpload) {\n      this.tryAgainOnFail = false;\n    }\n  }\n\n  public constructContainer(options: Partial<{\n    color: 'transparent',\n    bold: boolean\n  }> = {}) {\n    if(!this.preloader) {\n      this.preloader = document.createElement('div');\n      if(this.rtmp) {\n        this.preloader.classList.add('preloader-container-rtmp');\n      } else {\n        this.preloader.classList.add('preloader-container');\n      }\n\n      if(options.color) {\n        this.preloader.classList.add('preloader-' + options.color);\n      }\n\n      if(options.bold) {\n        this.preloader.classList.add('preloader-bold');\n      }\n\n      if(this.streamable) {\n        this.preloader.classList.add('preloader-streamable');\n      }\n    }\n  }\n\n  public constructDownloadIcon() {\n    this.constructContainer();\n  }\n\n  public construct() {\n    this.construct = null;\n\n    this.constructContainer();\n\n    if(this.rtmp) {\n      this.preloader.innerHTML = `\n      <div class=\"loading-wrap is-loading\">\n        <div class=\"loading\"></div>\n        <div class=\"loading_bezel-wrap\">\n          <div class=\"loading\"></div>\n        </div>\n      </div>`;\n    } else {\n      this.preloader.innerHTML = `\n      <div class=\"you-spin-me-round\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-circular\" viewBox=\"${this.streamable ? '25 25 50 50' : '27 27 54 54'}\">\n      <circle class=\"preloader-path-new\" cx=\"${this.streamable ? '50' : '54'}\" cy=\"${this.streamable ? '50' : '54'}\" r=\"${this.streamable ? 19 : 24}\" fill=\"none\" stroke-miterlimit=\"10\"/>\n      </svg>\n      </div>`;\n    }\n\n    if(this.streamable) {\n      this.totalLength = 118.61124420166016;\n    } else {\n      this.totalLength = 149.82473754882812;\n    }\n\n    if(this.cancelable) {\n      this.preloader.innerHTML += `\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-close\" viewBox=\"0 0 24 24\">\n        <g fill=\"none\" fill-rule=\"evenodd\">\n          <polygon points=\"0 0 24 0 24 24 0 24\"/>\n          <path fill=\"#000\" fill-rule=\"nonzero\" d=\"M5.20970461,5.38710056 L5.29289322,5.29289322 C5.65337718,4.93240926 6.22060824,4.90467972 6.61289944,5.20970461 L6.70710678,5.29289322 L12,10.585 L17.2928932,5.29289322 C17.6834175,4.90236893 18.3165825,4.90236893 18.7071068,5.29289322 C19.0976311,5.68341751 19.0976311,6.31658249 18.7071068,6.70710678 L13.415,12 L18.7071068,17.2928932 C19.0675907,17.6533772 19.0953203,18.2206082 18.7902954,18.6128994 L18.7071068,18.7071068 C18.3466228,19.0675907 17.7793918,19.0953203 17.3871006,18.7902954 L17.2928932,18.7071068 L12,13.415 L6.70710678,18.7071068 C6.31658249,19.0976311 5.68341751,19.0976311 5.29289322,18.7071068 C4.90236893,18.3165825 4.90236893,17.6834175 5.29289322,17.2928932 L10.585,12 L5.29289322,6.70710678 C4.93240926,6.34662282 4.90467972,5.77939176 5.20970461,5.38710056 L5.29289322,5.29289322 L5.20970461,5.38710056 Z\"/>\n        </g>\n      </svg>\n      <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"preloader-download\" viewBox=\"0 0 24 24\">\n        <g fill=\"none\" fill-rule=\"evenodd\">\n          <polygon points=\"0 0 24 0 24 24 0 24\"/>\n          <path fill=\"#000\" fill-rule=\"nonzero\" d=\"M5,19 L19,19 C19.5522847,19 20,19.4477153 20,20 C20,20.5128358 19.6139598,20.9355072 19.1166211,20.9932723 L19,21 L5,21 C4.44771525,21 4,20.5522847 4,20 C4,19.4871642 4.38604019,19.0644928 4.88337887,19.0067277 L5,19 L19,19 L5,19 Z M11.8833789,3.00672773 L12,3 C12.5128358,3 12.9355072,3.38604019 12.9932723,3.88337887 L13,4 L13,13.585 L16.2928932,10.2928932 C16.6533772,9.93240926 17.2206082,9.90467972 17.6128994,10.2097046 L17.7071068,10.2928932 C18.0675907,10.6533772 18.0953203,11.2206082 17.7902954,11.6128994 L17.7071068,11.7071068 L12.7071068,16.7071068 C12.3466228,17.0675907 11.7793918,17.0953203 11.3871006,16.7902954 L11.2928932,16.7071068 L6.29289322,11.7071068 C5.90236893,11.3165825 5.90236893,10.6834175 6.29289322,10.2928932 C6.65337718,9.93240926 7.22060824,9.90467972 7.61289944,10.2097046 L7.70710678,10.2928932 L11,13.585 L11,4 C11,3.48716416 11.3860402,3.06449284 11.8833789,3.00672773 L12,3 L11.8833789,3.00672773 Z\"/>\n        </g>\n      </svg>`;\n\n      this.downloadSvg = this.preloader.lastElementChild as HTMLElement;\n      this.cancelSvg = this.downloadSvg.previousElementSibling as any;\n    } else {\n      this.preloader.classList.add('preloader-swing');\n    }\n\n    this.circle = this.preloader.firstElementChild.firstElementChild.firstElementChild as SVGCircleElement;\n\n    if(this.cancelable) {\n      attachClickEvent(this.preloader, this.onClick);\n    }\n  }\n\n  public onClick = (e?: Event) => {\n    if(e) {\n      cancelEvent(e);\n    }\n\n    if(this.preloader.classList.contains('manual')) {\n      this.loadFunc?.(e);\n    } else {\n      this.promise?.cancel?.();\n    }\n  };\n\n  public setDownloadFunction(func: ProgressivePreloader['loadFunc']) {\n    this.loadFunc = func;\n  }\n\n  public setManual() {\n    this.preloader.classList.add('manual');\n    this.setProgress(0);\n  }\n\n  public attachPromise(promise: CancellablePromise<any>) {\n    if(this.isUpload && this.promise) return;\n\n    this.promise = promise;\n\n    const tempId = --this.tempId;\n    const startTime = Date.now();\n\n    const onEnd = (err: Error) => {\n      promise.notify = promise.notifyAll = null;\n\n      if(tempId !== this.tempId) {\n        return;\n      }\n\n      const elapsedTime = Date.now() - startTime;\n\n      // console.log('[PP]: end', this.detached, performance.now());\n\n      if(!err && this.cancelable) {\n        this.setProgress(100);\n\n        const delay = TRANSITION_TIME * 0.75;\n\n        if(elapsedTime < delay) {\n          this.detach();\n        } else {\n          setTimeout(() => { // * wait for transition complete\n            if(tempId === this.tempId) {\n              this.detach();\n            }\n          }, delay);\n        }\n      } else {\n        if(this.tryAgainOnFail) {\n          this.attach(this.preloader.parentElement);\n          fastRaf(() => {\n            this.setManual();\n          });\n        } else {\n          this.detach();\n        }\n      }\n\n      this.promise = promise = null;\n    };\n\n    promise\n    .then(() => onEnd(null))\n    .catch((err) => onEnd(err));\n\n    promise.addNotifyListener?.((details: {done: number, total: number}) => {\n      /* if(details.done >= details.total) {\n        onEnd();\n      } */\n\n      if(tempId !== this.tempId) return;\n\n      // console.log('preloader download', promise, details);\n      const percents = details.done / details.total * 100;\n      this.setProgress(percents);\n    });\n  }\n\n  public attach(elem: Element, reset = false, promise?: CancellablePromise<any>) {\n    if(!this.detached && (!this.preloader || !this.preloader.classList.contains('manual'))) {\n      return;\n    }\n\n    this.construct?.();\n\n    if(this.preloader.parentElement) {\n      this.preloader.classList.remove('manual');\n    }\n\n    this.detached = false;\n\n    if(promise/*  && false */) {\n      this.attachPromise(promise);\n    }\n\n    let useRafs = 0;\n    if(this.detached || this.preloader.parentElement !== elem) {\n      useRafs = isInDOM(this.preloader) ? 1 : 2;\n      if(this.preloader.parentElement !== elem) {\n        elem[this.attachMethod](this.preloader);\n      }\n    }\n\n    SetTransition({\n      element: this.preloader,\n      className: 'is-visible',\n      forwards: true,\n      duration: TRANSITION_TIME,\n      useRafs\n    });\n\n    if(this.cancelable && reset) {\n      this.setProgress(0);\n    }\n  }\n\n  public detach() {\n    if(this.detached) {\n      return;\n    }\n    // return;\n\n    this.detached = true;\n\n    // return;\n\n    if(this.preloader?.parentElement) {\n      /* setTimeout(() =>  */// fastRaf(() => {\n      /* if(!this.detached) return;\n        this.detached = true; */\n\n      // fastRaf(() => {\n      // console.log('[PP]: detach after rAF', this.detached, performance.now());\n\n      // if(!this.detached || !this.preloader.parentElement) {\n      //   return;\n      // }\n\n      SetTransition({\n        element: this.preloader,\n        className: 'is-visible',\n        forwards: false,\n        duration: TRANSITION_TIME,\n        onTransitionEnd: () => {\n          this.preloader.remove();\n        },\n        useRafs: 1\n      });\n      // });\n      // })/* , 5e3) */;\n    }\n  }\n\n  public setProgress(percents: number) {\n    if(!this.totalLength && !isInDOM(this.circle)) {\n      return;\n    }\n\n    if(percents === 0) {\n      this.circle.style.strokeDasharray = '';\n      return;\n    }\n\n    try {\n      this.totalLength ||= this.circle.getTotalLength();\n\n      // console.log('setProgress', (percents / 100 * totalLength));\n      this.circle.style.strokeDasharray = '' + Math.max(5, percents / 100 * this.totalLength) + ', ' + this.totalLength;\n    } catch(err) {}\n  }\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type {MyPhoto} from '@appManagers/appPhotosManager';\nimport type {ThumbCache} from '@lib/storages/thumbs';\nimport {THUMB_TYPE_FULL} from '@appManagers/constants';\nimport getImageFromStrippedThumb from '@helpers/getImageFromStrippedThumb';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {PhotoSize} from '@layer';\n\nexport default function getMediaThumbIfNeeded({\n  photo,\n  cacheContext,\n  useBlur,\n  ignoreCache,\n  onlyStripped\n}: {\n  photo: MyPhoto | MyDocument,\n  cacheContext: ThumbCache,\n  useBlur: boolean | number,\n  ignoreCache?: boolean,\n  onlyStripped?: boolean\n}) {\n  const isVideo = (['video', 'gif'] as MyDocument['type'][]).includes((photo as MyDocument).type);\n  if(!cacheContext.downloaded || isVideo || ignoreCache) {\n    if(\n      photo._ === 'document' &&\n      cacheContext.downloaded &&\n      !ignoreCache &&\n      (!isVideo || cacheContext.type !== THUMB_TYPE_FULL)\n    ) {\n      return null;\n    }\n\n    const sizes = (photo as MyPhoto).sizes || (photo as MyDocument).thumbs;\n    const length = sizes?.length;\n    if(!length) {\n      return null;\n    }\n\n    let currentSizeIndex = -1;\n    if(!onlyStripped) for(let i = length - 1; i >= 0; --i) {\n      const size = sizes[i];\n      if(size.type === cacheContext.type) {\n        currentSizeIndex = i;\n      } else if(currentSizeIndex) {\n        const cacheContext = apiManagerProxy.getCacheContext(photo, size.type);\n        if(cacheContext.downloaded) {\n          return getImageFromStrippedThumb(photo, size as PhotoSize.photoCachedSize, false, cacheContext.url);\n        }\n      }\n    }\n\n    const thumb = sizes.find((size) => size._ === 'photoStrippedSize');\n    if(thumb && ('bytes' in thumb)) {\n      return getImageFromStrippedThumb(photo, thumb as any, useBlur);\n    }\n  }\n\n  return null;\n}\n","import {Message, MessageMedia, PhotoSize, WebDocument} from '@layer';\nimport {REPLIES_HIDDEN_CHANNEL_ID} from '@appManagers/constants';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport {MediaSize, makeMediaSize} from '@helpers/mediaSize';\nimport isWebDocument from '@appManagers/utils/webDocs/isWebDocument';\n\nexport const EXPAND_TEXT_WIDTH = 320;\nexport const MIN_IMAGE_WIDTH = 120;\nexport const MIN_SIDE_SIZE = 200;\nexport const MIN_VIDEO_SIDE_SIZE = 368;\n\nexport default function setAttachmentSize({\n  photo,\n  element,\n  boxWidth,\n  boxHeight,\n  noZoom = true,\n  message,\n  pushDocumentSize,\n  photoSize,\n  size,\n  canHaveVideoPlayer,\n  noMinSize\n}: {\n  photo?: MyPhoto | MyDocument | WebDocument,\n  element: HTMLElement | SVGForeignObjectElement,\n  boxWidth: number,\n  boxHeight: number,\n  noZoom?: boolean,\n  message?: Message.message,\n  pushDocumentSize?: boolean,\n  photoSize?: ReturnType<typeof choosePhotoSize>,\n  size?: MediaSize,\n  canHaveVideoPlayer?: boolean,\n  noMinSize?: boolean\n}) {\n  const _isWebDocument = isWebDocument(photo);\n  // if(_isWebDocument && pushDocumentSize === undefined) {\n  //   pushDocumentSize = true;\n  // }\n\n  if(!photoSize && !size) {\n    photoSize = choosePhotoSize(photo, boxWidth, boxHeight, undefined, pushDocumentSize);\n  }\n  // console.log('setAttachmentSize', photo, photo.sizes[0].bytes, div);\n\n  const isDocument = photo?._ === 'document';\n  if(size) {\n\n  } else if(isDocument || _isWebDocument) {\n    size = makeMediaSize(\n      photo.w || (photoSize as PhotoSize.photoSize).w || 512,\n      photo.h || (photoSize as PhotoSize.photoSize).h || 512\n    );\n  } else {\n    size = makeMediaSize(\n      (photoSize as PhotoSize.photoSize).w || 100,\n      (photoSize as PhotoSize.photoSize).h || 100\n    );\n  }\n\n  let boxSize = makeMediaSize(boxWidth, boxHeight);\n\n  boxSize = size = size.aspect(boxSize, noZoom);\n\n  let isFit = true;\n  if(!noMinSize && (!isDocument || ['video', 'gif'].includes(photo.type) || _isWebDocument)) {\n    const minSideSize = MIN_SIDE_SIZE;\n    if(boxSize.width < minSideSize && boxSize.height < minSideSize) { // make at least one side this big\n      boxSize = size = size.aspectCovered(makeMediaSize(minSideSize, minSideSize));\n    }\n\n    if(message &&\n      (message.message ||\n        message.factcheck ||\n        message.reply_to_mid ||\n        (message.media as MessageMedia.messageMediaWebPage).webpage ||\n        (message.replies && message.replies.pFlags.comments && message.replies.channel_id.toChatId() !== REPLIES_HIDDEN_CHANNEL_ID)\n      )\n    ) { // make sure that bubble block is human-readable\n      if(boxSize.width < EXPAND_TEXT_WIDTH) {\n        boxSize = makeMediaSize(EXPAND_TEXT_WIDTH, boxSize.height);\n        isFit = false;\n      }\n    }\n\n    const minWidth = (photo as MyDocument)?.type === 'video' && canHaveVideoPlayer ? MIN_VIDEO_SIDE_SIZE : MIN_IMAGE_WIDTH;\n    if(/* isFit &&  */boxSize.width < minWidth && message) { // if image is too narrow\n      boxSize = makeMediaSize(minWidth, boxSize.height);\n      isFit = false;\n    }\n  }\n\n  // if(element instanceof SVGForeignObjectElement) {\n  //   element.setAttributeNS(null, 'width', '' + w);\n  //   element.setAttributeNS(null, 'height', '' + h);\n\n  //   //console.log('set dimensions to svg element:', element, w, h);\n  // } else {\n  element.style.width = boxSize.width + 'px';\n  element.style.height = boxSize.height + 'px';\n  // }\n\n  return {photoSize, size, isFit};\n}\n","import renderMediaWithFadeIn from '@helpers/dom/renderMediaWithFadeIn';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {InputWebFileLocation, Message, PhotoSize, VideoSize, WebDocument} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport rootScope from '@lib/rootScope';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport ProgressivePreloader from '@components/preloader';\nimport blur from '@helpers/blur';\nimport {AppManagers} from '@lib/managers';\nimport getMediaThumbIfNeeded from '@helpers/getStrippedThumbIfNeeded';\nimport setAttachmentSize from '@helpers/setAttachmentSize';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport type {ThumbCache} from '@lib/storages/thumbs';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport isWebDocument from '@appManagers/utils/webDocs/isWebDocument';\nimport createVideo from '@helpers/dom/createVideo';\nimport noop from '@helpers/noop';\nimport {THUMB_TYPE_FULL} from '@appManagers/constants';\nimport {Middleware} from '@helpers/middleware';\nimport liteMode from '@helpers/liteMode';\nimport isWebFileLocation from '@appManagers/utils/webFiles/isWebFileLocation';\nimport apiManagerProxy from '@lib/apiManagerProxy';\n\nexport default async function wrapPhoto({photo, message, container, boxWidth, boxHeight, withTail, isOut, lazyLoadQueue, middleware, size, withoutPreloader, loadPromises, autoDownloadSize, noBlur, noThumb, noFadeIn, blurAfter, managers = rootScope.managers, processUrl, fadeInElement, onRender, onRenderFinish, useBlur, useRenderCache, canHaveVideoPlayer, uploadingFileName}: {\n  photo: MyPhoto | MyDocument | WebDocument | InputWebFileLocation,\n  message?: Message.message | Message.messageService,\n  container?: HTMLElement,\n  boxWidth?: number,\n  boxHeight?: number,\n  withTail?: boolean,\n  isOut?: boolean,\n  lazyLoadQueue?: LazyLoadQueue | false,\n  middleware?: Middleware,\n  size?: PhotoSize | Extract<VideoSize, VideoSize.videoSize>,\n  withoutPreloader?: boolean,\n  loadPromises?: Promise<any>[],\n  autoDownloadSize?: number,\n  noBlur?: boolean,\n  noThumb?: boolean,\n  noFadeIn?: boolean,\n  blurAfter?: boolean,\n  managers?: AppManagers,\n  processUrl?: (url: string) => Promise<string>,\n  fadeInElement?: HTMLElement,\n  onRender?: () => void,\n  onRenderFinish?: () => void,\n  useBlur?: boolean | number,\n  useRenderCache?: boolean,\n  canHaveVideoPlayer?: boolean,\n  uploadingFileName?: string\n}) {\n  const ret = {\n    loadPromises: {\n      thumb: Promise.resolve() as Promise<any>,\n      full: Promise.resolve() as Promise<any>\n    },\n    images: {\n      thumb: null as HTMLImageElement | HTMLCanvasElement,\n      full: null as HTMLVideoElement | HTMLImageElement\n    },\n    preloader: null as ProgressivePreloader,\n    aspecter: null as HTMLElement\n  };\n\n  if(!container) {\n    withoutPreloader = true;\n    lazyLoadQueue = undefined;\n  }\n\n  const isWebFile = isWebFileLocation(photo);\n  const isDocument = photo._ === 'document';\n  const isImageFromDocument = isDocument && photo.mime_type.startsWith('image/') && !size;\n  const isWebDoc = isWebDocument(photo);\n  if(\n    !((photo as MyPhoto).sizes || (photo as MyDocument).thumbs) &&\n    !isWebDoc &&\n    !isImageFromDocument &&\n    !isWebFile\n  ) {\n    if(boxWidth && boxHeight && !size && isDocument) {\n      setAttachmentSize({\n        photo,\n        element: container,\n        boxWidth,\n        boxHeight,\n        message: message as Message.message,\n        canHaveVideoPlayer\n      });\n    }\n\n    return ret;\n  }\n\n  let noAutoDownload = autoDownloadSize === 0;\n\n  if(!size) {\n    if(boxWidth === undefined) boxWidth = mediaSizes.active.regular.width;\n    if(boxHeight === undefined) boxHeight = mediaSizes.active.regular.height;\n  }\n\n  container && container.classList.add('media-container');\n  let aspecter = container;\n\n  let isFit = true;\n  let loadThumbPromise: Promise<any> = Promise.resolve();\n  let thumbImage: HTMLImageElement | HTMLCanvasElement;\n  // let image: HTMLImageElement;\n  let cacheContext: ThumbCache;\n  // if(withTail) {\n  //   image = wrapMediaWithTail(photo, message, container, boxWidth, boxHeight, isOut);\n  // } else {\n\n  if(boxWidth && boxHeight && !size && !isWebFile && container) { // !album\n    const set = setAttachmentSize({\n      photo,\n      element: container,\n      boxWidth,\n      boxHeight,\n      message: message as Message.message,\n      photoSize: isImageFromDocument ? {\n        _: 'photoSize',\n        w: photo.w,\n        h: photo.h,\n        size: photo.size,\n        type: THUMB_TYPE_FULL\n      } : undefined,\n      canHaveVideoPlayer\n    });\n    size = set.photoSize;\n    isFit = set.isFit;\n    cacheContext = apiManagerProxy.getCacheContext(photo, size.type);\n\n    if(!isFit && !isWebDoc) {\n      aspecter = document.createElement('div');\n      aspecter.classList.add('media-container-aspecter');\n      aspecter.style.width = set.size.width + 'px';\n      aspecter.style.height = set.size.height + 'px';\n\n      const gotThumb = getMediaThumbIfNeeded({\n        photo,\n        cacheContext,\n        useBlur: useBlur !== undefined ? useBlur : !noBlur,\n        ignoreCache: true,\n        onlyStripped: true\n      });\n      if(gotThumb) {\n        loadThumbPromise = gotThumb.loadPromise;\n        const thumbImage = gotThumb.image; // local scope\n        thumbImage.classList.add('media-photo');\n        container.append(thumbImage);\n      } else {\n        const res = await wrapPhoto({\n          container,\n          message,\n          photo,\n          boxWidth: 0,\n          boxHeight: 0,\n          size,\n          lazyLoadQueue,\n          isOut,\n          loadPromises,\n          middleware,\n          withoutPreloader: true,\n          withTail,\n          autoDownloadSize,\n          noBlur,\n          noThumb: true,\n          blurAfter: true,\n          managers\n          // noFadeIn: true\n        });\n        const thumbImage = res.images.full;\n        thumbImage.classList.add('media-photo', 'thumbnail');\n        // container.append(thumbImage);\n      }\n\n      container.classList.add('media-container-fitted');\n      container.append(aspecter);\n    }\n  } else {\n    if(!size && !isWebFile) {\n      size = choosePhotoSize(photo, boxWidth, boxHeight, true);\n    }\n\n    cacheContext = apiManagerProxy.getCacheContext(photo, size?.type);\n  }\n\n  if(!noThumb && !isWebDoc && !isWebFile && aspecter) {\n    const gotThumb = getMediaThumbIfNeeded({\n      photo,\n      cacheContext,\n      useBlur: useBlur !== undefined ? useBlur : !noBlur\n    });\n\n    if(gotThumb) {\n      loadThumbPromise = Promise.all([loadThumbPromise, gotThumb.loadPromise]);\n      ret.loadPromises.thumb = ret.loadPromises.full = loadThumbPromise;\n      thumbImage = ret.images.thumb = gotThumb.image;\n      thumbImage.classList.add('media-photo');\n      aspecter.append(thumbImage);\n    }\n  }\n  // }\n\n  ret.aspecter = aspecter;\n\n  if((size?._ === 'photoSizeEmpty' && isDocument) || (size as PhotoSize.photoStrippedSize)?.bytes) {\n    return ret;\n  }\n\n  let media: HTMLVideoElement | HTMLImageElement;\n  if(size?._ === 'videoSize') {\n    media = ret.images.full = createVideo({middleware});\n    media.autoplay = true;\n    media.loop = true;\n    media.muted = true;\n    media.classList.add('media-photo');\n  } else {\n    media = ret.images.full = new Image();\n    media.classList.add('media-photo');\n  }\n\n  // console.log('wrapPhoto downloaded:', photo, photo.downloaded, container);\n\n  const needFadeIn = (thumbImage || !cacheContext.downloaded) && liteMode.isAvailable('animations') && !noFadeIn;\n\n  let preloader: ProgressivePreloader;\n  uploadingFileName ??= (message as Message.message)?.uploadingFileName?.[0];\n  if(!withoutPreloader) {\n    if(!cacheContext.downloaded || uploadingFileName) {\n      preloader = new ProgressivePreloader({\n        attachMethod: 'prepend',\n        isUpload: !!uploadingFileName\n      });\n    }\n\n    if(uploadingFileName) { // means upload\n      preloader.attachPromise(appDownloadManager.getUpload(uploadingFileName));\n      preloader.attach(container);\n      noAutoDownload = undefined;\n    }\n  }\n\n\n  const getDownloadPromise = () => {\n    // const promise = isGif && !size ?\n    //   managers.appDocsManager.downloadDoc(photo, /* undefined,  */lazyLoadQueue?.queueId) :\n    //   managers.appPhotosManager.preloadPhoto(photo, size, lazyLoadQueue?.queueId, noAutoDownload);\n    const haveToDownload = isImageFromDocument && !size;\n    const promise = appDownloadManager.downloadMediaURL({\n      media: photo,\n      thumb: size,\n      queueId: lazyLoadQueue && lazyLoadQueue.queueId,\n      onlyCache: haveToDownload ? undefined : noAutoDownload\n    });\n\n    return promise;\n  };\n\n  const renderOnLoad = (url: string) => {\n    return renderMediaWithFadeIn({\n      container,\n      media,\n      url,\n      needFadeIn,\n      aspecter,\n      thumbImage,\n      fadeInElement,\n      onRender,\n      onRenderFinish,\n      useRenderCache\n    });\n  };\n\n  const onLoad = async(url: string) => {\n    if(middleware && !middleware()) return;\n\n    if(processUrl) {\n      url = await processUrl(url);\n    }\n\n    if(blurAfter) {\n      // downscale to a tiny thumbnail before blurring so the upscaled side-fill looks like\n      // frosted glass (matches the official clients), instead of a weak blur on the full image\n      const result = blur(url, 10, 2, 48);\n      return result.promise.then(() => {\n        // image = result.canvas;\n        return renderOnLoad(result.canvas.toDataURL());\n      });\n    }\n\n    return renderOnLoad(url);\n  };\n\n  let loadPromise: Promise<any>;\n  const canAttachPreloader = (\n    !isWebFile &&\n    (size as PhotoSize.photoSize).w >= 150 &&\n    (size as PhotoSize.photoSize).h >= 150\n  ) || noAutoDownload;\n  const load = async() => {\n    if(noAutoDownload && !withoutPreloader && preloader) {\n      preloader.construct();\n      preloader.setManual();\n    }\n\n    const promise = getDownloadPromise();\n    const cacheContext = apiManagerProxy.getCacheContext(photo, size?.type);\n    if(\n      preloader &&\n      !cacheContext.downloaded &&\n      !withoutPreloader &&\n      canAttachPreloader\n    ) {\n      preloader.attach(container, false, promise);\n    }\n\n    noAutoDownload = undefined;\n\n    const renderPromise = promise.then(onLoad);\n    renderPromise.catch(noop);\n    return {download: promise, render: renderPromise};\n  };\n\n  if(preloader) {\n    preloader.setDownloadFunction(load);\n  }\n\n  if(cacheContext.downloaded) {\n    loadThumbPromise = loadPromise = (await load()).render;\n  } else {\n    if(!lazyLoadQueue) loadPromise = (await load()).render;\n    /* else if(noAutoDownload) {\n      preloader.construct();\n      preloader.setManual();\n      preloader.attach(container);\n    } */ else lazyLoadQueue.push({div: container, load: () => load().then(({download}) => download)});\n  }\n\n  if(loadPromises && loadThumbPromise) {\n    loadPromises.push(loadThumbPromise);\n  }\n\n  // const perf = performance.now();\n  // ! do not uncomment this, won't be able to modify element before the thumb is loaded\n  // await loadThumbPromise;\n  ret.loadPromises.thumb = loadThumbPromise;\n  ret.loadPromises.full = loadPromise || Promise.resolve();\n  ret.preloader = preloader;\n\n  // const elapsedTime = performance.now() - perf;\n  // if(elapsedTime > 4) {\n  //   console.log('wrapping photo thumb time', elapsedTime, photo, size);\n  // }\n\n  return ret;\n}\n\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport customProperties from '@helpers/dom/customProperties';\nimport textToSvgURL from '@helpers/textToSvgURL';\nimport rootScope from '@lib/rootScope';\nimport wrapPhoto from '@components/wrappers/photo';\n\nlet addedThemeListener = false;\nexport default function wrapAttachBotIcon({\n  doc,\n  element: iconElement,\n  size,\n  textColor,\n  strokeWidth\n}: {\n  doc: MyDocument,\n  element: HTMLElement,\n  size: number,\n  textColor: () => string,\n  strokeWidth: () => number\n}) {\n  iconElement.classList.add('is-external');\n\n  if(!addedThemeListener) {\n    addedThemeListener = true;\n\n    rootScope.addEventListener('theme_changed', () => {\n      const elements = document.querySelectorAll<HTMLElement>('.is-external');\n      elements.forEach((element) => {\n        const set = (element as any).set;\n        set?.(true);\n      });\n    });\n  }\n\n  const set = async(manual?: boolean) => {\n    const svg: SVGSVGElement = (iconElement as any).svg;\n    const color = customProperties.getProperty(textColor());\n    svg.querySelectorAll('path').forEach((path) => {\n      path.setAttributeNS(null, 'fill', color);\n      path.style.stroke = color;\n      path.style.strokeWidth = strokeWidth() + 'px';\n    });\n\n    const url = await textToSvgURL(svg.outerHTML);\n    if(!manual) {\n      return url;\n    }\n\n    ((iconElement as any).image as HTMLImageElement).src = url;\n  };\n\n  const originalPromise = wrapPhoto({\n    container: iconElement,\n    photo: doc,\n    boxWidth: size,\n    boxHeight: size,\n    withoutPreloader: true,\n    noFadeIn: true,\n    noBlur: true,\n    processUrl: async(url) => {\n      const text = await (await fetch(url)).text();\n      const doc = new DOMParser().parseFromString(text, 'image/svg+xml');\n      const svg = doc.firstElementChild as HTMLElement;\n      (iconElement as any).svg = svg;\n      (iconElement as any).set = set;\n      return set();\n    }\n  });\n\n  return originalPromise.then(async(ret) => {\n    iconElement.style.width = iconElement.style.height = '';\n    (iconElement as any).image = ret.images.full;\n    await ret.loadPromises.thumb;\n    return originalPromise;\n  });\n}\n","import wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport getAbbreviation from '@lib/richTextProcessor/getAbbreviation';\n\nexport default function wrapAbbreviation(str: string, onlyFirst?: boolean) {\n  const {text, entities} = getAbbreviation(str, onlyFirst);\n  return wrapEmojiText(text, undefined, entities);\n}\n","import {Chat, User} from '@layer';\nimport wrapAbbreviation from '@lib/richTextProcessor/wrapAbbreviation';\n\nexport default function getPeerInitials(peer: Chat | User) {\n  let str = '';\n  if(peer) {\n    str = (peer as Chat.chat).title ?? [\n      (peer as User.user).first_name,\n      (peer as User.user).last_name\n    ].filter(Boolean).join(' ');\n  }\n\n  return wrapAbbreviation(str);\n}\n","import {hexaToHsla} from '@helpers/color';\nimport {TOPIC_COLORS} from '@appManagers/constants';\nimport wrapAbbreviation from '@lib/richTextProcessor/wrapAbbreviation';\n\nlet svg: SVGSVGElement, span: HTMLElement, defs: HTMLElement;\nconst hadColors: Map<number, string> = new Map();\nexport default function topicAvatar(color: number, content: string) {\n  if(!svg) {\n    defs = document.getElementById('svg-defs') as HTMLElement;\n\n    const ns = 'http://www.w3.org/2000/svg';\n\n    svg = document.createElementNS(ns, 'svg');\n    svg.setAttributeNS(null, 'width', '26');\n    svg.setAttributeNS(null, 'height', '26');\n    svg.setAttributeNS(null, 'viewBox', '0 0 26 26');\n    svg.classList.add('topic-icon-svg');\n\n    const use = document.createElementNS(ns, 'use');\n    use.setAttributeNS(null, 'href', '#topic-icon');\n    svg.append(use);\n\n    span = document.createElement('span');\n    span.classList.add('topic-icon', 'avatar-like');\n\n    const contentSpan = document.createElement('span');\n    contentSpan.classList.add('topic-icon-content');\n    span.append(svg, contentSpan);\n  }\n\n  if(!color) {\n    console.error('NO TOPIC ICON COLOR!');\n    color = TOPIC_COLORS[0];\n  }\n\n  if(!content) {\n    console.error('NO TOPIC NAME!');\n    content = '';\n  }\n\n  const hex = color.toString(16);\n\n  const gradientId = `topic-icon-gradient-${color}`;\n  let strokeColor = hadColors.get(color);\n  if(!strokeColor) {\n    const {h, s, l, a} = hexaToHsla('#' + hex);\n    defs.insertAdjacentHTML('beforeend', `\n      <linearGradient id=\"${gradientId}\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\">\n        <stop style=\"stop-color: #${hex};\" offset=\"0%\" />\n        <stop style=\"stop-color: hsla(${h}, ${s}%, ${Math.max(0, l - 30)}%, ${a});\" offset=\"100%\" />\n      </linearGradient>\n    `);\n\n    hadColors.set(color, strokeColor = `hsla(${h}, ${s}%, ${Math.max(0, l - 40)}%, ${a})`);\n  }\n\n  const clone = span.cloneNode(true) as typeof span;\n  (clone.firstElementChild as HTMLElement).style.fill = `url(#${gradientId})`;\n  // (clone.firstElementChild as HTMLElement).style.stroke = `var(--peer-avatar-${color}-filled)`;\n  (clone.firstElementChild as HTMLElement).style.stroke = strokeColor;\n  clone.lastElementChild.append(wrapAbbreviation(content, true));\n  return clone;\n}\n","import {MessageEntity} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\n\nexport default function wrapCustomEmoji({\n  docIds,\n  loadPromises,\n  middleware,\n  lazyLoadQueue,\n  customEmojiSize,\n  animationGroup,\n  textColor\n}: {\n  docIds: DocId[],\n  loadPromises?: Promise<any>[]\n} & WrapSomethingOptions) {\n  const text = ' '.repeat(docIds.length);\n  const entities: MessageEntity[] = [];\n  docIds.forEach((docId, idx) => {\n    entities.push({\n      _: 'messageEntityCustomEmoji',\n      offset: idx,\n      length: 1,\n      document_id: docId\n    });\n  });\n\n  const wrapped = wrapRichText(text, {\n    entities,\n    loadPromises,\n    animationGroup,\n    customEmojiSize,\n    middleware,\n    lazyLoadQueue,\n    textColor\n  });\n\n  return wrapped;\n}\n\nexport function wrapCustomEmojiAwaited(options: Parameters<typeof wrapCustomEmoji>[0]) {\n  const loadPromises: Promise<any>[] = options.loadPromises ??= [];\n  const wrapped = wrapCustomEmoji(options);\n  return Promise.all(loadPromises).then(() => wrapped);\n}\n","import {InputGroupCall, Message, MessageAction} from '@layer';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\n\nexport default function wrapJoinVoiceChatAnchor(message: Message.messageService) {\n  const action = message.action as\n    | MessageAction.messageActionInviteToGroupCall\n    | MessageAction.messageActionGroupCall;\n\n  // Legacy voice/video chat in a group/channel — the tg:// URL flow routes\n  // through appImManager.joinGroupCall. Only the messageActionGroupCall /\n  // messageActionInviteToGroupCall variants carry an InputGroupCall on their\n  // `call` field, and both only ever appear for a chat peer. Conference calls\n  // (messageActionConferenceCall, always a private chat) are joined from their\n  // own bubble instead — see `wrapCallBubble`.\n  const call = (action as MessageAction.messageActionInviteToGroupCall).call as InputGroupCall.inputGroupCall;\n  if(!call || call._ !== 'inputGroupCall') {\n    return document.createElement('span');\n  }\n\n  const {onclick, url} = wrapUrl(\n    `tg://voicechat?chat_id=${message.peerId.toChatId()}&id=${call.id}&access_hash=${call.access_hash}`\n  );\n  if(!onclick) {\n    return document.createElement('span');\n  }\n\n  const a = document.createElement('a');\n  a.href = url;\n  a.setAttribute('onclick', onclick + '(this)');\n  return a;\n}\n","import {LangPackKey} from '@lib/langPack';\nimport {MessageAction} from '@layer';\n\n/**\n * State of a conference-call service action, mirroring tdesktop's\n * `Data::CallState` as computed in `ComputeCallData`\n * (data_media_types.cpp:505): a duration means the call is over, otherwise the\n * flags describe whether it was missed, is still running, or is a pending\n * invitation.\n */\nexport type ConferenceCallState = 'invitation' | 'active' | 'missed' | 'hangup';\n\nexport function getConferenceCallState(\n  action: MessageAction.messageActionConferenceCall\n): ConferenceCallState {\n  if(action.duration !== undefined) return 'hangup';\n  if(action.pFlags.missed) return 'missed';\n  if(action.pFlags.active) return 'active';\n  return 'invitation';\n}\n\n/**\n * Title of a conference-call message — tdesktop's `MediaCall::Text`\n * (data_media_types.cpp:1903). It is both the bubble's title and the plain\n * text used for chat list previews, replies and notifications.\n */\nexport function getConferenceCallLangKey(state: ConferenceCallState, isOut: boolean): LangPackKey {\n  if(state === 'invitation') return 'Chat.Service.ConferenceCall.Invitation';\n  if(state === 'active') return 'Chat.Service.ConferenceCall.Ongoing';\n  if(isOut) {\n    return state === 'missed' ?\n      'Chat.Service.ConferenceCall.Declined' :\n      'Chat.Service.ConferenceCall.Outgoing';\n  }\n\n  return state === 'missed' ?\n    'Chat.Service.ConferenceCall.Missed' :\n    'Chat.Service.ConferenceCall.Incoming';\n}\n","export default function partition<T>(arr: T[], callback: (item: T, idx: number, arr: T[]) => boolean) {\n  const good: T[] = [], bad: T[] = [];\n  for(let i = 0, length = arr.length; i < length; ++i) {\n    const item = arr[i];\n    (callback(item, i, arr) ? good : bad).push(item);\n  }\n\n  return [good, bad];\n}\n","export default function htmlToDocumentFragment(html: string | DocumentFragment) {\n  if(html instanceof DocumentFragment) return html;\n  const template = document.createElement('template');\n  html = html.trim(); // Never return a text node of whitespace as the result\n  template.innerHTML = html;\n  return template.content;\n}\n","import {isRestricted, isSensitive} from '@helpers/restrictions';\nimport {Message} from '@layer';\n\nexport default function isMessageRestricted(message: Message.message) {\n  return !!(message.restriction_reason && isRestricted(message.restriction_reason));\n}\n\nexport function isMessageSensitive(message: Message) {\n  return (message._ === 'message' && message.restriction_reason != null && isSensitive(message.restriction_reason));\n}\n","import {TextWithEntities} from '@layer';\nimport mergeEntities from '@lib/richTextProcessor/mergeEntities';\nimport wrapMessageEntities from '@lib/richTextProcessor/wrapMessageEntities';\n\nexport default function wrapTextWithEntities(textWithEntities: TextWithEntities): TextWithEntities {\n  const {message, entities, myEntities} = wrapMessageEntities(textWithEntities.text, textWithEntities.entities);\n  const totalEntities = mergeEntities(entities, myEntities.filter((entity) => entity._ === 'messageEntityCustomEmoji' || entity._ === 'messageEntityEmoji'));\n  return {_: 'textWithEntities', text: message, entities: totalEntities};\n}\n","import {AckedResult} from '@lib/superMessagePort';\nimport {Modify} from '@types';\n\nexport default async function modifyAckedResult<T>(acked: AckedResult<T>): Promise<Modify<AckedResult<T>, {result: T | Promise<T>}>> {\n  return {\n    cached: acked.cached,\n    result: acked.cached ? await acked.result : acked.result\n  };\n}\n\nexport function modifyAckedPromise<T>(promise: Promise<AckedResult<T>>) {\n  return promise.then(modifyAckedResult);\n}\n","import {createMemo, createRoot, Accessor, onCleanup} from 'solid-js';\n\ntype T = Partial<{\n  count: number,\n  factory: () => any,\n  value: any,\n  dispose: () => void\n}>;\n\nconst cache = new Map<string, T>();\n\nexport default function useDynamicCachedValue<T>(cacheKey: Accessor<string>, factory: () => T): Accessor<T> {\n  return createMemo(() => {\n    const currentKey = cacheKey();\n    let entry = cache.get(currentKey);\n\n    if(!entry) {\n      entry = {count: 0, factory};\n      entry.value = createRoot((dispose) => {\n        entry.dispose = dispose;\n        return factory();\n      });\n      cache.set(currentKey, entry);\n    }\n\n    ++entry.count;\n\n    onCleanup(() => {\n      if(!--entry.count) {\n        entry.dispose();\n        cache.delete(currentKey);\n      }\n    });\n\n    return entry.value;\n  });\n}\n","import {createStore, reconcile, unwrap} from 'solid-js/store';\nimport {ChatFull, UserFull} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport useDynamicCachedValue from '@helpers/solid/useDynamicCachedValue';\nimport {onCleanup} from 'solid-js';\nimport {PEER_FULL_TTL} from '@appManagers/constants';\n\nexport type PeerFull = ChatFull | UserFull;\n\nconst [state, setState] = createStore<{[peerId: PeerId]: PeerFull}>({});\nconst expirations = new Map<PeerId, number>();\n\nconst requestFullPeer = (peerId: PeerId, overwrite?: boolean) => {\n  rootScope.managers.appProfileManager.getProfileByPeerId(\n    peerId,\n    overwrite\n  ).then((fullPeer) => {\n    if(overwrite !== false) {\n      expirations.set(peerId, Date.now() + PEER_FULL_TTL);\n    }\n\n    setState(peerId, reconcile(fullPeer));\n  });\n};\n\nrootScope.addEventListener('peer_full_update', requestFullPeer);\n\nfunction _useFullPeer(peerId: PeerId) {\n  const fullPeer = () => state[peerId];\n\n  const expiration = expirations.get(peerId);\n  if(!expiration || !fullPeer()) {\n    requestFullPeer(peerId, false);\n  }\n\n  const delay = (expiration || 0) - Date.now();\n  const timeout = delay > 0 ? setTimeout(() => {\n    requestFullPeer(peerId, true);\n  }, delay) : 0;\n\n  const interval = setInterval(() => {\n    requestFullPeer(peerId, true);\n  }, PEER_FULL_TTL);\n\n  onCleanup(() => {\n    clearInterval(interval);\n    clearTimeout(timeout);\n  });\n\n  return fullPeer;\n}\n\nexport function useFullPeer(peerId: PeerId) {\n  return useDynamicCachedValue(\n    () => _useFullPeer.name + '-' + peerId,\n    () => _useFullPeer(peerId)\n  )();\n}\n\n/** Sync read of the cached fullPeer (no fetch, no reactive subscription). */\nexport function getCachedFullPeer(peerId: PeerId): PeerFull | undefined {\n  return unwrap(state[peerId]);\n}\n","import deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\n\nlet worker: Worker;\nlet promises: CancellablePromise<TranslatableLanguageISO>[];\n\nexport default function detectLanguage(text: string): Promise<TranslatableLanguageISO> {\n  if(!worker) {\n    worker = new Worker(new URL('./tinyld.worker.ts', import.meta.url), {type: 'module'});\n    worker.addEventListener('message', (e) => {\n      const {lang} = e.data;\n      const promise = promises.shift();\n      promise.resolve(lang);\n    });\n\n    promises = [];\n  }\n\n  const deferred = deferredPromise<TranslatableLanguageISO>();\n  promises.push(deferred);\n  worker.postMessage({text});\n  return deferred;\n}\n","import {createMemo, batch, untrack, createRoot, createEffect, on, Accessor} from 'solid-js';\nimport {createStore, SetStoreFunction} from 'solid-js/store';\nimport {Message} from '@layer';\nimport I18n from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport detectLanguage from '@lib/tinyld/detect';\nimport {useAppSettings} from '@stores/appSettings';\n\n// https://core.telegram.org/api/translation\nexport const MIN_TOTAL_PROCESSED_MESSAGES = 8;\nexport const MIN_FOREIGN_PERCENTAGE = 0.65;\n\ntype TT = {\n  messages: {[mid: number]: TranslatableLanguageISO},\n  languages: {[lang: string]: number},\n  language: TranslatableLanguageISO,\n  total: number,\n  totalForeign: number,\n  isFull?: boolean\n};\n\ntype T = {\n  [peerId: PeerId]: TT\n};\n\nlet state: T, setState: SetStoreFunction<T>, myLanguages: Accessor<Set<TranslatableLanguageISO>>;\nlet _createStore = () => {\n  _createStore = undefined;\n  [state, setState] = createStore({});\n\n  createRoot(() => {\n    const [appSettings] = useAppSettings();\n    myLanguages = createMemo(() => {\n      const myLanguages = new Set(\n        appSettings.translations.doNotTranslate.concat(\n          navigator.language.split('-')[0] as TranslatableLanguageISO,\n          I18n.langCodeNormalized()\n        )\n      );\n\n      return myLanguages;\n    });\n\n    createEffect(on(\n      myLanguages,\n      (myLanguages) => batch(() => {\n        for(const peerId in state) {\n          const current = state[peerId];\n          if(!current) {\n            continue;\n          }\n\n          let newTotalForeign = 0;\n          for(const lang in current.languages) {\n            if(!myLanguages.has(lang as TranslatableLanguageISO)) {\n              newTotalForeign += current.languages[lang];\n            }\n          }\n\n          setState(peerId.toPeerId(), 'totalForeign', newTotalForeign);\n        }\n      }),\n      {defer: true}\n    ));\n  });\n};\n\nfunction createEmpty(): TT {\n  return {\n    messages: {},\n    languages: {},\n    language: undefined,\n    total: 0,\n    totalForeign: 0\n  };\n}\n\nexport function setPeerLanguageLoaded(peerId: PeerId) {\n  _createStore?.();\n  if(!untrack(() => state[peerId])) {\n    setState(peerId, createEmpty());\n  }\n  setState(peerId, 'isFull', true);\n}\n\nexport async function processMessageForTranslation(peerId: PeerId, mid: number) {\n  _createStore?.();\n  if(state[peerId] && state[peerId].messages[mid]) {\n    return;\n  }\n\n  const message = apiManagerProxy.getMessageByPeer(peerId, mid);\n  const text = (message as Message.message)?.message;\n  if(!text) {\n    return;\n  }\n\n  const lang = await detectLanguage(text);\n  const isForeign = !myLanguages().has(lang);\n  batch(() => {\n    let previous = untrack(() => state[peerId]);\n    if(!previous) {\n      setState(peerId, previous = createEmpty());\n    } else if(previous.messages[mid]) {\n      return;\n    }\n\n    const newLanguageLength = (previous.languages[lang] ?? 0) + 1;\n    const newTotal = previous.total + 1;\n    const newTotalForeign = previous.totalForeign + (isForeign ? 1 : 0);\n    setState(peerId, 'messages', mid, lang);\n    setState(peerId, 'languages', lang, newLanguageLength);\n    setState(peerId, 'total', newTotal);\n    if(isForeign) setState(peerId, 'totalForeign', newTotalForeign);\n\n    const previousLanguage = previous.language;\n    if((previous.languages[previousLanguage] || 0) < newLanguageLength) {\n      setState(peerId, 'language', lang);\n    }\n  });\n}\n\nexport default function usePeerLanguage(peerId: () => PeerId, onlyIfForeign?: boolean) {\n  return createMemo(() => {\n    const _peerId = peerId();\n    if(!_peerId) {\n      return;\n    }\n\n    _createStore?.();\n    const current = state[_peerId];\n    if(current && current.total < MIN_TOTAL_PROCESSED_MESSAGES && !current.isFull) {\n      return;\n    }\n\n    if(onlyIfForeign && current && (current.totalForeign / current.total) < MIN_FOREIGN_PERCENTAGE) {\n      return;\n    }\n\n    return current?.language;\n  });\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\n\nconst [premium, setPremium] = createRoot(() => createSignal(rootScope.premium));\n\nconst onAuth = () => {\n  rootScope.managers.rootScope.getPremium().then(setPremium);\n};\n\nrootScope.addEventListener('premium_toggle', setPremium);\nif(rootScope.myId) {\n  onAuth();\n} else {\n  rootScope.addEventListener('user_auth', onAuth);\n}\n\nexport default function usePremium() {\n  return premium;\n}\n","import {useFullPeer} from '@stores/fullPeers';\nimport {createEffect, createMemo} from 'solid-js';\nimport usePeerLanguage from '@stores/peerLanguage';\nimport useDynamicCachedValue from '@helpers/solid/useDynamicCachedValue';\nimport I18n from '@lib/langPack';\nimport usePremium from '@stores/premium';\nimport {useAppSettings} from '@stores/appSettings';\nimport {usePeer} from '@stores/peers';\nimport {Chat} from '@layer';\nimport {useAppState} from '@stores/appState';\n\nfunction _usePeerTranslation(peerId: PeerId) {\n  const [appSettings, setAppSettings] = useAppSettings();\n  const [appState] = useAppState();\n\n  const fullPeer = useFullPeer(peerId);\n  const peer = usePeer(() => peerId);\n  const peerLanguage = usePeerLanguage(() => peerId, true);\n  const isPremium = usePremium();\n\n  const areTranslationsAvailable = (manual?: boolean) => {\n    if(appState.appConfig.freeze_since_date) {\n      return false;\n    }\n\n    const appConfig = appState?.appConfig;\n    if((manual ? appConfig?.translations_manual_enabled : appConfig?.translations_auto_enabled) !== 'enabled') {\n      return false;\n    }\n\n    return true;\n  };\n\n  const canTranslate = (manual?: boolean) => {\n    if(!areTranslationsAvailable(manual)) {\n      return false;\n    }\n\n    if(manual) {\n      return true;\n    }\n\n    return isPremium() || (!!peer() && !!(peer() as Chat.channel).pFlags.autotranslation);\n  };\n\n  const shouldShow = createMemo<boolean | undefined>(() => {\n    if(!canTranslate() || !peerLanguage() || !appSettings.translations.enabled) {\n      return;\n    }\n\n    const _fullPeer = fullPeer();\n    if(\n      (!_fullPeer || ('pFlags' in _fullPeer && _fullPeer.pFlags.translations_disabled)) ||\n      appSettings.translations.doNotTranslate.includes(peerLanguage())\n    ) {\n      return false;\n    }\n\n    return true;\n  });\n\n  const ret = {\n    peerLanguage,\n    language: (): TranslatableLanguageISO => (appSettings.translations.peers[peerId] || I18n.langCodeNormalized()) as any,\n    setLanguage: (lang: string) => setAppSettings('translations', 'peers', peerId, lang),\n    enabled: createMemo(() => !!(canTranslate() && appSettings.translations.enabled && appSettings.translations.enabledPeers[peerId]) && shouldShow()),\n    toggle: (enabled: boolean) => setAppSettings('translations', 'enabledPeers', peerId, enabled ? true : undefined),\n    shouldShow,\n    canTranslate,\n    areTranslationsAvailable\n  } as const;\n\n  createEffect(() => {\n    if(ret.shouldShow() === false && ret.enabled()) {\n      ret.toggle(false);\n    }\n  });\n\n  return ret;\n}\n\nexport default function usePeerTranslation(peerId: PeerId) {\n  return useDynamicCachedValue(() => usePeerTranslation.name + '-' + peerId, () => _usePeerTranslation(peerId))();\n}\n","import deferredPromise from '@helpers/cancellablePromise';\nimport {Middleware} from '@helpers/middleware';\nimport {modifyAckedPromise} from '@helpers/modifyAckedResult';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport {Message, TextWithEntities} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {createRoot, createSignal, createMemo, onCleanup, createEffect, Accessor, untrack} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport SuperIntersectionObserver from '@helpers/dom/superIntersectionObserver';\nimport {processMessageForTranslation} from '@stores/peerLanguage';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\n\nconst USE_OBSERVER = false;\n\nexport function TranslatableMessageTsx(props: {\n  peerId: PeerId,\n  message?: Message.message,\n  textWithEntities?: TextWithEntities,\n  richTextOptions?: Parameters<typeof wrapRichText>[1],\n  observer?: SuperIntersectionObserver,\n  observeElement?: HTMLElement,\n  container?: HTMLElement,\n  enabled?: boolean,\n  summarizing?: Accessor<boolean>,\n  onTranslation?: (callback: () => void) => void,\n  onTextWithEntities?: (textWithEntities: TextWithEntities) => TextWithEntities,\n  onFragment?: (fragment: DocumentFragment) => DocumentFragment,\n  onError?: (error: ApiError) => void\n}) {\n  const useObserver = USE_OBSERVER && props.observer && props.enabled === undefined;\n  const [visible, setVisible] = createSignal(!useObserver);\n  const wasVisible = createMemo<boolean>((prev) => prev || visible());\n  const [textWithEntities, setTextWithEntities] = createSignal<TextWithEntities>();\n  const translation = usePeerTranslation(props.peerId);\n  const deferred = deferredPromise<void>();\n  let originalText: TextWithEntities = props.textWithEntities;\n  let first = true, hadText = false;\n\n  const dontShowOriginalFirst = props.enabled;\n  const container = props.container ?? document.createElement('span');\n  container.classList.add('translatable-message');\n\n  if(props.message) {\n    processMessageForTranslation(props.peerId, props.message.mid);\n    originalText = {\n      _: 'textWithEntities',\n      text: props.message.message,\n      entities: props.message.totalEntities\n    };\n  }\n\n  if(props.richTextOptions?.loadPromises) {\n    props.richTextOptions.loadPromises.push(deferred);\n  }\n\n  const translate = (lang: string, onlyCache?: boolean) => {\n    return modifyAckedPromise(rootScope.managers.acknowledged.appTranslationsManager.translateText({\n      ...(props.message ? {\n        peerId: props.message.peerId,\n        mid: props.message.mid\n      } : {\n        text: props.textWithEntities\n      }),\n      lang,\n      onlyCache\n    }));\n  };\n\n  const summarizeText = (lang?: string) => {\n    return modifyAckedPromise(rootScope.managers.acknowledged.appTranslationsManager.summarizeText({\n      peerId: props.peerId,\n      mid: props.message.mid,\n      lang\n    }));\n  };\n\n  const setOriginalText = (loading?: boolean) => {\n    setTextWithEntities(originalText);\n    container.classList.toggle('text-loading', !!loading);\n  };\n\n  if(props.observer && props.observeElement && useObserver) {\n    const onVisible = (entry: IntersectionObserverEntry) => {\n      setVisible(entry.isIntersecting);\n    };\n\n    props.observer.observe(props.observeElement, onVisible);\n    onCleanup(() => {\n      props.observer.unobserve(props.observeElement, onVisible);\n    });\n  }\n\n  createEffect(async() => {\n    const middleware = createMiddleware().get();\n    const _first = first;\n    first = false;\n\n    const summarizing = props.summarizing?.();\n\n    // if the message is invisible and it's not the first time we're opening the chat\n    if(!summarizing && ((!translation.enabled() && !props.enabled) || (!wasVisible() && !_first))) {\n      setOriginalText();\n      return;\n    }\n\n    const r = await (summarizing ?\n      summarizeText(translation.enabled() ? translation.language() : undefined) :\n      translate(translation.language(), _first && useObserver));\n    if(!middleware()) {\n      return;\n    }\n\n    if(!r.cached) {\n      if(!dontShowOriginalFirst && !untrack(textWithEntities)) {\n        setOriginalText(true);\n      } else {\n        container.classList.add('text-loading');\n      }\n    } else if(!r.result) {\n      setOriginalText();\n      return;\n    }\n\n    try {\n      const textWithEntities$ = await r.result;\n      if(!middleware()) {\n        return;\n      }\n\n      if(!textWithEntities$) {\n        setOriginalText();\n        return;\n      }\n\n      setTextWithEntities(textWithEntities$);\n    } catch(err) {\n      if(!middleware()) {\n        return;\n      }\n\n      setOriginalText();\n      props.onError?.(err as ApiError);\n    }\n  });\n\n  createEffect(() => {\n    let r = textWithEntities();\n    if(!r) {\n      return;\n    }\n\n    if(props.onTextWithEntities) {\n      r = props.onTextWithEntities(r);\n    }\n\n    if(originalText !== r || !props.message) {\n      r = wrapTextWithEntities(r);\n    }\n\n    const middleware = createMiddleware().get();\n    const loadPromises: Promise<any>[] = [];\n    let wrapped = wrapRichText(r.text, {\n      ...(props.richTextOptions || {}),\n      loadPromises,\n      entities: r.entities\n    });\n\n    Promise.all(loadPromises).then(() => {\n      if(!middleware()) return;\n\n      const set = () => {\n        if(!middleware()) return;\n        deferred.resolve();\n\n        if(props.onFragment) {\n          wrapped = props.onFragment(wrapped);\n        }\n\n        container.replaceChildren(wrapped);\n        if(hadText || dontShowOriginalFirst) container.classList.remove('text-loading');\n        hadText = true;\n      };\n\n      if(hadText && props.onTranslation) {\n        props.onTranslation(set);\n        return;\n      }\n\n      set();\n    });\n  });\n\n  return container;\n}\n\nexport default function TranslatableMessage(props: Parameters<typeof TranslatableMessageTsx>[0] & {middleware: Middleware}) {\n  return createRoot((dispose) => {\n    props.middleware.onDestroy(dispose);\n    return TranslatableMessageTsx(props);\n  });\n}\n","import type {MyMessage} from '@appManagers/appMessagesManager';\nimport wrapMessageActionTextNewUnsafe from '@components/wrappers/messageActionTextNewUnsafe';\n\nexport type WrapMessageActionTextOptions = {\n  message: MyMessage,\n  plain?: boolean,\n  noLinks?: boolean,\n  noTextFormat?: boolean\n} & WrapSomethingOptions;\n\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions & {plain: true}): Promise<string>;\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions & {plain?: false}): Promise<HTMLElement>;\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions): Promise<string | HTMLElement>;\n\nexport default async function wrapMessageActionTextNew(options: WrapMessageActionTextOptions): Promise<string | HTMLElement> {\n  try {\n    return await wrapMessageActionTextNewUnsafe(options);\n  } catch(err) {\n    console.error('wrapMessageActionTextNewUnsafe error:', err);\n    return options.plain ? '' : document.createElement('span');\n  }\n}\n","import {_i18n} from '@lib/langPack';\n\nexport default function generateFakeIcon(isScam?: boolean) {\n  const span = document.createElement('span');\n  span.classList.add('badge-fake');\n  _i18n(span, isScam ? 'ScamMessage' : 'FakeMessage');\n  return span;\n}\n","import Icon from '@components/icon';\n\nexport default function generatePremiumIcon() {\n  const span = Icon('star', 'premium-icon');\n  return span;\n}\n","export default function generateVerifiedIcon() {\n  const span = document.createElement('span');\n  span.classList.add('verified-icon');\n\n  const size = 26; // 24\n  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n  svg.setAttributeNS(null, 'viewBox', `0 0 ${size} ${size}`);\n  svg.setAttributeNS(null, 'width', `${size}`);\n  svg.setAttributeNS(null, 'height', `${size}`);\n  svg.classList.add('verified-icon-svg');\n\n  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n  use.setAttributeNS(null, 'href', '#verified-icon-background');\n  use.classList.add('verified-icon-background');\n\n  const use2 = document.createElementNS('http://www.w3.org/2000/svg', 'use');\n  use2.setAttributeNS(null, 'href', '#verified-icon-check');\n  use2.classList.add('verified-icon-check');\n\n  // svg.append(use, use2);\n  svg.append(use2, use);\n\n  span.append(svg);\n\n  return span;\n  // const span = document.createElement('span');\n  // span.classList.add('verified-icon', 'tgico-verified_filled');\n  // return span;\n}\n","import {i18n, LangPackKey} from '@lib/langPack';\n\nexport default function formatBytes(bytes: number, decimals: number | 'auto' = 'auto') {\n  if(bytes === 0) return i18n('FileSize.B', [0]);\n\n  const strictDecimals = decimals === 'auto';\n\n  const k = 1024;\n  const sizes: LangPackKey[] = ['FileSize.B', 'FileSize.KB', 'FileSize.MB', 'FileSize.GB', 'FileSize.TB', 'FileSize.PB'];\n  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1);\n  const _decimals = decimals === 'auto' ? Math.max(0, i - 1) : decimals;\n\n  const dm = Math.max(0, _decimals);\n\n  const fixed = (bytes / Math.pow(k, i)).toFixed(dm);\n  return i18n(sizes[i], [strictDecimals ? fixed : parseFloat(fixed)]);\n}\n","import {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport {Document} from '@layer';\nimport {ApiLimitType} from '@appManagers/apiManagerMethods';\nimport {AppManagers} from '@lib/managers';\nimport formatBytes from '@helpers/formatBytes';\n\nexport interface PremiumPromoFeature {\n  feature: PremiumPromoFeatureType;\n  icon: Icon;\n  titleLangKey: LangPackKey;\n  subtitleLangKey: LangPackKey;\n  actionTitleLangKey?: LangPackKey;\n  actionIcon?: Icon;\n  headerLangKey?: LangPackKey;\n  titleLangArgs?: FormatterArguments;\n  subtitleLangArgs?: FormatterArguments;\n  _titleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n  _subtitleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n  videoPosition?: 'bottom' | 'top';\n  video?: Document.document;\n  wrappedVideo?: any;\n  type?: string;\n  content?: Array<{\n    titleLangKey?: LangPackKey,\n    titleLangArgs?: FormatterArguments,\n    _titleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>;\n    subtitleLangKey?: LangPackKey,\n    subtitleLangArgs?: FormatterArguments,\n    _subtitleLangArgs?: (managers: AppManagers) => MaybePromise<FormatterArguments>,\n    iconColor?: string,\n    icon?: Icon,\n    backgroundColor?: string,\n    limitType?: ApiLimitType,\n    name?: string,\n    free?: number,\n    premium?: number\n  }>;\n  new?: boolean,\n  builded?: boolean\n}\n\nexport const PREMIUM_FEATURES_COLORS: string[] = [\n  '#ef6922',\n  '#e95a2c',\n  '#e74e33',\n  '#e3433c',\n  '#db374b',\n  '#cb3e6d',\n  '#bc4395',\n  '#ab4ac4',\n  '#9b4fed',\n  '#8958ff',\n  '#676bff',\n  '#5b79ff',\n  '#4492ff',\n  '#429bd5',\n  '#41a6a5',\n  '#3eb26d',\n  '#3dbd4a'\n];\n\nconst stories: PremiumPromoFeature = {\n  feature: 'stories',\n  icon: 'stories',\n  titleLangKey: 'Premium.Boarding.Stories.Title',\n  subtitleLangKey: 'Premium.Boarding.Stories.Info',\n  type: 'upgraded-stories',\n  content: [{\n    titleLangKey: 'PremiumStoriesPriority',\n    subtitleLangKey: 'PremiumStoriesPriorityDescription',\n    iconColor: '#0079FE',\n    icon: 'multistories'\n  }, {\n    titleLangKey: 'PremiumStoriesStealth',\n    subtitleLangKey: 'PremiumStoriesStealthDescription',\n    iconColor: '#7889FE',\n    icon: 'eyecross'\n  }, {\n    titleLangKey: 'PremiumStoriesViews',\n    subtitleLangKey: 'PremiumStoriesViewsDescription',\n    iconColor: '#A45FE6',\n    icon: 'eye'\n  }, {\n    titleLangKey: 'PremiumStoriesExpiration',\n    subtitleLangKey: 'PremiumStoriesExpirationDescription',\n    iconColor: '#C355AE',\n    icon: 'timer_filled'\n  }, {\n    titleLangKey: 'PremiumStoriesSaveToGallery',\n    subtitleLangKey: 'PremiumStoriesSaveToGalleryDescription',\n    iconColor: '#E85D43',\n    icon: 'arrowcircle'\n  }, {\n    titleLangKey: 'PremiumStoriesCaption',\n    subtitleLangKey: 'PremiumStoriesCaptionDescription',\n    iconColor: '#F1822A',\n    icon: 'list'\n  }, {\n    titleLangKey: 'PremiumStoriesFormatting',\n    subtitleLangKey: 'PremiumStoriesFormattingDescription',\n    iconColor: '#E6AC19',\n    icon: 'limit_link'\n  }]\n};\n\nconst wrapGetLimitArgument = (limitType: ApiLimitType) => (managers: AppManagers) => managers.apiManager.getLimit(limitType, true).then((limit) => [limit]);\n\nconst doubleLimits: PremiumPromoFeature = {\n  feature: 'double_limits',\n  icon: 'premium_limits_filled',\n  titleLangKey: 'Premium.Boarding.Double.Title',\n  subtitleLangKey: 'Premium.Boarding.Double.Info',\n  headerLangKey: 'Premium.Boarding.Double.Title',\n  _subtitleLangArgs: (managers) => Promise.all(\n    (['channels', 'folders', 'pin', 'links'] as ApiLimitType[]).map((type) => {\n      return managers.apiManager.getLimit(type, true);\n    })\n  ),\n  type: 'limits',\n  content: [{\n    titleLangKey: 'GroupsAndChannelsLimitTitle',\n    subtitleLangKey: 'GroupsAndChannelsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('channels'),\n    limitType: 'channels',\n    backgroundColor: '#5B9FFF'\n  }, {\n    titleLangKey: 'PinChatsLimitTitle',\n    subtitleLangKey: 'PinChatsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('pin'),\n    limitType: 'pin',\n    backgroundColor: '#7889FE'\n  }, {\n    titleLangKey: 'PublicLinksLimitTitle',\n    subtitleLangKey: 'PublicLinksLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('links'),\n    limitType: 'links',\n    backgroundColor: '#9376FF'\n  }, {\n    titleLangKey: 'SavedGifsLimitTitle',\n    subtitleLangKey: 'SavedGifsLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('gifs'),\n    limitType: 'gifs',\n    backgroundColor: '#AB63F2'\n  }, {\n    titleLangKey: 'FavoriteStickersLimitTitle',\n    subtitleLangKey: 'FavoriteStickersLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('favedStickers'),\n    limitType: 'favedStickers',\n    backgroundColor: '#C456AE'\n  }, {\n    titleLangKey: 'BioLimitTitle',\n    subtitleLangKey: 'BioLimitSubtitle',\n    limitType: 'bio',\n    backgroundColor: '#CE569A'\n  }, {\n    titleLangKey: 'CaptionsLimitTitle',\n    subtitleLangKey: 'CaptionsLimitSubtitle',\n    limitType: 'caption',\n    backgroundColor: '#DA5786'\n  }, {\n    titleLangKey: 'FoldersLimitTitle',\n    subtitleLangKey: 'FoldersLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('folders'),\n    limitType: 'folders',\n    backgroundColor: '#DB496F'\n  }, {\n    titleLangKey: 'ChatPerFolderLimitTitle',\n    subtitleLangKey: 'ChatPerFolderLimitSubtitle',\n    _subtitleLangArgs: wrapGetLimitArgument('folderPeers'),\n    limitType: 'folderPeers',\n    backgroundColor: '#E85D43'\n  }, {\n    titleLangKey: 'ConnectedAccountsLimitTitle',\n    subtitleLangKey: 'ConnectedAccountsLimitSubtitle',\n    subtitleLangArgs: [4],\n    free: 3,\n    premium: 4,\n    backgroundColor: '#F1822A'\n  }]\n};\n\nconst formatParts = (parts: number) => formatBytes(parts * 1.024 * 512 * 1024, 0);\n\nexport const PREMIUM_FEATURES: {[type in PremiumPromoFeatureType]?: PremiumPromoFeature} = {\n  stories: stories,\n  double_limits: doubleLimits,\n  voice_to_text: {\n    feature: 'voice_to_text',\n    icon: 'premium_transcription_filled',\n    titleLangKey: 'Premium.Boarding.Voice.Title',\n    subtitleLangKey: 'Premium.Boarding.Voice.Info',\n    videoPosition: 'top'\n  },\n  faster_download: {\n    feature: 'faster_download',\n    icon: 'premium_speed_filled',\n    titleLangKey: 'Premium.Boarding.Download.Title',\n    subtitleLangKey: 'Premium.Boarding.Download.Info',\n    videoPosition: 'top'\n  },\n  translations: {\n    feature: 'translations',\n    icon: 'premium_translate',\n    titleLangKey: 'Premium.Boarding.Translate.Title',\n    subtitleLangKey: 'Premium.Boarding.Translate.Info',\n    videoPosition: 'top'\n  },\n  animated_emoji: {\n    feature: 'animated_emoji',\n    icon: 'premium_emoji_filled',\n    titleLangKey: 'Premium.Boarding.Emoji.Title',\n    subtitleLangKey: 'Premium.Boarding.Emoji.Info'\n  },\n  more_upload: {\n    feature: 'more_upload',\n    icon: 'premium_filesize_filled',\n    titleLangKey: 'Premium.Boarding.FileSize.Title',\n    _titleLangArgs: (managers) => managers.apiManager.getLimit('uploadFileParts', true).then((parts) => [formatParts(parts)]),\n    subtitleLangKey: 'Premium.Boarding.FileSize.Info',\n    _subtitleLangArgs: (managers) => Promise.all(\n      [false, true].map(async(isPremium) => {\n        const parts = await managers.apiManager.getLimit('uploadFileParts', isPremium);\n        return formatParts(parts);\n      })\n    )\n  },\n  emoji_status: {\n    feature: 'emoji_status',\n    icon: 'premium_status_filled',\n    titleLangKey: 'Premium.Boarding.Status.Title',\n    subtitleLangKey: 'Premium.Boarding.Status.Info',\n    videoPosition: 'top'\n  },\n  peer_colors: {\n    feature: 'peer_colors',\n    icon: 'premium_colors_filled',\n    titleLangKey: 'Premium.Promo.Colors.Title',\n    subtitleLangKey: 'Premium.Promo.Colors.Subtitle',\n    videoPosition: 'top'\n  },\n  wallpapers: {\n    feature: 'wallpapers',\n    icon: 'premium_wallpaper_filled',\n    titleLangKey: 'Premium.Promo.Wallpaper.Title',\n    subtitleLangKey: 'Premium.Promo.Wallpaper.Subtitle',\n    videoPosition: 'top',\n    new: true\n  },\n  profile_badge: {\n    feature: 'profile_badge',\n    icon: 'star',\n    titleLangKey: 'Premium.Boarding.Badge.Title',\n    subtitleLangKey: 'Premium.Boarding.Badge.Info',\n    videoPosition: 'top'\n  },\n  advanced_chat_management: {\n    feature: 'advanced_chat_management',\n    icon: 'premium_management_filled',\n    titleLangKey: 'Premium.Boarding.Chats.Title',\n    subtitleLangKey: 'Premium.Boarding.Chats.Info',\n    videoPosition: 'top'\n  },\n  no_ads: {\n    feature: 'no_ads',\n    icon: 'premium_noads_filled',\n    titleLangKey: 'Premium.Boarding.NoAds.Title',\n    subtitleLangKey: 'Premium.Boarding.NoAds.Info'\n    // actionTitleLangKey: 'Premium.Boarding.NoAds.Action',\n    // actionIcon: 'premium_badge'\n  },\n  infinite_reactions: {\n    feature: 'infinite_reactions',\n    icon: 'premium_reactions_filled',\n    titleLangKey: 'Premium.Boarding.ReactionsNew.Title',\n    subtitleLangKey: 'Premium.Boarding.ReactionsNew.Info',\n    videoPosition: 'top'\n    // actionIcon: 'premium_unlock'\n  },\n  animated_userpics: {\n    feature: 'animated_userpics',\n    icon: 'premium_avatars_filled',\n    titleLangKey: 'Premium.Boarding.Avatar.Title',\n    subtitleLangKey: 'Premium.Boarding.Avatar.Info',\n    videoPosition: 'top'\n  },\n  premium_stickers: {\n    feature: 'premium_stickers',\n    icon: 'premium_stickers_filled',\n    titleLangKey: 'Premium.Boarding.Stickers.Title',\n    subtitleLangKey: 'Premium.Boarding.Stickers.Info',\n    // actionIcon: 'premium_unlock',\n    type: 'premium-stickers'\n  },\n  last_seen: {\n    feature: 'last_seen',\n    icon: 'premium_lastseen_filled',\n    titleLangKey: 'PremiumPreviewLastSeen',\n    subtitleLangKey: 'PremiumPreviewLastSeenDescription',\n    new: true\n  },\n  message_privacy: {\n    feature: 'message_privacy',\n    icon: 'premium_privacy_filled',\n    titleLangKey: 'PremiumPreviewMessagePrivacy',\n    subtitleLangKey: 'PremiumPreviewMessagePrivacyDescription',\n    new: true\n  },\n  saved_tags: {\n    feature: 'saved_tags',\n    icon: 'premium_tags_filled',\n    titleLangKey: 'PremiumPreviewTags',\n    subtitleLangKey: 'PremiumPreviewTagsDescription2'\n  },\n  pm_noforwards: {\n    feature: 'pm_noforwards',\n    icon: 'sharingoff_filled',\n    titleLangKey: 'Premium.Boarding.NoForwards.Title',\n    subtitleLangKey: 'Premium.Boarding.NoForwards.Info',\n    videoPosition: 'top'\n  }\n};\n","import type {Message, MessageAction} from '@layer';\nimport type {HistoryResult, MyMessage} from '@appManagers/appMessagesManager';\nimport forEachReverse from '@helpers/array/forEachReverse';\n\nexport default function filterChatPhotosMessages(value: HistoryResult) {\n  forEachReverse(value.messages, (message, idx, arr) => {\n    // * the message can be missing when its mid was resolved from a storage that doesn't have it\n    if(!((message as Message.messageService)?.action as MessageAction.messageActionChatEditPhoto)?.photo) {\n      arr.splice(idx, 1);\n      if(value.count !== undefined) {\n        --value.count;\n      }\n    }\n  });\n}\n","import forEachReverse from '@helpers/array/forEachReverse';\nimport safeAssign from '@helpers/object/safeAssign';\n\nexport type ListLoaderOptions<T extends {}, P extends {}> = {\n  loadMore: ListLoader<T, P>['loadMore'],\n  loadCount?: ListLoader<T, P>['loadCount'],\n  loadWhenLeft?: ListLoader<T, P>['loadWhenLeft'],\n  processItem?: ListLoader<T, P>['processItem'],\n  onJump?: ListLoader<T, P>['onJump'],\n  onLoadedMore?: ListLoader<T, P>['onLoadedMore']\n};\n\nexport type ListLoaderResult<T extends {}> = {count: number, items: any[]};\nexport default class ListLoader<T extends {}, P extends {}> {\n  public current: T;\n  public previous: T[] = [];\n  public next: T[] = [];\n  public count: number;\n  public reverse = false; // reverse means next = higher msgid\n\n  protected loadMore: (anchor: T, older: boolean, loadCount: number) => Promise<ListLoaderResult<T>>;\n  protected processItem: (item: P) => T | Promise<T>;\n  protected loadCount = 50;\n  protected loadWhenLeft = 20;\n\n  public onJump: (item: T, older: boolean) => void;\n  public onLoadedMore: () => void;\n\n  protected loadedAllUp = false;\n  protected loadedAllDown = false;\n  protected loadPromiseUp: Promise<void>;\n  protected loadPromiseDown: Promise<void>;\n\n  constructor(options: ListLoaderOptions<T, P>) {\n    safeAssign(this, options);\n  }\n\n  public setTargets(previous: T[], next: T[], reverse: boolean) {\n    this.previous = previous;\n    this.next = next;\n    this.reverse = reverse;\n  }\n\n  public get index() {\n    return this.count !== undefined ? this.previous.length : -1;\n  }\n\n  /* public filter(callback: (item: T, idx: number, arr: T[]) => boolean) {\n    const filter = (item: T, idx: number, arr: T[]) => {\n      if(!callback(item, idx, arr)) {\n        arr.splice(idx, 1);\n      }\n    };\n\n    forEachReverse(this.previous, filter);\n    forEachReverse(this.next, filter);\n  } */\n\n  public reset(loadedAll = false) {\n    this.current = undefined;\n    this.previous = [];\n    this.next = [];\n    this.setLoaded(true, loadedAll);\n    this.setLoaded(false, loadedAll);\n  }\n\n  public go(length: number, dispatchJump = true) {\n    let items: T[], item: T;\n    if(length > 0) {\n      items = this.next.splice(0, length);\n      item = items.pop();\n      if(!item) {\n        return;\n      }\n\n      if(this.current !== undefined) items.unshift(this.current);\n      this.previous.push(...items);\n    } else {\n      items = this.previous.splice(Math.max(0, this.previous.length + length), -length);\n      item = items.shift();\n      if(!item) {\n        return;\n      }\n\n      if(this.current !== undefined) items.push(this.current);\n      this.next.unshift(...items);\n    }\n\n    this.current = item;\n\n    if(this.next.length < this.loadWhenLeft) {\n      this.load(!this.reverse);\n    }\n\n    if(this.previous.length < this.loadWhenLeft) {\n      this.load(this.reverse);\n    }\n\n    dispatchJump && this.onJump?.(item, length > 0);\n    return this.current;\n  }\n\n  protected unsetCurrent(toPrevious: boolean) {\n    if(toPrevious) this.previous.push(this.current);\n    else this.next.unshift(this.current);\n\n    this.current = undefined;\n  }\n\n  public goUnsafe(length: number, dispatchJump?: boolean) {\n    const leftLength = length > 0 ? Math.max(0, length - this.next.length) : Math.min(0, length + this.previous.length);\n    const item = this.go(length, leftLength ? false : dispatchJump);\n\n    /* if(length > 0 ? this.loadedAllUp : this.loadedAllDown) {\n      this.unsetCurrent(length > 0);\n    } */\n\n    return {\n      item: !leftLength ? item : undefined,\n      leftLength\n    };\n  }\n\n  protected setLoaded(down: boolean, value: boolean) {\n    const isChanged = (down ? this.loadedAllDown : this.loadedAllUp) !== value;\n    if(!isChanged) {\n      return false;\n    }\n\n    if(down) this.loadedAllDown = value;\n    else this.loadedAllUp = value;\n\n    if(!value) {\n      if(down) this.loadPromiseDown = null;\n      else this.loadPromiseUp = null;\n    }\n\n    return true;\n  }\n\n  // нет смысла делать проверку для reverse и loadMediaPromise\n  public load(older: boolean) {\n    if(older ? this.loadedAllDown : this.loadedAllUp) return Promise.resolve();\n\n    let promise = older ? this.loadPromiseDown : this.loadPromiseUp;\n    if(promise) return promise;\n\n    let anchor: T;\n    if(older) {\n      anchor = this.reverse ? this.previous[0] : this.next[this.next.length - 1];\n    } else {\n      anchor = this.reverse ? this.next[this.next.length - 1] : this.previous[0];\n    }\n\n    anchor ??= this.current;\n    promise = this.loadMore(anchor, older, this.loadCount).then(async(result) => {\n      if((older ? this.loadPromiseDown : this.loadPromiseUp) !== promise) {\n        return;\n      }\n\n      if(result.items.length < this.loadCount) {\n        this.setLoaded(older, true);\n      }\n\n      if(this.count === undefined) {\n        this.count = result.count || result.items.length;\n      }\n\n      const processedArr: (Promise<any> | any)[] = [];\n      const method = older && !this.reverse ? result.items.forEach.bind(result.items) : forEachReverse.bind(null, result.items);\n      method((item: any) => {\n        // * the loader can return holes (a mid without a message behind it), don't feed them to processItem\n        if(!item) return;\n\n        const processed = this.processItem ? this.processItem(item) : item;\n\n        if(!processed) return;\n        processedArr.push(processed);\n      });\n\n      const results = (await Promise.all(processedArr)).filter(Boolean);\n      if((older ? this.loadPromiseDown : this.loadPromiseUp) !== promise) {\n        return;\n      }\n\n      if(older) {\n        if(this.reverse) this.previous.unshift(...results);\n        else this.next.push(...results);\n      } else {\n        if(this.reverse) this.next.push(...results);\n        else this.previous.unshift(...results);\n      }\n\n      this.onLoadedMore?.();\n    }, () => {}).then(() => {\n      if(older) this.loadPromiseDown = null;\n      else this.loadPromiseUp = null;\n    });\n\n    if(older) this.loadPromiseDown = promise;\n    else this.loadPromiseUp = promise;\n\n    return promise;\n  }\n}\n","import type {MediaSearchContext} from '@components/appMediaPlaybackController';\nimport type {SearchSuperContext} from '@components/appSearchSuper';\nimport type {Message} from '@layer';\nimport type {MessagesStorageKey, MyMessage} from '@appManagers/appMessagesManager';\nimport {AppManagers} from '@lib/managers';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport filterChatPhotosMessages from '@helpers/filterChatPhotosMessages';\nimport ListLoader, {ListLoaderOptions} from '@helpers/listLoader';\n\nexport default class SearchListLoader<Item extends {mid: number, peerId: PeerId}> extends ListLoader<Item, Message.message> {\n  public searchContext: MediaSearchContext;\n  public onEmptied: () => void;\n\n  private otherSideLoader: SearchListLoader<Item>;\n  private managers: AppManagers;\n\n  constructor(options: Omit<ListLoaderOptions<Item, Message.message>, 'loadMore'> & {\n    onEmptied?: () => void,\n    isInner?: boolean,\n    managers?: AppManagers\n  } = {}) {\n    super({\n      ...options,\n      loadMore: async(anchor, older, loadCount) => {\n        const backLimit = older ? 0 : loadCount;\n        let offsetId = anchor?.mid ?? this.searchContext.maxId;\n\n        if(!older) offsetId = await this.managers.appMessagesIdsManager.incrementMessageId(offsetId, 1);\n\n        const peerId = this.searchContext.peerId || anchor?.peerId;\n\n        return this.managers.appMessagesManager.getHistory({\n          ...this.searchContext,\n          peerId,\n          offsetId,\n          offsetPeerId: !peerId ? anchor?.peerId : undefined,\n          limit: backLimit ? 0 : loadCount,\n          backLimit\n        }).then((value) => {\n          /* if(DEBUG) {\n            this.log('loaded more media by maxId:', maxId, value, older, this.reverse);\n          } */\n\n          // * a cached (non-global) search returns only mids, resolve them before filtering\n          if(!value.messages) {\n            value.messages = value.history.map((mid) => apiManagerProxy.getMessageByPeer(peerId, mid));\n          }\n\n          if(this.searchContext.inputFilter._ === 'inputMessagesFilterChatPhotos') {\n            filterChatPhotosMessages(value);\n          }\n\n          if(value.nextRate) {\n            this.searchContext.nextRate = value.nextRate;\n          }\n\n          return {count: value.count, items: value.messages};\n        });\n      },\n      processItem: async(message) => {\n        const filtered = await this.filterMids([message.mid]);\n        if(!filtered.length) {\n          return;\n        }\n\n        return options.processItem(message);\n      }\n    });\n\n    this.managers ??= rootScope.managers;\n    rootScope.addEventListener('history_delete', this.onHistoryDelete);\n    rootScope.addEventListener('history_multiappend', this.onHistoryMultiappend);\n    rootScope.addEventListener('message_sent', this.onMessageSent);\n\n    if(!options.isInner) {\n      this.otherSideLoader = new SearchListLoader({\n        ...options,\n        isInner: true\n      });\n\n      // this.otherSideLoader.onLoadedMore = () => {\n\n      // };\n    }\n  }\n\n  protected async filterMids(mids: number[]) {\n    const storageKey: MessagesStorageKey = `${this.searchContext.peerId}_${this.searchContext.isScheduled ? 'scheduled' : 'history'}`;\n    let filtered = (await this.managers.appMessagesManager.filterMessagesByInputFilterFromStorage(this.searchContext.inputFilter._, mids, storageKey, mids.length)) as Message.message[];\n    if(this.searchContext.skipSensitive) {\n      filtered = filtered.filter((message) => !isMessageSensitive(message));\n    }\n    return filtered;\n  }\n\n  protected onHistoryDelete = ({peerId, msgs}: BroadcastEvents['history_delete']) => {\n    const shouldBeDeleted = (item: Item) => item.peerId === peerId && msgs.has(item.mid);\n    const filter = (item: Item, idx: number, arr: Item[]) => {\n      if(shouldBeDeleted(item)) {\n        arr.splice(idx, 1);\n      }\n    };\n\n    forEachReverse(this.previous, filter);\n    forEachReverse(this.next, filter);\n\n    if(this.current && shouldBeDeleted(this.current)) {\n      this.current = undefined;\n      /* if(this.go(1)) {\n        this.previous.splice(this.previous.length - 1, 1);\n      } else if(this.go(-1)) {\n        this.next.splice(0, 1);\n      } else  */if(this.onEmptied) {\n        this.onEmptied();\n      }\n    }\n  };\n\n  protected onHistoryMultiappend = async(message: Message.message | Message.messageService) => {\n    const {searchContext} = this;\n    if(searchContext.folderId !== undefined) {\n      return;\n    }\n\n    // because it's reversed\n    if(!this.loadedAllUp || this.loadPromiseUp) {\n      return;\n    }\n\n    if(message.peerId !== searchContext.peerId) {\n      return;\n    }\n\n    const filtered = await this.filterMids([message.mid]);\n    if(this.searchContext !== searchContext) return;\n    const targets = (await Promise.all(filtered.map((message) => this.processItem(message)))).filter(Boolean);\n    if(this.searchContext !== searchContext) return;\n    if(!targets.length) {\n      return;\n    }\n\n    // * it can be already added because of `message_sent`\n    const allTargets = this.previous.concat(this.next, this.current ? [this.current] : []);\n    if(allTargets.some((item) => item?.mid === message.mid)) {\n      return;\n    }\n\n    if(!this.current) {\n      this.previous.push(...targets);\n    } else {\n      this.next.push(...targets);\n    }\n  };\n\n  protected onMessageSent = ({message}: {message: MyMessage}) => {\n    this.onHistoryMultiappend(message);\n  };\n\n  public setSearchContext(context: SearchSuperContext) {\n    this.searchContext = context;\n\n    if(this.searchContext.folderId !== undefined) {\n      this.loadedAllUp = true;\n\n      if(this.searchContext.nextRate === undefined) {\n        this.loadedAllDown = true;\n      }\n    }\n\n    if(this.searchContext.inputFilter._ === 'inputMessagesFilterChatPhotos') {\n      this.loadedAllUp = true;\n    }\n\n    if(this.searchContext.useSearch === false) {\n      this.loadedAllDown = this.loadedAllUp = true;\n    }\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.setSearchContext(context);\n    }\n  }\n\n  public reset() {\n    super.reset();\n    this.searchContext = undefined;\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.reset();\n    }\n  }\n\n  public getPrevious(withOtherSide?: boolean) {\n    let previous = this.previous;\n\n    if(this.otherSideLoader && withOtherSide) {\n      previous = previous.concat(this.otherSideLoader.previous);\n    }\n\n    return previous;\n  }\n\n  public getNext(withOtherSide?: boolean) {\n    let next = this.next;\n\n    if(this.otherSideLoader && withOtherSide) {\n      next = next.concat(this.otherSideLoader.next);\n    }\n\n    return next;\n  }\n\n  public getCurrent() {\n    return this.current || this.otherSideLoader?.current;\n  }\n\n  private goToOtherEnd(length: number) {\n    if(length > 0) return this.go(-this.previous.length);\n    else return this.go(this.next.length);\n  }\n\n  public goRound(length: number, dispatchJump?: boolean) {\n    let ret: ReturnType<SearchListLoader<Item>['goUnsafe']>;\n\n    if(this.otherSideLoader?.current) {\n      ret = this.otherSideLoader.goUnsafe(length, dispatchJump);\n      if(ret.item) {\n        return ret.item;\n      }\n\n      length = ret.leftLength;\n      if(!(length > 0 ? this.otherSideLoader.next : this.otherSideLoader.previous).length) {\n        const loaded = length > 0 ? this.otherSideLoader.loadedAllUp : this.otherSideLoader.loadedAllDown;\n        if(!loaded) { // do not reset anything until it's loaded\n          return;\n        }\n\n        // if other side is loaded too will start from its begin\n        if((length > 0 && (this.otherSideLoader.searchContext.maxId === 1 || this.otherSideLoader.loadedAllDown)) ||\n          (length < 0 && (this.otherSideLoader.searchContext.maxId === 0 || this.otherSideLoader.loadedAllUp))) {\n          return this.otherSideLoader.goToOtherEnd(length);\n        }\n\n        this.otherSideLoader.unsetCurrent(length > 0);\n      }\n    }\n\n    ret = this.goUnsafe(length, dispatchJump);\n    if(!ret.item) {\n      if(this.loadedAllUp && this.loadedAllDown) { // just use the same loader if the list is too short\n        return this.goToOtherEnd(length);\n      } else if(this.otherSideLoader) {\n        length = ret.leftLength;\n        ret = this.otherSideLoader.goUnsafe(length, dispatchJump);\n\n        if(ret.item) {\n          this.unsetCurrent(length > 0);\n        }\n      }\n    }\n\n    return ret?.item;\n  }\n\n  // public setTargets(previous: Item[], next: Item[], reverse: boolean) {\n  //   super.setTargets(previous, next, reverse);\n  // }\n\n  public setCurrent(item: Item) {\n    this.current = item;\n  }\n\n  protected setLoaded(down: boolean, value: boolean) {\n    const changed = super.setLoaded(down, value);\n\n    if(changed &&\n      this.otherSideLoader &&\n      value &&\n      this.searchContext?.useSearch !== false/*  &&\n      (this.reverse ? this.loadedAllUp : this.loadedAllDown) */) {\n      const reverse = this.loadedAllUp;\n      this.otherSideLoader.setSearchContext({\n        ...this.searchContext,\n        maxId: reverse ? 1 : 0\n      });\n\n      // these 'reverse' are different, not a mistake here.\n      this.otherSideLoader.reverse = this.reverse;\n      this.otherSideLoader.setLoaded(reverse, true);\n      this.otherSideLoader.load(!reverse);\n    }\n\n    return changed;\n  }\n\n  public cleanup() {\n    this.reset();\n    rootScope.removeEventListener('history_delete', this.onHistoryDelete);\n    rootScope.removeEventListener('history_multiappend', this.onHistoryMultiappend);\n    rootScope.removeEventListener('message_sent', this.onMessageSent);\n    this.onEmptied = undefined;\n\n    if(this.otherSideLoader) {\n      this.otherSideLoader.cleanup();\n      this.otherSideLoader = undefined;\n    }\n  }\n}\n","import {createEffect, createSignal, JSX, on, Signal, untrack} from 'solid-js';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport CheckboxField, {CheckboxFieldOptions} from '@components/checkboxField';\nimport {attachClassName} from '@helpers/solid/classname';\n\n/** The control only — put the label in a `Row.Title` next to `Row.CheckboxField` */\nexport default function CheckboxFieldTsx(props: Omit<CheckboxFieldOptions, 'toggleLockIcon'> & {\n  class?: string,\n  signal?: Signal<boolean>,\n  /** Shows a lock inside the toggle's circle. Requires `toggle` */\n  lockIcon?: Icon,\n  onChange?: (checked: boolean) => void,\n  ref?: (checkboxField: CheckboxField) => void\n}): JSX.Element {\n  const [checked, setChecked] = props.signal ?? createSignal(props.checked ?? false);\n\n  const checkboxField = new CheckboxField({\n    toggle: props.toggle,\n    toggleLockIcon: props.lockIcon,\n    round: props.round,\n    color: props.color,\n    name: props.name,\n    stateValues: props.stateValues,\n    stateValueReverse: props.stateValueReverse,\n    restriction: props.restriction,\n    listenerSetter: props.listenerSetter,\n    asRadio: props.asRadio,\n    stateKey: props.stateKey,\n    ...(props.signal || props.checked !== undefined ? {checked: checked()} : {})\n  });\n  props.ref?.(checkboxField);\n\n  createEffect(on(checked, () => {\n    checkboxField.setValueSilently(checked());\n  }, {defer: true}));\n\n  createEffect(on(() => props.lockIcon, (icon) => {\n    checkboxField.setToggleLockIcon(icon);\n  }, {defer: true}));\n\n  createEffect(on(() => props.checked, (value) => {\n    if(value === undefined) {\n      return;\n    }\n\n    setChecked(value);\n  }));\n\n  createEffect(() => {\n    checkboxField.toggleDisability(!!props.disabled);\n  });\n\n  subscribeOn(checkboxField.input)('change', () => {\n    setChecked(checkboxField.input.checked);\n    untrack(() => props.onChange?.(checked()));\n  });\n\n  attachClassName(checkboxField.label, () => props.class);\n\n  return checkboxField.label;\n}\n","import {createContext, onCleanup, JSX, createEffect, children, untrack, createRenderEffect} from 'solid-js';\nimport {createStore} from 'solid-js/store';\n\nexport type ComponentContextValue<Kind extends string> = {\n  register: (kind: Kind, element: JSX.Element) => JSX.Element,\n  store: {[key in Kind]?: JSX.Element}\n};\n\nexport default function createComponentContext<\n  ContextValue extends ComponentContextValue<Kind>,\n  Kind extends string\n>() {\n  const context = createContext<ContextValue>();\n\n  return {\n    context,\n    createValue: () => {\n      const [store, setStore] = createStore<ContextValue['store']>({});\n      const register: ContextValue['register'] = (kind, element) => {\n        const resolved = children(() => element);\n        createRenderEffect(() => {\n          setStore(kind as any, resolved() as any);\n          // console.log('resolved', kind, resolved(), untrack(() => children(() => store[kind]))());\n        });\n        // setStore(kind as any, element as any);\n        onCleanup(() => setStore(kind as any, undefined));\n        return undefined;\n        // return element;\n      };\n\n      const value: ComponentContextValue<Kind> = {\n        register,\n        store\n      };\n\n      return value;\n    }\n  };\n}\n","type K = boolean;\nexport default async function filterAsync<T>(arr: T[], callback: (item: T, idx: number, arr: T[]) => Promise<K> | K) {\n  const promises = arr.map(async(item, idx, arr) => {\n    if(await callback(item, idx, arr)) {\n      return item;\n    }\n  });\n\n  return (await Promise.all(promises)).filter(Boolean);\n}\n","import type {ButtonMenuDirection} from '@components/buttonMenuToggle';\nimport mediaSizes from '@helpers/mediaSizes';\nimport I18n from '@lib/langPack';\nimport clamp from './number/clamp';\nimport {getAppWindow} from '@helpers/appWindow';\n\nexport type MenuPositionPadding = {\n  top?: number,\n  right?: number,\n  bottom?: number,\n  left?: number\n};\n\nconst PADDING_TOP = 8;\nconst PADDING_BOTTOM = PADDING_TOP;\nconst PADDING_LEFT = 8;\nconst PADDING_RIGHT = PADDING_LEFT;\n\nexport const DEFAULT_MENU_WINDOW_MARGIN = 16;\n\nexport type MenuHorizontalDirection = 'left' | 'right';\n\nexport type FloatingMenuSide = 'top' | 'left' | 'right' | 'bottom';\nexport type FloatingMenuAlignment = 'start' | 'center' | 'end';\nexport type FloatingMenuDirection = `${FloatingMenuSide}-${FloatingMenuAlignment}`;\n\nconst OPPOSITE_SIDE: Record<FloatingMenuSide, FloatingMenuSide> = {\n  top: 'bottom',\n  bottom: 'top',\n  left: 'right',\n  right: 'left'\n};\n\nfunction canFitSide(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  side: FloatingMenuSide,\n  mainOffset: number\n) {\n  const margin = DEFAULT_MENU_WINDOW_MARGIN;\n  switch(side) {\n    case 'right':\n      return triggerBcr.right + mainOffset + menu.clientWidth + margin <= getAppWindow().innerWidth;\n    case 'left':\n      return triggerBcr.left - mainOffset - menu.clientWidth - margin >= 0;\n    case 'bottom':\n      return triggerBcr.bottom + mainOffset + menu.clientHeight + margin <= getAppWindow().innerHeight;\n    case 'top':\n      return triggerBcr.top - mainOffset - menu.clientHeight - margin >= 0;\n  }\n}\n\n/**\n * Positions a floating menu next to a trigger element.\n * - `side` is the side of the trigger the menu opens on.\n * - `alignment` aligns the menu along the perpendicular axis.\n * - `offset` is `[x, y]`. The component along the main axis acts as a gap from the trigger,\n *   the perpendicular component nudges along the alignment axis.\n *\n * Sets `left`, `top`, and `transformOrigin` on `menu`. Returns the actually used direction\n * (the side may flip to the opposite if the menu doesn't fit).\n */\nexport function positionFloatingMenu(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: FloatingMenuDirection,\n  offset: [number, number] = [0, 0]\n): FloatingMenuDirection {\n  const [requestedSide, alignment] = direction.split('-') as [FloatingMenuSide, FloatingMenuAlignment];\n\n  const isHorizontalSide = requestedSide === 'left' || requestedSide === 'right';\n  const mainOffset = isHorizontalSide ? offset[0] : offset[1];\n  const crossOffset = isHorizontalSide ? offset[1] : offset[0];\n\n  // Flip side if it doesn't fit and the opposite does (mirrors the original right/left logic).\n  const opposite = OPPOSITE_SIDE[requestedSide];\n  const side: FloatingMenuSide = canFitSide(triggerBcr, menu, requestedSide, mainOffset) ||\n      !canFitSide(triggerBcr, menu, opposite, mainOffset) ?\n    requestedSide :\n    opposite;\n\n  const margin = DEFAULT_MENU_WINDOW_MARGIN;\n  const menuW = menu.clientWidth;\n  const menuH = menu.clientHeight;\n\n  // Main-axis position.\n  let left: number;\n  let top: number;\n\n  if(side === 'right' || side === 'left') {\n    if(side === 'right') {\n      left = triggerBcr.right + mainOffset;\n    } else {\n      left = triggerBcr.left - mainOffset - menuW;\n    }\n    left = clamp(left, margin, getAppWindow().innerWidth - menuW - margin);\n\n    // Cross axis: vertical.\n    if(alignment === 'start') {\n      top = triggerBcr.top + crossOffset;\n    } else if(alignment === 'center') {\n      top = triggerBcr.top + triggerBcr.height / 2 - menuH / 2 + crossOffset;\n    } else {\n      top = triggerBcr.bottom - menuH - crossOffset;\n    }\n    top = clamp(top, margin, getAppWindow().innerHeight - menuH - margin);\n  } else {\n    if(side === 'bottom') {\n      top = triggerBcr.bottom + mainOffset;\n    } else {\n      top = triggerBcr.top - mainOffset - menuH;\n    }\n    top = clamp(top, margin, getAppWindow().innerHeight - menuH - margin);\n\n    // Cross axis: horizontal.\n    if(alignment === 'start') {\n      left = triggerBcr.left + crossOffset;\n    } else if(alignment === 'center') {\n      left = triggerBcr.left + triggerBcr.width / 2 - menuW / 2 + crossOffset;\n    } else {\n      left = triggerBcr.right - menuW - crossOffset;\n    }\n    left = clamp(left, margin, getAppWindow().innerWidth - menuW - margin);\n  }\n\n  // Transform origin: corner/edge closest to the trigger.\n  let originX: string;\n  let originY: string;\n  const alignmentToPercent = alignment === 'start' ? '0' : alignment === 'center' ? '50%' : '100%';\n\n  if(side === 'right' || side === 'left') {\n    originX = side === 'right' ? '0' : '100%';\n    originY = alignmentToPercent;\n  } else {\n    originY = side === 'bottom' ? '0' : '100%';\n    originX = alignmentToPercent;\n  }\n\n  menu.style.left = left + 'px';\n  menu.style.top = top + 'px';\n  menu.style.transformOrigin = `${originX} ${originY}`;\n\n  return `${side}-${alignment}` as FloatingMenuDirection;\n}\n\nexport function getMenuTopPositionForStartDirection(triggerBcr: DOMRect, menu: HTMLElement, offset: [number, number]) {\n  let top = triggerBcr.top + offset[1];\n  const bottom = top + menu.clientHeight;\n  if(bottom + DEFAULT_MENU_WINDOW_MARGIN > getAppWindow().innerHeight) top -= bottom - getAppWindow().innerHeight + DEFAULT_MENU_WINDOW_MARGIN;\n  top = Math.max(top, DEFAULT_MENU_WINDOW_MARGIN);\n\n  return top;\n}\n\nexport function canMenuFitDirection(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: MenuHorizontalDirection,\n  offset: [number, number]\n) {\n  if(direction === 'right') {\n    const left = triggerBcr.right + offset[0];\n    return left + menu.clientWidth + DEFAULT_MENU_WINDOW_MARGIN <= getAppWindow().innerWidth;\n  }\n\n  const right = triggerBcr.left - offset[0];\n  return right - menu.clientWidth - DEFAULT_MENU_WINDOW_MARGIN >= 0;\n}\n\nexport function getMenuLeftPositionForDirection(\n  triggerBcr: DOMRect,\n  menu: HTMLElement,\n  direction: MenuHorizontalDirection,\n  offset: [number, number]\n) {\n  if(direction === 'right') {\n    let left = triggerBcr.right + offset[0];\n    const right = left + menu.clientWidth;\n    if(right + DEFAULT_MENU_WINDOW_MARGIN > getAppWindow().innerWidth) left -= right - getAppWindow().innerWidth + DEFAULT_MENU_WINDOW_MARGIN;\n    return left;\n  }\n\n  const right = triggerBcr.left - offset[0];\n  let left = right - menu.clientWidth;\n  if(left - DEFAULT_MENU_WINDOW_MARGIN < 0) left = DEFAULT_MENU_WINDOW_MARGIN;\n  return left;\n}\n\nexport default function positionMenu(e: MouseEvent | Touch | TouchEvent, elem: HTMLElement, side?: 'left' | 'right' | 'center', additionalPadding?: MenuPositionPadding) {\n  if((e as TouchEvent).touches) {\n    e = (e as TouchEvent).touches[0];\n  }\n\n  const {pageX, pageY} = e as Touch;\n  // let {clientX, clientY} = e;\n\n  // * side mean the OPEN side\n\n  const getScrollWidthFromElement = (Array.from(elem.children) as HTMLElement[]).find((element) => element.classList.contains('btn-menu-items') || (element.classList.contains('btn-menu-item') && !element.classList.contains('hide'))) || elem;\n\n  let {scrollWidth: menuWidth} = getScrollWidthFromElement;\n  const {scrollHeight: menuHeight} = elem;\n  // let {innerWidth: windowWidth, innerHeight: windowHeight} = window;\n  const rect = getAppWindow().document.body.getBoundingClientRect();\n  const windowWidth = rect.width;\n  const windowHeight = rect.height;\n\n  menuWidth += getScrollWidthFromElement.offsetLeft * 2;\n\n  let paddingTop = PADDING_TOP, paddingRight = PADDING_RIGHT, paddingBottom = PADDING_BOTTOM, paddingLeft = PADDING_LEFT;\n  if(additionalPadding) {\n    if(additionalPadding.top) paddingTop += additionalPadding.top;\n    if(additionalPadding.right) paddingRight += additionalPadding.right;\n    if(additionalPadding.bottom) paddingBottom += additionalPadding.bottom;\n    if(additionalPadding.left) paddingLeft += additionalPadding.left;\n  }\n\n  if(I18n.getIsRTL()) side = mediaSizes.isMobile ? 'left' : 'right';\n  else side = mediaSizes.isMobile ? 'right' : 'left';\n  let verticalSide: 'top' /* | 'bottom' */ | 'center' = 'top';\n\n  const maxTop = windowHeight - menuHeight - paddingBottom;\n  const maxLeft = windowWidth - menuWidth - paddingRight;\n  const minTop = paddingTop;\n  const minLeft = paddingLeft;\n\n  const getSides = () => {\n    return {\n      x: {\n        left: pageX,\n        right: Math.min(maxLeft, pageX - menuWidth)\n      },\n      intermediateX: side === 'right' ? minLeft : maxLeft,\n      // intermediateX: clientX < windowWidth / 2 ? PADDING_LEFT : windowWidth - menuWidth - PADDING_LEFT,\n      y: {\n        top: pageY,\n        bottom: pageY - menuHeight\n      },\n      // intermediateY: verticalSide === 'top' ? paddingTop : windowHeight - menuHeight - paddingTop,\n      // intermediateY: pageY < (windowHeight / 2) ? paddingTop : windowHeight - menuHeight - paddingBottom,\n      intermediateY: maxTop\n    };\n  };\n\n  const sides = getSides();\n\n  const possibleSides = {\n    x: {\n      left: (sides.x.left + menuWidth + paddingRight) <= windowWidth,\n      right: sides.x.right >= paddingLeft\n    },\n    y: {\n      top: (sides.y.top + menuHeight + paddingBottom) <= windowHeight,\n      bottom: (sides.y.bottom - paddingBottom) >= paddingBottom\n    }\n  };\n\n  /* if(side === undefined) {\n    if((clientX + menuWidth + PADDING_LEFT) > windowWidth) {\n      side = 'right';\n    }\n  } */\n\n  {\n    /* const x = sides.x;\n\n    const s = Object.keys(x) as (keyof typeof possibleSides.x)[];\n    if(side) {\n      s.findAndSplice((s) => s === side);\n      s.unshift(side);\n    }\n\n    const possibleSide = s.find((s) => possibleSides.x[s]); */\n    // let left: number;\n    /* if(possibleSide) {\n      left = x[possibleSide];\n      side = possibleSide;\n    } else {\n      left = sides.intermediateX;\n      side = undefined;\n    } */\n    const left = possibleSides.x[side] ? sides.x[side] : (side = 'center', sides.intermediateX);\n\n    elem.style.left = left + 'px';\n  }\n\n  /* if((clientY + menuHeight + PADDING_TOP) > windowHeight) {\n    elem.style.top = clamp(clientY - menuHeight, PADDING_TOP, windowHeight - menuHeight - PADDING_TOP) + 'px';\n    // elem.style.top = (innerHeight - scrollHeight - PADDING_TOP) + 'px';\n    verticalSide = 'bottom';\n  } else {\n    elem.style.top = Math.max(PADDING_TOP, clientY) + 'px';\n    verticalSide = 'top';\n  } */\n\n  {\n    const top = possibleSides.y[verticalSide] ? sides.y[verticalSide] : (verticalSide = 'center', sides.intermediateY);\n\n    elem.style.top = top + 'px';\n  }\n\n  elem.className = elem.className.replace(/(top|center|bottom)-(left|center|right)/g, '');\n  elem.classList.add(\n    // (verticalSide === 'center' ? verticalSide : (verticalSide === 'bottom' ? 'top' : 'bottom')) +\n    (verticalSide === 'center' ? verticalSide : 'bottom') +\n    '-' +\n    (side === 'center' ? side : ((I18n.getIsRTL() ? side === 'right' : side === 'left') ? 'right' : 'left')));\n\n  return {\n    width: menuWidth,\n    height: menuHeight\n  };\n}\n\nexport function positionMenuTrigger(trigger: HTMLElement, menu: HTMLElement, direction: ButtonMenuDirection, additionalPadding?: MenuPositionPadding) {\n  const triggerRect = trigger.getBoundingClientRect();\n\n  const [directionX, directionY] = direction.split('-');\n\n  if(directionX === 'bottom') {\n    const top = triggerRect.top + triggerRect.height + (additionalPadding?.top ?? 0);\n    menu.style.top = `${Math.max(top, additionalPadding?.top ?? 0)}px`\n  } else {\n    const bottom = getAppWindow().innerHeight - triggerRect.top + (additionalPadding?.bottom ?? 0)\n    menu.style.bottom = `${Math.max(bottom, additionalPadding?.bottom ?? 0)}px`\n  }\n\n  if(directionY === 'right' || directionY === 'center') {\n    const left = triggerRect.left + (additionalPadding?.left ?? 0);\n    menu.style.left = `${Math.max(left, additionalPadding?.left ?? 0)}px`\n  } else {\n    const right = getAppWindow().innerWidth - triggerRect.left - triggerRect.width - (additionalPadding?.right ?? 0)\n    menu.style.right = `${Math.max(right, additionalPadding?.right ?? 0)}px`\n  }\n\n  if(directionY === 'center') {\n    menu.style.setProperty('--parent-half-width', (trigger.clientWidth / 2) + 'px');\n  }\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {IS_APPLE} from '@environment/userAgent';\nimport contextMenuController from '@helpers/contextMenuController';\nimport ListenerSetter, {ListenerOptions} from '@helpers/listenerSetter';\nimport cancelEvent from '@helpers/dom/cancelEvent';\n\nlet _cancelContextMenuOpening = false, _cancelContextMenuOpeningTimeout = 0;\nexport function cancelContextMenuOpening() {\n  if(_cancelContextMenuOpeningTimeout) {\n    clearTimeout(_cancelContextMenuOpeningTimeout);\n  }\n\n  _cancelContextMenuOpeningTimeout = window.setTimeout(() => {\n    _cancelContextMenuOpeningTimeout = 0;\n    _cancelContextMenuOpening = false;\n  }, .4e3);\n\n  _cancelContextMenuOpening = true;\n}\n\nexport function attachContextMenuListener({\n  element,\n  callback,\n  listenerSetter,\n  listenerOptions\n}: {\n  element: HTMLElement,\n  callback: (e: TouchEvent | MouseEvent) => void,\n  listenerSetter?: ListenerSetter,\n  listenerOptions?: ListenerOptions\n}) {\n  const add = listenerSetter ? listenerSetter.add(element) : element.addEventListener.bind(element);\n  const remove = listenerSetter ? listenerSetter.removeManual.bind(listenerSetter, element) : element.removeEventListener.bind(element);\n\n  // can't cancel further events coming after 'contextmenu' event\n  if((IS_APPLE && IS_TOUCH_SUPPORTED) || listenerOptions) {\n    let timeout: number;\n\n    const options: EventListenerOptions = {\n      ...(listenerOptions || {}),\n      capture: true\n    };\n\n    const onCancel = () => {\n      clearTimeout(timeout);\n      // @ts-ignore\n      remove('touchmove', onCancel, options);\n      // @ts-ignore\n      remove('touchend', onCancel, options);\n      // @ts-ignore\n      remove('touchcancel', onCancel, options);\n    };\n\n    add('touchstart', (e: TouchEvent) => {\n      if(e.touches.length > 1) {\n        onCancel();\n        return;\n      }\n\n      add('touchmove', onCancel, options);\n      add('touchend', onCancel, options);\n      add('touchcancel', onCancel, options);\n\n      timeout = window.setTimeout(() => {\n        if(_cancelContextMenuOpening) {\n          onCancel();\n          return;\n        }\n\n        callback(e);\n        onCancel();\n\n        if(contextMenuController.isOpened()) {\n          add('touchend', cancelEvent, {once: true}); // * fix instant closing\n        }\n      }, .4e3);\n    }, listenerOptions);\n\n    /* if(!isSafari) {\n      add('contextmenu', (e: any) => {\n        cancelEvent(e);\n      }, {passive: false, capture: true});\n    } */\n  } else {\n    add('contextmenu', IS_TOUCH_SUPPORTED ? (e: any) => {\n      callback(e);\n\n      if(contextMenuController.isOpened()) {\n        add('touchend', cancelEvent, {once: true}); // * fix instant closing\n      }\n    } : callback, listenerOptions);\n  }\n}\n","import ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '@helpers/array/filterAsync';\nimport callbackify from '@helpers/callbackify';\nimport contextMenuController from '@helpers/contextMenuController';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport positionMenu from '@helpers/positionMenu';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {logger} from '@lib/logger';\nimport {getOverlayRoot} from '@helpers/appWindow';\n\nconst log = logger('createContextMenu');\n\ntype ContextMenuEvent = MouseEvent | TouchEvent;\ntype ContextMenuInstance = {\n  element: HTMLElement,\n  cleanup: () => void,\n  destroy: () => void\n};\n\nexport default function createContextMenu<T extends ButtonMenuItemOptionsVerifiable>({\n  buttons,\n  findElement,\n  listenTo,\n  appendTo,\n  resolveAppendTo,\n  filterButtons,\n  onOpen,\n  onClose,\n  onCloseAfter,\n  onElementReady,\n  onOpenBefore,\n  onOpenAfter,\n  listenerSetter: attachListenerSetter,\n  middleware,\n  listenForClick,\n  position,\n  reopenOnTrigger,\n  cancelOnOpenFalse\n}: {\n  buttons: T[],\n  findElement?: (e: MouseEvent | TouchEvent) => HTMLElement,\n  listenTo: HTMLElement,\n  appendTo?: HTMLElement,\n  resolveAppendTo?: () => HTMLElement,\n  filterButtons?: (buttons: T[]) => Promise<T[]>,\n  onOpen?: (e: Event, target: HTMLElement) => any,\n  onClose?: () => any,\n  onCloseAfter?: () => any,\n  onOpenBefore?: () => any,\n  onOpenAfter?: (element: HTMLElement, target: HTMLElement) => any,\n  onElementReady?: (element: HTMLElement) => void,\n  listenerSetter?: ListenerSetter,\n  middleware?: Middleware,\n  listenForClick?: boolean,\n  position?: (e: ContextMenuEvent, element: HTMLElement, target: HTMLElement) => void,\n  reopenOnTrigger?: boolean,\n  cancelOnOpenFalse?: boolean\n}) {\n  attachListenerSetter ??= new ListenerSetter();\n  const instances = new Set<ContextMenuInstance>();\n  let element: HTMLElement;\n  let destroyed = false;\n  let openGeneration = 0;\n\n  const open = (e: ContextMenuEvent) => {\n    if(destroyed) return;\n    const target = findElement ? findElement(e as any) : listenTo;\n    if(!target) {\n      return;\n    }\n\n    let _element = element;\n    const generation = ++openGeneration;\n    // Duck-type instead of `instanceof MouseEvent`: the event from a Document PiP window is a\n    // pip-realm MouseEvent, which is NOT `instanceof` the main realm's MouseEvent (cross-realm\n    // instanceof is always false) — so the native context menu wasn't being suppressed in the pip.\n    if('preventDefault' in e) (e as any).preventDefault();\n    if(_element && _element.classList.contains('active')) {\n      if(!reopenOnTrigger) return false;\n      contextMenuController.close();\n      _element = undefined;\n    }\n    if('cancelBubble' in e) (e as any).cancelBubble = true;\n\n    const isCurrent = () => !destroyed && generation === openGeneration;\n    const r = async() => {\n      try {\n        const openResult = await onOpen?.(e, target);\n        if((cancelOnOpenFalse && openResult === false) || !isCurrent()) {\n          onClose?.();\n          return;\n        }\n      } catch(e) {\n        if(e instanceof Error) {\n          log.error('Error opening context menu:', e);\n        } else {\n          log('Opening context menu was blocked, reason:', e);\n        }\n        onClose?.();\n        return;\n      }\n\n      let initResult: Awaited<ReturnType<typeof init>>;\n      try {\n        initResult = await init(isCurrent);\n      } catch(e) {\n        log.error('Error creating context menu:', e);\n        onClose?.();\n        return;\n      }\n      if(!initResult || !isCurrent()) {\n        initResult?.destroy();\n        onClose?.();\n        return;\n      }\n\n      target.classList.add('menu-open');\n\n      _element = initResult.element;\n      element = _element;\n      const {cleanup, destroy} = initResult;\n\n      if(position) {\n        position(e, _element, target);\n      } else {\n        positionMenu(e, _element);\n      }\n\n      contextMenuController.openBtnMenu(_element, () => {\n        target.classList.remove('menu-open');\n        onClose?.();\n        cleanup();\n\n        setTimeout(() => {\n          onCloseAfter?.();\n          destroy();\n        }, 300);\n      }, target);\n      onOpenAfter?.(_element, target);\n    };\n\n    return r();\n  };\n\n  attachContextMenuListener({\n    element: listenTo,\n    callback: open,\n    listenerSetter: attachListenerSetter\n  });\n\n  const destroy = () => {\n    if(destroyed) return;\n    destroyed = true;\n    ++openGeneration;\n    if(element?.classList.contains('active')) {\n      contextMenuController.close();\n    }\n    attachListenerSetter.removeAll();\n    [...instances].forEach((instance) => instance.destroy());\n    element = undefined;\n  };\n\n  const close = () => {\n    if(destroyed) return;\n    ++openGeneration;\n    if(element?.classList.contains('active')) {\n      contextMenuController.close();\n    }\n  };\n\n  const init = async(isCurrent: () => boolean): Promise<ContextMenuInstance | undefined> => {\n    buttons.forEach((button) => button.element = undefined);\n    const f = filterButtons || ((buttons: T[]) => filterAsync(buttons, (button) => {\n      return button?.verify ? callbackify(button.verify(), (result) => result ?? false) : true;\n    }));\n\n    const filteredButtons = await f(buttons);\n    if(!isCurrent() || !filteredButtons.length) {\n      return;\n    }\n\n    const listenerSetter = new ListenerSetter();\n    const middlewareHelper = middleware ? middleware.create() : getMiddleware();\n    let _element: HTMLElement;\n    const disposeUnpublished = () => {\n      listenerSetter.removeAll();\n      middlewareHelper.destroy();\n      _element?.remove();\n    };\n\n    try {\n      _element = await ButtonMenu({\n        buttons: filteredButtons,\n        listenerSetter\n      });\n      if(!isCurrent()) {\n        disposeUnpublished();\n        return;\n      }\n      _element.classList.add('contextmenu');\n\n      await onOpenBefore?.();\n      if(!isCurrent()) {\n        disposeUnpublished();\n        return;\n      }\n      onElementReady?.(_element);\n\n      // Resolve lazily at open time so a context menu opened while the client is popped out lands in\n      // the Document PiP window's body (the active overlay realm), not the background tab.\n      (resolveAppendTo?.() ?? appendTo ?? getOverlayRoot()).append(_element);\n    } catch(err) {\n      disposeUnpublished();\n      throw err;\n    }\n\n    let cleaned = false;\n    let instanceDestroyed = false;\n    const cleanup = () => {\n      if(cleaned) return;\n      cleaned = true;\n      listenerSetter.removeAll();\n      middlewareHelper.clean();\n    };\n    const instance: ContextMenuInstance = {\n      element: _element,\n      cleanup,\n      destroy: () => {\n        if(instanceDestroyed) return;\n        instanceDestroyed = true;\n        listenerSetter.removeAll();\n        middlewareHelper.destroy();\n        _element.remove();\n        instances.delete(instance);\n        if(element === _element) element = undefined;\n      }\n    };\n    instances.add(instance);\n    return instance;\n  };\n\n  if(middleware) {\n    middleware.onDestroy(() => {\n      destroy();\n    });\n  }\n\n  if(listenForClick) {\n    attachClickEvent(listenTo, open, {listenerSetter: attachListenerSetter});\n  }\n\n  return {\n    get element() {\n      return element;\n    },\n    close,\n    destroy,\n    open\n  };\n}\n","import {\n  ColorRgb,\n  hexToRgb,\n  mixColorsPlusLighter,\n  rgbaToHexa\n} from '@helpers/color';\n\nconst OVERLAY_COLOR: ColorRgb = [255, 255, 255];\nconst OVERLAY_OPACITY = 0.14;\n\nexport const ROW_ICON_COLORS = {\n  blue: '#2196F3',\n  green: '#4CAF50',\n  grey: '#78909C',\n  orange: '#FB8C00',\n  pink: '#E91E63',\n  purple: '#7E57C2',\n  red: '#F44336'\n} as const;\n\ntype RowIconColorName = keyof typeof ROW_ICON_COLORS;\n\nexport const ROW_ICON_COLOR_BY_NAME: Partial<Record<Icon, RowIconColorName>> = {\n  account_filled: 'blue',\n  addmember_filled: 'orange',\n  admin_filled: 'green',\n  affiliate_filled: 'purple',\n  ai_filled: 'purple',\n  android_filled: 'green',\n  appearance_filled: 'orange',\n  apple_filled: 'blue',\n  auto_delete_filled: 'grey',\n  bell_filled: 'red',\n  bin_filled: 'red',\n  birthday_filled: 'purple',\n  bot_filled: 'green',\n  bubble_filled: 'pink',\n  business_filled: 'green',\n  channel_filled: 'orange',\n  checkboxblock: 'red',\n  checkboxon: 'blue',\n  commentssticker_filled: 'red',\n  darkmode_filled: 'purple',\n  data_filled: 'green',\n  data_transfer_filled: 'blue',\n  delete_filled: 'red',\n  devices_filled: 'blue',\n  email_filled: 'purple',\n  emoji_filled: 'orange',\n  eye1_filled: 'orange',\n  faceid_filled: 'green',\n  faq_filled: 'blue',\n  gift_filled: 'orange',\n  general_filled: 'grey',\n  gram_filled: 'blue',\n  group_circle_filled: 'blue',\n  group_filled: 'green',\n  info_filled: 'grey',\n  key_filled: 'grey',\n  keyboard_filled: 'orange',\n  lamp_filled: 'purple',\n  limit_file_filled: 'blue',\n  limit_folders_filled: 'blue',\n  link_filled: 'orange',\n  linux_filled: 'orange',\n  lock_filled: 'red',\n  location: 'red',\n  location_filled: 'green',\n  message_filled: 'green',\n  mention_filled: 'blue',\n  newchannel_filled: 'orange',\n  newprivate_filled: 'blue',\n  person_crossed_filled: 'grey',\n  person_filled: 'blue',\n  phone_filled: 'green',\n  photo_filled: 'orange',\n  pie_chart_filled: 'green',\n  plus_circle_filled: 'green',\n  policy_filled: 'green',\n  premium_avatars_filled: 'pink',\n  premium_filesize_filled: 'blue',\n  premium_lock_filled: 'grey',\n  reactions_filled: 'pink',\n  recent_actions_filled: 'green',\n  round_chats_filled: 'green',\n  saved_filled: 'blue',\n  sending: 'orange',\n  speaker_filled: 'green',\n  sputnik_filled: 'purple',\n  star_circle_filled: 'orange',\n  statistics_filled: 'purple',\n  sticker_filled: 'purple',\n  stories_filled: 'purple',\n  tag_alt_filled: 'blue',\n  time_filled: 'pink',\n  timer_filled: 'orange',\n  topics_filled: 'purple',\n  two_factor_auth_filled: 'green',\n  ubuntu_filled: 'red',\n  web_a_filled: 'purple',\n  web_filled: 'purple',\n  web_k_filled: 'purple',\n  win_key_filled: 'blue'\n};\n\nconst ROW_ICON_COLOR_VALUES = Object.values(ROW_ICON_COLORS);\n\nconst hashIconName = (icon: string) => {\n  let hash = 0x811c9dc5;\n\n  for(let i = 0; i < icon.length; ++i) {\n    hash ^= icon.charCodeAt(i);\n    hash = Math.imul(hash, 0x01000193);\n  }\n\n  return hash >>> 0;\n};\n\nconst formatOffset = (offset: number) => {\n  return `${+(offset * 100).toFixed(4)}%`;\n};\n\nexport function getRowIconBackgroundColor(icon: Icon) {\n  const registeredColor = ROW_ICON_COLOR_BY_NAME[icon];\n  return (registeredColor && ROW_ICON_COLORS[registeredColor]) ||\n    ROW_ICON_COLOR_VALUES[hashIconName(icon) % ROW_ICON_COLOR_VALUES.length];\n}\n\n/**\n * Reproduces the Figma Row icon backdrop without mix-blend-mode.\n *\n * Figma draws a white 100% -> 0% alpha gradient at 14% fill opacity over an\n * opaque base color using plus-lighter. The blend can clip individual RGB\n * channels before the gradient reaches its top edge, so those clipping points\n * are emitted as extra CSS stops instead of approximating the result with two\n * colors.\n */\nexport function getRowIconBackground(color: string) {\n  const backdrop = hexToRgb(color);\n  const offsets = new Set([0, 1]);\n\n  backdrop.forEach((value, index) => {\n    const maximumAddition = OVERLAY_COLOR[index] * OVERLAY_OPACITY;\n    if(!maximumAddition || value + maximumAddition <= 255) {\n      return;\n    }\n\n    offsets.add(1 - (255 - value) / maximumAddition);\n  });\n\n  const stops = [...offsets]\n  .sort((a, b) => a - b)\n  .map((offset) => {\n    const stopColor = mixColorsPlusLighter(\n      backdrop,\n      OVERLAY_COLOR,\n      OVERLAY_OPACITY * (1 - offset)\n    );\n\n    return `${rgbaToHexa(stopColor)} ${formatOffset(offset)}`;\n  });\n\n  return `linear-gradient(180deg, ${stops.join(', ')})`;\n}\n\nexport function getRowIconBackgroundImage(icon: Icon) {\n  if(icon === 'premium_badge') {\n    return 'var(--premium-gradient)';\n  }\n\n  return getRowIconBackground(getRowIconBackgroundColor(icon));\n}\n","/**\n * The classes a `Row` stamps on the fields it lays out itself.\n *\n * A row can also contain a checkbox that is none of its business — the selection checkbox a bubble\n * drops into a document/audio row, say — and that one must not pick up the row's layout. So the\n * styles in `scss/partials/_row.scss` key off these derived classes rather than off `.checkbox-field`\n * / `.radio-field` outright, and only the fields registered through `Row` carry them.\n */\nexport const ROW_CHECKBOX_FIELD_CLASS = 'row-checkbox-field';\nexport const ROW_CHECKBOX_FIELD_TOGGLE_CLASS = 'row-checkbox-field-toggle';\nexport const ROW_RADIO_FIELD_CLASS = 'row-radio-field';\nexport const RADIO_FIELD_RIGHT_CLASS = 'radio-field-right';\n","import {\n  children,\n  createRenderEffect,\n  JSX,\n  onCleanup,\n  Ref,\n  Show,\n  splitProps,\n  useContext\n} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {IconTsx} from '@components/iconTsx';\nimport RippleElement from '@components/rippleElement';\nimport createComponentContext, {ComponentContextValue} from '@helpers/solid/createComponentContext';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {hasMouseMovedSinceDown} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getRowIconBackgroundImage} from '@helpers/rowIconBackground';\nimport {attachHotClassName} from '@helpers/solid/classname';\nimport {\n  RADIO_FIELD_RIGHT_CLASS,\n  ROW_CHECKBOX_FIELD_CLASS,\n  ROW_CHECKBOX_FIELD_TOGGLE_CLASS,\n  ROW_RADIO_FIELD_CLASS\n} from '@components/rowFieldClasses';\n\nexport type RowMediaSizeType = 'small' | 'medium' | 'big' | 'abitbigger' | 'bigger' | '40';\n\nexport const createRowTitle = () => {\n  const title = document.createElement('div');\n  title.classList.add('row-title');\n  title.dir = 'auto';\n  return title;\n};\n\ntype Kind = 'title' | 'subtitle' | 'media' | 'midtitle' | 'icon' |\n  'rightContent' | 'checkboxField' | 'checkboxFieldToggle' | 'radioField' | 'radioFieldRight';\n\ntype RowContextValue = ComponentContextValue<Kind> & {\n  noWrap?: boolean,\n  /** A toggle sitting in its own right column instead of riding the title row. See `Row.CheckboxFieldToggle` */\n  toggleAside?: boolean\n};\n\nconst {\n  context: RowContext,\n  createValue: createRowValue\n} = createComponentContext<RowContextValue, Kind>();\n\nfunction registerExternalElement(\n  context: RowContextValue,\n  kind: Kind,\n  element: () => HTMLElement,\n  className: () => string\n) {\n  createRenderEffect(() => {\n    const currentElement = element();\n    const classes = className().split(' ').filter(Boolean);\n    if(!currentElement) {\n      return;\n    }\n\n    const addedClasses = classes.filter((className) => !currentElement.classList.contains(className));\n    currentElement.classList.add(...addedClasses);\n    onCleanup(() => currentElement.classList.remove(...addedClasses));\n  });\n\n  return context.register(kind, (\n    <Show keyed when={element()}>{(currentElement) => currentElement}</Show>\n  ));\n}\n\nconst Row = (props: {children: JSX.Element} & Partial<{\n  ref: Ref<HTMLElement>,\n  clickable: boolean | JSX.HTMLAttributes<HTMLElement>['onClick'],\n  role: JSX.HTMLAttributes<HTMLElement>['role'],\n  tabIndex: number,\n  'aria-label': string,\n  'on:keydown': JSX.HTMLAttributes<HTMLElement>['on:keydown'],\n  havePadding: boolean,\n  noRipple: boolean,\n  noWrap: boolean,\n  disabled: boolean,\n  fakeDisabled: boolean,\n  color: 'primary' | 'danger',\n  // buttonRight?: HTMLElement | boolean,\n  // buttonRightLangKey: LangPackKey,\n  // rightTextContent?: string,\n  as: 'a' | 'label' | 'div',\n  'aria-checked': boolean,\n  'aria-disabled': boolean,\n  contextMenu: Omit<Parameters<typeof createContextMenu>[0], 'findElement' | 'listenTo' | 'listenerSetter'>,\n  openContextMenuRef: (open?: ReturnType<typeof createContextMenu>['open']) => void,\n  // checkboxKeys: [LangPackKey, LangPackKey],\n  classList: {[key: string]: boolean},\n  class: string,\n  style: JSX.CSSProperties | string\n}>) => {\n  const value: RowContextValue = {\n    ...createRowValue(),\n    get noWrap() {\n      return props.noWrap;\n    },\n    // with a subtitle underneath, a toggle on the title row would hang above the row's own middle,\n    // out of line with the media/icon next to it — give it the right column instead\n    get toggleAside() {\n      return !!(this.store.checkboxFieldToggle && this.store.subtitle && !this.store.rightContent);\n    }\n  };\n\n  const {store} = value;\n\n  const isCheckbox = () => !!(\n    store.checkboxField || store.checkboxFieldToggle || store.radioField || store.radioFieldRight\n  );\n  const isClickable = () => !!(props.clickable || isCheckbox() || props.contextMenu);\n  const haveRipple = () => !!(!props.noRipple && isClickable());\n  const havePadding = () => !!(\n    props.havePadding ||\n    store.icon ||\n    store.checkboxField ||\n    store.radioField ||\n    store.media\n  );\n  const resolvedChildren = children(() => (\n    <RowContext.Provider value={value}>\n      {props.children}\n    </RowContext.Provider>\n  ));\n\n  let openContextMenu: ReturnType<typeof createContextMenu>['open'];\n  const ref = (container: HTMLElement) => {\n    const listenerSetter = new ListenerSetter();\n\n    if(props.contextMenu) {\n      const {open} = createContextMenu({\n        ...props.contextMenu,\n        listenTo: container,\n        listenerSetter\n      });\n\n      openContextMenu = open;\n      props.openContextMenuRef?.(open);\n    }\n\n    onCleanup(() => {\n      openContextMenu = undefined;\n      props.openContextMenuRef?.();\n      listenerSetter.removeAll();\n    });\n\n    if(typeof(props.ref) === 'function') {\n      props.ref(container);\n    }\n  };\n  const onClick: JSX.EventHandlerUnion<HTMLElement, MouseEvent> = (event) => {\n    const clickable = props.clickable;\n    if(typeof(clickable) === 'function') {\n      if(!hasMouseMovedSinceDown(event)) {\n        clickable(event);\n      }\n      return;\n    }\n\n    openContextMenu?.(event);\n  };\n\n  return (\n    <RippleElement\n      ref={ref}\n      component={props.as === 'a' ? 'a' : (props.as === 'label' || isCheckbox() ? 'label' : 'div')}\n      role={props.role}\n      tabIndex={props.tabIndex}\n      aria-checked={props['aria-checked']}\n      aria-disabled={props['aria-disabled'] || props.disabled ? true : undefined}\n      classList={{\n        'row': true,\n        'no-subtitle': !store.subtitle,\n        'no-wrap': value.noWrap,\n        'row-with-icon': !!store.icon,\n        'row-with-padding': havePadding(),\n        [`row-clickable hover-${props.color ? props.color + '-' : ''}effect`]: isClickable(),\n        'is-disabled': props.disabled,\n        'is-fake-disabled': props.fakeDisabled,\n        'row-grid': !!store.rightContent || value.toggleAside,\n        'with-midtitle': !!store.midtitle,\n        ...(props.classList || {}),\n        [props.class]: !!props.class\n      }}\n      onClick={typeof(props.clickable) === 'function' || props.contextMenu ? onClick : undefined}\n      aria-label={props['aria-label']}\n      style={props.style}\n      onKeyDown={!props['on:keydown'] && props.tabIndex !== undefined && props.clickable ? (event: KeyboardEvent) => {\n        if(event.key !== 'Enter' && event.key !== ' ') {\n          return;\n        }\n\n        event.preventDefault();\n        (event.currentTarget as HTMLElement).click();\n      } : undefined}\n      on:keydown={props['on:keydown']}\n      noRipple={!haveRipple()}\n    >\n      {resolvedChildren()}\n      {store.title}\n      {store.midtitle}\n      {store.subtitle}\n      {store.icon}\n      {store.checkboxField || store.radioField}\n      {store.rightContent}\n      <Show when={value.toggleAside}>\n        <div class=\"row-right\">{store.checkboxFieldToggle}</div>\n      </Show>\n      {store.media}\n    </RippleElement>\n  );\n};\n\nRow.RowPart = (props: {\n  class: string,\n  part?: JSX.Element,\n  elementRef?: Ref<HTMLDivElement>\n}) => {\n  const resolved = children(() => props.part);\n  return (\n    <Show when={!!props.elementRef || !!resolved()}>\n      <div\n        ref={(element) => {\n          if(typeof(props.elementRef) === 'function') {\n            props.elementRef(element);\n          }\n        }}\n        class={classNames(\n          'row-' + props.class,\n          useContext(RowContext).noWrap && 'no-wrap'\n        )}\n        dir=\"auto\"\n      >\n        {resolved()}\n      </div>\n    </Show>\n  );\n};\n\nRow.Row = (props: {\n  class: string,\n  rowClass?: string,\n  additionalClass?: string,\n  rightAdditionalClass?: string,\n  left?: JSX.Element,\n  right?: JSX.Element,\n  rightSecondary?: boolean,\n  leftRef?: Ref<HTMLDivElement>,\n  rightRef?: Ref<HTMLDivElement>\n}) => {\n  const part = (\n    <Row.RowPart\n      elementRef={props.leftRef}\n      class={classNames(props.class, props.additionalClass)}\n      part={props.left}\n    />\n  );\n  const resolved = children(() => props.right);\n  return (\n    <Show when={!!props.rightRef || !!resolved()} fallback={part}>\n      <div class={classNames('row-row', `row-${props.class}-row`, props.rowClass)}>\n        {part}\n        <Row.RowPart\n          elementRef={props.rightRef}\n          class={classNames(\n            props.class,\n            props.additionalClass,\n            props.rightAdditionalClass,\n            `row-${props.class}-right${props.rightSecondary ? ` row-${props.class}-right-secondary` : ''}`\n          )}\n          part={resolved()}\n        />\n      </div>\n    </Show>\n  );\n};\n\nRow.Title = (props: {\n  children?: JSX.Element,\n  rowClass?: string,\n  class?: string,\n  titleRight?: JSX.Element,\n  titleRightClass?: string,\n  titleRightSecondary?: boolean,\n  ref?: Ref<HTMLDivElement>,\n  titleRightRef?: (element: HTMLDivElement) => void\n}) => {\n  const context = useContext(RowContext);\n  const explicitRight = children(() => props.titleRight);\n  const control = () => context.store.radioFieldRight || (\n    context.toggleAside ? undefined : context.store.checkboxFieldToggle\n  );\n  const right = () => {\n    const explicit = explicitRight();\n    const currentControl = control();\n    return explicit && currentControl ? [explicit, currentControl] : explicit || currentControl;\n  };\n\n  return context.register('title', (\n    <Row.Row\n      class=\"title\"\n      rowClass={props.rowClass}\n      additionalClass={props.class}\n      left={props.children}\n      right={right()}\n      rightAdditionalClass={classNames(\n        props.titleRightClass,\n        !!(explicitRight() && control()) && 'row-title-right-with-control'\n      )}\n      rightSecondary={props.titleRightSecondary}\n      leftRef={props.ref}\n      rightRef={props.titleRightRef}\n    />\n  ));\n};\n\nRow.Midtitle = (props: {\n  children?: JSX.Element,\n  ref?: Ref<HTMLDivElement>\n}) => {\n  return useContext(RowContext).register('midtitle', (\n    <Row.Row\n      class=\"midtitle\"\n      left={props.children}\n      leftRef={props.ref}\n    />\n  ));\n};\n\nRow.Subtitle = (props: {\n  children?: JSX.Element,\n  class?: string,\n  subtitleRight?: JSX.Element,\n  ref?: Ref<HTMLDivElement>,\n  subtitleRightRef?: (element: HTMLDivElement) => void\n}) => {\n  return useContext(RowContext).register('subtitle', (\n    <Row.Row\n      class=\"subtitle\"\n      additionalClass={props.class}\n      left={props.children}\n      right={props.subtitleRight}\n      leftRef={props.ref}\n      rightRef={props.subtitleRightRef}\n    />\n  ));\n};\n\nRow.Icon = (props: {\n  icon: Icon,\n  class?: string\n}) => {\n  return useContext(RowContext).register('icon', (\n    <span\n      class={classNames(\n        'row-icon',\n        'row-icon-colored',\n        props.class\n      )}\n      style={{\n        'background-image': getRowIconBackgroundImage(props.icon)\n      }}\n    >\n      <IconTsx icon={props.icon} class=\"row-icon-icon\" />\n    </span>\n  ));\n};\n\ntype ExternalRowElementProps = {\n  class?: string,\n  element: HTMLElement\n};\n\nRow.RightContent = (inProps: JSX.HTMLAttributes<HTMLDivElement> | ExternalRowElementProps) => {\n  const context = useContext(RowContext);\n\n  if('element' in inProps) {\n    return registerExternalElement(\n      context,\n      'rightContent',\n      () => inProps.element,\n      () => classNames('row-right', inProps.class)\n    );\n  }\n\n  const [props, restProps] = splitProps(inProps, ['class']);\n  return context.register('rightContent', (\n    <div class={classNames('row-right', props.class)} {...restProps} />\n  ));\n};\n\n/**\n * Registers a field AND marks it as the row's own, so `_row.scss` lays out this checkbox and not\n * whatever else happens to sit inside the row. See `rowFieldClasses`.\n */\nfunction registerRowField(kind: Kind, classes: string[], element: JSX.Element) {\n  const context = useContext(RowContext);\n  const resolved = children(() => element);\n  const registeredKind = kind === 'radioField' && resolved.toArray().some((node) => (\n    node instanceof HTMLElement && node.classList.contains(RADIO_FIELD_RIGHT_CLASS)\n  )) ? 'radioFieldRight' : kind;\n\n  createRenderEffect(() => {\n    resolved.toArray().forEach((node) => {\n      node instanceof HTMLElement && attachHotClassName(node, ...classes);\n    });\n  });\n\n  return context.register(registeredKind, resolved());\n}\n\nRow.CheckboxField = (props: {\n  children: JSX.Element\n}) => {\n  return registerRowField('checkboxField', [ROW_CHECKBOX_FIELD_CLASS], props.children);\n};\n\nRow.RadioField = (props: {\n  children: JSX.Element\n}) => {\n  return registerRowField('radioField', [ROW_RADIO_FIELD_CLASS], props.children);\n};\n\nRow.CheckboxFieldToggle = (props: {\n  children: JSX.Element\n}) => {\n  // a toggle is a checkbox too, so the row's checkbox rules go on reaching it\n  return registerRowField(\n    'checkboxFieldToggle',\n    [ROW_CHECKBOX_FIELD_TOGGLE_CLASS],\n    props.children\n  );\n};\n\ntype RowMediaProps = JSX.HTMLAttributes<HTMLDivElement> & {\n  children?: JSX.Element,\n  size?: RowMediaSizeType,\n  class?: string\n};\n\ntype ExternalRowMediaProps = ExternalRowElementProps & {\n  size?: RowMediaSizeType\n};\n\nRow.Media = (inProps: RowMediaProps | ExternalRowMediaProps) => {\n  const context = useContext(RowContext);\n  const classes = () => classNames(\n    'row-media',\n    inProps.size && `row-media-${inProps.size}`,\n    inProps.class\n  );\n\n  if('element' in inProps) {\n    return registerExternalElement(context, 'media', () => inProps.element, classes);\n  }\n\n  const [props, restProps] = splitProps(inProps, ['children', 'size', 'class']);\n  return context.register('media', (\n    <div\n      class={classes()}\n      {...restProps}\n    >\n      {props.children}\n    </div>\n  ));\n};\n\nexport default Row;\n","import {createRoot, JSX} from 'solid-js';\nimport {Middleware} from '@helpers/middleware';\n\nexport function unwrapSolidElement(element: JSX.Element): JSX.Element {\n  while(typeof(element) === 'function') {\n    element = (element as () => JSX.Element)();\n  }\n\n  return element;\n}\n\nexport function wrapSolidComponent(component: () => JSX.Element, middleware: Middleware): HTMLElement {\n  let dispose!: VoidFunction;\n  const el = createRoot((dispose_) => {\n    dispose = dispose_;\n    return unwrapSolidElement(component());\n  });\n\n  middleware.onClean(dispose);\n\n  return el as HTMLElement;\n}\n\nexport function mountSolidComponent(\n  component: (middleware: Middleware) => JSX.Element,\n  parentMiddleware: Middleware\n): {element: HTMLElement, dispose: VoidFunction, middleware: Middleware} {\n  const middlewareHelper = parentMiddleware.create();\n  const middleware = middlewareHelper.get();\n  let disposed = false;\n  const dispose = () => {\n    if(disposed) {\n      return;\n    }\n\n    disposed = true;\n    middlewareHelper.destroy();\n  };\n\n  try {\n    return {\n      element: wrapSolidComponent(() => component(middleware), middleware),\n      dispose,\n      middleware\n    };\n  } catch(err) {\n    dispose();\n    throw err;\n  }\n}\n","import PopupElement, {addCancelButton, PopupButton, PopupOptions} from '.';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport CheckboxField, {CheckboxFieldOptions} from '@components/checkboxField';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {avatarNew} from '@components/avatarNew';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport rootScope from '@lib/rootScope';\nimport InputField from '@components/inputField';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport RowTsx from '@components/rowTsx';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\n\nexport type PopupPeerButton = Omit<PopupButton, 'callback'> & Partial<{callback: PopupPeerButtonCallback, onlyWithCheckbox: PopupPeerCheckboxOptions}>;\nexport type PopupPeerButtonCallbackCheckboxes = Set<LangPackKey>;\nexport type PopupPeerButtonCallback = (e: MouseEvent, checkboxes?: PopupPeerButtonCallbackCheckboxes) => void;\n// the caption belongs to the row the popup builds around the checkbox, not to the checkbox itself;\n// `text` doubles as the checkbox's identity in the button callbacks\nexport type PopupPeerCheckboxOptions = CheckboxFieldOptions & {\n  text?: LangPackKey,\n  textArgs?: any[],\n  checkboxField?: CheckboxField\n};\n\nexport type PopupPeerOptions = Omit<PopupOptions, 'buttons' | 'title'> & Partial<{\n  peerId: PeerId,\n  threadId: number,\n  // for a peer the plain avatar can't draw on its own (a Community and its decoration);\n  // the caller owns it and its teardown\n  avatar: HTMLElement,\n  title: string | HTMLElement | DocumentFragment,\n  titleLangKey: LangPackKey,\n  titleLangArgs: any[],\n  noTitle: boolean,\n  description: Parameters<typeof setInnerHTML>[1] | true,\n  descriptionRaw: string,\n  descriptionLangKey: LangPackKey,\n  descriptionLangArgs: any[],\n  buttons: Array<PopupPeerButton>,\n  checkboxes: Array<PopupPeerCheckboxOptions>,\n  inputField: InputField,\n  old: boolean\n}>;\nexport default class PopupPeer extends PopupElement {\n  protected description: HTMLParagraphElement;\n  private inputField?: InputField;\n\n  constructor(private className: string, options: PopupPeerOptions = {}) {\n    super('popup-peer' + (className ? ' ' + className : ''), {\n      overlayClosable: true,\n      ...options,\n      title: true,\n      buttons: options.buttons && addCancelButton(options.buttons)\n    });\n\n    if(options.avatar) {\n      this.header.prepend(options.avatar);\n    } else if(options.peerId) {\n      const isSavedDialog = !!(options.peerId === rootScope.myId && options.threadId);\n      const {node} = avatarNew({\n        middleware: this.middlewareHelper.get(),\n        size: 32,\n        isDialog: true,\n        peerId: isSavedDialog ? options.threadId : options.peerId,\n        threadId: isSavedDialog ? undefined : options.threadId,\n        meAsNotes: isSavedDialog\n      });\n      this.header.prepend(node);\n    }\n\n    if(!options.noTitle) {\n      if(options.titleLangKey || !options.title) {\n        this.title.append(i18n(options.titleLangKey || 'AppName', options.titleLangArgs));\n      } else if(options.title instanceof HTMLElement || options.title instanceof DocumentFragment) {\n        this.title.append(options.title);\n      } else this.title.innerText = options.title || '';\n    }\n\n    const fragment = document.createDocumentFragment();\n\n    if(options.descriptionLangKey || options.description || options.descriptionRaw) {\n      const p = this.description = document.createElement('p');\n      p.classList.add('popup-description');\n      if(options.descriptionLangKey) p.append(i18n(options.descriptionLangKey, options.descriptionLangArgs));\n      else if(options.description && options.description !== true) setInnerHTML(p, options.description);\n      else if(options.descriptionRaw) p.append(wrapEmojiText(options.descriptionRaw));\n\n      fragment.append(p);\n    }\n\n    if(options.inputField) {\n      this.inputField = options.inputField;\n      fragment.append(options.inputField.container);\n      const button = options.buttons.find((button) => !button.isCancel);\n      toggleDisability([button.element], !options.inputField.isValid());\n    }\n\n    if(options.checkboxes) {\n      this.container.classList.add('have-checkbox');\n\n      options.checkboxes.forEach((o) => {\n        const checkboxOptions: CheckboxFieldOptions = o;\n        const row = wrapSolidComponent(() => (\n          <RowTsx class=\"popup-peer-checkbox-row\">\n            {o.text && <RowTsx.Title>{i18n(o.text, o.textArgs)}</RowTsx.Title>}\n            <RowTsx.CheckboxField>\n              <CheckboxFieldTsx\n                {...checkboxOptions}\n                ref={(checkboxField) => o.checkboxField = checkboxField}\n              />\n            </RowTsx.CheckboxField>\n          </RowTsx>\n        ), this.middlewareHelper.get());\n\n        fragment.append(row);\n      });\n\n      options.buttons.forEach((button) => {\n        if(button.callback) {\n          const original = button.callback;\n          button.callback = (e) => {\n            const c: Set<LangPackKey> = new Set();\n            options.checkboxes.forEach((o) => {\n              if(o.checkboxField.checked) {\n                c.add(o.text);\n              }\n            });\n            original(e, c);\n          };\n        }\n\n        const checkbox = button.onlyWithCheckbox;\n        if(checkbox) {\n          const onChange = () => {\n            toggleDisability([button.element], !checkbox.checkboxField.checked);\n          };\n          this.listenerSetter.add(checkbox.checkboxField.input)('change', onChange);\n          onChange();\n        }\n      });\n    }\n\n    if(options.inputField) {\n      const button = options.buttons.find((button) => !button.isCancel);\n      this.listenerSetter.add(options.inputField.input)('input', () => {\n        toggleDisability([button.element], !options.inputField.isValid());\n      });\n    }\n\n    this.header.after(fragment);\n  }\n\n  public show(animate?: boolean): void {\n    super.show(animate);\n    this.inputField?.input.focus();\n  }\n}\n","import classNames from '@helpers/string/classNames';\nimport PopupElement, {addCancelButton} from '@components/popups';\nimport PopupPeer, {PopupPeerCheckboxOptions, PopupPeerOptions} from '@components/popups/peer';\n\nexport type ConfirmationPopupRejectReason = 'canceled' | 'closed';\n\n// type PopupConfirmationOptions = Pick<PopupPeerOptions, 'titleLangKey'>;\nexport type PopupConfirmationOptions = PopupPeerOptions & {\n  button: PopupPeerOptions['buttons'][0],\n  checkbox?: PopupPeerOptions['checkboxes'][0],\n  inputField?: PopupPeerOptions['inputField'],\n  rejectWithReason?: boolean,\n  className?: string;\n  onPopup?: (popup: PopupPeer) => void;\n};\n\nexport default function confirmationPopup<T extends PopupConfirmationOptions>(\n  options: T\n): Promise<T['checkboxes'] extends PopupPeerCheckboxOptions[] ? Array<boolean> : (T['checkbox'] extends PopupPeerCheckboxOptions ? boolean : void)> {\n  return new Promise<any>((resolve, reject: (reason?: ConfirmationPopupRejectReason) => void) => {\n    const {button, checkbox, rejectWithReason} = options;\n    button.callback = (e, set) => {\n      if(checkbox || !set) {\n        resolve(set ? !!set.size : undefined);\n      } else {\n        resolve(options.checkboxes.map((checkbox) => set.has(checkbox.text)));\n      }\n    };\n\n    const buttons = addCancelButton(options.buttons || [button]);\n    const cancelButton = buttons.find((button) => button.isCancel);\n    cancelButton.callback = () => {\n      reject(rejectWithReason ? 'canceled' : undefined);\n    };\n\n    options.buttons = buttons;\n    options.checkboxes ??= checkbox && [checkbox];\n\n    const popup = PopupElement.createPopup(PopupPeer, classNames('popup-confirmation', options.className), options);\n\n    options.onPopup?.(popup);\n\n    popup.addEventListener('closeAfterTimeout', () => {\n      reject(rejectWithReason ? 'closed' : undefined);\n    });\n\n    popup.show();\n  });\n}\n","import PopupElement from '.';\nimport type {PeerType} from '@appManagers/appPeersManager';\nimport {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport PopupPeer, {PopupPeerButtonCallbackCheckboxes, PopupPeerOptions} from '@components/popups/peer';\n\nexport default class PopupDeleteDialog {\n  constructor(\n    private peerId: PeerId,\n    // actionType: 'leave' | 'delete',\n    private peerType?: PeerType,\n    private onSelect?: (promise: Promise<any>) => void,\n    private threadId?: number,\n    private monoforumParentPeerId?: number\n  ) {\n    this.construct();\n  }\n\n  private async construct() {\n    let {peerId, peerType, onSelect, threadId, monoforumParentPeerId} = this;\n\n    const isSavedDialog = await rootScope.managers.appPeersManager.isSavedDialog(peerId, threadId);\n    // if(isSavedDialog) {\n    //   peerId = threadId;\n    // }\n\n    const peerTitleElement = await wrapPeerTitle({\n      peerId: isSavedDialog ? threadId : peerId,\n      threadId: isSavedDialog ? undefined : threadId,\n      meAsNotes: isSavedDialog\n    });\n\n    const managers = PopupElement.MANAGERS;\n    if(peerType === undefined) {\n      peerType = await managers.appPeersManager.getDialogType(monoforumParentPeerId || peerId, monoforumParentPeerId ? peerId : threadId);\n    }\n\n    /* const callbackFlush = (checked: PopupPeerButtonCallbackCheckboxes) => {\n      const promise = appMessagesManager.flushHistory(peerId, checkboxes ? !checked[checkboxes[0].text] : undefined);\n      onSelect && onSelect(promise);\n    }; */\n\n    const callbackLeave = (e: MouseEvent, checked: PopupPeerButtonCallbackCheckboxes, flush = checkboxes && !!checked.size) => {\n      let promise = managers.appChatsManager.leave(peerId.toChatId());\n\n      if(flush) {\n        promise = promise.then(() => {\n          return managers.appMessagesManager.flushHistory({peerId});\n        }) as any;\n      }\n\n      onSelect?.(promise);\n    };\n\n    const callbackDelete = (e: MouseEvent, checked: PopupPeerButtonCallbackCheckboxes) => {\n      let promise: Promise<any>;\n\n      if(monoforumParentPeerId) {\n        promise = managers.appMessagesManager.flushHistory({peerId: monoforumParentPeerId, justClear: false, revoke: true, monoforumThreadId: peerId});\n      } else if(isSavedDialog) {\n        promise = managers.appMessagesManager.flushHistory({peerId, justClear: false, revoke: true, threadOrSavedId: threadId});\n      } else if(threadId) {\n        promise = managers.appMessagesManager.flushHistory({peerId, justClear: false, revoke: true, threadOrSavedId: threadId});\n      } else if(peerId.isUser()) {\n        promise = managers.appMessagesManager.flushHistory({peerId, justClear: false, revoke: checkboxes ? !!checked.size : undefined});\n      } else {\n        if(checked.size) {\n          promise = managers.appChatsManager.delete(peerId.toChatId());\n        } else {\n          return callbackLeave(e, checked);\n        }\n      }\n\n      onSelect?.(promise);\n    };\n\n    let title: LangPackKey,\n      titleArgs: FormatterArguments,\n      description: LangPackKey,\n      descriptionArgs: FormatterArguments,\n      buttons: PopupPeerOptions['buttons'],\n      checkboxes: PopupPeerOptions['checkboxes'];\n    switch(peerType) {\n      case 'channel': {\n        if(/* actionType === 'delete' &&  */await managers.appChatsManager.hasRights(peerId.toChatId(), 'delete_chat')) {\n          title = 'ChannelDeleteMenu';\n          description = 'AreYouSureDeleteAndExitChannel';\n          buttons = [{\n            langKey: 'ChannelDeleteMenu',\n            isDanger: true,\n            callback: callbackDelete\n          }];\n\n          checkboxes = [{\n            text: 'DeleteChannelForAll'\n          }];\n        } else {\n          title = 'LeaveChannelMenu';\n          description = 'ChannelLeaveAlertWithName';\n          descriptionArgs = [peerTitleElement];\n          buttons = [{\n            langKey: 'LeaveChannel',\n            isDanger: true,\n            callback: callbackLeave\n          }];\n        }\n\n        break;\n      }\n\n      case 'monoforum': {\n        title = 'LeaveMonoforum';\n        description = 'MonoforumLeaveAlertWithName';\n        descriptionArgs = [peerTitleElement];\n        buttons = [{\n          langKey: 'LeaveMonoforum',\n          isDanger: true,\n          callback: callbackLeave\n        }];\n        break;\n      }\n\n      /* case 'megagroup': {\n        title = 'Leave Group?';\n        description = `Are you sure you want to leave this group?`;\n        buttons = [{\n          text: 'LEAVE ' + peerTitleElement,\n          isDanger: true,\n          callback: callbackLeave\n        }];\n\n        break;\n      } */\n\n      case 'monoforum_thread': {\n        title = 'DeleteChatUser';\n        description = 'AreYouSureDeleteThisChatWithUser';\n        descriptionArgs = [peerTitleElement];\n\n        buttons = [{\n          langKey: 'DeleteChatUser',\n          isDanger: true,\n          callback: callbackDelete\n        }];\n        break;\n      }\n      case 'chat': {\n        title = 'DeleteChatUser';\n        description = 'AreYouSureDeleteThisChatWithUser';\n        descriptionArgs = [peerTitleElement];\n\n        buttons = [{\n          langKey: 'DeleteChatUser',\n          isDanger: true,\n          callback: callbackDelete\n        }];\n\n        checkboxes = [{\n          text: 'DeleteMessagesOptionAlso',\n          textArgs: [\n            await wrapPeerTitle({peerId})\n          ]\n        }];\n\n        break;\n      }\n\n      case 'saved': {\n        title = 'DeleteChatUser';\n        description = 'AreYouSureDeleteThisChatSavedMessages';\n        buttons = [{\n          langKey: 'DeleteChatUser',\n          isDanger: true,\n          callback: callbackDelete\n        }];\n\n        break;\n      }\n\n      case 'savedDialog': {\n        title = 'DeleteChatUser';\n        description = 'DeleteSavedDialogDescription';\n        descriptionArgs = [peerTitleElement];\n        buttons = [{\n          langKey: 'DeleteChatUser',\n          isDanger: true,\n          callback: callbackDelete\n        }];\n\n        break;\n      }\n\n      case 'megagroup':\n      case 'group':\n      case 'botforum_thread': {\n        if(threadId) {\n          title = 'DeleteTopics';\n          titleArgs = [1];\n          description = 'DeleteSelectedTopic';\n          descriptionArgs = [peerTitleElement];\n          buttons = [{\n            langKey: 'Delete',\n            isDanger: true,\n            callback: callbackDelete\n          }];\n        } else if(/* actionType === 'delete' &&  */await managers.appChatsManager.hasRights(peerId.toChatId(), 'delete_chat')) {\n          title = 'DeleteMegaMenu';\n          description = 'AreYouSureDeleteAndExit';\n          buttons = [{\n            langKey: 'DeleteMegaMenu',\n            isDanger: true,\n            callback: callbackDelete\n          }];\n\n          checkboxes = [{\n            text: 'DeleteChat.DeleteGroupForAll'\n          }];\n        } else {\n          title = 'LeaveMegaMenu';\n          description = 'AreYouSureDeleteAndExitName';\n          descriptionArgs = [peerTitleElement];\n          buttons = [{\n            langKey: 'DeleteChatUser',\n            isDanger: true,\n            callback: (e, checkboxes) => callbackLeave(e, checkboxes, true)\n          }];\n        }\n\n        break;\n      }\n    }\n\n    PopupElement.createPopup(PopupPeer, 'popup-delete-chat', {\n      peerId,\n      threadId,\n      titleLangKey: title,\n      titleLangArgs: titleArgs,\n      descriptionLangKey: description,\n      descriptionLangArgs: descriptionArgs,\n      buttons,\n      checkboxes\n    }).show();\n  }\n}\n","import simulateEvent from '@helpers/dom/dispatchEvent';\nimport getDeepProperty from '@helpers/object/getDeepProperty';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport Icon from '@components/icon';\nimport {RADIO_FIELD_RIGHT_CLASS} from '@components/rowFieldClasses';\n\n/**\n * The radio control only. Any visible label belongs to the hosting Row.Title.\n */\nexport default class RadioField {\n  public input: HTMLInputElement;\n  public container: HTMLSpanElement;\n  public main: HTMLElement;\n  public lockIcon: HTMLElement;\n\n  constructor(options: {\n    name: string,\n    value?: string,\n    valueForState?: any,\n    stateKey?: string,\n    alignRight?: boolean\n  }) {\n    const container = this.container = document.createElement('span');\n    container.classList.add('radio-field');\n\n    if(options.alignRight) {\n      container.classList.add(RADIO_FIELD_RIGHT_CLASS);\n    }\n\n    const input = this.input = document.createElement('input');\n    input.type = 'radio';\n    input.name = 'input-radio-' + options.name;\n\n    if(options.value !== undefined) {\n      input.value = options.value;\n\n      const getValueForState = () => 'valueForState' in options ? options.valueForState : options.value;\n\n      if(options.stateKey) {\n        apiManagerProxy.getState().then((state) => {\n          input.checked = getDeepProperty(state, options.stateKey) === getValueForState();\n        });\n\n        input.addEventListener('change', () => {\n          rootScope.managers.appStateManager.setByKey(options.stateKey, getValueForState());\n        });\n      }\n    }\n\n    const main = this.main = document.createElement('div');\n    main.classList.add('radio-field-main');\n\n    container.append(input, main);\n  }\n\n  get checked() {\n    return this.input.checked;\n  }\n\n  set checked(checked: boolean) {\n    this.setValueSilently(checked);\n    simulateEvent(this.input, 'change');\n  }\n\n  get locked() {\n    return !!this.lockIcon;\n  }\n\n  set locked(locked: boolean) {\n    if(!locked) {\n      this.lockIcon?.remove();\n      this.lockIcon = undefined;\n      this.main.classList.remove('is-locked');\n      return;\n    }\n\n    if(this.lockIcon) {\n      return;\n    }\n\n    this.main.prepend(this.lockIcon = Icon('premium_lock', 'radio-field-lock'));\n    this.main.classList.add('is-locked');\n  }\n\n  public setValueSilently(checked: boolean) {\n    this.input.checked = checked;\n  }\n}\n","import {createEffect, splitProps} from 'solid-js';\nimport RadioField from '@components/radioField';\nimport {attachClassName} from '@helpers/solid/classname';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\n\n/** The control only — mount it through `Row.RadioField` and put its label in `Row.Title`. */\nexport default function RadioFieldTsx(props: ConstructorParameters<typeof RadioField>[0] & {\n  ariaLabel?: string,\n  checked?: boolean,\n  class?: string,\n  locked?: boolean,\n  onChange?: (checked: boolean, event: Event) => void\n}) {\n  const [local, radioProps] = splitProps(props, [\n    'ariaLabel',\n    'checked',\n    'class',\n    'locked',\n    'onChange'\n  ]);\n  const radioField = new RadioField(radioProps);\n\n  createEffect(() => {\n    if(local.checked !== undefined) {\n      radioField.setValueSilently(local.checked);\n    }\n  });\n\n  createEffect(() => {\n    radioField.locked = !!local.locked;\n  });\n\n  createEffect(() => {\n    const ariaLabel = local.ariaLabel;\n    if(ariaLabel) {\n      radioField.input.setAttribute('aria-label', ariaLabel);\n    } else {\n      radioField.input.removeAttribute('aria-label');\n    }\n  });\n\n  subscribeOn(radioField.input)('change', (event) => {\n    local.onChange?.(radioField.checked, event);\n  });\n\n  attachClassName(radioField.container, () => local.class);\n\n  return radioField.container;\n}\n","import {createUniqueId, For, JSX, Show} from 'solid-js';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport RadioFieldTsx from '@components/radioFieldTsx';\nimport Row from '@components/rowTsx';\n\nexport type RadioFormTsxValue<T extends number | string = number | string> = {\n  checked?: boolean,\n  langPackKey?: LangPackKey,\n  subtitle?: JSX.Element,\n  text?: string,\n  textElement?: HTMLElement | DocumentFragment,\n  value: T\n};\n\nexport default function RadioFormTsx<T extends number | string>(props: {\n  name?: string,\n  onChange: (value: T, event: Event) => void,\n  selected?: T,\n  values: RadioFormTsxValue<T>[]\n}) {\n  const name = props.name || createUniqueId();\n\n  return (\n    <form>\n      <For each={props.values}>{(item) => (\n        <Row>\n          <Row.RadioField>\n            <RadioFieldTsx\n              class=\"disable-hover\"\n              checked={props.selected === undefined ? item.checked : props.selected === item.value}\n              name={name}\n              value={String(item.value)}\n              onChange={(checked, event) => checked && props.onChange(item.value, event)}\n            />\n          </Row.RadioField>\n          <Row.Title>\n            {item.langPackKey ? i18n(item.langPackKey) : item.textElement ?? item.text}\n          </Row.Title>\n          <Show when={item.subtitle !== undefined}>\n            <Row.Subtitle>{item.subtitle}</Row.Subtitle>\n          </Show>\n        </Row>\n      )}</For>\n    </form>\n  );\n}\n","import {createMemo, JSX, onCleanup, Show} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport {Portal} from 'solid-js/web';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport type AvatarEdit from '@components/avatarEdit';\nimport classNames from '@helpers/string/classNames';\nimport type {Chat} from '@layer';\nimport styles from '@components/communities/communityAvatar.module.scss';\n\ntype AvatarPeer = NonNullable<Parameters<typeof AvatarNewTsx>[0]['peer']>;\n\nexport function getCommunityAvatarStyle(size: number) {\n  return {\n    '--community-avatar-size': `${size}px`\n  };\n}\n\nfunction CommunityAvatarDecoration(props: {fill?: string}) {\n  return (\n    <svg\n      class={styles.Decoration}\n      width=\"125\"\n      height=\"100\"\n      viewBox=\"0 0 125 100\"\n      fill=\"none\"\n      xmlns=\"http://www.w3.org/2000/svg\"\n      aria-hidden=\"true\"\n    >\n      <path opacity=\"0.15\" d=\"M26.4382 12.0185C26.0639 12.6406 25.7099 13.2766 25.3787 13.9267C23.6015 17.4147 22.788 21.3107 22.3913 26.165C21.9976 30.9845 21.9997 37.0086 21.9997 44.7997V55.2001C21.9997 62.9912 21.9976 69.0154 22.3913 73.8349C22.788 78.6891 23.6016 82.5852 25.3787 86.0732C26.6559 88.5799 28.2611 90.8845 30.1384 92.9345C28.104 91.6505 26.3049 90.0031 24.8396 88.0585C21.9499 84.2238 20.977 78.7084 19.032 67.6777L15.2117 46.0117C13.2667 34.9811 12.2943 29.4656 13.698 24.874C14.9328 20.8349 17.4147 17.2898 20.7878 14.748C22.3208 13.5928 24.123 12.7455 26.4382 12.0185Z\" fill={props.fill || 'black'} />\n      <path opacity=\"0.1\" d=\"M10.3996 25.7243C9.94967 28.0394 9.95115 30.4979 10.2131 33.3063C10.5379 36.7882 11.2941 41.0664 12.258 46.5329L16.0783 68.1989C17.0421 73.665 17.7943 77.9439 18.6799 81.3268C19.5744 84.7434 20.6657 87.5055 22.4436 89.8649C23.0895 90.722 23.7919 91.5293 24.5441 92.2819C23.6762 91.7404 22.8569 91.1149 22.1008 90.4098C19.2915 87.7901 17.7593 83.5791 14.6945 75.1588L6.89668 53.734C3.83196 45.3138 2.29974 41.1032 2.76778 37.2907C3.17959 33.9371 4.6422 30.7998 6.94649 28.3288C7.86463 27.3442 8.97798 26.5161 10.3996 25.7243ZM24.5754 87.696C24.6615 87.8184 24.7493 87.9392 24.8391 88.0583C24.8509 88.0739 24.8633 88.0895 24.8752 88.1051C24.8634 88.0896 24.8508 88.0748 24.8391 88.0592C24.7492 87.94 24.6616 87.8186 24.5754 87.696ZM22.6174 83.8893C22.8545 84.5181 23.1058 85.1059 23.3772 85.6588C23.1058 85.1059 22.8545 84.5181 22.6174 83.8893ZM22.2424 82.8258C22.3064 83.0203 22.3715 83.2109 22.4377 83.3981C22.3715 83.2109 22.3065 83.0203 22.2424 82.8258ZM21.5891 80.5983C21.4849 80.2014 21.3837 79.7907 21.2824 79.3659C21.3837 79.7907 21.4849 80.2014 21.5891 80.5983ZM20.3566 74.9938C20.1507 73.925 19.9404 72.7843 19.7209 71.5641L19.4357 69.9499C19.7627 71.7926 20.0624 73.4668 20.3566 74.9938ZM24.5705 87.6881C24.5723 87.6907 24.5736 87.6934 24.5754 87.696C24.5736 87.6934 24.5723 87.6907 24.5705 87.6881ZM22.5715 83.7663C22.5265 83.645 22.4817 83.5224 22.4377 83.3981C22.4816 83.5224 22.5265 83.645 22.5715 83.7663ZM21.6672 80.8883C21.6413 80.7924 21.6147 80.6959 21.5891 80.5983C21.6147 80.6959 21.6413 80.7924 21.6672 80.8883ZM20.6057 76.2536C20.5234 75.845 20.4398 75.4254 20.3566 74.9938C20.4398 75.4254 20.5234 75.845 20.6057 76.2536Z\" fill={props.fill || 'black'} />\n    </svg>\n  );\n}\n\nexport function getCloneableCommunityAvatarPeer(\n  community?: Chat.community | Chat.communityForbidden,\n  title?: string\n) {\n  if(!community) {\n    return;\n  }\n\n  const peer = unwrap(community);\n  return title === undefined ? peer : {...peer, title};\n}\n\nexport default function CommunityAvatar(props: {\n  community?: Chat.community | Chat.communityForbidden,\n  peerId?: PeerId,\n  title?: string,\n  size: number,\n  preview?: JSX.Element,\n  class?: string,\n  decorated?: boolean,\n  decorationFill?: string\n}) {\n  const avatarSource = createMemo(() => {\n    const community = props.community;\n    const title = props.title;\n    const photo = community?._ === 'community' ? community.photo : undefined;\n    const peer = getCloneableCommunityAvatarPeer(community, title);\n\n    return {\n      key: [\n        peer?._ || '',\n        peer?.id || props.peerId || '',\n        photo?._ || '',\n        photo?._ === 'chatPhoto' ? photo.photo_id : '',\n        photo?._ === 'chatPhoto' ? photo.dc_id : '',\n        title ?? peer?.title ?? '',\n        props.size\n      ].join(':'),\n      peer,\n      peerId: peer ? (peer.id as ChatId).toPeerId(true) : props.peerId,\n      size: props.size,\n      title: title ?? peer?.title ?? ''\n    };\n  });\n\n  return (\n    <div\n      class={classNames(styles.Container, props.class)}\n      style={getCommunityAvatarStyle(props.size)}\n    >\n      <Show when={props.decorated !== false}>\n        <CommunityAvatarDecoration fill={props.decorationFill || 'currentColor'} />\n      </Show>\n      <Show keyed when={avatarSource().key}>\n        <AvatarNewTsx\n          class={styles.Avatar}\n          peerId={avatarSource().peerId}\n          peer={avatarSource().peer as unknown as AvatarPeer}\n          peerTitle={avatarSource().peer || avatarSource().peerId ? undefined : avatarSource().title}\n          size={avatarSource().size}\n        />\n      </Show>\n      <Show when={props.preview}>\n        <div class={styles.Preview}>{props.preview}</div>\n      </Show>\n    </div>\n  );\n}\n\nexport function CommunityAvatarEditor(props: {\n  avatarEdit: AvatarEdit,\n  community?: Chat.community | Chat.communityForbidden,\n  peerId?: PeerId,\n  title?: string,\n  size?: number,\n  hasPreview: boolean\n}) {\n  const size = props.size || 120;\n  const container = props.avatarEdit.container;\n  container.classList.add(styles.EditorControl);\n  onCleanup(() => container.classList.remove(styles.EditorControl));\n\n  return (\n    <div\n      class={styles.EditorFrame}\n      style={getCommunityAvatarStyle(size)}\n    >\n      <CommunityAvatarDecoration fill=\"currentColor\" />\n      {container}\n      <Portal mount={container}>\n        <Show when={!props.hasPreview}>\n          <CommunityAvatar\n            class={`${styles.EditorPlaceholder} avatar-placeholder`}\n            community={props.community}\n            peerId={props.peerId}\n            title={props.title}\n            size={size}\n            decorated={false}\n          />\n        </Show>\n      </Portal>\n    </div>\n  );\n}\n","import {render} from 'solid-js/web';\nimport CommunityAvatar from '@components/communities/communityAvatar';\nimport {useCommunity} from '@stores/communities';\n\n/**\n * A Community avatar for the imperative parts of the app (chat-list rows, popups): the\n * same decorated avatar the Solid components render, in a plain element. It keeps itself\n * up to date with the Community, so call `dispose` when the host goes away.\n */\nexport default function createCommunityAvatarElement(\n  communityId: ChatId,\n  size: number\n) {\n  const mount = document.createElement('div');\n  const dispose = render(() => {\n    const community = useCommunity(() => communityId);\n    return (\n      <CommunityAvatar\n        community={community()}\n        title={community()?.title}\n        size={size}\n      />\n    );\n  }, mount);\n\n  return {\n    dispose,\n    element: mount.firstElementChild as HTMLElement\n  };\n}\n","import tsNow from '@helpers/tsNow';\nimport {LangPackKey} from '@lib/langPack';\nimport {MUTE_UNTIL} from '@appManagers/constants';\nimport RadioFormTsx from '@components/radioFormTsx';\nimport PopupPeer from '@components/popups/peer';\nimport createCommunityAvatarElement\nfrom '@components/communities/communityAvatarElement';\nimport {createComponent} from 'solid-js';\n\nconst ONE_HOUR = 3600;\nconst times: {value: number | string, langPackKey: LangPackKey, checked?: boolean}[] = [{\n  value: ONE_HOUR,\n  langPackKey: 'ChatList.Mute.1Hour'\n}, {\n  value: ONE_HOUR * 4,\n  langPackKey: 'ChatList.Mute.4Hours'\n}, {\n  value: ONE_HOUR * 8,\n  langPackKey: 'ChatList.Mute.8Hours'\n}, {\n  value: ONE_HOUR * 24,\n  langPackKey: 'ChatList.Mute.1Day'\n}, {\n  value: ONE_HOUR * 24 * 3,\n  langPackKey: 'ChatList.Mute.3Days'\n}, {\n  value: -1,\n  langPackKey: 'ChatList.Mute.Forever',\n  checked: true\n}];\n\nexport default class PopupMute extends PopupPeer {\n  constructor(\n    peerId?: PeerId,\n    threadId?: number,\n    communityId?: ChatId\n  ) {\n    // a Community can't go through `peerId`: its avatar is the decorated one, built here\n    // so the popup looks like every other mute popup instead of a bare title\n    const communityAvatar = communityId ?\n      createCommunityAvatarElement(communityId, 32) :\n      undefined;\n    super('popup-mute', {\n      peerId: communityId ? undefined : peerId,\n      avatar: communityAvatar?.element,\n      titleLangKey: 'Notifications',\n      buttons: [{\n        langKey: 'ChatList.Context.Mute',\n        callback: () => {\n          const muteUntil = time === -1 ?\n            MUTE_UNTIL :\n            tsNow(true) + time;\n          if(communityId) {\n            this.managers.appCommunitiesManager.muteCommunity(\n              communityId,\n              muteUntil\n            );\n          } else {\n            this.managers.appMessagesManager.mutePeer({\n              peerId,\n              muteUntil,\n              threadId\n            });\n          }\n        }\n      }],\n      body: true\n    });\n\n    if(communityAvatar) {\n      this.addEventListener('closeAfterTimeout', communityAvatar.dispose);\n    }\n\n    let time = +times.find((option) => option.checked).value;\n    this.appendSolid(() => createComponent(RadioFormTsx<number | string>, {\n      values: times,\n      onChange: (value) => {\n        time = +value;\n      }\n    }));\n\n    this.show();\n  }\n}\n","// https://spicyyoghurt.com/tools/easing-functions\nexport default function easeInOutSine(t: number, b: number, c: number, d: number) {\n  return t >= d ? b + c : easeInOutSineApply(t / d, c) + b;\n}\n\nexport function easeInOutSineApply(v: number, c: number) {\n  return -c / 2 * (Math.cos(Math.PI * v) - 1);\n}\n","export type GrabEvent = {x: number, y: number, isTouch?: boolean, event: TouchEvent | MouseEvent};\n\nexport default function attachGrabListeners(element: HTMLElement,\n  onStart: (position: GrabEvent) => void,\n  onMove: (position: GrabEvent) => void,\n  onEnd?: (position: GrabEvent) => void) {\n  // The grab MOVE/END track on `element.ownerDocument`, not the global `document`: while the client is\n  // popped into a Document PiP window the element lives in THAT document, so a main-`document` move/up\n  // listener never fires there and the drag (RangeSelector sliders — volume, seek bar — colorPicker,\n  // etc.) sticks. ownerDocument is the element's current window and can't change mid-drag.\n  // * Mouse\n  const onMouseMove = (event: MouseEvent) => {\n    onMove({x: event.pageX, y: event.pageY, event});\n  };\n\n  const onMouseUp = (event: MouseEvent) => {\n    element.ownerDocument.removeEventListener('mousemove', onMouseMove);\n    element.addEventListener('mousedown', onMouseDown, {once: true});\n    onEnd?.({x: event.pageX, y: event.pageY, event});\n  };\n\n  const onMouseDown = (event: MouseEvent) => {\n    if(event.button !== 0) {\n      element.addEventListener('mousedown', onMouseDown, {once: true});\n      return;\n    }\n\n    onStart({x: event.pageX, y: event.pageY, event});\n    onMouseMove(event);\n\n    element.ownerDocument.addEventListener('mousemove', onMouseMove);\n    element.ownerDocument.addEventListener('mouseup', onMouseUp, {once: true});\n  };\n\n  element.addEventListener('mousedown', onMouseDown, {once: true});\n\n  // * Touch\n  const onTouchMove = (event: TouchEvent) => {\n    event.preventDefault();\n    onMove({x: event.touches[0].clientX, y: event.touches[0].clientY, isTouch: true, event});\n  };\n\n  const onTouchEnd = (event: TouchEvent) => {\n    element.ownerDocument.removeEventListener('touchmove', onTouchMove);\n    element.addEventListener('touchstart', onTouchStart, {passive: false, once: true});\n    const touch = event.touches[0] || event.changedTouches[0];\n    onEnd?.({x: touch.clientX, y: touch.clientY, isTouch: true, event});\n  };\n\n  const onTouchStart = (event: TouchEvent) => {\n    onStart({x: event.touches[0].clientX, y: event.touches[0].clientY, isTouch: true, event});\n    onTouchMove(event);\n\n    element.ownerDocument.addEventListener('touchmove', onTouchMove, {passive: false});\n    element.ownerDocument.addEventListener('touchend', onTouchEnd, {passive: false, once: true});\n  };\n\n  element.addEventListener('touchstart', onTouchStart, {passive: false, once: true});\n\n  return () => {\n    element.removeEventListener('mousedown', onMouseDown);\n    element.ownerDocument.removeEventListener('mousemove', onMouseMove);\n    element.ownerDocument.removeEventListener('mouseup', onMouseUp);\n\n    element.removeEventListener('touchstart', onTouchStart);\n    element.ownerDocument.removeEventListener('touchmove', onTouchMove);\n    element.ownerDocument.removeEventListener('touchend', onTouchEnd);\n  };\n}\n","import attachGrabListeners, {GrabEvent} from '@helpers/dom/attachGrabListeners';\nimport clamp from '@helpers/number/clamp';\nimport safeAssign from '@helpers/object/safeAssign';\nimport I18n from '@lib/langPack';\n\nexport default class RangeSelector {\n  public container: HTMLDivElement;\n  protected filled: HTMLDivElement;\n  protected seek: HTMLInputElement;\n\n  public mousedown = false;\n  protected rect: DOMRect;\n  protected _removeListeners: () => void;\n\n  private events: Partial<{\n    // onMouseMove: ProgressLine['onMouseMove'],\n    onMouseDown: RangeSelector['onMouseDown'],\n    onMouseUp: RangeSelector['onMouseUp'],\n    onScrub: (value: number) => void\n  }> = {};\n\n  protected decimals: number;\n\n  protected step: number;\n  protected min: number;\n  protected max: number;\n  protected withTransition = false;\n  protected useTransform = false;\n  protected useProperty = false;\n  protected vertical = false;\n  protected offsetAxisValue = 0;\n\n  constructor(\n    options: {\n      step: RangeSelector['step'],\n      min?: RangeSelector['min'],\n      max?: RangeSelector['max'],\n      withTransition?: RangeSelector['withTransition'],\n      useTransform?: RangeSelector['useTransform'],\n      vertical?: RangeSelector['vertical'],\n      useProperty?: RangeSelector['useProperty'],\n      offsetAxisValue?: RangeSelector['offsetAxisValue']\n    },\n    value = 0\n  ) {\n    safeAssign(this, options);\n\n    this.container = document.createElement('div');\n    this.container.classList.add('progress-line');\n\n    // there is no sense in using transition with transform, because it is updating every frame\n    if(this.useTransform) {\n      this.container.classList.add('use-transform');\n    } else if(this.withTransition) {\n      this.container.classList.add('with-transition');\n    }\n\n    this.filled = document.createElement('div');\n    this.filled.classList.add('progress-line__filled');\n\n    const seek = this.seek = document.createElement('input');\n    seek.classList.add('progress-line__seek');\n    seek.type = 'range';\n    seek.step = '' + this.step;\n    this.setMinMax(this.min, this.max);\n    seek.value = '' + value;\n\n    if(value) {\n      this.setProgress(value);\n    }\n\n    const stepStr = '' + this.step;\n    const index = stepStr.indexOf('.');\n    this.decimals = index === -1 ? 0 : stepStr.length - index - 1;\n\n    this.container.append(this.filled, seek);\n  }\n\n  public setMinMax(min?: number, max?: number) {\n    this.min = min ?? (this.min ??= 0);\n    this.max = max ?? (this.max ??= 0);\n    this.seek.min = '' + min;\n    this.seek.max = '' + max;\n  }\n\n  get value() {\n    return +this.seek.value;\n  }\n\n  public setHandlers(events: RangeSelector['events']) {\n    this.events = events;\n  }\n\n  protected onMouseMove = (event: GrabEvent) => {\n    this.scrub(event);\n  };\n\n  protected onMouseDown = (event: GrabEvent) => {\n    this.rect = this.container.getBoundingClientRect();\n    this.mousedown = true;\n    this.scrub(event);\n    this.container.classList.add('is-focused');\n    this.events?.onMouseDown && this.events.onMouseDown(event);\n  };\n\n  protected onMouseUp = (event: GrabEvent) => {\n    this.mousedown = false;\n    this.container.classList.remove('is-focused');\n    this.events?.onMouseUp && this.events.onMouseUp(event);\n  };\n\n  public setListeners() {\n    this.seek.addEventListener('input', this.onInput);\n    this._removeListeners = attachGrabListeners(this.container, this.onMouseDown, this.onMouseMove, this.onMouseUp);\n  }\n\n  public onInput = () => {\n    const value = +this.seek.value;\n    this.setFilled(value);\n    this.events?.onScrub && this.events.onScrub(value);\n  };\n\n  public setProgress(value: number) {\n    this.seek.value = '' + value;\n    this.setFilled(+this.seek.value); // clamp\n  }\n\n  public addProgress(value: number) {\n    this.seek.value = '' + (+this.seek.value + value);\n    this.setFilled(+this.seek.value); // clamp\n  }\n\n  public setFilled(value: number) {\n    let percents = (value - this.min) / (this.max - this.min);\n    percents = clamp(percents, 0, 1);\n\n    // using scaleX and width even with vertical because it will be rotated\n    if(this.useTransform) {\n      this.filled.style.transform = `scaleX(${percents})`;\n    } else if(this.useProperty) {\n      this.container.style.setProperty('--progress', '' + percents);\n    } else {\n      this.filled.style.width = (percents * 100) + '%';\n    }\n  }\n\n  /**\n   * Make sure rect is set\n   * @returns value [0..1]\n   */\n  protected getValueByEvent(event: GrabEvent) {\n    let rectMax = this.vertical ? this.rect.height : this.rect.width;\n\n    if(this.offsetAxisValue) {\n      rectMax -= this.offsetAxisValue;\n    }\n\n    let offsetAxisValue = clamp(\n      this.vertical ?\n        -(event.y - this.rect.bottom) :\n        event.x - this.rect.left - this.offsetAxisValue / 2/*  - 30 */,\n      0,\n      rectMax\n    );\n\n    if(!this.vertical && I18n.getIsRTL()) {\n      offsetAxisValue = rectMax - offsetAxisValue;\n    }\n\n    return offsetAxisValue / rectMax;\n  }\n\n  protected scrub(event: GrabEvent, snapValue?: (value: number) => number) {\n    let value = this.min + (this.getValueByEvent(event) * (this.max - this.min));\n\n    if((value - this.min) < ((this.max - this.min) / 2)) {\n      value -= this.step / 10;\n    }\n\n    value = +value.toFixed(this.decimals);\n    value = clamp(value, this.min, this.max);\n    if(snapValue) value = snapValue(value);\n\n    // this.seek.value = '' + value;\n    // this.onInput();\n\n    this.setProgress(value);\n    this.events?.onScrub && this.events.onScrub(value);\n\n    return value;\n  }\n\n  public removeListeners() {\n    if(this._removeListeners) {\n      this._removeListeners();\n      this._removeListeners = null;\n    }\n\n    this.seek.removeEventListener('input', this.onInput);\n\n    this.events = {};\n  }\n}\n","import {animateSingle} from '@helpers/animation';\nimport {easeInOutSineApply} from '@helpers/easing/easeInOutSine';\nimport liteMode from '@helpers/liteMode';\nimport clamp from '@helpers/number/clamp';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {_i18n, i18n} from '@lib/langPack';\nimport Icon from '@components/icon';\nimport RangeSelector from '@components/rangeSelector';\n\ntype LimitLineProgressElements = {\n  from1: HTMLElement,\n  from2: HTMLElement,\n  to1: HTMLElement,\n  to2: HTMLElement\n};\n\nexport default class LimitLine {\n  public container: HTMLElement;\n  protected line: HTMLElement;\n  protected left: HTMLElement;\n  protected right: HTMLElement;\n  protected hint: HTMLElement;\n  protected hintNoStartEnd: boolean;\n  protected lastProgress: number;\n\n  constructor(options: {\n    limitPremium?: number,\n    limitFree?: number | string,\n    color?: string,\n    progress?: LimitLineProgressElements | true,\n    hint?: {\n      icon: Icon,\n      content?: HTMLElement | string,\n      noStartEnd?: boolean\n      renderInsideTrack?: boolean\n    },\n    slider?: (progress: number) => void\n    sliderValue?: number\n  }) {\n    let container: HTMLElement;\n    let hint: HTMLElement;\n\n    if(options.hint) {\n      container = document.createElement('div');\n      container.classList.add('limit-line-container');\n\n      hint = this.hint = document.createElement('div');\n      hint.classList.add('limit-line-hint', 'is-locked');\n      const i = Icon(options.hint.icon, 'limit-line-hint-icon');\n      hint.append(i);\n\n      if(options.hint.content) {\n        hint.append(options.hint.content);\n      }\n\n      this.hintNoStartEnd = options.hint.noStartEnd;\n      container.append(hint);\n    }\n\n    const limit = options.slider ? this.constructSlider(options) : this.constructLine(options, container);\n    this.container = container || limit;\n    if(container) {\n      if(limit) container.append(limit);\n    }\n  }\n\n  private constructLine(options: ConstructorParameters<typeof LimitLine>[0], container?: HTMLElement) {\n    const limit = this.line = document.createElement('div');\n    limit.classList.add('limit-line');\n\n    if(!container) {\n      limit.classList.add('is-alone');\n    }\n\n    const left = this.left = document.createElement('div');\n    left.classList.add('limit-line-part', 'limit-line-empty');\n\n    const right = this.right = document.createElement('div');\n    right.classList.add('limit-line-part', 'limit-line-filled');\n\n    if(options.progress) {\n      // const rightContainer = document.createElement('div');\n      // rightContainer.classList.add('limit-line-absolute-container');\n      // rightContainer.append(right);\n      right.classList.add('limit-line-absolute');\n      if(options.progress !== true) {\n        this.setProgressElements(options.progress);\n      }\n    }\n\n    if(options.limitPremium !== undefined) {\n      if(options.limitFree === undefined) {\n        _i18n(left, 'LimitFree');\n      } else {\n        left.append(i18n('LimitFree'), '' + options.limitFree);\n      }\n\n      if(options.color !== undefined) right.style.setProperty('--limit-background', options.color);\n      limit.append(right);\n      right.append(i18n('LimitPremium'), '' + options.limitPremium);\n    }\n\n    limit.append(left, right);\n    return limit;\n  }\n\n  private constructSlider(options: ConstructorParameters<typeof LimitLine>[0]) {\n    const range = new RangeSelector({\n      step: 0.0001,\n      min: 0,\n      max: 1,\n      useProperty: true,\n      offsetAxisValue: 30\n    }, options.sliderValue ?? 0);\n    range.setListeners();\n    range.setHandlers({\n      onScrub: options.slider\n    });\n\n    range.container.classList.add('limit-line-slider');\n\n    return this.line = range.container;\n  }\n\n  public setProgressElements(progress: LimitLineProgressElements) {\n    this.left.replaceChildren(progress.from1, progress.to1);\n    this.right.replaceChildren(progress.from2, progress.to2);\n  }\n\n  // [0..1]\n  public setProgress(\n    progress: number,\n    hintContent?: HTMLElement | string,\n    elements?: LimitLineProgressElements\n  ) {\n    const lastProgress = this.lastProgress;\n    if(this.hint) {\n      this.hint.classList.remove('is-locked');\n      if(hintContent) {\n        this.hint.replaceChildren(this.hint.firstElementChild, hintContent);\n      }\n    }\n\n    const set = (value: number) => {\n      this.container.style.setProperty('--limit-progress', value * 100 + '%');\n      if(this.hint) {\n        const t = 0.1;\n        if(this.hintNoStartEnd) {\n          this.hint.style.setProperty('--limit-progress', clamp(value, t, 1 - t) * 100 + '%')\n        } else {\n          this.hint.classList.toggle('is-start', value <= t);\n          this.hint.classList.toggle('is-end', value >= (1 - t));\n        }\n      }\n    };\n\n    if(lastProgress !== undefined && liteMode.isAvailable('animations')) {\n      const duration = 200;\n      const startTime = Date.now();\n      const toAdd = progress - this.lastProgress;\n      animateSingle(() => {\n        const v = (Date.now() - startTime) / duration;\n        const value = lastProgress + easeInOutSineApply(toAdd * v, 1);\n        set(value);\n\n        return v < 1;\n      }, this.container);\n    } else {\n      set(progress);\n    }\n\n    if(elements) {\n      this.setProgressElements(elements);\n    }\n\n    this.lastProgress = progress;\n  }\n\n  public setHintActive = () => {\n    this.hint.classList.add('active');\n  };\n\n  public _setHintActive() {\n    if(liteMode.isAvailable('animations')) {\n      doubleRaf().then(this.setHintActive);\n    } else {\n      this.setHintActive();\n    }\n  }\n}\n","import {LangPackKey} from '@lib/langPack';\nimport {ApiLimitType} from '@appManagers/apiManagerMethods';\nimport rootScope from '@lib/rootScope';\nimport PopupPeer from '@components/popups/peer';\nimport LimitLine from '@components/limit';\nimport PopupPremium from '@components/popups/premium';\n\nconst a: {[type in ApiLimitType]?: {\n  title: LangPackKey,\n  description: LangPackKey,\n  descriptionPremium: LangPackKey,\n  descriptionLocked: LangPackKey,\n  icon: Icon\n}} = {\n  pin: {\n    title: 'LimitReached',\n    description: 'LimitReachedPinDialogs',\n    descriptionPremium: 'LimitReachedPinDialogsPremium',\n    descriptionLocked: 'LimitReachedPinDialogsLocked',\n    icon: 'limit_pin_filled'\n  },\n  folders: {\n    title: 'LimitReached',\n    description: 'LimitReachedFolders',\n    descriptionPremium: 'LimitReachedFoldersPremium',\n    descriptionLocked: 'LimitReachedFoldersLocked',\n    icon: 'limit_folders'\n  },\n  folderPeers: {\n    title: 'LimitReached',\n    description: 'LimitReachedChatInFolders',\n    descriptionPremium: 'LimitReachedChatInFoldersPremium',\n    descriptionLocked: 'LimitReachedChatInFoldersLocked',\n    icon: 'limit_folders'\n  },\n  chatlistInvites: {\n    title: 'LimitReached',\n    description: 'LimitReachedSharedFolderInvites',\n    descriptionPremium: 'LimitReachedSharedFolderInvitesPremium',\n    descriptionLocked: 'LimitReachedSharedFolderInvitesLocked',\n    icon: 'limit_link'\n  },\n  savedPin: {\n    title: 'LimitReached',\n    description: 'LimitReachedPinDialogs',\n    descriptionPremium: 'LimitReachedPinDialogsPremium',\n    descriptionLocked: 'LimitReachedPinDialogsLocked',\n    icon: 'limit_pin_filled'\n  },\n  channels: {\n    title: 'LimitReached',\n    description: 'LimitReachedCommunities',\n    descriptionPremium: 'LimitReachedCommunitiesPremium',\n    descriptionLocked: 'LimitReachedCommunitiesLocked',\n    icon: 'limit_chat_filled'\n  }\n};\n\nclass P extends PopupPeer {\n  constructor(options: {\n    isPremium: boolean,\n    limit: number,\n    limitPremium: number,\n    feature?: PremiumPromoFeatureType,\n    popupRef?: (popup: P) => any,\n    strings: typeof a[keyof typeof a]\n  }) {\n    super('popup-limit', {\n      buttons: options.isPremium === undefined ? [{\n        langKey: 'LimitReached.Ok',\n        isCancel: true\n      }] : (options.isPremium ? [{\n        langKey: 'OK',\n        isCancel: true\n      }] : [{\n        langKey: 'IncreaseLimit',\n        callback: () => {\n          PopupPremium.show({feature: options.feature});\n        },\n        iconRight: 'premium_double_filled'\n      }, {\n        langKey: 'Cancel',\n        isCancel: true\n      }]),\n      descriptionLangKey: options.isPremium === undefined ? options.strings.descriptionLocked : (options.isPremium ? options.strings.descriptionPremium : options.strings.description),\n      descriptionLangArgs: options.isPremium ? [options.limitPremium] : [options.limit, options.limitPremium],\n      titleLangKey: options.strings.title,\n      body: !!options.popupRef\n    });\n\n    const limit = new LimitLine({\n      limitPremium: options.limitPremium,\n      hint: {\n        icon: options.strings.icon,\n        content: '' + (options.isPremium ? options.limitPremium : options.limit)\n      }\n    });\n\n    if(options.isPremium !== undefined) {\n      limit.setProgress(options.isPremium ? 1 : 0.5);\n    } else {\n      const limitLine = limit.container.querySelector('.limit-line');\n      limitLine?.remove();\n    }\n\n    this.description.before(limit.container);\n\n    // if(options.isPremium === false) {\n    //   this.buttons.pop().element.remove();\n    // }\n\n    limit._setHintActive();\n  }\n}\n\nexport default async function showLimitPopup(\n  type: keyof typeof a,\n  popupRef?: ConstructorParameters<typeof P>[0]['popupRef']\n) {\n  // const featureMap: {[type in keyof typeof a]?: PremiumPromoFeatureType} = {\n  //   folders: 'double_limits',\n  //   pin: 'double_limits',\n  //   chatlistInvites: 'double_limits'\n  // };\n  const feature: PremiumPromoFeatureType = 'double_limits';\n\n  const [appConfig, limit, limitPremium] = await Promise.all([\n    rootScope.managers.apiManager.getAppConfig(),\n    ...[false, true].map((v) => rootScope.managers.apiManager.getLimit(type, v))\n  ]);\n  const isLocked = appConfig.premium_purchase_blocked;\n  const popup = new P({\n    isPremium: isLocked ? undefined : rootScope.premium,\n    limit,\n    limitPremium,\n    // feature: featureMap[type]\n    feature,\n    popupRef,\n    strings: a[type]\n  });\n\n  if(popupRef) {\n    popupRef(popup);\n  } else {\n    popup.show();\n  }\n}\n","import EventListenerBase, {EventListenerListeners} from '@helpers/eventListenerBase';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport {AppManagers} from '@lib/managers';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport ButtonIcon from '@components/buttonIcon';\nimport Scrollable from '@components/scrollable';\nimport SidebarSlider from '@components/slider';\n\nexport interface SliderSuperTabConstructable<T extends SliderSuperTab = any> {\n  new(slider: SidebarSlider, destroyable: boolean): T;\n}\n\nexport interface SliderSuperTabEventableConstructable {\n  new(slider: SidebarSlider, destroyable: boolean): SliderSuperTabEventable;\n}\n\nexport default class SliderSuperTab {\n  public static getInitArgs?(...args: any[]): any;\n  public static noSame?: boolean;\n\n  public container: HTMLElement;\n\n  public header: HTMLElement;\n  public closeBtn: HTMLElement;\n  public title: HTMLElement;\n\n  public content: HTMLElement;\n  public scrollable: Scrollable;\n\n  public slider: SidebarSlider;\n  public destroyable: boolean;\n  public listenerSetter: ListenerSetter;\n\n  public managers: AppManagers;\n  public middlewareHelper: MiddlewareHelper;\n\n  public isConfirmationNeededOnClose: () => void | boolean | Promise<any>; // should return boolean instantly or `Promise` from `confirmationPopup`\n\n  /**\n   * Resolves once the tab has finished sliding in. `open()` awaits the render,\n   * the transition runs after it — the slider resolves this when it is over.\n   */\n  public shown: CancellablePromise<void> = deferredPromise<void>();\n\n  /** A reopened tab slides in again, so what waits on `shown` has to wait anew. */\n  public resetShown() {\n    if(this.shown.isFulfilled) {\n      this.shown = deferredPromise<void>();\n    }\n  }\n\n  constructor(slider: SidebarSlider, destroyable?: boolean) {\n    this._constructor(slider, destroyable);\n  }\n\n  public _constructor(slider: SidebarSlider, destroyable = true): any {\n    this.slider = slider;\n    this.middlewareHelper = slider ? slider.getMiddleware().create() : getMiddleware();\n    this.destroyable = destroyable;\n\n    this.container = document.createElement('div');\n    this.container.classList.add('tabs-tab', 'sidebar-slider-item');\n\n    // * Header\n    this.header = document.createElement('div');\n    this.header.classList.add('sidebar-header');\n\n    this.closeBtn = ButtonIcon('left sidebar-close-button', {noRipple: true});\n    this.title = document.createElement('div');\n    this.title.classList.add('sidebar-header__title');\n    this.header.append(this.closeBtn, this.title);\n\n    // * Content\n    this.content = document.createElement('div');\n    this.content.classList.add('sidebar-content');\n\n    this.scrollable = new Scrollable(this.content, undefined, undefined, true);\n    this.scrollable.attachBorderListeners(this.container);\n\n    this.container.append(this.header, this.content);\n\n    this.slider?.addTab(this);\n\n    this.listenerSetter = new ListenerSetter();\n  }\n\n  public close() {\n    return this.slider.closeTab(this);\n  }\n\n  public async open(...args: Parameters<typeof this['init']>) {\n    if(this.init) {\n      try {\n        const result = this.init(...args);\n        this.init = null;\n\n        if(result instanceof Promise) {\n          await result;\n        }\n      } catch(err) {\n        console.error('open tab error', err);\n      }\n    }\n\n    this.slider.selectTab(this);\n  }\n\n  public init(...args: any[]): Promise<any> | any {\n\n  }\n\n  protected onOpen() {}\n  protected onOpenAfterTimeout() {}\n  protected onClose() {}\n\n  protected onCloseAfterTimeout() {\n    if(this.destroyable) { // ! WARNING, пока что это будет работать только с самой последней внутренней вкладкой !\n      this.slider?.deleteTab(this);\n      this.container.remove();\n      this.scrollable.destroy();\n      this.listenerSetter?.removeAll();\n      this.middlewareHelper?.destroy();\n    }\n  }\n\n  protected setTitle(key: LangPackKey) {\n    this.title.replaceChildren(i18n(key));\n  }\n}\n\nexport class SliderSuperTabEventable<T extends EventListenerListeners = {}> extends SliderSuperTab {\n  public eventListener: EventListenerBase<{\n    destroy: () => void | Promise<any>,\n    destroyAfter: (promise: Promise<void>) => void,\n    close: () => void\n  } & T>;\n\n  constructor(slider: SidebarSlider) {\n    super(slider);\n    this.eventListener = new EventListenerBase();\n  }\n\n  onClose() {\n    // @ts-ignore\n    this.eventListener.dispatchEvent('close');\n  }\n\n  onCloseAfterTimeout() {\n    // @ts-ignore\n    const results = this.eventListener.dispatchResultableEvent('destroy');\n    // @ts-ignore\n    this.eventListener.dispatchEvent('destroyAfter', Promise.all(results).then(noop, noop));\n    this.eventListener.cleanup();\n    return super.onCloseAfterTimeout();\n  }\n}\n\n/* // @ts-ignore\ninterface SliderSuperEventsTab extends SliderSuperTab, EventListenerBase<{}> {\n  superConstructor: (...args: any[]) => any;\n}\nclass SliderSuperEventsTab implements SliderSuperEventsTab {\n  constructor(slider: SidebarSlider) {\n    this.superConstructor([slider, true]);\n  }\n}\napplyMixins(SliderSuperEventsTab, [SliderSuperTab, EventListenerBase]);\n\n(window as any).lol = SliderSuperEventsTab\n\nexport {SliderSuperEventsTab}; */\n","import {horizontalMenu} from '@components/horizontalMenu';\nimport TransitionSlider from '@components/transition';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport SliderSuperTab, {SliderSuperTabConstructable} from '@components/sliderTab';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport {MaybePromise} from '@types';\n\nconst TRANSITION_TIME = 250;\n\nexport {SliderSuperTab};\n\nexport type SidebarSliderOptions = {\n  sidebarEl: SidebarSlider['sidebarEl'],\n  tabs?: SidebarSlider['tabs'],\n  canHideFirst?: SidebarSlider['canHideFirst'],\n  navigationType: SidebarSlider['navigationType']\n}\n\nexport default class SidebarSlider {\n  protected _selectTab: ReturnType<typeof horizontalMenu>;\n  protected historyTabIds: (number | SliderSuperTab)[] = []; // * key is any, since right sidebar is ugly nowz\n  protected tabsContainer: HTMLElement;\n  public sidebarEl: HTMLElement;\n  protected tabs: Map<any, SliderSuperTab>; // * key is any, since right sidebar is ugly now\n  private canHideFirst = false;\n  private navigationType: NavigationItem['type'];\n  protected managers: AppManagers;\n  protected middlewareHelper: MiddlewareHelper;\n  public onOpenTab: () => MaybePromise<void>;\n  public onTabsCountChange?: () => void;\n\n  constructor(options: SidebarSliderOptions) {\n    safeAssign(this, options);\n\n    this.tabs ??= new Map();\n\n    this.tabsContainer = this.sidebarEl.querySelector('.sidebar-slider');\n    this._selectTab = TransitionSlider({\n      content: this.tabsContainer,\n      type: 'navigation',\n      transitionTime: TRANSITION_TIME\n    });\n    if(!this.canHideFirst) {\n      this._selectTab(0);\n    }\n\n    this.middlewareHelper = getMiddleware();\n\n    // Array.from(this.sidebarEl.querySelectorAll('.sidebar-close-button') as any as HTMLElement[]).forEach((el) => {\n    //   attachClickEvent(el, this.onCloseBtnClick);\n    // });\n  }\n\n  public getMiddleware() {\n    return this.middlewareHelper.get();\n  }\n\n  public onCloseBtnClick = () => {\n    const item = appNavigationController.findItemByType(this.navigationType);\n    if(item) {\n      appNavigationController.back(this.navigationType);\n      this.onTabsCountChange?.();\n    } else if(this.historyTabIds.length) {\n      this.closeTab(this.historyTabIds[this.historyTabIds.length - 1]);\n    }\n    // this.closeTab();\n  };\n\n  public closeTab = (id?: number | SliderSuperTab, animate?: boolean, isNavigation?: boolean) => {\n    if(id !== undefined && this.historyTabIds[this.historyTabIds.length - 1] !== id) {\n      this.removeTabFromHistory(id);\n      return false;\n    }\n\n    // console.log('sidebar-close-button click:', this.historyTabIDs);\n    const closingId = this.historyTabIds.pop(); // pop current\n    this.onCloseTab(closingId, animate, isNavigation);\n\n    const tab = this.historyTabIds[this.historyTabIds.length - 1];\n    this._selectTab(tab !== undefined ? (tab instanceof SliderSuperTab ? tab.container : tab) : (this.canHideFirst ? -1 : 0), animate);\n    return true;\n  };\n\n  protected pushNavigationItem(tab: SliderSuperTab) {\n    const navigationItem: NavigationItem = {\n      type: this.navigationType,\n      onPop: (canAnimate) => {\n        if(tab.isConfirmationNeededOnClose) {\n          const result = tab.isConfirmationNeededOnClose();\n          if(result) {\n            Promise.resolve(result).then(() => {\n              appNavigationController.removeItem(navigationItem);\n              this.onTabsCountChange?.();\n\n              this.closeTab(undefined, undefined, true);\n            }, () => {});\n\n            return false;\n          }\n        }\n\n        this.closeTab(undefined, canAnimate, true);\n        this.onTabsCountChange?.();\n        return true;\n      }\n    };\n\n    // if(!this.canHideFirst || this.historyTabIds.length) {\n    appNavigationController.pushItem(navigationItem);\n    this.onTabsCountChange?.();\n    // }\n  }\n\n  public async selectTab(id: number | SliderSuperTab) {\n    /* if(id instanceof SliderSuperTab) {\n      id = id.id;\n    } */\n\n    if(this.historyTabIds[this.historyTabIds.length - 1] === id) {\n      return false;\n    }\n\n    const tab: SliderSuperTab = id instanceof SliderSuperTab ? id : this.tabs.get(id);\n    this.onOpenTab && await this.onOpenTab();\n\n    if(tab) {\n      // @ts-ignore\n      tab.onOpen?.();\n\n      setTimeout(() => {\n        // @ts-ignore\n        tab.onOpenAfterTimeout?.();\n        tab.shown.resolve();\n      }, TRANSITION_TIME);\n    }\n\n    this.pushNavigationItem(tab);\n\n    this.historyTabIds.push(id);\n    this._selectTab(id instanceof SliderSuperTab ? id.container : id);\n    return true;\n  }\n\n  public removeTabFromHistory(id: number | SliderSuperTab) {\n    indexOfAndSplice(this.historyTabIds, id);\n    this.onCloseTab(id, undefined);\n  }\n\n  public closeAllTabs() {\n    const hasTabs = this.hasTabsInNavigation();\n    for(let i = this.historyTabIds.length - 1; i >= 0; --i) {\n      const tabId = this.historyTabIds[i];\n      const tab = tabId instanceof SliderSuperTab ? tabId : this.tabs.get(tabId);\n      tab.close();\n    }\n    return hasTabs;\n  }\n\n  private async closeTabsNaturallyUntil(\n    target?: SliderSuperTab\n  ): Promise<boolean> {\n    while(\n      this.historyTabIds.length &&\n      this.historyTabIds[this.historyTabIds.length - 1] !== target\n    ) {\n      const tabId = this.historyTabIds[this.historyTabIds.length - 1];\n      const tab = tabId instanceof SliderSuperTab ? tabId : this.tabs.get(tabId);\n\n      const confirmation = tab?.isConfirmationNeededOnClose?.();\n      if(confirmation) {\n        const confirmed = await Promise.resolve(confirmation).then(() => true, () => false);\n        if(!confirmed) {\n          return false;\n        }\n\n        // The stack may have shifted while the popup was open; re-evaluate.\n        if(this.historyTabIds[this.historyTabIds.length - 1] !== tabId) {\n          continue;\n        }\n      }\n\n      this.closeTab(tabId, undefined, false);\n    }\n\n    return !target || this.historyTabIds.includes(target);\n  }\n\n  // Close the open tabs from the top of the stack down, the same way the back\n  // arrow does — each tab that needs confirmation (isConfirmationNeededOnClose)\n  // gets to show its popup. If the user declines (the confirmation rejects),\n  // stop and return false; the declined tab and everything beneath it stay open.\n  // Unlike closeAllTabs, which force-closes every tab and ignores confirmation.\n  public closeAllTabsNaturally(): Promise<boolean> {\n    return this.closeTabsNaturallyUntil();\n  }\n\n  public closeTabsUntilTab(target: SliderSuperTab): Promise<boolean> {\n    if(!this.historyTabIds.includes(target)) {\n      return Promise.resolve(false);\n    }\n\n    return this.closeTabsNaturallyUntil(target);\n  }\n\n  public sliceTabsUntilTab(tabConstructor: SliderSuperTabConstructable, preserveTab: SliderSuperTab) {\n    for(let i = this.historyTabIds.length - 1; i >= 0; --i) {\n      const tab = this.historyTabIds[i];\n      if(tab === preserveTab) continue;\n      else if(tab instanceof tabConstructor) {\n        break;\n      }\n\n      this.removeTabFromHistory(tab);\n      // appNavigationController.removeByType(this.navigationType, true);\n    }\n  }\n\n  public getTab<T extends SliderSuperTab>(tabConstructor: SliderSuperTabConstructable<T>) {\n    return this.historyTabIds.find((t) => t instanceof tabConstructor) as T;\n  }\n\n  public getHistory() {\n    return this.historyTabIds;\n  }\n\n  public isTabExists(tabConstructor: SliderSuperTabConstructable) {\n    return !!this.getTab(tabConstructor);\n  }\n\n  protected onCloseTab(id: number | SliderSuperTab, animate: boolean, isNavigation?: boolean) {\n    if(!isNavigation) {\n      appNavigationController.removeByType(this.navigationType, true);\n      this.onTabsCountChange?.();\n    }\n\n    const tab: SliderSuperTab = id instanceof SliderSuperTab ? id : this.tabs.get(id);\n    if(tab) {\n      tab.resetShown();\n\n      try {\n        // @ts-ignore\n        tab.onClose?.();\n      } catch(err) {\n        console.error('tab onClose error', tab);\n      }\n\n      // @ts-ignore\n      if(tab.onCloseAfterTimeout) {\n        setTimeout(() => {\n          // @ts-ignore\n          tab.onCloseAfterTimeout();\n        }, TRANSITION_TIME + 30);\n      }\n    }\n  }\n\n  public addTab(tab: SliderSuperTab) {\n    if(!tab.container.parentElement) {\n      this.tabsContainer.append(tab.container);\n\n      if(tab.closeBtn) {\n        tab.closeBtn.addEventListener('click', this.onCloseBtnClick);\n      }\n    }\n  }\n\n  public deleteTab(tab: SliderSuperTab) {\n    this.tabs.delete(tab);\n  }\n\n  public createTab<T extends SliderSuperTab>(\n    ctor: SliderSuperTabConstructable<T>,\n    destroyable = true,\n    doNotAppend?: boolean\n  ) {\n    if(\n      (ctor as any).noSame &&\n      this.historyTabIds[this.historyTabIds.length - 1] instanceof ctor\n    ) {\n      return this.historyTabIds[this.historyTabIds.length - 1] as T;\n    }\n\n    const tab = new ctor(doNotAppend ? undefined : this, destroyable);\n    tab.managers = this.managers;\n    return tab;\n  }\n\n  public hasTabsInNavigation() {\n    return !!appNavigationController.findItemByType(this.navigationType);\n  }\n}\n","import ListLoader from '@helpers/listLoader';\n\nexport default class EmptyListLoader<T> extends ListLoader<T, any> {\n  constructor() {\n    super({\n      loadMore: () => {\n        return Promise.resolve({count: 0, items: []});\n      }\n    });\n\n    this.loadedAllDown = true;\n    this.loadedAllUp = true;\n  }\n}\n","import {InputDocument} from '@layer';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport getDocumentInput from '@appManagers/utils/docs/getDocumentInput';\nimport ListenerSetter from './listenerSetter';\n\n/**\n * Tracks how much of a music track the user actually listened to and reports it via\n * `messages.reportMusicListen`. The listened duration is the total of the UNIQUE track positions\n * the user covered (re-listening the same segment isn't counted twice, and seek jumps are excluded)\n * — matching the Android client.\n *\n * Driven by {@link AppMediaPlaybackController}: call {@link onPlay} on each `play` event (passing the\n * controller's playing details) and {@link finish} on `stop`. A session begins when a music track\n * starts and is finalized — and reported, when long enough — on track switch, stop, or a pause\n * longer than {@link MUSIC_LISTEN_PAUSE_LIMIT}.\n */\n\n// A pause longer than this ends the current listen; resuming afterwards counts as a new one.\nconst MUSIC_LISTEN_PAUSE_LIMIT = 60e3;\n// The server ignores reports shorter than this many seconds, so we don't bother sending them.\nconst MUSIC_LISTEN_MIN_DURATION = 3;\n\ntype MusicListenSession = {\n  inputDoc: InputDocument.inputDocument,\n  media: HTMLMediaElement,\n  listeners: ListenerSetter,\n  ranges: {from: number, to: number}[],\n  rangeStart: number,\n  lastPosition: number\n};\n\ntype PlayDetails = {\n  doc?: MyDocument,\n  media?: HTMLMediaElement\n};\n\nexport default class MusicListenTracker {\n  // `ranges` holds the merged covered intervals (seconds), `rangeStart` is the open interval's start\n  // (-1 when none), `lastPosition` is the last observed playback position (used to close ranges\n  // across seeks/stop).\n  private session: MusicListenSession;\n  private pauseTimeout: number;\n\n  constructor(private onReport: (inputDoc: InputDocument.inputDocument, listenedDuration: number) => void) {}\n\n  public onPlay(details: PlayDetails) {\n    // Only music is tracked — switching away from music to a voice/round/video finalizes any session.\n    if(details?.doc?.type !== 'audio') {\n      this.finish();\n      return;\n    }\n\n    const inputDoc = getDocumentInput(details.doc) as InputDocument.inputDocument;\n    const session = this.session;\n    if(session && session.inputDoc.id === inputDoc.id && session.media === details.media) {\n      // Same track still playing (e.g. resume) — the media-level listeners handle it.\n      return;\n    }\n\n    // A different track started — finalize the previous listen and begin a fresh one.\n    this.finish();\n    this.startSession(inputDoc, details.media);\n  }\n\n  // Settles the current listen and reports it (when long enough), then clears it. Called when a\n  // track ends, the user switches tracks, the player is closed, or a pause lasts longer than\n  // MUSIC_LISTEN_PAUSE_LIMIT.\n  public finish() {\n    this.clearPauseTimeout();\n\n    const session = this.session;\n    if(!session) {\n      return;\n    }\n\n    this.session = undefined;\n    session.listeners.removeAll();\n\n    // Close a still-open interval at the last known position. `media.currentTime` is unreliable\n    // here — `stop()` resets it to 0 before dispatching the event — so use `lastPosition`.\n    this.closeRange(session, session.lastPosition);\n\n    let total = 0;\n    for(const range of session.ranges) {\n      total += range.to - range.from;\n    }\n\n    const listenedDuration = Math.floor(total);\n    if(listenedDuration < MUSIC_LISTEN_MIN_DURATION) {\n      return;\n    }\n\n    this.onReport(session.inputDoc, listenedDuration);\n  }\n\n  private startSession(inputDoc: InputDocument.inputDocument, media: HTMLMediaElement) {\n    const listeners = new ListenerSetter();\n    const session: MusicListenSession = this.session = {\n      inputDoc,\n      media,\n      listeners,\n      ranges: [],\n      rangeStart: -1,\n      lastPosition: media.currentTime\n    };\n\n    // The media is already playing when the controller's `play` event reaches us, so open the\n    // first interval right away; later play/pause/seek transitions adjust it.\n    if(!media.paused) {\n      this.openRange(media.currentTime);\n    }\n\n    listeners.add(media)('timeupdate', () => {\n      session.lastPosition = media.currentTime;\n    });\n\n    listeners.add(media)('play', () => {\n      this.clearPauseTimeout();\n      this.openRange(media.currentTime);\n    });\n\n    listeners.add(media)('pause', () => {\n      // `stop()` resets currentTime to 0 before this async event fires, so fall back to the last\n      // tracked position; on a genuine user pause currentTime is accurate and slightly ahead.\n      this.closeRange(session, Math.max(session.lastPosition, media.currentTime));\n      this.clearPauseTimeout();\n      this.pauseTimeout = window.setTimeout(() => {\n        this.pauseTimeout = undefined;\n        this.finish();\n      }, MUSIC_LISTEN_PAUSE_LIMIT);\n    });\n\n    listeners.add(media)('seeking', () => {\n      // Close the interval at the pre-seek position, then reopen at the new one if still playing.\n      this.closeRange(session, session.lastPosition);\n      this.clearPauseTimeout();\n      if(!media.paused) {\n        this.openRange(media.currentTime);\n      }\n      session.lastPosition = media.currentTime;\n    });\n  }\n\n  // Opens a covered interval at the given position (no-op if one is already open).\n  private openRange(position: number) {\n    const session = this.session;\n    if(session && session.rangeStart < 0) {\n      session.rangeStart = position;\n    }\n  }\n\n  // Closes the open interval at the given position and merges it into the covered ranges.\n  private closeRange(session: MusicListenSession, position: number) {\n    if(session.rangeStart < 0) {\n      return;\n    }\n\n    const from = session.rangeStart;\n    session.rangeStart = -1;\n    if(position <= from) {\n      return;\n    }\n\n    // Insert sorted by `from`, then merge any overlapping/touching neighbours.\n    const ranges = session.ranges;\n    let idx = 0;\n    while(idx < ranges.length && ranges[idx].from <= from) idx++;\n    ranges.splice(idx, 0, {from, to: position});\n    for(let i = Math.max(0, idx - 1); i < ranges.length - 1;) {\n      const cur = ranges[i], next = ranges[i + 1];\n      if(cur.to >= next.from) {\n        cur.to = Math.max(cur.to, next.to);\n        ranges.splice(i + 1, 1);\n      } else {\n        i++;\n      }\n    }\n  }\n\n  private clearPauseTimeout() {\n    if(this.pauseTimeout !== undefined) {\n      clearTimeout(this.pauseTimeout);\n      this.pauseTimeout = undefined;\n    }\n  }\n}\n","import {MessageExtendedMedia, Photo, PhotoSize} from '@layer';\n\nexport default function generatePhotoForExtendedMediaPreview(media: MessageExtendedMedia.messageExtendedMediaPreview): Photo.photo {\n  let thumb = media.thumb as PhotoSize.photoStrippedSize;\n  if(thumb) {\n    thumb.w = media.w;\n    thumb.h = media.h;\n  } else {\n    thumb = {\n      _: 'photoStrippedSize',\n      bytes: new Uint8Array([1, 24, 30, 197, 162, 138, 40, 0, 162, 138, 40, 0, 162, 138, 40, 0, 162, 138, 40, 3]),\n      type: 'i',\n      w: 1,\n      h: 1\n    };\n  }\n\n  return {\n    _: 'photo',\n    access_hash: '',\n    pFlags: {},\n    date: 0,\n    dc_id: 0,\n    file_reference: [],\n    id: 0,\n    sizes: [thumb]\n  };\n}\n","import toArray from '@helpers/array/toArray';\nimport {Document, Game, Message, MessageAction, MessageExtendedMedia, MessageMedia, Photo, StoryItem, WebPage} from '@layer';\nimport generatePhotoForExtendedMediaPreview from '@appManagers/utils/photos/generatePhotoForExtendedMediaPreview';\n\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner: true, index?: number): Photo.photo | Document.document;\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner?: false, index?: number): Photo.photo | Document.document | Game.game | WebPage.webPage;\nexport default function getMediaFromMessage(message: Message | StoryItem.storyItem, onlyInner = false, index?: number): Photo.photo | Document.document | Game.game | WebPage.webPage {\n  if(!message) return;\n\n  let media: any;\n  if((message as Message.messageService).action) {\n    media = ((message as Message.messageService).action as MessageAction.messageActionChannelEditPhoto).photo;\n  } else if((message as Message.message).media) {\n    let messageMedia = (message as Message.message).media;\n    const extendedMedia = (messageMedia as MessageMedia.messageMediaInvoice | MessageMedia.messageMediaPaidMedia).extended_media;\n    if((messageMedia as MessageMedia.messageMediaWebPage).webpage) {\n      messageMedia = (messageMedia as MessageMedia.messageMediaWebPage).webpage as any as MessageMedia;\n    } else if(extendedMedia) {\n      const media = toArray(extendedMedia)[index ?? 0];\n      messageMedia = (media as MessageExtendedMedia.messageExtendedMedia).media;\n      if(!messageMedia) {\n        return generatePhotoForExtendedMediaPreview(media as MessageExtendedMedia.messageExtendedMediaPreview);\n      }\n    }\n\n    media = /* (messageMedia as MessageMedia.messageMediaDocument).alt_document || */\n      (messageMedia as MessageMedia.messageMediaDocument).document ||\n      (messageMedia as MessageMedia.messageMediaPhoto).photo ||\n      (onlyInner ? undefined : (messageMedia as MessageMedia.messageMediaGame).game || messageMedia);\n  }\n\n  return media as any;\n}\n","import {pinObjectURL} from '@helpers/objectUrl';\nimport {isObjectURL} from '@helpers/objectUrlUtils';\n\n// * MediaSession artwork has no DOM element and the OS fetches it lazily, so\n// * its blob URLs must stay pinned for as long as the metadata is current.\nexport default function createMediaMetadataObjectURLPins(\n  setMetadata = (metadata: MediaMetadata | null) => {\n    navigator.mediaSession.metadata = metadata;\n  }\n) {\n  let pins = new Map<string, () => void>();\n\n  return (metadata: MediaMetadata | null) => {\n    const nextPins = new Map<string, () => void>();\n    const createdPins: Array<() => void> = [];\n    for(const {src} of metadata?.artwork ?? []) {\n      if(isObjectURL(src) && !nextPins.has(src)) {\n        let unpin = pins.get(src);\n        if(!unpin) {\n          createdPins.push(unpin = pinObjectURL(src));\n        }\n        nextPins.set(src, unpin);\n      }\n    }\n\n    try {\n      setMetadata(metadata);\n    } catch(error) {\n      createdPins.forEach((unpin) => unpin());\n      throw error;\n    }\n\n    for(const [url, unpin] of pins) {\n      if(!nextPins.has(url)) {\n        unpin();\n      }\n    }\n    pins = nextPins;\n  };\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type {SearchSuperContext} from '@components/appSearchSuper';\nimport rootScope from '@lib/rootScope';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {IS_APPLE, IS_SAFARI} from '@environment/userAgent';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {getAppWindow} from '@helpers/appWindow';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\nimport {Document, DocumentAttribute, Message, PhotoSize} from '@layer';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport I18n from '@lib/langPack';\nimport SearchListLoader from '@helpers/searchListLoader';\nimport copy from '@helpers/object/copy';\nimport deepEqual from '@helpers/object/deepEqual';\nimport clamp from '@helpers/number/clamp';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport MusicListenTracker from '@helpers/musicListenTracker';\nimport {AppManagers} from '@lib/managers';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport animationIntersector from '@components/animationIntersector';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport {pinObjectURL} from '@helpers/objectUrl';\nimport clearMediaElementSource from '@helpers/dom/clearMediaElementSource';\nimport createMediaMetadataObjectURLPins from '@helpers/mediaMetadataObjectURLPins';\nimport type {Middleware} from '@helpers/middleware';\nimport ListLoader, {ListLoaderOptions} from '../helpers/listLoader';\n\n// TODO: Safari: проверить стрим, включить его и сразу попробовать включить видео или другую песню\n// TODO: Safari: попробовать замаскировать подгрузку последнего чанка\n// TODO: Safari: пофиксить момент, когда заканчивается песня и пытаешься включить её заново - прогресс сразу в конце\n\nexport type MediaItem = {mid: number, peerId: PeerId};\n\nconst SHOULD_USE_SAFARI_FIX = (() => {\n  try {\n    return IS_SAFARI && +navigator.userAgent.match(/ Version\\/(\\d+)/)[1] < 14;\n  } catch(err) {\n    return false;\n  }\n})();\n\nconst SEEK_OFFSET = 10;\n\nexport type MediaSearchContext = SearchSuperContext & Partial<{\n  isScheduled: boolean,\n  skipSensitive: boolean,\n  useSearch: boolean\n}>;\n\ntype MediaDetails = {\n  peerId: PeerId,\n  mid: number,\n  /**\n   * Effective key under which the media is stored in `this.media` / `this.scheduled`.\n   * Equals `mid + (slot ?? 0)` — see `AddMediaArgs.slot`.\n   */\n  storageKey: number,\n  docId: DocId,\n  doc: MyDocument,\n  message: Message.message,\n  consumers?: Set<Middleware>,\n  unpin?: () => void,\n  clean?: boolean,\n  isScheduled?: boolean,\n  isSingle?: boolean\n};\n\nexport type MediaListLoader = ListLoader<MediaItem, Message.message> & {\n  goRound: (length: number, dispatchJump?: boolean) => void\n  getPrevious: (withOtherSide?: boolean) => MediaItem[]\n  getNext: (withOtherSide?: boolean) => MediaItem[]\n  cleanup: () => void\n  setCurrent: (item: MediaItem) => void\n  repositionTo?: (mid: number, peerId: PeerId) => boolean\n};\nexport type MediaListLoaderOptions = Omit<ListLoaderOptions<MediaItem, Message.message>, 'loadMore'> & {\n  onEmptied?: () => void,\n};\nexport type MediaListLoaderFactory = (options: MediaListLoaderOptions) => MediaListLoader;\n\nexport type PlaybackMediaType = 'voice' | 'video' | 'audio';\n\nexport type AddMediaArgs = {\n  message: Message.message;\n  autoload: boolean;\n  clean?: boolean;\n  middleware?: Middleware;\n  /**\n   * Optional pre-extracted document. When provided, it overrides the default\n   * extraction from `message.media`. Useful when the document lives in a\n   * sibling field of the message (e.g. poll `solution_media`).\n   */\n  doc?: MyDocument;\n  /**\n   * Optional disambiguator added to `mid` when forming the storage key, so\n   * multiple media elements can coexist under the same `(peerId, mid)` pair.\n   * Used for sibling-media-on-the-same-message scenarios (e.g. poll\n   * description vs. explanation documents).\n   *\n   * Use small fractional values (e.g. `0.1`, `0.2`); `0` / undefined means\n   * the standard storage key equal to `mid`.\n   *\n   * Note: slotted entries are intentionally not reachable via `getMedia` /\n   * `playItem` (the playlist flow), since they're not part of a playlist.\n   */\n  slot?: number;\n};\n\nexport class AppMediaPlaybackController extends EventListenerBase<{\n  play: (details: ReturnType<AppMediaPlaybackController['getPlayingDetails']>) => void,\n  singleMedia: (media: HTMLMediaElement) => void,\n  pause: () => void,\n  playbackParams: (params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) => void,\n  stop: () => void,\n  toggleVideoAutoplaySound: (value: boolean) => void\n}> {\n  private container: HTMLElement;\n  private media: Map<PeerId, Map<number, HTMLMediaElement>> = new Map();\n  private scheduled: AppMediaPlaybackController['media'] = new Map();\n  private mediaDetails: Map<HTMLMediaElement, MediaDetails> = new Map();\n  private playingMedia: HTMLMediaElement;\n  private playingMediaType: PlaybackMediaType;\n\n  private waitingMediaForLoad: Map<PeerId, Map<number, CancellablePromise<void>>> = new Map();\n  private waitingScheduledMediaForLoad: AppMediaPlaybackController['waitingMediaForLoad'] = new Map();\n  private waitingDocumentsForLoad: {[docId: string]: Set<HTMLMediaElement>} = {};\n\n  public willBePlayedMedia: HTMLMediaElement;\n  private searchContext: MediaSearchContext;\n\n  private listLoader: MediaListLoader;\n  private listLoaderFactory: MediaListLoaderFactory;\n\n  public volume: number;\n  /**\n   * Voice/round-only boost added on top of the shared `volume` (WebAudio gain, see\n   * {@link applyVolumeToMedia}). The 0–100% slider range maps to the shared `volume`\n   * (common with video/music); the 100–200% range maps to this boost, so amplifying a\n   * voice never bleeds into video/music. Both `volume` and `boost` are clamped to [0, 1];\n   * effective voice volume = `volume + boost` ∈ [0, 2].\n   */\n  public boost: number;\n  public muted: boolean;\n  public playbackRate: number;\n  public loop: boolean;\n  public round: boolean;\n  private _volume: number;\n  private _boost: number;\n  private _muted: boolean;\n  private _playbackRate: number;\n  private _loop: boolean;\n  private _round: boolean;\n  private lockedSwitchers: boolean;\n  private playbackRates: Record<PlaybackMediaType, number> = {\n    voice: 1,\n    video: 1,\n    audio: 1\n  };\n\n  private pip: HTMLVideoElement;\n  private managers: AppManagers;\n  private skipMediaPlayEvent: boolean;\n\n  private gainAudioContext: AudioContext;\n  private mediaGainMap: WeakMap<HTMLMediaElement, {source: MediaElementAudioSourceNode, gain: GainNode, limiter: DynamicsCompressorNode}> = new WeakMap();\n\n  // Music-listen reporting (messages.reportMusicListen) — owned by MusicListenTracker; the\n  // controller just forwards the play/stop events below.\n  private musicListenTracker: MusicListenTracker;\n  private setMediaMetadata = createMediaMetadataObjectURLPins();\n\n  construct(managers: AppManagers) {\n    this.managers = managers;\n    this.musicListenTracker = new MusicListenTracker((inputDoc, listenedDuration) => {\n      // Fire-and-forget analytics — swallow errors (e.g. a stale file_reference) so they don't surface.\n      this.managers.appMessagesManager.reportMusicListen(inputDoc, listenedDuration).catch(() => {});\n    });\n    this.container = document.createElement('div');\n    // this.container.style.cssText = 'position: absolute; top: -10000px; left: -10000px;';\n    this.container.style.cssText = 'display: none;';\n    document.body.append(this.container);\n\n    if(navigator.mediaSession) {\n      const actions: {[action in MediaSessionAction]?: MediaSessionActionHandler} = {\n        play: this.browserPlay,\n        pause: this.browserPause,\n        stop: this.browserStop,\n        seekbackward: this.browserSeekBackward,\n        seekforward: this.browserSeekForward,\n        seekto: this.browserSeekTo,\n        previoustrack: this.browserPrevious,\n        nexttrack: this.browserNext\n      };\n\n      for(const action in actions) {\n        try {\n          navigator.mediaSession.setActionHandler(action as MediaSessionAction, actions[action as MediaSessionAction]);\n        } catch(err) {\n          console.warn('MediaSession action is not supported:', action);\n        }\n      }\n    }\n\n    rootScope.addEventListener('document_downloaded', (docId) => {\n      const set = this.waitingDocumentsForLoad[docId];\n      if(set) {\n        for(const media of set) {\n          this.onMediaDocumentLoad(media);\n        }\n      }\n    });\n\n    rootScope.addEventListener('media_play', () => {\n      if(this.skipMediaPlayEvent) {\n        this.skipMediaPlayEvent = false;\n        return;\n      }\n\n      if(!this.pause() && this.pip) {\n        this.pip.pause();\n      }\n    });\n\n    const properties: {[key: PropertyKey]: PropertyDescriptor} = {};\n    const keys = [\n      'volume' as const,\n      'boost' as const,\n      'muted' as const,\n      'playbackRate' as const,\n      'loop' as const,\n      'round' as const\n    ];\n    keys.forEach((key) => {\n      const _key = ('_' + key) as `_${typeof key}`;\n      properties[key] = {\n        get: () => this[_key],\n        set: (value: number | boolean) => {\n          // Shared master volume and the voice-only boost both stay in [0, 1]; their sum\n          // (effective voice volume) tops out at 200%, the boost never touches video/music.\n          if(key === 'volume' || key === 'boost') {\n            value = clamp(value as number, 0, 1);\n          }\n\n          if(this[_key] === value) {\n            return;\n          }\n\n          // @ts-ignore\n          this[_key] = value;\n          if(this.playingMedia && (key !== 'loop' || this.playingMediaType === 'audio') && key !== 'round') {\n            if(key === 'volume' || key === 'muted' || key === 'boost') {\n              this.applyVolumeToMedia(this.playingMedia, this.getVolumeForType(this.playingMediaType), this.muted, this.playingMediaType);\n            } else {\n              // @ts-ignore\n              this.playingMedia[key] = value;\n            }\n          }\n\n          if(key === 'playbackRate' && this.playingMediaType !== undefined) {\n            this.playbackRates[this.playingMediaType] = value as number;\n          }\n\n          this.dispatchPlaybackParams();\n        }\n      };\n    });\n    Object.defineProperties(this, properties);\n\n    this.addEventListener('play', (details) => {\n      if(details.doc.type === 'round') {\n        animationIntersector.toggleMediaPause(false);\n      }\n\n      this.musicListenTracker.onPlay(details);\n    });\n\n    this.addEventListener('pause', () => {\n      animationIntersector.toggleMediaPause(true);\n    });\n\n    this.addEventListener('stop', () => {\n      this.musicListenTracker.finish();\n    });\n  }\n\n  private dispatchPlaybackParams() {\n    this.dispatchEvent('playbackParams', this.getPlaybackParams());\n  }\n\n  private getOrCreateMediaGain(media: HTMLMediaElement) {\n    let entry = this.mediaGainMap.get(media);\n    if(entry) return entry;\n\n    try {\n      const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext;\n      if(!AC) return undefined;\n      if(!this.gainAudioContext) this.gainAudioContext = new AC();\n      const ctx = this.gainAudioContext;\n\n      const source = ctx.createMediaElementSource(media);\n      const gain = ctx.createGain();\n      // Brick-wall limiter after the gain — keeps amplified peaks below 0 dB so quadratic\n      // boosts raise perceived loudness instead of just clipping to the same ceiling.\n      const limiter = ctx.createDynamicsCompressor();\n      limiter.threshold.value = -1;\n      limiter.knee.value = 0;\n      limiter.ratio.value = 20;\n      limiter.attack.value = 0;\n      limiter.release.value = 0.05;\n      source.connect(gain);\n      gain.connect(limiter);\n      limiter.connect(ctx.destination);\n      entry = {source, gain, limiter};\n      this.mediaGainMap.set(media, entry);\n\n      if(ctx.state === 'suspended') ctx.resume().catch(() => {});\n\n      return entry;\n    } catch(e) {\n      return undefined;\n    }\n  }\n\n  /**\n   * Volume to feed playback for a given media type: voice/round add their boost on top of\n   * the shared master, everything else uses the shared master alone.\n   */\n  private getVolumeForType(mediaType: PlaybackMediaType) {\n    return mediaType === 'voice' ? clamp(this._volume + this._boost, 0, 2) : this._volume;\n  }\n\n  private applyVolumeToMedia(\n    media: HTMLMediaElement,\n    volume: number,\n    muted: boolean,\n    mediaType: PlaybackMediaType\n  ) {\n    if(mediaType === 'voice') {\n      const entry = this.getOrCreateMediaGain(media);\n      if(entry) {\n        if(this.gainAudioContext?.state === 'suspended') this.gainAudioContext.resume().catch(() => {});\n        // Below 100% linear (natural volume control), above 100% quadratic so the slider\n        // delivers perceptual loudness, not just a 2× peak multiplier (e.g. 200% → 4× ≈ +12 dB).\n        const amp = volume <= 1 ? volume : volume * volume;\n        const target = muted ? 0 : amp;\n        try {\n          entry.gain.gain.setTargetAtTime(target, this.gainAudioContext.currentTime, 0.01);\n        } catch(e) {\n          entry.gain.gain.value = target;\n        }\n        media.volume = 1;\n        media.muted = muted;\n        return;\n      }\n    }\n\n    media.volume = Math.min(volume, 1);\n    media.muted = muted;\n  }\n\n  public getPlaybackParams() {\n    const {volume, boost, muted, playbackRate, playbackRates, loop, round} = this;\n    return {\n      volume,\n      boost,\n      muted,\n      playbackRate,\n      playbackRates,\n      loop,\n      round\n    };\n  }\n\n  public setPlaybackParams(params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) {\n    this.playbackRates = params.playbackRates;\n    this._volume = clamp(params.volume ?? 1, 0, 1);\n    // Older states (and the buggy >100% writes this fixes) stored the voice boost inside\n    // `volume`, so when `boost` is absent recover it from the part of `volume` above 100%.\n    // `volume` itself stays clamped to the [0, 1] media range.\n    this._boost = clamp(params.boost ?? Math.max((params.volume ?? 1) - 1, 0), 0, 1);\n    this._muted = params.muted;\n    this._playbackRate = params.playbackRate;\n    this._loop = params.loop;\n    this._round = params.round;\n  }\n\n  public seekBackward = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, Math.max(0, media.currentTime - (details.seekOffset || SEEK_OFFSET)));\n    }\n  };\n\n  public seekForward = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, Math.min(media.duration, media.currentTime + (details.seekOffset || SEEK_OFFSET)));\n    }\n  };\n\n  public seekTo = (details: MediaSessionActionDetails, media = this.playingMedia) => {\n    if(media) {\n      setCurrentTime(media, details.seekTime);\n    }\n  };\n\n  public addMedia(args: AddMediaArgs): HTMLMediaElement {\n    const {message, autoload, clean, doc: docOverride, slot, middleware} = args;\n    const {peerId, mid} = message;\n    const storageKey = mid + (slot ?? 0);\n\n    const isScheduled = !!message.pFlags.is_scheduled;\n    const s = isScheduled ? this.scheduled : this.media;\n    let storage = s.get(message.peerId);\n    if(!storage) {\n      s.set(message.peerId, storage = new Map());\n    }\n\n    let media = storage.get(storageKey);\n    if(media) {\n      this.bindMediaMiddleware(media, middleware);\n      return media;\n    }\n\n    const doc = docOverride ?? (getMediaFromMessage(message, true) as Document.document);\n    storage.set(storageKey, media = document.createElement(doc.type === 'round' || doc.type === 'video' ? 'video' : 'audio'));\n    // const source = document.createElement('source');\n    // source.type = doc.type === 'voice' && !opusDecodeController.isPlaySupported() ? 'audio/wav' : doc.mime_type;\n\n    if(doc.type === 'round') {\n      media.setAttribute('playsinline', 'true');\n      // media.muted = true;\n    }\n\n    const details: MediaDetails = {\n      peerId,\n      mid,\n      storageKey,\n      docId: doc.id,\n      doc,\n      message,\n      clean,\n      isScheduled: message.pFlags.is_scheduled\n    };\n\n    this.mediaDetails.set(media, details);\n    this.bindMediaMiddleware(media, middleware);\n\n    // media.autoplay = true;\n    media.volume = 1;\n    // media.append(source);\n\n    this.container.append(media);\n\n    media.addEventListener('play', this.onPlay);\n    media.addEventListener('pause', this.onPause);\n    media.addEventListener('ended', this.onEnded);\n\n    if(doc.type !== 'audio' && message?.pFlags.media_unread && message.fromId !== rootScope.myId) {\n      media.addEventListener('timeupdate', () => {\n        this.managers.appMessagesManager.readMessages(peerId, [mid]);\n      }, {once: true});\n    }\n\n    /* const onError = (e: Event) => {\n      //console.log('appMediaPlaybackController: video onError', e);\n\n      if(this.nextMid === mid) {\n        this.loadSiblingsMedia(peerId, doc.type as MediaType, mid).then(() => {\n          if(this.nextMid && storage[this.nextMid]) {\n            storage[this.nextMid].play();\n          }\n        });\n      }\n    };\n\n    media.addEventListener('error', onError); */\n\n    const deferred = deferredPromise<void>();\n    if(autoload) {\n      deferred.resolve();\n    } else {\n      const w = message.pFlags.is_scheduled ? this.waitingScheduledMediaForLoad : this.waitingMediaForLoad;\n      let waitingStorage = w.get(peerId);\n      if(!waitingStorage) {\n        w.set(peerId, waitingStorage = new Map());\n      }\n\n      waitingStorage.set(storageKey, deferred);\n    }\n\n    deferred.then(() => {\n      // media.autoplay = true;\n      // console.log('will set media url:', media, doc, doc.type, doc.url);\n\n      if(doc.supportsStreaming || (apiManagerProxy.getCacheContext(doc)).url) {\n        this.onMediaDocumentLoad(media);\n      } else {\n        let set = this.waitingDocumentsForLoad[doc.id];\n        if(!set) {\n          set = this.waitingDocumentsForLoad[doc.id] = new Set();\n        }\n\n        set.add(media);\n        appDownloadManager.downloadMediaURL({media: doc});\n      }\n    }/* , onError */);\n\n    return media;\n  }\n\n  public getMedia(peerId: PeerId, mid: number, isScheduled?: boolean) {\n    const s = (isScheduled ? this.scheduled : this.media).get(peerId);\n    return s?.get(mid);\n  }\n\n  private onMediaDocumentLoad = async(media: HTMLMediaElement) => {\n    const details = this.mediaDetails.get(media);\n    if(!details) {\n      return;\n    }\n\n    const doc = await this.managers.appDocsManager.getDoc(details.docId);\n    if(this.mediaDetails.get(media) !== details) {\n      return;\n    }\n    if(doc.type === 'audio' && doc.supportsStreaming && SHOULD_USE_SAFARI_FIX) {\n      this.handleSafariStreamable(media);\n    }\n\n    // setTimeout(() => {\n    const cacheContext = apiManagerProxy.getCacheContext(doc);\n    // * playback needs the blob URL alive for seeks/loops — pin it until the\n    // * media element is removed\n    details.unpin?.();\n    details.unpin = pinObjectURL(cacheContext.url);\n    media.src = cacheContext.url;\n\n    if(this.playingMedia === media) {\n      media.playbackRate = this.playbackRate;\n\n      if(doc.type === 'audio') {\n        media.loop = this.loop;\n      }\n    }\n    // }, doc.supportsStreaming ? 500e3 : 0);\n\n    const set = this.waitingDocumentsForLoad[doc.id];\n    if(set) {\n      set.delete(media);\n\n      if(!set.size) {\n        delete this.waitingDocumentsForLoad[doc.id];\n      }\n    }\n  };\n\n  private bindMediaMiddleware(media: HTMLMediaElement, middleware?: Middleware) {\n    if(!middleware) {\n      return;\n    }\n\n    const details = this.mediaDetails.get(media);\n    const consumers = details.consumers ??= new Set();\n    if(consumers.has(middleware)) {\n      return;\n    }\n\n    consumers.add(middleware);\n    details.clean = false;\n    middleware.onClean(() => {\n      if(this.mediaDetails.get(media) !== details) {\n        return;\n      }\n\n      consumers.delete(middleware);\n      if(consumers.size) {\n        return;\n      }\n\n      if(media === this.playingMedia) {\n        details.clean = true;\n      } else {\n        this.removeMedia(media);\n      }\n    });\n  }\n\n  private removeMedia(media: HTMLMediaElement) {\n    const details = this.mediaDetails.get(media);\n    if(!details) {\n      return;\n    }\n\n    clearMediaElementSource(media);\n    details.unpin?.();\n    details.unpin = undefined;\n    const storage = (details.isScheduled ? this.scheduled : this.media).get(details.peerId);\n    storage?.delete(details.storageKey);\n    if(!storage?.size) {\n      (details.isScheduled ? this.scheduled : this.media).delete(details.peerId);\n    }\n    this.waitingDocumentsForLoad[details.docId]?.delete(media);\n    const waiting = (details.isScheduled ?\n      this.waitingScheduledMediaForLoad :\n      this.waitingMediaForLoad).get(details.peerId);\n    waiting?.delete(details.storageKey);\n    if(!waiting?.size) {\n      (details.isScheduled ?\n        this.waitingScheduledMediaForLoad :\n        this.waitingMediaForLoad).delete(details.peerId);\n    }\n    media.remove();\n    this.mediaDetails.delete(media);\n  }\n\n  // safari подгрузит последний чанк и песня включится,\n  // при этом этот чанк нельзя руками отдать из SW, потому что браузер тогда теряется\n  private handleSafariStreamable(media: HTMLMediaElement) {\n    media.addEventListener('play', () => {\n      /* if(media.readyState === 4) { // https://developer.mozilla.org/ru/docs/Web/API/XMLHttpRequest/readyState\n        return;\n      } */\n\n      // media.volume = 0;\n      const currentTime = media.currentTime;\n      // this.setSafariBuffering(media, true);\n\n      media.addEventListener('progress', () => {\n        setCurrentTime(media, media.duration - 1);\n\n        media.addEventListener('progress', () => {\n          setCurrentTime(media, currentTime);\n          // media.volume = 1;\n          // this.setSafariBuffering(media, false);\n\n          if(!media.paused) {\n            media.play()/* .catch(() => {}) */;\n          }\n        }, {once: true});\n      }, {once: true});\n    }/* , {once: true} */);\n  }\n\n  public resolveWaitingForLoadMedia(peerId: PeerId, mid: number, isScheduled?: boolean, slot?: number) {\n    const w = isScheduled ? this.waitingScheduledMediaForLoad : this.waitingMediaForLoad;\n    const storage = w.get(peerId);\n    if(!storage) {\n      return;\n    }\n\n    const storageKey = mid + (slot ?? 0);\n    const promise = storage.get(storageKey);\n    if(promise) {\n      promise.resolve();\n      storage.delete(storageKey);\n\n      if(!storage.size) {\n        w.delete(peerId);\n      }\n    }\n  }\n\n  /**\n   * Only for audio\n   */\n  public isSafariBuffering(media: HTMLMediaElement) {\n    // @ts-ignore\n    return !!media.safariBuffering;\n  }\n\n  private setSafariBuffering(media: HTMLMediaElement, value: boolean) {\n    // @ts-ignore\n    media.safariBuffering = value;\n  }\n\n  private async setNewMediadata(message: Message.message, playingMedia = this.playingMedia) {\n    if(getAppWindow().document.pictureInPictureElement) {\n      return;\n    }\n\n    await onMediaLoad(playingMedia, undefined, false); // have to wait for load, otherwise on macOS won't set\n\n    const doc = getMediaFromMessage(message, true) as MyDocument;\n    if(!doc) return; // live\n\n    const artwork: MediaImage[] = [];\n\n    const isVoice = doc.type === 'voice' || doc.type === 'round';\n    let title = '', artist = '';\n\n    if(doc.thumbs?.length) {\n      const size = doc.thumbs[doc.thumbs.length - 1];\n      if(!(size as PhotoSize.photoStrippedSize).bytes) {\n        const cacheContext = apiManagerProxy.getCacheContext(doc, size.type);\n\n        if(cacheContext.url) {\n          artwork.push({\n            src: cacheContext.url,\n            sizes: `${(size as PhotoSize.photoSize).w}x${(size as PhotoSize.photoSize).h}`,\n            type: 'image/jpeg'\n          });\n        } else {\n          const download = appDownloadManager.downloadMediaURL({media: doc, thumb: size});\n          download.then(() => {\n            if(this.playingMedia !== playingMedia || !cacheContext.url) {\n              return;\n            }\n\n            this.setNewMediadata(message);\n          });\n        }\n      }\n    } else if(isVoice) {\n      const peerId = message.fromId || message.peerId;\n      const peerPhoto = await this.managers.appPeersManager.getPeerPhoto(peerId);\n      if(peerPhoto) {\n        // const result = this.managers.appAvatarsManager.loadAvatar(peerId, peerPhoto, 'photo_small');\n        // if(result.cached) {\n        //   const url = await result.loadPromise;\n        //   artwork.push({\n        //     src: url,\n        //     sizes: '160x160',\n        //     type: 'image/jpeg'\n        //   });\n        // } else {\n        //   result.loadPromise.then((url) => {\n        //     if(this.playingMedia !== playingMedia || !url) {\n        //       return;\n        //     }\n\n        //     this.setNewMediadata(message);\n        //   });\n        // }\n      }\n\n      title = await getPeerTitle({peerId, plainText: true, onlyFirstName: false});\n      artist = I18n.format(doc.type === 'voice' ? 'AttachAudio' : 'AttachRound', true);\n    }\n\n    if(!isVoice) {\n      const attribute = doc.attributes.find((attribute) => attribute._ === 'documentAttributeAudio') as DocumentAttribute.documentAttributeAudio;\n      title = attribute?.title ?? doc.file_name;\n      artist = attribute?.performer;\n    }\n\n    if(!artwork.length) {\n      if(IS_APPLE) {\n        if(IS_TOUCH_SUPPORTED) {\n          artwork.push({\n            src: `assets/img/apple-touch-icon-precomposed.png`,\n            sizes: '180x180',\n            type: 'image/png'\n          });\n        } else {\n          artwork.push({\n            src: `assets/img/apple-touch-icon.png`,\n            sizes: '180x180',\n            type: 'image/png'\n          });\n        }\n      } else {\n        [72, 96, 144, 192, 256, 384, 512].forEach((size) => {\n          const sizes = `${size}x${size}`;\n          artwork.push({\n            src: `assets/img/android-chrome-${sizes}.png`,\n            sizes,\n            type: 'image/png'\n          });\n        });\n      }\n    }\n\n    const metadata = new MediaMetadata({\n      title,\n      artist,\n      artwork\n    });\n\n    this.setMediaMetadata(metadata);\n  }\n\n  public setCurrentMediadata() {\n    const {playingMedia} = this;\n    if(!playingMedia) return;\n    const message = this.getMessageByMedia(playingMedia);\n    this.setNewMediadata(message, playingMedia);\n  }\n\n  private getMessageByMedia(media: HTMLMediaElement): Message.message {\n    const details = this.mediaDetails.get(media);\n    return details?.message;\n    // const {peerId, mid} = details;\n    // const message = details.isScheduled ?\n    //   this.managers.appMessagesManager.getScheduledMessageByPeer(peerId, mid) :\n    //   this.managers.appMessagesManager.getMessageByPeer(peerId, mid);\n    // return message;\n  }\n\n  public getPlayingDetails() {\n    const {playingMedia} = this;\n    if(!playingMedia) {\n      return;\n    }\n\n    const message = this.getMessageByMedia(playingMedia);\n    if(!message) {\n      return;\n    }\n\n    const details = this.mediaDetails.get(playingMedia);\n\n    return {\n      doc: details?.doc || getMediaFromMessage(message, true) as MyDocument,\n      message,\n      media: playingMedia,\n      isSavedMusic: Boolean(message.pFlags.fakeForSavedMusic),\n      /**\n       * The message was built only to render a row (the music picker's preview list) and lives\n       * nowhere else — there is no chat message behind it to open.\n       */\n      isLocal: Boolean(message.pFlags.local),\n      /**\n       * True when the media was added with a non-zero `slot` (e.g. poll\n       * description / explanation audio). Such media is played in isolation:\n       * its list loader is empty, so next/previous navigation and looping\n       * are not meaningful.\n       */\n      isSlotted: !!details && details.storageKey !== details.mid,\n      playbackParams: this.getPlaybackParams()\n    };\n  }\n\n  private onPlay = (e?: Event) => {\n    const media = e.target as HTMLMediaElement;\n    const details = this.mediaDetails.get(media);\n    const {peerId, mid} = details;\n\n    // console.log('appMediaPlaybackController: video playing', this.currentPeerId, this.playingMedia, media);\n\n    const pip = this.pip;\n    if(pip) {\n      pip.pause();\n    }\n\n    const message = this.getMessageByMedia(media);\n\n    const previousMedia = this.playingMedia;\n    if(previousMedia !== media) {\n      this.stop();\n      this.setMedia(media, message);\n\n      const verify = (element: MediaItem) => element.mid === mid && element.peerId === peerId;\n      const listLoader = this.listLoader;\n      const current = listLoader.current;\n      if(!current || !verify(current)) {\n        let jumpLength: number;\n\n        for(const withOtherSide of [false, true]) {\n          const previous = listLoader.getPrevious(withOtherSide);\n\n          let idx = previous.findIndex(verify);\n          if(idx !== -1) {\n            jumpLength = -(previous.length - idx);\n          } else {\n            const next = listLoader.getNext(withOtherSide);\n            idx = next.findIndex(verify);\n            if(idx !== -1) {\n              jumpLength = idx + 1;\n            }\n          }\n\n          if(jumpLength !== undefined) {\n            break;\n          }\n        }\n\n        if(jumpLength) {\n          this.go(jumpLength, false);\n        } else if(!listLoader.repositionTo?.(mid, peerId)) {\n          this.setTargets({peerId, mid});\n        }\n      }\n    }\n\n    // audio_pause не успеет сработать без таймаута\n    setTimeout(() => {\n      if(this.playingMedia !== media) {\n        return;\n      }\n\n      this.dispatchEvent('play', this.getPlayingDetails());\n      this.pauseMediaInOtherTabs();\n    }, 0);\n  };\n\n  private onPause = (e?: Event) => {\n    /* const target = e.target as HTMLMediaElement;\n    if(!isInDOM(target)) {\n      this.container.append(target);\n      target.play();\n      return;\n    } */\n\n    // if(this.pip) {\n    //   this.pip.play();\n    // }\n\n    this.dispatchEvent('pause');\n  };\n\n  private onEnded = (e?: Event) => {\n    if(e && !e.isTrusted) {\n      return;\n    }\n\n    this.onPause(e);\n\n    // console.log('on media end');\n\n    const listLoader = this.listLoader;\n    if(\n      this.lockedSwitchers ||\n      (!this.round && listLoader.current && !listLoader.getNext(false).length) ||\n      !listLoader.getNext(true).length ||\n      !this.next()\n    ) {\n      this.stop();\n      this.dispatchEvent('stop');\n    }\n  };\n\n  public pauseMediaInOtherTabs() {\n    this.skipMediaPlayEvent = true;\n    rootScope.dispatchEvent('media_play');\n  }\n\n  // public get pip() {\n  //   return document.pictureInPictureElement as HTMLVideoElement;\n  // }\n\n  public toggle(play?: boolean, media = this.playingMedia) {\n    if(!media) {\n      return false;\n    }\n\n    if(play === undefined) {\n      play = media.paused;\n    }\n\n    if(media.paused !== play) {\n      return false;\n    }\n\n    if(play) {\n      media.play();\n    } else {\n      media.pause();\n    }\n\n    return true;\n  }\n\n  public getPlayingMedia() {\n    return this.playingMedia;\n  }\n\n  /**\n   * Slider value for the global-only selector (pinned audio plate) bound to whatever is\n   * playing: voice shows `volume + boost` (its 0–200% range), everything else the shared\n   * master `volume`.\n   */\n  public getGlobalSliderVolume() {\n    return this.getVolumeForType(this.playingMediaType);\n  }\n\n  /**\n   * Apply a global-only selector value. For voice the 0–100% part sets the shared master\n   * (common with video/music) and the 100–200% part sets the voice-only boost, so the\n   * boost stays out of `volume`. For everything else it just sets the shared master.\n   */\n  public setGlobalSliderVolume(value: number) {\n    if(this.playingMediaType === 'voice') {\n      this.boost = Math.max(value - 1, 0);\n      this.volume = Math.min(value, 1);\n    } else {\n      this.volume = value;\n    }\n  }\n\n  public play = () => {\n    return this.toggle(true);\n  };\n\n  public pause = () => {\n    return this.toggle(false);\n  };\n\n  public stop = (media = this.playingMedia, force?: boolean) => {\n    if(!media) {\n      return false;\n    }\n\n    if(!media.paused) {\n      media.pause();\n    }\n\n    setCurrentTime(media, 0);\n    simulateEvent(media, 'ended'); // ! important, will be used to hide controls for audio element\n\n    if(media === this.playingMedia) {\n      const details = this.mediaDetails.get(media);\n      if(details?.clean) {\n        this.removeMedia(media);\n      }\n\n      this.playingMedia = undefined;\n      this.playingMediaType = undefined;\n    }\n\n    if(force) {\n      this.dispatchEvent('stop');\n    }\n\n    return true;\n  };\n\n  public playItem = (item: MediaItem) => {\n    const {peerId, mid} = item;\n    const isScheduled = this.searchContext.isScheduled;\n    const media = this.getMedia(peerId, mid, isScheduled);\n\n    /* if(isSafari) {\n      media.autoplay = true;\n    } */\n\n    media.play();\n\n    setTimeout(() => {\n      this.resolveWaitingForLoadMedia(peerId, mid, isScheduled);\n    }, 0);\n  };\n\n  public go = (length: number, dispatchJump?: boolean) => {\n    const listLoader = this.listLoader;\n    if(this.lockedSwitchers || !listLoader) {\n      return;\n    }\n\n    if(this.playingMediaType === 'audio') {\n      return listLoader.goRound(length, dispatchJump);\n    } else {\n      return listLoader.go(length, dispatchJump);\n    }\n  };\n\n  private bindBrowserCallback(cb: (video: HTMLVideoElement, details: MediaSessionActionDetails) => void) {\n    const handler: MediaSessionActionHandler = (details) => {\n      cb(this.pip, details);\n    };\n\n    return handler;\n  }\n\n  public browserPlay = this.bindBrowserCallback((video) => this.toggle(true, video));\n  public browserPause = this.bindBrowserCallback((video) => this.toggle(false, video));\n  public browserStop = this.bindBrowserCallback((video) => this.stop(video));\n  public browserSeekBackward = this.bindBrowserCallback((video, details) => this.seekBackward(details, video));\n  public browserSeekForward = this.bindBrowserCallback((video, details) => this.seekForward(details, video));\n  public browserSeekTo = this.bindBrowserCallback((video, details) => this.seekTo(details, video));\n  public browserNext = this.bindBrowserCallback((video) => video || this.next());\n  public browserPrevious = this.bindBrowserCallback((video) => video ? this.seekToStart(video) : this.previous());\n\n  public next = () => {\n    return this.go(1);\n  };\n\n  public previous = () => {\n    if(this.seekToStart(this.playingMedia)) {\n      return;\n    }\n\n    return this.go(-1);\n  };\n\n  public seekToStart(media: HTMLMediaElement) {\n    if(media?.currentTime > 5) {\n      setCurrentTime(media, 0);\n      this.toggle(true, media);\n      return true;\n    }\n\n    return false;\n  }\n\n  public willBePlayed(media: HTMLMediaElement) {\n    this.willBePlayedMedia = media;\n  }\n\n  public getListLoaderFactory() {\n    return this.listLoaderFactory;\n  }\n\n  public setSearchContext(context: MediaSearchContext) {\n    if(deepEqual(this.searchContext, context)) {\n      return false;\n    }\n\n    this.searchContext = copy(context); // {_: type === 'audio' ? 'inputMessagesFilterMusic' : 'inputMessagesFilterRoundVoice'}\n    return true;\n  }\n\n  public getSearchContext() {\n    return this.searchContext;\n  }\n\n  private static defaultLoaderFactory: MediaListLoaderFactory = (options: MediaListLoaderOptions) => new SearchListLoader(options);\n\n  public setTargets(\n    current: MediaItem,\n    prev?: MediaItem[],\n    next?: MediaItem[],\n    loaderFactory: MediaListLoaderFactory = AppMediaPlaybackController.defaultLoaderFactory\n  ) {\n    let listLoader = this.listLoader;\n    if(!listLoader || this.listLoaderFactory !== loaderFactory) {\n      listLoader?.cleanup();\n\n      listLoader = this.listLoader = loaderFactory({\n        loadCount: 10,\n        loadWhenLeft: 5,\n        processItem: (message: Message.message) => {\n          this.addMedia({message, autoload: false});\n          return {peerId: message.peerId, mid: message.mid};\n        },\n        onJump: (item, older) => {\n          this.playItem(item);\n        },\n        onEmptied: () => {\n          this.dispatchEvent('stop');\n          this.stop();\n        }\n      });\n      this.listLoaderFactory = loaderFactory;\n    } else {\n      listLoader.reset();\n    }\n\n\n    if(listLoader instanceof SearchListLoader) {\n      const reverse = this.searchContext.folderId !== undefined ? false : true;\n      listLoader.setSearchContext(this.searchContext);\n      if(prev) {\n        listLoader.setTargets(prev, next, reverse);\n      } else {\n        listLoader.reverse = reverse;\n      }\n    }\n\n    listLoader.setCurrent(current);\n\n    listLoader.load(true);\n    listLoader.load(false);\n  }\n\n  private getPlaybackMediaTypeFromMessage(message: Message.message) {\n    const doc = getMediaFromMessage(message, true) as MyDocument;\n    let mediaType: PlaybackMediaType = 'audio';\n    if(doc?.type) {\n      if(doc.type === 'voice' || doc.type === 'round') {\n        mediaType = 'voice';\n      } else if(doc.type === 'video') {\n        mediaType = 'video';\n      }\n    }\n\n    return mediaType;\n  }\n\n  public setMedia(media: HTMLMediaElement, message: Message.message, standalone?: boolean) {\n    const mediaType = this.getPlaybackMediaTypeFromMessage(message);\n\n    this._playbackRate = this.playbackRates[mediaType];\n\n    this.playingMedia = media;\n    this.playingMediaType = mediaType;\n    if(!standalone) {\n      this.applyVolumeToMedia(this.playingMedia, this.getVolumeForType(mediaType), this.muted, mediaType);\n      this.playingMedia.playbackRate = this.playbackRate;\n      if(mediaType === 'audio') {\n        this.playingMedia.loop = this.loop;\n      }\n    }\n\n    if('mediaSession' in navigator) {\n      this.setNewMediadata(message);\n    }\n  }\n\n  public setSingleMedia({\n    media,\n    message,\n    standalone\n  }: {\n    media?: HTMLMediaElement,\n    message?: Message.message,\n    standalone?: boolean\n  } = {}) {\n    const playingMedia = this.playingMedia;\n\n    const wasPlaying = this.pause();\n\n    let onPlay: () => void;\n    if(media) {\n      onPlay = () => {\n        const pip = this.pip;\n        if(pip) {\n          pip.pause();\n        }\n\n        this.pauseMediaInOtherTabs();\n      };\n\n      if(!media.paused) {\n        onPlay();\n      }\n\n      media.addEventListener('play', onPlay);\n    } else { // maybe it's voice recording\n      this.pauseMediaInOtherTabs();\n    }\n\n    this.willBePlayed(undefined);\n    if(media) this.setMedia(media, message, standalone);\n    else this.playingMedia = undefined;\n    this.toggleSwitchers(false);\n\n    this.dispatchEvent('singleMedia', media);\n\n    return (playPaused = wasPlaying) => {\n      this.toggleSwitchers(true);\n\n      if(playingMedia) {\n        if(this.mediaDetails.get(playingMedia)) {\n          this.setMedia(playingMedia, this.getMessageByMedia(playingMedia));\n        } else {\n          this.next() || this.previous();\n        }\n      }\n\n      // If it's still not cleaned\n      if(this.playingMedia === media) {\n        this.playingMedia = undefined;\n        this.playingMediaType = undefined;\n      }\n\n      if(media) {\n        media.removeEventListener('play', onPlay);\n      }\n\n      // I don't remember what it was for\n      // if(media && this.playingMedia === media) {\n      //   this.stop();\n      // }\n\n      if(playPaused) {\n        this.play();\n      }\n    };\n  }\n\n  public toggleSwitchers(enabled: boolean) {\n    this.lockedSwitchers = !enabled;\n  }\n\n  public setPictureInPicture(video: HTMLVideoElement) {\n    this.pip = video;\n\n    // let wasPlaying = this.pause();\n\n    const listenerSetter = new ListenerSetter();\n    listenerSetter.add(video)('leavepictureinpicture', () => {\n      if(this.pip !== video) {\n        return;\n      }\n\n      this.pip = undefined;\n      // if(wasPlaying) {\n      //   this.play();\n      // }\n\n      listenerSetter.removeAll();\n    }, {once: true});\n\n    listenerSetter.add(video)('play', (e) => {\n      if(this.playingMedia !== video) {\n        this.pause();\n      }\n\n      this.pauseMediaInOtherTabs();\n      // if(this.pause()) {\n      //   listenerSetter.add(video)('pause', () => {\n      //     this.play();\n      //   }, {once: true});\n      // }\n    });\n  }\n}\n\nconst appMediaPlaybackController = new AppMediaPlaybackController();\nMOUNT_CLASS_TO.appMediaPlaybackController = appMediaPlaybackController;\nexport default appMediaPlaybackController;\n","import contextMenuController from '@helpers/contextMenuController';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {AttachClickOptions, CLICK_EVENT_NAME, hasMouseMovedSinceDown} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '@helpers/array/filterAsync';\nimport {doubleRaf} from '@helpers/schedulers';\nimport callbackify from '@helpers/callbackify';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {MenuPositionPadding, positionMenuTrigger} from '@helpers/positionMenu';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {getFullScreenElement} from '@helpers/dom/fullScreen';\n\n// TODO: refactor for attachClickEvent, because if move finger after touchstart, it will start anyway\nexport function ButtonMenuToggleHandler({\n  el,\n  onOpen,\n  options,\n  onClose\n}: {\n  el: HTMLElement,\n  onOpen?: (e: Event) => any,\n  options?: AttachClickOptions,\n  onClose?: () => void\n}) {\n  const add = options?.listenerSetter ? options.listenerSetter.add(el) : el.addEventListener.bind(el);\n\n  add(CLICK_EVENT_NAME, (e: Event) => {\n    if(!el.classList.contains('btn-menu-toggle') || hasMouseMovedSinceDown(e)) return false;\n\n    cancelEvent(e);\n\n    if(el.classList.contains('menu-open')) {\n      if(e.target && (e.target as HTMLElement).classList.contains('btn-menu')) {\n        return;\n      }\n\n      contextMenuController.close();\n    } else {\n      const result = onOpen?.(e);\n      const open = (element?: HTMLElement) => {\n        const openedMenu = element ?? el.querySelector('.btn-menu') as HTMLDivElement;\n        if(!openedMenu) {\n          return;\n        }\n\n        contextMenuController.openBtnMenu(openedMenu, onClose, el);\n      };\n\n      callbackify(result, open);\n    }\n  });\n}\n\nexport function filterButtonMenuItems(buttons: ButtonMenuItemOptionsVerifiable[]) {\n  return filterAsync(buttons, (button) => button?.verify ? button.verify() ?? false : true);\n}\n\n/**\n * A menu whose every item fails its verify has nothing to open, so hide its trigger.\n * Returns a function to call whenever something the verifies depend on has changed.\n */\nexport function createButtonMenuVisibility(\n  button: HTMLElement,\n  buttons: ButtonMenuItemOptionsVerifiable[],\n  hide?: () => boolean\n) {\n  let changeId = 0;\n  return () => {\n    const id = ++changeId;\n    void filterButtonMenuItems(buttons).then((items) => {\n      if(id === changeId) {\n        button.classList.toggle('hide', (hide?.() ?? false) || !items.length);\n      }\n    });\n  };\n}\n\nexport type ButtonMenuDirection = 'bottom-left' | 'bottom-right' | 'bottom-center' | 'top-left' | 'top-right'\n\nexport default function ButtonMenuToggle({\n  buttonOptions,\n  listenerSetter: attachListenerSetter,\n  container,\n  direction,\n  buttons,\n  onOpenBefore,\n  onOpen,\n  onClose,\n  onCloseAfter,\n  noIcon,\n  icon = 'more',\n  appendTo,\n  positionPadding\n}: {\n  buttonOptions?: Parameters<typeof ButtonIcon>[1],\n  listenerSetter?: ListenerSetter,\n  container?: HTMLElement\n  appendTo?: HTMLElement,\n  direction: ButtonMenuDirection,\n  buttons: ButtonMenuItemOptionsVerifiable[],\n  onOpenBefore?: (e: Event) => any,\n  onOpen?: (e: Event, element: HTMLElement) => any,\n  onClose?: () => void,\n  onCloseAfter?: () => void,\n  noIcon?: boolean,\n  icon?: (string & {}) | Icon,\n  positionPadding?: MenuPositionPadding\n}) {\n  if(buttonOptions) {\n    buttonOptions.asDiv = true;\n  }\n\n  const button = container ?? ButtonIcon(noIcon ? undefined : icon, buttonOptions);\n  const autoPosition = !appendTo;\n  button.classList.add('btn-menu-toggle');\n\n  const listenerSetter = new ListenerSetter();\n\n  const clearCloseTimeout = () => {\n    clearTimeout(closeTimeout);\n    closeTimeout = undefined;\n  };\n\n  // * fix translation by deleting text elements on close\n  const canDeleteTextElementsOnClose = buttons.filter((button) => !button.textElement);\n  const previousButtons = buttons.slice();\n\n  let element: HTMLElement, closeTimeout: number, tempId = 0;\n  ButtonMenuToggleHandler({\n    el: button,\n    onOpen: async(e) => {\n      const _tempId = ++tempId;\n      await onOpenBefore?.(e);\n      if(_tempId !== tempId) return;\n      if(closeTimeout) {\n        clearCloseTimeout();\n        if(element?.isConnected) {\n          return element;\n        }\n      }\n\n      const filteredButtons = await filterButtonMenuItems(buttons);\n      if(_tempId !== tempId) return;\n      if(!filteredButtons.length) {\n        return;\n      }\n\n      const newButtons = filteredButtons.slice().filter((button) => !previousButtons.includes(button));\n      previousButtons.push(...newButtons);\n      canDeleteTextElementsOnClose.push(...newButtons.filter((button) => !button.textElement));\n\n      const _element = element = await ButtonMenu({\n        buttons: filteredButtons,\n        listenerSetter\n      });\n      if(_tempId !== tempId) return;\n      _element.classList.add(direction);\n      if(direction === 'bottom-center') {\n        _element.style.setProperty('--parent-half-width', ((container ?? button).clientWidth / 2) + 'px');\n      }\n\n      await onOpen?.(e, _element);\n      if(_tempId !== tempId) return;\n\n      // Resolve the mount lazily so a menu opened while the client is popped out lands in the active\n      // window's body (the Document PiP window), not the background tab. While an element is fullscreen\n      // the browser paints ONLY the fullscreen subtree (its top layer), so a menu mounted on document.body\n      // would be invisible — mount it inside the fullscreen element when the trigger lives there (e.g. the\n      // video player's playback-rate / quality / live menus).\n      const fullScreenElement = getFullScreenElement();\n      const mountTarget = appendTo ??\n        (fullScreenElement?.contains(button) ? fullScreenElement : getOverlayRoot());\n      mountTarget.append(_element);\n      if(autoPosition) {\n        positionMenuTrigger(button, _element, direction, positionPadding ?? {top: 8, bottom: 8});\n      }\n      await doubleRaf();\n      if(_tempId !== tempId) {\n        _element.remove();\n      }\n\n      return _element\n    },\n    options: {\n      listenerSetter: attachListenerSetter\n    },\n    onClose: () => {\n      ++tempId;\n      clearCloseTimeout();\n      onClose?.();\n\n      closeTimeout = window.setTimeout(() => {\n        onCloseAfter?.();\n        closeTimeout = undefined;\n        listenerSetter.removeAll();\n        buttons.forEach((button) => {\n          try {button.dispose?.();} catch{}\n          button.element = undefined;\n        });\n        canDeleteTextElementsOnClose.forEach((button) => delete button.textElement);\n        element.remove();\n      }, 300);\n    }\n  });\n\n  return button;\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\nexport default class ControlsHover extends EventListenerBase<{\n  toggleControls: (show: boolean) => void\n}> {\n  protected hideControlsTimeout: number;\n  protected controlsLocked: boolean;\n\n  protected canHideControls: () => boolean;\n  protected canShowControls: () => boolean;\n  protected element: HTMLElement;\n  protected listenerSetter: ListenerSetter;\n  protected showOnLeaveToClassName: string | string[];\n  protected ignoreClickClassName: string;\n\n  constructor() {\n    super(false);\n    this.hideControlsTimeout = 0;\n  }\n\n  public setup(options: {\n    element: HTMLElement,\n    listenerSetter: ListenerSetter,\n    canHideControls?: () => boolean,\n    canShowControls?: () => boolean,\n    showOnLeaveToClassName?: string | string[],\n    ignoreClickClassName?: string\n  }) {\n    safeAssign(this, options);\n\n    const {listenerSetter, element} = this;\n\n    if(IS_TOUCH_SUPPORTED) {\n      listenerSetter.add(element)('click', (e) => {\n        if(this.ignoreClickClassName && findUpClassName(e.target, this.ignoreClickClassName)) {\n          return;\n        }\n\n        this.toggleControls();\n      });\n\n      /* listenerSetter.add(player)('touchstart', () => {\n        showControls(false);\n      });\n\n      listenerSetter.add(player)('touchend', () => {\n        if(player.classList.contains('is-playing')) {\n          showControls();\n        }\n      }); */\n    } else {\n      listenerSetter.add(element)('mousemove', () => {\n        this.showControls();\n      });\n\n      listenerSetter.add(element)('mouseenter', () => {\n        this.showControls(false);\n      });\n\n      listenerSetter.add(element)('mouseleave', (e) => {\n        // Leaving onto floating chrome (caption / topbar) must not start the hide —\n        // those elements live outside the player, so hiding here would yank them from\n        // under the cursor and bounce mouseenter↔mouseleave forever.\n        const showOnLeaveClassNames = Array.isArray(this.showOnLeaveToClassName) ? this.showOnLeaveToClassName : [this.showOnLeaveToClassName];\n        if(e.relatedTarget && showOnLeaveClassNames.some((className) => className && findUpClassName(e.relatedTarget, className))) {\n          this.showControls(false);\n          return;\n        }\n\n        this.hideControls();\n      });\n    }\n  }\n\n  public hideControls = (setHideTimeout = false) => {\n    if(setHideTimeout) {\n      if(!this.hideControlsTimeout) {\n        this.hideControlsTimeout = window.setTimeout(this.hideControls, 3e3);\n      }\n\n      return;\n    }\n\n    clearTimeout(this.hideControlsTimeout);\n    this.hideControlsTimeout = 0;\n\n    const isShown = this.element.classList.contains('show-controls');\n    if(this.controlsLocked !== false) {\n      if((this.canHideControls ? !this.canHideControls() : false) || !isShown || this.controlsLocked) {\n        return;\n      }\n    } else if(!isShown) {\n      return;\n    }\n\n    this.dispatchEvent('toggleControls', false);\n    this.element.classList.remove('show-controls');\n  };\n\n  public showControls = (setHideTimeout = true) => {\n    if(!(this.canShowControls?.() ?? true)) return;\n\n    if(this.hideControlsTimeout) {\n      clearTimeout(this.hideControlsTimeout);\n      this.hideControlsTimeout = 0;\n    } else if(!this.element.classList.contains('show-controls') && this.controlsLocked !== false) {\n      this.dispatchEvent('toggleControls', true);\n      this.element.classList.add('show-controls');\n    }\n\n    if(!setHideTimeout || this.controlsLocked) {\n      return;\n    }\n\n    this.hideControlsTimeout = window.setTimeout(this.hideControls, 3e3);\n  };\n\n  public toggleControls = (show?: boolean) => {\n    const isShown = this.element.classList.contains('show-controls');\n\n    if(show === undefined) {\n      if(isShown) this.hideControls();\n      else this.showControls();\n    } else if(show === isShown) return;\n    else if(show === false) this.hideControls();\n    else this.showControls();\n  };\n\n  public lockControls(visible: boolean) {\n    if(this.controlsLocked === visible) {\n      return;\n    }\n\n    this.controlsLocked = visible;\n    this.element.classList.toggle('disable-hover', visible === false);\n    this.toggleControls(visible);\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// Document Picture-in-Picture lets an arbitrary DOM subtree (not just a <video>) live in an\n// always-on-top OS window — https://developer.chrome.com/docs/web-platform/document-picture-in-picture.\n// Chromium-only as of 2026; absent everywhere else, so the chat-PiP entry point is gated on this.\nconst DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED = typeof window !== 'undefined' &&\n  'documentPictureInPicture' in window &&\n  typeof window.documentPictureInPicture?.requestWindow === 'function';\n\nexport default DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED;\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n/**\n * A Document Picture-in-Picture window starts as a blank document — none of the app's CSS reaches it.\n * This clones every stylesheet from `source` into `target` and keeps them live:\n *  - `<style>`/`<link>` additions & removals (Vite HMR, themeController's appended night-`<style>`);\n *  - the `<html>` class + inline style (the `.night` toggle, theme CSS custom properties, and the\n *    JS-owned layout vars `--vh` / `--chat-width` / `--left-column-width` …) mirrored on every change;\n *  - the `<body>` class (`has-chat`, `right-column-floats`, `is-mobile`, …).\n *\n * Per-source-sheet node mapping means unchanged sheets are never re-created, so theme/layout updates\n * don't flash the whole PiP. Returns a disposer that stops every observer.\n */\nexport default function mirrorDocumentStyles(source: Document, target: Document): () => void {\n  // Maps a source stylesheet's owner node -> the cloned node we maintain in `target.head`.\n  const mirrored = new Map<Node, HTMLStyleElement | HTMLLinkElement>();\n\n  const syncSheets = () => {\n    const seen = new Set<Node>();\n\n    for(const sheet of Array.from(source.styleSheets)) {\n      const owner = sheet.ownerNode;\n      if(!owner) continue;\n      seen.add(owner);\n\n      let node = mirrored.get(owner);\n      let cssText: string | undefined;\n      try {\n        cssText = Array.from(sheet.cssRules).map((rule) => rule.cssText).join('\\n');\n      } catch{\n        // Cross-origin sheet — cssRules throws. Re-link it by href instead of inlining.\n      }\n\n      if(cssText !== undefined) {\n        if(!node || node.tagName !== 'STYLE') {\n          node?.remove();\n          node = target.createElement('style');\n          mirrored.set(owner, node);\n          target.head.append(node);\n        }\n        if(sheet.media?.mediaText) node.media = sheet.media.mediaText;\n        if(node.textContent !== cssText) node.textContent = cssText;\n      } else {\n        const href = (sheet.ownerNode as HTMLLinkElement).href;\n        if(!href) continue;\n        if(!node || node.tagName !== 'LINK') {\n          node?.remove();\n          node = target.createElement('link');\n          (node as HTMLLinkElement).rel = 'stylesheet';\n          mirrored.set(owner, node);\n          target.head.append(node);\n        }\n        if(sheet.media?.mediaText) node.media = sheet.media.mediaText;\n        if((node as HTMLLinkElement).href !== href) (node as HTMLLinkElement).href = href;\n      }\n    }\n\n    for(const [owner, node] of mirrored) {\n      if(!seen.has(owner)) {\n        node.remove();\n        mirrored.delete(owner);\n      }\n    }\n  };\n\n  const copyAttributes = (from: Element, to: Element, names: string[]) => {\n    for(const name of names) {\n      const value = from.getAttribute(name);\n      if(value === null) to.removeAttribute(name);\n      else if(to.getAttribute(name) !== value) to.setAttribute(name, value);\n    }\n  };\n\n  const syncRoot = () => copyAttributes(source.documentElement, target.documentElement, ['class', 'style', 'dir', 'lang']);\n  const syncBody = () => copyAttributes(source.body, target.body, ['class']);\n\n  syncSheets();\n  syncRoot();\n  syncBody();\n\n  let scheduled = false;\n  const scheduleSheets = () => {\n    if(scheduled) return;\n    scheduled = true;\n    Promise.resolve().then(() => {\n      scheduled = false;\n      syncSheets();\n    });\n  };\n\n  // textContent of an existing <style> mutates as a childList change on that descendant.\n  const headObserver = new MutationObserver(scheduleSheets);\n  headObserver.observe(source.head, {childList: true, subtree: true, characterData: true});\n\n  const rootObserver = new MutationObserver(syncRoot);\n  rootObserver.observe(source.documentElement, {attributes: true, attributeFilter: ['class', 'style', 'dir', 'lang']});\n\n  const bodyObserver = new MutationObserver(syncBody);\n  bodyObserver.observe(source.body, {attributes: true, attributeFilter: ['class']});\n\n  return () => {\n    headObserver.disconnect();\n    rootObserver.disconnect();\n    bodyObserver.disconnect();\n    mirrored.clear();\n  };\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport classNames from '@helpers/string/classNames';\nimport styles from './clientPipPlaceholder.module.scss';\n\n/**\n * Shown in the now-empty tab while the client is popped out into a Document Picture-in-Picture window,\n * so the tab doesn't read as a blank page. The button brings the client back without the user having\n * to find the PiP window's own close control.\n */\nexport default function ClientPipPlaceholder(props: {onReturn: () => void}) {\n  return (\n    <div class={styles.screen}>\n      <div class={styles.content}>\n        <div class={styles.title}>\n          <I18nTsx key=\"ClientPip.PlaceholderTitle\" />\n        </div>\n        <div class={styles.description}>\n          <I18nTsx key=\"ClientPip.PlaceholderDescription\" />\n        </div>\n        <button\n          class={classNames('btn-primary', 'btn-color-primary', styles.button)}\n          onClick={() => props.onReturn()}\n        >\n          <I18nTsx key=\"ClientPip.ReturnToTab\" />\n        </button>\n      </div>\n    </div>\n  );\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED from '@environment/documentPictureInPictureSupport';\nimport {setAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport mirrorDocumentStyles from '@helpers/dom/mirrorDocumentStyles';\nimport appChatBackground from '@components/chat/bubbles/chatBackground';\nimport {delegateEvents, render} from 'solid-js/web';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {logger} from '@lib/logger';\nimport ClientPipPlaceholder from '@components/clientPipPlaceholder';\n\nconst log = logger('CLIENT-PIP');\n\n// The whole IM page (`.whole.page-chats` → #main-columns → the sidebars/list/chat). Moving this whole\n// subtree — not just #main-columns — keeps every `.page-chats`-scoped and `body.*`-scoped layout rule\n// matching (the columns collapse if #main-columns is orphaned from its .page-chats ancestor).\nconst APP_ROOT_ID = 'page-chats';\nconst PIP_WIDTH = 430;\nconst PIP_HEIGHT = 760;\n\ntype PipState = {\n  pipWindow: Window,\n  moved: {node: Element, placeholder: Comment}[],\n  placeholderScreen: HTMLElement,\n  disposePlaceholder: () => void,\n  disposeStyles: () => void,\n  cleanup: () => void\n};\n\nlet state: PipState | undefined;\n\nexport function isClientPipOpen() {\n  return !!state;\n}\n\n/**\n * Move the WHOLE live client (`#main-columns`) into `pipWindow`'s document — same app instance, so\n * it's instant (no boot). Pure DOM move + style mirror + metrics rebind; parameterized by the target\n * window so the headless harness can drive it with a plain iframe (which has a real viewport, unlike\n * the 0×0 preview tab). Returns false if already popped out or the shell is missing.\n */\nexport function moveAppToWindow(pipWindow: Window, onReturn: () => void = moveAppBack): boolean {\n  if(state) return false;\n  const appRoot = document.getElementById(APP_ROOT_ID);\n  if(!appRoot) return false;\n\n  const doc = pipWindow.document;\n  const disposeStyles = mirrorDocumentStyles(document, doc);\n\n  // The pip document is bare — give html/body the resets the app shell expects to fill.\n  const reset = doc.createElement('style');\n  reset.textContent = 'html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden}';\n  doc.head.append(reset);\n  doc.title = document.title;\n\n  // Point the metrics layer (windowSize / mediaSizes / updateColumnWidths / --vh) at the pip window\n  // BEFORE the move, so the very first layout pass sizes for the pip viewport instead of the tab's.\n  setAppWindow(pipWindow);\n\n  // Move every top-level app node — the #page-chats shell AND the body-level overlay roots (stories\n  // viewer, audio player, media-recording stage, sidebar drawer overlay, svg defs) — so overlays\n  // opened in the pip have their roots there too. Each leaves a placeholder comment so it returns to\n  // the exact same spot. Skip <script>s and the pip target itself (the harness iframe is in the body).\n  const moved: {node: Element, placeholder: Comment}[] = [];\n  Array.from(document.body.children).forEach((node) => {\n    if(node.tagName === 'SCRIPT') return;\n    if((node as HTMLIFrameElement).contentWindow === pipWindow) return;\n    const placeholder = document.createComment('client-pip');\n    node.before(placeholder);\n    doc.body.append(node); // cross-document adopt; listeners & state survive\n    moved.push({node, placeholder});\n  });\n\n  // Solid delegates onClick/onInput/etc. to the MAIN document (`delegateEvents` defaults to\n  // `window.document`), running ONE handler that walks up from the target to the node's `$$click`\n  // prop. The moved nodes keep those props, but the handler isn't on the pip document — so every\n  // Solid `onClick` is dead in the pip until we install the same delegated handlers there. (The\n  // event-name Set lives at the documented `_$DX_DELEGATE` key.)\n  const delegated = (document as any)['_$DX_DELEGATE'] as Set<string> | undefined;\n  if(delegated?.size) delegateEvents([...delegated], doc);\n\n  // Shown in the now-empty tab so it doesn't read as a blank page; the button brings the client back\n  // without the user having to find the pip window's own close control.\n  const placeholderScreen = document.createElement('div');\n  document.body.append(placeholderScreen);\n  const disposePlaceholder = render(() => <ClientPipPlaceholder onReturn={onReturn} />, placeholderScreen);\n\n  state = {pipWindow, moved, placeholderScreen, disposePlaceholder, disposeStyles, cleanup: () => {}};\n\n  // The wallpaper canvas/gradient renderer doesn't survive the cross-document move — rebuild it fresh\n  // in the pip document.\n  appChatBackground.reRender();\n\n  return true;\n}\n\n/** Move the client back into the main tab and tear down the pip plumbing. */\nexport function moveAppBack(): void {\n  if(!state) return;\n  const {moved, placeholderScreen, disposePlaceholder, disposeStyles, cleanup} = state;\n  cleanup();\n  disposePlaceholder();\n  placeholderScreen.remove();\n  setAppWindow(window); // rebind metrics to the tab before the move so it reflows for the real viewport\n  moved.forEach(({node, placeholder}) => placeholder.replaceWith(node));\n\n  // Same as on the way out — the wallpaper canvas didn't survive moving back; rebuild it in the tab.\n  appChatBackground.reRender();\n\n  disposeStyles();\n  state = undefined;\n}\n\n/**\n * Return the client to the tab AND dismiss the pip window. Mirrors the internal `closePip` closure wired\n * to the pip's own pagehide/visibility auto-return; exported so the \"Exit Picture-in-Picture\" menu entry\n * (and any other in-app affordance) can close the pip without the user reaching for the OS chrome.\n */\nexport function closeClientPip(): void {\n  const pipWindow = state?.pipWindow;\n  moveAppBack();\n  try {\n    pipWindow?.close();\n  } catch{}\n}\n\n/**\n * Pop the whole client out into an always-on-top Document Picture-in-Picture window. MUST be called\n * from a user gesture (the topbar button) so `requestWindow` is permitted. Auto-returns: once the tab\n * has actually been left and is then re-shown, the app moves back and the pip closes.\n */\nexport default async function openClientPip(): Promise<void> {\n  if(!DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED) return;\n  if(state) {\n    try {\n      state.pipWindow.focus();\n    } catch{}\n    return;\n  }\n\n  let pipWindow: Window;\n  try {\n    pipWindow = await window.documentPictureInPicture!.requestWindow({width: PIP_WIDTH, height: PIP_HEIGHT});\n  } catch(err) {\n    log.error('requestWindow failed', err);\n    return;\n  }\n\n  const closePip = () => {\n    moveAppBack();\n    try {\n      pipWindow.close();\n    } catch{}\n  };\n\n  if(!moveAppToWindow(pipWindow, closePip)) {\n    try {\n      pipWindow.close();\n    } catch{}\n    return;\n  }\n\n  let leftTab = false;\n  const onVisibility = () => {\n    if(document.visibilityState === 'hidden') leftTab = true;\n    else if(leftTab) closePip();\n  };\n\n  state.cleanup = () => {\n    document.removeEventListener('visibilitychange', onVisibility);\n    pipWindow.removeEventListener('pagehide', closePip);\n  };\n\n  document.addEventListener('visibilitychange', onVisibility);\n  // Dismissing via the OS chrome fires `pagehide`, not our close().\n  pipWindow.addEventListener('pagehide', closePip);\n}\n\n// Expose the core for the headless harness — a plain iframe (real viewport) stands in for the pip\n// window, letting the move + metrics-rebind be validated where requestWindow can't run.\nMOUNT_CLASS_TO && ((MOUNT_CLASS_TO as any).clientPip = {moveAppToWindow, moveAppBack, closeClientPip, openClientPip, isClientPipOpen, getOverlayRoot});\n","import {MOUNT_CLASS_TO} from '@config/debug';\n\nexport default function createElementFromMarkup<T = Element>(markup: string) {\n  const div = document.createElement('div');\n  div.innerHTML = markup.trim();\n  return div.firstElementChild as T;\n}\nMOUNT_CLASS_TO.createElementFromMarkup = createElementFromMarkup;\n","import {getOverlayRoot} from '@helpers/appWindow';\nimport createElementFromMarkup from '@helpers/createElementFromMarkup';\nimport {GrabEvent} from '@helpers/dom/attachGrabListeners';\nimport safePlay from '@helpers/dom/safePlay';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {VideoTimestamp} from '@components/mediaViewer/base';\nimport RangeSelector from '@components/rangeSelector';\nimport {observeResize} from '@components/resizeObserver';\n\nconst MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH = 7; // -2px padding will be 5px\n\ntype VideoTimestampSegment = {\n  time: number;\n  left: number;\n  right: number;\n}\n\nexport default class MediaProgressLine extends RangeSelector {\n  protected filledContainer?: HTMLDivElement;\n  protected filledLoad: HTMLDivElement;\n\n  protected currentTimeInfoElement?: HTMLDivElement;\n  protected currentTimeElement?: HTMLDivElement;\n  protected currentSegmentElement?: HTMLDivElement;\n\n  protected progressRAF: number;\n\n  protected media: HTMLMediaElement;\n  protected streamable: boolean;\n\n  protected static svgClipPathIdSeed = 0;\n  protected usedClipPathId: number;\n  protected clipPathSvg: SVGSVGElement;\n\n  protected segments: VideoTimestampSegment[] = [];\n  // protected lastOnPlayTime: number;\n  // protected lastOnPlayCurrentTime: number;\n\n  protected unobserveResize?: () => void;\n  protected activeSegmentIdx: number;\n  protected hoverRAF: number;\n\n  constructor(protected options: {\n    withTransition?: boolean,\n    useTransform?: boolean,\n    onSeekStart?: () => void,\n    onSeekEnd?: () => void,\n    onTimeUpdate?: (time: number) => void,\n    onHover?: (progress: number) => void,\n    onPointerOut?: () => void,\n    videoTimestamps?: VideoTimestamp[],\n    withTime?: boolean,\n    appendToTimeElement?: HTMLElement\n  } = {}) {\n    super({\n      step: 1000 / 60 / 1000,\n      min: 0,\n      max: 1,\n      withTransition: options.withTransition,\n      useTransform: options.useTransform\n    }, 0);\n  }\n\n  public setMedia({\n    media,\n    streamable,\n    duration\n  }: {\n    media: HTMLMediaElement,\n    streamable?: boolean,\n    duration?: number\n  }) {\n    if(this.media) {\n      this.removeListeners();\n    }\n\n    if(streamable && !this.filledLoad) {\n      this.filledLoad = document.createElement('div');\n      this.filledLoad.classList.add('progress-line__filled', 'progress-line__loaded');\n      this.container.prepend(this.filledLoad);\n      // this.setLoadProgress();\n    } else if(this.filledLoad) {\n      this.filledLoad.classList.toggle('hide', !streamable);\n    }\n\n    this.media = media;\n    this.streamable = streamable;\n\n    // Before anything draws: both bars divide by `max`, which is still the constructor's 1 until\n    // this runs. A media that is already positioned and paused — reopening a chat on a track you\n    // stopped halfway — never fires an event afterwards to correct a bar drawn against the wrong\n    // max, so it would sit at 100% for good.\n    this.setSeekMax(duration);\n\n    if(!media.paused || media.currentTime > 0) {\n      this.onPlay();\n    }\n\n    this.setTimestampsClipPath();\n\n    let wasPlaying = false;\n    this.setListeners();\n    this.setHandlers({\n      onMouseDown: () => {\n        wasPlaying = !this.media.paused;\n        wasPlaying && this.media.pause();\n        this.options?.onSeekStart?.();\n        this.container.classList.add('media-progress-line--seeking');\n      },\n\n      onMouseUp: (e) => {\n        // cancelEvent(e.event);\n        wasPlaying && safePlay(this.media);\n        this.options?.onSeekEnd?.();\n        this.container.classList.remove('media-progress-line--seeking');\n      }\n    });\n  }\n\n  protected initResizeObserver() {\n    this.unobserveResize?.();\n    this.unobserveResize = observeResize(this.filledContainer, () => {\n      this.setTimestampsClipPath();\n    });\n  }\n\n  protected onHover = (e: MouseEvent) => {\n    if(this.hoverRAF) {\n      return;\n    }\n\n    if(this.options.onHover) {\n      this.rect = this.container.getBoundingClientRect();\n      this.options.onHover(this.getValueByEvent({x: e.pageX, y: e.pageY, event: e}));\n    }\n\n    if(!this.filledContainer) {\n      return;\n    }\n\n    if(this.activeSegmentIdx !== undefined) {\n      this.toggleSegment(this.activeSegmentIdx, false);\n    }\n\n    const bcr = this.filledContainer.getBoundingClientRect();\n    const x = e.clientX - bcr.left;\n\n    const segmentIdx = this.segments.findIndex((segment) => segment.left <= x && x <= segment.right);\n    if(segmentIdx >= 0) {\n      this.activeSegmentIdx = segmentIdx;\n      this.toggleSegment(segmentIdx, true);\n    }\n\n    this.updateTimeAndSegment(x, bcr.width);\n  }\n\n  protected onPointerOut = () => {\n    this.options.onPointerOut?.();\n\n    if(this.filledContainer) {\n      this.toggleSegment(this.activeSegmentIdx, false);\n      this.activeSegmentIdx = undefined;\n    }\n  }\n\n  protected toggleSegment(idx: number, active: boolean) {\n    const element = this.clipPathSvg?.querySelector(`rect:nth-child(${idx + 1})`);\n    if(!element) {\n      return;\n    }\n\n    if(active) element.setAttribute('data-active', 'true');\n    else element.removeAttribute('data-active');\n  }\n\n  protected wrapProgressLinesInContainer() {\n    if(this.filledContainer) {\n      return;\n    }\n\n    this.container.classList.add('media-progress-line');\n\n    this.filledContainer = document.createElement('div');\n    this.filledContainer.classList.add('media-progress-line__filled-container');\n\n    const thumb = document.createElement('div');\n    thumb.classList.add('media-progress-line__thumb');\n\n    this.currentTimeInfoElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-time-info');\n\n    this.currentTimeElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-time');\n\n    this.currentSegmentElement = document.createElement('div');\n    this.currentTimeInfoElement.classList.add('media-progress-line__current-segment');\n\n    this.currentTimeInfoElement.append(...[\n      this.options.appendToTimeElement,\n      this.currentSegmentElement,\n      this.currentTimeElement\n    ].filter(Boolean));\n\n    this.filledContainer.append(this.filled, this.filledLoad);\n\n    this.container.prepend(this.filledContainer);\n    this.container.append(thumb, this.currentTimeInfoElement);\n\n    this.initResizeObserver();\n  }\n\n  protected clearTimeAndSegment() {\n    this.currentTimeElement.textContent = '';\n    this.currentSegmentElement.textContent = '';\n  }\n\n  protected updateTimeAndSegment(x: number, width: number) {\n    if(!this.media || !this.currentTimeInfoElement) {\n      return;\n    }\n\n    if(x < 0 || x > width) {\n      this.clearTimeAndSegment();\n      return;\n    }\n\n    const formattedTime = toHHMMSS(x / width * this.media.duration | 0);\n    this.currentTimeElement.textContent = formattedTime;\n\n    if(this.segments?.length > 0) {\n      const segment = this.segments.find((segment) => segment.left <= x && x <= segment.right);\n      const timestamp = this.options.videoTimestamps?.find((timestamp) => timestamp.time === segment.time);\n      this.currentSegmentElement.textContent = limitSymbols(timestamp?.text || '', 24, 27);\n    }\n\n    const infoBcr = this.currentTimeInfoElement.getBoundingClientRect();\n\n    const pushFromRight = Math.min(0, width - (x + infoBcr.width / 2));\n    const pushFromLeft = Math.max(0, infoBcr.width / 2 - x);\n\n    this.currentTimeInfoElement.style.setProperty('--current-time-info-x', x + pushFromLeft + pushFromRight + 'px');\n  }\n\n  protected setTimestampsClipPath() {\n    this.removeClipPathFromDOM();\n    this.segments = [];\n\n    if(!this.options.videoTimestamps?.length && !this.options.withTime) {\n      return;\n    }\n\n    this.wrapProgressLinesInContainer();\n\n    const bcr = this.filledContainer.getBoundingClientRect();\n    const totalWidth = bcr.width;\n\n    const segments = this.segments = this.getTimestampSegments(totalWidth);\n    if(!segments?.length) {\n      return;\n    }\n\n    const margin = 1;\n\n    const rects = segments.map((segment) => `<rect x=\"${\n      (segment.left + margin).toFixed(2)\n    }\" width=\"${\n      (segment.right - segment.left - 2 * margin).toFixed(2)\n    }\" rx=\"1\" />`);// }\"\n\n    this.usedClipPathId = ++MediaProgressLine.svgClipPathIdSeed;\n\n    const svgId = `media-progress-line-clip-path-svg-${MediaProgressLine.svgClipPathIdSeed}`;\n    const clipPathId = `media-progress-line-clip-path-${MediaProgressLine.svgClipPathIdSeed}`;\n\n    this.removeClipPathFromDOM();\n\n    this.clipPathSvg = createElementFromMarkup(`\n      <svg width=\"0\" height=\"0\" class=\"media-progress-line-clip-path-svg\" id=\"${svgId}\">\n        <clipPath id=\"${clipPathId}\">\n          ${rects.join('\\n')}\n        </clipPath>\n      </svg>\n    `);\n\n    getOverlayRoot().append(this.clipPathSvg);\n\n    this.filledContainer.style.clipPath = `url(#${clipPathId})`;\n  }\n\n  protected getTimestampSegments(totalWidth: number) {\n    const {videoTimestamps} = this.options;\n    if(!videoTimestamps?.length || !this.filledContainer) {\n      return [];\n    }\n\n    const duration = this.media.duration;\n    if(!duration) {\n      return [];\n    }\n\n    const timePoints = videoTimestamps.map(({time}) => time)\n    .filter((time) => time >= 0 && time <= duration)\n    .sort((a, b) => a - b);\n\n    if(timePoints[0] !== 0) timePoints.unshift(0);\n    timePoints.push(duration);\n\n    const result: VideoTimestampSegment[] = [];\n\n    let prevRight = 0;\n    for(let i = 0; i < timePoints.length - 1; i++) {\n      const left = Math.max(prevRight, timePoints[i] / duration * totalWidth);\n      let right = timePoints[i + 1] / duration * totalWidth;\n\n      if(right <= left) {\n        continue;\n      }\n\n      right = Math.max(right, left + MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH);\n      prevRight = right;\n\n      if(right + MIN_VIDEO_TIMESTAMP_SEGMENT_WIDTH >= totalWidth) right = totalWidth;\n\n      result.push({\n        left,\n        right,\n        time: timePoints[i]\n      });\n\n      if(right === totalWidth) {\n        break;\n      }\n    }\n\n    return result;\n  }\n\n  public removeClipPathFromDOM() {\n    this.clipPathSvg?.remove();\n  }\n\n  protected onLoadedData = () => {\n    this.setSeekMax();\n    this.setTimestampsClipPath();\n  };\n\n  protected onEnded = () => {\n    this.setProgress();\n  };\n\n  protected onPlay = () => {\n    const r = () => {\n      this.setProgress();\n\n      this.progressRAF = this.media.paused ? undefined : window.requestAnimationFrame(r);\n    };\n\n    if(this.progressRAF) {\n      window.cancelAnimationFrame(this.progressRAF);\n      this.progressRAF = undefined;\n    }\n\n    if(this.streamable) {\n      this.setLoadProgress();\n    }\n\n    // this.lastOnPlayTime = Date.now();\n    // this.lastOnPlayCurrentTime = this.media.currentTime;\n    r();\n    // this.progressRAF = window.requestAnimationFrame(r);\n  };\n\n  protected onTimeUpdate = () => {\n    if(this.media.paused) {\n      this.setProgress();\n\n      if(this.streamable) {\n        this.setLoadProgress();\n      }\n    }\n  };\n\n  protected onProgress = (e: Event) => {\n    this.setLoadProgress();\n  };\n\n  protected scrub(e: GrabEvent) {\n    let scrubTime = super.scrub(e, this.snapScrubValue);\n    // avoid `ended` when scrubbing to the end\n    if(this.media.duration && scrubTime >= this.media.duration) {\n      scrubTime = this.media.duration - 0.1;\n    }\n    setCurrentTime(this.media, scrubTime);\n    return scrubTime;\n  }\n\n  protected snapScrubValue = (value: number) => {\n    if(!this.segments?.length) {\n      return value;\n    }\n\n    const totalWidth = this.segments[this.segments.length - 1].right;\n    const x = value / this.media.duration * totalWidth;\n    for(const segment of this.segments) {\n      if(segment.left - 2 <= x && x <= segment.left + 3) {\n        return segment.time;\n      }\n    }\n\n    return value;\n  }\n\n  protected setLoadProgress() {\n    if(appMediaPlaybackController.isSafariBuffering(this.media)) {\n      return;\n    }\n\n    const buf = this.media.buffered;\n    const numRanges = buf.length;\n\n    const currentTime = this.media.currentTime;\n    let nearestStart = 0, end = 0;\n    for(let i = 0; i < numRanges; ++i) {\n      const start = buf.start(i);\n      if(currentTime >= start && start >= nearestStart) {\n        nearestStart = start;\n        end = buf.end(i);\n      }\n\n      // console.log('onProgress range:', i, buf.start(i), buf.end(i), this.media);\n    }\n\n    // console.log('onProgress correct range:', nearestStart, end, this.media);\n\n    const percents = this.max ? end / this.max : 0;\n    this.filledLoad.style.width = (percents * 100) + '%';\n    // this.filledLoad.style.transform = 'scaleX(' + percents + ')';\n  }\n\n  protected setSeekMax(duration?: number) {\n    const realDuration = this.media.duration || 0;\n    if(duration === undefined || realDuration) duration = realDuration;\n    if(this.max = duration) {\n      this.seek.setAttribute('max', '' + this.max);\n    } else {\n      this.media.addEventListener('loadeddata', this.onLoadedData);\n    }\n  }\n\n  public setProgress() {\n    if(appMediaPlaybackController.isSafariBuffering(this.media)) {\n      return;\n    }\n\n    // fix jumping progress on play\n    // let currentTime: number;\n    // const diff = (Date.now() - this.lastOnPlayTime) / 1000;\n    // if(!this.media.paused && this.lastOnPlayTime && diff <= 1) {\n    //   currentTime = this.lastOnPlayCurrentTime + diff;\n    // } else {\n    //   currentTime = this.media.currentTime;\n    // }\n\n    const currentTime = this.media.currentTime;\n    this.options.onTimeUpdate?.(currentTime);\n    super.setProgress(currentTime);\n\n    this.container.style.setProperty('--progress', currentTime / this.media.duration + '');\n  }\n\n  public setListeners() {\n    super.setListeners();\n    this.media.addEventListener('ended', this.onEnded);\n    this.media.addEventListener('play', this.onPlay);\n    this.media.addEventListener('pause', this.onTimeUpdate);\n    this.media.addEventListener('timeupdate', this.onTimeUpdate);\n    this.streamable && this.media.addEventListener('progress', this.onProgress);\n\n    if(this.options.onHover || this.options.videoTimestamps || this.options.withTime) {\n      this.container.addEventListener('pointermove', this.onHover);\n      this.container.addEventListener('pointerout', this.onPointerOut);\n    }\n  }\n\n  public removeListeners() {\n    super.removeListeners();\n\n    if(this.media) {\n      this.media.removeEventListener('loadeddata', this.onLoadedData);\n      this.media.removeEventListener('ended', this.onEnded);\n      this.media.removeEventListener('play', this.onPlay);\n      this.media.removeEventListener('pause', this.onTimeUpdate);\n      this.media.removeEventListener('timeupdate', this.onTimeUpdate);\n      this.streamable && this.media.removeEventListener('progress', this.onProgress);\n    }\n\n    this.container.removeEventListener('pointermove', this.onHover);\n    this.container.removeEventListener('pointerout', this.onPointerOut);\n\n    if(this.progressRAF) {\n      window.cancelAnimationFrame(this.progressRAF);\n      this.progressRAF = undefined;\n    }\n  }\n\n  public cleanup() {\n    this.removeClipPathFromDOM();\n    this.removeListeners();\n    this.unobserveResize?.();\n    this.segments = [];\n  }\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {_tgico} from '@helpers/tgico';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {replaceButtonIcon} from '@components/button';\nimport RangeSelector from '@components/rangeSelector';\n\nconst className = 'player-volume';\n\nexport default class VolumeSelector extends RangeSelector {\n  private static ICONS: Icon[] = ['volume_off_filled', 'volume_mute_filled', 'volume_down_filled', 'volume_up_filled'];\n  public btn: HTMLElement;\n  protected icon: HTMLSpanElement;\n  protected listenerSetter: ListenerSetter;\n  protected vertical: boolean;\n  protected media: HTMLMediaElement;\n  protected useGlobalVolume: 'auto' | 'no-init';\n  protected onVolumeChange: (type: 'global' | 'click') => void;\n  protected ignoreGlobalEvents: boolean;\n\n  constructor(options: {\n    listenerSetter: ListenerSetter,\n    useGlobalVolume?: VolumeSelector['useGlobalVolume'],\n    vertical?: boolean,\n    media?: HTMLMediaElement,\n    maxVolume?: number,\n    onVolumeChange?: VolumeSelector['onVolumeChange']\n  }) {\n    super({\n      step: 0.01,\n      min: 0,\n      max: options.maxVolume ?? 1,\n      vertical: options.vertical\n    }, 1);\n\n    safeAssign(this, options);\n\n    this.setListeners();\n    this.setHandlers({\n      onScrub: (_value) => {\n        const value = Math.max(Math.min(_value, this.max), 0);\n\n        if(this.useGlobalVolume) {\n          this.modifyGlobal(() => {\n            appMediaPlaybackController.muted = false;\n            this.writeGlobalVolume(value);\n          });\n        }\n\n        this.setVolume({volume: value, muted: false, eventType: 'click'});\n      }\n\n      /* onMouseUp: (e) => {\n        cancelEvent(e.event);\n      } */\n    });\n\n    const btn = this.btn = document.createElement('div');\n    btn.classList.add('btn-icon', className);\n\n    attachClickEvent(btn, (e) => {\n      if(!findUpClassName(e.target, className + '__icon') && e.target !== this.btn) {\n        return;\n      }\n\n      this.onMuteClick(e);\n    }, {listenerSetter: this.listenerSetter});\n\n    if(this.useGlobalVolume) {\n      this.listenerSetter.add(appMediaPlaybackController)('playbackParams', (params) => {\n        if(this.ignoreGlobalEvents) {\n          return;\n        }\n\n        this.setVolume({volume: this.readGlobalVolume(), muted: params.muted, eventType: 'global'});\n      });\n\n      if(this.useGlobalVolume === 'no-init') {\n        this.setVolume({volume: this.readGlobalVolume(), muted: this.media.muted});\n      } else {\n        this.setGlobalVolume();\n      }\n    } else if(this.media) {\n      this.setVolume({volume: this.media.volume, muted: this.media.muted});\n    }\n\n    btn.append(this.container);\n  }\n\n  public removeListeners() {\n    super.removeListeners();\n    this.onVolumeChange = undefined;\n  }\n\n  private modifyGlobal(callback: () => void) {\n    this.ignoreGlobalEvents = true;\n    callback();\n    this.ignoreGlobalEvents = false;\n  }\n\n  private onMuteClick(e?: Event) {\n    e && cancelEvent(e);\n\n    const globalMuted = appMediaPlaybackController.muted;\n    const {volume, muted} = this.media ?? {};\n\n    if(this.useGlobalVolume) {\n      this.modifyGlobal(() => {\n        appMediaPlaybackController.muted = !globalMuted;\n      });\n    }\n\n    this.setVolume({\n      volume: volume ?? this.readGlobalVolume(),\n      muted: !(muted ?? globalMuted),\n      eventType: 'click'\n    });\n  }\n\n  /**\n   * Read the global volume this selector tracks. A selector bound to a concrete media\n   * element (the video player) always follows the shared master `volume`. The global-only\n   * selector (pinned audio plate) follows the playing media: for voice that's `volume +\n   * boost` (its 0–200% range), so the boost shows on the slider without leaking elsewhere.\n   */\n  protected readGlobalVolume() {\n    return this.media ? appMediaPlaybackController.volume : appMediaPlaybackController.getGlobalSliderVolume();\n  }\n\n  /**\n   * Write a slider value back to the controller. With a local media element it sets the\n   * shared master directly; the global-only selector routes through the controller, which\n   * splits a voice value into shared master (0–100%) + voice-only boost (100–200%).\n   */\n  protected writeGlobalVolume(value: number) {\n    if(this.media) {\n      appMediaPlaybackController.volume = value;\n    } else {\n      appMediaPlaybackController.setGlobalSliderVolume(value);\n    }\n  }\n\n  public setVolume = ({volume, muted, eventType}: {volume: number, muted: boolean, eventType?: 'global' | 'click'}) => {\n    let iconIndex: number;\n    if(!volume || muted) {\n      iconIndex = 0;\n    } else if(volume > .5) {\n      iconIndex = 3;\n    } else if(volume > 0 && volume < .25) {\n      iconIndex = 1;\n    } else {\n      iconIndex = 2;\n    }\n\n    const newIcon = replaceButtonIcon(this.btn, VolumeSelector.ICONS[iconIndex]);\n    newIcon.classList.add(className + '__icon');\n\n    if(this.media) {\n      // HTMLMediaElement only accepts [0, 1]; the master volume is already clamped, but a\n      // boosted voice value (or a stale persisted >1) must never reach the element directly.\n      this.media.volume = Math.min(volume, 1);\n      this.media.muted = muted;\n    }\n\n    if(!this.mousedown) {\n      this.setProgress(muted ? 0 : volume);\n    }\n\n    eventType && this.onVolumeChange?.(eventType);\n  };\n\n  public setGlobalVolume = (eventType?: Parameters<VolumeSelector['setVolume']>[0]['eventType']) => {\n    const volume = this.readGlobalVolume();\n    const muted = appMediaPlaybackController.muted;\n    return this.setVolume({volume, muted, eventType});\n  };\n\n  public setMaxVolume = (max: number) => {\n    if(this.max === max) return;\n    this.max = max;\n    this.seek.max = '' + max;\n    this.setFilled(+this.seek.value);\n  };\n}\n","export default function createCanvasStream({width = 0, height = 0, image}: Partial<{width: number, height: number, image: CanvasImageSource}> = {}) {\n  const canvas = document.createElement('canvas');\n  canvas.width = width;\n  canvas.height = height;\n  const stream = canvas.captureStream();\n  stream.getVideoTracks()[0].enabled = true;\n  const context = canvas.getContext('2d');\n  if(image) {\n    context.drawImage(image, 0, 0, width, height);\n    context.globalAlpha = 0.5;\n    context.fillStyle = '#000';\n    context.fillRect(0, 0, width, height);\n  } else {\n    context.fillRect(0, 0, width, height);\n  }\n  return stream;\n}\n","import {HlsStandardResolutionHeight} from '@lib/hls/types';\n\nexport function snapQualityHeight(height: number) {\n  const standardHeights: HlsStandardResolutionHeight[] = [480, 720, 1080];\n\n  const threshold1 = (standardHeights[1] - standardHeights[0]) / 2;\n  if(height < standardHeights[0] + threshold1) return standardHeights[0];\n\n  const threshold2 = (standardHeights[2] - standardHeights[1]) / 2;\n  if(height < standardHeights[1] + threshold2) return standardHeights[1];\n\n  return standardHeights[2];\n}\n","import {createEffect, createMemo, createSignal, Show, JSX} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport type {Level} from 'hls.js';\n\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport Icon from '@components/icon';\nimport deferredPromise from '@helpers/cancellablePromise';\n\nimport {hlsInstancesByVideo} from '@lib/hls/hlsInstancesByVideo';\nimport {HlsStandardResolutionHeight} from '@lib/hls/types';\nimport {snapQualityHeight} from '@lib/hls/snapQualityHeight';\nimport {i18n, LangPackKey} from '@lib/langPack';\n\ntype QualityLevelsSwitchButtonProps = {\n  video: HTMLVideoElement;\n  skin: string;\n  onMenuToggle?: (open: boolean) => void;\n};\n\ntype InternalQualityLevelsSwitchButtonProps = QualityLevelsSwitchButtonProps & {\n  controlsRef: (value: QualityLevelsSwitchButtonControls) => void;\n}\n\ntype QualityLevelsSwitchButtonControls = {\n  loadQualityLevels: () => Promise<void>;\n  isMenuOpen: () => boolean;\n}\n\nfunction QualityLevelsSwitchButton(props: InternalQualityLevelsSwitchButtonProps) {\n  const [qualityLevelsMenuButtons, setQualityLevelsMenuButtons] = createSignal<ButtonMenuItemOptionsVerifiable[]>([]);\n\n  const [selectedHeight, setSelectedHeight] = createSignal<HlsStandardResolutionHeight>();\n  const [qualityLevelsLoaded, setQualityLevelsLoaded] = createSignal(false);\n\n  const controls: QualityLevelsSwitchButtonControls = {\n    loadQualityLevels: async() => {\n      setQualityLevelsLoaded(true);\n    },\n    isMenuOpen: () => {\n      return qualityLevelsButton().classList.contains('menu-open');\n    }\n  };\n\n  props.controlsRef(controls);\n\n  // Uncomment during development\n  // createEffect(() => {\n  //   setQualityLevelsLoaded(true);\n  // });\n\n  createEffect(() => {\n    if(qualityLevelsLoaded()) (async() => {\n      const options = await getButtonMenuQualityOptions(props.video, setSelectedHeight);\n      setQualityLevelsMenuButtons(options);\n    })();\n  });\n\n  createEffect(() => {\n    if(qualityLevelsLoaded()) {\n      qualityLevelsMenuButtons().forEach((btn) => btn.icon = undefined);\n      const selectedMenuButton = qualityLevelsMenuButtons().find((btn) => btn.id === (selectedHeight() || 'auto'));\n      if(selectedMenuButton) selectedMenuButton.icon = 'check';\n    }\n  });\n\n  const qualityLevelsButton = createMemo(() => ButtonMenuToggle({\n    icon: `settings ${props.skin}__button checkable-button-menu quality-levels-switch-button`,\n    buttons: qualityLevelsMenuButtons(),\n    direction: 'top-left',\n    onOpen: () => {\n      props.onMenuToggle?.(true);\n    },\n    onClose: () => {\n      props.onMenuToggle?.(false);\n    }\n  }));\n\n  createEffect(() => {\n    qualityLevelsButton()?.append(HdSvg() as HTMLElement);\n  });\n\n  createEffect(() => {\n    const isHd = selectedHeight() === 1080;\n\n    qualityLevelsButton()?.querySelector('.tgico')?.replaceWith(Icon(isHd ? 'settings_clipped_corner' : 'settings'));\n    qualityLevelsButton()?.classList.toggle('quality-levels-switch-button--is-hd', isHd);\n  });\n\n  return <Show when={qualityLevelsMenuButtons().length > 0}>{qualityLevelsButton()}</Show>;\n}\n\nexport function createQualityLevelsSwitchButton(props: QualityLevelsSwitchButtonProps) {\n  const element = document.createElement('div');\n  let controls: QualityLevelsSwitchButtonControls;\n\n  const dispose = render(\n    () => (\n      <QualityLevelsSwitchButton\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n\nexport function ButtonMenuItemWithAuxiliaryText(mainText: LangPackKey, additionalText: JSX.Element) {\n  return  (\n    <span class=\"btn-menu-item-with-auxiliary-text\">\n      {i18n(mainText)}\n      <span class=\"btn-menu-item-auxiliary-text\">{additionalText}</span>\n    </span>\n  );\n}\n\nexport function ButtonMenuItemQualityText(height: HlsStandardResolutionHeight) {\n  return ButtonMenuItemWithAuxiliaryText(`Hls.ResolutionHeightName${height}`, `${height}p`);\n}\n\nasync function getButtonMenuQualityOptions(\n  video: HTMLVideoElement,\n  onHeightSelect: (level?: HlsStandardResolutionHeight) => void\n) {\n  const hls = hlsInstancesByVideo.get(video);\n  if(!hls) return [];\n\n  const deferredLevels = deferredPromise<Level[]>();\n\n  const {default: Hls} = await import('hls.js');\n\n  if(hls.levels && hls.levels.length > 0) {\n    deferredLevels.resolve(hls.levels);\n  } else hls.on(Hls.Events.MANIFEST_PARSED, (_, data) => {\n    deferredLevels.resolve(data.levels);\n  });\n\n  const levels = await deferredLevels;\n\n  const availableHeights = Array.from(new Set(levels.map((level) => snapQualityHeight(level.height))))\n  .sort((a, b) => b - a);\n\n  const qualityButtons = availableHeights.map((height): ButtonMenuItemOptionsVerifiable => {\n    const levelsOfThisHeight = levels.filter((level) => snapQualityHeight(level.height) === height)\n    .sort((a, b) => a.bitrate - b.bitrate);\n\n    const onClick = () => {\n      let optimalLevel = levelsOfThisHeight[0];\n      for(const level of levelsOfThisHeight) {\n        if(level.bitrate < hls.bandwidthEstimate) optimalLevel = level;\n      }\n      const idx = levels.indexOf(optimalLevel);\n\n      hls.currentLevel = idx;\n      onHeightSelect(height);\n      // hls.autoLevelCapping = idx;\n    }\n\n    return {\n      id: height,\n      emptyIcon: true,\n      regularText: ButtonMenuItemQualityText(height) as HTMLElement,\n      onClick\n    };\n  });\n\n  const result: ButtonMenuItemOptionsVerifiable[] = [\n    {\n      id: 'auto',\n      text: 'Hls.ResolutionHeightAuto',\n      emptyIcon: true,\n      onClick: () => {\n        hls.currentLevel = -1;\n        onHeightSelect();\n      // hls.autoLevelCapping = -1;\n      }\n    },\n    ...qualityButtons\n  ];\n\n  return result;\n}\n\nfunction HdSvg() {\n  return (\n    <svg class='quality-levels-switch-button__hd-icon' width=\"14\" height=\"10\" viewBox=\"0 0 14 10\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"14\" height=\"10\" rx=\"2\" fill=\"currentColor\"/>\n      <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M3.5 2.5C3.5 2.08579 3.16421 1.75 2.75 1.75C2.33579 1.75 2 2.08579 2 2.5V5V7.5C2 7.91421 2.33579 8.25 2.75 8.25C3.16421 8.25 3.5 7.91421 3.5 7.5V5.75H5V7.5C5 7.91421 5.33579 8.25 5.75 8.25C6.16421 8.25 6.5 7.91421 6.5 7.5V5V2.5C6.5 2.08579 6.16421 1.75 5.75 1.75C5.33579 1.75 5 2.08579 5 2.5V4.25H3.5V2.5ZM8.25 1.75C7.83579 1.75 7.5 2.08579 7.5 2.5V7.5C7.5 7.91421 7.83579 8.25 8.25 8.25H9.75C11.2688 8.25 12.5 7.01878 12.5 5.5V4.5C12.5 2.98122 11.2688 1.75 9.75 1.75H8.25ZM9.75 6.75H9V3.25H9.75C10.4404 3.25 11 3.80964 11 4.5V5.5C11 6.19036 10.4404 6.75 9.75 6.75Z\" fill=\"black\"/>\n    </svg>\n  );\n}\n","import {createEffect, createSignal} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport Icon from '@components/icon';\n\ntype PlaybackRateButtonProps = {\n  skin: string;\n  onMenuToggle: (open: boolean) => void;\n};\n\ntype InternalPlaybackRateButtonProps = PlaybackRateButtonProps & {\n  controlsRef: (value: PlaybackRateButtonControls) => void;\n}\n\ntype PlaybackRateButtonControls = {\n  setPlayBackRate: (value: number | ((val: number) => number)) => void;\n  changeRateByAmount: (amount: number) => void;\n  isMenuOpen: () => boolean;\n}\n\nconst rates = [0.5, 1, 1.5, 2, 3];\nconst MAX_RATE = 5;\n\nconst geometricFontMap: Record<string, Icon> = {\n  '0': 'geometric_digit_0',\n  '1': 'geometric_digit_1',\n  '2': 'geometric_digit_2',\n  '3': 'geometric_digit_3',\n  '4': 'geometric_digit_4',\n  '5': 'geometric_digit_5',\n  '6': 'geometric_digit_6',\n  '7': 'geometric_digit_7',\n  '8': 'geometric_digit_8',\n  '9': 'geometric_digit_9',\n  'x': 'geometric_letter_x',\n  '.': 'geometric_dot'\n};\n\nfunction PlaybackRateButton(props: InternalPlaybackRateButtonProps) {\n  const [selectedRate, setSelectedRate] = createSignal<number>(appMediaPlaybackController.playbackRate || 1);\n\n  const controls: PlaybackRateButtonControls = {\n    setPlayBackRate: setSelectedRate,\n    changeRateByAmount: (amount) => {\n      const newValue = selectedRate() + amount;\n      if(newValue < 1) {\n        setSelectedRate(0.5);\n      } else {\n        setSelectedRate(Math.min(MAX_RATE, Math.round(newValue - 0.01)));\n      }\n      appMediaPlaybackController.playbackRate = selectedRate();\n    },\n    isMenuOpen: () => {\n      return playbackRateButton.classList.contains('menu-open');\n    }\n  };\n\n  props.controlsRef(controls);\n\n  const buttons: ButtonMenuItemOptionsVerifiable[] = rates.map((rate) => ({\n    id: rate.toFixed(1),\n    emptyIcon: true,\n    onClick: () => {\n      appMediaPlaybackController.playbackRate = rate;\n      setSelectedRate(rate);\n    },\n    text: rate === 1 ? 'PlaybackRateNormal' : undefined,\n    regularText: rate !== 1 ? rate + 'x' : undefined\n  }));\n\n  createEffect(() => {\n    buttons.forEach((btn) => btn.icon = undefined);\n    const button = buttons.find((btn) => btn.id === selectedRate().toFixed(1));\n    if(button) button.icon = 'check';\n  });\n\n  createEffect(() => {\n    const cls = 'playback-speed-icon-floating';\n    playbackRateButton.querySelector(`.${cls}`)?.remove();\n\n    const rateAsString = selectedRate().toFixed(1).replace(/\\.0$/, 'x');\n\n    const icons = rateAsString.split('').map((char) => ({\n      char: char === '.' ? 'dot': char,\n      icon: geometricFontMap[char]\n    })).filter(Boolean);\n\n    const rateElement = document.createElement('span');\n    rateElement.classList.add(cls);\n\n    rateElement.append(...icons.map((({char, icon}) => Icon(icon, 'geometric-font-icon', `geometric-font-icon--${char}`))));\n\n    playbackRateButton.append(rateElement);\n  });\n\n  const playbackRateButton = ButtonMenuToggle({\n    icon: `mediaspeed_empty ${props.skin}__button`,\n    buttons,\n    direction: 'top-left',\n    onOpen: () => {\n      props.onMenuToggle?.(true);\n    },\n    onClose: () => {\n      props.onMenuToggle?.(false);\n    }\n  });\n\n  createEffect(() => {\n    playbackRateButton?.classList.add('checkable-button-menu', 'playback-rate-button-menu');\n  });\n\n  return <>{playbackRateButton}</>;\n}\n\nexport function createPlaybackRateButton(props: PlaybackRateButtonProps) {\n  const element = document.createElement('div');\n  let controls: PlaybackRateButtonControls;\n\n  const dispose = render(\n    () => (\n      <PlaybackRateButton\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n","import {batch, createEffect, createSignal, onCleanup, onMount, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {bindActiveWindowListener} from '@helpers/appWindow';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {IconTsx} from '@components/iconTsx';\nimport clamp from '@helpers/number/clamp';\nimport {IS_MOBILE} from '@environment/userAgent';\n\nimport {i18n} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\n\ntype SpeedDragHandlerProps = {\n  video: HTMLVideoElement;\n  onShowSpeed: () => void;\n  onHideSpeed: () => void;\n};\n\ntype InternalSpeedDragHandlerProps = SpeedDragHandlerProps & {\n  controlsRef: (value: SpeedDragHandlerControls) => void;\n};\n\ntype SpeedDragHandlerControls = {\n  isChangingSpeed: () => boolean;\n};\n\n\nconst HIDE_TIP_MOUSE_MOVE_THRESHOLD = 2;\nconst SHOW_TIP_TIMEOUT = 200;\nconst HIDE_TIP_TIMEOUT = 1500;\n\nconst SPEED_PER_PX = 1 / 100;\nconst SPEED_MULTIPLIER_WHEN_BELOW_ONE = 0.2;\nconst MAX_SPEED = 5;\nconst MIN_SPEED = 0.2;\n\n\nexport function SpeedDragHandler(props: InternalSpeedDragHandlerProps) {\n  const [currentSpeed, setCurrentSpeed] = createSignal(appMediaPlaybackController.playbackRate);\n\n  const [showSpeed, setShowSpeed] = createSignal(false);\n  const [hideSpeedTip, setHideSpeedTip] = createSignal(true);\n  const [mouseCoords, setMouseCoords] = createSignal<[number, number]>([0, 0]);\n\n  const controls: SpeedDragHandlerControls = {\n    isChangingSpeed: () => showSpeed()\n  };\n  props.controlsRef(controls);\n\n  let speedTipRef: HTMLDivElement;\n\n  const listenerSetter = new ListenerSetter();\n\n  onMount(() => {\n    let initialMousePosition: [number, number];\n    let showTimeout = 0;\n    let initialSpeed = 1;\n    let additionalSpeed = 0;\n\n    function show() {\n      const rect = props.video.getBoundingClientRect();\n\n      batch(() => {\n        setShowSpeed(true);\n        setMouseCoords([\n          initialMousePosition[0] - rect.left,\n          initialMousePosition[1] - rect.top\n        ]);\n      });\n\n      if(additionalSpeed) {\n        appMediaPlaybackController.playbackRate = Math.min(initialSpeed + additionalSpeed, MAX_SPEED);\n      }\n\n      window.setTimeout(() => {\n        if(!speedTipRef) return;\n        const speedTipRect = speedTipRef.getBoundingClientRect();\n        if(\n          speedTipRect.left < rect.left ||\n          speedTipRect.top < rect.top ||\n          speedTipRect.right > rect.right ||\n          speedTipRect.bottom > rect.bottom\n        ) {\n          setHideSpeedTip(true);\n        } else {\n          setHideSpeedTip(false);\n        }\n\n        setTimeout(() => {\n          if(!hideSpeedTip()) setHideSpeedTip(true);\n        }, HIDE_TIP_TIMEOUT);\n      }, 0);\n    }\n\n    listenerSetter.add(props.video)('pointerdown', (e) => {\n      if(props.video.paused) return;\n\n      initialMousePosition = [e.clientX, e.clientY];\n      initialSpeed = appMediaPlaybackController.playbackRate;\n\n      if(!IS_MOBILE && areSpeedsEqual(initialSpeed, 1)) {\n        additionalSpeed = 1;\n      }\n      if(IS_MOBILE) {\n        additionalSpeed = initialSpeed;\n      }\n\n      showTimeout = window.setTimeout(() => {\n        show();\n      }, SHOW_TIP_TIMEOUT);\n    });\n\n    // The drag (speed change) and release (revert) track on the WINDOW — follow whichever window the\n    // app is in (the tab, or the Document PiP window), else in the PiP the pointermove/pointerup fire\n    // on the PiP window, never arrive, and the speed neither changes on drag nor reverts on release.\n    const disposePointerMove = bindActiveWindowListener((w) => w, 'pointermove', (e) => {\n      if(!initialMousePosition || IS_MOBILE) return;\n\n      const moveX = e.clientX - initialMousePosition[0];\n\n      const startSpeed = initialSpeed + additionalSpeed;\n      const changedSpeed = moveX * SPEED_PER_PX;\n\n      let newSpeed: number;\n\n      if(startSpeed < 1) {\n        const borrowedUnits = Math.min((1 - startSpeed) / SPEED_MULTIPLIER_WHEN_BELOW_ONE, changedSpeed);\n\n        newSpeed = startSpeed +\n          borrowedUnits * SPEED_MULTIPLIER_WHEN_BELOW_ONE +\n          Math.max(0, changedSpeed - borrowedUnits);\n        //\n      } else if(startSpeed + changedSpeed < 1) {\n        newSpeed = 1 - (1 - startSpeed - changedSpeed) * SPEED_MULTIPLIER_WHEN_BELOW_ONE;\n      } else {\n        newSpeed = startSpeed + changedSpeed;\n      }\n\n      newSpeed = clamp(newSpeed, MIN_SPEED, MAX_SPEED);\n\n      if(!areSpeedsEqual(appMediaPlaybackController.playbackRate, newSpeed)) {\n        appMediaPlaybackController.playbackRate = newSpeed;\n      }\n\n      if(!initialMousePosition || hideSpeedTip()) return;\n\n      const move = Math.hypot(\n        moveX,\n        e.clientY - initialMousePosition[1]\n      );\n\n      if(move > HIDE_TIP_MOUSE_MOVE_THRESHOLD) {\n        setHideSpeedTip(true);\n        window.clearTimeout(showTimeout);\n        setShowSpeed(true);\n      };\n    });\n\n    const disposePointerUp = bindActiveWindowListener((w) => w, 'pointerup', () => {\n      if(!initialMousePosition) return;\n\n      window.clearTimeout(showTimeout);\n      batch(() => {\n        setHideSpeedTip(true);\n        setShowSpeed(false);\n        setMouseCoords([0, 0]);\n      });\n      initialMousePosition = undefined;\n\n      if(additionalSpeed) {\n        appMediaPlaybackController.playbackRate = initialSpeed;\n      }\n      additionalSpeed = 0;\n    });\n\n    listenerSetter.add(appMediaPlaybackController)('playbackParams', () => {\n      setCurrentSpeed(appMediaPlaybackController.playbackRate);\n    });\n\n    onCleanup(() => {\n      disposePointerMove();\n      disposePointerUp();\n    });\n  });\n\n  createEffect(() => {\n    if(showSpeed()) {\n      props.onShowSpeed();\n      if(props.video) {\n        props.video.dataset.startedChangingSpeed = 'true';\n        props.video.dataset.wasChangingSpeed = 'true';\n        setTimeout(() => {\n          delete props.video.dataset.startedChangingSpeed;\n        }, 100);\n      }\n\n      onCleanup(() => {\n        props.onHideSpeed();\n\n        if(props.video) {\n          setTimeout(() => {\n            delete props.video.dataset.wasChangingSpeed;\n          }, 100);\n        }\n      });\n    }\n  });\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n\n  const formattedSpeed = () => currentSpeed().toFixed(1).replace(/\\.0$/, '');\n\n  return (\n    <Show when={showSpeed()}>\n      <div\n        class=\"speed-drag-handler__speed\"\n        style={{\n          '--animation-duration-multiplier': currentSpeed()\n        }}\n      >\n        <div class=\"speed-drag-handler__speed-number\">\n          {formattedSpeed()}x\n        </div>\n        <div class=\"speed-drag-handler__speed-arrows\">\n          <SpeedArrowRight />\n          <SpeedArrowRight class=\"speed-drag-handler__speed-arrow-right-last\" />\n        </div>\n      </div>\n\n      <div\n        ref={speedTipRef}\n        class=\"speed-drag-handler__speed-tip\"\n        classList={{\n          'speed-drag-handler__speed-tip--visible': !hideSpeedTip() && !IS_MOBILE\n        }}\n        style={{\n          '--left': mouseCoords()[0] + 'px',\n          '--top': mouseCoords()[1] + 'px'\n        }}\n      >\n        <div class=\"speed-drag-handler__speed-tip-arrows\">\n          <IconTsx icon=\"arrow_prev\" />\n          <IconTsx icon=\"arrow_next\" />\n        </div>\n        <div class=\"speed-drag-handler__speed-tip-description\">\n          {i18n('PlaybackRateDragTip')}\n        </div>\n      </div>\n    </Show>\n  );\n}\n\n\nexport function createSpeedDragHandler(props: SpeedDragHandlerProps) {\n  const element = document.createElement('div');\n  let controls: SpeedDragHandlerControls;\n\n  const dispose = render(\n    () => (\n      <SpeedDragHandler\n        controlsRef={(value) => {\n          controls = value\n        }}\n        {...props}\n      />\n    ),\n    element\n  );\n\n  return {\n    element,\n    get controls() {\n      return controls;\n    },\n    dispose\n  };\n}\n\nfunction areSpeedsEqual(a: number, b: number) {\n  return a.toFixed(1) === b.toFixed(1);\n}\n\nfunction SpeedArrowRight(props: {class?: string}) {\n  return (\n    <svg class={classNames('speed-drag-handler__speed-arrow-right', props.class)} width=\"8\" height=\"11\" viewBox=\"0 0 8 11\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <path opacity=\"0.7\" d=\"M0 1.5V9.5C0 10.324 0.940764 10.7944 1.6 10.3L6.93333 6.3C7.46667 5.9 7.46667 5.1 6.93333 4.7L1.6 0.7C0.940764 0.205573 0 0.675955 0 1.5Z\" fill=\"currentColor\"/>\n    </svg>\n  );\n}\n","import {Accessor, createEffect, createMemo} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nimport styles from './preview.module.scss';\nimport classNames from '@helpers/string/classNames';\n\nexport type StoryboardFrame = {\n  time: number, // * frame time in seconds (float)\n  top: number,\n  left: number\n};\n\nexport type Storyboard = {\n  image: HTMLImageElement,\n  frameWidth: number,\n  frameHeight: number,\n  frames: StoryboardFrame[]\n};\n\nexport type PreviewProps = {\n  storyboard: Accessor<Storyboard>,\n  visible: Accessor<boolean>,\n  time: Accessor<number>\n};\n\nfunction Preview(props: PreviewProps) {\n  createEffect<StoryboardFrame>((prevFrame) => {\n    const storyboard = props.storyboard();\n    if(!props.visible() || !storyboard) {\n      return;\n    }\n\n    const time = props.time();\n    const frame = storyboard.frames.find((frame) => time <= frame.time) ||\n      storyboard.frames[storyboard.frames.length - 1];\n    if(prevFrame === frame) {\n      return prevFrame;\n    }\n\n    const {width, height} = canvasRef;\n    const context = canvasRef.getContext('2d');\n    context.clearRect(0, 0, width, height);\n    context.drawImage(\n      storyboard.image,\n      frame.left,\n      frame.top,\n      storyboard.frameWidth,\n      storyboard.frameHeight,\n      0,\n      0,\n      width,\n      height\n    );\n\n    return frame;\n  });\n\n  let canvasRef: HTMLCanvasElement;\n  return (\n    <canvas\n      ref={canvasRef}\n      // class={classNames(styles.PreviewCanvas, props.visible() && styles.Visible)}\n      width={props.storyboard()?.frameWidth}\n      height={props.storyboard()?.frameHeight}\n      style={props.storyboard() && {\n        width: `${props.storyboard().frameWidth * 1.5}px`,\n        height: `${props.storyboard().frameHeight * 1.5}px`\n      }}\n    />\n  );\n}\n\nexport function createPreview(props: PreviewProps) {\n  const element = document.createElement('div');\n  element.classList.add(styles.Preview);\n\n  const dispose = render(\n    () => {\n      createEffect(() => {\n        element.classList.toggle('hide', !props.storyboard());\n      });\n\n      return (\n        <Preview {...props} />\n      );\n    },\n    element\n  );\n\n  return {\n    element,\n    dispose\n  };\n}\n","import appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {IS_APPLE_MOBILE, IS_MOBILE} from '@environment/userAgent';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport ListenerSetter, {Listener} from '@helpers/listenerSetter';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport ControlsHover from '@helpers/dom/controlsHover';\nimport {addFullScreenListener, cancelFullScreen, getFullScreenElement, isFullScreen, requestFullScreen} from '@helpers/dom/fullScreen';\nimport {isClientPipOpen} from '@components/clientPip';\nimport {toastNew} from '@components/toast';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport MediaProgressLine from '@components/mediaProgressLine';\nimport VolumeSelector from '@components/volumeSelector';\nimport debounce from '@helpers/schedulers/debounce';\nimport overlayCounter from '@helpers/overlayCounter';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport safePlay from '@helpers/dom/safePlay';\nimport ButtonIcon from '@components/buttonIcon';\nimport Button from '@components/button';\nimport Icon from '@components/icon';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport {i18n} from '@lib/langPack';\nimport {numberThousandSplitterForWatching} from '@helpers/number/numberThousandSplitter';\nimport createCanvasStream from '@helpers/canvas/createCanvasStream';\nimport simulateEvent from '@helpers/dom/dispatchEvent';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {VideoTimestamp} from '@components/mediaViewer/base';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {Accessor, createSignal, Setter} from 'solid-js';\n\nimport {createQualityLevelsSwitchButton} from './qualityLevelsSwitchButton';\nimport {createPlaybackRateButton} from './playbackRateButton';\nimport {createSpeedDragHandler} from './speedDragHandler';\nimport {createPreview} from './preview';\n\n\nexport default class VideoPlayer extends ControlsHover {\n  public video: HTMLVideoElement;\n  protected wrapper: HTMLElement;\n  protected progress: MediaProgressLine;\n  protected skin: 'default';\n  protected live: boolean;\n\n  protected listenerSetter: ListenerSetter;\n\n  protected playbackRateButton: ReturnType<typeof createPlaybackRateButton>;\n  protected speedDragHandler: ReturnType<typeof createSpeedDragHandler>;\n  protected qualityLevelsButton: ReturnType<typeof createQualityLevelsSwitchButton>;\n  protected preview: ReturnType<typeof createPreview>;\n\n  protected pipButton: HTMLElement;\n  protected liveMenuButton: HTMLElement;\n  protected toggles: HTMLElement[];\n  protected mainToggle: HTMLElement;\n  protected controls: HTMLElement;\n  protected gradient: HTMLElement;\n  public liveEl: HTMLElement;\n\n  /* protected videoParent: HTMLElement;\n  protected videoWhichChild: number; */\n\n  protected onMenuToggle?: (open: boolean) => void;\n  // Fired while the seek-bar time preview (.media-progress-line__current-time-info)\n  // is shown/hidden, so the host can hide chrome that would stack with it (caption).\n  protected onTimePreviewToggle?: (visible: boolean) => void;\n  protected onPip?: (pip: boolean) => void;\n  protected onPipClose?: () => void;\n  protected onVolumeChange: VolumeSelector['onVolumeChange'];\n  protected onFullScreen: (active: boolean) => void;\n  protected onFullScreenToPip: () => void;\n\n  protected canPause: boolean;\n  protected canSeek: boolean;\n\n  protected _inPip = false;\n\n  protected _width: number;\n  protected _height: number;\n\n  protected emptyPipVideo: HTMLVideoElement;\n  protected debouncedPip: (pip: boolean) => void;\n  protected debouncePipTime: number;\n  public emptyPipVideoSource: CanvasImageSource;\n\n  protected listenKeyboardEvents: 'always' | 'fullscreen';\n  protected hadContainer: boolean;\n  protected useGlobalVolume: VolumeSelector['useGlobalVolume'];\n  public volumeSelector: VolumeSelector;\n  protected isPlaying: boolean;\n  protected shouldEnableSoundOnClick: () => boolean;\n\n  protected previewParams: Parameters<typeof createPreview>[0];\n  protected previewVisible: Accessor<boolean>;\n  protected previewSetVisible: Setter<boolean>;\n  protected previewTime: Accessor<number>;\n  protected previewSetTime: Setter<number>;\n\n  constructor({\n    video,\n    container,\n    play = false,\n    streamable = false,\n    duration,\n    live,\n    width,\n    height,\n    videoTimestamps,\n    onMenuToggle,\n    onTimePreviewToggle,\n    onPip,\n    onPipClose,\n    listenKeyboardEvents,\n    useGlobalVolume,\n    onVolumeChange,\n    onFullScreen,\n    onFullScreenToPip,\n    shouldEnableSoundOnClick,\n    storyboard\n  }: {\n    video: HTMLVideoElement,\n    container?: HTMLElement,\n    play?: boolean,\n    streamable?: boolean,\n    duration?: number,\n    live?: boolean,\n    width?: number,\n    height?: number,\n    videoTimestamps?: VideoTimestamp[],\n    onMenuToggle?: VideoPlayer['onMenuToggle'],\n    onTimePreviewToggle?: VideoPlayer['onTimePreviewToggle'],\n    onPip?: VideoPlayer['onPip'],\n    onPipClose?: VideoPlayer['onPipClose'],\n    listenKeyboardEvents?: VideoPlayer['listenKeyboardEvents'],\n    useGlobalVolume?: VolumeSelector['useGlobalVolume'],\n    onVolumeChange?: VideoPlayer['onVolumeChange'],\n    onFullScreen?: (active: boolean) => void,\n    onFullScreenToPip?: VideoPlayer['onFullScreenToPip'],\n    shouldEnableSoundOnClick?: VideoPlayer['shouldEnableSoundOnClick'],\n    storyboard?: Parameters<typeof createPreview>[0]['storyboard']\n  }) {\n    super();\n\n    this.video = video;\n    this.video.classList.add('ckin__video');\n    this.wrapper = container ?? document.createElement('div');\n    this.wrapper.classList.add('ckin__player');\n    this.live = live;\n    this.canPause = !live;\n    this.canSeek = !live;\n    this._width = width;\n    this._height = height;\n\n    this.onMenuToggle = onMenuToggle;\n    this.onTimePreviewToggle = onTimePreviewToggle;\n    this.onPip = onPip;\n    this.onPipClose = onPipClose;\n    this.onVolumeChange = onVolumeChange;\n    this.onFullScreen = onFullScreen;\n    this.onFullScreenToPip = onFullScreenToPip;\n\n    this.listenKeyboardEvents = listenKeyboardEvents;\n    this.hadContainer = !!container;\n    this.useGlobalVolume = useGlobalVolume;\n    this.shouldEnableSoundOnClick = shouldEnableSoundOnClick;\n\n    if(storyboard) {\n      [this.previewVisible, this.previewSetVisible] = createSignal(false);\n      [this.previewTime, this.previewSetTime] = createSignal(0);\n      this.previewParams = {\n        storyboard,\n        visible: this.previewVisible,\n        time: this.previewTime\n      };\n    }\n\n    this.video.playbackRate = appMediaPlaybackController.playbackRate;\n\n    this.listenerSetter = new ListenerSetter();\n\n    this.setup({\n      element: this.wrapper,\n      listenerSetter: this.listenerSetter,\n      canHideControls: () => {\n        if(this.video.paused) return false;\n        if(this.playbackRateButton?.controls.isMenuOpen()) return false;\n        if(this.qualityLevelsButton?.controls.isMenuOpen()) return false;\n\n        return true;\n      },\n      canShowControls: () => {\n        if(this.speedDragHandler?.controls.isChangingSpeed()) return false;\n        return true;\n      },\n      showOnLeaveToClassName: ['media-viewer-caption', 'media-viewer-topbar'],\n      ignoreClickClassName: 'ckin__controls'\n    });\n\n    if(!this.hadContainer) {\n      video.parentNode.insertBefore(this.wrapper, video);\n      this.wrapper.appendChild(video);\n    }\n\n    this.skin = 'default';\n\n    this.stylePlayer(duration);\n\n    if(this.skin === 'default' && !live) {\n      const controls = this.controls = this.wrapper.querySelector('.default__controls.ckin__controls') as HTMLDivElement;\n      this.gradient = this.controls.previousElementSibling as HTMLElement;\n\n      if(this.previewParams) {\n        this.preview = createPreview(this.previewParams);\n      }\n\n      const debouncedToggleControls = debounce((show: boolean) => {\n        this.wrapper.classList.toggle('show-time', show);\n      }, 200, false, true);\n\n      this.addEventListener('toggleControls', debouncedToggleControls);\n\n      this.progress = new MediaProgressLine({\n        videoTimestamps,\n        withTime: true,\n        appendToTimeElement: this.preview?.element,\n        onSeekStart: () => {\n          this.wrapper.classList.add('is-seeking');\n        },\n        onSeekEnd: () => {\n          this.wrapper.classList.remove('is-seeking');\n        },\n        onHover: (value) => {\n          if(this.previewParams) {\n            this.previewSetTime(value * this.video.duration);\n            this.previewSetVisible(true);\n          }\n          this.onTimePreviewToggle?.(true);\n        },\n        onPointerOut: () => {\n          if(this.previewParams) {\n            this.previewSetVisible(false);\n          }\n          this.onTimePreviewToggle?.(false);\n        }\n      });\n      this.progress.setMedia({\n        media: video,\n        streamable,\n        duration\n      });\n      controls.prepend(this.progress.container);\n    }\n\n    if(play/*  && video.paused */) {\n      video.play().catch((err: Error) => {\n        if(err.name === 'NotAllowedError') {\n          video.muted = true;\n          video.autoplay = true;\n          safePlay(video);\n        }\n      }).finally(() => { // due to autoplay, play will not call\n        this.setIsPlaying(!this.video.paused);\n      });\n    } else {\n      this.setIsPlaying(!this.video.paused);\n    }\n  }\n\n  public get width() {\n    return this.video.videoWidth || this._width;\n  }\n\n  public get height() {\n    return this.video.videoHeight || this._height;\n  }\n\n  private setIsPlaying(isPlaying: boolean) {\n    if(this.isPlaying === isPlaying) {\n      return;\n    }\n\n    this.isPlaying = isPlaying;\n\n    this.toggleActivity(isPlaying);\n\n    if(this.live && !isPlaying) {\n      return;\n    }\n\n    this.wrapper.classList.toggle('is-playing', isPlaying);\n    this.toggles.forEach((toggle) => {\n      toggle.replaceChildren(Icon(isPlaying ? 'pause_filled' : 'play_filled'));\n    });\n  }\n\n  private stylePlayer(initDuration: number) {\n    const {wrapper, video, skin, listenerSetter, live} = this;\n\n    wrapper.classList.add(skin);\n    if(live) wrapper.classList.add(`${skin}-live`);\n\n    const html = this.buildControls();\n    wrapper.insertAdjacentHTML('beforeend', html);\n    let timeDuration: HTMLElement;\n\n    const onPlayCallbacks: (() => void)[] = [], onPauseCallbacks: (() => void)[] = [];\n    if(skin === 'default') {\n      if(this.canPause) {\n        const mainToggle = this.mainToggle = Button(`${skin}__button--big toggle`, {noRipple: true, icon: 'play_filled'});\n        wrapper.firstElementChild.after(mainToggle);\n      }\n\n      const leftControls = wrapper.querySelector('.left-controls') as HTMLElement;\n      if(live) {\n        this.toggles = [];\n      } else {\n        const leftToggle = ButtonIcon(` ${skin}__button toggle`, {noRipple: true});\n        leftControls.prepend(leftToggle);\n        this.toggles = [leftToggle];\n      }\n\n      const rightControls = wrapper.querySelector('.right-controls') as HTMLElement;\n      if(!live) {\n        this.playbackRateButton = createPlaybackRateButton({skin: this.skin, onMenuToggle: this.onMenuToggle});\n      }\n      if(!IS_MOBILE && document.pictureInPictureEnabled) {\n        this.pipButton = ButtonIcon(`pip ${skin}__button`, {noRipple: true});\n      }\n      const fullScreenButton = ButtonIcon(` ${skin}__button`, {noRipple: true});\n\n      rightControls.append(...[\n        this.playbackRateButton?.element,\n        this.createQualityLevelsButton(),\n        this.pipButton,\n        fullScreenButton\n      ].filter(Boolean));\n\n      const timeElapsed = wrapper.querySelector('.ckin__time-elapsed');\n      timeDuration = wrapper.querySelector('.ckin__time-duration') as HTMLElement;\n\n      const volumeSelector = this.volumeSelector = new VolumeSelector({\n        listenerSetter,\n        vertical: false,\n        media: video,\n        useGlobalVolume: this.useGlobalVolume,\n        onVolumeChange: this.onVolumeChange\n      });\n\n      volumeSelector.btn.classList.remove('btn-icon');\n      if(timeElapsed) {\n        timeElapsed.parentElement.before(volumeSelector.btn);\n      } else {\n        leftControls.lastElementChild.before(volumeSelector.btn);\n      }\n\n      this.toggles.forEach((button) => {\n        attachClickEvent(button, () => {\n          this.togglePlay();\n        }, {listenerSetter: this.listenerSetter});\n      });\n\n      if(this.pipButton) {\n        attachClickEvent(this.pipButton, this.requestPictureInPicture, {listenerSetter: this.listenerSetter});\n\n        this.debouncePipTime = 20;\n        this.debouncedPip = debounce(this._onPip, this.debouncePipTime, false, true);\n\n        this.addPipListeners(video);\n      }\n\n      if(!IS_TOUCH_SUPPORTED) {\n        if(this.canPause) {\n          attachClickEvent(video, () => {\n            if(this.checkInteraction() || video.dataset.wasChangingSpeed) {\n              return;\n            }\n\n            this.togglePlay();\n          }, {listenerSetter: this.listenerSetter});\n        }\n\n        if(this.listenKeyboardEvents) listenerSetter.add(getAppWindow().document)('keydown', (e: KeyboardEvent) => {\n          if(\n            overlayCounter.overlaysActive > 1 ||\n            getAppWindow().document.pictureInPictureElement === video ||\n            (this.listenKeyboardEvents === 'fullscreen' && !this.isFullScreen())\n          ) { // forward popup is active, etc\n            return;\n          }\n\n          const {key, code} = e;\n\n          let good = true;\n          if(code === 'KeyF') {\n            this.toggleFullScreen();\n          } else if(code === 'KeyM') {\n            appMediaPlaybackController.muted = !appMediaPlaybackController.muted;\n          } else if(code === 'Space' && this.canPause) {\n            this.togglePlay();\n          } else if(e.altKey && (code === 'Equal' || code === 'Minus') && this.canSeek) {\n            const add = code === 'Equal' ? 1 : -1;\n            this.playbackRateButton.controls.changeRateByAmount(add);\n          } else if(wrapper.classList.contains('ckin__fullscreen') && (key === 'ArrowLeft' || key === 'ArrowRight') && this.canSeek) {\n            if(key === 'ArrowLeft') appMediaPlaybackController.seekBackward({action: 'seekbackward'});\n            else appMediaPlaybackController.seekForward({action: 'seekforward'});\n          } else {\n            good = false;\n          }\n\n          if(good) {\n            cancelEvent(e);\n            return false;\n          }\n        });\n      }\n\n      if(this.canPause) {\n        this.speedDragHandler = createSpeedDragHandler({\n          video: this.video,\n          onShowSpeed: () => {\n            this.hideControls();\n          },\n          onHideSpeed: () => {\n            this.showControls();\n          }\n        });\n        this.wrapper.append(this.speedDragHandler.element);\n\n        listenerSetter.add(video)('contextmenu', (e) => {\n          e.preventDefault();\n        });\n      }\n\n      listenerSetter.add(video)('dblclick', () => {\n        if(!IS_TOUCH_SUPPORTED) {\n          this.toggleFullScreen();\n        }\n      });\n\n      attachClickEvent(fullScreenButton, () => {\n        this.toggleFullScreen();\n      }, {listenerSetter: this.listenerSetter});\n\n      addFullScreenListener(wrapper, () => this._onFullScreen(fullScreenButton), listenerSetter);\n      this._onFullScreen(fullScreenButton, true);\n\n      if(timeElapsed) {\n        listenerSetter.add(video)('timeupdate', () => {\n          if(!video.paused && !this.isPlaying) {\n            console.warn('video: fixing missing play event');\n            simulateEvent(video, 'play');\n          }\n\n          timeElapsed.textContent = toHHMMSS(video.currentTime | 0);\n        });\n      }\n\n      const onPlay = () => {\n        wrapper.classList.add('played');\n\n        if(!IS_TOUCH_SUPPORTED && !live) {\n          onPlayCallbacks.push(() => {\n            this.hideControls(true);\n          });\n        }\n\n        indexOfAndSplice(onPlayCallbacks, onPlay);\n      };\n\n      if(this.hadContainer) {\n        onPlay();\n      }\n\n      onPlayCallbacks.push(onPlay);\n      onPauseCallbacks.push(() => {\n        this.showControls(false);\n      });\n\n      listenerSetter.add(appMediaPlaybackController)('playbackParams', () => {\n        if(this.video.dataset.startedChangingSpeed) return;\n        this.playbackRateButton.controls.setPlayBackRate(appMediaPlaybackController.playbackRate);\n      });\n\n      if(live) {\n        this.liveEl = i18n('Rtmp.MediaViewer.Live');\n        this.liveEl.classList.add('controls-live');\n        leftControls.prepend(this.liveEl);\n      }\n    }\n\n    listenerSetter.add(video)('play', () => {\n      this.setIsPlaying(true);\n      onPlayCallbacks.forEach((cb) => cb());\n    });\n\n    listenerSetter.add(video)('pause', () => {\n      this.setIsPlaying(false);\n      onPauseCallbacks.forEach((cb) => cb());\n    });\n\n    if(timeDuration) {\n      if(video.duration || initDuration) {\n        timeDuration.textContent = toHHMMSS(Math.round(video.duration || initDuration));\n      } else {\n        onMediaLoad(video).then(() => {\n          timeDuration.textContent = toHHMMSS(Math.round(video.duration));\n        });\n      }\n    }\n  }\n\n  private createQualityLevelsButton() {\n    this.qualityLevelsButton = createQualityLevelsSwitchButton({skin: this.skin, video: this.video, onMenuToggle: this.onMenuToggle});\n\n    return this.qualityLevelsButton.element;\n  }\n\n  public async loadQualityLevels() {\n    this.qualityLevelsButton?.controls.loadQualityLevels();\n  }\n\n  protected checkInteraction() {\n    if(this.shouldEnableSoundOnClick?.()) {\n      this.volumeSelector.setVolume({volume: 1, muted: false});\n      return true;\n    }\n\n    return false;\n  }\n\n  protected _onPip = (pip: boolean) => {\n    this._inPip = pip;\n    this.wrapper.style.visibility = pip ? 'hidden': '';\n    this.onPip?.(pip);\n  };\n\n  protected onEnterPictureInPictureLeave = (e: Event) => {\n    const onPause = () => {\n      clearTimeout(timeout);\n      this.onPipClose?.();\n    };\n    const listener = this.listenerSetter.add(e.target)('pause', onPause, {once: true}) as any as Listener;\n    const timeout = setTimeout(() => {\n      this.listenerSetter.remove(listener);\n    }, this.debouncePipTime);\n  };\n\n  protected onEnterPictureInPicture = (e: Event) => {\n    this.debouncedPip(true);\n    this.listenerSetter.add(e.target)('leavepictureinpicture', this.onEnterPictureInPictureLeave, {once: true});\n  };\n\n  protected onLeavePictureInPicture = () => {\n    this.debouncedPip(false);\n  };\n\n  protected addPipListeners(video: HTMLVideoElement) {\n    this.listenerSetter.add(video)('enterpictureinpicture', this.onEnterPictureInPicture);\n    this.listenerSetter.add(video)('leavepictureinpicture', this.onLeavePictureInPicture);\n  }\n\n  public requestPictureInPicture = async() => {\n    if(this.video.duration) {\n      if(this.isFullScreen()) {\n        this.onFullScreenToPip?.();\n      }\n\n      this.video.requestPictureInPicture();\n      this.checkInteraction();\n      return;\n    }\n\n    if(!this.emptyPipVideo) {\n      const {width, height} = this;\n      this.emptyPipVideo = document.createElement('video');\n      this.emptyPipVideo.autoplay = true;\n      this.emptyPipVideo.muted = true;\n      this.emptyPipVideo.playsInline = true;\n      this.emptyPipVideo.style.position = 'absolute';\n      this.emptyPipVideo.style.visibility = 'hidden';\n      getOverlayRoot().prepend(this.emptyPipVideo);\n      this.emptyPipVideo.srcObject = createCanvasStream({width, height, image: this.emptyPipVideoSource});\n      this.addPipListeners(this.emptyPipVideo);\n    }\n\n    await onMediaLoad(this.emptyPipVideo);\n    this.emptyPipVideo.requestPictureInPicture();\n\n    onMediaLoad(this.video).then(() => {\n      if(getAppWindow().document.pictureInPictureElement === this.emptyPipVideo) {\n        getAppWindow().document.exitPictureInPicture();\n        this.video.requestPictureInPicture();\n      }\n    });\n  };\n\n  protected togglePlay(isPaused = this.video.paused) {\n    this.video[isPaused ? 'play' : 'pause']();\n  }\n\n  private buildControls() {\n    const skin = this.skin;\n\n    if(skin === 'default') {\n      const time = this.live ? `\n      <span class=\"left-controls-watching\"></span>\n      ` : `\n      <time class=\"ckin__time-elapsed\">0:00</time>\n      <span> / </span>\n      <time class=\"ckin__time-duration\">0:00</time>\n      `\n\n      return `\n      <div class=\"${skin}__gradient-bottom ckin__controls\"></div>\n      <div class=\"${skin}__controls ckin__controls\">\n        <div class=\"bottom-controls night\">\n          <div class=\"left-controls\">\n            <div class=\"ckin__time\">\n              ${time}\n            </div>\n          </div>\n          <div class=\"right-controls\"></div>\n        </div>\n      </div>`;\n    }\n  }\n\n  public cancelFullScreen() {\n    if(getFullScreenElement() === this.wrapper) {\n      this.toggleFullScreen();\n    }\n  }\n\n  protected toggleFullScreen() {\n    const player = this.wrapper;\n\n    // * https://caniuse.com/#feat=fullscreen\n    if(IS_APPLE_MOBILE) {\n      const video = this.video as any;\n      video.webkitEnterFullscreen();\n      video.enterFullscreen();\n      return;\n    }\n\n    if(!isFullScreen()) {\n      /* const videoParent = this.video.parentElement;\n      const videoWhichChild = whichChild(this.video);\n      const needVideoRemount = videoParent !== player;\n\n      if(needVideoRemount) {\n        this.videoParent = videoParent;\n        this.videoWhichChild = videoWhichChild;\n        player.prepend(this.video);\n      } */\n\n      // Fullscreen genuinely can't be entered while the client is popped into a Document PiP window:\n      // the Fullscreen API is disabled there by spec, AND Chrome won't carry the click's user-activation\n      // from the PiP window over to the