     if(this.tempId !== tempId) return;\n          isHlsStream = this.hasQualityOptions;\n\n          const promise: Promise<any> = supportsStreaming || isLiveStream ? Promise.resolve() : appDownloadManager.downloadMediaURL({media});\n\n          if(!supportsStreaming) {\n            onAnimationEnd.then(async() => {\n              if(!(await getCacheContext()).url) {\n                preloader?.attach(mover, true, promise);\n              }\n            });\n          }\n\n          Promise.all([\n            promise,\n            isLiveStream ? undefined : onAnimationEnd\n          ]).then(async() => {\n            if(this.tempId !== tempId) {\n              this.log.warn('media viewer changed video');\n              return;\n            }\n\n            const url = (await getCacheContext()).url;\n            // * keep a blob video's URL alive for seeks while the slide lives\n            mover.middlewareHelper.get().onClean(pinObjectURL(url));\n\n            const onError = (e: ErrorEvent) => {\n              if(shouldIgnoreVideoError(e) || isLiveStream) {\n                return;\n              }\n\n              toastNew({\n                langPackKey: IS_MOBILE ? 'Video.Unsupported.Mobile' : 'Video.Unsupported.Desktop'\n              });\n\n              const error = video.error;\n              if(error && error.code !== 4) {\n                this.log.error('Error ' + error.code + '; details: ' + error.message);\n              }\n\n              preloader?.detach();\n            };\n\n            const onMediaLoadPromise = onMediaLoad(video);\n            if(!isLiveStream) {\n              handleVideoLeak(video, onMediaLoadPromise).catch(onError);\n            }\n\n            video.addEventListener('error', onError, {once: true});\n            middleware.onClean(() => {\n              video.removeEventListener('error', onError);\n            });\n\n            if(target instanceof SVGSVGElement/*  && (video.parentElement || !isSafari) */) { // if video exists\n              // if(!video.parentElement) {\n              div.firstElementChild.lastElementChild.append(video);\n              // }\n            } else {\n              renderImageFromUrl(video, url);\n              this.videoPlayer?.loadQualityLevels();\n            }\n\n            // * have to set options (especially playbackRate) after src\n            // * https://github.com/videojs/video.js/issues/2516\n            if(useController) {\n              setSingleMedia();\n\n              this.addEventListener('setMoverBefore', () => {\n                this.releaseSingleMedia?.();\n                this.releaseSingleMedia = undefined;\n              }, {once: true});\n            }\n\n            this.updateMediaSource(target, url, 'video');\n\n            if(isLiveStream) {\n              createPlayer();\n            } else onMediaLoadPromise.then(() => {\n              createPlayer();\n            });\n          });\n\n          return promise;\n        };\n\n        this.lazyLoadQueue.unshift({load});\n        // } else createPlayer();\n      });\n\n      setMoverPromise = thumbPromise.then(set);\n    } else {\n      const set = () => this.setMoverToTarget(target, false, fromRight).then(({onAnimationEnd}) => {\n      // return; // set and don't move\n      // if(wasActive) return;\n        // return;\n\n        const load = async() => {\n          const cancellablePromise = isDocument ? appDownloadManager.downloadMediaURL({media}) : appDownloadManager.downloadMediaURL({media, thumb: size});\n\n          const photoSizes = !isDocument && media.sizes.slice().filter((size) => (size as PhotoSize.photoSize).w) as PhotoSize.photoSize[];\n          photoSizes && photoSizes.sort((a, b) => b.size - a.size);\n          const fullPhotoSize = photoSizes?.[0];\n          const cancellableFullPromise = !isDocument && fullPhotoSize !== size && appDownloadManager.downloadMediaURL({media, thumb: fullPhotoSize});\n\n          onAnimationEnd.then(async() => {\n            if(!(await getCacheContext()).url) {\n              this.preloader.attachPromise(cancellablePromise);\n              // this.preloader.attach(mover, true, cancellablePromise);\n            }\n          });\n\n          Promise.all([onAnimationEnd, cancellablePromise]).then(async() => {\n            if(this.tempId !== tempId) {\n              this.log.warn('media viewer changed photo');\n              return;\n            }\n\n            const url = (await getCacheContext()).url;\n            if(target instanceof SVGSVGElement) {\n              this.updateMediaSource(target, url, 'img');\n              this.updateMediaSource(mover, url, 'img');\n\n              if(mediaSizes.isMobile) {\n                const imgs = mover.querySelectorAll('img');\n                imgs.forEach((img) => {\n                  img.classList.remove('thumbnail'); // может здесь это вообще не нужно\n                });\n              }\n            } else {\n              const div = mover.firstElementChild && mover.firstElementChild.classList.contains('media-viewer-aspecter') ? mover.firstElementChild : mover;\n              const haveImage = ['CANVAS', 'IMG'].includes(div.firstElementChild?.tagName) ? div.firstElementChild as HTMLElement : null;\n              if((haveImage as HTMLImageElement)?.src !== url)  {\n                const image = new Image();\n                image.classList.add('thumbnail');\n\n                renderImageFromUrl(image, url, () => {\n                  fastRaf(() => {\n                    this.updateMediaSource(target, url, 'img');\n\n                    if(haveImage) {\n                      fastRaf(() => {\n                        haveImage.remove();\n                      });\n                    }\n\n                    div.append(image);\n                  });\n                }, false);\n\n                cancellableFullPromise && cancellableFullPromise.then((url) => {\n                  const fullImage = new Image();\n                  fullImage.classList.add('thumbnail');\n                  renderImageFromUrl(fullImage, url, () => {\n                    fastRaf(() => {\n                      image.replaceWith(fullImage);\n                    });\n                  }, false);\n                });\n              }\n            }\n\n            // this.preloader.detach();\n          }).catch((err) => {\n            this.log.error(err);\n            this.preloader.attach(mover);\n            this.preloader.setManual();\n          });\n\n          return cancellablePromise;\n        };\n\n        this.lazyLoadQueue.unshift({load});\n      });\n\n      setMoverPromise = thumbPromise.then(set);\n    }\n\n    const result = this.setMoverPromise = setMoverPromise.catch(() => {\n      this.setMoverAnimationPromise = null;\n    }).finally(() => {\n      this.setMoverPromise = null;\n    });\n\n    if(shouldLoadMore) {\n      // Prefetching used to run in a zero-delay timer, immediately before the first\n      // compositor frame. Let the real mover transition finish before doing list and\n      // worker work that is invisible while the viewer opens.\n      void result.then(() => this.setMoverAnimationPromise).then(() => {\n        if(this.tempId === tempId && this.listLoader.next.length < 10) {\n          this.listLoader.load(true);\n        }\n      });\n    }\n\n    return result;\n  }\n}\n","/**\n * Prevent spamming an async click handler\n */\nexport function wrapAsyncClickHandler<Args extends any[]>(handler: (...args: Args) => Promise<void>) {\n  let isPending = false;\n  return async(...args: Args) => {\n    if(isPending) return;\n\n    try {\n      isPending = true;\n      await handler(...args);\n    } finally {\n      isPending = false;\n    }\n  };\n}\n","import callbackify from '@helpers/callbackify';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {Chat, ChatFull} from '@layer';\nimport getParticipantsCount from '@appManagers/utils/chats/getParticipantsCount';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\n\nfunction _getChatMembersString(chat: Chat, chatFull: ChatFull) {\n  let count: number;\n  if(chatFull) {\n    count = getParticipantsCount(chatFull);\n  } else {\n    count = (chat as Chat.chat).participants_count || (chat as any).participants?.participants.length;\n  }\n\n  const isBroadcast = (chat as Chat.channel).pFlags.broadcast;\n  count = count || 1;\n\n  const key: LangPackKey = isBroadcast ? 'Peer.Status.Subscribers' : 'Peer.Status.Member';\n  return i18n(key, [numberThousandSplitter(count)]);\n}\n\nexport default function getChatMembersString(\n  chatId: ChatId,\n  managers = rootScope.managers,\n  chat?: Chat,\n  onlySync?: boolean,\n  chatFull?: ChatFull\n) {\n  chat ??= apiManagerProxy.getChat(chatId);\n  if(chat._ === 'chatForbidden') {\n    return i18n('YouWereKicked');\n  }\n\n  if(onlySync) {\n    return _getChatMembersString(chat, undefined);\n  }\n\n  const result = chatFull || managers.appProfileManager.getCachedFullChat(chatId);\n  return callbackify(result, (chatFull) => _getChatMembersString(chat, chatFull));\n}\n","import {formatFullSentTimeRaw} from '@helpers/date';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {User} from '@layer';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {REPLIES_PEER_ID, SERVICE_PEER_ID} from '@appManagers/constants';\n\nexport default function getUserStatusString(user: User.user): HTMLElement {\n  if(!user) {\n    return document.createElement('span');\n  }\n\n  let key: LangPackKey;\n  let args: any[];\n\n  switch(user.id) {\n    case REPLIES_PEER_ID.toUserId():\n      key = 'Peer.RepliesNotifications';\n      break;\n    case SERVICE_PEER_ID.toUserId():\n      key = 'Peer.ServiceNotifications';\n      break;\n    default: {\n      if(user.pFlags.bot) {\n        if(user.bot_active_users === undefined) {\n          key = 'Bot';\n          break;\n        }\n\n        key = 'BotUsers';\n        args = [numberThousandSplitter(user.bot_active_users)];\n        break;\n      }\n\n      if(user.pFlags.support) {\n        key = 'SupportStatus';\n        break;\n      }\n\n      switch(user.status?._) {\n        case 'userStatusRecently': {\n          key = 'Lately';\n          break;\n        }\n\n        case 'userStatusLastWeek': {\n          key = 'WithinAWeek';\n          break;\n        }\n\n        case 'userStatusLastMonth': {\n          key = 'WithinAMonth';\n          break;\n        }\n\n        case 'userStatusOffline': {\n          const date = user.status.was_online;\n          const today = new Date();\n          const now = today.getTime() / 1000 | 0;\n\n          const diff = now - date;\n          if(diff < 60) {\n            key = 'Peer.Status.justNow';\n          } else if(diff < 3600) {\n            key = 'Peer.Status.minAgo';\n            const c = diff / 60 | 0;\n            args = [c];\n          } else if(diff < 86400 && today.getDate() === new Date(date * 1000).getDate()) {\n            key = 'LastSeen.HoursAgo';\n            const c = diff / 3600 | 0;\n            args = [c];\n          } else {\n            key = 'Peer.Status.LastSeenAt';\n            const {dateEl, timeEl} = formatFullSentTimeRaw(date);\n            args = [dateEl, timeEl];\n          }\n\n          break;\n        }\n\n        case 'userStatusOnline': {\n          key = 'Online';\n          break;\n        }\n\n        default: {\n          key = 'ALongTimeAgo';\n          break;\n        }\n      }\n\n      break;\n    }\n  }\n\n  return i18n(key, args);\n}\n","export const generateDelimiter = () => {\n  const delimiter = document.createElement('div');\n  delimiter.classList.add('gradient-delimiter');\n  return delimiter;\n};\n","import {LangPackKey, FormatterArguments, i18n_} from '@lib/langPack';\nimport {generateDelimiter} from '@components/generateDelimiter';\nimport Scrollable from '@components/scrollable';\n\nexport type SettingSectionOptions = {\n  name?: LangPackKey | HTMLElement,\n  nameArgs?: FormatterArguments,\n  caption?: LangPackKey | true,\n  captionArgs?: FormatterArguments,\n  captionOld?: SettingSectionOptions['caption'],\n  noDelimiter?: boolean,\n  fakeGradientDelimiter?: boolean,\n  noShadow?: boolean,\n  // fullWidth?: boolean,\n  // noPaddingTop?: boolean\n};\n\nconst className = 'sidebar-left-section';\nexport default class SettingSection {\n  public container: HTMLElement;\n  public innerContainer: HTMLElement;\n  public content: HTMLElement;\n  public title: HTMLElement;\n  public caption: HTMLElement;\n\n  private fullWidth: boolean;\n\n  constructor(options: SettingSectionOptions = {}) {\n    const container = this.container = document.createElement('div');\n    container.classList.add(className + '-container');\n\n    const innerContainer = this.innerContainer = document.createElement('div');\n    innerContainer.classList.add(className);\n\n    if(options.noShadow) {\n      innerContainer.classList.add('no-shadow');\n    }\n\n    if(options.fakeGradientDelimiter) {\n      innerContainer.append(generateDelimiter());\n      innerContainer.classList.add('with-fake-delimiter');\n    } else if(!options.noDelimiter) {\n      const hr = document.createElement('hr');\n      innerContainer.append(hr);\n    } else {\n      innerContainer.classList.add('no-delimiter');\n    }\n\n    // if(options.fullWidth) {\n    //   this.fullWidth = true;\n    // }\n\n    // if(options.noPaddingTop) {\n    //   innerContainer.classList.add('no-padding-top');\n    // }\n\n    const content = this.content = this.generateContentElement();\n\n    if(options.name) {\n      const title = this.title = document.createElement('div');\n      title.classList.add('sidebar-left-h2', className + '-name');\n      if(typeof(options.name) === 'string') {\n        i18n_({element: title, key: options.name, args: options.nameArgs});\n      } else {\n        title.append(options.name);\n      }\n      content.append(title);\n    }\n\n    container.append(innerContainer);\n\n    const caption = options.caption ?? options.captionOld;\n    if(caption) {\n      const el = this.caption = this.generateContentElement();\n      el.classList.add(className + '-caption');\n\n      if(!options.captionOld) {\n        container.append(el);\n      }\n\n      if(caption !== true) {\n        i18n_({element: el, key: caption, args: options.captionArgs});\n      }\n    }\n  }\n\n  public generateContentElement() {\n    const content = document.createElement('div');\n    content.classList.add(className + '-content');\n\n    // if(this.fullWidth) {\n    //   content.classList.add('full-width');\n    // }\n\n    this.innerContainer.append(content);\n    return content;\n  }\n}\n\nexport const generateSection = (appendTo: Scrollable, name?: LangPackKey, caption?: LangPackKey) => {\n  const section = new SettingSection({name, caption});\n  appendTo.append(section.container);\n  return section.content;\n};\n","import {Middleware} from '@helpers/middleware';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport lottieLoader, {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker';\n\nexport default async function wrapLocalSticker({\n  container,\n  emoji,\n  width,\n  height,\n  assetName,\n  middleware,\n  managers = rootScope.managers,\n  loop = false,\n  autoplay = true\n}: {\n  container?: HTMLElement,\n  doc?: MyDocument,\n  // url?: string,\n  emoji?: string,\n  assetName?: LottieAssetName,\n  width: number,\n  height: number,\n  managers?: AppManagers,\n  middleware?: Middleware,\n  autoplay?: boolean,\n  loop?: boolean\n}) {\n  container ||= document.createElement('div');\n  container.classList.add('media-sticker-wrapper');\n\n  let playerPromise: Promise<LottiePlayer>;\n  if(assetName) {\n    playerPromise = lottieLoader.loadAnimationAsAsset({\n      container,\n      loop,\n      autoplay,\n      width,\n      height,\n      noCache: true,\n      middleware\n    }, assetName).then((animation) => {\n      return lottieLoader.waitForFirstFrame(animation);\n    });\n  } else if(emoji) {\n    const doc = await managers.appStickersManager.getAnimatedEmojiSticker(emoji);\n    if(doc) playerPromise = wrapSticker({\n      doc,\n      div: container,\n      loop,\n      play: autoplay,\n      width,\n      height,\n      emoji,\n      managers,\n      middleware\n    }).then((result) => {\n      return result.render as Promise<LottiePlayer>;\n    });\n  }\n\n  return {container, promise: playerPromise};\n}\n","import {Middleware} from '@helpers/middleware';\nimport {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport {Accessor, createRoot, JSX} from 'solid-js';\n\nexport default async function emptyPlaceholder({\n  middleware,\n  title,\n  description,\n  hide,\n  assetName = 'UtyanSearch',\n  width = 140,\n  height = 140,\n  isFullSize\n}: {\n  middleware: Middleware,\n  title: Accessor<JSX.Element>,\n  description: Accessor<JSX.Element>,\n  hide: Accessor<boolean>,\n  assetName?: LottieAssetName,\n  width?: number,\n  height?: number,\n  isFullSize?: boolean\n}) {\n  const {container, promise} = await wrapLocalSticker({\n    width,\n    height,\n    assetName,\n    middleware,\n    loop: true\n  });\n\n  if(!middleware()) {\n    return;\n  }\n\n  await promise;\n  if(!middleware()) {\n    return;\n  }\n\n  container.classList.add('selector-empty-placeholder-sticker');\n\n  let ret: JSX.Element;\n  createRoot((disposer) => {\n    middleware.onClean(disposer);\n    ret = (\n      <div class=\"selector-empty-placeholder\" classList={{'hide': hide(), 'is-full': isFullSize}}>\n        {container}\n        <div class=\"selector-empty-placeholder-title\">\n          {title()}\n        </div>\n        {description() && (\n          <div class=\"selector-empty-placeholder-description\">\n            {description()}\n          </div>\n        )}\n      </div>\n    );\n  });\n\n  return ret as HTMLElement;\n}\n","export default function roundRect(\n  ctx: CanvasRenderingContext2D,\n  x: number,\n  y: number,\n  width: number,\n  height: number,\n  radius: {[k in 'tl' | 'tr' | 'br' | 'bl']?: number} | number,\n  fill?: boolean,\n  stroke?: boolean\n) {\n  const dpr = ctx.canvas.dpr;\n  if(dpr) {\n    x *= dpr;\n    y *= dpr;\n    width *= dpr;\n    height *= dpr;\n  }\n\n  if(typeof(radius) === 'number') {\n    if(dpr) radius *= dpr;\n    radius = {tl: radius, tr: radius, br: radius, bl: radius};\n  } else {\n    const defaultRadius = {tl: 0, tr: 0, br: 0, bl: 0};\n    for(const side in defaultRadius) {\n      // @ts-ignore\n      radius[side] = radius[side] ? (dpr ? radius[side] * dpr : radius[side]) : defaultRadius[side];\n    }\n  }\n\n  ctx.beginPath();\n  ctx.moveTo(x + radius.tl, y);\n  ctx.lineTo(x + width - radius.tr, y);\n  ctx.quadraticCurveTo(x + width, y, x + width, y + radius.tr);\n  ctx.lineTo(x + width, y + height - radius.br);\n  ctx.quadraticCurveTo(x + width, y + height, x + width - radius.br, y + height);\n  ctx.lineTo(x + radius.bl, y + height);\n  ctx.quadraticCurveTo(x, y + height, x, y + height - radius.bl);\n  ctx.lineTo(x, y + radius.tl);\n  ctx.quadraticCurveTo(x, y, x + radius.tl, y);\n  ctx.closePath();\n\n  if(fill) {\n    ctx.fill();\n  }\n\n  if(stroke) {\n    ctx.stroke();\n  }\n}\n","import customProperties from '@helpers/dom/customProperties';\nimport clamp from '@helpers/number/clamp';\n\nexport default class Shimmer {\n  private canvas: HTMLCanvasElement;\n  private ctx: CanvasRenderingContext2D;\n  private font = '30pt Helvetica';\n  private currTime = Date.now();\n  private diffTime = 0;\n  private spread = 0;\n  private paused = false;\n  private pausedTime = 0;\n  private pauseInterval = 850;\n  private lightSource = 0;\n  private inc = 0.032;\n  private lightSpread = 0.55;\n  private animations = ['slide', 'slide', 'slide', 'slide'];\n  private currentAnimationIndex = 0;\n  private text: string;\n  private fillStyle: CanvasRenderingContext2D['fillStyle'];\n\n  public night: boolean;\n\n  private keepTime() {\n    this.diffTime = Date.now() - this.currTime;\n    this.currTime = Date.now();\n  }\n\n  private cycleAnimation() {\n    ++this.currentAnimationIndex;\n    if(this.currentAnimationIndex >= this.animations.length) {\n      this.currentAnimationIndex = 0;\n    }\n  }\n\n  private animate() {\n    const currentAnimation = this.animations[this.currentAnimationIndex];\n    if(currentAnimation === 'glow') {\n      return this.animateGlow(); // return glow style\n    } else if(currentAnimation === 'slide') {\n      return this.animateSlide(); // return slide gradient\n    } else {\n      console.log('unknown animation type: ' + String(currentAnimation));\n    }\n  }\n\n  private animateGlow() {\n    var glowEnd = 255,\n      rgbStart = 68,\n      r = rgbStart,\n      g = r,\n      b = r,\n      increment = 10,\n      interval = 800;\n\n    return () => {\n      var smartInc = increment * (this.diffTime / (1000 / 60));\n      if(this.paused) {\n        if((Date.now() - this.pausedTime) > interval) {\n          r = rgbStart;\n          this.cycleAnimation()\n          this.paused = false;\n        }\n      } else {\n        r = parseInt('' + (r + smartInc));\n        if(r >= glowEnd) {\n          this.paused = true;\n          this.pausedTime = Date.now()\n        }\n      }\n      return 'rgb('+ r + ',' + r + ',' + r + ')';\n    };\n  }\n\n  private animateSlide(): CanvasGradient {\n    var gradient = this.ctx.createLinearGradient(0, 0, this.canvas.width, 0),\n      smartInc = this.inc * (this.diffTime / (1000 / 60)),\n      lightLeft,\n      lightRight,\n      lightCenter;\n    if(this.paused) {\n      if((Date.now() - this.pausedTime) > this.pauseInterval) {\n        this.lightSource = -0.6;\n        this.cycleAnimation()\n        this.paused = false;\n        return this.animateSlide();\n      }\n    } else {\n      this.lightSource += smartInc;\n      if(this.lightSource > (1 + this.lightSpread)) {\n        this.paused = true;\n        this.pausedTime = Date.now();\n      }\n    }\n    // lighting positions:\n    lightCenter = clamp(this.lightSource, 0, 1);\n    lightLeft = clamp(this.lightSource - this.lightSpread, 0, 1);\n    lightRight = clamp(this.lightSource + this.lightSpread, 0, 1);\n\n    const backgroundColor = customProperties.getProperty('background-color', this.night);\n    const shimmerColor = customProperties.getProperty('surface-color', this.night);\n    gradient.addColorStop(lightLeft, backgroundColor);\n    gradient.addColorStop(lightCenter, shimmerColor);\n    gradient.addColorStop(lightRight, backgroundColor);\n\n    return gradient;\n  }\n\n  public settings(dict: Partial<{\n    canvas: Shimmer['canvas'],\n    fillStyle: Shimmer['fillStyle'],\n    font: Shimmer['font'],\n    lightSpread: Shimmer['lightSpread'],\n    inc: Shimmer['inc'],\n    animations: Shimmer['animations'],\n    text: Shimmer['text']\n  }> = {}) {\n    this.canvas = dict.canvas ?? document.createElement('canvas');\n    this.ctx = this.canvas.getContext('2d');\n    this.font = dict.font ?? this.font;\n    this.lightSpread = dict.lightSpread ?? this.lightSpread;\n    this.inc = dict.inc ?? this.inc;\n    this.animations = dict.animations ?? this.animations;\n    this.text = dict.text ?? this.text;\n    this.fillStyle = dict.fillStyle;\n\n    this.canvas.classList.add('shimmer-canvas');\n  }\n\n  public on() {\n    const {width, height} = this.canvas;\n    // record the time we ran:\n    this.keepTime();\n    // clear and fill the canvas:\n    this.ctx.clearRect(0, 0, width, height);\n\n    if(this.font) {\n      this.ctx.font = this.font;\n    }\n\n    this.ctx.fillStyle = this.animate() as any;\n    this.ctx.fillRect(0, 0, width, height);\n\n    if(this.fillStyle) {\n      this.ctx.fillStyle = this.fillStyle;\n      this.ctx.fillRect(0, 0, width, height);\n    }\n\n    if(this.text) {\n      this.ctx.fillText(this.text, 50, 50);\n    }\n  }\n}\n","import Scrollable from '@components/scrollable';\nimport rootScope from '@lib/rootScope';\nimport {animate} from '@helpers/animation';\nimport {drawCircleFromStart} from '@helpers/canvas/drawCircle';\nimport roundRect from '@helpers/canvas/roundRect';\nimport Shimmer from '@helpers/canvas/shimmer';\nimport customProperties from '@helpers/dom/customProperties';\nimport easeInOutSine from '@helpers/easing/easeInOutSine';\nimport liteMode from '@helpers/liteMode';\nimport mediaSizes from '@helpers/mediaSizes';\n\nexport default class DialogsPlaceholder {\n  private canvas: HTMLCanvasElement;\n  private ctx: CanvasRenderingContext2D;\n  private shimmer: Shimmer;\n  private tempId: number;\n  private detachTime: number;\n\n  private length: number;\n  private dialogHeight: number;\n  private availableLength: number;\n\n  private avatarSize: number;\n  private avatarMarginRight: number;\n  private marginVertical: number;\n  private marginLeft: number;\n  private gapVertical: number;\n  private totalHeight: number;\n  private lineHeight: number;\n  private lineBorderRadius: number;\n  private lineMarginVertical: number;\n  private statusWidth: number;\n  private generatedValues: {\n    firstLineWidth: number,\n    secondLineWidth: number,\n    statusWidth: number\n  }[];\n\n  private getRectFrom: () => Pick<DOMRectEditable, 'width' | 'height'>;\n  private onRemove: () => void;\n  private blockScrollable: Scrollable;\n\n  private night: boolean;\n  private noSecondLine: boolean;\n\n  constructor(sizes: Partial<{\n    avatarSize: number,\n    avatarMarginRight: number,\n    marginVertical: number,\n    marginLeft: number,\n    lineMarginVertical: number,\n    gapVertical: number,\n    totalHeight: number,\n    statusWidth: number,\n    noSecondLine: boolean,\n    night: boolean\n  }> = {}) {\n    this.shimmer = new Shimmer();\n    this.shimmer.night = this.night = sizes.night;\n    this.tempId = 0;\n    this.canvas = document.createElement('canvas');\n    this.canvas.classList.add('dialogs-placeholder-canvas');\n    this.ctx = this.canvas.getContext('2d');\n\n    this.generatedValues = [];\n    this.avatarSize = sizes.avatarSize ?? 54;\n    this.avatarMarginRight = sizes.avatarMarginRight ?? 10;\n    this.marginVertical = sizes.marginVertical ?? 9;\n    this.marginLeft = sizes.marginLeft ?? 17;\n    this.gapVertical = sizes.gapVertical ?? 0;\n    this.totalHeight = sizes.totalHeight ?? (this.avatarSize + this.marginVertical * 2);\n    this.lineHeight = 10;\n    this.lineBorderRadius = 6;\n    this.lineMarginVertical = sizes.lineMarginVertical ?? 8;\n    this.statusWidth = sizes.statusWidth ?? 24;\n    this.noSecondLine = sizes.noSecondLine;\n  }\n\n  public attach({container, rect, getRectFrom, onRemove, blockScrollable}: {\n    container: HTMLElement,\n    rect?: ReturnType<DialogsPlaceholder['getRectFrom']>,\n    getRectFrom?: HTMLElement | DialogsPlaceholder['getRectFrom'],\n    onRemove?: DialogsPlaceholder['onRemove'],\n    blockScrollable?: DialogsPlaceholder['blockScrollable']\n  }) {\n    const {canvas} = this;\n\n    this.detachTime = undefined;\n    this.onRemove = onRemove;\n    this.getRectFrom = typeof(getRectFrom) === 'function' ? getRectFrom : (getRectFrom || container).getBoundingClientRect.bind(getRectFrom || container);\n    if(this.blockScrollable = blockScrollable) {\n      blockScrollable.container.style.overflowY = 'hidden';\n    }\n\n    this.updateCanvasSize(rect);\n    this.startAnimation();\n    container.append(canvas);\n  }\n\n  public detach(availableLength: number) {\n    if(this.detachTime) {\n      return;\n    }\n\n    this.availableLength = availableLength;\n    this.detachTime = Date.now();\n\n    if(!liteMode.isAvailable('animations')) {\n      this.remove();\n    }\n  }\n\n  public removeWithoutUnmounting() {\n    this.stopAnimation();\n    this.onRemove?.();\n    this.onRemove = undefined;\n  }\n\n  public remove() {\n    this.stopAnimation();\n\n    if(this.canvas.parentElement) {\n      this.canvas.remove();\n\n      if(this.blockScrollable) {\n        this.blockScrollable.container.style.overflowY = '';\n        this.blockScrollable = undefined;\n      }\n    }\n\n    this.onRemove?.();\n    this.onRemove = undefined;\n  }\n\n  private updateCanvasSize(rect = this.getRectFrom()) {\n    const {canvas} = this;\n    const dpr = canvas.dpr = window.devicePixelRatio;\n    canvas.width = rect.width * dpr;\n    canvas.height = rect.height * dpr;\n    canvas.style.width = rect.width + 'px';\n    canvas.style.height = rect.height + 'px';\n  }\n\n  private renderDetachAnimationFrame() {\n    const {\n      canvas,\n      ctx,\n      detachTime,\n      length,\n      availableLength\n    } = this;\n\n    if(!detachTime) {\n      return;\n    } else if(!liteMode.isAvailable('animations')) {\n      this.remove();\n      return;\n    }\n\n    const {width} = canvas;\n\n    ctx.globalCompositeOperation = 'destination-out';\n\n    // ctx.fillStyle = 'rgba(0, 0, 0, 0)';\n    // ctx.fillRect(0, 0, width, height);\n\n    // const DURATION = 500;\n    // const DELAY = DURATION;\n    const DURATION = 150;\n    const DELAY = 15;\n    const elapsedTime = Date.now() - detachTime;\n    let completed = true;\n    for(let i = 0; i < length; ++i) {\n      const delay = availableLength < length && i >= availableLength ? DELAY * (availableLength - 1) : DELAY * i;\n      const elapsedRowTime = elapsedTime - delay;\n      if(elapsedRowTime <= 0) {\n        completed = false;\n        continue;\n      }\n\n      const progress = easeInOutSine(elapsedRowTime, 0, 1, DURATION);\n\n      ctx.beginPath();\n      ctx.rect(0, this.dialogHeight * i, width, this.dialogHeight);\n      ctx.fillStyle = `rgba(0, 0, 0, ${progress})`;\n      ctx.fill();\n\n      if(progress < 1) {\n        completed = false;\n      }\n    }\n\n    // const totalRadius = Math.sqrt(width ** 2 + height ** 2);\n    // const gradient = ctx.createRadialGradient(\n    //   0, 0, 0,\n    //   0, 0, totalRadius);\n    // gradient.addColorStop(0, 'rgba(0, 0, 0, 1)');\n    // gradient.addColorStop(progress, 'rgba(0, 0, 0, 0)');\n    // gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');\n\n    // const gradient = ctx.createLinearGradient(0, 0, 0, height);\n    // gradient.addColorStop(0, 'rgba(0, 0, 0, 1)');\n    // gradient.addColorStop(progress, 'rgba(0, 0, 0, 0)');\n    // gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');\n\n    // ctx.fillStyle = gradient;\n    // ctx.fillRect(0, 0, width, height);\n\n    ctx.globalCompositeOperation = 'source-over';\n\n    if(completed) {\n      this.remove();\n    }\n  }\n\n  private renderFrame() {\n    this.shimmer.on();\n    this.renderDetachAnimationFrame();\n  }\n\n  private startAnimation() {\n    const {canvas, shimmer} = this;\n    const tempId = ++this.tempId;\n    const pattern = this.createPattern();\n\n    shimmer.settings({\n      canvas,\n      fillStyle: pattern\n    });\n\n    const middleware = () => {\n      return this.tempId === tempId;\n    };\n\n    this.renderFrame();\n    animate(() => {\n      if(!middleware()) {\n        return false;\n      }\n\n      // ! should've removed the loop if animations are disabled\n      if(liteMode.isAvailable('animations')) {\n        this.renderFrame();\n      }\n\n      // ! tempId can be changed during renderFrame\n      return middleware();\n    });\n\n    rootScope.addEventListener('theme_changed', this.onThemeChange);\n    mediaSizes.addEventListener('resize', this.onResize);\n  }\n\n  private stopAnimation() {\n    ++this.tempId;\n    rootScope.removeEventListener('theme_changed', this.onThemeChange);\n    mediaSizes.removeEventListener('resize', this.onResize);\n  }\n\n  private onThemeChange = () => {\n    this.stopAnimation();\n    this.startAnimation();\n  };\n\n  private onResize = () => {\n    const {canvas} = this;\n    const {width, height, dpr} = canvas;\n    this.updateCanvasSize();\n    if(canvas.width === width && canvas.height === height && canvas.dpr === dpr) {\n      return;\n    }\n\n    this.stopAnimation();\n    this.startAnimation();\n  };\n\n  private createPattern() {\n    const {canvas, ctx} = this;\n\n    const patternCanvas = document.createElement('canvas');\n    const patternContext = patternCanvas.getContext('2d');\n    const dpr = canvas.dpr;\n    patternCanvas.dpr = dpr;\n    patternCanvas.width = canvas.width;\n    patternCanvas.height = canvas.height;\n\n    patternContext.fillStyle = customProperties.getProperty('surface-color', this.night);\n    patternContext.fillRect(0, 0, patternCanvas.width, patternCanvas.height);\n\n    patternContext.fillStyle = '#000';\n    patternContext.globalCompositeOperation = 'destination-out';\n\n    const dialogHeight = this.dialogHeight = this.totalHeight * dpr;\n    const gapVertical = this.gapVertical * dpr;\n    let gapVerticalSum = 0;\n    const length = this.length = Math.ceil(canvas.height / dialogHeight);\n    for(let i = 0; i < length; ++i) {\n      this.drawChat(patternContext, i, i * dialogHeight + gapVerticalSum);\n      gapVerticalSum += gapVertical;\n    }\n\n    return ctx.createPattern(patternCanvas, 'no-repeat');\n  }\n\n  private drawChat(ctx: CanvasRenderingContext2D, i: number, y: number) {\n    let generatedValues = this.generatedValues[i];\n    if(!generatedValues) {\n      generatedValues = this.generatedValues[i] = {\n        firstLineWidth: 40 + Math.random() * 100, // 120\n        secondLineWidth: this.noSecondLine ? 0 : 120 + Math.random() * 130, // 240\n        statusWidth: this.statusWidth ? this.statusWidth + Math.random() * 16 : undefined\n      };\n    }\n\n    const {\n      firstLineWidth,\n      secondLineWidth,\n      statusWidth\n    } = generatedValues;\n\n    const {canvas} = ctx;\n    const {dpr} = canvas;\n    y /= dpr;\n\n    const {\n      avatarSize,\n      marginVertical,\n      lineHeight,\n      lineBorderRadius,\n      lineMarginVertical\n    } = this;\n\n    let marginLeft = this.marginLeft;\n\n    if(avatarSize) {\n      drawCircleFromStart(ctx, marginLeft, y + marginVertical, avatarSize / 2, true);\n      marginLeft += avatarSize + this.avatarMarginRight;\n    }\n\n    // 9 + 54 - 10 - 8 = 45 ........ 72 - 9 - 10 - 8\n    roundRect(ctx, marginLeft, y + marginVertical + lineMarginVertical, firstLineWidth, lineHeight, lineBorderRadius, true);\n    // roundRect(ctx, marginLeft, y + marginVertical + avatarSize - lineHeight - lineMarginVertical, secondLineWidth, lineHeight, lineBorderRadius, true);\n    secondLineWidth && roundRect(ctx, marginLeft, y + this.totalHeight - marginVertical - lineHeight - lineMarginVertical, secondLineWidth, lineHeight, lineBorderRadius, true);\n\n    statusWidth && roundRect(ctx, canvas.width / dpr - 24 - statusWidth, y + marginVertical + lineMarginVertical, statusWidth, lineHeight, lineBorderRadius, true);\n  }\n}\n","import App from '@config/app';\nimport DEBUG from '@config/debug';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport {ConnectionStatus} from '@lib/mtproto/connectionStatus';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {AppManagers} from '@lib/managers';\nimport singleInstance from '@lib/singleInstance';\nimport InputSearch from '@components/inputSearch';\n\nconst NO_STATUS = false;\nconst TEST_DBLCLICK = false;\nconst HAVE_RECONNECT_BUTTON = false;\n\nexport default class ConnectionStatusComponent {\n  public static CHANGE_STATE_DELAY = 400;\n  public static INITIAL_DELAY = 2000;\n  public static ANIMATION_DURATION = 250;\n\n  private hadConnect = false;\n  private retryAt: number;\n  private connecting = false;\n  private timedOut = false;\n  private updating = false;\n\n  private log: ReturnType<typeof logger>;\n\n  private setFirstConnectionTimeout: number;\n  private setStateTimeout: number;\n\n  private managers: AppManagers;\n  private inputSearch: InputSearch;\n  private rAF: number;\n\n  public construct(\n    managers: AppManagers,\n    chatsContainer: HTMLElement,\n    inputSearch: InputSearch\n  ) {\n    this.managers = managers;\n    this.inputSearch = inputSearch;\n    this.log = logger('CS', undefined, undefined);\n    this.inputSearch.setPlaceholder('Search');\n\n    rootScope.addEventListener('connection_status_change', (status) => {\n      // console.log(status);\n\n      this.setConnectionStatus();\n    });\n\n    rootScope.addEventListener('state_synchronizing', () => {\n      this.updating = true;\n      DEBUG && this.log('updating', this.updating);\n      this.setState();\n    });\n\n    rootScope.addEventListener('state_synchronized', () => {\n      DEBUG && this.log('state_synchronized');\n      this.updating = false;\n      DEBUG && this.log('updating', this.updating);\n      this.setState();\n    });\n\n    this.setFirstConnectionTimeout = window.setTimeout(\n      this.setConnectionStatus,\n      ConnectionStatusComponent.INITIAL_DELAY\n    );\n\n    if(TEST_DBLCLICK) {\n      let bool = true;\n      document.addEventListener('dblclick', () => {\n        this.setConnectionStatus(bool ? (\n            bool = false,\n            ConnectionStatus.Closed\n          ) : (\n            bool = true,\n            this.updating = false,\n            ConnectionStatus.Connected\n          )\n        );\n      });\n    }\n  }\n\n  private setConnectionStatus = (overrideStatus?: ConnectionStatus) => {\n    Promise.all([\n      rootScope.managers.apiManager.getBaseDcId(),\n      rootScope.managers.rootScope.getConnectionStatus()\n    ]).then(([baseDcId, connectionStatus]) => {\n      if(!baseDcId) {\n        baseDcId = App.baseDcId;\n      }\n\n      if(this.setFirstConnectionTimeout) {\n        clearTimeout(this.setFirstConnectionTimeout);\n        this.setFirstConnectionTimeout = 0;\n      }\n\n      const status = connectionStatus['NET-' + baseDcId];\n      const online = status && (overrideStatus ?? status.status) === ConnectionStatus.Connected;\n\n      if(this.connecting && online) {\n        this.managers.apiUpdatesManager.forceGetDifference();\n      }\n\n      if(online && !this.hadConnect) {\n        this.hadConnect = true;\n      }\n\n      this.timedOut = status && (overrideStatus ?? status.status) === ConnectionStatus.TimedOut;\n      this.connecting = !online;\n      this.retryAt = status && status.retryAt;\n      DEBUG && this.log('connecting', this.connecting);\n      this.setState();\n    });\n  };\n\n  private wrapSetStatusText = (...args: Parameters<InputSearch['setPlaceholder']>) => {\n    return () => {\n      return this.inputSearch.setPlaceholder(...args);\n    };\n  };\n\n  private getA(langPackKey: LangPackKey, callback: () => void) {\n    const a = document.createElement('a');\n    a.classList.add('force-reconnect');\n    a.append(i18n(langPackKey));\n    attachClickEvent(a, (e) => {\n      cancelEvent(e);\n      callback();\n    });\n\n    return a;\n  }\n\n  private setState = () => {\n    if(singleInstance.deactivatedReason) {\n      return;\n    }\n\n    let setText: () => void;\n    if(this.connecting) {\n      if(this.timedOut) {\n        // const a = this.getA('ConnectionStatus.ForceReconnect', () => this.managers.networkerFactory.forceReconnect());\n        // setText = this.wrapSetStatusText('ConnectionStatus.TimedOut', [a]);\n        setText = this.wrapSetStatusText('Updating');\n      } else if(this.hadConnect) {\n        if(this.retryAt !== undefined) {\n          const timerSpan = document.createElement('span');\n          const retryAt = this.retryAt;\n          const setTime = () => {\n            const now = Date.now();\n            timerSpan.innerText = '' + Math.max(0, Math.round((retryAt - now) / 1000));\n            if(now > retryAt) {\n              clearInterval(interval);\n            }\n          };\n          const interval = setInterval(setTime, 1e3);\n          setTime();\n\n          if(HAVE_RECONNECT_BUTTON) {\n            const a = this.getA('ConnectionStatus.Reconnect', () => this.managers.networkerFactory.forceReconnectTimeout());\n            setText = this.wrapSetStatusText('ConnectionStatus.ReconnectIn', [timerSpan, a]);\n          } else {\n            setText = this.wrapSetStatusText('ConnectionStatus.ReconnectInPlain', [timerSpan]);\n          }\n        } else {\n          setText = this.wrapSetStatusText('ConnectionStatus.Reconnecting');\n        }\n      } else {\n        setText = this.wrapSetStatusText('ConnectionStatus.Waiting');\n      }\n    } else if(this.updating) {\n      setText = this.wrapSetStatusText('Updating');\n    } else {\n      setText = this.wrapSetStatusText('Search');\n    }\n\n    DEBUG && this.log('setState', this.connecting || this.updating);\n    if(this.rAF) window.cancelAnimationFrame(this.rAF);\n    this.rAF = window.requestAnimationFrame(() => {\n      this.rAF = 0;\n      if(this.setStateTimeout) clearTimeout(this.setStateTimeout);\n\n      const wasVisible = this.inputSearch.isLoading();\n      const cb = () => {\n        if(NO_STATUS) {\n          return;\n        }\n\n        setText();\n        const isConnecting = this.connecting || this.updating;\n        this.inputSearch.toggleLoading(isConnecting);\n        this.setStateTimeout = 0;\n        DEBUG && this.log('setState: isShown:', isConnecting);\n      };\n\n      if(wasVisible) {\n        cb();\n      } else {\n        this.setStateTimeout = window.setTimeout(cb, ConnectionStatusComponent.CHANGE_STATE_DELAY);\n      }\n    });\n  };\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport ButtonIcon from '@components/buttonIcon';\nimport ConnectionStatusComponent from '@components/connectionStatus';\nimport Icon from '@components/icon';\nimport InputField from '@components/inputField';\nimport ProgressivePreloader from '@components/preloader';\nimport SetTransition from '@components/singleTransition';\nimport classNames from '@helpers/string/classNames';\n\nexport default class InputSearch {\n  public container: HTMLElement;\n  public input: HTMLInputElement;\n  public inputField: InputField;\n  public clearBtn: HTMLElement;\n  public searchIcon: HTMLElement;\n  public backBtn: HTMLElement;\n\n  public prevValue = '';\n  public timeout = 0;\n  public onChange: (value: string) => void;\n  public onClear: (e?: MouseEvent, wasEmpty?: boolean) => void;\n  public onDebounce: (start: boolean) => void;\n  public onBack: () => void;\n  public onEnter: (value: string) => void;\n\n  private statusPreloader: ProgressivePreloader;\n  private currentLangPackKey: LangPackKey;\n  public currentPlaceholder: HTMLElement;\n\n  private listenerSetter: ListenerSetter;\n  private debounceTime: number;\n  private verifyDebounce: (value: string, prevValue: string) => boolean;\n\n  private alwaysShowClear: boolean;\n  private arrowBack: boolean;\n  private noPlaceholderAnimation: boolean;\n\n  constructor(options: {\n    placeholder?: LangPackKey,\n    onChange?: (value: string) => void,\n    onClear?: InputSearch['onClear'],\n    onFocusChange?: (isFocused: boolean) => void,\n    onDebounce?: (start: boolean) => void,\n    onBack?: () => void,\n    onEnter?: (value: string) => void,\n    alwaysShowClear?: boolean,\n    noBorder?: boolean,\n    noFocusEffect?: boolean,\n    debounceTime?: number,\n    verifyDebounce?: (value: string, prevValue: string) => boolean,\n    arrowBack?: boolean,\n    oldStyle?: boolean,\n    noPlaceholderAnimation?: boolean\n  } = {}) {\n    this.inputField = new InputField({\n      // placeholder,\n      plainText: true,\n      withBorder: !options.noBorder\n    });\n\n    this.listenerSetter = new ListenerSetter();\n    this.container = this.inputField.container;\n    this.container.classList.remove('input-field');\n    this.container.classList.add('input-search');\n\n    if(options.oldStyle) {\n      this.container.classList.add('old-style');\n    }\n\n    this.onChange = options.onChange;\n    this.onClear = options.onClear;\n    this.onDebounce = options.onDebounce;\n    this.onBack = options.onBack;\n    this.onEnter = options.onEnter;\n    this.debounceTime = options.debounceTime ?? 300;\n    this.verifyDebounce = options.verifyDebounce;\n    this.alwaysShowClear = options.alwaysShowClear;\n    this.noPlaceholderAnimation = options.noPlaceholderAnimation;\n\n    const input = this.input = this.inputField.input as HTMLInputElement;\n    input.classList.add('input-search-input');\n\n    if(!options.noFocusEffect) {\n      input.classList.add('with-focus-effect');\n    }\n\n    const searchIcon = this.searchIcon = this.createIcon('search', 'input-search-icon');\n    const clearBtn = this.clearBtn = this.createButtonIcon('close', 'input-search-clear');\n\n    this.listenerSetter.add(input)('input', this.onInput);\n    this.listenerSetter.add(input)('keydown', this.onKeyDown);\n    attachClickEvent(clearBtn, this.onClearClick, {listenerSetter: this.listenerSetter, cancelMouseDown: true});\n\n    if(options.placeholder) {\n      (input as HTMLInputElement).placeholder = ' ';\n      this.setPlaceholder(options.placeholder);\n    }\n\n    if(options.onFocusChange) {\n      this.listenerSetter.add(input)('focusin', () => {\n        options.onFocusChange?.(true);\n      });\n\n      this.listenerSetter.add(input)('focusout', () => {\n        options.onFocusChange?.(false);\n      });\n    }\n\n    this.container.append(searchIcon, clearBtn);\n\n    this.setArrowBack(options.arrowBack);\n  }\n\n  public setArrowBack = (arrowBack: boolean) => {\n    if(this.arrowBack === arrowBack) return;\n    this.arrowBack = arrowBack;\n\n    this.container.classList.toggle('with-arrow-back', arrowBack);\n\n    if(arrowBack && !this.backBtn) {\n      this.backBtn = this.createButtonIcon('arrow_prev', 'input-search-icon', 'input-search-back');\n      this.container.append(this.backBtn);\n      attachClickEvent(this.backBtn, this.onBack, {listenerSetter: this.listenerSetter, cancelMouseDown: true});\n    }\n\n    this.searchIcon.classList.toggle('hide', arrowBack);\n    this.backBtn && this.backBtn.classList.toggle('hide', !arrowBack);\n    this.clearBtn.classList.toggle('always-visible', !arrowBack && !!this.alwaysShowClear);\n  };\n\n  public createButtonIcon(icon: Icon, ...args: string[]) {\n    args ??= [];\n    args.push('input-search-part', 'input-search-button');\n    return ButtonIcon(icon + ' ' + args.join(' '), {noRipple: true});\n  }\n\n  public createIcon(icon: Icon, ...args: string[]) {\n    return Icon(icon, 'input-search-part', ...args);\n  }\n\n  public isLoading() {\n    return this.container.classList.contains('is-connecting');\n  }\n\n  public toggleLoading(loading: boolean) {\n    const another = this.arrowBack ? this.clearBtn : this.searchIcon;\n    if(!this.statusPreloader) {\n      this.statusPreloader = new ProgressivePreloader({cancelable: false});\n      this.statusPreloader.constructContainer({color: 'transparent', bold: true});\n      this.statusPreloader.construct?.();\n      this.statusPreloader.preloader.classList.add('is-visible', 'will-animate');\n      another.classList.add('will-animate');\n    }\n\n    if(loading && !this.statusPreloader.preloader.parentElement) {\n      this.container.append(this.statusPreloader.preloader);\n    }\n\n    this.statusPreloader.preloader.classList.toggle('is-hiding', !loading);\n    another.classList.toggle('is-hiding', loading || (another === this.clearBtn && this.inputField.isEmpty()));\n    SetTransition({\n      element: this.container,\n      className: 'is-connecting',\n      forwards: loading,\n      duration: ConnectionStatusComponent.ANIMATION_DURATION,\n      onTransitionEnd: loading ? undefined : () => {\n        this.statusPreloader.preloader.remove();\n      }\n      // useRafs: this.statusPreloader.preloader.isConnected ? 0 : 2\n    });\n  }\n\n  public setPlaceholder = (langPackKey: LangPackKey, args?: any[]) => {\n    if(this.currentLangPackKey === langPackKey) return;\n    this.currentLangPackKey = langPackKey;\n\n    const oldPlaceholder = this.currentPlaceholder;\n    if(oldPlaceholder) {\n      SetTransition({\n        element: oldPlaceholder,\n        className: 'is-hiding',\n        forwards: true,\n        duration: ConnectionStatusComponent.ANIMATION_DURATION,\n        onTransitionEnd: () => {\n          oldPlaceholder.remove();\n        }\n      });\n    }\n\n    this.currentPlaceholder = i18n(langPackKey, args);\n    this.currentPlaceholder.classList.add(...[\n      'input-search-placeholder',\n      !this.noPlaceholderAnimation && 'will-animate'\n    ].filter(Boolean));\n    this.container.append(this.currentPlaceholder);\n  };\n\n  onInput = () => {\n    if(!this.onChange) return;\n\n    const {value, prevValue} = this;\n    if(value === prevValue) {\n      return;\n    }\n\n    this.prevValue = value;\n    if(this.verifyDebounce?.(value, prevValue) === false) {\n      this.clearTimeout(false);\n      this.onChange(value);\n      return;\n    }\n\n    this.clearTimeout(true);\n    this.timeout = window.setTimeout(() => {\n      this.onDebounce?.(false);\n      this.onChange(value);\n    }, this.debounceTime);\n  };\n\n  onKeyDown = (e: KeyboardEvent) => {\n    if(e.key !== 'Enter' || !this.onEnter) return;\n    const value = this.value;\n    if(!value) return;\n    this.onEnter(value);\n  };\n\n  onClearClick = (e?: MouseEvent) => {\n    const isEmpty = this.inputField.isEmpty();\n    this.value = '';\n    this.onChange?.('');\n    this.onClear?.(e, isEmpty);\n  };\n\n  clearTimeout = (debounceStart: boolean) => {\n    clearTimeout(this.timeout);\n    this.onDebounce?.(debounceStart);\n  };\n\n  get value() {\n    return this.inputField.value;\n  }\n\n  set value(value: string) {\n    this.prevValue = value;\n    this.clearTimeout(false);\n    this.inputField.value = value;\n  }\n\n  public remove() {\n    this.clearTimeout(false);\n    this.verifyDebounce = undefined;\n    this.listenerSetter.removeAll();\n  }\n}\n","import TransitionSlider from '@components/transition';\nimport {ScrollableX} from '@components/scrollable';\nimport {fastRaf} from '@helpers/schedulers';\nimport fastSmoothScroll, {FocusDirection} from '@helpers/fastSmoothScroll';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport whichChild from '@helpers/dom/whichChild';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport liteMode from '@helpers/liteMode';\nimport {ScrollableContextValue} from '@components/scrollable2';\n\ntype OnChangeArgs = {\n  element: HTMLElement;\n  active: boolean;\n};\n\ntype Args = {\n  tabs: HTMLElement;\n  content: HTMLElement,\n  onClick?: (id: number, tabContent: HTMLDivElement, animate: boolean) => void | boolean | Promise<void | boolean>;\n  onTransitionEnd?: () => void;\n  transitionTime?: number;\n  scrollableX?: ScrollableX | ScrollableContextValue;\n  listenerSetter?: ListenerSetter;\n  onChange?: (args: OnChangeArgs) => void;\n};\n\nexport type SelectTargetArgs = {\n  target: HTMLElement;\n  id: number;\n  animate?: boolean;\n  tabs: HTMLElement;\n  content?: HTMLElement;\n  onClick?: Args['onClick'];\n  scrollableX?: Args['scrollableX'];\n  transitionTime?: number;\n  prevId?: number;\n  selectTab?: (id: number, animate: boolean) => void;\n  onChange?: (args: OnChangeArgs) => void;\n};\n\nexport async function selectTarget({\n  target,\n  id,\n  animate = true,\n  tabs,\n  content,\n  onClick,\n  scrollableX,\n  transitionTime = 200,\n  prevId = -1,\n  selectTab,\n  onChange\n}: SelectTargetArgs) {\n  if(onClick) {\n    const tabContent = content?.children[id] as HTMLDivElement;\n    const result1 = onClick(id, tabContent, animate);\n    const canChange = result1 instanceof Promise ? await result1 : result1;\n    if(canChange === false) {\n      return;\n    }\n  }\n\n  if(!target) {\n    return false;\n  }\n\n  if(scrollableX) {\n    const containerEl = scrollableX.container;\n    // Skip the scroll round-trip when there's no actual scrolling to do:\n    //   - row has no horizontal overflow (every tab is already visible)\n    //   - selecting the first tab while already at scrollLeft 0 (you can't\n    //     scroll past the start to \"center\" it, so fastSmoothScroll\n    //     clamps path to 0 and no-ops anyway)\n    // Common at the moment the search panel opens — `selectTab(0)` runs\n    // against a row whose scroll position is the default 0.\n    const noOverflow = containerEl.scrollWidth <= containerEl.clientWidth;\n    const isFirstAndAtStart = id === 0 && containerEl.scrollLeft === 0;\n    if(!noOverflow && !isFirstAndAtStart) {\n      fastSmoothScroll({\n        container: containerEl,\n        element: target.parentElement.children[id] as HTMLElement,\n        position: 'center',\n        forceDirection: animate ? undefined : FocusDirection.Static,\n        forceDuration: transitionTime,\n        axis: 'x'\n      });\n    }\n  }\n\n  if(!liteMode.isAvailable('animations')) {\n    animate = false;\n  }\n\n  if(target.classList.contains('active') || id === prevId) {\n    return false;\n  }\n\n  const mutateCallback = animate ? fastRaf : (cb: () => void) => cb();\n\n  const prev = tabs.querySelector(tabs.firstElementChild.tagName.toLowerCase() + '.active') as HTMLElement;\n  if(prev) {\n    mutateCallback(() => {\n      prev.classList.remove('active');\n      onChange?.({element: prev, active: false});\n    });\n  }\n\n  // a great stripe from Jolly Cobra\n  if(prevId !== -1 && animate) {\n    const selector = '.menu-horizontal-div-item-background';\n    mutateCallback(() => {\n      const indicator = target.querySelector(selector) as HTMLElement;\n      const previous = target.parentElement.children[prevId];\n      const currentIndicator = previous?.querySelector(selector) as HTMLElement;\n\n      // the callback runs a frame later, by which point the row may have been rebuilt or the\n      // previous item removed — the stripe is decoration, so skip it rather than throw\n      if(!indicator || !currentIndicator) {\n        return;\n      }\n\n      currentIndicator.classList.remove('animate');\n      indicator.classList.remove('animate');\n\n      const shiftLeft = currentIndicator.parentElement.offsetLeft - indicator.parentElement.offsetLeft;\n      const clientWidth = indicator.clientWidth;\n      const scaleFactor = currentIndicator.clientWidth / clientWidth;\n      indicator.style.transform = `translate3d(${shiftLeft}px, 0, 0)`;\n      indicator.style.width = `${clientWidth * scaleFactor}px`;\n\n      fastRaf(() => {\n        indicator.classList.add('animate');\n        indicator.style.transform = 'none';\n        indicator.style.width = '';\n      });\n    });\n  }\n\n  mutateCallback(() => {\n    target.classList.add('active');\n    onChange?.({element: target, active: true});\n  });\n\n  selectTab?.(id, animate);\n}\n\nexport function horizontalMenuObjArgs({tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange}: Args) {\n  return horizontalMenu(tabs, content, onClick, onTransitionEnd, transitionTime, scrollableX, listenerSetter, onChange);\n}\n\nexport function horizontalMenu(\n  tabs: Args['tabs'],\n  content: Args['content'],\n  onClick?: Args['onClick'],\n  onTransitionEnd?: Args['onTransitionEnd'],\n  transitionTime: Args['transitionTime'] = 200,\n  scrollableX?: Args['scrollableX'],\n  listenerSetter?: Args['listenerSetter'],\n  onChange?: Args['onChange']\n) {\n  const _selectTab = TransitionSlider({\n    content,\n    type: tabs || content.dataset.animation === 'tabs' ? 'tabs' : 'navigation',\n    transitionTime,\n    onTransitionEnd,\n    listenerSetter\n  });\n\n  if(!tabs) {\n    return _selectTab;\n  }\n\n  const _selectTarget = (target: HTMLElement, id: number, animate = true) => {\n    return selectTarget({\n      target,\n      id,\n      animate,\n      tabs,\n      content,\n      onClick,\n      scrollableX,\n      transitionTime,\n      prevId: _selectTab.prevId(),\n      selectTab: _selectTab,\n      onChange\n    });\n  };\n\n  const proxy = new Proxy(_selectTab, {\n    apply: (target, that, args) => {\n      const animate = args[1] !== undefined ? args[1] : true;\n\n      let id: number, el: HTMLElement;\n      if(args[0] instanceof HTMLElement) {\n        id = whichChild(args[0]);\n        el = args[0];\n      } else {\n        id = +args[0];\n        el = (tabs.querySelector(`[data-tab=\"${id}\"]`) || tabs.children[id]) as HTMLElement;\n      }\n\n      _selectTarget(el, id, animate);\n    }\n  });\n\n  attachClickEvent(tabs, (e) => {\n    let target = e.target as HTMLElement;\n    target = findUpAsChild(target, tabs);\n    if(!target) return false;\n\n    let id: number;\n    if(target.dataset.tab) {\n      id = +target.dataset.tab;\n      if(id === -1) {\n        return false;\n      }\n    } else {\n      id = whichChild(target);\n    }\n\n    _selectTarget(target, id);\n  }, {listenerSetter});\n\n  return proxy;\n}\n","import {horizontalMenu} from '@components/horizontalMenu';\nimport Scrollable from '@components/scrollable2';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport classNames from '@helpers/string/classNames';\nimport {Accessor, JSX, For, onCleanup, createContext, Ref, untrack} from 'solid-js';\n\nconst TabsContext = createContext<{\n}>();\n\nconst Tabs = (props: {\n  // tab: Accessor<number>,\n  // onChange: (index: number) => void,\n  children: JSX.Element\n}) => {\n  return (\n    <TabsContext.Provider value={{}}>\n      {props.children}\n    </TabsContext.Provider>\n  );\n};\n\nTabs.Menu = (props: {\n  class?: string,\n  id?: string,\n  ref?: Ref<HTMLDivElement>,\n  onClick?: (e: MouseEvent) => void,\n  children: JSX.Element\n}) => {\n  return (\n    <div\n      ref={props.ref}\n      class={classNames('menu-horizontal-div', props.class)}\n      id={props.id}\n      onClick={props.onClick}\n    >\n      {props.children}\n    </div>\n  );\n};\n\nTabs.MenuTab = (props: {\n  ref?: Ref<HTMLDivElement>,\n  class?: string,\n  children: JSX.Element\n}) => {\n  return (\n    <div ref={props.ref} class={classNames('menu-horizontal-div-item', props.class)}>\n      <i class=\"menu-horizontal-div-item-background\" />\n      <div class=\"menu-horizontal-div-item-span\">\n        {props.children}\n      </div>\n    </div>\n  );\n};\n\nTabs.MenuScrollable = (props: {\n  ref?: Ref<HTMLDivElement>,\n  scrollableProps?: Partial<Parameters<typeof Scrollable>[0]>,\n  class?: string,\n  children: JSX.Element\n}) => {\n  return (\n    <div ref={props.ref} class={classNames('menu-horizontal-scrollable', props.class)}>\n      <Scrollable axis=\"x\" {...(props.scrollableProps || {})}>\n        {props.children}\n      </Scrollable>\n    </div>\n  );\n};\n\nTabs.MenuGradient = (props: {\n  color: 'surface' | 'background',\n  smaller?: boolean,\n  className?: string,\n  ref?: Ref<HTMLDivElement>\n}) => {\n  return (\n    <div\n      ref={props.ref}\n      class={classNames(\n        'menu-horizontal-gradient-container',\n        props.className && props.className + '-container'\n      )}\n    >\n      <div\n        class={classNames(\n          'menu-horizontal-gradient',\n          'menu-horizontal-gradient-color-' + props.color,\n          props.smaller && 'menu-horizontal-gradient-smaller',\n          props.className\n        )}\n      ></div>\n    </div>\n  );\n};\n\nTabs.Content = (props: {\n  class: string,\n  ref?: Ref<HTMLDivElement>,\n  children: JSX.Element,\n  onClick?: (e: MouseEvent) => void\n}) => {\n  return (\n    <div ref={props.ref} class={props.class}>\n      {props.children}\n    </div>\n  );\n};\n\nTabs.ContentTab = (props: {\n  class: string,\n  hide: boolean,\n  children: JSX.Element\n}) => {\n  return (\n    <div class={classNames(props.class, props.hide && 'hide')}>\n      {props.children}\n    </div>\n  );\n};\n\nTabs.Simple = (props: {\n  tab: Accessor<number>,\n  onChange: (index: number) => void,\n  menu: JSX.Element[],\n  content: JSX.Element[],\n  class: string\n}) => {\n  const className = untrack(() => props.class);\n\n  let tabs: HTMLDivElement, content: HTMLDivElement;\n  const ret = (\n    <Tabs>\n      <Tabs.Menu ref={tabs} class={`${className}-tabs`}>\n        <For each={props.menu}>{(item) => {\n          return (\n            <Tabs.MenuTab class={`${className}-tab`}>{item}</Tabs.MenuTab>\n          );\n        }}</For>\n      </Tabs.Menu>\n      <Tabs.Content ref={content} class={classNames(`${className}-contents`)}>\n        <For each={props.content}>{(item, index) => {\n          return (\n            <Tabs.ContentTab class={`${className}-content`} hide={index() !== props.tab()}>{item}</Tabs.ContentTab>\n          );\n        }}</For>\n      </Tabs.Content>\n    </Tabs>\n  );\n\n  const listenerSetter = new ListenerSetter();\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n\n  const selectTab = horizontalMenu(\n    tabs,\n    content,\n    (tab) => {\n      props.onChange(tab);\n    },\n    undefined,\n    undefined,\n    undefined,\n    listenerSetter\n  );\n  selectTab(props.tab());\n\n  return ret;\n};\n\nexport default Tabs;\n","import Scrollable from '@components/scrollable';\nimport InputSearch from '@components/inputSearch';\nimport SettingSection from '@components/settingSection';\nimport PeerTitle from '@components/peerTitle';\nimport {avatarNew} from '@components/avatarNew';\nimport Icon from '@components/icon';\nimport Tabs from '@components/tabs';\nimport {observeResize} from '@components/resizeObserver';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport liteMode from '@helpers/liteMode';\nimport {FocusDirection} from '@helpers/fastSmoothScroll';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\n\nexport default class SelectorSearch {\n  public section: SettingSection;\n  public selectedContainer: HTMLElement;\n  public inputSearch: InputSearch;\n  public input: HTMLInputElement;\n  public gradient: HTMLElement;\n  private selectedScrollable: Scrollable;\n  private capturedRects: Map<HTMLElement, DOMRect>;\n  private flipElements: Set<HTMLElement>;\n  private middlewareHelper: MiddlewareHelper;\n  private chipsMap: Map<string, HTMLElement>;\n\n  constructor(options: {\n    middlewareHelper: MiddlewareHelper,\n    multiSelect: boolean,\n    onInput: () => void,\n    onChipClick: (key: string | PeerId) => void\n  }) {\n    this.middlewareHelper = options.middlewareHelper;\n    this.chipsMap = new Map();\n    this.flipElements = new Set();\n\n    this.inputSearch = new InputSearch({\n      placeholder: 'Search',\n      onChange: options.onInput,\n      debounceTime: 200,\n      noBorder: true,\n      noFocusEffect: true,\n      noPlaceholderAnimation: true\n    });\n    this.input = this.inputSearch.input;\n    this.inputSearch.container.classList.add('selector-search-input-container');\n    this.input.classList.add('selector-search-input');\n    this.inputSearch.clearBtn.remove();\n\n    const section = this.section = new SettingSection({});\n    section.innerContainer.classList.add('selector-search-section');\n    section.container.classList.add('selector-search-section-container');\n    const topContainer = document.createElement('div');\n    topContainer.classList.add('selector-search-container');\n\n    this.selectedContainer = document.createElement('div');\n    this.selectedContainer.classList.add('selector-search');\n\n    this.selectedContainer.append(this.inputSearch.container);\n    this.flipElements.add(this.inputSearch.container);\n    topContainer.append(this.selectedContainer);\n    this.selectedScrollable = new Scrollable(topContainer);\n\n    this.setupHeightAnimation();\n\n    if(options.multiSelect) attachClickEvent(this.selectedContainer, (e) => {\n      let target = e.target as HTMLElement;\n      target = findUpClassName(target, 'selector-user');\n      if(!target) return;\n      let key: string | PeerId = target.dataset.key;\n      key = key.isPeerId() ? key.toPeerId() : key;\n      options.onChipClick(key);\n    });\n\n    section.content.append(topContainer);\n\n    this.gradient = Tabs.MenuGradient({\n      color: 'background',\n      className: 'selector-search-gradient',\n      smaller: true\n    }) as HTMLElement;\n  }\n\n  private setupHeightAnimation() {\n    if(!liteMode.isAvailable('animations')) return;\n\n    let prevHeight = 0;\n    let isAnimating = false;\n    const el = this.selectedContainer;\n    const unobserve = observeResize(el, () => {\n      if(isAnimating) return;\n\n      el.style.height = '';\n      const targetHeight = el.clientHeight;\n      if(!prevHeight || targetHeight === prevHeight) {\n        prevHeight = targetHeight;\n        return;\n      }\n\n      if(!targetHeight) {\n        prevHeight = targetHeight;\n        return;\n      }\n\n      isAnimating = true;\n      el.style.height = prevHeight + 'px';\n      void el.offsetHeight;\n      el.style.height = targetHeight + 'px';\n      prevHeight = targetHeight;\n    });\n\n    el.addEventListener('transitionend', (e) => {\n      if(e.target === el && e.propertyName === 'height') {\n        isAnimating = false;\n        el.style.height = '';\n      }\n    });\n\n    this.middlewareHelper.get().onDestroy(unobserve);\n  }\n\n  private captureChildRects(exclude?: HTMLElement) {\n    if(!liteMode.isAvailable('animations')) return;\n    this.capturedRects = new Map();\n    for(const el of this.flipElements) {\n      if(el !== exclude) {\n        this.capturedRects.set(el, el.getBoundingClientRect());\n      }\n    }\n  }\n\n  private animateChildrenFlip(exclude?: HTMLElement) {\n    const rects = this.capturedRects;\n    if(!rects) return;\n    this.capturedRects = undefined;\n\n    const toAnimate: HTMLElement[] = [];\n    for(const [el, prevRect] of rects) {\n      if(el === exclude) {\n        continue;\n      }\n\n      const newRect = el.getBoundingClientRect();\n      const dx = prevRect.left - newRect.left;\n      const dy = prevRect.top - newRect.top;\n      if(!dx && !dy) continue;\n\n      el.style.transition = 'none';\n      el.style.transform = `translate(${dx}px, ${dy}px)`;\n      toAnimate.push(el);\n    }\n\n    if(!toAnimate.length) return;\n    void this.selectedContainer.offsetHeight;\n    for(const el of toAnimate) {\n      el.style.transition = '';\n      el.style.transform = '';\n    }\n  }\n\n  public addChip({\n    key,\n    middleware,\n    title,\n    scroll = true,\n    avatarSize = 30,\n    fallbackIcon,\n    primary\n  }: {\n    key: PeerId | string,\n    middleware: Middleware,\n    title?: string | HTMLElement,\n    scroll?: boolean,\n    avatarSize?: number,\n    fallbackIcon?: Icon,\n    primary?: boolean\n  }) {\n    const rendered = SelectorSearch.renderEntity({\n      key,\n      middleware,\n      title,\n      avatarSize,\n      fallbackIcon,\n      primary\n    });\n    const {element, promises} = rendered;\n\n    const keyStr = '' + key;\n    this.chipsMap.set(keyStr, element);\n\n    const insert = () => {\n      if(this.chipsMap.get(keyStr) !== element) {\n        return;\n      }\n\n      if(scroll) {\n        element.classList.add('scale-in');\n        element.addEventListener('animationend', () => {\n          element.classList.remove('scale-in');\n        }, {once: true});\n      }\n\n      const prevLast = this.inputSearch.container.previousElementSibling as HTMLElement;\n      if(prevLast?.classList.contains('selector-user')) {\n        prevLast.classList.remove('is-last');\n      }\n      element.classList.add('is-last');\n\n      this.captureChildRects();\n      this.flipElements.add(element);\n      this.inputSearch.container.before(element);\n      this.animateChildrenFlip();\n\n      if(scroll) {\n        this.selectedScrollable.scrollIntoViewNew({\n          element: this.inputSearch.container,\n          position: 'center'\n        });\n      }\n    };\n\n    if(promises.length) {\n      Promise.all(promises).then(insert);\n    } else {\n      insert();\n    }\n\n    return rendered;\n  }\n\n  public removeChip(key: PeerId | string, onRemoved?: () => void) {\n    const keyStr = '' + key;\n    const div = this.chipsMap.get(keyStr) as HTMLElement;\n    const cleanup = () => {\n      if(div) {\n        div.remove();\n        div.middlewareHelper.destroy();\n      }\n\n      onRemoved?.();\n    };\n\n    this.chipsMap.delete(keyStr);\n    if(div) this.flipElements.delete(div);\n\n    if(!div?.parentElement) {\n      cleanup();\n      return;\n    }\n\n    const animate = liteMode.isAvailable('animations');\n    const wasLast = div.classList.contains('is-last');\n\n    if(animate) {\n      this.captureChildRects(div);\n      const chipRect = div.getBoundingClientRect();\n      const containerRect = this.selectedContainer.getBoundingClientRect();\n      const scrollEl = this.selectedScrollable.container;\n      const scrollBefore = scrollEl.scrollTop;\n\n      // Take chip out of flex flow so layout reflows immediately\n      div.classList.remove('scale-in', 'is-last');\n      div.style.position = 'absolute';\n      div.style.left = (chipRect.left - containerRect.left) + 'px';\n\n      const initialTop = chipRect.top - containerRect.top;\n      const scrollDelta = scrollBefore - scrollEl.scrollTop;\n\n      if(scrollDelta) {\n        // Start at old visual position (compensated), then smoothly\n        // transition to the new position — matching the FLIP animation of neighbors\n        div.style.top = (initialTop - scrollDelta) + 'px';\n        void div.offsetHeight;\n        div.style.transition = 'top .15s ease';\n        div.style.top = initialTop + 'px';\n      } else {\n        div.style.top = initialTop + 'px';\n      }\n    } else {\n      div.classList.remove('scale-in');\n      cleanup();\n    }\n\n    if(wasLast) {\n      const newLast = (animate ? div : this.inputSearch.container).previousElementSibling as HTMLElement;\n      if(newLast?.classList.contains('selector-user')) {\n        newLast.classList.add('is-last');\n      }\n    }\n\n    if(animate) {\n      void div.offsetWidth;\n      div.classList.add('scale-out');\n      this.animateChildrenFlip();\n\n      div.addEventListener('animationend', cleanup, {once: true});\n    }\n  }\n\n  public clearInput() {\n    this.inputSearch.value = '';\n  }\n\n  public get value() {\n    return this.inputSearch.value;\n  }\n\n  public scrollToInput(forceDirection?: FocusDirection) {\n    this.selectedScrollable.scrollIntoViewNew({\n      element: this.inputSearch.container,\n      position: 'center',\n      forceDirection\n    });\n  }\n\n  public destroy() {\n    this.inputSearch.remove();\n  }\n\n  public static renderEntity({\n    key,\n    middleware,\n    title,\n    avatarSize,\n    fallbackIcon,\n    meAsSaved = true,\n    primary\n  }: {\n    key: PeerId | string,\n    middleware: Middleware,\n    title?: string | HTMLElement,\n    avatarSize: number,\n    fallbackIcon?: Icon,\n    meAsSaved?: boolean,\n    primary?: boolean\n  }) {\n    const div = document.createElement('div');\n    div.classList.add('selector-user');\n    div.middlewareHelper = middleware.create();\n\n    if(primary) {\n      div.classList.add('selector-user-primary');\n    }\n\n    const avatarContainer = document.createElement('div');\n    avatarContainer.classList.add('selector-user-avatar-container');\n    const avatarClose = document.createElement('div');\n    avatarClose.classList.add('selector-user-avatar-close');\n    avatarClose.append(Icon('close'));\n    const avatarEl = avatarNew({\n      middleware: div.middlewareHelper.get(),\n      size: avatarSize,\n      isDialog: meAsSaved\n    });\n    avatarEl.node.classList.add('selector-user-avatar');\n    avatarContainer.append(avatarEl.node, avatarClose);\n\n    const keyStr = '' + key;\n    let threadId: number;\n    if(keyStr.includes('_')) { // * handle threads\n      const [_peerId, _threadId] = keyStr.split('_');\n      if(_peerId.isPeerId()) { // * needed\n        key = _peerId.toPeerId();\n        threadId = +_threadId;\n      }\n    }\n\n    div.dataset.key = keyStr;\n    const promises: Promise<any>[] = [];\n    if(key.isPeerId()) {\n      if(title === undefined) {\n        const peerTitle = new PeerTitle();\n        promises.push(peerTitle.update({peerId: key.toPeerId(), threadId, dialog: meAsSaved}));\n        title = peerTitle.element;\n      }\n\n      avatarEl.render({\n        peerId: key.toPeerId(),\n        threadId\n      });\n\n      promises.push(avatarEl.readyThumbPromise);\n    } else if(fallbackIcon) {\n      avatarEl.setIcon(fallbackIcon);\n    }\n\n    if(title) {\n      const t = document.createElement('div');\n      t.classList.add('selector-user-title');\n      if(typeof(title) === 'string') { // * a plain string here is data (a peer title, a date tip), never markup\n        setInnerHTML(t, wrapEmojiText(title));\n      } else {\n        replaceContent(t, title);\n      }\n      div.append(t);\n    }\n\n    div.insertAdjacentElement('afterbegin', avatarContainer);\n\n    return {element: div, avatar: avatarEl, promises};\n  }\n}\n","export default function formatNumber(bytes: number, decimals = 2): string {\n  if(bytes === 0) return '0';\n  if(bytes < 0) return '-' + formatNumber(-bytes, decimals);\n\n  const k = 1000;\n  const dm = decimals < 0 ? 0 : decimals;\n  const sizes = ['', 'K', 'M', 'B', 'T'];\n\n  // * `i` is log-derived and otherwise unbounded at the top, so clamp it to the last\n  // * available unit: an out-of-range magnitude would index past `sizes`, making\n  // * `value + undefined` === NaN and breaking the declared `: string` return.\n  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1);\n\n  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + sizes[i];\n}\n","import type {ChatRights} from '@appManagers/appChatsManager';\nimport type {Dialog} from '@appManagers/appMessagesManager';\nimport type {AppPeersManager, IsPeerType} from '@appManagers/appPeersManager';\nimport appDialogsManager, {AppDialogsManager, DialogElement, DialogElementSize as DialogElementSize} from '@lib/appDialogsManager';\nimport rootScope from '@lib/rootScope';\nimport Scrollable from '@components/scrollable';\nimport {FocusDirection} from '@helpers/fastSmoothScroll';\nimport CheckboxField from '@components/checkboxField';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport findUpAttribute from '@helpers/dom/findUpAttribute';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport InputSearch from '@components/inputSearch';\nimport windowSize from '@helpers/windowSize';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport filterUnique from '@helpers/array/filterUnique';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport filterAsync from '@helpers/array/filterAsync';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport getUserStatusString from '@components/wrappers/getUserStatusString';\nimport {ChannelParticipant, ChannelParticipantsFilter, ChannelsChannelParticipants, Chat, ChatFull, ChatParticipant, ChatParticipants, User} from '@layer';\nimport canSendToUser from '@appManagers/utils/users/canSendToUser';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport getDialogIndex from '@appManagers/utils/dialogs/getDialogIndex';\nimport SettingSection from '@components/settingSection';\nimport emptyPlaceholder from '@components/emptyPlaceholder';\nimport {Middleware, MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport {createSignal, Setter, JSX, createRoot, createEffect} from 'solid-js';\nimport DialogsPlaceholder from '@helpers/dialogsPlaceholder';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport Icon from '@components/icon';\nimport wrapEmojiText from '@richTextProcessor/wrapEmojiText';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {hideToast, toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport SelectorSearch from '@components/selectorSearch';\nimport PopupPremium from '@components/popups/premium';\nimport formatNumber from '@helpers/number/formatNumber';\nimport namedPromises from '@helpers/namedPromises';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {FOLDER_ID_ALL, REAL_FOLDERS} from '@lib/appManagers/constants';\n\nexport type SelectSearchPeerType = 'contacts' | 'dialogs' | 'channelParticipants' | 'custom';\nexport type FilterPeerTypeByFunc = (peer: ReturnType<AppPeersManager['getPeer']>) => boolean;\n\n// TODO: правильная сортировка для addMembers, т.е. для peerType: 'contacts', потому что там идут сначала контакты - потом неконтакты, а должно всё сортироваться по имени\n\nexport default class AppSelectPeers {\n  public container = document.createElement('div');\n  public list = appDialogsManager.createChatList(/* {\n    handheldsSize: 66,\n    avatarSize: 48\n  } */);\n  protected oldList: HTMLElement;\n  public scrollable: Scrollable/*  | ScrollableContextValue */;\n  public selectorSearch: SelectorSearch;\n  public inputSearch: InputSearch;\n  public input: HTMLInputElement;\n\n  // public selected: {[peerId: PeerId]: HTMLElement} = {};\n  public selected = new Set<PeerId | string>();\n  private changes: {key: PeerId | string, add: boolean}[] = [];\n\n  public freezed = false;\n\n  private folderId = 0;\n  private selectedFolderId: number;\n  private offsetIndex = 0;\n  private promise: Promise<any>;\n\n  private query = '';\n  private cachedContacts: PeerId[];\n\n  private loadedWhat: Partial<{[k in 'dialogs' | 'archived' | 'contacts' | 'channelParticipants' | 'custom']: boolean}> = {};\n\n  private renderedPeerIds: Set<PeerId> = new Set();\n\n  private appendTo: HTMLElement;\n  private onChange: (length: number, changes: {key: PeerId | string, add: boolean}[]) => void;\n  public onSearchChange: (query: string) => void;\n  private peerType: SelectSearchPeerType[] = ['dialogs'];\n  public renderResultsFunc: (peerIds: PeerId[], append?: boolean) => void | Promise<void>;\n  private additionalDialogParams: (key: PeerId) => Partial<Parameters<AppDialogsManager['addDialogNew']>[0]>;\n  private chatRightsActions: ChatRights[];\n  public multiSelect: 'enabled' | 'hidden' | 'disabled' = 'enabled';\n  private multiSelectWasHidden: boolean;\n  private headerSearch: boolean;\n  private noSearch: boolean;\n  private rippleEnabled = true;\n  private avatarSize: DialogElementSize = 'abitbigger';\n  private exceptSelf: boolean;\n  private filterPeerTypeBy: IsPeerType[] | FilterPeerTypeByFunc;\n  private channelParticipantsFilter: ChannelParticipantsFilter | ((q: string) => ChannelParticipantsFilter);\n  private channelParticipantsUpdateFilter: (participant: ChannelParticipant | ChatParticipant) => boolean;\n  private channelParticipantsUpdatePeerId: PeerId;\n  private meAsSaved: boolean;\n  private onSelect: (peerId: PeerId, adding: boolean, e: MouseEvent) => MaybePromise<void | boolean>;\n\n  private tempIds: {[k in keyof AppSelectPeers['loadedWhat']]: number} = {};\n  private peerId: PeerId;\n\n  private placeholder: LangPackKey;\n\n  private selfPresence: LangPackKey = 'Presence.YourChat';\n\n  private needSwitchList = false;\n\n  private sectionNameLangPackKey: ConstructorParameters<typeof SettingSection>[0]['name'];\n  private sectionCaption: ConstructorParameters<typeof SettingSection>[0]['caption'];\n\n  private getSubtitleForElement: (\n    peerId: PeerId\n  ) => HTMLElement | DocumentFragment | undefined | Promise<HTMLElement | DocumentFragment | undefined>;\n  private processElementAfter: (peerId: PeerId, dialogElement: DialogElement) => void | Promise<void>;\n\n  private managers: AppManagers;\n\n  private middleware: Middleware;\n  public middlewareHelper: MiddlewareHelper;\n  public middlewareHelperLoader: MiddlewareHelper;\n\n  private emptySearchPlaceholderMiddlewareHelper: MiddlewareHelper;\n  private emptySearchPlaceholderQuerySetter: Setter<string>;\n  private emptySearchPlaceholderHideSetter: Setter<boolean>;\n\n  private dialogsPlaceholder: DialogsPlaceholder;\n\n  private design: 'round' | 'square' = 'round';\n  public section: SettingSection;\n\n  public participants: Map<PeerId, ChatParticipant | ChannelParticipant> = new Map();\n  public starsAmountByPeer: Map<PeerId, number> = new Map();\n  public onStarsAmountUpdate: () => void;\n  private listenerSetter: ListenerSetter;\n  public getMoreCustom: (q: string, middleware: () => boolean) => Promise<{result: PeerId[], isEnd: boolean}>;\n\n  private withStories: boolean;\n\n  private night: boolean;\n  public searchSection: SettingSection;\n\n  private checkboxSide: 'right' | 'left';\n  private noPlaceholder: boolean;\n\n  private limit: number;\n  private limitCallback: () => void;\n\n  private excludePeerIds: Set<PeerId>;\n  public getPeerIdFromKey: (key: string | PeerId) => PeerId;\n  public heightContainer: HTMLElement;\n\n  public children: Array<HTMLElement>;\n\n  private loadedFirst: boolean;\n  private onFirstRender: () => void;\n  private prependPeerIds: PeerId[];\n  private prependedPeerIds = false;\n\n  constructor(options: {\n    appendTo: AppSelectPeers['appendTo'],\n    managers: AppSelectPeers['managers'],\n    middleware: Middleware,\n    onChange?: AppSelectPeers['onChange'],\n    peerType?: AppSelectPeers['peerType'],\n    peerId?: AppSelectPeers['peerId'],\n    onFirstRender?: AppSelectPeers['onFirstRender'],\n    renderResultsFunc?: AppSelectPeers['renderResultsFunc'],\n    chatRightsActions?: AppSelectPeers['chatRightsActions'],\n    multiSelect?: AppSelectPeers['multiSelect'] | boolean,\n    headerSearch?: AppSelectPeers['headerSearch'],\n    channelParticipantsFilter?: AppSelectPeers['channelParticipantsFilter'],\n    channelParticipantsUpdateFilter?: AppSelectPeers['channelParticipantsUpdateFilter'],\n    channelParticipantsUpdatePeerId?: AppSelectPeers['channelParticipantsUpdatePeerId'],\n    noSearch?: AppSelectPeers['noSearch'],\n    rippleEnabled?: AppSelectPeers['rippleEnabled'],\n    avatarSize?: AppSelectPeers['avatarSize'],\n    placeholder?: AppSelectPeers['placeholder'],\n    selfPresence?: AppSelectPeers['selfPresence'],\n    exceptSelf?: AppSelectPeers['exceptSelf'],\n    filterPeerTypeBy?: AppSelectPeers['filterPeerTypeBy'],\n    sectionNameLangPackKey?: AppSelectPeers['sectionNameLangPackKey'],\n    sectionCaption?: AppSelectPeers['sectionCaption'],\n    design?: AppSelectPeers['design'],\n    getSubtitleForElement?: AppSelectPeers['getSubtitleForElement'],\n    processElementAfter?: AppSelectPeers['processElementAfter'],\n    meAsSaved?: AppSelectPeers['meAsSaved'],\n    onSelect?: AppSelectPeers['onSelect'],\n    scrollable?: AppSelectPeers['scrollable'],\n    getMoreCustom?: AppSelectPeers['getMoreCustom'],\n    placeholderElementsGap?: number,\n    withStories?: AppSelectPeers['withStories'],\n    night?: boolean,\n    checkboxSide?: 'right' | 'left',\n    noPlaceholder?: boolean,\n    excludePeerIds?: AppSelectPeers['excludePeerIds'],\n    excludeMonoforums?: boolean,\n    excludeBotforums?: boolean,\n    placeholderSizes?: ConstructorParameters<typeof DialogsPlaceholder>[0],\n    getPeerIdFromKey?: AppSelectPeers['getPeerIdFromKey'],\n    additionalDialogParams?: AppSelectPeers['additionalDialogParams'],\n    prependPeerIds?: AppSelectPeers['prependPeerIds'],\n    noInstantLoad?: boolean\n  }) {\n    safeAssign(this, options);\n\n    if(typeof(options.multiSelect) === 'boolean') {\n      this.multiSelect = options.multiSelect ? 'enabled' : 'disabled';\n    }\n\n    this.listenerSetter ??= new ListenerSetter();\n    this.checkboxSide ??= 'right';\n    this.exceptSelf ??= false;\n    this.meAsSaved ??= !(this.peerType.length === 1 && this.peerType[0] === 'channelParticipants');\n    this.headerSearch = /* this.multiSelect !== 'disabled' &&  */!this.noSearch;\n    // this.noSearch ??= !this.multiSelect;\n    this.excludePeerIds ??= new Set();\n    if(this.exceptSelf) this.excludePeerIds.add(rootScope.myId);\n    this.children = [];\n\n    this.middlewareHelper = options.middleware.create();\n    this.middlewareHelperLoader = this.middlewareHelper.get().create();\n    if(!this.noPlaceholder) this.dialogsPlaceholder = new DialogsPlaceholder(options.placeholderSizes || {\n      avatarSize: 42,\n      avatarMarginRight: 18,\n      marginVertical: 7,\n      marginLeft: 12 + (this.design === 'square' ? 48 : 0),\n      totalHeight: 56,\n      gapVertical: options.placeholderElementsGap,\n      statusWidth: 0,\n      night: this.night\n    });\n\n    this.container.classList.add(\n      'selector',\n      'selector-' + this.design,\n      'selector-' + this.checkboxSide\n    );\n\n    this.setMultiSelectMode(this.multiSelect);\n    this.multiSelectWasHidden = this.multiSelect === 'hidden';\n\n    const f = (this.renderResultsFunc || this.renderResults).bind(this);\n    this.renderResultsFunc = async(peerIds, append?: boolean) => {\n      const middleware = this.middlewareHelperLoader.get();\n      if(this.needSwitchList) {\n        this.needSwitchList = false;\n      }\n\n      peerIds = peerIds.filter((peerId) => {\n        if(this.excludePeerIds.has(peerId)) {\n          return false;\n        }\n\n        if(options.excludeMonoforums) {\n          const chat = apiManagerProxy.getChat(peerId.toChatId());\n          if(chat?._ === 'channel' && chat?.pFlags?.monoforum) return false;\n        }\n\n        if(options.excludeBotforums && apiManagerProxy.isBotforum(peerId)) return false;\n\n        const notRendered = !this.renderedPeerIds.has(peerId);\n        if(notRendered) this.renderedPeerIds.add(peerId);\n        return notRendered;\n      });\n\n      if(this.filterPeerTypeBy) {\n        const isFunction = typeof(this.filterPeerTypeBy) === 'function';\n        peerIds = await filterAsync(peerIds, async(peerId) => {\n          if(peerId.isPeerId()) {\n            if(isFunction) {\n              const peer = await this.managers.appPeersManager.getPeer(peerId);\n              return (this.filterPeerTypeBy as FilterPeerTypeByFunc)(peer);\n            } else {\n              for(const method of this.filterPeerTypeBy as IsPeerType[]) {\n                if(await this.managers.appPeersManager[method](peerId)) {\n                  return true;\n                }\n              }\n            }\n\n            return false;\n          }\n\n          return true;\n        });\n\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      await f(peerIds, append);\n      if(!middleware()) {\n        return;\n      }\n\n      // Mount the new list only when we're not waiting on a search promise.\n      // The search promise's then() handles the in-flight case. This branch\n      // covers callers that invoke renderResultsFunc directly (e.g. realtime\n      // chat_participant updates) outside of any pending search.\n      if(this.oldList && !this.promise) {\n        this.oldList.replaceWith(this.list);\n        this.oldList = undefined;\n      }\n\n      if(!this.promise) {\n        this.processPlaceholderOnResults();\n      }\n\n      if(this.chatRightsActions?.some((action) => action.startsWith('send_'))) {\n        Promise.all(peerIds.map(async(peerId) => {\n          const userId = peerId.toUserId();\n\n          const {requirement, starsAmount, canManageDirectMessages} = await namedPromises({\n            requirement: this.managers.appUsersManager.getRequirementToContact(userId),\n            starsAmount: this.managers.appPeersManager.getStarsAmount(peerId),\n            canManageDirectMessages: peerId.isAnyChat() && this.managers.appChatsManager.canManageDirectMessages(peerId.toChatId())\n          });\n\n          return {peerId, userId, requirement, requiredStars: starsAmount, canManageDirectMessages};\n        })).then((result) => {\n          for(const {peerId, requirement, requiredStars, canManageDirectMessages} of result) {\n            this.starsAmountByPeer.set(peerId.toPeerId(false), +requiredStars || 0);\n\n            const element = this.getElementByKey(peerId.toPeerId(false));\n            if(!element) {\n              continue;\n            }\n\n            if(requirement?._ === 'requirementToContactPremium') {\n              const lock = Icon('premium_lock', 'selector-premium-lock');\n              element.append(lock);\n              element.classList.add('is-premium-locked');\n            } else if(+requiredStars && !canManageDirectMessages) {\n              const starsAmount = formatNumber(+requiredStars, 1);\n\n              const starsBadge = document.createElement('span');\n              starsBadge.classList.add('stars-badge-base', 'dialog-stars-badge');\n\n              const starsBadgeStars = document.createElement('span');\n              starsBadgeStars.append(starsAmount + '');\n\n              starsBadge.append(\n                Icon('star', 'stars-badge-base__icon'),\n                starsBadgeStars\n              );\n\n              element.append(starsBadge);\n            }\n          }\n\n          this.onStarsAmountUpdate?.();\n        });\n      }\n    };\n\n    this.heightContainer = document.createElement('div');\n    this.heightContainer.classList.add('selector-height-container');\n    const section = this.section = new SettingSection({\n      name: this.sectionNameLangPackKey,\n      caption: this.sectionCaption\n    });\n\n    section.container.classList.add('is-visible');\n\n    if(this.sectionNameLangPackKey) {\n      section.content = section.generateContentElement();\n    }\n\n    // it can't have full height then\n    if(!this.sectionCaption) {\n      section.content.classList.add('selector-list-section-content');\n      section.container.classList.add('selector-list-section-container');\n    }\n\n    section.content.append(this.list);\n    this.heightContainer.append(section.container);\n\n    const hadScrollable = !!this.scrollable;\n    this.scrollable ||= new Scrollable();\n    this.scrollable.container.classList.add('selector-scrollable');\n\n    this.container.append(this.scrollable.container);\n\n    this.children.push(this.heightContainer);\n\n    if(!this.noSearch) {\n      this.selectorSearch = new SelectorSearch({\n        middlewareHelper: this.middlewareHelper,\n        multiSelect: this.multiSelect !== 'disabled',\n        onInput: () => this.onInput(),\n        onChipClick: (key) => {\n          if(this.freezed) return;\n          const li = this.getElementByKey(key) as HTMLElement;\n          if(!li) {\n            this.remove(key);\n          } else {\n            simulateClickEvent(li);\n          }\n        }\n      });\n      this.searchSection = this.selectorSearch.section;\n      this.inputSearch = this.selectorSearch.inputSearch;\n      this.input = this.selectorSearch.input;\n      this.children.unshift(this.selectorSearch.gradient, this.selectorSearch.section.container);\n    } else {\n      this.scrollable.attachBorderListeners();\n    }\n\n    attachClickEvent(this.container, async(e) => {\n      const target = findUpAttribute(e.target, 'data-peer-id') as HTMLElement;\n\n      if(\n        !target ||\n        (!target.classList.contains('row') && !target.classList.contains('btn-primary')) // * exception for 'includedChats' buttons\n      ) return;\n      cancelEvent(e);\n      if(this.freezed) return;\n\n      let key: PeerId | string = target.dataset.peerId;\n      key = key.isPeerId() ? key.toPeerId() : key;\n\n      if(key.isPeerId() && target.classList.contains('is-premium-locked')) {\n        wrapPeerTitle({peerId: key, onlyFirstName: true}).then((title) => {\n          toastNew({\n            langPackKey: 'OnlyPremiumCanMessage',\n            langPackArguments: [\n              title,\n              anchorCallback(() => {\n                hideToast();\n                PopupPremium.show();\n              })\n            ]\n          });\n        });\n        return;\n      }\n\n      const adding = !this.selected.has(key);\n      if(this.onSelect) {\n        const result = await this.onSelect(key, adding, e);\n        if(result === false) {\n          return;\n        }\n      }\n\n      const result = adding ? this.add({key}) : this.remove(key);\n      if(!result) {\n        return;\n      }\n\n      this.toggleElementCheckboxByKey(key, adding);\n    });\n\n    if(this.multiSelect === 'hidden') {\n      let target: HTMLElement;\n      let key: PeerId | string;\n      const contextMenuButtons: ButtonMenuItemOptionsVerifiable[] = [{\n        icon: 'select',\n        text: 'SelectChat',\n        onClick: () => {\n          this.setMultiSelectMode('enabled');\n          simulateClickEvent(target);\n        },\n        verify: () => !this.selected.has(key)\n      }, {\n        icon: 'close',\n        text: 'Deselect',\n        onClick: () => {\n          simulateClickEvent(target);\n        },\n        verify: () => this.selected.has(key)\n      }];\n\n      createContextMenu({\n        listenTo: this.container,\n        buttons: contextMenuButtons,\n        findElement: (e) => findUpAttribute(e.target, 'data-peer-id') as HTMLElement,\n        onOpen: (_e, _target) => {\n          target = _target;\n          key = target.dataset.peerId;\n          key = key.isPeerId() ? key.toPeerId() : key;\n        },\n        listenerSetter: this.listenerSetter,\n        middleware: this.middlewareHelper.get()\n      });\n    }\n\n    this.scrollable.onScrolledBottom = () => {\n      this.getMoreResults();\n    };\n\n    this.appendTo.append(this.container);\n\n    const onChatParticipant = (\n      participant: ChannelParticipant | ChatParticipant,\n      peerId: PeerId,\n      needAdd = this.channelParticipantsUpdateFilter(participant)\n    ) => {\n      if(needAdd) {\n        this.participants.set(peerId, participant);\n      } else {\n        this.participants.delete(peerId);\n      }\n\n      if(needAdd) {\n        this.renderResultsFunc([peerId], false);\n      } else {\n        this.deletePeerId(peerId);\n      }\n    };\n\n    if(this.channelParticipantsUpdateFilter) this.listenerSetter.add(rootScope)('chat_participant', (update) => {\n      if(update.channel_id.toPeerId(true) !== (this.channelParticipantsUpdatePeerId ?? this.peerId)) {\n        return;\n      }\n\n      onChatParticipant(update.new_participant, update.user_id.toPeerId(false));\n    });\n\n    if(\n      this.channelParticipantsUpdateFilter &&\n      apiManagerProxy.getPeer(this.peerId)?._ === 'chat'\n    ) {\n      this.listenerSetter.add(rootScope)('chat_full_update', async(chatId) => {\n        if(chatId.toPeerId(true) !== this.peerId) {\n          return;\n        }\n\n        const middleware = this.middlewareHelperLoader.get();\n        const chatFull = await this.managers.appProfileManager.getChatFull(this.peerId.toChatId()) as ChatFull.chatFull;\n        if(!middleware()) {\n          return;\n        }\n\n        const participants = chatFull.participants as ChatParticipants.chatParticipants;\n        const processedPeerIds = new Set<PeerId>();\n        for(const participant of participants.participants) {\n          const peerId = participant.user_id.toPeerId(false);\n          processedPeerIds.add(peerId);\n          onChatParticipant(\n            participant,\n            peerId,\n            undefined\n          );\n        }\n\n        this.participants.forEach((participant, peerId) => {\n          if(!processedPeerIds.has(peerId)) {\n            onChatParticipant(participant, peerId, false);\n          }\n        });\n      });\n    }\n\n    options.middleware.onDestroy(() => {\n      this.destroy();\n    });\n\n    if(!options.noInstantLoad) {\n      this.loadFirst();\n    }\n\n    if(!hadScrollable) {\n      (this.scrollable as Scrollable).append(...this.children);\n    }\n  }\n\n  public loadFirst() {\n    if(this.loadedFirst) {\n      return;\n    }\n\n    this.loadedFirst = true;\n    // WARNING TIMEOUT\n    setTimeout(() => {\n      const getResultsPromise = this.getMoreResults() as Promise<any>;\n      if(this.onFirstRender) {\n        getResultsPromise.then(() => {\n          this.onFirstRender();\n        });\n      }\n    }, 0);\n  }\n\n  public static convertPeerTypes(types: TelegramChoosePeerType[]) {\n    const isPeerTypeMap: {\n      [type in typeof types[0]]: IsPeerType\n    } = {\n      bots: 'isBot',\n      users: 'isRegularUser',\n      groups: 'isAnyGroup',\n      channels: 'isBroadcast'\n    };\n\n    const filterPeerTypeBy: IsPeerType[] = types.map((type) => isPeerTypeMap[type]);\n    return filterPeerTypeBy;\n  }\n\n  public setLimit(limit: number, callback: AppSelectPeers['limitCallback']) {\n    this.limit = limit;\n    this.limitCallback = callback;\n  }\n\n  public destroy() {\n    this.middlewareHelper.destroy();\n    this.emptySearchPlaceholderMiddlewareHelper?.destroy();\n    this.listenerSetter.removeAll();\n    this.dialogsPlaceholder?.removeWithoutUnmounting();\n    this.selectorSearch?.destroy();\n    this.inputSearch?.remove();\n  }\n\n  public deletePeerId(peerId: PeerId) {\n    const el = this.list.querySelector(`[data-peer-id=\"${peerId}\"]`);\n    const dialogElement = (el as any)?.dialogElement;\n    if(dialogElement) {\n      dialogElement.remove();\n    } else {\n      el?.remove();\n    }\n\n    this.renderedPeerIds.delete(peerId);\n\n    if(!this.promise) {\n      this.processPlaceholderOnResults();\n    }\n  }\n\n  private _setFolderId(value: string) {\n    this.folderId = (value ? FOLDER_ID_ALL : this.selectedFolderId) ?? FOLDER_ID_ALL;\n  }\n\n  private onInput = () => {\n    const value = this.inputSearch.value;\n    if(this.query === value) {\n      return;\n    }\n\n    if(this.peerType.includes('contacts') || this.peerType.includes('dialogs')) {\n      this.cachedContacts = undefined;\n    }\n\n    if(this.peerType.includes('dialogs')) {\n      this._setFolderId(value);\n      this.offsetIndex = 0;\n    }\n\n    for(const i in this.tempIds) {\n      // @ts-ignore\n      ++this.tempIds[i];\n    }\n\n    // Keep the currently mounted list reference until the new search resolves.\n    // ??= so that rapid re-typing doesn't overwrite the in-DOM list with a\n    // detached one from a still-pending previous search.\n    this.oldList ??= this.list;\n    this.list = appDialogsManager.createChatList();\n\n    this.promise = undefined;\n    this.query = value;\n    this.onSearchChange?.(value);\n    this.renderedPeerIds.clear();\n    this.prependedPeerIds = false;\n    this.needSwitchList = true;\n    this.middlewareHelperLoader.clean();\n\n    this.loadedWhat = {};\n    if(this.peerType.includes('dialogs')) {\n      this.loadedWhat.dialogs = false;\n      this.loadedWhat.archived = false;\n      this.loadedWhat.contacts = false;\n    }\n\n    if(this.peerType.includes('contacts')) {\n      this.loadedWhat.contacts = false;\n    }\n\n    if(this.peerType.includes('channelParticipants')) {\n      this.loadedWhat.channelParticipants = false;\n    }\n\n    if(this.peerType.includes('custom')) {\n      this.loadedWhat.custom = false;\n    }\n\n    // Only force the section open (hiding the empty placeholder) when there's\n    // actually previous content to show during the new search. If the previous\n    // search was empty, leave the placeholder visible — its query text is\n    // updated by processPlaceholderOnResults once the new search resolves.\n    if(this.oldList?.childElementCount) {\n      this.emptySearchPlaceholderHideSetter?.(true);\n    }\n\n    this.getMoreResults();\n  };\n\n  public clearInput() {\n    this.inputSearch.value = '';\n    this.onInput();\n  }\n\n  private async renderSaved() {\n    if(\n      !this.exceptSelf &&\n      !this.offsetIndex &&\n      this.folderId === FOLDER_ID_ALL &&\n      this.peerType.includes('dialogs') &&\n      (!this.query || await this.managers.appUsersManager.testSelfSearch(this.query))\n    ) {\n      await this.renderResultsFunc([rootScope.myId]);\n    }\n  }\n\n  private getTempId(type: keyof AppSelectPeers['tempIds']) {\n    this.tempIds[type] ??= 0;\n    const tempId = ++this.tempIds[type];\n    return {\n      tempId,\n      middleware: () => this.tempIds[type] === tempId\n    };\n  }\n\n  private async getMoreDialogs(): Promise<any> {\n    if(this.loadedWhat.dialogs && this.loadedWhat.archived) {\n      return;\n    }\n\n    // в десктопе - сначала без группы, потом архивные, потом контакты без сообщений\n    const pageCount = windowSize.height / 56 * 1.25 | 0;\n\n    const {middleware} = this.getTempId('dialogs');\n    const promise = this.managers.dialogsStorage.getDialogs({\n      query: this.query,\n      offsetIndex: this.offsetIndex,\n      limit: pageCount,\n      filterId: this.folderId,\n      skipMigrated: true\n    });\n\n    promise.catch(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      this.loadedWhat[this.loadedWhat.dialogs ? 'archived' : 'dialogs'] = true;\n    });\n\n    const value = await promise;\n    if(!middleware()) {\n      return;\n    }\n\n    let dialogs = value.dialogs as Dialog[];\n    if(dialogs.length) {\n      const newOffsetIndex = getDialogIndex(dialogs[dialogs.length - 1]) || 0;\n\n      dialogs = dialogs.slice();\n\n      if(this.chatRightsActions) {\n        dialogs = await filterAsync(dialogs, (d) => this.filterByRights(d.peerId));\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      await this.renderSaved();\n      if(!middleware()) {\n        return;\n      }\n\n      this.offsetIndex = newOffsetIndex;\n    }\n\n    await this.renderResultsFunc(dialogs.map((dialog) => dialog.peerId));\n\n    if(value.isEnd) {\n      if(!this.loadedWhat.dialogs) {\n        await this.renderSaved();\n        if(!middleware()) {\n          return;\n        }\n\n        this.loadedWhat.dialogs = true;\n\n        if(this.selectedFolderId !== undefined) {\n          this.loadedWhat.archived = true;\n        } else {\n          this.offsetIndex = 0;\n          this.folderId = 1;\n          return this.getMoreDialogs();\n        }\n      } else {\n        this.loadedWhat.archived = true;\n      }\n\n      if(this.canLoadContacts()) {\n        return this.getMoreContacts();\n      }\n    } else if(this.renderedPeerIds.size < pageCount) {\n      return this.getMoreDialogs();\n    }\n  }\n\n  private async filterByRights(peerId: PeerId) {\n    const peer = apiManagerProxy.getPeer(peerId);\n    if(peerId.isUser()) {\n      return this.chatRightsActions[0] !== 'send_plain' || canSendToUser(peer as User.user);\n    } else if(this.chatRightsActions.every((action) => hasRights(peer as Chat.chat, action))) {\n      return true;\n    }\n  }\n\n  private canLoadContacts() {\n    return !(this.loadedWhat.contacts || !REAL_FOLDERS.has(this.folderId));\n  }\n\n  private async getMoreContacts() {\n    if(!this.canLoadContacts()) {\n      return;\n    }\n\n    const isGlobalSearch = this.peerType.includes('contacts');\n\n    if(!this.cachedContacts) {\n      /* const promises: Promise<any>[] = [appUsersManager.getContacts(this.query)];\n      if(!this.peerType.includes('dialogs')) {\n        promises.push(appMessagesManager.getConversationsAll());\n      }\n\n      this.promise = Promise.all(promises);\n      this.cachedContacts = (await this.promise)[0].slice(); */\n      const {middleware} = this.getTempId('contacts');\n      const promise = Promise.all([\n        isGlobalSearch ? this.managers.appUsersManager.getContactsPeerIds(this.query) : [],\n        this.query ? this.managers.appUsersManager.searchContacts(this.query) : undefined\n      ]);\n\n      promise.catch(() => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.loadedWhat.contacts = true;\n      });\n\n      const [cachedContacts, searchResult] = await promise;\n      if(!middleware()) {\n        return;\n      }\n\n      if(searchResult) {\n        // do not add global result if only dialogs needed\n        let resultPeerIds = isGlobalSearch ? searchResult.my_results.concat(searchResult.results) : searchResult.my_results;\n\n        if(this.chatRightsActions) {\n          resultPeerIds = await filterAsync(resultPeerIds, (peerId) => this.filterByRights(peerId));\n          if(!middleware()) {\n            return;\n          }\n        }\n\n        if(!this.peerType.includes('dialogs')) {\n          resultPeerIds = resultPeerIds.filter((peerId) => peerId.isUser());\n        }\n\n        this.cachedContacts = filterUnique(cachedContacts.concat(resultPeerIds));\n      } else this.cachedContacts = cachedContacts.slice();\n    }\n\n    // if(this.cachedContacts.length) {\n    const pageCount = windowSize.height / 56 * 1.25 | 0;\n    const arr = this.cachedContacts.splice(0, pageCount);\n    await this.renderResultsFunc(arr);\n    // }\n\n    if(!this.cachedContacts.length) {\n      this.loadedWhat.contacts = true;\n\n      // need to load non-contacts\n      /* if(!this.peerType.includes('dialogs')) {\n        return this.getMoreDialogs();\n      } */\n    }\n  }\n\n  private async getMoreChannelParticipants() {\n    if(this.loadedWhat.channelParticipants) {\n      return;\n    }\n\n    const pageCount = 50; // same as in group permissions to use cache\n\n    let filter: ChannelParticipantsFilter;\n    if(this.channelParticipantsFilter) {\n      filter = typeof(this.channelParticipantsFilter) === 'function' ?\n        this.channelParticipantsFilter(this.query) :\n        this.channelParticipantsFilter;\n    } else {\n      filter = {\n        _: 'channelParticipantsSearch',\n        q: this.query\n      };\n    }\n\n    const {middleware} = this.getTempId('channelParticipants');\n    const promise = this.managers.appProfileManager.getParticipants({\n      id: this.peerId.toChatId(),\n      filter,\n      limit: pageCount,\n      offset: this.list.childElementCount\n    });\n\n    promise.catch(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      this.loadedWhat.channelParticipants = true;\n    });\n\n    const chatParticipants = await promise;\n    if(!middleware()) {\n      return;\n    }\n\n    const {participants} = chatParticipants;\n\n    const peerIds = participants.map((participant) => {\n      const peerId = getParticipantPeerId(participant);\n      this.participants.set(peerId, participant);\n      return peerId;\n    });\n    await this.renderResultsFunc(peerIds);\n\n    const count = (chatParticipants as ChannelsChannelParticipants.channelsChannelParticipants).count ?? participants.length;\n\n    if(this.list.childElementCount >= count || participants.length < pageCount) {\n      this.loadedWhat.channelParticipants = true;\n    }\n  }\n\n  private async _getMoreCustom() {\n    if(this.loadedWhat.custom) {\n      return;\n    }\n\n    const {middleware} = this.getTempId('custom');\n    const promise = this.getMoreCustom(this.query, middleware);\n\n    promise.catch(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      this.loadedWhat.custom = true;\n    });\n\n    const res = await promise;\n    if(!middleware()) {\n      return;\n    }\n\n    const {result, isEnd} = res;\n\n    await this.renderResultsFunc(result);\n\n    if(isEnd) {\n      this.loadedWhat.custom = true;\n    }\n  }\n\n  checkForTriggers = () => {\n    this.scrollable.checkForTriggers();\n  };\n\n  private _getMoreResults(): Promise<any> | undefined {\n    if(!this.query && !this.prependedPeerIds && this.prependPeerIds?.length) {\n      this.prependedPeerIds = true;\n      return Promise.resolve(this.renderResultsFunc(this.prependPeerIds))\n      .then((): Promise<any> | undefined => this._getMoreResults());\n    }\n\n    if((this.peerType.includes('dialogs')/*  || this.loadedWhat.contacts */) && !this.loadedWhat.archived) { // to load non-contacts\n      return this.getMoreSomething('dialogs');\n    }\n\n    if((this.peerType.includes('contacts') || this.peerType.includes('dialogs')) && !this.loadedWhat.contacts && this.canLoadContacts()) {\n      return this.getMoreSomething('contacts');\n    }\n\n    if(this.peerType.includes('channelParticipants') && !this.loadedWhat.channelParticipants) {\n      return this.getMoreSomething('channelParticipants');\n    }\n\n    if(this.peerType.includes('custom') && !this.loadedWhat.custom) {\n      return this.getMoreSomething('custom');\n    }\n  }\n\n  private processPlaceholderOnResults = () => {\n    const length = this.list.childElementCount;\n    if(!length) {\n      if(!this.emptySearchPlaceholderMiddlewareHelper) {\n        this.emptySearchPlaceholderMiddlewareHelper = getMiddleware();\n        const middleware = this.emptySearchPlaceholderMiddlewareHelper.get();\n\n        createRoot((dispose) => {\n          const [query, setQuery] = createSignal(this.query);\n          const [description, setDescription] = createSignal<JSX.Element>();\n          const [hide, setHide] = createSignal(false);\n          this.emptySearchPlaceholderQuerySetter = setQuery;\n          this.emptySearchPlaceholderHideSetter = setHide;\n          middleware.onClean(dispose);\n          createEffect(() => {\n            const query$ = query();\n            setDescription(\n              query$.trim() ?\n                i18n('RequestJoin.List.SearchEmpty', [wrapEmojiText(query$)]) :\n                i18n('Search.EmptyQuery')\n            );\n          });\n\n          createEffect(() => {\n            this.section.container.classList.toggle('is-visible', hide());\n          });\n\n          emptyPlaceholder({\n            middleware,\n            title: () => i18n('SearchEmptyViewTitle'),\n            description,\n            hide\n          }).then((container) => {\n            if(!middleware()) {\n              return;\n            }\n\n            this.heightContainer.append(container);\n          });\n        });\n        return;\n      } else {\n        this.dialogsPlaceholder?.detach(length);\n        this.emptySearchPlaceholderHideSetter(false);\n        this.emptySearchPlaceholderQuerySetter(this.query);\n      }\n    } else {\n      this.dialogsPlaceholder?.detach(length);\n      this.emptySearchPlaceholderHideSetter?.(true);\n      this.emptySearchPlaceholderQuerySetter?.(this.query);\n    }\n  };\n\n  private getMoreResults() {\n    if(this.promise) {\n      return this.promise;\n    }\n\n    const loadPromise = this._getMoreResults();\n    if(!loadPromise) {\n      this.processPlaceholderOnResults();\n      return Promise.resolve();\n    }\n\n    const middleware = this.middlewareHelperLoader.get();\n    const promise = this.promise = loadPromise.catch((err) => {\n      console.error('get more result error', err);\n    }).then(() => {\n      if(this.promise === promise) {\n        this.promise = undefined;\n      }\n\n      if(middleware()) {\n        // Search is done — swap the previous list out for the freshly built one.\n        if(this.oldList) {\n          this.oldList.replaceWith(this.list);\n          this.oldList = undefined;\n        }\n\n        const loadedWhatValues = Object.values(this.loadedWhat);\n        const loadedAll = loadedWhatValues.every((v) => v);\n\n        const length = this.list.childElementCount;\n        if(loadedAll && !length) {\n          this.dialogsPlaceholder?.detach(length);\n          return this.processPlaceholderOnResults();\n        } else if(length || loadedAll) {\n          this.dialogsPlaceholder?.detach(length);\n          this.emptySearchPlaceholderHideSetter?.(true);\n        }\n      }\n\n      this.checkForTriggers(); // set new promise\n      return this.promise;\n    });\n\n    return promise;\n  }\n\n  private getMoreSomething(peerType: SelectSearchPeerType) {\n    const map: {[type in SelectSearchPeerType]: () => Promise<any>} = {\n      dialogs: this.getMoreDialogs,\n      contacts: this.getMoreContacts,\n      channelParticipants: this.getMoreChannelParticipants,\n      custom: this._getMoreCustom\n    };\n\n    const promise = map[peerType].call(this);\n    return promise;\n  }\n\n  private async renderResults(peerIds: PeerId[], append?: boolean) {\n    // console.log('will renderResults:', peerIds);\n\n    // оставим только неконтакты с диалогов\n    if(!this.peerType.includes('dialogs') && this.loadedWhat.contacts) {\n      peerIds = await filterAsync(peerIds, (peerId) => {\n        return this.managers.appUsersManager.isNonContactUser(peerId);\n      });\n    }\n\n    const promises = peerIds.map(async(key) => {\n      const dialogElement = appDialogsManager.addDialogNew({\n        peerId: this.getPeerIdFromKey?.(key) ?? key,\n        container: this.list,\n        rippleEnabled: this.rippleEnabled,\n        avatarSize: this.avatarSize,\n        meAsSaved: this.meAsSaved,\n        append,\n        wrapOptions: {\n          middleware: this.middlewareHelperLoader.get()\n        },\n        withStories: this.withStories,\n        ...(this.additionalDialogParams?.(key) || {})\n      });\n\n      if(this.getPeerIdFromKey) {\n        dialogElement.container.dataset.peerId = key as any as string;\n      }\n\n      (dialogElement.container as any).dialogElement = dialogElement;\n\n      const {dom} = dialogElement;\n\n      if(this.multiSelect !== 'disabled') {\n        const selected = this.selected.has(key);\n        const checkbox = this.checkbox(selected);\n        if(this.checkboxSide === 'right') {\n          dom.containerEl.append(checkbox);\n        } else {\n          dom.containerEl.prepend(checkbox);\n        }\n      }\n\n      let subtitleEl: HTMLElement | DocumentFragment;\n      if(this.getSubtitleForElement) {\n        subtitleEl = await this.getSubtitleForElement(key);\n      }\n\n      if(!subtitleEl) {\n        subtitleEl = await this.wrapSubtitle(key);\n      }\n\n      dom.lastMessageSpan.append(subtitleEl);\n\n      if(this.processElementAfter) {\n        await this.processElementAfter(key, dialogElement);\n      }\n    });\n\n    return Promise.all(promises);\n  }\n\n  public async wrapSubtitle(peerId: PeerId) {\n    let subtitleEl: HTMLElement;\n    if(peerId.isAnyChat()) {\n      subtitleEl = await getChatMembersString(peerId.toChatId());\n    } else if(peerId === rootScope.myId) {\n      subtitleEl = i18n(this.selfPresence);\n    } else {\n      subtitleEl = getUserStatusString(await this.managers.appUsersManager.getUser(peerId.toUserId()));\n    }\n\n    return subtitleEl;\n  }\n\n  public checkbox(\n    selected?: boolean,\n    color: ConstructorParameters<typeof CheckboxField>[0]['color'] = 'secondary'\n  ) {\n    const checkboxField = new CheckboxField({\n      round: this.design === 'round',\n      color\n    });\n    if(selected) {\n      checkboxField.input.checked = selected;\n    }\n\n    return checkboxField.label;\n  }\n\n  public static renderEntity = SelectorSearch.renderEntity;\n\n  public add({\n    key,\n    title,\n    scroll = true,\n    fireOnChange = true,\n    fallbackIcon\n  }: {\n    key: PeerId | string,\n    title?: string | HTMLElement,\n    scroll?: boolean,\n    fireOnChange?: boolean,\n    fallbackIcon?: Icon\n  }): boolean | ReturnType<typeof SelectorSearch['renderEntity']> {\n    if(this.limit && this.selected.size >= this.limit) {\n      this.limitCallback?.();\n      return false;\n    }\n\n    // console.trace('add');\n    const added = !this.selected.has(key);\n    this.selected.add(key);\n    if(added) {\n      this.changes.push({key, add: true});\n    }\n\n    if(this.multiSelect !== 'enabled' || !this.input) {\n      fireOnChange && this.dispatchOnChange();\n      return this.multiSelect !== 'disabled';\n    }\n\n    if(this.query.trim()) {\n      this.clearInput();\n    }\n\n    const rendered = this.selectorSearch.addChip({\n      key,\n      middleware: this.middlewareHelper.get(),\n      title,\n      scroll,\n      fallbackIcon,\n      primary: true\n    });\n    fireOnChange && this.dispatchOnChange();\n\n    return rendered;\n  }\n\n  public remove(key: PeerId | string, fireOnChange = true): boolean {\n    if(this.multiSelect !== 'enabled') {\n      return false;\n    }\n\n    const onRemoved = () => {\n      const removed = this.selected.delete(key);\n      if(removed) {\n        this.changes.push({key, add: false});\n      }\n      fireOnChange && this.dispatchOnChange();\n    };\n\n    onRemoved();\n\n    if(this.selectorSearch) {\n      this.selectorSearch.removeChip(key);\n    }\n\n    return true;\n  }\n\n  public getSelected() {\n    return [...this.selected];\n  }\n\n  public getElementByKey(key: PeerId | string) {\n    return this.container.querySelector<HTMLElement>(`.row[data-peer-id=\"${key}\"]`);\n  }\n\n  public toggleElementCheckboxByKey(key: PeerId | string, checked?: boolean) {\n    const checkboxes = this.findCheckboxes(key);\n    const value = checked === undefined ? undefined : checked;\n    checkboxes.forEach((checkbox) => checkbox.checked = value ?? !checkbox.checked);\n  }\n\n  public addBatch(values: any[]) {\n    if(!values.length) {\n      return;\n    }\n\n    values.forEach((value) => {\n      this.add({\n        key: value,\n        scroll: false,\n        fireOnChange: false\n      });\n      this.toggleElementCheckboxByKey(value, true);\n    });\n\n    this.dispatchOnChange();\n  }\n\n  public removeBatch(values: any[], fireOnChange = true) {\n    if(!values.length) {\n      return;\n    }\n\n    values.forEach((value) => {\n      this.remove(value, false);\n      this.toggleElementCheckboxByKey(value, false);\n    });\n\n    if(fireOnChange) {\n      this.dispatchOnChange();\n    }\n  }\n\n  private dispatchOnChange() {\n    const changes = this.changes;\n    this.changes = [];\n    // * important order here\n    // * onChange should be fired with old multiselect state\n    this.onChange?.(this.selected.size, changes);\n    if(!this.selected.size && this.multiSelectWasHidden) {\n      this.setMultiSelectMode('hidden');\n    }\n  }\n\n  private findCheckboxes(key: PeerId | string): HTMLInputElement[] {\n    const query = `[data-peer-id=\"${key}\"] input`;\n    const containers: Element[] = [this.container];\n\n    // if(!this.container.closest('.selector')) {\n    //   const selectorSearch = document.querySelector('.selector-search');\n    //   if(selectorSearch) containers.push(selectorSearch);\n    // }\n\n    return containers.flatMap((c) => [...c.querySelectorAll<HTMLInputElement>(query)]);\n  }\n\n  public addInitial(values: any[]) {\n    if(!values?.length) {\n      return;\n    }\n\n    this.addBatch(values);\n\n    this.selectorSearch && window.requestAnimationFrame(() => { // ! not the best place for this raf though it works\n      this.selectorSearch.scrollToInput(FocusDirection.Static);\n    });\n  }\n\n  public setMultiSelectMode(mode: AppSelectPeers['multiSelect']) {\n    this.multiSelect = mode;\n    this.container.classList.toggle('selector-multiselect-hidden', mode === 'hidden');\n  }\n\n  public setFolderId(folderId: number) {\n    const willBeFolderId = folderId || undefined;\n    if(this.selectedFolderId === willBeFolderId) {\n      return;\n    }\n\n    this.selectedFolderId = willBeFolderId;\n    if(!this.loadedFirst) {\n      this._setFolderId('');\n      return;\n    }\n\n    this.query = '\\x01'; // force onInput to detect a change\n    this.onInput();\n  }\n}\n","import appDialogsManager from '@lib/appDialogsManager';\nimport rootScope from '@lib/rootScope';\nimport {createSearchGroup, SearchGroup} from '@components/searchGroup';\nimport {Middleware} from '@helpers/middleware';\nimport {MyTopPeer} from '@lib/appManagers/appUsersManager';\n\nexport default function createTopPeersList({\n  middleware,\n  onFound,\n  group,\n  modifyPeers,\n  className\n}: {\n  middleware: Middleware,\n  onFound?: () => void,\n  group?: SearchGroup,\n  modifyPeers?: (peers: MyTopPeer[]) => MyTopPeer[],\n  className?: string\n}) {\n  const autonomous = !group;\n  group ??= createSearchGroup({\n    type: 'contacts',\n    className: 'search-group-people' + (className ? ' ' + className : ''),\n    autonomous,\n    onFound,\n    noIcons: true,\n    middleware,\n    scrollableX: true,\n    clickable: !!onFound\n  });\n\n  const promise = rootScope.managers.appUsersManager.getTopPeers('correspondents').then((peers) => {\n    if(!middleware()) return;\n\n    if(modifyPeers) {\n      peers = modifyPeers(peers.slice());\n    }\n\n    peers.forEach((peer) => {\n      const {dom} = appDialogsManager.addDialogNew({\n        peerId: peer.id,\n        container: group.list,\n        onlyFirstName: true,\n        avatarSize: 'bigger',\n        autonomous,\n        noIcons: group.noIcons,\n        wrapOptions: {\n          middleware\n        },\n        withStories: true\n      });\n\n      dom.subtitleEl.remove();\n    });\n\n    group.toggle();\n  });\n\n  return {group, promise};\n}\n","import {Dynamic} from 'solid-js/web';\nimport {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\nexport default function Badge(props: {\n  tag: 'span' | 'div',\n  /** the pill's height; the rectangle variant sizes itself to its text instead */\n  size?: number,\n  color?: 'primary' | 'gray',\n  /** a compact tinted rectangle for badges that sit inline with a heading */\n  rectangle?: boolean,\n  children: JSX.Element,\n  class?: string\n}) {\n  return (\n    <Dynamic\n      component={props.tag}\n      class={classNames(\n        'badge',\n        props.size && `badge-${props.size}`,\n        props.color && `badge-${props.color}`,\n        props.rectangle && 'badge-rectangle',\n        !props.children && 'is-badge-empty',\n        props.class\n      )}\n    >\n      {props.children}\n    </Dynamic>\n  );\n}\n","import {Middleware} from '@helpers/middleware';\nimport {TextWithEntities} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\n\ntype Options = {\n  textColor?: string;\n};\n\nexport default function wrapFolderTitle<T extends boolean = false>(\n  text: TextWithEntities,\n  middleware: Middleware,\n  noWait?: T,\n  {textColor = 'primary-text-color'}: Options = {}\n): T extends true ? DocumentFragment : Promise<DocumentFragment> {\n  const loadPromises: Promise<any>[] = [];\n  text = wrapTextWithEntities(text);\n  const wrapped = wrapRichText(text.text, {entities: text.entities, middleware, loadPromises, textColor});\n  if(noWait) {\n    return wrapped as any;\n  }\n\n  return Promise.all(loadPromises).then(() => wrapped) as any;\n}\n","export default function documentFragmentToNodes(fragment: DocumentFragment) {\n  const nodes: (Node | string)[] = new Array(fragment.childNodes.length);\n  let node = fragment.firstChild;\n  let i = 0;\n  while(node) {\n    nodes[i++] = node.nodeType === node.TEXT_NODE ? node.nodeValue : node;\n    node = node.nextSibling;\n  }\n  return nodes;\n}\n","import {createEffect, createMemo, createRoot, createSignal, untrack} from 'solid-js';\nimport {createStore, reconcile} from 'solid-js/store';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport rootScope from '@lib/rootScope';\nimport {FOLDER_ID_ALL, FOLDER_ID_ARCHIVE, REAL_FOLDERS} from '@appManagers/constants';\nimport type {MyDialogFilter} from '@lib/storages/filters';\nimport type {AppManagers} from '@lib/managers';\n\nexport type StoredFolder = {\n  id: number,\n  notifications?: {\n    count: number,\n    muted: boolean\n  },\n  chatsCount: number | null,\n  filter: MyDialogFilter\n};\n\nasync function getNotificationCountForFilter(filterId: number, managers: AppManagers) {\n  const {\n    unreadUnmutedCount,\n    unreadCount,\n    unreadMentionsCount\n  } = await managers.dialogsStorage.getFolderUnreadCount(filterId);\n\n  return {\n    count: filterId === FOLDER_ID_ALL ? unreadUnmutedCount : unreadCount,\n    muted: !unreadUnmutedCount && !!unreadCount && !unreadMentionsCount\n  };\n}\n\nasync function getFolderItemsInOrder(folderItems: StoredFolder[], managers: AppManagers) {\n  const filters = new Map<number, MyDialogFilter>();\n\n  const filtersPromises = folderItems\n  .filter((item) => item.id)\n  .map((item) => managers.filtersStorage.getFilter(item.id));\n\n  const filtersArr = (\n    await Promise.all(filtersPromises)\n  ).filter(Boolean);\n\n  for(const filter of filtersArr) {\n    filters.set(filter.id, filter);\n  }\n\n  return folderItems.sort((a, b) => {\n    if(!a.id || !b.id) return 0;\n    return filters.get(a.id)?.localId - filters.get(b.id)?.localId;\n  });\n}\n\nconst useFoldersStore = createRoot(() => {\n  const [selectedFolderId, _setSelectedFolderId] = createSignal<number>(FOLDER_ID_ALL);\n  const [folderItems, setFolderItems] = createStore<StoredFolder[]>([]);\n  const selectedFolderIndex = createMemo(() => folderItems.findIndex(({id}) => id === selectedFolderId()));\n\n  let setSelectedFolderId: (index: number, dontAnimate?: boolean) => any;\n  const [onClick, setOnClick] = createSignal<typeof setSelectedFolderId>();\n\n  createEffect(() => {\n    setSelectedFolderId = onClick();\n  });\n\n  function updateFolderItem(folderId: number, payload: Partial<StoredFolder>) {\n    const idx = folderItems.findIndex((item) => item.id === folderId);\n    if(idx === -1) {\n      return;\n    }\n\n    const folderItem = folderItems[idx];\n    setFolderItems(idx, reconcile({...folderItem, ...payload}));\n  }\n\n  async function updateFolderNotifications(folderId: number) {\n    updateFolderItem(folderId, {\n      notifications: await getNotificationCountForFilter(folderId, rootScope.managers)\n    });\n  }\n\n  function updateAllFolderNotifications() {\n    for(const folderItem of folderItems) {\n      if(!folderItem.id) continue;\n      updateFolderNotifications(folderItem.id);\n    }\n  }\n\n  async function makeFolderItemPayload(filter: MyDialogFilter): Promise<StoredFolder> {\n    const [notifications, folder] = await Promise.all([\n      getNotificationCountForFilter(filter.id, rootScope.managers),\n      rootScope.managers.dialogsStorage.getFolder(filter.id)\n    ]);\n\n    return {\n      id: filter.id,\n      notifications: notifications,\n      chatsCount: folder?.dialogs?.length || 0,\n      filter\n    };\n  }\n\n  async function updateOrAddFolder(filter: MyDialogFilter) {\n    const items = [...folderItems];\n    const existingItem = items.find((item) => item.id === filter.id);\n\n    if(existingItem) {\n      updateFolderItem(filter.id, await makeFolderItemPayload(filter));\n      return;\n    }\n\n    const [payload, orderedFolderItems] = await Promise.all([\n      makeFolderItemPayload(filter),\n      getFolderItemsInOrder(items, rootScope.managers)\n    ]);\n\n    items.push(payload);\n    setFolderItems(orderedFolderItems);\n  }\n\n  function deleteFolder(filterId: number) {\n    const items = [...folderItems];\n    const existingItemIndex = items.findIndex((item) => item.id === filterId);\n\n    if(existingItemIndex === -1) return;\n\n    items.splice(existingItemIndex, 1);\n    const length = items.length;\n    setFolderItems(items);\n\n    const selectedId = untrack(selectedFolderId);\n    if(length >= selectedId || selectedId === filterId) {\n      setSelectedFolderId(0);\n    }\n  }\n\n  function updateItemsOrder(order: number[]) {\n    order = [...order];\n    indexOfAndSplice(order, FOLDER_ID_ARCHIVE);\n\n    const items = [...folderItems];\n\n    items.sort((a, b) => {\n      const aIndex = order.indexOf(a.id);\n      const bIndex = order.indexOf(b.id);\n\n      if(aIndex === -1) return -1;\n      if(bIndex === -1) return 1;\n\n      return aIndex - bIndex;\n    });\n\n    setFolderItems(items);\n  }\n\n  let lastHydrationId = 0;\n  let listenersInited = false;\n  async function hydrateFilters(filters: MyDialogFilter[]) {\n    const hydrationId = ++lastHydrationId;\n    const folderFilters = filters.filter((filter) => filter.id !== FOLDER_ID_ARCHIVE);\n    const items = await Promise.all(folderFilters.map(makeFolderItemPayload));\n    const orderedItems = await getFolderItemsInOrder(items, rootScope.managers);\n\n    if(hydrationId !== lastHydrationId) {\n      return;\n    }\n\n    setFolderItems(orderedItems);\n    if(!listenersInited) {\n      listenersInited = true;\n      initListeners();\n    }\n  }\n\n  function initListeners() {\n    rootScope.addEventListener('dialog_flush', ({dialog}) => {\n      if(!dialog) return;\n      updateAllFolderNotifications();\n    });\n\n    rootScope.addEventListener('folder_unread', (filter) => {\n      if(filter.id < 0) return;\n      updateFolderNotifications(filter.id);\n    });\n\n    const onFilterUpsert = (filter: MyDialogFilter) => {\n      if(REAL_FOLDERS.has(filter.id)) return;\n      return updateOrAddFolder(filter);\n    };\n\n    rootScope.addEventListener('filter_update', onFilterUpsert);\n    rootScope.addEventListener('filter_new', onFilterUpsert);\n\n    rootScope.addEventListener('filter_delete', (filter) => {\n      deleteFolder(filter.id);\n    });\n\n    rootScope.addEventListener('filter_order', (order) => {\n      updateItemsOrder(order);\n    });\n\n    rootScope.addEventListener('filter_joined', (filter) => {\n      setSelectedFolderId(filter.id);\n    });\n\n    rootScope.addEventListener('premium_toggle', async(isPremium) => {\n      if(isPremium) {\n        return;\n      }\n\n      const isFolderAvailable = await rootScope.managers.filtersStorage.isFilterIdAvailable(selectedFolderId());\n      if(!isFolderAvailable) {\n        setSelectedFolderId(FOLDER_ID_ALL);\n      }\n    });\n  }\n\n  return {\n    selectedFolderId,\n    setSelectedFolderId: _setSelectedFolderId,\n    selectedFolderIndex,\n    folderItems,\n    hydrateFilters,\n    onClick,\n    setOnClick\n  };\n});\n\nexport default function useFolders() {\n  return useFoldersStore;\n}\n","import Badge from '@components/badge';\nimport Tabs from '@components/tabs';\nimport wrapFolderTitle from '@components/wrappers/folderTitle';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {FOLDER_ID_ALL} from '@lib/appManagers/constants';\nimport {i18n} from '@lib/langPack';\nimport useFolders from '@stores/folders';\nimport {For} from 'solid-js';\n\nexport default function FoldersTabs(props: {\n  scrollableProps?: Partial<Parameters<typeof Tabs.MenuScrollable>[0]>,\n  menuProps?: Partial<Parameters<typeof Tabs.Menu>[0]>,\n  gradientProps?: Parameters<typeof Tabs.MenuGradient>[0]\n}) {\n  const {folderItems} = useFolders();\n\n  const Tab = (item: typeof folderItems[0]) => {\n    const title = () => {\n      if(item.id === FOLDER_ID_ALL) {\n        return i18n('FilterAllChatsShort');\n      }\n\n      const fragment = wrapFolderTitle(\n        item.filter.title,\n        createMiddleware().get(),\n        true,\n        {textColor: 'secondary-text-color'}\n      );\n      return documentFragmentToNodes(fragment);\n    };\n\n    return (\n      <Tabs.MenuTab\n        ref={(ref) => ref.dataset.filterId = '' + item.filter.id}\n      >\n        <span class=\"text-super\">\n          {title()}\n        </span>\n        <Badge\n          tag=\"div\"\n          size={20}\n          color={item.notifications.muted ? 'gray' : 'primary'}\n        >\n          {item.notifications.count}\n        </Badge>\n      </Tabs.MenuTab>\n    );\n  };\n\n  return (\n    <Tabs>\n      {props.gradientProps && <Tabs.MenuGradient {...props.gradientProps} />}\n      <Tabs.MenuScrollable {...(props.scrollableProps || {})}>\n        <Tabs.Menu {...(props.menuProps || {})}>\n          <For each={folderItems}>{Tab}</For>\n        </Tabs.Menu>\n      </Tabs.MenuScrollable>\n    </Tabs>\n  );\n}\n","import {JSX, splitProps} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport Icon from '@components/icon';\nimport ripple from '@components/ripple';\n\nexport const ButtonIconTsx = (inProps: {icon?: Icon, noRipple?: boolean} & JSX.ButtonHTMLAttributes<HTMLButtonElement>) => {\n  const [props, restProps] = splitProps(inProps, ['icon', 'class', 'children', 'noRipple']);\n\n  const btn = (\n    <button\n      class={classNames('btn-icon', props.class)}\n      {...restProps}\n      tabIndex={-1}\n    >\n      {props.icon && Icon(props.icon)}\n      {props.children}\n    </button>\n  );\n\n  if(!props.noRipple) ripple(btn as HTMLElement);\n\n  return btn;\n};\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport AppSelectPeers, {SelectSearchPeerType} from '@components/appSelectPeers';\nimport PopupElement, {createPopup, PopupContext, PopupContextValue} from '@components/popups/indexTsx';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {Modify} from '@types';\nimport {IsPeerType} from '@appManagers/appPeersManager';\nimport TransitionSlider from '@components/transition';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport {ForumTopic} from '@layer';\nimport RowTsx from '@components/rowTsx';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {avatarNew} from '@components/avatarNew';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport getDialogIndex from '@appManagers/utils/dialogs/getDialogIndex';\nimport {Middleware} from '@helpers/middleware';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport findUpAttribute from '@helpers/dom/findUpAttribute';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport rootScope from '@lib/rootScope';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport createTopPeersList from '@components/topPeersList';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport FoldersTabs from '@components/foldersTabs';\nimport {observeResize} from '@components/resizeObserver';\nimport {render} from 'solid-js/web';\nimport {selectTarget} from '@components/horizontalMenu';\nimport {ScrollableContextValue} from '@components/scrollable2';\nimport whichChild from '@helpers/dom/whichChild';\nimport showLimitPopup from '@components/popups/limit';\nimport type DialogsStorage from '@lib/storages/dialogs';\nimport type MonoforumDialogsStorage from '@lib/storages/monoforumDialogs';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {Accessor, createSignal, JSX, Show, untrack, useContext} from 'solid-js';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport {AppManagers} from '@lib/managers';\nimport {REAL_FOLDERS} from '@lib/appManagers/constants';\n\ntype PopupPickUserSelectedItem = {\n  peerId: PeerId,\n  threadId?: number,\n  monoforumThreadId?: PeerId,\n  key: string\n};\n\nexport type PopupPickUserOptions = Modify<ConstructorParameters<typeof AppSelectPeers>[0], {\n  appendTo?: never,\n  managers?: never,\n  onSelect?: (chosen: PopupPickUserSelectedItem[]) => Promise<void> | void,\n  onClose?: () => void,\n  onCloseAfterTimeout?: () => void,\n  middleware?: never,\n  titleLangKey: LangPackKey,\n  initial?: PeerId[],\n  prependPeerIds?: PeerId[],\n  useTopics?: boolean,\n  footerButtonProps?: Parameters<typeof PopupElement['FooterButton']>[0],\n  footer?: (ctx: {multiSelect: Accessor<AppSelectPeers['multiSelect']>}) => JSX.Element,\n  autoHeight?: boolean,\n  showTopPeers?: boolean,\n  btnConfirmOnEnter?: Parameters<typeof PopupElement>[0]['btnConfirmOnEnter'],\n  containerProps?: Parameters<typeof PopupElement>[0]['containerProps']\n}>;\n\nasync function wrapTopicRow({\n  peerId,\n  threadId,\n  middleware\n}: {\n  peerId: PeerId,\n  threadId: number,\n  middleware: Middleware\n}) {\n  const size = makeMediaSize(32, 32);\n  const title = threadId ? await wrapPeerTitle({peerId, threadId}) : i18n('AllMessages');\n  let media: JSX.Element;\n  if(threadId) {\n    const avatar = avatarNew({\n      peerId,\n      threadId,\n      middleware,\n      size: size.width,\n      wrapOptions: {\n        middleware,\n        textColor: 'primary-text-color',\n        customEmojiSize: size\n      }\n    });\n    await avatar.readyThumbPromise;\n    media = avatar.node;\n  } else {\n    media = wrapEmojiText('💬');\n  }\n\n  const row = wrapSolidComponent(() => (\n    <RowTsx\n      clickable\n      class=\"selector-forum-topic\"\n      classList={{'selector-forum-topic-all': !threadId}}\n    >\n      <RowTsx.Title>{title}</RowTsx.Title>\n      <RowTsx.Media size=\"abitbigger\">{media}</RowTsx.Media>\n    </RowTsx>\n  ), middleware);\n  row.dataset.peerId = [peerId, threadId].filter(Boolean).join('_');\n  return row;\n}\n\nexport default function showPickUserPopup(options: PopupPickUserOptions) {\n  let multiSelect: AppSelectPeers['multiSelect'];\n  if(typeof(options.multiSelect) === 'boolean') {\n    multiSelect = options.multiSelect ? 'enabled' : 'disabled';\n  } else {\n    multiSelect = options.multiSelect;\n  }\n  multiSelect ||= 'disabled';\n\n  const _onSelect = options.onSelect;\n\n  const [show, setShow] = createSignal(false);\n  const [canGoBack, setCanGoBack] = createSignal(false);\n  const [multiSelectMode, setMultiSelectMode] = createSignal<AppSelectPeers['multiSelect']>(multiSelect);\n\n  let selector: AppSelectPeers;\n  let forumSelector: AppSelectPeers | undefined;\n  let transition: ReturnType<typeof TransitionSlider> | undefined;\n  let forumNavigationItem: NavigationItem | undefined;\n  let btnConfirm: HTMLButtonElement;\n  let isMonoforum = false;\n  const selected: Array<PopupPickUserSelectedItem> = [];\n\n  let context: PopupContextValue;\n  let managers: AppManagers;\n  let middleware: Middleware;\n  let night: boolean;\n\n  const tabsContainer = document.createElement('div');\n  tabsContainer.classList.add('tabs-container');\n\n  let busy = false;\n  const finalize = async() => {\n    if(busy) {\n      return;\n    }\n\n    busy = true;\n    try {\n      const res = _onSelect(selected);\n      if(res instanceof Promise) {\n        await res;\n      }\n\n      busy = false;\n    } catch(err) {\n      busy = false;\n      throw err;\n    }\n\n    setShow(false);\n  };\n\n  const onSingleSelect = async(\n    sel: AppSelectPeers,\n    key: PeerId | string,\n    adding: boolean\n  ) => {\n    key = '' + key;\n    const [_peerId, _threadId] = key.split('_');\n    const peerId = _peerId.toPeerId();\n    const threadId = _threadId ? +_threadId : undefined;\n    const item: PopupPickUserSelectedItem = {\n      peerId,\n      threadId: isMonoforum ? undefined : threadId,\n      monoforumThreadId: isMonoforum ? threadId : undefined,\n      key\n    };\n\n    if(adding) selected.push(item);\n    else findAndSplice(selected, (item) => item.key === key);\n\n    if((sel.multiSelect === 'enabled' && selected.length) || !selected.length) {\n      return;\n    }\n\n    await finalize();\n  };\n\n  // The header button both reflects and drives the selector the user is currently looking at, so\n  // every selector reports its mode back here — the peer list and, once opened, the topic list.\n  const trackMultiSelectMode = (sel: AppSelectPeers) => {\n    const originalSetMultiSelectMode = sel.setMultiSelectMode.bind(sel);\n    sel.setMultiSelectMode = (mode) => {\n      originalSetMultiSelectMode(mode);\n      setMultiSelectMode(mode);\n    };\n    setMultiSelectMode(sel.multiSelect);\n  };\n\n  const enableMultiSelect = () => {\n    (canGoBack() ? forumSelector : selector)?.setMultiSelectMode('enabled');\n  };\n\n  const onBackClick = () => {\n    if(forumSelector) {\n      const selected = forumSelector.getSelected();\n      selector.removeBatch(selector.getSelected(), false);\n      selector.setMultiSelectMode(forumSelector.multiSelect);\n      selector.addInitial(selected);\n    }\n\n    transition?.(selector.container);\n    if(forumNavigationItem) {\n      appNavigationController.removeItem(forumNavigationItem);\n      forumNavigationItem = undefined;\n    }\n    setCanGoBack(false);\n  };\n\n  const createForumSelector = async({\n    peerId,\n    placeholder,\n    isMonoforum: _isMonoforum\n  }: {\n    peerId: PeerId,\n    placeholder: LangPackKey,\n    isMonoforum: boolean\n  }) => {\n    const fsMiddlewareHelper = middleware.create();\n    const fsMiddleware = fsMiddlewareHelper.get();\n    const deferred = deferredPromise<void>();\n    let offsetIndex: number, lastQuery: string, firstRender = true;\n    isMonoforum = _isMonoforum;\n    const selected = selector.getSelected();\n    const fs = forumSelector = new AppSelectPeers({\n      middleware: fsMiddleware,\n      appendTo: tabsContainer,\n      managers,\n      rippleEnabled: false,\n      night,\n      multiSelect,\n      placeholder,\n      peerType: ['custom'],\n      onChange: (length, changes) => {\n        changes.forEach(({key, add}) => onSingleSelect(fs, key, add));\n      },\n      getMoreCustom: async(q, middleware) => {\n        if(lastQuery !== q) {\n          offsetIndex = undefined;\n          lastQuery = q;\n        }\n\n        const limit = 20;\n        let result: Awaited<ReturnType<DialogsStorage['getDialogs']> | ReturnType<MonoforumDialogsStorage['getDialogs']>>;\n        if(_isMonoforum) {\n          result = await managers.monoforumDialogsStorage.getDialogs({\n            parentPeerId: peerId,\n            limit,\n            offsetIndex\n          });\n        } else {\n          result = await managers.dialogsStorage.getDialogs({\n            query: q,\n            filterId: peerId,\n            limit,\n            skipMigrated: true,\n            offsetIndex\n          });\n        }\n\n        if(!middleware()) {\n          return;\n        }\n\n        offsetIndex = getDialogIndex(result.dialogs[result.dialogs.length - 1]);\n\n        return {\n          result: _isMonoforum ?\n            result.dialogs.map((dialog) => dialog.peerId) as any :\n            result.dialogs.map((forumTopic) => (forumTopic as ForumTopic.forumTopic).id),\n          isEnd: result.isEnd\n        };\n      },\n      renderResultsFunc: async(threadIds, append) => {\n        const middleware = fs.middlewareHelperLoader.get();\n        if(firstRender) {\n          firstRender = false;\n\n          if(apiManagerProxy.isBotforum(peerId)) {\n            threadIds.unshift(undefined);\n          }\n        }\n\n        const promises = threadIds.map((threadId) => {\n          return wrapTopicRow({peerId, threadId, middleware});\n        });\n        const elements = await Promise.all(promises);\n        if(!middleware()) {\n          return;\n        }\n\n        elements.forEach((element) => {\n          const sel = fs.selected.has(element.dataset.peerId);\n          element.prepend(fs.checkbox(sel));\n        });\n        fs.list[!append ? 'append' : 'prepend'](...elements);\n      },\n      // placeholderSizes: _isMonoforum ? undefined : {\n      //   avatarSize: 32,\n      //   avatarMarginRight: 72 - 32 - 17,\n      //   marginVertical: 8,\n      //   marginLeft: 17,\n      //   lineMarginVertical: 11,\n      //   gapVertical: 0,\n      //   totalHeight: 48,\n      //   statusWidth: 0,\n      //   noSecondLine: true,\n      //   night\n      // },\n      onFirstRender: () => {\n        deferred.resolve();\n      },\n      noSearch: _isMonoforum && !selected.length\n    });\n\n    fs.setMultiSelectMode(selector.multiSelect);\n    trackMultiSelectMode(fs);\n    fs.addInitial(selected);\n    fs.container.classList.add('tabs-tab');\n    fs.container.middlewareHelper = fsMiddlewareHelper;\n    if(_isMonoforum && fs.selectorSearch) {\n      fs.selectorSearch.inputSearch.container.classList.add('hide');\n    }\n\n    await deferred;\n\n    setCanGoBack(true);\n    transition?.(fs.container);\n    const navigationItem: NavigationItem = forumNavigationItem = {\n      type: 'popup',\n      onPop: () => {\n        onBackClick();\n      }\n    };\n    appNavigationController.pushItem(navigationItem);\n    middleware.onClean(() => {\n      isMonoforum = false;\n      appNavigationController.removeItem(navigationItem);\n    });\n  };\n\n  const createFolderTabs = (afterElement: HTMLElement) => {\n    let menu: HTMLElement;\n    let prevId = -1;\n    const mount = document.createElement('div');\n    mount.classList.add('popup-forward-folder-tabs-container', 'collapsable');\n    afterElement.after(mount);\n    let scrollableContext: ScrollableContextValue;\n\n    const sectionContainer = selector.selectorSearch.section.container;\n    const unobserve = observeResize(sectionContainer, () => {\n      mount.style.top = sectionContainer.offsetHeight + 'px';\n    });\n    const lateMiddleware = untrack(() => context.lateMiddlewareHelper).get();\n    lateMiddleware.onClean(unobserve);\n\n    const deferred = deferredPromise<void>();\n\n    const scrollToStart = (callback: () => void) => {\n      let clicked = false;\n      const onFinish = () => {\n        if(!clicked) {\n          clicked = true;\n          callback();\n        }\n      };\n\n      fastSmoothScroll({\n        container: selector.scrollable.container,\n        element: selector.section.container,\n        position: 'start',\n        getElementPosition: ({elementPosition}) => elementPosition -\n          mount.offsetHeight -\n          sectionContainer.offsetHeight,\n        startCallback: ({duration, path}) => {\n          if(path >= 0) onFinish();\n          else setTimeout(onFinish, Math.max(0, duration / 2));\n        }\n      }).finally(callback);\n    };\n\n    const onTabClick = (target: HTMLElement, id: number) => {\n      return selectTarget({\n        target,\n        id,\n        tabs: menu,\n        onClick: async() => {\n          const filterId = +(target.dataset.filterId || 0);\n          const available = REAL_FOLDERS.has(filterId) ||\n            (await rootScope.managers.filtersStorage.isFilterIdAvailable(filterId) ?? true);\n          if(!available) {\n            showLimitPopup('folders');\n            return false;\n          }\n\n          if(prevId !== -1) {\n            await new Promise<void>((resolve) => scrollToStart(resolve));\n          }\n\n          selector.setFolderId(filterId);\n          prevId = id;\n        },\n        prevId,\n        scrollableX: scrollableContext\n      });\n    };\n\n    const dispose = render(() => FoldersTabs({\n      scrollableProps: {\n        class: 'popup-forward-folder-tabs',\n        scrollableProps: {\n          contextRef: (ref) => scrollableContext = ref\n        }\n      },\n      menuProps: {\n        ref: (ref) => {\n          menu = ref;\n          queueMicrotask(async() => {\n            const first = ref.firstElementChild as HTMLElement;\n            if(first) await onTabClick(first, 0);\n            deferred.resolve();\n          });\n        },\n        onClick: (e) => {\n          cancelEvent(e);\n          const target = findUpAttribute(e.target, 'data-filter-id') as HTMLElement;\n          if(!target) return;\n          const id = whichChild(target);\n          onTabClick(target, id);\n        }\n      },\n      gradientProps: {\n        color: 'background',\n        className: 'popup-forward-folder-tabs-gradient'\n      }\n    }), mount);\n\n    lateMiddleware.onClean(dispose);\n\n    selector.onSearchChange = (query) => {\n      mount.classList.toggle('is-collapsed', !!query);\n    };\n\n    return deferred;\n  };\n\n  function Inner() {\n    context = useContext(PopupContext);\n    managers = untrack(() => context.managers);\n    middleware = untrack(() => context.middlewareHelper.get());\n    night = untrack(() => context.night);\n\n    selector = new AppSelectPeers({\n      ...options,\n      multiSelect,\n      middleware,\n      appendTo: tabsContainer,\n      onChange: (length, changes) => {\n        btnConfirm?.classList.toggle('is-visible', !!length);\n        changes.forEach(({key, add}) => onSingleSelect(selector, key, add));\n        options.onChange?.(length, changes);\n      },\n      onSelect: async(peerId, adding, e) => {\n        let _isMonoforum = false;\n        if(\n          options.useTopics &&\n          e.isTrusted &&\n          (\n            apiManagerProxy.isForum(peerId) ||\n            apiManagerProxy.isBotforum(peerId) ||\n            (_isMonoforum = (\n              await managers.appPeersManager.canManageDirectMessages(peerId) &&\n              await managers.appPeersManager.isMonoforum(peerId)\n            ))\n          )\n        ) {\n          createForumSelector({\n            peerId,\n            placeholder: options.placeholder,\n            isMonoforum: _isMonoforum\n          });\n          return false;\n        }\n      },\n      onFirstRender: () => {\n        setShow(true);\n        selector.checkForTriggers();\n\n        if(!IS_TOUCH_SUPPORTED && selector.inputSearch) {\n          selector.inputSearch.input.focus();\n        }\n      },\n      noPlaceholder: true,\n      rippleEnabled: false,\n      avatarSize: 'abitbigger',\n      managers,\n      night,\n      noInstantLoad: true,\n      noSearch: options.noSearch\n    });\n    selector.container.classList.add('tabs-tab');\n\n    trackMultiSelectMode(selector);\n\n    const loadPromises: Promise<any>[] = [];\n    if(options.showTopPeers) {\n      const {group, promise} = createTopPeersList({\n        middleware,\n        className: 'popup-forward-top-peers collapsable',\n        modifyPeers: (peers) => {\n          findAndSplice(peers, (peer) => peer.id === rootScope.myId);\n          peers.unshift({\n            id: rootScope.myId,\n            rating: 0\n          });\n          return peers;\n        }\n      });\n      selector.heightContainer.before(group.container);\n\n      loadPromises.push(createFolderTabs(group.container));\n\n      const prevOnSearchChange = selector.onSearchChange;\n      selector.onSearchChange = (query) => {\n        group.container.classList.toggle('is-collapsed', !!query);\n        prevOnSearchChange?.(query);\n      };\n\n      if(multiSelect !== 'disabled') promise.then(() => {\n        const topPeerElements = group.list.querySelectorAll<HTMLElement>('.chatlist-chat');\n\n        topPeerElements.forEach((el) => {\n          const peerId = el.dataset.peerId.toPeerId();\n          const sel = selector.selected.has(peerId);\n          el.prepend(selector.checkbox(sel, 'white'));\n        });\n      });\n    }\n\n    if(options.initial) {\n      selector.addInitial(options.initial);\n    }\n    selector.container.classList.add('active');\n\n    if(options.useTopics) {\n      transition = TransitionSlider({\n        content: tabsContainer,\n        type: 'tabs',\n        transitionTime: 150,\n        animateFirst: false,\n        onTransitionEnd: (id) => {\n          if(!id) {\n            (Array.from(tabsContainer.children) as HTMLElement[]).forEach((el) => {\n              if(el !== selector.container) {\n                (el as any).middlewareHelper?.destroy();\n                el.remove();\n              }\n            });\n          } else {\n            selector.clearInput();\n          }\n        }\n      });\n      transition(selector.container);\n    }\n\n    Promise.all(loadPromises).then(() => {\n      selector.loadFirst();\n    });\n\n    return tabsContainer;\n  }\n\n  function FooterInner(): JSX.Element {\n    if(options.footer) {\n      return options.footer({multiSelect: multiSelectMode});\n    }\n\n    return (\n      <PopupElement.FooterButton\n        confirm\n        callback={() => {\n          finalize();\n        }}\n        {...(options.footerButtonProps || {})}\n      />\n    );\n  }\n\n  createPopup(() => {\n    return (\n      <PopupElement\n        class=\"popup-forward\"\n        containerClass={options.autoHeight ? 'popup-forward-auto-height' : undefined}\n        containerProps={options.containerProps}\n        closable\n        show={show()}\n        onClose={() => {\n          options.onClose?.();\n        }}\n        onCloseAfterTimeout={() => {\n          selector?.destroy();\n          selector = undefined;\n          options.onCloseAfterTimeout?.();\n        }}\n        btnConfirmOnEnter={options.btnConfirmOnEnter}\n      >\n        <PopupElement.Header>\n          <PopupElement.CloseButton\n            canGoBack={canGoBack()}\n            onBackClick={onBackClick}\n          />\n          <PopupElement.Title title={options.titleLangKey} />\n          {/* 'hidden' is the only mode where multiselect is available but off — 'disabled' has none\n              to offer and 'enabled' is already selecting, so the button belongs to that state alone */}\n          <Show when={multiSelectMode() === 'hidden'}>\n            <ButtonIconTsx\n              icon=\"checkround\"\n              class=\"popup-forward-multiselect\"\n              onClick={enableMultiSelect}\n            />\n          </Show>\n        </PopupElement.Header>\n        <PopupElement.Body>\n          <Inner />\n        </PopupElement.Body>\n        <Show when={multiSelect !== 'disabled' || options.footer}>\n          <PopupElement.Footer class=\"popup-forward-footer\" floating>\n            <FooterInner />\n          </PopupElement.Footer>\n        </Show>\n      </PopupElement>\n    );\n  });\n\n  return {\n    get selector() {\n      return selector;\n    },\n    get middleware() {\n      return middleware;\n    },\n    hide() {\n      setShow(false);\n    },\n    finalize\n  };\n}\n\nexport async function showPickUser2Popup<T extends boolean = false>({\n  peerType,\n  filterPeerTypeBy,\n  chatRightsActions,\n  multiSelect,\n  limit,\n  limitCallback,\n  titleLangKey,\n  placeholder,\n  exceptSelf\n}: {\n  peerType?: SelectSearchPeerType[],\n  filterPeerTypeBy: AppSelectPeers['filterPeerTypeBy'],\n  chatRightsActions?: PopupPickUserOptions['chatRightsActions'],\n  placeholder?: LangPackKey,\n  multiSelect?: T,\n  limit?: number,\n  limitCallback?: () => void,\n  titleLangKey?: LangPackKey,\n  exceptSelf?: boolean\n}) {\n  return new Promise<T extends false ? PeerId : PeerId[]>((resolve, reject) => {\n    let resolved = false;\n    const popup = showPickUserPopup({\n      peerType,\n      placeholder: placeholder || 'SelectChat',\n      onSelect: (chosen) => {\n        // The footer button stays clickable with an empty selection — treat\n        // that as a cancel (onClose rejects) instead of resolving with [].\n        if(!chosen.length) {\n          return;\n        }\n\n        resolved = true;\n        resolve((multiSelect ? chosen.map((c) => c.peerId) : chosen[0].peerId) as any);\n      },\n      multiSelect,\n      // The batch is confirmed via the floating footer button, which needs a\n      // label — an unlabeled FooterButton renders as an empty bar.\n      footerButtonProps: multiSelect ? {langKey: 'Send'} : undefined,\n      filterPeerTypeBy,\n      chatRightsActions,\n      titleLangKey,\n      exceptSelf,\n      onClose: () => {\n        if(!resolved) {\n          reject();\n        }\n      }\n    });\n\n    if(limit) {\n      popup.selector?.setLimit(limit, limitCallback);\n    }\n  });\n}\n\nexport async function showPickUser3Popup(\n  types: Parameters<typeof AppSelectPeers['convertPeerTypes']>[0] = ['users', 'bots', 'groups', 'channels'],\n  chatRightsActions?: PopupPickUserOptions['chatRightsActions']\n) {\n  if(!Array.isArray(types)) {\n    types = [];\n  }\n\n  const filterPeerTypeBy: IsPeerType[] = AppSelectPeers.convertPeerTypes(types);\n  const peerType: SelectSearchPeerType[] = ['dialogs'];\n  if(types.includes('users')) peerType.push('contacts');\n\n  if(!filterPeerTypeBy.length) {\n    throw undefined;\n  }\n\n  return showPickUser2Popup({\n    peerType,\n    filterPeerTypeBy,\n    chatRightsActions,\n    titleLangKey: 'ShareWith'\n  });\n}\n\nexport function showSharingPickerPopup(options: {\n  onSelect: PopupPickUserOptions['onSelect'],\n  chatRightsActions?: PopupPickUserOptions['chatRightsActions'],\n  excludeMonoforums?: PopupPickUserOptions['excludeMonoforums'],\n  excludeBotforums?: PopupPickUserOptions['excludeBotforums'],\n  placeholder?: LangPackKey,\n  selfPresence?: LangPackKey,\n  // Multi-select toggle for the picker. `true` ⇒ checkboxes, user confirms a\n  // batch; `false` (default) ⇒ pick-and-send immediately. Pass-through to\n  // AppSelectPeers' own `multiSelect` enum if a non-boolean is needed.\n  multiSelect?: PopupPickUserOptions['multiSelect'],\n  onCloseAfterTimeout?: () => void,\n  onClose?: () => void\n}) {\n  options.chatRightsActions ??= ['send_plain'];\n  options.placeholder ??= 'ShareModal.Search.Placeholder';\n  options.selfPresence ??= 'ChatYourSelf';\n  return showPickUserPopup({\n    titleLangKey: 'ShareWith',\n    showTopPeers: true,\n    // Default the floating footer button's label to \"Send\" — without this the\n    // PopupElement.FooterButton renders as an empty purple bar in multi-select\n    // mode (single-select callers complete via row click and never see it).\n    footerButtonProps: {langKey: 'Send'},\n    ...options,\n    peerType: ['dialogs', 'contacts']\n  });\n}\n\nexport function showSharingPicker2Popup(options?: Modify<Parameters<typeof showSharingPickerPopup>[0], {onSelect?: never}>) {\n  return new Promise<{peerId: PeerId, threadId?: number, monoforumThreadId?: PeerId}>((resolve, reject) => {\n    let resolved = false;\n    showSharingPickerPopup({\n      ...(options || {}),\n      onSelect: (chosen) => {\n        resolved = true;\n        resolve(chosen[0]);\n      },\n      onClose: () => {\n        if(!resolved) {\n          reject();\n        }\n      }\n    });\n  });\n}\n\nexport function showReplyPickerPopup(options: Pick<PopupPickUserOptions, 'excludeBotforums' | 'excludeMonoforums'> = {}) {\n  return showSharingPicker2Popup({\n    placeholder: 'ReplyToDialog',\n    selfPresence: 'SavedMessagesInfoQuote',\n    ...options\n  });\n}\n\nexport function showContactPickerPopup() {\n  return new Promise<PeerId>((resolve, reject) => {\n    let resolved = false;\n    showPickUserPopup({\n      titleLangKey: 'Contacts',\n      peerType: ['contacts'],\n      placeholder: 'Search',\n      onSelect: (chosen) => {\n        resolved = true;\n        resolve(chosen[0].peerId);\n      },\n      onClose: () => {\n        if(!resolved) {\n          reject();\n        }\n      }\n    });\n  });\n}\n","import {getAppWindow} from '@helpers/appWindow';\n\nexport type CopyToClipboardOptions = {\n  /** Re-throw the underlying error instead of swallowing it (e.g. so a caller can show a toast) */\n  rethrow?: boolean;\n};\n\ntype ClipboardItemData = ConstructorParameters<typeof ClipboardItem>[0];\n\nfunction getClipboardContext(appWindow = getAppWindow()) {\n  const ClipboardItemConstructor = (appWindow as any).ClipboardItem as typeof ClipboardItem;\n  const clipboard = appWindow.navigator.clipboard;\n\n  return {ClipboardItemConstructor, clipboard};\n}\n\nexport function canWriteClipboardItem(mimeType: string, appWindow = getAppWindow()) {\n  const {ClipboardItemConstructor, clipboard} = getClipboardContext(appWindow);\n  return !!(\n    ClipboardItemConstructor &&\n    clipboard?.write &&\n    (!ClipboardItemConstructor.supports || ClipboardItemConstructor.supports(mimeType))\n  );\n}\n\nexport function writeClipboardItem(data: ClipboardItemData, appWindow = getAppWindow()) {\n  const {ClipboardItemConstructor, clipboard} = getClipboardContext(appWindow);\n  if(!ClipboardItemConstructor || !clipboard?.write) {\n    throw new Error('Clipboard item writing is not supported');\n  }\n\n  return clipboard.write([new ClipboardItemConstructor(data)]);\n}\n\n// https://stackoverflow.com/a/30810322\nfunction fallbackCopyTextToClipboard(\n  text: string,\n  html?: string,\n  options?: CopyToClipboardOptions,\n  appWindow = getAppWindow()\n) {\n  const {document} = appWindow;\n  const textArea = document.createElement(html ? 'div' : 'textarea');\n  if(html) {\n    textArea.tabIndex = 0;\n    textArea.contentEditable = 'true';\n    textArea.innerHTML = html;\n  } else {\n    (textArea as HTMLTextAreaElement).value = text;\n  }\n\n  // Avoid scrolling to bottom\n  textArea.style.top = '0';\n  textArea.style.left = '0';\n  textArea.style.position = 'fixed';\n\n  document.body.appendChild(textArea);\n  textArea.focus();\n  if(html) {\n    const selection = appWindow.getSelection();\n    selection.removeAllRanges();\n    const range = document.createRange();\n    range.setStartBefore(textArea.firstChild);\n    range.setEndAfter(textArea.lastChild);\n    selection.addRange(range);\n  } else {\n    (textArea as HTMLTextAreaElement).select();\n  }\n\n  try {\n    document.execCommand('copy');\n    appWindow.getSelection().removeAllRanges();\n  } catch(err) {\n    console.error('unable to copy', err);\n    if(options?.rethrow) {\n      throw err;\n    }\n  } finally {\n    document.body.removeChild(textArea);\n  }\n}\n\nexport async function copyTextToClipboard(text: string, html?: string, options?: CopyToClipboardOptions) {\n  const appWindow = getAppWindow();\n  const BlobConstructor = (appWindow as any).Blob as typeof Blob;\n  if(!appWindow.navigator.clipboard) {\n    fallbackCopyTextToClipboard(text, undefined, options, appWindow);\n    return;\n  }\n\n  try {\n    if(!html) {\n      await appWindow.navigator.clipboard.writeText(text);\n      return;\n    }\n\n    await writeClipboardItem({\n      'text/plain': new BlobConstructor([text], {type: 'text/plain'}),\n      'text/html': new BlobConstructor([html], {type: 'text/html'})\n    }, appWindow);\n  } catch(err) {\n    console.error('clipboard error', err);\n    // The fallback will rethrow if it also fails and the caller opted in\n    fallbackCopyTextToClipboard(text, html, options, appWindow);\n  }\n}\n","export type StickyIntersectorOptions = {\n  rootMargin?: string\n};\n\nexport default class StickyIntersector {\n  private headersObserver: IntersectionObserver;\n  private elementsObserver: IntersectionObserver;\n  private observed = new Map<HTMLElement, HTMLElement>(); // sticky-target element → its top sentinel\n  private rootMargin: string | undefined;\n\n  constructor(\n    private container: HTMLElement,\n    private handler: (stuck: boolean, target: HTMLElement) => void,\n    options?: StickyIntersectorOptions\n  ) {\n    this.rootMargin = options?.rootMargin;\n    this.createObservers();\n  }\n\n  private createObservers() {\n    this.headersObserver = new IntersectionObserver((entries) => {\n      for(const entry of entries) {\n        const targetInfo = entry.boundingClientRect;\n        const stickyTarget = entry.target.parentElement;\n        const rootBoundsInfo = entry.rootBounds;\n\n        // Stuck while the sentinel sits above the root's top edge. Otherwise the\n        // section is either in view or scrolled past below — both mean not stuck.\n        this.handler(targetInfo.bottom < rootBoundsInfo.top, stickyTarget);\n      }\n    }, {threshold: 0, root: this.container, rootMargin: this.rootMargin});\n\n    this.elementsObserver = new IntersectionObserver((entries) => {\n      // A section is \"stuck\" while it straddles the root's top edge. Containers\n      // have real height, so unlike thin sentinels the observer can't skip their\n      // intersection transitions on fast scrolls — this serves as a backup that\n      // clears state when headersObserver missed a sentinel crossing.\n      for(const entry of entries) {\n        const stuck = entry.isIntersecting && entry.boundingClientRect.top < entry.rootBounds.top;\n        this.handler(stuck, entry.target as HTMLElement);\n      }\n    }, {root: this.container, rootMargin: this.rootMargin});\n  }\n\n  public setRootMargin(rootMargin: string | undefined) {\n    if(this.rootMargin === rootMargin) return;\n    this.rootMargin = rootMargin;\n    this.headersObserver.disconnect();\n    this.elementsObserver.disconnect();\n    this.createObservers();\n    for(const [element, sentinel] of this.observed) {\n      this.headersObserver.observe(sentinel);\n      this.elementsObserver.observe(element);\n    }\n  }\n\n  /**\n   * @param {!Element} container\n   * @param {string} className\n   */\n  private addSentinel(container: HTMLElement, className: string) {\n    const sentinel = document.createElement('div');\n    sentinel.classList.add('sticky_sentinel', className);\n    return container.appendChild(sentinel);\n  }\n\n  /**\n   * Notifies when elements w/ the `sticky` class begin to stick or stop sticking.\n   * Note: the elements should be children of `container`.\n   * @param {!Element} container\n   */\n  public observeStickyHeaderChanges(element: HTMLElement) {\n    const headerSentinel = this.addSentinel(element, 'sticky_sentinel--top');\n    this.observed.set(element, headerSentinel);\n    this.headersObserver.observe(headerSentinel);\n    this.elementsObserver.observe(element);\n  }\n\n  public disconnect() {\n    this.headersObserver.disconnect();\n    this.elementsObserver.disconnect();\n    this.observed.clear();\n  }\n\n  public unobserve(element: HTMLElement, headerSentinel?: HTMLElement) {\n    this.elementsObserver.unobserve(element);\n    const sentinel = this.observed.get(element) ?? headerSentinel;\n    if(sentinel) {\n      this.headersObserver.unobserve(sentinel);\n    }\n    this.observed.delete(element);\n  }\n}\n","import getEmojiEntityFromEmoji from '@lib/richTextProcessor/getEmojiEntityFromEmoji';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\n\nexport default function wrapSingleEmoji(emoji: string) {\n  return wrapRichText(emoji, {\n    entities: [getEmojiEntityFromEmoji(emoji)]\n  });\n}\n","import whichChild from '@helpers/dom/whichChild';\n\nexport default function positionElementByIndex(element: HTMLElement, container: HTMLElement, pos: number, prevPos?: number) {\n  if(prevPos === undefined) {\n    prevPos = element.parentElement === container ? whichChild(element) : -1;\n  }\n\n  if(prevPos === pos) {\n    return false;\n  } else if(prevPos !== -1 && prevPos < pos) { // was higher\n    pos += 1;\n  }\n\n  if(!pos) {\n    container.prepend(element);\n  } else if(container.childElementCount > pos) {\n    container.insertBefore(element, container.children[pos]);\n  } else {\n    container.append(element);\n  }\n\n  return true;\n}\n","export enum ChatType {\n  Chat = 'chat',\n  Pinned = 'pinned',\n  Discussion = 'discussion',\n  Scheduled = 'scheduled',\n  Stories = 'stories',\n  Saved = 'saved',\n  Search = 'search',\n  Static = 'static',\n  Logs = 'logs'\n}\n","import {JSX, ParentComponent, Ref, splitProps} from 'solid-js';\nimport {LangPackKey, FormatterArguments, i18n} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\n\nexport type SectionOptions = {\n  name?: LangPackKey | HTMLElement | DocumentFragment | JSX.Element,\n  nameArgs?: FormatterArguments,\n  nameRight?: JSX.Element,\n  nameRef?: Ref<HTMLDivElement>,\n  caption?: LangPackKey | JSX.Element,\n  captionArgs?: FormatterArguments,\n  captionOld?: boolean,\n  captionTop?: boolean,\n  captionRef?: Ref<HTMLDivElement>,\n  noDelimiter?: boolean,\n  noShadow?: boolean,\n  noMarginBottom?: boolean,\n  noContent?: boolean,\n  class?: JSX.HTMLAttributes<HTMLDivElement>['class'],\n  innerClass?: string,\n  contentProps?: JSX.HTMLAttributes<HTMLDivElement>,\n  ref?: Ref<HTMLDivElement>\n};\n\nconst className = 'sidebar-left-section';\ntype SectionProps = SectionOptions & Omit<\n  JSX.HTMLAttributes<HTMLDivElement>,\n  keyof SectionOptions\n>;\nconst SectionContent: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {\n  const [local, rest] = splitProps(props, ['ref', 'class', 'children']);\n  return (\n    <div\n      {...rest}\n      ref={local.ref}\n      class={classNames(className + '-content', local.class)}\n    >\n      {local.children}\n    </div>\n  );\n};\nconst SectionCaption = (props: Pick<SectionOptions, 'caption' | 'captionArgs' | 'captionRef'>) => {\n  return (\n    <SectionContent ref={props.captionRef} class={className + '-caption'}>\n      {typeof props.caption === 'string' ?\n        i18n(props.caption as LangPackKey, props.captionArgs) :\n        props.caption}\n    </SectionContent>\n  );\n};\nconst Section: ParentComponent<SectionProps> = (props) => {\n  const [, rest] = splitProps(props, ['name', 'nameRef', 'nameArgs', 'nameRight', 'innerClass', 'caption', 'captionArgs', 'captionOld', 'captionTop', 'captionRef', 'noDelimiter', 'noShadow', 'noMarginBottom', 'noContent', 'class', 'contentProps', 'ref']);\n  return (\n    <div\n      class={classNames(className + '-container', props.class)}\n      ref={props.ref}\n      {...rest}\n    >\n      {props.caption && props.captionTop && <SectionCaption {...props} />}\n      {!props.noContent && (\n        <div\n          class={classNames(\n            className,\n            props.noShadow && 'no-shadow',\n            props.noDelimiter && 'no-delimiter',\n            props.innerClass,\n            props.noMarginBottom && 'no-margin-bottom'\n          )}\n        >\n          <SectionContent {...props.contentProps}>\n            {props.name && (\n              <div ref={props.nameRef} class={classNames('sidebar-left-h2', className + '-name')}>\n                {typeof(props.name) === 'string' ? i18n(props.name as LangPackKey, props.nameArgs) : props.name}\n                {props.nameRight && <div class={className + '-name-right'}>{props.nameRight}</div>}\n              </div>\n            )}\n            {props.children}\n          </SectionContent>\n          {props.caption && !props.captionTop && props.captionOld && <SectionCaption {...props} />}\n        </div>\n      )}\n      {props.caption && !props.captionTop && !props.captionOld && <SectionCaption {...props} />}\n    </div>\n  );\n}\n\nexport default Section;\n","import type LazyLoadQueue from '@components/lazyLoadQueue';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport {avatarNew} from '@components/avatarNew';\nimport {createEffect, on, onCleanup} from 'solid-js';\n\nconst CLASS_NAME = 'stacked-avatars';\nconst AVATAR_CLASS_NAME = CLASS_NAME + '-avatar';\nconst AVATAR_CONTAINER_CLASS_NAME = AVATAR_CLASS_NAME + '-container';\n\nexport default class StackedAvatars {\n  public container: HTMLElement;\n  private lazyLoadQueue: LazyLoadQueue;\n  private avatarSize: number;\n  private middlewareHelper: MiddlewareHelper;\n\n  constructor(options: {\n    lazyLoadQueue?: StackedAvatars['lazyLoadQueue'],\n    avatarSize: StackedAvatars['avatarSize'],\n    middleware: Middleware\n  }) {\n    this.lazyLoadQueue = options.lazyLoadQueue;\n    this.avatarSize = options.avatarSize;\n    this.middlewareHelper = options.middleware.create();\n\n    this.container = document.createElement('div');\n    this.container.classList.add(CLASS_NAME);\n\n    this.container.style.setProperty('--avatar-size', options.avatarSize + 'px');\n  }\n\n  /**\n   * MACOS, ANDROID - без реверса\n   * WINDOWS DESKTOP - реверс\n   * все приложения накладывают аватарку первую на вторую, а в макете зато вторая на первую, ЛОЛ!\n   */\n  public render(peerIds: PeerId[], loadPromises: Promise<any>[] = []) {\n    const children = this.container.children;\n    peerIds = peerIds.slice().reverse();\n    if(peerIds.length > 3) {\n      peerIds = peerIds.slice(-3);\n    }\n\n    peerIds.forEach((peerId, idx) => {\n      let avatarContainer = children[idx] as HTMLElement;\n      if(!avatarContainer) {\n        avatarContainer = document.createElement('div');\n        avatarContainer.classList.add(AVATAR_CONTAINER_CLASS_NAME);\n        avatarContainer.middlewareHelper = this.middlewareHelper.get().create();\n      } else {\n        avatarContainer.middlewareHelper.clean();\n      }\n\n      const avatarElem = avatarNew({\n        middleware: avatarContainer.middlewareHelper.get(),\n        size: this.avatarSize,\n        isDialog: false,\n        lazyLoadQueue: this.lazyLoadQueue,\n        peerId\n      });\n      avatarElem.node.classList.add(AVATAR_CLASS_NAME);\n      loadPromises?.push(avatarElem.readyThumbPromise);\n\n      avatarContainer.replaceChildren(avatarElem.node);\n\n      if(!avatarContainer.parentNode) {\n        this.container.append(avatarContainer);\n      }\n\n      avatarContainer.classList.toggle('is-first', idx === 0);\n      avatarContainer.classList.toggle('is-last', idx === peerIds.length - 1);\n    });\n\n    // if were 3 and became 2\n    (Array.from(children) as HTMLElement[]).slice(peerIds.length).forEach((el) => {\n      el.middlewareHelper.destroy();\n      el.remove();\n    });\n\n    return Promise.all(loadPromises);\n  }\n}\n\nexport function StackedAvatarsTsx(props: {\n  peerIds: PeerId[],\n  avatarSize: number,\n  lazyLoadQueue?: StackedAvatars['lazyLoadQueue'],\n}) {\n  const middleware = getMiddleware()\n  const stackedAvatars = new StackedAvatars({\n    avatarSize: props.avatarSize,\n    lazyLoadQueue: props.lazyLoadQueue,\n    middleware: middleware.get()\n  });\n\n  onCleanup(() => middleware.destroy());\n\n  createEffect(on(() => props.peerIds, (peerIds) => {\n    stackedAvatars.render(peerIds);\n  }));\n\n  return stackedAvatars.container;\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport type {Middleware} from '@helpers/middleware';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {FormatterArguments, i18n, LangPackKey} from '@lib/langPack';\nimport CheckboxField from '@components/checkboxField';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport RowTsx from '@components/rowTsx';\nimport {toastNew} from '@components/toast';\nimport {Accessor, createRoot, createSignal, Setter} from 'solid-js';\nimport {unwrapSolidElement} from '@helpers/solid/wrapSolidComponent';\n\nexport type CheckboxFieldsRow = {\n  container: HTMLElement,\n  title?: HTMLElement,\n  toggleDisability: (disable?: boolean) => VoidFunction\n};\n\nexport type CheckboxFieldsField = {\n  text?: LangPackKey,\n  textArgs?: FormatterArguments,\n  description?: LangPackKey,\n  restrictionText?: LangPackKey,\n  checkboxField?: CheckboxField,\n  checked?: boolean,\n  nested?: CheckboxFieldsField[],\n  nestedTo?: CheckboxFieldsField,\n  nestedCounter?: HTMLElement,\n  setNestedCounter?: (count: number) => void,\n  nestedRightButtonIcon?: Icon | false,\n  toggleWith?: {checked?: CheckboxFieldsField[], unchecked?: CheckboxFieldsField[]},\n  name?: string,\n  row?: CheckboxFieldsRow\n};\n\nexport default class CheckboxFields<K extends CheckboxFieldsField = CheckboxFieldsField> {\n  public fields: Array<K>;\n  protected listenerSetter: ListenerSetter;\n  /** The rows' RENDER lifetime, when the owner has one - see the disposal note in `createField` */\n  protected middleware: Middleware;\n  protected asRestrictions: boolean;\n  protected round: boolean;\n  protected onRowCreation: (row: CheckboxFieldsRow, info: K) => void;\n  protected rightButtonIcon: Icon;\n  protected onAnyChange?: () => void;\n  protected onExpand?: (info: K) => void;\n\n  constructor(options: {\n    fields: Array<K>,\n    listenerSetter: ListenerSetter,\n    middleware?: Middleware,\n    asRestrictions?: boolean,\n    round?: boolean,\n    rightButtonIcon?: Icon,\n    onRowCreation?: CheckboxFields<K>['onRowCreation'],\n    onAnyChange?: () => void,\n    onExpand?: (info: K) => void\n  }) {\n    safeAssign(this, options);\n  }\n\n  public createField(info: CheckboxFieldsField, isNested?: boolean) {\n    if(info.nestedTo && !isNested) {\n      return;\n    }\n\n    let accordion: HTMLElement;\n    let rightContent: HTMLElement;\n    let nestedCounter: HTMLElement;\n    let expanded: Accessor<boolean>;\n    let setExpanded: Setter<boolean>;\n    const updateAccordionHeight = () => {\n      accordion.style.setProperty('--max-height', accordion.scrollHeight + 'px');\n    };\n    const setAccordionExpanded = (expanded: boolean) => {\n      updateAccordionHeight();\n      setExpanded(expanded);\n      accordion.classList.toggle('is-expanded', expanded);\n      this.onExpand?.(info as K);\n    };\n\n    let container: HTMLElement;\n    let title: HTMLElement;\n    let checkboxField: CheckboxField;\n    let disposeRoot: VoidFunction;\n    let disabled: Accessor<boolean>;\n    let setDisabled: Setter<boolean>;\n    let disposed = false;\n    const titleContent = info.text ? i18n(info.text, info.textArgs) : undefined;\n    const subtitleContent = info.description ? i18n(info.description) : undefined;\n    const isToggle = !this.round && !isNested;\n    const nestedRightButtonIcon = info.nestedRightButtonIcon === false ?\n      undefined :\n      info.nestedRightButtonIcon ?? this.rightButtonIcon;\n    const onClick = info.nested ? (e: MouseEvent) => {\n      if(\n        this.round ?\n          !findUpAsChild(e.target as HTMLElement, rightContent) && e.target !== rightContent :\n          findUpAsChild(e.target as HTMLElement, checkboxField.label)\n      ) {\n        if(checkboxField.input.disabled) {\n          const checked = checkboxField.checked;\n          info.nested.forEach((field) => {\n            field.checkboxField.checked = !checked;\n          });\n        } else {\n          checkboxField.checked = !checkboxField.checked;\n        }\n\n        return;\n      }\n\n      cancelEvent(e);\n\n      setAccordionExpanded(!accordion.classList.contains('is-expanded'));\n    } : undefined;\n\n    const rowElement = createRoot((dispose) => {\n      disposeRoot = dispose;\n      [expanded, setExpanded] = createSignal(false);\n      [disabled, setDisabled] = createSignal(false);\n\n      const field = (\n        <CheckboxFieldTsx\n          checked={info.nested ? false : info.checked}\n          toggle={this.round ? undefined : !isNested}\n          listenerSetter={this.listenerSetter}\n          restriction={this.asRestrictions && !isNested}\n          name={info.name}\n          round={this.round}\n          lockIcon={info.restrictionText && !info.nestedTo ? 'premium_lock' : undefined}\n          ref={(createdField) => {\n            checkboxField = info.checkboxField = createdField;\n            createdField.label.classList.add('disable-hover');\n          }}\n        />\n      );\n\n      const element = (\n        <RowTsx\n          ref={(element) => container = element}\n          clickable={onClick}\n          disabled={disabled()}\n          aria-disabled={disabled()}\n          classList={{\n            'accordion-row': true,\n            'accordion-toggler': !!info.nested,\n            'accordion-toggler-round': !!info.nested && !!this.round,\n            'accordion-toggler-expanded': expanded()\n          }}\n        >\n          {/* Row.Title adopts an already-registered toggle into its right column. */}\n          {isToggle ? (\n            <RowTsx.CheckboxFieldToggle>{field}</RowTsx.CheckboxFieldToggle>\n          ) : (\n            <RowTsx.CheckboxField>{field}</RowTsx.CheckboxField>\n          )}\n          {(titleContent || (!this.round && info.nested)) && (\n            <RowTsx.Title\n              ref={(element) => title = element}\n              rowClass={!this.round && info.nested ? 'with-delimiter' : undefined}\n            >\n              {titleContent}\n              {!this.round && info.nested && (\n                <>\n                  {' '}\n                  <b ref={(element) => nestedCounter = info.nestedCounter = element} class=\"accordion-counter\" />\n                  {' '}\n                  <IconTsx icon=\"down\" class=\"accordion-icon\" />\n                </>\n              )}\n            </RowTsx.Title>\n          )}\n          {subtitleContent && (\n            <RowTsx.Subtitle>{subtitleContent}</RowTsx.Subtitle>\n          )}\n          {this.round && info.nested && (\n            <RowTsx.RightContent\n              ref={(element) => rightContent = element}\n              class=\"accordion-right-button\"\n            >\n              {nestedRightButtonIcon && (\n                <>\n                  <IconTsx icon={nestedRightButtonIcon} />\n                  {' '}\n                </>\n              )}\n              <b ref={(element) => nestedCounter = info.nestedCounter = element} class=\"accordion-counter\" />\n              {' '}\n              <IconTsx icon=\"down\" class=\"accordion-icon\" />\n            </RowTsx.RightContent>\n          )}\n        </RowTsx>\n      );\n\n      return unwrapSolidElement(element);\n    });\n\n    const dispose = () => {\n      if(disposed) return;\n\n      disposed = true;\n      disposeRoot();\n    };\n    // same rule as `rowTsxController`: a Solid root follows the render lifetime, so prefer the\n    // middleware and fall back to the listenerSetter only when the owner has none\n    if(this.middleware) {\n      this.middleware.onDestroy(dispose);\n    } else {\n      this.listenerSetter.addCleanup(dispose);\n    }\n\n    const row = info.row = {\n      container: rowElement as HTMLElement,\n      title,\n      toggleDisability: (disable = !disabled()) => {\n        setDisabled(disable);\n        return () => setDisabled(!disable);\n      }\n    };\n\n    if(info.restrictionText) {\n      info.checkboxField.input.disabled = true;\n\n      if(!info.nested) attachClickEvent(row.container, (e) => {\n        toastNew({langPackKey: info.restrictionText});\n      }, {listenerSetter: this.listenerSetter});\n    }\n\n    const nodes: HTMLElement[] = [row.container];\n    if(info.nested) {\n      const container = accordion = document.createElement('div');\n      container.classList.add('accordion');\n      const _info = info;\n      info.nested.forEach((info) => {\n        info.nestedTo ??= _info;\n        container.append(...this.createField(info, true).nodes);\n      });\n      nodes.push(container);\n\n      this.setNestedCounter(info);\n\n      // * will control it myself, otherwise on mobiles it will be toggled everytime\n      checkboxField.input.disabled = true;\n      checkboxField.setValueSilently(this.getNestedCheckedLength(info) === info.nested.length);\n\n      info.toggleWith ??= {checked: info.nested, unchecked: info.nested};\n    }\n\n    if(info.toggleWith || info.nestedTo) {\n      const processToggleWith = info.toggleWith ? (info: CheckboxFieldsField) => {\n        const {toggleWith, nested} = info;\n        const value = info.checkboxField.checked;\n        const arr = value ? toggleWith.checked : toggleWith.unchecked;\n        if(!arr) {\n          return;\n        }\n\n        const other = this.fields.filter((i) => arr.includes(i));\n        other.forEach((info) => {\n          if(info.restrictionText) {\n            return;\n          }\n\n          info.checkboxField.setValueSilently(value);\n          if(info.nestedTo && !nested) {\n            this.setNestedCounter(info.nestedTo);\n          }\n\n          if(info.toggleWith) {\n            processToggleWith(info);\n          }\n        });\n\n        if(info.nested) {\n          this.setNestedCounter(info);\n        }\n      } : undefined;\n\n      const processNestedTo = info.nestedTo ? () => {\n        const length = this.getNestedCheckedLength(info.nestedTo);\n        info.nestedTo.checkboxField.setValueSilently(length === info.nestedTo.nested.length);\n        this.setNestedCounter(info.nestedTo, length);\n      } : undefined;\n\n      this.listenerSetter.add(info.checkboxField.input)('change', () => {\n        processToggleWith?.(info);\n        processNestedTo?.();\n        this.onAnyChange?.();\n      });\n    } else if(this.onAnyChange && !info.nested) {\n      this.listenerSetter.add(info.checkboxField.input)('change', () => {\n        this.onAnyChange();\n      });\n    }\n\n    this.onRowCreation?.(row, info as K);\n\n    return {row, nodes};\n  }\n\n  protected getNestedCheckedLength(info: CheckboxFieldsField) {\n    return info.nested.reduce((acc, v) => acc + +v.checkboxField.checked, 0);\n  }\n\n  public setNestedCounter(info: CheckboxFieldsField, count = this.getNestedCheckedLength(info)) {\n    if(info.setNestedCounter) {\n      info.setNestedCounter(count);\n      return;\n    }\n\n    info.nestedCounter.textContent = this.round ? '' + info.nested.length : `${count}/${info.nested.length}`;\n  }\n}\n","import copy from '@helpers/object/copy';\nimport {ChatBannedRights, Chat} from '@layer';\n\nexport default function combineParticipantBannedRights(chat: Chat.channel, rights: ChatBannedRights) {\n  if(chat.default_banned_rights) {\n    rights = copy(rights);\n    const defaultRights = chat.default_banned_rights.pFlags;\n    for(const i in defaultRights) {\n      // @ts-ignore\n      rights.pFlags[i] = defaultRights[i];\n    }\n  }\n\n  return rights;\n}\n","import type {ChatRights} from '@appManagers/appChatsManager';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {ChannelParticipant, Chat, ChatAdminRights, ChatBannedRights} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport combineParticipantBannedRights from '@appManagers/utils/chats/combineParticipantBannedRights';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport {LangPackKey} from '@lib/langPack';\nimport SliderSuperTab from '@components/sliderTab';\nimport CheckboxFields, {CheckboxFieldsField} from '@components/checkboxFields';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {createEffect, createRoot, createSignal, onCleanup} from 'solid-js';\nimport {createStore} from 'solid-js/store';\nimport deepEqual from '@helpers/object/deepEqual';\nimport ButtonIcon from '@components/buttonIcon';\nimport throttle from '@helpers/schedulers/throttle';\nimport {PopupPeerOptions} from '@components/popups/peer';\nimport confirmationPopup, {ConfirmationPopupRejectReason} from '@components/confirmationPopup';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {isParticipantCreator} from '@lib/appManagers/utils/chats/isParticipantAdmin';\nimport {CHAT_LEGACY_ADMIN_RIGHTS} from '@lib/appManagers/utils/chats/constants';\nimport {BANNED_RIGHTS_UNTIL_FOREVER} from '@lib/appManagers/constants';\n\ntype PermissionsCheckboxFieldsField = CheckboxFieldsField & {\n  flags: ChatRights[],\n  exceptionText: LangPackKey\n};\n\nexport type AdministratorRightsCheckboxFieldsField = CheckboxFieldsField & {\n  flags: ChatRights[]\n};\n\nexport class ChatPermissions extends CheckboxFields<PermissionsCheckboxFieldsField> {\n  protected chat: Chat.chat | Chat.channel;\n  protected rights: ChatBannedRights.chatBannedRights;\n  protected defaultBannedRights: ChatBannedRights.chatBannedRights;\n  protected untilDate: number;\n\n  constructor(private options: {\n    chatId: ChatId,\n    listenerSetter: ListenerSetter,\n    appendTo: HTMLElement,\n    participant?: ChannelParticipant.channelParticipantBanned,\n    forChat?: boolean,\n    onSomethingChanged?: () => void\n  }, private managers: AppManagers) {\n    super({\n      listenerSetter: options.listenerSetter,\n      fields: [],\n      asRestrictions: true\n    });\n\n    this.construct();\n  }\n\n  public async construct() {\n    const options = this.options;\n    const peerId = options.chatId.toPeerId(true);\n    const chat = this.chat = apiManagerProxy.getChat(options.chatId) as Chat.chat | Chat.channel;\n    const isForum = apiManagerProxy.isForum(peerId);\n    const defaultBannedRights = this.defaultBannedRights = chat.default_banned_rights;\n    const rights = this.rights = options.participant ? combineParticipantBannedRights(chat as Chat.channel, options.participant.banned_rights) : defaultBannedRights;\n    this.untilDate = rights.until_date || BANNED_RIGHTS_UNTIL_FOREVER;\n\n    const mediaNested: PermissionsCheckboxFieldsField[] = [\n      {flags: ['send_photos'], text: 'UserRestrictionsSendPhotos', exceptionText: 'UserRestrictionsNoSendPhotos'},\n      {flags: ['send_videos'], text: 'UserRestrictionsSendVideos', exceptionText: 'UserRestrictionsNoSendVideos'},\n      {flags: ['send_stickers', 'send_gifs'], text: 'UserRestrictionsSendStickers', exceptionText: 'UserRestrictionsNoSendStickers'},\n      {flags: ['send_audios'], text: 'UserRestrictionsSendMusic', exceptionText: 'UserRestrictionsNoSendMusic'},\n      {flags: ['send_docs'], text: 'UserRestrictionsSendFiles', exceptionText: 'UserRestrictionsNoSendDocs'},\n      {flags: ['send_voices'], text: 'UserRestrictionsSendVoices', exceptionText: 'UserRestrictionsNoSendVoice'},\n      {flags: ['send_roundvideos'], text: 'UserRestrictionsSendRound', exceptionText: 'UserRestrictionsNoSendRound'},\n      {flags: ['embed_links'], text: 'UserRestrictionsEmbedLinks', exceptionText: 'UserRestrictionsNoEmbedLinks'},\n      {flags: ['send_polls'], text: 'UserRestrictionsSendPolls', exceptionText: 'UserRestrictionsNoSendPolls'}\n    ];\n\n    let v: PermissionsCheckboxFieldsField[] = [\n      {flags: ['send_plain'], text: 'UserRestrictionsSend', exceptionText: 'UserRestrictionsNoSend'},\n      {flags: ['send_media'], text: 'UserRestrictionsSendMedia', exceptionText: 'UserRestrictionsNoSendMedia', nested: mediaNested},\n      {flags: ['invite_users'], text: 'UserRestrictionsInviteUsers', exceptionText: 'UserRestrictionsNoInviteUsers'},\n      {flags: ['pin_messages'], text: 'UserRestrictionsPinMessages', exceptionText: 'UserRestrictionsNoPinMessages'},\n      isForum && {flags: ['manage_topics'], text: 'CreateTopicsPermission', exceptionText: 'UserRestrictionsNoChangeInfo'},\n      {flags: ['change_info'], text: 'UserRestrictionsChangeInfo', exceptionText: 'UserRestrictionsNoChangeInfo'}\n    ];\n    v = v.filter(Boolean);\n\n\n    const map: {[action in ChatRights]?: PermissionsCheckboxFieldsField} = {};\n    v.push(...mediaNested);\n    v.forEach((info) => {\n      const mainFlag = info.flags[0];\n      map[mainFlag] = info;\n      info.checked = hasRights(chat, mainFlag, rights);\n    });\n\n    mediaNested.forEach((info) => info.nestedTo = map.send_media);\n    map.send_media.toggleWith = {unchecked: mediaNested, checked: mediaNested};\n    map.embed_links.toggleWith = {checked: [map.send_plain]};\n    map.send_plain.toggleWith = {unchecked: [map.embed_links]};\n\n    this.fields = v;\n\n    for(const info of this.fields) {\n      if(!options.forChat && defaultBannedRights.pFlags[info.flags[0] as keyof typeof defaultBannedRights['pFlags']]) {\n        info.restrictionText = 'UserRestrictionsDisabled';\n      } else if(getPeerActiveUsernames(chat as Chat.channel)[0] && (info.flags.includes('pin_messages') || info.flags.includes('change_info'))) {\n        info.restrictionText = options.participant ? 'UserRestrictionsDisabled' : 'EditCantEditPermissionsPublic';\n      }\n    }\n\n    for(const info of this.fields) {\n      if(info.nestedTo) {\n        continue;\n      }\n\n      const {nodes} = this.createField(info);\n      options.appendTo.append(...nodes);\n    }\n\n    this.fields.forEach((field) => {\n      field.checkboxField.listenerSetter.add(field.checkboxField.input)('change', () => {\n        this.options?.onSomethingChanged?.();\n      });\n    });\n  }\n\n  public setUntilDate(untilDate: number) {\n    this.untilDate = untilDate;\n    this.options.onSomethingChanged?.();\n  }\n\n  public takeOut() {\n    const rights: ChatBannedRights = {\n      _: 'chatBannedRights',\n      until_date: this.untilDate,\n      pFlags: {}\n    };\n\n    const IGNORE_FLAGS: Set<ChatRights> = new Set([\n      'send_media'\n    ]);\n    for(const info of this.fields) {\n      const banned = !info.checkboxField.checked;\n      if(!banned) {\n        continue;\n      }\n\n      info.flags.forEach((flag) => {\n        if(IGNORE_FLAGS.has(flag)) {\n          return;\n        }\n\n        // @ts-ignore\n        rights.pFlags[flag] = true;\n      });\n    }\n\n    if(this.rights?.pFlags.manage_linked_peers) {\n      rights.pFlags.manage_linked_peers = true;\n    }\n\n    return rights;\n  }\n}\n\nexport class ChatAdministratorRights extends CheckboxFields<AdministratorRightsCheckboxFieldsField> {\n  protected rights: ChatAdminRights;\n  protected defaultBannedRights: ChatAdminRights;\n  protected restrictionText: LangPackKey;\n\n  protected static CHAT_LEGACY_ADMIN_RIGHTS: ChatAdminRights = {\n    _: 'chatAdminRights',\n    pFlags: {\n      change_info: true,\n      delete_messages: true,\n      ban_users: true,\n      invite_users: true,\n      pin_messages: true,\n      manage_call: true\n    }\n  };\n\n  constructor(private options: {\n    chatId: ChatId,\n    listenerSetter: ListenerSetter,\n    appendTo: HTMLElement,\n    participant?: ChannelParticipant.channelParticipantAdmin | ChannelParticipant.channelParticipantCreator,\n    rights?: ChatAdminRights,\n    chat?: Chat,\n    canEdit?: boolean,\n    onSomethingChanged?: () => void,\n    fields?: AdministratorRightsCheckboxFieldsField[],\n    canGrant?: (right: ChatRights) => boolean,\n    preserveUnhandledRights?: boolean\n  }) {\n    super({\n      listenerSetter: options.listenerSetter,\n      fields: [],\n      asRestrictions: true\n    });\n\n    this.construct();\n  }\n\n  public construct() {\n    const options = this.options;\n    const chat = options.chat as Chat.chat | Chat.channel;\n    const isBroadcast = !!(chat as Chat.channel)?.pFlags.broadcast;\n    const isForum = !!(chat as Chat.channel)?.pFlags.forum;\n    const rights = this.rights = options.rights ?? (options.participant ? options.participant.admin_rights : undefined);\n\n    const manageMessagesNested: AdministratorRightsCheckboxFieldsField[] = isBroadcast && [\n      {flags: ['post_messages'], text: 'EditAdminPostMessages'},\n      {flags: ['edit_messages'], text: 'EditAdminEditMessages'},\n      {flags: ['delete_messages'], text: 'EditAdminDeleteMessages'}\n    ];\n\n    const manageStoriesNested: AdministratorRightsCheckboxFieldsField[] = isBroadcast && [\n      {flags: ['post_stories'], text: 'AdminRights.PostStories'},\n      {flags: ['edit_stories'], text: 'AdminRights.EditStories'},\n      {flags: ['delete_stories'], text: 'AdminRights.DeleteStories'}\n    ];\n\n    const isCreator = isParticipantCreator(options.participant);\n    const manageMessagesNestedKey: ChatRights = 'post_messages_nested' as any;\n    const manageStoriesNestedKey: ChatRights = 'post_stories_nested' as any;\n    let v: AdministratorRightsCheckboxFieldsField[] = options.fields?.map((field) => ({\n      ...field,\n      flags: [...field.flags]\n    })) || [\n      {flags: ['change_info'], text: isBroadcast ? 'EditAdminChangeChannelInfo' : 'EditAdminChangeGroupInfo'},\n      isBroadcast && {flags: [manageMessagesNestedKey], text: 'AdminRights.ManageMessages', nested: manageMessagesNested},\n      isBroadcast && {flags: [manageStoriesNestedKey], text: 'AdminRights.ManageStories', nested: manageStoriesNested},\n      !isBroadcast && {flags: ['delete_messages'], text: isBroadcast ? 'EditAdminDeleteMessages' : 'EditAdminGroupDeleteMessages'},\n      !isBroadcast && {flags: ['ban_users'], text: 'EditAdminBanUsers'},\n      !isBroadcast && {flags: ['invite_users'], text: 'EditAdminAddUsersViaLink'},\n      !isBroadcast && {flags: ['pin_messages'], text: 'EditAdminPinMessages'},\n      isForum && {flags: ['manage_topics'], text: 'ManageTopicsPermission'},\n      {flags: ['manage_call'], text: isBroadcast ? 'StartVoipChatPermission' : 'Channel.EditAdmin.ManageCalls'},\n      isBroadcast && {flags: ['invite_users'], text: 'Channel.EditAdmin.PermissionInviteSubscribers'},\n      isBroadcast && {flags: ['manage_direct_messages'], text: 'Channel.EditAdmin.ManageDirectMessages'},\n      !isBroadcast && {flags: ['anonymous'], text: 'EditAdminSendAnonymously', checked: rights ? undefined : false},\n      {flags: ['add_admins'], text: 'EditAdminAddAdmins', checked: rights ? undefined : isCreator}\n    ];\n\n    const map: {[action in ChatRights]?: AdministratorRightsCheckboxFieldsField} = {};\n    v = v.filter(Boolean);\n    if(manageMessagesNested) v.push(...manageMessagesNested);\n    if(manageStoriesNested) v.push(...manageStoriesNested);\n    v.forEach((info) => {\n      const mainFlag = info.flags[0];\n      map[mainFlag] = info;\n      info.checked ??= options.canGrant ?\n        !!rights?.pFlags[mainFlag as keyof ChatAdminRights['pFlags']] :\n        hasRights(chat, mainFlag, rights);\n    });\n\n    if(manageMessagesNested) {\n      manageMessagesNested.forEach((info) => info.nestedTo = map[manageMessagesNestedKey]);\n      map[manageMessagesNestedKey].toggleWith = {unchecked: manageMessagesNested, checked: manageMessagesNested};\n    }\n\n    if(manageStoriesNested) {\n      manageStoriesNested.forEach((info) => info.nestedTo = map[manageStoriesNestedKey]);\n      map[manageStoriesNestedKey].toggleWith = {unchecked: manageStoriesNested, checked: manageStoriesNested};\n    }\n\n    this.fields = v;\n\n    const CREATOR_EXCEPTIONS: Set<ChatRights> = new Set([\n      'anonymous'\n    ]);\n\n    for(const info of this.fields) {\n      const mainFlag = info.flags[0];\n      if(!options.canEdit) {\n        info.restrictionText = 'EditAdminCantEdit';\n      } else if(options.canGrant ?\n        !options.canGrant(mainFlag) :\n        (isCreator && !CREATOR_EXCEPTIONS.has(mainFlag as ChatRights)) || !hasRights(chat, mainFlag)\n      ) {\n        info.restrictionText = 'EditCantEditPermissions';\n      }\n    }\n\n    for(const info of this.fields) {\n      if(info.nestedTo) {\n        continue;\n      }\n\n      const {nodes} = this.createField(info);\n      options.appendTo.append(...nodes);\n    }\n\n    this.fields.forEach((field) => {\n      field.checkboxField.listenerSetter.add(field.checkboxField.input)('change', () => {\n        this.options?.onSomethingChanged?.();\n      });\n    });\n  }\n\n  public takeOut() {\n    let rights: ChatAdminRights = {\n      _: 'chatAdminRights',\n      pFlags: this.options.preserveUnhandledRights ?\n        {...this.rights?.pFlags} :\n        {}\n    };\n\n    for(const info of this.fields) {\n      info.flags.forEach((flag) => {\n        delete rights.pFlags[flag as keyof ChatAdminRights['pFlags']];\n      });\n      if(!info.checkboxField.checked) {\n        continue;\n      }\n\n      info.flags.forEach((flag) => {\n        // @ts-ignore\n        rights.pFlags[flag] = true;\n      });\n    }\n\n    if(\n      this.rights?.pFlags.manage_linked_peers &&\n      !this.fields.some((field) => {\n        return field.flags.includes('manage_linked_peers');\n      })\n    ) {\n      rights.pFlags.manage_linked_peers = true;\n    }\n\n    // * fix missing flags\n    if(\n      this.options.chat?._ === 'chat' &&\n      deepEqual(rights, ChatAdministratorRights.CHAT_LEGACY_ADMIN_RIGHTS)\n    ) {\n      rights = CHAT_LEGACY_ADMIN_RIGHTS;\n    }\n\n    // Keep the participant an administrator even when every visible right is\n    // disabled. An actually empty rights object is reserved for dismissal.\n    rights.pFlags.other = true;\n\n    return rights;\n  }\n}\n\ntype CreateSolidTabStateProps = {\n  tab: SliderSuperTab,\n  save: () => Promise<any>,\n  alwaysShowSave?: boolean,\n  unsavedConfirmationProps?: Partial<Pick<Parameters<typeof confirmationPopup>[0], 'titleLangKey' | 'descriptionLangKey' | 'button'>>\n};\n\nexport const createSolidTabState = <StateStore extends object>({tab, save, alwaysShowSave, unsavedConfirmationProps = {}}: CreateSolidTabStateProps) => createRoot((dispose) => {\n  tab.middlewareHelper.get().onDestroy(dispose);\n\n  const initialState: StateStore = {} as any;\n\n  const [store, set] = createStore<StateStore>({} as StateStore);\n  const [saveIcon, setSaveIcon] = createSignal<HTMLElement>(ButtonIcon('check primary appear-zoom'));\n  const [saving, setSaving] = createSignal(false);\n  const [valid, setValid] = createSignal(true);\n\n  const [hasChanges, setHasChanges] = createSignal(false);\n  const throttledSetHasChanges = throttle(setHasChanges, 200, true);\n\n  createEffect(() => {\n    throttledSetHasChanges(!deepEqual(store, initialState));\n  });\n\n  createEffect(() => {\n    if(!saveIcon()) return;\n\n    saveIcon().classList.toggle(\n      'appear-zoom--active',\n      hasChanges() || !!alwaysShowSave\n    );\n  });\n\n  createEffect(() => {\n    toggleDisability(saveIcon(), !valid() || saving());\n  });\n\n  // createEffect(() => {\n  //   ({...store});\n  //   console.log('{...store} :>> ', {...unwrap(store)});\n  // });\n\n  const initiateSaving = async() => {\n    setSaving(true);\n    try {\n      await save();\n      dispose();\n      tab.close();\n    } catch(err) {\n      setSaving(false);\n      throw err;\n    }\n  };\n\n  const detach = attachClickEvent(saveIcon(), initiateSaving);\n  onCleanup(detach);\n\n  tab.isConfirmationNeededOnClose = async() => {\n    if(!hasChanges() || saving()) return;\n\n    const saveButton: PopupPeerOptions['buttons'][number] = unsavedConfirmationProps.button || {\n      langKey: 'Save'\n    };\n\n    try {\n      await confirmationPopup({\n        button: saveButton,\n        buttons: [\n          saveButton,\n          {isCancel: true, langKey: 'Discard'}\n        ],\n        titleLangKey: 'UnsavedChanges',\n        descriptionLangKey: 'UnsavedChangesDescription',\n        ...unsavedConfirmationProps,\n        rejectWithReason: true\n      });\n\n      await initiateSaving();\n    } catch(_reason: any) {\n      const reason: ConfirmationPopupRejectReason = _reason;\n\n      if(reason !== 'canceled') {\n        throw new Error();\n      }\n    }\n  };\n\n  onCleanup(() => {\n    tab.isConfirmationNeededOnClose = undefined;\n  });\n\n  return {\n    setInitial: (state: Partial<StateStore>) => {\n      Object.assign(initialState, state);\n      set(state as any);\n    },\n\n    store,\n    set,\n    saveIcon,\n    // setSaveIcon,\n\n    saving,\n\n    valid,\n    setValid,\n\n    hasChanges,\n\n    dispose,\n\n    save: initiateSaving\n  };\n});\n","import {ChannelParticipant, Chat, ChatParticipant} from '@layer';\nimport {isParticipantCreator} from '@lib/appManagers/utils/chats/isParticipantAdmin';\n\nexport default function canEditAdmin(chat: Chat, participant: ChatParticipant | ChannelParticipant, myId: PeerId) {\n  const isCreator = isParticipantCreator(participant);\n  const myUserId = myId.toUserId();\n  const promotedBy = (participant as ChannelParticipant.channelParticipantAdmin)?.promoted_by ||\n    (participant as ChatParticipant.chatParticipant)?.inviter_id;\n  return !!(chat as Chat.channel).pFlags.creator ||\n    (!isCreator && (!promotedBy || promotedBy === myUserId));\n}\n","import PopupElement, {addCancelButton} from '.';\nimport filterUnique from '@helpers/array/filterUnique';\nimport {Chat, ChatFull, Message, Reaction} from '@layer';\nimport I18n, {FormatterArguments, i18n, LangPackKey} from '@lib/langPack';\nimport Section from '@components/section';\nimport StackedAvatars from '@components/stackedAvatars';\nimport {createEffect, createSignal, Show} from 'solid-js';\nimport CheckboxFields, {CheckboxFieldsField} from '@components/checkboxFields';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport flatten from '@helpers/array/flatten';\nimport {avatarNew} from '@components/avatarNew';\nimport PeerTitle from '@components/peerTitle';\nimport Row, {createRowTitle} from '@components/rowTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport classNames from '@helpers/string/classNames';\nimport {ChatPermissions} from '@components/sidebarRight/tabs/groupPermissions/sharedPermissions';\nimport {animate} from '@helpers/animation';\nimport canEditAdmin from '@appManagers/utils/chats/canEditAdmin';\nimport rootScope from '@lib/rootScope';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport type {AppManagers} from '@lib/managers';\n\nconst className = 'popup-delete-megagroup-messages';\n\ntype DeleteCheckboxFieldsField = CheckboxFieldsField & {\n  peerId?: PeerId,\n  action:\n    'report' |\n    'delete' |\n    'deleteReactions' |\n    'deleteOptions' |\n    'ban' |\n    'communityBan',\n  peerRow?: boolean\n};\n\ntype DeleteAction = Exclude<DeleteCheckboxFieldsField['action'], 'deleteOptions'>;\n\ntype ModerateOptions = {\n  reportSpam: boolean,\n  reportReaction: boolean,\n  deleteAllMessages: boolean,\n  deleteAllReactions: boolean,\n  banOrRestrict: boolean,\n  communityId?: ChatId,\n  communityChatsCount?: number\n};\n\nconst getNoModerateOptions = (): ModerateOptions => ({\n  reportSpam: false,\n  reportReaction: false,\n  deleteAllMessages: false,\n  deleteAllReactions: false,\n  banOrRestrict: false\n});\n\nfunction getCommunityId(managers: AppManagers, peerId: PeerId) {\n  return managers.appCommunitiesManager?.getPeerLinkedCommunityId(peerId);\n}\n\nasync function getCommunityModerateOptions(\n  managers: AppManagers,\n  peerId: PeerId\n): Promise<Partial<ModerateOptions>> {\n  const communitiesManager = managers.appCommunitiesManager;\n  if(!communitiesManager) {\n    return {};\n  }\n\n  const communityId = await getCommunityId(managers, peerId);\n  const canBanFromCommunity = !!communityId &&\n    await communitiesManager.hasRights(communityId, 'ban_users')\n    .catch(() => false);\n  if(!canBanFromCommunity) {\n    return {};\n  }\n\n  const communityFull = await Promise.resolve(managers.appProfileManager\n  .getChatFull(communityId))\n  .catch((): undefined => undefined);\n  return {\n    communityId,\n    communityChatsCount: communityFull?._ === 'communityFull' ?\n      communityFull.linked_peers.length :\n      undefined\n  };\n}\n\ntype ModerateMessage = Message.message | Message.messageService;\n\nexport type ModerateReactionEntry = {\n  message: ModerateMessage,\n  participantPeerId: PeerId,\n  knownReaction?: Reaction\n};\n\nexport type PopupDeleteMegagroupMessagesOptions = ({\n  messages: ModerateMessage[],\n  reaction?: never\n} | {\n  messages?: never,\n  reaction: ModerateReactionEntry\n}) & {\n  onConfirm?: () => void\n};\n\nexport default class PopupDeleteMegagroupMessages extends PopupElement {\n  private messages: ModerateMessage[];\n  private reaction: ModerateReactionEntry;\n  private fields: DeleteCheckboxFieldsField[];\n  private restricting: boolean;\n  private chatPermissions: ChatPermissions;\n  private onConfirm: () => void;\n  private reportReaction: boolean;\n\n  private updateReactionTitle() {\n    if(!this.reaction || !this.fields) {\n      return;\n    }\n\n    const isChecked = (action: DeleteAction) => this.fields.some((field) =>\n      field.peerId === this.reaction.participantPeerId &&\n      field.action === action &&\n      field.checkboxField?.checked\n    );\n    const key: LangPackKey = isChecked('delete') ?\n      'DeleteAllMessages' :\n      (isChecked('deleteReactions') ? 'DeleteAllReactions' : 'DeleteReaction');\n    this.title.replaceChildren(i18n(key));\n  }\n\n  constructor(options: PopupDeleteMegagroupMessagesOptions) {\n    const reaction = 'reaction' in options ? options.reaction : undefined;\n    const messages = 'messages' in options ? options.messages : [];\n    super(className, {\n      body: true,\n      scrollable: true,\n      title: reaction ? i18n('DeleteReaction') : i18n('DeleteOptionsTitle', [messages.length]),\n      overlayClosable: true,\n      buttons: addCancelButton([{\n        langKey: 'DeleteProceedBtn',\n        isDanger: true,\n        callback: () => this.onConfirmClick(),\n        iconLeft: 'delete_filled'\n      }])\n    });\n\n    this.messages = messages;\n    this.reaction = reaction;\n    this.onConfirm = options.onConfirm;\n\n    this.construct();\n  }\n\n  private async onConfirmClick() {\n    const byPeers = this.fields.reduce((acc, field) => {\n      if(field.peerId === undefined || field.action === 'deleteOptions' || !field.checkboxField.checked) {\n        return acc;\n      }\n\n      let set = acc.get(field.peerId);\n      if(!set) {\n        acc.set(field.peerId, set = new Set());\n      }\n\n      set.add(field.action);\n      return acc;\n    }, new Map<PeerId, Set<DeleteAction>>());\n\n    const mids = this.messages.length ?\n      this.messages.map(({mid}) => mid) :\n      [this.reaction.message.mid];\n    const peerId = this.reaction?.message.peerId ?? this.messages[0].peerId;\n    const deleteOriginReactions = !!this.reaction &&\n      byPeers.get(this.reaction.participantPeerId)?.has('deleteReactions');\n    const {restricting, managers} = this;\n    for(const [fromId, actions] of byPeers) {\n      if(actions.has('communityBan')) {\n        const communityId = await getCommunityId(managers, peerId);\n        if(!communityId || !await this.banFromCommunity(communityId, fromId)) {\n          return false;\n        }\n      }\n\n      const promises: Promise<any>[] = [];\n      if(actions.has('ban') && restricting) {\n        const rights = this.chatPermissions.takeOut();\n        promises.push(managers.appChatsManager.editBanned(peerId.toChatId(), fromId, rights));\n      } else if(actions.has('ban')) {\n        promises.push(managers.appChatsManager.kickFromChannel(peerId.toChatId(), fromId));\n      }\n\n      if(actions.has('report')) {\n        if(this.reaction && this.reportReaction && fromId === this.reaction.participantPeerId) {\n          promises.push(managers.appReactionsManager.reportParticipantReaction({\n            peerId,\n            mid: this.reaction.message.mid,\n            participantPeerId: fromId\n          }));\n        } else {\n          promises.push(managers.appMessagesManager.reportSpamMessages(peerId, fromId, mids));\n        }\n      }\n\n      if(actions.has('delete')) {\n        promises.push(managers.appMessagesManager.doFlushHistory({peerId, justClear: false, revoke: true, participantPeerId: fromId}));\n      }\n\n      if(actions.has('deleteReactions')) {\n        promises.push(managers.appReactionsManager.deleteParticipantReactions({\n          peerId,\n          participantPeerId: fromId,\n          ...(this.reaction?.participantPeerId === fromId ? {\n            originMid: this.reaction.message.mid,\n            knownReaction: this.reaction.knownReaction\n          } : {})\n        }));\n      }\n    }\n\n    if(this.reaction && !deleteOriginReactions) {\n      managers.appReactionsManager.deleteParticipantReaction({\n        peerId,\n        mid: this.reaction.message.mid,\n        participantPeerId: this.reaction.participantPeerId,\n        knownReaction: this.reaction.knownReaction\n      });\n    }\n\n    if(this.messages.length) {\n      managers.appMessagesManager.deleteMessages(peerId, mids, true);\n    }\n\n    this.onConfirm?.();\n    return true;\n  }\n\n  private async banFromCommunity(\n    communityId: ChatId,\n    participantId: PeerId\n  ) {\n    try {\n      const joinedChats = await this.managers.appCommunitiesManager\n      .getParticipantJoinedChats({communityId, participantId});\n      if(joinedChats.creator_chat_ids.length) {\n        const title = await getPeerTitle({\n          peerId: participantId,\n          plainText: true,\n          onlyFirstName: true\n        });\n        try {\n          await confirmationPopup({\n            titleLangKey: 'Community.BanWarningTitle',\n            descriptionLangKey: 'Community.BanWarning',\n            descriptionLangArgs: [\n              title,\n              joinedChats.creator_chat_ids.length\n            ],\n            button: {\n              langKey: 'Community.Ban',\n              isDanger: true\n            }\n          });\n        } catch{\n          return false;\n        }\n      }\n\n      await this.managers.appCommunitiesManager.toggleParticipantBanned({\n        communityId,\n        participantId\n      });\n      toastNew({\n        langPackKey: 'Community.Banned',\n        langPackArguments: [\n          await getPeerTitle({\n            peerId: participantId,\n            plainText: true,\n            onlyFirstName: true\n          })\n        ]\n      });\n      return true;\n    } catch(error) {\n      console.error('ban participant from community error', error);\n      toastNew({langPackKey: 'Error.AnError'});\n      return false;\n    }\n  }\n\n  private async getModerateOptions(peerId: PeerId): Promise<ModerateOptions> {\n    if(!this.reaction) {\n      return {\n        reportSpam: true,\n        reportReaction: false,\n        deleteAllMessages: true,\n        deleteAllReactions: true,\n        banOrRestrict: true,\n        ...await getCommunityModerateOptions(this.managers, peerId)\n      };\n    }\n\n    const participantPeerId = this.reaction.participantPeerId;\n    if(participantPeerId === peerId || participantPeerId === rootScope.myId) {\n      return getNoModerateOptions();\n    }\n\n    const chatId = peerId.toChatId();\n    if(participantPeerId.isAnyChat()) {\n      const participantFull = await this.managers.appProfileManager\n      .getChatFull(participantPeerId.toChatId())\n      .catch((): undefined => undefined);\n      if((participantFull as ChatFull.channelFull)?.linked_chat_id === chatId) {\n        return getNoModerateOptions();\n      }\n    }\n\n    const [chat, canDeleteMessages, canBanUsers, isPublic] = await Promise.all([\n      this.managers.appChatsManager.getChat(chatId) as Promise<Chat>,\n      this.managers.appChatsManager.hasRights(chatId, 'delete_messages'),\n      this.managers.appChatsManager.hasRights(chatId, 'ban_users'),\n      this.managers.appChatsManager.isPublic(chatId)\n    ]);\n    const isChannel = chat?._ === 'channel';\n    const isMegagroup = isChannel && !!chat.pFlags.megagroup;\n    let banOrRestrict = false;\n\n    if(isChannel && canBanUsers) {\n      if(chat.pFlags.creator) {\n        banOrRestrict = true;\n      } else {\n        const participant = await this.managers.appProfileManager.getParticipant(chatId, participantPeerId).catch((): undefined => undefined);\n        banOrRestrict = !!participant && canEditAdmin(chat, participant, rootScope.myId);\n      }\n    }\n\n    return {\n      reportSpam: isChannel,\n      reportReaction: isMegagroup && isPublic,\n      deleteAllMessages: isChannel && canDeleteMessages,\n      deleteAllReactions: canDeleteMessages,\n      banOrRestrict,\n      ...(isChannel ? await getCommunityModerateOptions(this.managers, peerId) : {})\n    };\n  }\n\n  private async construct() {\n    const fromPeerIds = this.reaction ?\n      [this.reaction.participantPeerId] :\n      filterUnique(this.messages.map(({fromId}) => fromId));\n    const peerId = this.reaction?.message.peerId ?? this.messages[0].peerId;\n\n    const stackedAvatars = new StackedAvatars({\n      middleware: this.middlewareHelper.get(),\n      avatarSize: 32\n    });\n\n    const loadPromises: Promise<any>[] = [];\n    stackedAvatars.render(fromPeerIds.slice(0, 3), loadPromises);\n    stackedAvatars.container.classList.add(`${className}-avatars`);\n    this.header.prepend(stackedAvatars.container);\n\n    const isSinglePeer = fromPeerIds.length === 1;\n    const moderateOptions = await this.getModerateOptions(peerId);\n    this.reportReaction = moderateOptions.reportReaction;\n    const deletePeerTitle = isSinglePeer ?\n      await wrapPeerTitle({peerId: fromPeerIds[0], onlyFirstName: true}) :\n      undefined;\n\n    const actions: {\n      action: DeleteAction,\n      peerIds: PeerId[],\n      langKey: LangPackKey,\n      langArgs?: FormatterArguments,\n      callback?: () => void\n    }[] = [];\n\n    if(moderateOptions.reportSpam) {\n      actions.push({\n        action: 'report',\n        peerIds: fromPeerIds,\n        langKey: 'DeleteReportSpam'\n      });\n    }\n\n    if(!isSinglePeer) {\n      if(moderateOptions.deleteAllMessages) {\n        actions.push({\n          action: 'delete',\n          peerIds: fromPeerIds,\n          langKey: 'DeleteAllMessages'\n        });\n      }\n\n      if(moderateOptions.deleteAllReactions) {\n        actions.push({\n          action: 'deleteReactions',\n          peerIds: fromPeerIds,\n          langKey: 'DeleteAllReactions'\n        });\n      }\n    }\n\n    if(moderateOptions.banOrRestrict) {\n      actions.push({\n        action: 'ban',\n        peerIds: fromPeerIds,\n        langKey: isSinglePeer ? 'DeleteBan' : 'DeleteBanUsers',\n        langArgs: isSinglePeer ? [await wrapPeerTitle({peerId: fromPeerIds[0], onlyFirstName: true})] : undefined\n      });\n    }\n\n    if(\n      isSinglePeer &&\n      fromPeerIds[0].isUser() &&\n      fromPeerIds[0] !== rootScope.myId &&\n      moderateOptions.communityId\n    ) {\n      actions.push({\n        action: 'communityBan',\n        peerIds: fromPeerIds,\n        langKey: 'Community.BanFromCommunity'\n      });\n    }\n\n    const nameStart = 'delete-fields';\n\n    const join = (...args: string[]) => [nameStart, ...args].join('-');\n\n    const wrap = (item: typeof actions[number]): DeleteCheckboxFieldsField[] => {\n      const nested = isSinglePeer ? [] : item.peerIds.map((peerId) => {\n        const name = join(item.action, '' + peerId);\n        const field: DeleteCheckboxFieldsField = {\n          action: item.action,\n          name,\n          peerId,\n          peerRow: true\n        };\n\n        return field;\n      });\n\n      return [{\n        action: item.action,\n        text: item.langKey,\n        textArgs: item.langArgs,\n        nested: isSinglePeer ? undefined : nested,\n        name: isSinglePeer ? join(item.action, '' + peerId) : join(item.action),\n        peerId: isSinglePeer ? item.peerIds[0] : undefined\n      }, ...nested];\n    };\n\n    const fields = flatten(actions.map(wrap));\n    if(isSinglePeer) {\n      const nested: DeleteCheckboxFieldsField[] = [];\n      if(moderateOptions.deleteAllMessages) {\n        nested.push({\n          action: 'delete',\n          text: 'DeleteAllMessages',\n          name: join('delete', '' + fromPeerIds[0]),\n          peerId: fromPeerIds[0]\n        });\n      }\n\n      if(moderateOptions.deleteAllReactions) {\n        nested.push({\n          action: 'deleteReactions',\n          text: 'DeleteAllReactions',\n          name: join('deleteReactions', '' + fromPeerIds[0]),\n          peerId: fromPeerIds[0]\n        });\n      }\n\n      if(nested.length) {\n        const useDeleteOptions = nested.length > 1;\n        const deleteOptionsField: DeleteCheckboxFieldsField = useDeleteOptions ? {\n          action: 'deleteOptions',\n          text: 'DeleteAllFrom',\n          textArgs: [deletePeerTitle],\n          nested,\n          name: join('deleteOptions'),\n          nestedRightButtonIcon: false\n        } : nested[0];\n        if(useDeleteOptions) {\n          deleteOptionsField.setNestedCounter = (count) => {\n            deleteOptionsField.nestedCounter.textContent = `${count}/${nested.length}`;\n          };\n        }\n\n        const reportIndex = fields.findIndex((field) => field.action === 'report');\n        fields.splice(reportIndex + 1, 0, deleteOptionsField, ...(useDeleteOptions ? nested : []));\n      }\n    }\n    this.fields = fields;\n\n    const checkboxFields = new CheckboxFields({\n      fields,\n      listenerSetter: this.listenerSetter,\n      middleware: this.middlewareHelper.get(),\n      round: true,\n      onRowCreation: (row, info) => {\n        if(!info.nestedTo || !info.peerRow) {\n          return;\n        }\n\n        row.container.classList.add(`${className}-row`);\n\n        const div = document.createElement('div');\n        div.classList.add(`${className}-row-title`);\n        const title = createRowTitle();\n\n        const avatar = avatarNew({\n          peerId: info.peerId,\n          middleware: this.middlewareHelper.get(),\n          size: 32\n        });\n\n        const peerTitle = new PeerTitle();\n        const peerTitlePromise = peerTitle.update({\n          peerId: info.peerId,\n          onlyFirstName: true\n        });\n\n        title.append(peerTitle.element);\n\n        loadPromises.push(avatar.readyThumbPromise, peerTitlePromise);\n        div.append(avatar.node, title);\n        row.container.append(div);\n      },\n      rightButtonIcon: 'group_filled',\n      onAnyChange: () => {\n        this.updateReactionTitle();\n        onAnyChange();\n      },\n      onExpand: () => {\n        const duration = 300;\n        const startTime = Date.now();\n        animate(() => {\n          this.scrollable.onScroll();\n          const progress = Math.min((Date.now() - startTime) / duration, 1);\n          return progress < 1;\n        });\n      }\n    });\n\n    const createdFields = fields.map((field) => {\n      const created = checkboxFields.createField(field);\n      return created?.nodes;\n    }).filter(Boolean);\n\n    const hasBanAction = fields.some((field) => field.action === 'ban');\n    let chatPermissionsContainer: HTMLElement;\n    if(hasBanAction) {\n      chatPermissionsContainer = document.createElement('div');\n      this.chatPermissions = new ChatPermissions({\n        appendTo: chatPermissionsContainer,\n        chatId: peerId.toChatId(),\n        listenerSetter: this.listenerSetter\n      }, this.managers);\n    }\n\n    let onAnyChange: () => void;\n    this.appendSolid(() => {\n      const [banning, setBanning] = createSignal<PeerId[]>([]);\n      const [communityBanning, setCommunityBanning] = createSignal(false);\n      const [collapsed, setCollapsed] = createSignal(true);\n      const collapsedName = () => collapsed() ?\n        (banning().length === 1 ? 'DeleteToggleRestrictUser' : 'DeleteToggleRestrictUsers') :\n        (banning().length === 1 ? 'DeleteToggleBanUser' : 'DeleteToggleBanUsers');\n\n      onAnyChange = () => {\n        const peerIds = fields\n        .filter((field) => field.action === 'ban' && field.checkboxField.checked && field.peerId)\n        .map(({peerId}) => peerId);\n        setBanning(peerIds);\n        setCommunityBanning(fields.some((field) => {\n          return field.action === 'communityBan' &&\n            field.checkboxField.checked;\n        }));\n      };\n\n      createEffect(() => {\n        if(!banning().length) {\n          setCollapsed(true);\n        }\n      });\n\n      createEffect(() => {\n        if(!hasBanAction) {\n          return;\n        }\n\n        const field = fields.find((field) => field.action === 'ban' && (isSinglePeer ? true : !field.peerId));\n        const i18nElement = I18n.weakMap.get(field.row.title.firstElementChild as HTMLElement) as I18n.IntlElement;\n        this.restricting = !collapsed();\n        i18nElement.compareAndUpdate({\n          key: collapsed() ?\n            (isSinglePeer ? 'DeleteBan' : 'DeleteBanUsers') :\n            (isSinglePeer ? 'DeleteRestrict' : 'DeleteRestrictUsers')\n        });\n      });\n\n      createEffect(() => {\n        if(!collapsed()) {\n          const duration = 300;\n          const startTime = Date.now();\n          const scrollPosition = this.scrollable.scrollPosition + this.scrollable.clientSize;\n          const scrollHeight = this.scrollable.scrollSize;\n          const path = 712 + scrollHeight - scrollPosition;\n          animate(() => {\n            const progress = Math.min((Date.now() - startTime) / duration, 1);\n            const newScrollPosition = scrollPosition + path * progress;\n            this.scrollable.scrollPosition = newScrollPosition;\n            return progress < 1;\n          });\n        }\n      });\n\n      // let lastRowRef: HTMLElement;\n      return (\n        <>\n          {!!createdFields.length &&\n            <Section name=\"DeleteAdditionalActions\" noShadow noDelimiter>\n              {flatten(createdFields)}\n            </Section>\n          }\n          <Show when={\n            communityBanning() &&\n            moderateOptions.communityChatsCount\n          }>\n            <Section noShadow noDelimiter>\n              <Row>\n                <Row.Subtitle>\n                  {i18n('Community.BanFromCommunityInfo', [\n                    moderateOptions.communityChatsCount\n                  ])}\n                </Row.Subtitle>\n              </Row>\n            </Section>\n          </Show>\n          {hasBanAction && <>\n            <Section\n              class={`${className}-permissions`}\n              name=\"UserRestrictionsCanDoUsers\"\n              nameArgs={[banning().length]}\n              noShadow\n              style={{\n                // 'max-height': collapsed() ? '0px' : ((chatPermissionsContainer.childElementCount - 1) * 48) + 40 + 'px'\n                'max-height': collapsed() ? '0px' : '712px'\n              }}\n            >\n              {chatPermissionsContainer}\n            </Section>\n            <Section\n              classList={{hide: !banning().length}}\n            >\n              <Row\n                ref={(e) => {\n                  // lastRowRef = e;\n                  e.classList.add('primary');\n                }}\n                clickable={() => {\n                  setCollapsed((v) => !v);\n                }}\n                color=\"primary\"\n              >\n                <Row.Title>\n                  <div class={classNames(`${className}-expand-row`, !collapsed() && 'is-expanded')}>\n                    {i18n(collapsedName())}\n                    <IconTsx icon=\"down\" class={`${className}-expand-row-icon`} />\n                  </div>\n                </Row.Title>\n              </Row>\n            </Section>\n          </>}\n        </>\n      );\n    });\n\n    await Promise.all(loadPromises);\n\n    this.show();\n  }\n}\n","import rootScope from '@lib/rootScope';\nimport PopupElement, {addCancelButton} from '.';\nimport PopupPeer, {PopupPeerButtonCallbackCheckboxes, PopupPeerOptions} from '@components/popups/peer';\nimport {ChatType} from '@components/chat/chatType';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {Message, MessageMedia} from '@layer';\nimport {formatFullSentTime} from '@helpers/date';\nimport tsNow from '@helpers/tsNow';\nimport PopupDeleteMegagroupMessages from '@components/popups/deleteMegagroupMessages';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport namedPromises from '@helpers/namedPromises';\nimport isEphemeralMessage from '@appManagers/utils/messages/isEphemeralMessage';\n\nexport default class PopupDeleteMessages {\n  constructor(\n    private peerId: PeerId,\n    private mids: number[],\n    private type: ChatType,\n    private onConfirm?: () => void,\n    private threadId?: number\n  ) {\n    this.construct();\n  }\n\n  private async construct() {\n    let {peerId, mids, type, onConfirm, threadId} = this;\n\n    mids = mids.slice();\n\n    const managers = PopupElement.MANAGERS;\n\n    const {peerTitleElement, isBot, messages} = await namedPromises({\n      peerTitleElement: wrapPeerTitle({peerId, threadId, onlyFirstName: true}),\n      isBot: managers.appPeersManager.isBot(peerId),\n      // scheduled mids belong to a separate storage; getMessageByPeer would read history and\n      // return undefined / another chat's message (breaking the megagroup-admin & giveaway checks)\n      messages: Promise.all(mids.map((mid) => type === ChatType.Scheduled ?\n        managers.appMessagesManager.getScheduledMessageByPeer(peerId, mid) :\n        managers.appMessagesManager.getMessageByPeer(peerId, mid)))\n    });\n\n    const isEphemeral = !!messages.length && messages.every(isEphemeralMessage);\n    const isMegagroup = await managers.appPeersManager.isMegagroup(peerId);\n    if(!isEphemeral && isMegagroup && !messages.some((message) => message.pFlags.out)) {\n      const participants = await managers.appProfileManager.getParticipants({\n        id: peerId.toChatId(),\n        filter: {_: 'channelParticipantsAdmins'},\n        limit: 100\n      });\n\n      const foundAdmin = messages.some((message) => {\n        return participants.participants.some((participant) => getParticipantPeerId(participant) === message.fromId);\n      });\n\n      if(!foundAdmin) {\n        PopupElement.createPopup(PopupDeleteMegagroupMessages, {\n          messages,\n          onConfirm: this.onConfirm\n        });\n        return;\n      }\n    }\n\n    const callback = (\n      e: MouseEvent,\n      checked: PopupPeerButtonCallbackCheckboxes,\n      revoke?: boolean\n    ) => {\n      onConfirm?.();\n      if(type === ChatType.Scheduled) {\n        managers.appMessagesManager.deleteScheduledMessages(peerId, mids);\n      } else {\n        const needRevoke = !!checked.size || revoke;\n        if(peerId.isUser() && needRevoke && canRevoke.length !== mids.length) {\n          managers.appMessagesManager.deleteMessages(peerId, canRevoke, true);\n          managers.appMessagesManager.deleteMessages(peerId, mids.filter((mid) => !canRevoke.includes(mid)), false);\n        } else {\n          managers.appMessagesManager.deleteMessages(peerId, mids, needRevoke);\n        }\n      }\n    };\n\n    const buttons: PopupPeerOptions['buttons'] = [{\n      langKey: 'Delete',\n      isDanger: true,\n      callback\n    }];\n    const checkboxes: PopupPeerOptions['checkboxes'] = [];\n    let title: LangPackKey, titleArgs: any[], description: LangPackKey, descriptionArgs: any[];\n    const isSingleMessage = mids.length === 1;\n    if(isSingleMessage) {\n      title = 'DeleteSingleMessagesTitle';\n    } else {\n      title = 'DeleteMessagesTitle';\n      titleArgs = [i18n('messages', [mids.length])];\n    }\n\n    if(isEphemeral) {\n      description = isSingleMessage ? 'AreYouSureDeleteSingleMessage' : 'AreYouSureDeleteFewMessages';\n    } else if(isMegagroup) {\n      description = isSingleMessage ? 'AreYouSureDeleteSingleMessageMega' : 'AreYouSureDeleteFewMessagesMega';\n    } else if(isBot) {\n      description = isSingleMessage ? 'AreYouSureDeleteSingleMessageBot' : 'AreYouSureDeleteFewMessagesBot';\n    } else {\n      description = isSingleMessage ? 'AreYouSureDeleteSingleMessage' : 'AreYouSureDeleteFewMessages';\n    }\n\n    let canRevoke: number[] = mids.slice();\n    if(isEphemeral) {\n      canRevoke = [];\n    } else if(peerId === rootScope.myId || type === ChatType.Scheduled || isBot) {\n\n    } else if(peerId.isUser()) {\n      canRevoke = canRevoke.filter((mid, idx) => {\n        const message = messages[idx];\n        const media = (message as Message.message).media;\n        if(media?._ === 'messageMediaDice') {\n          return false;\n        }\n\n        return true;\n      });\n\n      if(canRevoke.length === mids.length) {\n        checkboxes.push({\n          text: 'DeleteMessagesOptionAlso',\n          textArgs: [peerTitleElement]\n        });\n      } else {\n        description = isSingleMessage ? 'AreYouSureDeleteSingleMessageOnlyMe' : 'AreYouSureDeleteFewMessagesOnlyMe';\n\n        if(canRevoke.length) {\n          checkboxes.push({\n            text: 'DeleteMessagesOption'\n          });\n\n          description = 'AreYouSureDeleteFewMessagesMixed';\n          descriptionArgs = [peerTitleElement];\n        }\n      }\n    } else {\n      const chat = await managers.appChatsManager.getChat(peerId.toChatId());\n\n      const _hasRights = hasRights(chat, 'delete_messages');\n      if(chat._ === 'chat') {\n        canRevoke = _hasRights ? canRevoke : canRevoke.filter((mid, idx) => {\n          const message = messages[idx];\n          return message.fromId === rootScope.myId;\n        });\n\n        if(canRevoke.length) {\n          if(canRevoke.length === mids.length) {\n            checkboxes.push({\n              text: 'DeleteForAll'\n            });\n          } else {\n            checkboxes.push({\n              text: 'DeleteMessagesOption'\n            });\n\n            description = 'DeleteMessagesTextGroup';\n            descriptionArgs = [i18n('messages', [canRevoke.length])];\n          }\n        }\n      } else {\n        let foundGiveaway: MessageMedia.messageMediaGiveaway;\n        messages.find((message) => {\n          return message &&\n            (message as Message.message).media?._ === 'messageMediaGiveaway' &&\n            !(message as Message.message).fwdFromId &&\n            (foundGiveaway = (message as Message.message).media as MessageMedia.messageMediaGiveaway);\n        });\n\n        if(foundGiveaway && foundGiveaway.until_date >= tsNow(true)) {\n          title = 'BoostingGiveawayDeleteMsgTitle';\n          description = 'BoostingGiveawayDeleteMsgText';\n          descriptionArgs = [formatFullSentTime(foundGiveaway.until_date, undefined, true)];\n        }\n\n        buttons[0].callback = (e, checked) => callback(e, checked, true);\n      }\n    }\n\n    addCancelButton(buttons);\n\n    const popup = PopupElement.createPopup(PopupPeer, 'popup-delete-chat', {\n      peerId,\n      threadId,\n      titleLangKey: title,\n      titleLangArgs: titleArgs,\n      descriptionLangKey: description,\n      descriptionLangArgs: descriptionArgs,\n      buttons,\n      checkboxes\n    });\n\n    popup.show();\n  }\n}\n","import PopupElement, {addCancelButton} from '.';\nimport PopupPeer, {PopupPeerButtonCallbackCheckboxes, PopupPeerOptions} from '@components/popups/peer';\nimport rootScope from '@lib/rootScope';\nimport {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\nexport default class PopupPinMessage {\n  constructor(\n    private peerId: PeerId,\n    private mid: number,\n    private unpin?: true,\n    private onConfirm?: () => void,\n    /** Forum topic the action is scoped to — the pinned list there is per-topic. */\n    private threadId?: number\n  ) {\n    this.construct();\n  }\n\n  private async construct() {\n    const {peerId, mid, unpin, onConfirm, threadId} = this;\n    let title: LangPackKey, description: LangPackKey, descriptionArgs: FormatterArguments;\n    const buttons: PopupPeerOptions['buttons'] = [], checkboxes: PopupPeerOptions['checkboxes'] = [];\n\n    const managers = PopupElement.MANAGERS;\n\n    const canUnpin = await managers.appPeersManager.canPinMessage(peerId);\n\n    const callback = (e: MouseEvent, checked: PopupPeerButtonCallbackCheckboxes, oneSide?: boolean, silent?: boolean) => {\n      setTimeout(() => { // * костыль, потому что document.elementFromPoint вернёт popup-peer пока он будет закрываться\n        let promise: Promise<any>;\n        if(unpin && !mid) {\n          if(canUnpin) {\n            promise = managers.appMessagesManager.unpinAllMessages(peerId, threadId);\n          } else {\n            promise = managers.appMessagesManager.hidePinnedMessages(peerId, threadId);\n          }\n        } else {\n          promise = managers.appMessagesManager.updatePinnedMessage(peerId, mid, unpin, silent, oneSide);\n        }\n\n        if(onConfirm) {\n          promise.then(onConfirm);\n        }\n      }, 300);\n    };\n\n    if(unpin) {\n      let buttonText: LangPackKey = 'UnpinMessage';\n      if(!mid) {\n        if(canUnpin) {\n          title = 'Popup.Unpin.AllTitle';\n          description = 'Chat.UnpinAllMessagesConfirmation';\n          descriptionArgs = ['' + ((await managers.appMessagesManager.getPinnedMessagesCount(peerId, threadId)) || 1)];\n        } else {\n          title = 'Popup.Unpin.HideTitle';\n          description = 'Popup.Unpin.HideDescription';\n          buttonText = 'Popup.Unpin.Hide';\n        }\n      } else {\n        title = 'UnpinMessageAlertTitle';\n        description = 'Chat.Confirm.Unpin';\n      }\n\n      buttons.push({\n        langKey: buttonText,\n        isDanger: true,\n        callback\n      });\n    } else {\n      title = 'PinMessageAlertTitle';\n      const pinButtonText: LangPackKey = 'PinMessage';\n\n      if(peerId.isAnyChat()) {\n        buttons.push({\n          langKey: pinButtonText,\n          callback: (e, checked) => callback(e, checked, false, !checked.size)\n        });\n\n        if(await managers.appChatsManager.isBroadcast(peerId.toChatId())) {\n          description = 'PinMessageAlertChannel';\n        } else {\n          description = 'PinMessageAlert';\n\n          checkboxes.push({\n            text: 'PinNotify',\n            checked: true\n          });\n        }\n      } else {\n        description = 'PinMessageAlertChat';\n\n        if(peerId === rootScope.myId) {\n          buttons.push({\n            langKey: pinButtonText,\n            callback\n          });\n        } else {\n          buttons.push({\n            langKey: pinButtonText,\n            callback: (e, checked) => callback(e, checked, !checked.size)\n          });\n\n          checkboxes.push({\n            text: 'PinAlsoFor',\n            textArgs: [await wrapPeerTitle({peerId})],\n            checked: true\n          });\n        }\n      }\n    }\n\n    addCancelButton(buttons);\n\n    const popup = PopupElement.createPopup(PopupPeer, 'popup-delete-chat', {\n      peerId,\n      titleLangKey: title,\n      descriptionLangKey: description,\n      descriptionLangArgs: descriptionArgs,\n      buttons,\n      checkboxes\n    });\n\n    popup.show();\n  }\n}\n","import PopupPeer from '@components/popups/peer';\n\nexport default class PopupSendNow extends PopupPeer {\n  constructor(peerId: PeerId, mids: number[], onConfirm?: () => void) {\n    super('popup-delete-chat', {\n      title: `Send Message${mids.length > 1 ? 's' : ''} Now`,\n      description: mids.length > 1 ? 'Send ' + mids.length + ' messages now?' : 'Send message now?',\n      buttons: [{\n        langKey: 'Send',\n        callback: () => {\n          onConfirm && onConfirm();\n          this.managers.appMessagesManager.sendScheduledMessages(peerId, mids);\n        }\n      }]\n    });\n\n    this.show();\n  }\n}\n","import findUpClassName from '@helpers/dom/findUpClassName';\n\n/**\n * The message unit a click addresses: a single item of an album (a photo, a video or a document of\n * a group), or the whole bubble otherwise. What ChatSelection selects — and what the context menu\n * highlights as its target.\n */\nexport default function getSelectionElementFromTarget(target: EventTarget | HTMLElement) {\n  return findUpClassName(target, 'grouped-item') || findUpClassName(target, 'bubble');\n}\n","import setBlankToAnchor from '@lib/richTextProcessor/setBlankToAnchor';\nimport isSuspiciousUrl from '@helpers/string/isSuspiciousUrl';\nimport {normalizeUrlProtocol} from '@lib/richTextProcessor/matchUrlProtocol';\n\nexport default function safeWindowOpen(url: string) {\n  // most callers hand over a url straight off the wire (a web app event, a keyboard button, a\n  // gift's listing url) without running it through `wrapUrl` first, so it gets the same protocol\n  // filter here — a `javascript:` payload must not run on this origin\n  url = normalizeUrlProtocol(url);\n\n  // every external url opened without an anchor of its own passes through here — inline keyboard\n  // buttons, story links, web app events — so a lookalike host is caught in one place. the alert\n  // is reached through the global the anchor listeners register, keeping this leaf helper free of\n  // the popup's imports; before the app registers it there is nothing to confirm with\n  const showMaskedAlert = (window as any).showMaskedAlert;\n  if(showMaskedAlert && isSuspiciousUrl(url)) {\n    const anchor = setBlankToAnchor(document.createElement('a'));\n    anchor.href = url; // the alert prints `anchor.href`, i.e. the punycode form of the host\n    showMaskedAlert(anchor);\n    return;\n  }\n\n  window.open(url, '_blank', 'noreferrer');\n}\n","import safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport I18n, {i18n} from '@lib/langPack';\nimport PopupPeer from '@components/popups/peer';\n\nexport default class PopupSponsored extends PopupPeer {\n  constructor() {\n    super('popup-sponsored', {\n      titleLangKey: 'Chat.Message.Sponsored.What',\n      descriptionLangKey: 'Chat.Message.Ad.Text',\n      descriptionLangArgs: [i18n('Chat.Message.Sponsored.Link')],\n      buttons: [{\n        langKey: 'OK',\n        isCancel: true\n      }, {\n        langKey: 'Chat.Message.Ad.ReadMore',\n        callback: () => {\n          safeWindowOpen(I18n.format('Chat.Message.Sponsored.Link', true));\n        },\n        isCancel: true\n      }],\n      scrollable: true\n    });\n\n    this.scrollable.append(this.description);\n\n    this.show();\n  }\n}\n","export default function maybe2x(str: string) {\n  return str + (window.devicePixelRatio > 1 ? '@2x' : '');\n}\n","// https://stackoverflow.com/a/14824756/6758968\nconst ltrChars  = 'A-Za-z\\u00C0-\\u00D6\\u00D8-\\u00F6\\u00F8-\\u02B8\\u0300-\\u0590\\u0800-\\u1FFF'+'\\u2C00-\\uFB1C\\uFDFE-\\uFE6F\\uFEFD-\\uFFFF',\n  rtlChars      = '\\u0591-\\u07FF\\uFB1D-\\uFDFD\\uFE70-\\uFEFC',\n  fullRtlDirCheck   = new RegExp('^[^'+ltrChars+']*['+rtlChars+']'),\n  justRtlDirCheck   = new RegExp('['+rtlChars+']');\n\nexport default function isRTL(s: string, anyChar?: boolean) {\n  return anyChar ? justRtlDirCheck.test(s) : fullRtlDirCheck.test(s);\n}\n\nexport function endsWithRTL(s: string) {\n  return justRtlDirCheck.test(s?.slice(-1));\n}\n","import isRTL from '@helpers/string/isRTL';\n\n// import { MOUNT_CLASS_TO } from '@config/debug';\n\nlet context: CanvasRenderingContext2D;\n/**\n * Get the text width\n * @param {string} text\n * @param {string} font\n */\nexport default function getTextWidth(text: string, font: string) {\n  // const perf = performance.now();\n  if(!context) {\n    const canvas = document.createElement('canvas');\n    context = canvas.getContext('2d', {alpha: false});\n  }\n\n  if(context.font !== font) {\n    context.font = font;\n  }\n\n  context.direction = isRTL(text) ? 'rtl' : 'ltr';\n\n  // context.font = font;\n  const metrics = context.measureText(text);\n  // console.log('getTextWidth perf:', performance.now() - perf);\n  return metrics.width;\n  // return Math.round(metrics.width);\n}\n\n// MOUNT_CLASS_TO && (MOUNT_CLASS_TO.getTextWidth = getTextWidth);\n","function cacheCallback<A, T>(callback: (str: A) => T) {\n  const stringResults: any = {}, numberResults: any = {};\n  return (value: A): T => {\n    const key = '_' + value;\n    return (typeof(value) === 'string' ? stringResults : numberResults)[key] ??= callback(value);\n  };\n}\n\nexport default cacheCallback;\n","export default function replaceNonNumber(str: string) {\n  return str.replace(/\\D/g, '');\n}\n","import cacheCallback from '@helpers/cacheCallback';\nimport replaceNonNumber from '@helpers/string/replaceNonNumber';\n\nconst CARD_BRAND_REGEXP: {[brand: string]: RegExp} = {\n  visa: /^4/,\n  mastercard: /^(51|52|53|54|55|222|23|24|25|26|27)/,\n  amex: /^(34|37)/,\n  discover: /^(60|64|65)/,\n  diners: /^(30|38|39)/,\n  diners14: /^(36)/,\n  jcb: /^(35)/,\n  unionpay: /^(62[0-6,8-9]|627[0-6,8-9]|6277[0-7,9]|62778[1-9]|81)/,\n  elo: /^(5067|509|636368|627780)/,\n  // mir: /^(220[0-4])/\n  mir: /^(2\\d+)/\n};\n\n// * taken from Stripe\nexport const CARD_BRANDS: {[b: string]: {\n  minLength: number,\n  maxLength: number,\n  cvcMaxLength: number,\n  cvcMinLength: number | null\n}} = {\n  visa: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  mastercard: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  amex: {\n    minLength: 15,\n    maxLength: 15,\n    cvcMaxLength: 4,\n    cvcMinLength: 3\n  },\n  unionpay: {\n    minLength: 13,\n    maxLength: 19,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  diners: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  diners14: {\n    minLength: 14,\n    maxLength: 14,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  discover: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  jcb: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  elo: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  mir: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 3,\n    cvcMinLength: null\n  },\n  unknown: {\n    minLength: 16,\n    maxLength: 16,\n    cvcMaxLength: 4,\n    cvcMinLength: 3\n  }\n};\n\nexport const detectCardBrand = cacheCallback((card: string = '') => {\n  const keys = Object.keys(CARD_BRAND_REGEXP);\n  const sanitizedCard = replaceNonNumber(card);\n  let brand: string;\n  let last = 0;\n  keys.forEach((key) => {\n    const regExp = CARD_BRAND_REGEXP[key];\n    const match = sanitizedCard.match(regExp);\n    if(match) {\n      const result = match[0];\n      if(result && result.length > last) {\n        brand = key;\n        last = result.length;\n      }\n    }\n  });\n\n  return brand || 'unknown';\n});\n\nexport function cardBrandToUnifiedBrand(brand: string) {\n  return brand === 'diners14' ? 'diners' : brand;\n}\n\nexport function detectUnifiedCardBrand(card = '') {\n  const brand = detectCardBrand(card);\n  return cardBrandToUnifiedBrand(brand);\n}\n","import type Scrollable from '@components/scrollable';\nimport type {ScrollableContextValue} from '@components/scrollable2';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport {fastRaf} from '@helpers/schedulers';\n\n// let USE_REFLOW = false;\n// if(IS_SAFARI) {\n//   try {\n//     // throw '';\n//     const match = navigator.userAgent.match(/Version\\/(.+?) /);\n//     USE_REFLOW = +match[1] < 15.4;\n//   } catch(err) {\n//     USE_REFLOW = true;\n//   }\n// }\n\nexport default class ScrollSaver {\n  private scrollHeight: number;\n  private scrollHeightMinusTop: number;\n  private scrollTop: number;\n  private scrolledToEnd: boolean;\n  private clientHeight: number;\n  private elements: {element: HTMLElement, rect: DOMRect}[];\n\n  /**\n   *\n   * @param scrollable to reset scroll position and direction\n   * @param reverse true means top\n   */\n  constructor(\n    private scrollable: Scrollable | ScrollableContextValue,\n    private query: string,\n    private reverse: boolean\n  ) {\n\n  }\n\n  private get container() {\n    return this.scrollable.container;\n  }\n\n  public getSaved() {\n    return {\n      scrollHeight: this.scrollHeight,\n      scrollTop: this.scrollTop,\n      clientHeight: this.clientHeight\n    };\n  }\n\n  public findElements() {\n    if(!this.query) return [];\n\n    const {container} = this;\n    const containerRect = container.getBoundingClientRect();\n    const bubbles = Array.from(container.querySelectorAll(this.query)) as HTMLElement[];\n    const elements: ScrollSaver['elements'] = [];\n    for(const bubble of bubbles) {\n      const elementRect = bubble.getBoundingClientRect();\n      const visibleRect = getVisibleRect(bubble, container, undefined, elementRect, containerRect);\n      if(visibleRect) {\n        elements.push({element: bubble, rect: elementRect});\n        // break; // find first\n      } else if(elements.length) { // find last\n        break;\n      }\n    }\n\n    if(!elements.length) {\n      const bubble = bubbles[0];\n      if(bubble) {\n        elements.push({element: bubble, rect: bubble.getBoundingClientRect()});\n      }\n    }\n\n    return elements;\n  }\n\n  public replaceSaved(from: HTMLElement, to: HTMLElement) {\n    if(!this.elements) {\n      return;\n    }\n\n    const idx = this.elements.findIndex(({element}) => from === element);\n    if(idx !== -1) {\n      this.elements[idx].element = to;\n    }\n  }\n\n  public findAndSetElements() {\n    this.elements = this.findElements();\n  }\n\n  public save() {\n    this.findAndSetElements();\n    // console.warn('scroll save', this.elements);\n    this._save();\n  }\n\n  public _save() {\n    const {scrollTop, scrollHeight, clientHeight} = this.container;\n\n    // previousScrollHeight = scrollHeight;\n    // previousScrollHeight = scrollHeight + padding;\n    this.scrollHeight = scrollHeight;\n    this.scrollTop = scrollTop;\n    this.clientHeight = clientHeight;\n    this.scrollHeightMinusTop = this.reverse ? scrollHeight - scrollTop : scrollTop;\n    this.scrolledToEnd = scrollHeight - Math.ceil(scrollTop + clientHeight) <= 1;\n    // this.chatInner.style.paddingTop = padding + 'px';\n    /* if(reverse) {\n      previousScrollHeightMinusTop = this.scrollable.scrollHeight - scrollTop;\n    } else {\n      previousScrollHeightMinusTop = scrollTop;\n    } */\n  }\n\n  private onRestore(useReflow?: boolean) {\n    // if(USE_REFLOW && useReflow/*  && !isAppleMobile */) { // * fix blinking and jumping\n    //   reflowScrollableElement(this.container);\n    // }\n\n    this.scrollable.onSizeChange();\n  }\n\n  private setScrollTop(newScrollTop: number, useReflow?: boolean) {\n    // touchSupport for safari iOS\n    // isTouchSupported && isApple && (container.container.style.overflow = 'hidden');\n    this.scrollable.setScrollPositionSilently(this.scrollTop = newScrollTop);\n    // container.scrollTop = scrollHeight;\n    // isTouchSupported && isApple && (container.container.style.overflow = '');\n\n    if(IS_SAFARI) {\n      fastRaf(() => {\n        if(this.scrollTop === newScrollTop) {\n          this.scrollable.setScrollPositionSilently(this.scrollTop = newScrollTop);\n        }\n      });\n    }\n\n    this.onRestore(useReflow);\n  }\n\n  private getAnchor() {\n    return this.elements[this.reverse ? 0 : this.elements.length - 1];\n  }\n\n  public restore(useReflow?: boolean) {\n    const {scrollPosition: scrollTop, scrollSize: scrollHeight} = this.scrollable;\n    this.scrollHeight = scrollHeight;\n\n    if(!this.elements.length && this.query) { // maybe all messages have been deleted or adding first message\n      // this._restore(useReflow);\n      this.setScrollTop(this.reverse ? scrollHeight : 0, useReflow); // fix scrolling to first new message\n      return;\n    }\n\n    let anchor: ScrollSaver['elements'][0];\n    // for(let i = this.elements.length - 1; i >= 0; --i) {\n    //   const _anchor = this.elements[i];\n    //   if(_anchor.element.parentElement) {\n    //     anchor = _anchor;\n    //     break;\n    //   }\n    // }\n    anchor = this.getAnchor();\n\n    if(!anchor?.element?.parentElement) { // try to find new anchor\n      this.findAndSetElements();\n      anchor = this.getAnchor();\n\n      if(!anchor) { // fallback to old method if smth is really strange\n        this._restore(useReflow);\n        return;\n      }\n    }\n\n    const {element, rect} = anchor;\n    const newRect = element.getBoundingClientRect();\n    const containerRect = this.container.getBoundingClientRect();\n    const isOverflowingTop = rect.top < containerRect.top;\n    const isOverflowingBottom = rect.bottom > containerRect.bottom;\n    let positionKey: 'top' | 'bottom' = this.reverse ? 'top' : 'bottom';\n    if( // * stick to one of the visible edges\n      this.reverse ?\n        isOverflowingTop && !isOverflowingBottom :\n        isOverflowingBottom && !isOverflowingTop\n    ) {\n      positionKey = this.reverse ? 'bottom' : 'top';\n    }\n    const newPosition = newRect[positionKey];\n    let position = rect[positionKey];\n    const modifiedHeight = rect.height - newRect.height;\n    if(isOverflowingTop && isOverflowingBottom && modifiedHeight > 0) { // * large quote collapsing\n      position = containerRect[positionKey];\n      // position = newRect[positionKey] - containerRect[positionKey];\n      // position = (position + rect.height / 2) - (containerRect.height / 2);\n    }\n    if(\n      newPosition === position &&\n      // newRect.bottom === rect.bottom &&\n      !this.scrolledToEnd\n      /*  && modifiedHeight >= 0 */\n    ) {\n      // console.log('no need to scroll', rect, newRect);\n      return; // no need to scroll\n    }\n\n    const posDiff = newPosition - position;\n    const diff = posDiff/*  + (modifiedHeight > 0 ? modifiedHeight : -modifiedHeight) *//*  * (this.reverse ? -1 : 1) */;\n    // console.log(rect, posDiff, diff, newRect);\n    if(!Math.abs(diff)) {\n      return;\n    }\n    this.setScrollTop(scrollTop + diff, useReflow);\n    // if(diff) debugger;\n    // console.warn('scroll restore', rect, diff, newRect);\n  }\n\n  public _restore(useReflow?: boolean) {\n    const {scrollHeightMinusTop: previousScrollHeightMinusTop, scrollable} = this;\n    // if(previousScrollHeightMinusTop === undefined) {\n    //   throw new Error('scroll was not saved');\n    // }\n\n    // const scrollHeight = container.scrollHeight;\n    const scrollHeight = this.scrollHeight;\n    // if(scrollHeight === this.scrollHeight) {\n    //   return;\n    // }\n\n    // this.scrollHeight = scrollHeight;\n\n    /* const scrollHeight = container.scrollHeight;\n    const addedHeight = scrollHeight - previousScrollHeight;\n\n    this.chatInner.style.paddingTop = (10000 - addedHeight) + 'px'; */\n    /* const scrollHeight = scrollHeight;\n    const addedHeight = scrollHeight - previousScrollHeight;\n\n    this.chatInner.style.paddingTop = (padding - addedHeight) + 'px';\n\n    //const newScrollTop = reverse ? scrollHeight - previousScrollHeightMinusTop : previousScrollHeightMinusTop;\n    const newScrollTop = reverse ? scrollHeight - addedHeight - previousScrollHeightMinusTop : previousScrollHeightMinusTop;\n    this.log('performHistoryResult: will set scrollTop',\n    previousScrollHeightMinusTop, scrollHeight,\n    newScrollTop, container.container.clientHeight); */\n    // const newScrollTop = reverse ? scrollHeight - previousScrollHeightMinusTop : previousScrollHeightMinusTop;\n    const newScrollTop = this.reverse ? scrollHeight - previousScrollHeightMinusTop : previousScrollHeightMinusTop;\n\n    /* if(DEBUG) {\n      this.log('performHistoryResult: will set up scrollTop:', newScrollTop, this.isHeavyAnimationInProgress);\n    } */\n\n    this.setScrollTop(newScrollTop, useReflow);\n\n    /* if(DEBUG) {\n      this.log('performHistoryResult: have set up scrollTop:', newScrollTop, container.scrollTop, container.scrollHeight, this.isHeavyAnimationInProgress);\n    } */\n  }\n}\n\nMOUNT_CLASS_TO && (MOUNT_CLASS_TO.ScrollSaver = ScrollSaver);\n","export default function createArray<T1>(length: number, fill?: T1, map?: any): T1[] {\n  const arr = new Array<T1>(length);\n  arr.fill(fill);\n  return map ? arr.map(map) : arr;\n}\n","const delta = '０'.charCodeAt(0) - '0'.charCodeAt(0);\nconst buggedRegExp = /[０-９]/g;\n\n// function hasBuggedNumbers(str: string) {\n//   return !!str.match(a);\n// }\n\nfunction getDistanceFromBuggedToNormal(char: string) {\n  return String.fromCharCode(char.charCodeAt(0) - delta);\n}\n\nexport function fixBuggedNumbers(str: string) {\n  return str.replace(buggedRegExp, getDistanceFromBuggedToNormal);\n}\n","import {fixBuggedNumbers} from '@helpers/string/buggedNumbers';\nimport replaceNonNumber from '@helpers/string/replaceNonNumber';\n\nexport type PatternCharacter = {\n  type: 'optional',\n  result: string,\n  consumed: number\n} | {\n  type: 'required',\n  result: string,\n  consumed: number,\n  partial?: boolean\n} | {\n  type: 'formatting',\n  result: string,\n  consumed: number\n};\n\nexport type PatternFunction = (str: string) => ((str: string) => PatternCharacter)[];\n\nfunction makeOptionalCharacter(result: string, consumed: number): PatternCharacter {\n  return {type: 'optional', result, consumed};\n}\n\nfunction makeRequiredCharacter(result: string, consumed: number, partial?: boolean): PatternCharacter {\n  return {type: 'required', result, consumed, partial};\n}\n\nfunction makeFormattingCharacter(result: string, consumed: number): PatternCharacter {\n  return {type: 'formatting', result, consumed};\n}\n\nfunction wrapCharacterRegExpFactory(regExp: RegExp, optional?: boolean) {\n  return (str: string) => {\n    const _regExp = new RegExp('^'.concat(regExp.source.replace(/^\\^/, '')));\n    const match = str.match(_regExp);\n    const makeCharacter = optional ? makeOptionalCharacter : makeRequiredCharacter;\n    if(match) {\n      const result = match[0];\n      return makeCharacter(result, match.index + result.length);\n    }\n\n    return makeCharacter('', str.length);\n  };\n}\n\nfunction makeCapitalPatternCharacter(str: string) {\n  const char = wrapCharacterRegExpFactory(/\\w/)(str);\n  return char.result ? makeRequiredCharacter(char.result.toUpperCase(), char.consumed) : char;\n}\n\nconst makeMonthDigitPatternCharacter = wrapCharacterRegExpFactory(/1[0-2]|0?[1-9]|0/);\n\nfunction digit(str: string) {\n  return wrapCharacterRegExpFactory(/[0-9]/)(fixBuggedNumbers(str));\n}\n\nconst patternCharacters = {\n  digit,\n  capitalCharacter: makeCapitalPatternCharacter,\n  month: (str: string) => {\n    const char = makeMonthDigitPatternCharacter(fixBuggedNumbers(str));\n    const cleanedResult = replaceNonNumber(char.result);\n    const isPartial = ['0', '1'].includes(char.result) && str.length === 1;\n    if(isPartial || (char.result === '0' && str.length >= 2)) {\n      return makeRequiredCharacter(char.result, str.length, true);\n    }\n\n    return makeRequiredCharacter(cleanedResult.length === 1 ? '0' + cleanedResult : cleanedResult, char.consumed);\n  },\n  formattingCharacter: (str: string) => {\n    return (str1: string) => {\n      const consumed = str === str1[0] ? 1 : 0;\n      return makeFormattingCharacter(str, consumed);\n    }\n  },\n  optionalPattern: (regExp: RegExp) => {\n    return (str: string) => {\n      const char = wrapCharacterRegExpFactory(regExp, true)(str);\n      return char.result ? char : makeOptionalCharacter('', 0);\n    };\n  }\n};\n\nexport default patternCharacters;\n","import {IS_ANDROID} from '@environment/userAgent';\nimport createArray from '@helpers/array/createArray';\nimport cacheCallback from '@helpers/cacheCallback';\nimport replaceNonNumber from '@helpers/string/replaceNonNumber';\nimport {CARD_BRANDS, detectCardBrand} from '@helpers/cards/cardBrands';\nimport patternCharacters from '@helpers/cards/patternCharacters';\n\nconst digit = patternCharacters.digit;\nconst capitalCharacter = patternCharacters.capitalCharacter;\nconst spaceCharacter = patternCharacters.formattingCharacter(' ');\nconst yearOptionalPattern = patternCharacters.optionalPattern(/\\d\\d/);\nconst sixteenPattern = [digit, digit, digit, digit, spaceCharacter, digit, digit, digit, digit, digit, digit, spaceCharacter, digit, digit, digit, digit, digit];\nconst fifteenPattern = [digit, digit, digit, digit, spaceCharacter, digit, digit, digit, digit, digit, digit, spaceCharacter, digit, digit, digit, digit];\n\nconst requiredPostcodes = new Set(['DZ', 'AR', 'AM', 'AU', 'AT', 'AZ', 'PT', 'BD', 'BY', 'BE', 'BA', 'BR', 'BN', 'BG', 'CA', 'IC', 'CN', 'CO', 'HR', 'CY', 'CZ', 'DK', 'EC', 'GB', 'EE', 'FO', 'FI', 'FR', 'GE', 'DE', 'GR', 'GL', 'GU', 'GG', 'NL', 'HU', 'IN', 'ID', 'IL', 'IT', 'JP', 'JE', 'KZ', 'KR', 'FM', 'KG', 'LV', 'LI', 'LT', 'LU', 'MK', 'MG', 'PT', 'MY', 'MH', 'MQ', 'YT', 'MX', 'MN', 'ME', 'NL', 'NZ', 'GB', 'NO', 'PK', 'PH', 'PL', 'FM', 'PT', 'PR', 'RE', 'RU', 'SA', 'SF', 'RS', 'SG', 'SK', 'SI', 'ZA', 'ES', 'LK', 'SX', 'VI', 'VI', 'SE', 'CH', 'TW', 'TJ', 'TH', 'TU', 'TN', 'TR', 'TM', 'VI', 'UA', 'GB', 'US', 'UY', 'UZ', 'VA', 'VN', 'GB', 'FM']);\n\nconst generateFourPattern = cacheCallback((length: number) => {\n  const out: Array<typeof digit | typeof spaceCharacter> = [];\n\n  for(let i = 0, k = 0; i < length;) {\n    if(k === 4) {\n      out.push(spaceCharacter);\n      k = 0;\n    } else {\n      out.push(digit);\n      ++i;\n      ++k;\n    }\n  }\n\n  return out;\n});\n\nfunction generateCardNumberPattern(card: string) {\n  const brand = detectCardBrand(card);\n  if(brand === 'amex') return sixteenPattern;\n  if(brand === 'diners14') return fifteenPattern;\n  const {minLength, maxLength} = CARD_BRANDS[brand];\n  const s = replaceNonNumber(card).length;\n  const d = Math.min(Math.max(minLength, s), maxLength);\n  return generateFourPattern(d);\n}\n\nconst cardFormattingPatterns = {\n  cardNumber: generateCardNumberPattern,\n  cardExpiry: () => [patternCharacters.month, patternCharacters.formattingCharacter('/'), digit, digit, yearOptionalPattern],\n  cardCvc: (card?: string) => cardFormattingPatterns.cardCvcFromBrand(detectCardBrand(card)),\n  cardCvcFromBrand: cacheCallback((brand: string) => {\n    const info = CARD_BRANDS[brand];\n    const {cvcMinLength, cvcMaxLength} = info;\n    const pattern = createArray(cvcMinLength || cvcMaxLength, digit);\n    if(cvcMinLength && cvcMinLength < cvcMaxLength) {\n      const i = cvcMaxLength - cvcMinLength;\n      const h = patternCharacters.optionalPattern(/\\d/);\n      if(i) {\n        pattern.push(...createArray(i, h));\n      }\n    }\n\n    return pattern;\n  }),\n  postalCodeFromCountry: cacheCallback((iso2: string) => {\n    switch(iso2) {\n      case 'US':\n        return createArray(5, digit);\n      case 'CA':\n        return IS_ANDROID ? null : [capitalCharacter, capitalCharacter, capitalCharacter, spaceCharacter, capitalCharacter, capitalCharacter, capitalCharacter];\n      default:\n        const optionalDigits = createArray(10, patternCharacters.optionalPattern(/\\d/));\n        if(requiredPostcodes.has(iso2)) {\n          optionalDigits[0] = digit;\n        }\n        return optionalDigits;\n    }\n  })\n};\n\nexport default cardFormattingPatterns;\n","import accumulate from '@helpers/array/accumulate';\nimport {PatternFunction} from '@helpers/cards/patternCharacters';\n\nfunction accumulateLengths(strs: string[]) {\n  return accumulate(strs.map((str) => str.length), 0);\n}\n\nfunction formatValueByPattern(\n  getPattern: PatternFunction,\n  value: string,\n  options: Partial<{\n    selectionStart: number,\n    selectionEnd: number\n  }> = {},\n  pushRest?: boolean\n) {\n  const pattern = getPattern(value);\n\n  if(!pattern) {\n    return {\n      value: value,\n      selection: null as typeof options,\n      autocorrectComplete: !!value\n    };\n  }\n\n  const length = pattern.length;\n  const c: string[] = [];\n  const s: string[] = [];\n\n  let l = 0;\n  let i = 0;\n  let f = options.selectionStart === 0 ? 0 : null;\n  let d = options.selectionEnd === 0 ? 0 : null;\n  const p = () => {\n    if(f === null && (i + 1) >= options.selectionStart) f = accumulateLengths(c) + (pushRest ? s.length : 0);\n    if(d === null && (i + 1) >= options.selectionEnd) d = accumulateLengths(c) + (pushRest ? s.length : 0);\n  };\n  const m = (e: number) => {\n    if(e > 0) {\n      p();\n      i += e;\n    }\n  };\n\n  for(; l < length;) {\n    const getCharacter = pattern[l];\n    const character = getCharacter(value.slice(i));\n    const {type, result, consumed} = character;\n    if(type === 'required') {\n      if(result) {\n        c.push(...s, result);\n        s.length = 0;\n        ++l;\n\n        if(character.partial) {\n          m(value.length - i);\n          break;\n        }\n\n        m(consumed);\n      } else {\n        if(!consumed) {\n          break;\n        }\n\n        m(1);\n      }\n    } else if(type === 'optional') {\n      if(result) {\n        c.push(...s, result);\n        s.length = 0;\n        m(consumed);\n      }\n\n      ++l;\n    } else if(type === 'formatting') {\n      if(!pushRest && i >= value.length) {\n        break;\n      }\n\n      s.push(result);\n      ++l;\n      m(consumed);\n    }\n  }\n\n  if(pushRest) {\n    c.push(...s);\n  }\n\n  return {\n    value: c.join(''),\n    selection: {\n      selectionStart: f === null || value.length && options.selectionStart === value.length ? accumulateLengths(c) : f,\n      selectionEnd: d === null || value.length && options.selectionEnd === value.length ? accumulateLengths(c) : d\n    },\n    autocorrectComplete: l === length\n  };\n}\n\nexport default formatValueByPattern;\n","import formatValueByPattern from '@helpers/cards/formatValueByPattern';\n\nexport default function formatInputValueByPattern(options: {\n  value: string,\n  getPattern: Parameters<typeof formatValueByPattern>[0],\n  deleting?: boolean,\n  input?: HTMLElement\n}) {\n  const {value: originalValue, getPattern, deleting, input} = options;\n  const pushRest = !deleting && !!originalValue.length;\n  const result = formatValueByPattern(getPattern, originalValue, {\n    selectionStart: input ? (input as HTMLInputElement).selectionStart : 0,\n    selectionEnd: input ? (input as HTMLInputElement).selectionEnd : 0\n  }, pushRest)\n  const {value, selection} = result;\n\n  return {\n    value,\n    meta: {\n      autocorrectComplete: result.autocorrectComplete,\n      empty: !value\n    },\n    selection\n  };\n}\n","import {CARD_BRANDS, detectCardBrand} from '@helpers/cards/cardBrands';\nimport formatInputValueByPattern from '@helpers/cards/formatInputValueByPattern';\nimport NBSP from '@helpers/string/nbsp';\nimport replaceNonNumber from '@helpers/string/replaceNonNumber';\n\nexport type PatternValidationOptions = Partial<{\n  ignoreIncomplete: boolean\n}>;\n\nconst nbspRegExp = new RegExp(NBSP, 'g');\n\nfunction makeValidationError(code?: string) {\n  return code ? {\n    type: 'invalid',\n    code\n  } : null;\n}\n\n// Luhn algorithm\nfunction validateCompleteCardNumber(card: string) {\n  const t = '0'.charCodeAt(0);\n  const n = card.length % 2;\n  let a = 0;\n  for(let i = card.length - 1; i >= 0; --i) {\n    const c = n === (i % 2);\n    let o = card.charCodeAt(i) - t;\n    if(c) o *= 2;\n    if(o > 9) o -= 9;\n    a += o;\n  }\n  return !(a % 10);\n}\n\nfunction validateExpiry(year: number, month: number, options?: PatternValidationOptions & {date?: Date}) {\n  const date = options.date || new Date();\n  const _year = year < 100 ? date.getFullYear() % 100 : date.getFullYear();\n  const nextMonth = date.getMonth() + 1;\n\n  if(isNaN(year) || isNaN(month)) {\n    return options?.ignoreIncomplete ? null : 'incomplete';\n  }\n\n  if((year - _year) < 0) {\n    return 'invalid_expiry_year_past';\n  }\n\n  if((year - _year) > 50) {\n    return 'invalid_expiry_year';\n  }\n\n  return !(year - _year) && month < nextMonth ? 'invalid_expiry_month_past' : null;\n}\n\nfunction getCardInfoByNumber(card: string) {\n  const sanitized = replaceNonNumber(card);\n  const brand = detectCardBrand(card);\n  return {\n    sanitized,\n    brand,\n    minLength: CARD_BRANDS[brand].minLength\n  };\n}\n\nfunction makeCardNumberError(str: string, length: number, ignoreIncomplete: boolean) {\n  if(str.length >= length) {\n    return validateCompleteCardNumber(str) || detectCardBrand(str) === 'mir' ? null : makeValidationError('invalid');\n  }\n\n  return ignoreIncomplete ? null : makeValidationError('incomplete');\n}\n\nexport function validateCardNumber(str: string, options: PatternValidationOptions = {}) {\n  const {sanitized, minLength} = getCardInfoByNumber(str);\n  return makeCardNumberError(sanitized, minLength, options.ignoreIncomplete);\n}\n\nexport function validateCardExpiry(str: string, options: Parameters<typeof validateExpiry>[2] = {}) {\n  const sanitized = str.replace(nbspRegExp, '').split(/ ?\\/ ?/);\n  const [monthStr, yearStr = ''] = sanitized;\n  const [month, year] = [monthStr, yearStr].map((str) => +str);\n  const s = yearStr.length === 2 ? year % 100 : year;\n  return yearStr.length < 2 || yearStr.length === 3 ? (options.ignoreIncomplete ? null : makeValidationError('incomplete')) : makeValidationError(validateExpiry(s, month, options));\n}\n\nexport function validateAnyIncomplete(formatted: ReturnType<typeof formatInputValueByPattern>, str: string, options: PatternValidationOptions = {}) {\n  return formatted.meta.autocorrectComplete || options.ignoreIncomplete ? null : makeValidationError('incomplete');\n}\n","import EventListenerBase from '@helpers/eventListenerBase';\nimport {TelegramWebViewEvent, TelegramWebViewEventMap, TelegramWebViewSendEventMap} from '@types';\n\nconst weakMap: WeakMap<Window, TelegramWebView> = new WeakMap();\nwindow.addEventListener('message', (e) => {\n  weakMap.get(e.source as Window)?.onMessage(e.origin, e.data);\n});\n\nexport default class TelegramWebView extends EventListenerBase<{\n  [type in keyof TelegramWebViewEventMap]: (data: TelegramWebViewEventMap[type]) => void\n}> {\n  public iframe: HTMLIFrameElement;\n  public lastDispatchedWebViewEvent: {type: keyof TelegramWebViewSendEventMap, count: number};\n\n  private onLoad: () => void;\n  private html: string;\n  private origin: string;\n\n  constructor({url, sandbox, allow, html, origin, onLoad}: {\n    url?: string,\n    sandbox?: string,\n    allow?: string,\n    html?: string,\n    origin?: string,\n    onLoad?: () => void\n  }) {\n    super(false);\n\n    const iframe = this.iframe = document.createElement('iframe');\n    if(url) iframe.src = url;\n    if(sandbox) iframe.setAttribute('sandbox', sandbox);\n    if(allow) iframe.allow = allow;\n    if(html) this.html = html;\n    if(origin) this.origin = origin;\n\n    if(onLoad) {\n      this.onLoad = onLoad;\n      iframe.addEventListener('load', onLoad, {once: true});\n    }\n  }\n\n  // ! `origin` is set only for a frame the server asked to keep on the origin it was opened at\n  // ! (`webViewResultUrl.same_origin`) — the WindowProxy keeps its identity across a cross-origin\n  // ! navigation, so without this the document that replaced it would inherit the bridge, and with\n  // ! it the privileges of the bot the frame was opened for\n  public setOrigin(origin: string) {\n    this.origin = origin;\n  }\n\n  public onMessage(origin: string, data: string) {\n    if(this.origin && origin !== this.origin) {\n      return;\n    }\n\n    this.onTelegramWebViewEvent(JSON.parse(data));\n  }\n\n  public onMount() {\n    // ! the WindowProxy stays the same object across the srcdoc navigation, so registering\n    // ! before assigning it keeps the bridge working and avoids missing an early event\n    // ! from the frame\n    weakMap.set(this.iframe.contentWindow, this);\n    if(this.html) {\n      // ! never write into contentWindow.document — a no-src iframe inherits this origin,\n      // ! which would run the embedded third-party scripts as web.telegram.org\n      this.iframe.srcdoc = this.html;\n    }\n  }\n\n  public destroy() {\n    this.cleanup();\n    weakMap.delete(this.iframe.contentWindow);\n    this.iframe.removeEventListener('load', this.onLoad);\n  }\n\n  private onTelegramWebViewEvent = ({eventType, eventData}: TelegramWebViewEvent) => {\n    if((eventData as any) === '') {\n      eventData = undefined;\n    }\n\n    // console.log('onTelegramWebViewEvent', eventType, eventData);\n    this.dispatchEvent(eventType, eventData as any);\n  };\n\n  public dispatchWebViewEvent<T extends keyof TelegramWebViewSendEventMap>(\n    eventType: T,\n    eventData: TelegramWebViewSendEventMap[T]\n  ) {\n    if(this.lastDispatchedWebViewEvent?.type !== eventType) {\n      this.lastDispatchedWebViewEvent = {type: eventType, count: 0};\n    }\n\n    ++this.lastDispatchedWebViewEvent.count;\n    // ! targeting the origin makes the browser drop the event when the frame has navigated away —\n    // ! otherwise an answer to a request the mini app made (its location, the clipboard, a custom\n    // ! method result) would be handed to whatever document occupies the frame by the time it arrives\n    this.iframe.contentWindow.postMessage(JSON.stringify({\n      eventType,\n      eventData\n    }), this.origin || '*');\n  }\n}\n","// ! `path_full` is whatever the frame put in a `web_app_open_tg_link` event, so it cannot be pasted\n// ! onto the bare host — a value that does not start with a slash lands in the host instead of the\n// ! path ('.evil.com/x' would build https://t.me.evil.com/x)\nexport default function getWebViewTgLink(pathFull: string) {\n  return 'https://t.me/' + (pathFull || '').replace(/^\\/+/, '');\n}\n","import PopupElement from '.';\nimport appImManager from '@lib/appImManager';\nimport TelegramWebView from '@components/telegramWebView';\nimport getWebViewTgLink from '@helpers/getWebViewTgLink';\n\nexport function createVerificationIframe(options: ConstructorParameters<typeof TelegramWebView>[0]) {\n  const result = new TelegramWebView({\n    ...options,\n    sandbox: 'allow-forms allow-scripts allow-same-origin allow-modals'\n  });\n  const {iframe} = result;\n  iframe.allow = 'payment';\n  iframe.classList.add('payment-verification');\n  return result;\n}\n\nexport default class PopupPaymentVerification extends PopupElement<{\n  finish: () => void\n}> {\n  private telegramWebView: TelegramWebView;\n\n  constructor(private url: string, private openPathAfter?: boolean) {\n    super('popup-payment popup-payment-verification', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      title: 'Checkout.WebConfirmation.Title'\n    });\n\n    this.d();\n  }\n\n  private d() {\n    const telegramWebView = this.telegramWebView = createVerificationIframe({\n      url: this.url\n    });\n\n    telegramWebView.addEventListener('web_app_open_tg_link', (e) => {\n      this.dispatchEvent('finish');\n      this.hide();\n      if(this.openPathAfter) {\n        appImManager.openUrl(getWebViewTgLink(e.path_full));\n      }\n    });\n\n    this.body.append(telegramWebView.iframe);\n    this.show();\n    telegramWebView.onMount();\n  }\n\n  protected destroy() {\n    this.telegramWebView.destroy();\n    return super.destroy();\n  }\n}\n","import {LangPackKey, i18n} from '@lib/langPack';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport RowTsx from '@components/rowTsx';\n\nexport default function PaymentSaveInformationRow(props: {\n  checked: boolean,\n  disabled?: boolean,\n  title: LangPackKey,\n  subtitle: LangPackKey,\n  onChange: (checked: boolean) => void\n}) {\n  return (\n    <RowTsx disabled={props.disabled}>\n      <RowTsx.Title>{i18n(props.title)}</RowTsx.Title>\n      <RowTsx.Subtitle>{i18n(props.subtitle)}</RowTsx.Subtitle>\n      <RowTsx.CheckboxField>\n        <CheckboxFieldTsx\n          checked={props.checked}\n          disabled={props.disabled}\n          onChange={props.onChange}\n        />\n      </RowTsx.CheckboxField>\n    </RowTsx>\n  );\n}\n","import PopupElement from '.';\nimport cardFormattingPatterns from '@helpers/cards/cardFormattingPatterns';\nimport {detectUnifiedCardBrand} from '@helpers/cards/cardBrands';\nimport formatInputValueByPattern from '@helpers/cards/formatInputValueByPattern';\nimport {validateAnyIncomplete, validateCardExpiry, validateCardNumber} from '@helpers/cards/validateCard';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport noop from '@helpers/noop';\nimport {PaymentFormMethod, PaymentsPaymentForm, User} from '@layer';\nimport {LangPackKey, _i18n} from '@lib/langPack';\nimport confirmationPopup from '@components/confirmationPopup';\nimport CountryInputField from '@components/countryInputField';\nimport InputField, {InputFieldOptions, InputState} from '@components/inputField';\nimport {getPaymentBrandIconPath, PaymentButton, PaymentsCredentialsToken} from '@components/popups/payment';\nimport {createVerificationIframe} from '@components/popups/paymentVerification';\nimport {PasswordInputHelpers} from '@components/passwordInputField';\nimport SettingSection from '@components/settingSection';\nimport TelegramWebView from '@components/telegramWebView';\nimport {formatPhoneNumber} from '@helpers/formatPhoneNumber';\nimport PaymentSaveInformationRow from '@components/popups/paymentSaveInformationRow';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\n\nexport type PaymentCardDetails = {\n  cardNumber: string;\n  cardholderName: string;\n  expiryFull: string;\n  expiryMonth: string;\n  expiryYear: string;\n  cvc: string;\n  country: string;\n  zip: string;\n  save?: boolean;\n};\n\nexport type PaymentCardDetailsShort = {\n  title: string,\n  save?: boolean;\n  icon?: string;\n};\n\nexport type PaymentCardDetailsResult = PaymentCardDetails | PaymentCardDetailsShort;\n\nexport class InputFieldCorrected extends InputField {\n  private lastKeyDown: string;\n  private lastTransformed: ReturnType<typeof formatInputValueByPattern>;\n\n  constructor(public options: InputFieldOptions & {\n    formatMethod: typeof cardFormattingPatterns['cardNumber'],\n    validateMethod?: typeof validateCardNumber,\n    errorKeys?: {[code: string]: LangPackKey},\n    optional?: boolean,\n    onChange?: (transformed: InputFieldCorrected['lastTransformed']) => void,\n    onKeyDown?: (e: KeyboardEvent) => void\n  }) {\n    super(options);\n\n    // const handleIncomplete = (t?: any) => {\n    //   if(\n    //     (!lastTransformed.value && t) ||\n    //     lastTransformed.meta.autocorrectComplete ||\n    //     lastTransformed.meta.error ||\n    //     optional\n    //   ) {\n    //     return;\n    //   }\n\n\n    // };\n\n    this.input.addEventListener('keydown', this.onKeyDown);\n    this.input.addEventListener('input', this.onInput);\n    this.input.addEventListener('blur', this.onBlur);\n  }\n\n  private onKeyDown = (e: KeyboardEvent) => {\n    this.lastKeyDown = e.key;\n    this.options.onKeyDown?.(e);\n  };\n\n  private onInput = () => {\n    const value = this.value;\n    const deleting = this.lastKeyDown === 'Backspace' && (((this.lastTransformed && this.lastTransformed.value.length) || 0) - value.length) === 1;\n    const result = this.lastTransformed = formatInputValueByPattern({\n      value: value,\n      getPattern: this.options.formatMethod,\n      deleting,\n      input: this.input\n    });\n\n    const transformedValue = result.value;\n    if(transformedValue !== value) {\n      this.setValueSilently(transformedValue);\n\n      if(result.selection) {\n        (this.input as HTMLInputElement).selectionStart = result.selection.selectionStart;\n        (this.input as HTMLInputElement).selectionEnd = result.selection.selectionEnd;\n      }\n    }\n\n    this.validateNew(transformedValue, {ignoreIncomplete: true/* !result.meta.autocorrectComplete */});\n\n    this.options.onChange?.(result);\n  };\n\n  private onBlur = () => {\n    const value = this.lastTransformed?.value;\n    if(value) {\n      this.validateNew(value);\n    }\n  };\n\n  public update() {\n    this.onInput();\n  }\n\n  public validate = () => {\n    return this.validateNew();\n  };\n\n  public validateNew(\n    value = this.lastTransformed?.value ?? '',\n    t: any = {},\n    justReturn?: boolean\n  ) {\n    let result: ReturnType<InputFieldCorrected['options']['validateMethod']>;\n    if(this.options.validateMethod) {\n      result = this.options.validateMethod?.(value, t);\n    } else {\n      result = validateAnyIncomplete(this.lastTransformed, value, t);\n    }\n\n    if(result?.code) {\n      const langPackKey: LangPackKey = this.options.errorKeys?.[result.code];\n      !justReturn && this.setState(InputState.Error, langPackKey);\n      return false;\n    }\n\n    !justReturn && this.setState(InputState.Neutral);\n    return true;\n  }\n}\n\nexport function handleInputFieldsOnChange(inputFields: (CountryInputField | InputField | InputFieldCorrected)[], _onChange: (valid: boolean) => void) {\n  const onChange = () => {\n    const valid = inputFields.every((inputField) => {\n      return 'validateNew' in inputField ? inputField.validateNew(undefined, undefined, true) : inputField.isValid();\n    });\n\n    _onChange(valid);\n  };\n\n  inputFields.forEach((inputField) => {\n    if(inputField instanceof InputFieldCorrected) {\n      const original = inputField.options.onChange;\n      inputField.options.onChange = (...args: any[]) => {\n        // @ts-ignore\n        original?.(...args);\n        onChange();\n      };\n\n      if('update' in inputField) {\n        inputField.update();\n      }\n    } else {\n      inputField.input.addEventListener('input', onChange);\n    }\n  });\n\n  return {validate: onChange};\n}\n\nexport function createCountryZipFields(country?: boolean, zip?: boolean) {\n  let countryInputField: CountryInputField, postcodeInputField: InputFieldCorrected;\n  if(country || zip) {\n    if(country) countryInputField = new CountryInputField({\n      noPhoneCodes: true,\n      onCountryChange: () => {\n        postcodeInputField?.update();\n      },\n      required: true,\n      autocomplete: 'country'\n    });\n    if(zip) postcodeInputField = new InputFieldCorrected({\n      label: 'PaymentShippingZipPlaceholder',\n      plainText: true,\n      inputMode: 'numeric',\n      autocomplete: 'postal-code',\n      formatMethod: (/* ...args */) => {\n        const {country} = countryInputField.getSelected();\n        const iso2 = country?.iso2;\n        return cardFormattingPatterns.postalCodeFromCountry(iso2 && iso2.toUpperCase());\n      }\n    });\n  }\n\n  return {countryInputField, postcodeInputField};\n}\n\nexport type PaymentsNativeProvider = 'stripe' | 'smartglocal';\nexport type PaymentsNativeParams = {\n  need_country?: boolean,\n  need_zip?: boolean,\n  need_cardholder_name?: boolean,\n  publishable_key?: string, // stripe\n  public_token?: string, // smartglocal\n  gpay_params: string,\n  tokenize_url?: string\n};\nconst SUPPORTED_NATIVE_PROVIDERS: Set<PaymentsNativeProvider> = new Set(['stripe', 'smartglocal']);\n\nexport default class PopupPaymentCard extends PopupElement<{\n  finish: (obj: {token: any, card: PaymentCardDetailsResult}) => void\n}> {\n  protected telegramWebView: TelegramWebView;\n\n  constructor(\n    private paymentForm: PaymentsPaymentForm.paymentsPaymentForm,\n    private user: User.user,\n    private savedCard?: PaymentCardDetails,\n    private method?: PaymentFormMethod\n  ) {\n    super('popup-payment popup-payment-card', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: SUPPORTED_NATIVE_PROVIDERS.has(paymentForm.native_provider as PaymentsNativeProvider),\n      title: 'PaymentCardInfo'\n    });\n\n    if(SUPPORTED_NATIVE_PROVIDERS.has(paymentForm.native_provider as PaymentsNativeProvider) && !method) {\n      this.d();\n    } else {\n      const telegramWebView = this.telegramWebView = createVerificationIframe({\n        url: method?.url || paymentForm.url\n      });\n\n      telegramWebView.addEventListener('payment_form_submit', (data) => {\n        const cardOut = {title: data.title, save: false} as any as PaymentCardDetails;\n        this.dispatchEvent('finish', {\n          token: data.credentials,\n          card: cardOut\n        });\n\n        this.hide();\n\n        if(!method && paymentForm.pFlags.can_save_credentials) {\n          confirmationPopup({\n            titleLangKey: 'PaymentCardSavePaymentInformation',\n            descriptionLangKey: 'PaymentCardSavePaymentInformationInfoLine1',\n            button: {\n              langKey: 'Save'\n            }\n          }).then(() => {\n            cardOut.save = true;\n          }, noop);\n        }\n      });\n\n      // putPreloader(this.body, true);\n      this.body.append(telegramWebView.iframe);\n      this.show();\n      telegramWebView.onMount();\n    }\n  }\n\n  protected destroy() {\n    this.telegramWebView?.destroy();\n    return super.destroy();\n  }\n\n  private d() {\n    const savedCard = this.savedCard;\n    const cardSection = new SettingSection({name: 'PaymentInfo.Card.Title', noDelimiter: true, noShadow: true});\n\n    const nativeParams: PaymentsNativeParams = JSON.parse(this.paymentForm.native_params.data);\n\n    let lastBrand: string, brandIconTempId = 0, lastBrandImg: HTMLImageElement;\n    const setBrandIcon = (brand: string) => {\n      if(lastBrand === brand) {\n        return;\n      }\n\n      const tempId = ++brandIconTempId;\n      lastBrand = brand;\n\n      const path = getPaymentBrandIconPath(brand);\n      if(!path) {\n        if(lastBrandImg) {\n          lastBrandImg.remove();\n          lastBrandImg = undefined;\n        }\n\n        return;\n      }\n\n      const img = new Image();\n      img.classList.add('input-field-icon');\n      renderImageFromUrlPromise(img, path, false).then(() => {\n        if(brandIconTempId !== tempId) {\n          return;\n        }\n\n        if(lastBrandImg) {\n          lastBrandImg.replaceWith(img);\n        } else {\n          cardInputField.container.append(img);\n        }\n\n        lastBrandImg = img;\n      });\n    };\n    const cardInputField = new InputFieldCorrected({\n      label: 'PaymentCardNumber',\n      plainText: true,\n      inputMode: 'numeric',\n      autocomplete: 'cc-number',\n      formatMethod: cardFormattingPatterns.cardNumber,\n      validateMethod: validateCardNumber,\n      errorKeys: {\n        invalid: 'PaymentCard.Error.Invalid',\n        incomplete: 'PaymentCard.Error.Incomplete'\n      },\n      onChange: (transformed) => {\n        setBrandIcon(detectUnifiedCardBrand(transformed.value));\n        cvcInputField.update(); // format cvc\n      }\n    });\n\n    let nameInputField: InputField;\n    if(nativeParams.need_cardholder_name) nameInputField = new InputField({\n      label: 'Checkout.NewCard.CardholderNamePlaceholder',\n      maxLength: 255,\n      required: true,\n      autocomplete: 'cc-name'\n    });\n\n    const formatted = formatPhoneNumber(this.user.phone);\n    const expireInputField = new InputFieldCorrected({\n      label: 'SecureId.Identity.Placeholder.ExpiryDate',\n      plainText: true,\n      inputMode: 'numeric',\n      autocomplete: 'cc-exp',\n      formatMethod: cardFormattingPatterns.cardExpiry,\n      validateMethod: formatted.country.iso2 === 'RU' ? (str, options) => {\n        return validateCardExpiry(str, {\n          ...(options || {}),\n          date: new Date(2022, 0, 1)\n        });\n      } : validateCardExpiry\n    });\n\n    // handle autocomplete: 01/2345 -> 01/45\n    expireInputField.input.addEventListener('input', () => {\n      let value = expireInputField.value;\n      if(value.length < 5) {\n        return;\n      }\n\n      const splitted = value.split('/');\n      if(splitted[1].length !== 4) {\n        return;\n      }\n\n      value = [splitted[0], splitted[1].slice(2)].join('/');\n      expireInputField.setValueSilently(value);\n    }, {capture: true});\n\n    const cvcInputField = new InputFieldCorrected({\n      labelText: 'CVC',\n      plainText: true,\n      inputMode: 'numeric',\n      autocomplete: 'cc-csc',\n      name: 'cvc',\n      formatMethod: () => cardFormattingPatterns.cardCvc(cardInputField.value)\n      // validateMethod: (...args) => _5AH3.a.cardCvc(cardInputField.value)(...args)\n    });\n\n    const passwordHelpers = new PasswordInputHelpers(cvcInputField.container, cvcInputField.input as HTMLInputElement);\n\n    const switchFocusOrder: (InputFieldCorrected | InputField)[] = [\n      cardInputField,\n      expireInputField,\n      cvcInputField,\n      nameInputField\n    ].filter(Boolean);\n    switchFocusOrder.forEach((inputField) => {\n      const onKeyDown = (e: KeyboardEvent) => {\n        if(!inputField.value && e.key === 'Backspace') {\n          const previousInputField = switchFocusOrder[switchFocusOrder.indexOf(inputField) - 1];\n          if(previousInputField) {\n            // previousInputField.value = previousInputField.value.slice(0, -1);\n            placeCaretAtEnd(previousInputField.input, true);\n          }\n        }\n      };\n\n      if(inputField instanceof InputFieldCorrected) {\n        inputField.options.onKeyDown = onKeyDown;\n\n        const original = inputField.options.onChange;\n        inputField.options.onChange = (transformed) => {\n          original?.(transformed);\n\n          if(inputField.input.ownerDocument.activeElement === inputField.input && transformed.meta.autocorrectComplete) {\n            for(let i = switchFocusOrder.indexOf(inputField), length = switchFocusOrder.length; i < length; ++i) {\n              const nextInputField = switchFocusOrder[i];\n              if(\n                nextInputField instanceof InputFieldCorrected ?\n                !nextInputField.validateNew(undefined, undefined, true) :\n                !nextInputField.value\n              ) {\n                placeCaretAtEnd(nextInputField.input, true);\n                break;\n              }\n            }\n          }\n        };\n      } else {\n        inputField.input.addEventListener('keydown', onKeyDown);\n      }\n    });\n\n    const inputFieldsRow = document.createElement('div');\n    inputFieldsRow.classList.add('input-fields-row');\n    inputFieldsRow.append(expireInputField.container, cvcInputField.container);\n\n    const form = document.createElement('form');\n    form.append(...[\n      cardInputField.container,\n      inputFieldsRow,\n      nameInputField?.container\n    ].filter(Boolean))\n\n    cardSection.content.append(form);\n\n    let billingSection: SettingSection;\n    // let saveCheckboxField: CheckboxField;\n    const {countryInputField, postcodeInputField} = createCountryZipFields(nativeParams.need_country, nativeParams.need_zip);\n    if(nativeParams.need_country || nativeParams.need_zip) {\n      billingSection = new SettingSection({name: 'PaymentInfo.Billing.Title', noDelimiter: true, noShadow: true});\n\n      // const inputFieldsRow2 = inputFieldsRow.cloneNode() as HTMLElement;\n      // inputFieldsRow2.append(countryInputField.container, postcodeInputField.container);\n      // billingSection.content.append(inputFieldsRow2);\n      billingSection.content.append(...[countryInputField, postcodeInputField].filter(Boolean).map((i) => i.container));\n    }\n\n    const canSave = !!this.paymentForm.pFlags.can_save_credentials;\n    let savePaymentInformation = canSave;\n    const saveRow = wrapSolidComponent(() => (\n      <PaymentSaveInformationRow\n        checked={canSave}\n        disabled={!canSave}\n        title=\"PaymentCardSavePaymentInformation\"\n        subtitle={canSave ? 'PaymentCardSavePaymentInformationInfoLine1' : 'Checkout.2FA.Text'}\n        onChange={(checked) => savePaymentInformation = checked}\n      />\n    ), this.middlewareHelper.get());\n\n    (billingSection || cardSection).content.append(saveRow);\n\n    this.scrollable.append(...[cardSection, billingSection].filter(Boolean).map((s) => s.container));\n\n    const payButton = PaymentButton({\n      key: 'PaymentInfo.Done',\n      onClick: async() => {\n        const data: PaymentCardDetails = {\n          cardNumber: cardInputField.value,\n          expiryFull: expireInputField.value,\n          expiryMonth: expireInputField.value.split('/')[0],\n          expiryYear: expireInputField.value.split('/')[1],\n          cvc: cvcInputField.value,\n\n          cardholderName: nameInputField?.value,\n          country: countryInputField?.value,\n          zip: postcodeInputField?.value,\n\n          save: savePaymentInformation\n        };\n\n        const nativeProvider: PaymentsNativeProvider = this.paymentForm.native_provider as any;\n        let out: PaymentsCredentialsToken;\n        if(nativeProvider === 'stripe') {\n          const url = new URL('https://api.stripe.com/v1/tokens');\n          url.search = new URLSearchParams({\n            'card[number]': data.cardNumber,\n            'card[exp_month]': data.expiryMonth,\n            'card[exp_year]': data.expiryYear,\n            'card[cvc]': data.cvc,\n            'card[address_zip]': data.zip,\n            'card[address_country]': data.country,\n            'card[name]': data.cardholderName\n          }).toString();\n\n          const response = await fetch(url.toString(), {\n            method: 'POST',\n            credentials: 'same-origin',\n            headers: {\n              'Content-Type': 'application/x-www-form-urlencoded',\n              'Authorization': `Bearer ${nativeParams.publishable_key}`\n            }\n          });\n\n          out = await response.json();\n        } else if(nativeProvider === 'smartglocal') {\n          const params = {\n            card: {\n              number: data.cardNumber.replace(/[^\\d]+/g, ''),\n              expiration_month: data.expiryMonth,\n              expiration_year: data.expiryYear,\n              security_code: data.cvc.replace(/[^\\d]+/g, '')\n            }\n          };\n\n          let url = /* DEBUG_PAYMENT_SMART_GLOCAL */false ?\n            'https://tgb-playground.smart-glocal.com/cds/v1/tokenize/card' :\n            'https://tgb.smart-glocal.com/cds/v1/tokenize/card';\n\n          const nativeTokenizeUrl = nativeParams.tokenize_url;\n          if(typeof(nativeTokenizeUrl) === 'string' &&\n              nativeTokenizeUrl.startsWith('https://') &&\n              nativeTokenizeUrl.endsWith('.smart-glocal.com/cds/v1/tokenize/card')) {\n            url = nativeTokenizeUrl;\n          }\n\n          const response = await fetch(url, {\n            method: 'POST',\n            headers: {\n              'Accept': 'application/json',\n              'Content-Type': 'application/json',\n              'X-PUBLIC-TOKEN': nativeParams.public_token\n            },\n            body: JSON.stringify(params)\n          });\n\n          const json: { // smartglocal\n            data: {\n              info: {\n                card_network: string,\n                card_type: string,\n                masked_card_number: string\n              },\n              token: string\n            },\n            status: 'ok'\n          } = await response.json();\n\n          out = {type: 'card', token: json.data.token}\n        }\n\n        this.dispatchEvent('finish', {token: out, card: data});\n        this.hide();\n      }\n    });\n\n    const inputFields = ([\n      cardInputField,\n      nameInputField,\n      expireInputField,\n      cvcInputField,\n      countryInputField,\n      postcodeInputField\n    ] as const).filter(Boolean);\n    handleInputFieldsOnChange(inputFields, (valid) => {\n      payButton.disabled = !valid;\n      // payButton.classList.toggle('btn-disabled', !valid);\n    });\n\n    if(savedCard) {\n      cardInputField.value = savedCard.cardNumber;\n      expireInputField.value = savedCard.expiryFull;\n      cvcInputField.value = savedCard.cvc;\n      nameInputField && (nameInputField.value = savedCard.cardholderName);\n      countryInputField && (countryInputField.value = savedCard.country);\n      postcodeInputField && (postcodeInputField.value = savedCard.zip);\n    }\n\n    this.body.append(this.btnConfirmOnEnter = payButton);\n\n    this.show();\n\n    if(!cardInputField.validateNew(undefined, undefined, true)) {\n      placeCaretAtEnd(cardInputField.input);\n    }\n  }\n}\n","import PopupElement from '.';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {AccountPassword, AccountTmpPassword} from '@layer';\nimport {InputState} from '@components/inputField';\nimport PasswordInputField from '@components/passwordInputField';\nimport SettingSection from '@components/settingSection';\nimport {PaymentButton} from '@components/popups/payment';\n\nexport default class PopupPaymentCardConfirmation extends PopupElement<{\n  finish: (tmpPassword: AccountTmpPassword) => void\n}> {\n  constructor(card: string, passwordState: AccountPassword) {\n    super('popup-payment popup-payment-card-confirmation', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      title: 'Checkout.PasswordEntry.Title'\n    });\n\n    const section = new SettingSection({noDelimiter: true, noShadow: true, caption: 'Checkout.PasswordEntry.Text', captionArgs: [card]});\n    const passwordInputField = new PasswordInputField({labelText: passwordState.hint ?? ''});\n    section.content.append(passwordInputField.container);\n    this.scrollable.append(section.container);\n\n    const onInput = () => {\n      payButton.disabled = !passwordInputField.value;\n      passwordInputField.setState(InputState.Neutral);\n    };\n\n    passwordInputField.input.addEventListener('input', onInput);\n\n    const payButton = PaymentButton({\n      key: 'Checkout.PasswordEntry.Pay',\n      onClick: async() => {\n        try {\n          const inputCheckPassword = await this.managers.passwordManager.getInputCheckPassword(passwordInputField.value, passwordState);\n          const tmpPassword = await this.managers.passwordManager.getTmpPassword(inputCheckPassword, 60);\n\n          this.dispatchEvent('finish', tmpPassword);\n          this.hide();\n        } catch(err) {\n          if((err as ApiError).type === 'PASSWORD_HASH_INVALID') {\n            (err as ApiError).handled = true;\n            passwordInputField.setError('PASSWORD_HASH_INVALID');\n          }\n\n          throw err;\n        }\n      }\n    });\n    this.body.append(this.btnConfirmOnEnter = payButton);\n\n    onInput();\n\n    this.show();\n\n    placeCaretAtEnd(passwordInputField.input);\n  }\n}\n","import PopupElement from '.';\nimport {i18n} from '@lib/langPack';\nimport {PaymentsPaymentForm, User} from '@layer';\nimport PopupPayment from '@components/popups/payment';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport PopupPaymentCard, {PaymentCardDetails, PaymentCardDetailsResult} from '@components/popups/paymentCard';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport Row from '@components/rowTsx';\nimport {JSX} from 'solid-js';\n\nfunction PaymentMethodRow(props: {\n  checked?: boolean,\n  onSelect: () => void,\n  title: JSX.Element\n}) {\n  return (\n    <Row\n      class=\"payment-item-row\"\n      noWrap\n    >\n      <Row.Title>{props.title}</Row.Title>\n      <Row.CheckboxField>\n        <CheckboxFieldTsx\n          class=\"disable-hover\"\n          checked={props.checked}\n          round\n          onChange={() => props.onSelect()}\n        />\n      </Row.CheckboxField>\n    </Row>\n  );\n}\n\nexport default class PopupPaymentMethods extends PopupElement {\n  private promise: CancellablePromise<PopupPaymentCard>;\n\n  constructor(\n    private paymentForm: PaymentsPaymentForm.paymentsPaymentForm,\n    private user: User.user,\n    private savedCard?: PaymentCardDetails\n  ) {\n    super('popup-payment popup-payment-methods', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      title: 'PaymentMethod'\n    });\n\n    this.promise = deferredPromise();\n    this.addEventListener('closeAfterTimeout', () => {\n      this.promise.reject();\n    });\n    this.construct();\n  }\n\n  public waitForMethodPopup() {\n    return this.promise;\n  }\n\n  private _construct() {\n    const selectMethod = (onClick: () => PopupPaymentCard) => {\n      this.hide();\n      this.promise.resolve(onClick());\n    };\n\n    const savedCardTitle = this.savedCard && PopupPayment.getCardDetailsInfo(this.savedCard).str;\n\n    return (\n      <>\n        <PaymentMethodRow\n          title={i18n('PaymentMethodNewCard')}\n          onSelect={() => selectMethod(() => PopupElement.createPopup(\n            PopupPaymentCard,\n            this.paymentForm,\n            this.user\n          ))}\n        />\n        {savedCardTitle && (\n          <PaymentMethodRow\n            checked\n            title={savedCardTitle}\n            onSelect={() => selectMethod(() => undefined)}\n          />\n        )}\n        {this.paymentForm.additional_methods.map((method) => (\n          <PaymentMethodRow\n            title={wrapEmojiText(method.title)}\n            onSelect={() => selectMethod(() => PopupElement.createPopup(\n              PopupPaymentCard,\n              this.paymentForm,\n              this.user,\n              undefined,\n              method\n            ))}\n          />\n        ))}\n      </>\n    );\n  }\n\n  private async construct() {\n    this.appendSolid(() => this._construct());\n    this.show();\n  }\n}\n","import {EMAIL_REG_EXP} from '.';\n\nexport default function matchEmail(text: string) {\n  return !text ? null : text.match(EMAIL_REG_EXP);\n}\n","import PopupElement from '.';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {InputInvoice, PaymentRequestedInfo, PaymentsPaymentForm, PaymentsValidatedRequestedInfo} from '@layer';\nimport matchEmail from '@lib/richTextProcessor/matchEmail';\nimport CountryInputField from '@components/countryInputField';\nimport InputField from '@components/inputField';\nimport SettingSection from '@components/settingSection';\nimport TelInputField from '@components/telInputField';\nimport {PaymentButton} from '@components/popups/payment';\nimport {createCountryZipFields, handleInputFieldsOnChange, InputFieldCorrected} from '@components/popups/paymentCard';\nimport PaymentSaveInformationRow from '@components/popups/paymentSaveInformationRow';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\n\nexport type PaymentShippingAddress = PaymentRequestedInfo;\n\ntype ShippingFocusField = 'name' | 'email' | 'phone';\n\nexport default class PopupPaymentShipping extends PopupElement<{\n  finish: (o: {shippingAddress: PaymentShippingAddress, requestedInfo: PaymentsValidatedRequestedInfo}) => void\n}> {\n  constructor(\n    private paymentForm: PaymentsPaymentForm.paymentsPaymentForm,\n    private inputInvoice: InputInvoice,\n    private focus?: ShippingFocusField\n  ) {\n    super('popup-payment popup-payment-shipping', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      title: 'PaymentShippingInfo'\n    });\n\n    this.d();\n  }\n\n  private d() {\n    const paymentForm = this.paymentForm;\n    const invoice = paymentForm.invoice;\n    const savedInfo = this.paymentForm.saved_info;\n\n    let addressSection: SettingSection,\n      address1InputField: InputField,\n      address2InputField: InputField,\n      cityInputField: InputField,\n      stateInputField: InputField,\n      countryInputField: CountryInputField,\n      postcodeInputField: InputFieldCorrected;\n    if(invoice.pFlags.shipping_address_requested) {\n      addressSection = new SettingSection({name: 'PaymentShippingAddress', noDelimiter: true, noShadow: true});\n      address1InputField = new InputField({label: 'PaymentShippingAddress1Placeholder', maxLength: 64, required: true});\n      address2InputField = new InputField({label: 'PaymentShippingAddress2Placeholder', maxLength: 64});\n      cityInputField = new InputField({label: 'PaymentShippingCityPlaceholder', maxLength: 64, required: true});\n      stateInputField = new InputField({label: 'PaymentShippingStatePlaceholder', maxLength: 64});\n      const res = createCountryZipFields(true, true);\n      countryInputField = res.countryInputField;\n      postcodeInputField = res.postcodeInputField;\n\n      addressSection.content.append(...[\n        address1InputField,\n        address2InputField,\n        cityInputField,\n        stateInputField,\n        countryInputField,\n        postcodeInputField\n      ].filter(Boolean).map((inputField) => inputField.container));\n    }\n\n    let receiverSection: SettingSection;\n    let nameInputField: InputField, emailInputField: InputField, telInputField: TelInputField;\n    if([invoice.pFlags.name_requested, invoice.pFlags.email_requested, invoice.pFlags.phone_requested].includes(true)) {\n      receiverSection = new SettingSection({name: 'PaymentShippingReceiver', noDelimiter: true, noShadow: true});\n\n      const validateEmail = () => {\n        const value = emailInputField.value;\n        const match = matchEmail(value);\n        if(!match || match[0].length !== value.length) {\n          return false;\n        }\n\n        return true;\n      };\n\n      const validatePhone = () => {\n        return !!telInputField.value.match(/\\d/);\n      };\n\n      if(invoice.pFlags.name_requested) nameInputField = new InputField({label: 'PaymentShippingName', maxLength: 256, required: true});\n      if(invoice.pFlags.email_requested) emailInputField = new InputField({label: 'PaymentShippingEmailPlaceholder', maxLength: 64, required: true, validate: validateEmail});\n      if(invoice.pFlags.phone_requested) telInputField = new TelInputField({required: true, validate: validatePhone});\n\n      receiverSection.content.append(...[\n        nameInputField,\n        emailInputField,\n        telInputField\n      ].filter(Boolean).map((inputField) => inputField.container));\n    }\n\n    let savePaymentInformation = true;\n    const saveRow = wrapSolidComponent(() => (\n      <PaymentSaveInformationRow\n        checked\n        title=\"PaymentShippingSave\"\n        subtitle=\"PaymentShippingSaveInfo\"\n        onChange={(checked) => savePaymentInformation = checked}\n      />\n    ), this.middlewareHelper.get());\n\n    (receiverSection || addressSection).content.append(saveRow);\n\n    this.scrollable.append(...[addressSection, receiverSection].filter(Boolean).map((section) => section.container));\n\n    const payButton = PaymentButton({\n      key: 'PaymentInfo.Done',\n      onClick: async() => {\n        const selectedCountry = countryInputField && countryInputField.getSelected().country;\n        const data: PaymentShippingAddress = {\n          _: 'paymentRequestedInfo',\n          shipping_address: selectedCountry && {\n            _: 'postAddress',\n            street_line1: address1InputField.value,\n            street_line2: address2InputField.value,\n            city: cityInputField.value,\n            state: stateInputField.value,\n            // country: countryInputField.value,\n            country_iso2: selectedCountry?.iso2,\n            post_code: postcodeInputField.value\n          },\n          name: nameInputField?.value,\n          email: emailInputField?.value,\n          phone: telInputField?.value\n        };\n\n        try {\n          const requestedInfo = await this.managers.appPaymentsManager.validateRequestedInfo(this.inputInvoice, data, savePaymentInformation);\n\n          this.dispatchEvent('finish', {\n            shippingAddress: data,\n            requestedInfo\n          });\n\n          this.hide();\n        } catch(err: any) {\n          const errorMap: {[err in ErrorType]?: InputField} = {\n            ADDRESS_STREET_LINE1_INVALID: address1InputField,\n            ADDRESS_STREET_LINE2_INVALID: address2InputField,\n            ADDRESS_COUNTRY_INVALID: countryInputField,\n            ADDRESS_CITY_INVALID: cityInputField,\n            ADDRESS_STATE_INVALID: stateInputField,\n            ADDRESS_POSTCODE_INVALID: postcodeInputField,\n\n            REQ_INFO_NAME_INVALID: nameInputField,\n            REQ_INFO_EMAIL_INVALID: emailInputField,\n            REQ_INFO_PHONE_INVALID: telInputField\n          };\n\n          const inputField = errorMap[(err as ApiError).type];\n          if(inputField) {\n            inputField.setError();\n            (err as ApiError).handled = true;\n          }\n\n          throw err;\n        }\n      }\n    });\n    this.body.append(this.btnConfirmOnEnter = payButton);\n\n    if(savedInfo) {\n      const shippingAddress = savedInfo.shipping_address;\n      if(shippingAddress) {\n        address1InputField.value = shippingAddress.street_line1;\n        address2InputField.value = shippingAddress.street_line2;\n        cityInputField.value = shippingAddress.city;\n        stateInputField.value = shippingAddress.state;\n        countryInputField.selectCountryByIso2(shippingAddress.country_iso2);\n        postcodeInputField.value = shippingAddress.post_code;\n      }\n\n      savedInfo.name && nameInputField && (nameInputField.value = savedInfo.name);\n      savedInfo.email && emailInputField && (emailInputField.value = savedInfo.email);\n      savedInfo.phone && telInputField && (telInputField.value = savedInfo.phone);\n    }\n\n    const {validate} = handleInputFieldsOnChange([\n      address1InputField,\n      address2InputField,\n      cityInputField,\n      stateInputField,\n      countryInputField,\n      postcodeInputField,\n      nameInputField,\n      emailInputField,\n      telInputField\n    ].filter(Boolean), (valid) => {\n      payButton.disabled = !valid;\n    });\n\n    validate();\n\n    this.show();\n\n    let focusField: InputField;\n    if(this.focus) {\n      const focusMap: {[field in ShippingFocusField]?: InputField} = {\n        name: nameInputField,\n        email: emailInputField,\n        phone: telInputField\n      };\n\n      focusField = focusMap[this.focus];\n    } else {\n      focusField = address1InputField;\n    }\n\n    if(focusField) {\n      placeCaretAtEnd(focusField.input);\n    }\n  }\n}\n","import PopupElement from '.';\nimport accumulate from '@helpers/array/accumulate';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {PaymentsPaymentForm, PaymentsValidatedRequestedInfo, ShippingOption} from '@layer';\nimport {PaymentButton} from '@components/popups/payment';\nimport RadioFormTsx from '@components/radioFormTsx';\nimport Section from '@components/section';\nimport {createComponent} from 'solid-js';\n\nexport default class PopupPaymentShippingMethods extends PopupElement<{\n  finish: (shippingOption: ShippingOption) => void\n}> {\n  constructor(\n    private paymentForm: PaymentsPaymentForm,\n    private requestedInfo: PaymentsValidatedRequestedInfo,\n    private shippingOption: ShippingOption\n  ) {\n    super('popup-payment popup-payment-shipping-methods', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      title: 'PaymentShippingMethod'\n    });\n\n    this.d();\n  }\n\n  private d() {\n    const selectedShippingId = this.shippingOption?.id || this.requestedInfo.shipping_options[0].id;\n    const values = this.requestedInfo.shipping_options.map((shippingOption) => ({\n      checked: shippingOption.id === selectedShippingId,\n      text: shippingOption.title,\n      value: shippingOption.id,\n      subtitle: paymentsWrapCurrencyAmount(\n        accumulate(shippingOption.prices.map(({amount}) => +amount), 0),\n        this.paymentForm.invoice.currency\n      )\n    }));\n\n    let lastShippingId = selectedShippingId;\n    this.appendSolid(() => createComponent(Section, {\n      name: 'PaymentCheckoutShippingMethod',\n      noDelimiter: true,\n      noShadow: true,\n      get children() {\n        return createComponent(RadioFormTsx<string>, {\n          name: 'shipping-method',\n          values,\n          onChange: (value) => {\n            lastShippingId = value;\n          }\n        });\n      }\n    }));\n\n    const payButton = PaymentButton({\n      key: 'PaymentInfo.Done',\n      onClick: () => {\n        this.dispatchEvent('finish', this.requestedInfo.shipping_options.find((option) => option.id === lastShippingId));\n        this.hide();\n      }\n    });\n    this.body.append(this.btnConfirmOnEnter = payButton);\n\n    this.show();\n  }\n}\n","import ListenerSetter from '@helpers/listenerSetter';\nimport {onCleanup} from 'solid-js';\n\nexport default function createListenerSetter() {\n  const listenerSetter = new ListenerSetter();\n  onCleanup(() => listenerSetter.removeAll());\n  return listenerSetter;\n}\n","import {createResource, onCleanup, Ref} from 'solid-js';\nimport PeerTitle from '@components/peerTitle';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {attachClassName} from '@helpers/solid/classname';\nimport createListenerSetter from '../helpers/solid/createListenerSetter';\n\nexport const PeerTitleTsx = (props: {\n  ref?: Ref<HTMLElement>;\n  class?: string\n  peerId: PeerId,\n  threadId?: number,\n  onlyFirstName?: boolean,\n  username?: boolean,\n  limitSymbols?: number,\n  withIcons?: boolean,\n  onClick?: () => void\n}) => {\n  const peerTitle = new PeerTitle();\n  const listenerSetter = createListenerSetter();\n\n  props.ref instanceof Function && props.ref?.(peerTitle.element); // solid will always make it a function\n\n  const [loaded] = createResource(\n    () => [props.peerId, props.threadId],\n    async([peerId, threadId]) => {\n      await peerTitle.update({\n        peerId,\n        threadId,\n        dialog: false,\n        onlyFirstName: props.onlyFirstName,\n        username: props.username,\n        limitSymbols: props.limitSymbols,\n        withIcons: props.withIcons\n      });\n      if(props.onClick) {\n        attachClickEvent(peerTitle.element, props.onClick, {listenerSetter});\n      }\n      return true;\n    }\n  );\n\n  attachClassName(peerTitle.element, () => props.class);\n\n  return (\n    <>\n      {loaded() && peerTitle.element}\n    </>\n  );\n};\n","import clamp from '@helpers/number/clamp';\nimport OverlayClickHandler from '@helpers/overlayClickHandler';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport classNames from '@helpers/string/classNames';\nimport {createRoot, createSignal, onMount, JSX} from 'solid-js';\nimport {Portal} from 'solid-js/web';\nimport {IconTsx} from '@components/iconTsx';\nimport SetTransition from '@components/singleTransition';\n\nconst KEEP_TOOLTIP = true;\nconst tooltipOverlayClickHandler = new OverlayClickHandler(undefined, true);\nexport default function showTooltip({\n  element,\n  class: className,\n  container = element.parentElement,\n  vertical,\n  textElement,\n  subtitleElement,\n  paddingX = 0,\n  offsetY = 0,\n  centerVertically,\n  onClose,\n  icon,\n  auto,\n  // Mount into the active window's body so a tooltip shown while the client is popped out renders in\n  // the Document PiP window. Falls back to the main body when not popped out — same as before.\n  mountOn = getOverlayRoot(),\n  relative,\n  absolute,\n  lighter,\n  rightElement,\n  useOverlay = mountOn === getOverlayRoot()\n}: {\n  element: HTMLElement,\n  class?: string,\n  container?: HTMLElement,\n  vertical: 'top' | 'bottom',\n  textElement?: HTMLElement | DocumentFragment,\n  subtitleElement?: HTMLElement | DocumentFragment,\n  rightElement?: JSX.Element,\n  paddingX?: number,\n  offsetY?: number,\n  centerVertically?: boolean,\n  onClose?: () => void,\n  icon?: Icon,\n  auto?: boolean,\n  mountOn?: HTMLElement,\n  relative?: boolean,\n  // Position absolutely within `mountOn` (a positioned ancestor) instead of `fixed` to the viewport, so\n  // the tooltip scrolls with its anchor and is clipped by the scroll container rather than floating over\n  // fixed chrome (topbar). `mountOn` must be the offset parent (e.g. the bubble the tooltip anchors to).\n  absolute?: boolean,\n  lighter?: boolean, // When opening a tooltip in dark mode on a surface\n  useOverlay?: boolean\n}) {\n  const containerRect = !relative && container.getBoundingClientRect();\n  const elementRect = !relative &&  element.getBoundingClientRect();\n  const mountRect = absolute && mountOn.getBoundingClientRect();\n\n  let close: () => void;\n  createRoot((dispose) => {\n    const [getRect, setRect] = createSignal<DOMRect>();\n\n    const getStyle = (): JSX.CSSProperties => {\n      const css: JSX.CSSProperties = {\n        'max-width': Math.min(containerRect.width - paddingX * 2, 320) + 'px'\n      };\n\n      // when anchored inside `mountOn`, switch to absolute so the tooltip travels with the scroll\n      if(absolute) css.position = 'absolute';\n\n      const rect = getRect();\n      if(!rect) {\n        return css;\n      }\n\n      // everything below is computed in viewport space, then shifted into `mountOn`'s frame for absolute mode\n      const mountLeft = absolute ? mountRect.left : 0;\n      const mountTop = absolute ? mountRect.top : 0;\n\n      const minX = Math.min(containerRect.left + paddingX, containerRect.right);\n      const maxX = Math.max(containerRect.left, containerRect.right - Math.min(containerRect.width, rect.width) - paddingX);\n\n      const centerX = elementRect.left + (elementRect.width - rect.width) / 2;\n      const left = clamp(centerX, minX, maxX);\n      const verticalOffset = 12;\n      if(vertical === 'top') css.top = (centerVertically ? elementRect.top + elementRect.height / 2 : elementRect.top) - rect.height - verticalOffset + offsetY - mountTop + 'px';\n      else css.top = elementRect.bottom + verticalOffset - mountTop + 'px';\n      css.left = left - mountLeft + 'px';\n\n      const notchCenterX = elementRect.left + (elementRect.width - 19) / 2;\n      css['--notch-offset'] = notchCenterX - left + 'px';\n\n      return css;\n    };\n\n    let div: HTMLDivElement;\n    const tooltip = (\n      <div\n        ref={div}\n        class={classNames('tooltip', 'tooltip-' + vertical, icon && 'tooltip-with-icon', className, lighter && 'tooltip-lighter')}\n        style={!relative && getStyle()}\n      >\n        <div class=\"tooltip-part tooltip-background\"></div>\n        <span class=\"tooltip-part tooltip-notch\"></span>\n        <div class=\"tooltip-part tooltip-text\">\n          {icon && <IconTsx icon={icon} class=\"tooltip-icon\" />}\n          {subtitleElement ? (\n            <>\n              <div>{textElement}</div>\n              <div class=\"tooltip-subtitle\">{subtitleElement}</div>\n            </>\n          ) : textElement}\n        </div>\n        {rightElement && <div class=\"tooltip-part tooltip-right\">{rightElement}</div>}\n      </div>\n    );\n\n    <Portal mount={mountOn}>\n      {tooltip}\n    </Portal>\n\n    onMount(() => {\n      !relative && setRect(div.getBoundingClientRect());\n      div.classList.add('mounted');\n      SetTransition({\n        element: div,\n        className: 'is-visible',\n        duration: 200,\n        useRafs: 2,\n        forwards: true\n      });\n    });\n\n    let closed = false;\n    const onToggle = (open: boolean) => {\n      if(open) {\n        return;\n      }\n\n      closed = true;\n      clearTimeout(timeout);\n      SetTransition({\n        element: div,\n        className: 'is-visible',\n        duration: 200,\n        forwards: false,\n        onTransitionEnd: () => {\n          onClose?.();\n          dispose();\n        }\n      });\n    };\n\n    close = () => {\n      if(closed) {\n        return;\n      }\n\n      if(useOverlay) tooltipOverlayClickHandler.close();\n      else onToggle(false);\n    };\n\n    const timeout = KEEP_TOOLTIP && !auto ? 0 : window.setTimeout(close, 3000);\n\n    useOverlay && Promise.resolve().then(() => {\n      tooltipOverlayClickHandler.open(mountOn);\n      tooltipOverlayClickHandler.addEventListener('toggle', onToggle, {once: true});\n    });\n  });\n\n  return {close};\n}\n","import {ComponentProps, For, JSX, splitProps, untrack} from 'solid-js';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {AvatarNew} from '@components/avatarNew';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport classNames from '@helpers/string/classNames';\n\nimport styles from '@components/table.module.scss';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport Button from '@components/buttonTsx';\nimport showTooltip from '@components/tooltip';\n\nexport type TableRow = [LangPackKey | JSX.Element, JSX.Element];\n\nconst keyCellClass = classNames(styles.cell, styles.key);\n\nexport default function Table(props: {\n  class?: string,\n  content: TableRow[]\n  boldKey?: boolean\n  footer?: JSX.Element\n  footerClass?: string\n  cellClass?: string\n  keyCellClass?: string\n}) {\n  return (\n    <table\n      class={classNames(\n        styles.table,\n        props.boldKey && styles.boldKey,\n        props.class\n      )}\n    >\n      <For each={props.content}>\n        {([key, value]) => (\n          <tr class={/* @once */ styles.row}>\n            <td class={classNames(keyCellClass, props.cellClass, props.keyCellClass)}>\n              {typeof key === 'string' ? i18n(key as LangPackKey) : key}\n            </td>\n            <td class={classNames(styles.cell, props.cellClass)}>\n              <div class={/* @once */ styles.value}>\n                {value}\n              </div>\n            </td>\n          </tr>\n        )}\n      </For>\n      {props.footer && (\n        <tr class={/* @once */ styles.row}>\n          <td class={props.footerClass ?? classNames(styles.cell, props.cellClass)} colspan={2}>\n            {props.footer}\n          </td>\n        </tr>\n      )}\n    </table>\n  );\n}\n\nexport function TablePeer(props: {\n  peerId: PeerId,\n  onClick?: () => void\n}) {\n  const avatar = untrack(() => AvatarNew({peerId: props.peerId, size: 24}));\n  return (\n    <div\n      class={/* @once */ styles.peer}\n      onClick={props.onClick}\n    >\n      {props.peerId === NULL_PEER_ID ? (\n        <>\n          <div class=\"popup-star-gift-info-anonymous\">\n            <img src=\"assets/img/anon_paid_reaction.png\" alt=\"Anonymous\" />\n          </div>\n          {i18n('StarGiftHiddenUser')}\n        </>\n      ) : (\n        <>\n          {avatar.element}\n          <PeerTitleTsx peerId={props.peerId} />\n        </>\n      )}\n    </div>\n  );\n}\n\nexport function TableButton(props: ComponentProps<typeof Button>) {\n  return (\n    <Button\n      {...props}\n      class={/* @once */ styles.button}\n    />\n  )\n}\n\nexport function TableButtonWithTooltip(props: ComponentProps<typeof Button> & {\n  tooltipClass?: string\n  tooltipTextElement?: HTMLElement\n}) {\n  const [, rest] = splitProps(props, ['tooltipClass', 'tooltipTextElement']);\n  return (\n    <Button\n      {...rest}\n      class={classNames(rest.class, styles.button)}\n      onClick={(evt) => {\n        props.onClick?.(evt);\n        if(props.tooltipTextElement) showTooltip({\n          element: evt.target as HTMLElement,\n          vertical: 'top',\n          container: document.body,\n          class: props.tooltipClass,\n          textElement: props.tooltipTextElement\n        });\n      }}\n    />\n  )\n}\n","import PopupElement from '.';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {formatFullSentTime} from '@helpers/date';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport maybe2x from '@helpers/maybe2x';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {InputInvoice, MessageMedia, PaymentsPaymentForm, PaymentsPaymentReceipt, StarsTransaction, Message, MessageExtendedMedia, Photo, Document, ChatInvite, StarsSubscription, Chat, MessageAction, Boost, WebDocument} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {replaceButtonIcon} from '@components/button';\nimport {putPreloader} from '@components/putPreloader';\nimport Table, {TablePeer} from '@components/table';\nimport {toastNew} from '@components/toast';\nimport PopupPayment, {PopupPaymentResult} from '@components/popups/payment';\nimport PopupStars, {getExamplesAnchor, getStarsTransactionTitleAndMedia, StarsAmount, StarsBalance, StarsChange} from '@components/popups/stars';\nimport {JSX} from 'solid-js';\nimport partition from '@helpers/array/partition';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport wrapTelegramUrlToAnchor from '@lib/richTextProcessor/wrapTelegramUrlToAnchor';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport AppMediaViewer from '@components/mediaViewer';\nimport {NULL_PEER_ID, TON_CURRENCY} from '@appManagers/constants';\nimport tsNow from '@helpers/tsNow';\nimport classNames from '@helpers/string/classNames';\nimport {useChat} from '@stores/peers';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport liteMode from '@helpers/liteMode';\nimport PeerTitle from '@components/peerTitle';\nimport rootScope from '@lib/rootScope';\nimport {IconTsx} from '@components/iconTsx';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport DEBUG from '@config/debug';\nimport makeError from '@helpers/makeError';\nimport bigInt from 'big-integer';\n\nconst TEST_FIRST_TIME = DEBUG && false;\n\nexport default class PopupStarsPay extends PopupElement<{\n  finish: (result: PopupPaymentResult) => void\n}> {\n  private paymentForm:\n    | PaymentsPaymentForm.paymentsPaymentFormStars\n    | PaymentsPaymentReceipt.paymentsPaymentReceiptStars\n    | PaymentsPaymentForm.paymentsPaymentFormStarGift;\n  private result: PopupPaymentResult;\n  private inputInvoice: InputInvoice;\n  private isReceipt: boolean;\n  private isTopUp: boolean;\n  private paidMedia: MessageMedia.messageMediaPaidMedia;\n  private message: Message.message;\n  private peerId: PeerId;\n  private transaction: StarsTransaction;\n  private chatInvite: ChatInvite.chatInvite;\n  private subscription: StarsSubscription;\n  private isOutGift: boolean;\n  private boost: Boost;\n  private noShowIfStars: boolean;\n  private purpose: ConstructorParameters<typeof PopupPayment>[0]['purpose'];\n\n  private onConfirm: () => void;\n\n  constructor(options: ConstructorParameters<typeof PopupPayment>[0]) {\n    super('popup-stars popup-stars-pay', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      footer: true,\n      withConfirm: true,\n      title: true,\n      old: true\n    });\n\n    safeAssign(this, options);\n    this.footer.classList.add('abitlarger');\n    this.result = 'cancelled';\n    let test = TEST_FIRST_TIME;\n\n    const onConfirm = this.onConfirm = async() => {\n      const {paymentForm} = this;\n      if(this.isReceipt || (!paymentForm && !this.chatInvite && !this.subscription)) {\n        this.hide();\n        return;\n      }\n\n      const isTon = paymentForm?.invoice.currency === TON_CURRENCY\n      const itemPrice = paymentForm ? +paymentForm.invoice.prices[0].amount : (this.chatInvite ? +this.chatInvite.subscription_pricing.amount : +this.subscription.pricing.amount)\n\n      const d = putPreloader(this.btnConfirm);\n      const toggle = toggleDisability([this.btnConfirm], true);\n      this.result = 'pending';\n\n      let result: Promise<any>;\n      if(test) {\n        test = false;\n        result = Promise.reject(makeError('BALANCE_TOO_LOW'));\n        // result = Promise.resolve();\n      } else if(this.subscription) {\n        result = this.managers.appPaymentsManager.changeStarsSubscription(\n          this.subscription.id,\n          !this.subscription.pFlags.canceled\n        );\n      } else {\n        const balance = await this.managers.appPaymentsManager[isTon ? 'getStarsStatusTon' : 'getStarsStatus']();\n        if(bigInt(balance.balance.amount as number).lt(itemPrice)) {\n          result = Promise.reject(makeError('BALANCE_TOO_LOW'));\n        } else {\n          result = this.managers.appPaymentsManager.sendStarsForm(\n            this.inputInvoice,\n            (paymentForm as PaymentsPaymentForm.paymentsPaymentFormStars)?.form_id || this.chatInvite.subscription_form_id\n          );\n        }\n      }\n\n      try {\n        await result;\n        this.result = 'paid';\n        this.hide();\n      } catch(err) {\n        let shouldRetry = false;\n        if((err as ApiError).type === 'BALANCE_TOO_LOW') {\n          PopupElement.createPopup(PopupStars, {\n            itemPrice,\n            paymentForm: paymentForm as PaymentsPaymentForm.paymentsPaymentFormStars,\n            ton: isTon,\n            onTopup: async() => {\n              await this.reloadForm();\n              onConfirm();\n            },\n            onCancel: () => {\n              this.result = 'cancelled';\n              this.hide();\n            },\n            purpose: this.purpose,\n            spendPurposePeerId: this.peerId\n          });\n        } else if((err as ApiError).type === 'FORM_EXPIRED') {\n          await this.reloadForm();\n          shouldRetry = true;\n        } else {\n          this.result = 'failed';\n        }\n\n        toggle();\n        d.remove();\n\n        if(shouldRetry) {\n          onConfirm();\n        }\n      }\n    };\n\n    attachClickEvent(this.btnConfirm, onConfirm, {listenerSetter: this.listenerSetter});\n  }\n\n  private get form() {\n    return this.paymentForm || this.transaction;\n  }\n\n  public hide() {\n    this.dispatchEvent('finish', this.result);\n    return super.hide();\n  }\n\n  private async reloadForm() {\n    if(!this.paymentForm) {\n      return;\n    }\n\n    this.paymentForm = await this.managers.appPaymentsManager.getPaymentForm(this.inputInvoice) as PaymentsPaymentForm.paymentsPaymentFormStars;\n  }\n\n  public setPaymentForm(paymentForm: PopupStarsPay['paymentForm']) {\n    this.paymentForm = paymentForm;\n    this.isReceipt = !!this.transaction || paymentForm?._ === 'payments.paymentReceiptStars';\n    this.isOutGift = !!this.transaction && !this.transaction.id;\n    this.construct();\n  }\n\n  private _construct(\n    image: HTMLElement,\n    _title: HTMLElement,\n    avatar: HTMLElement,\n    link?: string\n  ) {\n    if(!this.isReceipt && (!this.subscription || tsNow(true) > this.subscription.until_date)) {\n      this.header.append(StarsBalance() as HTMLElement);\n    }\n\n    this.footer.append(this.btnConfirm);\n    this.body.after(this.footer);\n    let amount: Long;\n    if(this.paymentForm) {\n      const labeledPrice = this.paymentForm.invoice.prices[0];\n      amount = labeledPrice.amount;\n    } else if(this.chatInvite) {\n      amount = this.chatInvite.subscription_pricing.amount;\n    } else if(this.subscription) {\n      amount = this.subscription.pricing.amount;\n    } else {\n      amount = formatStarsAmount(this.transaction.amount);\n    }\n\n    if(this.isReceipt) {\n      this.btnConfirm.append(i18n('OK'));\n    } else if(this.chatInvite) {\n      this.btnConfirm.append(i18n('Stars.Subscribe.Button'));\n      const terms = i18n('Stars.Subscribe.Terms');\n      terms.classList.add('popup-footer-caption');\n      this.btnConfirm.after(terms);\n    } else if(this.subscription) {\n      if(this.subscription.pFlags.canceled) {\n        this.btnConfirm.append(i18n('Stars.Subscription.Renew'));\n      } else {\n        this.btnConfirm.className = 'btn-primary btn-secondary btn-primary-transparent danger';\n        this.btnConfirm.append(i18n('Stars.Subscription.Cancel'));\n      }\n\n      if(this.subscription.until_date > tsNow(true)) {\n        const chat = useChat(this.peerId.toChatId());\n        if((chat as Chat.channel).pFlags.left) {\n          const btnFulfill = document.createElement('button');\n          btnFulfill.classList.add('btn-primary', 'btn-color-primary');\n          btnFulfill.append(i18n('Stars.Subscription.Fulfill'));\n          btnFulfill.style.marginTop = '.5rem';\n          attachClickEvent(btnFulfill, async() => {\n            const toggle = toggleDisability([this.btnConfirm, btnFulfill], true);\n            try {\n              await this.managers.appPaymentsManager.fulfillStarsSubscription(this.subscription.id);\n              hidePopupsWithCallback(() => {\n                appImManager.setInnerPeer({peerId: this.peerId});\n              });\n            } catch(err) {\n              console.error('fulfill error', err);\n              toggle();\n            }\n          }, {listenerSetter: this.listenerSetter});\n          this.btnConfirm.after(btnFulfill);\n        }\n      }\n    } else {\n      this.btnConfirm.append(i18n('Stars.ConfirmPurchaseButton', [amount]));\n      replaceButtonIcon(this.btnConfirm, 'star');\n    }\n\n    const hidePopupsWithCallback = (callback: () => void, e?: Event) => {\n      cancelEvent(e);\n      this.hide();\n      const starsPopups = PopupElement.getPopups(PopupStars);\n      starsPopups?.[0]?.hide();\n      this.hideWithCallback(callback);\n    };\n\n    let noStarsChange = false;\n    let title: JSX.Element, subtitle: JSX.Element;\n    if(this.transaction && this.transaction.pFlags.gift) {\n      title = i18n(this.isOutGift ? 'StarsGiftSent' : 'StarsGiftReceived');\n      subtitle = document.createDocumentFragment();\n      const anchor = getExamplesAnchor(hidePopupsWithCallback);\n      const title1 = new PeerTitle();\n      title1.update({peerId: this.peerId, wrapOptions: {middleware: this.middlewareHelper.get()}});\n      (subtitle as DocumentFragment).append(\n        i18n(this.isOutGift ? 'ActionGiftStarsSubtitle' : 'ActionGiftStarsSubtitleYou', [title1.element]),\n        ' ',\n        anchor\n      );\n    } else if(this.transaction?.extended_media) {\n      title = i18n('StarMediaPurchase');\n    } else if(this.paidMedia) {\n      const [photos, videos] = partition(this.paidMedia.extended_media, (extendedMedia) => {\n        if(extendedMedia._ === 'messageExtendedMedia') {\n          return extendedMedia.media._ !== 'messageMediaDocument';\n        } else {\n          return extendedMedia.video_duration === undefined;\n        }\n      });\n\n      const multiplePhotosLang = i18n('Stars.Unlock.Photos', [photos.length]);\n      const multipleVideosLang = i18n('Stars.Unlock.Videos', [videos.length]);\n\n      title = i18n('StarsConfirmPurchaseTitle');\n      subtitle = i18n(this.peerId.isUser() ? 'Stars.Unlock.FromBot' : 'Stars.Unlock', [\n        photos.length && videos.length ?\n          i18n('Stars.Unlock.Media', [multiplePhotosLang, multipleVideosLang]) :\n          (photos.length || videos.length) === 1 ? i18n(photos.length ? 'Stars.Unlock.Photo' : 'Stars.Unlock.Video') : (photos.length ? multiplePhotosLang : multipleVideosLang),\n        _title,\n        i18n('Stars.Unlock.Stars', [amount])\n      ]);\n    } else if(this.transaction && this.transaction.pFlags.reaction) {\n      title = i18n('StarsReactionTitle');\n    } else if(this.transaction?.giveaway_post_id) {\n      title = i18n(!this.transaction.id ? 'Stars' : 'StarsGiveawayPrizeReceived', [formatStarsAmount(this.transaction.amount)]);\n      if(!this.transaction.id) {\n        subtitle = (\n          <span class=\"popup-stars-pay-boosts\">\n            <IconTsx icon=\"boost_filled\" />\n            {i18n('BoostingBoostsCountTitle', [this.boost.multiplier || 1])}\n          </span>\n        );\n        noStarsChange = true;\n      }\n    } else if(this.form._ === 'payments.paymentFormStarGift') {\n      title = i18n('StarsConfirmPurchaseTitle');\n      subtitle = i18n(this.inputInvoice._ === 'inputInvoiceStarGiftTransfer' ? 'StarGiftConfirmTransferText' : 'StarGiftConfirmPurchaseText', [amount]);\n    } else if(this.inputInvoice?._ === 'inputInvoiceStarGiftDropOriginalDetails') {\n      title = i18n('StarGiftDropOriginalDetailsTitle');\n      subtitle = i18n('StarGiftDropOriginalDetailsText');\n    } else if(this.transaction && !this.form.title) {\n      title = i18n(this.transaction.subscription_period ? 'Stars.Subscription.Title' : 'Stars.TopUp');\n    } else if(this.chatInvite) {\n      title = i18n('Stars.Subscribe.Title');\n      _title.style.display = 'inline';\n      subtitle = i18n('Stars.Subscribe.Description', [_title, i18n('Stars.Unlock.Stars', [amount])]);\n    } else if(this.subscription) {\n      title = i18n('Stars.Subscription');\n      subtitle = i18n('Stars.Subscription.Fee', [StarsAmount({stars: amount}) as HTMLElement]);\n      (subtitle as HTMLElement).classList.add('secondary');\n    } else if(this.transaction?.paid_messages) {\n      title = i18n('PaidMessages.FeeForMessages', [this.transaction.paid_messages]);\n      if(!this.transaction.pFlags.refund && +amount > 0) {\n        subtitle = i18n('PaidMessages.YouReceiveWithCommissionNotice');\n        Promise.resolve(apiManagerProxy.getAppConfig()).then((config) => {\n          const intlElement = I18n.weakMap.get(subtitle as HTMLElement) as I18n.IntlElement;\n          intlElement.compareAndUpdate({\n            key: 'PaidMessages.YouReceiveWithCommissionNotice',\n            args: [Math.round(config.stars_paid_message_commission_permille / 10)]\n          })\n        });\n      }\n    } else {\n      title = this.isReceipt ? wrapEmojiText(this.form.title) : i18n('StarsConfirmPurchaseTitle');\n      subtitle = this.isReceipt ?\n        wrapEmojiText(this.form.description) :\n        i18n('StarsConfirmPurchaseText', [amount, wrapEmojiText((this.paymentForm as PaymentsPaymentForm.paymentsPaymentFormStars).title), _title]);\n    }\n\n    const transactionId = this.transaction?.id ?? (this.paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceiptStars)?.transaction_id;\n    const onTransactionClick = () => {\n      copyTextToClipboard(transactionId);\n      toastNew({langPackKey: 'StarsTransactionIDCopied'});\n    };\n\n    const messageAnchor = link && wrapTelegramUrlToAnchor(link);\n    if(messageAnchor) {\n      messageAnchor.textContent = link.replace('https://', '');\n      messageAnchor.onclick = (e) => hidePopupsWithCallback(() => appImManager.openUrl(link), e);\n    }\n\n    const makeTablePeer = (peerId: PeerId) => TablePeer({\n      peerId,\n      onClick: () => {\n        hidePopupsWithCallback(() => {\n          appImManager.setInnerPeer({\n            peerId,\n            stack: this.message ? {\n              peerId: this.message.peerId,\n              mid: this.message.mid\n            } : undefined\n          });\n        });\n      }\n    });\n\n    const tablePeer = (this.isReceipt || this.subscription) && makeTablePeer(this.peerId);\n    const isTon = this.transaction?.amount._ === 'starsTonAmount';\n\n    const transactionIdSpan = transactionId && (<span onClick={onTransactionClick}>{wrapRichText(transactionId, {entities: [{_: 'messageEntityCode', length: transactionId.length, offset: 0}]})}</span>);\n\n    let tableContent: Parameters<typeof Table>[0]['content'];\n    if(this.subscription) {\n      tableContent = [\n        ['Stars.Subscription', tablePeer],\n        ['Stars.Subscription.Subscribed', formatFullSentTime(this.subscription.until_date - this.subscription.pricing.period)],\n        ['Stars.Subscription.Renews', formatFullSentTime(this.subscription.until_date)]\n      ];\n    } else if(this.transaction?.giveaway_post_id) {\n      messageAnchor.replaceChildren(i18n('BoostingGiveaway'));\n      tableContent = [\n        ['BoostingFrom', tablePeer],\n        this.transaction.id && ['BoostingTo', makeTablePeer(rootScope.myId)],\n        [this.transaction.id ? 'BoostingGift' : 'Giveaway.Prize', i18n('Stars', [formatStarsAmount(this.transaction.amount)])],\n        ['BoostingReason', messageAnchor],\n        this.transaction.id && ['StarsTransactionID', transactionIdSpan],\n        ['StarsTransactionDate',  formatFullSentTime((this.form as PaymentsPaymentReceipt.paymentsPaymentReceiptStars).date, undefined, true)]\n      ];\n    } else if(this.transaction && this.transaction.pFlags.gift) {\n      tableContent = [\n        [this.isOutGift ? 'BoostingTo' : 'BoostingFrom', tablePeer]\n      ];\n      if(transactionIdSpan) {\n        tableContent.push(['StarsTransactionID', transactionIdSpan]);\n      }\n      tableContent.push(\n        ['StarsTransactionDate',  formatFullSentTime((this.form as PaymentsPaymentReceipt.paymentsPaymentReceiptStars).date, undefined, true)]\n      )\n    } else if(this.isReceipt) {\n      const realAmount = this.transaction?.paid_messages &&\n        !this.transaction.pFlags.refund &&\n        this.transaction.starref_amount &&\n        this.transaction.amount &&\n        +amount > 0 &&\n        (formatStarsAmount(this.transaction.starref_amount) + formatStarsAmount(this.transaction.amount));\n\n      tableContent = [\n        this.peerId ? [\n          this.transaction?.subscription_period ? 'Stars.Subscription' : 'BoostingTo',\n          tablePeer\n        ] : ['Stars.Via', _title],\n        realAmount && ['PaidMessages.FullPrice', <StarsChange reverse noSign inline stars={realAmount} ton={isTon} />],\n        this.transaction && (this.transaction.extended_media || this.transaction.pFlags.reaction) && messageAnchor && [this.transaction.pFlags.reaction ? 'Message' : 'StarsTransactionMedia', messageAnchor],\n        ['StarsTransactionID', transactionIdSpan],\n        ['StarsTransactionDate', formatFullSentTime((this.form as PaymentsPaymentReceipt.paymentsPaymentReceiptStars).date, undefined, true)]\n      ];\n    }\n\n    return (\n      <div class=\"popup-stars-pay-padding\">\n        {image}\n        <div class=\"popup-stars-pay-images\">\n          <div\n            class=\"popup-stars-pay-avatar\"\n            onClick={async() => {\n              if(!this.isReceipt || !this.transaction.extended_media) {\n                return;\n              }\n\n              const extendedMedia = this.transaction.extended_media;\n              const media = extendedMedia.map((messageMedia) => {\n                return (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo ||\n                  (messageMedia as MessageMedia.messageMediaDocument).document as Document.document;\n              });\n\n              const message = await this.managers.appMessagesManager.generateStandaloneOutgoingMessage(this.peerId);\n              message.media = {\n                _: 'messageMediaPaidMedia',\n                extended_media: extendedMedia.map((messageMedia) => {\n                  return {_: 'messageExtendedMedia', media: messageMedia};\n                }),\n                stars_amount: 0\n              };\n              message.id = getServerMessageId(this.transaction.msg_id);\n              message.mid = this.transaction.msg_id;\n\n              const targets: AppMediaViewer['target'][] = media.map((media, index) => {\n                return {element: null as HTMLElement, mid: 0, peerId: 0, index, message};\n              });\n\n              targets[0].element = avatar;\n\n              new AppMediaViewer(true)\n              .setSearchContext({peerId: 0, inputFilter: {_: 'inputMessagesFilterEmpty'}, useSearch: false})\n              .openMedia({\n                message,\n                target: targets[0].element,\n                fromRight: 0,\n                reverse: false,\n                prevTargets: [],\n                nextTargets: targets.slice(1)\n              });\n            }}\n          >{avatar}</div>\n        </div>\n        <div class=\"popup-stars-title\">{title}</div>\n        {tableContent && !this.subscription && !noStarsChange && (\n          <StarsChange\n            stars={!this.transaction ? -+amount : amount}\n            isRefund={!!this.transaction?.pFlags?.refund}\n            noSign={this.isOutGift}\n            ton={isTon}\n          />\n        )}\n        {subtitle && <div class={classNames('popup-stars-subtitle', tableContent && !this.subscription && !this.boost && 'mt')}>{subtitle}</div>}\n        {tableContent && (\n          <>\n            <Table class=\"popup-stars-pay-table\" content={tableContent.filter(Boolean)} />\n            <div class=\"popup-stars-pay-tos\">{i18n('Stars.TransactionTOS')}</div>\n            {this.subscription && (\n              <div class={classNames('popup-stars-pay-tos', 'popup-stars-pay-tos2', this.subscription.pFlags.canceled && 'danger')}>{\n                i18n(\n                  this.subscription.pFlags.canceled ?\n                    'Stars.Subscription.Cancelled' :\n                    'Stars.Subscription.Active',\n                  [formatFullSentTime(this.subscription.until_date)]\n                )\n              }</div>\n            )}\n          </>\n        )}\n      </div>\n    );\n  }\n\n  private async construct() {\n    if(this.chatInvite || this.paymentForm?._ === 'payments.paymentFormStarGift') {\n      this.peerId = NULL_PEER_ID;\n    } else if(this.paymentForm) {\n      this.peerId = this.paymentForm.bot_id.toPeerId(false);\n    } else if(this.subscription) {\n      this.peerId = getPeerId(this.subscription.peer);\n    } else if(this.transaction.peer._ === 'starsTransactionPeer') {\n      this.peerId = getPeerId(this.transaction.peer.peer);\n    }\n\n    const [image, {title, media}, link] = await Promise.all([\n      (async() => {\n        const img = document.createElement('img');\n        img.classList.add('popup-stars-image');\n        await renderImageFromUrlPromise(img, `assets/img/${maybe2x(this.boost ? 'stars' : 'stars_pay')}.png`);\n        return img;\n      })(),\n      (async() => {\n        const result = await getStarsTransactionTitleAndMedia({\n          transaction: this.transaction,\n          middleware: this.middlewareHelper.get(),\n          size: 90,\n          paidMedia: this.paidMedia,\n          paidMediaPeerId: this.message ? this.message.fwdFromId || this.message.fromId : this.peerId,\n          chatInvite: this.chatInvite,\n          subscription: this.subscription,\n          photo: this.form._ === 'payments.paymentFormStarGift' ? undefined : this.form?.photo as WebDocument.webDocument\n        });\n\n        if(this.boost) {\n          result.media = undefined;\n          // const img = document.createElement('img');\n          // await renderImageFromUrlPromise(img, `assets/img/${maybe2x('stars')}.png`);\n          // result.media = img;\n          // img.classList.add('popup-stars-pay-star');\n        } else if(this.transaction && (this.transaction.pFlags.gift || this.transaction.giveaway_post_id)) {\n          const size = 128;\n          result.media = await wrapLocalSticker({\n            width: size,\n            height: size,\n            assetName: 'Gift3',\n            middleware: this.middlewareHelper.get(),\n            loop: false,\n            autoplay: liteMode.isAvailable('stickers_chat')\n          }).then(async({container, promise}) => {\n            container.classList.add('popup-stars-pay-sticker');\n            await promise;\n            return container as HTMLDivElement;\n          });\n        } else {\n          result.media.classList.add('popup-stars-pay-item');\n        }\n\n        return result;\n      })(),\n      (async() => {\n        if(\n          (!this.transaction || (!this.transaction.extended_media && !this.transaction.pFlags.reaction && !this.transaction.giveaway_post_id)) ||\n          !this.peerId ||\n          this.peerId.isUser()\n        ) {\n          return;\n        }\n\n        const channelId = this.peerId.toChatId()\n        const serverMsgId = getServerMessageId(this.transaction.msg_id || this.transaction.giveaway_post_id)\n        return `https://t.me/c/${channelId}/${serverMsgId}`;\n      })()\n    ]);\n    this.body.classList.toggle('is-receipt', this.isReceipt);\n    this.appendSolid(() => this._construct(image, title, media, link));\n    if(this.noShowIfStars) {\n      this.onConfirm();\n    } else {\n      this.show();\n    }\n  }\n}\n","import {Component, createRoot} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport type SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {Middleware} from '@helpers/middleware';\n\ntype RenderComponentArgs<T extends object> = {\n  element?: HTMLElement,\n  Component: Component<T>,\n  middleware: Middleware,\n  HotReloadGuard?: typeof SolidJSHotReloadGuardProvider\n} & (keyof T extends never ? {props?: T} : {props: T});\n\nexport const renderComponent = <T extends object>({\n  element,\n  Component,\n  props,\n  middleware,\n  HotReloadGuard\n}: RenderComponentArgs<T>) => {\n  const ToRender = HotReloadGuard ?\n    () => <HotReloadGuard><Component {...(props || ({} as T))} /></HotReloadGuard> :\n    () => <Component {...(props || ({} as T))} />;\n\n  const dispose = element ?\n    render(() => <ToRender />, element) :\n    createRoot((dispose) => {<ToRender />; return dispose});\n\n  middleware.onDestroy(() => dispose());\n};\n","import PopupElement from '.';\nimport {createEffect, createRoot, createSignal, JSX, Show, Signal} from 'solid-js';\nimport Currencies from '@config/currencies';\nimport {FontFamily, FontFull, FontSize} from '@config/font';\nimport accumulate from '@helpers/array/accumulate';\nimport {getAppWindow} from '@helpers/appWindow';\nimport assumeType from '@helpers/assumeType';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport {detectUnifiedCardBrand} from '@helpers/cards/cardBrands';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {formatPhoneNumber} from '@helpers/formatPhoneNumber';\nimport makeError from '@helpers/makeError';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport safeAssign from '@helpers/object/safeAssign';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport ScrollSaver from '@helpers/scrollSaver';\nimport tsNow from '@helpers/tsNow';\nimport {AccountTmpPassword, Boost, ChatInvite, DocumentAttribute, InputInvoice, InputPaymentCredentials, LabeledPrice, Message, MessageAction, MessageMedia, PaymentRequestedInfo, PaymentSavedCredentials, PaymentsPaymentForm, PaymentsPaymentReceipt, PaymentsValidatedRequestedInfo, PostAddress, ShippingOption, StarsSubscription, StarsTransaction, User} from '@layer';\nimport I18n, {i18n, LangPackKey, _i18n} from '@lib/langPack';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport rootScope from '@lib/rootScope';\nimport {useUser} from '@stores/peers';\nimport {avatarNew} from '@components/avatarNew';\nimport Button from '@components/button';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport PeerTitle from '@components/peerTitle';\nimport {putPreloader} from '@components/putPreloader';\nimport Row from '@components/rowTsx';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport wrapPhoto from '@components/wrappers/photo';\nimport PopupPaymentCard, {PaymentCardDetails, PaymentCardDetailsResult} from '@components/popups/paymentCard';\nimport PopupPaymentCardConfirmation from '@components/popups/paymentCardConfirmation';\nimport PopupPaymentMethods from '@components/popups/paymentMethods';\nimport PopupPaymentShipping, {PaymentShippingAddress} from '@components/popups/paymentShipping';\nimport PopupPaymentShippingMethods from '@components/popups/paymentShippingMethods';\nimport PopupPaymentVerification from '@components/popups/paymentVerification';\nimport type PopupStars from '@components/popups/stars';\nimport PopupStarsPay from '@components/popups/starsPay';\nimport {renderComponent} from '@helpers/solid/renderComponent';\n\nconst USE_NATIVE_SYMBOL = true;\nconst iconPath = 'assets/img/';\nconst icons = [\n  'amex',\n  'card',\n  'diners',\n  'discover',\n  'jcb',\n  'mastercard',\n  'visa',\n  'unionpay',\n  'mir',\n  'logo'\n];\n\nexport function getPaymentBrandIconPath(brand: string) {\n  if(!icons.includes(brand)) {\n    return;\n  }\n\n  return `${iconPath}${brand}.svg`;\n}\n\nexport function PaymentButton(options: {\n  onClick: () => Promise<any> | void,\n  key?: LangPackKey,\n  textEl?: I18n.IntlElement\n}) {\n  const textEl = options.textEl ?? new I18n.IntlElement({key: options.key ?? 'PaymentInfo.Done'});\n  const key = textEl.key;\n  const payButton = Button('btn-primary btn-color-primary payment-item-pay');\n  payButton.append(textEl.element);\n  attachClickEvent(payButton, async() => {\n    const result = options.onClick();\n    if(!(result instanceof Promise)) {\n      return;\n    }\n\n    const d = putPreloader(payButton);\n    const toggle = toggleDisability([payButton], true);\n    textEl.compareAndUpdate({key: 'PleaseWait'});\n    try {\n      await result;\n    } catch(err) {\n      if(!(err as ApiError).handled) {\n        console.error('payment button error', err);\n      }\n\n      toggle();\n      textEl.compareAndUpdate({key});\n      d.remove();\n    }\n  });\n  return payButton;\n}\n\nexport type PaymentsCredentialsToken = {type: 'card', token?: string, id?: string};\n\nexport type PopupPaymentResult = 'paid' | 'cancelled' | 'pending' | 'failed';\n\nexport class InputRightNumber {\n  public input: HTMLInputElement;\n\n  constructor(public options: {\n    fontWeight?: number\n  } = {}) {\n    const input = this.input = document.createElement('input');\n    input.type = 'tel';\n    // const input: HTMLElement = document.createElement('div');\n    // input.contentEditable = 'true';\n    input.classList.add('input-clear');\n\n    const haveToIgnoreEvents = input instanceof HTMLInputElement ? 1 : 2;\n    const onSelectionChange = () => {\n      if(ignoreNextSelectionChange) {\n        --ignoreNextSelectionChange;\n        return;\n      }\n\n      // setTimeout(() => {\n      ignoreNextSelectionChange = haveToIgnoreEvents;\n      placeCaretAtEnd(input);\n      // }, 0);\n    };\n\n    const onFocus = () => {\n      // cancelEvent(e);\n      setTimeout(() => {\n        ignoreNextSelectionChange = haveToIgnoreEvents;\n        placeCaretAtEnd(input);\n        getAppWindow().document.addEventListener('selectionchange', onSelectionChange);\n      }, 0);\n    };\n\n    const onFocusOut = () => {\n      input.addEventListener('focus', onFocus, {once: true});\n      getAppWindow().document.removeEventListener('selectionchange', onSelectionChange);\n    };\n\n    let ignoreNextSelectionChange: number;\n    input.addEventListener('focusout', onFocusOut);\n    onFocusOut();\n  }\n\n  public get value() {\n    // return input.textContent;\n    return this.input.value;\n  }\n\n  public set value(value: string) {\n    this.input.value = value;\n    // input.textContent = wrapped;\n    this.onValue();\n  }\n\n  public onValue() {\n    if(this.input.ownerDocument.activeElement === this.input) {\n      placeCaretAtEnd(this.input);\n    }\n\n    this.setWidth();\n  }\n\n  public setWidth() {\n    const width = getTextWidth(this.value, this.options?.fontWeight ? `${this.options.fontWeight} ${FontSize} ${FontFamily}` : FontFull);\n    this.input.style.width = width + 'px';\n  }\n}\n\nconst className = 'payment-item';\n\ntype PaymentRowState = {\n  title: Signal<JSX.Element>,\n  subtitleVisible: Signal<boolean>,\n  media: Signal<HTMLElement>,\n  hidden: Signal<boolean>\n};\n\nconst createPaymentRowState = (options: {\n  title?: JSX.Element,\n  subtitleVisible?: boolean,\n  hidden?: boolean\n} = {}): PaymentRowState => ({\n  title: createSignal<JSX.Element>(options.title || ''),\n  subtitleVisible: createSignal(options.subtitleVisible ?? !!options.title),\n  media: createSignal<HTMLElement>(),\n  hidden: createSignal(!!options.hidden)\n});\n\nconst PaymentRow = (props: {\n  state: PaymentRowState,\n  label: LangPackKey,\n  labelArgs?: any[],\n  icon?: Icon,\n  clickable?: (event: MouseEvent) => void,\n  class?: string,\n  mediaClass?: string\n}) => (\n  <Row\n    class={`${className}-row${props.class ? ' ' + props.class : ''}`}\n    classList={{hide: props.state.hidden[0]()}}\n    clickable={props.clickable}\n    noWrap\n  >\n    <Show when={props.state.media[0]()} fallback={props.icon && <Row.Icon icon={props.icon} />}>\n      {(media) => <Row.Media element={media()} size=\"small\" class={props.mediaClass} />}\n    </Show>\n    <Row.Title>{props.state.title[0]() || i18n(props.label, props.labelArgs)}</Row.Title>\n    <Row.Subtitle class={props.state.subtitleVisible[0]() ? undefined : 'hide'}>\n      {i18n(props.label, props.labelArgs)}\n    </Row.Subtitle>\n  </Row>\n);\n\nexport default class PopupPayment extends PopupElement<{\n  finish: (result: PopupPaymentResult) => void\n}> {\n  private tipButtonsMap: Map<number, HTMLElement>;\n  private result: PopupPaymentResult;\n  private message: Message.message;\n  private inputInvoice: InputInvoice;\n  private paymentForm?: PaymentsPaymentForm | PaymentsPaymentReceipt;\n  private isReceipt: boolean;\n\n  constructor(options: {\n    message?: Message.message,\n    inputInvoice?: InputInvoice,\n    paymentForm?: PaymentsPaymentForm | PaymentsPaymentReceipt,\n    isReceipt?: boolean,\n\n    // * stars only\n    isTopUp?: boolean,\n    transaction?: StarsTransaction,\n    paidMedia?: MessageMedia.messageMediaPaidMedia,\n    chatInvite?: ChatInvite.chatInvite,\n    noPaymentForm?: boolean,\n    subscription?: StarsSubscription,\n    giftAction?: MessageAction.messageActionGiftStars,\n    boost?: Boost,\n    giftPeerId?: PeerId,\n    noShowIfStars?: boolean,\n    purpose?: ConstructorParameters<typeof PopupStars>[0]['purpose']\n  }) {\n    super('popup-payment', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      title: true\n    });\n\n    safeAssign(this, options);\n\n    this.result = 'cancelled';\n\n    this.tipButtonsMap = new Map();\n  }\n\n  public hide() {\n    this.dispatchEvent('finish', this.result);\n    return super.hide();\n  }\n\n  public setPaymentForm(paymentForm: PaymentsPaymentForm | PaymentsPaymentReceipt) {\n    this.paymentForm = paymentForm;\n    this.d().catch((err) => {\n      console.error('payment popup error', err);\n      this.hide();\n    });\n  }\n\n  private async d() {\n    this.element.classList.add('is-loading');\n    this.show();\n\n    let confirmed = false;\n    const onConfirmed = () => {\n      if(confirmed) {\n        return;\n      }\n\n      this.result = 'paid';\n      confirmed = true;\n      if(popupPaymentVerification) {\n        popupPaymentVerification.hide();\n      }\n\n      this.hide();\n    };\n\n    const {paymentForm, message} = this;\n    if(paymentForm._ === 'payments.paymentFormStarGift') {\n      throw new Error('not implemented');\n    }\n\n    if(message) {\n      this.listenerSetter.add(rootScope)('payment_sent', ({peerId, mid}) => {\n        if(message.peerId === peerId && message.mid === mid) {\n          onConfirmed();\n        }\n      });\n    }\n\n    const mediaInvoice = message?.media as MessageMedia.messageMediaInvoice;\n    const isReceipt = this.isReceipt ??\n      (\n        mediaInvoice ?\n          !!mediaInvoice.receipt_msg_id || mediaInvoice.extended_media?._ === 'messageExtendedMedia' :\n          paymentForm._ === 'payments.paymentReceipt'\n      );\n    const isTest = mediaInvoice ? mediaInvoice.pFlags.test : paymentForm.invoice.pFlags.test;\n    const isStars = paymentForm._ === 'payments.paymentFormStars';\n\n    const photo = mediaInvoice ? mediaInvoice.photo : (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).photo;\n    const title = mediaInvoice ? mediaInvoice.title : paymentForm.title;\n    const description = mediaInvoice ? mediaInvoice.description : paymentForm.description;\n\n    _i18n(this.title, isReceipt ? 'PaymentReceipt' : 'PaymentCheckout');\n    if(isTest) {\n      this.title.append(' (Test)');\n    }\n\n    const itemEl = document.createElement('div');\n    itemEl.classList.add(className);\n\n    const detailsClassName = className + '-details';\n    const details = document.createElement('div');\n    details.classList.add(detailsClassName);\n\n    let photoEl: HTMLElement;\n    if(photo) {\n      photoEl = document.createElement('div');\n      photoEl.classList.add(detailsClassName + '-photo', 'media-container-contain');\n      const sizeAttribute = photo.attributes.find((attribute) => attribute._ === 'documentAttributeImageSize') as DocumentAttribute.documentAttributeImageSize;\n      const boxSize = makeMediaSize(100, 100);\n      if(sizeAttribute) {\n        const photoSize = makeMediaSize(sizeAttribute.w, sizeAttribute.h);\n        const fittedSize = photoSize.aspectFitted(boxSize);\n        photoEl.style.width = fittedSize.width + 'px';\n        photoEl.style.height = fittedSize.height + 'px';\n      }\n\n      wrapPhoto({\n        photo: photo,\n        container: photoEl,\n        boxWidth: boxSize.width,\n        boxHeight: boxSize.height,\n        size: {_: 'photoSizeEmpty', type: ''}\n      });\n      details.append(photoEl);\n    }\n\n    const linesClassName = detailsClassName + '-lines';\n    const linesEl = document.createElement('div');\n    linesEl.classList.add(linesClassName);\n\n    const titleEl = document.createElement('div');\n    titleEl.classList.add(linesClassName + '-title');\n\n    const descriptionEl = document.createElement('div');\n    descriptionEl.classList.add(linesClassName + '-description');\n\n    const botName = document.createElement('div');\n    botName.classList.add(linesClassName + '-bot-name');\n\n    linesEl.append(titleEl, descriptionEl, botName);\n\n    setInnerHTML(titleEl, wrapEmojiText(title));\n    setInnerHTML(descriptionEl, wrapEmojiText(description));\n\n    const peerTitle = new PeerTitle();\n    botName.append(peerTitle.element);\n\n    details.append(linesEl);\n    itemEl.append(details);\n    this.scrollable.append(itemEl);\n\n    const preloaderContainer = document.createElement('div');\n    preloaderContainer.classList.add(className + '-preloader-container');\n    const preloader = putPreloader(preloaderContainer, true);\n    this.scrollable.append(preloaderContainer);\n\n    const inputInvoice = this.inputInvoice;\n\n    let savedInfo = (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).saved_info || (paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).info;\n    const savedCredentials = (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).saved_credentials?.[0];\n    let [\n      lastRequestedInfo,\n      passwordState,\n      providerPeerTitle\n    ] = await Promise.all([\n      !isReceipt && savedInfo && this.managers.appPaymentsManager.validateRequestedInfo(inputInvoice, savedInfo).catch((err: ApiError) => {\n        console.error('validateRequestedInfo', err, savedInfo);\n        // savedInfo = undefined;\n        return undefined as PaymentsValidatedRequestedInfo;\n      }),\n      savedCredentials && this.managers.passwordManager.getState(),\n      wrapPeerTitle({peerId: isStars ? NULL_PEER_ID : (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).provider_id.toPeerId()})\n    ]);\n\n    // console.log(paymentForm, lastRequestedInfo);\n\n    await peerTitle.update({peerId: paymentForm.bot_id.toPeerId()});\n    preloaderContainer.remove();\n    this.element.classList.remove('is-loading');\n\n    const wrapAmount = (amount: string | number, skipSymbol?: boolean) => {\n      return paymentsWrapCurrencyAmount(amount, currency, skipSymbol, USE_NATIVE_SYMBOL, true);\n    };\n\n    const {invoice} = paymentForm;\n    const currency = invoice.currency;\n\n    const isRecurring = invoice.pFlags.recurring && !isReceipt;\n    const hasTerms = !!invoice.terms_url;\n\n    await peerTitle.update({peerId: paymentForm.bot_id.toPeerId()});\n    const peerTitle2 = isRecurring || hasTerms ? await wrapPeerTitle({peerId: paymentForm.bot_id.toPeerId()}) : undefined;\n    preloaderContainer.remove();\n    this.element.classList.remove('is-loading');\n\n    const makeLabel = () => {\n      const labelEl = document.createElement('div');\n      labelEl.classList.add(pricesClassName + '-price');\n\n      const left = document.createElement('span');\n      const right = document.createElement('span');\n      labelEl.append(left, right);\n      return {label: labelEl, left, right};\n    };\n\n    const pricesClassName = className + '-prices';\n    const prices = document.createElement('div');\n    prices.classList.add(pricesClassName);\n    const makePricesElements = (prices: LabeledPrice[]) => {\n      return prices.map((price) => {\n        const {amount, label} = price;\n\n        const _label = makeLabel();\n        _label.left.append(wrapEmojiText(label));\n\n        const wrappedAmount = wrapAmount(amount);\n        _label.right.textContent = wrappedAmount;\n\n        return _label.label;\n      });\n    };\n\n    const pricesElements = makePricesElements(invoice.prices);\n\n    let getTipsAmount = (): number => 0;\n    let shippingAmount = 0;\n\n    const getTotalTotal = () => totalAmount + getTipsAmount() + shippingAmount;\n    const setTotal = () => {\n      const wrapped = wrapAmount(getTotalTotal());\n      totalLabel.right.textContent = wrapped;\n      payI18n.compareAndUpdate({\n        key: 'PaymentCheckoutPay',\n        args: [wrapped]\n      });\n    };\n\n    const payI18n = new I18n.IntlElement();\n\n    const totalLabel = makeLabel();\n    totalLabel.label.classList.add('is-total');\n    _i18n(totalLabel.left, 'PaymentTransactionTotal');\n    const totalAmount = accumulate(invoice.prices.map(({amount}) => +amount), 0);\n\n    const canTip = (invoice.max_tip_amount !== undefined && !isReceipt) || !!(paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).tip_amount;\n    if(canTip) {\n      const tipsClassName = className + '-tips';\n\n      const currencyData = Currencies[currency];\n\n      getTipsAmount = () => +inputRightNumber.value.replace(/\\D/g, '');\n\n      const setInputValue = (amount: string | number) => {\n        amount = Math.min(+amount, +invoice.max_tip_amount);\n        const wrapped = wrapAmount(amount, true);\n\n        inputRightNumber.value = wrapped;\n\n        unsetActiveTip?.();\n        const tipEl = this.tipButtonsMap.get(amount);\n        if(tipEl) {\n          tipEl.classList.add('active');\n        }\n\n        setTotal();\n      };\n\n      const tipsLabel = makeLabel();\n      _i18n(tipsLabel.left, isReceipt ? 'PaymentTip' : 'PaymentTipOptional');\n      const inputRightNumber = new InputRightNumber({fontWeight: 500});\n      const {input} = inputRightNumber;\n      input.classList.add('input-clear', tipsClassName + '-input');\n      tipsLabel.right.append(input);\n\n      if(!isReceipt) {\n        tipsLabel.label.style.cursor = 'text';\n      } else {\n        tipsLabel.label.classList.add('disable-hover');\n      }\n\n      tipsLabel.label.addEventListener('mousedown', (e) => {\n        if(!findUpAsChild(e.target as HTMLElement, input)) {\n          placeCaretAtEnd(input);\n        }\n      });\n\n      input.addEventListener('input', () => {\n        setInputValue(getTipsAmount());\n      });\n\n      const s = [\n        USE_NATIVE_SYMBOL ? currencyData.native || currencyData.symbol : currencyData.symbol,\n        currencyData.space_between ? ' ' : ''\n      ];\n      if(!currencyData.symbol_left) s.reverse();\n      tipsLabel.right[currencyData.symbol_left ? 'prepend' : 'append'](s.join(''));\n\n      pricesElements.push(tipsLabel.label);\n\n      //\n      let unsetActiveTip: () => void;\n      if(!isReceipt) {\n        const tipsEl = document.createElement('div');\n        tipsEl.classList.add(tipsClassName);\n\n        const tipClassName = tipsClassName + '-tip';\n        const tipButtons = invoice.suggested_tip_amounts.map((tipAmount) => {\n          const button = Button(tipClassName, {noRipple: true});\n          button.textContent = wrapAmount(tipAmount);\n\n          this.tipButtonsMap.set(+tipAmount, button);\n          return button;\n        });\n\n        unsetActiveTip = () => {\n          const prevTipEl = tipsEl.querySelector('.active');\n          if(prevTipEl) {\n            prevTipEl.classList.remove('active');\n          }\n        };\n\n        attachClickEvent(tipsEl, (e) => {\n          const tipEl = findUpClassName(e.target, tipClassName);\n          if(!tipEl) {\n            return;\n          }\n\n          let tipAmount = 0;\n          if(tipEl.classList.contains('active')) {\n            tipEl.classList.remove('active');\n          } else {\n            unsetActiveTip();\n            tipEl.classList.add('active');\n\n            for(const [amount, el] of this.tipButtonsMap) {\n              if(el === tipEl) {\n                tipAmount = amount;\n                break;\n              }\n            }\n          }\n\n          setInputValue(tipAmount);\n        });\n\n        setInputValue(0);\n\n        tipsEl.append(...tipButtons);\n        pricesElements.push(tipsEl);\n      } else {\n        setInputValue((paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).tip_amount);\n      }\n    } else {\n      setTotal();\n    }\n\n    pricesElements.push(totalLabel.label);\n\n    prices.append(...pricesElements);\n    itemEl.append(prices);\n\n    // /\n\n    const setRowIcon = async(row: PaymentRowState, icon?: string) => {\n      const img = document.createElement('img');\n      img.classList.add('media-photo');\n      await renderImageFromUrlPromise(img, getPaymentBrandIconPath(icon));\n      let container = row.media[0]();\n      if(!container) {\n        container = document.createElement('div');\n        container.append(img);\n        row.media[1](container);\n      } else {\n        container.replaceChildren(img);\n      }\n    };\n\n    const setRowTitle = (row: PaymentRowState, title: JSX.Element) => {\n      row.title[1](title || '');\n      row.subtitleVisible[1](!!title);\n    };\n\n    const setCardSubtitle = (card: PaymentCardDetailsResult) => {\n      const {brand, str, icon} = PopupPayment.getCardDetailsInfo(card);\n\n      setRowIcon(methodRow, icon || brand.toLowerCase());\n      setRowTitle(methodRow, str);\n    };\n\n    const onMethodClick = async() => {\n      const user = useUser(rootScope.myId) as User.user;\n      assumeType<PaymentsPaymentForm.paymentsPaymentForm>(paymentForm);\n\n      let popup: PopupPaymentMethods | PopupPaymentCard;\n      if(paymentForm.additional_methods) {\n        popup = PopupElement.createPopup(\n          PopupPaymentMethods,\n          paymentForm,\n          user,\n          previousCardDetails as PaymentCardDetails\n        );\n        popup = await popup.waitForMethodPopup();\n\n        // * reusing same card\n        if(!popup) {\n          return;\n        }\n      } else {\n        popup = PopupElement.createPopup(\n          PopupPaymentCard,\n          paymentForm,\n          user,\n          previousCardDetails as PaymentCardDetails\n        );\n      }\n\n      popup.addEventListener('finish', ({token, card}) => {\n        previousToken = token, previousCardDetails = card;\n\n        setCardSubtitle(card);\n      });\n    };\n\n    let previousCardDetails: PaymentCardDetailsResult, previousToken: PaymentsCredentialsToken;\n    const methodRow = createPaymentRowState();\n\n    if(savedCredentials) {\n      setCardSubtitle(savedCredentials);\n    } else if((paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).credentials_title) {\n      setCardSubtitle({title: (paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).credentials_title});\n    }\n\n    const providerRow = createPaymentRowState({title: providerPeerTitle});\n\n    const providerAvatar = avatarNew({\n      middleware: this.middlewareHelper.get(),\n      size: 32,\n      peerId: isStars ? NULL_PEER_ID : (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).provider_id.toPeerId()\n    });\n    const providerMedia = document.createElement('div');\n    providerMedia.append(providerAvatar.node);\n    providerRow.media[1](providerMedia);\n\n    let shippingAddressRow: PaymentRowState, shippingNameRow: PaymentRowState, shippingEmailRow: PaymentRowState, shippingPhoneRow: PaymentRowState, shippingMethodRow: PaymentRowState;\n    let lastShippingOption: ShippingOption, onShippingAddressClick: (focus?: ConstructorParameters<typeof PopupPaymentShipping>[2]) => void, onShippingMethodClick: () => void;\n    const setShippingTitle = invoice.pFlags.shipping_address_requested ? (shippingAddress?: PaymentShippingAddress) => {\n      if(!shippingAddress) {\n        shippingMethodRow.title[1](i18n('PaymentShippingAddress'));\n        shippingMethodRow.subtitleVisible[1](false);\n        return;\n      }\n\n      const postAddress = shippingAddress.shipping_address;\n      setRowTitle(shippingAddressRow, [\n        postAddress.city,\n        postAddress.street_line1,\n        postAddress.street_line2\n      ].filter(Boolean).join(', '));\n\n      shippingMethodRow.hidden[1](!lastRequestedInfo?.shipping_options && !isReceipt);\n    } : undefined;\n\n    const setShippingInfo = (info: PaymentRequestedInfo) => {\n      setShippingTitle && setShippingTitle?.(info);\n      shippingNameRow && setRowTitle(shippingNameRow, info.name);\n      shippingEmailRow && setRowTitle(shippingEmailRow, info.email);\n      shippingPhoneRow && setRowTitle(shippingPhoneRow, info.phone && ('+' + formatPhoneNumber(info.phone).formatted));\n    };\n\n    if(!isReceipt) {\n      onShippingAddressClick = (focus) => {\n        PopupElement.createPopup(\n          PopupPaymentShipping,\n          paymentForm as PaymentsPaymentForm.paymentsPaymentForm,\n          inputInvoice,\n          focus\n        ).addEventListener('finish', ({shippingAddress, requestedInfo}) => {\n          lastRequestedInfo = requestedInfo;\n          savedInfo = (paymentForm as PaymentsPaymentForm.paymentsPaymentForm).saved_info = shippingAddress;\n          setShippingInfo(shippingAddress);\n        });\n      };\n    }\n\n    if(invoice.pFlags.shipping_address_requested) {\n      const setShippingOption = (shippingOption?: ShippingOption) => {\n        const scrollSaver = new ScrollSaver(this.scrollable, undefined, true);\n        scrollSaver.save();\n        if(lastShippingPricesElements) {\n          lastShippingPricesElements.forEach((node) => node.remove());\n        }\n\n        if(!shippingOption) {\n          shippingAmount = 0;\n\n          setTotal();\n          scrollSaver.restore();\n          this.onContentUpdate();\n          return;\n        }\n\n        lastShippingOption = shippingOption;\n        setRowTitle(shippingMethodRow, shippingOption.title);\n\n        shippingAmount = accumulate(shippingOption.prices.map(({amount}) => +amount), 0);\n        lastShippingPricesElements = makePricesElements(shippingOption.prices);\n        let l = totalLabel.label;\n        if(canTip) {\n          l = l.previousElementSibling as any;\n          if(!isReceipt) {\n            l = l.previousElementSibling as any;\n          }\n        }\n\n        lastShippingPricesElements.forEach((element) => l.parentElement.insertBefore(element, l));\n\n        setTotal();\n        scrollSaver.restore();\n        this.onContentUpdate();\n      };\n\n      shippingAddressRow = createPaymentRowState();\n\n      let lastShippingPricesElements: HTMLElement[];\n      shippingMethodRow = createPaymentRowState({hidden: true});\n      onShippingMethodClick = () => {\n        PopupElement.createPopup(\n          PopupPaymentShippingMethods,\n          paymentForm as PaymentsPaymentForm,\n          lastRequestedInfo,\n          lastShippingOption\n        ).addEventListener('finish', (shippingOption) => {\n          setShippingOption(shippingOption);\n        });\n      };\n\n      const shippingOption = (paymentForm as PaymentsPaymentReceipt.paymentsPaymentReceipt).shipping;\n      if(shippingOption) {\n        setShippingOption(shippingOption);\n      }\n    }\n\n    if(invoice.pFlags.name_requested) {\n      shippingNameRow = createPaymentRowState();\n    }\n\n    if(invoice.pFlags.email_requested) {\n      shippingEmailRow = createPaymentRowState();\n    }\n\n    if(invoice.pFlags.phone_requested) {\n      shippingPhoneRow = createPaymentRowState();\n    }\n\n    if(savedInfo) {\n      setShippingInfo(savedInfo);\n    }\n\n    const acceptTermsSignal = createSignal(!(!isReceipt && (isRecurring || hasTerms)));\n\n    const rowsContainer = document.createElement('div');\n    this.scrollable.append(document.createElement('hr'), rowsContainer);\n    renderComponent({\n      element: rowsContainer,\n      Component: () => (\n        <>\n          <PaymentRow\n            state={methodRow}\n            label=\"PaymentCheckoutMethod\"\n            icon=\"card\"\n            class={`${className}-method-row`}\n            mediaClass=\"media-container-cover\"\n            clickable={isReceipt ? undefined : onMethodClick}\n          />\n          <PaymentRow state={providerRow} label=\"PaymentCheckoutProvider\" />\n          <Show when={shippingAddressRow}>\n            <PaymentRow\n              state={shippingAddressRow}\n              label=\"PaymentShippingAddress\"\n              icon=\"location\"\n              clickable={isReceipt ? undefined : onShippingAddressClick.bind(null, undefined)}\n            />\n          </Show>\n          <Show when={shippingMethodRow}>\n            <PaymentRow\n              state={shippingMethodRow}\n              label=\"PaymentCheckoutShippingMethod\"\n              icon=\"shipping\"\n              clickable={isReceipt ? undefined : onShippingMethodClick}\n            />\n          </Show>\n          <Show when={shippingNameRow}>\n            <PaymentRow\n              state={shippingNameRow}\n              label=\"PaymentCheckoutName\"\n              icon=\"newprivate_filled\"\n              clickable={isReceipt ? undefined : onShippingAddressClick.bind(null, 'name')}\n            />\n          </Show>\n          <Show when={shippingEmailRow}>\n            <PaymentRow\n              state={shippingEmailRow}\n              label=\"PaymentShippingEmailPlaceholder\"\n              icon=\"mention_filled\"\n              clickable={isReceipt ? undefined : onShippingAddressClick.bind(null, 'email')}\n            />\n          </Show>\n          <Show when={shippingPhoneRow}>\n            <PaymentRow\n              state={shippingPhoneRow}\n              label=\"PaymentCheckoutPhoneNumber\"\n              icon=\"phone_filled\"\n              clickable={isReceipt ? undefined : onShippingAddressClick.bind(null, 'phone')}\n            />\n          </Show>\n          <Show when={!isReceipt && (isRecurring || hasTerms)}>\n            <hr />\n            <Row class={`${className}-row`} noWrap>\n              <Row.CheckboxField>\n                <CheckboxFieldTsx signal={acceptTermsSignal} />\n              </Row.CheckboxField>\n              <Row.Title>{i18n(\n                isRecurring ? 'Payments.Recurrent.Accept' : 'Payments.Terms.Accept',\n                [wrapRichText(invoice.terms_url), peerTitle2]\n              )}</Row.Title>\n            </Row>\n          </Show>\n        </>\n      ),\n      middleware: this.middlewareHelper.get()\n    });\n\n    // /\n    let popupPaymentVerification: PopupPaymentVerification, lastTmpPasword: AccountTmpPassword;\n    const onClick = () => {\n      const missingInfo = invoice.pFlags.name_requested && !savedInfo?.name ? 'name' : (invoice.pFlags.email_requested && !savedInfo?.email ? 'email' : (invoice.pFlags.phone_requested && !savedInfo?.phone ? 'phone' : undefined));\n      if(invoice.pFlags.shipping_address_requested) {\n        if(!lastRequestedInfo) {\n          onShippingAddressClick();\n          return;\n        } else if(!lastShippingOption && lastRequestedInfo.shipping_options) {\n          onShippingMethodClick();\n          return;\n        }\n      } else if(missingInfo) {\n        onShippingAddressClick(missingInfo);\n        return;\n      }\n\n      if(!previousCardDetails && !lastTmpPasword) {\n        if(!savedCredentials) {\n          onMethodClick();\n          return;\n        }\n\n        Promise.resolve(passwordState ?? this.managers.passwordManager.getState()).then((_passwordState) => {\n          PopupElement.createPopup(\n            PopupPaymentCardConfirmation,\n            savedCredentials.title,\n            _passwordState\n          ).addEventListener('finish', (tmpPassword) => {\n            passwordState = undefined;\n            lastTmpPasword = tmpPassword;\n            simulateClickEvent(payButton);\n\n            // * reserve 5 seconds\n            const diff = tmpPassword.valid_until - tsNow(true) - 5;\n            setTimeout(() => {\n              if(lastTmpPasword === tmpPassword) {\n                lastTmpPasword = undefined;\n              }\n            }, diff * 1000);\n          });\n        });\n\n        return;\n      }\n\n      return Promise.resolve().then(async() => {\n        const credentials: InputPaymentCredentials = lastTmpPasword ? {\n          _: 'inputPaymentCredentialsSaved',\n          id: savedCredentials.id,\n          tmp_password: lastTmpPasword.tmp_password\n        } : {\n          _: 'inputPaymentCredentials',\n          data: {\n            _: 'dataJSON',\n            data: JSON.stringify(previousToken.token ? previousToken : {type: previousToken.type, id: previousToken.id})\n          },\n          pFlags: {\n            save: previousCardDetails.save || undefined\n          }\n        };\n\n        try {\n          this.result = 'pending';\n          const paymentResult = await this.managers.appPaymentsManager.sendPaymentForm(\n            inputInvoice,\n            (paymentForm as PaymentsPaymentForm).form_id,\n            lastRequestedInfo?.id,\n            lastShippingOption?.id,\n            credentials,\n            getTipsAmount()\n          );\n\n          if(paymentResult._ === 'payments.paymentResult') {\n            onConfirmed();\n          } else {\n            popupPaymentVerification = PopupElement.createPopup(\n              PopupPaymentVerification,\n              paymentResult.url,\n              !mediaInvoice?.extended_media\n            );\n            popupPaymentVerification.addEventListener('finish', () => {\n              popupPaymentVerification = undefined;\n\n              onConfirmed();\n            });\n            await new Promise<void>((resolve, reject) => {\n              popupPaymentVerification.addEventListener('close', () => {\n                popupPaymentVerification = undefined;\n                if(confirmed) {\n                  resolve();\n                } else {\n                  const err = makeError(undefined, 'payment not finished');\n                  (err as ApiError).handled = true;\n                  reject(err);\n                  this.result = 'failed';\n                }\n              });\n            });\n          }\n        } catch(err) {\n          if((err as ApiError).type === 'BOT_PRECHECKOUT_TIMEOUT') {\n            toastNew({langPackKey: 'Error.AnError'});\n            (err as ApiError).handled = true;\n          } else if((err as ApiError).type === 'TMP_PASSWORD_INVALID') {\n            passwordState = lastTmpPasword = undefined;\n            simulateClickEvent(payButton);\n            (err as ApiError).handled = true;\n          } else {\n            this.result = 'failed';\n          }\n\n          throw err;\n        }\n      });\n    };\n\n    const onChange = () => {\n      payButton.disabled = !acceptTermsSignal[0]();\n    };\n\n    let payButton: HTMLButtonElement;\n    if(isReceipt) {\n      payButton = PaymentButton({\n        onClick: () => this.hide(),\n        key: 'Done'\n      });\n    } else {\n      payButton = PaymentButton({\n        onClick: onClick,\n        textEl: payI18n\n      });\n    }\n\n    onChange();\n    if(!isReceipt && (isRecurring || hasTerms)) {\n      createRoot((dispose) => {\n        this.middlewareHelper.onDestroy(dispose);\n        createEffect(onChange);\n      });\n    }\n\n    this.body.append(this.btnConfirmOnEnter = payButton);\n\n    this.onContentUpdate();\n  }\n\n  public static async create(options: ConstructorParameters<typeof PopupPayment>[0]) {\n    let promise: Promise<PaymentsPaymentForm | PaymentsPaymentReceipt>;\n    if(!options.paymentForm && !options.transaction && !options.noPaymentForm) {\n      if(options.isReceipt) promise = rootScope.managers.appPaymentsManager.getPaymentReceipt(options.message.peerId, (options.message.media as MessageMedia.messageMediaInvoice).receipt_msg_id || (options.inputInvoice as InputInvoice.inputInvoiceMessage).msg_id);\n      else promise = rootScope.managers.appPaymentsManager.getPaymentForm(options.inputInvoice);\n    } else {\n      promise = Promise.resolve(options.paymentForm);\n    }\n\n    const paymentForm = await promise;\n    const constructor = options.noPaymentForm ||\n      options.transaction ||\n      options.giftAction ||\n      paymentForm._ === 'payments.paymentFormStars' ||\n      paymentForm._ === 'payments.paymentReceiptStars' ||\n      paymentForm._ === 'payments.paymentFormStarGift' ? PopupStarsPay : PopupPayment;\n\n    const popup = PopupElement.createPopup(constructor as any, options) as PopupStarsPay | PopupPayment;\n    popup.setPaymentForm(paymentForm as any);\n\n    return popup;\n  }\n\n  public static getCardDetailsInfo(card: PaymentCardDetailsResult) {\n    let brand: string;\n    let str: string;\n    let icon: string;\n    if('title' in card) {\n      brand = card.title.split(' ').shift();\n      str = card.title;\n      icon = card.icon;\n    } else {\n      brand = detectUnifiedCardBrand(card.cardNumber);\n      str = brand + ' *' + card.cardNumber.split(' ').pop();\n    }\n\n    return {brand, str, icon};\n  }\n}\n","import {Accessor, batch, createMemo, createReaction, createRoot, createSignal, onCleanup} from 'solid-js';\nimport {Middleware} from '@helpers/middleware';\nimport useDynamicCachedValue from '@helpers/solid/useDynamicCachedValue';\nimport rootScope, {BroadcastEventsListeners} from '@lib/rootScope';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport bigInt from 'big-integer';\n\nconst [stars, setStars] = createSignal<Long>();\nconst [reservedStars, setReservedStars] = createSignal<number>(0);\n\nconst [tonBalance, setTonBalance] = createSignal<Long>();\nconst [reservedTonBalance, setReservedTonBalance] = createSignal<number>(0);\nconst [hasTonTransactions, setHasTonTransactions] = createSignal(false);\n\nconst fetchStars = () => rootScope.managers.appPaymentsManager.getStarsStatus(true).then((starsStatus) => setStars(formatStarsAmount(starsStatus.balance)));\nconst fetchTonBalance = () => rootScope.managers.appPaymentsManager.getStarsStatusTon(true).then((starsStatus) => {\n  batch(() => {\n    setTonBalance(starsStatus.balance.amount);\n    setHasTonTransactions((hasTransactions) => hasTransactions || !!starsStatus.history?.length);\n  });\n});\n\nexport function prefetchStars(middleware: Middleware) {\n  return createRoot((dispose) => {\n    middleware.onClean(dispose);\n    const stars = useStars();\n    if(stars() !== undefined) {\n      return stars();\n    }\n\n    return new Promise<Long>((resolve) => {\n      createReaction(() => resolve(stars()))(stars);\n    });\n  });\n}\n\nexport {hasTonTransactions, setReservedStars};\n\nlet cached: Accessor<Long>;\nlet cachedTon: Accessor<Long>;\nfunction _useStars(ton: boolean) {\n  if(ton && cachedTon) {\n    return cachedTon;\n  } else if(!ton && cached) {\n    return cached;\n  }\n\n  return useDynamicCachedValue(() => _useStars.name + (ton ? 'ton' : ''), () => {\n    (ton ? fetchTonBalance : fetchStars)();\n    const handler: BroadcastEventsListeners['stars_balance'] = ({balance, fulfilledReservedStars, ton}) => {\n      batch(() => {\n        (ton ? setTonBalance : setStars)(balance);\n        if(ton) setHasTonTransactions(true);\n        if(fulfilledReservedStars) (ton ? setReservedTonBalance : setReservedStars)(prev => Math.max(0, prev - fulfilledReservedStars));\n      });\n    }\n    rootScope.addEventListener('stars_balance', handler);\n\n    // const interval = setInterval(() => {\n    //   fetchStars();\n    // }, 60e3);\n\n    onCleanup(() => {\n      // clearInterval(interval);\n      rootScope.removeEventListener('stars_balance', handler);\n    });\n\n    // return stars;\n    return createMemo(() => {\n      if(ton) {\n        return bigInt(tonBalance() as string).minus(reservedTonBalance()).toString();\n      }\n      return +stars() - +reservedStars();\n    });\n  })();\n}\n\n// * cache once and for all\nexport default function useStars(ton = false) {\n  if(ton) {\n    return cachedTon ??= createRoot(() => _useStars(ton));\n  }\n\n  return cached ??= createRoot(() => _useStars(ton));\n}\n","import {setDirection} from '@helpers/dom/setInnerHTML';\n\nexport default class DivAndCaption<T> {\n  public container: HTMLElement;\n  public border: HTMLElement;\n  public content: HTMLElement;\n  public title: HTMLElement;\n  public subtitle: HTMLElement;\n\n  constructor(protected className: string, public fill?: T) {\n    this.container = document.createElement('div');\n    this.container.className = className;\n\n    this.border = document.createElement('div');\n    this.border.classList.add(className + '-border');\n\n    this.content = document.createElement('div');\n    this.content.classList.add(className + '-content');\n\n    this.title = document.createElement('div');\n    this.title.classList.add(className + '-title');\n    setDirection(this.title);\n\n    this.subtitle = document.createElement('div');\n    this.subtitle.classList.add(className + '-subtitle');\n    setDirection(this.subtitle);\n\n    this.content.append(this.title, this.subtitle);\n    this.container.append(this.border, this.content);\n  }\n}\n","import {FontFamily, FontSize, FontWeight} from '@config/font';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport mediaSizes from '@helpers/mediaSizes';\nimport clamp from '@helpers/number/clamp';\nimport {fastRaf} from '@helpers/schedulers';\n\n// Thanks to https://stackoverflow.com/a/49349813\n\n/**\n * Attibute modifier to create middle ellipsis\n * When the attribute value is left blank the ellipsis will be in the middle\n * When positive the attribute value will be used as a percentage\n * When negative the attribute value will be used as character index counted from the end\n * @example\n *   <div data-middle-ellipsis>A Javascript solution to middle ellipsis</div>\n *   <div data-middle-ellipsis=\"20\">A Javascript solution to middle ellipsis</div>\n *   <div data-middle-ellipsis=\"-3\">A Javascript solution to middle ellipsis</div>\n */\nconst ellipsis = '…';\nconst map: Map<HTMLElement, {\n  text: string,\n  textLength: number,\n  from: number,\n  multiplier: number,\n  font: string,\n  textWidth: number,\n  elementWidth: number\n}> = new Map();\n\nconst testQueue: Set<HTMLElement> = new Set();\nconst fontSize = '16px';\nlet pendingTest = false;\n\nfunction setTestQueue() {\n  if(pendingTest) {\n    return;\n  }\n\n  pendingTest = true;\n  fastRaf(() => {\n    pendingTest = false;\n    testQueueElements();\n  });\n}\n\nfunction testQueueElements() {\n  testQueue.forEach(testElement);\n  testQueue.clear();\n}\n\nwindow.addEventListener('resize', () => {\n  for(const [key] of map) {\n    testQueue.add(key);\n  }\n\n  setTestQueue();\n}, {capture: true, passive: true});\n\nfunction getElementWidth(element: HTMLElement) {\n  const getSize = (element as any).getSize;\n  if(getSize) {\n    return getSize();\n  }\n\n  const type = element.dataset.sizeType;\n  if(type) {\n    const mediaSize = mediaSizes.active;\n    // @ts-ignore\n    const size: MediaSize = mediaSize[type];\n    return size.width;\n  }\n\n  return element.getBoundingClientRect().width;\n}\n\nfunction testElement(element: HTMLElement) {\n  // const perf = performance.now();\n  // do not recalculate variables a second time\n  let mapped = map.get(element);\n  const firstTime = !mapped;\n\n  let {text, textLength, from, multiplier, font, textWidth, elementWidth} = mapped || {};\n  // console.log('[MEE] testElement got mapped', mapped);\n\n  if(firstTime) {\n    text = element.textContent;\n    textLength = text.length;\n    from = /* parseFloat(element.getAttribute(attributeName)) ||  */50;\n    multiplier = from > 0 && from / 100;\n\n    let fontSize = element.dataset.fontSize;\n    if(fontSize && +fontSize) fontSize += 'px';\n    // const perf = performance.now();\n    font = `${element.dataset.fontWeight || FontWeight} ${fontSize || FontSize} ${FontFamily}`;\n    /* const computedStyle = window.getComputedStyle(elm, null);\n    font = `${computedStyle.getPropertyValue('font-weight')} ${computedStyle.getPropertyValue('font-size')} ${computedStyle.getPropertyValue('font-family')}`; */\n    // console.log('testMiddleEllipsis get computed style:', performance.now() - perf, font);\n\n    textWidth = getTextWidth(text, font);\n    // const perf = performance.now();\n    elementWidth = getElementWidth(element);\n    // console.log('testMiddleEllipsis get offsetWidth:', performance.now() - perf, font);\n    mapped = {text, textLength, from, multiplier, font, textWidth, elementWidth};\n    map.set(element, mapped);\n\n    // console.log('[MEE] testElement map set', element);\n  }\n\n  const newElementWidth = getElementWidth(element);\n  const widthChanged = firstTime || elementWidth !== newElementWidth;\n  !firstTime && widthChanged && (mapped.elementWidth = elementWidth = newElementWidth);\n\n  if(widthChanged) {\n    if(textWidth > elementWidth) {\n      element.setAttribute('title', text);\n      let smallerText = text;\n      let smallerWidth = elementWidth;\n      while(smallerText.length > 3) {\n        const smallerTextLength = smallerText.length;\n        const half = multiplier &&\n          clamp(multiplier * smallerTextLength << 0, 1, smallerTextLength - 2) ||\n          Math.max(smallerTextLength + from - 1, 1);\n        const half1 = smallerText.substr(0, half).replace(/\\s*$/, '');\n        const half2 = smallerText.substr(half + 1).replace(/^\\s*/, '');\n        smallerText = half1 + half2;\n        smallerWidth = getTextWidth(smallerText + ellipsis, font);\n        if(smallerWidth < elementWidth) {\n          element.textContent = half1 + ellipsis + half2;\n          break;\n        }\n      }\n\n      // * set new width after cutting text\n      mapped.elementWidth = getElementWidth(element);\n      // mapped.textWidth = smallerWidth;\n    } else {\n      element.removeAttribute('title');\n    }\n  }\n\n  // console.log('testMiddleEllipsis for element:', elm, performance.now() - perf);\n}\n\nexport class MiddleEllipsisElement extends HTMLElement {\n  connectedCallback() {\n    // console.log('[MEE]: connectedCallback before', map.has(this), testQueue.has(this), map.size, this.textContent, map);\n\n    map.set(this, null);\n    if(this.dataset.sizeType || (this as any).getSize) {\n      testElement(this);\n    } else {\n      testQueue.add(this);\n      setTestQueue();\n    }\n    // testElement(this);\n\n    // console.log('[MEE]: connectedCallback after', map.has(this), map.size, testQueue.has(this), testQueue.size);\n  }\n\n  disconnectedCallback() {\n    const deleted = map.delete(this);\n    testQueue.delete(this);\n    // console.log('[MEE]: disconnectedCallback', deleted, map.has(this), map.size, this.textContent, map);\n  }\n}\n\ncustomElements.define('middle-ellipsis-element', MiddleEllipsisElement);\n","import {Message} from '@layer';\nimport type {MyMessage} from '@appManagers/appMessagesManager';\nimport getFwdFromName from '@appManagers/utils/messages/getFwdFromName';\n\nexport default function getMessageSenderPeerIdOrName(message: MyMessage) {\n  if(message.fromId) {\n    return {\n      peerId: message.fromId\n    };\n  } else {\n    return {\n      fromName: getFwdFromName((message as Message.message).fwd_from)\n    };\n  }\n}\n","import {MyMessage} from '@appManagers/appMessagesManager';\nimport getMessageSenderPeerIdOrName from '@appManagers/utils/messages/getMessageSenderPeerIdOrName';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\nexport default async function wrapSenderToPeer(message: MyMessage) {\n  const senderTitle: HTMLElement = document.createElement('span');\n  senderTitle.classList.add('sender-title');\n\n  const fromMe = message.fromId === rootScope.myId && message.peerId !== rootScope.myId;\n  senderTitle.append(\n    fromMe ?\n      i18n('FromYou') :\n      await wrapPeerTitle({\n        ...getMessageSenderPeerIdOrName(message),\n        dialog: message.peerId === rootScope.myId\n      })\n  );\n\n  if(await rootScope.managers.appPeersManager.isAnyGroup(message.peerId) || fromMe) {\n    const peerTitle = await wrapPeerTitle({peerId: message.peerId});\n    senderTitle.append(' ➝ ', peerTitle);\n  }\n\n  return senderTitle;\n}\n","import {formatDateAccordingToTodayNew} from '@helpers/date';\nimport {MyMessage} from '@appManagers/appMessagesManager';\n\nexport default function wrapSentTime(message: MyMessage) {\n  const el: HTMLElement = document.createElement('span');\n  el.classList.add('sent-time');\n  el.append(formatDateAccordingToTodayNew(new Date(message.date * 1000)));\n\n  return el;\n}\n","import {children, createEffect, createMemo, JSX, onCleanup, Show} from 'solid-js';\nimport {createStore} from 'solid-js/store';\nimport {Message} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport noop from '@helpers/noop';\nimport {IconTsx} from '@components/iconTsx';\nimport {hideToast, toastNew} from '@components/toast';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupPremium from '@components/popups/premium';\n\n\n/**\n * Where a voice row stands in the transcription flow. It starts `idle`; asking for a transcription\n * moves it to `loading`, and the first answer from the server — partial or final — moves it to\n * `transcribed` for good.\n */\nexport type TranscriptionStatus = 'idle' | 'loading' | 'transcribed';\n\nexport type TranscriptionState = {\n  status: TranscriptionStatus,\n  text: string,\n  /** The server is still working on it: keep the dots and the button's outline running. */\n  pending: boolean,\n  /** The server gave up — the error message stands in for the text. */\n  error: boolean,\n  /** Only meaningful once `transcribed`: whether the text is showing. */\n  expanded: boolean\n};\n\n/** All the transcription needs of the row it belongs to: a DOM anchor carrying a live message. */\ntype TranscribableRow = HTMLElement & {message: Message.message};\n\n/**\n * Folds a `message_transcribed` update into the row's state. A transcription can arrive in pieces,\n * so this runs once per update rather than once per request.\n */\nexport function reduceTranscribed(\n  prev: TranscriptionState,\n  update: {text: string, pending?: boolean}\n): Partial<TranscriptionState> {\n  return {\n    status: 'transcribed',\n    text: update.text,\n    pending: !!update.pending,\n    // no text and nothing more coming is how a failure reads on the wire\n    error: !update.text && !update.pending,\n    // the first answer opens the transcription; after that the reader's own choice stands\n    expanded: prev.status === 'transcribed' ? prev.expanded : true\n  };\n}\n\nfunction TranscribedText(props: {state: TranscriptionState}) {\n  return (\n    <div\n      class=\"audio-transcribed-text\"\n      classList={{\n        'is-error': props.state.error,\n        'hide': !props.state.expanded\n      }}\n    >\n      <Show when={props.state.error} fallback={props.state.text}>\n        {i18n('Chat.Voice.Transribe.Error')}\n      </Show>\n      <Show when={props.state.pending}>\n        {/* three real dots rather than an animated `content`, which only pseudo-elements can do —\n          each fades in on its own beat, and they hold the width even while hidden */}\n        <span class=\"audio-transcribing-dots\">\n          {[1, 2, 3].map((i) => (\n            <span class={`audio-transcribing-dots-dot audio-transcribing-dots-dot-${i}`}>.</span>\n          ))}\n        </span>\n      </Show>\n    </div>\n  );\n}\n\nfunction TranscribeLoader(props: {active: boolean}) {\n  return (\n    <div class=\"loader\" classList={{active: props.active}}>\n      <svg class=\"audio-transcribe-outline\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 24\">\n        <rect\n          class=\"audio-transcribe-outline-rect\"\n          fill=\"transparent\"\n          stroke-width=\"3\"\n          stroke-linejoin=\"round\"\n          rx=\"6\"\n          ry=\"6\"\n          stroke=\"var(--message-primary-color)\"\n          stroke-dashoffset=\"1\"\n          stroke-dasharray=\"32,68\"\n          width=\"32\"\n          height=\"24\"\n        />\n      </svg>\n    </div>\n  );\n}\n\nfunction TranscribeButton(props: {\n  state: TranscriptionState,\n  row: () => TranscribableRow,\n  onClick: () => void\n}) {\n  // The transcribed text cannot live inside the row — that box is a single fixed-height flex line —\n  // so it is built under this owner (which keeps it reactive and disposes it with the row) and\n  // mounted beside the row the first time there is anything to show. `children` is what turns the\n  // component into a node to mount: a component on its own hands back a lazily-evaluated value.\n  const hasText = createMemo(() => props.state.status === 'transcribed');\n  const text = children(() => hasText() ? <TranscribedText state={props.state} /> : undefined);\n\n  let mounted: HTMLElement;\n  createEffect(() => {\n    const element = text() as HTMLElement;\n    if(!element || element === mounted) {\n      return;\n    }\n\n    mounted = element;\n    const row = props.row();\n    // a bubble hangs the row off a `.document-wrapper`; a reply quote nests it inside `.quote-text`\n    if(findUpClassName(row, 'document-wrapper')) row.after(element);\n    else findUpClassName(row, 'quote-text')?.append(element);\n  });\n\n  onCleanup(() => mounted?.remove());\n\n  return (\n    <div class=\"audio-to-text-button\" onClick={props.onClick}>\n      <IconTsx icon={hasText() && props.state.expanded ? 'up' : 'transcribe'} />\n      <TranscribeLoader active={props.state.status === 'loading' || props.state.pending} />\n    </div>\n  );\n}\n\n/**\n * Wires a voice row's transcribe button to `messages.transcribeAudio`. The row owns the state and\n * listens for its own `message_transcribed` updates, so a transcription started anywhere — this\n * button, another client, a cached result — lands on every rendering of that message.\n */\nexport default function createAudioTranscription(options: {\n  listenerSetter: ListenerSetter,\n  getRow: () => TranscribableRow\n}) {\n  const [state, setState] = createStore<TranscriptionState>({\n    status: 'idle',\n    text: '',\n    pending: false,\n    error: false,\n    expanded: false\n  });\n\n  options.listenerSetter.add(rootScope)('message_transcribed', ({peerId, mid, text, pending}) => {\n    const {message} = options.getRow();\n    if(peerId !== message.peerId || mid !== message.mid) {\n      return;\n    }\n\n    setState((prev) => reduceTranscribed(prev, {text, pending}));\n  });\n\n  const onClick = () => {\n    if(state.status === 'transcribed') {\n      setState('expanded', (expanded) => !expanded);\n      return;\n    }\n\n    if(state.status === 'loading') { // already asked — the answer is on its way\n      return;\n    }\n\n    const {message} = options.getRow();\n    if(message.pFlags.is_outgoing) {\n      return;\n    }\n\n    if(!rootScope.getPremium()) {\n      toastNew({\n        langPackKey: 'AudioAndVideoTranscription.PremiumAlert',\n        langPackArguments: [anchorCallback(() => {\n          hideToast();\n          PopupPremium.show({feature: 'voice_to_text'});\n        })]\n      });\n      return;\n    }\n\n    setState('status', 'loading');\n    rootScope.managers.appMessagesManager.transcribeAudio(message).catch(noop);\n  };\n\n  return {\n    state,\n    /** Evaluated inside the row's `Row`, and owns the transcribed text mounted next to it. */\n    button: (): JSX.Element => (\n      <TranscribeButton state={state} row={options.getRow} onClick={onClick} />\n    )\n  };\n}\n","import createElementFromMarkup from '@helpers/createElementFromMarkup';\nimport forwardMarkup from '@/assets/audioIcons/forward.svg?raw';\nimport pauseplayMarkup from '@/assets/audioIcons/pauseplay.svg?raw';\nimport playpauseMarkup from '@/assets/audioIcons/playpause.svg?raw';\nimport rewindMarkup from '@/assets/audioIcons/rewind.svg?raw';\n\n\n/**\n * The four animated audio glyphs. `playpause` / `pauseplay` are transitions — each one starts on the\n * glyph it is named after and freezes on the other. `forward` / `rewind` rest on their finished\n * frame and simply replay, so they read as a pulse rather than a change of state.\n */\nexport type AudioAnimatedIconName = 'playpause' | 'pauseplay' | 'forward' | 'rewind';\n\nconst MARKUP: Record<AudioAnimatedIconName, string> = {\n  playpause: playpauseMarkup,\n  pauseplay: pauseplayMarkup,\n  forward: forwardMarkup,\n  rewind: rewindMarkup\n};\n\n/**\n * Chrome no longer renders SMIL (since 150): the timeline advances and `beginEvent` fires, but the\n * animated value never reaches the element, so a glyph only ever snaps between its first and last\n * frame — which is what \"the animation sometimes doesn't play\" turned out to be. So the glyph's own\n * keyframes are replayed through the Web Animations API instead, which every engine has.\n *\n * Only the path morph needs more than that: `d` is animatable as a CSS property in Chrome and\n * Firefox but not yet in Safari, and that is the one case left on SMIL — which Safari does still\n * render. The choice is made per glyph rather than per browser, so the seek pulses, which only move\n * their shapes about, take the Web Animations path everywhere.\n */\nconst CAN_ANIMATE = typeof Element !== 'undefined' && typeof Element.prototype.animate === 'function';\nconst CAN_ANIMATE_PATH = CAN_ANIMATE && typeof CSS !== 'undefined' && !!CSS.supports?.('d', 'path(\"M 0 0\")');\n\n/** One SMIL animation is one CSS value, so animations sharing a target become one set of keyframes. */\ntype GlyphAnimation = {target: SVGElement, keyframes: Keyframe[], duration: number};\n\nconst parseDuration = (value: string) => parseFloat(value) * (value.endsWith('ms') ? 1 : 1000);\n\n/** The SMIL transform types the glyphs use, written as the CSS functions that mean the same. */\nfunction transformFunction(type: string, value: string) {\n  const [first, second, third] = value.trim().split(/[\\s,]+/);\n  switch(type) {\n    case 'translate':\n      return `translate(${first}px, ${second || 0}px)`;\n    case 'scale':\n      return `scale(${first}, ${second || first})`;\n    case 'rotate':\n      // SMIL takes the centre inline; CSS has to walk to it and back, since transform-origin is\n      // pinned to the user-space origin below\n      return third === undefined ?\n        `rotate(${first}deg)` :\n        `translate(${second}px, ${third}px) rotate(${first}deg) translate(${-parseFloat(second)}px, ${-parseFloat(third)}px)`;\n    default:\n      return '';\n  }\n}\n\n/**\n * Reads a glyph's SMIL declarations as Web Animations keyframes. Exported for the tests — the\n * conversion is the part that has to keep matching the assets.\n */\nexport function readGlyphAnimations(svg: SVGSVGElement): GlyphAnimation[] {\n  const byTarget = new Map<SVGElement, SVGAnimationElement[]>();\n  (Array.from(svg.querySelectorAll('animate, animateTransform')) as SVGAnimationElement[]).forEach((animation) => {\n    const target = animation.parentElement as any as SVGElement;\n    const list = byTarget.get(target);\n    if(list) list.push(animation);\n    else byTarget.set(target, [animation]);\n  });\n\n  const result: GlyphAnimation[] = [];\n  byTarget.forEach((animations, target) => {\n    // the whole glyph is authored on one clock, so the first declaration's timing describes the rest\n    const first = animations[0];\n    const duration = parseDuration(first.getAttribute('dur'));\n    const offsets = first.getAttribute('keyTimes').split(';').map(Number);\n    const splines = (first.getAttribute('keySplines') || '').split(';').filter(Boolean);\n\n    const keyframes = offsets.map((offset, index): Keyframe => {\n      const keyframe: Keyframe = {offset};\n      let transform = '';\n\n      animations.forEach((animation) => {\n        const value = animation.getAttribute('values').split(';')[index].trim();\n        if(animation.getAttribute('attributeName') === 'd') {\n          keyframe.d = `path(\"${value}\")`;\n          return;\n        }\n\n        // SMIL composition: an additive declaration stacks onto the ones before it, a plain one\n        // replaces the base transform outright\n        const piece = transformFunction(animation.getAttribute('type'), value);\n        transform = animation.getAttribute('additive') === 'sum' && transform ? `${transform} ${piece}` : piece;\n      });\n\n      if(transform) {\n        keyframe.transform = transform;\n      }\n\n      // a spline describes the segment that STARTS at its keyframe, which is what `easing` means here\n      const spline = splines[index];\n      if(spline) {\n        keyframe.easing = `cubic-bezier(${spline.trim().split(/[\\s,]+/).join(', ')})`;\n      }\n\n      return keyframe;\n    });\n\n    result.push({target, keyframes, duration});\n  });\n\n  return result;\n}\n\nexport type AudioAnimatedIcon = {\n  element: SVGSVGElement,\n  duration: number,\n  /** Replays a glyph that is already on screen — one being mounted starts from its markup. */\n  play: () => void,\n  /** How far the glyph has moved, in ms. */\n  elapsed: () => number,\n  /** Starts the glyph part-way, so a morph that interrupts another can pick it up where it stands. */\n  seek: (ms: number) => void\n};\n\n/**\n * Builds one of the glyphs. It holds its first frame until `play()` runs — nothing moves just\n * because the icon was mounted.\n */\nexport default function createAudioAnimatedIcon(name: AudioAnimatedIconName, autoplay?: boolean): AudioAnimatedIcon {\n  const element = createElementFromMarkup(MARKUP[name]) as any as SVGSVGElement;\n  element.classList.add('audio-animated-icon');\n\n  const parsed = readGlyphAnimations(element);\n  const morphsPath = parsed.some(({keyframes}) => keyframes.some((keyframe) => keyframe.d));\n\n  if(!CAN_ANIMATE || (morphsPath && !CAN_ANIMATE_PATH)) {\n    const animations = Array.from(element.querySelectorAll('animate, animateTransform')) as SVGAnimationElement[];\n    // The start is declared on the element rather than triggered afterwards: `beginElement()` on a\n    // node inserted in this same task can be dropped, because its timeline has not started yet.\n    if(autoplay) {\n      animations.forEach((animation) => animation.setAttribute('begin', '0s'));\n    }\n\n    return {\n      element,\n      duration: parsed[0]?.duration || 0,\n      play: () => animations.forEach((animation) => animation.beginElement()),\n      // Both deliberately inert: seeking SMIL into the middle of a morph is what froze the glyph the\n      // last time it was tried, so a morph on this path always runs from its own first frame.\n      elapsed: () => 0,\n      seek: () => {}\n    };\n  }\n\n  // the declarations would only fight the Web Animations ones in a browser that runs both\n  element.querySelectorAll('animate, animateTransform').forEach((animation) => animation.remove());\n  // SMIL turns about the user-space origin; CSS would turn about the middle of the view box\n  parsed.forEach(({target, keyframes}) => {\n    if(keyframes.some((keyframe) => keyframe.transform)) {\n      target.style.transformOrigin = '0px 0px';\n    }\n  });\n\n  let animations: Animation[];\n  const start = (offset?: number) => {\n    animations = parsed.map(({target, keyframes, duration}) => {\n      const animation = target.animate(keyframes, {duration, fill: 'forwards'});\n      if(offset) animation.currentTime = offset;\n      return animation;\n    });\n  };\n\n  if(autoplay) {\n    start();\n  }\n\n  return {\n    element,\n    duration: parsed[0]?.duration || 0,\n    play: () => {\n      animations?.forEach((animation) => animation.cancel());\n      start();\n    },\n    elapsed: () => (animations?.[0]?.currentTime as number) || 0,\n    seek: (ms) => {\n      if(animations) animations.forEach((animation) => animation.currentTime = ms);\n      else start(ms);\n    }\n  };\n}\n\n/**\n * The play button's glyph. Animating means starting on the glyph already on screen and moving to the\n * new one; the very first call is silent, so a row that mounts mid-playback simply shows the pause\n * glyph rather than performing for nobody.\n */\nexport function createPlayPauseIcon(getContainer: () => HTMLElement) {\n  let playing: boolean;\n  let current: AudioAnimatedIcon;\n\n  return (next: boolean, animate = true) => {\n    if(playing === next) {\n      return;\n    }\n\n    const isFirst = playing === undefined;\n    playing = next;\n\n    const shouldAnimate = animate && !isFirst;\n    const name: AudioAnimatedIconName = shouldAnimate ?\n      (next ? 'playpause' : 'pauseplay') :\n      (next ? 'pauseplay' : 'playpause');\n\n    const icon = createAudioAnimatedIcon(name, shouldAnimate);\n\n    // The two files are the same move in opposite directions, so a morph that interrupts another\n    // starts as far from its own beginning as the one it cut short had left to run: the glyph turns\n    // around where it stands, instead of jumping back to a whole play or pause first. Pressing the\n    // button repeatedly is exactly where that jump was visible.\n    if(shouldAnimate && current) {\n      const elapsed = Math.min(current.elapsed(), icon.duration);\n      if(elapsed) {\n        icon.seek(icon.duration - elapsed);\n      }\n    }\n\n    current = icon;\n    getContainer().replaceChildren(icon.element);\n  };\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport ProgressivePreloader from '@components/preloader';\nimport appMediaPlaybackController, {MediaItem, MediaListLoaderFactory, MediaSearchContext} from '@components/appMediaPlaybackController';\nimport {DocumentAttribute, Message} from '@layer';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport rootScope from '@lib/rootScope';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport ListenerSetter, {Listener} from '@helpers/listenerSetter';\nimport noop from '@helpers/noop';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {joinElementsWith} from '@lib/langPack';\nimport {MiddleEllipsisElement} from '@components/middleEllipsis';\nimport {formatFullSentTime} from '@helpers/date';\nimport throttleWithRaf from '@helpers/schedulers/throttleWithRaf';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport formatBytes from '@helpers/formatBytes';\nimport {animateSingle} from '@helpers/animation';\nimport clamp from '@helpers/number/clamp';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport MediaProgressLine from '@components/mediaProgressLine';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapSenderToPeer from '@components/wrappers/senderToPeer';\nimport wrapSentTime from '@components/wrappers/sentTime';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport wrapPhoto from '@components/wrappers/photo';\nimport safePlay from '@helpers/dom/safePlay';\nimport Row from '@components/rowTsx';\nimport createAudioTranscription from '@components/audioTranscription';\nimport {createPlayPauseIcon} from '@components/audioAnimatedIcon';\nimport {children, createRoot, JSX, Show} from 'solid-js';\nimport {createStore, SetStoreFunction} from 'solid-js/store';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport makeError from '@helpers/makeError';\nimport {Middleware} from '@helpers/middleware';\n\n\nconst UNMOUNT_PRELOADER = true;\nconst SUBTITLE_SEPARATOR = ' • ';\n\nrootScope.addEventListener('messages_media_read', ({mids, peerId}) => {\n  mids.forEach((mid) => {\n    const attr = `[data-mid=\"${mid}\"][data-peer-id=\"${peerId}\"]`;\n    (Array.from(document.querySelectorAll(`.audio.is-unread${attr}, .media-round.is-unread${attr}`)) as HTMLElement[]).forEach((elem) => {\n      // an audio row keeps `is-unread` in its store — stripping the class here would only last until\n      // the next reactive update put it back.\n      if(isAudioElement(elem)) elem.setUnread(false);\n      else elem.classList.remove('is-unread');\n    });\n  });\n});\n\n// https://github.com/LonamiWebs/Telethon/blob/4393ec0b83d511b6a20d8a20334138730f084375/telethon/utils.py#L1285\nexport function decodeWaveform(waveform: Uint8Array | number[]) {\n  if(!(waveform instanceof Uint8Array)) {\n    waveform = new Uint8Array(waveform);\n  }\n\n  const bitCount = waveform.length * 8;\n  const valueCount = bitCount / 5 | 0;\n  if(!valueCount) {\n    return new Uint8Array([]);\n  }\n\n  const result = new Uint8Array(valueCount);\n  for(let i = 0; i < valueCount; i++) {\n    const byteIndex = i * 5 / 8 | 0;\n    const bitShift = i * 5 % 8;\n    // read two bytes manually instead of DataView.getUint16, which over-reads by\n    // a byte and throws when the last 5-bit value lands in the final byte (e.g.\n    // 62-byte / 99-sample waveforms) — that threw away the whole waveform\n    const low = waveform[byteIndex];\n    const high = byteIndex + 1 < waveform.length ? waveform[byteIndex + 1] : 0;\n    result[i] = ((low | (high << 8)) >> bitShift) & 0b00011111;\n  }\n\n  return result;\n}\n\nfunction createWaveformBars(waveform: Uint8Array, duration: number) {\n  const barWidth = 2;\n  const barMargin = 2;\n  const barHeightMin = 4;\n  const barHeightMax = mediaSizes.isMobile && false ? 16 : 23;\n\n  const minW = mediaSizes.isMobile ? 152 : 190;\n  const maxW = mediaSizes.isMobile ? 190 : 256;\n  const availW = clamp(duration / 60 * maxW, minW, maxW);\n\n  const normValue = Math.max(...waveform);\n  const wfSize = waveform.length;\n  const barCount = Math.min((availW / (barWidth + barMargin)) | 0, wfSize);\n\n  let maxValue = 0;\n  const maxDelta = barHeightMax - barHeightMin;\n\n  let html = '';\n  for(let i = 0, barX = 0, sumI = 0; i < wfSize; ++i) {\n    const value = waveform[i] || 0;\n    if((sumI + barCount) >= wfSize) { // draw bar\n      sumI = sumI + barCount - wfSize;\n      if(sumI < (barCount + 1) / 2) {\n        if(maxValue < value) maxValue = value;\n      }\n\n      const bar_value = Math.max(((maxValue * maxDelta) + ((normValue + 1) / 2)) / (normValue + 1), barHeightMin);\n\n      const h = `<rect class=\"audio-waveform-bar\" x=\"${barX}\" y=\"${barHeightMax - bar_value}\" width=\"${barWidth}\" height=\"${bar_value}\" rx=\"1\" ry=\"1\"></rect>`;\n      html += h;\n\n      barX += barWidth + barMargin;\n\n      if(sumI < (barCount + 1) / 2) {\n        maxValue = 0;\n      } else {\n        maxValue = value;\n      }\n    } else {\n      if(maxValue < value) maxValue = value;\n\n      sumI += barCount;\n    }\n  }\n\n  let container: HTMLElement, svg: SVGSVGElement;\n\n  if(!html) {\n\n  } else {\n    container = document.createElement('div');\n    container.classList.add('audio-waveform');\n\n    svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n    svg.classList.add('audio-waveform-bars');\n    svg.setAttributeNS(null, 'width', '' + availW);\n    svg.setAttributeNS(null, 'height', '' + barHeightMax);\n    svg.setAttributeNS(null, 'viewBox', `0 0 ${availW} ${barHeightMax}`);\n    svg.insertAdjacentHTML('beforeend', html);\n\n    container.append(svg);\n  }\n\n  return {svg, container, availW};\n}\n\n/**\n * Every class the row puts on itself. Solid owns `class` on the root once the row is rendered, so a\n * `classList.add` there would be undone by the next reactive update — these flags are the way in.\n */\ntype AudioRowState = {\n  isVoice: boolean,\n  isOut: boolean,\n  canTranscribe: boolean,\n  isUnread: boolean,\n  isOutgoing: boolean,\n  withThumb: boolean,\n  cornerDownload: boolean,\n  downloading: boolean,\n  /** Music only: the row swaps its description for the progress line while it plays. */\n  showProgress: boolean,\n  progressLine: HTMLElement\n};\n\n/**\n * What the two type-specific wrappers get to work with. `element` is filled in the moment the row is\n * rendered — the wrappers only ever reach for it from callbacks, which all run later.\n */\ntype AudioRowContext = {\n  options: AudioElementOptions,\n  doc: MyDocument,\n  timeEl: HTMLElement,\n  state: AudioRowState,\n  setState: SetStoreFunction<AudioRowState>,\n  element: AudioElement,\n  listenerSetter: ListenerSetter,\n  readyPromise: CancellablePromise<void>,\n  addAudioListener: HTMLMediaElement['addEventListener'],\n  togglePlay: (e?: Event, paused?: boolean) => void\n};\n\n/** What a wrapper hands back: markup Row evaluates itself, plus the playback wiring. */\ntype WrappedAudio = {\n  content: () => JSX.Element,\n  onLoad: () => () => void\n};\n\nfunction AudioRow(props: {\n  state: AudioRowState,\n  content: () => JSX.Element,\n  clickable: boolean,\n  ref: (toggle: HTMLElement) => void,\n  playIconRef: (container: HTMLElement) => void\n}) {\n  return (\n    <Row\n      noRipple\n      clickable={props.clickable}\n      classList={{\n        'audio': true,\n        'audio-details': true,\n        'is-voice': props.state.isVoice,\n        'is-out': props.state.isOut,\n        'can-transcribe': props.state.canTranscribe,\n        'is-unread': props.state.isUnread,\n        'is-outgoing': props.state.isOutgoing,\n        'audio-with-thumb': props.state.withThumb,\n        'corner-download': props.state.cornerDownload,\n        'downloading': props.state.downloading,\n        'audio-show-progress': props.state.showProgress\n      }}\n    >\n      {/* The play button IS the row's media: same 48x48 slot every other Row puts an avatar in. */}\n      <Row.Media size=\"big\" class=\"audio-toggle\" ref={props.ref}>\n        <div class=\"audio-play-icon\" ref={props.playIconRef} />\n      </Row.Media>\n      {/* Row.Title / Row.Subtitle read RowContext, so their JSX has to be evaluated inside Row —\n        hence a factory rather than ready-made nodes. */}\n      {props.content()}\n    </Row>\n  );\n}\n\nasync function wrapVoiceMessage(ctx: AudioRowContext): Promise<WrappedAudio> {\n  const {options, doc, setState} = ctx;\n  const message = options.message;\n\n  setState('isVoice', true);\n  if(message.pFlags.out) {\n    setState('isOut', true);\n  }\n\n  let waveform = (doc.attributes.find((attribute) => attribute._ === 'documentAttributeAudio') as DocumentAttribute.documentAttributeAudio)?.waveform || new Uint8Array([]);\n  waveform = decodeWaveform(waveform.slice(0, 63));\n\n  const {svg, container: svgContainer, availW} = createWaveformBars(waveform, doc.duration);\n\n  let fakeSvgContainer: HTMLElement;\n  if(svgContainer) {\n    fakeSvgContainer = svgContainer.cloneNode(true) as HTMLElement;\n    fakeSvgContainer.classList.add('audio-waveform-fake');\n    svgContainer.classList.add('audio-waveform-background');\n  }\n\n  const waveformContainer = (\n    <div class=\"audio-waveform-container\">\n      {svgContainer && [svgContainer, fakeSvgContainer]}\n    </div>\n  ) as HTMLElement;\n\n  let transcribeButton: () => JSX.Element;\n  if(options.customAudioToTextButton) {\n    // a round video expanded into voice form brings its own button — it transcribes itself\n    setState('canTranscribe', true);\n    const customButton = options.customAudioToTextButton;\n    transcribeButton = () => customButton;\n  } else if(options.canTranscribe) {\n    setState('canTranscribe', true);\n    transcribeButton = createAudioTranscription({\n      listenerSetter: ctx.listenerSetter,\n      getRow: () => ctx.element\n    }).button;\n  }\n\n  // Same two lines as the music variant: the waveform reads as the row's title and the clock as its\n  // subtitle. The transcribe button hangs off the row itself — it sits outside both.\n  const content = () => (\n    <>\n      <Row.Title class=\"audio-title\">{waveformContainer}</Row.Title>\n      <Row.Subtitle class=\"audio-subtitle\">{ctx.timeEl}</Row.Subtitle>\n      {transcribeButton?.()}\n    </>\n  );\n\n  let progress = svg as any as HTMLElement, progressLine: MediaProgressLine;\n  if(!progress) {\n    progressLine = new MediaProgressLine();\n\n    waveformContainer.append(progressLine.container);\n  }\n\n  const onLoad = () => {\n    let audio = ctx.element.audio;\n\n    const setAnimation = () => {\n      animateSingle(() => {\n        if(!audio) return false;\n        onTimeUpdate();\n        return !audio.paused;\n      }, ctx.element);\n    };\n\n    const onTimeUpdate = () => {\n      if(fakeSvgContainer) {\n        fakeSvgContainer.style.width = (audio.currentTime / audio.duration * 100) + '%';\n      }\n    };\n\n    if(!audio.paused || (audio.currentTime > 0 && audio.currentTime !== audio.duration)) {\n      onTimeUpdate();\n    }\n\n    const throttledTimeUpdate = throttleWithRaf(onTimeUpdate);\n    ctx.addAudioListener('timeupdate', throttledTimeUpdate);\n    ctx.addAudioListener('ended', throttledTimeUpdate);\n    ctx.addAudioListener('play', setAnimation);\n\n    progress && ctx.readyPromise.then(() => {\n      let mousedown = false, mousemove = false;\n      progress.addEventListener('mouseleave', (e) => {\n        if(mousedown) {\n          ctx.togglePlay(undefined, true);\n          mousedown = false;\n        }\n        mousemove = false;\n      });\n      progress.addEventListener('mousemove', (e) => {\n        mousemove = true;\n        if(mousedown) scrub(e);\n      });\n      progress.addEventListener('mousedown', (e) => {\n        e.preventDefault();\n        if(e.button !== 0) return;\n        if(!audio.paused) {\n          ctx.togglePlay(undefined, false);\n        }\n\n        scrub(e);\n        mousedown = true;\n      });\n      progress.addEventListener('mouseup', (e) => {\n        if(mousemove && mousedown) {\n          ctx.togglePlay(undefined, true);\n          mousedown = false;\n        }\n      });\n      attachClickEvent(progress, (e) => {\n        cancelEvent(e);\n        if(!audio.paused) scrub(e);\n      });\n\n      function scrub(e: MouseEvent | TouchEvent) {\n        let offsetX: number;\n        if(!('touches' in e)) { // cross-realm-safe mouse check (works in the Document PiP window)\n          offsetX = e.offsetX;\n        } else { // touch\n          const rect = (e.target as HTMLElement).getBoundingClientRect();\n          offsetX = e.targetTouches[0].pageX - rect.left;\n        }\n\n        let scrubTime = offsetX / availW /* width */ * audio.duration;\n        if(audio.duration && scrubTime >= audio.duration) {\n          scrubTime = audio.duration - 0.01;\n        }\n        setCurrentTime(audio, scrubTime);\n      }\n    }, noop);\n\n    !progress && progressLine.setMedia({\n      media: audio,\n      streamable: doc.supportsStreaming,\n      duration: doc.duration\n    });\n\n    return () => {\n      progress?.remove();\n      progress = null;\n      audio = null;\n    };\n  };\n\n  return {content, onLoad};\n}\n\nasync function wrapAudio(ctx: AudioRowContext): Promise<WrappedAudio> {\n  const {options, doc, setState} = ctx;\n  const message = options.message;\n\n  const isVoice = doc.type === 'voice' || doc.type === 'round';\n  const descriptionEl = document.createElement('div');\n  descriptionEl.classList.add('audio-description');\n\n  const audioAttribute = doc.attributes?.find((attr) => attr._ === 'documentAttributeAudio') as DocumentAttribute.documentAttributeAudio;\n\n  // the performer rides in the title next to the track name, so the description is what is left\n  const performer = !isVoice && audioAttribute?.performer;\n\n  // the duration sits in front of the description, so the description opens with a separator\n  if(!isVoice) {\n    const parts: (Node | string)[] = [\n      options.withTime ? formatFullSentTime(message.date) : formatBytes(doc.size)\n    ];\n\n    if(options.showSender) {\n      parts.push(await wrapSenderToPeer(message));\n    }\n\n    descriptionEl.append(SUBTITLE_SEPARATOR, ...joinElementsWith(parts, SUBTITLE_SEPARATOR));\n  }\n\n  const middleEllipsisEl = new MiddleEllipsisElement();\n  middleEllipsisEl.dataset.fontWeight = '' + options.fontWeight;\n  middleEllipsisEl.dataset.fontSize = '' + options.fontSize;\n  middleEllipsisEl.dataset.sizeType = options.sizeType;\n  (middleEllipsisEl as any).getSize = options.getSize;\n  if(isVoice) {\n    middleEllipsisEl.append(await wrapSenderToPeer(message));\n  } else {\n    setInnerHTML(middleEllipsisEl, wrapEmojiText(audioAttribute?.title ?? doc.file_name));\n  }\n\n  const sentTime = options.showSender && wrapSentTime(message);\n\n  const content = () => (\n    <>\n      <Row.Title class=\"audio-title\" titleRight={sentTime} titleRightSecondary>\n        {/* one box for the name and the performer, so the title ellipsises as a whole */}\n        <span class=\"audio-title-text\">\n          {performer && [<span class=\"audio-performer text-bold\">{wrapEmojiText(performer)}</span>, ' — ']}\n          {middleEllipsisEl}\n        </span>\n      </Row.Title>\n      <Row.Subtitle class=\"audio-subtitle\">\n        {ctx.timeEl}\n        {ctx.state.showProgress ? ctx.state.progressLine : descriptionEl}\n      </Row.Subtitle>\n    </>\n  );\n\n  const onLoad = () => {\n    const progressLine = new MediaProgressLine();\n    progressLine.setMedia({\n      media: ctx.element.audio,\n      streamable: doc.supportsStreaming,\n      duration: doc.duration\n    });\n\n    setState('progressLine', progressLine.container);\n\n    ctx.addAudioListener('ended', () => setState('showProgress', false));\n    ctx.addAudioListener('play', () => setState('showProgress', true));\n\n    const audio = ctx.element.audio;\n    if(!audio.paused || audio.currentTime > 0) {\n      setState('showProgress', true);\n    }\n\n    return () => {\n      progressLine.removeListeners();\n      setState({showProgress: false, progressLine: undefined});\n    };\n  };\n\n  return {content, onLoad};\n}\n\nfunction constructDownloadPreloader(tryAgainOnFail = true) {\n  const preloader = new ProgressivePreloader({cancelable: true, tryAgainOnFail});\n  preloader.construct();\n\n  if(!tryAgainOnFail) {\n    preloader.circle.setAttributeNS(null, 'r', '23');\n    preloader.totalLength = 143.58203125;\n  }\n\n  return preloader;\n}\n\nexport const findMediaTargets = (anchor: HTMLElement, anchorMid: number/* , useSearch: boolean */) => {\n  let prev: MediaItem[], next: MediaItem[];\n  // if(anchor.classList.contains('search-super-item') || !useSearch) {\n  const isBubbles = !anchor.classList.contains('search-super-item');\n  const container = findUpClassName(anchor, !isBubbles ? 'tabs-tab' : 'bubbles-inner');\n  if(container) {\n    const attr = `:not([data-is-outgoing=\"1\"])`;\n    const justAudioSelector = `.audio:not(.is-voice)${attr}`;\n    let selectors: string[];\n    if(!anchor.matches(justAudioSelector)) {\n      selectors = [`.audio.is-voice${attr}`, `.media-round${attr}`];\n    } else {\n      selectors = [justAudioSelector];\n    }\n\n    if(isBubbles) {\n      const prefix = '.bubble:not(.webpage) ';\n      selectors = selectors.map((s) => prefix + s);\n    }\n\n    const selector = selectors.join(', ');\n\n    let elements = Array.from(container.querySelectorAll(selector)) as HTMLElement[];\n    elements = elements.filter((element) => element === anchor || element.matches(':not([data-to-be-skipped=\"1\"])'));\n    const idx = elements.indexOf(anchor);\n\n    const mediaItems: MediaItem[] = elements.map((element) => ({peerId: element.dataset.peerId.toPeerId(), mid: +element.dataset.mid}));\n\n    prev = mediaItems.slice(0, idx);\n    next = mediaItems.slice(idx + 1);\n  }\n  // }\n\n  if((next.length && next[0].mid < anchorMid) || (prev.length && prev[prev.length - 1].mid > anchorMid)) {\n    [prev, next] = [next.reverse(), prev.reverse()];\n  }\n\n  // prev = next = undefined;\n\n  return [prev, next];\n};\n\nexport type AudioElementOptions = {\n  message: Message.message,\n  middleware: Middleware,\n  /**\n   * Optional pre-extracted document. When set, it overrides extraction from `message.media`.\n   * Useful when the audio document lives in a sibling field of the message (e.g. poll\n   * `solution_media`).\n   */\n  doc?: MyDocument,\n  /**\n   * Optional storage-key disambiguator. See `AddMediaArgs.slot`. Required when two rows share the\n   * same `(peerId, mid)` but render different documents (e.g. poll description + explanation).\n   */\n  mediaSlot?: number,\n  withTime?: boolean,\n  voiceAsMusic?: boolean,\n  searchContext?: MediaSearchContext,\n  showSender?: boolean,\n  noAutoDownload?: boolean,\n  /**\n   * Keeps the duration out of the subtitle until the row plays. The profile playlist reads as\n   * `Artist — Title` over the file size alone, with the clock only while it runs.\n   */\n  /**\n   * Gives the row the hover a Row normally gets from being clickable. Off inside a bubble, where the\n   * row is a piece of the message rather than something to point at.\n   */\n  clickable?: boolean,\n  lazyLoadQueue?: LazyLoadQueue,\n  loadPromises?: Promise<any>[],\n  /** Whether the row offers to transcribe itself. Voice messages only. */\n  canTranscribe?: boolean,\n  uploadingFileName?: string,\n  shouldWrapAsVoice?: boolean,\n  customAudioToTextButton?: HTMLElement,\n  listLoaderFactory?: MediaListLoaderFactory,\n  /** An already-playing media element to bind to instead of adding a new one. */\n  globalMedia?: HTMLMediaElement,\n  isOut?: boolean,\n  fontWeight?: number,\n  fontSize?: number,\n  sizeType?: string,\n  getSize?: () => number\n};\n\n/**\n * An audio/voice row. It is a plain `div.audio` carrying its own API rather than a custom element:\n * the DOM node IS the handle, which is what every caller (bubbles, selection, round videos) already\n * relies on.\n */\nexport interface AudioElement extends HTMLDivElement {\n  message: Message.message;\n  audio: HTMLMediaElement;\n  listLoaderFactory: MediaListLoaderFactory;\n\n  /** Swaps the temporary outgoing message for the sent one and starts the playback wiring. */\n  replaceMessage(message: Message.message): void;\n  setUnread(unread: boolean): void;\n  togglePlay(e?: Event, paused?: boolean): void;\n  playWithTimestamp(timestamp: number): void;\n}\n\n/**\n * A row that holds back its playback wiring until its outgoing message is actually sent — the audio\n * row and the round-video bubble (`wrappers/video.ts`) both play by this contract.\n */\nexport interface DeferredMediaElement extends HTMLElement {\n  onLoad: (autoload?: boolean) => void;\n}\n\nexport function isAudioElement(element: unknown): element is AudioElement {\n  return element instanceof HTMLElement && element.classList.contains('audio');\n}\n\nexport default async function createAudioElement(options: AudioElementOptions): Promise<AudioElement> {\n  const {middleware} = options;\n  const doc = options.doc ?? (getMediaFromMessage(options.message) as MyDocument);\n  const isRealVoice = doc.type === 'voice';\n  const isVoice = !options.voiceAsMusic && isRealVoice;\n  const isOutgoing = options.message.pFlags.is_outgoing;\n  const uploadingFileName = options.uploadingFileName ?? options.message?.uploadingFileName?.[0];\n\n  let listenerSetter = new ListenerSetter();\n  let onTypeDisconnect: () => void;\n  let dispose: () => void;\n  let load: (shouldPlay: boolean, controlledAutoplay?: boolean) => void;\n  let onLoad: (autoload?: boolean) => void;\n\n  const [state, setState] = createStore<AudioRowState>({\n    isVoice: false,\n    isOut: !!options.isOut,\n    canTranscribe: false,\n    isUnread: !!(doc.type !== 'audio' && options.message && options.message.pFlags.media_unread),\n    isOutgoing: !!uploadingFileName,\n    withThumb: false,\n    cornerDownload: false,\n    downloading: false,\n    showProgress: false,\n    progressLine: undefined\n  });\n\n  const getDurationStr = () => {\n    const audio = ctx.element?.audio;\n    const duration = audio && audio.readyState >= audio.HAVE_CURRENT_DATA ? audio.duration : doc.duration;\n    return toHHMMSS(duration | 0);\n  };\n\n  let toggle: HTMLElement;\n  let playIconContainer: HTMLElement;\n\n  const downloadDiv = (<div class=\"audio-download\" />) as HTMLElement;\n  // The clock writes into a text node of its own so the unread dot beside it survives every update.\n  const timeText = document.createTextNode('');\n  const timeEl = (\n    <div class=\"audio-time\">\n      {timeText}\n      <Show when={state.isVoice && state.isUnread}>\n        <span class=\"audio-unread-dot\" />\n      </Show>\n    </div>\n  ) as HTMLElement;\n\n  const ctx: AudioRowContext = {\n    options,\n    doc,\n    timeEl,\n    state,\n    setState,\n    element: undefined,\n    listenerSetter,\n    readyPromise: undefined,\n    addAudioListener: ((...args: any[]) => (listenerSetter.add(ctx.element.audio) as any)(...args)) as any,\n    togglePlay: (e, paused) => ctx.element.togglePlay(e, paused)\n  };\n\n  const {content, onLoad: onTypeLoad} = await (isVoice || options.shouldWrapAsVoice ? wrapVoiceMessage(ctx) : wrapAudio(ctx));\n\n  const el = createRoot((d) => {\n    dispose = d;\n    return children(() => (\n      <AudioRow\n        state={state}\n        content={content}\n        clickable={!!options.clickable}\n        ref={(el) => toggle = el}\n        playIconRef={(el) => playIconContainer = el}\n      />\n    ))() as any as AudioElement;\n  });\n\n  ctx.element = el;\n  const setPlayIcon = createPlayPauseIcon(() => playIconContainer);\n\n  /**\n   * The glyph is a function of the media, not of the click: it morphs on every transition of\n   * `paused`, whoever caused it — this button, the topbar plate, another row playing the same\n   * track, the playlist advancing, the OS media keys. Reading the media rather than trusting which\n   * event fired also survives a `play`/`pause` pair that arrives late or out of order when the\n   * button is hit twice quickly. `animate: false` is for the two moments that are a mount rather\n   * than a transition — building the row, and resolving its media — where there is no one to\n   * perform the morph for.\n   */\n  const syncPlayState = (animate?: boolean) => {\n    const playing = !!el.audio && !el.audio.paused;\n    toggle.classList.toggle('playing', playing);\n    setPlayIcon(playing, animate);\n  };\n\n  el.message = options.message;\n  el.audio = options.globalMedia;\n  el.listLoaderFactory = options.listLoaderFactory;\n  el.dataset.mid = '' + options.message.mid;\n  el.dataset.peerId = '' + options.message.peerId;\n  if(options.globalMedia) el.dataset.toBeSkipped = '1';\n\n  timeText.textContent = getDurationStr();\n  syncPlayState(false);\n\n  const destroy = () => {\n    if(onTypeDisconnect) {\n      onTypeDisconnect();\n      onTypeDisconnect = null;\n    }\n\n    if(ctx.readyPromise) {\n      ctx.readyPromise.reject();\n    }\n\n    if(listenerSetter) {\n      listenerSetter.removeAll();\n      listenerSetter = null;\n    }\n\n    if(dispose) {\n      dispose();\n      dispose = null;\n    }\n  };\n\n  middleware.onDestroy(destroy);\n\n  const onDownloadInit = (shouldPlay: boolean) => {\n    if(shouldPlay) {\n      appMediaPlaybackController.willBePlayed(el.audio); // prepare for loading audio\n\n      if(IS_SAFARI && !el.audio.autoplay) {\n        el.audio.autoplay = true;\n      }\n    }\n  };\n\n  onLoad = (autoload: boolean) => {\n    onLoad = undefined;\n\n    const audio = el.audio ??= appMediaPlaybackController.addMedia({\n      message: el.message,\n      autoload,\n      doc: options.doc,\n      slot: options.mediaSlot,\n      middleware\n    }) as HTMLMediaElement;\n\n    const readyPromise = ctx.readyPromise = deferredPromise<void>();\n    if(audio.readyState >= audio.HAVE_CURRENT_DATA) readyPromise.resolve();\n    else {\n      ctx.addAudioListener('canplay', () => readyPromise.resolve(), {once: true});\n    }\n\n    onTypeDisconnect = onTypeLoad();\n\n    const getTimeStr = () => toHHMMSS(audio.currentTime | 0) + (isVoice ? (' / ' + getDurationStr()) : '');\n\n    // the row can be built while its track is already playing — scrolled back into view, or a list\n    // opened mid-playback — so take that state instead of morphing into it\n    syncPlayState(false);\n\n    if(!audio.paused || (audio.currentTime > 0 && audio.currentTime !== audio.duration)) {\n      timeText.textContent = getTimeStr();\n    }\n\n    toggle.addEventListener('click', (e: MouseEvent) => {\n      el.togglePlay(e);\n    });\n\n    ctx.addAudioListener('ended', () => {\n      syncPlayState();\n      timeText.textContent = getDurationStr();\n    });\n\n    ctx.addAudioListener('timeupdate', () => {\n      if((!audio.currentTime && audio.paused) || appMediaPlaybackController.isSafariBuffering(audio)) return;\n      timeText.textContent = getTimeStr();\n    });\n\n    ctx.addAudioListener('pause', () => syncPlayState());\n\n    // `emptied` is the controller dropping the media out from under the row (track swapped, list\n    // cleaned): the row stopped playing without ever being paused\n    ctx.addAudioListener('emptied', () => syncPlayState());\n\n    ctx.addAudioListener('play', () => {\n      timeText.textContent = getTimeStr();\n      syncPlayState();\n    });\n  };\n\n  el.setUnread = (unread) => setState('isUnread', unread);\n\n  el.replaceMessage = (message) => {\n    el.message = message;\n    el.dataset.mid = '' + message.mid;\n    delete el.dataset.isOutgoing;\n    onLoad?.(true);\n  };\n\n  el.togglePlay = (e?: Event, paused = el.audio.paused) => {\n    e && cancelEvent(e);\n\n    if(paused) {\n      setTargetsIfNeeded();\n      safePlay(el.audio);\n    } else {\n      el.audio.pause();\n    }\n  };\n\n  el.playWithTimestamp = (timestamp: number) => {\n    load?.(true);\n    setCurrentTime(el.audio, timestamp);\n    el.togglePlay(undefined, true);\n  };\n\n  const setTargetsIfNeeded = () => {\n    const hadSearchContext = !!options.searchContext;\n    const searchContextChanged = appMediaPlaybackController.setSearchContext(options.searchContext || {\n      peerId: NULL_PEER_ID,\n      inputFilter: {_: 'inputMessagesFilterEmpty'},\n      useSearch: false\n    });\n    const loaderFactoryChanged = el.listLoaderFactory && appMediaPlaybackController.getListLoaderFactory() !== el.listLoaderFactory;\n    if(searchContextChanged || loaderFactoryChanged) {\n      const thisTarget = el.dataset.toBeSkipped ? el.audio.parentElement : el;\n      const [prev, next] = !hadSearchContext ? [] : findMediaTargets(thisTarget, el.message.mid/* , options.searchContext.useSearch */);\n      appMediaPlaybackController.setTargets({peerId: el.message.peerId, mid: el.message.mid}, prev, next, el.listLoaderFactory);\n    }\n  };\n\n  if(uploadingFileName) {\n    el.append(downloadDiv);\n  }\n\n  if(doc.thumbs?.length) {\n    const imgs: HTMLElement[] = [];\n    const wrapped = await wrapPhoto({\n      photo: doc,\n      message: null,\n      container: toggle,\n      boxWidth: 48,\n      boxHeight: 48,\n      loadPromises: options.loadPromises,\n      withoutPreloader: true,\n      lazyLoadQueue: options.lazyLoadQueue,\n      middleware\n    });\n    toggle.style.width = toggle.style.height = '';\n    if(wrapped.images.thumb) imgs.push(wrapped.images.thumb);\n    if(wrapped.images.full) imgs.push(wrapped.images.full);\n\n    setState('withThumb', true);\n    imgs.forEach((img) => img.classList.add('audio-thumb'));\n  }\n\n  if(!isOutgoing) {\n    let preloader: ProgressivePreloader;\n\n    const autoDownload = doc.type !== 'audio'/*  || !options.noAutoDownload */;\n    onLoad(autoDownload);\n\n    const r = load = (shouldPlay: boolean, controlledAutoplay?: boolean) => {\n      load = undefined;\n\n      if(el.audio.src) {\n        return;\n      }\n\n      appMediaPlaybackController.resolveWaitingForLoadMedia(el.message.peerId, el.message.mid, el.message.pFlags.is_scheduled, options.mediaSlot);\n\n      onDownloadInit(shouldPlay);\n\n      if(!preloader) {\n        if(doc.supportsStreaming) {\n          setState('cornerDownload', true);\n\n          let pauseListener: Listener;\n          const onPlay = () => {\n            const preloader = constructDownloadPreloader(false);\n            const deferred = deferredPromise<void>();\n            deferred.notifyAll({done: 75, total: 100});\n            deferred.catch(() => {\n              el.audio.pause();\n              appMediaPlaybackController.willBePlayed(undefined);\n            });\n            deferred.cancel = () => {\n              deferred.cancel = noop;\n              deferred.reject(makeError('CANCELED'));\n            };\n            preloader.attach(downloadDiv, false, deferred);\n\n            pauseListener = ctx.addAudioListener('pause', () => {\n              deferred.cancel();\n            }, {once: true}) as any;\n\n            onDownloadInit(shouldPlay);\n          };\n\n          const playListener: any = ctx.addAudioListener('play', onPlay);\n          ctx.readyPromise.then(() => {\n            listenerSetter.remove(playListener);\n            pauseListener && listenerSetter.remove(pauseListener);\n          });\n        } else {\n          preloader = constructDownloadPreloader();\n\n          if(!shouldPlay) {\n            ctx.readyPromise = deferredPromise();\n          }\n\n          const startDownload = () => {\n            onDownloadInit(shouldPlay);\n\n            const download = appDownloadManager.downloadMediaURL({media: doc});\n\n            if(!shouldPlay) {\n              download.then(() => {\n                ctx.readyPromise.resolve();\n              });\n            }\n\n            preloader.attach(downloadDiv, false, download);\n            return {download};\n          };\n\n          preloader.setDownloadFunction(startDownload);\n          startDownload();\n        }\n      }\n\n      // the streaming preloader rides on the toggle, the plain one sits at the end of the row\n      if(state.cornerDownload) {\n        toggle.append(downloadDiv);\n      } else {\n        el.append(downloadDiv);\n      }\n\n      setState('downloading', true);\n\n      ctx.readyPromise.then(() => {\n        if(UNMOUNT_PRELOADER) {\n          setState('downloading', false);\n          downloadDiv.classList.add('downloaded');\n          setTimeout(() => {\n            downloadDiv.remove();\n          }, 200);\n        }\n\n        // release loaded audio\n        if(!controlledAutoplay && appMediaPlaybackController.willBePlayedMedia === el.audio) {\n          safePlay(el.audio);\n          appMediaPlaybackController.willBePlayed(undefined);\n        }\n      });\n    };\n\n    if(!el.audio?.src) {\n      if(autoDownload) {\n        r(false);\n      } else {\n        attachClickEvent(toggle, () => {\n          r(true);\n        }, {once: true, listenerSetter});\n      }\n    }\n  } else if(uploadingFileName) {\n    setState('downloading', true);\n    const preloader = constructDownloadPreloader(false);\n    const promise = appDownloadManager.getUpload(uploadingFileName);\n    preloader.attachPromise(promise);\n    el.dataset.isOutgoing = '1';\n    preloader.attach(downloadDiv, false);\n    promise.then(() => {\n      setState('downloading', false);\n      downloadDiv.classList.add('downloaded');\n      setTimeout(() => {\n        downloadDiv.remove();\n      }, 200);\n    });\n  }\n\n  return el;\n}\n","import {createRoot, createSignal, JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\n// The circular SVG progress ring used by round video notes (wrappers/video.ts)\n// and the video-note recording preview. Markup/classes are kept identical to\n// the original so existing CSS and the global resize handler in video.ts keep\n// working on whatever produced the element.\n//\n// `progress` is 0..1 (0 = empty ring, 1 = full). The ring is rotated -90° so it\n// fills clockwise from 12 o'clock.\n\nexport interface ProgressRingProps {\n  size: number;\n  strokeWidth?: number;\n  stroke?: string;\n  strokeOpacity?: number;\n  progress: number;\n  class?: string;\n  // Refs fire synchronously while the component body runs, so callers that need\n  // the real DOM nodes immediately (e.g. the imperative createProgressRing\n  // below, or wrappers/video.ts) get them here — calling the component as a\n  // function returns the HMR wrapper, NOT the <svg>, so don't rely on its return.\n  ref?: (svg: SVGSVGElement) => void;\n  circleRef?: (circle: SVGCircleElement) => void;\n}\n\nexport const DEFAULT_STROKE_WIDTH = 3.5;\n\n// Shared radius formula so this component and the imperative resize path in\n// wrappers/video.ts compute the same value (the strokeWidth*2 inset is the\n// original constant: at the default 3.5 it equals halfSize - 7).\nexport function getProgressRingRadius(size: number, strokeWidth: number = DEFAULT_STROKE_WIDTH) {\n  return size / 2 - strokeWidth * 2;\n}\n\nexport function getProgressRingCircumference(size: number, strokeWidth: number = DEFAULT_STROKE_WIDTH) {\n  return 2 * Math.PI * getProgressRingRadius(size, strokeWidth);\n}\n\nexport default function ProgressRing(props: ProgressRingProps): JSX.Element {\n  const strokeWidth = () => props.strokeWidth ?? DEFAULT_STROKE_WIDTH;\n  const radius = () => getProgressRingRadius(props.size, strokeWidth());\n  const circumference = () => getProgressRingCircumference(props.size, strokeWidth());\n  const dashoffset = () => circumference() * (1 - Math.max(0, Math.min(1, props.progress || 0)));\n\n  return (\n    <svg\n      ref={props.ref}\n      class={classNames('progress-ring', props.class)}\n      width={props.size}\n      height={props.size}\n      style={{transform: 'rotate(-90deg)'}}\n    >\n      <circle\n        ref={props.circleRef}\n        class=\"progress-ring__circle\"\n        stroke={props.stroke ?? 'white'}\n        stroke-opacity={props.strokeOpacity ?? 0.3}\n        stroke-width={strokeWidth()}\n        cx={props.size / 2}\n        cy={props.size / 2}\n        r={radius()}\n        fill=\"transparent\"\n        style={{\n          'stroke-dasharray': `${circumference()} ${circumference()}`,\n          'stroke-dashoffset': '' + dashoffset()\n        }}\n      />\n    </svg>\n  );\n}\n\nexport interface ProgressRingHandle {\n  element: SVGSVGElement;\n  circle: SVGCircleElement;\n  setProgress: (progress: number) => void;\n  setSize: (size: number) => void;\n  destroy: () => void;\n}\n\n// Imperative wrapper for non-Solid / class-based call sites. Owns its own\n// reactive root; call destroy() to dispose (e.g. from middleware.onDestroy).\n// Both progress and size can be driven imperatively; keeping them as signals\n// ensures a resize recomputes the circle geometry without losing progress.\nexport function createProgressRing(opts: Omit<ProgressRingProps, 'progress' | 'ref' | 'circleRef'> & {progress?: number}): ProgressRingHandle {\n  return createRoot((dispose) => {\n    const [progress, setProgress] = createSignal(opts.progress ?? 0);\n    const [size, setSize] = createSignal(opts.size);\n    // Capture the real DOM nodes via refs — they're set synchronously while the\n    // component body runs. The component's RETURN value is the HMR wrapper (not\n    // the <svg>), so we can't use it as the element.\n    let element: SVGSVGElement;\n    let circle: SVGCircleElement;\n    ProgressRing({\n      get size() {\n        return size();\n      },\n      strokeWidth: opts.strokeWidth,\n      stroke: opts.stroke,\n      strokeOpacity: opts.strokeOpacity,\n      class: opts.class,\n      get progress() {\n        return progress();\n      },\n      ref: (svg) => element = svg,\n      circleRef: (c) => circle = c\n    });\n\n    return {element, circle, setProgress, setSize, destroy: dispose};\n  });\n}\n","import {IS_SAFARI} from '@environment/userAgent';\nimport {IS_H265_SUPPORTED} from '@environment/videoSupport';\nimport {animateSingle} from '@helpers/animation';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport createVideo from '@helpers/dom/createVideo';\nimport handleVideoLeak from '@helpers/dom/handleVideoLeak';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport renderImageFromUrl from '@helpers/dom/renderImageFromUrl';\nimport safePlay from '@helpers/dom/safePlay';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport getMediaThumbIfNeeded from '@helpers/getStrippedThumbIfNeeded';\nimport liteMode from '@helpers/liteMode';\nimport makeError from '@helpers/makeError';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport onMediaLoad, {shouldIgnoreVideoError} from '@helpers/onMediaLoad';\nimport {fastRaf} from '@helpers/schedulers';\nimport throttle from '@helpers/schedulers/throttle';\nimport sequentialDom from '@helpers/sequentialDom';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport {Message, PhotoSize, VideoSize} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport appImManager from '@lib