ayButton, photoSize, videoSize, searchContext, autoDownload, managers = rootScope.managers, noAutoplayAttribute, ignoreStreaming, canAutoplay, useBlur, observer, setShowControlsOn, uploadingFileName, onGlobalMedia, onLoad, withPreview}: {\n  doc: MyDocument,\n  altDoc?: MyDocument,\n  container?: HTMLElement,\n  message?: Message.message,\n  boxWidth?: number,\n  boxHeight?: number,\n  withTail?: boolean,\n  isOut?: boolean,\n  middleware: Middleware,\n  lazyLoadQueue?: LazyLoadQueue,\n  noInfo?: boolean,\n  noPlayButton?: boolean,\n  group?: AnimationItemGroup,\n  onlyPreview?: boolean,\n  noPreview?: boolean,\n  withPreview?: boolean,\n  withoutPreloader?: boolean,\n  loadPromises?: Promise<any>[],\n  autoDownload?: ChatAutoDownloadSettings,\n  photoSize?: PhotoSize,\n  videoSize?: Extract<VideoSize, VideoSize.videoSize>,\n  searchContext?: MediaSearchContext,\n  managers?: AppManagers,\n  noAutoplayAttribute?: boolean,\n  ignoreStreaming?: boolean,\n  canAutoplay?: boolean,\n  useBlur?: boolean | number,\n  observer?: SuperIntersectionObserver,\n  setShowControlsOn?: HTMLElement,\n  uploadingFileName?: string,\n  onGlobalMedia?: (media: HTMLMediaElement) => void,\n  onLoad?: () => void\n}) {\n  const supportsStreaming = doc.supportsStreaming && !ignoreStreaming;\n  if(!supportsStreaming && altDoc && !onlyPreview && !IS_H265_SUPPORTED) {\n    doc = altDoc;\n    altDoc = undefined;\n  }\n\n  if(doc.type === 'gif' && container) {\n    container.classList.add('media-gif-wrapper');\n    container.dataset.docId = '' + doc.id;\n  }\n\n  const autoDownloadSize = autoDownload?.video;\n  let noAutoDownload = autoDownloadSize === 0;\n  const isGroupedItem = !(boxWidth && boxHeight);\n  uploadingFileName ??= message?.uploadingFileName?.[0];\n  // * a round video keeps looping its muted preview while it uploads, like the official clients do;\n  // * a regular video would just play under the progress spinner, so it waits for the upload instead\n  const suppressAutoplayWhileUploading = !!uploadingFileName && doc.type !== 'round';\n  canAutoplay ??= /* doc.sticker ||  */(\n    (\n      doc.type !== 'video' || (\n        doc.size <= MAX_VIDEO_AUTOPLAY_SIZE &&\n        !isGroupedItem\n      )\n    ) && (doc.type === 'gif' ? liteMode.isAvailable('gif') : liteMode.isAvailable('video'))\n  );\n  let spanTime: HTMLElement, spanPlay: HTMLElement;\n\n  let willObserveSound = false, noSoundIcon: HTMLElement, myMiddlewareHelper: MiddlewareHelper, originalMiddleware: Middleware;\n  if(!noInfo && container) {\n    spanTime = document.createElement('span');\n    spanTime.classList.add('video-time');\n    container.append(spanTime);\n\n    let needPlayButton = false;\n    if(doc.type !== 'gif') {\n      spanTime.innerText = toHHMMSS(doc.duration, false);\n\n      if(!noPlayButton && doc.type !== 'round') {\n        if(canAutoplay && !noAutoDownload) {\n          if(observer && USE_VIDEO_OBSERVER) {\n            willObserveSound = true;\n            // noAutoplayAttribute = true;\n            originalMiddleware = middleware;\n            myMiddlewareHelper = getMiddleware();\n            middleware = myMiddlewareHelper.get();\n          }\n\n          spanTime.append(noSoundIcon = Icon('nosound_filled', 'video-time-icon'));\n        } else {\n          needPlayButton = true;\n        }\n      }\n    } else {\n      spanTime.innerText = 'GIF';\n\n      if(!canAutoplay && !noPlayButton) {\n        needPlayButton = true;\n        noAutoDownload = undefined;\n      }\n    }\n\n    if(needPlayButton) {\n      spanPlay = Button('btn-circle video-play position-center', {icon: 'largeplay_filled', noRipple: true});\n      container.append(spanPlay);\n    }\n  }\n\n  const res: {\n    thumb?: typeof photoRes,\n    video?: HTMLVideoElement,\n    loadPromise: Promise<any>\n  } = {} as any;\n\n  if(doc.mime_type === 'image/gif') {\n    const photoRes = await wrapPhoto({\n      photo: doc,\n      message,\n      container,\n      boxWidth,\n      boxHeight,\n      withTail,\n      isOut,\n      lazyLoadQueue,\n      middleware,\n      withoutPreloader,\n      loadPromises,\n      autoDownloadSize,\n      size: photoSize,\n      managers,\n      useBlur,\n      uploadingFileName\n    });\n\n    res.thumb = photoRes;\n    res.loadPromise = photoRes.loadPromises.full;\n    return res;\n  }\n\n  /* const video = doc.type === 'round' ? appMediaPlaybackController.addMedia(doc, message.mid) as HTMLVideoElement : document.createElement('video');\n  if(video.parentElement) {\n    video.remove();\n  } */\n\n  let preloader: ProgressivePreloader; // it must be here, otherwise will get error before initialization in round onPlay\n\n  const video = createVideo({middleware, pip: willObserveSound});\n  video.classList.add('media-video');\n  video.muted = true;\n  if(doc.type === 'round') {\n    const divRound = document.createElement('div');\n    divRound.classList.add('media-round', 'z-depth-1');\n    divRound.dataset.mid = '' + message.mid;\n    divRound.dataset.peerId = '' + message.peerId;\n    (divRound as any).message = message;\n\n    const strokeWidth = 3.5;\n    const roundVideoSize = doc.w || mediaSizes.active.round.width;\n    const getProgressRingSize = () => Math.min(roundVideoSize, mediaSizes.active.round.width);\n\n    // Shared round progress-ring component (also used by the video-note\n    // recorder). Older round videos can be smaller than the current UI default,\n    // so keep this ring bound to the video's own rendered diameter.\n    const progressRingSize = getProgressRingSize();\n    const ring = createProgressRing({size: progressRingSize, strokeWidth, strokeOpacity: 0.3});\n    let progress = 0;\n    let circumference = getProgressRingCircumference(progressRingSize, strokeWidth);\n    const setProgress = (value: number) => {\n      progress = Math.max(0, Math.min(1, value || 0));\n      ring.circle.style.strokeDashoffset = '' + circumference * (1 - progress);\n    };\n    const resizeProgressRing = () => {\n      const