(!globalVideo.duration) {\n          return;\n        }\n\n        if(!isInDOM(globalVideo)) {\n          clear();\n          return;\n        }\n\n        if(globalVideo.paused) {\n          onFrame();\n        }\n\n        spanTime.firstChild.nodeValue = toHHMMSS(globalVideo.duration - globalVideo.currentTime, false);\n      };\n\n      const throttledTimeUpdate = throttle(() => {\n        fastRaf(onTimeUpdate);\n      }, 1000, false);\n\n      const noSoundIcon = Icon('nosound_filled', 'video-time-icon');\n      const setIsPaused = (paused: boolean) => {\n        divRound.classList.toggle('is-paused', paused);\n        if(paused) {\n          spanTime.append(noSoundIcon);\n        } else {\n          noSoundIcon.remove();\n        }\n      };\n\n      const onPlay = () => {\n        video.classList.add('hide');\n        setIsPaused(false);\n        animateSingle(onFrame, canvas);\n\n        if(preloader?.preloader && preloader.preloader.classList.contains('manual')) {\n          preloader.onClick();\n        }\n      };\n\n      const onPaused = () => {\n        if(!isInDOM(globalVideo)) {\n          clear();\n          return;\n        }\n\n        setIsPaused(true);\n      };\n\n      const onEnded = () => {\n        video.classList.remove('hide');\n        setIsPaused(true);\n\n        setCurrentTime(video, 0);\n        spanTime.firstChild.nodeValue = toHHMMSS(globalVideo.duration, false);\n\n        if(globalVideo.currentTime) {\n          setCurrentTime(globalVideo, 0);\n        }\n      };\n\n      globalVideo.addEventListener('play', onPlay);\n      globalVideo.addEventListener('timeupdate', throttledTimeUpdate);\n      globalVideo.addEventListener('pause', onPaused);\n      globalVideo.addEventListener('ended', onEnded);\n\n      attachClickEvent(canvas, (e) => {\n        cancelEvent(e);\n\n        // ! костыль\n        if(preloader && !preloader.detached) {\n          preloader.onClick();\n        }\n\n        // ! can't use it here. on Safari iOS video won't start.\n        /* if(globalVideo.readyState < 2) {\n          return;\n        } */\n\n        if(globalVideo.paused) {\n          const hadSearchContext = !!searchContext;\n          if(appMediaPlaybackController.setSearchContext(searchContext || {\n            peerId: NULL_PEER_ID,\n            inputFilter: {_: 'inputMessagesFilterEmpty'},\n            useSearch: false\n          })) {\n            const [prev, next] = !hadSearchContext ? [] : findMediaTargets(divRound, message.mid/* , searchContext.useSearch */);\n            appMediaPlaybackController.setTargets({peerId: message.peerId, mid: message.mid}, prev, next);\n          }\n\n          safePlay(globalVideo);\n        } else {\n          globalVideo.pause();\n        }\n      });\n\n      if(globalVideo.paused) {\n        if(globalVideo.duration && globalVideo.currentTime !== globalVideo.duration && globalVideo.currentTime > 0) {\n          onFrame();\n          onTimeUpdate();\n          video.classList.add('hide');\n        } else {\n          onPaused();\n        }\n      } else {\n        onPlay();\n      }\n    };\n\n    if(message.pFlags.is_outgoing) {\n      // ! WARNING ! just to type-check\n      (divRound as any as DeferredMediaElement).onLoad = onLoad;\n      divRound.dataset.isOutgoing = '1';\n    } else {\n      onLoad();\n    }\n  } else if(!noAutoplayAttribute && !suppressAutoplayWhileUploading) {\n    video.autoplay = true; // для safari\n  }\n\n  let photoRes: Awaited<ReturnType<typeof wrapPhoto>>;\n  if(message || onlyPreview || withPreview) {\n    photoRes = await wrapPhoto({\n      photo: doc,\n      message,\n      container,\n      boxWidth,\n      boxHeight,\n      withTail,\n      isOut,\n      lazyLoadQueue,\n      middleware,\n      withoutPreloader: true,\n      loadPromises,\n      autoDownloadSize: autoDownload?.photo,\n      size: photoSize,\n      managers,\n      useBlur,\n      canHaveVideoPlayer: willObserveSound,\n      uploadingFileName\n    });\n\n    res.thumb = photoRes;\n\n    if((!canAutoplay && doc.type !== 'gif') || onlyPreview) {\n      if(uploadingFileName && container && !onlyPreview) {\n        preloader = new ProgressivePreloader({\n          attachMethod: 'prepend',\n          isUpload: true\n        });\n        preloader.attachPromise(appDownloadManager.getUpload(uploadingFileName));\n        preloader.attach(container, false);\n      }\n\n      res.loadPromise = photoRes.loadPromises.full;\n      return res;\n    }\n\n    if(withTail) {\n      const foreignObject = (photoRes.images.thumb || photoRes.images.full).parentElement;\n      video.width = +foreignObject.getAttributeNS(null, 'width');\n      video.height = +foreignObject.getAttributeNS(null, 'height');\n      foreignObject.append(video);\n    }\n  } else if(!noPreview) { // * gifs masonry\n    const gotThumb = getMediaThumbIfNeeded({\n      photo: doc,\n      cacheContext: {} as ThumbCache,\n      useBlur: useBlur || true\n    });\n    if(gotThumb) {\n      const thumbImage = gotThumb.image;\n      thumbImage.classList.add('media-poster');\n      container?.append(thumbImage);\n      res.thumb = {\n        loadPromises: {\n          thumb: gotThumb.loadPromise,\n          full: Promise.resolve()\n        },\n        images: {\n          thumb: thumbImage,\n          full: null\n        },\n        preloader: null,\n        aspecter: null\n      };\n\n      loadPromises?.push(gotThumb.loadPromise);\n      res.loadPromise = gotThumb.loadPromise;\n    }\n  }\n\n  if(onlyPreview) {\n    return res;\n  }\n\n  // ! do not append before load or will get `URL safety check` error\n  const appendVideo = () => {\n    (photoRes?.aspecter || container).append(video);\n  };\n\n  if(!video.parentElement && container && video.poster/*  && !altDoc */) {\n    appendVideo();\n  }\n\n  let cacheContext: ThumbCache, altCacheContext: ThumbCache;\n  const getCacheContext = () => {\n    cacheContext = apiManagerProxy.getCacheContext(doc, videoSize?.type);\n    altDoc && (altCacheContext = apiManagerProxy.getCacheContext(altDoc, videoSize?.type));\n  };\n\n  getCacheContext();\n\n  if(uploadingFileName) { // means upload\n    preloader = new ProgressivePreloader({\n      attachMethod: 'prepend',\n      isUpload: true\n    });\n    preloader.attachPromise(appDownloadManager.getUpload(uploadingFileName));\n    preloader.attach(container, false);\n    noAutoDownload = undefined;\n\n    // * autoplay is suppressed while the upload is in progress, and the bubble\n    // * isn't re-rendered on send — resume playback once the upload completes\n    if(!noAutoplayAttribute && suppressAutoplayWhileUploading) {\n      appDownloadManager.getUpload(uploadingFileName).then(() => {\n        if(middleware && !middleware()) return;\n        video.autoplay = true; // * so the intersector resumes it after it scrolls back into view\n        safePlay(video);\n      }, noop);\n    }\n  } else if(!cacheContext.downloaded && !supportsStreaming && !withoutPreloader) {\n    preloader = new ProgressivePreloader({\n      attachMethod: 'prepend'\n    });\n  } else if(supportsStreaming && !withoutPreloader) {\n    preloader = new ProgressivePreloader({\n      cancelable: false,\n      attachMethod: 'prepend'\n    });\n  }\n\n  const renderDeferred = deferredPromise<void>();\n  video.addEventListener('error', (e) => {\n    if(shouldIgnoreVideoError(e)) {\n      return;\n    }\n\n    if(video.error.code !== 4) {\n      console.error('Error ' + video.error.code + '; details: ' + video.error.message);\n    }\n\n    if(preloader && !uploadingFileName) {\n      preloader.detach();\n    }\n\n    if(!renderDeferred.isFulfilled) {\n      renderDeferred.resolve();\n    }\n  }, {once: true});\n\n  if(doc.type === 'video' && spanTime) {\n    const onTimeUpdate = () => {\n      if(!video.duration) {\n        return;\n      }\n\n      spanTime.firstChild.nodeValue = toHHMMSS(video.duration - video.currentTime, false);\n    };\n\n    const throttledTimeUpdate = throttle(() => {\n      fastRaf(onTimeUpdate);\n    }, 1e3, false);\n\n    video.addEventListener('timeupdate', throttledTimeUpdate);\n\n    if(spanPlay) {\n      video.addEventListener('timeupdate', () => {\n        sequentialDom.mutateElement(spanPlay, () => {\n          spanPlay.remove();\n        });\n      }, {once: true});\n    }\n  }\n\n  video.muted = true;\n  video.loop = true;\n  // video.play();\n  if(!noAutoplayAttribute && !suppressAutoplayWhileUploading) {\n    video.autoplay = true;\n  }\n\n  let loadPhotoThumbFunc = noAutoDownload && photoRes?.preloader?.loadFunc;\n  const load = async() => {\n    if(preloader && noAutoDownload && !withoutPreloader) {\n      preloader.construct();\n      preloader.setManual();\n    }\n\n    getCacheContext();\n    let loadPromise: Promise<any> = Promise.resolve();\n    if((preloader && !uploadingFileName) || withoutPreloader) {\n      if(!cacheContext.downloaded && !supportsStreaming) {\n        const promise = loadPromise = appDownloadManager.downloadMediaURL({\n          media: doc,\n          queueId: lazyLoadQueue?.queueId,\n          onlyCache: noAutoDownload,\n          thumb: videoSize\n        });\n\n        if(preloader) {\n          preloader.attach(container, false, promise);\n        }\n      } else if(supportsStreaming) {\n        if(noAutoDownload) {\n          loadPromise = Promise.reject(makeError('NO_AUTO_DOWNLOAD'));\n        } else if(!cacheContext.downloaded && preloader) { // * check for uploading video\n          preloader.attach(container, false, null);\n          video.addEventListener(IS_SAFARI ? 'timeupdate' : 'canplay', () => {\n            preloader.detach();\n          }, {once: true});\n        }\n      }\n    }\n\n    if(!noAutoDownload && loadPhotoThumbFunc) {\n      loadPhotoThumbFunc();\n      loadPhotoThumbFunc = null;\n    }\n\n    noAutoDownload = undefined;\n\n    loadPromise.then(async() => {\n      if(middleware && !middleware()) {\n        renderDeferred.resolve();\n        return;\n      }\n\n      if(doc.type === 'round') {\n        appMediaPlaybackController.resolveWaitingForLoadMedia(message.peerId, message.mid, message.pFlags.is_scheduled);\n      }\n\n      getCacheContext();\n\n      const onError = (err: any) => {\n        console.error('video load error', video, err);\n        if(spanTime) {\n          spanTime.classList.add('is-error');\n          const previousIcon = spanTime.querySelector('.video-time-icon');\n          const newIcon = Icon('sendingerror_filled', 'video-time-icon');\n          if(previousIcon) previousIcon.replaceWith(newIcon);\n          else spanTime.append(newIcon);\n        }\n        renderDeferred.reject(err);\n      };\n      const onMediaLoadPromise = onMediaLoad(video);\n      const videoLeakPromise = handleVideoLeak(video, onMediaLoadPromise);\n      videoLeakPromise.catch(onError);\n      onMediaLoadPromise.then(() => {\n        if(group) {\n          animationIntersector.addAnimation({\n            animation: video,\n            group,\n            observeElement: video,\n            type: 'video',\n            locked: willObserveSound\n          });\n        }\n\n        if(preloader && !uploadingFileName) {\n          preloader.detach();\n        }\n\n        if(!video.parentElement && container && !video.poster/*  && !altDoc */) {\n          appendVideo();\n        }\n\n        if(altDoc) {\n          videoLeakPromise.then(() => {\n            video.pause();\n            renderDeferred.resolve();\n          });\n          setCurrentTime(video, 0.0001);\n        } else {\n          renderDeferred.resolve();\n        }\n\n        onLoad?.();\n        attachSoundObserver?.();\n      }, onError);\n\n      if(altDoc && altCacheContext) {\n        const sources = [\n          {context: cacheContext, type: 'video/mp4; codecs=\"hev1\"', width: doc.w},\n          {context: altCacheContext, type: 'video/mp4; codecs=\"avc1.64001E\"', width: altDoc.w}\n        ].map(({context, type, width}) => {\n          const source = document.createElement('source');\n          source.src = context.url;\n          // source.type = type;\n          source.width = width;\n          return source;\n        });\n\n        video.append(...sources);\n        video.load();\n      } else {\n        renderImageFromUrl(video, cacheContext.url);\n      }\n    }, noop);\n\n    return {download: loadPromise, render: Promise.all([loadPromise, renderDeferred])};\n  };\n\n  if(preloader && !uploadingFileName) {\n    preloader.setDownloadFunction(load);\n  }\n\n  container && ((container as any).preloader = preloader);\n\n  if(doc.type === 'gif' && !canAutoplay) {\n    attachClickEvent(container, (e) => {\n      cancelEvent(e);\n      spanPlay?.remove();\n      load();\n    }, {capture: true, once: true});\n  } else {\n    res.loadPromise = !lazyLoadQueue ?\n      (await load()).render :\n      (lazyLoadQueue.push({div: container, load: () => load().then(({render}) => render)}), Promise.resolve());\n  }\n\n  if(res.thumb) {\n    await res.thumb.loadPromises.thumb;\n  }\n\n  if(video) {\n    res.video = video;\n  }\n\n  const attachSoundObserver = willObserveSound ? () => {\n    video.mini = true;\n    video.pause();\n    // const button = ButtonIcon('zoomin video-to-viewer', {noRipple: true});\n    // container.append(button);\n\n    // const updateIcon = (muted: boolean) => {\n    //   replaceButtonIcon(button, muted ? 'speakeroff_filled' : 'speaker_filled');\n    // };\n\n    // updateIcon(video.muted);\n\n    const onMuted = () => {\n      return;\n\n      releaseSingleMedia?.(true);\n      releaseSingleMedia = undefined;\n      // video.muted = true;\n    };\n\n    const onUnmute = () => {\n      return;\n\n      // if(onAnotherSingleMedia !== _onAnotherSingleMedia) {\n      //   onAnotherSingleMedia?.();\n      // }\n\n      releaseSingleMedia = appMediaPlaybackController.setSingleMedia({\n        media: video,\n        message,\n        standalone: true\n      });\n      // onAnotherSingleMedia = _onAnotherSingleMedia = () => {\n      //   mute();\n      // };\n    };\n\n    const mute = () => {\n      if(!releaseSingleMedia) {\n        return;\n      }\n\n      noSoundIcon.classList.remove('hide');\n      onMuted();\n    };\n\n    const unmute = () => {\n      if(releaseSingleMedia) {\n        return;\n      }\n\n      noSoundIcon.classList.add('hide');\n      onUnmute();\n    };\n\n    // const toggle = (_unmute?: boolean) => {\n    //   if(_unmute !== undefined) (_unmute ? unmute : mute)();\n    //   else (releaseSingleMedia ? mute : unmute)();\n    //   updateIcon(video.muted);\n    // };\n\n    let releaseSingleMedia: ReturnType<AppMediaPlaybackController['setSingleMedia']>/* , _onAnotherSingleMedia: () => void */;\n    // const detachClickEvent = attachClickEvent(button, (e) => {\n    //   cancelEvent(e);\n    //   toggle();\n    // });\n\n    const onIntersection: IntersectionCallback = (entry) => {\n      if(!entry.isIntersecting) {\n        destroyPlayer();\n      }\n\n      if(!entry.isIntersecting && !video.muted) {\n        // toggle(false);\n        onMuted();\n      }\n    };\n\n    container.classList.add('media-video-container', 'media-video-mini');\n    observer.observe(video, onIntersection);\n\n    const destroyPlayer = () => {\n      debouncedDestroy.clearTimeout();\n      if(\n        !videoPlayer ||\n        !middleware() ||\n        isFullScreen() ||\n        videoPlayer.inPip\n      ) {\n        return;\n      }\n\n      videoPlayer.unmount();\n      videoPlayer.cleanup();\n      videoPlayer = undefined;\n      setShowControlsOn.classList.remove('show-controls');\n    };\n\n    const debouncedDestroy = debounce(destroyPlayer, 1000, false, true);\n\n    let videoPlayer: VideoPlayer, releasePromise: CancellablePromise<void>/* , changedVolume = false */;\n    container.onMiniVideoMouseMove = (e: MouseEvent) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      const toggleReleasePromise = (active: boolean) => {\n        if(active) releasePromise = deferredPromise();\n        else releasePromise?.resolve();\n      };\n\n      const onLock = (active: boolean) => {\n        if(ignoreNextEvents && ignoreNextEvents--) {\n          return;\n        }\n\n        const animationItem = animationIntersector.getAnimations(video)[0];\n        animationIntersector.toggleItemLock(animationItem, active);\n        toggleReleasePromise(active);\n      };\n\n      let ignoreNextEvents = 0;\n      videoPlayer = new VideoPlayer({\n        video,\n        container,\n        duration: video.duration,\n        streamable: true,\n        listenKeyboardEvents: 'fullscreen',\n        useGlobalVolume: 'no-init',\n        // shouldEnableSoundOnClick: () => !changedVolume,\n        onVolumeChange: (type) => {\n          const noVolume = !video.volume || video.muted;\n          let newValue: boolean;\n          if(noVolume) {\n            newValue = turnedObserverOn = false;\n          } else if(type === 'click') {\n            newValue = turnedObserverOn = true;\n          }\n\n          if(newValue !== turnedObserverOn && newValue !== undefined) {\n            appMediaPlaybackController.dispatchEvent('toggleVideoAutoplaySound', newValue);\n          }\n\n          // changedVolume = true;\n          // (!video.volume || video.muted ? mute : unmute)();\n        },\n        onFullScreen: (active) => {\n          onLock(active);\n          overlayCounter.isDarkOverlayActive = active;\n        },\n        onFullScreenToPip: () => {\n          ignoreNextEvents = 2;\n        },\n        onPip: onLock/* ,\n        onPipClose: () => {\n          if(!setShowControlsOn.classList.contains('show-controls')) {\n            debouncedDestroy();\n          }\n        } */\n      });\n\n      videoPlayer.volumeSelector.setVolume({muted: !turnedObserverOn, volume: video.volume});\n\n      videoPlayer.addEventListener('toggleControls', (show) => {\n        setShowControlsOn.classList.toggle('show-controls', show);\n        if(show) {\n          debouncedDestroy.clearTimeout();\n        } else {\n          debouncedDestroy();\n        }\n      });\n    };\n\n    // * mute video when other media is playing\n    const onAutoplaySound = (enabled: boolean) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      video.muted = appMediaPlaybackController.muted;\n      video.volume = Math.min(appMediaPlaybackController.volume, 1);\n    };\n\n    const onSingleMedia = (media: HTMLMediaElement) => {\n      if(media !== video && !video.muted) {\n        if(videoPlayer) {\n          videoPlayer.volumeSelector.setVolume({muted: true, volume: video.volume});\n        } else {\n          video.muted = true;\n        }\n      }\n    };\n\n    const onPlaybackMediaParams = (params: ReturnType<AppMediaPlaybackController['getPlaybackParams']>) => {\n      if(videoPlayer) {\n        return;\n      }\n\n      video.muted = turnedObserverOn ? params.muted : true;\n      video.playbackRate = params.playbackRate;\n      video.volume = Math.min(params.volume, 1);\n    };\n\n    appMediaPlaybackController.addEventListener('toggleVideoAutoplaySound', onAutoplaySound);\n    // appMediaPlaybackController.addEventListener('singleMedia', onSingleMedia);\n    appMediaPlaybackController.addEventListener('playbackParams', onPlaybackMediaParams);\n\n    middleware.onClean(() => {\n      // detachClickEvent();\n      releaseSingleMedia?.();\n      observer.unobserve(video, onIntersection);\n      delete container.onMiniVideoMouseMove;\n      appMediaPlaybackController.removeEventListener('toggleVideoAutoplaySound', onAutoplaySound);\n      // appMediaPlaybackController.removeEventListener('singleMedia', onSingleMedia);\n      appMediaPlaybackController.removeEventListener('playbackParams', onPlaybackMediaParams);\n    });\n\n    originalMiddleware.onClean(async() => {\n      await releasePromise;\n      myMiddlewareHelper.destroy();\n    });\n  } : undefined;\n\n  return res;\n}\n","/**\n * Bounds a promise that may never settle, resolving with `fallback` once `ms` has elapsed.\n *\n * Rejections still propagate — this guards only against an answer that never arrives at all\n * (a worker that stops replying, a request that never completes). Such a promise is invisible\n * to `.catch()`, so without a deadline it parks every `await` behind it for the tab's lifetime.\n */\nexport default function withTimeout<T, F = undefined>(\n  promise: PromiseLike<T>,\n  ms: number,\n  fallback?: F\n): Promise<T | F> {\n  let timeout: ReturnType<typeof setTimeout>;\n  const deadline = new Promise<F>((resolve) => {\n    timeout = setTimeout(() => resolve(fallback), ms);\n  });\n\n  // drop the timer as soon as the promise wins — callers on a render hot path would otherwise\n  // leave one pending timeout, holding its closure, behind every single call\n  return Promise.race([\n    Promise.resolve(promise).finally(() => clearTimeout(timeout)),\n    deadline\n  ]);\n}\n","import {createEffect, createMemo, createRoot} from 'solid-js';\nimport {useAppConfig, useAppState} from '@stores/appState';\nimport {ignoreRestrictionReasons} from '@helpers/restrictions';\n\nexport default function useContentSettings() {\n  const appConfig = useAppConfig();\n  const [appState] = useAppState();\n\n  const contentSettings = createMemo(() => appState.accountContentSettings.value);\n  const sensitiveEnabled = createMemo(() => (contentSettings() && contentSettings().pFlags.sensitive_enabled) ?? false);\n  const sensitiveCanChange = createMemo(() => (contentSettings() && contentSettings().pFlags.sensitive_can_change) ?? false);\n  const ignoreRestrictionReasons = createMemo(() => appConfig.ignore_restriction_reasons ?? []);\n  const needAgeVerification = createMemo(() => appConfig.need_age_video_verification ?? false);\n  const ageVerified = createMemo(() => !!appState.ageVerification);\n\n  return {\n    sensitiveEnabled,\n    sensitiveCanChange,\n    needAgeVerification,\n    ageVerified,\n    ignoreRestrictionReasons\n  };\n}\n\n// * handle settings changes\ncreateRoot(() => {\n  const contentSettings = useContentSettings();\n  createEffect(() => {\n    ignoreRestrictionReasons(contentSettings.ignoreRestrictionReasons());\n  });\n});\n","import PopupElement from '.';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport safeAssign from '@helpers/object/safeAssign';\nimport appImManager from '@lib/appImManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport useContentSettings from '@stores/contentSettings';\nimport Button from '@components/buttonTsx';\nimport styles from '@components/popups/ageVerification.module.scss';\n\nexport class AgeVerificationPopup extends PopupElement {\n  private onVerify: (verified: boolean) => void;\n\n  constructor(options: {\n    onVerify: (verified: boolean) => void\n  }) {\n    super(styles.popup, {\n      title: 'AgeVerification.Title',\n      body: true,\n      closable: true,\n      overlayClosable: true\n    })\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  _switchedToWebApp = false;\n\n  private async construct() {\n    const appConfig = await this.managers.apiManager.getAppConfig();\n    this.appendSolidBody(() => this._construct({appConfig}));\n  }\n\n  protected _construct({appConfig}: {appConfig: MTAppConfig}) {\n    let textKey: LangPackKey;\n    if(appConfig.verify_age_country === 'GB') {\n      textKey = 'AgeVerification.TextGB';\n    } else {\n      textKey = 'AgeVerification.Text';\n    }\n\n    const handleVerify = async() => {\n      const bot = await this.managers.appUsersManager.resolveUserByUsername(\n        appConfig.verify_age_bot_username ?? 'TelegramAge'\n      );\n      this._switchedToWebApp = true;\n      this.destroy();\n      appImManager.openWebApp({\n        botId: bot.id,\n        main: true,\n        noConfirmation: true,\n        forcePopup: true,\n        onClose: () => {\n          this.onVerify(!!useContentSettings().ageVerified());\n        }\n      });\n    };\n\n    return (\n      <>\n        <div class={styles.text}>\n          {i18n(textKey)}\n        </div>\n        <Button class={`${styles.button} btn-color-primary btn-primary`} onClick={handleVerify}>\n          {i18n('AgeVerification.Action')}\n        </Button>\n      </>\n    );\n  }\n\n  static create(): Promise<boolean> {\n    const promise = deferredPromise<boolean>();\n    const popup = PopupElement.createPopup(AgeVerificationPopup, {\n      onVerify: (verified) => promise.resolve(verified)\n    });\n\n    popup.addEventListener('close', () => {\n      if(!popup._switchedToWebApp) {\n        promise.resolve(false);\n      }\n    });\n    popup.show();\n\n    return promise;\n  }\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport safePlay from '@helpers/dom/safePlay';\nimport getImageFromStrippedThumb from '@helpers/getImageFromStrippedThumb';\nimport withTimeout from '@helpers/schedulers/withTimeout';\nimport {Document, Photo, PhotoSize} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport useContentSettings from '@stores/contentSettings';\nimport confirmationPopup from '@components/confirmationPopup';\nimport DotRenderer from '@components/dotRenderer';\nimport Icon from '@components/icon';\nimport {AgeVerificationPopup} from '@components/popups/ageVerification';\nimport SetTransition from '@components/singleTransition';\nimport {toastNew} from '@components/toast';\n\n// * the dot canvas is decoration on top of an already-covering blurred thumbnail; never let it\n// * hold up the message batch for longer than this\nconst SPOILER_READY_TIMEOUT = 2000;\n\nconst sensitiveSpoilers = new Set<HTMLElement>();\n\nexport function clearSensitiveSpoilers() {\n  for(const spoiler of sensitiveSpoilers) {\n    toggleMediaSpoiler({\n      mediaSpoiler: spoiler,\n      reveal: true,\n      destroyAfter: true\n    });\n  }\n  sensitiveSpoilers.clear();\n}\n\nexport function toggleMediaSpoiler(options: {\n  mediaSpoiler: HTMLElement,\n  reveal: boolean,\n  destroyAfter?: boolean\n}) {\n  const {mediaSpoiler, reveal, destroyAfter} = options;\n  SetTransition({\n    element: mediaSpoiler,\n    forwards: reveal,\n    className: 'is-revealing',\n    duration: 250,\n    onTransitionEnd: () => {\n      if(reveal && destroyAfter) {\n        mediaSpoiler.remove();\n        mediaSpoiler.middlewareHelper.destroy();\n      }\n    }\n  });\n}\n\n\nfunction revealSpoilerWithAnimation(options: {\n  mediaSpoiler: HTMLElement,\n  event: Event\n}) {\n  const {mediaSpoiler, event} = options;\n\n  const thumbnailCanvas = mediaSpoiler.querySelector('canvas.media-spoiler-thumbnail') as HTMLCanvasElement;\n  const canvas = mediaSpoiler.querySelector('canvas.canvas-dots') as HTMLElement;\n\n  const controls = DotRenderer.getImageSpoilerByElement(canvas);\n\n  if(!controls || !thumbnailCanvas) return false;\n\n  const result = controls.revealWithAnimation(event, thumbnailCanvas);\n  if(!result) return false;\n\n  return result.then(() => {\n    mediaSpoiler?.remove?.();\n    mediaSpoiler?.middlewareHelper?.destroy?.();\n  });\n}\n\nexport function onMediaSpoilerClick(options: {\n  mediaSpoiler: HTMLElement,\n  event: Event\n}) {\n  const {mediaSpoiler, event} = options;\n  const contentSettings = useContentSettings();\n  cancelEvent(event);\n\n  if(mediaSpoiler.classList.contains('is-revealing') || mediaSpoiler.dataset.isRevealing) {\n    return;\n  }\n\n  if(mediaSpoiler.dataset.isSensitive) {\n    if(!contentSettings.sensitiveCanChange()) {\n      toastNew({langPackKey: 'SensitiveContentUnavailable'});\n      return;\n    }\n\n    if(contentSettings.needAgeVerification() && !contentSettings.ageVerified()) {\n      AgeVerificationPopup.create().then((verified) => {\n        if(verified) {\n          clearSensitiveSpoilers();\n        }\n      });\n      return;\n    }\n\n    confirmationPopup({\n      titleLangKey: '18Plus',\n      descriptionLangKey: 'SensitiveContentDesc',\n      button: {\n        langKey: 'SensitiveContentConfirm'\n      },\n      checkbox: {\n        text: 'SensitiveContentRemember'\n      }\n    }).then((remember) => {\n      if(remember) {\n        rootScope.managers.appPrivacyManager.setContentSettings({sensitive_enabled: true});\n        clearSensitiveSpoilers();\n        return\n      }\n\n      delete mediaSpoiler.dataset.isSensitive;\n      onMediaSpoilerClick(options);\n    })\n    return;\n  }\n\n  const video = mediaSpoiler.parentElement.querySelector('video');\n  if(video && !mediaSpoiler.parentElement.querySelector('.video-play')) {\n    video.autoplay = true;\n    safePlay(video);\n  }\n\n  if(revealSpoilerWithAnimation({mediaSpoiler, event})) {\n    mediaSpoiler.dataset.isRevealing = 'true';\n    return;\n  }\n\n  toggleMediaSpoiler({\n    mediaSpoiler,\n    reveal: true,\n    destroyAfter: true\n  });\n}\n\nfunction wrapMediaSpoilerWithImage(options: {\n  image: Awaited<ReturnType<typeof getImageFromStrippedThumb>>['image']\n} & Parameters<typeof DotRenderer['create']>[0]) {\n  const {middleware, image} = options;\n  if(!middleware()) {\n    return;\n  }\n\n  image.classList.add('media-spoiler-thumbnail');\n\n  const container = document.createElement('div');\n  container.classList.add('media-spoiler-container');\n  container.middlewareHelper = middleware.create();\n\n  const {canvas, readyResult} = DotRenderer.create({\n    ...options,\n    middleware: container.middlewareHelper.get()\n  });\n\n  container.append(image, canvas);\n\n  return {container, readyResult};\n}\n\nexport function hasSensitiveSpoiler(container: HTMLElement) {\n  return container.querySelector('.media-spoiler-container[data-is-sensitive]') != null;\n}\n\nexport default async function wrapMediaSpoiler(\n  options: Omit<Parameters<typeof wrapMediaSpoilerWithImage>[0], 'image'> & {\n    media: Document.document | Photo.photo,\n    sensitive?: boolean\n  }\n) {\n  const {media, sensitive} = options;\n  const sizes = (media as Photo.photo).sizes || (media as Document.document).thumbs;\n  const thumb = sizes.find((size) => size._ === 'photoStrippedSize') as PhotoSize.photoStrippedSize;\n  if(!thumb) {\n    return;\n  }\n\n  const {image, loadPromise} = getImageFromStrippedThumb(media, thumb, true);\n  await loadPromise;\n\n  const {container, readyResult} = wrapMediaSpoilerWithImage({\n    ...options,\n    image\n  });\n\n  if(sensitive) {\n    const div = document.createElement('div');\n    div.classList.add('sensitive-content-warning');\n    div.replaceChildren(Icon('eyecross'), i18n('18Plus'));\n    container.prepend(div);\n    container.dataset.isSensitive = 'true';\n    sensitiveSpoilers.add(container);\n    options.middleware.onClean(() => {\n      sensitiveSpoilers.delete(container);\n    });\n  }\n\n  if(readyResult instanceof Promise) {\n    // Waiting here only avoids a blank first frame of the dot canvas — the media is already covered\n    // by the blurred thumbnail underneath. The bubble's render promise is awaited by the message\n    // batch processor, so blocking on this indefinitely stalls the whole chat: bail out after a\n    // deadline and let the dots appear late if the renderer wakes up later.\n    await withTimeout<unknown>(readyResult, SPOILER_READY_TIMEOUT);\n  }\n\n  return container;\n}\n","import {Middleware} from '@helpers/middleware';\nimport {Document, Message, MessageMedia, Photo, WebPage, VideoSize, StoryItem, MessageReplyHeader, MessageEntity} from '@layer';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport DivAndCaption from '@components/divAndCaption';\nimport wrapMessageForReply from '@components/wrappers/messageForReply';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapSticker from '@components/wrappers/sticker';\nimport wrapVideo from '@components/wrappers/video';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport {WrapReplyOptions} from '@components/wrappers/reply';\nimport {Modify} from '@types';\nimport {i18n} from '@lib/langPack';\nimport Icon from '@components/icon';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport compareUint8Arrays from '@helpers/bytes/compareUint8Arrays';\n\nconst MEDIA_SIZE = 32;\n\nexport type WrapReplyMediaOptions = {\n  message?: Message.message | Message.messageService,\n  storyItem?: StoryItem.storyItem,\n  replyHeader?: MessageReplyHeader,\n  mediaEl: HTMLElement,\n  size?: number,\n  isSensitive?: boolean,\n  middleware?: Middleware,\n  lazyLoadQueue?: false | LazyLoadQueue,\n  loadPromises?: Promise<any>[],\n  animationGroup?: WrapRichTextOptions['animationGroup']\n};\n\n/**\n * Render a small thumbnail of the media attached to a message (or story item)\n * into `mediaEl`. Handles photos, videos (via thumbs), stickers, gifs, and\n * round videos. Returns `{setMedia, isRound}` describing whether anything was\n * inserted and whether it should be drawn as a circle.\n *\n * Extracted from `wrapReplyDivAndCaption` so the same render can be reused\n * outside of reply-style previews (e.g. day cells in the date-picker calendar).\n */\nexport async function wrapReplyMedia({\n  message,\n  storyItem,\n  replyHeader,\n  mediaEl,\n  size = MEDIA_SIZE,\n  isSensitive,\n  middleware,\n  lazyLoadQueue,\n  loadPromises,\n  animationGroup\n}: WrapReplyMediaOptions): Promise<{setMedia: boolean, isRound: boolean}> {\n  loadPromises ??= [];\n\n  let messageMedia: MessageMedia | WebPage.webPage = storyItem?.media ||\n    (message as Message.message)?.media ||\n    (replyHeader?._ === 'messageReplyHeader' && replyHeader.reply_media);\n\n  if(messageMedia?._ === 'messageMediaStory') {\n    storyItem = messageMedia.story as StoryItem.storyItem;\n    messageMedia = storyItem?.media;\n  }\n\n  let setMedia = false, isRound = false;\n  if(!messageMedia || !mediaEl || (messageMedia as MessageMedia.messageMediaPhoto).ttl_seconds) {\n    return {setMedia, isRound};\n  }\n\n  messageMedia = (messageMedia as MessageMedia.messageMediaWebPage).webpage as WebPage.webPage || messageMedia;\n  const photo = (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo;\n  const document = (messageMedia as MessageMedia.messageMediaDocument).document as Document.document;\n  const spoiler = (messageMedia as MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument)?.pFlags?.spoiler;\n\n  if(!photo && !(document && document.thumbs?.length)) {\n    return {setMedia, isRound};\n  }\n\n  if(document?.type === 'sticker') {\n    await wrapSticker({\n      doc: document,\n      div: mediaEl,\n      lazyLoadQueue: lazyLoadQueue || undefined,\n      group: animationGroup,\n      width: size,\n      height: size,\n      middleware,\n      loadPromises\n    });\n    setMedia = true;\n  } else if(document?.type === 'gif' && document.video_thumbs) {\n    setMedia = true;\n    await wrapVideo({\n      doc: document,\n      container: mediaEl,\n      boxWidth: size,\n      boxHeight: size,\n      lazyLoadQueue: lazyLoadQueue || undefined,\n      noPlayButton: true,\n      noInfo: true,\n      middleware,\n      loadPromises,\n      withoutPreloader: true,\n      videoSize: document.video_thumbs[0] as Extract<VideoSize, VideoSize.videoSize>,\n      group: animationGroup\n    });\n  } else {\n    const m = photo || document;\n    isRound = document?.type === 'round';\n\n    try {\n      await wrapPhoto({\n        photo: m,\n        container: mediaEl,\n        boxWidth: size,\n        boxHeight: size,\n        size: choosePhotoSize(m, size, size),\n        middleware,\n        lazyLoadQueue,\n        noBlur: true,\n        withoutPreloader: true,\n        loadPromises\n      });\n\n      if(spoiler || isSensitive) {\n        const spoilerEl = await wrapMediaSpoiler({\n          media: m,\n          width: size,\n          height: size,\n          multiply: 0.1,\n          middleware,\n          animationGroup\n        });\n        mediaEl.append(spoilerEl);\n      }\n\n      setMedia = true;\n    } catch(err) {\n\n    }\n  }\n\n  return {setMedia, isRound};\n}\n\nexport async function wrapReplyDivAndCaption(options: {\n  title?: string | HTMLElement | DocumentFragment,\n  titleEl: HTMLElement,\n  subtitle?: string | HTMLElement | DocumentFragment,\n  subtitleEl: HTMLElement,\n  message: Message.message | Message.messageService,\n  storyItem?: StoryItem.storyItem,\n  mediaEl: HTMLElement,\n  isStoryExpired?: boolean,\n  isSensitive?: boolean,\n  middleware?: Middleware,\n  lazyLoadQueue?: false | LazyLoadQueue,\n  replyHeader?: MessageReplyHeader,\n  quote?: {text: string, entities?: MessageEntity[]},\n  withoutMediaType?: boolean,\n  canTranslate?: boolean\n} & WrapRichTextOptions) {\n  options.loadPromises ||= [];\n\n  const {titleEl, subtitleEl, mediaEl, message, loadPromises, animationGroup, middleware, lazyLoadQueue, replyHeader} = options;\n  let {storyItem, quote} = options;\n  let quoteIcon: HTMLElement | undefined;\n\n  let wrappedTitle = options.title;\n  if(wrappedTitle !== undefined) {\n    if(typeof(wrappedTitle) === 'string') {\n      wrappedTitle = limitSymbols(wrappedTitle, 140);\n      wrappedTitle = wrapEmojiText(wrappedTitle);\n    }\n\n    replaceContent(titleEl, wrappedTitle);\n  } else if(options.isStoryExpired) {\n    const icon = Icon('bomb_filled', 'expired-story-icon');\n    titleEl.append(icon, i18n('ExpiredStory'));\n  }\n\n  const isMessageReply = replyHeader?._ === 'messageReplyHeader';\n\n  if(isMessageReply && replyHeader.quote_text) {\n    quote ??= {\n      text: replyHeader.quote_text,\n      entities: replyHeader.quote_entities\n    };\n  }\n\n  if(isMessageReply && replyHeader.poll_option && message?._ === 'message' && message.media?._ === 'messageMediaPoll') {\n    const pollOption = message.media.poll.answers.find(answer => answer._ === 'pollAnswer' && compareUint8Arrays(replyHeader.poll_option, answer.option));\n    if(pollOption) {\n      quoteIcon = Icon('checkround_filled', 'inline-icon', 'inline-icon-left');\n      quote ??= {\n        text: pollOption.text.text,\n        entities: pollOption.text.entities\n      };\n    }\n  }\n\n  const mediaChildren = mediaEl ? Array.from(mediaEl.children).slice() : [];\n  const {setMedia, isRound} = await wrapReplyMedia({\n    message,\n    storyItem,\n    replyHeader,\n    mediaEl,\n    isSensitive: options.isSensitive,\n    middleware,\n    lazyLoadQueue,\n    loadPromises,\n    animationGroup\n  });\n\n  if(options.subtitle !== undefined) {\n    let wrappedSubtitle = options.subtitle;\n    if(typeof(wrappedSubtitle) === 'string') {\n      wrappedSubtitle = limitSymbols(wrappedSubtitle, 140);\n      wrappedSubtitle = wrapEmojiText(wrappedSubtitle);\n    }\n\n    replaceContent(subtitleEl, wrappedSubtitle || '');\n  } else if(storyItem && options.storyItem) {\n    subtitleEl.replaceChildren(i18n('Story'));\n  } else if(options.isStoryExpired) {\n    const icon = Icon('bomb_filled', 'expired-story-icon');\n    subtitleEl.replaceChildren(icon, i18n('ExpiredStory'));\n  } else if(quote) {\n    const fragment = wrapRichText(limitSymbols(quote.text, 200), {\n      ...options,\n      noLinebreaks: true,\n      entities: quote.entities,\n      noLinks: true\n      // noTextFormat: true\n    });\n\n    subtitleEl.replaceChildren(...[quoteIcon, fragment].filter(Boolean));\n  } else if(message) {\n    const fragment = await wrapMessageForReply(options);\n    subtitleEl.replaceChildren(fragment);\n  }\n\n  // if(options.isStoryExpired) {\n  //   setMedia = true;\n  // }\n\n  Promise.all(loadPromises).then(() => {\n    if(middleware && !middleware()) return;\n    mediaChildren.forEach((child) => child.remove());\n\n    if(mediaEl) {\n      mediaEl.classList.toggle('is-round', isRound);\n    }\n  });\n\n  return setMedia;\n}\n\nexport default class ReplyContainer extends DivAndCaption<(options: WrapReplyOptions) => Promise<void>> {\n  private mediaEl: HTMLElement;\n\n  constructor(protected className: string) {\n    super(className, async(options) => {\n      if(!this.mediaEl) {\n        this.mediaEl = document.createElement('div');\n        this.mediaEl.classList.add(this.className + '-media');\n      }\n\n      const isMediaSet = await wrapReplyDivAndCaption({\n        ...(options as Modify<typeof options, {message: Message.message | Message.messageService}>),\n        isSensitive: options.isChatSensitive || (options.message && isMessageSensitive(options.message)),\n        titleEl: this.title,\n        subtitleEl: this.subtitle,\n        mediaEl: this.mediaEl\n      });\n\n      if(options.isStoryExpired) {\n    // this.mediaEl.classList.add('is-expired-story', 'tgico-clock_filled');\n        this.container.classList.add('is-expired-story');\n      }\n\n      this.container.classList.toggle('is-media', isMediaSet);\n      if(isMediaSet) {\n        this.content.prepend(this.mediaEl);\n      } else {\n        this.mediaEl.remove();\n      }\n    });\n  }\n}\n","import {createSignal, createEffect, on, JSX, onCleanup, catchError} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport rootScope from '@lib/rootScope';\nimport {Photo, StoryItem, Document, MessageMedia, Message} from '@layer';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapVideo from '@components/wrappers/video';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {AnimationItemGroup} from '@components/animationIntersector';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {ChatAutoDownloadSettings} from '@hooks/useAutoDownloadSettings';\n\nlet processing = false;\nconst pollStories = () => {\n  if(processing) return;\n  const promises: PromiseLike<any>[] = [];\n  wrappedStories.forEach((map, peerId) => {\n    const ids = [...map.keys()];\n    const promise = rootScope.managers.appStoriesManager.getStoriesById(peerId, ids, true).then(() => {\n      ids.forEach((id) => {\n        if(!map.get(id).mounted) {\n          map.delete(id);\n          if(!map.size) {\n            wrappedStories.delete(peerId);\n          }\n        }\n      });\n    });\n\n    promises.push(promise);\n  });\n\n  Promise.all(promises).then(() => {\n    processing = false;\n  });\n};\n\nconst wrappedStories: Map<PeerId, Map<number, {mounted: number}>> = new Map();\n(window as any).wrappedStories = wrappedStories;\nsetInterval(pollStories, 300e3);\n\ntype CommonProperties = {\n  peerId: PeerId,\n  message?: Message.message,\n  boxWidth?: number,\n  boxHeight?: number,\n  withPreloader?: boolean,\n  noInfo?: boolean,\n  group?: AnimationItemGroup,\n  lazyLoadQueue?: LazyLoadQueue,\n  autoDownload?: ChatAutoDownloadSettings,\n  canAutoplay?: boolean,\n  noAspecter?: boolean\n};\n\nexport const wrapStoryMedia = (props: {\n  storyItem: StoryItem.storyItem,\n  forPreview?: boolean,\n  forViewer?: boolean,\n  containerProps?: JSX.HTMLAttributes<HTMLDivElement>,\n  childrenClassName?: string,\n  noPlayButton?: boolean,\n  onlyPreview?: boolean,\n  useBlur?: boolean | number\n} & CommonProperties) => {\n  const [thumb, setThumb] = createSignal<HTMLImageElement | HTMLCanvasElement>();\n  const [media, setMedia] = createSignal<HTMLImageElement | HTMLVideoElement>();\n  const [ready, setReady] = createSignal(false);\n\n  let map = wrappedStories.get(props.peerId);\n  if(!map) {\n    wrappedStories.set(props.peerId, map = new Map());\n  }\n\n  let c = map.get(props.storyItem.id);\n  if(!c) {\n    map.set(props.storyItem.id, c = {mounted: 0});\n  }\n  ++c.mounted;\n  onCleanup(() => {\n    --c.mounted;\n  });\n\n  const messageMedia = unwrap(props.storyItem.media);\n  const middleware = createMiddleware().get();\n\n  let div: HTMLDivElement;\n  const container = <div ref={div} {...(props.containerProps || {})}></div>;\n\n  const setChildrenClassName = (wrapped: {images: {thumb: HTMLElement, full: HTMLElement}}, className: string) => {\n    [\n      wrapped.images.thumb,\n      wrapped.images.full\n    ].filter(Boolean).forEach((image) => {\n      image.classList.add(className);\n    });\n  };\n\n  const wrappers = {\n    photo: (messageMedia: MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument) => {\n      const photo = (messageMedia as MessageMedia.messageMediaDocument).document as Document.document || (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo;\n      const result = wrapPhoto({\n        ...props,\n        container: div,\n        photo,\n        middleware,\n        ...(props.forPreview && {\n          ...(props.noAspecter && {\n            size: choosePhotoSize(photo, 150, 200)\n          }),\n          // size: choosePhotoSize(photo, 150, 200),\n          useRenderCache: false\n        }),\n        ...(props.forViewer && {\n          size: choosePhotoSize(photo, Infinity, Infinity),\n          // noBlur: true,\n          noFadeIn: true\n          // noThumb: true\n        }),\n        withoutPreloader: !props.withPreloader\n      });\n\n      result.then(async(result) => {\n        if(!middleware()) return;\n        if(props.childrenClassName) setChildrenClassName(result, props.childrenClassName);\n        await result.loadPromises.thumb;\n        if(!middleware()) return;\n        setThumb(result.images.thumb);\n        setReady(true);\n        await result.loadPromises.full;\n        if(!middleware()) return;\n        setMedia(result.images.full);\n      });\n\n      return result;\n    },\n\n    video: (messageMedia: MessageMedia.messageMediaDocument) => {\n      const document = messageMedia.document as Document.document;\n      const altDocument = messageMedia.alt_documents?.[0] as Document.document; // Supposedly there is only one alt document for stories\n      const result = wrapVideo({\n        ...props,\n        container: div,\n        doc: document,\n        altDoc: altDocument,\n        // ignoreStreaming: true,\n        middleware,\n        ...(props.forViewer && {\n          // noPreview: true,\n          noInfo: true,\n          // noPlayButton: true,\n          noAutoplayAttribute: true\n        }),\n        ...(props.forPreview && {\n          ...(props.noAspecter && {\n            photoSize: choosePhotoSize(document, 200, 200, false)\n          }),\n          onlyPreview: true\n        }),\n        withoutPreloader: !props.withPreloader\n      });\n\n      result.then(async(result) => {\n        if(!middleware()) return;\n        if(props.childrenClassName) {\n          if(result?.thumb) setChildrenClassName(result.thumb, props.childrenClassName);\n          if(result?.video) result.video.classList.add(props.childrenClassName);\n        }\n        if(result?.thumb) await result.thumb.loadPromises.thumb;\n        if(!middleware()) return;\n        if(result?.thumb) setThumb(result.thumb.images.full as any || result.thumb.images.thumb);\n        setReady(true);\n        const video = result?.video;\n        if(video && props.forViewer) {\n          video.loop = false;\n          video.muted = true;\n\n          if(IS_SAFARI) { // * force Safari to load the video\n            video.load();\n          }\n        }\n        await result?.loadPromise;\n        if(!middleware()) return;\n\n        setMedia(video);\n      });\n\n      return result;\n    }\n  };\n\n  let mediaResult: ReturnType<typeof wrapPhoto | typeof wrapVideo>;\n  switch(messageMedia._) {\n    case 'messageMediaPhoto': {\n      mediaResult = wrappers.photo(messageMedia);\n      break;\n    }\n\n    case 'messageMediaDocument': {\n      // if(!props.group && props.forPreview) {\n      //   mediaResult = wrappers.photo(messageMedia);\n      // } else {\n      mediaResult = wrappers.video(messageMedia);\n      // }\n\n      break;\n    }\n  }\n\n  return {container, div, media, mediaResult, thumb, ready};\n};\n\nexport const StoryPreview = (props: {\n  storyId: number,\n  loadPromises?: Promise<any>[],\n  onExpiredStory?: () => void,\n} & CommonProperties) => {\n  let {loadPromises} = props;\n  if(loadPromises) {\n    delete props.loadPromises;\n  }\n\n  const loadPromise: CancellablePromise<void> = loadPromises && deferredPromise();\n  loadPromises?.push(loadPromise);\n  loadPromises = undefined;\n\n  const [storyItem, setStoryItem] = createSignal<StoryItem.storyItem>(undefined, {equals: false});\n  const [f, setF] = createSignal<JSX.Element>();\n\n  rootScope.managers.acknowledged.appStoriesManager.getStoryById(props.peerId, props.storyId)\n  .then(async(result) => {\n    if(!result.cached) {\n      loadPromise?.resolve();\n    }\n\n    const storyItem = await result.result;\n    setStoryItem(storyItem);\n  });\n\n  const onStoryItem = (storyItem: StoryItem.storyItem) => {\n    if(!storyItem) {\n      props.onExpiredStory?.();\n      loadPromise.resolve();\n      return;\n    }\n\n    onCleanup(() => {\n      loadPromise?.reject();\n    });\n\n    // catchError(() => {\n    //   wrapStoryMedia({\n    //     ...props,\n    //     storyItem,\n    //     forPreview: true\n    //   });\n    // }, (err) => {\n    //   console.error('error', err);\n    // });\n\n    const {container, ready} = wrapStoryMedia({\n      ...props,\n      storyItem,\n      forPreview: true\n    });\n\n    createEffect(\n      on(\n        () => ready(),\n        () => {\n          loadPromise?.resolve();\n          setF(container);\n        },\n        {defer: true}\n      )\n    );\n  };\n\n  createEffect(\n    on(\n      () => storyItem(),\n      onStoryItem,\n      {defer: true}\n    )\n  );\n\n  return (\n    <>{f}</>\n  );\n};\n","export default function easeOutCubic(t: number, b: number, c: number, d: number) {\n  return t >= d ? b + c : easeOutCubicApply(t / d, c) + b;\n}\n\nexport function easeOutCubicApply(v: number, c: number) {\n  return c * (--v * v * v + 1);\n}\n","// Live waveform extractor for voice messages.\n// Taps the same MediaStream the Opus encoder is reading from and computes peaks\n// from raw Float32 PCM, mirroring the algorithm used by iOS / Android / tdesktop:\n//   * per-chunk amplitude = peak (max abs)\n//   * adaptive log-step downsampling (iOS-style) to keep ≤ 200 buckets in memory\n//   * final pass: peak = max(sum*1.8/N, 2500); value = min(31, min(s, peak)*31/peak)\n//   * 5-bit LSB-first packing across byte boundaries\n\nexport const WAVEFORM_SAMPLES_COUNT = 100;\nexport const WAVEFORM_BYTES_LENGTH = Math.ceil(WAVEFORM_SAMPLES_COUNT * 5 / 8); // 63\nconst DOWNSAMPLE_THRESHOLD = WAVEFORM_SAMPLES_COUNT * 2; // 200\n\n// ScriptProcessorNode is deprecated but present in every browser Telegram Web\n// targets — opus-recorder uses it too, so this adds no compatibility risk.\n// Migrating both to AudioWorkletNode would be a separate, larger change.\nconst SCRIPT_PROCESSOR_BUFFER_LENGTH = 4096;\n\nexport default class VoiceWaveformAnalyser {\n  private sourceNode: AudioNode;\n  private scriptProcessor: ScriptProcessorNode;\n  private peaks: number[];\n  private currentPeak: number;\n  private currentPeakCount: number;\n  private peakCompressionFactor: number;\n  private finished: boolean;\n  private paused: boolean;\n\n  constructor(sourceNode: AudioNode) {\n    this.sourceNode = sourceNode;\n    this.peaks = [];\n    this.currentPeak = 0;\n    this.currentPeakCount = 0;\n    this.peakCompressionFactor = 1;\n    this.finished = false;\n    this.paused = false;\n\n    const context = sourceNode.context;\n    this.scriptProcessor = context.createScriptProcessor(SCRIPT_PROCESSOR_BUFFER_LENGTH, 1, 1);\n    this.scriptProcessor.onaudioprocess = this.onAudioProcess;\n    sourceNode.connect(this.scriptProcessor);\n    // ScriptProcessor only fires onaudioprocess while plugged into the graph.\n    // Output buffer is left untouched, so destination receives silence.\n    this.scriptProcessor.connect(context.destination);\n  }\n\n  public setPaused(paused: boolean) {\n    this.paused = paused;\n  }\n\n  // Snapshot of the current per-bucket peaks (raw int amplitudes ~0..32767).\n  // Used by the recording UI to show the full waveform during pause/playback\n  // — the visualizer reads this and normalizes it for canvas rendering.\n  public getCurrentPeaks(): number[] {\n    return this.peaks.slice();\n  }\n\n  private onAudioProcess = (e: AudioProcessingEvent) => {\n    if(this.finished || this.paused) return;\n\n    const channel = e.inputBuffer.getChannelData(0);\n    const len = channel.length;\n    let peak = this.currentPeak;\n    let count = this.currentPeakCount;\n\n    for(let i = 0; i < len; ++i) {\n      const sample = Math.abs(channel[i]) * 32767;\n      if(sample > peak) peak = sample;\n      if(++count === this.peakCompressionFactor) {\n        this.peaks.push(peak);\n        peak = 0;\n        count = 0;\n\n        if(this.peaks.length >= DOWNSAMPLE_THRESHOLD) {\n          for(let j = 0; j < WAVEFORM_SAMPLES_COUNT; ++j) {\n            const a = this.peaks[j * 2];\n            const b = this.peaks[j * 2 + 1];\n            this.peaks[j] = a > b ? a : b;\n          }\n          this.peaks.length = WAVEFORM_SAMPLES_COUNT;\n          this.peakCompressionFactor *= 2;\n        }\n      }\n    }\n\n    this.currentPeak = peak;\n    this.currentPeakCount = count;\n  };\n\n  public finish(): Uint8Array {\n    if(this.finished) return new Uint8Array(WAVEFORM_BYTES_LENGTH);\n    this.finished = true;\n\n    try {\n      this.sourceNode.disconnect(this.scriptProcessor);\n    } catch(e) {}\n    this.scriptProcessor.disconnect();\n    this.scriptProcessor.onaudioprocess = null;\n\n    const peaks = this.peaks.slice(0, WAVEFORM_SAMPLES_COUNT);\n    while(peaks.length < WAVEFORM_SAMPLES_COUNT) peaks.push(0);\n\n    let sum = 0;\n    for(let i = 0; i < peaks.length; ++i) sum += peaks[i];\n    let normPeak = sum * 1.8 / peaks.length;\n    if(normPeak < 2500) normPeak = 2500;\n\n    const result = new Uint8Array(WAVEFORM_BYTES_LENGTH);\n    for(let i = 0; i < peaks.length; ++i) {\n      const clamped = peaks[i] < normPeak ? peaks[i] : normPeak;\n      const v = Math.min(31, (clamped * 31 / normPeak) | 0);\n      const bitOffset = i * 5;\n      const byteIndex = bitOffset >> 3;\n      const bitShift = bitOffset & 7;\n      result[byteIndex] |= (v << bitShift) & 0xFF;\n      if(bitShift > 3 && byteIndex + 1 < result.length) {\n        result[byteIndex + 1] |= (v >> (8 - bitShift)) & 0xFF;\n      }\n    }\n\n    return result;\n  }\n}\n","// Live amplitude tap used by the recording UI to draw the in-progress waveform.\n// Independent of VoiceWaveformAnalyser (which produces the 63-byte payload sent\n// with the message): this one emits a steady stream of unprocessed peaks at a\n// fixed window, so the UI can scroll bars without the iOS-style log compression\n// the message waveform applies.\n\nconst BUFFER_LENGTH = 2048; // ~43ms at 48kHz\n\nexport default class LiveWaveformAnalyser {\n  private sourceNode: AudioNode;\n  private scriptProcessor: ScriptProcessorNode;\n  private finished = false;\n  private paused = false;\n\n  public onpeak: (peak: number) => void = () => {};\n\n  constructor(sourceNode: AudioNode) {\n    this.sourceNode = sourceNode;\n    const ctx = sourceNode.context;\n    this.scriptProcessor = ctx.createScriptProcessor(BUFFER_LENGTH, 1, 1);\n    this.scriptProcessor.onaudioprocess = this.onAudioProcess;\n    sourceNode.connect(this.scriptProcessor);\n    this.scriptProcessor.connect(ctx.destination);\n  }\n\n  public setPaused(paused: boolean) {\n    this.paused = paused;\n  }\n\n  private onAudioProcess = (e: AudioProcessingEvent) => {\n    if(this.finished || this.paused) return;\n\n    const channel = e.inputBuffer.getChannelData(0);\n    let peak = 0;\n    for(let i = 0; i < channel.length; ++i) {\n      const v = Math.abs(channel[i]);\n      if(v > peak) peak = v;\n    }\n    this.onpeak(peak);\n  };\n\n  public destroy() {\n    if(this.finished) return;\n    this.finished = true;\n    try {\n      this.sourceNode.disconnect(this.scriptProcessor);\n    } catch(e) {}\n    this.scriptProcessor.disconnect();\n    this.scriptProcessor.onaudioprocess = null;\n  }\n}\n","// OGG container muxer for Opus packets, per RFC 7845 (Opus-in-Ogg) and RFC 3533 (Ogg).\n// Used to wrap raw Opus packets emitted by WebCodecs AudioEncoder into the\n// `audio/ogg;codecs=opus` container that Telegram expects for voice messages.\n\nconst OGG_CRC_TABLE = (() => {\n  const table = new Uint32Array(256);\n  for(let i = 0; i < 256; ++i) {\n    let r = i << 24;\n    for(let j = 0; j < 8; ++j) {\n      r = (r & 0x80000000) ? (((r << 1) >>> 0) ^ 0x04C11DB7) : ((r << 1) >>> 0);\n    }\n    table[i] = r >>> 0;\n  }\n  return table;\n})();\n\nfunction oggCrc(bytes: Uint8Array): number {\n  let crc = 0;\n  for(let i = 0; i < bytes.length; ++i) {\n    crc = (((crc << 8) >>> 0) ^ OGG_CRC_TABLE[((crc >>> 24) ^ bytes[i]) & 0xFF]) >>> 0;\n  }\n  return crc >>> 0;\n}\n\n// Default OpusHead used when the encoder did not provide a description.\n// Pre-skip 312 samples is the libopus default for a fresh encoder at 48kHz.\nfunction buildOpusHead(channels: number, inputSampleRate: number, preSkip: number): Uint8Array {\n  const head = new Uint8Array(19);\n  const view = new DataView(head.buffer);\n  head.set([0x4F, 0x70, 0x75, 0x73, 0x48, 0x65, 0x61, 0x64], 0); // 'OpusHead'\n  head[8] = 1;\n  head[9] = channels;\n  view.setUint16(10, preSkip, true);\n  view.setUint32(12, inputSampleRate, true);\n  view.setInt16(16, 0, true);\n  head[18] = 0;\n  return head;\n}\n\nfunction buildOpusTags(vendor: string): Uint8Array {\n  const enc = new TextEncoder();\n  const v = enc.encode(vendor);\n  const tags = new Uint8Array(8 + 4 + v.length + 4);\n  const view = new DataView(tags.buffer);\n  tags.set([0x4F, 0x70, 0x75, 0x73, 0x54, 0x61, 0x67, 0x73], 0); // 'OpusTags'\n  view.setUint32(8, v.length, true);\n  tags.set(v, 12);\n  view.setUint32(12 + v.length, 0, true); // 0 user comments\n  return tags;\n}\n\nconst OGG_HEADER_TYPE_CONTINUED = 0x01;\nconst OGG_HEADER_TYPE_BOS = 0x02;\nconst OGG_HEADER_TYPE_EOS = 0x04;\n\nconst MAX_PAGE_SEGMENTS = 255;\nconst MAX_SEGMENT_LEN = 255;\n\nexport interface OggOpusWriterOptions {\n  channels: number;\n  inputSampleRate: number;\n  vendor?: string;\n  preSkip?: number;\n  serialNumber?: number;\n  pageGranularitySamples?: number;\n}\n\nexport default class OggOpusWriter {\n  private channels: number;\n  private inputSampleRate: number;\n  private vendor: string;\n  private preSkip: number;\n  private serial: number;\n  private pageGranularitySamples: number;\n\n  private pageSequence = 0;\n  private granulePosition = 0;\n  private pageBuffer: Uint8Array[] = [];\n  private samplesInCurrentPage = 0;\n  private chunks: Uint8Array[] = [];\n  private headersWritten = false;\n  private finalized = false;\n\n  constructor(options: OggOpusWriterOptions) {\n    this.channels = options.channels;\n    this.inputSampleRate = options.inputSampleRate;\n    this.vendor = options.vendor ?? 'tweb';\n    this.preSkip = options.preSkip ?? 312;\n    this.serial = options.serialNumber ?? ((Math.random() * 0xFFFFFFFF) >>> 0);\n    this.pageGranularitySamples = options.pageGranularitySamples ?? 48000;\n  }\n\n  // Optional: replace the default OpusHead with the one the encoder provided\n  // (via EncodedAudioChunkMetadata.decoderConfig.description). Must be called\n  // before any writePacket().\n  public setOpusHead(opusHead: Uint8Array) {\n    if(this.headersWritten) return;\n    this.writeHeaderPagesWith(opusHead);\n  }\n\n  private ensureHeadersWritten() {\n    if(this.headersWritten) return;\n    this.writeHeaderPagesWith(buildOpusHead(this.channels, this.inputSampleRate, this.preSkip));\n  }\n\n  private writeHeaderPagesWith(opusHead: Uint8Array) {\n    this.emitPage([opusHead], 0, OGG_HEADER_TYPE_BOS);\n    this.emitPage([buildOpusTags(this.vendor)], 0, 0);\n    this.headersWritten = true;\n  }\n\n  public writePacket(packet: Uint8Array, durationSamples: number) {\n    if(this.finalized) return;\n    this.ensureHeadersWritten();\n\n    this.pageBuffer.push(packet);\n    this.samplesInCurrentPage += durationSamples;\n    this.granulePosition += durationSamples;\n\n    if(this.shouldFlushPage()) {\n      this.flushDataPage(false);\n    }\n  }\n\n  private shouldFlushPage(): boolean {\n    if(this.pageBuffer.length >= MAX_PAGE_SEGMENTS) return true;\n    if(this.samplesInCurrentPage >= this.pageGranularitySamples) return true;\n\n    let segmentCount = 0;\n    for(let i = 0; i < this.pageBuffer.length; ++i) {\n      segmentCount += Math.floor(this.pageBuffer[i].length / MAX_SEGMENT_LEN) + 1;\n      if(segmentCount >= MAX_PAGE_SEGMENTS) return true;\n    }\n    return false;\n  }\n\n  private flushDataPage(eos: boolean) {\n    if(!this.pageBuffer.length) {\n      if(eos) this.emitPage([], this.granulePosition, OGG_HEADER_TYPE_EOS);\n      return;\n    }\n    this.emitPage(this.pageBuffer, this.granulePosition, eos ? OGG_HEADER_TYPE_EOS : 0);\n    this.pageBuffer = [];\n    this.samplesInCurrentPage = 0;\n  }\n\n  private emitPage(packets: Uint8Array[], granulePos: number, headerType: number) {\n    const page = this.buildPage(packets, granulePos, headerType, this.pageSequence++);\n    this.chunks.push(page);\n  }\n\n  private buildPage(packets: Uint8Array[], granulePos: number, headerType: number, pageSequence: number): Uint8Array {\n    const segments: number[] = [];\n    let payloadLen = 0;\n    for(let i = 0; i < packets.length; ++i) {\n      const len = packets[i].length;\n      const full = Math.floor(len / MAX_SEGMENT_LEN);\n      for(let j = 0; j < full; ++j) segments.push(MAX_SEGMENT_LEN);\n      segments.push(len % MAX_SEGMENT_LEN);\n      payloadLen += len;\n    }\n\n    const segCount = segments.length;\n    const page = new Uint8Array(27 + segCount + payloadLen);\n    const view = new DataView(page.buffer);\n\n    page.set([0x4F, 0x67, 0x67, 0x53], 0); // 'OggS'\n    page[4] = 0;\n    page[5] = headerType;\n    view.setUint32(6, (granulePos >>> 0), true);\n    view.setUint32(10, (Math.floor(granulePos / 0x100000000) >>> 0), true);\n    view.setUint32(14, this.serial, true);\n    view.setUint32(18, pageSequence, true);\n    view.setUint32(22, 0, true);\n    page[26] = segCount;\n    for(let i = 0; i < segCount; ++i) page[27 + i] = segments[i];\n\n    let off = 27 + segCount;\n    for(let i = 0; i < packets.length; ++i) {\n      page.set(packets[i], off);\n      off += packets[i].length;\n    }\n\n    view.setUint32(22, oggCrc(page), true);\n    return page;\n  }\n\n  public finalize(): Uint8Array {\n    if(this.finalized) return this.concat();\n    this.ensureHeadersWritten();\n    this.flushDataPage(true);\n    this.finalized = true;\n    return this.concat();\n  }\n\n  // Build a playable OGG snapshot of everything written so far without mutating\n  // internal state. The snapshot always closes with an EOS page (carrying any\n  // pending packets) so decoders read the correct duration; the live writer\n  // keeps its state and continues from where it left off on the next packet.\n  public snapshot(): Uint8Array {\n    if(!this.headersWritten) return new Uint8Array(0);\n\n    const extraPage = this.buildPage(this.pageBuffer, this.granulePosition, OGG_HEADER_TYPE_EOS, this.pageSequence);\n\n    let total = extraPage.length;\n    for(let i = 0; i < this.chunks.length; ++i) total += this.chunks[i].length;\n\n    const out = new Uint8Array(total);\n    let off = 0;\n    for(let i = 0; i < this.chunks.length; ++i) {\n      out.set(this.chunks[i], off);\n      off += this.chunks[i].length;\n    }\n    out.set(extraPage, off);\n    return out;\n  }\n\n  private concat(): Uint8Array {\n    let total = 0;\n    for(let i = 0; i < this.chunks.length; ++i) total += this.chunks[i].length;\n    const out = new Uint8Array(total);\n    let off = 0;\n    for(let i = 0; i < this.chunks.length; ++i) {\n      out.set(this.chunks[i], off);\n      off += this.chunks[i].length;\n    }\n    return out;\n  }\n}\n","import DEBUG, {MOUNT_CLASS_TO} from '@config/debug';\nimport {appSettings, setAppSettings} from '@stores/appSettings';\nimport {logger} from '@lib/logger';\n\nconst log = logger('getStream');\n\n// The single chokepoint for call-related `getUserMedia` calls. Every call\n// path (P2P + group + previews) goes through here, so the stale-device-id\n// recovery logic lives in exactly one place.\n//\n// Two browsers raise different names for the same \"deviceId.exact no longer\n// matches a physical device\" condition: Chromium / Safari say\n// `OverconstrainedError`, Firefox says `NotFoundError`.\nfunction isMissingDeviceError(err: unknown): boolean {\n  if(!err || typeof err !== 'object') return false;\n  const name = (err as {name?: unknown}).name;\n  return name === 'OverconstrainedError' || name === 'NotFoundError';\n}\n\ntype StrippedConstraint<T> = {value: T, stripped: boolean};\nfunction stripDeviceId<T extends boolean | MediaTrackConstraints | undefined>(\n  constraint: T\n): StrippedConstraint<T> {\n  if(!constraint || typeof constraint !== 'object') return {value: constraint, stripped: false};\n  if(!('deviceId' in constraint)) return {value: constraint, stripped: false};\n  const {deviceId: _, ...rest} = constraint as MediaTrackConstraints & {deviceId?: unknown};\n  return {value: rest as T, stripped: true};\n}\n\nfunction applyMuted(stream: MediaStream, muted: boolean | undefined): MediaStream {\n  if(muted !== undefined) {\n    // `muted` is the voice-call microphone intent. A combined audio+video\n    // acquisition must not silently disable the camera when the user joins\n    // muted but explicitly chose to keep video on.\n    stream.getAudioTracks().forEach((track) => track.enabled = !muted);\n  }\n  return stream;\n}\n\nfunction getRequestedDeviceId(constraint: boolean | MediaTrackConstraints | undefined): string | undefined {\n  if(!constraint || typeof constraint !== 'object') return undefined;\n  const {deviceId} = constraint;\n  if(typeof deviceId === 'string') return deviceId;\n  if(!deviceId || typeof deviceId !== 'object' || Array.isArray(deviceId)) return undefined;\n  const {exact} = deviceId as ConstrainDOMStringParameters;\n  return typeof exact === 'string' ? exact : undefined;\n}\n\nfunction clearStaleDeviceId(kind: 'microphoneId' | 'cameraId', requestedDeviceId: string | undefined): boolean {\n  if(!requestedDeviceId || appSettings.callDevices?.[kind] !== requestedDeviceId) return false;\n  setAppSettings('callDevices', kind, '');\n  return true;\n}\n\n// Acquire a media stream for the call subsystem with self-healing fallback\n// when the persisted device id is stale.\n//\n// Recovery uses an **incremental** retry so a working preference isn't\n// thrown out alongside a dead one:\n//   1. Try the requested constraints unchanged.\n//   2. If they fail with the missing-device error AND both audio and video\n//      asked for an exact deviceId, retry keeping audio's deviceId but\n//      dropping video's. On success the camera was the culprit — clear\n//      cameraId, keep microphoneId.\n//   3. If step 2 also reports a missing device, try the symmetric probe: keep\n//      video's exact deviceId and drop audio's. On success only the microphone\n//      was stale, so cameraId survives.\n//   4. Otherwise (single-deviceId failure, or both probes failed) drop every\n//      requested deviceId, clear the matching appSettings fields, and retry on\n//      OS defaults.\n//\n// `muted` is only honoured if explicitly provided — leaving it `undefined`\n// means \"don't touch track enabled flags\" (callers that don't care about\n// muted state can skip the second argument).\nexport default async function getStream(\n  constraints: MediaStreamConstraints,\n  muted?: boolean\n): Promise<MediaStream> {\n  try {\n    return applyMuted(await navigator.mediaDevices.getUserMedia(constraints), muted);\n  } catch(err) {\n    if(!isMissingDeviceError(err)) throw err;\n\n    const audio = stripDeviceId(constraints.audio);\n    const video = stripDeviceId(constraints.video);\n    const requestedMicrophoneId = getRequestedDeviceId(constraints.audio);\n    const requestedCameraId = getRequestedDeviceId(constraints.video);\n\n    // Nothing to fall back FROM — propagate the original error so the caller\n    // surfaces it (this is a real \"no device at all\" condition, not a stale\n    // persisted choice).\n    if(!audio.stripped && !video.stripped) throw err;\n\n    log.warn('saved device id is stale, attempting fallback', {audioHadDeviceId: audio.stripped, videoHadDeviceId: video.stripped, error: (err as {name?: string})?.name});\n\n    // Both had deviceId — try keeping audio first; if that succeeds, the\n    // camera was the only stale device and the mic preference survives.\n    if(audio.stripped && video.stripped) {\n      try {\n        const stream = await navigator.mediaDevices.getUserMedia({\n          audio: constraints.audio,\n          video: video.value\n        });\n        clearStaleDeviceId('cameraId', requestedCameraId);\n        log('camera device was stale; kept microphone, cleared cameraId');\n        return applyMuted(stream, muted);\n      } catch(err2) {\n        if(!isMissingDeviceError(err2)) throw err2;\n      }\n\n      // The first probe only proved that keeping audio still fails. Preserve a\n      // working camera preference by trying the mirror image before clearing\n      // both ids; a stale microphone plus a valid camera is a common USB/headset\n      // hot-unplug case.\n      try {\n        const stream = await navigator.mediaDevices.getUserMedia({\n          audio: audio.value,\n          video: constraints.video\n        });\n        clearStaleDeviceId('microphoneId', requestedMicrophoneId);\n        log('microphone device was stale; kept camera, cleared microphoneId');\n        return applyMuted(stream, muted);\n      } catch(err3) {\n        if(!isMissingDeviceError(err3)) throw err3;\n        // Both exact ids may be stale — fall through to the dual-clear path.\n      }\n    }\n\n    const clearedMicrophone = audio.stripped && clearStaleDeviceId('microphoneId', requestedMicrophoneId);\n    const clearedCamera = video.stripped && clearStaleDeviceId('cameraId', requestedCameraId);\n\n    log.warn('clearing stale device id(s), retrying on OS defaults', {clearedMicrophone, clearedCamera});\n\n    return applyMuted(await navigator.mediaDevices.getUserMedia({\n      audio: audio.value,\n      video: video.value\n    }), muted);\n  }\n}\n\nDEBUG && (MOUNT_CLASS_TO.getStream = getStream);\n","// Native voice recorder built on the standard web platform — no WASM:\n//   getUserMedia → AudioContext(48k) → AudioWorklet (PCM tap) →\n//     WebCodecs AudioEncoder (opus) → OGG/Opus muxer.\n//\n// Mirrors the parts of the opus-recorder API that input.ts uses, so the\n// caller can swap implementations without conditionals at the use site.\n\nimport OggOpusWriter from './oggOpusWriter';\nimport isNativeVoiceRecorderSupported from './isNativeSupported';\nimport getStream from '@lib/calls/helpers/getStream';\n\nexport {isNativeVoiceRecorderSupported};\n\nconst WORKLET_SOURCE = `\nclass VoiceCaptureProcessor extends AudioWorkletProcessor {\n  constructor(options) {\n    super();\n    const opts = (options && options.processorOptions) || {};\n    this.bufferSize = opts.bufferSize || 2048;\n    this.buffer = new Float32Array(this.bufferSize);\n    this.bufferIndex = 0;\n  }\n  process(inputs) {\n    const input = inputs[0];\n    if(!input || !input[0] || input[0].length === 0) return true;\n    const channel = input[0];\n    let i = 0;\n    while(i < channel.length) {\n      const remaining = this.bufferSize - this.bufferIndex;\n      const toCopy = remaining < (channel.length - i) ? remaining : (channel.length - i);\n      this.buffer.set(channel.subarray(i, i + toCopy), this.bufferIndex);\n      this.bufferIndex += toCopy;\n      i += toCopy;\n      if(this.bufferIndex === this.bufferSize) {\n        this.port.postMessage(this.buffer.slice(0));\n        this.bufferIndex = 0;\n      }\n    }\n    return true;\n  }\n}\nregisterProcessor('voice-capture-processor', VoiceCaptureProcessor);\n`;\n\nconst WORKLET_PROCESSOR_NAME = 'voice-capture-processor';\nconst WORKLET_BUFFER_SIZE = 2048;\nconst ENCODER_SAMPLE_RATE = 48000;\nconst DEFAULT_BITRATE = 32000;\nconst DEFAULT_FRAME_DURATION_US = 20000;\nconst DEFAULT_OPUS_FRAME_SAMPLES = (DEFAULT_FRAME_DURATION_US * ENCODER_SAMPLE_RATE) / 1_000_000;\n\nexport interface NativeVoiceRecorderConfig {\n  encoderSampleRate?: number;\n  numberOfChannels?: number;\n  encoderBitRate?: number;\n  mediaTrackConstraints?: boolean | MediaTrackConstraints;\n}\n\ntype State = 'inactive' | 'recording' | 'paused';\n\nexport default class NativeVoiceRecorder {\n  public sourceNode: MediaStreamAudioSourceNode;\n  public state: State = 'inactive';\n\n  public onstart: () => void = () => {};\n  public onstop: () => void = () => {};\n  public onpause: () => void = () => {};\n  public onresume: () => void = () => {};\n  public ondataavailable: (data: Uint8Array) => void = () => {};\n\n  private config: Required<Pick<NativeVoiceRecorderConfig, 'encoderSampleRate' | 'numberOfChannels' | 'encoderBitRate'>> & {\n    mediaTrackConstraints: boolean | MediaTrackConstraints\n  };\n\n  private stream: MediaStream;\n  private audioContext: AudioContext;\n  private workletNode: AudioWorkletNode;\n  private encoder: AudioEncoder;\n  private writer: OggOpusWriter;\n  private encoderTimestampUs = 0;\n  private opusHeadCaptured = false;\n  public notifySamples: (samples: Float32Array) => void;\n\n  static isSupported = isNativeVoiceRecorderSupported;\n\n  constructor(config: NativeVoiceRecorderConfig = {}) {\n    this.config = {\n      encoderSampleRate: config.encoderSampleRate ?? ENCODER_SAMPLE_RATE,\n      numberOfChannels: config.numberOfChannels ?? 1,\n      encoderBitRate: config.encoderBitRate ?? DEFAULT_BITRATE,\n      mediaTrackConstraints: config.mediaTrackConstraints ?? true\n    };\n  }\n\n  // Choose the microphone to record with (empty/undefined = OS default). The\n  // caller passes the user's pick from Settings → Speakers and Camera\n  // (appSettings.callDevices.microphoneId), same source as calls. Applied on the\n  // next start().\n  public setMicrophoneId(microphoneId?: string) {\n    this.config.mediaTrackConstraints = microphoneId ? {deviceId: {exact: microphoneId}} : true;\n  }\n\n  public async start(): Promise<void> {\n    if(this.state !== 'inactive') return;\n\n    // Reuse the call stack's getUserMedia chokepoint: if the selected mic is\n    // gone it strips the deviceId, clears the stale appSettings.callDevices.\n    // microphoneId and retries on the OS default — same self-healing as calls.\n    this.stream = await getStream({audio: this.config.mediaTrackConstraints});\n\n    this.audioContext = new AudioContext({sampleRate: this.config.encoderSampleRate});\n    this.sourceNode = this.audioContext.createMediaStreamSource(this.stream);\n\n    const blob = new Blob([WORKLET_SOURCE], {type: 'application/javascript'});\n    const workletUrl = URL.createObjectURL(blob);\n    try {\n      await this.audioContext.audioWorklet.addModule(workletUrl);\n    } finally {\n      URL.revokeObjectURL(workletUrl);\n    }\n\n    this.workletNode = new AudioWorkletNode(this.audioContext, WORKLET_PROCESSOR_NAME, {\n      numberOfInputs: 1,\n      numberOfOutputs: 1,\n      outputChannelCount: [this.config.numberOfChannels],\n      processorOptions: {bufferSize: WORKLET_BUFFER_SIZE}\n    });\n\n    this.writer = new OggOpusWriter({\n      channels: this.config.numberOfChannels,\n      inputSampleRate: this.config.encoderSampleRate\n    });\n\n    this.encoder = new AudioEncoder({\n      output: (chunk, metadata) => this.onEncoderChunk(chunk, metadata),\n      error: (err) => console.error('[NativeVoiceRecorder] encoder error:', err)\n    });\n\n    this.encoder.configure({\n      codec: 'opus',\n      sampleRate: this.config.encoderSampleRate,\n      numberOfChannels: this.config.numberOfChannels,\n      bitrate: this.config.encoderBitRate\n    });\n\n    this.workletNode.port.onmessage = (e: MessageEvent<Float32Array>) => this.onWorkletMessage(e.data);\n\n    this.sourceNode.connect(this.workletNode);\n    // AudioWorkletNode needs a downstream consumer for process() to be called;\n    // outputs are silent (we never write to them).\n    this.workletNode.connect(this.audioContext.destination);\n\n    this.state = 'recording';\n    this.encoderTimestampUs = 0;\n    this.opusHeadCaptured = false;\n    this.onstart();\n  }\n\n  private onWorkletMessage(samples: Float32Array) {\n    if(this.state !== 'recording') return;\n    if(this.notifySamples) this.notifySamples(samples);\n    const numberOfFrames = samples.length / this.config.numberOfChannels;\n    const audioData = new AudioData({\n      format: 'f32-planar',\n      sampleRate: this.config.encoderSampleRate,\n      numberOfFrames,\n      numberOfChannels: this.config.numberOfChannels,\n      timestamp: this.encoderTimestampUs,\n      data: samples.slice()\n    });\n    this.encoderTimestampUs += (numberOfFrames * 1_000_000) / this.config.encoderSampleRate;\n    try {\n      this.encoder.encode(audioData);\n    } catch(err) {\n      console.error('[NativeVoiceRecorder] encode error:', err);\n    }\n    audioData.close();\n  }\n\n  private onEncoderChunk(chunk: EncodedAudioChunk, metadata?: EncodedAudioChunkMetadata) {\n    if(!this.opusHeadCaptured && metadata?.decoderConfig?.description) {\n      const desc = metadata.decoderConfig.description;\n      let bytes: Uint8Array;\n      if(desc instanceof ArrayBuffer) {\n        bytes = new Uint8Array(desc);\n      } else {\n        const view = desc as ArrayBufferView;\n        bytes = new Uint8Array(view.buffer as ArrayBuffer, view.byteOffset, view.byteLength);\n      }\n      this.writer.setOpusHead(bytes);\n      this.opusHeadCaptured = true;\n    }\n\n    const data = new Uint8Array(chunk.byteLength);\n    chunk.copyTo(data);\n\n    const durationUs = chunk.duration ?? DEFAULT_FRAME_DURATION_US;\n    const durationSamples = Math.round((durationUs * ENCODER_SAMPLE_RATE) / 1_000_000) || DEFAULT_OPUS_FRAME_SAMPLES;\n    this.writer.writePacket(data, durationSamples);\n  }\n\n  // Pause keeps the worklet → encoder pipeline wired up but ignores incoming\n  // PCM samples. The encoder is flushed so the OGG snapshot is playable.\n  public async pause(): Promise<void> {\n    if(this.state !== 'recording') return;\n    this.state = 'paused';\n    if(this.encoder && this.encoder.state !== 'closed') {\n      try {\n        await this.encoder.flush();\n      } catch(e) {}\n    }\n    this.onpause();\n  }\n\n  public resume(): void {\n    if(this.state !== 'paused') return;\n    this.state = 'recording';\n    this.onresume();\n  }\n\n  // Build a playable OGG of everything captured so far without ending the\n  // recording. Used to preview the in-progress voice message during pause.\n  public getSnapshot(): Uint8Array {\n    return this.writer ? this.writer.snapshot() : new Uint8Array(0);\n  }\n\n  public async stop(): Promise<void> {\n    if(this.state === 'inactive') return;\n    this.state = 'inactive';\n\n    try {\n      this.sourceNode?.disconnect();\n    } catch(e) {}\n    if(this.workletNode) {\n      try {\n        this.workletNode.disconnect();\n      } catch(e) {}\n      this.workletNode.port.onmessage = null;\n    }\n\n    if(this.stream) {\n      this.stream.getTracks().forEach((t) => t.stop());\n    }\n\n    if(this.encoder && this.encoder.state !== 'closed') {\n      try {\n        await this.encoder.flush();\n      } catch(e) {\n        console.error('[NativeVoiceRecorder] flush error:', e);\n      }\n      try {\n        this.encoder.close();\n      } catch(e) {}\n    }\n\n    const ogg = this.writer ? this.writer.finalize() : new Uint8Array(0);\n\n    if(this.audioContext && this.audioContext.state !== 'closed') {\n      try {\n        await this.audioContext.close();\n      } catch(e) {}\n    }\n\n    this.ondataavailable(ogg);\n    this.onstop();\n  }\n}\n","import simulateEvent from '@helpers/dom/dispatchEvent';\n\nexport default function stopTrack(track: MediaStreamTrack) {\n  track.stop();\n  simulateEvent(track, 'ended');\n}\n","import getStream from '@lib/calls/helpers/getStream';\nimport stopTrack from '@lib/calls/helpers/stopTrack';\n\nexport type StreamAcquisition = {\n  // Resolves to the live stream, or `undefined` if dispose() was called before\n  // (or while) getUserMedia resolved. Rejects only on a real acquisition error\n  // that happened while the stream was still wanted — once disposed, a rejection\n  // is swallowed and surfaces as `undefined` instead.\n  promise: Promise<MediaStream>,\n  // Release the acquisition. Stops the stream's tracks if it has already\n  // resolved; otherwise flags it so the stream is stopped the instant it\n  // resolves. Idempotent, and safe to call before the stream exists.\n  dispose: () => void\n};\n\n// `getStream` (getUserMedia under it) CAN'T be cancelled: by the time the\n// promise resolves the device is already captured. So if the owner — a Solid\n// component, a recorder — is torn down (close popup, switch chat) WHILE the\n// acquire is in flight, the resolved stream is orphaned and the camera/mic\n// stays live forever (hardware indicator stuck on): teardown ran before there\n// was a stream to stop.\n//\n// This wraps `getStream` as a disposable handle. Crucially it returns\n// SYNCHRONOUSLY — the caller gets `dispose` before the `await`, so it can wire\n// it into its teardown (Solid `onCleanup`, a class release()/cleanup()...)\n// up-front, closing the window. dispose() owns the stream's tracks: stops them\n// now if resolved, or the moment they resolve if not. Owners WITHOUT\n// authoritative lifecycle state should acquire camera/mic through here instead\n// of raw `getStream` (the call instances do have such state and guard inline\n// with `isClosing`, so they stay on `getStream`).\nexport default function acquireStream(\n  constraints: MediaStreamConstraints,\n  muted?: boolean\n): StreamAcquisition {\n  let disposed = false;\n  let acquired: MediaStream | undefined;\n\n  const promise = (async() => {\n    let stream: MediaStream;\n    try {\n      stream = await getStream(constraints, muted);\n    } catch(err) {\n      // The owner already walked away — its error handler is gone, so swallow\n      // the rejection and resolve like a (benign) disposed acquire rather than\n      // surfacing a stale error / leaving it unhandled.\n      if(disposed) return undefined;\n      throw err;\n    }\n\n    // Torn down while getUserMedia was resolving — stop the orphaned stream and\n    // hand back nothing.\n    if(disposed) {\n      stream.getTracks().forEach((track) => stopTrack(track));\n      return undefined;\n    }\n\n    acquired = stream;\n    return stream;\n  })();\n\n  const dispose = () => {\n    disposed = true;\n    if(acquired) {\n      acquired.getTracks().forEach((track) => stopTrack(track));\n      acquired = undefined;\n    }\n  };\n\n  return {promise, dispose};\n}\n","// Native round-video-note recorder.\n//\n//   getUserMedia(video + audio) → center-cropped square <canvas> (drawn per\n//   camera frame) → canvas.captureStream() + the mic track → MediaRecorder\n//   (mp4/avc1+aac, or webm/vp9|vp8+opus fallback) → Blob.\n//\n// Why the canvas: round notes are SQUARE (iOS/Desktop 400×400, Android 384×384;\n// we use the larger, 400). Cameras only output rectangular feeds (640×480,\n// 1280×720…), and MediaRecorder would otherwise encode that rectangle — so the\n// sent file would neither be square nor match the documentAttributeVideo w/h.\n// Drawing a centre-cropped square onto a fixed-size canvas guarantees the\n// encoded video is exactly `width`×`height`, matching the official clients.\n//\n// `stream` stays the RAW camera+mic stream (the chat input shows it in the\n// preview circle and taps its audio for the waveform); the MediaRecorder\n// records the canvas stream instead.\n//\n// Paused preview: round notes are sent as mp4 (the only container every\n// recipient — incl. iOS/macOS — can play), but Chrome's mp4 MediaRecorder emits\n// data ONLY at stop(), so the mid-recording snapshot the paused preview plays\n// would be empty. To keep preview working \"like voice\" we run a SECOND, webm\n// recorder on the same stream purely for getSnapshot() (webm timeslice chunks\n// are independently playable). The sent file is always the mp4 one.\n//\n// Mirrors the parts of the NativeVoiceRecorder API that input.ts uses (state,\n// onstart/onstop/onpause/onresume/ondataavailable, getSnapshot).\n\nimport {IS_APPLE_MOBILE, IS_SAFARI} from '@environment/userAgent';\nimport acquireStream, {StreamAcquisition} from '@lib/calls/helpers/acquireStream';\n\nexport interface NativeVideoRecorderConfig {\n  // Square output dimensions written to the encoded file. 400 = the larger of\n  // iOS (400) and Android (384), matching what other clients send.\n  width?: number;\n  height?: number;\n  videoBitsPerSecond?: number;\n  audioBitsPerSecond?: number;\n  frameRate?: number;\n  facingMode?: 'user' | 'environment';\n  videoDeviceId?: string;\n  audioDeviceId?: string;\n}\n\ntype State = 'inactive' | 'recording' | 'paused';\n\n// Codec preferences, ordered most → least preferred. mp4/h264 matches what\n// official clients send; webm is the universal fallback in browsers without\n// MP4 in MediaRecorder (older Chrome/Firefox).\nconst MIME_CANDIDATES = [\n  'video/mp4;codecs=avc1.42E01E,mp4a.40.2',\n  'video/mp4',\n  'video/webm;codecs=vp9,opus',\n  'video/webm;codecs=vp8,opus',\n  'video/webm'\n];\n\nfunction pickMimeType(): string | undefined {\n  if(typeof MediaRecorder === 'undefined') return undefined;\n  for(const mime of MIME_CANDIDATES) {\n    try {\n      if(MediaRecorder.isTypeSupported(mime)) return mime;\n    } catch(e) {}\n  }\n  // No candidate matched — return undefined (not '') so isNativeVideoRecorderSupported\n  // correctly reports unsupported on a UA with MediaRecorder but no usable codec.\n  return undefined;\n}\n\n// Streamable container for the paused-preview snapshot. Chrome's mp4\n// MediaRecorder emits a playable file ONLY at stop() (no mid-stream chunks), so\n// when the sent file is mp4 we run a SECOND, parallel recorder in webm — whose\n// timeslice chunks ARE independently decodable — purely to back the \"play what\n// you've recorded so far\" preview. Nothing here is sent.\nconst PREVIEW_MIME_CANDIDATES = [\n  'video/webm;codecs=vp9,opus',\n  'video/webm;codecs=vp8,opus',\n  'video/webm'\n];\n\nfunction pickPreviewMimeType(): string | undefined {\n  if(typeof MediaRecorder === 'undefined') return undefined;\n  for(const mime of PREVIEW_MIME_CANDIDATES) {\n    try {\n      if(MediaRecorder.isTypeSupported(mime)) return mime;\n    } catch(e) {}\n  }\n  return undefined;\n}\n\nexport function isNativeVideoRecorderSupported(): boolean {\n  if(typeof MediaRecorder === 'undefined') return false;\n  if(!navigator?.mediaDevices?.getUserMedia) return false;\n  if(typeof HTMLCanvasElement === 'undefined' || !HTMLCanvasElement.prototype.captureStream) return false;\n  // WebKit (Safari + all iOS browsers) exposes canvas.captureStream and an mp4\n  // MediaRecorder, but the canvas-captured video track is broken — invalid\n  // frames and a possible hang on stop() (WebKit bug #181663). Disable video\n  // notes there; getActiveRecordingMediaType() falls back to voice.\n  if(IS_SAFARI || IS_APPLE_MOBILE) return false;\n  return pickMimeType() !== undefined;\n}\n\nexport default class NativeVideoRecorder {\n  // Raw camera+mic stream — the chat input renders this in the preview circle\n  // and taps its audio for the waveform. NOT what gets recorded (see canvas).\n  public stream: MediaStream;\n  public state: State = 'inactive';\n  public mimeType: string;\n\n  public onstart: () => void = () => {};\n  public onstop: () => void = () => {};\n  public onpause: () => void = () => {};\n  public onresume: () => void = () => {};\n  public ondataavailable: (blob: Blob) => void = () => {};\n\n  private config: Required<Omit<NativeVideoRecorderConfig, 'videoDeviceId' | 'audioDeviceId' | 'facingMode'>> & {\n    videoDeviceId?: string;\n    audioDeviceId?: string;\n    facingMode: 'user' | 'environment';\n  };\n\n  private mediaRecorder: MediaRecorder;\n  private chunks: Blob[] = [];\n  // Guards emitResult() so the blob is sent once — onstop and the stop()-error\n  // fallback can otherwise both fire.\n  private finished = false;\n\n  // Parallel webm recorder backing the paused-preview snapshot (see\n  // PREVIEW_MIME_CANDIDATES). Only created when the sent container (mp4) can't\n  // produce mid-stream playable data; when the sent file is already a\n  // streamable webm we timeslice the main recorder and read its chunks instead.\n  private previewRecorder: MediaRecorder;\n  private previewChunks: Blob[] = [];\n  private previewMimeType: string;\n  private snapshotContainer: string; // container of getSnapshot()'s blobs\n\n  // Square-crop pipeline.\n  private drawVideo: HTMLVideoElement;     // plays `stream`, source for the canvas\n  private canvas: HTMLCanvasElement;       // width×height square, encoded as-is\n  private canvasCtx: CanvasRenderingContext2D;\n  private canvasStream: MediaStream;       // canvas.captureStream() — video only\n  private drawing = false;\n  // Holds the in-flight / active camera+mic acquire. dispose() (called from\n  // releaseStream()) stops its tracks even if getUserMedia resolves DURING the\n  // up-to-1.5s warm-up, after a cancel / ChatRecording.destroy() — getUserMedia\n  // can't be cancelled, so without this the camera LED would stay on forever.\n  // See acquireStream.\n  private acquisition: StreamAcquisition | undefined;\n\n  static isSupported = isNativeVideoRecorderSupported;\n\n  constructor(config: NativeVideoRecorderConfig = {}) {\n    this.config = {\n      width: config.width ?? 400,\n      height: config.height ?? 400,\n      videoBitsPerSecond: config.videoBitsPerSecond ?? 1_200_000,\n      audioBitsPerSecond: config.audioBitsPerSecond ?? 64_000,\n      frameRate: config.frameRate ?? 30,\n      facingMode: config.facingMode ?? 'user',\n      videoDeviceId: config.videoDeviceId,\n      audioDeviceId: config.audioDeviceId\n    };\n  }\n\n  // Choose the camera/microphone to record with (empty/undefined = OS default).\n  // The caller passes the user's picks from Settings → Speakers and Camera\n  // (appSettings.callDevices.cameraId/microphoneId), same source as calls.\n  // Applied on the next start().\n  public setDeviceIds(videoDeviceId?: string, audioDeviceId?: string) {\n    this.config.videoDeviceId = videoDeviceId || undefined;\n    this.config.audioDeviceId = audioDeviceId || undefined;\n  }\n\n  public async start(): Promise<void> {\n    if(this.state !== 'inactive') return;\n\n    // The recorder is reused across recordings — drop prior chunks and release\n    // a stream the caller may have left alive for the stop animation.\n    this.chunks = [];\n    this.previewChunks = [];\n    this.finished = false;\n    this.releaseStream();\n\n    // Source a bit larger than the square output so the centre-crop stays sharp\n    // (`ideal`, never `min` — a hard min paired with `deviceId:{exact}` becomes\n    // OverconstrainedError). Honour the camera/mic the caller selected (Settings\n    // → Speakers and Camera) via videoDeviceId/audioDeviceId.\n    const video: MediaTrackConstraints = {\n      width: {ideal: 720},\n      height: {ideal: 720},\n      frameRate: {ideal: this.config.frameRate}\n    };\n    if(this.config.videoDeviceId) {\n      video.deviceId = {exact: this.config.videoDeviceId};\n    } else {\n      video.facingMode = this.config.facingMode;\n    }\n\n    const audio: MediaTrackConstraints = {};\n    if(this.config.audioDeviceId) {\n      audio.deviceId = {exact: this.config.audioDeviceId};\n    }\n\n    // Reuse the call stack's getUserMedia chokepoint: if a selected device is\n    // gone it strips the deviceId, clears the stale appSettings.callDevices.*\n    // entry and retries on the OS default — round notes get the exact same\n    // self-healing device fallback as calls.\n    const acquisition = this.acquisition = acquireStream({video, audio: Object.keys(audio).length ? audio : true});\n    const stream = await acquisition.promise;\n    // Released (cancel / ChatRecording.destroy()) while getUserMedia was\n    // resolving — dispose() already stopped the orphaned stream; bail so the\n    // camera doesn't go live with no owner.\n    if(!stream) return;\n    this.stream = stream;\n\n    // Off-DOM <video> that decodes the raw camera feed for the canvas.\n    this.drawVideo = document.createElement('video');\n    this.drawVideo.muted = true;\n    this.drawVideo.playsInline = true;\n    this.drawVideo.srcObject = this.stream;\n\n    this.canvas = document.createElement('canvas');\n    this.canvas.width = this.config.width;\n    this.canvas.height = this.config.height;\n    this.canvasCtx = this.canvas.getContext('2d', {willReadFrequently: true}) as CanvasRenderingContext2D;\n\n    await this.drawVideo.play().catch(() => {});\n\n    // Don't begin recording on the camera's black warm-up frames — wait until\n    // it outputs a visible (non-black) frame, so the clip doesn't start black.\n    await this.waitForVisibleFrame();\n    if(!this.stream) return; // released (cancel/destroy) while we waited\n\n    // Prime the canvas with the first real frame, then keep it fed.\n    this.drawCroppedFrame();\n    this.startDrawLoop();\n\n    this.mimeType = pickMimeType();\n    try {\n      this.canvasStream = this.canvas.captureStream(this.config.frameRate);\n      const videoTrack = this.canvasStream.getVideoTracks()[0];\n      if(!videoTrack || videoTrack.readyState !== 'live') {\n        // e.g. a broken canvas.captureStream — bail rather than record a black/empty clip.\n        throw new Error('canvas.captureStream produced no live video track');\n      }\n      const recordStream = new MediaStream([\n        videoTrack,\n        ...this.stream.getAudioTracks()\n      ]);\n\n      const options: MediaRecorderOptions = {\n        videoBitsPerSecond: this.config.videoBitsPerSecond,\n        audioBitsPerSecond: this.config.audioBitsPerSecond\n      };\n      if(this.mimeType) options.mimeType = this.mimeType;\n\n      this.mediaRecorder = new MediaRecorder(recordStream, options);\n      // Prefer the container WE requested (and verified) over the recorder's\n      // possibly-empty reported mimeType; drop `;codecs=…` so appMessagesManager's\n      // exact-string VIDEO_MIME_TYPES_SUPPORTED lookup matches.\n      const fullMime = this.mimeType || this.mediaRecorder.mimeType || 'video/webm';\n      this.mimeType = fullMime.split(';')[0].trim();\n\n      this.mediaRecorder.ondataavailable = (e) => {\n        if(e.data && e.data.size > 0) this.chunks.push(e.data);\n      };\n      // The stream is intentionally NOT released in emitResult — the caller keeps\n      // the preview alive through the fade-out and calls releaseStream() after.\n      this.mediaRecorder.onstop = () => this.emitResult();\n\n      // Paused-preview snapshot source. If the sent container is already a\n      // streamable webm, timeslice the main recorder and read its own chunks.\n      // Otherwise (mp4 — no mid-stream data) spin up a parallel webm recorder on\n      // the same stream whose timeslice chunks are independently playable.\n      const mainIsStreamable = this.mimeType.startsWith('video/webm');\n      if(mainIsStreamable) {\n        this.snapshotContainer = this.mimeType;\n      } else {\n        this.previewMimeType = pickPreviewMimeType();\n        if(this.previewMimeType) {\n          this.previewRecorder = new MediaRecorder(recordStream, {\n            mimeType: this.previewMimeType,\n            videoBitsPerSecond: this.config.videoBitsPerSecond,\n            audioBitsPerSecond: this.config.audioBitsPerSecond\n          });\n          this.snapshotContainer = (this.previewRecorder.mimeType || this.previewMimeType).split(';')[0].trim();\n          this.previewRecorder.ondataavailable = (e) => {\n            if(e.data && e.data.size > 0) this.previewChunks.push(e.data);\n          };\n        }\n      }\n\n      // mp4: one final chunk at stop() (no timeslice). Streamable webm: periodic\n      // chunks so getSnapshot() has playable data mid-recording.\n      this.mediaRecorder.start(mainIsStreamable ? 250 : undefined);\n      this.previewRecorder?.start(250);\n    } catch(err) {\n      this.releaseStream(); // tear down the half-initialised pipeline + camera\n      throw err;\n    }\n\n    this.state = 'recording';\n    this.onstart();\n  }\n\n  // Centre-crop the camera feed to a square and scale it into the output canvas.\n  private drawCroppedFrame() {\n    const v = this.drawVideo;\n    const ctx = this.canvasCtx;\n    if(!v || !ctx) return;\n    const vw = v.videoWidth, vh = v.videoHeight;\n    if(!vw || !vh) return;\n    const side = Math.min(vw, vh);\n    const sx = (vw - side) / 2;\n    const sy = (vh - side) / 2;\n    ctx.drawImage(v, sx, sy, side, side, 0, 0, this.config.width, this.config.height);\n  }\n\n  private startDrawLoop() {\n    if(this.drawing) return;\n    this.drawing = true;\n    // Drive draws with requestAnimationFrame, NOT requestVideoFrameCallback:\n    // rVFC only fires while the source <video> is actually being rendered, and\n    // ours is off-DOM (never appended) — and the tab may be unfocused — so rVFC\n    // can stay silent forever, freezing the canvas and yielding a ~1-frame clip.\n    // rAF keeps ticking regardless.\n    //\n    // Throttle to the capture frame rate: rAF fires at the display rate (~60fps)\n    // but canvas.captureStream(frameRate) only samples at config.frameRate (30),\n    // so drawing every tick just burns CPU on a redundant 720→400 drawImage and\n    // steals main-thread time from the encoder / live preview / waveform — which\n    // can drop the *captured* rate under load. Drawing at the capture rate keeps\n    // output fps identical while ~halving the crop work; under heavy load the\n    // gate is a no-op (ticks already arrive slower than the interval).\n    const minIntervalMs = 1000 / this.config.frameRate;\n    let lastDraw = 0;\n    const tick = (now: number) => {\n      if(!this.drawing) return;\n      if(now - lastDraw >= minIntervalMs - 1) {\n        lastDraw = now;\n        this.drawCroppedFrame();\n      }\n      requestAnimationFrame(tick);\n    };\n    requestAnimationFrame(tick);\n  }\n\n  // Resolves once the camera produces a non-black frame (or after a safety\n  // timeout / a few frames in a genuinely dark room). Samples the centre-crop\n  // canvas so the very first recorded frame is the visible one.\n  private waitForVisibleFrame(): Promise<void> {\n    return new Promise((resolve) => {\n      const v = this.drawVideo;\n      if(!v || !this.canvasCtx) {\n        resolve();\n        return;\n      }\n\n      let done = false;\n      let frames = 0;\n      const finish = () => {\n        if(done) return;\n        done = true;\n        clearTimeout(safety);\n        resolve();\n      };\n      const safety = setTimeout(finish, 1500);\n\n      // rAF, not rVFC — see startDrawLoop: rVFC never fires for our off-DOM /\n      // unfocused video, which would stall first-frame detection until the\n      // safety timeout and then start recording on a frozen canvas.\n      const schedule = () => requestAnimationFrame(check);\n\n      const check = () => {\n        if(done || !this.stream) {\n          finish();\n          return;\n        }\n        frames++;\n        let bright = false;\n        try {\n          this.drawCroppedFrame();\n          const sw = Math.min(16, this.canvas.width);\n          const data = this.canvasCtx.getImageData(0, 0, sw, sw).data;\n          let sum = 0;\n          for(let i = 0; i < data.length; i += 4) sum += data[i] + data[i + 1] + data[i + 2];\n          bright = sum / (sw * sw * 3) > 10; // 0..255 avg luminance\n        } catch(e) {\n          bright = true; // can't sample — don't block recording\n        }\n        // Give up after ~25 frames so a genuinely dark scene still records.\n        if(bright || frames >= 25) finish();\n        else schedule();\n      };\n\n      schedule();\n    });\n  }\n\n  public async pause(): Promise<void> {\n    if(this.state !== 'recording' || !this.mediaRecorder) return;\n    // Flush a pending chunk on whichever recorder backs getSnapshot() so the\n    // paused preview includes everything captured so far.\n    const snapshotRecorder = this.previewRecorder || this.mediaRecorder;\n    try {\n      snapshotRecorder.requestData?.();\n    } catch(e) {}\n    try {\n      this.previewRecorder?.pause();\n    } catch(e) {}\n    this.mediaRecorder.pause();\n    // Stop feeding the canvas while paused — no recorder is consuming it, so the\n    // rAF crop loop would just burn CPU/GPU for the whole (possibly long) pause.\n    this.drawing = false;\n    this.state = 'paused';\n    this.onpause();\n  }\n\n  public resume(): void {\n    if(this.state !== 'paused' || !this.mediaRecorder) return;\n    // Refresh the canvas and restart the crop loop before the recorders resume,\n    // so they don't capture a stale frozen frame.\n    this.drawCroppedFrame();\n    this.startDrawLoop();\n    try {\n      this.previewRecorder?.resume();\n    } catch(e) {}\n    this.mediaRecorder.resume();\n    this.state = 'recording';\n    this.onresume();\n  }\n\n  // A playable Blob of everything captured so far — for the paused preview.\n  // Sourced from the streamable (webm) chunks; mp4's own chunks aren't\n  // mid-stream playable. Undefined when no streamable source exists (e.g.\n  // mp4-only browsers) — the caller then just shows the frozen last frame.\n  public getSnapshot(): Blob | undefined {\n    const chunks = this.previewRecorder ? this.previewChunks : this.chunks;\n    if(!chunks.length || !this.snapshotContainer) return undefined;\n    return new Blob(chunks, {type: this.snapshotContainer});\n  }\n\n  public stop(): void {\n    if(this.state === 'inactive' || !this.mediaRecorder) return;\n    this.state = 'inactive';\n    try {\n      this.previewRecorder?.stop();\n    } catch(e) {}\n    try {\n      this.mediaRecorder.stop(); // → onstop → emitResult()\n    } catch(e) {\n      this.emitResult(); // stop() threw and onstop won't fire — emit directly\n    }\n  }\n\n  // Emit the recorded blob + fire onstop exactly once, whether triggered by the\n  // recorder's onstop or the stop()-error fallback. The camera stream is NOT\n  // released here — the caller fades the preview out and calls releaseStream().\n  private emitResult() {\n    if(this.finished) return;\n    this.finished = true;\n    const blob = new Blob(this.chunks, {type: this.mimeType});\n    this.ondataavailable(blob);\n    this.onstop();\n  }\n\n  // Stop the camera/mic + canvas pipeline. Public so the caller can keep the\n  // preview visible during the stop animation and release afterwards.\n  // Idempotent.\n  public releaseStream() {\n    this.drawing = false;\n    // Stops the camera+mic stream — including one still awaiting getUserMedia\n    // (see start()), which dispose() stops the instant it resolves.\n    this.acquisition?.dispose();\n    this.acquisition = undefined;\n\n    if(this.previewRecorder) {\n      try {\n        if(this.previewRecorder.state !== 'inactive') this.previewRecorder.stop();\n      } catch(e) {}\n      this.previewRecorder.ondataavailable = null;\n      this.previewRecorder = undefined;\n    }\n    this.previewChunks = [];\n\n    if(this.mediaRecorder) {\n      try {\n        if(this.mediaRecorder.state !== 'inactive') this.mediaRecorder.stop();\n      } catch(e) {}\n      this.mediaRecorder.ondataavailable = null;\n      this.mediaRecorder.onstop = null;\n      this.mediaRecorder = undefined;\n    }\n    // Free the recorded blob array (can be several MB) instead of holding it\n    // until the next start(). The sent Blob was already built in emitResult().\n    this.chunks = [];\n\n    if(this.canvasStream) {\n      this.canvasStream.getTracks().forEach((t) => {\n        try {\n          t.stop();\n        } catch(e) {}\n      });\n      this.canvasStream = undefined;\n    }\n\n    if(this.drawVideo) {\n      try {\n        this.drawVideo.pause();\n      } catch(e) {}\n      this.drawVideo.srcObject = null;\n      this.drawVideo = undefined;\n    }\n    this.canvas = undefined;\n    this.canvasCtx = undefined;\n\n    // `this.stream` is the acquisition's stream; dispose() above stopped its\n    // tracks.\n    this.stream = undefined;\n  }\n}\n","// Canvas renderer for the in-input voice recording waveform.\n//   * During recording: bars push in from the right and scroll left once the\n//     visible window fills. Each bar is one normalized peak.\n//   * During pause/playback: peaks are frozen and a vertical playhead overlay\n//     splits \"played\" (dim) from \"remaining\" (bright) bars.\n\nconst BAR_WIDTH = 3;\nconst BAR_GAP = 3;\nconst BAR_RADIUS = 1.5;\nconst MIN_BAR_HEIGHT = 3;\n\nexport interface LiveWaveformOptions {\n  height?: number;\n  width?: number;\n  // CSS custom property names to read colors from the canvas element. Falls back\n  // to the resolved `color` if the var is empty.\n  activeColorVar?: string;\n  inactiveColorVar?: string;\n}\n\nexport default class LiveWaveform {\n  public element: HTMLCanvasElement;\n  private ctx: CanvasRenderingContext2D;\n  private peaks: number[] = [];\n  // Lifetime peak — used as the normalization reference. Speech of the same\n  // loudness renders at the same height because the reference doesn't shrink\n  // between syllables. A new louder peak rescales the reference upward; old\n  // bars already rendered keep their drawn height (we don't repaint them).\n  private maxPeak = 0.05;\n  private capacity = 0;\n  private cssWidth = 0;\n  private cssHeight = 0;\n  private dpr = 1;\n  private progress: number | undefined;\n  private activeColorVar: string;\n  private inactiveColorVar: string;\n  private rafScheduled = false;\n  private resizeObserver?: ResizeObserver;\n  // Called when the user clicks on the waveform. Argument is a 0..1 position\n  // along the bars (left edge = 0, right edge = 1). Only invoked while\n  // setSeekable(true) has been called — by convention the panel only enables\n  // seeking during playback.\n  public onSeek?: (progress: number) => void;\n  private seekable = false;\n\n  constructor(opts: LiveWaveformOptions = {}) {\n    this.element = document.createElement('canvas');\n    this.element.classList.add('voice-recording-waveform');\n    this.ctx = this.element.getContext('2d');\n    this.activeColorVar = opts.activeColorVar || '--primary-color';\n    this.inactiveColorVar = opts.inactiveColorVar || '--secondary-color';\n\n    this.cssHeight = opts.height ?? 36;\n    if(opts.width) this.cssWidth = opts.width;\n\n    this.resizeObserver = new ResizeObserver(() => {\n      this.measureAndResize();\n      this.draw();\n    });\n    this.resizeObserver.observe(this.element);\n\n    this.element.addEventListener('click', this.onClick);\n  }\n\n  private onClick = (e: MouseEvent) => {\n    if(!this.seekable || !this.onSeek) return;\n    const rect = this.element.getBoundingClientRect();\n    if(rect.width <= 0) return;\n    const x = e.clientX - rect.left;\n    const progress = Math.max(0, Math.min(1, x / rect.width));\n    this.onSeek(progress);\n  };\n\n  public setSeekable(seekable: boolean) {\n    this.seekable = seekable;\n    this.element.style.cursor = seekable ? 'pointer' : '';\n  }\n\n  private measureAndResize() {\n    const rect = this.element.getBoundingClientRect();\n    if(rect.width <= 0) return;\n\n    this.cssWidth = rect.width;\n    this.cssHeight = rect.height;\n    this.dpr = window.devicePixelRatio || 1;\n    this.element.width = Math.round(this.cssWidth * this.dpr);\n    this.element.height = Math.round(this.cssHeight * this.dpr);\n    this.capacity = Math.max(1, Math.floor((this.cssWidth + BAR_GAP) / (BAR_WIDTH + BAR_GAP)));\n\n    // Trim oldest peaks if window shrinks below current buffer.\n    if(this.peaks.length > this.capacity) {\n      this.peaks.splice(0, this.peaks.length - this.capacity);\n    }\n  }\n\n  public pushPeak(value: number) {\n    if(value > this.maxPeak) this.maxPeak = value;\n    const denom = Math.max(this.maxPeak, 0.02);\n    const normalized = Math.min(1, value / denom);\n    this.peaks.push(normalized);\n    if(this.peaks.length > this.capacity) {\n      this.peaks.splice(0, this.peaks.length - this.capacity);\n    }\n    this.scheduleDraw();\n  }\n\n  // Replace the entire peak buffer (used when computing the full waveform from\n  // recorded audio for the pause/playback view).\n  public setPeaks(peaks: ArrayLike<number>) {\n    const fitted: number[] = [];\n    if(this.capacity <= 0) this.measureAndResize();\n    const cap = this.capacity || 1;\n    if(peaks.length <= cap) {\n      for(let i = 0; i < peaks.length; ++i) fitted.push(peaks[i]);\n    } else {\n      const ratio = peaks.length / cap;\n      for(let i = 0; i < cap; ++i) {\n        const start = Math.floor(i * ratio);\n        const end = Math.floor((i + 1) * ratio);\n        let peak = 0;\n        for(let j = start; j < end && j < peaks.length; ++j) {\n          if(peaks[j] > peak) peak = peaks[j];\n        }\n        fitted.push(peak);\n      }\n    }\n    let max = 0.001;\n    for(let i = 0; i < fitted.length; ++i) if(fitted[i] > max) max = fitted[i];\n    for(let i = 0; i < fitted.length; ++i) fitted[i] = Math.min(1, fitted[i] / max);\n\n    this.peaks = fitted;\n    this.scheduleDraw();\n  }\n\n  public setProgress(progress: number | undefined) {\n    this.progress = progress;\n    this.scheduleDraw();\n  }\n\n  public clear() {\n    this.peaks = [];\n    this.maxPeak = 0.05;\n    this.progress = undefined;\n    this.scheduleDraw();\n  }\n\n  private scheduleDraw() {\n    if(this.rafScheduled) return;\n    this.rafScheduled = true;\n    requestAnimationFrame(() => {\n      this.rafScheduled = false;\n      this.draw();\n    });\n  }\n\n  private draw() {\n    if(!this.cssWidth) this.measureAndResize();\n    const w = this.cssWidth;\n    const h = this.cssHeight;\n    if(!w || !h) return;\n    const ctx = this.ctx;\n    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);\n    ctx.clearRect(0, 0, w, h);\n\n    if(!this.peaks.length) return;\n\n    const stride = BAR_WIDTH + BAR_GAP;\n    const totalWidth = this.peaks.length * stride - BAR_GAP;\n    // Align bars to the right edge so live recording grows from the right.\n    const startX = Math.max(0, w - totalWidth);\n    const midY = h / 2;\n\n    const computed = getComputedStyle(this.element);\n    const activeColor = computed.getPropertyValue(this.activeColorVar).trim() || computed.color;\n    ctx.fillStyle = activeColor;\n\n    // Progress overlay is only used during playback. Without progress every\n    // bar is primary (recording / paused-preview look). With progress set,\n    // bars left of the playhead stay primary and bars to the right fade to\n    // 30% (matches how the standard voice-message bubble draws unplayed bars).\n    const hasProgress = this.progress != null;\n    const progressPx = hasProgress ?\n      startX + Math.max(0, Math.min(1, this.progress)) * totalWidth :\n      Infinity;\n\n    for(let i = 0; i < this.peaks.length; ++i) {\n      const x = startX + i * stride;\n      if(x + BAR_WIDTH < 0) continue;\n      const peak = this.peaks[i];\n      const barH = Math.max(MIN_BAR_HEIGHT, Math.min(h, peak * h));\n      const y = midY - barH / 2;\n\n      ctx.globalAlpha = !hasProgress || x + BAR_WIDTH / 2 <= progressPx ? 1 : 0.3;\n\n      if((ctx as any).roundRect) {\n        ctx.beginPath();\n        (ctx as any).roundRect(x, y, BAR_WIDTH, barH, BAR_RADIUS);\n        ctx.fill();\n      } else {\n        ctx.fillRect(x, y, BAR_WIDTH, barH);\n      }\n    }\n\n    ctx.globalAlpha = 1;\n  }\n\n  public destroy() {\n    this.resizeObserver?.disconnect();\n    this.resizeObserver = undefined;\n    this.element.removeEventListener('click', this.onClick);\n    this.peaks = [];\n  }\n}\n","// Self-contained recording UI overlay shown in the chat input while the user\n// is recording (or has paused) a voice message. The whole subtree lives inside\n// one absolutely-positioned container so the chat input can fade or slide it\n// in/out atomically.\n//\n// Layout while recording:\n//   [trash] [● red dot] [waveform .....................] [timer] [pause]\n// Layout while paused / playing back:\n//   [trash] [play/pause] [waveform .....................] [timer] [microphone]\n//\n// External wiring:\n//   * pushPeak()           — call for every live amplitude during recording.\n//   * setPeaks()           — replace buffer with the full recording (used for\n//                            the static playback view once paused).\n//   * setTimer()           — update the timer text (MM:SS,CS).\n//   * setMode()            — switch between recording / paused (+ playing).\n//   * setPlaybackProgress  — drives the playhead overlay during playback.\n//   * onCancel             — discard recording.\n//   * onPauseToggle        — pause while recording / resume recording while paused.\n//   * onPlayToggle         — playback / pause playback (paused mode only).\n\nimport Icon from '@components/icon';\nimport Button from '@components/button';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport LiveWaveform from './liveWaveform';\n\nexport interface VoiceRecordingPanelOptions {\n  onCancel: () => void;\n  onPauseToggle: () => void;\n  onPlayToggle: () => void;\n  onSeek: (progress: number) => void;\n}\n\nexport type VoiceRecordingMode = 'recording' | 'paused';\n\nexport default class VoiceRecordingPanel {\n  public element: HTMLDivElement;\n  public waveform: LiveWaveform;\n\n  private btnCancel: HTMLButtonElement;\n  // Pill container that holds the lead + waveform on a tinted background.\n  private pillEl: HTMLDivElement;\n  // Left-of-waveform slot — red dot while recording, play/pause while paused.\n  private leadEl: HTMLDivElement;\n  private dotEl: HTMLDivElement;\n  private btnPlayToggle: HTMLButtonElement;\n  private playPlayIcon: HTMLElement;\n  private playPauseIcon: HTMLElement;\n  // Right-of-timer slot — pause while recording, microphone while paused.\n  private btnPauseToggle: HTMLButtonElement;\n  private pauseIconRecord: HTMLElement;\n  private pauseIconMic: HTMLElement;\n\n  private timerEl: HTMLSpanElement;\n  private listenerSetter = new ListenerSetter();\n  private mode: VoiceRecordingMode = 'recording';\n  private isPlaying = false;\n\n  constructor(opts: VoiceRecordingPanelOptions) {\n    this.element = document.createElement('div');\n    this.element.classList.add('voice-recording-panel');\n\n    this.btnCancel = Button('btn-icon voice-recording-cancel danger');\n    this.btnCancel.append(Icon('delete', 'voice-recording-cancel-icon'));\n\n    this.leadEl = document.createElement('div');\n    this.leadEl.classList.add('voice-recording-lead');\n\n    this.dotEl = document.createElement('div');\n    this.dotEl.classList.add('voice-recording-dot');\n\n    this.btnPlayToggle = Button('btn-icon voice-recording-play');\n    this.playPlayIcon = Icon('play_filled', 'voice-recording-play-icon', 'voice-recording-play-icon--play');\n    this.playPauseIcon = Icon('pause_filled', 'voice-recording-play-icon', 'voice-recording-play-icon--pause');\n    this.btnPlayToggle.append(this.playPlayIcon, this.playPauseIcon);\n\n    this.leadEl.append(this.dotEl, this.btnPlayToggle);\n\n    this.waveform = new LiveWaveform();\n\n    this.timerEl = document.createElement('span');\n    this.timerEl.classList.add('voice-recording-timer');\n    this.timerEl.textContent = '0:00,0';\n\n    this.btnPauseToggle = Button('btn-icon voice-recording-pause-toggle');\n    this.pauseIconRecord = Icon('pause_filled', 'voice-recording-pause-icon', 'voice-recording-pause-icon--pause');\n    this.pauseIconMic = Icon('microphone', 'voice-recording-pause-icon', 'voice-recording-pause-icon--mic');\n    this.btnPauseToggle.append(this.pauseIconRecord, this.pauseIconMic);\n\n    this.pillEl = document.createElement('div');\n    this.pillEl.classList.add('voice-recording-pill');\n    this.pillEl.append(this.leadEl, this.waveform.element, this.timerEl);\n\n    this.element.append(\n      this.btnCancel,\n      this.pillEl,\n      this.btnPauseToggle\n    );\n\n    attachClickEvent(this.btnCancel, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onCancel();\n    }, {listenerSetter: this.listenerSetter});\n\n    attachClickEvent(this.btnPauseToggle, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onPauseToggle();\n    }, {listenerSetter: this.listenerSetter});\n\n    attachClickEvent(this.btnPlayToggle, (e) => {\n      e?.preventDefault?.();\n      e?.stopPropagation?.();\n      opts.onPlayToggle();\n    }, {listenerSetter: this.listenerSetter});\n\n    this.waveform.onSeek = (progress) => opts.onSeek(progress);\n\n    this.setMode('recording');\n  }\n\n  public setMode(mode: VoiceRecordingMode) {\n    this.mode = mode;\n    this.element.classList.toggle('voice-recording-panel--paused', mode === 'paused');\n    this.element.classList.toggle('voice-recording-panel--recording', mode === 'recording');\n    if(mode === 'recording') {\n      this.setPlaying(false);\n      this.waveform.setProgress(undefined);\n    }\n  }\n\n  public getMode(): VoiceRecordingMode {\n    return this.mode;\n  }\n\n  public setPlaying(isPlaying: boolean) {\n    this.isPlaying = isPlaying;\n    this.element.classList.toggle('voice-recording-panel--playing', isPlaying);\n  }\n\n  public setSeekable(seekable: boolean) {\n    this.waveform.setSeekable(seekable);\n  }\n\n  public getIsPlaying() {\n    return this.isPlaying;\n  }\n\n  public setPlaybackProgress(progress: number | undefined) {\n    this.waveform.setProgress(progress);\n  }\n\n  public setTimer(text: string) {\n    if(this.timerEl.textContent !== text) this.timerEl.textContent = text;\n  }\n\n  public pushPeak(value: number) {\n    this.waveform.pushPeak(value);\n  }\n\n  public setPeaks(peaks: ArrayLike<number>) {\n    this.waveform.setPeaks(peaks);\n  }\n\n  public clearPeaks() {\n    this.waveform.clear();\n  }\n\n  public destroy() {\n    this.listenerSetter.removeAll();\n    this.waveform.destroy();\n    this.element.remove();\n  }\n}\n","// Just the visual for a round video note while recording: a 360x360 circular\n// camera preview centered on screen with a drop shadow (no dimming layer) and\n// the same SVG progress ring incoming round videos use (the shared ProgressRing\n// component, @components/progressRing).\n//\n// All recording *controls* (trash / waveform / timer / pause / preview / send)\n// are the regular VoiceRecordingPanel + send button that live in the chat input\n// — this owns none of them. ChatRecording drives the voice panel for video\n// exactly as for audio; this overlay is purely the кружок.\n//\n// Authored in Solid: reactive signals (mode / playing / progress) back the JSX,\n// and createVideoRecordingPanel() exposes the same imperative handle ChatRecording\n// drives (mirrors createProgressRing in progressRing.tsx).\n\nimport {Accessor, createRoot, createSignal, JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport ProgressRing from '@components/progressRing';\n\nconst STAGE_SIZE = 360;\n\nexport type VideoRecordingMode = 'recording' | 'paused';\n\nexport default function VideoRecordingPanel(props: {\n  mode: Accessor<VideoRecordingMode | undefined>,\n  playing: Accessor<boolean>,\n  progress: Accessor<number>,\n  // Refs fire synchronously while the body runs — that's how the handle below\n  // gets the real DOM nodes (calling the component returns the HMR wrapper, not\n  // the <div>). rootRef = the stage element to mount; ref = the preview <video>.\n  rootRef: (stage: HTMLDivElement) => void,\n  ref: (video: HTMLVideoElement) => void\n}): JSX.Element {\n  return (\n    <div\n      ref={props.rootRef}\n      class={classNames(\n        'video-recording-stage',\n        props.mode() === 'recording' && 'video-recording-stage--recording',\n        props.mode() === 'paused' && 'video-recording-stage--paused',\n        props.playing() && 'video-recording-stage--playing'\n      )}\n    >\n      <div\n        class=\"video-recording-circle\"\n        style={{width: STAGE_SIZE + 'px', height: STAGE_SIZE + 'px'}}\n      >\n        <video\n          class=\"video-recording-preview\"\n          ref={(el) => {\n            el.muted = true;\n            el.autoplay = true;\n            el.playsInline = true;\n            props.ref(el);\n          }}\n        />\n        <ProgressRing\n          size={STAGE_SIZE}\n          strokeOpacity={0.9}\n          class=\"video-recording-progress-ring\"\n          progress={props.progress()}\n        />\n      </div>\n    </div>\n  );\n}\n\nexport interface VideoRecordingPanelHandle {\n  element: HTMLDivElement;\n  readonly previewVideo: HTMLVideoElement;\n  setMode(mode: VideoRecordingMode): void;\n  getMode(): VideoRecordingMode | undefined;\n  startLivePreview(stream: MediaStream): void;\n  reset(): void;\n  setPlaying(isPlaying: boolean): void;\n  getIsPlaying(): boolean;\n  setProgress(progress: number): void;\n  destroy(): void;\n}\n\n// Imperative handle for the (non-Solid) ChatRecording controller. Owns its own\n// reactive root; destroy() disposes it.\nexport function createVideoRecordingPanel(): VideoRecordingPanelHandle {\n  return createRoot((dispose) => {\n    const [mode, setModeSignal] = createSignal<VideoRecordingMode | undefined>(undefined);\n    const [playing, setPlayingSignal] = createSignal(false);\n    const [progress, setProgressSignal] = createSignal(0);\n\n    let element: HTMLDivElement;\n    let previewVideo: HTMLVideoElement;\n    // Bumped on each startLivePreview()/reset() so a pending \"reveal on first\n    // frame\" callback from a superseded session is ignored.\n    let liveToken = 0;\n    let clearVideoTimer: number;\n\n    // Capture the real DOM nodes via refs (set synchronously while the body\n    // runs); the component's return value is the HMR wrapper, not the <div>.\n    VideoRecordingPanel({\n      mode,\n      playing,\n      progress,\n      rootRef: (stage) => element = stage,\n      ref: (video) => previewVideo = video\n    });\n\n    const setMode = (m: VideoRecordingMode) => {\n      // A fresh recording/preview is about to show — cancel any pending\n      // fade-out cleanup.\n      if(clearVideoTimer) {\n        clearTimeout(clearVideoTimer);\n        clearVideoTimer = undefined;\n      }\n      setModeSignal(m);\n      if(m === 'recording') setPlayingSignal(false);\n    };\n\n    const releasePreview = () => {\n      previewVideo.srcObject = null;\n      if(previewVideo.src) {\n        previewVideo.removeAttribute('src');\n        try {\n          previewVideo.load();\n        } catch(e) {}\n      }\n    };\n\n    // Attach the live camera stream and reveal the circle only once the first\n    // frame is actually painted — revealing immediately fades in a black circle\n    // while the camera spins up. Cancelled if reset() runs first.\n    const startLivePreview = (stream: MediaStream) => {\n      const token = ++liveToken;\n      previewVideo.srcObject = stream;\n      previewVideo.muted = true;\n      previewVideo.play().catch(() => {});\n\n      let safety: number;\n      const reveal = () => {\n        if(safety) {\n          clearTimeout(safety); // don't let the safety net fire after a real reveal\n          safety = undefined;\n        }\n        if(liveToken !== token) return; // a newer call / reset superseded us\n        setMode('recording');\n      };\n\n      const rvfc = previewVideo as HTMLVideoElement & {requestVideoFrameCallback?: (cb: () => void) => number};\n      if(typeof rvfc.requestVideoFrameCallback === 'function') {\n        rvfc.requestVideoFrameCallback(() => reveal());\n      } else {\n        previewVideo.addEventListener('loadeddata', reveal, {once: true});\n      }\n      // Safety net: reveal anyway if the frame callback never fires.\n      safety = window.setTimeout(reveal, 800);\n    };\n\n    // Hide the circle and release the preview. We DON'T clear the camera source\n    // immediately: dropping the mode class fades the stage out over its opacity\n    // transition while the last camera frame stays painted, so the brief\n    // camera-off black frame never shows. The source is released after the fade.\n    const reset = () => {\n      ++liveToken; // cancel any pending reveal-on-first-frame\n      setModeSignal(undefined);\n      setPlayingSignal(false);\n      setProgressSignal(0);\n\n      if(clearVideoTimer) clearTimeout(clearVideoTimer);\n      clearVideoTimer = window.setTimeout(() => {\n        clearVideoTimer = undefined;\n        releasePreview();\n      }, 250); // matches the .video-recording-stage opacity transition (.2s) + margin\n    };\n\n    return {\n      element,\n      get previewVideo() {\n        return previewVideo;\n      },\n      setMode,\n      getMode: () => mode(),\n      startLivePreview,\n      reset,\n      setPlaying: (isPlaying: boolean) => setPlayingSignal(isPlaying),\n      getIsPlaying: () => playing(),\n      setProgress: (value: number) => setProgressSignal(value),\n      destroy: () => {\n        if(clearVideoTimer) clearTimeout(clearVideoTimer);\n        releasePreview();\n        element.remove();\n        dispose();\n      }\n    };\n  });\n}\n","import ctx from '@environment/ctx';\nimport noop from '@helpers/noop';\n\n// It's better to use timeout instead of interval, because interval can be corrupted\nexport default function eachTimeout(callback: () => any, getNextTimeout: () => number, runFirst = true) {\n  const cancel = () => {\n    clearTimeout(timeout);\n  };\n\n  // replace callback to run noop and restore after\n  const _callback = callback;\n  if(!runFirst) {\n    callback = noop;\n  }\n\n  let timeout: number;\n  (function run() {\n    callback();\n    timeout = ctx.setTimeout(run, Math.max(0, getNextTimeout()));\n  })();\n\n  callback = _callback;\n\n  return cancel;\n}\n","import eachTimeout from '@helpers/eachTimeout';\n\n// It's better to use timeout instead of interval, because interval can be corrupted\nexport default function eachSecond(callback: () => any, runFirst?: boolean) {\n  return eachTimeout(callback, () => 1000 - new Date().getMilliseconds(), runFirst);\n}\n","import {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\n\nexport interface AnimatedSuperOptions {\n  duration?: number;\n}\n\nexport class AnimatedSuper {\n  static BASE_CLASS = 'animated-super';\n  static DEFAULT_DURATION = 200;\n  container: HTMLDivElement;\n  rows: {[index: string]: {element: HTMLElement, middleware: MiddlewareHelper, timeout?: number, new?: true}} = {};\n  clearTimeout: number;\n\n  duration: AnimatedSuperOptions['duration'];\n  constructor(options?: AnimatedSuperOptions) {\n    this.duration = options?.duration ?? AnimatedSuper.DEFAULT_DURATION;\n    this.container = document.createElement('div');\n    this.container.className = AnimatedSuper.BASE_CLASS;\n  }\n\n  public getRow(index: number, animateFirst = false) {\n    if(this.rows[index]) return this.rows[index].element;\n    const row = document.createElement('div');\n    const isFirst = !Object.keys(this.rows).length && !animateFirst;\n    row.className = AnimatedSuper.BASE_CLASS + '-row' + (isFirst ? '' : ' is-hiding hide');\n    this.rows[index] = {element: row, middleware: row.middlewareHelper = getMiddleware(), new: true};\n    this.container.append(row);\n    return row;\n  }\n\n  public clearRow(index: number) {\n    if(!this.rows[index]) return;\n    this.rows[index].element.remove();\n    this.rows[index].middleware.destroy();\n    delete this.rows[index];\n  }\n\n  public clearRows(currentIndex?: number) {\n    if(this.clearTimeout) clearTimeout(this.clearTimeout);\n    this.clearTimeout = window.setTimeout(() => {\n      for(const i in this.rows) {\n        if(+i === currentIndex) continue;\n        this.clearRow(+i);\n      }\n    }, this.duration);\n  }\n\n  public setNewRow(index: number, reflow = false) {\n    const row = this.rows[index];\n    if(row.new) {\n      if(reflow) {\n        row.element.classList.remove('hide');\n        void row.element.offsetLeft; // reflow\n      } else {\n        row.element.classList.remove('is-hiding', 'hide');\n      }\n\n      delete row.new;\n    }\n\n    this.clearRows(index);\n  }\n\n  public animate(index: number, previousIndex: number, fromTop = index > previousIndex, ignorePrevious = false) {\n    if(index === previousIndex) { // * handle if set index 0 and previousIndex 0\n      return this.setNewRow(index);\n    }\n\n    const row = this.rows[index];\n    const previousRow = this.rows[previousIndex];\n    if(!previousRow && !ignorePrevious) {\n      return this.setNewRow(index);\n    }\n\n    const sides = ['from-top', 'from-bottom'];\n    if(!fromTop) sides.reverse();\n\n    row.element.classList.add(sides[0]);\n    row.element.classList.remove(sides[1]);\n    if(previousRow) {\n      previousRow.element.classList.add(sides[1]);\n      previousRow.element.classList.remove(sides[0]);\n    }\n\n    if(row.new) {\n      this.setNewRow(index, true);\n    }\n\n    row.element.classList.toggle('is-hiding', false);\n    previousRow && previousRow.element.classList.toggle('is-hiding', true);\n\n    this.clearRows(index);\n  }\n\n  public destroy() {\n    for(const i in this.rows) {\n      this.clearRow(+i);\n    }\n  }\n}\n","import {fastRaf} from '@helpers/schedulers';\nimport {AnimatedSuper} from '@components/animatedSuper';\n\nexport interface AnimatedCounterOptions {\n  reverse?: boolean;\n  duration?: number;\n  prefix?: string;\n  calculateWidth?: ((text: string) => number) | true;\n}\n\nexport class AnimatedCounter {\n  static EMPTY_INDEX = -1;\n  static BASE_CLASS = 'animated-counter';\n  container: HTMLElement;\n  decimals: {\n    container: HTMLElement,\n    placeholder: HTMLElement,\n    animatedSuper: AnimatedSuper\n  }[] = [];\n  prefixContainer?: HTMLElement;\n  previousNumber = 0;\n  clearTimeout: number;\n\n  prefix?: AnimatedCounterOptions['prefix'];\n  reverse: AnimatedCounterOptions['reverse'];\n  duration: AnimatedCounterOptions['duration'];\n  calculateWidth?: AnimatedCounterOptions['calculateWidth'];\n\n  constructor(options: AnimatedCounterOptions) {\n    this.reverse = options.reverse;\n    this.duration = options.duration ?? AnimatedSuper.DEFAULT_DURATION;\n    this.container = document.createElement('div');\n    this.container.className = AnimatedCounter.BASE_CLASS;\n    this.calculateWidth = options.calculateWidth;\n\n    if(this.calculateWidth) {\n      this.container.classList.add('animated-counter-dynamic-width');\n    }\n\n    if(options.prefix) {\n      const prefixContainer = document.createElement('div');\n      prefixContainer.className = AnimatedCounter.BASE_CLASS + '-decimal-prefix';\n      prefixContainer.innerText = this.prefix = options.prefix;\n      this.container.append(prefixContainer);\n      this.prefixContainer = prefixContainer;\n    }\n  }\n\n  getDecimal(index: number) {\n    if(this.decimals[index]) return this.decimals[index];\n    const item = document.createElement('div');\n    item.className = AnimatedCounter.BASE_CLASS + '-decimal';\n\n    const placeholder = document.createElement('div');\n    placeholder.className = AnimatedCounter.BASE_CLASS + '-decimal-placeholder';\n\n    const animatedSuper = new AnimatedSuper({duration: this.duration});\n    animatedSuper.container.className = AnimatedCounter.BASE_CLASS + '-decimal-wrapper';\n\n    item.append(placeholder, animatedSuper.container);\n\n    this.container.append(item);\n\n    return this.decimals[index] = {container: item, placeholder, animatedSuper};\n  }\n\n  clear(number: number) {\n    if(this.clearTimeout) clearTimeout(this.clearTimeout);\n\n    const decimals = ('' + number).length;\n    if(decimals >= this.decimals.length) {\n      return;\n    }\n\n    this.clearTimeout = window.setTimeout(() => {\n      const byDecimal = this.decimals.splice(decimals, this.decimals.length - decimals);\n      byDecimal.forEach((decimal) => {\n        decimal.container.remove();\n      });\n    }, this.duration);\n  }\n\n  hideLeft(number: number) {\n    const decimals = ('' + number).length;\n    const byDecimal = this.decimals.slice(decimals);// this.decimals.splice(deleteCount, this.decimals.length - deleteCount);\n    byDecimal.forEach((decimal) => {\n      const previousDecimalNumber = +decimal.placeholder.innerText || 0;\n      const row = decimal.animatedSuper.getRow(AnimatedCounter.EMPTY_INDEX, true);\n      decimal.animatedSuper.animate(AnimatedCounter.EMPTY_INDEX, previousDecimalNumber, this.reverse ? number < this.previousNumber : number > this.previousNumber, true);\n    });\n\n    this.clear(number);\n  }\n\n  setCount(number: number, noRaf?: boolean) {\n    // this.prepareNumber(number);\n\n    const texts: string[] = [];\n    const nextRows: HTMLElement[] = [];\n    const previousByDecimal = Array.from('' + this.previousNumber).map((n) => +n);\n    const byDecimal = Array.from('' + number).map((n) => +n);\n    byDecimal.forEach((decimalNumber, idx) => {\n      const decimal = this.getDecimal(idx);\n      const row = decimal.animatedSuper.getRow(decimalNumber, true);\n      const previousDecimalNumber = previousByDecimal[idx] ?? AnimatedCounter.EMPTY_INDEX;\n      const text = '' + decimalNumber;\n      row.innerText = decimal.placeholder.innerText = text;\n      texts.push(text);\n      nextRows.push(row);\n      decimal.animatedSuper.animate(\n        decimalNumber,\n        previousDecimalNumber,\n        this.reverse ? number < this.previousNumber : number > this.previousNumber,\n        true\n      );\n    });\n\n    const setWidth = () => {\n      let width: number;\n      if(typeof(calculateWidth) === 'boolean') {\n        width = nextRows.reduce((sum, row) => sum + row.clientWidth, 0);\n        if(this.prefixContainer) {\n          width += this.prefixContainer.clientWidth;\n        }\n      } else {\n        const text = (this.prefix || '') + texts.join('');\n        width = calculateWidth(text);\n      }\n\n      this.container.style.setProperty('--width', width + 'px');\n    };\n\n    const {calculateWidth} = this;\n    if(calculateWidth) {\n      noRaf ? setWidth() : fastRaf(setWidth);\n    }\n\n    this.hideLeft(number);\n    // this.clear(number);\n    this.previousNumber = number;\n  }\n\n  destroy() {\n    this.decimals.forEach((decimal) => {\n      decimal.animatedSuper.destroy();\n    });\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {JSX} from 'solid-js';\n\nimport classNames from '@helpers/string/classNames';\nimport appImManager from '@lib/appImManager';\n\nimport showTooltip from '@components/tooltip';\n\ntype CurrentToast = {\n  hide: () => void,\n  closeOnPeerChange: boolean\n};\n\nlet current: CurrentToast;\nlet isListenerSet = false;\n\n/**\n * A toast docked just below the chat topbar (and floating pinned plates).\n *\n * Mounted on the .chat element (sibling to .topbar / .bubbles), NOT inside\n * .bubbles: .bubbles is a transformed z-index:1 stacking context that would\n * trap the toast below the topbar (z-index:2) and chat input. Docking is done\n * by the chat-toast class (see _chatToast.scss).\n *\n * Only one toast is shown at a time — showing a new one hides the previous.\n */\nexport default function showChatToast(options: {\n  textElement: HTMLElement | DocumentFragment,\n  title?: HTMLElement,\n  rightElement?: JSX.Element,\n  icon?: Icon,\n  class?: string,\n  duration?: number,\n  // 'slide' emerges from behind the topbar, 'fade' rises into place fading in\n  animation?: 'slide' | 'fade',\n  closeOnPeerChange?: boolean,\n  onHide?: () => void\n}) {\n  current?.hide();\n\n  if(!isListenerSet) {\n    isListenerSet = true;\n    appImManager.addEventListener('peer_changed', () => {\n      if(current?.closeOnPeerChange) {\n        current.hide();\n      }\n    });\n  }\n\n  options.title?.classList.add('text-bold');\n\n  const {close} = showTooltip({\n    element: appImManager.chat.container,\n    container: appImManager.chat.container,\n    mountOn: appImManager.chat.container,\n    relative: true,\n    vertical: 'top',\n    class: classNames('chat-toast', `chat-toast--${options.animation ?? 'slide'}`, options.class),\n    icon: options.icon,\n    textElement: options.title ?? options.textElement,\n    subtitleElement: options.title && options.textElement,\n    rightElement: options.rightElement,\n    onClose: () => {\n      if(current === entry) {\n        current = undefined;\n      }\n\n      options.onHide?.();\n    }\n  });\n\n  const entry: CurrentToast = current = {\n    hide: close,\n    closeOnPeerChange: options.closeOnPeerChange ?? true\n  };\n\n  if(options.duration) {\n    setTimeout(close, options.duration);\n  }\n\n  return {hide: close};\n}\n","import {Accessor, createEffect, createRoot, createSignal, onCleanup} from 'solid-js';\n\nimport {SEND_PAID_WITH_STARS_DELAY} from '@appManagers/constants';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\nimport eachSecond from '@helpers/eachSecond';\nimport {animate} from '@helpers/animation';\n\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport showChatToast from '@components/chat/chatToast';\n\n\ntype LangKeys = {\n  titleKey: LangPackKey;\n  subtitleKey: LangPackKey;\n};\n\nexport const paidReactionLangKeys: LangKeys = {\n  titleKey: 'PaidReaction.Sent',\n  subtitleKey: 'StarsSentText'\n};\n\nexport const paidMessagesLangKeys: LangKeys = {\n  titleKey: 'PaidMessages.MessagesSent',\n  subtitleKey: 'PaidMessages.YouPaidForMessages'\n};\n\n\nexport default function showUndoablePaidTooltip(props: {\n  sendTime: Accessor<number>;\n  titleCount: Accessor<number>;\n  subtitleCount: Accessor<number>;\n  onUndo: () => void;\n  wider?: boolean;\n} & LangKeys) {\n  createRoot((dispose) => {\n    const [secondsLeft, setSecondsLeft] = createSignal<number>();\n    const [progressCircumference, setProgressCircumference] = createSignal<number>();\n\n    const title = new I18n.IntlElement({key: props.titleKey});\n    const subtitle = new I18n.IntlElement({key: props.subtitleKey});\n\n    createEffect(() => {\n      title.compareAndUpdate({args: [props.titleCount()]});\n      subtitle.compareAndUpdate({args: [props.subtitleCount()]});\n    });\n\n    createEffect(() => {\n      if(!(!!props.sendTime())) {\n        dispose();\n        hide();\n      } else {\n        const disposeTimer = eachSecond(() => {\n          setSecondsLeft((props.sendTime() - Date.now()) / 1000 | 0);\n        });\n\n        animate(() => {\n          const progress = (props.sendTime() - Date.now()) / SEND_PAID_WITH_STARS_DELAY;\n          setProgressCircumference(progress * circumference);\n          return !cleaned;\n        });\n\n        let cleaned = false;\n        onCleanup(() => {\n          cleaned = true;\n          disposeTimer();\n        });\n      }\n    });\n\n    const size = 24;\n    const radius = 10;\n    const circumference = radius * 2 * Math.PI;\n\n    const countdown = new AnimatedCounter({reverse: false});\n    createEffect(() => countdown.setCount(secondsLeft()));\n\n    const {hide} = showChatToast({\n      animation: 'fade',\n      // the undo countdown outlives a chat switch — the send can still be aborted\n      closeOnPeerChange: false,\n      class: classNames('paid-reaction-tooltip', props.wider && 'paid-reaction-tooltip--a-little-wider'),\n      title: title.element,\n      textElement: subtitle.element,\n      rightElement: (\n        <span\n          class=\"tooltip-undo\"\n          onClick={() => void props.onUndo()}\n        >\n          {i18n('Undo')}\n          <span class=\"tooltip-undo-timer\">\n            <svg class=\"tooltip-undo-timer-svg\" width={size + 'px'} height={size + 'px'}>\n              <circle\n                cx={size / 2}\n                cy={size / 2}\n                r={radius}\n                class=\"tooltip-undo-timer-circle\"\n                transform={`rotate(-90, ${size / 2}, ${size / 2})`}\n                stroke-dasharray={`${progressCircumference()} ${circumference}`}\n              ></circle>\n            </svg>\n            <span class=\"tooltip-undo-timer-number\">\n              {countdown.container}\n            </span>\n          </span>\n        </span>\n      ),\n      icon: 'star'\n    });\n  });\n}\n","import {createRoot, createSignal} from 'solid-js';\n\nimport {setReservedStars} from '@stores/stars';\n\n\nconst createPendingUndoableMessage = () => createRoot(dispose => {\n  const [messageCount, setMessageCount] = createSignal(0);\n  const [sendTime, setSendTime] = createSignal(0);\n\n  const [reserved, setReserved] = createSignal(0);\n\n  let abortController = new AbortController;\n\n  return {\n    timeoutId: 0,\n\n    messageCount,\n    setMessageCount,\n    sendTime,\n    setSendTime,\n    reserved,\n    setReserved,\n\n    abort() {\n      abortController.abort();\n    },\n\n    get signal() {\n      return abortController.signal;\n    },\n\n    softReset() {\n      self.clearTimeout(this.timeoutId);\n      this.timeoutId = 0;\n\n      abortController = new AbortController;\n    },\n\n\n    resetGlobalReserved() {\n      setReservedStars(prev => prev - reserved());\n    },\n\n    reset() {\n      this.softReset();\n\n      setSendTime(0);\n      setMessageCount(0);\n\n      setReserved(0);\n    },\n\n    dispose\n  };\n});\n\nexport default createPendingUndoableMessage;\n","import {SEND_PAID_WITH_STARS_DELAY} from '@appManagers/constants';\nimport type {AppManagers} from '@lib/managers';\nimport useStars, {setReservedStars} from '@stores/stars';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport rootScope from '@lib/rootScope';\nimport {i18n} from '@lib/langPack';\nimport noop from '@helpers/noop';\n\nimport confirmationPopup from '@components/confirmationPopup';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport PopupStars from '@components/popups/stars';\nimport PopupElement from '@components/popups';\n\nimport showUndoablePaidTooltip, {paidMessagesLangKeys} from '@components/chat/undoablePaidTooltip';\nimport createPendingUndoableMessage from '@components/chat/pendingUndoableMessage';\nimport type Chat from '@components/chat/chat';\nimport {useAppState} from '@stores/appState';\n\n\ntype PassedDownArgs = {\n  peerId: PeerId;\n  messageCount: number;\n  starsAmount: number;\n};\n\nenum UserConfirmationResult {\n  /**\n   * In case 'Don't show again' was checked previously\n   */\n  Skipped,\n\n  Confirmed,\n  Rejected\n};\n\nexport type ConfirmedPaymentResult = {\n  starsAmount: number;\n  canUndo: boolean;\n};\n\n/**\n * `undefined` if no stars are needed, or a PAYMENT_REJECTED symbol if the users cancels the payment / doesn't have enough balance\n */\ntype PreparedPaymentResult = undefined | typeof PAYMENT_REJECTED | ConfirmedPaymentResult;\n\nexport const PAYMENT_REJECTED = Symbol('Payment rejected');\n\n\nexport default class PaidMessagesInterceptor {\n  private pendingUndoableMessage = createPendingUndoableMessage();\n\n  private static rawStars = useStars();\n\n  /**\n   * Mininum required params to make the message(s) undoable\n   *\n   * (Editable through global class attached to the window)\n   */\n  private static MIN_UNDO_SENDING_PARAMS = {\n    starsAmount: 100,\n    messageCount: 3\n  };\n  // private static MIN_UNDO_SENDING_PARAMS = {\n  //   starsAmount: 2,\n  //   messageCount: 3\n  // };\n\n  public static PaymentRejectedSymbol: typeof PAYMENT_REJECTED = PAYMENT_REJECTED;\n\n  constructor(private chat: Chat, private managers: AppManagers) {}\n\n  public dispose() {\n    this.pendingUndoableMessage.dispose();\n  }\n\n  private static get starsBalance() {\n    return +this.rawStars();\n  }\n\n  /**\n   * The starsAmount better be provided by this interceptor and then passed manually to the send method\n   * to make sure we don't accidentally send stars in a case that might have not been handled\n   */\n  public async prepareStarsForPayment(messageCount: number): Promise<PreparedPaymentResult> {\n    const {peerId, starsAmount} = this.chat\n\n    if(!starsAmount) return;\n\n    const totalStarsAmount = messageCount * starsAmount;\n\n    if(PaidMessagesInterceptor.starsBalance < totalStarsAmount)\n    {\n      this.pendingUndoableMessage.abort();\n      PopupElement.createPopup(PopupStars, {spendPurposePeerId: peerId});\n      return PAYMENT_REJECTED;\n    }\n\n    const userConfirmation = await PaidMessagesInterceptor.checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain: true});\n    if(userConfirmation === UserConfirmationResult.Rejected) return PAYMENT_REJECTED;\n\n    const canUndo = (\n      PaidMessagesInterceptor.canUndoMessageSending({userConfirmation, messageCount, starsAmount}) ||\n      !!this.pendingUndoableMessage.messageCount() // Allow undo if there's some pending undoable messages already\n    );\n\n    if(canUndo)\n    {\n      setReservedStars(prev => prev + totalStarsAmount);\n      this.pendingUndoableMessage.setReserved(prev => prev + totalStarsAmount);\n\n      this.triggerUndoableMessages({peerId, messageCount, starsAmount});\n    }\n\n    return {starsAmount, canUndo};\n  }\n\n  private static canUndoMessageSending(args: {userConfirmation: UserConfirmationResult, messageCount: number, starsAmount: number}) {\n    const {messageCount, starsAmount, userConfirmation} = args;\n\n    if(UserConfirmationResult.Skipped !== userConfirmation) return false;\n\n    return (\n      starsAmount >= this.MIN_UNDO_SENDING_PARAMS.starsAmount ||\n      messageCount >= this.MIN_UNDO_SENDING_PARAMS.messageCount\n    );\n  }\n\n  /**\n   * Static method - to be used outside a chat instance\n   *\n   * The starsAmount better be provided by this interceptor and then passed manually to the send method\n   * to make sure we don't accidentally send stars in a case that might have not been handled\n   */\n  public static async prepareStarsForPayment(args: {messageCount: number, peerId: PeerId}): Promise<PreparedPaymentResult> {\n    const {peerId, messageCount} = args;\n\n    const starsAmount = await rootScope.managers.appPeersManager.getStarsAmount(peerId);\n\n    if(!starsAmount) return;\n\n    const totalStarsAmount = messageCount * starsAmount;\n\n    if(PaidMessagesInterceptor.starsBalance < totalStarsAmount)\n    {\n      PopupElement.createPopup(PopupStars, {spendPurposePeerId: peerId});\n      return PAYMENT_REJECTED;\n    }\n\n    const userConfirmation = await PaidMessagesInterceptor.checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain: false});\n\n    if(userConfirmation === UserConfirmationResult.Rejected) return PAYMENT_REJECTED;\n\n\n    return {starsAmount, canUndo: false};\n  }\n\n  private static async checkIfUserReallyWantsToPay({peerId, messageCount, starsAmount, withDontShowAgain}: PassedDownArgs & {withDontShowAgain: boolean}) {\n    const totalStarsAmount = starsAmount * messageCount;\n\n    let onNotShowAgain = noop;\n\n    if(withDontShowAgain)\n    {\n      const {dontShowPaidMessageWarningFor = []} = await rootScope.managers.appStateManager.getState();\n      const shouldShowWarning = !dontShowPaidMessageWarningFor.includes(peerId);\n\n      if(!shouldShowWarning) return UserConfirmationResult.Skipped;\n\n      onNotShowAgain = () => {\n        const [, setAppState] = useAppState();\n        setAppState('dontShowPaidMessageWarningFor', [...dontShowPaidMessageWarningFor, peerId]);\n      };\n    }\n\n    try\n    {\n      const dontShowAgain = await confirmationPopup({\n        titleLangKey: 'ConfirmPayment',\n        descriptionLangKey: messageCount > 1 ?\n          'PaidMessages.UserChargesForMultipleMessageWarning' :\n          'PaidMessages.UserChargesForOneMessageWarning',\n        descriptionLangArgs: [\n          await wrapPeerTitle({peerId, onlyFirstName: true}),\n          i18n('Stars', [starsAmount]),\n          i18n('Stars', [totalStarsAmount]),\n          ...(messageCount > 1 ? [messageCount] : [])\n        ],\n        checkbox: withDontShowAgain ? {\n          text: 'DontAskAgain'\n        } : undefined,\n        button: {\n          langKey: 'PaidMessages.PayForMessages',\n          langArgs: [messageCount]\n        }\n      });\n\n      if(withDontShowAgain && dontShowAgain) onNotShowAgain();\n    }\n    catch\n    {\n      return UserConfirmationResult.Rejected;\n    }\n\n    return UserConfirmationResult.Confirmed;\n  }\n\n  private triggerUndoableMessages({peerId, messageCount, starsAmount}: PassedDownArgs) {\n    this.pendingUndoableMessage.setMessageCount(prev => prev + messageCount);\n    this.pendingUndoableMessage.setSendTime(Date.now() + SEND_PAID_WITH_STARS_DELAY);\n\n    if(!this.pendingUndoableMessage.timeoutId) {\n      showUndoablePaidTooltip({\n        sendTime: this.pendingUndoableMessage.sendTime,\n        titleCount: this.pendingUndoableMessage.messageCount,\n        subtitleCount: () => this.pendingUndoableMessage.messageCount() * starsAmount,\n        onUndo: () => void this.pendingUndoableMessage.abort(),\n        ...paidMessagesLangKeys\n      });\n    }\n\n    this.pendingUndoableMessage.softReset();\n\n    this.pendingUndoableMessage.signal.addEventListener('abort', () => {\n      this.managers.appMessagesManager.cancelQueuedPaidMessages(peerId);\n      this.pendingUndoableMessage.resetGlobalReserved();\n      this.pendingUndoableMessage.reset();\n    });\n\n    this.pendingUndoableMessage.timeoutId = self.setTimeout(() => {\n      this.managers.appMessagesManager.sendQueuedPaidMessages(peerId);\n      this.pendingUndoableMessage.reset();\n    }, SEND_PAID_WITH_STARS_DELAY);\n  }\n}\n\nMOUNT_CLASS_TO['PaidMessagesInterceptor'] = PaidMessagesInterceptor;\n","export default function canvasToBlob(canvas: HTMLCanvasElement, type?: string, quality?: number) {\n  return new Promise<Blob>((resolve, reject) => {\n    canvas.toBlob((blob) => {\n      if(blob) {\n        resolve(blob);\n      } else {\n        reject(new Error('Failed to encode canvas'));\n      }\n    }, type, quality);\n  });\n}\n","import type {MediaSize} from '@helpers/mediaSize';\nimport IS_IMAGE_BITMAP_SUPPORTED from '@environment/imageBitmapSupport';\nimport canvasToBlob from '@helpers/canvas/canvasToBlob';\n\nexport default async function scaleMediaElement<T extends {\n  media: CanvasImageSource,\n  mediaSize?: MediaSize,\n  boxSize?: MediaSize,\n  quality?: number,\n  mimeType?: 'image/jpeg' | 'image/png',\n  size?: MediaSize,\n  toDataURL?: boolean\n}>(options: T): Promise<T['toDataURL'] extends true ? {url: string, size: MediaSize} : {blob: Blob, size: MediaSize}> {\n  const canvas = document.createElement('canvas');\n  const size = options.size ?? options.mediaSize.aspectFitted(options.boxSize);\n  const dpr = window.devicePixelRatio && 1;\n  canvas.width = size.width * dpr;\n  canvas.height = size.height * dpr;\n  const ctx = canvas.getContext('2d');\n\n  let source: CanvasImageSource;\n  if(IS_IMAGE_BITMAP_SUPPORTED) {\n    source = await createImageBitmap(options.media, {resizeWidth: size.width, resizeHeight: size.height});\n  } else {\n    source = options.media;\n  }\n\n  ctx.drawImage(source, 0, 0, canvas.width, canvas.height);\n\n  if(IS_IMAGE_BITMAP_SUPPORTED) {\n    (source as ImageBitmap)?.close();\n  }\n\n  const mimeType = options.mimeType ?? 'image/jpeg';\n  const quality = options.quality ?? 1;\n  if(options.toDataURL) {\n    const url = canvas.toDataURL(mimeType, quality);\n    return {url, size} as any;\n  }\n\n  const blob = await canvasToBlob(canvas, mimeType, quality);\n  return {blob, size} as any;\n}\n","import pause from '@helpers/schedulers/pause';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport scaleMediaElement from '@helpers/canvas/scaleMediaElement';\nimport preloadVideo from '@helpers/preloadVideo';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\n\n// iOS fits the uploaded video thumb into a square box (320), Android keeps the\n// frame size as-is; 720 matches the media editor's thumbnail cap and stays\n// sharp on retina bubbles (the old 320x240 box crippled portrait videos)\nconst POSTER_MAX_SIZE = 720;\n\nexport function createPosterFromMedia(media: HTMLVideoElement | HTMLImageElement) {\n  let width: number, height: number;\n  if(media instanceof HTMLVideoElement) {\n    width = media.videoWidth;\n    height = media.videoHeight;\n  } else {\n    width = media.naturalWidth;\n    height = media.naturalHeight;\n  }\n\n  return scaleMediaElement({\n    media,\n    mediaSize: makeMediaSize(width, height),\n    // clamp the box to the source so a smaller video is never upscaled\n    boxSize: makeMediaSize(Math.min(width, POSTER_MAX_SIZE), Math.min(height, POSTER_MAX_SIZE)),\n    quality: .9\n  });\n}\n\nexport function createPosterFromVideo(video: HTMLVideoElement): ReturnType<typeof createPosterFromMedia> {\n  return new Promise((resolve, reject) => {\n    video.onseeked = () => {\n      video.onseeked = () => {\n        createPosterFromMedia(video).then(resolve);\n\n        video.onseeked = undefined;\n      };\n\n      setCurrentTime(video, 0);\n    };\n\n    video.onerror = reject;\n    setCurrentTime(video, Math.min(video.duration, 1));\n  });\n}\n\nexport async function createPosterForVideo(url: string) {\n  const video = await preloadVideo(url);\n\n  return Promise.race([\n    pause(2000) as Promise<undefined>,\n    createPosterFromVideo(video)\n  ]);\n}\n\n\n","// ChatRecording — the voice + round-video-note recording collaborator extracted\n// out of ChatInput. Owns all recording state (recorders, waveform analysers, the\n// voice + video panels, playback) and every method that drives a recording\n// session. ChatInput keeps the send button / input row and delegates the\n// recording branches here.\n//\n// `import type ChatInput` is intentionally TYPE-ONLY to avoid a runtime import\n// cycle (ChatInput constructs this class at runtime).\n\nimport type ChatInput from '../input';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport {POSTING_NOT_ALLOWED_MAP} from '../input';\nimport {ChatType} from '../chatType';\nimport opusDecodeController from '@lib/opusDecodeController';\nimport VoiceWaveformAnalyser from '@helpers/voiceWaveformAnalyser';\nimport LiveWaveformAnalyser from '@helpers/voiceRecorder/liveWaveformAnalyser';\nimport NativeVoiceRecorder, {isNativeVoiceRecorderSupported} from '@helpers/voiceRecorder/nativeVoiceRecorder';\nimport NativeVideoRecorder, {isNativeVideoRecorderSupported} from '@helpers/videoRecorder/nativeVideoRecorder';\nimport VoiceRecordingPanel from '@components/chat/voiceRecording/voiceRecordingPanel';\nimport {createVideoRecordingPanel, VideoRecordingPanelHandle} from '@components/chat/recording/videoRecordingPanel';\nimport {appSettings} from '@stores/appSettings';\nimport {toast, toastNew} from '@components/toast';\nimport {Listener} from '@helpers/listenerSetter';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport {fastRaf} from '@helpers/schedulers';\nimport PopupPeer from '@components/popups/peer';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport PopupElement from '@components/popups';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {ChatRights} from '@appManagers/appChatsManager';\nimport type {MessageSendingParams} from '@appManagers/appMessagesManager';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {createPosterFromMedia} from '@helpers/createPoster';\nimport type {MediaSize} from '@helpers/mediaSize';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\n\nconst RECORD_MIN_TIME = 500;\n// Max duration of a round video note. Matches the cap official clients enforce\n// (`60s`); the recorder stops automatically when the progress ring fills.\nconst VIDEO_RECORD_MAX_MS = 60_000;\n\n// Mirrors the module-local CLASS_NAME in input.ts (`'chat-input'`). The\n// outside-click guards installed while recording test the click target against\n// this class to decide whether a click is \"inside\" the chat input.\nconst CLASS_NAME = 'chat-input';\n\nexport default class ChatRecording {\n  private recorder: any;\n  private videoRecorder: NativeVideoRecorder;\n  private waveformAnalyser: VoiceWaveformAnalyser;\n  private liveWaveformAnalyser: LiveWaveformAnalyser;\n  public active = false;\n  // Which recorder is currently active during a recording session. When not\n  // recording, the user's persisted `recordingMediaType` setting dictates the\n  // icon shown on the send button; once a recording starts we capture the\n  // type here so toggle-mid-recording can't desync the UI.\n  private recordingType: 'voice' | 'video' = 'voice';\n  private recordPaused = false;\n  private recordCanceled = false;\n  private recordStartTime = 0;\n  private recordAccumulatedMs = 0;\n  private recordingOverlayListener: Listener;\n  private recordingNavigationItem: NavigationItem;\n  private voiceRecordingPanel: VoiceRecordingPanel;\n  private videoRecordingPanel: VideoRecordingPanelHandle;\n  private playbackAudio: HTMLAudioElement;\n  private playbackObjectUrl: string;\n  private playbackRafId: number;\n  private voiceMenuClickGuard: (e: MouseEvent) => void;\n  // Recorded blob URL used for paused-preview playback inside the round video\n  // panel. Revoked on stop() / send / cancel to release the captured frames.\n  private videoPlaybackObjectUrl: string;\n  // Audio tap for the live waveform during video recording. The MediaRecorder\n  // doesn't expose PCM, so we open a parallel AudioContext on a CLONE of the\n  // stream's audio track (tapping the original track that MediaRecorder is\n  // recording starves both consumers → silent recording + flat waveform).\n  private videoAudioContext: AudioContext;\n  private videoWaveformStream: MediaStream;\n  private videoPlaybackRafId: number;\n  // Set when a video recording hits VIDEO_RECORD_MAX_MS: recording stops at the\n  // cap and switches to the paused-preview state (iOS-style) — the user can\n  // preview + send/discard but cannot record further (resume is blocked).\n  private videoLimitReached = false;\n  // True from the moment a recording is requested until start() resolves —\n  // blocks a duplicate start during the camera warm-up wait.\n  private isStartingRecording = false;\n  // Set when a left-button long-press on the record button opens the mode-switch\n  // menu, so the click that ends the press doesn't also start a recording.\n  private recordModeLongPressed = false;\n  private pinnedEphemeralSendingParams: MessageSendingParams;\n\n  private releaseMediaPlayback: () => void;\n\n  constructor(private input: ChatInput) {\n    this.constructRecorder();\n\n    this.voiceRecordingPanel = new VoiceRecordingPanel({\n      onCancel: () => this.onCancelRecordClick(),\n      onPauseToggle: () => this.onPauseToggleClick(),\n      onPlayToggle: () => this.onPlayToggleClick(),\n      onSeek: (progress) => this.onPlaybackSeek(progress)\n    });\n    // The panel is an absolutely-positioned overlay inside the input row.\n    // It sits *under* btnSendContainer in DOM order so the send button stays\n    // on top while everything else (attach, input, emoji) is hidden via CSS.\n    this.input.newMessageWrapper.insertBefore(this.voiceRecordingPanel.element, this.input.btnSendContainer);\n\n    // Round-video-note panel — created here (and not next to the voice panel)\n    // because constructRecorder is what sets this.videoRecorder. The control\n    // bar slots into the input row the same way as voice; the dim overlay +\n    // 360x360 round preview is mounted into the chat container so it covers\n    // bubbles but stays under the input bar (which has a higher z-index).\n    if(this.videoRecorder) {\n      // Just the centered round preview — all recording controls stay in the\n      // chat input (the same voiceRecordingPanel + btn-send the voice flow\n      // uses). Mounted on <body> so it's reliably screen-centered.\n      this.videoRecordingPanel = createVideoRecordingPanel();\n      getOverlayRoot().append(this.videoRecordingPanel.element);\n    }\n\n    this.setupRecordingModeMenu();\n  }\n\n  private constructRecorder() {\n    const config = {\n      // encoderBitRate: 32,\n      // encoderPath: \"../dist/encoderWorker.min.js\",\n      encoderSampleRate: 48000,\n      monitorGain: 0,\n      numberOfChannels: 1,\n      recordingGain: 1,\n      reuseWorker: true\n    };\n\n    if(isNativeVoiceRecorderSupported()) {\n      try {\n        this.recorder = new NativeVoiceRecorder(config);\n      } catch(err) {\n        console.error('NativeVoiceRecorder constructor error:', err);\n      }\n    }\n\n    if(!this.recorder) {\n      const Recorder = (window as any).Recorder;\n      if(Recorder) try {\n        this.recorder = new Recorder(config);\n      } catch(err) {\n        console.error('Recorder constructor error:', err);\n      }\n    }\n\n    if(isNativeVideoRecorderSupported()) {\n      try {\n        this.videoRecorder = new NativeVideoRecorder({\n          width: 400,\n          height: 400,\n          frameRate: 30,\n          videoBitsPerSecond: 1_200_000,\n          audioBitsPerSecond: 64_000\n        });\n      } catch(err) {\n        console.error('NativeVideoRecorder constructor error:', err);\n      }\n    }\n\n    if(!this.recorder) {\n      return;\n    }\n\n    attachClickEvent(this.input.btnCancelRecord, this.onCancelRecordClick, {listenerSetter: this.input.listenerSetter});\n\n    this.recorder.onstop = () => {\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n\n      if(this.waveformAnalyser) {\n        this.waveformAnalyser.finish();\n        this.waveformAnalyser = undefined;\n      }\n      this.teardownLiveWaveform();\n      this.stopPlayback();\n      // Any menu-open click guard from the SendMenu is now meaningless —\n      // recording is over.\n      this.setVoiceRecordingMenuGuard(false);\n    };\n\n    this.recorder.ondataavailable = async(typedArray: Uint8Array) => {\n      if(this.releaseMediaPlayback) {\n        this.releaseMediaPlayback();\n        this.releaseMediaPlayback = undefined;\n      }\n\n      if(this.recordingOverlayListener) {\n        this.input.listenerSetter.remove(this.recordingOverlayListener);\n        this.recordingOverlayListener = undefined;\n      }\n\n      if(this.recordingNavigationItem) {\n        appNavigationController.removeItem(this.recordingNavigationItem);\n        this.recordingNavigationItem = undefined;\n      }\n\n      const waveform = this.waveformAnalyser?.finish();\n      this.waveformAnalyser = undefined;\n\n      if(this.recordCanceled) {\n        return;\n      }\n\n      const sendingParams = {\n        ...this.input.chat.getMessageSendingParams(),\n        ...this.pinnedEphemeralSendingParams\n      };\n      const isEphemeral = !!sendingParams.ephemeral;\n      this.pinnedEphemeralSendingParams = undefined;\n\n      if(!isEphemeral) {\n        const preparedPaymentResult = await this.input.paidMessageInterceptor.prepareStarsForPayment(1);\n        if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n        sendingParams.confirmedPaymentResult = preparedPaymentResult;\n      }\n\n      const duration = this.getRecordingElapsedMs() / 1000 | 0;\n      const dataBlob = new Blob([typedArray as BlobPart], {type: 'audio/ogg'});\n      opusDecodeController.decode(typedArray, false).then((result) => {\n        opusDecodeController.setKeepAlive(false);\n\n        // тут objectURL ставится уже с audio/wav\n        this.input.managers.appMessagesManager.sendFile({\n          ...sendingParams,\n          file: dataBlob,\n          isVoiceMessage: true,\n          isMedia: true,\n          duration,\n          waveform,\n          objectURLBlob: result.blob,\n          clearDraft: true\n        });\n\n        this.input.onMessageSent(false, true, isEphemeral);\n      });\n    };\n\n    if(this.videoRecorder) {\n      this.videoRecorder.onstop = () => {\n        this.setRecording(false);\n        this.videoLimitReached = false;\n        this.input.chatInput.classList.remove('is-locked');\n        this.stopVideoPlayback();\n        this.teardownVideoWaveform();\n        // Reset the voice panel (in place) + fade out the round preview. The\n        // camera is kept alive through the fade (see NativeVideoRecorder), so\n        // the last frame fades instead of cutting to black — release it after.\n        this.voiceRecordingPanel?.setMode('recording');\n        this.voiceRecordingPanel?.clearPeaks();\n        this.videoRecordingPanel?.reset();\n        setTimeout(() => this.videoRecorder?.releaseStream(), 300);\n        this.setVoiceRecordingMenuGuard(false);\n      };\n\n      this.videoRecorder.ondataavailable = async(blob: Blob) => {\n        if(this.releaseMediaPlayback) {\n          this.releaseMediaPlayback();\n          this.releaseMediaPlayback = undefined;\n        }\n\n        if(this.recordingOverlayListener) {\n          this.input.listenerSetter.remove(this.recordingOverlayListener);\n          this.recordingOverlayListener = undefined;\n        }\n\n        if(this.recordingNavigationItem) {\n          appNavigationController.removeItem(this.recordingNavigationItem);\n          this.recordingNavigationItem = undefined;\n        }\n\n        if(this.recordCanceled) {\n          return;\n        }\n\n        // Grab a poster from the still-live camera frame *before* anything\n        // awaits — gives the optimistic (uploading) bubble something to show\n        // instead of a black circle while the upload runs.\n        const thumbPromise = this.captureVideoPoster();\n\n        const sendingParams = {\n          ...this.input.chat.getMessageSendingParams(),\n          ...this.pinnedEphemeralSendingParams\n        };\n        const isEphemeral = !!sendingParams.ephemeral;\n        this.pinnedEphemeralSendingParams = undefined;\n        if(!isEphemeral) {\n          const preparedPaymentResult = await this.input.paidMessageInterceptor.prepareStarsForPayment(1);\n          if(preparedPaymentResult === PAYMENT_REJECTED) return;\n          sendingParams.confirmedPaymentResult = preparedPaymentResult;\n        }\n\n        const duration = this.getRecordingElapsedMs() / 1000 | 0;\n        const thumb = await thumbPromise;\n        // The Blob already carries the recorder's mime type. We hand it to\n        // sendFile with isRoundMessage=true so the documentAttributeVideo flag\n        // gets `round_message=true` (see appMessagesManager.sendFile).\n        this.input.managers.appMessagesManager.sendFile({\n          ...sendingParams,\n          file: blob,\n          isRoundMessage: true,\n          isMedia: true,\n          duration,\n          // The capture is square at the configured size; appMessagesManager\n          // reads w/h off the file when omitted here, but providing them makes\n          // the optimistic message render correctly.\n          width: 400,\n          height: 400,\n          objectURLBlob: blob,\n          thumb,\n          clearDraft: true\n        });\n\n        this.input.onMessageSent(false, true, isEphemeral);\n      };\n    }\n  }\n\n  private onCancelRecordClick = (e?: Event) => {\n    if(e) {\n      cancelEvent(e);\n    }\n\n    this.recordCanceled = true;\n    this.stopPlayback();\n    this.stopVideoPlayback();\n    this.getActiveRecorder()?.stop();\n    if(this.recordingType === 'voice') {\n      opusDecodeController.setKeepAlive(false);\n    }\n  };\n\n  private getRecordingElapsedMs() {\n    if(this.recordPaused) return this.recordAccumulatedMs;\n    return this.recordAccumulatedMs + (Date.now() - this.recordStartTime);\n  }\n\n  private teardownLiveWaveform() {\n    if(this.liveWaveformAnalyser) {\n      this.liveWaveformAnalyser.destroy();\n      this.liveWaveformAnalyser = undefined;\n    }\n  }\n\n  private onPauseToggleClick = () => {\n    if(!this.active) return;\n    if(this.recordingType === 'video') {\n      this.onVideoPauseToggleClick();\n      return;\n    }\n    if(!this.recorder) return;\n\n    if(this.recordPaused) {\n      // Resume recording from paused state. Keep the existing waveform —\n      // new live bars will push in from the right, gradually shifting the\n      // snapshot off to the left rather than starting from scratch.\n      this.stopPlayback();\n      if(typeof this.recorder.resume === 'function') {\n        this.recorder.resume();\n      }\n      this.recordPaused = false;\n      this.recordStartTime = Date.now();\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.setSeekable(false);\n      this.liveWaveformAnalyser?.setPaused(false);\n      this.waveformAnalyser?.setPaused(false);\n      this.startRecordingTimerLoop();\n    } else {\n      // Pause active recording. Replace the rolling live waveform with the\n      // full compressed peaks the analyser has accumulated so playback\n      // progress maps to the whole recording duration, not just the bars\n      // that happened to fit in the live window.\n      if(typeof this.recorder.pause !== 'function') return;\n      this.recordAccumulatedMs += Date.now() - this.recordStartTime;\n      this.recordPaused = true;\n      this.liveWaveformAnalyser?.setPaused(true);\n      this.waveformAnalyser?.setPaused(true);\n      const fullPeaks = this.waveformAnalyser?.getCurrentPeaks();\n      if(fullPeaks && fullPeaks.length) {\n        this.voiceRecordingPanel?.setPeaks(fullPeaks);\n      }\n      this.voiceRecordingPanel?.setMode('paused');\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setSeekable(true);\n      Promise.resolve(this.recorder.pause()).catch(() => {});\n    }\n  };\n\n  private onVideoPauseToggleClick() {\n    if(!this.videoRecorder) return;\n\n    if(this.recordPaused) {\n      // Max length hit — recording is locked at the cap. Keep the resume button\n      // but tell the user why pressing it does nothing.\n      if(this.videoLimitReached) {\n        toastNew({langPackKey: 'Chat.Input.Record.VideoLimitReached'});\n        return;\n      }\n      // Resume from paused state — discard any preview playback, restore the\n      // live camera feed in the preview <video>, and continue recording.\n      this.stopVideoPlayback();\n      this.videoRecorder.resume();\n      this.recordPaused = false;\n      this.recordStartTime = Date.now();\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.setSeekable(false);\n      this.liveWaveformAnalyser?.setPaused(false);\n      this.waveformAnalyser?.setPaused(false);\n      // Restore the live camera feed (reveals on its first frame).\n      this.videoRecordingPanel?.startLivePreview(this.videoRecorder.stream);\n      this.startVideoRecordingTimerLoop();\n    } else {\n      this.recordAccumulatedMs += Date.now() - this.recordStartTime;\n      this.recordPaused = true;\n      this.liveWaveformAnalyser?.setPaused(true);\n      this.waveformAnalyser?.setPaused(true);\n      // Freeze the waveform on the full-recording peaks, like voice.\n      const fullPeaks = this.waveformAnalyser?.getCurrentPeaks();\n      if(fullPeaks && fullPeaks.length) this.voiceRecordingPanel?.setPeaks(fullPeaks);\n      this.voiceRecordingPanel?.setMode('paused');\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setSeekable(true);\n      this.videoRecordingPanel?.setMode('paused');\n      Promise.resolve(this.videoRecorder.pause()).catch(() => {});\n    }\n  }\n\n  private onPlayToggleClick = () => {\n    if(!this.active || !this.recordPaused) return;\n    if(this.recordingType === 'video') {\n      this.onVideoPlayToggleClick();\n      return;\n    }\n    if(this.playbackAudio && !this.playbackAudio.paused) {\n      this.playbackAudio.pause();\n      return;\n    }\n    if(this.playbackAudio && this.playbackAudio.currentTime > 0 && this.playbackAudio.currentTime < this.playbackAudio.duration) {\n      this.playbackAudio.play().catch(() => {});\n      return;\n    }\n    this.startPlaybackFromSnapshot();\n  };\n\n  private onVideoPlayToggleClick() {\n    if(!this.videoRecordingPanel || !this.videoRecorder) return;\n    const video = this.videoRecordingPanel.previewVideo;\n    // If we already have a playable snapshot mounted in the <video>, just\n    // play/pause it directly. The first call swaps in the snapshot blob.\n    if(!video.srcObject && video.src) {\n      if(video.paused) {\n        video.play().catch(() => {});\n      } else {\n        video.pause();\n      }\n      return;\n    }\n    this.startVideoPlaybackFromSnapshot();\n  }\n\n  // The mid-recording snapshot is a non-finalized webm/mp4, so video.duration\n  // is usually Infinity/NaN — fall back to the elapsed recording time we\n  // already track for progress + seeking math.\n  private getVideoPreviewDurationSec() {\n    const video = this.videoRecordingPanel?.previewVideo;\n    if(video && video.duration && isFinite(video.duration)) return video.duration;\n    return this.recordAccumulatedMs / 1000;\n  }\n\n  private startVideoPlaybackFromSnapshot() {\n    const snapshot = this.videoRecorder?.getSnapshot();\n    if(!snapshot || !snapshot.size || !this.videoRecordingPanel) return;\n    this.stopVideoPlayback();\n    this.videoPlaybackObjectUrl = URL.createObjectURL(snapshot);\n    const video = this.videoRecordingPanel.previewVideo;\n    video.srcObject = null;\n    // Unmute for preview (it was muted while mirroring the live camera to\n    // avoid feedback). volume + removeAttribute guard against a sticky\n    // muted-autoplay state.\n    video.muted = false;\n    video.volume = 1;\n    video.removeAttribute('muted');\n    video.loop = false;\n    video.src = this.videoPlaybackObjectUrl;\n    // videoRecordingPanel.setPlaying toggles the preview un-mirror; the\n    // voiceRecordingPanel owns the play/pause icon + waveform playhead + timer.\n    const setPlaying = (p: boolean) => {\n      this.videoRecordingPanel?.setPlaying(p);\n      this.voiceRecordingPanel?.setPlaying(p);\n    };\n    // Per-frame tick — `timeupdate` only fires every ~250ms, which looks jerky;\n    // a rAF loop reading currentTime each frame keeps the timer/ring/playhead\n    // smooth.\n    const tick = () => {\n      if(this.videoPlaybackRafId === undefined) return;\n      const dur = this.getVideoPreviewDurationSec();\n      if(dur) {\n        const progress = Math.max(0, Math.min(1, video.currentTime / dur));\n        this.voiceRecordingPanel?.setPlaybackProgress(progress);\n        this.videoRecordingPanel?.setProgress(progress);\n        this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(video.currentTime * 1000));\n      }\n      this.videoPlaybackRafId = requestAnimationFrame(tick);\n    };\n    const startTick = () => {\n      if(this.videoPlaybackRafId === undefined) this.videoPlaybackRafId = requestAnimationFrame(tick);\n    };\n    const stopTick = () => {\n      if(this.videoPlaybackRafId !== undefined) {\n        cancelAnimationFrame(this.videoPlaybackRafId);\n        this.videoPlaybackRafId = undefined;\n      }\n    };\n    video.onplay = () => {\n      setPlaying(true);\n      startTick();\n    };\n    video.onpause = () => {\n      setPlaying(false);\n      stopTick();\n    };\n    video.onended = () => {\n      setPlaying(false);\n      stopTick();\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(this.recordAccumulatedMs));\n      // Restore the ring to the recorded fraction (its frozen-pause look).\n      this.videoRecordingPanel?.setProgress(this.recordAccumulatedMs / VIDEO_RECORD_MAX_MS);\n    };\n    video.play().catch(() => {\n      // Preview playback can reject on routine autoplay hiccups — just reset,\n      // no need to log (mirrors the voice flow's silent playback catch).\n      this.stopVideoPlayback();\n    });\n  }\n\n  private stopVideoPlayback() {\n    if(this.videoPlaybackRafId !== undefined) {\n      cancelAnimationFrame(this.videoPlaybackRafId);\n      this.videoPlaybackRafId = undefined;\n    }\n    if(!this.videoRecordingPanel) return;\n    const video = this.videoRecordingPanel.previewVideo;\n    try {\n      video.pause();\n    } catch(e) {}\n    video.onplay = null;\n    video.onpause = null;\n    video.onended = null;\n    video.muted = true;\n    if(this.videoPlaybackObjectUrl) {\n      try {\n        URL.revokeObjectURL(this.videoPlaybackObjectUrl);\n      } catch(e) {}\n      this.videoPlaybackObjectUrl = undefined;\n    }\n    if(video.src) {\n      video.removeAttribute('src');\n      try {\n        video.load();\n      } catch(e) {}\n    }\n    this.videoRecordingPanel.setPlaying(false);\n    this.voiceRecordingPanel?.setPlaying(false);\n  }\n\n  // Drives the timer text + progress-ring fill while a video recording is\n  // active. Pauses (returns without re-scheduling) when recording is paused,\n  // resumed by onVideoPauseToggleClick. At VIDEO_RECORD_MAX_MS the recording\n  // doesn't auto-send — it stops at the cap and drops into the paused-preview\n  // state (iOS-style): preview + send/discard, but no further recording.\n  private startVideoRecordingTimerLoop() {\n    const r = () => {\n      if(!this.active || this.recordPaused) return;\n      if(this.recordingType !== 'video') return;\n      const elapsed = this.getRecordingElapsedMs();\n      if(elapsed >= VIDEO_RECORD_MAX_MS) {\n        this.reachVideoLimit();\n        return;\n      }\n      // Timer text lives in the shared voice panel; the ring is the video\n      // overlay's own progress affordance.\n      if(!this.voiceRecordingPanel?.getIsPlaying()) {\n        this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(elapsed));\n      }\n      this.videoRecordingPanel?.setProgress(elapsed / VIDEO_RECORD_MAX_MS);\n      fastRaf(r);\n    };\n    r();\n  }\n\n  // Hit the max duration: lock the recording at the cap and switch to the\n  // paused-preview state. Resume is then blocked (see onVideoPauseToggleClick);\n  // the user can only preview, send or discard.\n  private reachVideoLimit() {\n    if(this.videoLimitReached) return;\n    this.videoLimitReached = true;\n    this.videoRecordingPanel?.setProgress(1);\n    // Enter the paused state (recordPaused is false here, so this pauses).\n    this.onVideoPauseToggleClick();\n    this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(VIDEO_RECORD_MAX_MS));\n  }\n\n  // Install / remove the document-level click guard that closes the SendMenu\n  // on the first click anywhere outside the menu while a voice recording is\n  // active. Without this guard, a left-click would close the menu and also\n  // hit the underlying button (cancel/pause/send) on the way through — every\n  // visible button while recording is its own action target. Capture phase so\n  // we beat the buttons' own bubble-phase click listeners.\n  public setVoiceRecordingMenuGuard(active: boolean) {\n    if(this.voiceMenuClickGuard) {\n      getAppWindow().document.removeEventListener('click', this.voiceMenuClickGuard, {capture: true});\n      this.voiceMenuClickGuard = undefined;\n    }\n    if(!active || !this.active) return;\n\n    this.voiceMenuClickGuard = (e: MouseEvent) => {\n      // Let clicks inside the menu through so menu items still work.\n      if(findUpClassName(e.target as HTMLElement, 'btn-menu')) return;\n      cancelEvent(e);\n      if(contextMenuController.isOpened()) contextMenuController.close();\n    };\n    // On the active window's document so the guard still works in a Document PiP window.\n    getAppWindow().document.addEventListener('click', this.voiceMenuClickGuard, {capture: true});\n  }\n\n  // Stop the recorder so its ondataavailable handler sends the voice file.\n  // Used by the send context menu (Silent / Schedule / SendWhenOnline) while\n  // recording — the menu just sets the relevant flag on the ChatInput and\n  // delegates to this helper to commit the recording. The actual silent /\n  // scheduleDate flags are read back from this.input by getMessageSendingParams.\n  // Stop + send the in-progress recording from the send button's context menu\n  // (Send Without Sound / Schedule / Send When Online). Must stop the ACTIVE\n  // recorder — voice OR video — not always the voice one, or sending a round\n  // video note from the menu does nothing. The silent/schedule flags are already\n  // set by the caller and picked up via getMessageSendingParams on send.\n  public finishRecordingFromMenu() {\n    if(!this.active) return;\n    this.stopPlayback();\n    this.stopVideoPlayback();\n    this.getActiveRecorder()?.stop();\n  }\n\n  // Click-to-seek from the waveform. progress is 0..1 along the bars.\n  // If audio hasn't been decoded yet we kick playback off at that offset.\n  private onPlaybackSeek(progress: number) {\n    if(!this.recordPaused) return;\n    // The shared voice panel's waveform seek is wired to this; for a video\n    // recording it should scrub the round-video preview instead of audio.\n    if(this.recordingType === 'video') {\n      this.onVideoPlaybackSeek(progress);\n      return;\n    }\n    if(this.playbackAudio && this.playbackAudio.duration && !isNaN(this.playbackAudio.duration)) {\n      const target = Math.max(0, Math.min(this.playbackAudio.duration, progress * this.playbackAudio.duration));\n      this.playbackAudio.currentTime = target;\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n      if(this.playbackAudio.paused) this.playbackAudio.play().catch(() => {});\n      return;\n    }\n    // No audio yet — start playback and seek once metadata is available.\n    this.startPlaybackFromSnapshot(progress);\n  }\n\n  private async startPlaybackFromSnapshot(seekProgress?: number) {\n    if(!this.recorder || typeof this.recorder.getSnapshot !== 'function') return;\n    const snapshot: Uint8Array = this.recorder.getSnapshot();\n    if(!snapshot || !snapshot.length) return;\n\n    // Tear down any prior playback before decoding the fresh snapshot.\n    this.stopPlayback();\n\n    try {\n      const {blob} = await opusDecodeController.decode(snapshot, false);\n      const url = URL.createObjectURL(blob);\n      this.playbackObjectUrl = url;\n    } catch(err) {\n      console.error('[ChatInput] voice playback decode error:', err);\n      return;\n    }\n    if(!this.recordPaused) {\n      // Recording was resumed while we were decoding — drop the result.\n      this.playbackObjectUrl && URL.revokeObjectURL(this.playbackObjectUrl);\n      this.playbackObjectUrl = undefined;\n      return;\n    }\n\n    const audio = this.playbackAudio = new Audio(this.playbackObjectUrl);\n    audio.preload = 'auto';\n\n    const onTick = () => {\n      if(this.playbackAudio !== audio) return;\n      if(!audio.duration || isNaN(audio.duration)) {\n        this.playbackRafId = requestAnimationFrame(onTick);\n        return;\n      }\n      const progress = audio.currentTime / audio.duration;\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n\n      const playedMs = audio.currentTime * 1000;\n      const playedSec = playedMs / 1000;\n      const ms = playedMs % 1000;\n      this.voiceRecordingPanel?.setTimer(toHHMMSS(playedSec) + ',' + ('00' + Math.round(ms / 10)).slice(-2));\n\n      this.playbackRafId = requestAnimationFrame(onTick);\n    };\n\n    audio.addEventListener('play', () => {\n      this.voiceRecordingPanel?.setPlaying(true);\n      cancelAnimationFrame(this.playbackRafId);\n      this.playbackRafId = requestAnimationFrame(onTick);\n    });\n    audio.addEventListener('pause', () => {\n      this.voiceRecordingPanel?.setPlaying(false);\n      cancelAnimationFrame(this.playbackRafId);\n    });\n    audio.addEventListener('ended', () => {\n      this.voiceRecordingPanel?.setPlaying(false);\n      // Clear the progress overlay so all bars return to the active primary\n      // colour after playback — same look as the just-paused state.\n      this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n      this.voiceRecordingPanel?.setTimer(this.formatRecordingTimer(this.recordAccumulatedMs));\n      cancelAnimationFrame(this.playbackRafId);\n    });\n\n    if(seekProgress != null) {\n      const seek = () => {\n        if(audio.duration && !isNaN(audio.duration)) {\n          audio.currentTime = Math.max(0, Math.min(audio.duration, seekProgress * audio.duration));\n          this.voiceRecordingPanel?.setPlaybackProgress(seekProgress);\n          audio.removeEventListener('loadedmetadata', seek);\n        }\n      };\n      audio.addEventListener('loadedmetadata', seek);\n      seek();\n    }\n\n    audio.play().catch((err) => {\n      console.error('[ChatInput] voice playback play() error:', err);\n      this.stopPlayback();\n    });\n  }\n\n  private formatRecordingTimer(totalMs: number) {\n    const seconds = totalMs / 1000;\n    const ms = totalMs % 1000;\n    return toHHMMSS(seconds) + ',' + ('00' + Math.round(ms / 10)).slice(-2);\n  }\n\n  // The loop pauses (returns without re-scheduling) when recording is paused\n  // so we don't burn ~60 rAFs per second writing the same string to the DOM —\n  // resume() restarts it from onPauseToggleClick.\n  private startRecordingTimerLoop() {\n    const r = () => {\n      if(!this.active || this.recordPaused) return;\n      const elapsed = this.getRecordingElapsedMs();\n      const formatted = this.formatRecordingTimer(elapsed);\n      if(!this.voiceRecordingPanel?.getIsPlaying()) {\n        this.voiceRecordingPanel?.setTimer(formatted);\n      }\n      fastRaf(r);\n    };\n    r();\n  }\n\n  private stopPlayback() {\n    if(this.playbackRafId) {\n      cancelAnimationFrame(this.playbackRafId);\n      this.playbackRafId = undefined;\n    }\n    if(this.playbackAudio) {\n      try {\n        this.playbackAudio.pause();\n      } catch(e) {}\n      this.playbackAudio.src = '';\n      this.playbackAudio = undefined;\n    }\n    if(this.playbackObjectUrl) {\n      try {\n        URL.revokeObjectURL(this.playbackObjectUrl);\n      } catch(e) {}\n      this.playbackObjectUrl = undefined;\n    }\n    this.voiceRecordingPanel?.setPlaying(false);\n    this.voiceRecordingPanel?.setPlaybackProgress(undefined);\n  }\n\n  private setRecording(value: boolean) {\n    if(this.active === value) {\n      return;\n    }\n\n    this.active = value;\n    this.input.inputState.set({isRecording: value});\n    this.input.setShrinking(this.active, ['is-recording']);\n    this.input.updateSendBtn();\n    this.input.onRecording?.(value);\n  }\n\n  // Swallow the click that ends a record-button long-press (it already opened\n  // the mode-switch menu). Returns true when the click should be ignored.\n  public consumeLongPressSuppression(): boolean {\n    if(this.recordModeLongPressed) {\n      this.recordModeLongPressed = false;\n      return true;\n    }\n    return false;\n  }\n\n  public hasAnyRecorder(): boolean {\n    return !!(this.recorder || this.videoRecorder);\n  }\n\n  // Whether the voice recorder specifically is available. Drives the send\n  // button's record/send icon choice (no voice recorder ⇒ never a record icon).\n  public hasVoiceRecorder(): boolean {\n    return !!this.recorder;\n  }\n\n  // Handle the send button's recording branch: stop+send (or cancel if too\n  // short). Called by ChatInput.onBtnSendClick when a recording is active.\n  public handleSendButtonClick() {\n    if(this.getRecordingElapsedMs() < RECORD_MIN_TIME) {\n      this.onCancelRecordClick();\n    } else {\n      this.stopPlayback();\n      this.getActiveRecorder()?.stop();\n    }\n  }\n\n  // Empty input + not recording: start a recording in the active media type.\n  public startActive() {\n    this.startRecordingNow(this.getActiveRecordingMediaType());\n  }\n\n  // Whether voice ↔ video can be switched right now: only in the idle\n  // record-button state (empty field, not recording / editing / forwarding) and\n  // when both recorders exist. Shared by the record-button context menu, the\n  // desktop long-press, and the attach-menu items.\n  public canSwitchRecordingMode(): boolean {\n    return this.input.isInputEmpty() &&\n      !this.active &&\n      !this.input.forwarding &&\n      !this.input.editMsgId &&\n      !this.input.suggestedPost?.hasMedia &&\n      this.input.chat.type !== ChatType.Stories &&\n      !!this.recorder &&\n      !!this.videoRecorder;\n  }\n\n  public setRecordingMediaType(type: 'voice' | 'video') {\n    this.input.chat.setAppSettings('recordingMediaType', type);\n    this.input.updateSendBtn();\n  }\n\n  private setupRecordingModeMenu() {\n    if(!this.recorder || !this.videoRecorder) return; // nothing to switch between\n\n    const contextMenu = createContextMenu({\n      buttons: [{\n        icon: 'microphone',\n        text: 'Chat.Input.Record.Voice',\n        onClick: () => this.setRecordingMediaType('voice'),\n        verify: () => this.canSwitchRecordingMode() && this.getActiveRecordingMediaType() !== 'voice'\n      }, {\n        icon: 'recordround_filled',\n        text: 'Chat.Input.Record.Video',\n        onClick: () => this.setRecordingMediaType('video'),\n        verify: () => this.canSwitchRecordingMode() && this.getActiveRecordingMediaType() !== 'video'\n      }],\n      listenTo: this.input.btnSend,\n      listenerSetter: this.input.listenerSetter\n    });\n\n    // Desktop: hold the left mouse button on the record button (~400ms) to open\n    // the same switch menu — more discoverable than the right-click. Touch\n    // devices already get this via attachContextMenuListener (long-press →\n    // contextmenu) inside createContextMenu, so this is mouse-only.\n    if(!IS_TOUCH_SUPPORTED) {\n      let pressTimer: number;\n      const clearPressTimer = () => {\n        if(pressTimer) {\n          clearTimeout(pressTimer);\n          pressTimer = 0;\n        }\n      };\n\n      this.input.listenerSetter.add(this.input.btnSend)('mousedown', (e: MouseEvent) => {\n        this.recordModeLongPressed = false; // clear any stale flag from an aborted press\n        if(e.button !== 0 || !this.canSwitchRecordingMode()) return; // left button, idle record state\n        clearPressTimer();\n        pressTimer = window.setTimeout(() => {\n          pressTimer = 0;\n          this.recordModeLongPressed = true; // suppress the release click (see onBtnSendClick)\n          contextMenu.open(e);\n        }, 400);\n      });\n      this.input.listenerSetter.add(this.input.btnSend)('mouseup', clearPressTimer);\n      this.input.listenerSetter.add(this.input.btnSend)('mouseleave', clearPressTimer);\n    }\n  }\n\n  // The recording mode shown on the button. Locked to the active session's\n  // type while recording (so resuming / sending uses the matching recorder);\n  // otherwise driven by the persisted user preference.\n  public getActiveRecordingMediaType(): 'voice' | 'video' {\n    if(this.active) return this.recordingType;\n    const persisted = this.input.chat?.appSettings?.recordingMediaType ?? 'voice';\n    // If the persisted type isn't available on this device (e.g. no\n    // MediaRecorder support for video), silently fall back to voice.\n    if(persisted === 'video' && !this.videoRecorder) return 'voice';\n    if(persisted === 'voice' && !this.recorder) return 'video';\n    return persisted;\n  }\n\n  // Returns the recorder driving the current session (or undefined when not\n  // recording). Used by the click handler to stop+send regardless of type.\n  private getActiveRecorder(): {stop: () => void, pause?: () => void | Promise<void>, resume?: () => void, getSnapshot?: () => unknown} | undefined {\n    if(!this.active) return undefined;\n    return this.recordingType === 'video' ? this.videoRecorder : this.recorder;\n  }\n\n  private startRecordingNow(type: 'voice' | 'video') {\n    // `this.active` only flips true once start() resolves; for video that\n    // now includes waiting for the camera's first visible frame, a longer\n    // window in which a second click could kick off a duplicate recording.\n    // Guard it explicitly.\n    if(this.active || this.isStartingRecording) return;\n    if(type === 'video' && !this.videoRecorder) return;\n    if(!this.input.verifyEphemeralCommand()) return;\n    const sendingParams = this.input.chat.getMessageSendingParams();\n    this.pinnedEphemeralSendingParams = sendingParams.ephemeral ? {\n      ephemeral: true,\n      ephemeralReceiverId: sendingParams.ephemeralReceiverId,\n      peerId: sendingParams.peerId,\n      threadId: sendingParams.threadId,\n      replyToMsgId: sendingParams.replyToMsgId,\n      replyTo: sendingParams.replyTo\n    } : undefined;\n    this.isStartingRecording = true;\n    const promise = type === 'video' ? this.startVideoRecording() : this.startVoiceRecording();\n    Promise.resolve(promise).catch(() => {}).finally(() => {\n      this.isStartingRecording = false;\n    });\n  }\n\n  private async startVoiceRecording() {\n    const isAnyChat = this.input.chat.peerId.isAnyChat();\n    const isEphemeral = this.input.isEphemeralComposerMode();\n    const flag: ChatRights = 'send_voices';\n    if(!isEphemeral && isAnyChat && !(await this.input.chat.canSend(flag))) {\n      toastNew({langPackKey: POSTING_NOT_ALLOWED_MAP[flag]});\n      return;\n    }\n\n    if(!isEphemeral && await this.input.showSlowModeTooltipIfNeeded()) {\n      return;\n    }\n\n    this.input.chatInput.classList.add('is-locked');\n    blurActiveElement();\n\n    let restricted = false;\n    if(!isAnyChat) {\n      const userFull = await this.input.managers.appProfileManager.getProfile(this.input.chat.peerId.toUserId());\n      if(userFull?.pFlags.voice_messages_forbidden) {\n        toastNew({\n          langPackKey: 'Chat.SendVoice.PrivacyError',\n          langPackArguments: [await wrapPeerTitle({peerId: this.input.chat.peerId})]\n        });\n        restricted = true;\n      }\n    }\n\n    if(restricted) {\n      this.input.chatInput.classList.remove('is-locked');\n      return;\n    }\n\n    this.recordingType = 'voice';\n\n    // Record with the microphone selected in Settings → Speakers and Camera\n    // (same appSettings.callDevices source as the call stack + the video note);\n    // empty ⇒ OS default. Read fresh each time, applied to whichever recorder\n    // backs this session: NativeVoiceRecorder via its setter, or the opus-recorder\n    // fallback by setting the `config.mediaTrackConstraints` its start() reads.\n    const microphoneId = appSettings.callDevices?.microphoneId;\n    if(this.recorder.setMicrophoneId) {\n      this.recorder.setMicrophoneId(microphoneId);\n    } else if(this.recorder.config) {\n      this.recorder.config.mediaTrackConstraints = microphoneId ? {deviceId: {exact: microphoneId}} : true;\n    }\n\n    this.recorder.start().then(() => {\n      this.releaseMediaPlayback = appMediaPlaybackController.setSingleMedia();\n      this.recordCanceled = false;\n      this.recordPaused = false;\n      this.recordAccumulatedMs = 0;\n\n      this.setRecording(true);\n      this.voiceRecordingPanel?.setMode('recording');\n      this.voiceRecordingPanel?.clearPeaks();\n      opusDecodeController.setKeepAlive(true);\n\n      const showDiscardPopup = () => {\n        PopupElement.createPopup(PopupPeer, 'popup-cancel-record', {\n          titleLangKey: 'DiscardVoiceMessageTitle',\n          descriptionLangKey: 'DiscardVoiceMessageDescription',\n          buttons: [{\n            langKey: 'DiscardVoiceMessageAction',\n            callback: () => {\n              simulateClickEvent(this.input.btnCancelRecord);\n            }\n          }, {\n            langKey: 'Continue',\n            isCancel: true\n          }]\n        }).show();\n      };\n\n      this.recordingOverlayListener = this.input.listenerSetter.add(getOverlayRoot())('mousedown', (e) => {\n        if(!findUpClassName(e.target, CLASS_NAME) && !findUpClassName(e.target, 'popup-cancel-record')) {\n          cancelEvent(e);\n          showDiscardPopup();\n        }\n      }, {capture: true, passive: false}) as any;\n\n      appNavigationController.pushItem(this.recordingNavigationItem = {\n        type: 'voice',\n        onPop: () => {\n          setTimeout(() => {\n            showDiscardPopup();\n          }, 0);\n\n          return false;\n        }\n      });\n\n      this.recordStartTime = Date.now();\n\n      const sourceNode: MediaStreamAudioSourceNode = this.recorder.sourceNode;\n      this.waveformAnalyser = new VoiceWaveformAnalyser(sourceNode);\n      this.liveWaveformAnalyser = new LiveWaveformAnalyser(sourceNode);\n      this.liveWaveformAnalyser.onpeak = (peak) => {\n        this.voiceRecordingPanel?.pushPeak(peak);\n      };\n\n      this.startRecordingTimerLoop();\n    }).catch((e: Error) => {\n      switch(e.name as string) {\n        case 'NotAllowedError': {\n          toastNew({langPackKey: 'NoMicrophoneAccess'});\n          break;\n        }\n\n        case 'NotReadableError': {\n          toast(e.message);\n          break;\n        }\n\n        default:\n          console.error('Recorder start error:', e, e.name, e.message);\n          toast(e.message);\n          break;\n      }\n\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n    });\n  }\n\n  private async startVideoRecording() {\n    if(!this.videoRecorder) return;\n    const isAnyChat = this.input.chat.peerId.isAnyChat();\n    const isEphemeral = this.input.isEphemeralComposerMode();\n    // Round video notes go through the same restriction set as voice (the\n    // server-side flag is shared; clients gate on `send_voices`).\n    const flag: ChatRights = 'send_voices';\n    if(!isEphemeral && isAnyChat && !(await this.input.chat.canSend(flag))) {\n      toastNew({langPackKey: POSTING_NOT_ALLOWED_MAP[flag]});\n      return;\n    }\n\n    if(!isEphemeral && await this.input.showSlowModeTooltipIfNeeded()) {\n      return;\n    }\n\n    this.input.chatInput.classList.add('is-locked');\n    blurActiveElement();\n\n    this.recordingType = 'video';\n\n    // Record with the camera + microphone the user selected in Settings →\n    // Speakers and Camera (the same appSettings.callDevices source the call\n    // stack reads); empty string ⇒ OS default. Read fresh each time so a change\n    // in settings takes effect on the next recording.\n    this.videoRecorder.setDeviceIds(appSettings.callDevices?.cameraId, appSettings.callDevices?.microphoneId);\n\n    try {\n      await this.videoRecorder.start();\n    } catch(e) {\n      const err = e as Error;\n      switch(err.name) {\n        case 'NotAllowedError':\n          toastNew({langPackKey: 'NoMicrophoneAccess'});\n          break;\n        case 'NotReadableError':\n          toast(err.message);\n          break;\n        default:\n          console.error('VideoRecorder start error:', err);\n          // err.message is empty for some errors (OverconstrainedError /\n          // NotFoundError) — fall back to the name so the toast isn't blank.\n          toast(err.message || err.name);\n          break;\n      }\n      this.setRecording(false);\n      this.input.chatInput.classList.remove('is-locked');\n      return;\n    }\n\n    this.releaseMediaPlayback = appMediaPlaybackController.setSingleMedia();\n    this.recordCanceled = false;\n    this.recordPaused = false;\n    this.recordAccumulatedMs = 0;\n    this.videoLimitReached = false;\n\n    // The recording bar is the regular voice panel, IN PLACE in the chat input.\n    // We just drive it for video; the only video-specific UI is the centered\n    // round preview (videoRecordingPanel).\n    this.setRecording(true);\n    this.voiceRecordingPanel?.setMode('recording');\n    this.voiceRecordingPanel?.clearPeaks();\n    this.videoRecordingPanel?.setProgress(0);\n\n    // Pipe the live camera into the 360x360 preview and reveal the circle only\n    // once the first frame is actually painted — revealing immediately would\n    // fade in a black circle while the camera spins up.\n    this.videoRecordingPanel?.startLivePreview(this.videoRecorder.stream);\n\n    // Live waveform: tap the captured audio track through a throwaway\n    // AudioContext (MediaRecorder gives us no PCM). Mirror the voice flow —\n    // feed normalized peaks into the (shared) voice panel's waveform.\n    this.setupVideoWaveform();\n\n    const showDiscardPopup = () => {\n      PopupElement.createPopup(PopupPeer, 'popup-cancel-record', {\n        titleLangKey: 'DiscardVoiceMessageTitle',\n        descriptionLangKey: 'DiscardVoiceMessageDescription',\n        buttons: [{\n          langKey: 'DiscardVoiceMessageAction',\n          callback: () => {\n            simulateClickEvent(this.input.btnCancelRecord);\n          }\n        }, {\n          langKey: 'Continue',\n          isCancel: true\n        }]\n      }).show();\n    };\n\n    this.recordingOverlayListener = this.input.listenerSetter.add(getOverlayRoot())('mousedown', (e) => {\n      // Same dismiss-on-outside-click guard as voice — clicks inside the chat\n      // input or the discard popup are allowed; everything else opens the\n      // discard confirmation.\n      if(\n        !findUpClassName(e.target, CLASS_NAME) &&\n        !findUpClassName(e.target, 'popup-cancel-record') &&\n        !findUpClassName(e.target, 'video-recording-stage') // clicking the preview circle isn't \"outside\"\n      ) {\n        cancelEvent(e);\n        showDiscardPopup();\n      }\n    }, {capture: true, passive: false}) as any;\n\n    appNavigationController.pushItem(this.recordingNavigationItem = {\n      type: 'voice',\n      onPop: () => {\n        setTimeout(() => {\n          showDiscardPopup();\n        }, 0);\n\n        return false;\n      }\n    });\n\n    this.recordStartTime = Date.now();\n    this.startVideoRecordingTimerLoop();\n  }\n\n  // Opens an AudioContext on the recording stream's audio track and routes it\n  // through the same analysers the voice flow uses, feeding the (shared) voice\n  // panel waveform. Torn down in teardownVideoWaveform (on stop). Best-effort —\n  // a waveform failure must not break the recording.\n  private setupVideoWaveform() {\n    if(!this.videoRecorder?.stream || !this.voiceRecordingPanel) return;\n    const audioTracks = this.videoRecorder.stream.getAudioTracks();\n    if(!audioTracks.length) return;\n    try {\n      this.videoAudioContext = new AudioContext();\n      // Created after `await getUserMedia`, i.e. outside the original click\n      // gesture, so it may start suspended — without resuming, the\n      // ScriptProcessor never fires and the waveform stays flat.\n      if(this.videoAudioContext.state === 'suspended') {\n        this.videoAudioContext.resume().catch(() => {});\n      }\n      // Tap a CLONE of the audio track, not the one MediaRecorder is recording.\n      // Sharing the single track between MediaRecorder and a Web Audio source\n      // makes one of them read silence (flat waveform + soundless recording);\n      // an independent clone feeds both with real audio.\n      this.videoWaveformStream = new MediaStream([audioTracks[0].clone()]);\n      const source = this.videoAudioContext.createMediaStreamSource(this.videoWaveformStream);\n      // Full-recording peaks for the frozen pause view, live peaks for the\n      // scrolling bars — same pair the voice recorder wires up.\n      this.waveformAnalyser = new VoiceWaveformAnalyser(source);\n      this.liveWaveformAnalyser = new LiveWaveformAnalyser(source);\n      this.liveWaveformAnalyser.onpeak = (peak) => {\n        if(this.recordingType === 'video') this.voiceRecordingPanel?.pushPeak(peak);\n      };\n    } catch(e) {\n      console.error('[ChatInput] video waveform setup error:', e);\n    }\n  }\n\n  private teardownVideoWaveform() {\n    this.teardownLiveWaveform();\n    if(this.waveformAnalyser) {\n      this.waveformAnalyser.finish();\n      this.waveformAnalyser = undefined;\n    }\n    if(this.videoWaveformStream) {\n      this.videoWaveformStream.getTracks().forEach((t) => t.stop());\n      this.videoWaveformStream = undefined;\n    }\n    if(this.videoAudioContext) {\n      const ctx = this.videoAudioContext;\n      this.videoAudioContext = undefined;\n      if(ctx.state !== 'closed') ctx.close().catch(() => {});\n    }\n  }\n\n  // Snapshot the current round-preview frame as a JPEG poster for the optimistic\n  // message. Must be called while the camera is still live (we keep it alive\n  // through the stop fade-out).\n  private async captureVideoPoster(): Promise<{blob: Blob, size: MediaSize} | undefined> {\n    const v = this.videoRecordingPanel?.previewVideo;\n    if(!v || !v.videoWidth || !v.videoHeight) return undefined;\n    try {\n      const poster = await createPosterFromMedia(v);\n      if(!poster?.blob) return undefined;\n      return {blob: poster.blob, size: poster.size};\n    } catch(e) {\n      return undefined;\n    }\n  }\n\n  private onVideoPlaybackSeek(progress: number) {\n    const video = this.videoRecordingPanel?.previewVideo;\n    if(!video) return;\n    const seekTo = () => {\n      const dur = this.getVideoPreviewDurationSec();\n      if(!dur) return;\n      video.currentTime = Math.max(0, Math.min(dur, progress * dur));\n      this.voiceRecordingPanel?.setPlaybackProgress(progress);\n      this.videoRecordingPanel?.setProgress(progress);\n    };\n    // No preview mounted yet (still showing the live camera) — start playback\n    // and seek once it's loaded.\n    if(video.srcObject || !video.src) {\n      this.startVideoPlaybackFromSnapshot();\n      const onMeta = () => {\n        seekTo();\n        video.removeEventListener('loadedmetadata', onMeta);\n      };\n      video.addEventListener('loadedmetadata', onMeta);\n      return;\n    }\n    seekTo();\n    if(video.paused) video.play().catch(() => {});\n  }\n\n  public destroy() {\n    // The round-preview element lives on <body>, outside the input subtree, so\n    // tear it down explicitly. Also release the camera in case a recording (or\n    // its warm-up) is still in flight.\n    this.teardownVideoWaveform();\n    // stopVideoPlayback before the panel goes away: cancels the playback rAF and\n    // revokes videoPlaybackObjectUrl (it reads videoRecordingPanel.previewVideo).\n    this.stopVideoPlayback();\n    this.videoRecorder?.releaseStream();\n    // A recording in flight pushed a navigation item with an onPop discard popup;\n    // drop it so it doesn't linger / fire after the chat is gone.\n    if(this.recordingNavigationItem) {\n      appNavigationController.removeItem(this.recordingNavigationItem);\n      this.recordingNavigationItem = undefined;\n    }\n    this.videoRecordingPanel?.destroy();\n    this.videoRecordingPanel = undefined;\n  }\n}\n","import appDownloadManager from '@lib/appDownloadManager';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport {getEmojiToneIndex} from '@vendor/emoji';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {getMiddleware} from '@helpers/middleware';\nimport {saveLottiePreviewFromPlayer} from '@helpers/saveLottiePreview';\n\nexport default function preloadAnimatedEmojiSticker(emoji: string, width?: number, height?: number) {\n  return rootScope.managers.appStickersManager.preloadAnimatedEmojiSticker(emoji).then(({doc}) => {\n    if(!doc) {\n      return;\n    }\n\n    return appDownloadManager.downloadMedia({media: doc})\n    .then(async(blob) => {\n      const mediaSize = mediaSizes.active.emojiSticker;\n      const toneIndex = getEmojiToneIndex(emoji);\n      const middlewareHelper = getMiddleware();\n      const animation = await lottieLoader.loadAnimationWorker({\n        container: undefined,\n        animationData: blob,\n        width: width ?? mediaSize.width,\n        height: height ?? mediaSize.height,\n        name: 'doc' + doc.id,\n        autoplay: false,\n        loop: false,\n        toneIndex,\n        group: 'none',\n        middleware: middlewareHelper.get()\n      });\n\n      animation.addEventListener('firstFrame', () => {\n        saveLottiePreviewFromPlayer(doc, animation, toneIndex).finally(() => {\n          middlewareHelper.destroy();\n        });\n      }, {once: true});\n    });\n  });\n}\n","import indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport LazyLoadQueueIntersector, {LazyLoadElement} from '@components/lazyLoadQueueIntersector';\nimport VisibilityIntersector, {OnVisibilityChange} from '@components/visibilityIntersector';\n\nexport default class LazyLoadQueueRepeat extends LazyLoadQueueIntersector {\n  private elementsMap: Map<HTMLElement, LazyLoadElement> = new Map();\n\n  constructor(\n    parallelLimit?: number,\n    protected onVisibilityChange?: OnVisibilityChange,\n    options?: IntersectionObserverInit\n  ) {\n    super(parallelLimit);\n\n    this.intersector = new VisibilityIntersector((item) => {\n      const {target, visible} = item;\n\n      const queueItem = this.elementsMap.get(target);\n      queueItem.visible = visible;\n\n      if(visible) {\n        queueItem.wasSeen = true;\n        if(!this.queue.includes(queueItem)) {\n          this.queue.push(queueItem);\n        }\n      } else {\n        indexOfAndSplice(this.queue, queueItem);\n      }\n\n      this.onVisibilityChange?.(item);\n      this.setProcessQueueTimeout();\n    }, options);\n  }\n\n  public clear() {\n    super.clear();\n    this.elementsMap.clear();\n  }\n\n  /* public async processItem(item: LazyLoadElement) {\n    //await super.processItem(item);\n    await LazyLoadQueueBase.prototype.processItem.call(this, item);\n\n    if(this.lazyLoadMedia.length) {\n      this.processQueue();\n    }\n  } */\n\n  public observe(el: LazyLoadElement) {\n    this.elementsMap.set(el.div, el);\n    super.observe(el);\n  }\n\n  public unobserve(el: LazyLoadElement) {\n    this.elementsMap.delete(el.div);\n    super.unobserve(el);\n  }\n}\n","import mediaSizes from '@helpers/mediaSizes';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport LazyLoadQueueRepeat from '@components/lazyLoadQueueRepeat';\nimport wrapSticker from '@components/wrappers/sticker';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\n\nexport default class SuperStickerRenderer {\n  public lazyLoadQueue: LazyLoadQueueRepeat;\n  private animated: Set<HTMLElement> = new Set();\n  private regularLazyLoadQueue: LazyLoadQueue;\n  private group: AnimationItemGroup;\n  private managers: AppManagers;\n  private intersectionObserverInit: IntersectionObserverInit;\n  private visibleRenderOptions: Partial<Parameters<typeof wrapSticker>[0]>;\n  private withLock: boolean\n  private playOnHover: boolean\n\n  constructor(options: {\n    regularLazyLoadQueue: LazyLoadQueue;\n    group: AnimationItemGroup;\n    managers: AppManagers;\n    intersectionObserverInit?: SuperStickerRenderer['intersectionObserverInit'];\n    visibleRenderOptions?: SuperStickerRenderer['visibleRenderOptions'];\n    withLock?: boolean\n    playOnHover?: boolean\n  }) {\n    options.withLock ??= true;\n    safeAssign(this, options);\n\n    this.lazyLoadQueue = new LazyLoadQueueRepeat(undefined, ({target, visible}) => {\n      if(!visible) {\n        this.processInvisible(target);\n      }\n    }, this.intersectionObserverInit);\n  }\n\n  public clear() {\n    this.lazyLoadQueue.clear();\n    this.animated.forEach((element) => {\n      element.middlewareHelper?.destroy();\n    });\n    this.animated.clear();\n  }\n\n  public destroy() {\n    this.clear();\n  }\n\n  public renderSticker(\n    doc: MyDocument,\n    element?: HTMLElement,\n    loadPromises?: Promise<any>[],\n    middleware?: Middleware\n  ) {\n    if(!element) {\n      element = document.createElement('div');\n      element.classList.add('grid-item', 'super-sticker');\n      element.dataset.docId = '' + doc.id;\n\n      if(doc.animated) {\n        this.observeAnimated(element);\n      }\n    }\n\n    element.middlewareHelper ??= middleware ? middleware.create() : getMiddleware();\n\n    // * This will wrap only a thumb\n    /* !doc.animated &&  */ wrapSticker({\n      doc,\n      div: element,\n      lazyLoadQueue: this.regularLazyLoadQueue,\n      group: this.group,\n      onlyThumb: doc.animated,\n      loadPromises,\n      middleware: element.middlewareHelper.get(),\n      ...(doc.animated ? {} : this.visibleRenderOptions || {})\n    });\n\n    if(this.playOnHover) {\n      element.addEventListener('mouseenter', () => {\n        const renderer = this.rendererByElement.get(element);\n        if(renderer && 'playOrRestart' in renderer) {\n          renderer.playOrRestart()\n        }\n      })\n    }\n\n    return element;\n  }\n\n  public observeAnimated(element: HTMLElement) {\n    this.animated.add(element);\n    this.lazyLoadQueue.observe({\n      div: element,\n      load: this.processVisible\n    });\n  }\n\n  public unobserveAnimated(element: HTMLElement) {\n    element.middlewareHelper?.destroy();\n    this.animated.delete(element);\n    this.lazyLoadQueue.delete({div: element});\n  }\n\n  public deleteSticker(element: HTMLElement) {\n    return this.unobserveAnimated(element);\n  }\n\n  private checkAnimationContainer = (element: HTMLElement, visible: boolean) => {\n    // console.error('checkAnimationContainer', div, visible);\n    const players = animationIntersector.getAnimations(element);\n    players.forEach((player) => {\n      if(!visible) {\n        animationIntersector.removeAnimation(player);\n      } else {\n        animationIntersector.checkAnimation(player, false);\n      }\n    });\n  };\n\n  private rendererByElement = new WeakMap<HTMLElement, Awaited<Awaited<ReturnType<typeof wrapSticker>>['render']>>();\n  private processVisible = async(element: HTMLElement) => {\n    const docId = element.dataset.docId;\n    const doc = await this.managers.appDocsManager.getDoc(docId);\n\n    const size = mediaSizes.active.esgSticker.width;\n\n    element.middlewareHelper ??= getMiddleware();\n    element.middlewareHelper.clean();\n\n    // console.log('processVisibleDiv:', element);\n    const promise = wrapSticker({\n      doc,\n      div: element,\n      width: size,\n      height: size,\n      lazyLoadQueue: null,\n      group: this.group,\n      onlyThumb: false,\n      play: true,\n      loop: true,\n      withLock: this.withLock,\n      middleware: element.middlewareHelper.get(),\n      ...(this.visibleRenderOptions || {})\n    }).then(({render}) => render);\n\n    promise.then(() => {\n      // clearTimeout(timeout);\n      this.checkAnimationContainer(element, this.lazyLoadQueue.intersector.isVisible(element));\n    }, noop);\n\n    if(this.playOnHover) {\n      promise.then(renderer => {\n        this.rendererByElement.set(element, renderer);\n      });\n    }\n\n    /* let timeout = window.setTimeout(() => {\n      console.error('processVisibleDiv timeout', div, doc);\n    }, 1e3); */\n    return promise;\n  };\n\n  public processInvisible = async(element: HTMLElement) => {\n    const docId = element.dataset.docId;\n    const doc = await this.managers.appDocsManager.getDoc(docId);\n\n    // the await above is a real worker round-trip - the cell may be back on\n    // screen; demolishing it now would yank a live canvas (visible blink).\n    // Bail and leave the old player alive - the visible flip that brought the\n    // cell back already queued processVisible, which cleans and re-wraps. The\n    // dropdown 'closed' sweep clears visibility synchronously before these\n    // continuations run, so it still demolishes hidden cells.\n    if(this.lazyLoadQueue.intersector.isVisible(element)) {\n      return;\n    }\n\n    // console.log('STICKER INvisible:', /* div,  */docId);\n    this.checkAnimationContainer(element, false);\n\n    element.middlewareHelper?.clean();\n    // no replaceChildren - the thumb re-wrap adopts the dead canvas (pixels\n    // retained) as its bottom layer and retires it only under the decoded\n    // preview img (replacePreviousMedia), so a mis-timed demolition can never\n    // produce an empty/silhouette frame\n    this.renderSticker(doc, element as HTMLDivElement);\n  };\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {simulateClickEvent, attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport safePlay from '@helpers/dom/safePlay';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport {doubleRaf} from '@helpers/schedulers';\nimport pause from '@helpers/schedulers/pause';\nimport windowSize from '@helpers/windowSize';\nimport {DocumentAttribute} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport getStickerEffectThumb from '@appManagers/utils/stickers/getStickerEffectThumb';\nimport CustomEmojiElement from '@lib/customEmoji/element';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport {EMOJI_TEXT_COLOR} from '@components/emoticonsDropdown';\nimport SetTransition from '@components/singleTransition';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {STICKER_EFFECT_MULTIPLIER} from '@components/wrappers/sticker';\nimport wrapVideo from '@components/wrappers/video';\n\nlet hasViewer = false;\nexport default function attachStickerViewerListeners({listenTo, listenerSetter, selector, findTarget: originalFindTarget, getTextColor, additionalClass}: {\n  additionalClass?: string,\n  listenerSetter: ListenerSetter,\n  listenTo: HTMLElement,\n  selector?: string,\n  findTarget?: (e: MouseEvent) => HTMLElement,\n  getTextColor?: () => string\n}) {\n  if(IS_TOUCH_SUPPORTED) {\n    return;\n  }\n\n  const findTarget = (e: MouseEvent, checkForParent?: boolean) => {\n    let el: HTMLElement;\n    if(originalFindTarget) el = originalFindTarget(e);\n    else {\n      const s = selector || '.media-sticker-wrapper, .media-gif-wrapper';\n      el = (e.target as HTMLElement).closest(s) as HTMLElement;\n    }\n\n    return el && (!checkForParent || findUpAsChild(el, listenTo)) ? el : undefined;\n  };\n\n  const managers = rootScope.managers;\n\n  listenerSetter.add(listenTo)('mousedown', (e) => {\n    if(hasViewer || e.buttons > 1 || e.button !== 0) return;\n    let mediaContainer = findTarget(e);\n    if(!mediaContainer) {\n      return;\n    }\n\n    // const img: HTMLImageElement = mediaContainer.querySelector('img.media-sticker');\n\n    const docId = mediaContainer.dataset.docId;\n    if(!docId) {\n      return;\n    }\n\n    // The whole hold-drag-release gesture is tracked on document-level mousemove/mouseup + a post-\n    // release click-swallow, and timed by setTimeout/setInterval — all of which must use whichever\n    // window the app currently lives in (the tab, or the Document PiP window). Bound to the MAIN\n    // window, the viewer opens on hold but its mouseup/mousemove fire on the PiP document and never\n    // arrive, so it sticks open and can't switch stickers.\n    const activeWindow = getAppWindow();\n    const activeDocument = activeWindow.document;\n\n    const className = 'sticker-viewer';\n    const group: AnimationItemGroup = 'STICKER-VIEWER';\n    const openDuration = 200;\n    const switchDuration = 200;\n    const previousGroup = animationIntersector.getOnlyOnePlayableGroup();\n    const _middleware = getMiddleware();\n    let container: HTMLElement,\n      previousTransformer: HTMLElement,\n      isMouseUp = false;\n\n    const doThatSticker = async({mediaContainer, doc, middleware, lockGroups, isSwitching}: {\n      mediaContainer: HTMLElement,\n      doc: MyDocument,\n      middleware: Middleware,\n      lockGroups?: boolean,\n      isSwitching?: boolean\n    }) => {\n      const isGif = doc.type === 'gif';\n      const effectThumb = isGif ? undefined : getStickerEffectThumb(doc);\n      const mediaRect: DOMRect = mediaContainer.getBoundingClientRect();\n      const s = makeMediaSize(doc.w, doc.h);\n      const size = effectThumb ? 280 : (isGif ? Math.min(480, windowSize.height - 200) : 360);\n      const boxSize = makeMediaSize(size, size);\n      const fitted = mediaRect.width === mediaRect.height ? boxSize : s.aspectFitted(boxSize);\n\n      const bubble = findUpClassName(mediaContainer, 'bubble');\n      const isOut = bubble ? bubble.classList.contains('is-out') : true;\n\n      const transformer = document.createElement('div');\n      transformer.classList.add(className + '-transformer');\n      transformer.middlewareHelper = middleware.create();\n      middleware = transformer.middlewareHelper.get();\n\n      const stickerContainer = document.createElement('div');\n      stickerContainer.classList.add(className + '-sticker');\n      /* transformer.style.width =  */stickerContainer.style.width = fitted.width + 'px';\n      /* transformer.style.height =  */stickerContainer.style.height = fitted.height + 'px';\n\n      const viewerEmoji = mediaContainer.dataset.stickerEmoji || doc.stickerEmojiRaw;\n      const stickerEmoji = document.createElement('div');\n      stickerEmoji.classList.add(className + '-emoji');\n      stickerEmoji.append(wrapEmojiText(viewerEmoji));\n\n      if(effectThumb) {\n        const margin = (size * STICKER_EFFECT_MULTIPLIER - size) / 3 * (isOut ? 1 : -1);\n        transformer.classList.add('has-effect');\n        // const property = `--margin-${isOut ? 'right' : 'left'}`;\n        // stickerContainer.style.setProperty(property, `${margin * 2}px`);\n        transformer.style.setProperty('--translateX', `${margin}px`);\n        stickerEmoji.style.setProperty('--translateX', `${-margin}px`);\n      }\n\n      const overflowElement = findUpClassName(mediaContainer, 'scrollable');\n      const visibleRect = getVisibleRect(mediaContainer, overflowElement, true, mediaRect);\n      if(visibleRect.overflow.vertical || visibleRect.overflow.horizontal) {\n        stickerContainer.classList.add('is-overflow');\n      }\n\n      // if(img) {\n      //   const ratio = img.naturalWidth / img.naturalHeight;\n      //   if((mediaRect.width / mediaRect.height).toFixed(1) !== ratio.toFixed(1)) {\n\n      //     mediaRect = mediaRect.toJSON();\n      //   }\n      // }\n\n      const rect = mediaContainer.getBoundingClientRect();\n      const scaleX = rect.width / fitted.width;\n      const scaleY = rect.height / fitted.height;\n      const transformX = rect.left - (windowSize.width - rect.width) / 2;\n      const transformY = rect.top - (windowSize.height - rect.height) / 2;\n      transformer.style.transform = `translate(${transformX}px, ${transformY}px) scale(${scaleX}, ${scaleY})`;\n      if(isSwitching) transformer.classList.add('is-switching', 'forwards');\n      transformer.append(stickerContainer, stickerEmoji);\n      container.append(transformer);\n\n      const attribute = doc.attributes.find((attribute) => attribute._ === 'documentAttributeCustomEmoji') as DocumentAttribute.documentAttributeCustomEmoji;\n\n      const o = isGif ? await wrapVideo({\n        doc,\n        container: stickerContainer,\n        group,\n        boxWidth: fitted.width,\n        boxHeight: fitted.height,\n        canAutoplay: true,\n        middleware,\n        noInfo: true\n        // noPreview: true\n      }).then(async(res) => (await res.loadPromise, res.video)) : await wrapSticker({\n        doc,\n        div: stickerContainer,\n        group,\n        width: fitted.width,\n        height: fitted.height,\n        play: false,\n        loop: true,\n        middleware,\n        managers,\n        needFadeIn: false,\n        isOut,\n        emoji: attribute ? undefined : viewerEmoji,\n        withThumb: false,\n        relativeEffect: true,\n        loopEffect: true,\n        textColor: attribute && attribute.pFlags.text_color ? getTextColor?.() || EMOJI_TEXT_COLOR : undefined\n      }).then(({render}) => render);\n      if(!middleware()) return;\n\n      if(!container.parentElement) {\n        getOverlayRoot().append(container);\n      }\n\n      const player = Array.isArray(o) ? o[0] : o;\n\n      const firstFramePromise = player instanceof LottiePlayer ?\n        new Promise<void>((resolve) => player.addEventListener('firstFrame', resolve, {once: true})) :\n        Promise.resolve();\n      await Promise.all([firstFramePromise, doubleRaf()]);\n      await pause(0); // ! need it because firstFrame will be called just from the loop\n      if(!middleware()) return;\n\n      if(lockGroups) {\n        animationIntersector.setOnlyOnePlayableGroup(group);\n        animationIntersector.checkAnimations2(true);\n      }\n\n      if(player instanceof LottiePlayer) {\n        const prevPlayer = mediaContainer instanceof CustomEmojiElement ?\n          mediaContainer.player as LottiePlayer :\n          lottieLoader.getAnimation(mediaContainer);\n        if(prevPlayer) {\n          player.curFrame = prevPlayer.curFrame;\n          player.play();\n          await new Promise<void>((resolve) => {\n            let i = 0;\n            const c = () => {\n              if(++i === 2) {\n                resolve();\n                player.removeEventListener('enterFrame', c);\n              }\n            };\n\n            player.addEventListener('enterFrame', c);\n          });\n          if(!middleware()) return;\n          player.pause();\n        }\n      } else if(player instanceof HTMLVideoElement) {\n        const prevPlayer = mediaContainer.querySelector<HTMLVideoElement>('video');\n        if(prevPlayer) {\n          player.currentTime = prevPlayer.currentTime;\n        }\n      }\n\n      return {\n        ready: () => {\n          if(player instanceof LottiePlayer || player instanceof HTMLVideoElement) {\n            safePlay(player);\n          }\n\n          if(effectThumb) {\n            simulateClickEvent(stickerContainer);\n          }\n        },\n        transformer\n      };\n    };\n\n    const timeout = activeWindow.setTimeout(async() => {\n      activeDocument.removeEventListener('mousemove', onMousePreMove);\n\n      container = document.createElement('div');\n      container.classList.add(className, additionalClass);\n      hasViewer = true;\n\n      const middleware = _middleware.get();\n      const doc = await managers.appDocsManager.getDoc(docId);\n      if(!middleware()) return;\n\n      let result: Awaited<ReturnType<typeof doThatSticker>>;\n      try {\n        result = await doThatSticker({\n          doc,\n          mediaContainer,\n          middleware,\n          lockGroups: true\n        });\n        if(!result) return;\n      } catch(err) {\n        return;\n      }\n\n      // * can't use middleware here\n      if(isMouseUp) {\n        return;\n      }\n\n      const {ready, transformer} = result;\n\n      previousTransformer = transformer;\n\n      SetTransition({\n        element: container,\n        className: 'is-visible',\n        forwards: true,\n        duration: openDuration,\n        onTransitionEnd: () => {\n          if(!middleware()) return;\n          ready();\n        }\n      });\n\n      activeDocument.addEventListener('mousemove', onMouseMove);\n    }, 125);\n\n    const onMouseMove = async(e: MouseEvent) => {\n      const newMediaContainer = findTarget(e, true);\n      if(!newMediaContainer || mediaContainer === newMediaContainer) {\n        return;\n      }\n\n      const docId = newMediaContainer.dataset.docId;\n      if(!docId) {\n        return;\n      }\n\n      mediaContainer = newMediaContainer;\n      _middleware.clean();\n      const middleware = _middleware.get();\n\n      const doc = await managers.appDocsManager.getDoc(docId);\n      if(!middleware()) return;\n\n      let r: Awaited<ReturnType<typeof doThatSticker>>;\n      try {\n        r = await doThatSticker({\n          doc,\n          mediaContainer,\n          middleware,\n          isSwitching: true\n        });\n        if(!r) return;\n      } catch(err) {\n        console.error('sticker viewer error', err);\n        return;\n      }\n\n      const {ready, transformer} = r;\n\n      const _previousTransformer = previousTransformer;\n      SetTransition({\n        element: _previousTransformer,\n        className: 'is-switching',\n        forwards: true,\n        duration: switchDuration,\n        onTransitionEnd: () => {\n          _previousTransformer.remove();\n          _previousTransformer.middlewareHelper.destroy();\n        }\n      });\n\n      previousTransformer = transformer;\n\n      SetTransition({\n        element: transformer,\n        className: 'is-switching',\n        forwards: false,\n        duration: switchDuration,\n        onTransitionEnd: () => {\n          if(!middleware()) return;\n          ready();\n        }\n      });\n    };\n\n    const onMousePreMove = (e: MouseEvent) => {\n      if(!findUpAsChild(e.target as HTMLElement, mediaContainer)) {\n        onMouseUp();\n      }\n    };\n\n    const onMouseUp = () => {\n      isMouseUp = true;\n      activeWindow.clearTimeout(timeout);\n      activeWindow.clearInterval(unmountInterval);\n      // _middleware.clean();\n\n      if(container) {\n        SetTransition({\n          element: container,\n          className: 'is-visible',\n          forwards: false,\n          duration: openDuration,\n          onTransitionEnd: () => {\n            container.remove();\n            animationIntersector.setOnlyOnePlayableGroup(previousGroup);\n            animationIntersector.checkAnimations2(false);\n            _middleware.destroy();\n            hasViewer = false;\n          }\n        });\n\n        attachClickEvent(activeDocument.body, cancelEvent, {capture: true, once: true});\n      }\n\n      activeDocument.removeEventListener('mousemove', onMousePreMove);\n      activeDocument.removeEventListener('mousemove', onMouseMove);\n      activeDocument.removeEventListener('mouseup', onMouseUp, {capture: true});\n    };\n\n    activeDocument.addEventListener('mousemove', onMousePreMove);\n    activeDocument.addEventListener('mouseup', onMouseUp, {once: true, capture: true});\n    const unmountInterval = activeWindow.setInterval(() => {\n      if(!isInDOM(mediaContainer)) {\n        onMouseUp();\n      }\n    }, 100);\n  });\n}\n","import fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\ntype ArrowKey = 'ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight';\nconst HANDLE_EVENT = 'keydown';\nconst ACTIVE_CLASS_NAME = 'active';\n\nconst AXIS_Y_KEYS: ArrowKey[] = ['ArrowUp', 'ArrowDown'];\nconst AXIS_X_KEYS: ArrowKey[] = ['ArrowLeft', 'ArrowRight'];\n\nconst PROPERTY_NEXT = 'nextElementSibling';\nconst PROPERTY_PREV = 'previousElementSibling';\nconst PROPERTY_FIRST = 'firstElementChild';\nconst PROPERTY_LAST = 'lastElementChild';\n\nexport type ListNavigationOptions = {\n  list: HTMLElement,\n  type: 'xy' | 'x' | 'y',\n  onSelect: (target: Element) => void | boolean | Promise<boolean>,\n  once?: boolean,\n  waitForKey?: string[],\n  activeClassName?: string,\n  cancelMouseDown?: boolean,\n  target?: Element\n};\n\nexport default function attachListNavigation({\n  list,\n  type,\n  onSelect,\n  once,\n  waitForKey,\n  activeClassName = ACTIVE_CLASS_NAME,\n  cancelMouseDown,\n  target\n}: ListNavigationOptions) {\n  let waitForKeySet = waitForKey?.length ? new Set(waitForKey) : undefined;\n  const keyNames = new Set(type === 'xy' ? AXIS_Y_KEYS.concat(AXIS_X_KEYS) : (type === 'x' ? AXIS_X_KEYS : AXIS_Y_KEYS));\n\n  const getCurrentTarget = () => {\n    return target || list.querySelector('.' + activeClassName) || list[PROPERTY_FIRST];\n  };\n\n  const setCurrentTarget = (_target: Element, scrollTo: boolean) => {\n    if(target === _target) {\n      return;\n    }\n\n    let hadTarget = false;\n    if(target) {\n      hadTarget = true;\n      target.classList.remove(activeClassName);\n    }\n\n    target = _target;\n    if(!target) return;\n    target.classList.add(activeClassName);\n\n    if(hadTarget && scrollable && scrollTo) {\n      fastSmoothScroll({\n        container: scrollable,\n        element: target as HTMLElement,\n        position: 'center',\n        forceDuration: 100,\n        axis: type === 'x' ? 'x' : 'y'\n      });\n    }\n  };\n\n  const getNextTargetX = (currentTarget: Element, isNext: boolean): Element => {\n    let nextTarget: Element;\n    if(isNext) nextTarget = currentTarget[PROPERTY_NEXT] || list[PROPERTY_FIRST];\n    else nextTarget = currentTarget[PROPERTY_PREV] || list[PROPERTY_LAST];\n\n    return nextTarget;\n  };\n\n  const getNextTargetY = (currentTarget: Element, isNext: boolean) => {\n    const property = isNext ? PROPERTY_NEXT : PROPERTY_PREV;\n    const endProperty = isNext ? PROPERTY_FIRST : PROPERTY_LAST;\n    const currentRect = currentTarget.getBoundingClientRect();\n\n    let nextTarget = currentTarget[property] || list[endProperty];\n    while(nextTarget !== currentTarget) {\n      const targetRect = nextTarget.getBoundingClientRect();\n      if(targetRect.x === currentRect.x && targetRect.y !== currentRect.y) {\n        break;\n      }\n\n      nextTarget = nextTarget[property] || list[endProperty];\n    }\n\n    return nextTarget;\n  };\n\n  let handleArrowKey: (currentTarget: Element, key: ArrowKey) => Element;\n  if(type === 'xy') { // flex-direction: row; flex-wrap: wrap;\n    handleArrowKey = (currentTarget, key) => {\n      if(key === 'ArrowUp' || key === 'ArrowDown') return getNextTargetY(currentTarget, key === 'ArrowDown');\n      else return getNextTargetX(currentTarget, key === 'ArrowRight');\n    };\n  } else { // flex-direction: row | column;\n    handleArrowKey = (currentTarget, key) => getNextTargetX(currentTarget, key === 'ArrowRight' || key === 'ArrowDown');\n  }\n\n  let onKeyDown = (e: KeyboardEvent) => {\n    const key = e.key;\n    if(!keyNames.has(key as any)) {\n      if(key === 'Enter' || (type !== 'xy' && key === 'Tab')) {\n        cancelEvent(e);\n        fireSelect(getCurrentTarget());\n      }\n\n      return;\n    }\n\n    cancelEvent(e);\n\n    if(list.childElementCount > 1) {\n      let currentTarget = getCurrentTarget();\n      currentTarget = handleArrowKey(currentTarget, key as any);\n      setCurrentTarget(currentTarget, true);\n    }\n  };\n\n  const scrollable = findUpClassName(list, 'scrollable');\n  list.classList.add('navigable-list');\n\n  const onMouseMove = (e: MouseEvent) => {\n    const target = findUpAsChild(e.target as HTMLElement, list) as HTMLElement;\n    if(!target) {\n      return;\n    }\n\n    setCurrentTarget(target, false);\n  };\n\n  const onClick = (e: Event) => {\n    cancelEvent(e); // cancel keyboard closening\n\n    const target = findUpAsChild(e.target as HTMLElement, list) as HTMLElement;\n    if(!target) {\n      return;\n    }\n\n    setCurrentTarget(target, false);\n    fireSelect(getCurrentTarget());\n  };\n\n  const fireSelect = async(target: Element) => {\n    const canContinue = await onSelect(target);\n    if(canContinue !== undefined ? !canContinue : once) {\n      detach();\n    }\n  };\n\n  let attached = false, detachClickEvent: () => void;\n  const attach = () => {\n    if(attached) return;\n    attached = true;\n    // const input = document.activeElement as HTMLElement;\n    // input.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n    document.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n    list.addEventListener('mousemove', onMouseMove, {passive: true});\n    if(cancelMouseDown) list.addEventListener('mousedown', cancelEvent);\n    detachClickEvent = attachClickEvent(list, onClick, {ignoreMove: cancelMouseDown});\n  };\n\n  const detach = () => {\n    if(!attached) return;\n    attached = false;\n    // input.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n    document.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n    list.removeEventListener('mousemove', onMouseMove);\n    if(cancelMouseDown) list.removeEventListener('mousedown', cancelEvent);\n    detachClickEvent();\n    detachClickEvent = undefined;\n  };\n\n  const resetTarget = () => {\n    if(waitForKeySet) return;\n    setCurrentTarget(list[PROPERTY_FIRST], false);\n  };\n\n  if(waitForKeySet) {\n    const _onKeyDown = onKeyDown;\n    onKeyDown = (e) => {\n      if(waitForKeySet.has(e.key)) {\n        cancelEvent(e);\n\n        document.removeEventListener(HANDLE_EVENT, onKeyDown, {capture: true});\n        onKeyDown = _onKeyDown;\n        document.addEventListener(HANDLE_EVENT, onKeyDown, {capture: true, passive: false});\n\n        waitForKeySet = undefined;\n        resetTarget();\n      }\n    };\n  } else if(!target) {\n    resetTarget();\n  }\n\n  attach();\n\n  return {\n    attach,\n    detach,\n    resetTarget\n  };\n}\n","import attachListNavigation, {ListNavigationOptions} from '@helpers/dom/attachListNavigation';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport rootScope from '@lib/rootScope';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport SetTransition from '@components/singleTransition';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\nimport safeAssign from '@helpers/object/safeAssign';\nimport liteMode from '@helpers/liteMode';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\n\nexport default class AutocompleteHelper extends EventListenerBase<{\n  hidden: () => void,\n  visible: () => void,\n  hiding: () => void\n}> {\n  protected hidden = true;\n  public container: HTMLElement;\n  protected list: HTMLElement;\n  protected resetTarget: () => void;\n  protected attach: () => void;\n  protected detach: () => void;\n  protected init?(): void;\n\n  protected controller: AutocompleteHelperController;\n  protected listType: 'xy' | 'x' | 'y';\n  protected onSelect: ListNavigationOptions['onSelect'];\n  protected getNavigationList?: () => HTMLElement;\n  protected waitForKey?: string[];\n\n  protected navigationItem: NavigationItem;\n\n  // * helpers in this set are allowed to remain visible alongside this one\n  public siblings: Set<AutocompleteHelper> = new Set();\n  // * per-helper middleware so concurrent sibling helpers don't cancel each other\n  private middlewareHelper: MiddlewareHelper = getMiddleware();\n\n  constructor(options: {\n    appendTo: HTMLElement,\n    controller?: AutocompleteHelper['controller'],\n    listType: AutocompleteHelper['listType'],\n    onSelect: AutocompleteHelper['onSelect'],\n    waitForKey?: AutocompleteHelper['waitForKey'],\n    getNavigationList?: AutocompleteHelper['getNavigationList']\n  }) {\n    super(false);\n\n    safeAssign(this, options);\n\n    this.container = document.createElement('div');\n    this.container.classList.add('autocomplete-helper', 'z-depth-1');\n\n    options.appendTo.append(this.container);\n\n    this.attachNavigation();\n\n    this.controller?.addHelper(this);\n  }\n\n  public getMiddleware() {\n    this.middlewareHelper.clean();\n    return this.middlewareHelper.get();\n  }\n\n  public addSibling(other: AutocompleteHelper) {\n    this.siblings.add(other);\n    other.siblings.add(this);\n  }\n\n  public toggleListNavigation(enabled: boolean) {\n    if(enabled) {\n      this.attach?.();\n    } else {\n      this.detach?.();\n    }\n  }\n\n  protected onVisible = () => {\n    this.detach?.(); // it can be so because 'visible' calls before animation's end\n\n    const list = this.list;\n    const {attach, detach, resetTarget} = attachListNavigation({\n      list: this.getNavigationList?.() || list,\n      type: this.listType,\n      onSelect: this.onSelect,\n      once: true,\n      waitForKey: this.waitForKey\n    });\n\n    this.attach = attach;\n    this.detach = detach;\n    this.resetTarget = resetTarget;\n    if(!IS_MOBILE && !this.navigationItem) {\n      this.navigationItem = {\n        type: 'autocomplete-helper',\n        onPop: () => {\n          this.navigationItem = undefined;\n          this.toggle(true);\n        },\n        noBlurOnPop: true\n      };\n\n      appNavigationController.pushItem(this.navigationItem);\n    }\n\n    this.addEventListener('hidden', () => {\n      this.resetTarget = undefined;\n      this.attach = undefined;\n      this.detach = undefined;\n\n      list.replaceChildren();\n      detach();\n\n      if(this.navigationItem) {\n        appNavigationController.removeItem(this.navigationItem);\n        this.navigationItem = undefined;\n      }\n    }, {once: true});\n  };\n\n  protected attachNavigation() {\n    this.addEventListener('visible', this.onVisible);\n  }\n\n  public toggle(hide?: boolean, fromController = false, skipAnimation?: boolean) {\n    if(hide === undefined) {\n      hide = this.container.classList.contains('is-visible') && !this.container.classList.contains('backwards');\n    }\n\n    // * Cancel any in-flight suggestion load whenever we're hiding — including the\n    // * early-return paths below (not yet initialized, or already hidden). Otherwise a\n    // * slow request resolves later and shows the panel for input that was already\n    // * cleared, since both of those paths used to skip middlewareHelper.clean().\n    if(hide) {\n      this.middlewareHelper.clean();\n    }\n\n    if(this.init) {\n      return;\n    }\n\n    if(this.hidden === hide) {\n      if(!hide) {\n        this.dispatchEvent('visible'); // reset target and listener\n      }\n\n      return;\n    }\n\n    this.hidden = hide;\n\n    if(!hide) {\n      if(this.controller) {\n        // * preserve self + siblings so a sibling that's still loading isn't killed by us showing\n        const preserve = new Set<AutocompleteHelper>([this]);\n        this.siblings.forEach((sibling) => preserve.add(sibling));\n        this.controller.hideOtherHelpers(preserve);\n      }\n      this.dispatchEvent('visible'); // fire it before so target will be set\n    } else {\n      if(this.navigationItem) {\n        appNavigationController.removeItem(this.navigationItem);\n        this.navigationItem = undefined;\n      }\n\n      if(!fromController && this.controller) {\n        this.controller.hideOtherHelpers();\n      }\n\n      this.detach?.(); // force detach here\n    }\n\n    const useRafs = this.controller || hide ? 0 : 2;\n\n    if(hide) {\n      this.dispatchEvent('hiding');\n    }\n\n    SetTransition({\n      element: this.container,\n      className: 'is-visible',\n      forwards: !hide,\n      duration: liteMode.isAvailable('animations') && !skipAnimation ? 300 : 0,\n      onTransitionEnd: () => {\n        this.hidden && this.dispatchEvent('hidden');\n      },\n      useRafs\n    });\n  }\n}\n","import type Chat from '@components/chat/chat';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport mediaSizes from '@helpers/mediaSizes';\nimport preloadAnimatedEmojiSticker from '@helpers/preloadAnimatedEmojiSticker';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport Scrollable from '@components/scrollable';\nimport attachStickerViewerListeners from '@components/stickerViewer';\nimport AutocompleteHelper from '@components/chat/autocompleteHelper';\nimport AutocompleteHelperController from '@components/chat/autocompleteHelperController';\n\nexport default class StickersHelper extends AutocompleteHelper {\n  private scrollable: Scrollable;\n  private onChangeScreen: () => void;\n  private listenerSetter: ListenerSetter;\n\n  constructor(\n    appendTo: HTMLElement,\n    controller: AutocompleteHelperController,\n    private chat: Chat,\n    private managers: AppManagers\n  ) {\n    super({\n      appendTo,\n      controller,\n      listType: 'xy',\n      onSelect: async(target) => {\n        return !(await this.chat.input.emoticonsDropdown.onMediaClick({target}, true));\n      },\n      waitForKey: ['ArrowUp', 'ArrowDown']\n    });\n\n    this.container.classList.add('stickers-helper');\n\n    this.addEventListener('visible', () => {\n      setTimeout(() => { // it is not rendered yet\n        this.scrollable.scrollPosition = 0;\n      }, 0);\n\n      rootScope.dispatchEvent('choosing_sticker', true);\n    });\n\n    this.addEventListener('hidden', () => {\n      if(this.onChangeScreen) {\n        mediaSizes.removeEventListener('changeScreen', this.onChangeScreen);\n        this.onChangeScreen = undefined;\n\n        this.listenerSetter.removeAll();\n        this.listenerSetter = undefined;\n      }\n\n      rootScope.dispatchEvent('choosing_sticker', false);\n    });\n  }\n\n  public checkEmoticon(emoticon: string) {\n    const middleware = this.getMiddleware();\n\n    preloadAnimatedEmojiSticker(emoticon);\n    this.managers.appStickersManager.getStickersByEmoticon({\n      emoticon,\n      includeOurStickers: true,\n      includeServerStickers: this.chat.appSettings.stickers.suggest === 'all'\n    }).then((stickers) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(this.init) {\n        this.init();\n        this.init = null;\n      }\n\n      const container = this.list.cloneNode() as HTMLElement;\n\n      let ready: Promise<void>;\n\n      if(stickers.length) {\n        const lazyLoadQueue = new LazyLoadQueue();\n        const superStickerRenderer = new SuperStickerRenderer({\n          regularLazyLoadQueue: lazyLoadQueue,\n          group: this.chat.animationGroup,\n          managers: this.managers\n        });\n\n        ready = new Promise<void>((resolve) => {\n          const promises: Promise<any>[] = [];\n          stickers.forEach((sticker) => {\n            container.append(superStickerRenderer.renderSticker(sticker as MyDocument, undefined, promises));\n          });\n\n          (Promise.all(promises) as Promise<any>).finally(resolve);\n        });\n\n        middleware.onClean(() => {\n          lazyLoadQueue.clear();\n          setTimeout(() => superStickerRenderer.destroy(), 500); // * fix video flick\n        });\n      } else {\n        ready = Promise.resolve();\n      }\n\n      ready.then(() => {\n        this.list.replaceWith(container);\n        this.list = container;\n\n        if(!this.onChangeScreen) {\n          this.onChangeScreen = () => {\n            const width = (this.list.childElementCount * mediaSizes.active.esgSticker.width) + (this.list.childElementCount - 1 * 1);\n            this.list.style.width = width + 'px';\n          };\n          mediaSizes.addEventListener('changeScreen', this.onChangeScreen);\n\n          this.listenerSetter = new ListenerSetter();\n          attachStickerViewerListeners({listenTo: this.container, listenerSetter: this.listenerSetter});\n        }\n\n        this.onChangeScreen();\n\n        this.toggle(!stickers.length);\n        this.scrollable.scrollPosition = 0;\n      });\n    });\n  }\n\n  public init() {\n    this.list = document.createElement('div');\n    this.list.classList.add('stickers-helper-stickers', 'super-stickers');\n\n    this.container.append(this.list);\n\n    this.scrollable = new Scrollable(this.container);\n  }\n}\n","import {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\n/**\n * Marker class for the unified chat-input plate layout. Anything carrying this\n * class is one of the new uniform-width footer plates (as opposed to the bare\n * single buttons the control container used to hold).\n */\nexport const CHAT_INPUT_PLATE_CLASS = 'chat-input-plate';\n\n/**\n * Unified chat-input control plate.\n *\n * Every non-typing state of the chat-input footer — join channel, unblock,\n * bot start, pinned, message selection, … — renders through this single\n * layout instead of the bespoke per-state markup that used to live in the\n * control container and the selection wrapper.\n *\n * The layout mirrors the topbar translation plate (`translation.tsx`): an\n * optional icon button on each side and a centered main button —\n * `Button.Icon + Button + Button.Icon`. The side slots reserve symmetric\n * space even when empty so the centre button always stays centred, which\n * makes every plate exactly the same width as the message-input row. Plates\n * therefore cross-fade in place (opacity only) instead of morphing width.\n */\nexport default function ChatInputPlate(props: {\n  class?: string,\n  /** Optional leading icon button (`Button.Icon`). */\n  left?: JSX.Element,\n  /** Main centered button (`Button`). */\n  center: JSX.Element,\n  /** Optional trailing icon button (`Button.Icon`). */\n  right?: JSX.Element\n}): JSX.Element {\n  return (\n    <div class={classNames(CHAT_INPUT_PLATE_CLASS, 'rows-wrapper-row', props.class)}>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-side`}>{props.left}</div>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-center`}>{props.center}</div>\n      <div class={`${CHAT_INPUT_PLATE_CLASS}-side`}>{props.right}</div>\n    </div>\n  );\n}\n","import {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport styles from '@components/stargifts/stargiftBadge.module.scss';\nimport {StarGiftAttribute} from '@layer';\nimport {rgbIntToHex} from '@helpers/color';\n\nexport function StarGiftBadge(props: {\n  class?: string\n  textClass?: string\n  children: JSX.Element\n  backdropAttr?: StarGiftAttribute.starGiftAttributeBackdrop\n}) {\n  return (\n    <div\n      class={classNames(styles.badge, props.class)}\n      style={{\n        background: props.backdropAttr ?\n          `linear-gradient(180deg, ${rgbIntToHex(props.backdropAttr.center_color)} 0%, ${rgbIntToHex(props.backdropAttr.edge_color)} 100%)` :\n          undefined\n      }}\n    >\n      <div class={classNames(styles.text, props.textClass)}>\n        {props.children}\n      </div>\n    </div>\n  )\n}\n","import customProperties from '@helpers/dom/customProperties';\nimport {Middleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport pause from '@helpers/schedulers/pause';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {applyColorOnContext} from '@lib/lottie/lottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker';\n\nexport default async function wrapEmojiPattern({\n  docId,\n  middleware,\n  useHighlightingColor,\n  colorAsOut,\n  container,\n  color,\n  positions,\n  canvasWidth,\n  canvasHeight,\n  emojiSize,\n  onCacheStatus: onCacheStatus\n}: {\n  docId: DocId | MyDocument,\n  middleware: Middleware,\n  useHighlightingColor?: boolean,\n  colorAsOut?: boolean,\n  container?: HTMLElement,\n  color?: string,\n  positions: [x: number, y: number, size: number, alpha: number][],\n  canvasWidth: number,\n  canvasHeight: number,\n  emojiSize: number,\n  onCacheStatus?: (cached: boolean) => void\n}) {\n  let doc: MyDocument;\n  if(typeof docId  === 'object') {\n    doc = docId;\n  } else {\n    const result = await rootScope.managers.acknowledged.appEmojiManager.getCustomEmojiDocument(docId);\n    if(!result.cached) onCacheStatus?.(false);\n    doc = await result.result;\n  }\n\n  const d = document.createElement('div');\n  return wrapSticker({\n    doc,\n    div: d,\n    middleware,\n    width: emojiSize,\n    height: emojiSize,\n    // onlyThumb: true,\n    static: true,\n    withThumb: false,\n    exportLoad: 2,\n    useCache: false\n  }).then(({load, downloaded}) => {\n    onCacheStatus?.(downloaded);\n    return load();\n  }).then((result) => {\n    const image = (result as HTMLImageElement[])[0];\n    if(!image.naturalWidth) {\n      console.warn('should wait for image size', image);\n      return pause(100).then(() => image);\n    }\n    return image;\n  }).then((image) => {\n    const canvas = document.createElement('canvas');\n    canvas.classList.add('emoji-pattern-canvas');\n    canvas.style.width = `${canvasWidth}px`;\n    canvas.style.height = `${canvasHeight}px`;\n    const ctx = canvas.getContext('2d');\n    const dpr = canvas.dpr = window.devicePixelRatio;\n    canvas.width = canvasWidth * dpr;\n    canvas.height = canvasHeight * dpr;\n    positions.forEach(([x, y, size, alpha]) => {\n      ctx.globalAlpha = alpha;\n      ctx.drawImage(image, x * dpr, y * dpr, size * dpr, size * dpr);\n    });\n    ctx.globalAlpha = 1;\n\n    if(useHighlightingColor) {\n      color = '#ffffff';\n    } else if(colorAsOut) {\n      color = customProperties.getProperty('message-out-primary-color');\n    }\n\n    applyColorOnContext(ctx, color, 0, 0, canvas.width, canvas.height);\n    if(container) container.prepend(canvas);\n    return canvas;\n  }).catch(noop) as Promise<HTMLCanvasElement>;\n}\n","import {createEffect, createMemo, createSignal, JSX, on, onCleanup, onMount} from 'solid-js';\nimport {StarGiftAttribute} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport wrapEmojiPattern from '@components/wrappers/emojiPattern';\nimport {getMiddleware} from '@helpers/middleware';\nimport {rgbIntToHex} from '@helpers/color';\n\nconst MIN_OPACITY = .1;\nconst MID_OPACITY = .2;\nconst MAX_OPACITY = .3;\nconst CANVAS_WIDTH = 266;\nconst CANVAS_HEIGHT = 184;\n\nconst SMALL_CANVAS_WIDTH = 120;\nconst SMALL_CANVAS_HEIGHT = 120;\n\nimport styles from '@components/stargifts/stargiftBackdrop.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport {Transition} from '@vendor/solid-transition-group';\n\nconst POSITIONS: [number, number, number, number][] = [\n  [55, 47, 18, MAX_OPACITY],\n  [23, 26, 18, MID_OPACITY],\n  [0, 64, 18, MID_OPACITY],\n  [0, 165, 18, MIN_OPACITY],\n  [17, 125, 18, MID_OPACITY],\n  [58, 141, 22, MAX_OPACITY],\n  [81, 13, 24, MAX_OPACITY],\n  [38, 82, 26, MAX_OPACITY],\n  [187, 46, 18, MAX_OPACITY],\n  [219, 26, 18, MID_OPACITY],\n  [119, 5, 18, MAX_OPACITY],\n  [242, 64, 18, MID_OPACITY],\n  [245, 165, 18, MIN_OPACITY],\n  [225, 125, 18, MID_OPACITY],\n  [118, 151, 22, MAX_OPACITY],\n  [180, 141, 22, MAX_OPACITY],\n  [155, 13, 24, MAX_OPACITY],\n  [196, 82, 26, MAX_OPACITY]\n]\n\nconst POSITIONS_SMALL: [number, number, number, number][] = [\n  [49, 1, 20, MAX_OPACITY],\n  [93, 12, 20, MAX_OPACITY],\n  [99, 42, 20, MAX_OPACITY],\n  [89, 86, 20, MAX_OPACITY],\n  [49, 97, 20, MAX_OPACITY],\n  [9, 86, 20, MAX_OPACITY],\n  [0, 42, 20, MAX_OPACITY],\n  [5, 12, 20, MAX_OPACITY]\n];\n\nexport function StarGiftBackdrop(props: {\n  class?: string\n  small?: boolean\n  canvasClass?: string\n  backdrop: StarGiftAttribute.starGiftAttributeBackdrop\n  patternEmoji: MyDocument\n}) {\n  const middlewareHelper = getMiddleware();\n\n  const [patternCanvas, setPatternCanvas] = createSignal<HTMLCanvasElement>();\n\n  function render() {\n    const middleware = middlewareHelper.get();\n    const currentEmoji = props.patternEmoji;\n    wrapEmojiPattern({\n      docId: props.patternEmoji,\n      middleware,\n      canvasWidth: props.small ? SMALL_CANVAS_WIDTH : CANVAS_WIDTH,\n      canvasHeight: props.small ? SMALL_CANVAS_HEIGHT : CANVAS_HEIGHT,\n      emojiSize: 24,\n      positions: props.small ? POSITIONS_SMALL : POSITIONS,\n      color: rgbIntToHex(props.backdrop.pattern_color)\n    }).then((canvas) => {\n      if(!middleware()) return;\n      if(currentEmoji !== props.patternEmoji) return\n      canvas.classList.add(styles.canvas, props.canvasClass);\n      setPatternCanvas(canvas);\n    });\n  }\n\n  createEffect(on(() => [props.patternEmoji, props.backdrop], () => {\n    render();\n  }));\n\n  return (\n    <div\n      class={classNames(styles.wrap, props.class)}\n      style={{\n        '--stargift-backdrop-edge-color': rgbIntToHex(props.backdrop.edge_color),\n        '--stargift-backdrop-center-color': rgbIntToHex(props.backdrop.center_color)\n      }}\n    >\n      <Transition>\n        {patternCanvas()}\n      </Transition>\n      <div class={classNames(styles.halo, props.small && styles.haloSmall)} />\n    </div>\n  );\n}\n","import numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {StarGift} from '@layer';\n\nexport function getCollectibleName(gift: StarGift.starGiftUnique) {\n  return `${gift.title} #${numberThousandSplitter(gift.num, ',')}`\n}\n","import PopupElement, {addCancelButton, PopupButton} from '.';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {InputCheckPasswordSRP} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport {InputState} from '@components/inputField';\nimport PasswordInputField from '@components/passwordInputField';\nimport PopupPeer, {PopupPeerOptions} from '@components/popups/peer';\n\nexport async function passwordPopup<Result>(options: Omit<PopupPeerOptions, 'inputField'> & {\n  button?: Omit<PopupPeerOptions['buttons'][0], 'callback'>;\n  callback: (inputCheckPassword: InputCheckPasswordSRP) => Promise<Result>;\n}) {\n  let state = await rootScope.managers.passwordManager.getState();\n\n  const passwordInputField = new PasswordInputField({\n    labelText: state.hint ?? '',\n    onRawInput: () => {\n      passwordInputField.setState(InputState.Neutral);\n    }\n  });\n\n  let resolved = false;\n  const deferred = deferredPromise<Result>();\n\n  const buttonOptions: PopupButton = {\n    langKey: options.button?.langKey ?? 'Confirm',\n    langArgs: options.button?.langArgs ?? [],\n    callback: async() => {\n      buttonOptions.element.disabled = true\n      try {\n        const inputCheckPassword = await rootScope.managers.passwordManager.getInputCheckPassword(passwordInputField.value, state);\n        const result = await options.callback(inputCheckPassword);\n        deferred.resolve(result);\n        resolved = true;\n        return true\n      } catch(err) {\n        console.error(err)\n        if((err as ApiError).type === 'PASSWORD_HASH_INVALID') {\n          passwordInputField.setState(InputState.Error, 'PASSWORD_HASH_INVALID')\n        } else if((err as ApiError).type.startsWith('FLOOD_WAIT_')) {\n          passwordInputField.setState(InputState.Error, 'PasscodeLock.TooManyAttempts')\n        } else {\n          passwordInputField.setState(InputState.Error, 'Error.AnError')\n        }\n        state = await rootScope.managers.passwordManager.getState();\n        return false\n      } finally {\n        buttonOptions.element.disabled = false\n      }\n    }\n  }\n\n  const popup = PopupElement.createPopup(PopupPeer, 'popup-confirmation', {\n    ...options,\n    inputField: passwordInputField,\n    buttons: addCancelButton([buttonOptions])\n  })\n\n  popup.addEventListener('closeAfterTimeout', () => {\n    if(!resolved) {\n      deferred.reject();\n    }\n  });\n\n  popup.show()\n\n  return deferred;\n}\n","import classNames from '@helpers/string/classNames';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {IconTsx} from '@components/iconTsx';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport {StarGiftBackdrop} from '@components/stargifts/stargiftBackdrop';\nimport styles from '@components/stargifts/transferPreview.module.scss'\n\nexport function StarGiftTransferPreview(props: {\n  class?: string;\n  gift: MyStarGift\n  recipient: PeerId\n}) {\n  return (\n    <div class={classNames(styles.graph, props.class)}>\n      <div class={/* @once */ styles.giftWrap}>\n        <StarGiftBackdrop\n          backdrop={props.gift.collectibleAttributes?.backdrop}\n          patternEmoji={props.gift.collectibleAttributes?.pattern.document as MyDocument}\n          small\n          canvasClass={/* @once */ styles.giftBackdropCanvas}\n        />\n        <StickerTsx\n          sticker={props.gift.collectibleAttributes?.model.document as MyDocument}\n          width={48}\n          height={48}\n          autoStyle\n          extraOptions={{play: true, loop: true}}\n        />\n      </div>\n      <IconTsx icon=\"next\" />\n      <AvatarNewTsx\n        peerId={props.recipient}\n        size={60}\n      />\n    </div>\n  )\n}\n","import {splitProps} from 'solid-js'\nimport ButtonMenuToggle from '@components/buttonMenuToggle'\nimport {attachClassName} from '@helpers/solid/classname'\n\nexport type ButtonMenuToggleProps = Parameters<typeof ButtonMenuToggle>[0] & {\n  class?: string\n}\n\nexport const ButtonMenuToggleTsx = (props: ButtonMenuToggleProps) => {\n  const [, rest] = splitProps(props, ['class'])\n  const res = ButtonMenuToggle(rest)\n\n  attachClassName(res, () => props.class)\n\n  return res\n}\n","import classNames from '@helpers/string/classNames';\nimport useStars from '@stores/stars';\nimport PopupStars, {StarsStar} from '@components/popups/stars';\nimport styles from '@components/popups/floatingStarsBalance.module.scss';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport PopupElement from '.';\nimport {i18n} from '@lib/langPack';\nimport {IconTsx} from '@components/iconTsx';\nimport {createResource} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport paymentsWrapCurrencyAmount, {formatNanoton, nanotonToJsNumber} from '@helpers/paymentsWrapCurrencyAmount';\n\nexport function FloatingStarsBalance(props: {\n  class?: string;\n  ton?: boolean;\n}) {\n  const balance = useStars();\n  const balanceTon = useStars(true);\n  const [appConfig] = createResource(() => rootScope.managers.apiManager.getAppConfig());\n\n  const converted = () => {\n    const rate = appConfig.latest?.ton_usd_rate;\n    if(!rate) return '...';\n\n    return paymentsWrapCurrencyAmount(nanotonToJsNumber(balanceTon()) * rate * 100, 'USD');\n  }\n\n  return (\n    <div class={classNames(styles.container, props.class)}>\n      <I18nTsx\n        key=\"StarsBalanceLong\"\n        args={props.ton ? [\n          <IconTsx icon=\"ton\" />,\n          <b>{formatNanoton(balanceTon())}</b>\n        ] : [\n          <StarsStar />,\n          <b>{balance()}</b>\n        ]}\n      />\n      {props.ton ? (\n        <div class={styles.tonUsd}>\n          ~{converted()}\n        </div>\n      ) : (\n        <a\n          class={styles.getMore}\n          onClick={() => PopupElement.createPopup(PopupStars)}\n        >\n          {i18n('GetMoreStars')}\n        </a>\n      )}\n    </div>\n  );\n}\n","import {createContext, createEffect, JSX, on, onCleanup, onMount, Ref, useContext} from 'solid-js';\n\nimport styles from '@components/chipTabs.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {fastRaf} from '@helpers/schedulers';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport Scrollable from '@components/scrollable2';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport filterAsync from '../helpers/array/filterAsync';\n\ninterface ChipTabsContextValue {\n  value: string,\n  onClick: (event: MouseEvent, value: string) => void\n  updateCurrent: () => void\n}\n\nconst ChipTabsContext = createContext<ChipTabsContextValue>(null);\n\nexport function ChipTab(props: {\n  class?: string\n  children: JSX.Element\n  value: string\n}) {\n  const ctx = useContext(ChipTabsContext);\n  onCleanup(() => fastRaf(ctx.updateCurrent));\n  return (\n    <div\n      class={classNames(styles.chip, ctx.value === props.value && styles.active, props.class)}\n      onClick={(event: MouseEvent) => ctx.onClick(event, props.value)}\n      data-value={props.value}\n    >\n      {props.children}\n    </div>\n  )\n}\n\nexport function ChipTabs(props: {\n  class?: string\n  value: string,\n  view: 'surface' | 'secondary' | 'primary',\n  onChange: (value: string) => boolean | void,\n  contextMenuButtons?: (itemId: string) => MaybePromise<ButtonMenuItemOptionsVerifiable[]>,\n  children: JSX.Element\n  ref?: Ref<HTMLDivElement>\n  center?: boolean\n  needIntersectionObserver?: boolean\n}) {\n  let scrollable!: HTMLDivElement;\n  let chosenRef!: HTMLDivElement;\n\n  function updateChosen(categoryEl: HTMLElement, categoryRect: DOMRect) {\n    const scrollableRect = scrollable.getBoundingClientRect();\n    chosenRef.style.width = `${categoryRect.width}px`;\n    chosenRef.style.left = `${categoryRect.left - scrollableRect.left + scrollable.scrollLeft}px`;\n\n    const visibleRect = getVisibleRect(categoryEl, scrollable, false, categoryRect, undefined, true);\n    if(!visibleRect || visibleRect.overflow.horizontal) {\n      fastSmoothScroll({\n        element: categoryEl,\n        container: scrollable,\n        position: 'center',\n        axis: 'x'\n      });\n    }\n  }\n\n  function handleClick(event: MouseEvent, value: string) {\n    const result = props.onChange(value);\n    if(result === false) return;\n    const categoryEl = findUpClassName(event.target as HTMLElement, styles.chip);\n\n    fastRaf(() => {\n      const categoryRect = categoryEl.getBoundingClientRect();\n      updateChosen(categoryEl, categoryRect);\n    });\n  }\n\n  let updatedOnce = false\n  function updateCurrent() {\n    const categoryEl = scrollable.querySelector(`[data-value=\"${props.value}\"]`);\n    if(categoryEl) {\n      const rect = categoryEl.getBoundingClientRect();\n      if(rect.width === 0 && rect.height === 0) return;\n      updateChosen(categoryEl as HTMLElement, rect);\n    }\n    if(!updatedOnce) {\n      chosenRef.classList.add(styles.animate);\n      updatedOnce = true;\n    }\n  }\n\n  createEffect(on(() => props.value, () => fastRaf(updateCurrent)))\n\n  if(props.needIntersectionObserver) {\n    onMount(() => {\n      const observer = new IntersectionObserver((mutations) => {\n        mutations.forEach((mutation) => {\n          if(mutation.isIntersecting) {\n            updateCurrent();\n            observer.disconnect();\n          }\n        });\n      }, {\n        threshold: 1\n      });\n\n      observer.observe(scrollable.parentElement);\n\n      onCleanup(() => observer.disconnect());\n    })\n  }\n\n  if(props.contextMenuButtons) {\n    let chosenElement: HTMLElement;\n    onMount(() => {\n      createContextMenu({\n        listenTo: scrollable,\n        findElement: (event) => findUpClassName(event.target as HTMLElement, styles.chip),\n        onOpen: (event, target) => {\n          chosenElement = target;\n        },\n        buttons: [],\n        filterButtons: async() => {\n          const buttons = await props.contextMenuButtons(chosenElement.dataset.value)\n          return filterAsync(buttons, async(button) => {\n            return button?.verify ? (await button.verify()) ?? false : true;\n          })\n        }\n      })\n    })\n  }\n\n  return (\n    <ChipTabsContext.Provider\n      value={{\n        get value() {\n          return props.value;\n        },\n        onClick: handleClick,\n        updateCurrent\n      }}\n    >\n      <div\n        class={classNames(\n          props.class,\n          styles.container,\n          styles[props.view],\n          props.view === 'primary' && styles.primary,\n          props.center && styles.center\n        )}\n        ref={props.ref}\n      >\n        <Scrollable axis=\"x\" ref={scrollable}>\n          <div class={styles.chosen} ref={chosenRef} />\n          {props.children}\n        </Scrollable>\n      </div>\n    </ChipTabsContext.Provider>\n  )\n}\n","import {createEffect, createSignal, on} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport rootScope from '@lib/rootScope';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport styles from '@components/popups/buyResaleGift.module.scss';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport {STARS_CURRENCY, TON_CURRENCY} from '@appManagers/constants';\nimport {StarGift} from '@layer';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {FloatingStarsBalance} from '@components/popups/floatingStarsBalance';\nimport PopupPayment from '@components/popups/payment';\nimport {StarGiftTransferPreview} from '@components/stargifts/transferPreview';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\n\nexport default class PopupBuyResaleGift extends PopupElement<{\n  finish: (result: boolean) => void\n}> {\n  private recipientId: PeerId;\n  private gift: MyStarGift;\n\n  private finished = false;\n  constructor(options: {\n    recipientId: PeerId,\n    gift: MyStarGift\n  }) {\n    super(styles.popup, {\n      overlayClosable: true,\n      body: true\n    });\n\n    this.addEventListener('close', () => {\n      if(!this.finished) {\n        this.dispatchEvent('finish', false);\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.header.remove()\n\n    this.construct()\n  }\n\n  protected async construct() {\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    const [ton, setTon] = createSignal(this.gift.resellOnlyTon ?? false);\n    const gift = this.gift.raw as StarGift.starGiftUnique;\n\n    createEffect(on(ton, (ton) => {\n      this.setButtons([\n        {\n          langKey: 'StarGiftResaleBuyConfirm',\n          langArgs: [\n              ton ?\n                paymentsWrapCurrencyAmount(this.gift.resellPriceTon, TON_CURRENCY) :\n                paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY)\n          ],\n          callback: async() => {\n            const popup = await PopupPayment.create({\n              inputInvoice: {\n                _: 'inputInvoiceStarGiftResale',\n                pFlags: {ton: ton ? true : undefined},\n                slug: gift.slug,\n                to_id: await rootScope.managers.appPeersManager.getInputPeerById(this.recipientId)\n              },\n              noShowIfStars: true,\n              purpose: 'stargift'\n            });\n\n            popup.addEventListener('finish', (result) => {\n              if(result === 'paid' || result === 'pending') {\n                this.finished = true;\n                this.dispatchEvent('finish', true);\n                this.hide()\n              }\n            });\n            return false;\n          }\n        },\n        {\n          langKey: 'Cancel',\n          callback: () => {\n            this.finished = true\n            this.dispatchEvent('finish', false);\n          }\n        }\n      ])\n    }))\n\n    return (\n      <>\n        {gift.pFlags.resale_ton_only ? (\n          <div class={/* @once */ styles.onlyTon}>\n            <I18nTsx key=\"StarGiftResaleOnlyTon\" />\n          </div>\n        ) : (\n          <ChipTabs\n            value={ton() ? 'ton' : 'stars'}\n            view=\"primary\"\n            onChange={(value) => setTon(value === 'ton')}\n          >\n            <ChipTab value=\"stars\">\n              <I18nTsx key=\"StarGiftResalePayInStars\" />\n            </ChipTab>\n            <ChipTab value=\"ton\">\n              <I18nTsx key=\"StarGiftResalePayInTon\" />\n            </ChipTab>\n          </ChipTabs>\n        )}\n\n        <StarGiftTransferPreview\n          class={/* @once */ styles.graph}\n          gift={this.gift}\n          recipient={this.recipientId}\n        />\n\n        <I18nTsx class={/* @once */ styles.title} key=\"ConfirmPayment\" />\n\n        <div class={/* @once */ styles.text}>\n          <I18nTsx\n            key={this.recipientId !== rootScope.myId ? 'StarGiftResaleBuyTextWithRecipient' : 'StarGiftResaleBuyText'}\n            args={[\n              <span>\n                {gift.title}\n                &nbsp;#{numberThousandSplitter(gift.num)}\n              </span>,\n              ton() ?\n                paymentsWrapCurrencyAmount(this.gift.resellPriceTon, TON_CURRENCY, false, false, true) :\n                paymentsWrapCurrencyAmount(this.gift.resellPriceStars, STARS_CURRENCY, false, false, true),\n              this.recipientId !== rootScope.myId && <PeerTitleTsx peerId={this.recipientId} />\n            ]}\n          />\n        </div>\n        <FloatingStarsBalance class={styles.starsBalance} ton={ton()} />\n      </>\n    )\n  }\n}\n","import classNames from '@helpers/string/classNames';\n\nfunction Path1(props: {stroke?: boolean}) {\n  return (\n    <path class={props.stroke && 'currency-star-icon-stroke'} d=\"M8.7221 7.50194L11.1473 2.67049C11.4277 2.11345 12.106 1.88988 12.6593 2.17029C12.8753 2.28018 13.0496 2.45828 13.1595 2.67807L15.452 7.339C15.6377 7.72173 16.0053 7.97941 16.4259 8.02867L21.2195 8.60465C21.8712 8.68423 22.3373 9.27916 22.2615 9.93473C22.2274 10.2038 22.1062 10.4539 21.9129 10.6433L18.1198 14.3835C17.9644 14.535 17.8924 14.7472 17.9189 14.9632L18.5517 20.0107C18.6427 20.7345 18.1311 21.3938 17.4111 21.4848C17.1383 21.5189 16.8655 21.4696 16.623 21.337L12.6176 19.1467C12.3258 18.9876 11.9772 18.9838 11.6854 19.1353L7.53223 21.265C6.94867 21.5643 6.23627 21.3294 5.93691 20.742C5.82322 20.5222 5.78533 20.2759 5.81944 20.0334L6.14911 17.7143C6.31205 16.5813 7.01309 15.5961 8.02864 15.0769L12.6365 12.7237C12.7578 12.6631 12.807 12.5115 12.7464 12.3865C12.6972 12.2917 12.5948 12.2349 12.4887 12.25L6.85015 13.061C5