=> count - 1);\n      shiftStoryIndex(peerIndex, storyIndex, -1);\n    });\n  };\n\n  const onStoriesRead = ({peerId, maxReadId}: BroadcastEvents['stories_read']) => {\n    const peerIndex = getPeerIndex(peerId);\n    if(peerIndex === -1) {\n      return;\n    }\n\n    setState('peers', peerIndex, 'maxReadId', maxReadId);\n  };\n\n  // const onUserStoriesHidden = ({userId, hidden}: BroadcastEvents['user_stories_hidden']) => {\n  //   const peerId = userId.toPeerId(false);\n  //   const peerIndex = getPeerIndex(peerId);\n  //   if(peerIndex === -1) {\n  //     return;\n  //   }\n\n  //   if((props.archive && !hidden) || (!props.archive && hidden)) {\n  //     deletePeer(peerId);\n  //   }\n  // };\n\n  const onStoriesPosition = (data: BroadcastEvents['stories_position'], ignoreFreezed?: boolean) => {\n    const {peerId, position} = data;\n    if(freezedSorting.size && !ignoreFreezed) {\n      const previousPosition = positions.get(peerId);\n      if(previousPosition?.type === position?.type || (state.hasViewer && previousPosition && position)) {\n        findAndSplice(postponedPositions, (data) => data.peerId === peerId);\n        postponedPositions.push(data);\n        return;\n      }\n    }\n\n    onPosition(data);\n\n    if(!canAddPeer(peerId)) {\n      deletePeer(peerId);\n      return;\n    }\n\n    const peer = state.peers.find((p) => p.peerId === peerId);\n    if(!peer) {\n      return;\n    }\n\n    addPeers([peer]);\n  };\n\n  const onStealthMode = (data: BroadcastEvents['stories_stealth_mode']) => {\n    setState('stealthMode', reconcile(data));\n  };\n\n  listenerSetter.add(rootScope)('story_update', onStoryUpdate);\n  listenerSetter.add(rootScope)('story_deleted', onStoryDeleted);\n  if(!props.archive && !props.pinned) {\n    listenerSetter.add(rootScope)('story_expired', onStoryDeleted);\n  }\n  if(!props.singleStory) {\n    listenerSetter.add(rootScope)('story_new', onStoryNew);\n  }\n  if(!singlePeerId || props.needUpdates) {\n    listenerSetter.add(rootScope)('stories_stories', onStoriesStories);\n    listenerSetter.add(rootScope)('stories_read', onStoriesRead);\n    // listenerSetter.add(rootScope)('user_stories_hidden', onUserStoriesHidden);\n    listenerSetter.add(rootScope)('stories_position', onStoriesPosition);\n  }\n  listenerSetter.add(rootScope)('stories_stealth_mode', onStealthMode);\n\n  if(singlePeerId && props.pinned) {\n    listenerSetter.add(rootScope)('story_album_created', ({peerId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      setState('peers', 0, 'albums', albums);\n    });\n\n    listenerSetter.add(rootScope)('story_album_deleted', ({peerId, albumId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      albumCache.delete(albumId);\n      if(state.albumId === albumId) {\n        if(albumCache.has(undefined)) {\n          syncManagerSnapshot(undefined, false);\n        }\n        actions.setAlbumId(undefined);\n        albumCache.delete(albumId);\n      }\n      setState('peers', 0, 'albums', albums);\n    });\n\n    listenerSetter.add(rootScope)('story_album_updated', ({peerId, albumId, albums}) => {\n      if(peerId !== singlePeerId) return;\n      setState('peers', 0, 'albums', albums);\n\n      if(albumCache.has(undefined)) {\n        syncManagerSnapshot(undefined, false);\n      }\n\n      if(state.albumId === albumId) {\n        syncManagerSnapshot(albumId, true);\n      } else if(albumCache.has(albumId)) {\n        syncManagerSnapshot(albumId, false);\n      }\n    });\n  }\n\n  // * updates section end\n\n  if(!props.manualLoad) {\n    if(!state.ready) {\n      actions.load();\n    } else if(state.peer?.index === undefined) { // * `props.index` can point past `props.peers`\n      actions.resetIndexes();\n    }\n  }\n\n  rootScope.managers.appStoriesManager.getStealthMode().then((data) => {\n    if(!disposed) {\n      onStealthMode(data);\n    }\n  });\n\n  if(singlePeerId) {\n    if(singlePeerId === rootScope.myId) {\n      setState({canEdit: true});\n    } else if(singlePeerId.isAnyChat()) {\n      rootScope.managers.appChatsManager.hasRights(singlePeerId.toChatId(), 'edit_stories').then((canEdit) => {\n        if(!disposed) {\n          setState({canEdit});\n        }\n      });\n    }\n  }\n\n  return [state, actions];\n};\n\n// const storiesStore = createStoriesStore();\nexport const StoriesContext = createContext<StoriesContextValue>(/* storiesStore */);\nexport const StoriesProvider: ParentComponent<Parameters<typeof createStoriesStore>[0]> = (props) => {\n  return (\n    <StoriesContext.Provider value={createStoriesStore(props)}>\n      {props.children}\n    </StoriesContext.Provider>\n  );\n}\n\nexport const useStories = () => useContext(StoriesContext);\n","import type {PeerAvailableReactions} from '@appManagers/appReactionsManager';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {IS_MOBILE, IS_SAFARI} from '@environment/userAgent';\nimport filterUnique from '@helpers/array/filterUnique';\nimport assumeType from '@helpers/assumeType';\nimport callbackifyAll from '@helpers/callbackifyAll';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport liteMode from '@helpers/liteMode';\nimport {Middleware, getMiddleware} from '@helpers/middleware';\nimport noop from '@helpers/noop';\nimport {fastRaf} from '@helpers/schedulers';\nimport {Message, AvailableReaction, Reaction, AvailableEffect, EmojiGroup} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport rootScope from '@lib/rootScope';\nimport {stashFlightSource, warmUpGenericEffectAssets, warmUpReactionEffect} from '@components/chat/reaction';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport ButtonIcon from '@components/buttonIcon';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport EmojiTab from '@components/emoticonsDropdown/tabs/emoji';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {i18n} from '@lib/langPack';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupPremium from '@components/popups/premium';\nimport contextMenuController from '@helpers/contextMenuController';\nimport callbackify from '@helpers/callbackify';\nimport partition from '@helpers/array/partition';\nimport {PAID_REACTION_EMOJI_DOCID} from '@lib/customEmoji/constants';\nimport {StarsStar} from '@components/popups/stars';\nimport {cleanEmoji} from '@lib/richTextProcessor/fixEmoji';\n\nconst REACTIONS_CLASS_NAME = 'btn-menu-reactions';\nconst REACTION_CLASS_NAME = REACTIONS_CLASS_NAME + '-reaction';\n\nconst REACTIONS_MAX_LENGTH = 7;\nconst REACTION_SIZE = 28; // 36\nconst PADDING = 6;\nexport const REACTION_CONTAINER_SIZE = REACTION_SIZE + PADDING * 2;\n\nconst CAN_USE_TRANSFORM = !IS_SAFARI;\nconst SCALE_ON_HOVER = CAN_USE_TRANSFORM && false;\n\ntype ChatReactionsMenuPlayers = {\n  select?: LottiePlayer,\n  appear?: LottiePlayer,\n  selectWrapper: HTMLElement,\n  appearWrapper: HTMLElement,\n  reaction: Reaction\n};\nexport class ChatReactionsMenu {\n  public widthContainer: HTMLElement;\n  public container: HTMLElement;\n  private reactionsMap: Map<HTMLElement, ChatReactionsMenuPlayers>;\n  // private scrollable: ScrollableBase;\n  private animationGroup: AnimationItemGroup;\n  private middlewareHelper: ReturnType<typeof getMiddleware>;\n  private managers: AppManagers;\n  private onFinish: (reaction?: Reaction | Promise<Reaction>) => void;\n  private listenerSetter: ListenerSetter;\n  private size: number;\n  private openSide: 'top' | 'bottom';\n  private getOpenPosition: (hasMenu: boolean) => DOMRectEditable;\n  private noMoreButton: boolean;\n  private isTags: boolean;\n  private isEffects: boolean;\n  private reactions: Reaction[];\n  private availableReactions: AvailableReaction[];\n  private noPacks: boolean;\n  private noSearch: boolean;\n  public freeCustomEmoji: Set<DocId>;\n  public inited: boolean;\n\n  constructor(options: {\n    managers: AppManagers,\n    type: 'horizontal' | 'vertical',\n    middleware: Middleware,\n    onFinish: ChatReactionsMenu['onFinish'],\n    size?: ChatReactionsMenu['size'],\n    openSide?: ChatReactionsMenu['openSide'],\n    getOpenPosition: ChatReactionsMenu['getOpenPosition'],\n    noMoreButton?: boolean,\n    isTags?: boolean,\n    isEffects?: boolean\n  }) {\n    this.managers = options.managers;\n    this.middlewareHelper = options.middleware ? options.middleware.create() : getMiddleware();\n    this.onFinish = options.onFinish;\n    this.listenerSetter = new ListenerSetter();\n    this.size = options.size ?? REACTION_SIZE;\n    this.openSide = options.openSide ?? 'bottom';\n    this.getOpenPosition = options.getOpenPosition;\n    this.noMoreButton = options.noMoreButton;\n    this.isTags = options.isTags;\n    this.isEffects = options.isEffects;\n\n    this.middlewareHelper.get().onDestroy(() => {\n      this.listenerSetter.removeAll();\n    });\n\n    const widthContainer = this.widthContainer = document.createElement('div');\n    widthContainer.classList.add(\n      REACTIONS_CLASS_NAME + '-container',\n      REACTIONS_CLASS_NAME + '-container-' + options.type,\n      'btn-menu-transition'\n    );\n\n    if(this.isTags || this.isEffects) {\n      widthContainer.classList.add(REACTIONS_CLASS_NAME + '-container-' + 'tags');\n      const description = this.isEffects ? i18n('AddEffectMessageHint') : i18n(\n        rootScope.premium ? 'Reactions.Tag.Description' : 'Reactions.Tag.PremiumHint',\n        [\n          anchorCallback(() => {\n            contextMenuController.close();\n            PopupPremium.show({feature: 'saved_tags'});\n          })\n        ]\n      );\n      description.classList.add(REACTIONS_CLASS_NAME + '-description');\n      widthContainer.append(description);\n    }\n\n    const reactionsContainer = this.container = document.createElement('div');\n    reactionsContainer.classList.add(REACTIONS_CLASS_NAME/* , 'btn-menu-transition' */);\n\n    // const shadow = document.createElement('div');\n    // shadow.classList.add('inner-shadow');\n\n    // const reactionsScrollable = this.scrollable = type === 'vertical' ? new Scrollable(undefined) : new ScrollableX(undefined);\n    // reactionsContainer.append(reactionsScrollable.container/* , shadow */);\n    // reactionsScrollable.onAdditionalScroll = this.onScroll;\n    // reactionsScrollable.setListeners();\n    // reactionsScrollable.container.classList.add('no-scrollbar');\n\n    ['big'].forEach((type) => {\n      const bubble = document.createElement('div');\n      bubble.classList.add(\n        REACTIONS_CLASS_NAME + '-bubble',\n        REACTIONS_CLASS_NAME + '-bubble-' + type\n        // 'btn-menu-transition'\n      );\n      widthContainer.append(bubble);\n    });\n\n    this.reactionsMap = new Map();\n    this.animationGroup = `CHAT-MENU-REACTIONS-${Date.now()}`;\n    animationIntersector.setOverrideIdleGroup(this.animationGroup, true);\n\n    if(!IS_TOUCH_SUPPORTED) {\n      reactionsContainer.addEventListener('mousemove', this.onMouseMove);\n    }\n\n    attachClickEvent(reactionsContainer, (e) => {\n      const reactionDiv = findUpClassName(e.target, REACTION_CLASS_NAME);\n      if(!reactionDiv) return;\n\n      const players = this.reactionsMap.get(reactionDiv);\n      if(!players) return;\n\n      // * snapshot the clicked element (instant flight source) + kick off the\n      // * clean first-frame render that upgrades it\n      if(!this.isEffects) {\n        stashFlightSource(players.reaction, reactionDiv);\n      }\n      this.onFinish(players.reaction);\n    }, {listenerSetter: this.listenerSetter});\n\n    widthContainer.append(reactionsContainer);\n  }\n\n  private render = async(renderPromises: Promise<any>[], hasMore: boolean) => {\n    const middleware = this.middlewareHelper.get();\n    await Promise.all(renderPromises);\n    if(!middleware()) {\n      return;\n    }\n\n    if(hasMore && !this.noMoreButton) {\n      const moreButton = ButtonIcon(`${this.openSide === 'bottom' ? 'down' : 'up'} ${REACTIONS_CLASS_NAME}-more`, {noRipple: true});\n      this.container.append(moreButton);\n      attachClickEvent(\n        moreButton,\n        this.onMoreClick,\n        {listenerSetter: this.listenerSetter}\n      );\n    }\n\n    const setVisible = () => {\n      this.widthContainer.classList.add('is-visible');\n    };\n\n    return setVisible;\n  };\n\n  private renderReactions(\n    {type, reactions}: PeerAvailableReactions,\n    availableReactions: AvailableReaction[]\n  ) {\n    if(availableReactions) {\n      this.availableReactions = availableReactions;\n      this.freeCustomEmoji = new Set(\n        this.availableReactions\n        .map((availableReaction) => availableReaction.select_animation.id)\n        .concat(reactions.map((reaction) => this.reactionToDocId(reaction)))\n      );\n    }\n\n    const renderPromises = reactions.slice(0, REACTIONS_MAX_LENGTH).map((reaction) => {\n      const availableReaction = reaction._ === 'reactionEmoji' ? availableReactions.find((_reaction) => _reaction.reaction === reaction.emoticon) : undefined;\n      return this.renderReaction(reaction, availableReaction);\n    });\n\n    return this.render(renderPromises, reactions.length > REACTIONS_MAX_LENGTH);\n  }\n\n  private renderEffects(availableEffects: AvailableEffect[]) {\n    const renderPromises = availableEffects.slice(0, REACTIONS_MAX_LENGTH).map((availableEffect) => {\n      return this.renderReaction({_: 'reactionCustomEmoji', document_id: availableEffect.effect_sticker_id});\n    });\n\n    return this.render(renderPromises, availableEffects.length > REACTIONS_MAX_LENGTH);\n  }\n\n  private async prepareReactions(message?: Message.message | Message.messageService) {\n    // * most reactions resolve to the generic effect - have its assets ready\n    // * by the time the user picks one\n    warmUpGenericEffectAssets(this.managers);\n\n    const middleware = this.middlewareHelper.get();\n    const availableReactionsResult = apiManagerProxy.getAvailableReactions();\n    const peerAvailableReactionsResult = await this.managers.acknowledged.appReactionsManager.getAvailableReactionsByMessage(message);\n    const cached = !(availableReactionsResult instanceof Promise) && peerAvailableReactionsResult.cached;\n    const renderPromise = callbackifyAll([\n      peerAvailableReactionsResult.result,\n      availableReactionsResult\n    ], async([peerAvailableReactions, availableReactions]) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(peerAvailableReactions.type === 'chatReactionsNone') {\n        return;\n      }\n\n      this.reactions = peerAvailableReactions.reactions;\n      // At reactions_uniq_max the message can take no new distinct reaction, so hide the\n      // custom-emoji search/packs (like tdesktop/iOS/Android) — the grid is already narrowed\n      // to the present kinds; only piling onto those stays possible.\n      this.noPacks = this.noSearch = peerAvailableReactions.type !== 'chatReactionsAll' || !!peerAvailableReactions.atUniqCap;\n      return this.renderReactions(peerAvailableReactions, availableReactions);\n    });\n\n    return [cached, renderPromise] as const;\n  }\n\n  private async prepareEffects() {\n    const middleware = this.middlewareHelper.get();\n    const availableEffects = await this.managers.acknowledged.appReactionsManager.getAvailableEffects();\n    const {cached} = availableEffects;\n    const renderPromise = callbackify(\n      availableEffects.result,\n      async(availableEffects) => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.freeCustomEmoji = new Set(\n          availableEffects\n          .filter((availableEffect) => !availableEffect.pFlags.premium_required)\n          .map((availableEffect) => availableEffect.effect_sticker_id)\n        );\n\n        this.noPacks = true;\n\n        return this.renderEffects(availableEffects);\n      }\n    );\n\n    return [cached, renderPromise] as const;\n  }\n\n  public async init(message?: Message.message | Message.messageService) {\n    let cached: boolean, renderPromise: Promise<() => void>;\n    if(this.isEffects) {\n      [cached, renderPromise] = await this.prepareEffects();\n    } else {\n      [cached, renderPromise] = await this.prepareReactions(message);\n    }\n\n    if(cached) {\n      await renderPromise;\n    }\n\n    renderPromise.then((callback) => {\n      if(!callback) {\n        return;\n      }\n\n      if(cached) {\n        callback();\n      } else {\n        fastRaf(callback);\n      }\n    });\n\n    this.inited = true;\n  }\n\n  public cleanup() {\n    this.middlewareHelper.clean();\n    // this.scrollable.removeListeners();\n    this.reactionsMap.clear();\n    animationIntersector.setOverrideIdleGroup(this.animationGroup, false);\n    animationIntersector.checkAnimations(true, this.animationGroup, true);\n  }\n\n  // private onScroll = () => {\n  //   this.reactionsMap.forEach((players, div) => {\n  //     this.onScrollProcessItem(div, players);\n  //   });\n  // };\n\n  private reactionToDocId = (reaction: Reaction) => {\n    if(reaction._ === 'reactionPaid') return PAID_REACTION_EMOJI_DOCID;\n    let docId = (reaction as Reaction.reactionCustomEmoji).document_id;\n    if(!docId) {\n      const availableReaction = this.availableReactions.find((_reaction) => _reaction.reaction === (reaction as Reaction.reactionEmoji).emoticon);\n      docId = availableReaction.select_animation.id;\n    }\n\n    return docId;\n  };\n\n  private reactionsToDocIds = (reactions: Reaction[]) => {\n    return reactions.map(this.reactionToDocId);\n  };\n\n  private loadTags = () => {\n    const reactionsPromise = this.managers.appReactionsManager.getTagReactions()\n    .then(this.reactionsToDocIds);\n    return [reactionsPromise];\n  };\n\n  private loadEffects = () => {\n    const reactionsPromise = this.managers.appReactionsManager.getAvailableEffects()\n    .then((availableEffects) => {\n      return availableEffects.filter((availableEffect) => {\n        return !!availableEffect.effect_animation_id;\n      }).map((availableEffect) => availableEffect.effect_sticker_id);\n    }) as Promise<DocId[]>;\n    return [reactionsPromise];\n  };\n\n  private loadReactions = () => {\n    const topReactionsPromise = Promise.resolve(this.reactions)\n    // const topReactionsPromise = this.managers.appReactionsManager.getTopReactions()\n    .then(this.reactionsToDocIds);\n\n    const allRecentReactionsPromise = this.managers.appReactionsManager.getRecentReactions()\n    .then(this.reactionsToDocIds);\n\n    const topReactionsSlicedPromise = topReactionsPromise.then((docIds) => this.noPacks ? docIds : docIds.slice(0, 16));\n\n    const recentReactionsPromise = this.noPacks ? undefined : Promise.all([\n      topReactionsPromise,\n      allRecentReactionsPromise,\n      topReactionsSlicedPromise\n    ]).then(([topDocIds, recentDocIds, topSlicedDocIds]) => {\n      // filter recent reactions and add left top reactions\n      recentDocIds = recentDocIds.filter((docId) => !topSlicedDocIds.includes(docId));\n      recentDocIds.push(...topDocIds.slice(16));\n      return filterUnique(recentDocIds);\n    });\n\n    return [topReactionsSlicedPromise, recentReactionsPromise].filter(Boolean);\n  };\n\n  private onMoreClick = (e: MouseEvent) => {\n    cancelEvent(e);\n\n    const canShrink = this.noPacks && this.noSearch;\n\n    const emojiTab = new EmojiTab({\n      noRegularEmoji: true,\n      noPacks: this.noPacks,\n      noSearch: this.noSearch,\n      managers: this.managers,\n      mainSets: this.isTags ? this.loadTags : (this.isEffects ? this.loadEffects : this.loadReactions),\n      additionalLocalStickerSet: this.isEffects ? async() => {\n        const availableEffects = await this.managers.appReactionsManager.getAvailableEffects();\n        return (await this.splitAvailableEffects(availableEffects)).localStickerSet;\n      } : undefined,\n      onClick: async(emoji) => {\n        if(emoji.docId && emoji.emoji) {\n          const availableReactions = await apiManagerProxy.getAvailableReactions();\n          const hasNativeReaction = availableReactions.find((_reaction) => _reaction.select_animation?.id === emoji.docId);\n          if(hasNativeReaction) {\n            emoji.emoji = hasNativeReaction.reaction;\n            delete emoji.docId;\n          }\n        }\n\n        let reaction: Reaction;\n        if(emoji.docId === PAID_REACTION_EMOJI_DOCID) {\n          reaction = {_: 'reactionPaid'};\n        } else if(emoji.docId) {\n          reaction = {\n            _: 'reactionCustomEmoji',\n            document_id: emoji.docId\n          };\n        } else {\n          reaction = {\n            _: 'reactionEmoji',\n            emoticon: cleanEmoji(emoji.emoji) // * heart can be different, like '❤' and '❤️'\n          };\n        }\n\n        // * snapshot the clicked element (instant flight source) + kick off the\n        // * clean first-frame render that upgrades it\n        if(!this.isEffects) {\n          stashFlightSource(reaction, emoji.element);\n        }\n\n        deferred.resolve(reaction);\n        emoticonsDropdown.hideAndDestroy();\n      },\n      freeCustomEmoji: this.freeCustomEmoji,\n      onReady: () => {\n        const element = emoticonsDropdown.getElement();\n        // element.style.setProperty('--width', element.offsetWidth + 'px');\n        if(canShrink) {\n          const container = element.querySelector<HTMLElement>('.emoticons-categories-container');\n          element.style.setProperty('--height', container.offsetHeight + 'px');\n        }\n      },\n      searchFetcher: this.isEffects ? async(q) => {\n        const availableEffects = await this.managers.appReactionsManager.searchAvailableEffects({q});\n        return this.splitAvailableEffects(availableEffects);\n      } : async(q) => {\n        const emojis = await this.managers.appEmojiManager.prepareAndSearchEmojis({q, limit: Infinity, minChars: 1, addCustom: true});\n        return {\n          emojis: emojis.filter((emoji) => {\n            if(!emoji.docId) {\n              if(this.availableReactions) {\n                return this.availableReactions.some((availableReaction) => availableReaction.reaction === emoji.emoji);\n              }\n\n              return false;\n            }\n\n            return true;\n          })\n        };\n      },\n      groupFetcher: this.isEffects ? async(emojiGroup) => {\n        const availableEffects = await this.managers.appReactionsManager.searchAvailableEffects({emoticon: (emojiGroup as EmojiGroup.emojiGroup).emoticons});\n        return this.splitAvailableEffects(availableEffects);\n      } : undefined,\n      showLocks: this.isEffects\n    });\n\n    const emoticonsDropdown = new EmoticonsDropdown({\n      tabsToRender: [emojiTab],\n      // Mount into the active app window's body (a function so it resolves lazily at open time):\n      // while the client is popped into a Document PiP window the reactions menu lives there, so a\n      // hardcoded main-`document.body` would render this emoji picker into the now-background tab.\n      customParentElement: getOverlayRoot,\n      getOpenPosition: () => this.getOpenPosition(!this.noPacks)\n    });\n\n    if(canShrink) {\n      emoticonsDropdown.getElement().classList.add('shrink');\n    }\n\n    if(this.isEffects) {\n      emoticonsDropdown.getElement().classList.add('smaller');\n    }\n\n    const deferred = deferredPromise<Reaction>();\n    this.onFinish(deferred);\n    emoticonsDropdown.addEventListener('closed', () => {\n      deferred.resolve(undefined);\n      emoticonsDropdown.hideAndDestroy();\n    });\n\n    emoticonsDropdown.onButtonClick();\n  };\n\n  private async splitAvailableEffects(\n    availableEffects: AvailableEffect[]\n  ): Promise<Awaited<ReturnType<EmojiTab['searchFetcher']>>> {\n    const [stickers, customEmojis] = partition(availableEffects, (availableEffect) => !availableEffect.effect_animation_id);\n    const docIds = stickers.map((availableEffect) => availableEffect.effect_sticker_id);\n    const docs = await Promise.all(docIds.map((docId) => this.managers.appDocsManager.getDoc(docId)));\n    return {\n      emojis: customEmojis.map((availableEffect) => {\n        return {\n          emoji: '',\n          docId: availableEffect.effect_sticker_id\n        }\n      }),\n      localStickerSet: {\n        title: 'StickerEffects',\n        stickers: docs\n      }\n    };\n  }\n\n  private canUseAnimations() {\n    return liteMode.isAvailable('animations') && liteMode.isAvailable('stickers_chat') && !IS_MOBILE;\n  }\n\n  private async renderReaction(reaction: Reaction, availableReaction?: AvailableReaction) {\n    if(availableReaction) {\n      warmUpReactionEffect(availableReaction);\n    }\n\n    const reactionDiv = document.createElement('div');\n    reactionDiv.classList.add(REACTION_CLASS_NAME);\n\n    const scaleContainer = document.createElement('div');\n    scaleContainer.classList.add(REACTION_CLASS_NAME + '-scale');\n\n    const appearWrapper = document.createElement('div');\n    let selectWrapper: HTMLElement;;\n    appearWrapper.classList.add(REACTION_CLASS_NAME + '-appear');\n\n    if(this.canUseAnimations()) {\n      selectWrapper = document.createElement('div');\n      selectWrapper.classList.add(REACTION_CLASS_NAME + '-select', 'hide');\n    }\n\n    const players: ChatReactionsMenuPlayers = {\n      selectWrapper,\n      appearWrapper,\n      reaction\n    };\n    this.reactionsMap.set(reactionDiv, players);\n\n    const middleware = this.middlewareHelper.get();\n\n    const hoverScale = IS_TOUCH_SUPPORTED || !SCALE_ON_HOVER ? 1 : 1.25;\n    const size = REACTION_SIZE * hoverScale;\n\n    const loadPromises: Promise<any>[] = [];\n    const options = {\n      width: size,\n      height: size,\n      skipRatio: 1,\n      needFadeIn: false,\n      withThumb: false,\n      group: this.animationGroup,\n      middleware,\n      loadPromises\n    };\n\n    const canUseAnimations = this.canUseAnimations();\n    const isPaidReaction = reaction._ === 'reactionPaid';\n\n    this.container.append(reactionDiv);\n    if(isPaidReaction && !canUseAnimations) {\n      appearWrapper.append(StarsStar() as HTMLElement);\n    } else if(isPaidReaction && canUseAnimations) {\n      const promise = lottieLoader.loadAnimationAsAsset({\n        container: appearWrapper,\n        loop: false,\n        autoplay: true,\n        width: size,\n        height: size,\n        skipRatio: 1,\n        middleware,\n        group: this.animationGroup\n      }, 'StarReactionAppear').then((player) => {\n        players.appear = player;\n\n        const selectLoadPromise = lottieLoader.loadAnimationAsAsset({\n          container: selectWrapper,\n          loop: false,\n          autoplay: false,\n          ...options\n        }, 'StarReactionSelect');\n\n        player.addEventListener('enterFrame', (frameNo) => {\n          if(player.maxFrame === frameNo) {\n            selectLoadPromise.then((selectPlayer) => {\n              assumeType<LottiePlayer>(selectPlayer);\n              appearWrapper.classList.add('hide');\n              selectWrapper.classList.remove('hide');\n\n              players.select = selectPlayer;\n            }, noop);\n          }\n        });\n      });\n\n      loadPromises.push(promise);\n    } else if(!canUseAnimations || !availableReaction) {\n      delete options.needFadeIn;\n      delete options.withThumb;\n\n      const wrap = () => {\n        wrapSticker({\n          doc,\n          div: appearWrapper,\n          liteModeKey: false,\n          play: availableReaction === undefined ? true : undefined,\n          ...options\n        });\n      };\n\n      let doc = availableReaction?.static_icon, delay = false;\n      if(!doc) {\n        const result = await this.managers.acknowledged.appEmojiManager.getCustomEmojiDocument((reaction as Reaction.reactionCustomEmoji).document_id);\n        // * a custom emoji reaction fires the effect of its base emoji - warm\n        // * it up so the click plays it instead of the generic fallback\n        if(!this.isEffects && reaction._ === 'reactionCustomEmoji') {\n          Promise.resolve(result.result).then((doc) => {\n            return doc?.stickerEmojiRaw && Promise.resolve(apiManagerProxy.getReaction(doc.stickerEmojiRaw)).then((availableReaction) => {\n              availableReaction && warmUpReactionEffect(availableReaction);\n            });\n          }).catch(noop);\n        }\n\n        if(result.cached) {\n          doc = await result.result;\n        } else {\n          delete options.loadPromises;\n          delay = true;\n          result.result.then((_doc) => (doc = _doc, wrap()));\n        }\n      }\n\n      if(!delay) {\n        wrap();\n      }\n    } else {\n      let isFirst = true;\n      wrapSticker({\n        doc: availableReaction.appear_animation,\n        div: appearWrapper,\n        play: true,\n        liteModeKey: false,\n        ...options\n      }).then(({render}) => render).then((player) => {\n        assumeType<LottiePlayer>(player);\n\n        players.appear = player;\n\n        player.addEventListener('enterFrame', (frameNo) => {\n          if(player.maxFrame === frameNo) {\n            selectLoadPromise.then((selectPlayer) => {\n              assumeType<LottiePlayer>(selectPlayer);\n              appearWrapper.classList.add('hide');\n              selectWrapper.classList.remove('hide');\n\n              if(isFirst) {\n                players.select = selectPlayer;\n                isFirst = false;\n              }\n            }, noop);\n          }\n        });\n      }, noop);\n\n      const selectLoadPromise = wrapSticker({\n        doc: availableReaction.select_animation,\n        div: selectWrapper,\n        liteModeKey: false,\n        ...options\n      }).then(({render}) => render).then((player) => {\n        assumeType<LottiePlayer>(player);\n\n        return lottieLoader.waitForFirstFrame(player);\n      }).catch(noop);\n    }\n\n    scaleContainer.append(appearWrapper);\n    selectWrapper && scaleContainer.append(selectWrapper);\n    reactionDiv.append(scaleContainer);\n    // this.scrollable.append(reactionDiv);\n\n    return Promise.all(loadPromises);\n  }\n\n  // private onScrollProcessItem(div: HTMLElement, players: ChatReactionsMenuPlayers) {\n  //   // return;\n\n  //   const scaleContainer = div.firstElementChild as HTMLElement;\n  //   const visibleRect = getVisibleRect(div, this.scrollable.container);\n  //   let transform: string;\n  //   if(!visibleRect) {\n  //     if(!players.appearWrapper.classList.contains('hide') || !players.appear) {\n  //       return;\n  //     }\n\n  //     if(players.select) {\n  //       players.select.stop();\n  //     }\n\n  //     players.appear.stop();\n  //     players.appear.autoplay = true;\n  //     players.appearWrapper.classList.remove('hide');\n  //     players.selectWrapper.classList.add('hide');\n\n  //     transform = '';\n  //   } else if(visibleRect.overflow.left || visibleRect.overflow.right) {\n  //     const diff = Math.abs(visibleRect.rect.left - visibleRect.rect.right);\n  //     const scale = Math.min(diff ** 2 / REACTION_CONTAINER_SIZE ** 2, 1);\n\n  //     transform = 'scale(' + scale + ')';\n  //   } else {\n  //     transform = '';\n  //   }\n\n  //   if(CAN_USE_TRANSFORM) {\n  //     scaleContainer.style.transform = transform;\n  //   }\n  // }\n\n  private onMouseMove = (e: MouseEvent) => {\n    const reactionDiv = findUpClassName(e.target, REACTION_CLASS_NAME);\n    if(!reactionDiv) {\n      return;\n    }\n\n    const players = this.reactionsMap.get(reactionDiv);\n    if(!players) {\n      return;\n    }\n\n    // do not play select animation when appearing\n    if(!players.appear?.paused) {\n      return;\n    }\n\n    const player = players.select;\n    if(!player) {\n      return;\n    }\n\n    if(player.paused) {\n      player.autoplay = true;\n      player.restart();\n    }\n  };\n}\n","export default function isTargetAnInput(target: HTMLElement) {\n  return !!target && (target.tagName === 'INPUT' && !['checkbox', 'radio'].includes((target as HTMLInputElement).type)) || target.isContentEditable;\n}\n","import {StoryItem, MediaArea} from '@layer';\n\nexport default function getStoryRepostInfo(story: StoryItem.storyItem) {\n  const fwdFrom = story.fwd_from;\n  let mediaAreaChannelPost: MediaArea.mediaAreaChannelPost;\n  if(!fwdFrom) {\n    mediaAreaChannelPost = (story.media_areas || []).find((mediaArea) => mediaArea._ === 'mediaAreaChannelPost') as MediaArea.mediaAreaChannelPost;\n    if(!mediaAreaChannelPost) {\n      return;\n    }\n  }\n\n  return {fwdFrom, mediaAreaChannelPost};\n}\n","import liteMode from '@helpers/liteMode';\nimport {resolveElements} from '@solid-primitives/refs';\nimport {createListTransition} from '@vendor/createListTransition';\nimport {Accessor, createEffect, createRoot, FlowComponent, JSX, onCleanup} from 'solid-js';\n\nexport const TransitionGroup: FlowComponent<{\n  noWait?: Accessor<boolean>,\n  transitions: WeakMap<Element, Accessor<boolean>>\n}> = (props) => {\n  const observeElement = (element: Element, callback: () => void) => {\n    const transition = props.transitions.get(element);\n    createEffect((prev) => {\n      const t = transition();\n      if(prev || t) {\n        if(!t) {\n          callback();\n        }\n\n        return true;\n      }\n    });\n  };\n\n  const disposers: Map<Element, () => void> = new Map();\n  const exitElement = (element: Element, callback: () => void) => {\n    createRoot((dispose) => {\n      disposers.set(element, dispose);\n\n      observeElement(element, () => {\n        dispose();\n        callback();\n      });\n\n      onCleanup(() => {\n        if(disposers.get(element) === dispose) {\n          disposers.delete(element);\n        }\n      });\n    });\n  };\n\n  onCleanup(() => {\n    disposers.forEach((dispose) => dispose());\n  });\n\n  const listTransition = createListTransition(resolveElements(() => props.children).toArray, {\n    exitMethod: 'keep-relative',\n    onChange: ({added, removed, finishRemoved}) => {\n      for(const element of added) {\n        const dispose = disposers.get(element);\n        dispose?.();\n      }\n\n      if(props.noWait?.() || !liteMode.isAvailable('animations')) {\n        finishRemoved(removed);\n        return;\n      }\n\n      const filtered: Element[] = [];\n      for(const element of removed) {\n        if(!props.transitions.has(element)) {\n          filtered.push(element);\n          continue;\n        }\n\n        exitElement(element, () => {\n          finishRemoved([element]);\n        });\n      }\n\n      if(filtered.length) {\n        finishRemoved(filtered);\n      }\n    }\n  }) as unknown as JSX.Element;\n\n  return listTransition;\n};\n","import {GeoPoint} from '@layer';\n\nexport default function makeGoogleMapsUrl(geo: GeoPoint.geoPoint) {\n  return 'https://maps.google.com/maps?q=' + geo.lat + ',' + geo.long;\n}\n","import rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker'\nimport {Modify} from '@types';\n\nexport default async function wrapStickerEmoji(options: Modify<Parameters<typeof wrapSticker>[0], {\n  div: HTMLElement,\n  doc?: never,\n  loop?: never\n}>) {\n  const {\n    emoji,\n    div,\n    managers = rootScope.managers\n  } = options;\n  const doc = await managers.appStickersManager.getAnimatedEmojiSticker(emoji);\n  if(!doc) {\n    div.classList.add('media-sticker-wrapper');\n    throw new Error('no sticker');\n  }\n\n  return wrapSticker({\n    doc,\n    play: true,\n    loop: false,\n    ...options\n  });\n}\n","import PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\nimport {ChatType} from '@components/chat/chatType';\nimport {ChannelsSponsoredMessageReportResult, MessageReportOption, ReportResult, SponsoredMessageReportOption} from '@layer';\nimport {Accessor, createSignal, For, Setter, createResource, createEffect, onCleanup, createMemo, untrack, useContext} from 'solid-js';\nimport Section from '@components/section';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {TransitionGroup} from '@helpers/solid/transitionGroup';\nimport TransitionSlider from '@components/transition';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {toastNew} from '@components/toast';\nimport Icon from '@components/icon';\nimport rootScope from '@lib/rootScope';\nimport preloadAnimatedEmojiSticker from '@helpers/preloadAnimatedEmojiSticker';\nimport wrapStickerEmoji from '@components/wrappers/stickerEmoji';\nimport InputField from '@components/inputField';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport Button from '@components/buttonTsx';\nimport classNames from '@helpers/string/classNames';\nimport Row from '@components/rowTsx';\nimport Scrollable from '@components/scrollable2';\n\nconst STICKER_EMOJI = '👮‍♀️';\n\ntype ReportAdResult = ChannelsSponsoredMessageReportResult | ReportResult;\ntype ReportFn = (option: Uint8Array, text?: string) => Promise<ReportAdResult>;\n\nconst getTerminalState = (result: ReportAdResult) => {\n  const hasReported = result._ === 'channels.sponsoredMessageReportResultReported' || result._ === 'reportResultReported';\n  const hasHidden = result._ === 'channels.sponsoredMessageReportResultAdsHidden';\n  return hasReported || hasHidden ? {hasReported} : undefined;\n};\n\ntype ChooseOrComment =\n  ChannelsSponsoredMessageReportResult.channelsSponsoredMessageReportResultChooseOption |\n  ReportResult.reportResultChooseOption |\n  ReportResult.reportResultAddComment;\n\ntype RenderedSection = {\n  container: HTMLDivElement,\n  transition: Accessor<boolean>,\n  maxHeight: Accessor<number>,\n  prevText: string,\n  readyPromise: Promise<any>,\n  isComment: boolean\n};\n\nexport default function showReportAdPopup(\n  type: 'ad' | 'message' | 'story' | 'peer',\n  report: ReportFn,\n  onAdHide?: () => void,\n  onError?: (err: ApiError, option?: Uint8Array, text?: string) => boolean | void,\n  initial?: {option: Uint8Array, text?: string}\n) {\n  preloadAnimatedEmojiSticker(STICKER_EMOJI);\n\n  const finishReport = (hasReported: boolean) => {\n    onAdHide?.();\n    toastNew({langPackKey: type === 'ad' ? (hasReported ? 'Ads.Reported' : 'AdHidden') : 'Reported2'});\n  };\n\n  // * returns whether the popup should hide, and toasts otherwise\n  const handleError = (err: ApiError, option?: Uint8Array, text?: string) => {\n    console.error('report error', err);\n    if(onError?.(err, option, text)) {\n      return true;\n    }\n\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  };\n\n  function Inner(props: {reportResult: ReportAdResult}) {\n    const context = useContext(PopupContext);\n\n    const transitions = new WeakMap<HTMLElement, Accessor<boolean>>();\n    const [sections, setSections] = createSignal<RenderedSection[]>([]);\n    const [activeSection, setActiveSection] = createSignal<RenderedSection>();\n\n    function renderSection(result: ChooseOrComment, prevText?: string): RenderedSection {\n      const [option, setOption] = createSignal<SponsoredMessageReportOption | MessageReportOption>(undefined, {equals: false});\n      const [data] = createResource(() => option()?.option, (option) => report(option).catch((err: ApiError) => {\n        if(handleError(err, option)) {\n          context.hide();\n        }\n\n        setOption(); // reset for another click\n        return undefined as ReportAdResult;\n      }));\n\n      const onReport = (hasReported: boolean) => {\n        context.hide();\n        finishReport(hasReported);\n      };\n\n      createEffect(() => {\n        const _data = data();\n        if(!_data) {\n          return;\n        }\n\n        const terminal = getTerminalState(_data);\n        if(terminal) {\n          onReport(terminal.hasReported);\n          return;\n        }\n\n        const rendered = renderSection(_data as typeof result, untrack(option).text);\n        const middleware = createMiddleware().get();\n        rendered.readyPromise.then(() => {\n          if(!middleware()) return;\n          setSections((sections) => [\n            ...sections,\n            rendered\n          ]);\n        });\n        setOption(); // reset for another click\n      });\n\n      const [transition, setTransition] = createSignal(false);\n\n      let timeout: number;\n      const onTransition = (e: TransitionEvent) => {\n        if(e.target !== container) {\n          return;\n        }\n\n        const isStart = e.type === 'transitionstart';\n        setTransition(isStart);\n        clearTimeout(timeout);\n        if(isStart) { // * fix\n          timeout = window.setTimeout(() => {\n            setTransition(false);\n          }, 300);\n        }\n      };\n\n      let maxHeight: Accessor<number>, setMaxHeight: Setter<number>;\n      let stickerDiv: HTMLDivElement, inputField: InputField, sendButton: HTMLButtonElement;\n      let readyPromise: Promise<any> = Promise.resolve();\n      const isComment = result._ === 'reportResultAddComment';\n      if(isComment) {\n        stickerDiv = document.createElement('div');\n        const size = 130;\n        readyPromise = wrapStickerEmoji({\n          div: stickerDiv,\n          emoji: STICKER_EMOJI,\n          width: size,\n          height: size,\n          middleware: createMiddleware().get()\n        }).then(({render}) => render);\n        inputField = new InputField({\n          label: 'ReportHint',\n          maxLength: 512,\n          placeholder: result.pFlags.optional ? 'Report2CommentOptional' : 'Report2Comment',\n          required: !result.pFlags.optional\n        });\n\n        [maxHeight, setMaxHeight] = createSignal<number>();\n      } else {\n        maxHeight = () => 48 * result.options.length;\n      }\n\n      let container: HTMLDivElement, caption: HTMLDivElement;\n      const activeHeight = createMemo(() => {\n        const section = activeSection();\n        const height = section?.maxHeight();\n        return height && section.isComment && !isComment ? height - 64 : height;\n      });\n\n      const inner = isComment ? (\n        <>\n          {stickerDiv}\n          {inputField.container}\n        </>\n      ) : (\n        <For each={result.options}>\n          {(option) => {\n            return (\n              <Row clickable={() => setOption(option)}>\n                <Row.Title>{wrapEmojiText(option.text)}</Row.Title>\n                <Row.RightContent>{Icon('next', 'popup-report-ad-option-arrow-icon')}</Row.RightContent>\n              </Row>\n            );\n          }}\n        </For>\n      );\n\n      (\n        <Section\n          ref={container}\n          name={'title' in result ? wrapEmojiText(result.title) : undefined}\n          caption={type === 'ad' ? 'ReportAdLearnMore' : (isComment ? 'ReportInfo' : undefined)}\n          captionRef={(ref) => caption = ref}\n          class=\"popup-report-ad-tab tabs-tab\"\n          noShadow\n          noDelimiter\n          onTransitionStart={onTransition}\n          onTransitionEnd={onTransition}\n        >\n          <div class={classNames('popup-report-ad-tab-options')} style={{height: (activeHeight() || maxHeight()) + 'px'}}>\n            {inner}\n          </div>\n        </Section>\n      );\n\n      transitions.set(container, transition);\n      onCleanup(() => transitions.delete(container));\n\n      if(isComment) {\n        const [disabled, setDisabled] = createSignal(false);\n        (\n          <Button\n            ref={sendButton}\n            disabled={disabled()}\n            class=\"btn-primary btn-color-primary popup-report-ad-send-button\"\n            text=\"Report2Send\"\n            onClick={async() => {\n              setDisabled(true);\n              inputField.input.contentEditable = 'false';\n              try {\n                await report(result.option, inputField.value);\n                onReport(true);\n              } catch(err) {\n                if(handleError(err as ApiError, result.option, inputField.value)) {\n                  context.hide();\n                  return;\n                }\n\n                setDisabled(false);\n                inputField.input.contentEditable = 'true';\n              }\n            }}\n          />\n        );\n\n        const onChange = () => {\n          setDisabled(!inputField.isValid());\n          setMaxHeight((inputField.value ? inputField.container.offsetHeight : 54) + 142 + 147);\n        };\n\n        inputField.input.addEventListener('input', onChange);\n        onChange();\n\n        caption.classList.add('popup-report-ad-comment-caption')\n        caption.after(sendButton);\n      }\n\n      return {container, transition, maxHeight, prevText, readyPromise, isComment};\n    }\n\n    setSections([\n      renderSection(props.reportResult as ChooseOrComment)\n    ]);\n\n    createEffect(() => {\n      const _sections = sections();\n      transition(_sections.length - 1);\n      headerTransition(_sections.length === 1 ? 0 : 1);\n      if(!untrack(activeSection)) {\n        setActiveSection(_sections[_sections.length - 1]);\n      }\n    });\n\n    let container: HTMLDivElement;\n    const body = (\n      <div ref={container} class=\"popup-report-ad-tabs tabs-container\">\n        <TransitionGroup transitions={transitions}>\n          {sections().map(({container}) => container)}\n        </TransitionGroup>\n      </div>\n    );\n\n    const transition = TransitionSlider({\n      content: container,\n      type: 'tabs',\n      transitionTime: 150,\n      animateFirst: false,\n      onTransitionStartAfter: () => {\n        setActiveSection(sections()[sections().length - 1]);\n      }\n    });\n\n    const prevText = createMemo<string>((prev) => activeSection()?.prevText ?? prev);\n\n    const titleKey: LangPackKey = type === 'ad' ? 'ReportAd' : 'ReportChat';\n    let titleRef: HTMLDivElement;\n    const title = (\n      <div ref={titleRef} class=\"transition slide-fade\">\n        <div class=\"transition-item\">{i18n(titleKey)}</div>\n        <div class=\"transition-item\">\n          <div class=\"popup-report-ad-header-rows\">\n            <div class=\"popup-report-ad-header-title\">{i18n(titleKey)}</div>\n            <div class=\"popup-report-ad-header-subtitle\">{wrapEmojiText(prevText())}</div>\n          </div>\n        </div>\n      </div>\n    );\n\n    const headerTransition = TransitionSlider({\n      content: titleRef,\n      type: 'slide-fade',\n      transitionTime: 400,\n      isHeavy: false\n    });\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton\n            canGoBack={sections().length > 1}\n            onBackClick={() => {\n              setSections((sections) => sections.slice(0, -1));\n            }}\n          />\n          <PopupElement.Title>{title}</PopupElement.Title>\n        </PopupElement.Header>\n        <PopupElement.Body>\n          <Scrollable>\n            {body}\n          </Scrollable>\n        </PopupElement.Body>\n      </>\n    );\n  }\n\n  report(initial?.option ?? new Uint8Array, initial?.text).then((reportResult) => {\n    // * a seeded first request can complete the report right away\n    const terminal = getTerminalState(reportResult);\n    if(terminal) {\n      finishReport(terminal.hasReported);\n      return;\n    }\n\n    createPopup(() => (\n      <PopupElement\n        class=\"popup-report-ad\"\n        closable\n        old\n        show\n      >\n        <Inner reportResult={reportResult} />\n      </PopupElement>\n    ));\n  }, (err: ApiError) => {\n    handleError(err, initial?.option ?? new Uint8Array, initial?.text);\n  });\n}\n\nexport function showAdReport(\n  sponsoredMessage: {random_id: Uint8Array},\n  onAdHide?: () => void\n) {\n  showReportAdPopup(\n    'ad',\n    (option) => rootScope.managers.appMessagesManager.reportSponsoredMessage(sponsoredMessage.random_id, option),\n    onAdHide\n  );\n}\n\nexport function showMessageReport(peerId: PeerId, mids: number[], onFinish?: () => void) {\n  showReportAdPopup(\n    'message',\n    (option, text) => rootScope.managers.appMessagesManager.reportMessages(peerId, mids, option, text),\n    onFinish\n  );\n}\n\nexport function showPeerReport(peerId: PeerId) {\n  let selecting = false;\n  showReportAdPopup(\n    'peer',\n    (option, text) => rootScope.managers.appMessagesManager.reportMessages(peerId, [], option, text),\n    undefined,\n    (err, option, text) => {\n      if(err?.type !== 'MESSAGE_ID_REQUIRED') {\n        return false;\n      }\n\n      // * the server wants specific messages for this report option,\n      // * ask the user to select them like tdesktop does\n      if(!selecting) {\n        selecting = true;\n        selectMessagesToReport(peerId, option, text);\n      }\n\n      return true;\n    }\n  );\n}\n\n// * continuation of a peer report after MESSAGE_ID_REQUIRED: re-sends the report\n// * with the selected messages and the previously chosen option, the server\n// * resumes the flow from there (comment step, next options or reported)\nexport function showSelectedMessagesReport(\n  peerId: PeerId,\n  mids: number[],\n  option: Uint8Array,\n  text: string | undefined,\n  onFinish?: () => void\n) {\n  showReportAdPopup(\n    'peer',\n    (option, text) => rootScope.managers.appMessagesManager.reportMessages(peerId, mids, option, text),\n    onFinish,\n    undefined,\n    {option, text}\n  );\n}\n\nasync function selectMessagesToReport(peerId: PeerId, option: Uint8Array, text?: string) {\n  const {default: appImManager} = await import('@lib/appImManager');\n  const chat = appImManager.chat;\n  if(chat?.peerId !== peerId || chat.type !== ChatType.Chat) {\n    return;\n  }\n\n  chat.selection.enterReportSelection({option, text});\n  toastNew({langPackKey: 'Report2SelectMessages'});\n}\n\nexport function showStoryReport(peerId: PeerId, ids: number[], onFinish?: () => void) {\n  showReportAdPopup(\n    'story',\n    (option, text) => rootScope.managers.appStoriesManager.report(peerId, ids, option, text),\n    onFinish\n  );\n}\n","import classNames from '@helpers/string/classNames';\nimport styles from './featureDetailsIconSticker.module.scss';\nimport Icon from './icon';\n\nexport default function createFeatureDetailsIconSticker(icon: Icon, className?: string) {\n  const div = document.createElement('div');\n  div.className = classNames(styles.Container, className);\n  div.appendChild(Icon(icon, styles.Icon));\n  return div;\n}\n","import showFeatureDetailsPopup, {FeatureDetailsButton} from '@components/popups/featureDetails';\nimport {i18n} from '@lib/langPack';\nimport {useAppConfig} from '@stores/appState';\nimport {wrapStoriesStealthModeDuration} from '@components/wrappers/wrapDuration';\nimport usePremium from '@stores/premium';\nimport PopupPremium from '@components/popups/premium';\nimport rootScope from '@lib/rootScope';\nimport tsNow from '@helpers/tsNow';\nimport {slowModeTimer} from '@components/chat/utils';\nimport {onCleanup} from 'solid-js';\nimport createFeatureDetailsIconSticker from '@components/featureDetailsIconSticker';\n\nexport default async function showStoriesStealthModePopup(props: {\n  onActivate?: () => void,\n  onClose?: () => void\n} = {}) {\n  const appConfig = useAppConfig();\n  const isPremium = usePremium();\n\n  const stealthMode = await rootScope.managers.appStoriesManager.getStealthMode();\n  const getLeftCooldown = () => (stealthMode.cooldown_until_date || 0) - tsNow(true);\n\n  const getButton = (): FeatureDetailsButton => {\n    if(!isPremium()) {\n      return {\n        text: i18n('Stories.StealthMode.Unlock'),\n        onClick: () => {\n          PopupPremium.show({feature: 'stories'});\n        }\n      };\n    } else if(getLeftCooldown() > 0) {\n      const {element, dispose} = slowModeTimer(getLeftCooldown);\n      onCleanup(dispose);\n      return {\n        text: i18n('Stories.StealthMode.Cooldown', [element])\n      };\n    } else {\n      return {\n        text: i18n('Stories.StealthMode.Button'),\n        onClick: async() => {\n          const needToActivate = (stealthMode.active_until_date || 0) <= tsNow(true);\n          if(needToActivate) {\n            await rootScope.managers.appStoriesManager.activateStealthMode();\n          }\n\n          props.onActivate?.();\n        }\n      };\n    }\n  };\n\n  showFeatureDetailsPopup({\n    rows: [\n      {\n        icon: 'backward_5',\n        title: i18n('Stories.StealthMode.Row1.Title'),\n        subtitle: i18n('Stories.StealthMode.Row1.Subtitle', [\n          wrapStoriesStealthModeDuration(appConfig.stories_stealth_past_period)\n        ])\n      },\n      {\n        icon: 'forward_25',\n        title: i18n('Stories.StealthMode.Row2.Title'),\n        subtitle: i18n('Stories.StealthMode.Row2.Subtitle', [\n          wrapStoriesStealthModeDuration(appConfig.stories_stealth_future_period)\n        ])\n      }\n    ],\n    sticker: {\n      element: createFeatureDetailsIconSticker('eye2_filled', 'background-gradient-stories')\n    },\n    title: i18n('Stories.StealthMode.Title'),\n    subtitle: i18n('Stories.StealthMode.Subtitle'),\n    get buttons() {\n      return [getButton()];\n    },\n    onClose: props.onClose\n  });\n}\n","import {StoryItem} from '../../layer';\nimport rootScope from '../../lib/rootScope';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '../chat/paidMessagesInterceptor';\nimport {showSharingPickerPopup} from '../popups/pickUser';\n\nexport function handleShareStory(options: {\n  story: StoryItem,\n  peerId: PeerId,\n  onClose?: () => void\n  onSend?: (toPeerId: PeerId) => void\n}) {\n  showSharingPickerPopup({\n    onSelect: async(chosen) => {\n      const {peerId, monoforumThreadId} = chosen[0];\n      const storyPeerId = options.peerId;\n\n      const preparedPaymentResult = await PaidMessagesInterceptor.prepareStarsForPayment({messageCount: 1, peerId});\n      if(preparedPaymentResult === PAYMENT_REJECTED) throw new Error();\n\n      const inputPeer = await rootScope.managers.appPeersManager.getInputPeerById(storyPeerId);\n      rootScope.managers.appMessagesManager.sendOther({\n        peerId,\n        inputMedia: {\n          _: 'inputMediaStory',\n          id: options.story.id,\n          peer: inputPeer\n        },\n        confirmedPaymentResult: preparedPaymentResult,\n        replyToMonoforumPeerId: monoforumThreadId\n      });\n\n      options.onSend?.(peerId);\n    },\n    chatRightsActions: ['send_media'],\n    onCloseAfterTimeout: options.onClose\n  });\n}\n","/* @refresh reload */\n\nimport {animateSingle, cancelAnimationByKey} from '@helpers/animation';\nimport {bindActiveWindowListener, getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport overlayCounter from '@helpers/overlayCounter';\nimport throttle from '@helpers/schedulers/throttle';\nimport classNames from '@helpers/string/classNames';\nimport windowSize from '@helpers/windowSize';\nimport {Document, DocumentAttribute, GeoPoint, MediaArea, MessageMedia, Reaction, StoryItem, StoryView, User, Chat as MTChat, AvailableReaction, MessageEntity, StoriesStealthMode} from '@layer';\nimport animationIntersector from '@components/animationIntersector';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport PeerTitle from '@components/peerTitle';\nimport SwipeHandler from '@components/swipeHandler';\nimport styles from '@components/stories/viewer.module.scss';\nimport {createSignal, createEffect, JSX, For, Accessor, onCleanup, createMemo, mergeProps, splitProps, untrack, on, getOwner, runWithOwner, createRoot, ParentProps, Signal, onMount, Setter, createReaction, Show, createRenderEffect} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport {assign, Portal} from 'solid-js/web';\nimport rootScope from '@lib/rootScope';\nimport {Middleware} from '@helpers/middleware';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport wrapMessageEntities from '@lib/richTextProcessor/wrapMessageEntities';\nimport tsNow from '@helpers/tsNow';\nimport {LangPackKey, i18n, joinElementsWith} from '@lib/langPack';\nimport formatDuration, {DurationType} from '@helpers/formatDuration';\nimport {easeOutCubicApply} from '@helpers/easing/easeOutCubic';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport {onMediaCaptionClick} from '@components/mediaViewer';\nimport InputFieldAnimated from '@components/inputFieldAnimated';\nimport ChatInput from '@components/chat/input';\nimport appImManager from '@lib/appImManager';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from '@components/chat/chatType';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport emoticonsDropdown from '@components/emoticonsDropdown';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\nimport debounce from '@helpers/schedulers/debounce';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {formatDateAccordingToTodayNew, formatFullSentTime} from '@helpers/date';\nimport getVisibleRect from '@helpers/dom/getVisibleRect';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport {AvatarNew, avatarNew} from '@components/avatarNew';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport {SERVICE_PEER_ID} from '@appManagers/constants';\nimport idleController from '@helpers/idleController';\nimport OverlayClickHandler from '@helpers/overlayClickHandler';\nimport getStoryPrivacyType, {StoryPrivacyType} from '@appManagers/utils/stories/privacyType';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport StackedAvatars from '@components/stackedAvatars';\nimport PopupElement from '@components/popups';\nimport {processDialogElementForReaction} from '@components/popups/reactedList';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport focusInput from '@helpers/dom/focusInput';\nimport {wrapStoryMedia} from '@components/stories/preview';\nimport {StoriesContextPeerState, useStories, StoriesProvider} from '@components/stories/store';\nimport createUnifiedSignal from '@helpers/solid/createUnifiedSignal';\nimport setBlankToAnchor from '@lib/richTextProcessor/setBlankToAnchor';\nimport liteMode from '@helpers/liteMode';\nimport Icon from '@components/icon';\nimport {ChatReactionsMenu} from '@components/chat/reactionsMenu';\nimport setCurrentTime from '@helpers/dom/setCurrentTime';\nimport ReactionElement from '@components/chat/reaction';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport wrapSticker from '@components/wrappers/sticker';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport isTargetAnInput from '@helpers/dom/isTargetAnInput';\nimport {setQuizHint} from '@components/quizHint';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {resolveFirst} from '@solid-primitives/refs';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport formatNumber from '@helpers/number/formatNumber';\nimport callbackify from '@helpers/callbackify';\nimport {dispatchHeavyAnimationEvent} from '@hooks/useHeavyAnimationCheck';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport wrapReply from '@components/wrappers/reply';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport appSidebarRight from '@components/sidebarRight';\nimport AppStatisticsTab from '@components/sidebarRight/tabs/statistics';\nimport getStoryRepostInfo from '@appManagers/utils/stories/repostInfo';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport {Transition} from 'solid-transition-group';\nimport {TransitionGroup} from '@helpers/solid/transitionGroup';\nimport makeGoogleMapsUrl from '@helpers/makeGoogleMapsUrl';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport showTooltip from '@components/tooltip';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport {showStoryReport} from '@components/popups/reportAd';\nimport {useAppSettings} from '@stores/appSettings';\nimport showStoriesStealthModePopup from '@components/popups/storiesStealthMode';\nimport {useAppConfig} from '@stores/appState';\nimport {wrapStoriesStealthModeDuration} from '@components/wrappers/wrapDuration';\nimport {handleShareStory} from './share';\nimport createListenerSetter from '@helpers/solid/createListenerSetter';\n\nexport const STORY_DURATION = 5e3;\nconst STORY_HEADER_AVATAR_SIZE = 32;\nconst STORY_SCALE_SMALL = 0.33;\nconst STORIES_PRESERVE = 2;\nconst STORIES_PRESERVE_HIDDEN = 2;\nconst STORY_REPOST_ICON: Icon = 'storyrepost';\nlet CHANGELOG_PEER_ID = SERVICE_PEER_ID;\n\nrootScope.addEventListener('app_config', (appConfig) => {\n  const userId = appConfig.stories_changelog_user_id;\n  CHANGELOG_PEER_ID = userId ? userId.toPeerId(false) : SERVICE_PEER_ID;\n});\n\nconst x = new OverlayClickHandler(undefined, true);\n\nconst StorySlides = (props: {\n  state: StoriesContextPeerState,\n  index: Accessor<number>,\n  currentStory: Accessor<StoryItem>,\n  splitByDays?: boolean\n}) => {\n  let storyIndex: Accessor<number>, storiesForSlides: Accessor<StoryItem[]>;\n  if(props.splitByDays) {\n    const getStoryDateTimestamp = (storyItem: StoryItem.storyItem) => {\n      const timestamp = storyItem.date;\n      const date = new Date(timestamp * 1000);\n      date.setHours(0, 0, 0);\n      return date.getTime();\n    };\n\n    const storiesSplittedByDays = createMemo(() => {\n      const stories = props.state.stories;\n      const days: Record<number, StoryItem[]> = {};\n      (stories as StoryItem.storyItem[]).forEach((story) => {\n        const dateTimestamp = getStoryDateTimestamp(story);\n        (days[dateTimestamp] ??= []).push(story);\n      });\n      return days;\n    });\n\n    storiesForSlides = createMemo(() => {\n      const days = storiesSplittedByDays();\n      const story = props.currentStory();\n      const dateTimestamp = getStoryDateTimestamp(story as StoryItem.storyItem);\n      return days[dateTimestamp];\n    });\n\n    storyIndex = createMemo(() => {\n      const story = props.currentStory();\n      const stories = storiesForSlides();\n      // return props.state.index;\n      return stories.indexOf(story);\n    });\n  } else {\n    storiesForSlides = () => props.state.stories;\n    storyIndex = () => props.state.index;\n  }\n\n  const slides = (\n    <For each={storiesForSlides()}>\n      {(_, i) => <StorySlide {...mergeProps(props, {slideIndex: i, storyIndex})} />}\n    </For>\n  );\n\n  return slides;\n};\n\nconst StorySlide = (props: {\n  slideIndex: Accessor<number>,\n  state: StoriesContextPeerState,\n  storyIndex: Accessor<number>,\n  index: Accessor<number>\n}) => {\n  const [progress, setProgress] = createSignal(0);\n  const [stories] = useStories();\n\n  const calculateAndSetProgress = () => {\n    const elapsedTime = Date.now() - stories.startTime;\n    const progress = elapsedTime / stories.storyDuration;\n    setProgress(progress);\n  };\n\n  const onTick = () => {\n    if(\n      stories.peer !== props.state ||\n      props.storyIndex() !== props.slideIndex() ||\n      stories.paused\n    ) {\n      onPause();\n      return false;\n    }\n\n    // if(stories.paused) {\n    //   return true;\n    // }\n\n    calculateAndSetProgress();\n    return true;\n  };\n\n  const onPause = () => {\n    cancelAnimationByKey(ret);\n  };\n\n  const onPlay = () => {\n    animateSingle(onTick, ret);\n  };\n\n  createEffect(() => { // on peer change\n    if(stories.peer !== props.state) {\n      onPause();\n      return;\n    }\n\n    createEffect(on( // on story change\n      () => [props.storyIndex(), props.slideIndex()],\n      ([storyIndex, slideIndex]) => {\n        const isActive = storyIndex === slideIndex;\n        if(isActive) {\n          setProgress(undefined);\n\n          createEffect(() => { // on story toggle\n            if(stories.paused || stories.buffering) {\n              onPause();\n            } else {\n              onPlay();\n            }\n          });\n        } else {\n          onPause();\n          setProgress(storyIndex > slideIndex ? 1 : undefined);\n        }\n      })\n    );\n  });\n\n  const ret = (\n    <div\n      class={styles.ViewerStorySlidesSlide}\n      // classList={{[styles.active]: index() > slideIndex()}}\n      style={progress() !== undefined ? {'--progress': Math.min(100, progress() * 100) + '%'} : {}}\n    />\n  );\n\n  return ret;\n};\n\nconst DEFAULT_REACTION_EMOTICON = '❤';\nconst isDefaultReaction = (reaction: Reaction) => (reaction as Reaction.reactionEmoji)?.emoticon === DEFAULT_REACTION_EMOTICON;\n\nconst StoryInput = (props: {\n  state: StoriesContextPeerState,\n  currentStory: Accessor<StoryItem>,\n  isActive: Accessor<boolean>,\n  focusedSignal: Signal<boolean>,\n  inputEmptySignal: Signal<boolean>,\n  inputMenuOpenSignal: Signal<boolean>,\n  isPublic: Accessor<boolean>,\n  sendReaction: StorySendReaction,\n  shareStory: () => void,\n  reaction: Accessor<JSX.Element>,\n  onShareButtonClick: (e: MouseEvent, listenTo: HTMLElement) => void,\n  onMessageSent: () => void,\n  setInputReady: Setter<boolean>,\n  isFull: Accessor<boolean>\n}) => {\n  const [stories, actions] = useStories();\n  const [focused, setFocused] = props.focusedSignal;\n  const [inputEmpty, setInputEmpty] = props.inputEmptySignal;\n  const [inputMenuOpen, setInputMenuOpen] = props.inputMenuOpenSignal;\n  const [recording, setRecording] = createSignal(false);\n  const middlewareHelper = createMiddleware();\n  const middleware = middlewareHelper.get();\n\n  const chat = new Chat(appImManager, rootScope.managers, false, {elements: true, sharedMedia: true});\n  chat.setType(ChatType.Stories);\n  chat.isStandalone = true;\n\n  const onReactionClick = async() => {\n    const story = props.currentStory() as StoryItem.storyItem;\n    const isNewReaction = !story.sent_reaction;\n    const reaction: Reaction = !isNewReaction ? undefined : {_: 'reactionEmoji', emoticon: DEFAULT_REACTION_EMOTICON};\n    props.sendReaction({reaction, target: btnReactionEl});\n  };\n\n  let btnReactionEl: HTMLButtonElement;\n  const btnReaction = (\n    <ButtonIconTsx\n      ref={btnReactionEl}\n      onClick={onReactionClick}\n      tabIndex={-1}\n      class=\"btn-circle btn-reaction chat-input-secondary-button chat-secondary-button\"\n      noRipple={true}\n    >\n      {props.reaction()}\n    </ButtonIconTsx>\n  );\n\n  const input = chat.input = new ChatInput(chat, appImManager, rootScope.managers, 'stories-input');\n  input.noRipple = true;\n  input.btnReaction = btnReactionEl;\n  input.excludeParts = {\n    replyMarkup: true,\n    scheduled: true,\n    downButton: true,\n    reply: true,\n    forwardOptions: true,\n    mentionButton: true,\n    attachMenu: true,\n    commandsHelper: true,\n    botCommands: true,\n    emoticons: IS_MOBILE\n  };\n  input.globalMentions = true;\n  input.getMiddleware = (...args) => middleware.create().get(...args);\n\n  // const onMouseDown = (e: MouseEvent) => {\n  //   if(\n  //     focused() &&\n  //     !findUpClassName(e.target, styles.ViewerStoryPrivacy) &&\n  //     !findUpClassName(e.target, 'btn-icon') &&\n  //     !findUpClassName(e.target, styles.small) &&\n  //     !findUpAsChild(e.target as HTMLElement, input.emoticonsDropdown.getElement())\n  //   ) {\n  //     document.addEventListener('click', cancelEvent, {capture: true, once: true});\n  //   }\n\n  //   onFocusChange(false);\n  // };\n\n  const onClick = (e: MouseEvent) => {\n    // if(!inputEmpty()) {\n    //   return;\n    // }\n\n    const target = e.target as HTMLElement;\n    const good = !findUpClassName(target, styles.ViewerStoryReactions) && (\n      findUpClassName(target, styles.ViewerStory) ||\n      target.classList.contains(styles.Viewer)\n    );\n    if(!good) {\n      return;\n    }\n\n    cancelEvent(e);\n    setFocused(false);\n  };\n\n  onCleanup(() => {\n    if(navigationItem) {\n      appNavigationController.removeItem(navigationItem);\n      navigationItem = undefined;\n    }\n  });\n\n  let navigationItem: NavigationItem;\n  createEffect(\n    on(\n      () => focused(),\n      (focused) => {\n        if(focused) {\n          playAfterFocus = untrack(() => !stories.paused);\n          // document.addEventListener('mousedown', onMouseDown, {capture: true, once: true});\n          getAppWindow().document.addEventListener('click', onClick, {capture: true});\n          appNavigationController.pushItem(navigationItem = {\n            type: 'stories-focus',\n            onPop: () => {\n              setFocused(false);\n            }\n          });\n        } else {\n          // document.removeEventListener('mousedown', onMouseDown, {capture: true});\n          getAppWindow().document.removeEventListener('click', onClick, {capture: true});\n          appNavigationController.removeItem(navigationItem);\n          navigationItem = undefined;\n        }\n\n        actions.toggle(focused ? false : playAfterFocus);\n        input.freezeFocused(focused);\n        input.chatInput.classList.toggle('is-focused', focused);\n        // input.setShrinking(!focused);\n      },\n      {defer: true}\n    )\n  );\n\n  let playAfterFocus = false;\n  input.onFocusChange = (_focused: boolean) => {\n    if(input.emoticonsDropdown.isActive()) {\n      return;\n    }\n\n    if(!_focused) {\n      return;\n    }\n\n    setFocused(_focused);\n  };\n\n  let playAfter = false;\n  const onMenuToggle = (open: boolean) => {\n    if(open) {\n      playAfter = !stories.paused;\n    }\n\n    actions.toggle(open ? false : playAfter);\n    setInputMenuOpen(open);\n  };\n  input.onMenuToggle/*  = input.onRecording */ = onMenuToggle;\n  input.construct();\n  input.constructPeerHelpers();\n  // input.setShrinking(true);\n  // input.chatInput.classList.add(styles.hideOnSmall);\n  // input.rowsWrapper.classList.add('night');\n  input.messageInput.dataset.textColor = 'white';\n\n  createEffect(() => {\n    if(props.isActive()) {\n      const onOpen = (): void => (onMenuToggle(true)/* , setFocused(true) */, undefined);\n      const onClose = (): void => (onMenuToggle(false)/* , setFocused(false) */, undefined);\n      emoticonsDropdown.addEventListener('open', onOpen);\n      emoticonsDropdown.addEventListener('close', onClose);\n      emoticonsDropdown.chatInput = input;\n\n      onCleanup(() => {\n        emoticonsDropdown.removeEventListener('open', onOpen);\n        emoticonsDropdown.removeEventListener('close', onClose);\n      });\n    }\n  });\n\n  createEffect(() => {\n    input.chatInput.classList.toggle('is-private', !props.isPublic());\n    input.setCanForwardStory(props.isPublic());\n  });\n\n  createEffect(() => {\n    const [_focused, _recording, isPublic] = [focused(), recording(), props.isPublic()];\n    const isReactionButtonVisible = !_focused;\n    const isMainButtonVisible = _focused ? true : isPublic;\n    const isRecordingButtonVisible = _recording;\n    const visibleButtons = Math.min(2, [\n      isReactionButtonVisible,\n      isMainButtonVisible,\n      isRecordingButtonVisible\n    ].reduce((acc, v) => acc + +v, 0));\n    const chatInputSize = 48;\n    const chatInputBtnSendMargin = 8;\n    const chatInputPadding = props.isFull() ? 8 : 0;\n    const focusOffset = props.isFull() ? 0 : 135;\n    const width = stories.width - (chatInputSize + chatInputBtnSendMargin) * visibleButtons + (_focused ? focusOffset : 0) - chatInputPadding * 2;\n    input.rowsWrapper.style.setProperty('width', width + 'px', 'important');\n    input.chatInput.classList.toggle('is-focused', _focused);\n  });\n\n  const owner = getOwner();\n\n  chat.peerId = props.state.peerId;\n  chat.onChangePeer({\n    peerId: chat.peerId,\n    type: ChatType.Stories\n  }, middlewarePromise(middleware)).then(() => {\n    if(!middleware()) return;\n    return chat.finishPeerChange({\n      peerId: chat.peerId,\n      middleware\n    });\n  }).then(() => {\n    if(!middleware()) return;\n    props.setInputReady(true);\n\n    runWithOwner(owner, () => {\n      createEffect(() => {\n        input.setReplyTo({\n          replyToStoryId: props.currentStory().id\n        });\n      });\n\n      createEffect(async() => {\n        JSON.stringify(stories.stealthMode); // * track every key change\n        chat.stealthMode = stories.stealthMode;\n        input.updateMessageInputPlaceholder(await input.getPlaceholderParams());\n      });\n    });\n  });\n\n  onCleanup(() => {\n    input.onFocusChange =\n      input.onFileSelection =\n      input.onMenuToggle =\n      input.onRecording =\n      input.onUpdateSendBtn =\n      input.onMessageSent2 =\n      input.forwardStoryCallback =\n      undefined;\n    middlewareHelper.destroy();\n    chat.destroy();\n  });\n\n  input.onFileSelection = (promise) => {\n    onMenuToggle(true);\n    promise.finally(() => {\n      onMenuToggle(false);\n    });\n  };\n\n  input.onUpdateSendBtn = (icon) => {\n    setInputEmpty(icon === 'record' || icon === 'forward');\n  };\n\n  input.onMessageSent2 = () => {\n    blurActiveElement();\n    setFocused(false);\n    props.onMessageSent();\n  };\n\n  input.forwardStoryCallback = (e) => {\n    props.onShareButtonClick(e, input.btnSendContainer);\n  };\n\n  input.onRecording = (recording) => {\n    setRecording(recording);\n  };\n\n  return input.chatInput;\n};\n\nconst JOINER = ' • ';\n\nconst renderStoryReaction = async(props: {\n  reaction: Reaction,\n  uReaction: ReturnType<typeof createUnifiedSignal<JSX.Element>>,\n  div: HTMLDivElement,\n  size: number,\n  textColor: string,\n  play: boolean\n}) => {\n  let doc: Document.document;\n  const {reaction, div, size, textColor, play, uReaction} = props;\n  const isCustomEmoji = reaction._ === 'reactionCustomEmoji';\n  const middleware = createMiddleware().get();\n  uReaction(null);\n  let availableReaction: MaybePromise<AvailableReaction>;\n  if(isCustomEmoji) {\n    const result = await rootScope.managers.acknowledged.appEmojiManager.getCustomEmojiDocument(reaction.document_id);\n    if(!middleware()) return;\n    if(!result.cached) {\n      uReaction();\n    }\n\n    doc = await result.result;\n    availableReaction = apiManagerProxy.getReaction(doc.stickerEmojiRaw);\n  } else {\n    const availableReactionsResult = apiManagerProxy.getAvailableReactions();\n    if(availableReactionsResult instanceof Promise) {\n      uReaction();\n    }\n    const availableReactions = await availableReactionsResult;\n    if(!middleware()) return;\n    availableReaction = availableReactions.find((availableReaction) => reactionsEqual(reaction, availableReaction));\n    doc = /* availableReaction.center_icon ??  */play ? availableReaction.select_animation : availableReaction.static_icon;\n  }\n\n  // preload animation\n  availableReaction && callbackify(availableReaction, (availableReaction) => {\n    if(availableReaction?.around_animation) {\n      appDownloadManager.downloadMedia({\n        media: availableReaction.around_animation\n      });\n    }\n  });\n\n  const loadPromises: Promise<any>[] = [];\n  await wrapSticker({\n    div,\n    doc,\n    width: size,\n    height: size,\n    play,\n    // isCustomEmoji,\n    textColor,\n    middleware,\n    loadPromises,\n    loop: play || undefined\n  });\n\n  await Promise.all(loadPromises);\n  if(!middleware()) return;\n  uReaction(div);\n};\n\nconst StoryMediaArea = (props: {\n  story: StoryItem.storyItem,\n  mediaArea: MediaArea,\n  isActive: Accessor<boolean>,\n  setTooltipCloseCallback: Setter<() => void>,\n  setReady: Setter<boolean>,\n  sendReaction: StorySendReaction,\n  close: (callback?: () => void) => void,\n}) => {\n  const [stories, actions] = useStories();\n  const {x, y, w, h, rotation} = props.mediaArea.coordinates;\n  // const rotation = 10;\n  // const w = 100 / stories.width * 100;\n  // const h = 100 / stories.height * 100;\n  const playingMemo = createMemo((prev) => prev || (props.isActive() && stories.startTime));\n  const [children, setChildren] = createSignal<JSX.Element>();\n  const isLocation = createMemo(() => props.mediaArea._ === 'mediaAreaGeoPoint' || props.mediaArea._ === 'mediaAreaVenue');\n  const isReaction = createMemo(() => props.mediaArea._ === 'mediaAreaSuggestedReaction');\n  const isPost = createMemo(() => props.mediaArea._ === 'mediaAreaChannelPost');\n  const isLink = createMemo(() => props.mediaArea._ === 'mediaAreaUrl');\n\n  const onLocationClick = async() => {\n    const geoPoint = (props.mediaArea as MediaArea.mediaAreaGeoPoint).geo as GeoPoint.geoPoint;\n    const href = makeGoogleMapsUrl(geoPoint);\n\n    const onAnchorClick = async(e: MouseEvent) => {\n      if(ignoreClickEvent) {\n        ignoreClickEvent = false;\n        return;\n      }\n\n      hasPopup = true;\n      cancelEvent(e);\n      try {\n        await confirmationPopup({\n          descriptionLangKey: 'Popup.OpenInGoogleMaps',\n          button: {\n            langKey: 'Open'\n          }\n        });\n      } catch(err) {\n        if(wasPlaying) {\n          actions.play();\n        }\n\n        return;\n      }\n\n      ignoreClickEvent = true;\n      a.click();\n    };\n\n    let a: HTMLAnchorElement, ignoreClickEvent = false, hasPopup: boolean;\n    (\n      <a\n        ref={a}\n        href={href}\n        onClick={onAnchorClick}\n      >\n        {i18n('StoryViewLocation')}\n      </a>\n    );\n    setBlankToAnchor(a);\n    const wasPlaying = !stories.paused;\n    actions.pause();\n    const {close} = showTooltip({\n      element: div,\n      vertical: 'top',\n      textElement: a,\n      centerVertically: !!rotation,\n      onClose: () => {\n        if(hasPopup) {\n          hasPopup = false;\n          return;\n        }\n\n        if(wasPlaying) {\n          actions.play();\n        }\n      }\n    });\n    props.setTooltipCloseCallback(() => close);\n  };\n\n  const onReactionClick = () => {\n    const mediaArea = props.mediaArea as MediaArea.mediaAreaSuggestedReaction;\n    const size = stories.width * w / 100;\n    const multiplier = 2.6875;\n    props.sendReaction({\n      reaction: mediaArea.reaction,\n      target: div,\n      sizes: {\n        genericEffect: size * 0.375,\n        genericEffectSize: size * 1.5,\n        size,\n        effectSize: size * multiplier\n      },\n      textColor: mediaArea.pFlags.dark ? 'white' : undefined,\n      fireSame: true\n    });\n  };\n\n  const showNotCenteredTooltip = (_props: {\n    callback: () => void,\n    text: HTMLElement\n  }) => {\n    const a = anchorCallback(() => {\n      close();\n      _props.callback();\n    });\n    a.append(_props.text);\n    const wasPlaying = !stories.paused;\n    actions.pause();\n    const {close} = showTooltip({\n      element: div,\n      vertical: 'top',\n      textElement: a,\n      centerVertically: false,\n      onClose: () => {\n        if(wasPlaying) {\n          actions.play();\n        }\n      }\n    });\n    props.setTooltipCloseCallback(() => close);\n  };\n\n  const onPostClick = () => {\n    const openPost = () => {\n      props.close(() => {\n        const mediaArea = props.mediaArea as MediaArea.mediaAreaChannelPost;\n        appImManager.setInnerPeer({\n          peerId: mediaArea.channel_id.toPeerId(true),\n          lastMsgId: mediaArea.msg_id\n        });\n      });\n    };\n\n    showNotCenteredTooltip({\n      callback: openPost,\n      text: i18n('Story.ViewPost')\n    });\n  };\n\n  const onLinkClick = () => {\n    showNotCenteredTooltip({\n      callback: () => {\n        const url = (props.mediaArea as MediaArea.mediaAreaUrl).url;\n        if(wrapUrl(url).onclick) {\n          props.close(() => {\n            appImManager.openUrl(url);\n          });\n        } else {\n          safeWindowOpen(url);\n        }\n      },\n      text: i18n('OpenUrlTitle')\n    });\n  };\n\n  const onClick = (e: MouseEvent) => {\n    if(!props.isActive()) {\n      return;\n    }\n\n    cancelEvent(e);\n    onTypeClick(e);\n  };\n\n  const renderReaction = (mediaArea: MediaArea.mediaAreaSuggestedReaction) => {\n    const reaction = mediaArea.reaction;\n    const [count, setCount] = createSignal<number>(0);\n    const uReaction = createUnifiedSignal<JSX.Element>();\n    const size = stories.width * w / 100 * 0.72;\n\n    let div: HTMLDivElement;\n    (<div\n      ref={div}\n      class={classNames(\n        styles.ViewerStoryMediaAreaReactionInner,\n        count() && styles.hasCount\n      )}\n    />);\n\n    renderStoryReaction({\n      reaction,\n      uReaction,\n      div,\n      size,\n      textColor: mediaArea.pFlags.dark ? 'white' : undefined,\n      play: true\n    });\n\n    createRenderEffect(() => {\n      const views = props.story.views;\n      const reactions = views?.reactions;\n      const reactionCount = reactions?.find((reactionCount) => reactionsEqual(reactionCount.reaction, reaction));\n      setCount(reactionCount?.count ?? 0);\n    });\n\n    createEffect(() => {\n      const element = uReaction();\n      if(element === null) {\n        return;\n      }\n\n      setChildren((\n        <>\n          <div\n            class={classNames(\n              styles.ViewerStoryMediaAreaReactionBubbles,\n              mediaArea.pFlags.dark && styles.dark,\n              count() && styles.hasCount\n            )}\n          >\n            <div class={styles.ViewerStoryMediaAreaReactionBubble}></div>\n            <div class={classNames(styles.ViewerStoryMediaAreaReactionBubble, styles.small)}></div>\n          </div>\n          {element}\n          <div\n            class={classNames(\n              styles.ViewerStoryMediaAreaReactionCount,\n              mediaArea.pFlags.dark && styles.dark,\n              count() && styles.hasCount\n            )}\n            // style={{'font-size': size * .275 + 'px'}}\n            style={{'font-size': `calc(var(--stories-width) * ${w / 100 * 0.72 * .275})`}}\n          >\n            {count() ? formatNumber(count(), 1) : ''}\n          </div>\n        </>\n      ));\n      props.setReady(true);\n    });\n  };\n\n  let onTypeClick: (e: MouseEvent) => any;\n  if(isReaction()) {\n    onTypeClick = onReactionClick;\n    renderReaction(props.mediaArea as MediaArea.mediaAreaSuggestedReaction);\n  } else if(isLocation()) {\n    onTypeClick = onLocationClick;\n    props.setReady(true);\n  } else if(isPost()) {\n    onTypeClick = onPostClick;\n    props.setReady(true);\n  } else if(isLink()) {\n    onTypeClick = onLinkClick;\n    props.setReady(true);\n  } else {\n    props.setReady(true);\n  }\n\n  let div: HTMLDivElement;\n  return (\n    <div\n      ref={div}\n      class={classNames(\n        styles.ViewerStoryMediaArea,\n        ...(isLocation() ? [\n          playingMemo() && 'shimmer',\n          'shimmer-bright',\n          'shimmer-once'\n        ] : []),\n        ...(isReaction() ? [\n          styles.ViewerStoryMediaAreaReaction\n        ] : [])\n      )}\n      style={`left: ${x}%; top: ${y}%; width: ${w}%; height: ${h}%; --rotate: ${rotation}deg`}\n      onClick={onClick}\n    >\n      {children()}\n    </div>\n  );\n};\n\ntype StorySendReactionAnimation = {\n  reaction: Reaction | Promise<Reaction>,\n  target: HTMLElement,\n  sizes?: Parameters<(typeof ReactionElement)['fireAroundAnimation']>[0]['sizes'],\n  textColor?: string,\n  fireSame?: boolean\n};\ntype StorySendReaction = (params: StorySendReactionAnimation) => void;\n\nconst Stories = (props: {\n  state: StoriesContextPeerState,\n  index: Accessor<number>,\n  splitByDays?: boolean,\n  pinned?: boolean,\n  onReady?: () => void,\n  close: (callback?: () => void) => void,\n  peers: StoriesContextPeerState[],\n  isFull: Accessor<boolean>,\n  transitionSignal: Signal<boolean>\n}) => {\n  const avatar = AvatarNew({\n    size: STORY_HEADER_AVATAR_SIZE,\n    peerId: props.state.peerId,\n    isDialog: false\n  });\n  avatar.node.classList.add(styles.ViewerStoryHeaderAvatar);\n  const isMe = rootScope.myId === props.state.peerId;\n  const peerTitle = !isMe && new PeerTitle();\n  let peerTitleElement: HTMLElement;\n  if(peerTitle) {\n    peerTitle.update({peerId: props.state.peerId, dialog: false});\n    peerTitleElement = peerTitle.element;\n  } else {\n    peerTitleElement = i18n('YourStory');\n  }\n\n  peerTitleElement.classList.add(styles.ViewerStoryHeaderName);\n\n  // * `wasPlaying` is resolved in the body, not as a parameter default: the production\n  // * minifier binds a closure variable read from a parameter default to the wrong symbol\n  const wasPlayingOr = (wasPlaying?: boolean) => wasPlaying ?? !stories.paused;\n  const bindOnAnyPopupClose = (wasPlaying?: boolean) => {\n    const _wasPlaying = wasPlayingOr(wasPlaying);\n    return () => onAnyPopupClose(_wasPlaying);\n  };\n  const onAnyPopupClose = (wasPlaying: boolean) => {\n    if(wasPlaying) {\n      actions.play();\n    }\n  };\n\n  const onShareClick = (_wasPlaying?: boolean) => {\n    const wasPlaying = wasPlayingOr(_wasPlaying);\n    actions.pause();\n    handleShareStory({\n      story: currentStory(),\n      peerId: props.state.peerId,\n      onSend: async(toPeerId: PeerId) => {\n        showMessageSentTooltip(\n          i18n(\n            toPeerId === rootScope.myId ? 'StorySharedToSavedMessages' : 'StorySharedTo',\n            [await wrapPeerTitle({peerId: toPeerId})]\n          )\n        )\n      },\n      onClose: bindOnAnyPopupClose(wasPlaying)\n    })\n  };\n\n  const onShareButtonClick = (e: MouseEvent, listenTo: HTMLElement) => {\n    const story = currentStory() as StoryItem.storyItem;\n    if(story.pFlags.noforwards) {\n      const {open} = createContextMenu({\n        buttons: [{\n          icon: 'link',\n          text: 'CopyLink',\n          onClick: copyLink\n        }],\n        listenTo: listenTo,\n        ...topMenuOptions\n      });\n      open(e);\n    } else {\n      onShareClick();\n    }\n  };\n\n  const avatarInfo = AvatarNew({\n    size: 162/* 54 */,\n    peerId: props.state.peerId,\n    isDialog: false,\n    withStories: true,\n    storyColors: {\n      read: 'rgba(255, 255, 255, .3)'\n    }\n  });\n  avatarInfo.node.classList.add(styles.ViewerStoryInfoAvatar);\n  let peerTitleInfoElement: HTMLElement;\n  if(isMe) {\n    peerTitleInfoElement = i18n('MyStory');\n  } else {\n    const peerTitleInfo = new PeerTitle();\n    peerTitleInfo.update({peerId: props.state.peerId, dialog: false, onlyFirstName: true});\n    peerTitleInfoElement = peerTitleInfo.element;\n  }\n  peerTitleInfoElement.classList.add(styles.ViewerStoryInfoName);\n\n  const [stories, actions] = useStories();\n  const [content, setContent] = createSignal<JSX.Element>();\n  const [videoDuration, setVideoDuration] = createSignal<number>();\n  const [caption, setCaption] = createSignal<JSX.Element>();\n  const [repost, setRepost] = createSignal<{reply: JSX.Element, header: JSX.Element}>();\n  const [reaction, setReaction] = createSignal<JSX.Element>();\n  const [captionOpacity, setCaptionOpacity] = createSignal(0);\n  const [captionActive, setCaptionActive] = createSignal(false);\n  const [date, setDate] = createSignal<{timestamp: number, edited?: boolean}>();\n  const [loading, setLoading] = createSignal(false);\n  const [canShareStory, setCanShareStory] = createSignal();\n  const focusedSignal = createSignal(false);\n  const sendingReactionSignal = createSignal<StorySendReactionAnimation>();\n  const inputEmptySignal = createSignal(true);\n  const inputMenuOpenSignal = createSignal(false);\n  const isPublicSignal = createSignal(false);\n  const [focused, setFocused] = focusedSignal;\n  const [sendingReaction, setSendingReaction] = sendingReactionSignal;\n  const [inputEmpty] = inputEmptySignal;\n  const [inputMenuOpen] = inputMenuOpenSignal;\n  const [isPublic, setIsPublic] = isPublicSignal;\n  const [noSound, setNoSound] = createSignal(false);\n  const [sliding, setSliding] = props.transitionSignal;\n  const [privacyType, setPrivacyType] = createSignal<StoryPrivacyType>();\n  const [mediaAreas, setMediaAreas] = createSignal<JSX.Element>();\n  const [stackedAvatars, setStackedAvatars] = createSignal<StackedAvatars>();\n  const [tooltipCloseCallback, setTooltipCloseCallback] = createSignal<VoidFunction>();\n  const [reactionsMenu, setReactionsMenu] = createSignal<ChatReactionsMenu>();\n  const currentStory = createMemo(() => props.state.stories[props.state.index]);\n  const isExpired = createMemo(() => {\n    const story = currentStory();\n    const expireDate = (story as StoryItem.storyItem).expire_date;\n    if(!expireDate) return false;\n    return expireDate <= tsNow(true);\n  });\n  const isActive = createMemo(() => stories.peer === props.state);\n  const [forceReaction, setForceReaction] = createSignal(false, {equals: false});\n\n  let currentStoryMiddleware: Middleware;\n  createEffect(() => {\n    currentStory();\n    currentStoryMiddleware = createMiddleware().get();\n  });\n\n  const fireReactionAnimation = (reaction: Reaction, params = untrack(() => sendingReaction())) => {\n    if(!params || params.target === storyDiv) {\n      return;\n    }\n\n    const sizes = params.sizes ?? {\n      genericEffect: 26,\n      genericEffectSize: 100,\n      size: 22 + 18,\n      effectSize: 80\n    };\n\n    ReactionElement.fireAroundAnimation({\n      middleware: params.fireSame ? currentStoryMiddleware : createMiddleware().get(),\n      reaction,\n      sizes,\n      stickerContainer: params.target,\n      cache: params.fireSame ? {} : params.target as any,\n      textColor: params.textColor\n    });\n  };\n\n  createEffect(() => {\n    const reaction = (currentStory() as StoryItem.storyItem).sent_reaction;\n    if(!reaction) {\n      return;\n    }\n\n    // ! DO NOT REMOVE ! it handles update, since I don't observe any property in reaction\n    (reaction as Reaction.reactionCustomEmoji)?.document_id;\n    forceReaction();\n    fireReactionAnimation(reaction);\n  });\n\n  const sendReaction: StorySendReaction = async(params) => {\n    let {reaction} = params;\n    const peerId = props.state.peerId;\n    const story = currentStory() as StoryItem.storyItem;\n    const storyId = story.id;\n    const sentReaction = story.sent_reaction;\n\n    // * wait for picker\n    if(reaction instanceof Promise) {\n      reaction = await reaction;\n      if(!reaction) {\n        return;\n      }\n    }\n\n    const isNewReaction = !reactionsEqual(sentReaction, reaction);\n    if(!isNewReaction && !params.fireSame) {\n      reaction = undefined;\n    }\n\n    setFocused(false);\n    setSendingReaction(params);\n\n    if(!isNewReaction && params.fireSame) {\n      setForceReaction(true);\n    }\n\n    await rootScope.managers.acknowledged.appStoriesManager.sendReaction(\n      peerId,\n      storyId,\n      unwrap(reaction as Reaction)\n    );\n    setSendingReaction();\n  };\n\n  const createReactionsMenu = () => {\n    const [inited, setInited] = createSignal(false);\n    const middleware = createMiddleware().get();\n    const menu = new ChatReactionsMenu({\n      managers: rootScope.managers,\n      type: 'horizontal',\n      middleware,\n      onFinish: (reaction) => sendReaction({reaction, target: storyDiv}),\n      size: 36,\n      openSide: 'top',\n      getOpenPosition: () => undefined,\n      noMoreButton: true\n    });\n\n    menu.widthContainer.classList.add(styles.ViewerStoryReactions);\n\n    menu.init().finally(() => {\n      setInited(true);\n    });\n\n    let timeout: number;\n    createEffect(() => {\n      if(!inited()) {\n        return;\n      }\n\n      const isVisible = shouldMenuBeVisible();\n      menu.widthContainer.classList.toggle('is-visible', isVisible);\n\n      if(!isVisible) {\n        timeout = window.setTimeout(() => {\n          setReactionsMenu();\n          menu.cleanup();\n        }, liteMode.isAvailable('animations') ? 200 : 0);\n      } else {\n        clearTimeout(timeout);\n      }\n    });\n\n    setReactionsMenu(menu);\n  };\n\n  const shouldMenuBeVisible = () => focused() && inputEmpty() && !inputMenuOpen();\n  const haveToCreateMenu = createMemo(() => {\n    return reactionsMenu() ? true : shouldMenuBeVisible();\n  });\n\n  createEffect(() => {\n    if(haveToCreateMenu()) {\n      createReactionsMenu();\n    }\n  });\n\n  const setVideoListeners = (video: HTMLVideoElement) => {\n    let cleaned = false;\n    onCleanup(() => {\n      cleaned = true;\n      video.pause();\n      // video.src = '';\n      // video.load();\n      video.removeEventListener('waiting', onWaiting);\n      video.removeEventListener('canplay', onCanPlay);\n    });\n\n    const onCanPlay = () => {\n      setLoading(false);\n      if(isActive()) {\n        actions.setBuffering(false);\n      }\n    };\n\n    const onWaiting = () => {\n      const loading = video.networkState === video.NETWORK_LOADING;\n      const isntEnoughData = video.readyState < video.HAVE_FUTURE_DATA;\n\n      if(loading && isntEnoughData) {\n        setLoading(true);\n        if(isActive()) {\n          actions.setBuffering(true);\n        }\n        video.addEventListener('canplay', onCanPlay, {once: true});\n      }\n    };\n\n    const reset = () => {\n      if(!video.currentTime) {\n        return;\n      }\n\n      setCurrentTime(video, 0);\n    };\n\n    video.addEventListener('waiting', onWaiting);\n\n    onCleanup(() => {\n      if(stories.buffering) {\n        actions.setBuffering(false);\n      }\n    });\n\n    // pause the video on viewer pause or story change\n    createEffect(() => {\n      if(stories.paused || !isActive()) {\n        video.pause();\n      } else {\n        video.play();\n      }\n    });\n\n    const onFirstActive = () => {\n      // seek to start on story change\n      createEffect(on(\n        () => [/* props.state.index,  */isActive()],\n        ([/* index,  */isActive]) => {\n          if(isActive) {\n            return;\n          }\n\n          reset();\n        }\n      ));\n\n      createEffect(() => {\n        video.muted = stories.muted;\n      });\n    };\n\n    if(isActive()) {\n      onFirstActive();\n    } else {\n      createReaction(onFirstActive)(() => isActive());\n    }\n\n    const story = untrack(() => currentStory());\n    createEffect(() => {\n      if(isActive() && !stories.startTime && currentStory() === story) {\n        reset();\n      }\n    });\n\n    if(!untrack(noSound)) {\n      const [appSettings, setAppSettings] = useAppSettings();\n      if(!cleaned && !appSettings.seenTooltips.storySound) {\n        const playingMemo = createMemo((prev) => prev || (isActive() && stories.startTime));\n        createEffect(() => {\n          if(playingMemo()) {\n            const {close} = showTooltip({\n              ...muteTooltipOptions,\n              textElement: i18n('Story.SoundTooltip')\n            });\n            setTooltipCloseCallback(() => close);\n          }\n        });\n\n        setAppSettings('seenTooltips', 'storySound', true);\n      }\n    }\n  };\n\n  const setStoryMeta = (story: StoryItem.storyItemSkipped | StoryItem.storyItem) => {\n    let privacyType = getStoryPrivacyType(story as StoryItem.storyItem);\n    if(/* !isMe &&  */privacyType === 'public') {\n      privacyType = undefined;\n    }\n\n    const messageMedia = unwrap((story as StoryItem.storyItem).media);\n    const document = (messageMedia as MessageMedia.messageMediaDocument)?.document as Document.document;\n    const videoAttribute = document && document.attributes.find((attribute) => attribute._ === 'documentAttributeVideo') as DocumentAttribute.documentAttributeVideo;\n    const noSound = videoAttribute ? !!videoAttribute.pFlags.nosound : false;\n    const videoDuration = videoAttribute?.duration;\n    const date = story.date;\n    const edited = (story as StoryItem.storyItem).pFlags.edited;\n    const isPublic = !!(story as StoryItem.storyItem).pFlags.public;\n    const peer = apiManagerProxy.getPeer(props.state.peerId);\n    const usernames = getPeerActiveUsernames(peer);\n\n    setPrivacyType(privacyType);\n    setDate({timestamp: date, edited});\n    setNoSound(noSound);\n    setVideoDuration(videoDuration && (videoDuration * 1000));\n    setIsPublic(isPublic);\n    setCanShareStory(isPublic && (!(story as StoryItem.storyItem).pFlags.noforwards || !!usernames[0]));\n    // shareButton.classList.toggle('hide', !isPublic);\n  };\n\n  const setStory = async(story: StoryItem) => {\n    setLoading(true);\n    if(story._ !== 'storyItem') {\n      setStackedAvatars();\n      setContent();\n      setCaption();\n      setReaction();\n      setMediaAreas();\n      setRepost();\n      setStoryMeta(story as StoryItem.storyItemSkipped);\n      rootScope.managers.appStoriesManager.getStoryById(props.state.peerId, story.id);\n      props.onReady?.();\n      return;\n    }\n\n    const middleware = createMiddleware().get();\n    const uStackedAvatars = isMe ? createUnifiedSignal<StackedAvatars>() : undefined;\n    const uCaption = createUnifiedSignal<JSX.Element>();\n    const uContent = createUnifiedSignal<JSX.Element>();\n    const uReaction = createUnifiedSignal<JSX.Element>();\n    const uMediaAreas = createUnifiedSignal<JSX.Element>();\n    const uRepost = createUnifiedSignal<{reply: JSX.Element, header: JSX.Element}>();\n    const recentViewersMemo = isMe ? createMemo<UserId[]>((previousRecentViewers) => {\n      const views = story.views;\n      const recentViewers = views?.recent_viewers;\n      if(previousRecentViewers?.join() === recentViewers?.join()) {\n        return previousRecentViewers;\n      }\n      return recentViewers;\n    }) : undefined;\n\n    const getRichTextOptions = (\n      peerId: PeerId,\n      entities: MessageEntity[],\n      loadPromises?: Promise<any>[]\n    ): WrapRichTextOptions => {\n      return {\n        entities,\n        middleware,\n        textColor: 'white',\n        loadPromises,\n        passMaskedLinks: CHANGELOG_PEER_ID === peerId\n      };\n    };\n\n    isMe && createEffect(async() => {\n      let stackedAvatars: StackedAvatars;\n      const recentViewers = recentViewersMemo();\n      if(recentViewers?.length) {\n        stackedAvatars = new StackedAvatars({\n          avatarSize: 30,\n          middleware\n        });\n\n        const peerIds = recentViewers.map((userId) => {\n          return userId.toPeerId(false);\n        });\n\n        uStackedAvatars(null);\n        await stackedAvatars.render(peerIds);\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      uStackedAvatars(stackedAvatars);\n    });\n\n    createEffect(async() => {\n      let captionNode: JSX.Element;\n      const {caption, entities} = story;\n      if(caption?.trim()) {\n        const loadPromises: Promise<any>[] = [];\n        const {message, totalEntities} = wrapMessageEntities(caption, entities?.slice());\n        const wrapped = wrapRichText(\n          message,\n          getRichTextOptions(props.state.peerId, totalEntities, loadPromises)\n        );\n\n        uCaption(null);\n        await Promise.all(loadPromises);\n        if(!middleware()) {\n          return;\n        }\n\n        captionNode = documentFragmentToNodes(wrapped);\n      }\n\n      uCaption(captionNode);\n    });\n\n    createEffect(() => {\n      const media = untrack(() => getMediaFromMessage(story));\n      const mediaId = media.id;\n      if(!mediaId) {\n        uContent();\n        return;\n      }\n\n      uContent(null);\n\n      const wrapped = wrapStoryMedia({\n        peerId: props.state.peerId,\n        storyItem: unwrap(story),\n        forViewer: true,\n        containerProps: {\n          class: styles.ViewerStoryContentMediaContainer\n        },\n        childrenClassName: styles.ViewerStoryContentMedia,\n        useBlur: 40\n      });\n\n      const onReady = () => {\n        uContent(wrapped.container);\n      };\n\n      const onLoad = () => {\n        if(!middleware()) {\n          return;\n        }\n\n        setLoading(false);\n        untrack(() => playOnOpen());\n        // props.onReady?.();\n      };\n\n      const onMedia = () => {\n        const media = wrapped.media();\n\n        if(media instanceof HTMLVideoElement) {\n          setVideoListeners(media);\n          onMediaLoad(media).then(onLoad);\n        } else {\n          onLoad();\n        }\n      };\n\n      createReaction(onReady)(() => wrapped.ready());\n      createReaction(onMedia)(() => wrapped.media());\n    });\n\n    createEffect(() => {\n      let reactionNode: JSX.Element;\n      const sentReaction = story.sent_reaction;\n      const isDefault = isDefaultReaction(sentReaction);\n      if(!sentReaction || isDefault) {\n        reactionNode = Icon('reactions_filled', ...['btn-reaction-icon', isDefault && 'btn-reaction-default'].filter(Boolean));\n        uReaction(reactionNode);\n      } else {\n        const div = document.createElement('div');\n        div.classList.add('btn-reaction-sticker', 'night');\n        renderStoryReaction({\n          reaction: sentReaction,\n          uReaction,\n          div,\n          size: 26,\n          textColor: 'white',\n          play: false\n        });\n      }\n    });\n\n    createEffect(() => {\n      if(!(story as StoryItem.storyItem).media_areas?.length) {\n        uMediaAreas();\n        return;\n      }\n\n      uMediaAreas(null);\n\n      const [allReady, setAllReady] = createSignal(false);\n      const [readyCount, setReadyCount] = createSignal(0);\n      const mediaAreas = (\n        <For each={(story as StoryItem.storyItem).media_areas}>\n          {(mediaArea) => {\n            const [ready, setReady] = createSignal(false);\n\n            createReaction(() => {\n              setReadyCount((count) => count + 1);\n              if(readyCount() === (story as StoryItem.storyItem).media_areas.length) {\n                setAllReady(true);\n              }\n            })(ready);\n\n            return (\n              <StoryMediaArea\n                story={story}\n                mediaArea={mediaArea}\n                isActive={isActive}\n                setTooltipCloseCallback={setTooltipCloseCallback}\n                setReady={setReady}\n                sendReaction={sendReaction}\n                close={props.close}\n              />\n            );\n          }}\n        </For>\n      );\n\n      createReaction(() => {\n        uMediaAreas(mediaAreas);\n      })(allReady);\n    });\n\n    createEffect(async() => {\n      const repostInfo = getStoryRepostInfo(story);\n      if(!repostInfo) {\n        uRepost();\n        return;\n      }\n\n      const {fwdFrom, mediaAreaChannelPost} = repostInfo;\n      uRepost(null);\n\n      const [headerContent, setHeaderContent] = createSignal<JSX.Element>();\n      const [subtitle, setSubtitle] = createSignal<JSX.Element>();\n\n      const ret: {reply: JSX.Element, header: JSX.Element} = {\n        header: (\n          <span class={styles.ViewerStoryHeaderRepost}>\n            {headerContent()}\n          </span>\n        )\n      } as any;\n\n      let fwdFromPeerId: PeerId, fwdFromName: string, fwdFromStoryId: number;\n      if(fwdFrom) {\n        fwdFromPeerId = fwdFrom.from && getPeerId(fwdFrom.from);\n        fwdFromName = fwdFrom.from_name;\n        fwdFromStoryId = fwdFrom.story_id;\n      } else {\n        fwdFromPeerId = mediaAreaChannelPost.channel_id.toPeerId(true);\n      }\n\n      const peerTitleOptions: Parameters<typeof wrapPeerTitle>[0] = {\n        peerId: fwdFromPeerId,\n        fromName: fwdFromName\n      };\n\n      const {node, readyThumbPromise} = avatarNew({\n        peerId: fwdFromPeerId,\n        peerTitle: fwdFromName,\n        size: 16,\n        // props: {\n        //   class: styles.ViewerStoryHeaderRepostAvatar\n        // },\n        middleware\n      });\n\n      const subtitleElement = (\n        <span>{subtitle()}</span>\n      );\n\n      const processStoryPromise = async(promise: Promise<StoryItem.storyItem>, cached: boolean) => {\n        const storyItem = await promise;\n        if(!middleware()) {\n          return;\n        }\n\n        if(cached && !storyItem.caption) {\n          setSubtitle(i18n('Story'));\n          return;\n        }\n\n        const loadPromises: Promise<any>[] = [];\n        const {message, totalEntities} = wrapMessageEntities(storyItem.caption, storyItem.entities?.slice());\n        const wrapped = wrapRichText(\n          message,\n          getRichTextOptions(fwdFromPeerId, totalEntities, loadPromises)\n        );\n        await Promise.all(loadPromises);\n        if(!middleware()) {\n          return;\n        }\n\n        setSubtitle(documentFragmentToNodes(wrapped));\n      };\n\n      const storyPromise = fwdFromStoryId && rootScope.managers.acknowledged.appStoriesManager.getStoryById(\n        fwdFromPeerId,\n        fwdFromStoryId\n      ).then(async(ackedResult) => {\n        const promise = processStoryPromise(ackedResult.result, ackedResult.cached);\n        if(!ackedResult.cached) {\n          setSubtitle(i18n('Story'));\n          return;\n        }\n\n        return promise;\n      });\n\n      const [reply, headerPeerTitle, headerAvatar] = await Promise.all([\n        wrapPeerTitle(peerTitleOptions).then(async(peerTitle) => {\n          const title = document.createDocumentFragment();\n          if(fwdFromPeerId) {\n            const isBroadcast = await rootScope.managers.appPeersManager.isBroadcast(fwdFromPeerId);\n            const icon = Icon(\n              isBroadcast ? 'newchannel_filled' : (fwdFromPeerId.isUser() ? 'newprivate_filled' : 'group_filled'),\n              'inline-icon',\n              'reply-title-icon',\n              'with-margin'\n            );\n            title.append(icon);\n          }\n\n          title.append(peerTitle);\n\n          if(fwdFromName || mediaAreaChannelPost) {\n            const container = document.createElement('div');\n            container.classList.add(styles.ViewerStoryRepostSmall);\n            container.append(title);\n            return container;\n          }\n\n          const {container, fillPromise} = wrapReply({\n            title,\n            subtitle: subtitleElement as HTMLElement,\n            useHighlightingColor: true,\n            setColorPeerId: fwdFromPeerId\n          });\n\n          await fillPromise;\n          return container;\n        }),\n        wrapPeerTitle(peerTitleOptions),\n        readyThumbPromise.then(() => node),\n        storyPromise\n      ]);\n      if(!middleware()) return;\n\n      headerPeerTitle.classList.add(styles.ViewerStoryHeaderRepostTitle);\n\n      reply.classList.add(styles.ViewerStoryRepost);\n      ret.reply = reply;\n      setHeaderContent([\n        Icon(STORY_REPOST_ICON, styles.ViewerStoryHeaderRepostIcon),\n        headerAvatar,\n        headerPeerTitle\n      ]);\n\n      uRepost(ret);\n    });\n\n    createEffect(\n      on(\n        () => [inputReady(), uStackedAvatars?.(), uCaption(), uContent(), uReaction?.(), uMediaAreas(), uRepost()] as const,\n        ([inputReady, ...u]) => {\n          if(!inputReady || u.some((v) => v === null)) {\n            return;\n          }\n\n          const [stackedAvatars, caption, content, reaction, mediaAreas, repost] = u;\n          setStackedAvatars(stackedAvatars);\n          setCaption(caption);\n          setContent(content);\n          setReaction(reaction);\n          setMediaAreas(mediaAreas);\n          setRepost(repost);\n          props.onReady?.();\n\n          createEffect(() => {\n            setStoryMeta(story);\n          });\n        },\n        {defer: true}\n      )\n    );\n  };\n\n  createEffect(() => { // on story change\n    const story = currentStory();\n    setCaptionOpacity(0);\n    setCaptionActive(false);\n\n    createEffect(() => {\n      setStory(story);\n    });\n    // createEffect(on( // on story update\n    //   () => story._,\n    //   () => {\n    //     setStory(unwrap(story), hasViewer);\n    //   }\n    // ));\n  });\n\n  const pollViewedStories = () => {\n    if(!pollViewedStoriesSet.size) {\n      return;\n    }\n\n    const ids = Array.from(pollViewedStoriesSet);\n    pollViewedStoriesSet.clear();\n    rootScope.managers.appStoriesManager.getStoriesById(props.state.peerId, ids, true);\n  };\n  const pollViewedStoriesSet: Set<number> = new Set();\n  let pollViewedStoriesInterval: number;\n  createEffect(() => {\n    if(isActive()) {\n      pollViewedStoriesInterval = window.setInterval(pollViewedStories, 60e3);\n\n      createEffect(() => {\n        pollViewedStoriesSet.add(currentStory().id);\n      });\n    } else {\n      clearInterval(pollViewedStoriesInterval);\n    }\n  });\n\n  const readStories = (maxId: number) => {\n    if(viewedStories.size) {\n      rootScope.managers.appStoriesManager.incrementStoryViews(props.state.peerId, Array.from(viewedStories));\n      viewedStories.clear();\n    }\n\n    rootScope.managers.appStoriesManager.readStories(props.state.peerId, maxId);\n  };\n\n  const viewedStories: Set<number> = new Set();\n  const readDebounced = debounce(readStories, 5e3, true, true);\n  createEffect(() => { // read stories\n    if(!isActive()) {\n      return;\n    }\n\n    let lastId: number;\n    createEffect(() => {\n      const story = currentStory();\n      if(props.pinned && untrack(() => isExpired())) viewedStories.add(story.id);\n      readDebounced(lastId = story.id);\n    });\n\n    onCleanup(() => {\n      if(!readDebounced.isDebounced()) {\n        return;\n      }\n\n      readDebounced.clearTimeout();\n      readStories(lastId);\n    });\n  });\n\n  const playOnOpen = () => {\n    if(!stories.hasViewer || untrack(() => !isActive())) {\n      return;\n    }\n\n    playOnReady();\n  };\n\n  createEffect(playOnOpen); // play on open\n\n  const slides = <StorySlides {...mergeProps(props, {currentStory})} />;\n\n  let shouldAddTranslateX = true;\n  const calculateTranslateX = () => {\n    let diff = diffToActive();\n    if(!diff) {\n      return '0px';\n    }\n\n    if(\n      shouldShow() &&\n      stories.hasViewer &&\n      fadeIn() &&\n      shouldAddTranslateX\n    ) {\n      if(diff > 0) ++diff;\n      else --diff;\n    }\n\n    const storyWidth = stories.width;\n    const MARGIN = 40;\n    const multiplier = diff > 0 ? 1 : -1;\n    const smallStoryWidth = storyWidth * STORY_SCALE_SMALL;\n    let offset = storyWidth * multiplier;\n    const distance = (storyWidth - smallStoryWidth) / 2 - MARGIN;\n    offset = (storyWidth - distance) * multiplier;\n    if(Math.abs(diff) !== 1) {\n      const d = diff - 1 * multiplier;\n      offset += d * smallStoryWidth + MARGIN * d;\n    }\n    return offset + 'px';\n  };\n\n  const playOnReady = () => {\n    if(untrack(() => loading())) {\n      return;\n    }\n\n    const activeVideoDuration = untrack(() => videoDuration());\n    // * add 0.001 just to differ video and photo stories\n    const storyDuration = activeVideoDuration ? activeVideoDuration + 0.001 : STORY_DURATION;\n    actions.play(storyDuration);\n  };\n\n  // let transitionPromise: CancellablePromise<void>;\n  const onTransitionStart = (e?: TransitionEvent) => {\n    if(e && e.target !== div) {\n      return;\n    }\n\n    setSliding(true);\n    // transitionPromise = deferredPromise();\n  };\n\n  const onTransitionEnd = (e?: TransitionEvent) => {\n    if(e && e.target !== div) {\n      return;\n    }\n\n    shouldAddTranslateX = true;\n    setSliding(false);\n    // transitionPromise?.resolve();\n    if(!isActive()) {\n      return;\n    }\n\n    playOnReady();\n  };\n\n  const toggleMute = (e: MouseEvent) => {\n    if(noSound()) {\n      const {close} = showTooltip({\n        ...muteTooltipOptions,\n        textElement: i18n('Story.NoSound')\n      });\n      setTooltipCloseCallback(() => close);\n      return;\n    }\n\n    actions.toggleMute();\n  };\n\n  let muteButtonButton: HTMLButtonElement;\n  const muteButton = (\n    <ButtonIconTsx\n      ref={muteButtonButton}\n      classList={{[styles.noSound]: noSound()}}\n      icon={stories.muted || noSound() ? 'speakeroff_filled' : 'speaker_filled'}\n      onClick={toggleMute}\n    />\n  );\n\n  const copyLink = () => {\n    copyTextToClipboard(`https://t.me/${getPeerActiveUsernames(peer)[0]}/s/${currentStory().id}`);\n    toastNew({\n      langPackKey: 'LinkCopied'\n    });\n  };\n\n  const topMenuOptions: Partial<Parameters<typeof createContextMenu>[0]> = {\n    onOpenBefore: async() => {\n      peer = await rootScope.managers.appStoriesManager.getPeer(props.state.peerId);\n      story = currentStory() as StoryItem.storyItem;\n      peerId = props.state.peerId;\n    },\n    onOpen: () => {\n      wasPlaying = !stories.paused;\n      actions.pause();\n    },\n    onCloseAfter: () => {\n      if(wasPlaying && !ignoreOnClose) {\n        actions.play();\n      }\n\n      ignoreOnClose = false;\n    }\n  };\n\n  // * caption start\n\n  const CAPTION_ACTIVE_THRESHOLD = 0.2;\n  createEffect(() => {\n    if(!isActive()) {\n      return;\n    }\n\n    actions.setLoop(videoDuration() !== undefined && captionActive());\n  });\n\n  let wasPlayingBeforeCaption: boolean;\n  const onCaptionScrollTop = (scrollTop: number) => {\n    const progress = Math.min(1, scrollTop / 100);\n    const active = progress >= CAPTION_ACTIVE_THRESHOLD;\n    setCaptionOpacity(progress);\n    setCaptionActive(active);\n    // console.log('caption progress', progress);\n\n    if(videoDuration() !== undefined) {\n      return;\n    }\n\n    if(active) {\n      if(wasPlayingBeforeCaption === undefined) {\n        wasPlayingBeforeCaption = !stories.paused;\n        actions.pause();\n      }\n    } else if(wasPlayingBeforeCaption) {\n      wasPlayingBeforeCaption = undefined;\n      actions.play();\n    }\n  };\n\n  let captionScrollable: HTMLDivElement, captionText: HTMLDivElement, scrolling = false;\n  const onCaptionScroll = () => {\n    if(scrolling) {\n      return;\n    }\n\n    const scrollTop = captionScrollable.scrollTop;\n    onCaptionScrollTop(scrollTop);\n  };\n\n  const scrollPath = (path: number) => {\n    const target = Math.max(0, path);\n    const startTime = Date.now();\n    scrolling = true;\n\n    const story = currentStory();\n    animateSingle(() => {\n      if(currentStory() !== story) {\n        return false;\n      }\n\n      const t = Math.min(1, (Date.now() - startTime) / 300);\n      const value = easeOutCubicApply(t, 1);\n      const currentPath = path * (1 - value);\n      const scrollTop = Math.round(target - currentPath);\n      captionScrollable.scrollTop = scrollTop;\n      onCaptionScrollTop(scrollTop);\n\n      return t < 1;\n    }, captionScrollable).finally(() => {\n      scrolling = false;\n    });\n  };\n\n  const onCaptionClick = (e: MouseEvent) => {\n    if((captionScrollable.scrollHeight <= captionScrollable.clientHeight) || captionScrollable.scrollTop) {\n      return;\n    }\n\n    cancelEvent(e);\n    // const visibleTextHeight = captionScrollable.clientHeight - captionScrollable.clientWidth * 0.7 - 8;\n    const visibleTextHeight = 56;\n    const path = Math.min(captionText.scrollHeight - visibleTextHeight, captionScrollable.clientHeight - 60);\n    scrollPath(path);\n  };\n\n  const captionContainer = (\n    <div\n      ref={captionScrollable}\n      class={classNames(\n        'scrollable',\n        'scrollable-y',\n        'no-scrollbar',\n        styles.ViewerStoryCaption,\n        repost() && caption() && styles.hasReply\n      )}\n      onScroll={onCaptionScroll}\n    >\n      <div\n        ref={captionText}\n        class={classNames('spoilers-container', styles.ViewerStoryCaptionText)}\n        onClick={onCaptionClick}\n      >\n        <div class={styles.ViewerStoryCaptionTextCell} dir=\"auto\">\n          {repost()?.reply}\n          {caption()}\n        </div>\n      </div>\n    </div>\n  );\n\n  // * caption end\n\n  const contentItem = (\n    <div\n      class={styles.ViewerStoryContentItem}\n      style={captionOpacity() && {opacity: 1 - captionOpacity() * 0.5}}\n    >\n      {content()}\n    </div>\n  );\n\n  const getDateText = () => {\n    const {timestamp, edited} = date() || {};\n    if(!timestamp) {\n      return;\n    }\n\n    const elapsedTime = tsNow(true) - timestamp;\n    const formatted = formatDuration(elapsedTime);\n    const map: {[type in DurationType]?: LangPackKey} = {\n      [DurationType.Seconds]: 'StoryJustNow',\n      [DurationType.Minutes]: 'MinutesShortAgo',\n      [DurationType.Hours]: 'HoursShortAgo'\n      // [DurationType.Days]: 'DaysShortAgo'\n    };\n\n    // if(formatted[0].type === DurationType.Seconds) {\n    //   formatted[0] = {\n    //     type: DurationType.Minutes,\n    //     duration: 0\n    //   };\n    // }\n\n    const first = formatted[0];\n    const key = map[first.type];\n    const elements: (Node | string | (Node | string)[])[] = [];\n    if(!key) {\n      // return formatFullSentTime(timestamp);\n      // elements.push(getFullDate(new Date(timestamp * 1000), {shortYear: true}));\n      elements.push(<span>{documentFragmentToNodes(formatFullSentTime(timestamp))}</span> as any);\n    } else if(first.type === DurationType.Days && first.duration !== 1) {\n      elements.push(formatDateAccordingToTodayNew(new Date(timestamp * 1000)));\n    } else {\n      elements.push(i18n(key, [first.duration]));\n    }\n\n    if(edited) {\n      elements.push(i18n('EditedMessage'));\n    }\n\n    if(repost()) {\n      elements.unshift(repost().header as HTMLElement);\n    }\n\n    let joined: JSX.Element[] = joinElementsWith(elements, JOINER);\n    if(repost()) {\n      joined = [\n        joined[0],\n        <span class={styles.ViewerStoryHeaderSecondary}>{joined.slice(1)}</span>\n      ];\n    }\n\n    return joined;\n  };\n\n  const showMessageSentTooltip = (textElement: HTMLElement, peerId?: PeerId) => {\n    let a: HTMLAnchorElement;\n    if(peerId) {\n      a = document.createElement('a');\n      a.href = '#';\n      a.addEventListener('click', (e) => {\n        cancelEvent(e);\n        props.close(() => {\n          appImManager.setInnerPeer({peerId});\n        });\n      }, {capture: true, passive: false});\n      a.append(i18n('ViewInChat'));\n    }\n\n    setQuizHint({\n      textElement,\n      textRight: a,\n      appendTo: storyDiv,\n      from: 'bottom',\n      duration: 3000,\n      icon: 'checkround_filled'\n    });\n  };\n\n  const needStoryInput = props.state.peerId !== CHANGELOG_PEER_ID &&\n    props.state.peerId !== rootScope.myId &&\n    props.state.peerId.isUser();\n  const [inputReady, setInputReady] = createSignal(!needStoryInput);\n  const storyInput = needStoryInput &&\n    <StoryInput\n      {\n        ...mergeProps(props, {\n          currentStory,\n          isActive,\n          focusedSignal,\n          inputEmptySignal,\n          inputMenuOpenSignal,\n          sendReaction,\n          isPublic,\n          shareStory: onShareClick,\n          reaction,\n          onShareButtonClick,\n          onMessageSent: () => {\n            showMessageSentTooltip(i18n('Story.Tooltip.MessageSent'), props.state.peerId);\n          },\n          setInputReady\n        })\n      }\n    />;\n\n  // * top menu start\n\n  const isPeerArchived = async(visible: boolean) => {\n    const peerId = props.state.peerId;\n    if(peerId === rootScope.myId || peerId === CHANGELOG_PEER_ID) {\n      return false;\n    }\n\n    const [peer, isSubscribed] = await Promise.all([\n      rootScope.managers.appStoriesManager.getPeer(peerId),\n      rootScope.managers.appStoriesManager.isSubcribedToPeer(peerId)\n    ]);\n    const isHidden = !!peer.pFlags.stories_hidden;\n    return (visible ? !isHidden : isHidden) && isSubscribed;\n  };\n\n  const togglePeerHidden = async(hidden: boolean) => {\n    const peerId = props.state.peerId;\n    rootScope.managers.appStoriesManager.toggleStoriesHidden(peerId, hidden);\n    toastNew({\n      langPackKey: hidden ? 'StoriesMovedToContacts' : 'StoriesMovedToDialogs',\n      langPackArguments: [await wrapPeerTitle({peerId})]\n    });\n  };\n\n  const togglePinned = async(pinned: boolean) => {\n    const peerId = props.state.peerId;\n    rootScope.managers.appStoriesManager.togglePinned(peerId, currentStory().id, pinned).then(() => {\n      toastNew({\n        langPackKey: pinned ?\n          (peerId.isUser() ? 'StoryPinnedToProfile' : 'StoryPinnedToPosts') :\n          (peerId.isUser() ? 'StoryArchivedFromProfile' : 'StoryUnpinnedFromPosts')\n      });\n    });\n  };\n\n  let wasPlaying = false,\n    peer: User.user | MTChat.channel,\n    peerId: PeerId,\n    story: StoryItem.storyItem | StoryItem.storyItemSkipped,\n    ignoreOnClose = false;\n  const btnMenu = ButtonMenuToggle({\n    buttons: [{\n      icon: 'plusround',\n      text: 'Story.AddToProfile',\n      onClick: () => togglePinned(true),\n      verify: () => peerId === rootScope.myId && !(story as StoryItem.storyItem).pFlags?.pinned\n    }, {\n      icon: 'crossround',\n      text: 'Story.RemoveFromProfile',\n      onClick: () => togglePinned(false),\n      verify: () => peerId === rootScope.myId && !!(story as StoryItem.storyItem).pFlags?.pinned\n    }, {\n      icon: 'plusround',\n      text: 'SaveToPosts',\n      onClick: () => togglePinned(true),\n      verify: () => !peerId.isUser() && !(story as StoryItem.storyItem).pFlags?.pinned && rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'pin')\n    }, {\n      icon: 'crossround',\n      text: 'RemoveFromPosts',\n      onClick: () => togglePinned(false),\n      verify: () => !peerId.isUser() && !!(story as StoryItem.storyItem).pFlags?.pinned && rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'pin')\n    }, {\n      icon: 'forward',\n      text: 'ShareFile',\n      onClick: () => {\n        ignoreOnClose = true;\n        onShareClick(wasPlaying);\n      },\n      verify: () => {\n        return !!(story as StoryItem.storyItem)?.pFlags?.public && !(story as StoryItem.storyItem).pFlags.noforwards;\n      }\n    }, {\n      icon: 'link',\n      text: 'CopyLink',\n      onClick: copyLink,\n      verify: () => {\n        if(story._ !== 'storyItem') {\n          return false;\n        }\n\n        // const appConfig = await rootScope.managers.apiManager.getAppConfig();\n        return (story.pFlags.public/*  || appConfig.stories_export_nopublic_link */) && !!getPeerActiveUsernames(peer)[0];\n      }\n    }, {\n      icon: 'download',\n      text: 'MediaViewer.Context.Download',\n      onClick: () => {\n        const story = currentStory();\n        const media = getMediaFromMessage(story as StoryItem.storyItem, true);\n        if(!media) {\n          return;\n        }\n        appDownloadManager.downloadToDisc({media: unwrap(media)});\n      },\n      verify: () => {\n        if(props.state.peerId === rootScope.myId) {\n          return true;\n        }\n\n        const story = currentStory();\n        return !!(story?._ === 'storyItem' && !story.pFlags.noforwards && rootScope.premium);\n      }\n    }, {\n      icon: 'eyecross',\n      text: 'Stories.StealthMode.View',\n      onClick: () => {\n        ignoreOnClose = true;\n        const appConfig = useAppConfig();\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        showStoriesStealthModePopup({\n          onActivate: () => {\n            setQuizHint({\n              title: i18n('Stories.StealthMode.Activated.Title'),\n              textElement: i18n('Stories.StealthMode.Activated.Subtitle', [\n                wrapStoriesStealthModeDuration(appConfig.stories_stealth_future_period),\n                wrapStoriesStealthModeDuration(appConfig.stories_stealth_past_period)\n              ]),\n              appendTo: storyDiv,\n              from: 'bottom',\n              duration: 8000,\n              icon: 'checkround_filled'\n            });\n          },\n          onClose: onAnyPopupClose\n        });\n      }\n    }, {\n      icon: 'archive',\n      text: 'ArchivePeerStories',\n      onClick: () => togglePeerHidden(true),\n      verify: () => isPeerArchived(true)\n    }, {\n      icon: 'unarchive',\n      text: 'UnarchiveStories',\n      onClick: () => togglePeerHidden(false),\n      verify: () => isPeerArchived(false)\n    }, {\n      icon: 'statistics_filled',\n      text: 'ViewStatistics',\n      onClick: () => {\n        const storyId = currentStory().id;\n        props.close(() => {\n          setTimeout(() => {\n            appSidebarRight.createTab(AppStatisticsTab).open(peerId.toChatId(), undefined, storyId);\n            appSidebarRight.toggleSidebar(true);\n          }, 0);\n        });\n      },\n      verify: () => rootScope.managers.appProfileManager.canViewStatistics(peerId)\n    }, {\n      icon: 'delete danger' as Icon,\n      text: 'Delete',\n      onClick: async() => {\n        const id = currentStory().id;\n        const peerId = props.state.peerId;\n        ignoreOnClose = true;\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        try {\n          await confirmationPopup({\n            titleLangKey: 'DeleteStoryTitle',\n            descriptionLangKey: 'DeleteStorySubtitle',\n            button: {\n              langKey: 'Delete',\n              isDanger: true\n            }\n          });\n        } catch(err) {\n          onAnyPopupClose();\n          return;\n        }\n\n        rootScope.managers.appStoriesManager.deleteStories(peerId, [id]);\n      },\n      verify: () => rootScope.managers.appStoriesManager.hasRights(peerId, story.id, 'delete')\n    }, {\n      icon: 'flag',\n      className: 'danger',\n      text: 'ReportChat',\n      onClick: () => {\n        ignoreOnClose = true;\n        const onAnyPopupClose = bindOnAnyPopupClose(wasPlaying);\n        showStoryReport(props.state.peerId, [currentStory().id], onAnyPopupClose);\n      },\n      verify: () => !(story as StoryItem.storyItem).pFlags?.out && props.state.peerId !== CHANGELOG_PEER_ID\n      // separator: true\n    }],\n    direction: 'bottom-left',\n    ...topMenuOptions\n  });\n  btnMenu.classList.add('night');\n\n  // * top menu end\n\n  // * privacy icon start\n\n  const privacyIconMap: {[key in StoryPrivacyType]: Icon} = {\n    close: 'star_filled',\n    contacts: 'newprivate_filled',\n    public: 'newchannel_filled',\n    selected: 'newgroup_filled'\n  };\n\n  const onPrivacyIconClick = async() => {\n    const type = privacyType();\n    const peerTitle = await wrapPeerTitle({peerId: props.state.peerId, onlyFirstName: true});\n    const {close} = showTooltip({\n      container: headerDiv,\n      element: privacyIconElement,\n      vertical: 'bottom',\n      textElement: i18n(\n        type === 'close' ? 'StoryCloseFriendsHint' : (type === 'selected' ? 'StorySelectedContactsHint' : 'StoryContactsHint'),\n        [peerTitle]\n      ),\n      paddingX: 13\n    });\n\n    setTooltipCloseCallback(() => close);\n  };\n\n  createEffect(() => {\n    const close = tooltipCloseCallback();\n    if(!close) {\n      return;\n    }\n\n    onCleanup(close);\n\n    createEffect(\n      on(\n        () => [isActive(), currentStory()],\n        () => {\n          close();\n          setTooltipCloseCallback();\n        },\n        {defer: true}\n      )\n    );\n  });\n\n  let privacyIconElement: HTMLDivElement;\n  const privacyIcon = (\n    <div\n      ref={privacyIconElement}\n      class={classNames(\n        styles.ViewerStoryPrivacy,\n        'privacy-bg',\n        `privacy-bg-${privacyType()}`\n      )}\n      onClick={() => onPrivacyIconClick()}\n    >\n      {Icon(privacyIconMap[privacyType()])}\n    </div>\n  );\n\n  // * privacy icon end\n\n  // * my footer start\n\n  const getViews = isMe && (() => {\n    const story = currentStory();\n    if(story._ !== 'storyItem') {\n      return;\n    }\n\n    const viewsCount = story.views?.views_count ?? 0;\n    if(!viewsCount) {\n      const isExpired = story.expire_date <= tsNow(true);\n      if(isExpired) {\n        return i18n('NobodyViewsArchived');\n      } else {\n        return i18n('NobodyViews');\n      }\n    } else {\n      return i18n('Views', [viewsCount]);\n    }\n  });\n\n  const openViewsList = isMe && (() => {\n    let nextOffset: string;\n    const viewsMap: Map<PeerId, StoryView.storyView> = new Map();\n    const popup = showPickUserPopup({\n      titleLangKey: 'StoryViewers',\n      peerType: ['custom'],\n      getMoreCustom: (q) => {\n        const loadCount = 50;\n        return rootScope.managers.appStoriesManager.getStoryViewsList(\n          props.state.peerId,\n          currentStory().id,\n          loadCount,\n          nextOffset,\n          q\n        ).then(({nextOffset: _nextOffset, views}) => {\n          nextOffset = _nextOffset;\n          return {\n            result: views.map((storyView) => {\n              const peerId = storyView.user_id.toPeerId(false);\n              viewsMap.set(peerId, storyView);\n              return peerId;\n            }),\n            isEnd: !nextOffset\n          };\n        });\n      },\n      processElementAfter: (peerId, dialogElement) => {\n        const view = viewsMap.get(peerId);\n        return processDialogElementForReaction({\n          dialogElement,\n          peerId,\n          date: view.date,\n          isMine: true,\n          middleware: popup.selector.middlewareHelperLoader.get(),\n          reaction: view.reaction\n        });\n      },\n      onSelect: ([obj]) => {\n        props.close(() => {\n          appImManager.setInnerPeer(obj);\n        });\n      },\n      placeholder: 'SearchPlaceholder',\n      exceptSelf: true,\n      meAsSaved: false\n    });\n  });\n\n  const onDeleteClick = isMe && (async() => {\n    const peerId = props.state.peerId;\n    const storyId = currentStory().id;\n    await confirmationPopup({\n      titleLangKey: 'DeleteStoryTitle',\n      descriptionLangKey: 'DeleteStorySubtitle',\n      button: {\n        isDanger: true,\n        langKey: 'Delete'\n      }\n    });\n\n    rootScope.managers.appStoriesManager.deleteStories(peerId, [storyId]);\n  });\n\n  if(isMe) {\n    const viewedStories: Set<number> = new Set();\n    const getAround = 2;\n    let promise: Promise<any>;\n    const getStoriesViews = async() => {\n      if(promise) {\n        return;\n      }\n\n      const story = currentStory();\n      const index = props.state.stories.indexOf(story);\n      const slice = props.state.stories.slice(Math.max(0, index - getAround), index + getAround);\n      slice.forEach((story) => {\n        viewedStories.add(story.id);\n      });\n\n      const ids = Array.from(viewedStories);\n      viewedStories.clear();\n      promise = rootScope.managers.appStoriesManager.getStoriesViews(props.state.peerId, ids).then(() => {\n        promise = undefined;\n      });\n\n      // let's clear after last execution, not before viewer is closed\n      if(cleaned) {\n        clearInterval(interval);\n      }\n    };\n    const interval = setInterval(getStoriesViews, 10e3);\n\n    createEffect(() => {\n      const story = currentStory();\n      viewedStories.add(story.id);\n    });\n\n    let cleaned = false;\n    onCleanup(() => {\n      cleaned = true;\n    });\n\n    onMount(() => {\n      getStoriesViews();\n    });\n  }\n\n  let footerReactionElement: HTMLSpanElement;\n  const footer = (isMe || CHANGELOG_PEER_ID === props.state.peerId || !props.state.peerId.isUser()) && (\n    <div\n      class={classNames(\n        styles.ViewerStoryFooter,\n        styles.hideOnSmall,\n        rootScope.myId === props.state.peerId && styles.isMe,\n        CHANGELOG_PEER_ID === props.state.peerId && styles.isChangelog\n      )}\n    >\n      {isMe ? (\n        <>\n          <div class={styles.ViewerStoryFooterLeft} onClick={openViewsList}>\n            {stackedAvatars() && stackedAvatars().container}\n            {getViews()}\n          </div>\n          <div class={styles.ViewerStoryFooterRight}>\n            <ButtonIconTsx icon=\"delete\" onClick={onDeleteClick} />\n          </div>\n        </>\n      ) : (!props.state.peerId.isUser() ? (\n        <>\n          <div class={styles.ViewerStoryFooterLeft}>\n            <span class={styles.ViewerStoryFooterIcon}>\n              {Icon('eye1_filled', styles.ViewerStoryFooterIconIcon)}\n              {formatNumber((currentStory() as StoryItem.storyItem).views?.views_count || 1, 1)}\n            </span>\n          </div>\n          <div class={styles.ViewerStoryFooterRight}>\n            {canShareStory() && (\n              <ButtonIconTsx\n                icon=\"forward\"\n                onClick={(e) => {\n                  onShareButtonClick(e, e.target as HTMLElement);\n                }}\n              />\n            )}\n            <span\n              ref={footerReactionElement}\n              class={classNames(\n                styles.ViewerStoryFooterIcon,\n                styles.ViewerStoryFooterReaction,\n                (currentStory() as StoryItem.storyItem).sent_reaction && styles.isReacted\n              )}\n              onClick={(e) => sendReaction({reaction: {_: 'reactionEmoji', emoticon: DEFAULT_REACTION_EMOTICON}, target: footerReactionElement.firstElementChild as HTMLElement})}\n            >\n              <IconTsx icon={(currentStory() as StoryItem.storyItem).sent_reaction ? 'reactions_filled' : 'reactions'} class={styles.ViewerStoryFooterIconIcon}></IconTsx>\n              {(currentStory() as StoryItem.storyItem).views?.reactions_count || 0}\n            </span>\n          </div>\n        </>\n      ) : i18n('StoryCantReply'))}\n    </div>\n  );\n\n  // * my footer end\n\n  createEffect(\n    on(\n      () => [isActive(), currentStory()],\n      () => {\n        if(liteMode.isAvailable('animations')) {\n          return;\n        }\n\n        untrack(() => {\n          onTransitionStart();\n          onTransitionEnd();\n        });\n      }\n    )\n  );\n\n  // createEffect(() => {\n  //   if(stories.peer && !liteMode.isAvailable('animations')) {\n  //     untrack(() => {\n  //       onTransitionStart();\n  //       onTransitionEnd();\n  //     });\n  //   }\n  // });\n\n  const onProfileClick = (e: MouseEvent) => {\n    // * I'm handling it elsewhere\n    if(findUpClassName(e.target, styles.ViewerStoryHeaderRepost)) {\n      return;\n    }\n\n    const peerId = props.state.peerId;\n    props.close(() => {\n      appImManager.setInnerPeer({peerId});\n    });\n  };\n\n  const diffToActive = createMemo(() => {\n    return props.index() - props.peers.indexOf(stories.peer);\n  });\n\n  const fromLeft = createMemo<boolean>((prev) => {\n    return sliding() ? prev : diffToActive() < 0;\n  });\n\n  const fromRight = createMemo<boolean>((prev) => {\n    return sliding() ? prev : diffToActive() > 0;\n  });\n\n  const [fadeIn, setFadeIn] = createSignal(false);\n\n  const shouldShow = createMemo((/* prev */) => {\n    const diff = Math.abs(diffToActive());\n    let shouldBeVisible: boolean;\n    if(/* props.isFull() &&  */!stories.hasViewer) {\n      shouldBeVisible = diff === 0;\n\n      if(!props.isFull() && diff <= STORIES_PRESERVE) {\n        shouldAddTranslateX = false;\n      }\n    } else {\n      shouldBeVisible = diff <= STORIES_PRESERVE;\n    }\n\n    // if(!shouldBeVisible && prev) {\n    //   return sliding();\n    // }\n\n    return shouldBeVisible;\n  });\n\n  createEffect<boolean>((prev) => {\n    if(!shouldShow()) {\n      // if(prev) {\n      setFadeIn(true);\n      // }\n\n      return true;\n    } else if(prev) {\n      setFadeIn(true);\n\n      doubleRaf().then(() => {\n        setFadeIn(false);\n      });\n\n      return true;\n    }\n  });\n\n  let div: HTMLDivElement, storyDiv: HTMLDivElement, headerDiv: HTMLDivElement;\n  const ret = (\n    <div\n      ref={div}\n      class={styles.ViewerStoryContainer}\n      classList={{\n        ...(props.isFull() ? {\n          [styles.fromLeft]: fromLeft(),\n          [styles.current]: isActive(),\n          [styles.fromRight]: fromRight()\n        } : {\n          [styles.small]: !isActive()\n        }),\n        [styles.hold]: stories.hideInterface && isActive(),\n        [styles.focused]: focused(),\n        [styles.fadeIn]: fadeIn()\n      }}\n      style={!props.isFull() && {\n        '--translateX': calculateTranslateX()\n      }}\n      onClick={(e) => {\n        if(!isActive()) {\n          actions.set({peer: props.state, index: props.state.index});\n        } else if(\n          findUpClassName(e.target, styles.ViewerStoryRepost) ||\n          findUpClassName(e.target, styles.ViewerStoryHeaderRepost)\n        ) {\n          const story = currentStory();\n          const repostInfo = getStoryRepostInfo(story as StoryItem.storyItem);\n          if(!repostInfo) {\n            toastNew({\n              langPackKey: 'HidAccount'\n            });\n            return;\n          }\n\n          const {fwdFrom, mediaAreaChannelPost} = repostInfo;\n          if(fwdFrom?.from || mediaAreaChannelPost) {\n            e.stopPropagation();\n            props.close(() => {\n              const peerId = fwdFrom ? getPeerId(fwdFrom.from) : mediaAreaChannelPost.channel_id.toPeerId(true);\n              if(fwdFrom?.story_id && !findUpClassName(e.target, styles.ViewerStoryHeaderRepost)) {\n                createStoriesViewerWithPeer({\n                  peerId,\n                  id: fwdFrom.story_id\n                });\n              } else {\n                appImManager.setInnerPeer({\n                  peerId,\n                  lastMsgId: mediaAreaChannelPost?.msg_id\n                });\n              }\n            });\n          }\n        } else if(\n          captionScrollable.scrollTop &&\n          !findUpAsChild(e.target, captionText) &&\n          !findUpClassName(e.target, styles.ViewerStoryHeader)\n        ) {\n          scrollPath(-captionScrollable.scrollTop);\n        } else if(\n          !stories.paused &&\n          !stories.hideInterface &&\n          !findUpAsChild(e.target, captionText) &&\n          !findUpClassName(e.target, styles.ViewerStoryHeader) &&\n          !findUpClassName(e.target, 'stories-input') &&\n          !findUpClassName(e.target, styles.ViewerStoryReactions) &&\n          findUpClassName(e.target, styles.ViewerStory)\n        ) {\n          const rect = div.getBoundingClientRect();\n          const next = e.clientX > (rect.left + rect.width / 3);\n          actions.goToNearestStorySafe(next);\n        }\n      }}\n      onTransitionStart={onTransitionStart}\n      onTransitionEnd={onTransitionEnd}\n    >\n      <div ref={storyDiv} class={classNames(styles.ViewerStory, loading() && isActive() && 'shimmer')}>\n        <div class={styles.ViewerStoryContent}>\n          {contentItem}\n        </div>\n        <div class={styles.hideOnSmall}>\n          <div class={classNames(styles.ViewerStoryShadow, caption() && styles.hasCaption)}></div>\n          <div class={styles.ViewerStorySlides}>\n            {slides}\n          </div>\n          <div ref={headerDiv} class={classNames(styles.ViewerStoryHeader, 'night')}>\n            <div class={styles.ViewerStoryHeaderLeft} onClick={onProfileClick}>\n              {avatar.element}\n              <div class={styles.ViewerStoryHeaderInfo}>\n                <div class={styles.ViewerStoryHeaderRow}>\n                  {peerTitleElement}\n                  {props.splitByDays && (\n                    <span class={styles.ViewerStoryHeaderSecondary}>\n                      {`${JOINER}${props.state.index + 1}/${props.state.stories.length}`}\n                    </span>\n                  )}\n                </div>\n                <div\n                  class={classNames(\n                    // styles.ViewerStoryHeaderRow,\n                    repost() ? styles.hasRepost : styles.ViewerStoryHeaderSecondary,\n                    styles.ViewerStoryHeaderTime\n                  )}\n                >\n                  {getDateText()}\n                </div>\n              </div>\n            </div>\n            <div class={styles.ViewerStoryHeaderRight}>\n              {privacyType() && privacyIcon}\n              <ButtonIconTsx\n                icon={stories.paused && !stories.playAfterGesture ? 'play_filled' : 'pause_filled'}\n                onClick={() => actions.toggle()}\n              />\n              {videoDuration() && muteButton}\n              {/* <ButtonIconTsx icon={'more'} /> */}\n              {btnMenu}\n              {props.isFull() && (\n                <ButtonIconTsx\n                  icon={'close'}\n                  onClick={() => props.close()}\n                />\n              )}\n            </div>\n          </div>\n          {(caption() || repost()) && captionContainer}\n          {mediaAreas() && (\n            <div\n              class={styles.ViewerStoryMediaAreas}\n              style={captionOpacity() && {'opacity': 1 - captionOpacity() * 0.5, 'z-index': 0}}\n            >\n              {mediaAreas()}\n            </div>\n          )}\n          {reactionsMenu()?.widthContainer}\n        </div>\n        {!props.isFull() && (\n          <div class={styles.ViewerStoryInfo}>\n            {avatarInfo.node}\n            {peerTitleInfoElement}\n          </div>\n        )}\n      </div>\n      {storyInput || footer}\n      {/* <MessageInputField /> */}\n    </div>\n  );\n\n  const muteTooltipOptions: Parameters<typeof showTooltip>[0] = {\n    container: headerDiv,\n    element: muteButtonButton,\n    vertical: 'bottom',\n    paddingX: 13\n  };\n\n  return (\n    <Show when={shouldShow()}>\n      {ret}\n    </Show>\n  );\n}\n\nexport default function StoriesViewer(props: {\n  onExit?: () => void,\n  target?: Accessor<Element>,\n  splitByDays?: boolean,\n  pinned?: boolean\n}) {\n  const [stories, actions] = useStories();\n  const [show, setShow] = createSignal(false);\n  const isFull = createMemo(() => {\n    return windowSize.height > windowSize.width ||\n      windowSize.width < (stories.width + 135 + 8 * 2) ||\n      stories.width === windowSize.width;\n  });\n  const wasShown = createMemo((shown) => shown || show());\n\n  // * fix `ended` property\n  actions.viewerReady(false);\n\n  const CANCELABLE_KEYS: Set<string> = new Set([\n    'ArrowRight',\n    'ArrowLeft',\n    'ArrowDown',\n    'Space'\n  ]);\n\n  const onKeyDown = (e: KeyboardEvent) => {\n    if(isTargetAnInput(getAppWindow().document.activeElement as HTMLElement)) {\n      throttledKeyDown.clear();\n      return;\n    }\n\n    const activeStoryContainer = getActiveStoryContainer();\n    if(animating || !!activeStoryContainer.querySelector('.is-recording')) {\n      throttledKeyDown.clear();\n      cancelEvent(e);\n      return;\n    }\n\n    if(CANCELABLE_KEYS.has(e.key) || CANCELABLE_KEYS.has(e.code)) {\n      cancelEvent(e);\n    } else {\n      const input = activeStoryContainer.querySelector<HTMLElement>('.input-message-input');\n      if(\n        input &&\n        !IS_TOUCH_SUPPORTED &&\n        input.isContentEditable &&\n        overlayCounter.overlaysActive === overlaysActive\n      ) {\n        focusInput(input, e);\n      }\n    }\n\n    if(e.key === 'ArrowDown') {\n      throttledKeyDown.clear();\n      close();\n      return;\n    }\n\n    throttledKeyDown(e);\n  };\n\n  const throttledKeyDown = throttle((e: KeyboardEvent) => {\n    if(e.key === 'ArrowRight') {\n      actions.goToNearestStorySafe(true);\n    } else if(e.key === 'ArrowLeft') {\n      actions.goToNearestStorySafe(false);\n    } else if(e.code === 'Space') {\n      actions.toggle();\n    }\n  }, 200, true);\n\n  // Follow the active window so the stories keyboard handler keeps firing when the overlay\n  // moves into a Document PiP window.\n  let disposeKeyDownListener: () => void;\n\n  emoticonsDropdown.getElement().classList.add('night');\n  emoticonsDropdown.setTextColor('white');\n\n  onCleanup(() => {\n    disposeKeyDownListener?.();\n    toggleOverlay(false);\n    swipeHandler.removeListeners();\n    appNavigationController.removeItem(navigationItem);\n\n    emoticonsDropdown.getElement().classList.remove('night');\n    emoticonsDropdown.setTextColor();\n    emoticonsDropdown.chatInput = undefined;\n  });\n\n  const close = (callback?: () => void) => {\n    callback && runWithOwner(owner, () => {\n      onCleanup(() => {\n        callback();\n      });\n    });\n\n    actions.viewerReady(false);\n    if(dispose) {\n      deferred = deferredPromise();\n      dispatchHeavyAnimationEvent(deferred, 1000);\n      dispose();\n      dispose = undefined;\n    }\n    actions.pause();\n    throttledKeyDown.clear();\n    setShow(false);\n    div.removeEventListener('click', onDivClick, {capture: true});\n  };\n\n  let div: HTMLDivElement, backgroundDiv: HTMLDivElement, closeButton: HTMLButtonElement;\n  let dispose: () => void; // * dispose listeners on close to avoid effects during animation\n  const ret = createRoot((_dispose) => {\n    dispose = _dispose;\n\n    createEffect(() => {\n      if(stories.ended) {\n        close();\n      }\n    });\n\n    const storiesReadiness: Set<PeerId> = new Set();\n    const storiesShouldBeReady: Set<PeerId> = new Set();\n    const perf = performance.now();\n    let wasReady = false;\n\n    const openOnReady = () => {\n      clearTimeout(timeout)\n      wasReady = true;\n      runWithOwner(owner, () => {\n        onMount(() => {\n          open();\n        });\n      });\n    };\n\n    const timeout = setTimeout(() => {\n      console.error('stories timeout');\n      stories.peers\n      .filter((peer) => storiesShouldBeReady.has(peer.peerId) && !storiesReadiness.has(peer.peerId))\n      .forEach((peer) => {\n        console.error('stories not ready', peer);\n      });\n      openOnReady();\n    }, 250);\n\n    const createStories = (peer: StoriesContextPeerState, index: Accessor<number>) => {\n      const onReady = () => {\n        storiesReadiness.add(peer.peerId);\n\n        if(wasReady) {\n          return;\n        }\n\n        // console.log('stories ready', peer.peerId, storiesReadiness.size, performance.now() - perf);\n\n        if(storiesReadiness.size === storiesShouldBeReady.size) {\n          openOnReady();\n        }\n      };\n\n      storiesShouldBeReady.add(peer.peerId);\n\n      const transitionSignal = createSignal(false);\n      const ret = (\n        <Stories\n          state={peer}\n          index={index}\n          splitByDays={props.splitByDays}\n          pinned={props.pinned}\n          onReady={onReady}\n          close={close}\n          peers={itemsToRender()}\n          isFull={isFull}\n          transitionSignal={transitionSignal}\n        />\n      );\n\n      const ref = resolveFirst(() => ret);\n      createEffect(() => {\n        const element = ref();\n        if(!element) {\n          return;\n        }\n\n        transitions.set(element, transitionSignal[0]);\n\n        onCleanup(() => {\n          transitions.delete(element);\n        });\n      });\n\n      return ret;\n    };\n\n    const preserve = STORIES_PRESERVE + STORIES_PRESERVE_HIDDEN;\n    const getItemsToRender = (index: number) => stories.peers.slice(Math.max(index - preserve, 0), Math.min(index + preserve + 1, stories.peers.length));\n    const itemsToRender = createMemo(() => getItemsToRender(stories.index));\n    const btnClose = <ButtonIconTsx ref={closeButton} icon={'close'} class={styles.ViewerClose} onClick={() => close()} />;\n    const transitions: WeakMap<Element, Accessor<boolean>> = new WeakMap();\n\n    return (\n      <div\n        ref={div}\n        class={classNames(\n          styles.Viewer,\n          !show() && styles.isInvisible,\n          isFull() && styles.isFull,\n          stories.hasViewer && styles.isReady\n        )}\n        onClick={(e) => {\n          if(animating) {\n            cancelEvent(e);\n            return;\n          }\n\n          if(e.target === div) {\n            close();\n          }\n        }}\n        style={{\n          '--stories-width': stories.width + 'px',\n          '--stories-height': stories.height + 'px'\n        }}\n      >\n        <div ref={backgroundDiv} class={styles.ViewerBackground} />\n        {!isFull() && btnClose}\n        {/* <For each={stories.peers}>{createStories}</For> */}\n        <TransitionGroup noWait={() => isFull()/*  || !stories.hasViewer */} transitions={transitions}>\n          <For each={itemsToRender()}>{createStories}</For>\n        </TransitionGroup>\n      </div>\n    );\n  });\n\n  let pauseTimeout: number;\n  const swipeHandler = new SwipeHandler({\n    element: div,\n    onSwipe: (xDiff, yDiff, e) => {\n      if(!(e instanceof TouchEvent)) {\n        return;\n      }\n\n      const jumpOn = Math.min(125, windowSize.width / 3);\n      const closeOn = Math.min(125, windowSize.height * 0.2);\n      if(yDiff > closeOn) {\n        close();\n        return true;\n      }\n\n      if(Math.abs(xDiff) < jumpOn) {\n        return false;\n      }\n\n      const peerIndex = stories.peers.indexOf(stories.peer);\n      const neighbourIndex = peerIndex + (xDiff < 0 ? 1 : -1);\n      const neighbour = stories.peers[neighbourIndex];\n      if(!neighbour) {\n        close();\n      } else {\n        actions.set({peer: neighbour});\n      }\n\n      return true;\n    },\n    verifyTouchTarget: (e) => {\n      return !findUpClassName(e.target, 'btn-icon') &&\n        !findUpClassName(e.target, 'btn-corner') &&\n        !findUpClassName(e.target, styles.ViewerStoryRepost) &&\n        !findUpClassName(e.target, styles.ViewerStoryMediaArea) &&\n        !findUpClassName(e.target, styles.ViewerStoryPrivacy) &&\n        !findUpClassName(e.target, styles.ViewerStoryCaptionText) &&\n        !findUpClassName(e.target, styles.ViewerStoryReactions) &&\n        !!findUpClassName(e.target, styles.ViewerStory) &&\n        !findUpClassName(e.target, styles.small) &&\n        !findUpClassName(e.target, styles.focused);\n    },\n    onStart: () => {\n      // if(stories.paused && !stories.hideInterface) {\n      //   return;\n      // }\n\n      pauseTimeout = window.setTimeout(() => {\n        actions.pause(true);\n      }, 200);\n    },\n    onReset: (e) => {\n      window.clearTimeout(pauseTimeout);\n      if(!e ||\n        !stories.paused ||\n        findUpClassName(e.target, 'btn-icon') ||\n        findUpClassName(e.target, styles.ViewerStoryPrivacy) ||\n        findUpClassName(e.target, 'btn-corner') ||\n        findUpClassName(e.target, styles.ViewerStoryReactions)) {\n        return;\n      }\n\n      const story = findUpClassName(e.target, styles.ViewerStory);\n      const caption = story?.querySelector('.' + styles.ViewerStoryCaption);\n      if(caption?.scrollTop) {\n        return;\n      }\n\n      if(story && stories.hideInterface) {\n        getAppWindow().document.addEventListener('click', cancelEvent, {capture: true, once: true});\n      }\n\n      const playStories = stories.playAfterGesture || !stories.hideInterface;\n      actions.toggleInterface(false);\n      if(playStories) {\n        actions.play();\n      }\n    }\n  });\n\n  let avatarFrom: ReturnType<typeof AvatarNew>;\n  const open = () => {\n    const target = props.target?.();\n    if(!target || !target.classList.contains('avatar')) {\n      setShow(true);\n      return;\n    }\n\n    avatarFrom = AvatarNew({\n      size: STORY_HEADER_AVATAR_SIZE,\n      isDialog: false,\n      useCache: false\n    });\n\n    avatarFrom.node.style.cssText = `position: absolute; visibility: hidden; z-index: 1000; transform-origin: top left;`;\n    getOverlayRoot().append(avatarFrom.node);\n\n    if(!untrack(() => show())) {\n      createEffect(() => {\n        if(avatarFrom.ready()) {\n          setShow(true);\n        }\n      });\n    }\n\n    createEffect(() => {\n      const peerId = stories.peer?.peerId;\n      if(!peerId || !avatarFrom) {\n        return;\n      }\n\n      untrack(() => {\n        avatarFrom.render({peerId});\n      });\n    });\n\n    onCleanup(() => {\n      if(!avatarFrom) {\n        return;\n      }\n\n      avatarFrom.node.remove();\n    });\n  };\n\n  const onDivClick = (e: MouseEvent) => {\n    if(animating) {\n      cancelEvent(e);\n    }\n\n    const story = findUpClassName(e.target, styles.ViewerStory);\n    const caption = story?.querySelector('.' + styles.ViewerStoryCaptionText) as HTMLElement;\n    const callback = caption && onMediaCaptionClick(caption, e);\n    if(!callback) {\n      return;\n    }\n\n    close(callback);\n    return false;\n  };\n\n  div.addEventListener('click', onDivClick, {capture: true});\n\n  const owner = getOwner();\n\n  const navigationItem: NavigationItem = {\n    type: 'stories',\n    onPop: () => {\n      if(animating) {\n        return false;\n      }\n\n      close();\n    }\n  };\n\n  appNavigationController.pushItem(navigationItem);\n\n  const getActiveStoryContainer = (el: Element = div) => {\n    return el.querySelector(`.${styles.ViewerStoryContainer}:not(.${styles.small})`) as HTMLElement;\n  };\n\n  const animate = (el: Element, forwards: boolean, done: () => void) => {\n    const container = getActiveStoryContainer(el);\n    if(!liteMode.isAvailable('animations') || !container) {\n      done();\n      return;\n    }\n\n    const containers = Array.from(el.querySelectorAll(`.${styles.ViewerStoryContainer}`));\n    let needAvatarOpacity: boolean;\n    const target = untrack(() => {\n      const target = props.target?.();\n      if(!target) {\n        return;\n      }\n\n      const overflowElement = findUpClassName(target, 'scrollable');\n      if(!overflowElement) {\n        return target;\n      }\n\n      const visibleRect = getVisibleRect(target as HTMLElement, overflowElement);\n      if(!visibleRect) {\n        if(avatarFrom) {\n          avatarFrom.node.remove();\n          avatarFrom = undefined;\n        }\n\n        return;\n      }\n\n      if(avatarFrom && (visibleRect.overflow.horizontal || visibleRect.overflow.vertical)) {\n        needAvatarOpacity = true;\n      }\n\n      return target;\n    });\n    const rectFrom = target && (target.querySelector('.avatar') || target).getBoundingClientRect();\n    const rectTo = container.getBoundingClientRect();\n    const borderRadius = avatarFrom ? '50%' : window.getComputedStyle(container).borderRadius;\n\n    // ! manually reverse the keyframes because Safari treats `direction: reverse` with lags\n    const makeKeyframes = (keyframes: Keyframe[]) => {\n      if(!forwards) {\n        keyframes.reverse();\n      }\n\n      return keyframes;\n    };\n\n    const options: KeyframeAnimationOptions = {\n      duration: 250,\n      easing: 'cubic-bezier(0.4, 0.0, 0.6, 1)'\n      // direction: forwards ? 'normal' : 'reverse'\n    };\n\n    // * animate avatar movement\n    let avatarAnimation: Animation, avatar: HTMLElement;\n    if(avatarFrom) {\n      avatar = container.querySelector<HTMLElement>(`.${styles.ViewerStoryHeaderAvatar}`);\n      avatar.style.visibility = 'hidden';\n      // const rectFrom = props.target.querySelector('.avatar').getBoundingClientRect();\n      const rectTo = avatar.getBoundingClientRect();\n      avatarFrom.node.style.top = `${rectFrom.top}px`;\n      avatarFrom.node.style.left = `${rectFrom.left}px`;\n      avatarFrom.node.style.visibility = '';\n      if(!avatarFrom.node.parentElement) {\n        getOverlayRoot().append(avatarFrom.node);\n      }\n      const translateX = rectTo.left - rectFrom.left;\n      const translateY = rectTo.top - rectFrom.top;\n\n      const keyframes: Keyframe[] = makeKeyframes([{\n        transform: `translate(0, 0) scale(${rectFrom.width / STORY_HEADER_AVATAR_SIZE})`\n      }, {\n        transform: `translate(${translateX}px, ${translateY}px) scale(1)`\n      }]);\n\n      if(needAvatarOpacity) {\n        keyframes[0].opacity = 0;\n        keyframes[1].opacity = 1;\n      }\n\n      avatarAnimation = avatarFrom.node.animate(keyframes, options);\n    }\n\n    const setOverflow = (overflow: boolean) => {\n      // container.style.overflow = overflow ? 'visible' : '';\n    };\n\n    if(!forwards) {\n      setOverflow(false);\n    }\n\n    // * animate main container\n    const translateX = rectFrom && rectFrom.left - (windowSize.width / 2) + rectFrom.width / 2;\n    const translateY = rectFrom && rectFrom.top - (windowSize.height / 2) + rectFrom.height / 2;\n    const containerAnimation = rectFrom && container.animate(makeKeyframes([{\n      borderRadius,\n      transform: `translate3d(${translateX}px, ${translateY}px, 0) scale3d(${rectFrom.width / rectTo.width}, ${rectFrom.height / rectTo.height}, 1)`,\n      opacity: 0\n    }, {\n      opacity: 1,\n      offset: 0.3\n    }, {\n      borderRadius: '0%',\n      transform: `translate3d(0, 0, 0) scale3d(1, 1, 1)`\n    }]), options);\n\n    // * animate simple opacity\n    const opacityAnimations = (containerAnimation ?\n      [backgroundDiv, !isFull() && closeButton].filter(Boolean) :\n      [container, el]\n    ).map((element) => {\n      return element.animate(makeKeyframes([{opacity: 0}, {opacity: 1}]), options);\n    });\n\n    // * animate small containers\n    const activeIndex = containers.indexOf(container);\n    containers.splice(activeIndex, 1);\n    const before = containers.slice(0, activeIndex);\n    const after = containers.slice(activeIndex);\n    const animateSmallContainers = (containers: Element[], next: boolean) => {\n      if(!rectFrom) {\n        return containers.map((container) => {\n          return container.animate(makeKeyframes([{opacity: 0}, {opacity: 1}]), options);\n        });\n      }\n\n      return containers.map((container, idx, arr) => {\n        const offsetX = (next ? idx + 1 : (arr.length - idx)) * 60 * (next ? -1 : 1);\n        return container.animate(makeKeyframes([{\n          transform: `translate3d(calc(var(--translateX) + ${offsetX}px), 0, 0) scale3d(${STORY_SCALE_SMALL / 2}, ${STORY_SCALE_SMALL / 2}, 1)`,\n          opacity: 0.001 // fix lag with fractal opacity so element should be prepared for animation\n        }, {\n          opacity: 0.001,\n          offset: 0.5\n        }, {\n          transform: `translate3d(var(--translateX), 0, 0) scale3d(${STORY_SCALE_SMALL}, ${STORY_SCALE_SMALL}, 1)`,\n          opacity: 1\n        }]), options);\n      })\n    };\n\n    const animations = [\n      ...opacityAnimations,\n      containerAnimation,\n      avatarAnimation,\n      ...animateSmallContainers(before, false),\n      ...animateSmallContainers(after, true)\n    ];\n\n    const promises = animations.map((animation) => animation?.finished);\n    return Promise.all(promises).then(() => {\n      if(avatarFrom) {\n        avatarFrom.node.remove();\n        avatar.style.visibility = '';\n      }\n\n      if(forwards) {\n        setOverflow(true);\n      }\n\n      done();\n    });\n  };\n\n  let overlaysActive: number;\n  const toggleOverlay = (active: boolean) => {\n    actions.toggleSorting('viewer', active);\n    overlayCounter.isDarkOverlayActive = active;\n    animationIntersector.checkAnimations2(active);\n\n    if(active) {\n      overlaysActive = overlayCounter.overlaysActive;\n    }\n  };\n\n  const listenerSetter = createListenerSetter();\n  let wasPlayingBeforeIdle: boolean;\n  listenerSetter.add(idleController)('change', (idle) => {\n    if(idle) {\n      wasPlayingBeforeIdle = !stories.paused;\n      actions.pause();\n      x.open();\n      return;\n    }\n\n    const onMouseDown = () => {\n      clearTimeout(timeout);\n    };\n\n    document.body.addEventListener('mousedown', onMouseDown, {once: true});\n    const timeout = setTimeout(() => {\n      document.body.removeEventListener('mousedown', onMouseDown);\n      x.close();\n    }, 100);\n\n    if(wasPlayingBeforeIdle) {\n      actions.play();\n    }\n  });\n\n  let wasPlayingBeforeOverlay: boolean;\n  listenerSetter.add(overlayCounter)('change', () => {\n    const active = overlayCounter.overlaysActive;\n    if(active > overlaysActive) {\n      wasPlayingBeforeOverlay = !stories.paused;\n      actions.pause();\n    } else if(active === overlaysActive && wasPlayingBeforeOverlay) {\n      actions.play();\n    }\n  });\n\n  let deferred: CancellablePromise<void> = deferredPromise<void>();\n\n  let animating = true;\n  return (\n    <Show when={wasShown()} fallback={ret}>\n      <Transition\n        onEnter={(el, done) => {\n          dispatchHeavyAnimationEvent(deferred, 1000);\n          disposeKeyDownListener = bindActiveWindowListener((w) => w.document.body, 'keydown', onKeyDown);\n          toggleOverlay(true);\n          animate(el, true, done);\n        }}\n        onAfterEnter={() => {\n          animating = false;\n          actions.viewerReady(true);\n          deferred.resolve();\n          // play();\n        }}\n        onExit={(el, done) => {\n          animating = true;\n          actions.viewerReady(false);\n          animate(el, false, done);\n        }}\n        onAfterExit={() => {\n          animating = false;\n          props.onExit?.();\n          stop();\n          deferred.resolve();\n        }}\n        appear\n      >\n        {show() && ret}\n      </Transition>\n    </Show>\n  );\n}\n\nexport const createStoriesViewerWithProvider = (\n  viewerProps: Parameters<typeof StoriesViewer>[0],\n  providerProps: Parameters<typeof StoriesProvider>[0]\n): JSX.Element => {\n  return createRoot((dispose) => {\n    const savedOnExit = viewerProps.onExit;\n    viewerProps.onExit = () => {\n      dispose();\n      savedOnExit?.();\n    };\n    return (\n      <StoriesProvider {...providerProps}>\n        {createStoriesViewer(viewerProps)}\n      </StoriesProvider>\n    );\n  });\n};\n\nexport const createStoriesViewer = (\n  props: Parameters<typeof StoriesViewer>[0] & Parameters<typeof StoriesProvider>[0]\n): JSX.Element => {\n  if(props.peers && !props.onExit) {\n    return createRoot((dispose) => {\n      props.onExit = () => dispose();\n      return (\n        <StoriesProvider peers={props.peers} index={props.index}>\n          {createStoriesViewer(props)}\n        </StoriesProvider>\n      );\n    });\n  }\n\n  return (\n    <Portal mount={document.getElementById('stories-viewer')}>\n      <StoriesViewer {...props} />\n    </Portal>\n  );\n};\n\nexport const createStoriesViewerWithStory = (\n  props: Omit<Parameters<typeof createStoriesViewer>[0], 'peers' | 'index'> & {\n    peerId: PeerId,\n    storyItem: StoryItem\n  }\n) => {\n  const [, rest] = splitProps(props, ['peerId', 'storyItem']);\n  return createStoriesViewer({\n    ...rest,\n    peers: [{\n      peerId: props.peerId,\n      stories: [props.storyItem],\n      index: 0,\n      count: 1\n    }],\n    index: 0\n  });\n};\n\nexport const createStoriesViewerWithPeer = async(\n  props: Omit<Parameters<typeof createStoriesViewer>[0], 'peers' | 'index'> & {\n    peerId: PeerId,\n    id?: number,\n  }\n): Promise<void> => {\n  const [, rest] = splitProps(props, ['peerId', 'id']);\n  const peerStories = await rootScope.managers.appStoriesManager.getPeerStories(props.peerId);\n  const storyIndex = props.id ? peerStories.stories.findIndex((story) => story.id === props.id) : undefined;\n  if(props.id) {\n    const storyItem = await rootScope.managers.appStoriesManager.getStoryById(props.peerId, props.id);\n    if(!storyItem) {\n      toastNew({langPackKey: 'Story.ExpiredToast'});\n      return;\n    }\n    // if(storyItem) { // own story can be missed in PeerStories\n    //   return createStoriesViewerWithPeer(props);\n    // }\n\n    createStoriesViewerWithStory({\n      ...rest,\n      peerId: props.peerId,\n      storyItem,\n      singleStory: true\n    });\n    return;\n  }\n\n  createStoriesViewer({\n    ...rest,\n    peers: [{\n      peerId: props.peerId,\n      stories: peerStories.stories,\n      maxReadId: peerStories.max_read_id,\n      index: storyIndex,\n      count: peerStories.stories.length\n    }],\n    index: 0\n  });\n};\n\n// export const openStories = (target?: Parameters<typeof StoriesViewer>[0]['target'], onExit?: () => void) => {\n//   const dispose = render(\n//     () => (\n//       <StoriesProvider stories={[]}>\n//         <StoriesViewer onExit={() => {dispose(); onExit?.();}} target={target} />\n//       </StoriesProvider>\n//     ),\n//     document.getElementById('stories-viewer')\n//   );\n// };\n","import type TChart from '@lib/tchart/chart';\nimport type {TChartData, TChatOriginalData} from '@lib/tchart/types';\nimport {Message, MessagesMessages, PostInteractionCounters, PublicForward, StatsAbsValueAndPrev, StatsBroadcastStats, StatsGraph, StatsGroupTopAdmin, StatsGroupTopInviter, StatsGroupTopPoster, StatsMegagroupStats, StatsMessageStats, StatsPercentValue, StatsPollStats, StatsPublicForwards, StatsStoryStats, StoryItem} from '@layer';\nimport I18n, {LangPackKey, i18n, join, joinElementsWith} from '@lib/langPack';\nimport Section from '@components/section';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {For, render} from 'solid-js/web';\nimport {Accessor, JSX, Show, createEffect, createRoot, createSignal, onMount} from 'solid-js';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {FontFamily} from '@config/font';\nimport {DcId, PickByType} from '@types';\nimport rootScope from '@lib/rootScope';\nimport customProperties from '@helpers/dom/customProperties';\nimport {hexToRgb, mixColors} from '@helpers/color';\nimport emptyPlaceholder from '@components/emptyPlaceholder';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport liteMode from '@helpers/liteMode';\nimport classNames from '@helpers/string/classNames';\nimport Icon from '@components/icon';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport RowTsx from '@components/rowTsx';\nimport {wrapReplyDivAndCaption} from '@components/chat/replyContainer';\nimport {formatFullSentTime} from '@helpers/date';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {wrapStoryMedia} from '@components/stories/preview';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport Button from '@components/buttonTsx';\nimport themeController from '@helpers/themeController';\nimport assumeType from '@helpers/assumeType';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport appImManager from '@lib/appImManager';\nimport {createStoriesViewerWithPeer} from '@components/stories/viewer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {avatarNew} from '@components/avatarNew';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\n\nconst CHANNEL_GRAPHS_TITLES: {[key in keyof PickByType<StatsBroadcastStats, StatsGraph>]: LangPackKey} = {\n  growth_graph: 'GrowthChartTitle',\n  followers_graph: 'FollowersChartTitle',\n  mute_graph: 'Notifications',\n  top_hours_graph: 'TopHoursChartTitle',\n  views_by_source_graph: 'ViewsBySourceChartTitle',\n  new_followers_by_source_graph: 'NewFollowersBySourceChartTitle',\n  languages_graph: 'LanguagesChartTitle',\n  interactions_graph: 'InteractionsChartTitle',\n  iv_interactions_graph: 'IVInteractionsChartTitle',\n  reactions_by_emotion_graph: 'ReactionsByEmotionChartTitle',\n  story_interactions_graph: 'StoryInteractionsChartTitle',\n  story_reactions_by_emotion_graph: 'StoryReactionsByEmotionChartTitle'\n};\n\nconst GROUP_GRAPH_TITLES: {[key in keyof PickByType<StatsMegagroupStats, StatsGraph>]: LangPackKey} = {\n  growth_graph: 'GrowthChartTitle',\n  members_graph: 'GroupMembersChartTitle',\n  new_members_by_source_graph: 'NewMembersBySourceChartTitle',\n  languages_graph: 'MembersLanguageChartTitle',\n  messages_graph: 'MessagesChartTitle',\n  actions_graph: 'ActionsChartTitle',\n  top_hours_graph: 'TopHoursChartTitle',\n  weekdays_graph: 'TopDaysOfWeekChartTitle'\n};\n\ntype StatsMessageStatsWithPoll = StatsMessageStats & Partial<Pick<StatsPollStats, 'votes_graph'>>;\n\nconst MESSAGE_GRAPH_TITLES: {[key in keyof PickByType<StatsMessageStatsWithPoll, StatsGraph>]: LangPackKey} = {\n  views_graph: 'ViewsAndSharesChartTitle',\n  reactions_by_emotion_graph: 'ReactionsByEmotionChartTitle',\n  votes_graph: 'PollStats.Votes'\n};\n\nconst STORY_GRAPH_TITLES: {[key in keyof PickByType<StatsStoryStats, StatsGraph>]: LangPackKey} = {\n  views_graph: 'ViewsAndSharesChartTitle',\n  reactions_by_emotion_graph: 'ReactionsByEmotionChartTitle'\n};\n\nconst POLL_GRAPH_TITLES: {[key in keyof PickByType<StatsPollStats, StatsGraph>]: LangPackKey} = {\n  votes_graph: 'PollStats.Votes'\n};\n\nconst getStatisticsErrorText = (error: unknown) => {\n  if(typeof(error) === 'string') return error;\n  if(!error || typeof(error) !== 'object') return;\n\n  const apiErrorType = (error as Partial<ApiError>).type;\n  if(apiErrorType) return apiErrorType;\n\n  const message = (error as Partial<Error>).message;\n  if(typeof(message) === 'string') return message;\n};\n\nconst CHANNEL_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsBroadcastStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  followers: 'FollowersChartTitle',\n  enabled_notifications: 'EnabledNotifications',\n  views_per_post: 'ViewsPerPost',\n  views_per_story: 'ViewsPerStory',\n  shares_per_post: 'SharesPerPost',\n  shares_per_story: 'SharesPerStory',\n  reactions_per_post: 'ReactionsPerPost',\n  reactions_per_story: 'ReactionsPerStory'\n};\n\nconst GROUP_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsMegagroupStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  members: 'MembersOverviewTitle',\n  messages: 'MessagesOverview',\n  viewers: 'ViewingMembers',\n  posters: 'PostingMembers'\n};\n\nconst MESSAGE_OVERVIEW_ITEMS: {[key in keyof PickByType<StatsMessageStats, StatsAbsValueAndPrev | StatsPercentValue>]: LangPackKey} = {\n  views: 'StatisticViews',\n  public_shares: 'PublicShares',\n  reactions: 'Reactions',\n  private_shares: 'PrivateShares'\n};\n\nconst STORY_OVERVIEW_ITEMS = MESSAGE_OVERVIEW_ITEMS;\n\nlet TChartPromise: Promise<any>;\nlet _TChart: typeof TChart;\nfunction ensureTChart() {\n  return TChartPromise ??= import('../../../lib/tchart/chart').then((module) => {\n    _TChart = module.default;\n  });\n}\n\nfunction extractColor(color: string): string {\n  return color.substring(color.indexOf('#'));\n}\n\nexport const makeAbsStats = (value: number, approximate?: boolean): StatsAbsValueAndPrev => {\n  return {\n    _: 'statsAbsValueAndPrev',\n    current: value,\n    previous: 0,\n    approximate\n  };\n};\n\nexport type LoadableList<T extends any = any> = {rendered: (HTMLElement | JSX.Element)[], values: T[], left: number, count: number, loadMore?: () => Promise<void>};\nexport const createLoadableList = <T extends any = any>(props: Partial<LoadableList<T>> = {}) => {\n  return createSignal<LoadableList<T>>({\n    rendered: [],\n    values: [],\n    left: 0,\n    count: 0,\n    ...props\n  }, {equals: false});\n};\n\nexport const MoreButton = (props: {\n  count: number,\n  callback: Parameters<typeof Button>[0]['onClick'],\n  key?: LangPackKey\n}) => {\n  return (\n    <Button\n      text={props.key || 'PollResults.LoadMore'}\n      textArgs={[props.count]}\n      onClick={(e) => props.callback(e)}\n      class=\"btn btn-primary btn-transparent primary\"\n      icon=\"down\"\n    />\n  );\n};\n\nconst StatisticsOverviewItem = ({\n  value,\n  title,\n  includeZeroValue,\n  describePercentage\n}: {\n  value: StatsAbsValueAndPrev | StatsPercentValue,\n  title: LangPackKey,\n  includeZeroValue?: boolean,\n  describePercentage?: boolean\n}) => {\n  const isPercentage = value._ === 'statsPercentValue';\n  let v: JSX.Element;\n  if(isPercentage) {\n    const n = (value.part / value.total * 100).toFixed(2);\n    v = `${n}%`;\n\n    if(describePercentage) {\n      v = (\n        <>\n          {`≈${value.part} `}\n          <span class=\"statistics-overview-item-value-description\">\n            {v}\n          </span>\n        </>\n      );\n    }\n  } else {\n    v = formatNumber(value.current, 1);\n\n    if(value.approximate) {\n      v = '≈' + v;\n    }\n\n    if(!value.current && !value.previous && !includeZeroValue) {\n      return;\n    }\n\n    if(value.current !== value.previous && value.previous) {\n      const diff = value.current - value.previous;\n      const absDiff = Math.abs(diff);\n      const vv = `${diff > 0 ? '+' : '-'}${formatNumber(absDiff, 1)}`;\n      const p = +(Math.abs(1 - value.current / value.previous) * 100).toFixed(2);\n      const str = `${vv} (${p}%)`;\n      v = (\n        <>\n          {v}{' '}\n          <span\n            class={classNames('statistics-overview-item-value-description', diff > 0 ? 'green' : 'red')}\n          >\n            {str}\n          </span>\n        </>\n      );\n    }\n  }\n\n  return (\n    <div class=\"statistics-overview-item\">\n      <div class=\"statistics-overview-item-value\">\n        {v}\n      </div>\n      <div class=\"statistics-overview-item-name\">\n        {i18n(title)}\n      </div>\n    </div>\n  );\n};\n\nexport const StatisticsOverviewItems = (props: {\n  items: Parameters<typeof StatisticsOverviewItem>[0][]\n}) => {\n  return (\n    <div class=\"statistics-overview\">\n      <For each={props.items}>{StatisticsOverviewItem}</For>\n    </div>\n  );\n};\n\nexport default class AppStatisticsTab extends SliderSuperTabEventable {\n  private chatId: ChatId;\n  private peerId: PeerId;\n  private mid: number;\n  private storyId: number;\n  private stats: StatsBroadcastStats | StatsMegagroupStats | StatsMessageStatsWithPoll | StatsStoryStats | StatsPollStats;\n  private messages: Map<number, Message.message>;\n  private stories: Map<number, StoryItem.storyItem>;\n  private dcId: DcId;\n  private graphDcIds: Map<string, DcId>;\n  private openPromise: CancellablePromise<void>;\n  private isBroadcast: boolean;\n  private isMegagroup: boolean;\n  private isMessage: boolean;\n  private isStory: boolean;\n  private isPoll: boolean;\n\n  protected onOpenAfterTimeout(): void {\n    this.openPromise.resolve();\n  }\n\n  private _construct(\n    recentPosts: {container: HTMLElement, postInteractionCounters: PostInteractionCounters}[],\n    topPosters: {container: HTMLElement, peerId: PeerId}[],\n    topAdmins: {container: HTMLElement, peerId: PeerId}[],\n    topInviters: {container: HTMLElement, peerId: PeerId}[],\n    publicForwards: Accessor<LoadableList>,\n    currentPost: (typeof recentPosts)[0]\n  ) {\n    const dateElement = new I18n.IntlDateElement({options: {}});\n    const getLabelDate: TChartData['getLabelDate'] = (value, options = {}) => {\n      options.displayYear ??= true;\n      options.isMonthShort ??= true;\n\n      const date = new Date(value);\n      dateElement.update({\n        date,\n        options: {\n          weekday: options.displayWeekDay ? options.isShort ? 'short' : 'long' : undefined,\n          year: options.displayYear ? 'numeric' : undefined,\n          hour: options.displayHours ? '2-digit' : undefined,\n          minute: options.displayHours ? '2-digit' : undefined,\n          month: options.isMonthShort ? 'short' : 'long',\n          day: 'numeric'\n        }\n      });\n\n      return dateElement.element.textContent;\n    };\n\n    const getLabelTime: TChartData['getLabelTime'] = (value: number) => {\n      const date = new Date(value);\n      dateElement.update({\n        date,\n        options: {\n          hour: '2-digit',\n          minute: '2-digit'\n        }\n      });\n\n      return dateElement.element.textContent;\n    };\n\n    const makeColors = () => {\n      const surface = customProperties.getProperty('surface-color');\n      const primary = customProperties.getProperty('primary-color');\n      const secondary = customProperties.getProperty('secondary-color');\n      const surfaceRgb = hexToRgb(surface);\n\n      const miniMask = mixColors(\n        hexToRgb(secondary),\n        mixColors(\n          hexToRgb(primary),\n          surfaceRgb,\n          0.1\n        ),\n        0.2\n      );\n\n      const miniFrame = mixColors(\n        hexToRgb(secondary),\n        mixColors(\n          hexToRgb(primary),\n          surfaceRgb,\n          0.3\n        ),\n        0.4\n      );\n\n      const colors: ConstructorParameters<typeof TChart>[0]['settings']['COLORS'] = {\n        primary: customProperties.getProperty('primary-color'),\n        secondary: customProperties.getProperty('secondary-color'),\n        background: surface,\n        backgroundRgb: surfaceRgb,\n        text: customProperties.getProperty('primary-text-color'),\n        dates: customProperties.getProperty('secondary-text-color'),\n        grid: `rgba(${hexToRgb(customProperties.getProperty('secondary-text-color')).join(', ')}, 0.2)`,\n        axis: {\n          x: customProperties.getProperty('secondary-text-color'),\n          y: customProperties.getProperty('secondary-text-color')\n        },\n        barsSelectionBackground: `rgba(${surfaceRgb.join(', ')}, 0.5)`,\n        miniMask: `rgba(${miniMask.join(', ')}, 0.6)`,\n        miniFrame: `rgb(${miniFrame.join(', ')})`\n      };\n\n      return colors;\n    };\n    let colors = makeColors();\n    this.listenerSetter.add(rootScope)('theme_changed', () => {\n      colors = makeColors();\n    });\n\n    const titles = this.isPoll ? POLL_GRAPH_TITLES : (this.isBroadcast ? CHANNEL_GRAPHS_TITLES : (this.isMegagroup ? GROUP_GRAPH_TITLES : (this.isStory ? STORY_GRAPH_TITLES : MESSAGE_GRAPH_TITLES)));\n    const graphs: {statsGraph: StatsGraph.statsGraph, title: LangPackKey, percentage: boolean, dcId: DcId}[] = Object.keys(titles).map((key) => {\n      const statsGraph = this.stats[key as keyof typeof titles];\n      return statsGraph && {\n        statsGraph,\n        title: titles[key as keyof typeof titles],\n        percentage: (key as keyof typeof titles) === 'languages_graph',\n        dcId: this.graphDcIds.get(key) ?? this.dcId\n      };\n    }).filter(Boolean);\n    const renderGraph = ({statsGraph, title, percentage, dcId}: typeof graphs[0]) => {\n      onMount(() => {\n        let data: TChatOriginalData = JSON.parse(statsGraph.json.data);\n        // console.log('data', JSON.parse(statsGraph.json.data));\n\n        const prepareData = (data: TChatOriginalData, percentage?: boolean) => {\n          for(const i in data.colors) {\n            const color = data.colors[i];\n            data.colors[i] = extractColor(color);\n          }\n\n          if(percentage) for(const i in data.types) {\n            if(data.types[i] === 'bar') {\n              data.types[i] = 'area';\n            }\n          }\n\n          return data;\n        };\n\n        data = prepareData(data, percentage);\n\n        type T = ConstructorParameters<typeof TChart>[0]['data'];\n        const addOptions: Partial<T> = {\n          getLabelDate,\n          getLabelTime,\n          tooltipOnHover: true\n        };\n\n        const zoomToken = statsGraph.zoom_token;\n        const tChart = _TChart.render({\n          container,\n          data: {\n            ...data,\n            ...addOptions,\n            x_on_zoom: zoomToken ? async(x) => {\n              const statsGraph = await this.managers.appStatisticsManager.loadAsyncGraph(zoomToken, x, dcId);\n              if(statsGraph._ === 'statsGraphError') {\n                return;\n              }\n\n              // console.log('zoom data', JSON.parse((statsGraph as StatsGraph.statsGraph).json.data));\n\n              return {\n                ...prepareData(JSON.parse((statsGraph as StatsGraph.statsGraph).json.data), percentage),\n                ...addOptions\n              };\n            } : undefined\n          } as T,\n          settings: {\n            darkMode: themeController.isNight(),\n            ALL_LABEL: I18n.format('Chart.Tooltip.All', true),\n            DATES_SIDE: 'left',\n            DATES_WEIGHT: 'normal',\n            DATES_FONT_SIZE: 14,\n            ZOOM_TEXT: I18n.format('ZoomOut', true),\n            FONT: {\n              family: FontFamily,\n              bold: '500',\n              normal: '400'\n            },\n            COLORS: colors\n          }\n        });\n\n        const setStyles = () => {\n          const p: [property: string, value: string][] = [\n            ['primary-color', colors.primary],\n            ['background-color', colors.background],\n            ['background-color-rgb', colors.backgroundRgb.join(', ')],\n            ['text-color', colors.text],\n            ['secondary-color', colors.secondary],\n            ['font-family', FontFamily]\n          ];\n\n          p.forEach(([property, value]) => {\n            tChart.$wrapper.style.setProperty(`--tchart-${property}`, value);\n          });\n        };\n\n        setStyles();\n\n        this.listenerSetter.add(rootScope)('theme_changed', () => {\n          tChart.setDarkMode(themeController.isNight(), {...colors});\n          setStyles();\n        });\n      });\n\n      const titleElement = document.createElement('div');\n      const captionElement = document.createElement('div');\n      titleElement.classList.add('statistics-title');\n      const t = i18n(title);\n      t.classList.add('statistics-title-text');\n      titleElement.append(t);\n      // let zoomOutElement: HTMLElement;\n      // if(graph.zoomToken || graph.isPercentage) {\n      //   zoomOutElement = document.createElement('div');\n      //   zoomOutElement.classList.add('statistics-title-zoom');\n      //   zoomOutElement.append(Icon('zoomout', 'statistics-title-zoom-icon'), i18n('ZoomOut'));\n      //   titleElement.append(zoomOutElement);\n      // }\n      let container: HTMLDivElement;\n      return (\n        <Section name={titleElement} nameRight={captionElement}>\n          <div class=\"statistics-chart\" ref={container}></div>\n        </Section>\n      );\n    };\n\n    const overviewTitles = this.isPoll ? undefined : (this.stats._ === 'stats.broadcastStats' ? CHANNEL_OVERVIEW_ITEMS : (this.isMegagroup ? GROUP_OVERVIEW_ITEMS : (this.isStory ? STORY_OVERVIEW_ITEMS : MESSAGE_OVERVIEW_ITEMS)));\n    const overviewItems: {value: StatsAbsValueAndPrev | StatsPercentValue, title: LangPackKey}[] = Object.keys(overviewTitles || {}).map((key) => {\n      const value = this.stats[key as keyof typeof overviewTitles];\n      return value && {\n        value,\n        title: overviewTitles[key as keyof typeof overviewTitles]\n      };\n    }).filter(Boolean);\n\n    const formatDateRange = (min: number, max: number) => {\n      return joinElementsWith([min, max].map((timestamp) => {\n        return new I18n.IntlDateElement({\n          date: new Date(timestamp * 1e3),\n          options: {\n            month: 'short',\n            day: 'numeric',\n            year: 'numeric'\n          }\n        }).element;\n      }), ' — ');\n    };\n\n    const period = (this.stats as StatsBroadcastStats).period;\n    const topPeersTitles: [LangPackKey, LangPackKey, LangPackKey] = ['TopMembers', 'TopAdmins', 'TopInviters'];\n    let postsContainer: HTMLDivElement;\n    const ret = (\n      <>\n        {currentPost && <Section>{currentPost.container}</Section>}\n        {!!overviewItems.length && <Section name=\"StatisticOverview\" nameRight={period && formatDateRange(period.min_date, period.max_date)}>\n          <StatisticsOverviewItems items={overviewItems} />\n        </Section>}\n        <For each={graphs}>{renderGraph}</For>\n        {recentPosts.length && <Section ref={postsContainer} name=\"RecentPosts\">\n          {recentPosts.map(({container}) => container)}\n        </Section>}\n        <For each={[topPosters, topAdmins, topInviters]}>{(topPeers, idx) => {\n          if(!topPeers.length) {\n            return;\n          }\n\n          topPeers = topPeers.slice();\n\n          const chatlist = appDialogsManager.createChatList();\n          chatlist.append(...topPeers.splice(0, 10).map(({container}) => container));\n          const [moreButton, setMoreButton] = createSignal<JSX.Element>(topPeers.length && MoreButton({\n            count: topPeers.length,\n            callback: () => {\n              setMoreButton(undefined);\n              chatlist.append(...topPeers.map(({container}) => container));\n            }\n          }));\n          return (\n            <Section name={topPeersTitles[idx()]} nameRight={period && formatDateRange(period.min_date, period.max_date)}>\n              {chatlist}\n              {moreButton()}\n            </Section>\n          );\n        }}</For>\n        {publicForwards().count && <Section name=\"PublicSharesCount\" nameArgs={[publicForwards().count]}>\n          <div\n            ref={(el) => {\n              appDialogsManager.setListClickListener({\n                list: el,\n                onFound: (target) => {\n                  const storyId = target.dataset.storyId;\n                  if(storyId) {\n                    createStoriesViewerWithPeer({\n                      target: () => target.querySelector('.avatar'),\n                      peerId: target.dataset.peerId.toPeerId(),\n                      id: +target.dataset.storyId\n                    });\n                    return false;\n                  }\n                },\n                withContext: undefined,\n                autonomous: undefined,\n                openInner: true\n              });\n            }}\n          >\n            {publicForwards().rendered}\n          </div>\n          <Show when={!!publicForwards().loadMore}>\n            <MoreButton\n              count={publicForwards().count - publicForwards().rendered.length}\n              callback={() => publicForwards().loadMore()}\n            />\n          </Show>\n        </Section>}\n      </>\n    );\n\n    if(postsContainer) {\n      const map: Map<HTMLElement, PostInteractionCounters> = new Map();\n      recentPosts.forEach(({container, postInteractionCounters}) => {\n        map.set(container, postInteractionCounters);\n      });\n\n      const findTarget = (e: MouseEvent | TouchEvent) => findUpClassName(e.target, 'statistics-post');\n      let counters: PostInteractionCounters;\n\n      const onOpenClick = () => {\n        this.slider.createTab(AppStatisticsTab).open(\n          this.chatId,\n          (counters as PostInteractionCounters.postInteractionCountersMessage).msg_id,\n          (counters as PostInteractionCounters.postInteractionCountersStory).story_id\n        );\n      };\n\n      attachClickEvent(postsContainer, (e) => {\n        counters = map.get(findTarget(e));\n        if(!counters) {\n          return;\n        }\n\n        onOpenClick();\n      }, {listenerSetter: this.listenerSetter});\n\n      createContextMenu({\n        buttons: [{\n          icon: 'statistics_filled',\n          text: 'ViewStatistics',\n          onClick: onOpenClick\n        }, {\n          icon: 'message',\n          text: 'Message.Context.Goto',\n          onClick: () => {\n            appImManager.setInnerPeer({\n              peerId: this.chatId.toPeerId(true),\n              lastMsgId: (counters as PostInteractionCounters.postInteractionCountersMessage).msg_id\n            });\n          },\n          verify: () => counters._ === 'postInteractionCountersMessage'\n        }, {\n          icon: 'stories',\n          text: 'ViewStory',\n          onClick: () => {\n            createStoriesViewerWithPeer({\n              peerId: this.chatId.toPeerId(true),\n              id: (counters as PostInteractionCounters.postInteractionCountersStory).story_id\n            });\n          },\n          verify: () => counters._ === 'postInteractionCountersStory'\n        }],\n        listenTo: postsContainer,\n        listenerSetter: this.listenerSetter,\n        findElement: (e) => {\n          const target = findTarget(e);\n          counters = map.get(target);\n          return target;\n        },\n        middleware: this.middlewareHelper.get()\n      });\n    }\n\n    return ret;\n  }\n\n  private async renderRecentPost(\n    postInteractionCounters: PostInteractionCounters,\n    peerId: PeerId = this.chatId.toPeerId(true),\n    message?: Message.message,\n    storyItem?: StoryItem.storyItem,\n    noLabels?: boolean\n  ) {\n    const subtitleRightFragment = document.createDocumentFragment();\n    const a: [Icon, number][] = [\n      ['reactions', postInteractionCounters.reactions],\n      ['reply', postInteractionCounters.forwards]\n    ];\n\n    !noLabels && a.forEach(([icon, count]) => {\n      if(!count) {\n        return;\n      }\n\n      const i = Icon(icon, 'statistics-post-counter-icon');\n      if(icon === 'reply') {\n        i.classList.add('icon-reflect');\n      }\n\n      const e = document.createElement('span');\n      e.classList.add('statistics-post-counter');\n      e.append(i, formatNumber(count, 1));\n      subtitleRightFragment.append(e);\n    });\n\n    const middleware = this.middlewareHelper.get();\n    const mediaEl = document.createElement('div');\n    mediaEl.classList.add('statistics-post-media');\n    let titleElement: HTMLDivElement;\n    let subtitleElement: HTMLDivElement;\n    const container = wrapSolidComponent(() => (\n      <RowTsx\n        clickable\n        noWrap\n        as={message || storyItem ? 'a' : undefined}\n        class=\"statistics-post\"\n      >\n        <RowTsx.Title\n          ref={titleElement}\n          class=\"statistics-post-title\"\n          titleRight={noLabels ? undefined : i18n('Views', [numberThousandSplitter(postInteractionCounters.views)])}\n        />\n        <RowTsx.Subtitle\n          ref={subtitleElement}\n          subtitleRight={noLabels ? undefined : subtitleRightFragment}\n        />\n        <RowTsx.Media element={mediaEl} size=\"abitbigger\" />\n      </RowTsx>\n    ), middleware);\n\n    if(message || storyItem) {\n      const {node, readyThumbPromise, setStoriesSegments} = avatarNew({\n        middleware,\n        size: 42,\n        isDialog: true,\n        peerId\n      });\n\n      container.dataset.peerId = '' + peerId;\n      if(storyItem) {\n        setStoriesSegments([{length: 1, type: 'unread'}]);\n        container.dataset.storyId = '' + storyItem.id;\n      } else {\n        container.dataset.mid = '' + message.mid;\n      }\n\n      mediaEl.append(node);\n      await readyThumbPromise;\n      titleElement.append(await wrapPeerTitle({peerId}));\n      subtitleElement.append(formatFullSentTime(message?.date || storyItem?.date));\n    } else if(postInteractionCounters._ === 'postInteractionCountersMessage') {\n      container.classList.add('statistics-post-message');\n      message ||= this.messages.get(postInteractionCounters.msg_id);\n      const isMediaSet = await wrapReplyDivAndCaption({\n        titleEl: subtitleElement,\n        title: formatFullSentTime(message.date),\n        subtitleEl: titleElement,\n        message,\n        mediaEl,\n        middleware,\n        withoutMediaType: true\n      });\n\n      if(!isMediaSet) {\n        const {node, readyThumbPromise} = avatarNew({middleware, peerId, size: 42});\n        mediaEl.append(node);\n        await readyThumbPromise;\n      }\n    } else {\n      container.classList.add('statistics-post-story');\n      storyItem ||= this.stories.get(postInteractionCounters.story_id);\n      titleElement.append(i18n('Story'));\n      subtitleElement.append(formatFullSentTime(storyItem.date));\n\n      const border = document.createElement('div');\n      border.classList.add('avatar-stories-simple', 'is-unread');\n      mediaEl.append(border);\n\n      await createRoot((dispose) => {\n        middleware.onDestroy(dispose);\n        const {ready, div} = wrapStoryMedia({\n          storyItem,\n          peerId: this.chatId.toPeerId(true),\n          forPreview: true,\n          noInfo: true,\n          withPreloader: false,\n          noAspecter: true\n        });\n\n        const deferred = deferredPromise<void>();\n\n        createEffect(() => {\n          if(ready()) {\n            mediaEl.append(div);\n            deferred.resolve();\n          }\n        });\n\n        return deferred;\n      });\n    }\n\n    return {container, postInteractionCounters};\n  }\n\n  private renderPeer = async(peer: StatsGroupTopPoster | StatsGroupTopAdmin | StatsGroupTopInviter | Message.message) => {\n    const peerId = peer._ === 'message' ? peer.peerId : peer.user_id.toPeerId(false);\n    const loadPromises: Promise<any>[] = [];\n    const {dom} = appDialogsManager.addDialogNew({\n      peerId: peerId,\n      container: false,\n      rippleEnabled: true,\n      avatarSize: 'abitbigger',\n      loadPromises,\n      wrapOptions: {\n        middleware: this.middlewareHelper.get()\n      },\n      meAsSaved: false\n    });\n\n    let toJoin: Node[];\n    if(peer._ === 'message') {\n      toJoin = [\n        await getChatMembersString(peerId.toChatId()),\n        i18n('Views', [formatNumber(peer.views, 1)])\n      ];\n      dom.listEl.dataset.mid = '' + peer.mid;\n    } else if(peer._ === 'statsGroupTopPoster') {\n      toJoin = [\n        peer.messages && i18n('messages', [peer.messages]),\n        peer.avg_chars && i18n('CharactersPerMessage', [i18n('Characters', [peer.avg_chars])])\n      ];\n    } else if(peer._ === 'statsGroupTopAdmin') {\n      toJoin = [\n        peer.deleted && i18n('Deletions', [peer.deleted]),\n        peer.banned && i18n('Bans', [peer.banned]),\n        peer.kicked && i18n('Restrictions', [peer.kicked])\n      ];\n    } else {\n      toJoin = [\n        peer.invitations && i18n('Invitations', [peer.invitations])\n      ];\n    }\n\n    toJoin = toJoin.filter(Boolean);\n    if(toJoin.length) {\n      dom.lastMessageSpan.replaceChildren(...join(toJoin, false));\n    }\n\n    await Promise.all(loadPromises);\n    return {container: dom.listEl, peerId};\n  };\n\n  private renderPublicForward = async(publicForward: PublicForward) => {\n    if(publicForward._ === 'publicForwardMessage') {\n      const message = publicForward.message as Message.message;\n      return this.renderRecentPost({\n        _: 'postInteractionCountersMessage',\n        forwards: message.forwards,\n        msg_id: message.mid,\n        views: message.views,\n        reactions: message.reactions ? message.reactions.results.reduce((acc, v) => acc + v.count, 0) : 0\n      }, message.peerId, message);\n    }\n\n    const storyItem = publicForward.story as StoryItem.storyItem;\n    if(!storyItem) {\n      return;\n    }\n\n    const storyViews = storyItem.views;\n    return this.renderRecentPost({\n      _: 'postInteractionCountersStory',\n      forwards: storyViews?.forwards_count || 0,\n      story_id: storyItem.id,\n      views: storyViews?.views_count || 0,\n      reactions: storyViews?.reactions_count || 0\n    }, getPeerId(publicForward.peer), undefined, storyItem);\n  };\n\n  private async loadStats() {\n    const peerId = this.peerId;\n    const manager = this.managers.appStatisticsManager;\n    const loadLimit = 100;\n    const func = this.isPoll ? manager.getPollStats : (this.isBroadcast ? manager.getBroadcastStats : (this.isMegagroup ? manager.getMegagroupStats : (this.isStory ? manager.getStoryStats : manager.getMessageStats)));\n    const postPromise = this.isMessage ? this.managers.appMessagesManager.reloadMessage(peerId, this.mid) : undefined;\n    const postPublicForwardsPromise = this.isMessage ? manager.getMessagePublicForwards({peerId, mid: this.mid, limit: loadLimit}) : undefined;\n    const storyPromise = this.isStory ? this.managers.appStoriesManager.getStoryById(peerId, this.storyId) : undefined;\n    const storyPublicForwardsPromise = this.isStory ? manager.getStoryPublicForwards({peerId, id: this.storyId, limit: loadLimit}) : undefined;\n    const statsPromise = func({\n      peerId,\n      dark: themeController.isNight(),\n      storyId: this.storyId,\n      mid: this.mid\n    });\n    const loadPollStats = (message: Message) => {\n      if(message?._ !== 'message' || message.media?._ !== 'messageMediaPoll' || !message.media.results.pFlags.can_view_stats) {\n        return;\n      }\n\n      return manager.getPollStats({\n        peerId,\n        mid: this.mid,\n        dark: themeController.isNight()\n      });\n    };\n    const pollStatsPromise = this.isMessage ?\n      this.managers.appMessagesManager.getMessageByPeer(peerId, this.mid).then((message) => {\n        return loadPollStats(message) || postPromise.then(loadPollStats);\n      }).catch((): undefined => undefined) :\n      undefined;\n    const [{stats, dcId}, pollStatsResult] = await Promise.all([statsPromise, pollStatsPromise]);\n    this.graphDcIds = new Map();\n    if(this.isMessage && pollStatsResult) {\n      (stats as StatsMessageStatsWithPoll).votes_graph = pollStatsResult.stats.votes_graph;\n      this.graphDcIds.set('votes_graph', pollStatsResult.dcId);\n    }\n\n    this.stats = stats;\n    this.dcId = dcId;\n\n    const promises: PromiseLike<any>[] = [];\n    for(const key in stats) {\n      const value = stats[key as keyof typeof stats] as any as StatsGraph;\n      if(value._ === 'statsGraphAsync') {\n        const isOptionalPollGraph = this.isMessage && key === 'votes_graph';\n        const promise = manager.loadAsyncGraph(\n          value.token,\n          undefined,\n          this.graphDcIds.get(key) ?? dcId\n        ).then((statsGraph) => {\n          if(statsGraph._ === 'statsGraphError') {\n            if(this.isPoll && statsGraph.error) {\n              throw new Error(statsGraph.error);\n            }\n\n            delete stats[key as keyof typeof stats];\n            return;\n          }\n\n          stats[key as keyof typeof stats] = statsGraph as any;\n        }, (err) => {\n          if(isOptionalPollGraph) {\n            delete stats[key as keyof typeof stats];\n            return;\n          }\n\n          throw err;\n        });\n        promises.push(promise);\n      } else if(value._ === 'statsGraphError') {\n        if(this.isPoll && value.error) {\n          throw new Error(value.error);\n        }\n\n        delete stats[key as keyof typeof stats];\n      }\n    }\n\n    const recentPosts = (stats as StatsBroadcastStats).recent_posts_interactions || [];\n    recentPosts.forEach((postInteractionCounters) => {\n      let promise: PromiseLike<any>;\n      if(postInteractionCounters._ === 'postInteractionCountersMessage') {\n        promise = this.managers.appMessagesManager.reloadMessage(peerId, postInteractionCounters.msg_id)\n        .then((message) => {\n          if(!message) {\n            indexOfAndSplice(recentPosts, postInteractionCounters);\n            return;\n          }\n\n          this.messages.set(message.mid, message as Message.message);\n        });\n      } else {\n        promise = this.managers.appStoriesManager.getStoryById(peerId, postInteractionCounters.story_id)\n        .then((storyItem) => {\n          if(!storyItem) {\n            indexOfAndSplice(recentPosts, postInteractionCounters);\n            return;\n          }\n\n          this.stories.set(storyItem.id, storyItem);\n        });\n      }\n\n      promises.push(promise);\n    });\n\n    const renderedPublicForwards = Promise.all([\n      postPromise,\n      postPublicForwardsPromise,\n      storyPromise,\n      storyPublicForwardsPromise\n    ]).then(async([message, messagePublicForwards, storyItem, storyPublicForwards]) => {\n      const [f, setF] = createLoadableList();\n      if(!message && !storyItem) {\n        return f;\n      }\n\n      assumeType<StatsMessageStats | StatsStoryStats>(stats);\n\n      if(message) {\n        assumeType<Message.message>(message);\n        this.messages.set(message.mid, message);\n        const totalPublicForwards = messagePublicForwards.count;\n        stats.views = makeAbsStats(message.views);\n        stats.reactions = makeAbsStats(message.reactions ? message.reactions.results.reduce((acc, v) => acc + v.count, 0) : 0);\n        stats.public_shares = makeAbsStats(totalPublicForwards);\n        stats.private_shares = makeAbsStats(message.forwards - totalPublicForwards, true);\n\n        setF((value) => (value.count = totalPublicForwards, value));\n\n        let offset: string;\n        const r = async(statsPublicForwards: StatsPublicForwards.statsPublicForwards) => {\n          offset = statsPublicForwards.next_offset;\n\n          const promises = statsPublicForwards.forwards.map(this.renderPublicForward);\n          const rendered = await Promise.all(promises);\n          setF((value) => {\n            value.rendered.push(...rendered.map(({container}) => container));\n            value.loadMore = offset ? () => {\n              return manager.getMessagePublicForwards({\n                peerId,\n                mid: this.mid,\n                limit: loadLimit,\n                offset\n              }).then(r);\n            } : undefined;\n            return value;\n          });\n        };\n\n        await r(messagePublicForwards);\n      } else {\n        const totalPublicForwards = storyPublicForwards.count;\n        const storyViews = storyItem.views;\n        stats.views = makeAbsStats(storyViews.views_count);\n        stats.reactions = makeAbsStats(storyViews.reactions_count || 0);\n        stats.public_shares = makeAbsStats(totalPublicForwards);\n        stats.private_shares = makeAbsStats(Math.abs((storyViews.forwards_count || 0) - totalPublicForwards), true);\n\n        setF((value) => (value.count = totalPublicForwards, value));\n\n        let offset: string;\n        const r = async(statsPublicForwards: StatsPublicForwards.statsPublicForwards) => {\n          offset = statsPublicForwards.next_offset;\n\n          const promises = statsPublicForwards.forwards.map(this.renderPublicForward);\n          const rendered = await Promise.all(promises);\n          setF((value) => {\n            value.rendered.push(...rendered.map(({container}) => container));\n            value.loadMore = offset ? () => {\n              return manager.getStoryPublicForwards({\n                peerId,\n                id: storyItem.id,\n                limit: loadLimit,\n                offset\n              }).then(r);\n            } : undefined;\n            return value;\n          });\n        };\n\n        await r(storyPublicForwards);\n      }\n\n      return f;\n    });\n    promises.push(renderedPublicForwards);\n\n    const topPosters = (stats as StatsMegagroupStats).top_posters || [];\n    const topAdmins = (stats as StatsMegagroupStats).top_admins || [];\n    const topInvites = (stats as StatsMegagroupStats).top_inviters || [];\n    const renderedTopPosters = topPosters.map(this.renderPeer);\n    const renderedTopAdmins = topAdmins.map(this.renderPeer);\n    const renderedTopInviters = topInvites.map(this.renderPeer);\n\n    return Promise.all(promises).then(() => {\n      const recentPostsPromises = recentPosts.map((postInteractionCounters) => {\n        return this.renderRecentPost(postInteractionCounters);\n      });\n\n      const currentPostPromise = this.isMessage ? this.renderRecentPost({\n        _: 'postInteractionCountersMessage',\n        msg_id: this.mid,\n        forwards: 0,\n        reactions: 0,\n        views: 0\n      }, undefined, undefined, undefined, true) : undefined;\n\n      const promises = [\n        Promise.all(recentPostsPromises),\n        Promise.all(renderedTopPosters),\n        Promise.all(renderedTopAdmins),\n        Promise.all(renderedTopInviters),\n        renderedPublicForwards,\n        currentPostPromise\n      ] as const;\n\n      return Promise.all(promises);\n    });\n  }\n\n  public async init(chatIdOrPeerId: ChatId | PeerId, mid?: number, storyId?: number, mode?: 'poll') {\n    this.container.classList.add('statistics-container');\n\n    this.isPoll = mode === 'poll';\n    this.chatId = this.isPoll ? chatIdOrPeerId.toChatId() : chatIdOrPeerId as ChatId;\n    this.peerId = this.isPoll ? chatIdOrPeerId as PeerId : this.chatId.toPeerId(true);\n    this.mid = mid;\n    this.storyId = storyId;\n    this.messages = new Map();\n    this.stories = new Map();\n    this.graphDcIds = new Map();\n    this.openPromise = deferredPromise<void>();\n\n    if(!this.isPoll && mid) {\n      this.isMessage = true;\n    } else if(!this.isPoll && storyId) {\n      this.isStory = true;\n    } else if(!this.isPoll) {\n      this.isBroadcast = await this.managers.appChatsManager.isBroadcast(this.chatId);\n      this.isMegagroup = await this.managers.appChatsManager.isMegagroup(this.chatId);\n    }\n\n    this.setTitle(this.isPoll ? 'PollStats.Title' : (this.isBroadcast ? 'Statistics' : (this.isMegagroup ? 'GroupStats.Title' : (this.isStory ? 'StoryStatistics' : 'PostStatistics'))));\n\n    const promise = Promise.all([\n      ensureTChart(),\n      this.openPromise,\n      this.loadStats()\n    ]);\n    promise.catch((): undefined => undefined);\n\n    const [hide, setHide] = createSignal(false);\n    const [placeholderState, setPlaceholderState] = createSignal<'loading' | 'empty' | 'error'>('loading');\n    const [statisticsError, setStatisticsError] = createSignal<string>();\n    const middleware = this.middlewareHelper.get();\n\n    const element = await emptyPlaceholder({\n      title: () => placeholderState() === 'error' ? (statisticsError() || i18n('Error.AnError')) : i18n(placeholderState() === 'empty' ? 'PollStats.NoVotes' : 'LoadingStats'),\n      description: () => placeholderState() === 'loading' ? i18n('LoadingStatsDescription') : undefined,\n      assetName: 'StatsEmoji',\n      middleware,\n      hide,\n      isFullSize: true\n    });\n\n    if(!middleware() || !element) {\n      return;\n    }\n\n    this.scrollable.append(element);\n    promise.then(async([_, __, loaded]) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(this.isPoll && (this.stats as StatsPollStats).votes_graph?._ !== 'statsGraph') {\n        setPlaceholderState('empty');\n        return;\n      }\n\n      const div = document.createElement('div');\n      if(!middleware()) {\n        return;\n      }\n\n      this.scrollable.append(div);\n      const dispose = render(() => this._construct(...loaded), div);\n      this.eventListener.addEventListener('destroy', dispose);\n\n      if(liteMode.isAvailable('animations')) {\n        const keyframes: Keyframe[] = [{opacity: '1'}, {opacity: '0'}];\n        const options: KeyframeAnimationOptions = {duration: 200, fill: 'forwards', easing: 'ease-in-out'};\n        const animations = [\n          element.animate(keyframes, options),\n          div.animate(keyframes.slice().reverse(), options)\n        ];\n\n        await Promise.all(animations.map((animation) => animation.finished)).catch((): undefined => undefined);\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      setHide(true);\n    }, (error) => {\n      if(middleware() && this.isPoll) {\n        setStatisticsError(getStatisticsErrorText(error));\n        setPlaceholderState('error');\n      }\n    });\n  }\n}\n","import PopupElement from '@components/popups';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport PopupSendGift from '@components/popups/sendGift';\n\ntype PickUserOptions = Parameters<typeof showPickUserPopup>[0];\n\n/**\n * The recipient picker behind every \"send a gift\" entry — the Settings row, the\n * birthday suggestion and `tg://settings/send-gift` all open the same one, and\n * pass only what is their own (the birthdays it puts on top, for instance).\n */\nexport default function showSendGiftPicker(options?: Partial<PickUserOptions>) {\n  return showPickUserPopup({\n    titleLangKey: 'SendGiftTo',\n    placeholder: 'Chat.Menu.SendGift',\n    selfPresence: 'SendGiftSelfCaption',\n    meAsSaved: false,\n    filterPeerTypeBy: ['isRegularUser', 'isBroadcast'],\n    onSelect: ([{peerId}]) => {\n      PopupElement.createPopup(PopupSendGift, {peerId});\n    },\n    ...options\n  });\n}\n","import PopupElement, {addCancelButton} from '.';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {Middleware} from '@helpers/middleware';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {Chat, ChatInvite} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {i18n, _i18n, LangPackKey} from '@lib/langPack';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport {avatarNew, wrapPhotoToAvatar} from '@components/avatarNew';\nimport generateTitleIcons from '@components/generateTitleIcons';\nimport {toastNew} from '@components/toast';\nimport PopupPeer from '@components/popups/peer';\n\n// const FAKE_CHAT_ID = Number.MAX_SAFE_INTEGER - 0x1000;\n\nconst getJoinLangKey = (chatInvite: ChatInvite.chatInvite | ChatInvite.chatInvitePeek): LangPackKey => {\n  if(chatInvite._ === 'chatInvitePeek') {\n    const chat = (chatInvite as ChatInvite.chatInvitePeek).chat as Chat.channel | Chat.chat;\n    return (chat as Chat.channel).pFlags.broadcast ? 'JoinByPeekChannelTitle' : 'JoinByPeekGroupTitle';\n  }\n\n  if(chatInvite.pFlags.request_needed) {\n    return 'RequestJoin.Button';\n  }\n\n  if(chatInvite.pFlags.broadcast) {\n    return 'JoinByPeekChannelTitle';\n  }\n\n  return 'JoinByPeekGroupTitle';\n};\n\nexport async function wrapChatInviteTitle(\n  chatInvite: ChatInvite.chatInvite,\n  middleware: Middleware\n) {\n  const title = document.createElement('div');\n  title.classList.add('peer-title', 'chat-title');\n\n  const icons = await generateTitleIcons({\n    peerId: NULL_PEER_ID,\n    noVerifiedIcon: false,\n    noFakeIcon: false,\n    noPremiumIcon: false,\n    peer: {\n      _: 'channel',\n      pFlags: {\n        verified: chatInvite.pFlags.verified,\n        scam: chatInvite.pFlags.scam,\n        fake: chatInvite.pFlags.fake\n      },\n      date: 0,\n      id: 0,\n      photo: undefined,\n      title: ''\n    },\n    wrapOptions: {\n      middleware\n    }\n  });\n\n  const titleFragment = wrapEmojiText(chatInvite.title);\n  if(icons.elements.length || icons.botVerification) {\n    title.classList.add('with-icons');\n    const titleInner = document.createElement('span');\n    titleInner.classList.add('peer-title-inner');\n    titleInner.append(titleFragment);\n    if(icons.botVerification) titleInner.append(icons.botVerification);\n    title.append(titleInner, ...icons.elements);\n  } else {\n    setInnerHTML(title, titleFragment);\n  }\n\n  return title;\n}\n\nexport async function wrapChatInviteAvatar(chatInvite: ChatInvite.chatInvite, middleware: Middleware, size: number) {\n  const avatarElem = avatarNew({\n    middleware,\n    size,\n    isDialog: false,\n    isSubscribed: !!chatInvite.subscription_pricing || undefined\n  });\n  if(chatInvite.photo?._ === 'photo') {\n    await wrapPhotoToAvatar(avatarElem, chatInvite.photo);\n    if(chatInvite.subscription_pricing) {\n      avatarElem.setIsSubscribed(true);\n    }\n  } else {\n    avatarElem.render({\n      peerTitle: chatInvite.title\n    });\n    await avatarElem.readyThumbPromise;\n  }\n\n  return avatarElem;\n}\n\nexport default class PopupJoinChatInvite extends PopupPeer {\n  constructor(\n    private hash: string,\n    private chatInvite: ChatInvite.chatInvite\n  ) {\n    super('popup-join-chat-invite', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      buttons: addCancelButton([{\n        langKey: getJoinLangKey(chatInvite),\n        callback: () => {\n          PopupJoinChatInvite.import(hash, chatInvite.title);\n        }\n      }]),\n      description: true\n    });\n\n    this.construct();\n  }\n\n  public static openChat(chatId: ChatId) {\n    const peerId = chatId.toPeerId(true);\n    // Use `open` (not `setInnerPeer`) so forums route through `op`, which opens the topics\n    // tab in the left sidebar instead of just dropping the user into the chat view.\n    appImManager.open({peerId});\n  }\n\n  public static import(hash: string, chatTitle?: string) {\n    rootScope.managers.appChatInvitesManager.importChatInvite(hash)\n    .then((result) => {\n      if(typeof(result) === 'object') {\n        void appImManager.openJoinChatWebView(result, chatTitle);\n        return;\n      }\n\n      if(result) {\n        this.openChat(result);\n      }\n    }, (error) => {\n      if((error as ApiError).type === 'INVITE_REQUEST_SENT') {\n        toastNew({langPackKey: 'RequestToJoinSent'});\n      }\n    });\n  }\n\n  public static async open(hash: string, chatInvite: ChatInvite) {\n    if(chatInvite._ === 'chatInviteAlready') {\n      // load missing chat\n      await rootScope.managers.appChatInvitesManager.checkChatInvite(hash);\n      this.openChat(chatInvite.chat.id);\n    } else if(chatInvite._ === 'chatInvitePeek') {\n      this.openChat(chatInvite.chat.id);\n    } else {\n      PopupElement.createPopup(PopupJoinChatInvite, hash, chatInvite);\n    }\n  }\n\n  private async construct() {\n    this.header.remove();\n    /* const fakeChat: Chat.channel | Chat.chat = {\n      _: chatInvite.pFlags.channel ? 'channel' : 'chat',\n      id: FAKE_CHAT_ID,\n      title: chatInvite.title,\n      photo: chatInvite.photo as any,\n      date: Date.now() / 1000 | 0,\n      version: 0,\n      participants_count: chatInvite.participants_count,\n      pFlags: chatInvite.pFlags as any\n    };\n\n    appChatsManager.saveApiChat(fakeChat); */\n\n    const {chatInvite} = this;\n\n    const avatarElem = await wrapChatInviteAvatar(chatInvite, this.middlewareHelper.get(), 100);\n    const title = await wrapChatInviteTitle(chatInvite, this.middlewareHelper.get());\n    // avatarElem.setAttribute('peer', '' + -fakeChat.id);\n\n    if(chatInvite.about) {\n      this.description.replaceChildren(wrapEmojiText(chatInvite.about));\n    } else {\n      this.description.remove();\n      this.description = undefined;\n    }\n\n    const isBroadcast = chatInvite.pFlags.broadcast;\n    const peopleCount = i18n(isBroadcast ? 'Subscribers' : 'Members', [numberThousandSplitter(chatInvite.participants_count)]);\n    peopleCount.classList.add('chat-participants-count');\n\n    this.body.append(...[avatarElem.node, title, peopleCount, this.description].filter(Boolean));\n\n    if(chatInvite.pFlags.request_needed) {\n      const caption = document.createElement('div');\n      _i18n(caption, isBroadcast ? 'RequestToJoinChannelDescription' : 'RequestToJoinGroupDescription');\n      caption.classList.add('chat-participants-count', 'request-caption');\n\n      this.body.append(caption);\n    }\n\n    this.show();\n  }\n}\n","import apiManagerProxy from '@lib/apiManagerProxy';\nimport {Chat, User} from '@layer';\n\n/**\n * Peer the stars are about to be spent on, to be passed as `spend_purpose_peer` of `inputStorePaymentStarsTopup`.\n * Only bots and channels count as a purpose, monoforums resolve to their broadcast.\n */\nexport default function getStarsSpendPurposePeerId(peerId: PeerId): PeerId {\n  if(!peerId) {\n    return;\n  }\n\n  const peer = apiManagerProxy.getPeer(peerId) as Chat.channel | User.user;\n  if(!peer) {\n    return;\n  }\n\n  if(peer._ === 'channel') {\n    return peer.pFlags?.monoforum && peer.linked_monoforum_id ?\n      peer.linked_monoforum_id.toPeerId(true) :\n      peerId;\n  }\n\n  return peer._ === 'user' && peer.pFlags?.bot ? peerId : undefined;\n}\n","/* @refresh reload */\n\nimport PopupElement from '.';\nimport maybe2x from '@helpers/maybe2x';\nimport {InputInvoice, MessageMedia, PaymentsPaymentForm, Photo, Document, StarsTopupOption, StarsTransaction, StarsTransactionPeer, MessageExtendedMedia, ChatInvite, StarsSubscription, StarsGiftOption, InputStorePaymentPurpose, WebDocument} from '@layer';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport Section from '@components/section';\nimport {createMemo, createRoot, createSignal, For, JSX, Show, untrack} from 'solid-js';\nimport paymentsWrapCurrencyAmount, {formatNanoton} from '@helpers/paymentsWrapCurrencyAmount';\nimport classNames from '@helpers/string/classNames';\nimport PopupPayment from '@components/popups/payment';\nimport useStars, {prefetchStars} from '@stores/stars';\nimport safeAssign from '@helpers/object/safeAssign';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport {createLoadableList} from '@components/sidebarRight/tabs/statistics';\nimport Row from '@components/rowTsx';\nimport showSendGiftPicker from '@components/popups/sendGiftPicker';\nimport {formatFullSentTime} from '@helpers/date';\nimport {avatarNew} from '@components/avatarNew';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport Icon from '@components/icon';\nimport {Middleware} from '@helpers/middleware';\nimport generatePhotoForExtendedMediaPreview from '@appManagers/utils/photos/generatePhotoForExtendedMediaPreview';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport wrapPhoto from '@components/wrappers/photo';\nimport currencyStarIcon from '@components/currencyStarIcon';\nimport {wrapChatInviteAvatar, wrapChatInviteTitle} from '@components/popups/joinChatInvite';\nimport tsNow from '@helpers/tsNow';\nimport Button from '@components/buttonTsx';\nimport showPickUserPopup, {showContactPickerPopup} from '@components/popups/pickUser';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport rootScope from '@lib/rootScope';\nimport appImManager from '@lib/appImManager';\nimport {toastNew} from '@components/toast';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport {MoreButton} from '@components/sidebarRight/tabs/statistics';\nimport formatStarsAmount from '@appManagers/utils/payments/formatStarsAmount';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport bigInt from 'big-integer';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport {IconTsx} from '@components/iconTsx';\nimport Tabs from '@components/tabs';\nimport {GrowHeightReveal} from '@helpers/solid/animations';\nimport getStarsSpendPurposePeerId from '@helpers/getStarsSpendPurposePeerId';\nimport confirmationPopup from '@components/confirmationPopup';\n\nexport function StarsStrokeStar(props: {stroke?: boolean, style?: JSX.HTMLAttributes<HTMLDivElement>['style']}) {\n  return (\n    <svg class={classNames('stars-star-icon', props.stroke && 'stars-star-icon-stroke')} width=\"26\" height=\"25\" viewBox=\"0 0 26 25\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style={props.style}>\n      {props.stroke && <path d=\"M1.55275 9.54149L2.08783 9.9899L1.55275 9.54149C0.839803 10.3922 0.951509 11.6599 1.80225 12.3728L3.70157 13.9645C4.85897 14.9344 6.38486 15.3453 7.87281 15.0877L10.9718 14.5512L8.2359 15.8647C6.9783 16.4685 6.05307 17.5988 5.70955 18.9509L4.94315 21.9674C4.80966 22.4929 4.89409 23.0499 5.17728 23.5122C5.75711 24.4587 6.99445 24.7559 7.94094 24.1761L12.8919 21.1432C12.9484 21.1