nodd\" clip-rule=\"evenodd\" d=\"M12.413 20.3615L7.4621 23.3945C6.9473 23.7098 6.27431 23.5482 5.95894 23.0334C5.80491 22.7819 5.75899 22.4789 5.8316 22.1931L6.598 19.1766C6.87465 18.0876 7.61981 17.1774 8.63265 16.6911L14.0338 14.0979C14.2857 13.977 14.3918 13.6749 14.2709 13.4231C14.173 13.2191 13.9516 13.105 13.7287 13.1436L7.71644 14.1845C6.49429 14.3961 5.24099 14.0586 4.29035 13.2619L2.39103 11.6702C1.92831 11.2825 1.86756 10.593 2.25533 10.1303C2.44393 9.90522 2.71514 9.7655 3.00787 9.74259L8.81084 9.28846C9.2208 9.25637 9.57808 8.99693 9.73546 8.61702L11.9741 3.21299C12.2052 2.65524 12.8447 2.39039 13.4024 2.62145C13.6702 2.7324 13.883 2.94518 13.9939 3.21299L16.2326 8.61702C16.39 8.99693 16.7473 9.25637 17.1572 9.28846L22.9921 9.74509C23.594 9.79219 24.0437 10.3183 23.9966 10.9202C23.974 11.2097 23.837 11.4783 23.616 11.6668L19.166 15.4605C18.8527 15.7275 18.7161 16.148 18.8124 16.5482L20.1805 22.2314C20.3218 22.8184 19.9605 23.4087 19.3735 23.55C19.0915 23.6179 18.794 23.5709 18.5467 23.4194L13.5551 20.3615C13.2046 20.1468 12.7634 20.1468 12.413 20.3615Z\" stroke=\"url(#paint2_linear_4300_30119)\" stroke-width=\"2.44444\" style=\"mix-blend-mode:soft-light\"/>\n      <defs>\n        <linearGradient id=\"paint0_linear_4300_30119\" x1=\"0.0870915\" y1=\"28.1529\" x2=\"41.4\" y2=\"-18.3997\" gradientUnits=\"userSpaceOnUse\">\n          <stop stop-color=\"#FDEB32\"/>\n          <stop offset=\"0.439058\" stop-color=\"#FEBD04\"/>\n          <stop offset=\"1\" stop-color=\"#D75902\"/>\n        </linearGradient>\n        <linearGradient id=\"paint1_linear_4300_30119\" x1=\"27.0556\" y1=\"3.61111\" x2=\"9.33333\" y2=\"15.8333\" gradientUnits=\"userSpaceOnUse\">\n          <stop stop-color=\"#DB5A00\"/>\n          <stop offset=\"1\" stop-color=\"#FF9145\"/>\n        </linearGradient>\n        <linearGradient id=\"paint2_linear_4300_30119\" x1=\"29.5\" y1=\"3.00001\" x2=\"13\" y2=\"13.0592\" gradientUnits=\"userSpaceOnUse\">\n          <stop stop-color=\"var(--star-background-color)\" stop-opacity=\"0\"/>\n          <stop offset=\"0.395833\" stop-color=\"var(--star-background-color)\" stop-opacity=\"0.85\"/>\n          <stop offset=\"0.520833\" stop-color=\"var(--star-background-color)\"/>\n          <stop offset=\"0.645833\" stop-color=\"var(--star-background-color)\" stop-opacity=\"0.85\"/>\n          <stop offset=\"1\" stop-color=\"var(--star-background-color)\" stop-opacity=\"0\"/>\n        </linearGradient>\n      </defs>\n    </svg>\n  );\n}\n\nexport function StarsStackedStars(props: {stars: number, size: number}) {\n  let icons = 1;\n  if(props.stars >= 2500) icons = 6;\n  else if(props.stars >= 1000) icons = 5;\n  else if(props.stars >= 500) icons = 4;\n  else if(props.stars >= 250) icons = 3;\n  else if(props.stars >= 50) icons = 2;\n  let iconsElements: JSX.Element;\n  const m = props.size + (props.size === 18 ? 4 : 6);\n  if(icons > 1) {\n    iconsElements = [];\n    for(let i = 0; i < icons; ++i) iconsElements.push((\n      <StarsStrokeStar\n        stroke={i !== (icons - 1)}\n        style={{\n          'margin-right': (Math.min(i, 1) * -m) + 'px'\n        }}\n      />\n    ));\n  } else {\n    iconsElements = <StarsStrokeStar />;\n  }\n\n  iconsElements = (\n    <div\n      class=\"stars-stacked\"\n      style={{\n        'width': `${props.size + (icons - 1) * 6}px`,\n        '--size': props.size + 'px'\n      }}\n    >\n      {iconsElements}\n    </div>\n  );\n  return iconsElements;\n}\n\nexport function StarsStar() {\n  return currencyStarIcon();\n}\n\nexport function StarsBalance() {\n  const stars = useStars();\n  return (\n    <div class=\"stars-balance\">\n      <div class=\"stars-balance-title\">{i18n('StarsBalance')}</div>\n      <div class=\"stars-balance-subtitle\"><StarsStar />{'' + (stars() ?? 0)}</div>\n    </div>\n  );\n}\n\nexport function StarsAmount(props: {stars: Long}) {\n  return (\n    <div class={classNames('popup-stars-pay-amount', 'popup-stars-pay-amount-plain')}>\n      <StarsStar />\n      {props.stars}\n    </div>\n  );\n}\n\nexport function StarsChange(props: {\n  stars: Long,\n  isRefund?: boolean,\n  noSign?: boolean,\n  reverse?: boolean,\n  inline?: boolean,\n  ton?: boolean\n}) {\n  return (\n    <div class={classNames('popup-stars-pay-amount', +props.stars > 0 ? 'green' : 'danger', props.reverse && 'reverse', props.inline && 'inline')}>\n      {`${+props.stars > 0 && !props.noSign ? '+' : ''}${props.stars}`}\n      {props.ton ? <IconTsx icon=\"ton\" /> : <StarsStar />}\n      {props.isRefund && <span class=\"popup-stars-pay-amount-status\">{i18n('StarsRefunded')}</span>}\n    </div>\n  );\n}\n\nexport function getStarsTransactionTitle(transaction: StarsTransaction) {\n  if(transaction.subscription_period) {\n    return i18n('Stars.Subscription.Title');\n  }\n\n  if(transaction.pFlags.gift) {\n    return i18n('StarsGiftReceived');\n  }\n\n  const map: {[key in StarsTransactionPeer['_']]?: LangPackKey} = {\n    starsTransactionPeerFragment: 'Stars.Via.Fragment',\n    starsTransactionPeerPremiumBot: 'Stars.Via.Bot',\n    starsTransactionPeerAppStore: 'Stars.Via.App',\n    starsTransactionPeerPlayMarket: 'Stars.Via.App'\n  };\n\n  const key = map[transaction.peer._] ?? 'Stars.Via.Unsupported';\n  return i18n(key);\n}\n\nexport function getExamplesAnchor(hide: (callback: () => void) => void) {\n  let loading = false;\n  const popularAppBotsPromise = rootScope.managers.appAttachMenuBotsManager.getPopularAppBots();\n  const anchor = anchorCallback(async() => {\n    if(loading) return;\n    loading = true;\n    const {userIds: botIds} = await popularAppBotsPromise;\n    loading = false;\n    showPickUserPopup({\n      onSelect: ([obj]) => {\n        hide(() => {\n          appImManager.setInnerPeer(obj);\n        });\n      },\n      peerType: ['custom'],\n      getMoreCustom: async() => {\n        return {\n          result: botIds.map((botId) => botId.toPeerId(false)),\n          isEnd: true\n        };\n      },\n      titleLangKey: 'SearchAppsExamples'\n    });\n  });\n  anchor.append(i18n('GiftStarsSubtitleLinkName'));\n  return anchor;\n}\n\nexport async function getStarsTransactionTitleAndMedia({\n  transaction,\n  middleware,\n  size,\n  paidMedia,\n  paidMediaPeerId,\n  chatInvite,\n  subscription,\n  photo\n}: {\n  transaction: StarsTransaction,\n  middleware: Middleware,\n  size: number,\n  paidMedia?: MessageMedia.messageMediaPaidMedia,\n  paidMediaPeerId?: PeerId,\n  chatInvite?: ChatInvite.chatInvite,\n  subscription?: StarsSubscription,\n  photo?: WebDocument.webDocument\n}) {\n  const [title, media] = await Promise.all([\n    (() => {\n      if(subscription) {\n        return wrapPeerTitle({peerId: getPeerId(subscription.peer)});\n      }\n\n      if(chatInvite) {\n        return wrapChatInviteTitle(chatInvite, middleware);\n      }\n\n      if(paidMedia || transaction?.extended_media) {\n        return wrapPeerTitle({peerId: paidMediaPeerId || getPeerId((transaction.peer as StarsTransactionPeer.starsTransactionPeer).peer)});\n      }\n\n      if(!transaction || transaction.peer._ === 'starsTransactionPeer') {\n        return wrapPeerTitle({\n          peerId: transaction ? getPeerId((transaction.peer as StarsTransactionPeer.starsTransactionPeer).peer) : paidMediaPeerId\n        });\n      }\n\n      return getStarsTransactionTitle(transaction);\n    })(),\n    (async() => {\n      const _wrapPhoto = async(container: HTMLElement, photo: Parameters<typeof wrapPhoto>[0]['photo']) => {\n        const loadPromises: Promise<any>[] = [];\n        wrapPhoto({\n          container,\n          photo,\n          boxWidth: size,\n          boxHeight: size,\n          middleware,\n          loadPromises,\n          withoutPreloader: true,\n          size: photo._ === 'webDocument' ? {_: 'photoSizeEmpty', type: ''} : undefined\n        });\n\n        await Promise.all(loadPromises);\n      };\n\n      if(photo) {\n        const container = document.createElement('div');\n        container.classList.add('popup-stars-pay-item');\n        await _wrapPhoto(container, photo);\n        return container;\n      }\n\n      if(chatInvite) {\n        const avatar = await wrapChatInviteAvatar(chatInvite, middleware, 90);\n        return avatar.node;\n      }\n\n      if(paidMedia || transaction?.extended_media) {\n        const array = paidMedia?.extended_media || transaction.extended_media;\n        let media: Photo.photo | Document.document;\n\n        if(paidMedia) {\n          const extendedMedia = paidMedia.extended_media[0] as MessageExtendedMedia.messageExtendedMediaPreview;\n          media = generatePhotoForExtendedMediaPreview(extendedMedia);\n        } else {\n          const extendedMedia = transaction.extended_media[0];\n          media = (extendedMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo ||\n            (extendedMedia as MessageMedia.messageMediaDocument).document as Document.document;\n        }\n\n        const container = document.createElement('div');\n        container.classList.add('popup-stars-transaction-media', 'is-paid-media');\n\n        if(paidMedia) {\n          const spoilerContainer = await wrapMediaSpoiler({\n            media,\n            animationGroup: 'chat',\n            middleware,\n            width: size,\n            height: size\n          });\n          container.append(spoilerContainer);\n        } else {\n          await _wrapPhoto(container, media);\n        }\n\n        const length = array.length;\n        if(length > 1) {\n          const counter = document.createElement('span');\n          counter.classList.add('popup-stars-transaction-media-counter');\n          counter.textContent = '' + length;\n          container.append(counter);\n        }\n\n        return container;\n      }\n\n      if(transaction?.photo) {\n        const container = document.createElement('div');\n        container.classList.add('popup-stars-transaction-media', 'is-paid-media');\n        await _wrapPhoto(container, transaction?.photo);\n        return container;\n      }\n\n      let peerId: PeerId;\n      if(subscription) {\n        peerId = getPeerId(subscription.peer);\n      } else if(transaction && transaction.peer._ === 'starsTransactionPeer') {\n        peerId = getPeerId(transaction.peer.peer);\n      } else if(paidMediaPeerId) {\n        peerId = paidMediaPeerId;\n      }\n\n      if(peerId) {\n        const avatar = avatarNew({peerId, size, middleware});\n        await avatar.readyThumbPromise;\n        return avatar.node;\n      }\n\n      const div = document.createElement('div');\n      div.classList.add('popup-stars-transaction-media');\n      div.append(Icon('star'));\n      return div;\n    })()\n  ]);\n\n  return {title, media};\n}\n\n/**\n * Picks who the stars are for, then opens the top-up for them — the row inside\n * this popup and `tg://settings/stars/gift` are the same thing.\n */\nexport function showGiftStarsPicker() {\n  return showSendGiftPicker({\n    titleLangKey: 'TelegramStarsGift',\n    onSelect: ([{peerId}]) => {\n      PopupElement.createPopup(PopupStars, {giftPeerId: peerId});\n    }\n  });\n}\n\nexport default class PopupStars extends PopupElement {\n  private options: (StarsTopupOption | StarsGiftOption)[];\n  private paymentForm: PaymentsPaymentForm.paymentsPaymentFormStars;\n  private itemPrice: Long;\n  private onTopup: (amount: number) => void;\n  private onCancel: () => void;\n  private purpose: 'reaction' | 'stargift' | (string & {});\n  private giftPeerId: PeerId;\n  private peerId: PeerId;\n  private appConfig: MTAppConfig;\n  private toppedUp: boolean;\n  private ton: boolean;\n  private spendPurposePeerId: PeerId;\n  private purposePeerId: PeerId;\n  private purchaseBlocked: boolean;\n\n  constructor(options: {\n    paymentForm?: PaymentsPaymentForm.paymentsPaymentFormStars,\n    itemPrice?: Long,\n    onTopup?: (amount: number) => void,\n    onCancel?: () => void,\n    purpose?: PopupStars['purpose'],\n    giftPeerId?: PeerId,\n    peerId?: PeerId,\n    ton?: boolean,\n    spendPurposePeerId?: PeerId\n  } = {}) {\n    super('popup-stars', {\n      closable: true,\n      overlayClosable: true,\n      floatingHeader: true,\n      body: true,\n      title: options.ton ? 'GramBalance' : 'TelegramStars',\n      scrollable: true\n    });\n\n    safeAssign(this, options);\n\n    this.purposePeerId = getStarsSpendPurposePeerId(this.spendPurposePeerId);\n\n    this.construct();\n  }\n\n  private renderTransaction = async(transaction: StarsTransaction) => {\n    const middleware = this.middlewareHelper.get();\n    const {title, media} = await getStarsTransactionTitleAndMedia({\n      transaction,\n      middleware,\n      size: 42\n    });\n\n    return createRoot((dispose) => {\n      middleware.onDestroy(dispose);\n\n      const _title = transaction.extended_media ? i18n('StarMediaPurchase') : title;\n      let midtitle: HTMLElement | DocumentFragment;\n      if(transaction.extended_media) {\n        midtitle = title;\n      } else if(transaction.description) {\n        midtitle = wrapEmojiText(transaction.description);\n      } else if(transaction.pFlags.reaction) {\n        midtitle = i18n('StarsReactionTitle');\n      } else if(transaction.giveaway_post_id) {\n        midtitle = i18n('StarsGiveawayPrizeReceived');\n      } else if(transaction.paid_messages) {\n        midtitle = i18n('PaidMessages.FeeForMessages', [transaction.paid_messages]);\n      } else if(formatStarsAmount(transaction.amount) > 0) {\n        midtitle = transaction.pFlags.gift ? i18n('StarsGiftReceived') : i18n('Stars.TopUp');\n      } else if(transaction.subscription_period) {\n        midtitle = i18n('Stars.Subscription.Title');\n      }\n\n      const subtitle = formatFullSentTime(transaction.date);\n\n      let subtitleStatus: HTMLElement;\n      if(transaction.pFlags.refund) subtitleStatus = i18n('StarsRefunded');\n      else if(transaction.pFlags.failed) subtitleStatus = i18n('StarsFailed');\n      else if(transaction.pFlags.pending) subtitleStatus = i18n('StarsPending');\n\n      let container: HTMLDivElement;\n      (\n        <Row\n          ref={container}\n          clickable={() => {\n            PopupPayment.create({\n              transaction\n            });\n          }}\n        >\n          <Row.Title><b>{_title}</b></Row.Title>\n          <Row.Midtitle>{midtitle}</Row.Midtitle>\n          <Row.Subtitle>{subtitleStatus ? [subtitle, ' — ', subtitleStatus] : subtitle}</Row.Subtitle>\n          <Row.RightContent><StarsChange stars={formatStarsAmount(transaction.amount)} ton={transaction.amount._ === 'starsTonAmount'} /></Row.RightContent>\n          <Row.Media size=\"abitbigger\">{media}</Row.Media>\n        </Row>\n      );\n\n      return container;\n    });\n  };\n\n  private renderSubscription = async(subscription: StarsSubscription) => {\n    const middleware = this.middlewareHelper.get();\n\n    const peerId = getPeerId(subscription.peer);\n    const title = await wrapPeerTitle({peerId});\n    title.classList.add('text-bold');\n    const avatar = untrack(() => avatarNew({peerId, size: 42, middleware}));\n    await avatar.readyThumbPromise;\n\n    const isCancelled = !!subscription.pFlags.canceled;\n    const isExpired = tsNow(true) > subscription.until_date;\n\n    return createRoot((dispose) => {\n      middleware.onDestroy(dispose);\n\n      let container: HTMLDivElement;\n      (\n        <Row\n          ref={container}\n          clickable={async() => {\n            const popup = await PopupPayment.create({\n              subscription,\n              noPaymentForm: true\n            });\n\n            popup.addEventListener('finish', (result) => {\n              if(result === 'paid') {\n                this.hide();\n              }\n            });\n          }}\n        >\n          <Row.Title titleRight={!isCancelled && (<StarsAmount stars={subscription.pricing.amount} />)}>{title}</Row.Title>\n          <Row.Subtitle subtitleRight={!isCancelled && i18n('Stars.Subscriptions.PerMonth')}>{\n            i18n(\n              isExpired ? 'Stars.Subscriptions.Expired' : isCancelled ?\n                'Stars.Subscriptions.Expires' :\n                'Stars.Subscriptions.Renews',\n              [formatFullSentTime(subscription.until_date, undefined, true)]\n            )}</Row.Subtitle>\n          <Row.RightContent>{isCancelled && (<span class=\"popup-stars-cancelled danger\">{i18n('Stars.Subscriptions.Cancelled')}</span>)}</Row.RightContent>\n          <Row.Media size=\"abitbigger\">{avatar.node}</Row.Media>\n        </Row>\n      );\n\n      return container;\n    });\n  };\n\n  private _construct(\n    image: HTMLElement,\n    peerTitle?: HTMLElement,\n    avatar?: HTMLElement\n  ) {\n    if(!this.ton) {\n      this.header.append(StarsBalance() as HTMLElement);\n    }\n\n    const stars = useStars(this.ton);\n    const starsNeeded = createMemo(() => {\n      if(!this.itemPrice) return bigInt.zero;\n      return bigInt(this.itemPrice.toString()).minus(stars());\n    });\n    const topupOptions = createMemo(() => {\n      if(this.ton) return [];\n      if(this.itemPrice) {\n        const filtered = this.options.filter((option) => starsNeeded().lt(option.stars));\n        if(!filtered.length) {\n          return [this.options[this.options.length - 1]];\n        }\n\n        return filtered;\n      }\n\n      return this.options;\n    });\n    const alwaysVisible = topupOptions().length > 3 ? topupOptions().filter((option) => !option.pFlags.extended) : topupOptions();\n    const [extended, setExtended] = createSignal(topupOptions().length <= 3);\n    const displayingRows = createMemo(() => Math.ceil((extended() ? topupOptions().length : alwaysVisible.length) / 2));\n\n    let busy = false;\n\n    let title: JSX.Element;\n    if(this.giftPeerId && !this.itemPrice) {\n      title = i18n('GiftStarsTitle');\n    } else if(this.itemPrice) {\n      if(this.ton) {\n        title = i18n('TonNeededTitle', [formatNanoton(starsNeeded().toString())]);\n      } else {\n        title = i18n('StarsNeededTitle', [starsNeeded().toJSNumber()]);\n      }\n    } else if(this.ton) {\n      title = i18n('GramBalance');\n    } else {\n      title = i18n('TelegramStars');\n    }\n\n    let subtitle: JSX.Element;\n    if(this.giftPeerId && !this.purpose) {\n      subtitle = (\n        <>\n          {i18n('GiftStarsSubtitle', [peerTitle])}\n          {' '}\n          {getExamplesAnchor(this.hideWithCallback)}\n        </>\n      );\n    } else if(this.ton) {\n      subtitle = i18n('TonNeededText');\n    } else if(this.purpose) {\n      let langPackKey: LangPackKey;\n      if(this.purpose === 'reaction') {\n        langPackKey = 'Stars.TopUp.Reaction';\n      } else {\n        const key = `Stars.TopUp.Label_`;\n        // @ts-ignore\n        if(I18n.strings.get(key + this.purpose)) {\n          // @ts-ignore\n          langPackKey = key + this.purpose;\n        } else {\n          // @ts-ignore\n          langPackKey = key + 'default';\n        }\n      }\n\n      subtitle = i18n(langPackKey as LangPackKey, [peerTitle]);\n    } else if(this.itemPrice) {\n      subtitle = i18n(this.paymentForm ? 'StarsNeededText' : 'Stars.Subscribe.Need', [peerTitle]);\n    } else {\n      subtitle = i18n(this.purchaseBlocked ? 'StarsPurchaseUnavailable' : 'TelegramStarsInfo');\n    }\n\n    const firstSection = !this.purchaseBlocked && (\n      <Section caption=\"Stars.TOS\">\n        <div class=\"popup-stars-options\" style={{height: (displayingRows() * 79 + (displayingRows() - 1) * 8) + 'px'}}>\n          <Show when={this.ton}>\n            <Button\n              class=\"btn-primary btn-color-primary\"\n              text=\"FragmentTopUp\"\n              onClick={() => {\n                safeWindowOpen(this.appConfig.ton_topup_url);\n              }}\n            />\n          </Show>\n          <For each={topupOptions()}>{(option, idx) => {\n            const index = createMemo(() => extended() || option.pFlags.extended ? idx() : alwaysVisible.indexOf(option));\n            const translateX = createMemo(() => (index() % 2) ? 'calc(100% + .5rem)' : '0');\n            const translateY = createMemo(() => (Math.floor(index() / 2) * 79 + Math.floor(index() / 2) * 8) + 'px');\n            const isFullWidth = createMemo(() => {\n              if(!((extended() ? topupOptions() : alwaysVisible).length % 2)) {\n                return false;\n              }\n\n              if(extended() || option.pFlags.extended) {\n                return index() === (topupOptions().length - 1);\n              }\n\n              return index() === (alwaysVisible.length - 1);\n            });\n\n            const iconsElements = StarsStackedStars({stars: +option.stars, size: 26});\n\n            return (\n              <div\n                class=\"popup-stars-option\"\n                classList={{invisible: option.pFlags.extended && !extended(), full: isFullWidth()}}\n                style={{transform: `translate(${translateX()}, ${translateY()})`}}\n                onClick={async() => {\n                  if(busy) {\n                    return;\n                  }\n\n                  busy = true;\n\n                  const purpose: InputStorePaymentPurpose = this.giftPeerId ? {\n                    _: 'inputStorePaymentStarsGift',\n                    amount: option.amount,\n                    currency: option.currency,\n                    stars: option.stars,\n                    user_id: await this.managers.appUsersManager.getUserInput(this.giftPeerId.toUserId())\n                  } : {\n                    _: 'inputStorePaymentStarsTopup',\n                    amount: option.amount,\n                    currency: option.currency,\n                    stars: option.stars,\n                    spend_purpose_peer: this.purposePeerId ?\n                      await this.managers.appPeersManager.getInputPeerById(this.purposePeerId) :\n                      undefined\n                  };\n\n                  const inputInvoice: InputInvoice = {\n                    _: 'inputInvoiceStars',\n                    purpose\n                  };\n                  try {\n                    const paymentForm = await this.managers.appPaymentsManager.getPaymentForm(inputInvoice);\n                    const popup = await PopupPayment.create({\n                      inputInvoice,\n                      paymentForm\n                    });\n\n                    popup.addEventListener('finish', (result) => {\n                      if(result === 'paid') {\n                        this.toppedUp = true;\n\n                        if(this.onTopup) {\n                          this.hide();\n                          this.onTopup(+option.amount);\n                        }\n                      }\n                    });\n                  } catch(err) {\n                    console.error('stars error', err);\n                  }\n\n                  busy = false;\n                }}\n              >\n                <div class=\"popup-stars-option-title\">{`+${option.stars}`}{iconsElements}</div>\n                <div class=\"popup-stars-option-subtitle\">{paymentsWrapCurrencyAmount(option.amount, option.currency)}</div>\n              </div>\n            );\n          }}</For>\n        </div>\n        <GrowHeightReveal when={!extended()} appear={false}>\n          <Button\n            class=\"btn-primary btn-transparent primary popup-stars-more\"\n            icon=\"down\"\n            text=\"ShowMoreOptions\"\n            onClick={() => setExtended((v) => !v)}\n          />\n        </GrowHeightReveal>\n      </Section>\n    );\n\n    const createLoader = (inbound?: boolean) => {\n      const middleware = this.middlewareHelper.get();\n      let offset = '', loading = false;\n      const loadMore = async() => {\n        if(loading) {\n          return;\n        }\n\n        loading = true;\n        const starsStatus = await this.managers.appPaymentsManager.getStarsTransactions(offset, inbound, this.ton);\n        if(!middleware()) return;\n\n        const promises = (starsStatus.history || []).map(this.renderTransaction);\n        const rendered = await Promise.all(promises);\n        if(!middleware()) return;\n\n        setF((value) => {\n          // value.count = starsStatus.count;\n          offset = starsStatus.next_offset;\n          if(!offset) {\n            value.loadMore = undefined;\n          }\n\n          value.rendered.push(...rendered);\n          return value;\n        });\n\n        loading = false;\n      };\n\n      const [f, setF] = createLoadableList({loadMore});\n      return f;\n    };\n\n    const lists = [undefined, true, false].map((inbound) => {\n      const list = createLoader(inbound);\n      list().loadMore();\n      return list;\n    });\n\n    const [tab, setTab] = createSignal(0);\n\n    this.scrollable.onScrolledBottom = () => {\n      const list = lists[tab()];\n      list().loadMore?.();\n    };\n\n    const middleware = this.middlewareHelper.get();\n    let subscriptionsOffset: string;\n    const loadMoreSubscriptions = async() => {\n      const starsStatus = await this.managers.appPaymentsManager.getStarsSubscriptions(subscriptionsOffset);\n      if(!middleware()) {\n        return;\n      }\n\n      const promises = (starsStatus.subscriptions || []).map(this.renderSubscription);\n      const rendered = await Promise.all(promises);\n      if(!middleware()) return;\n\n      setSubscriptionsLoader((value) => {\n        value.count += rendered.length;\n        subscriptionsOffset = starsStatus.subscriptions_next_offset;\n        if(!subscriptionsOffset) {\n          value.loadMore = undefined;\n        }\n\n        value.rendered.push(...rendered);\n        return value;\n      });\n    };\n\n    const [subscriptionsLoader, setSubscriptionsLoader] = createLoadableList({\n      loadMore: loadMoreSubscriptions\n    });\n\n    subscriptionsLoader().loadMore();\n    const subscriptionsSection = (\n      <Section class=\"popup-stars-subscriptions-section\" name=\"Stars.Subscriptions\">\n        <div>{subscriptionsLoader().rendered}</div>\n        <Show when={!!subscriptionsLoader().loadMore}>\n          <MoreButton\n            count={subscriptionsLoader().count - subscriptionsLoader().rendered.length}\n            callback={() => subscriptionsLoader().loadMore()}\n          />\n        </Show>\n      </Section>\n    );\n\n    const transactionsSection = (\n      <Section class=\"popup-stars-transactions-section\">\n        <Tabs.Simple\n          tab={tab}\n          onChange={setTab}\n          class=\"popup-stars-transactions\"\n          menu={[\n            i18n('StarsTransactionsAll'),\n            i18n('StarsTransactionsIncoming'),\n            i18n('StarsTransactionsOutgoing')\n          ]}\n          content={lists.map((list) => {\n            return <div>{list().rendered}</div>\n          })}\n        />\n      </Section>\n    );\n\n    const restSection = (\n      <>\n        {this.appConfig.stars_gifts_enabled && !this.ton && !this.purchaseBlocked && (\n          <Section>\n            <Button\n              class=\"btn-primary btn-transparent primary\"\n              text=\"TelegramStarsGift\"\n              onClick={async() => {\n                this.hide();\n                const peerId = await showContactPickerPopup();\n                PopupElement.createPopup(PopupStars, {\n                  giftPeerId: peerId,\n                  onTopup: async(stars) => {\n                    toastNew({\n                      langPackKey: 'StarsGiftSentPopupInfo',\n                      langPackArguments: [stars, await wrapPeerTitle({peerId})]\n                    });\n                  }\n                });\n              }}\n            />\n          </Section>\n        )}\n        {!!subscriptionsLoader().count && subscriptionsSection}\n        {transactionsSection}\n      </>\n    );\n\n    // Gifting stars is buying them for someone else, so it goes with the top-up\n    // options and is out when buying is blocked or this popup is already a gift.\n    const giftSection = !this.purchaseBlocked && !this.ton && !this.giftPeerId && !this.itemPrice && (\n      <Section>\n        <Row clickable={showGiftStarsPicker}>\n          <Row.Icon icon=\"gift\" />\n          <Row.Title>{i18n('TelegramStarsGift')}</Row.Title>\n        </Row>\n      </Section>\n    );\n\n    return (\n      <>\n        {image}\n        {avatar}\n        <div class=\"popup-stars-title\">{title}</div>\n        <div class=\"popup-stars-subtitle\">{subtitle}</div>\n        {firstSection}\n        {giftSection}\n        {starsNeeded() === bigInt.zero && !this.giftPeerId && restSection}\n      </>\n    );\n  }\n\n  private async construct() {\n    const [image, peerTitle, options, avatar, appConfig, _] = await Promise.all([\n      (async() => {\n        if(this.ton) {\n          const stickerDiv = document.createElement('div');\n          stickerDiv.classList.add('popup-stars-image');\n          stickerDiv.style.width = stickerDiv.style.height = '100px';\n          return wrapLocalSticker({\n            assetName: 'Diamond',\n            width: 100,\n            height: 100,\n            middleware: this.middlewareHelper.get(),\n            loop: true,\n            autoplay: true\n          }).then(({container}) => {\n            stickerDiv.append(container);\n            return stickerDiv;\n          });\n        }\n        const img = document.createElement('img');\n        img.classList.add('popup-stars-image');\n        await renderImageFromUrlPromise(img, `assets/img/${maybe2x(this.giftPeerId ? 'stars_pay' : 'stars')}.png`);\n        return img;\n      })(),\n      this.peerId || this.paymentForm?.bot_id || this.giftPeerId ? wrapPeerTitle({peerId: this.peerId || this.giftPeerId || this.paymentForm.bot_id.toPeerId(false)}) : undefined,\n      this.giftPeerId ? this.managers.appPaymentsManager.getStarsGiftOptions(this.giftPeerId.toUserId()) : this.managers.appPaymentsManager.getStarsTopupOptions(),\n      this.giftPeerId && (async() => {\n        const avatar = avatarNew({peerId: this.giftPeerId, size: 100, middleware: this.middlewareHelper.get()});\n        await avatar.readyThumbPromise;\n        avatar.node.classList.add('popup-stars-gift-avatar');\n        return avatar.node;\n      })(),\n      this.managers.apiManager.getAppConfig(),\n      this.itemPrice && prefetchStars(this.middlewareHelper.get())\n    ]);\n    this.options = options;\n    this.appConfig = appConfig;\n\n    // * stars can be unavailable for purchase at all, then only the balance and the history are left\n    this.purchaseBlocked = !this.ton && !!appConfig.stars_purchase_blocked;\n    if(this.purchaseBlocked && (this.itemPrice || this.giftPeerId)) {\n      confirmationPopup({\n        titleLangKey: 'StarsNotAvailableTitle',\n        descriptionLangKey: 'StarsNotAvailableText',\n        button: {langKey: 'OK', isCancel: true}\n      }).catch(() => {});\n      this.hide();\n      this.onCancel?.();\n      return;\n    }\n\n    // * topping up for a spend on a bot or a channel can be forbidden, then there's nothing to offer\n    if(!this.ton && this.purposePeerId && appConfig.stars_spend_topup_invoice_disabled) {\n      toastNew({langPackKey: 'PaymentInvoiceDisabledStarsText'});\n      this.hide();\n      this.onCancel?.();\n      return;\n    }\n\n    this.appendSolid(() => this._construct(image, peerTitle, avatar));\n    this.addEventListener('close', () => {\n      if(!this.toppedUp && this.onCancel) {\n        this.onCancel();\n      }\n    });\n    this.show();\n  }\n}\n","import callbackify from '@helpers/callbackify';\nimport formatNumber from '@helpers/number/formatNumber';\nimport getImageFromStrippedThumb from '@helpers/getImageFromStrippedThumb';\nimport {AvailableReaction, Document, MessagePeerReaction, PhotoSize, Reaction, ReactionCount} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport rootScope from '@lib/rootScope';\nimport SetTransition from '@components/singleTransition';\nimport StackedAvatars from '@components/stackedAvatars';\nimport wrapSticker from '@components/wrappers/sticker';\nimport wrapStickerAnimation from '@components/wrappers/stickerAnimation';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport {fastRaf} from '@helpers/schedulers';\nimport {getMiddleware, Middleware} from '@helpers/middleware';\nimport liteMode from '@helpers/liteMode';\nimport appImManager from '@lib/appImManager';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport CustomEmojiElement from '@lib/customEmoji/element';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport noop from '@helpers/noop';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport BezierEasing from '@vendor/bezierEasing';\nimport lottieLoader, {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport Scrollable from '@components/scrollable';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {savedReactionTags} from '@components/chat/reactions';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport {StarsStar} from '@components/popups/stars';\nimport {Sparkles} from '@components/sparkles';\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport getUnsafeRandomInt from '@helpers/number/getUnsafeRandomInt';\nimport {IS_MOBILE} from '@environment/userAgent';\n\nconst CLASS_NAME = 'reaction';\nconst TAG_NAME = CLASS_NAME + '-element';\n\nexport enum ReactionLayoutType {\n  Inline = 'inline',\n  Block = 'block',\n  Tag = 'tag'\n};\n\nexport const REACTIONS_SIZE: {[key in ReactionLayoutType]: number} = {\n  [ReactionLayoutType.Inline]: 14,\n  [ReactionLayoutType.Block]: 22,\n  [ReactionLayoutType.Tag]: 22\n};\n\nexport const REACTIONS_DISPLAY_COUNTER_AT: {[key in ReactionLayoutType]?: number} = {\n  [ReactionLayoutType.Inline]: 2,\n  [ReactionLayoutType.Block]: 4\n};\n\nconst defaultBezier = (val: number) => val;\ntype Position = [number, number, number];\ntype EasingFunction = typeof defaultBezier;\ntype Layer = {\n  ddd: 0 | 1,\n  ind: number,\n  ty: number,\n  nm: string,\n  parent: number,\n  refId: string,\n  sr: number,\n  ks: {\n    o: Transformation, // opacity\n    p: Transformation, // position\n    a: Transformation, // anchor\n    s: Transformation, // scale\n  },\n  ao: number,\n  w: number,\n  h: number,\n  ip: number,\n  op: number,\n  st: number,\n  bm: number\n};\ntype Transformation = {\n  a: 1,\n  k: Keyframe[]\n} | {\n  a: 0,\n  k: Position\n};\ntype Keyframe = {\n  i?: KeyframeBezier,\n  o?: Keyframe['i'],\n  t: number,\n  s: Position\n};\ntype KeyframeBezier = {\n  x: number | Position,\n  y: KeyframeBezier['x']\n};\n\nclass TransformationComputator {\n  transformation: Transformation;\n  keyframes: Keyframe[];\n\n  keyframeIndex: number;\n  keyframe: Keyframe;\n  nextKeyframe: Keyframe;\n  beziers: EasingFunction | EasingFunction[];\n\n  constructor(transformation: Transformation) {\n    this.transformation = transformation;\n    this.keyframes = this.transformation.k as Keyframe[];\n\n    this.keyframeIndex = 0;\n    this.nextKeyframe = this.keyframes[this.keyframeIndex];\n  }\n\n  private withProgress(point: number) {\n    const pointsPlayed = point - this.keyframe.t;\n    let pointsProgress = pointsPlayed / (this.nextKeyframe.t - this.keyframe.t);\n\n    const isArrayBeziers = Array.isArray(this.beziers);\n    if(!isArrayBeziers) {\n      pointsProgress = (this.beziers as EasingFunction)(pointsProgress);\n    }\n\n    return this.keyframe.s.map((value: number, index: number) => {\n      return value + (this.nextKeyframe.s[index] - value) * (\n        isArrayBeziers ? (this.beziers as EasingFunction[])[index](pointsProgress) : pointsProgress\n      );\n    }) as Position;\n  }\n\n  computeAtPoint(point: number) {\n    if(!this.nextKeyframe) {\n      return;\n    }\n\n    if(point >= this.nextKeyframe.t) {\n      this.keyframe = this.nextKeyframe;\n      this.nextKeyframe = this.keyframes[++this.keyframeIndex];\n\n      if(this.keyframe.o && this.keyframe.i) {\n        if(!Array.isArray(this.keyframe.o.x)) {\n          // @ts-ignore\n          this.beziers = BezierEasing(this.keyframe.o.x, this.keyframe.o.y, this.keyframe.i.x, this.keyframe.i.y);\n        } else if(new Set(this.keyframe.o.x).size === 1) {\n          // @ts-ignore\n          this.beziers = BezierEasing(this.keyframe.o.x[0], this.keyframe.o.y[0], this.keyframe.i.x[0], this.keyframe.i.y[0]);\n        } else {\n          this.beziers = this.keyframe.o.x.map((_, index) => {\n            // @ts-ignore\n            return BezierEasing(this.keyframe.o.x[index], this.keyframe.o.y[index], this.keyframe.i.x[index], this.keyframe.i.y[index]);\n          });\n        }\n      } else {\n        this.beziers = defaultBezier;\n      }\n\n      if(!this.nextKeyframe || point === this.nextKeyframe.t) {\n        return this.keyframe.s;\n      } else {\n        return this.withProgress(point);\n      }\n    } else if(this.keyframe) {\n      return this.withProgress(point);\n    } else { // ! test\n      return this.nextKeyframe.s;\n    }\n  }\n}\n\nfunction computeLayerTransformations(layer: Layer) {\n  const ks = layer.ks;\n  const anchor = ks.a;\n  const op = layer.op;\n  const layerTransformations: ComputedFrameTransformations[] = new Array(op - 1);\n  const opacityComputator = ks.o && new TransformationComputator(ks.o);\n  const translationComputator = ks.p && new TransformationComputator(ks.p);\n  const scaleComputator = ks.s && new TransformationComputator(ks.s);\n  for(let point = 0; point < op; ++point) {\n    if(point < layer.ip) {\n      continue;\n    }\n\n    const prevTransformations = layerTransformations[point - 1] || {};\n    const transformations: ComputedFrameTransformations = {};\n\n    const translation = translationComputator.computeAtPoint(point);\n    if(translation) {\n      transformations.translation = translation;\n\n      if(anchor) {\n        transformations.anchor = anchor.k as Position;\n        // transformations.anchor = translation.map((value, index) => {\n        //   return anchor.k[index] as number + value;\n        // }) as Position;\n      }\n    } else {\n      transformations.translation = prevTransformations.translation;\n      transformations.anchor = prevTransformations.anchor;\n    }\n\n    const scale = scaleComputator.computeAtPoint(point);\n    if(scale) {\n      transformations.scale = scale;\n    } else {\n      transformations.scale = prevTransformations.scale;\n    }\n\n    const opacity = opacityComputator.computeAtPoint(point);\n    if(opacity) {\n      transformations.opacity = opacity;\n    } else {\n      transformations.opacity = prevTransformations.opacity;\n    }\n\n    if(translation || scale || opacity) {\n      layerTransformations[point] = transformations;\n    }\n  }\n\n  return layerTransformations;\n}\n\ntype ComputedFrameTransformations = {\n  opacity?: Position,\n  translation?: Position,\n  anchor?: Position,\n  scale?: Position\n};\n\nlet reactionGenericPromise: ReturnType<typeof loadReactionGeneric>;\nfunction loadReactionGeneric(): Promise<{layersPositions: ComputedFrameTransformations[][], op: number}> {\n  if(reactionGenericPromise) {\n    return reactionGenericPromise;\n  }\n\n  const url = lottieLoader.makeAssetUrl('ReactionGeneric');\n  const promise = reactionGenericPromise = lottieLoader.loadAnimationDataFromURL(url, 'json').then((animationData) => {\n    const placeholderLayers: Layer[] = animationData.layers.filter((layer: any) => layer.nm.startsWith('placeholder_'))/* .slice(0, 1) */;\n    const layersPositions: ComputedFrameTransformations[][] = [];\n    for(const layer of placeholderLayers) {\n      layersPositions.push(computeLayerTransformations(layer));\n    }\n\n    return {layersPositions, op: animationData.op};\n  });\n  promise.catch(() => {\n    if(reactionGenericPromise === promise) {\n      reactionGenericPromise = undefined;\n    }\n  });\n\n  return promise;\n}\n\n// * background warm-up downloads are sequential so the big effect files never\n// * starve the interactive fetches (the reaction icon thumb, the flight media)\nlet warmUpChain: Promise<any> = Promise.resolve();\nfunction warmUpDownload(doc: Document.document) {\n  const cacheContext = apiManagerProxy.getCacheContext(doc);\n  if(cacheContext.downloaded || cacheContext.url) {\n    return;\n  }\n\n  warmUpChain = warmUpChain.then(() => appDownloadManager.downloadMediaURL({media: doc})).catch(noop);\n}\n\n// * warm up the activation effect while the user is aiming at the reaction,\n// * so the click fires the native effect instead of the generic fallback\nexport function warmUpReactionEffect(availableReaction: AvailableReaction) {\n  if(!liteMode.isAvailable('effects_reactions')) {\n    return;\n  }\n\n  const docs = [\n    availableReaction.around_animation,\n    availableReaction.center_icon\n  ].filter(Boolean) as Document.document[];\n  docs.forEach(warmUpDownload);\n}\n\nconst GENERIC_EFFECT_SIZE = 100;\nconst GENERIC_EFFECT_STICKER_SIZE = 26;\nconst FLIGHT_SOURCE_SIZE = 100;\n\n// * resolve a document to render the reaction's first frame from. The user\n// * clicked an already-rendered emoji, so SOMETHING is cached - but for a native\n// * reaction the menu/picker rendered the appear/select animation, not the\n// * canonical center_icon, so naively picking center_icon can hit an uncached doc\n// * and the flight gets no source in time. Prefer center_icon (cleanest still),\n// * but fall back to whichever of the reaction's docs is already cached so the\n// * render is instant; a custom emoji's own doc is always the rendered (cached) one\nfunction getReactionStickerDoc(reaction: Reaction, managers: AppManagers) {\n  if(reaction._ === 'reactionEmoji') {\n    return callbackify(apiManagerProxy.getReaction(reaction.emoticon), (availableReaction) => {\n      if(!availableReaction) {\n        return;\n      }\n\n      const candidates = [\n        availableReaction.center_icon,\n        availableReaction.static_icon,\n        availableReaction.select_animation,\n        availableReaction.appear_animation\n      ].filter(Boolean) as Document.document[];\n      const cached = candidates.find((doc) => {\n        const cacheContext = apiManagerProxy.getCacheContext(doc);\n        return cacheContext.downloaded || cacheContext.url;\n      });\n      return cached || candidates[0];\n    });\n  } else if(reaction._ === 'reactionCustomEmoji') {\n    return managers.appEmojiManager.getCustomEmojiDocument(reaction.document_id);\n  }\n}\n\nfunction mediaToCanvas(media: HTMLImageElement | HTMLCanvasElement | HTMLVideoElement) {\n  let width: number, height: number;\n  if(media instanceof HTMLVideoElement) {\n    width = media.videoWidth;\n    height = media.videoHeight;\n  } else if(media instanceof HTMLImageElement) {\n    width = media.naturalWidth;\n    height = media.naturalHeight;\n  } else {\n    width = media.width;\n    height = media.height;\n  }\n\n  if(!width || !height) {\n    throw new Error('rendered media has no size');\n  }\n\n  const canvas = document.createElement('canvas');\n  canvas.width = width;\n  canvas.height = height;\n  canvas.getContext('2d').drawImage(media, 0, 0);\n  return normalizeReactionSource(canvas);\n}\n\nconst REACTION_SOURCE_FILL = .9;\nconst REACTION_SOURCE_ALPHA_THRESHOLD = 8;\n\nfunction normalizeReactionSource(canvas: HTMLCanvasElement) {\n  const {width, height} = canvas;\n  const data = canvas.getContext('2d').getImageData(0, 0, width, height).data;\n  let left = width, top = height, right = -1, bottom = -1;\n  for(let y = 0; y < height; ++y) {\n    for(let x = 0; x < width; ++x) {\n      if(data[(y * width + x) * 4 + 3] < REACTION_SOURCE_ALPHA_THRESHOLD) {\n        continue;\n      }\n\n      left = Math.min(left, x);\n      top = Math.min(top, y);\n      right = Math.max(right, x);\n      bottom = Math.max(bottom, y);\n    }\n  }\n\n  if(right < left || bottom < top) {\n    throw new Error('rendered media has no visible pixels');\n  }\n\n  const inkWidth = right - left + 1;\n  const inkHeight = bottom - top + 1;\n  // Keep a small breathing room, but never make an already full-size source\n  // smaller. A square output also prevents non-square emoji from stretching\n  // when the placeholder fills .reaction-sticker.\n  const size = Math.min(\n    Math.max(width, height),\n    Math.ceil(Math.max(inkWidth, inkHeight) / REACTION_SOURCE_FILL)\n  );\n  const normalized = document.createElement('canvas');\n  normalized.width = normalized.height = size;\n  normalized.getContext('2d').drawImage(\n    canvas,\n    left,\n    top,\n    inkWidth,\n    inkHeight,\n    Math.round((size - inkWidth) / 2),\n    Math.round((size - inkHeight) / 2),\n    inkWidth,\n    inkHeight\n  );\n  return normalized;\n}\n\n// * snapshot the clicked element's CURRENT pixels synchronously - an INSTANT\n// * flight source so the generic copies fly from frame 0 even before the clean\n// * first-frame render is ready (a cold lottie parse can take ~1s, during which\n// * the flight would otherwise run to its end empty = \"no flying emoji\"). The\n// * first frame upgrades this as soon as it resolves\nfunction captureClickedSnapshot(container: HTMLElement): HTMLCanvasElement {\n  if(!container) {\n    return;\n  }\n\n  try {\n    let snapshot: HTMLCanvasElement;\n    const media = container instanceof HTMLImageElement || container instanceof HTMLCanvasElement || container instanceof HTMLVideoElement ?\n      container :\n      Array.from(\n        container.querySelectorAll<HTMLCanvasElement | HTMLImageElement | HTMLVideoElement>('canvas, img.media-sticker, video.media-sticker, img.emoji')\n      ).find((media) => !media.closest('.hide'));\n\n    if(media) {\n      let width: number, height: number;\n      if(media instanceof HTMLVideoElement) {\n        width = media.videoWidth;\n        height = media.videoHeight;\n      } else if(media instanceof HTMLImageElement) {\n        width = media.naturalWidth;\n        height = media.naturalHeight;\n      } else {\n        width = media.width;\n        height = media.height;\n      }\n\n      if(!width || !height) {\n        return;\n      }\n\n      snapshot = document.createElement('canvas');\n      snapshot.width = width;\n      snapshot.height = height;\n      snapshot.getContext('2d').drawImage(media, 0, 0);\n    } else {\n      // * a custom emoji is painted on the shared renderer canvas - copy its region\n      const customEmoji = container instanceof CustomEmojiElement ?\n        container :\n        container.querySelector<CustomEmojiElement>('custom-emoji-element');\n      const rendererCanvas = customEmoji?.renderer?.canvas;\n      if(!rendererCanvas) {\n        return;\n      }\n\n      const canvasRect = rendererCanvas.getBoundingClientRect();\n      const rect = customEmoji.getBoundingClientRect();\n      if(!rect.width || !rect.height || !canvasRect.width || !canvasRect.height) {\n        return;\n      }\n\n      const scaleX = rendererCanvas.width / canvasRect.width;\n      const scaleY = rendererCanvas.height / canvasRect.height;\n      snapshot = document.createElement('canvas');\n      snapshot.width = Math.max(1, Math.round(rect.width * scaleX));\n      snapshot.height = Math.max(1, Math.round(rect.height * scaleY));\n      snapshot.getContext('2d').drawImage(\n        rendererCanvas,\n        (rect.left - canvasRect.left) * scaleX,\n        (rect.top - canvasRect.top) * scaleY,\n        snapshot.width,\n        snapshot.height,\n        0,\n        0,\n        snapshot.width,\n        snapshot.height\n      );\n    }\n\n    // * crop the transparent document/menu padding. Both the optimistic\n    // * .reaction-sticker placeholder and the generic flight draw the whole\n    // * source canvas, so keeping those margins makes the emoji look too small\n    return normalizeReactionSource(snapshot);\n  } catch{\n    return;\n  }\n}\n\n// * render the reaction's emoji on its own and freeze it at the FIRST frame - a\n// * clean, deterministic source for the generic flight copies and the\n// * .reaction-sticker placeholder; unlike a live snapshot it never depends on\n// * whatever animation frame the clicked element happened to be on. Rendered\n// * from the cached FULL document (play:false → frame 0), NOT static:true - the\n// * warm-up downloads the full doc (so it's the cached one), while static would\n// * fetch a separate thumb PhotoSize nobody warmed; sampling the player canvas\n// * is also decode-safe, unlike reading an <img> right after its load event\nfunction renderReactionFirstFrame(reaction: Reaction, managers: AppManagers): Promise<HTMLCanvasElement> {\n  const middlewareHelper = getMiddleware();\n  return Promise.resolve(getReactionStickerDoc(reaction, managers)).then((doc) => {\n    if(!doc) {\n      throw new Error('no sticker document for the reaction');\n    }\n\n    const div = document.createElement('div');\n    return wrapSticker({\n      div,\n      doc,\n      width: FLIGHT_SOURCE_SIZE,\n      height: FLIGHT_SOURCE_SIZE,\n      play: false,\n      loop: false,\n      withThumb: false,\n      needFadeIn: false,\n      group: 'none',\n      managers,\n      middleware: middlewareHelper.get(),\n      noOffscreen: true\n    }).then(({render}) => render).then((result) => new Promise<HTMLCanvasElement>((resolve, reject) => {\n      const snapshot = (source: HTMLImageElement | HTMLCanvasElement | HTMLVideoElement) => {\n        try {\n          const canvas = mediaToCanvas(source);\n          resolve(canvas);\n        } catch(err) {\n          reject(err);\n        }\n      };\n\n      // * a lottie/webm renders into a player canvas (frame 0); a static sticker\n      // * resolves to its loaded [img]\n      if(result instanceof LottiePlayer) {\n        let settled = false;\n        const cleanup = () => {\n          result.removeEventListener('firstFrame', onFirstFrame);\n          result.removeEventListener('error', onError);\n          result.removeEventListener('destroy', onDestroy);\n        };\n        const onFirstFrame = () => {\n          if(settled) {\n            return;\n          }\n\n          settled = true;\n          cleanup();\n          snapshot(result.canvas[0]);\n        };\n        const onError = (error: unknown) => {\n          if(settled) {\n            return;\n          }\n\n          settled = true;\n          cleanup();\n          reject(error);\n        };\n        const onDestroy = () => onError(result.error || new Error('reaction first-frame player destroyed'));\n\n        if(result.hasFailed) {\n          onError(result.error);\n        } else if(result.hasRenderedFirstFrame) {\n          onFirstFrame();\n        } else {\n          result.addEventListener('firstFrame', onFirstFrame);\n          result.addEventListener('error', onError);\n          result.addEventListener('destroy', onDestroy);\n          result.loadPromise.catch(onError);\n        }\n      } else {\n        snapshot((Array.isArray(result) ? result[0] : result) as any || div.querySelector('img, canvas'));\n      }\n    }));\n  }).finally(() => middlewareHelper.destroy());\n}\n\n// * the user clicks an already rendered emoji. We keep TWO sources: an INSTANT\n// * synchronous snapshot of the clicked element (so the flight copies fly from\n// * frame 0 right away) and a clean first-frame render that upgrades it once\n// * ready (a cold lottie parse can be ~1s - too late for the flight on its own)\ntype StashedFlightSource = {snapshot: HTMLCanvasElement, firstFrame: Promise<HTMLCanvasElement>};\nlet stashedFlightSource: StashedFlightSource & {reaction: Reaction, time: number};\nexport function stashFlightSource(reaction: Reaction, container?: HTMLElement, managers: AppManagers = rootScope.managers) {\n  if(\n    !liteMode.isAvailable('effects_reactions') ||\n    !reaction ||\n    reaction._ === 'reactionEmpty' ||\n    reaction._ === 'reactionPaid'\n  ) {\n    return;\n  }\n\n  const snapshot = captureClickedSnapshot(container);\n  const firstFrame = renderReactionFirstFrame(reaction, managers);\n  firstFrame.catch(noop);\n  stashedFlightSource = {reaction, snapshot, firstFrame, time: Date.now()};\n}\n\n// * peeked, not consumed: both the activation flight and the reaction element\n// * placeholder use it; the TTL is what retires it\nfunction peekStashedFlightSource(reaction: Reaction): StashedFlightSource | undefined {\n  const stashed = stashedFlightSource;\n  if(!stashed) {\n    return;\n  }\n\n  if((Date.now() - stashed.time) > 5e3) {\n    stashedFlightSource = undefined;\n    return;\n  }\n\n  // * compare only the identity fields - the menu and the message reaction\n  // * objects come from different sources and can differ in auxiliary keys\n  const [a, b] = [stashed.reaction, reaction];\n  const same = a._ === b._ && (\n    (a._ === 'reactionEmoji' && a.emoticon === (b as Reaction.reactionEmoji).emoticon) ||\n    (a._ === 'reactionCustomEmoji' && '' + a.document_id === '' + (b as Reaction.reactionCustomEmoji).document_id)\n  );\n  if(!same) {\n    return;\n  }\n\n  return {snapshot: stashed.snapshot, firstFrame: stashed.firstFrame};\n}\n\n// * tab-side cache of the next generic animation to play: keeps the worker\n// * round-trip off the critical path of an effect activation\nlet cachedGenericEffect: Document.document;\nfunction getGenericEffect(managers: AppManagers): MaybePromise<Document.document> {\n  const cached = cachedGenericEffect;\n  const promise = Promise.resolve(managers.appReactionsManager.getRandomGenericAnimation()).then((doc) => {\n    return cachedGenericEffect = doc || cached;\n  }, () => cached);\n\n  return cached || promise;\n}\n\ntype PreparedGenericEffect = {\n  doc: Document.document,\n  around: LottiePlayer,\n  flight: LottiePlayer\n};\n\n// * a generic effect prepared in advance: by the time it has to be played its\n// * players are already parsed and have their first frame rendered, so the\n// * activation starts instantly; once taken, the next one gets prepared\nlet preparedGenericEffect: PreparedGenericEffect;\nlet preparingGenericEffect = false;\nfunction prepareGenericEffect(managers: AppManagers = rootScope.managers) {\n  if(preparingGenericEffect || preparedGenericEffect || !liteMode.isAvailable('effects_reactions')) {\n    return;\n  }\n\n  preparingGenericEffect = true;\n  Promise.resolve(getGenericEffect(managers)).then(async(doc) => {\n    if(!doc) {\n      return;\n    }\n\n    const [blob] = await Promise.all([\n      appDownloadManager.downloadMedia({media: doc}),\n      // * marks the cache context so the doc is considered loaded everywhere\n      appDownloadManager.downloadMediaURL({media: doc}).then(noop, noop)\n    ]);\n\n    const players: LottiePlayer[] = [];\n    let cancelled = false;\n    const makePlayer = async(width: number, loop: boolean) => {\n      const player = await lottieLoader.loadAnimationWorker({\n        container: document.createElement('div'),\n        animationData: blob,\n        autoplay: false,\n        loop,\n        width,\n        height: width,\n        name: 'doc' + doc.id,\n        skipRatio: 1,\n        group: 'none',\n        noOffscreen: true\n      });\n      if(cancelled) {\n        player.remove();\n        throw new Error('generic reaction effect preparation cancelled');\n      }\n\n      players.push(player);\n      await lottieLoader.waitForFirstFrame(player);\n      if(cancelled || !player.hasRenderedFirstFrame) {\n        player.remove();\n        throw new Error('generic reaction effect did not render its first frame');\n      }\n\n      return player;\n    };\n\n    try {\n      const [around, flight] = await Promise.all([\n        makePlayer(GENERIC_EFFECT_SIZE, false),\n        makePlayer(GENERIC_EFFECT_STICKER_SIZE, true)\n      ]);\n      preparedGenericEffect = {doc, around, flight};\n    } catch(err) {\n      cancelled = true;\n      players.forEach((player) => player.remove());\n      throw err;\n    }\n  }).catch(noop).finally(() => {\n    preparingGenericEffect = false;\n  });\n}\n\nfunction takePreparedGenericEffect(sizes: {genericEffect: number, genericEffectSize: number}) {\n  const prepared = preparedGenericEffect;\n  if(!prepared) {\n    prepareGenericEffect();\n    return;\n  }\n\n  if(sizes.genericEffect !== GENERIC_EFFECT_STICKER_SIZE || sizes.genericEffectSize !== GENERIC_EFFECT_SIZE) {\n    return;\n  }\n\n  preparedGenericEffect = undefined;\n  prepareGenericEffect();\n  return prepared;\n}\n\nexport function warmUpGenericEffectAssets(managers: AppManagers = rootScope.managers) {\n  if(!liteMode.isAvailable('effects_reactions')) {\n    return;\n  }\n\n  loadReactionGeneric().catch(noop);\n  prepareGenericEffect(managers);\n}\n\nrootScope.addEventListener('user_auth', () => {\n  setTimeout(() => warmUpGenericEffectAssets(), 5e3);\n});\n\nexport default class ReactionElement extends HTMLElement {\n  private type: ReactionLayoutType;\n  private counter: HTMLElement;\n  public stickerContainer: HTMLElement;\n  private stackedAvatars: StackedAvatars;\n  private canRenderAvatars: boolean;\n  private _reactionCount: ReactionCount;\n  public wrapStickerPromise: Awaited<ReturnType<typeof wrapSticker>>['render'];\n  public managers: AppManagers;\n  public middleware: Middleware;\n  private customEmojiElement: CustomEmojiElement;\n  public hasAroundAnimation: Promise<void>;\n  public isUnread: boolean;\n  private hasTitle: boolean;\n  private paidReactionCounter: AnimatedCounter;\n  private stickerPlaceholderCleanup: () => void;\n  private stickerPlaceholderPending: boolean;\n\n  constructor() {\n    super();\n    this.classList.add(CLASS_NAME);\n    this.managers = rootScope.managers;\n  }\n\n  public get reactionCount() {\n    return this._reactionCount;\n  }\n\n  public set reactionCount(reactionCount: ReactionCount) {\n    this._reactionCount = reactionCount;\n  }\n\n  public get count() {\n    return this.reactionCount.count;\n  }\n\n  public init(type: ReactionLayoutType, middleware: Middleware) {\n    this.type = type;\n    this.classList.add(CLASS_NAME + '-' + type);\n    this.classList.toggle(CLASS_NAME + '-like-block', type === ReactionLayoutType.Block || type === ReactionLayoutType.Tag);\n    this.middleware = middleware;\n\n    if(type === ReactionLayoutType.Tag) {\n      // this.insertAdjacentHTML('beforeend', `\n      //   <svg class=\"reaction-tag-svg\" width=\"43\" height=\"30\" viewBox=\"0 0 43 30\" xmlns=\"http://www.w3.org/2000/svg\">\n      //     <path class=\"reaction-tag-svg-path\" d=\"M40.8317 12.0432L34.9967 4.08636C33.1129 1.51761 30.1181 0 26.9326 0H7C3.13401 0 0 3.13401 0 7V23C0 26.866 3.13401 30 7 30H26.9326C30.1181 30 33.1129 28.4824 34.9967 25.9136L40.8317 17.9568C42.1223 16.1969 42.1223 13.8031 40.8317 12.0432Z\" />\n      //     <circle class=\"reaction-tag-svg-circle\" cx=\"34\" cy=\"15\" r=\"3\" />\n      //   </svg>\n      // `);\n      this.insertAdjacentHTML('beforeend', `\n        <div class=\"reaction-tag-background\"></div>\n        <svg class=\"reaction-tag-svg\" width=\"43\" height=\"30\" viewBox=\"0 0 43 30\" xmlns=\"http://www.w3.org/2000/svg\">\n          <path class=\"reaction-tag-svg-path\" d=\"M40.8317 12.0432L34.9967 4.08636C33.1129 1.51761 30.1181 0 26.9326 0H7C3.13401 0 0 3.13401 0 7V23C0 26.866 3.13401 30 7 30H26.9326C30.1181 30 33.1129 28.4824 34.9967 25.9136L40.8317 17.9568C42.1223 16.1969 42.1223 13.8031 40.8317 12.0432Z\" />\n        </svg>\n        <div class=\"reaction-tag-dot\"></div>\n      `);\n    }\n  }\n\n  public setCanRenderAvatars(canRenderAvatars: boolean) {\n    this.canRenderAvatars = canRenderAvatars;\n  }\n\n  public render(doNotRenderSticker?: boolean) {\n    const hadStickerContainer = !!this.stickerContainer;\n    if(!hadStickerContainer) {\n      this.stickerContainer = document.createElement('div');\n      this.stickerContainer.classList.add(CLASS_NAME + '-sticker');\n      this.append(this.stickerContainer);\n    }\n\n    if(!doNotRenderSticker) {\n      this.renderStickerPlaceholder();\n    }\n\n    if(hadStickerContainer) {\n      return this.customEmojiElement;\n    }\n\n    const reactionCount = this.reactionCount;\n    if(doNotRenderSticker || hadStickerContainer) {\n      return;\n    }\n\n    const reaction = reactionCount.reaction;\n    if(reaction._ === 'reactionEmoji') {\n      const availableReaction = apiManagerProxy.getReaction(reaction.emoticon);\n      return callbackify(availableReaction, (availableReaction) => {\n        if(!availableReaction.center_icon) {\n          this.stickerContainer.classList.add('is-static');\n        } else {\n          this.stickerContainer.classList.add('is-regular');\n        }\n\n        if(availableReaction.pFlags.inactive) {\n          this.classList.add('is-inactive');\n        }\n\n        const doc = availableReaction.center_icon ?? availableReaction.static_icon;\n        this.renderDoc(doc);\n\n        // customEmojiElement.static = true;\n        // customEmojiElement.docId = doc.id;\n        // return customEmojiElement;\n      });\n    } else if(reaction._ === 'reactionCustomEmoji') {\n      this.stickerContainer.classList.add('is-custom');\n      // const wrapped = wrapCustomEmoji({\n      //   docIds: [reaction.document_id],\n      //   customEmojiSize: makeMediaSize(REACTION_BLOCK_SIZE, REACTION_BLOCK_SIZE)\n      // });\n\n      // this.stickerContainer.append(wrapped);\n\n      if(!this.customEmojiElement) {\n        this.customEmojiElement = CustomEmojiElement.create();\n        const wrapPromise = this.wrapStickerPromise = this.customEmojiElement.readyPromise = deferredPromise();\n        this.wrapStickerPromise.finally(() => {\n          if(this.wrapStickerPromise === wrapPromise) {\n            this.wrapStickerPromise = undefined;\n          }\n        }).catch(noop);\n        this.stickerContainer.append(this.customEmojiElement);\n        // * the renderer paints outside of the container - the placeholder\n        // * has to be retired by the ready signal, not by the observer\n        wrapPromise.then(\n          () => this.maybeRemoveStickerPlaceholder(),\n          noop\n        );\n      }\n\n      this.customEmojiElement.docId = reaction.document_id;\n      return this.customEmojiElement;\n    } else if(reaction._ === 'reactionPaid') {\n      this.classList.add('is-paid');\n      if(!IS_MOBILE) this.append(Sparkles({mode: 'button', isDiv: true}));\n      this.stickerContainer.append(StarsStar() as HTMLElement);\n    }\n  }\n\n  public setPaidReactionCounter(count: number) {\n    if(!this.paidReactionCounter) {\n      this.paidReactionCounter = new AnimatedCounter({\n        reverse: false,\n        prefix: '+',\n        calculateWidth: true\n        // calculateWidth: (text) => {\n        //   return getTextWidth(text, `400 24 ${customProperties.getProperty('font-rounded')}`) * 1.5;\n        // }\n      });\n      this.paidReactionCounter.container.classList.add('reaction-paid-counter');\n      this.append(this.paidReactionCounter.container);\n      this.paidReactionCounter.setCount(count, true);\n    } else {\n      this.paidReactionCounter.setCount(count);\n    }\n  }\n\n  public destroyPaidReactionCounter() {\n    if(this.paidReactionCounter) {\n      const {container} = this.paidReactionCounter;\n      this.paidReactionCounter = undefined;\n      setTimeout(() => {\n        container.remove();\n      }, 300);\n    }\n  }\n\n  private renderDoc(doc: Document.document) {\n    const size = REACTIONS_SIZE[this.type];\n    const wrapPromise = this.wrapStickerPromise = wrapSticker({\n      div: this.stickerContainer,\n      doc,\n      width: size,\n      height: size,\n      static: true,\n      managers: this.managers,\n      middleware: this.middleware,\n      needFadeIn: false\n    }).then(({render}) => render).finally(() => {\n      if(this.wrapStickerPromise === wrapPromise) {\n        this.wrapStickerPromise = undefined;\n      }\n    });\n  }\n\n  // * the sticker may take a while to download - show the snapshot of what\n  // * the user has clicked in the panel and remove it ONLY when the real\n  // * media is actually in place (render promises can settle early, e.g.\n  // * when the optimistic element gets replaced by the server echo)\n  private renderStickerPlaceholder() {\n    const reaction = this.reactionCount?.reaction;\n    if(this.stickerPlaceholderCleanup || this.stickerPlaceholderPending || !this.stickerContainer || !reaction) {\n      return;\n    }\n\n    if(this.hasRealStickerMedia()) {\n      return;\n    }\n\n    const stash = peekStashedFlightSource(reaction);\n    if(!stash) {\n      return;\n    }\n\n    let placeholder: HTMLCanvasElement;\n    const mount = (source: HTMLCanvasElement) => {\n      if(!source || !this.middleware() || this.stickerPlaceholderCleanup || !this.stickerContainer || this.hasRealStickerMedia()) {\n        return;\n      }\n\n      placeholder = document.createElement('canvas');\n      placeholder.width = source.width;\n      placeholder.height = source.height;\n      placeholder.getContext('2d').drawImage(source, 0, 0);\n      placeholder.classList.add(CLASS_NAME + '-sticker-placeholder');\n      placeholder.style.cssText = 'position:absolute;left:0;top:0;width:100%;height:100%;object-fit:contain;';\n      const prevPosition = this.stickerContainer.style.position;\n      this.stickerContainer.style.position = 'relative';\n      this.stickerContainer.append(placeholder);\n\n      const observer = new MutationObserver(() => this.maybeRemoveStickerPlaceholder());\n      observer.observe(this.stickerContainer, {childList: true, subtree: true});\n\n      const cleanup = () => {\n        observer.disconnect();\n        placeholder.remove();\n        // * restore the inline position we overrode (don't leave .reaction-sticker\n        // * permanently position:relative after the placeholder is gone)\n        this.stickerContainer.style.position = prevPosition;\n        if(this.stickerPlaceholderCleanup === cleanup) {\n          this.stickerPlaceholderCleanup = undefined;\n        }\n      };\n\n      this.stickerPlaceholderCleanup = cleanup;\n      this.middleware.onDestroy(cleanup);\n\n      // * a custom emoji paints on the external shared renderer canvas, so the\n      // * MutationObserver never fires for it - retire the placeholder when the\n      // * icon's own render settles (also covers a late mount)\n      this.wrapStickerPromise?.finally(() => this.maybeRemoveStickerPlaceholder()).catch(noop);\n    };\n\n    // * INSTANT: mount the clicked-element snapshot so .reaction-sticker fills now\n    mount(stash.snapshot);\n\n    // * UPGRADE: swap in the clean first frame (or mount it if there was no\n    // * snapshot) once rendered, unless the real media has already arrived\n    this.stickerPlaceholderPending = !placeholder;\n    stash.firstFrame.then((firstFrame) => {\n      this.stickerPlaceholderPending = false;\n      if(placeholder?.isConnected && !this.hasRealStickerMedia()) {\n        const context = placeholder.getContext('2d');\n        context.clearRect(0, 0, placeholder.width, placeholder.height);\n        context.drawImage(firstFrame, 0, 0, placeholder.width, placeholder.height);\n      } else if(!placeholder) {\n        mount(firstFrame);\n      }\n    }, () => {\n      this.stickerPlaceholderPending = false;\n    });\n  }\n\n  private hasRealStickerMedia() {\n    // * the custom emoji is painted on the shared renderer canvas, its\n    // * readiness is signalled by the resolved (and cleared) readyPromise\n    if(this.customEmojiElement) {\n      return !this.wrapStickerPromise;\n    }\n\n    return !!Array.from(\n      this.stickerContainer.querySelectorAll<HTMLImageElement | HTMLVideoElement>('img.media-sticker, video.media-sticker')\n    ).find((media) => !(media instanceof HTMLImageElement) || (media.complete && media.naturalWidth > 0));\n  }\n\n  private maybeRemoveStickerPlaceholder() {\n    if(!this.stickerPlaceholderCleanup || !this.hasRealStickerMedia()) {\n      return;\n    }\n\n    this.stickerPlaceholderCleanup();\n  }\n\n  public findTitle() {\n    let title: string;\n    if(this.type === ReactionLayoutType.Tag) {\n      const tag = savedReactionTags.find((tag) => reactionsEqual(tag.reaction, this.reactionCount.reaction));\n      title = tag?.title;\n    }\n\n    return title;\n  }\n\n  public renderCounter(force?: boolean, title: string | HTMLElement = this.findTitle()) {\n    const displayOn = REACTIONS_DISPLAY_COUNTER_AT[this.type];\n    if(displayOn === undefined && !force && !title && !this.hasTitle) return;\n    const reactionCount = this.reactionCount;\n\n    // Empty paid (star) reaction button — show just the star, never a \"0\" count.\n    if(reactionCount.reaction._ === 'reactionPaid' && !reactionCount.count) {\n      if(this.counter?.parentElement) {\n        this.counter.remove();\n        this.counter = undefined;\n      }\n      this.hasTitle = false;\n      return;\n    }\n\n    let setTitle = false;\n    if(force || title || reactionCount.count >= displayOn || (this.type === ReactionLayoutType.Block && !this.canRenderAvatars)) {\n      if(!this.counter) {\n        this.counter = document.createElement(this.type === ReactionLayoutType.Inline ? 'i' : 'span');\n        this.counter.classList.add(CLASS_NAME + '-counter');\n      }\n\n      const formatted = formatNumber(reactionCount.count);\n      if(title) {\n        const span = document.createElement('span');\n        span.classList.add(CLASS_NAME + '-counter-title');\n        span.append(typeof(title) === 'string' ? wrapEmojiText(title) : title);\n        this.counter.replaceChildren(span);\n        setTitle = true;\n        if(force) {\n          this.counter.append(' ', formatted);\n        }\n      } else if(this.counter.textContent !== formatted) {\n        this.counter.textContent = formatted;\n      }\n\n      if(!this.counter.parentElement) {\n        this.append(this.counter);\n      }\n    } else if(this.counter?.parentElement) {\n      this.counter.remove();\n      this.counter = undefined;\n    }\n\n    this.hasTitle = setTitle;\n  }\n\n  public renderAvatars(recentReactions: MessagePeerReaction[]) {\n    if(this.type !== ReactionLayoutType.Block) {\n      return;\n    }\n\n    if(this.reactionCount.count >= REACTIONS_DISPLAY_COUNTER_AT[this.type] || !this.canRenderAvatars) {\n      if(this.stackedAvatars) {\n        this.stackedAvatars.container.remove();\n        this.stackedAvatars = undefined;\n      }\n\n      return;\n    }\n\n    if(!this.stackedAvatars) {\n      this.stackedAvatars = new StackedAvatars({\n        avatarSize: 24,\n        middleware: this.middleware\n      });\n\n      this.append(this.stackedAvatars.container);\n    }\n\n    this.stackedAvatars.render(recentReactions.map((reaction) => getPeerId(reaction.peer_id)));\n  }\n\n  public setIsChosen(isChosen = this.reactionCount.chosen_order !== undefined) {\n    if(this.type === ReactionLayoutType.Inline) return;\n    const wasChosen = this.classList.contains('is-chosen') && !this.classList.contains('backwards');\n    if(wasChosen !== isChosen) {\n      SetTransition({\n        element: this,\n        className: 'is-chosen',\n        forwards: isChosen,\n        duration: this.isConnected ? 300 : 0\n      });\n    }\n  }\n\n  public fireAroundAnimation(waitPromise?: Promise<any>) {\n    let add = 0;\n    if(this.type === ReactionLayoutType.Inline) {\n      add = 14;\n    } else if(this.type === ReactionLayoutType.Block || this.type === ReactionLayoutType.Tag) {\n      add = 18;\n    }\n\n    return ReactionElement?.fireAroundAnimation({\n      waitPromise,\n      cache: this,\n      middleware: this.middleware,\n      reaction: this.reactionCount?.reaction,\n      stickerContainer: this.stickerContainer,\n      managers: this.managers,\n      sizes: {\n        genericEffect: GENERIC_EFFECT_STICKER_SIZE,\n        genericEffectSize: GENERIC_EFFECT_SIZE,\n        size: REACTIONS_SIZE[this.type] + add,\n        effectSize: 80\n      },\n      scrollable: appImManager.chat.bubbles.scrollable\n    });\n  }\n\n  public static fireAroundAnimation(options: {\n    waitPromise?: Promise<any>\n    cache?: {\n      hasAroundAnimation: ReactionElement['hasAroundAnimation'],\n      wrapStickerPromise?: ReactionElement['wrapStickerPromise']\n    },\n    reaction: Reaction,\n    managers?: AppManagers,\n    middleware: Middleware,\n    stickerContainer: HTMLElement,\n    sizes: {\n      genericEffect: number,\n      genericEffectSize: number,\n      size: number,\n      effectSize: number\n    },\n    textColor?: string,\n    scrollable?: Scrollable\n  }) {\n    if(options.cache.hasAroundAnimation || !liteMode.isAvailable('effects_reactions')) {\n      return;\n    }\n\n    options.managers ??= rootScope.managers;\n\n    const reaction = options.reaction;\n    if(reaction._ === 'reactionEmpty') return;\n\n    const onAvailableReaction = ({\n      availableReaction,\n      genericEffect,\n      sticker,\n      onlyAround,\n      assetName,\n      staticSticker,\n      prepared\n    }: {\n      availableReaction?: AvailableReaction,\n      genericEffect?: Document.document,\n      sticker?: Document.document,\n      onlyAround?: boolean\n      assetName?: LottieAssetName,\n      staticSticker?: boolean,\n      prepared?: PreparedGenericEffect\n    }) => {\n      const size = genericEffect ? options.sizes.genericEffect : options.sizes.size;\n      const div = genericEffect ? undefined : document.createElement('div');\n      div && div.classList.add(CLASS_NAME + '-sticker-activate');\n\n      const genericEffectSize = options.sizes.genericEffectSize;\n      // * every generic flight is masked: the copies are drawn from whatever\n      // * source is available right now (live media, a stripped thumb, and\n      // * finally the real render once it's loaded) - like the official\n      // * clients, the effect never waits for the sticker to download\n      const isGenericMasked = !!genericEffect;\n\n      const textColor = options.textColor || 'primary-text-color';\n\n      const aroundParams: Parameters<typeof wrapStickerAnimation>[0] = {\n        doc: genericEffect || availableReaction?.around_animation,\n        size: genericEffect ? genericEffectSize : options.sizes.effectSize,\n        target: options.stickerContainer,\n        side: 'center',\n        skipRatio: 1,\n        play: false,\n        managers: options.managers,\n        middleware: options.middleware,\n        scrollable: options.scrollable\n      };\n\n      const aroundWrap = assetName ? undefined : wrapStickerAnimation({\n        ...aroundParams,\n        animation: prepared?.around\n      });\n      const aroundResult = assetName ? lottieLoader.loadAnimationAsAsset({\n        width: options.sizes.effectSize,\n        height: options.sizes.effectSize,\n        skipRatio: 1,\n        autoplay: false,\n        middleware: options.middleware,\n        container: div,\n        noCache: true\n      }, assetName) : aroundWrap.stickerPromise;\n      const genericResult = genericEffect && wrapStickerAnimation({\n        ...aroundParams,\n        animation: prepared?.flight,\n        size: genericEffectSize,\n        stickerSize: size,\n        loopEffect: true,\n        textColor,\n        noOffscreen: true\n      });\n      // * the very same media is already rendered inside the reaction element -\n      // * fly it instead of fetching it again\n      const liveMediaCandidate = isGenericMasked ? Array.from(\n        options.stickerContainer.querySelectorAll<HTMLImageElement | HTMLVideoElement>('img.media-sticker, video.media-sticker')\n      )[0] : undefined;\n      const liveMaskedMedia = liveMediaCandidate instanceof HTMLVideoElement ||\n        (liveMediaCandidate?.complete && liveMediaCandidate.naturalWidth > 0) ?\n        liveMediaCandidate :\n        undefined;\n\n      // * the masked generic flight always flies the icon's first frame (a\n      // * separate static render) - never a mid-animation frame; the native\n      // * effect keeps its animated overlay (rendered here, played explicitly)\n      const stickerResult = (!genericEffect || (isGenericMasked && !liveMaskedMedia)) && !onlyAround && wrapSticker({\n        div: div || document.createElement('div'),\n        doc: sticker || availableReaction.center_icon,\n        width: size,\n        height: size,\n        withThumb: false,\n        needUpscale: true,\n        play: false,\n        skipRatio: 1,\n        group: 'none',\n        needFadeIn: false,\n        managers: options.managers,\n        middleware: options.middleware,\n        textColor,\n        loop: false,\n        static: (isGenericMasked || staticSticker) || undefined,\n        // This player's consumer grabs contexts[0], re-parents canvas[0] and\n        // installs overrideRender after load.\n        noOffscreen: true\n      }).then(({render}) => render as Promise<LottiePlayer>);\n\n      return Promise.all([\n        genericEffect ?\n          genericResult.stickerPromise :\n          stickerResult,\n\n        aroundResult,\n\n        genericEffect && loadReactionGeneric(),\n\n        options.waitPromise\n      ]).then(([iconPlayer, aroundPlayer, reactionGeneric, _]) => {\n        if(onlyAround) {\n          iconPlayer = aroundPlayer;\n        }\n\n        let flightSourcePlayer: LottiePlayer;\n        const deferred = deferredPromise<void>();\n        const remove = () => {\n          deferred.resolve();\n          // return;\n          // if(!isInDOM(div)) return;\n          iconPlayer?.remove();\n          flightSourcePlayer?.remove();\n          div?.remove();\n          options.stickerContainer.classList.remove('has-animation');\n        };\n\n        if(!iconPlayer || !aroundPlayer) {\n          remove();\n          return deferred;\n        }\n\n        if(genericEffect) {\n          const canvas = iconPlayer.canvas[0];\n          canvas.classList.add('hide');\n          const context = iconPlayer.contexts[0];\n          const dpr = canvas.dpr;\n          const newCanvasSize = genericEffectSize * dpr;\n          const size = canvas.width;\n          genericResult.animationDiv.append(canvas);\n          genericResult.animationDiv.style.transform = 'scaleX(-1)';\n\n          // * the effect is not gated on the masked media: it starts right\n          // * away with the best source available and upgrades on the fly -\n          // * live media > stripped thumb placeholder > nothing, then the\n          // * real render replaces the placeholder once it's loaded\n          let maskedMedia: HTMLCanvasElement;\n          let maskedMediaRank = 0;\n          const setMaskedMedia = (\n            media: HTMLImageElement | HTMLVideoElement | HTMLCanvasElement,\n            rank: number\n          ) => {\n            if(!media || rank <= maskedMediaRank) {\n              return;\n            }\n\n            try {\n              maskedMedia = mediaToCanvas(media);\n            } catch{\n              return;\n            }\n\n            maskedMediaRank = rank;\n          };\n\n          setMaskedMedia(liveMaskedMedia, 3);\n          // * the clicked emoji: an INSTANT snapshot (rank 2) so copies fly from\n          // * frame 0, upgraded to the clean first-frame render (rank 3) once ready\n          const stash = peekStashedFlightSource(reaction);\n          if(stash) {\n            stash.snapshot && setMaskedMedia(stash.snapshot, 2);\n            stash.firstFrame.then((media) => setMaskedMedia(media, 3), noop);\n          }\n\n          if(!liveMaskedMedia && liveMediaCandidate instanceof HTMLImageElement) {\n            // * the element's own media is still loading (its fetch started\n            // * earlier than ours) - let it join the flight when it's ready\n            liveMediaCandidate.addEventListener('load', () => {\n              setMaskedMedia(liveMediaCandidate, 2);\n            }, {once: true});\n          }\n\n          if(!maskedMedia) { // * instant placeholder, zero network\n            const strippedThumb = (sticker.thumbs as PhotoSize[])?.find((thumb) => thumb._ === 'photoStrippedSize') as PhotoSize.photoStrippedSize;\n            if(strippedThumb?.bytes?.length) {\n              const {image, loadPromise} = getImageFromStrippedThumb(sticker, strippedThumb, true);\n              loadPromise.then(() => setMaskedMedia(image, 1)).catch(noop);\n            }\n          }\n\n          if(stickerResult) {\n            (stickerResult as any as Promise<any>).then((result) => {\n              if(result instanceof LottiePlayer) {\n                flightSourcePlayer = result;\n                result.onFirstFrame(() => setMaskedMedia(result.canvas[0], 3));\n              } else {\n                setMaskedMedia(Array.isArray(result) ? result[0] : undefined, 3);\n              }\n            }).catch(noop);\n          }\n\n          iconPlayer.onFirstFrame(() => {\n            iconPlayer.setSize(newCanvasSize, newCanvasSize);\n            canvas.classList.remove('hide');\n          });\n\n          let frameNo = 0;\n          const scale = newCanvasSize / 512;\n\n          const {layersPositions, op} = reactionGeneric;\n\n          iconPlayer.overrideRender = (frame) => {\n            if(isGenericMasked) {\n              // * the flight is one composition with the effect around - its\n              // * timeline keeps running even before there is a drawable\n              // * source, the copies simply join in whenever it arrives\n              if(!maskedMedia) {\n                if(++frameNo >= op) {\n                  removeOnFrame();\n                }\n\n                return;\n              }\n\n              frame = maskedMedia as any as HTMLCanvasElement;\n            }\n\n            const isImageData = frame instanceof ImageData;\n            context.clearRect(0, 0, newCanvasSize, newCanvasSize);\n\n            for(let i = 0; i < layersPositions.length; ++i) {\n              const frames = layersPositions[i];\n              const transformations = frames[frameNo];\n              if(!transformations) {\n                continue;\n              }\n\n              let savedContext = false, flippedX = false, flippedY = false;\n              let scaledWidth = size, scaledHeight = size;\n              if(transformations.scale) {\n                const [x, y] = transformations.scale;\n                scaledWidth *= /* Math.abs */(x) * 4 / 100;\n                scaledHeight *= /* Math.abs */(y) * 4 / 100;\n\n                flippedX = x < 0/*  && false */;\n                flippedY = y < 0/*  && false */;\n              }\n\n              let [x, y] = transformations.translation;\n              x = (x + transformations.anchor[0]) * scale - Math.abs(scaledWidth) / 2;\n              y = (y + transformations.anchor[1]) * scale - Math.abs(scaledHeight) / 2;\n\n              if(flippedX || flippedY) {\n                savedContext = true;\n                context.save();\n                context.scale(flippedX ? -1 : 1, flippedY ? -1 : 1);\n\n                if(flippedX) x = -x;\n                if(flippedY) y = -y;\n              }\n\n              if(transformations.opacity) {\n                if(!savedContext) {\n                  savedContext = true;\n                  context.save();\n                }\n\n                context.globalAlpha = transformations.opacity[0] / 100;\n              }\n\n              if(isImageData) {\n                context.putImageData(frame as ImageData, x, y);\n              } else {\n                context.drawImage(frame as ImageBitmap, x, y, scaledWidth, scaledHeight);\n              }\n\n              if(savedContext) {\n                context.restore();\n              }\n            }\n\n            frameNo++;\n\n            if(frameNo >= op) {\n              removeOnFrame();\n            }\n          };\n        }\n\n        const removeOnFrame = () => {\n          // if(!isInDOM(div)) return;\n          fastRaf(remove);\n        };\n\n        options.middleware.onDestroy(removeOnFrame);\n\n        !genericEffect && iconPlayer.addEventListener('enterFrame', (frameNo) => {\n          if(frameNo === iconPlayer.maxFrame) {\n            if(options.cache.wrapStickerPromise) { // wait for fade in animation\n              options.cache.wrapStickerPromise.then(() => {\n                setTimeout(removeOnFrame, 1e3);\n              });\n            } else {\n              removeOnFrame();\n            }\n          }\n        });\n\n        iconPlayer.onFirstFrame(() => {\n          // * has-animation hides the sticker (.media-sticker opacity: 0)\n          // * while the activate overlay replaces it - the generic effect has\n          // * no overlay, the sticker must stay visible under the flight\n          if(div) {\n            options.stickerContainer.append(div);\n            options.stickerContainer.classList.add('has-animation');\n          }\n\n          iconPlayer.play();\n          aroundPlayer.play();\n        });\n\n        return deferred;\n      });\n    };\n\n    const onEmoticon = (sticker: Document.document, emoticon: string = sticker.stickerEmojiRaw) => {\n      return callbackify(apiManagerProxy.getReaction(emoticon), (availableReaction) => {\n        const onlyAround = !!sticker;\n        let staticSticker: boolean;\n        if(availableReaction) {\n          const docs = [\n            availableReaction.around_animation,\n            !onlyAround && availableReaction.center_icon\n          ].filter(Boolean) as Document.document[];\n          const isEffectLoaded = docs.every((doc) => {\n            const cacheContext = apiManagerProxy.getCacheContext(doc);\n            return !!(cacheContext.downloaded || cacheContext.url);\n          });\n\n          if(isEffectLoaded || !docs.length) {\n            return onAvailableReaction({availableReaction, onlyAround});\n          }\n\n          // * the reaction effect isn't loaded yet - play a generic animation\n          // * instead, but still load the effect to fire it the next time\n          docs.forEach(warmUpDownload);\n\n          if(!sticker) {\n            sticker = availableReaction.center_icon ?? availableReaction.static_icon;\n            staticSticker = true;\n          }\n        }\n\n        if(!sticker) {\n          return;\n        }\n\n        const prepared = takePreparedGenericEffect(options.sizes);\n        if(prepared) {\n          return onAvailableReaction({genericEffect: prepared.doc, sticker, staticSticker, prepared});\n        }\n\n        return callbackify(getGenericEffect(options.managers), (genericEffect) => {\n          if(!genericEffect) { // * fallback to the late effect\n            return availableReaction && onAvailableReaction({availableReaction, onlyAround});\n          }\n\n          return onAvailableReaction({genericEffect, sticker, staticSticker});\n        });\n      });\n    };\n\n    let promise: Promise<void>;\n    if(reaction._ === 'reactionEmoji') {\n      promise = Promise.resolve(onEmoticon(undefined, reaction.emoticon));\n    } else if(reaction._ === 'reactionPaid') {\n      promise = Promise.resolve()\n      onAvailableReaction({\n        onlyAround: true,\n        assetName: `StarReactionEffect${getUnsafeRandomInt(1, 3)}` as LottieAssetName\n      })\n    } else {\n      promise = callbackify(options.managers.appEmojiManager.getCustomEmojiDocument(reaction.document_id), (doc) => {\n        return onEmoticon(doc);\n      });\n    }\n\n    options.middleware.onDestroy(() => {\n      options.cache.hasAroundAnimation = undefined;\n    });\n\n    options.cache.hasAroundAnimation = promise;\n    promise.finally(() => {\n      if(options.cache.hasAroundAnimation === promise) {\n        options.cache.hasAroundAnimation = undefined;\n      }\n    }).catch(noop);\n  }\n}\n\nif(!customElements.get(TAG_NAME)) {\n  customElements.define(TAG_NAME, ReactionElement);\n}\n","import type {ReactionsContext} from '@appManagers/appReactionsManager';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport callbackifyAll from '@helpers/callbackifyAll';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport {ReactionCount, SavedReactionTag} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {AppManagers} from '@lib/managers';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport {CustomEmojiRendererElement} from '@lib/customEmoji/renderer';\nimport rootScope from '@lib/rootScope';\nimport {AnimationItemGroup} from '@components/animationIntersector';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport ReactionElement, {ReactionLayoutType, REACTIONS_DISPLAY_COUNTER_AT, REACTIONS_SIZE} from '@components/chat/reaction';\nimport {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport pause from '@helpers/schedulers/pause';\nimport {Accessor, Setter} from 'solid-js';\n\n\nconst CLASS_NAME = 'reactions';\nconst TAG_NAME = CLASS_NAME + '-element';\n\nconst REACTIONS_ELEMENTS: Map<string, Set<ReactionsElement>> = new Map();\nexport {REACTIONS_ELEMENTS};\n\nexport type PendingPaidReaction = {\n  count: Accessor<number>,\n  setCount: Setter<number>,\n  sendTime: Accessor<number>,\n  setSendTime: Setter<number>,\n  sendTimeout: number,\n  abortController: AbortController,\n};\n\nconst PENDING_PAID_REACTIONS: Map<string, PendingPaidReaction> = new Map();\nconst PENDING_PAID_REACTION_SENT_ABORT_REASON = Symbol('Reaction was sent');\nexport {PENDING_PAID_REACTIONS, PENDING_PAID_REACTION_SENT_ABORT_REASON};\n\nexport function getPendingPaidReactionKey(message: ReactionsContext) {\n  return message.peerId + '_' + message.mid;\n}\n\n// Cache of \"may this peer's posts show a paid (star) reaction\" so we don't make a\n// worker round-trip per bubble. Resolves to a boolean once known; cleared when the\n// peer's full info changes (an admin may toggle paid reactions on/off).\nconst PAID_REACTION_AVAILABLE: Map<PeerId, MaybePromise<boolean>> = new Map();\n\nfunction getPaidReactionAvailable(managers: AppManagers, peerId: PeerId): MaybePromise<boolean> {\n  let value = PAID_REACTION_AVAILABLE.get(peerId);\n  if(value === undefined) {\n    value = managers.appReactionsManager.isPaidReactionAvailable(peerId);\n    PAID_REACTION_AVAILABLE.set(peerId, value);\n    if(value instanceof Promise) {\n      value.then(\n        (resolved) => PAID_REACTION_AVAILABLE.set(peerId, resolved),\n        () => PAID_REACTION_AVAILABLE.delete(peerId)\n      );\n    }\n  }\n\n  return value;\n}\n\nrootScope.addEventListener('chat_full_update', (chatId) => {\n  PAID_REACTION_AVAILABLE.delete(chatId.toPeerId(true));\n});\n\nexport const savedReactionTags: SavedReactionTag[] = [];\nrootScope.addEventListener('saved_tags', ({savedPeerId, tags}) => {\n  if(savedPeerId) {\n    return;\n  }\n\n  savedReactionTags.splice(0, savedReactionTags.length, ...tags);\n\n  REACTIONS_ELEMENTS.forEach((set) => {\n    set.forEach((reactionsElement) => {\n      const context = reactionsElement.getContext();\n      if(context.peerId === rootScope.myId && reactionsElement.getType() === ReactionLayoutType.Tag) {\n        reactionsElement.render();\n      }\n    });\n  });\n});\n\nexport default class ReactionsElement extends HTMLElement {\n  private context: ReactionsContext;\n  private key: string;\n  private isPlaceholder: boolean;\n  private type: ReactionLayoutType;\n  private sorted: ReactionElement[];\n  private onConnectCallback: () => void;\n  private managers: AppManagers;\n  private middleware: Middleware;\n  private middlewareHelpers: Map<ReactionElement, MiddlewareHelper>;\n  public customEmojiRenderer: CustomEmojiRendererElement;\n  private customEmojiRendererMiddlewareHelper: MiddlewareHelper;\n  private animationGroup: AnimationItemGroup;\n  private lazyLoadQueue: LazyLoadQueue;\n  private forceCounter: boolean;\n\n  constructor() {\n    super();\n    this.classList.add(CLASS_NAME);\n    this.sorted = [];\n    this.middlewareHelpers = new Map();\n    this.managers = rootScope.managers;\n  }\n\n  connectedCallback() {\n    let set = REACTIONS_ELEMENTS.get(this.key);\n    if(!set) {\n      REACTIONS_ELEMENTS.set(this.key, set = new Set());\n    }\n\n    set.add(this);\n\n    if(this.onConnectCallback && this.isConnected) {\n      this.onConnectCallback();\n      this.onConnectCallback = undefined;\n    }\n  }\n\n  disconnectedCallback() {\n    const set = REACTIONS_ELEMENTS.get(this.key);\n    set.delete(this);\n    if(!set.size) {\n      REACTIONS_ELEMENTS.delete(this.key);\n    }\n  }\n\n  public getType() {\n    return this.type;\n  }\n\n  public getReactionCount(reactionElement: ReactionElement) {\n    return this.sorted[this.sorted.indexOf(reactionElement)].reactionCount;\n  }\n\n  public getContext() {\n    return this.context;\n  }\n\n  public getSorted() {\n    return this.sorted;\n  }\n\n  public shouldUseTagsForContext(context: ReactionsElement['context']) {\n    if(context.peerId !== rootScope.myId) {\n      return false;\n    }\n\n    const reactions = context.reactions;\n    if(!reactions || reactions.pFlags.reactions_as_tags) {\n      return true;\n    }\n\n    return !reactions.results.length;\n  }\n\n  public init({\n    context,\n    type,\n    middleware,\n    isPlaceholder = this.isPlaceholder,\n    animationGroup,\n    lazyLoadQueue,\n    forceCounter\n  }: {\n    context: ReactionsContext,\n    type: ReactionLayoutType,\n    middleware: Middleware,\n    isPlaceholder?: boolean,\n    animationGroup?: AnimationItemGroup,\n    lazyLoadQueue?: LazyLoadQueue,\n    forceCounter?: boolean\n  }) {\n    if(this.key !== undefined) {\n      this.disconnectedCallback();\n    }\n\n    if(this.middleware !== middleware) {\n      middleware.onDestroy(() => {\n        this.middlewareHelpers.clear();\n      });\n    }\n\n    this.context = context;\n    this.key = this.context.peerId + '_' + this.context.mid;\n    this.middleware = middleware;\n    this.isPlaceholder = isPlaceholder;\n    this.animationGroup = animationGroup;\n    this.lazyLoadQueue = lazyLoadQueue;\n    this.forceCounter = forceCounter;\n\n    this.setType(type);\n\n    this.connectedCallback();\n  }\n\n  public setType(type: ReactionLayoutType) {\n    if(type === ReactionLayoutType.Block && this.shouldUseTagsForContext(this.context)) {\n      type = ReactionLayoutType.Tag;\n    }\n\n    if(this.type === type) {\n      return;\n    }\n\n    this.type = type;\n\n    for(const type in ReactionLayoutType) {\n      this.classList.remove(CLASS_NAME + '-' + type);\n    }\n\n    this.classList.add(CLASS_NAME + '-' + type);\n    this.classList.toggle(CLASS_NAME + '-like-block', type === ReactionLayoutType.Block || type === ReactionLayoutType.Tag);\n  }\n\n  public changeContext(context: ReactionsContext) {\n    return this.init({\n      context,\n      type: this.type,\n      middleware: this.middleware\n    });\n  }\n\n  public update(context: ReactionsContext, changedResults?: ReactionCount[], waitPromise?: Promise<any>) {\n    this.context = context;\n    this.render(changedResults, waitPromise);\n  }\n\n  private shouldAddEmptyPaidReaction(counts: ReactionCount[]) {\n    if(\n      this.type !== ReactionLayoutType.Block ||\n      this.context.peerId.isUser() ||\n      !counts.length ||\n      counts.some((reactionCount) => reactionCount.reaction._ === 'reactionPaid')\n    ) {\n      return false;\n    }\n\n    const available = getPaidReactionAvailable(this.managers, this.context.peerId);\n    if(available instanceof Promise) {\n      // Availability isn't known yet — re-render once it resolves (if still mounted).\n      // Swallow rejections (e.g. CHANNEL_PRIVATE): a failed lookup just means no button.\n      available.then((value) => {\n        if(value && this.middleware?.()) {\n          this.render();\n        }\n      }, () => {});\n      return false;\n    }\n\n    return available;\n  }\n\n  public render(changedResults?: ReactionCount[], waitPromise?: Promise<any>) {\n    const reactions = this.context.reactions;\n    const hasReactions = !!(reactions && reactions.results.length);\n    this.classList.toggle('has-no-reactions', !hasReactions);\n    if(!hasReactions && !this.sorted.length) return;\n\n    // const availableReactionsResult = this.managers.appReactionsManager.getAvailableReactions();\n    // callbackify(availableReactionsResult, () => {\n    let counts = hasReactions ? (\n      reactions.results\n        // availableReactionsResult instanceof Promise ?\n        //   reactions.results :\n        //   reactions.results.filter((reactionCount) => {\n        //     return this.managers.appReactionsManager.isReactionActive(reactionCount.reaction);\n        //   })\n      ) : [];\n\n    // Like the official clients: on channel/group posts that already have reactions\n    // but no paid one, prepend an empty (count 0) paid star reaction button so users\n    // can send stars. A fresh array — never mutate the message's own results.\n    if(this.shouldAddEmptyPaidReaction(counts)) {\n      counts = [{_: 'reactionCount', reaction: {_: 'reactionPaid'}, count: 0}, ...counts];\n    }\n\n    // counts = counts.filter((count) => count.reaction._ !== 'reactionPaid');\n\n    // if(this.context.peerId.isUser()) {\n    //   counts.sort((a, b) => (b.count - a.count) || ((b.chosen_order ?? 0) - (a.chosen_order ?? 0)));\n    // } else {\n    // counts.sort((a, b) => (b.count - a.count) || ((a.chosen_order ?? 0) - (b.chosen_order ?? 0)));\n    // }\n\n    forEachReverse(this.sorted, (reactionElement, idx, arr) => {\n      const reaction = reactionElement.reactionCount.reaction;\n      const found = counts.some((reactionCount) => reactionsEqual(reactionCount.reaction, reaction));\n      if(!found) {\n        const middlewareHelper = this.middlewareHelpers.get(reactionElement);\n        middlewareHelper.destroy();\n        this.middlewareHelpers.delete(reactionElement);\n        arr.splice(idx, 1);\n        reactionElement.remove();\n      }\n    });\n\n    let animationShouldHaveDelay = false;\n    const totalReactions = counts.reduce((acc, c) => acc + c.count, 0);\n    const canRenderAvatars = reactions &&\n      (!!reactions.pFlags.can_see_list || this.context.peerId.isUser()) &&\n      totalReactions < REACTIONS_DISPLAY_COUNTER_AT[this.type];\n    const customEmojiElements: ReturnType<ReactionElement['render']>[] = new Array(counts.length);\n    let paidReactionElement: ReactionElement, pendingPaidReaction: PendingPaidReaction;\n    this.sorted = counts.map((reactionCount, idx, arr) => {\n      let reactionElement: ReactionElement = this.sorted.find((reactionElement) => reactionsEqual(reactionElement.reactionCount.reaction, reactionCount.reaction));\n      if(!reactionElement) {\n        const middlewareHelper = this.middleware.create();\n        reactionElement = new ReactionElement();\n        reactionElement.init(this.type, middlewareHelper.get());\n        this.middlewareHelpers.set(reactionElement, middlewareHelper);\n      }\n\n      reactionElement.classList.toggle('is-last', idx === (arr.length - 1));\n\n      const isPaidReaction = reactionCount.reaction._ === 'reactionPaid';\n      const pending = isPaidReaction && PENDING_PAID_REACTIONS.get(getPendingPaidReactionKey(this.context));\n      if(pending) {\n        paidReactionElement = reactionElement;\n        pendingPaidReaction = pending;\n      }\n\n      const recentReactions = reactions.recent_reactions ?\n        reactions.recent_reactions.filter((reaction) => reactionsEqual(reaction.reaction, reactionCount.reaction)) :\n        [];\n      const wasUnread = reactionElement.isUnread;\n      const isUnread = recentReactions.some((reaction) => reaction.pFlags.unread);\n      reactionElement.reactionCount = {\n        ...reactionCount,\n        count: reactionCount.count + (pending?.count?.() ?? 0)\n      };\n      reactionElement.setCanRenderAvatars(canRenderAvatars);\n      const customEmojiElement = reactionElement.render(this.isPlaceholder);\n      reactionElement.renderCounter(this.forceCounter);\n      reactionElement.renderAvatars(recentReactions);\n      reactionElement.isUnread = isUnread;\n      reactionElement.setIsChosen(\n        isPaidReaction ?\n          !!pending || !!reactions.top_reactors?.some((reactor) => reactor.pFlags.my && reactor.count) :\n          undefined\n      );\n\n      if(wasUnread && !isUnread && !changedResults?.includes(reactionCount)) {\n        (changedResults ??= []).push(reactionCount);\n        animationShouldHaveDelay = true;\n      }\n\n      customEmojiElements[idx] = customEmojiElement;\n\n      return reactionElement;\n    });\n\n    this.sorted.forEach((element, idx) => {\n      positionElementByIndex(element, this, idx);\n    });\n\n    if(pendingPaidReaction) {\n      const {width} = paidReactionElement.getBoundingClientRect();\n      paidReactionElement.style.setProperty('--width', width + 'px');\n      paidReactionElement.setPaidReactionCounter(pendingPaidReaction.count());\n      if(!paidReactionElement.classList.contains('effect-active')) {\n        paidReactionElement.classList.add('effect-active');\n        pendingPaidReaction.abortController.signal.addEventListener('abort', () => {\n          paidReactionElement.classList.remove('effect-active');\n          paidReactionElement.querySelectorAll('.reaction-sticker-activate').forEach((it) => it.remove());\n          paidReactionElement.destroyPaidReactionCounter();\n        });\n      }\n    }\n\n    callbackifyAll(customEmojiElements, (customEmojiElements) => {\n      const map: Parameters<CustomEmojiRendererElement['add']>[0]['addCustomEmojis'] = new Map();\n      customEmojiElements.forEach((customEmojiElement) => {\n        if(!customEmojiElement) {\n          return;\n        }\n\n        map.set(customEmojiElement.docId, new Set([customEmojiElement]));\n      });\n\n      if(!map.size) {\n        if(this.customEmojiRenderer) {\n          this.customEmojiRendererMiddlewareHelper.destroy();\n          this.customEmojiRenderer.remove();\n          this.customEmojiRenderer =\n            this.customEmojiRendererMiddlewareHelper =\n            undefined;\n        }\n\n        return;\n      }\n\n      if(!this.customEmojiRenderer) {\n        const size = REACTIONS_SIZE[this.type];\n        this.customEmojiRendererMiddlewareHelper = this.middleware.create();\n        this.customEmojiRenderer = CustomEmojiRendererElement.create({\n          animationGroup: this.animationGroup,\n          customEmojiSize: makeMediaSize(size, size),\n          middleware: this.customEmojiRendererMiddlewareHelper.get(),\n          lazyLoadQueue: this.lazyLoadQueue,\n          observeResizeElement: this\n        });\n\n        this.customEmojiRenderer.classList.add(CLASS_NAME + '-renderer');\n        this.customEmojiRenderer.canvas.classList.add(CLASS_NAME + '-renderer-canvas');\n        this.prepend(this.customEmojiRenderer);\n      }\n\n      this.customEmojiRenderer.add({\n        addCustomEmojis: map,\n        lazyLoadQueue: this.lazyLoadQueue\n      });\n    });\n\n    if(!this.isPlaceholder && changedResults?.length) {\n      if(this.isConnected) {\n        this.handleChangedResults(changedResults, waitPromise, animationShouldHaveDelay);\n      } else {\n        this.onConnectCallback = () => {\n          this.handleChangedResults(changedResults, waitPromise, animationShouldHaveDelay);\n        };\n      }\n    }\n  }\n\n  private async handleChangedResults(changedResults: ReactionCount[], waitPromise?: Promise<any>, withDelay?: boolean) {\n    await getHeavyAnimationPromise();\n    // ! temp\n    if(this.context.peerId !== appImManager.chat.peerId) return;\n    if(withDelay) {\n      waitPromise = (waitPromise || Promise.resolve()).then(() => pause(150));\n    }\n\n    changedResults.forEach((reactionCount) => {\n      const reactionElement = this.sorted.find((reactionElement) => {\n        return reactionsEqual(reactionElement.reactionCount.reaction, reactionCount.reaction);\n      });\n\n      reactionElement?.fireAroundAnimation(waitPromise);\n    });\n  }\n}\n\nif(!customElements.get(TAG_NAME)) {\n  customElements.define(TAG_NAME, ReactionsElement);\n}\n","import Scrollable from '@components/scrollable';\nimport safeAssign from '@helpers/object/safeAssign';\n\nexport default class ScrollableLoader {\n  public loading = false;\n  private scrollable: Scrollable;\n  private getPromise: () => Promise<boolean>;\n  private promise: Promise<any>;\n  private loaded = false;\n\n  constructor(options: {\n    scrollable: ScrollableLoader['scrollable'],\n    getPromise: ScrollableLoader['getPromise']\n  }) {\n    safeAssign(this, options);\n\n    options.scrollable.onScrolledBottom = () => {\n      this.load();\n    };\n  }\n\n  public load() {\n    if(this.loaded) {\n      return Promise.resolve();\n    }\n\n    if(this.loading) {\n      return this.promise;\n    }\n\n    this.loading = true;\n    this.promise = this.getPromise().then((done) => {\n      this.loading = false;\n      this.promise = undefined;\n\n      if(done) {\n        this.loaded = true;\n        this.scrollable.onScrolledBottom = null;\n      } else {\n        this.scrollable.checkForTriggers();\n      }\n    }, () => {\n      this.promise = undefined;\n      this.loading = false;\n    });\n  }\n}\n","import {Message, Reaction} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport PopupElement from '@components/popups';\nimport PopupDeleteMegagroupMessages from '@components/popups/deleteMegagroupMessages';\n\nexport default async function deleteParticipantReaction({\n  message,\n  participantPeerId,\n  knownReaction,\n  isMyReaction,\n  managers,\n  onConfirm\n}: {\n  message: Message.message | Message.messageService,\n  participantPeerId: PeerId,\n  knownReaction?: Reaction,\n  isMyReaction?: boolean,\n  managers: AppManagers,\n  onConfirm?: () => void\n}) {\n  if(\n    isMyReaction ||\n    participantPeerId === rootScope.myId ||\n    !await managers.appReactionsManager.canDeleteParticipantReactions(message.peerId)\n  ) {\n    return;\n  }\n\n  PopupElement.createPopup(PopupDeleteMegagroupMessages, {\n    reaction: {\n      message,\n      participantPeerId,\n      knownReaction\n    },\n    onConfirm\n  });\n  return true;\n}\n","import PopupElement from '.';\nimport {Message, Reaction, ReactionCount} from '@layer';\nimport ReactionsElement from '@components/chat/reactions';\nimport {horizontalMenu} from '@components/horizontalMenu';\nimport Scrollable from '@components/scrollable';\nimport ScrollableLoader from '@helpers/scrollableLoader';\nimport appDialogsManager, {DialogDom, DialogElement} from '@lib/appDialogsManager';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport wrapSticker from '@components/wrappers/sticker';\nimport ReactionElement, {ReactionLayoutType} from '@components/chat/reaction';\nimport getUserStatusString from '@components/wrappers/getUserStatusString';\nimport {MediaSize, makeMediaSize} from '@helpers/mediaSize';\nimport wrapCustomEmoji from '@components/wrappers/customEmoji';\nimport SettingSection from '@components/settingSection';\nimport {formatFullSentTime} from '@helpers/date';\nimport {Middleware} from '@helpers/middleware';\nimport rootScope from '@lib/rootScope';\nimport Icon from '@components/icon';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport {ButtonMenuSync} from '@components/buttonMenu';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport contextMenuController from '@helpers/contextMenuController';\nimport positionMenu from '@helpers/positionMenu';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport deleteParticipantReaction from '@components/chat/deleteParticipantReaction';\n\nconst size = 24;\nconst _mediaSize = makeMediaSize(size, size);\nexport async function processDialogElementForReaction({\n  peerId,\n  dialogElement,\n  reaction,\n  middleware,\n  isMine,\n  date,\n  mediaSize = _mediaSize\n}: {\n  peerId: PeerId,\n  dialogElement: DialogElement,\n  reaction?: Reaction,\n  middleware: Middleware,\n  isMine: boolean,\n  date: number,\n  mediaSize?: MediaSize\n}) {\n  const {dom} = dialogElement;\n  if(reaction) {\n    const stickerContainer = document.createElement('div');\n    stickerContainer.classList.add('reacted-list-reaction-icon');\n\n    if(reaction._ === 'reactionEmoji') {\n      const availableReaction = await rootScope.managers.appReactionsManager.getReaction(reaction.emoticon);\n\n      wrapSticker({\n        doc: availableReaction.static_icon,\n        div: stickerContainer,\n        width: 24,\n        height: 24,\n        middleware\n      });\n    } else if(reaction._ === 'reactionCustomEmoji') {\n      stickerContainer.append(wrapCustomEmoji({\n        docIds: [reaction.document_id],\n        customEmojiSize: mediaSize,\n        middleware\n      }));\n    }\n\n    dom.listEl.append(stickerContainer);\n  }\n\n  if(date && isMine) {\n    const c = document.createElement('span');\n    dom.lastMessageSpan.style.cssText = `display: flex !important; align-items: center;`;\n    const span = Icon(reaction ? 'reactions' : 'checks', 'reacted-list-checks');\n    const fragment = document.createDocumentFragment();\n    c.append(formatFullSentTime(date, false));\n    fragment.append(span, c);\n    replaceContent(dom.lastMessageSpan, fragment);\n  } else if(peerId.isUser()) {\n    const user = await rootScope.managers.appUsersManager.getUser(peerId.toUserId());\n    replaceContent(dom.lastMessageSpan, getUserStatusString(user));\n  } else if(date) {\n    replaceContent(dom.lastMessageSpan, formatFullSentTime(date, false));\n  }\n}\n\nexport default class PopupReactedList extends PopupElement {\n  constructor(\n    private message: Message.message,\n    private initialReaction?: Reaction\n  ) {\n    super('popup-reacted-list', {closable: true, overlayClosable: true, body: true});\n\n    this.init();\n  }\n\n  private async init() {\n    const middleware = this.middlewareHelper.get();\n    const message = await this.managers.appMessagesManager.getGroupsFirstMessage(this.message);\n    if(!middleware()) return;\n    const [canViewReadParticipants, canDeleteReactions] = await Promise.all([\n      this.managers.appMessagesManager.canViewMessageReadParticipants(message),\n      this.managers.appReactionsManager.canDeleteParticipantReactions(message.peerId)\n    ]);\n    if(!middleware()) return;\n    // this.body.append(generateDelimiter());\n\n    const reactionsElement = new ReactionsElement();\n    const newMessage: Message.message = {\n      ...message,\n      mid: 0,\n      id: 0,\n      reactions: {\n        _: 'messageReactions',\n        results: [],\n\n        ...message.reactions,\n\n        pFlags: {},\n        recent_reactions: []\n      }\n    };\n\n    newMessage.reactions.results = newMessage.reactions.results.map((reactionCount) => {\n      const _reactionCount: ReactionCount = {\n        ...reactionCount,\n        chosen_order: undefined\n      };\n\n      return _reactionCount;\n    });\n\n    reactionsElement.init({\n      context: newMessage,\n      type: ReactionLayoutType.Block,\n      middleware: this.middlewareHelper.get()\n    });\n    reactionsElement.render();\n    reactionsElement.classList.add('no-stripe');\n    reactionsElement.classList.remove('has-no-reactions');\n\n    reactionsElement.append(this.btnClose);\n\n    this.header.append(reactionsElement);\n\n    const tabsContainer = document.createElement('div');\n    tabsContainer.classList.add('tabs-container');\n    tabsContainer.dataset.animation = 'tabs';\n\n    const loaders: Map<HTMLElement, ScrollableLoader> = new Map();\n\n    let hasAllReactions = false;\n    if(newMessage.reactions.results.length) {\n      const reaction = this.createFakeReaction('reactions', newMessage.reactions.results.reduce((acc, r) => acc + r.count, 0));\n\n      reactionsElement.prepend(reaction);\n      newMessage.reactions.results.unshift(reaction.reactionCount);\n      hasAllReactions = true;\n    }\n\n    let hasReadParticipants = false;\n    if(canViewReadParticipants) {\n      try {\n        const readUserIds = await this.managers.appMessagesManager.getMessageReadParticipants(message.peerId, message.mid);\n        if(!middleware()) return;\n        if(!readUserIds.length) {\n          throw '';\n        }\n\n        const reaction = this.createFakeReaction('checks', readUserIds.length);\n\n        reactionsElement.prepend(reaction);\n        newMessage.reactions.results.unshift(reaction.reactionCount);\n        hasReadParticipants = true;\n      } catch(err) {\n\n      }\n    }\n\n    if(reactionsElement.customEmojiRenderer) {\n      reactionsElement.append(reactionsElement.customEmojiRenderer);\n    }\n\n    const initialTabIndex = this.initialReaction ? newMessage.reactions.results.findIndex((reactionCount) => {\n      return reactionsEqual(reactionCount.reaction, this.initialReaction);\n    }) : 0;\n\n    newMessage.reactions.results.forEach((reactionCount) => {\n      const scrollable = new Scrollable(undefined);\n      scrollable.container.classList.add('tabs-tab');\n\n      const chatlist = appDialogsManager.createChatList({\n        dialogSize: 72\n      });\n\n      appDialogsManager.setListClickListener({\n        list: chatlist,\n        onFound: () => {\n          this.hide();\n        },\n        withContext: undefined,\n        autonomous: false,\n        openInner: true\n      });\n\n      scrollable.append(chatlist);\n\n      const skipReadParticipants = (reactionCount.reaction as any) !== 'checks';\n      const skipReactionsList = (reactionCount.reaction as any) === 'checks';\n      if(['checks', 'reactions'].includes(reactionCount.reaction as any)) {\n        reactionCount.reaction = undefined;\n      }\n\n      let nextOffset: string;\n      const loader = new ScrollableLoader({\n        scrollable,\n        getPromise: async() => {\n          const result = await this.managers.appMessagesManager.getMessageReactionsListAndReadParticipants(message, undefined, reactionCount.reaction, nextOffset, skipReadParticipants, skipReactionsList);\n          nextOffset = result.nextOffset;\n\n          await Promise.all(result.combined.map(async({peerId, reaction, date, isMyReaction}) => {\n            const dialogElement = appDialogsManager.addDialogNew({\n              peerId: peerId,\n              autonomous: true,\n              container: chatlist,\n              avatarSize: 'abitbigger',\n              rippleEnabled: false,\n              meAsSaved: false,\n              wrapOptions: {\n                middleware: this.middlewareHelper.get()\n              }\n            });\n\n            await processDialogElementForReaction({\n              dialogElement,\n              date,\n              isMine: message.pFlags.out,\n              middleware,\n              peerId,\n              reaction\n            });\n            if(!middleware()) return;\n\n            if(canDeleteReactions && reaction && !isMyReaction && peerId !== rootScope.myId) {\n              attachContextMenuListener({\n                element: dialogElement.dom.listEl,\n                callback: (e) => this.openDeleteReactionMenu({\n                  e,\n                  element: dialogElement.dom.listEl,\n                  message,\n                  participantPeerId: peerId,\n                  reaction,\n                  isMyReaction\n                }),\n                listenerSetter: this.listenerSetter\n              });\n            }\n          }));\n\n          return !nextOffset;\n        }\n      });\n\n      loaders.set(scrollable.container, loader);\n\n      tabsContainer.append(scrollable.container);\n    });\n\n    this.body.append(tabsContainer);\n\n    const selectTab = horizontalMenu(reactionsElement, tabsContainer, (id, tabContent) => {\n      if(id >= (reactionsElement.childElementCount - (reactionsElement.customEmojiRenderer ? 2 : 1))) {\n        return false;\n      }\n\n      const reaction = reactionsElement.children[id] as ReactionElement;\n      const prevId = selectTab.prevId();\n      if(prevId !== -1) {\n        (reactionsElement.children[prevId] as ReactionElement).setIsChosen(false);\n      }\n\n      reaction.setIsChosen(true);\n\n      const loader = loaders.get(tabContent);\n      loader.load();\n    }, undefined, undefined, undefined, this.listenerSetter);\n\n    // selectTab(hasAllReactions && hasReadParticipants ? 1 : 0, false);\n    selectTab(initialTabIndex === -1 ? 0 : initialTabIndex, false);\n\n    this.show();\n  }\n\n  private openDeleteReactionMenu({\n    e,\n    element,\n    message,\n    participantPeerId,\n    reaction,\n    isMyReaction\n  }: {\n    e: MouseEvent | TouchEvent,\n    element: HTMLElement,\n    message: Message.message,\n    participantPeerId: PeerId,\n    reaction: Reaction,\n    isMyReaction?: boolean\n  }) {\n    cancelEvent(e);\n\n    const listenerSetter = new ListenerSetter();\n    const menu = ButtonMenuSync({\n      buttons: [{\n        icon: 'delete',\n        text: 'DeleteReaction',\n        danger: true,\n        onClick: () => {\n          void deleteParticipantReaction({\n            message,\n            participantPeerId,\n            knownReaction: reaction,\n            isMyReaction,\n            managers: this.managers,\n            onConfirm: () => {\n              this.hide();\n            }\n          });\n        }\n      }],\n      listenerSetter\n    });\n    menu.classList.add('contextmenu');\n    getOverlayRoot().append(menu);\n    positionMenu(e, menu);\n    contextMenuController.openBtnMenu(menu, () => {\n      listenerSetter.removeAll();\n      setTimeout(() => menu.remove(), 300);\n    }, element);\n  }\n\n  private createFakeReaction(icon: Icon, count: number) {\n    const reaction = new ReactionElement();\n    reaction.init(ReactionLayoutType.Block, this.middlewareHelper.get());\n    reaction.reactionCount = {\n      _: 'reactionCount',\n      count: count,\n      reaction: icon as any\n    };\n    reaction.setCanRenderAvatars(false);\n    reaction.renderCounter();\n\n    const allReactionsSticker = document.createElement('div');\n    allReactionsSticker.classList.add('reaction-counter', 'reaction-sticker-icon');\n    allReactionsSticker.append(Icon(icon));\n    reaction.prepend(allReactionsSticker);\n\n    return reaction;\n  }\n}\n","import {Document, Message, MessageMedia} from '@layer';\n\nexport function canSaveMessageMediaWithNoForwards(message: Message.message) {\n  const document = (message.media as MessageMedia.messageMediaDocument)?.document;\n  if(!document) {\n    return false;\n  }\n\n  return !(['video', 'gif', 'round', 'sticker'] as Document.document['type'][]).includes((document as Document.document).type);\n}\n\nexport default function canSaveMessageMedia(\n  message: Message.message | Message.messageService,\n  noForwards?: boolean\n) {\n  return message &&\n    !message.pFlags.is_outgoing &&\n    !((message as Message.message).media as MessageMedia.messageMediaInvoice)?.extended_media &&\n    (!((message as Message.message).pFlags.noforwards || noForwards) || canSaveMessageMediaWithNoForwards(message as Message.message));\n}\n","// https://github.com/telegramdesktop/tdesktop/blob/0514f13af0d7d1686944e7ba909df2dab16a6f5e/Telegram/SourceFiles/core/mime_type.cpp#L327\nconst extensionsSet = new Set(['htm', 'html', 'svg', 'm4v', 'm3u', 'm3u8', 'xhtml', 'xml', 'kml', 'kmz']);\nconst mimeTypesSet = new Set(['text/html', 'image/svg+xml', 'application/vnd.google-earth.kml+xml', 'application/vnd.google-earth.kmz']);\n\nexport const isIpRevealingExtension = (extension: string) => extensionsSet.has(extension);\nexport const isIpRevealingMimeType = (mimeType: string) => mimeTypesSet.has(mimeType);\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport ListLoader from '@helpers/listLoader';\nimport {Message} from '@layer';\nimport type {\n  MediaItem,\n  MediaListLoader,\n  MediaListLoaderFactory,\n  MediaListLoaderOptions\n} from './appMediaPlaybackController';\n\n/**\n * A `MediaListLoader` implementation that exposes an always-empty playlist.\n *\n * Intended for media that should play in isolation (e.g. a poll's\n * description / explanation audio) — the playback controller still\n * tracks the media as the currently-playing one, but `next` / `previous`\n * navigation does nothing because there is nothing to navigate to.\n *\n * Use the exported `emptyMediaListLoaderFactory` as the\n * `listLoaderFactory` on an `AudioElement`.\n */\nexport class EmptyMediaListLoader extends ListLoader<MediaItem, Message.message> implements MediaListLoader {\n  public onEmptied?: () => void;\n\n  constructor() {\n    super({\n      loadMore: async() => ({count: 0, items: []})\n    });\n\n    // No prev / no next — we're loaded \"to the ends\" in both directions.\n    this.setLoaded(true, true);\n    this.setLoaded(false, true);\n  }\n\n  public setOptions(options: MediaListLoaderOptions) {\n    this.processItem = options.processItem;\n    this.loadCount = options.loadCount ?? 50;\n    this.loadWhenLeft = options.loadWhenLeft ?? 20;\n    this.onJump = options.onJump;\n    this.onEmptied = options.onEmptied;\n    this.onLoadedMore = options.onLoadedMore;\n  }\n\n  public goRound(_length: number, _dispatchJump?: boolean): void {\n    // Empty playlist: navigation is a no-op.\n  }\n\n  public getPrevious(_withOtherSide?: boolean): MediaItem[] {\n    return [];\n  }\n\n  public getNext(_withOtherSide?: boolean): MediaItem[] {\n    return [];\n  }\n\n  public setCurrent(item: MediaItem) {\n    this.current = item;\n  }\n\n  public cleanup() {\n    // No external resources to release.\n  }\n}\n\nexport const emptyMediaListLoaderFactory: MediaListLoaderFactory = (options) => {\n  const loader = new EmptyMediaListLoader();\n  loader.setOptions(options);\n  return loader;\n};\n","import type {ChatSetPeerOptions} from '@lib/appImManager';\n\n// * https://core.telegram.org/api/links\n\nexport enum INTERNAL_LINK_TYPE {\n  MESSAGE,\n  PRIVATE_POST,\n  STICKER_SET,\n  JOIN_CHAT,\n  VOICE_CHAT,\n  USER_PHONE_NUMBER,\n  INVOICE,\n  EMOJI_SET,\n  ATTACH_MENU_BOT,\n  WEB_APP,\n  ADD_LIST,\n  STORY,\n  BOOST,\n  PREMIUM_FEATURES,\n  GIFT_CODE,\n  BUSINESS_CHAT,\n  STARS_TOPUP,\n  SHARE,\n  UNIQUE_STAR_GIFT,\n  STAR_GIFT_COLLECTION,\n  STORY_ALBUM,\n  INSTANT_VIEW,\n  NEW,\n  SETTINGS,\n  CONTACTS,\n  CONFERENCE_CALL,\n  ADD_AI_STYLE\n};\n\nexport type InternalLink =\n  InternalLink.InternalLinkMessage |\n  InternalLink.InternalLinkPrivatePost |\n  InternalLink.InternalLinkStickerSet |\n  InternalLink.InternalLinkJoinChat |\n  InternalLink.InternalLinkVoiceChat |\n  InternalLink.InternalLinkUserPhoneNumber |\n  InternalLink.InternalLinkInvoice |\n  InternalLink.InternalLinkEmojiSet |\n  InternalLink.InternalLinkAttachMenuBot |\n  InternalLink.InternalLinkWebApp |\n  InternalLink.InternalLinkAddList |\n  InternalLink.InternalLinkStory |\n  InternalLink.InternalLinkBoost |\n  InternalLink.InternalLinkPremiumFeatures |\n  InternalLink.InternalLinkGiftCode |\n  InternalLink.InternalLinkBusinessChat |\n  InternalLink.InternalLinkStarsTopup |\n  InternalLink.InternalLinkShare |\n  InternalLink.InternalLinkUniqueStarGift |\n  InternalLink.InternalLinkStarGiftCollection |\n  InternalLink.InternalLinkStoryAlbum |\n  InternalLink.InternalLinkInstantView |\n  InternalLink.InternalLinkNew |\n  InternalLink.InternalLinkSettings |\n  InternalLink.InternalLinkContacts |\n  InternalLink.InternalLinkConferenceCall |\n  InternalLink.InternalLinkAddAiStyle;\n\nexport namespace InternalLink {\n  export interface InternalLinkMessage {\n    _: INTERNAL_LINK_TYPE.MESSAGE,\n    domain: string,\n    post?: string,\n    comment?: string,\n    thread?: string,\n    start?: string,\n    startgroup?: string,\n    startchannel?: string,\n    admin?: string,\n    option?: string,\n    t?: string, // media timestamp\n    single?: string,\n    text?: string,\n    stack?: ChatSetPeerOptions['stack'] // local\n  }\n\n  export interface InternalLinkPrivatePost {\n    _: INTERNAL_LINK_TYPE.PRIVATE_POST,\n    channel: string,\n    post: string,\n    thread?: string,\n    comment?: string,\n    option?: string,\n    t?: string // media timestamp\n    stack?: ChatSetPeerOptions['stack'] // local\n  }\n\n  export interface InternalLinkStickerSet {\n    _: INTERNAL_LINK_TYPE.STICKER_SET,\n    set: string\n  }\n\n  export interface InternalLinkJoinChat {\n    _: INTERNAL_LINK_TYPE.JOIN_CHAT,\n    invite: string\n  }\n\n  export interface InternalLinkVoiceChat {\n    _: INTERNAL_LINK_TYPE.VOICE_CHAT,\n    id?: string,\n    access_hash?: string,\n    chat_id?: string,\n    domain?: string,\n    livestream?: string,\n    videochat?: string,\n    voicechat?: string\n  }\n\n  export interface InternalLinkUserPhoneNumber {\n    _: INTERNAL_LINK_TYPE.USER_PHONE_NUMBER,\n    phone: string,\n    text?: string\n  }\n\n  export interface InternalLinkInvoice {\n    _: INTERNAL_LINK_TYPE.INVOICE,\n    slug: string\n  }\n\n  export interface InternalLinkEmojiSet {\n    _: INTERNAL_LINK_TYPE.EMOJI_SET,\n    set: string\n  }\n\n  export interface InternalLinkAttachMenuBot {\n    _: INTERNAL_LINK_TYPE.ATTACH_MENU_BOT,\n    startattach?: string,\n    choose?: TelegramChoosePeerType,\n    attach?: string,\n    domain?: string,\n    nestedLink?: InternalLink\n  }\n\n  export interface InternalLinkWebApp {\n    _: INTERNAL_LINK_TYPE.WEB_APP,\n    domain: string,\n    appname: string,\n    startapp?: string,\n    masked?: boolean,\n    mode?: 'compact' | 'fullscreen'\n  }\n\n  export interface InternalLinkAddList {\n    _: INTERNAL_LINK_TYPE.ADD_LIST,\n    slug: string\n  }\n\n  export interface InternalLinkStory {\n    _: INTERNAL_LINK_TYPE.STORY,\n    domain: string,\n    story: string\n  }\n\n  export interface InternalLinkBoost {\n    _: INTERNAL_LINK_TYPE.BOOST,\n    domain?: string,\n    channel?: string\n  }\n\n  export interface InternalLinkPremiumFeatures {\n    _: INTERNAL_LINK_TYPE.PREMIUM_FEATURES,\n    ref?: string\n  }\n\n  export interface InternalLinkGiftCode {\n    _: INTERNAL_LINK_TYPE.GIFT_CODE,\n    slug: string,\n    stack?: ChatSetPeerOptions['stack'] // local\n  }\n\n  export interface InternalLinkBusinessChat {\n    _: INTERNAL_LINK_TYPE.BUSINESS_CHAT,\n    slug: string\n  }\n\n  export interface InternalLinkStarsTopup {\n    _: INTERNAL_LINK_TYPE.STARS_TOPUP,\n    balance: string,\n    purpose: string\n  }\n\n  export interface InternalLinkShare {\n    _: INTERNAL_LINK_TYPE.SHARE,\n    url?: string,\n    text?: string\n  }\n\n  export interface InternalLinkUniqueStarGift {\n    _: INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT,\n    slug: string\n  }\n\n  export interface InternalLinkStarGiftCollection {\n    _: INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION,\n    domain: string,\n    id: string\n  }\n\n  export interface InternalLinkStoryAlbum {\n    _: INTERNAL_LINK_TYPE.STORY_ALBUM,\n    domain: string,\n    id: string\n  }\n\n  export interface InternalLinkInstantView {\n    _: INTERNAL_LINK_TYPE.INSTANT_VIEW,\n    url: string\n  }\n\n  export interface InternalLinkNew {\n    _: INTERNAL_LINK_TYPE.NEW,\n    type?: 'group' | 'contact' | 'channel'\n  }\n\n  export interface InternalLinkSettings {\n    _: INTERNAL_LINK_TYPE.SETTINGS,\n    path: string\n  }\n\n  export interface InternalLinkContacts {\n    _: INTERNAL_LINK_TYPE.CONTACTS,\n    type?: 'search' | 'sort' | 'new' | 'invite' | 'manage'\n  }\n\n  // t.me/call/<slug> and tg://call?slug=<slug> — invite link for a\n  // TdE2E-encrypted conference call. The slug resolves to an\n  // `inputGroupCallSlug` that we feed straight into\n  // `groupCallsController.joinConference`.\n  export interface InternalLinkConferenceCall {\n    _: INTERNAL_LINK_TYPE.CONFERENCE_CALL,\n    slug: string\n  }\n\n  export interface InternalLinkAddAiStyle {\n    _: INTERNAL_LINK_TYPE.ADD_AI_STYLE,\n    slug: string\n  }\n}\n\nexport type InternalLinkTypeMap = {\n  [INTERNAL_LINK_TYPE.MESSAGE]: InternalLink.InternalLinkMessage,\n  [INTERNAL_LINK_TYPE.PRIVATE_POST]: InternalLink.InternalLinkPrivatePost,\n  [INTERNAL_LINK_TYPE.STICKER_SET]: InternalLink.InternalLinkStickerSet,\n  [INTERNAL_LINK_TYPE.JOIN_CHAT]: InternalLink.InternalLinkJoinChat,\n  [INTERNAL_LINK_TYPE.VOICE_CHAT]: InternalLink.InternalLinkVoiceChat,\n  [INTERNAL_LINK_TYPE.USER_PHONE_NUMBER]: InternalLink.InternalLinkUserPhoneNumber,\n  [INTERNAL_LINK_TYPE.INVOICE]: InternalLink.InternalLinkInvoice,\n  [INTERNAL_LINK_TYPE.EMOJI_SET]: InternalLink.InternalLinkEmojiSet,\n  [INTERNAL_LINK_TYPE.ATTACH_MENU_BOT]: InternalLink.InternalLinkAttachMenuBot,\n  [INTERNAL_LINK_TYPE.WEB_APP]: InternalLink.InternalLinkWebApp,\n  [INTERNAL_LINK_TYPE.ADD_LIST]: InternalLink.InternalLinkAddList,\n  [INTERNAL_LINK_TYPE.STORY]: InternalLink.InternalLinkStory,\n  [INTERNAL_LINK_TYPE.BOOST]: InternalLink.InternalLinkBoost,\n  [INTERNAL_LINK_TYPE.PREMIUM_FEATURES]: InternalLink.InternalLinkPremiumFeatures,\n  [INTERNAL_LINK_TYPE.GIFT_CODE]: InternalLink.InternalLinkGiftCode,\n  [INTERNAL_LINK_TYPE.BUSINESS_CHAT]: InternalLink.InternalLinkBusinessChat,\n  [INTERNAL_LINK_TYPE.STARS_TOPUP]: InternalLink.InternalLinkStarsTopup,\n  [INTERNAL_LINK_TYPE.SHARE]: InternalLink.InternalLinkShare,\n  [INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT]: InternalLink.InternalLinkUniqueStarGift,\n  [INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION]: InternalLink.InternalLinkStarGiftCollection,\n  [INTERNAL_LINK_TYPE.STORY_ALBUM]: InternalLink.InternalLinkStoryAlbum,\n  [INTERNAL_LINK_TYPE.INSTANT_VIEW]: InternalLink.InternalLinkInstantView,\n  [INTERNAL_LINK_TYPE.NEW]: InternalLink.InternalLinkNew,\n  [INTERNAL_LINK_TYPE.SETTINGS]: InternalLink.InternalLinkSettings,\n  [INTERNAL_LINK_TYPE.CONTACTS]: InternalLink.InternalLinkContacts,\n  [INTERNAL_LINK_TYPE.CONFERENCE_CALL]: InternalLink.InternalLinkConferenceCall,\n  [INTERNAL_LINK_TYPE.ADD_AI_STYLE]: InternalLink.InternalLinkAddAiStyle,\n};\n","import PopupElement from '.';\nimport filterUnique from '@helpers/array/filterUnique';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport shake from '@helpers/dom/shake';\nimport toggleDisability from '@helpers/dom/toggleDisability';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {ChatlistsChatlistInvite, ChatlistsChatlistUpdates, DialogFilter, Peer} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport I18n, {i18n, _i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport Button from '@components/button';\nimport wrapFolderTitle from '@components/wrappers/folderTitle';\nimport showLimitPopup from '@components/popups/limit';\n\nconst CLASS_NAME = 'popup-chatlist-invite';\nexport default class PopupSharedFolderInvite extends PopupElement {\n  private selector: AppSelectPeers;\n  private chatlistInvite: ChatlistsChatlistInvite;\n  private slug: string;\n  private filter: DialogFilter.dialogFilterChatlist;\n  private deleting: boolean;\n  private updating: boolean;\n\n  constructor(options: Partial<{\n    chatlistInvite: PopupSharedFolderInvite['chatlistInvite'],\n    slug: PopupSharedFolderInvite['slug'],\n    filter: PopupSharedFolderInvite['filter'],\n    deleting: PopupSharedFolderInvite['deleting'],\n    updating: PopupSharedFolderInvite['updating']\n  }>) {\n    super('popup-forward ' + CLASS_NAME, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      footer: true,\n      title: true,\n      withConfirm: true\n    });\n\n    safeAssign(this, options);\n\n    this.construct();\n  }\n\n  public async construct() {\n    const n = document.createElement('div');\n    n.classList.add('menu-horizontal-scrollable');\n\n    const nav = document.createElement('nav');\n    nav.classList.add('menu-horizontal-div');\n\n    const {chatlistInvite, deleting, updating} = this;\n    const isAlready = chatlistInvite?._ === 'chatlists.chatlistInviteAlready';\n    const isJoining = isAlready && !!chatlistInvite.missing_peers.length;\n    const filter = this.filter ??= isAlready ? await this.managers.filtersStorage.getFilter(chatlistInvite.filter_id) as DialogFilter.dialogFilterChatlist : undefined;\n\n    this.title.append(i18n(deleting ? 'SharedFolder.Link.TitleRemove' : (isJoining ? 'SharedFolder.Link.TitleAdd' : 'SharedFolder.Link.Title')));\n\n    let leaveSuggestionsPeerIds: PeerId[];\n    if(deleting) {\n      const peers = await this.managers.filtersStorage.getLeaveChatlistSuggestions(this.filter.id);\n      leaveSuggestionsPeerIds = peers.map((peer) => getPeerId(peer));\n    }\n\n    const makeItem = () => {\n      const item = document.createElement('div');\n      item.classList.add('menu-horizontal-div-item');\n      const i = document.createElement('i');\n      i.classList.add('menu-horizontal-div-item-background');\n      const span = document.createElement('span');\n      span.classList.add('menu-horizontal-div-item-span');\n      item.append(i, span);\n      nav.append(item);\n      return span;\n    };\n\n    makeItem().append(i18n('FilterAllChats'));\n    const activeItem = makeItem();\n    activeItem.parentElement.classList.add('active');\n    activeItem.append(\n      await wrapFolderTitle(filter ? filter.title : (chatlistInvite as ChatlistsChatlistInvite.chatlistsChatlistInvite).title, this.middlewareHelper.get())\n    );\n    makeItem().append(i18n('FilterPersonal'));\n\n    const shadow = document.createElement('div');\n    shadow.classList.add('inner-shadow', 'inner-shadow-inset');\n\n    n.append(nav, shadow);\n\n    const description = document.createElement('div');\n    description.classList.add(CLASS_NAME + '-description', 'subtitle');\n    let descriptionAddI18n: I18n.IntlElement, descriptionAddTitle: HTMLElement;\n    if(deleting) {\n      _i18n(description, 'SharedFolder.Link.DescriptionRemove', [await wrapFolderTitle(filter.title, this.middlewareHelper.get())]);\n    } else if(!isJoining) {\n      _i18n(description, isAlready ? 'SharedFolder.Link.DescriptionAlready' : 'SharedFolder.Link.Description');\n    } else {\n      descriptionAddI18n = new I18n.IntlElement();\n      descriptionAddTitle = document.createElement('span');\n      descriptionAddTitle.append(await wrapFolderTitle(filter.title, this.middlewareHelper.get()));\n    }\n\n    const counterI18n = new I18n.IntlElement();\n\n    const onSelectionChange = (length: number) => {\n      if(alreadyPeerIds && isJoining) {\n        length = Math.max(0, length - alreadyPeerIds.length);\n      }\n\n      counterI18n.update({\n        key: deleting ? 'SharedFolder.Link.ChatsRemove' : (isJoining ? 'SharedFolder.Link.ChatsAdd' : (isAlready ? 'SharedFolder.Link.ChatsAlready' : 'SharedFolder.Link.Chats')),\n        args: [i18n('Chats', [length])]\n      });\n\n      selectAllI18n?.update({\n        key: (shouldDeselect = length === peerIds.length) ? 'DeselectAll' : 'SelectAll'\n      });\n\n      descriptionAddI18n?.update({\n        key: 'SharedFolder.Link.DescriptionAdd',\n        args: [i18n('Chats', [length]), descriptionAddTitle]\n      });\n\n      if(selectAllI18n) {\n        if(length) addFolderText.dataset.badge = '' + length;\n        addFolderText.classList.toggle('has-badge', !!length);\n      }\n\n      if(deleting) {\n        addFolderI18n.update({\n          key: length ? 'SharedFolder.Link.Remove' : 'SharedFolder.Link.TitleRemove'\n        });\n      }\n\n      if(!deleting) {\n        toggleDisability([this.btnConfirm], !length);\n      }\n    };\n\n    let shouldDeselect: boolean;\n    this.selector = new AppSelectPeers({\n      middleware: this.middlewareHelper.get(),\n      appendTo: this.body,\n      onChange: onSelectionChange,\n      onFirstRender: () => {\n        this.show();\n        this.selector.checkForTriggers(); // ! due to zero height before mounting\n      },\n      multiSelect: true,\n      noSearch: true,\n      sectionNameLangPackKey: counterI18n.element,\n      avatarSize: 'abitbigger',\n      managers: this.managers,\n      peerType: [],\n      getSubtitleForElement: async(peerId) => {\n        if(alreadyPeerIds?.includes(peerId)) {\n          const isBroadcast = await this.managers.appPeersManager.isBroadcast(peerId);\n          return i18n(isBroadcast ? 'SharedFolder.Link.ChannelAlready' : 'SharedFolder.Link.ChatAlready');\n        }\n      },\n      processElementAfter: (peerId, dialogElement) => {\n        if(alreadyPeerIds?.includes(peerId)) {\n          dialogElement.dom.containerEl.classList.add('already');\n        }\n      }\n    });\n\n    let selectAllI18n: I18n.IntlElement;\n    if(!isAlready || isJoining) {\n      selectAllI18n = new I18n.IntlElement();\n      selectAllI18n.element.classList.add('sidebar-left-section-name-right');\n      this.selector.section.title.append(selectAllI18n.element);\n\n      attachClickEvent(selectAllI18n.element, () => {\n        if(shouldDeselect) {\n          this.selector.removeBatch(peerIds);\n        } else {\n          this.selector.addBatch(peerIds);\n        }\n      }, {listenerSetter: this.listenerSetter});\n    }\n\n    let peerIds: PeerId[];\n    if(chatlistInvite) {\n      const peers = isJoining ? chatlistInvite.missing_peers : (isAlready ? chatlistInvite.already_peers : chatlistInvite.peers);\n      peerIds = peers.map((peer) => getPeerId(peer));\n    } else {\n      peerIds = filter.includePeerIds;\n    }\n\n    let alreadyPeerIds: PeerId[];\n    if(isAlready) {\n      alreadyPeerIds = chatlistInvite.already_peers.map((peer) => getPeerId(peer));\n    }\n\n    if(alreadyPeerIds) {\n      const _remove = this.selector.remove.bind(this.selector);\n      this.selector.remove = (...args) => {\n        const peerId = args[0].toPeerId();\n        if(alreadyPeerIds.includes(peerId)) {\n          const container = this.selector.getElementByKey(peerId);\n          shake(container);\n          return false;\n        }\n\n        return _remove(...args);\n      };\n    }\n\n    this.scrollable = this.selector.scrollable;\n    this.attachScrollableListeners();\n\n    this.scrollable.prepend(n, description);\n\n    this.btnConfirm.classList.add(`${CLASS_NAME}-button`);\n    const addFolderI18n = new I18n.IntlElement({\n      key: deleting ? 'SharedFolder.Link.Remove' : (isJoining ? 'SharedFolder.Link.Join' : (isAlready ? 'OK' : 'SharedFolder.Link.Title'))\n    });\n    const addFolderText = addFolderI18n.element;\n    addFolderText.classList.add(`${CLASS_NAME}-button-text`);\n    this.btnConfirm.append(addFolderText);\n    this.footer.append(this.btnConfirm);\n\n    attachClickEvent(this.btnConfirm, () => {\n      if(isAlready && !isJoining) {\n        this.hide();\n        return;\n      }\n\n      let promise: Promise<any>;\n\n      const toggle = toggleDisability([this.btnConfirm], true);\n\n      const peerIds = [...this.selector.selected] as PeerId[];\n      if(updating) {\n        promise = this.managers.filtersStorage.joinChatlistUpdates(this.filter.id, peerIds);\n      } else if(chatlistInvite) {\n        promise = this.managers.filtersStorage.joinChatlistInvite(\n          this.slug,\n          peerIds\n        ).catch((error: ApiError) => {\n          if(error.type === 'DIALOG_FILTERS_TOO_MUCH') {\n            showLimitPopup('folders');\n            this.hide();\n          } else {\n            throw error;\n          }\n        });\n      } else {\n        promise = this.managers.filtersStorage.leaveChatlist(this.filter.id, peerIds);\n      }\n\n      promise.then(() => {\n        this.hide();\n      }, (error: ApiError) => {\n        toggle();\n        throw error;\n      });\n    }, {listenerSetter: this.listenerSetter});\n\n    const totalPeerIds = alreadyPeerIds ? peerIds.concat(alreadyPeerIds) : peerIds;\n    const initial = deleting ? leaveSuggestionsPeerIds : totalPeerIds\n    this.selector.addInitial(initial);\n    this.selector.renderResultsFunc(deleting ? filterUnique(leaveSuggestionsPeerIds.concat(totalPeerIds)) : totalPeerIds);\n\n    if(!initial.length) {\n      onSelectionChange(0);\n    }\n    // if(isAlready && !isJoining) {\n    //   this.selector.list.classList.add('disable-hover');\n    // }\n\n    this.body.after(this.footer);\n  }\n}\n","import wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport matchTelegramUrlHost from '@lib/richTextProcessor/matchTelegramUrlHost';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport parseUriParams from '@helpers/string/parseUriParams';\n\n// * https://core.telegram.org/api/links\n\ntype InternalLinkAnchorType =\n  | 'showMaskedAlert'\n  | 'execBotCommand'\n  | 'searchByHashtag'\n  | 'addstickers'\n  | 'im'\n  | 'resolve'\n  | 'privatepost'\n  | 'voicechat'\n  | 'call'\n  | 'joinchat'\n  | 'join'\n  | 'invoice'\n  | 'addemoji'\n  | 'setMediaTimestamp'\n  | 'addlist'\n  | 'boost'\n  | 'premium_offer'\n  | 'giftcode'\n  | 'm'\n  | 'message'\n  | 'stars_topup'\n  | 'share'\n  | 'msg_url'\n  | 'nft'\n  | 'iv'\n  | 'new'\n  | 'settings'\n  | 'contacts'\n  | 'addstyle'\n;\n\nexport const UNSAFE_ANCHOR_LINK_TYPES: Set<InternalLinkAnchorType> = new Set([\n  'showMaskedAlert',\n  'execBotCommand'\n]);\n\nexport default function addAnchorListener<\n  Params extends {\n    pathnameParams?: any,\n    uriParams?: any\n  }\n>(options: {\n  name: InternalLinkAnchorType,\n  protocol?: 'tg',\n  callback: (params: Params & {element?: HTMLAnchorElement, masked?: boolean, event?: Event}) => any,\n  noPathnameParams?: boolean,\n  noUriParams?: boolean,\n  noCancelEvent?: boolean\n}) {\n  (window as any)[(options.protocol ? options.protocol + '_' : '') + options.name] = (element?: HTMLAnchorElement, e?: Event) => {\n    !options.noCancelEvent && cancelEvent(null);\n\n    let href = element.href;\n    if(!href) {\n      return;\n    }\n\n    let pathnameParams: any[];\n    let uriParams: any;\n\n    const u = new URL(href);\n    const match = matchTelegramUrlHost(u);\n    if(match?.prefix) {\n      u.pathname = match.prefix + (u.pathname === '/' ? '' : u.pathname);\n      href = u.toString();\n    }\n\n    if(!options.noPathnameParams) pathnameParams = new URL(href).pathname.split('/').slice(1);\n    if(!options.noUriParams) uriParams = parseUriParams(href);\n\n    const masked = element.href !== wrapUrl(element.textContent).url && element.getAttribute('safe') === null;\n    const result = options.callback({\n      ...{pathnameParams, uriParams} as Params,\n      element,\n      masked,\n      event: e || window.event\n    });\n\n    if(!e?.isTrusted) {\n      return result;\n    }\n  };\n}\n","// https://github.com/tdlib/td/blob/c95598e5e1493881d31211c1329bdbe4630f6136/td/telegram/misc.cpp#L246\nexport function isUsernameValid(username: string) {\n  if(username.length < 3 || username.length > 32) {\n    return false;\n  }\n\n  if(!/[a-zA-Z]/.test(username.charAt(0))) {\n    return false;\n  }\n\n  for(let i = 0; i < username.length; i++) {\n    const c = username.charAt(i);\n    if(!/[a-zA-Z0-9_]/.test(c)) {\n      return false;\n    }\n  }\n\n  if(username.charAt(username.length - 1) === '_') {\n    return false;\n  }\n\n  for(let i = 1; i < username.length; i++) {\n    if(username.charAt(i - 1) === '_' && username.charAt(i) === '_') {\n      return false;\n    }\n  }\n\n  return true;\n}\n\nexport function isWebAppNameValid(name: string) {\n  return name.length >= 3 && isUsernameValid(name);\n}\n","import type {Message} from '@layer';\n\n/** A message's identity across peers: its peer id and its mid in one key. */\nexport type FullMid = `${PeerId}_${number}`;\n\nexport function makeFullMid(peerId: PeerId | Message.message | Message.messageService, mid?: number): FullMid {\n  if(typeof(peerId) === 'object') {\n    mid = peerId.mid;\n    peerId = peerId.peerId;\n  }\n\n  return `${peerId}_${mid}`;\n}\n\nexport function splitFullMid(fullMid: FullMid) {\n  const [peerId, mid] = fullMid.split('_');\n  return {peerId: peerId.toPeerId(), mid: +mid};\n}\n","import {createContext, useContext, ParentProps} from 'solid-js';\n\ntype PromiseCollectorContextValue = {\n  collect: (promise: Promise<any>) => void;\n};\n\nconst PromiseCollectorContext = createContext<PromiseCollectorContextValue>({\n  collect: () => {}\n});\n\ntype PromiseCollectorProps = {\n  onCollect: (promise: Promise<any>) => void;\n};\n\nexport const PromiseCollector = (props: ParentProps<PromiseCollectorProps>) => {\n  return (\n    <PromiseCollectorContext.Provider value={{collect: props.onCollect}}>\n      {props.children}\n    </PromiseCollectorContext.Provider>\n  );\n};\n\nPromiseCollector.createHelper = () => {\n  const promises: Promise<any>[] = [];\n\n  let collectPromise = (promise: Promise<any>) => {\n    promises.push(promise);\n  };\n\n  return {\n    onCollect: (promise: Promise<any>) => collectPromise(promise),\n    await: () => {\n      collectPromise = () => {}; // lose reference to the promises array\n      return Promise.all(promises);\n    }\n  };\n};\n\nexport const usePromiseCollector = () => useContext(PromiseCollectorContext);\n","import {createContext, ParentComponent, useContext} from 'solid-js';\nimport {InstanceOf} from '@types';\nimport type SliderSuperTab from '@components/sliderTab';\nimport {ProvidedTabs} from '@components/solidJsTabs/providedTabs';\n\n\nconst SuperTabContext = createContext<[SliderSuperTab, ProvidedTabs]>();\n\ntype SuperTabProviderProps = {\n  self: SliderSuperTab;\n};\n\nexport const SuperTabProvider: ParentComponent<SuperTabProviderProps> & {\n  allTabs: ProvidedTabs;\n} = (props) => {\n  return (\n    <SuperTabContext.Provider value={[props.self, SuperTabProvider.allTabs]}>\n      {props.children}\n    </SuperTabContext.Provider>\n  );\n};\n\nSuperTabProvider.allTabs = {} as ProvidedTabs; // will get reassigned in index.ts\n\nexport const useSuperTab = <TabClass extends typeof SliderSuperTab>() =>\n  useContext(SuperTabContext) as [InstanceOf<TabClass>, ProvidedTabs];\n","import {Component} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport {LangPackKey} from '@lib/langPack';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {InstanceOf} from '@types';\nimport {SliderSuperTab} from '@components/slider';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {EventListenerListeners} from '@helpers/eventListenerBase';\nimport {PromiseCollector} from '@components/solidJsTabs/promiseCollector';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\n\n\ntype ScaffoldSolidJSTabArgs<Payload> = {\n  title: LangPackKey | ((payload: Payload) => LangPackKey);\n  getComponentModule: () => Promise<{default: Component}>;\n  onOpenAfterTimeout?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n  onClose?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n  onCloseAfterTimeout?: (this: InstanceOf<ScaffoledClass<Payload>>) => void;\n};\n\ntype ScaffoledClass<Payload = void> = new (...args: ConstructorParameters<typeof SliderSuperTab>) => SliderSuperTab & {\n  payload: Payload;\n  init(payload: Payload, overrideTitle?: LangPackKey): Promise<void>;\n};\n\nexport function scaffoldSolidJSTab<Payload = void>({\n  title,\n  getComponentModule,\n  onOpenAfterTimeout,\n  onClose,\n  onCloseAfterTimeout\n}: ScaffoldSolidJSTabArgs<Payload>): ScaffoledClass<Payload> {\n  return class extends SliderSuperTab {\n    public payload: Payload;\n\n    private dispose?: () => void;\n\n    public async init(payload: Payload, overrideTitle?: LangPackKey) {\n      this.setTitle(overrideTitle || (typeof title === 'function' ? title(payload) : title));\n      this.payload = payload;\n\n      const div = document.createElement('div');\n\n      const {default: Component} = await getComponentModule();\n\n      const promiseCollectorHelper = PromiseCollector.createHelper();\n\n      this.dispose = render(() => (\n        <SolidJSHotReloadGuardProvider>\n          <PromiseCollector onCollect={promiseCollectorHelper.onCollect}>\n            <SuperTabProvider self={this}>\n              <Component />\n            </SuperTabProvider>\n          </PromiseCollector>\n        </SolidJSHotReloadGuardProvider>\n      ), div);\n\n      this.scrollable.append(div);\n\n      await promiseCollectorHelper.await();\n    }\n\n    protected onClose() {\n      onClose?.call?.(this);\n    }\n\n    protected onCloseAfterTimeout() {\n      onCloseAfterTimeout?.call?.(this);\n      this.dispose?.();\n      super.onCloseAfterTimeout();\n    }\n\n    protected onOpenAfterTimeout() {\n      onOpenAfterTimeout?.call?.(this);\n    }\n  } as ScaffoledClass<Payload>;\n}\n\n\ntype ScaffoldSolidJSTabEventableArgs<Payload> = {\n  title: LangPackKey | ((payload: Payload) => LangPackKey);\n  getComponentModule: () => Promise<{default: Component}>;\n  onOpenAfterTimeout?: (this: InstanceOf<ScaffoledEventableClass<Payload>>) => void;\n};\n\ntype ScaffoledEventableClass<Payload = void, Events extends EventListenerListeners = {}> =\n  new (...args: ConstructorParameters<typeof SliderSuperTab>) => SliderSuperTabEventable<Events> & {\n    payload: Payload;\n    init(payload: Payload, overrideTitle?: LangPackKey): Promise<void>;\n  };\n\n/**\n * Same as {@link scaffoldSolidJSTab} but the tab instance is a\n * {@link SliderSuperTabEventable}, so the rendered Solid component can dispatch\n * through (and external openers can listen on) `tab.eventListener` — needed by\n * e.g. PrivacySection, which saves on the tab's `destroy` event.\n */\nexport function scaffoldSolidJSTabEventable<Payload = void, Events extends EventListenerListeners = {}>({\n  title,\n  getComponentModule,\n  onOpenAfterTimeout\n}: ScaffoldSolidJSTabEventableArgs<Payload>): ScaffoledEventableClass<Payload, Events> {\n  return class extends SliderSuperTabEventable<Events> {\n    public payload: Payload;\n\n    private dispose?: () => void;\n\n    public async init(payload: Payload, overrideTitle?: LangPackKey) {\n      this.setTitle(overrideTitle || (typeof title === 'function' ? title(payload) : title));\n      this.payload = payload;\n\n      const div = document.createElement('div');\n\n      const {default: Component} = await getComponentModule();\n\n      const promiseCollectorHelper = PromiseCollector.createHelper();\n\n      this.dispose = render(() => (\n        <SolidJSHotReloadGuardProvider>\n          <PromiseCollector onCollect={promiseCollectorHelper.onCollect}>\n            <SuperTabProvider self={this}>\n              <Component />\n            </SuperTabProvider>\n          </PromiseCollector>\n        </SolidJSHotReloadGuardProvider>\n      ), div);\n\n      this.scrollable.append(div);\n\n      await promiseCollectorHelper.await();\n    }\n\n    public onCloseAfterTimeout() {\n      this.dispose?.();\n      return super.onCloseAfterTimeout();\n    }\n\n    protected onOpenAfterTimeout() {\n      onOpenAfterTimeout?.call?.(this);\n    }\n  } as ScaffoledEventableClass<Payload, Events>;\n}\n","import tsNow from '@helpers/tsNow';\nimport {ChatInviteImporter, ExportedChatInvite} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport hasRights from '@lib/appManagers/utils/chats/hasRights';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport {InviteLink} from '@components/sidebarLeft/tabs/inviteLink';\n\nexport type ChatInvite = ExportedChatInvite.chatInviteExported;\n\nexport type ChatInviteActions = {\n  revokeLink: () => void,\n  deleteLink: () => void,\n  editLink: () => void\n};\n\nexport function isActiveInvite(invite: ChatInvite) {\n  if(invite.pFlags.revoked) {\n    return false;\n  }\n\n  if(invite.expire_date && invite.expire_date <= tsNow(true)) {\n    return false;\n  }\n\n  if(invite.usage_limit && invite.usage_limit <= (invite.usage || 0)) {\n    return false;\n  }\n\n  return true;\n}\n\nexport class ChatInviteLink extends InviteLink {\n  public subtitle: HTMLElement;\n\n  constructor(public options: ConstructorParameters<typeof InviteLink>[0] & {\n    actions: ChatInviteActions,\n    withSubtitle?: boolean\n  }) {\n    super({\n      ...options\n    });\n\n    if(options.withSubtitle) {\n      this.subtitle = document.createElement('div');\n      this.subtitle.classList.add('invite-link-subtitle', 'hide');\n      this.container.append(this.subtitle);\n    }\n  }\n\n  public setChatInvite(chatInvite: ChatInvite | string) {\n    const isUsername = typeof(chatInvite) === 'string';\n    const username = typeof(chatInvite) === 'string' ? chatInvite : undefined;\n    this.setUrl(isUsername ? 't.me/' + username : chatInvite.link);\n\n    if(this.subtitle) {\n      if(!isUsername && chatInvite?.usage) {\n        this.subtitle.replaceChildren(i18n('InviteLink.JoinedNew', [chatInvite.usage]));\n      }\n\n      this.subtitle.classList.toggle('hide', isUsername || !chatInvite?.usage);\n    }\n\n    let hasSomething: LangPackKey;\n    if(!isUsername) {\n      if(chatInvite.pFlags.revoked) {\n        this.onButtonClick = () => this.options.actions.deleteLink();\n        hasSomething = 'DeleteLink';\n      } else if(!isActiveInvite(chatInvite)) {\n        this.onButtonClick = () => this.options.actions.editLink();\n        hasSomething = 'InviteLinks.Reactivate';\n      }\n    }\n\n    if(!hasSomething) {\n      hasSomething = 'ShareLink';\n      this.onButtonClick = undefined;\n    }\n\n    this.buttonText.replaceChildren(i18n(hasSomething));\n  }\n}\n\nexport function getImportersLoader({\n  chatId,\n  managers,\n  link,\n  requested\n}: {\n  chatId: ChatId,\n  managers: AppManagers,\n  link?: string,\n  requested?: boolean\n}) {\n  const importers: ChatInviteImporter[] = [];\n  const importersMap: Map<PeerId, ChatInviteImporter> = new Map();\n  let lastQuery = '';\n  const load: AppSelectPeers['getMoreCustom'] = async(q) => {\n    if(lastQuery !== q) {\n      importers.length = 0;\n      importersMap.clear();\n      lastQuery = q;\n    }\n\n    const limit = 50;\n    const lastImporter = importers[importers.length - 1];\n    const result = await managers.appChatInvitesManager.getChatInviteImporters({\n      chatId,\n      limit,\n      link,\n      requested,\n      offsetDate: lastImporter?.date,\n      offsetUserId: lastImporter?.user_id,\n      q\n    });\n\n    importers.push(...result.importers);\n\n    return {\n      result: result.importers.map((importer) => {\n        const peerId = importer.user_id.toPeerId(false);\n        importersMap.set(peerId, importer);\n        return peerId;\n      }),\n      isEnd: result.importers.length < limit\n    };\n  };\n\n  const deleteImporter = (peerId: PeerId) => {\n    importers.splice(importers.findIndex((importer) => importer.user_id.toPeerId(false) === peerId), 1);\n    importersMap.delete(peerId);\n  };\n\n  return {\n    importers,\n    importersMap,\n    load,\n    deleteImporter\n  };\n}\n\nexport function getChatInviteLinksInitArgs(chatId: ChatId, adminId?: UserId) {\n  return {\n    animationData: !adminId && lottieLoader.loadAnimationFromURLManually('UtyanLinks'),\n    invites: rootScope.managers.appChatInvitesManager.getExportedChatInvites({chatId, adminId}),\n    invitesRevoked: rootScope.managers.appChatInvitesManager.getExportedChatInvites({chatId, adminId, revoked: true}),\n    adminsInvites: !adminId && hasRights(apiManagerProxy.getChat(chatId), 'change_type') && rootScope.managers.appChatInvitesManager.getAdminsWithInvites(chatId),\n    chatFull: rootScope.managers.appProfileManager.getChatFull(chatId)\n  };\n}\n","import {DialogFilter} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport confirmationPopup from '@components/confirmationPopup';\nimport PopupElement from '@components/popups';\nimport PopupSharedFolderInvite from '@components/popups/sharedFolderInvite';\n\nexport function getEditFolderInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('Folders_2')\n  };\n}\n\nexport async function deleteFolder(filterId: number) {\n  const filter = await rootScope.managers.filtersStorage.getFilter(filterId);\n  if(filter?._ === 'dialogFilterChatlist' && !filter.pFlags.has_my_invites) {\n    PopupElement.createPopup(PopupSharedFolderInvite, {\n      filter,\n      deleting: true\n    });\n\n    return;\n  }\n\n  await confirmationPopup({\n    titleLangKey: 'ChatList.Filter.Confirm.Remove.Header',\n    descriptionLangKey: (filter as DialogFilter.dialogFilterChatlist).pFlags.has_my_invites ? 'RemoveSharedFolder' : 'ChatList.Filter.Confirm.Remove.Text',\n    button: {\n      langKey: 'Delete',\n      isDanger: true\n    }\n  });\n\n  return rootScope.managers.filtersStorage.updateDialogFilter(\n    {\n      _: 'dialogFilter',\n      id: filterId\n    } as DialogFilter.dialogFilter,\n    true\n  );\n}\n","import {CancellablePromise} from '@helpers/cancellablePromise';\nimport {AccountPasskeys, AccountPassword, Authorization, ChannelParticipant, Chat, ChatAdminRights, ChatParticipant, ConnectedBot, DialogFilter, ExportedChatlistInvite, GlobalPrivacySettings, Passkey, WebAuthorization} from '@layer';\nimport type SidebarSlider from '@components/slider';\nimport type {SliderSuperTab} from '@components/slider';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport type {MyDialogFilter} from '@lib/storages/filters';\nimport {FormatterArgument, LangPackKey} from '@lib/langPack';\nimport type {PasscodeActions} from '@lib/passcode/actions';\nimport {InstanceOf} from '@types';\nimport {SetStoreFunction} from 'solid-js/store';\nimport {scaffoldSolidJSTab, scaffoldSolidJSTabEventable} from '@components/solidJsTabs/scaffoldSolidJSTab';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\nimport rootScope from '@lib/rootScope';\nimport type {EditProfileTabPayload} from '@components/sidebarLeft/tabs/editProfile';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {ChatInvite, ChatInviteActions, getChatInviteLinksInitArgs} from '@components/sidebarRight/tabs/chatInviteLinkShared';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport {deleteFolder as deleteEditFolder, getEditFolderInitArgs} from '@components/sidebarLeft/tabs/editFolderShared';\nimport type {\n  FilterPeerTypeByFunc,\n  SelectSearchPeerType\n} from '@components/appSelectPeers';\nimport type {IsPeerType} from '@appManagers/appPeersManager';\nimport type {AppChatFull} from '@appManagers/appProfileManager';\n\n\nexport const AppPasscodeLockTab =\n  scaffoldSolidJSTab({\n    title: 'PasscodeLock.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/passcodeLock/mainTab'),\n    onOpenAfterTimeout: async function() {\n      // Remove the previous enter password tab\n      this.slider.sliceTabsUntilTab(\n        SuperTabProvider.allTabs.AppPrivacyAndSecurityTab,\n        this\n      );\n    }\n  });\n\n\ntype AppPasscodeEnterPasswordTabPayload = {\n  onSubmit: (passcode: string, tab: InstanceOf<typeof AppPasscodeEnterPasswordTab>, passcodeActions: PasscodeActions) => MaybePromise<void>;\n\n  inputLabel: LangPackKey;\n  buttonText: LangPackKey;\n};\n\nexport const AppPasscodeEnterPasswordTab =\n  scaffoldSolidJSTab<AppPasscodeEnterPasswordTabPayload>({\n    title: 'PasscodeLock.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/passcodeLock/enterPasswordTab')\n  });\n\n\ntype AppPrivacyMessagesTabPayload = {\n  onSaved: (globalPrivacy: CancellablePromise<GlobalPrivacySettings.globalPrivacySettings>) => void;\n};\n\nexport const AppPrivacyMessagesTab =\n  scaffoldSolidJSTab<AppPrivacyMessagesTabPayload>({\n    title: 'PrivacyMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/messages/tab')\n  });\n\n\ntype AppDirectMessagesTabPayload = {\n  chat: Chat.channel;\n};\n\nexport const AppDirectMessagesTab =\n  scaffoldSolidJSTab<AppDirectMessagesTabPayload>({\n    title: 'ChannelDirectMessages.Settings.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/channelDirectMessages')\n  });\n\n\nexport const AppNotificationsTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.NotificationSettingsViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/notifications')\n  });\n\n\nexport function getEditProfileInitArgs(overwriteConnectedBot?: boolean): EditProfileTabPayload {\n  return {\n    bioMaxLength: rootScope.managers.apiManager.getLimit('bio'),\n    user: rootScope.managers.appUsersManager.getSelf(),\n    userFull: rootScope.managers.appProfileManager.getProfile(rootScope.myId.toUserId()),\n    connectedBot: rootScope.managers.appBusinessManager.getConnectedBot(overwriteConnectedBot)\n  };\n}\n\nexport const AppEditProfileTab =\n  scaffoldSolidJSTab<EditProfileTabPayload>({\n    title: 'EditAccount.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/editProfile')\n  });\n(AppEditProfileTab as any).noSame = true;\n\n\ntype AppChatAutomationTabPayload = {\n  connectedBot?: ConnectedBot.connectedBot\n};\n\nexport const AppChatAutomationTab =\n  scaffoldSolidJSTab<AppChatAutomationTabPayload>({\n    title: 'ChatAutomation.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/chatAutomation')\n  });\n(AppChatAutomationTab as any).noSame = true;\n\n\nexport const AppKeyboardShortcutsTab =\n  scaffoldSolidJSTab({\n    title: 'KeyboardShortcuts.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/keyboardShortcuts')\n  });\n\n\ntype AppAdminRecentActionsTabPayload = {\n  channelId: ChatId;\n  isBroadcast: boolean;\n};\n\nexport const AppAdminRecentActionsTab =\n  scaffoldSolidJSTab<AppAdminRecentActionsTabPayload>({\n    title: 'RecentActions',\n    getComponentModule: () => import('../sidebarRight/tabs/adminRecentActions')\n  });\n\n\ntype AppPasskeysTabPayload = {\n  passkeys: Passkey[],\n  setPasskeys: SetStoreFunction<Passkey[]>\n};\n\nexport const AppPasskeysTab =\n  scaffoldSolidJSTab<AppPasskeysTabPayload>({\n    title: 'Privacy.Passkeys',\n    getComponentModule: () => import('../sidebarLeft/tabs/passkeys')\n  });\n\ntype AppMessagesAutoDeleteTabPayload = {\n  period: number;\n  onSaved: (period: number) => void;\n};\n\nexport const AppMessagesAutoDeleteTab =\n  scaffoldSolidJSTab<AppMessagesAutoDeleteTabPayload>({\n    title: 'AutoDeleteMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDeleteMessages')\n  });\n\nexport const AppArchiveSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'ArchiveSettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/archiveSettingsTab')\n  });\n\nexport const AppGeneralSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.GeneralSettingsViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/generalSettings')\n  });\n\n\nexport const AppChatBackgroundTab =\n  scaffoldSolidJSTab({\n    title: 'ChatBackground',\n    getComponentModule: () => import('../sidebarLeft/tabs/background')\n  });\n\n\nexport const AppLanguageTab =\n  scaffoldSolidJSTab({\n    title: 'Telegram.LanguageViewController',\n    getComponentModule: () => import('../sidebarLeft/tabs/language')\n  });\n\n\nexport const AppSpeakersAndCameraTab =\n  scaffoldSolidJSTab({\n    title: 'AccountSettings.SpeakersAndCamera',\n    getComponentModule: () => import('../sidebarLeft/tabs/speakersAndCamera')\n  });\n\n\nexport const AppSettingsTab =\n  scaffoldSolidJSTab({\n    title: 'Settings',\n    getComponentModule: () => import('../sidebarLeft/tabs/settings')\n  });\n\n\nexport const AppQuickReactionTab =\n  scaffoldSolidJSTab({\n    title: 'DoubleTapSetting',\n    getComponentModule: () => import('../sidebarLeft/tabs/quickReaction')\n  });\n\n\nexport const AppStickersAndEmojiTab =\n  scaffoldSolidJSTab({\n    title: 'StickersName',\n    getComponentModule: () => import('../sidebarLeft/tabs/stickersAndEmoji')\n  });\n\n\nexport const AppContactsTab =\n  scaffoldSolidJSTab({\n    title: 'Contacts',\n    getComponentModule: () => import('../sidebarLeft/tabs/contacts')\n  });\n(AppContactsTab as any).noSame = true;\n\n\nexport const AppPowerSavingTab =\n  scaffoldSolidJSTab({\n    title: 'LiteMode.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/powerSaving')\n  });\n\n\ntype AppBlockedUsersTabPayload = {\n  peerIds: PeerId[];\n};\n\nexport const AppBlockedUsersTab =\n  scaffoldSolidJSTab<AppBlockedUsersTabPayload>({\n    title: 'BlockedUsers',\n    getComponentModule: () => import('../sidebarLeft/tabs/blockedUsers'),\n    onOpenAfterTimeout: function() {\n      this.scrollable.onScroll();\n    }\n  });\n\n\ntype AppNewChannelTabPayload = {\n  onCreate?: (chatId: ChatId) => MaybePromise<void>,\n  openAfter?: boolean\n};\n\nexport const AppNewChannelTab =\n  scaffoldSolidJSTab<AppNewChannelTabPayload>({\n    title: 'NewChannel',\n    getComponentModule: () => import('../sidebarLeft/tabs/newChannel')\n  });\n(AppNewChannelTab as any).noSame = true;\n\n\nexport const AppBackgroundColorTab =\n  scaffoldSolidJSTab({\n    title: 'SetColor',\n    getComponentModule: () => import('../sidebarLeft/tabs/backgroundColor')\n  });\n\n\ntype AppNewGroupTabPayload = {\n  peerIds: PeerId[],\n  isGeoChat?: boolean,\n  onCreate?: (chatId: ChatId) => MaybePromise<void>,\n  openAfter?: boolean,\n  title?: string,\n  asChannel?: boolean\n};\n\nexport const AppNewGroupTab =\n  scaffoldSolidJSTab<AppNewGroupTabPayload>({\n    title: 'NewGroup',\n    getComponentModule: () => import('../sidebarLeft/tabs/newGroup')\n  });\n(AppNewGroupTab as any).noSame = true;\n\n\n// ─── Privacy sub-tabs (eventable: PrivacySection saves on the tab's destroy event) ───\n\nexport const AppPrivacyAboutTab =\n  scaffoldSolidJSTabEventable({\n    title: 'UserBio',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/about')\n  });\n\nexport const AppPrivacyCallsTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.VoiceCalls',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/calls')\n  });\n\nexport const AppPrivacyVoicesTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyVoiceMessages',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/voices')\n  });\n\nexport const AppPrivacyAddToGroupsTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.Groups',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/addToGroups')\n  });\n\nexport const AppPrivacyBirthdayTab =\n  scaffoldSolidJSTabEventable({\n    title: 'Birthday',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/birthday')\n  });\n\nexport const AppPrivacyForwardMessagesTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySettings.Forwards',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/forwardMessages')\n  });\n\nexport const AppPrivacyProfilePhotoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyProfilePhoto',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/profilePhoto')\n  });\n\nexport const AppPrivacySavedMusicTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacySavedMusic',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/savedMusic')\n  });\n\nexport const AppPrivacyPhoneNumberTab =\n  scaffoldSolidJSTabEventable({\n    title: 'PrivacyPhone',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/phoneNumber')\n  });\n\ntype AppPrivacyGlobalTabEvents = {\n  privacy: (globalPrivacy: Promise<GlobalPrivacySettings>) => void\n};\n\nexport const AppPrivacyLastSeenTab =\n  scaffoldSolidJSTabEventable<GlobalPrivacySettings, AppPrivacyGlobalTabEvents>({\n    title: 'PrivacyLastSeen',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/lastSeen')\n  });\n\nexport const AppPrivacyGiftsTab =\n  scaffoldSolidJSTabEventable<GlobalPrivacySettings, AppPrivacyGlobalTabEvents>({\n    title: 'PrivacyGifts',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacy/gifts')\n  });\n\n\ntype AppActiveSessionsTabPayload = {\n  authorizations: Authorization.authorization[];\n  connectedBot?: ConnectedBot.connectedBot;\n  /** `account.authorizations.authorization_ttl_days` — 0 while unknown. */\n  ttlDays?: number;\n};\n\nexport const AppActiveSessionsTab =\n  scaffoldSolidJSTabEventable<AppActiveSessionsTabPayload>({\n    title: 'SessionsTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/activeSessions')\n  });\n\ntype AppSessionTabPayload = {\n  authorization: Authorization.authorization;\n  /**\n   * Confirms + terminates the session; resolves to whether it was terminated.\n   * Absent for the current session, which cannot terminate itself.\n   */\n  onTerminate?: () => Promise<boolean>;\n  /** Reports a flag flipped through account.changeAuthorizationSettings back to the list. */\n  onSettingsChanged?: (authorization: Authorization.authorization) => void;\n};\n\nexport const AppSessionTab =\n  scaffoldSolidJSTabEventable<AppSessionTabPayload>({\n    title: 'AuthSessions.View.Device',\n    getComponentModule: () => import('../sidebarLeft/tabs/session')\n  });\n\ntype AppConnectedBotSessionTabPayload = {\n  connectedBot: ConnectedBot.connectedBot;\n};\n\nexport const AppConnectedBotSessionTab =\n  scaffoldSolidJSTabEventable<AppConnectedBotSessionTabPayload>({\n    title: 'ChatAutomation.Session',\n    getComponentModule: () => import('../sidebarLeft/tabs/connectedBotSession')\n  });\n\nexport const AppActiveWebSessionsTab =\n  scaffoldSolidJSTabEventable<WebAuthorization[]>({\n    title: 'WebSessionsTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/activeWebSessions')\n  });\n\n\n// ─── Data and storage + its auto-download sub-tabs (all eventable) ───\n\nexport const AppAutoDownloadPhotoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadPhotos',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/photo')\n  });\n\nexport const AppAutoDownloadVideoTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadVideos',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/video')\n  });\n\nexport const AppAutoDownloadFileTab =\n  scaffoldSolidJSTabEventable({\n    title: 'AutoDownloadFiles',\n    getComponentModule: () => import('../sidebarLeft/tabs/autoDownload/file')\n  });\n\nexport const AppDataAndStorageTab =\n  scaffoldSolidJSTabEventable({\n    title: 'DataSettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/dataAndStorage')\n  });\n\n\n// ─── Right sidebar ───\n\ntype AppRemovedUsersTabPayload =\n  | {chatId: ChatId}\n  | {communityId: ChatId};\n\nexport const AppRemovedUsersTab =\n  scaffoldSolidJSTabEventable<AppRemovedUsersTabPayload>({\n    title: 'ChannelBlacklist',\n    getComponentModule: () => import('../sidebarRight/tabs/removedUsers')\n  });\n\nexport const AppGifsTab =\n  scaffoldSolidJSTab({\n    title: 'SearchGifsTitle',\n    getComponentModule: () => import('../sidebarRight/tabs/gifs')\n  });\n\nexport const AppChatRequestsTab =\n  scaffoldSolidJSTabEventable<ChatId, {finish: (changedLength: number) => void}>({\n    title: 'MemberRequests',\n    getComponentModule: () => import('../sidebarRight/tabs/chatRequests')\n  });\n\nexport const AppChatReactionsTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId}>({\n    title: 'Reactions',\n    getComponentModule: () => import('../sidebarRight/tabs/chatReactions')\n  });\n\nexport const AppChatMembersTab =\n  scaffoldSolidJSTabEventable<ChatId>({\n    title: 'GroupMembers',\n    getComponentModule: () => import('../sidebarRight/tabs/chatMembers')\n  });\n\ntype AppGroupStickersTabPayload = {\n  chatId: ChatId,\n  isEmoji?: boolean\n};\n\nexport const AppGroupStickersTab =\n  scaffoldSolidJSTab<AppGroupStickersTabPayload>({\n    title: ({isEmoji}) => isEmoji ? 'GroupEmojiPack' : 'GroupStickers',\n    getComponentModule: () => import('../sidebarRight/tabs/groupStickers')\n  });\n\ntype AppChatAdministratorsTabPayload =\n  | {chatId: ChatId}\n  | {communityId: ChatId};\n\nexport const AppChatAdministratorsTab =\n  scaffoldSolidJSTabEventable<AppChatAdministratorsTabPayload>({\n    title: 'PeerInfo.Administrators',\n    getComponentModule: () => import('../sidebarRight/tabs/chatAdministrators')\n  });\n\nexport const AppEditBotTab =\n  scaffoldSolidJSTab<PeerId>({\n    title: 'EditBot.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/editBot')\n  });\n\nexport const AppEditContactTab =\n  scaffoldSolidJSTab<PeerId>({\n    title: 'Edit',\n    getComponentModule: () => import('../sidebarRight/tabs/editContact')\n  });\n\nexport const AppEditTopicTab =\n  scaffoldSolidJSTab<{peerId: PeerId, threadId?: number}>({\n    title: (p) => p.threadId ? 'ForumTopic.Title.Edit' : 'NewTopic',\n    getComponentModule: () => import('../sidebarRight/tabs/editTopic')\n  });\n\nexport const AppStickersTab =\n  scaffoldSolidJSTab({\n    title: 'StickersName',\n    getComponentModule: () => import('../sidebarRight/tabs/stickers')\n  });\n\nexport const AppChatDiscussionTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId, linkedChatId: ChatId}>({\n    title: 'DiscussionController.Channel.Title',\n    getComponentModule: () => import('../sidebarRight/tabs/chatDiscussion')\n  });\n\nexport const AppChatTypeTab =\n  scaffoldSolidJSTabEventable<{chatId: ChatId, chatFull: AppChatFull}>({\n    title: 'ChannelType',\n    getComponentModule: () => import('../sidebarRight/tabs/chatType')\n  });\n\ntype AppUserPermissionsChatPayload = {\n  participant: ChannelParticipant | ChatParticipant,\n  chatId: ChatId,\n  userId: UserId,\n  editingAdmin?: boolean,\n  initialAdminRights?: ChatAdminRights,\n  existingAdminRights?: ChatAdminRights,\n  addingBot?: {\n    startParam?: string,\n    sendStartAfterAdmin?: boolean,\n    existingAdmin?: boolean\n  }\n};\n\ntype AppUserPermissionsCommunityPayload = {\n  communityId: ChatId,\n  participantId: PeerId,\n  participant?: ChannelParticipant,\n  editingAdmin: true,\n  onUpdated?: (participant?: ChannelParticipant) => MaybePromise<void>\n};\n\ntype AppUserPermissionsTabPayload =\n  AppUserPermissionsChatPayload |\n  AppUserPermissionsCommunityPayload;\n\nexport const AppUserPermissionsTab =\n  scaffoldSolidJSTabEventable<AppUserPermissionsTabPayload>({\n    title: (p) => 'communityId' in p ?\n      'EditAdmin' :\n      (p.addingBot && !p.addingBot.existingAdmin ?\n        'AddBot' :\n        (p.editingAdmin ? 'EditAdmin' : 'UserRestrictions')),\n    getComponentModule: () => import('../sidebarRight/tabs/userPermissions')\n  });\n\n// Replaces the legacy AppUserPermissionsTab.openTab static.\nexport function openUserPermissionsTab(\n  slider: SidebarSlider,\n  chatId: ChatId,\n  participant: ChatParticipant | ChannelParticipant,\n  isAdmin?: boolean,\n  options?: Pick<AppUserPermissionsChatPayload, 'initialAdminRights' | 'existingAdminRights' | 'addingBot'>\n) {\n  slider.createTab(AppUserPermissionsTab).open({\n    participant,\n    chatId,\n    userId: getParticipantPeerId(participant).toUserId(),\n    editingAdmin: isAdmin,\n    ...options\n  });\n}\n\nexport function openCommunityUserPermissionsTab(\n  slider: SidebarSlider,\n  communityId: ChatId,\n  participantId: PeerId,\n  participant?: ChannelParticipant,\n  onUpdated?: (participant?: ChannelParticipant) => MaybePromise<void>\n) {\n  slider.createTab(AppUserPermissionsTab).open({\n    communityId,\n    participantId,\n    participant,\n    editingAdmin: true,\n    onUpdated\n  });\n}\n\n\ntype AppIncludedChatsTabPayload = {\n  filter: MyDialogFilter,\n  type: 'included' | 'excluded',\n  onSetFilter: (filter: MyDialogFilter) => void\n};\n\nexport const AppIncludedChatsTab =\n  scaffoldSolidJSTab<AppIncludedChatsTabPayload>({\n    title: (p) => p.type === 'included' ? 'FilterAlwaysShow' : 'FilterNeverShow',\n    getComponentModule: () => import('../sidebarLeft/tabs/includedChats')\n  });\n\ntype AppSharedFolderTabPayload = {\n  filter: DialogFilter.dialogFilterChatlist,\n  chatlistInvite: ExportedChatlistInvite\n};\n\nexport const AppSharedFolderTab =\n  scaffoldSolidJSTabEventable<AppSharedFolderTabPayload, {\n    delete: () => void,\n    edit: (chatlistInvite: ExportedChatlistInvite) => void\n      }>({\n        title: 'SharedFolder.Edit.Title',\n        getComponentModule: () => import('../sidebarLeft/tabs/sharedFolder'),\n        onOpenAfterTimeout: function() {\n          (this as any)._onOpenAfterTimeout?.();\n        }\n      });\n\ntype AppGroupPermissionsTabPayload = {\n  chatId: ChatId\n};\n\nexport const AppGroupPermissionsTab =\n  scaffoldSolidJSTab<AppGroupPermissionsTabPayload>({\n    title: 'ChannelPermissions',\n    getComponentModule: () => import('../sidebarRight/tabs/groupPermissions/groupPermissions'),\n    onOpenAfterTimeout: function() {\n      this.scrollable.onScroll();\n    }\n  });\n\nconst getPrivacyAndSecurityInitArgs = (fromTab: SliderSuperTab) => ({\n  appConfig: fromTab.managers.apiManager.getAppConfig(),\n  globalPrivacy: fromTab.managers.appPrivacyManager.getGlobalPrivacySettings(),\n  webAuthorizations: fromTab.managers.appSeamlessLoginManager.getWebAuthorizations()\n});\n\ntype AppPrivacyAndSecurityTabPayload = ReturnType<typeof getPrivacyAndSecurityInitArgs>;\n\nexport const AppPrivacyAndSecurityTab =\n  scaffoldSolidJSTabEventable<AppPrivacyAndSecurityTabPayload>({\n    title: 'PrivacySettings',\n    getComponentModule: () => import('../sidebarLeft/tabs/privacyAndSecurity')\n  });\n\n// Preload (appConfig / globalPrivacy / webAuthorizations) read off the constructor\n// by settings.tsx's makeSubTabConfig, matching the old static getInitArgs.\n(AppPrivacyAndSecurityTab as any).getInitArgs = getPrivacyAndSecurityInitArgs;\n\n\ntype AppEditChatInviteLinkTabPayload = {\n  chatId: ChatId,\n  invite?: ChatInvite\n};\n\nexport const AppEditChatInviteLinkTab =\n  scaffoldSolidJSTabEventable<AppEditChatInviteLinkTabPayload, {\n    finish: (chatInvite: ChatInvite) => void\n      }>({\n        title: (p) => p.invite ? 'InviteLinks.Edit' : 'NewLink',\n        getComponentModule: () => import('../sidebarRight/tabs/editChatInviteLink')\n      });\n\n\ntype AppChatInviteLinkTabPayload = {\n  chatId: ChatId,\n  chatInvite: ChatInvite,\n  menuButtons: ButtonMenuItemOptionsVerifiable[],\n  actions: ChatInviteActions,\n  onUpdate?: (chatInvite: ChatInvite) => void\n};\n\nexport const AppChatInviteLinkTab =\n  scaffoldSolidJSTabEventable<AppChatInviteLinkTabPayload>({\n    title: 'InviteLink',\n    getComponentModule: () => import('../sidebarRight/tabs/chatInviteLink')\n  });\n\n\ntype AppChatInviteLinksTabPayload = {\n  chatId: ChatId,\n  adminId?: UserId,\n  p?: ReturnType<typeof getChatInviteLinksInitArgs>\n};\n\n// getInitArgs is read directly (typed) by editChat's navigationTab, so expose it\n// on the constructor via Object.assign rather than an untyped property poke.\nexport const AppChatInviteLinksTab = Object.assign(\n  scaffoldSolidJSTabEventable<AppChatInviteLinksTabPayload>({\n    title: 'InviteLinks',\n    getComponentModule: () => import('../sidebarRight/tabs/chatInviteLinks')\n  }),\n  {getInitArgs: getChatInviteLinksInitArgs}\n);\n\n\ntype AppEditChatTabPayload = {\n  chatId: ChatId\n};\n\nexport const AppEditChatTab =\n  scaffoldSolidJSTab<AppEditChatTabPayload>({\n    title: 'Edit',\n    getComponentModule: () => import('../sidebarRight/tabs/editChat')\n  });\n\n\ntype AppAddGroupToCommunityTabPayload = {\n  peerId: PeerId\n};\n\nexport const AppAddGroupToCommunityTab =\n  scaffoldSolidJSTab<AppAddGroupToCommunityTabPayload>({\n    title: 'Community.AddGroup',\n    getComponentModule: () => import('../communities/addGroupToCommunity')\n  });\n\n\ntype AppCreateCommunityTabPayload = {\n  peerId: PeerId\n};\n\nexport const AppCreateCommunityTab =\n  scaffoldSolidJSTab<AppCreateCommunityTabPayload>({\n    title: 'Community.Create',\n    getComponentModule: () => import('../communities/createCommunity')\n  });\n\n\nexport type CommunityChatVisibility = 'visible' | 'hidden';\nexport type CommunityChatSettingsMode = 'settings' | 'add';\n\ntype AppCommunityChatSettingsTabPayload = {\n  communityId?: ChatId,\n  peerId: PeerId,\n  mode?: CommunityChatSettingsMode,\n  initialVisibility?: CommunityChatVisibility,\n  onSave?: (visibility: CommunityChatVisibility) => MaybePromise<void>,\n  returnToEditChat?: boolean,\n  returnToEditCommunity?: boolean\n};\n\nexport const AppCommunityChatSettingsTab =\n  scaffoldSolidJSTab<AppCommunityChatSettingsTabPayload>({\n    title: (payload) => payload.mode === 'add' ?\n      'Community.AddChat' :\n      'Community.ChatSettings',\n    getComponentModule: () => import('../communities/communityChatSettings')\n  });\n\n\ntype AppEditCommunityTabPayload = {\n  communityId: ChatId\n};\n\nexport const AppEditCommunityTab =\n  scaffoldSolidJSTab<AppEditCommunityTabPayload>({\n    title: 'Community.Edit',\n    getComponentModule: () => import('../communities/editCommunity')\n  });\n\n\ntype AppAddChatToCommunityTabPayload = {\n  communityId: ChatId\n};\n\nexport const AppAddChatToCommunityTab =\n  scaffoldSolidJSTab<AppAddChatToCommunityTabPayload>({\n    title: 'Community.AddChat',\n    getComponentModule: () => import('../communities/addChatToCommunity')\n  });\n\n\ntype AppCommunityPendingRequestsTabPayload = {\n  communityId: ChatId\n};\n\nexport const AppCommunityPendingRequestsTab =\n  scaffoldSolidJSTab<AppCommunityPendingRequestsTabPayload>({\n    title: 'Community.PendingRequests',\n    getComponentModule: () => import('../communities/communityPendingRequests')\n  });\n\n\nfunction getChatFoldersInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('Folders_1'),\n    filters: rootScope.managers.filtersStorage.getDialogFilters()\n  };\n}\n\ntype AppChatFoldersTabPayload = ReturnType<typeof getChatFoldersInitArgs>;\n\n// getInitArgs is read both via makeSubTabConfig (any-cast) and directly (typed)\n// by foldersSidebarContent, so expose it on the constructor via Object.assign.\nexport const AppChatFoldersTab = Object.assign(\n  scaffoldSolidJSTab<AppChatFoldersTabPayload>({\n    title: 'ChatList.Filter.List.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/chatFolders'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  }),\n  {getInitArgs: getChatFoldersInitArgs}\n);\n\n\ntype AppEditFolderTabPayload = ReturnType<typeof getEditFolderInitArgs> & {\n  initFilter?: MyDialogFilter\n};\n\n// getInitArgs (preload) + deleteFolder (called from createFolderContextMenu and\n// chatFolders via the hot-reload guard) are exposed on the constructor.\nexport const AppEditFolderTab = Object.assign(\n  scaffoldSolidJSTab<AppEditFolderTabPayload>({\n    title: 'FilterHeaderEdit',\n    getComponentModule: () => import('../sidebarLeft/tabs/editFolder'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  }),\n  {\n    getInitArgs: getEditFolderInitArgs,\n    deleteFolder: deleteEditFolder\n  }\n);\n\n\nfunction getMyStoriesInitArgs() {\n  return {\n    animationData: lottieLoader.loadAnimationFromURLManually('UtyanStories')\n  };\n}\n\ntype AppMyStoriesTabPayload = ReturnType<typeof getMyStoriesInitArgs> & {\n  isArchive?: boolean,\n  chatId?: ChatId,\n  initialAlbumId?: number\n};\n\nexport const AppMyStoriesTab = Object.assign(\n  scaffoldSolidJSTab<AppMyStoriesTabPayload>({\n    title: (p) => p.isArchive ? 'MyStories.Archive' : 'MyStories.Title',\n    getComponentModule: () => import('../sidebarLeft/tabs/myStories')\n  }),\n  {getInitArgs: getMyStoriesInitArgs}\n);\n\n\nexport const AppArchivedTab =\n  scaffoldSolidJSTab({\n    title: 'ArchivedChats',\n    getComponentModule: () => import('../sidebarLeft/tabs/archivedTab'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onClose: function() {\n      (this as any)._onClose?.();\n    },\n    onCloseAfterTimeout: function() {\n      (this as any)._onCloseAfterTimeout?.();\n    }\n  });\n\n\n// ── 2FA wizard ──────────────────────────────────────────────────────────────\n\ntype AppTwoStepVerificationSetTabPayload = {\n  messageFor: 'password' | 'email'\n};\n\nexport const AppTwoStepVerificationSetTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationSetTabPayload>({\n    title: (p) => p.messageFor === 'password' ? 'TwoStepVerificationPasswordSet' : 'TwoStepVerificationEmailSet',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/passwordSet')\n  });\n\n\ntype AppTwoStepVerificationTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string\n};\n\nexport const AppTwoStepVerificationTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationTabPayload>({\n    title: 'TwoStepVerificationTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/index')\n  });\n\n\ntype AppTwoStepVerificationEnterPasswordTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  isFirst?: boolean\n};\n\nexport const AppTwoStepVerificationEnterPasswordTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEnterPasswordTabPayload>({\n    title: (p) => (!p.state.pFlags.has_password || p.plainPassword) ? 'PleaseEnterFirstPassword' : 'PleaseEnterCurrentPassword',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/enterPassword'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onClose: function() {\n      (this as any)._onClose?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationReEnterPasswordTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string\n};\n\nexport const AppTwoStepVerificationReEnterPasswordTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationReEnterPasswordTabPayload>({\n    title: 'PleaseReEnterPassword',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/reEnterPassword'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationHintTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string\n};\n\nexport const AppTwoStepVerificationHintTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationHintTabPayload>({\n    title: 'TwoStepAuth.SetupHintTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/hint'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationEmailTabPayload = {\n  state: AccountPassword,\n  plainPassword?: string,\n  newPassword?: string,\n  hint?: string,\n  isFirst?: boolean,\n  justSetPasssword?: boolean\n};\n\nexport const AppTwoStepVerificationEmailTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEmailTabPayload>({\n    title: 'RecoveryEmailTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/email'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\ntype AppTwoStepVerificationEmailConfirmationTabPayload = {\n  state: AccountPassword,\n  email: FormatterArgument,\n  length: number,\n  isFirst?: boolean,\n  forPasswordReset?: boolean,\n  justSetPasssword?: boolean\n};\n\nexport const AppTwoStepVerificationEmailConfirmationTab =\n  scaffoldSolidJSTab<AppTwoStepVerificationEmailConfirmationTabPayload>({\n    title: 'TwoStepAuth.RecoveryTitle',\n    getComponentModule: () => import('../sidebarLeft/tabs/2fa/emailConfirmation'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    },\n    onCloseAfterTimeout: function() {\n      (this as any)._onCloseAfterTimeout?.();\n    }\n  });\n\n\ntype AppPrivateSearchTabPayload = {\n  peerId: PeerId,\n  threadId?: number,\n  onDatePick?: (timestamp: number) => void,\n  query?: string\n};\n\nexport const AppPrivateSearchTab =\n  scaffoldSolidJSTab<AppPrivateSearchTabPayload>({\n    title: 'Search',\n    getComponentModule: () => import('../sidebarRight/tabs/search'),\n    onOpenAfterTimeout: function() {\n      (this as any)._onOpenAfterTimeout?.();\n    }\n  });\n\n\nexport type AppAddMembersExtraCategory = {\n  key: string;\n  icon: Icon;\n  text: LangPackKey;\n  statusLangKey?: LangPackKey;\n};\n\nexport type AppAddMembersPeerLoader = (\n  query: string,\n  isCurrent: () => boolean\n) => Promise<{\n  result: PeerId[],\n  isEnd: boolean\n}>;\n\ntype AppAddMembersTabPayload = {\n  title: LangPackKey;\n  placeholder: LangPackKey;\n  type: 'channel' | 'chat' | 'privacy';\n  takeOut?: (peerIds: PeerId[], extras?: Set<string>) => Promise<any> | false | void;\n  skippable: boolean;\n  selectedPeerIds?: PeerId[];\n  selectedExtras?: Set<string>;\n  extraCategories?: ReadonlyArray<AppAddMembersExtraCategory>;\n  extraCategoriesSectionLangKey?: LangPackKey;\n  peerType?: SelectSearchPeerType[];\n  channelParticipantsPeerId?: PeerId;\n  peerLoader?: AppAddMembersPeerLoader;\n  exceptSelf?: boolean;\n  filterPeerTypeBy?: IsPeerType[] | FilterPeerTypeByFunc;\n  limit?: number;\n  limitCallback?: () => void;\n  attachToPromise?: (promise: Promise<any>) => void;\n};\n\nexport const AppAddMembersTab =\n  scaffoldSolidJSTab<AppAddMembersTabPayload>({\n    title: 'GroupAddMembers',\n    getComponentModule: () => import('../sidebarLeft/tabs/addMembers')\n  });\n(AppAddMembersTab as any).noSame = true;\nconst _origAddMembersInit = (AppAddMembersTab.prototype as any).init;\n(AppAddMembersTab.prototype as any).init = function(payload: AppAddMembersTabPayload, overrideTitle?: LangPackKey) {\n  return _origAddMembersInit.call(this, payload, overrideTitle || payload.title);\n};\n","import {animateValue} from './animateValue';\nimport deferredPromise from './cancellablePromise';\nimport {lerp} from './lerp';\n\ntype AnimateImageToTargetArgs = {\n  animatedImg: HTMLImageElement;\n  target: HTMLElement;\n  targetIsRound?: boolean;\n};\n\nexport function animateImageToTarget({animatedImg, target, targetIsRound}: AnimateImageToTargetArgs) {\n  const deferred = deferredPromise<void>();\n\n  const bcr = animatedImg.getBoundingClientRect();\n  const left = bcr.left + bcr.width / 2, top = bcr.top + bcr.height / 2, width = bcr.width, height = bcr.height;\n  const targetBcr = target.getBoundingClientRect();\n  const leftDiff = (targetBcr.left + targetBcr.width / 2) - left;\n  const topDiff = (targetBcr.top + targetBcr.height / 2) - top;\n\n  const cancelAnimation = animateValue(\n    0, 1, 200,\n    (progress) => {\n      animatedImg.style.transform = `translate(calc(${ progress * leftDiff }px - 50%), calc(${ progress * topDiff }px - 50%))`;\n      animatedImg.style.width = lerp(width, targetBcr.width, progress) + 'px';\n      animatedImg.style.height = lerp(height, targetBcr.height, progress) + 'px';\n\n      if(targetIsRound) {\n        animatedImg.style.borderRadius = lerp(0, 50, progress) + '%';\n      }\n    },\n    {\n      onEnd: () => {\n        deferred.resolve();\n      }\n    }\n  );\n\n  return {\n    promise: deferred,\n    cancel: (reject?: boolean) => {\n      cancelAnimation();\n      if(reject) {\n        deferred.reject();\n      }\n    }\n  };\n}\n","import {createObjectURL, revokeObjectURL} from '@helpers/objectUrl';\n\ntype RenderImageAndURLFromBlobResult = {\n  ok: true;\n  url: string;\n  img: HTMLImageElement;\n} | {\n  ok: false;\n};\n\nexport async function createImageAndURLFromBlob(blob: Blob): Promise<RenderImageAndURLFromBlobResult> {\n  const url = createObjectURL(blob);\n\n  const img = new Image();\n  img.src = url;\n\n  try {\n    await img.decode();\n    return {ok: true, url, img};\n  } catch{\n    revokeObjectURL(url);\n    return {ok: false};\n  }\n}\n","import {MediaEditorFinalResult} from '@components/mediaEditor/finalRender/createFinalResult';\nimport IMAGE_MIME_TYPES_SUPPORTED from '@environment/imageMimeTypesSupport';\nimport VIDEO_MIME_TYPES_SUPPORTED from '@environment/videoMimeTypesSupport';\nimport {createImageAndURLFromBlob} from '@helpers/createImageAndURLFromBlob';\nimport {getAppWindow} from '@helpers/appWindow';\nimport {createObjectURL, revokeObjectURL} from '@helpers/objectUrl';\nimport rootScope from '@lib/rootScope';\n\n\ntype OnFinishArgs = {\n  editorResult: MediaEditorFinalResult;\n  originalFile: File;\n};\n\ntype GetFileAndOpenEditorArgs = {\n  dontCreatePreview?: boolean;\n  isEditingForAvatar?: boolean;\n  isEditingForumAvatar?: boolean;\n  canImageResultInGIF?: boolean;\n  /**\n   * Allowed media types in the file picker. Defaults to images only.\n   */\n  acceptMediaTypes?: Array<'photo' | 'video'>;\n  /**\n   * Optional gate to decide whether the editor should be opened for the selected file.\n   * If it returns false, `onSkipEditor` is called with the file and the editor is not opened.\n   * Defaults to always opening the editor.\n   */\n  shouldOpenEditor?: (file: File) => boolean | Promise<boolean>;\n  onSkipEditor?: (file: File) => void;\n  onFinish: (args: OnFinishArgs) => void;\n};\n\nexport async function getFileAndOpenEditor({\n  onFinish,\n  dontCreatePreview,\n  isEditingForAvatar,\n  isEditingForumAvatar,\n  canImageResultInGIF = false,\n  acceptMediaTypes = ['photo'],\n  shouldOpenEditor,\n  onSkipEditor\n}: GetFileAndOpenEditorArgs) {\n  const input = createHiddenFileInput(acceptMediaTypes);\n  document.body.append(input);\n\n  const file = await getFileFromInput(input).finally(() => {\n    input.remove();\n  });\n\n  if(!file) return;\n\n  if(shouldOpenEditor && !(await shouldOpenEditor(file))) {\n    onSkipEditor?.(file);\n    return;\n  }\n\n  const isVideo = file.type.startsWith('video/');\n\n  let mediaSrc: string;\n  if(isVideo) {\n    mediaSrc = createObjectURL(file);\n  } else {\n    const imgResult = await createImageAndURLFromBlob(file); // make sure to render the image to know if it's valid\n    if(!imgResult.ok) return;\n    mediaSrc = imgResult.url;\n  }\n\n  let openMediaEditorFromMediaRaw: typeof import('@components/mediaEditor')['openMediaEditorFromMediaRaw'];\n  try {\n    ({openMediaEditorFromMediaRaw} = await import('@components/mediaEditor'));\n  } catch(error) {\n    revokeObjectURL(mediaSrc);\n    throw error;\n  }\n\n  openMediaEditorFromMediaRaw({\n    isEditingForAvatar,\n    isEditingForumAvatar,\n    canFinishWithoutChanges: true,\n    canImageResultInGIF,\n    getMediaBlob: async() => file,\n    managers: rootScope.managers,\n    mediaSrc,\n    mediaType: isVideo ? 'video' : 'image',\n    // Editing an avatar with a video → avatar-video mode (≤10s trim, forced mute,\n    // cover-frame picker). Non-avatar callers are unaffected.\n    isVideoAvatarMode: isEditingForAvatar && isVideo,\n    initialTab: isVideo ? 'adjustments' : 'crop',\n    onEditFinish: (editorResult) => onFinish({editorResult, originalFile: file}),\n    dontCreatePreview,\n    onClose: () => revokeObjectURL(mediaSrc)\n  });\n}\n\nfunction createHiddenFileInput(acceptMediaTypes: Array<'photo' | 'video'>): HTMLInputElement {\n  const input = document.createElement('input');\n  input.type = 'file';\n  input.style.display = 'none';\n\n  const mimeTypes: string[] = [];\n  if(acceptMediaTypes.includes('photo')) mimeTypes.push(...IMAGE_MIME_TYPES_SUPPORTED);\n  if(acceptMediaTypes.includes('video')) mimeTypes.push(...VIDEO_MIME_TYPES_SUPPORTED);\n  input.accept = mimeTypes.join(',');\n\n  return input;\n}\n\nfunction getFileFromInput(input: HTMLInputElement): Promise<File | void> {\n  const promise = new Promise<File | void>((resolve) => {\n    input.addEventListener('change', () => {\n      const file = input.files?.[0];\n      resolve(file);\n    });\n\n    // Resolve the promise if the user cancels the file selection — active window (the PiP when popped)\n    getAppWindow().addEventListener('focus', () => {\n      // It seems like the focus event fires before the change event, so we need to wait a bit before resolving\n      setTimeout(() => {\n        input.remove();\n        resolve();\n      }, 1000);\n    }, {once: true});\n  });\n\n  input.click();\n\n  return promise;\n}\n","import {Signal} from 'solid-js';\nimport {ProgressCircleSVG} from '@components/progressCircleSVG';\n\nexport default function RenderProgressCircle(props: {creationProgress: Signal<number>}) {\n  const [progress] = props.creationProgress;\n\n  return (\n    <div\n      style={{\n        display: 'flex',\n        position: 'absolute',\n        left: '50%',\n        top: '50%',\n        transform: 'translate(-50%, -50%)',\n        width: '64px',\n        ...{\n          'background-color': 'rgba(0, 0, 0, .25)',\n          'border-radius': '64px',\n          'max-width': '80%',\n          'max-height': '80%',\n          'aspect-ratio': '1 / 1',\n          'z-index': 2\n        }\n      }}\n    >\n      <ProgressCircleSVG progress={progress()} strokeThickness={1 / 10} withText stroke='white' />\n    </div>\n  );\n}\n","import {i18n} from '@lib/langPack';\n\nexport type AdjustmentsConfig = typeof adjustmentsConfig;\n\nexport type AdjustmentKey = AdjustmentsConfig[number]['key'];\n\nexport const adjustmentsConfig = [\n  {\n    key: 'enhance',\n    uniform: 'uEnhance',\n    label: () => i18n('MediaEditor.Adjustments.Enhance'),\n    to100: true\n  },\n  {\n    key: 'brightness',\n    uniform: 'uBrightness',\n    label: () => i18n('MediaEditor.Adjustments.Brightness'),\n    to100: false\n  },\n  {\n    key: 'contrast',\n    uniform: 'uContrast',\n    label: () => i18n('MediaEditor.Adjustments.Contrast'),\n    to100: false\n  },\n  {\n    key: 'saturation',\n    uniform: 'uSaturation',\n    label: () => i18n('MediaEditor.Adjustments.Saturation'),\n    to100: false\n  },\n  {\n    key: 'warmth',\n    uniform: 'uWarmth',\n    label: () => i18n('MediaEditor.Adjustments.Warmth'),\n    to100: false\n  },\n  {\n    key: 'fade',\n    uniform: 'uFade',\n    label: () => i18n('MediaEditor.Adjustments.Fade'),\n    to100: true\n  },\n  {\n    key: 'highlights',\n    uniform: 'uHighlights',\n    label: () => i18n('MediaEditor.Adjustments.Highlights'),\n    to100: false\n  },\n  {\n    key: 'shadows',\n    uniform: 'uShadows',\n    label: () => i18n('MediaEditor.Adjustments.Shadows'),\n    to100: false\n  },\n  {\n    key: 'vignette',\n    uniform: 'uVignette',\n    label: () => i18n('MediaEditor.Adjustments.Vignette'),\n    to100: true\n  },\n  {\n    key: 'grain',\n    uniform: 'uGrain',\n    label: () => i18n('MediaEditor.Adjustments.Grain'),\n    to100: true\n  },\n  {\n    key: 'sharpen',\n    uniform: 'uSharpen',\n    label: () => i18n('MediaEditor.Adjustments.Sharpen'),\n    to100: true\n  }\n] as const;\n","export default function exceptKeys<T extends object, Key extends keyof T>(obj: T, keys: Key[]) {\n  const set = new Set<any>(keys);\n  const res = {};\n\n  Object.keys(obj).forEach((key) => {\n    if(set.has(key)) return;\n    (res as any)[key] = (obj as any)[key];\n  });\n\n  return res as Exclude<T, Key>;\n}\n","import {AdjustmentKey, adjustmentsConfig} from '@components/mediaEditor/adjustments';\nimport {BrushDrawnLine} from '@components/mediaEditor/canvas/brushPainter';\nimport {FinalTransform} from '@components/mediaEditor/canvas/useFinalTransform';\nimport type {MediaEditorProps} from '@components/mediaEditor/mediaEditor';\nimport {MediaType, NumberPair, ResizableLayer, StickerRenderingInfo, TextLayerInfo} from '@components/mediaEditor/types';\nimport {approximateDeepEqual, brushDefaults, textLayerInfoDefaults, traverseObjectDeep} from '@components/mediaEditor/utils';\nimport {RenderingPayload} from '@components/mediaEditor/webgl/initWebGL';\nimport exceptKeys from '@helpers/object/exceptKeys';\nimport throttle from '@helpers/schedulers/throttle';\nimport type {AppManagers} from '@lib/managers';\nimport type {ObjectPath} from '@types';\nimport {Accessor, createContext, createEffect, createMemo, createSignal, on, useContext} from 'solid-js';\nimport {createMutable, modifyMutable, produce, Store} from 'solid-js/store';\n\n\ntype EditingMediaStateWithoutHistory = {\n  scale: number;\n  rotation: number;\n  translation: NumberPair;\n  flip: NumberPair;\n  currentImageRatio: number;\n\n  currentVideoTime: number;\n  videoCropStart: number;\n  videoCropLength: number;\n  videoThumbnailPosition: number;\n  videoMuted: boolean;\n  videoQuality: number;\n\n  adjustments: Record<AdjustmentKey, number>;\n\n  resizableLayers: ResizableLayer[];\n  brushDrawnLines: BrushDrawnLine[];\n};\n\nexport type EditingMediaState = EditingMediaStateWithoutHistory & {\n  history: HistoryItem[];\n  redoHistory: HistoryItem[];\n};\n\nexport type KeyofEditingMediaState = ObjectPath<EditingMediaStateWithoutHistory>;\n\nexport namespace HistoryItem {\n  export const RemoveArrayItem = 'SSBiZWxpZXZlIEkgY2FuIGZseSwgSSBiZWxpZXZlIEkgY2FuIHRvdWNoIHRoZSBza3kh'; // Symbol('Remove'); Symbol cannot be structuredClone :(\n}\n\nexport type HistoryItem = {\n  path: KeyofEditingMediaState;\n  newValue: any;\n  oldValue: any;\n\n  // Resizable layers can change order!\n  findBy?: {\n    id: any;\n  };\n};\n\nexport type ColoredBrushType = 'pen' | 'brush' | 'neon' | 'arrow';\nexport type BrushType = ColoredBrushType | 'blur' | 'eraser';\n\nexport type MediaEditorState = {\n  isReady: boolean;\n\n  pixelRatio: number;\n  renderingPayload?: RenderingPayload;\n\n  currentTab: string;\n  cropTabAnimationProgress: number;\n\n  mediaSize?: NumberPair;\n  mediaRatio?: number;\n  canvasSize?: NumberPair;\n  fixedImageRatioKey?: string;\n  finalTransform: FinalTransform;\n\n  currentTextLayerInfo: TextLayerInfo;\n  selectedResizableLayer?: number;\n  stickersLayersInfo: Record<number, StickerRenderingInfo>;\n\n  imageCanvas?: HTMLCanvasElement;\n  brushCanvas?: HTMLCanvasElement;\n\n  currentBrush: {\n    color: string;\n    size: number;\n    brush: BrushType;\n  };\n  previewBrushSize?: number;\n\n  resizeHandlesContainer?: HTMLDivElement;\n\n  isAdjusting: boolean;\n  isMoving: boolean;\n  isPlaying: boolean;\n};\n\nexport enum SetVideoTimeFlags {\n  Redraw = 0b001,\n  UpdateCursor = 0b010,\n  UpdateVideo = 0b100\n};\n\nexport type EditorOverridableGlobalActions = {\n  pushToHistory: (item: HistoryItem) => void;\n  updateMediaStateClone: (callback: (state: EditingMediaState) => void) => void;\n  redrawBrushes: () => void;\n  abortDrawerSlide: () => void;\n  resetRotationWheel: () => void;\n  setVideoTime: (time: number, flags?: SetVideoTimeFlags) => void;\n};\n\n\nconst getDefaultEditingMediaState = (): EditingMediaState => ({\n  scale: 1,\n  rotation: 0,\n  translation: [0, 0],\n  flip: [1, 1],\n  currentImageRatio: 0,\n\n  currentVideoTime: 0,\n  videoCropStart: 0,\n  videoCropLength: 1,\n  videoThumbnailPosition: 0,\n  videoMuted: false,\n  videoQuality: 0,\n\n  adjustments: Object.fromEntries(adjustmentsConfig.map(entry => [entry.key, 0])) as Record<AdjustmentKey, number>,\n\n  resizableLayers: [],\n  brushDrawnLines: [],\n\n  history: [],\n  redoHistory: []\n});\n\nconst getDefaultMediaEditorState = (): MediaEditorState => ({\n  isReady: false,\n\n  pixelRatio: window.devicePixelRatio,\n  renderingPayload: undefined,\n\n  currentTab: 'adjustments',\n  cropTabAnimationProgress: 0,\n\n  mediaSize: undefined,\n  canvasSize: undefined,\n  fixedImageRatioKey: undefined,\n  finalTransform: {\n    flip: [1, 1],\n    rotation: 0,\n    scale: 1,\n    translation: [0, 0]\n  },\n\n  currentTextLayerInfo: structuredClone(textLayerInfoDefaults),\n  selectedResizableLayer: undefined,\n  stickersLayersInfo: {},\n\n  currentBrush: structuredClone(brushDefaults),\n  previewBrushSize: undefined,\n\n  resizeHandlesContainer: undefined,\n\n  isAdjusting: false,\n  isMoving: false,\n  isPlaying: false\n});\n\nexport type MediaEditorContextValue = {\n  managers: AppManagers;\n\n  mediaSrc: string;\n  mediaType: MediaType;\n  getMediaBlob: () => Promise<Blob | null>;\n  canImageResultInGIF: boolean;\n  isEditingForAvatar: boolean;\n  isEditingForumAvatar: boolean;\n  isVideoAvatarMode: boolean;\n  dontCreatePreview: boolean;\n  imageType?: 'image/jpeg' | 'image/png';\n  imageQuality?: number;\n\n  mediaState: Store<EditingMediaState>;\n  editorState: Store<MediaEditorState>;\n  actions: EditorOverridableGlobalActions;\n\n  canFinish: Accessor<boolean>;\n  hasModifications: Accessor<boolean>;\n\n  resizableLayersSeed: number;\n};\n\n\nconst MediaEditorContext = createContext<MediaEditorContextValue>();\n\nexport function createContextValue(props: MediaEditorProps): MediaEditorContextValue {\n  const mediaStateInit = props.editingMediaState ?\n    structuredClone(props.editingMediaState) : // Prevent mutable store being synchronized with the passed object reference\n    getDefaultEditingMediaState();\n\n  const mediaStateInitClone = structuredClone(mediaStateInit);\n\n\n  // Video-avatar mode forces audio off, since profile videos have no sound.\n  if(props.isVideoAvatarMode) {\n    mediaStateInit.videoMuted = true;\n  }\n\n  const mediaState = createMutable(mediaStateInit);\n  const editorState = createMutable(getDefaultMediaEditorState());\n\n  if(props.initialTab) {\n    editorState.currentTab = props.initialTab;\n    if(props.initialTab === 'crop') {\n      editorState.cropTabAnimationProgress = 1;\n    }\n  }\n\n  const actions: EditorOverridableGlobalActions = {\n    pushToHistory: (item: HistoryItem) => {\n      modifyMutable(mediaState, produce(({history, redoHistory}) => {\n        history.push(item);\n        redoHistory.length && redoHistory.splice(0, Infinity);\n      }));\n    },\n    updateMediaStateClone: (callback) => {\n      callback(mediaStateInitClone);\n    },\n    redrawBrushes: () => {},\n    abortDrawerSlide: () => {},\n    resetRotationWheel: () => {},\n    setVideoTime: () => {}\n  };\n\n  const [hasModifications, setHasModifications] = createSignal(false);\n\n  const keysToExcept = ['history', 'redoHistory', 'currentVideoTime'] satisfies (keyof EditingMediaState)[];\n\n  const throttledUpdateHasModifications = throttle(() => {\n    setHasModifications(\n      !approximateDeepEqual(\n        exceptKeys(mediaStateInitClone, keysToExcept),\n        exceptKeys(mediaState, keysToExcept)\n      )\n    );\n  }, 200, false);\n\n  createEffect(on(() => traverseObjectDeep(exceptKeys(mediaState, keysToExcept)), () => {\n    throttledUpdateHasModifications();\n  }));\n\n  // (window as any).mediaState = mediaState;\n  // (window as any).unwrap = unwrap;\n\n  return {\n    managers: props.managers,\n\n    mediaSrc: props.mediaSrc,\n    mediaType: props.mediaType,\n    getMediaBlob: props.getMediaBlob,\n    canImageResultInGIF: props.canImageResultInGIF || false,\n    isEditingForAvatar: props.isEditingForAvatar || false,\n    isEditingForumAvatar: props.isEditingForumAvatar || false,\n    isVideoAvatarMode: props.isVideoAvatarMode || false,\n    dontCreatePreview: props.dontCreatePreview || false,\n    imageType: props.imageType,\n    imageQuality: props.imageQuality,\n\n    mediaState,\n    editorState,\n    actions,\n\n    canFinish: createMemo(() => props.canFinishWithoutChanges || hasModifications()),\n    hasModifications,\n\n    // [0-1] make sure it's different even after reopening the editor, note that there might be some items in history!\n    resizableLayersSeed: Math.random()\n  };\n}\n\nexport const useMediaEditorContext = () => useContext(MediaEditorContext);\n\nexport default MediaEditorContext;\n","import {HistoryItem, MediaEditorState} from '@components/mediaEditor/context';\nimport {FontInfo, FontKey, NumberPair, ResizableLayer, TextLayerInfo} from '@components/mediaEditor/types';\nimport StickerType from '@config/stickerType';\nimport {IS_FIREFOX} from '@environment/userAgent';\nimport {hexaToHsla} from '@helpers/color';\nimport {logger} from '@lib/logger';\n\nexport const log = logger('Media editor');\n\nexport const delay = (timeout: number) => new Promise((resolve) => setTimeout(resolve, timeout));\n\nexport function distance(p1: NumberPair, p2: NumberPair) {\n  return Math.hypot(p1[0] - p2[0], p1[1] - p2[1]);\n}\n\n/**\n * Projects `to` onto the closest ray leaving `from` at a multiple of `step` radians — the angle\n * snapping other graphic editors do while a straight line is being drawn with Shift\n */\nexport function snapToAngle(from: NumberPair, to: NumberPair, step = Math.PI / 4): NumberPair {\n  const dx = to[0] - from[0], dy = to[1] - from[1];\n  const angle = Math.round(Math.atan2(dy, dx) / step) * step;\n  const projection = dx * Math.cos(angle) + dy * Math.sin(angle);\n\n  return [from[0] + Math.cos(angle) * projection, from[1] + Math.sin(angle) * projection];\n}\n\nexport function snapToViewport(ratio: number, vw: number, vh: number) {\n  if(vw / ratio > vh) vw = vh * ratio;\n  else vh = vw / ratio;\n\n  return [vw, vh] as NumberPair;\n}\n\nexport function getSnappedViewportsScale(ratio: number, vw1: number, vh1: number, vw2: number, vh2: number) {\n  [vw1, vh1] = snapToViewport(ratio, vw1, vh1);\n  [vw2, vh2] = snapToViewport(ratio, vw2, vh2);\n\n  return Math.max(vw1 / vw2, vh1 / vh2);\n}\n\nexport function getContrastColor(color: string) {\n  return hexaToHsla(color).l < 80 ? '#ffffff' : '#000000';\n}\n\n\n// const isPureObject = (obj: any) => [Object.prototype, null].includes(Object.getPrototypeOf(obj));\nconst isObject = (obj: any) => obj instanceof Object;\n\nconst COMPARISON_ERROR = 0.001;\n\nexport function approximateDeepEqual(x: any, y: any): boolean {\n  if(typeof x === 'number' && typeof y === 'number') return Math.abs(x - y) < COMPARISON_ERROR;\n\n  if(x === y) return true;\n\n  if(x instanceof Array && y instanceof Array)\n    return x.length === y.length && x\n    .every((value, idx) => approximateDeepEqual(value, y[idx]));\n\n\n  if(isObject(x) && isObject(y))\n    return Array\n    .from(new Set([...Object.keys(x), ...Object.keys(y)]))\n    .every(key => approximateDeepEqual(x[key], y[key]))\n\n\n  return false;\n}\n\nexport function processHistoryItem(item: HistoryItem, mediaState: any) {\n  const path = [...item.path].reverse() as (keyof any)[];\n  if(!path?.length) return;\n\n  let obj = mediaState;\n\n  while(path.length > 1)\n    obj = obj[path.pop()];\n\n  let key = path.pop();\n\n  if(obj instanceof Array) {\n    key = key as number;\n    if(item.findBy) key = obj.findIndex((value) => value?.id === item.findBy.id);\n    if(key === -1) key = obj.length;\n\n    if(item.newValue === HistoryItem.RemoveArrayItem)\n      obj.splice(key, 0, item.oldValue);\n    else if(item.oldValue === HistoryItem.RemoveArrayItem)\n      obj.splice(key, 1);\n    else\n      obj[key] = item.oldValue;\n  } else {\n    obj[key] = item.oldValue;\n  }\n}\n\nexport function traverseObjectDeep(obj: any) {\n  if(obj instanceof Array) obj.forEach(val => traverseObjectDeep(val));\n  else if(obj instanceof Object) Object.values(obj).forEach(val => traverseObjectDeep(val));\n}\n\nexport function cleanupWebGl(gl: WebGLRenderingContext) {\n  gl.getExtension('WEBGL_lose_context')?.loseContext();\n}\n\nexport const availableQualityHeights = [\n  240,\n  360,\n  480,\n  600, // non-standard, but prevents big quality jumps\n  720,\n  1080\n];\n\nexport function snapToAvailableQuality(videoHeight: number) {\n  const ALLOWED_THRESHOLD = 0.8;\n\n  for(let i = availableQualityHeights.length - 1; i > 0; i--) {\n    const higher = availableQualityHeights[i], lower = availableQualityHeights[i - 1];\n    const diff = higher - lower;\n\n    if(videoHeight > lower + diff * ALLOWED_THRESHOLD) return higher;\n  }\n\n  return availableQualityHeights[0];\n}\n\nexport function checkIfHasAnimatedStickers(layers: ResizableLayer[]) {\n  return !!layers.find((layer) => {\n    const stickerType = layer.sticker?.sticker;\n    return stickerType === StickerType.Lottie || (!IS_FIREFOX && stickerType === StickerType.WebM);\n  });\n};\n\nexport const fontInfoMap: Record<FontKey, FontInfo> = {\n  roboto: {\n    fontFamily: '\\'Roboto\\'',\n    fontWeight: 500,\n    baseline: 0.75\n  },\n  suez: {\n    fontFamily: '\\'Suez One\\'',\n    fontWeight: 400,\n    baseline: 0.75\n  },\n  bubbles: {\n    fontFamily: '\\'Rubik Bubbles\\'',\n    fontWeight: 400,\n    baseline: 0.75\n  },\n  playwrite: {\n    fontFamily: '\\'Playwrite BE VLG\\'',\n    fontWeight: 400,\n    baseline: 0.85\n  },\n  chewy: {\n    fontFamily: '\\'Chewy\\'',\n    fontWeight: 400,\n    baseline: 0.75\n  },\n  courier: {\n    fontFamily: '\\'Courier Prime\\'',\n    fontWeight: 700,\n    baseline: 0.65\n  },\n  fugaz: {\n    fontFamily: '\\'Fugaz One\\'',\n    fontWeight: 400,\n    baseline: 0.75\n  },\n  sedan: {\n    fontFamily: '\\'Sedan\\'',\n    fontWeight: 400,\n    baseline: 0.75\n  }\n};\n\nexport const textLayerInfoDefaults: TextLayerInfo = {\n  alignment: 'left',\n  style: 'outline',\n  color: '#ffffff',\n  font: 'roboto',\n  size: 40\n};\n\nexport const brushDefaults: MediaEditorState['currentBrush'] = {\n  brush: 'pen',\n  color: '#fe4438',\n  size: 12\n};\n","import Icon from '@components/icon';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {animateImageToTarget} from '@helpers/animateImageToTarget';\nimport type {CancellablePromise} from '@helpers/cancellablePromise';\nimport {createImageAndURLFromBlob} from '@helpers/createImageAndURLFromBlob';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {getFileAndOpenEditor} from '@helpers/getFileAndOpenEditor';\nimport {revokeObjectURL} from '@helpers/objectUrl';\nimport type {InputFile, Photo} from '@layer';\nimport type {AppManagers} from '@lib/managers';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport chooseProfileVideoSize from '@appManagers/utils/photos/chooseProfileVideoSize';\nimport rootScope from '@lib/rootScope';\nimport {render} from 'solid-js/web';\nimport {MediaEditorFinalResult} from './mediaEditor/finalRender/createFinalResult';\nimport RenderProgressCircle from './mediaEditor/renderProgressCircle';\nimport {snapToViewport} from './mediaEditor/utils';\n\nexport type AvatarEditPayload = {\n  file: () => CancellablePromise<InputFile>;\n  video?: () => CancellablePromise<InputFile>;\n  videoStartTs?: number;\n};\n\ntype Options = {\n  isForum?: boolean;\n};\n\n// video_start_ts (the cover frame) in seconds relative to the *trimmed* clip\n// start, clamped within the clip. videoThumbnailPosition / videoCrop* are 0..1\n// normalised over the *entire* source, so convert against the source duration.\nfunction computeVideoStartTs(editorResult: MediaEditorFinalResult): number {\n  const editing = editorResult.editingMediaState;\n  const sourceDuration = editorResult.videoDuration || 0;\n  const trimStartSec = editing.videoCropStart * sourceDuration;\n  const coverSec = editing.videoThumbnailPosition * sourceDuration;\n  const clipLengthSec = editing.videoCropLength * sourceDuration;\n  return Math.min(Math.max(0, coverSec - trimStartSec), clipLengthSec);\n}\n\n// Converts a finished media-editor result into upload thunks (cover JPEG +\n// optional MP4 + video_start_ts), without touching any preview canvas. Shared\n// by the contact-photo / fallback-photo flows that upload directly.\nexport async function mediaEditorResultToAvatarPayload(\n  editorResult: MediaEditorFinalResult,\n  namePrefix = 'avatar'\n): Promise<AvatarEditPayload | undefined> {\n  const resultPayload = await editorResult.getResult();\n\n  if(editorResult.isVideo) {\n    if(!resultPayload.thumb) return undefined;\n    const videoStartTs = computeVideoStartTs(editorResult);\n    return {\n      file: () => appDownloadManager.upload(resultPayload.thumb.blob, namePrefix + '-cover.jpg'),\n      video: () => appDownloadManager.upload(resultPayload.blob, namePrefix + '.mp4'),\n      videoStartTs\n    };\n  }\n\n  return {\n    file: () => appDownloadManager.upload(resultPayload.blob, namePrefix + '.jpg')\n  };\n}\n\ntype AvatarUploadMode = 'self' | 'fallback' | {userId: UserId; suggest?: boolean};\n\n// Shared tail of every \"edited avatar → upload\" flow: turn the editor result\n// into upload thunks, surface cancellable progress, then upload as the right\n// kind of photo (own / fallback / contact / suggested).\nasync function handleAvatarEditorResult(opts: {\n  result: MediaEditorFinalResult;\n  managers: AppManagers;\n  mode: AvatarUploadMode;\n  // Fired once the upload starts, with a cancellable progress source (suitable\n  // for ProgressivePreloader.attachPromise); cancelling it aborts the upload.\n  onUploadStart?: (progress: CancellablePromise<InputFile>) => void;\n  onUploaded?: () => void;\n}) {\n  const {result, managers, mode} = opts;\n  // Drop the full-screen preview right away; the encode + upload run in the\n  // background and the target avatar (if any) shows the upload progress.\n  result.animatedPreview?.remove();\n\n  const namePrefix = mode === 'self' ? 'avatar' :\n    mode === 'fallback' ? 'fallback' :\n    (mode.suggest ? 'suggest' : 'personal');\n\n  const payload = await mediaEditorResultToAvatarPayload(result, namePrefix);\n  if(!payload) return;\n\n  const filePromise = payload.file();\n  const videoPromise = payload.video?.();\n  // The bigger upload (video, if any) drives the visible progress; cancel\n  // aborts BOTH. Capture original cancels before overriding (progressSource\n  // is one of these promises, so reading its cancel after would recurse).\n  const progressSource = videoPromise || filePromise;\n  const fileCancel = filePromise.cancel?.bind(filePromise);\n  const videoCancel = videoPromise?.cancel?.bind(videoPromise);\n  progressSource.cancel = () => {\n    fileCancel?.();\n    videoCancel?.();\n  };\n  opts.onUploadStart?.(progressSource);\n\n  let file: InputFile, video: InputFile;\n  try {\n    [file, video] = await Promise.all([filePromise, videoPromise]);\n  } catch{\n    return; // cancelled or upload failed\n  }\n\n  if(mode === 'self') {\n    await managers.appProfileManager.uploadProfilePhoto({\n      file, video, videoStartTs: payload.videoStartTs\n    });\n  } else if(mode === 'fallback') {\n    await managers.appProfileManager.uploadProfilePhoto({\n      file, video, videoStartTs: payload.videoStartTs, fallback: true\n    });\n  } else {\n    await managers.appProfileManager.uploadContactProfilePhoto({\n      userId: mode.userId,\n      file, video, videoStartTs: payload.videoStartTs,\n      // \"Set photo for X\" (personal photo, only the current user sees it) needs\n      // save:true for the server to actually apply + persist it. Suggesting only\n      // sends the suggestion message (save stays false). Mirrors the official\n      // clients (Android: set → suggest=F/save=T; suggest → suggest=T/save=F).\n      suggest: mode.suggest || undefined,\n      save: mode.suggest ? undefined : true\n    });\n  }\n  opts.onUploaded?.();\n}\n\n// High-level helper: open the file picker + editor, then upload the result as a\n// contact photo (personal or suggested) or as the user's own fallback photo.\nexport function pickAvatarAndUpload(opts: {\n  managers: AppManagers;\n  isForum?: boolean;\n  mode: 'fallback' | {userId: UserId; suggest?: boolean};\n  onUploadStart?: (progress: CancellablePromise<InputFile>) => void;\n  onUploaded?: () => void;\n}) {\n  getFileAndOpenEditor({\n    isEditingForAvatar: true,\n    isEditingForumAvatar: opts.isForum,\n    acceptMediaTypes: ['photo', 'video'],\n    onFinish: ({editorResult}) => handleAvatarEditorResult({\n      result: editorResult,\n      managers: opts.managers,\n      mode: opts.mode,\n      onUploadStart: opts.onUploadStart,\n      onUploaded: opts.onUploaded\n    })\n  });\n}\n\n// High-level helper: download an existing photo, open the avatar editor on it,\n// and on confirm set the (edited) result as the user's OWN profile photo. Used\n// to accept a suggested profile photo on the receiving side.\nexport async function editAndSetOwnAvatar(opts: {\n  managers: AppManagers;\n  photo: Photo.photo;\n  isForum?: boolean;\n  onUploadStart?: (progress: CancellablePromise<InputFile>) => void;\n  onUploaded?: () => void;\n}) {\n  // Animated (video) suggested photo → download the full video variant and open\n  // the editor in video mode, so accepting keeps the animation. Static → image.\n  const videoSize = opts.photo.video_sizes?.length ? chooseProfileVideoSize(opts.photo, 'full') : undefined;\n  let file: File;\n  if(videoSize) {\n    const blob = await appDownloadManager.downloadMedia({media: opts.photo, thumb: videoSize});\n    file = new File([blob], 'suggested.mp4', {type: 'video/mp4'});\n  } else {\n    const size = choosePhotoSize(opts.photo, 1280, 1280, true);\n    const blob = await appDownloadManager.downloadMedia({media: opts.photo, thumb: size});\n    file = new File([blob], 'suggested.jpg', {type: blob.type || 'image/jpeg'});\n  }\n\n  return openAvatarEditorWithFile(file, {\n    isForum: opts.isForum,\n    onFinish: (editorResult) => handleAvatarEditorResult({\n      result: editorResult,\n      managers: opts.managers,\n      mode: 'self',\n      onUploadStart: opts.onUploadStart,\n      onUploaded: opts.onUploaded\n    })\n  });\n}\n\n// Opens the avatar media editor on an already-obtained file/blob (no picker).\n// Used when editing an existing photo (e.g. accepting a suggested profile photo).\nexport async function openAvatarEditorWithFile(\n  file: File | Blob,\n  {isForum, onFinish, dontCreatePreview}: {\n    isForum?: boolean;\n    dontCreatePreview?: boolean;\n    onFinish: (editorResult: MediaEditorFinalResult) => void;\n  }\n) {\n  const isVideo = file.type.startsWith('video/');\n\n  let mediaSrc: string;\n  if(isVideo) {\n    mediaSrc = URL.createObjectURL(file);\n  } else {\n    const imgResult = await createImageAndURLFromBlob(file);\n    if(!imgResult.ok) return;\n    mediaSrc = imgResult.url;\n  }\n\n  const {openMediaEditorFromMediaRaw} = await import('@components/mediaEditor');\n\n  openMediaEditorFromMediaRaw({\n    isEditingForAvatar: true,\n    isEditingForumAvatar: isForum,\n    isVideoAvatarMode: isVideo,\n    canFinishWithoutChanges: true,\n    canImageResultInGIF: false,\n    getMediaBlob: async() => file,\n    managers: rootScope.managers,\n    mediaSrc,\n    mediaType: isVideo ? 'video' : 'image',\n    initialTab: isVideo ? 'adjustments' : 'crop',\n    onEditFinish: onFinish,\n    dontCreatePreview,\n    onClose: () => revokeObjectURL(mediaSrc)\n  });\n}\n\nexport default class AvatarEdit {\n  public container: HTMLElement;\n  private canvas: HTMLCanvasElement;\n  private icon: HTMLSpanElement;\n\n  constructor(onChange: (payload: AvatarEditPayload) => void, options?: Options) {\n    this.container = document.createElement('div');\n    this.container.classList.add('avatar-edit');\n\n    this.canvas = document.createElement('canvas');\n    this.canvas.classList.add('avatar-edit-canvas');\n\n    this.icon = Icon('cameraadd', 'avatar-edit-icon');\n\n    this.container.append(this.canvas, this.icon);\n\n    attachClickEvent(this.container, () => {\n      getFileAndOpenEditor({\n        isEditingForAvatar: true,\n        isEditingForumAvatar: options?.isForum,\n        acceptMediaTypes: ['photo', 'video'],\n        onFinish: ({editorResult}) => {\n          finishFromResult({\n            result: editorResult,\n            onChange,\n            canvas: this.canvas\n          })\n        }\n      });\n    });\n  }\n\n  public clear() {\n    const ctx = this.canvas.getContext('2d');\n    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);\n  }\n}\n\ntype FinishFromResultArgs = {\n  result: MediaEditorFinalResult;\n  canvas: HTMLCanvasElement;\n  onChange: (payload: AvatarEditPayload) => void;\n};\n\nasync function finishFromResult({result: editorResult, canvas, onChange}: FinishFromResultArgs) {\n  // Video: don't block on the (real-time) encode here — fly the preview into the\n  // avatar and show the progress ring on the avatar itself, encoding in the bg.\n  if(editorResult.isVideo) {\n    await finishFromVideoResult({editorResult, canvas, onChange});\n    return;\n  }\n\n  const earlyDispose = () => {\n    editorResult.animatedPreview?.remove();\n  };\n\n  const resultPayload = await editorResult.getResult();\n\n  if(!editorResult.animatedPreview) return void earlyDispose();\n\n  const imgResult = await createImageAndURLFromBlob(resultPayload.blob);\n  if(!imgResult.ok) return earlyDispose();\n\n  const img = imgResult.img;\n\n  const animatedImg = editorResult.animatedPreview;\n  await animateImageToTarget({animatedImg, target: canvas, targetIsRound: true}).promise;\n\n  const [width, height] = snapToViewport(1, editorResult.width, editorResult.height);\n\n  [canvas.width, canvas.height] = [width, height];\n\n  const ctx = canvas.getContext('2d');\n  ctx.drawImage(img, 0, 0, width, height);\n  revokeObjectURL(imgResult.url);\n  ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';\n  ctx.fillRect(0, 0, width, height);\n\n  // Doing this now prevents the avatar blinking to the old one\n  onChange({\n    file: () => appDownloadManager.upload(resultPayload.blob)\n  });\n\n  await animatedImg.animate({\n    opacity: [1, 0]\n  }, {\n    duration: 200,\n    fill: 'forwards'\n  }).finished;\n\n  animatedImg.remove();\n}\n\nasync function finishFromVideoResult({\n  editorResult,\n  canvas,\n  onChange\n}: {\n  editorResult: MediaEditorFinalResult;\n  canvas: HTMLCanvasElement;\n  onChange: (payload: AvatarEditPayload) => void;\n}) {\n  // Fly the full-screen preview into the avatar circle straight away — we have\n  // the preview frame immediately, so there's no need to wait for the encode.\n  // The editor has already started closing.\n  const animatedImg = editorResult.animatedPreview;\n  let ringCleanup: (() => void) | undefined;\n  if(animatedImg) {\n    await animateImageToTarget({animatedImg, target: canvas, targetIsRound: true}).promise;\n    // Spin an encode-progress ring centered on the avatar while the video\n    // renders in the background, so nothing ever looks frozen.\n    ringCleanup = spawnAvatarProgressRing(animatedImg, editorResult.creationProgress);\n  }\n\n  // Now wait for the real-time video encode to finish (it was kicked off inside\n  // createFinalResult and keeps running after the editor closed).\n  let resultPayload: Awaited<ReturnType<MediaEditorFinalResult['getResult']>> | undefined;\n  try {\n    resultPayload = await editorResult.getResult();\n  } catch{}\n\n  if(!resultPayload?.thumb) {\n    ringCleanup?.();\n    animatedImg?.remove();\n    return;\n  }\n\n  const videoStartTs = computeVideoStartTs(editorResult);\n\n  // Paint the avatar canvas with the real cover thumb (sits behind the preview).\n  const thumbImg = await createImageAndURLFromBlob(resultPayload.thumb.blob);\n  if(thumbImg.ok) {\n    const [width, height] = snapToViewport(1, editorResult.width, editorResult.height);\n    [canvas.width, canvas.height] = [width, height];\n    const ctx = canvas.getContext('2d');\n    ctx.drawImage(thumbImg.img, 0, 0, width, height);\n    revokeObjectURL(thumbImg.url);\n    ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';\n    ctx.fillRect(0, 0, width, height);\n  }\n\n  onChange({\n    file: () => appDownloadManager.upload(resultPayload.thumb.blob, 'cover.jpg'),\n    video: () => appDownloadManager.upload(resultPayload.blob, 'avatar.mp4'),\n    videoStartTs\n  });\n\n  // Drop the ring and fade the preview out to reveal the canvas thumb.\n  ringCleanup?.();\n  if(animatedImg) {\n    await animatedImg.animate({\n      opacity: [1, 0]\n    }, {\n      duration: 200,\n      fill: 'forwards'\n    }).finished;\n    animatedImg.remove();\n  }\n}\n\n// Mounts a render-progress ring centered over `anchor` (the preview that has\n// just flown into the avatar). Returns a cleanup that unmounts it (tearing down\n// the reactive read of the progress signal).\nfunction spawnAvatarProgressRing(\n  anchor: HTMLElement,\n  creationProgress: MediaEditorFinalResult['creationProgress']\n): () => void {\n  if(!creationProgress) return () => {};\n\n  const bcr = anchor.getBoundingClientRect();\n  const container = document.createElement('div');\n  container.style.cssText =\n    `position:fixed;left:${bcr.left + bcr.width / 2}px;top:${bcr.top + bcr.height / 2}px;` +\n    `width:${bcr.width}px;height:${bcr.height}px;transform:translate(-50%, -50%);` +\n    'z-index:1001;pointer-events:none';\n  getOverlayRoot().append(container);\n\n  const dispose = render(() => RenderProgressCircle({creationProgress}), container);\n\n  return () => {\n    dispose();\n    container.remove();\n  };\n}\n","import AvatarEdit, {AvatarEditPayload} from '@components/avatarEdit';\nimport InputField from '@components/inputField';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ButtonCorner from '@components/buttonCorner';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport {Middleware} from '@helpers/middleware';\nimport {avatarNew} from '@components/avatarNew';\n\nexport default class EditPeer {\n  public nextBtn: HTMLButtonElement;\n\n  public uploadAvatar: AvatarEditPayload | undefined;\n  public avatarEdit: AvatarEdit;\n  public avatarElem: ReturnType<typeof avatarNew>;\n\n  private inputFields: InputField[];\n  private listenerSetter: ListenerSetter;\n\n  private peerId: PeerId;\n\n  private _disabled = false;\n  private avatarSize = 120;\n\n  constructor(options: {\n    peerId?: EditPeer['peerId'],\n    inputFields: EditPeer['inputFields'],\n    listenerSetter: ListenerSetter,\n    doNotEditAvatar?: boolean,\n    withoutAvatar?: boolean,\n    nextBtn?: HTMLButtonElement,\n    avatarSize?: number,\n    popupOptions?: ConstructorParameters<typeof AvatarEdit>[1],\n    middleware: Middleware\n  }) {\n    safeAssign(this, options);\n\n    this.peerId ||= NULL_PEER_ID;\n\n    if(!this.nextBtn) {\n      this.nextBtn = ButtonCorner({icon: 'check'});\n    } else if(!this.nextBtn.classList.contains('btn-corner')) {\n      this.handleChange = () => {\n        this.nextBtn.toggleAttribute('disabled', !this.isChanged() || this.disabled);\n      };\n    }\n\n    if(!options.withoutAvatar) {\n      this.avatarElem = avatarNew({\n        middleware: options.middleware,\n        size: this.avatarSize,\n        peerId: this.peerId\n      });\n      this.avatarElem.node.classList.add('avatar-placeholder');\n\n      if(!options.doNotEditAvatar) {\n        this.avatarEdit = new AvatarEdit((payload) => {\n          this.uploadAvatar = payload;\n          this.handleChange();\n          this.avatarElem.node.remove();\n        }, options.popupOptions);\n\n        this.avatarEdit.container.append(this.avatarElem.node);\n      }\n    }\n\n    this.inputFields.forEach((inputField) => {\n      this.listenerSetter.add(inputField.input)('input', this.handleChange);\n    });\n\n    this.handleChange();\n  }\n\n  public get disabled() {\n    return this._disabled;\n  }\n\n  public set disabled(value) {\n    this._disabled = value;\n    this.inputFields.forEach((inputField) => inputField.input.toggleAttribute('disabled', value));\n    this.handleChange();\n  }\n\n  public lockWithPromise(promise: Promise<any>, unlockOnSuccess = false) {\n    this.disabled = true;\n    promise.then(() => {\n      if(unlockOnSuccess) {\n        this.disabled = false;\n      }\n    }, () => {\n      this.disabled = false;\n    });\n  }\n\n  public isChanged = () => {\n    if(this.uploadAvatar) {\n      return true;\n    }\n\n    let changedLength = 0, requiredLength = 0, requiredValidLength = 0;\n    this.inputFields.forEach((inputField) => {\n      if(inputField.isValid()) {\n        if(inputField.isChanged()) {\n          ++changedLength;\n        }\n\n        if(inputField.required) {\n          ++requiredValidLength;\n        }\n      }\n\n      if(inputField.required) {\n        ++requiredLength;\n      }\n    });\n\n    return requiredLength === requiredValidLength && changedLength > 0;\n  };\n\n  public handleChange = () => {\n    this.nextBtn.classList.toggle('is-visible', this.isChanged());\n  };\n}\n","import PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\nimport {createSignal, onCleanup, onMount, untrack, useContext} from 'solid-js';\nimport InputField from '@components/inputField';\nimport TelInputField from '@components/telInputField';\nimport EditPeer from '@components/editPeer';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {formatPhoneNumber} from '@helpers/formatPhoneNumber';\nimport {toastNew} from '@components/toast';\nimport {i18n} from '@lib/langPack';\nimport ListenerSetter from '@helpers/listenerSetter';\n\nexport default function showCreateContactPopup(): void {\n  function Inner() {\n    const context = useContext(PopupContext);\n    const middleware = untrack(() => context.middlewareHelper).get();\n    const managers = untrack(() => context.managers);\n    const listenerSetter = new ListenerSetter();\n\n    const nameInputField = new InputField({\n      label: 'FirstName',\n      name: 'create-contact-name',\n      maxLength: 70,\n      required: true\n    });\n    nameInputField.container.classList.add('input-field-name');\n\n    const lastNameInputField = new InputField({\n      label: 'LastName',\n      name: 'create-contact-lastname',\n      maxLength: 70\n    });\n\n    const telInputField = new TelInputField({required: true});\n    telInputField.validate = () => {\n      return !!telInputField.value.match(/\\d/);\n    };\n\n    const inputFields: InputField[] = [nameInputField, lastNameInputField, telInputField];\n\n    let editPeer: EditPeer;\n    let confirmBtn!: HTMLButtonElement;\n\n    const [avatarNode, setAvatarNode] = createSignal<HTMLElement>();\n\n    const onInput = () => {\n      const name = nameInputField.value + ' ' + lastNameInputField.value;\n      editPeer.avatarElem.render({peerTitle: name});\n    };\n\n    listenerSetter.add(nameInputField.input)('input', onInput);\n    listenerSetter.add(lastNameInputField.input)('input', onInput);\n\n    const onConfirm = () => {\n      const promise = managers.appUsersManager.importContact(nameInputField.value, lastNameInputField.value, telInputField.value);\n\n      promise.then(() => {\n        context.hide();\n      }, (err: ApiError) => {\n        if(err.type === 'NO_USER') {\n          toastNew({langPackKey: 'Contacts.PhoneNumber.NotRegistred'});\n          editPeer.disabled = false;\n        }\n      });\n\n      editPeer.lockWithPromise(promise);\n    };\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    });\n\n    onMount(() => {\n      editPeer = new EditPeer({\n        inputFields,\n        listenerSetter,\n        doNotEditAvatar: true,\n        nextBtn: confirmBtn,\n        avatarSize: 100,\n        middleware\n      });\n      setAvatarNode(editPeer.avatarElem.node);\n\n      attachClickEvent(confirmBtn, onConfirm, {listenerSetter});\n      context.setBtnConfirmOnEnter(confirmBtn);\n\n      managers.appUsersManager.getSelf().then((user) => {\n        if(!middleware()) return;\n        const formatted = formatPhoneNumber(user.phone);\n        if(formatted.code) {\n          telInputField.value = '+' + formatted.code.country_code;\n        }\n      });\n    });\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title title=\"AddContactTitle\" />\n          <button ref={confirmBtn} class=\"btn-primary btn-color-primary\">{i18n('Add')}</button>\n        </PopupElement.Header>\n        <div class=\"name-fields\">\n          {nameInputField.container}\n          {lastNameInputField.container}\n          {avatarNode()}\n        </div>\n        {telInputField.container}\n      </>\n    );\n  }\n\n  createPopup(() => (\n    <PopupElement\n      class=\"popup-create-contact\"\n      closable={false}\n      old\n    >\n      <Inner />\n    </PopupElement>\n  ));\n}\n","import type SidebarSlider from '@components/slider';\nimport {AppAddMembersTab} from '@components/solidJsTabs/tabs';\nimport {AppNewGroupTab} from '@components/solidJsTabs/tabs';\n\nexport default function createNewGroupTab(slider: SidebarSlider) {\n  slider.createTab(AppAddMembersTab).open({\n    type: 'chat',\n    skippable: true,\n    takeOut: (peerIds) => slider.createTab(AppNewGroupTab).open({peerIds}),\n    title: 'GroupAddMembers',\n    placeholder: 'SendMessageTo'\n  });\n}\n","import {providedTabs} from '@components/solidJsTabs/providedTabs';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\nimport {\n  AppAddMembersTab,\n  AppChatBackgroundTab,\n  AppDirectMessagesTab,\n  AppEditProfileTab,\n  AppGeneralSettingsTab,\n  AppKeyboardShortcutsTab,\n  AppLanguageTab,\n  AppNotificationsTab,\n  AppPasscodeEnterPasswordTab,\n  AppPasscodeLockTab,\n  AppPrivacyMessagesTab,\n  AppPasskeysTab,\n  AppSettingsTab,\n  AppSpeakersAndCameraTab,\n  getEditProfileInitArgs\n} from '@components/solidJsTabs/tabs';\n\n\nSuperTabProvider.allTabs = providedTabs;\n\n\nexport {providedTabs};\n\nexport {\n  AppAddMembersTab,\n  AppChatBackgroundTab,\n  AppDirectMessagesTab,\n  AppEditProfileTab,\n  AppGeneralSettingsTab,\n  AppKeyboardShortcutsTab,\n  AppLanguageTab,\n  AppNotificationsTab,\n  AppPasscodeEnterPasswordTab,\n  AppPasscodeLockTab,\n  AppPrivacyMessagesTab,\n  AppPasskeysTab,\n  AppSettingsTab,\n  AppSpeakersAndCameraTab,\n  getEditProfileInitArgs\n};\n","import type {AppNewGroupTab} from '@components/solidJsTabs/tabs';\nimport {AppAddMembersTab, AppNotificationsTab, AppPasscodeEnterPasswordTab, AppPasscodeLockTab, AppPrivacyAndSecurityTab, AppUserPermissionsTab} from '@components/solidJsTabs/tabs';\n\n\nexport type ProvidedTabs = {\n  AppPasscodeLockTab: typeof AppPasscodeLockTab;\n  AppPasscodeEnterPasswordTab: typeof AppPasscodeEnterPasswordTab;\n  AppNotificationsTab: typeof AppNotificationsTab;\n  AppAddMembersTab: typeof AppAddMembersTab;\n  AppPrivacyAndSecurityTab: typeof AppPrivacyAndSecurityTab;\n  AppUserPermissionsTab: typeof AppUserPermissionsTab;\n\n  // Other non solid-js tabs\n  AppNewGroupTab: typeof AppNewGroupTab;\n};\n\n/**\n * To avoid circular imports, other tabs should be assigned elsewhere in the app (they can be assigned in the module of the tab itself)\n */\nexport const providedTabs = {\n  AppPasscodeLockTab,\n  AppPasscodeEnterPasswordTab,\n  AppNotificationsTab,\n  AppAddMembersTab,\n  AppPrivacyAndSecurityTab,\n  AppUserPermissionsTab\n\n  // Others to be assigned...\n} as ProvidedTabs;\n","import {createEffect, createSignal, For, onMount, Show} from 'solid-js';\nimport PopupElement from '@components/popups/indexTsx';\nimport {createPopup} from '@components/popups/indexTsx';\nimport {I18nTsx} from '@helpers/solid/i18n';\n\nimport {Birthday} from '@layer';\nimport {getMonths, getDaysPerMonthForYear, numberOfDaysEachMonth} from '@helpers/date';\nimport InputField from '@components/inputField';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {createButtonMenuSelect} from '@components/buttonMenuSelect';\nimport {IconTsx} from '@components/iconTsx';\n\nimport styles from '@components/popups/birthday.module.scss';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {AppPrivacyBirthdayTab} from '@components/solidJsTabs/tabs';\nimport rootScope from '@lib/rootScope';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {toastNew} from '@components/toast';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport LottieAnimation from '@components/lottieAnimation';\n\nconst MIN_YEAR = 1900;\n\ninterface MonthOption {\n  text: string;\n  value: number;\n}\n\nexport async function saveMyBirthday(date: Birthday | null) {\n  try {\n    await rootScope.managers.appProfileManager.setMyBirthday(date);\n    return true;\n  } catch(error) {\n    console.error(error);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n\nexport async function suggestUserBirthday(userId: UserId, date: Birthday) {\n  try {\n    await rootScope.managers.appProfileManager.suggestUserBirthday(userId, date);\n    return true;\n  } catch(error) {\n    console.error(error);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n\nexport default async function showBirthdayPopup(props: {\n  initialDate?: Birthday\n  suggestForPeer?: PeerId\n  fromProfile?: boolean\n  fromSuggestion?: boolean\n  onSave: (date: Birthday | null) => MaybePromise<boolean>\n}) {\n  const privacy = props.suggestForPeer ? null : await rootScope.managers.appPrivacyManager.getPrivacy('inputPrivacyKeyBirthday');\n  const isContactsOnly = !privacy || (\n    privacy.length === 2 &&\n    privacy[0]._ === 'privacyValueAllowContacts' &&\n    privacy[1]._ === 'privacyValueDisallowAll'\n  );\n\n  createPopup(() => {\n    const [show, setShow] = createSignal(false);\n    const [day, setDay] = createSignal<number | undefined>(props.initialDate?.day);\n    const [month, setMonth] = createSignal<MonthOption | undefined>();\n    const [year, setYear] = createSignal<number | undefined>(props.initialDate?.year);\n\n    const monthOptions = getMonths().map((m, idx) => ({text: m, value: idx + 1}));\n    if(props.initialDate?.month) {\n      setMonth(monthOptions[props.initialDate.month - 1]);\n    }\n\n    const daysPerMonth = (year$ = year()) => year$ ? getDaysPerMonthForYear(year$) : numberOfDaysEachMonth;\n\n    const dayField = new InputField({\n      label: 'BirthdayPopup.Day',\n      plainText: true\n    });\n    dayField.container.classList.add(styles.day);\n\n    const monthField = new InputField({\n      label: 'BirthdayPopup.Month',\n      plainText: true\n    });\n    monthField.container.classList.add(styles.month);\n\n    const yearField = new InputField({\n      label: 'BirthdayPopup.Year',\n      plainText: true\n    });\n    yearField.container.classList.add(styles.year);\n\n    if(props.initialDate?.day) {\n      dayField.setValueSilently(String(props.initialDate.day));\n    }\n    if(props.initialDate?.year) {\n      yearField.setValueSilently(String(props.initialDate.year));\n    }\n\n    const now = new Date();\n    const nowYear = now.getFullYear();\n    const nowMonth = now.getMonth() + 1;\n    const nowDay = now.getDate();\n\n    function updateDayInput() {\n      const value = dayField.value;\n      const cleanValue = value.replace(/[^0-9]/g, '');\n      if(!cleanValue) {\n        setDay(undefined);\n        return;\n      }\n\n      const month$ = month();\n\n      const valueNum = Number(cleanValue);\n      const daysInMonth = month$ ? daysPerMonth()[month$.value - 1] : 31;\n      if(yearField.value === String(nowYear) && month$.value === nowMonth && valueNum > nowDay) {\n        dayField.setValueSilently(nowDay.toString());\n        setDay(nowDay);\n      } else if(valueNum > daysInMonth) {\n        dayField.setValueSilently(daysInMonth.toString());\n        setDay(daysInMonth);\n      } else if(valueNum < 1) {\n        dayField.setValueSilently('1');\n        setDay(1);\n      } else {\n        setDay(valueNum);\n      }\n    }\n\n    dayField.input.addEventListener('input', updateDayInput);\n    monthField.input.addEventListener('beforeinput', (e) => cancelEvent(e));\n    monthField.input.addEventListener('paste', (e) => cancelEvent(e));\n\n    const {open: openMonthsMenu, close: closeMonthsMenu} = createButtonMenuSelect<MonthOption>({\n      class: styles.monthMenu,\n      direction: 'bottom-center',\n      get value() { return month() ? [month()] : [] },\n      onValueChange: (value) => {\n        setMonth(value[0])\n        monthField.input.focus()\n        updateDayInput()\n      },\n      get options() {\n        if(yearField.value === String(nowYear)) {\n          return monthOptions.filter((m) => m.value <= nowMonth)\n        }\n\n        return monthOptions\n      },\n      single: true,\n      optionKey: (v) => v.value.toString(),\n      renderOption: (props) => (\n        <>\n          <div class=\"btn-menu-item-text\">\n            {props.option.text}\n          </div>\n          {props.chosen && <IconTsx icon=\"check\" class=\"btn-menu-item-icon-right\" />}\n        </>\n      )\n    });\n    monthField.input.addEventListener('focus', () => openMonthsMenu(monthField.container));\n    monthField.input.addEventListener('click', () => openMonthsMenu(monthField.container));\n    monthField.input.addEventListener('blur', (e) => {\n      if((e.relatedTarget as HTMLElement)?.closest('.btn-menu')) return;\n      closeMonthsMenu();\n    });\n\n    yearField.input.addEventListener('input', () => {\n      const value = yearField.value;\n      const valueNum = Number(value);\n\n      if(isNaN(valueNum)) {\n        const cleanValue = value.replace(/[^0-9]/g, '');\n        yearField.setValueSilently(cleanValue);\n        setYear(Number(cleanValue));\n      } else if(value.length >= 4) {\n        if(valueNum < MIN_YEAR) {\n          yearField.setValueSilently(String(MIN_YEAR));\n          setYear(MIN_YEAR);\n        } else if(valueNum >= nowYear) {\n          yearField.setValueSilently(nowYear.toString());\n          setYear(nowYear);\n          if(month() && month().value > nowMonth) {\n            setMonth(monthOptions[nowMonth - 1])\n          }\n        } else {\n          setYear(valueNum);\n        }\n\n        updateDayInput()\n      } else {\n        setYear(undefined);\n      }\n    })\n    yearField.input.addEventListener('blur', () => {\n      const value = yearField.value;\n      if(value.length !== 4) yearField.value = '';\n    });\n\n    function openPrivacySettings() {\n      appSidebarLeft.createTab(AppPrivacyBirthdayTab).open();\n      setShow(false);\n    }\n\n    createEffect(() => {\n      const month$ = month();\n      if(month$) {\n        monthField.value = month$.text;\n      }\n    });\n\n    const doubleRafPromise = doubleRaf();\n\n    return (\n      <PopupElement class={styles.popup} containerClass={styles.popupContainer} show={show()}>\n        <PopupElement.Header class={styles.popupHeader}>\n          <PopupElement.CloseButton class={styles.popupCloseButton} />\n        </PopupElement.Header>\n        <PopupElement.Body class={styles.popupBody}>\n          <LottieAnimation\n            class={styles.img}\n            size={120}\n            lottieLoader={lottieLoader}\n            restartOnClick\n            name=\"UtyanBirthday\"\n            onPromise={(promise) => {\n              Promise.all([promise, doubleRafPromise]).then(([p]) => {\n                setShow(true);\n                p.playOrRestart()\n              });\n            }}\n          />\n\n          <I18nTsx\n            class={styles.title}\n            key={props.suggestForPeer ? 'BirthdayPopup.TitleForPeer' : 'BirthdayPopup.Title'}\n            args={[props.suggestForPeer ? <PeerTitleTsx peerId={props.suggestForPeer} /> : undefined]}\n          />\n\n          <div class={styles.datePicker}>\n            {dayField.container}\n            {monthField.container}\n            {yearField.container}\n          </div>\n\n          <Show when={!props.suggestForPeer}>\n            <div class={styles.privacyInfo}>\n              <I18nTsx\n                class={styles.privacyInfoText}\n                key={isContactsOnly ? 'BirthdayPopup.OnlyContacts' : 'BirthdayPopup.Choose'}\n                args={[\n                  <a class={styles.privacyInfoLink} onClick={openPrivacySettings}>\n                    <I18nTsx key={isContactsOnly ? 'BirthdayPopup.OnlyContactsLink' : 'BirthdayPopup.ChooseLink'} />\n                    <IconTsx icon=\"next\" />\n                  </a>\n                ]} />\n            </div>\n          </Show>\n        </PopupElement.Body>\n        <PopupElement.Footer class={styles.popupFooter}>\n          <Show when={props.fromSuggestion && props.initialDate.year}>\n            <PopupElement.FooterButton\n              langKey=\"BirthdayPopup.HideYear\"\n              color=\"secondary\"\n              callback={() => {\n                setYear(undefined);\n                yearField.setValueSilently('');\n                return false;\n              }}\n            />\n          </Show>\n          <Show when={props.fromProfile && props.initialDate}>\n            <PopupElement.FooterButton\n              langKey=\"BirthdayPopup.Remove\"\n              color=\"secondary\"\n              callback={async() => {\n                await props.onSave(null);\n                return true;\n              }}\n            />\n          </Show>\n          <PopupElement.FooterButton\n            disabled={!day() || !month()}\n            langKey={\n              props.fromSuggestion ? 'BirthdayPopup.SaveFromSuggestion' :\n              props.suggestForPeer ? 'BirthdayPopup.Suggest' : 'Save'}\n            callback={async() => {\n              if(!day() || !month()) return;\n              await props.onSave({_: 'birthday', day: day(), month: month().value, year: year()});\n              return true;\n            }}\n          />\n        </PopupElement.Footer>\n      </PopupElement>\n    );\n  });\n}\n","import {Chat} from '@layer';\nimport hasRights from '@appManagers/utils/chats/hasRights';\n\nexport default function canOpenBotAdminEditor(\n  chat: Chat.chat | Chat.channel,\n  participantMissing: boolean\n) {\n  return !participantMissing ||\n    (chat._ === 'channel' && !!chat.pFlags.broadcast) ||\n    hasRights(chat, 'invite_users');\n}\n","import {ChatAdminRights} from '@layer';\n\nexport default function hasBotAdminRights(rights?: ChatAdminRights) {\n  return !!rights && Object.keys(rights.pFlags).length > 0;\n}\n","import {User, UserFull} from '@layer';\nimport {REPLIES_PEER_ID, VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport hasBotAdminRights from '@appManagers/utils/bots/hasBotAdminRights';\nimport {LangPackKey} from '@lib/langPack';\n\nexport default function getAddBotToChatAction(\n  user: User.user,\n  userFull?: UserFull.userFull\n): {\n  text: LangPackKey,\n  about?: LangPackKey,\n  pickerTitle: LangPackKey\n} | undefined {\n  const userId = +user?.id;\n  if(\n    !user?.pFlags.bot ||\n    user.pFlags.support ||\n    userId === REPLIES_PEER_ID ||\n    userId === VERIFICATION_CODES_BOT_ID\n  ) {\n    return;\n  }\n\n  const canAddToGroup = !user.pFlags.bot_nochats;\n  const canManageGroup = hasBotAdminRights(userFull?.bot_group_admin_rights);\n  const canAddToChannel = hasBotAdminRights(userFull?.bot_broadcast_admin_rights);\n  if(!canAddToGroup && !canAddToChannel) {\n    return;\n  }\n\n  if(canAddToGroup && canAddToChannel) {\n    return {\n      text: 'BotAddToGroupOrChannel',\n      about: canManageGroup ? 'BotAddToGroupOrChannelAbout' : 'BotAddToChannelAbout',\n      pickerTitle: 'SelectChat'\n    };\n  }\n\n  if(canAddToChannel) {\n    return {\n      text: 'AddToChannel',\n      about: 'BotAddToChannelAbout',\n      pickerTitle: 'SelectChat'\n    };\n  }\n\n  return {\n    text: 'AddToGroup',\n    about: canManageGroup ? 'BotAddToGroupAbout' : undefined,\n    pickerTitle: 'BotChooseGroup'\n  };\n}\n","import {Chat, ChatAdminRights, UserFull} from '@layer';\nimport type {AddBotToChatScope} from '@appManagers/utils/bots/getBotAddToChatScope';\nimport hasBotAdminRights from '@appManagers/utils/bots/hasBotAdminRights';\n\nexport default function getBotAdminRightsForChat({\n  chat,\n  userFull,\n  scope,\n  requestedRights\n}: {\n  chat: Chat.chat | Chat.channel,\n  userFull: UserFull.userFull,\n  scope: AddBotToChatScope,\n  requestedRights?: ChatAdminRights\n}) {\n  if(scope === 'groupAdmin') {\n    if(chat._ === 'channel' && chat.pFlags.broadcast) {\n      return;\n    }\n\n    return hasBotAdminRights(requestedRights) ? requestedRights : userFull.bot_group_admin_rights;\n  }\n\n  if(scope === 'channelAdmin') {\n    if(chat._ !== 'channel' || !chat.pFlags.broadcast) {\n      return;\n    }\n\n    return hasBotAdminRights(requestedRights) ? requestedRights : userFull.bot_broadcast_admin_rights;\n  }\n\n  return chat._ === 'channel' && chat.pFlags.broadcast ?\n    userFull.bot_broadcast_admin_rights :\n    userFull.bot_group_admin_rights;\n}\n","import {ChatAdminRights} from '@layer';\n\nexport type BotAdminRight = keyof ChatAdminRights['pFlags'];\n\nexport const BOT_ADMIN_RIGHTS: BotAdminRight[] = [\n  'change_info',\n  'post_messages',\n  'edit_messages',\n  'delete_messages',\n  'ban_users',\n  'invite_users',\n  'pin_messages',\n  'add_admins',\n  'anonymous',\n  'manage_call',\n  'other',\n  'manage_topics',\n  'post_stories',\n  'edit_stories',\n  'delete_stories',\n  'manage_direct_messages',\n  'manage_ranks'\n];\n\nexport const BOT_ADMIN_RIGHTS_BY_LINK_NAME: Record<string, BotAdminRight> = {\n  change_info: 'change_info',\n  post_messages: 'post_messages',\n  edit_messages: 'edit_messages',\n  delete_messages: 'delete_messages',\n  restrict_members: 'ban_users',\n  invite_users: 'invite_users',\n  manage_topics: 'manage_topics',\n  pin_messages: 'pin_messages',\n  promote_members: 'add_admins',\n  post_stories: 'post_stories',\n  edit_stories: 'edit_stories',\n  delete_stories: 'delete_stories',\n  manage_video_chats: 'manage_call',\n  manage_direct_messages: 'manage_direct_messages',\n  anonymous: 'anonymous',\n  manage_chat: 'other'\n};\n","import {ChatAdminRights} from '@layer';\nimport {BOT_ADMIN_RIGHTS} from '@appManagers/utils/bots/constants';\n\nexport default function mergeBotAdminRights(\n  ...values: (ChatAdminRights | undefined)[]\n): ChatAdminRights {\n  const rights: ChatAdminRights = {\n    _: 'chatAdminRights',\n    pFlags: {}\n  };\n\n  BOT_ADMIN_RIGHTS.forEach((flag) => {\n    if(values.some((value) => value?.pFlags[flag])) {\n      rights.pFlags[flag] = true;\n    }\n  });\n\n  return rights;\n}\n","import {ChannelParticipant, Chat, ChatParticipant} from '@layer';\nimport {CHAT_LEGACY_ADMIN_RIGHTS} from '@appManagers/utils/chats/constants';\nimport {isParticipantAdmin} from '@appManagers/utils/chats/isParticipantAdmin';\nimport mergeBotAdminRights from '@appManagers/utils/bots/mergeBotAdminRights';\n\nexport default function getBotExistingAdminRights(\n  chat: Chat.chat | Chat.channel,\n  participant: ChatParticipant | ChannelParticipant\n) {\n  if(!isParticipantAdmin(participant)) {\n    return;\n  }\n\n  return mergeBotAdminRights(chat._ === 'chat' ?\n    CHAT_LEGACY_ADMIN_RIGHTS :\n    (participant as ChannelParticipant.channelParticipantAdmin | ChannelParticipant.channelParticipantCreator).admin_rights\n  );\n}\n","import {ChannelParticipant, Chat, ChatAdminRights, ChatParticipant, User} from '@layer';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport {isParticipantAdmin} from '@appManagers/utils/chats/isParticipantAdmin';\nimport appImManager from '@lib/appImManager';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport appSidebarRight from '@components/sidebarRight';\nimport confirmationPopup from '@components/confirmationPopup';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport {openUserPermissionsTab} from '@components/solidJsTabs/tabs';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport type {AddBotToChatScope} from '@appManagers/utils/bots/getBotAddToChatScope';\nimport canOpenBotAdminEditor from '@appManagers/utils/bots/canOpenBotAdminEditor';\nimport getAddBotToChatAction from '@appManagers/utils/bots/getAddBotToChatAction';\nimport getBotAdminRightsForChat from '@appManagers/utils/bots/getBotAdminRightsForChat';\nimport getBotExistingAdminRights from '@appManagers/utils/bots/getBotExistingAdminRights';\nimport hasBotAdminRights from '@appManagers/utils/bots/hasBotAdminRights';\nimport mergeBotAdminRights from '@appManagers/utils/bots/mergeBotAdminRights';\nimport tsNow from '@helpers/tsNow';\n\nfunction makeMissingParticipant(\n  chat: Chat.chat | Chat.channel,\n  botId: BotId\n): ChatParticipant.chatParticipant | ChannelParticipant.channelParticipant {\n  const date = tsNow(true);\n  if(chat._ === 'channel') {\n    return {\n      _: 'channelParticipant',\n      user_id: botId,\n      date\n    };\n  }\n\n  return {\n    _: 'chatParticipant',\n    user_id: botId,\n    inviter_id: rootScope.myId.toUserId(),\n    date\n  };\n}\n\nasync function getParticipantOrMissing(chat: Chat.chat | Chat.channel, botId: BotId) {\n  try {\n    return {\n      participant: await rootScope.managers.appProfileManager.getParticipant(chat.id, botId.toPeerId(false)),\n      missing: false\n    };\n  } catch(err) {\n    if((err as ApiError)?.type !== 'USER_NOT_PARTICIPANT') {\n      throw err;\n    }\n\n    return {\n      participant: makeMissingParticipant(chat, botId),\n      missing: true\n    };\n  }\n}\n\nexport default async function showAddBotToChat(options: {\n  botId: BotId,\n  scope?: AddBotToChatScope,\n  startParam?: string,\n  requestedRights?: ChatAdminRights\n}) {\n  const scope = options.scope ?? 'all';\n  const [user, userFull] = await Promise.all([\n    rootScope.managers.appUsersManager.getUser(options.botId) as Promise<User.user>,\n    rootScope.managers.appProfileManager.getProfile(options.botId)\n  ]);\n  const action = getAddBotToChatAction(user, userFull);\n  if(scope === 'all' && !action) {\n    return;\n  }\n\n  const getRights = (chat: Chat.chat | Chat.channel) => getBotAdminRightsForChat({\n    chat,\n    userFull,\n    scope,\n    requestedRights: options.requestedRights\n  });\n\n  return showPickUserPopup({\n    titleLangKey: scope === 'groupAdmin' ? 'BotChooseGroup' : action?.pickerTitle || 'SelectChat',\n    placeholder: 'SelectChat',\n    peerType: ['dialogs'],\n    filterPeerTypeBy: (peer) => {\n      if(peer._ !== 'chat' && peer._ !== 'channel') {\n        return false;\n      }\n\n      const isBroadcast = peer._ === 'channel' && !!peer.pFlags.broadcast;\n      const canAddAsAdmin = hasBotAdminRights(getRights(peer)) && hasRights(peer, 'add_admins');\n      if(scope === 'groupAdmin') {\n        return !isBroadcast && canAddAsAdmin;\n      }\n\n      if(scope === 'channelAdmin') {\n        return isBroadcast && canAddAsAdmin;\n      }\n\n      if(isBroadcast) {\n        return canAddAsAdmin;\n      }\n\n      return canAddAsAdmin || (!user.pFlags.bot_nochats && hasRights(peer, 'invite_users'));\n    },\n    onSelect: async(chosen) => {\n      const peerId = chosen[0].peerId;\n      const chatId = peerId.toChatId();\n      const chat = apiManagerProxy.getChat(chatId) as Chat.chat | Chat.channel;\n      const isBroadcast = chat._ === 'channel' && !!chat.pFlags.broadcast;\n      const rights = getRights(chat);\n      const canAddAsAdmin = hasBotAdminRights(rights) && hasRights(chat, 'add_admins');\n\n      if(canAddAsAdmin) {\n        const {participant, missing} = await getParticipantOrMissing(chat, options.botId);\n        if(!canOpenBotAdminEditor(chat, missing)) {\n          toastNew({langPackKey: 'Error.RequestPeer.NoRights.Group'});\n          return;\n        }\n\n        const existingAdminRights = getBotExistingAdminRights(chat, participant);\n        const initialAdminRights = mergeBotAdminRights(rights, existingAdminRights);\n\n        openUserPermissionsTab(appSidebarRight, chatId, participant, true, {\n          initialAdminRights,\n          existingAdminRights,\n          addingBot: {\n            startParam: options.startParam,\n            sendStartAfterAdmin: scope === 'groupAdmin',\n            existingAdmin: isParticipantAdmin(participant)\n          }\n        });\n        appSidebarRight.toggleSidebar(true);\n        return;\n      }\n\n      await confirmationPopup({\n        titleLangKey: 'AddOneMemberAlertTitle',\n        descriptionLangKey: 'AddMembersAlertNamesText',\n        descriptionLangArgs: [\n          await wrapPeerTitle({peerId: options.botId.toPeerId(false)}),\n          await wrapPeerTitle({peerId})\n        ],\n        button: {\n          langKey: 'Add'\n        }\n      });\n      await rootScope.managers.appMessagesManager.addBotToChat(\n        options.botId,\n        chatId,\n        options.startParam\n      );\n      appImManager.setInnerPeer({peerId});\n    }\n  });\n}\n","import {ChatAdminRights} from '@layer';\nimport hasBotAdminRights from '@appManagers/utils/bots/hasBotAdminRights';\n\nexport type AddBotToChatScope = 'all' | 'groupAdmin' | 'channelAdmin';\n\nexport default function getBotAddToChatScope(\n  link: {startgroup?: string, startchannel?: string},\n  requestedRights?: ChatAdminRights\n): AddBotToChatScope | undefined {\n  if(link.startgroup !== undefined) {\n    return hasBotAdminRights(requestedRights) ? 'groupAdmin' : 'all';\n  }\n\n  if(link.startchannel !== undefined) {\n    return 'channelAdmin';\n  }\n}\n","import {ChatAdminRights} from '@layer';\nimport {BOT_ADMIN_RIGHTS_BY_LINK_NAME} from '@appManagers/utils/bots/constants';\n\nexport default function parseBotAdminRights(value?: string): ChatAdminRights {\n  const rights: ChatAdminRights = {\n    _: 'chatAdminRights',\n    pFlags: {}\n  };\n\n  value?.split(/[+ ]/).forEach((name) => {\n    const flag = BOT_ADMIN_RIGHTS_BY_LINK_NAME[name];\n    if(flag) {\n      rights.pFlags[flag] = true;\n    }\n  });\n\n  return rights;\n}\n","import {isUsernameValid} from '@lib/richTextProcessor/validators';\n\nexport default function parseChatSpecificTag(value: string) {\n  const prefix = value[0] === '$' ? '$' : '#';\n  const tag = prefix === '$' ? value.slice(1) : value;\n  const separatorIndex = tag.indexOf('@');\n  const username = separatorIndex > 0 ? tag.slice(separatorIndex + 1) : undefined;\n\n  if(!username || !isUsernameValid(username)) {\n    return {query: prefix + tag};\n  }\n\n  return {\n    query: prefix + tag.slice(0, separatorIndex),\n    username\n  };\n}\n","export default async function searchByTag<T>(options: {\n  query: string,\n  username?: string,\n  activateSearch: (query: string) => void,\n  resolveUsername: (username: string) => MaybePromise<T>,\n  openPeer: (peer: T) => MaybePromise<unknown>,\n  isCurrent: () => boolean,\n  onResolveError: (err: unknown) => void\n}) {\n  options.activateSearch(options.query);\n  if(!options.username) {\n    return;\n  }\n\n  let peer: T;\n  try {\n    peer = await options.resolveUsername(options.username);\n  } catch(err) {\n    if(options.isCurrent()) {\n      options.onResolveError(err);\n    }\n\n    return;\n  }\n\n  if(!options.isCurrent()) {\n    return;\n  }\n\n  await options.openPeer(peer);\n  if(options.isCurrent()) {\n    options.activateSearch(options.query);\n  }\n}\n","import type AppMediaViewerBase from '@components/mediaViewer/base';\nimport PopupElement from '@components/popups';\nimport PopupSharedFolderInvite from '@components/popups/sharedFolderInvite';\nimport PopupJoinChatInvite from '@components/popups/joinChatInvite';\nimport PopupPayment from '@components/popups/payment';\nimport PopupPeer from '@components/popups/peer';\nimport {showPickUser3Popup, showSharingPicker2Popup} from '@components/popups/pickUser';\nimport showStickersPopup from '@components/popups/stickers';\nimport {toastNew, hideToast} from '@components/toast';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport {CONFERENCE_CALL_SLUG_REGEXP} from '@lib/calls/constants';\nimport addAnchorListener from '@helpers/addAnchorListener';\nimport assumeType from '@helpers/assumeType';\nimport findUpAttribute from '@helpers/dom/findUpAttribute';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {User, AttachMenuPeerType, MessagesBotApp, BotApp, ChatlistsChatlistInvite, Chat, InputInvoice} from '@layer';\nimport {i18n, LangPackKey, _i18n} from '@lib/langPack';\nimport {PHONE_NUMBER_REG_EXP} from '@lib/richTextProcessor';\nimport {isWebAppNameValid} from '@lib/richTextProcessor/validators';\nimport appImManager, {APP_TABS, JoinConferenceOptions} from '@lib/appImManager';\nimport {makeFullMid} from '@appManagers/utils/messages/fullMid';\nimport {INTERNAL_LINK_TYPE, InternalLinkTypeMap, InternalLink} from '@lib/internalLink';\nimport {AppManagers} from '@lib/managers';\nimport {createStoriesViewerWithPeer} from '@components/stories/viewer';\nimport {simulateClickEvent} from '@helpers/dom/clickEvent';\nimport shake from '@helpers/dom/shake';\nimport PopupPremium from '@components/popups/premium';\nimport rootScope from '@lib/rootScope';\nimport PopupBoost from '@components/popups/boost';\nimport PopupGiftLink from '@components/popups/giftLink';\nimport PopupStars, {showGiftStarsPicker} from '@components/popups/stars';\nimport PopupSendGift from '@components/popups/sendGift';\nimport showSendGiftPicker from '@components/popups/sendGiftPicker';\nimport type {RequestWebViewOptions} from '@appManagers/appAttachMenuBotsManager';\nimport {prefetchStars} from '@stores/stars';\nimport {getMiddleware} from '@helpers/middleware';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupStarGiftInfo from '@components/popups/starGiftInfo';\nimport noop from '@helpers/noop';\nimport appSidebarRight from '@components/sidebarRight';\nimport pause from '@helpers/schedulers/pause';\nimport namedPromises from '@helpers/namedPromises';\nimport {openInstantViewInAppBrowser} from '@components/browser';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {AppContactsTab} from '@components/solidJsTabs/tabs';\nimport {AppNewChannelTab} from '@components/solidJsTabs/tabs';\nimport showCreateContactPopup from '@components/popups/createContact';\nimport createNewGroupTab from '@components/sidebarLeft/tabs/createNewGroupTab';\nimport {AppEditProfileTab, AppSettingsTab, getEditProfileInitArgs} from '@components/solidJsTabs';\nimport showBirthdayPopup, {saveMyBirthday} from '@components/popups/birthday';\nimport {getStickerSetInputByShortName} from '@lib/appManagers/utils/stickers/getStickerSetInput';\nimport {AppMyStoriesTab} from '@components/solidJsTabs/tabs';\nimport showAddBotToChat from '@components/popups/addBotToChat';\nimport getBotAddToChatScope from '@appManagers/utils/bots/getBotAddToChatScope';\nimport parseBotAdminRights from '@appManagers/utils/bots/parseBotAdminRights';\nimport isEphemeralMessage from '@appManagers/utils/messages/isEphemeralMessage';\nimport parseChatSpecificTag from '@lib/richTextProcessor/parseChatSpecificTag';\nimport searchByTag from '@lib/richTextProcessor/searchByTag';\n\nexport class InternalLinkProcessor {\n  protected managers: AppManagers;\n  private processingAddAiStyleSlugs: Set<string> = new Set();\n  private tagSearchVersion = 0;\n\n  private showUsernameResolveError(err: ApiError) {\n    if(err.type === 'USERNAME_NOT_OCCUPIED') {\n      toastNew({langPackKey: 'NoUsernameFound'});\n    } else if(err.type === 'USERNAME_INVALID') {\n      toastNew({langPackKey: 'Alert.UserDoesntExists'});\n    }\n  }\n\n  public construct(managers: AppManagers) {\n    this.managers = managers;\n\n    addAnchorListener<{}>({\n      name: 'showMaskedAlert',\n      callback: ({element}) => {\n        const href = element.href;\n\n        const a = element.cloneNode(true) as HTMLAnchorElement;\n        a.className = 'anchor-url';\n        a.innerText = href;\n        a.removeAttribute('onclick');\n\n        const popup = PopupElement.createPopup(PopupPeer, 'popup-masked-url', {\n          titleLangKey: 'OpenUrlTitle',\n          descriptionLangKey: 'OpenUrlAlert2',\n          descriptionLangArgs: [a],\n          buttons: [{\n            langKey: 'Open',\n            callback: () => {\n              a.click();\n            }\n          }]\n        })\n\n        popup.show();\n        return popup;\n      }\n    });\n\n    addAnchorListener<{uriParams: {command: string, bot: string}}>({\n      name: 'execBotCommand',\n      callback: ({element, uriParams}) => {\n        const {command, bot} = uriParams;\n        const chat = appImManager.chat;\n        let sendingParams = chat.input?.getEphemeralSendingSnapshot() || {\n          peerId: chat.peerId\n        };\n        const bubble = findUpClassName(element, 'bubble');\n        if(\n          bubble?.dataset.mid &&\n          bubble.dataset.peerId?.toPeerId() === chat.peerId\n        ) {\n          const message = chat.getMessage(+bubble.dataset.mid);\n          if(isEphemeralMessage(message)) {\n            sendingParams = {\n              ephemeral: true,\n              peerId: chat.peerId,\n              threadId: chat.threadId,\n              replyToMsgId: message.mid\n            };\n          }\n        }\n\n        /* const promise = bot ? this.openUsername(bot).then(() => this.chat.peerId) : Promise.resolve(this.chat.peerId);\n        promise.then((peerId) => {\n          this.managers.appMessagesManager.sendText(peerId, '/' + command);\n        }); */\n\n        return this.managers.appMessagesManager.sendText({\n          ...sendingParams,\n          text: '/' + command + (bot ? '@' + bot : '')\n        });\n      }\n    });\n\n    addAnchorListener<{uriParams: {hashtag: string}}>({\n      name: 'searchByHashtag',\n      callback: ({uriParams}) => {\n        const {hashtag} = uriParams;\n        if(!hashtag) {\n          return;\n        }\n\n        const search = parseChatSpecificTag(hashtag);\n        const version = ++this.tagSearchVersion;\n        return searchByTag({\n          query: search.query + ' ',\n          username: search.username,\n          activateSearch: (query) => appImManager.chat.initSearch({query, focus: true}),\n          resolveUsername: (username) => this.managers.appUsersManager.resolveUsername(username),\n          openPeer: (peer) => appImManager.setInnerPeer({\n            peerId: peer.id.toPeerId(peer._ !== 'user')\n          }),\n          isCurrent: () => version === this.tagSearchVersion,\n          onResolveError: (err) => {\n            appImManager.chat.resetSearch();\n            this.showUsernameResolveError(err as ApiError);\n          }\n        });\n      }\n    });\n\n    addAnchorListener<{}>({\n      name: 'setMediaTimestamp',\n      callback: ({element}) => {\n        const timestamp = +element.dataset.timestamp;\n        const bubble = findUpClassName(element, 'bubble');\n        if(bubble) {\n          appImManager.chat.bubbles.playMediaWithTimestamp(element, timestamp);\n          return;\n        }\n\n        if(findUpClassName(element, 'media-viewer-caption')) {\n          const appMediaViewer = (window as any).appMediaViewer as AppMediaViewerBase<any, any, any>;\n          return appMediaViewer.setMediaTimestamp(timestamp);\n        }\n      }\n    });\n\n    ([\n      ['addstickers', INTERNAL_LINK_TYPE.STICKER_SET],\n      ['addemoji', INTERNAL_LINK_TYPE.EMOJI_SET]\n    ] as [\n      'addstickers' | 'addemoji',\n      INTERNAL_LINK_TYPE.STICKER_SET | INTERNAL_LINK_TYPE.EMOJI_SET\n    ][]).forEach(([name, type]) => {\n      addAnchorListener<{pathnameParams: [typeof name, string]}>({\n        name,\n        callback: ({pathnameParams}) => {\n          if(!pathnameParams[1]) {\n            return;\n          }\n\n          const link: InternalLink = {\n            _: type,\n            set: pathnameParams[1]\n          };\n\n          return this.processInternalLink(link);\n        }\n      });\n\n      addAnchorListener<{\n        uriParams: {\n          set: string\n        }\n      }>({\n        name,\n        protocol: 'tg',\n        callback: ({uriParams}) => {\n          const link = this.makeLink(type, uriParams);\n          return this.processInternalLink(link);\n        }\n      });\n    });\n\n    // * t.me/invoice/asdasdad\n    // * t.me/$asdasdad\n    addAnchorListener<{pathnameParams: ['invoice', string] | string}>({\n      name: 'invoice',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.INVOICE,\n          slug: pathnameParams.length > 1 ? pathnameParams[1] : pathnameParams[0].slice(1)\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/addlist/adasdasd\n    addAnchorListener<{pathnameParams: ['folder', string]}>({\n      name: 'addlist',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.ADD_LIST,\n          slug: pathnameParams[1]\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // Support old t.me/joinchat/asd and new t.me/+asd\n    addAnchorListener<{pathnameParams: ['joinchat', string]}>({\n      name: 'joinchat',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.JOIN_CHAT,\n          invite: pathnameParams[1] || decodeURIComponent(pathnameParams[0]).slice(1)\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    if(IS_GROUP_CALL_SUPPORTED) {\n      addAnchorListener<{\n        uriParams: Omit<InternalLink.InternalLinkVoiceChat, '_'>\n      }>({\n        name: 'voicechat',\n        protocol: 'tg',\n        callback: ({uriParams}) => {\n          const link = this.makeLink(INTERNAL_LINK_TYPE.VOICE_CHAT, uriParams);\n          return this.processInternalLink(link);\n        }\n      });\n\n      // t.me/call/<slug> — TdE2E conference invite link. tdesktop maps this\n      // to `tg://call?slug=<slug>` (local_url_handlers.cpp:1967) and then to\n      // `ResolveConferenceCall` (window_session_controller.cpp:977). Here we\n      // resolve the slug straight into `joinConference` since the controller\n      // already does the chain-head poll itself.\n      addAnchorListener<{pathnameParams: ['call', string]}>({\n        name: 'call',\n        callback: ({pathnameParams, element, event}) => {\n          if(!pathnameParams[1]) return;\n          const link: InternalLink = {\n            _: INTERNAL_LINK_TYPE.CONFERENCE_CALL,\n            slug: pathnameParams[1]\n          };\n          // Straight to the handler rather than through `processInternalLink`:\n          // this is the only place that still knows WHICH message the link was\n          // clicked in, and the join confirmation names its sender.\n          return this.processConferenceCallLink(link, {\n            inviterPeerId: this.getClickedMessageSenderPeerId(element, event)\n          });\n        }\n      });\n\n      // tg://call?slug=<slug>\n      addAnchorListener<{uriParams: {slug: string}}>({\n        name: 'call',\n        protocol: 'tg',\n        callback: ({uriParams}) => {\n          if(!uriParams.slug) return;\n          const link = this.makeLink(INTERNAL_LINK_TYPE.CONFERENCE_CALL, uriParams);\n          return this.processInternalLink(link);\n        }\n      });\n    }\n\n    type K1 = {thread?: string, comment?: string, t?: string, option?: string};\n    type K2 = {thread?: string, comment?: string, start?: string, startgroup?: string, startchannel?: string, admin?: string, t?: string, text?: string, option?: string};\n    type K3 = {startattach?: string, attach?: string, choose?: TelegramChoosePeerType};\n    type K4 = {startapp?: string, mode?: 'compact' | 'fullscreen'};\n    type K5 = {story?: string};\n    type K6 = {boost?: string};\n    type K7 = {voicechat?: string, videochat?: string, livestream?: string};\n    type K8 = {text?: string};\n\n    addAnchorListener<{\n    //   pathnameParams: ['c', string, string],\n    //   uriParams: {thread?: number}\n    // } | {\n    //   pathnameParams: [string, string?],\n    //   uriParams: {comment?: number}\n      pathnameParams: ['c', string, string] | [string, string?],\n      uriParams: K1 | K2 | K3 | K4 | K5 | K6 | K7 | K8\n    }>({\n      name: 'im',\n      callback: async({pathnameParams, uriParams, element, masked}) => {\n        let link: InternalLink;\n        if('voicechat' in uriParams || 'videochat' in uriParams || 'livestream' in uriParams) {\n          assumeType<K7>(uriParams);\n          link = {\n            _: INTERNAL_LINK_TYPE.VOICE_CHAT,\n            domain: pathnameParams[0],\n            ...uriParams\n          };\n        } else if('boost' in uriParams || pathnameParams?.[0] === 'boost') {\n          const channel = pathnameParams?.[0] === 'c' ? pathnameParams[1] : (uriParams as any).c;\n          link = {\n            _: INTERNAL_LINK_TYPE.BOOST,\n            domain: channel ? undefined : ('boost' in uriParams ? pathnameParams[0] : pathnameParams[1]),\n            channel\n          };\n        } else if(pathnameParams?.[1] === 's') {\n          link = {\n            _: INTERNAL_LINK_TYPE.STORY,\n            domain: pathnameParams[0],\n            story: pathnameParams[2]\n          };\n        } else if(pathnameParams?.[1] === 'c') {\n          link = {\n            _: INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION,\n            domain: pathnameParams[0],\n            id: pathnameParams[2]\n          };\n        } else if(pathnameParams?.[1] === 'a') {\n          link = {\n            _: INTERNAL_LINK_TYPE.STORY_ALBUM,\n            domain: pathnameParams[0],\n            id: pathnameParams[2]\n          };\n        } else if(PHONE_NUMBER_REG_EXP.test(pathnameParams[0])) {\n          link = {\n            _: INTERNAL_LINK_TYPE.USER_PHONE_NUMBER,\n            phone: pathnameParams[0],\n            text: (uriParams as K8).text\n          };\n        } else if(pathnameParams[0] === 'c') {\n          assumeType<K1>(uriParams);\n          pathnameParams.shift();\n          const thread = 'thread' in uriParams ? uriParams.thread : pathnameParams[2] && pathnameParams[1];\n          link = {\n            _: INTERNAL_LINK_TYPE.PRIVATE_POST,\n            channel: pathnameParams[0],\n            post: pathnameParams[2] || pathnameParams[1],\n            thread,\n            comment: uriParams.comment,\n            option: 'option' in uriParams ? uriParams.option : undefined,\n            stack: appImManager.getStackFromElement(element),\n            t: uriParams.t\n          };\n        } else if(pathnameParams[1] ? isWebAppNameValid(pathnameParams[1]) : (uriParams as K4).startapp !== undefined) {\n          assumeType<K4>(uriParams);\n          link = {\n            _: INTERNAL_LINK_TYPE.WEB_APP,\n            domain: pathnameParams[0],\n            appname: pathnameParams[1],\n            startapp: uriParams.startapp,\n            masked,\n            mode: uriParams.mode\n          };\n        } else {\n          assumeType<K2>(uriParams);\n          const thread = 'thread' in uriParams ? uriParams.thread : pathnameParams[2] && pathnameParams[1];\n          link = {\n            _: INTERNAL_LINK_TYPE.MESSAGE,\n            domain: pathnameParams[0],\n            post: pathnameParams[2] || pathnameParams[1],\n            thread,\n            comment: uriParams.comment,\n            start: 'start' in uriParams ? uriParams.start : undefined,\n            startgroup: 'startgroup' in uriParams ? uriParams.startgroup : undefined,\n            startchannel: 'startchannel' in uriParams ? uriParams.startchannel : undefined,\n            admin: 'admin' in uriParams ? uriParams.admin : undefined,\n            option: 'option' in uriParams ? uriParams.option : undefined,\n            stack: appImManager.getStackFromElement(element),\n            t: uriParams.t,\n            text: uriParams.text\n          };\n        }\n\n        if('startattach' in uriParams || 'attach' in uriParams) {\n          assumeType<K3>(uriParams);\n          link = {\n            _: INTERNAL_LINK_TYPE.ATTACH_MENU_BOT,\n            nestedLink: link,\n            ...uriParams\n          };\n        }\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    addAnchorListener<{\n      uriParams: {\n        domain: string,\n\n        // telegrampassport\n        scope?: string,\n        nonce?: string,\n        payload?: string,\n        bot_id?: string,\n        public_key?: string,\n        callback_url?: string,\n\n        // regular\n        start?: string,\n        startgroup?: string,\n        startchannel?: string,\n        admin?: string,\n        game?: string,\n        voicechat?: string,\n        videochat?: string,\n        livestream?: string,\n        post?: string,\n        thread?: string,\n        comment?: string,\n        phone?: string,\n        t?: string,\n        attach?: string,\n        startattach?: string,\n        choose?: TelegramChoosePeerType,\n        appname?: string,\n        startapp?: string,\n        compact?: string,\n        story?: string\n      }\n    }>({\n      name: 'resolve',\n      protocol: 'tg',\n      callback: ({uriParams, element, masked}) => {\n        let link: InternalLink;\n        if(uriParams.voicechat !== undefined || uriParams.videochat !== undefined || uriParams.livestream !== undefined) {\n          link = this.makeLink(INTERNAL_LINK_TYPE.VOICE_CHAT, uriParams as Required<typeof uriParams>);\n        } else if(uriParams.story) {\n          link = this.makeLink(INTERNAL_LINK_TYPE.STORY, uriParams as Required<typeof uriParams>);\n        } else if(uriParams.phone) {\n          link = this.makeLink(INTERNAL_LINK_TYPE.USER_PHONE_NUMBER, uriParams as Required<typeof uriParams>);\n        } else if(uriParams.domain === 'telegrampassport') {\n\n        } else if((uriParams.appname || uriParams.startapp) !== undefined) {\n          link = this.makeLink(INTERNAL_LINK_TYPE.WEB_APP, {\n            masked,\n            ...uriParams as Required<typeof uriParams>\n          });\n        } else {\n          link = this.makeLink(INTERNAL_LINK_TYPE.MESSAGE, {\n            ...uriParams,\n            stack: appImManager.getStackFromElement(element)\n          });\n        }\n\n        if(uriParams.attach !== undefined || uriParams.startattach !== undefined) {\n          const nestedLink = link;\n          link = this.makeLink(INTERNAL_LINK_TYPE.ATTACH_MENU_BOT, uriParams as Required<typeof uriParams>);\n          link.nestedLink = nestedLink;\n        }\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    addAnchorListener<{\n      uriParams: {\n        channel: string,\n        post: string,\n        thread?: string,\n        comment?: string\n      }\n    }>({\n      name: 'privatepost',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.PRIVATE_POST, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://invoice?slug=asdasd\n    addAnchorListener<{\n      uriParams: {\n        slug: string\n      }\n    }>({\n      name: 'invoice',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.INVOICE, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://addlist?slug=asd\n    addAnchorListener<{\n      uriParams: {\n        slug: string\n      }\n    }>({\n      name: 'addlist',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.ADD_LIST, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    ['joinchat' as const, 'join' as const].forEach((name) => {\n      addAnchorListener<{\n        uriParams: {\n          invite: string\n        }\n      }>({\n        name,\n        protocol: 'tg',\n        callback: ({uriParams}) => {\n          const link = this.makeLink(INTERNAL_LINK_TYPE.JOIN_CHAT, uriParams);\n          return this.processInternalLink(link);\n        }\n      });\n    });\n\n    // tg://boost?channel=123 tg://boost?domain=username\n    addAnchorListener<{\n      uriParams: {\n        channel?: string,\n        domain?: string\n      }\n    }>({\n      name: 'boost',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.BOOST, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/boost/adasdasd\n    addAnchorListener<{pathnameParams: ['boost', string]}>({\n      name: 'boost',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.BOOST,\n          domain: pathnameParams[1]\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://premium_offer?ref=premium tg://premium_offer\n    addAnchorListener<{\n      uriParams: {\n        ref?: string\n      }\n    }>({\n      name: 'premium_offer',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.PREMIUM_FEATURES, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/giftcode/slug\n    addAnchorListener<{pathnameParams: ['giftcode', string]}>({\n      name: 'giftcode',\n      callback: ({pathnameParams, element}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.GIFT_CODE,\n          slug: pathnameParams[1],\n          stack: appImManager.getStackFromElement(element)\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://giftcode?slug=...\n    addAnchorListener<{\n      uriParams: {\n        slug: string\n      }\n    }>({\n      name: 'giftcode',\n      protocol: 'tg',\n      callback: ({uriParams, element}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.GIFT_CODE, uriParams);\n        link.stack = appImManager.getStackFromElement(element);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/m/slug\n    addAnchorListener<{pathnameParams: ['m', string]}>({\n      name: 'm',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.BUSINESS_CHAT,\n          slug: pathnameParams[1]\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://message?slug=...\n    addAnchorListener<{\n      uriParams: {\n        slug: string\n      }\n    }>({\n      name: 'message',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.BUSINESS_CHAT, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://stars_topup?amount=100\n    addAnchorListener<{\n      uriParams: {\n        balance: string,\n        purpose: string\n      }\n    }>({\n      name: 'stars_topup',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.STARS_TOPUP, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/share/url?url=...&text=...\n    addAnchorListener<{pathnameParams: ['share', 'url'], uriParams: {url?: string, text?: string}}>({\n      name: 'share',\n      callback: ({pathnameParams, uriParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.SHARE,\n          url: uriParams.url,\n          text: uriParams.text\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    addAnchorListener<{\n      uriParams: {\n        url?: string,\n        text?: string\n      }\n    }>({\n      name: 'msg_url',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.SHARE,\n          url: uriParams.url,\n          text: uriParams.text\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // t.me/nft/asdasd-1\n    addAnchorListener<{pathnameParams: ['nft', string]}>({\n      name: 'nft',\n      callback: ({pathnameParams}) => {\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT,\n          slug: pathnameParams.slice(1).join('/') // support unescaped slash\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://nft?slug=...\n    addAnchorListener<{\n      uriParams: {\n        slug: string\n      }\n    }>({\n      name: 'nft',\n      protocol: 'tg',\n      callback: ({uriParams}) => {\n        const link = this.makeLink(INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT, uriParams);\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://iv?url=...\n    addAnchorListener<{\n      uriParams: {\n        url: string\n      },\n    }>({\n      name: 'iv',\n      protocol: 'tg',\n      noCancelEvent: true,\n      callback: ({element, event}) => {\n        if((event as MouseEvent).ctrlKey || (event as MouseEvent).metaKey) {\n          return;\n        }\n\n        cancelEvent(event);\n        const link = this.makeLink(INTERNAL_LINK_TYPE.INSTANT_VIEW, {url: element.href});\n        return this.processInternalLink(link);\n      }\n    });\n\n    // tg://new/\n    // tg://new/group\n    // tg://new/contact\n    // tg://new/channel\n    addAnchorListener<{\n      pathnameParams: [InternalLink.InternalLinkNew['type'] | '']\n    }>({\n      name: 'new',\n      protocol: 'tg',\n      callback: ({pathnameParams}) => {\n        const [type] = pathnameParams;\n        switch(type) {\n          case 'contact':\n            return showCreateContactPopup();\n          case 'channel':\n            return appSidebarLeft.createTab(AppNewChannelTab).open({});\n          case 'group':\n            return createNewGroupTab(appSidebarLeft);\n          default:\n            return appSidebarLeft.createTab(AppContactsTab).open();\n        }\n      }\n    });\n\n    addAnchorListener<{\n      pathnameParams: string[],\n      uriParams: {highlight?: string}\n    }>({\n      name: 'settings',\n      protocol: 'tg',\n      callback: ({pathnameParams, uriParams}) => {\n        const path = pathnameParams.join('/');\n        switch(path) {\n          case '':\n            // reuse the open Settings instead of stacking a second one\n            return (appSidebarLeft.getTab(AppSettingsTab) || appSidebarLeft.createTab(AppSettingsTab)).open();\n          case 'edit':\n          case 'edit/set-photo':\n          case 'edit/first-name':\n          case 'edit/last-name':\n          case 'edit/bio':\n          case 'edit/username':\n          case 'profile-photo': {\n            // `noSame` hands back the editor when it is already open, and a tab\n            // inits once — so the field is pointed at afterwards, from outside,\n            // the way every other settings link points at its control.\n            const tab = appSidebarLeft.createTab(AppEditProfileTab);\n            return tab.open(getEditProfileInitArgs()).then(async() => {\n              // pointing at a field while the tab is still sliding in scrolls it\n              await tab.shown;\n\n              if(path === 'profile-photo' || path === 'edit/set-photo') {\n                shake(tab.container.querySelector('.avatar-edit'));\n                return;\n              }\n\n              const [{findSettingsLink}, {focusControl}] = await Promise.all([\n                import('@lib/settingsSearch/link'),\n                import('@lib/settingsSearch/highlight')\n              ]);\n\n              // which label a path names is the link table's business, the same\n              // table the search copies links from\n              const key = findSettingsLink(path)?.highlight;\n              if(key) {\n                focusControl(key, {root: tab.container, middleware: tab.middlewareHelper.get()});\n              }\n            });\n          }\n          case 'edit/birthday':\n            return this.managers.appProfileManager.getProfile(rootScope.myId).then((userFull) => {\n              showBirthdayPopup({\n                initialDate: userFull.birthday,\n                fromProfile: true,\n                onSave: saveMyBirthday\n              });\n            });\n          case 'edit/add-account':\n            // tdesktop points at the control instead of starting the flow\n            // (`SettingsControl{InformationId(), \"edit/add-account\"}`); ours lives\n            // in the chat list's menu, so that is the menu we open.\n            return appImManager.selectTab(APP_TABS.CHATLIST).then(() => {\n              return this.highlightMenuItem(\n                appSidebarLeft.sidebarEl.querySelector('.sidebar-header .btn-menu-toggle'),\n                'MultiAccount.AddAccount'\n              );\n            });\n          case 'edit/log-out': {\n            // tdesktop shows Settings with the log-out control highlighted\n            // (`ShowLogOutMenu`) — a link must not open the confirmation itself.\n            // Ours lives in the header menu, so the menu is opened and the item\n            // inside it is the one that flashes.\n            const settingsTab = appSidebarLeft.getTab(AppSettingsTab) || appSidebarLeft.createTab(AppSettingsTab);\n            return settingsTab.open().then(async() => {\n              // a menu opened over a tab that is still sliding in would jump\n              await settingsTab.shown;\n              return this.highlightMenuItem(\n                settingsTab.header.querySelector('.btn-menu-toggle'),\n                'EditAccount.Logout'\n              );\n            });\n          }\n          // case 'edit/change-number':\n          // case 'edit/your-color':\n          // case 'edit/channel':\n\n          case 'emoji-status': {\n            // iOS opens the picker itself, from where it always opens — for us\n            // that is the status button in the chat list header.\n            const statusBtn = appSidebarLeft.sidebarEl.querySelector<HTMLElement>('.sidebar-emoji-status');\n\n            // no button means no premium — the same promo the control itself\n            // shows when it is used without it (tdesktop: ShowPremiumPreviewBox).\n            // Nothing to reach, so nothing is closed to reach it.\n            if(!statusBtn) {\n              return PopupPremium.show({feature: 'emoji_status'});\n            }\n\n            return appImManager.selectTab(APP_TABS.CHATLIST).then(async() => {\n              // the button belongs to the chat list's own header, so whatever is\n              // stacked over the list has to go — the natural way, letting a tab\n              // that asks before closing ask\n              if(!await appSidebarLeft.closeEverythingInsideNaturally()) {\n                return;\n              }\n\n              // the button opens the picker on its own, and plays its animation\n              // when the status changes; only a collapsed column hides it, and a\n              // hidden anchor would leave the picker in the corner of the screen\n              if(statusBtn.offsetParent) {\n                simulateClickEvent(statusBtn);\n                return;\n              }\n\n              const {openEmojiStatusPicker} = await import('@components/sidebarLeft/emojiStatusPicker');\n              openEmojiStatusPicker({\n                managers: this.managers,\n                anchorElement: statusBtn.closest('.sidebar-header')\n              });\n            });\n          }\n\n          // destinations that are a screen of their own: tdesktop opens the\n          // Premium and Credits sections, and ours live in popups\n          case 'premium':\n            return PopupPremium.show();\n          case 'stars':\n            return PopupElement.createPopup(PopupStars);\n          case 'stars/gift':\n            return showGiftStarsPicker();\n          case 'send-gift':\n            return showSendGiftPicker();\n          case 'send-gift/self':\n            return PopupElement.createPopup(PopupSendGift, {peerId: rootScope.myId});\n\n          // destinations outside Settings, which the section table cannot address\n          case 'saved-messages':\n            return appImManager.setPeer({peerId: appImManager.myId});\n          case 'my-profile/posts/all-stories':\n            return appSidebarLeft.createTab(AppMyStoriesTab).open(AppMyStoriesTab.getInitArgs());\n          case 'my-profile/archived-posts':\n            return appSidebarLeft.createTab(AppMyStoriesTab).open({\n              ...AppMyStoriesTab.getInitArgs(),\n              isArchive: true\n            });\n          case 'ton':\n            return PopupElement.createPopup(PopupStars, {ton: true});\n\n          default:\n            // Every section the settings search indexes is addressable — see\n            // @lib/settingsSearch/link. Imported lazily to keep the index out of\n            // the startup bundle.\n            return import('@lib/settingsSearch/navigate').then(({openSettingsDeepLink}) => {\n              return openSettingsDeepLink(path, uriParams.highlight, appSidebarLeft);\n            }).catch((err) => console.error('settings link failed', path, err));\n        }\n      }\n    });\n\n    // tg://contacts/\n    // tg://contacts/search\n    // tg://contacts/sort\n    // tg://contacts/new\n    // tg://contacts/invite\n    // tg://contacts/manage\n    addAnchorListener<{\n      pathnameParams: [InternalLink.InternalLinkContacts['type'] | '']\n    }>({\n      name: 'contacts',\n      protocol: 'tg',\n      callback: ({pathnameParams}) => {\n        const [type] = pathnameParams;\n        switch(type) {\n          case 'new':\n            return showCreateContactPopup();\n          case 'search':\n          case '':\n            return appSidebarLeft.createTab(AppContactsTab).open();\n          // case 'invite':\n          // case 'manage':\n          // case 'sort':\n        }\n      }\n    });\n\n    // t.me/addstyle/<slug>\n    addAnchorListener<{pathnameParams: ['addstyle', string]}>({\n      name: 'addstyle',\n      callback: ({pathnameParams}) => {\n        if(!pathnameParams[1]) {\n          return;\n        }\n\n        const link: InternalLink = {\n          _: INTERNAL_LINK_TYPE.ADD_AI_STYLE,\n          slug: pathnameParams[1]\n        };\n\n        return this.processInternalLink(link);\n      }\n    });\n  }\n\n  /** Points at a control that lives in the menu behind `toggle`. */\n  private async highlightMenuItem(toggle: HTMLElement, key: LangPackKey) {\n    const {highlightMenuControl} = await import('@lib/settingsSearch/highlight');\n    highlightMenuControl(toggle, key);\n  }\n\n  private makeLink<T extends INTERNAL_LINK_TYPE>(type: T, uriParams: Omit<InternalLinkTypeMap[T], '_'>) {\n    return {\n      _: type,\n      ...uriParams\n    } as any as InternalLinkTypeMap[T];\n  }\n\n  public processMessageLink = (link: InternalLink.InternalLinkMessage) => {\n    if(link.startgroup !== undefined || link.startchannel !== undefined) {\n      const requestedRights = parseBotAdminRights(link.admin);\n      const scope = getBotAddToChatScope(link, requestedRights);\n      return this.managers.appUsersManager.resolveUsername(link.domain).then(async(peer) => {\n        if(peer._ === 'user' && peer.pFlags.bot) {\n          await showAddBotToChat({\n            botId: peer.id as BotId,\n            scope,\n            startParam: link.startgroup,\n            requestedRights\n          });\n          return;\n        }\n\n        await appImManager.openUsername({userName: link.domain});\n      }, (err: ApiError) => {\n        this.showUsernameResolveError(err);\n      });\n    }\n\n    const postId = link.post ? +link.post : undefined;\n    const commentId = link.comment ? +link.comment : undefined;\n    const threadId = link.thread ? +link.thread : undefined;\n\n    return appImManager.openUsername({\n      userName: link.domain,\n      lastMsgId: postId,\n      pollOption: link.option,\n      commentId,\n      startParam: link.start,\n      stack: link.stack,\n      threadId,\n      mediaTimestamp: link.t && +link.t,\n      text: link.text\n    });\n  };\n\n  public processPrivatePostLink = async(link: InternalLink.InternalLinkPrivatePost) => {\n    const chatId = link.channel.toChatId();\n    const userId = link.channel.toUserId();\n\n    const {chat, isBotforum, user} = await namedPromises({\n      chat: this.managers.appChatsManager.getChat(chatId),\n      isBotforum: this.managers.appUsersManager.isBotforum(userId),\n      user: this.managers.appUsersManager.getUser(userId)\n    });\n\n    if(!chat && !isBotforum) {\n      try {\n        await this.managers.appChatsManager.resolveChannel(chatId);\n      } catch(err) {\n        toastNew({langPackKey: 'LinkNotFound'});\n        throw err;\n      }\n    }\n\n    const postId = +link.post;\n    const threadId = link.thread ? +link.thread : undefined;\n\n    return appImManager.op({\n      peer: chat || user,\n      lastMsgId: postId,\n      threadId,\n      pollOption: link.option,\n      stack: link.stack,\n      mediaTimestamp: link.t && +link.t\n    });\n  };\n\n  public processStickerSetLink = (link: InternalLink.InternalLinkStickerSet | InternalLink.InternalLinkEmojiSet) => {\n    return showStickersPopup(getStickerSetInputByShortName(link.set), link._ === INTERNAL_LINK_TYPE.EMOJI_SET);\n  };\n\n  public processJoinChatLink = (link: InternalLink.InternalLinkJoinChat) => {\n    return this.managers.appChatInvitesManager.checkChatInvite(link.invite).then(async(chatInvite) => {\n      if(chatInvite._ === 'chatInviteAlready' ||\n        chatInvite._ === 'chatInvitePeek'/*  && chatInvite.expires > tsNow(true) */) {\n        // `open` (not `setInnerPeer`) so a forum routes through `op` and opens the topics tab\n        // in the left sidebar instead of just dropping into the chat view (same as bug with\n        // PopupJoinChatInvite.openChat).\n        appImManager.open({\n          peerId: chatInvite.chat.id.toPeerId(true)\n        });\n        return;\n      }\n\n      if(chatInvite.subscription_pricing && !chatInvite.pFlags.can_refulfill_subscription) {\n        const inputInvoice: InputInvoice = {\n          _: 'inputInvoiceChatInviteSubscription',\n          hash: link.invite\n        };\n\n        const popup = await PopupPayment.create({\n          inputInvoice,\n          chatInvite,\n          noPaymentForm: true\n        });\n\n        popup.addEventListener('finish', (result) => {\n          if(result === 'paid') {\n            this.processJoinChatLink(link);\n          }\n        });\n\n        return popup;\n      }\n\n      return PopupElement.createPopup(PopupJoinChatInvite, link.invite, chatInvite);\n    }, (err: ApiError) => {\n      if(err.type === 'INVITE_HASH_EXPIRED') {\n        toastNew({langPackKey: 'InviteExpired'});\n      }\n    });\n  };\n\n  public processVoiceChatLink = async(link: InternalLink.InternalLinkVoiceChat) => {\n    const openPeerId = (peerId: PeerId) => {\n      if(appImManager.chat.peerId !== peerId) {\n        return appImManager.setInnerPeer({peerId});\n      }\n    };\n\n    if(link.livestream !== undefined) {\n      const peer = await this.managers.appUsersManager.resolveUsername(link.domain);\n      const peerId = peer.id.toPeerId(true);\n      await openPeerId(peerId);\n      return appImManager.joinLiveStream(peerId);\n    }\n\n    if(!IS_GROUP_CALL_SUPPORTED) {\n      return;\n    }\n\n    if(link.id) {\n      const peerId = link.chat_id.toPeerId(true);\n      await openPeerId(peerId);\n      return appImManager.joinGroupCall(peerId, link.id);\n    }\n  };\n\n  // t.me/call/<slug> handler. Hand the slug to `appImManager.joinConference`,\n  // the single conference-join policy entry point — it owns the support gate,\n  // the \"already in a call\" guard and the dead-link error UX (so re-clicking\n  // the link while already in the call doesn't rejoin). tdesktop equivalent:\n  // SessionNavigation::resolveConferenceCall → startOrJoinConferenceCall.\n  public processConferenceCallLink = (\n    link: InternalLink.InternalLinkConferenceCall,\n    options?: JoinConferenceOptions\n  ) => {\n    // The slug is an opaque token the server minted; a malformed one is a dead\n    // link, and it gets the same notice as an expired one.\n    if(typeof(link.slug) !== 'string' || !CONFERENCE_CALL_SLUG_REGEXP.test(link.slug)) {\n      toastNew({langPackKey: 'InviteExpired'});\n      return Promise.resolve();\n    }\n\n    return appImManager.joinConference({_: 'inputGroupCallSlug', slug: link.slug}, options);\n  };\n\n  /**\n   * Sender of the message a link was clicked in. tdesktop threads the clicked\n   * item through the click handler's context and names its sender in the\n   * conference join confirmation (window_session_controller.cpp:1023); here\n   * the click is the only thread back to that message.\n   *\n   * A surface that already knows its message says so on the anchor it builds\n   * (`getWebPageActionOnClick`) — that covers the buttons which have no\n   * rendered message around them, like the pinned bar's Join call. Otherwise\n   * the link is text inside a bubble, and the bubble is what identifies it.\n   */\n  private getClickedMessageSenderPeerId(element?: HTMLElement, event?: Event) {\n    const stamped = element?.dataset?.fromId ||\n      findUpAttribute(event?.target as HTMLElement, 'data-from-id')?.dataset.fromId;\n    if(stamped) {\n      return stamped.toPeerId();\n    }\n\n    const bubble = findUpClassName(element, 'bubble') ||\n      findUpClassName(event?.target as HTMLElement, 'bubble');\n    const chat = appImManager.chat;\n    if(!bubble || !chat || bubble.dataset.peerId !== '' + chat.peerId) {\n      return;\n    }\n\n    return chat.getMessage(makeFullMid(chat.peerId, +bubble.dataset.mid))?.fromId;\n  }\n\n  public processAddAiStyleLink = async(link: InternalLink.InternalLinkAddAiStyle) => {\n    if(this.processingAddAiStyleSlugs.has(link.slug)) return;\n    this.processingAddAiStyleSlugs.add(link.slug);\n\n    try {\n      const {module: {default: showViewTonePopup}, tone, tones} = await namedPromises({\n        module: import('@components/popups/aiEditorPopup/viewTonePopup'),\n        tone: this.managers.aiTonesManager.getToneBySlug(link.slug),\n        tones: this.managers.aiTonesManager.getTones()\n      });\n      if(!tone) throw new Error();\n\n      const savedTones = tones.filter((t) => t._ === 'aiComposeTone').length;\n      const isSaved = !tone.pFlags.creator && tones.some((t) => t._ === 'aiComposeTone' && t.id.toString() === tone.id.toString());\n\n      showViewTonePopup({\n        tone,\n        isSaved,\n        savedTones,\n        HotReloadGuard: SolidJSHotReloadGuardProvider\n      });\n    } catch{\n      toastNew({\n        langPackKey: 'AiEditor.StyleNotFound'\n      });\n    } finally {\n      this.processingAddAiStyleSlugs.delete(link.slug);\n    }\n  };\n\n  public processUserPhoneNumberLink = (link: InternalLink.InternalLinkUserPhoneNumber) => {\n    return this.managers.appUsersManager.resolvePhone(link.phone).then((user) => {\n      return appImManager.setInnerPeer({\n        peerId: user.id.toPeerId(false),\n        text: link.text\n      });\n    }).catch((err: ApiError) => {\n      if(err.type === 'PHONE_NOT_OCCUPIED') {\n        toastNew({langPackKey: 'Alert.UserDoesntExists'});\n      }\n    });\n  };\n\n  public processInvoiceLink = (link: InternalLink.InternalLinkInvoice) => {\n    return this.managers.appPaymentsManager.getInputInvoiceBySlug(link.slug).then((inputInvoice) => {\n      return this.managers.appPaymentsManager.getPaymentForm(inputInvoice).then((paymentForm) => {\n        // const message: Message.message = {\n        //   _: 'message',\n        //   date: 0,\n        //   id: 0,\n        //   peerId: 0,\n        //   peer_id: undefined,\n        //   message: '',\n        //   media: {\n        //     _: 'messageMediaInvoice',\n        //     currency: paymentForm.invoice.currency,\n        //     description: paymentForm.description,\n\n        //   }\n        // };\n        return PopupPayment.create({inputInvoice, paymentForm});\n      }, (err) => {\n        if((err as ApiError).type === 'SLUG_INVALID') {\n          toastNew({langPackKey: 'PaymentInvoiceLinkInvalid'});\n        }\n\n        throw err;\n      });\n    });\n  };\n\n  public processAttachMenuBotLink = async(link: InternalLink.InternalLinkAttachMenuBot) => {\n    const botUsername = link.attach || link.domain || (link.nestedLink as InternalLink.InternalLinkMessage).domain;\n    const user = await this.managers.appUsersManager.resolveUserByUsername(botUsername).catch(() => undefined as User.user);\n\n    let processInternalLinkResult: any;\n    if(link.attach !== undefined) {\n      processInternalLinkResult = this.processInternalLink(link.nestedLink);\n    }\n\n    let errorLangPackKey: LangPackKey;\n    if(!user) {\n      errorLangPackKey = 'Alert.UserDoesntExists';\n    } else if(!user.pFlags.bot_attach_menu) {\n      errorLangPackKey = 'BotCantAddToAttachMenu';\n    }/*  else if(user.pFlags.attach_menu_enabled) {\n      errorLangPackKey = 'BotAlreadyAddedToAttachMenu';\n    } */\n\n    if(errorLangPackKey) {\n      toastNew({langPackKey: errorLangPackKey});\n      return;\n    }\n\n    processInternalLinkResult && await processInternalLinkResult;\n    const attachMenuBot = await appImManager.toggleBotInAttachMenu(user.id, true);\n\n    if(link.choose) {\n      type ChooseType = typeof link['choose'];\n      const choose = link.choose.split('+') as ChooseType[];\n      const verifyMap: {\n        [type in ChooseType]: AttachMenuPeerType['_']\n      } = {\n        bots: 'attachMenuPeerTypeBotPM',\n        users: 'attachMenuPeerTypePM',\n        groups: 'attachMenuPeerTypeChat',\n        channels: 'attachMenuPeerTypeBroadcast'\n      };\n\n      const filteredTypes = choose.filter((type) => {\n        const peerTypePredicate = verifyMap[type];\n        return attachMenuBot.peer_types.some((peerType) => peerType._ === peerTypePredicate);\n      });\n\n      const chosenPeerId = await showPickUser3Popup(filteredTypes);\n      await appImManager.setInnerPeer({peerId: chosenPeerId});\n    }\n\n    appImManager.chat.openWebApp({attachMenuBot, startParam: link.startattach});\n  };\n\n  public processWebAppLink = async(link: InternalLink.InternalLinkWebApp) => {\n    const user = await this.managers.appUsersManager.resolveUserByUsername(link.domain).catch(() => undefined as User.user);\n    if(!user) {\n      toastNew({langPackKey: 'Alert.UserDoesntExists'});\n      return;\n    }\n\n    const botId = user.id;\n    const commonOptions: Partial<RequestWebViewOptions> = {\n      compact: link.mode === 'compact',\n      fullscreen: link.mode === 'fullscreen',\n      startParam: link.startapp,\n      botId\n    };\n\n    if(!link.appname) {\n      if(!user.pFlags.bot_has_main_app) {\n        toastNew({langPackKey: 'Alert.BotAppDoesntExist'});\n        return;\n      }\n\n      if(link.masked) {\n        await appImManager.confirmBotWebViewInner({\n          botId\n        });\n      }\n\n      appImManager.chat.openWebApp({\n        ...commonOptions,\n        main: true\n      });\n\n      return;\n    }\n\n    let messagesBotApp: MessagesBotApp;\n    try {\n      messagesBotApp = await this.managers.appAttachMenuBotsManager.getBotApp(botId, link.appname);\n    } catch(err) {\n      if((err as ApiError).type === 'BOT_APP_INVALID') {\n        toastNew({langPackKey: 'Alert.BotAppDoesntExist'});\n        return;\n      } else {\n        throw err;\n      }\n    }\n\n    const attachMenuBot = user.pFlags.bot_attach_menu && await appImManager.toggleBotInAttachMenu(botId, true);\n\n    let haveWriteAccess: boolean;\n    if(attachMenuBot) {\n\n    } else if(link.masked || messagesBotApp.pFlags.inactive) {\n      haveWriteAccess = await appImManager.confirmBotWebViewInner({\n        botId,\n        requestWriteAccess: messagesBotApp.pFlags.request_write_access,\n        showDisclaimer: user.pFlags.bot_attach_menu && messagesBotApp.pFlags.inactive\n      });\n    }\n\n    appImManager.chat.openWebApp({\n      ...commonOptions,\n      attachMenuBot,\n      writeAllowed: haveWriteAccess,\n      app: messagesBotApp.app as BotApp.botApp,\n      noConfirmation: !attachMenuBot,\n      hasSettings: messagesBotApp.pFlags.has_settings\n    });\n  };\n\n  public processListLink = async(link: InternalLink.InternalLinkAddList) => {\n    let chatlistInvite: ChatlistsChatlistInvite;\n    try {\n      chatlistInvite = await this.managers.filtersStorage.checkChatlistInvite(link.slug);\n    } catch(err) {\n      if((err as ApiError).type === 'INVITE_SLUG_EXPIRED') {\n        toastNew({langPackKey: 'SharedFolder.Link.Expired'});\n        return;\n      }\n\n      throw err;\n    }\n\n    PopupElement.createPopup(PopupSharedFolderInvite, {\n      chatlistInvite,\n      slug: link.slug\n    });\n  };\n\n  public processStoryLink = async(link: InternalLink.InternalLinkStory) => {\n    const event = window.event;\n    const bubble = findUpClassName(event.target as HTMLElement, 'bubble');\n    if(bubble && bubble.classList.contains('story')) {\n      simulateClickEvent(bubble.querySelector('.media-container').querySelector('img, video'));\n      return;\n    }\n\n    let peer: User.user | Chat;\n    try {\n      peer = await this.managers.appUsersManager.resolveUsername(link.domain);\n    } catch(err) {\n      if((err as ApiError).type === 'USERNAME_NOT_OCCUPIED') {\n        toastNew({langPackKey: 'NoUsernameFound'});\n      } else {\n        console.error(err);\n      }\n\n      return;\n    }\n\n    const peerId = peer.id.toPeerId(peer._ !== 'user');\n    const storyItem = await this.managers.appStoriesManager.getStoryById(peerId, +link.story);\n    if(!storyItem) {\n      toastNew({langPackKey: 'NoStoryFound'});\n      return;\n    }\n\n    createStoriesViewerWithPeer({\n      peerId,\n      id: +link.story\n    });\n  };\n\n  public processBoostLink = async(link: InternalLink.InternalLinkBoost) => {\n    let peerId = link.channel ? link.channel.toPeerId(true) : undefined;\n    if(peerId === undefined) {\n      const chat = await this.managers.appUsersManager.resolveUsername(link.domain) as Chat;\n      peerId = chat.id.toPeerId(true);\n    }\n\n    PopupElement.createPopup(PopupBoost, peerId);\n  };\n\n  public processPremiumFeaturesLink = async(link: InternalLink.InternalLinkPremiumFeatures) => {\n    if(rootScope.premium) {\n      toastNew({langPackKey: 'Premium.Offset.AlreadyHave'});\n      return;\n    }\n\n    PopupPremium.show();\n  };\n\n  public processGiftCodeLink = (link: InternalLink.InternalLinkGiftCode) => {\n    PopupElement.createPopup(PopupGiftLink, link.slug, link.stack);\n  };\n\n  public processBusinessChatLink = async(link: InternalLink.InternalLinkBusinessChat) => {\n    const resolved = await this.managers.appBusinessManager.resolveBusinessChatLink(link.slug);\n    appImManager.setInnerPeer({\n      peerId: resolved.peerId,\n      text: resolved.message,\n      entities: resolved.entities\n    });\n  };\n\n  public processStarsTopupLink = async(link: InternalLink.InternalLinkStarsTopup) => {\n    const middlewareHelper = getMiddleware();\n    const balance = +(await prefetchStars(middlewareHelper.get()));\n    middlewareHelper.destroy();\n\n    const purpose = link.purpose || 'topup';\n\n    const itemPrice = +link.balance;\n    if(balance >= itemPrice) {\n      toastNew({\n        langPackKey: 'Stars.TopUp.Enough',\n        langPackArguments: [\n          anchorCallback(() => {\n            hideToast();\n            const popup = PopupElement.createPopup(PopupStars, {\n              onTopup: () => {\n                popup.hide();\n              },\n              purpose\n            });\n          })\n        ]\n      });\n      return;\n    }\n\n    const popup = PopupElement.createPopup(PopupStars, {\n      itemPrice,\n      onTopup: () => {\n        popup.hide();\n      },\n      purpose\n    });\n  };\n\n  public processShareLink = async(link: InternalLink.InternalLinkShare) => {\n    const {peerId, threadId, monoforumThreadId} = await showSharingPicker2Popup();\n    // The shared text becomes a draft of the chosen chat — any chat, the way\n    // tdesktop's `MainWidget::shareUrl` does it. `setInnerPeer({text})` is the\n    // `?text=` deep-link path, which only prefills private chats.\n    const text = [link.url, link.text].filter(Boolean).join('\\n');\n    if(text) {\n      await rootScope.managers.appDraftsManager.setDraft(peerId, threadId || monoforumThreadId, text);\n    }\n\n    appImManager.setInnerPeer({peerId, threadId, monoforumThreadId});\n  };\n\n  public processUniqueStarGiftLink = async(link: InternalLink.InternalLinkUniqueStarGift) => {\n    const gift = await this.managers.appGiftsManager.getGiftBySlug(link.slug).catch(noop);\n    if(!gift) {\n      toastNew({langPackKey: 'Error.AnError'});\n      return;\n    }\n\n    PopupElement.createPopup(PopupStarGiftInfo, {gift});\n  };\n\n  public processStarGiftCollectionLink = async(link: InternalLink.InternalLinkStarGiftCollection) => {\n    const peer = await this.managers.appUsersManager.resolveUsername(link.domain);\n    const peerId = peer.id.toPeerId(peer._ !== 'user');\n    if(appImManager.chat.peerId !== peerId) {\n      await appImManager.setInnerPeer({peerId});\n      await pause(500);\n    }\n    appSidebarRight.toggleSidebar(true, true);\n    appSidebarRight.sharedMediaTab.setSearchTab('gifts');\n    appSidebarRight.sharedMediaTab.searchSuper.stargiftsActions?.setFilters({chosenCollection: Number(link.id)});\n  };\n\n  public processStoryAlbumLink = async(link: InternalLink.InternalLinkStoryAlbum) => {\n    const peer = await this.managers.appUsersManager.resolveUsername(link.domain);\n    const peerId = peer.id.toPeerId(peer._ !== 'user');\n    const albumId = +link.id;\n\n    if(peerId === rootScope.myId) {\n      const existing = appSidebarRight.getTab(AppMyStoriesTab);\n      if(existing) {\n        (existing as any).setAlbum(albumId);\n        return;\n      }\n\n      await appSidebarRight.createTab(AppMyStoriesTab).open({...AppMyStoriesTab.getInitArgs(), initialAlbumId: albumId});\n      appSidebarRight.toggleSidebar(true, true);\n    } else {\n      if(appImManager.chat.peerId !== peerId) {\n        await appImManager.setInnerPeer({peerId});\n        await pause(500);\n      }\n      appSidebarRight.toggleSidebar(true, true);\n      appSidebarRight.sharedMediaTab.setSearchTab('stories');\n      appSidebarRight.sharedMediaTab.searchSuper.storiesSetAlbum(albumId);\n    }\n  };\n\n  public processInstantViewLink = (link: InternalLink.InternalLinkInstantView) => {\n    openInstantViewInAppBrowser({\n      cachedPage: link.url,\n      HotReloadGuardProvider: SolidJSHotReloadGuardProvider\n    });\n  };\n\n  public processInternalLink(link: InternalLink) {\n    const map: {\n      [key in InternalLink['_']]?: (link: any) => any\n    } = {\n      [INTERNAL_LINK_TYPE.MESSAGE]: this.processMessageLink,\n      [INTERNAL_LINK_TYPE.PRIVATE_POST]: this.processPrivatePostLink,\n      [INTERNAL_LINK_TYPE.EMOJI_SET]: this.processStickerSetLink,\n      [INTERNAL_LINK_TYPE.STICKER_SET]: this.processStickerSetLink,\n      [INTERNAL_LINK_TYPE.JOIN_CHAT]: this.processJoinChatLink,\n      [INTERNAL_LINK_TYPE.VOICE_CHAT]: this.processVoiceChatLink,\n      [INTERNAL_LINK_TYPE.USER_PHONE_NUMBER]: this.processUserPhoneNumberLink,\n      [INTERNAL_LINK_TYPE.INVOICE]: this.processInvoiceLink,\n      [INTERNAL_LINK_TYPE.ATTACH_MENU_BOT]: this.processAttachMenuBotLink,\n      [INTERNAL_LINK_TYPE.WEB_APP]: this.processWebAppLink,\n      [INTERNAL_LINK_TYPE.ADD_LIST]: this.processListLink,\n      [INTERNAL_LINK_TYPE.STORY]: this.processStoryLink,\n      [INTERNAL_LINK_TYPE.BOOST]: this.processBoostLink,\n      [INTERNAL_LINK_TYPE.PREMIUM_FEATURES]: this.processPremiumFeaturesLink,\n      [INTERNAL_LINK_TYPE.GIFT_CODE]: this.processGiftCodeLink,\n      [INTERNAL_LINK_TYPE.BUSINESS_CHAT]: this.processBusinessChatLink,\n      [INTERNAL_LINK_TYPE.STARS_TOPUP]: this.processStarsTopupLink,\n      [INTERNAL_LINK_TYPE.SHARE]: this.processShareLink,\n      [INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT]: this.processUniqueStarGiftLink,\n      [INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION]: this.processStarGiftCollectionLink,\n      [INTERNAL_LINK_TYPE.STORY_ALBUM]: this.processStoryAlbumLink,\n      [INTERNAL_LINK_TYPE.INSTANT_VIEW]: this.processInstantViewLink,\n      [INTERNAL_LINK_TYPE.CONFERENCE_CALL]: this.processConferenceCallLink,\n      [INTERNAL_LINK_TYPE.ADD_AI_STYLE]: this.processAddAiStyleLink\n    };\n\n    const processor = map[link._];\n    if(!processor) {\n      console.warn('Not supported internal link:', link);\n      return;\n    }\n\n    return processor(link);\n  }\n}\n\nconst internalLinkProcessor = new InternalLinkProcessor();\nMOUNT_CLASS_TO && (MOUNT_CLASS_TO.internalLinkProcessor = internalLinkProcessor);\nexport default internalLinkProcessor;\n","import {createSignal, onCleanup} from 'solid-js';\nimport PopupElement from '.';\nimport formatDuration from '@helpers/formatDuration';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport {randomItem, randomItemExcept} from '@helpers/array/randomItem';\nimport assumeType from '@helpers/assumeType';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\n\nimport css from '@components/popups/webAppEmojiStatusAccess.module.scss';\nimport rootScope from '@lib/rootScope';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nexport default class PopupWebAppEmojiStatusAccess extends PopupElement<{\n  finish: (result: boolean) => void\n}> {\n  private sticker: MyDocument;\n  private defaultStatusEmojis: MyDocument[];\n  private period: number;\n  private botId: PeerId;\n\n  constructor(options: {\n    botId: PeerId,\n    sticker?: MyDocument,\n    defaultStatusEmojis?: MyDocument[],\n    period?: number\n  }) {\n    let finished = false;\n    super(css.popup, {\n      overlayClosable: true,\n      body: true,\n      buttons: [\n        {\n          langKey: options.sticker ? 'Confirm' : 'Allow',\n          callback: () => {\n            finished = true\n            this.dispatchEvent('finish', true);\n          }\n        },\n        {\n          langKey: options.sticker ? 'Cancel' : 'Decline',\n          callback: () => {\n            finished = true\n            this.dispatchEvent('finish', false);\n          }\n        }\n      ]\n    });\n\n    this.addEventListener('close', () => {\n      if(!finished) {\n        this.dispatchEvent('finish', false);\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.header.remove()\n\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    const [sticker, setSticker] = createSignal<MyDocument>(this.sticker);\n\n    if(!this.sticker) {\n      setSticker(randomItem(this.defaultStatusEmojis));\n      this.body.classList.add(css.forOffline)\n    }\n\n    const renderChip = () => (\n      <div class={/* @once */ css.chip}>\n        <AvatarNewTsx peerId={rootScope.myId} size={32} />\n        <PeerTitleTsx peerId={rootScope.myId} />\n\n        <StickerTsx\n          ref={stickerRef}\n          class={/* @once */ css.chipSticker}\n          autoStyle\n          sticker={sticker()}\n          extraOptions={{\n            play: true,\n            textColor: 'primary-color'\n          }}\n          width={20}\n          height={20}\n          onRender={(player) => {\n            if(this.sticker) return\n            stickerRef.classList.remove(css.switch);\n\n            assumeType<LottiePlayer>(player);\n            player.playOrRestart();\n            player.addEventListener('enterFrame', (frameNo) => {\n              if(frameNo === player.maxFrame) {\n                player.stop(false);\n                stickerRef.classList.add(css.switch)\n                stickerRef.addEventListener('transitionend', () => {\n                  setSticker(randomItemExcept(this.defaultStatusEmojis, sticker()));\n                }, {once: true});\n              }\n            });\n          }}\n        />\n      </div>\n    )\n\n    let stickerRef: HTMLElement;\n    return (\n      <>\n        {this.sticker && (\n          <>\n            <StickerTsx\n              autoStyle\n              class={/* @once */ css.sticker}\n              sticker={this.sticker}\n              extraOptions={{play: true}}\n              width={96}\n              height={96}\n            />\n            <div class={/* @once */ css.title}>\n              <I18nTsx key=\"BotSetEmojiStatusTitle\" />\n            </div>\n          </>\n        )}\n\n        {!this.sticker && renderChip()}\n\n        <div class={/* @once */ css.text}>\n          <I18nTsx\n            key={\n              this.sticker ?\n                this.period ?\n                  'BotSetEmojiStatusTextFor' :\n                  'BotSetEmojiStatusText' :\n                'BotSetEmojiStatusOffline'\n            }\n            args={this.sticker && this.period ? [\n              <PeerTitleTsx peerId={this.botId} />,\n              wrapFormattedDuration(formatDuration(this.period))\n            ] : [\n              <PeerTitleTsx peerId={this.botId} />,\n              !this.sticker && <PeerTitleTsx peerId={this.botId} />\n            ]}\n          />\n        </div>\n\n        {this.sticker && renderChip()}\n      </>\n    )\n  }\n}\n","import PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport rootScope from '@lib/rootScope';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {IconTsx} from '@components/iconTsx';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport css from '@components/popups/webAppLocationAccess.module.scss';\n\nexport default class PopupWebAppLocationAccess extends PopupElement<{\n  finish: (result: boolean) => void\n}> {\n  private botId: PeerId;\n\n  constructor(options: {\n    botId: PeerId,\n  }) {\n    let finished = false;\n    super(css.popup, {\n      overlayClosable: true,\n      body: true,\n      buttons: [\n        {\n          langKey: 'Allow',\n          callback: () => {\n            finished = true\n            this.dispatchEvent('finish', true);\n          }\n        },\n        {\n          langKey: 'Decline',\n          callback: () => {\n            finished = true\n            this.dispatchEvent('finish', false);\n          }\n        }\n      ]\n    });\n\n    this.addEventListener('close', () => {\n      if(!finished) {\n        this.dispatchEvent('finish', false);\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.header.remove()\n\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    return (\n      <>\n        <div class={/* @once */ css.graph}>\n          <div class={/* @once */ css.avatarWrap}>\n            <AvatarNewTsx\n              peerId={rootScope.myId}\n              size={64}\n            />\n            <div class={/* @once */ css.locationIcon}>\n              <IconTsx icon=\"location\" />\n            </div>\n          </div>\n          <IconTsx icon=\"next\" />\n          <AvatarNewTsx\n            peerId={this.botId}\n            size={64}\n          />\n        </div>\n\n        <div class={/* @once */ css.text}>\n          <I18nTsx\n            key=\"BotLocationAccessText\"\n            args={[\n              <PeerTitleTsx peerId={this.botId} />,\n              <PeerTitleTsx peerId={this.botId} />\n            ]}\n          />\n        </div>\n      </>\n    )\n  }\n}\n","import {createEffect, createResource, JSX, on} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {MessageEntity, ReplyMarkup} from '@layer';\nimport {generateTail} from '@components/chat/utils';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport rootScope from '@lib/rootScope';\nimport ReplyMarkupLayout from '@components/chat/bubbleParts/replyMarkupLayout';\n\nfunction ViaUsername(props: {botId: BotId}) {\n  const [resource, ctx] = createResource(async() => {\n    const via = document.createElement('span');\n    via.innerText = '@' + (await rootScope.managers.appPeersManager.getPeerUsername(props.botId.toPeerId()));\n    via.classList.add('peer-title');\n    return via\n  })\n\n  createEffect(on(() => props.botId, () => ctx.refetch()));\n\n  return <>{resource()}</>;\n}\n\nexport function BubbleLayout(props: {\n  class?: string\n  contentStyle?: Record<string, string>\n  text?: string\n  textEntities?: MessageEntity[]\n  content?: JSX.Element\n  tail?: boolean\n  out?: boolean\n  justMedia?: boolean\n  group?: 'first' | 'last' | 'single'\n  via?: BotId\n  attachment?: JSX.Element\n  replyMarkup?: ReplyMarkup.replyInlineMarkup\n}) {\n  const renderVia = () => (\n    <span class=\"is-via\">\n      <I18nTsx key=\"ViaBot\" />\n      {' '}\n      <ViaUsername botId={props.via.toPeerId()} />\n    </span>\n  )\n\n  return (\n    <div\n      class={classNames(\n        'bubble',\n        props.tail && 'can-have-tail',\n        props.out && 'is-out',\n        (props.group === 'first' || props.group === 'single') && 'is-group-first',\n        (props.group === 'last' || props.group === 'single') && 'is-group-last',\n        props.via && 'must-have-name',\n        props.justMedia && 'just-media',\n        props.replyMarkup && 'with-reply-markup',\n        props.class\n      )}\n    >\n      <div class=\"bubble-content-wrapper\">\n        <div class=\"bubble-content\" style={props.contentStyle}>\n          {props.justMedia ? (\n            <div class=\"floating-part name-with-reply\" dir=\"auto\">\n              <div class=\"name\">\n                {renderVia()}\n              </div>\n            </div>\n          ) : (\n            <div\n              class={classNames(\n                'name floating-part',\n                !props.attachment && 'next-is-message'\n              )}\n              dir=\"auto\"\n            >\n              {renderVia()}\n            </div>\n          )}\n          {props.attachment}\n          {(props.text || props.content) && (\n            <div class={classNames('message spoilers-container', props.attachment && 'mt-shorter')}>\n              {props.content ?? wrapRichText(props.text, {entities: props.textEntities})}\n            </div>\n          )}\n          {props.tail && generateTail()}\n        </div>\n\n        {props.replyMarkup && <ReplyMarkupLayout.Inline rows={props.replyMarkup.rows} />}\n      </div>\n    </div>\n  )\n}\n","import {createResource, createSignal, onMount} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {I18nTsx} from '@helpers/solid/i18n';\n\nimport {BotInlineResult, Message, MessageEntity, MessagesPreparedInlineMessage, Photo, ReplyMarkup, TextWithEntities} from '@layer';\nimport {BubbleLayout} from '@components/chat/bubbles/bubbleLayout';\nimport {FakeBubbles} from '@components/chat/bubbles/fakeBubbles';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\n\nimport css from '@components/popups/webAppPreparedMessage.module.scss';\nimport wrapPhoto from '@components/wrappers/photo';\nimport classNames from '@helpers/string/classNames';\nimport setAttachmentSize from '@helpers/setAttachmentSize';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport wrapSticker from '@components/wrappers/sticker';\nimport wrapVideo from '@components/wrappers/video';\nimport wrapDocument from '@components/wrappers/document';\nimport {useAppSettings} from '@stores/appSettings';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {showPickUser2Popup} from '@components/popups/pickUser';\nimport appImManager from '@lib/appImManager';\nimport generateQId from '@appManagers/utils/inlineBots/generateQId';\n\nexport default class PopupWebAppPreparedMessage extends PopupElement<{\n  finish: (error?: string) => void\n}> {\n  private message: MessagesPreparedInlineMessage.messagesPreparedInlineMessage;\n  private botId: BotId;\n\n  constructor(options: {\n    message: MessagesPreparedInlineMessage.messagesPreparedInlineMessage\n    botId: BotId\n  }) {\n    let finished = false;\n    super(css.popup, {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      title: 'BotSharePreparedMessageTitle',\n      buttons: [\n        {\n          langKey: 'ShareFile',\n          callback: async() => {\n            const availableTypes = new Set(this.message.peer_types.map(it => it._))\n\n            const chosenPeerId = await showPickUser2Popup({\n              peerType: ['dialogs', 'contacts'],\n              filterPeerTypeBy: (peer) => {\n                if(peer._ === 'user') {\n                  if(peer.id === this.botId && availableTypes.has('inlineQueryPeerTypeSameBotPM')) return true\n                  if(peer.pFlags.bot && availableTypes.has('inlineQueryPeerTypeBotPM')) return true\n                  if(availableTypes.has('inlineQueryPeerTypePM')) return true\n                }\n                if(peer._ === 'chat' && availableTypes.has('inlineQueryPeerTypeChat')) return true\n                if(peer._ === 'channel') {\n                  if(peer.pFlags.broadcast && availableTypes.has('inlineQueryPeerTypeBroadcast')) return true\n                  if(peer.pFlags.megagroup && availableTypes.has('inlineQueryPeerTypeChat')) return true\n                }\n\n                return false\n              },\n              chatRightsActions: ['send_inline']\n            }).catch(() => undefined as PeerId);\n\n            if(!chosenPeerId) {\n              return false;\n            }\n\n            await appImManager.setInnerPeer({peerId: chosenPeerId});\n            const queryAndResultIds = generateQId(this.message.query_id, this.message.result.id);\n            const sent = await this.managers.appInlineBotsManager.sendInlineResult(chosenPeerId, this.botId, queryAndResultIds, {\n              inlineResult: this.message.result,\n              ...appImManager.chat.getMessageSendingParams(),\n              clearDraft: true\n            })\n            if(!sent) {\n              return false;\n            }\n\n            finished = true\n            this.dispatchEvent('finish');\n            return true\n          }\n        },\n        {\n          langKey: 'Cancel',\n          callback: () => {\n            finished = true\n            this.dispatchEvent('finish', 'USER_DECLINED');\n          }\n        }\n      ]\n    });\n\n    this.addEventListener('close', () => {\n      if(!finished) {\n        this.dispatchEvent('finish', 'USER_DECLINED');\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    const result = this.message.result;\n    const sendMessage = result.send_message\n\n    let text: string\n    let entities: MessageEntity[]\n    let attachmentDiv: HTMLDivElement\n    let contentDiv: HTMLDivElement\n    let bubbleClass = css.bubble;\n    const bubbleContainerStyle: Record<string, string> = {};\n\n    switch(sendMessage._) {\n      case 'botInlineMessageText':\n      case 'botInlineMessageMediaAuto':\n      case 'botInlineMessageMediaWebPage':\n        text = sendMessage.message;\n        entities = sendMessage.entities;\n        break;\n    }\n\n    let justMedia = false\n\n    if(result._ === 'botInlineMediaResult' || result.thumb) {\n      attachmentDiv = document.createElement('div');\n      attachmentDiv.classList.add('attachment');\n      if(text) {\n        attachmentDiv.classList.add('no-brb');\n        bubbleClass += ' with-media-tail';\n      } else {\n        bubbleClass += ' has-plain-media-tail';\n      }\n    }\n\n    if(result._ === 'botInlineMediaResult') {\n      if(result.type === 'photo' && result.photo) {\n        bubbleClass += ' photo';\n\n        wrapPhoto({\n          photo: result.photo as MyPhoto,\n          container: attachmentDiv,\n          withTail: true,\n          isOut: true,\n          middleware: this.middlewareHelper.get()\n        })\n      } else if(result.document) {\n        const doc = result.document as MyDocument;\n\n        if(result.type === 'sticker') {\n          justMedia = true\n          bubbleClass += ' sticker';\n\n          if(doc.animated) {\n            bubbleClass += 'sticker-animated'\n          }\n\n          const boxSize = doc.animated ? mediaSizes.active.animatedSticker : mediaSizes.active.staticSticker;\n\n          setAttachmentSize({\n            photo: doc,\n            element: attachmentDiv,\n            boxWidth: boxSize.width,\n            boxHeight: boxSize.height\n          });\n          bubbleContainerStyle['min-width'] = boxSize.width + 'px';\n          bubbleContainerStyle['min-height'] = boxSize.height + 'px';\n\n          wrapSticker({\n            doc,\n            div: attachmentDiv,\n            middleware: this.middlewareHelper.get(),\n            play: true,\n            liteModeKey: 'stickers_chat',\n            loop: true,\n            withThumb: true,\n            isOut: true\n          })\n        } else if(result.type === 'video') {\n          const isRound = doc.type === 'round';\n          justMedia = isRound\n          bubbleClass += isRound ? ' round' : ' video';\n\n          wrapVideo({\n            doc,\n            message: {\n              _: 'message',\n              media: {\n                _: 'messageMediaDocument',\n                document: doc\n              }\n            } as Message.message,\n            container: attachmentDiv,\n            middleware: this.middlewareHelper.get(),\n            boxWidth: mediaSizes.active.regular.width,\n            boxHeight: mediaSizes.active.regular.height,\n            isOut: true\n          })\n        } else {\n          bubbleClass += ' document-message is-single-document';\n          const container = document.createElement('div');\n          container.classList.add('document-container');\n          const wrapper = document.createElement('div');\n          wrapper.classList.add('document-wrapper');\n\n          container.append(wrapper);\n          contentDiv = container\n\n          const [appSettings] = useAppSettings();\n          wrapDocument({\n            message: {\n              _: 'message',\n              pFlags: {is_outgoing: true},\n              media: {\n                _: 'messageMediaDocument',\n                document: doc\n              }\n            } as Message.message,\n            middleware: this.middlewareHelper.get(),\n            sizeType: 'documentName',\n            fontSize: appSettings.messagesTextSize,\n            canTranscribeVoice: false,\n            isOut: true\n          }).then((div) => {\n            wrapper.append(div);\n\n            if(text) {\n              const message = document.createElement('div');\n              message.classList.add('document-message');\n              const rich = wrapRichText(text, {entities});\n              message.append(rich);\n              wrapper.append(message);\n            }\n          });\n        }\n      }\n    } else if(result._ === 'botInlineResult' && result.thumb && result.thumb.mime_type.indexOf('image/') === 0) {\n      bubbleClass += ' photo';\n\n      wrapPhoto({\n        photo: result.thumb,\n        container: attachmentDiv,\n        withTail: true,\n        isOut: true,\n        middleware: this.middlewareHelper.get()\n      })\n    }\n\n    return (\n      <>\n        <FakeBubbles class={css.bubbles} contentClass={css.bubblesContent}>\n          <BubbleLayout\n            class={classNames(css.bubble, bubbleClass)}\n            justMedia={justMedia}\n            contentStyle={bubbleContainerStyle}\n            text={text}\n            textEntities={entities}\n            out\n            tail={!justMedia}\n            via={this.botId}\n            group=\"single\"\n            attachment={attachmentDiv}\n            content={contentDiv}\n            replyMarkup={result.send_message?.reply_markup as ReplyMarkup.replyInlineMarkup}\n          />\n        </FakeBubbles>\n\n        <div class={css.text}>\n          <I18nTsx\n            key='BotSharePreparedMessageText'\n            args={<PeerTitleTsx peerId={this.botId.toPeerId()} />}\n          />\n        </div>\n      </>\n    )\n  }\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\n\nconst IS_WEB_APP_BROWSER_SUPPORTED = !IS_TOUCH_SUPPORTED || true;\nexport default IS_WEB_APP_BROWSER_SUPPORTED;\n","import rootScope from '@lib/rootScope';\nimport wrapSticker from '@components/wrappers/sticker';\n\nexport function wrapAdaptiveCustomEmoji(options: {\n  as?: string\n  docId: DocId,\n  size: number\n  wrapOptions?: WrapSomethingOptions\n}) {\n  const {docId, size, wrapOptions, as} = options;\n  const container = document.createElement(as || 'div');\n  container.classList.add('custom-emoji');\n\n  if(wrapOptions?.textColor) {\n    container.classList.add('emoji-status-text-color')\n  }\n\n  const loadPromise = (async() => {\n    const doc = await rootScope.managers.appEmojiManager.getCustomEmojiDocument(docId);\n    await wrapSticker({\n      doc,\n      div: container,\n      width: size,\n      height: size,\n      play: false,\n      withThumb: false,\n      group: 'none',\n      static: !wrapOptions?.textColor,\n      middleware: wrapOptions?.middleware,\n      textColor: wrapOptions?.textColor,\n      lazyLoadQueue: wrapOptions?.lazyLoadQueue === false ? undefined : wrapOptions?.lazyLoadQueue,\n      managers: wrapOptions?.managers\n    }).then(res => res.render);\n  })()\n\n  return {container, loadPromise};\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {BotInfo} from '@layer';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\n\n// Hardcoded default URL, matching tdesktop (lng_profile_bot_privacy_url) and\n// Android (BotDefaultPrivacyPolicy). Not an appConfig key.\nexport const BOT_DEFAULT_PRIVACY_POLICY_URL = 'https://telegram.org/privacy-tpa';\n\nexport function botHasPrivacyCommand(botInfo: BotInfo.botInfo) {\n  return botInfo.commands?.some((c) => c.command === 'privacy') ?? false;\n}\n\n/**\n * Resolves the bot privacy policy action, mirroring tdesktop/Android:\n * 1) privacy_policy_url set -> open it;\n * 2) else no /privacy command -> open the default URL;\n * 3) else (has /privacy command) -> send /privacy in the bot chat.\n */\nexport function resolveBotPrivacyPolicy(botInfo: BotInfo.botInfo): {url: string} | {sendCommand: true} {\n  if(botInfo.privacy_policy_url) return {url: botInfo.privacy_policy_url};\n  if(!botHasPrivacyCommand(botInfo)) return {url: BOT_DEFAULT_PRIVACY_POLICY_URL};\n  return {sendCommand: true};\n}\n\n/**\n * Acts on the resolved policy: opens the URL in a new tab, or runs\n * sendPrivacyCommand() — the caller's \"open the bot chat and send /privacy\".\n * Shared by the bot profile row and the mini-app menu item.\n */\nexport function openBotPrivacyPolicy(botInfo: BotInfo.botInfo, sendPrivacyCommand: () => void) {\n  const resolved = resolveBotPrivacyPolicy(botInfo);\n  if('url' in resolved) {\n    safeWindowOpen(resolved.url);\n    return;\n  }\n\n  sendPrivacyCommand();\n}\n","import {VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport {User} from '@layer';\n\nexport default function canReportBot(peerId: PeerId, user: User) {\n  return user?._ === 'user' &&\n    !!user.pFlags.bot &&\n    !user.pFlags.support &&\n    peerId !== VERIFICATION_CODES_BOT_ID;\n}\n","import {Accessor, createSignal, Show} from 'solid-js';\nimport {hexToRgb, calculateLuminance, getTextColor, calculateOpacity, rgbaToRgb, rgbIntToHex, mixColors, rgbaToHexa} from '@helpers/color';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport themeController from '@helpers/themeController';\nimport {AttachMenuBot, BotInfo, DataJSON, WebViewResult, Document, MessagesPreparedInlineMessage, Update} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {InternalLink, INTERNAL_LINK_TYPE} from '@lib/internalLink';\nimport internalLinkProcessor from '@lib/internalLinkProcessor';\nimport {AppManagers} from '@lib/managers';\nimport getAttachMenuBotIcon from '@appManagers/utils/attachMenuBots/getAttachMenuBotIcon';\nimport I18n, {LangPackKey} from '@lib/langPack';\nimport wrapEmojiText, {EmojiTextTsx} from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport {TelegramWebViewEventMap, AnyFunction, TelegramWebViewSendEventMap} from '@types';\nimport ButtonTsx from '@components/buttonTsx';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport confirmationPopup from '@components/confirmationPopup';\nimport PopupElement from '@components/popups';\nimport PopupPeer, {PopupPeerOptions} from '@components/popups/peer';\nimport {showPickUser3Popup} from '@components/popups/pickUser';\nimport selectRequestPeers from '@components/popups/requestPeer';\nimport TelegramWebView from '@components/telegramWebView';\nimport wrapAttachBotIcon from '@components/wrappers/attachBotIcon';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport classNames from '@helpers/string/classNames';\nimport {render} from 'solid-js/web';\nimport {attachClassName} from '@helpers/solid/classname';\nimport PopupWebAppEmojiStatusAccess from '@components/popups/webAppEmojiStatusAccess';\nimport {toastNew} from '@components/toast';\nimport tsNow from '@helpers/tsNow';\nimport PopupPremium from '@components/popups/premium';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport PopupWebAppLocationAccess from '@components/popups/webAppLocationAccess';\nimport appSidebarRight from '@components/sidebarRight';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport {Transition} from '@vendor/solid-transition-group';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport type {RequestWebViewOptions} from '@appManagers/appAttachMenuBotsManager';\nimport {createSvgFromBytes} from '@helpers/bytes/getPathFromBytes';\nimport clamp from '@helpers/number/clamp';\nimport PopupWebAppPreparedMessage from '@components/popups/webAppPreparedMessage';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport IS_WEB_APP_BROWSER_SUPPORTED from '@environment/webAppBrowserSupport';\nimport {wrapAdaptiveCustomEmoji} from '@components/wrappers/customEmojiSimple';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {openBotPrivacyPolicy} from '@helpers/getBotPrivacyPolicy';\nimport canReportBot from '@appManagers/utils/bots/canReportBot';\nimport {showPeerReport} from '@components/popups/reportAd';\nimport getWebViewTgLink from '@helpers/getWebViewTgLink';\n\nconst SANDBOX_ATTRIBUTES = [\n  'allow-scripts',\n  'allow-same-origin',\n  'allow-popups',\n  'allow-forms',\n  'allow-modals',\n  'allow-storage-access-by-user-activation'\n].join(' ');\n\nconst DEVICEMOTION_TIMEOUT = 500;\n\nexport type WebAppLaunchOptions = {\n  webViewResultUrl: WebApp['webViewResultUrl'],\n  webViewOptions: WebApp['webViewOptions'],\n  attachMenuBot?: AttachMenuBot,\n  cacheKey?: string,\n  onClose?: () => void,\n  joinChat?: {\n    queryIds: Long[]\n  }\n};\n\nexport default class WebApp {\n  private telegramWebView: TelegramWebView;\n  private webViewResultUrl: WebViewResult.webViewResultUrl;\n  private webViewOptions: RequestWebViewOptions;\n  private attachMenuBot: AttachMenuBot;\n  private botInfo: BotInfo.botInfo;\n  private isCloseConfirmationNeeded: boolean;\n  private lastHeaderColor: TelegramWebViewEventMap['web_app_set_header_color'];\n  private showSettingsButton: boolean;\n  private readyResult: TelegramWebViewEventMap['iframe_ready'];\n  private reloadTimeout: number;\n  private iconElement: HTMLElement | SVGElement;\n  private listenerSetter: ListenerSetter;\n  private destroyed: boolean;\n  private joinChat: WebAppLaunchOptions['joinChat'];\n  private joinChatDecisionHandled: boolean;\n  // private mainButtonText: HTMLElement;\n\n  public header: HTMLElement;\n  public title: HTMLElement;\n  public body: HTMLElement;\n\n  public footer: HTMLElement;\n  private setMainButtonState: (state: TelegramWebViewEventMap['web_app_setup_main_button']) => void;\n  private setSecondaryButtonState: (state: TelegramWebViewEventMap['web_app_setup_secondary_button']) => void;\n  private footerCleanup: () => void;\n\n  private fullscreenButtons: HTMLElement;\n\n  private forceHide: () => void;\n  private onBackStatus: (visible: boolean) => void;\n\n  private managers: AppManagers;\n\n  public cacheKey: string;\n\n  constructor(options: WebAppLaunchOptions & {\n    header: WebApp['header'],\n    title: WebApp['title'],\n    body: WebApp['body'],\n    forceHide: WebApp['forceHide'],\n    onBackStatus: WebApp['onBackStatus']\n  }) {\n    safeAssign(this, options);\n\n    this.listenerSetter = new ListenerSetter();\n    this.managers = rootScope.managers;\n\n    this.title.classList.add('web-app-title');\n    this.header.classList.add('web-app-header');\n    this.body.classList.add('web-app-body');\n\n    this.footer = document.createElement('div');\n    this.body.append(this.footer);\n    this.footerCleanup = render(() => this._constructFooter(), this.footer);\n\n    this.fullscreenButtons = document.createElement('div');\n    this.fullscreenButtons.classList.add('web-app-fullscreen-buttons');\n    this.body.append(this.fullscreenButtons);\n\n    const fullscreenCloseButton = ButtonIcon('close');\n    const fullscreenMoreButton = ButtonMenuToggle({\n      listenerSetter: this.listenerSetter,\n      buttons: this.getMenuButtons(),\n      direction: 'bottom-left'\n    });\n    this.fullscreenButtons.append(fullscreenMoreButton, fullscreenCloseButton);\n\n    attachClickEvent(fullscreenCloseButton, () => {\n      document.exitFullscreen();\n      this.forceHide();\n    }, {listenerSetter: this.listenerSetter});\n\n    this.listenerSetter.add(rootScope)('theme_changed', () => {\n      this.setHeaderColor();\n      this.sendTheme();\n    });\n    this.listenerSetter.add(rootScope)('attach_menu_bot', (attachMenuBot) => {\n      if(this.webViewOptions.botId === attachMenuBot.bot_id) {\n        this.attachMenuBot = attachMenuBot;\n      }\n    });\n\n    if(!this.joinChat && this.webViewResultUrl._ === 'webViewResultUrl') {\n      const queryId = this.webViewResultUrl.query_id;\n      this.listenerSetter.add(rootScope)('web_view_result_sent', (_queryId) => {\n        if(queryId === _queryId) {\n          this.forceHide();\n        }\n      });\n    }\n\n    if(this.joinChat) {\n      this.listenerSetter.add(rootScope)('join_chat_webview_decision', this.onJoinChatWebViewDecision);\n    }\n  }\n\n  private onJoinChatWebViewDecision = (update: Update.updateJoinChatWebViewDecision) => {\n    if(!this.joinChat?.queryIds.some((queryId) => String(queryId) === String(update.query_id))) {\n      return;\n    }\n\n    if(this.joinChatDecisionHandled) {\n      return;\n    }\n\n    if(update.result._ === 'joinChatBotResultWebView') {\n      this.loadExternal(update.result.url);\n      return;\n    }\n\n    this.joinChatDecisionHandled = true;\n    this.forceHide();\n  };\n\n  // the origin the bot asked the mini app to stay on, when it asked at all — the bridge is bound to\n  // it, so a document that replaces the mini app after a navigation away can neither reach the\n  // handlers nor receive the answers meant for the mini app\n  private getSameOrigin() {\n    const webViewResultUrl = this.webViewResultUrl;\n    if(!webViewResultUrl?.pFlags?.same_origin) {\n      return;\n    }\n\n    return new URL(webViewResultUrl.url).origin;\n  }\n\n  // the url is applied even before the web view exists — `createWebView` reads `webViewResultUrl.url`,\n  // so a decision arriving while `init` is still awaiting is not lost\n  private loadExternal(url: string) {\n    this.webViewResultUrl.url = url;\n    this.readyResult = undefined;\n    this.telegramWebView?.setOrigin(this.getSameOrigin());\n\n    const iframe = this.telegramWebView?.iframe;\n    if(!iframe) {\n      return;\n    }\n\n    this.hideWebViewContent();\n    iframe.addEventListener('load', this.showWebViewContent, {once: true});\n    iframe.src = this.getWebViewUrl(url);\n  }\n\n  private hideWebViewContent() {\n    const iframe = this.telegramWebView?.iframe;\n    if(!iframe) {\n      return;\n    }\n\n    iframe.style.opacity = '0';\n    iframe.classList.add('disable-hover');\n  }\n\n  private showWebViewContent = () => {\n    if(this.iconElement) {\n      this.iconElement.style.opacity = '0';\n    }\n\n    const iframe = this.telegramWebView?.iframe;\n    if(!iframe) {\n      return;\n    }\n\n    iframe.style.opacity = '1';\n    iframe.classList.remove('disable-hover');\n  };\n\n  private getWebViewUrl(url: string) {\n    return url.replace('tgWebAppVersion=8.0', 'tgWebAppVersion=9.0');\n  }\n\n  protected _constructFooter() {\n    const [mainButtonState, setMainButtonState] = createSignal<TelegramWebViewEventMap['web_app_setup_main_button']>({\n      is_visible: false,\n      is_active: false,\n      is_progress_visible: false,\n      color: 'primary',\n      text: '',\n      text_color: '#ffffff',\n      has_shine_effect: false,\n      icon_custom_emoji_id: undefined\n    });\n    let mainButtonRef: HTMLElement;\n    const [secondaryButtonState, setSecondaryButtonState] = createSignal<TelegramWebViewEventMap['web_app_setup_secondary_button']>({\n      is_visible: false,\n      is_active: false,\n      is_progress_visible: false,\n      color: 'primary',\n      text: '',\n      text_color: '#ffffff',\n      position: 'left',\n      has_shine_effect: false,\n      icon_custom_emoji_id: undefined\n    });\n    let secondaryButtonRef: HTMLElement;\n\n    this.setMainButtonState = (state) => {\n      setMainButtonState(state)\n      if(state.color) themeController.applyAppColor({\n        name: 'primary-color',\n        element: mainButtonRef,\n        hex: state.color,\n        darkenAlpha: 0.04\n      });\n      mainButtonRef.style.setProperty('--text-color', state.text_color);\n    };\n    this.setSecondaryButtonState = (state) => {\n      setSecondaryButtonState(state)\n      if(state.color) themeController.applyAppColor({\n        name: 'primary-color',\n        element: secondaryButtonRef,\n        hex: state.color,\n        darkenAlpha: 0.04\n      });\n      secondaryButtonRef.style.setProperty('--text-color', state.text_color);\n    };\n\n    attachClassName(this.footer, () => classNames(\n      'web-app-footer',\n      (mainButtonState().is_visible || secondaryButtonState().is_visible) && 'is-visible',\n      (mainButtonState().is_visible && secondaryButtonState().is_visible) && `has-two-buttons position-${secondaryButtonState().position}`\n    ));\n\n    const ButtonContent = (props: {\n      state: Accessor<TelegramWebViewEventMap['web_app_setup_main_button'] | TelegramWebViewEventMap['web_app_setup_secondary_button']>\n    }) => {\n      return (\n        <Transition name=\"fade\" mode=\"outin\">\n          <span class=\"web-app-button-content text-overflow-no-wrap\">\n            <Show\n              when={!props.state().is_progress_visible}\n              fallback={<PreloaderTsx />}\n            >\n              <Show when={props.state().icon_custom_emoji_id}>\n                {(docId) => wrapAdaptiveCustomEmoji({\n                  docId: docId(),\n                  size: 20,\n                  wrapOptions: {\n                    middleware: createMiddleware().get(),\n                    textColor: props.state().text_color\n                  }\n                }).container}\n              </Show>\n              <EmojiTextTsx text={props.state().text} />\n            </Show>\n          </span>\n        </Transition>\n      );\n    };\n\n    return (\n      <>\n        <ButtonTsx\n          ref={secondaryButtonRef}\n          class={classNames(\n            'btn-primary',\n            'btn-color-primary',\n            'web-app-button',\n            'web-app-button-secondary',\n            secondaryButtonState().is_visible && 'is-visible',\n            secondaryButtonState().is_active && 'is-active',\n            secondaryButtonState().has_shine_effect && 'shimmer'\n          )}\n          disabled={!secondaryButtonState().is_active}\n          onClick={() => this.telegramWebView.dispatchWebViewEvent('secondary_button_pressed', undefined)}\n        >\n          <ButtonContent state={secondaryButtonState} />\n        </ButtonTsx>\n        <ButtonTsx\n          ref={mainButtonRef}\n          class={classNames(\n            'btn-primary',\n            'web-app-button',\n            'btn-color-primary',\n            mainButtonState().is_visible && 'is-visible',\n            mainButtonState().has_shine_effect && 'shimmer'\n          )}\n          disabled={!mainButtonState().is_active}\n          onClick={() => this.telegramWebView.dispatchWebViewEvent('main_button_pressed', undefined)}\n        >\n          <ButtonContent state={mainButtonState} />\n        </ButtonTsx>\n      </>\n    );\n  }\n\n  public onBackClick = (): false | void => {\n    this.telegramWebView.dispatchWebViewEvent('back_button_pressed', undefined);\n    return false;\n  };\n\n  public isConfirmationNeededOnClose = () => {\n    if(!this.isCloseConfirmationNeeded) {\n      return;\n    }\n\n    return confirmationPopup({\n      descriptionLangKey: 'BotWebViewChangesMayNotBeSaved',\n      button: {\n        isDanger: true,\n        langKey: 'BotWebViewCloseAnyway'\n      }\n    });\n  };\n\n  public getMenuButtons(): ButtonMenuItemOptionsVerifiable[] {\n    const botId = this.webViewOptions.botId;\n    const botPeerId = botId.toPeerId();\n\n    return [{\n      icon: 'settings',\n      text: 'BotSettings',\n      onClick: () => {\n        this.telegramWebView.dispatchWebViewEvent('settings_button_pressed', undefined);\n      },\n      // verify: () => (this.attachMenuBot && this.attachMenuBot.pFlags.has_settings) || this.webViewOptions.hasSettings\n      verify: () => this.showSettingsButton\n    }, {\n      icon: 'bots',\n      text: 'BotWebViewOpenBot',\n      onClick: () => {\n        this.forceHide();\n        appImManager.setInnerPeer({peerId: botPeerId});\n      },\n      verify: () => this.webViewOptions.peerId !== botPeerId || appImManager.chat?.peerId !== botPeerId\n    }, {\n      icon: 'rotate_left',\n      text: 'BotWebViewReloadPage',\n      onClick: () => {\n        const fallbackReload = () => {\n          const oldWebView = this.telegramWebView;\n          const telegramWebView = this.createWebView();\n          oldWebView.iframe.replaceWith(telegramWebView.iframe);\n          oldWebView.destroy();\n          telegramWebView.onMount();\n        };\n\n        if(!this.readyResult?.reload_supported) {\n          fallbackReload();\n          return;\n        }\n\n        this.reloadTimeout = window.setTimeout(() => {\n          this.reloadTimeout = undefined;\n          fallbackReload();\n        }, 300);\n\n        this.telegramWebView.dispatchWebViewEvent('reload_iframe', undefined);\n      },\n      verify: () => true\n    }, {\n      icon: 'info',\n      text: 'TermsOfUse',\n      onClick: () => {\n        safeWindowOpen(I18n.format('WebAppDisclaimerUrl', true));\n      },\n      verify: () => true\n    }, {\n      icon: 'privacypolicy',\n      text: 'BotPrivacyPolicy',\n      onClick: () => openBotPrivacyPolicy(this.botInfo, () => {\n        this.forceHide();\n        appImManager.setInnerPeer({peerId: botPeerId});\n        this.managers.appMessagesManager.sendText({peerId: botPeerId, text: '/privacy'});\n      }),\n      verify: async() => !!(await this.getBotInfo())\n    }, {\n      icon: 'flag',\n      text: 'ReportChat',\n      onClick: () => {\n        showPeerReport(botPeerId);\n      },\n      verify: async() => canReportBot(botPeerId, await this.managers.appUsersManager.getUser(botId))\n    }, /* {\n      icon: 'plusround',\n      text: 'WebApp.InstallBot',\n      onClick: () => {\n        appImManager.toggleBotInAttachMenu(botId, true).then(async(attachMenuBot) => {\n          this.attachMenuBot = attachMenuBot;\n        });\n      },\n      verify: () => this.attachMenuBot && this.attachMenuBot.pFlags.inactive\n    },  */{\n      icon: 'delete',\n      className: 'danger',\n      text: 'BotWebViewDeleteBot',\n      onClick: () => {\n        appImManager.toggleBotInAttachMenu(botId, false).then(async(attachMenuBot) => {\n          this.attachMenuBot = attachMenuBot;\n          this.forceHide();\n        });\n      },\n      verify: () => this.attachMenuBot && !this.attachMenuBot.pFlags.inactive,\n      separator: true\n    }];\n  }\n\n  private async getBotInfo() {\n    if(!this.botInfo) {\n      const {bot_info} = await this.managers.appProfileManager.getProfile(this.webViewOptions.botId);\n      this.botInfo = bot_info;\n    }\n\n    return this.botInfo;\n  }\n\n  protected getThemeParams() {\n    return themeController.getThemeParamsForWebView();\n  }\n\n  protected sendTheme = () => {\n    this.telegramWebView.dispatchWebViewEvent('theme_changed', {\n      theme_params: this.getThemeParams()\n    });\n  };\n\n  protected setHeaderColor = (color: WebApp['lastHeaderColor'] = this.lastHeaderColor) => {\n    this.lastHeaderColor = color;\n\n    let backgroundColor: string;\n    const hex = color.color;\n    if(hex) {\n      const rgb = hexToRgb(hex);\n      const luminance = calculateLuminance(rgb);\n      const textColor = getTextColor(luminance);\n      const textOpacity = calculateOpacity(luminance, 2.5);\n      const textRgbColor = rgbaToRgb([...textColor, textOpacity], rgb);\n      // const borderColor = rgbaToRgb([...rgb, 1 - 0.08], rgb || rgbaToRgb([255, 255, 255, 0.08], rgb));\n      backgroundColor = hex;\n      this.title.style.color = `rgb(${textColor.join(',')})`;\n      this.header.style.setProperty('--secondary-text-color', `rgb(${textRgbColor.join(', ')})`);\n      this.header.style.setProperty('--light-secondary-text-color', `rgba(${textColor.join(', ')}, ${0.08})`);\n      // this.header.style.setProperty('--border-color', `rgb(${borderColor.join(', ')})`);\n      this.header.style.setProperty('--border-color', `rgba(${textColor.join(', ')}, ${0.08})`);\n    } else {\n      backgroundColor = this.getThemeParams()[color.color_key];\n      this.title.style.color = '';\n      this.header.style.removeProperty('--secondary-text-color');\n      this.header.style.removeProperty('--light-secondary-text-color');\n      this.header.style.removeProperty('--border-color');\n    }\n\n    this.header.style.backgroundColor = backgroundColor;\n  };\n\n  protected setBodyColor = (color: string) => {\n    this.body.style.backgroundColor = color;\n  };\n\n  protected switchInlineQuery = async({\n    query,\n    chat_types\n  }: TelegramWebViewEventMap['web_app_switch_inline_query']) => {\n    const user = await this.managers.appUsersManager.getUser(this.webViewOptions.botId);\n    if(user.bot_inline_placeholder === undefined) {\n      return;\n    }\n\n    this.forceHide();\n\n    const chat = appImManager.chat;\n    let peerId = chat.peerId, threadId = chat.threadId;\n    if(chat_types?.length) {\n      const chosenPeerId = await showPickUser3Popup(chat_types, ['send_inline']);\n      if(peerId !== chosenPeerId) {\n        peerId = chosenPeerId;\n        threadId = undefined;\n        await appImManager.setInnerPeer({peerId});\n      }\n    }\n\n    this.managers.appInlineBotsManager.switchInlineQuery(\n      peerId,\n      threadId,\n      this.webViewOptions.botId,\n      query\n    );\n  };\n\n  protected setupBackButton = ({\n    is_visible\n  }: TelegramWebViewEventMap['web_app_setup_back_button']) => {\n    this.onBackStatus(is_visible);\n  };\n\n  protected setupSettingsButton = ({\n    is_visible\n  }: TelegramWebViewEventMap['web_app_setup_settings_button']) => {\n    this.showSettingsButton = is_visible;\n  };\n\n  protected openPopup = async({\n    title,\n    message,\n    buttons\n  }: TelegramWebViewEventMap['web_app_open_popup']) => {\n    const buttonLangPackKeysMap: {[type in typeof buttons[0]['type']]?: LangPackKey} = {\n      cancel: 'Cancel',\n      close: 'Close',\n      ok: 'OK'\n    };\n\n    let pressedButtonId: string;\n    const popup = PopupElement.createPopup(\n      PopupPeer,\n      'popup-confirmation',\n      {\n        title: title ? wrapEmojiText(title) : undefined,\n        description: wrapEmojiText(message),\n        buttons: buttons.map(({type, text, id}) => {\n          const langPackKey = buttonLangPackKeysMap[type];\n          const button: PopupPeerOptions['buttons'][0] = {\n            langKey: langPackKey,\n            text: !langPackKey ? wrapEmojiText(text) : undefined,\n            isCancel: true,\n            isDanger: type === 'destructive',\n            callback: () => {\n              pressedButtonId = id;\n            }\n          };\n\n          return button;\n        })\n      }\n    );\n\n    const promise = new Promise<void>((resolve) => {\n      popup.addEventListener('close', () => {\n        this.telegramWebView.dispatchWebViewEvent('popup_closed', {\n          ...(pressedButtonId !== undefined ? {button_id: pressedButtonId} : {})\n        });\n        resolve();\n      });\n    });\n\n    popup.show();\n\n    return promise;\n  };\n\n  public destroy() {\n    if(this.destroyed) {\n      return;\n    }\n\n    this.destroyed = true;\n    this.telegramWebView?.destroy();\n    this.listenerSetter.removeAll();\n    clearTimeout(this.reloadTimeout);\n    clearTimeout(this._deviceMotionTimeoutId);\n    clearTimeout(this._deviceOrientationTimeoutId);\n    window.removeEventListener('devicemotion', this.handleDeviceMotion);\n    window.removeEventListener('deviceorientation', this.handleDeviceOrientation);\n    window.removeEventListener('deviceorientationabsolute', this.handleDeviceOrientation);\n    this.footerCleanup?.();\n  }\n\n\n  protected debouncePopupMethod<T extends AnyFunction, K extends keyof TelegramWebViewSendEventMap>(\n    callback: T,\n    resultType: K,\n    debouncedResult: TelegramWebViewSendEventMap[K]\n  ) {\n    let isOpen = false, debouncing = false;\n    return (async(...args: any[]) => {\n      if(isOpen) {\n        return;\n      }\n\n      const {lastDispatchedWebViewEvent} = this.telegramWebView;\n      if(!debouncing && lastDispatchedWebViewEvent?.type === resultType && lastDispatchedWebViewEvent.count >= 3) {\n        debouncing = true;\n        setTimeout(() => {\n          if(this.telegramWebView.lastDispatchedWebViewEvent === lastDispatchedWebViewEvent) {\n            this.telegramWebView.lastDispatchedWebViewEvent.count = 0;\n          }\n          debouncing = false;\n        }, 3000);\n      }\n\n      if(debouncing) {\n        this.telegramWebView.dispatchWebViewEvent(resultType, debouncedResult);\n        return;\n      }\n\n      isOpen = true;\n      try {\n        await callback(...args);\n      } finally {\n        isOpen = false;\n      }\n    }) as T;\n  }\n\n  protected handleReadClipboard = async({req_id}: TelegramWebViewEventMap['web_app_read_text_from_clipboard']) => {\n    const result: TelegramWebViewSendEventMap['clipboard_text_received'] = {\n      req_id\n    };\n\n    if(this.attachMenuBot && !this.attachMenuBot.pFlags.inactive) try {\n      const permission = await navigator.permissions.query({\n        // @ts-ignore\n        name: 'clipboard-read'\n      });\n\n      if(permission.state === 'granted') {\n        result.data = await navigator.clipboard.readText();\n      }\n    } catch(error) {\n      console.error('clipboard read error', error);\n    }\n\n    this.telegramWebView.dispatchWebViewEvent('clipboard_text_received', result);\n  };\n\n  protected handleHapticFeedback = (data: TelegramWebViewEventMap['web_app_trigger_haptic_feedback']) => {\n    if(!navigator.vibrate) {\n      return;\n    }\n\n    let pattern: number[];\n    switch(data.type) {\n      case 'impact':\n        switch(data.impact_style) {\n          case 'light':\n            pattern = [60];\n            break;\n          case 'medium':\n            pattern = [70];\n            break;\n          case 'heavy':\n            pattern = [80]\n            break;\n          case 'rigid':\n            pattern = [50]\n            break;\n          case 'soft':\n            pattern = [55]\n            break;\n        }\n        break\n      case 'notification':\n        switch(data.notification_type) {\n          case 'error':\n            pattern = [40, 60, 40, 60, 65, 60, 40];\n            break;\n          case 'success':\n            pattern = [50, 60, 65];\n            break;\n          case 'warning':\n            pattern = [65, 60, 40];\n            break;\n        }\n      case 'selection_change':\n        pattern = [30];\n        break;\n    }\n\n    if(pattern) {\n      navigator.vibrate(pattern);\n    }\n  };\n\n  protected handleSetEmojiStatus = this.debouncePopupMethod(async(data) => {\n    const {telegramWebView, managers, webViewOptions} = this;\n    const doc = await managers.appEmojiManager.getCustomEmojiDocument(data.custom_emoji_id);\n    if(!doc) {\n      telegramWebView.dispatchWebViewEvent('emoji_status_failed', {error: 'SUGGESTED_EMOJI_INVALID'});\n      return;\n    }\n\n    const duration = data.duration ?? 0;\n    const popup = PopupElement.createPopup(PopupWebAppEmojiStatusAccess, {\n      botId: webViewOptions.botId.toPeerId(),\n      sticker: doc,\n      period: duration\n    });\n\n    popup.addEventListener('finish', async(result) => {\n      if(result) {\n        if(!(await managers.rootScope.getPremium())) {\n          PopupPremium.show({feature: 'emoji_status'});\n          telegramWebView.dispatchWebViewEvent('emoji_status_failed', {error: 'SERVER_ERROR'});\n          return;\n        }\n\n        try {\n          await managers.appUsersManager.updateEmojiStatus({\n            _: 'emojiStatus',\n            document_id: data.custom_emoji_id,\n            until: duration ? tsNow(true) + duration : undefined\n          });\n          toastNew({langPackKey: 'SetAsEmojiStatusInfo'});\n          telegramWebView.dispatchWebViewEvent('emoji_status_set', undefined);\n        } catch(err) {\n          console.log(err);\n          toastNew({langPackKey: 'Error.AnError'});\n          telegramWebView.dispatchWebViewEvent('emoji_status_failed', {error: 'SERVER_ERROR'});\n        }\n      } else {\n        telegramWebView.dispatchWebViewEvent('emoji_status_failed', {error: 'USER_DECLINED'});\n      }\n    });\n\n    popup.show();\n  }, 'emoji_status_failed', {error: 'USER_DECLINED'});\n\n  protected handleEmojiStatusAccess = this.debouncePopupMethod(async() => {\n    const {telegramWebView, managers, webViewOptions} = this;\n    const peer = await managers.appProfileManager.getCachedFullUser(this.webViewOptions.botId);\n    if(peer.pFlags.bot_can_manage_emoji_status) {\n      telegramWebView.dispatchWebViewEvent('emoji_status_access_requested', {status: 'allowed'});\n      return;\n    }\n\n    const defaultEmojis = await managers.appStickersManager.getLocalStickerSet('inputStickerSetEmojiDefaultStatuses')\n    const popup = PopupElement.createPopup(PopupWebAppEmojiStatusAccess, {\n      botId: webViewOptions.botId.toPeerId(),\n      defaultStatusEmojis: defaultEmojis.documents as MyDocument[]\n    });\n\n    popup.addEventListener('finish', async(result) => {\n      if(result) {\n        if(!(await managers.rootScope.getPremium())) {\n          PopupPremium.show({feature: 'emoji_status'});\n          telegramWebView.dispatchWebViewEvent('emoji_status_access_requested', {status: 'cancelled'});\n          return;\n        }\n\n        try {\n          await managers.appBotsManager.toggleEmojiStatusPermission(this.webViewOptions.botId, true);\n        } catch(err) {\n          console.error(err);\n          toastNew({langPackKey: 'Error.AnError'});\n          telegramWebView.dispatchWebViewEvent('emoji_status_access_requested', {status: 'cancelled'});\n          return\n        }\n\n        telegramWebView.dispatchWebViewEvent('emoji_status_access_requested', {status: 'allowed'});\n      } else {\n        telegramWebView.dispatchWebViewEvent('emoji_status_access_requested', {status: 'cancelled'});\n      }\n    });\n\n    popup.show();\n  }, 'emoji_status_access_requested', {status: 'cancelled'});\n\n  protected handleCheckLocation = async() => {\n    const {telegramWebView} = this;\n    const browserPermission = await navigator.permissions.query({name: 'geolocation'});\n    if(browserPermission.state === 'denied') {\n      telegramWebView.dispatchWebViewEvent('location_checked', {available: false});\n      return;\n    }\n\n    const botPermission = await this.managers.appBotsManager.readBotInternalStorage(this.webViewOptions.botId, 'locationPermission');\n\n    telegramWebView.dispatchWebViewEvent('location_checked', {\n      available: true,\n      access_requested: botPermission != null,\n      access_granted: botPermission === 'true'\n    });\n  }\n\n  protected _requestLocationPopup = false;\n  protected handleRequestLocation = async() => {\n    const botPermission = await this.managers.appBotsManager.readBotInternalStorage(this.webViewOptions.botId, 'locationPermission');\n\n    const sendLocation = () => {\n      navigator.geolocation.getCurrentPosition((pos) => {\n        this.telegramWebView.dispatchWebViewEvent('location_requested', {\n          available: true,\n          latitude: pos.coords.latitude,\n          longitude: pos.coords.longitude,\n          altitude: pos.coords.altitude,\n          course: pos.coords.heading,\n          speed: pos.coords.speed,\n          horizontal_accuracy: pos.coords.accuracy,\n          vertical_accuracy: pos.coords.altitudeAccuracy,\n          course_accuracy: null,\n          speed_accuracy: null\n        });\n      }, (err) => {\n        console.error(err);\n        this.telegramWebView.dispatchWebViewEvent('location_requested', {available: false});\n      });\n    }\n\n    if(!botPermission) {\n      if(this._requestLocationPopup) return;\n      this._requestLocationPopup = true;\n      const popup = PopupElement.createPopup(PopupWebAppLocationAccess, {\n        botId: this.webViewOptions.botId.toPeerId()\n      });\n      popup.addEventListener('finish', async(result) => {\n        this._requestLocationPopup = false;\n        await this.managers.appBotsManager.writeBotInternalStorage(this.webViewOptions.botId, 'locationPermission', String(result));\n        if(result) {\n          sendLocation();\n        } else {\n          this.telegramWebView.dispatchWebViewEvent('location_requested', {available: false});\n        }\n      });\n      popup.show();\n      return;\n    }\n\n    if(botPermission === 'true') {\n      sendLocation();\n    } else {\n      this.telegramWebView.dispatchWebViewEvent('location_requested', {available: false});\n    }\n  }\n\n  protected _gyroscopeFreqMs = -1;\n  protected _gyroscopeLastEvent = 0;\n  protected _accelerometerFreqMs = -1;\n  protected _accelerometerLastEvent = 0;\n  protected _deviceMotionTimeoutId: number | null = null;\n  protected handleDeviceMotion = (event: DeviceMotionEvent) => {\n    if(this._deviceMotionTimeoutId !== null) {\n      clearTimeout(this._deviceMotionTimeoutId);\n      this._deviceMotionTimeoutId = null;\n\n      if(this._gyroscopeFreqMs !== -1) {\n        if(event.rotationRate.alpha !== null && event.rotationRate.beta !== null && event.rotationRate.gamma !== null) {\n          this.telegramWebView.dispatchWebViewEvent('gyroscope_started', undefined);\n        } else {\n          this.telegramWebView.dispatchWebViewEvent('gyroscope_failed', {error: 'UNSUPPORTED'});\n          return;\n        }\n      }\n\n      if(this._accelerometerFreqMs !== -1) {\n        if(event.acceleration.x !== null && event.acceleration.y !== null && event.acceleration.z !== null) {\n          this.telegramWebView.dispatchWebViewEvent('accelerometer_started', undefined);\n        } else {\n          this.telegramWebView.dispatchWebViewEvent('accelerometer_failed', {error: 'UNSUPPORTED'});\n          return;\n        }\n      }\n    }\n\n    const shouldEmitGyroscope = this._gyroscopeFreqMs !== -1 && performance.now() - this._gyroscopeLastEvent > this._gyroscopeFreqMs;\n    const shouldEmitAccelerometer = this._accelerometerFreqMs !== -1 && performance.now() - this._accelerometerLastEvent > this._accelerometerFreqMs;\n\n    if(shouldEmitGyroscope) {\n      this._gyroscopeLastEvent = performance.now();\n      this.telegramWebView.dispatchWebViewEvent('gyroscope_changed', {\n        x: event.rotationRate.alpha,\n        y: event.rotationRate.beta,\n        z: event.rotationRate.gamma\n      });\n    }\n\n    if(shouldEmitAccelerometer) {\n      this._accelerometerLastEvent = performance.now();\n      this.telegramWebView.dispatchWebViewEvent('accelerometer_changed', {\n        x: event.acceleration.x,\n        y: event.acceleration.y,\n        z: event.acceleration.z\n      });\n    }\n  }\n\n  protected _deviceOrientationFreqMs = -1;\n  protected _deviceOrientationAbsolute = false;\n  protected _deviceOrientationLastEvent = 0;\n  protected _deviceOrientationTimeoutId: number | null = null;\n  protected handleDeviceOrientation = (event: DeviceOrientationEvent) => {\n    if(this._deviceOrientationTimeoutId !== null) {\n      clearTimeout(this._deviceOrientationTimeoutId);\n      this._deviceOrientationTimeoutId = null;\n\n      if(event.alpha !== null && event.beta !== null && event.gamma !== null) {\n        this.telegramWebView.dispatchWebViewEvent('device_orientation_started', undefined);\n      } else {\n        this.telegramWebView.dispatchWebViewEvent('device_orientation_failed', {error: 'UNSUPPORTED'});\n        return;\n      }\n    }\n\n    const shouldEmit = this._deviceOrientationFreqMs !== -1 && performance.now() - this._deviceOrientationLastEvent > this._deviceOrientationFreqMs;\n    if(!shouldEmit) return;\n\n    this._deviceOrientationLastEvent = performance.now();\n    this.telegramWebView.dispatchWebViewEvent('device_orientation_changed', {\n      absolute: event.absolute,\n      alpha: event.alpha,\n      beta: event.beta,\n      gamma: event.gamma\n    });\n  }\n\n  protected setupDeviceMotion() {\n    window.removeEventListener('devicemotion', this.handleDeviceMotion);\n    clearTimeout(this._deviceMotionTimeoutId);\n\n    if(this._gyroscopeFreqMs !== -1 || this._accelerometerFreqMs !== -1) {\n      window.addEventListener('devicemotion', this.handleDeviceMotion, true);\n\n      this._deviceMotionTimeoutId = window.setTimeout(() => {\n        if(this._gyroscopeFreqMs !== -1) {\n          this.telegramWebView.dispatchWebViewEvent('gyroscope_failed', {error: 'UNSUPPORTED'});\n        }\n        if(this._accelerometerFreqMs !== -1) {\n          this.telegramWebView.dispatchWebViewEvent('accelerometer_failed', {error: 'UNSUPPORTED'});\n        }\n      }, DEVICEMOTION_TIMEOUT);\n    }\n  }\n\n  protected _fileDownloadPending = false;\n  protected handleFileDownload = async(event: TelegramWebViewEventMap['web_app_request_file_download']) => {\n    if(this._fileDownloadPending) return;\n    this._fileDownloadPending = true;\n\n    const {telegramWebView, managers, webViewOptions} = this;\n\n    try {\n      const allow = await managers.apiManager.invokeApiSingle('bots.checkDownloadFileParams', {\n        bot: await managers.appUsersManager.getUserInput(webViewOptions.botId),\n        file_name: event.file_name,\n        url: event.url\n      });\n\n      if(!allow) {\n        telegramWebView.dispatchWebViewEvent('file_download_requested', {status: 'cancelled'});\n        return;\n      }\n    } catch(e) {\n      telegramWebView.dispatchWebViewEvent('file_download_requested', {status: 'cancelled'});\n      return;\n    }\n\n    const popup = PopupElement.createPopup(PopupPeer, 'popup-confirmation', {\n      titleLangKey: 'BotDownloadPromptTitle',\n      descriptionLangKey: 'BotDownloadPromptText',\n      descriptionLangArgs: [\n        await wrapPeerTitle({peerId: webViewOptions.botId.toPeerId()}),\n        event.file_name\n      ],\n      buttons: [\n        {\n          langKey: 'BotDownloadAccept',\n          callback: () => {\n            this._fileDownloadPending = false;\n            telegramWebView.dispatchWebViewEvent('file_download_requested', {status: 'downloading'});\n            // try downloading with fetch\n            appDownloadManager.downloadToDisc({\n              media: {\n                _: 'inputWebFileLocation',\n                url: 'web-app-ext:' + event.url,\n                access_hash: ''\n              },\n              fileName: event.file_name\n            }).catch((e) => {\n              this._fileDownloadPending = false;\n              PopupElement.createPopup(PopupPeer, 'popup-confirmation', {\n                titleLangKey: 'BotDownloadPromptTitle',\n                descriptionLangKey: 'BotDownloadPromptManual',\n                buttons: [\n                  // <a download=\"...\" /> only works for same-origin urls\n                  {langKey: 'Confirm', callback: () => safeWindowOpen(event.url)},\n                  {langKey: 'Cancel', isCancel: true}\n                ]\n              }).show();\n            });\n          }\n        },\n        {\n          langKey: 'Cancel',\n          isCancel: true\n        }\n      ]\n    });\n\n    popup.addEventListener('close', () => {\n      if(this._fileDownloadPending) {\n        this._fileDownloadPending = false;\n        telegramWebView.dispatchWebViewEvent('file_download_requested', {status: 'cancelled'});\n      }\n    });\n\n    popup.show();\n  }\n\n  protected createWebView() {\n    const telegramWebView = this.telegramWebView = new TelegramWebView({\n      url: this.getWebViewUrl(this.webViewResultUrl.url), // fixme\n      origin: this.getSameOrigin(),\n      sandbox: SANDBOX_ATTRIBUTES,\n      allow: 'camera; microphone; geolocation; accelerometer; gyroscope; magnetometer; device-orientation; clipboard-write;',\n      onLoad: () => this.showWebViewContent()\n    });\n\n    this.hideWebViewContent();\n    telegramWebView.iframe.allowFullscreen = true;\n\n    telegramWebView.addMultipleEventsListeners({\n      iframe_ready: (result) => {\n        this.readyResult = result;\n      },\n      iframe_will_reload: () => {\n        if(this.reloadTimeout) {\n          clearTimeout(this.reloadTimeout);\n          this.reloadTimeout = undefined;\n        }\n      },\n      web_app_ready: () => {\n        this.showWebViewContent();\n      },\n      web_app_data_send: ({data}) => {\n        if(!this.webViewOptions.isSimpleWebView || this.webViewOptions.fromSwitchWebView) {\n          return;\n        }\n\n        this.forceHide();\n        this.managers.appAttachMenuBotsManager.sendWebViewData(this.webViewOptions.botId, this.webViewOptions.buttonText, data);\n      },\n      web_app_close: () => {\n        this.forceHide();\n      },\n      web_app_open_link: ({url}) => {\n        this.managers.apiManager.getAppConfig().then((config) => {\n          const url_ = new URL(url);\n          if(config.web_app_allowed_protocols?.includes(url_.protocol.slice(0, -1))) {\n            safeWindowOpen(url);\n          }\n        })\n      },\n      web_app_open_tg_link: ({path_full}) => {\n        appImManager.openUrl(getWebViewTgLink(path_full));\n        // this.forceHide();\n      },\n      web_app_open_invoice: ({slug}) => {\n        const link: InternalLink.InternalLinkInvoice = {\n          _: INTERNAL_LINK_TYPE.INVOICE,\n          slug\n        };\n\n        internalLinkProcessor.processInvoiceLink(link).then((popupPayment) => {\n          popupPayment.addEventListener('finish', (result) => {\n            telegramWebView.dispatchWebViewEvent('invoice_closed', {\n              slug,\n              status: result\n            });\n          });\n        });\n      },\n      web_app_request_theme: this.sendTheme,\n      web_app_set_background_color: ({color}) => this.setBodyColor(color),\n      web_app_set_header_color: this.setHeaderColor,\n      web_app_switch_inline_query: this.switchInlineQuery,\n      web_app_setup_main_button: (opts) => this.setMainButtonState(opts),\n      web_app_setup_secondary_button: (opts) => this.setSecondaryButtonState(opts),\n      web_app_setup_back_button: this.setupBackButton,\n      web_app_setup_settings_button: this.setupSettingsButton,\n      web_app_setup_closing_behavior: ({need_confirmation}) => this.isCloseConfirmationNeeded = !!need_confirmation,\n      web_app_open_popup: this.debouncePopupMethod(this.openPopup, 'popup_closed', {}),\n      web_app_open_scan_qr_popup: () => telegramWebView.dispatchWebViewEvent('scan_qr_popup_closed', {}),\n      web_app_read_text_from_clipboard: this.handleReadClipboard,\n      web_app_request_write_access: this.debouncePopupMethod(async() => {\n        const botId = this.webViewOptions.botId;\n        const canSendMessage = await this.managers.appBotsManager.canSendMessage(botId);\n        const status: TelegramWebViewSendEventMap['write_access_requested'] = {status: 'allowed'};\n        if(!canSendMessage) {\n          try {\n            await confirmationPopup({\n              titleLangKey: 'WebApp.WriteAccess.Title',\n              descriptionLangKey: 'WebApp.WriteAccess.Description',\n              descriptionLangArgs: [await wrapPeerTitle({peerId: botId.toPeerId(false)})],\n              button: {\n                langKey: 'OK'\n              }\n            });\n\n            await this.managers.appBotsManager.allowSendMessage(botId);\n          } catch(err) {\n            status.status = 'cancelled';\n          }\n        }\n\n        telegramWebView.dispatchWebViewEvent('write_access_requested', status);\n      }, 'write_access_requested', {status: 'cancelled'}),\n      web_app_request_phone: this.debouncePopupMethod(async() => {\n        const status: TelegramWebViewSendEventMap['phone_requested'] = {status: 'sent'};\n        try {\n          const botId = this.webViewOptions.botId;\n          await this.managers.appMessagesManager.unblockBot(botId);\n          await appImManager.requestPhone(botId.toPeerId(false));\n        } catch(err) {\n          status.status = 'cancelled';\n        }\n\n        telegramWebView.dispatchWebViewEvent('phone_requested', status);\n      }, 'phone_requested', {status: 'cancelled'}),\n      web_app_request_chat: this.debouncePopupMethod(async({req_id}: TelegramWebViewEventMap['web_app_request_chat']) => {\n        const botId = this.webViewOptions.botId;\n        let sent = false;\n        try {\n          const button = await this.managers.appAttachMenuBotsManager.getRequestedWebViewButton(botId, req_id);\n          if(button?._ !== 'keyboardButtonRequestPeer' || button.peer_type._ === 'requestPeerTypeCreateBot') {\n            throw new Error('REQUEST_CHAT_UNSUPPORTED');\n          }\n\n          const requestingPeerId = botId.toPeerId(false);\n          const requestedPeerIds = await selectRequestPeers({button, requestingPeerId});\n          await this.managers.appMessagesManager.sendBotRequestedPeer(\n            requestingPeerId,\n            button.button_id,\n            requestedPeerIds,\n            {webappReqId: req_id}\n          );\n\n          sent = true;\n        } catch{}\n\n        telegramWebView.dispatchWebViewEvent(sent ? 'requested_chat_sent' : 'requested_chat_failed', {req_id});\n      }, 'requested_chat_failed', {req_id: ''}),\n      web_app_invoke_custom_method: async({req_id, method, params}) => {\n        let result: DataJSON.dataJSON, error: ApiError;\n        try {\n          result = await this.managers.appAttachMenuBotsManager.invokeWebViewCustomMethod(\n            this.webViewOptions.botId,\n            method,\n            params\n          );\n        } catch(_error) {\n          error = _error as ApiError;\n        }\n\n        telegramWebView.dispatchWebViewEvent('custom_method_invoked', {\n          req_id,\n          result: result && JSON.parse(result.data),\n          error: error?.type\n        });\n      },\n      web_app_biometry_get_info: () => telegramWebView.dispatchWebViewEvent('biometry_info_received', {\n        available: false,\n        access_requested: false,\n        access_granted: false,\n        token_saved: false,\n        device_id: ''\n      }),\n      web_app_trigger_haptic_feedback: this.handleHapticFeedback,\n      web_app_set_bottom_bar_color: ({color}) => {\n        this.footer.style.setProperty('--bg-color', color);\n        const luminance = calculateLuminance(hexToRgb(color));\n        const borderColor = mixColors(luminance > 0.5 ? [0, 0, 0] : [255, 255, 255], hexToRgb(color), 0.2);\n        this.footer.style.setProperty('--border-color', rgbaToHexa(borderColor));\n      },\n      // we can't use w3c sensors reliably with iframes unfortunately: https://w3c.github.io/sensors/#focused-area :c\n      web_app_start_accelerometer: (data) => {\n        this._accelerometerFreqMs = clamp(data.refresh_rate, 20, 1000);\n        this.setupDeviceMotion();\n      },\n      web_app_stop_accelerometer: () => {\n        this._accelerometerFreqMs = -1;\n        this.setupDeviceMotion();\n        this.telegramWebView.dispatchWebViewEvent('accelerometer_stopped', undefined);\n      },\n      web_app_start_gyroscope: (data) => {\n        this._gyroscopeFreqMs = clamp(data.refresh_rate, 20, 1000);\n        this.setupDeviceMotion();\n      },\n      web_app_stop_gyroscope: () => {\n        this._gyroscopeFreqMs = -1;\n        this.setupDeviceMotion();\n        this.telegramWebView.dispatchWebViewEvent('gyroscope_stopped', undefined);\n      },\n      web_app_start_device_orientation: (data) => {\n        this._deviceOrientationFreqMs = clamp(data.refresh_rate, 20, 1000);\n        this._deviceOrientationAbsolute = data.need_absolute && !IS_SAFARI;\n        const eventName = this._deviceOrientationAbsolute ? 'deviceorientationabsolute' : 'deviceorientation';\n        window.addEventListener(eventName, this.handleDeviceOrientation, true);\n\n        this._deviceOrientationTimeoutId = window.setTimeout(() => {\n          this.telegramWebView.dispatchWebViewEvent('device_orientation_failed', {error: 'UNSUPPORTED'});\n        }, DEVICEMOTION_TIMEOUT);\n      },\n      web_app_stop_device_orientation: () => {\n        this._deviceOrientationFreqMs = -1;\n        const eventName = this._deviceOrientationAbsolute ? 'deviceorientationabsolute' : 'deviceorientation';\n        window.removeEventListener(eventName, this.handleDeviceOrientation);\n        this.telegramWebView.dispatchWebViewEvent('device_orientation_stopped', undefined);\n        clearTimeout(this._deviceOrientationTimeoutId);\n      },\n      web_app_add_to_home_screen: (data) => {\n        telegramWebView.dispatchWebViewEvent('home_screen_failed', {error: 'UNSUPPORTED'});\n      },\n      web_app_check_home_screen: (data) => {\n        telegramWebView.dispatchWebViewEvent('home_screen_checked', {status: 'unsupported'});\n      },\n      web_app_set_emoji_status: this.handleSetEmojiStatus,\n      web_app_request_emoji_status_access: this.handleEmojiStatusAccess,\n      web_app_check_location: this.handleCheckLocation,\n      web_app_request_location: this.handleRequestLocation,\n      web_app_open_location_settings: async() => {\n        const botPermission = await this.managers.appBotsManager.readBotInternalStorage(this.webViewOptions.botId, 'locationPermission');\n        if(botPermission == null) return;\n        appImManager.setInnerPeer({peerId: this.webViewOptions.botId.toPeerId()});\n        appSidebarRight.toggleSidebar(true);\n      },\n      web_app_request_file_download: this.handleFileDownload,\n      web_app_device_storage_save_key: async({req_id, key, value}) => {\n        const error = await this.managers.appBotsManager.writeBotDeviceStorage(this.webViewOptions.botId, key, value);\n        if(error) {\n          this.telegramWebView.dispatchWebViewEvent('device_storage_failed', {req_id, error});\n        } else {\n          this.telegramWebView.dispatchWebViewEvent('device_storage_key_saved', {req_id});\n        }\n      },\n      web_app_device_storage_get_key: async({req_id, key}) => {\n        const value = await this.managers.appBotsManager.readBotDeviceStorage(this.webViewOptions.botId, key);\n        this.telegramWebView.dispatchWebViewEvent('device_storage_key_received', {req_id, value: value ?? null});\n      },\n      web_app_device_storage_clear: async({req_id}) => {\n        await this.managers.appBotsManager.clearBotDeviceStorage(this.webViewOptions.botId);\n        this.telegramWebView.dispatchWebViewEvent('device_storage_cleared', {req_id});\n      },\n      web_app_request_fullscreen: () => {\n        if(document.fullscreenElement === this.body) {\n          this.telegramWebView.dispatchWebViewEvent('fullscreen_failed', {error: 'ALREADY_FULLSCREEN'});\n          return;\n        }\n\n        this.body.requestFullscreen().catch((err) => {\n          console.error(err);\n          this.telegramWebView.dispatchWebViewEvent('fullscreen_failed', {error: 'UNSUPPORTED'});\n        });\n      },\n      web_app_exit_fullscreen: () => {\n        if(document.fullscreenElement === this.body) {\n          document.exitFullscreen();\n        }\n\n        telegramWebView.dispatchWebViewEvent('fullscreen_changed', {is_fullscreen: false});\n      },\n      web_app_secure_storage_save_key: ({req_id}) => telegramWebView.dispatchWebViewEvent('secure_storage_failed', {req_id, error: 'UNSUPPORTED'}),\n      web_app_secure_storage_get_key: ({req_id}) => telegramWebView.dispatchWebViewEvent('secure_storage_failed', {req_id, error: 'UNSUPPORTED'}),\n      web_app_secure_storage_restore_key: ({req_id}) => telegramWebView.dispatchWebViewEvent('secure_storage_failed', {req_id, error: 'UNSUPPORTED'}),\n      web_app_secure_storage_clear: ({req_id}) => telegramWebView.dispatchWebViewEvent('secure_storage_failed', {req_id, error: 'UNSUPPORTED'}),\n      web_app_share_to_story: () => {\n        toastNew({langPackKey: 'BotStorySharingNotSupported'});\n      },\n      web_app_send_prepared_message: this.debouncePopupMethod(async({id}) => {\n        let message: MessagesPreparedInlineMessage.messagesPreparedInlineMessage;\n        try {\n          message = await this.managers.appBotsManager.getPreparedMessage(this.webViewOptions.botId, id);\n        } catch(err) {\n          this.telegramWebView.dispatchWebViewEvent('prepared_message_failed', {error: (err as any).code});\n          return;\n        }\n\n        const popup = PopupElement.createPopup(PopupWebAppPreparedMessage, {\n          message,\n          botId: this.webViewOptions.botId\n        });\n\n        popup.addEventListener('finish', async(error) => {\n          if(error) {\n            this.telegramWebView.dispatchWebViewEvent('prepared_message_failed', {error});\n          } else {\n            this.telegramWebView.dispatchWebViewEvent('prepared_message_sent', undefined);\n            this.forceHide();\n          }\n        });\n\n        popup.show();\n      }, 'prepared_message_failed', {error: 'USER_DECLINED'}),\n      web_app_verify_age: async({passed, age}) => {\n        if(!passed) return;\n        const config = await this.managers.apiManager.getAppConfig();\n\n        // * only the configured age-verification bot may attest age — otherwise any\n        // * third-party Mini App could self-enable sensitive content\n        const verifyAgeBotUsername = (config.verify_age_bot_username ?? 'TelegramAge').toLowerCase();\n        const usernames = await this.managers.appPeersManager.getPeerActiveUsernames(this.getPeerId());\n        if(!usernames.some((username) => username.toLowerCase() === verifyAgeBotUsername)) {\n          return;\n        }\n\n        const minAge = config.verify_age_min ?? 18;\n        if(age < minAge) {\n          toastNew({langPackKey: 'AgeVerification.Failed'});\n          return;\n        }\n\n        await this.managers.appPrivacyManager.notifyAgeVerified();\n      }\n    });\n\n    telegramWebView.iframe.classList.add('payment-verification');\n    return telegramWebView;\n  }\n\n  public getPeerId() {\n    if(this.attachMenuBot) {\n      return this.attachMenuBot.bot_id.toPeerId(false);\n    } else {\n      return this.webViewOptions.botId.toPeerId(false);\n    }\n  }\n\n  public async getTitle(plain: true): Promise<string>;\n  public async getTitle(plain: false): Promise<HTMLElement | DocumentFragment>;\n  public async getTitle(plain: boolean): Promise<string | HTMLElement | DocumentFragment> {\n    if(!this.attachMenuBot) {\n      const peerId = this.getPeerId();\n      if(plain) return getPeerTitle({peerId, plainText: true});\n      else return wrapPeerTitle({peerId});\n    } else {\n      if(plain) return this.attachMenuBot.short_name;\n      else return wrapEmojiText(this.attachMenuBot.short_name);\n    }\n  }\n\n  public notifyVisible(visible: boolean) {\n    this.telegramWebView?.dispatchWebViewEvent('visibility_changed', {is_visible: visible});\n  }\n\n  public async init(mountCallback: () => MaybePromise<void>) {\n    if(!this.attachMenuBot || !IS_WEB_APP_BROWSER_SUPPORTED) {\n      const title = await this.getTitle(false);\n      if(this.destroyed) {\n        return;\n      }\n\n      this.title.append(title);\n    }\n\n    let hasIcon = false;\n    this.iconElement = document.createElement('span');\n    /* if(this.webViewOptions.app) {\n\n    } else  */try {\n      const attachMenuBot = this.attachMenuBot ?? await this.managers.appAttachMenuBotsManager.getAttachMenuBot(this.webViewOptions.botId);\n      if(this.destroyed) {\n        return;\n      }\n\n      const icon = getAttachMenuBotIcon(attachMenuBot);\n      if(icon) {\n        await wrapAttachBotIcon({\n          element: this.iconElement,\n          doc: icon.icon as Document.document,\n          size: 80,\n          textColor: () => 'secondary-text-color',\n          strokeWidth: () => .5\n        });\n        if(this.destroyed) {\n          return;\n        }\n\n        hasIcon = true;\n      }\n    } catch(err) {}\n\n    if(this.destroyed) {\n      return;\n    }\n\n    const botInfo = await this.getBotInfo();\n    if(this.destroyed) {\n      return;\n    }\n\n\n    const bodyColorFromSettings = themeController.isNight() ? botInfo.app_settings?.background_dark_color : botInfo.app_settings?.background_color;\n    const headerColorFromSettings = themeController.isNight() ? botInfo.app_settings?.header_dark_color : botInfo.app_settings?.header_color;\n\n    if(botInfo?.app_settings?.placeholder_path) {\n      const {svg, path} = createSvgFromBytes(botInfo.app_settings.placeholder_path);\n      path.setAttributeNS(null, 'fill', 'currentColor');\n      this.iconElement = svg;\n      hasIcon = true;\n    }\n\n    if(hasIcon) {\n      this.iconElement.classList.add('web-app-icon');\n    } else {\n      this.iconElement = undefined;\n    }\n\n    const telegramWebView = this.createWebView();\n\n    this.setBodyColor(bodyColorFromSettings ? rgbIntToHex(bodyColorFromSettings) : this.getThemeParams().bg_color);\n    this.setHeaderColor(headerColorFromSettings ? {color: rgbIntToHex(headerColorFromSettings)} : {color_key: 'bg_color'});\n    this.body.prepend(...[this.iconElement, telegramWebView.iframe].filter(Boolean));\n\n    this.listenerSetter.add(this.body)('fullscreenchange', () => {\n      const isFullscreen = document.fullscreenElement === this.body;\n      this.telegramWebView?.dispatchWebViewEvent('fullscreen_changed', {is_fullscreen: isFullscreen});\n      this.telegramWebView?.dispatchWebViewEvent('content_safe_area_changed', {\n        top: isFullscreen ? 56 : 0,\n        left: 0,\n        right: 0,\n        bottom: 0\n      });\n      this.body.classList.toggle('is-fullscreen', isFullscreen);\n    });\n\n    if(this.webViewOptions.fullscreen || this.webViewResultUrl?.pFlags.fullscreen) {\n      this.body.requestFullscreen().catch((err) => {\n        if(this.destroyed) {\n          return;\n        }\n\n        console.error(err);\n        this.telegramWebView?.dispatchWebViewEvent('fullscreen_failed', {error: 'UNSUPPORTED'});\n      });\n    }\n\n    Promise.resolve(mountCallback()).then(() => {\n      if(this.destroyed) {\n        return;\n      }\n\n      telegramWebView.onMount();\n\n      if(!this.joinChat && !this.webViewOptions.isSimpleWebView && (this.webViewResultUrl as WebViewResult.webViewResultUrl).query_id) {\n        setTimeout(() => this.prolongWebView(), 50e3);\n      }\n    });\n  }\n\n  private prolongWebView() {\n    this.managers.appAttachMenuBotsManager.prolongWebView({\n      queryId: (this.webViewResultUrl as WebViewResult.webViewResultUrl).query_id,\n      ...this.webViewOptions\n    }).then(() => {\n      if(this.destroyed) {\n        return;\n      }\n\n      setTimeout(() => {\n        if(this.destroyed) {\n          return;\n        }\n\n        this.prolongWebView();\n      }, 50e3);\n    }, (err: ApiError) => {\n      if(this.destroyed) {\n        return;\n      }\n\n      if(err.type === 'QUERY_ID_INVALID') {\n        this.forceHide();\n      } else {\n        console.error('web app prolong error', err);\n      }\n    });\n  }\n}\n","import {getOverlayRoot} from '@helpers/appWindow';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport mediaSizes from '@helpers/mediaSizes';\nimport clamp from '@helpers/number/clamp';\nimport safeAssign from '@helpers/object/safeAssign';\nimport windowSize from '@helpers/windowSize';\nimport SwipeHandler from '@components/swipeHandler';\n\ntype ResizeSide = 'n' | 'e' | 's' | 'w' | 'ne' | 'se' | 'sw' | 'nw';\nexport type MovableState = {\n  top?: number;\n  left?: number;\n  width: number;\n  height: number;\n};\n\nconst className = 'movable-element';\nconst resizeHandlerClassName = className + '-resize-handler';\n\nexport type MovableElementOptions = {\n  minWidth: MovableElement['minWidth'],\n  minHeight: MovableElement['minHeight'],\n  element: MovableElement['element'],\n  verifyTouchTarget?: MovableElement['verifyTouchTarget'],\n  aspectRatio?: MovableElement['aspectRatio'],\n  resetTransition?: MovableElement['resetTransition']\n};\n\nexport default class MovableElement extends EventListenerBase<{\n  resize: (state: MovableState) => void\n}> {\n  private minWidth: number;\n  private minHeight: number;\n  private element: HTMLElement;\n  private verifyTouchTarget: (evt: Parameters<SwipeHandler['verifyTouchTarget']>[0], type: 'resize' | 'move') => boolean;\n  private aspectRatio: number;\n  private resetTransition: boolean;\n\n  private top: number;\n  private left: number;\n  private _width: number;\n  private _height: number;\n\n  private swipeHandler: SwipeHandler;\n  private handlers: HTMLElement[];\n  private overlay: HTMLElement;\n\n  constructor(options: MovableElementOptions) {\n    super(true);\n    safeAssign(this, options);\n\n    this.top = this.left = this.width = this.height = 0;\n    this.element.classList.add(className);\n\n    this.addResizeHandlers();\n    this.setSwipeHandler();\n\n    mediaSizes.addEventListener('resize', this.onResize);\n  }\n\n  private onResize = () => {\n    this.fixDimensions(true);\n    this.fixPosition();\n    this.setPosition();\n  };\n\n  public toggleResizable(value: boolean) {\n    if(!value) {\n      this.destroyResizeHandlers();\n    } else {\n      this.addResizeHandlers();\n    }\n  }\n\n  public destroyElements() {\n    this.element.classList.remove(className);\n    this.destroyResizeHandlers();\n  }\n\n  public destroyResizeHandlers() {\n    if(this.handlers) {\n      this.handlers.forEach((handler) => {\n        handler.remove();\n      });\n\n      this.handlers = undefined;\n    }\n  }\n\n  public destroy() {\n    mediaSizes.removeEventListener('resize', this.onResize);\n    this.swipeHandler.removeListeners();\n  }\n\n  private addResizeHandlers() {\n    if(this.handlers) {\n      return;\n    }\n\n    const sides: ResizeSide[] = ['n', 'e', 's', 'w', 'ne', 'se', 'sw', 'nw'];\n    this.handlers = sides.map((side) => {\n      const div = document.createElement('div');\n      div.dataset.side = side;\n      div.classList.add(resizeHandlerClassName, resizeHandlerClassName + '-side-' + side);\n      this.element.append(div);\n      return div;\n    });\n  }\n\n  private setSwipeHandler() {\n    let startTop: number,\n      startLeft: number,\n      startWidth: number,\n      startHeight: number,\n      startExtraHeight: number,\n      startExtraWidth: number,\n      resizingSide: ResizeSide;\n    const swipeHandler = this.swipeHandler = new SwipeHandler({\n      element: this.element,\n      onSwipe: (xDiff, yDiff, e) => {\n        // console.log(xDiff, yDiff, e);\n\n        if(resizingSide) {\n          const changingWidth = resizingSide.includes('e') || resizingSide.includes('w');\n          const changingHeight = resizingSide.includes('n') || resizingSide.includes('s');\n          const maxPossibleWidth = resizingSide.includes('e') || !changingWidth ? windowSize.width - startLeft : startWidth + startLeft;\n          const maxPossibleHeight = resizingSide.includes('s') || !changingHeight ? windowSize.height - startTop : startHeight + startTop;\n\n          if(changingWidth) {\n            const isEnlarging = resizingSide.includes('e') && xDiff > 0 || resizingSide.includes('w') && xDiff < 0;\n            const resizeDiff = Math.abs(xDiff) * (isEnlarging ? 1 : -1);\n\n            this.width = clamp(startWidth + resizeDiff, this.minWidth, maxPossibleWidth);\n\n            if(this.aspectRatio) {\n              this.height = clamp(this.width / this.aspectRatio + startExtraHeight, this.minHeight, maxPossibleHeight);\n              this.width = this.height * this.aspectRatio + startExtraWidth;\n            }\n          }\n\n          if(changingHeight) {\n            const isEnlarging = resizingSide.includes('s') && yDiff > 0 || resizingSide.includes('n') && yDiff < 0;\n            const resizeDiff = Math.abs(yDiff) * (isEnlarging ? 1 : -1);\n\n            this.height = clamp(startHeight + resizeDiff, this.minHeight, maxPossibleHeight);\n\n            if(this.aspectRatio) {\n              this.width = clamp(this.height * this.aspectRatio + startExtraWidth, this.minWidth, maxPossibleWidth);\n              this.height = this.width / this.aspectRatio + startExtraHeight;\n            }\n          }\n\n          // this.fixDimensions();\n\n          if(resizingSide.includes('w')) {\n            this.left = Math.min(startLeft + startWidth - this.minWidth, startLeft + xDiff);\n          }\n\n          if(resizingSide.includes('n')) {\n            this.top = Math.min(startTop + startHeight - this.minHeight, startTop + yDiff);\n          }\n        } else {\n          this.top = startTop + yDiff;\n          this.left = startLeft + xDiff;\n        }\n\n        this.fixPosition();\n        this.setPosition();\n      },\n      verifyTouchTarget: (e) => {\n        const target = e.target;\n        const resizeHandler = findUpClassName(target, resizeHandlerClassName);\n\n        if(this.verifyTouchTarget && !this.verifyTouchTarget(e, resizeHandler ? 'resize' : 'move')) {\n          return false;\n        }\n\n        if(resizeHandler) {\n          resizingSide = resizeHandler.dataset.side as ResizeSide;\n          let cursor: Parameters<SwipeHandler['setCursor']>[0] = 'col-resize';\n          if(resizingSide === 'nw' || resizingSide === 'se') {\n            cursor = 'nwse-resize';\n          } else if(resizingSide === 'ne' || resizingSide === 'sw') {\n            cursor = 'nesw-resize';\n          } else if(resizingSide === 'n' || resizingSide === 's') {\n            cursor = 'row-resize';\n          }\n          swipeHandler.setCursor(cursor);\n        } else {\n          resizingSide = undefined;\n          swipeHandler.setCursor('grabbing');\n        }\n\n        return true;\n      },\n      onFirstSwipe: () => {\n        startTop = this.top;\n        startLeft = this.left;\n        startWidth = this.width;\n        startHeight = this.height;\n\n        if(!this.overlay) {\n          this.overlay = document.createElement('div');\n          this.overlay.classList.add(className + '-overlay');\n        }\n\n        this.element.append(this.overlay);\n\n        if(this.aspectRatio) {\n          startExtraWidth = this.width - this.height * this.aspectRatio;\n          startExtraHeight = this.height - this.width / this.aspectRatio;\n        }\n\n        if(this.resetTransition) {\n          this.element.classList.add('no-transition');\n          void this.element.offsetLeft; // reflow\n        }\n      },\n      onReset: () => {\n        if(this.resetTransition) {\n          this.element.classList.remove('no-transition');\n        }\n\n        this.overlay.remove();\n      },\n      setCursorTo: getOverlayRoot()\n    });\n  }\n\n  public setPositionToCenter() {\n    this.top = (windowSize.height / 2) - (this.height / 2);\n    this.left = (windowSize.width / 2) - (this.width / 2);\n    this.setPosition();\n  }\n\n  private fixDimensions(fixAspectRatio?: boolean) {\n    if(fixAspectRatio && this.aspectRatio) {\n      const extraWidth = this.width - this.height * this.aspectRatio;\n      const extraHeight = this.height - this.width / this.aspectRatio;\n\n      const maxPossibleWidth = windowSize.width - this.left;\n      const maxPossibleHeight = windowSize.height - this.top;\n      if(this.width > maxPossibleWidth) {\n        this.width = maxPossibleWidth;\n        this.height = this.width / this.aspectRatio + extraHeight;\n      } else if(this.height > maxPossibleHeight) {\n        this.height = maxPossibleHeight;\n        this.width = this.height * this.aspectRatio + extraWidth;\n      } else {\n        return;\n      }\n    }\n\n    this.width = clamp(this.width, this.minWidth, windowSize.width);\n    this.height = clamp(this.height, this.minHeight, windowSize.height);\n  }\n\n  private fixPosition() {\n    this.top = clamp(this.top, 0, windowSize.height - this.height);\n    this.left = clamp(this.left, 0, windowSize.width - this.width);\n  }\n\n  private setPosition() {\n    this.element.style.top = this.top + 'px';\n    this.element.style.left = this.left + 'px';\n    this.element.style.right = 'auto';\n    this.element.style.bottom = 'auto';\n    this.element.style.width = this.width + 'px';\n    this.element.style.height = this.height + 'px';\n\n    this.dispatchEvent('resize', this.state);\n  }\n\n  public get width() {\n    return this._width;\n  }\n\n  public get height() {\n    return this._height;\n  }\n\n  private set width(value: number) {\n    this._width = value;\n  }\n\n  private set height(value: number) {\n    this._height = value;\n  }\n\n  public get state(): MovableState {\n    const {top, left, width, height} = this;\n    return {\n      top,\n      left,\n      width,\n      height\n    };\n  }\n\n  public set state(state: MovableState) {\n    const {top, left, width, height} = state;\n    this.top = top;\n    this.left = left;\n    this.width = width;\n    this.height = height;\n    this.onResize();\n  }\n\n  public setMinValues(width: number, height: number) {\n    this.minWidth = width;\n    this.minHeight = height;\n  }\n}\n","import MovableElement, {MovableElementOptions, MovableState} from '@components/movableElement';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport safeAssign from '@helpers/object/safeAssign';\n\nexport default class MovablePanel {\n  #movable: MovableElement;\n  private listenerSetter: ListenerSetter;\n  private previousState: MovableState;\n  private onResize: () => void;\n  private movableOptions: MovableElementOptions;\n\n  constructor(options: {\n    listenerSetter: ListenerSetter,\n    previousState: MovableState,\n    onResize?: (state: MovableState) => void,\n    movableOptions: MovableElementOptions\n  }) {\n    safeAssign(this, options);\n\n    this.toggleMovable(!IS_TOUCH_SUPPORTED);\n\n    this.listenerSetter.add(mediaSizes)('changeScreen', (from, to) => {\n      if(to === ScreenSize.mobile || from === ScreenSize.mobile) {\n        this.toggleMovable(!IS_TOUCH_SUPPORTED);\n      }\n    });\n  }\n\n  public destroy() {\n    const movable = this.movable;\n    if(movable) {\n      movable.destroy();\n    }\n  }\n\n  public get movable() {\n    return this.#movable;\n  }\n\n  public get state() {\n    return this.movable ? this.movable.state : this.previousState;\n  }\n\n  public set state(state: MovableState) {\n    this.previousState = state;\n  }\n\n  private toggleMovable(enabled: boolean) {\n    let {movable} = this;\n    if(enabled) {\n      if(movable) {\n        return;\n      }\n\n      movable = this.#movable = new MovableElement(this.movableOptions);\n\n      movable.state = this.previousState;\n      if(this.previousState.top === undefined) {\n        movable.setPositionToCenter();\n      }\n\n      if(this.onResize) {\n        this.listenerSetter.add(movable)('resize', this.onResize);\n      }\n    } else {\n      if(!movable) {\n        return;\n      }\n\n      this.previousState = movable.state;\n      movable.destroyElements();\n      movable.destroy();\n      this.#movable = undefined;\n    }\n  }\n}\n","import {createEffect, createSignal, JSX, For, untrack, Accessor, onCleanup, Ref, createMemo} from 'solid-js';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {AvatarNew} from '@components/avatarNew';\nimport PeerTitle from '@components/peerTitle';\nimport Scrollable from '@components/scrollable2';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {Chat, MessagesChats, User} from '@layer';\nimport computeLockColor from '@helpers/computeLockColor';\nimport classNames from '@helpers/string/classNames';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport PopupPremium from '@components/popups/premium';\nimport appImManager from '@lib/appImManager';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupElement from '@components/popups';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {IconTsx} from '@components/iconTsx';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport showTooltip from '@components/tooltip';\nimport {usePeer} from '@stores/peers';\n\nlet canvas: HTMLCanvasElement, context: CanvasRenderingContext2D;\nexport function SimilarPeer(props: {\n  peerId: PeerId,\n  promises?: Promise<any>[],\n  ref?: Ref<HTMLDivElement>,\n  avatarSize: number,\n\n  isLast?: boolean,\n  count?: number,\n  defaultLimit?: number,\n  premium?: boolean\n}) {\n  if(!canvas) {\n    canvas = document.createElement('canvas');\n    canvas.width = 20;\n    canvas.height = 20;\n    context = canvas.getContext('2d', {alpha: false, willReadFrequently: true});\n  }\n\n  const [color, setColor] = createSignal<string>();\n  const [badgeBackgroundUrl, setBadgeBackgroundUrl] = createSignal<string>();\n  const onImageLoad = (image: HTMLImageElement) => {\n    if(image.naturalWidth < 100) {\n      return;\n    }\n\n    // const perf = performance.now();\n    context.drawImage(image, 0, 0, canvas.width, canvas.height);\n    setBadgeBackgroundUrl(computeLockColor(canvas));\n    // console.log('lock color', performance.now() - perf);\n  };\n\n  const avatar = untrack(() => {\n    return AvatarNew({\n      peerId: props.peerId,\n      size: props.avatarSize,\n      processImageOnLoad: onImageLoad\n    });\n  });\n  avatar.node.classList.add('similar-channels-channel-avatar');\n  const promises: Promise<any>[] = [];\n  promises.push(avatar.readyThumbPromise);\n  if(props.isLast) {\n    avatar.node.classList.add('similar-channels-channel-avatar-stack-first');\n  }\n\n  avatar.readyThumbPromise.then(() => {\n    setColor(avatar.color());\n  });\n\n  let nameElement: HTMLElement;\n  if(!props.isLast) {\n    const peerTitle = new PeerTitle();\n    promises.push(peerTitle.update({peerId: untrack(() => props.peerId)}));\n    nameElement = peerTitle.element;\n  } else {\n    nameElement = i18n('MoreSimilar');\n  }\n  nameElement.classList.add('similar-channels-channel-name');\n\n  const icon = (\n    <IconTsx\n      icon={props.isLast ? 'premium_lock' : 'newprivate_filled'}\n      class=\"similar-channels-channel-badge-icon\"\n    />\n  );\n\n  if(props.promises) {\n    props.promises.push(...promises);\n  }\n\n  const peer = usePeer(props.peerId);\n  const badge = (\n    <span\n      class=\"similar-channels-channel-badge\"\n      style={badgeBackgroundUrl() ? {'background-image': `url(${badgeBackgroundUrl()})`} : {'background-color': `var(--peer-avatar-${color()}-bottom)`}}\n    >\n      {props.isLast ? (\n        <>\n          {`+${props.count - props.defaultLimit}`}\n          {!untrack(() => props.premium) && icon}\n        </>\n      ) : (\n        <>\n          {icon}\n          {formatNumber((peer as User.user).bot_active_users || (peer as Chat.channel).participants_count || 1, 1)}\n        </>\n      )}\n    </span>\n  );\n\n  const displayBadge = createMemo(() => (peer as User.user)._ !== 'user' || (peer as User.user).bot_active_users !== undefined);\n\n  return (\n    <div\n      class={classNames('similar-channels-channel', props.isLast && 'is-last', !displayBadge() && 'no-badge')}\n      ref={props.ref}\n    >\n      {props.isLast ? (\n        <div class=\"similar-channels-channel-avatar-stack\">\n          {avatar.element}\n          <div class=\"similar-channels-channel-avatar-stack-middle\" />\n          <div class=\"similar-channels-channel-avatar-stack-last\" />\n        </div>\n      ) : avatar.element}\n      {displayBadge() && badge}\n      {nameElement}\n    </div>\n  );\n}\n\nexport default function SimilarChannels(props: {\n  chatId: ChatId,\n  onClose: () => void,\n  onAcked?: (cached: boolean) => void,\n  onReady?: () => void,\n  onEmpty?: () => void\n}) {\n  const [premium, setPremium] = createSignal(rootScope.premium);\n  const [details, setDetails] = createSignal<Awaited<Awaited<ReturnType<typeof getDetails>>['results']>>();\n  const [list, setList] = createSignal<JSX.Element>();\n\n  let {onAcked, onReady, onEmpty} = props;\n\n  const canvas = document.createElement('canvas');\n  canvas.width = 20;\n  canvas.height = 20;\n  const context = canvas.getContext('2d', {alpha: false, willReadFrequently: true});\n\n  rootScope.addEventListener('premium_toggle', setPremium);\n\n  const getDetails = async() => {\n    const r = apiManagerProxy.isPremiumFeaturesHidden();\n    const results = await Promise.all([\n      rootScope.managers.acknowledged.appChatsManager.getChannelRecommendations(props.chatId),\n      rootScope.managers.acknowledged.apiManager.getLimit('recommendedChannels', false),\n      rootScope.managers.acknowledged.apiManager.getLimit('recommendedChannels', true),\n      {cached: !(r instanceof Promise), result: Promise.resolve(r)}\n    ]);\n\n    return {\n      cached: results.every((result) => result.cached),\n      results: Promise.all(results.map((result) => result.result)) as Promise<[MessagesChats, number, number, boolean]>\n    };\n  };\n\n  createEffect(async() => {\n    premium();\n    const middleware = createMiddleware().get();\n    const {cached, results} = await getDetails();\n    onAcked?.(cached);\n    onAcked = undefined;\n    if(!middleware()) {\n      return;\n    }\n\n    const details = await results;\n    if(!middleware()) {\n      return;\n    }\n\n    if(!details[0].chats.length) {\n      props.onEmpty?.();\n      return;\n    }\n\n    setDetails(details);\n  });\n\n  createEffect(async() => {\n    const d = details();\n    if(!d) {\n      return;\n    }\n\n    const [messagesChats, defaultLimit, premiumLimit, isPremiumFeaturesHidden] = d;\n    const count = (messagesChats as MessagesChats.messagesChatsSlice).count ?? messagesChats.chats.length;\n    const hasMore = count > defaultLimit && !isPremiumFeaturesHidden;\n    const rendered: Map<HTMLElement, Chat.channel> = new Map();\n\n    const middleware = createMiddleware().get();\n    const promises: Promise<any>[] = [];\n    let ref: HTMLDivElement;\n    const list = (\n      <div ref={ref} class=\"similar-channels-list\">\n        <For each={(messagesChats.chats as Chat.channel[]).slice(0, defaultLimit)}>\n          {(chat, idx) => {\n            const isLast = hasMore && idx() === defaultLimit - 1;\n            return (\n              <SimilarPeer\n                peerId={chat.id.toPeerId(true)}\n                promises={promises}\n                isLast={isLast}\n                ref={(el) => rendered.set(el, isLast ? undefined : chat)}\n                count={count}\n                defaultLimit={defaultLimit}\n                premium={untrack(premium)}\n                avatarSize={60}\n              />\n            );\n          }}\n        </For>\n      </div>\n    );\n\n    const detach = attachClickEvent(ref, (e) => {\n      const target = findUpClassName(e.target, 'similar-channels-channel');\n      if(!target) {\n        return;\n      }\n\n      cancelEvent(e);\n      const chat = rendered.get(target);\n      if(chat) {\n        appImManager.setInnerPeer({peerId: chat.id.toPeerId(true)});\n        return;\n      }\n\n      if(premium()) {\n        showPickUserPopup({\n          onSelect: ([first]) => {\n            appImManager.setInnerPeer(first);\n          },\n          peerType: ['custom'],\n          getMoreCustom: async() => {\n            return {\n              result: messagesChats.chats.map((chat) => chat.id.toPeerId(true)),\n              isEnd: true\n            };\n          },\n          titleLangKey: 'SimilarChannels',\n          noSearch: true\n        });\n        return;\n      }\n\n      const anchor = anchorCallback(() => {\n        close();\n        PopupPremium.show();\n      });\n      anchor.classList.add('primary');\n\n      const {close} = showTooltip({\n        element: target.querySelector('.similar-channels-channel-avatar-stack, .similar-channels-channel-avatar'),\n        container: target.parentElement,\n        vertical: 'top',\n        textElement: i18n(\n          'SimilarChannels.Unlock',\n          [\n            anchor,\n            premiumLimit\n          ]\n        ),\n        icon: 'star'\n      });\n    });\n    onCleanup(detach);\n\n    await Promise.all(promises);\n    if(!middleware()) {\n      return;\n    }\n\n    setList(list);\n    onReady?.();\n    onReady = undefined;\n  });\n\n  return (\n    <div class=\"similar-channels-container\">\n      <svg class=\"similar-channels-notch\" width=\"19\" height=\"7\" viewBox=\"0 0 19 7\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n        <path class=\"similar-channels-notch-path\" fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M19 7C16.8992 7 13.59 3.88897 11.5003 1.67424C10.7648 0.894688 10.397 0.50491 10.0434 0.385149C9.70568 0.270811 9.4225 0.270474 9.08456 0.38401C8.73059 0.50293 8.36133 0.892443 7.62279 1.67147C5.52303 3.88637 2.18302 7 0 7L19 7Z\" />\n      </svg>\n      <div class=\"similar-channels-header\">\n        {i18n('SimilarChannels')}\n        <ButtonIconTsx icon=\"close\" onClick={props.onClose} />\n      </div>\n      <Scrollable axis=\"x\">\n        <div class=\"similar-channels-list-margin\"></div>\n        {list()}\n        <div class=\"similar-channels-list-margin\"></div>\n      </Scrollable>\n    </div>\n  );\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// Inline math (`$x$`) is carried through the markdown / RichText pipeline as a base64-encoded source\n// wrapped in STX (\\x02) sentinels. base64 contains no markdown-special characters, so the LaTeX\n// source survives the emphasis / escape passes and parseMarkdown untouched; the IV later decodes &\n// renders it with Temml (see instantViewMath). Mirrors how WebA (telegram-tt) renders `textMath`.\n\nconst STX = '\\x02';\n\nexport const MATH_MARKER_RE = /\\x02([A-Za-z0-9+/=]+)\\x02/g;\n\nfunction toBase64(s: string): string {\n  const bytes = new TextEncoder().encode(s);\n  let bin = '';\n  for(let i = 0; i < bytes.length; ++i) {\n    bin += String.fromCharCode(bytes[i]);\n  }\n  return btoa(bin);\n}\n\nfunction fromBase64(b64: string): string {\n  const bin = atob(b64);\n  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));\n  return new TextDecoder().decode(bytes);\n}\n\nexport function encodeInlineMath(source: string): string {\n  return STX + toBase64(source) + STX;\n}\n\nexport function decodeInlineMath(encoded: string): string {\n  return fromBase64(encoded);\n}\n","import {RichText, TextWithEntities, MessageEntity} from '@layer';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\nimport {encodeInlineMath} from '@helpers/math/mathMarker';\n\ntype Options = {\n  webPageId: Long,\n  url: string,\n  randomId: string\n};\n\nexport default function wrapTelegramRichText(\n  richText: RichText,\n  options?: Options\n): TextWithEntities {\n  const textWithEntities = wrapTextWithEntities(processRichText(richText, options));\n\n  // if(!options) {\n  //   return textWithEntities;\n  // }\n\n  // * convert textUrl to textAnchor\n  // textWithEntities.entities.forEach((entity) => {\n  //   if(entity._ === 'messageEntityTextUrl') {\n  //     try {\n  //       let url = new URL(entity.url);\n  //       if(url.protocol !== 'tg:' || url.host !== 'iv') {\n  //         return;\n  //       }\n\n  //       url = new URL(decodeURIComponent(url.searchParams.get('url')));\n  //       const hash = url.hash;\n  //       url.hash = '';\n  //       if(url.toString() === options.url) {\n  //         debugger;\n  //       }\n  //     } catch(err) {}\n  //   }\n  // });\n\n  return textWithEntities;\n}\n\nfunction processRichText(richText: RichText, options: Options): TextWithEntities {\n  switch(richText._) {\n    case 'textEmpty':\n      return {\n        _: 'textWithEntities',\n        text: '',\n        entities: []\n      };\n    case 'textPlain':\n      return {\n        _: 'textWithEntities',\n        text: richText.text,\n        entities: []\n      };\n    case 'textConcat': {\n      let text = '';\n      const entities: MessageEntity[] = [];\n      for(const part of richText.texts) {\n        const partResult = processRichText(part, options);\n        for(const entity of partResult.entities) {\n          entities.push({\n            ...entity,\n            offset: entity.offset + text.length\n          });\n        }\n        text += partResult.text;\n      }\n      return {\n        _: 'textWithEntities',\n        text,\n        entities\n      };\n    }\n    case 'textBold':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBold',\n        offset,\n        length\n      }), options);\n    case 'textItalic':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityItalic',\n        offset,\n        length\n      }), options);\n    case 'textUnderline':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityUnderline',\n        offset,\n        length\n      }), options);\n    case 'textStrike':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityStrike',\n        offset,\n        length\n      }), options);\n    case 'textFixed':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityCode',\n        offset,\n        length\n      }), options);\n    case 'textUrl': {\n      // fetchLong only returns a number for longs inside the safe-integer range — a bare truthy\n      // check would take a stringified '0' for a real webpage\n      const hasWebPage = !!richText.webpage_id && richText.webpage_id !== '0';\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityTextUrl',\n        offset,\n        length,\n        url: hasWebPage ?\n          'tg://iv?url=' + encodeURIComponent(richText.url) :\n          richText.url,\n        safe: hasWebPage\n      }), options);\n    }\n    case 'textEmail':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityEmail',\n        offset,\n        length\n      }), options);\n    case 'textMarked':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityHighlight',\n        offset,\n        length\n      }), options);\n    case 'textPhone':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityPhone',\n        offset,\n        length\n      }), options);\n    case 'textMath':\n      // Carry inline math as a base64 marker (like master's markdown path) so the IV's\n      // RichTextRenderer -> hydrateInlineMath() renders it with Temml. Consumers that want plain\n      // text (e.g. reply/search summaries) decode the marker back to the raw LaTeX source.\n      return {\n        _: 'textWithEntities',\n        text: encodeInlineMath(richText.source),\n        entities: []\n      };\n    case 'textImage':\n      return wrapEntity({_: 'textPlain', text: '\\x01'}, (offset, length) => ({\n        _: 'messageEntityCustomEmoji',\n        document_id: richText.document_id,\n        offset,\n        length,\n        w: richText.w,\n        h: richText.h\n      }), options);\n    case 'textCustomEmoji':\n      return wrapEntity({_: 'textPlain', text: richText.alt || '\\x01'}, (offset, length) => ({\n        _: 'messageEntityCustomEmoji',\n        document_id: richText.document_id,\n        offset,\n        length\n      }), options);\n    case 'textSpoiler':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySpoiler',\n        offset,\n        length\n      }), options);\n    case 'textMention':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityMention',\n        offset,\n        length\n      }), options);\n    case 'textHashtag':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityHashtag',\n        offset,\n        length\n      }), options);\n    case 'textBotCommand':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBotCommand',\n        offset,\n        length\n      }), options);\n    case 'textCashtag':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityCashtag',\n        offset,\n        length\n      }), options);\n    case 'textAutoUrl':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityUrl',\n        offset,\n        length\n      }), options);\n    case 'textAutoEmail':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityEmail',\n        offset,\n        length\n      }), options);\n    case 'textAutoPhone':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityPhone',\n        offset,\n        length\n      }), options);\n    case 'textBankCard':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityBankCard',\n        offset,\n        length\n      }), options);\n    case 'textMentionName':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityMentionName',\n        offset,\n        length,\n        user_id: richText.user_id\n      }), options);\n    case 'textDate':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityFormattedDate',\n        pFlags: richText.pFlags,\n        offset,\n        length,\n        date: richText.date\n      }), options);\n    case 'textSubscript':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySubscript',\n        offset,\n        length\n      } as any), options);\n    case 'textSuperscript':\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntitySuperscript',\n        offset,\n        length\n      } as any), options);\n    case 'textAnchor': {\n      // const url = options?.url && new URL(options.url);\n      // if(url) url.hash = richText.name;\n      return wrapEntity(richText.text, (offset, length) => ({\n        _: 'messageEntityAnchor',\n        offset,\n        length,\n        name: (options?.randomId || '') + richText.name\n        // url: 'tg://iv?' + (url ?\n        //   'url=' + encodeURIComponent(url.toString()) :\n        //   'anchor=' + encodeURIComponent('#' + richText.name)\n        // )\n      }), options);\n    }\n    case 'textDiff':\n      // Normal rendering resolves a diff to its updated text. A dedicated diff\n      // viewer can render old_text separately when that UI is implemented.\n      return processRichText(richText.text, options);\n    default:\n      return {\n        _: 'textWithEntities',\n        text: '',\n        entities: []\n      };\n  }\n}\n\nfunction wrapEntity(\n  innerRichText: RichText,\n  createEntity: (offset: number, length: number) => MessageEntity,\n  options: Options\n): TextWithEntities {\n  const innerResult = processRichText(innerRichText, options);\n  const entity = createEntity(0, innerResult.text.length);\n  return {\n    _: 'textWithEntities',\n    text: innerResult.text,\n    entities: [entity, ...innerResult.entities]\n  };\n}\n","import {For, JSX, Show} from 'solid-js';\nimport {Dynamic} from 'solid-js/web';\nimport classNames from '@helpers/string/classNames';\nimport styles from '@components/genericTable.module.scss';\n\nexport type GenericTableCell = {\n  content?: JSX.Element;\n  header?: boolean;\n  colspan?: number;\n  rowspan?: number;\n  alignCenter?: boolean;\n  alignRight?: boolean;\n  valignMiddle?: boolean;\n  valignBottom?: boolean;\n};\n\nexport type GenericTableRow = {\n  cells: GenericTableCell[];\n};\n\nexport default function GenericTable(props: {\n  rows: GenericTableRow[];\n  bordered?: boolean;\n  striped?: boolean;\n  class?: string;\n}) {\n  return (\n    <div class={classNames(styles.wrapper, 'no-scrollbar')}>\n      <table\n        class={classNames(\n          styles.genericTable,\n          props.bordered && styles.bordered,\n          props.class\n        )}\n      >\n        <Show when={props.bordered}>\n          <div class={styles.border} />\n        </Show>\n        <tbody>\n          <For each={props.rows}>{(row, idx) => (\n            <tr\n              class={classNames(\n                styles.genericRow,\n                props.striped && !(idx() % 2) && styles.striped\n              )}\n            >\n              <For each={row.cells}>{(cell) => (\n                <Dynamic\n                  component={cell.header ? 'th' : 'td'}\n                  colSpan={cell.colspan}\n                  rowSpan={cell.rowspan}\n                  class={classNames(\n                    cell.header ? styles.genericHeaderCell : styles.genericCell,\n                    cell.alignCenter && styles.cellAlignCenter,\n                    cell.alignRight && styles.cellAlignRight,\n                    cell.valignMiddle && styles.cellValignMiddle,\n                    cell.valignBottom && styles.cellValignBottom\n                  )}\n                >\n                  {cell.content}\n                </Dynamic>\n              )}</For>\n            </tr>\n          )}</For>\n        </tbody>\n      </table>\n    </div>\n  );\n}\n","import {Suspense, ParentProps, children, createMemo, JSX, createSignal, createReaction} from 'solid-js';\n\nexport default function MySuspense(props: ParentProps<{\n  onReady?: () => void;\n}>) {\n  const resolvedChildren = children(() => (\n    <Suspense>\n      {props.children}\n    </Suspense>\n  ));\n\n  // const [ready, setReady] = createSignal(false);\n  const childrenMemo = createMemo<JSX.Element>((prev) => {\n    const children = resolvedChildren() || prev;\n    // console.log('children', children);\n    if(children && !prev) {\n      // setReady(true);\n      props.onReady?.();\n    }\n    return children;\n  });\n\n  // createReaction(ready)(() => {\n  //   props.onReady?.();\n  // });\n\n  return (\n    <>\n      {childrenMemo()}\n    </>\n  );\n}\n","import {GeoPoint, InputWebFileLocation} from '@layer';\n\nexport default function getWebFileLocation(\n  geo: GeoPoint.geoPoint,\n  width: number,\n  height: number,\n  zoom: number\n): InputWebFileLocation.inputWebFileGeoPointLocation {\n  return {\n    _: 'inputWebFileGeoPointLocation',\n    access_hash: geo.access_hash,\n    geo_point: {\n      _: 'inputGeoPoint',\n      lat: geo.lat,\n      long: geo.long,\n      accuracy_radius: geo.accuracy_radius\n    },\n    w: width,\n    h: height,\n    scale: window.devicePixelRatio,\n    zoom\n  };\n}\n","export default function GeoPin() {\n  return (\n    <svg class=\"geo-pin\" xmlns=\"http://www.w3.org/2000/svg\" width=\"21.333\" height=\"37.218\" viewBox=\"0 0 20 34.892\">\n      <g transform=\"translate(-965.773 -331.784) scale(1.18559)\">\n        <path d=\"M817.112 282.971c-1.258 1.343-2.046 3.299-2.015 5.139.064 3.845 1.797 5.3 4.568 10.592.999 2.328 2.04 4.792 3.031 8.873.138.602.272 1.16.335 1.21.062.048.196-.513.334-1.115.99-4.081 2.033-6.543 3.031-8.871 2.771-5.292 4.504-6.748 4.568-10.592.031-1.84-.759-3.798-2.017-5.14-1.437-1.535-3.605-2.67-5.916-2.717-2.312-.048-4.481 1.087-5.919 2.621z\" style=\"fill:#ea4336;stroke:#ea4336;stroke-width:1;\"/>\n        <circle r=\"3.035\" cy=\"288.253\" cx=\"823.031\" style=\"fill:#970a0a;stroke-width:0\"/>\n      </g>\n    </svg>\n  ) as SVGSVGElement;\n}\n","/*\nThis file is part of Telegram Desktop,\nthe official desktop application for the Telegram messaging service.\nFor license and copyright information please follow this link:\nhttps://github.com/telegramdesktop/tdesktop/blob/master/LEGAL\n*/\n\nimport accumulate from '@helpers/array/accumulate';\nimport clamp from '@helpers/number/clamp';\n\ntype Size = {w: number, h: number};\nexport type GroupMediaLayout = {\n  geometry: {\n    x: number,\n    y: number,\n    width: number,\n    height: number\n  },\n  sides: number\n};\ntype Attempt = {\n  lineCounts: number[],\n  heights: number[]\n};\nexport const RectPart = {\n  None: 0,\n  Top: 1,\n  Right: 2,\n  Bottom: 4,\n  Left: 8\n};\n\n// https://github.com/telegramdesktop/tdesktop/blob/4669c07dc5335cbf4795bbbe5b0ab7c007b9aee2/Telegram/SourceFiles/ui/grouped_layout.cpp\nexport class Layouter {\n  private count: number;\n  private ratios: number[];\n  private proportions: string;\n  private averageRatio: number;\n  private maxSizeRatio: number;\n\n  constructor(private sizes: Size[], private maxWidth: number, private minWidth: number, private spacing: number, private maxHeight = maxWidth) {\n    this.count = sizes.length;\n    this.ratios = Layouter.countRatios(sizes);\n    this.proportions = Layouter.countProportions(this.ratios);\n    this.averageRatio = accumulate(this.ratios, 1) / this.count; // warn\n    this.maxSizeRatio = maxWidth / this.maxHeight;\n  }\n\n  public layout(): GroupMediaLayout[] {\n    if(!this.count) return [];\n    else if(this.count === 1) return this.layoutOne();\n\n    if(this.count >= 5 || this.ratios.find((r) => r > 2)) {\n      return new ComplexLayouter(this.ratios, this.averageRatio, this.maxWidth, this.minWidth, this.spacing).layout();\n    }\n\n    if(this.count === 2) return this.layoutTwo();\n    else if(this.count === 3) return this.layoutThree();\n    return this.layoutFour();\n  }\n\n  private layoutTwo(): ReturnType<Layouter['layout']> {\n    if((this.proportions === 'ww') &&\n      (this.averageRatio > 1.4 * this.maxSizeRatio) &&\n      (this.ratios[1] - this.ratios[0] < 0.2)) {\n      return this.layoutTwoTopBottom();\n    } else if(this.proportions === 'ww' || this.proportions === 'qq') {\n      return this.layoutTwoLeftRightEqual();\n    }\n    return this.layoutTwoLeftRight();\n  }\n\n  private layoutThree(): ReturnType<Layouter['layout']> {\n    if(this.proportions[0] === 'n') {\n      return this.layoutThreeLeftAndOther();\n    }\n    return this.layoutThreeTopAndOther();\n  }\n\n  private layoutFour(): ReturnType<Layouter['layout']> {\n    if(this.proportions[0] === 'w') {\n      return this.layoutFourTopAndOther();\n    }\n    return this.layoutFourLeftAndOther();\n  }\n\n  private layoutOne(): ReturnType<Layouter['layout']> {\n    const width = this.maxWidth;\n    const height = (this.sizes[0].h * width) / this.sizes[0].w;\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width, height},\n        sides: RectPart.Left | RectPart.Top | RectPart.Right | RectPart.Bottom\n      }\n    ];\n  }\n\n  private layoutTwoTopBottom(): ReturnType<Layouter['layout']> {\n    const width = this.maxWidth;\n    const height = Math.round(Math.min(\n      width / this.ratios[0],\n      Math.min(\n        width / this.ratios[1],\n        (this.maxHeight - this.spacing) / 2)));\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width, height},\n        sides: RectPart.Left | RectPart.Top | RectPart.Right\n      },\n      {\n        geometry: {x: 0, y: height + this.spacing, width, height},\n        sides: RectPart.Left | RectPart.Bottom | RectPart.Right\n      }\n    ];\n  }\n\n  private layoutTwoLeftRightEqual(): ReturnType<Layouter['layout']> {\n    const width = (this.maxWidth - this.spacing) / 2;\n    const height = Math.round(Math.min(\n      width / this.ratios[0],\n      Math.min(width / this.ratios[1], this.maxHeight * 1)));\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width, height},\n        sides: RectPart.Top | RectPart.Left | RectPart.Bottom\n      },\n      {\n        geometry: {x: width + this.spacing, y: 0, width, height},\n        sides: RectPart.Top | RectPart.Right | RectPart.Bottom\n      }\n    ];\n  }\n\n  private layoutTwoLeftRight(): ReturnType<Layouter['layout']> {\n    const minimalWidth = Math.round(this.minWidth * 1.5);\n    const secondWidth = Math.min(\n      Math.round(Math.max(\n        0.4 * (this.maxWidth - this.spacing),\n        (this.maxWidth - this.spacing) / this.ratios[0] /\n          (1 / this.ratios[0] + 1 / this.ratios[1]))),\n      this.maxWidth - this.spacing - minimalWidth);\n    const firstWidth = this.maxWidth -\n      secondWidth -\n      this.spacing;\n    const height = Math.min(\n      this.maxHeight,\n      Math.round(Math.min(\n        firstWidth / this.ratios[0],\n        secondWidth / this.ratios[1])));\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width: firstWidth, height},\n        sides: RectPart.Top | RectPart.Left | RectPart.Bottom\n      },\n      {\n        geometry: {x: firstWidth + this.spacing, y: 0, width: secondWidth, height},\n        sides: RectPart.Top | RectPart.Right | RectPart.Bottom\n      }\n    ];\n  }\n\n  private layoutThreeLeftAndOther(): ReturnType<Layouter['layout']> {\n    const firstHeight = this.maxHeight;\n    const thirdHeight = Math.round(Math.min(\n      (this.maxHeight - this.spacing) / 2.,\n      (this.ratios[1] * (this.maxWidth - this.spacing) /\n        (this.ratios[2] + this.ratios[1]))));\n    const secondHeight = firstHeight -\n      thirdHeight -\n      this.spacing;\n    const rightWidth = Math.max(\n      this.minWidth,\n      Math.round(Math.min(\n        (this.maxWidth - this.spacing) / 2.,\n        Math.min(\n          thirdHeight * this.ratios[2],\n          secondHeight * this.ratios[1]))));\n    const leftWidth = Math.min(\n      Math.round(firstHeight * this.ratios[0]),\n      this.maxWidth - this.spacing - rightWidth);\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width: leftWidth, height: firstHeight},\n        sides: RectPart.Top | RectPart.Left | RectPart.Bottom\n      },\n      {\n        geometry: {x: leftWidth + this.spacing, y: 0, width: rightWidth, height: secondHeight},\n        sides: RectPart.Top | RectPart.Right\n      },\n      {\n        geometry: {x: leftWidth + this.spacing, y: secondHeight + this.spacing, width: rightWidth, height: thirdHeight},\n        sides: RectPart.Bottom | RectPart.Right\n      }\n    ];\n  }\n\n  private layoutThreeTopAndOther(): ReturnType<Layouter['layout']> {\n    const firstWidth = this.maxWidth;\n    const firstHeight = Math.round(Math.min(\n      firstWidth / this.ratios[0],\n      (this.maxHeight - this.spacing) * 0.66));\n    const secondWidth = (this.maxWidth - this.spacing) / 2;\n    const secondHeight = Math.min(\n      this.maxHeight - firstHeight - this.spacing,\n      Math.round(Math.min(\n        secondWidth / this.ratios[1],\n        secondWidth / this.ratios[2])));\n    const thirdWidth = firstWidth - secondWidth - this.spacing;\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width: firstWidth, height: firstHeight},\n        sides: RectPart.Left | RectPart.Top | RectPart.Right\n      },\n      {\n        geometry: {x: 0, y: firstHeight + this.spacing, width: secondWidth, height: secondHeight},\n        sides: RectPart.Bottom | RectPart.Left\n      },\n      {\n        geometry: {x: secondWidth + this.spacing, y: firstHeight + this.spacing, width: thirdWidth, height: secondHeight},\n        sides: RectPart.Bottom | RectPart.Right\n      }\n    ];\n  }\n\n  private layoutFourTopAndOther(): ReturnType<Layouter['layout']> {\n    const w = this.maxWidth;\n    const h0 = Math.round(Math.min(\n      w / this.ratios[0],\n      (this.maxHeight - this.spacing) * 0.66));\n    const h = Math.round(\n      (this.maxWidth - 2 * this.spacing) /\n        (this.ratios[1] + this.ratios[2] + this.ratios[3]));\n    const w0 = Math.max(\n      this.minWidth,\n      Math.round(Math.min(\n        (this.maxWidth - 2 * this.spacing) * 0.4,\n        h * this.ratios[1])));\n    const w2 = Math.round(Math.max(\n      Math.max(\n        this.minWidth * 1.,\n        (this.maxWidth - 2 * this.spacing) * 0.33),\n      h * this.ratios[3]));\n    const w1 = w - w0 - w2 - 2 * this.spacing;\n    const h1 = Math.min(\n      this.maxHeight - h0 - this.spacing,\n      h);\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width: w, height: h0},\n        sides: RectPart.Left | RectPart.Top | RectPart.Right\n      },\n      {\n        geometry: {x: 0, y: h0 + this.spacing, width: w0, height: h1},\n        sides: RectPart.Bottom | RectPart.Left\n      },\n      {\n        geometry: {x: w0 + this.spacing, y: h0 + this.spacing, width: w1, height: h1},\n        sides: RectPart.Bottom\n      },\n      {\n        geometry: {x: w0 + this.spacing + w1 + this.spacing, y: h0 + this.spacing, width: w2, height: h1},\n        sides: RectPart.Right | RectPart.Bottom\n      }\n    ];\n  }\n\n  private layoutFourLeftAndOther(): ReturnType<Layouter['layout']> {\n    const h = this.maxHeight;\n    const w0 = Math.round(Math.min(\n      h * this.ratios[0],\n      (this.maxWidth - this.spacing) * 0.6));\n\n    const w = Math.round(\n      (this.maxHeight - 2 * this.spacing) /\n        (1. / this.ratios[1] + 1. / this.ratios[2] + 1. / this.ratios[3])\n    );\n    const h0 = Math.round(w / this.ratios[1]);\n    const h1 = Math.round(w / this.ratios[2]);\n    const h2 = h - h0 - h1 - 2 * this.spacing;\n    const w1 = Math.max(\n      this.minWidth,\n      Math.min(this.maxWidth - w0 - this.spacing, w));\n\n    return [\n      {\n        geometry: {x: 0, y: 0, width: w0, height: h},\n        sides: RectPart.Top | RectPart.Left | RectPart.Bottom\n      },\n      {\n        geometry: {x: w0 + this.spacing, y: 0, width: w1, height: h0},\n        sides: RectPart.Top | RectPart.Right\n      },\n      {\n        geometry: {x: w0 + this.spacing, y: h0 + this.spacing, width: w1, height: h1},\n        sides: RectPart.Right\n      },\n      {\n        geometry: {x: w0 + this.spacing, y: h0 + h1 + 2 * this.spacing, width: w1, height: h2},\n        sides: RectPart.Bottom | RectPart.Right\n      }\n    ];\n  }\n\n  private static countRatios(sizes: Size[]) {\n    return sizes.map((size) => size.w / size.h);\n  }\n\n  private static countProportions(ratios: number[]) {\n    return ratios.map((ratio) => (ratio > 1.2) ? 'w' : (ratio < 0.8) ? 'n' : 'q').join('');\n  }\n}\n\nclass ComplexLayouter {\n  private ratios: number[];\n  private count: number;\n\n  constructor(ratios: number[], private averageRatio: number, private maxWidth: number, private minWidth: number, private spacing: number, private maxHeight = maxWidth * 4 / 3) {\n    this.ratios = ComplexLayouter.cropRatios(ratios, averageRatio);\n    this.count = ratios.length;\n  }\n\n  private static cropRatios(ratios: number[], averageRatio: number) {\n    const kMaxRatio = 2.75;\n    const kMinRatio = 0.6667;\n    return ratios.map((ratio) => {\n      return averageRatio > 1.1 ?\n        clamp(ratio, 1., kMaxRatio) :\n        clamp(ratio, kMinRatio, 1.);\n    });\n  }\n\n  public layout(): GroupMediaLayout[] {\n    const result = new Array<GroupMediaLayout>(this.count);\n\n    const attempts: Attempt[] = [];\n    const multiHeight = (offset: number, count: number) => {\n      const ratios = this.ratios.slice(offset, offset + count); // warn\n      const sum = accumulate(ratios, 0);\n      return (this.maxWidth - (count - 1) * this.spacing) / sum;\n    };\n    const pushAttempt = (lineCounts: number[]) => {\n      const heights: number[] = [];\n      let offset = 0;\n      for(const count of lineCounts) {\n        heights.push(multiHeight(offset, count));\n        offset += count;\n      }\n      attempts.push({lineCounts, heights}); // warn\n    };\n\n    for(let first = 1; first !== this.count; ++first) {\n      const second = this.count - first;\n      if(first > 3 || second > 3) {\n        continue;\n      }\n      pushAttempt([first, second]);\n    }\n    for(let first = 1; first !== this.count - 1; ++first) {\n      for(let second = 1; second !== this.count - first; ++second) {\n        const third = this.count - first - second;\n        if((first > 3) ||\n          (second > ((this.averageRatio < 0.85) ? 4 : 3)) ||\n          (third > 3)) {\n          continue;\n        }\n        pushAttempt([first, second, third]);\n      }\n    }\n    for(let first = 1; first !== this.count - 1; ++first) {\n      for(let second = 1; second !== this.count - first; ++second) {\n        for(let third = 1; third !== this.count - first - second; ++third) {\n          const fourth = this.count - first - second - third;\n          if(first > 3 || second > 3 || third > 3 || fourth > 3) {\n            continue;\n          }\n          pushAttempt([first, second, third, fourth]);\n        }\n      }\n    }\n\n    let optimalAttempt: Attempt = null;\n    let optimalDiff = 0;\n    for(const attempt of attempts) {\n      const {heights, lineCounts: counts} = attempt;\n      const lineCount = counts.length;\n      const totalHeight = accumulate(heights, 0) +\n        this.spacing * (lineCount - 1);\n      const minLineHeight = Math.min(...heights);\n      const maxLineHeight = Math.max(...heights);\n      const bad1 = (minLineHeight < this.minWidth) ? 1.5 : 1;\n      const bad2 = (() => {\n        for(let line = 1; line !== lineCount; ++line) {\n          if(counts[line - 1] > counts[line]) {\n            return 1.5;\n          }\n        }\n        return 1.;\n      })();\n      const diff = Math.abs(totalHeight - this.maxHeight) * bad1 * bad2;\n      if(!optimalAttempt || diff < optimalDiff) {\n        optimalAttempt = attempt;\n        optimalDiff = diff;\n      }\n    }\n\n    const optimalCounts = optimalAttempt.lineCounts;\n    const optimalHeights = optimalAttempt.heights;\n    const rowCount = optimalCounts.length;\n\n    let index = 0;\n    let y = 0;\n    for(let row = 0; row !== rowCount; ++row) {\n      const colCount = optimalCounts[row];\n      const lineHeight = optimalHeights[row];\n      const height = Math.round(lineHeight);\n\n      let x = 0;\n      for(let col = 0; col !== colCount; ++col) {\n        const sides = RectPart.None |\n          (row === 0 ? RectPart.Top : RectPart.None) |\n          (row === rowCount - 1 ? RectPart.Bottom : RectPart.None) |\n          (col === 0 ? RectPart.Left : RectPart.None) |\n          (col === colCount - 1 ? RectPart.Right : RectPart.None);\n\n        const ratio = this.ratios[index];\n        const width = (col === colCount - 1) ?\n          (this.maxWidth - x) :\n          Math.round(ratio * lineHeight);\n        result[index] = {\n          geometry: {x, y, width, height},\n          sides\n        };\n\n        x += width + this.spacing;\n        ++index;\n      }\n      y += height + this.spacing;\n    }\n\n    return result;\n  }\n}\n","import {Layouter, RectPart} from '@components/groupedLayout';\n\nexport default function prepareAlbum(options: {\n  container: HTMLElement,\n  items: {w: number, h: number}[],\n  maxWidth: number,\n  minWidth: number,\n  spacing: number,\n  maxHeight?: number,\n  forMedia?: true,\n  noGroupedItem?: boolean\n}) {\n  const layouter = new Layouter(options.items, options.maxWidth, options.minWidth, options.spacing, options.maxHeight);\n  const layout = layouter.layout();\n\n  const widthItem = layout.find((item) => item.sides & RectPart.Right);\n  const width = widthItem.geometry.width + widthItem.geometry.x;\n\n  const heightItem = layout.find((item) => item.sides & RectPart.Bottom);\n  const height = heightItem.geometry.height + heightItem.geometry.y;\n\n  const container = options.container;\n  container.style.width = width + 'px';\n  container.style.height = height + 'px';\n  const children = container.children;\n\n  const items = layout.map(({geometry, sides}, idx) => {\n    let div: HTMLElement;\n    div = children[idx] as HTMLElement;\n    if(!div) {\n      div = document.createElement('div');\n      container.append(div);\n    }\n\n    div.classList.add('album-item');\n    if(!options.noGroupedItem) div.classList.add('grouped-item');\n\n    div.style.width = (geometry.width / width * 100) + '%';\n    div.style.height = (geometry.height / height * 100) + '%';\n    div.style.top = (geometry.y / height * 100) + '%';\n    div.style.left = (geometry.x / width * 100) + '%';\n\n    if(sides & RectPart.Left && sides & RectPart.Top) {\n      div.style.borderStartStartRadius = `calc(var(--border-start-start-radius) - ${options.spacing}px)`;\n    }\n\n    if(sides & RectPart.Left && sides & RectPart.Bottom) {\n      div.style.borderEndStartRadius =  `calc(var(--border-end-start-radius) - ${options.spacing}px)`;\n    }\n\n    if(sides & RectPart.Right && sides & RectPart.Top) {\n      div.style.borderStartEndRadius =  `calc(var(--border-start-end-radius) - ${options.spacing}px)`;\n    }\n\n    if(sides & RectPart.Right && sides & RectPart.Bottom) {\n      div.style.borderEndEndRadius =  `calc(var(--border-end-end-radius) - ${options.spacing}px)`;\n    }\n\n    if(options.forMedia) {\n      const mediaDiv = document.createElement('div');\n      mediaDiv.classList.add('album-item-media');\n\n      div.append(mediaDiv);\n    }\n\n    // @ts-ignore\n    // div.style.backgroundColor = '#' + Math.floor(Math.random() * (2 ** 24 - 1)).toString(16).padStart(6, '0');\n\n    return div;\n  });\n\n  /* if(options.forMedia) {\n    layout.forEach((_, i) => {\n      const mediaDiv = document.createElement('div');\n      mediaDiv.classList.add('album-item-media');\n\n      options.container.children[i].append(mediaDiv);\n    });\n  } */\n\n  return {items, width, height};\n}\n","import classNames from '@helpers/string/classNames';\nimport {JSX, splitProps} from 'solid-js';\nimport styles from './staticCheckbox.module.scss';\n\n\nexport type StaticCheckboxProps = JSX.HTMLAttributes<HTMLDivElement> & {\n  checked?: boolean;\n  round?: boolean;\n  /**\n   * TODO: animation from unchecked to checked is not yet supported, used as static for now\n   */\n  cross?: boolean;\n};\n\nexport const StaticCheckbox = (inProps: StaticCheckboxProps) => {\n  const [props, restProps] = splitProps(\n    inProps,\n    [\n      'class',\n      'classList',\n      'checked',\n      'round',\n      'cross'\n    ]\n  );\n\n  return (\n    <div\n      class={classNames(styles.Checkbox, props.class)}\n      classList={{\n        [styles.checked]: props.checked,\n        [styles.round]: props.round,\n        ...props.classList\n      }}\n      {...restProps}\n    >\n      <div class={styles.Border}></div>\n      <div class={styles.Background}></div>\n      <svg\n        class={styles.Check}\n        viewBox=\"0 0 24 24\"\n      >\n        <use\n          href={props.cross ? '#checkbox-cross' : '#check'}\n          x={props.cross ? undefined : '-1'}\n        />\n      </svg>\n    </div>\n  );\n};\n","import {copyTextToClipboard} from '@helpers/clipboard';\n// import SelectionSaver from \"@helpers/selectionSaver\";\n// import selectElementContents from \"@helpers/dom/selectElementContents\";\n\nexport default function copyFromElement(element: HTMLElement) {\n  copyTextToClipboard(element.textContent);\n  // const saver = new SelectionSaver();\n  // saver.save();\n  // selectElementContents(element);\n  // document.execCommand('copy');\n  // saver.restore();\n}\n","export default \"__VITE_ASSET__FKNdLzKnlftW3t_gzo81yw__\"","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport temmlUrl from 'temml/dist/temml.min.js?url';\n\nexport type TemmlRender = (source: string, element: HTMLElement, options?: {displayMode?: boolean, throwOnError?: boolean}) => void;\nexport type Temml = {render: TemmlRender};\n\nlet temmlPromise: Promise<Temml> | undefined;\n\n// Temml MUST reach the browser as a file no bundler re-printed. Its lexer builds the master token\n// regex by concatenating string literals holding RAW lone surrogates (the surrogate-pair\n// alternative, `\"|[\\uD800-\\uDBFF][\\uDC00-\\uDFFF]\"`). Re-printing that folded string writes each\n// lone surrogate as U+FFFD, so the class degrades to `[<FFFD>d800-<FFFD>dbff]`, whose `0-<FFFD>`\n// range swallows `\\` and makes every control word lex as a one-letter command: `\\frac` dies with\n// \"Unsupported function name: \\f\" and nothing but bare symbols parses. Verified on temml 0.13.3\n// that BOTH the esbuild dev dep-optimizer and the rolldown production build mangle those 4 code\n// points — https://github.com/ronkok/Temml/pull/128 did NOT fix it, and `optimizeDeps.exclude`\n// would only cover dev. So: `?url` (Vite emits the file byte-identical) + a runtime load the\n// bundler cannot see.\n//\n// We take `temml.min.js` rather than `temml.mjs` because upstream minifies it with terser at\n// publish time and terser escapes the lone surrogates correctly — it is 49KB gzip / 41KB brotli\n// against the .mjs bundle's 115KB / 93KB, i.e. lighter than the (broken) bundled copy ever was.\n// The price is that it is an IIFE global build, not ESM, so it loads via a <script> tag and\n// publishes `window.temml`. That global is a `var` in a classic script and therefore\n// non-configurable — it stays for the life of the page by design, not by omission.\nexport default function loadTemml(): Promise<Temml> {\n  if(!temmlPromise) {\n    temmlPromise = Promise.all([\n      loadTemmlScript(),\n      import('temml/dist/Temml-Local.css')\n    ]).then(([temml]) => temml);\n  }\n\n  return temmlPromise;\n}\n\nfunction loadTemmlScript(): Promise<Temml> {\n  return new Promise((resolve, reject) => {\n    const script = document.createElement('script');\n    script.src = temmlUrl;\n    script.onload = () => {\n      const temml = (window as any).temml as Temml;\n      if(temml) resolve(temml);\n      else reject(new Error('temml: loaded but no global'));\n    };\n    script.onerror = () => reject(new Error('temml: failed to load'));\n    document.head.append(script);\n  });\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {JSX, onMount} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {MATH_MARKER_RE, decodeInlineMath} from '@helpers/math/mathMarker';\nimport styles from '@components/instantView.module.scss';\nimport loadTemml from '@helpers/math/loadTemml';\n\n// Temml writes `\\label{foo}` straight into `id=\"foo\"`, and formula sources arrive in message\n// content — so a message would otherwise pick ids for the document. That is two problems: an id is\n// exposed on `window` under its own name (a DOM-clobbering primitive), and it can collide with an\n// id the app or another formula already owns. Rewrite every id, and the `\\ref` links pointing at\n// them, into a per-render namespace: the dashes keep it off the global scope and the counter keeps\n// each rendered formula to itself.\nlet labelIdSeed = 0;\nfunction namespaceLabelIds(element: HTMLElement) {\n  const labelled = element.querySelectorAll('[id]');\n  const referencing = element.querySelectorAll('[href^=\"#\"]');\n  if(!labelled.length && !referencing.length) {\n    return;\n  }\n\n  const prefix = 'tml-label-' + ++labelIdSeed + '-';\n  labelled.forEach((node) => node.setAttribute('id', prefix + node.getAttribute('id')));\n  referencing.forEach((node) => node.setAttribute('href', '#' + prefix + node.getAttribute('href').slice(1)));\n}\n\n// Render LaTeX `source` into `element` as MathML. Shows the raw source until Temml loads and as a\n// fallback if the library fails to load or the source doesn't parse (matches WebA's behaviour).\nexport function renderLatexInto(element: HTMLElement, source: string, isBlock: boolean) {\n  element.textContent = source;\n  loadTemml().then((temml) => {\n    try {\n      element.textContent = '';\n      temml.render(source, element, {displayMode: isBlock, throwOnError: true});\n      namespaceLabelIds(element);\n    } catch{\n      element.textContent = source;\n    }\n  }, () => {\n    element.textContent = source;\n  });\n}\n\n// Block math (`$$…$$`) — a Solid component used directly in the IV block renderer.\nexport function Latex(props: {source: string, isBlock?: boolean}): JSX.Element {\n  let ref: HTMLSpanElement;\n  onMount(() => renderLatexInto(ref, props.source, props.isBlock));\n  return <span ref={ref!} class={classNames(styles.Latex, props.isBlock && styles.LatexBlock)} />;\n}\n\n// Inline math — wrapRichText emits the base64 marker as plain text. Replace each marker in the\n// fragment with a span and render it with Temml (display mode off). Run on the fragment BEFORE it\n// is inserted into the document, so the `\\x02…` sentinels never become visible.\nexport function hydrateInlineMath(fragment: DocumentFragment | HTMLElement) {\n  const walker = document.createTreeWalker(fragment, NodeFilter.SHOW_TEXT);\n  const textNodes: Text[] = [];\n  let node: Node;\n  while((node = walker.nextNode())) {\n    if(node.nodeValue.includes('\\x02')) {\n      textNodes.push(node as Text);\n    }\n  }\n\n  for(const textNode of textNodes) {\n    const text = textNode.nodeValue;\n    MATH_MARKER_RE.lastIndex = 0;\n    if(!MATH_MARKER_RE.test(text)) {\n      continue;\n    }\n\n    MATH_MARKER_RE.lastIndex = 0;\n    const pieces = document.createDocumentFragment();\n    let last = 0;\n    let m: RegExpExecArray;\n    while((m = MATH_MARKER_RE.exec(text))) {\n      if(m.index > last) {\n        pieces.append(text.slice(last, m.index));\n      }\n      const span = document.createElement('span');\n      span.className = styles.LatexInline;\n      renderLatexInto(span, decodeInlineMath(m[1]), false);\n      pieces.append(span);\n      last = m.index + m[0].length;\n    }\n    if(last < text.length) {\n      pieces.append(text.slice(last));\n    }\n    textNode.replaceWith(pieces);\n  }\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\nexport type CodeBlockClickTarget = {\n  code: HTMLElement,\n  container: HTMLElement | null, // null for a bare `.monospace-text` (no code-header wrapper)\n  isWrapToggle: boolean\n};\n\n// Resolve a click/mousedown target to the code block it acts on (the `.code-code` of a fenced block,\n// or a bare `.monospace-text`), or null if it isn't a code-block control. Shared by the chat bubbles\n// handler and the Instant View onClick delegator so the detection lives in one place.\nexport function getCodeBlockClickTarget(target: EventTarget): CodeBlockClickTarget | null {\n  const container = findUpClassName(target, 'code-header') && findUpClassName(target, 'code');\n  const code = container?.querySelector<HTMLElement>('.code-code') || findUpClassName(target, 'monospace-text');\n  if(!code) {\n    return null;\n  }\n  return {code, container: container || null, isWrapToggle: !!findUpClassName(target, 'code-header-toggle-wrap')};\n}\n\n// Toggle the code block between horizontal-scroll and wrap.\nexport function toggleCodeBlockWrap({code, container}: CodeBlockClickTarget) {\n  if(!container) {\n    return;\n  }\n  const present = container.classList.toggle('is-scrollable');\n  code.classList.toggle('no-scrollbar', present);\n}\n","import {For, createEffect, createContext, useContext, Show, createSignal, Setter, onCleanup, createReaction} from 'solid-js';\nimport type {JSX} from 'solid-js';\nimport {Dynamic} from 'solid-js/web';\nimport {Document, MessageEntity, Page, PageBlock, PageCaption, PageListOrderedItem, Photo, RichText} from '@layer';\nimport wrapTelegramRichText from '@lib/richTextProcessor/wrapTelegramRichText';\nimport styles from '@components/instantView.module.scss';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport classNames from '@helpers/string/classNames';\nimport {IconTsx} from '@components/iconTsx';\nimport GenericTable, {GenericTableRow} from '@components/genericTable';\nimport {SolidJSHotReloadGuardContextValue, useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport {formatDate, formatFullSentTime} from '@helpers/date';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport Scrollable, {ScrollableContext} from '@components/scrollable2';\nimport fastSmoothScroll, {fastSmoothScrollToStart} from '@helpers/fastSmoothScroll';\nimport Animated from '@helpers/solid/animations';\nimport {unwrap} from 'solid-js/store';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport {CustomEmojiRendererElement} from '@lib/customEmoji/renderer';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport MySuspense from '@helpers/solid/mySuspense';\nimport TelegramWebView from '@components/telegramWebView';\nimport getWebFileLocation from '@helpers/getWebFileLocation';\nimport makeGoogleMapsUrl from '@helpers/makeGoogleMapsUrl';\nimport {GeoPoint} from '@layer';\nimport GeoPin from '@components/geoPin';\nimport ScrollSaver from '@helpers/scrollSaver';\nimport windowSize from '@helpers/windowSize';\nimport {Message} from '@layer';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport prepareAlbum from '@components/prepareAlbum';\nimport type AppMediaViewer from '@components/mediaViewer';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {useAppSettings} from '@stores/appSettings';\nimport {StaticCheckbox} from '@components/staticCheckbox';\nimport copyFromElement from '@helpers/dom/copyFromElement';\nimport {toastNew} from '@components/toast';\nimport {Latex, hydrateInlineMath} from '@components/instantViewMath';\nimport {getCodeBlockClickTarget, toggleCodeBlockWrap} from '@helpers/dom/codeBlockClick';\n\ntype InstantViewContextValue = {\n  webPageId: Long,\n  page: Page.page,\n  randomId: string,\n  openNewPage: (url: string) => void,\n  collapse: () => void,\n  scrollToAnchor: (anchor: string, instantly: boolean) => void,\n  customEmojiRenderer: CustomEmojiRendererElement,\n  details: WeakMap<HTMLElement, Setter<boolean>>,\n  ready: boolean,\n  savingScroll: boolean,\n  media: Array<{ref: HTMLElement, media: Photo.photo | Document.document, caption: PageCaption}>\n};\n\nconst InstantViewContext = createContext<InstantViewContextValue>();\n\n// Match in-page fragment URLs: `#x` (raw markdown) or `<protocol>://#x`\n// (after wrapUrl prepends the missing scheme to a bare fragment).\nconst FRAGMENT_HREF_RE = /^(?:[a-z]+:\\/\\/)?(#[^#?]+)$/i;\n\n// An embed block carries third-party provider markup (GitHub Gist, Twitter, YouTube, ...).\n// Without a sandbox the frame keeps every capability it is given by default, and an\n// `html` embed additionally inherits this origin, so its scripts would run as\n// web.telegram.org with access to the parent document and its storage.\nconst EMBED_SANDBOX_ATTRIBUTES = [\n  'allow-scripts',\n  'allow-popups',\n  'allow-popups-to-escape-sandbox', // links inside the embed must open as normal pages\n  'allow-forms',\n  'allow-modals'\n].join(' ');\n\n// A cross-origin `url` embed already loads under the provider's own origin, so keeping it\n// costs nothing here and preserves the provider's cookies and storage.\nconst EMBED_URL_SANDBOX_ATTRIBUTES = EMBED_SANDBOX_ATTRIBUTES + ' allow-same-origin';\n\n// The height in a `resize_frame` event is authored by the embedded document — a third-party page,\n// and after a navigation away not even the one the block asked for — so it only ever grows the\n// block to something a tall embed could plausibly need, never to an arbitrary size.\nconst MAX_EMBED_VIEWPORTS = 4;\n\n// An `html` embed is a wrapper document whose canonical link points at Telegram's own embed host\n// (embed.telegra.ph), which serves the very same markup. Pointing the frame at that URL is what\n// isolates it: the frame lands on a real, non-Telegram origin instead of inheriting this one.\n// Rendering the markup inline would work too, but only in an opaque origin, and provider widgets\n// need storage there — Twitter's createTweet() resolves to null and draws nothing.\nfunction extractEmbedUrl(html: string) {\n  try {\n    const href = new DOMParser().parseFromString(html, 'text/html') // does not run scripts\n    .querySelector('link[rel~=\"canonical\" i]')\n    ?.getAttribute('href')\n    ?.trim();\n    const url = href && new URL(href);\n    return url && (url.protocol === 'https:' || url.protocol === 'http:') ? url.href : undefined;\n  } catch(err) {\n    return undefined;\n  }\n}\n\nfunction getEmbedSandbox(html: string, url: string) {\n  if(html) { // srcdoc — allow-same-origin would hand it this origin, which is the whole problem\n    return EMBED_SANDBOX_ATTRIBUTES;\n  }\n\n  let isCrossOrigin: boolean;\n  try {\n    isCrossOrigin = new URL(url, location.href).origin !== location.origin;\n  } catch(err) {\n    isCrossOrigin = false;\n  }\n\n  // a same-origin frame with allow-same-origin can reach into the parent and lift its own sandbox\n  return isCrossOrigin ? EMBED_URL_SANDBOX_ATTRIBUTES : EMBED_SANDBOX_ATTRIBUTES;\n}\n\nfunction onClick(context: InstantViewContextValue, e: MouseEvent) {\n  // Code block header buttons (copy / wrap toggle) — same affordance as chat bubbles, since IV\n  // reuses wrapRichText's `messageEntityPre` markup for highlighted code.\n  const codeTarget = getCodeBlockClickTarget(e.target);\n  if(codeTarget) {\n    cancelEvent(e);\n    if(codeTarget.isWrapToggle) {\n      toggleCodeBlockWrap(codeTarget);\n    } else {\n      copyFromElement(codeTarget.code);\n      toastNew({langPackKey: 'CodeCopied'});\n    }\n    return;\n  }\n\n  const anchor = findUpClassName(e.target, 'anchor-url') as HTMLAnchorElement;\n  if(anchor) {\n    const href = anchor.getAttribute('href') || '';\n    const m = href.match(FRAGMENT_HREF_RE);\n    if(m) {\n      cancelEvent(e);\n      context.scrollToAnchor(m[1], false);\n      return;\n    }\n  }\n}\n\n// Expand every collapsed <details> the anchor target sits inside, so it's actually visible before we\n// scroll to it. Shared by the full-page IV and inline RichMessage anchor navigation.\nfunction expandDetailsAncestors(context: InstantViewContextValue, element: HTMLElement) {\n  let detailsElement: HTMLElement = element;\n  do {\n    detailsElement = findUpClassName(detailsElement, styles.Details);\n    if(!detailsElement) {\n      break;\n    }\n\n    context.details.get(detailsElement)?.(true);\n    detailsElement = detailsElement.parentElement;\n  } while(true);\n}\n\nexport function InstantViewBlocks(props: {\n  webPageId: Long,\n  page: Page.page,\n  openNewPage: (url: string) => void,\n  collapse: () => void,\n  // host-provided scroll for in-page anchor jumps (the embedding chat passes its viewport-aware\n  // bubbles.scrollToBubble); omitted → anchor links are inert\n  scrollToElement?: (element: HTMLElement) => void,\n  class?: string,\n  contentClass?: string,\n  paddings?: number,\n  style?: JSX.CSSProperties\n}) {\n  const customEmojiRenderer = CustomEmojiRendererElement.create({\n    textColor: 'primary-text-color',\n    middleware: createMiddleware().get(),\n    renderNonSticker: true\n  });\n\n  const value: InstantViewContextValue = {\n    get webPageId() {\n      return props.webPageId;\n    },\n    ready: true,\n    page: props.page,\n    randomId: '' + (Math.random() * 1000 | 0),\n    openNewPage: props.openNewPage,\n    collapse: props.collapse,\n    scrollToAnchor: (anchor) => {\n      if(!anchor) {\n        return;\n      }\n\n      const element = document.getElementById(value.randomId + anchor.slice(1)) as HTMLElement;\n      if(!element) {\n        return;\n      }\n\n      expandDetailsAncestors(value, element);\n      props.scrollToElement?.(element);\n    },\n    customEmojiRenderer,\n    details: new WeakMap(),\n    savingScroll: false,\n    media: []\n  };\n\n  return (\n    <InstantViewContent\n      value={value}\n      class={props.class}\n      contentClass={props.contentClass}\n      paddings={props.paddings}\n      style={props.style}\n    />\n  );\n}\n\n// Shared render of the context provider + `.InstantView` wrapper + block list. Both the full-page\n// `InstantView` (wrapped in Scrollable/MySuspense with a footer) and the inline `InstantViewBlocks`\n// (used to embed rich messages inside chat bubbles) delegate here so the block markup lives in one\n// place. The distinct context values (ready/scrollToAnchor) and outer chrome stay in each caller.\nfunction InstantViewContent(props: {\n  value: InstantViewContextValue,\n  class?: string,\n  contentClass?: string,\n  paddings?: number,\n  style?: JSX.CSSProperties,\n  children?: JSX.Element\n}) {\n  return (\n    <InstantViewContext.Provider value={props.value}>\n      <div\n        dir={props.value.page.pFlags.rtl ? 'auto' : undefined}\n        class={classNames(styles.InstantView, props.class, 'text-overflow-wrap')}\n        onClick={onClick.bind(null, props.value)}\n        style={props.style}\n      >\n        {props.value.customEmojiRenderer}\n        <div class={classNames(styles.InstantViewContent, props.contentClass)}>\n          <For each={props.value.page.blocks}>{(block) => (\n            <Block block={block} paddings={props.paddings ?? 2} />\n          )}</For>\n        </div>\n        {props.children}\n      </div>\n    </InstantViewContext.Provider>\n  );\n}\n\nexport function InstantView(props: {\n  webPageId: Long,\n  page: Page.page,\n  openNewPage: (url: string) => void,\n  collapse: () => void,\n  needFadeIn?: boolean,\n  anchor?: string, // * expect it to be '#name'\n  onReady?: () => void\n}) {\n  const [ready, setReady] = createSignal(false);\n  const value: InstantViewContextValue = {\n    get webPageId() {\n      return props.webPageId;\n    },\n    get ready() {\n      return ready();\n    },\n    page: props.page,\n    randomId: '' + (Math.random() * 1000 | 0),\n    openNewPage: props.openNewPage,\n    collapse: props.collapse,\n    scrollToAnchor: (anchor, instantly) => {\n      const forceDuration = instantly ? 0 : undefined;\n      if(!anchor) {\n        fastSmoothScrollToStart(scrollableRef, 'y', forceDuration);\n        return;\n      }\n\n      const element = document.getElementById(value.randomId + anchor.slice(1)) as HTMLElement;\n      if(!element) {\n        return;\n      }\n\n      expandDetailsAncestors(value, element);\n      fastSmoothScroll({container: scrollableRef, element, position: 'start', forceDuration});\n    },\n    customEmojiRenderer: CustomEmojiRendererElement.create({\n      textColor: 'primary-text-color',\n      middleware: createMiddleware().get(),\n      renderNonSticker: true\n    }),\n    details: new WeakMap(),\n    savingScroll: false,\n    media: []\n  };\n\n  // console.log(props.page);\n\n  let firstAnchor = true;\n  createEffect(() => {\n    if(!ready()) {\n      return;\n    }\n\n    const anchor = props.anchor;\n    const _firstAnchor = firstAnchor;\n    firstAnchor = false;\n    if(_firstAnchor && !anchor) {\n      return;\n    }\n\n    queueMicrotask(() => {\n      value.scrollToAnchor(anchor, _firstAnchor);\n    });\n  });\n\n  const {i18n, appImManager, rootScope} = useHotReloadGuard();\n  const [appSettings] = useAppSettings();\n  let scrollableRef: HTMLDivElement;\n  return (\n    <Animated type=\"cross-fade\" appear={props.needFadeIn} mode=\"add-remove\">\n      <MySuspense\n        onReady={() => {\n          setReady(true);\n          props.onReady?.();\n        }}\n      >\n        <Scrollable ref={scrollableRef}>\n          <InstantViewContent\n            value={value}\n            paddings={2}\n            style={{'--iv-scale': (1.125 * appSettings.instantView.scale).toFixed(3)}}\n          >\n            <div\n              dir=\"auto\"\n              class={classNames(styles.InstantViewFooter, 'secondary')}\n            >\n              <Show when={props.page.views}>\n                {i18n('Views', [props.page.views])}\n                {` • `}\n              </Show>\n              <a\n                class={styles.WrongLayout}\n                href=\"#\"\n                onClick={async(e) => {\n                  cancelEvent(e);\n                  value.collapse();\n                  const user = await rootScope.managers.appUsersManager.resolveUserByUsername('@previews');\n                  const startParam = `webpage${value.webPageId}`;\n                  appImManager.setInnerPeer({\n                    peerId: user.id.toPeerId(false),\n                    startParam\n                  });\n                }}\n              >\n                {i18n('InstantView.WrongLayout')}\n              </a>\n            </div>\n          </InstantViewContent>\n        </Scrollable>\n      </MySuspense>\n    </Animated>\n  );\n}\n\nfunction _onMediaResult(\n  ref: HTMLElement,\n  width: number,\n  height: number,\n  paddings: number\n) {\n  ref.style.setProperty(\n    '--aspect-ratio',\n    '' + (width / height)\n  );\n\n  ref.style.setProperty(\n    '--paddings',\n    // '' + (paddings > 1 ? paddings + 1 : 0)\n    '' + (paddings > 2 ? paddings : 0)\n  );\n}\n\nfunction onMediaResult(\n  ref: HTMLDivElement,\n  paddings: number,\n  onSize?: (size: {width: number, height: number}) => void\n) {\n  const {width, height} = ref.style;\n  const widthNum = parseInt(width);\n  const heightNum = parseInt(height);\n  _onMediaResult(ref, widthNum, heightNum, paddings);\n\n  const r = {width: widthNum, height: heightNum};\n  onSize?.(r);\n  return r;\n}\n\nfunction Caption(props: {caption: PageCaption}) {\n  const {caption} = props;\n  const isTextEmpty = isRichTextEmpty(caption.text);\n  const isCreditEmpty = isRichTextEmpty(caption.credit);\n  return (\n    <Show when={!isTextEmpty || !isCreditEmpty}>\n      <div class={classNames(styles.Padding, styles.Caption, 'secondary')}>\n        <Show when={!isTextEmpty}>\n          <div class={classNames(styles.CaptionText, 'text-bold')}>\n            <RichTextRenderer text={caption.text} />\n          </div>\n        </Show>\n        <Show when={!isCreditEmpty}>\n          <div class={styles.CaptionCredit}>\n            <RichTextRenderer text={caption.credit} />\n          </div>\n        </Show>\n      </div>\n    </Show>\n  );\n}\n\nfunction prepareMediaForViewer(\n  ref: HTMLDivElement,\n  media: Photo.photo | Document.document,\n  caption: PageCaption,\n  webPageId?: Long,\n  url?: string\n) {\n  const context = useContext(InstantViewContext);\n  const hotReloadGuard = useHotReloadGuard();\n  const item = {\n    ref,\n    media,\n    caption\n  };\n  context.media.push(item);\n\n  onCleanup(() => {\n    indexOfAndSplice(context.media, item);\n  });\n\n  return onMediaClick.bind(null, {\n    context,\n    ref,\n    hotReloadGuard,\n    webPageId,\n    url\n  });\n}\n\nasync function onMediaClick({\n  context,\n  ref,\n  hotReloadGuard,\n  webPageId,\n  url\n}: {\n  context: InstantViewContextValue,\n  ref: HTMLElement,\n  hotReloadGuard: SolidJSHotReloadGuardContextValue,\n  webPageId?: Long,\n  url?: string\n}) {\n  const {rootScope, AppMediaViewer, I18n} = hotReloadGuard;\n  const promises = context.media.map(async({ref, media, caption}, index) => {\n    const message = await rootScope.managers.appMessagesManager.generateStandaloneOutgoingMessage(NULL_PEER_ID);\n    message.media = media._ === 'photo' ?\n      {_: 'messageMediaPhoto', pFlags: {}, photo: media} :\n      {_: 'messageMediaDocument', pFlags: {video: true}, document: media};\n    message.id = message.mid = 0;\n    message.date = media.date;\n    message.fromId = NULL_PEER_ID;\n\n    if(!isRichTextEmpty(caption.text)) {\n      const textWithEntities = wrapTelegramRichText(caption.text);\n      message.totalEntities = textWithEntities.entities;\n      message.message = textWithEntities.text;\n    }\n\n    if(url) {\n      const string = I18n.format(\n        IS_TOUCH_SUPPORTED ? 'InstantView.Media.Url.Touch' : 'InstantView.Media.Url',\n        true\n      ) + '\\n';\n\n      const addingString = string + url + '\\n\\n';\n\n      message.message = addingString + message.message;\n      message.totalEntities ||= [];\n      message.totalEntities.forEach((entity) => {\n        entity.offset += addingString.length;\n      });\n      message.totalEntities.unshift({\n        _: 'messageEntityTextUrl',\n        offset: string.length,\n        length: url.length,\n        url: webPageId ?\n          'tg://iv?url=' + encodeURIComponent(url) :\n          url,\n        safe: !!webPageId\n      });\n    }\n\n    const target: AppMediaViewer['target'] = {\n      message,\n      element: ref,\n      mid: 0,\n      peerId: NULL_PEER_ID,\n      index\n    };\n    return target;\n  });\n  const targets = await Promise.all(promises);\n  const target = targets.find(({element}) => element === ref);\n  targets.forEach((target) => target.element = target.element.lastElementChild as any);\n\n  new AppMediaViewer(true)\n  .setSearchContext({peerId: NULL_PEER_ID, inputFilter: {_: 'inputMessagesFilterEmpty'}, useSearch: false})\n  .openMedia({\n    message: target.message,\n    target: target.element,\n    fromRight: 0,\n    reverse: false,\n    prevTargets: targets.slice(0, target.index),\n    nextTargets: targets.slice(target.index + 1)\n  });\n}\n\nfunction Block(props: {\n  block: PageBlock,\n  paddings: number,\n  noCaption?: boolean,\n  onSize?: (size: {width: number, height: number}) => void,\n}) {\n  const block = props.block;\n\n  const CaptionC: typeof Caption = props.noCaption ? (...args: any[]) => false : Caption;\n  // if(block._ !== 'pageBlockRelatedArticles' && Math.random() !== undefined) {\n  //   return;\n  // }\n\n  switch(block._) {\n    case 'pageBlockTitle':\n      return <h1 class={classNames(styles.Padding, styles.Title)}><RichTextRenderer text={block.text} /></h1>;\n    case 'pageBlockHeading1':\n      return <h1 class={classNames(styles.Padding, styles.Title)}><RichTextRenderer text={block.text} /></h1>;\n    case 'pageBlockSubtitle':\n      return <h2 class={classNames(styles.Padding, styles.Subtitle, 'secondary')}><RichTextRenderer text={block.text} /></h2>;\n    case 'pageBlockHeading2':\n      return <h2 class={classNames(styles.Padding, styles.Subtitle)}><RichTextRenderer text={block.text} /></h2>;\n    case 'pageBlockHeader':\n    case 'pageBlockSubheader': {\n      // Markdown levels 1-6 are stashed as `headingLevel` on the block by parseMarkdownToPage\n      // (see comment there). Without it (e.g. native IV articles) fall back to the original\n      // h3 / h4 tag. With it, render the matching semantic tag and add `HeadingH{n}` so the\n      // CSS module can size each level distinctly.\n      const isHeader = block._ === 'pageBlockHeader';\n      const level = (block as typeof block & {headingLevel?: number}).headingLevel;\n      const tag = level ? `h${Math.min(level + 1, 6)}` : (isHeader ? 'h3' : 'h4');\n      return (\n        <Dynamic\n          component={tag}\n          class={classNames(\n            styles.Padding,\n            isHeader ? styles.Header : styles.Subheader,\n            level && styles[`HeadingH${level}`]\n          )}\n        >\n          <RichTextRenderer text={block.text} />\n        </Dynamic>\n      );\n    }\n    case 'pageBlockHeading3':\n      return <h3 class={classNames(styles.Padding, styles.Header)}><RichTextRenderer text={block.text} /></h3>;\n    case 'pageBlockHeading4':\n      return <h4 class={classNames(styles.Padding, styles.Subheader)}><RichTextRenderer text={block.text} /></h4>;\n    case 'pageBlockHeading5':\n      return <h5 class={classNames(styles.Padding, styles.Subheader)}><RichTextRenderer text={block.text} /></h5>;\n    case 'pageBlockHeading6':\n      return <h6 class={classNames(styles.Padding, styles.Subheader)}><RichTextRenderer text={block.text} /></h6>;\n    case 'pageBlockParagraph':\n      return <p class={classNames(styles.Padding, styles.Paragraph)}><RichTextRenderer text={block.text} /></p>;\n    case 'pageBlockPreformatted': {\n      const code = richTextToString(block.text);\n      // `$$…$$` blocks are tagged language `math` by parseMarkdownToPage — render them as display\n      // formulas via Temml (like WebA), wrapped in a horizontal scroller for wide equations.\n      if(block.language === 'math') {\n        return (\n          <div class={classNames(styles.Padding, styles.MathBlockWrapper)}>\n            <Latex source={code} isBlock />\n          </div>\n        );\n      }\n      // Otherwise render as the app's real highlighted code block (Prism + language header +\n      // copy/wrap), reusing the exact markup wrapRichText builds for `messageEntityPre`. The header\n      // buttons are wired by the IV root onClick delegator (see onClick()).\n      const entities: MessageEntity[] = [{_: 'messageEntityPre', offset: 0, length: code.length, language: block.language || ''}];\n      const fragment = wrapRichText(code, {entities});\n      return <div class={classNames(styles.Padding, styles.PreformattedWrapper)}>{documentFragmentToNodes(fragment)}</div>;\n    }\n    case 'pageBlockMath':\n      // Server-sent `pageBlockMath` (rich messages) — render as a display formula through the same\n      // Temml path master uses for markdown `$$…$$` blocks, instead of dumping the raw LaTeX source.\n      return (\n        <div class={classNames(styles.Padding, styles.MathBlockWrapper)}>\n          <Latex source={block.source} isBlock />\n        </div>\n      );\n    case 'pageBlockFooter':\n      return <footer class={classNames(styles.Padding, styles.Footer, 'secondary')}><RichTextRenderer text={block.text} /></footer>;\n    case 'pageBlockDivider':\n      return <div class={styles.Divider} />;\n    case 'pageBlockOrderedList':\n    case 'pageBlockList': {\n      // * own numbers cannot be perfectly vertical aligned if children is not plain text\n      const isOrdered = block._ === 'pageBlockOrderedList';\n      const shouldHaveOwnNumbers = isOrdered && block.items.some((item) => item.num && !item.num.match(/^\\d+$/));\n      const orderedProps = isOrdered ? {\n        reversed: block.pFlags.reversed,\n        start: block.start,\n        type: block.type\n      } : {};\n      const {wrapEmojiText} = useHotReloadGuard();\n      return (\n        <Dynamic\n          component={isOrdered ? 'ol' : 'ul'}\n          {...orderedProps}\n          class={classNames(\n            styles.List,\n            styles.BlockContainer,\n            styles.BlockGutter,\n            shouldHaveOwnNumbers && styles.ListOrdered,\n            'browser-default'\n          )}\n        >\n          <For each={block.items}>{(item, idx) => (\n            <li class={styles.ListItem}>\n              {shouldHaveOwnNumbers && (\n                <span class={styles.ListItemNumber}>\n                  {(item as PageListOrderedItem.pageListOrderedItemText).num ?\n                    wrapEmojiText((item as PageListOrderedItem.pageListOrderedItemText).num) :\n                    idx() + 1}\n                  {`. `}\n                </span>\n              )}\n              {item._ === 'pageListItemText' || item._ === 'pageListOrderedItemText' ? (\n                <>\n                  <Show when={item.pFlags?.checkbox}>\n                    <StaticCheckbox\n                      class={styles.TaskCheckbox}\n                      checked={item.pFlags?.checked}\n                    />\n                  </Show>\n                  <RichTextRenderer text={item.text} />\n                </>\n              ) : (\n                <For each={item.blocks}>{(subBlock) => (\n                  <Block block={subBlock} paddings={props.paddings + 1} />\n                )}</For>\n              )}\n            </li>\n          )}</For>\n        </Dynamic>\n      );\n    }\n    case 'pageBlockBlockquote':\n      return (\n        <div class={classNames(styles.Padding, styles.BlockquoteWrapper)}>\n          {/* reuse the app-standard quote styling (left accent bar + tinted bg + quote glyph) */}\n          <blockquote class={classNames('quote-like', 'quote-like-border', 'quote-like-icon', styles.Blockquote)}>\n            <RichTextRenderer text={block.text} />\n            <Show when={!isRichTextEmpty(block.caption)}>\n              <div class={classNames(styles.BlockquoteCaption, 'secondary')}>\n                <RichTextRenderer text={block.caption} />\n              </div>\n            </Show>\n          </blockquote>\n        </div>\n      );\n    case 'pageBlockBlockquoteBlocks':\n      return (\n        <div class={classNames(styles.Padding, styles.BlockquoteWrapper)}>\n          {/* same app-standard quote chrome as the inline blockquote (accent bar + tinted bg + glyph),\n              but hosting parsed child blocks instead of a single rich-text run */}\n          <blockquote class={classNames('quote-like', 'quote-like-border', 'quote-like-icon', styles.Blockquote, styles.BlockquoteBlocks, styles.BlockContainer)}>\n            <For each={block.blocks}>{(subBlock) => (\n              <Block block={subBlock} paddings={props.paddings + 1} />\n            )}</For>\n            <Show when={!isRichTextEmpty(block.caption)}>\n              <div class={classNames(styles.BlockquoteCaption, 'secondary')}>\n                <RichTextRenderer text={block.caption} />\n              </div>\n            </Show>\n          </blockquote>\n        </div>\n      );\n    case 'pageBlockCover':\n      return (\n        <div class={styles.Cover}>\n          <Block block={block.cover} paddings={props.paddings} />\n        </div>\n      );\n    case 'pageBlockPhoto': {\n      const context = useContext(InstantViewContext);\n      const {PhotoTsx} = useHotReloadGuard();\n      const photo = unwrap(context.page.photos.find((photo) => photo.id === block.photo_id)) as Photo.photo;\n      let ref: HTMLDivElement, onClick: () => void;\n      return (\n        <>\n          <PhotoTsx\n            ref={(_ref) => {\n              ref = _ref;\n              onClick = prepareMediaForViewer(ref, photo, block.caption, block.webpage_id, block.url);\n            }}\n            class={styles.Media}\n            photo={photo}\n            withoutPreloader\n            onResult={() => onMediaResult(ref, props.paddings, props.onSize)}\n            onClick={() => onClick()}\n          />\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockVideo': {\n      const context = useContext(InstantViewContext);\n      const {VideoTsx} = useHotReloadGuard();\n      const doc = unwrap(context.page.documents.find((doc) => doc.id === block.video_id)) as Document.document;\n      let ref: HTMLDivElement, onClick: () => void;\n      return (\n        <>\n          <VideoTsx\n            ref={(_ref) => {\n              ref = _ref;\n              onClick = prepareMediaForViewer(ref, doc, block.caption);\n            }}\n            doc={doc}\n            class={styles.Media}\n            withoutPreloader\n            withPreview\n            noInfo\n            onResult={() => onMediaResult(ref, props.paddings, props.onSize)}\n            onClick={() => onClick()}\n          />\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockAudio': {\n      const context = useContext(InstantViewContext);\n      const {DocumentTsx} = useHotReloadGuard();\n      const doc = unwrap(context.page.documents.find((doc) => doc.id === block.audio_id)) as Document.document;\n\n      const message: Message.message = {\n        _: 'message',\n        id: (Number(block.audio_id) || 0) as number, // Fake ID\n        peer_id: {_: 'peerUser', user_id: 0},\n        date: 0,\n        message: '',\n        media: {\n          _: 'messageMediaDocument',\n          document: doc,\n          pFlags: {}\n        },\n        pFlags: {},\n        mid: (Number(block.audio_id) || 0) as number, // Fake MID\n        peerId: NULL_PEER_ID\n      };\n\n      return (\n        <>\n          <DocumentTsx\n            class={classNames(styles.Padding, styles.Audio)}\n            message={message}\n            withTime={false}\n            clickable\n            autoDownloadSize={10 * 1024 * 1024} // 10MB auto-download limit\n          />\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockChannel': {\n      const {PeerTitleTsx, appImManager} = useHotReloadGuard();\n      const {collapse} = useContext(InstantViewContext);\n      const peerId = block.channel.id.toPeerId(true);\n      return (\n        <div\n          class={classNames(\n            styles.SectionName,\n            styles.Channel,\n            'text-bold'\n          )}\n          onClick={() => {\n            collapse();\n            appImManager.setInnerPeer({peerId});\n          }}\n        >\n          <PeerTitleTsx peerId={peerId} />\n        </div>\n      );\n    }\n    case 'pageBlockAuthorDate':\n      return (\n        <div\n          dir=\"auto\"\n          class={classNames(\n            styles.Padding,\n            styles.AuthorDate,\n            'secondary',\n            useContext(InstantViewContext).page.pFlags.rtl && 'text-right'\n          )}\n        >\n          <Show when={!isRichTextEmpty(block.author)}>\n            <RichTextRenderer text={block.author} />\n            {` • `}\n          </Show>\n          {block.published_date ?\n            formatFullSentTime(block.published_date, true) :\n            formatDate(new Date())}\n        </div>\n      );\n    case 'pageBlockAnchor':\n      return (\n        <div\n          class={styles.Anchor}\n          id={useContext(InstantViewContext).randomId + block.name}\n        />\n      );\n    case 'pageBlockTable': {\n      const rows: GenericTableRow[] = block.rows.map((row) => ({\n        cells: row.cells.map((cell) => ({\n          content: cell.text ? <RichTextRenderer text={cell.text} /> : undefined,\n          header: cell.pFlags.header,\n          colspan: cell.colspan,\n          rowspan: cell.rowspan,\n          alignCenter: cell.pFlags.align_center,\n          alignRight: cell.pFlags.align_right,\n          valignMiddle: cell.pFlags.valign_middle,\n          valignBottom: cell.pFlags.valign_bottom\n        }))\n      }));\n\n      return (\n        <div class={styles.TableWrapper}>\n          <Show when={!isRichTextEmpty(block.title)}>\n            <div class={styles.TableName}>\n              <RichTextRenderer text={block.title} />\n            </div>\n          </Show>\n          <div class={styles.Table}>\n            <GenericTable\n              rows={rows}\n              bordered={block.pFlags.bordered}\n              striped={block.pFlags.striped}\n            />\n          </div>\n        </div>\n      );\n    }\n    case 'pageBlockRelatedArticles': {\n      const {PhotoTsx} = useHotReloadGuard();\n      return (\n        <>\n          <div class={styles.SectionName}>\n            {/* {useHotReloadGuard().i18n('InstantView.RelatedArticles')} */}\n            <RichTextRenderer text={block.title} />\n          </div>\n          <For each={block.articles}>{(article, idx) => {\n            const wrapped = wrapUrl('tg://iv?url=' + encodeURIComponent(article.url));\n            const photo = article.photo_id ?\n              unwrap(useContext(InstantViewContext).page.photos.find((photo) => photo.id === article.photo_id)) :\n              undefined;\n            return (\n              <>\n                {idx() && <div class={styles.Border} />}\n                <a\n                  dir=\"auto\"\n                  href={wrapped.url}\n                  class={classNames(\n                    styles.RelatedArticle,\n                    photo && styles.WithPhoto,\n                    idx() && styles.BorderTop,\n                    'hover-effect'\n                  )}\n                  // @ts-ignore\n                  attr:onclick={wrapped.onclick + '(this)'}\n                >\n                  <div class={classNames(styles.RelatedArticleTitle, 'text-bold')}>\n                    <RichTextRenderer text={{_: 'textPlain', text: article.title}} />\n                  </div>\n                  <div class={styles.RelatedArticleDescription}>\n                    <RichTextRenderer text={{_: 'textPlain', text: article.description}} />\n                  </div>\n                  <div class={classNames(styles.RelatedArticleAuthor, 'secondary')}>\n                    <Show when={article.author}>\n                      <RichTextRenderer text={{_: 'textPlain', text: article.author}} />\n                      {` • `}\n                    </Show>\n                    <Show when={article.published_date}>\n                      <span dir=\"auto\">{formatFullSentTime(article.published_date, true)}</span>\n                    </Show>\n                  </div>\n                  <Show when={photo}>\n                    <PhotoTsx\n                      photo={photo as Photo.photo}\n                      class={styles.RelatedArticlePhoto}\n                      boxWidth={100}\n                      boxHeight={100}\n                      withoutPreloader\n                    />\n                  </Show>\n                </a>\n              </>\n            );\n          }}</For>\n        </>\n      );\n    }\n    case 'pageBlockEmbed': {\n      const context = useContext(InstantViewContext);\n      const {PhotoTsx} = useHotReloadGuard();\n      const isFullWidth = block.pFlags?.full_width;\n      const posterPhoto = block.poster_photo_id ?\n        unwrap(context.page.photos.find((photo) => photo.id === block.poster_photo_id)) as Photo.photo :\n        undefined;\n\n      const [height, setHeight] = createSignal(0);\n      // prefer the canonical URL, and only render the markup inline when there is none\n      const embedUrl = block.url || (block.html ? extractEmbedUrl(block.html) : undefined);\n      const embedHtml = embedUrl ? undefined : block.html;\n      const webView = embedHtml || embedUrl ?\n        new TelegramWebView({\n          html: embedHtml,\n          url: embedUrl,\n          sandbox: getEmbedSandbox(embedHtml, embedUrl)\n        }) :\n        undefined;\n      if(webView) {\n        webView.iframe.classList.add(styles.EmbedIframe);\n        webView.iframe.scrolling = block.pFlags?.allow_scrolling ? 'yes' : 'no';\n        webView.iframe.allowFullscreen = true;\n\n        if(block.url) {\n          webView.iframe.style.width = '100%';\n          webView.iframe.style.height = '100%';\n          webView.iframe.style.border = '0';\n        }\n\n        createEffect(() => {\n          if(!context.ready) {\n            return;\n          }\n\n          queueMicrotask(() => {\n            if(!cleaned) {\n              webView.onMount();\n            }\n          });\n        });\n\n        let cleaned = false;\n        onCleanup(() => {\n          cleaned = true;\n          webView.destroy();\n        });\n\n        const scrollableContext = useContext(ScrollableContext);\n        webView.addEventListener('resize_frame', ({height}) => {\n          if(!height) {\n            return;\n          }\n\n          height = Math.min(height, windowSize.height * MAX_EMBED_VIEWPORTS);\n\n          const scrollSaver = context.savingScroll ? undefined : new ScrollSaver(scrollableContext, undefined, false);\n          if(scrollSaver) {\n            context.savingScroll = true;\n            scrollSaver.save();\n          }\n\n          setHeight(height);\n          if(scrollSaver) queueMicrotask(() => {\n            queueMicrotask(() => {\n              context.savingScroll = false;\n              scrollSaver.restore();\n            });\n          });\n        });\n      }\n\n      return (\n        <>\n          <div\n            ref={(ref) => {\n              _onMediaResult(\n                ref,\n                block.w || 4,\n                block.h || 3,\n                Math.max(isFullWidth ? 0 : 2, props.paddings)\n              );\n            }}\n            class={classNames(\n              styles.Media,\n              styles.Embed,\n              isFullWidth ? styles.EmbedFullWidth : styles.EmbedAutoWidth,\n              height() && styles.EmbedHasHeight\n            )}\n            style={{\n              '--height': height() && height() + 'px'\n            }}\n          >\n            <Show when={!webView} fallback={webView.iframe}>\n              <Show when={posterPhoto}>\n                <PhotoTsx\n                  photo={posterPhoto}\n                  withoutPreloader\n                />\n              </Show>\n            </Show>\n          </div>\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockEmbedPost': {\n      const context = useContext(InstantViewContext);\n      const {Row, PhotoTsx} = useHotReloadGuard();\n      const authorPhoto = block.author_photo_id ?\n        unwrap(context.page.photos.find((photo) => photo.id === block.author_photo_id)) as Photo.photo :\n        undefined;\n\n      return (\n        <div class={classNames(styles.Post, styles.BlockGutter)}>\n          <div class={styles.PostBorder} />\n          <Row class={styles.PostAuthor}>\n            <Row.Title class=\"text-bold\">\n              <RichTextRenderer text={{_: 'textPlain', text: block.author}} />\n            </Row.Title>\n            <Row.Subtitle>\n              {formatFullSentTime(block.date, true)}\n            </Row.Subtitle>\n            <Row.Media size=\"abitbigger\">\n              <PhotoTsx\n                class={styles.PostAuthorPhoto}\n                photo={authorPhoto}\n                withoutPreloader\n                boxWidth={42}\n                boxHeight={42}\n              />\n            </Row.Media>\n          </Row>\n          <div class={styles.BlockContainer}>\n            <For each={block.blocks}>{(subBlock) => (\n              <Block block={subBlock} paddings={props.paddings + 1} />\n            )}</For>\n          </div>\n        </div>\n      );\n    }\n    case 'pageBlockSlideshow': {\n      const {Slideshow} = useHotReloadGuard();\n\n      return (\n        <>\n          <Slideshow\n            class={styles.Slideshow}\n            items={block.items}\n          >\n            {(item, idx) => (\n              <Block block={item} paddings={0} noCaption />\n            )}\n          </Slideshow>\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockMap': {\n      const geo = block.geo as GeoPoint.geoPoint;\n      const url = makeGoogleMapsUrl(geo);\n      const location = getWebFileLocation(geo, block.w, block.h, block.zoom);\n      const {PhotoTsx} = useHotReloadGuard();\n\n      return (\n        <>\n          <a\n            ref={(ref) => {\n              _onMediaResult(\n                ref,\n                block.w,\n                block.h,\n                props.paddings\n              );\n            }}\n            href={url}\n            target=\"_blank\"\n            class={styles.Map}\n            style={{'--max-height': block.h + 'px'}}\n          >\n            <PhotoTsx\n              photo={location}\n              class={styles.Media}\n              withoutPreloader\n            />\n            <GeoPin />\n          </a>\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    case 'pageBlockKicker':\n      return (\n        <div class={classNames(styles.Padding, styles.Kicker, 'text-bold')}>\n          <RichTextRenderer text={block.text} />\n        </div>\n      );\n    case 'pageBlockThinking':\n      return (\n        <p class={classNames(styles.Padding, styles.Paragraph, 'secondary')}>\n          <RichTextRenderer text={block.text} />\n        </p>\n      );\n    case 'pageBlockPullquote':\n      return (\n        <div class={styles.Pullquote}>\n          <RichTextRenderer text={block.text} />\n          <Show when={!isRichTextEmpty(block.caption)}>\n            <div class={classNames(styles.BlockquoteCaption, 'secondary')}>\n              <RichTextRenderer text={block.caption} />\n            </div>\n          </Show>\n        </div>\n      );\n    case 'pageBlockDetails': {\n      const [open, setOpen] = createSignal(!!block.pFlags.open);\n      const detailsMap = useContext(InstantViewContext).details;\n      return (\n        <div\n          ref={(ref) => {detailsMap.set(ref, setOpen)}}\n          class={classNames(styles.Details)}\n        >\n          <div\n            class={classNames(styles.DetailsSummary, 'hover-effect')}\n            onClick={() => setOpen(!open())}\n          >\n            <IconTsx\n              icon=\"down\"\n              class={classNames(styles.DetailsIcon, open() && styles.DetailsIconOpen)}\n            />\n            <div class={classNames(styles.DetailsTitle, 'text-bold')}>\n              <RichTextRenderer text={block.title} />\n            </div>\n          </div>\n          <div class={styles.Border} />\n          <div\n            class={classNames(\n              styles.DetailsContent,\n              open() && styles.DetailsContentOpen\n            )}\n          >\n            <div class={styles.DetailsContentInner}>\n              <For each={block.blocks}>{(subBlock) => (\n                <Block block={subBlock} paddings={props.paddings} />\n              )}</For>\n            </div>\n          </div>\n        </div>\n      );\n    }\n    case 'pageBlockCollage': {\n      let ref: HTMLDivElement;\n      const map: Map<HTMLDivElement, {width: number, height: number}> = new Map();\n      const ret = (\n        <div\n          ref={ref}\n          class={classNames(styles.Collage, styles.Media)}\n        >\n          <For each={block.items}>{(item) => {\n            let ref: HTMLDivElement;\n            const ret = (\n              <div\n                ref={ref}\n                class={styles.CollageItem}\n              >\n                <Block\n                  block={item}\n                  paddings={props.paddings}\n                  onSize={(size) => {\n                    map.set(ref, size);\n                  }}\n                />\n              </div>\n            );\n\n            return ret;\n          }}</For>\n        </div>\n      );\n\n      createEffect(() => {\n        const sizes = Array.from(map.values()).map(({width, height}) => ({w: width, h: height}));\n        const {width, height} = prepareAlbum({\n          container: ref,\n          items: sizes,\n          maxWidth: 400,\n          minWidth: 100,\n          spacing: 2\n        });\n        _onMediaResult(ref, width, height, props.paddings);\n        // console.warn('collage map', map, ref.childElementCount);\n      });\n\n      return (\n        <>\n          {ret}\n          <CaptionC caption={block.caption} />\n        </>\n      );\n    }\n    default:\n      return (\n        <div class={classNames(styles.Padding, styles.Unsupported)}>\n          Unsupported block: {block._}\n        </div>\n      );\n  }\n}\n\nfunction isRichTextEmpty(text: RichText) {\n  return text._ === 'textEmpty' || (text._ === 'textPlain' && !text.text.trim());\n}\n\n// Flatten a RichText tree to its plain string (preformatted code is plain text; any inline\n// formatting is dropped since a code block renders verbatim).\nfunction richTextToString(text: RichText): string {\n  if(!text) return '';\n  switch(text._) {\n    case 'textEmpty': return '';\n    case 'textPlain': return text.text;\n    case 'textConcat': return text.texts.map(richTextToString).join('');\n    default: return richTextToString((text as Exclude<RichText, RichText.textConcat | RichText.textPlain | RichText.textEmpty> & {text: RichText}).text);\n  }\n}\n\nfunction RichTextRenderer(props: {text: RichText}) {\n  const {webPageId, page, randomId, customEmojiRenderer} = useContext(InstantViewContext);\n  const {text, entities} = wrapTelegramRichText(\n    props.text,\n    {webPageId, url: page.url, randomId}\n  );\n\n  // console.log({text, entities}, unwrap(props.text));\n  const fragment = wrapRichText(text, {entities, customEmojiRenderer});\n  fragment.querySelectorAll('[onclick=\"tg_iv(this)\"]').forEach((el) => {\n    el.classList.add(styles.Anchor);\n  });\n  // In-page fragment links (`#x`) get wrapped by wrapUrl into `https://#x` and flagged as\n  // masked → wrapRichText attaches `showMaskedAlert` onclick. That alert is meaningless for\n  // a same-page scroll, strip it so the IV onClick delegator can run scrollToAnchor.\n  fragment.querySelectorAll<HTMLAnchorElement>('a.anchor-url[onclick=\"showMaskedAlert(this)\"]').forEach((el) => {\n    if(FRAGMENT_HREF_RE.test(el.getAttribute('href') || '')) {\n      el.removeAttribute('onclick');\n    }\n  });\n  // Inline math markers (`$x$`) are carried as plain-text base64 by the parser — swap them for\n  // Temml-rendered spans before the fragment is inserted, so the sentinels never become visible.\n  hydrateInlineMath(fragment);\n  return documentFragmentToNodes(fragment);\n  // return (<span dir=\"auto\">{fragment}</span>);\n  // const textWithEntities = createMemo(() => wrapTelegramRichText(props.text));\n\n  // let ref: HTMLSpanElement;\n  // const ret = (<span ref={ref} />);\n\n  // createRenderEffect(() => {\n  //   if(ref) {\n  //     const {text, entities} = textWithEntities();\n  //     console.log(textWithEntities(), props.text);\n  //     const wrapped = wrapRichText(text, {entities});\n  //     ref.replaceChildren(wrapped);\n  //   }\n  // });\n\n  // return ret;\n}\n","import {Portal} from 'solid-js/web';\nimport {batch, createContext, createEffect, createRoot, For, onCleanup, onMount, useContext, JSX, createMemo, createSignal, Accessor, untrack, createResource, Resource, on, createReaction, Show, createRenderEffect, createComputed, Setter} from 'solid-js';\nimport styles from '@components/browser.module.scss';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport {FontFull, FontFullBold} from '@config/font';\nimport {createStore, reconcile, unwrap} from 'solid-js/store';\nimport untrackActions from '@helpers/solid/untrackActions';\nimport classNames from '@helpers/string/classNames';\nimport Scrollable from '@components/scrollable2';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport {IconTsx} from '@components/iconTsx';\nimport {ButtonMenuItemOptionsVerifiable, ButtonMenuSync} from '@components/buttonMenu';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport contextMenuController from '@helpers/contextMenuController';\nimport positionMenu from '@helpers/positionMenu';\nimport copy from '@helpers/object/copy';\nimport {filterButtonMenuItems} from '@components/buttonMenuToggle';\nimport Animated from '@helpers/solid/animations';\nimport WebApp, {WebAppLaunchOptions} from '@components/webApp';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport I18n, {i18n} from '@lib/langPack';\nimport {avatarNew} from '@components/avatarNew';\nimport {getMiddleware} from '@helpers/middleware';\nimport MovablePanel from '@helpers/movablePanel';\nimport {MovableState} from '@components/movableElement';\nimport {Ref, resolveElements, resolveFirst} from '@solid-primitives/refs';\nimport Section from '@components/section';\nimport InputSearch from '@components/inputSearch';\nimport rootScope from '@lib/rootScope';\nimport {SimilarPeer} from '@components/chat/similarChannels';\nimport SearchIndex from '@lib/searchIndex';\nimport {useUser} from '@stores/peers';\nimport {Game, Message, Page, User} from '@layer';\nimport TelegramWebView from '@components/telegramWebView';\nimport showForwardPopup from '@components/popups/forward';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport internalLinkProcessor from '@lib/internalLinkProcessor';\nimport {INTERNAL_LINK_TYPE} from '@lib/internalLink';\nimport {InstantView} from '@components/instantView';\nimport {WebPage} from '@layer';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport safeWindowOpen from '@helpers/dom/safeWindowOpen';\nimport wrapTelegramRichText from '@lib/richTextProcessor/wrapTelegramRichText';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport {toastNew} from '@components/toast';\nimport pause from '@helpers/schedulers/pause';\nimport assumeType from '@helpers/assumeType';\nimport {useAppSettings} from '@stores/appSettings';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport clamp from '@helpers/number/clamp';\nimport windowSize from '@helpers/windowSize';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\n\ntype BrowserPageProps<T = {}> = T & {\n  title: string, // plain text\n  icon: JSX.Element,\n  dispose: () => void,\n  titleWidth?: () => number,\n  id?: string,\n  menuButtons?: ButtonMenuItemOptionsVerifiable[],\n  scrollFromPage?: BrowserPageProps<any>,\n  content?: JSX.Element | (() => JSX.Element),\n  cacheKey?: string,\n\n  isCatalogue?: boolean,\n\n  isConfirmationNeededOnClose?: () => void | Promise<boolean>,\n  needBackButton?: boolean,\n  onBackClick?: () => void\n};\n\nfunction BrowserHeaderTipSvg(props: {left?: boolean, right?: boolean}) {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" class={classNames(styles.BrowserHeaderSelectorTail, props.left ? styles.left : styles.right)}>\n      <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M16 16V0C16 8.83656 8.83656 16 0 16H16Z\" fill=\"var(--surface-color)\"/>\n    </svg>\n  );\n}\n\nfunction BrowserHeaderButton(props: Parameters<typeof ButtonIconTsx>[0]) {\n  return (\n    <ButtonIconTsx {...props} class={classNames(styles.BrowserHeaderButton, props.class)} noRipple />\n  );\n}\n\nfunction BrowserHeaderTab(props: {\n  page: BrowserPageProps,\n  ref: Ref<HTMLDivElement>,\n  openPageMenu: (e: MouseEvent | TouchEvent) => void,\n  index: Accessor<number>\n}) {\n  const [state, actions] = useContext(BrowserContext);\n  const isActive = createMemo(() => !state.collapsed && state.page === props.page);\n  const transform = createMemo(() => {\n    if(!state.collapsed) {\n      return '';\n    }\n\n    const index = props.index();\n    let value = -20 + Math.min(2, index) * -26;\n    if(index > 2) {\n      value += (index - 2) * -40;\n    }\n\n    return `translateX(${value}px)`;\n  });\n\n  return (\n    <div\n      ref={props.ref}\n      class={classNames(\n        styles.BrowserHeaderTab,\n        isActive() && styles.active,\n        state.pages.indexOf(props.page) === 0 && styles.first\n      )}\n      style={{\n        '--text-width': props.page.titleWidth() + 26 + 'px',\n        'z-index': Math.max(1, 4 - props.index()),\n        'transform': transform()\n      }}\n      onClick={() => actions.select(props.page)}\n    >\n      <BrowserHeaderButton class={styles.BrowserHeaderTabIcon}>\n        <span class={styles.BrowserHeaderTabIconInner}>{props.page.icon}</span>\n        <IconTsx\n          icon=\"more\"\n          class={classNames(styles.BrowserHeaderTabHover, styles.BrowserHeaderTabMore)}\n          onClick={props.openPageMenu}\n        />\n      </BrowserHeaderButton>\n      <div dir=\"auto\" class={styles.BrowserHeaderTabTitle}>\n        {documentFragmentToNodes(wrapEmojiText(props.page.title))}\n      </div>\n      <div class={classNames(styles.BrowserHeaderTabHover, styles.BrowserHeaderTabMask)}></div>\n      <ButtonIconTsx\n        icon=\"close\"\n        class={classNames(styles.BrowserHeaderTabHover, styles.BrowserHeaderTabClose)}\n        noRipple\n        onClick={(e) => {\n          e.stopPropagation();\n          actions.close(props.page);\n        }}\n      />\n    </div>\n  );\n}\n\nfunction BrowserHeader(props: {\n}) {\n  const [state, actions] = useContext(BrowserContext);\n  const needBackButton = createMemo(() => !!state.page.needBackButton);\n  const tabMap: Map<string, HTMLDivElement> = new Map();\n\n  createEffect(() => {\n    const page = state.page;\n    const scrollFromPage = state.page?.scrollFromPage;\n    if(!scrollFromPage) {\n      return;\n    }\n\n    fastSmoothScroll({\n      container: scrollableRef,\n      element: tabMap.get(page.id),\n      position: 'center',\n      axis: 'x',\n      forceDuration: 200,\n      getNormalSize: ({rect}) => {\n        const diff = scrollFromPage.titleWidth() - page.titleWidth();\n        return rect.width + diff/*  + page.titleWidth */;\n      }\n    });\n  });\n\n  const openPageMenu = async(e: MouseEvent | TouchEvent) => {\n    const target = findUpClassName(e.target, styles.BrowserHeaderTab);\n    if(!target) {\n      return;\n    }\n\n    if(!('touches' in e)) e.preventDefault(); // cross-realm-safe mouse check (Document PiP window)\n    // smth\n    if(!('touches' in e)) e.cancelBubble = true;\n\n    const page = state.pages.find((page) => tabMap.get(page.id) === target);\n    if(!page?.menuButtons) {\n      return;\n    }\n\n    const listenerSetter = new ListenerSetter();\n    const copied = page.menuButtons.map((button) => (button = unwrap(button), button.element ? button : copy(button)));\n    const buttons = (await filterButtonMenuItems(copied)).map((button) => {\n      button.options = {listenerSetter};\n      return button;\n    });\n    const element = ButtonMenuSync({\n      buttons,\n      listenerSetter\n    });\n    element.classList.add('contextmenu');\n\n    getOverlayRoot().append(element);\n\n    positionMenu(e, element);\n    contextMenuController.openBtnMenu(element, () => {\n      setTimeout(() => {\n        element.remove();\n        listenerSetter.removeAll();\n      }, 1e3);\n    });\n  };\n\n  onMount(() => {\n    const listenerSetter = new ListenerSetter();\n    attachContextMenuListener({\n      element: scrollableRef,\n      callback: openPageMenu,\n      listenerSetter\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    });\n  });\n\n  const collapsedTitle = createMemo(() => {\n    const wrapTitles = (pages: BrowserPageProps[]) => pages.map((page) => wrapEmojiText(page.title));\n    const pages = state.pages;\n    if(pages.length === 1) {\n      return i18n('MiniApps.Collapsed.One', wrapTitles([pages[0]]));\n    } else if(pages.length === 2) {\n      return i18n('MiniApps.Collapsed.Two', wrapTitles(pages.slice(0, 2)));\n    } else {\n      return i18n('MiniApps.Collapsed.Many', [pages.length - 1, ...wrapTitles([pages[0]])]);\n    }\n  });\n\n  let scrollableRef: HTMLDivElement;\n  return (\n    <div class={styles.BrowserHeader}>\n      <BrowserHeaderButton\n        onClick={() => {\n          if(needBackButton()) {\n            state.page.onBackClick();\n          } else {\n            actions.close(state.page);\n          }\n        }}\n      >\n        <div class={classNames('animated-close-icon', needBackButton() && 'state-back')}></div>\n      </BrowserHeaderButton>\n      <Scrollable\n        class={classNames(styles.BrowserHeaderTabsScrollable, state.collapsed && 'disable-hover')}\n        axis=\"x\"\n        ref={scrollableRef}\n        withBorders=\"manual\"\n      >\n        <div class={styles.BrowserHeaderTabs}>\n          <div\n            class={styles.BrowserHeaderSelector}\n            style={{\n              transform: `translateX(${state.index * 40 + 7 + (state.index >= 1 ? 16 : 0)}px)`,\n              width: state.page.titleWidth() + 16 * 2 + 34 + 'px'\n            }}\n          >\n            <BrowserHeaderTipSvg left />\n            <BrowserHeaderTipSvg right />\n          </div>\n          <Animated type=\"grow-width\" mode=\"add-remove\">\n            <For each={state.pages}>{(page, index) => {\n              return (\n                <BrowserHeaderTab\n                  page={page}\n                  openPageMenu={openPageMenu}\n                  ref={(el) => tabMap.set(page.id, el)}\n                  index={index}\n                />\n              );\n            }}\n            </For>\n          </Animated>\n          <BrowserHeaderButton\n            class={classNames(styles.BrowserHeaderTabIcon, styles.BrowserHeaderNewButton)}\n            onClick={() => openCatalogueInAppBrowser()}\n          >\n            <span class={styles.BrowserHeaderTabIconInner}><IconTsx icon=\"plus\" /></span>\n          </BrowserHeaderButton>\n        </div>\n      </Scrollable>\n      <div\n        class={styles.BrowserHeaderCollapsedTitle}\n        style={{'--translateX': Math.max(0, 3 - state.pages.length) * -14 + 'px'}}\n      >\n        {collapsedTitle()}\n      </div>\n      <Show when={state.canCollapse}>\n        <BrowserHeaderButton\n          icon={state.collapsed ? 'app_expand' : 'app_shrink'}\n          onClick={() => actions.toggleCollapsed()}\n        />\n      </Show>\n    </div>\n  );\n}\n\ntype BrowserContextState = {\n  pages: BrowserPageProps[],\n  index: number,\n  page: BrowserPageProps,\n  destroyed: boolean,\n  collapsed: boolean,\n  canCollapse: boolean\n};\ntype BrowserContextActions = {\n  add: (page: BrowserPageProps) => void,\n  select: (page: BrowserPageProps | number) => void,\n  close: (page: BrowserPageProps) => void,\n  destroy: () => void,\n  toggleCollapsed: (collapse?: boolean) => void,\n  replace: (page: BrowserPageProps, originalPage: BrowserPageProps) => void,\n  setCanCollapse: (canCollapse: boolean) => void\n};\n\nexport type BrowserContextValue = [\n  state: BrowserContextState,\n  actions: BrowserContextActions\n];\n\nfunction createBrowserStore(props: {\n  pages: BrowserPageProps[]\n}): BrowserContextValue {\n  const initialState: BrowserContextState = {\n    pages: [],\n    index: 0,\n    get page() {\n      return state.pages[state.index];\n    },\n    destroyed: false,\n    collapsed: false,\n    canCollapse: true\n  };\n\n  const [state, setState] = createStore<BrowserContextState>(initialState);\n\n  const actions: BrowserContextActions = untrackActions({\n    add: (page) => {\n      page = makeBrowserPage(page);\n      setState('pages', (pages) => {\n        return [...pages, page];\n      });\n      actions.select(state.pages.length - 1);\n    },\n    select: (page) => {\n      let newIndex: number;\n      if(typeof(page) === 'number') {\n        if(page < 0 || page >= state.pages.length) {\n          newIndex = -1;\n        } else {\n          newIndex = page;\n        }\n      } else {\n        newIndex = state.pages.indexOf(page);\n      }\n\n      if(newIndex === -1) {\n        return;\n      }\n\n      batch(() => {\n        const currentPage = state.page;\n        const newPage = state.pages[newIndex];\n        setState('index', newIndex);\n        setState('pages', newIndex, 'scrollFromPage', currentPage);\n\n        queueMicrotask(() => {\n          const index = state.pages.indexOf(newPage);\n          setState('pages', index, 'scrollFromPage', undefined);\n        });\n      });\n    },\n    close: async(page) => {\n      const index = state.pages.findIndex((_page) => _page.id === page.id);\n      if(index === -1) {\n        return;\n      }\n\n      await page.isConfirmationNeededOnClose?.();\n\n      if(state.pages.length === 1) {\n        actions.destroy();\n        return;\n      }\n\n      const pages = state.pages.slice();\n      pages.splice(index, 1);\n\n      let newIndex: number;\n      if(index < state.index) {\n        newIndex = state.index - 1;\n      } else if(index === state.index) {\n        newIndex = Math.min(state.index, pages.length - 1);\n      }\n\n      setState({\n        pages,\n        ...(newIndex !== undefined && {index: newIndex})\n      });\n\n      page.dispose();\n    },\n    destroy: () => {\n      if(state.destroyed) {\n        return;\n      }\n\n      setState('destroyed', true);\n    },\n    toggleCollapsed: (collapse) => {\n      if(!untrack(() => state.canCollapse)) {\n        collapse = false;\n      }\n\n      setState('collapsed', collapse ?? ((v) => !v));\n    },\n    replace: (page, originalPage) => {\n      page.id = originalPage.id;\n      page = makeBrowserPage(page);\n      originalPage.dispose();\n      setState('pages', state.pages.findIndex((_page) => _page.id === originalPage.id), reconcile(page));\n    },\n    setCanCollapse: (canCollapse) => {\n      setState({\n        canCollapse,\n        ...(!canCollapse && {collapsed: false})\n      });\n    }\n  });\n\n  props.pages.forEach(actions.add);\n  setState('index', 0);\n\n  onCleanup(() => {\n    state.pages.forEach((page) => page.dispose());\n  });\n\n  return [state, actions];\n}\n\nconst BrowserContext = createContext<BrowserContextValue>();\nfunction Browser(props: {\n  onExit: () => void\n}) {\n  const width = 480;\n  const height = 640;\n  const aspectRatio = width / height;\n  const additionalHeight = 48;\n  const minWidth = 328;\n  const minHeight = height * (minWidth / width) + additionalHeight;\n\n  const [state, actions] = lastContext = useContext(BrowserContext);\n  const [movableState, setMovableState] = createSignal<MovableState>({\n    width,\n    height: height + additionalHeight\n  });\n\n  onMount(() => {\n    const listenerSetter = new ListenerSetter();\n    const movablePanel = new MovablePanel({\n      listenerSetter,\n      movableOptions: {\n        minWidth,\n        minHeight,\n        element: ref,\n        verifyTouchTarget: (e, type) => {\n          const target = e.target;\n          if(type === 'move' && (\n            !findUpClassName(target, styles.BrowserHeader) ||\n            findUpClassName(target, styles.BrowserHeaderButton) ||\n            findUpClassName(target, styles.BrowserHeaderTab)\n          )) {\n            return false;\n          }\n\n          return true;\n        },\n        aspectRatio: IS_TOUCH_SUPPORTED ? aspectRatio : undefined,\n        resetTransition: true\n      },\n      onResize: (movableState) => {\n        if(state.collapsed) {\n          return;\n        }\n\n        setMovableState(movableState);\n      },\n      previousState: movableState()\n    });\n\n    createEffect(() => {\n      const {movable} = movablePanel;\n      if(!movable) {\n        createEffect(() => {\n          setMovableState({\n            width: windowSize.width - 16,\n            height: Math.min(688, windowSize.height - 16 * 2)\n          });\n\n          ref.style.width = movableState().width + 'px';\n          ref.style.height = movableState().height + 'px';\n        });\n\n        actions.setCanCollapse(false);\n        ref.classList.add(styles.noMovable);\n        onCleanup(() => {\n          actions.setCanCollapse(true);\n          ref.classList.remove(styles.noMovable);\n        });\n        return;\n      }\n\n      const {collapsed} = state;\n      const collapsedWidth = 328;\n      const collapsedHeight = 48;\n      movable.toggleResizable(!collapsed);\n      movable.setMinValues(\n        collapsed ? collapsedWidth : minWidth,\n        collapsed ? collapsedHeight : minHeight\n      );\n\n      const previousMovableState = untrack(movableState);\n      movable.state = collapsed ? {\n        ...previousMovableState,\n        width: collapsedWidth,\n        height: collapsedHeight\n      } : {\n        ...movable.state,\n        width: previousMovableState.width,\n        height: previousMovableState.height\n      };\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n      movablePanel.destroy();\n    });\n  });\n\n  let ref: HTMLDivElement;\n  const main = (\n    <div ref={ref} class={classNames(styles.Browser, state.collapsed && styles.collapsed, 'movable-element')}>\n      <BrowserHeader />\n      <div\n        class={styles.BrowserBody}\n        style={{\n          'width': movableState().width + 'px',\n          '--browser-width': movableState().width + 'px',\n          'height': movableState().height - additionalHeight + 'px'\n        }}\n      >\n        <For each={state.pages}>{(page) => {\n          return (\n            <div\n              class={classNames(\n                styles.BrowserPage,\n                state.page !== page && 'hide'\n              )}\n            >\n              {typeof(page.content) === 'function' ? page.content() : page.content}\n            </div>\n          );\n        }}</For>\n      </div>\n    </div>\n  );\n\n  const animated = (\n    <Animated type=\"cross-fade\" mode=\"add-remove\" appear>\n      {!state.destroyed && main}\n    </Animated>\n  );\n\n  const child = resolveFirst(() => animated);\n  createEffect(() => {\n    if(!child()) {\n      props.onExit();\n    }\n  });\n\n  return (\n    <Portal>\n      {animated}\n    </Portal>\n  );\n}\n\nfunction makeBrowserPage(props: BrowserPageProps): BrowserPageProps {\n  props.titleWidth ??= () => getTextWidth(props.title, FontFullBold);\n  props.id ??= Math.random().toString(36).slice(2);\n  props.menuButtons ??= [];\n  props.menuButtons.push({\n    icon: 'close',\n    text: 'Close',\n    onClick: () => {\n      lastContext[1].close(props);\n    }\n  });\n  return props;\n}\n\nlet lastContext: BrowserContextValue;\nexport function openInAppBrowser(page?: BrowserPageProps) {\n  if(lastContext) {\n    lastContext[1].add(page);\n    lastContext[1].toggleCollapsed(false);\n    return;\n  }\n\n  createRoot((dispose) => {\n    const pages: BrowserPageProps[] = [page];\n\n    const store = createBrowserStore({\n      pages: pages.filter(Boolean)\n    });\n\n    return (\n      <BrowserContext.Provider value={store}>\n        <Browser\n          onExit={() => {\n            lastContext = undefined;\n            dispose();\n          }}\n        />\n      </BrowserContext.Provider>\n    );\n  });\n}\n\nexport async function openWebAppInAppBrowser(options: WebAppLaunchOptions) {\n  if(lastContext && options.cacheKey) {\n    const page = lastContext[0].pages.find((page) => page.cacheKey === options.cacheKey);\n    if(page) {\n      lastContext[1].select(page);\n      return;\n    }\n  }\n\n  const deferred = deferredPromise<void>();\n  const [needBackButton, setNeedBackButton] = createSignal(false);\n  const [destroy, setDestroy] = createSignal(false);\n  const webApp = new WebApp({\n    ...options,\n    header: document.createElement('div'),\n    title: document.createElement('div'),\n    body: document.createElement('div'),\n    forceHide: () => setDestroy(true),\n    onBackStatus: setNeedBackButton\n  });\n\n  const title = await webApp.getTitle(true);\n  if(destroy()) {\n    webApp.destroy();\n    options.onClose?.();\n    return;\n  }\n\n  webApp.init(() => deferred);\n\n  const middlewareHelper = getMiddleware();\n  const avatar = avatarNew({\n    peerId: webApp.getPeerId(),\n    size: 24,\n    middleware: middlewareHelper.get()\n  });\n  await avatar.readyThumbPromise;\n  if(destroy()) {\n    middlewareHelper.destroy();\n    webApp.destroy();\n    options.onClose?.();\n    return;\n  }\n\n  return createRoot((dispose) => {\n    const initialState: BrowserPageProps = {\n      title,\n      icon: avatar.node,\n      menuButtons: webApp.getMenuButtons(),\n      dispose,\n      isConfirmationNeededOnClose: webApp.isConfirmationNeededOnClose,\n      content: webApp.body,\n      get needBackButton() {\n        return needBackButton();\n      },\n      onBackClick: webApp.onBackClick,\n      cacheKey: webApp.cacheKey\n    };\n\n    onCleanup(() => {\n      webApp.destroy();\n      options.onClose?.();\n    });\n\n    createEffect(() => {\n      if(destroy()) {\n        lastContext[1].close(initialState);\n      }\n    });\n\n    queueMicrotask(() => deferred.resolve());\n    // const [state, setState] = createStore<BrowserPageProps>(initialState);\n    const lastState = lastContext?.[0];\n    if(lastState && lastState?.page.isCatalogue) {\n      lastContext[1].replace(initialState, lastContext[0].page);\n    } else {\n      openInAppBrowser(initialState);\n    }\n\n    createEffect(on(() => lastContext[0].collapsed, (collapsed) => {\n      webApp.notifyVisible(!collapsed);\n    }))\n  });\n}\n\nconst GAME_SANDBOX_ATTRIBUTES = [\n  'allow-scripts',\n  'allow-same-origin',\n  'allow-popups',\n  'allow-popups-to-escape-sandbox',\n  'allow-forms',\n  'allow-modals',\n  'allow-orientation-lock',\n  'allow-pointer-lock'\n].join(' ');\n\nconst GAME_ALLOW_ATTRIBUTES = 'accelerometer; gyroscope; magnetometer; gamepad; fullscreen; autoplay; clipboard-write;';\n\nexport async function openGameInAppBrowser(options: {\n  game: Game.game,\n  message: Message.message,\n  url: string\n}) {\n  const {game, message, url} = options;\n  const cacheKey = `game-${game.id}-${message.peerId}-${message.mid}`;\n\n  if(lastContext) {\n    const existing = lastContext[0].pages.find((page) => page.cacheKey === cacheKey);\n    if(existing) {\n      lastContext[1].select(existing);\n      lastContext[1].toggleCollapsed(false);\n      return;\n    }\n  }\n\n  const shareMessage = async() => {\n    const mids = await rootScope.managers.appMessagesManager.getMidsByMessage(message);\n    showForwardPopup({[message.peerId]: mids});\n  };\n\n  const body = document.createElement('div');\n  body.classList.add(styles.BrowserGameBody);\n\n  const telegramWebView = new TelegramWebView({\n    url,\n    sandbox: GAME_SANDBOX_ATTRIBUTES,\n    allow: GAME_ALLOW_ATTRIBUTES,\n    onLoad: () => {\n      telegramWebView.iframe.style.opacity = '1';\n    }\n  });\n\n  const iframe = telegramWebView.iframe;\n  iframe.classList.add(styles.BrowserGameIframe);\n  iframe.style.opacity = '0';\n  body.append(iframe);\n\n  telegramWebView.addEventListener('share_game', shareMessage);\n  telegramWebView.addEventListener('share_score', shareMessage);\n\n  const botId = message.viaBotId || message.fromId;\n  const middlewareHelper = getMiddleware();\n  const avatar = avatarNew({\n    peerId: botId ? (botId as UserId).toPeerId(false) : message.peerId,\n    size: 24,\n    middleware: middlewareHelper.get()\n  });\n  await avatar.readyThumbPromise;\n\n  return createRoot((dispose) => {\n    const initialState: BrowserPageProps = {\n      title: game.title || '',\n      icon: avatar.node,\n      menuButtons: [{\n        icon: 'forward',\n        text: 'ShareFile',\n        onClick: shareMessage,\n        verify: () => true\n      }],\n      dispose,\n      content: body,\n      cacheKey\n    };\n\n    onCleanup(() => {\n      telegramWebView.destroy();\n      middlewareHelper.destroy();\n    });\n\n    queueMicrotask(() => telegramWebView.onMount());\n\n    const lastState = lastContext?.[0];\n    if(lastState && lastState?.page.isCatalogue) {\n      lastContext[1].replace(initialState, lastContext[0].page);\n    } else {\n      openInAppBrowser(initialState);\n    }\n  });\n}\n\nexport async function openCatalogueInAppBrowser() {\n  return createRoot((dispose) => {\n    const [folded, setFolded] = createSignal(true);\n    const [value, setValue] = createSignal('');\n    const targets = new WeakMap<HTMLElement, BotId>;\n    const searchIndex = new SearchIndex<BotId>({ignoreCase: true});\n\n    const inputSearch = new InputSearch({\n      placeholder: 'MiniApps.Search',\n      onChange: (value) => {\n        value = value.trim();\n        setValue(value);\n      },\n      debounceTime: 200,\n      oldStyle: true\n    });\n\n    inputSearch.container.classList.add(styles.BrowserCatalogueSearch);\n\n    const render = (botIds: BotId[], ready: () => void) => {\n      const promises: Promise<any>[] = [];\n      const ret = botIds.map((botId) => {\n        return (\n          <SimilarPeer\n            ref={(el) => targets.set(el, botId)}\n            peerId={botId.toPeerId(false)}\n            promises={promises}\n            avatarSize={64}\n          />);\n      });\n\n      Promise.all(promises).then(ready);\n      return ret;\n    };\n\n    const children = (items: Accessor<JSX.Element>, folded?: Accessor<boolean>) => {\n      return (\n        <div class={classNames(styles.BrowserCatalogueList, folded?.() && styles.folded)}>{items()}</div>\n      );\n    };\n\n    const processBotIds = (botIds: BotId[]) => {\n      untrack(() => {\n        botIds.forEach((botId) => {\n          const user = useUser(botId) as User.user;\n          searchIndex.indexObjectArray(botId, [user.first_name, user.last_name, ...getPeerActiveUsernames(user)].filter(Boolean));\n        });\n      });\n\n      return botIds;\n    };\n\n    const search = (\n      <Section name=\"MiniApps.AppsSearch\" noShadow>\n        <Loader\n          loader={() => {\n            const query = value();\n            return async() => {\n              const result = searchIndex.search(query);\n              return [...result];\n            };\n          }}\n          render={render}\n        >\n          {children}\n        </Loader>\n      </Section>\n    );\n\n    const main = (\n      <div>\n        <Loader\n          loader={() => {\n            return async() => {\n              const result = await rootScope.managers.appUsersManager.getTopPeers('bots_app');\n              return processBotIds(result.map((user) => user.id.toPeerId(false)));\n            };\n          }}\n          render={render}\n        >\n          {(items) => {\n            const elements = resolveElements(items).toArray;\n            const isMoreThanEnough = createMemo(() => elements().length > 7);\n            if(!isMoreThanEnough()) {\n              setFolded(false);\n            }\n\n            return (\n              <Section\n                name=\"MiniApps.Apps\"\n                nameRight={isMoreThanEnough() && (\n                  <span onClick={() => setFolded((folded) => !folded)}>\n                    {i18n(folded() ? 'MiniApps.AppsMore' : 'MiniApps.AppsLess')}\n                  </span>\n                )}\n                noShadow\n              >\n                {children(items, folded)}\n              </Section>\n            );\n          }}\n        </Loader>\n        <Loader\n          loader={() => {\n            let offset = '';\n            return async() => {\n              const result = await rootScope.managers.appAttachMenuBotsManager.getPopularAppBots(offset, 50);\n              offset = result.nextOffset;\n              return processBotIds(result.userIds);\n            };\n          }}\n          render={render}\n        >\n          {(items) => {\n            return items() && (\n              <Section name=\"MiniApps.Popular\" noShadow>\n                {children(items)}\n              </Section>\n            );\n          }}\n        </Loader>\n      </div>\n    );\n\n    const initialState: BrowserPageProps = {\n      title: 'Open App',\n      icon: IconTsx({icon: 'plus'}),\n      dispose,\n      content: (\n        <Scrollable class={styles.BrowserCatalogueScrollable}>\n          <div\n            class={styles.BrowserCatalogue}\n            onClick={(e) => {\n              const target = findUpClassName(e.target as HTMLElement, 'similar-channels-channel');\n              if(!target) {\n                return;\n              }\n\n              const botId = targets.get(target);\n              internalLinkProcessor.processWebAppLink({\n                _: INTERNAL_LINK_TYPE.WEB_APP,\n                appname: '',\n                domain: getPeerActiveUsernames(useUser(botId) as User.user)[0]\n              });\n              // lastContext[1].close(initialState);\n            }}\n          >\n            {inputSearch.container}\n            <Animated type=\"cross-fade\">\n              {value() ? search : main}\n            </Animated>\n          </div>\n        </Scrollable>\n      ),\n      isCatalogue: true\n    };\n\n    openInAppBrowser(initialState);\n    // queueMicrotask(() => deferred.resolve());\n  });\n}\n\nfunction Loader<T>(props: {\n  loader: () => () => Promise<T>,\n  render: (item: T, ready: () => void) => JSX.Element,\n  children: (items: Accessor<JSX.Element>) => JSX.Element,\n  onReady?: () => void\n}) {\n  const loader = createMemo(props.loader);\n  const [ready, setReady] = createSignal(false);\n  const [rendered, setRendered] = createSignal<JSX.Element[]>(undefined, {equals: false});\n\n  const loadMore = (first?: boolean) => {\n    const _loader = loader();\n    const [result, setResult] = createSignal<T>();\n    _loader().then(setResult);\n\n    createReaction(() => {\n      const onReady = () => {\n        setRendered((v) => {\n          if(first) {\n            return [rendered];\n          }\n\n          return [...v, rendered];\n        });\n\n        props.onReady?.();\n        setReady(true);\n      };\n\n      let returned = false;\n      const rendered = props.render(result(), () => {\n        if(returned) {\n          onReady();\n        } else {\n          returned = true;\n        }\n      });\n\n      if(returned) {\n        onReady();\n      } else {\n        returned = true;\n      }\n    })(result);\n  };\n\n  createEffect(on(loader, () => loadMore(true)));\n\n  return (\n    <>\n      {ready() && props.children(rendered)}\n    </>\n  );\n}\n\ntype InstantViewPageExtraProps = {\n  url: string,\n  setAnchor: Setter<string>\n};\n\nexport function openInstantViewInAppBrowser({\n  webPageId: _webPageId,\n  cachedPage,\n  HotReloadGuardProvider,\n  anchor\n}: {\n  webPageId?: Long,\n  cachedPage?: Page | string,\n  HotReloadGuardProvider: typeof SolidJSHotReloadGuardProvider,\n  anchor?: string // * expect it to be '#name'\n}) {\n  if(!cachedPage && anchor) {\n    (lastContext[0].page as BrowserPageProps<InstantViewPageExtraProps>).setAnchor(anchor);\n    return;\n  }\n\n  const TEST_PART = false;\n  let hadCachedPage = typeof(cachedPage) !== 'string';\n  let url: string;\n  if(hadCachedPage) {\n    assumeType<Page>(cachedPage);\n    url = cachedPage.url;\n    if(TEST_PART) {\n      cachedPage.blocks = cachedPage.blocks.slice(0, -5);\n    }\n\n    // * preload page first because anchor can be missing\n    if(anchor && cachedPage.pFlags.part) {\n      hadCachedPage = false;\n      cachedPage = undefined;\n    }\n  } else {\n    url = cachedPage as string;\n    cachedPage = undefined;\n    anchor = new URL(url).hash;\n\n    if(/* anchor &&  */lastContext && lastContext[0].page) {\n      const page = lastContext[0].page as BrowserPageProps<InstantViewPageExtraProps>;\n      const u1 = new URL(page.url);\n      const u2 = new URL(url);\n      u2.hash = u1.hash = '';\n      // * protocol can be http or https\n      if(u1.hostname === u2.hostname && u1.pathname === u2.pathname) {\n        page.setAnchor(anchor);\n        return;\n      }\n    }\n  }\n\n  assumeType<Page>(cachedPage);\n\n  const [webPageId, setWebPageId] = createSignal<Long>(_webPageId);\n  const [page, setPageStore] = createStore<Page>(undefined);\n  const [pageResource] = createResource<Page>(async() => {\n    if(\n      !TEST_PART &&\n      hadCachedPage &&\n      (!cachedPage.pFlags.part && cachedPage.views !== undefined)\n    ) {\n      return cachedPage;\n    }\n\n    if(TEST_PART) await pause(10000);\n    return rootScope.managers.appWebPagesManager.getWebPage(url)\n    .then((webPage) => {\n      setWebPageId(webPage.id);\n      return (webPage as WebPage.webPage).cached_page;\n    });\n  }, {initialValue: cachedPage});\n\n  const needFadeIn = !hadCachedPage;\n  createRoot((dispose) => {\n    createComputed(() => {\n      if(pageResource()) {\n        setPageStore(reconcile(pageResource()));\n      }\n    });\n\n    const [_anchor, setAnchor] = createSignal(anchor, {equals: false});\n    const [appSettings, setAppSettings] = useAppSettings();\n\n    const waitForReady = !lastContext && hadCachedPage;\n    let wasReady = false;\n    const onReady = () => {\n      if(wasReady) {\n        return;\n      }\n\n      wasReady = true;\n      openInAppBrowser(initialState);\n    };\n\n    const scaleModifier = 0.1;\n    const changeScale = (add: boolean, e: MouseEvent) => {\n      cancelEvent(e);\n      setAppSettings(\n        'instantView',\n        'scale',\n        (value) => clamp(+(value + (add ? scaleModifier : -scaleModifier)).toFixed(2), 0.5, 1.5)\n      );\n      return false;\n    };\n\n    const initialState: BrowserPageProps<InstantViewPageExtraProps> = {\n      get title() {\n        if(pageResource.loading && !pageResource.latest) {\n          return I18n.format('Loading', true);\n        }\n\n        const block = page.blocks.find((block) => block._ === 'pageBlockTitle');\n        if(!block) {\n          return /* webPage().site_name ||  */'Instant View';\n        }\n\n        const textWithEntities = wrapTelegramRichText(block.text);\n        return limitSymbols(textWithEntities.text, 20);\n      },\n      menuButtons: [{\n        element: (\n          <span class={classNames('btn-menu-item', styles.ScaleMenu)}>\n            <span class={classNames(styles.ScaleMenuSmaller, 'hover-effect')} onClick={changeScale.bind(null, false)}>A</span>\n            <span class={styles.ScaleMenuScale}>{Math.round(appSettings.instantView.scale * 100) + '%'}</span>\n            <span class={classNames(styles.ScaleMenuBigger, 'hover-effect')} onClick={changeScale.bind(null, true)}>A</span>\n          </span>\n        ) as HTMLElement,\n        onClick: () => {}\n      }, {\n        icon: 'newtab',\n        text: 'OpenInNewTab',\n        onClick: () => safeWindowOpen(url),\n        separator: true,\n        verify: () => !!url // * markdown IV has no real URL — hide open/copy-link actions\n      }, {\n        icon: 'copy',\n        text: 'CopyLink',\n        onClick: () => {\n          copyTextToClipboard(url);\n          toastNew({langPackKey: 'LinkCopied'});\n        },\n        verify: () => !!url\n      }],\n      icon: <IconTsx icon=\"boostcircle_filled\" />,\n      dispose,\n      content: (\n        <Show when={pageResource()}>\n          <HotReloadGuardProvider>\n            <InstantView\n              webPageId={webPageId()}\n              page={page}\n              openNewPage={(url) => {\n                openInstantViewInAppBrowser({cachedPage: url, HotReloadGuardProvider});\n              }}\n              anchor={_anchor()}\n              needFadeIn={needFadeIn}\n              collapse={() => {\n                lastContext[1].toggleCollapsed(true);\n              }}\n              onReady={waitForReady ? () => queueMicrotask(onReady) : undefined}\n            />\n          </HotReloadGuardProvider>\n        </Show>\n      ),\n\n      url,\n      setAnchor\n    };\n\n    if(!waitForReady) {\n      onReady();\n    }\n  });\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {MessageEntity, RichText} from '@layer';\nimport parseMarkdown from '@lib/richTextProcessor/parseMarkdown';\nimport sortEntities from '@lib/richTextProcessor/sortEntities';\nimport {encodeInlineMath} from '@helpers/math/mathMarker';\n\n// * Escaped characters (\\* \\_ \\` …) are stashed as Private Use Area placeholders — one distinct\n// * code point per escapable char — so they pass through the emphasis regexes and parseMarkdown\n// * WITHOUT being seen as markdown delimiters, then are restored to the literal char by cleanup().\n// * (The old `\\x00X\\x00` triple left the literal X in the stream, which re-triggered *emphasis*.)\nconst ESCAPABLE = '\\\\*_`[]<>~|()#+-=!.';\nconst ESC_PUA_BASE = 0xE000;\n// matches exactly the PUA range used for escape placeholders (ESC_PUA_BASE .. +ESCAPABLE.length-1)\nconst ESC_PUA_RE = new RegExp(\n  '[' + String.fromCharCode(ESC_PUA_BASE) + '-' + String.fromCharCode(ESC_PUA_BASE + ESCAPABLE.length - 1) + ']',\n  'g'\n);\nconst SOH = '\\x01';\n// A footnote reference `[^id]` becomes `\\x03N\\x03` (N = its number). splitOnSentinels builds a\n// clickable superscript directly from it — done as a dedicated sentinel (not `[N](#fn-N)` markdown)\n// so the top-level parseMarkdown pass doesn't create a link entity that would sever the pair.\nconst FN_SENTINEL = '\\x03';\nconst SUP_SENTINEL = '\\x04';\nconst SUB_SENTINEL = '\\x06';\nconst MARK_SENTINEL = '\\x07';\n\nconst SENTINEL_TYPE: Record<string, 'textSuperscript' | 'textSubscript' | 'textMarked'> = {\n  [SUP_SENTINEL]: 'textSuperscript',\n  [SUB_SENTINEL]: 'textSubscript',\n  [MARK_SENTINEL]: 'textMarked'\n};\n\nconst SENTINEL_RE = /([\\x03\\x04\\x06\\x07])([^\\x03\\x04\\x06\\x07]+?)\\1/g;\n\nconst CONVERTIBLE = new Set<MessageEntity['_']>([\n  'messageEntityBold',\n  'messageEntityItalic',\n  'messageEntityUnderline',\n  'messageEntityStrike',\n  'messageEntityCode',\n  'messageEntityPre',\n  'messageEntityTextUrl',\n  'messageEntityUrl',\n  'messageEntityEmail',\n  'messageEntityPhone',\n  'messageEntityHighlight',\n  'messageEntityAnchor',\n  'messageEntitySubscript',\n  'messageEntitySuperscript'\n]);\n\n// * preprocess CommonMark dialect into parseMarkdown's dialect.\n// * parseMarkdown supports `**X**` (bold), `__X__` (italic — quirky), `_-_X_-_` (underline),\n// * `~~X~~` (strike), `||X||` (spoiler), `` `X` ``, ``` ```pre``` ```, `[t](u)`.\n// * It does NOT support `*X*`, `_X_`, `***X***`, `\\X` escapes, `<url>`, HTML, $math$, [^fn].\nfunction preprocess(raw: string, refs?: Map<string, string>, footnoteNumbers?: Map<string, number>): string {\n  let s = raw;\n\n  s = s.replace(/<!--[\\s\\S]*?-->/g, '');\n  s = s.replace(/<br\\s*\\/?>/gi, '\\n');\n\n  // <sub>X</sub>, <sup>X</sup>, <mark>X</mark> → sentinel pairs preserved through entity build,\n  // converted to textSubscript/textSuperscript/textMarked in postProcessSentinels.\n  s = s.replace(/<sub\\b[^<>]*>([\\s\\S]*?)<\\/sub>/gi, `${SUB_SENTINEL}$1${SUB_SENTINEL}`);\n  s = s.replace(/<sup\\b[^<>]*>([\\s\\S]*?)<\\/sup>/gi, `${SUP_SENTINEL}$1${SUP_SENTINEL}`);\n  s = s.replace(/<mark\\b[^<>]*>([\\s\\S]*?)<\\/mark>/gi, `${MARK_SENTINEL}$1${MARK_SENTINEL}`);\n\n  // Strip layout / container tags (keep their inner text). Inline formatting tags (b/strong, i/em,\n  // u, s/strike/del) are NOT stripped here — they are converted to real styling further below.\n  s = s.replace(/<\\/?(div|details|summary|p|span)\\b[^<>]*>/gi, '');\n\n  s = s.replace(/<(https?:\\/\\/[^\\s<>]+)>/g, '[$1]($1)');\n  s = s.replace(/<([\\w.+-]+@[\\w.-]+\\.\\w+)>/g, '[$1](mailto:$1)');\n\n  // Footnote references [^id]. A known (defined) footnote → \\x03N\\x03, rendered as a clickable\n  // superscript linking to its definition. An unknown one → a plain \\x04id\\x04 superscript.\n  s = s.replace(/\\[\\^([^\\]\\n]+)\\]/g, (_full, id) => {\n    const n = footnoteNumbers?.get(id);\n    return n !== undefined ? FN_SENTINEL + n + FN_SENTINEL : SUP_SENTINEL + id + SUP_SENTINEL;\n  });\n\n  // Reference-style links [text][id] → [text](url).\n  if(refs && refs.size > 0) {\n    s = s.replace(/\\[([^\\]\\n]+)\\]\\[([^\\]\\n]+)\\]/g, (full, text, id) => {\n      const url = refs.get(String(id).toLowerCase());\n      return url ? `[${text}](${url})` : full;\n    });\n  }\n\n  // [text](url \"title\") → [text](url) — strip optional title.\n  s = s.replace(/\\[([^\\]\\n]+)\\]\\(\\s*([^\\s)]+)\\s+\"[^\"]*\"\\s*\\)/g, '[$1]($2)');\n\n  // Inline math $X$ → a base64-protected marker carried verbatim to the IV, which renders it with\n  // Temml. Encoding it here (before the escape / emphasis passes) keeps the raw LaTeX source intact.\n  s = s.replace(/(?<!\\\\|\\$)\\$(?!\\s|\\$)([^$\\n]+?)(?<!\\s)\\$(?!\\$)/g, (_full, src) => encodeInlineMath(src));\n\n  s = s.replace(/\\\\([\\\\*_`\\[\\]<>~|()#+\\-=!.])/g, (_full, ch) => String.fromCharCode(ESC_PUA_BASE + ESCAPABLE.indexOf(ch)));\n\n  // ***X*** / ___X___ → bold + italic, using parseMarkdown's `**X**` outer and `__X__` inner.\n  // Must run BEFORE single `__X__` so the inserted inner `__` markers stay paired.\n  const tripleReplacement = `${SOH}**${SOH}__${SOH}$1${SOH}__${SOH}**${SOH}`;\n  s = s.replace(/___([^\\n_\\x00\\x01]+?)___/g, tripleReplacement);\n  s = s.replace(/\\*\\*\\*([^\\n*\\x00\\x01]+?)\\*\\*\\*/g, tripleReplacement);\n\n  // CommonMark __X__ (bold) → parseMarkdown's **X**. Content excludes \\x01 so that\n  // the inner `__` from triple replacements (wrapped in \\x01) isn't matched.\n  s = s.replace(/__([^\\n_\\x00\\x01]+?)__/g, `${SOH}**$1**${SOH}`);\n\n  // CommonMark *X* (italic) → parseMarkdown's __X__ (italic).\n  s = s.replace(/(?<![*\\\\\\x00\\x01])\\*(?![\\s*\\x00\\x01])([^\\n*\\x00\\x01]+?)(?<![\\s\\x00\\x01])\\*(?![*\\x00\\x01])/g, `${SOH}__$1__${SOH}`);\n\n  // CommonMark _X_ (italic) → parseMarkdown's __X__. Skip when adjacent to word chars (snake_case).\n  s = s.replace(/(?<![_\\\\\\w\\x00\\x01])_(?![_\\s\\x00\\x01])([^\\n_\\x00\\x01]+?)(?<![\\s\\x00\\x01])_(?![_\\w\\x00\\x01])/g, `${SOH}__$1__${SOH}`);\n\n  // Safe inline formatting HTML → parseMarkdown markers, SOH-wrapped so they parse in any position.\n  // Runs after the emphasis passes so any `*` / `_` content inside is already converted and nests.\n  s = s.replace(/<(?:strong|b)\\b[^<>]*>([\\s\\S]*?)<\\/(?:strong|b)>/gi, `${SOH}**$1**${SOH}`);\n  s = s.replace(/<(?:em|i)\\b[^<>]*>([\\s\\S]*?)<\\/(?:em|i)>/gi, `${SOH}__$1__${SOH}`);\n  s = s.replace(/<u\\b[^<>]*>([\\s\\S]*?)<\\/u>/gi, `${SOH}_-_$1_-_${SOH}`);\n  s = s.replace(/<(?:s|strike|del)\\b[^<>]*>([\\s\\S]*?)<\\/(?:s|strike|del)>/gi, `${SOH}~~$1~~${SOH}`);\n\n  return s;\n}\n\nfunction cleanup(s: string): string {\n  if(!s) return s;\n  s = s.replace(/\\x01/g, '');\n  // restore escaped-char PUA placeholders back to their literal character\n  s = s.replace(ESC_PUA_RE, (ch) => ESCAPABLE[ch.charCodeAt(0) - ESC_PUA_BASE]);\n  return s;\n}\n\nfunction plain(s: string): RichText {\n  return s ? {_: 'textPlain', text: s} : {_: 'textEmpty'};\n}\n\nfunction wrapEntity(entity: MessageEntity, sourceText: string, inner: RichText): RichText {\n  switch(entity._) {\n    case 'messageEntityBold':\n      return {_: 'textBold', text: inner};\n    case 'messageEntityItalic':\n      return {_: 'textItalic', text: inner};\n    case 'messageEntityUnderline':\n      return {_: 'textUnderline', text: inner};\n    case 'messageEntityStrike':\n      return {_: 'textStrike', text: inner};\n    case 'messageEntityCode':\n    case 'messageEntityPre':\n      return {_: 'textFixed', text: inner};\n    case 'messageEntityTextUrl':\n      return {_: 'textUrl', text: inner, url: cleanup(entity.url), webpage_id: 0};\n    case 'messageEntityUrl':\n      return {_: 'textUrl', text: inner, url: cleanup(sourceText), webpage_id: 0};\n    case 'messageEntityEmail':\n      return {_: 'textEmail', text: inner, email: cleanup(sourceText)};\n    case 'messageEntityPhone':\n      return {_: 'textPhone', text: inner, phone: cleanup(sourceText)};\n    case 'messageEntityHighlight':\n      return {_: 'textMarked', text: inner};\n    case 'messageEntityAnchor':\n      return {_: 'textAnchor', text: inner, name: entity.name || ''};\n    case 'messageEntitySubscript':\n      return {_: 'textSubscript', text: inner};\n    case 'messageEntitySuperscript':\n      return {_: 'textSuperscript', text: inner};\n    default:\n      return inner;\n  }\n}\n\nfunction buildSegment(text: string, entities: MessageEntity[], from: number, to: number): RichText {\n  const parts: RichText[] = [];\n  let cursor = from;\n  let i = 0;\n  while(i < entities.length) {\n    const e = entities[i];\n    const eStart = e.offset;\n    const eEnd = e.offset + e.length;\n    if(eStart < cursor || eEnd > to) {\n      ++i;\n      continue;\n    }\n\n    if(eStart > cursor) {\n      parts.push(plain(cleanup(text.slice(cursor, eStart))));\n    }\n\n    const children: MessageEntity[] = [];\n    let j = i + 1;\n    while(j < entities.length) {\n      const c = entities[j];\n      if(c.offset >= eStart && c.offset + c.length <= eEnd) {\n        children.push(c);\n        ++j;\n      } else {\n        break;\n      }\n    }\n\n    const innerText = text.slice(eStart, eEnd);\n    let inner: RichText;\n    if(children.length > 0) {\n      const adjusted = children.map((c) => ({...c, offset: c.offset - eStart}));\n      inner = buildSegment(innerText, adjusted, 0, innerText.length);\n    } else {\n      inner = parseAndBuild(innerText);\n    }\n\n    parts.push(wrapEntity(e, innerText, inner));\n    cursor = eEnd;\n    i = j;\n  }\n\n  if(cursor < to) {\n    parts.push(plain(cleanup(text.slice(cursor, to))));\n  }\n\n  if(parts.length === 0) return {_: 'textEmpty'};\n  if(parts.length === 1) return parts[0];\n  return {_: 'textConcat', texts: parts};\n}\n\nfunction parseAndBuild(text: string): RichText {\n  if(!text) return {_: 'textEmpty'};\n  const [t, entities] = parseMarkdown(text, [], true);\n  const filtered = entities.filter((e) => CONVERTIBLE.has(e._));\n  sortEntities(filtered);\n  return buildSegment(t, filtered, 0, t.length);\n}\n\nfunction splitOnSentinels(text: string): RichText {\n  SENTINEL_RE.lastIndex = 0;\n  const parts: RichText[] = [];\n  let last = 0;\n  let m: RegExpExecArray | null;\n  // A sentinel pair can be severed when its wrapped content gets inline formatting (the entity\n  // tree splits the run, leaving each marker in a different textPlain). Drop any such stray\n  // marker so a raw control char never leaks into rendered text, instead of showing garbage.\n  const pushPlain = (s: string) => {\n    s = s.replace(/[\\x03\\x04\\x06\\x07]/g, '');\n    if(s) parts.push({_: 'textPlain', text: s});\n  };\n  while((m = SENTINEL_RE.exec(text)) !== null) {\n    if(m.index > last) {\n      pushPlain(text.slice(last, m.index));\n    }\n    if(m[1] === FN_SENTINEL) {\n      // Footnote reference: a superscript number that links to its definition (#fn-N), wrapped in an\n      // anchor (#fnref-N) so the definition's back-link can jump here. N is a plain number — no inner\n      // markdown — so building the RichText directly (not via parseMarkdown) can't sever the pair.\n      const n = m[2];\n      parts.push({\n        _: 'textAnchor',\n        name: 'fnref-' + n,\n        text: {\n          _: 'textSuperscript',\n          text: {_: 'textUrl', url: '#fn-' + n, text: {_: 'textPlain', text: n}, webpage_id: 0}\n        }\n      });\n    } else {\n      // Parse the wrapped content so inline markdown inside <sub>/<sup>/<mark> (e.g. **bold**) is\n      // rendered, not shown literally — the surrounding sentinel chars block parseMarkdown otherwise.\n      parts.push({_: SENTINEL_TYPE[m[1]], text: postProcessSentinels(parseAndBuild(m[2]))} as RichText);\n    }\n    last = m.index + m[0].length;\n  }\n  if(last < text.length) {\n    pushPlain(text.slice(last));\n  }\n  if(parts.length === 0) return {_: 'textEmpty'};\n  if(parts.length === 1) return parts[0];\n  return {_: 'textConcat', texts: parts};\n}\n\nfunction postProcessSentinels(rt: RichText): RichText {\n  switch(rt._) {\n    case 'textPlain':\n      if(/[\\x03\\x04\\x06\\x07]/.test(rt.text)) return splitOnSentinels(rt.text);\n      return rt;\n    case 'textConcat':\n      return {_: 'textConcat', texts: rt.texts.map(postProcessSentinels)};\n    case 'textBold':\n    case 'textItalic':\n    case 'textUnderline':\n    case 'textStrike':\n    case 'textFixed':\n    case 'textMarked':\n    case 'textSubscript':\n    case 'textSuperscript':\n    case 'textUrl':\n    case 'textEmail':\n    case 'textPhone':\n    case 'textAnchor':\n      return {...rt, text: postProcessSentinels(rt.text)};\n    default:\n      return rt;\n  }\n}\n\nexport default function inlineMarkdownToRichText(\n  raw: string,\n  refs?: Map<string, string>,\n  footnoteNumbers?: Map<string, number>\n): RichText {\n  if(!raw) return {_: 'textEmpty'};\n  const trimmed = preprocess(raw, refs, footnoteNumbers).replace(/^\\s+|\\s+$/g, '');\n  const built = parseAndBuild(trimmed);\n  return postProcessSentinels(built);\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {Page, PageBlock, PageListItem, PageListOrderedItem, PageTableCell, PageTableRow, RichText} from '@layer';\nimport inlineMarkdownToRichText from '@lib/richTextProcessor/inlineMarkdownToRichText';\n\nconst FENCED_OPEN_RE = /^(`{3,}|~{3,})\\s*(\\S*).*$/;\nconst DIVIDER_RE = /^([-*_])\\1{2,}\\s*$/;\nconst ATX_RE = /^(#{1,6})\\s+(.+?)\\s*#*\\s*$/;\nconst BLOCKQUOTE_RE = /^>\\s?(.*)$/;\nconst UNORDERED_RE = /^(\\s*)([*\\-+•])\\s+(.+)$/;\nconst ORDERED_RE = /^(\\s*)(\\d+)[.)]\\s+(.+)$/;\nconst INDENTED_CODE_RE = /^( {4}|\\t)(.*)$/;\n// up to 3 leading spaces are allowed before a link-reference / footnote definition (CommonMark)\nconst REF_LINK_DEF_RE = /^ {0,3}\\[([^\\]\\n^][^\\]\\n]*)\\]:\\s+(\\S+)(?:\\s+[\"'][^\"']*[\"'])?\\s*$/;\nconst FOOTNOTE_DEF_RE = /^ {0,3}\\[\\^([^\\]\\n]+)\\]:\\s+(.*)$/;\nconst TABLE_LINE_RE = /^\\s*\\|.*\\|\\s*$/;\nconst TABLE_CELL_SEP_RE = /^\\s*:?-{3,}:?\\s*$/;\nconst TASK_RE = /^\\[([ xX])\\]\\s+(.*)$/;\nconst MATH_BLOCK_RE = /^\\$\\$\\s*$/;\nconst DEFLIST_DEF_RE = /^:\\s+(.+)$/;\nconst DETAILS_OPEN_RE = /^\\s*<details\\b[^>]*>/i;\nconst DETAILS_CLOSE_RE = /<\\/details\\s*>/i;\nconst SUMMARY_RE = /<summary\\b[^>]*>([\\s\\S]*?)<\\/summary\\s*>/i;\n// A trailing attribution line inside a blockquote — `— Author`, `– Author`, or `-- Author`. When it\n// stands as its own paragraph it becomes the quote's `caption` (the attribution slot Telegram IV\n// renders under the quote), matching the common markdown convention for cited quotes.\nconst BLOCKQUOTE_ATTRIBUTION_RE = /^(?:—|–|--)\\s+(.+)$/;\n\ntype Refs = Map<string, string>;\n\nfunction plainOrEmpty(text: string): RichText {\n  return text ? {_: 'textPlain', text} : {_: 'textEmpty'};\n}\n\n// GitHub-style heading slug: lowercase, drop non-word/space/dash, spaces → dashes.\nfunction slugifyHeading(text: string): string {\n  return text\n  .toLowerCase()\n  .replace(/<[^<>]+>/g, '')\n  .replace(/[`*_~]/g, '')\n  .replace(/[^\\w\\s-]/g, '')\n  .trim()\n  .replace(/\\s+/g, '-');\n}\n\n// Dynamic scope for the id→sequential-number map of the document currently being parsed. Set (with\n// save/restore) at the top of parseMarkdownToPage so every inlineToRichText call — including those\n// in module-level helpers (lists, tables) — renders `[^id]` references as their number, without\n// threading the map through a dozen signatures. Safe because parsing is synchronous & single-pass;\n// the recursive <details> parse save/restores it.\nlet activeFootnoteNumbers: Map<string, number> | undefined;\n\nfunction inlineToRichText(raw: string, refs: Refs): RichText {\n  return inlineMarkdownToRichText(raw, refs, activeFootnoteNumbers);\n}\n\n// Build a list-item, detecting markdown task syntax (`[x]` / `[ ]`). The task state is carried in\n// the item's native `checkbox`/`checked` pFlags (layer 227) — not rendered as a ☑/☐ glyph — so the\n// IV renderer can show a real square checkbox.\nfunction makeListItem(content: string, num: string, isOrdered: boolean, refs: Refs): PageListItem | PageListOrderedItem {\n  const task = TASK_RE.exec(content);\n  const text = inlineToRichText(task ? task[2] : content, refs);\n  const pFlags: PageListItem.pageListItemText['pFlags'] = {};\n  if(task) {\n    pFlags.checkbox = true;\n    if(task[1].toLowerCase() === 'x') pFlags.checked = true;\n  }\n  return isOrdered ?\n    {_: 'pageListOrderedItemText', pFlags, num, text} :\n    {_: 'pageListItemText', pFlags, text};\n}\n\nfunction isBlockStart(line: string): boolean {\n  return FENCED_OPEN_RE.test(line) ||\n    DIVIDER_RE.test(line) ||\n    ATX_RE.test(line) ||\n    BLOCKQUOTE_RE.test(line) ||\n    UNORDERED_RE.test(line) ||\n    ORDERED_RE.test(line) ||\n    INDENTED_CODE_RE.test(line) ||\n    TABLE_LINE_RE.test(line) ||\n    MATH_BLOCK_RE.test(line) ||\n    DETAILS_OPEN_RE.test(line) ||\n    REF_LINK_DEF_RE.test(line) ||\n    FOOTNOTE_DEF_RE.test(line);\n}\n\nfunction isFenceClose(line: string, openMarker: string): boolean {\n  const m = line.match(/^(`{3,}|~{3,})\\s*$/);\n  if(!m) return false;\n  return m[1][0] === openMarker[0] && m[1].length >= openMarker.length;\n}\n\nfunction splitTableCells(line: string): string[] {\n  let s = line.trim();\n  if(s.startsWith('|')) s = s.slice(1);\n  if(s.endsWith('|')) s = s.slice(0, -1);\n  s = s.replace(/\\\\\\|/g, '\\x05');\n  return s.split('|').map((c) => c.trim().replace(/\\x05/g, '|'));\n}\n\nfunction isTableSeparatorLine(line: string): boolean {\n  if(!TABLE_LINE_RE.test(line)) return false;\n  const cells = splitTableCells(line);\n  return cells.length > 0 && cells.every((c) => TABLE_CELL_SEP_RE.test(c));\n}\n\nfunction parseAlignments(separatorCells: string[]): Array<'left' | 'center' | 'right'> {\n  return separatorCells.map((c) => {\n    const trimmed = c.trim();\n    const left = trimmed.startsWith(':');\n    const right = trimmed.endsWith(':');\n    if(left && right) return 'center';\n    if(right) return 'right';\n    return 'left';\n  });\n}\n\nfunction makeTableCell(text: string, header: boolean, align: 'left' | 'center' | 'right', refs: Refs): PageTableCell {\n  const pFlags: PageTableCell.pageTableCell['pFlags'] = {};\n  if(header) pFlags.header = true;\n  if(align === 'center') pFlags.align_center = true;\n  else if(align === 'right') pFlags.align_right = true;\n  const cell: PageTableCell = {_: 'pageTableCell', pFlags};\n  if(text) cell.text = inlineToRichText(text, refs);\n  return cell;\n}\n\nfunction lineIndent(line: string): number {\n  let n = 0;\n  for(const ch of line) {\n    if(ch === ' ') ++n;\n    else if(ch === '\\t') n += 4;\n    else break;\n  }\n  return n;\n}\n\nfunction parseListBlock(\n  lines: string[],\n  startIdx: number,\n  baseIndent: number,\n  refs: Refs,\n  skipLines: Set<number>\n): {endIdx: number, block: PageBlock | null} {\n  let scan = startIdx;\n  while(scan < lines.length && (skipLines.has(scan) || lines[scan].trim() === '')) ++scan;\n  if(scan >= lines.length) return {endIdx: startIdx, block: null};\n\n  const firstLine = lines[scan];\n  const ordMatch = ORDERED_RE.exec(firstLine);\n  const unMatch = ordMatch ? null : UNORDERED_RE.exec(firstLine);\n  if(!ordMatch && !unMatch) return {endIdx: startIdx, block: null};\n\n  const isOrdered = !!ordMatch;\n  const itemIndent = lineIndent(firstLine);\n  if(itemIndent < baseIndent) return {endIdx: startIdx, block: null};\n\n  const items: Array<PageListItem | PageListOrderedItem> = [];\n  let i = scan;\n\n  while(i < lines.length) {\n    if(skipLines.has(i)) { ++i; continue; }\n    if(lines[i].trim() === '') break;\n    const line = lines[i];\n    const ind = lineIndent(line);\n    if(ind < itemIndent) break;\n\n    if(ind === itemIndent) {\n      const m = isOrdered ? ORDERED_RE.exec(line) : UNORDERED_RE.exec(line);\n      if(!m) break;\n      const content = m[3];\n      const newItem = makeListItem(content, m[2], isOrdered, refs);\n      items.push(newItem);\n      ++i;\n    } else {\n      // ind > itemIndent — possible nested list under previous item\n      const nestedOrd = ORDERED_RE.exec(line);\n      const nestedUn = nestedOrd ? null : UNORDERED_RE.exec(line);\n      if((nestedOrd || nestedUn) && items.length > 0) {\n        const {endIdx, block: nestedBlock} = parseListBlock(lines, i, itemIndent + 1, refs, skipLines);\n        if(nestedBlock) {\n          const last = items[items.length - 1];\n          attachNestedBlock(items, items.length - 1, last, nestedBlock);\n          i = endIdx;\n          continue;\n        }\n      }\n      break;\n    }\n  }\n\n  if(items.length === 0) return {endIdx: i, block: null};\n  const block: PageBlock = isOrdered ?\n    {_: 'pageBlockOrderedList', pFlags: {}, items: items as PageListOrderedItem[]} :\n    {_: 'pageBlockList', items: items as PageListItem[]};\n  return {endIdx: i, block};\n}\n\nfunction attachNestedBlock(\n  items: Array<PageListItem | PageListOrderedItem>,\n  index: number,\n  item: PageListItem | PageListOrderedItem,\n  nested: PageBlock\n): void {\n  if(item._ === 'pageListItemBlocks' || item._ === 'pageListOrderedItemBlocks') {\n    item.blocks.push(nested);\n    return;\n  }\n  const text = (item as PageListItem.pageListItemText | PageListOrderedItem.pageListOrderedItemText).text;\n  const paraBlock: PageBlock = {_: 'pageBlockParagraph', text};\n  if(item._ === 'pageListOrderedItemText') {\n    items[index] = {\n      _: 'pageListOrderedItemBlocks',\n      pFlags: item.pFlags,\n      num: item.num,\n      blocks: [paraBlock, nested]\n    };\n  } else {\n    items[index] = {\n      _: 'pageListItemBlocks',\n      pFlags: item.pFlags,\n      blocks: [paraBlock, nested]\n    };\n  }\n}\n\n// Build a blockquote block from its inner lines (a single leading `>` already stripped from each).\n// The content is parsed recursively so nested blockquotes (`> >`), lists, code blocks, and multiple\n// paragraphs survive as real child blocks. A lone paragraph collapses back to the flat\n// `pageBlockBlockquote` (keeps simple quotes lightweight and matches native IV); anything richer\n// becomes `pageBlockBlockquoteBlocks` carrying the parsed children.\nfunction makeBlockquote(quoteLines: string[], refs: Refs): PageBlock {\n  let caption: RichText = {_: 'textEmpty'};\n\n  // Pull out a trailing `— Author` attribution as the caption when it stands on its own paragraph\n  // (preceded by a blank line, with real quote content before it), leaving the body to be parsed.\n  let last = quoteLines.length - 1;\n  while(last >= 0 && quoteLines[last].trim() === '') --last;\n  if(last >= 1 && quoteLines[last - 1].trim() === '' && quoteLines.slice(0, last - 1).some((l) => l.trim() !== '')) {\n    const m = BLOCKQUOTE_ATTRIBUTION_RE.exec(quoteLines[last].trim());\n    if(m) {\n      caption = inlineToRichText(m[1], refs);\n      quoteLines = quoteLines.slice(0, last);\n    }\n  }\n\n  const innerBlocks = parseMarkdownToPage(quoteLines.join('\\n')).blocks;\n\n  // Empty quote (e.g. it held only an attribution) still renders as a flat, text-less blockquote.\n  if(innerBlocks.length === 0) {\n    return {_: 'pageBlockBlockquote', text: {_: 'textEmpty'}, caption};\n  }\n\n  // A single plain paragraph keeps the lighter inline blockquote (back-compat with flat quotes).\n  if(innerBlocks.length === 1 && innerBlocks[0]._ === 'pageBlockParagraph') {\n    return {_: 'pageBlockBlockquote', text: innerBlocks[0].text, caption};\n  }\n\n  return {_: 'pageBlockBlockquoteBlocks', blocks: innerBlocks, caption};\n}\n\nfunction preScan(lines: string[]): {refs: Refs, footnotes: Array<{id: string, content: string}>, skipLines: Set<number>} {\n  const refs: Refs = new Map();\n  const footnotes: Array<{id: string, content: string}> = [];\n  const skipLines = new Set<number>();\n  for(let i = 0; i < lines.length; ++i) {\n    const line = lines[i];\n    const fn = FOOTNOTE_DEF_RE.exec(line);\n    if(fn) {\n      let content = fn[2];\n      let j = i + 1;\n      // swallow indented continuation lines — but stop at the next footnote / link-reference\n      // definition so it isn't absorbed and silently lost\n      while(\n        j < lines.length &&\n        /^[ \\t]+\\S/.test(lines[j]) &&\n        lines[j].trim() !== '' &&\n        !FOOTNOTE_DEF_RE.test(lines[j]) &&\n        !REF_LINK_DEF_RE.test(lines[j])\n      ) {\n        content += '\\n' + lines[j].trim();\n        skipLines.add(j);\n        ++j;\n      }\n      // keep the FIRST definition of a given id; a duplicate `[^id]:` is still skipped (not leaked\n      // as text) but doesn't create a second numbered entry / anchor.\n      if(!footnotes.some((f) => f.id === fn[1])) {\n        footnotes.push({id: fn[1], content});\n      }\n      skipLines.add(i);\n      continue;\n    }\n    const ref = REF_LINK_DEF_RE.exec(line);\n    if(ref) {\n      refs.set(ref[1].toLowerCase(), ref[2]);\n      skipLines.add(i);\n    }\n  }\n  return {refs, footnotes, skipLines};\n}\n\nexport default function parseMarkdownToPage(raw: string, url = ''): Page.page {\n  raw = raw.replace(/<!--[\\s\\S]*?-->/g, '');\n  const lines = raw.replace(/\\r\\n?/g, '\\n').split('\\n');\n  const blocks: PageBlock[] = [];\n  let firstHash = true;\n\n  const {refs, footnotes, skipLines} = preScan(lines);\n  // number footnotes in definition order; `[^id]` references render the number, and the section\n  // below lists the definitions in the same order (self-consistent, GitHub-like).\n  const footnoteNumbers = new Map<string, number>(footnotes.map((fn, idx) => [fn.id, idx + 1]));\n  const prevFootnoteNumbers = activeFootnoteNumbers;\n  activeFootnoteNumbers = footnoteNumbers;\n  let hasFootnotesHeading = false;\n\n  let i = 0;\n  while(i < lines.length) {\n    if(skipLines.has(i)) {\n      ++i;\n      continue;\n    }\n\n    const line = lines[i];\n\n    if(line.trim() === '') {\n      ++i;\n      continue;\n    }\n\n    const fence = line.match(FENCED_OPEN_RE);\n    if(fence) {\n      const openMarker = fence[1];\n      const language = fence[2] || '';\n      const codeLines: string[] = [];\n      let j = i + 1;\n      while(j < lines.length && !isFenceClose(lines[j], openMarker)) {\n        codeLines.push(lines[j]);\n        ++j;\n      }\n      blocks.push({\n        _: 'pageBlockPreformatted',\n        text: plainOrEmpty(codeLines.join('\\n')),\n        language\n      });\n      i = j < lines.length ? j + 1 : j;\n      continue;\n    }\n\n    if(MATH_BLOCK_RE.test(line)) {\n      const mathLines: string[] = [];\n      let j = i + 1;\n      while(j < lines.length && !MATH_BLOCK_RE.test(lines[j])) {\n        mathLines.push(lines[j]);\n        ++j;\n      }\n      blocks.push({\n        _: 'pageBlockPreformatted',\n        text: plainOrEmpty(mathLines.join('\\n')),\n        language: 'math'\n      });\n      i = j < lines.length ? j + 1 : j;\n      continue;\n    }\n\n    if(DIVIDER_RE.test(line)) {\n      blocks.push({_: 'pageBlockDivider'});\n      ++i;\n      continue;\n    }\n\n    const atx = line.match(ATX_RE);\n    if(atx) {\n      const level = atx[1].length;\n      const headingText = atx[2];\n      if(headingText.trim().toLowerCase() === 'footnotes') {\n        hasFootnotesHeading = true;\n      }\n      const inner = inlineToRichText(headingText, refs);\n      const slug = slugifyHeading(headingText);\n      let block: PageBlock;\n      if(level === 1) {\n        if(firstHash) {\n          block = {_: 'pageBlockTitle', text: inner};\n          firstHash = false;\n        } else {\n          block = {_: 'pageBlockHeader', text: inner};\n        }\n      } else if(level === 2) {\n        block = {_: 'pageBlockHeader', text: inner};\n      } else {\n        block = {_: 'pageBlockSubheader', text: inner};\n      }\n      // Stash the original markdown level (1-6) so the renderer can pick the right\n      // semantic tag (h2-h6) and a level-specific CSS class — pageBlockHeader/Subheader\n      // alone collapses h2 with h1-rest and h3..h6 into one style each.\n      if(block._ !== 'pageBlockTitle') {\n        (block as PageBlock & {headingLevel: number}).headingLevel = level;\n      }\n      if(slug && block._ !== 'pageBlockTitle') {\n        blocks.push({_: 'pageBlockAnchor', name: slug});\n      }\n      blocks.push(block);\n      ++i;\n      continue;\n    }\n\n    if(DETAILS_OPEN_RE.test(line)) {\n      // <details><summary>…</summary>…</details> → native collapsible IV block. The inner content\n      // is parsed recursively (reuses all block handling); the <summary> becomes the title.\n      const openMatch = line.match(DETAILS_OPEN_RE);\n      const firstRemainder = line.slice(openMatch[0].length);\n      const innerLines: string[] = [];\n      let next: number; // index of the line to resume at, after </details>\n      if(DETAILS_CLOSE_RE.test(firstRemainder)) {\n        // whole <details>…</details> sits on this one line\n        innerLines.push(firstRemainder.slice(0, firstRemainder.search(DETAILS_CLOSE_RE)));\n        next = i + 1;\n      } else {\n        if(firstRemainder.trim()) innerLines.push(firstRemainder);\n        let j = i + 1;\n        while(j < lines.length && !DETAILS_CLOSE_RE.test(lines[j])) {\n          innerLines.push(lines[j]);\n          ++j;\n        }\n        if(j < lines.length) {\n          const before = lines[j].slice(0, lines[j].search(DETAILS_CLOSE_RE));\n          if(before.trim()) innerLines.push(before);\n        }\n        next = j < lines.length ? j + 1 : j;\n      }\n      let innerText = innerLines.join('\\n');\n      let title: RichText = {_: 'textEmpty'};\n      const sm = SUMMARY_RE.exec(innerText);\n      if(sm) {\n        title = inlineToRichText(sm[1].trim(), refs);\n        innerText = innerText.replace(SUMMARY_RE, '');\n      }\n      blocks.push({\n        _: 'pageBlockDetails',\n        pFlags: {},\n        title,\n        blocks: parseMarkdownToPage(innerText).blocks\n      });\n      i = next;\n      continue;\n    }\n\n    if(BLOCKQUOTE_RE.test(line)) {\n      const quoteLines: string[] = [];\n      while(i < lines.length) {\n        const m = lines[i].match(BLOCKQUOTE_RE);\n        if(!m) break;\n        quoteLines.push(m[1]);\n        ++i;\n      }\n      blocks.push(makeBlockquote(quoteLines, refs));\n      continue;\n    }\n\n    if(TABLE_LINE_RE.test(line) && i + 1 < lines.length && isTableSeparatorLine(lines[i + 1])) {\n      const headerCells = splitTableCells(line);\n      const aligns = parseAlignments(splitTableCells(lines[i + 1]));\n      const rows: PageTableRow[] = [];\n      rows.push({\n        _: 'pageTableRow',\n        cells: headerCells.map((c, idx) => makeTableCell(c, true, aligns[idx] || 'left', refs))\n      });\n      let j = i + 2;\n      while(j < lines.length && TABLE_LINE_RE.test(lines[j]) && !isTableSeparatorLine(lines[j])) {\n        const dataCells = splitTableCells(lines[j]);\n        rows.push({\n          _: 'pageTableRow',\n          cells: dataCells.map((c, idx) => makeTableCell(c, false, aligns[idx] || 'left', refs))\n        });\n        ++j;\n      }\n      blocks.push({\n        _: 'pageBlockTable',\n        pFlags: {bordered: true},\n        title: {_: 'textEmpty'},\n        rows\n      });\n      i = j;\n      continue;\n    }\n\n    if(UNORDERED_RE.test(line) || ORDERED_RE.test(line)) {\n      const {endIdx, block: listBlock} = parseListBlock(lines, i, 0, refs, skipLines);\n      if(listBlock) {\n        blocks.push(listBlock);\n        i = endIdx;\n        continue;\n      }\n    }\n\n    if(INDENTED_CODE_RE.test(line)) {\n      const codeLines: string[] = [];\n      while(i < lines.length) {\n        const m = lines[i].match(INDENTED_CODE_RE);\n        if(!m) break;\n        codeLines.push(m[2]);\n        ++i;\n      }\n      blocks.push({\n        _: 'pageBlockPreformatted',\n        text: plainOrEmpty(codeLines.join('\\n')),\n        language: ''\n      });\n      continue;\n    }\n\n    if(i + 1 < lines.length && DEFLIST_DEF_RE.test(lines[i + 1]) && !isBlockStart(line)) {\n      const term = line;\n      const definitions: string[] = [];\n      let j = i + 1;\n      while(j < lines.length) {\n        const m = DEFLIST_DEF_RE.exec(lines[j]);\n        if(!m) break;\n        definitions.push(m[1]);\n        ++j;\n      }\n      blocks.push({\n        _: 'pageBlockParagraph',\n        text: {_: 'textBold', text: inlineToRichText(term, refs)}\n      });\n      for(const def of definitions) {\n        blocks.push({\n          _: 'pageBlockBlockquote',\n          text: inlineToRichText(def, refs),\n          caption: {_: 'textEmpty'}\n        });\n      }\n      i = j;\n      continue;\n    }\n\n    const paragraphLines: string[] = [];\n    while(i < lines.length && lines[i].trim() !== '' && !isBlockStart(lines[i]) && !skipLines.has(i)) {\n      paragraphLines.push(lines[i]);\n      ++i;\n    }\n    if(paragraphLines.length) {\n      blocks.push({\n        _: 'pageBlockParagraph',\n        text: inlineToRichText(paragraphLines.join('\\n'), refs)\n      });\n    } else {\n      // The line matched isBlockStart() (so the paragraph loop consumed nothing) yet no block\n      // branch above claimed it — e.g. a pipe-wrapped line that isn't a real GFM table, or a stray\n      // table separator. Emit it as a literal paragraph and advance: `i` MUST always move forward,\n      // otherwise the outer while spins forever and hangs the thread.\n      blocks.push({\n        _: 'pageBlockParagraph',\n        text: inlineToRichText(line, refs)\n      });\n      ++i;\n    }\n  }\n\n  if(footnotes.length > 0) {\n    // A divider separates the definitions from the body (GitHub-style). The auto \"Footnotes\" header\n    // is skipped when the document already titles a section \"Footnotes\" (avoids a duplicate).\n    blocks.push({_: 'pageBlockDivider'});\n    if(!hasFootnotesHeading) {\n      blocks.push({_: 'pageBlockHeader', text: {_: 'textPlain', text: 'Footnotes'}});\n    }\n    for(const fn of footnotes) {\n      const n = footnoteNumbers.get(fn.id);\n      // Anchor (#fn-N) that the reference jumps to.\n      blocks.push({_: 'pageBlockAnchor', name: 'fn-' + n});\n      blocks.push({\n        _: 'pageBlockParagraph',\n        text: {\n          _: 'textConcat',\n          texts: [\n            // the leading marker links back to the reference (#fnref-N) — a clean, no-emoji back-link.\n            {_: 'textSuperscript', text: {_: 'textUrl', url: '#fnref-' + n, text: {_: 'textPlain', text: '' + n}, webpage_id: 0}},\n            {_: 'textPlain', text: ' '},\n            inlineToRichText(fn.content, refs)\n          ]\n        }\n      });\n    }\n  }\n\n  activeFootnoteNumbers = prevFootnoteNumbers;\n  return {\n    _: 'page',\n    pFlags: {},\n    url,\n    blocks,\n    photos: [],\n    documents: []\n  };\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\nimport {openInstantViewInAppBrowser} from '@components/browser';\nimport parseMarkdownToPage from '@lib/richTextProcessor/parseMarkdownToPage';\nimport type SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\nexport function openMarkdownInstantView({\n  raw,\n  url = '',\n  HotReloadGuardProvider\n}: {\n  raw: string,\n  url?: string,\n  HotReloadGuardProvider: typeof SolidJSHotReloadGuardProvider\n}) {\n  const page = parseMarkdownToPage(raw, url);\n  // * mark page as fully cached so openInstantViewInAppBrowser doesn't fetch\n  // * 0 is falsy and hides the views row in InstantView footer\n  page.views = 0;\n  openInstantViewInAppBrowser({cachedPage: page, HotReloadGuardProvider});\n}\n","import {isIpRevealingExtension, isIpRevealingMimeType} from '@environment/ipRevealingDocuments';\nimport MEDIA_MIME_TYPES_SUPPORTED from '@environment/mediaMimeTypesSupport';\nimport {CancellablePromise} from '@helpers/cancellablePromise';\nimport {clearBadCharsAndTrim} from '@helpers/cleanSearchText';\nimport {formatFullSentTime} from '@helpers/date';\nimport {simulateClickEvent, attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport formatBytes from '@helpers/formatBytes';\nimport liteMode from '@helpers/liteMode';\nimport {MediaSizeType} from '@helpers/mediaSizes';\nimport noop from '@helpers/noop';\nimport {Message, MessageMedia, WebPage} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport appDownloadManager, {Progress} from '@lib/appDownloadManager';\nimport appImManager from '@lib/appImManager';\nimport {AppManagers} from '@lib/managers';\nimport getDownloadMediaDetails from '@appManagers/utils/download/getDownloadMediaDetails';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport {joinElementsWith} from '@lib/langPack';\nimport {MAX_FILE_SAVE_SIZE} from '@appManagers/constants';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport wrapPlainText from '@lib/richTextProcessor/wrapPlainText';\nimport rootScope from '@lib/rootScope';\nimport type {ThumbCache} from '@lib/storages/thumbs';\nimport {MediaSearchContext} from '@components/appMediaPlaybackController';\nimport createAudioElement, {AudioElement} from '@components/audio';\nimport {emptyMediaListLoaderFactory} from '@components/emptyMediaListLoader';\nimport confirmationPopup from '@components/confirmationPopup';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {MiddleEllipsisElement} from '@components/middleEllipsis';\nimport ProgressivePreloader from '@components/preloader';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapSenderToPeer from '@components/wrappers/senderToPeer';\nimport wrapSentTime from '@components/wrappers/sentTime';\nimport {Middleware} from '@helpers/middleware';\nimport readBlobAsText from '@helpers/blob/readBlobAsText';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {openMarkdownInstantView} from '@components/markdownInstantView';\n\nrootScope.addEventListener('document_downloading', (docId) => {\n  const elements = Array.from(document.querySelectorAll(`.document[data-doc-id=\"${docId}\"]`)) as HTMLElement[];\n  elements.forEach((element) => {\n    if(element.querySelector('.preloader-container.manual')) {\n      simulateClickEvent(element);\n    }\n  });\n});\n\nexport default async function wrapDocument({\n  message,\n  middleware,\n  withTime,\n  fontWeight,\n  voiceAsMusic,\n  showSender,\n  searchContext,\n  loadPromises,\n  autoDownloadSize,\n  lazyLoadQueue,\n  sizeType,\n  managers = rootScope.managers,\n  cacheContext,\n  fontSize,\n  getSize,\n  canTranscribeVoice,\n  isOut,\n  clickable,\n  uploadingFileName,\n  shouldWrapAsVoice,\n  customAudioToTextButton,\n  globalMedia,\n  doc: docOverride,\n  slot\n}: {\n  message: Message.message,\n  middleware: Middleware,\n  withTime?: boolean,\n  fontWeight?: number,\n  voiceAsMusic?: boolean,\n  showSender?: boolean,\n  searchContext?: MediaSearchContext,\n  loadPromises?: Promise<any>[],\n  autoDownloadSize?: number,\n  lazyLoadQueue?: LazyLoadQueue,\n  sizeType?: MediaSizeType,\n  managers?: AppManagers,\n  cacheContext?: ThumbCache,\n  fontSize?: number,\n  getSize?: () => number,\n  canTranscribeVoice?: boolean,\n  isOut?: boolean,\n  /** Keep the duration out of the subtitle until the row plays. See `AudioElementOptions`. */\n  /** Give an audio row the hover of a clickable Row. See `AudioElementOptions`. */\n  clickable?: boolean,\n  uploadingFileName?: string,\n  customAudioToTextButton?: HTMLElement,\n  shouldWrapAsVoice?: boolean,\n  globalMedia?: HTMLMediaElement,\n  /**\n   * Optional pre-extracted document. When provided, it overrides the\n   * default extraction from `message.media` (or its webpage). Useful when\n   * the document lives in a sibling field of the message (e.g. poll\n   * `solution_media` / `attached_media`).\n   */\n  doc?: MyDocument,\n  /**\n   * Optional storage-key disambiguator forwarded to the underlying\n   * AudioElement / `appMediaPlaybackController.addMedia`. See\n   * `AddMediaArgs.slot`.\n   */\n  slot?: number\n}): Promise<HTMLElement> {\n  fontWeight ??= 500;\n  sizeType ??= '' as any;\n  fontSize ??= 16;\n  const noAutoDownload = autoDownloadSize === 0;\n\n  const doc = docOverride ?? (((message.media as MessageMedia.messageMediaDocument).document || ((message.media as MessageMedia.messageMediaWebPage).webpage as WebPage.webPage).document) as MyDocument);\n  uploadingFileName ??= message?.uploadingFileName?.[0];\n  if(doc.type === 'audio' || doc.type === 'voice' || doc.type === 'round') {\n    return createAudioElement({\n      message,\n      middleware,\n      doc: docOverride,\n      // Slotted audio (e.g. poll description / explanation) should not participate in any chat-wide\n      // playlist. Use an empty list loader so next/previous navigation is a no-op.\n      ...(slot !== undefined ? {mediaSlot: slot, listLoaderFactory: emptyMediaListLoaderFactory} : {}),\n      withTime,\n      voiceAsMusic,\n      searchContext,\n      showSender,\n      noAutoDownload,\n      clickable,\n      lazyLoadQueue,\n      loadPromises,\n      uploadingFileName,\n      shouldWrapAsVoice,\n      customAudioToTextButton,\n      globalMedia,\n      isOut,\n      canTranscribe: canTranscribeVoice && doc.type === 'voice',\n      fontWeight,\n      fontSize,\n      sizeType,\n      getSize\n    });\n  }\n\n  const extSplitted = doc.file_name ? doc.file_name.split('.') : '';\n  let ext = '';\n  ext = extSplitted.length > 1 && Array.isArray(extSplitted) ?\n    clearBadCharsAndTrim(extSplitted.pop().split(' ', 1)[0].toLowerCase()) :\n    'file';\n\n  const docDiv = document.createElement('div');\n  docDiv.classList.add('document', `ext-${ext}`);\n  docDiv.dataset.docId = '' + doc.id;\n  (docDiv as any).doc = doc;\n\n  // return docDiv;\n\n  const icoDiv = document.createElement('div');\n  icoDiv.classList.add('document-ico');\n  let icoTextEl: HTMLElement;\n\n  const hadContext = !!cacheContext;\n  const getCacheContext = () => {\n    return hadContext ? cacheContext : apiManagerProxy.getCacheContext(doc);\n  };\n\n  cacheContext = getCacheContext();\n  let hasThumb = false;\n  if((doc.thumbs?.length || (message.pFlags.is_outgoing && cacheContext.url && doc.type === 'photo'))/*  && doc.mime_type !== 'image/gif' */) {\n    docDiv.classList.add('document-with-thumb');\n    hasThumb = true;\n\n    const imgs: (HTMLImageElement | HTMLCanvasElement | HTMLVideoElement)[] = [];\n    // ! WARNING, use thumbs for check when thumb will be generated for media\n    if(message.pFlags.is_outgoing && ['photo', 'video'].includes(doc.type) && cacheContext.url) {\n      icoDiv.innerHTML = `<img src=\"${cacheContext.url}\">`;\n      imgs.push(icoDiv.firstElementChild as HTMLImageElement);\n    } else {\n      const perf = performance.now();\n      const wrapped = await wrapPhoto({\n        photo: doc,\n        message: null,\n        container: icoDiv,\n        boxWidth: 54,\n        boxHeight: 54,\n        loadPromises,\n        withoutPreloader: true,\n        lazyLoadQueue,\n        size: choosePhotoSize(doc, 54, 54, true),\n        managers\n      });\n      // console.log('was wrapping photo', performance.now() - perf);\n      icoDiv.style.width = icoDiv.style.height = '';\n      if(wrapped.images.thumb) imgs.push(wrapped.images.thumb);\n      if(wrapped.images.full) imgs.push(wrapped.images.full);\n    }\n\n    imgs.forEach((img) => img.classList.add('document-thumb'));\n  } else {\n    icoTextEl = document.createElement('span');\n    icoTextEl.classList.add('document-ico-text');\n    icoTextEl.innerText = ext;\n    icoDiv.append(icoTextEl);\n  }\n\n  // let fileName = stringMiddleOverflow(doc.file_name || 'Unknown.file', 26);\n  const fileName = doc.file_name ? wrapPlainText(doc.file_name) : 'Unknown.file';\n  const descriptionEl = document.createElement('div');\n  descriptionEl.classList.add('document-description');\n  const bytesContainer = document.createElement('span');\n  const bytesEl = formatBytes(doc.size);\n  const bytesJoiner = ' / ';\n\n  const descriptionParts: (HTMLElement | string | DocumentFragment)[] = [bytesEl];\n\n  if(withTime) {\n    descriptionParts.push(formatFullSentTime(message.date));\n  }\n\n  if(showSender) {\n    descriptionParts.push(await wrapSenderToPeer(message));\n  }\n\n  if(!withTime && !showSender) {\n    const b = document.createElement('span');\n    const bytesMaxEl = formatBytes(doc.size);\n    b.append(bytesJoiner, bytesMaxEl);\n    b.style.visibility = 'hidden';\n    descriptionParts.push(b);\n  }\n\n  docDiv.innerHTML = `\n  ${(cacheContext.downloaded && !uploadingFileName) || !message.mid || !hasThumb ? '' : `<div class=\"document-download\"></div>`}\n  <div class=\"document-name\"></div>\n  <div class=\"document-size\"></div>\n  `;\n\n  const nameDiv = docDiv.querySelector('.document-name') as HTMLElement;\n  const middleEllipsisEl = new MiddleEllipsisElement();\n  middleEllipsisEl.dataset.fontWeight = '' + fontWeight;\n  middleEllipsisEl.dataset.fontSize = '' + fontSize;\n  middleEllipsisEl.dataset.sizeType = sizeType;\n  (middleEllipsisEl as any).getSize = getSize;\n  middleEllipsisEl.textContent = fileName;\n  // setInnerHTML(middleEllipsisEl, fileName);\n\n  // * new media popup\n  if(!message.mid) {\n    docDiv.classList.add('downloaded');\n  }\n\n  nameDiv.append(middleEllipsisEl);\n\n  if(showSender) {\n    nameDiv.append(wrapSentTime(message));\n  }\n\n  const sizeDiv = docDiv.querySelector('.document-size') as HTMLElement;\n  bytesContainer.append(...joinElementsWith(descriptionParts, ' · '));\n  sizeDiv.append(bytesContainer);\n\n  docDiv.prepend(icoDiv);\n\n  if(!uploadingFileName && message.pFlags.is_outgoing && !message.mid) {\n    return docDiv;\n  }\n\n  const canSaveToCache = doc.size <= MAX_FILE_SAVE_SIZE;\n\n  let downloadDiv: HTMLElement, preloader: ProgressivePreloader = null;\n  const onLoad = () => {\n    docDiv.classList.remove('downloading');\n\n    if(/* !hasThumb ||  */(doc.size > MAX_FILE_SAVE_SIZE && !uploadingFileName)) {\n      preloader.setManual();\n      preloader.attach(downloadDiv);\n      preloader.preloader.classList.add('manual');\n      preloader.setDownloadFunction(load);\n      return;\n    }\n\n    if(canSaveToCache) {\n      docDiv.classList.add('downloaded');\n    }\n\n    if(downloadDiv) {\n      if(downloadDiv !== icoDiv) {\n        const _downloadDiv = downloadDiv;\n        setTimeout(() => {\n          _downloadDiv.remove();\n        }, 200);\n      }\n\n      downloadDiv = null;\n    }\n\n    if(preloader) {\n      preloader = null;\n    }\n  };\n\n  const addByteProgress = (promise: CancellablePromise<any>) => {\n    docDiv.classList.add('downloading');\n\n    const sizeContainer = document.createElement('span');\n    const _bytesContainer = formatBytes(doc.size);\n    sizeContainer.style.position = 'absolute';\n    sizeContainer.style.left = '0';\n    promise.then(onLoad, noop).finally(() => {\n      // sizeContainer.replaceWith(bytesContainer);\n      bytesContainer.style.visibility = '';\n      sizeContainer.remove();\n      // b && b.classList.remove('hide');\n    });\n\n    // b && b.classList.add('hide');\n\n    const format = (bytes: number) => formatBytes(bytes);\n    let d = format(0);\n    bytesContainer.style.visibility = 'hidden';\n    // bytesContainer.replaceWith(sizeContainer);\n    sizeContainer.append(d, bytesJoiner, _bytesContainer);\n    bytesContainer.parentElement.append(sizeContainer);\n    promise.addNotifyListener((progress: Progress) => {\n      const _d = format(progress.done);\n      d.replaceWith(_d);\n      d = _d;\n    });\n  };\n\n  // ! DO NOT USE ASYNC/AWAIT HERE ! SAFARI WON'T LET DOWNLOAD THE FILE BECAUSE OF ASYNC\n  const load = (e?: Event) => {\n    const save = !e || e.isTrusted;\n    const doc = (docDiv as any).doc;\n    // const doc = await managers.appDocsManager.getDoc(docDiv.dataset.docId);\n    let download: CancellablePromise<any>;\n    const queueId = appImManager.chat.bubbles ? appImManager.chat.bubbles.lazyLoadQueue.queueId : undefined;\n    if(!save) {\n      download = appDownloadManager.downloadToDisc({media: doc, queueId}, true);\n    } else if(ext === 'md' || ext === 'markdown' || /^text\\/(x-)?markdown\\b/i.test(doc.mime_type || '')) {\n      download = appDownloadManager.downloadMedia({media: doc, queueId});\n      download.then(readBlobAsText).then((raw) => {\n        openMarkdownInstantView({\n          raw,\n          HotReloadGuardProvider: SolidJSHotReloadGuardProvider\n        });\n      }).catch(noop);\n    } else if(doc.type === 'pdf' && false) {\n      const canOpenAfter = /* managers.appDocsManager.downloading.has(doc.id) ||  */!preloader || preloader.detached;\n      download = appDownloadManager.downloadMediaURL({media: doc, queueId});\n      if(canOpenAfter) {\n        download.then(() => {\n          setTimeout(async() => { // wait for preloader animation end\n            const url = (getCacheContext()).url;\n            window.open(url);\n          }, liteMode.isAvailable('animations') ? 250 : 0);\n        });\n      }\n    } else if(\n      MEDIA_MIME_TYPES_SUPPORTED.has(doc.mime_type) &&\n      doc.thumbs?.length &&\n      canSaveToCache\n    ) {\n      download = appDownloadManager.downloadMediaURL({media: doc, queueId});\n    } else {\n      download = appDownloadManager.downloadToDisc({media: doc, queueId});\n\n      if(isIpRevealingMimeType(doc.mime_type) || isIpRevealingExtension(ext)) {\n        confirmationPopup({\n          descriptionLangKey: 'Chat.File.QuickLook.Svg',\n          button: {\n            langKey: 'OK',\n            isCancel: true\n          }\n        });\n      }\n    }\n\n    download.catch(() => {\n      docDiv.classList.remove('downloading');\n    });\n\n    if(downloadDiv) {\n      preloader.attach(downloadDiv, true, download);\n      addByteProgress(download);\n    }\n  };\n\n  const {fileName: downloadFileName} = getDownloadMediaDetails({media: doc, downloadId: '1'});\n  if(await managers.apiFileManager.isDownloading(downloadFileName)) {\n    downloadDiv = docDiv.querySelector('.document-download') || icoDiv;\n    const promise = appDownloadManager.downloadToDisc({media: doc}, true);\n\n    preloader = new ProgressivePreloader();\n    preloader.attach(downloadDiv, false, promise);\n    preloader.setDownloadFunction(load);\n    addByteProgress(promise);\n  } else if(!cacheContext.downloaded || uploadingFileName) {\n    downloadDiv = docDiv.querySelector('.document-download') || icoDiv;\n    preloader = new ProgressivePreloader({\n      isUpload: !!uploadingFileName\n    });\n\n    if(!uploadingFileName) {\n      preloader.construct();\n      preloader.setManual();\n      preloader.attach(downloadDiv);\n      preloader.setDownloadFunction(load);\n\n      if(autoDownloadSize !== undefined && autoDownloadSize >= doc.size) {\n        simulateClickEvent(preloader.preloader);\n      }\n    } else {\n      const uploadPromise = appDownloadManager.getUpload(uploadingFileName);\n      preloader.attachPromise(uploadPromise);\n      preloader.attach(downloadDiv);\n      addByteProgress(uploadPromise);\n    }\n  }\n\n  attachClickEvent(docDiv, (e) => {\n    if(findUpClassName(e.target, 'time')) { // prevent downloading by clicking on time\n      return;\n    }\n\n    if(preloader) {\n      preloader.onClick(e);\n    } else {\n      load(e);\n    }\n  });\n\n  return docDiv;\n}\n","import {ScrollableBase} from '@components/scrollable';\nimport SwipeHandler from '@components/swipeHandler';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport rootScope from '@lib/rootScope';\nimport liteMode from '@helpers/liteMode';\nimport {Middleware} from '@helpers/middleware';\nimport clamp from '@helpers/number/clamp';\nimport safeAssign from '@helpers/object/safeAssign';\nimport pause from '@helpers/schedulers/pause';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport whichChild from '@helpers/dom/whichChild';\n\nexport default class Sortable {\n  private element: HTMLElement;\n  private elementRect: DOMRect;\n  private containerRect: DOMRect;\n  private scrollableRect: DOMRect;\n  private minY: number;\n  private maxY: number;\n  private siblings: HTMLElement[];\n  private swipeHandler: SwipeHandler;\n  private startScrollPos: number;\n  private addScrollPos: number;\n\n  private list: HTMLElement;\n  private middleware: Middleware;\n  private onSort: (prevIdx: number, newIdx: number) => void;\n  private scrollable: ScrollableBase;\n\n  constructor(options: {\n    list: HTMLElement,\n    middleware: Middleware,\n    onSort: Sortable['onSort'],\n    scrollable?: Sortable['scrollable']\n  }) {\n    safeAssign(this, options);\n\n    this.swipeHandler = new SwipeHandler({\n      element: this.list,\n      onSwipe: this.onSwipe,\n      verifyTouchTarget: this.verifyTouchTarget,\n      onStart: this.onStart,\n      onReset: this.onReset,\n      setCursorTo: getOverlayRoot(),\n      middleware: this.middleware,\n      withDelay: true\n    });\n  }\n\n  private onSwipe = (xDiff: number, yDiff: number) => {\n    yDiff = clamp(yDiff, this.minY, this.maxY);\n    this.element.style.transform = `translateY(${yDiff}px)`;\n    const count = Math.round(Math.abs(yDiff) / this.elementRect.height);\n    const lastSiblings = this.siblings;\n    this.siblings = [];\n    const property = yDiff < 0 ? 'previousElementSibling' : 'nextElementSibling';\n    let sibling = this.element[property] as HTMLElement;\n    for(let i = 0; i < count; ++i) {\n      if(this.getSortableTarget(sibling)) {\n        this.siblings.push(sibling);\n        sibling = sibling[property] as HTMLElement;\n      } else {\n        break;\n      }\n    }\n\n    (lastSiblings || []).forEach((sibling) => {\n      if(!this.siblings.includes(sibling)) {\n        sibling.style.transform = '';\n      }\n    });\n\n    this.siblings.forEach((sibling) => {\n      const y = this.elementRect.height * (yDiff < 0 ? 1 : -1);\n      sibling.style.transform = `translateY(${y}px)`;\n    });\n\n    if(this.scrollableRect) {\n      const diff = yDiff;\n      const toEnd = diff > 0;\n      const elementEndPos = toEnd ? this.elementRect.bottom : this.elementRect.top;\n      const clientY = elementEndPos + diff - this.addScrollPos;\n      // console.log(clientY, this.scrollableRect.top, elementEndPos, diff, this.addScrollPos, toEnd);\n      let change = 2;\n      if((clientY + (toEnd ? 0 : this.elementRect.height)) >= this.scrollableRect.bottom/*  && diff < this.maxY */) {\n\n      } else if((clientY - (toEnd ? this.elementRect.height : 0)) <= this.scrollableRect.top/*  && diff > this.minY */) {\n        change *= -1;\n      } else {\n        change = undefined;\n      }\n\n      if(change !== undefined) {\n        this.scrollable.scrollPosition += change;\n      }\n    }\n  };\n\n  private verifyTouchTarget = (e: {target: EventTarget}) => {\n    if(this.list.classList.contains('is-reordering')) {\n      return false;\n    }\n\n    this.element = this.getSortableTarget(e.target as HTMLElement);\n    return !!this.element/*  && pause(150).then(() => true) */;\n  };\n\n  private onScroll = () => {\n    const scrollPos = this.scrollable.scrollPosition;\n    const diff = this.addScrollPos = scrollPos - this.startScrollPos;\n    const isVertical = this.scrollable.scrollPositionProperty === 'scrollTop';\n    this.swipeHandler.add(isVertical ? 0 : diff, isVertical ? diff : 0);\n  };\n\n  private onStart = () => {\n    this.list.classList.add('is-reordering');\n    this.element.classList.add('is-dragging', 'no-transition');\n    this.swipeHandler.setCursor('grabbing');\n    this.elementRect = this.element.getBoundingClientRect();\n    this.containerRect = this.list.getBoundingClientRect();\n\n    this.minY = this.containerRect.top - this.elementRect.top;\n    this.maxY = this.containerRect.bottom - this.elementRect.bottom;\n    this.addScrollPos = 0;\n\n    if(this.scrollable) {\n      this.startScrollPos = this.scrollable.scrollPosition;\n      this.scrollableRect = this.scrollable.container.getBoundingClientRect();\n      this.scrollable.container.addEventListener('scroll', this.onScroll);\n    }\n  };\n\n  private onReset = async() => {\n    const length = this.siblings.length;\n    const move = length && length * (this.siblings[0].previousElementSibling === this.element ? 1 : -1);\n    const idx = whichChild(this.element);\n    const newIdx = idx + move;\n\n    this.element.classList.remove('no-transition');\n    this.element.style.transform = move ? `translateY(${move * this.elementRect.height}px)` : '';\n    this.swipeHandler.setCursor('');\n\n    if(this.scrollable) {\n      this.scrollable.container.removeEventListener('scroll', this.onScroll);\n    }\n\n    if(!IS_TOUCH_SUPPORTED) {\n      // Swallow the click that ends the reorder on the active window's body (the PiP doc when popped\n      // out), else the post-drag click isn't suppressed there. (The drag itself runs via SwipeHandler.)\n      attachClickEvent(getOverlayRoot(), cancelEvent, {capture: true, once: true});\n    }\n\n    if(liteMode.isAvailable('animations')) {\n      await pause(250);\n    }\n\n    this.list.classList.remove('is-reordering');\n    this.element.classList.remove('is-dragging');\n    positionElementByIndex(this.element, this.list, newIdx, idx);\n    [this.element, ...this.siblings].forEach((element) => {\n      element.style.transform = '';\n    });\n\n    this.element =\n      this.siblings =\n      this.elementRect =\n      this.containerRect =\n      this.minY =\n      this.maxY =\n      this.startScrollPos =\n      this.addScrollPos =\n      undefined;\n\n    // cancelClick = true;\n\n    if(!move) {\n      return;\n    }\n\n    this.onSort(idx, newIdx);\n  };\n\n  private getSortableTarget(target: HTMLElement) {\n    if(!target) {\n      return;\n    }\n\n    let child = findUpAsChild(target as HTMLElement, this.list);\n    if(child && child.classList.contains('cant-sort')) {\n      child = undefined;\n    }\n\n    return child;\n  }\n}\n","import {Message} from '@layer';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport rootScope from '@lib/rootScope';\n\n/**\n * A local, never-sent message wrapping an audio document, so it can be rendered with the regular\n * `wrapDocument` / `AudioElement` machinery — which needs a message to hang playback state off.\n *\n * Used where tracks exist outside of any chat history: the profile playlist and the music picker.\n * `mid` must be unique within the list that renders it (playback identifies a track by peerId+mid).\n */\nexport default async function createFakeAudioMessage({doc, peerId, mid, savedMusic}: {\n  doc: MyDocument,\n  peerId: PeerId,\n  mid: number,\n  savedMusic?: boolean\n}): Promise<Message.message> {\n  return {\n    _: 'message',\n    id: mid,\n    mid: mid,\n    peer_id: await rootScope.managers.appPeersManager.getOutputPeer(peerId),\n    peerId: peerId,\n    fromId: peerId,\n    date: doc.date,\n    message: '',\n    pFlags: {\n      local: true,\n      ...(savedMusic ? {fakeForSavedMusic: true as const} : {})\n    },\n    media: {\n      _: 'messageMediaDocument',\n      document: doc,\n      pFlags: {}\n    }\n  };\n}\n","import {createEffect, createSignal, onCleanup, onMount, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport {SliderSuperTab} from '@components/slider';\nimport {i18n} from '@lib/langPack';\nimport wrapDocument from '@components/wrappers/document';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {Message} from '@layer';\nimport {MediaItem, MediaListLoader, MediaListLoaderFactory, MediaListLoaderOptions} from '@components/appMediaPlaybackController';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport ListLoader, {ListLoaderResult} from '@helpers/listLoader';\nimport rootScope from '@lib/rootScope';\nimport type {AudioElement} from '@components/audio';\nimport Scrollable from '@components/scrollable';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport showForwardPopup from '@components/popups/forward';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport Sortable from '@helpers/dom/sortable';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {confirmRemoveFromProfileMusic, removeFromProfileMusic} from '@components/savedMusicActions';\nimport createFakeAudioMessage from '@components/wrappers/fakeAudioMessage';\nimport Icon from '@components/icon';\nimport ButtonIcon from '@components/buttonIcon';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport Section from '@components/section';\n\nimport styles from '@components/sidebarRight/tabs/savedMusic.module.scss';\nimport createMiddleware from '@helpers/solid/createMiddleware';\n\nconst DOC_ID_ATTRIBUTE = 'data-doc-id';\n\nfunction SavedMusicContent(props: {\n  peerId: PeerId,\n  scrollable: Scrollable,\n  isMine: boolean,\n  sorting: () => boolean,\n  startSorting: () => void,\n  onLocalMutation: () => void,\n  onLocalMutationFailed: () => void\n}) {\n  const [loadedFirst, setLoadedFirst] = createSignal(false);\n  const [loaded, setLoaded] = createSignal(false);\n  const [docCount, setDocCount] = createSignal(0);\n  let listEl!: HTMLDivElement;\n\n  const lazyLoadQueue = new LazyLoadQueue();\n  onCleanup(() => lazyLoadQueue.clear());\n\n  const savedMusicLoader = new SavedMusicListLoader(props.peerId);\n\n  const loaderFactory: MediaListLoaderFactory = (options) => {\n    savedMusicLoader.setOptions(options);\n    return savedMusicLoader;\n  };\n\n  const middleware = createMiddleware().get();\n\n  let renderPromise = Promise.resolve();\n  savedMusicLoader.onNewDocs = (docs) => {\n    setDocCount((count) => count + docs.length);\n    renderPromise = renderPromise.then(async() => {\n      const playingDetails = appMediaPlaybackController.getPlayingDetails();\n      const playingDocId = playingDetails?.doc?.id;\n      const elements = await Promise.all(docs.map(async(doc) => {\n        const message = await createFakeAudioMessage({doc, peerId: props.peerId, mid: savedMusicLoader.getFakeMid(doc.id), savedMusic: true});\n        const div = await wrapDocument({\n          message,\n          middleware,\n          fontWeight: 400,\n          voiceAsMusic: true,\n          clickable: true,\n          lazyLoadQueue,\n          autoDownloadSize: 0,\n          getSize: () => 320,\n          ...(playingDocId === doc.id && playingDetails.media && playingDetails.isSavedMusic ? {globalMedia: playingDetails.media} : {})\n        }) as AudioElement;\n        div.classList.add('audio-48', 'search-super-item');\n        applySortable(div, props.sorting());\n        div.setAttribute(DOC_ID_ATTRIBUTE, '' + doc.id);\n        div.listLoaderFactory = loaderFactory;\n        return div;\n      }));\n      for(const el of elements) {\n        listEl.append(el);\n      }\n      setLoadedFirst(true);\n      props.scrollable.checkForTriggers?.();\n    });\n  };\n\n  savedMusicLoader.extraOnLoadedMore = () => {\n    if(savedMusicLoader.isFullyLoaded) {\n      setLoaded(true);\n    }\n  };\n\n  savedMusicLoader.setOptions({\n    loadCount: 50,\n    loadWhenLeft: 5,\n    processItem: (message: Message.message) => {\n      appMediaPlaybackController.addMedia({\n        message,\n        autoload: false,\n        clean: false,\n        middleware\n      });\n      return {peerId: message.peerId, mid: message.mid};\n    }\n  });\n\n\n  /**\n   * The marking every reorderable list in the app uses (see `Row.makeSortable`): the handle, the\n   * row's lift while dragged and the transition its neighbours slide with all hang off\n   * `row-sortable`. `cant-sort` is the other half — it is what keeps `Sortable` off a row while the\n   * list is not in the mode, so a plain tap still plays the track.\n   */\n  const applySortable = (element: HTMLElement, sorting: boolean) => {\n    element.classList.toggle('row-sortable', sorting);\n    element.classList.toggle('cant-sort', !sorting);\n\n    const handle = element.querySelector('.row-sortable-icon');\n    if(sorting && !handle) {\n      element.append(Icon('menu', 'row-sortable-icon'));\n    } else if(!sorting) {\n      handle?.remove();\n    }\n  };\n\n  // rows built later read the mode themselves, so this only has to catch the ones already standing\n  createEffect(() => {\n    const sorting = props.sorting();\n    Array.from(listEl.children).forEach((element) => applySortable(element as HTMLElement, sorting));\n  });\n\n  const getTargetDoc = (target: AudioElement | undefined) => {\n    return target?.message && getMediaFromMessage(target.message, true) as MyDocument;\n  };\n\n  onMount(() => {\n    savedMusicLoader.load(true);\n\n    let contextMenuTarget: AudioElement | undefined;\n    createContextMenu({\n      listenTo: listEl,\n      middleware,\n      buttons: [{\n        icon: 'forward',\n        text: 'Forward',\n        onClick: async() => {\n          const msg = contextMenuTarget?.message;\n          if(!msg) return;\n          await rootScope.managers.appMessagesManager.saveMessages([msg]);\n          showForwardPopup({[msg.peerId]: [msg.mid]});\n        },\n        verify: () => !!contextMenuTarget?.message\n      }, {\n        icon: 'download',\n        text: 'MediaViewer.Context.Download',\n        onClick: () => {\n          const doc = getTargetDoc(contextMenuTarget);\n          if(doc) appDownloadManager.downloadToDisc({media: doc});\n        },\n        verify: () => !!getTargetDoc(contextMenuTarget)\n      }, {\n        // the handle the rows grow once the mode is on, so the entry looks like what it turns on\n        icon: 'menu',\n        text: 'SavedMusic.Sort',\n        onClick: () => props.startSorting(),\n        verify: () => props.isMine && !props.sorting() && docCount() > 1\n      }, {\n        icon: 'delete',\n        text: 'SavedMusic.RemoveFromProfile',\n        danger: true,\n        onClick: async() => {\n          const element = contextMenuTarget;\n          const doc = getTargetDoc(element);\n          if(!doc || !await confirmRemoveFromProfileMusic()) {\n            return;\n          }\n\n          // The row goes away right here, so the update our own mutation dispatches would only\n          // rebuild an already-correct list — and throw away the scroll position with it. A\n          // failure is the one case where the list IS wrong now, so rebuild it then.\n          props.onLocalMutation();\n          element.remove();\n          setDocCount((count) => count - 1);\n          removeFromProfileMusic(doc.id).catch(() => props.onLocalMutationFailed());\n        },\n        verify: () => props.isMine && !!getTargetDoc(contextMenuTarget)\n      }],\n      findElement: (e) => {\n        const el = (e.target as HTMLElement).closest('.audio') as AudioElement;\n        if(el) contextMenuTarget = el;\n        return el;\n      }\n    });\n\n    if(props.isMine) {\n      new Sortable({\n        list: listEl,\n        middleware,\n        scrollable: props.scrollable,\n        onSort: (prevIdx, newIdx) => {\n          const ids = Array.from(listEl.children).map((el) => el.getAttribute(DOC_ID_ATTRIBUTE));\n          // `after_id` anchors to the track the moved one now follows — absent means \"put it first\".\n          rootScope.managers.appSavedMusicManager.reorderMusic(ids[newIdx], newIdx > 0 ? ids[newIdx - 1] : undefined);\n        }\n      });\n    }\n  });\n\n  props.scrollable.onScrolledBottom = () => {\n    if(loaded()) return;\n    savedMusicLoader.load(true);\n  };\n\n  return (\n    <>\n      <Show when={loaded() && !docCount()}>\n        <div class={styles.empty}>\n          {i18n('Chat.Search.NothingFound')}\n        </div>\n      </Show>\n      <Show when={!loadedFirst()}>\n        <PreloaderTsx />\n      </Show>\n      {/* the playlist reads as a settings list, so it sits in the section every other row list does */}\n      <Section noDelimiter>\n        <div class={styles.list} ref={listEl} />\n      </Section>\n    </>\n  );\n}\n\n/**\n * Rebuilds the list whenever the playlist changes underneath it — a save from another client, or\n * one of our own mutations that isn't already reflected in the DOM. Remounting is what re-runs the\n * loader from offset 0; the mutations the tab performs itself opt out via `onLocalMutation`.\n */\nfunction SavedMusicList(props: {\n  peerId: PeerId,\n  scrollable: Scrollable,\n  header: HTMLElement\n}) {\n  const [version, setVersion] = createSignal(1);\n  // Sorting is a mode rather than something the rows are always in: dragging and playing are the\n  // same gesture on a row, so the list only becomes reorderable when asked from the menu.\n  const [sorting, setSorting] = createSignal(false);\n\n  // The way out belongs with the tab's own buttons, so it is mounted into the header — and taken\n  // back out the moment the mode ends, which is also when the tab is torn down.\n  createEffect(() => {\n    if(!sorting()) {\n      return;\n    }\n\n    const button = ButtonIcon('checkround');\n    attachClickEvent(button, () => setSorting(false));\n    props.header.append(button);\n    onCleanup(() => button.remove());\n  });\n  const rebuild = () => setVersion((version) => version + 1);\n  let skipUpdates = 0;\n\n  subscribeOn(rootScope)('saved_music_update', ({peerId}) => {\n    if(peerId !== props.peerId) {\n      return;\n    }\n\n    if(skipUpdates) {\n      --skipUpdates;\n      return;\n    }\n\n    rebuild();\n  });\n\n  return (\n    <Show keyed when={version()}>\n      {(_version) => (\n        <SavedMusicContent\n          peerId={props.peerId}\n          scrollable={props.scrollable}\n          isMine={props.peerId === rootScope.myId}\n          sorting={sorting}\n          startSorting={() => setSorting(true)}\n          onLocalMutation={() => ++skipUpdates}\n          onLocalMutationFailed={rebuild}\n        />\n      )}\n    </Show>\n  );\n}\n\ninterface TailEntry {\n  item: MediaItem;\n  doc: MyDocument;\n}\n\nclass SavedMusicListLoader extends ListLoader<MediaItem, Message.message> implements MediaListLoader {\n  public onEmptied?: () => void;\n  public extraOnLoadedMore?: () => void;\n  public onNewDocs?: (docs: MyDocument[]) => void;\n  private offset = 0;\n  private peerId: PeerId;\n  private fakeMidCounter = 0;\n  private docIdToFakeMid = new Map<DocId, number>();\n  private loadingFromEnd = false;\n  private loadingMainForward = false;\n  private loadingTailPrev = false;\n  private gapFillingInProgress = false; // stays true until gap is closed\n\n  // tail: items fetched from the end when wrapping, with a gap in the middle\n  private tailEntries: TailEntry[] = [];\n  private tailOffset = 0;\n  private tailCurrentIdx = -1; // -1 = not in tail region\n  private get inTailRegion() { return this.tailCurrentIdx >= 0; }\n\n  constructor(\n    peerId: PeerId\n  ) {\n    super({\n      loadMore: async(_anchor, older, loadCount) => {\n        if(!older) {\n          return {count: this.count ?? 0, items: []};\n        }\n\n        const result = await rootScope.managers.appSavedMusicManager.getSavedMusic(peerId.toUserId(), this.offset, loadCount);\n        const docs = result.documents as MyDocument[];\n\n        this.offset += docs.length;\n\n        this.onNewDocs?.(docs);\n        const messages: Message.message[] = await Promise.all(\n          docs.map((doc) => createFakeAudioMessage({doc, peerId, mid: this.getFakeMid(doc.id), savedMusic: true}))\n        );\n\n        return {count: result.count, items: messages} as ListLoaderResult<Message.message>;\n      }\n    });\n\n    this.peerId = peerId;\n\n    this.setLoaded(false, true);\n  }\n\n  setCurrent(item: MediaItem) {\n    if(item) {\n      this.current = undefined; // clear so getMainItems doesn't duplicate\n\n      if(!this.repositionTo(item.mid, item.peerId)) {\n        this.current = item; // fallback if item not yet loaded\n      }\n    } else {\n      this.current = item;\n    }\n  }\n\n  public getFakeMid(docId: DocId): number {\n    let mid = this.docIdToFakeMid.get(docId);\n    if(mid === undefined) {\n      mid = -(++this.fakeMidCounter);\n      this.docIdToFakeMid.set(docId, mid);\n    }\n    return mid;\n  };\n\n  private itemMatches(item: MediaItem, mid: number, peerId: PeerId): boolean {\n    return item.mid === mid && item.peerId === peerId;\n  }\n\n  private async loadTailChunk(offset: number, count: number): Promise<TailEntry[]> {\n    const result = await rootScope.managers.appSavedMusicManager.getSavedMusic(\n      this.peerId.toUserId(),\n      offset,\n      count\n    );\n    const docs = result.documents as MyDocument[];\n    const entries: TailEntry[] = [];\n\n    for(const doc of docs) {\n      const message = await createFakeAudioMessage({doc, peerId: this.peerId, mid: this.getFakeMid(doc.id), savedMusic: true});\n      const item = this.processItem ? await this.processItem(message) : {peerId: message.peerId, mid: message.mid};\n      if(item) {\n        entries.push({item: item as MediaItem, doc});\n      }\n    }\n\n    return entries;\n  }\n\n  private async loadFromEnd(jumpToLast: boolean) {\n    if(this.loadingFromEnd || !this.count) return;\n    this.loadingFromEnd = true;\n\n    try {\n      const tailOffset = Math.max(this.offset, this.count - this.loadCount);\n      const tailCount = this.count - tailOffset;\n\n      if(tailOffset <= this.offset) {\n        if(jumpToLast) {\n          await this.load(true);\n          const allItems = this.getMainItems();\n          if(allItems.length > 0) {\n            this.goToMainIndex(allItems, allItems.length - 1, true, false);\n          }\n        }\n        return;\n      }\n\n      this.tailEntries = await this.loadTailChunk(tailOffset, tailCount);\n      this.tailOffset = tailOffset;\n\n      if(jumpToLast && this.tailEntries.length > 0) {\n        this.enterTailRegion(this.tailEntries.length - 1, true);\n      }\n    } finally {\n      this.loadingFromEnd = false;\n    }\n  }\n\n  private enterTailRegion(idx: number, dispatchJump: boolean) {\n    if(idx < 0 || idx >= this.tailEntries.length) return;\n\n    if(!this.inTailRegion && this.current) {\n      this.next.unshift(this.current);\n    }\n\n    this.tailCurrentIdx = idx;\n    this.current = this.tailEntries[idx].item;\n\n    dispatchJump && this.onJump?.(this.current, false);\n    this.prefetchTail();\n  }\n\n  private prefetchTail() {\n    if(!this.inTailRegion) return;\n    const fromStart = this.tailCurrentIdx;\n    if(fromStart < this.loadWhenLeft && this.tailOffset > this.offset) {\n      if(!this.loadingTailPrev) {\n        this.loadTailPrevious();\n      }\n      if(!this.gapFillingInProgress) {\n        this.gapFillingInProgress = true;\n        this.loadMainForward();\n      }\n    }\n  }\n\n  private async loadMainForward() {\n    if(this.loadingMainForward) return;\n    this.loadingMainForward = true;\n    try {\n      await this.load(true);\n      this.tryMergeTail();\n    } finally {\n      this.loadingMainForward = false;\n      this.gapFillingInProgress = false;\n    }\n  }\n\n  private prefetchMain() {\n    if(this.inTailRegion) return;\n\n    const mainItems = this.getMainItems();\n    const currentIdx = this.getMainCurrentIndex();\n    if(currentIdx < 0) return;\n\n    const fromStart = currentIdx;\n    const fromEnd = mainItems.length - 1 - currentIdx;\n\n    if((fromStart < this.loadWhenLeft && this.loadedAllUp) ||\n       (fromEnd < this.loadWhenLeft && !this.loadedAllDown)) {\n      if(!this.tailEntries.length && this.count && this.offset < this.count) {\n        this.loadFromEnd(false);\n      }\n    }\n  }\n\n  private async loadTailPrevious(pendingNav?: {length: number; dispatchJump: boolean; round: boolean}) {\n    if(this.loadingTailPrev) return;\n    this.loadingTailPrev = true;\n\n    try {\n      const chunkStart = Math.max(this.offset, this.tailOffset - this.loadCount);\n      const chunkCount = this.tailOffset - chunkStart;\n\n      if(chunkCount <= 0) {\n        this.tryMergeTail();\n        if(pendingNav) {\n          pendingNav.round ? this.goRound(pendingNav.length, pendingNav.dispatchJump) : this.go(pendingNav.length, pendingNav.dispatchJump);\n        }\n        return;\n      }\n\n      const newEntries = await this.loadTailChunk(chunkStart, chunkCount);\n\n      if(this.inTailRegion) {\n        this.tailCurrentIdx += newEntries.length;\n      }\n      this.tailEntries.unshift(...newEntries);\n      this.tailOffset = chunkStart;\n\n      this.tryMergeTail();\n      this.onLoadedMore?.();\n\n      if(pendingNav) {\n        pendingNav.round ? this.goRound(pendingNav.length, pendingNav.dispatchJump) : this.go(pendingNav.length, pendingNav.dispatchJump);\n      }\n    } finally {\n      this.loadingTailPrev = false;\n    }\n  }\n\n  private tryMergeTail() {\n    if(!this.tailEntries.length) return;\n\n    if(this.offset >= this.tailOffset) {\n      const wasInTail = this.inTailRegion;\n      const currentTailItem = wasInTail ? this.tailEntries[this.tailCurrentIdx]?.item : undefined;\n\n      if(wasInTail) {\n        this.current = undefined;\n        this.tailCurrentIdx = -1;\n      }\n\n      // build combined list: main items + tail items (deduped)\n      const mainItems = this.getMainItems();\n      const existingMids = new Set(mainItems.map((i) => i.mid));\n      if(this.current) existingMids.add(this.current.mid);\n\n      const newTailEntries = this.tailEntries.filter((e) => !existingMids.has(e.item.mid));\n      const allItems = [...mainItems, ...newTailEntries.map((e) => e.item)];\n\n      this.setLoaded(true, true);\n      this.tailEntries = [];\n\n      if(newTailEntries.length) {\n        this.onNewDocs?.(newTailEntries.map((e) => e.doc));\n      }\n\n      // find the target current position\n      const targetMid = currentTailItem?.mid ?? this.current?.mid;\n      const targetIdx = targetMid !== undefined ? allItems.findIndex((i) => i.mid === targetMid) : -1;\n\n      if(targetIdx === -1 && this.current) {\n        // current not in allItems, keep as-is but update prev/next\n        this.previous.length = 0;\n        this.next.length = 0;\n        this.next.push(...allItems);\n      } else if(targetIdx !== -1) {\n        this.previous.length = 0;\n        this.previous.push(...allItems.slice(0, targetIdx));\n        this.current = allItems[targetIdx];\n        this.next.length = 0;\n        this.next.push(...allItems.slice(targetIdx + 1));\n      } else {\n        // no current, just put everything in next\n        this.previous.length = 0;\n        this.next.length = 0;\n        this.next.push(...allItems);\n      }\n    }\n  }\n\n  public setOptions(options: MediaListLoaderOptions) {\n    this.processItem = options.processItem;\n    this.loadCount = options.loadCount ?? 50;\n    this.loadWhenLeft = options.loadWhenLeft ?? 20;\n    this.onJump = options.onJump;\n    this.onEmptied = options.onEmptied;\n\n    const callerOnLoadedMore = options.onLoadedMore;\n    this.onLoadedMore = () => {\n      // dedup: remove any items from prev/next that duplicate current or each other\n      const seenMids = new Set<number>();\n      if(this.current) seenMids.add(this.current.mid);\n\n      // filter previous\n      for(let i = this.previous.length - 1; i >= 0; i--) {\n        const mid = this.previous[i].mid;\n        if(seenMids.has(mid)) {\n          this.previous.splice(i, 1);\n        } else {\n          seenMids.add(mid);\n        }\n      }\n\n      // filter next\n      for(let i = 0; i < this.next.length; i++) {\n        const mid = this.next[i].mid;\n        if(seenMids.has(mid)) {\n          this.next.splice(i, 1);\n          i--;\n        } else {\n          seenMids.add(mid);\n        }\n      }\n\n      this.tryMergeTail();\n      callerOnLoadedMore?.();\n      this.extraOnLoadedMore?.();\n      this.prefetchMain();\n    };\n  }\n\n  public get isFullyLoaded() {\n    return this.loadedAllDown;\n  }\n\n  public override reset(loadedAll = false) {\n    if(this.current || this.previous.length || this.next.length) {\n      return;\n    }\n    super.reset(loadedAll);\n    this.offset = 0;\n    this.tailCurrentIdx = -1;\n    this.tailEntries = [];\n    this.tailOffset = 0;\n    this.gapFillingInProgress = false;\n  }\n\n  public cleanup() {}\n\n  private getMainItems(): MediaItem[] {\n    const items = [...this.previous];\n    if(this.current && !this.inTailRegion) items.push(this.current);\n    items.push(...this.next);\n    return items;\n  }\n\n  private getMainCurrentIndex(): number {\n    if(this.inTailRegion || !this.current) return -1;\n    return this.previous.length;\n  }\n\n  private goToMainIndex(items: MediaItem[], idx: number, dispatchJump: boolean, older: boolean) {\n    if(idx < 0 || idx >= items.length) return undefined;\n\n    this.tailCurrentIdx = -1;\n    this.previous.length = 0;\n    this.previous.push(...items.slice(0, idx));\n    this.current = items[idx];\n    this.next.length = 0;\n    this.next.push(...items.slice(idx + 1));\n\n    dispatchJump && this.onJump?.(this.current, older);\n    return this.current;\n  }\n\n  private syncTailRegion() {\n    if(this.inTailRegion || !this.current || !this.tailEntries.length) return;\n\n    const idx = this.tailEntries.findIndex((e) => this.itemMatches(e.item, this.current!.mid, this.current!.peerId));\n    if(idx !== -1) {\n      this.tailCurrentIdx = idx;\n    }\n  }\n\n  public goRound(length: number, dispatchJump?: boolean): MediaItem | undefined {\n    this.syncTailRegion();\n    this.tryMergeTail();\n    const dispatch = dispatchJump ?? true;\n\n    if(this.inTailRegion) {\n      return this.goRoundInTail(length, dispatch);\n    }\n\n    const mainItems = this.getMainItems();\n    const currentIdx = this.getMainCurrentIndex();\n    let targetIdx = currentIdx + length;\n\n    if(targetIdx >= mainItems.length && !this.loadedAllDown && !this.tailEntries.length) {\n      this.load(true);\n      return undefined;\n    }\n    if(targetIdx < 0 && !this.loadedAllUp) {\n      this.load(false);\n      return undefined;\n    }\n\n    if(mainItems.length > 0) {\n      if(targetIdx < 0 && this.loadedAllUp) {\n        if(this.loadedAllDown) {\n          targetIdx = mainItems.length - 1;\n        } else if(this.tailEntries.length > 0) {\n          this.enterTailRegion(this.tailEntries.length - 1, dispatch);\n          return this.current;\n        } else {\n          this.loadFromEnd(true);\n          return undefined;\n        }\n      } else if(targetIdx >= mainItems.length) {\n        if(this.tailEntries.length > 0) {\n          this.enterTailRegion(0, dispatch);\n          return this.current;\n        } else if(this.loadedAllDown) {\n          targetIdx = 0;\n        }\n      }\n    }\n\n    if(targetIdx < 0 || targetIdx >= mainItems.length) return undefined;\n\n    const result = this.goToMainIndex(mainItems, targetIdx, dispatch, length > 0);\n\n    if(this.next.length < this.loadWhenLeft && !this.loadedAllDown) {\n      this.load(true);\n    }\n    this.prefetchMain();\n\n    return result;\n  }\n\n  private goRoundInTail(length: number, dispatchJump: boolean): MediaItem | undefined {\n    const targetIdx = this.tailCurrentIdx + length;\n\n    if(targetIdx < 0) {\n      if(this.offset >= this.tailOffset) {\n        this.tryMergeTail();\n        return this.goRound(length, dispatchJump);\n      }\n      this.loadTailPrevious({length, dispatchJump, round: true});\n      return undefined;\n    }\n\n    if(targetIdx >= this.tailEntries.length) {\n      this.current = undefined;\n      this.tailCurrentIdx = -1;\n      const mainItems = this.getMainItems();\n      if(mainItems.length > 0) {\n        return this.goToMainIndex(mainItems, 0, dispatchJump, true);\n      }\n      return undefined;\n    }\n\n    this.tailCurrentIdx = targetIdx;\n    this.current = this.tailEntries[targetIdx].item;\n    dispatchJump && this.onJump?.(this.current, length > 0);\n    this.prefetchTail();\n    return this.current;\n  }\n\n  public go(length: number, dispatchJump = true): MediaItem | undefined {\n    this.syncTailRegion();\n    this.tryMergeTail();\n\n    if(this.inTailRegion) {\n      return this.goInTail(length, dispatchJump);\n    }\n\n    const mainItems = this.getMainItems();\n    const currentIdx = this.getMainCurrentIndex();\n    const targetIdx = currentIdx + length;\n\n    if(targetIdx < 0 || targetIdx >= mainItems.length) {\n      if(targetIdx >= mainItems.length && !this.loadedAllDown && !this.tailEntries.length) {\n        this.load(true);\n      }\n      return undefined;\n    }\n\n    const result = this.goToMainIndex(mainItems, targetIdx, dispatchJump, length > 0);\n\n    if(this.next.length < this.loadWhenLeft && !this.loadedAllDown) {\n      this.load(true);\n    }\n    this.prefetchMain();\n\n    return result;\n  }\n\n  private goInTail(length: number, dispatchJump: boolean): MediaItem | undefined {\n    const targetIdx = this.tailCurrentIdx + length;\n\n    if(targetIdx < 0) {\n      if(this.offset >= this.tailOffset) {\n        this.tryMergeTail();\n        return this.go(length, dispatchJump);\n      }\n      this.loadTailPrevious({length, dispatchJump, round: false});\n      return undefined;\n    }\n\n    if(targetIdx >= this.tailEntries.length) {\n      return undefined;\n    }\n\n    this.tailCurrentIdx = targetIdx;\n    this.current = this.tailEntries[targetIdx].item;\n    dispatchJump && this.onJump?.(this.current, length > 0);\n    this.prefetchTail();\n    return this.current;\n  }\n\n  public getPrevious(withOtherSide?: boolean): MediaItem[] {\n    const prev = this.inTailRegion ? this.tailEntries.slice(0, this.tailCurrentIdx).map((e) => e.item) : this.previous;\n    if(withOtherSide) return [...prev, ...this.getNext()];\n    return prev;\n  }\n\n  public getNext(withOtherSide?: boolean): MediaItem[] {\n    const next = this.inTailRegion ? this.tailEntries.slice(this.tailCurrentIdx + 1).map((e) => e.item) : this.next;\n    if(withOtherSide) return [...next, ...this.getPrevious()];\n    return next;\n  }\n\n  // move current position to a known item without resetting the loader state\n  // used when user clicks on a track that's already loaded in main or tail\n  public repositionTo(mid: number, peerId: PeerId): boolean {\n    if(this.tailEntries.length) {\n      const tailIdx = this.tailEntries.findIndex((e) => this.itemMatches(e.item, mid, peerId));\n      if(tailIdx !== -1) {\n        this.enterTailRegion(tailIdx, false);\n        return true;\n      }\n    }\n\n    const mainItems = this.getMainItems();\n    const mainIdx = mainItems.findIndex((item) => this.itemMatches(item, mid, peerId));\n    if(mainIdx !== -1) {\n      this.goToMainIndex(mainItems, mainIdx, false, false);\n      this.prefetchMain();\n      return true;\n    }\n\n    return false;\n  }\n\n  public getCurrent() {\n    return this.current;\n  }\n}\n\nexport default class AppSavedMusicTab extends SliderSuperTab {\n  public peerId: PeerId;\n  private dispose: VoidFunction;\n\n  public init() {\n    this.container.classList.add(styles.container);\n    this.setTitle(this.peerId === rootScope.myId ? 'SavedMusicTabMine' : 'SavedMusicTab');\n\n    this.dispose = render(() => (\n      <SavedMusicList\n        peerId={this.peerId}\n        scrollable={this.scrollable}\n        header={this.header}\n      />\n    ), this.scrollable.container);\n  }\n\n  onCloseAfterTimeout() {\n    super.onCloseAfterTimeout();\n    this.dispose();\n  }\n}\n","import {Message, MessageMedia} from '@layer';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport type {MyMessage} from '@appManagers/appMessagesManager';\nimport canSaveMessageMedia from '@appManagers/utils/messages/canSaveMessageMedia';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport rootScope from '@lib/rootScope';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport type {AppSidebarRight} from '@components/sidebarRight';\nimport AppSavedMusicTab from '@components/sidebarRight/tabs/savedMusic';\n\n/**\n * The playlist tab is one of a kind. Both places that open it — the profile row and the topbar\n * plate — stay reachable while it is up, so opening it again has to bring back the one already\n * there rather than stack another copy on the slider; for a different peer the old one goes once\n * the new has slid in.\n *\n * The slider comes in as an argument because the profile takes its own from the hot-reload guard.\n */\nexport function openSavedMusicTab(appSidebarRight: AppSidebarRight, peerId: PeerId) {\n  const prevTab = appSidebarRight.getTab(AppSavedMusicTab);\n  if(prevTab?.peerId === peerId) {\n    appSidebarRight.toggleSidebar(true);\n    return;\n  }\n\n  const tab = appSidebarRight.createTab(AppSavedMusicTab);\n  tab.peerId = peerId;\n  tab.open();\n  appSidebarRight.toggleSidebar(true);\n  if(prevTab) {\n    setTimeout(() => prevTab.close(), 300);\n  }\n}\n\n/**\n * The document behind a message when it can go into the profile playlist — a plain song, matching\n * `DocumentData::isMusicForProfile` (tdesktop). Voice notes, round videos and non-audio documents\n * are not eligible, and neither is media the sender protected from saving.\n */\nexport function getSavedMusicDocument(message: MyMessage, noForwards?: boolean): MyDocument | undefined {\n  if(!message || message._ !== 'message' || !canSaveMessageMedia(message, noForwards)) {\n    return;\n  }\n\n  const media = (message as Message.message).media as MessageMedia.messageMediaDocument;\n  if(media?._ !== 'messageMediaDocument') {\n    return;\n  }\n\n  const doc = getMediaFromMessage(message, true) as MyDocument;\n  return doc?._ === 'document' && doc.type === 'audio' ? doc : undefined;\n}\n\nexport async function addToProfileMusic(docId: DocId) {\n  // The manager answers false when it can't resolve the document — don't claim a save that the\n  // profile won't actually show.\n  if(await rootScope.managers.appSavedMusicManager.saveMusic(docId)) {\n    toastNew({langPackKey: 'SavedMusic.Added'});\n  }\n}\n\nexport function confirmRemoveFromProfileMusic() {\n  return confirmationPopup({\n    titleLangKey: 'SavedMusic.RemoveFromProfile',\n    descriptionLangKey: 'SavedMusic.RemoveConfirm',\n    button: {\n      langKey: 'Remove',\n      isDanger: true\n    }\n  }).then(() => true, () => false);\n}\n\nexport async function removeFromProfileMusic(docId: DocId) {\n  if(await rootScope.managers.appSavedMusicManager.removeMusic(docId)) {\n    toastNew({langPackKey: 'SavedMusic.Removed'});\n  }\n}\n","import {Message} from '@layer';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport type Chat from '@components/chat/chat';\n\n\nexport function canHaveSuggestedPostReplyMarkup(message: Message.message): boolean {\n  return !message.reply_markup && !!message.suggested_post && !message.suggested_post.pFlags.accepted && !message.suggested_post.pFlags.rejected;\n}\n\ntype Args = {\n  chat: Chat;\n  message: Message.message;\n  bubble: HTMLElement;\n  contentWrapper: HTMLElement;\n};\n\nexport default function addSuggestedPostReplyMarkup({chat, message, bubble, contentWrapper}: Args) {\n  if(!canHaveSuggestedPostReplyMarkup(message)) return;\n\n  return (async() => {\n    const {default: SuggestedPostReplyMarkupContent} = await import('./suggestedPostReplyMarkupContent');\n    const container = new SuggestedPostReplyMarkupContent;\n    container.HotReloadGuard = SolidJSHotReloadGuardProvider;\n    container.feedProps({message, chat});\n\n    bubble.classList.add('with-reply-markup');\n    contentWrapper.append(container);\n  })();\n}\n","import type {AdminLog} from '@appManagers/appChatsManager';\nimport type {MyMessage} from '@appManagers/appMessagesManager';\nimport isEphemeralMessage from '@appManagers/utils/messages/isEphemeralMessage';\n\nfunction getMessageId(message: MyMessage | AdminLog) {\n  return message._ === 'channelAdminLogEvent' ? +message.id : message.mid;\n}\n\nexport default function compareBubbleTimelineMessages(\n  message1: MyMessage | AdminLog,\n  message2: MyMessage | AdminLog\n) {\n  const isEphemeral1 = isEphemeralMessage(message1);\n  const isEphemeral2 = isEphemeralMessage(message2);\n  if(!isEphemeral1 && !isEphemeral2) {\n    return getMessageId(message1) - getMessageId(message2);\n  }\n\n  const timestampDiff = message1.date - message2.date;\n  if(timestampDiff) {\n    return timestampDiff;\n  }\n\n  if(isEphemeral1 && isEphemeral2) {\n    return (message1.ephemeral_order || message1.mid) -\n      (message2.ephemeral_order || message2.mid);\n  }\n\n  return isEphemeral1 ? 1 : -1;\n}\n","import {Accessor, batch, createEffect, createMemo, createRoot, createSignal, onCleanup, Ref} from 'solid-js';\nimport {createStore, SetStoreFunction} from 'solid-js/store';\nimport {Portal} from 'solid-js/web';\nimport clamp from '@helpers/number/clamp';\nimport {attachHotClassName} from '@helpers/solid/classname';\nimport type CustomEmojiElement from '@lib/customEmoji/element';\nimport defineSolidElement, {PassedProps} from '@lib/solidjs/defineSolidElement';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport {IconTsx} from '@components/iconTsx';\nimport type ChatBubbles from '@components/chat/bubbles';\nimport styles from '@components/chat/bubbleParts/chatThreadSeparator.module.scss';\n\nif(import.meta.hot) import.meta.hot.accept();\n\n\nconst PADDING = 2;\nconst SEPARATOR_HEIGHT = 30; // it's actually 29, but let's have it rounded up)\nconst SEPARATOR_ROOT_MARGIN_TOP = 2 * PADDING + 2 * SEPARATOR_HEIGHT;\n\nconst LIMIT_SYMBOLS = 15;\n\n\nexport type SeparatorIntersectorRoot = ReturnType<typeof createIntersectorRoot>;\n\ntype ElementState = {\n  floating?: boolean;\n  hidden?: boolean;\n  nextIntersectionRatio?: number;\n};\n\ntype ElementMapValue = {\n  index: number;\n  signal: [ElementState, SetStoreFunction<ElementState>];\n};\n\nconst getThreshold = () => new Array(SEPARATOR_HEIGHT + 1).fill(0).map((_, idx) => idx / SEPARATOR_HEIGHT);\n\nconst createIntersectorRoot = (rootElement: HTMLElement, initialTopOffset: number) => createRoot((dispose) => {\n  const map = new Map<HTMLElement, ElementMapValue>();\n  let topOffset = initialTopOffset;\n\n  const onEntries = (entries: IntersectionObserverEntry[]) => {\n    batch(() => entries.forEach(entry => {\n      const element = entry.target as HTMLElement;\n      if(!map.has(element)) return;\n\n      const targetMapValue = map.get(element);\n      const [, setState] = targetMapValue.signal;\n\n      const floating = entry.boundingClientRect.bottom < entry.rootBounds.top;\n\n      setState({floating});\n\n      const sortedMapValues = Array.from(map.values()).sort((a, b) => a.index - b.index);\n      const n = sortedMapValues.length;\n      for(let i = 0; i < n - 1; i++) {\n        const [, setCurrent] = sortedMapValues[i].signal;\n        const [next] = sortedMapValues[i + 1].signal;\n\n        setCurrent({hidden: next.floating});\n\n        if(sortedMapValues[i + 1] === targetMapValue) {\n          setCurrent({\n            nextIntersectionRatio: entry.boundingClientRect.bottom < entry.rootBounds.bottom ? entry.intersectionRatio : 1\n          });\n        }\n      }\n    })\n    );\n  };\n\n  const createObserver = () => new IntersectionObserver(onEntries, {\n    root: rootElement,\n    rootMargin: `-${topOffset + SEPARATOR_ROOT_MARGIN_TOP}px 0px 0px 0px`,\n    threshold: getThreshold()\n  });\n\n  let observer = createObserver();\n\n  let cleaned = false;\n\n  onCleanup(() => {\n    cleaned = true;\n    observer.disconnect();\n  });\n\n  return {\n    observe(element: HTMLElement, index: number) {\n      setTimeout(() => {\n        if(!cleaned) observer.observe(element);\n      }, 0);\n\n      const [state, setState] = createStore<ElementState>({floating: false, hidden: false});\n      map.set(element, {\n        index,\n        signal: [state, setState]\n      });\n\n      return state;\n    },\n    unobserve(element: HTMLElement) {\n      observer.unobserve(element);\n      map.delete(element);\n    },\n    setTopOffset(value: number) {\n      if(value === topOffset) return;\n\n      topOffset = value;\n      observer.disconnect();\n      observer = createObserver();\n      map.forEach((_, element) => observer.observe(element));\n    },\n    count: 0,\n    dispose\n  };\n});\n\n\ntype UseIntersectorArgs = {\n  bubbles: ChatBubbles;\n  element: Accessor<HTMLElement>;\n  index: Accessor<number>;\n}\n\nfunction useIntersector({bubbles, element, index}: UseIntersectorArgs) {\n  const root = bubbles.separatorIntersectorRoot ??= createIntersectorRoot(\n    bubbles.scrollable.container,\n    bubbles.chat.chatPaddingTop[0]()\n  );\n  root.count++;\n\n  onCleanup(() => {\n    root.count--;\n    if(root.count <= 0) {\n      root.dispose();\n      bubbles.separatorIntersectorRoot = undefined;\n    }\n  });\n\n  return createMemo((): ElementState => {\n    const el = element();\n    if(!el) return {};\n\n    const state = root.observe(el, index());\n    onCleanup(() => root.unobserve(el));\n\n    return state;\n  });\n}\n\ntype Props = {\n  bubbles: ChatBubbles;\n  peerId: PeerId;\n  threadId?: number;\n  targetPeerId: PeerId;\n  targetThreadId?: number;\n  targetMonoforumThreadId?: PeerId;\n  index: number;\n};\n\nconst ChatThreadSeparator = defineSolidElement({\n  name: 'chat-thread-separator',\n  component: (props: PassedProps<Props>) => {\n    const {appImManager, PeerTitleTsx} = useHotReloadGuard();\n    attachHotClassName(props.element, styles.Container);\n\n    let scaledEl: HTMLElement;\n\n    const [serviceMsg, setServiceMsg] = createSignal<HTMLElement>();\n\n    const state = useIntersector({\n      bubbles: props.bubbles,\n      element: serviceMsg,\n      index: () => props.index\n    });\n\n    const onClick = () => {\n      appImManager.setInnerPeer({\n        peerId: props.targetPeerId,\n        monoforumThreadId: props.targetMonoforumThreadId,\n        threadId: props.targetThreadId\n      });\n    };\n\n    const scale = createMemo(() => clamp((state().nextIntersectionRatio ?? 1), 0, 1));\n\n    const isScaling = createMemo(() => scale() < 1);\n\n    createEffect(() => {\n      if(!isScaling() || !scaledEl) return;\n\n      const emojiElements = Array.from(scaledEl.querySelectorAll<CustomEmojiElement>('custom-emoji-element'))\n      .filter(emojiElement => !emojiElement?.paused);\n\n      emojiElements.forEach((emojiElement) => {\n        emojiElement.pause();\n      });\n\n      onCleanup(() => {\n        emojiElements.forEach((emojiElement) => {\n          emojiElement.play();\n        });\n      });\n    });\n\n    const InnerPeerTitle = (thisProps: {ref?: Ref<HTMLElement>}) => {\n      return (\n        <PeerTitleTsx\n          ref={thisProps.ref}\n          class={styles.PeerTitle}\n          peerId={props.peerId}\n          threadId={props.threadId}\n          withIcons={!!props.threadId}\n          limitSymbols={LIMIT_SYMBOLS}\n          onlyFirstName={true}\n        />\n      );\n    };\n\n    return (\n      <>\n        <div\n          ref={setServiceMsg}\n          class={styles.ServiceMsg}\n          classList={{\n            [styles.hidden]: state().floating\n          }}\n          onClick={onClick}\n        >\n          <InnerPeerTitle />\n          <IconTsx icon='arrowhead' class={styles.ArrowIcon} />\n        </div>\n\n        <Portal mount={props.bubbles.floatingSeparatorsContainer}>\n          <div\n            class={styles.ServiceMsg}\n            classList={{\n              [styles.hidden]: !state().floating || state().hidden,\n              [styles.floating]: true\n            }}\n            style={{\n              '--top': `${props.bubbles.chat.chatPaddingTop[0]() + SEPARATOR_HEIGHT + 2 * PADDING}px`,\n              '--scale': scale()\n            }}\n            onClick={onClick}\n          >\n            <InnerPeerTitle ref={scaledEl} />\n            <IconTsx icon='arrowhead' class={styles.ArrowIcon} />\n          </div>\n        </Portal>\n\n        <div class={`${styles.Separator} ${styles.SeparatorLeft}`} classList={{\n          [styles.center]: state().floating\n        }} />\n        <div class={`${styles.Separator} ${styles.SeparatorRight}`} classList={{\n          [styles.center]: state().floating\n        }} />\n      </>\n    );\n  }\n});\n\nexport default ChatThreadSeparator;\n","import type {Message} from '@layer';\nimport type {AdminLog} from '@appManagers/appChatsManager';\nimport type Chat from '@components/chat/chat';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport getMessageThreadId from '@appManagers/utils/messages/getMessageThreadId';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport type {BubbleElementAddons} from '@components/chat/types';\nimport ChatThreadSeparator from '@components/chat/bubbleParts/chatThreadSeparator';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\n\ntype SeparatorItem = {\n  bubble: HTMLElement,\n  message: Message.message | Message.messageService | AdminLog\n};\n\ntype SeparatorChat = Pick<Chat,\n  'hashtagType' |\n  'isMonoforum' |\n  'canManageDirectMessages' |\n  'monoforumThreadId' |\n  'isBotforum' |\n  'threadId' |\n  'isAllMessagesForum' |\n  'isOutMessage' |\n  'peerId' |\n  'bubbles'\n>;\n\nfunction removeSeparator(item: SeparatorItem) {\n  item.bubble.classList.remove('has-chat-thread-separator');\n  (item.bubble as BubbleElementAddons).chatThreadSeparator?.remove();\n}\n\nexport default function updateChatThreadSeparators(items: SeparatorItem[], chat: SeparatorChat) {\n  const isMyMessagesSearch = chat.hashtagType === 'my';\n  const isMonoforum = !isMyMessagesSearch && chat.isMonoforum && chat.canManageDirectMessages && !chat.monoforumThreadId;\n  const isBotforum = !isMyMessagesSearch && chat.isBotforum && !chat.threadId;\n  const isForum = !isMyMessagesSearch && chat.isAllMessagesForum;\n\n  const canHaveSeparators = isMyMessagesSearch || isMonoforum || isBotforum || isForum;\n\n  if(!canHaveSeparators) {\n    items.forEach(removeSeparator);\n    return;\n  }\n\n  let prevKey: number | string;\n\n  forEachReverse(items, (item, i) => {\n    const message = item.message;\n    if(message._ === 'channelAdminLogEvent') {\n      removeSeparator(item);\n      return;\n    }\n\n    let peerId: PeerId;\n    let threadId: number;\n    let targetPeerId: PeerId;\n    let targetThreadId: number;\n    let targetMonoforumThreadId: PeerId;\n    let key: number | string;\n\n    if(isMyMessagesSearch) {\n      if(message._ !== 'message' || !chat.isOutMessage(message)) {\n        removeSeparator(item);\n        return;\n      }\n\n      peerId = message.peerId;\n      const isResultForum = apiManagerProxy.isForum(peerId);\n      const isResultBotforum = apiManagerProxy.isBotforum(peerId);\n      const isResultMonoforum = apiManagerProxy.isMonoforum(peerId);\n      const savedPeerId = getPeerId(message.saved_peer_id);\n\n      threadId = savedPeerId || (isResultForum || isResultBotforum || isResultMonoforum ? getMessageThreadId(message, {\n        isForum: isResultForum,\n        isBotforum: isResultBotforum\n      }) : undefined);\n      targetPeerId = peerId;\n      if(isResultMonoforum) {\n        targetMonoforumThreadId = threadId as PeerId;\n      } else {\n        targetThreadId = threadId;\n      }\n      key = `${peerId}_${threadId || ''}`;\n    } else {\n      const savedPeerId = isMonoforum ? getPeerId(message.saved_peer_id) : undefined;\n      threadId = isBotforum ?\n        getMessageThreadId(message, {isBotforum: true}) :\n        isForum ? getMessageThreadId(message, {isForum: true}) : undefined;\n\n      peerId = savedPeerId || chat.peerId;\n      key = savedPeerId || threadId;\n      targetPeerId = isMonoforum ? chat.peerId : peerId;\n      targetThreadId = isMonoforum ? undefined : threadId;\n      targetMonoforumThreadId = isMonoforum ? savedPeerId : undefined;\n    }\n\n    if(!key) {\n      removeSeparator(item);\n      return;\n    }\n\n    const bubbleAddons = item.bubble as BubbleElementAddons;\n\n    if(prevKey === key) {\n      removeSeparator(item);\n      return;\n    }\n\n    prevKey = key;\n\n    if(bubbleAddons.chatThreadSeparator) {\n      bubbleAddons.chatThreadSeparator.feedProps<false>({\n        peerId,\n        threadId,\n        targetPeerId,\n        targetThreadId,\n        targetMonoforumThreadId,\n        index: -i\n      });\n      item.bubble.classList.add('has-chat-thread-separator');\n      if(bubbleAddons.chatThreadSeparator.parentElement !== item.bubble) {\n        item.bubble.prepend(bubbleAddons.chatThreadSeparator);\n      }\n      return;\n    }\n\n    bubbleAddons.chatThreadSeparator = new ChatThreadSeparator;\n    bubbleAddons.chatThreadSeparator.HotReloadGuard = SolidJSHotReloadGuardProvider;\n    bubbleAddons.chatThreadSeparator.feedProps({\n      bubbles: chat.bubbles,\n      peerId,\n      threadId,\n      targetPeerId,\n      targetThreadId,\n      targetMonoforumThreadId,\n      index: -i\n    });\n    item.bubble.classList.add('has-chat-thread-separator');\n    item.bubble.prepend(bubbleAddons.chatThreadSeparator);\n  });\n}\n","import rootScope from '@lib/rootScope';\n// import { generatePathData } from '@helpers/dom';\nimport {MyMessage} from '@appManagers/appMessagesManager';\nimport type Chat from '@components/chat/chat';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport insertInDescendSortedArray from '@helpers/array/insertInDescendSortedArray';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport {Message, ReplyMarkup} from '@layer';\nimport {NULL_PEER_ID, REPLIES_PEER_ID, VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport ChatBubbles, {SERVICE_AS_REGULAR, STICKY_OFFSET} from '@components/chat/bubbles';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport partition from '@helpers/array/partition';\nimport getMessageThreadId from '@appManagers/utils/messages/getMessageThreadId';\nimport {avatarNew} from '@components/avatarNew';\nimport {MiddlewareHelper} from '@helpers/middleware';\nimport {ChatType} from './chatType';\nimport getFwdFromName from '@appManagers/utils/messages/getFwdFromName';\nimport {getGuestChatViaFromId, getMid, isMessage, isMessageForVerificationBot} from '@components/chat/utils';\nimport {canHaveSuggestedPostReplyMarkup} from '@components/chat/bubbleParts/suggestedPostReplyMarkup';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport type {BubbleElementAddons} from '@components/chat/types';\nimport {AdminLog} from '@appManagers/appChatsManager';\nimport isEphemeralMessage from '@appManagers/utils/messages/isEphemeralMessage';\nimport compareBubbleTimelineMessages from '@components/chat/compareBubbleTimelineMessages';\nimport filterReplyMarkupRows from '@components/chat/bubbleParts/filterReplyMarkupRows';\nimport updateChatThreadSeparators from '@components/chat/bubbleParts/updateChatThreadSeparators';\n\n\ntype GroupItem = {\n  bubble: HTMLElement,\n  fromId: PeerId,\n  mid: number,\n  groupMid?: number,\n  timestamp: number,\n  dateTimestamp: number,\n  mounted: boolean,\n  single: boolean,\n  group?: BubbleGroup,\n  message: Message.message | Message.messageService | AdminLog, // use it only to set avatar\n  reverse?: boolean\n};\n\nfunction insertSomething<T>(\n  to: Array<T>,\n  what: T,\n  sortKey: keyof T,\n  reverse: boolean,\n  compare?: (item1: T, item2: T) => number\n) {\n  if(!sortKey) {\n    indexOfAndSplice(to, what);\n    return (reverse ? to.push(what) : to.unshift(what)) - 1;\n  } else if(compare) {\n    indexOfAndSplice(to, what);\n\n    let left = 0;\n    let right = to.length;\n    while(left < right) {\n      const middle = (left + right) >> 1;\n      if(compare(what, to[middle]) > 0) {\n        right = middle;\n      } else {\n        left = middle + 1;\n      }\n    }\n\n    to.splice(left, 0, what);\n    return left;\n  } else {\n    // @ts-ignore\n    return insertInDescendSortedArray(to, what, sortKey);\n  }\n}\n\nfunction compareTimelineItems(item1: GroupItem, item2: GroupItem) {\n  return compareBubbleTimelineMessages(item1.message, item2.message);\n}\n\nfunction getReplyMarkupRows(message: Message.message) {\n  const replyMarkup = message.reply_markup;\n  return replyMarkup?._ === 'replyInlineMarkup' ? filterReplyMarkupRows(replyMarkup.rows) : [];\n}\n\nexport class BubbleGroup {\n  container: HTMLElement;\n  chat: Chat;\n  groups: BubbleGroups;\n  items: GroupItem[]; // descend sorted\n  avatarContainer: HTMLElement;\n  avatarLoadPromise: Promise<void>;\n  avatar: ReturnType<typeof avatarNew>;\n  mounted: boolean;\n  dateTimestamp: number;\n  offset: number;\n  middlewareHelper: MiddlewareHelper;\n  dateContainer: ReturnType<ChatBubbles['getDateContainerByTimestamp']>;\n\n  constructor(chat: Chat, groups?: BubbleGroups, dateTimestamp?: number) {\n    this.container = document.createElement('div');\n    this.container.classList.add('bubbles-group');\n    this.chat = chat;\n    this.groups = groups;\n    this.items = [];\n    this.dateTimestamp = dateTimestamp;\n    this.offset = 0;\n    this.middlewareHelper = chat.bubbles.getMiddleware().create();\n  }\n\n  getAvatarOptions(message: Message.message | AdminLog) {\n    const fwdFrom = isMessage(message) ? message.fwd_from : undefined;\n    const fwdFromId = isMessage(message) ? message.fwdFromId : undefined;\n    const fwdFromName = getFwdFromName(fwdFrom);\n    const isForwardFromChannel = isMessage(message) && message.from_id && message.from_id._ === 'peerChannel' && message.fromId === fwdFromId;\n    const currentPeerId = this.chat.peerId;\n\n    const getPeerIdForLog = (log: AdminLog) => {\n      const entry = this.chat.bubbles.resolveAdminLogUnsafe({log, noJsx: true});\n\n      if(entry?.type === 'default') {\n        if(entry.message._ === 'message') return getPeerId(\n          entry.message.from_id ||\n          entry.message.peer_id\n        );\n      }\n\n      return log?.user_id?.toPeerId();\n    };\n\n    const peerId =\n      (\n        isMessage(message) ?\n          ((fwdFrom && (/* currentPeerId === rootScope.myId ||  */currentPeerId === REPLIES_PEER_ID || currentPeerId === VERIFICATION_CODES_BOT_ID) && !fwdFromName) || isForwardFromChannel ? fwdFromId : message.fromId) :\n          getPeerIdForLog(message)\n      ) ||\n      NULL_PEER_ID;\n\n    return {\n      // peerId: fwdFromName ? NULL_PEER_ID : peerId,\n      peerId,\n      // peerTitle: !fwdFromId && fwdFrom && fwdFromName && peerId === NULL_PEER_ID ? /* '🔥 FF 🔥' */fwdFromName : undefined\n      peerTitle: peerId === NULL_PEER_ID ? fwdFromName : undefined\n    };\n  }\n\n  destroyAvatar() {\n    if(!this.avatar) {\n      return;\n    }\n\n    this.avatarContainer.remove();\n    this.avatarLoadPromise = this.avatar = this.avatarContainer = undefined;\n    --this.offset;\n  }\n\n  createAvatar(message: Message.message | Message.messageService | AdminLog, options?: Partial<Parameters<typeof avatarNew>[0]>) {\n    if(this.avatarLoadPromise) {\n      return this.avatarLoadPromise;\n    } else if(message._ === 'messageService') {\n      return;\n    }\n\n    this.avatarContainer = document.createElement('div');\n    this.avatarContainer.classList.add('bubbles-group-avatar-container');\n    ++this.offset;\n\n    this.avatar = avatarNew({\n      middleware: this.middlewareHelper.get(),\n      size: 40,\n      lazyLoadQueue: this.chat.bubbles.lazyLoadQueue,\n      ...(options || this.getAvatarOptions(message))\n    });\n    this.avatar.node.classList.add('bubbles-group-avatar', 'user-avatar'/* , 'can-zoom-fade' */);\n\n    this.updateAvatarClassNames(message);\n\n    // this.avatarLoadPromise = Promise.all([\n    //   avatarLoadPromise,\n    //   peerId && peerId.isUser() ? this.chat.managers.appUsersManager.getUser(peerId.toUserId()) : undefined\n    // ]).then(([result, user]) => {\n    //   if(user?.pFlags?.premium) {\n    //     avatar.classList.add('is-premium', 'tgico-star');\n    //   }\n\n    //   return result;\n    // });\n    this.avatarLoadPromise = this.avatar.readyThumbPromise;\n\n    this.avatarContainer.append(this.avatar.node);\n    this.container.append(this.avatarContainer);\n\n    return this.avatarLoadPromise;\n  }\n\n  updateAvatarClassNames(message = this.lastItem.message) {\n    if(!this.avatar || message?._ !== 'message') {\n      return;\n    }\n\n    const replyMarkupRows = getReplyMarkupRows(message);\n    this.avatarContainer.classList.toggle('avatar-for-reply-markup', !!replyMarkupRows.length);\n    if(replyMarkupRows.length) {\n      this.avatarContainer.style.setProperty('--reply-markup-row-count', replyMarkupRows.length.toString());\n    } else {\n      this.avatarContainer.style.removeProperty('--reply-markup-row-count');\n    }\n\n    this.avatar.node.classList.toggle('avatar-for-suggested-reply-markup', canHaveSuggestedPostReplyMarkup(message));\n  }\n\n  get firstTimestamp() {\n    return this.firstItem.timestamp;\n  }\n\n  get firstMid() {\n    return this.firstItem.mid;\n  }\n\n  get firstItem() {\n    return this.items[this.items.length - 1];\n  }\n\n  get lastTimestamp() {\n    return this.lastItem.timestamp;\n  }\n\n  get lastMid() {\n    return this.lastItem.mid;\n  }\n\n  get lastItem() {\n    return this.items[0];\n  }\n\n  updateClassNames() {\n    const items = this.items;\n    const length = items.length;\n    if(!length) {\n      return;\n    }\n\n    // const elements = Array.from(this.container.children);\n    // if(this.offset) elements.splice(0, this.offset);\n\n    // const length = elements.length;\n    // if(!length) {\n    //   return;\n    // }\n\n    const first = items[length - 1].bubble;\n\n    this.updateAvatarClassNames();\n\n    if(items.length === 1) {\n      first.classList.add('is-group-first', 'is-group-last');\n      // this.setClipIfNeeded(first);\n      return;\n    } else {\n      first.classList.remove('is-group-last');\n      first.classList.add('is-group-first');\n      // this.setClipIfNeeded(first, true);\n    }\n\n    for(let i = 1, _length = length - 1; i < _length; ++i) {\n      const bubble = items[i].bubble;\n      bubble.classList.remove('is-group-last', 'is-group-first');\n      // this.setClipIfNeeded(bubble, true);\n    }\n\n    const last = items[0].bubble;\n    last.classList.remove('is-group-first');\n    last.classList.add('is-group-last');\n    // this.setClipIfNeeded(last);\n  }\n\n  insertItem(item: GroupItem) {\n    const {items} = this;\n    insertSomething(\n      items,\n      item,\n      this.groups.sortGroupItemsKey,\n      this.groups.reverse = item.reverse,\n      this.groups.compareGroupItems\n    );\n\n    item.group = this;\n    if(items.length === 1) {\n      this.groups.insertGroup(this);\n    }\n  }\n\n  removeItem(item: GroupItem) {\n    indexOfAndSplice(this.items, item);\n\n    if(!this.items.length) {\n      indexOfAndSplice(this.groups.groups, this);\n    }\n\n    item.group = undefined;\n  }\n\n  mount(updateClassNames?: boolean) {\n    if(!this.groups.groups.includes(this) || !this.items.length) { // group can be already removed\n      debugger;\n\n      if(this.mounted) {\n        this.onItemUnmount();\n      }\n\n      return;\n    }\n\n    const {offset, items} = this;\n    const {length} = items;\n    forEachReverse(items, (item, idx) => {\n      this.mountItem(item, length - 1 - idx, offset);\n    });\n\n    if(updateClassNames) {\n      this.updateClassNames();\n    }\n\n    this.onItemMount();\n  }\n\n  mountItem(item: GroupItem, idx = this.items.indexOf(item), offset = this.offset) {\n    if(item.mounted) {\n      return;\n    }\n\n    positionElementByIndex(item.bubble, this.container, offset + idx);\n    item.mounted = true;\n  }\n\n  unmountItem(item: GroupItem) {\n    if(!item.mounted) {\n      return;\n    }\n\n    item.bubble.remove();\n    item.mounted = false;\n    this.onItemUnmount();\n  }\n\n  onItemMount() {\n    if(this.mounted) {\n      return;\n    }\n\n    const dateContainer = this.dateContainer = this.chat.bubbles.getDateContainerByTimestamp(this.dateTimestamp / 1000);\n    // const idx = this.groups.indexOf(group);\n    const dateGroups = this.groups.groups.filter((_group) => _group.dateTimestamp === this.dateTimestamp);\n    const dateGroupsLength = dateGroups.length;\n    const idx = dateGroups.indexOf(this);\n    const unmountedLength = dateGroups.slice(idx + 1).reduce((acc, v) => acc + (v.mounted ? 0 : 1), 0);\n    positionElementByIndex(this.container, dateContainer.container, STICKY_OFFSET + dateGroupsLength - 1 - idx - unmountedLength);\n    ++dateContainer.groupsLength;\n    this.mounted = true;\n    this.groups?.updateGroupsClassNames();\n  }\n\n  onItemUnmount() {\n    if(!this.mounted) {\n      return;\n    }\n\n    if(!this.items.length) {\n      this.container.remove();\n      this.dateContainer && --this.dateContainer.groupsLength;\n      this.dateContainer = undefined;\n      this.chat.bubbles.deleteEmptyDateGroups();\n      this.mounted = false;\n      this.middlewareHelper.clean();\n      this.groups?.updateGroupsClassNames();\n    } else {\n      this.updateClassNames();\n    }\n  }\n}\n\n// class BubbleGroupItem implements GroupItem {\n//   bubble: HTMLElement;\n//   fromId: PeerId;\n//   mid: number;\n//   timestamp: number;\n//   dateTimestamp: number;\n//   mounted: boolean;\n//   single: boolean;\n//   group: BubbleGroup;\n\n//   constructor(details: GroupItem) {\n//     Object.assign(this, details);\n//   }\n// }\n\nexport default class BubbleGroups {\n  public itemsArr: Array<GroupItem> = []; // descend sorted\n  private itemsMap: Map<HTMLElement, GroupItem> = new Map();\n  public groups: Array<BubbleGroup> = []; // descend sorted\n  private newGroupDiff = 121; // * 121 in scheduled messages\n  private sortItemsKey: Extract<keyof GroupItem, 'timestamp' | 'mid'>;\n  private sortGroupsKey: Extract<keyof BubbleGroup, 'lastMid' | 'lastTimestamp'>;\n  public sortGroupItemsKey: Extract<keyof GroupItem, 'groupMid' | 'timestamp'>;\n  public compareGroupItems?: typeof compareTimelineItems;\n  private compareItems?: typeof compareTimelineItems;\n  private compareGroups?: (group1: BubbleGroup, group2: BubbleGroup) => number;\n  public reverse: boolean; // * used for search\n\n  constructor(private chat: Chat) {\n    if(chat.type !== ChatType.Search) {\n      this.sortItemsKey = chat.type === ChatType.Scheduled ? 'timestamp' : 'mid';\n      this.sortGroupsKey = chat.type === ChatType.Scheduled ? 'lastTimestamp' : 'lastMid';\n      this.sortGroupItemsKey = /* chat.type === 'scheduled' ? 'timestamp' :  */'groupMid';\n\n      if(chat.type === ChatType.Chat || chat.type === ChatType.Discussion) {\n        this.compareItems = this.compareGroupItems = compareTimelineItems;\n        this.compareGroups = (group1, group2) => compareTimelineItems(group1.lastItem, group2.lastItem);\n      }\n    }\n  }\n\n  removeItem(item: GroupItem) {\n    item.group?.removeItem(item);\n    this.removeItemFromCache(item);\n  }\n\n  removeAndUnmountBubble(bubble: HTMLElement) {\n    const item = this.getItemByBubble(bubble);\n    if(!item) { // * can be a placeholder\n      const parentElement = bubble.parentElement;\n      if(parentElement) {\n        if(parentElement.classList.contains('bubbles-group')) {\n          parentElement.remove();\n        } else {\n          bubble.remove();\n        }\n      }\n\n      return false;\n    }\n\n    const items = this.itemsArr;\n    const index = items.indexOf(item);\n    const siblings = this.getSiblingsAtIndex(index, items);\n\n    const group = item.group;\n    this.removeItem(item);\n\n    const modifiedGroups: Set<BubbleGroup> = new Set();\n    if(group) {\n      group.unmountItem(item);\n      modifiedGroups.add(group);\n    }\n\n    const [previousSibling, nextSibling] = siblings;\n    if(\n      previousSibling &&\n      nextSibling &&\n      this.canItemsBeGrouped(previousSibling, nextSibling) &&\n      previousSibling.group !== nextSibling.group\n    ) {\n      const group = nextSibling.group;\n      this.f(nextSibling.group.items);\n      group.onItemUnmount();\n      modifiedGroups.add(previousSibling.group);\n      this.groupUngrouped();\n    }\n\n    this.mountUnmountGroups(Array.from(modifiedGroups));\n\n    return true;\n  }\n\n  mountUnmountGroups(groups: BubbleGroup[]) {\n    // groups.sort((a, b) => (b.lastItem?.mid ?? 0) - (a.lastItem?.mid ?? 0));\n\n    const [toMount, toUnmount] = partition(groups, (group) => !!group.items.length);\n    toUnmount.forEach((group) => {\n      group.onItemUnmount();\n    })\n\n    toMount.forEach((group) => {\n      group.mount(true);\n    });\n\n    this.addChatThreadSeparators();\n    this.addContinueLastTopicReplyMarkup();\n  }\n\n  private addChatThreadSeparators() {\n    updateChatThreadSeparators(this.itemsArr, this.chat);\n  }\n\n  /**\n   * Makes the reply markup of the last message bubble visible\n   */\n  private addContinueLastTopicReplyMarkup() {\n    if(!this.chat.isBotforum) return;\n\n    let visible = true;\n\n    this.itemsArr.forEach((item) => {\n      const bubbleAddons = item.bubble as BubbleElementAddons;\n\n      if(item.message._ !== 'message') return;\n      if(!bubbleAddons.continueLastTopicReplyMarkup) return;\n      if(!getMessageThreadId(item.message, {isBotforum: this.chat.isBotforum})) return;\n\n      bubbleAddons.continueLastTopicReplyMarkup.feedProps<false>({\n        visible: visible && !(item.message.reply_markup as ReplyMarkup.replyInlineMarkup)?.rows\n      });\n\n      visible = false;\n    });\n  }\n\n  f(items: GroupItem[], index: number = 0, length = items.length) {\n    for(; index < length; ++index) {\n      const item = items[index];\n      item.mounted = false;\n      item.group.removeItem(item);\n      --length;\n      --index;\n    }\n  }\n\n  getItemByBubble(bubble: HTMLElement) {\n    return this.itemsMap.get(bubble);\n  }\n\n  get firstGroup() {\n    return this.groups[this.groups.length - 1];\n  }\n\n  get lastGroup() {\n    return this.groups[0];\n  }\n\n  changeBubbleMessage(bubble: HTMLElement, message: GroupItem['message']) {\n    const item = this.getItemByBubble(bubble);\n    if(!item) {\n      return;\n    }\n\n    item.mid = /* item.groupMid =  */getMid(message);\n    item.message = message;\n    item.groupMid = this.generateGroupMid(message, item.dateTimestamp);\n\n    // indexOfAndSplice(item.group.items, item);\n    // // const canChangeGroupMid = !item.group.items.length || item.group.items.every((item) => item.groupMid === item.mid);\n    // // if(canChangeGroupMid) item.groupMid = mid;\n    // item.group.insertItem(item);\n\n    indexOfAndSplice(this.itemsArr, item);\n    this.insertItemToArray(item, this.itemsArr);\n  }\n\n  changeItemBubble(item: GroupItem, bubble: HTMLElement) {\n    this.itemsMap.delete(item.bubble);\n    item.bubble = bubble;\n    this.itemsMap.set(bubble, item);\n  }\n\n  changeBubbleByBubble(from: HTMLElement, to: HTMLElement) {\n    const item = this.getItemByBubble(from);\n    if(!item) {\n      return;\n    }\n\n    this.changeItemBubble(item, to);\n  }\n\n  canItemsBeGrouped(item1: GroupItem, item2: GroupItem) {\n    if(item1.message?._ === 'channelAdminLogEvent' || item2.message?._ === 'channelAdminLogEvent') return false;\n\n    if(isMessageForVerificationBot(item1.message)) return false;\n\n    if(isEphemeralMessage(item1.message) !== isEphemeralMessage(item2.message)) return false;\n\n    if(\n      item1.message?._ === 'message' && item1.message?.suggested_post ||\n      item2.message?._ === 'message' && item2.message?.suggested_post\n    ) return false;\n\n    const isOut1 = this.chat.isOutMessage(item1.message);\n    return item2.fromId === item1.fromId &&\n      // * keep guest-chat messages from different visitors in separate groups (own avatar + \"for <visitor>\")\n      getGuestChatViaFromId(item1.message) === getGuestChatViaFromId(item2.message) &&\n      item1.dateTimestamp === item2.dateTimestamp &&\n      Math.abs(item2.timestamp - item1.timestamp) <= this.newGroupDiff &&\n      !item1.single &&\n      !item2.single &&\n      isOut1 === this.chat.isOutMessage(item2.message) &&\n      (!this.chat.isAllMessagesForum || getMessageThreadId(item1.message, {isForum: true}) === getMessageThreadId(item2.message, {isForum: true})) &&\n      (!this.chat.isBotforum || getMessageThreadId(item1.message, {isBotforum: true}) === getMessageThreadId(item2.message, {isBotforum: true})) &&\n      (!this.chat.isMonoforum || getMessageThreadId(item1.message) === getMessageThreadId(item2.message)) &&\n      (!isOut1 || item1.message.fromId === rootScope.myId || this.chat.isMonoforum) && // * group anonymous sending\n      item1.message.peerId === item2.message.peerId &&\n      (item1.message as Message.message).post_author === (item2.message as Message.message).post_author;\n  }\n\n  getSiblingsAtIndex(itemIndex: number, items: GroupItem[]) {\n    return [items[itemIndex - 1], items[itemIndex + 1]] as const;\n  }\n\n  // findGroupSiblingInSiblings(item: GroupItem, siblings: ReturnType<BubbleGroups['getSiblingsAtIndex']>) {\n  //   return siblings.find((sibling) => sibling && this.canItemsBeGrouped(item, sibling));\n  // }\n\n  findGroupSiblingByItem(item: GroupItem, items: GroupItem[]) {\n    items = items.slice();\n    const idx = this.insertItemToArray(item, items);\n    // return this.findGroupSiblingInSiblings(item, this.getSiblingsAtIndex(idx, items));\n    return this.findGroupSiblingInItems(item, items, idx);\n  }\n\n  findGroupSiblingInItems(item: GroupItem, items: GroupItem[], index = items.indexOf(item), length = items.length) {\n    const previousItem = items[index - 1];\n    let siblingGroupedItem: GroupItem;\n    if(previousItem?.group && this.canItemsBeGrouped(item, previousItem)) {\n      siblingGroupedItem = previousItem;\n    } else {\n      for(let k = index + 1; k < length; ++k) {\n        const nextItem = items[k];\n        if(this.canItemsBeGrouped(item, nextItem)) {\n          if(nextItem.group) {\n            siblingGroupedItem = nextItem;\n          }\n        } else {\n          break;\n        }\n      }\n    }\n\n    return siblingGroupedItem;\n  }\n\n  addItemToGroup(item: GroupItem, group: BubbleGroup) {\n    group.insertItem(item);\n    this.addItemToCache(item);\n  }\n\n  insertItemToArray(item: GroupItem, array: GroupItem[]) {\n    return insertSomething(\n      array,\n      item,\n      this.sortItemsKey,\n      this.reverse = item.reverse,\n      this.compareItems\n    );\n  }\n\n  insertGroup(group: BubbleGroup) {\n    const idx = insertSomething(\n      this.groups,\n      group,\n      this.sortGroupsKey,\n      this.reverse,\n      this.compareGroups\n    );\n    // this.updateGroupsClassNames();\n    return idx;\n  }\n\n  updateGroupsClassNames() {\n    this.groups.forEach((group, idx, arr) => {\n      group.container.classList.toggle('bubbles-group-last', idx === 0);\n      group.container.classList.toggle('bubbles-group-first', idx === (arr.length - 1));\n    });\n  }\n\n  addItemToCache(item: GroupItem) {\n    this.insertItemToArray(item, this.itemsArr);\n    this.itemsMap.set(item.bubble, item);\n  }\n\n  removeItemFromCache(item: GroupItem) {\n    indexOfAndSplice(this.itemsArr, item);\n    this.itemsMap.delete(item.bubble);\n  }\n\n  getMessageFromId(message: MyMessage | AdminLog) {\n    if(message._ === 'channelAdminLogEvent') {\n      return this.chat.peerId;\n    }\n\n    let fromId = /* (this.chat.peerId.isAnyChat() && message.viaBotId) ||  */message.fromId;\n\n    // fix for saved messages forward to self\n    if(fromId === rootScope.myId && message.peerId === rootScope.myId && (message as Message.message).fwdFromId === fromId) {\n      fromId = fromId.toPeerId(true);\n    }\n\n    return fromId;\n  }\n\n  generateGroupMid(message: MyMessage | AdminLog, dateTimestamp: number) {\n    const {date: timestamp} = message;\n    const mid = getMid(message);\n    return this.chat.type === ChatType.Scheduled ? +`${(timestamp * 1000 - dateTimestamp) / 1000}.${+('' + mid).replace('.', '')}` : mid;\n  }\n\n  createItem(bubble: HTMLElement, message: MyMessage | AdminLog, reverse: boolean) {\n    const single = !(message._ === 'message' || (message._ === 'messageService' && message.action && SERVICE_AS_REGULAR.has(message.action._)));\n    const {date: timestamp} = message;\n    const mid = getMid(message);\n    const {dateTimestamp} = this.chat.bubbles.getDateForDateContainer(timestamp);\n    const item: GroupItem = {\n      mid,\n      groupMid: this.generateGroupMid(message, dateTimestamp),\n      fromId: this.getMessageFromId(message),\n      bubble,\n      // timestamp: this.chat.type === 'scheduled' ? +`${(timestamp * 1000 - dateTimestamp) / 1000}.${mid}` : timestamp,\n      timestamp,\n      dateTimestamp,\n      mounted: false,\n      single,\n      message,\n      reverse\n    };\n\n    return item;\n  }\n\n  splitSiblingsOnGrouping(siblings: ReturnType<BubbleGroups['getSiblingsAtIndex']>) {\n    const [previousSibling, nextSibling] = siblings;\n    const previousGroup = previousSibling?.group;\n    const nextGroup = nextSibling?.group;\n\n    if(!previousGroup) {\n      return;\n    }\n\n    // will refresh group\n    // if(previousGroup === nextGroup) {\n    const items = previousGroup.items;\n    const index = items.indexOf(previousSibling) + 1;\n    const length = items.length;\n    if(index === length) {\n      return;\n    }\n\n    const modifiedGroups: BubbleGroup[] = [previousGroup];\n    // if(previousGroup !== nextGroup && nextGroup) {\n    //   modifiedGroups.push(nextGroup);\n    // }\n\n    this.f(items, index, length);\n    return modifiedGroups;\n    // }\n  }\n\n  prepareForGrouping(bubble: HTMLElement, message: MyMessage | AdminLog, reverse: boolean) {\n    const foundItem = this.getItemByBubble(bubble);\n    if(foundItem) { // should happen only on edit\n      // debugger;\n      return;\n    }\n\n    const item = this.createItem(bubble, message, reverse);\n    this.addItemToCache(item);\n  }\n\n  groupUngrouped() {\n    const items = this.itemsArr;\n    const length = items.length;\n    const modifiedGroups: Set<BubbleGroup> = new Set();\n    // for(let i = length - 1; i >= 0; --i) {\n    for(let i = 0; i < length; ++i) {\n      const item = items[i];\n      if(item.group) {\n        continue;\n      }\n\n      let hadGroup = true;\n      const siblings = this.getSiblingsAtIndex(i, items);\n      const siblingGroupedItem = this.findGroupSiblingInItems(item, items, i, length);\n\n      // const foundItem = this.findGroupSiblingInSiblings(item, siblings);\n      const foundItem = siblingGroupedItem;\n      const group = foundItem?.group ?? (hadGroup = false, new BubbleGroup(this.chat, this, item.dateTimestamp));\n\n      modifiedGroups.add(group);\n      group.insertItem(item);\n\n      if(!hadGroup) {\n        const splittedGroups = this.splitSiblingsOnGrouping(siblings);\n        if(splittedGroups) {\n          splittedGroups.forEach((group) => modifiedGroups.add(group));\n        }\n      }\n    }\n\n    return modifiedGroups;\n  }\n\n  // addBubble(bubble: HTMLElement, message: MyMessage, unmountIfFound?: boolean) {\n  //   const oldItem = this.getItemByBubble(bubble);\n  //   if(unmountIfFound) { // updating position\n  //     this.removeAndUnmountBubble(bubble);\n  //   } else if(oldItem) { // editing\n  //     const group = oldItem.group;\n  //     this.changeItemBubble(oldItem, bubble);\n  //     oldItem.mounted = false;\n\n  //     return {item: oldItem, group};\n  //   }\n\n  //   const item = this.createItem(bubble, message);\n\n  //   const foundItem = this.findSameGroupItem(item, this.itemsArr);\n\n  //   const group = foundItem?.group ?? new BubbleGroup(this.chat, this, item.dateTimestamp);\n  //   this.addItemToGroup(item, group);\n\n  //   return {item, group};\n  // }\n\n  /* setClipIfNeeded(bubble: HTMLDivElement, remove = false) {\n    //console.log('setClipIfNeeded', bubble, remove);\n    const className = bubble.className;\n    if(className.includes('is-message-empty') && (className.includes('photo') || className.includes('video'))) {\n      let container = bubble.querySelector('.bubble__media-container') as SVGSVGElement;\n      //console.log('setClipIfNeeded', bubble, remove, container);\n      if(!container) return;\n\n      try {\n        Array.from(container.children).forEach((object) => {\n          if(object instanceof SVGDefsElement) return;\n\n          if(remove) {\n            object.removeAttributeNS(null, 'clip-path');\n          } else {\n            let clipId = container.dataset.clipId;\n            let path = container.firstElementChild.firstElementChild.lastElementChild as SVGPathElement;\n            let width = +object.getAttributeNS(null, 'width');\n            let height = +object.getAttributeNS(null, 'height');\n            let isOut = className.includes('is-out');\n            let isReply = className.includes('is-reply');\n            let d = '';\n\n            //console.log('setClipIfNeeded', object, width, height, isOut);\n\n            let tr: number, tl: number;\n            if(className.includes('forwarded') || isReply) {\n              tr = tl = 0;\n            } else if(isOut) {\n              tr = className.includes('is-group-first') ? 12 : 6;\n              tl = 12;\n            } else {\n              tr = 12;\n              tl = className.includes('is-group-first') ? 12 : 6;\n            }\n\n            if(isOut) {\n              d = generatePathData(0, 0, width - 9, height, tl, tr, 0, 12);\n            } else {\n              d = generatePathData(9, 0, width - 9, height, tl, tr, 12, 0);\n            }\n\n            path.setAttributeNS(null, 'd', d);\n            object.setAttributeNS(null, 'clip-path', 'url(#' + clipId + ')');\n          }\n        });\n      } catch(err) {}\n    }\n  } */\n\n  // updateGroupByMessageId(mid: number) {\n  //   const item = this.itemsArr.find((g) => g.mid === mid);\n  //   if(item) {\n  //     item.group.updateGroup();\n  //   }\n  // }\n\n  cleanup() {\n    this.itemsArr = [];\n    this.groups = [];\n    this.itemsMap.clear();\n  }\n\n  // findIncorrentPositions() {\n  //   var bubbles = Array.from(this.chat.bubbles.chatInner.querySelectorAll('.bubbles-group .bubble')).reverse();\n  //   var items = this.itemsArr;\n  //   for(var i = 0, length = items.length; i < length; ++i) {\n  //     const item = items[i];\n  //     const foundBubble = bubbles[i];\n  //     if(item.bubble !== foundBubble) {\n  //       console.log('incorrect position', i, item, foundBubble);\n  //       // debugger;\n  //       // break;\n  //     }\n  //   }\n  // }\n}\n","import {SEND_WHEN_ONLINE_TIMESTAMP} from '@appManagers/constants';\nimport {formatDate} from '@helpers/date';\nimport {i18n} from '@lib/langPack';\n\nexport default function createDateBubble(\n  timestamp: number,\n  date: Date = new Date(timestamp * 1000),\n  isScheduled = false\n) {\n  const today = new Date();\n  today.setHours(0, 0, 0, 0);\n\n  let dateElement: HTMLElement;\n  if(today.getTime() === date.getTime()) {\n    dateElement = i18n(isScheduled ? 'Chat.Date.ScheduledForToday' : 'Date.Today');\n  } else if(isScheduled && timestamp === SEND_WHEN_ONLINE_TIMESTAMP) {\n    dateElement = i18n('MessageScheduledUntilOnline');\n  } else {\n    dateElement = formatDate(date, {today});\n\n    if(isScheduled) {\n      dateElement = i18n('Chat.Date.ScheduledFor', [dateElement]);\n    }\n  }\n\n  const bubble = document.createElement('div');\n  bubble.className = 'bubble service is-date';\n  const bubbleContent = document.createElement('div');\n  bubbleContent.classList.add('bubble-content');\n  const serviceMsg = document.createElement('div');\n  serviceMsg.classList.add('service-msg');\n\n  serviceMsg.append(dateElement);\n  bubbleContent.append(serviceMsg);\n  bubble.append(bubbleContent);\n\n  return bubble;\n}\n","/**\n * Throttles an asynchronous function by caching its result for a specified duration.\n *\n * If the same arguments (as determined by `getKeyFromArgs`) are passed in again within `timeoutMs`,\n * the cached Promise result is returned instead of re-invoking the function.\n * After `timeoutMs` milliseconds, the cache entry is invalidated automatically.\n *\n * @param callback - The async function to throttle.\n * @param getKeyFromArgs - A function that extracts a unique cache key from the function arguments.\n * @param timeoutMs - The time in milliseconds to cache the result before invalidation.\n * @returns A throttled version of the async function.\n */\nexport default function memoizeAsyncWithTTL<Callback extends(...args: any[]) => Promise<any>>(\n  callback: Callback,\n  getKeyFromArgs: (args: Parameters<Callback>) => any,\n  timeoutMs: number\n) {\n  type Args = Parameters<Callback>;\n\n  const cachedResultsMap = new Map<any, ReturnType<Callback>>;\n\n  return (...args: Args) => {\n    const key = getKeyFromArgs(args);\n    if(cachedResultsMap.has(key)) return cachedResultsMap.get(key);\n\n    const promise = callback(...args).finally(() => {\n      self.setTimeout(() => {\n        cachedResultsMap.delete(key);\n      }, timeoutMs);\n    }) as ReturnType<Callback>;\n\n    cachedResultsMap.set(key, promise);\n\n    return promise;\n  };\n}\n","export default function reflowScrollableElement(element: HTMLElement) {\n  element.style.display = 'none';\n  void element.offsetLeft; // reflow\n  element.style.display = '';\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n// CSS Custom Highlight API (`CSS.highlights` + `::highlight()`): paints arbitrary DOM ranges\n// without touching the DOM. Chrome 105+, Safari 17.2+, Firefox 140+. Where it is missing the\n// text highlighting (search matches, quotes) is simply not shown.\nconst IS_TEXT_HIGHLIGHT_SUPPORTED = typeof CSS !== 'undefined' &&\n  'highlights' in CSS &&\n  typeof Highlight === 'function';\n\nexport default IS_TEXT_HIGHLIGHT_SUPPORTED;\n","// credits to https://github.com/sindresorhus/escape-string-regexp/blob/master/index.js\nexport default function escapeRegExp(str: string) {\n  return str\n  .replace(/[|\\\\{}()[\\]^$+*?.]/g, '\\\\$&')\n  .replace(/-/g, '\\\\x2d');\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2021 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n/**\n * Text highlighting for arbitrary rendered DOM — search matches in bubbles and chat-list rows,\n * the quoted part of a replied-to message, …\n *\n * The matched text is described by live `Range`s over the container's text nodes, so entities,\n * custom emoji, spoilers, code blocks and translations stay untouched and a match that wraps\n * over several lines is still a single range. Two ways to paint them:\n *\n * - default: the CSS Custom Highlight API — ranges registered under a global `Highlight`\n *   (`CSS.highlights`) and styled by `::highlight(<name>)` rules (see\n *   `scss/partials/_textHighlight.scss`). Nothing is inserted into the DOM, but browsers paint\n *   only glyph-high boxes, which leaves gaps between wrapped lines;\n * - `lineBoxes`: an absolutely positioned overlay inside the container with one box per line,\n *   stretched to the full line height — a contiguous block like a text selection. Needs a\n *   positioned container that paints its background below its text.\n *\n * A highlight re-finds its text whenever the container mutates (translation swap, re-render …)\n * or is re-laid out, and is dropped automatically once its container has left the document for\n * good, so callers that cannot easily track the lifetime of their element do not have to.\n */\n\nimport IS_TEXT_HIGHLIGHT_SUPPORTED from '@environment/textHighlightSupport';\nimport {animateValue} from '@helpers/animateValue';\nimport liteMode from '@helpers/liteMode';\nimport throttleWithRaf from '@helpers/schedulers/throttleWithRaf';\nimport escapeRegExp from '@helpers/string/escapeRegExp';\n\nexport type TextHighlightMatch = {\n  /** server-search-like: case-insensitive, every query word matched at a word start */\n  type: 'search',\n  query: string\n} | {\n  /** exact text (a reply quote), the occurrence closest to `offset` wins */\n  type: 'quote',\n  text: string,\n  offset?: number\n};\n\nexport type TextHighlightOptions = {\n  container: HTMLElement,\n  match: TextHighlightMatch,\n  /** selector of subtrees to leave alone (message time, reactions, …) */\n  skip?: string,\n  /** re-find the text when the container mutates (default: `true`) */\n  observe?: boolean,\n  /**\n   * Paint full line boxes through a DOM overlay prepended to `container` instead of the\n   * glyph-high `::highlight()` boxes. The container must be positioned (the overlay is\n   * `position: absolute` at `z-index: -1`, i.e. below the text and above the background of the\n   * nearest stacking context) — true for a bubble's `.message`.\n   */\n  lineBoxes?: boolean,\n  /**\n   * `lineBoxes` only — appear the way iOS does it: the whole text of the container is selected\n   * first, holds a moment, then the selection narrows down to the match. Skipped when\n   * animations are off.\n   */\n  animateIn?: boolean\n};\n\n/** a painted line box, relative to the overlay's origin */\nexport type TextLineBox = {\n  left: number,\n  top: number,\n  width: number,\n  height: number\n};\n\nexport interface TextHighlight {\n  /** whether the last (re)application found anything to paint */\n  readonly found: boolean;\n  /** fade the highlight out and dispose it afterwards */\n  fadeOut(duration?: number): void;\n  dispose(): void;\n}\n\nexport type TextSpan = [start: number, end: number];\n\ntype TextSegment = {\n  node: Node,\n  start: number,\n  end: number,\n  /** an element standing for its text (emoji image, custom emoji): ranges snap around it */\n  atomic: boolean\n};\n\nconst HIGHLIGHT_NAMES: {[type in TextHighlightMatch['type']]: string} = {\n  search: 'tg-search',\n  quote: 'tg-quote'\n};\n\n// a quote must win over a search match painted in the same message\nconst HIGHLIGHT_PRIORITIES: {[type in TextHighlightMatch['type']]: number} = {\n  search: 1,\n  quote: 2\n};\n\n/** inherited by `::highlight()` / read by the overlay from the container, animated by `fadeOut` */\nconst OPACITY_PROPERTY = '--text-highlight-opacity';\nconst FADE_DURATION = 400;\n\nconst OVERLAY_CLASS = 'text-highlight-overlay';\nconst OVERLAY_BOX_CLASS = 'text-highlight-overlay-box';\n/** `animateIn` overlay states: the intro is on / the whole-text selection is still transparent / narrowing */\nconst OVERLAY_INTRO_CLASS = 'is-intro';\nconst OVERLAY_APPEARING_CLASS = 'is-appearing';\nconst OVERLAY_NARROWING_CLASS = 'is-narrowing';\n/** hairline gaps between consecutive line boxes (rounding, mixed inline heights) get closed */\nconst LINE_BOX_SNAP = 3;\n/** `animateIn`: the whole-text selection fades in (must match the transition in scss) … */\nconst NARROW_APPEAR = 200;\n/** … stays for this long … */\nconst NARROW_HOLD = 300;\n/** … then narrows down to the match over this long (must match the transition in scss) */\nconst NARROW_DURATION = 400;\n\n/** icons are text glyphs in a private-use range — never part of the searchable text */\nconst DEFAULT_SKIP = `.tgico, .${OVERLAY_CLASS}`;\n\nconst WORD_CHARACTER = '\\\\p{L}\\\\p{N}\\\\p{M}';\nconst WORD_START = `(?<![${WORD_CHARACTER}])`;\n\n/** collects the visible text of `root` together with the DOM positions it came from */\nexport function extractText(root: HTMLElement, skip = DEFAULT_SKIP) {\n  const segments: TextSegment[] = [];\n  let text = '';\n\n  const push = (node: Node, value: string, atomic: boolean) => {\n    if(!value) {\n      return;\n    }\n\n    segments.push({node, start: text.length, end: text.length + value.length, atomic});\n    text += value;\n  };\n\n  const visit = (node: Node) => {\n    if(node.nodeType === Node.TEXT_NODE) {\n      push(node, (node as Text).data, false);\n      return;\n    }\n\n    if(node.nodeType !== Node.ELEMENT_NODE) {\n      return;\n    }\n\n    const element = node as HTMLElement;\n    if(element.matches(skip)) {\n      return;\n    }\n\n    // * emoji images and custom emoji carry their text as `alt` / `data-sticker-emoji`\n    // * (same convention as `getRichElementValue`)\n    const alt = element.dataset.stickerEmoji || (element as HTMLImageElement).alt;\n    if(alt) {\n      push(element, alt, true);\n      return;\n    }\n\n    for(let child = node.firstChild; child; child = child.nextSibling) {\n      visit(child);\n    }\n  };\n\n  visit(root);\n  return {text, segments};\n}\n\nfunction execAll(regExp: RegExp, text: string) {\n  const spans: TextSpan[] = [];\n  let match: RegExpExecArray;\n  while((match = regExp.exec(text)) !== null) {\n    if(!match[0].length) { // * safety against zero-length loops\n      ++regExp.lastIndex;\n      continue;\n    }\n\n    spans.push([match.index, match.index + match[0].length]);\n  }\n\n  return spans;\n}\n\nfunction mergeSpans(spans: TextSpan[]) {\n  spans.sort((a, b) => a[0] - b[0]);\n  const merged: TextSpan[] = [];\n  for(const span of spans) {\n    const last = merged[merged.length - 1];\n    if(last && span[0] < last[1]) {\n      last[1] = Math.max(last[1], span[1]);\n    } else {\n      merged.push([span[0], span[1]]);\n    }\n  }\n\n  return merged;\n}\n\n/**\n * What the server search matched: the whole query as a phrase, otherwise every query word as\n * a word prefix (extended to the end of the word it starts, so \"hel\" lights up \"hello\"). Falls\n * back to shorter prefixes of a word — down to half of it — the way tdesktop does.\n */\nexport function findSearchSpans(text: string, query: string): TextSpan[] {\n  query = query.trim();\n  if(!query || !text) {\n    return [];\n  }\n\n  const phrase = execAll(new RegExp(`${WORD_START}${escapeRegExp(query)}(?![${WORD_CHARACTER}])`, 'giu'), text);\n  if(phrase.length) {\n    return mergeSpans(phrase);\n  }\n\n  const spans: TextSpan[] = [];\n  const words = query.split(new RegExp(`[^${WORD_CHARACTER}]+`, 'u')).filter(Boolean);\n  for(const word of words) {\n    const minLength = Math.ceil(word.length / 2);\n    for(let length = word.length; length >= minLength; --length) {\n      const prefix = escapeRegExp(word.slice(0, length));\n      const found = execAll(new RegExp(`${WORD_START}${prefix}[${WORD_CHARACTER}]*`, 'giu'), text);\n      if(found.length) {\n        spans.push(...found);\n        break;\n      }\n    }\n  }\n\n  return mergeSpans(spans);\n}\n\nfunction findNearest(text: string, needle: string, hint: number): TextSpan | undefined {\n  hint = Math.max(0, Math.min(hint, text.length));\n  const after = text.indexOf(needle, hint);\n  const before = text.lastIndexOf(needle, hint);\n  if(after === -1 && before === -1) {\n    return;\n  }\n\n  const start = after === -1 ? before :\n    before === -1 ? after :\n      (hint - before <= after - hint ? before : after);\n  return [start, start + needle.length];\n}\n\n/**\n * The quote is a verbatim slice of the message text, `offset` is where it started there. The\n * rendered text may differ slightly (dropped line breaks around block quotes, media captions\n * preceded by a file name …), hence the nearest occurrence to the offset and a\n * whitespace-insensitive retry.\n */\nexport function findQuoteSpan(text: string, quote: string, offset = 0): TextSpan | undefined {\n  if(!quote || !text) {\n    return;\n  }\n\n  const exact = findNearest(text, quote, offset);\n  if(exact) {\n    return exact;\n  }\n\n  const needle = quote.replace(/\\s+/g, '');\n  if(!needle) {\n    return;\n  }\n\n  // * strip all whitespace, remembering where every kept character came from\n  const map: number[] = [];\n  let stripped = '';\n  let strippedHint = 0;\n  for(let i = 0; i < text.length; ++i) {\n    if(i === offset) {\n      strippedHint = stripped.length;\n    }\n\n    if(!/\\s/.test(text[i])) {\n      map.push(i);\n      stripped += text[i];\n    }\n  }\n\n  if(offset >= text.length) {\n    strippedHint = stripped.length;\n  }\n\n  const found = findNearest(stripped, needle, strippedHint);\n  return found && [map[found[0]], map[found[1] - 1] + 1];\n}\n\nexport function findSpans(text: string, match: TextHighlightMatch): TextSpan[] {\n  if(match.type === 'search') {\n    return findSearchSpans(text, match.query);\n  }\n\n  const span = findQuoteSpan(text, match.text, match.offset);\n  return span ? [span] : [];\n}\n\n/** turns text spans into DOM ranges over the container's text */\nexport function computeRanges(container: HTMLElement, match: TextHighlightMatch, skip?: string) {\n  const {text, segments} = extractText(container, skip ? `${DEFAULT_SKIP}, ${skip}` : DEFAULT_SKIP);\n  const ranges: Range[] = [];\n  if(!segments.length) {\n    return ranges;\n  }\n\n  let index = 0;\n  for(const [start, end] of findSpans(text, match)) {\n    while(index < segments.length && segments[index].end <= start) {\n      ++index;\n    }\n\n    const startSegment = segments[index];\n    if(!startSegment) {\n      break;\n    }\n\n    let endIndex = index;\n    while(segments[endIndex].end < end && endIndex + 1 < segments.length) {\n      ++endIndex;\n    }\n\n    const endSegment = segments[endIndex];\n    const range = new Range();\n    if(startSegment.atomic) range.setStartBefore(startSegment.node);\n    else range.setStart(startSegment.node, start - startSegment.start);\n    if(endSegment.atomic) range.setEndAfter(endSegment.node);\n    else range.setEnd(endSegment.node, Math.min(end, endSegment.end) - endSegment.start);\n    ranges.push(range);\n  }\n\n  return ranges;\n}\n\n/**\n * Where the match sits on the screen right now, without painting anything: the rect of its\n * first occurrence (the whole of it, several lines included). For scrolling the text into\n * view before the highlight is applied to it.\n */\nexport function findTextRect(container: HTMLElement, match: TextHighlightMatch, skip?: string) {\n  const [range] = computeRanges(container, match, skip);\n  const rect = range?.getBoundingClientRect();\n  return rect?.height ? rect : undefined;\n}\n\n/**\n * Turns the ranges' fragment rects into per-line boxes stretched to the line height (glyph rects\n * are only font-high; the missing half-leading is added on both sides), unioned along a line\n * and expressed relative to `origin`.\n */\nexport function computeLineBoxes(ranges: Range[], origin: DOMRect, lineHeight: number): TextLineBox[] {\n  type Edges = {left: number, right: number, top: number, bottom: number};\n  const fragments: Edges[] = [];\n  for(const range of ranges) {\n    for(const rect of range.getClientRects()) {\n      if(!rect.width || !rect.height) { // * empty lines and collapsed points\n        continue;\n      }\n\n      const extra = Math.max(0, lineHeight - rect.height) / 2;\n      fragments.push({left: rect.left, right: rect.right, top: rect.top - extra, bottom: rect.bottom + extra});\n    }\n  }\n\n  fragments.sort((a, b) => (a.top - b.top) || (a.left - b.left));\n\n  // * same line = vertical overlap of at least half of the smaller one; on a line, fragments that\n  // * touch or overlap horizontally merge into one box (separate matches stay separate)\n  const boxes: Edges[] = [];\n  for(const fragment of fragments) {\n    const last = boxes[boxes.length - 1];\n    if(last) {\n      const overlap = Math.min(last.bottom, fragment.bottom) - Math.max(last.top, fragment.top);\n      const sameLine = overlap >= Math.min(last.bottom - last.top, fragment.bottom - fragment.top) / 2;\n      if(sameLine && fragment.left <= last.right + 1 && fragment.right >= last.left - 1) {\n        last.left = Math.min(last.left, fragment.left);\n        last.right = Math.max(last.right, fragment.right);\n        last.top = Math.min(last.top, fragment.top);\n        last.bottom = Math.max(last.bottom, fragment.bottom);\n        continue;\n      }\n    }\n\n    boxes.push({...fragment});\n  }\n\n  for(let i = 1; i < boxes.length; ++i) {\n    const previous = boxes[i - 1], box = boxes[i];\n    const gap = box.top - previous.bottom;\n    if(gap > 0 && gap < LINE_BOX_SNAP) {\n      const middle = (previous.bottom + box.top) / 2;\n      previous.bottom = box.top = middle;\n    }\n  }\n\n  return boxes.map((box) => ({\n    left: box.left - origin.left,\n    top: box.top - origin.top,\n    width: box.right - box.left,\n    height: box.bottom - box.top\n  }));\n}\n\n/** a range over all the searchable text of the container (skipped subtrees excluded at the ends) */\nexport function computeFullRange(container: HTMLElement, skip?: string) {\n  const {segments} = extractText(container, skip ? `${DEFAULT_SKIP}, ${skip}` : DEFAULT_SKIP);\n  if(!segments.length) {\n    return;\n  }\n\n  const first = segments[0], last = segments[segments.length - 1];\n  const range = new Range();\n  if(first.atomic) range.setStartBefore(first.node);\n  else range.setStart(first.node, 0);\n  if(last.atomic) range.setEndAfter(last.node);\n  else range.setEnd(last.node, last.end - last.start);\n  return range;\n}\n\n/**\n * Where every \"whole text\" line box goes when the selection narrows down to the match: onto the\n * first match box of its line, or collapsed onto the nearest edge of the match; match boxes that\n * no line box lands on (`extra`) fade in on their own.\n */\nexport function computeNarrowing(full: TextLineBox[], targets: TextLineBox[]) {\n  const ends: TextLineBox[] = [];\n  const claimed = new Set<TextLineBox>();\n  const first = targets[0];\n  for(const box of full) {\n    const bottom = box.top + box.height;\n    const onLine = targets.find((target) => {\n      const overlap = Math.min(bottom, target.top + target.height) - Math.max(box.top, target.top);\n      return overlap >= Math.min(box.height, target.height) / 2;\n    });\n\n    if(onLine) {\n      claimed.add(onLine);\n      ends.push(onLine);\n      continue;\n    }\n\n    // * collapse onto the bottom edge of the last match above, or the top edge of the first one\n    const above = [...targets].reverse().find((target) => target.top < box.top);\n    const anchor = above || first;\n    const edge = above ? above.top + above.height : first.top;\n    ends.push({left: anchor.left, top: edge, width: anchor.width, height: 0});\n  }\n\n  return {ends, extra: targets.filter((target) => !claimed.has(target))};\n}\n\nfunction getRegistryHighlight(type: TextHighlightMatch['type']) {\n  const name = HIGHLIGHT_NAMES[type];\n  let highlight = CSS.highlights.get(name);\n  if(!highlight) {\n    highlight = new Highlight();\n    highlight.priority = HIGHLIGHT_PRIORITIES[type];\n    CSS.highlights.set(name, highlight);\n  }\n\n  return highlight;\n}\n\n// * every live highlight, so the ones whose container silently left the document (a cleared\n// * search list, an ejected bubble) can be released without a hook at each call site\nconst instances = new Set<TextHighlighter>();\nconst SWEEP_INTERVAL = 30e3;\n// * a container may be detached only briefly (virtual lists reattach rows) — give it time\nconst DETACHED_GRACE = 10e3;\nlet sweepTimeout: number;\n\nfunction scheduleSweep() {\n  if(sweepTimeout || !instances.size) {\n    return;\n  }\n\n  sweepTimeout = window.setTimeout(() => {\n    sweepTimeout = undefined;\n    const now = Date.now();\n    for(const instance of instances) {\n      if(instance.container.isConnected) {\n        instance.detachedAt = undefined;\n      } else if(!instance.detachedAt) {\n        instance.detachedAt = now;\n      } else if(now - instance.detachedAt >= DETACHED_GRACE) {\n        instance.dispose();\n      }\n    }\n\n    scheduleSweep();\n  }, SWEEP_INTERVAL);\n}\n\nclass TextHighlighter implements TextHighlight {\n  public found = false;\n  public detachedAt: number;\n  public readonly container: HTMLElement;\n\n  /** `::highlight()` mode: the registry entry the ranges are added to */\n  private readonly highlight: Highlight;\n  /** `lineBoxes` mode: the overlay the boxes are painted into */\n  private overlay: HTMLElement;\n  private ranges: Range[] = [];\n  private mutationObserver: MutationObserver;\n  private resizeObserver: ResizeObserver;\n  private cancelFade: () => void;\n  /** `animateIn`: still to be played by the first paint */\n  private introPending: boolean;\n  private introTimeout: number;\n  private disposed = false;\n\n  constructor(private readonly options: TextHighlightOptions) {\n    this.container = options.container;\n    if(options.lineBoxes) {\n      this.overlay = document.createElement('span');\n      this.overlay.className = OVERLAY_CLASS;\n      this.overlay.setAttribute('aria-hidden', 'true');\n      this.container.prepend(this.overlay);\n      this.introPending = !!options.animateIn && liteMode.isAvailable('animations');\n    } else {\n      this.highlight = getRegistryHighlight(options.match.type);\n    }\n\n    this.apply();\n\n    const reapply = throttleWithRaf(() => this.apply());\n    if(options.observe !== false) {\n      this.mutationObserver = new MutationObserver((records) => {\n        // * painting the overlay mutates the container too — do not chase our own changes\n        if(records.some((record) => !this.isOwnMutation(record))) {\n          reapply();\n        }\n      });\n      this.mutationObserver.observe(this.container, {childList: true, characterData: true, subtree: true});\n    }\n\n    if(this.overlay) {\n      // * boxes are geometry — a narrower container wraps the lines differently. The initial\n      // * notification (and any that does not change the size) must not repaint: it would cut\n      // * the `animateIn` intro short.\n      let lastSize: string;\n      this.resizeObserver = new ResizeObserver(([entry]) => {\n        const size = `${entry.contentRect.width}x${entry.contentRect.height}`;\n        if(lastSize !== undefined && lastSize !== size) {\n          reapply();\n        }\n\n        lastSize = size;\n      });\n      this.resizeObserver.observe(this.container);\n    }\n\n    instances.add(this);\n    scheduleSweep();\n  }\n\n  private isOwnMutation(record: MutationRecord) {\n    const {overlay} = this;\n    if(!overlay) {\n      return false;\n    }\n\n    if(record.target === overlay || overlay.contains(record.target)) {\n      return true;\n    }\n\n    return record.type === 'childList' &&\n      [...record.addedNodes, ...record.removedNodes].every((node) => node === overlay);\n  }\n\n  private clearRanges() {\n    if(this.highlight) {\n      for(const range of this.ranges) {\n        this.highlight.delete(range);\n      }\n    }\n\n    this.ranges = [];\n    this.found = false;\n  }\n\n  private apply() {\n    if(this.disposed) {\n      return;\n    }\n\n    this.clearRanges();\n    this.clearIntro();\n    const {container, match, skip} = this.options;\n    this.ranges = computeRanges(container, match, skip);\n    this.found = this.ranges.length > 0;\n\n    if(!this.overlay) {\n      for(const range of this.ranges) {\n        this.highlight.add(range);\n      }\n\n      return;\n    }\n\n    const boxes = this.computeLineBoxes(this.ranges);\n    if(this.introPending) {\n      this.introPending = false;\n      const fullRange = boxes.length && computeFullRange(container, skip);\n      const full = fullRange ? this.computeLineBoxes([fullRange]) : [];\n      if(full.length) {\n        this.narrowIn(full, boxes);\n        return;\n      }\n    }\n\n    this.paintLineBoxes(boxes);\n  }\n\n  private computeLineBoxes(ranges: Range[]) {\n    const lineHeight = parseFloat(getComputedStyle(this.container).lineHeight) || 0;\n    return computeLineBoxes(ranges, this.overlay.getBoundingClientRect(), lineHeight);\n  }\n\n  private createLineBox(box: TextLineBox) {\n    const element = document.createElement('span');\n    element.className = OVERLAY_BOX_CLASS;\n    element.style.cssText = `left:${box.left}px;top:${box.top}px;width:${box.width}px;height:${box.height}px`;\n    return element;\n  }\n\n  private paintLineBoxes(boxes: TextLineBox[]) {\n    this.overlay.replaceChildren(...boxes.map((box) => this.createLineBox(box)));\n  }\n\n  /**\n   * The whole text is selected (fading in), holds a moment, then every line box slides / scales\n   * onto the match (transforms only, so nothing is laid out again); the plain match boxes take\n   * over once the transition is through.\n   */\n  private narrowIn(full: TextLineBox[], targets: TextLineBox[]) {\n    const {overlay} = this;\n    const elements = full.map((box) => this.createLineBox(box));\n    // * the transparent start state is committed while nothing transitions yet — otherwise the\n    // * jump to it would itself animate and the fade-in would reverse from ~1\n    overlay.classList.add(OVERLAY_APPEARING_CLASS);\n    overlay.replaceChildren(...elements);\n    void overlay.offsetWidth;\n    overlay.classList.add(OVERLAY_INTRO_CLASS);\n    overlay.classList.remove(OVERLAY_APPEARING_CLASS);\n\n    this.introTimeout = window.setTimeout(() => {\n      const {ends, extra} = computeNarrowing(full, targets);\n      const extraElements = extra.map((box) => {\n        const element = this.createLineBox(box);\n        element.style.opacity = '0';\n        return element;\n      });\n      overlay.append(...extraElements);\n      void overlay.offsetWidth; // * commit the start state before transitioning\n      overlay.classList.add(OVERLAY_NARROWING_CLASS);\n\n      elements.forEach((element, i) => {\n        const from = full[i], to = ends[i];\n        element.style.transform = `translate(${to.left - from.left}px, ${to.top - from.top}px) ` +\n          `scale(${to.width / from.width}, ${to.height / from.height})`;\n      });\n      extraElements.forEach((element) => element.style.opacity = '');\n\n      this.introTimeout = window.setTimeout(() => {\n        this.introTimeout = undefined;\n        overlay.classList.remove(OVERLAY_INTRO_CLASS, OVERLAY_NARROWING_CLASS);\n        this.paintLineBoxes(targets);\n      }, NARROW_DURATION);\n    }, NARROW_APPEAR + NARROW_HOLD);\n  }\n\n  private clearIntro() {\n    if(this.introTimeout) {\n      clearTimeout(this.introTimeout);\n      this.introTimeout = undefined;\n    }\n\n    this.overlay?.classList.remove(OVERLAY_INTRO_CLASS, OVERLAY_APPEARING_CLASS, OVERLAY_NARROWING_CLASS);\n  }\n\n  private stopObserving() {\n    this.mutationObserver?.disconnect();\n    this.mutationObserver = undefined;\n    this.resizeObserver?.disconnect();\n    this.resizeObserver = undefined;\n  }\n\n  public fadeOut(duration = FADE_DURATION) {\n    if(this.disposed || this.cancelFade) {\n      return;\n    }\n\n    if(!liteMode.isAvailable('animations')) {\n      this.dispose();\n      return;\n    }\n\n    // * the text is going away, no point in following its container anymore\n    this.stopObserving();\n\n    this.cancelFade = animateValue(1, 0, duration, (value) => {\n      this.container.style.setProperty(OPACITY_PROPERTY, '' + value);\n    }, {onEnd: () => this.dispose()});\n  }\n\n  public dispose() {\n    if(this.disposed) {\n      return;\n    }\n\n    this.disposed = true;\n    this.clearRanges();\n    this.clearIntro();\n    this.stopObserving();\n    this.cancelFade?.();\n    this.cancelFade = undefined;\n    this.container.style.removeProperty(OPACITY_PROPERTY);\n    this.overlay?.remove();\n    this.overlay = undefined;\n    instances.delete(this);\n  }\n}\n\nconst NOOP_HIGHLIGHT: TextHighlight = {\n  found: false,\n  fadeOut: () => {},\n  dispose: () => {}\n};\n\n/**\n * Highlights `match` inside `container`. Returns a handle: call `dispose()` (or `fadeOut()`)\n * once the highlight should go; forgetting it is not fatal — a highlight whose container has\n * been removed from the document is collected on its own.\n */\nexport default function highlightText(options: TextHighlightOptions): TextHighlight {\n  if(!options.lineBoxes && !IS_TEXT_HIGHLIGHT_SUPPORTED) {\n    return NOOP_HIGHLIGHT;\n  }\n\n  return new TextHighlighter(options);\n}\n","import SwipeHandler, {SwipeHandlerOptions} from '@components/swipeHandler';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport isSwipingBackSafari from '@helpers/dom/isSwipingBackSafari';\n\nexport type SwipeHandlerHorizontalOptions = SwipeHandlerOptions & {\n  // xThreshold?: number\n};\n\nexport default function handleHorizontalSwipe(options: SwipeHandlerHorizontalOptions) {\n  let cancelY = false, hadMove = false;\n  return new SwipeHandler({\n    ...options,\n    verifyTouchTarget: (e) => {\n      return !findUpClassName(e.target, 'progress-line') &&\n        !isSwipingBackSafari(e as any as TouchEvent) &&\n        (options.verifyTouchTarget ? options.verifyTouchTarget(e) : true);\n    },\n    onSwipe: (xDiff, yDiff, e) => {\n      xDiff *= -1;\n      yDiff *= -1;\n\n      if(!cancelY && Math.abs(yDiff) > 20) {\n        return true;\n      }\n\n      if(Math.abs(xDiff) > Math.abs(yDiff)) {\n        cancelEvent(e as any as Event);\n        cancelY = true;\n      } else if(!cancelY && Math.abs(yDiff) > Math.abs(xDiff)/*  || Math.abs(yDiff) > 20 */) {\n        return true;\n      }\n\n      /* if(!cancelY && options.xThreshold !== undefined && xDiff >= options.xThreshold) {\n        cancelY = true;\n      } */\n\n      hadMove = true;\n      return options.onSwipe(xDiff, yDiff, e);\n    },\n    onReset: () => {\n      if(hadMove) options.onReset?.();\n      cancelY = hadMove = false;\n    },\n    cancelEvent: false // cannot use cancelEvent on Safari iOS because scroll will be canceled too\n  });\n}\n","export default async function mergeEphemeralHistoryForRender<\n  HistoryEntry,\n  EphemeralMessage extends HistoryEntry\n>(\n  history: HistoryEntry[],\n  shouldLoad: boolean,\n  load: () => Promise<EphemeralMessage[]>\n) {\n  if(!shouldLoad) {\n    return [] as EphemeralMessage[];\n  }\n\n  const messages = await load();\n  history.push(...messages);\n  return messages;\n}\n","export function shouldRenderSenderNameWithEphemeralBadge(\n  needName: boolean,\n  isStandaloneMedia: boolean,\n  isEphemeral: boolean\n) {\n  return needName && (!isStandaloneMedia || isEphemeral);\n}\n\nexport function shouldKeepSenderNameAcrossGroup(\n  isEphemeral: boolean,\n  isOut: boolean\n) {\n  return isEphemeral && !isOut;\n}\n\nexport default function placeEphemeralBadge(\n  bubbleContainer: HTMLElement,\n  name: HTMLElement,\n  badgeContainer: HTMLElement,\n  isStandaloneMedia = false\n) {\n  if(name?.parentElement) {\n    const nextChip = Array.from(name.children).find((element) => (\n      element.classList.contains('bubble-name-chip-container')\n    ));\n\n    if(nextChip) {\n      nextChip.before(badgeContainer);\n    } else {\n      name.append(badgeContainer);\n    }\n  } else {\n    if(isStandaloneMedia) {\n      badgeContainer.classList.add('floating-part', 'ephemeral-badge-standalone');\n    }\n\n    bubbleContainer.prepend(badgeContainer);\n  }\n}\n","export type IntersectionTarget = Element;\nexport type IntersectionCallback = (entry: IntersectionObserverEntry) => void;\n\nexport default class SuperIntersectionObserver {\n  private observing: Map<IntersectionTarget, Set<IntersectionCallback>>;\n  private observingQueue: SuperIntersectionObserver['observing'];\n  private intersecting: Set<IntersectionTarget>;\n  private observer: IntersectionObserver;\n  private freezedObservingNew: boolean;\n\n  constructor(init?: IntersectionObserverInit) {\n    this.observing = new Map();\n    this.observingQueue = new Map();\n    this.intersecting = new Set();\n    this.freezedObservingNew = false;\n\n    this.observer = new IntersectionObserver((entries) => {\n      const observing = this.observing;\n      for(let i = 0, length = entries.length; i < length; ++i) {\n        const entry = entries[i];\n        const callbacks = observing.get(entry.target);\n        if(!callbacks) {\n          console.error('intersection process no callbacks:', entry);\n          debugger;\n          continue;\n        }\n\n        if(entry.isIntersecting) this.intersecting.add(entry.target);\n        else this.intersecting.delete(entry.target);\n\n        for(const callback of callbacks) {\n          try {\n            callback(entry);\n          } catch(err) {\n            console.error('intersection process callback error:', err);\n          }\n        }\n      }\n    }, init);\n  }\n\n  public getIntersecting() {\n    return this.intersecting;\n  }\n\n  public disconnect() {\n    this.observing.clear();\n    this.observingQueue.clear();\n    this.intersecting.clear();\n    this.observer.disconnect();\n  }\n\n  public toggleObservingNew(value: boolean) {\n    if(this.freezedObservingNew === value) {\n      return;\n    }\n\n    this.freezedObservingNew = value;\n\n    const queue = this.observingQueue;\n    if(!value && queue.size) {\n      for(const [target, callbacks] of queue) {\n        for(const callback of callbacks) {\n          this.observe(target, callback);\n        }\n      }\n\n      queue.clear();\n    }\n  }\n\n  public has(target: IntersectionTarget, callback: IntersectionCallback, observing = this.observing) {\n    const callbacks = observing.get(target);\n    return !!(callbacks && callbacks.has(callback));\n  }\n\n  public observe(target: IntersectionTarget, callback: IntersectionCallback) {\n    if(this.freezedObservingNew && this.has(target, callback)) {\n      return;\n    }\n\n    const observing = this.freezedObservingNew ? this.observingQueue : this.observing;\n    let callbacks = observing.get(target);\n    if(callbacks && callbacks.has(callback)) {\n      return;\n    }\n\n    if(!callbacks) {\n      callbacks = new Set();\n      observing.set(target, callbacks);\n\n      if(observing === this.observing) {\n        this.observer.observe(target);\n      }\n    }\n\n    callbacks.add(callback);\n  }\n\n  // Force the native observer to re-deliver an entry for an already-observed\n  // target (all its callbacks get a fresh intersection notification). Plain\n  // re-`observe` of the same callback only re-triggers when it's the target's\n  // only callback; this works regardless of how many callbacks the target has.\n  // No-op while frozen — the queued target will be delivered fresh on drain.\n  public reobserve(target: IntersectionTarget) {\n    if(this.freezedObservingNew || !this.observing.has(target)) {\n      return;\n    }\n\n    this.observer.unobserve(target);\n    this.observer.observe(target);\n  }\n\n  public unobserve(target: IntersectionTarget, callback: IntersectionCallback) {\n    const observing = this.freezedObservingNew && !this.has(target, callback) ? this.observingQueue : this.observing;\n    const callbacks = observing.get(target);\n    if(!callbacks) {\n      return;\n    }\n\n    callbacks.delete(callback);\n    if(!callbacks.size) {\n      observing.delete(target);\n      this.observer.unobserve(target);\n      this.intersecting.delete(target);\n    }\n  }\n}\n","import limitSymbols from '@helpers/string/limitSymbols';\nimport {WebPage} from '@layer';\nimport wrapRichText, {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport {appState} from '@stores/appState';\nimport {untrack} from 'solid-js';\n\nexport default function wrapWebPageDescription(\n  webPage: WebPage.webPage,\n  richTextOptions?: WrapRichTextOptions,\n  isSponsored?: boolean\n) {\n  if(isSponsored) {\n    return wrapRichText(webPage.description || '', {\n      ...richTextOptions,\n      entities: webPage.entities\n    });\n  }\n\n  richTextOptions ??= {};\n  richTextOptions.whitelistedDomains ??= untrack(() => appState.appConfig?.whitelisted_domains);\n\n  const shortDescriptionText = limitSymbols(webPage.description || '', 150, 180);\n  return wrapRichText(shortDescriptionText, richTextOptions);\n}\n","import limitSymbols from '@helpers/string/limitSymbols';\nimport {WebPage} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\n\nexport default function wrapWebPageTitle(webPage: WebPage.webPage) {\n  let shortTitle = webPage.title || webPage.author || '';\n  shortTitle = limitSymbols(shortTitle, 80, 100);\n  return wrapRichText(shortTitle, {noLinks: true, noLinebreaks: true});\n}\n","import {InputMessageReadMetric} from '@layer';\nimport {randomLong} from './random';\nimport clamp from './number/clamp';\n\n/**\n * Port of tdesktop's `HistoryView::ReadMetricsTracker` (history_view_read_metrics_tracker.cpp):\n * collects per-post engagement metrics (`messages.reportReadMetrics`) while channel posts are in\n * the viewport.\n *\n * The DOM layer drives it with a batch each time visibility may have changed — call\n * {@link startBatch}, then {@link push} for every channel post currently overlapping the viewport\n * (with its top/height in the SAME coordinate space as the viewport bounds passed to startBatch),\n * then {@link endBatch}. Between batches an internal timer advances grace periods, accumulates\n * in-view time and enforces the max-duration cap. Finalized metrics are handed to `onFinalize`.\n *\n * Coordinate space is arbitrary but must be consistent within a batch; this port uses client\n * (getBoundingClientRect) pixels.\n */\n\nconst GRACE_PERIOD = 300;\nconst ACTIVITY_TIMEOUT = 15 * 1000;\nconst MAX_TRACKING_DURATION = 5 * 60 * 1000;\nconst MIN_REPORT_THRESHOLD = 300;\n\nexport type FinalizedReadMetric = {\n  peerId: PeerId,\n  metric: Omit<InputMessageReadMetric.inputMessageReadMetric, '_'>\n};\n\ntype TrackedItem = {\n  peerId: PeerId,\n  viewId: string,\n  entryGraceStart: number,\n  trackingStarted: number,\n  lastUpdate: number,\n  totalInView: number,\n  activeInView: number,\n  seenTop: number,\n  seenBottom: number,\n  maxItemHeight: number,\n  maxViewportHeight: number,\n  entryGracePending: boolean,\n  exitGracePending: boolean,\n  exitGraceStart: number\n};\n\nexport default class ReadMetricsTracker {\n  private tracked: Map<number, TrackedItem> = new Map();\n  private currentlyVisible: Set<number> = new Set();\n\n  private batchNow = 0;\n  private batchPeerId: PeerId;\n  private batchViewportHeight = 0;\n  private batchVisibleTop = 0;\n  private batchVisibleBottom = 0;\n  private batchVisible: Set<number> = new Set();\n\n  private lastActivity = 0;\n  private appActive = true;\n  private screenActive = true;\n  private paused = false;\n  private pausedSince = 0;\n  private timeout: number;\n\n  constructor(private onFinalize: (finalized: FinalizedReadMetric) => void) {}\n\n  public startBatch(peerId: PeerId, visibleTop: number, visibleBottom: number) {\n    this.batchNow = Date.now();\n    this.sync(this.batchNow);\n    this.batchPeerId = peerId;\n    this.batchViewportHeight = visibleBottom - visibleTop;\n    this.batchVisibleTop = visibleTop;\n    this.batchVisibleBottom = visibleBottom;\n    this.batchVisible.clear();\n  }\n\n  public push(msgId: number, itemTop: number, itemHeight: number) {\n    this.batchVisible.add(msgId);\n\n    const clippedTop = Math.max(itemTop, this.batchVisibleTop) - itemTop;\n    const clippedBottom = Math.min(itemTop + itemHeight, this.batchVisibleBottom) - itemTop;\n\n    const addTracked = () => {\n      this.tracked.set(msgId, {\n        peerId: this.batchPeerId,\n        viewId: '',\n        entryGraceStart: this.batchNow,\n        trackingStarted: 0,\n        lastUpdate: 0,\n        totalInView: 0,\n        activeInView: 0,\n        seenTop: clippedTop,\n        seenBottom: clippedBottom,\n        maxItemHeight: itemHeight,\n        maxViewportHeight: this.batchViewportHeight,\n        entryGracePending: true,\n        exitGracePending: false,\n        exitGraceStart: 0\n      });\n    };\n\n    const tracked = this.tracked.get(msgId);\n    if(!tracked) {\n      addTracked();\n      return;\n    }\n\n    if(tracked.exitGracePending) {\n      if(this.batchNow - tracked.exitGraceStart >= GRACE_PERIOD) {\n        this.finalize(msgId, tracked);\n        this.tracked.delete(msgId);\n        addTracked();\n        return;\n      }\n\n      tracked.exitGracePending = false;\n      tracked.exitGraceStart = 0;\n      tracked.lastUpdate = this.batchNow;\n    }\n\n    tracked.seenTop = Math.min(tracked.seenTop, clippedTop);\n    tracked.seenBottom = Math.max(tracked.seenBottom, clippedBottom);\n    tracked.maxItemHeight = Math.max(tracked.maxItemHeight, itemHeight);\n    tracked.maxViewportHeight = Math.max(tracked.maxViewportHeight, this.batchViewportHeight);\n  }\n\n  public endBatch() {\n    for(const [msgId, tracked] of this.tracked) {\n      if(this.batchVisible.has(msgId)) {\n        continue;\n      }\n\n      if(tracked.entryGracePending) {\n        this.tracked.delete(msgId);\n        continue;\n      }\n\n      if(!tracked.exitGracePending) {\n        tracked.exitGracePending = true;\n        tracked.exitGraceStart = this.batchNow;\n      }\n    }\n\n    const previous = this.currentlyVisible;\n    this.currentlyVisible = this.batchVisible;\n    this.batchVisible = previous;\n    this.batchVisible.clear();\n    this.restartTimer();\n  }\n\n  public registerActivity() {\n    if(!this.appActive || !this.screenActive) {\n      return;\n    }\n\n    const now = Date.now();\n    const activityDeadline = this.activeUntil();\n    if(activityDeadline && activityDeadline < now) {\n      this.sync(now);\n    }\n\n    this.lastActivity = now;\n    this.restartTimer();\n  }\n\n  public setAppActive(active: boolean) {\n    if(this.appActive === active) {\n      return;\n    }\n\n    this.appActive = active;\n    this.refreshPaused(Date.now());\n  }\n\n  public setScreenActive(active: boolean) {\n    if(this.screenActive === active) {\n      return;\n    }\n\n    this.screenActive = active;\n    this.refreshPaused(Date.now());\n  }\n\n  // Finalizes (and reports, if long enough) every tracked post and stops the timer. Call when the\n  // screen is destroyed or its content (peer) is replaced.\n  public finalizeAll() {\n    this.sync(Date.now());\n    for(const [msgId, tracked] of this.tracked) {\n      this.finalize(msgId, tracked);\n    }\n\n    this.tracked.clear();\n    this.currentlyVisible.clear();\n    this.clearTimeout();\n  }\n\n  private onTimeout = () => {\n    this.timeout = undefined;\n    this.sync(Date.now());\n  };\n\n  private sync(now: number) {\n    const activeUntil = this.activeUntil();\n    this.processTransitions(now, activeUntil);\n    this.accumulate(now, activeUntil);\n    this.restartTimer();\n  }\n\n  private processTransitions(now: number, activeUntil: number) {\n    for(const [msgId, tracked] of this.tracked) {\n      if(tracked.entryGracePending && !this.paused && now - tracked.entryGraceStart >= GRACE_PERIOD) {\n        tracked.entryGracePending = false;\n        tracked.viewId = randomLong();\n        tracked.trackingStarted = tracked.entryGraceStart;\n        tracked.lastUpdate = tracked.trackingStarted;\n      }\n\n      if(tracked.exitGracePending && !this.paused && now - tracked.exitGraceStart >= GRACE_PERIOD) {\n        this.finalize(msgId, tracked);\n        this.tracked.delete(msgId);\n        continue;\n      }\n\n      if(tracked.viewId && !tracked.entryGracePending && !tracked.exitGracePending) {\n        const deadline = tracked.trackingStarted + MAX_TRACKING_DURATION;\n        if(now >= deadline) {\n          if(!this.paused && this.currentlyVisible.has(msgId) && tracked.lastUpdate < deadline) {\n            this.addElapsed(tracked, tracked.lastUpdate, deadline, activeUntil);\n            tracked.lastUpdate = deadline;\n          }\n\n          this.finalize(msgId, tracked);\n          this.tracked.delete(msgId);\n          continue;\n        }\n      }\n    }\n  }\n\n  private accumulate(now: number, activeUntil: number) {\n    for(const [msgId, tracked] of this.tracked) {\n      if(!tracked.viewId || tracked.entryGracePending || tracked.exitGracePending || tracked.lastUpdate <= 0) {\n        continue;\n      }\n\n      if(this.paused || !this.currentlyVisible.has(msgId)) {\n        tracked.lastUpdate = now;\n        continue;\n      }\n\n      this.addElapsed(tracked, tracked.lastUpdate, now, activeUntil);\n      tracked.lastUpdate = now;\n    }\n  }\n\n  private refreshPaused(now: number) {\n    const paused = !this.appActive || !this.screenActive;\n    if(this.paused === paused) {\n      return;\n    }\n\n    if(paused) {\n      const activeUntil = this.activeUntil();\n      this.processTransitions(now, activeUntil);\n      this.accumulate(now, activeUntil);\n      this.pausedSince = now;\n      for(const [, tracked] of this.tracked) {\n        if(tracked.entryGracePending || tracked.exitGracePending) {\n          continue;\n        }\n\n        tracked.lastUpdate = now;\n      }\n    } else {\n      const delta = now - this.pausedSince;\n      for(const [, tracked] of this.tracked) {\n        if(tracked.entryGracePending) {\n          tracked.entryGraceStart = tracked.entryGraceStart < this.pausedSince ? tracked.entryGraceStart + delta : now;\n        } else if(tracked.exitGracePending) {\n          tracked.exitGraceStart = tracked.exitGraceStart < this.pausedSince ? tracked.exitGraceStart + delta : now;\n        } else if(tracked.viewId) {\n          tracked.lastUpdate = now;\n        }\n      }\n\n      this.pausedSince = 0;\n    }\n\n    this.paused = paused;\n    this.restartTimer();\n  }\n\n  private restartTimer() {\n    if(!this.tracked.size) {\n      this.clearTimeout();\n      return;\n    }\n\n    const now = Date.now();\n    let nearest = 0;\n    const updateNearest = (deadline: number) => {\n      if(!deadline) {\n        return;\n      }\n\n      if(!nearest || deadline < nearest) {\n        nearest = deadline;\n      }\n    };\n\n    const activityDeadline = this.activeUntil();\n    for(const [msgId, tracked] of this.tracked) {\n      if(tracked.entryGracePending && !this.paused) {\n        updateNearest(tracked.entryGraceStart + GRACE_PERIOD);\n      } else if(tracked.exitGracePending && !this.paused) {\n        updateNearest(tracked.exitGraceStart + GRACE_PERIOD);\n      } else if(tracked.viewId) {\n        updateNearest(tracked.trackingStarted + MAX_TRACKING_DURATION);\n        if(!this.paused && this.currentlyVisible.has(msgId) && activityDeadline > now) {\n          updateNearest(activityDeadline);\n        }\n      }\n    }\n\n    if(!nearest) {\n      this.clearTimeout();\n      return;\n    }\n\n    this.clearTimeout();\n    this.timeout = self.setTimeout(this.onTimeout, Math.max(nearest - now, 0));\n  }\n\n  private clearTimeout() {\n    if(this.timeout !== undefined) {\n      self.clearTimeout(this.timeout);\n      this.timeout = undefined;\n    }\n  }\n\n  private activeUntil() {\n    return this.lastActivity ? this.lastActivity + ACTIVITY_TIMEOUT : 0;\n  }\n\n  private addElapsed(tracked: TrackedItem, from: number, till: number, activeUntil: number) {\n    if(till <= from) {\n      return;\n    }\n\n    tracked.totalInView += till - from;\n    if(activeUntil > from) {\n      tracked.activeInView += Math.max(Math.min(till, activeUntil) - from, 0);\n      tracked.activeInView = Math.min(tracked.activeInView, tracked.totalInView);\n    }\n  }\n\n  private finalize(msgId: number, tracked: TrackedItem) {\n    if(!tracked.viewId || tracked.totalInView < MIN_REPORT_THRESHOLD) {\n      return;\n    }\n\n    const heightRatio = tracked.maxViewportHeight > 0 ?\n      Math.round(tracked.maxItemHeight * 1000 / tracked.maxViewportHeight) :\n      0;\n    const seenRange = tracked.maxItemHeight > 0 ?\n      clamp(Math.round((tracked.seenBottom - tracked.seenTop) * 1000 / tracked.maxItemHeight), 0, 1000) :\n      0;\n\n    this.onFinalize({\n      peerId: tracked.peerId,\n      metric: {\n        msg_id: msgId,\n        view_id: tracked.viewId,\n        time_in_view_ms: Math.round(tracked.totalInView),\n        active_time_in_view_ms: Math.round(tracked.activeInView),\n        height_to_viewport_ratio_permille: heightRatio,\n        seen_range_ratio_permille: seenRange\n      }\n    });\n  }\n}\n","/*\n * Computes the square grid geometry for a sticker-set / custom-emoji webpage preview.\n * Mirrors tdesktop history_view_web_page.cpp:1067-1068:\n *   side = ceil(sqrt(count)); single = box / side;\n * The grid is a square NxN (e.g. 4 stickers -> 2x2, 9 -> 3x3); each sticker is\n * centered in its cell. `count` is clamped to >= 1 to avoid NaN / divide-by-zero.\n */\nexport default function computeStickerSetPreviewGrid(count: number, boxSize = 56) {\n  const n = Math.max(1, count);\n  const side = Math.ceil(Math.sqrt(n));\n  const cellSize = Math.floor(boxSize / side);\n  return {side, cellSize, boxSize};\n}\n","import mediaSizes from '@helpers/mediaSizes';\nimport {Middleware} from '@helpers/middleware';\nimport {ChatAutoDownloadSettings} from '@hooks/useAutoDownloadSettings';\nimport {Document, Message, MessageMedia, Photo, PhotoSize} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport rootScope from '@lib/rootScope';\nimport {AnimationItemGroup} from '@components/animationIntersector';\nimport Chat from '@components/chat/chat';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport prepareAlbum from '@components/prepareAlbum';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapVideo from '@components/wrappers/video';\n\nexport default function wrapAlbum({messages, media, attachmentDiv, middleware, uploading, lazyLoadQueue, isOut, chat, loadPromises, autoDownload, managers = rootScope.managers, animationGroup, spoilered, videoTimes, uploadingFileName, sensitive}: {\n  messages?: Message.message[],\n  media?: (Photo.photo | Document.document)[],\n  attachmentDiv: HTMLElement,\n  middleware?: Middleware,\n  lazyLoadQueue?: LazyLoadQueue,\n  uploading?: boolean,\n  isOut: boolean,\n  chat: Chat,\n  loadPromises?: Promise<any>[],\n  autoDownload?: ChatAutoDownloadSettings,\n  managers?: AppManagers,\n  animationGroup?: AnimationItemGroup,\n  spoilered?: boolean,\n  sensitive?: boolean,\n  videoTimes?: HTMLElement[],\n  uploadingFileName?: string[]\n}) {\n  const items: {size: PhotoSize.photoSize, media: Photo.photo | Document.document, message: Message.message}[] = [];\n\n  // !lowest msgID will be the FIRST in album\n  for(const message of media || messages) {\n    const isMessage = !!messages;\n    const media = isMessage ? getMediaFromMessage(message as Message.message, true) : message;\n\n    const size: any = media._ === 'photo' ?\n      choosePhotoSize(media, 480, 480) :\n      {w: (media as Document.document).w, h: (media as Document.document).h};\n    items.push({size, media: media as any, message: isMessage ? message as Message.message : undefined});\n  }\n\n  /* // * pending\n  if(storage[0] < 0) {\n    items.reverse();\n  } */\n\n  prepareAlbum({\n    container: attachmentDiv,\n    items: items.map((i) => ({w: i.size.w, h: i.size.h})),\n    maxWidth: mediaSizes.active.album.width,\n    minWidth: 100,\n    spacing: 1,\n    forMedia: true,\n    noGroupedItem: !messages\n  });\n\n  const {width, height} = attachmentDiv.style;\n  const containerWidth = parseInt(width);\n  const containerHeight = parseInt(height);\n\n  items.forEach((item, idx) => {\n    const {size, media, message} = item;\n\n    const messageMedia = message?.media;\n    const hasSpoiler = spoilered || sensitive || !!(messageMedia as MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument)?.pFlags?.spoiler;\n\n    const div = attachmentDiv.children[idx] as HTMLElement;\n    if(message) {\n      div.dataset.mid = '' + message.mid;\n      div.dataset.peerId = '' + message.peerId;\n    } else {\n      div.dataset.index = '' + idx;\n    }\n    const mediaDiv = div.firstElementChild as HTMLElement;\n    const isPhoto = media._ === 'photo';\n    let thumbPromise: Promise<any>;\n    if(isPhoto) {\n      thumbPromise = wrapPhoto({\n        photo: media,\n        message,\n        container: mediaDiv,\n        boxWidth: 0,\n        boxHeight: 0,\n        isOut,\n        lazyLoadQueue,\n        middleware,\n        size,\n        loadPromises,\n        autoDownloadSize: autoDownload.photo,\n        managers,\n        uploadingFileName: uploadingFileName?.[idx]\n      });\n    } else {\n      thumbPromise = wrapVideo({\n        doc: media,\n        container: mediaDiv,\n        message,\n        boxWidth: 0,\n        boxHeight: 0,\n        withTail: false,\n        isOut,\n        lazyLoadQueue,\n        middleware,\n        loadPromises,\n        autoDownload,\n        managers,\n        noAutoplayAttribute: true,\n        uploadingFileName: uploadingFileName?.[idx]\n      });\n    }\n\n    if(thumbPromise) {\n      loadPromises?.push(thumbPromise);\n    }\n\n    if(hasSpoiler) {\n      const promise = (thumbPromise || Promise.resolve()).then(async() => {\n        if(!middleware()) {\n          return;\n        }\n\n        const {width, height} = div.style;\n        const itemWidth = +width.slice(0, -1) / 100 * containerWidth;\n        const itemHeight = +height.slice(0, -1) / 100 * containerHeight;\n        const container = await wrapMediaSpoiler({\n          media,\n          animationGroup,\n          middleware,\n          width: itemWidth,\n          height: itemHeight,\n          sensitive\n        });\n\n        if(!middleware()) {\n          return;\n        }\n\n        mediaDiv.append(container);\n      });\n\n      loadPromises?.push(promise);\n    }\n\n    const videoTime = videoTimes?.[idx];\n    if(videoTime) {\n      mediaDiv.append(videoTime);\n    }\n  });\n}\n","import {Document, Message, MessageMedia} from '@layer';\n\nexport default function getMediaDurationFromMessage(message: Message.message) {\n  if(!message) return undefined;\n  const doc = (message.media as MessageMedia.messageMediaDocument)?.document as Document.document;\n  const duration = ((['voice', 'audio', 'video'] as Document.document['type'][]).includes(doc?.type) && doc.duration) || undefined;\n  return duration;\n}\n","import setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {MediaSizeType} from '@helpers/mediaSizes';\nimport {Message} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport getMediaDurationFromMessage from '@appManagers/utils/messages/getMediaDurationFromMessage';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {MediaSearchContext} from '@components/appMediaPlaybackController';\nimport Chat from '@components/chat/chat';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport TranslatableMessage from '@components/translatableMessage';\nimport wrapDocument from '@components/wrappers/document';\nimport {Middleware} from '@helpers/middleware';\n\nexport default async function wrapGroupedDocuments({\n  albumMustBeRenderedFull,\n  middleware,\n  message,\n  bubble,\n  messageDiv,\n  chat,\n  loadPromises,\n  autoDownloadSize,\n  lazyLoadQueue,\n  searchContext,\n  useSearch,\n  sizeType,\n  managers,\n  fontWeight,\n  fontSize,\n  richTextFragment,\n  richTextOptions,\n  canTranscribeVoice,\n  translatableParams,\n  factCheckBox,\n  isOut\n}: {\n  albumMustBeRenderedFull: boolean,\n  middleware: Middleware,\n  message: any,\n  messageDiv: HTMLElement,\n  bubble: HTMLElement,\n  uploading?: boolean,\n  chat: Chat,\n  loadPromises?: Promise<any>[],\n  autoDownloadSize?: number,\n  lazyLoadQueue?: LazyLoadQueue,\n  searchContext?: MediaSearchContext,\n  useSearch?: boolean,\n  sizeType?: MediaSizeType,\n  managers?: AppManagers,\n  fontWeight?: number,\n  fontSize?: number,\n  richTextFragment?: DocumentFragment | HTMLElement,\n  richTextOptions?: Parameters<typeof wrapRichText>[1]\n  canTranscribeVoice?: boolean,\n  translatableParams: Parameters<typeof TranslatableMessage>[0],\n  factCheckBox?: HTMLElement,\n  isOut?: boolean\n}) {\n  let nameContainer: HTMLElement;\n  const {peerId} = message;\n  const mids = albumMustBeRenderedFull ? await chat.getMidsByMid(message.peerId, message.mid) : [message.mid];\n  /* if(isPending) {\n    mids.reverse();\n  } */\n\n  const promises = mids.map(async(mid, idx, arr) => {\n    const message = chat.getMessageByPeer(peerId, mid) as Message.message;\n    const div = await wrapDocument({\n      message,\n      middleware,\n      loadPromises,\n      autoDownloadSize,\n      lazyLoadQueue,\n      searchContext,\n      sizeType,\n      managers,\n      fontWeight,\n      fontSize,\n      canTranscribeVoice,\n      isOut\n    });\n\n    const container = document.createElement('div');\n    container.classList.add('document-container');\n    container.dataset.mid = '' + mid;\n    container.dataset.peerId = '' + message.peerId;\n\n    const wrapper = document.createElement('div');\n    wrapper.classList.add('document-wrapper');\n\n    const isFirst = idx === 0;\n    const isLast = idx === (arr.length - 1);\n\n    if(isFirst) container.classList.add('is-first');\n    if(isLast) container.classList.add('is-last');\n    // if(!(isFirst && isLast)) container.classList.add('has-sibling');\n\n    let messageDiv: HTMLElement;\n    if(message.message || (isLast && factCheckBox)) {\n      messageDiv = document.createElement('div');\n      messageDiv.classList.add('document-message');\n    }\n\n    if(message.message) {\n      let fragment = richTextFragment;\n      if(!fragment) {\n        if(translatableParams) {\n          fragment = TranslatableMessage({\n            ...translatableParams,\n            message,\n            richTextOptions: {\n              ...translatableParams.richTextOptions,\n              maxMediaTimestamp: getMediaDurationFromMessage(message)\n            }\n          });\n        } else {\n          fragment = wrapRichText(message.message, {\n            ...richTextOptions,\n            entities: message.totalEntities,\n            maxMediaTimestamp: getMediaDurationFromMessage(message)\n          });\n        }\n      }\n\n      setInnerHTML(messageDiv, fragment);\n    }\n\n    if(factCheckBox && messageDiv && isLast) {\n      messageDiv.append(factCheckBox);\n    }\n\n    if(mids.length > 1) {\n      const selection = document.createElement('div');\n      selection.classList.add('document-selection');\n      container.append(selection);\n\n      container.classList.add('grouped-item');\n\n      if(idx === 0) {\n        nameContainer = wrapper;\n      }\n    }\n\n    wrapper.append(...[div, messageDiv].filter(Boolean));\n    container.append(wrapper);\n    return container;\n  });\n\n  const containers = await Promise.all(promises);\n  messageDiv.append(...containers);\n\n  if(mids.length > 1) {\n    bubble.classList.add('is-multiple-documents', 'is-grouped');\n  }\n\n  return nameContainer;\n}\n","import {logger, LogTypes} from '@lib/logger';\nimport insertInDescendSortedArray from '@helpers/array/insertInDescendSortedArray';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport safeAssign from '@helpers/object/safeAssign';\nimport pause from '@helpers/schedulers/pause';\n\nexport type SortedElementBase<T = any> = {\n  id: T,\n  index: number\n};\n\nlet id = 0;\n\nexport class BatchProcessor<Item extends any = any> {\n  protected queue: MaybePromise<Item>[];\n  protected promise: Promise<void>;\n\n  protected middlewareHelper: MiddlewareHelper;\n  protected log: ReturnType<typeof logger>;\n\n  protected process: (batch: Item[], m: ReturnType<typeof middlewarePromise>, log: BatchProcessor['log']) => Promise<any>;\n  protected possibleError: any;\n\n  constructor(options: {\n    log?: BatchProcessor['log'],\n    // middleware: MiddlewareHelper,\n    process: BatchProcessor<Item>['process'],\n    possibleError?: BatchProcessor['possibleError']\n  }) {\n    safeAssign(this, options);\n\n    this.queue = [];\n    this.middlewareHelper ??= getMiddleware();\n\n    const prefix = 'BATCH-PROCESSOR-' + ++id;\n    const logTypes = LogTypes.Log | LogTypes.Warn | LogTypes.Error;\n    if(this.log) {\n      this.log = this.log.bindPrefix(prefix, logTypes);\n    } else {\n      this.log = logger(prefix, logTypes);\n    }\n  }\n\n  public get queuePromise() {\n    return this.promise;\n  }\n\n  public clear() {\n    this.log('clear');\n    this.queue.length = 0;\n    this.promise = undefined;\n    this.middlewareHelper.clean();\n  }\n\n  public addToQueue(item: BatchProcessor<Item>['queue'][0]) {\n    this.queue.push(item);\n    return this.setQueue();\n  }\n\n  protected setQueue() {\n    if(!this.queue.length) {\n      return Promise.resolve();\n    }\n\n    if(this.promise) {\n      return this.promise;\n    }\n\n    const middleware = this.middlewareHelper.get();\n    const log = this.log.bindPrefix('queue');\n    const m = middlewarePromise(middleware, this.possibleError);\n\n    const processQueue = async(): Promise<void> => {\n      log('start', this.queue.length);\n\n      const queue = this.queue.splice(0, this.queue.length);\n\n      const perf = performance.now();\n      const promises = queue.map((promise) => {\n        if(promise instanceof Promise) {\n          promise.then((details) => {\n            log('render item time', performance.now() - perf, details);\n          });\n        }\n\n        return promise;\n      });\n\n      const renderedQueue = await m(Promise.all(promises));\n      await m(this.process(renderedQueue, m, log));\n\n      log('queue rendered');\n\n      if(this.queue.length) {\n        log('have new items to render');\n        return processQueue();\n      } else {\n        log('end');\n      }\n    };\n\n    log('setting pause');\n    const promise = this.promise = m(pause(0))\n    .then(\n      () => processQueue().catch((err: ApiError) => {\n        if(err !== this.possibleError) {\n          log.error('process queue error', err);\n        }\n\n        throw err;\n      }),\n      (err) => {\n        log('pause has been cleared');\n        throw err;\n      }\n    )\n    .finally(() => {\n      if(this.promise === promise) {\n        this.promise = undefined;\n      }\n    });\n\n    return promise;\n  }\n}\n\nexport default class SortedList<SortedElement extends SortedElementBase, SortedElementId = SortedElement['id']> {\n  protected elements: Map<SortedElementId, SortedElement>;\n  protected sorted: Array<SortedElement>;\n\n  protected getIndex: (element: SortedElement) => Promise<number> | number;\n  protected onDelete: (element: SortedElement) => void;\n  protected onUpdate: (element: SortedElement) => void;\n  protected onSort: (element: SortedElement, idx: number) => void;\n  protected onElementCreate: (base: SortedElementBase) => Promise<SortedElement> | SortedElement;\n\n  protected updateElementWith = (callback: () => void) => callback();\n  protected updateListWith = (callback: (canUpdate: boolean | undefined) => void) => callback(true);\n\n  protected middlewareHelper: MiddlewareHelper;\n\n  protected batchProcessor: BatchProcessor<SortedElement>;\n\n  protected log: ReturnType<typeof logger>;\n\n  constructor(options: {\n    getIndex: SortedList<SortedElement>['getIndex'],\n    onDelete?: SortedList<SortedElement>['onDelete'],\n    onUpdate?: SortedList<SortedElement>['onUpdate'],\n    onSort?: SortedList<SortedElement>['onSort'],\n    onElementCreate: SortedList<SortedElement>['onElementCreate'],\n\n    updateElementWith?: SortedList<SortedElement>['updateElementWith'],\n    updateListWith?: SortedList<SortedElement>['updateListWith'],\n\n    log?: SortedList<SortedElement>['log'],\n\n    middleware?: Middleware\n  }) {\n    safeAssign(this, options);\n\n    this.elements = new Map();\n    this.sorted = [];\n    this.middlewareHelper = options.middleware?.create() || getMiddleware();\n\n    this.batchProcessor = new BatchProcessor<SortedElement>({\n      log: this.log,\n      process: async(batch, m, log) => {\n        // const elements = await Promise.all(batch.map((element) => this.onElementCreate(element)));\n        const elements = batch;\n        const promises = elements.map((element) => this.update(element.id, element));\n        await m(Promise.all(promises));\n      }\n    });\n  }\n\n  public clear() {\n    this.batchProcessor.clear();\n    this.middlewareHelper.clean();\n    this.elements.clear();\n    this.sorted.length = 0;\n  }\n\n  protected _updateList() {\n    this.elements.forEach((element) => {\n      this.update(element.id);\n    });\n\n    if(this.onSort) {\n      this.sorted.forEach((element, idx) => {\n        this.onSort(element, idx);\n      });\n    }\n  }\n\n  public updateList(callback?: (updated: boolean) => void) {\n    const middleware = this.middlewareHelper.get();\n    this.updateListWith((canUpdate) => {\n      if(!middleware() || (canUpdate !== undefined && !canUpdate)) {\n        callback?.(false);\n        return;\n      }\n\n      this._updateList();\n\n      callback?.(true);\n    });\n  }\n\n  public has(id: SortedElementId) {\n    return this.elements.has(id);\n  }\n\n  public get(id: SortedElementId) {\n    return this.elements.get(id);\n  }\n\n  public getAll() {\n    return this.elements;\n  }\n\n  public async add(id: SortedElementId) {\n    const element = this.get(id);\n    if(element) {\n      return;\n      // return element;\n    }\n\n    const base: SortedElementBase = {\n      id,\n      index: 0\n    };\n\n    this.elements.set(id, base as SortedElement);\n    let result = this.onElementCreate(base);\n    if(result instanceof Promise) {\n      let processed = false;\n      result = Promise.race([\n        result.then((result) => {\n          processed = true;\n          return result;\n        }),\n        pause(1000).then(() => {\n          if(!processed) {\n            console.error('loadPromises are still pending?', base);\n            return base as any;\n          }\n        })\n      ]);\n    }\n    return this.batchProcessor.addToQueue(result);\n\n    // return element;\n  }\n\n  public delete(id: SortedElementId, noScheduler?: boolean) {\n    const element = this.elements.get(id);\n    if(!element) {\n      return false;\n    }\n\n    this.elements.delete(id);\n\n    const idx = this.sorted.indexOf(element);\n    if(idx !== -1) {\n      this.sorted.splice(idx, 1);\n    }\n\n    if(this.onDelete) {\n      if(noScheduler) {\n        this.onDelete(element);\n      } else {\n        const middleware = this.middlewareHelper.get();\n        this.updateElementWith(() => {\n          if(!middleware()) {\n            return;\n          }\n\n          this.onDelete(element);\n        });\n      }\n    }\n\n    return true;\n  }\n\n  public async update(id: SortedElementId, element = this.get(id)) {\n    if(!element) {\n      return;\n    }\n\n    element.index = await this.getIndex(element);\n    if(this.get(id) !== element) {\n      return;\n    }\n\n    this.onUpdate?.(element);\n\n    const idx = insertInDescendSortedArray(this.sorted, element, 'index');\n    this.onSort(element, idx);\n  }\n}\n","import {ChannelParticipant, ChatParticipant} from '@layer';\n\nexport default function getParticipantRank(participant: ChannelParticipant | ChatParticipant) {\n  return (participant as ChannelParticipant.channelParticipantAdmin).rank ||\n    (participant._ === 'channelParticipantAdmin' || participant._ === 'chatParticipantAdmin' ? 2 :\n      (participant._ === 'chatParticipantCreator' || participant._ === 'channelParticipantCreator' ? 1 : undefined));\n}\n","import getParticipantRank from '@appManagers/utils/chats/getParticipantRank';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\n\nexport default function wrapParticipantRank(rank: Parameters<typeof getParticipantRank>[0] | ReturnType<typeof getParticipantRank> | 0) {\n  if(typeof(rank) === 'object') {\n    rank = getParticipantRank(rank);\n  }\n\n  return typeof(rank) === 'number' ?\n    i18n(!rank ? 'Chat.ChannelBadge' : (rank === 1 ? 'Chat.OwnerBadge' : 'ChatAdmin')) :\n    wrapEmojiText(rank);\n}\n","import {getAppWindow} from '@helpers/appWindow';\n\nexport default function getSelectedText(): string {\n  if(getAppWindow().getSelection) {\n    return getAppWindow().getSelection().toString();\n    // @ts-ignore\n  } else if(document.selection) {\n    // @ts-ignore\n    return document.selection.createRange().text;\n  }\n\n  return '';\n}\n","import Icon from '@components/icon';\nimport {wrapCallDuration} from '@components/wrappers/wrapDuration';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport {MessageAction} from '@layer';\nimport {_i18n, LangPackKey} from '@lib/langPack';\nimport {getConferenceCallLangKey, getConferenceCallState} from '@lib/calls/helpers/conferenceCallAction';\nimport {CallType} from '@lib/calls/types';\n\nexport type CallBubbleAction =\n  | MessageAction.messageActionPhoneCall\n  | MessageAction.messageActionConferenceCall;\n\n/**\n * The call-log bubble: icon, what kind of call it was, and a status line the\n * caller appends the message time to. tdesktop draws 1-on-1 and conference\n * calls with the very same media (HistoryView::Call, history_view_call.cpp),\n * and so does this — the conference variant differs only in its icon, in\n * taking its title from the call's state, and in carrying the invite message\n * id the join click needs.\n */\nexport default function wrapCallBubble(options: {\n  action: CallBubbleAction,\n  isOut: boolean,\n  /** Local mid of the message the bubble belongs to. */\n  mid: number\n}) {\n  const {action, isOut, mid} = options;\n  const isConference = action._ === 'messageActionConferenceCall';\n\n  const element = document.createElement('div');\n  element.classList.add('bubble-call');\n  element.append(Icon(\n    action.pFlags.video ? 'videocamera' : (isConference ? 'group' : 'phone'),\n    'bubble-call-icon'\n  ));\n\n  const title = document.createElement('div');\n  title.classList.add('bubble-call-title');\n\n  const subtitle = document.createElement('div');\n  subtitle.classList.add('bubble-call-subtitle');\n\n  let isMissed: boolean;\n  if(action._ === 'messageActionConferenceCall') {\n    // The title carries the whole state (invitation / ongoing / missed /\n    // declined), the status line only ever adds a duration next to the time,\n    // and the bubble as a whole is the join affordance.\n    const state = getConferenceCallState(action);\n    isMissed = state === 'missed';\n    element.dataset.conferenceMsgId = '' + getServerMessageId(mid);\n    _i18n(title, getConferenceCallLangKey(state, isOut));\n\n    if(action.duration !== undefined) {\n      subtitle.append(wrapCallDuration(action.duration));\n    }\n  } else {\n    const type: CallType = action.pFlags.video ? 'video' : 'voice';\n    element.dataset.type = type;\n    isMissed = action.duration === undefined;\n\n    _i18n(title, isOut ?\n      (action.pFlags.video ? 'CallMessageVideoOutgoing' : 'CallMessageOutgoing') :\n      (action.pFlags.video ? 'CallMessageVideoIncoming' : 'CallMessageIncoming'));\n\n    if(action.duration !== undefined) {\n      subtitle.append(wrapCallDuration(action.duration));\n    } else {\n      let langPackKey: LangPackKey;\n      switch(action.reason._) {\n        case 'phoneCallDiscardReasonBusy':\n          langPackKey = 'Call.StatusBusy';\n          break;\n        case 'phoneCallDiscardReasonMissed':\n          langPackKey = 'Chat.Service.Call.Missed';\n          break;\n        // case 'phoneCallDiscardReasonHangup':\n        default:\n          langPackKey = 'Chat.Service.Call.Cancelled';\n          break;\n      }\n\n      subtitle.classList.add('is-reason');\n      _i18n(subtitle, langPackKey);\n    }\n  }\n\n  subtitle.prepend(Icon('arrow_next', 'bubble-call-arrow', 'bubble-call-arrow-' + (isMissed ? 'red' : 'green')));\n\n  element.append(title, subtitle);\n\n  return {element, subtitle};\n}\n","import {formatFullSentTime, formatMonthsDuration} from '@helpers/date';\nimport liteMode from '@helpers/liteMode';\nimport clamp from '@helpers/number/clamp';\nimport {Message, MessageMedia} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport I18n, {FormatterArguments, LangPackKey, i18n, join} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport {getCountryEmoji} from '@vendor/emoji';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport confirmationPopup from '@components/confirmationPopup';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport {For, JSX} from 'solid-js';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport PopupElement from '@components/popups';\nimport PopupGiftLink from '@components/popups/giftLink';\nimport classNames from '@helpers/string/classNames';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {IconTsx} from '@components/iconTsx';\nimport {setPeerColorToElement} from '@components/peerColors';\n\nexport function getGiftAssetName(days?: number) {\n  const months = days === undefined ? days : Math.round(days / 30);\n  const durationAssetMap: {[key: number]: LottieAssetName} = {\n    3: 'Gift3',\n    6: 'Gift6',\n    12: 'Gift12'\n  };\n\n  return durationAssetMap[clamp(months ?? 0, 3, 12)];\n}\n\nexport function DelimiterWithText(props: {langKey: LangPackKey}) {\n  return (\n    <span class=\"delimiter-with-text\">\n      <span class=\"delimiter-with-text-stripe\" />\n      {i18n(props.langKey)}\n      <span class=\"delimiter-with-text-stripe\" />\n    </span>\n  );\n}\n\nexport async function onGiveawayClick(message: Message.message) {\n  const giveaway = message.media as MessageMedia.messageMediaGiveaway | MessageMedia.messageMediaGiveawayResults;\n  const giveawayInfo = await rootScope.managers.appPaymentsManager.getGiveawayInfo(message.peerId, message.mid);\n  const d = document.createDocumentFragment();\n  const duration = formatMonthsDuration(giveaway.months, true);\n  const giveawayPeerId = (message as Message.message).fwdFromId || message.peerId;\n\n  const isMediaResults = giveaway._ === 'messageMediaGiveawayResults';\n  const isResults = giveawayInfo._ === 'payments.giveawayInfoResults';\n  const isRefunded = isResults && giveawayInfo.pFlags.refunded;\n  const isWinner = !isRefunded && isResults && giveawayInfo.pFlags.winner;\n  const isParticipating = !isResults && giveawayInfo.pFlags.participating;\n  const isStars = !!giveaway.stars;\n  const onlyNewSubscribers = giveaway.pFlags.only_new_subscribers;\n  const quantity = isMediaResults ? giveaway.winners_count + giveaway.unclaimed_count : giveaway.quantity;\n  const additionalPeersLength = isMediaResults ? giveaway.additional_peers_count || 0 : giveaway.channels.length - 1;\n\n  const formatDate = (timestamp: number) => formatFullSentTime(timestamp, undefined, true);\n\n  let subtitleKey: LangPackKey = 'Giveaway.Info';\n  const subtitleArgs: FormatterArguments = [\n    formatDate(isResults ? giveawayInfo.finish_date : giveaway.until_date),\n    i18n('Giveaway.Info.Users', [quantity]),\n    await wrapPeerTitle({peerId: giveawayPeerId})\n  ];\n\n  if(additionalPeersLength) {\n    subtitleKey += '.Several';\n    subtitleArgs.push(i18n('Giveaway.Info.OtherChannels', [additionalPeersLength]));\n  }\n  if(onlyNewSubscribers) {\n    subtitleKey += '.Date';\n    subtitleArgs.push(formatDate(giveawayInfo.start_date));\n  }\n  if(isResults) subtitleKey += '.End';\n\n  let subsubtitleKey: LangPackKey,\n    subsubtitleArgs: FormatterArguments,\n    subsubtitleAtTop: boolean;\n  if(isRefunded) {\n    subsubtitleKey = 'BoostingGiveawayCanceledByPayment';\n  } else if(isWinner) {\n    subsubtitleKey = 'Giveaway.Won';\n    subsubtitleArgs = [\n      wrapEmojiText('🏆')\n    ];\n    subsubtitleAtTop = true;\n  } else if(isResults) {\n    subsubtitleKey = 'BoostingGiveawayYouNotWon';\n    subsubtitleAtTop = true;\n  } else if(giveawayInfo.joined_too_early_date) {\n    subsubtitleKey = 'BoostingGiveawayNotEligible';\n    subsubtitleArgs = [\n      formatDate(giveawayInfo.joined_too_early_date)\n    ];\n  } else if(giveawayInfo.disallowed_country) {\n    subsubtitleKey = 'BoostingGiveawayNotEligibleCountry';\n  } else if(giveawayInfo.admin_disallowed_chat_id) {\n    subsubtitleKey = 'BoostingGiveawayNotEligibleAdmin';\n    subsubtitleArgs = [\n      await wrapPeerTitle({peerId: giveawayInfo.admin_disallowed_chat_id.toPeerId(true)})\n    ];\n  } else {\n    subsubtitleKey = isParticipating ? 'Giveaway.Participation' : 'Giveaway.TakePart';\n    subsubtitleArgs = [\n      await wrapPeerTitle({peerId: giveawayPeerId})\n    ];\n\n    if(additionalPeersLength) {\n      subsubtitleKey += '.Multi';\n      subsubtitleArgs.push(i18n('Giveaway.Info.OtherChannels', [additionalPeersLength]));\n    }\n\n    if(!isParticipating && giveawayInfo.start_date) {\n      subsubtitleArgs.push(formatDate(giveaway.until_date));\n    }\n  }\n\n  let titleLangPackKey: LangPackKey;\n  if(isStars) {\n    titleLangPackKey = isResults ? 'BoostingStarsGiveawayHowItWorksTextEnd' : 'BoostingStarsGiveawayHowItWorksText';\n  } else {\n    titleLangPackKey = isResults ? 'BoostingGiveawayHowItWorksTextEnd' : 'BoostingGiveawayHowItWorksText';\n  }\n\n  const title = i18n(\n    titleLangPackKey,\n    [\n      giveaway.stars || quantity,\n      await wrapPeerTitle({peerId: giveawayPeerId}),\n      quantity,\n      duration\n    ]\n  );\n\n  const subtitle = i18n(subtitleKey as LangPackKey, subtitleArgs);\n  const subsubtitle = i18n(subsubtitleKey as LangPackKey, subsubtitleArgs);\n\n  if(subsubtitleAtTop || isRefunded) {\n    subsubtitle.classList.add('popup-description-framed');\n  }\n\n  if(isRefunded) {\n    subsubtitle.classList.add('popup-description-danger');\n  }\n\n  d.append(...[\n    ...(subsubtitleAtTop ? [\n      subsubtitle,\n      document.createElement('br')\n    ] : []),\n    title,\n    document.createElement('br'),\n    document.createElement('br'),\n    ...(giveaway.prize_description ? [\n      i18n('Giveaway.AlsoPrizes', [\n        await wrapPeerTitle({peerId: giveawayPeerId}),\n        quantity,\n        wrapEmojiText(giveaway.prize_description),\n        i18n('Giveaway.AlsoPrizes2', [quantity])\n      ]),\n      document.createElement('br'),\n      document.createElement('br')\n    ] : []),\n    subtitle,\n    ...(isResults && giveawayInfo.activated_count ? [\n      ' ',\n      i18n('BoostingGiveawayUsedLinksPlural', [giveawayInfo.activated_count])\n    ] : []),\n    ...(!subsubtitleAtTop ? [\n      document.createElement('br'),\n      document.createElement('br'),\n      subsubtitle\n    ] : [])\n  ].filter(Boolean));\n\n  await confirmationPopup({\n    titleLangKey: isResults ? 'BoostingGiveawayEnd' : 'BoostingGiveAwayAbout',\n    description: d,\n    button: isWinner ? {\n      langKey: 'BoostingGiveawayViewPrize'\n    } : {\n      langKey: 'OK',\n      isCancel: true\n    }\n  });\n\n  if(isWinner) {\n    PopupElement.createPopup(PopupGiftLink, giveawayInfo.gift_code_slug);\n  }\n}\n\nexport default function Giveaway(props: {\n  giveaway: MessageMedia.messageMediaGiveaway | MessageMedia.messageMediaGiveawayResults,\n  loadPromises?: Promise<any>[]\n}) {\n  // props.giveaway.countries_iso2 = ['UA', 'PL', 'AE'];\n\n  const middleware = createMiddleware().get();\n  const giveaway = props.giveaway;\n  const isResults = giveaway._ === 'messageMediaGiveawayResults';\n  const quantity = isResults ? giveaway.stars ?? giveaway.winners_count : giveaway.stars ?? giveaway.quantity;\n  const countriesElements = !isResults && giveaway.countries_iso2?.map((iso2) => {\n    const span = document.createElement('span');\n    span.classList.add('bubble-giveaway-country');\n    const country = I18n.countriesList.find((country) => country.iso2 === iso2);\n    span.append(wrapEmojiText(getCountryEmoji(iso2) + ' ' + (country.name || country.default_name)));\n    return span;\n  });\n\n  const headerDuration = formatMonthsDuration(giveaway.months, true);\n  let header: JSX.Element;\n  if(isResults) {\n    let a: HTMLAnchorElement;\n    (\n      <a\n        ref={a}\n        class=\"bubble-giveaway-link\"\n        data-saved-from={`${giveaway.channel_id.toPeerId(true)}_${giveaway.launch_msg_id}`}\n      />\n    );\n    header = (\n      <>\n        {i18n('Giveaway.Results.Subtitle', [giveaway.winners_count, a])}\n      </>\n    );\n  } else {\n    header = giveaway.prize_description ? (\n      <>\n        <b>{`${quantity} `}</b>\n        {wrapEmojiText(giveaway.prize_description)}\n        <DelimiterWithText langKey=\"Giveaway.With\" />\n        {giveaway.stars ?\n          i18n('Giveaway.WithStars', [giveaway.quantity, i18n('Giveaway.WithStars.Stars', [+giveaway.stars])]) :\n          i18n(+quantity > 1 ? 'Giveaway.WithSubscriptionsPlural' : 'Giveaway.WithSubscriptionsSingle', [headerDuration])}\n      </>\n    ) : (\n      <>\n        {i18n(giveaway.stars ? 'BoostingStarsGiveawayMsgInfoPlural1' : 'BoostingGiveawayMsgInfoPlural1', [quantity])}\n        <br/>\n        {i18n(giveaway.stars ? 'BoostingStarsGiveawayMsgInfoPlural2' : 'BoostingGiveawayMsgInfoPlural2', [giveaway.stars ? giveaway.quantity : headerDuration])}\n      </>\n    );\n  }\n\n  const renderEntity = (peerId: PeerId) => {\n    const entity = AppSelectPeers.renderEntity({\n      key: peerId,\n      middleware,\n      avatarSize: 30,\n      meAsSaved: false\n    });\n\n    setPeerColorToElement({peerId, element: entity.element});\n\n    entity.element.classList.add('bubble-giveaway-channel', 'hover-primary');\n\n    return entity.element;\n  };\n\n  const channelsWrapped = !isResults && (\n    <div class=\"bubble-giveaway-channels\">\n      <For each={giveaway.channels}>\n        {(chatId) => renderEntity(chatId.toPeerId(true))}\n      </For>\n    </div>\n  );\n\n  const countriesWrapped = countriesElements && (\n    <div class=\"bubble-giveaway-countries\">\n      {i18n(\n        'BoostingGiveAwayFromCountries',\n        [join(countriesElements)]\n      )}\n    </div>\n  );\n\n  let middle: JSX.Element;\n  if(isResults) {\n    middle = (\n      <>\n        <div class=\"bubble-giveaway-channels\">\n          <For each={giveaway.winners}>\n            {(userId) => renderEntity(userId.toPeerId(false))}\n          </For>\n        </div>\n        {giveaway.winners_count > giveaway.winners.length && (\n          <div class=\"bubble-giveaway-and-more\">\n            {i18n('Giveaway.Results.AndMore', [giveaway.winners_count - giveaway.winners.length])}\n          </div>\n        )}\n      </>\n    );\n  } else {\n    middle = (\n      <>\n        {i18n(\n          giveaway.pFlags.only_new_subscribers ?\n            'BoostingGiveawayMsgNewSubsPlural' :\n            'BoostingGiveawayMsgAllSubsPlural',\n          [giveaway.channels.length]\n        )}\n        {channelsWrapped}\n        {countriesWrapped}\n      </>\n    );\n  }\n\n  let stickerDiv: HTMLDivElement;\n  const ret = (\n    <div class={classNames('bubble-giveaway', 'no-select', 'disable-hover', isResults && 'bubble-giveaway-results')}>\n      <div ref={stickerDiv} class=\"bubble-giveaway-sticker\">\n        <div class={classNames('bubble-giveaway-sticker-counter', giveaway.stars && 'bubble-giveaway-sticker-counter-stars')}>\n          {giveaway.stars && <IconTsx icon=\"star\" />}\n          {giveaway.stars ? ` ${quantity}` : `X${quantity}`}\n        </div>\n      </div>\n      <div class=\"bubble-giveaway-row\">\n        <div class=\"bubble-giveaway-row-title\">{i18n(isResults ? 'Giveaway.Re