e(context.attachmentDiv);\n\n        const width = context.attachmentDiv.style.width;\n        if(width) {\n          bubbleContainer.style.maxWidth = `min(100%, ${width})`;\n        }\n      }\n\n      if(canHavePlainMediaTail && !withReplies) {\n        bubble.classList.add('has-plain-media-tail');\n      }\n    }\n\n    const isFloatingTime = timeSpan && ((isMessageEmpty && !context.mediaRequiresMessageDiv) || (invertMedia && !processedWebPage));\n    if(isMessageEmpty && !context.mediaRequiresMessageDiv) {\n      messageDiv.remove();\n      bubble.classList.add('is-message-empty');\n    } else {\n      if(context.attachmentDiv) {\n        context.attachmentDiv.classList.add(invertMedia ? 'no-brt' : 'no-brb');\n        messageDiv.classList.add(invertMedia ? 'mb-shorter' : 'mt-shorter');\n      }\n    }\n\n    if(isFloatingTime) {\n      timeSpan.classList.add('is-floating');\n      bubble.classList.add('has-floating-time');\n      // bubble.timeAppenders = [];\n      appendBubbleTime(bubble, bubbleContainer, () => bubbleContainer.append(timeSpan));\n    }\n\n    if(context.isStandaloneMedia) {\n      bubble.classList.add('just-media');\n    }\n\n    if(sponsoredMessage) {\n      const canReport = sponsoredMessage.pFlags.can_report;\n      const buttons = document.createElement('div');\n      buttons.classList.add('bubble-beside-button', 'bubble-beside-button-top');\n      let hideButton: HTMLElement;\n      if(canReport) {\n        buttons.classList.add('bubble-sponsored-buttons');\n        hideButton = ButtonIcon('close bubble-sponsored-buttons-button', {noRipple: true});\n        const hr = document.createElement('div');\n        hr.classList.add('bubble-sponsored-buttons-delimiter');\n        const menu = ButtonIcon('more bubble-sponsored-buttons-button', {noRipple: true});\n        buttons.append(hideButton, hr, menu);\n\n        attachClickEvent(menu, (e) => {\n          this.chat.contextMenu.onContextMenu(e as MouseEvent);\n        });\n      } else {\n        hideButton = buttons;\n        hideButton.append(Icon('close'));\n        buttons.classList.add('bubble-sponsored-hide');\n      }\n      bubbleContainer.prepend(buttons);\n      bubble.classList.add('with-beside-button');\n      attachClickEvent(hideButton, () => {\n        PopupPremium.show({feature: 'no_ads'});\n      });\n    }\n\n    let savedFrom = '';\n\n    if(context.isStandaloneMedia || !isOut || (message as Message.message).fwdFromId) {\n      setPeerColorToElement({\n        peerId: (message as Message.message).fwdFromId || message.fromId,\n        element: bubble,\n        messageHighlighting: context.isStandaloneMedia,\n        colorAsOut: isOut,\n        color: sponsoredMessage?.color\n      });\n    }\n\n    const showNameForVerificationCodes = isMessageForVerificationBot(message) && !message.pFlags.local;\n    // const needName = ((peerId.isAnyChat() && (peerId !== message.fromId || our)) && message.fromId !== rootScope.myId) || message.viaBotId;\n\n    const iPostedAsSomeoneElse = message.fromId !== rootScope.myId && !this.chat.isMonoforum;\n\n    // * a guest-chat message shows \"<bot> for <visitor>\" and the bot's avatar, even in a 1-on-1\n    const guestChatViaFromId = getGuestChatViaFromId(message);\n\n    const needName = ((iPostedAsSomeoneElse || !isOut) && this.chat.isLikeGroup) ||\n      message.viaBotId ||\n      storyFromPeerId ||\n      guestChatViaFromId ||\n      (showNameForVerificationCodes && !replyTo);\n\n    let nameDiv: HTMLElement;\n    if(needName || fwdFrom || replyTo) { // chat\n      let title: HTMLElement;\n      let titleVia: typeof title;\n      let noColor: boolean;\n      const peerIdForColor = message.fromId;\n\n\n      const isForwardFromChannel = message.from_id?._ === 'peerChannel' && message.fromId === fwdFromId;\n      const fwdFromName = getFwdFromName(fwdFrom);\n      const hasTwoTitles = _isForwardOfForward && !isOut && fwdFrom.from_name && fwdFrom.saved_from_name;\n\n      let mustHaveName = shouldKeepSenderNameAcrossGroup(isEphemeral, isOut) ||\n        !!message.viaBotId ||\n        storyFromPeerId;\n      const isHidden = !!(fwdFrom && (!fwdFrom.from_id || fwdFromName));\n      if(message.viaBotId) {\n        titleVia = document.createElement('span');\n        titleVia.innerText = '@' + (await this.managers.appPeersManager.getPeerUsername(message.viaBotId));\n        titleVia.classList.add('peer-title');\n      }\n\n      let isForward = !!(storyFromPeerId || fwdFromId || fwdFrom) && !showNameForVerificationCodes;\n      if(isForward && this.chat.type === ChatType.Saved && fwdFromId === rootScope.myId) {\n        isForward = false;\n      }\n\n      if(isHidden && !fwdFromId) {\n        title = document.createElement('span');\n        title.classList.add('peer-title');\n        setInnerHTML(title, wrapEmojiText(fwdFrom.from_name || fwdFromName));\n        bubble.classList.add('hidden-profile');\n      } else {\n        const titlePeerId = storyFromPeerId || fwdFromId || message.fromId;\n        title = this.createTitle(titlePeerId, wrapOptions, isForward).element;\n      }\n\n      let replyContainer: HTMLElement;\n      if(\n        isMessage &&\n        (\n          replyTo?._ === 'messageReplyStoryHeader' || (\n            message.reply_to_mid &&\n            message.reply_to_mid !== this.chat.threadId &&\n            message.reply_to_mid !== replyTo?.reply_to_top_id\n          ) || replyTo?.reply_from\n        ) &&\n        (!this.chat.isAllMessagesForum && !this.chat.isBotforum || this.chat.type === ChatType.Logs || (replyTo as MessageReplyHeader.messageReplyHeader).reply_to_top_id)\n      ) {\n        replyContainer = await MessageRender.setReply({\n          chat: this.chat,\n          bubble,\n          bubbleContainer,\n          logId,\n          message,\n          appendCallback: (container) => {\n            nameContainer.prepend(container);\n            if(!isMessageEmpty && (!context.attachmentDiv || invertMedia)) {\n              container.classList.add('mb-shorter');\n            }\n\n            if(context.attachmentDiv) {\n              context.attachmentDiv.classList.add('no-brt');\n            }\n          },\n          middleware,\n          lazyLoadQueue: this.lazyLoadQueue,\n          needUpdate: this.needUpdate,\n          isStandaloneMedia: context.isStandaloneMedia,\n          isOut\n        });\n      }\n\n      // this.log(title);\n\n      if(isForward) {\n        const isRegularSaved = this.peerId === rootScope.myId && (!this.chat.threadId || !isForwardOfForward(message) /* !isOut || this.chat.threadId === fwdFromId */);\n        if(!isRegularSaved && !isForwardFromChannel) {\n          bubble.classList.add('forwarded');\n        }\n\n        if((message as Message.message).savedFrom) {\n          savedFrom = (message as Message.message).savedFrom;\n          title.dataset.savedFrom = savedFrom;\n        }\n\n        nameDiv = document.createElement('div');\n        const titlePeerId = storyFromPeerId || fwdFromId;\n        title.dataset.peerId = '' + titlePeerId;\n\n        if(\n          (isRegularSaved || this.peerId === REPLIES_PEER_ID || isForwardFromChannel) &&\n          !context.isStandaloneMedia &&\n          !hasTwoTitles &&\n          !_isForwardOfForward &&\n          !storyFromPeerId\n        ) {\n          nameDiv.classList.add('colored-name');\n          nameDiv.append(title);\n        } else {\n          mustHaveName ||= true;\n          bubble.classList.remove('hide-name');\n          const firstArgs: FormatterArguments = [title];\n\n          if(titlePeerId) {\n            const avatar = avatarNew({\n              middleware,\n              size: 20,\n              lazyLoadQueue: this.lazyLoadQueue,\n              peerId: titlePeerId,\n              isDialog: false\n            });\n\n            avatar.node.classList.add('bubble-name-forwarded-avatar');\n            // loadPromises.push(avatar.readyThumbPromise);\n            firstArgs.unshift(avatar.node);\n          } else {\n            title.classList.add('text-normal');\n          }\n\n          if(context.isStandaloneMedia || true) {\n            const br = document.createElement('br');\n            br.classList.add('hide-ol');\n            firstArgs.unshift(br);\n          }\n\n          let nameKey: LangPackKey;\n          const nameArgs: FormatterArguments = [firstArgs];\n          if(fwdFrom?.post_author) {\n            nameKey = storyFromPeerId ? 'ForwardedStoryFromAuthor1' : 'ForwardedFromAuthor';\n            const s = document.createElement('span');\n            s.append(wrapEmojiText(fwdFrom.post_author));\n            nameArgs.push(s);\n          } else {\n            nameKey = storyFromPeerId ? 'ForwardedStoryFrom1' : 'ForwardedFrom';\n          }\n\n          const span = i18n(nameKey, nameArgs);\n          span.classList.add('bubble-name-forwarded');\n          nameDiv.append(span);\n\n          if(hasTwoTitles) {\n            let title: HTMLElement;\n            if(fwdFromName) {\n              title = document.createElement('span');\n              title.classList.add('peer-title');\n              title.style.color = 'var(--message-primary-color)';\n              title.dataset.peerId = '' + NULL_PEER_ID;\n              title.append(wrapEmojiText(fwdFromName));\n            } else {\n              const peerId = getPeerId(fwdFrom.saved_from_id);\n              const {element, textColorProperty} = this.createTitle(peerId, wrapOptions, false);\n              element.style.color = `rgb(var(--${textColorProperty}))`;\n              title = element;\n            }\n\n            const line = document.createElement('div');\n            line.classList.add('name-first-line');\n            line.append(title);\n            nameDiv.prepend(line);\n          }\n        }\n      } else if(!message.viaBotId) {\n        if(shouldRenderSenderNameWithEphemeralBadge(\n          !!needName,\n          context.isStandaloneMedia,\n          isEphemeral\n        )) {\n          nameDiv = document.createElement('div');\n          nameDiv.append(title);\n\n          if(!noColor) {\n            const peer = apiManagerProxy.getPeer(peerIdForColor);\n            const pFlags = (peer as User.user)?.pFlags;\n            if(pFlags && (pFlags.scam || pFlags.fake)) {\n              nameDiv.append(generateFakeIcon(pFlags.scam));\n            }\n\n            if(!our) {\n              nameDiv.classList.add('colored-name');\n            }\n\n            nameDiv.dataset.peerId = '' + peerIdForColor;\n          }\n        } else /* if(!message.reply_to_mid) */ {\n          bubble.classList.add('hide-name');\n        }\n      }\n\n      if(message.viaBotId) {\n        if(!nameDiv) {\n          nameDiv = document.createElement('div');\n        } else {\n          nameDiv.append(' ');\n        }\n\n        const span = document.createElement('span');\n        span.append(i18n('ViaBot'), ' ', titleVia);\n        span.classList.add('is-via');\n\n        nameDiv.append(span);\n      }\n\n      // * append \"for <visitor>\" after the guest bot's name; the visitor title opens its profile on click.\n      // * plain first name, no premium/status icons — those add `.peer-title.with-icons` (display: flex,\n      // * i.e. block), which would drop the visitor onto its own line\n      if(guestChatViaFromId) {\n        if(!nameDiv) {\n          nameDiv = document.createElement('div');\n        } else {\n          nameDiv.append(' ');\n        }\n\n        const visitorTitle = new PeerTitle({peerId: guestChatViaFromId, onlyFirstName: true, wrapOptions}).element;\n        const span = document.createElement('span');\n        span.classList.add('is-guest-chat-for');\n        span.append(i18n('GuestChatFor'), ' ', visitorTitle);\n\n        nameDiv.append(span);\n        bubble.classList.remove('hide-name');\n      }\n\n      if(nameDiv && !bubble.classList.contains('hide-name')) {\n        nameDiv.classList.add('name');\n        setDirection(nameDiv);\n\n        const updateMessageDiv = (insertedElement: HTMLElement) => {\n          if(messageDiv && insertedElement.nextElementSibling === messageDiv) {\n            insertedElement.classList.add('next-is-message');\n          }\n        };\n\n        if(context.isStandaloneMedia) {\n          const newNameContainer = document.createElement('div');\n          newNameContainer.classList.add('name-with-reply', 'floating-part');\n          nameContainer.prepend(newNameContainer);\n          updateMessageDiv(newNameContainer);\n          nameContainer = newNameContainer;\n        } else {\n          nameDiv.classList.add('floating-part');\n        }\n\n        nameContainer.prepend(nameDiv);\n        if(!context.isStandaloneMedia) {\n          updateMessageDiv(nameDiv);\n        }\n\n        if(context.isStandaloneMedia && replyContainer) {\n          nameDiv.after(replyContainer);\n        }\n      } else if(context.isStandaloneMedia && replyContainer) {\n        replyContainer.classList.add('floating-part');\n      }\n\n      const firstElement = nameDiv?.firstElementChild as HTMLElement || title;\n      if(\n        this.canShowRanks &&\n        title &&\n        !isHidden &&\n        !fwdFromId\n        // (!fwdFromId || (message.post_author && !this.chat.getPostAuthor(message)))\n      ) {\n        const processRank = () => {\n          const rank = this.ranks.get(message.fromId);\n          if(!rank && !(message as Message.message).from_boosts_applied) {\n            return;\n          }\n\n          this.wrapTitleAndRank(firstElement, message as Message.message, rank);\n        };\n\n        const postAuthor = hasPostAuthor && (message as Message.message).post_author/*  || fwdFrom?.post_author */;\n        if(postAuthor) {\n          this.wrapTitleAndRank(firstElement, message, postAuthor);\n        } else if(this.ranks) {\n          processRank();\n        } else {\n          const processRanks = this.processRanks;\n          processRanks.add(processRank);\n\n          middleware.onDestroy(() => {\n            processRanks.delete(processRank);\n          });\n        }\n      } else if(this.chat.isMegagroup && !message.fromId.isUser() && (message as Message.message).views) {\n        this.wrapTitleAndRank(firstElement, message as Message.message, 0);\n      }/*  else if((message as Message.message).from_boosts_applied) {\n        this.wrapTitleAndRank(firstElement, message as Message.message);\n      } */\n\n      if(mustHaveName) {\n        bubble.classList.add('must-have-name');\n      }\n    } else {\n      bubble.classList.add('hide-name');\n    }\n\n    if(this.chat.type === ChatType.Pinned) {\n      savedFrom = makeFullMid(this.chat.peerId, message.mid);\n    }\n\n    const isThreadStarter = messageWithReplies && messageWithReplies.mid === this.chat.threadId;\n    if(isThreadStarter) {\n      bubble.classList.add('is-thread-starter', 'is-group-last');\n    }\n\n    if(savedFrom && (this.chat.type === ChatType.Pinned || fwdFrom.saved_from_msg_id) && this.peerId !== REPLIES_PEER_ID) {\n      const goto = document.createElement('div');\n      goto.classList.add('bubble-beside-button', 'with-hover', 'goto-original');\n      goto.append(Icon('arrow_next'));\n      bubbleContainer.append(goto);\n      bubble.dataset.savedFrom = savedFrom;\n      bubble.classList.add('with-beside-button');\n    }\n\n    if(isEphemeral) {\n      const badge = this.createEphemeralBadge(message, wrapOptions);\n      placeEphemeralBadge(\n        bubbleContainer,\n        nameDiv,\n        badge,\n        context.isStandaloneMedia\n      );\n    }\n\n    bubble.classList.add(isOut ? 'is-out' : 'is-in');\n\n    // * reserve room for the forced guest-bot avatar in 1-on-1 chats (group chats already indent)\n    if(guestChatViaFromId) {\n      bubble.classList.add('is-guest-chat');\n\n      // * explain what a guest bot is when its first message scrolls into view — up to twice, like iOS.\n      // * iOS shows this in any chat type (not just 1-on-1), so there's no peer-type gate here\n      if(this.observer && !this.guestChatHintShown && (this.chat.appSettings.seenTooltips.guestBotPrivacy || 0) < 2) {\n        this.observer.observe(bubble, this.guestChatHintObserverCallback);\n      }\n    }\n\n    if(withReplies) {\n      const isFooter = MessageRender.renderReplies({\n        bubble,\n        bubbleContainer,\n        message: messageWithReplies,\n        messageDiv,\n        loadPromises,\n        lazyLoadQueue: this.lazyLoadQueue,\n        middleware\n      });\n\n      if(isFooter) {\n        context.canHaveTail = true;\n      } else {\n        bubble.classList.add('with-beside-replies');\n      }\n    } else if(isMessage && message.replies && this.chat.isAnyGroup) {\n      const replies = message.replies;\n      this.setBubbleRepliesCount(bubble, replies.replies);\n    }\n\n    if(!previewOnly && hasReactions && this.chat.type !== ChatType.Logs) {\n      this.appendReactionsElementToBubble(bubble, message, reactionsMessage, undefined, loadPromises);\n    }\n\n    if(context.canHaveTail && !isRound) {\n      bubble.classList.add('can-have-tail');\n    }\n    if(context.canHaveTail || isRound) {\n      bubbleContainer.append(generateTail());\n    }\n\n    if(!previewOnly && our && (this.peerId !== rootScope.myId || isOut)) {\n      if(!isEphemeral && (message.pFlags.unread || context.isOutgoing)) this.unreadOut.add(message.mid);\n      let status: Parameters<ChatBubbles['setBubbleSendingStatus']>[1];\n      if(message.error) status = 'error';\n      else if(context.isOutgoing) status = 'sending';\n      else if(isEphemeral) status = 'sent';\n      else status = message.pFlags.unread || (message as Message.message).pFlags.is_scheduled ? 'sent' : 'read';\n\n      if(isOut || (status !== 'sent' && status !== 'read')) {\n        this.setBubbleSendingStatus(bubble, status, true);\n      }\n    }\n\n    if(isMessage) {\n      createRoot((dispose) => {\n        middleware.onDestroy(dispose);\n\n        createEffect(() => {\n          bubble.classList.toggle('no-forwards', !this.canForward(message));\n        });\n      });\n    }\n\n    if(!isEphemeral && !previewOnly && isMessage && message.effect && (context.isInUnread || context.isOutgoing)) {\n      this.observer.observe(bubble, this.messageEffectObserverCallback);\n    }\n\n\n    if(isRound) {\n      wrapRoundVideoBubble({\n        bubble,\n        message: message as Message.message,\n        globalMediaDeferred,\n        searchContext\n      });\n    }\n\n    if(!previewOnly && this.sponsoredAfterMids.size > 0) {\n      const sponsoredMessageAfterMid = groupedMids ? groupedMids.find(it => this.sponsoredAfterMids.has(it)) : message.mid\n      const sponsoredMessage = this.sponsoredAfterMids.get(sponsoredMessageAfterMid);\n      if(sponsoredMessage) {\n        const sponsoredBubblePromise = this.safeRenderMessage({\n          message: sponsoredMessage,\n          reverse: false,\n          updatePosition: false,\n          processResult: async(res) => {\n            const bubble = (await res).bubble;\n            (bubble as any).message = sponsoredMessage;\n            ret.bubble.appendChild(bubble);\n            return res\n          },\n          canAnimateLadder: true\n        });\n        ret.promises.push(sponsoredBubblePromise);\n      }\n    }\n\n    this.addMessageSpoilerOverlay({\n      mid: message.mid,\n      messageDiv,\n      middleware,\n      loadPromises,\n      canTranslate\n    });\n\n    return ret;\n  }\n\n  private async addMessageSpoilerOverlay({mid, messageDiv, middleware, loadPromises, canTranslate}: AddMessageSpoilerOverlayArgs) {\n    if(IS_FIREFOX) return; // Firefox has very poor performance when drawing on canvas\n    if(canTranslate && loadPromises) await Promise.all(loadPromises); // TranslatableMessage delays the moment when content appears in the DOM\n\n    if(!messageDiv.querySelector('.spoiler-text')) return;\n\n    const spoilerOverlay = createMessageSpoilerOverlay({\n      mid: mid,\n      messageElement: messageDiv,\n      animationGroup: this.chat.animationGroup\n    }, SolidJSHotReloadGuardProvider);\n\n    messageDiv.append(spoilerOverlay.element);\n    middleware.onDestroy(() => {\n      spoilerOverlay.dispose();\n    });\n\n    await Promise.all(loadPromises);\n    spoilerOverlay.controls.update(); // For chats that have custom theme differing from the one from settings\n  }\n\n  public canForward(message: Message.message | Message.messageService) {\n    if(message?._ !== 'message' || message.pFlags.noforwards || isEphemeralMessage(message)) {\n      return false;\n    }\n\n    if(message.peerId.isUser()) {\n      const userFull = this.chat.fullPeer() as UserFull;\n      if(userFull?.pFlags?.noforwards_my_enabled || userFull?.pFlags?.noforwards_peer_enabled) {\n        return false;\n      }\n      return true;\n    }\n\n    if((usePeer(message.peerId) as MTChat.channel).pFlags.noforwards) {\n      return false;\n    }\n\n    return true;\n  }\n\n  private appendReactionsElementToBubble(\n    bubble: HTMLElement,\n    message: Message.message | Message.messageService,\n    reactionsMessage: Message.message | Message.messageService,\n    changedResults?: ReactionCount[],\n    loadPromises?: Promise<any>[]\n  ) {\n    if(this.peerId.isUser() && USER_REACTIONS_INLINE/*  || true */) {\n      return;\n    }\n\n    if(!reactionsMessage?.reactions || !reactionsMessage.reactions.results.length) {\n      return;\n    }\n\n    // message = this.appMessagesManager.getMessageWithReactions(message);\n\n    const reactionsElement = new ReactionsElement();\n    reactionsElement.init({\n      context: reactionsMessage,\n      type: ReactionLayoutType.Block,\n      middleware: bubble.middlewareHelper.get(),\n      animationGroup: this.chat.animationGroup,\n      lazyLoadQueue: this.lazyLoadQueue\n    });\n    reactionsElement.render(changedResults);\n\n    if(bubble.classList.contains('has-floating-time') || bubble.classList.contains('service')) {\n      bubble.querySelector('.bubble-content-wrapper').append(reactionsElement);\n    } else {\n      const timeSpan = bubble.timeSpan;\n      const messageDiv = bubble.querySelector('.message');\n\n      appendBubbleTime(bubble, reactionsElement, () => reactionsElement.append(timeSpan));\n\n      if(bubble.classList.contains('is-multiple-documents')) {\n        const documentContainer = messageDiv.lastElementChild as HTMLElement;\n        let documentMessageDiv = documentContainer.querySelector('.document-message');\n\n        if(!documentMessageDiv) {\n          documentMessageDiv = document.createElement('div');\n          documentMessageDiv.classList.add('document-message');\n          documentContainer.querySelector('.document-wrapper').append(documentMessageDiv);\n        }\n\n        documentMessageDiv.append(reactionsElement);\n      } else {\n        messageDiv.append(reactionsElement);\n      }\n    }\n  }\n\n  private setStoryContainerDimensions(container: HTMLElement) {\n    const ratio = 9 / 16;\n    const height = 256;\n    const width = height * ratio;\n    container.style.width = `${width}px`;\n    container.style.height = `${height}px`;\n  }\n\n  private async getStoryReplyIfExpired(storyPeerId: PeerId, storyId: number, isWebPage: boolean, noBorder?: boolean) {\n    const result = await this.managers.acknowledged.appStoriesManager.getStoryById(storyPeerId, storyId);\n    if(result.cached && !(await result.result)) {\n      if(isWebPage) {\n        return null;\n      }\n\n      const peerTitle = await wrapPeerTitle({peerId: storyPeerId});\n      const {container, fillPromise} = wrapReply({\n        title: isWebPage ? peerTitle : undefined,\n        subtitle: isWebPage ? undefined : i18n('ExpiredStorySubtitle', [peerTitle]),\n        isStoryExpired: true,\n        isChatSensitive: this.chat.isSensitive,\n        noBorder\n      });\n\n      return container;\n    }\n  }\n\n  private wrapSomeSolid(func: () => JSX.Element, container: HTMLElement, middleware: Middleware) {\n    const dispose = render(func, container);\n    middleware.onClean(dispose);\n  }\n\n  private wrapStory({\n    message,\n    bubble,\n    storyPeerId: peerId,\n    storyId,\n    container,\n    middleware,\n    loadPromises,\n    boxWidth,\n    boxHeight\n  }: {\n    message: Message.message,\n    bubble: HTMLElement,\n    storyPeerId: PeerId,\n    storyId: number,\n    container: HTMLElement,\n    middleware: Middleware,\n    loadPromises: Promise<any>[],\n    boxWidth?: number,\n    boxHeight?: number\n  }) {\n    container.dataset.storyPeerId = '' + peerId;\n    container.dataset.storyId = '' + storyId;\n    this.wrapSomeSolid(() => {\n      return StoryPreview({\n        message,\n        peerId,\n        storyId,\n        boxWidth,\n        boxHeight,\n        lazyLoadQueue: this.lazyLoadQueue,\n        // group: this.chat.animationGroup,\n        autoDownload: this.chat.autoDownload,\n        loadPromises,\n        canAutoplay: false,\n        onExpiredStory: async() => {\n          await getHeavyAnimationPromise(); // wait for scroll to end\n          message = this.chat.getMessageByPeer(message.peerId, message.mid) as Message.message;\n          this.safeRenderMessage({\n            message,\n            reverse: true,\n            bubble\n          });\n        },\n        withPreloader: true\n      });\n    }, container, middleware);\n  }\n\n  private wrapTitleAndRank(\n    title: HTMLElement,\n    message: Message.message,\n    rank?: Parameters<ChatBubbles['createBubbleNameRank']>[0]\n  ) {\n    const wrappedRank = rank !== undefined && this.createBubbleNameRank(rank);\n    // title.after(wrappedRank);\n    const container = document.createElement('div');\n    container.classList.add('title-flex');\n    title.replaceWith(container);\n    let boostsElement: HTMLElement;\n    const boosts = message.from_boosts_applied;\n    if(boosts) {\n      boostsElement = document.createElement('span');\n      boostsElement.classList.add('bubble-name-boosts');\n      boostsElement.append(Icon('boosts_filled', 'inline-icon', 'bubble-name-boosts-icon'), '' + boosts);\n    }\n    title.classList.add('bubble-name-first');\n    container.append(...[title, wrappedRank, boostsElement].filter(Boolean));\n  }\n\n  private createBubbleNameRank(rank: Parameters<typeof wrapParticipantRank>[0]) {\n    const span = document.createElement('span');\n    span.classList.add('bubble-name-rank');\n    span.append(wrapParticipantRank(rank));\n    return span;\n  }\n\n  private createTitle(peerId: PeerId, wrapOptions: WrapSomethingOptions, isForward?: boolean) {\n    const colorIndex = getPeerColorIndexByPeer(apiManagerProxy.getPeer(peerId));\n    let textColorProperty: string;\n    if(colorIndex !== -1) {\n      textColorProperty = `peer-${colorIndex}-color-rgb`;\n    }\n\n    return {\n      element: new PeerTitle({\n        peerId,\n        withPremiumIcon: !isForward,\n        wrapOptions: {\n          ...wrapOptions,\n          textColor: textColorProperty\n        }\n      }).element,\n      textColorProperty\n    };\n  }\n\n  private createEphemeralBadge(\n    message: MyEphemeralMessage,\n    wrapOptions: WrapSomethingOptions\n  ) {\n    const container = document.createElement('div');\n    container.classList.add('ephemeral-badge-container', 'bubble-name-chip-container');\n\n    const badge = document.createElement('div');\n    badge.classList.add('ephemeral-badge');\n    badge.setAttribute('role', 'note');\n    badge.title = I18n.format('Ephemeral.About', true);\n    badge.append(Icon('eyecross', 'ephemeral-badge-icon'));\n\n    if(message.pFlags.out) {\n      const receiverPeerId = message.ephemeral_receiver_id.toPeerId(false);\n      const receiver = apiManagerProxy.getPeer(receiverPeerId);\n      const receiverTitle = new PeerTitle({\n        peerId: receiverPeerId,\n        username: !!getPeerActiveUsernames(receiver)[0],\n        dialog: false,\n        wrapOptions\n      }).element;\n      receiverTitle.classList.add('ephemeral-badge-peer');\n      badge.append(i18n('Ephemeral.VisibleTo', [receiverTitle]));\n    } else {\n      badge.append(i18n('Ephemeral.VisibleYou'));\n    }\n\n    container.append(badge);\n    return container;\n  }\n\n  private prepareToSaveScroll(reverse?: boolean, sliceTop?: boolean, sliceBottom?: boolean) {\n    const isMounted = !!this.chatInner.parentElement;\n    if(!isMounted) {\n      return {};\n    }\n\n    const log = this.log.bindPrefix('prepareToSaveScroll');\n    log('save');\n    const scrollSaver = this.createScrollSaver(reverse);\n    scrollSaver.save(); // * let's save scroll position by point before the slicing, not after\n\n    if((sliceTop || sliceBottom) && this.getRenderedLength() && !this.chat.setPeerPromise) {\n      const viewportSlice = this.getViewportSlice(true);\n      if(!sliceTop) viewportSlice.invisibleTop.length = 0;\n      if(!sliceBottom) viewportSlice.invisibleBottom.length = 0;\n      this.deleteViewportSlice(viewportSlice, true);\n    }\n\n    // scrollSaver.save(); // ! slicing will corrupt scroll position\n    // const saved = scrollSaver.getSaved();\n    // const hadScroll = saved.scrollHeight !== saved.clientHeight;\n\n    return {\n      restoreScroll: () => {\n        log('restore');\n        // scrollSaver.restore(_history.length === 1 && !reverse ? false : true);\n        scrollSaver.restore(reverse);\n        this.onRenderScrollSet(scrollSaver.getSaved());\n      },\n      scrollSaver\n    };\n  }\n\n  public async performHistoryResult(\n    historyResult: LocalHistoryResult | {history: (Message.message | Message.messageService | number)[]},\n    reverse: boolean,\n    includeEphemeralHistory = false\n  ) {\n    const log = false || true ? this.log.bindPrefix('perform-' + (Math.random() * 1000 | 0)) : undefined;\n    log?.('start', this.chatInner.parentElement, historyResult);\n\n    let history: (Message.message | Message.messageService | AdminLog | number)[] = (historyResult as LocalHistoryResult).messages || historyResult.history;\n    history = history.slice(); // need\n\n    if(this.needReflowScroll) {\n      reflowScrollableElement(this.scrollable.container);\n      this.needReflowScroll = false;\n    }\n\n    const cb = (message: Message.message | Message.messageService | AdminLog) => {\n      if(!message) {\n        return;\n      } else if(isMessage(message) && message.pFlags.local) {\n        return this.processLocalMessageRender(message);\n      } else {\n        return this.safeRenderMessage({\n          message,\n          reverse,\n          canAnimateLadder: true\n        });\n      }\n    };\n\n    let isEnd: HistoryResult['isEnd'];\n    if(!this.scrollable.loadedAll['bottom'] || !this.scrollable.loadedAll['top']) {\n      isEnd = (historyResult as HistoryResult).isEnd;\n      if(!isEnd) {\n        const historyStorage = this.chat.getHistoryStorage();\n        const firstSlice = historyStorage.history.first;\n        const lastSlice = historyStorage.history.last;\n        isEnd = {top: false, bottom: false, both: false};\n        if(firstSlice.isEnd(SliceEnd.Bottom) && (!firstSlice.length || history.includes(firstSlice[0]))) {\n          isEnd.bottom = true;\n        }\n\n        if(lastSlice.isEnd(SliceEnd.Top) && (!lastSlice.length || history.includes(lastSlice[lastSlice.length - 1]))) {\n          isEnd.top = true;\n        }\n      }\n\n      if(!isEnd.bottom && this.setPeerOptions) {\n        const {lastMsgFullMid, topMessageFullMid, savedPosition} = this.setPeerOptions;\n        this.setPeerOptions = undefined;\n        // ! warning\n        if((lastMsgFullMid === EMPTY_FULL_MID && !savedPosition?.mids) || (topMessageFullMid !== EMPTY_FULL_MID && this.getBubble(topMessageFullMid)) || lastMsgFullMid === topMessageFullMid) {\n          isEnd.bottom = true;\n        }\n      }\n    }\n\n    const ephemeralMessages = await mergeEphemeralHistoryForRender(\n      history,\n      includeEphemeralHistory &&\n        !this.ephemeralHistoryLoaded &&\n        (this.chat.type === ChatType.Chat || this.chat.type === ChatType.Discussion) &&\n        (this.scrollable.loadedAll.bottom || !!isEnd?.bottom),\n      () => this.getEphemeralHistoryMessages()\n    );\n    if(ephemeralMessages.length) {\n      ++this.pendingEphemeralHistory;\n    }\n\n    const messages = /* await Promise.all */(history.map((mid) => {\n      return typeof(mid) === 'number' ? this.chat.getMessage(mid) : mid;\n    }));\n\n    const setLoadedPromises: Promise<any>[] = [];\n    if(isEnd?.top) {\n      setLoadedPromises.push(this.setLoaded('top', true));\n    }\n    if(isEnd?.bottom) {\n      setLoadedPromises.push(this.setLoaded('bottom', true));\n    }\n\n    if(setLoadedPromises.length) {\n      await Promise.all(setLoadedPromises);\n    }\n\n    if(this.sponsoredMessageEvery && this.sponsoredMessagesAvailable.length) {\n      const [readMaxId, chatMaxId] = await Promise.all([\n        this.managers.appMessagesManager.getReadMaxIdIfUnread(this.chat.peerId, this.chat.threadId),\n        this.chat.getHistoryMaxId()\n      ])\n      let prevGroupedId: Long | undefined\n\n      for(const mid_ of history) {\n        if(typeof mid_ === 'object' && mid_?._ === 'channelAdminLogEvent') continue;\n        const mid = typeof(mid_) === 'number' ? mid_ : mid_.mid;\n        if(mid <= readMaxId) continue\n\n        const msg = typeof mid_ === 'number' ? this.chat.getMessage(mid) : mid_;\n        const groupedId = msg._ === 'message' ? msg.grouped_id : undefined;\n        if(groupedId && prevGroupedId === groupedId) continue\n\n        prevGroupedId = groupedId\n        let add = 1\n        if(!groupedId && (\n          msg._ === 'messageService' ||\n          (msg._ === 'message' && !msg.media && msg.message.length < 100)\n        )) {\n          add = 0.2\n        }\n\n        this.messagesSinceLastSponsored += add;\n\n        const addOffset = (reverse ? 1 : 0) // because we display *after* and reverse is before\n        if(this.messagesSinceLastSponsored >= (this.sponsoredMessageEvery + addOffset)) {\n          this.messagesSinceLastSponsored = 0;\n          this.log('will render sponsored message after mid', mid);\n          this.sponsoredAfterMids.set(mid, this.sponsoredMessagesAvailable.shift())\n          if(!this.sponsoredMessagesAvailable.length) break\n        }\n      }\n    }\n\n    let promises: Promise<any>[] = [];\n    if(this.chat.type === ChatType.Search && false) {\n      const length = history.length;\n      if(reverse) for(let i = 0; i < length; ++i) promises.push(cb(messages[i]));\n      else for(let i = length - 1; i >= 0; --i) promises.push(cb(messages[i]));\n    } else {\n      promises = messages.map(cb);\n    }\n\n    try {\n      // cannot combine them into one promise\n      promises.length && await Promise.all(promises);\n      await this.messagesQueuePromise;\n    } finally {\n      if(ephemeralMessages.length) {\n        this.pendingEphemeralHistory = Math.max(0, this.pendingEphemeralHistory - 1);\n      }\n    }\n\n    if(ephemeralMessages.length) {\n      this.updateHasMessages();\n    }\n\n    // * have to check again, because it can be skipped above\n    const placeholderPromise = this.checkIfEmptyPlaceholderNeeded();\n    placeholderPromise && await placeholderPromise;\n    this.messagesQueuePromise && await this.messagesQueuePromise;\n\n    if(this.scrollable.loadedAll.top && this.messagesQueueOnRenderAdditional) {\n      this.messagesQueueOnRenderAdditional();\n      this.messagesQueueOnRenderAdditional?.(); // * can set it second time\n    }\n\n    log?.('performHistoryResult end');\n  }\n\n  private onRenderScrollSet(state?: {scrollHeight: number, clientHeight: number}) {\n    const className = 'has-sticky-dates';\n    if(!this.container.classList.contains(className)) {\n      const isLoading = !this.preloader.detached;\n\n      if(isLoading ||\n        (\n          state ??= {\n            scrollHeight: this.scrollable.scrollSize,\n            clientHeight: this.scrollable.clientSize\n          },\n          state.scrollHeight !== state.clientHeight\n        )\n      ) {\n        /* for(const timestamp in this.dateMessages) {\n          const dateMessage = this.dateMessages[timestamp];\n          dateMessage.div.classList.add('is-sticky');\n        } */\n\n        const middleware = this.getMiddleware();\n        const callback = () => {\n          if(!middleware()) return;\n          this.container.classList.add(className);\n        };\n\n        if(this.willScrollOnLoad) {\n          callback();\n        } else {\n          setTimeout(callback, 600);\n        }\n\n        return;\n      }\n    }\n\n    this.willScrollOnLoad = undefined;\n  }\n\n  public onDatePick = (timestamp: number) => {\n    const peerId = this.peerId;\n    this.managers.appMessagesManager.requestHistory({\n      ...this.chat.requestHistoryOptionsPart,\n      offsetId: 0,\n      limit: 2,\n      addOffset: -1,\n      offsetDate: timestamp\n    }).then((history) => {\n      if(!history?.messages?.length) {\n        this.log.error('no history!');\n        return;\n      } else if(this.peerId !== peerId) {\n        return;\n      }\n\n      this.chat.setMessageId({lastMsgId: (history.messages[0] as MyMessage).mid});\n      // console.log('got history date:', history);\n    });\n  };\n\n  public requestHistory(offsetId: number | FullMid, limit: number, backLimit: number): Promise<AckedResult<LocalHistoryResult>>  {\n    let offsetPeerId: PeerId;\n    if(typeof(offsetId) === 'string') {\n      const {peerId, mid} = splitFullMid(offsetId);\n      offsetPeerId = peerId;\n      offsetId = mid;\n    }\n\n    if(this.chat.type === ChatType.Logs) {\n      return Promise.resolve({\n        cached: false,\n        result: (async() => {\n          const {peerId} = this.chat;\n\n          const {items: logs, isStart, isEnd} = await this.managers.appChatsManager.getAdminLogs({\n            channelId: peerId.toChatId(),\n            search: this.inChatQuery,\n            admins: this.committedLogsFilters?.admins,\n            flags: this.committedLogsFilters?.flags,\n            offsetId,\n            limit,\n            backLimit\n          });\n\n          return {\n            history: logs.map(log => +log.id),\n            count: logs.length,\n            messages: logs,\n            isEnd: {\n              both: isStart && isEnd,\n              bottom: isStart,\n              top: isEnd\n            }\n          };\n        })()\n      });\n    } else if(this.chat.type === ChatType.Static) {\n      return Promise.resolve({\n        cached: true,\n        result: Promise.resolve({\n          history: this.chat.staticMessages?.map(message => message.mid) || [],\n          count: this.chat.staticMessages?.length || 0,\n          messages: this.chat.staticMessages || [],\n          isEnd: {\n            both: true,\n            bottom: true,\n            top: true\n          }\n        })\n      });\n    } else if([ChatType.Chat, ChatType.Discussion, ChatType.Saved, ChatType.Search].includes(this.chat.type)) {\n      return this.managers.acknowledged.appMessagesManager.getHistory({\n        ...this.chat.requestHistoryOptionsPart,\n        offsetPeerId,\n        offsetId,\n        limit,\n        backLimit\n      });\n    } else if(this.chat.type === ChatType.Pinned) {\n      return this.managers.acknowledged.appMessagesManager.getHistory({\n        peerId: this.peerId,\n        inputFilter: {_: 'inputMessagesFilterPinned'},\n        // thread-scoped in a forum topic, like `getPinnedMessagesMaxId` above\n        threadId: this.chat.threadId,\n        offsetPeerId,\n        offsetId,\n        limit,\n        backLimit\n      });\n    } else if(this.chat.type === ChatType.Scheduled) {\n      return this.managers.acknowledged.appMessagesManager.getScheduledMessages(this.peerId).then((ackedResult) => {\n        return {\n          cached: ackedResult.cached,\n          result: Promise.resolve(ackedResult.result).then((mids) => {\n            return {\n              history: mids.slice().reverse(),\n              count: mids.length,\n              isEnd: {\n                both: true,\n                bottom: true,\n                top: true\n              }\n            };\n          })\n        };\n      });\n    }\n  }\n\n  private async animateAsLadder(additionalFullMid: FullMid, additionalFullMids: FullMid[], isAdditionalRender: boolean, backLimit: number, maxId: FullMid) {\n    /* const middleware = this.getMiddleware();\n    await this.ladderDeferred; */\n\n    const log = this.log.bindPrefix('ladder');\n    if(this.chat.setPeerPromise && !this.resolveLadderAnimation) {\n      log.warn('will be delayed');\n      // @ts-ignore\n      this.resolveLadderAnimation = this.animateAsLadder.bind(this, additionalFullMid, additionalFullMids, isAdditionalRender, backLimit, maxId);\n      return;\n    }\n\n    /* if(!middleware()) {\n      return;\n    } */\n\n    const fullMids = this.getRenderedHistory('desc');\n\n    if(!fullMids.length) {\n      log.warn('no bubbles');\n      return;\n    }\n\n    let sortedFullMids = fullMids.slice();\n\n    if(isAdditionalRender && additionalFullMids.length) {\n      sortedFullMids = sortedFullMids.filter((fullMid) => !additionalFullMids.includes(fullMid));\n    }\n\n    let targetMid: FullMid;\n    if(backLimit) {\n      targetMid = maxId || sortedFullMids[0]; // * on discussion enter\n    } else {\n      if(additionalFullMid) {\n        targetMid = additionalFullMid;\n      } else { // * if maxId === 0\n        targetMid = sortedFullMids[0];\n      }\n    }\n\n    const topIds = sortedFullMids.slice(sortedFullMids.findIndex((mid) => targetMid > mid));\n    const middleIds = isAdditionalRender ? [] : [targetMid];\n    const bottomIds = isAdditionalRender ? [] : sortedFullMids.slice(0, sortedFullMids.findIndex((mid) => targetMid >= mid)).reverse();\n\n    if(DEBUG) {\n      log('targeting mid:', targetMid, maxId, additionalFullMid, topIds, bottomIds);\n    }\n\n    const setBubbles: HTMLElement[] = [];\n\n    this.chatInner.classList.add('zoom-fading');\n    const delay = isAdditionalRender ? 10 : 40;\n    const offsetIndex = isAdditionalRender ? 0 : 1;\n    const animateAsLadder = (fullMids: string[], offsetIndex = 0) => {\n      const animationPromise = deferredPromise<void>();\n      let lastMsDelay = 0;\n      fullMids.forEach((fullMid, idx) => {\n        const bubble = this.getBubble(fullMid);\n        if(!bubble || this.skippedMids.has(fullMid)) {\n          log.warn('no bubble by mid:', fullMid);\n          return;\n        }\n\n        lastMsDelay = ((idx + offsetIndex) || 0.1) * delay;\n        // lastMsDelay = (idx + offsetIndex) * delay;\n        // lastMsDelay = (idx || 0.1) * 1000;\n\n        const contentWrapper = bubble.lastElementChild as HTMLElement;\n        if(!contentWrapper) {\n          log.warn('bubble not ready yet', fullMid, this.batchProcessor);\n          return;\n        }\n\n        const elementsToAnimate: HTMLElement[] = [contentWrapper];\n        const item = this.bubbleGroups.getItemByBubble(bubble);\n        if(item && item.group.avatar && item.group.lastItem === item) {\n          elementsToAnimate.push(item.group.avatar.node);\n        }\n\n        elementsToAnimate.forEach((element) => {\n          element.classList.add('zoom-fade', 'can-zoom-fade');\n          element.style.setProperty('transition-delay', lastMsDelay + 'ms', 'important');\n        });\n\n        if(idx === (fullMids.length - 1)) {\n          const onTransitionEnd = (e: TransitionEvent) => {\n            if(e.target !== contentWrapper) {\n              return;\n            }\n\n            animationPromise.resolve();\n            contentWrapper.removeEventListener('transitionend', onTransitionEnd);\n          };\n\n          contentWrapper.addEventListener('transitionend', onTransitionEnd);\n        }\n\n        setBubbles.push(...elementsToAnimate);\n      });\n\n      if(!fullMids.length) {\n        animationPromise.resolve();\n      }\n\n      return {lastMsDelay, animationPromise};\n    };\n\n    const topRes = animateAsLadder(topIds, offsetIndex);\n    const middleRes = animateAsLadder(middleIds);\n    const bottomRes = animateAsLadder(bottomIds, offsetIndex);\n    const promises = [topRes.animationPromise, middleRes.animationPromise, bottomRes.animationPromise];\n    const delays: number[] = [topRes.lastMsDelay, middleRes.lastMsDelay, bottomRes.lastMsDelay];\n\n    if(this.onAnimateLadder) {\n      await this.onAnimateLadder();\n    }\n\n    fastRaf(() => {\n      this.setStickyDateManually(); // ! maybe it's not efficient\n\n      setBubbles.forEach((element) => {\n        element.classList.remove('zoom-fade');\n      });\n    });\n\n    let promise: Promise<any>;\n    if(topIds.length || middleIds.length || bottomIds.length) {\n      promise = Promise.all(promises);\n\n      const TRANSITION_TIME = 300;\n      const timeout = Math.max(...delays) + TRANSITION_TIME;\n      dispatchHeavyAnimationEvent(promise, timeout)\n      .then(() => {\n        fastRaf(() => {\n          setBubbles.forEach((element) => {\n            element.style.transitionDelay = '';\n            element.classList.remove('can-zoom-fade');\n          });\n\n          this.chatInner.classList.remove('zoom-fading');\n        });\n\n        // ! в хроме, каким-то образом из-за zoom-fade класса начинает прыгать скролл при подгрузке сообщений вверх,\n        // ! т.е. скролл не ставится, так же, как в сафари при translateZ на блок выше scrollable\n        // if(!IS_SAFARI) {\n        //   this.needReflowScroll = true;\n        // }\n      });\n    }\n\n    return promise;\n  }\n\n  private async renderEmptyPlaceholder(\n    type: EmptyPlaceholderType,\n    bubble: HTMLElement,\n    message: any,\n    elements: (Node | string)[]\n  ) {\n    const BASE_CLASS = 'empty-bubble-placeholder';\n    bubble.classList.add(BASE_CLASS, BASE_CLASS + '-' + type);\n\n    let title: HTMLElement, topic: ForumTopic.forumTopic;\n    if(type === 'group') title = i18n('GroupEmptyTitle1');\n    else if(type === 'saved') title = i18n('ChatYourSelfTitle');\n    else if(type === 'noMessages' || type === 'greeting') title = i18n('NoMessages');\n    else if(type === 'noScheduledMessages') title = i18n('NoScheduledMessages');\n    else if(type === 'restricted') {\n      title = document.createElement('span');\n      const reason = getRestrictionReason(await this.managers.appPeersManager.getPeerRestrictions(this.peerId))\n\n      if(reason) {\n        if(!reason.text && reason.reason === 'sensitive') {\n          title.replaceChildren(i18n('SensitiveChannel'));\n        } else {\n          title.innerText = reason.text;\n        }\n      } else {\n        title.replaceChildren(i18n(this.peerId.isUser() ? 'RestrictedUser' : 'RestrictedChat'));\n      }\n    }\n\n    if(title) {\n      title.classList.add('center', BASE_CLASS + '-title');\n      elements.push(title);\n    }\n\n    let listElements: HTMLElement[];\n    if(type === 'group') {\n      elements.push(i18n('GroupEmptyTitle2'));\n      listElements = [\n        i18n('GroupDescription1'),\n        i18n('GroupDescription2'),\n        i18n('GroupDescription3'),\n        i18n('GroupDescription4')\n      ];\n    } else if(type === 'saved') {\n      listElements = [\n        i18n('ChatYourSelfDescription1'),\n        i18n('ChatYourSelfDescription2'),\n        i18n('ChatYourSelfDescription3'),\n        i18n('ChatYourSelfDescription4')\n      ];\n    } else if(type === 'greeting') {\n      let subtitle = i18n('NoMessagesGreetingsDescription');\n\n      // findAndSplice(this.messagesQueue, q => q.bubble === bubble);\n\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n\n      const middleware = this.getMiddleware();\n\n      const promises = Promise.all([\n        this.managers.appStickersManager.getGreetingSticker(),\n        this.managers.appProfileManager.getProfile(message.peerId.toUserId())\n      ]);\n      await promises.then(async([doc, userFull]) => {\n        if(!middleware()) return;\n\n        const intro = userFull.business_intro;\n        if(intro) {\n          if(intro.title) {\n            const _title = document.createElement('span');\n            _title.append(wrapEmojiText(intro.title));\n            _title.className = title.className;\n            elements[elements.indexOf(title)] = _title;\n          }\n\n          if(intro.description) {\n            subtitle = document.createElement('span');\n            subtitle.append(wrapEmojiText(intro.description));\n          }\n\n          if(intro.sticker) {\n            doc = intro.sticker as MyDocument;\n          }\n\n          const bubbleContainer = bubble.querySelector('.bubble-content');\n          const content = bubbleContainer.cloneNode(false) as HTMLElement;\n          const service = bubbleContainer.querySelector('.service-msg').cloneNode(false) as HTMLElement;\n\n          service.append(i18n(\n            intro.title || intro.description ? 'ChatEmpty.BusinessIntro.How' : 'ChatEmpty.BusinessIntro.Sticker.How',\n            [\n              await wrapPeerTitle({peerId: message.peerId, onlyFirstName: true}),\n              anchorCallback(() => {\n                PopupPremium.show();\n              })\n            ]\n          ));\n\n          content.classList.add('has-service-before');\n          content.append(service);\n          bubbleContainer.after(content);\n          bubble.classList.add('wider');\n        }\n\n        const loadPromises: Promise<any>[] = [];\n        await wrapSticker({\n          doc,\n          // doc: appDocsManager.getDoc(\"5431607541660389336\"), // cubigator mockup\n          div: stickerDiv,\n          middleware,\n          lazyLoadQueue: this.lazyLoadQueue,\n          group: this.chat.animationGroup,\n          // play: !!message.pending || !multipleRender,\n          play: true,\n          loop: true,\n          withThumb: true,\n          loadPromises,\n          liteModeKey: 'stickers_chat'\n        });\n\n        attachClickEvent(stickerDiv, (e) => {\n          cancelEvent(e);\n          this.chat.input.emoticonsDropdown.onMediaClick({target: e.target}, undefined, undefined, true);\n        });\n\n        return Promise.all(loadPromises);\n      });\n\n      // this.renderMessagesQueue({\n      //   message,\n      //   bubble,\n      //   reverse: false,\n      //   promises: [loadPromise]\n      // });\n\n      subtitle.classList.add('center', BASE_CLASS + '-subtitle');\n\n      elements.push(subtitle, stickerDiv);\n    } else if(type === 'premiumRequired') {\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n      stickerDiv.append(Icon('premium_restrict_filled'));\n\n      const subtitle = i18n('Chat.PremiumRequired', [await wrapPeerTitle({peerId: this.peerId, onlyFirstName: true})]);\n      subtitle.classList.add('center', BASE_CLASS + '-subtitle');\n\n      const button = Button('bubble-service-button', {noRipple: true, text: 'Chat.PremiumRequiredButton'});\n      attachClickEvent(button, () => {\n        PopupPremium.show();\n      });\n\n      elements.push(stickerDiv, subtitle, button);\n    } else if(type === 'paidMessages') {\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n      stickerDiv.append(Icon('premium_restrict_filled'));\n\n      const starsAmount = await this.managers.appPeersManager.getStarsAmount(this.peerId); // should be cached probably here\n\n      const starsElement = document.createElement('span');\n      starsElement.classList.add(BASE_CLASS + '-stars');\n      starsElement.append(\n        Icon('star', BASE_CLASS + '-star-icon'),\n        numberThousandSplitterForStars(starsAmount)\n      );\n\n      const subtitle = i18n('PaidMessages.NewChatDescription', [\n        await wrapPeerTitle({peerId: this.peerId, onlyFirstName: true}),\n        starsElement\n      ]);\n      subtitle.classList.add('center', BASE_CLASS + '-subtitle');\n\n      const button = Button('bubble-service-button overflow-hidden', {noRipple: true, text: 'BuyStars'});\n      button.append(Sparkles({isDiv: true, mode: 'button'}));\n      attachClickEvent(button, () => {\n        PopupElement.createPopup(PopupStars, {spendPurposePeerId: this.peerId});\n      });\n\n      elements.push(stickerDiv, subtitle, button);\n    } else if(type === 'directChannelMessages') {\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n      stickerDiv.append(Icon('round_chats_filled'));\n\n      const starsAmount = await this.managers.appPeersManager.getStarsAmount(this.peerId);\n\n      let starsElement: HTMLElement;\n\n      if(starsAmount) {\n        starsElement = document.createElement('span');\n        starsElement.classList.add(BASE_CLASS + '-stars');\n        starsElement.append(\n          Icon('star', BASE_CLASS + '-star-icon'),\n          numberThousandSplitterForStars(starsAmount)\n        );\n      }\n\n      const subtitle = i18n(starsAmount ? 'ChannelDirectMessages.WelcomePaid' : 'ChannelDirectMessages.Welcome', [await wrapPeerTitle({peerId: this.peerId}), starsElement]);\n      subtitle.classList.add('center', BASE_CLASS + '-subtitle');\n\n      let button: HTMLElement;\n      if(starsAmount) {\n        button = Button('bubble-service-button overflow-hidden', {noRipple: true, text: 'BuyStars'});\n        button.append(Sparkles({isDiv: true, mode: 'button'}));\n        attachClickEvent(button, () => {\n          PopupElement.createPopup(PopupStars, {spendPurposePeerId: this.peerId});\n        });\n      }\n\n      elements.push(...[stickerDiv, subtitle, button].filter(Boolean));\n    } else if(type === 'topic' && (topic = await this.managers.dialogsStorage.getForumTopic(this.peerId, this.chat.threadId))) {\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n\n      stickerDiv.append(\n        await wrapTopicIcon({topic, middleware: this.getMiddleware(), customEmojiSize: TOPIC_ICON_SIZE})\n      );\n\n      this.placeholderTopicIconContainer = stickerDiv;\n      this.getMiddleware().onDestroy(() => {\n        this.placeholderTopicIconContainer = undefined;\n      });\n\n      const title = i18n('TopicEmptyTitle');\n      title.classList.add('center', BASE_CLASS + '-topic-title');\n\n      const subtitle = i18n('TopicEmptyDescription');\n      subtitle.classList.add('center', BASE_CLASS + '-topic-subtitle');\n\n      elements.push(stickerDiv, title, subtitle);\n    } else if(type === 'logs') {\n      const stickerDiv = document.createElement('div');\n      stickerDiv.classList.add(BASE_CLASS + '-sticker');\n      stickerDiv.append(Icon('clipboard'));\n\n      const hasFilters = this.inChatQuery || this.committedLogsFilters;\n\n      const title = i18n(!hasFilters ? 'AdminRecentActionsPlaceholder.Title' : 'AdminRecentActionsPlaceholder.WithFilterTitle');\n      title.classList.add('center', BASE_CLASS + '-title');\n\n      const subtitle = i18n(!hasFilters ? 'AdminRecentActionsPlaceholder.Description' : 'AdminRecentActionsPlaceholder.WithFilterDescription');\n      subtitle.classList.add('center', BASE_CLASS + '-logs-subtitle');\n\n      elements.push(stickerDiv, title, subtitle);\n    }\n\n    if(listElements) {\n      elements.push(\n        ...listElements.map((elem) => {\n          const span = document.createElement('span');\n          span.classList.add(BASE_CLASS + '-list-item');\n          span.append(elem);\n          return span;\n        })\n      );\n\n      if(type === 'group') {\n        listElements.forEach((elem) => {\n          const i = Icon('check', BASE_CLASS + '-list-check');\n          elem.prepend(i);\n        });\n      } else if(type === 'saved') {\n        listElements.forEach((elem) => {\n          const i = document.createElement('span');\n          i.classList.add(BASE_CLASS + '-list-bullet');\n          i.innerText = '•';\n          elem.prepend(i);\n        });\n      }\n    }\n\n    if(elements.length > 1) {\n      bubble.classList.add('has-service-description');\n    }\n\n    elements.forEach((element: any) => element.classList.add(BASE_CLASS + '-line'));\n  }\n\n  private async processLocalMessageRender(\n    message: Message.message | Message.messageService,\n    animate?: boolean\n  ) {\n    const isSponsored = !!(message as Message.message).pFlags.sponsored;\n\n    const onClearedBefore = () => {\n      this.log.warn('local message was cleared before render', message);\n    };\n\n    const p: Parameters<ChatBubbles['safeRenderMessage']>[0]['processResult'] = async(result) => {\n      const {bubble} = await result;\n      if(!bubble) {\n        onClearedBefore();\n        return result;\n      }\n\n      const fullMid = makeFullMid(message);\n\n      const middleware = bubble.middlewareHelper.get();\n      const m = middlewarePromise(middleware);\n\n      (bubble as any).message = message;\n\n      bubble.classList.add('is-group-last', 'is-group-first');\n\n      const updatePosition = () => {\n        if(this.updatePlaceholderPosition === updatePosition) {\n          this.updatePlaceholderPosition = undefined;\n        }\n\n        if(!middleware() || this.getBubble(fullMid) !== bubble) {\n          onClearedBefore();\n          return;\n        }\n\n        appendTo[method](appendWhat);\n      };\n\n      if(!isSponsored) {\n        if(!this.shouldShowBotforumNewTopic()) bubble.classList.add('bubble-first');\n        bubble.classList.remove('can-have-tail', 'is-in');\n      }\n\n      if(this.shouldShowBotforumNewTopic()) bubble.classList.add('bubble-last', 'botforum-new-topic-bubble');\n\n      const elements: (Node | string)[] = [];\n      const isBot = this.chat.isBot;\n      const appendWhat = bubble;\n      let renderPromise: Promise<any>,\n        appendTo = this.container,\n        method: 'append' | 'prepend' | 'replaceChildren' = 'append',\n        elementsMethod: 'prepend' | 'replaceChildren' = 'prepend';\n      if(this.chat.isRestricted) {\n        renderPromise = this.renderEmptyPlaceholder('restricted', bubble, message, elements);\n      } else if(isSponsored) {\n        bubble.classList.add('avoid-selection');\n\n        appendTo = this.chatInner;\n        method = 'append';\n        animate = false;\n      } else if(this.shouldShowBotforumNewTopic()) {\n        animate = false;\n        appendTo = this.chatInner;\n        method = 'append';\n        elementsMethod = 'replaceChildren';\n\n        elements.push(new BotforumNewTopic);\n      } else if(isBot && message._ === 'message') {\n        if(isMessageForVerificationBot(message)) {\n          const langPackString = I18n.strings.get('VerificationCodesBotDescription');\n          assumeType<LangPackString.langPackString>(langPackString);\n\n          const messageText = langPackString.value;\n          elements.push(messageText);\n          elementsMethod = 'replaceChildren';\n\n          bubble.classList.add('placeholder-when-no-messages');\n        } else {\n          const b = document.createElement('b');\n          b.append(i18n('BotInfoTitle'));\n          elements.push(b, '\\n\\n');\n        }\n\n        method = 'prepend';\n        appendTo = this.chatInner;\n      } else if(this.chat.isMonoforum && !this.chat.canManageDirectMessages) {\n        renderPromise = this.renderEmptyPlaceholder('directChannelMessages', bubble, message, elements);\n      } else if(this.chat.isAnyGroup && (this.chat.peer as MTChat.chat).pFlags.creator) {\n        renderPromise = this.renderEmptyPlaceholder('group', bubble, message, elements);\n      } else if(this.chat.type === ChatType.Scheduled) {\n        renderPromise = this.renderEmptyPlaceholder('noScheduledMessages', bubble, message, elements);\n      } else if(rootScope.myId === this.peerId) {\n        renderPromise = this.renderEmptyPlaceholder('saved', bubble, message, elements);\n      } else if(this.peerId.isUser() && !isBot && await m(this.chat.canSend()) && this.chat.type === ChatType.Chat) {\n        const requirement = await this.managers.appUsersManager.getRequirementToContact(this.peerId.toUserId());\n        if(requirement._ === 'requirementToContactPremium') {\n          renderPromise = this.renderEmptyPlaceholder('premiumRequired', bubble, message, elements);\n        } else if(\n          requirement._ === 'requirementToContactPaidMessages' &&\n          !(await this.managers.appProfileManager.hasBussinesIntro(this.peerId.toUserId()) && this.chat.starsAmount <= +this.chat.stars())\n        ) {\n          renderPromise = this.renderEmptyPlaceholder('paidMessages', bubble, message, elements);\n        } else {\n          renderPromise = this.renderEmptyPlaceholder('greeting', bubble, message, elements);\n        }\n      } else if((this.chat.isBotforum || this.chat.isForum) && this.chat.threadId) {\n        renderPromise = this.renderEmptyPlaceholder('topic', bubble, message, elements);\n      } else if(this.chat.type === ChatType.Logs) {\n        renderPromise = this.renderEmptyPlaceholder('logs', bubble, message, elements);\n      } else {\n        renderPromise = this.renderEmptyPlaceholder('noMessages', bubble, message, elements);\n      }\n\n      if(renderPromise) {\n        await renderPromise;\n      }\n\n      if(elements.length) {\n        const messageDiv = bubble.querySelector('.message, .service-msg');\n        messageDiv[elementsMethod](...elements);\n      }\n\n      const isWaitingForAnimation = !!this.messagesQueueOnRenderAdditional;\n      const noTransition = this.setPeerCached && !isWaitingForAnimation;\n      if(noTransition) {\n        const setOn = bubble.firstElementChild;\n        setOn.classList.add('no-transition');\n\n        if(this.chat.setPeerPromise) {\n          this.chat.setPeerPromise.catch(noop).finally(() => {\n            setOn.classList.remove('no-transition');\n          });\n        }\n      }\n\n      if(animate === undefined && !noTransition) {\n        animate = true;\n      }\n\n      if(isWaitingForAnimation || animate) {\n        this.updatePlaceholderPosition = updatePosition;\n\n        this.onAnimateLadder = () => {\n          // appendTo[method](bubble);\n          this.onAnimateLadder = undefined;\n\n          // need raf here because animation won't fire if this message is single\n          if(!this.messagesQueuePromise) {\n            return fastRafPromise();\n          }\n        };\n      } else if(this.chat.setPeerPromise) {\n        this.attachPlaceholderOnRender = () => {\n          this.attachPlaceholderOnRender = undefined;\n          updatePosition();\n          // appendTo[method](bubble);\n        };\n      } else {\n        this.updatePlaceholderPosition = updatePosition;\n        // appendTo[method](bubble);\n      }\n\n      if(!isWaitingForAnimation && animate) {\n        await m(getHeavyAnimationPromise());\n        const additionalFullMids = this.getRenderedHistory('asc');\n        indexOfAndSplice(additionalFullMids, fullMid);\n        this.animateAsLadder(fullMid, additionalFullMids, false, 0, EMPTY_FULL_MID);\n      }\n\n      bubble.middlewareHelper.onDestroy(() => {\n        if(this.emptyPlaceholderBubble === bubble) {\n          this.emptyPlaceholderBubble = undefined;\n        }\n      });\n\n      this.emptyPlaceholderBubble = bubble;\n\n      return result;\n    };\n\n    return this.safeRenderMessage({\n      message,\n      reverse: !isSponsored,\n      updatePosition: false,\n      processResult: p,\n      canAnimateLadder: true\n    });\n  }\n\n  private makeViewButton<T extends Parameters<typeof Button>[1]>(options: T) {\n    const button = Button('btn-primary btn-primary-transparent bubble-view-button', options);\n    const text = button.querySelector('.i18n');\n    if(text) {\n      text.classList.add('bubble-view-button-text');\n    }\n    return button;\n  }\n\n  private generateLocalMessageId(addOffset = 0) {\n    // const INCREMENT = 0x10;\n    const offset = (this.chat.type === ChatType.Scheduled ? -1 : 0) + addOffset;\n    // offset = generateMessageId(offset);\n    // id: -Math.abs(+this.peerId * INCREMENT + offset),\n    const id = -Math.abs(offset);\n    // const mid = -Math.abs(generateMessageId(id));\n    const mid = id;\n    return {id, mid};\n  }\n\n  private async generateLocalFirstMessage<T extends boolean>(\n    service?: T,\n    fill?: (message: GenerateLocalMessageType<T>) => void,\n    addOffset = 0\n  ): Promise<GenerateLocalMessageType<T>> {\n    const {id, mid} = this.generateLocalMessageId(addOffset);\n    let message: Omit<Message.message | Message.messageService, 'message'> & {message?: string} = {\n      _: service ? 'messageService' : 'message',\n      date: 0,\n      id,\n      mid,\n      peer_id: await this.managers.appPeersManager.getOutputPeer(this.peerId),\n      pFlags: {\n        local: true\n      }\n    };\n\n    if(!service) {\n      message.message = '';\n    }/*  else {\n      (message as Message.messageService).action = {} as any;\n    } */\n\n    assumeType<GenerateLocalMessageType<T>>(message);\n\n    fill?.(message);\n\n    const savedMessages = await this.managers.appMessagesManager.saveMessages([message], {storage: new Map() as any});\n    message = savedMessages[0];\n    message.mid = mid;\n    return message as any;\n  }\n\n  public getViewportSlice(useExtra?: boolean) {\n    // this.log.trace('viewport slice');\n    return getViewportSlice({\n      overflowElement: this.scrollable.container,\n      selector: '.bubbles-date-group .bubble:not(.is-date)',\n      extraSize: useExtra ? Math.max(700, windowSize.height) * 2 : undefined,\n      extraMinLength: useExtra ? 5 : undefined\n    });\n  }\n\n  public deleteViewportSlice(slice: ReturnType<ChatBubbles['getViewportSlice']>, ignoreScrollSaving?: boolean) {\n    if(DO_NOT_SLICE_VIEWPORT_ON_RENDER) {\n      return;\n    }\n\n    const {invisibleTop, invisibleBottom} = slice;\n    const invisible = invisibleTop.concat(invisibleBottom);\n    if(!invisible.length) {\n      return;\n    }\n\n    const log = this.log.bindPrefix('VIEWPORT-SLICE');\n\n    if(invisibleTop.length) {\n      this.setLoaded('top', false);\n      this.getHistoryTopPromise = undefined;\n      log('will slice top', invisible);\n    }\n\n    if(invisibleBottom.length) {\n      this.setLoaded('bottom', false);\n      this.getHistoryBottomPromise = undefined;\n      log('will slice bottom', invisible);\n    }\n\n    const fullMids = invisible.map(({element}) => getBubbleFullMid(element));\n    if(fullMids.some((fullMid) => {\n      const {peerId, mid} = splitFullMid(fullMid);\n      return isEphemeralMessage(this.chat.getMessageByPeer(peerId, mid));\n    })) {\n      this.ephemeralHistoryLoaded = false;\n      ++this.ephemeralHistoryGeneration;\n    }\n\n    let scrollSaver: ScrollSaver;\n    if(/* !!invisibleTop.length !== !!invisibleBottom.length &&  */!ignoreScrollSaving) {\n      scrollSaver = this.createScrollSaver(!!invisibleTop.length);\n      scrollSaver.save();\n    }\n\n    log('slicing mids', fullMids);\n    this.deleteMessagesByIds(fullMids, false, true);\n\n    if(scrollSaver) {\n      scrollSaver.restore();\n    } else if(invisibleTop.length) {\n      this.scrollable.lastScrollPosition = this.scrollable.scrollPosition;\n    }\n  }\n\n  public sliceViewport(ignoreHeavyAnimation?: boolean) {\n    // Safari cannot reset the scroll.\n    if(IS_SAFARI || (this.isHeavyAnimationInProgress && !ignoreHeavyAnimation) || DO_NOT_SLICE_VIEWPORT) {\n      return;\n    }\n\n    // const scrollSaver = new ScrollSaver(this.scrollable, true);\n    // scrollSaver.save();\n    const slice = this.getViewportSlice(true);\n    // if(IS_SAFARI) slice.invisibleTop = [];\n    this.deleteViewportSlice(slice);\n    // scrollSaver.restore();\n  }\n\n  private async setLoaded(side: SliceSides, value: boolean, checkPlaceholders = true) {\n    const willChange = this.scrollable.loadedAll[side] !== value;\n    if(!willChange) {\n      return;\n    }\n\n    const log = this.log.bindPrefix('setLoaded');\n    log('change', side, value);\n\n    this.scrollable.loadedAll[side] = value;\n    this.scrollable.onScroll(); // ! WARNING\n    // return;\n\n    if(value) {\n      void this.loadEphemeralHistory();\n    }\n\n    if(this.scrollable.loadedAll.bottom && this.scrollable.loadedAll.top) {\n      setPeerLanguageLoaded(this.peerId);\n    }\n\n    if(!checkPlaceholders) {\n      return;\n    }\n\n    if(this.pendingEphemeralHistory) {\n      return;\n    }\n\n    if(!this.chat.isRestricted) {\n      if(side === 'bottom' && this.sponsoredMessagesAvailable.length > 0) {\n        Promise.all([this.getHistoryTopPromise, this.messagesQueuePromise]).then(() => {\n          this.performHistoryResult({history: [this.sponsoredMessagesAvailable.shift()]}, false);\n        })\n      }\n\n      if(side === 'bottom' && value && this.shouldShowBotforumNewTopic()) {\n        return this.renderBotforumPlaceholder();\n      }\n\n      if(side === 'top' && value && this.chat.isBot && !this.chat.threadId) {\n        return this.renderBotPlaceholder();\n      }\n\n      if(side === 'top' && value && shouldShowUnknownUserPlaceholder(this.peerSettings)) {\n        return this.renderUnknownUserPlaceholder();\n      }\n    }\n\n    return this.checkIfEmptyPlaceholderNeeded();\n  }\n\n  private sponsoredMessagesMids: FullMid[] = [];\n  private sponsoredMessages: MyMessage[] = [];\n  private sponsoredMessagesAvailable: MyMessage[] = [];\n  private sponsoredMessageEvery = 0;\n  private messagesSinceLastSponsored = 0;\n  private sponsoredAfterMids = new Map<number, MyMessage>();\n  private sponsoredMessagesLoaded = false;\n\n  private async generateSponsoredMessage(sponsoredMessage: SponsoredMessage.sponsoredMessage, idx: number) {\n    const offset = SPONSORED_MESSAGE_ID_OFFSET + idx\n\n    const msg = await this.generateLocalFirstMessage(false, (message) => {\n      message.message = '';\n      message.from_id = {_: 'peerUser', user_id: NULL_PEER_ID};\n      message.pFlags.sponsored = true;\n      message.pFlags.invert_media = true;\n      message.sponsoredMessage = sponsoredMessage;\n\n      const sponsoredMedia = sponsoredMessage.media;\n\n      const localWebPage: WebPage.webPage = {\n        _: 'webPage',\n        id: message.mid,\n        pFlags: {\n          has_large_media: !!sponsoredMedia || undefined\n        },\n        url: '',\n        display_url: '',\n        hash: 0,\n        description: sponsoredMessage.message,\n        entities: sponsoredMessage.entities,\n        document: (sponsoredMedia as MessageMedia.messageMediaDocument)?.document,\n        photo: (sponsoredMedia as MessageMedia.messageMediaPhoto)?.photo\n      };\n\n      message.media = {\n        _: 'messageMediaWebPage',\n        pFlags: {\n          force_large_media: !!sponsoredMedia || undefined\n        },\n        webpage: localWebPage\n      };\n    }, offset)\n\n    this.sponsoredMessagesMids.push(makeFullMid(this.peerId, msg.mid));\n\n    return msg;\n  }\n  private async loadSponsoredMessages() {\n    if(this.sponsoredMessagesLoaded) return;\n\n    const log = this.log.bindPrefix('sponsored-' + (Math.random() * 1000 | 0));\n\n    const middleware = this.getMiddleware(() => this.getSponsoredMessagePromise === promise);\n\n    const promise = this.getSponsoredMessagePromise = this.managers.appMessagesManager.getSponsoredMessage(this.peerId)\n    .then((sponsoredMessages) => {\n      if(!middleware() || sponsoredMessages._ === 'messages.sponsoredMessagesEmpty') {\n        return;\n      }\n      log('sponsored messages:', sponsoredMessages);\n\n      if(sponsoredMessages.posts_between) {\n        this.sponsoredMessageEvery = sponsoredMessages.posts_between;\n        Promise.all(sponsoredMessages.messages.map((it, idx) => this.generateSponsoredMessage(it, idx))).then((msgs) => {\n          this.messagesSinceLastSponsored = 0;\n          this.sponsoredMessages = this.sponsoredMessagesAvailable = msgs\n          if(this.scrollable.loadedAll.bottom) {\n            this.performHistoryResult({history: [msgs.shift()]}, false);\n          }\n        });\n        return;\n      }\n\n      const sponsoredMessage = sponsoredMessages.messages[0];\n      if(!sponsoredMessage) {\n        log('no message');\n        return;\n      }\n\n      const messagePromise = this.generateSponsoredMessage(sponsoredMessage, 0);\n\n      return Promise.all([\n        messagePromise,\n        this.getHistoryTopPromise, // wait for top load and execute rendering after or with it\n        this.messagesQueuePromise\n      ]).then(([message]) => {\n        if(!middleware()) return;\n        if(this.scrollable.loadedAll.bottom) {\n          this.performHistoryResult({history: [message]}, false);\n        } else {\n          this.sponsoredMessagesAvailable = [message]\n        }\n      })\n    }).finally(() => {\n      if(this.getSponsoredMessagePromise === promise) {\n        this.getSponsoredMessagePromise = undefined;\n        this.sponsoredMessagesLoaded = true;\n      }\n    });\n  }\n\n  private async renderBotPlaceholder() {\n    const _log = this.log.bindPrefix('bot placeholder');\n\n    const middleware = this.getMiddleware();\n    const result = await this.managers.acknowledged.appProfileManager.getProfile(this.peerId.toUserId());\n    _log('getting profile, cached:', result.cached);\n    const processPromise = result.result.then(async(userFull) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(!userFull.bot_info?.description) {\n        _log.warn('no description');\n        return this.checkIfEmptyPlaceholderNeeded();\n      }\n\n      const message = await this.generateLocalFirstMessage(false, (message) => {\n        const botInfo = userFull.bot_info;\n        message.message = botInfo.description;\n        if(botInfo.description_document) message.media = {_: 'messageMediaDocument', document: botInfo.description_document, pFlags: {}};\n        if(botInfo.description_photo) message.media = {_: 'messageMediaPhoto', photo: botInfo.description_photo, pFlags: {}};\n      });\n\n      if(!middleware()) {\n        return;\n      }\n\n      _log('rendering');\n      const renderPromise = this.processLocalMessageRender(message, !result.cached).then(() => {\n        _log('done');\n      });\n\n      return {renderPromise};\n    });\n\n    if(!result.cached) {\n      return;\n    }\n\n    return processPromise;\n  }\n\n  private async renderBotforumPlaceholder() {\n    const middleware = this.getMiddleware();\n\n    const message = await this.generateLocalFirstMessage(false, (message) => {\n      message.message = '-'; // will get replaced anyway\n      message.date = Date.now() * 1000;\n    });\n\n    if(!middleware()) {\n      return;\n    }\n\n    return {\n      renderPromise: this.processLocalMessageRender(message, false)\n    }\n  }\n\n  private async renderUnknownUserPlaceholder() {\n    const middleware = this.getMiddleware();\n\n    const [\n      user,\n      userFull\n    ] = await Promise.all([\n      this.managers.appUsersManager.getUser(this.peerId.toUserId()),\n      this.managers.appProfileManager.getProfile(this.peerId.toUserId())\n    ])\n    if(!middleware()) return\n\n    const message = await this.generateLocalFirstMessage(true);\n\n    return this.safeRenderMessage({\n      message,\n      reverse: true,\n      updatePosition: false,\n      processResult: async(result) => {\n        const {bubble} = await result;\n\n        bubble.classList.add('unknown-user-bubble');\n\n        const content = bubble.querySelector('.bubble-content');\n        content.replaceChildren()\n\n        const cleanup = render(() => UnknownUserBubble({\n          peerId: this.peerId,\n          user,\n          userFull,\n          peerSettings: this.peerSettings\n        }), content);\n        middleware.onDestroy(cleanup);\n\n        this.chatInner.prepend(bubble);\n        this.emptyPlaceholderBubble = bubble;\n        return result;\n      },\n      canAnimateLadder: true\n    });\n  }\n\n  public async checkIfEmptyPlaceholderNeeded() {\n    if(this.scrollable.loadedAll.top &&\n      this.scrollable.loadedAll.bottom &&\n      !this.pendingEphemeralHistory &&\n      !this.hasRenderedEphemeralMessages() &&\n      this.emptyPlaceholderBubble === undefined &&\n      !shouldShowUnknownUserPlaceholder(this.peerSettings) &&\n      (!this.chat.isBotforum || this.chat.canManageBotforumTopics) &&\n      (\n        this.chat.isRestricted ||\n        this.chat.type === ChatType.Logs ||\n        (\n          Object.keys(this.bubbles).length &&\n          !this.getRenderedLength()\n        ) ||\n        (this.chat.type === ChatType.Scheduled && !this.getRenderedLength()) ||\n        !this.chat.getHistoryStorage().count\n      )\n    ) {\n      this.log('inject empty peer placeholder');\n\n      const message = await this.generateLocalFirstMessage(true);\n      return {renderPromise: this.processLocalMessageRender(message)};\n    }\n  }\n\n  public getHistory1(maxId?: FullMid, reverse?: boolean, isBackLimit?: boolean, additionalFullMid?: FullMid, justLoad?: boolean) {\n    const middleware = this.getMiddleware(justLoad ? undefined : () => {\n      return (reverse ? this.getHistoryTopPromise : this.getHistoryBottomPromise) === waitPromise;\n    });\n\n    const result = this.getHistory(maxId, reverse, isBackLimit, additionalFullMid, justLoad, middleware);\n    const waitPromise = result.then((res) => res && (res.waitPromise || res.promise));\n\n    (reverse ? this.getHistoryTopPromise = waitPromise : this.getHistoryBottomPromise = waitPromise);\n    waitPromise.then(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      (reverse ? this.getHistoryTopPromise = undefined : this.getHistoryBottomPromise = undefined);\n\n      if(!justLoad) {\n        // preload more\n        // if(!isFirstMessageRender) {\n        if(this.chat.type === ChatType.Chat/*  || this.chat.type === 'discussion' */) {\n          /* const storage = this.appMessagesManager.getHistoryStorage(peerId, this.chat.threadId);\n            const isMaxIdInHistory = storage.history.indexOf(maxId) !== -1;\n            if(isMaxIdInHistory || true) { // * otherwise it is a search or jump */\n          setTimeout(() => {\n            if(reverse) {\n              this.loadMoreHistory(true, true);\n            } else {\n              this.loadMoreHistory(false, true);\n            }\n          }, 0);\n          // }\n        }\n        // }\n\n        // this.scrollable.onScroll();\n      }\n    });\n\n    return result;\n  }\n\n  // private async getDiscussionMessages() {\n  //   const mids = await this.chat.getMidsByMid(this.chat.threadId);\n  //   return Promise.all(mids.map((mid) => this.chat.getMessage(mid)));\n  // }\n\n  /**\n   * Load and render history\n   * @param maxId max message id\n   * @param reverse 'true' means up\n   * @param isBackLimit is search\n   * @param additionalFullMid for the last message\n   * @param justLoad do not render\n   */\n  public async getHistory(\n    maxId: FullMid = EMPTY_FULL_MID,\n    reverse = false,\n    isBackLimit = false,\n    additionalFullMid?: FullMid,\n    justLoad = false,\n    middleware?: () => boolean\n  ): Promise<{cached: boolean, promise: Promise<void>, waitPromise: Promise<any>}> {\n    const peerId = this.peerId;\n\n    const isBroadcast = this.chat.isBroadcast;\n    // console.time('appImManager call getHistory');\n    const pageCount = Math.min(40, windowSize.height / 40/*  * 1.25 */ | 0);\n    // const loadCount = Object.keys(this.bubbles).length > 0 ? 50 : pageCount;\n    const realLoadCount = isBroadcast ? 20 : (this.getRenderedHistory(undefined, true).length > 0 ? Math.max(35, pageCount) : pageCount);\n    // const realLoadCount = pageCount;//const realLoadCount = 50;\n    let loadCount = realLoadCount;\n\n    /* if(TEST_SCROLL) {\n      //loadCount = 1;\n      if(Object.keys(this.bubbles).length > 0)\n      return {cached: false, promise: Promise.resolve(true)};\n    } */\n    // if(TEST_SCROLL !== undefined) {\n    //   if(TEST_SCROLL) {\n    //     if(Object.keys(this.bubbles).length > 0) {\n    //       --TEST_SCROLL;\n    //     }\n    //   } else {\n    //     return {cached: false, promise: Promise.resolve(), waitPromise: Promise.resolve()};\n    //   }\n    // }\n\n    // //console.time('render history total');\n\n    let backLimit = 0;\n    if(isBackLimit) {\n      backLimit = loadCount;\n\n      if(!reverse) { // if not jump\n        loadCount = 0;\n        // maxId = this.appMessagesManager.incrementMessageId(maxId, 1);\n      }\n    }\n\n    let additionalFullMids: FullMid[];\n    if(additionalFullMid && !isBackLimit) {\n      if(this.chat.type === ChatType.Pinned) {\n        additionalFullMids = [additionalFullMid];\n      } else {\n        const historyStorage = this.chat.getHistoryStorage();\n        const slicedArray = historyStorage.history;\n        const slice = slicedArray.slice;\n        if(slice.isEnd(SliceEnd.Bottom) && !slice.isEnd(SliceEnd.Both)) {\n          const {mid, peerId} = splitFullMid(additionalFullMid);\n          const sliced = slicedArray.sliceMe(mid, 0, loadCount);\n          if(sliced) {\n            additionalFullMids = [additionalFullMid, ...sliced.slice.map((mid) => makeFullMid(peerId, mid))];\n          } else {\n            additionalFullMids = slice.slice(0, loadCount).map((mid) => makeFullMid(peerId, mid));\n          }\n\n          // * filter last album, because we don't know is it the last item\n          for(let i = additionalFullMids.length - 1; i >= 0; --i) {\n            const message = this.chat.getMessage(additionalFullMids[i]);\n            if((message as Message.message)?.grouped_id) additionalFullMids.splice(i, 1);\n            else break;\n          }\n\n          loadCount = Math.max(0, loadCount - additionalFullMids.length);\n          maxId = additionalFullMids[additionalFullMids.length - 1] || maxId;\n        }\n      }\n    }\n\n    /* const result = additionMsgID ?\n      {history: [additionMsgID]} :\n      appMessagesManager.getHistory(this.peerId, maxId, loadCount, backLimit); */\n    let result: AckedResult<MyHistoryResult> = await this.requestHistory(maxId, loadCount, backLimit) as any;\n    let resultPromise: typeof result['result'];\n\n    this.log('i vin brehnya', result, maxId, loadCount, backLimit);\n\n    // const isFirstMessageRender = !!additionMsgID && result.cached && !appMessagesManager.getMessage(additionMsgID).grouped_id;\n    // const isAdditionRender = additionMsgIds?.length && !result.cached;\n    const isAdditionRender = !!additionalFullMids?.length;\n    // const isFirstMessageRender = (this.isFirstLoad && backLimit && !result.cached) || (isAdditionRender && loadCount > 0);\n    const isFirstMessageRender = this.isFirstLoad && !result.cached && (isAdditionRender || loadCount > 0);\n    if(isAdditionRender) {\n      resultPromise = result.result;\n\n      result = {\n        cached: true,\n        result: Promise.resolve({history: additionalFullMids.map((fullMid) => splitFullMid(fullMid).mid)})\n      };\n\n      // additionMsgID = 0;\n    }\n\n    this.isFirstLoad = false;\n\n    const processResult = async(historyResult: Awaited<typeof result['result']>) => {\n      // if((historyResult as HistoryResult).isEnd?.top) {\n      //   // * synchronize bot placeholder & user premium appearance\n      //   await this.managers.appProfileManager.getProfileByPeerId(peerId);\n\n      //   // await this.setLoaded('top', true);\n      // }\n    };\n\n    const sup = (historyResult: Awaited<typeof result['result']>) => {\n      return getHeavyAnimationPromise().then(() => {\n        return processResult(historyResult);\n      }).then(() => {\n        if(!isAdditionRender && additionalFullMid) {\n          historyResult.history.unshift(splitFullMid(additionalFullMid).mid);\n        }\n\n        return this.performHistoryResult(historyResult, reverse, true);\n      });\n    };\n\n    const processPromise = (_promise: typeof result['result']) => {\n      const promise = Promise.resolve(_promise).then((result) => {\n        if(middleware && !middleware()) {\n          throw PEER_CHANGED_ERROR;\n        }\n\n        if(justLoad) {\n          // нужно делать из-за ранней прогрузки\n          this.scrollable.onScroll();\n          // fastRaf(() => {\n          //   this.scrollable.checkForTriggers();\n          // });\n          return;\n        }\n\n        return sup(result);\n      }, (err) => {\n        this.log.error('getHistory error:', err);\n        throw err;\n      });\n\n      return promise;\n    };\n\n    let promise: Promise<void>, cached: boolean;\n    if(!result.cached) {\n      cached = false;\n      promise = processPromise(result.result);\n    } else if(justLoad) {\n      // нужно делать из-за ранней прогрузки\n      this.scrollable.onScroll();\n      return null;\n    } else {\n      cached = true;\n      promise = sup(await result.result);\n    }\n\n    const waitPromise = isAdditionRender ? processPromise(resultPromise) : promise;\n\n    if(isFirstMessageRender && liteMode.isAvailable('animations')/*  && false */) {\n      let times = isAdditionRender ? 2 : 1;\n      this.messagesQueueOnRenderAdditional = () => {\n        this.log('messagesQueueOnRenderAdditional');\n\n        if(--times) return;\n\n        this.messagesQueueOnRenderAdditional = undefined;\n\n        const promise = this.animateAsLadder(additionalFullMid, additionalFullMids, isAdditionRender, backLimit, maxId);\n        promise.then(() => {\n          setTimeout(() => { // preload messages\n            this.loadMoreHistory(reverse, true);\n          }, 0);\n        });\n      };\n    } else {\n      this.messagesQueueOnRenderAdditional = undefined;\n    }\n\n    if(justLoad) {\n      return null;\n    }\n\n    return {cached, promise, waitPromise};\n  }\n\n  /** The first rendered incoming message past the read cursor — where the unread delimiter goes */\n  private findFirstUnreadFullMid(readMaxId: number) {\n    return this.getRenderedHistory('asc', true).find((fullMid) => {\n      const bubble = this.getBubble(fullMid);\n      return splitFullMid(fullMid).mid > readMaxId && bubble && !bubble.classList.contains('is-out');\n    });\n  }\n\n  /**\n   * The bubble the unread delimiter sits on (or would sit on), i.e. tdesktop's\n   * `History::firstUnreadMessage()`. Falls back to a scan when the delimiter itself hasn't been\n   * attached yet (or has been sliced out of the viewport).\n   */\n  private getFirstUnreadBubble(readMaxId: number) {\n    if(this.firstUnreadBubble?.parentElement) {\n      return this.firstUnreadBubble;\n    }\n\n    const fullMid = this.findFirstUnreadFullMid(readMaxId);\n    return fullMid ? this.getBubble(fullMid) : undefined;\n  }\n\n  /**\n   * tdesktop's `HistoryWidget::insideJumpToEndInsteadOfToUnread` — in an already opened chat the\n   * go-down button (and re-clicking the open dialog in the chat list) jumps to the first unread\n   * message, and only goes to the very end once that message is no longer below the viewport.\n   */\n  private shouldJumpToEndInsteadOfUnread(readMaxId: number) {\n    const bubble = this.getFirstUnreadBubble(readMaxId);\n    return !!bubble && bubble.getBoundingClientRect().top <= this.chat.bubblesViewport.getBoundingClientRect().bottom;\n  }\n\n  public async setUnreadDelimiter() {\n    if(!(this.chat.type === ChatType.Chat || this.chat.type === ChatType.Discussion)) {\n      return;\n    }\n\n    if(this.attachedUnreadBubble) {\n      return;\n    }\n\n    // * the aggregated monoforum admin view has no single unread cursor to draw a delimiter for\n    if(this.chat.isMonoforum && this.chat.canManageDirectMessages && !this.chat.monoforumThreadId) {\n      return;\n    }\n\n    const middleware = this.getMiddleware();\n\n    const {peerId, threadId, monoforumThreadId} = this.chat;\n\n    const historyMaxId = this.chat.getHistoryMaxId();\n    const readMaxId = await this.managers.appMessagesManager.getReadMaxIdIfUnread(peerId, threadId || monoforumThreadId);\n    if(!readMaxId || !middleware()) return;\n\n    const firstUnreadFullMid = this.findFirstUnreadFullMid(readMaxId);\n    if(!firstUnreadFullMid) {\n      return;\n    }\n\n    const firstUnreadMid = splitFullMid(firstUnreadFullMid).mid;\n    const bubble = this.getBubble(peerId, firstUnreadMid);\n    if(!bubble) {\n      return;\n    }\n\n    if(this.firstUnreadBubble && this.firstUnreadBubble !== bubble) {\n      this.firstUnreadBubble.classList.remove('is-first-unread');\n      this.firstUnreadBubble = null;\n    }\n\n    if(firstUnreadMid !== historyMaxId) {\n      bubble.classList.add('is-first-unread');\n    }\n\n    this.firstUnreadBubble = bubble;\n    this.attachedUnreadBubble = true;\n  }\n\n  public deleteEmptyDateGroups() {\n    let deleted = false;\n    for(const i in this.dateMessages) {\n      const dateMessage = this.dateMessages[i];\n\n      if(dateMessage.groupsLength) {\n        continue;\n      }\n\n      dateMessage.container.remove();\n      this.stickyIntersector?.unobserve(dateMessage.container, dateMessage.div);\n      delete this.dateMessages[i];\n      deleted = true;\n\n      // * no sense in it\n      /* if(dateMessage.div === this.previousStickyDate) {\n        this.previousStickyDate = undefined;\n      } */\n    }\n\n    if(!deleted) {\n      return;\n    }\n\n    if(!Object.keys(this.dateMessages).length) {\n      this.container.classList.remove('has-groups');\n    }\n\n    this.checkIfEmptyPlaceholderNeeded();\n    this.setStickyDateManually();\n  }\n\n  public async setPeerSettings(peerId: PeerId, peerSettings: PeerSettings) {\n    if(this.peerId !== peerId) return;\n\n    this.peerSettings = peerSettings;\n\n    if(shouldShowUnknownUserPlaceholder(peerSettings)) {\n      this.cleanupPlaceholders()\n      this.renderUnknownUserPlaceholder();\n    }\n  }\n\n  private shouldShowBotforumNewTopic() {\n    return this.chat.isBotforum && !this.chat.threadId && this.chat.canManageBotforumTopics;\n  }\n\n  private finalizeTypingMessage(message: MyMessage, tempId: number) {\n    const currentlyTyping = this.currentlyTypingMessages[tempId];\n    const bubble = currentlyTyping?.bubble;\n\n    if(!currentlyTyping || !bubble) return false;\n\n    currentlyTyping?.clean();\n    delete this.currentlyTypingMessages[tempId];\n\n    this.currentlyTypingMessages[message.mid] = currentlyTyping;\n    currentlyTyping.nextIsEnd = true;\n\n    this.safeRenderMessage({\n      message,\n      bubble,\n      reverse: true\n    });\n\n    return true;\n  }\n\n  makeFullMid(message: MyMessage | AdminLog) {\n    if(message._ === 'channelAdminLogEvent') return makeFullMid(this.chat.peerId, +message.id);\n    return makeFullMid(message);\n  }\n\n  public isAvatarNeeded(message: Message.message | Message.messageService | AdminLog) {\n    if(message?._ === 'channelAdminLogEvent') {\n      const entry = this.resolveAdminLogUnsafe({\n        log: message,\n        noJsx: true\n      });\n\n      if(!entry) return false;\n\n      if(entry.type === 'default') message = entry.message;\n      else if(entry.type === 'regular') return message.user_id?.toPeerId() !== rootScope.myId;\n      else return false;\n    }\n\n    if(isMessageForVerificationBot(message)) return true;\n    // * guest-chat messages carry the guest bot's avatar even in a 1-on-1 chat\n    if(isGuestChatMessage(message)) return true;\n    return this.chat.isLikeGroup && !this.chat.isOutMessage(message);\n  }\n\n  private reload() {\n    this.cleanup(true);\n    this.setPeer({\n      peerId: this.peerId,\n      type: this.chat.type,\n      samePeer: true,\n      sameSearch: false,\n      forceIsFirstLoad: true\n    });\n  }\n\n  public setInChatQuery(query: string) {\n    query = query || undefined;\n    if(query === this.inChatQuery) return;\n\n    this.inChatQuery = query;\n    this.reload();\n  }\n\n  public setLogFilters(filters?: CommittedFilters) {\n    filters = filters || undefined;\n    if(filters === this.committedLogsFilters) return;\n\n    this.committedLogsFilters = filters;\n    this.reload();\n  }\n\n  public async resolveAdminLog(args: BubblesResolveAdminLogArgs) {\n    const promise = ensureAdminLogResolver();\n    if(promise) await promise;\n\n    return this.resolveAdminLogUnsafe(args);\n  }\n\n  /**\n   * Doesn't ensure the resolver function was loaded\n   */\n  public resolveAdminLogUnsafe(args: BubblesResolveAdminLogArgs) {\n    if(!resolveAdminLog) return null;\n\n    const {log} = args;\n\n    const wrapOptions: WrapSomethingOptions = args.noJsx !== true ? {\n      lazyLoadQueue: this.lazyLoadQueue,\n      middleware: args.middleware,\n      customEmojiSize: this.chat.appImManager.customEmojiSize,\n      animationGroup: this.chat.animationGroup\n    } : undefined;\n\n    const promises = args.noJsx !== true ? args.promises : undefined;\n\n    const isOut = log.user_id.toPeerId() === rootScope.myId;\n\n    const entry = resolveAdminLog({\n      channelId: this.peerId.toChatId(),\n      event: log,\n      isBroadcast: this.chat.isBroadcast,\n      isForum: this.chat.isForum,\n      peerId: log.user_id.toPeerId(),\n      isOut,\n      makePeerTitle: promises ?\n        (peerId) => {\n          const peerTitle = new PeerTitle;\n          promises.push(peerTitle.update({peerId}));\n          return peerTitle.element;\n        } :\n        () => document.createElement('span'),\n      makeMessagePeerTitle: wrapOptions ?\n        (peerId) => {\n          const {element, textColorProperty} = this.createTitle(peerId, wrapOptions, false);\n          element.style.color = `rgb(var(--${textColorProperty}))`;\n          return element;\n        } :\n        () => document.createElement('span')\n    });\n\n    return entry;\n  }\n\n  /** the answer a jump points at (a poll option link), -1 when there is none */\n  private getBubblePollAnswerIndex(bubble?: HTMLElement, lastMsgFullMid?: FullMid, pollOption?: string | Uint8Array) {\n    if(!bubble || lastMsgFullMid === EMPTY_FULL_MID || !pollOption) return -1;\n\n    const message = this.chat.getMessage(lastMsgFullMid);\n    if(!message || message?._ !== 'message' || message?.media?._ !== 'messageMediaPoll') return -1;\n\n    let option: Uint8Array;\n    if(pollOption instanceof Uint8Array) {\n      option = pollOption;\n    } else {\n      const maxLength = 100;\n      if(pollOption.length > maxLength) return -1; // discard possibly malformed parameter\n      option = linkToPollOption(pollOption);\n      if(!option) return -1;\n    }\n\n    return message.media.poll.answers.findIndex((answer) => answer._ === 'pollAnswer' && compareUint8Arrays(answer.option, option));\n  }\n\n  private highlightBubblePollAnswer(bubble?: HTMLElement, lastMsgFullMid?: FullMid, pollOption?: string | Uint8Array) {\n    const pollOptionIndex = this.getBubblePollAnswerIndex(bubble, lastMsgFullMid, pollOption);\n    if(pollOptionIndex === -1) return;\n\n    this.contexts.get(bubble)?.pollMessageContentControls?.highlightAnswerWithTimeout?.(pollOptionIndex, 3000);\n  }\n}\n","import {JSX} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport PopupElement from '.';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {DelimiterWithText} from '@components/chat/giveaway';\nimport PopupPremium from '@components/popups/premium';\nimport wrapLocalSticker from '@components/wrappers/localSticker';\nimport liteMode from '@helpers/liteMode';\nimport {toastNew} from '@components/toast';\nimport toggleDisability from '@helpers/dom/toggleDisability';\n\nexport default class PopupToggleReadDate extends PopupElement {\n  private titles: HTMLElement[];\n  private isPremiumPurchaseBlocked: boolean;\n  private stickerContainer: HTMLElement;\n\n  constructor(\n    private peerId: PeerId,\n    private type: 'lastSeen' | 'readTime'\n  ) {\n    super('popup-toggle-read-date', {\n      closable: true,\n      overlayClosable: true,\n      body: true\n    });\n\n    this.construct();\n  }\n\n  private _construct() {\n    const Part = (props: {\n      title: JSX.Element,\n      text: JSX.Element,\n      buttonText: LangPackKey,\n      onClick: () => any,\n      isPremium?: boolean\n    }) => {\n      let button: HTMLButtonElement;\n      return (\n        <>\n          <div class=\"popup-toggle-read-date-title\">{props.title}</div>\n          <div class=\"popup-toggle-read-date-subtitle\">{props.text}</div>\n          <button\n            ref={button}\n            class={'btn-primary btn-color-primary popup-toggle-read-date-button' + (props.isPremium ? ' popup-gift-premium-confirm shimmer' : '')}\n            onClick={() => {\n              const result = props.onClick();\n              if(result instanceof Promise) {\n                toggleDisability(button, true);\n              }\n            }}\n          >\n            {i18n(props.buttonText)}\n          </button>\n        </>\n      );\n    };\n\n    const map: {[type in PopupToggleReadDate['type']]?: {\n      title1: LangPackKey,\n      text1: LangPackKey,\n      lockedText: LangPackKey,\n      buttonText1: LangPackKey,\n      onClick: () => void,\n      title2: LangPackKey,\n      text2: LangPackKey,\n      buttonText2: LangPackKey\n    }} = {\n      lastSeen: {\n        title1: 'PremiumLastSeenHeader1',\n        text1: 'PremiumLastSeenText1',\n        lockedText: 'PremiumLastSeenText1Locked',\n        buttonText1: 'PremiumLastSeenButton1',\n        onClick: async() => {\n          await this.managers.appPrivacyManager.setPrivacy(\n            'inputPrivacyKeyStatusTimestamp',\n            [{_: 'inputPrivacyValueAllowAll'}]\n          );\n          this.hide();\n          toastNew({langPackKey: 'PremiumLastSeenSet'});\n        },\n        title2: 'PremiumLastSeenHeader2',\n        text2: 'PremiumLastSeenText2',\n        buttonText2: 'PremiumLastSeenButton2'\n      },\n      readTime: {\n        title1: 'PremiumReadHeader1',\n        text1: 'PremiumReadText1',\n        lockedText: 'PremiumReadText1Locked',\n        buttonText1: 'PremiumReadButton1',\n        onClick: async() => {\n          const globalPrivacy = await this.managers.appPrivacyManager.getGlobalPrivacySettings();\n          await this.managers.appPrivacyManager.setGlobalPrivacySettings({\n            _: 'globalPrivacySettings',\n            pFlags: {\n              ...globalPrivacy.pFlags,\n              hide_read_marks: undefined\n            }\n          });\n          this.hide();\n          toastNew({langPackKey: 'PremiumReadSet'});\n        },\n        title2: 'PremiumReadHeader2',\n        text2: 'PremiumReadText2',\n        buttonText2: 'PremiumReadButton2'\n      }\n    };\n\n    const details = map[this.type];\n\n    return (\n      <>\n        <div class=\"popup-toggle-read-date-sticker\">\n          {this.stickerContainer}\n        </div>\n        <Part\n          title={i18n(details.title1)}\n          text={i18n(this.isPremiumPurchaseBlocked ? details.lockedText : details.text1, [this.titles[0]])}\n          buttonText={details.buttonText1}\n          onClick={details.onClick}\n        />\n        {!this.isPremiumPurchaseBlocked && (\n          <>\n            <DelimiterWithText langKey=\"PremiumOr\" />\n            <Part\n              title={i18n(details.title2)}\n              text={i18n(details.text2, [this.titles[1]])}\n              buttonText={details.buttonText2}\n              onClick={() => {\n                this.hide();\n                PopupPremium.show();\n              }}\n              isPremium\n            />\n          </>\n        )}\n      </>\n    );\n  }\n\n  private async construct() {\n    const [titles, isPremiumPurchaseBlocked, stickerContainer] = await Promise.all([\n      Promise.all(new Array(2).fill(0).map(() => wrapPeerTitle({peerId: this.peerId, onlyFirstName: true}))),\n      apiManagerProxy.isPremiumPurchaseBlocked(),\n      wrapLocalSticker({\n        width: 86,\n        height: 86,\n        assetName: this.type === 'lastSeen' ? 'large_lastseen' : 'large_readtime',\n        middleware: this.middlewareHelper.get(),\n        loop: false,\n        autoplay: liteMode.isAvailable('stickers_chat')\n      }).then(async({container, promise}) => {\n        await promise;\n        return container\n      })\n    ]);\n    this.titles = titles;\n    this.isPremiumPurchaseBlocked = isPremiumPurchaseBlocked;\n    this.stickerContainer = stickerContainer;\n\n    this.appendSolid(() => this._construct());\n    this.show();\n  }\n}\n","import type Chat from '@components/chat/chat';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport {InputStickerSet, Message, MessagePeerReaction, MessagesMessageReactionsList, Reaction} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport {Middleware} from '@helpers/middleware';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ButtonMenu, {ButtonMenuItemOptions} from '@components/buttonMenu';\nimport ButtonIcon from '@components/buttonIcon';\nimport PeerTitle from '@components/peerTitle';\nimport PopupElement from '@components/popups';\nimport PopupReactedList from '@components/popups/reactedList';\nimport ReactionsElement from '@components/chat/reactions';\nimport ReactionElement from '@components/chat/reaction';\nimport {formatFullSentTime} from '@helpers/date';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport showStickersPopup from '@components/popups/stickers';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport contextMenuController from '@helpers/contextMenuController';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport deleteParticipantReaction from '@components/chat/deleteParticipantReaction';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport rootScope from '@lib/rootScope';\n\nconst MAX_VISIBLE_REACTORS = 6;\n\ntype ReactionPack = {\n  input: InputStickerSet.inputStickerSetID,\n  title: string\n};\n\nasync function getReactionPack(managers: AppManagers, reaction: Reaction): Promise<ReactionPack> {\n  if(reaction._ !== 'reactionCustomEmoji') {\n    return;\n  }\n\n  const [cachedDocument] = await managers.appEmojiManager.getCachedCustomEmojiDocuments([reaction.document_id]);\n  const document = cachedDocument ?? (await managers.appEmojiManager.getCustomEmojiDocuments([reaction.document_id]))[0];\n  const input = (document as MyDocument)?.stickerSetInput as InputStickerSet.inputStickerSetID;\n  if(!input || input._ !== 'inputStickerSetID') {\n    return;\n  }\n\n  const stickerSet = await managers.appStickersManager.getStickerSet(input);\n  return {\n    input,\n    title: stickerSet.set.title\n  };\n}\n\nfunction createPeerText(peerId: PeerId, date: number) {\n  const container = document.createElement('span');\n  container.classList.add('reaction-context-menu-peer');\n\n  const title = new PeerTitle({\n    peerId,\n    dialog: false\n  }).element;\n  title.classList.add('reaction-context-menu-peer-title');\n\n  const subtitle = document.createElement('span');\n  subtitle.classList.add('reaction-context-menu-peer-date');\n  subtitle.append(formatFullSentTime(date, false));\n\n  container.append(title, subtitle);\n  return container;\n}\n\nexport default async function createReactionContextMenu({\n  chat,\n  managers,\n  reactionElement,\n  reactionsElement,\n  middleware,\n  listenerSetter\n}: {\n  chat: Chat,\n  managers: AppManagers,\n  reactionElement: ReactionElement,\n  reactionsElement: ReactionsElement,\n  middleware: Middleware,\n  listenerSetter: ListenerSetter\n}) {\n  const context = reactionsElement.getContext();\n  const reaction = reactionElement.reactionCount.reaction;\n  const message = await managers.appMessagesManager.getMessageByPeer(context.peerId, context.mid) as Message.message | Message.messageService;\n  if(!middleware() || !message) {\n    return;\n  }\n\n  const canViewList = !!message.reactions?.pFlags.can_see_list || message.peerId.isUser();\n  const reactionPackPromise = getReactionPack(managers, reaction).catch((): undefined => undefined);\n  const [reactionsList, canDelete]: [\n    MessagesMessageReactionsList | undefined,\n    boolean\n  ] = await Promise.all([\n    canViewList ? managers.appReactionsManager.getMessageReactionsList(\n      message.peerId,\n      message.mid,\n      50,\n      reaction\n    ).catch((): undefined => undefined) : undefined,\n    canViewList ? managers.appReactionsManager.canDeleteParticipantReactions(message.peerId) : false\n  ]);\n  if(!middleware() || !reactionElement.isConnected) {\n    return;\n  }\n\n  const seenPeerIds = new Set<PeerId>();\n  const sourceReactions = reactionsList ?\n    reactionsList.reactions :\n    (canViewList ? message.reactions?.recent_reactions ?? [] : []);\n  const peerReactions = sourceReactions.filter((peerReaction: MessagePeerReaction) => {\n    const peerId = getPeerId(peerReaction.peer_id);\n    if(\n      seenPeerIds.has(peerId) ||\n      !reactionsEqual(peerReaction.reaction, reaction)\n    ) {\n      return false;\n    }\n\n    seenPeerIds.add(peerId);\n    return true;\n  });\n  const visiblePeerReactions = peerReactions.slice(0, MAX_VISIBLE_REACTORS);\n  const buttons: ButtonMenuItemOptions[] = [];\n  const participantButtons: Array<{\n    button: ButtonMenuItemOptions,\n    peerReaction: MessagePeerReaction,\n    peerId: PeerId\n  }> = [];\n\n  visiblePeerReactions.forEach((peerReaction) => {\n    const peerId = getPeerId(peerReaction.peer_id);\n    const button: ButtonMenuItemOptions = {\n      avatarInfo: {peerId},\n      className: 'reaction-context-menu-participant with-subtitle',\n      textElement: createPeerText(peerId, peerReaction.date),\n      onClick: undefined\n    };\n    buttons.push(button);\n    participantButtons.push({button, peerReaction, peerId});\n  });\n\n  if(reactionsList?.count > visiblePeerReactions.length) {\n    buttons.push({\n      icon: 'reactions',\n      text: 'ShowAllReactions',\n      separator: !!buttons.length,\n      onClick: () => {\n        PopupElement.createPopup(PopupReactedList, message as Message.message, reaction);\n      }\n    });\n  }\n\n  let reactionPackButton: ButtonMenuItemOptions;\n  let resolveReactionPackButton = false;\n  if(reaction._ === 'reactionCustomEmoji') {\n    if(buttons.length) {\n      resolveReactionPackButton = true;\n      reactionPackButton = {\n        text: 'Loading',\n        multiline: true,\n        separator: true,\n        keepOpen: true,\n        onClick: () => {\n          void reactionPackPromise.then((reactionPack) => {\n            if(middleware() && reactionPack) {\n              contextMenuController.close();\n              showStickersPopup(reactionPack.input, true, chat.input);\n            }\n          });\n        }\n      };\n    } else {\n      const reactionPack = await reactionPackPromise;\n      if(!middleware() || !reactionPack) {\n        return;\n      }\n\n      reactionPackButton = {\n        textElement: i18n('MessageContainsReactionPack', [wrapEmojiText(reactionPack.title)]),\n        multiline: true,\n        onClick: () => {\n          showStickersPopup(reactionPack.input, true, chat.input);\n        }\n      };\n    }\n    buttons.push(reactionPackButton);\n  }\n\n  const hasDeletableParticipant = canDelete && participantButtons.some(({peerReaction, peerId}) =>\n    !peerReaction.pFlags.my && peerId !== rootScope.myId\n  );\n  if(IS_TOUCH_SUPPORTED && hasDeletableParticipant) {\n    const hint = document.createElement('div');\n    hint.classList.add('reaction-context-menu-hint');\n    hint.append(i18n('TapAndHoldToDeleteReaction'));\n    buttons.push({\n      element: hint,\n      separator: document.createElement('hr'),\n      onClick: undefined\n    });\n  }\n\n  if(!buttons.length) {\n    return;\n  }\n\n  const element = await ButtonMenu({buttons, listenerSetter});\n  element.classList.add('contextmenu', 'reaction-context-menu');\n\n  if(resolveReactionPackButton) {\n    void reactionPackPromise.then((reactionPack) => {\n      if(!middleware()) {\n        return;\n      }\n\n      if(!reactionPack) {\n        reactionPackButton.element.remove();\n        (reactionPackButton.separator as HTMLElement).remove();\n        return;\n      }\n\n      replaceContent(\n        reactionPackButton.textElement,\n        i18n('MessageContainsReactionPack', [wrapEmojiText(reactionPack.title)])\n      );\n    });\n  }\n\n  participantButtons.forEach(({button, peerReaction, peerId}) => {\n    const openPeer = (e: Event) => {\n      cancelEvent(e);\n      contextMenuController.close();\n      chat.appImManager.setInnerPeer({\n        peerId,\n        stack: chat.appImManager.getStackFromElement(reactionElement)\n      });\n    };\n    button.element.tabIndex = 0;\n    button.element.setAttribute('role', 'button');\n    listenerSetter.add(button.element)('click', openPeer);\n    listenerSetter.add(button.element)('keydown', (e: KeyboardEvent) => {\n      if(e.target === button.element && (e.key === 'Enter' || e.key === ' ')) {\n        openPeer(e);\n      }\n    });\n\n    const isMyReaction = !!peerReaction.pFlags.my;\n    if(!canDelete || isMyReaction || peerId === rootScope.myId) {\n      return;\n    }\n\n    const onDelete = (e: Event) => {\n      cancelEvent(e);\n      void deleteParticipantReaction({\n        message,\n        participantPeerId: peerId,\n        knownReaction: peerReaction.reaction,\n        isMyReaction,\n        managers\n      });\n\n      // Keep the current menu alive until attachContextMenuListener installs\n      // its touchend guard, then close it behind the confirmation popup.\n      setTimeout(() => contextMenuController.close(), 0);\n    };\n    attachContextMenuListener({\n      element: button.element,\n      callback: onDelete,\n      listenerSetter\n    });\n\n    if(!IS_TOUCH_SUPPORTED) {\n      const deleteButton = ButtonIcon('close', {noRipple: true});\n      deleteButton.classList.add('reaction-context-menu-delete');\n      deleteButton.setAttribute('aria-label', i18n('DeleteReaction').textContent);\n      attachClickEvent(deleteButton, onDelete, {listenerSetter});\n      button.element.append(deleteButton);\n    }\n  });\n\n  return {\n    element,\n    destroy: () => {\n      buttons.forEach((button) => button.dispose?.());\n      element.remove();\n    }\n  };\n}\n","import type {ChatInputReplyTo} from '@components/chat/input';\nimport {MessageEntity} from '@layer';\nimport cancelSelection from '@helpers/dom/cancelSelection';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\n\nexport default function getRichSelection(target: HTMLElement) {\n  const selection = target.ownerDocument.defaultView.getSelection();\n  const range = selection.getRangeAt(0);\n  const {startContainer, startOffset, endContainer, endOffset} = range;\n  const startValue = startContainer.nodeValue;\n  const endValue = endContainer.nodeValue;\n\n  // * find the index\n  const needle = '\\x02';\n  const container = findUpClassName(target, 'spoilers-container');\n  const skipSelectors: string[] = ['.reply'];\n  const s = skipSelectors.map((selector) => {\n    const element = container.querySelector(selector);\n    if(element) {\n      const textNode = document.createTextNode('');\n      element.replaceWith(textNode);\n      return [textNode, element];\n    }\n  }).filter(Boolean);\n\n  let insertedStartNode: Text, insertedEndNode: Text;\n  if(startValue === null) {\n    startContainer.parentNode.insertBefore(\n      insertedStartNode = document.createTextNode(needle),\n      startOffset === 0 ? startContainer : startContainer.nextSibling\n    );\n  }\n\n  if(endValue === null) {\n    endContainer.parentNode.insertBefore(\n      insertedEndNode = document.createTextNode(needle),\n      endOffset === 0 ? endContainer : endContainer.nextSibling\n    );\n  }\n\n  if(startContainer === endContainer && !insertedStartNode) {\n    startContainer.nodeValue = startValue.slice(0, startOffset) + needle + startValue.slice(startOffset, endOffset) + needle + startValue.slice(endOffset);\n  } else {\n    if(!insertedEndNode) endContainer.nodeValue = endValue.slice(0, endOffset) + needle + endValue.slice(endOffset);\n    if(!insertedStartNode) startContainer.nodeValue = startValue.slice(0, startOffset) + needle + startValue.slice(startOffset);\n  }\n  const {value: valueBefore} = getRichValueWithCaret(container);\n  const startIndex = valueBefore.indexOf(needle);\n  const endIndex = valueBefore.indexOf(needle, startIndex + 1) - 1;\n  if(insertedStartNode) insertedStartNode.remove();\n  else startContainer.nodeValue = startValue;\n  if(insertedEndNode) insertedEndNode.remove();\n  else endContainer.nodeValue = endValue;\n\n  // * have to fix entities\n  const SUPPORTED_ENTITIES = new Set<MessageEntity['_']>([\n    'messageEntityBold',\n    'messageEntityItalic',\n    'messageEntityUnderline',\n    'messageEntityStrike',\n    'messageEntitySpoiler',\n    'messageEntityCustomEmoji',\n    'messageEntityEmoji',\n    'messageEntityFormattedDate'\n  ]);\n  const {value: valueAfter, entities} = getRichValueWithCaret(container, true);\n  const value = valueAfter.slice(startIndex, endIndex);\n  for(let i = 0; i < entities.length; ++i) {\n    const entity = entities[i];\n    const startOffset = entity.offset;\n    const endOffset = startOffset + entity.length;\n    if(endOffset < startIndex || startOffset >= endIndex || !SUPPORTED_ENTITIES.has(entity._)) {\n      entities.splice(i--, 1);\n      continue;\n    }\n\n    entity.offset = Math.max(startOffset - startIndex, 0);\n    const distance = Math.max(startIndex - startOffset, 0);\n    const maxLength = endIndex - startIndex - entity.offset;\n    entity.length = Math.min(entity.length - distance, maxLength);\n  }\n\n  s.forEach(([textNode, element]) => textNode.replaceWith(element));\n  cancelSelection();\n\n  const quote: ChatInputReplyTo['replyToQuote'] = {\n    text: value,\n    entities: entities.length ? entities : undefined,\n    offset: startIndex\n  };\n\n  return quote;\n}\n","import detectLanguage from '@lib/tinyld/detect';\nimport {useAppSettings} from '@stores/appSettings';\nimport {useAppState} from '@stores/appState';\n\nexport default async function detectLanguageForTranslation(text: string): Promise<TranslatableLanguageISO> {\n  const [appSettings] = useAppSettings();\n  const [appState] = useAppState();\n  if(\n    !text ||\n    !appSettings.translations.showInMenu ||\n    appState.appConfig.translations_manual_enabled !== 'enabled'\n  ) return;\n  const language = await detectLanguage(text);\n  if(!appSettings.translations.doNotTranslate.includes(language)) {\n    return language;\n  }\n}\n","import PopupElement from '.';\nimport I18n, {i18n} from '@lib/langPack';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {StarsBalance} from '@components/popups/stars';\nimport {Accessor, createEffect, createMemo, createSignal, For, on, onCleanup, onMount, Show} from 'solid-js';\nimport {easeOutCircApply} from '@helpers/easing/easeOutCirc';\nimport Row from '@components/rowTsx';\nimport CheckboxField from '@components/checkboxField';\nimport {replaceButtonIcon} from '@components/button';\nimport rootScope from '@lib/rootScope';\nimport {Message, MessageReactor, PaidReactionPrivacy, Peer} from '@layer';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {IconTsx} from '@components/iconTsx';\nimport classNames from '@helpers/string/classNames';\nimport appImManager from '@lib/appImManager';\nimport {Ripple} from '@components/rippleTsx';\nimport RangeSelector from '@components/rangeSelector';\nimport clamp from '@helpers/number/clamp';\nimport {fastRaf} from '@helpers/schedulers';\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport debounce from '@helpers/schedulers/debounce';\nimport {Sparkles} from '@components/sparkles';\nimport ChatSendAs from '@components/chat/sendAs';\nimport Icon from '@components/icon';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {useAppState} from '@stores/appState';\nimport {SEND_PAID_REACTION_ANONYMOUS_PEER_ID} from '@appManagers/constants';\nimport type Chat from '@components/chat/chat';\nimport {PENDING_PAID_REACTIONS} from '@components/chat/reactions';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport {LimitLineTsx} from '@components/limitLineTsx';\n\nexport default class PopupStarReaction extends PopupElement {\n  constructor(private peerId: PeerId, private mid: number, private chat: Chat) {\n    super('popup-stars popup-star-reaction', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      scrollable: true,\n      footer: true,\n      withConfirm: true,\n      old: true\n      // title: true\n    });\n\n    this.footer.classList.add('abitlarger');\n\n    // * cancel all pending paid reactions\n    PENDING_PAID_REACTIONS.forEach((it) => it.abortController.abort());\n\n    this.construct();\n  }\n\n  private _construct(params: {\n    defaultSendAs?: PaidReactionPrivacy,\n    peerTitle: HTMLElement,\n    message: Message.message\n  }) {\n    const {defaultSendAs, peerTitle, message} = params;\n    this.footer.append(this.btnConfirm);\n    this.body.after(this.footer);\n\n    const sendText = new I18n.IntlElement({key: 'PaidReaction.Send'});\n\n    this.btnConfirm.append(sendText.element);\n    replaceButtonIcon(this.btnConfirm, 'star');\n\n    const sendAsContainer = document.createElement('div');\n    sendAsContainer.classList.add('popup-stars-send-as');\n    this.header.append(sendAsContainer);\n\n    this.header.append(StarsBalance() as HTMLElement);\n\n    const [appState] = useAppState();\n    const maximumStars = appState.appConfig.stars_paid_reaction_amount_max;\n    const [starsSliderValue, setStarsSliderValue] = createSignal<number>(0.1); // 50 stars\n    const [sendAsPeerId, setSendAsPeerId] = createSignal<PeerId>(\n      (!defaultSendAs || defaultSendAs._ === 'paidReactionPrivacyDefault') ? rootScope.myId :\n        defaultSendAs._ === 'paidReactionPrivacyAnonymous' ? SEND_PAID_REACTION_ANONYMOUS_PEER_ID :\n          getPeerId(defaultSendAs.peer)\n    );\n    const topSenders = () => {\n      return message.reactions?.top_reactors?.slice() ?? [];\n    };\n\n    let defaultSendAsPeerId: PeerId;\n    const myReactor = topSenders().find((sender) => sender.pFlags.my);\n    if(myReactor) {\n      defaultSendAsPeerId = getPeerId(myReactor.peer_id);\n    } else {\n      defaultSendAsPeerId = rootScope.myId;\n    }\n\n    const starsCount = () => {\n      const value$ = starsSliderValue();\n      const v = easeOutCircApply(1 - value$, 1);\n      return Math.max(1, Math.round((1 - v) * maximumStars));\n    };\n\n    attachClickEvent(this.btnConfirm, () => {\n      this.chat.sendReaction({\n        sendAsPeerId: sendAsPeerId(),\n        message,\n        reaction: {_: 'reactionPaid'},\n        count: starsCount()\n      });\n      this.destroy();\n    }, {listenerSetter: this.listenerSetter});\n\n    const checkboxField = new CheckboxField({\n      checked: myReactor ? !myReactor.pFlags.anonymous : defaultSendAs?._ !== 'paidReactionPrivacyAnonymous'\n    });\n    checkboxField.input.addEventListener('change', () => {\n      const sendAsPeerId$ = checkboxField.checked ? sendAs.getSendAsPeerId() : SEND_PAID_REACTION_ANONYMOUS_PEER_ID;\n      setSendAsPeerId(sendAsPeerId$);\n    });\n\n    const hintCounter = new AnimatedCounter({\n      reverse: true,\n      duration: 50,\n      calculateWidth: true\n    });\n    hintCounter.setCount(starsCount());\n\n    const sendAs = new ChatSendAs({\n      managers: this.managers,\n      menuContainer: sendAsContainer,\n      onReady: (el) => {\n        sendAsContainer.replaceChildren(\n          el,\n          Icon('down')\n        );\n      },\n      onChange: (peerId) => {\n        if(sendAsPeerId() === SEND_PAID_REACTION_ANONYMOUS_PEER_ID) return;\n        setSendAsPeerId(peerId);\n      },\n      forPaidReaction: true,\n      defaultPeerId: defaultSendAsPeerId\n    });\n    sendAs.setPeerId(message.peerId);\n    sendAs.update(true);\n\n    // * modify privacy\n    if(myReactor) createEffect(on(sendAsPeerId, (sendAsPeerId$) => {\n      this.managers.appReactionsManager.togglePaidReactionPrivacy(\n        message.peerId,\n        message.mid,\n        sendAsPeerId$\n      );\n    }, {defer: true}));\n\n\n    const updateCounterDebounced = debounce(val => fastRaf(() => hintCounter.setCount(val)), 10, true, true);\n\n    createEffect(() => {\n      sendText.compareAndUpdate({\n        args: [starsCount()]\n      });\n      updateCounterDebounced(starsCount());\n    });\n\n    const mySender = createMemo(() => {\n      const existing = topSenders().find((sender) => sender.pFlags.my);\n      const sendAsPeerId$ = sendAsPeerId();\n      const anonymous = sendAsPeerId$ === SEND_PAID_REACTION_ANONYMOUS_PEER_ID;\n      const peerId: Peer = anonymous ? undefined : (\n        sendAsPeerId$ === rootScope.myId ?\n          {_: 'peerUser', user_id: rootScope.myId} :\n          {_: 'peerChannel', channel_id: sendAsPeerId$}\n      );\n\n      const reactor: MessageReactor = {\n        _: 'messageReactor',\n        pFlags: {my: true, anonymous: anonymous || undefined},\n        peer_id: peerId,\n        get count() {\n          return (existing?.count || 0) + starsCount();\n        }\n      };\n\n      return reactor;\n    });\n\n    const topSendersWithMe = createMemo(() => {\n      const topSenders$ = topSenders();\n      findAndSplice(topSenders$, (sender) => sender.pFlags.my);\n      topSenders$.push(mySender());\n      return topSenders$.sort((a, b) => b.count - a.count).slice(0, 3);\n    });\n\n    const sparkles = (\n      <Sparkles\n        count={clamp(starsCount(), 20, 100)}\n        mode=\"progress\"\n      />\n    );\n\n    const renderSender = (sender: MessageReactor.messageReactor) => {\n      const peerId = getPeerId(sender.peer_id);\n      const anonymous = sender.pFlags.anonymous;\n      let ret = (\n        <div\n          class={classNames('popup-star-reaction-senders-item', !anonymous && 'is-clickable')}\n          onClick={() => {\n            if(anonymous) return;\n            appImManager.setInnerPeer({\n              peerId,\n              stack: {\n                peerId: this.peerId,\n                mid: this.mid\n              }\n            });\n            this.hide();\n          }}\n        >\n          <div class=\"popup-star-reaction-senders-avatar-wrap\">\n            {anonymous ? (\n              <div class=\"popup-star-reaction-senders-item-anonymous\">\n                <img src=\"assets/img/anon_paid_reaction.png\" alt=\"Anonymous\" />\n              </div>\n            ) : (\n              <AvatarNewTsx peerId={peerId} size={60} />\n            )}\n            <div class=\"popup-star-reaction-senders-amount\">\n              <IconTsx icon=\"star\" />\n              {sender.count}\n            </div>\n          </div>\n          {anonymous ? (\n            <div class=\"peer-title\">\n              {i18n('AuthorHiddenShort')}\n            </div>\n          ) : (\n            <PeerTitleTsx\n              peerId={peerId}\n            />\n          )}\n        </div>\n      );\n\n      if(!anonymous) {\n        ret = (\n          <Ripple>\n            {ret}\n          </Ripple>\n        );\n      }\n\n      return ret;\n    };\n\n    return (\n      <>\n        <LimitLineTsx\n          class=\"popup-stars-slider\"\n          filledProgressElement={sparkles as HTMLElement}\n          progress={starsSliderValue()}\n          onScrub={setStarsSliderValue}\n          hint={\n            <div class=\"popup-stars-slider-hint\">\n              {hintCounter.container}\n              <Sparkles mode=\"button\" />\n            </div>\n          }\n          hintIcon=\"star\"\n        />\n        <div class=\"popup-stars-title\">{i18n('StarsReactionTitle')}</div>\n        <div class=\"popup-stars-subtitle\">{i18n('StarsReactionText', [peerTitle])}</div>\n        <div class=\"popup-star-reaction-senders\">\n          <div class=\"popup-star-reaction-senders-delimiter\">\n            <div class=\"popup-star-reaction-senders-line\"></div>\n            <span class=\"popup-star-reaction-senders-text\">\n              {i18n('StarsReactionTopSenders')}\n            </span>\n            <div class=\"popup-star-reaction-senders-line\"></div>\n          </div>\n          <div class=\"popup-star-reaction-senders-list\">\n            <For each={topSendersWithMe()}>\n              {renderSender}\n            </For>\n          </div>\n        </div>\n        <div class=\"popup-star-reaction-checkbox\">\n          <Row class=\"popup-star-reaction-checkbox-row\">\n            <Row.CheckboxField>{checkboxField.label}</Row.CheckboxField>\n            <Row.Title>{i18n('StarsReactionShowMeInTopSenders')}</Row.Title>\n          </Row>\n        </div>\n      </>\n    );\n  }\n\n  private async construct() {\n    const [peerTitle, message, privacy] = await Promise.all([\n      wrapPeerTitle({peerId: this.peerId}),\n      rootScope.managers.appMessagesManager.getMessageByPeer(this.peerId, this.mid),\n      rootScope.managers.appReactionsManager.getPaidReactionPrivacy()\n    ]);\n\n    this.appendSolid(() => this._construct({\n      peerTitle,\n      message: message as Message.message,\n      defaultSendAs: privacy\n    }));\n    this.show();\n  }\n}\n","import filterUnique from '@helpers/array/filterUnique';\nimport {Message, MessageEntity, Reaction, MessageMedia} from '@layer';\n\nexport default function getUniqueCustomEmojisFromMessage(message: Message) {\n  const docIds: DocId[] = [];\n\n  const iterateEntities = (entities: MessageEntity[]) => {\n    if(!entities) {\n      return;\n    }\n\n    const filtered = entities.filter((entity) => entity._ === 'messageEntityCustomEmoji') as MessageEntity.messageEntityCustomEmoji[];\n    docIds.push(...filtered.map((entity) => entity.document_id));\n  };\n\n  iterateEntities((message as Message.message).entities);\n\n  const reactions = (message as Message.message).reactions;\n  if(reactions) {\n    const results = reactions.results.filter((reactionCount) => reactionCount.reaction._ === 'reactionCustomEmoji');\n    docIds.push(...results.map((reactionCount) => (reactionCount.reaction as Reaction.reactionCustomEmoji).document_id));\n  }\n\n  const poll = ((message as Message.message).media as MessageMedia.messageMediaPoll)?.poll;\n  if(poll) {\n    iterateEntities(poll.question.entities);\n    poll.answers.forEach((answer) => {\n      iterateEntities(answer.text.entities);\n    });\n  }\n\n  const todo = ((message as Message.message).media as MessageMedia.messageMediaToDo)?.todo;\n  if(todo) {\n    iterateEntities(todo.title.entities);\n    todo.list.forEach((item) => {\n      iterateEntities(item.title.entities);\n    });\n  }\n\n  return filterUnique(docIds);\n}\n","import {TextWithEntities} from '@layer';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport documentFragmentToHTML from '@helpers/dom/documentFragmentToHTML';\n\ntype TextWithEntitiesForCopying = Omit<TextWithEntities, '_'>;\nexport default function prepareTextWithEntitiesForCopying(\n  textWithEntities: TextWithEntitiesForCopying | TextWithEntitiesForCopying[],\n  meta?: string[]\n) {\n  if(!Array.isArray(textWithEntities)) {\n    textWithEntities = [textWithEntities];\n  }\n\n  const htmlParts = textWithEntities.map(({text, entities}) => {\n    const wrapped = wrapRichText(text, {\n      entities,\n      wrappingDraft: true\n    });\n    return documentFragmentToHTML(wrapped);\n  });\n\n  const parts: string[] = textWithEntities.map(({text}) => {\n    return text;\n  });\n\n  const prepare = (smth: string[]) => {\n    return smth.map((str, idx) => {\n      return meta?.[idx] ? meta[idx] + '\\n' + str : str;\n    }).join('\\n\\n');\n  };\n\n  return {\n    text: prepare(parts),\n    html: prepare(htmlParts)\n  };\n}\n","import formatDuration from '@helpers/formatDuration';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport {Accessor, createEffect, createMemo, createSignal, JSX, onCleanup} from 'solid-js';\nimport {wrapFormattedDuration} from './wrappers/wrapDuration';\n\n\nconst hourInSeconds = 60 * 60;\nconst minuteInSeconds = 60;\nconst updateTimerFrom = hourInSeconds + minuteInSeconds;\n\ntype Props = {\n  finishTimestamp: number;\n  children: (time: Accessor<JSX.Element>) => JSX.Element;\n};\n\nexport const RemainingTime = (props: Props) => {\n  const [shouldUpdateTimer, setShouldUpdateTimer] = createSignal(false);\n\n  const nowMillis = useNowMillis(shouldUpdateTimer);\n  const nowSeconds = createMemo(() => Math.floor(nowMillis() / 1000));\n\n  const finishesAtSeconds = createMemo(() => props.finishTimestamp);\n  const remainingSeconds = createMemo(() => Math.max(0, finishesAtSeconds() - nowSeconds()) || 0);\n\n  createEffect(() => {\n    setShouldUpdateTimer(0 < remainingSeconds() && remainingSeconds() < updateTimerFrom);\n  });\n\n  const formattedTime = createMemo(() => {\n    if(remainingSeconds() < hourInSeconds) {\n      return toHHMMSS(remainingSeconds());\n    }\n    return wrapFormattedDuration(formatDuration(remainingSeconds(), 1))\n  });\n\n  return props.children(formattedTime);\n};\n\nfunction useNowMillis(shouldUpdate: Accessor<boolean>) {\n  const [now, setNow] = createSignal(Date.now());\n\n  createEffect(() => {\n    if(!shouldUpdate()) {\n      return;\n    }\n\n    let timeout: number;\n\n    function scheduleNext() {\n      const now = Date.now();\n      const msPart = now % 1000;\n      const left = 1000 - msPart;\n\n      setNow(now);\n      timeout = self.setTimeout(scheduleNext, left);\n    }\n\n    scheduleNext();\n\n    onCleanup(() => {\n      self.clearTimeout(timeout);\n    });\n  });\n\n  return now;\n}\n","import {RemainingTime} from '@components/remainingTime';\nimport {Show} from 'solid-js';\nimport {attachHotClassName} from '../../helpers/solid/classname';\nimport {I18nTsx} from '../../helpers/solid/i18n';\nimport defineSolidElement, {PassedProps} from '../../lib/solidjs/defineSolidElement';\nimport {IconTsx} from '../iconTsx';\nimport styles from './contextMenuDeleteOptionText.module.scss';\n\nif(import.meta.hot) import.meta.hot.accept();\n\n\ntype Props = {\n  dateTimestamp: number;\n  ttlPeriod?: number;\n};\n\nexport const ContextMenuDeleteOptionText = defineSolidElement({\n  name: 'context-menu-delete-option-text',\n  component: (props: PassedProps<Props>) => {\n    attachHotClassName(props.element, styles.Container);\n\n    // Uncomment these lines to manually test different scenarios\n    // props.dateTimestamp = Date.now() / 1000\n    // props.ttlPeriod = 60 * 60 + 4\n\n    return (\n      <Show when={props.ttlPeriod} fallback={<I18nTsx key='Delete' />}>\n        <div>\n          <I18nTsx key='Delete' />\n        </div>\n        <div class={styles.Subtitle}>\n          <IconTsx class={styles.Icon} icon='fire' />\n          <RemainingTime finishTimestamp={props.dateTimestamp + props.ttlPeriod}>\n            {(time) => {\n              return <I18nTsx key='AutoDeletesIn' args={[time()]} />\n            }}\n          </RemainingTime>\n        </div>\n      </Show>\n    );\n  }\n});\n","// ! doesn't work for exact selection\n// export default function isNodeFullyInsideRange(range: Range, node: Node): boolean {\n//   const nodeRange = document.createRange();\n//   nodeRange.selectNode(node);\n\n//   console.log(range.compareBoundaryPoints(Range.START_TO_START, nodeRange), range.compareBoundaryPoints(Range.END_TO_END, nodeRange));\n//   return (\n//     range.compareBoundaryPoints(Range.START_TO_START, nodeRange) <= 0 &&\n//     range.compareBoundaryPoints(Range.END_TO_END, nodeRange) >= 0\n//   );\n// }\n\n// ! doesn't work for exact selection\n// export default function isNodeFullyInsideRange(range: Range, node: Node): boolean {\n//   const parent = node.parentNode;\n//   // const parent = node.nodeType === node.TEXT_NODE ? node.parentNode : node;\n//   if(!parent) return false;\n\n//   const index = Array.prototype.indexOf.call(parent.childNodes, node);\n\n//   console.log(range.comparePoint(parent, index), range.comparePoint(parent, index + 1));\n//   return (\n//     range.comparePoint(parent, index) >= 0 &&\n//     range.comparePoint(parent, index + 1) <= 0\n//   );\n// }\n\n// export default function isNodeFullyInsideRange(range: Range, node: Node): boolean {\n//   const frag = range.cloneContents();\n//   return frag.childNodes.length === 1 && frag.firstChild?.isEqualNode(node);\n// }\n\nexport default function isNodeFullyInsideRange(range: Range, node: Node): boolean {\n  if(!range.intersectsNode(node)) return false;\n\n  const nodeRange = document.createRange();\n  nodeRange.selectNodeContents(node);\n\n  return (\n    range.compareBoundaryPoints(Range.START_TO_START, nodeRange) <= 0 &&\n    range.compareBoundaryPoints(Range.END_TO_END, nodeRange) >= 0\n  ) || range.toString() === node.textContent;\n}\n","import {TextWithEntities} from '@layer';\n\nexport function concatTextsWithEntities(items: TextWithEntities.textWithEntities[]) {\n  const result: TextWithEntities.textWithEntities = {\n    _: 'textWithEntities',\n    text: '',\n    entities: []\n  };\n\n  for(const item of items) {\n    const entities = item.entities?.map(entity => ({\n      ...entity, offset: entity.offset + result.text.length\n    })) ?? [];\n\n    result.entities.push(...entities);\n\n    result.text += item.text;\n  }\n\n  return result;\n}\n","/**\n * Standard IEEE 802.3 CRC32 (poly 0xEDB88320, init 0xFFFFFFFF, reflected input/output,\n * final XOR 0xFFFFFFFF). Bit-identical to tdesktop's `base::crc32` (see\n * `Telegram/SourceFiles/base/crc32hash.cpp`).\n */\n\nconst CRC32_TABLE = (() => {\n  const table = new Uint32Array(256);\n  for(let i = 0; i < 256; i++) {\n    let c = i;\n    for(let j = 0; j < 8; j++) {\n      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);\n    }\n    table[i] = c >>> 0;\n  }\n  return table;\n})();\n\nexport default function crc32(data: Uint8Array): number {\n  let crc = 0xffffffff;\n  for(let i = 0; i < data.length; i++) {\n    crc = (crc >>> 8) ^ CRC32_TABLE[(crc & 0xff) ^ data[i]];\n  }\n  return (crc ^ 0xffffffff) >>> 0;\n}\n","import crc32 from '@helpers/number/crc32';\nimport {Poll, PollAnswer} from '@layer';\n\nexport const shouldShufflePollOptions = (poll: Poll): boolean =>\n  !poll.pFlags.creator && !!poll.pFlags.shuffle_answers;\n\n/**\n * Port of tdesktop's `HashPollShuffleValue`:\n *\n *   hash = decimal(userId) + option bytes + decimal(pollId)\n *   return uint32(base::crc32(hash))\n *\n * Keeps the resulting per-option order identical to tdesktop's poll shuffling.\n */\nconst hashPollShuffleValue = (\n  userId: PeerId,\n  pollId: Poll.poll['id'],\n  option: Uint8Array\n): number => {\n  const textEncoder = new TextEncoder();\n\n  const userIdBytes = textEncoder.encode(String(userId));\n  const pollIdBytes = textEncoder.encode(String(pollId));\n  const buffer = new Uint8Array(userIdBytes.length + option.length + pollIdBytes.length);\n  buffer.set(userIdBytes, 0);\n  buffer.set(option, userIdBytes.length);\n  buffer.set(pollIdBytes, userIdBytes.length + option.length);\n  return crc32(buffer);\n};\n\n/**\n * Lexicographic byte comparison, mirroring QByteArray's `operator<` used by\n * tdesktop's tie-breaker.\n */\nconst compareOptionBytes = (a: Uint8Array, b: Uint8Array): number => {\n  const len = Math.min(a.length, b.length);\n  for(let i = 0; i < len; i++) {\n    if(a[i] !== b[i]) return a[i] - b[i];\n  }\n  return a.length - b.length;\n};\n\ntype ShufflePollOptionsArgs = {\n  options: PollAnswer.pollAnswer[];\n  userId: PeerId;\n  pollId: Poll.poll['id'];\n};\n\nexport const shufflePollOptions = ({options, userId, pollId}: ShufflePollOptionsArgs) => {\n  return options.slice().sort((a, b) => {\n    const hashA = hashPollShuffleValue(userId, pollId, a.option);\n    const hashB = hashPollShuffleValue(userId, pollId, b.option);\n    if(hashA !== hashB) return hashA - hashB;\n    return compareOptionBytes(a.option, b.option);\n  });\n};\n","import type {MessageEntity} from '@layer';\n\nconst ATOMIC: ReadonlySet<MessageEntity['_']> = new Set([\n  'messageEntityMention',\n  'messageEntityMentionName',\n  'inputMessageEntityMentionName',\n  'messageEntityHashtag',\n  'messageEntityCashtag',\n  'messageEntityBotCommand',\n  'messageEntityUrl',\n  'messageEntityTextUrl',\n  'messageEntityEmail',\n  'messageEntityPhone',\n  'messageEntityBankCard',\n  'messageEntityCustomEmoji',\n  'messageEntityEmoji',\n  'messageEntityImage',\n  'messageEntityTimestamp',\n  'messageEntityFormattedDate',\n  'messageEntityAnchor',\n  'messageEntityDiffReplace'\n]);\n\nconst ZERO_LENGTH: ReadonlySet<MessageEntity['_']> = new Set([\n  'messageEntityLinebreak',\n  'messageEntityCaret'\n]);\n\n/** Sorted UTF-16 indices of every grapheme boundary, including 0 and text.length. */\nfunction graphemeBoundaries(text: string): number[] {\n  const seg = new Intl.Segmenter(undefined, {granularity: 'grapheme'});\n  const out: number[] = [];\n  for(const {index} of seg.segment(text)) out.push(index);\n  out.push(text.length);\n  return out;\n}\n\n/** Smallest boundary >= i. */\nfunction snapUp(boundaries: number[], i: number): number {\n  let lo = 0, hi = boundaries.length - 1;\n  while(lo < hi) {\n    const mid = (lo + hi) >>> 1;\n    if(boundaries[mid] < i) lo = mid + 1;\n    else hi = mid;\n  }\n  return boundaries[lo];\n}\n\n/** Largest boundary <= i. */\nfunction snapDown(boundaries: number[], i: number): number {\n  let lo = 0, hi = boundaries.length - 1;\n  while(lo < hi) {\n    const mid = (lo + hi + 1) >>> 1;\n    if(boundaries[mid] > i) hi = mid - 1;\n    else lo = mid;\n  }\n  return boundaries[lo];\n}\n\n/**\n * Slices `text` over the UTF-16 range `[from, to)` while preserving entity\n * integrity. Boundaries are snapped inward to the nearest grapheme cluster so\n * surrogate pairs and emoji sequences are never split. Entities are clipped\n * to the resulting range; atomic entities (mentions, links, custom emoji,\n * etc.) are dropped if a boundary falls inside them. Returns the sliced text,\n * the adjusted entities, and the actual `from`/`to` used after snapping.\n */\nexport function sliceTextWithEntities(\n  text: string,\n  entities: MessageEntity[],\n  from: number,\n  to: number\n): {text: string, entities: MessageEntity[], from: number, to: number} {\n  from = Math.max(0, Math.min(from, text.length));\n  to = Math.max(0, Math.min(to, text.length));\n  if(to < from) to = from;\n\n  const boundaries = graphemeBoundaries(text);\n  const start = snapUp(boundaries, from);\n  let end = snapDown(boundaries, to);\n  if(end < start) end = start;\n\n  const slicedText = text.slice(start, end);\n\n  const out: MessageEntity[] = [];\n  for(const e of entities) {\n    const eStart = e.offset ?? 0;\n    const eLen = e.length ?? 0;\n    const eEnd = eStart + eLen;\n\n    if(ZERO_LENGTH.has(e._)) {\n      if(eStart >= start && eStart <= end) {\n        out.push({...e, offset: eStart - start, length: 0});\n      }\n      continue;\n    }\n\n    if(eEnd <= start || eStart >= end) continue;\n\n    const fullyInside = eStart >= start && eEnd <= end;\n    if(!fullyInside && ATOMIC.has(e._)) continue;\n\n    const newStart = Math.max(eStart, start);\n    const newEnd = Math.min(eEnd, end);\n    out.push({...e, offset: newStart - start, length: newEnd - newStart});\n  }\n\n  return {text: slicedText, entities: out, from: start, to: end};\n}\n","import {MessageEntity} from '@layer';\nimport {sliceTextWithEntities} from '@lib/richTextProcessor/sliceTextWithEntities';\n\n/**\n * Uses Unicode horizontal ellipsis (U+2026) instead of \"...\"\n * for better typography, line breaking, and internationalization.\n */\nconst ELLIPSIS = '…';\n\nexport function truncateTextWithEntities(\n  text: string,\n  entities: MessageEntity[],\n  n: number\n): {text: string, entities: MessageEntity[]} {\n  if(text.length <= n) {\n    return {text, entities};\n  }\n\n  if(n <= ELLIPSIS.length) {\n    // Not enough room for content + ellipsis; just return as much ellipsis as fits.\n    return {text: ELLIPSIS.slice(0, Math.max(0, n)), entities: []};\n  }\n\n  const budget = n - ELLIPSIS.length;\n  const sliced = sliceTextWithEntities(text, entities, 0, budget);\n\n  return {\n    text: sliced.text + ELLIPSIS,\n    entities: sliced.entities\n  };\n}\n","import type {PollVoteRestriction} from '@appManagers/utils/polls/pollVoteRestriction';\nimport getPollCountryName from '@helpers/getPollCountryName';\nimport {Poll} from '@layer';\nimport {FormatterArguments, join, LangPackKey} from '@lib/langPack';\n\nexport type PollVoteRestrictionText = {\n  langPackKey: LangPackKey;\n  langPackArguments?: FormatterArguments;\n};\n\nexport function getPollVoteRestrictionDisplayState(\n  activeRestriction: PollVoteRestriction | undefined,\n  hideResults: boolean\n) {\n  return {\n    forceResults: !!activeRestriction && !hideResults,\n    showVotersCount: !!activeRestriction\n  };\n}\n\nexport function getPollVoteRestrictionText(\n  poll: Poll,\n  restriction: PollVoteRestriction,\n  peerName?: string\n): PollVoteRestrictionText {\n  if(restriction === 'subscribersOnly') {\n    return peerName ? {\n      langPackKey: 'Poll.VoteRestricted.SubscribersChannel',\n      langPackArguments: [peerName]\n    } : {\n      langPackKey: 'Poll.VoteRestricted.Subscribers'\n    };\n  }\n\n  if(restriction === 'subscribersJoinedTooRecently') {\n    return {langPackKey: 'Poll.VoteRestricted.SubscribersRecent'};\n  }\n\n  const countries = poll.countries_iso2?.map(getPollCountryName).filter(Boolean);\n  return countries?.length ? {\n    langPackKey: 'Poll.VoteRestricted.CountriesList',\n    langPackArguments: [join(countries, true, true)]\n  } : {\n    langPackKey: 'Poll.VoteRestricted.Countries'\n  };\n}\n","import {isRegularPollMessage} from '@appManagers/utils/polls/pollVoteRestriction';\nimport {Message} from '@layer';\n\nexport function canViewPollStatistics(message?: Message, isRegularSurface = true) {\n  return message?._ === 'message' &&\n    message.media?._ === 'messageMediaPoll' &&\n    !!message.media.results.pFlags.can_view_stats &&\n    !message.pFlags.is_outgoing &&\n    isRegularPollMessage(message, isRegularSurface);\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type {MyPhoto} from '@appManagers/appPhotosManager';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport IMAGE_MIME_TYPES_SUPPORTED from '@environment/imageMimeTypesSupport';\nimport {getAppWindow} from '@helpers/appWindow';\nimport canvasToBlob from '@helpers/canvas/canvasToBlob';\nimport {canWriteClipboardItem, writeClipboardItem} from '@helpers/clipboard';\nimport appDownloadManager from '@lib/appDownloadManager';\n\nconst CLIPBOARD_MIME_TYPE = 'image/png';\n\ntype CopyableMedia = MyPhoto | MyDocument;\n\nexport function canCopyMediaToClipboard(media: CopyableMedia) {\n  if(!media || (\n    media._ !== 'photo' &&\n    (media._ !== 'document' || !IMAGE_MIME_TYPES_SUPPORTED.has(media.mime_type))\n  )) {\n    return false;\n  }\n\n  return canWriteClipboardItem(CLIPBOARD_MIME_TYPE);\n}\n\nfunction downloadFullSizeMedia(media: CopyableMedia) {\n  return appDownloadManager.downloadMedia({\n    media,\n    thumb: media._ === 'photo' ? choosePhotoSize(media, Infinity, Infinity) : undefined\n  });\n}\n\nasync function convertToPng(blob: Blob) {\n  if(blob.type === CLIPBOARD_MIME_TYPE) {\n    return blob;\n  }\n\n  const appWindow = getAppWindow();\n  const canvas = appWindow.document.createElement('canvas');\n  const context = canvas.getContext('2d');\n  let source: CanvasImageSource;\n  let width: number;\n  let height: number;\n  let cleanup: () => void;\n\n  if(appWindow.createImageBitmap) {\n    const bitmap = await appWindow.createImageBitmap(blob);\n    source = bitmap;\n    width = bitmap.width;\n    height = bitmap.height;\n    cleanup = () => bitmap.close();\n  } else {\n    const image = appWindow.document.createElement('img');\n    const URLConstructor = (appWindow as any).URL as typeof URL;\n    const url = URLConstructor.createObjectURL(blob);\n    image.src = url;\n    try {\n      await image.decode();\n    } catch(error) {\n      URLConstructor.revokeObjectURL(url);\n      throw error;\n    }\n\n    source = image;\n    width = image.naturalWidth;\n    height = image.naturalHeight;\n    cleanup = () => URLConstructor.revokeObjectURL(url);\n  }\n\n  canvas.width = width;\n  canvas.height = height;\n\n  try {\n    context.drawImage(source, 0, 0);\n    return await canvasToBlob(canvas, CLIPBOARD_MIME_TYPE);\n  } finally {\n    cleanup();\n  }\n}\n\nexport default function copyMediaToClipboard(media: CopyableMedia) {\n  if(!canCopyMediaToClipboard(media)) {\n    return Promise.reject(new Error('Media clipboard writing is not supported'));\n  }\n\n  const blobPromise = Promise.resolve()\n  .then(() => downloadFullSizeMedia(media))\n  .then(convertToPng);\n\n  try {\n    // The write itself must stay in the user-activation tick. ClipboardItem\n    // accepts the pending full-size download and resolves it before committing.\n    return writeClipboardItem({\n      [CLIPBOARD_MIME_TYPE]: blobPromise\n    });\n  } catch(error) {\n    void blobPromise.catch((): void => {});\n    return Promise.reject(error);\n  }\n}\n","import type {MyMessage} from '@appManagers/appMessagesManager';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport {ButtonMenuItemOptions, setButtonMenuItemLoading} from '@components/buttonMenu';\nimport {toastNew} from '@components/toast';\nimport copyMediaToClipboard from '@helpers/copyMediaToClipboard';\nimport contextMenuController from '@helpers/contextMenuController';\n\nexport default function copyMessageMediaWithFeedback(options: {\n  message: MyMessage,\n  button: ButtonMenuItemOptions,\n  index?: number,\n  cleanup?: () => void\n}) {\n  const {message, button, index, cleanup} = options;\n  const media = getMediaFromMessage(message, true, index);\n  const buttonElement = button.element;\n  setButtonMenuItemLoading(button, true, buttonElement);\n\n  copyMediaToClipboard(media).then(() => {\n    toastNew({langPackKey: 'MediaCopied'});\n    if(buttonElement?.closest('.btn-menu')?.classList.contains('active')) {\n      contextMenuController.close();\n    }\n  }).catch((error) => {\n    console.error('media copy failed', error);\n    toastNew({langPackKey: 'MediaCopyFailed'});\n  }).finally(() => {\n    cleanup?.();\n    setButtonMenuItemLoading(button, false, buttonElement);\n  });\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport type Chat from '@components/chat/chat';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ButtonMenu, {ButtonMenuItemOptions, ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport PopupDeleteMessages from '@components/popups/deleteMessages';\nimport showForwardPopup from '@components/popups/forward';\nimport PopupPinMessage from '@components/popups/unpinMessage';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport PopupSendNow from '@components/popups/sendNow';\nimport {toastNew} from '@components/toast';\nimport I18n, {i18n, LangPackKey} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport getSelectionElementFromTarget from '@components/chat/getSelectionElementFromTarget';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport isSelectionEmpty from '@helpers/dom/isSelectionEmpty';\nimport {Message, Poll, Chat as MTChat, MessageMedia, InputStickerSet, StickerSet, Document, Reaction, Photo, SponsoredMessage, TextWithEntities, TodoItem, TodoCompletion, MessageReplyHeader, PollAnswer} from '@layer';\nimport assumeType from '@helpers/assumeType';\nimport PopupSponsored from '@components/popups/sponsored';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware} from '@helpers/middleware';\nimport PeerTitle from '@components/peerTitle';\nimport StackedAvatars from '@components/stackedAvatars';\nimport {IS_APPLE, IS_MOBILE} from '@environment/userAgent';\nimport PopupReactedList from '@components/popups/reactedList';\nimport {ChatReactionsMenu, REACTION_CONTAINER_SIZE} from '@components/chat/reactionsMenu';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport {AppManagers} from '@lib/managers';\nimport positionMenu, {MenuPositionPadding, positionFloatingMenu} from '@helpers/positionMenu';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport filterAsync from '@helpers/array/filterAsync';\nimport appDownloadManager, {DownloadBlob} from '@lib/appDownloadManager';\nimport {SERVICE_PEER_ID} from '@appManagers/constants';\nimport {MessagesStorageKey, MyMessage} from '@appManagers/appMessagesManager';\nimport filterUnique from '@helpers/array/filterUnique';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport wrapEmojiText, {wrapEmojiTextWithEntities} from '@lib/richTextProcessor/wrapEmojiText';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport showStickersPopup from '@components/popups/stickers';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport canSaveMessageMedia from '@appManagers/utils/messages/canSaveMessageMedia';\nimport {addToProfileMusic, getSavedMusicDocument, removeFromProfileMusic} from '@components/savedMusicActions';\nimport getGroupedText from '@appManagers/utils/messages/getGroupedText';\nimport PopupElement from '@components/popups';\nimport confirmationPopup, {PopupConfirmationOptions} from '@components/confirmationPopup';\nimport Icon from '@components/icon';\nimport cloneDOMRect from '@helpers/dom/cloneDOMRect';\nimport PopupPremium from '@components/popups/premium';\nimport {ChatInputReplyTo} from '@components/chat/input';\nimport {makeFullMid, TEST_BUBBLES_DELETION} from '@components/chat/bubbles';\nimport AppStatisticsTab from '@components/sidebarRight/tabs/statistics';\nimport {ChatType} from './chatType';\nimport {formatFullSentTime} from '@helpers/date';\nimport PopupToggleReadDate from '@components/popups/toggleReadDate';\nimport rootScope from '@lib/rootScope';\nimport ReactionElement from '@components/chat/reaction';\nimport ReactionsElement from '@components/chat/reactions';\nimport createReactionContextMenu from '@components/chat/reactionContextMenu';\nimport InputField from '@components/inputField';\nimport getMainGroupedMessage from '@appManagers/utils/messages/getMainGroupedMessage';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport getRichSelection from '@helpers/dom/getRichSelection';\nimport detectLanguageForTranslation from '@helpers/detectLanguageForTranslation';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport documentFragmentToHTML from '@helpers/dom/documentFragmentToHTML';\nimport {showAdReport, showMessageReport} from '@components/popups/reportAd';\nimport showAboutAdPopup from '@components/popups/aboutAd';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport deepEqual from '@helpers/object/deepEqual';\nimport wrapDraftText from '@lib/richTextProcessor/wrapDraftText';\nimport PopupStarReaction from '@components/popups/starReaction';\nimport getUniqueCustomEmojisFromMessage from '@appManagers/utils/messages/getUniqueCustomEmojisFromMessage';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport {getFullDate} from '@helpers/date/getFullDate';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {MySponsoredPeer} from '@appManagers/appChatsManager';\nimport showChecklistPopup from '@components/popups/checklist';\nimport createSubmenuTrigger, {CreateSubmenuArgs} from '@components/createSubmenuTrigger';\nimport noop from '@helpers/noop';\nimport {isSensitive} from '@helpers/restrictions';\nimport {hasSensitiveSpoiler} from '@components/wrappers/mediaSpoiler';\nimport {useIsFrozen} from '@stores/appState';\nimport prepareTextWithEntitiesForCopying from '@helpers/prepareTextWithEntitiesForCopying';\nimport {runWithHotReloadGuard} from '@lib/solidjs/runWithHotReloadGuard';\nimport {PartialByKeys} from '@types';\nimport {ContextMenuDeleteOptionText} from '@components/chat/contextMenuDeleteOptionText';\nimport getMarkupInSelection from '@helpers/dom/getMarkupInSelection';\nimport isNodeFullyInsideRange from '@helpers/dom/isNodeFullyInsideRange';\nimport parseEntities from '@lib/richTextProcessor/parseEntities';\nimport {concatTextsWithEntities} from '@lib/richTextProcessor/concatTextsWithEntities';\nimport {shouldShufflePollOptions, shufflePollOptions} from './bubbleParts/pollMessageContent/shuffle';\nimport {truncateTextWithEntities} from '@lib/richTextProcessor/truncateTextWithEntities';\nimport {pollOptionToLink} from './bubbleParts/pollMessageContent/pollToOptionLink';\nimport {getPollVoteRestrictionPeerId} from '@appManagers/utils/polls/pollVoteRestriction';\nimport {getPollVoteRestrictionText} from './bubbleParts/pollMessageContent/pollVoteRestriction';\nimport {canViewPollStatistics as canViewPollStatisticsForMessage} from './bubbleParts/pollMessageContent/pollStatistics';\nimport {canCopyMediaToClipboard} from '@helpers/copyMediaToClipboard';\nimport copyMessageMediaWithFeedback from '@components/copyMessageMediaWithFeedback';\nimport isEphemeralMessage from '@appManagers/utils/messages/isEphemeralMessage';\n\ntype ChatContextMenuButton = ButtonMenuItemOptions & {\n  verify: () => boolean | Promise<boolean>,\n  notDirect?: () => boolean,\n  withSelection?: true,\n  isSponsored?: true,\n  localName?: 'views' | 'emojis' | 'sponsorInfo' | 'sponsorAdditionalInfo'\n};\n\nexport function getSponsoredMessageButtons(options: {\n  message?: SponsoredMessage | MySponsoredPeer,\n  handleReportAd: () => void,\n  handleCopy?: () => void,\n  extraVerify?: () => boolean,\n}): ChatContextMenuButton[] {\n  const {\n    message,\n    extraVerify = () => true,\n    handleReportAd,\n    handleCopy\n  } = options;\n  if(!message) return []\n\n  const canReport = message._ === 'sponsoredPeer' ? true : message.pFlags.can_report;\n\n  return [\n    {\n      icon: 'info',\n      text: 'Chat.Message.Sponsored.What',\n      onClick: () => {\n        PopupElement.createPopup(PopupSponsored);\n      },\n      verify: () => extraVerify() && !canReport,\n      isSponsored: true\n    }, {\n      icon: 'info',\n      text: 'AboutRevenueSharingAds',\n      onClick: () => {\n        showAboutAdPopup();\n      },\n      verify: () => extraVerify() && !!canReport,\n      isSponsored: true\n    }, {\n      icon: 'hand',\n      text: 'HideAd',\n      onClick: () => {\n        PopupPremium.show({feature: 'no_ads'});\n      },\n      verify: () => extraVerify() && !canReport,\n      isSponsored: true\n    }, {\n      icon: 'hand',\n      text: 'ReportAd',\n      onClick: handleReportAd,\n      verify: () => extraVerify() && !!canReport,\n      isSponsored: true\n    }, {\n      icon: 'crossround',\n      text: 'RemoveAds',\n      onClick: () => {\n        PopupPremium.show({feature: 'no_ads'});\n      },\n      verify: () => extraVerify() && !!canReport,\n      isSponsored: true\n    }, {\n      icon: 'copy',\n      text: 'Copy',\n      onClick: handleCopy,\n      verify: () => handleCopy != null && extraVerify(),\n      isSponsored: true\n    }, {\n      regularText: message.sponsor_info ? wrapEmojiText(message.sponsor_info) : undefined,\n      separator: true,\n      secondary: true,\n      onClick: () => copyTextToClipboard(message.sponsor_info),\n      verify: () => extraVerify() && !!message.sponsor_info,\n      isSponsored: true\n    }, {\n      regularText: message.additional_info ? wrapEmojiText(message.additional_info) : undefined,\n      separator: true,\n      secondary: true,\n      onClick: () => copyTextToClipboard(message.additional_info),\n      verify: () => extraVerify() && !!message.additional_info,\n      isSponsored: true\n    }]\n}\n\nexport default class ChatContextMenu {\n  private buttons: ChatContextMenuButton[];\n  private element: HTMLElement;\n\n  private isSelectable: boolean;\n  private isSelected: boolean;\n  private target: HTMLElement;\n  private isTargetAGroupedItem: boolean;\n  private isTextSelected: boolean;\n  private isTextFromMultipleMessagesSelected: boolean;\n  private isAnchorTarget: boolean;\n  private isUsernameTarget: boolean;\n  private isEmailTarget: boolean;\n  private isSponsored: boolean;\n  private isOverBubble: boolean;\n  private isTag: boolean;\n  private reactionElement: ReactionElement;\n  private peerId: PeerId;\n  private mid: number;\n  private message: Message.message | Message.messageService;\n  private messageFromLog: Message.message | Message.messageService;\n  private mainMessage: Message.message | Message.messageService;\n  private sponsoredMessage: SponsoredMessage;\n  private noForwards: boolean;\n  private checklistItem: {item: TodoItem, completion?: TodoCompletion};\n  private pollAnswer: {\n    idx: number;\n    value: PollAnswer.pollAnswer;\n  };\n\n  private reactionsMenu: ChatReactionsMenu;\n  private listenerSetter: ListenerSetter;\n  private attachListenerSetter: ListenerSetter;\n\n  private viewerPeerId: PeerId;\n  private middleware: ReturnType<typeof getMiddleware>;\n  private canOpenReactedList: boolean;\n\n  private emojiInputsPromise: CancellablePromise<InputStickerSet.inputStickerSetID[]>;\n  private groupedMessages: Message.message[];\n  private linkToMessage: Awaited<ReturnType<ChatContextMenu['getUrlToMessage']>>;\n  private selectedMessagesText: PartialByKeys<Awaited<ReturnType<ChatContextMenu['getSelectedMessagesText']>>, 'html'>;\n  private selectedMessages: MyMessage[];\n  private avatarPeerId: number;\n  private copyMediaButton: ChatContextMenuButton;\n\n  private isLegacy: boolean;\n  private messagePeerId: number;\n\n  private canViewReadTime: boolean;\n  private messageLanguage: TranslatableLanguageISO;\n  private bubble?: HTMLElement;\n\n  constructor(\n    private chat: Chat,\n    private managers: AppManagers\n  ) {\n    this.listenerSetter = new ListenerSetter();\n    this.attachListenerSetter = new ListenerSetter();\n    this.middleware = getMiddleware();\n  }\n\n  public attachTo(element: HTMLElement) {\n    this.attachListenerSetter.removeAll();\n\n    if(IS_TOUCH_SUPPORTED/*  && false */) {\n      // Reaction taps are handled by the inner bubbles delegate, which stops\n      // the synthetic mousedown before it reaches this container. Listen to\n      // touchstart in capture phase so a real hold can still open the same\n      // reaction-specific menu without changing the normal tap behavior.\n      attachContextMenuListener({\n        element,\n        callback: (e) => {\n          if(\n            !this.chat.selection.isSelecting &&\n            (e.target as HTMLElement).closest('reaction-element')\n          ) {\n            this.onContextMenu(e);\n            const options = {\n              capture: true,\n              once: true\n            };\n            const listenerSetter = this.attachListenerSetter;\n            function onTouchEnd(e: TouchEvent) {\n              listenerSetter.removeManual(element, 'touchcancel', onTouchCancel, options);\n              cancelEvent(e);\n            }\n            function onTouchCancel() {\n              listenerSetter.removeManual(element, 'touchend', onTouchEnd, options);\n            }\n            listenerSetter.add(element)('touchend', onTouchEnd, options);\n            listenerSetter.add(element)('touchcancel', onTouchCancel, options);\n          }\n        },\n        listenerSetter: this.attachListenerSetter,\n        listenerOptions: {capture: true}\n      });\n\n      attachClickEvent(element, (e) => {\n        if(this.chat.selection.isSelecting) {\n          return;\n        }\n\n        this.chat.log('touchend', e);\n\n        const badSelectors = [\n          '.name',\n          '.peer-title',\n          '.reply',\n          '.document',\n          '.audio',\n          // 'avatar-element',\n          'a',\n          '.bubble-beside-button',\n          'replies-element',\n          '[data-saved-from]:not(.bubble)',\n          'poll-element',\n          '.attachment',\n          '.reply-markup-button',\n          '.bubble-view-button',\n          '.webpage',\n          '.bubbles-group-avatar',\n          '.bubble-service-button'\n        ];\n        const good = !(e.target as HTMLElement).closest(badSelectors.join(', '));\n        if(good) {\n          cancelEvent(e);\n          // onContextMenu((e as TouchEvent).changedTouches[0]);\n          // onContextMenu((e as TouchEvent).changedTouches ? (e as TouchEvent).changedTouches[0] : e as MouseEvent);\n          this.onContextMenu(e);\n        }\n      }, {listenerSetter: this.attachListenerSetter});\n    } else attachContextMenuListener({\n      element,\n      callback: this.onContextMenu,\n      listenerSetter: this.attachListenerSetter\n    });\n\n    // * handle message deletion\n    this.attachListenerSetter.add(rootScope)('history_delete', ({peerId, msgs}) => {\n      if(peerId !== this.chat.peerId) {\n        return;\n      }\n\n      if(this.mid && msgs.has(this.mid)) {\n        contextMenuController.close();\n        return;\n      }\n\n      if(this.chat.selection.isSelecting && this.selectedMessages) {\n        const hasDeletedSelectedMessage = this.selectedMessages.some((message) => msgs.has(message.mid));\n        if(hasDeletedSelectedMessage) {\n          contextMenuController.close();\n          return;\n        }\n      }\n\n      if(this.groupedMessages) {\n        const hasDeletedGroupedMessage = this.groupedMessages.some((message) => msgs.has(message.mid));\n        if(hasDeletedGroupedMessage) {\n          contextMenuController.close();\n        }\n      }\n    });\n\n    this.attachListenerSetter.add(rootScope)('ephemeral_history_delete', ({peerId, msgs}) => {\n      if(peerId !== this.chat.peerId) {\n        return;\n      }\n\n      if(this.mid && msgs.has(this.mid)) {\n        contextMenuController.close();\n        return;\n      }\n\n      if(this.groupedMessages?.some((message) => msgs.has(message.mid))) {\n        contextMenuController.close();\n      }\n    });\n  }\n\n  public onContextMenu = (e: MouseEvent | Touch | TouchEvent) => {\n    if(this.chat.type === ChatType.Static) return;\n\n\n    let bubble: HTMLElement, contentWrapper: HTMLElement, avatar: HTMLElement;\n\n    try {\n      contentWrapper = findUpClassName(e.target, 'bubble-content-wrapper');\n      bubble = contentWrapper ? contentWrapper.parentElement : findUpClassName(e.target, 'bubble');\n      avatar = findUpClassName(e.target, 'bubbles-group-avatar') as HTMLElement || undefined;\n    } catch(e) {}\n\n    // ! context menu click by date bubble (there is no pointer-events)\n    if((!bubble || bubble.classList.contains('bubble-first')) && !avatar) return;\n\n    let element = this.element;\n    // `!('touches' in e)` is the cross-realm-safe equivalent of `instanceof MouseEvent`: it stays true\n    // for a Document PiP window's mouse event (whose constructor is a different realm, so `instanceof`\n    // the main realm's MouseEvent is false) while still excluding TouchEvent/Touch — otherwise the\n    // native browser context menu wasn't suppressed on right-click inside the popped-out client.\n    if(!('touches' in e) && 'preventDefault' in e) (e as any).preventDefault();\n    if(element && element.classList.contains('active')) {\n      return false;\n    }\n    if(!('touches' in e) && 'cancelBubble' in e) (e as any).cancelBubble = true;\n\n    let mid = avatar ? 0 : +bubble.dataset.mid;\n    if(!mid && mid !== 0) {\n      return;\n    }\n\n    if(avatar && !avatar.dataset.peerId) {\n      toastNew({langPackKey: 'HidAccount'});\n      return;\n    }\n\n    const paidReactionElement = (e.target as HTMLElement).closest('.reaction.is-paid');\n    if(paidReactionElement) {\n      PopupElement.createPopup(PopupStarReaction, bubble.dataset.peerId.toPeerId(), mid, this.chat);\n      return;\n    }\n\n    const reactionElement = (e.target as HTMLElement).closest('reaction-element') as ReactionElement;\n    const tagReactionElement = reactionElement?.classList.contains('reaction-tag') ? reactionElement : undefined;\n    if(\n      reactionElement &&\n      !tagReactionElement &&\n      !this.chat.selection.isSelecting &&\n      !findUpClassName(e.target, 'tooltip')\n    ) {\n      const reactionsElement = reactionElement.parentElement as ReactionsElement;\n      if(reactionsElement?.getContext) {\n        const context = reactionsElement.getContext();\n        const reaction = reactionElement.reactionCount.reaction;\n        const canOpenReactionMenu =\n          reaction._ === 'reactionCustomEmoji' ||\n          !!context.reactions?.pFlags.can_see_list ||\n          context.peerId.isUser();\n        if(canOpenReactionMenu) {\n          void this.openReactionContextMenu(reactionElement, reactionsElement);\n          return;\n        }\n      }\n    }\n\n    let checklistItemId: number;\n    const checklistItemElement = (e.target as HTMLElement).closest('[data-checklist-item-id]');\n    if(checklistItemElement) {\n      checklistItemId = +(checklistItemElement as HTMLElement).dataset.checklistItemId;\n    }\n\n    let pollOptionIdx: number;\n    const pollOptionElement = (e.target as HTMLElement).closest('[data-poll-option-idx]');\n    if(pollOptionElement) {\n      pollOptionIdx = +(pollOptionElement as HTMLElement).dataset.pollOptionIdx;\n    }\n\n    const prepareForMessage = async() => {\n      const isSponsored = this.isSponsored = mid < 0;\n      this.isSelectable = this.chat.selection.canSelectBubble(bubble);\n      this.messagePeerId = bubble ? bubble.dataset.peerId.toPeerId() : undefined;\n      this.peerId = this.messagePeerId ?? this.chat.peerId;\n      this.target = e.target as HTMLElement;\n      this.isTextSelected = !isSelectionEmpty();\n      this.isAnchorTarget = this.target.tagName === 'A' && (\n        (this.target as HTMLAnchorElement).target === '_blank' ||\n        this.target.classList.contains('anchor-url')\n      );\n      this.isEmailTarget = this.isAnchorTarget && (this.target as HTMLAnchorElement).href.startsWith('mailto:');\n      this.isUsernameTarget = this.target.tagName === 'A' && this.target.classList.contains('mention');\n      this.isTag = !!tagReactionElement;\n      this.reactionElement = tagReactionElement as ReactionElement;\n\n      if(this.isTag && !rootScope.premium) {\n        PopupPremium.show({feature: 'saved_tags'});\n        return;\n      }\n\n      if(this.isTextSelected) {\n        const range = getAppWindow().getSelection().getRangeAt(0);\n        this.isTextFromMultipleMessagesSelected = findUpClassName(range.startContainer.parentElement, 'spoilers-container') !== findUpClassName(range.endContainer.parentElement, 'spoilers-container');\n      } else {\n        this.isTextFromMultipleMessagesSelected = false;\n      }\n\n      this.sponsoredMessage = isSponsored ? (bubble as any).message.sponsoredMessage : undefined;\n\n      const mids = avatar ? [] : await this.chat.getMidsByMid(this.messagePeerId, mid);\n      // * если открыть контекстное меню для альбома не по бабблу, и последний элемент не выбран, чтобы показать остальные пункты\n      if(this.chat.selection.isSelecting && !contentWrapper && mid) {\n        if(isSponsored) {\n          return;\n        }\n\n        if(mids.length > 1) {\n          const selectedMid = this.chat.selection.isMidSelected(this.messagePeerId, mid) ?\n            mid :\n            mids.find((mid) => this.chat.selection.isMidSelected(this.messagePeerId, mid));\n          if(selectedMid) {\n            mid = selectedMid;\n          }\n        }\n      }\n\n      this.isOverBubble = !!contentWrapper;\n\n      this.avatarPeerId = avatar && avatar.dataset.peerId.toPeerId();\n\n      const groupedItem = findUpClassName(this.target, 'grouped-item');\n      this.isTargetAGroupedItem = !!groupedItem;\n      if(groupedItem) {\n        this.mid = +groupedItem.dataset.mid;\n      } else {\n        this.mid = mid;\n      }\n\n      this.isLegacy = this.messagePeerId && this.messagePeerId !== this.peerId;\n      this.isSelected = this.chat.selection.isMidSelected(this.messagePeerId, this.mid);\n      this.message = avatar ? undefined : (bubble as any).message || this.chat.getMessageByPeer(this.messagePeerId, this.mid);\n      this.groupedMessages = (this.message as Message.message)?.grouped_id ? await this.managers.appMessagesManager.getMessagesByGroupedId((this.message as Message.message).grouped_id) : undefined;\n      if(!groupedItem && this.groupedMessages) this.message = getMainGroupedMessage(this.groupedMessages);\n      this.mainMessage = this.groupedMessages ? getMainGroupedMessage(this.groupedMessages) : this.message;\n      this.selectedMessages = this.chat.selection.isSelecting && !avatar ? await this.chat.selection.getSelectedMessages() : undefined;\n      this.noForwards = this.message && !isSponsored && !(await Promise.all((this.selectedMessages || [this.message]).map((message) => this.managers.appMessagesManager.canForward(message)))).every(Boolean);\n      this.viewerPeerId = undefined;\n      this.canOpenReactedList = undefined;\n      this.linkToMessage = await this.getUrlToMessage();\n      this.selectedMessagesText = await this.getSelectedMessagesText();\n      this.messageLanguage = await this.getMessageLanguage();\n      this.bubble = findUpClassName(e.target, 'bubble');\n\n      if(checklistItemId) {\n        const media = (this.message as Message.message).media as MessageMedia.messageMediaToDo;\n        this.checklistItem = {\n          item: media.todo.list.find((item) => item.id === checklistItemId),\n          completion: media.completions?.find((completion) => completion.id === checklistItemId)\n        };\n      } else {\n        this.checklistItem = undefined;\n      }\n\n      if(pollOptionIdx !== undefined) {\n        const media = (this.message as Message.message).media as MessageMedia.messageMediaPoll;\n        const answer = media?.poll?.answers?.[pollOptionIdx];\n        this.pollAnswer = answer?._ === 'pollAnswer' ? {idx: pollOptionIdx, value: answer} : undefined;\n      } else {\n        this.pollAnswer = undefined;\n      }\n    };\n\n\n    const prepareForLog = async() => {\n      const log = this.chat.bubbles.logsByBubble.get(bubble);\n      try {\n        const entry = await this.chat.bubbles.resolveAdminLog({\n          log,\n          noJsx: true\n        });\n\n        this.selectedMessagesText = await runWithHotReloadGuard(entry.getCopyText);\n        this.messageFromLog = entry.type === 'default' ? entry.message : undefined;\n      } catch{}\n    };\n\n    const openMenu = async() => {\n      if(this.chat.type === ChatType.Logs) {\n        await prepareForLog();\n      } else {\n        await prepareForMessage();\n      }\n\n      const initResult = await this.init();\n      if(!initResult) {\n        return;\n      }\n\n      element = initResult.element;\n      const {cleanup, destroy, menuPadding, reactionsMenu, reactionsMenuPosition} = initResult;\n      const reactionsCallbacks = reactionsMenu && ChatContextMenu.appendReactionsMenu({element, reactionsMenu, reactionsMenuPosition});\n\n      const side: 'left' | 'right' = !bubble || bubble.classList.contains('is-in') ? 'left' : 'right';\n      // bubble.parentElement.append(element);\n      // appImManager.log('contextmenu', e, bubble, side);\n      positionMenu((e as TouchEvent).touches ? (e as TouchEvent).touches[0] : e as MouseEvent, element, side, menuPadding);\n\n      const cleanupHighlight = this.highlightPollAnswer();\n\n      // * the menu belongs to a message, not to an avatar — highlight it the way it gets selected\n      const activeElement = bubble && getSelectionElementFromTarget(e.target);\n      activeElement && this.chat.bubbles.toggleActiveBubble(activeElement, true);\n\n      // if(reactionsMenu) {\n      //   reactionsMenu.widthContainer.style.top = element.style.top;\n      //   reactionsMenu.widthContainer.style.left = element.style.left;\n      //   reactionsMenu.widthContainer.style.setProperty('--menu-width', element[reactionsMenuPosition === 'vertical' ? 'offsetHeight' : 'offsetWidth'] + 'px');\n      //   element.parentElement.append(reactionsMenu.widthContainer);\n      //   if(isReactionsMenuVisible) void reactionsMenu.container.offsetLeft; // reflow\n      // }\n\n      contextMenuController.openBtnMenu(element, () => {\n        reactionsCallbacks?.onClose();\n        cleanupHighlight?.();\n        activeElement && this.chat.bubbles.toggleActiveBubble(activeElement, false);\n\n        this.mid = 0;\n        this.peerId = undefined;\n        this.target = null;\n        this.viewerPeerId = undefined;\n        this.canOpenReactedList = undefined;\n        cleanup();\n\n        setTimeout(() => {\n          destroy();\n        }, 300);\n      });\n\n      reactionsCallbacks?.onAfterInit();\n    };\n\n    openMenu();\n  };\n\n  private async openReactionContextMenu(\n    reactionElement: ReactionElement,\n    reactionsElement: ReactionsElement\n  ) {\n    this.cleanup();\n    const middleware = this.middleware.get();\n    const reactionListenerSetter = new ListenerSetter();\n    const context = reactionsElement.getContext();\n    const appDocument = getAppWindow().document;\n    let pending = true;\n    const cancelPending = () => {\n      if(pending && middleware()) {\n        this.middleware.clean();\n      }\n    };\n    const removePendingListeners = () => {\n      appDocument.removeEventListener('pointerdown', cancelPending, true);\n      appDocument.removeEventListener('keydown', cancelPending, true);\n    };\n    appDocument.addEventListener('pointerdown', cancelPending, {capture: true, once: true});\n    appDocument.addEventListener('keydown', cancelPending, {capture: true, once: true});\n    middleware.onClean(removePendingListeners);\n    reactionListenerSetter.add(rootScope)('history_delete', ({peerId, msgs}) => {\n      if(peerId !== context.peerId || !msgs.has(context.mid)) {\n        return;\n      }\n\n      if(pending) {\n        this.middleware.clean();\n      } else {\n        contextMenuController.close();\n      }\n    });\n\n    let result: Awaited<ReturnType<typeof createReactionContextMenu>>;\n    try {\n      result = await createReactionContextMenu({\n        chat: this.chat,\n        managers: this.managers,\n        reactionElement,\n        reactionsElement,\n        middleware,\n        listenerSetter: reactionListenerSetter\n      });\n    } catch(err) {\n      reactionListenerSetter.removeAll();\n      if(middleware()) {\n        this.middleware.clean();\n      }\n      return;\n    } finally {\n      pending = false;\n      removePendingListeners();\n    }\n\n    if(!middleware() || !result || contextMenuController.isOpened()) {\n      result?.destroy();\n      reactionListenerSetter.removeAll();\n      return;\n    }\n\n    const {element, destroy} = result;\n    this.element = element;\n    element.id = 'reaction-contextmenu';\n    getOverlayRoot().append(element);\n\n    const bubble = reactionElement.closest('.bubble');\n    const alignment = bubble?.classList.contains('is-in') ? 'start' : 'end';\n    positionFloatingMenu(\n      reactionElement.getBoundingClientRect(),\n      element,\n      `top-${alignment}`,\n      [0, 8]\n    );\n\n    contextMenuController.openBtnMenu(element, () => {\n      this.element = undefined;\n      reactionListenerSetter.removeAll();\n      this.middleware.clean();\n      setTimeout(destroy, 300);\n    }, reactionElement);\n  }\n\n  private highlightPollAnswer() {\n    if(!this.pollAnswer || !this.bubble) return;\n\n    const bubbleContext = this.chat.bubbles.contexts.get(this.bubble);\n    if(!bubbleContext?.pollMessageContentControls) return;\n\n    bubbleContext.pollMessageContentControls.highlightAnswer?.(this.pollAnswer.idx);\n\n    return () => {\n      bubbleContext.pollMessageContentControls.highlightAnswer?.(null);\n    }\n  }\n\n  public cleanup() {\n    this.listenerSetter.removeAll();\n    this.reactionsMenu && this.reactionsMenu.cleanup();\n    this.middleware.clean();\n  }\n\n  public destroy() {\n    this.cleanup();\n    this.attachListenerSetter.removeAll();\n  }\n\n  private async filterButtons(buttons: ChatContextMenu['buttons']) {\n    return filterAsync(buttons, async(button) => {\n      let good: boolean;\n\n      if((this.isSponsored && !button.isSponsored) || (!this.isSponsored && button.isSponsored)) {\n        return false;\n      }\n\n      // if((appImManager.chatSelection.isSelecting && !button.withSelection) || (button.withSelection && !appImManager.chatSelection.isSelecting)) {\n      if(this.chat.selection.isSelecting && !button.withSelection) {\n        good = false;\n      } else {\n        good = this.isOverBubble || IS_TOUCH_SUPPORTED || true ?\n          await button.verify() :\n          button.notDirect && await button.verify() && button.notDirect();\n      }\n\n      return !!good;\n    });\n  }\n\n  private setButtons() {\n    if(this.chat.type === ChatType.Logs) {\n      this.buttons = [\n        {\n          icon: 'copy',\n          text: 'Copy',\n          onClick: this.onCopyClick,\n          verify: () => !!this.selectedMessagesText\n        },\n        {\n          icon: 'download',\n          text: 'DownloadMedia',\n          onClick: () => {\n            const media = getMediaFromMessage(this.messageFromLog, true);\n            if(!media) return;\n            appDownloadManager.downloadToDisc({media, queueId: this.chat.bubbles.lazyLoadQueue.queueId});\n          },\n          verify: () => this.messageFromLog && !!getMediaFromMessage(this.messageFromLog)\n        }\n      ];\n      return;\n    }\n\n    if(this.isTag) {\n      const tagTitle = this.reactionElement.findTitle();\n      const reactionCount = this.reactionElement.reactionCount;\n      const renameTitle: LangPackKey = tagTitle ? 'SavedTagRenameTag' : 'SavedTagLabelTag';\n      this.buttons = [{\n        icon: 'tag_filter',\n        text: 'SavedTagFilterByTag',\n        onClick: () => {\n          this.chat.initSearch({reaction: reactionCount.reaction});\n        },\n        verify: () => true\n      }, {\n        icon: 'tag_name',\n        text: renameTitle,\n        onClick: async() => {\n          const inputField = new InputField({\n            maxLength: 12,\n            label: 'SavedTagLabelPlaceholder'\n          });\n\n          tagTitle && inputField.setOriginalValue(tagTitle);\n\n          await confirmationPopup({\n            titleLangKey: renameTitle,\n            descriptionLangKey: 'SavedTagLabelTagText',\n            button: {\n              langKey: 'Save'\n            },\n            inputField\n          });\n\n          this.managers.appReactionsManager.updateSavedReactionTag(\n            reactionCount.reaction,\n            inputField.value\n          );\n        },\n        verify: () => true\n      }, {\n        icon: 'tag_crossed',\n        text: 'SavedTagRemoveTag',\n        onClick: () => {\n          this.chat.sendReaction({message: this.message, reaction: reactionCount.reaction});\n        },\n        verify: () => true,\n        danger: true\n      }, {\n        // icon: 'smile',\n        text: 'Loading',\n        onClick: () => {\n          this.emojiInputsPromise.then((inputs) => {\n            showStickersPopup(inputs, true, this.chat.input);\n          });\n        },\n        verify: () => reactionCount.reaction._ === 'reactionCustomEmoji',\n        localName: 'emojis'\n      }];\n      return;\n    }\n\n    if(this.avatarPeerId !== undefined) {\n      const openPeer = () => {\n        this.chat.appImManager.setInnerPeer({\n          peerId: this.avatarPeerId,\n          stack: this.chat.appImManager.getStackFromElement(this.target)\n        });\n      };\n\n      this.buttons = [{\n        icon: 'message',\n        text: 'SendMessage',\n        onClick: openPeer,\n        verify: () => this.chat.peerId !== this.avatarPeerId && this.avatarPeerId.isUser()\n      }, {\n        icon: 'newgroup',\n        text: 'OpenGroup2',\n        onClick: openPeer,\n        verify: () => this.chat.peerId !== this.avatarPeerId && this.managers.appPeersManager.isAnyGroup(this.avatarPeerId)\n      }, {\n        icon: 'newchannel',\n        text: 'OpenChannel2',\n        onClick: openPeer,\n        verify: () => this.chat.peerId !== this.avatarPeerId && this.managers.appPeersManager.isBroadcast(this.avatarPeerId)\n      }, {\n        icon: 'mention',\n        text: 'Mention',\n        onClick: () => {\n          this.chat.input.mentionUser(this.avatarPeerId, false);\n        },\n        verify: () => /* this.avatarPeerId.isUser() &&  */this.chat.canSend('send_plain')\n      }, {\n        icon: 'search',\n        text: 'Search