rect: () => true,\n      withSelection: true\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Select',\n      onClick: this.onSelectClick,\n      verify: () => !(this.message as Message.messageService).action && !this.isSelected && this.isSelectable,\n      notDirect: () => true,\n      withSelection: true\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Selection.Clear',\n      onClick: this.onClearSelectionClick,\n      verify: () => this.isSelected,\n      notDirect: () => true,\n      withSelection: true\n    }, {\n      onClick: () => {\n        if(this.viewerPeerId && false) {\n          this.chat.appImManager.setInnerPeer({\n            peerId: this.viewerPeerId\n          });\n        } else if(this.canOpenReactedList) {\n          PopupElement.createPopup(PopupReactedList, this.message as Message.message);\n        } else {\n          return false;\n        }\n      },\n      verify: () => !this.peerId.isUser() &&\n        !isEphemeralMessage(this.message) &&\n        (!!(this.message as Message.message).reactions?.recent_reactions?.length || this.managers.appMessagesManager.canViewMessageReadParticipants(this.message)),\n      notDirect: () => true,\n      localName: 'views'\n    }, {\n      icon: 'rotate_right',\n      text: 'Resend',\n      onClick: () => this.handleRepay(),\n      verify: () => 'repayRequest' in this.message && !!this.message.repayRequest\n    }, {\n      icon: 'delete',\n      get className() {\n        if(self.message?.ttl_period) return 'danger with-subtitle';\n        return 'danger';\n      },\n      get regularText() {\n        const content = new ContextMenuDeleteOptionText;\n        content.feedProps({\n          dateTimestamp: self.message.date,\n          ttlPeriod: self.message.ttl_period || 0\n        });\n        return content;\n      },\n      onClick: this.onDeleteClick,\n      verify: async() => this.managers.appMessagesManager.canDeleteMessage(this.message)\n    }, {\n      regularText: i18n('Ephemeral.About'),\n      className: 'ephemeral-context-about',\n      separator: true,\n      secondary: true,\n      onClick: noop,\n      verify: () => isEphemeralMessage(this.message)\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Message.Context.Selection.Delete',\n      onClick: this.onDeleteClick,\n      verify: () => !!this.chat.selection.selectionDeleteBtn &&\n        this.isSelected &&\n        !this.chat.selection.selectionDeleteBtn.hasAttribute('disabled'),\n      notDirect: () => true,\n      withSelection: true\n    },\n    ...getSponsoredMessageButtons({\n      message: this.sponsoredMessage,\n      extraVerify: () => this.isSponsored,\n      handleReportAd: () => {\n        const {peerId, mid} = this.message;\n        showAdReport(this.sponsoredMessage, () => {\n          this.chat.bubbles.deleteMessagesByIds([makeFullMid(peerId, mid)], true)\n        });\n      },\n      handleCopy: this.onCopyClick\n    }),\n    {\n      // icon: 'smile',\n      text: 'Loading',\n      onClick: () => {\n        this.emojiInputsPromise.then((inputs) => {\n          showStickersPopup(inputs, true, this.chat.input);\n        });\n      },\n      verify: () => !!this.getUniqueCustomEmojisFromMessage().length,\n      notDirect: () => true,\n      localName: 'emojis'\n    }];\n  }\n\n  private createChecklistItemSubmenu = async({middleware}: CreateSubmenuArgs) => {\n    const {item, completion} = this.checklistItem;\n    const message = this.message as Message.message & {media: MessageMedia.messageMediaToDo};\n    const canEdit = await this.managers.appMessagesManager.canEditMessage(message, 'text');\n    const buttons: ButtonMenuItemOptionsVerifiable[] = [\n      {\n        icon: 'check',\n        regularText: completion ? formatFullSentTime(completion.date) : undefined,\n        separatorDown: true,\n        verify: () => !!completion,\n        onClick: noop\n      },\n      {\n        icon: completion ? 'checklist_undone' : 'checklist_done',\n        text: completion ? 'ChecklistUncheck' : 'ChecklistCheck',\n        verify: () => message.media.todo.pFlags.others_can_complete || message.fromId === this.managers.rootScope.myId,\n        onClick: () => {\n          this.managers.appMessagesManager.updateTodo({\n            peerId: message.peerId,\n            mid: message.mid,\n            taskId: item.id,\n            action: completion ? 'uncomplete' : 'complete'\n          })\n        }\n      },\n      {\n        icon: 'copy',\n        text: 'Copy',\n        onClick: () => copyTextToClipboard(item.title.text)\n      },\n      {\n        icon: 'edit',\n        text: 'ChecklistEditItem',\n        verify: () => canEdit,\n        onClick: () => {\n          showChecklistPopup({\n            chat: this.chat,\n            editMessage: message,\n            focusItemId: item.id\n          });\n        }\n      },\n      {\n        icon: 'delete',\n        text: 'ChecklistDeleteItem',\n        verify: () => canEdit,\n        separator: true,\n        danger: true,\n        onClick: async() => {\n          await this.managers.appMessagesManager.editMessage(message, message.message, {\n            newMedia: {\n              _: 'inputMediaTodo',\n              todo: {\n                ...message.media.todo,\n                list: message.media.todo.list.filter((v) => v.id !== item.id)\n              }\n            }\n          });\n        }\n      }\n    ];\n\n    const filteredButtons = await filterAsync(buttons, (button) => button.verify?.() ?? true);\n\n    if(!middleware()) return;\n\n    return ButtonMenu({\n      buttons: filteredButtons\n    })\n  }\n\n  private createPollAnswerSubmenu = async({middleware}: CreateSubmenuArgs) => {\n    const pollAnswer = this.pollAnswer?.value;\n    const message = this.message as Message.message & {media: MessageMedia.messageMediaPoll};\n    const canReply = !this.isLegacy &&\n      !message.pFlags.is_outgoing &&\n      !!this.chat.input.messageInput &&\n      this.chat.type !== ChatType.Scheduled &&\n      (this.chat.bubbles.canForward(message) || await this.chat.canSend());\n    const canCopyLink = !!this.linkToMessage;\n\n    const buttons: ButtonMenuItemOptionsVerifiable[] = [\n      {\n        icon: 'reply',\n        text: 'Chat.Poll.ReplyToOption',\n        verify: () => canReply,\n        onClick: () => this.onReplyToPollOptionClick(pollAnswer)\n      },\n      {\n        icon: 'copy',\n        text: 'Chat.Poll.CopyOption',\n        onClick: () => copyTextToClipboard(pollAnswer.text.text)\n      },\n      {\n        icon: 'link',\n        text: 'Chat.Poll.CopyOptionLink',\n        verify: () => canCopyLink,\n        onClick: () => {\n          const {url, isPrivate} = this.linkToMessage;\n          const optionParam = pollOptionToLink(pollAnswer.option);\n          const fullUrl = url + (url.includes('?') ? '&' : '?') + 'option=' + optionParam;\n          const key: LangPackKey = isPrivate ? 'LinkCopiedPrivateInfo' : 'LinkCopied';\n          toastNew({langPackKey: key});\n          copyTextToClipboard(fullUrl);\n        }\n      }\n    ];\n\n    const filteredButtons = await filterAsync(buttons, (button) => button.verify?.() ?? true);\n\n    if(!middleware()) return;\n\n    return ButtonMenu({\n      buttons: filteredButtons\n    })\n  }\n\n  private getSavedMusicDocId() {\n    return getSavedMusicDocument(\n      this.message,\n      isEphemeralMessage(this.message) ? false : this.noForwards\n    )?.id;\n  }\n\n  private async verifySavedMusic(inProfile: boolean) {\n    const docId = this.getSavedMusicDocId();\n    if(!docId || useIsFrozen()) {\n      return false;\n    }\n\n    return await this.managers.appSavedMusicManager.isInProfile(docId) === inProfile;\n  }\n\n  public static canDownload(\n    message: MyMessage | MyMessage[],\n    withTarget?: HTMLElement,\n    noForwards?: boolean,\n    container?: HTMLElement\n  ): boolean {\n    if(Array.isArray(message)) {\n      return message.some((message) => ChatContextMenu.canDownload(message, withTarget, noForwards, container));\n    }\n\n    if(!canSaveMessageMedia(message, noForwards)) {\n      return false;\n    }\n\n    const photo = ((message as Message.message).media as MessageMedia.messageMediaPhoto)?.photo as Photo.photo;\n    const document = ((message as Message.message).media as MessageMedia.messageMediaDocument)?.document as Document.document;\n    const isPhoto: boolean = !!photo;\n    let isGoodType = false\n\n    if(isPhoto) {\n      isGoodType = true;\n    } else {\n      if(!document) {\n        return false;\n      }\n\n      // isGoodType = doc.type && (['gif', 'video', 'audio', 'voice', 'sticker'] as MyDocument['type'][]).includes(doc.type)\n      isGoodType = true;\n    }\n\n    let hasTarget = !withTarget || !!IS_TOUCH_SUPPORTED;\n\n    if(isGoodType && withTarget) {\n      hasTarget ||= !!(findUpClassName(withTarget, 'document') ||\n        findUpClassName(withTarget, 'audio') ||\n        findUpClassName(withTarget, 'media-sticker-wrapper') ||\n        findUpClassName(withTarget, 'media-photo') ||\n        findUpClassName(withTarget, 'media-video'));\n    }\n\n    if(container && (message as Message.message).restriction_reason && isSensitive((message as Message.message).restriction_reason)) {\n      const item = container.querySelector(\n        `[data-peer-id=\"${message.peerId}\"][data-mid=\"${message.mid}\"]`\n      ) || container.querySelector(`[data-mid=\"${message.mid}\"]:not([data-peer-id])`);\n      return isGoodType && hasTarget && !!item && !hasSensitiveSpoiler(item as HTMLElement);\n    }\n\n    return isGoodType && hasTarget;\n  }\n\n  public static canCopyMedia(\n    message: MyMessage,\n    withTarget?: HTMLElement,\n    noForwards?: boolean,\n    container?: HTMLElement\n  ) {\n    return ChatContextMenu.canDownload(message, withTarget, noForwards, container) &&\n      canCopyMediaToClipboard(getMediaFromMessage(message, true));\n  }\n\n  private getMessageWithText() {\n    return (this.groupedMessages && getGroupedText(this.groupedMessages)) || this.message;\n  }\n\n  private getUniqueCustomEmojisFromMessage() {\n    return getUniqueCustomEmojisFromMessage(this.getMessageWithText());\n  }\n\n  private async init() {\n    this.cleanup();\n    this.setButtons();\n\n    const filteredButtons = await this.filterButtons(this.buttons);\n    if(!filteredButtons.length) {\n      return;\n    }\n\n    const element = this.element = await ButtonMenu({\n      buttons: filteredButtons,\n      listenerSetter: this.listenerSetter\n    });\n    element.id = 'bubble-contextmenu';\n    element.classList.add('contextmenu');\n\n    const viewsButton = filteredButtons.find((button) => button.localName === 'views');\n    if(viewsButton && this.peerId.isUser()) {\n      viewsButton.element.prepend(Icon('checks', 'btn-menu-item-icon'));\n      const loader = document.createElement('div');\n      loader.classList.add('btn-menu-item-loader', 'shimmer');\n      viewsButton.textElement.append(loader);\n      // viewsButton.element.classList.add('is-smaller');\n\n      viewsButton.element.after(document.createElement('hr'));\n      const delimiter = viewsButton.element.nextElementSibling;\n\n      const middleware = this.middleware.get();\n      this.managers.appMessagesManager.getOutboxReadDate(this.message.peerId, this.message.mid).then((outboxReadDate) => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.canViewReadTime = true;\n        // loader.replaceWith(i18n('PmRead'), ' ', formatFullSentTime(outboxReadDate.date, false, false));\n        // loader.replaceWith(i18n('Chat.ContextMenu.Read'), ' ', formatFullSentTime(outboxReadDate.date, false, false));\n        loader.replaceWith(formatFullSentTime(outboxReadDate.date, true, false));\n      }, (err) => {\n        if(!middleware()) {\n          return;\n        }\n\n        if((err as ApiError).type !== 'YOUR_PRIVACY_RESTRICTED') {\n          delimiter.remove();\n          viewsButton.element.remove();\n          return;\n        }\n\n        this.canViewReadTime = false;\n        const when = i18n('PmReadShowWhen');\n        when.classList.add('show-when');\n        loader.replaceWith(i18n('Chat.ContextMenu.Read'), ' ', when);\n      });\n    } else if(viewsButton) {\n      const reactions = (this.message as Message.message).reactions;\n      const recentReactions = reactions?.recent_reactions;\n      const isViewingReactions = !!recentReactions?.length;\n      const participantsCount = await this.managers.appMessagesManager.canViewMessageReadParticipants(this.message) ?\n        ((await this.managers.appPeersManager.getPeer(this.peerId)) as MTChat.chat).participants_count :\n        undefined;\n      const reactedLength = reactions ? reactions.results.reduce((acc, r) => acc + r.count, 0) : undefined;\n\n      viewsButton.element.prepend(Icon(isViewingReactions ? 'reactions' : 'checks', 'btn-menu-item-icon'));\n      const i18nElem = new I18n.IntlElement({\n        key: isViewingReactions ? (\n          participantsCount === undefined ? 'Chat.Context.ReactedFast' : 'Chat.Context.Reacted'\n        ) : 'NobodyViewed',\n        args: isViewingReactions ? (\n          participantsCount === undefined ? [reactedLength] : [participantsCount, participantsCount]\n        ) : undefined,\n        element: viewsButton.textElement\n      });\n\n      let fakeText: HTMLElement;\n      if(isViewingReactions) {\n        if(participantsCount === undefined) {\n          fakeText = i18n('Chat.Context.ReactedFast', [reactedLength]);\n        } else {\n          fakeText = i18n(\n            recentReactions.length === participantsCount ? 'Chat.Context.ReactedFast' : 'Chat.Context.Reacted',\n            [recentReactions.length, participantsCount]\n          );\n        }\n      } else {\n        fakeText = i18n('Loading');\n      }\n\n      fakeText.classList.add('btn-menu-item-text-fake');\n      viewsButton.element.append(fakeText);\n\n      const AVATAR_SIZE = 22;\n      const MAX_AVATARS = 3;\n      const PADDING_PER_AVATAR = 1.125;\n      i18nElem.element.style.visibility = 'hidden';\n      i18nElem.element.style.paddingRight = isViewingReactions ? PADDING_PER_AVATAR * Math.min(MAX_AVATARS, recentReactions.length) + 'rem' : '1rem';\n      const middleware = this.middleware.get();\n      this.managers.appMessagesManager.getMessageReactionsListAndReadParticipants(this.message as Message.message).then((result) => {\n        if(!middleware()) {\n          return;\n        }\n\n        fakeText?.remove();\n\n        const reactions = result.combined;\n        const reactedLength = participantsCount === undefined ?\n          result.reactionsCount :\n          (\n            isViewingReactions ?\n              reactions.filter((reaction) => reaction.reaction).length :\n              reactions.length\n          );\n\n        let fakeElem: HTMLElement;\n        if(reactions.length === 1) {\n          fakeElem = new PeerTitle({\n            peerId: reactions[0].peerId,\n            onlyFirstName: true,\n            dialog: false\n          }).element;\n\n          if(!isViewingReactions || result.readParticipantDates.length <= 1) {\n            this.viewerPeerId = reactions[0].peerId;\n          }\n        } else if(isViewingReactions) {\n          const isFull = reactedLength === reactions.length || participantsCount === undefined;\n          fakeElem = i18n(\n            isFull ? 'Chat.Context.ReactedFast' : 'Chat.Context.Reacted',\n            isFull ? [reactedLength] : [reactedLength, reactions.length]\n          );\n        } else {\n          if(!reactions.length) {\n            i18nElem.element.style.visibility = '';\n          } else {\n            fakeElem = i18n('MessageSeen', [reactions.length]);\n          }\n        }\n\n        if(fakeElem) {\n          fakeElem.style.paddingRight = PADDING_PER_AVATAR * Math.min(MAX_AVATARS, reactedLength) + 'rem';\n          fakeElem.classList.add('btn-menu-item-text-fake');\n          viewsButton.element.append(fakeElem);\n        }\n\n        if(reactions.length) {\n          const avatars = new StackedAvatars({avatarSize: AVATAR_SIZE, middleware});\n          avatars.render(recentReactions ? recentReactions.map((r) => getPeerId(r.peer_id)) : reactions.map((reaction) => reaction.peerId));\n          viewsButton.element.append(avatars.container);\n\n          // if(reactions.length > 1) {\n          // if(isViewingReactions) {\n          this.canOpenReactedList = true;\n          // }\n        }\n      });\n    }\n\n    let menuPadding: MenuPositionPadding;\n    let reactionsMenu: ChatReactionsMenu;\n    let reactionsMenuPosition: 'horizontal' | 'vertical';\n    if(\n      this.chat.type !== ChatType.Logs &&\n      this.message &&\n      (this.message._ === 'message' || (this.message._ === 'messageService' && this.message.pFlags.reactions_are_possible)) &&\n      !this.chat.selection.isSelecting &&\n      !this.message.pFlags.is_outgoing &&\n      !(this.message._ === 'message' && this.message.pFlags.is_scheduled) &&\n      !this.message.pFlags.local &&\n      !isEphemeralMessage(this.message) &&\n      !this.reactionElement\n    ) {\n      const reactions = this.message.reactions;\n      const tags = this.message.peerId === rootScope.myId && (!reactions || reactions.pFlags.reactions_as_tags);\n      const reactionsMessage = this.message._ === 'message' ?\n        await this.managers.appMessagesManager.getGroupsFirstMessage(this.message) :\n        this.message;\n      reactionsMenuPosition = (IS_APPLE || IS_TOUCH_SUPPORTED) || true/*  && false */ ? 'horizontal' : 'vertical';\n      reactionsMenu = this.reactionsMenu = new ChatReactionsMenu({\n        managers: this.managers,\n        type: reactionsMenuPosition,\n        middleware: this.middleware.get(),\n        onFinish: async(reaction) => {\n          contextMenuController.close();\n          reaction = await reaction;\n          if(!reaction) {\n            return;\n          }\n\n          if(reaction._ === 'reactionPaid') {\n            PopupElement.createPopup(PopupStarReaction, reactionsMessage.peerId, reactionsMessage.mid, this.chat);\n            return;\n          }\n\n          if(!rootScope.premium && tags) {\n            PopupPremium.show({feature: 'saved_tags'});\n            return;\n          }\n\n          this.chat.sendReaction({message: reactionsMessage, reaction});\n        },\n        getOpenPosition: (hasMenu) => ChatContextMenu.getReactionsOpenPosition(reactionsMenu, hasMenu),\n        isTags: tags\n      });\n      await reactionsMenu.init(reactionsMessage);\n      // element.prepend(reactionsMenu.widthContainer);\n\n      menuPadding = ChatContextMenu.getReactionsMenuPadding(reactionsMenuPosition);\n    }\n\n    const emojisButton = filteredButtons.find((button) => button.localName === 'emojis');\n    if(emojisButton) {\n      emojisButton.element.classList.add('is-multiline');\n      emojisButton.element.parentElement.insertBefore(document.createElement('hr'), emojisButton.element);\n\n      const setPadding = () => {\n        menuPadding ??= {};\n        menuPadding.bottom = 24;\n      };\n\n      const docIds = this.reactionElement ?\n        [(this.reactionElement.reactionCount.reaction as Reaction.reactionCustomEmoji).document_id] :\n        this.getUniqueCustomEmojisFromMessage();\n      const inputsPromise = this.emojiInputsPromise = deferredPromise();\n\n      await this.managers.appEmojiManager.getCachedCustomEmojiDocuments(docIds).then(async(docs) => {\n        const p = async(docs: Document.document[]) => {\n          const s: Map<StickerSet['id'], InputStickerSet.inputStickerSetID> = new Map();\n          docs.forEach((doc) => {\n            if(!doc || s.has(doc.stickerSetInput.id)) {\n              return;\n            }\n\n            s.set(doc.stickerSetInput.id, doc.stickerSetInput);\n          });\n\n          const inputs = [...s.values()];\n          inputsPromise.resolve(inputs);\n          if(s.size === 1) {\n            const result = await this.managers.acknowledged.appStickersManager.getStickerSet(inputs[0]);\n            const promise = result.result.then((set) => {\n              const el = i18n(\n                this.isTag ? 'Reaction.Tag.From' : (this.reactionElement ? 'MessageContainsReactionPack' : 'MessageContainsEmojiPack'),\n                [wrapEmojiText(set.set.title)]\n              );\n              replaceContent(emojisButton.textElement, el);\n            });\n\n            return result.cached ? promise : (setPadding(), undefined);\n          }\n\n          replaceContent(emojisButton.textElement, i18n('MessageContainsEmojiPacks', [s.size]));\n        };\n\n        if(docs.some((doc) => !doc)) {\n          setPadding();\n          this.managers.appEmojiManager.getCustomEmojiDocuments(docIds).then(p);\n        } else {\n          return p(docs);\n        }\n      });\n      // emojisButton.element.append(i18n('Loading'));\n    }\n\n    // Mount into the active window's body so a context menu opened while the client is popped out\n    // lands in the Document PiP window (positionMenu + contextMenuController then follow its realm).\n    getOverlayRoot().append(element);\n    this.buttons.forEach((button) => button.onOpen?.());\n\n    return {\n      element,\n      cleanup: () => {\n        this.cleanup();\n        reactionsMenu && reactionsMenu.cleanup();\n      },\n      destroy: () => {\n        element.remove();\n        this.buttons.forEach((button) => button.onClose?.());\n        reactionsMenu && reactionsMenu.widthContainer.remove();\n      },\n      menuPadding,\n      reactionsMenu,\n      reactionsMenuPosition\n    };\n  }\n\n  private async getUrlToMessage() {\n    if(!this.message || this.messagePeerId.isUser()) {\n      return;\n    }\n\n    let threadMessage: Message.message;\n    const {peerId, mid} = this.message;\n    const threadId = this.chat.threadId;\n    if(this.chat.type === ChatType.Discussion) {\n      threadMessage = (await this.managers.appMessagesManager.getMessageByPeer(peerId, threadId)) as Message.message;\n    }\n\n    const isDiscussionFromChannel = !!(threadMessage?.fwd_from?.channel_post && threadMessage.fwd_from.saved_from_msg_id);\n    const username = await this.managers.appPeersManager.getPeerUsername(isDiscussionFromChannel ? threadMessage.fromId : peerId);\n    const msgId = getServerMessageId(mid);\n    let url = 'https://t.me/';\n    if(username) {\n      url += username;\n      if(isDiscussionFromChannel) url += `/${getServerMessageId(threadMessage.fwd_from.channel_post)}?comment=${msgId}`;\n      else if(threadId) url += `/${getServerMessageId(threadId)}/${msgId}`;\n      else url += '/' + msgId;\n    } else {\n      url += 'c/' + peerId.toChatId();\n      if(threadMessage) url += `/${msgId}?thread=${getServerMessageId(threadMessage.mid)}`;\n      else if(threadId) url += `/${getServerMessageId(threadId)}/${msgId}`;\n      else url += '/' + msgId;\n    }\n\n    return {url, isPrivate: !username};\n  }\n\n  private async getSelectedMessagesText() {\n    if(this.avatarPeerId || !isSelectionEmpty()) {\n      return;\n    }\n\n    let rawMessages: (Message.message | SponsoredMessage.sponsoredMessage)[];\n    if(this.isSponsored) {\n      rawMessages = [this.sponsoredMessage];\n    } else if(!this.chat.selection.isSelecting) {\n      const message = this.getMessageWithText();\n      if(!message) {\n        return;\n      }\n\n      rawMessages = [message as Message.message];\n    } else {\n      // read selected messages from their own (scheduled vs history) storage; re-fetching by a\n      // bare id resolves against history/global and can pull a same-id message from another peer\n      // (e.g. copying in Scheduled would grab a message from a different chat)\n      rawMessages = await this.chat.selection.getSelectedMessages() as Message.message[];\n    }\n\n    // sort by send time so the copied text follows the chronological order, not the selection order (#357)\n    const messages = (rawMessages.filter((message) => message?.message) as Message.message[])\n    .sort((a, b) => a.date - b.date || a.mid - b.mid);\n    const meta = messages.length > 1 ? await Promise.all(messages.map(async(message) => {\n      const peerTitle = await getPeerTitle({\n        peerId: message.fromId,\n        plainText: true\n      });\n\n      const date = getFullDate(new Date(message.date * 1000), {\n        noSeconds: true,\n        monthAsNumber: true,\n        timeJoiner: ' ',\n        leadingZero: true\n      });\n\n      return peerTitle + ', [' + date + ']';\n    })) : [];\n\n    return prepareTextWithEntitiesForCopying(messages.map((message) => {\n      return {\n        text: message.message,\n        entities: (message as Message.message).totalEntities || message.entities\n      };\n    }), meta);\n  }\n\n  private onSendScheduledClick = async() => {\n    if(this.chat.selection.isSelecting) {\n      simulateClickEvent(this.chat.selection.selectionSendNowBtn);\n    } else {\n      PopupElement.createPopup(PopupSendNow, this.peerId, await this.chat.getMidsByMid(this.messagePeerId, this.mid));\n    }\n  };\n\n  private onReplyClick = async() => {\n    const {peerId, message} = this;\n    const replyTo = this.chat.input.getChatInputReplyToFromMessage(message);\n\n    if(!await this.chat.canSend()) {\n      replyTo.replyToPeerId = peerId;\n      this.chat.input.createReplyPicker(replyTo);\n      return;\n    }\n\n    this.chat.input.initMessageReply(replyTo);\n  };\n\n  private onReplyToPollOptionClick = async(pollAnswer: PollAnswer.pollAnswer) => {\n    const {peerId, message} = this;\n    const replyTo = this.chat.input.getChatInputReplyToFromMessage(message);\n    replyTo.replyToPollOption = pollAnswer.option;\n\n    if(!await this.chat.canSend()) {\n      replyTo.replyToPeerId = peerId;\n      this.chat.input.createReplyPicker(replyTo);\n      return;\n    }\n\n    this.chat.input.initMessageReply(replyTo);\n  };\n\n  private onFaveStickerClick = (unfave?: boolean) => {\n    const document = ((this.message as Message.message).media as MessageMedia.messageMediaDocument).document as MyDocument;\n    const docId = document.id;\n    if(document.type === 'gif') {\n      this.managers.appGifsManager.saveGif(docId, unfave);\n    } else {\n      this.managers.appStickersManager.faveSticker(docId, unfave);\n    }\n  };\n\n  private onEditClick = () => {\n    const message = this.getMessageWithText();\n    if(message._ === 'message' && message.media?._ === 'messageMediaToDo') {\n      showChecklistPopup({\n        chat: this.chat,\n        editMessage: message as any\n      });\n      return;\n    }\n\n    if(message?._ === 'message' && message.suggested_post) {\n      this.chat.input.initSuggestPostChange(message.mid);\n      return;\n    }\n\n    this.chat.input.initMessageEditing(this.isTargetAGroupedItem ? this.mid : message.mid);\n  };\n\n  private onEditFactCheckClick = async() => {\n    const {mainMessage: message} = this;\n    const factCheck = (message as Message.message).factcheck;\n    const buttonTextElement = new I18n.IntlElement({key: 'Done'});\n    const buttonOptions: PopupConfirmationOptions['button'] = {\n      text: buttonTextElement.element\n    };\n\n    const inputField = new InputField({\n      placeholder: 'FactCheckPlaceholder',\n      withLinebreaks: true,\n      onRawInput: factCheck ? (value) => {\n        buttonTextElement.compareAndUpdate({key: value ? 'Done' : 'Remove'});\n        if(!buttonOptions.element) {\n          return;\n        }\n\n        buttonOptions.element.classList.toggle('primary', !!value);\n        buttonOptions.element.classList.toggle('danger', !value);\n      } : undefined,\n      canHaveFormatting: ['bold', 'italic', 'link']\n    });\n\n    if(factCheck) {\n      inputField.setValueSilently(wrapDraftText(factCheck.text.text, {entities: factCheck.text.entities}));\n    }\n\n    try {\n      await confirmationPopup({\n        titleLangKey: 'FactCheckDialog',\n        inputField,\n        button: buttonOptions,\n        confirmShortcutIsSendShortcut: true\n      });\n    } catch(err) {\n      return;\n    }\n\n    const {value: text, entities} = getRichValueWithCaret(inputField.input, true, false);\n    const newTextWithEntities: TextWithEntities = text ? {_: 'textWithEntities', text, entities} : undefined;\n    if(factCheck && deepEqual(factCheck.text, newTextWithEntities)) {\n      return;\n    }\n\n    this.managers.appMessagesManager.updateFactCheck(\n      message.peerId,\n      message.mid,\n      newTextWithEntities\n    ).then(() => {\n      toastNew({\n        langPackKey: text ? 'FactCheckEdited' : 'FactCheckDeleted'\n      });\n    });\n  };\n\n  private onCopyClick = async() => {\n    if(isSelectionEmpty()) {\n      const {text, html} = this.selectedMessagesText;\n      copyTextToClipboard(text, html);\n    } else {\n      getAppWindow().document.execCommand('copy');\n      // cancelSelection();\n    }\n  };\n\n  private onCopyMediaClick = () => {\n    copyMessageMediaWithFeedback({\n      message: this.message,\n      button: this.copyMediaButton\n    });\n  };\n\n  private onCopyAnchorLinkClick = () => {\n    let href = (this.target as HTMLAnchorElement).href;\n    href = href.replace(/^mailto:/, '');\n    copyTextToClipboard(href);\n  };\n\n  private onCopyLinkClick = () => {\n    const {url, isPrivate} = this.linkToMessage;\n    const key: LangPackKey = isPrivate ? 'LinkCopiedPrivateInfo' : 'LinkCopied';\n    toastNew({langPackKey: key});\n    copyTextToClipboard(url);\n  };\n\n  private onPinClick = () => {\n    PopupElement.createPopup(PopupPinMessage, this.messagePeerId, this.mid);\n  };\n\n  private onUnpinClick = () => {\n    PopupElement.createPopup(PopupPinMessage, this.messagePeerId, this.mid, true);\n  };\n\n  private onRetractVote = () => {\n    this.managers.appPollsManager.sendVote(this.message as Message.message, []);\n  };\n\n  private onStopPoll = () => {\n    this.managers.appPollsManager.stopPoll(this.message as Message.message);\n  };\n\n  private onAddTaskClick = async() => {\n    if(!rootScope.premium) {\n      PopupPremium.show();\n      return;\n    }\n\n    showChecklistPopup({\n      chat: this.chat,\n      editMessage: this.message as any,\n      appending: true\n    });\n  };\n\n  private onForwardClick = async() => {\n    if(this.chat.selection.isSelecting) {\n      simulateClickEvent(this.chat.selection.selectionForwardBtn);\n    } else {\n      const peerId = this.messagePeerId;\n      const mids = this.isTargetAGroupedItem ? [this.mid] : await this.chat.getMidsByMid(peerId, this.mid);\n      showForwardPopup({\n        [peerId]: mids\n      });\n    }\n  };\n\n  private onSelectClick = () => {\n    this.chat.selection.toggleByElement(getSelectionElementFromTarget(this.target));\n  };\n\n  private onClearSelectionClick = () => {\n    this.chat.selection.cancelSelection();\n  };\n\n  private onDeleteClick = async() => {\n    if(this.chat.selection.isSelecting) {\n      simulateClickEvent(this.chat.selection.selectionDeleteBtn);\n      return;\n    }\n\n    const {message} = this;\n    const {peerId, mid} = message;\n    // if(TEST_BUBBLES_DELETION) {\n    //   return this.chat.bubbles.deleteMessagesByIds(await this.chat.getMidsByMid(mid), true);\n    // }\n\n    PopupElement.createPopup(\n      PopupDeleteMessages,\n      peerId,\n      this.isTargetAGroupedItem ? [mid] : await this.chat.getMidsByMid(peerId, mid),\n      this.chat.type\n    );\n  };\n\n  private getQuotedText() {\n    return getRichSelection(this.target);\n  }\n\n  private onQuoteClick = async() => {\n    const messageWithText = this.getMessageWithText();\n    const {peerId} = messageWithText;\n    let {text: value, entities = [], offset: startIndex} = this.getQuotedText();\n\n    const appConfig = await this.managers.apiManager.getAppConfig();\n    let maxLength = appConfig.quote_length_max ?? 1024;\n    const whitespaceLength = value.length - value.trimEnd().length;\n    if(whitespaceLength) { // * fix whitespace\n      maxLength = Math.min(value.length - whitespaceLength, maxLength);\n    }\n    if(value.length > maxLength) { // * fix overflow\n      value = value.slice(0, maxLength);\n      entities = entities // * fix length for entities\n      .filter((entity) => entity.offset < maxLength)\n      .map((entity) => {\n        if((entity.offset + entity.length) > maxLength) {\n          entity.length = maxLength - entity.offset;\n        }\n\n        return entity;\n      });\n    }\n\n    const quote: ChatInputReplyTo['replyToQuote'] = {\n      text: value,\n      entities: entities.length ? entities : undefined,\n      offset: startIndex\n    };\n\n    const replyTo = this.chat.input.getChatInputReplyToFromMessage(messageWithText, quote);\n\n    if(!await this.chat.canSend()) {\n      replyTo.replyToPeerId = peerId;\n      this.chat.input.createReplyPicker(replyTo);\n      return;\n    }\n\n    this.chat.input.initMessageReply(replyTo);\n  };\n\n  private onStatisticsClick = () => {\n    this.chat.topbar.appSidebarRight.createTab(AppStatisticsTab).open(this.messagePeerId.toChatId(), this.mid);\n    this.chat.topbar.appSidebarRight.toggleSidebar(true);\n  };\n\n  private canViewMessageStatistics = async() => {\n    return await this.managers.appPeersManager.isBroadcast(this.messagePeerId) &&\n      await this.managers.appProfileManager.canViewStatistics(this.messagePeerId) &&\n      !this.message.pFlags.is_outgoing;\n  };\n\n  private getPollVoteRestrictionsText = async() => {\n    const media = this.message?._ === 'message' && this.message.media;\n    if(!media || media._ !== 'messageMediaPoll' || media.poll.pFlags.closed) return;\n\n    const poll = media.poll;\n    const result = document.createElement('span');\n    const appendRestriction = (restriction: ReturnType<typeof getPollVoteRestrictionText>) => {\n      if(result.childNodes.length) result.append('\\n');\n      result.append(i18n(restriction.langPackKey, restriction.langPackArguments));\n    };\n\n    if(poll.pFlags.subscribers_only) {\n      const sourcePeerId = getPollVoteRestrictionPeerId(this.message);\n      const isBroadcast = sourcePeerId.isAnyChat() && await this.managers.appPeersManager.isBroadcast(sourcePeerId);\n      const peerName = isBroadcast ? await getPeerTitle({\n        peerId: sourcePeerId,\n        plainText: true,\n        managers: this.managers,\n        useManagers: true\n      }) : undefined;\n\n      appendRestriction(getPollVoteRestrictionText(\n        poll,\n        peerName ? 'subscribersOnly' : 'subscribersJoinedTooRecently',\n        peerName\n      ));\n    }\n\n    if(poll.countries_iso2?.length) {\n      appendRestriction(getPollVoteRestrictionText(poll, 'countries'));\n    }\n\n    return result.childNodes.length ? result : undefined;\n  };\n\n  private canViewPollStatistics = () => {\n    return canViewPollStatisticsForMessage(\n      this.message,\n      ![ChatType.Logs, ChatType.Static, ChatType.Scheduled].includes(this.chat.type)\n    );\n  };\n\n  private onPollStatisticsClick = () => {\n    this.chat.topbar.appSidebarRight.createTab(AppStatisticsTab).open(this.messagePeerId, this.mid, undefined, 'poll');\n    this.chat.topbar.appSidebarRight.toggleSidebar(true);\n  };\n\n  private async handleRepay() {\n    if(!('repayRequest' in this.message) || !this.message.repayRequest) return;\n\n    const preparedPaymentResult = await this.chat.input.paidMessageInterceptor.prepareStarsForPayment(\n      this.message.repayRequest.messageCount\n    );\n\n    if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n    this.managers.appMessagesManager.confirmRepayRequest(this.message.repayRequest.id, preparedPaymentResult);\n  }\n\n  public static onDownloadClick(messages: MyMessage | MyMessage[], noForwards?: boolean, container?: HTMLElement): DownloadBlob | DownloadBlob[] {\n    if(Array.isArray(messages)) {\n      return messages.map((message) => {\n        return this.onDownloadClick(message, noForwards, container) as any;\n      });\n    }\n\n    if(!this.canDownload(messages, undefined, noForwards, container)) {\n      return;\n    }\n\n    return appDownloadManager.downloadToDisc({media: getMediaFromMessage(messages, true)});\n  };\n\n  public static getReactionsMenuPadding(position: 'vertical' | 'horizontal') {\n    const size = 36;\n    const margin = 8;\n    const totalSize = size + margin;\n    let paddingLeft = 56;\n    const paddingRight = 40;\n    if(IS_TOUCH_SUPPORTED) {\n      paddingLeft += 32;\n    }\n\n    let menuPadding: MenuPositionPadding;\n    if(position === 'vertical') {\n      menuPadding = {\n        top: paddingLeft,\n        // bottom: 36, // positionMenu will detect it itself somehow\n        left: totalSize\n      };\n    } else {\n      menuPadding = {\n        top: totalSize,\n        right: paddingRight,\n        left: paddingLeft\n      };\n    }\n\n    return menuPadding;\n  }\n\n  public static getReactionsOpenPosition(reactionsMenu: ChatReactionsMenu, hasMenu: boolean) {\n    const rect = reactionsMenu.container.getBoundingClientRect();\n    const newRect = cloneDOMRect(rect);\n    newRect.left -= 21 / 2;\n    newRect.top -= 121 / 2;\n    if(!hasMenu) newRect.top += 37;\n    return newRect;\n  }\n\n  public static appendReactionsMenu({element, reactionsMenu, reactionsMenuPosition}: {\n    element: HTMLElement,\n    reactionsMenu: ChatReactionsMenu,\n    reactionsMenuPosition: 'horizontal' | 'vertical'\n  }) {\n    let isReactionsMenuVisible = false;\n    if(reactionsMenu) {\n      const className = 'is-visible';\n      isReactionsMenuVisible = reactionsMenu.container.classList.contains(className);\n      if(isReactionsMenuVisible) reactionsMenu.container.classList.remove(className);\n\n      if(reactionsMenuPosition === 'horizontal') {\n        const offsetSize = element[/* reactionsMenuPosition === 'vertical' ? 'offsetHeight' :  */'offsetWidth'];\n        // if(reactionsMenu.scrollable.container.scrollWidth > offsetWidth) {\n        const INNER_CONTAINER_PADDING = 8;\n        const visibleLength = (offsetSize - INNER_CONTAINER_PADDING) / REACTION_CONTAINER_SIZE;\n        const nextVisiblePart = visibleLength % 1;\n        const MIN_NEXT_VISIBLE_PART = 0.65;\n        if(nextVisiblePart < MIN_NEXT_VISIBLE_PART) {\n          const minSize = (offsetSize + (MIN_NEXT_VISIBLE_PART - nextVisiblePart) * REACTION_CONTAINER_SIZE) | 0;\n          element.style[/* reactionsMenuPosition === 'vertical' ? 'minHeight' :  */'minWidth'] = minSize + 'px';\n        }\n        // }\n      }\n    }\n\n    if(reactionsMenu) {\n      const container = reactionsMenu.widthContainer;\n      if(!IS_MOBILE) {\n        const i = document.createElement('div');\n        i.classList.add('btn-menu-items', 'btn-menu-transition');\n        i.append(...Array.from(element.childNodes));\n        element.classList.add('has-items-wrapper');\n        element.append(container, i);\n      } else {\n        element.prepend(container);\n      }\n\n      container.style.setProperty('--height', container.offsetHeight + 'px');\n    }\n\n    return {\n      onAfterInit: () => {\n        if(isReactionsMenuVisible) {\n          reactionsMenu.container.classList.add('is-visible');\n        }\n      },\n      onClose: () => {\n        if(reactionsMenu) {\n          reactionsMenu.container.classList.remove('is-visible');\n        }\n      }\n    };\n  }\n\n  private async getMessageLanguage() {\n    if(this.chat.appConfig.freeze_since_date || this.selectedMessages || !this.message) return;\n\n    if(this.message._ === 'message' && this.message.media?._ === 'messageMediaPoll') {\n      const text = (await this.getPollTextWithEntities(this.message))?.text;\n      if(!text) return;\n\n      return detectLanguageForTranslation(text);\n    }\n\n    return detectLanguageForTranslation((this.message as Message.message).message);\n  }\n\n  private async getPollTextWithEntities(message: MyMessage) {\n    if(message?._ !== 'message' || message.media?._ !== 'messageMediaPoll') return;\n\n    const listDotText = '🔘 ';\n    const listDotEntities = parseEntities(listDotText);\n    const listDot: TextWithEntities = {_: 'textWithEntities', text: listDotText, entities: listDotEntities};\n    const lineBreakText = '\\n';\n    const lineBreakEntities = parseEntities(lineBreakText);\n    const lineBreak: TextWithEntities = {_: 'textWithEntities', text: lineBreakText, entities: lineBreakEntities};\n\n    // Note: poll_update doesn't modify the message, so we're getting the poll and results separately\n    const {poll, results} = await this.managers.appPollsManager.getPoll(message.media.poll.id);\n\n    if(!poll) return;\n\n    let answers = poll.answers.filter(answer => answer._ === 'pollAnswer');\n\n    if(shouldShufflePollOptions(poll)) {\n      answers = shufflePollOptions({\n        options: answers,\n        userId: rootScope.myId,\n        pollId: poll.id\n      });\n    }\n\n    const parts: TextWithEntities[] = [\n      {\n        _: 'textWithEntities',\n        text: message.message,\n        entities: message.entities\n      },\n      lineBreak,\n      poll.question,\n      lineBreak,\n      ...answers.filter(answer => answer._ === 'pollAnswer').map(answer => concatTextsWithEntities([\n        listDot,\n        answer.text,\n        lineBreak\n      ])),\n      ...(results?.solution ? [\n        {\n          _: 'textWithEntities',\n          text: results.solution,\n          entities: results.solution_entities ?? []\n        } as TextWithEntities\n      ] : [])\n    ];\n\n    return concatTextsWithEntities(parts);\n  }\n}\n","import contextMenuController from '@helpers/contextMenuController';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport {Reaction} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport {ButtonMenuItemOptionsVerifiable, ButtonMenuSync} from '@components/buttonMenu';\nimport PopupPremium from '@components/popups/premium';\nimport ChatContextMenu from '@components/chat/contextMenu';\nimport {ChatReactionsMenu} from '@components/chat/reactionsMenu';\n\nexport default class SendMenu {\n  private type: 'schedule' | 'reminder';\n  private isPaid: boolean;\n  private middlewareHelper: MiddlewareHelper;\n\n  constructor(private options: {\n    onSilentClick: () => void,\n    onScheduleClick: () => void,\n    onSendWhenOnlineClick?: () => void,\n    onRef: (element: HTMLElement) => void,\n    middleware: Middleware,\n    openSide: string,\n    onContextElement: HTMLElement,\n    onOpen?: () => boolean,\n    onToggle?: (open: boolean) => void,\n    canSendWhenOnline?: () => boolean | Promise<boolean>,\n    withEffects?: () => boolean,\n    effect?: () => DocId,\n    onEffect?: (effect: DocId) => void\n  }) {\n    this.middlewareHelper = options.middleware.create();\n    this.createMenu();\n  }\n\n  public setPeerParams(params: {peerId: PeerId, isPaid: boolean}) {\n    this.type = params.peerId === rootScope.myId ? 'reminder' : 'schedule';\n    this.isPaid = params.isPaid;\n  }\n\n  private createButtons(): ButtonMenuItemOptionsVerifiable[] {\n    return [{\n      icon: 'mute',\n      text: 'Chat.Send.WithoutSound',\n      onClick: this.options.onSilentClick,\n      verify: () => this.type === 'schedule'\n    }, {\n      icon: 'schedule',\n      text: 'Chat.Send.ScheduledMessage',\n      onClick: this.options.onScheduleClick,\n      verify: () => this.type === 'schedule' && !this.isPaid\n    }, {\n      icon: 'schedule',\n      text: 'Chat.Send.SetReminder',\n      onClick: this.options.onScheduleClick,\n      verify: () => this.type === 'reminder'\n    }, {\n      icon: 'online',\n      text: 'Schedule.SendWhenOnline',\n      onClick: this.options.onSendWhenOnlineClick,\n      verify: async() => this.type === 'schedule' && (await this.options.canSendWhenOnline?.()) && !this.isPaid\n    }, {\n      icon: 'crossround',\n      text: 'Effect.Remove',\n      danger: true,\n      onClick: () => this.options.onEffect(undefined),\n      verify: () => !!this.options.effect?.()\n    }];\n  }\n\n  private createMenu() {\n    this.middlewareHelper.clean();\n    const middleware = this.middlewareHelper.get();\n\n    const listenerSetter = new ListenerSetter();\n    middleware.onClean(() => {\n      listenerSetter.removeAll();\n    });\n\n    this.createButtons();\n    const buttons = this.createButtons();\n    const element = ButtonMenuSync({buttons, listenerSetter});\n    element.classList.add('menu-send', this.options.openSide);\n    this.options.onRef(element);\n\n    attachContextMenuListener({\n      element: this.options.onContextElement,\n      callback: async(e) => {\n        if(this.options.onOpen && !this.options.onOpen()) {\n          return;\n        }\n\n        cancelEvent(e);\n        await Promise.all(buttons.map(async(button) => {\n          const result = await button.verify();\n          button.element.classList.toggle('hide', !result);\n        }));\n\n        const middlewareHelper = getMiddleware();\n        const middleware = middlewareHelper.get();\n\n        const reactionsMenuPosition = 'horizontal';\n        let reactionsMenu: ChatReactionsMenu;\n        if(this.options.withEffects?.()) {\n          reactionsMenu = new ChatReactionsMenu({\n            managers: rootScope.managers,\n            type: reactionsMenuPosition,\n            middleware,\n            onFinish: async(reaction) => {\n              contextMenuController.close();\n              reaction = await reaction;\n              if(!reaction) {\n                return;\n              }\n\n              const stickerDocId = (reaction as Reaction.reactionCustomEmoji).document_id;\n              if(!rootScope.premium && !reactionsMenu.freeCustomEmoji.has(stickerDocId)) {\n                PopupPremium.show({feature: 'premium_stickers'});\n                return;\n              }\n\n              const availableEffects = await rootScope.managers.appReactionsManager.getAvailableEffects();\n              const availableEffect = availableEffects.find((effect) => effect.effect_sticker_id === stickerDocId);\n              this.options.onEffect(availableEffect.id);\n            },\n            getOpenPosition: (hasMenu) => ChatContextMenu.getReactionsOpenPosition(reactionsMenu, hasMenu),\n            isEffects: true\n          });\n\n          await reactionsMenu.init();\n\n          // const menuPadding = ChatContextMenu.getReactionsMenuPadding(reactionsMenuPosition);\n        }\n\n        const reactionsCallbacks = reactionsMenu && ChatContextMenu.appendReactionsMenu({element: element, reactionsMenu, reactionsMenuPosition});\n\n        this.options.onToggle?.(true);\n        contextMenuController.openBtnMenu(element, () => {\n          this.options.onToggle?.(false);\n          reactionsCallbacks?.onClose();\n          middlewareHelper.destroy();\n          this.createMenu();\n          setTimeout(() => {\n            element.remove();\n          }, 400);\n        });\n\n        reactionsCallbacks?.onAfterInit();\n      },\n      listenerSetter\n    });\n  }\n};\n","/**\n * @returns duration in ms\n */\nexport default function getGifDuration(image: HTMLImageElement) {\n  const src = image.src;\n\n  return fetch(src)\n  .then((response) => response.arrayBuffer())\n  .then((arrayBuffer) => {\n    const d = new Uint8Array(arrayBuffer);\n    // Thanks to http://justinsomnia.org/2006/10/gif-animation-duration-calculation/\n    // And http://www.w3.org/Graphics/GIF/spec-gif89a.txt\n    let duration = 0;\n    for(let i = 0, length = d.length; i < length; ++i) {\n      // Find a Graphic Control Extension hex(21F904__ ____ __00)\n      if(d[i] == 0x21 &&\n       d[i + 1] == 0xF9 &&\n       d[i + 2] == 0x04 &&\n       d[i + 7] == 0x00) {\n        // Swap 5th and 6th bytes to get the delay per frame\n        const delay = (d[i + 5] << 8) | (d[i + 4] & 0xFF);\n\n        // Should be aware browsers have a minimum frame delay\n        // e.g. 6ms for IE, 2ms modern browsers (50fps)\n        duration += delay < 2 ? 10 : delay;\n      }\n    }\n\n    return duration / 1000;\n  });\n}\n","import noop from '@helpers/noop';\nimport calcCodecAndBitrate, {BITRATE_TARGET_FPS} from '@components/mediaEditor/finalRender/calcCodecAndBitrate';\n\nexport default async function createMp4VideoEncoder({width, height, frameRate, onError}: {\n  width: number,\n  height: number,\n  // mediabunny snaps timestamps to this frame rate, so pass it only when frames sit exactly on its grid\n  frameRate?: number,\n  onError?: (error: DOMException) => void\n}) {\n  const {BufferTarget, EncodedPacket, EncodedVideoPacketSource, Mp4OutputFormat, Output} = await import('mediabunny');\n\n  const output = new Output({\n    format: new Mp4OutputFormat({fastStart: 'in-memory'}),\n    target: new BufferTarget()\n  });\n\n  const videoSource = new EncodedVideoPacketSource('avc');\n  output.addVideoTrack(videoSource, {frameRate});\n\n  await output.start();\n\n  // packets must be added sequentially (decode order + backpressure), but the encoder callback is sync\n  let addChain: Promise<unknown> = Promise.resolve();\n\n  const encoder = new VideoEncoder({\n    output: (chunk, meta) => {\n      addChain = addChain.then(() => videoSource.add(EncodedPacket.fromEncodedChunk(chunk), meta));\n      addChain.catch(noop); // the rejection still surfaces when finalize awaits the chain\n    },\n    error: onError || ((e) => console.error(e))\n  });\n\n  encoder.configure({\n    width,\n    height,\n    ...calcCodecAndBitrate(width, height, BITRATE_TARGET_FPS)\n  });\n\n  return {\n    encoder,\n    finalize: async() => {\n      await addChain;\n      await output.finalize();\n      return new Blob([output.target.buffer], {type: 'video/mp4'});\n    }\n  };\n}\n","import createMp4VideoEncoder from '@components/mediaEditor/finalRender/createMp4VideoEncoder';\n\nlet supported: boolean;\n\nexport function canConvertGifToVideoSync() {\n  return !!supported;\n}\n\nexport async function canConvertGifToVideo(): Promise<boolean> {\n  if(supported !== undefined) {\n    return supported;\n  }\n\n  if(typeof(ImageDecoder) === 'undefined' || typeof(VideoEncoder) === 'undefined') {\n    return supported = false;\n  }\n\n  const {supportsVideoEncoding} = await import('@components/mediaEditor/support');\n  return supported = await supportsVideoEncoding();\n}\n\nexport default async function gifToVideo(blob: Blob, onProgress?: (progress: number) => void): Promise<{\n  blob: Blob,\n  width: number,\n  height: number,\n  duration: number\n}> {\n  const decoder = new ImageDecoder({data: await blob.arrayBuffer(), type: 'image/gif', preferAnimation: true});\n  await decoder.tracks.ready;\n  const frameCount = decoder.tracks.selectedTrack.frameCount;\n\n  const {image: firstFrame} = await decoder.decode({frameIndex: 0});\n  // * H.264 requires even dimensions\n  const width = firstFrame.displayWidth & ~1;\n  const height = firstFrame.displayHeight & ~1;\n  firstFrame.close();\n\n  const canvas = new OffscreenCanvas(width, height);\n  const ctx = canvas.getContext('2d');\n\n  const {encoder, finalize} = await createMp4VideoEncoder({width, height});\n\n  let duration = 0;\n  try {\n    for(let i = 0; i < frameCount; ++i) {\n      const {image} = await decoder.decode({frameIndex: i});\n      const frameDuration = image.duration || 1e5; // gifs with no delay play at ~10fps\n      ctx.drawImage(image, 0, 0, width, height);\n      image.close();\n\n      const videoFrame = new VideoFrame(canvas, {\n        timestamp: duration,\n        duration: frameDuration\n      });\n      encoder.encode(videoFrame, {keyFrame: i % 30 === 0});\n      videoFrame.close();\n\n      duration += frameDuration;\n      onProgress?.((i + 1) / frameCount);\n    }\n\n    await encoder.flush();\n  } finally {\n    encoder.close();\n    decoder.close();\n  }\n\n  return {\n    blob: await finalize(),\n    width,\n    height,\n    duration: duration / 1e6\n  };\n}\n","import {EXTENSION_MIME_TYPE_MAP, MIME_TYPE_ALIASES} from '@environment/mimeTypeMap';\n\ntype FileWithMimeType = Blob | {\n  mime_type?: string,\n  file_name?: string\n};\n\nexport default function getFileMimeType(file: FileWithMimeType): string {\n  const rawMimeType = 'mime_type' in file ? file.mime_type : (file as Blob).type;\n  const mimeType = (rawMimeType || '').toLowerCase();\n  const normalizedMimeType = MIME_TYPE_ALIASES[mimeType] || mimeType;\n\n  if(normalizedMimeType && normalizedMimeType !== 'application/octet-stream') {\n    return normalizedMimeType;\n  }\n\n  const fileName = 'name' in file ? (file as File).name : (file as {file_name?: string}).file_name;\n  const extension = fileName?.split('.').pop()?.toLowerCase() as MTFileExtension;\n  return EXTENSION_MIME_TYPE_MAP[extension] || normalizedMimeType;\n}\n\nexport function normalizeFileMimeType(file: File): File {\n  const mimeType = getFileMimeType(file);\n  if(!mimeType || mimeType === file.type) {\n    return file;\n  }\n\n  return new File([file], file.name, {\n    type: mimeType,\n    lastModified: file.lastModified\n  });\n}\n","import {MAX_EDITABLE_VIDEO_SIZE} from '@components/mediaEditor/support';\nimport getFileMimeType from '@helpers/files/getFileMimeType';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\n\nexport type MovVideoInfo = {\n  width: number,\n  height: number,\n  duration: number\n};\n\n// remuxing is I/O-bound, so even a huge H.264 file converts in moments — the\n// cap is the user's upload limit (2GB, 4GB with premium), not the conversion.\n// An actual transcode (non-H.264 source) runs at roughly realtime though, so\n// there the media-editor cap stays and bigger files fall back to documents.\nconst MAX_TRANSCODABLE_SIZE = MAX_EDITABLE_VIDEO_SIZE;\n\nconst UPLOAD_PART_SIZE = 512 * 1024;\n// upload_max_fileparts_default/premium, until the app config arrives\nconst FALLBACK_MAX_FILEPARTS = 4000;\n\nfunction getMaxUploadSize() {\n  const appConfig = apiManagerProxy.getAppConfig();\n  const parts = appConfig instanceof Promise ?\n    FALLBACK_MAX_FILEPARTS :\n    (rootScope.premium ? appConfig.upload_max_fileparts_premium : appConfig.upload_max_fileparts_default) ?? FALLBACK_MAX_FILEPARTS;\n  return parts * UPLOAD_PART_SIZE;\n}\n\n// 'in-memory' fastStart holds the media twice at finalization (the muxer's\n// buffers + the target buffer); above this size the moov goes to the end of\n// the file instead, halving the memory peak — players reach it via ranges\nconst IN_MEMORY_FASTSTART_MAX_SIZE = 512 * 1024 * 1024;\n\n// * whether this .mov can be offered the mp4 conversion at all; whether the\n// * conversion actually succeeds is only known per-file, when it runs\nexport function isConvertibleMov(file: File | Blob) {\n  return getFileMimeType(file) === 'video/quicktime' && file.size <= getMaxUploadSize();\n}\n\n// * Remuxes (or, when the codec demands it, transcodes) a QuickTime .mov file\n// * into a streamable mp4. H.264+AAC sources — the typical macOS screen\n// * recording or camera clip — are repackaged without re-encoding, so the\n// * conversion is lossless and fast; an HEVC source is transcoded to H.264,\n// * which requires WebCodecs support for both directions. When a track can't\n// * be carried over losslessly the conversion throws instead of silently\n// * dropping it, so the caller can fall back to sending the original file.\nexport default async function movToVideo(\n  file: Blob,\n  onProgress?: (progress: number) => void,\n  onInfo?: (info: MovVideoInfo) => void,\n  waitBeforeConvert?: Promise<void>\n): Promise<MovVideoInfo & {blob: Blob}> {\n  const {Input, Output, Conversion, Mp4OutputFormat, BufferTarget, BlobSource, QTFF, MP4} = await import('mediabunny');\n\n  const input = new Input({\n    source: new BlobSource(file),\n    formats: [QTFF, MP4]\n  });\n\n  const videoTrack = await input.getPrimaryVideoTrack();\n  if(!videoTrack) {\n    throw new Error('mov has no video track');\n  }\n\n  const [width, height, duration, videoCodec] = await Promise.all([\n    videoTrack.getDisplayWidth(),\n    videoTrack.getDisplayHeight(),\n    input.computeDuration(),\n    videoTrack.getCodec()\n  ]);\n\n  if(videoCodec !== 'avc' && file.size > MAX_TRANSCODABLE_SIZE) {\n    throw new Error('the video needs an actual transcode and is too big for one');\n  }\n\n  onInfo?.({width, height, duration});\n\n  // the metadata read above is cheap; the conversion below isn't — the caller\n  // can postpone it (e.g. until the popup open animation has finished)\n  await waitBeforeConvert;\n\n  const output = new Output({\n    format: new Mp4OutputFormat({fastStart: file.size <= IN_MEMORY_FASTSTART_MAX_SIZE ? 'in-memory' : false}),\n    target: new BufferTarget()\n  });\n\n  const conversion = await Conversion.init({\n    input,\n    output,\n    // H.264 + AAC play in every Telegram client; matching sources are copied\n    // as-is, only other codecs get transcoded (a PCM track would otherwise be\n    // copied into the mp4 verbatim, which Telegram clients can't play)\n    video: {codec: 'avc'},\n    audio: {codec: 'aac'},\n    showWarnings: false\n  });\n\n  if(!conversion.isValid || conversion.discardedTracks.length) {\n    await conversion.cancel();\n    const reasons = conversion.discardedTracks.map(({track, reason}) => `${track.type}: ${reason}`);\n    throw new Error(`cannot convert mov [${reasons.join(', ')}]`);\n  }\n\n  conversion.onProgress = onProgress;\n  await conversion.execute();\n\n  return {\n    blob: new Blob([output.target.buffer], {type: 'video/mp4'}),\n    width,\n    height,\n    duration\n  };\n}\n","export type AUDIO_MIME_TYPE = 'audio/mpeg' | 'audio/aac' | 'audio/wav';\nconst AUDIO_MIME_TYPES_SUPPORTED: Set<AUDIO_MIME_TYPE> = new Set([\n  'audio/mpeg',\n  'audio/aac',\n  'audio/wav'\n]);\n\nexport default AUDIO_MIME_TYPES_SUPPORTED;\n","import PopupElement from '.';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport shake from '@helpers/dom/shake';\nimport {Middleware} from '@helpers/middleware';\nimport {LangPackKey} from '@lib/langPack';\nimport Button from '@components/button';\nimport currencyStarIcon from '@components/currencyStarIcon';\nimport InputField from '@components/inputField';\nimport Section from '@components/section';\nimport PopupStars from '@components/popups/stars';\n\nexport function InputStarsField(options: {\n  middleware: Middleware,\n  placeholder?: LangPackKey,\n  label?: LangPackKey,\n  max: number,\n  onValue?: (stars: number) => void,\n}) {\n  const inputField = new InputField({\n    inputMode: 'numeric',\n    label: options.label,\n    placeholder: options.placeholder,\n    plainText: true,\n    withLinebreaks: false\n  });\n\n  inputField.container.classList.add('popup-make-paid-input');\n\n  const star = currencyStarIcon() as HTMLElement;\n  star.classList.add('popup-make-paid-star');\n  inputField.container.append(star);\n\n  const onInput = () => {\n    const value = '' + +inputField.value;\n    let newValue = value.replace(/[^0-9]/g, '');\n    if(+newValue > options.max) {\n      newValue = '' + options.max;\n    }\n    inputField.setValueSilently(newValue);\n    options.onValue?.(+newValue);\n  };\n\n  inputField.input.addEventListener('input', onInput);\n  options.middleware.onDestroy(() => {\n    inputField.input.removeEventListener('input', onInput);\n  });\n\n  return inputField;\n}\n\nexport default class PopupMakePaid extends PopupElement {\n  private inputField: InputField;\n\n  constructor(onSave: (value: number) => void, private editingFrom?: number) {\n    super('popup-make-paid', {\n      closable: true,\n      overlayClosable: true,\n      body: true,\n      title: 'PaidMedia.Title',\n      withConfirm: 'PaidMedia.Button',\n      footer: true,\n      withFooterConfirm: true\n    });\n\n    this.footer.classList.add('abitlarger');\n\n    attachClickEvent(this.btnConfirm, () => {\n      const value = parseInt(this.inputField.value || '0');\n      if(value > 0) {\n        onSave(value);\n        this.hide();\n      } else {\n        shake(this.inputField.container);\n      }\n    }, {listenerSetter: this.listenerSetter});\n\n    if(editingFrom) {\n      const button = Button('btn-primary btn-primary-transparent primary', {text: 'PaidMedia.KeepFree'});\n      attachClickEvent(button, () => {\n        onSave(0);\n        this.hide();\n      }, {listenerSetter: this.listenerSetter});\n      this.btnConfirm.after(button);\n    }\n\n    this.d();\n  }\n\n  private async d() {\n    const appConfig = await this.managers.apiManager.getAppConfig();\n    this.appendSolid(() => {\n      const inputField = this.inputField = InputStarsField({\n        middleware: this.middlewareHelper.get(),\n        label: 'PaidMedia.Enter',\n        max: appConfig.stars_paid_post_amount_max\n      });\n\n      if(this.editingFrom) {\n        inputField.value = '' + this.editingFrom;\n      }\n\n      setTimeout(() => {\n        this.show();\n        placeCaretAtEnd(inputField.input);\n      }, 0);\n\n      return (\n        <Section\n          caption=\"PaidMedia.Caption\"\n          captionArgs={[\n            anchorCallback(() => {\n              PopupElement.createPopup(PopupStars);\n            })\n          ]}\n          noShadow\n          noDelimiter\n        >\n          {inputField.container}\n        </Section>\n      );\n    });\n  }\n}\n","\ntype CanVideoBeAnimatedArgs = {\n  noSound: boolean;\n  size: number;\n  isEditingMediaFromAlbum?: boolean;\n};\n\n/**\n * Determines whether a video can be labeled as GIF, will loop in the chat if so\n */\nexport default function canVideoBeAnimated({noSound, size, isEditingMediaFromAlbum}: CanVideoBeAnimatedArgs) {\n  return !isEditingMediaFromAlbum && noSound &&\n    size > (10 * 1024) &&\n    size < (10 * 1024 * 1024);\n}\n","export function makeDateFromTimestamp(timestamp: number): Date {\n  return new Date(timestamp * 1000);\n}\n","import {Portal, render} from 'solid-js/web';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {createStore} from 'solid-js/store';\n\nimport type Chat from '@components/chat/chat';\nimport type {MessageSendingParams, SendFileDetails} from '@appManagers/appMessagesManager';\nimport type {ChatRights} from '@appManagers/appChatsManager';\nimport PopupElement from '.';\nimport {toastNew} from '@components/toast';\nimport SendContextMenu from '@components/chat/sendContextMenu';\nimport {createPosterFromMedia, createPosterFromVideo} from '@helpers/createPoster';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {FormatterArguments, i18n, LangPackKey} from '@lib/langPack';\nimport calcImageInBox from '@helpers/calcImageInBox';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport MEDIA_MIME_TYPES_SUPPORTED from '@environment/mediaMimeTypesSupport';\nimport getGifDuration from '@helpers/getGifDuration';\nimport gifToVideo, {canConvertGifToVideo, canConvertGifToVideoSync} from '@helpers/gifToVideo';\nimport movToVideo, {isConvertibleMov} from '@helpers/movToVideo';\nimport getFileMimeType, {normalizeFileMimeType} from '@helpers/files/getFileMimeType';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {ObjectURLScope} from '@helpers/objectUrl';\nimport noop from '@helpers/noop';\nimport toHHMMSS from '@helpers/string/toHHMMSS';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport createVideo from '@helpers/dom/createVideo';\nimport prepareAlbum from '@components/prepareAlbum';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {ThumbCache} from '@lib/storages/thumbs';\nimport onMediaLoad from '@helpers/onMediaLoad';\nimport {SEND_WHEN_ONLINE_TIMESTAMP, SERVER_IMAGE_MIME_TYPES, STARS_CURRENCY, THUMB_TYPE_FULL} from '@appManagers/constants';\nimport wrapDocument from '@components/wrappers/document';\nimport wrapVideo from '@components/wrappers/video';\nimport wrapMediaSpoiler, {toggleMediaSpoiler} from '@components/wrappers/mediaSpoiler';\nimport {MiddlewareHelper} from '@helpers/middleware';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport scaleMediaElement from '@helpers/canvas/scaleMediaElement';\nimport {doubleRaf, fastRafPromise} from '@helpers/schedulers';\nimport defineNotNumerableProperties from '@helpers/object/defineNotNumerableProperties';\nimport {DocumentAttribute, DraftMessage, Photo, PhotoSize} from '@layer';\nimport {getPreviewBytesFromURL} from '@helpers/bytes/getPreviewURLFromBytes';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport Button from '@components/buttonTsx';\nimport InputFieldAnimated from '@components/inputFieldAnimated';\nimport InputFieldMessage from '@components/inputFieldMessage';\nimport IMAGE_MIME_TYPES_SUPPORTED from '@environment/imageMimeTypesSupport';\nimport VIDEO_MIME_TYPES_SUPPORTED from '@environment/videoMimeTypesSupport';\nimport {IS_MOV_SUPPORTED} from '@environment/videoSupport';\nimport rootScope from '@lib/rootScope';\nimport shake from '@helpers/dom/shake';\nimport AUDIO_MIME_TYPES_SUPPORTED from '@environment/audioMimeTypeSupport';\nimport liteMode from '@helpers/liteMode';\nimport handleVideoLeak from '@helpers/dom/handleVideoLeak';\nimport wrapDraft from '@components/wrappers/draft';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport {ChatType} from '@components/chat/chatType';\nimport pause from '@helpers/schedulers/pause';\nimport {Accessor, createMemo, createRoot, createSignal, Setter, Signal} from 'solid-js';\nimport SelectedEffect from '@components/chat/selectedEffect';\nimport PopupMakePaid from '@components/popups/makePaid';\nimport paymentsWrapCurrencyAmount from '@helpers/paymentsWrapCurrencyAmount';\nimport Icon from '@components/icon';\nimport {MediaEditorFinalResult, MediaEditorFinalResultPayload} from '@components/mediaEditor/finalRender/createFinalResult';\nimport RenderProgressCircle from '@components/mediaEditor/renderProgressCircle';\nimport {delay} from '@components/mediaEditor/utils';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport canVideoBeAnimated from '@appManagers/utils/docs/canVideoBeAnimated';\nimport isEphemeralMessageId from '@appManagers/utils/messageId/isEphemeralMessageId';\nimport MarkupTooltip from '@components/chat/markupTooltip';\nimport {MAX_EDITABLE_VIDEO_SIZE, supportsVideoEncoding} from '@components/mediaEditor/support';\nimport {animateValue} from '@helpers/animateValue';\nimport {lerp} from '@helpers/lerp';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport ButtonMenu from '@components/buttonMenu';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {makeDateFromTimestamp} from '@helpers/date/makeDateFromTimestamp';\nimport Section from '@components/section';\n\n\ntype SendFileParams = SendFileDetails & {\n  file?: File | MyDocument,\n  scaledBlob?: Blob,\n  itemDiv: HTMLElement,\n  mediaSpoiler?: HTMLElement,\n  middlewareHelper: MiddlewareHelper,\n  objectURLs: ObjectURLScope,\n  editResult?: MediaEditorFinalResult\n};\n\ntype ConstructorInputFile = {\n  file: File;\n  editResult: MediaEditorFinalResult;\n};\n\nlet currentPopup: PopupNewMedia;\n\nconst MAX_WIDTH = 400 - 16;\n\n// A \"compressed photo\" heavier than this is re-encoded to JPEG at PHOTO_COMPRESSED_QUALITY,\n// otherwise the server rejects it with PHOTO_SAVE_FILE_INVALID (a detailed 2560px PNG is\n// ~10MB). Used for both the direct send (scaleImageForTelegram) and the edited result\n// (passed into the media editor), so the policy lives in one place.\nconst PHOTO_HEAVY_BYTES = 2 * 1024 * 1024;\nconst PHOTO_COMPRESSED_QUALITY = 0.9;\n\nexport function getCurrentNewMediaPopup() {\n  return currentPopup;\n}\n\nexport default class PopupNewMedia extends PopupElement {\n  private mediaContainer: HTMLElement;\n  private wasDraft: DraftMessage.draftMessage;\n\n  private willAttach: Partial<{\n    type: 'media' | 'document',\n    isMedia: true,\n    group: boolean,\n    sendFileDetails: SendFileParams[],\n    invertMedia: boolean,\n    stars: number\n  }>;\n  private effect: Accessor<DocId>;\n  private setEffect: Setter<DocId>;\n  private messageInputField: InputFieldAnimated;\n  private captionLengthMax: number;\n\n  private animationGroup: AnimationItemGroup;\n\n  private activeActionsMenuItemDiv: HTMLElement;\n  private activeActionsMenu: HTMLElement;\n  private canShowActions = false;\n\n  private cachedMediaEditorFiles = new WeakMap<Blob, File>;\n\n  private actionsMenuListenerSetter = new ListenerSetter;\n\n  private isMediaEditorOpen = false;\n  private ephemeralComposer = false;\n  private pinnedEphemeralSendingParams: MessageSendingParams;\n\n  private files: File[] = [];\n  private gifDocument: MyDocument;\n  private pendingEditResults = new WeakMap<File, MediaEditorFinalResult>;\n  private convertedFiles = new WeakMap<File, {file: File, width: number, height: number, duration: number}>;\n  private failedConversions = new WeakSet<File>;\n  private fileConversions = new Map<File, {promise: Promise<void>, progress: Signal<number>, info: Promise<{width: number, height: number} | undefined>}>;\n  // * heavy work (conversions) waits for this so it doesn't jank the open animation\n  private openAnimationDeferred = deferredPromise<void>();\n\n  constructor(\n    private chat: Chat,\n    inputFiles: (ConstructorInputFile | File)[],\n    willAttachType: PopupNewMedia['willAttach']['type'],\n    private ignoreInputValue?: boolean,\n    gifDocument?: MyDocument,\n    pinnedEphemeralSendingParams?: MessageSendingParams\n  ) {\n    super('popup-send-photo popup-new-media', {\n      closable: true,\n      withConfirm: true,\n      confirmShortcutIsSendShortcut: true,\n      body: true,\n      title: true,\n      scrollable: true\n    });\n\n    const sendingParams = pinnedEphemeralSendingParams || this.chat.getMessageSendingParams();\n    const hasEphemeralReply = sendingParams.replyTo?._ === 'inputReplyToEphemeralMessage' ||\n      (!!sendingParams.replyToMsgId && isEphemeralMessageId(sendingParams.replyToMsgId));\n    if(sendingParams.ephemeral && hasEphemeralReply) {\n      this.pinnedEphemeralSendingParams = {\n        ephemeral: true,\n        ephemeralReceiverId: sendingParams.ephemeralReceiverId,\n        peerId: sendingParams.peerId,\n        threadId: sendingParams.threadId,\n        replyToMsgId: sendingParams.replyToMsgId,\n        replyTo: sendingParams.replyTo\n      };\n    }\n\n    this.ephemeralComposer = !!sendingParams.ephemeral;\n    if(this.ephemeralComposer && inputFiles.length > 1) {\n      inputFiles = inputFiles.slice(0, 1);\n      toastNew({langPackKey: 'Ephemeral.SingleAttachment'});\n    }\n\n    this.files = inputFiles.map((inputFile) => {\n      // The {file, editResult} wrapper is the only variant carrying a `file` field; everything else\n      // is a plain File. Cross-realm-safe (a Document PiP window's File isn't `instanceof` the main File).\n      if(!('file' in inputFile)) {\n        return normalizeFileMimeType(inputFile);\n      }\n      const file = normalizeFileMimeType(inputFile.file);\n      this.pendingEditResults.set(file, inputFile.editResult);\n      return file;\n    });\n\n    this.animationGroup = 'NEW-MEDIA';\n    this.gifDocument = gifDocument;\n    canConvertGifToVideo(); // warm up the memo for the sync reads\n    // this.updateConfirmBtnContent(0);\n    this.construct(willAttachType);\n  }\n\n  public static async canSend({peerId, onlyVisible, threadId}: {peerId?: PeerId, onlyVisible?: boolean, threadId?: number}) {\n    const actions: ChatRights[] = [\n      'send_photos',\n      'send_videos',\n      'send_docs',\n      'send_audios',\n      'send_gifs'\n    ];\n\n    const actionsPromises = actions.map((action) => {\n      return peerId.isAnyChat() && !onlyVisible ?\n        rootScope.managers.appChatsManager.hasRights(peerId.toChatId(), action, undefined, threadId ? true : undefined) :\n        true;\n    });\n\n    const out: {[action in ChatRights]?: boolean} = {};\n\n    const results = await Promise.all(actionsPromises);\n    actions.forEach((action, idx) => {\n      out[action] = results[idx];\n    })\n\n    return out;\n  }\n\n  private async construct(willAttachType: PopupNewMedia['willAttach']['type']) {\n    this.willAttach = {\n      type: willAttachType,\n      sendFileDetails: [],\n      group: true\n    };\n\n    const captionMaxLength = await this.managers.apiManager.getLimit('caption');\n    this.captionLengthMax = captionMaxLength;\n\n    const canSend = await PopupNewMedia.canSend({\n      ...this.chat.getMessageSendingParams(),\n      onlyVisible: true\n    });\n\n    const canSendPhotos = canSend.send_photos;\n    const canSendVideos = canSend.send_videos;\n    const canSendDocs = canSend.send_docs;\n\n    attachClickEvent(this.btnConfirm, async() => (await pause(0), this.send()), {listenerSetter: this.listenerSetter});\n\n    const btnMenu = ButtonMenuToggle({\n      listenerSetter: this.listenerSetter,\n      direction: 'bottom-left',\n      buttons: [{\n        icon: 'plusround',\n        text: 'Add',\n        onClick: () => {\n          this.chat.input.onAttachClick(false, false, false);\n        },\n        verify: () => this.canHaveMultipleFiles()\n      }, {\n        icon: 'image',\n        text: 'Popup.Attach.AsMedia',\n        onClick: () => this.changeType('media'),\n        verify: () => {\n          if(!this.hasAnyMedia() || this.willAttach.type !== 'document' || this.isEditingMediaFromAlbum()) {\n            return false;\n          }\n\n          if(!canSendPhotos && !canSendVideos) {\n            return false;\n          }\n\n          if(!canSendPhotos || !canSendVideos) {\n            const mimeTypes = canSendPhotos ? IMAGE_MIME_TYPES_SUPPORTED : VIDEO_MIME_TYPES_SUPPORTED;\n            const {media, files} = this.partition(mimeTypes);\n            if(files.length) {\n              return false;\n            }\n          }\n\n          return true;\n        }\n      }, {\n        icon: 'document',\n        text: 'SendAsFile',\n        onClick: () => this.changeType('document'),\n        verify: () => this.files.length === 1 && this.willAttach.type !== 'document' && canSendDocs && !this.isEditingMediaFromAlbum()\n      }, {\n        icon: 'document',\n        text: 'SendAsFiles',\n        onClick: () => this.changeType('document'),\n        verify: () => this.files.length > 1 && this.willAttach.type !== 'document' && canSendDocs && !this.isEditingMediaFromAlbum()\n      }, {\n        icon: 'groupmedia',\n        text: 'Popup.Attach.GroupMedia',\n        onClick: () => this.changeGroup(true),\n        verify: () => !this.willAttach.group && this.canGroupSomething() && this.canCheckIfHasGif() && !this.hasGif() && this.canHaveMultipleFiles()\n      }, {\n        icon: 'groupmediaoff',\n        text: 'Popup.Attach.UngroupMedia',\n        onClick: () => this.changeGroup(false),\n        verify: () => this.willAttach.group && this.canGroupSomething() && this.canCheckIfHasGif() && !this.hasGif() && this.canHaveMultipleFiles()\n      }, {\n        icon: 'mediaspoiler',\n        text: 'EnablePhotoSpoiler',\n        onClick: () => this.changeSpoilers(true),\n        verify: () => this.canToggleSpoilers(true, true)\n      }, {\n        icon: 'mediaspoiler',\n        text: 'Popup.Attach.EnableSpoilers',\n        onClick: () => this.changeSpoilers(true),\n        verify: () => this.canToggleSpoilers(true, false)\n      }, {\n        icon: 'mediaspoileroff',\n        text: 'DisablePhotoSpoiler',\n        onClick: () => this.changeSpoilers(false),\n        verify: () => this.canToggleSpoilers(false, true)\n      }, {\n        icon: 'mediaspoileroff',\n        text: 'Popup.Attach.RemoveSpoilers',\n        onClick: () => this.changeSpoilers(false),\n        verify: () => this.canToggleSpoilers(false, false)\n      }, {\n        icon: 'captionup',\n        text: 'CaptionAbove',\n        onClick: () => this.moveCaption(true),\n        verify: () => this.canMoveCaption() && !this.willAttach.invertMedia\n      }, {\n        icon: 'captiondown',\n        text: 'CaptionBelow',\n        onClick: () => this.moveCaption(false),\n        verify: () => this.canMoveCaption() && !!this.willAttach.invertMedia\n      }, {\n        icon: 'cash_circle',\n        text: 'PaidMedia.Menu.Edit',\n        onClick: () => {\n          PopupElement.createPopup(PopupMakePaid, (value) => {\n            this.setPaidMedia(value);\n          }, this.willAttach.stars);\n        },\n        verify: () => !!this.willAttach.stars && this.canSendPaidMedia()\n      }, {\n        icon: 'cash_circle',\n        text: 'PaidMedia.Menu',\n        onClick: () => {\n          PopupElement.createPopup(PopupMakePaid, (value) => {\n            this.setPaidMedia(value);\n          });\n        },\n        verify: () => !this.willAttach.stars && this.canSendPaidMedia()\n      }]\n    });\n\n    this.header.append(btnMenu);\n\n    this.btnConfirm.remove();\n\n    this.mediaContainer = document.createElement('div');\n    this.mediaContainer.classList.add('popup-photo');\n    this.scrollable.container.append(this.mediaContainer);\n\n    let draft: DocumentFragment;\n    if(!this.ignoreInputValue) {\n      this.wasDraft = this.chat.input.getCurrentInputAsDraft();\n      if(this.wasDraft) {\n        draft = wrapDraft(this.wasDraft, {\n          wrappingForPeerId: this.chat.peerId,\n          animationGroup: this.animationGroup,\n          middleware: this.middlewareHelper.get()\n        });\n\n        this.chat.input.messageInputField.value = '';\n      }\n    }\n\n    createRoot((dispose) => {\n      this.middlewareHelper.onDestroy(dispose);\n\n      const children = InputFieldMessage({\n        maxLength: this.captionLengthMax,\n        animationGroup: this.animationGroup,\n        listenerSetter: this.listenerSetter,\n        onScroll: this.onScroll,\n        onInput: (hasValue) => {\n          this.starsState.set({hasMessage: hasValue});\n          this.updateEphemeralComposer();\n        },\n        stars: this.starsState.totalStars,\n        draft,\n        ref: (inputField) => {\n          this.messageInputField = inputField;\n        },\n        btnConfirm: this.btnConfirm,\n        chatInput: this.chat.input\n      });\n\n      Portal({\n        mount: this.container,\n        children\n      });\n    });\n    this.updateEphemeralComposer();\n\n    this.listenerSetter.add(this.scrollable.container)('scroll', this.onScroll);\n\n    if(this.chat.input.editMessage) {\n      this.willAttach.invertMedia = this.chat.input.editMessage.pFlags?.invert_media;\n    }\n\n    this.attachFiles();\n\n    this.addEventListener('close', () => {\n      this.files.length = 0;\n      this.willAttach.sendFileDetails.length = 0;\n      this.hideActiveActionsMenu();\n\n      if(currentPopup === this) {\n        currentPopup = undefined;\n      }\n    });\n\n    if(this.chat.type === ChatType.Scheduled && this.isEditing()) {\n      attachContextMenuListener({\n        element: this.btnConfirm,\n        callback: async(e) => {\n          cancelEvent(e);\n\n          const element = await ButtonMenu({\n            buttons: [{\n              text: 'MessageScheduleEditTime',\n              icon: 'schedule',\n              onClick: () => {\n                const editMessage = this.chat.input.editMessage;\n                this.chat.input.scheduleSending(\n                  () => this.send(true),\n                  editMessage?.date ? makeDateFromTimestamp(editMessage.date) : undefined,\n                  editMessage?.schedule_repeat_period\n                );\n              }\n            }],\n            listenerSetter: this.listenerSetter\n          });\n          element.classList.add('menu-send', 'top-left');\n\n          this.container.append(element);\n\n          await fastRafPromise();\n          contextMenuController.openBtnMenu(element, () => {\n            setTimeout(() => {\n              element.remove();\n            }, 400);\n          });\n        },\n        listenerSetter: this.listenerSetter\n      });\n    }\n\n    if(this.chat.type !== ChatType.Scheduled && !this.isEditing()) {\n      createRoot((dispose) => {\n        this.chat.destroyMiddlewareHelper.onDestroy(dispose);\n        const [effect, setEffect] = createSignal<DocId>(this.wasDraft?.effect);\n        this.effect = effect;\n        this.setEffect = setEffect;\n        this.btnConfirm.append(SelectedEffect({effect: this.effect}) as HTMLElement);\n      });\n\n      const sendMenu = new SendContextMenu({\n        onSilentClick: () => {\n          this.chat.input.sendSilent = true;\n          this.send();\n        },\n        onScheduleClick: () => {\n          this.chat.input.scheduleSending(() => {\n            this.send();\n          });\n        },\n        onSendWhenOnlineClick: () => {\n          this.chat.input.setScheduleTimestamp(SEND_WHEN_ONLINE_TIMESTAMP, () => {\n            this.send();\n          });\n        },\n        openSide: 'top-left',\n        onContextElement: this.btnConfirm,\n        middleware: this.middlewareHelper.get(),\n        canSendWhenOnline: this.chat.input.canSendWhenOnline,\n        onRef: (element) => {\n          this.container.append(element);\n        },\n        onOpen: () => !this.ephemeralComposer,\n        withEffects: () => this.chat.peerId.isUser() && this.chat.peerId !== rootScope.myId,\n        effect: this.effect,\n        onEffect: this.setEffect\n      });\n\n      sendMenu?.setPeerParams({peerId: this.chat.peerId, isPaid: !!this.chat.starsAmount});\n    }\n\n    currentPopup = this;\n  }\n\n  private canConvertGif(file: File) {\n    return canConvertGifToVideoSync() &&\n      file.size <= MAX_EDITABLE_VIDEO_SIZE &&\n      !this.failedConversions.has(file);\n  }\n\n  private canConvertMov(file: File | MyDocument): file is File {\n    // cross-realm-safe `instanceof File` (a Document PiP window's File isn't `instanceof` the main\n    // File): a File is the only variant carrying `lastModified`; no MyDocument variant has it.\n    return 'lastModified' in file &&\n      isConvertibleMov(file) &&\n      !this.failedConversions.has(file);\n  }\n\n  // * a convertible .mov counts as media right away — it becomes an mp4 video\n  // * by send time, even in browsers that can't play video/quicktime natively\n  private isMediaFile(file: File | MyDocument) {\n    return MEDIA_MIME_TYPES_SUPPORTED.has(getFileMimeType(file)) || this.canConvertMov(file);\n  }\n\n  // * the server only allows photos and plain videos in paid media, so GIF files\n  // * are sent converted to silent videos — an unconvertible GIF can't be paid.\n  // * Same for .mov files in browsers that can't play them natively: unconverted\n  // * they go out as documents\n  private hasUnpayableMedia() {\n    return !!this.gifDocument || this.files.some((file) => {\n      const mimeType = getFileMimeType(file);\n      if(mimeType === 'image/gif') {\n        return !this.convertedFiles.has(file) && !this.canConvertGif(file);\n      }\n\n      if(getFileMimeType(file) === 'video/quicktime' && !IS_MOV_SUPPORTED) {\n        return !this.convertedFiles.has(file) && !this.canConvertMov(file);\n      }\n\n      return false;\n    });\n  }\n\n  private getEphemeralCommandResolution(caption?: string) {\n    if(caption === undefined) {\n      if(!this.messageInputField) {\n        return {state: 'none'} as const;\n      }\n\n      caption = getRichValueWithCaret(this.messageInputField.input, true, false).value;\n    }\n\n    return this.chat.input.getEphemeralCommandResolution(caption || '');\n  }\n\n  private isEphemeralComposerMode(caption?: string) {\n    return !!this.pinnedEphemeralSendingParams ||\n      this.getEphemeralCommandResolution(caption).state !== 'none';\n  }\n\n  private updateEphemeralComposer() {\n    const ephemeralComposer = this.isEphemeralComposerMode();\n    const changed = ephemeralComposer !== this.ephemeralComposer;\n    this.ephemeralComposer = ephemeralComposer;\n    this.element.classList.toggle('is-ephemeral-composer', ephemeralComposer);\n    if(!changed || !ephemeralComposer) {\n      return;\n    }\n\n    if(this.files.length > 1) {\n      this.files.splice(1);\n      toastNew({langPackKey: 'Ephemeral.SingleAttachment'});\n      if(this.willAttach.sendFileDetails.length) {\n        this.attachFiles();\n      }\n    }\n\n    if(this.willAttach.stars) {\n      this.setPaidMedia(undefined);\n    }\n  }\n\n  private async canSendPaidMedia() {\n    if(this.ephemeralComposer || this.isEditing() || this.hasUnpayableMedia()) return false;\n    return await this.managers.appPeersManager.isBroadcast(this.chat.peerId) &&\n      !!(await this.managers.appProfileManager.getChannelFull(this.chat.peerId.toChatId())).pFlags.paid_media_allowed;\n  }\n\n  public willSendPaidMedia() {\n    return this.willAttach.stars &&\n      this.willAttach.type === 'media' &&\n      !this.hasUnpayableMedia() &&\n      this.willAttach.sendFileDetails.length <= 10;\n  }\n\n  public setPaidMedia(stars: number) {\n    this.willAttach.stars = stars;\n    this.changeSpoilers(!!stars);\n    this.setUnlockPlaceholders();\n  }\n\n  private setUnlockPlaceholders() {\n    const {stars} = this.willAttach;\n    this.mediaContainer.querySelectorAll('.popup-item-album, .popup-item-media:not(.grouped-item)').forEach((element) => {\n      const className = 'extended-media-buy';\n      element.querySelector(`.${className}`)?.remove();\n\n      if(!this.willSendPaidMedia()) {\n        return;\n      }\n\n      const priceEl = document.createElement('span');\n      priceEl.classList.add(className);\n      priceEl.append(i18n('PaidMedia.Unlock', [paymentsWrapCurrencyAmount(stars, STARS_CURRENCY)]));\n      element.append(priceEl);\n    });\n  }\n\n  private onScroll = () => {\n    const {input} = this.messageInputField;\n    this.scrollable.onAdditionalScroll();\n    if(input.scrollTop > 0 && input.scrollHeight > 130) {\n      this.scrollable.container.classList.remove('scrolled-end');\n    }\n\n    this.scrollable.container.addEventListener('scroll', () => {\n      const actions = this.activeActionsMenu;\n      if(!actions || !this.activeActionsMenuItemDiv) return;\n\n      const bcr = this.activeActionsMenuItemDiv.getBoundingClientRect();\n      if(!this.canShowActionsForBcr(bcr)) return void this.hideActiveActionsMenu();\n\n      actions.style.left = bcr.left + bcr.width / 2 + 'px';\n      actions.style.top = bcr.bottom + 'px';\n    });\n  };\n\n  private async applyMediaSpoiler(item: SendFileParams, noAnimation?: boolean) {\n    const spoilerToggle: HTMLElement = item.itemDiv.querySelector('.spoiler-toggle');\n    if(spoilerToggle) spoilerToggle.dataset.disabled = 'true';\n\n\n    const middleware = item.middlewareHelper.get();\n    const {width: widthStr, height: heightStr} = item.itemDiv.style;\n\n    let width: number, height: number;\n    if(item.itemDiv.classList.contains('album-item')) {\n      const {width: containerWidthStr, height: containerHeightStr} = item.itemDiv.parentElement.style;\n      const containerWidth = parseInt(containerWidthStr);\n      const containerHeight = parseInt(containerHeightStr);\n\n      width = +widthStr.slice(0, -1) / 100 * containerWidth;\n      height = +heightStr.slice(0, -1) / 100 * containerHeight;\n    } else {\n      width = parseInt(widthStr);\n      height = parseInt(heightStr);\n    }\n\n    const {url} = await scaleMediaElement({\n      media: item.itemDiv.firstElementChild as HTMLImageElement,\n      boxSize: makeMediaSize(40, 40),\n      mediaSize: makeMediaSize(width, height),\n      toDataURL: true,\n      quality: 0.2\n    });\n\n    const strippedBytes = getPreviewBytesFromURL(url);\n    const photoSize: PhotoSize.photoStrippedSize = {\n      _: 'photoStrippedSize',\n      bytes: strippedBytes,\n      type: 'i'\n    };\n\n    item.strippedBytes = strippedBytes;\n\n    const photo: Photo.photo = {\n      _: 'photo',\n      sizes: [\n        photoSize\n      ],\n      id: 0,\n      access_hash: 0,\n      date: 0,\n      dc_id: 0,\n      file_reference: [],\n      pFlags: {}\n    };\n\n    const mediaSpoiler = await wrapMediaSpoiler({\n      middleware,\n      width,\n      height,\n      animationGroup: this.animationGroup,\n      media: photo\n    });\n\n    if(!middleware()) {\n      return;\n    }\n\n    if(!noAnimation) {\n      mediaSpoiler.classList.add('is-revealing');\n    }\n\n    item.mediaSpoiler = mediaSpoiler;\n    item.itemDiv.append(mediaSpoiler);\n\n    await doubleRaf();\n    if(!middleware()) {\n      return;\n    }\n\n    toggleMediaSpoiler({\n      mediaSpoiler,\n      reveal: false\n    });\n\n    if(spoilerToggle) {\n      spoilerToggle.dataset.toggled = 'true';\n      delete spoilerToggle.dataset.disabled;\n    }\n  }\n\n  private removeMediaSpoiler(item: SendFileParams) {\n    const spoilerToggle: HTMLElement = item.itemDiv.querySelector('.spoiler-toggle');\n    if(spoilerToggle) spoilerToggle.dataset.disabled = 'true';\n\n    toggleMediaSpoiler({\n      mediaSpoiler: item.mediaSpoiler,\n      reveal: true,\n      destroyAfter: true\n    });\n\n    if(spoilerToggle) {\n      delete spoilerToggle.dataset.toggled;\n      delete spoilerToggle.dataset.disabled;\n    }\n\n    item.mediaSpoiler = undefined;\n  }\n\n  public appendDrops(element: HTMLElement) {\n    this.body.append(element);\n  }\n\n  private partition(mimeTypes = MEDIA_MIME_TYPES_SUPPORTED) {\n    const media: SendFileParams[] = [], files: SendFileParams[] = [], audio: SendFileParams[] = [];\n    this.willAttach.sendFileDetails.forEach((d) => {\n      // * a convertible .mov counts as its converted form — an mp4 video\n      if(mimeTypes.has(getFileMimeType(d.file)) || (mimeTypes.has('video/mp4') && this.canConvertMov(d.file))) {\n        media.push(d);\n      } else if(AUDIO_MIME_TYPES_SUPPORTED.has(getFileMimeType(d.file) as any)) {\n        audio.push(d);\n      } else {\n        files.push(d);\n      }\n    });\n\n    return {\n      media,\n      files,\n      audio\n    };\n  }\n\n  private mediaCount() {\n    return this.partition().media.length;\n  }\n\n  private hasAnyMedia() {\n    return this.mediaCount() > 0;\n  }\n\n  private messagesCount() {\n    let count = 0;\n    this.iterate(() => {\n      ++count;\n    });\n\n    return count;\n  }\n\n  private canGroupSomething() {\n    const {media, files, audio} = this.partition();\n    return media.length > 1 || files.length > 1 || audio.length > 1;\n  }\n\n  private canToggleSpoilers(toggle: boolean, single: boolean) {\n    if(this.willSendPaidMedia()) return false;\n\n    let good = this.willAttach.type === 'media' && this.hasAnyMedia();\n    if(single && good) {\n      good = !!this.gifDocument || this.files.length === 1;\n    }\n\n    if(good) {\n      const media = this.willAttach.sendFileDetails\n      .filter((d) => this.isMediaFile(d.file))\n      const mediaWithSpoilers = media.filter((d) => d.mediaSpoiler);\n\n      good = single ? true : media.length > 1;\n\n      if(good) {\n        good = toggle ? media.length !== mediaWithSpoilers.length : media.length === mediaWithSpoilers.length;\n      }\n    }\n\n    return good;\n  }\n\n  private changeType(type: PopupNewMedia['willAttach']['type']) {\n    if(type === 'document') {\n      this.moveCaption(false);\n    }\n\n    this.willAttach.type = type;\n    this.attachFiles();\n  }\n\n  public changeGroup(group: boolean) {\n    this.willAttach.group = group;\n    this.attachFiles();\n    this.starsState.set({isGrouped: group});\n  }\n\n  public changeSpoilers(toggle: boolean) {\n    this.partition().media.forEach((item) => {\n      if(toggle && !item.mediaSpoiler) {\n        this.applyMediaSpoiler(item);\n      } else if(!toggle && item.mediaSpoiler) {\n        this.removeMediaSpoiler(item);\n      }\n    });\n  }\n\n  public canMoveCaption() {\n    return !this.messageInputField.isEmpty() && this.willAttach.type === 'media';\n  }\n\n  public moveCaption(above: boolean) {\n    this.willAttach.invertMedia = above || undefined;\n  }\n\n  public addFiles(files: File[]) {\n    files = files.map(normalizeFileMimeType);\n\n    if(!this.canHaveMultipleFiles() && this.files.length) {\n      if(files.length) {\n        this.files.splice(0, Infinity, files[0]);\n        this.attachFiles();\n      }\n      return;\n    }\n\n    if(!this.canHaveMultipleFiles()) files.splice(1);\n\n    const toPush = files.filter((file) => {\n      const found = this.files.find((_file) => {\n        return _file.lastModified === file.lastModified && _file.name === file.name && _file.size === file.size;\n      });\n\n      return !found;\n    });\n\n    if(toPush.length) {\n      this.files.push(...toPush);\n\n      if(this.willAttach.stars) {\n        if(this.hasUnpayableMedia()) {\n          // * an unpayable GIF/mov was added — drop the price visibly instead of\n          // * silently posting the priced media for free at send time\n          this.setPaidMedia(undefined);\n        } else if(this.files.length > 10) {\n          this.changeSpoilers(false);\n        }\n      }\n\n      this.attachFiles();\n    }\n  }\n\n  private onKeyDown = (e: KeyboardEvent) => {\n    const target = e.target as HTMLElement;\n    const {input} = this.messageInputField;\n    if(target !== input) {\n      if(target.tagName === 'INPUT' || target.isContentEditable || this.isMediaEditorOpen) {\n        return;\n      }\n\n      input.focus();\n      placeCaretAtEnd(input);\n    }\n  };\n\n  private prepareEditedFileForSending(params: SendFileParams): File | undefined {\n    const editResult = params.editResult?.getResult();\n    if(!editResult || editResult instanceof Promise) return undefined;\n\n    return this.wrapMediaEditorBlobInFile(params.file as File, editResult.blob, params.editResult?.isVideo);\n  }\n\n  // * the send menu stamps the one-shot flags (schedule date / silent) onto the\n  // * ChatInput and only then delegates here, and this path never goes through\n  // * onMessageSent — so drop them once the attempt is over, sent or rejected,\n  // * otherwise the next message inherits them\n  private async send(force = false) {\n    try {\n      return await this.performSend(force);\n    } finally {\n      this.chat.input.resetSendingFlags();\n    }\n  }\n\n  private async performSend(force = false) {\n    if(this.fileConversions.size) { // * the file to send doesn't exist yet\n      return;\n    }\n\n    let {value: caption, entities} = getRichValueWithCaret(this.messageInputField.input, true, false);\n    if(caption.length > this.captionLengthMax) {\n      toastNew({langPackKey: 'Error.PreviewSender.CaptionTooLong'});\n      return;\n    }\n\n    const {input} = this.chat;\n    const ephemeralCommandResolution = this.getEphemeralCommandResolution(caption);\n    if(!this.pinnedEphemeralSendingParams && !input.verifyEphemeralCommand(caption)) {\n      return;\n    }\n\n    const ephemeralReceiverId = this.pinnedEphemeralSendingParams?.ephemeralReceiverId ||\n      (\n        ephemeralCommandResolution.state === 'resolved' ?\n          ephemeralCommandResolution.receiverId :\n          undefined\n      );\n    const isEphemeral = !!this.pinnedEphemeralSendingParams ||\n      ephemeralCommandResolution.state !== 'none';\n    if(isEphemeral && !this.isEditing() && (this.chat.type === ChatType.Scheduled || input.scheduleDate)) {\n      toastNew({langPackKey: 'Ephemeral.CantSchedule'});\n      return;\n    }\n\n    if(isEphemeral && this.willAttach.sendFileDetails.length > 1) {\n      this.files.splice(1);\n      this.willAttach.sendFileDetails.splice(1);\n      toastNew({langPackKey: 'Ephemeral.SingleAttachment'});\n    }\n\n    const isSlowModeActive = () => input.showSlowModeTooltipIfNeeded({\n      sendingFew: this.messagesCount() > 1,\n      container: this.btnConfirm.parentElement,\n      element: this.btnConfirm\n    });\n\n    if(!this.isEditing() && !isEphemeral && await isSlowModeActive()) {\n      return;\n    }\n\n    const canSend = await PopupNewMedia.canSend({\n      ...this.chat.getMessageSendingParams(),\n      onlyVisible: isEphemeral\n    });\n    const willAttach = this.willAttach;\n    willAttach.isMedia = willAttach.type === 'media' || undefined;\n    const {sendFileDetails, isMedia} = willAttach;\n\n    let foundBad = false;\n    this.iterate((sendFileParams) => {\n      if(foundBad) {\n        return;\n      }\n\n      const isBad: (LangPackKey | boolean)[] = sendFileParams.map((params) => {\n        const isVideoFile = () => VIDEO_MIME_TYPES_SUPPORTED.has(getFileMimeType(params.file) as any) || this.canConvertMov(params.file);\n        const a: [Set<string> | (() => boolean), LangPackKey, ChatRights][] = [\n          [AUDIO_MIME_TYPES_SUPPORTED, 'GlobalAttachAudioRestricted', 'send_audios'],\n          [() => !this.isMediaFile(params.file), 'GlobalAttachDocumentsRestricted', 'send_docs']\n        ];\n\n        if(isMedia) {\n          a.unshift(\n            [IMAGE_MIME_TYPES_SUPPORTED, 'GlobalAttachPhotoRestricted', 'send_photos'],\n            [() => isVideoFile() && params.isAnimated, 'GlobalAttachGifRestricted', 'send_gifs'],\n            [isVideoFile, 'GlobalAttachVideoRestricted', 'send_videos']\n          );\n        }\n\n        const found = a.find(([verify]) => {\n          return typeof(verify) === 'function' ? verify() : verify.has(getFileMimeType(params.file));\n        });\n\n        if(found) {\n          return canSend[found[2]] ? undefined : found[1];\n        }\n\n        return (!isMedia && !canSend.send_docs && 'GlobalAttachDocumentsRestricted') || undefined;\n      });\n\n      const key = isBad.find((i) => typeof(i) === 'string') as LangPackKey;\n      if(key) {\n        toastNew({\n          langPackKey: key\n        });\n\n        if(liteMode.isAvailable('animations')) {\n          shake(this.body);\n        }\n      }\n\n      foundBad ||= !!key;\n    });\n\n    if(foundBad) {\n      return;\n    }\n\n    if(this.chat.type === ChatType.Scheduled && !this.isEditing() && !force) {\n      this.chat.input.scheduleSending(() => {\n        this.send(true);\n      }, this.chat.input.editMessage?.date ? makeDateFromTimestamp(this.chat.input.editMessage.date) : undefined);\n\n      return;\n    }\n\n    const {length} = sendFileDetails;\n    const sendingParams = this.chat.getMessageSendingParams();\n    if(isEphemeral) {\n      Object.assign(sendingParams, this.pinnedEphemeralSendingParams);\n      sendingParams.ephemeral = true;\n      sendingParams.ephemeralReceiverId = ephemeralReceiverId;\n    } else {\n      sendingParams.ephemeral = undefined;\n      sendingParams.ephemeralReceiverId = undefined;\n    }\n\n    const preparedPaymentResult = !isEphemeral && !input.editMsgId ?\n      await input.paidMessageInterceptor.prepareStarsForPayment(this.starsState.totalMessages()) :\n      undefined;\n    if(preparedPaymentResult === PAYMENT_REJECTED) return;\n    sendingParams.confirmedPaymentResult = preparedPaymentResult;\n\n    let effect = this.effect?.();\n    this.iterate((sendFileParams) => {\n      if(caption && sendFileParams.length !== length) {\n        this.managers.appMessagesManager.sendText({\n          ...sendingParams,\n          text: caption,\n          entities,\n          effect\n          // clearDraft: true\n        });\n\n        caption = entities = effect = undefined;\n      }\n\n      const willSendPaidMedia = this.willSendPaidMedia();\n\n      const d: SendFileDetails[] = sendFileParams.map((params) => {\n        return {\n          ...params,\n          file: this.prepareEditedFileForSending(params) || this.convertedFiles.get(params.file as File)?.file || params.scaledBlob || params.file,\n          width: params.editResult?.width || params.width,\n          height: params.editResult?.height || params.height,\n          spoiler: willSendPaidMedia ? undefined : !!params.mediaSpoiler,\n          editResult: undefined as MediaEditorFinalResult\n        };\n      });\n\n      const w = {\n        ...willAttach,\n        sendFileDetails: d\n      };\n\n      if(!willSendPaidMedia) {\n        delete w.stars;\n      }\n\n      if(!this.chat.input.editMessage) {\n        this.managers.appMessagesManager.sendGrouped({\n          ...sendingParams,\n          caption,\n          entities,\n          effect,\n          isMedia,\n          // clearDraft: true,\n          ...w\n        });\n      } else {\n        this.managers.appMessagesManager.editMessageMedia({\n          message: this.chat.input.editMessage,\n          text: caption,\n          options: {\n            entities,\n            invertMedia: willAttach.invertMedia,\n            scheduleDate: sendingParams.scheduleDate,\n            isMedia\n          },\n          sendFileDetails: d[0]\n        });\n\n        this.chat.input.onMessageSent();\n      }\n\n      caption = entities = effect = undefined;\n    });\n\n    if(isEphemeral && !this.isEditing()) {\n      input.onMessageSent(true, true, true);\n    } else if(sendingParams.replyToMsgId || sendingParams.suggestedPost) {\n      input.onHelperCancel();\n    }\n    // input.replyToMsgId = this.chat.threadId;\n    // input.onMessageSent();\n    this.wasDraft = undefined;\n\n    this.hide();\n  }\n\n  private modifyMimeTypeForTelegram(mimeType: MTMimeType): MTMimeType {\n    return SERVER_IMAGE_MIME_TYPES.has(mimeType) ? 'image/jpeg' : mimeType;\n  }\n\n  private async scaleImageForTelegram(\n    image: HTMLImageElement,\n    mimeType: MTMimeType,\n    fileSize: number,\n    objectURLs: ObjectURLScope,\n    convertIncompatible?: boolean\n  ) {\n    const PHOTO_SIDE_LIMIT = 2560;\n    // PNG/BMP are lossless and can be huge even when ≤2560px (a detailed 2560px\n    // screenshot/map is ~10MB), which the server rejects as a compressed photo with\n    // PHOTO_SAVE_FILE_INVALID. Re-encode such HEAVY lossless images to JPEG — but\n    // only when they're actually heavy, so a normal small PNG keeps its original\n    // quality and isn't touched at all.\n    const isHeavyLossless = (mimeType === 'image/png' || mimeType === 'image/bmp') && fileSize > PHOTO_HEAVY_BYTES;\n    const needsResize = Math.max(image.naturalWidth, image.naturalHeight) > PHOTO_SIDE_LIMIT;\n    let url = image.src, scaledBlob: Blob;\n    if(\n      mimeType !== 'image/gif' &&\n      (needsResize || isHeavyLossless || (convertIncompatible && !SERVER_IMAGE_MIME_TYPES.has(mimeType)))\n    ) {\n      const {blob} = await scaleMediaElement({\n        media: image,\n        // Cap each side at PHOTO_SIDE_LIMIT, but never upscale a smaller image\n        // (aspectFitted would otherwise blow a small PNG up to 2560px).\n        boxSize: makeMediaSize(\n          Math.min(image.naturalWidth, PHOTO_SIDE_LIMIT),\n          Math.min(image.naturalHeight, PHOTO_SIDE_LIMIT)\n        ),\n        mediaSize: makeMediaSize(image.naturalWidth, image.naturalHeight),\n        mimeType: this.modifyMimeTypeForTelegram(mimeType) as any,\n        // Only drop quality when compressing a heavy image; a plain >2560 resize or\n        // a format conversion keeps the default (near-lossless) quality.\n        quality: isHeavyLossless ? PHOTO_COMPRESSED_QUALITY : undefined\n      });\n\n      scaledBlob = blob;\n      objectURLs.release(url);\n      url = objectURLs.create(blob);\n      await renderImageFromUrlPromise(image, url);\n    }\n\n    return scaledBlob && {url, blob: scaledBlob};\n  }\n\n  // * the confirm button is locked while anything is still producing the file\n  // * to send — gif/mov conversions and media-editor renders share it\n  private updateConfirmLock() {\n    const pendingEdit = this.willAttach.sendFileDetails.some((params) => params.editResult?.getResult() instanceof Promise);\n    (this.btnConfirmOnEnter as HTMLButtonElement).disabled = this.isMediaEditorOpen ||\n      pendingEdit ||\n      this.fileConversions.size > 0;\n  }\n\n  private mountItemProgress(itemDiv: HTMLElement, creationProgress: Signal<number>, promise: Promise<any>) {\n    const div = document.createElement('div');\n    const dispose = render(() => RenderProgressCircle({creationProgress}), div);\n    itemDiv.append(div);\n\n    promise.finally(() => {\n      div.remove();\n      dispose();\n    }).catch(noop);\n  }\n\n  private getMediaConversion(file: File) {\n    let conversion = this.fileConversions.get(file);\n    if(!conversion) {\n      const progress = createSignal(0);\n      const infoDeferred = deferredPromise<{width: number, height: number} | undefined>();\n      const convertedPromise = getFileMimeType(file) === 'image/gif' ?\n        this.openAnimationDeferred.then(() => gifToVideo(file, progress[1])) :\n        movToVideo(file, progress[1], (info) => infoDeferred.resolve(info), this.openAnimationDeferred);\n      const promise = convertedPromise.then((converted) => {\n        this.convertedFiles.set(file, {\n          file: this.wrapMediaEditorBlobInFile(file, converted.blob, true),\n          width: converted.width,\n          height: converted.height,\n          duration: Math.ceil(converted.duration)\n        });\n      }, (err) => {\n        console.error('media conversion error', err);\n        this.failedConversions.add(file);\n\n        if(!this.destroyed) {\n          toastNew({langPackKey: 'Error.AnError'});\n          if(this.willAttach.stars && this.hasUnpayableMedia()) {\n            this.setPaidMedia(undefined);\n          }\n        }\n      }).finally(() => {\n        this.fileConversions.delete(file);\n        infoDeferred.resolve(undefined); // unblock a placeholder awaiting the info of a failed conversion\n\n        if(!this.destroyed) {\n          this.updateConfirmLock();\n          pause(0).then(() => this.attachFiles());\n        }\n      });\n\n      this.fileConversions.set(file, conversion = {promise, progress, info: infoDeferred});\n      this.updateConfirmLock();\n    }\n\n    return conversion;\n  }\n\n  private async convertGifMedia(params: SendFileParams) {\n    const {itemDiv} = params;\n    const file = params.file as File;\n\n    const img = new Image();\n    itemDiv.append(img);\n    const url = params.objectURL = params.objectURLs.create(file);\n    await renderImageFromUrlPromise(img, url);\n    params.width = img.naturalWidth;\n    params.height = img.naturalHeight;\n\n    const conversion = this.getMediaConversion(file);\n    this.mountItemProgress(itemDiv, conversion.progress, conversion.promise);\n  }\n\n  private async convertMovMedia(params: SendFileParams) {\n    const {itemDiv} = params;\n    const file = params.file as File;\n\n    const conversion = this.getMediaConversion(file);\n\n    // * purely cosmetic — the browser may not be able to play the original\n    // * .mov, in which case the placeholder stays blank under the progress\n    const video = createVideo({middleware: params.middlewareHelper.get()});\n    video.src = params.objectURL = params.objectURLs.create(file);\n    video.autoplay = true;\n    video.controls = false;\n    video.muted = true;\n    video.addEventListener('timeupdate', () => {\n      video.pause();\n    }, {once: true});\n    itemDiv.append(video);\n\n    const info = await conversion.info;\n    params.width = info?.width || 320;\n    params.height = info?.height || 240;\n\n    this.mountItemProgress(itemDiv, conversion.progress, conversion.promise);\n  }\n\n  private async attachMedia(params: SendFileParams) {\n    const {itemDiv} = params;\n    itemDiv.classList.add('popup-item-media');\n\n    let file = params.file as File;\n\n    // * GIFs are converted to silent videos right away, so they can be edited and\n    // * priced (the server rejects animated documents in paid media). params.file\n    // * KEEPS the original — this.files lookups rely on its identity; the converted\n    // * file is rendered here and substituted at send time\n    if(getFileMimeType(file) === 'image/gif' && file.size <= MAX_EDITABLE_VIDEO_SIZE && !this.failedConversions.has(file)) {\n      const converted = this.convertedFiles.get(file);\n      if(converted) {\n        file = converted.file;\n        params.width = converted.width;\n        params.height = converted.height;\n        params.duration = converted.duration;\n        params.isAnimated = true;\n      } else if(await canConvertGifToVideo()) {\n        return this.convertGifMedia(params);\n      }\n    } else if(this.canConvertMov(file)) {\n      // * .mov files get the same treatment: remuxed/transcoded to mp4 right away,\n      // * so they go out as streamable videos every client can play\n      const converted = this.convertedFiles.get(file);\n      if(converted) {\n        file = converted.file;\n        params.width = converted.width;\n        params.height = converted.height;\n        params.duration = converted.duration;\n      } else {\n        return this.convertMovMedia(params);\n      }\n    }\n\n    const isVideo = getFileMimeType(file).startsWith('video/');\n\n    const editResult = params.editResult;\n\n    let promise: Promise<void>;\n\n    const myself = this;\n\n    function addVideoTime() {\n      if(params.isAnimated || !params.duration) return;\n      const videoTime = document.createElement('span');\n      videoTime.classList.add('video-time');\n      videoTime.textContent = toHHMMSS(params.duration, false);\n      itemDiv.append(videoTime);\n    }\n\n    function addGifLabel() {\n      if(!params.isAnimated) return;\n      const gifLabel = i18n('AttachGif');\n      gifLabel.classList.add('video-time');\n      itemDiv.append(gifLabel);\n    }\n\n    if(editResult) {\n      const result = editResult.getResult();\n\n      if(!(result instanceof Promise)) {\n        if(editResult.isVideo) {\n          await putEditedImage(editResult.preview);\n          await putEditedVideo(result);\n          addGifLabel();\n          addVideoTime();\n        } else {\n          await putEditedImage(result.blob, true);\n        }\n      } else {\n        await putEditedImage(editResult.preview);\n\n        this.mountItemProgress(itemDiv, editResult.creationProgress, result);\n        this.updateConfirmLock();\n\n        result.then(() => {\n          if(!this.destroyed) {\n            pause(0).then(() => !this.destroyed && this.attachFiles());\n          }\n        }).catch(async() => {\n          params.editResult = undefined;\n          if(!this.destroyed) {\n            pause(0).then(() => !this.destroyed && this.attachFiles());\n          }\n\n          this.hideActiveActionsMenu();\n        }).finally(() => {\n          this.updateConfirmLock();\n          this.hideActiveActionsMenu();\n        });\n      }\n\n      async function putEditedImage(blob: Blob, saveObjectURL = false) {\n        const url = params.objectURLs.create(blob);\n        if(saveObjectURL) params.objectURL = url;\n\n        const img = new Image();\n        await renderImageFromUrlPromise(img, url);\n\n        img.className = 'popup-item-media-extend-full';\n\n        itemDiv.append(img);\n\n        params.width = editResult.width;\n        params.height = editResult.height;\n      }\n\n      async function putEditedVideo(result: MediaEditorFinalResultPayload) {\n        const video = createVideo({middleware: params.middlewareHelper.get()});\n        const url = params.objectURLs.create(result.blob);\n        video.src = params.objectURL = url;\n        video.autoplay = true;\n        video.controls = false;\n        video.muted = true;\n        video.loop = true;\n\n        video.className = 'popup-item-media-extend-full';\n\n        itemDiv.append(video);\n\n        await onMediaLoad(video as HTMLMediaElement)\n\n        params.width = editResult.width;\n        params.height = editResult.height;\n        params.duration = video.duration;\n        params.isAnimated = canVideoBeAnimated({\n          noSound: !result.hasSound,\n          size: result.blob.size,\n          isEditingMediaFromAlbum: myself.isEditingMediaFromAlbum()\n        });\n\n        const thumb = result.thumb || await createPosterFromVideo(video);\n\n        params.thumb = {\n          url: params.objectURLs.create(thumb.blob),\n          isCover: !params.isAnimated && !!result.thumb,\n          ...thumb\n        };\n      }\n    } else if(isVideo) {\n      const video = createVideo({middleware: params.middlewareHelper.get()});\n      video.src = params.objectURL = params.objectURLs.create(file);\n      video.autoplay = true;\n      video.controls = false;\n      video.muted = true;\n\n      video.addEventListener('timeupdate', () => {\n        video.pause();\n      }, {once: true});\n\n      itemDiv.append(video);\n\n      let error: Error;\n      try {\n        const promise = onMediaLoad(video as HTMLMediaElement);\n        await handleVideoLeak(video, promise);\n      } catch(err) {\n        error = err as any;\n      }\n\n      params.width = video.videoWidth;\n      params.height = video.videoHeight;\n      params.duration = Math.floor(video.duration);\n\n      if(error) {\n        throw error;\n      }\n\n      const audioDecodedByteCount = (video as any).webkitAudioDecodedByteCount;\n      if(audioDecodedByteCount !== undefined && !params.isAnimated) {\n        const noSound = !audioDecodedByteCount;\n        params.isAnimated = canVideoBeAnimated({\n          noSound,\n          size: file.size,\n          isEditingMediaFromAlbum: this.isEditingMediaFromAlbum()\n        });\n      }\n\n      const thumb = await createPosterFromVideo(video);\n      params.thumb = {\n        url: params.objectURLs.create(thumb.blob),\n        ...thumb\n      };\n\n      addGifLabel();\n      addVideoTime();\n    } else {\n      const img = new Image();\n      itemDiv.append(img);\n\n      const url = params.objectURL = params.objectURLs.create(file);\n      await renderImageFromUrlPromise(img, url);\n\n      const mimeType = getFileMimeType(params.file) as MTMimeType;\n      const scaled = await this.scaleImageForTelegram(img, mimeType, file.size, params.objectURLs, true);\n      if(scaled) {\n        params.objectURL = scaled.url;\n        params.scaledBlob = scaled.blob;\n      }\n\n      params.width = img.naturalWidth;\n      params.height = img.naturalHeight;\n\n      if(getFileMimeType(file) === 'image/gif') {\n        params.isAnimated = true;\n\n        promise = Promise.all([\n          getGifDuration(img).then((duration) => {\n            params.duration = Math.ceil(duration);\n          }),\n\n          createPosterFromMedia(img).then((thumb) => {\n            params.thumb = {\n              url: params.objectURLs.create(thumb.blob),\n              ...thumb\n            };\n          })\n        ]).then(() => {});\n      }\n    }\n    {\n      const showActions = async() => {\n        if(this.activeActionsMenuItemDiv === itemDiv || !this.canShowActions || this.destroyed) return;\n        const bcr = itemDiv.getBoundingClientRect();\n        if(!this.canShowActionsForBcr(bcr)) return;\n\n        this.hideActiveActionsMenu();\n\n        this.activeActionsMenuItemDiv = itemDiv;\n\n        const actions = document.createElement('div');\n        this.activeActionsMenu = actions;\n        actions.classList.add('popup-item-media-action-menu');\n        const itemCls = 'popup-item-media-action';\n\n        const canEditVideo = await supportsVideoEncoding() && file.size <= MAX_EDITABLE_VIDEO_SIZE;\n\n        let equalizeIcon: HTMLSpanElement;\n        if(!this.willAttach.stars && getFileMimeType(file) !== 'image/gif' && (!isVideo || canEditVideo)) {\n          import('../mediaEditor'); // prefetch\n\n          equalizeIcon = Icon('equalizer', itemCls);\n          equalizeIcon.addEventListener('click', async() => {\n            this.hideActiveActionsMenu();\n            MarkupTooltip.getInstance().hide();\n\n            (this.btnConfirmOnEnter as HTMLButtonElement).disabled = true;\n            const source = itemDiv.querySelector('video') || itemDiv.querySelector('img');\n            if(!source) return;\n\n            const {openMediaEditorFromMedia} = await import('../mediaEditor');\n\n            this.isMediaEditorOpen = true;\n            const mediaSrc = params.objectURLs.create(file);\n\n            openMediaEditorFromMedia({\n              source,\n              rect: itemDiv.getBoundingClientRect(),\n              animatedCanvasSize: [params.width, params.height],\n              mediaType: isVideo ? 'video' : 'image',\n              mediaSrc,\n              getMediaBlob: async() => file,\n              managers: this.managers,\n              // Compressed-photo output: JPEG, and only drop quality for a heavy\n              // source (same policy/threshold as the direct send) — a small edit\n              // stays near-lossless. (Ignored for the video path.)\n              imageType: 'image/jpeg',\n              imageQuality: file.size > PHOTO_HEAVY_BYTES ? PHOTO_COMPRESSED_QUALITY : undefined,\n              onEditFinish: (result) => {\n                params.editResult = result;\n                this.attachFiles();\n              },\n              editingMediaState: params.editResult?.editingMediaState,\n              onClose: (hasGif) => {\n                params.objectURLs.release(mediaSrc);\n                this.isMediaEditorOpen = false;\n                if(!hasGif) this.updateConfirmLock();\n              },\n              canImageResultInGIF: !this.isEditingMediaFromAlbum() && canEditVideo\n            });\n          });\n        }\n\n        let spoilerToggle: HTMLSpanElement;\n        if(!this.willAttach.stars) {\n          spoilerToggle = document.createElement('span');\n          spoilerToggle.classList.add(itemCls, 'spoiler-toggle');\n          if(params.mediaSpoiler) spoilerToggle.dataset.toggled = 'true';\n          spoilerToggle.append(Icon('mediaspoiler', 'spoiler-on'), Icon('mediaspoileroff', 'spoiler-off'));\n          spoilerToggle.addEventListener('click', () => {\n            if(spoilerToggle.dataset.disabled) return; // Prevent double clicks\n            spoilerToggle.dataset.toggled = spoilerToggle.dataset.toggled === 'true' ? 'false' : 'true'\n            !params.mediaSpoiler ? this.applyMediaSpoiler(params) : this.removeMediaSpoiler(params);\n          });\n        }\n\n        const deleteIcon = Icon('delete', itemCls);\n        deleteIcon.addEventListener('click', () => this.removeFile(params));\n\n        const resultPromise = params?.editResult?.getResult();\n        let cancelBtn: HTMLDivElement;\n        if(resultPromise instanceof Promise) {\n          actions.classList.add('popup-item-media-action-menu-cancel');\n          cancelBtn = document.createElement('div');\n          cancelBtn.append(i18n('Cancel'));\n          cancelBtn.classList.add('popup-item-media-action-menu-cancel-btn');\n          cancelBtn.addEventListener('click', () => {\n            params?.editResult.cancel?.();\n          });\n        }\n\n        actions.append(...[cancelBtn, equalizeIcon, spoilerToggle, deleteIcon].filter(Boolean));\n\n        actions.style.left = bcr.left + bcr.width / 2 + 'px';\n        actions.style.top = bcr.bottom + 'px';\n\n        getOverlayRoot().append(actions);\n        await doubleRaf();\n        actions.style.opacity = '1';\n\n        const listener = (e: MouseEvent) => {\n          if(\n            (e.target as HTMLElement)?.closest?.('.popup-item-media-action-menu') ||\n            e.target === itemDiv ||\n            itemDiv.contains(e.target as Node)\n          ) return;\n          this.hideActiveActionsMenu();\n        }\n        this.actionsMenuListenerSetter.add(document)('pointermove', listener);\n        this.actionsMenuListenerSetter.add(document)('keydown', () => {\n          this.hideActiveActionsMenu();\n        }, {capture: true});\n        if(IS_MOBILE) {\n          this.actionsMenuListenerSetter.add(document)('pointerdown', listener);\n        }\n      }\n\n      itemDiv.addEventListener('pointermove', showActions);\n      itemDiv.addEventListener('pointerup', showActions);\n    }\n\n    return promise;\n  }\n\n  private removeFile(params: SendFileParams) {\n    const idx = this.files.findIndex((file) => file === params.file);\n    if(idx < 0) return;\n    this.hideActiveActionsMenu();\n    this.files.splice(idx, 1);\n    this.files.length ? this.attachFiles() : this.destroy();\n  }\n\n  private async hideActiveActionsMenu() {\n    this.actionsMenuListenerSetter.removeAll();\n\n    const el = this.activeActionsMenu;\n    this.activeActionsMenu = this.activeActionsMenuItemDiv = undefined;\n\n    if(!el) return;\n    el.style.opacity = '0';\n    el.style.pointerEvents = 'none';\n    await delay(200);\n    el?.remove();\n  }\n\n  private wrapMediaEditorBlobInFile(originalFile: File, editedBlob: Blob, isVideo: boolean) {\n    if(this.cachedMediaEditorFiles.has(editedBlob)) return this.cachedMediaEditorFiles.get(editedBlob);\n\n    let name = originalFile.name;\n\n    const imageTypeToExtMap: Record<string, string> = {\n      'image/jpeg': 'jpg',\n      'image/jpg': 'jpg',\n      'image/png': 'png',\n      'image/webp': 'webp'\n    };\n\n    if(isVideo) name = name.replace(/\\.[^.]+$/, '.mp4');\n    else if(editedBlob.type in imageTypeToExtMap) {\n      const ext = '.' + imageTypeToExtMap[editedBlob.type];\n      name = name.replace(/\\.[^.]+$/, ext);\n      if(!name.endsWith(ext)) name = name.replace(/\\.+$/, '') + ext;\n    }\n\n    const result = new File([editedBlob], name, {type: editedBlob.type});\n    this.cachedMediaEditorFiles.set(editedBlob, result);\n\n    return result;\n  }\n\n\n  private async attachDocument(params: SendFileParams): ReturnType<PopupNewMedia['attachMedia']> {\n    const {itemDiv} = params;\n    itemDiv.classList.add('popup-item-document');\n\n    const editResult = await params.editResult?.getResult();\n    const file = editResult ?\n      this.wrapMediaEditorBlobInFile(params.file as File, editResult.blob, params.editResult?.isVideo) :\n      params.file as File;\n\n    const isPhoto = getFileMimeType(file).startsWith('image/');\n    const isAudio = AUDIO_MIME_TYPES_SUPPORTED.has(getFileMimeType(file) as any);\n    if(isPhoto || isAudio || file.size < 20e6) {\n      params.objectURL ||= params.objectURLs.create(file);\n    }\n\n    const attributes: DocumentAttribute[] = [];\n\n    let img: HTMLImageElement;\n    if(isPhoto && params.objectURL) {\n      img = new Image();\n      await renderImageFromUrlPromise(img, params.objectURL);\n      const scaled = await this.scaleImageForTelegram(img, file.type as MTMimeType, file.size, params.objectURLs);\n      if(scaled) {\n        params.objectURL = scaled.url;\n      }\n    }\n\n    if(isAudio && params.objectURL) {\n      try {\n        // * get audio duration\n        const audio = new Audio();\n        audio.src = params.objectURL;\n        audio.muted = true;\n        audio.autoplay = true;\n        await onMediaLoad(audio);\n        params.duration = audio.duration;\n        attributes.push({\n          _: 'documentAttributeAudio',\n          duration: params.duration,\n          pFlags: {}\n        });\n      } catch(err) {\n        console.error('audio loading error', err);\n      }\n    }\n\n    const doc: MyDocument = {\n      _: 'document',\n      file,\n      file_name: file.name || '',\n      size: file.size,\n      type: isAudio ? 'audio' : (isPhoto ? 'photo' : undefined),\n      access_hash: 0,\n      attributes,\n      date: 0,\n      dc_id: 0,\n      file_reference: [],\n      id: 0,\n      pFlags: {},\n      duration: params.duration\n    };\n\n    let cacheContext: ThumbCache;\n    if(params.objectURL) {\n      cacheContext = {\n        url: params.objectURL,\n        downloaded: file.size,\n        type: THUMB_TYPE_FULL\n      };\n    }\n\n    const docDiv = await wrapDocument({\n      message: {\n        _: 'message',\n        pFlags: {\n          is_outgoing: true\n        },\n        mid: 0,\n        peerId: 0,\n        media: {\n          _: 'messageMediaDocument',\n          document: doc\n        }\n      } as any,\n      middleware: params.middlewareHelper.get(),\n      clickable: true,\n      cacheContext\n    });\n\n    if(isPhoto) {\n      params.width = img.naturalWidth;\n      params.height = img.naturalHeight;\n    }\n\n    itemDiv.append(docDiv);\n\n    createRoot((dispose) => {\n      params.middlewareHelper.get().onDestroy(dispose);\n      Button.Icon({\n        icon: 'delete',\n        class: 'popup-item-document-delete',\n        noRipple: true,\n        onClick: (e) => {\n          e.stopPropagation();\n          this.removeFile(params);\n        },\n        ref: (ref) => itemDiv.append(ref)\n      });\n    });\n  }\n\n  private attachFile = (file: File | MyDocument, oldParams?: Partial<SendFileParams>) => {\n    const willAttach = this.willAttach;\n    const shouldCompress = this.shouldCompress(file);\n\n    const itemDiv = document.createElement('div');\n    itemDiv.classList.add('popup-item');\n\n    const params: SendFileParams = {\n      file,\n      ...(oldParams || {})\n    } as any;\n\n    // do not pass these properties to worker\n    defineNotNumerableProperties(params, ['scaledBlob', 'middlewareHelper', 'objectURLs', 'itemDiv', 'mediaSpoiler']);\n\n    params.middlewareHelper = this.middlewareHelper.get().create();\n    params.objectURLs = new ObjectURLScope();\n    params.itemDiv = itemDiv;\n\n    const middleware = params.middlewareHelper.get();\n    middleware.onDestroy(() => params.objectURLs.dispose());\n\n    const promise = this.gifDocument ?\n      this.attachGifDocument(params) :\n      (shouldCompress ? this.attachMedia(params) : this.attachDocument(params));\n    willAttach.sendFileDetails.push(params);\n    return promise.catch((err) => {\n      itemDiv.style.backgroundColor = '#000';\n      console.error('error rendering file', err);\n    }).finally(() => {\n      if(!middleware()) {\n        params.objectURLs.dispose();\n      }\n    });\n  };\n\n  private async attachGifDocument(params: SendFileParams) {\n    const itemDiv = params.itemDiv;\n    itemDiv.classList.add('popup-item-media');\n\n    const doc = params.file as MyDocument;\n    params.width = doc.w;\n    params.height = doc.h;\n    params.duration = doc.duration;\n    params.isAnimated = true;\n\n    const size = calcImageInBox(doc.w, doc.h, MAX_WIDTH, 320);\n    itemDiv.style.width = size.width + 'px';\n    itemDiv.style.height = size.height + 'px';\n\n    const loadPromises: Promise<any>[] = [];\n    await wrapVideo({\n      doc,\n      container: itemDiv as HTMLDivElement,\n      boxWidth: size.width,\n      boxHeight: size.height,\n      lazyLoadQueue: null,\n      noInfo: true,\n      group: this.animationGroup,\n      middleware: params.middlewareHelper.get(),\n      withoutPreloader: true,\n      loadPromises\n    });\n\n    await Promise.all(loadPromises);\n\n    const gifLabel = i18n('AttachGif');\n    gifLabel.classList.add('video-time');\n    itemDiv.append(gifLabel);\n\n    return params;\n  }\n\n  private shouldCompress(file: File | MyDocument) {\n    return this.willAttach.type === 'media' && this.isMediaFile(file);\n  }\n\n  private onRender() {\n    // show now\n    if(this.element.classList.contains('active')) {\n      return;\n    }\n\n    this.listenerSetter.add(getOverlayRoot())('keydown', this.onKeyDown);\n    animationIntersector.setOnlyOnePlayableGroup(this.animationGroup);\n    this.addEventListener('close', () => {\n      animationIntersector.setOnlyOnePlayableGroup();\n\n      if(!this.ignoreInputValue && this.wasDraft) {\n        this.chat.input.setDraft(this.wasDraft, false, true);\n      }\n    });\n    this.show();\n\n    const resolveOpenAnimation = () => this.openAnimationDeferred.resolve();\n    this.listenerSetter.add(this.element)('transitionend', resolveOpenAnimation, {once: true});\n    pause(400).then(resolveOpenAnimation); // reduced motion has no transition to end\n  }\n\n  private starsState = createRoot((dispose) => {\n    this.middlewareHelper.get().onDestroy(() => void dispose());\n\n    const [store, set] = createStore({\n      hasMessage: false,\n      isGrouped: true,\n      attachedFiles: this.files.length,\n      starsAmount: this.chat.starsAmount || 0\n    });\n\n    const shouldCountMessage = () => +store.hasMessage * +(!store.isGrouped && store.attachedFiles > 1);\n    const totalMessages = createMemo(() => +shouldCountMessage() + store.attachedFiles);\n    const totalStars = createMemo(() => store.starsAmount * totalMessages());\n\n    return {store, set, totalMessages, totalStars};\n  });\n\n  public setStarsAmount(starsAmount: number) {\n    this.starsState.set({starsAmount});\n  }\n\n  private setTitle() {\n    const {willAttach, title, files} = this;\n    let key: LangPackKey;\n    const args: FormatterArguments = [];\n    if(this.gifDocument) {\n      key = 'PreviewSender.SendGif';\n      args.push(1);\n    } else if(willAttach.type === 'document') {\n      key = 'PreviewSender.SendFile';\n      args.push(files.length);\n    } else {\n      let foundPhotos = 0, foundVideos = 0, foundFiles = 0;\n      files.forEach((file) => {\n        const mimeType = getFileMimeType(file);\n        if(mimeType === 'image/gif') ++foundVideos; // gifs are sent converted to videos\n        else if(mimeType.startsWith('image/')) ++foundPhotos;\n        else if(mimeType.startsWith('video/')) ++foundVideos;\n        else ++foundFiles;\n      });\n\n      if([foundPhotos, foundVideos, foundFiles].filter((n) => n > 0).length > 1) {\n        key = 'PreviewSender.SendFile';\n        args.push(files.length);\n      } else if(foundPhotos) {\n        key = 'PreviewSender.SendPhoto';\n        args.push(foundPhotos);\n      } else if(foundVideos) {\n        key = 'PreviewSender.SendVideo';\n        args.push(foundVideos);\n      } else {\n        key = 'PreviewSender.SendFile';\n        args.push(foundFiles);\n      }\n    }\n\n    replaceContent(title, i18n(key, args));\n  }\n\n  private currentFileSection: HTMLElement;\n\n  private appendMediaToContainer(params: SendFileParams) {\n    if(this.shouldCompress(params.file)) {\n      this.currentFileSection = undefined;\n\n      const size = calcImageInBox(params.width, params.height, MAX_WIDTH, 320);\n      params.itemDiv.style.width = size.width + 'px';\n      params.itemDiv.style.height = size.height + 'px';\n\n      this.mediaContainer.append(params.itemDiv);\n      return;\n    }\n\n    if(!this.currentFileSection) {\n      const items = document.createElement('div');\n      createRoot((dispose) => {\n        Section({\n          class: 'popup-send-photo-documents',\n          ref: (ref: HTMLDivElement) => {\n            this.currentFileSection = ref;\n          },\n          children: [items]\n        });\n\n        this.middlewareHelper.onDestroy(dispose);\n      });\n      this.mediaContainer.append(this.currentFileSection);\n      this.currentFileSection = items;\n    }\n\n    this.currentFileSection.append(params.itemDiv);\n  }\n\n  private hasGif() {\n    const {sendFileDetails} = this.willAttach;\n\n    return sendFileDetails.some((params) => params.isAnimated);\n  }\n\n  private canCheckIfHasGif() {\n    const {sendFileDetails} = this.willAttach;\n\n    return sendFileDetails.every((params) => !(params?.editResult?.getResult() instanceof Promise));\n  }\n\n  private iterate(cb: (sendFileDetails: SendFileParams[]) => void) {\n    const {sendFileDetails} = this.willAttach;\n\n    // * paid GIFs go out as plain videos, so they don't break the single paid album\n    if(!this.willAttach.group || (this.hasGif() && !this.willSendPaidMedia())) {\n      sendFileDetails.forEach((p) => cb([p]));\n      return;\n    }\n\n    const length = sendFileDetails.length;\n    for(let i = 0; i < length;) {\n      const firstFile = sendFileDetails[i].file;\n      let k = 0, isAudio: boolean;\n      for(; k < 10 && i < length; ++i, ++k) {\n        const file = sendFileDetails[i].file;\n        const _isAudio = AUDIO_MIME_TYPES_SUPPORTED.has(getFileMimeType(file) as any);\n        isAudio ??= _isAudio;\n        if(_isAudio !== isAudio || this.shouldCompress(firstFile) !== this.shouldCompress(file)) {\n          break;\n        }\n      }\n\n      cb(sendFileDetails.slice(i - k, i));\n    }\n  }\n\n  private attachFiles() {\n    const {files, willAttach, mediaContainer} = this;\n\n    const oldSendFileDetails = willAttach.sendFileDetails.splice(0, willAttach.sendFileDetails.length);\n\n    const getPendingEditResult = (file: File) => {\n      const pendingEditResult = this.pendingEditResults.get(file);\n      this.pendingEditResults.delete(file);\n      return pendingEditResult;\n    };\n\n    const promises = this.gifDocument ? [this.attachFile(this.gifDocument)] : files.map((file) => {\n      const oldParams = oldSendFileDetails.find((o) => o.file === file);\n      const editResult = oldParams?.editResult || getPendingEditResult(file);\n\n      return this.attachFile(\n        file,\n        editResult ? {\n          editResult\n        } : undefined\n      );\n    });\n\n    this.canShowActions = false;\n\n    Promise.all(promises).then(() => {\n      mediaContainer.replaceChildren();\n      // * destroy the old items only AFTER they've left the DOM — destroying at\n      // * the start of the re-render blanks the still-visible media out for the\n      // * whole rebuild (createVideo clears src on middleware destroy)\n      oldSendFileDetails.forEach((params) => {\n        params.middlewareHelper.destroy();\n      });\n      this.currentFileSection = undefined;\n      const filesLength = this.gifDocument ? 1 : files.length;\n      this.starsState.set({attachedFiles: filesLength, isGrouped: this.willAttach?.group && !this.hasGif()});\n\n      if(!filesLength) {\n        return;\n      }\n\n      this.setTitle();\n\n      this.iterate((sendFileDetails) => {\n        const shouldCompress = this.shouldCompress(sendFileDetails[0].file);\n        if(shouldCompress && sendFileDetails.length > 1) {\n          this.currentFileSection = undefined;\n          const albumContainer = document.createElement('div');\n          albumContainer.classList.add('popup-item-album', 'popup-item');\n          albumContainer.append(...sendFileDetails.map((s) => s.itemDiv));\n\n          prepareAlbum({\n            container: albumContainer,\n            items: sendFileDetails.map((o) => ({w: o.width, h: o.height})),\n            maxWidth: MAX_WIDTH,\n            minWidth: 100,\n            spacing: 2\n          });\n\n          mediaContainer.append(albumContainer);\n        } else {\n          sendFileDetails.forEach((params) => {\n            this.appendMediaToContainer(params);\n          });\n        }\n\n        if(!shouldCompress) {\n          return;\n        }\n\n        sendFileDetails.forEach((params) => {\n          const oldParams = oldSendFileDetails.find((o) => o.file === params.file);\n          if(oldParams?.mediaSpoiler || this.willSendPaidMedia()) {\n            this.applyMediaSpoiler(params, true);\n          }\n        });\n      });\n\n      const topLevelItems = mediaContainer.children;\n      for(let i = 1; i < topLevelItems.length; ++i) {\n        const prev = topLevelItems[i - 1];\n        const curr = topLevelItems[i];\n        if(prev.classList.contains('popup-item') && curr.classList.contains('popup-item')) {\n          curr.classList.add('popup-item-stacked');\n        }\n      }\n\n      this.setUnlockPlaceholders();\n    }).then(() => {\n      this.onRender();\n      this.onScroll();\n      doubleRaf().then(() => this.afterRender());\n    });\n  }\n\n  private isSuggestingPost() {\n    return !!this.chat?.input?.suggestedPost;\n  }\n\n  private isEditing() {\n    return !!this.chat?.input?.editMessage;\n  }\n\n  private isEditingMediaFromAlbum() {\n    return !!this.chat?.input?.editMessage?.grouped_id;\n  }\n\n  private canHaveMultipleFiles() {\n    return !this.ephemeralComposer &&\n      !this.isEditing() &&\n      !this.isSuggestingPost() &&\n      !this.gifDocument;\n  }\n\n  private canShowActionsForBcr(bcr: DOMRect) {\n    const scrollableBcr = this.scrollable.container.getBoundingClientRect();\n    const approximateCenterY = bcr.bottom - 20;\n\n    return approximateCenterY >= scrollableBcr.top && approximateCenterY <= scrollableBcr.bottom;\n  }\n\n  private afterRender() {\n    setTimeout(() => {\n      this.canShowActions = true;\n    }, 200);\n\n    this.willAttach.sendFileDetails.forEach((params) => {\n      const editResult = params.editResult;\n      if(editResult?.animatedPreview) {\n        const img = editResult.animatedPreview;\n        const bcr = img.getBoundingClientRect();\n        const left = bcr.left + bcr.width / 2, top = bcr.top + bcr.height / 2, width = bcr.width, height = bcr.height;\n        const targetBcr = params.itemDiv.getBoundingClientRect();\n        const leftDiff = (targetBcr.left + targetBcr.width / 2) - left;\n        const topDiff = (targetBcr.top + targetBcr.height / 2) - top;\n        animateValue(\n          0, 1, 200,\n          (progress) => {\n            img.style.transform = `translate(calc(${\n              progress * leftDiff\n            }px - 50%), calc(${\n              progress * topDiff\n            }px - 50%))`;\n            img.style.width = lerp(width, targetBcr.width, progress) + 'px';\n            img.style.height = lerp(height, targetBcr.height, progress) + 'px';\n          },\n          {\n            onEnd: () => {\n              img.remove();\n              editResult.animatedPreview = undefined;\n            }\n          }\n        )\n      }\n    });\n  }\n\n  protected destroy() {\n    super.destroy();\n    this.hideActiveActionsMenu();\n  }\n}\n\n(window as any).PopupNewMedia = PopupNewMedia;\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport showStickersPopup from '@components/popups/stickers';\nimport rootScope from '@lib/rootScope';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport PopupElement from '@components/popups';\nimport PopupNewMedia from '@components/popups/newMedia';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport ChatInput from '@components/chat/input';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {getEmojiFromElement} from '@components/emoticonsDropdown/tabs/emoji';\nimport tsNow from '@helpers/tsNow';\nimport {toastNew} from '@components/toast';\nimport {DocumentAttribute, EmojiStatus, InputStickerSet} from '@layer';\n\nexport default function createStickersContextMenu({\n  listenTo,\n  chatInput,\n  isPack,\n  verifyRecent,\n  appendTo,\n  isEmojis,\n  isGif,\n  canHaveEmojiTimer,\n  canViewPack,\n  onContextMenu,\n  onOpen,\n  onClose,\n  onSend\n}: {\n  listenTo: HTMLElement,\n  chatInput?: ChatInput,\n  isPack?: boolean,\n  verifyRecent?: (target: HTMLElement) => boolean,\n  appendTo?: HTMLElement,\n  isEmojis?: boolean,\n  isGif?: boolean,\n  canHaveEmojiTimer?: boolean,\n  canViewPack?: boolean,\n  onContextMenu?: (event: MouseEvent | TouchEvent) => {\n    cleanup: () => void,\n    onMenuOpen?: (menu: HTMLElement) => void\n  } | void,\n  onOpen?: () => any,\n  onClose?: () => any,\n  onSend?: () => any\n}) {\n  let target: HTMLElement, doc: MyDocument;\n  let contextMenuAddon: {\n    cleanup: () => void,\n    onMenuOpen?: (menu: HTMLElement) => void\n  };\n  const verifyFavoriteSticker = async(toAdd: boolean) => {\n    const favedStickers = await (isGif ? rootScope.managers.acknowledged.appGifsManager.getGifs() : rootScope.managers.acknowledged.appStickersManager.getFavedStickersStickers());\n    if(!favedStickers.cached) {\n      return false;\n    }\n\n    const found = (await favedStickers.result).some((_doc) => _doc.id === doc.id);\n    return toAdd ? !found : found;\n  };\n\n  const updateEmojiStatus = (emojiStatus: EmojiStatus) => {\n    rootScope.managers.appUsersManager.updateEmojiStatus(emojiStatus).then(() => {\n      toastNew({langPackKey: 'SetAsEmojiStatusInfo'});\n    });\n  };\n\n  const updateEmojiStatusUntil = async(duration: number) => {\n    updateEmojiStatus({\n      _: 'emojiStatus',\n      document_id: doc.id,\n      until: tsNow(true) + duration\n    });\n  };\n\n  let buttons: ButtonMenuItemOptionsVerifiable[] = isEmojis ? [{\n    icon: 'copy',\n    text: 'Copy',\n    onClick: () => {\n      if(doc) {\n        copyTextToClipboard(doc.stickerEmojiRaw, target.outerHTML);\n      } else {\n        copyTextToClipboard(getEmojiFromElement(target).emoji);\n      }\n    }\n  }, {\n    icon: 'stickers_face',\n    text: 'ViewPackPreview',\n    onClick: () => {\n      const attribute = doc.attributes.find((attr) => attr._ === 'documentAttributeCustomEmoji') as DocumentAttribute.documentAttributeCustomEmoji;\n      const inputStickerSet = attribute.stickerset as InputStickerSet.inputStickerSetID;\n      showStickersPopup(inputStickerSet, true, chatInput);\n    },\n    verify: () => !!(canViewPack && doc)\n  }, {\n    icon: 'smile',\n    text: 'SetAsEmojiStatus',\n    onClick: () => {\n      updateEmojiStatus({\n        _: 'emojiStatus',\n        document_id: doc.id\n      });\n    },\n    verify: () => !!(rootScope.premium && doc)\n  }, {\n    icon: 'delete',\n    text: 'DeleteFromRecent',\n    onClick: () => rootScope.managers.appEmojiManager.deleteRecentEmoji(getEmojiFromElement(target)),\n    verify: () => verifyRecent?.(target) ?? false\n  }] : [{\n    icon: 'stickers',\n    text: 'Context.ViewStickerSet',\n    onClick: () => showStickersPopup(doc.stickerSetInput, false, chatInput),\n    verify: () => !isPack && !isGif\n  }, {\n    icon: isGif ? 'gifs' : 'favourites',\n    text: isGif ? 'SaveToGIFs' : 'AddToFavorites',\n    onClick: () => isGif ? rootScope.managers.appGifsManager.saveGif(doc.id, false) : rootScope.managers.appStickersManager.faveSticker(doc.id, false),\n    verify: () => verifyFavoriteSticker(true)\n  }, {\n    icon: isGif ? 'crossgif' : 'crossstar',\n    text: isGif ? 'Message.Context.RemoveGif' : 'DeleteFromFavorites',\n    onClick: () => isGif ? rootScope.managers.appGifsManager.saveGif(doc.id, true) : rootScope.managers.appStickersManager.faveSticker(doc.id, true),\n    verify: () => verifyFavoriteSticker(false)\n  }, {\n    icon: 'delete',\n    text: 'DeleteFromRecent',\n    onClick: () => rootScope.managers.appStickersManager.saveRecentSticker(doc.id, true),\n    verify: () => verifyRecent?.(target) ?? false\n  }, {\n    icon: 'edit',\n    text: 'Chat.Send.WithCaption',\n    onClick: () => {\n      onSend?.();\n      PopupElement.createPopup(PopupNewMedia, chatInput.chat, [], 'media', false, doc);\n    },\n    verify: () => !!(isGif && chatInput && chatInput.chat.peerId)\n  }, {\n    icon: 'mute',\n    text: 'Chat.Send.WithoutSound',\n    onClick: () => {\n      onSend?.();\n      return chatInput.emoticonsDropdown.sendDocId({\n        document: doc.id,\n        clearDraft: false,\n        silent: true,\n        target\n      });\n    },\n    verify: () => !!(chatInput && chatInput.chat.peerId && chatInput.chat.peerId !== rootScope.myId)\n  }, {\n    icon: 'schedule',\n    text: 'Chat.Send.ScheduledMessage',\n    onClick: () => chatInput.scheduleSending(() => chatInput.sendMessageWithDocument({document: doc, target})),\n    verify: () => chatInput && !!chatInput.chat.peerId && !chatInput.chat.starsAmount\n  }];\n\n  if(canHaveEmojiTimer) buttons = [{\n    text: 'SetEmojiStatusUntil1Hour',\n    onClick: () => updateEmojiStatusUntil(3600),\n    verify: () => canHaveEmojiTimer\n  }, {\n    text: 'SetEmojiStatusUntil2Hours',\n    onClick: () => updateEmojiStatusUntil(3600 * 2),\n    verify: () => canHaveEmojiTimer\n  }, {\n    text: 'SetEmojiStatusUntil8Hours',\n    onClick: () => updateEmojiStatusUntil(3600 * 8),\n    verify: () => canHaveEmojiTimer\n  }, {\n    text: 'SetEmojiStatusUntil2Days',\n    onClick: () => updateEmojiStatusUntil(3600 * 24 * 2),\n    verify: () => canHaveEmojiTimer\n  }];\n\n  return createContextMenu({\n    listenTo: listenTo,\n    appendTo,\n    findElement: (e) => {\n      contextMenuAddon?.cleanup();\n      contextMenuAddon = onContextMenu?.(e) || undefined;\n      target = e.target as HTMLElement;\n      if(isEmojis) {\n        const superEmoji = findUpClassName(target, 'super-emoji');\n        if(superEmoji) {\n          target = superEmoji.firstElementChild as HTMLElement;\n        } else {\n          target = findUpClassName(target, 'emoji') || findUpClassName(target, 'custom-emoji');\n        }\n      } else if(isGif) {\n        target = findUpClassName(e.target, 'gif');\n      } else {\n        target = findUpClassName(e.target, 'media-sticker-wrapper');\n      }\n\n      return target;\n    },\n    onOpen: async() => {\n      doc = await rootScope.managers.appDocsManager.getDoc(target.dataset.docId);\n      return onOpen?.();\n    },\n    onClose: () => {\n      contextMenuAddon?.cleanup();\n      contextMenuAddon = undefined;\n      onClose?.();\n    },\n    onOpenAfter: (element) => {\n      contextMenuAddon?.onMenuOpen?.(element);\n    },\n    buttons\n  });\n}\n","import {JSX, createMemo, untrack, Show, createSignal, createRenderEffect} from 'solid-js';\n\n/**\n * Drop-in replacement for solid-js Show.\n * Uses 1 memo instead of 3, avoids chained subscriptions.\n * ~55x faster creation than the original Show.\n */\nexport default function MyShow<T>(props: {\n  when: T | undefined | null | false,\n  keyed?: boolean,\n  fallback?: JSX.Element,\n  children: JSX.Element | ((item: T | (() => T)) => JSX.Element)\n}): JSX.Element {\n  const [children, setChildren] = createSignal<JSX.Element>();\n  createRenderEffect(() => {\n    setChildren(props.when ? props.children : props.fallback as any);\n  });\n  return children as unknown as JSX.Element;\n  // const retMemo = createMemo(() => {\n  //   const w = props.when;\n  //   if(w) {\n  //     const child = props.children;\n  //     return child;\n  //     // return typeof(child) === 'function' && child.length > 0 ?\n  //     //   untrack(() => (child as Function)(props.keyed ? w : () => props.when)) :\n  //     //   child;\n  //   }\n  //   return props.fallback;\n  // }) as unknown as JSX.Element;\n  // return (\n  //   <>\n  //     {props.when ? props.children : props.fallback}\n  //   </>\n  // );\n  // const ret = (<Show {...props as any} />);\n  // untrack(() => {\n  //   console.warn('myshow', (ret as any)(), (retMemo as any)());\n  // });\n}\n","import type {AppStickersManager} from '@appManagers/appStickersManager';\nimport type ChatInput from '@components/chat/input';\nimport PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\nimport wrapSticker from '@components/wrappers/sticker';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {putPreloader} from '@components/putPreloader';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport appImManager from '@lib/appImManager';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {i18n} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {toastNew} from '@components/toast';\nimport createStickersContextMenu from '@helpers/dom/createStickersContextMenu';\nimport attachStickerViewerListeners from '@components/stickerViewer';\nimport {Document, StickerSet} from '@layer';\nimport RowTsx from '@components/rowTsx';\nimport rootScope from '@lib/rootScope';\nimport wrapCustomEmoji from '@components/wrappers/customEmoji';\nimport emoticonsDropdown from '@components/emoticonsDropdown';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport {onMediaCaptionClick} from '@components/mediaViewer';\nimport DEBUG from '@config/debug';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport pause from '@helpers/schedulers/pause';\nimport toArray from '@helpers/array/toArray';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {createSignal, JSX, onCleanup, onMount, Show, untrack, useContext} from 'solid-js';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport MyShow from '@helpers/solid/myShow';\nimport Button from '@components/button';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\n\nconst ANIMATION_GROUP: AnimationItemGroup = 'STICKERS-POPUP';\nexport const STICKERS_POPUP_KIND = Symbol('stickers-popup');\n\nconst TEST_LOADING_DELAY = 0;\n\nexport default function showStickersPopup(\n  stickerSetInput: Parameters<AppStickersManager['getStickerSet']>[0] | Parameters<AppStickersManager['getStickerSet']>[0][],\n  isEmojisInitial?: boolean,\n  chatInput: ChatInput = appImManager.chat?.input\n) {\n  const [show, setShow] = createSignal(true);\n\n  const handle = {\n    hide: () => setShow(false)\n  };\n\n  let isEmojis = isEmojisInitial;\n  let sets: StickerSet.stickerSet[] = [];\n  const updateAddedMap: {[setId: Long]: (added: boolean) => void} = {};\n  const deferredCloseCallbacks: (() => void)[] = [];\n  let containerEl!: HTMLDivElement;\n\n  function Inner() {\n    const context = useContext(PopupContext);\n    const middleware = untrack(() => context.middlewareHelper).get();\n    const managers = untrack(() => context.managers);\n    const listenerSetter = new ListenerSetter();\n\n    let scrollableEl!: HTMLDivElement;\n\n    const [titleContent, setTitleContent] = createSignal<JSX.Element>(i18n('Loading'));\n    const [menuEl, setMenuEl] = createSignal<HTMLElement>();\n    const [isLoaded, setIsLoaded] = createSignal(false);\n    const [isAdd, setIsAdd] = createSignal(false);\n    const [buttonText, setButtonText] = createSignal<JSX.Element>();\n    const [containers, setContainers] = createSignal<JSX.Element>();\n\n    let rawSetsRef: Awaited<ReturnType<AppStickersManager['getStickerSet']>>[];\n\n    emoticonsDropdown.setIgnoreMouseOut('popup', true);\n\n    onCleanup(() => {\n      emoticonsDropdown.setIgnoreMouseOut('popup', false);\n      animationIntersector.setOnlyOnePlayableGroup();\n      listenerSetter.removeAll();\n    });\n\n    const updateButton = () => {\n      let buttonAppend: HTMLElement;\n      let add: boolean;\n      if(sets.length === 1) {\n        const firstSet = sets[0];\n        buttonAppend = i18n(isEmojis ? 'EmojiCount' : 'Stickers', [firstSet.count]);\n        add = !firstSet.installed_date;\n      } else {\n        const installed = sets.filter((set) => set.installed_date);\n        let count: number;\n        if(sets.length === installed.length) {\n          add = false;\n          count = sets.length;\n        } else {\n          add = true;\n          count = sets.length - installed.length;\n        }\n        buttonAppend = i18n('EmojiPackCount', [count]);\n      }\n\n      setIsAdd(add);\n      setButtonText(i18n(add ? 'AddStickersCount' : 'RemoveStickersCount', [buttonAppend]));\n    };\n\n    const onStickerSetUpdate = (set: StickerSet.stickerSet) => {\n      const idx = sets.findIndex((s) => s.id === set.id);\n      if(idx === -1) return;\n      sets[idx] = set;\n      updateAddedMap[set.id]?.(!!set.installed_date);\n      updateButton();\n    };\n\n    subscribeOn(rootScope)('stickers_installed', onStickerSetUpdate);\n    subscribeOn(rootScope)('stickers_deleted', onStickerSetUpdate);\n\n    const createStickerSetElements = (set?: StickerSet.stickerSet) => {\n      const container = document.createElement('div');\n      container.classList.add('sticker-set');\n\n      let headerRow: {container: HTMLElement, buttonRight: HTMLElement};\n      let setUpdateAdded: (added: boolean) => void;\n      if(set) {\n        const buttonRight = Button('btn-primary btn-color-primary btn-control-small');\n        const row = wrapSolidComponent(() => (\n          <RowTsx>\n            <RowTsx.Title>{wrapRichText(set.title)}</RowTsx.Title>\n            <RowTsx.Subtitle>\n              {i18n(set.pFlags.emojis ? 'EmojiCount' : 'Stickers', [set.count])}\n            </RowTsx.Subtitle>\n            <RowTsx.RightContent element={buttonRight} />\n          </RowTsx>\n        ), middleware);\n        headerRow = {container: row, buttonRight};\n\n        setUpdateAdded = (added) => {\n          headerRow.buttonRight.replaceChildren(i18n(added ? 'Stickers.SearchAdded' : 'Stickers.SearchAdd'));\n          headerRow.buttonRight.classList.toggle('active', added);\n        };\n\n        setUpdateAdded(!!set.installed_date);\n        container.append(headerRow.container);\n      }\n\n      const itemsContainer = document.createElement('div');\n      itemsContainer.classList.add('sticker-set-stickers');\n      container.append(itemsContainer);\n\n      return {container, headerRow, updateAdded: setUpdateAdded, itemsContainer};\n    };\n\n    const onStickersClick = async(e: MouseEvent) => {\n      if(!chatInput.chat.peerId) return;\n\n      const target = findUpClassName(e.target, 'sticker-set-sticker') || findUpClassName(e.target, 'custom-emoji');\n      if(!target) return;\n\n      const docId = target.dataset.docId;\n      let emoji: {docId: DocId, emoji: string};\n      if(isEmojis) {\n        emoji = {docId, emoji: target.dataset.stickerEmoji};\n        if(!chatInput.emoticonsDropdown.canUseEmoji(emoji, true)) return;\n      }\n\n      const shouldHide = isEmojis ?\n        chatInput.onEmojiSelected(emoji, false) :\n        await appImManager.chat.input.sendMessageWithDocument({document: docId, target});\n      if(shouldHide) handle.hide();\n    };\n\n    const loadStickerSet = async() => {\n      const inputs = toArray(stickerSetInput);\n      const setsPromises = inputs.map((input) => managers.appStickersManager.getStickerSet(input));\n      let rawSets = await Promise.all(setsPromises);\n      if(!middleware()) return;\n      let firstSet = rawSets[0];\n      if(rawSets.length === 1 && !firstSet) {\n        toastNew({langPackKey: isEmojis ? 'AddEmojiNotFound' : 'StickerSet.DontExist'});\n        handle.hide();\n        return;\n      }\n\n      rawSets = rawSets.filter(Boolean);\n      firstSet = rawSets[0];\n      sets = rawSets.map((set) => set.set);\n      rawSetsRef = rawSets;\n\n      isEmojis ??= !!firstSet.set.pFlags.emojis;\n\n      attachClickEvent(scrollableEl, onStickersClick, {listenerSetter});\n\n      const {destroy} = createStickersContextMenu({\n        listenTo: scrollableEl,\n        chatInput,\n        isPack: true,\n        isEmojis,\n        onSend: () => handle.hide()\n      });\n      middleware.onClean(destroy);\n\n      animationIntersector.setOnlyOnePlayableGroup(ANIMATION_GROUP);\n\n      const lazyLoadQueue = new LazyLoadQueue();\n      const loadPromises: Promise<any>[] = [];\n\n      const containersPromises = rawSets.map(async(set) => {\n        const {container, itemsContainer, headerRow, updateAdded: setUpdateAdded} =\n          createStickerSetElements(rawSets.length > 1 ? set.set : undefined);\n\n        if(headerRow) {\n          attachClickEvent(headerRow.buttonRight, () => {\n            managers.appStickersManager.toggleStickerSet(set.set);\n          }, {listenerSetter});\n        }\n\n        updateAddedMap[set.set.id] = setUpdateAdded;\n\n        let divs: (HTMLElement | DocumentFragment)[];\n        const docs = set.documents.filter((doc) => doc?._ === 'document') as Document.document[];\n        if(isEmojis) {\n          const fragment = wrapCustomEmoji({\n            docIds: docs.map((doc) => doc.id),\n            loadPromises,\n            animationGroup: ANIMATION_GROUP,\n            customEmojiSize: mediaSizes.active.esgCustomEmoji,\n            middleware\n          });\n\n          (Array.from(fragment.children) as HTMLElement[]).slice(1).forEach((element) => {\n            const span = document.createElement('span');\n            span.classList.add('super-emoji', 'super-emoji-custom');\n            element.replaceWith(span);\n            span.append(element);\n          });\n\n          divs = [fragment];\n          itemsContainer.classList.replace('sticker-set-stickers', 'super-emojis');\n          itemsContainer.classList.add('is-emojis');\n        } else {\n          divs = await Promise.all(docs.map(async(doc) => {\n            const div = document.createElement('div');\n            div.classList.add('sticker-set-sticker');\n            const size = mediaSizes.active.popupSticker.width;\n            await wrapSticker({\n              doc,\n              div,\n              lazyLoadQueue,\n              group: ANIMATION_GROUP,\n              play: true,\n              loop: true,\n              width: size,\n              height: size,\n              withLock: true,\n              loadPromises,\n              middleware\n            });\n            return div;\n          }));\n        }\n\n        itemsContainer.append(...divs.filter(Boolean));\n        return container;\n      });\n\n      const containers = await Promise.all(containersPromises);\n      await Promise.all(loadPromises);\n      if(!middleware()) return;\n\n      const title = rawSets.length === 1 ?\n        wrapRichText(firstSet.set.title) :\n        i18n('Emoji');\n\n      updateButton();\n\n      const buttons: ButtonMenuItemOptionsVerifiable[] = [{\n        icon: 'copy',\n        text: 'CopyLink',\n        onClick: () => {\n          const prefix = `https://t.me/${isEmojis ? 'addemoji' : 'addstickers'}/`;\n          const text = rawSets.map((set) => prefix + set.set.short_name).join('\\n');\n          copyTextToClipboard(text);\n        }\n      }];\n\n      if(DEBUG) {\n        buttons.push({\n          icon: 'download',\n          text: 'MediaViewer.Context.Download',\n          onClick: async() => {\n            for(const set of rawSets) {\n              for(const doc of set.documents) {\n                appDownloadManager.downloadToDisc({media: doc as Document.document});\n                await pause(100);\n              }\n            }\n          }\n        });\n      }\n\n      const buttonMenu = ButtonMenuToggle({\n        listenerSetter,\n        buttons,\n        direction: 'bottom-left'\n      });\n\n      const onReady = () => {\n        setTitleContent(title);\n        setMenuEl(buttonMenu);\n        setIsLoaded(true);\n        setContainers(containers);\n      };\n\n      setTimeout(onReady, TEST_LOADING_DELAY);\n    };\n\n    onMount(() => {\n      attachStickerViewerListeners({listenTo: scrollableEl, listenerSetter});\n\n      const onContainerClick = (e: MouseEvent) => {\n        const callback = onMediaCaptionClick(containerEl, e);\n        if(callback) {\n          deferredCloseCallbacks.push(callback);\n          handle.hide();\n          return false;\n        }\n      };\n\n      containerEl.addEventListener('click', onContainerClick, {capture: true});\n      middleware.onDestroy(() => {\n        containerEl.removeEventListener('click', onContainerClick, {capture: true});\n      });\n\n      loadStickerSet();\n    });\n\n    return (\n      <>\n        <PopupElement.Header>\n          <PopupElement.CloseButton />\n          <PopupElement.Title>{titleContent()}</PopupElement.Title>\n          {menuEl()}\n        </PopupElement.Header>\n        <PopupElement.Body>\n          <PopupElement.Scrollable\n            ref={scrollableEl}\n            class={!isLoaded() && 'is-loading'}\n            withBorders=\"top\"\n          >\n            <Show when={isLoaded()} fallback={putPreloader(undefined, true)}>\n              {containers()}\n            </Show>\n          </PopupElement.Scrollable>\n        </PopupElement.Body>\n        <PopupElement.Footer floating={isLoaded()}>\n          <PopupElement.FooterButton\n            noRipple\n            color={isLoaded() ? (isAdd() ? 'primary' : 'danger') : 'secondary'}\n            callback={async() => {\n              await managers.appStickersManager.toggleStickerSets(\n                rawSetsRef.map((set) => set.set)\n              );\n            }}\n            disabled={!isLoaded()}\n          >\n            <MyShow when={isLoaded()} fallback={i18n('Loading')}>\n              {buttonText()}\n            </MyShow>\n          </PopupElement.FooterButton>\n        </PopupElement.Footer>\n      </>\n    );\n  }\n\n  createPopup(() => (\n    <PopupElement\n      class=\"popup-stickers\"\n      closable\n      show={show()}\n      kind={STICKERS_POPUP_KIND}\n      animationGroup={ANIMATION_GROUP}\n      containerProps={{ref: (el) => containerEl = el}}\n      onCloseAfterTimeout={() => {\n        deferredCloseCallbacks.splice(0).forEach((cb) => cb());\n      }}\n      old\n    >\n      <Inner />\n    </PopupElement>\n  ));\n}\n","import {makeMediaSize, MediaSize} from '@helpers/mediaSize';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {MiddlewareHelper, Middleware, getMiddleware} from '@helpers/middleware';\nimport {StickerSet} from '@layer';\nimport ButtonIcon from '@components/buttonIcon';\nimport {ScrollableX} from '@components/scrollable';\nimport {EMOJI_ELEMENT_SIZE} from '@components/emoticonsDropdown/tabs/emoji';\n\nexport type StickersTabCategoryItem = {element: HTMLElement};\nexport type StickersTabStyles = {\n  padding: number,\n  gapX: number,\n  gapY: number,\n  getElementMediaSize: () => MediaSize,\n  itemsClassName: string\n};\n\nexport const EmoticonsTabStyles: {[key in 'Stickers' | 'Emoji' | 'GIF']?: StickersTabStyles} = {\n  Stickers: {\n    getElementMediaSize: () => mediaSizes.active.esgSticker,\n    padding: 3 * 2,\n    gapX: 4,\n    gapY: 4,\n    itemsClassName: 'super-stickers'\n  },\n  Emoji: {\n    getElementMediaSize: () => EMOJI_ELEMENT_SIZE,\n    padding: 16,\n    gapX: 4,\n    gapY: 0,\n    itemsClassName: 'super-emojis'\n  },\n  GIF: {\n    getElementMediaSize: () => makeMediaSize(124, 124),\n    padding: 4,\n    gapX: 2,\n    gapY: 2,\n    itemsClassName: 'emoticons-gifs'\n  }\n}\n\nexport default class StickersTabCategory<Item extends StickersTabCategoryItem, AdditionalElements extends Record<string, HTMLElement> = {}> {\n  public elements: {\n    container: HTMLElement,\n    title: HTMLElement,\n    items: HTMLElement,\n    menuTab: HTMLElement,\n    menuTabPadding: HTMLElement\n  } & AdditionalElements;\n  public items: Item[];\n  public mounted: boolean;\n  public id: string;\n  public limit: number;\n\n  public getContainerSize: () => {width: number, height: number};\n  private getElementMediaSize: () => MediaSize;\n\n  private gapX: number;\n  private gapY: number;\n\n  public set?: StickerSet;\n  public local?: boolean;\n  public menuScroll?: ScrollableX;\n\n  public middlewareHelper: MiddlewareHelper;\n\n  constructor(options: {\n    id: string,\n    title: HTMLElement | DocumentFragment,\n    overflowElement: HTMLElement,\n    styles: StickersTabStyles,\n    getContainerSize: StickersTabCategory<Item>['getContainerSize'],\n    noMenuTab?: boolean,\n    middleware?: Middleware\n  }) {\n    const container = document.createElement('div');\n    container.classList.add('emoji-category');\n\n    const items = document.createElement('div');\n    items.classList.add('category-items');\n\n    let title: HTMLElement;\n    if(options.title) {\n      title = document.createElement('div');\n      title.classList.add('category-title');\n      title.append(options.title);\n    }\n\n    let menuTab: HTMLElement, menuTabPadding: HTMLElement;\n    if(!options.noMenuTab) {\n      menuTab = ButtonIcon(undefined, {noRipple: true});\n      menuTab.classList.add('menu-horizontal-div-item');\n\n      menuTabPadding = document.createElement('div');\n      menuTabPadding.classList.add('menu-horizontal-div-item-padding');\n\n      menuTab.append(menuTabPadding);\n    }\n\n    if(title) container.append(title);\n    container.append(items);\n\n    this.elements = {\n      container,\n      title,\n      items,\n      menuTab,\n      menuTabPadding\n    } as any;\n    this.id = options.id;\n    this.items = [];\n\n    this.getContainerSize = options.getContainerSize;\n    this.getElementMediaSize = options.styles.getElementMediaSize;\n    this.gapX = options.styles.gapX ?? 0;\n    this.gapY = options.styles.gapY ?? 0;\n    this.middlewareHelper = options.middleware ? options.middleware.create() : getMiddleware();\n  }\n\n  public setCategoryItemsHeight(itemsLength = this.items.length) {\n    const {width: containerWidth} = this.getContainerSize();\n    const elementSize = this.getElementMediaSize().width;\n\n    let itemsPerRow = containerWidth / elementSize;\n    if(this.gapX) itemsPerRow -= Math.floor(itemsPerRow - 1) * this.gapX / elementSize;\n    itemsPerRow = Math.floor(itemsPerRow);\n\n    const rows = Math.ceil(itemsLength / itemsPerRow);\n    let height = rows * elementSize;\n    if(this.gapY) height += (rows - 1) * this.gapY;\n\n    this.elements.items.style.minHeight = height + 'px';\n  }\n}\n","import {Accessor, createEffect, createSignal, onCleanup, For, on} from 'solid-js';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport fastSmoothScroll, {fastSmoothScrollToStart} from '@helpers/fastSmoothScroll';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {EmojiGroup} from '@layer';\nimport {AppEmojiManager} from '@appManagers/appEmojiManager';\nimport {LangPackKey} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport InputSearch from '@components/inputSearch';\nimport Scrollable from '@components/scrollable2';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {AnimationItemGroup} from '@components/animationIntersector';\n\n/* @refresh reload */\n\nfunction addSearchCategories(props: {\n  type: Parameters<typeof EmoticonsSearch>[0]['type'],\n  searching: Accessor<boolean>,\n  inputSearch: InputSearch,\n  onGroup: (group: EmojiGroup) => void,\n  animatedItemGroup?: AnimationItemGroup,\n  color?: WrapSomethingOptions['textColor']\n}) {\n  const {inputSearch} = props;\n  const [emojiGroups, setEmojiGroups] = createSignal<Awaited<ReturnType<AppEmojiManager['getEmojiGroups']>>>([]);\n  const [selected, setSelected] = createSignal<EmojiGroup>();\n  const [scrolled, setScrolled] = createSignal(false);\n\n  const onEmojiGroupClick = (group: EmojiGroup, e: MouseEvent) => {\n    setSelected(group);\n    fastSmoothScroll({\n      container: scrollableContainer,\n      element: e.target as HTMLElement,\n      position: 'center',\n      axis: 'x'\n    });\n  };\n\n  const EmojiGroup = ({group, document}: ReturnType<typeof emojiGroups>[0]) => {\n    if(props.type !== 'stickers' && group._ === 'emojiGroupPremium') {\n      return;\n    }\n\n    let element: HTMLDivElement, stickerContainer: HTMLDivElement;\n    const ret = (\n      <div\n        ref={element}\n        class=\"emoticons-search-input-category\"\n        classList={{active: selected() === group}}\n        title={group.title}\n        onClick={[onEmojiGroupClick, group]}\n      >\n        <div ref={stickerContainer} class=\"emoticons-search-input-category-sticker\"></div>\n      </div>\n    );\n\n    wrapSticker({\n      doc: document,\n      div: stickerContainer,\n      width: 24,\n      height: 24,\n      group: props.animatedItemGroup,\n      play: true,\n      middleware: createMiddleware().get(),\n      textColor: props.color\n    });\n\n    return ret;\n  };\n\n  let scrollableContainer: HTMLDivElement;\n  const scrollable = (\n    <Scrollable\n      axis=\"x\"\n      ref={(el) => {\n        scrollableContainer = el;\n        el.addEventListener('click', (e) => {\n          if(e.target === inputSearch.currentPlaceholder) {\n            placeCaretAtEnd(inputSearch.input, true, true);\n          }\n        });\n      }}\n      class=\"emoticons-search-input-scrollable\"\n      classList={{'is-searching': props.searching(), 'is-scrolled': scrolled()}}\n      onScroll={() => {\n        setScrolled(scrollableContainer.scrollLeft > 0);\n      }}\n    >\n      {inputSearch.currentPlaceholder}\n      <div class=\"emoticons-search-input-categories\">\n        <For each={emojiGroups()}>{EmojiGroup}</For>\n      </div>\n    </Scrollable>\n  );\n\n  inputSearch.input.after(scrollableContainer);\n\n  inputSearch.currentPlaceholder.classList.remove('will-animate');\n\n  const arrowButton = inputSearch.createButtonIcon('arrow_prev', 'will-animate', 'emoticons-search-input-arrow');\n  inputSearch.searchIcon.classList.add('will-animate');\n  inputSearch.searchIcon.after(arrowButton);\n\n  const detachClickEvent = attachClickEvent(arrowButton, () => {\n    setSelected();\n  });\n\n  onCleanup(detachClickEvent);\n\n  createEffect(() => {\n    arrowButton.classList.toggle('is-hiding', !selected());\n    inputSearch.searchIcon.classList.toggle('is-hiding', !!selected());\n  });\n\n  createEffect(() => {\n    if(props.searching()) {\n      setSelected();\n    }\n  });\n\n  createEffect(on(selected, (selected) => {\n    props.onGroup(selected);\n    if(!selected) {\n      fastSmoothScrollToStart(scrollableContainer, 'x');\n    }\n  }, {defer: true}));\n\n  rootScope.managers.appEmojiManager.getEmojiGroups(props.type === 'stickers' ? 'stickers' : 'esg').then(setEmojiGroups);\n}\n\nexport default function EmoticonsSearch(props: {\n  type: 'emoji' | 'stickers' | 'gifs'\n  placeholder?: LangPackKey,\n  // * defaults to 0 - local searches (emoji, stickers) can run on every keystroke,\n  // * server-backed ones must not or the API floods the client out\n  debounceTime?: number,\n  // * return false to answer a value right away, e.g. one the tab already has results for\n  verifyDebounce?: ConstructorParameters<typeof InputSearch>[0]['verifyDebounce'],\n  loading?: Accessor<boolean>,\n  onValue: (value: string) => void,\n  onFocusChange?: ConstructorParameters<typeof InputSearch>[0]['onFocusChange'],\n  onGroup?: (group: EmojiGroup) => void,\n  animatedItemGroup?: AnimationItemGroup,\n  categoryColor?: WrapSomethingOptions['textColor']\n}) {\n  const [searching, setSearching] = createSignal(false);\n  const [debounced, setDebounced] = createSignal(false);\n  const inputSearch = new InputSearch({\n    placeholder: props.placeholder || 'Search',\n    onChange: (value) => {\n      value = value.trim();\n      setSearching(!!value);\n      props.onValue(value);\n    },\n    onFocusChange: props.onFocusChange,\n    onDebounce: setDebounced,\n    noBorder: true,\n    noFocusEffect: true,\n    debounceTime: props.debounceTime ?? 0,\n    verifyDebounce: props.verifyDebounce\n  });\n  inputSearch.container.classList.add('emoticons-search-input-container');\n  inputSearch.input.classList.add('emoticons-search-input');\n\n  onCleanup(() => {\n    inputSearch.remove();\n  });\n\n  if(props.loading) {\n    createEffect(() => {\n      inputSearch.toggleLoading(debounced() || props.loading());\n    });\n  }\n\n  if(props.onGroup) {\n    addSearchCategories({\n      type: props.type,\n      searching,\n      inputSearch,\n      onGroup: props.onGroup,\n      animatedItemGroup: props.animatedItemGroup,\n      color: props.categoryColor\n    });\n  }\n\n  return (\n    <>\n      {inputSearch.container}\n    </>\n  );\n}\n","import createVideo from '@helpers/dom/createVideo';\nimport renderImageFromUrl from '@helpers/dom/renderImageFromUrl';\nimport {Document, DocumentAttribute, StickerSet} from '@layer';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport {AppManagers} from '@lib/managers';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {Middleware} from '@helpers/middleware';\nimport {EMOJI_TEXT_COLOR} from '@components/emoticonsDropdown';\nimport {getStickerSetInputById} from '@lib/appManagers/utils/stickers/getStickerSetInput';\nimport {createObjectURL, revokeObjectURL} from '@helpers/objectUrl';\nimport clearMediaElementSource from '@helpers/dom/clearMediaElementSource';\n\nexport default async function wrapStickerSetThumb({set, lazyLoadQueue, container, group, autoplay, width, height, managers = rootScope.managers, middleware, textColor}: {\n  set: StickerSet.stickerSet,\n  lazyLoadQueue: LazyLoadQueue,\n  container: HTMLElement,\n  group: AnimationItemGroup,\n  autoplay: boolean,\n  width: number,\n  height: number,\n  managers?: AppManagers\n  middleware: Middleware,\n  textColor?: WrapSomethingOptions['textColor']\n}) {\n  if(set.thumbs?.length) {\n    container.classList.add('media-sticker-wrapper');\n    lazyLoadQueue.push({\n      div: container,\n      middleware,\n      load: async() => {\n        const downloadOptions = await managers.appStickersManager.getStickerSetThumbDownloadOptions(set);\n        const promise = appDownloadManager.download(downloadOptions);\n\n        const isLottie = downloadOptions.mimeType === 'application/x-tgsticker';\n        if(isLottie) {\n          return promise.then((blob) => {\n            lottieLoader.loadAnimationWorker({\n              container,\n              loop: true,\n              autoplay,\n              animationData: blob,\n              width,\n              height,\n              needUpscale: true,\n              name: 'setThumb' + set.id,\n              group,\n              middleware\n            });\n          });\n        } else {\n          const isVideo = set.thumbs?.some((thumb) => thumb.type === 'v');\n          let media: HTMLElement;\n          if(isVideo) {\n            media = createVideo({middleware});\n            (media as HTMLVideoElement).autoplay = true;\n            (media as HTMLVideoElement).muted = true;\n            (media as HTMLVideoElement).loop = true;\n          } else {\n            media = new Image();\n          }\n\n          media.classList.add('media-sticker');\n\n          return promise.then((blob) => {\n            if(!middleware()) {\n              return;\n            }\n\n            const url = createObjectURL(blob);\n            middleware.onClean(() => {\n              clearMediaElementSource(media as HTMLImageElement | HTMLMediaElement);\n              revokeObjectURL(url);\n            });\n            renderImageFromUrl(media, url, () => {\n              if(!middleware()) {\n                return;\n              }\n\n              container.append(media);\n\n              if(isVideo) {\n                animationIntersector.addAnimation({\n                  animation: media as HTMLVideoElement,\n                  controlled: middleware,\n                  group,\n                  observeElement: media,\n                  type: 'video'\n                });\n              }\n            });\n          });\n        }\n      }\n    });\n\n    return;\n  }\n\n  let getDocPromise: Promise<Document.document>;\n\n  if(set.thumb_document_id) {\n    getDocPromise = managers.appEmojiManager.getCustomEmojiDocument(set.thumb_document_id);\n  } else {\n    getDocPromise = managers.appStickersManager.getStickerSet(getStickerSetInputById(set)).then((stickerSet) => stickerSet.documents[0] as Document.document);\n  }\n\n  const doc = await getDocPromise;\n  if(!doc) {\n    return;\n  }\n\n  const attribute = doc.attributes.find((a) => a._ === 'documentAttributeCustomEmoji') as DocumentAttribute.documentAttributeCustomEmoji\n  // as thumb will be used first sticker\n  wrapSticker({\n    doc,\n    div: container,\n    group: group,\n    lazyLoadQueue,\n    managers,\n    width,\n    height,\n    middleware,\n    textColor: attribute?.pFlags?.text_color ? textColor || EMOJI_TEXT_COLOR : undefined\n  }); // kostil\n}\n","import {EmoticonsTab, EmoticonsDropdown, EMOTICONSSTICKERGROUP, EMOJI_TEXT_COLOR} from '.';\nimport createStickersContextMenu from '@helpers/dom/createStickersContextMenu';\nimport customProperties from '@helpers/dom/customProperties';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport {IgnoreMouseOutType} from '@helpers/dropdownHover';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {MiddlewareHelper, getMiddleware, Middleware} from '@helpers/middleware';\nimport safeAssign from '@helpers/object/safeAssign';\nimport Animated from '@helpers/solid/animations';\nimport windowSize from '@helpers/windowSize';\nimport {EmojiGroup, StickerSet} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {AnyFunction} from '@types';\nimport {createSignal, createMemo, createResource, createEffect, untrack} from 'solid-js';\nimport {render, Portal} from 'solid-js/web';\nimport Icon from '@components/icon';\nimport Scrollable, {ScrollableX} from '@components/scrollable';\nimport attachStickerViewerListeners from '@components/stickerViewer';\nimport VisibilityIntersector from '@components/visibilityIntersector';\nimport StickersTabCategory, {EmoticonsTabStyles, StickersTabStyles} from '@components/emoticonsDropdown/category';\nimport EmoticonsSearch from '@components/emoticonsDropdown/search';\nimport wrapStickerSetThumb from '@components/wrappers/stickerSetThumb';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\n\nexport default class EmoticonsTabC<Category extends StickersTabCategory<any, any>, T = any> implements EmoticonsTab {\n  public content: HTMLElement;\n  public menuScroll: ScrollableX;\n  public container: HTMLElement;\n  public menuWrapper: HTMLElement;\n  public menu: HTMLElement;\n  public emoticonsDropdown: EmoticonsDropdown;\n\n  protected categories: {[id: string]: Category};\n  protected categoriesMap: Map<HTMLElement, Category>;\n  protected categoriesByMenuTabMap: Map<HTMLElement, Category>;\n  protected categoriesIntersector: VisibilityIntersector;\n  protected categoriesContainer: HTMLElement;\n  protected localCategories: Category[];\n\n  protected listenerSetter: ListenerSetter;\n\n  public scrollable: Scrollable;\n  protected mounted = false;\n  protected menuOnClickResult: ReturnType<typeof EmoticonsDropdown['menuOnClick']>;\n\n  public tabId: number;\n\n  protected postponedEvents: {cb: AnyFunction, args: any[]}[];\n\n  public getContainerSize: Category['getContainerSize'];\n\n  public middlewareHelper: MiddlewareHelper;\n  private disposeSearch: () => void;\n\n  public managers: AppManagers;\n  protected noMenu: boolean;\n  protected additionalStickerViewerClass: string;\n  // * returning the results directly (not a promise) renders them without a repaint gap\n  protected searchFetcher?: (value: string) => MaybePromise<T>;\n  protected groupFetcher?: (group: EmojiGroup) => MaybePromise<T>;\n  protected processSearchResult?: (result: {data: T, searching: boolean, grouping: boolean}) => Promise<HTMLElement>;\n  protected searchNoLoader: boolean;\n  protected searchPlaceholder?: LangPackKey;\n  protected searchType: Parameters<typeof EmoticonsSearch>[0]['type'];\n  protected searchDebounceTime?: number;\n  protected searchVerifyDebounce?: Parameters<typeof EmoticonsSearch>[0]['verifyDebounce'];\n\n  constructor(options: {\n    managers: AppManagers,\n    noMenu?: boolean,\n    additionalStickerViewerClass?: string,\n    searchFetcher?: EmoticonsTabC<Category, T>['searchFetcher'],\n    groupFetcher?: EmoticonsTabC<Category, T>['groupFetcher'],\n    processSearchResult?: EmoticonsTabC<Category, T>['processSearchResult'],\n    searchNoLoader?: boolean,\n    searchPlaceholder?: LangPackKey,\n    searchType?: Parameters<typeof EmoticonsSearch>[0]['type'],\n    searchDebounceTime?: number,\n    searchVerifyDebounce?: EmoticonsTabC<Category, T>['searchVerifyDebounce']\n  }) {\n    safeAssign(this, options);\n    this.categories = {};\n    this.categoriesMap = new Map();\n    this.categoriesByMenuTabMap = new Map();\n    this.localCategories = [];\n    this.postponedEvents = [];\n\n    this.listenerSetter = new ListenerSetter();\n    this.middlewareHelper = getMiddleware();\n\n    this.container = document.createElement('div');\n    this.container.classList.add('tabs-tab', 'emoticons-container');\n\n    if(this.noMenu) {\n      this.container.classList.add('no-menu');\n    } else {\n      this.createMenu();\n    }\n\n    this.content = document.createElement('div');\n    this.content.classList.add('emoticons-content');\n\n    this.container.append(...[this.menuWrapper, this.content].filter(Boolean));\n\n    this.scrollable = new Scrollable(this.content, 'STICKERS');\n\n    this.categoriesContainer = document.createElement('div');\n    this.categoriesContainer.classList.add('emoticons-categories-container');\n\n    if(!this.noMenu) {\n      this.scrollable.container.classList.add('emoticons-will-move-up');\n      this.categoriesContainer.classList.add('emoticons-will-move-down');\n    }\n\n    if(options.searchFetcher) {\n      this.createSearch();\n    } else {\n      this.scrollable.append(this.categoriesContainer);\n    }\n  }\n\n  public textColor = () => {\n    return this.emoticonsDropdown?.textColor?.() || EMOJI_TEXT_COLOR;\n  };\n\n  private createMenu() {\n    this.menuWrapper = document.createElement('div');\n    this.menuWrapper.classList.add('menu-wrapper', 'emoticons-menu-wrapper', 'emoticons-will-move-up');\n\n    this.menu = document.createElement('nav');\n    this.menu.className = 'menu-horizontal-div no-stripe justify-start emoticons-menu';\n\n    this.menuWrapper.append(this.menu);\n    this.menuScroll = new ScrollableX(this.menuWrapper);\n  }\n\n  private createSearch() {\n    const searchContainer = document.createElement('div');\n    searchContainer.classList.add('emoticons-search-container');\n    if(!this.noMenu) searchContainer.classList.add('emoticons-will-move-down');\n    this.scrollable.append(searchContainer);\n    this.categoriesContainer.classList.add('emoticons-has-search');\n    this.disposeSearch = render(() => {\n      const [query, setQuery] = createSignal('');\n      const [group, setGroup] = createSignal<EmojiGroup>();\n      const [focused, setFocused] = createSignal(false);\n      const searching = createMemo(() => !!query());\n\n      const [loadedData, setLoadedData] = createSignal<T>();\n      const [data] = createResource(query, this.searchFetcher);\n      const [groupData] = this.groupFetcher ? createResource(group, this.groupFetcher) : [];\n      const [element] = createResource(() => {\n        return {\n          data: loadedData(),\n          grouping: !!untrack(group),\n          searching: untrack(searching)\n        };\n      }, this.processSearchResult);\n\n      const loading = this.searchNoLoader ? undefined : createMemo(() => searching() && element.loading);\n      const shouldMoveSearch = createMemo(() => focused() || searching() || !!group());\n      const shouldUseContainer = createMemo(() => element() || this.categoriesContainer);\n\n      Portal({\n        mount: this.scrollable.container,\n        children: Animated({\n          type: 'cross-fade',\n          get children() {\n            return shouldUseContainer();\n          }\n        })\n      });\n\n      createEffect(() => {\n        const useData = group() ? groupData : data;\n        if(useData.loading) {\n          return;\n        }\n\n        // * reading a rejected resource throws, which would abort this effect before it\n        // * ever sets the data - the previous query's results would stay on screen with no\n        // * spinner and no error, making every following query look like it never ran\n        setLoadedData(() => useData.error === undefined ? useData() : undefined);\n      });\n\n      createEffect(() => {\n        this.container.classList.toggle('is-searching', shouldMoveSearch());\n      });\n\n      return EmoticonsSearch({\n        type: this.searchType,\n        placeholder: this.searchPlaceholder,\n        debounceTime: this.searchDebounceTime,\n        verifyDebounce: this.searchVerifyDebounce,\n        loading,\n        onValue: setQuery,\n        onFocusChange: setFocused,\n        onGroup: this.groupFetcher ? setGroup : undefined,\n        // categoryColor: this.textColor\n        categoryColor: 'primary-text-color'\n      });\n    }, searchContainer);\n  }\n\n  public getCategoryByContainer(container: HTMLElement) {\n    return this.categoriesMap.get(container);\n  }\n\n  public getCategoryByMenuTab(menuTab: HTMLElement) {\n    return this.categoriesByMenuTabMap.get(menuTab);\n  }\n\n  public createCategory({\n    stickerSet,\n    id,\n    title,\n    isLocal,\n    noMenuTab = !stickerSet && !id,\n    styles\n  }: {\n    stickerSet?: StickerSet,\n    /**\n     * Overrides the key the category is filed under. The group's own set needs one of these:\n     * keyed by the set id it would fight for the slot with the same set installed by the user,\n     * and with the events (install / delete / reorder) that address installed sets by id.\n     */\n    id?: string,\n    title?: HTMLElement | DocumentFragment,\n    isLocal?: boolean,\n    noMenuTab?: boolean,\n    styles: StickersTabStyles\n  }) {\n    if(this.noMenu) {\n      noMenuTab = true;\n    }\n\n    const categoryId = id ?? '' + stickerSet?.id;\n    const category: Category = new StickersTabCategory({\n      id: categoryId,\n      title,\n      overflowElement: this.content,\n      getContainerSize: () => {\n        let width: number, height: number;\n        if(this.getContainerSize) {\n          const size = this.getContainerSize();\n          width = size.width;\n          height = size.height;\n        } else {\n          const element = this.emoticonsDropdown.getElement();\n          const propertyWidth = element.style.getPropertyValue('--width');\n          width = propertyWidth ? parseInt(propertyWidth) : element.offsetWidth;\n          // const esgWidth = customProperties.getPropertyAsSize('esg-width');\n          // width = esgWidth === undefined ? windowSize.width : esgWidth;\n        }\n\n        return {width: width - styles.padding, height};\n      },\n      styles,\n      noMenuTab,\n      middleware: this.middlewareHelper.get()\n    }) as any;\n\n    if(styles.itemsClassName) {\n      category.elements.items.classList.add(styles.itemsClassName);\n    }\n\n    const container = category.elements.container;\n    container.classList.add('hide');\n\n    if(stickerSet || id) {\n      category.set = stickerSet;\n      this.categories[categoryId] = category;\n      this.categoriesMap.set(container, category);\n      this.categoriesIntersector.observe(container);\n    }\n\n    if(!noMenuTab) {\n      this.categoriesByMenuTabMap.set(category.elements.menuTab, category);\n      this.menuOnClickResult.stickyIntersector.observeStickyHeaderChanges(container);\n      !isLocal && category.elements.menuTab.classList.add('not-local');\n    }\n\n    return category;\n  }\n\n  public positionCategory(category: Category, prepend?: boolean) {\n    const {menuTab, container} = category.elements;\n    const posItems = prepend ? this.localCategories.filter((category) => category.mounted).length : 0xFFFF;\n    let foundMenuScroll = false;\n    const posMenu = prepend ? this.localCategories.filter((category) => {\n      if(category.menuScroll && !foundMenuScroll) {\n        foundMenuScroll = true;\n        return true;\n      }\n\n      return category.mounted && !category.menuScroll && category.elements.menuTab;\n    }).length : 0xFFFF;\n    positionElementByIndex(container, this.categoriesContainer, posItems);\n    positionElementByIndex(menuTab, this.menu, posMenu);\n    // the DOM move blanks transferred placeholder canvases inside - re-present\n    lottieLoader.nudgePresentWithin(container);\n  }\n\n  public isCategoryVisible(category: Category) {\n    return this.categoriesIntersector.isVisible(category.elements.container);\n  }\n\n  protected toggleLocalCategory(category: Category, visible: boolean) {\n    if(!visible) {\n      category.elements.menuTab?.remove();\n      category.elements.container.remove();\n    } else {\n      const idx = this.localCategories.indexOf(category);\n      const sliced = this.localCategories.slice(0, idx);\n      let notMountedItems = 0, notMountedMenus = 0;\n      sliced.forEach((category) => {\n        if(!category.mounted) {\n          ++notMountedItems;\n          ++notMountedMenus;\n        } else if(!category.elements.menuTab || category.menuScroll) {\n          ++notMountedMenus;\n        }\n      });\n      const itemsIdx = idx - notMountedItems, menuIdx = idx - notMountedMenus;\n      category.elements.menuTab && positionElementByIndex(category.elements.menuTab, this.menu, menuIdx);\n      positionElementByIndex(category.elements.container, this.categoriesContainer, itemsIdx);\n    }\n\n    category.mounted = visible;\n    // category.elements.container.classList.toggle('hide', !visible);\n  }\n\n  protected createLocalCategory({\n    id,\n    title,\n    icon,\n    noMenuTab,\n    styles\n  }: {\n    id?: string,\n    title: LangPackKey | '',\n    icon?: Icon,\n    noMenuTab?: boolean,\n    styles: StickersTabStyles\n  }) {\n    if(this.noMenu) {\n      noMenuTab = true;\n    }\n\n    const hasId = id !== undefined;\n\n    const category = this.createCategory({\n      stickerSet: hasId ? {id} as any : undefined,\n      title: title && i18n(title),\n      isLocal: true,\n      noMenuTab,\n      styles\n    });\n    category.local = true;\n    hasId && this.localCategories.push(category);\n    if(category.elements.title) {\n      category.elements.title.classList.add('disable-hover');\n    }\n\n    if(category.elements.menuTab) {\n      if(icon) {\n        category.elements.menuTab.append(Icon(icon));\n      }\n\n      category.elements.menuTabPadding.remove();\n    }\n\n    this.toggleLocalCategory(category, false);\n    return category;\n  }\n\n  protected onLocalCategoryUpdate(category: Category) {\n    category.setCategoryItemsHeight();\n    this.toggleLocalCategory(category, !!category.items.length);\n  }\n\n  protected resizeCategories = () => {\n    for(const [container, category] of this.categoriesMap) {\n      category.setCategoryItemsHeight();\n    }\n  };\n\n  protected deleteCategory(category: Category) {\n    if(category) {\n      category.elements.container.remove();\n      category.elements.menuTab?.remove();\n      this.categoriesIntersector.unobserve(category.elements.container);\n      // mirrors the observe in createCategory; without it the sticky observer keeps\n      // reporting a container that no longer resolves to a category\n      this.menuOnClickResult?.stickyIntersector?.unobserve(category.elements.container);\n      delete this.categories[category.id];\n      this.categoriesMap.delete(category.elements.container);\n      this.categoriesByMenuTabMap.delete(category.elements.menuTab);\n      category.middlewareHelper.destroy();\n\n      return true;\n    }\n\n    return false;\n  }\n\n  protected spliceExceed(category: Category) {\n    if(category.limit === undefined) {\n      return false;\n    }\n\n    const {items, limit} = category;\n    items.splice(limit, items.length - limit).forEach(({element}) => {\n      element.remove();\n    });\n\n    this.onLocalCategoryUpdate(category);\n\n    return true;\n  }\n\n  public init() {\n    this.emoticonsDropdown && this.listenerSetter.add(this.emoticonsDropdown)('closed', () => {\n      this.postponedEvents.forEach(({cb, args}) => {\n        cb(...args);\n      });\n\n      this.postponedEvents.length = 0;\n    });\n  }\n\n  public destroy() {\n    this.getContainerSize = undefined;\n    this.postponedEvents.length = 0;\n    this.categoriesIntersector?.disconnect();\n    this.listenerSetter.removeAll();\n    this.scrollable.destroy();\n    this.menuScroll?.destroy();\n    this.menuOnClickResult?.stickyIntersector?.disconnect();\n    this.middlewareHelper.destroy();\n    this.disposeSearch?.();\n  }\n\n  /**\n   * Holds an event back until the panel is off screen. The check is `isDisplayed` rather than\n   * `isActive`: sending closes the dropdown, which drops the `active` class right away while\n   * the panel keeps fading out for another animation frame or two — an update landing in that\n   * window would be seen rearranging the panel, which is exactly what postponing avoids.\n   */\n  protected postponedEvent = <K>(cb: (...args: K[]) => void) => {\n    return (...args: K[]) => {\n      if(this.emoticonsDropdown?.isDisplayed()) {\n        this.postponedEvents.push({cb, args});\n      } else {\n        cb(...args);\n      }\n    };\n  };\n\n  protected attachHelpers({getTextColor, verifyRecent, canHaveEmojiTimer, isGif, onContextMenu}: {\n    getTextColor?: () => string,\n    verifyRecent?: (target: HTMLElement) => boolean,\n    canHaveEmojiTimer?: boolean,\n    isGif?: boolean,\n    onContextMenu?: Parameters<typeof createStickersContextMenu>[0]['onContextMenu']\n  } = {}) {\n    attachStickerViewerListeners({\n      additionalClass: this.additionalStickerViewerClass,\n      listenTo: this.content,\n      listenerSetter: this.listenerSetter,\n      getTextColor\n    });\n\n    const type: IgnoreMouseOutType = 'menu';\n    this.emoticonsDropdown && createStickersContextMenu({\n      listenTo: this.content,\n      chatInput: this.emoticonsDropdown.chatInput,\n      verifyRecent,\n      isEmojis: !!getTextColor,\n      isGif,\n      canHaveEmojiTimer,\n      canViewPack: true,\n      onContextMenu,\n      onOpen: () => {\n        this.emoticonsDropdown.setIgnoreMouseOut(type, true);\n      },\n      onClose: () => {\n        this.emoticonsDropdown.setIgnoreMouseOut(type, false);\n      }\n    });\n  }\n\n  protected get animationGroup() {\n    return this.emoticonsDropdown?.animationGroup || EMOTICONSSTICKERGROUP;\n  }\n\n  // * common methods for tabs\n\n  public renderStickerSetThumb({set, menuTabPadding, middleware, textColor}: {\n    set: StickerSet.stickerSet,\n    menuTabPadding: HTMLElement,\n    middleware: Middleware,\n    textColor?: WrapSomethingOptions['textColor']\n  }) {\n    wrapStickerSetThumb({\n      set,\n      container: menuTabPadding,\n      group: this.animationGroup,\n      lazyLoadQueue: this.emoticonsDropdown?.lazyLoadQueue,\n      width: 32,\n      height: 32,\n      autoplay: false,\n      textColor,\n      middleware\n    });\n  }\n\n  public createStickerRenderer() {\n    const superStickerRenderer = new SuperStickerRenderer({\n      regularLazyLoadQueue: this.emoticonsDropdown.lazyLoadQueue,\n      group: this.animationGroup,\n      managers: this.managers,\n      intersectionObserverInit: this.emoticonsDropdown.intersectionOptions\n    });\n\n    const rendererLazyLoadQueue = superStickerRenderer.lazyLoadQueue;\n    this.emoticonsDropdown.addLazyLoadQueueRepeat(\n      rendererLazyLoadQueue,\n      superStickerRenderer.processInvisible,\n      this.middlewareHelper.get()\n    );\n\n    return superStickerRenderer;\n  }\n}\n","import {ChatFull, StickerSet} from '@layer';\n\n/**\n * The sticker set (or custom emoji pack) a group offers to everyone chatting in it.\n * Only supergroups can have one, so anything else resolves to nothing.\n */\nexport default function getGroupStickerSet(chatFull: ChatFull, isEmoji?: boolean) {\n  const channelFull = chatFull as ChatFull.channelFull;\n  return (isEmoji ? channelFull?.emojiset : channelFull?.stickerset) as StickerSet.stickerSet;\n}\n","import {Chat, ChatFull, StickerSet} from '@layer';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport rootScope from '@lib/rootScope';\nimport getGroupStickerSet from '@appManagers/utils/chats/getGroupStickerSet';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport type {AppManagers} from '@lib/managers';\n\n/**\n * The category the group's own set is filed under. It is deliberately not the set's id:\n * the same set may also sit in the user's own list, and the install / delete / reorder\n * events address those by id.\n */\nexport const GROUP_SET_CATEGORY_ID = 'megagroup';\n\nexport type GroupSetState = {\n  /** absent while the group offers nothing — the placeholder case */\n  set?: StickerSet.stickerSet,\n  /** whether the user may change what the group offers */\n  canEdit: boolean,\n  /** the user collapsed the section for this chat */\n  hidden: boolean\n};\n\n/**\n * Tracks the sticker set / custom emoji pack the open group offers to everyone chatting in\n * it, so a tab can show it even when the user hasn't installed it.\n *\n * Resolving reads the chat's full info, so it is deliberately kept off the chat-open path:\n * {@link update} runs when the dropdown opens, and afterwards only when that chat's full\n * info changes.\n */\nexport default class GroupSetController {\n  private chatId: ChatId;\n  private state: GroupSetState;\n  private requestId = 0;\n\n  constructor(private options: {\n    managers: AppManagers,\n    listenerSetter: ListenerSetter,\n    isEmoji?: boolean,\n    getPeerId: () => PeerId,\n    isHidden: (chatId: ChatId, set: StickerSet.stickerSet) => boolean,\n    /** whether the set already sits in the user's own list of installed ones */\n    isInstalled: (set: StickerSet.stickerSet) => boolean,\n    render: (state: GroupSetState) => void,\n    remove: () => void\n  }) {\n    options.listenerSetter.add(rootScope)('chat_full_update', (chatId) => {\n      if(this.getChatId() === chatId) {\n        this.update();\n      }\n    });\n  }\n\n  private getChatId() {\n    const peerId = this.options.getPeerId();\n    return peerId?.isAnyChat() ? peerId.toChatId() : undefined;\n  }\n\n  public getCurrentChatId() {\n    return this.chatId;\n  }\n\n  public getCurrentSet() {\n    return this.state?.set;\n  }\n\n  public async update() {\n    const chatId = this.getChatId();\n    const requestId = ++this.requestId;\n\n    const state = chatId ? await this.resolve(chatId) : undefined;\n    if(requestId !== this.requestId) {\n      return;\n    }\n\n    this.chatId = chatId;\n    this.setState(state);\n  }\n\n  private async resolve(chatId: ChatId): Promise<GroupSetState> {\n    const [chatFull, chat] = await Promise.all([\n      this.options.managers.appProfileManager.getChatFull(chatId),\n      this.options.managers.appChatsManager.getChat(chatId)\n    ]);\n\n    const set = getGroupStickerSet(chatFull, this.options.isEmoji);\n    // a sticker set is the server's call (it reports when the group is big enough), an emoji\n    // pack follows from being able to edit the group — the same split tdesktop makes.\n    // `change_info` on its own reads a plain member's default rights, so it answers true for\n    // everyone the group hasn't muted: the admin-ness has to be established first, which is\n    // what tdesktop's canEditEmoji() = amCreator() || (adminRights & ChangeInfo) amounts to.\n    // Only a supergroup can carry a pack at all, so an admin elsewhere has nothing to set\n    const canEdit = this.options.isEmoji ?\n      !!(chat as Chat.channel).pFlags?.megagroup &&\n        hasRights(chat, 'just_admin') &&\n        hasRights(chat, 'change_info') :\n      !!(chatFull as ChatFull.channelFull)?.pFlags?.can_set_stickers;\n\n    // nothing offered and nothing to offer it with\n    if(!set) {\n      return canEdit ? {canEdit, hidden: false} : undefined;\n    }\n\n    // already in the user's own list and not theirs to change — a second copy is just noise\n    if(!canEdit && this.options.isInstalled(set)) {\n      return undefined;\n    }\n\n    // an admin always sees the section, so a stale collapsed flag never hides it from them\n    const hidden = !canEdit && this.options.isHidden(chatId, set);\n    return {set, canEdit, hidden};\n  }\n\n  /** Drops the section without resolving a new one — for leaving the chat it belonged to. */\n  public clear() {\n    ++this.requestId;\n    this.chatId = undefined;\n    this.setState(undefined);\n  }\n\n  private setState(state?: GroupSetState) {\n    const previous = this.state;\n    if(\n      previous?.set?.id === state?.set?.id &&\n      previous?.canEdit === state?.canEdit &&\n      previous?.hidden === state?.hidden &&\n      !!previous === !!state\n    ) {\n      return;\n    }\n\n    if(previous) {\n      this.options.remove();\n    }\n\n    this.state = state;\n    if(state) {\n      this.options.render(state);\n    }\n  }\n}\n","import {StickerSet} from '@layer';\nimport ButtonIcon from '@components/buttonIcon';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport I18n, {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {appSettings, setAppSettings} from '@stores/appSettings';\n\nconst hiddenKey = (isEmoji?: boolean) => isEmoji ? 'hiddenGroupEmojiSets' as const : 'hiddenGroupSets' as const;\n\n/** Whether the user collapsed the set the group currently offers in this chat. */\nexport function isGroupSetHidden(chatId: ChatId, set: StickerSet.stickerSet, isEmoji?: boolean) {\n  return appSettings.stickers[hiddenKey(isEmoji)]?.['' + chatId] === '' + set.id;\n}\n\n/** Keyed by set, so a group swapping packs brings the section back on its own. */\nexport function setGroupSetHidden(\n  chatId: ChatId,\n  set: StickerSet.stickerSet,\n  isEmoji: boolean,\n  hidden: boolean\n) {\n  // the store merges objects rather than replacing them, so un-hiding has to write the key\n  // as undefined — handing it a smaller object would leave the old entry in place\n  setAppSettings('stickers', hiddenKey(isEmoji), {\n    ['' + chatId]: hidden ? '' + set.id : undefined\n  });\n}\n\n/** The set's own title, or the section name while the group offers nothing yet. */\nexport function getGroupSetTitle(set: StickerSet.stickerSet, isEmoji?: boolean) {\n  return set ?\n    wrapEmojiText(set.title) :\n    i18n(isEmoji ? 'GroupEmojiPack' : 'GroupStickers');\n}\n\n/** Takes an admin from the panel straight to the screen that configures the group's set. */\nexport async function openGroupSetTab(chatId: ChatId, isEmoji: boolean) {\n  // imported at click time: the panel lives under the chat input, which the sidebar imports\n  const [{default: appSidebarRight}, {AppGroupStickersTab}] = await Promise.all([\n    import('@components/sidebarRight'),\n    import('@components/solidJsTabs/tabs')\n  ]);\n\n  // the panel stays usable with the tab open, so repeated taps must not stack copies of it.\n  // The same tab serves both variants, hence the payload comparison rather than an\n  // instance check alone.\n  const current = appSidebarRight.getHistory().slice(-1)[0];\n  if(\n    current instanceof AppGroupStickersTab &&\n    current.payload?.chatId === chatId &&\n    !!current.payload?.isEmoji === isEmoji\n  ) {\n    appSidebarRight.toggleSidebar(true);\n    return;\n  }\n\n  appSidebarRight.createTab(AppGroupStickersTab).open({chatId, isEmoji});\n  appSidebarRight.toggleSidebar(true);\n}\n\n/**\n * The button tdesktop puts in the section header: an admin is taken to the setup screen,\n * everyone else collapses the section to the bottom of the panel (or brings it back).\n */\nexport function createGroupSetHeaderButton(options: {\n  canEdit: boolean,\n  hidden: boolean,\n  isEmoji?: boolean,\n  onClick: () => void\n}) {\n  const {canEdit, hidden} = options;\n  const button = ButtonIcon(\n    canEdit ? 'settings' : (hidden ? 'add' : 'hide'),\n    {noRipple: true}\n  );\n  button.setAttribute('aria-label', I18n.format(\n    canEdit ?\n      (options.isEmoji ? 'GroupEmojiPack' : 'GroupStickers') :\n      (hidden ? 'Show' : 'Hide'),\n    true\n  ));\n\n  attachClickEvent(button, (event) => {\n    event.stopPropagation();\n    options.onClick();\n  });\n\n  return button;\n}\n","import lottieLoader from '@lib/lottie/lottieLoader';\nimport {EmoticonsDropdown} from '..';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {Document, MessagesAllStickers, StickerSet} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport {AppManagers} from '@lib/managers';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport {putPreloader} from '@components/putPreloader';\nimport showStickersPopup from '@components/popups/stickers';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport noop from '@helpers/noop';\nimport ButtonIcon from '@components/buttonIcon';\nimport confirmationPopup from '@components/confirmationPopup';\nimport VisibilityIntersector, {OnVisibilityChangeItem} from '@components/visibilityIntersector';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport forEachReverse from '@helpers/array/forEachReverse';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport getStickerEffectThumb from '@appManagers/utils/stickers/getStickerEffectThumb';\nimport StickersTabCategory, {EmoticonsTabStyles} from '@components/emoticonsDropdown/category';\nimport EmoticonsTabC from '@components/emoticonsDropdown/tab';\nimport {i18n} from '@lib/langPack';\nimport {onCleanup} from 'solid-js';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport GroupSetController, {GROUP_SET_CATEGORY_ID, GroupSetState} from '@components/emoticonsDropdown/groupSet';\nimport {\n  createGroupSetHeaderButton,\n  getGroupSetTitle,\n  isGroupSetHidden,\n  openGroupSetTab,\n  setGroupSetHidden\n} from '@components/emoticonsDropdown/groupSetSection';\nimport Icon from '@components/icon';\nimport {getStickerSetInputById} from '@lib/appManagers/utils/stickers/getStickerSetInput';\n\ntype StickersTabItem = {element: HTMLElement, document: Document.document};\nexport default class StickersTab extends EmoticonsTabC<StickersTabCategory<StickersTabItem>, Document.document[]> {\n  private stickerRenderer: SuperStickerRenderer;\n  private groupSetController: GroupSetController;\n  private groupSetHidden: boolean;\n\n  constructor(managers: AppManagers) {\n    super({\n      managers,\n      searchFetcher: async(value) => {\n        if(!value) return [];\n        return this.managers.appStickersManager.searchStickers(value);\n      },\n      groupFetcher: async(group) => {\n        if(!group) return [];\n\n        if(group._ === 'emojiGroupPremium') {\n          return this.managers.appStickersManager.getPremiumStickers();\n        }\n\n        return this.managers.appStickersManager.getStickersByEmoticon({emoticon: group.emoticons, includeServerStickers: true});\n      },\n      processSearchResult: async({data: stickers, searching, grouping}) => {\n        if(!stickers || (!searching && !grouping)) {\n          return;\n        }\n\n        if(!stickers.length) {\n          const span = i18n('NoStickersFound');\n          span.classList.add('emoticons-not-found');\n          return span;\n        }\n\n        const container = this.categoriesContainer.cloneNode(false) as HTMLElement;\n        const category = this.createCategory({styles: EmoticonsTabStyles.Stickers});\n        const promise = StickersTab.categoryAppendStickers(\n          this,\n          this.stickerRenderer,\n          stickers.length,\n          category,\n          stickers\n        );\n        container.append(category.elements.container);\n\n        let cleaned = false;\n        onCleanup(() => {\n          cleaned = true;\n          category.middlewareHelper.destroy();\n          this.clearCategoryItems(category, true);\n        });\n\n        await promise;\n\n        if(!cleaned) {\n          StickersTab._onCategoryVisibility(category, true);\n        }\n\n        return container;\n      },\n      // searchNoLoader: true,\n      searchPlaceholder: 'SearchStickers',\n      searchType: 'stickers'\n    });\n\n    this.container.classList.add('stickers-padding');\n    this.content.id = 'content-stickers';\n  }\n\n  private setFavedLimit(limit: number) {\n    const category = this.categories['faved'];\n    category.limit = limit;\n  }\n\n  private initGroupSet() {\n    this.groupSetController = new GroupSetController({\n      managers: this.managers,\n      listenerSetter: this.listenerSetter,\n      getPeerId: () => this.emoticonsDropdown ? this.emoticonsDropdown.chatInput?.chat?.peerId : undefined,\n      isHidden: (chatId, set) => isGroupSetHidden(chatId, set),\n      isInstalled: (set) => !!this.categories[set.id],\n      render: (state) => this.renderGroupSet(state),\n      remove: () => this.deleteCategory(this.categories[GROUP_SET_CATEGORY_ID])\n    });\n\n    if(this.emoticonsDropdown) {\n      this.listenerSetter.add(this.emoticonsDropdown)('opened', () => this.groupSetController.update());\n      // the tab is built on the first open, after that open's event already fired\n      this.groupSetController.update();\n    }\n  }\n\n  /**\n   * Reuses the menu tab's own click: it already handles making the category active and\n   * scrolling the panel to it, including the bookkeeping that keeps the scroll spy quiet.\n   */\n  private scrollToGroupSet() {\n    const menuTab = this.categories[GROUP_SET_CATEGORY_ID]?.elements.menuTab;\n    if(menuTab) {\n      simulateClickEvent(menuTab);\n    }\n  }\n\n  /**\n   * A collapsed section belongs below every other set, but sets keep arriving — the initial\n   * load and later installs both append — so its place has to be reclaimed afterwards.\n   */\n  private repositionGroupSet() {\n    const category = this.categories[GROUP_SET_CATEGORY_ID];\n    if(category && this.groupSetHidden) {\n      this.positionCategory(category, false);\n    }\n  }\n\n  private renderGroupSet(state: GroupSetState) {\n    const {set, canEdit, hidden} = state;\n    this.groupSetHidden = hidden;\n    const chatId = this.groupSetController.getCurrentChatId();\n    const category = this.createCategory({\n      id: GROUP_SET_CATEGORY_ID,\n      stickerSet: set,\n      title: getGroupSetTitle(set),\n      styles: EmoticonsTabStyles.Stickers\n    });\n\n    category.elements.title.append(createGroupSetHeaderButton({\n      canEdit,\n      hidden,\n      onClick: () => {\n        if(canEdit) {\n          openGroupSetTab(chatId, false);\n          return;\n        }\n\n        setGroupSetHidden(chatId, set, false, !hidden);\n        this.groupSetController.update().then(() => {\n          // bringing it back should show it, not just move it up the list\n          if(hidden) this.scrollToGroupSet();\n        });\n      }\n    }));\n\n    // hidden sections sink below the user's own sets, exactly like tdesktop's Hidden place\n    this.positionCategory(category, !hidden);\n\n    if(set) {\n      StickersTab.categoryAppendStickers(\n        this,\n        this.stickerRenderer,\n        set.count,\n        category,\n        this.managers.appStickersManager.getStickerSet(getStickerSetInputById(set))\n        .then((stickerSet) => stickerSet.documents as MyDocument[])\n      );\n\n      this.renderStickerSetThumb({\n        set,\n        menuTabPadding: category.elements.menuTabPadding,\n        middleware: category.middlewareHelper.get()\n      });\n    } else {\n      // nothing configured yet: an empty section whose only job is to lead an admin to setup\n      category.elements.container.classList.remove('hide');\n      category.elements.menuTab.append(Icon('stickers_face'));\n    }\n  }\n\n  public onPeerChanged() {\n    if(!this.groupSetController) {\n      return;\n    }\n\n    this.groupSetController.clear();\n    // an open dropdown has to swap the set right away; a closed one resolves on its next open\n    if(this.emoticonsDropdown?.isActive()) {\n      this.groupSetController.update();\n    }\n  }\n\n  public static _onCategoryVisibility = (category: StickersTabCategory<any>, visible: boolean) => {\n    category.elements.items.replaceChildren(...(!visible ? [] : category.items.map(({element}) => element)));\n    if(visible) {\n      // remounting detaches+reattaches the cells - transferred placeholder\n      // canvases lose their displayed frame until the next worker commit\n      lottieLoader.nudgePresentWithin(category.elements.items);\n    }\n  };\n\n  private onCategoryVisibility = ({target, visible}: OnVisibilityChangeItem) => {\n    const category = this.categoriesMap.get(target);\n    // the set's documents resolve asynchronously, so this can fire for a category that was\n    // already deleted — leaving a chat drops the group's set that way\n    if(!category) {\n      return;\n    }\n\n    StickersTab._onCategoryVisibility(category, visible);\n  };\n\n  public init() {\n    super.init();\n\n    this.scrollable.onAdditionalScroll = () => {\n      this.setTyping();\n    };\n\n    /* stickersDiv.addEventListener('mouseover', (e) => {\n      let target = e.target as HTMLElement;\n\n      if(target.tagName === 'CANVAS') { // turn on sticker\n        let animation = lottieLoader.getAnimation(target.parentElement, EMOTICONSSTICKERGROUP);\n\n        if(animation) {\n          // @ts-ignore\n          if(animation.currentFrame === animation.totalFrames - 1) {\n            animation.goToAndPlay(0, true);\n          } else {\n            animation.play();\n          }\n        }\n      }\n    }); */\n\n    const intersectionOptions = this.emoticonsDropdown.intersectionOptions;\n    this.categoriesIntersector = new VisibilityIntersector(this.onCategoryVisibility, intersectionOptions);\n\n    this.scrollable.container.addEventListener('click', (e) => {\n      const target = e.target as HTMLElement;\n      if(findUpClassName(target, 'category-title')) {\n        const container = findUpClassName(target, 'emoji-category');\n        const category = this.categoriesMap.get(container);\n        if(category.local) {\n          return;\n        }\n\n        showStickersPopup(getStickerSetInputById(category.set), false, this.emoticonsDropdown.chatInput);\n        return;\n      }\n\n      this.emoticonsDropdown.onMediaClick(e);\n    });\n\n    this.menuOnClickResult = EmoticonsDropdown.menuOnClick(this, this.menu, this.scrollable, this.menuScroll);\n\n    const preloader = putPreloader(this.content, true);\n\n    const onCategoryStickers = (category: StickersTabCategory<StickersTabItem>, stickers: MyDocument[]) => {\n      // if(category.id === 'faved' && category.limit && category.limit < stickers.length) {\n      //   category.limit = stickers.length;\n      // }\n\n      if(category.limit) {\n        stickers = stickers.slice(0, category.limit);\n      }\n\n      const ids = new Set(stickers.map((doc) => doc.id));\n      forEachReverse(category.items, (item) => {\n        if(!ids.has(item.document.id)) {\n          this.deleteSticker(category, item.document, true);\n        }\n      });\n\n      this.toggleLocalCategory(category, !!stickers.length);\n      forEachReverse(stickers, (doc, idx) => {\n        this.unshiftSticker(category, doc, true, idx);\n      });\n      this.spliceExceed(category);\n      category.elements.container.classList.remove('hide');\n    };\n\n    const favedCategory = this.createLocalCategory({\n      id: 'faved',\n      title: 'FavoriteStickers',\n      icon: 'savedmessages',\n      styles: EmoticonsTabStyles.Stickers\n    });\n    // favedCategory.elements.menuTab.classList.add('active');\n\n    const recentCategory = this.createLocalCategory({\n      id: 'recent',\n      title: 'Stickers.Recent',\n      icon: 'recent',\n      styles: EmoticonsTabStyles.Stickers\n    });\n    recentCategory.limit = 20;\n\n    const clearButton = ButtonIcon('close', {noRipple: true});\n    recentCategory.elements.title.append(clearButton);\n    attachClickEvent(clearButton, () => {\n      confirmationPopup({\n        titleLangKey: 'ClearRecentStickersAlertTitle',\n        descriptionLangKey: 'ClearRecentStickersAlertMessage',\n        button: {\n          langKey: 'Clear'\n        }\n      }).then(() => {\n        this.managers.appStickersManager.clearRecentStickers();\n      }, noop);\n    });\n\n    const promises = [\n      Promise.all([\n        this.managers.apiManager.getLimit('favedStickers'),\n        this.managers.appStickersManager.getFavedStickersStickers()\n      ]).then(([limit, stickers]) => {\n        this.setFavedLimit(limit);\n        onCategoryStickers(favedCategory, stickers);\n      }),\n\n      this.managers.appStickersManager.getRecentStickersStickers().then((stickers) => {\n        onCategoryStickers(recentCategory, stickers);\n      }),\n\n      this.managers.appStickersManager.getAllStickers().then((res) => {\n        for(const set of (res as MessagesAllStickers.messagesAllStickers).sets) {\n          StickersTab.renderStickerSet(this, this.stickerRenderer, set, false);\n        }\n      })\n    ];\n\n    Promise.race(promises).finally(() => {\n      preloader.remove();\n    });\n\n    Promise.all(promises).finally(() => {\n      this.mounted = true;\n      this.setTyping();\n\n      const favedCategory = this.categories['faved'];\n      const recentCategory = this.categories['recent'];\n      this.menuOnClickResult.setActive(favedCategory.items.length ? favedCategory : recentCategory);\n\n      this.repositionGroupSet();\n\n      rootScope.addEventListener('stickers_installed', (set) => {\n        if(!this.categories[set.id]) {\n          StickersTab.renderStickerSet(this, this.stickerRenderer, set, true);\n          this.repositionGroupSet();\n          // installing the group's own set gives it a category of its own — the group one\n          // beside it would be a duplicate\n          this.groupSetController?.update();\n        }\n      });\n    });\n\n    this.stickerRenderer = this.createStickerRenderer();\n    this.initGroupSet();\n\n    const onStickerUpdated = ({type, document, faved}: BroadcastEvents['sticker_updated']) => {\n      const category = this.categories[type === 'faved' ? 'faved' : 'recent'];\n      if(category) {\n        if(faved) {\n          this.unshiftSticker(category, document);\n        } else {\n          this.deleteSticker(category, document);\n        }\n      }\n    };\n\n    const onStickerUpdatedPostponed = this.postponedEvent(onStickerUpdated);\n    rootScope.addEventListener('sticker_updated', (data) => {\n      // using a sticker reshuffles the recent row, which must not happen under the cursor —\n      // that waits for the panel to hide; faving and removing are the user's own doing right\n      // there in the panel, so they land at once\n      const postpone = data.type === 'recent' && data.faved;\n      (postpone ? onStickerUpdatedPostponed : onStickerUpdated)(data);\n    });\n\n    rootScope.addEventListener('stickers_deleted', ({id}) => {\n      const category = this.categories[id];\n      this.deleteCategory(category);\n      // uninstalling may turn a deduped group set into one worth showing on its own\n      this.groupSetController?.update();\n    });\n\n    rootScope.addEventListener('stickers_top', this.postponedEvent((id) => {\n      const category = this.categories[id];\n      if(category) {\n        this.positionCategory(category, true);\n        this.emoticonsDropdown.addEventListener('openAfterLayout', () => {\n          this.menuOnClickResult.setActiveStatic(category);\n        }, {once: true});\n      }\n    }));\n\n    rootScope.addEventListener('stickers_order', this.postponedEvent(({type, order}) => {\n      if(type !== 'stickers') {\n        return;\n      }\n\n      order.forEach((id) => {\n        const category = this.categories[id];\n        if(category) {\n          this.positionCategory(category, false);\n        }\n      });\n    }));\n\n    const onStickersUpdated = ({type, stickers}: BroadcastEvents['stickers_updated']) => {\n      const category = this.categories[type === 'faved' ? 'faved' : 'recent'];\n      if(category) {\n        onCategoryStickers(category, stickers);\n      }\n    };\n\n    const onStickersUpdatedPostponed = this.postponedEvent(onStickersUpdated);\n    rootScope.addEventListener('stickers_updated', (data) => {\n      const category = this.categories[data.type === 'faved' ? 'faved' : 'recent'];\n      const {limit} = category || {};\n      const length = limit ? Math.min(limit, data.stickers.length) : data.stickers.length;\n      // a list that got shorter means something was taken out of it — clearing the recent\n      // stickers, un-faving one — and the user has to see that happen; a list of the same\n      // length is the reorder that follows using a sticker, which waits for the panel to hide\n      const shrunk = category && length < category.items.length;\n      (shrunk ? onStickersUpdated : onStickersUpdatedPostponed)(data);\n    });\n\n    rootScope.addEventListener('app_config', () => {\n      this.managers.apiManager.getLimit('favedStickers').then((limit) => {\n        this.setFavedLimit(limit);\n      });\n    });\n\n    mediaSizes.addEventListener('resize', this.resizeCategories);\n\n    this.attachHelpers({\n      verifyRecent: (target) => !!findUpAsChild(target, this.categories['recent'].elements.items)\n    });\n\n    this.init = null;\n  }\n\n  public deleteCategory(category: StickersTabCategory<StickersTabItem>) {\n    const ret = super.deleteCategory(category);\n    if(ret) {\n      this.clearCategoryItems(category);\n    }\n\n    return ret;\n  }\n\n  private clearCategoryItems(category: StickersTabCategory<StickersTabItem>, noUnmount?: boolean) {\n    if(!noUnmount) category.elements.items.replaceChildren();\n    category.items.splice(0, Infinity).forEach(({element}) => this.stickerRenderer.unobserveAnimated(element));\n  }\n\n  public deleteSticker(category: StickersTabCategory<StickersTabItem>, doc: MyDocument, batch?: boolean) {\n    const item = findAndSplice(category.items, (item) => item.document.id === doc.id);\n    if(item) {\n      item.element.remove();\n      this.stickerRenderer.unobserveAnimated(item.element);\n\n      if(!batch) {\n        this.onLocalCategoryUpdate(category);\n      }\n    }\n  }\n\n  public unshiftSticker(category: StickersTabCategory<StickersTabItem>, doc: MyDocument, batch?: boolean, idx?: number) {\n    if(idx !== undefined) {\n      const i = category.items[idx];\n      if(i && i.document.id === doc.id) {\n        return;\n      }\n    }\n\n    let item = findAndSplice(category.items, (item) => item.document.id === doc.id);\n    if(!item) {\n      item = {\n        element: this.stickerRenderer.renderSticker(doc, undefined, undefined, category.middlewareHelper.get()),\n        document: doc\n      };\n    }\n\n    category.items.unshift(item);\n    category.elements.items.prepend(item.element);\n    // the DOM move blanks a transferred placeholder canvas - re-present\n    lottieLoader.nudgePresentWithin(item.element);\n\n    if(!batch) {\n      this.spliceExceed(category);\n    }\n  }\n\n  public unshiftRecentSticker(doc: MyDocument) {\n    this.managers.appStickersManager.saveRecentSticker(doc.id);\n  }\n\n  public deleteRecentSticker(doc: MyDocument) {\n    this.managers.appStickersManager.saveRecentSticker(doc.id, true);\n  }\n\n  public setTyping = (cancel = false) => {\n    if(!cancel && (!this.emoticonsDropdown.isActive() || this.emoticonsDropdown.tab !== this)) {\n      return;\n    }\n\n    rootScope.dispatchEvent('choosing_sticker', !cancel);\n  };\n\n  public onClosed() {\n    this.setTyping(true);\n  }\n\n  public onOpened() {\n    this.setTyping();\n    this.resizeCategories();\n  }\n\n  public destroy() {\n    this.stickerRenderer.destroy();\n    super.destroy();\n  }\n\n  public static categoryAppendStickers(\n    tab: EmoticonsTabC<any>,\n    stickerRenderer: SuperStickerRenderer,\n    count: number,\n    category: StickersTabCategory<StickersTabItem>,\n    promise: MaybePromise<MyDocument[]>\n  ) {\n    const {container} = category.elements;\n\n    category.setCategoryItemsHeight(count);\n    container.classList.remove('hide');\n\n    return Promise.all([\n      promise,\n      apiManagerProxy.isPremiumFeaturesHidden()\n    ]).then(([documents, isPremiumFeaturesHidden]) => {\n      const isVisible = tab.isCategoryVisible(category);\n\n      const elements = documents.map((document) => {\n        if(isPremiumFeaturesHidden && getStickerEffectThumb(document)) {\n          return;\n        }\n\n        const element = stickerRenderer.renderSticker(document, undefined, undefined, category.middlewareHelper.get());\n        category.items.push({document, element});\n        return element;\n      }).filter(Boolean);\n\n      if(isVisible) {\n        category.elements.items.append(...elements);\n      }\n    });\n  }\n\n  public static async renderStickerSet(\n    tab: EmoticonsTabC<any>,\n    stickerRenderer: SuperStickerRenderer,\n    set: StickerSet.stickerSet,\n    prepend?: boolean\n  ) {\n    const category = tab.createCategory({\n      stickerSet: set,\n      title: wrapEmojiText(set.title),\n      styles: EmoticonsTabStyles.Stickers\n    });\n    const {menuTabPadding} = category.elements;\n\n    const promise = tab.managers.appStickersManager.getStickerSet(getStickerSetInputById(set));\n    this.categoryAppendStickers(\n      tab,\n      stickerRenderer,\n      set.count,\n      category,\n      promise.then((stickerSet) => stickerSet.documents as MyDocument[])\n    );\n\n    if(prepend !== undefined) {\n      tab.positionCategory(category, prepend);\n    }\n\n    tab.renderStickerSetThumb({\n      set,\n      menuTabPadding,\n      middleware: category.middlewareHelper.get()\n    });\n  }\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\nimport clamp from '@helpers/number/clamp';\nimport contextMenuController from '@helpers/contextMenuController';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport type {EmojiSkinTone, EmojiSkinToneVariants} from '@helpers/emojiSkinTone';\nimport {createRoot, For, onCleanup, onMount, Show} from 'solid-js';\nimport {Portal} from 'solid-js/web';\n\ntype EmojiTonePickerProps = {\n  variants: EmojiSkinToneVariants,\n  selectedTone: EmojiSkinTone,\n  renderEmoji: (emoji: string) => HTMLElement,\n  onSelect: (tone: EmojiSkinTone) => void,\n  ref: (element: HTMLDivElement) => void\n};\n\nfunction EmojiTonePickerButton(props: {\n  emoji: string,\n  tone: EmojiSkinTone,\n  selected: boolean,\n  renderEmoji: EmojiTonePickerProps['renderEmoji'],\n  onSelect: EmojiTonePickerProps['onSelect']\n}) {\n  let button: HTMLButtonElement;\n  const emojiElement = props.renderEmoji(props.emoji);\n  emojiElement.classList.add('emoji-tone-picker-emoji');\n\n  onMount(() => {\n    const detachClickEvent = attachClickEvent(button, (event) => {\n      cancelEvent(event);\n      props.onSelect(props.tone);\n      contextMenuController.close();\n    });\n    onCleanup(detachClickEvent);\n  });\n\n  return (\n    <button\n      ref={button}\n      class=\"btn-icon emoji-tone-picker-button\"\n      classList={{active: props.selected}}\n      type=\"button\"\n      aria-label={props.emoji}\n      aria-pressed={props.selected}\n    >\n      {emojiElement}\n    </button>\n  );\n}\n\nfunction EmojiTonePicker(props: EmojiTonePickerProps) {\n  return (\n    <div\n      ref={props.ref}\n      class=\"markup-tooltip emoji-tone-picker z-depth-1 no-transition\"\n    >\n      <div class=\"markup-tooltip-wrapper\">\n        <div class=\"markup-tooltip-tools markup-tooltip-tools-regular\">\n          <For each={props.variants}>\n            {(emoji, index) => (\n              <>\n                <Show when={index() === 1}>\n                  <span class=\"markup-tooltip-delimiter\" />\n                </Show>\n                <EmojiTonePickerButton\n                  emoji={emoji}\n                  tone={index() as EmojiSkinTone}\n                  selected={index() === props.selectedTone}\n                  renderEmoji={props.renderEmoji}\n                  onSelect={props.onSelect}\n                />\n              </>\n            )}\n          </For>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport default function showEmojiTonePicker({\n  event,\n  variants,\n  selectedTone,\n  renderEmoji,\n  onSelect\n}: {\n  event: MouseEvent | TouchEvent,\n  variants: EmojiSkinToneVariants,\n  selectedTone: EmojiSkinTone,\n  renderEmoji: (emoji: string) => HTMLElement,\n  onSelect: (tone: EmojiSkinTone) => void\n}) {\n  cancelEvent(event);\n\n  const overlayRoot = getOverlayRoot();\n  const doc = overlayRoot.ownerDocument;\n  let container: HTMLDivElement;\n  const dispose = createRoot((dispose) => {\n    <Portal mount={overlayRoot}>\n      <EmojiTonePicker\n        variants={variants}\n        selectedTone={selectedTone}\n        renderEmoji={renderEmoji}\n        onSelect={onSelect}\n        ref={(element) => container = element}\n      />\n    </Portal>;\n\n    return dispose;\n  });\n  let cleanupTimeout: number;\n\n  return {\n    show: (target: HTMLElement) => {\n      const overlayRect = overlayRoot.getBoundingClientRect();\n      const targetRect = target.getBoundingClientRect();\n      const menuRect = container.getBoundingClientRect();\n      const viewWidth = overlayRect.width || doc.defaultView.innerWidth;\n      const viewHeight = overlayRect.height || doc.defaultView.innerHeight;\n      const margin = 8;\n      const left = clamp(\n        targetRect.left - overlayRect.left + (targetRect.width - menuRect.width) / 2,\n        margin,\n        Math.max(margin, viewWidth - menuRect.width - margin)\n      );\n      const above = targetRect.top - overlayRect.top - menuRect.height - margin;\n      const below = targetRect.bottom - overlayRect.top + margin;\n      const top = above >= margin ?\n        above :\n        clamp(below, margin, Math.max(margin, viewHeight - menuRect.height - margin));\n\n      container.style.transform = `translate3d(${left}px, ${top}px, 0)`;\n      void container.offsetLeft;\n      container.classList.remove('no-transition');\n      container.classList.add('is-visible');\n    },\n    cleanup: () => {\n      if(cleanupTimeout) {\n        return;\n      }\n\n      container.classList.remove('is-visible');\n      cleanupTimeout = doc.defaultView.setTimeout(() => {\n        dispose();\n      }, 200);\n    }\n  };\n}\n","import type {MyDocument} from '@appManagers/appDocsManager';\nimport {EmoticonsDropdown} from '..';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {fastRaf} from '@helpers/schedulers';\nimport pause from '@helpers/schedulers/pause';\nimport appImManager from '@lib/appImManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport {emojiFromCodePoints} from '@vendor/emoji';\nimport {putPreloader} from '@components/putPreloader';\nimport {ScrollableX} from '@components/scrollable';\nimport IS_EMOJI_SUPPORTED from '@environment/emojiSupport';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport Emoji from '@config/emoji';\nimport fixEmoji from '@lib/richTextProcessor/fixEmoji';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapSingleEmoji from '@lib/richTextProcessor/wrapSingleEmoji';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {AppManagers} from '@lib/managers';\nimport VisibilityIntersector, {OnVisibilityChangeItem} from '@components/visibilityIntersector';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {StickerSet} from '@layer';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport findAndSpliceAll from '@helpers/array/findAndSpliceAll';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport showStickersPopup from '@components/popups/stickers';\nimport {hideToast, toastNew} from '@components/toast';\nimport safeAssign from '@helpers/object/safeAssign';\nimport liteMode from '@helpers/liteMode';\nimport CustomEmojiElement from '@lib/customEmoji/element';\nimport {CustomEmojiRendererElement} from '@lib/customEmoji/renderer';\nimport Icon from '@components/icon';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport {onCleanup} from 'solid-js';\nimport StickersTabCategory, {EmoticonsTabStyles} from '@components/emoticonsDropdown/category';\nimport EmoticonsTabC from '@components/emoticonsDropdown/tab';\nimport flatten from '@helpers/array/flatten';\nimport SuperStickerRenderer from '@components/emoticonsDropdown/tabs/SuperStickerRenderer';\nimport StickersTab from '@components/emoticonsDropdown/tabs/stickers';\nimport GroupSetController, {GROUP_SET_CATEGORY_ID, GroupSetState} from '@components/emoticonsDropdown/groupSet';\nimport {\n  createGroupSetHeaderButton,\n  getGroupSetTitle,\n  isGroupSetHidden,\n  openGroupSetTab,\n  setGroupSetHidden\n} from '@components/emoticonsDropdown/groupSetSection';\nimport {PAID_REACTION_EMOJI_DOCID} from '@lib/customEmoji/constants';\nimport {getStickerSetInputById} from '@lib/appManagers/utils/stickers/getStickerSetInput';\nimport {\n  EmojiSkinTone,\n  getEmojiSkinTone,\n  getEmojiSkinToneVariants\n} from '@helpers/emojiSkinTone';\nimport showEmojiTonePicker from '@components/emoticonsDropdown/emojiTonePicker';\n\n\nconst loadedURLs: Set<string> = new Set();\nexport function appendEmoji(_emoji: AppEmoji, unify = false) {\n  if(_emoji.docId) {\n    const customEmojiElement = CustomEmojiElement.create(_emoji.docId);\n    const spanEmoji = document.createElement('span');\n    spanEmoji.classList.add('super-emoji', 'super-emoji-custom');\n    spanEmoji.append(customEmojiElement);\n    return spanEmoji;\n  }\n  // const emoji = details.unified;\n  // const emoji = (details.unified as string).split('-')\n  // .reduce((prev, curr) => prev + String.fromCodePoint(parseInt(curr, 16)), '');\n\n  let {emoji} = _emoji;\n  const spanEmoji = document.createElement('span');\n  spanEmoji.classList.add('super-emoji', 'super-emoji-regular');\n\n  let el: DocumentFragment;\n  if(unify && !IS_EMOJI_SUPPORTED) {\n    el = wrapSingleEmoji(emoji);\n  } else {\n    emoji = fixEmoji(emoji);\n    el = wrapEmojiText(emoji);\n  }\n\n  spanEmoji.append(el);\n\n  if(spanEmoji.children.length > 1) {\n    const first = spanEmoji.firstElementChild;\n    spanEmoji.replaceChildren(first);\n  }\n\n  if(spanEmoji.firstElementChild?.tagName === 'IMG') {\n    const image = spanEmoji.firstElementChild as HTMLImageElement;\n\n    const url = image.src;\n    if(!loadedURLs.has(url)) {\n      image.setAttribute('loading', 'lazy');\n      const placeholder = document.createElement('span');\n      placeholder.classList.add('emoji-placeholder');\n\n      if(liteMode.isAvailable('animations')) {\n        image.style.opacity = '0';\n        placeholder.style.opacity = '1';\n      }\n\n      image.addEventListener('load', () => {\n        fastRaf(() => {\n          if(liteMode.isAvailable('animations')) {\n            image.style.opacity = '';\n            placeholder.style.opacity = '';\n          }\n\n          spanEmoji.classList.remove('empty');\n\n          loadedURLs.add(url);\n        });\n      }, {once: true});\n\n      spanEmoji.append(placeholder);\n    }\n  }\n\n  // spanEmoji = spanEmoji.firstElementChild as HTMLSpanElement;\n  // spanEmoji.setAttribute('emoji', emoji);\n\n  return spanEmoji;\n}\n\nexport function getEmojiFromElement(element: HTMLElement): {docId?: DocId, emoji: string} {\n  const superEmoji = findUpClassName(element, 'super-emoji');\n  if(!superEmoji) return;\n\n  const firstElementChild = superEmoji.firstElementChild as HTMLElement;\n  if(firstElementChild && firstElementChild.classList.contains('custom-emoji')) {\n    return {emoji: firstElementChild.dataset.stickerEmoji, docId: firstElementChild.dataset.docId} as const;\n  } else {\n    if(element.nodeType === element.TEXT_NODE) return {emoji: element.nodeValue};\n    if(element.tagName === 'SPAN' && !element.classList.contains('emoji') && element.firstElementChild) {\n      element = element.firstElementChild as HTMLElement;\n    }\n\n    return {emoji: element.getAttribute('alt') || element.innerText} as const;\n  }\n}\n\nconst EMOJI_RECENT_ID: (typeof EMOJI_CATEGORIES)[0][0] = 'Emoji.Recent';\nconst EMOJI_RECENT_CATEGORY: (typeof EMOJI_CATEGORIES)[0] = [EMOJI_RECENT_ID, 'recent'];\nconst CUSTOM_EMOJI_RECENT_ID: (typeof EMOJI_CATEGORIES)[0][0] = '';\nconst CUSTOM_EMOJI_RECENT_CATEGORY: (typeof EMOJI_CATEGORIES)[0] = [CUSTOM_EMOJI_RECENT_ID, ''];\nconst EMOJI_CATEGORIES: [LangPackKey | '', string][] = [\n  ['Emoji.SmilesAndPeople', 'smile'],\n  ['Emoji.AnimalsAndNature', 'animals'],\n  ['Emoji.FoodAndDrink', 'eats'],\n  ['Emoji.TravelAndPlaces', 'car'],\n  ['Emoji.ActivityAndSport', 'sport'],\n  ['Emoji.Objects', 'lamp'],\n  // ['Emoji.Symbols', 'info'],\n  ['Emoji.Flags', 'flag'],\n  ['Skin Tones' as any, '']\n];\n\nlet sorted: Map<(typeof EMOJI_CATEGORIES)[0], string[]>;\nfunction prepare() {\n  if(sorted) {\n    return sorted;\n  }\n\n  const a: Array<[(typeof EMOJI_CATEGORIES)[0], string[]]> = [\n    [CUSTOM_EMOJI_RECENT_CATEGORY, []],\n    [EMOJI_RECENT_CATEGORY, []]\n  ];\n\n  sorted = new Map(a);\n  for(const emoji in Emoji) {\n    const details = Emoji[emoji];\n    const i = '' + details;\n    const category = EMOJI_CATEGORIES[+i[0] - 1];\n    if(!category) continue; // maybe it's skin tones\n\n    let s = sorted.get(category);\n    if(!s) {\n      s = [];\n      sorted.set(category, s);\n    }\n\n    s[+i.slice(1) || 0] = emoji;\n  }\n\n  sorted.delete(EMOJI_CATEGORIES.pop());\n  EMOJI_CATEGORIES.unshift(CUSTOM_EMOJI_RECENT_CATEGORY, EMOJI_RECENT_CATEGORY);\n  const order = EMOJI_CATEGORIES.map(([id]) => id);\n  const entries = [...sorted.entries()].sort((a, b) => order.indexOf(a[0][0]) - order.indexOf(b[0][0]));\n  sorted = new Map(entries);\n\n  return sorted;\n}\n\nexport const EMOJI_ELEMENT_SIZE = makeMediaSize(42, 42);\nconst RECENT_MAX_LENGTH = 32;\n\ntype EmojiTabItem = {\n  element: HTMLElement,\n  baseEmoji?: string\n} & ReturnType<typeof getEmojiFromElement>;\nexport type EmojiTabCategory = StickersTabCategory<EmojiTabItem, {renderer: CustomEmojiRendererElement}>;\nexport default class EmojiTab extends EmoticonsTabC<EmojiTabCategory, {emojis: AppEmoji[], localStickerSet?: {title: LangPackKey, stickers: MyDocument[]}}> {\n  private closeScrollTop: number;\n  private menuInnerScroll: ScrollableX;\n  private isStandalone?: boolean;\n  private noRegularEmoji?: boolean;\n  private noSearchGroups?: boolean;\n  private mainSets: () => (Promise<DocId[]> | Array<Promise<DocId[]>>);\n  private additionalSets: () => Promise<StickerSet.stickerSet[]>;\n  private additionalLocalStickerSet: () => Promise<{title: LangPackKey, stickers: MyDocument[]}>;\n  private onClick: (emoji: EmojiTabItem) => void;\n  private activeEmoji: ReturnType<typeof getEmojiFromElement>;\n  private activeElements: EmojiTabItem[];\n  private noPacks: boolean;\n  private noSearch: boolean;\n  private preloaderDelay: number;\n  private freeCustomEmoji: Set<DocId>;\n  private canHaveEmojiTimer?: boolean;\n  private onReady: () => void;\n  private stickerRenderer: SuperStickerRenderer;\n  private showLocks: boolean;\n  private nativeEmojiFadeReady: boolean;\n  private canUsePremiumEmojiAlways?: boolean;\n  private emojiVariants: {[emoji: string]: EmojiSkinTone};\n  private groupSetController: GroupSetController;\n  private groupSetHidden: boolean;\n  public initPromise: Promise<void>;\n\n  constructor(options: {\n    managers: AppManagers,\n    isStandalone?: boolean,\n    noRegularEmoji?: boolean,\n    noSearchGroups?: boolean,\n    mainSets?: EmojiTab['mainSets'],\n    additionalSets?: EmojiTab['additionalSets'],\n    additionalLocalStickerSet?: EmojiTab['additionalLocalStickerSet'],\n    onClick?: EmojiTab['onClick'],\n    noPacks?: EmojiTab['noPacks'],\n    noSearch?: EmojiTab['noSearch'],\n    additionalStickerViewerClass?: EmojiTab['additionalStickerViewerClass'],\n    preloaderDelay?: EmojiTab['preloaderDelay'],\n    freeCustomEmoji?: EmojiTab['freeCustomEmoji'],\n    canHaveEmojiTimer?: EmojiTab['canHaveEmojiTimer'],\n    onReady?: EmojiTab['onReady'],\n    searchFetcher?: EmojiTab['searchFetcher'],\n    groupFetcher?: EmojiTab['groupFetcher'],\n    canUsePremiumEmojiAlways?: boolean,\n    showLocks?: boolean\n  }) {\n    super({\n      managers: options.managers,\n      noMenu: options.noPacks,\n      additionalStickerViewerClass: options.additionalStickerViewerClass,\n      searchFetcher: options.noSearch ? undefined : async(value) => {\n        if(!value) return {emojis: []};\n\n        if(options.searchFetcher) {\n          return options.searchFetcher(value);\n        }\n\n        return {emojis: await this.managers.appEmojiManager.prepareAndSearchEmojis({q: value, limit: Infinity, minChars: 1, addCustom: true})};\n      },\n      groupFetcher: options.noSearchGroups ? undefined : options.groupFetcher ? options.groupFetcher : async(group) => {\n        if(group?._ !== 'emojiGroup') return {emojis: []};\n\n        if(options.groupFetcher) {\n          return options.groupFetcher(group);\n        }\n\n        const emojiList = await this.managers.appEmojiManager.searchCustomEmoji(group.emoticons.join(''));\n\n        const emojis: AppEmoji[] = [\n          ...emojiList.document_id.map((docId) => ({docId, emoji: ''})),\n          ...group.emoticons.map((emoji) => ({emoji}))\n        ];\n\n        return {emojis};\n      },\n      processSearchResult: async({data, searching, grouping}) => {\n        const {emojis, localStickerSet} = data || {};\n        if(!emojis || (!searching && !grouping)) {\n          return;\n        }\n\n        if(!emojis.length && !localStickerSet) {\n          const span = i18n('NoEmojiFound');\n          span.classList.add('emoticons-not-found');\n          return span;\n        }\n\n        const container = this.categoriesContainer.cloneNode(false) as HTMLElement;\n        const category = this.createCategory({styles: EmoticonsTabStyles.Emoji});\n        this.createEmojiRendererForCategory(category);\n        for(const emoji of emojis) {\n          this.addEmojiToCategory({\n            category: category,\n            emoji,\n            batch: true\n          });\n        }\n        category.setCategoryItemsHeight(emojis.length);\n        category.elements.container.style.paddingTop = '.5rem';\n        category.elements.container.classList.remove('hide');\n        this._onCategoryVisibility(category, true);\n\n        const renderedCategories: EmojiTabCategory[] = [category];\n        if(localStickerSet) {\n          const category = this.renderLocalStickerSet(localStickerSet);\n          renderedCategories.push(category);\n        }\n\n        container.append(...renderedCategories.map((category) => category.elements.container));\n\n        onCleanup(() => {\n          renderedCategories.forEach((category) => {\n            category.middlewareHelper.destroy();\n          });\n        });\n\n        return container;\n      },\n      searchNoLoader: true,\n      searchPlaceholder: 'SearchEmoji',\n      searchType: 'emoji'\n    });\n\n    safeAssign(this, options);\n    this.container.classList.add('emoji-padding');\n    this.content.id = 'content-emoji';\n    this.activeElements = [];\n    this.freeCustomEmoji ??= new Set();\n    this.emojiVariants = {};\n  }\n\n  public _onCategoryVisibility(category: EmojiTabCategory, visible: boolean) {\n    // console.log(target, visible, category);\n    // if(category.local) return;\n\n    const renderer = category.elements.renderer;\n    const newChildren: HTMLElement[] = [];\n    if(renderer) {\n      newChildren.push(renderer);\n      const customEmojis: Parameters<CustomEmojiRendererElement['add']>[0]['addCustomEmojis'] = new Map();\n      if(visible) {\n        newChildren.push(...category.items.map(({docId, element}) => {\n          if(!docId) {\n            return element;\n          }\n\n          // return element;\n\n          // if(element.firstElementChild) {\n          //   return element;\n          // }\n\n          const customEmojiElement = element.firstElementChild as CustomEmojiElement;\n          customEmojiElement.clear(false);\n          // const customEmojiElement = CustomEmojiElement.create(document.id);\n          customEmojis.set(customEmojiElement.docId, new Set([customEmojiElement]));\n          // element.append(customEmojiElement);\n          return element;\n        }));\n\n        renderer.add({\n          addCustomEmojis: customEmojis\n        });\n      } else {\n        renderer.clearCanvas();\n        renderer.middlewareHelper.clean();\n      }\n    } else if(visible) {\n      newChildren.push(...category.items.map(({element}) => element));\n    }\n\n    // if(visible)\n    category.elements.items.replaceChildren(...newChildren);\n\n    if(visible && this.nativeEmojiFadeReady) {\n      this.fadeInNativeEmojis(newChildren);\n    }\n\n    if(renderer && !visible) {\n      const customEmojis: Parameters<CustomEmojiRendererElement['add']>[0]['addCustomEmojis'] = new Map();\n      category.items.forEach(({docId, element}) => {\n        if(!docId) {\n          return;\n        }\n\n        const customEmojiElement = element.firstElementChild as CustomEmojiElement;\n        customEmojiElement.clear();\n        customEmojis.set(customEmojiElement.docId, new Set([customEmojiElement]));\n      });\n\n      /* const promise =  */renderer.add({\n        addCustomEmojis: customEmojis,\n        onlyThumb: true\n      });\n      // promise.then(() => {\n      //   customEmojis.forEach((elements) => {\n      //     elements.forEach((element) => {\n      //       if(!element.innerHTML) {\n      //         console.log('no thumb', element);\n      //         // debugger;\n      //       }\n      //     });\n      //   });\n\n      //   const set = customEmojis.get('5766933926429854499');\n      //   console.log(`wrapped ${customEmojis.size} thumbs`, set && set.values().next().value.innerHTML);\n      // });\n    }\n\n    // if(!visible) {\n    //   const customEmojis: Parameters<CustomEmojiRendererElement['add']>[0] = {};\n    //   category.items.forEach((item) => {\n    //     const {element, document} = item;\n    //     if(!element.firstElementChild) {\n    //       return;\n    //     }\n\n    //     const customEmojiElement = CustomEmojiElement.create(document.id);\n    //     customEmojis[customEmojiElement.docId] = new Set([customEmojiElement]);\n    //     element.firstElementChild.replaceWith(customEmojiElement);\n    //   });\n\n    //   renderer.add(customEmojis, EmoticonsDropdown.lazyLoadQueue);\n    // }\n  }\n\n  private onCategoryVisibility = ({target, visible}: Pick<OnVisibilityChangeItem, 'target' | 'visible'>) => {\n    const category = this.categoriesMap.get(target);\n    // the set's documents resolve asynchronously, so this can fire for a category that was\n    // already deleted — leaving a chat drops the group's pack that way\n    if(!category) {\n      return;\n    }\n\n    this._onCategoryVisibility(category, visible);\n  };\n\n  private fadeInNativeEmojis(parents: HTMLElement[]) {\n    const natives: HTMLElement[] = [];\n    for(const parent of parents) {\n      const child = parent.firstElementChild as HTMLElement | null;\n      if(child?.classList.contains('emoji-native')) {\n        natives.push(child);\n      }\n    }\n    if(!natives.length) return;\n    natives.forEach((el) => { el.style.opacity = '0'; });\n    fastRaf(() => natives.forEach((el) => { el.style.opacity = ''; }));\n  }\n\n  public destroy() {\n    super.destroy();\n    this.menuInnerScroll?.destroy();\n  }\n\n  public init() {\n    super.init();\n    this.init = undefined;\n\n    const intersectionOptions: IntersectionObserverInit = {\n      root: this.isStandalone ? this.content : this.emoticonsDropdown.getElement()\n    };\n\n    this.categoriesIntersector = new VisibilityIntersector(this.onCategoryVisibility, intersectionOptions);\n\n    if(this.menu) this.menuOnClickResult = EmoticonsDropdown.menuOnClick(\n      this,\n      this.menu,\n      this.scrollable,\n      this.menuScroll,\n      undefined,\n      this.listenerSetter\n    );\n\n    const preloader = putPreloader(this.content, true);\n\n    let innerScrollWrapper: HTMLElement;\n\n    if(!this.isStandalone && this.menu) {\n      const x = this.menuInnerScroll = new ScrollableX(undefined);\n      x.container.classList.add('menu-horizontal-inner-scroll');\n\n      innerScrollWrapper = document.createElement('div');\n      innerScrollWrapper.classList.add('menu-horizontal-inner');\n      innerScrollWrapper.append(x.container);\n    }\n\n    let preparedMap: ReturnType<typeof prepare>;\n    prepare();\n    if(!this.noRegularEmoji) {\n      preparedMap = prepare();\n    } else {\n      preparedMap = new Map([\n        [[CUSTOM_EMOJI_RECENT_CATEGORY[0], 'recent'], []]\n        // [EMOJI_RECENT_CATEGORY, []]\n      ]);\n\n      if(this.menu) {\n        preparedMap.set([EMOJI_RECENT_CATEGORY[0], ''], []);\n      }\n    }\n\n    preparedMap.forEach((emojis, [titleLangPackKey, icon]) => {\n      const category = this.createLocalCategory({\n        id: titleLangPackKey,\n        title: titleLangPackKey,\n        icon: icon as Icon,\n        noMenuTab: !icon,\n        styles: EmoticonsTabStyles.Emoji\n      });\n      category.elements.container.classList.remove('hide');\n\n      emojis.forEach((unified) => {\n        /* if(emojiUnicode(emoji) === '1f481-200d-2642') {\n          console.log('append emoji', emoji, emojiUnicode(emoji));\n        } */\n\n        const emoji = emojiFromCodePoints(unified);\n        // if(emoji.includes('🕵')) {\n        // console.log('toCodePoints', toCodePoints(emoji));\n        // emoji = emoji.replace(/(\\u200d[\\u2640\\u2642\\u2695])(?!\\ufe0f)/, '\\ufe0f$1');\n        // const zwjIndex = emoji.indexOf('\\u200d');\n        // if(zwjIndex !== -1 && !emoji.includes('\\ufe0f')) {\n        //   /* if(zwjIndex !== (emoji.length - 1)) {\n        //     emoji = emoji.replace(/(\\u200d)/g, '\\ufe0f$1');\n        //   } */\n\n        //   emoji += '\\ufe0f';\n        //   //emoji += '\\ufe0f';\n        // }\n\n        // debugger;\n        // }\n\n        this.addEmojiToCategory({\n          category,\n          emoji: {emoji},\n          batch: true\n        });\n\n        /* if(category === 'Smileys & Emotion') {\n          console.log('appended emoji', emoji, itemsDiv.children[itemsDiv.childElementCount - 1].innerHTML, emojiUnicode(emoji));\n        } */\n      });\n    });\n\n    const mainSetsResult = this.mainSets?.();\n    const promise = Promise.all([\n      !this.preloaderDelay ? undefined : pause(this.preloaderDelay),\n      !this.noRegularEmoji && this.managers.appEmojiManager.getRecentEmojis('native'),\n      !this.isStandalone && this.managers.appEmojiManager.getRecentEmojis('custom'),\n      !this.noPacks && Promise.resolve(apiManagerProxy.isPremiumFeaturesHidden()).then((isPremiumPurchaseHidden) => {\n        return isPremiumPurchaseHidden ? undefined : this.managers.appEmojiManager.getCustomEmojis();\n      }),\n      mainSetsResult && Promise.all(Array.isArray(mainSetsResult) ? mainSetsResult : [mainSetsResult]),\n      this.additionalSets?.(),\n      this.additionalLocalStickerSet?.(),\n      !this.noRegularEmoji && this.managers.appEmojiManager.getEmojiVariants()\n    ]).then(([_, recent, recentCustom, sets, mainSets, additionalSets, additionalLocalStickerSet, emojiVariants]) => {\n      this.emojiVariants = emojiVariants || {};\n      this.applySavedEmojiVariants();\n      preloader.remove();\n\n      // Native emojis (IS_EMOJI_SUPPORTED === true) have no load event, so without\n      // staging they pop in the moment IntersectionObserver inserts them into the\n      // DOM. Flip the gate now so that `_onCategoryVisibility` starts applying a\n      // JS-driven opacity transition for subsequent insertions, and retroactively\n      // fade any category that's already been mounted and populated.\n      if(IS_EMOJI_SUPPORTED && liteMode.isAvailable('animations')) {\n        this.nativeEmojiFadeReady = true;\n        for(const category of this.categoriesMap.values()) {\n          if(this.isCategoryVisible(category)) {\n            this.fadeInNativeEmojis(Array.from(category.elements.items.children) as HTMLElement[]);\n          }\n        }\n      }\n\n      const docIdsToCustomEmoji = (docIds: DocId[]): ReturnType<typeof getEmojiFromElement>[] => {\n        return docIds.map((docId) => {\n          return {emoji: '', docId};\n        });\n      };\n\n      let recentEmojis: ReturnType<typeof getEmojiFromElement>[], recentCustomEmojis: typeof recentEmojis;\n      if(mainSets) {\n        recentCustomEmojis = docIdsToCustomEmoji(mainSets[0]);\n        if(mainSets[1]) recentEmojis = docIdsToCustomEmoji(mainSets[1]);\n      }\n\n      if(!recentEmojis && recent) {\n        recentEmojis = recent.map((emoji) => ({emoji}));\n      }\n\n      if(!recentCustomEmojis && recentCustom) {\n        recentCustomEmojis = docIdsToCustomEmoji(recentCustom);\n      }\n\n      const recentCategory = this.categories[EMOJI_RECENT_ID];\n      const recentCustomCategory = this.categories[CUSTOM_EMOJI_RECENT_ID];\n\n      if(!this.noRegularEmoji) {\n        const a = [\n          recentCategory && [recentCategory, recent] as const,\n          recentCustomCategory && [recentCustomCategory, recentCustom] as const\n        ];\n\n        a.filter(Boolean).forEach(([category, recent]) => {\n          category.limit = RECENT_MAX_LENGTH;\n          recent.splice(RECENT_MAX_LENGTH, recent.length - RECENT_MAX_LENGTH);\n        });\n      }\n\n      if(recentCategory) {\n        this.createEmojiRendererForCategory(recentCategory);\n        if(recentEmojis?.length) for(const emoji of recentEmojis) {\n          this.addEmojiToCategory({\n            category: recentCategory,\n            emoji,\n            batch: true\n          });\n        }\n      }\n\n      if(recentCustomCategory) {\n        this.createEmojiRendererForCategory(recentCustomCategory);\n        if(recentCustomEmojis?.length) for(const emoji of recentCustomEmojis) {\n          this.addEmojiToCategory({\n            category: recentCustomCategory,\n            emoji,\n            batch: true\n          });\n        }\n        recentCustomCategory.elements.container.style.paddingTop = '.5rem';\n        if(this.noMenu) {\n          recentCustomCategory.elements.container.style.paddingBottom = '.5rem';\n        }\n      }\n\n      EMOJI_CATEGORIES.forEach(([id]) => {\n        const category = this.categories[id];\n        if(!category) {\n          return;\n        }\n\n        this.toggleLocalCategory(category, !!category.items.length);\n\n        if(id !== EMOJI_RECENT_ID && id !== CUSTOM_EMOJI_RECENT_ID) {\n          category.menuScroll = this.menuInnerScroll;\n          this.menuInnerScroll?.append(category.elements.menuTab);\n        }\n      });\n\n      this.resizeCategories();\n\n      if(recentCategory && innerScrollWrapper && recentCategory.elements.menuTab) {\n        recentCategory.elements.menuTab.after(innerScrollWrapper);\n      }\n\n      flatten([sets?.sets, additionalSets].filter(Boolean)).forEach((set) => {\n        this.renderEmojiSet(set);\n      });\n\n      if(additionalLocalStickerSet) {\n        const category = this.renderLocalStickerSet(additionalLocalStickerSet);\n        this.categoriesContainer.append(category.elements.container);\n      }\n\n      this.continueInit();\n    });\n\n    attachClickEvent(this.content, this.onContentClick, {listenerSetter: this.listenerSetter});\n\n    const recentCategory = this.categories[EMOJI_RECENT_ID];\n    const recentCustomCategory = this.categories[CUSTOM_EMOJI_RECENT_ID];\n    this.attachHelpers({\n      getTextColor: this.textColor,\n      verifyRecent: (target) => !!(findUpAsChild(target, recentCustomCategory.elements.items) || findUpAsChild(target, recentCategory.elements.items)),\n      canHaveEmojiTimer: this.canHaveEmojiTimer,\n      onContextMenu: this.onContextMenu\n    });\n\n    return this.initPromise = promise;\n  }\n\n  private renderLocalStickerSet(localStickerSet: {title: LangPackKey, stickers: MyDocument[]}) {\n    this.stickerRenderer ??= this.createStickerRenderer();\n    const category = this.createLocalCategory({\n      title: localStickerSet.title,\n      styles: EmoticonsTabStyles.Stickers,\n      noMenuTab: true\n    });\n\n    StickersTab.categoryAppendStickers(\n      this,\n      this.stickerRenderer,\n      localStickerSet.stickers.length,\n      category as any,\n      localStickerSet.stickers\n    ).then(() => {\n      StickersTab._onCategoryVisibility(category, true);\n    });\n\n    category.elements.container.style.paddingBottom = (EmoticonsTabStyles.Stickers.padding / 2) + 'px';\n    return category;\n  }\n\n  private continueInit() {\n    this.listenerSetter.add(rootScope)('premium_toggle', () => {\n      this.toggleCustomCategory();\n    });\n\n    this.listenerSetter.add(rootScope)('stickers_top', this.postponedEvent((id) => {\n      const category = this.categories[id];\n      if(!category) {\n        return;\n      }\n\n      this.positionCategory(category, true);\n\n      this.listenerSetter.add(this.emoticonsDropdown)('openAfterLayout', () => {\n        this.menuOnClickResult.setActiveStatic(category);\n      }, {once: true});\n    }));\n\n    const toggleRenderers = (ignore: boolean) => {\n      for(const id in this.categories) {\n        const category = this.categories[id];\n        const renderer = category.elements.renderer;\n        if(renderer) {\n          renderer.ignoreSettingDimensions = ignore;\n          if(!ignore) {\n            renderer.setDimensionsFromRect(undefined, true);\n          }\n        }\n      }\n    };\n\n    !this.isStandalone && this.listenerSetter.add(this.emoticonsDropdown)('opened', () => {\n      toggleRenderers(false);\n    });\n\n    !this.isStandalone && this.listenerSetter.add(this.emoticonsDropdown)('close', () => {\n      toggleRenderers(true);\n    });\n\n    this.initGroupSet();\n\n    this.listenerSetter.add(rootScope)('stickers_installed', (set) => {\n      if(!this.categories[set.id] && set.pFlags.emojis) {\n        this.renderEmojiSet(set, true);\n        this.repositionGroupSet();\n        // installing the group's own pack gives it a category of its own — the group one\n        // beside it would be a duplicate\n        this.groupSetController?.update();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('stickers_deleted', (set) => {\n      const category = this.categories[set.id];\n      if(this.deleteCategory(category)) {\n        const {renderer} = category.elements;\n        if(renderer) {\n          renderer.middlewareHelper.clean();\n        }\n      }\n\n      // uninstalling may turn a deduped group pack into one worth showing on its own\n      this.groupSetController?.update();\n    });\n\n    this.listenerSetter.add(rootScope)('emoji_variant', ({baseEmoji, tone}) => {\n      this.applyEmojiVariant(baseEmoji, tone);\n    });\n\n    const onEmojiRecent = ({emoji, deleted}: BroadcastEvents['emoji_recent']) => {\n      const category = this.categories[emoji.docId ? CUSTOM_EMOJI_RECENT_ID : EMOJI_RECENT_ID];\n      if(!category) {\n        return;\n      }\n\n      const toneVariants = !emoji.docId && getEmojiSkinToneVariants(emoji.emoji);\n      const verify: (item: EmojiTabItem) => boolean = emoji.docId ?\n        (item) => item.docId === emoji.docId :\n        toneVariants ?\n          (item) => item.baseEmoji === toneVariants.baseEmoji :\n          (item) => item.emoji === emoji.emoji;\n      const found = findAndSplice(category.items, verify);\n      if(deleted) {\n        // a use of this emoji may be waiting in the queue for the panel to hide — deleting it\n        // now must not let that put it back\n        findAndSpliceAll(this.postponedEvents, (event) => {\n          if(event.cb !== onEmojiRecent) {\n            return false;\n          }\n\n          const other = (event.args[0] as BroadcastEvents['emoji_recent']).emoji;\n          return emoji.docId ? other.docId === emoji.docId : other.emoji === emoji.emoji;\n        });\n\n        if(!found) {\n          return;\n        }\n\n        found.element.remove();\n        if(this.isCategoryVisible(category)) {\n          this.onLocalCategoryUpdate(category);\n        }\n      } else if(found) {\n        category.items.unshift(found);\n        if(this.isCategoryVisible(category)) {\n          const {renderer} = category.elements;\n          positionElementByIndex(found.element, category.elements.items, renderer ? 1 : 0, -1);\n          renderer?.forceRender();\n        }\n      } else {\n        this.addEmojiToCategory({\n          category,\n          emoji,\n          batch: false,\n          prepend: true\n        });\n      }\n\n      if(this.closeScrollTop === 0) {\n        this.menuOnClickResult.setActive(emoji.docId ? this.categories[EMOJI_RECENT_ID] : category);\n      }\n    };\n\n    const onEmojiRecentPostponed = this.postponedEvent(onEmojiRecent);\n    !this.noRegularEmoji && this.listenerSetter.add(rootScope)('emoji_recent', (data) => {\n      // using an emoji reshuffles the recent row, so it waits for the panel to hide — the panel\n      // stays open while typing; deleting one is the user's own doing right there in it and\n      // lands at once\n      (data.deleted ? onEmojiRecent : onEmojiRecentPostponed)(data);\n    });\n\n    this.toggleCustomCategory();\n\n    this.menuOnClickResult?.setActive([\n      this.categories[EMOJI_RECENT_ID],\n      this.categories[CUSTOM_EMOJI_RECENT_ID]\n    ].find((category) => !!category.elements.menuTab));\n\n    this.onReady?.();\n  }\n\n  private get peerId() {\n    return (this.emoticonsDropdown ? this.emoticonsDropdown.chatInput?.chat?.peerId : NULL_PEER_ID) ?? NULL_PEER_ID;\n  }\n\n  public getCustomCategory() {\n    return this.categories[CUSTOM_EMOJI_RECENT_ID];\n  }\n\n  public toggleCustomCategory() {\n    const category = this.categories[CUSTOM_EMOJI_RECENT_ID];\n    const hasPremium = rootScope.premium || this.peerId === rootScope.myId || !!this.mainSets;\n    const canSeeCustomCategory = hasPremium || this.isStandalone;\n    super.toggleLocalCategory(category, !!category.items.length && canSeeCustomCategory);\n    this.content.classList.toggle('has-premium', hasPremium);\n  }\n\n  protected toggleLocalCategory(category: EmojiTabCategory, visible: boolean) {\n    if(category.id === CUSTOM_EMOJI_RECENT_ID) {\n      this.toggleCustomCategory();\n      return;\n    }\n\n    super.toggleLocalCategory(category, visible);\n  }\n\n  private initGroupSet() {\n    this.groupSetController = new GroupSetController({\n      managers: this.managers,\n      listenerSetter: this.listenerSetter,\n      isEmoji: true,\n      getPeerId: () => this.emoticonsDropdown ? this.emoticonsDropdown.chatInput?.chat?.peerId : undefined,\n      isHidden: (chatId, set) => isGroupSetHidden(chatId, set, true),\n      isInstalled: (set) => !!this.categories[set.id],\n      render: (state) => this.renderGroupSet(state),\n      remove: () => {\n        const category = this.categories[GROUP_SET_CATEGORY_ID];\n        if(this.deleteCategory(category)) {\n          category.elements.renderer?.middlewareHelper.clean();\n        }\n      }\n    });\n\n    if(!this.isStandalone) {\n      this.listenerSetter.add(this.emoticonsDropdown)('opened', () => this.groupSetController.update());\n      // the tab is built on the first open, after that open's event already fired\n      this.groupSetController.update();\n    }\n  }\n\n  public onPeerChanged() {\n    if(!this.groupSetController) {\n      return;\n    }\n\n    this.groupSetController.clear();\n    // an open dropdown has to swap the pack right away; a closed one resolves on its next open\n    if(this.emoticonsDropdown?.isActive()) {\n      this.groupSetController.update();\n    }\n  }\n\n  /**\n   * Reuses the menu tab's own click: it already handles making the category active and\n   * scrolling the panel to it, including the bookkeeping that keeps the scroll spy quiet.\n   */\n  private scrollToGroupSet() {\n    const menuTab = this.categories[GROUP_SET_CATEGORY_ID]?.elements.menuTab;\n    if(menuTab) {\n      simulateClickEvent(menuTab);\n    }\n  }\n\n  /**\n   * A collapsed section belongs below every other pack, but packs keep arriving — the initial\n   * load and later installs both append — so its place has to be reclaimed afterwards.\n   */\n  private repositionGroupSet() {\n    const category = this.categories[GROUP_SET_CATEGORY_ID];\n    if(category && this.groupSetHidden) {\n      this.positionCategory(category, false);\n    }\n  }\n\n  private renderGroupSet(state: GroupSetState) {\n    const {set, canEdit, hidden} = state;\n    this.groupSetHidden = hidden;\n    const chatId = this.groupSetController.getCurrentChatId();\n    const category = set ?\n      this.renderEmojiSet(set, !hidden, true) :\n      this.createCategory({\n        id: GROUP_SET_CATEGORY_ID,\n        title: getGroupSetTitle(undefined, true),\n        styles: EmoticonsTabStyles.Emoji\n      });\n\n    if(!set) {\n      // nothing configured yet: an empty section whose only job is to lead an admin to setup\n      this.positionCategory(category, true);\n      category.elements.container.classList.remove('hide');\n      category.elements.menuTab.append(Icon('smile'));\n    }\n\n    category.elements.title.append(createGroupSetHeaderButton({\n      canEdit,\n      hidden,\n      isEmoji: true,\n      onClick: () => {\n        if(canEdit) {\n          openGroupSetTab(chatId, true);\n          return;\n        }\n\n        setGroupSetHidden(chatId, set, true, !hidden);\n        this.groupSetController.update().then(() => {\n          // bringing it back should show it, not just move it up the list\n          if(hidden) this.scrollToGroupSet();\n        });\n      }\n    }));\n  }\n\n  /**\n   * `isGroupSet` marks the pack the open group offers to its members: everyone there may\n   * use it, Premium or not, so it carries neither the lock badge nor the click gate, and it\n   * is filed under a synthetic id so it never fights the user's own copy for the slot.\n   */\n  protected renderEmojiSet(set: StickerSet.stickerSet, prepend?: boolean, isGroupSet?: boolean) {\n    const category = this.createCategory({\n      stickerSet: set,\n      id: isGroupSet ? GROUP_SET_CATEGORY_ID : undefined,\n      title: wrapEmojiText(set.title),\n      styles: EmoticonsTabStyles.Emoji\n    });\n    this.positionCategory(category, prepend);\n    const {container, menuTabPadding} = category.elements;\n    category.elements.items.classList.add('not-local');\n    if(!isGroupSet) {\n      category.elements.container.classList.add('is-premium-set');\n      category.elements.title.prepend(Icon('premium_lock', 'category-title-lock'));\n    }\n\n    this.createEmojiRendererForCategory(category);\n\n    category.setCategoryItemsHeight(set.count);\n    container.classList.remove('hide');\n\n    const promise = this.managers.appStickersManager.getStickerSet(getStickerSetInputById(set));\n    promise.then(({documents}) => {\n      if(isGroupSet) {\n        // must be marked free before the items render, or they'd come out locked\n        documents.forEach((document) => this.freeCustomEmoji.add(document.id));\n      }\n\n      documents.forEach((document) => {\n        this.addEmojiToCategory({\n          category,\n          emoji: {docId: document.id, emoji: (document as MyDocument).stickerEmojiRaw},\n          batch: true\n        });\n      });\n\n      // if(this.isCategoryVisible(category)) {\n      //   category.elements.items.append(...category.items.map(({element}) => element));\n      // }\n\n      this.onCategoryVisibility({target: category.elements.container, visible: this.isCategoryVisible(category)});\n    });\n\n    this.renderStickerSetThumb({\n      set,\n      menuTabPadding,\n      middleware: category.middlewareHelper.get(),\n      textColor: this.textColor\n    });\n\n    return category;\n  }\n\n  private createEmojiRendererForCategory(category: EmojiTabCategory) {\n    const middleware = category.middlewareHelper.get();\n    const renderer = CustomEmojiRendererElement.create({\n      animationGroup: this.animationGroup,\n      customEmojiSize: mediaSizes.active.esgCustomEmoji,\n      textColor: this.textColor,\n      middleware\n    });\n\n    category.elements.renderer = renderer;\n    category.elements.items.append(renderer);\n  }\n\n  private updateEmojiItemTone(item: EmojiTabItem, tone: EmojiSkinTone) {\n    const toneVariants = item.baseEmoji && getEmojiSkinToneVariants(item.baseEmoji);\n    if(!toneVariants) {\n      return;\n    }\n\n    const emoji = toneVariants.variants[tone];\n    if(item.emoji === emoji) {\n      return;\n    }\n\n    item.emoji = emoji;\n    const renderedEmoji = appendEmoji({emoji});\n    item.element.replaceChildren(...Array.from(renderedEmoji.childNodes));\n  }\n\n  private applySavedEmojiVariants() {\n    this.categoriesMap.forEach((category) => {\n      category.items.forEach((item) => {\n        const tone = item.baseEmoji && this.emojiVariants[item.baseEmoji];\n        if(tone !== undefined) {\n          this.updateEmojiItemTone(item, tone);\n        }\n      });\n    });\n  }\n\n  private applyEmojiVariant(baseEmoji: string, tone: EmojiSkinTone) {\n    this.emojiVariants[baseEmoji] = tone;\n    this.categoriesMap.forEach((category) => {\n      category.items.forEach((item) => {\n        if(item.baseEmoji === baseEmoji) {\n          this.updateEmojiItemTone(item, tone);\n        }\n      });\n    });\n  }\n\n  private onContextMenu = (event: MouseEvent | TouchEvent) => {\n    const target = findUpClassName(event.target, 'super-emoji');\n    const emoji = target && getEmojiFromElement(target.firstElementChild as HTMLElement);\n    if(!emoji || emoji.docId) {\n      return;\n    }\n\n    const toneVariants = getEmojiSkinToneVariants(emoji.emoji);\n    if(!toneVariants) {\n      return;\n    }\n\n    const {baseEmoji, variants} = toneVariants;\n    const picker = showEmojiTonePicker({\n      event,\n      variants,\n      selectedTone: this.emojiVariants[baseEmoji] ?? getEmojiSkinTone(emoji.emoji),\n      renderEmoji: (emoji) => appendEmoji({emoji}),\n      onSelect: (tone) => {\n        this.applyEmojiVariant(baseEmoji, tone);\n        this.managers.appEmojiManager.saveEmojiVariant(baseEmoji, tone);\n      }\n    });\n    this.emoticonsDropdown?.setIgnoreMouseOut('tooltip', true);\n    return {\n      cleanup: () => {\n        picker.cleanup();\n        this.emoticonsDropdown?.setIgnoreMouseOut('tooltip', false);\n      },\n      onMenuOpen: picker.show\n    };\n  };\n\n  public addEmojiToCategory(options: {\n    category: EmojiTabCategory,\n    emoji?: ReturnType<typeof getEmojiFromElement>,\n    element?: HTMLElement,\n    batch?: boolean,\n    prepend?: boolean,\n    active?: boolean\n  }) {\n    const {category, batch, prepend} = options;\n    let {emoji} = options;\n    let element = options.element;\n    let baseEmoji: string;\n    if(emoji && !emoji.docId) {\n      const toneVariants = getEmojiSkinToneVariants(emoji.emoji);\n      if(toneVariants) {\n        baseEmoji = toneVariants.baseEmoji;\n        const tone = this.emojiVariants[baseEmoji] ?? getEmojiSkinTone(emoji.emoji);\n        emoji = {\n          ...emoji,\n          emoji: toneVariants.variants[tone]\n        };\n      }\n    }\n\n    if(element) {\n      const spanEmoji = document.createElement('span');\n      spanEmoji.classList.add('super-emoji');\n      spanEmoji.append(element);\n      element = spanEmoji;\n    } else {\n      element = appendEmoji(emoji/* .replace(/[\\ufe0f\\u2640\\u2642\\u2695]/g, '') *//* , false */);\n\n      if(this.showLocks && !this.canUseEmoji(emoji, category)) {\n        element.append(Icon('premium_lock', 'premium-sticker-lock'));\n      }\n    }\n\n    const item: typeof category['items'][0] = {\n      ...(emoji || {emoji: undefined}),\n      baseEmoji,\n      element\n    };\n\n    if(\n      options.active || (\n        this.activeEmoji && (\n          item.docId ?\n            this.activeEmoji.docId === item.docId :\n            this.activeEmoji.emoji === item.emoji\n        )\n      )\n    ) {\n      this.activeEmoji === emoji;\n      this.activeElements.push(item);\n      element.classList.add('active');\n    }\n\n    category.items[prepend ? 'unshift' : 'push'](item);\n    if(!batch && !this.spliceExceed(category)) {\n      this.onLocalCategoryUpdate(category);\n    }\n  }\n\n  // private addEmojisToCategory(category: EmojiTabCategory, emojis: string[], prepend?: boolean) {\n  //   emojis.forEach((emoji) => {\n  //     this.addEmojiToCategory(category, emoji, true, prepend);\n  //   });\n\n  //   this.onLocalCategoryUpdate(category);\n  // }\n\n  public canUseEmoji(emoji: ReturnType<typeof getEmojiFromElement>, category?: EmojiTabCategory, showToast?: boolean) {\n    if(emoji.docId === PAID_REACTION_EMOJI_DOCID) return true\n    if(\n      emoji.docId &&\n      !rootScope.premium && (\n        this.isStandalone && category ? category.id !== CUSTOM_EMOJI_RECENT_ID : this.peerId !== rootScope.myId\n      ) && !this.freeCustomEmoji.has(emoji.docId) &&\n      !this.canUsePremiumEmojiAlways\n    ) {\n      if(showToast) {\n        const a = anchorCallback(() => {\n          hideToast();\n          appImManager.openPremiumBot();\n        });\n        toastNew({\n          langPackKey: 'CustomEmoji.PremiumAlert',\n          langPackArguments: [a]\n        });\n      }\n\n      return false;\n    }\n\n    return true;\n  }\n\n  private onContentClick = (e: MouseEvent) => {\n    const {target} = e;\n    const container = findUpClassName(target, 'emoji-category');\n    if(!container) {\n      return;\n    }\n\n    cancelEvent(e);\n    const category = this.categoriesMap.get(container);\n    if(!category) { // possibly sticker\n      const sticker = findUpClassName(target, 'super-sticker');\n      if(sticker) {\n        this.onClick?.({\n          emoji: '',\n          docId: sticker.dataset.docId,\n          element: sticker\n        });\n        return;\n      }\n    }\n\n    if(findUpClassName(target, 'category-title')) {\n      if(category.local) {\n        return;\n      }\n\n      showStickersPopup(\n        getStickerSetInputById(category.set),\n        true,\n        this.emoticonsDropdown.chatInput\n      );\n      return;\n    }\n\n    const emoji = getEmojiFromElement(target as HTMLElement);\n    if(!emoji || !this.canUseEmoji(emoji, category, true)) {\n      return;\n    }\n\n    if(this.onClick) {\n      this.onClick({\n        ...emoji,\n        element: findUpClassName(target, 'super-emoji').firstElementChild as HTMLElement\n      });\n    } else {\n      this.emoticonsDropdown.chatInput.onEmojiSelected(emoji, false);\n    }\n\n    if(IS_TOUCH_SUPPORTED) {\n      blurActiveElement();\n    }\n  };\n\n  public setActive(emoji: ReturnType<typeof getEmojiFromElement>) {\n    if(\n      emoji === this.activeEmoji ||\n      emoji?.docId ? emoji.docId === this.activeEmoji?.docId : emoji?.emoji === this.activeEmoji?.emoji\n    ) {\n      return;\n    }\n\n    this.activeEmoji = emoji;\n\n    this.activeElements.forEach((item) => {\n      item.element.classList.remove('active');\n    });\n\n    this.activeElements.length = 0;\n\n    this.categoriesMap.forEach((category) => {\n      category.items.forEach((item) => {\n        if(emoji.docId ? item.docId === emoji.docId : item.emoji === emoji.emoji) {\n          item.element.classList.add('active');\n          this.activeElements.push(item);\n        }\n      });\n    });\n  }\n\n  public onClose() {\n    this.closeScrollTop = this.scrollable.scrollPosition;\n  }\n}\n","import type AppGifsManager from '@appManagers/appGifsManager';\nimport GifsMasonry from '@components/gifsMasonry';\nimport {putPreloader} from '@components/putPreloader';\nimport {AppManagers} from '@lib/managers';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport EmoticonsTabC from '@components/emoticonsDropdown/tab';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {i18n} from '@lib/langPack';\nimport {onCleanup} from 'solid-js';\nimport {Middleware} from '@helpers/middleware';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport rootScope from '@lib/rootScope';\nimport {MyDocument} from '@appManagers/appDocsManager';\n\n// * a query keeps its results (and the pages scrolled into them) for as long as the search\n// * lasts, so going back to an earlier query is instant and costs no inline bot request\ntype GifsSearchResults = Awaited<ReturnType<AppGifsManager['searchGifs']>> & {query: string};\n\nexport default class GifsTab extends EmoticonsTabC<any, GifsSearchResults> {\n  private searchCache: Map<string, MaybePromise<GifsSearchResults>>;\n\n  constructor(options: {\n    managers: AppManagers\n  }) {\n    super({\n      managers: options.managers,\n      noMenu: true,\n      searchFetcher: (value) => {\n        if(!value) {\n          // * the cache lives for one search, exactly like tdesktop's cancelGifsSearch\n          this.searchCache?.clear();\n          return {documents: [], nextOffset: '', query: value};\n        }\n\n        return this.getSearchResults(value);\n      },\n      groupFetcher: (group) => {\n        if(group?._ !== 'emojiGroup') return {documents: [], nextOffset: '', query: ''};\n        return this.getSearchResults(group.emoticons.join(''));\n      },\n      // * only a value that still has to be asked for waits out the debounce - clearing the\n      // * search and returning to an already fetched query both answer at once\n      searchVerifyDebounce: (value) => {\n        value = value.trim();\n        return !!value && !this.searchCache?.has(value);\n      },\n      processSearchResult: async({data, searching, grouping}) => {\n        if(!searching && !grouping) {\n          return;\n        }\n\n        // * `data` is undefined until the first fetch resolves and again whenever one fails\n        const gifs = data?.documents;\n        if(!gifs?.length) {\n          const span = i18n('NoGIFsFound');\n          span.classList.add('emoticons-not-found');\n          return span;\n        }\n\n        const middleware = createMiddleware().get();\n        const container = this.categoriesContainer.cloneNode(false) as HTMLElement;\n        const {masonry, container: gifsContainer} = this.createMasonry(middleware);\n        gifs.forEach((doc) => masonry.add(doc));\n        container.append(gifsContainer);\n\n        const old = this.scrollable.onAdditionalScroll;\n        this.scrollable.onAdditionalScroll = () => {\n          old?.();\n\n          const {nextOffset} = data;\n          if(!nextOffset) {\n            return;\n          }\n\n          // prevent multiple requests\n          data.nextOffset = undefined;\n\n          this.managers.appGifsManager.searchGifs(data.query, nextOffset).then((result) => {\n            // * this view is what the results were rendered into - once it is gone the page\n            // * has nowhere to go, so put the offset back and let the next view ask again,\n            // * otherwise the rebuilt view would carry on past a page it never got\n            if(!middleware()) {\n              data.nextOffset = nextOffset;\n              return;\n            }\n\n            result.documents.forEach((doc) => masonry.add(doc));\n            data.documents.push(...result.documents);\n            data.nextOffset = result.nextOffset;\n          }, () => {\n            // * let a later scroll retry the page instead of ending the list here\n            data.nextOffset = nextOffset;\n          });\n        };\n\n        onCleanup(() => {\n          this.scrollable.onAdditionalScroll = old;\n        });\n\n        return container;\n      },\n      searchNoLoader: true,\n      searchPlaceholder: 'SearchGIFs',\n      searchType: 'gifs',\n      // * every keystroke is an inline bot query - firing one per character earns a\n      // * multi-minute FLOOD_WAIT that freezes the whole panel on its last results.\n      // * 400ms is what tdesktop waits (kSearchRequestDelay in gifs_list_widget.cpp)\n      searchDebounceTime: 400\n    });\n\n    safeAssign(this, options);\n    this.container.classList.add('gifs-padding');\n    this.content.id = 'content-gifs';\n  }\n\n  private getSearchResults(query: string) {\n    const cache = this.searchCache ??= new Map();\n    const cached = cache.get(query);\n    if(cached) {\n      return cached;\n    }\n\n    // * the promise is cached too so the pending query is never requested twice, and it is\n    // * swapped for the plain results afterwards - a repeat of the query then resolves\n    // * synchronously and the search input skips its debounce for it\n    const promise = this.managers.appGifsManager.searchGifs(query).then((result) => {\n      const results: GifsSearchResults = {...result, query};\n      // * the search may have been cancelled (dropping the cache) while this was in flight -\n      // * results of a search that is over must not reappear in the next one\n      if(cache.get(query) === promise) {\n        cache.set(query, results);\n      }\n\n      return results;\n    }, (err) => {\n      cache.delete(query);\n      throw err;\n    });\n\n    cache.set(query, promise);\n    return promise;\n  }\n\n  private createMasonry(middleware: Middleware) {\n    const gifsContainer = document.createElement('div');\n    gifsContainer.classList.add('gifs-masonry');\n    const detachClickEvent = attachClickEvent(gifsContainer, this.emoticonsDropdown.onMediaClick);\n    const masonry = new GifsMasonry(gifsContainer, this.animationGroup, this.scrollable);\n\n    middleware.onDestroy(() => {\n      masonry.clear();\n      detachClickEvent();\n    });\n\n    this.emoticonsDropdown.addLazyLoadQueueRepeat(masonry.lazyLoadQueue, masonry.processInvisibleDiv, middleware);\n    return {masonry, container: gifsContainer};\n  }\n\n  public init() {\n    super.init();\n\n    const middleware = this.middlewareHelper.get();\n    const {masonry, container} = this.createMasonry(middleware);\n    this.categoriesContainer.append(container);\n    const preloader = putPreloader(this.content, true);\n\n    let rendered = 0;\n    const onGifsUpdated = (gifs: MyDocument[]) => {\n      masonry.update(gifs);\n      rendered = gifs.length;\n    };\n\n    this.managers.appGifsManager.getGifs().then((docs) => {\n      masonry.addBatch(docs);\n      rendered = docs.length;\n      preloader.remove();\n    });\n\n    const onGifsUpdatedPostponed = this.postponedEvent(onGifsUpdated);\n    rootScope.addEventListener('gifs_updated', (gifs) => {\n      // a shorter list means a gif was taken out of the saved ones — the user did that and has\n      // to see it go; a list of the same length is the reorder that follows using one, which\n      // waits for the panel to hide\n      (gifs.length < rendered ? onGifsUpdated : onGifsUpdatedPostponed)(gifs);\n    });\n\n    this.attachHelpers({\n      isGif: true\n    });\n\n    this.init = undefined;\n  }\n}\n","import type LazyLoadQueueIntersector from '@components/lazyLoadQueueIntersector';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport {horizontalMenu} from '@components/horizontalMenu';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport Scrollable, {ScrollableX} from '@components/scrollable';\nimport appSidebarRight from '@components/sidebarRight';\nimport StickyIntersector from '@components/stickyIntersector';\nimport EmojiTab, {EmojiTabCategory, getEmojiFromElement} from '@components/emoticonsDropdown/tabs/emoji';\nimport GifsTab from '@components/emoticonsDropdown/tabs/gifs';\nimport StickersTab from '@components/emoticonsDropdown/tabs/stickers';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {AppGifsTab} from '@components/solidJsTabs/tabs';\nimport {AppStickersTab} from '@components/solidJsTabs/tabs';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport whichChild from '@helpers/dom/whichChild';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport DropdownHover from '@helpers/dropdownHover';\nimport pause from '@helpers/schedulers/pause';\nimport {IS_APPLE_MOBILE} from '@environment/userAgent';\nimport {AppManagers} from '@lib/managers';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport overlayCounter from '@helpers/overlayCounter';\nimport {getAppWindow, getOverlayRoot} from '@helpers/appWindow';\nimport noop from '@helpers/noop';\nimport {FocusDirection, ScrollOptions} from '@helpers/fastSmoothScroll';\nimport BezierEasing from '@vendor/bezierEasing';\nimport RichInputHandler from '@helpers/dom/richInputHandler';\nimport {getCaretPosF} from '@helpers/dom/getCaretPosNew';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {ChatRights} from '@appManagers/appChatsManager';\nimport {toastNew} from '@components/toast';\nimport ChatInput, {POSTING_NOT_ALLOWED_MAP} from '@components/chat/input';\nimport safeAssign from '@helpers/object/safeAssign';\nimport ButtonIcon from '@components/buttonIcon';\nimport StickersTabCategory from '@components/emoticonsDropdown/category';\nimport {Middleware} from '@helpers/middleware';\nimport {Accessor, createSignal, Setter} from 'solid-js';\n\nexport const EMOTICONSSTICKERGROUP: AnimationItemGroup = 'emoticons-dropdown';\n\nexport interface EmoticonsTab {\n  content: HTMLElement;\n  scrollable: Scrollable;\n  menuScroll?: ScrollableX;\n  tabId: number;\n  init: () => void;\n  onOpen?: () => void;\n  onOpened?: () => void;\n  onClose?: () => void;\n  onClosed?: () => void;\n  onPeerChanged?: () => void;\n}\n\nexport interface EmoticonsTabConstructable<T extends EmoticonsTab = any> {\n  new(...args: any[]): T;\n}\n\nconst easing = BezierEasing(0.42, 0.0, 0.58, 1.0);\nconst scrollOptions: Partial<ScrollOptions> = {\n  forceDuration: 150,\n  transitionFunction: easing,\n  maxDistance: 150\n};\nconst renderEmojiDropdownElement = (): HTMLDivElement => {\n  const div = document.createElement('div');\n  div.innerHTML =\n    `<div class=\"emoji-dropdown\" style=\"display: none;\">\n      <div class=\"emoji-container\">\n        <div class=\"tabs-container\"></div>\n      </div>\n      <div class=\"emoji-tabs menu-horizontal-div emoticons-menu no-stripe\"></div>\n    </div>`;\n  const a: [string, string, number][] = [\n    ['search justify-self-start', 'search', -1],\n    ['emoji', 'smile', 0],\n    ['stickers', 'stickers_face', 1],\n    ['gifs', 'gifs', 2],\n    ['delete justify-self-end', 'deleteleft', -1]\n  ];\n  const d = div.firstElementChild as HTMLDivElement;\n  d.lastElementChild.append(...a.map(([className, icon, tabId]) => {\n    const button = ButtonIcon(`${icon} menu-horizontal-div-item emoji-tabs-${className}`, {noRipple: true});\n    button.dataset.tab = '' + tabId;\n    return button;\n  }));\n  return d;\n}\n\nexport const EMOJI_TEXT_COLOR = 'primary-text-color';\n\nexport class EmoticonsDropdown extends DropdownHover {\n  public lazyLoadQueue = new LazyLoadQueue(1);\n\n  private container: HTMLElement;\n  private tabsEl: HTMLElement;\n  private tabId = -1;\n\n  private tabs: {[id: number]: EmoticonsTab};\n\n  private searchButton: HTMLElement;\n  private deleteBtn: HTMLElement;\n\n  private selectTab: ReturnType<typeof horizontalMenu>;\n\n  private savedRange: Range;\n  private tabsToRender: EmoticonsTab[] = [];\n  private managers: AppManagers;\n\n  private rights: {[action in ChatRights]?: boolean};\n\n  private listenerSetter: ListenerSetter;\n\n  private _chatInput: ChatInput;\n  public textColor: Accessor<string>;\n  private _setTextColor: Setter<string>;\n\n  public isStandalone: boolean;\n\n  public animationGroup: AnimationItemGroup;\n\n  constructor(options: {\n    customParentElement?: HTMLElement | (() => HTMLElement),\n    // customAnchorElement?: HTMLElement,\n    getOpenPosition?: () => DOMRectEditable,\n    tabsToRender?: EmoticonsTab[],\n    customOnSelect?: (emoji: {element: HTMLElement} & ReturnType<typeof getEmojiFromElement>) => void,\n    animationGroup?: AnimationItemGroup,\n    suppressOutClick?: boolean\n  } = {}) {\n    super({\n      element: renderEmojiDropdownElement(),\n      ignoreOutClickClassName: 'input-message-input'\n    });\n    safeAssign(this, options);\n\n    [this.textColor, this._setTextColor] = createSignal(EMOJI_TEXT_COLOR);\n\n    this.listenerSetter = new ListenerSetter();\n    this.isStandalone = !!options?.tabsToRender;\n    this.element.classList.toggle('is-standalone', this.isStandalone);\n    this.animationGroup = options.animationGroup || EMOTICONSSTICKERGROUP;\n\n    this.rights = {\n      send_gifs: this.isStandalone || undefined,\n      send_stickers: this.isStandalone || undefined\n    };\n\n    this.addEventListener('open', async() => {\n      if(IS_TOUCH_SUPPORTED) {\n        // this.chatInput.saveScroll();\n        if(blurActiveElement()) {\n          // * commented to fix dynamic height of the dropdown (like limited reactions menu)\n          // await pause(100);\n        }\n      }\n\n      if(options.getOpenPosition) {\n        const rect = options.getOpenPosition();\n        this.element.style.setProperty('--top', rect.top + 'px');\n        this.element.style.setProperty('--left', rect.left + 'px');\n      }/*  else if(options.customAnchorElement) {\n        const anchorRect = options.customAnchorElement.getBoundingClientRect();\n        const offset = 64;\n        this.element.style.left = anchorRect.left + 'px' as string;\n        this.element.style.bottom = anchorRect.top + offset + 'px' as string;\n      } */\n\n      if(options.customParentElement) {\n        const c = options.customParentElement;\n        const parent = typeof(c) === 'function' ? c() : c;\n        parent.append(this.element);\n      } else if(this.element.parentElement !== this.chatInput.chatInput) {\n        this.chatInput.chatInput.append(this.element);\n      }\n\n      this.savedRange = this.getGoodRange();\n\n      this.lazyLoadQueue.lock();\n      // this.lazyLoadQueue.unlock();\n      animationIntersector.lockIntersectionGroup(this.animationGroup);\n\n      const tab = this.tab;\n      tab.onOpen?.();\n    });\n\n    this.addEventListener('opened', () => {\n      animationIntersector.unlockIntersectionGroup(this.animationGroup);\n      this.lazyLoadQueue.unlockAndRefresh();\n\n      // this.container.classList.remove('disable-hover');\n\n      const tab = this.tab;\n      tab.onOpened?.();\n    });\n\n    this.addEventListener('openAfterLayout', () => {\n      if(options.getOpenPosition) {\n        this.element.style.setProperty('--width', this.element.offsetWidth + 'px');\n      }\n    });\n\n    this.addEventListener('close', () => {\n      this.lazyLoadQueue.lock();\n\n      // нужно залочить группу и выключить стикеры\n      animationIntersector.lockIntersectionGroup(this.animationGroup);\n      animationIntersector.checkAnimations(true, this.animationGroup);\n\n      const tab = this.tab;\n      tab.onClose?.();\n    });\n\n    this.addEventListener('closed', () => {\n      // теперь можно убрать visible, чтобы они не включились после фокуса\n      animationIntersector.unlockIntersectionGroup(this.animationGroup);\n      this.lazyLoadQueue.unlock();\n      this.lazyLoadQueue.refresh();\n\n      // this.container.classList.remove('disable-hover');\n\n      this.savedRange = undefined;\n\n      const tab = this.tab;\n      tab.onClosed?.();\n    });\n  }\n\n  public canUseEmoji(emoji: AppEmoji, showToast?: boolean) {\n    this.init?.();\n    return this.getTab(EmojiTab).canUseEmoji(emoji, undefined, showToast);\n  }\n\n  public get tab() {\n    return this.tabs[this.tabId];\n  }\n\n  public get chatInput() {\n    return this._chatInput || appImManager.chat.input;\n  }\n\n  public set chatInput(chatInput: ChatInput) {\n    const changed = this._chatInput !== chatInput;\n    this._chatInput = chatInput;\n    if(changed && this.chatInput !== undefined) {\n      this.checkRights();\n    }\n  }\n\n  public get intersectionOptions(): IntersectionObserverInit {\n    return {root: this.getElement()};\n  }\n\n  public setTextColor(textColor: string = EMOJI_TEXT_COLOR) {\n    this._setTextColor(textColor);\n    // this.getTab(EmojiTab)?.setTextColor(textColor);\n  }\n\n  public getTab<T extends EmoticonsTab>(instance: EmoticonsTabConstructable<T>) {\n    return this.tabsToRender.find((tab) => tab instanceof instance) as T;\n  }\n\n  public init() {\n    this.managers = rootScope.managers;\n\n    if(!this.tabsToRender.length) {\n      this.tabsToRender = [\n        new EmojiTab({managers: this.managers, preloaderDelay: 200}),\n        new StickersTab(this.managers),\n        new GifsTab({managers: this.managers})\n      ];\n    }\n\n    this.tabs = {};\n    this.tabsToRender.forEach((tab, idx) => {\n      (tab as EmojiTab).emoticonsDropdown = this;\n      tab.tabId = idx;\n      this.tabs[idx] = tab;\n    });\n\n    this.container = this.element.querySelector('.emoji-container .tabs-container') as HTMLDivElement;\n    this.container.prepend(...this.tabsToRender.map((tab) => (tab as EmojiTab).container));\n    this.tabsEl = this.element.querySelector('.emoji-tabs') as HTMLUListElement;\n\n    this.selectTab = horizontalMenu(this.tabsEl, this.container, this.onSelectTabClick, () => {\n      const {tab} = this;\n      tab.init?.();\n      animationIntersector.checkAnimations(false, this.animationGroup);\n    });\n\n    this.searchButton = this.element.querySelector('.emoji-tabs-search');\n    this.listenerSetter.add(this.searchButton)('click', () => {\n      if(this.tabId === this.getTab(StickersTab)?.tabId) {\n        if(!appSidebarRight.isTabExists(AppStickersTab)) {\n          appSidebarRight.createTab(AppStickersTab).open();\n        }\n      } else {\n        if(!appSidebarRight.isTabExists(AppGifsTab)) {\n          appSidebarRight.createTab(AppGifsTab).open();\n        }\n      }\n    });\n\n    this.deleteBtn = this.element.querySelector('.emoji-tabs-delete');\n    attachClickEvent(this.deleteBtn, (e) => {\n      cancelEvent(e);\n      const input = this.chatInput.messageInput;\n      // RichInputHandler.getInstance().makeFocused(this.chatInput.messageInput);\n      let range = RichInputHandler.getInstance().getSavedRange(input);\n      if(!range) {\n        range = input.ownerDocument.createRange();\n        range.setStartAfter(input.lastChild);\n      }\n\n      const newRange = range.cloneRange();\n      // if(range.endOffset === range.startOffset && range.endContainer === range.startContainer) {\n      if(range.collapsed) {\n        const {node, offset} = getCaretPosF(input, range.endContainer, range.endOffset);\n        let newStartNode: Node;\n        if(offset) {\n          newStartNode = node;\n        } else {\n          newStartNode = node.previousSibling;\n          if(!newStartNode) {\n            return;\n          }\n\n          while(newStartNode.nodeType === newStartNode.TEXT_NODE && !newStartNode.nodeValue && (newStartNode = newStartNode.previousSibling)) {\n\n          }\n\n          if(newStartNode.nodeType === newStartNode.ELEMENT_NODE && !(newStartNode as HTMLElement).isContentEditable) {\n            return;\n          }\n        }\n\n        if(newStartNode.nodeType === newStartNode.ELEMENT_NODE && (newStartNode as any).tagName === 'IMG') {\n          newRange.selectNode(newStartNode);\n        } else {\n          const text = [...newStartNode.textContent];\n          let t: string;\n          if(offset) {\n            let length = 0;\n            t = text.find((text) => (length += text.length, length >= offset));\n          } else {\n            t = text.pop() || '';\n          }\n\n          const newOffset = offset ? offset - t.length : newStartNode.textContent.length - t.length;\n          newRange.setStart(newStartNode, newOffset);\n        }\n      }\n\n      newRange.deleteContents();\n\n      this.chatInput.messageInputField.simulateInputEvent();\n    }, {listenerSetter: this.listenerSetter});\n\n    const HIDE_EMOJI_TAB = IS_APPLE_MOBILE && false;\n\n    const INIT_TAB_ID = (HIDE_EMOJI_TAB ? this.getTab(StickersTab) : this.getTab(EmojiTab))?.tabId ?? this.tabsToRender[0]?.tabId ?? 0;\n\n    if(HIDE_EMOJI_TAB) {\n      (this.tabsEl.children[1] as HTMLElement).classList.add('hide');\n    }\n\n    simulateClickEvent(this.tabsEl.children[INIT_TAB_ID + 1] as HTMLElement);\n    if(this.tabsToRender.length <= 1) {\n      this.tabsEl.classList.add('hide');\n    }\n    this.tabs[INIT_TAB_ID].init?.(); // onTransitionEnd не вызовется, т.к. это первая открытая вкладка\n\n    if(!IS_TOUCH_SUPPORTED) {\n      let lastMouseMoveEvent: MouseEvent, mouseMoveTarget: HTMLElement;\n      const onMouseMove = (e: MouseEvent) => {\n        lastMouseMoveEvent = e;\n      };\n      this.listenerSetter.add(overlayCounter)('change', (isActive) => {\n        if(isActive) {\n          if(!mouseMoveTarget) {\n            // Bind to the active app window's body (PiP-aware) and keep the exact reference so the\n            // matching remove below targets the same element even if the active window changed.\n            mouseMoveTarget = getOverlayRoot();\n            this.listenerSetter.add(mouseMoveTarget)('mousemove', onMouseMove);\n          }\n        } else if(mouseMoveTarget) {\n          this.listenerSetter.removeManual(mouseMoveTarget, 'mousemove', onMouseMove);\n          mouseMoveTarget = undefined;\n          if(lastMouseMoveEvent) {\n            this.onMouseOut(lastMouseMoveEvent);\n          }\n        }\n      });\n    }\n\n    const onPeerChanging = () => {\n      if(this._chatInput || this.isStandalone) {\n        return;\n      }\n\n      this.toggle(false);\n    };\n\n    const onPeerChanged = () => {\n      // tabs track per-chat content (the group's own sticker set), so they are told\n      // about the switch even when the dropdown itself is pinned to one chat input\n      this.tabsToRender.forEach((tab) => tab.onPeerChanged?.());\n\n      if(this._chatInput || this.isStandalone) {\n        return;\n      }\n\n      this.checkRights();\n    };\n\n    this.listenerSetter.add(appImManager)('peer_changing', onPeerChanging);\n    this.listenerSetter.add(appImManager)('peer_changed', onPeerChanged);\n    onPeerChanged();\n\n    const ret = super.init();\n    this.init = undefined;\n    return ret;\n  }\n\n  public getElement() {\n    return this.element;\n  }\n\n  public scrollTo(tab: EmoticonsTab, element: HTMLElement) {\n    tab.scrollable.scrollIntoViewNew({\n      element: element as HTMLElement,\n      axis: 'y',\n      position: 'start',\n      getElementPosition: tab.scrollable.container === element ? () => -element.scrollTop : undefined,\n      ...scrollOptions\n    });\n  }\n\n  private onSelectTabClick = (id: number) => {\n    if(this.tabId === id) {\n      const {tab} = this;\n      this.scrollTo(tab, tab.scrollable.container as HTMLElement);\n      return;\n    }\n\n    const rights: {[tabId: number]: ChatRights} = {\n      ...(this.getTab(StickersTab) && {[this.getTab(StickersTab).tabId]: 'send_stickers'}),\n      ...(this.getTab(GifsTab) && {[this.getTab(GifsTab).tabId]: 'send_gifs'})\n    };\n\n    const action = rights[id];\n    if(action && !this.rights[action]) {\n      toastNew({langPackKey: POSTING_NOT_ALLOWED_MAP[action]});\n      return false;\n    }\n\n    animationIntersector.checkAnimations(true, this.animationGroup);\n\n    this.tabId = id;\n    this.searchButton.classList.toggle('hide', this.tabId === this.getTab(EmojiTab)?.tabId);\n    this.deleteBtn.classList.toggle('hide', this.tabId !== this.getTab(EmojiTab)?.tabId);\n  };\n\n  private checkRights = async() => {\n    this.managers ??= rootScope.managers;\n    const {peerId, threadId} = this.chatInput.chat;\n\n    const actions = Object.keys(this.rights) as ChatRights[];\n\n    const rights = await Promise.all(actions.map((action) => {\n      return this.managers.appMessagesManager.canSendToPeer(peerId, threadId, action);\n    }));\n\n    actions.forEach((action, idx) => {\n      this.rights[action] = rights[idx];\n    });\n\n    if(this.init) {\n      return;\n    }\n\n    const emojiTab = this.getTab(EmojiTab);\n    const active = this.tabsEl.querySelector('.active');\n    if(active && whichChild(active) !== (emojiTab?.tabId + 1) && (!this.rights['send_stickers'] || !this.rights['send_gifs'])) {\n      this.selectTab(emojiTab.tabId, false);\n    }\n\n    emojiTab?.toggleCustomCategory();\n  };\n\n  public static menuOnClick = (\n    emoticons: EmojiTab | StickersTab,\n    menu: HTMLElement,\n    scrollable: Scrollable,\n    menuScroll?: ScrollableX,\n    prevTab?: StickersTabCategory<any>,\n    listenerSetter?: ListenerSetter\n  ) => {\n    let jumpedTo = -1;\n\n    const scrollToTab = (tab: typeof prevTab, f?: boolean) => {\n      const m = tab.menuScroll || menuScroll;\n      if(m) {\n        m.scrollIntoViewNew({\n          element: tab.elements.menuTab,\n          position: 'center',\n          axis: 'x',\n          getElementPosition: f ? ({elementPosition}) => {\n            return elementPosition - 106;\n          } : undefined,\n          ...scrollOptions\n        });\n      }\n    };\n\n    const setActive = (tab: typeof prevTab, scroll = true) => {\n      if(tab === prevTab) {\n        return false;\n      }\n\n      let f = false;\n      if(prevTab) {\n        prevTab.elements.menuTab.classList.remove('active');\n        if(prevTab.menuScroll && prevTab.menuScroll !== tab.menuScroll) {\n          f = true;\n          // scroll to first\n          prevTab.menuScroll.container.parentElement.classList.remove('active');\n          prevTab.menuScroll.scrollIntoViewNew({\n            element: prevTab.menuScroll.firstElementChild as HTMLElement,\n            forceDirection: scroll ? undefined : FocusDirection.Static,\n            position: 'center',\n            axis: 'x',\n            ...scrollOptions\n          });\n        }\n      }\n\n      tab.elements.menuTab.classList.add('active');\n\n      if(tab.menuScroll) {\n        tab.menuScroll.container.parentElement.classList.add('active');\n        scroll && menuScroll.scrollIntoViewNew({\n          element: tab.menuScroll.container.parentElement,\n          position: 'center',\n          axis: 'x',\n          ...scrollOptions\n        });\n      }\n\n      if(prevTab) {\n        scrollToTab(tab, f);\n      }\n\n      prevTab = tab;\n\n      return true;\n    };\n\n    const setActiveStatic = (tab: typeof prevTab) => {\n      if(prevTab?.local) {\n        return;\n      }\n\n      emoticons.scrollable.scrollPosition = tab.elements.container.offsetTop + 1;\n      const s = emoticons.menuScroll.container;\n      const e = tab.elements.menuTab;\n      s.scrollLeft = e.offsetLeft - s.clientWidth / 2 + e.offsetWidth / 2;\n      setActive(tab, false);\n    };\n\n    let scrollingToContent = false;\n    const stickyIntersector = new StickyIntersector(scrollable.container, (stuck, target) => {\n      if(scrollingToContent) {\n        return;\n      }\n\n      // console.log('sticky scrollTop', stuck, target, scrollable.container.scrollTop, jumpedTo);\n\n      if(Math.abs(jumpedTo - scrollable.scrollPosition) <= 1) {\n        return;\n      } else {\n        jumpedTo = -1;\n      }\n\n      const tab = emoticons.getCategoryByContainer(target);\n      // the entry may describe a category deleted since the observer queued it\n      if(!tab?.elements.menuTab) {\n        return;\n      }\n\n      const which = whichChild(target);\n      if(!stuck && (which || tab.menuScroll)) {\n        return;\n      }\n\n      setActive(tab);\n    });\n\n    attachClickEvent(menu, (e) => {\n      cancelEvent(e);\n      let target = findUpClassName(e.target as HTMLElement, 'menu-horizontal-div-item');\n      if(!target) {\n        target = findUpClassName(e.target as HTMLElement, 'menu-horizontal-inner');\n        if(!target || target.classList.contains('active')) {\n          return;\n        }\n\n        target = target.firstElementChild.firstElementChild as HTMLElement;\n      }\n\n      const which = whichChild(target);\n\n      const tab = emoticons.getCategoryByMenuTab(target);\n\n      /* if(menuScroll) {\n        menuScroll.scrollIntoView(target, false, 0);\n      } */\n\n      if(setActive(tab)) {\n        // scrollToTab(tab);\n        // return;\n      }\n\n      let offsetTop = 0, additionalOffset = 0;\n      if(which > 0 || tab.menuScroll) {\n        const element = tab.elements.container;\n        additionalOffset = 1;\n        offsetTop = element.offsetTop + additionalOffset; // * due to stickyIntersector\n      }\n\n      jumpedTo = offsetTop;\n\n      scrollingToContent = true;\n      scrollable.scrollIntoViewNew({\n        element: offsetTop ? tab.elements.container : scrollable.firstElementChild as HTMLElement,\n        position: 'start',\n        axis: 'y',\n        getElementPosition: offsetTop ? ({elementPosition}) => elementPosition + additionalOffset : undefined,\n        startCallback: () => {\n          if(emoticons instanceof EmojiTab && !emoticons.isCategoryVisible(tab as EmojiTabCategory)) {\n            emoticons._onCategoryVisibility(tab as EmojiTabCategory, true);\n          }\n        },\n        ...scrollOptions\n      }).finally(() => {\n        setActive(tab);\n        scrollingToContent = false;\n      });\n    }, {listenerSetter});\n\n    const a = scrollable.onAdditionalScroll ? scrollable.onAdditionalScroll.bind(scrollable) : noop;\n    scrollable.onAdditionalScroll = () => {\n      emoticons.content.parentElement.classList.toggle('no-border-top',\n        scrollable.scrollPosition <= 0 ||\n        emoticons.container.classList.contains('is-searching')\n      );\n      a();\n    };\n\n    emoticons.content.parentElement.classList.add('no-border-top');\n\n    return {stickyIntersector, setActive, setActiveStatic};\n  };\n\n  public onMediaClick = async(e: {target: EventTarget | Element}, clearDraft = false, silent?: boolean, ignoreNoPremium?: boolean) => {\n    const target = findUpTag(e.target as HTMLElement, 'DIV');\n    if(!target) return false;\n\n    const docId = target.dataset.docId;\n    if(!docId) return false;\n\n    return this.sendDocId({document: docId, clearDraft, silent, target, ignoreNoPremium});\n  };\n\n  public async sendDocId(options: Parameters<ChatInput['sendMessageWithDocument']>[0]) {\n    if(await this.chatInput.sendMessageWithDocument(options)) {\n      /* dropdown.classList.remove('active');\n      toggleEl.classList.remove('active'); */\n      if(emoticonsDropdown.container) {\n        emoticonsDropdown.forceClose = true;\n        // emoticonsDropdown.container.classList.add('disable-hover');\n        emoticonsDropdown.toggle(false);\n      }\n\n      return true;\n    } else {\n      console.warn('got no doc by id:', document);\n      return false;\n    }\n  }\n\n  public addLazyLoadQueueRepeat(lazyLoadQueue: LazyLoadQueueIntersector, processInvisibleDiv: (div: HTMLElement) => void, middleware: Middleware) {\n    const listenerSetter = new ListenerSetter();\n    listenerSetter.add(this)('close', () => {\n      lazyLoadQueue.lock();\n    });\n\n    listenerSetter.add(this)('closed', () => {\n      const divs = lazyLoadQueue.intersector.getVisible();\n\n      for(const div of divs) {\n        processInvisibleDiv(div);\n      }\n\n      lazyLoadQueue.intersector.clearVisible();\n    });\n\n    listenerSetter.add(this)('opened', () => {\n      lazyLoadQueue.unlockAndRefresh();\n    });\n\n    middleware.onClean(() => {\n      listenerSetter.removeAll();\n    });\n  }\n\n  public getSavedRange() {\n    return this.getGoodRange() || this.savedRange;\n  }\n\n  private getGoodRange() {\n    const sel = getAppWindow().getSelection();\n    if(sel.rangeCount && getAppWindow().document.activeElement === this.chatInput?.messageInput) {\n      return sel.getRangeAt(0);\n    }\n  }\n\n  public destroy() {\n    this.cleanup();\n    this.listenerSetter.removeAll();\n    this.tabsToRender.forEach((tab) => (tab as EmojiTab).destroy?.());\n    this.element.remove();\n  }\n\n  public hideAndDestroy() {\n    return this.toggle(false).then(() => {\n      return this.destroy();\n    });\n  }\n}\n\nconst emoticonsDropdown = new EmoticonsDropdown();\nMOUNT_CLASS_TO.emoticonsDropdown = emoticonsDropdown;\nexport default emoticonsDropdown;\n","import {MessageEntity} from '@layer';\nimport getEmojiEntityFromEmoji from '@lib/richTextProcessor/getEmojiEntityFromEmoji';\n\ntype Args = {\n  docId?: DocId;\n  emoji: string;\n};\n\nexport function getMessageEntityForEmojiWithDocId({docId, emoji}: Args): MessageEntity {\n  if(!docId) return getEmojiEntityFromEmoji(emoji);\n\n  return {\n    _: 'messageEntityCustomEmoji',\n    document_id: docId,\n    length: emoji?.length ?? 0,\n    offset: 0\n  };\n}\n","import Button from '@components/buttonTsx';\nimport styles from '@components/emojiDropdownButton.module.scss';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport EmojiTab from '@components/emoticonsDropdown/tabs/emoji';\nimport InputField, {insertRichTextAsHTML} from '@components/inputField';\nimport createListenerSetter from '@helpers/solid/createListenerSetter';\nimport {MessageEntity} from '@layer';\nimport {getMessageEntityForEmojiWithDocId} from '@lib/richTextProcessor/getMessageEntityFromDocIdOrEmoji';\nimport rootScope from '@lib/rootScope';\nimport {createRoot, onCleanup} from 'solid-js';\n\n\ntype CreateEmojiDropdownButtonArgs = {\n  inputField?: InputField;\n  class?: string;\n  onEmoticonsDropdown?: (emoticonsDropdown: EmoticonsDropdown) => void;\n  onClick?: OnClick;\n}\n  & Pick<ConstructorParameters<typeof EmoticonsDropdown>[0], 'customParentElement' | 'getOpenPosition' | 'animationGroup'>\n  & Pick<ConstructorParameters<typeof EmojiTab>[0], 'noPacks' | 'noSearchGroups' | 'noRegularEmoji' | 'canUsePremiumEmojiAlways'>;\n\ntype OnClick = ConstructorParameters<typeof EmojiTab>[0]['onClick'];\n\nconst createEmojiDropdownButton = ({\n  class: _class,\n  onEmoticonsDropdown,\n  ...rest\n}: CreateEmojiDropdownButtonArgs) => createRoot((dispose) => {\n  let button: HTMLButtonElement;\n  Button.Icon({\n    icon: 'smile',\n    class: _class,\n    noRipple: true,\n    ref: (ref) => button = ref as HTMLButtonElement\n  }) as HTMLElement;\n\n  const {emoticonsDropdown} = useEmojiDropdown({\n    element: button,\n    ...rest\n  });\n\n  onEmoticonsDropdown?.(emoticonsDropdown);\n\n  return {button, dispose};\n});\n\ntype UseEmojiDropdownArgs = Omit<CreateEmojiDropdownButtonArgs, 'class' | 'onEmoticonsDropdown'> & {\n  element: HTMLElement;\n};\n\nexport const useEmojiDropdown = ({\n  inputField,\n  onClick = inputField ? getDefaultOnClick(inputField) : undefined,\n  element,\n  noPacks,\n  noSearchGroups,\n  noRegularEmoji,\n  canUsePremiumEmojiAlways,\n  ...rest\n}: UseEmojiDropdownArgs) => {\n  const emojiTab = new EmojiTab({\n    managers: rootScope.managers,\n    additionalStickerViewerClass: styles.StickerViewer,\n    noPacks: noPacks ?? !rootScope.premium,\n    noSearchGroups: noSearchGroups ?? !rootScope.premium,\n    noRegularEmoji,\n    onClick: onClick,\n    canUsePremiumEmojiAlways\n  });\n\n  const emoticonsDropdown = new EmoticonsDropdown({\n    tabsToRender: [emojiTab],\n    ...rest\n  });\n\n  emoticonsDropdown.attachButtonListener(element, createListenerSetter());\n  emoticonsDropdown.getElement().classList.add(styles.EmoticonsDropdown);\n  emoticonsDropdown.setTextColor('primary-text-color');\n\n  onCleanup(() => {\n    emoticonsDropdown?.hideAndDestroy();\n  });\n\n  return {\n    emojiTab,\n    emoticonsDropdown\n  };\n};\n\nconst getDefaultOnClick = (inputField: InputField): OnClick => (emoji) => {\n  const entity: MessageEntity = getMessageEntityForEmojiWithDocId({\n    docId: emoji.docId,\n    emoji: emoji.emoji\n  });\n\n  insertRichTextAsHTML(\n    inputField.input,\n    emoji.emoji,\n    entity ? [entity] : undefined\n  );\n};\n\nexport default createEmojiDropdownButton;\n","import type InputField from '@components/inputField';\nimport {LocalTextWithEntities} from '@types';\nimport {JSX} from 'solid-js';\nimport type ChatInput from '../input';\nimport {defaultShouldShowFromHeight, useAiEditorButton} from './useAiEditorButton';\n\n\ntype AiEditorButtonProps = {\n  instance: ChatInput;\n  container: HTMLDivElement;\n  appendTo: HTMLDivElement;\n  canSend: boolean;\n  shouldShowFromHeight?: number;\n  onApply: (text: LocalTextWithEntities) => void;\n  inputField: InputField;\n  class?: string;\n};\n\nexport const AiEditorButton = (props: AiEditorButtonProps): JSX.Element => {\n  useAiEditorButton({\n    instance: props.instance,\n    class: props.class,\n    container: () => props.container,\n    appendTo: () => props.appendTo,\n    canSend: props.canSend,\n    onApply: props.onApply,\n    inputField: () => props.inputField,\n    shouldShowFromHeight: () => props.shouldShowFromHeight ?? defaultShouldShowFromHeight\n  });\n  return null;\n};\n","import type {AnimationItemGroup} from '@components/animationIntersector';\nimport Button from '@components/buttonTsx';\nimport createEmojiDropdownButton from '@components/emojiDropdownButton';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport {IconTsx} from '@components/iconTsx';\nimport InputFieldAnimated from '@components/inputFieldAnimated';\nimport {getTransition} from '@config/transitions';\nimport cloneDOMRect from '@helpers/dom/cloneDOMRect';\nimport getRichValueWithCaret from '@helpers/dom/getRichValueWithCaret';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport liteMode from '@helpers/liteMode';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport throttle from '@helpers/schedulers/throttle';\nimport Animated from '@helpers/solid/animations';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport classNames from '@helpers/string/classNames';\nimport {LangPackKey} from '@lib/langPack';\nimport wrapDraftText from '@lib/richTextProcessor/wrapDraftText';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {Accessor, createEffect, createSignal, onCleanup, Show, untrack} from 'solid-js';\nimport {Portal} from 'solid-js/web';\nimport ChatInput from './chat/input';\nimport {AiEditorButton} from './chat/inputState/aiEditorButton';\n\ntype InputFieldMessageProps = {\n  placeholder?: LangPackKey,\n  name?: string,\n  withLinebreaks?: boolean,\n  maxLength?: number,\n  animationGroup?: AnimationItemGroup,\n  listenerSetter?: ListenerSetter,\n  onScroll?: () => void,\n  onInput?: (hasValue: boolean, length: number) => void,\n  draft?: Parameters<InputFieldAnimated['setValueSilently']>[0],\n  ref?: (inputField: InputFieldAnimated) => void,\n  btnConfirm?: HTMLElement,\n  btnProps?: Parameters<typeof Button>[0],\n  stars?: Accessor<number>,\n  chatInput?: ChatInput,\n};\n\nconst InputFieldMessage = (props: InputFieldMessageProps) => {\n  const [container, setContainer] = createSignal<HTMLDivElement>();\n  const [inputFieldContainer, setInputFieldContainer] = createSignal<HTMLDivElement>();\n\n  const inputField = new InputFieldAnimated({\n    placeholder: props.placeholder ?? 'PreviewSender.CaptionPlaceholder',\n    name: props.name ?? 'message',\n    withLinebreaks: props.withLinebreaks ?? true,\n    maxLength: props.maxLength\n  });\n\n  const additionalClass = 'simple-message-input';\n  let btnConfirm = untrack(() => props.btnConfirm);\n\n  {\n    const _additionalClass = additionalClass + '-confirm';\n    const contentClass = _additionalClass + '-content';\n    let contentWrapper: HTMLDivElement;\n    const inner = () => (\n      <Animated\n        type=\"cross-fade\"\n        itemClass={contentClass + '-item'}\n        noItemClass\n      >\n        <Show\n          when={props.stars?.() ?? 0}\n          fallback={<IconTsx icon=\"logo\" class={_additionalClass + '-icon'} />}\n        >\n          <span class={_additionalClass + '-inner'}>\n            <IconTsx icon=\"star\" class={_additionalClass + '-inner-star'} />\n            {numberThousandSplitterForStars(props.stars?.() ?? 0) + ''}\n          </span>\n        </Show>\n      </Animated>\n    );\n\n    if(btnConfirm) {\n      btnConfirm.classList.add(_additionalClass);\n\n      <Portal\n        mount={btnConfirm}\n        ref={(el) => {\n          contentWrapper = el;\n          el.classList.add(contentClass);\n        }}\n      >\n        {inner()}\n      </Portal>;\n    } else {\n      <Button\n        {...(props.btnProps || {})}\n        ref={(ref) => {\n          btnConfirm = ref;\n          (props.btnProps?.ref as any)(ref);\n        }}\n        primaryFilled\n        class={classNames(_additionalClass, props.btnProps.class)}\n        noRipple\n      >\n        <div ref={contentWrapper} class={contentClass}>\n          {inner()}\n        </div>\n      </Button>;\n    }\n\n    let prevWidth: number;\n    createEffect(() => {\n      props.stars?.();\n      queueMicrotask(() => {\n        const last = contentWrapper?.lastElementChild as HTMLElement | null;\n        if(!last?.offsetWidth) return;\n        const style = getComputedStyle(btnConfirm);\n        const padding = parseFloat(style.paddingLeft) + parseFloat(style.paddingRight);\n        const minWidth = parseFloat(style.minWidth) || 0;\n        const currentWidth = Math.max(last.offsetWidth + padding, minWidth);\n        if(prevWidth !== undefined && prevWidth !== currentWidth && liteMode.isAvailable('animations')) {\n          btnConfirm.animate([\n            {width: prevWidth + 'px'},\n            {width: currentWidth + 'px'}\n          ], {\n            duration: 200,\n            easing: getTransition('standard').easing\n          });\n        }\n        prevWidth = currentWidth;\n      });\n    });\n  }\n\n  if(props.animationGroup) {\n    inputField.input.dataset.animationGroup = props.animationGroup;\n  }\n\n  [inputField.input, inputField.inputFake].forEach((input) => {\n    input.classList.replace('input-field-input', 'input-message-input');\n    input.classList.add(additionalClass + '-input');\n  });\n\n  inputField.placeholder.classList.add(\n    'input-message-placeholder',\n    additionalClass + '-placeholder'\n  );\n\n  if(props.listenerSetter) {\n    if(props.onScroll) {\n      props.listenerSetter.add(inputField.input)('scroll', props.onScroll);\n    }\n\n    if(props.onInput) {\n      props.listenerSetter.add(inputField.input)('input', throttle(() => {\n        const {value} = getRichValueWithCaret(inputField.input);\n        const trimmed = value.trim();\n        props.onInput(!!trimmed, trimmed ? value.length : 0);\n      }, 120, true));\n    }\n  }\n\n  if(props.draft !== undefined) {\n    inputField.setValueSilently(props.draft);\n  }\n\n  let emoticonsDropdown: EmoticonsDropdown;\n  const {button: emojiButton, dispose} = createEmojiDropdownButton({\n    inputField,\n    class: additionalClass + '-emoji',\n    animationGroup: props.animationGroup,\n    customParentElement: getOverlayRoot,\n    onEmoticonsDropdown: (dropdown) => {\n      emoticonsDropdown = dropdown;\n      emoticonsDropdown.getElement().style.transformOrigin = '0 100%';\n    },\n    getOpenPosition: () => {\n      if(!container()) return {top: 0, left: 0, width: 0, height: 0, bottom: 0, right: 0};\n      const rect = container().getBoundingClientRect();\n      const cloned = cloneDOMRect(rect);\n      cloned.left = rect.left;\n      cloned.top = rect.top - 420 - 8;\n      return cloned;\n    }\n  });\n\n  onCleanup(dispose);\n\n  props.ref?.(inputField);\n\n  return (\n    <div\n      ref={setContainer}\n      class={additionalClass + '-container'}\n    >\n      {emojiButton}\n      <div ref={setInputFieldContainer} class={classNames('input-message-container', additionalClass + '-inputs')}>\n        {inputField.input}\n        {inputField.placeholder}\n        {inputField.inputFake}\n      </div>\n      {btnConfirm}\n      {props.chatInput && (\n        <SolidJSHotReloadGuardProvider>\n          <AiEditorButton\n            class='simple-message-input-ai-button'\n            instance={props.chatInput}\n            container={inputFieldContainer()}\n            appendTo={container()}\n            canSend={false}\n            inputField={inputField}\n            onApply={(text) => {\n              const node = wrapDraftText(text.text, {\n                entities: text.entities,\n                wrappingForPeerId: props.chatInput.chat.peerId,\n                middleware: createMiddleware().get()\n              });\n              inputField.setValueSilently(node);\n            }}\n            shouldShowFromHeight={100}\n          />\n        </SolidJSHotReloadGuardProvider>\n      )}\n    </div>\n  );\n};\n\nexport default InputFieldMessage;\n","import type {ChatRights} from '@appManagers/appChatsManager';\nimport flatten from '@helpers/array/flatten';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport {toastNew} from '@components/toast';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {i18n, join} from '@lib/langPack';\nimport {useAppConfig, useIsFrozen} from '@stores/appState';\nimport {Message, User} from '@layer';\nimport {createMemo, createRoot, Show} from 'solid-js';\nimport {createStore} from 'solid-js/store';\nimport Animated from '@helpers/solid/animations';\nimport classNames from '@helpers/string/classNames';\nimport InputFieldMessage from '@components/inputFieldMessage';\nimport PopupElement from '@components/popups/indexTsx';\nimport InputFieldAnimated from '@components/inputFieldAnimated';\nimport ChatInput from '@components/chat/input';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport SendMenu from '@components/chat/sendContextMenu';\nimport showScheduleSendingPopup from '@components/popups/scheduleSendingPopup';\nimport {getMiddleware} from '@helpers/middleware';\nimport {SEND_WHEN_ONLINE_TIMESTAMP} from '@appManagers/constants';\n\nasync function resolveChatRightsActions(peerIdMids: {[fromPeerId: PeerId]: number[]}): Promise<ChatRights[]> {\n  const messagesPromises = Object.keys(peerIdMids).map((peerId) => {\n    const mids = peerIdMids[peerId as any as number];\n    return mids.map((mid) => {\n      return rootScope.managers.appMessagesManager.getMessageByPeer(peerId.toPeerId(), mid);\n    });\n  });\n\n  const messages = await Promise.all(flatten(messagesPromises));\n  const actions: Set<ChatRights> = new Set();\n  messages.forEach((message) => {\n    if(!message) {\n      return;\n    }\n\n    const media = getMediaFromMessage(message);\n    let action: ChatRights;\n    if(!media) {\n      if(message.viaBotId) {\n        action = 'send_inline';\n      } else {\n        action = 'send_plain';\n      }\n    } else {\n      if(media._ === 'webPage') {\n        action = 'embed_links';\n      } else if(media._ === 'photo') {\n        action = 'send_photos';\n      } else if(media._ === 'game') {\n        action = 'send_games';\n      } else {\n        switch(media.type) {\n          case 'audio':\n            action = 'send_audios';\n            break;\n          case 'gif':\n            action = 'send_gifs';\n            break;\n          case 'round':\n            action = 'send_roundvideos';\n            break;\n          case 'sticker':\n            action = 'send_stickers';\n            break;\n          case 'voice':\n            action = 'send_voices';\n            break;\n          case 'video':\n            action = 'send_videos';\n            break;\n          default:\n            action = 'send_docs';\n            break;\n        }\n      }\n    }\n\n    if(action) {\n      actions.add(action);\n    }\n  });\n\n  return Array.from(actions);\n}\n\nexport default async function showForwardPopup(\n  peerIdMids?: {[fromPeerId: PeerId]: number[]},\n  _onSelect?: (peerId: PeerId, threadId?: number) => Promise<void> | void,\n  noTopics?: boolean,\n  onClose?: () => void\n) {\n  const chatRightsActions = peerIdMids ? await resolveChatRightsActions(peerIdMids) : [];\n  if(!chatRightsActions.length) {\n    chatRightsActions.push('send_plain');\n  }\n\n  let canCopyLink = false, messageCount = 0;\n  if(peerIdMids) {\n    for(const fromPeerId in peerIdMids) {\n      const mids = peerIdMids[fromPeerId];\n      messageCount += mids.length;\n    }\n\n    const fromPeerIdStr = Object.keys(peerIdMids)[0];\n    const fromPeerId = fromPeerIdStr.toPeerId();\n    const mid = peerIdMids[fromPeerIdStr as any as number][0];\n    const firstMessage = await rootScope.managers.appMessagesManager.getMessageByPeer(fromPeerId, mid) as Message.message;\n    canCopyLink = !!firstMessage?.pFlags?.post;\n  }\n\n  const {message_length_max: MAX_MESSAGE_LENGTH} = await rootScope.managers.apiManager.getConfig();\n\n  const listenerSetter = new ListenerSetter();\n  const sendMenuMiddleware = getMiddleware();\n  let sendMenu: SendMenu | undefined;\n  let sendMenuElement: HTMLElement | undefined;\n  let silent = false;\n  let scheduleDate: number | undefined;\n  let scheduleRepeatPeriod: number | undefined;\n\n  // eslint-disable-next-line prefer-const -- referenced by starsState memo created before the popup handle is assigned\n  let handle: ReturnType<typeof showPickUserPopup>;\n  let finalizingThroughButton = false;\n\n  let starsStateDispose: () => void;\n  const starsState = createRoot((dispose) => {\n    starsStateDispose = dispose;\n\n    const [store, set] = createStore({\n      messageLength: 0,\n      selectedPeers: [] as PeerId[],\n      starsTick: 0\n    });\n\n    const messageMsgCount = createMemo(() => {\n      const len = store.messageLength;\n      if(!len) return 0;\n      return Math.max(1, Math.ceil(len / MAX_MESSAGE_LENGTH));\n    });\n\n    const totalMessages = createMemo(() => messageCount + messageMsgCount());\n\n    const totalStars = createMemo(() => {\n      store.starsTick;\n      const msgs = totalMessages();\n      if(!msgs) return 0;\n      const map = handle?.selector?.starsAmountByPeer;\n      if(!map) return 0;\n      const peers = store.selectedPeers;\n      if(!peers.length) return 0;\n      let sum = 0;\n      for(const peerId of peers) {\n        sum += (map.get(peerId) || 0) * msgs;\n      }\n      return sum;\n    });\n\n    return {store, set, totalStars};\n  });\n\n  const handleCopyLink = async() => {\n    const fromPeerIdStr = Object.keys(peerIdMids)[0];\n    const fromPeerId = fromPeerIdStr.toPeerId();\n    const mid = peerIdMids[fromPeerIdStr as any as number][0];\n    const username = await rootScope.managers.appPeersManager.getPeerUsername(fromPeerId);\n    const msgId = getServerMessageId(mid);\n    let url = 'https://t.me/';\n    if(username) {\n      url += username + '/' + msgId;\n    } else {\n      url += 'c/' + fromPeerId.toChatId() + '/' + msgId;\n    }\n\n    copyTextToClipboard(url);\n    toastNew({langPackKey: 'LinkCopied'});\n    handle.hide();\n  };\n\n  const processSingle = async({\n    peerId,\n    threadId,\n    monoforumThreadId\n  }: {\n    peerId: number,\n    threadId?: number,\n    monoforumThreadId?: number\n  }, openChat: boolean) => {\n    if(_onSelect) {\n      const res = _onSelect(peerId);\n      if(res instanceof Promise) {\n        await res;\n      }\n    }\n\n    let success: boolean;\n    if(openChat) {\n      await appImManager.setInnerPeer({peerId, threadId, monoforumThreadId});\n      appImManager.chat.input.initMessagesForward(peerIdMids);\n    } else {\n      const result = await ChatInput.sendMessageWithForward({\n        inputField,\n        sendingParams: {\n          peerId,\n          threadId,\n          silent: silent || undefined,\n          scheduleDate: scheduleDate || undefined,\n          scheduleRepeatPeriod: scheduleRepeatPeriod || undefined\n        },\n        forwarding: peerIdMids,\n        slowModeParams: {\n          peerId,\n          element: btnRef,\n          managers: rootScope.managers\n        }\n      });\n\n      success = !!result;\n    }\n\n    return success;\n  };\n\n  const updateSendMenuPeerParams = () => {\n    if(!sendMenu) return;\n    const selected = handle?.selector?.getSelected() ?? [];\n    const peerIds = selected.filter((k): k is PeerId => k.isPeerId());\n    const allSelf = peerIds.length > 0 && peerIds.every((p) => p === rootScope.myId);\n    const peerId = allSelf ?\n      rootScope.myId :\n      (peerIds.find((p) => p !== rootScope.myId) ?? rootScope.myId);\n    const map = handle?.selector?.starsAmountByPeer;\n    const isPaid = map ? peerIds.some((p) => (map.get(p) || 0) > 0) : false;\n    sendMenu.setPeerParams({peerId, isPaid});\n  };\n\n  const setupSendMenu = (btn: HTMLElement) => {\n    if(!btn) return;\n    sendMenuElement?.remove();\n    sendMenuElement = undefined;\n    sendMenuMiddleware.clean();\n\n    if(!popupContainerEl) return;\n\n    sendMenu = new SendMenu({\n      onSilentClick: () => {\n        silent = true;\n        finalizingThroughButton = true;\n        handle.finalize();\n      },\n      onScheduleClick: () => {\n        showScheduleSendingPopup({\n          onPick: (timestamp, repeatPeriod) => {\n            scheduleDate = timestamp;\n            scheduleRepeatPeriod = repeatPeriod;\n            finalizingThroughButton = true;\n            handle.finalize();\n          },\n          canSendWhenOnline: false\n        });\n      },\n      onSendWhenOnlineClick: () => {\n        scheduleDate = SEND_WHEN_ONLINE_TIMESTAMP;\n        finalizingThroughButton = true;\n        handle.finalize();\n      },\n      canSendWhenOnline: async() => {\n        const selected = handle?.selector?.getSelected() ?? [];\n        const peerIds = selected.filter((k): k is PeerId => k.isPeerId());\n        if(peerIds.length !== 1) return false;\n        const peerId = peerIds[0];\n        if(peerId === rootScope.myId || !peerId.isUser()) return false;\n        if(!(await rootScope.managers.appUsersManager.isUserOnlineVisible(peerId.toUserId()))) {\n          return false;\n        }\n        const user = await rootScope.managers.appUsersManager.getUser(peerId.toUserId()) as User.user;\n        if(user?.pFlags?.bot) return false;\n        return user?.status?._ !== 'userStatusOnline';\n      },\n      middleware: sendMenuMiddleware.get(),\n      openSide: 'top-left',\n      onContextElement: btn,\n      onOpen: () => {\n        const peerIds = (handle?.selector?.getSelected() ?? []).filter((k) => k.isPeerId());\n        return peerIds.length > 0;\n      },\n      onRef: (element) => {\n        sendMenuElement = element;\n        popupContainerEl.appendChild(element);\n      }\n    });\n\n    updateSendMenuPeerParams();\n  };\n\n  const resetSendOptions = () => {\n    silent = false;\n    scheduleDate = undefined;\n    scheduleRepeatPeriod = undefined;\n  };\n\n  let onSelect: Parameters<typeof showPickUserPopup>[0]['onSelect'];\n  if(!peerIdMids && _onSelect) {\n    onSelect = (chosen) => _onSelect(chosen[0].peerId, chosen[0].threadId);\n  } else {\n    onSelect = async(chosen) => {\n      const sentToPeerIds: Set<PeerId> = new Set();\n      const succeeded: Array<typeof chosen[0]> = [];\n      const isSavedMessagesNoText = chosen.length === 1 &&\n        chosen[0].peerId === rootScope.myId &&\n        !starsState.store.messageLength;\n      const openChat = chosen.length === 1 && !finalizingThroughButton && !isSavedMessagesNoText;\n      for(const item of chosen) {\n        const success = await processSingle(\n          item,\n          openChat\n        );\n\n        if(success) {\n          sentToPeerIds.add(item.peerId);\n          succeeded.push(item);\n        }\n      }\n\n      if(sentToPeerIds.size === 1 && [...sentToPeerIds.values()][0] === rootScope.myId) {\n        toastNew({\n          langPackKey: messageCount > 1 ? 'FwdMessagesToSavedMessages' : 'FwdMessageToSavedMessages'\n        });\n      } else if(sentToPeerIds.size) {\n        const peerTitles = sentToPeerIds.size <= 3 ? await Promise.all(Array.from(sentToPeerIds).map((peerId) => {\n          return wrapPeerTitle({peerId, dialog: true});\n        })) : [];\n\n        const boldPeerTitles = peerTitles.map((element) => {\n          const b = document.createElement('b');\n          b.append(element);\n          return b;\n        });\n        toastNew({\n          langPackKey: messageCount === 1 ? 'FwdMessageTo' : 'FwdMessagesTo',\n          langPackArguments: peerTitles.length ? [join(boldPeerTitles)] : [i18n('FwdMessagesToChats', [sentToPeerIds.size])]\n        });\n      }\n\n      // * deselect failed\n      if(!openChat && succeeded.length !== chosen.length) {\n        handle.selector.removeBatch(succeeded.map(({key}) => key));\n        throw new Error();\n      }\n    };\n  }\n\n  let btnRef: HTMLElement, inputField: InputFieldAnimated, popupContainerEl: HTMLElement;\n  handle = showPickUserPopup({\n    peerType: ['dialogs', 'contacts'],\n    containerProps: {ref: (el) => popupContainerEl = el},\n    onSelect,\n    onChange: () => {\n      const selected = handle.selector.getSelected() ?? [];\n      const peerIds = selected.filter((k): k is PeerId => k.isPeerId());\n      starsState.set('selectedPeers', peerIds);\n      updateSendMenuPeerParams();\n    },\n    multiSelect: 'hidden',\n    placeholder: 'ShareModal.Search.ForwardPlaceholder',\n    chatRightsActions,\n    selfPresence: 'ChatYourSelf',\n    useTopics: !noTopics,\n    titleLangKey: 'ShareWith',\n    showTopPeers: true,\n    ...(useIsFrozen() && {\n      getMoreCustom: async() => {\n        const appConfig = useAppConfig();\n        const peer = await rootScope.managers.appUsersManager.resolveUsername(appConfig.freeze_appeal_url.split('/').pop());\n        return {\n          result: [peer.id.toPeerId(peer._ !== 'user')],\n          isEnd: true\n        };\n      },\n      peerType: ['custom'],\n      noSearch: true,\n      headerLangPackKey: 'Forward'\n    }),\n    footer: ({multiSelect}) => {\n      const hasMessage = () => !!starsState.store.messageLength;\n      const showCopyLink = () => canCopyLink && multiSelect() === 'hidden' && !hasMessage();\n      const isFooterHidden = () => !canCopyLink && multiSelect() === 'hidden' && !hasMessage();\n      return (\n        <div class={classNames('popup-forward-footer-content', isFooterHidden() && 'is-hidden')}>\n          <Animated type=\"cross-fade\" itemClass=\"popup-forward-footer-item\">\n            <Show\n              when={showCopyLink()}\n              fallback={\n                <InputFieldMessage\n                  btnProps={{\n                    ref: (ref) => {\n                      btnRef = ref;\n                      setupSendMenu(ref);\n                    },\n                    onClick: () => {\n                      resetSendOptions();\n                      finalizingThroughButton = true;\n                      handle.finalize();\n                    }\n                  }}\n                  ref={(ref) => inputField = ref}\n                  listenerSetter={listenerSetter}\n                  onInput={(_hasValue, length) => starsState.set('messageLength', length)}\n                  stars={starsState.totalStars}\n                />\n              }\n            >\n              <PopupElement.FooterButton callback={handleCopyLink}>\n                {i18n('CopyLink')}\n              </PopupElement.FooterButton>\n            </Show>\n          </Animated>\n        </div>\n      );\n    },\n    onClose: () => {\n      listenerSetter.removeAll();\n      sendMenuElement?.remove();\n      sendMenuMiddleware.destroy();\n      starsStateDispose?.();\n      handle.selector && (handle.selector.onStarsAmountUpdate = undefined);\n      onClose?.();\n    },\n    btnConfirmOnEnter: () => btnRef\n  });\n\n  if(handle.selector) {\n    handle.selector.onStarsAmountUpdate = () => {\n      starsState.set('starsTick', (t) => t + 1);\n    };\n  }\n}\n","import EmptyListLoader from '@helpers/emptyListLoader';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {Photo, Document} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport AppMediaViewerBase from '@components/mediaViewer/base';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport PopupElement from '@components/popups';\nimport PopupForward from '@components/popups/forward';\nimport appSidebarRight from '@components/sidebarRight';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport {wrapAsyncClickHandler} from '@helpers/wrapAsyncClickHandler';\nimport showForwardPopup from '@components/popups/forward';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\n\n\nexport type AppMediaViewerStaticTargetType = {\n  media: Photo.photo | Document.document;\n  element: HTMLElement;\n  fromId: PeerId\n  timestamp: number;\n  peerId: PeerId;\n  mid?: number;\n};\n\ntype OpenMediaArgs = AppMediaViewerStaticTargetType & {\n  allTargets?: AppMediaViewerStaticTargetType[];\n  index?: number;\n  fromRight: number;\n};\n\nexport default class AppMediaViewerStatic extends AppMediaViewerBase<never, 'forward', AppMediaViewerStaticTargetType> {\n  constructor() {\n    super(new EmptyListLoader, ['forward']);\n\n    const buttons: ButtonMenuItemOptionsVerifiable[] = [\n      {\n        icon: 'forward',\n        text: 'Forward',\n        onClick: this.onForwardClick\n      }, {\n        icon: 'download',\n        text: 'MediaViewer.Context.Download',\n        onClick: this.onDownloadClick\n      }\n    ];\n\n    this.setBtnMenuToggle(buttons);\n\n    this.setListeners();\n  }\n\n  protected setListeners(): void {\n    super.setListeners();\n    attachClickEvent(this.buttons.forward, this.onForwardClick);\n  }\n\n  onPrevClick = (target: AppMediaViewerStaticTargetType) => {\n    this.openMedia({\n      ...target,\n      fromRight: -1\n    });\n  };\n\n  onNextClick = (target: AppMediaViewerStaticTargetType) => {\n    this.openMedia({\n      ...target,\n      fromRight: 1\n    });\n  };\n\n  onForwardClick = () => {\n    const target = this.target;\n    if(target.mid) {\n      showForwardPopup({\n        [target.peerId]: [target.mid]\n      }, undefined, undefined, () => {\n        return this.close();\n      });\n    }\n  };\n\n  onAuthorClick = async(e: MouseEvent) => {\n    await this.close(e)\n    if(mediaSizes.isMobile) {\n      const tab = appSidebarRight.getTab(AppSharedMediaTab);\n      if(tab) {\n        tab.close();\n      }\n    }\n\n    appImManager.setInnerPeer({\n      peerId: this.target.peerId\n    });\n  };\n\n  onDownloadClick = wrapAsyncClickHandler(async() => {\n    await appDownloadManager.downloadToDisc({media: this.target.media, queueId: appImManager.chat.bubbles.lazyLoadQueue.queueId});\n  });\n\n  public openMedia({allTargets, index, ...rest}: OpenMediaArgs) {\n    const prevTargets = index !== undefined && allTargets ? allTargets.slice(0, index) : undefined;\n    const nextTargets = index !== undefined && allTargets ? allTargets.slice(index + 1) : undefined;\n    console.log('my-debug rest', rest)\n\n    this._openMedia({\n      prevTargets,\n      nextTargets,\n      target: rest.element,\n      ...rest\n    });\n    Object.assign(this.target, {\n      media: rest.media,\n      element: rest.element,\n      fromId: rest.fromId,\n      timestamp: rest.timestamp,\n      peerId: rest.peerId,\n      mid: rest.mid\n    });\n  }\n}\n","export type SequentialCursorFetcherResult<T> = {\n  cursor: T;\n  count: number;\n  totalCount?: number;\n};\n\nexport class SequentialCursorFetcher<T> {\n  private fetchedItemsCount = 0;\n  private neededCount = 0;\n\n  private cursor: T;\n\n  private isFetching = false;\n\n  private needToFetchMore = false;\n\n  constructor(private fetcher: (cursor: T | undefined) => Promise<SequentialCursorFetcherResult<T>>) {}\n\n  public fetchUntil(neededCount: number, currentCount?: number) {\n    this.neededCount = Math.max(this.neededCount, neededCount);\n    if(typeof currentCount !== 'undefined') this.fetchedItemsCount = currentCount;\n\n    this.triggerFetching();\n  }\n\n  public tryToFetchMore() {\n    this.needToFetchMore = true;\n    this.triggerFetching();\n  }\n\n  public setFetchedItemsCount(count: number) {\n    this.fetchedItemsCount = count;\n  }\n\n  public setNeededCount(count: number) {\n    this.neededCount = count;\n  }\n\n  public setCursor(cursor: T) {\n    this.cursor = cursor;\n  }\n\n  public reset() {\n    this.fetchedItemsCount = 0;\n    this.neededCount = 0;\n    this.isFetching = false;\n    this.cursor = undefined;\n  }\n\n  private triggerFetching() {\n    if(this.isFetching) return;\n\n    this.isFetching = true;\n    this.fetchUntilNeededCount().catch(() => {}).finally(() => {\n      this.isFetching = false;\n    });\n  }\n\n  private async fetchUntilNeededCount() {\n    while(this.fetchedItemsCount < this.neededCount || this.needToFetchMore) {\n      const {cursor, count, totalCount} = await this.fetcher(this.cursor);\n\n      this.needToFetchMore = false;\n\n      if(count === 0) break;\n      this.cursor = cursor;\n\n      if(totalCount !== undefined)\n        this.fetchedItemsCount = totalCount;\n      else\n        this.fetchedItemsCount += count;\n    }\n  }\n}\n","import deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport DialogsPlaceholder from '@helpers/dialogsPlaceholder';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport throttle from '@helpers/schedulers/throttle';\nimport {SequentialCursorFetcher, SequentialCursorFetcherResult} from '@helpers/sequentialCursorFetcher';\nimport windowSize from '@helpers/windowSize';\nimport type {AppDialogsManager, DialogDom} from '@lib/appDialogsManager';\nimport appImManager from '@lib/appImManager';\nimport {AppManagers} from '@lib/managers';\nimport getDialogIndex from '@appManagers/utils/dialogs/getDialogIndex';\nimport getDialogIndexKey from '@appManagers/utils/dialogs/getDialogIndexKey';\nimport {isForumTopic} from '@appManagers/utils/dialogs/isDialog';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport {AnyDialog} from '@lib/storages/dialogs';\nimport {MonoforumDialog} from '@lib/storages/monoforumDialogs';\nimport Scrollable from '@components/scrollable';\nimport SortedDialogList from '@components/sortedDialogList';\nimport {AutonomousDialogList} from '@components/autonomousDialogList/dialogs';\n\n\nexport const DIALOG_LOAD_COUNT = 20;\nconst NOT_IMPLEMENTED_ERROR = new Error('not implemented');\n\n/**\n * Shows the peer's ongoing activity in place of the last message. Applied both\n * from the `peer_typings` event and when a dialog element is (re)built, since a\n * row created while the peer is already typing gets no event of its own.\n *\n * Returns whether the row is left showing an activity that can no longer be\n * rendered, i.e. the caller has to put the last message back.\n */\nexport async function setDialogTyping({dom, peerId, threadId}: {\n  dom: DialogDom,\n  peerId: PeerId,\n  threadId?: number\n}) {\n  const oldTypingElement = dom.lastMessageSpan.querySelector('.peer-typing-container') as HTMLElement;\n  const newTypingElement = await appImManager.getPeerTyping(peerId, oldTypingElement, threadId);\n  if(newTypingElement) {\n    if(!oldTypingElement) {\n      replaceContent(dom.lastMessageSpan, newTypingElement);\n      dom.lastMessageSpan.classList.add('user-typing');\n    }\n\n    return false;\n  }\n\n  // * the row shows an activity that can no longer be rendered — its last message has to come back\n  return !!oldTypingElement;\n}\n\ntype DialogKey = any;\nexport type PossibleDialog = AnyDialog | MonoforumDialog;\n\nexport type BaseConstructorArgs = {\n  appDialogsManager: AppDialogsManager;\n};\n\nexport type LoadDialogsInnerArgs = {\n  offsetIndex?: number;\n  removePlaceholder?: boolean;\n  canFinish: () => boolean;\n};\n\nexport class AutonomousDialogListBase<T extends PossibleDialog = PossibleDialog> {\n  public sortedList: SortedDialogList;\n  public scrollable: Scrollable;\n  public loadedDialogsAtLeastOnce: boolean;\n  public needPlaceholderAtFirstTime: boolean;\n  // protected offsets: {top: number, bottom: number};\n  protected indexKey: ReturnType<typeof getDialogIndexKey>;\n  protected sliceTimeout: number;\n  protected managers: AppManagers;\n  protected appDialogsManager: AppDialogsManager;\n  protected listenerSetter: ListenerSetter;\n  protected loadDialogsPromise: Promise<{cached: boolean, renderPromise: AutonomousDialogList['loadDialogsRenderPromise']}>;\n  protected loadDialogsRenderPromise: Promise<void>;\n  protected placeholder: DialogsPlaceholder;\n  protected log: ReturnType<typeof logger>;\n  protected placeholderOptions: ConstructorParameters<typeof DialogsPlaceholder>[0];\n\n  protected cursorFetcher = new SequentialCursorFetcher((cursor: number) => this.loadDialogs(cursor));\n  protected hasReachedTheEnd = false;\n\n  protected skipMigrated = true;\n\n  private refetchTimeout: number;\n\n  public requestItemForIdx = (idx: number, itemsLength?: number) => {\n    this.cursorFetcher.fetchUntil(idx + 1, itemsLength);\n  }\n\n  public onListShrinked = () => {\n    const items = this.sortedList.getSortedItems();\n    const last = items[items.length - 1];\n\n    this.cursorFetcher.setFetchedItemsCount(items.length);\n    this.cursorFetcher.setNeededCount(items.length);\n    this.cursorFetcher.setCursor(last?.index);\n\n    // Make sure the current request is canceled so the cursor is not overriden to a bigger page\n    this.loadDialogsDeferred?.reject();\n  }\n\n  constructor({appDialogsManager}: BaseConstructorArgs) {\n    this.log = logger('CL');\n    this.managers = rootScope.managers;\n    this.listenerSetter = new ListenerSetter();\n    this.appDialogsManager = appDialogsManager;\n  }\n\n  public setIndexKey(indexKey: AutonomousDialogListBase['indexKey']) {\n    this.indexKey = indexKey;\n    this.sortedList.indexKey = indexKey;\n  }\n\n  protected deleteDialogByKey(key: DialogKey) {\n    this.sortedList.delete(key);\n  }\n\n  public deleteDialog(dialog: T) {\n    return this.deleteDialogByKey(this.getDialogKey(dialog));\n  }\n\n  /**\n   * @returns Returns `true` if a new dialog was just added\n   */\n  private addOrDeleteDialogIfNeeded(dialog: T, key: any) {\n    if(!this.canUpdateDialog(dialog)) {\n      this.deleteDialog(dialog);\n      return false;\n    }\n\n    if(!this.sortedList.has(key)) {\n      this.sortedList.add(key);\n      return true;\n    }\n\n    return false;\n  }\n\n  public updateDialog(dialog: T) {\n    const key = this.getDialogKey(dialog);\n\n    if(this.addOrDeleteDialogIfNeeded(dialog, key)) return;\n\n    const dialogElement = this.getDialogElement(key);\n    if(!dialogElement) {\n      return;\n    }\n\n    this.appDialogsManager.setLastMessageN({\n      dialog,\n      dialogElement,\n      setUnread: true\n    });\n    this.sortedList.update(key);\n  }\n\n  protected canUpdateDialog(dialog: T) {\n    const sortedItems = this.sortedList.getSortedItems();\n    const last = sortedItems[sortedItems.length - 1];\n\n    const bottomIndex = last?.index;\n    const dialogIndex = getDialogIndex(dialog, this.indexKey);\n\n    return !last || dialogIndex >= bottomIndex || this.hasReachedTheEnd;\n  }\n\n  public onChatsScroll() {\n    this.requestItemForIdx(0);\n  };\n\n  protected onScrolledBottom() {\n    this.cursorFetcher.tryToFetchMore();\n  }\n\n  public createPlaceholder(): DialogsPlaceholder {\n    const placeholder = this.placeholder = new DialogsPlaceholder(this.placeholderOptions);\n    const getRectFrom = this.getRectFromForPlaceholder();\n    placeholder.attach({\n      container: this.sortedList.list.parentElement,\n      getRectFrom,\n      onRemove: () => {\n        if(this.placeholder === placeholder) {\n          this.placeholder = undefined;\n\n          // The dialogs placeholder is a little taller than the container, so we need to update the scrollbar\n          this.scrollable?.onScroll?.();\n        }\n      },\n      blockScrollable: this.scrollable\n    });\n\n    return placeholder;\n  }\n\n  private loadDialogsDeferred: CancellablePromise<SequentialCursorFetcherResult<number>>;\n\n  private async loadDialogs(offsetIndex?: number) {\n    this.loadDialogsDeferred?.reject();\n    const deferred = this.loadDialogsDeferred = deferredPromise();\n\n    this.loadDialogsInner({offsetIndex, canFinish: () => !deferred.isRejected})\n    .then(\n      deferred.resolve.bind(deferred),\n      deferred.reject.bind(deferred)\n    )\n    .finally(() => {\n      this.placeholder?.detach(this.sortedList?.itemsLength() || 0);\n    });\n\n    return this.loadDialogsDeferred;\n  }\n\n  public getDialogKey(dialog: T): DialogKey {\n    throw NOT_IMPLEMENTED_ERROR;\n  }\n\n  public getDialogKeyFromElement(element: HTMLElement): DialogKey {\n    throw NOT_IMPLEMENTED_ERROR;\n  }\n\n  public getRectFromForPlaceholder(): Parameters<DialogsPlaceholder['attach']>[0]['getRectFrom'] {\n    throw NOT_IMPLEMENTED_ERROR;\n  }\n\n  public getDialogFromElement(element: HTMLElement): Promise<T> {\n    throw NOT_IMPLEMENTED_ERROR;\n  }\n\n  protected getFilterId(): number {\n    throw NOT_IMPLEMENTED_ERROR;\n  }\n\n  public checkForDialogsPlaceholder() {\n    if(this.placeholder || this.loadedDialogsAtLeastOnce) return;\n\n    this.placeholder = this.createPlaceholder();\n  }\n\n  private guessLoadCount() {\n    // Make sure we have some scroll even when the screen is very huge\n    return Math.max(windowSize.height / 64 * 1.25 | 0, DIALOG_LOAD_COUNT);\n  }\n\n  public async preloadDialogs() {\n    const filterId = this.getFilterId();\n\n    await this.managers.acknowledged.dialogsStorage.getDialogs({\n      offsetIndex: 0,\n      limit: this.guessLoadCount(),\n      filterId,\n      skipMigrated: this.skipMigrated\n    });\n\n    this.checkForDialogsPlaceholder();\n  }\n\n  protected async dialogsFetcher(offsetIndex: number, limit: number): Promise<{dialogs: PossibleDialog[], count: number, isEnd: boolean}> {\n    const ackedResult = await this.managers.acknowledged.dialogsStorage.getDialogs({\n      offsetIndex,\n      limit,\n      filterId: this.getFilterId(),\n      skipMigrated: this.skipMigrated\n    });\n\n    const result = await ackedResult.result;\n\n    return result;\n  }\n\n  protected async loadDialogsInner({offsetIndex, removePlaceholder = true, canFinish}: LoadDialogsInnerArgs): Promise<SequentialCursorFetcherResult<number>> {\n    this.checkForDialogsPlaceholder();\n\n    /**\n     * The first time getDialogs might return `count: null`, which is not good for this\n     * infinite loading implementation, that's why we're refetching after 0.5 seconds to\n     * make sure we get the latest total count of dialogs to properly render the whole list\n     */\n    let shouldRefetch = false;\n    if(this.appDialogsManager.isFirstDialogsLoad && !offsetIndex) {\n      this.appDialogsManager.isFirstDialogsLoad = false;\n      shouldRefetch = true;\n    }\n\n    const result = await this.dialogsFetcher(offsetIndex, this.guessLoadCount());\n\n    if(shouldRefetch) {\n      const id = this.refetchTimeout = self.setTimeout(async() => {\n        try {\n          const {totalCount} = await this.loadDialogsInner({\n            canFinish: () => id === this.refetchTimeout\n          });\n          this.cursorFetcher.setFetchedItemsCount(totalCount);\n        } catch{}\n      }, 500);\n    }\n\n    const newOffsetIndex = result.dialogs.reduce((prev, curr) => {\n      const index = getDialogIndex(curr, this.indexKey);\n      return index < prev ? index : prev;\n    }, offsetIndex || Infinity);\n\n    const items = await Promise.all(result.dialogs.map(async(dialog) => {\n      const key = this.getDialogKey(dialog as T);\n\n      return this.sortedList.createItemForKey(key);\n    }));\n\n    if(!canFinish()) throw new Error();\n\n    this.loadedDialogsAtLeastOnce = true;\n    this.hasReachedTheEnd = !!result.isEnd;\n\n    this.sortedList.addDeferredItems(items, result.count || 0);\n\n    if(removePlaceholder) this.placeholder?.detach(this.sortedList.itemsLength());\n\n    return {\n      cursor: newOffsetIndex === Infinity ? undefined : newOffsetIndex,\n      count: result.dialogs.length,\n      totalCount: this.sortedList.itemsLength() // Note that at some point we might add duplicates\n    };\n  }\n\n  public async setTyping(dialog: T) {\n    const key = this.getDialogKey(dialog);\n    const dom = this.getDialogDom(key);\n    if(!dom) {\n      return;\n    }\n\n    const needsLastMessage = await setDialogTyping({\n      dom,\n      peerId: dialog.peerId,\n      threadId: isForumTopic(dialog) ? dialog.id : undefined\n    });\n\n    if(needsLastMessage) {\n      this.unsetTyping(dialog);\n    }\n  }\n\n  public unsetTyping(dialog: T) {\n    const key = this.getDialogKey(dialog);\n    const dialogElement = this.getDialogElement(key);\n    if(!dialogElement) {\n      return;\n    }\n\n    dialogElement.dom.lastMessageSpan.classList.remove('user-typing');\n    this.appDialogsManager.setLastMessageN({\n      dialog,\n      lastMessage: null,\n      dialogElement,\n      setUnread: null\n    });\n  }\n\n  public getDialogDom(key: DialogKey) {\n    const element = this.getDialogElement(key);\n    return element?.dom;\n  }\n\n  public getDialogElement(key: DialogKey) {\n    const element = this.sortedList.getDialogElement(key);\n    return element;\n  }\n\n  public getListElement(key: DialogKey) {\n    return this.getDialogElement(key)?.dom.listEl;\n  }\n\n  public bindScrollable() {\n    this.scrollable.onScrolledBottom = throttle(() => {\n      this.onScrolledBottom();\n    }, 200, false);\n  }\n\n  public clear() {\n    this.sortedList.clear();\n    this.placeholder?.remove();\n    this.loadDialogsDeferred?.reject();\n    this.loadDialogsDeferred = undefined;\n    this.cursorFetcher.reset();\n    this.hasReachedTheEnd = false;\n    self.clearTimeout(this.refetchTimeout);\n    this.refetchTimeout = undefined;\n  }\n\n  public reset() {\n    this.loadDialogsRenderPromise = undefined;\n    this.loadDialogsPromise = undefined;\n  }\n\n  public fullReset() {\n    this.reset();\n    this.clear();\n    return this.onChatsScroll();\n  }\n\n  public destroy() {\n    this.clear();\n    this.scrollable.destroy();\n    this.listenerSetter.removeAll();\n    this.sortedList?.destroy();\n  }\n}\n","import rootScope from '@lib/rootScope';\nimport {MonoforumDialog} from '@lib/storages/monoforumDialogs';\nimport {AutonomousDialogListBase, BaseConstructorArgs} from '@components/autonomousDialogList/base';\n\n\ntype ConstructorArgs = BaseConstructorArgs & {\n  peerId: PeerId;\n};\n\nexport class AutonomousMonoforumThreadList extends AutonomousDialogListBase<MonoforumDialog> {\n  public onEmpty: () => void;\n  private peerId: PeerId\n\n  constructor({peerId, ...args}: ConstructorArgs) {\n    super(args);\n\n    this.peerId = peerId;\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_update', ({dialogs}) => {\n      dialogs.filter(dialog => dialog.parentPeerId === this.peerId).forEach(dialog => this.updateDialog(dialog));\n    });\n\n    this.listenerSetter.add(rootScope)('monoforum_draft_update', ({dialog}) => {\n      if(dialog.parentPeerId !== this.peerId) return;\n      this.updateDialog(dialog);\n    });\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_drop', ({parentPeerId, ids}) => {\n      if(parentPeerId !== this.peerId) return;\n      ids.forEach(id => this.deleteDialogByKey(id));\n\n      if(!this.sortedList.itemsLength()) this.onEmpty?.();\n    });\n  }\n\n  protected getFilterId() {\n    return this.peerId;\n  }\n\n  public getDialogKey(dialog: MonoforumDialog) {\n    return dialog?.peerId;\n  }\n\n  protected dialogsFetcher(offsetIndex: number, limit: number) {\n    return this.managers.monoforumDialogsStorage.getDialogs({parentPeerId: this.peerId, limit, offsetIndex});\n  }\n}\n","import {BusinessWeeklyOpen, BusinessWorkHours} from '@layer';\nimport I18n from '@lib/langPack';\nimport {ONE_DAY_MINUTES, ONE_WEEK_MINUTES, formatTime} from '@helpers/date';\nimport copy from '@helpers/object/copy';\n\nclass Period {\n  // from 0 to 2 * 24 * 60\n  constructor(public start: number, public end: number) {\n  }\n\n  public toString() {\n    return Period.timeToString(this.start) + ' - ' + Period.timeToString(this.end);\n  }\n\n  public static timeToString(time: number, includeNextDay = true) {\n    const min = time % 60;\n    const hours = (time - min) / 60 % 24;\n    const rightNow = new Date();\n    rightNow.setHours(hours, min);\n    const str = formatTime(rightNow).textContent;\n    if(time > ONE_DAY_MINUTES && includeNextDay) {\n      return I18n.format('BusinessHoursNextDay', true, [str]);\n    }\n    return str;\n  }\n}\n\nexport default class OpeningHours {\n  static Period = Period;\n\n  // https://github.com/DrKLO/Telegram/blob/a906f12aaec2768969c77650a7e4b377baa6cf2a/TMessagesProj/src/main/java/org/telegram/ui/Business/OpeningHoursActivity.java#L201\n  static adaptWeeklyOpen(hours: BusinessWeeklyOpen[], utcOffset: number) {\n    const array: BusinessWeeklyOpen[] = copy(hours);\n\n    const array2: BusinessWeeklyOpen[] = new Array();\n    for(let i = 0; i < array.length; ++i) {\n      const weekly = array[i];\n      let newWeekly: BusinessWeeklyOpen = {...weekly};\n\n      if(utcOffset !== 0) {\n        const start = weekly.start_minute % ONE_DAY_MINUTES;\n        const end = start + (weekly.end_minute - weekly.start_minute);\n        if(start === 0 && (end === ONE_DAY_MINUTES || end === (ONE_DAY_MINUTES - 1))) {\n          newWeekly.start_minute = weekly.start_minute;\n          newWeekly.end_minute = weekly.end_minute;\n          array2.push(newWeekly);\n          continue;\n        }\n      }\n\n      newWeekly.start_minute = weekly.start_minute + utcOffset;\n      newWeekly.end_minute = weekly.end_minute + utcOffset;\n      array2.push(newWeekly);\n\n      if(newWeekly.start_minute < 0) {\n        if(newWeekly.end_minute < 0) {\n          newWeekly.start_minute += ONE_WEEK_MINUTES;\n          newWeekly.end_minute += ONE_WEEK_MINUTES;\n        } else {\n          newWeekly.start_minute = 0;\n\n          newWeekly = {...weekly};\n          newWeekly.start_minute = ONE_WEEK_MINUTES + weekly.start_minute + utcOffset;\n          newWeekly.end_minute = (ONE_WEEK_MINUTES - 1);\n          array2.push(newWeekly);\n        }\n      } else if(newWeekly.end_minute > ONE_WEEK_MINUTES) {\n        if(newWeekly.start_minute > ONE_WEEK_MINUTES) {\n          newWeekly.start_minute -= ONE_WEEK_MINUTES;\n          newWeekly.end_minute -= ONE_WEEK_MINUTES;\n        }/*  else {\n          newWeekly.end_minute = ONE_WEEK_MINUTES - 1;\n\n          newWeekly = {...weekly};\n          newWeekly.start_minute = 0;\n          newWeekly.end_minute = weekly.end_minute + utcOffset - (ONE_WEEK_MINUTES - 1);\n          array2.push(newWeekly);\n        } */\n      }\n    }\n\n    array2.sort((a, b) => a.start_minute - b.start_minute);\n    return array2;\n  }\n\n  /**\n   * @returns periods starting from Monday\n   */\n  static getDaysHours(hours: BusinessWeeklyOpen[]) {\n    const days: Period[][] = new Array(7);\n    for(let i = 0; i < days.length; ++i) {\n      days[i] = [];\n    }\n    for(let i = 0; i < hours.length; ++i) {\n      const period = hours[i];\n      const day = Math.floor((period.start_minute / ONE_DAY_MINUTES) % 7);\n      const start = period.start_minute % ONE_DAY_MINUTES;\n      const end = start + (period.end_minute - period.start_minute);\n      days[day].push(new Period(start, end));\n    }\n    for(let i = 0; i < 7; ++i) {\n      const start = ONE_DAY_MINUTES * i;\n      const end = ONE_DAY_MINUTES * (i + 1);\n\n      let m = start;\n      for(let j = 0; j < hours.length; ++j) {\n        const period = hours[j];\n        if(period.start_minute <= m && period.end_minute >= m) {\n          m = period.end_minute + 1;\n        }\n      }\n\n      const isFull = m >= end;\n      if(isFull) {\n        const prevDay = (7 + i - 1) % 7;\n        if(days[prevDay].length && days[prevDay][days[prevDay].length - 1].end >= ONE_DAY_MINUTES) {\n          days[prevDay][days[prevDay].length - 1].end = ONE_DAY_MINUTES - 1;\n        }\n        days[i].length = 0;\n        days[i].push(new Period(0, ONE_DAY_MINUTES - 1));\n      } else {\n        const nextDay = (i + 1) % 7;\n        if(days[i].length && days[nextDay].length) {\n          const todayLast = days[i][days[i].length - 1];\n          const tomorrowFirst = days[nextDay][0];\n          if(todayLast.end > ONE_DAY_MINUTES && todayLast.end - ONE_DAY_MINUTES + 1 === tomorrowFirst.start) {\n            todayLast.end = ONE_DAY_MINUTES - 1;\n            tomorrowFirst.start = 0;\n          }\n        }\n      }\n    }\n    return days;\n  }\n\n  static is24x7(hours: BusinessWorkHours) {\n    if(!hours || !hours.weekly_open.length) return false;\n    let last = 0;\n    for(let i = 0; i < hours.weekly_open.length; ++i) {\n      const period = hours.weekly_open[i];\n      if(period.start_minute > last + 1) return false;\n      last = period.end_minute;\n    }\n    return last >= ONE_WEEK_MINUTES - 1;\n  }\n\n  static isOpenNow(adapted_weekly_open: BusinessWeeklyOpen[]) {\n    const date = new Date();\n\n    const nowWeekday = (7 + date.getDay() - 1) % 7;\n    const nowHours = date.getHours();\n    const nowMinutes = date.getMinutes();\n\n    let openNow = false;\n    const nowPeriodTime = nowMinutes + nowHours * 60 + nowWeekday * ONE_DAY_MINUTES;\n    for(let i = 0; i < adapted_weekly_open.length; ++i) {\n      const weeklyPeriod = adapted_weekly_open[i];\n      if(\n        nowPeriodTime >= weeklyPeriod.start_minute && nowPeriodTime <= weeklyPeriod.end_minute ||\n        (nowPeriodTime + ONE_WEEK_MINUTES) >= weeklyPeriod.start_minute && (nowPeriodTime + ONE_WEEK_MINUTES) <= weeklyPeriod.end_minute ||\n        (nowPeriodTime - ONE_WEEK_MINUTES) >= weeklyPeriod.start_minute && (nowPeriodTime - ONE_WEEK_MINUTES) <= weeklyPeriod.end_minute\n      ) {\n        openNow = true;\n        break;\n      }\n    }\n\n    return {openNow, nowWeekday, nowHours, nowPeriodTime};\n  }\n\n  static isFull(periods: Period[]) {\n    if(!periods || !periods.length) return false;\n    let lastTime = 0;\n    for(let i = 0; i < periods.length; ++i) {\n      const p = periods[i];\n      if(lastTime < p.start) {\n        return false;\n      }\n      lastTime = p.end;\n    }\n    return lastTime === (ONE_DAY_MINUTES - 1) || lastTime === ONE_DAY_MINUTES;\n  }\n}\n","export default function rotateArray<T>(array: T[], n: number) {\n  const front = array.slice(n);\n  const back = array.slice(0, n);\n  return front.concat(back);\n}\n","import {onCleanup} from 'solid-js';\nimport {requestRAF} from '@helpers/solid/requestRAF';\n\n\ntype ResizeCallbackArgs = {\n  entry: ResizeObserverEntry;\n  size: {\n    width: number;\n    height: number;\n  };\n};\n\ntype ResizeCallback = (args: ResizeCallbackArgs) => void;\n\nexport function useResizeObserver() {\n  const callbacks = new Map<Element, ResizeCallback>();\n  const queuedCallbacks = new Map<Element, () => void>();\n\n  const observer = new ResizeObserver(entries => {\n    for(const entry of entries) {\n      if(!queuedCallbacks.has(entry.target))\n        requestRAF(() => {\n          const cb = queuedCallbacks.get(entry.target);\n          queuedCallbacks.delete(entry.target);\n          cb?.();\n        });\n\n      queuedCallbacks.set(entry.target, () => {\n        const cb = callbacks.get(entry.target);\n        const boxSize = entry.borderBoxSize[0];\n        if(cb && boxSize) {\n          cb({\n            entry,\n            size: {width: boxSize.inlineSize, height: boxSize.blockSize}\n          });\n        }\n      });\n    }\n  });\n\n  onCleanup(() => {\n    observer.disconnect();\n    callbacks.clear();\n    queuedCallbacks.clear();\n  });\n\n  return (el: Element, cb: ResizeCallback) => {\n    callbacks.set(el, cb);\n    observer.observe(el);\n\n    onCleanup(() => {\n      callbacks.delete(el);\n      observer.unobserve(el);\n    });\n  };\n}\n","import {createMemo, createSignal, For, Show} from 'solid-js';\nimport OpeningHours from '@helpers/openingHours';\nimport {BusinessWorkHours, Timezone} from '@layer';\nimport RowTsx from '@components/rowTsx';\nimport I18n, {i18n} from '@lib/langPack';\nimport {getWeekDays, ONE_DAY_MINUTES, ONE_WEEK_MINUTES} from '@helpers/date';\nimport rotateArray from '@helpers/array/rotate';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\nimport Animated from '@helpers/solid/animations';\nimport {useResizeObserver} from '@hooks/useResizeObserver';\n\ntype BusinessHoursRow = {\n  periods: string[],\n  weekDay: string\n};\n\nexport default function BusinessHours(props: {\n  hours: () => BusinessWorkHours,\n  timezones: () => Timezone[]\n}) {\n  const [expanded, setExpanded] = createSignal(false);\n  const [showInMyTimezone, setShowInMyTimezone] = createSignal(false);\n  const [detailsHeight, setDetailsHeight] = createSignal(0);\n  const observeResize = useResizeObserver();\n\n  const model = createMemo(() => {\n    const workHours = props.hours();\n    const timezones = props.timezones();\n    if(!workHours || !timezones) {\n      return;\n    }\n\n    const timezone = timezones.find((timezone) => timezone.id === workHours.timezone_id);\n    const currentUtcOffset = -new Date().getTimezoneOffset();\n    const valueUtcOffset = !timezone ? 0 : timezone.utc_offset / 60;\n    const utcOffset = currentUtcOffset - valueUtcOffset;\n    const isDifferentTimezone = !!utcOffset;\n    const useMyTimezone = isDifferentTimezone ? showInMyTimezone() : true;\n    const is24x7 = OpeningHours.is24x7(workHours);\n    const weeklyOpen = workHours.weekly_open;\n    const adaptedWeeklyOpen = OpeningHours.adaptWeeklyOpen(weeklyOpen, utcOffset);\n    const {openNow, nowPeriodTime, nowWeekday} = OpeningHours.isOpenNow(adaptedWeeklyOpen);\n\n    const formatDay = (day: Parameters<typeof OpeningHours.isFull>[0], index: number) => {\n      if(OpeningHours.isFull(day)) {\n        return [I18n.format('BusinessHoursProfileOpen', true)];\n      }\n\n      if(!index && !openNow && !expanded()) {\n        let opensPeriodTime = -1;\n        for(let i = 0; i < adaptedWeeklyOpen.length; ++i) {\n          const weekly = adaptedWeeklyOpen[i];\n          if(nowPeriodTime < weekly.start_minute) {\n            opensPeriodTime = weekly.start_minute;\n            break;\n          }\n        }\n\n        if(opensPeriodTime === -1 && adaptedWeeklyOpen.length) {\n          opensPeriodTime = adaptedWeeklyOpen[0].start_minute;\n        }\n\n        if(opensPeriodTime === -1) {\n          return [I18n.format('BusinessHoursProfileClose', true)];\n        }\n\n        const diff = opensPeriodTime < nowPeriodTime ?\n          opensPeriodTime + (ONE_WEEK_MINUTES - nowPeriodTime) :\n          opensPeriodTime - nowPeriodTime;\n        if(diff < 60) {\n          return [I18n.format('BusinessHoursProfileOpensInMinutes', true, [diff])];\n        }\n        if(diff < ONE_DAY_MINUTES) {\n          return [I18n.format('BusinessHoursProfileOpensInHours', true, [Math.ceil(diff / 60)])];\n        }\n        return [I18n.format('BusinessHoursProfileOpensInDays', true, [Math.ceil(diff / ONE_DAY_MINUTES)])];\n      }\n\n      const result = day.map((period) => period.toString());\n      return result.length ? result : [I18n.format('BusinessHoursProfileClose', true)];\n    };\n\n    const formatDays = (days: ReturnType<typeof OpeningHours.getDaysHours>) => {\n      return rotateArray(days, nowWeekday).map(formatDay);\n    };\n\n    const localDays = formatDays(OpeningHours.getDaysHours(weeklyOpen));\n    const myDays = formatDays(OpeningHours.getDaysHours(adaptedWeeklyOpen));\n    const days = useMyTimezone ? myDays : localDays;\n    const weekDays = rotateArray(getWeekDays(), nowWeekday);\n    const rows: BusinessHoursRow[] = days.map((periods, index) => ({\n      periods: index === 0 ? periods.slice(1) : periods,\n      weekDay: weekDays[index]\n    }));\n    const text = rotateArray(days.map((periods, index) => (\n      `${weekDays[index]}: ${periods.join(', ')}`\n    )), -nowWeekday).join('\\n');\n\n    return {\n      is24x7,\n      isDifferentTimezone,\n      openNow,\n      rows,\n      subtitleRight: is24x7 ? I18n.format('BusinessHoursProfileFullOpen', true) : days[0][0],\n      text\n    };\n  });\n\n  return (\n    <RowTsx\n      class=\"business-hours-container\"\n      classList={{'is-expanded': expanded()}}\n      style={{\n        'padding-bottom': expanded() && !model()?.is24x7 && detailsHeight() ?\n          `${10 + detailsHeight()}px` :\n          undefined\n      }}\n      clickable={() => {\n        if(!model()?.is24x7) {\n          setExpanded((value) => !value);\n        }\n      }}\n      contextMenu={{\n        buttons: [{\n          icon: 'copy',\n          text: 'Copy',\n          onClick: () => {\n            copyTextToClipboard(model()?.text || '');\n            toastNew({langPackKey: 'BusinessHoursCopied'});\n          }\n        }]\n      }}\n    >\n      <RowTsx.Icon icon=\"time_filled\" />\n      <RowTsx.Title\n        class={model()?.openNow ? 'green' : 'danger'}\n        titleRight={(\n          <Show when={model()?.isDifferentTimezone}>\n            <span\n              class=\"business-hours-switch-time\"\n              onClick={(event) => {\n                event.preventDefault();\n                event.stopPropagation();\n                setShowInMyTimezone((value) => !value);\n                setExpanded(true);\n              }}\n            >\n              {i18n(showInMyTimezone() ? 'BusinessHoursProfileSwitchMy' : 'BusinessHoursProfileSwitchLocal')}\n            </span>\n          </Show>\n        )}\n      >\n        {model() && i18n(model().openNow ? 'BusinessHoursProfileNowOpen' : 'BusinessHoursProfileNowClosed')}\n      </RowTsx.Title>\n      <RowTsx.Subtitle subtitleRight={model()?.subtitleRight}>\n        {i18n('BusinessHoursProfile')}\n      </RowTsx.Subtitle>\n      <Animated type=\"cross-fade\">\n        <Show keyed when={!model()?.is24x7 && model()}>{(current) => (\n          <div\n            ref={(element) => {\n              observeResize(element, ({size}) => setDetailsHeight(size.height));\n            }}\n            class=\"business-hours\"\n          >\n            <For each={current.rows}>{({periods, weekDay}, dayIndex) => (\n              <For each={periods}>{(period, periodIndex) => (\n                <div class=\"business-hours-row\">\n                  <div class=\"business-hours-row-day\">\n                    {dayIndex() !== 0 && periodIndex() === 0 ? weekDay : ''}\n                  </div>\n                  <div class=\"business-hours-row-time\">{period}</div>\n                </div>\n              )}</For>\n            )}</For>\n          </div>\n        )}</Show>\n      </Animated>\n    </RowTsx>\n  );\n}\n","const Languages = [\n  ['af', 'Afrikaans'],\n  ['sq', 'Shqip'],\n  ['am', 'አማርኛ'],\n  ['ar', 'العربية'],\n  ['hy', 'Հայերեն'],\n  ['az', 'Azərbaycan dili'],\n  ['eu', 'Euskara'],\n  ['be', 'Беларуская'],\n  ['bn', 'বাংলা'],\n  ['bs', 'Bosanski'],\n  ['bg', 'Български'],\n  ['ca', 'Català'],\n  ['ceb', 'Cebuano'],\n  ['zh-CN', '简体中文'],\n  ['zh', '中文'],\n  ['zh-TW', '繁體中文'],\n  ['co', 'Corsu'],\n  ['hr', 'Hrvatski'],\n  ['cs', 'Čeština'],\n  ['da', 'Dansk'],\n  ['nl', 'Nederlands'],\n  ['en', 'English'],\n  ['eo', 'Esperanto'],\n  ['et', 'Eesti'],\n  ['fi', 'Suomi'],\n  ['fr', 'Français'],\n  ['fy', 'Frysk'],\n  ['gl', 'Galego'],\n  ['ka', 'ქართული'],\n  ['de', 'Deutsch'],\n  ['el', 'Ελληνικά'],\n  ['gu', 'ગુજરાતી'],\n  ['ht', 'Kreyòl ayisyen'],\n  ['ha', 'Hausa'],\n  ['haw', 'ʻŌlelo Hawaiʻi'],\n  ['he', 'עברית'],\n  ['iw', 'עברית'],\n  ['hi', 'हिन्दी'],\n  ['hmn', 'Hmoob'],\n  ['hu', 'Magyar'],\n  ['is', 'Íslenska'],\n  ['ig', 'Igbo'],\n  ['id', 'Indonesia'],\n  ['ga', 'Gaeilge'],\n  ['it', 'Italiano'],\n  ['ja', '日本語'],\n  ['jv', 'Basa Jawa'],\n  ['kn', 'ಕನ್ನಡ'],\n  ['kk', 'Қазақ тілі'],\n  ['km', 'ភាសាខ្មែរ'],\n  ['rw', 'Kinyarwanda'],\n  ['ko', '한국어'],\n  ['ku', 'Kurdî'],\n  ['ky', 'Кыргызча'],\n  ['lo', 'ລາວ'],\n  ['la', 'Latina'],\n  ['lv', 'Latviešu'],\n  ['lt', 'Lietuvių'],\n  ['lb', 'Lëtzebuergesch'],\n  ['mk', 'Македонски'],\n  ['mg', 'Malagasy'],\n  ['ms', 'Bahasa Melayu'],\n  ['ml', 'മലയാളം'],\n  ['mt', 'Malti'],\n  ['mi', 'Māori'],\n  ['mr', 'मराठी'],\n  ['mn', 'Монгол'],\n  ['my', 'ဗမာ'],\n  ['ne', 'नेपाली'],\n  ['no', 'Norsk'],\n  ['ny', 'Chichewa'],\n  ['or', 'ଓଡ଼ିଆ'],\n  ['ps', 'پښتو'],\n  ['fa', 'فارسی'],\n  ['pl', 'Polski'],\n  ['pt', 'Português'],\n  ['pa', 'ਪੰਜਾਬੀ'],\n  ['ro', 'Română'],\n  ['ru', 'Русский'],\n  ['sm', 'Gagana fa\\'a Samoa'],\n  ['gd', 'Gàidhlig'],\n  ['sr', 'Српски'],\n  ['st', 'Sesotho'],\n  ['sn', 'Shona'],\n  ['sd', 'سنڌي'],\n  ['si', 'සිංහල'],\n  ['sk', 'Slovenčina'],\n  ['sl', 'Slovenščina'],\n  ['so', 'Soomaali'],\n  ['es', 'Español'],\n  ['su', 'Basa Sunda'],\n  ['sw', 'Kiswahili'],\n  ['sv', 'Svenska'],\n  ['tl', 'Tagalog'],\n  ['tg', 'Тоҷикӣ'],\n  ['ta', 'தமிழ்'],\n  ['tt', 'Татар теле'],\n  ['te', 'తెలుగు'],\n  ['th', 'ไทย'],\n  ['tr', 'Türkçe'],\n  ['tk', 'Türkmen'],\n  ['uk', 'Українська'],\n  ['ur', 'اردو'],\n  ['ug', 'ئۇيغۇرچە'],\n  ['uz', 'O‘zbek'],\n  ['vi', 'Tiếng Việt'],\n  ['cy', 'Cymraeg'],\n  ['xh', 'isiXhosa'],\n  ['yi', 'ייִדיש'],\n  ['yo', 'Yorùbá'],\n  ['zu', 'isiZulu']\n] as const;\n\nexport default Languages;\n","/**\n * Solid replacement for the imperative `PinnedContainer`.\n *\n * Composable namespace component (shape mirrors `tabs.tsx`):\n *\n *   <TopbarPlate modifier=\"message\" hidden={hidden()}>\n *     <TopbarPlate.Body onClick={onFollow}>\n *       <TopbarPlate.Content>\n *         <TopbarPlate.Title>{title}</TopbarPlate.Title>\n *         <TopbarPlate.Subtitle>{subtitle}</TopbarPlate.Subtitle>\n *       </TopbarPlate.Content>\n *       <TopbarPlate.CloseButton onClick={onClose} />\n *     </TopbarPlate.Body>\n *   </TopbarPlate>\n *\n * Class names match the existing `pinned-${modifier}` SCSS so legacy\n * stylesheets (`_chatPinned.scss`) keep working. Anything single-use lives\n * in the consuming plate, not here.\n *\n * `createTopbarPlate(...)` is a bridge for class-based callers (currently\n * `topbar.ts`) that need an imperative controller with `.container` /\n * `.height` / `.isVisible()`. Once the topbar itself is rewritten to TSX\n * the bridge can be dropped — drop `<TopbarPlate>` straight into the JSX.\n */\n\nimport {Accessor, createContext, createSignal, JSX, onCleanup, Ref, useContext} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport classNames from '@helpers/string/classNames';\nimport ripple from '@components/ripple';\nimport Button from '@components/buttonTsx';\nimport RippleElement from '@components/rippleElement';\n\nconst BASE = 'pinned-container';\n\ntype PlateContextValue = {\n  modifier: string\n};\n\nconst PlateContext = createContext<PlateContextValue>();\n\nconst useModifier = () => useContext(PlateContext)!.modifier;\nconst baseCls = (suffix: string) => `${BASE}-${suffix}`;\nconst modCls = (modifier: string, suffix: string) => `pinned-${modifier}-${suffix}`;\n\nconst TopbarPlate = (props: {\n  /** Modifier identifier (e.g. `message`, `audio`, `translation`, `live`) — drives `pinned-${modifier}-*` classes. */\n  modifier: string,\n  /** Controlled hidden state. When true, applies `hide` class. */\n  hidden?: boolean,\n  class?: string,\n  ref?: Ref<HTMLDivElement>,\n  children: JSX.Element\n}) => {\n  return (\n    <PlateContext.Provider value={{modifier: props.modifier}}>\n      <div\n        ref={props.ref}\n        class={classNames(\n          BASE,\n          `pinned-${props.modifier}`,\n          props.hidden && 'hide',\n          props.class\n        )}\n      >\n        {props.children}\n      </div>\n    </PlateContext.Provider>\n  );\n};\n\nTopbarPlate.Body = (props: {\n  ref?: Ref<HTMLDivElement>,\n  noRipple?: boolean,\n  class?: string,\n  onClick?: (e: MouseEvent) => void,\n  children: JSX.Element\n}) => {\n  const modifier = useModifier();\n  return (\n    <RippleElement\n      component=\"div\"\n      noRipple={props.noRipple}\n      class={classNames(baseCls('wrapper'), modCls(modifier, 'wrapper'), props.class)}\n      onClick={props.onClick}\n    >\n      {props.children}\n    </RippleElement>\n  );\n};\n\nTopbarPlate.Content = (props: {\n  class?: string,\n  children: JSX.Element,\n  ripple?: boolean\n}) => {\n  const modifier = useModifier();\n  return (\n    <RippleElement\n      component=\"div\"\n      noRipple={!props.ripple}\n      class={classNames(baseCls('content'), modCls(modifier, 'content'), props.class)}\n    >\n      {props.children}\n    </RippleElement>\n  );\n};\n\nTopbarPlate.Title = (props: {\n  class?: string,\n  children: JSX.Element\n}) => {\n  const modifier = useModifier();\n  return (\n    <div class={classNames(baseCls('title'), modCls(modifier, 'title'), props.class)}>\n      {props.children}\n    </div>\n  );\n};\n\nTopbarPlate.Subtitle = (props: {\n  class?: string,\n  children: JSX.Element\n}) => {\n  const modifier = useModifier();\n  return (\n    <div class={classNames(baseCls('subtitle'), modCls(modifier, 'subtitle'), props.class)}>\n      {props.children}\n    </div>\n  );\n};\n\nTopbarPlate.CloseButton = (props: {\n  onClick?: (e: MouseEvent) => void,\n  class?: string,\n  ref?: Ref<HTMLElement>\n}) => {\n  const modifier = useModifier();\n  return (\n    <Button.Icon\n      ref={props.ref}\n      icon=\"close\"\n      class={classNames(baseCls('close'), modCls(modifier, 'close'), props.class)}\n      onClick={props.onClick}\n      noRipple\n    />\n  );\n};\n\nTopbarPlate.ActionButton = (props: {\n  /** Set true while the previous button cross-fades out. Adds `is-leaving`. */\n  leaving?: boolean,\n  as?: 'button' | 'a',\n  class?: string,\n  onClick?: (e: MouseEvent) => void,\n  ref?: Ref<HTMLElement>,\n  children: JSX.Element\n}) => {\n  const modifier = useModifier();\n  const className = () => classNames(\n    baseCls('action-button'),\n    modCls(modifier, 'action-button'),\n    'text-overflow-no-wrap',\n    props.leaving && 'is-leaving',\n    props.class\n  );\n  return props.as === 'a' ?\n    <a\n      ref={props.ref as Ref<HTMLAnchorElement>}\n      class={className()}\n      onClick={props.onClick}\n    >\n      {props.children}\n    </a> :\n    <button\n      ref={props.ref as Ref<HTMLButtonElement>}\n      class={className()}\n      onClick={props.onClick}\n    >\n      {props.children}\n    </button>;\n};\n\nTopbarPlate.PrimaryButton = (props: {\n  onClick: () => void,\n  children: JSX.Element,\n  class?: string,\n  danger?: boolean,\n  /** Plain label: default text colour and a neutral hover, no primary tint. */\n  quiet?: boolean,\n  ref?: Ref<HTMLElement>\n}) => {\n  const modifier = useModifier();\n  return (\n    <Button\n      ref={props.ref}\n      class={classNames(\n        baseCls('primary-button'),\n        modCls(modifier, 'primary-button'),\n        props.danger && 'btn-primary btn-transparent danger',\n        props.quiet && 'btn-primary btn-transparent',\n        props.class\n      )}\n      primaryTransparent={!props.danger && !props.quiet}\n      onClick={props.onClick}\n    >\n      {props.children}\n    </Button>\n  );\n};\n\nexport default TopbarPlate;\n\n// =============================================================================\n// Imperative controller — bridge for class-based callers (topbar.ts).\n// =============================================================================\n\nexport type TopbarPlateController = {\n  /** The plate's root DOM element. Append it wherever needed. */\n  container: HTMLElement,\n  /** Height read by `topbar.setFloating()`. `'auto'` = measured at runtime. */\n  height: number | 'auto',\n  /** Reactive hidden state — useful for outer effects that depend on visibility. */\n  hidden: Accessor<boolean>,\n  setHidden: (hidden: boolean) => void,\n  /** Convenience for legacy `pinnedContainer.isVisible()` callers. */\n  isVisible: () => boolean,\n  destroy: () => void\n};\n\nexport type CreateTopbarPlateOptions = {\n  modifier: string,\n  height: number | 'auto',\n  /** Defaults to `true` — plate stays hidden until first content is ready. */\n  initiallyHidden?: boolean,\n  /**\n   * Reactive class accessor applied to the plate root in addition to the\n   * built-in `pinned-container` / `pinned-${modifier}` / `hide` classes.\n   * Use this instead of mutating `controller.container.classList` from\n   * imperative callers so class state stays in the Solid reactive system.\n   */\n  class?: Accessor<string>,\n  /** Called every time `hidden` flips — typically wires `topbar.setFloating`. */\n  onVisibilityChange?: (visible: boolean) => void,\n  /**\n   * Render fn for the plate body. Receives the live `hidden` accessor and\n   * its setter so consumers can drive visibility from inside (e.g. via\n   * `createEffect(() => setHidden(!shouldShow()))`).\n   */\n  render: (api: {\n    hidden: Accessor<boolean>,\n    setHidden: (hidden: boolean) => void\n  }) => JSX.Element\n};\n\n/**\n * Mount a `<TopbarPlate>` detached from any parent and return an imperative\n * controller. The consumer takes ownership of `.container` and places it\n * into its own layout.\n */\nexport const createTopbarPlate = (options: CreateTopbarPlateOptions): TopbarPlateController => {\n  const [hidden, setHiddenSignal] = createSignal(options.initiallyHidden ?? true);\n  const setHidden = (next: boolean) => {\n    if(hidden() === next) return;\n    setHiddenSignal(next);\n    options.onVisibilityChange?.(!next);\n  };\n\n  let plateEl: HTMLDivElement;\n  const host = document.createElement('div');\n\n  const dispose = render(() => (\n    <TopbarPlate\n      modifier={options.modifier}\n      hidden={hidden()}\n      class={options.class?.()}\n      ref={(el) => (plateEl = el)}\n    >\n      {options.render({hidden, setHidden})}\n    </TopbarPlate>\n  ), host);\n\n  return {\n    container: plateEl!,\n    height: options.height,\n    hidden,\n    setHidden,\n    isVisible: () => !hidden(),\n    destroy: () => {\n      dispose();\n      plateEl?.remove();\n    }\n  };\n};\n","import {Accessor, createEffect, createMemo, createSignal} from 'solid-js';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport {AppManagers} from '@lib/managers';\nimport I18n, {i18n} from '@lib/langPack';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport SearchIndex from '@lib/searchIndex';\nimport Languages from '@lib/tinyld/languages';\nimport usePremium from '@stores/premium';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport Icon from '@components/icon';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport PopupPremium from '@components/popups/premium';\nimport RowTsx from '@components/rowTsx';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\nimport Chat from '@components/chat/chat';\nimport ChatTopbar from '@components/chat/topbar';\nimport {useAppSettings} from '@stores/appSettings';\nimport {toastNew} from '@components/toast';\nimport {usePeer} from '@stores/peers';\nimport {Chat as MTChat} from '@layer';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\nexport function pickLanguage<T extends boolean>(\n  multi?: T,\n  selected?: Array<TranslatableLanguageISO>\n): T extends true ? Promise<TranslatableLanguageISO[]> : Promise<TranslatableLanguageISO> {\n  const deferred = deferredPromise<TranslatableLanguageISO>();\n\n  const index = new SearchIndex({ignoreCase: true});\n  const map: Map<string, [string, string]> = new Map();\n  Languages.forEach(([iso2, name]) => {\n    const translated = I18n.format(`Language.${iso2}`, true);\n    map.set(iso2, [name, translated]);\n    index.indexObjectArray(iso2, [iso2, name, translated]);\n  });\n\n  const popup = showPickUserPopup({\n    peerType: ['custom'],\n    renderResultsFunc: (iso2s) => {\n      const middleware = popup.selector.middlewareHelperLoader.get();\n      iso2s.forEach((iso2) => {\n        const [name, translated] = map.get(iso2 as any as string);\n        const checkbox = multi ? popup.selector.checkbox(popup.selector.selected.has(iso2)) : undefined;\n        const row = wrapSolidComponent(() => (\n          <RowTsx\n            ref={(element) => {\n              element.dataset.peerId = String(iso2);\n            }}\n            clickable\n            havePadding={multi}\n          >\n            {checkbox}\n            <RowTsx.Title>{translated}</RowTsx.Title>\n            <RowTsx.Subtitle>{name}</RowTsx.Subtitle>\n          </RowTsx>\n        ), middleware);\n\n        popup.selector.list.append(row);\n      });\n    },\n    placeholder: 'Search',\n    getMoreCustom: async(q) => {\n      const filtered = q ? [...index.search(q)] : Languages.map(([iso2]) => iso2);\n      return {\n        result: filtered as any,\n        isEnd: true\n      };\n    },\n    onSelect: (results) => {\n      const keys = results.map(({key}) => key);\n      deferred.resolve(multi ? keys as any : keys[0]);\n    },\n    multiSelect: multi,\n    titleLangKey: 'Telegram.LanguageViewController',\n    checkboxSide: 'left',\n    noPlaceholder: true,\n    onClose: () => deferred.reject(),\n    footerButtonProps: {\n      children: i18n('Save')\n    }\n  });\n\n  // Only in multi-select: `addInitial` in single-select mode counts as a user\n  // pick and instantly resolves + closes the popup, and the `add` override is\n  // dead anyway (chips are rendered by the selector only when multi is on).\n  if(multi && selected) {\n    const _add = popup.selector.add.bind(popup.selector);\n    popup.selector.add = ({key, scroll}) => {\n      const ret = _add({\n        key: key,\n        title: i18n(`Language.${key as TranslatableLanguageISO}`),\n        scroll,\n        fallbackIcon: 'check'\n      });\n      return ret;\n    };\n\n    popup.selector.addInitial(selected);\n  }\n\n  return deferred as any;\n}\n\nexport type ChatTranslationPlate = TopbarPlateController & {\n  setPeerId: (peerId: PeerId) => void\n};\n\n/**\n * Top-level component so solid-refresh can swap it on HMR. The plate\n * factory's closure state (the peerId signal) is preserved because the\n * factory isn't re-invoked when this file hot-updates.\n */\nfunction TranslationPlateBody(props: {\n  peerId: Accessor<PeerId>,\n  managers: AppManagers,\n  setHidden: (hidden: boolean) => void\n}) {\n  const i = new I18n.IntlElement({key: 'DoNotTranslateLanguage'});\n\n  const peerTranslation = createMemo(() => usePeerTranslation(props.peerId()));\n  const isPremium = usePremium();\n\n  createEffect(() => {\n    i.compareAndUpdate({args: [i18n(`Language.${peerTranslation().peerLanguage()}`)]});\n  });\n\n  createEffect(() => props.setHidden(!peerTranslation().shouldShow()));\n\n  const listenerSetter = new ListenerSetter();\n  const menu = ButtonMenuToggle({\n    direction: 'bottom-left',\n    buttons: [{\n      icon: 'premium_translate',\n      text: 'Chat.Translate.Menu.To',\n      onClick: async() => {\n        const iso2 = await pickLanguage(false);\n        peerTranslation().setLanguage(iso2);\n      },\n      verify: isPremium\n    }, {\n      icon: 'hand',\n      textElement: i.element,\n      onClick: () => {\n        const [_, setAppSettings] = useAppSettings();\n        setAppSettings('translations', 'doNotTranslate', (arr) => [...arr, peerTranslation().peerLanguage()]);\n      },\n      verify: isPremium,\n      separatorDown: true\n    }, {\n      icon: 'crossround',\n      text: 'Hide',\n      onClick: () => {\n        const peer = usePeer(props.peerId());\n        toastNew({\n          langPackKey: (peer as MTChat.channel).pFlags.broadcast ?\n            'TranslationBarHiddenChannel' :\n            'TranslationBarHidden'\n        });\n        props.managers.appTranslationsManager.togglePeerTranslations(props.peerId(), true);\n      }\n    }],\n    listenerSetter\n  });\n  menu.classList.add('pinned-translation-menu');\n\n  return (\n    <>\n      <TopbarPlate.PrimaryButton\n        onClick={() => {\n          const translation = peerTranslation();\n          if(!translation.canTranslate()) {\n            PopupPremium.show({feature: 'translations'});\n            return;\n          }\n          translation.toggle(!translation.enabled());\n        }}\n      >\n        {Icon('premium_translate', 'pinned-translation-primary-button-icon')}\n        {peerTranslation().enabled() ?\n          i18n('ShowOriginalButton') :\n          i18n('TranslateToButton', [i18n(`Language.${peerTranslation().language()}`)])\n        }\n      </TopbarPlate.PrimaryButton>\n      {menu}\n    </>\n  );\n}\n\nexport default function createChatTranslationPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatTranslationPlate {\n  const [peerId, setPeerIdSignal] = createSignal<PeerId>(NULL_PEER_ID);\n\n  const plate = createTopbarPlate({\n    modifier: 'translation',\n    height: 48,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: ({setHidden}) => <TranslationPlateBody peerId={peerId} managers={managers} setHidden={setHidden} />\n  });\n\n  return {\n    ...plate,\n    setPeerId: (next) => setPeerIdSignal(next)\n  };\n}\n","import type {Chat, User} from '@layer';\nimport {i18n} from '@lib/langPack';\n\ntype CommunityPeer = Chat | User;\n\nexport function getCommunityPeerParticipantsCount(peer?: CommunityPeer) {\n  if(peer?._ === 'channel' || peer?._ === 'chat') {\n    return peer.participants_count;\n  }\n}\n\nexport function getCommunityPeerSubtitle(peer?: CommunityPeer) {\n  if(peer?._ === 'user' && peer.pFlags.bot) {\n    return i18n('Bot');\n  }\n\n  const participantsCount = getCommunityPeerParticipantsCount(peer);\n  if(participantsCount !== undefined) {\n    return i18n(\n      peer?._ === 'channel' && !peer.pFlags.megagroup ?\n        'Subscribers' :\n        'Members',\n      [participantsCount]\n    );\n  }\n\n  return peer?._ === 'channel' && !peer.pFlags.megagroup ?\n    i18n('Channel') :\n    i18n('Group');\n}\n","import noop from '@helpers/noop';\nimport type {\n  AppDialogsManager,\n  DialogElement\n} from '@lib/appDialogsManager';\n\ntype AddListDialogOptions = Parameters<\n  AppDialogsManager['addListDialog']\n>[0];\n\nexport default function createCommunityDialogElement(\n  manager: Pick<AppDialogsManager, 'addDialogNew' | 'addListDialog'>,\n  peerId: PeerId,\n  wrapOptions: AddListDialogOptions['wrapOptions'],\n  options: Pick<\n    AddListDialogOptions,\n    | 'avatarSize'\n    | 'autoDeletePeriod'\n    | 'dialog'\n    | 'dontSetActive'\n    | 'lastMessage'\n    | 'onInitPromise'\n  >,\n  initialize = true\n): DialogElement {\n  const loadPromises: Promise<any>[] = [];\n  const dialogOptions: AddListDialogOptions = {\n    peerId,\n    loadPromises,\n    isBatch: true,\n    isMainList: false,\n    controlled: true,\n    meAsSaved: true,\n    wrapOptions,\n    ...options\n  };\n  const dialogElement = initialize ?\n    manager.addListDialog(dialogOptions) :\n    manager.addDialogNew({\n      ...dialogOptions,\n      autonomous: false,\n      withStories: true\n    });\n  if(initialize) {\n    void Promise.all(loadPromises).catch(noop);\n  }\n  dialogElement.dom.listEl.dataset.communityDialog = 'true';\n  return dialogElement;\n}\n","/* @refresh skip */\n// Owns imperative DialogElements and nested Solid roots, so updates remount its owner.\n\nimport type {Chat} from '@layer';\nimport createCommunityAvatarElement\nfrom '@components/communities/communityAvatarElement';\nimport {\n  getCommunityPeerSubtitle\n} from '@components/communities/communityPeerStatus';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport type {Middleware} from '@helpers/middleware';\nimport appDialogsManager, {\n  DialogElement,\n  DialogElementSize\n} from '@lib/appDialogsManager';\nimport createCommunityDialogElement\nfrom '@components/autonomousDialogList/createCommunityDialogElement';\nimport {i18n} from '@lib/langPack';\nimport {useCommunityFulls} from '@stores/communities';\nimport {usePeer} from '@stores/peers';\nimport {\n  createEffect,\n  createRoot,\n  createSignal,\n  JSX,\n  onCleanup,\n  Show\n} from 'solid-js';\nimport {insert, render} from 'solid-js/web';\nimport styles from '@components/communities/communityPeerDialogList.module.scss';\nimport sharedStyles from '@components/communities/communityShared.module.scss';\n\nexport type CommunityPeerDialogContextMenu = Omit<\n  Parameters<typeof createContextMenu>[0],\n  'findElement' | 'listenTo' | 'listenerSetter'\n>;\n\nexport type CommunityPeerDialogListProps<T> = {\n  items: readonly T[],\n  middleware: Middleware,\n  getPeerId: (item: T) => PeerId,\n  getSubtitle?: (item: T) => JSX.Element,\n  getTitleAccessory?: (item: T) => JSX.Element,\n  getRight?: (item: T) => JSX.Element,\n  isRightInteractive?: (item: T) => boolean,\n  getAvatarOverlayPeerId?: (item: T) => PeerId,\n  getCommunity?: (item: T) => Chat.community | Chat.communityForbidden,\n  onClick?: (item: T, event: MouseEvent) => void,\n  getContextMenu?: (item: T) => CommunityPeerDialogContextMenu,\n  // hand the rows to the shared dialog context menu (DialogsContextMenu), which reads\n  // what it needs off the row — see `getDataset`\n  withDialogContextMenu?: boolean,\n  getDataset?: (item: T) => Record<string, string>,\n  class?: string,\n  getClass?: (item: T) => string,\n  avatarSize?: DialogElementSize,\n  listRef?: (list: HTMLUListElement) => void\n};\n\nexport type CommunityDialogListProps = {\n  communities: ReadonlyArray<Chat.community | Chat.communityForbidden>,\n  middleware: Middleware,\n  onClick?: (community: Chat.community | Chat.communityForbidden, event: MouseEvent) => void,\n  getContextMenu?: (\n    community: Chat.community | Chat.communityForbidden\n  ) => CommunityPeerDialogContextMenu,\n  class?: string\n};\n\ntype DialogRecord<T> = {\n  dialogElement: DialogElement,\n  dispose: VoidFunction,\n  getItem: () => T,\n  setItem: (item: T) => void\n};\n\nfunction getClassTokens(value?: string) {\n  return value?.split(/\\s+/).filter(Boolean) || [];\n}\n\nexport default function CommunityPeerDialogList<T>(\n  props: CommunityPeerDialogListProps<T>\n) {\n  const list = appDialogsManager.createChatList();\n  const records = new Map<PeerId, DialogRecord<T>>();\n  const rightActionRows = new Map<HTMLElement, HTMLElement>();\n  let rightResizeObserver: ResizeObserver;\n  let listClassTokens: string[] = [];\n\n  const syncRightActionWidth = (right: HTMLElement) => {\n    const element = rightActionRows.get(right);\n    if(!element) {\n      return;\n    }\n\n    element.style.setProperty(\n      '--community-peer-dialog-action-width',\n      `${right.getBoundingClientRect().width}px`\n    );\n  };\n  const getRightResizeObserver = () => {\n    if(!rightResizeObserver && window.ResizeObserver) {\n      const ResizeObserverConstructor = window.ResizeObserver;\n      rightResizeObserver = new ResizeObserverConstructor((entries) => {\n        for(const entry of entries) {\n          syncRightActionWidth(entry.target as HTMLElement);\n        }\n      });\n    }\n\n    return rightResizeObserver;\n  };\n  const observeRightAction = (\n    right: HTMLElement,\n    element: HTMLElement\n  ) => {\n    if(rightActionRows.get(right) !== element) {\n      rightActionRows.set(right, element);\n      getRightResizeObserver()?.observe(right);\n    }\n    queueMicrotask(() => syncRightActionWidth(right));\n  };\n  const unobserveRightAction = (\n    right: HTMLElement,\n    element: HTMLElement\n  ) => {\n    if(rightActionRows.get(right) === element) {\n      rightResizeObserver?.unobserve(right);\n      rightActionRows.delete(right);\n    }\n    element.style.removeProperty(\n      '--community-peer-dialog-action-width'\n    );\n  };\n\n  const onListClick = (event: MouseEvent) => {\n    if(\n      event.button !== 0 ||\n      !props.onClick ||\n      (event.target as HTMLElement)\n      .closest?.('[data-dialog-list-action]')\n    ) {\n      return;\n    }\n\n    const element = (event.target as HTMLElement)\n    .closest?.<HTMLElement>('[data-community-peer-dialog]');\n    if(!element || element.parentElement !== list) {\n      return;\n    }\n\n    const record = records.get(element.dataset.peerId.toPeerId());\n    if(record) {\n      props.onClick(record.getItem(), event);\n    }\n  };\n  list.addEventListener('click', onListClick, {capture: true});\n\n  appDialogsManager.setListClickListener({\n    list,\n    onFound: () => false,\n    withContext: props.withDialogContextMenu\n  });\n  props.listRef?.(list);\n\n  createEffect(() => {\n    const nextTokens = getClassTokens(props.class);\n    for(const token of listClassTokens) {\n      if(!nextTokens.includes(token)) {\n        list.classList.remove(token);\n      }\n    }\n    for(const token of nextTokens) {\n      list.classList.add(token);\n    }\n    listClassTokens = nextTokens;\n  });\n\n  const createDialogRecord = (\n    peerId: PeerId,\n    initialItem: T\n  ): DialogRecord<T> => {\n    let record: DialogRecord<T>;\n    const dispose = createRoot((disposeRoot) => {\n      const [item, setItem] = createSignal(initialItem);\n      const initialCommunity = props.getCommunity?.(initialItem);\n      const communityAvatar = initialCommunity ?\n        createCommunityAvatarElement(initialCommunity.id, 42) :\n        undefined;\n      const communityAvatarMedia = communityAvatar &&\n        props.getAvatarOverlayPeerId ?\n        document.createElement('div') :\n        undefined;\n      if(communityAvatarMedia) {\n        communityAvatarMedia.classList.add(sharedStyles.avatarMedia);\n        communityAvatar.element.classList.add(sharedStyles.peerAvatar);\n        communityAvatarMedia.append(communityAvatar.element);\n      }\n      const peer = usePeer(() => peerId);\n      const dialogElement = initialCommunity ?\n        appDialogsManager.addDialogNew({\n          peerId,\n          container: false,\n          autonomous: true,\n          rippleEnabled: true,\n          avatarSize: 'abitbigger',\n          meAsSaved: false,\n          fromName: initialCommunity.title,\n          noIcons: true,\n          avatarElement: communityAvatarMedia || communityAvatar.element,\n          wrapOptions: {\n            middleware: props.middleware\n          }\n        }) :\n        createCommunityDialogElement(\n          appDialogsManager,\n          peerId,\n          {middleware: props.middleware},\n          {\n            avatarSize: props.avatarSize,\n            dontSetActive: true\n          },\n          false\n        );\n      if(communityAvatar) {\n        dialogElement.middlewareHelper.onDestroy(communityAvatar.dispose);\n      }\n      const {dom} = dialogElement;\n      const element = dom.listEl;\n      element.dataset.communityPeerDialog = 'true';\n\n      const activateFromKeyboard = (event: KeyboardEvent) => {\n        const MouseEventConstructor =\n          element.ownerDocument.defaultView?.MouseEvent || MouseEvent;\n        element.dispatchEvent(new MouseEventConstructor('click', {\n          bubbles: true,\n          cancelable: true,\n          button: 0,\n          ctrlKey: event.ctrlKey,\n          metaKey: event.metaKey,\n          shiftKey: event.shiftKey\n        }));\n      };\n      const onKeyDown = (event: KeyboardEvent) => {\n        if(\n          event.target !== element ||\n          !props.onClick ||\n          event.key !== 'Enter' && event.key !== ' '\n        ) {\n          return;\n        }\n\n        event.preventDefault();\n        if(event.key === 'Enter' && !event.repeat) {\n          activateFromKeyboard(event);\n        }\n      };\n      element.addEventListener('keydown', onKeyDown);\n      const onKeyUp = (event: KeyboardEvent) => {\n        if(\n          event.target !== element ||\n          !props.onClick ||\n          event.key !== ' '\n        ) {\n          return;\n        }\n\n        event.preventDefault();\n        activateFromKeyboard(event);\n      };\n      element.addEventListener('keyup', onKeyUp);\n\n      createEffect(() => {\n        const clickable = !!props.onClick;\n        if(clickable) {\n          element.setAttribute('role', 'button');\n          element.tabIndex = 0;\n        } else {\n          element.removeAttribute('role');\n          element.removeAttribute('tabindex');\n        }\n      });\n\n      let itemDatasetKeys: string[] = [];\n      createEffect(() => {\n        const next = props.getDataset?.(item()) || {};\n        for(const key of itemDatasetKeys) {\n          if(!(key in next)) {\n            delete element.dataset[key];\n          }\n        }\n        for(const [key, value] of Object.entries(next)) {\n          element.dataset[key] = value;\n        }\n        itemDatasetKeys = Object.keys(next);\n      });\n\n      let itemClassTokens: string[] = [];\n      createEffect(() => {\n        const nextTokens = getClassTokens(props.getClass?.(item()));\n        for(const token of itemClassTokens) {\n          if(!nextTokens.includes(token)) {\n            element.classList.remove(token);\n          }\n        }\n        for(const token of nextTokens) {\n          element.classList.add(token);\n        }\n        itemClassTokens = nextTokens;\n      });\n\n      const disposeSubtitle = render(\n        () => (\n          <>\n            {props.getSubtitle ?\n              props.getSubtitle(item()) :\n              getCommunityPeerSubtitle(peer())}\n          </>\n        ),\n        dom.lastMessageSpan\n      );\n      onCleanup(disposeSubtitle);\n\n      const titleAccessoryMarker = document.createComment(\n        'community-peer-title-accessory'\n      );\n      dom.titleSpan.after(titleAccessoryMarker);\n      insert(\n        dom.titleSpan.parentElement,\n        () => props.getTitleAccessory?.(item()),\n        titleAccessoryMarker\n      );\n      onCleanup(() => {\n        let node = dom.titleSpan.nextSibling;\n        while(node && node !== titleAccessoryMarker) {\n          const next = node.nextSibling;\n          node.remove();\n          node = next;\n        }\n        titleAccessoryMarker.remove();\n      });\n\n      const right = document.createElement('span');\n      dialogElement.titleRight.replaceChildren(right);\n      const disposeRight = render(\n        () => <>{props.getRight?.(item())}</>,\n        right\n      );\n      onCleanup(disposeRight);\n      onCleanup(() => unobserveRightAction(right, element));\n      createEffect(() => {\n        const interactive = !!props.isRightInteractive?.(item());\n        element.classList.toggle(styles.withRightInteractive, interactive);\n        if(interactive) {\n          right.classList.add(styles.rightInteractive);\n          right.dataset.dialogListAction = 'true';\n          element.append(right);\n          observeRightAction(right, element);\n        } else {\n          unobserveRightAction(right, element);\n          right.classList.remove(styles.rightInteractive);\n          delete right.dataset.dialogListAction;\n          dialogElement.titleRight.append(right);\n        }\n      });\n\n      if(initialCommunity) {\n        createEffect(() => {\n          void dialogElement.updateTitle(\n            props.getCommunity?.(item())?.title || ''\n          );\n        });\n      }\n\n      if(props.getAvatarOverlayPeerId) {\n        const avatarMedia = communityAvatarMedia ||\n          document.createElement('div');\n        if(!communityAvatarMedia) {\n          const avatar = dom.avatarEl?.node;\n          avatarMedia.classList.add(sharedStyles.avatarMedia);\n          if(avatar) {\n            avatar.classList.add(sharedStyles.peerAvatar);\n          }\n          dialogElement.applyMediaElement(avatarMedia, 'abitbigger');\n          if(avatar) {\n            avatarMedia.append(avatar);\n          }\n        }\n        const avatarOverlay = document.createElement('span');\n        avatarMedia.append(avatarOverlay);\n        const disposeAvatarOverlay = render(() => (\n          <Show when={props.getAvatarOverlayPeerId?.(item())}>\n            {(overlayPeerId) => (\n              <AvatarNewTsx\n                class={sharedStyles.peerAvatarOverlay}\n                peerId={overlayPeerId()}\n                size={18}\n              />\n            )}\n          </Show>\n        ), avatarOverlay);\n        onCleanup(disposeAvatarOverlay);\n      }\n\n      createEffect(() => {\n        const options = props.getContextMenu?.(item());\n        if(!options) {\n          return;\n        }\n\n        const {destroy} = createContextMenu({\n          ...options,\n          listenTo: element\n        });\n        onCleanup(destroy);\n      });\n\n      onCleanup(() => {\n        element.removeEventListener('keydown', onKeyDown);\n        element.removeEventListener('keyup', onKeyUp);\n        dialogElement.remove();\n      });\n\n      record = {\n        dialogElement,\n        dispose: disposeRoot,\n        getItem: item,\n        setItem\n      };\n      return disposeRoot;\n    });\n    record.dispose = dispose;\n    return record;\n  };\n\n  createEffect(() => {\n    const nextPeerIds: PeerId[] = [];\n    const nextItems = new Map<PeerId, T>();\n    for(const item of props.items) {\n      const peerId = props.getPeerId(item);\n      if(!nextItems.has(peerId)) {\n        nextPeerIds.push(peerId);\n      }\n      nextItems.set(peerId, item);\n    }\n\n    for(const [peerId, record] of records) {\n      if(nextItems.has(peerId)) {\n        continue;\n      }\n      records.delete(peerId);\n      record.dispose();\n    }\n\n    for(const peerId of nextPeerIds) {\n      const item = nextItems.get(peerId);\n      let record = records.get(peerId);\n      if(record) {\n        record.setItem(item);\n      } else {\n        record = createDialogRecord(peerId, item);\n        records.set(peerId, record);\n      }\n      list.append(record.dialogElement.dom.listEl);\n    }\n  });\n\n  onCleanup(() => {\n    list.removeEventListener('click', onListClick, {capture: true});\n    for(const record of records.values()) {\n      record.dispose();\n    }\n    records.clear();\n    rightResizeObserver?.disconnect();\n    rightActionRows.clear();\n  });\n\n  return list;\n}\n\nexport function CommunityDialogList(props: CommunityDialogListProps) {\n  const communityFulls = useCommunityFulls();\n\n  return (\n    <CommunityPeerDialogList\n      items={props.communities}\n      middleware={props.middleware}\n      getPeerId={(community) => community.id.toPeerId(true)}\n      getCommunity={(community) => community}\n      getSubtitle={(community) => {\n        const full = communityFulls[community.id.toChatId()];\n        return full ?\n          i18n('Community.ChatsCount', [full.linked_peers.length]) :\n          i18n('Community.Title');\n      }}\n      onClick={props.onClick}\n      getContextMenu={props.getContextMenu}\n      class={props.class}\n    />\n  );\n}\n","import {createMemo, Ref, Show} from 'solid-js';\nimport type {Chat} from '@layer';\nimport Button from '@components/buttonTsx';\nimport {\n  CommunityDialogList\n} from '@components/communities/communityPeerDialogList';\nimport Row from '@components/rowTsx';\nimport Section from '@components/section';\nimport type {Middleware} from '@helpers/middleware';\nimport {i18n, LangPackKey} from '@lib/langPack';\n\nexport default function CommunityLinkSection(props: {\n  ref?: Ref<HTMLDivElement>,\n  linkedCommunityId?: ChatId,\n  communities: ReadonlyArray<Chat.community | Chat.communityForbidden>,\n  middleware: Middleware,\n  caption: LangPackKey,\n  hideCaptionWhenLinked?: boolean,\n  hideWhenLinkedCommunityMissing?: boolean,\n  addIcon: Icon,\n  addText: LangPackKey,\n  removeText: LangPackKey,\n  onAdd: () => void,\n  onOpenCommunity: (communityId: ChatId) => void,\n  onRemove: (communityId: ChatId) => Promise<void>\n}) {\n  const community = createMemo(() => {\n    return props.communities.find((community) => {\n      return community.id.toChatId() === props.linkedCommunityId;\n    });\n  });\n  const hide = () => !!(\n    props.hideWhenLinkedCommunityMissing &&\n    props.linkedCommunityId &&\n    !community()\n  );\n\n  return (\n    <Section\n      ref={props.ref}\n      classList={{hide: hide()}}\n      caption={\n        props.hideCaptionWhenLinked && props.linkedCommunityId ?\n          undefined :\n          props.caption\n      }\n    >\n      <Show\n        when={props.linkedCommunityId}\n        fallback={(\n          <Row\n            clickable={props.onAdd}\n            role=\"button\"\n            tabIndex={0}\n          >\n            <Row.Icon icon={props.addIcon} />\n            <Row.Title>{i18n(props.addText)}</Row.Title>\n          </Row>\n        )}\n      >\n        {(linkedCommunityId) => (\n          <>\n            <Show when={community()}>\n              {(linkedCommunity) => (\n                <CommunityDialogList\n                  communities={[linkedCommunity()]}\n                  middleware={props.middleware}\n                  onClick={() => {\n                    props.onOpenCommunity(linkedCommunityId());\n                  }}\n                />\n              )}\n            </Show>\n            <Button\n              class=\"btn-primary btn-transparent danger\"\n              icon=\"delete\"\n              text={props.removeText}\n              onClick={() => props.onRemove(linkedCommunityId())}\n            />\n          </>\n        )}\n      </Show>\n    </Section>\n  );\n}\n","/**\n * How many photos the profile carousel has for a chat / channel.\n *\n * The carousel always renders the current photo as its first item, while\n * `messages.getHistory` counts only the photos that have a service message.\n * Normally the current one does, and it gets spliced out of the loaded page —\n * so the server count already covers it. When it doesn't (its service message\n * was deleted, or the photo was set without one), the current photo is\n * synthesized on top of the WHOLE history and the server count is one short —\n * which makes the click handler treat the first photo as the last one\n * (distance = -(count - 1) = 0), so the carousel never moves.\n */\nexport default function getChatPhotosCount(\n  historyCount: number,\n  loadedCount: number,\n  isCurrentSynthesized: boolean\n) {\n  const count = historyCount ?? loadedCount;\n  return isCurrentSynthesized ? count + 1 : count;\n}\n","import {Photo} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport ListLoader, {ListLoaderOptions} from '@helpers/listLoader';\n\nexport default class AvatarListLoader<Item extends {photoId: Photo.photo['id']}> extends ListLoader<Item, any> {\n  private peerId: PeerId;\n  private managers: AppManagers;\n  // The public (fallback) photo, shown as the LAST item (self profile only).\n  private fallbackPhotoId: Photo.photo['id'];\n  private fallbackAppended: boolean;\n\n  constructor(options: Omit<ListLoaderOptions<Item, any>, 'loadMore'> & {peerId: PeerId, managers: AppManagers, fallbackPhotoId?: Photo.photo['id']}) {\n    super({\n      ...options,\n      loadMore: (anchor, older, loadCount) => {\n        if(this.peerId.isAnyChat() || !older) return Promise.resolve({count: 0, items: []}); // ! это значит, что открыло аватар чата, но следующих фотографий нет.\n\n        const maxId = anchor?.photoId;\n        // The public (fallback) photo isn't part of the user's photo sequence and\n        // is always the LAST item — never page from it. getUserPhotos(max_id) would\n        // re-return earlier photos as duplicates, and nothing follows the fallback.\n        if(maxId !== undefined && maxId === this.fallbackPhotoId) {\n          const count = this.previous.length + (this.current ? 1 : 0) + this.next.length;\n          return Promise.resolve({count, items: []});\n        }\n\n        return this.managers.appPhotosManager.getUserPhotos(this.peerId, maxId, loadCount).then((value) => {\n          const items = value.photos\n          .filter((photoId) => photoId !== this.fallbackPhotoId)\n          .map((photoId) => {\n            return {element: null as HTMLElement, photoId} as any;\n          });\n\n          let count = value.count;\n          if(this.fallbackPhotoId) {\n            // One extra item beyond the real photos.\n            if(count !== undefined) count += 1;\n            // Append the public photo once, after the last real page.\n            if(!this.fallbackAppended && value.photos.length < loadCount) {\n              items.push({element: null as HTMLElement, photoId: this.fallbackPhotoId} as any);\n              this.fallbackAppended = true;\n            }\n          }\n\n          return {count, items};\n        });\n      }\n    });\n\n    this.loadedAllUp = true;\n    this.peerId = options.peerId;\n    this.fallbackPhotoId = options.fallbackPhotoId;\n  }\n}\n","import type {Middleware} from '@helpers/middleware';\nimport {pinObjectURL} from '@helpers/objectUrl';\n\n// Creates a muted, looping, inline <video> set up to autoplay an avatar clip.\n//\n// IMPORTANT: every autoplay-relevant property/attribute is set BEFORE assigning\n// `src`. Chrome evaluates the autoplay policy the moment the source starts\n// loading — if `muted` isn't already true at that point, autoplay is blocked\n// (the element then only plays on an explicit play()). Setting src last (and\n// retrying play() on canplay/loadeddata) makes muted autoplay reliable.\n//\n// `startTime` (seconds) is the animated profile photo's video_start_ts: official\n// clients begin playback at that frame so the moving clip continues the static\n// cover, then native-loop back to 0 (tdesktop video_userpic_player.cpp:138,\n// iOS PeerAvatarImageGalleryItem.swift:365). We seek to it once metadata is in.\nexport default function createLoopingMutedVideo(\n  url: string,\n  className?: string,\n  startTime?: number,\n  middleware?: Middleware\n) {\n  const v = document.createElement('video');\n  if(className) v.className = className;\n\n  v.muted = true;\n  v.loop = true;\n  v.playsInline = true;\n  v.preload = 'auto';\n  v.setAttribute('muted', '');\n  v.setAttribute('playsinline', '');\n  v.setAttribute('disableremoteplayback', '');\n\n  const tryPlay = () => {\n    v.play().catch(() => {});\n  };\n\n  const seekTo = startTime > 0 ? startTime : 0;\n\n  if(seekTo) {\n    // Don't autoplay from 0 — seek to video_start_ts first (once the duration is\n    // known), then play; native loop wraps subsequent passes back to 0.\n    v.addEventListener('loadedmetadata', () => {\n      try {\n        v.currentTime = Math.min(seekTo, v.duration || seekTo);\n      } catch{}\n      tryPlay();\n      // Flag it as autoplay only AFTER the seek — setting it before src (like the\n      // no-seek branch) would make the browser start at frame 0 and flash it\n      // before the cover frame. The flag itself is just a marker so a pause/resume\n      // manager (e.g. animationIntersector) knows the clip is meant to be playing.\n      v.autoplay = true;\n    }, {once: true});\n    v.addEventListener('canplay', tryPlay, {once: true}); // backstop\n  } else {\n    v.autoplay = true;\n    v.addEventListener('loadeddata', tryPlay, {once: true});\n    v.addEventListener('canplay', tryPlay, {once: true});\n  }\n\n  // * a looping video needs its blob URL alive across loops/seeks — pin it\n  // * for as long as the consumer lives\n  if(middleware) {\n    middleware.onClean(pinObjectURL(url));\n  }\n  v.src = url; // assign last so the autoplay policy sees muted=true\n  if(!seekTo) tryPlay();\n\n  return v;\n}\n","import {Photo} from '@layer';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport chooseProfileVideoSize from '@appManagers/utils/photos/chooseProfileVideoSize';\nimport createLoopingMutedVideo from '@helpers/dom/createLoopingMutedVideo';\nimport clearMediaElementSource from '@helpers/dom/clearMediaElementSource';\n\n// Overlays a looping muted video (animated avatar) on top of the media-viewer\n// mover's still image, once the photo's full video variant has downloaded.\n// Returns a cleanup that cancels the pending download and removes the video.\n// Shared by AppMediaViewer (chat/channel avatar-change photos) and\n// AppMediaViewerAvatar (peer avatars).\nexport default function overlayAvatarVideoOnMover(mover: HTMLElement, photo: Photo.photo): () => void {\n  let video: HTMLVideoElement | undefined;\n  let cancelled = false;\n\n  const videoSize = chooseProfileVideoSize(photo, 'full');\n  if(videoSize) {\n    Promise.resolve(appDownloadManager.downloadMediaURL({media: photo, thumb: videoSize})).then((url) => {\n      if(cancelled || !url || !mover.isConnected) return;\n      const container = (mover.querySelector('.media-viewer-aspecter') as HTMLElement) || mover;\n      video = createLoopingMutedVideo(\n        url,\n        'media-viewer-avatar-video',\n        videoSize.video_start_ts,\n        mover.middlewareHelper.get()\n      );\n      container.append(video);\n    });\n  }\n\n  return () => {\n    cancelled = true;\n    if(video) {\n      clearMediaElementSource(video);\n      video.remove();\n      video = undefined;\n    }\n  };\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport AvatarListLoader from '@helpers/avatarListLoader';\nimport {Photo} from '@layer';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport AppMediaViewerBase from '@components/mediaViewer/base';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport overlayAvatarVideoOnMover from '@components/mediaViewer/avatarVideo';\nimport {i18n} from '@lib/langPack';\n\ntype AppMediaViewerAvatarTargetType = {element: HTMLElement, photoId: Photo.photo['id'], photo?: Photo.photo};\nexport default class AppMediaViewerAvatar extends AppMediaViewerBase<'', 'delete', AppMediaViewerAvatarTargetType> {\n  public peerId: PeerId;\n  protected btnMenuDelete: ButtonMenuItemOptionsVerifiable;\n  private canDeletePromise: Promise<boolean>;\n  private videoAvatarCleanup?: () => void;\n  private fallbackPhotoId?: Photo.photo['id'];\n\n  constructor(peerId: PeerId, fallbackPhotoId?: Photo.photo['id']) {\n    super(new AvatarListLoader({peerId, managers: rootScope.managers, fallbackPhotoId}), ['delete']);\n\n    this.peerId = peerId;\n    this.fallbackPhotoId = fallbackPhotoId;\n\n    // The avatar viewer's date line also shows \"X of Y\" (a regular photo) or\n    // \"Public Photo\" (the fallback) before the date. The total count arrives\n    // after the first page loads, so refresh the prefix on every load too.\n    const baseOnLoadedMore = this.listLoader.onLoadedMore;\n    this.listLoader.onLoadedMore = () => {\n      baseOnLoadedMore?.();\n      this.applyDateExtra();\n    };\n\n    this.buttons.delete.classList.add('hide');\n    attachClickEvent(this.buttons.delete, this.onDeleteClick);\n\n    this.setBtnMenuToggle([{\n      icon: 'download',\n      text: 'MediaViewer.Context.Download',\n      onClick: this.onDownloadClick\n    }, this.btnMenuDelete = {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Delete',\n      onClick: this.onDeleteClick,\n      verify: () => this.getCanDelete()\n    }]);\n\n    // * constructing html end\n\n    this.setListeners();\n  }\n\n  private getCanDelete() {\n    return this.canDeletePromise ??= this.computeCanDelete();\n  }\n\n  private async computeCanDelete(): Promise<boolean> {\n    if(this.peerId === rootScope.myId) return true;\n    if(this.peerId.isAnyChat()) {\n      return this.managers.appChatsManager.hasRights(this.peerId.toChatId(), 'change_info');\n    }\n\n    // Own bot — its avatar is editable (and removable) by the owner.\n    const user = await this.managers.appUsersManager.getUser(this.peerId.toUserId());\n    return !!(user?.pFlags?.bot && user.pFlags.bot_can_edit);\n  }\n\n  onPrevClick = (target: AppMediaViewerAvatarTargetType) => {\n    this.openMedia({\n      photoId: target.photoId,\n      target: target.element,\n      fromRight: -1\n    });\n  };\n\n  onNextClick = (target: AppMediaViewerAvatarTargetType) => {\n    this.openMedia({\n      photoId: target.photoId,\n      target: target.element,\n      fromRight: 1\n    });\n  };\n\n  onDownloadClick = () => {\n    appDownloadManager.downloadToDisc({\n      media: this.target.photo,\n      queueId: appImManager.chat.bubbles.lazyLoadQueue.queueId\n    });\n  };\n\n  onDeleteClick = async() => {\n    const peerId = this.peerId;\n    const photoId = this.target.photoId;\n    try {\n      await confirmationPopup({\n        titleLangKey: 'Delete',\n        descriptionLangKey: 'AreYouSureDeletePhoto',\n        button: {\n          langKey: 'Delete',\n          isDanger: true\n        }\n      });\n    } catch{\n      return;\n    }\n\n    if(peerId === rootScope.myId) {\n      await this.managers.appProfileManager.deletePhotos([photoId as string]);\n    } else if(peerId.isUser()) { // own bot, see computeCanDelete\n      await this.managers.appProfileManager.clearBotProfilePhoto(peerId.toUserId());\n    } else {\n      await this.managers.appChatsManager.editPhoto(peerId.toChatId());\n    }\n\n    this.target = {element: this.content.media} as any;\n    this.close();\n  };\n\n  public async openMedia({\n    photoId,\n    photo: cachedPhoto,\n    target,\n    fromRight = 0,\n    prevTargets,\n    nextTargets\n  }: {\n    photoId: Photo.photo['id'],\n    photo?: Photo.photo,\n    target?: HTMLElement,\n    fromRight?: number,\n    prevTargets?: AppMediaViewerAvatarTargetType[],\n    nextTargets?: AppMediaViewerAvatarTargetType[]\n  }) {\n    if(this.setMoverPromise) return this.setMoverPromise;\n\n    const [photo, canDelete] = await Promise.all([\n      cachedPhoto || this.managers.appPhotosManager.getPhoto(photoId),\n      this.getCanDelete()\n    ]);\n\n    this.buttons.delete.classList.toggle('hide', !canDelete);\n\n    const ret = super._openMedia({\n      media: photo,\n      timestamp: photo.date,\n      fromId: this.peerId,\n      fromRight,\n      // The profile-avatars carousel lazy-loads its avatar nodes, so a node we\n      // navigate to often has no <img>/<canvas> to morph from. Passing such an\n      // empty element leaves the incoming slide blank until the animation ends\n      // (\"appears from emptiness\"). Fall back to the container in that case so\n      // the viewer's own (cached) thumbnail fills the slide.\n      target: target?.querySelector('img, canvas, video') ? target : undefined,\n      reverse: false,\n      prevTargets,\n      nextTargets\n    });\n    this.target.photoId = photo.id;\n    this.target.photo = photo;\n\n    // Animated profile photo — overlay a looping muted video on top of the\n    // static image once the open/move animation has settled.\n    this.videoAvatarCleanup?.();\n    this.videoAvatarCleanup = undefined;\n    if((photo as Photo.photo).video_sizes?.length) {\n      Promise.resolve(ret).then(() => {\n        // Bail if the viewer navigated to a different photo while opening.\n        if(this.target?.photoId !== photo.id || !this.content.mover) return;\n        this.videoAvatarCleanup = overlayAvatarVideoOnMover(this.content.mover, photo as Photo.photo);\n      });\n    }\n\n    return ret;\n  }\n\n  protected setAuthorInfo(fromId: PeerId | string, timestamp: number) {\n    return super.setAuthorInfo(fromId, timestamp).then(() => {\n      this.applyDateExtra();\n    });\n  }\n\n  // The date line reads \"<X of Y / Public Photo> • <date>\". The base sets the\n  // date text; this prepends the avatar-specific prefix + a large-dot separator.\n  private applyDateExtra() {\n    const dateEl = this.author?.date;\n    if(!dateEl) return;\n\n    // Re-applied on navigation and once the count loads — drop the old prefix.\n    dateEl.querySelector('.media-viewer-date-extra')?.remove();\n    dateEl.querySelector('.media-viewer-date-dot')?.remove();\n\n    const content = this.getDateExtraContent();\n    if(!content) return;\n\n    const extra = document.createElement('span');\n    extra.classList.add('media-viewer-date-extra');\n    extra.append(content);\n\n    const dot = document.createElement('span');\n    dot.classList.add('media-viewer-date-dot');\n\n    dateEl.prepend(extra, dot);\n  }\n\n  private getDateExtraContent(): HTMLElement | undefined {\n    const photoId = this.target?.photoId;\n\n    // The public (fallback) photo is labelled, not numbered.\n    if(this.fallbackPhotoId && photoId && photoId === this.fallbackPhotoId) {\n      return i18n('MediaViewer.ProfilePublicPhoto');\n    }\n\n    const index = this.listLoader.index; // 0-based; -1 until the count is known\n    const count = this.listLoader.count;\n    if(count !== undefined && index >= 0) {\n      // The fallback takes one slot in count but is shown as a label, so exclude\n      // it from the \"of N\" total.\n      const total = this.fallbackPhotoId ? count - 1 : count;\n      if(total > 1) return i18n('Of', [index + 1, total]);\n    }\n\n    return undefined;\n  }\n\n  public close(e?: MouseEvent) {\n    this.videoAvatarCleanup?.();\n    this.videoAvatarCleanup = undefined;\n    return super.close(e);\n  }\n}\n","import isObject from '@helpers/object/isObject';\nimport {Photo, MessageAction, Message} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport AppMediaViewer from '@components/mediaViewer';\nimport AppMediaViewerAvatar from '@components/mediaViewer/avatar';\n\ntype AvatarViewerItem = Photo.photo['id'] | Message.messageService;\n\nexport default async function openAvatarViewer(\n  target: HTMLElement,\n  peerId: PeerId,\n  middleware: () => boolean,\n  item?: AvatarViewerItem,\n  prevTargets?: {element: HTMLElement, item: AvatarViewerItem}[],\n  nextTargets?: typeof prevTargets,\n  cachedPhoto?: Photo.photo,\n  fallbackPhotoId?: Photo.photo['id']\n) {\n  let photo = cachedPhoto || await rootScope.managers.appProfileManager.getFullPhoto(peerId);\n  if(!middleware() || photo?._ !== 'photo') {\n    return;\n  }\n\n  const getTarget = () => {\n    const good = Array.from(target.querySelectorAll('img')).find((img) => !img.classList.contains('emoji'));\n    return good ? target : null;\n  };\n\n  if(peerId.isAnyChat()) {\n    const inputFilter = 'inputMessagesFilterChatPhotos';\n    let message = isObject(item) ? item as Message.messageService : undefined;\n    if(!message) {\n      message = await rootScope.managers.appMessagesManager.generateFakeAvatarMessage(peerId, photo);\n      if(!middleware()) return;\n    }\n\n    if(message) {\n      // ! гений в деле, костылируем (но это гениально)\n      const messagePhoto = (message.action as MessageAction.messageActionChannelEditPhoto).photo;\n      if(messagePhoto.id !== photo.id) {\n        message = await rootScope.managers.appMessagesManager.generateFakeAvatarMessage(peerId, photo);\n        if(!middleware()) return;\n      }\n\n      const f = (arr: typeof prevTargets) => arr.map((el) => ({\n        element: el.element,\n        mid: (el.item as Message.messageService).mid,\n        peerId: (el.item as Message.messageService).peerId\n      }));\n\n      new AppMediaViewer()\n      .setSearchContext({\n        peerId,\n        inputFilter: {_: inputFilter}\n      })\n      .openMedia({\n        message,\n        target: getTarget(),\n        prevTargets: prevTargets ? f(prevTargets) : undefined,\n        nextTargets: nextTargets ? f(nextTargets) : undefined\n      });\n\n      return;\n    }\n  }\n\n  if(photo) {\n    if(!isObject(item) && item && photo.id !== item) {\n      photo = await rootScope.managers.appPhotosManager.getPhoto(item);\n    }\n\n    const f = (arr: typeof prevTargets) => arr.map((el) => ({\n      element: el.element,\n      photoId: el.item as string\n    }));\n\n    new AppMediaViewerAvatar(peerId, fallbackPhotoId).openMedia({\n      photoId: photo.id,\n      photo,\n      target: getTarget(),\n      prevTargets: prevTargets ? f(prevTargets) : undefined,\n      nextTargets: nextTargets ? f(nextTargets) : undefined\n    });\n  }\n}\n","import {subscribeOn} from '@helpers/solid/subscribeOn';\nimport themeController from '@helpers/themeController';\nimport rootScope from '@lib/rootScope';\nimport {createSignal} from 'solid-js';\n\nexport default function useIsNightTheme() {\n  const [isNight, setIsNight] = createSignal<boolean>(themeController.isNight());\n  subscribeOn(rootScope)('theme_changed', () => {\n    setIsNight(themeController.isNight());\n  });\n  return isNight;\n}\n","import {Accessor, Signal, createEffect, createMemo, createSignal} from 'solid-js';\nimport {HelpPeerColorOption, HelpPeerColorSet, User} from '@layer';\nimport {usePeer} from '@stores/peers';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\n\nlet signal: Signal<HelpPeerColorOption[]>;\nexport default function useProfileColors() {\n  return signal ??= createSignal<HelpPeerColorOption[]>();\n}\n\nexport function usePeerProfileAppearance(peerId: PeerId): Accessor<{\n  bgColors?: number[]\n  backgroundEmojiId?: Long\n}> {\n  const [colorOptions] = useProfileColors();\n  const isNightTheme = useIsNightTheme();\n  const peer = usePeer(() => peerId);\n\n  return createMemo(() => {\n    const _peer = peer();\n\n    const emojiStatus = (_peer as User.user)?.emoji_status\n    if(emojiStatus?._ === 'emojiStatusCollectible') {\n      return {\n        bgColors: [emojiStatus.edge_color, emojiStatus.center_color],\n        backgroundEmojiId: emojiStatus.pattern_document_id\n      }\n    }\n\n    const profileColor = (_peer as User.user)?.profile_color;\n    if(profileColor?._ !== 'peerColor') {\n      return {};\n    }\n\n    const colorOption = colorOptions()?.find((colorOption) => colorOption.color_id === profileColor.color);\n    const colorSet = (isNightTheme() && colorOption?.dark_colors ? colorOption.dark_colors : colorOption?.colors) as HelpPeerColorSet.helpPeerColorProfileSet\n    return {\n      bgColors: colorSet?.bg_colors,\n      backgroundEmojiId: profileColor.background_emoji_id\n    }\n  });\n}\n","type WheelKind = 'input' | 'inertia';\n\ninterface WheelSample {\n  t: number;\n  d: number;\n  raw: WheelEvent;\n}\n\nexport default class WheelClassifier {\n  private events: WheelSample[] = [];\n  private readonly maxSamples = 12;\n  private lastType: WheelKind = 'input';\n\n  push(e: WheelEvent): WheelKind {\n    const now = performance.now();\n\n    this.events.push({\n      t: now,\n      d: Math.abs(e.deltaY),\n      raw: e\n    });\n\n    if(this.events.length > this.maxSamples) {\n      this.events.shift();\n    }\n\n    return this.classify();\n  }\n\n  private classify(): WheelKind {\n    if(this.events.length < 4) {\n      return this.lastType;\n    }\n\n    const ev = this.events;\n\n    // интервалы\n    const intervals: number[] = [];\n    for(let i = 1; i < ev.length; i++) {\n      intervals.push(ev[i].t - ev[i - 1].t);\n    }\n\n    const avgInterval = avg(intervals);\n\n    // затухание дельты\n    let decayCount = 0;\n    for(let i = 1; i < ev.length; i++) {\n      if(ev[i].d < ev[i - 1].d) decayCount++;\n    }\n\n    const decayRatio = decayCount / (ev.length - 1);\n\n    // разброс дельт\n    const deltas = ev.map(e => e.d);\n    const deltaStd = stddev(deltas);\n    const deltaAvg = avg(deltas);\n\n    const looksLikeInertia =\n      avgInterval < 40 &&\n      decayRatio > 0.6 &&\n      deltaStd < deltaAvg * 0.8;\n\n    const looksLikeInput =\n      deltaAvg > 25 &&\n      decayRatio < 0.4;\n\n    if(looksLikeInertia) this.lastType = 'inertia';\n    else if(looksLikeInput) this.lastType = 'input';\n\n    return this.lastType;\n  }\n}\n\nfunction avg(arr: number[]): number {\n  return arr.reduce((a, b) => a + b, 0) / arr.length;\n}\n\nfunction stddev(arr: number[]): number {\n  const m = avg(arr);\n  return Math.sqrt(avg(arr.map(v => (v - m) ** 2)));\n}\n","import SwipeHandler from '@components/swipeHandler';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {animateSingle, cancelAnimationByKey} from '@helpers/animation';\nimport {CancellablePromise} from '@helpers/cancellablePromise';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport WheelClassifier from '@helpers/dom/wheelClassifier';\nimport liteMode from '@helpers/liteMode';\nimport clamp from '@helpers/number/clamp';\nimport debounce from '@helpers/schedulers/debounce';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {createSignal, createMemo, onCleanup, createEffect} from 'solid-js';\n\nconst STATE_FOLDED = 1;\nconst STATE_UNFOLDED = 0;\n\nexport function useCollapsable(props: {\n  scrollable: () => HTMLElement,\n  listenWheelOn: HTMLElement,\n  container: () => HTMLElement,\n  shouldIgnore?: () => boolean,\n  skipAnimationClassName?: string,\n  disableHoverWhenFolded?: boolean\n}) {\n  const [progress, _setProgress] = createSignal(STATE_FOLDED);\n  const [isTransition, setIsTransition] = createSignal(false);\n  const folded = createMemo(() => progress() === STATE_FOLDED);\n\n  const setProgress = (progress: number, skipAnimation?: boolean) => {\n    if(liteMode.isAvailable('animations') && !skipAnimation) setIsTransition(true);\n    _setProgress(progress);\n  };\n\n  const scrollTo = (wasProgress: number, open?: boolean) => {\n    const startTime = Date.now();\n    const _animation = animation = animateSingle(() => {\n      const value = clamp((Date.now() - startTime) / 125, 0, 1);\n\n      let progress = wasProgress;\n      if((wasProgress > 0.5 || open === false) && open !== true) {\n        progress += (1 - wasProgress) * value;\n        animationOpening = false;\n      } else {\n        animationOpening = true;\n        progress -= wasProgress * value;\n      }\n\n      setProgress(progress);\n      return value < 1;\n    }, props.container()).finally(() => {\n      if(_animation === animation) {\n        animation = undefined;\n      }\n    });\n  };\n\n  const clearAnimation = () => {\n    cancelAnimationByKey(props.container());\n  };\n\n  let animation: CancellablePromise<void>, animationOpening: boolean;\n  const onScrolled = () => {\n    return;\n\n    const wasProgress = progress();\n    if(wasProgress >= 1 || wasProgress <= 0) {\n      return;\n    }\n\n    scrollTo(wasProgress);\n  };\n\n  const debounced = debounce(onScrolled, 75, false, true);\n  const classifier = new WheelClassifier();\n\n  const onMove = (delta: number, e?: WheelEvent | TouchEvent) => {\n    const scrollTop = props.scrollable().scrollTop;\n    const isWheel = !!e && 'deltaY' in e; // cross-realm-safe `instanceof WheelEvent` (Document PiP window)\n    if(isWheel || true) {\n      if(scrollTop && progress() !== STATE_FOLDED) {\n        setProgress(STATE_FOLDED);\n        debounced.clearTimeout();\n        return;\n      }\n\n      if(isWheel) {\n        const type = classifier.push(e as WheelEvent);\n        if(type === 'inertia') {\n          return;\n        }\n      }\n\n      const newState = delta < 0 ? STATE_UNFOLDED : STATE_FOLDED;\n      if((scrollTop && progress() !== STATE_UNFOLDED) || debounced.isDebounced()) {\n        debounced();\n        return;\n      }\n\n      if(progress() === newState) {\n        return;\n      }\n\n      e && cancelEvent(e);\n      setProgress(newState);\n      return;\n    }\n\n    const wasProgress = progress();\n    props.container().classList.add(props.skipAnimationClassName);\n\n    // if user starts to scroll down when it's being opened\n    if(delta > 0 && animation && animationOpening) {\n      debounced.clearTimeout();\n      scrollTo(wasProgress, false);\n      return;\n    }\n\n    if(\n      animation ||\n      (wasProgress >= STATE_FOLDED && delta > 0) ||\n      (wasProgress <= STATE_UNFOLDED && delta <= 0)/*  ||\n      (scrollTop && progress() !== STATE_UNFOLDED) */\n    ) {\n      return;\n    }\n\n    // if(animation) {\n    //   cancelEvent(e);\n    //   return;\n    // }\n\n    let value = delta / 600;\n    value = clamp(wasProgress + value, 0, 1);\n    setProgress(value);\n    if(value >= 1 || value <= 0) {\n      debounced.clearTimeout();\n      onScrolled();\n    } else {\n      e && cancelEvent(e);\n      debounced();\n    }\n  };\n\n  const onWheel = (e: WheelEvent) => {\n    if(props.shouldIgnore?.()) {\n      return;\n    }\n\n    // * `wheelDeltaY` is a non-standard WebKit/Blink property that Firefox has never had, so\n    // * `-wheelDeltaY` came back NaN there and `NaN < 0` made every wheel resolve to\n    // * STATE_FOLDED — the collapsible could never be unfolded, and a folded stories list is\n    // * `pointer-events: none`, so clicking a story did nothing. `deltaY` is the standard\n    // * equivalent and carries the same sign, which is all `onMove` reads off it.\n    onMove(e.deltaY, e);\n  };\n  subscribeOn(props.listenWheelOn)('wheel', onWheel, {passive: false});\n\n  if(IS_TOUCH_SUPPORTED) {\n    const swipeHandler = new SwipeHandler({\n      element: props.listenWheelOn,\n      onSwipe: (xDiff, yDiff, e) => {\n        const delta = -yDiff;\n        onMove(delta, e as any as TouchEvent);\n      },\n      cancelEvent: false,\n      cursor: '',\n      verifyTouchTarget: (e) => {\n        return e instanceof TouchEvent && !props.shouldIgnore?.() && !findUpClassName(e.target, 'folders-tabs-scrollable');\n      }\n    });\n\n    onCleanup(() => {\n      swipeHandler.removeListeners();\n    });\n  }\n\n  const unfold = (e?: MouseEvent) => {\n    const wasProgress = progress();\n    if(wasProgress !== STATE_UNFOLDED) {\n      // scrollTo(wasProgress, true);\n      clearAnimation();\n      setProgress(STATE_UNFOLDED);\n      e && cancelEvent(e);\n    }\n  };\n\n  const fold = () => {\n    scrollTo(progress(), false);\n  };\n\n  createEffect(() => {\n    const container = props.container();\n    if(!container) {\n      return;\n    }\n\n    container.classList.toggle('disable-hover', (props.disableHoverWhenFolded ? folded() : false) || isTransition());\n    props.skipAnimationClassName && container.classList.toggle(props.skipAnimationClassName, folded() && !isTransition());\n  });\n\n  createEffect(() => {\n    const container = props.container();\n    if(!container) {\n      return;\n    }\n\n    subscribeOn(container)('transitionstart', (e) => e.target === container && setIsTransition(true));\n    subscribeOn(container)('transitionend', (e) => e.target === container && setIsTransition(false));\n  });\n\n  return {folded, unfold, fold, progress, clearAnimation, isTransition, STATE_FOLDED, STATE_UNFOLDED};\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport type {CancellablePromise} from '@helpers/cancellablePromise';\nimport type {InputFile} from '@layer';\n\n// Tracks in-flight profile-photo uploads per peer so the big collapsible\n// profile avatar (PeerProfileAvatars) can show a cancellable progress ring and\n// lock itself collapsed while the upload runs.\n\nexport type AvatarUploadEntry = {\n  // A CancellablePromise suitable for ProgressivePreloader.attachPromise:\n  // exposes addNotifyListener({done,total}) for progress + cancel() for abort.\n  promise: CancellablePromise<any>;\n};\n\nconst [map, setMap] = createRoot(() => createSignal<Map<PeerId, AvatarUploadEntry>>(new Map()));\n\nexport const avatarUploads = map;\n\nexport function getAvatarUpload(peerId: PeerId) {\n  return map().get(peerId);\n}\n\nfunction setEntry(peerId: PeerId, entry: AvatarUploadEntry | null) {\n  setMap((prev) => {\n    const next = new Map(prev);\n    if(entry) next.set(peerId, entry);\n    else next.delete(peerId);\n    return next;\n  });\n}\n\n// Register a profile-photo upload. `file` is the JPEG (always present); `video`\n// is the optional MP4. The bigger of the two (video, if any) drives the visible\n// progress; cancelling aborts BOTH.\nexport function trackAvatarUpload(peerId: PeerId, promises: {\n  file?: CancellablePromise<InputFile>,\n  video?: CancellablePromise<InputFile>\n}) {\n  const progressSource = promises.video || promises.file;\n  if(!progressSource) return;\n\n  // Capture the ORIGINAL cancels before overriding — progressSource is one of\n  // these promises, so reading its cancel after the override would recurse.\n  const fileCancel = promises.file?.cancel?.bind(promises.file);\n  const videoCancel = promises.video?.cancel?.bind(promises.video);\n  // ProgressivePreloader.onClick calls promise.cancel() — make it abort both.\n  progressSource.cancel = () => {\n    fileCancel?.();\n    videoCancel?.();\n  };\n\n  setEntry(peerId, {promise: progressSource});\n\n  Promise.all([promises.file, promises.video].filter(Boolean))\n  .catch(() => {})\n  .finally(() => setEntry(peerId, null));\n}\n","import type {AppMessagesManager} from '@appManagers/appMessagesManager';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport filterChatPhotosMessages from '@helpers/filterChatPhotosMessages';\nimport getChatPhotosCount from '@helpers/getChatPhotosCount';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport ListLoader from '@helpers/listLoader';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {fastRaf} from '@helpers/schedulers';\nimport {Message, ChatFull, MessageAction, Photo, User, ChatPhoto, UserFull} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport {avatarNew, wrapPhotoToAvatar} from '@components/avatarNew';\nimport animationIntersector from '@components/animationIntersector';\nimport Scrollable from '@components/scrollable';\nimport SwipeHandler from '@components/swipeHandler';\nimport wrapPhoto from '@components/wrappers/photo';\nimport openAvatarViewer from '@components/mediaViewer/openAvatarViewer';\nimport Icon from '@components/icon';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {createEffect, createRoot, on} from 'solid-js';\nimport {usePeerProfileAppearance} from '@hooks/useProfileColors';\nimport {getHexColorFromTelegramColor} from '@helpers/color';\nimport wrapEmojiPattern from '@components/wrappers/emojiPattern';\nimport {useCollapsable} from '@hooks/useCollapsable';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\nimport customProperties from '@helpers/dom/customProperties';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {changeTitleEmojiColor} from '@components/peerTitle';\nimport ProgressivePreloader from '@components/preloader';\nimport {avatarUploads} from '@stores/avatarUpload';\n\nconst LOAD_NEAREST = 3;\nexport const SHOW_NO_AVATAR = true;\n\nconst getPhotoFromAvatarMessage = (message: Message.messageService) => {\n  return (message.action as MessageAction.messageActionChannelEditPhoto).photo as Photo.photo;\n};\n\nexport default class PeerProfileAvatars {\n  private static BASE_CLASS = 'profile-avatars';\n  private static SCALE = 1;\n  private static TRANSLATE_TEMPLATE = 'translate({x}, 0)';\n  public container: HTMLElement;\n  private avatars: HTMLElement;\n  private gradient: HTMLElement;\n  private gradientTop: HTMLElement;\n  public info: HTMLElement;\n  private arrowPrevious: HTMLElement;\n  private arrowNext: HTMLElement;\n  private tabs: HTMLDivElement;\n  private listLoader: ListLoader<Photo.photo['id'] | Message.messageService, Photo.photo['id'] | Message.messageService>;\n  private peerId: PeerId;\n  private threadId: number;\n  private intersectionObserver: IntersectionObserver;\n  private loadCallbacks: Map<Element, () => void>;\n  private listenerSetter: ListenerSetter;\n  private swipeHandler: SwipeHandler;\n  private middlewareHelper: MiddlewareHelper;\n  private hasBackgroundColor: boolean;\n  private emojiPatternCanvas: HTMLCanvasElement;\n  private unfold: (e?: MouseEvent) => void;\n  private fakeAvatar: ReturnType<typeof avatarNew>;\n  private hasNoPhoto: boolean;\n  private videoProgressRAF: number;\n  private fold: () => void;\n  private uploadInProgress: boolean;\n  private uploadPreloader: ProgressivePreloader;\n  private photosByElement = new WeakMap<HTMLElement, Photo.photo>();\n  // The public (fallback) photo, appended at the END of the carousel on the\n  // self profile. Resolved id + a once-guard so it's added on exactly one page.\n  private fallbackPhotoId: Photo.photo['id'];\n  private fallbackAppended: boolean;\n  public onNeedWhiteChanged: (needWhite: boolean) => void;\n\n  constructor(\n    private scrollable: Scrollable,\n    private managers: AppManagers,\n    private setCollapsedOn: HTMLElement\n  ) {\n    this.container = document.createElement('div');\n    this.container.classList.add(PeerProfileAvatars.BASE_CLASS + '-container');\n\n    this.avatars = document.createElement('div');\n    this.avatars.classList.add(PeerProfileAvatars.BASE_CLASS + '-avatars');\n\n    this.gradient = document.createElement('div');\n    this.gradient.classList.add(PeerProfileAvatars.BASE_CLASS + '-gradient');\n\n    this.gradientTop = this.gradient.cloneNode() as HTMLElement;\n    this.gradientTop.classList.add(PeerProfileAvatars.BASE_CLASS + '-gradient-top');\n\n    this.info = document.createElement('div');\n    this.info.classList.add(PeerProfileAvatars.BASE_CLASS + '-info');\n\n    this.tabs = document.createElement('div');\n    this.tabs.classList.add(PeerProfileAvatars.BASE_CLASS + '-tabs');\n\n    this.arrowPrevious = document.createElement('div');\n    this.arrowPrevious.classList.add(PeerProfileAvatars.BASE_CLASS + '-arrow');\n    this.arrowPrevious.append(Icon('avatarprevious', PeerProfileAvatars.BASE_CLASS + '-arrow-icon'));\n\n    this.middlewareHelper = getMiddleware();\n\n    this.arrowNext = document.createElement('div');\n    this.arrowNext.classList.add(PeerProfileAvatars.BASE_CLASS + '-arrow', PeerProfileAvatars.BASE_CLASS + '-arrow-next');\n    this.arrowNext.append(Icon('avatarnext', PeerProfileAvatars.BASE_CLASS + '-arrow-icon'));\n\n    this.container.append(this.avatars, this.gradient, this.gradientTop, this.tabs, this.arrowPrevious, this.arrowNext, this.info);\n\n    this.loadCallbacks = new Map();\n    this.listenerSetter = new ListenerSetter();\n\n    // An avatar video fires 'play' when it (re)starts — e.g. when the right\n    // sidebar is reopened (animationIntersector.toggleVideosUnder resumes it) or\n    // it's scrolled back into view. 'play' doesn't bubble, so capture it on the\n    // container to wake the progress loop, which self-suspends (see the tick)\n    // whenever the active video is paused so it isn't churning rAF for nothing.\n    // Scope to avatar videos — other <video>s appended into the container (pinned\n    // gifts, story previews) shouldn't wake the loop.\n    this.listenerSetter.add(this.container)('play', (e) => {\n      if((e.target as HTMLElement)?.classList?.contains('avatar-video') && !this.videoProgressRAF) {\n        this.startVideoProgressLoop();\n      }\n    }, {capture: true});\n\n    const checkScrollTop = () => {\n      if(this.scrollable.scrollPosition !== 0) {\n        this.scrollable.scrollIntoViewNew({\n          element: this.scrollable.firstElementChild as HTMLElement,\n          position: 'start'\n        });\n        return false;\n      }\n\n      return true;\n    };\n\n    const SWITCH_ZONE = 1 / 3;\n    let cancel = false;\n    let freeze = false;\n    // The info overlay (name + subtitle) is pointer-events: none, so an event\n    // can only reach one of its descendants when that descendant opted back in\n    // — i.e. it is an interactive control (emoji status, stars rating, the\n    // topic's forum button, \"show when\") and owns the click. The header must\n    // not also fold/unfold, nor run checkScrollTop below, which would yank a\n    // scrolled profile back to the top. Deriving that from the overlay beats\n    // listing the classes: the list and the CSS opt-ins drifted apart twice.\n    // The overlay ITSELF is never a target while it stays pointer-events: none\n    // — excluding it only keeps that from silently turning the whole strip\n    // click-through for the header should the rule ever be relaxed.\n    attachClickEvent(this.container, async(_e) => {\n      const {target} = _e;\n      if(target !== this.info && this.info.contains(target as Node)) {\n        return;\n      }\n\n      if(freeze) {\n        cancelEvent(_e);\n        return;\n      }\n\n      if(cancel) {\n        cancel = false;\n        return;\n      }\n\n      // While an avatar upload is running the header stays collapsed and locked;\n      // let clicks fall through to the cancel preloader instead of expanding.\n      if(this.uploadInProgress) {\n        return;\n      }\n\n      if(!checkScrollTop()) {\n        return;\n      }\n\n      if(this.hasNoPhoto) {\n        return;\n      }\n\n      if(this.isCollapsed() && this.unfold) {\n        if(findUpClassName(_e.target, 'avatar') && this.container.classList.contains('has-stories')) {\n          cancel = true;\n          simulateClickEvent(this.fakeAvatar.node);\n          return;\n        }\n\n        this.unfold(_e);\n        return;\n      }\n\n      const rect = this.container.getBoundingClientRect();\n\n      // const e = (_e as TouchEvent).touches ? (_e as TouchEvent).touches[0] : _e as MouseEvent;\n      const e = _e;\n      const x = e.pageX;\n\n      const clickX = x - rect.left;\n      if((!this.listLoader.previous.length && !this.listLoader.next.length) ||\n        (clickX > (rect.width * SWITCH_ZONE) && clickX < (rect.width - rect.width * SWITCH_ZONE))) {\n        const peerId = this.peerId;\n\n        const targets: {element: HTMLElement, item: Photo.photo['id'] | Message.messageService}[] = [];\n        this.listLoader.previous.concat(this.listLoader.current, this.listLoader.next).forEach((item, idx) => {\n          targets.push({\n            element: /* null */this.avatars.children[idx] as HTMLElement,\n            item\n          });\n        });\n\n        const prevTargets = targets.slice(0, this.listLoader.previous.length);\n        // The viewer's own loader owns the public (fallback) photo — it keeps it\n        // last and never paginates from it. Don't pass it through here, or it\n        // would be re-anchored (duplicates) / no longer last in the viewer.\n        const nextTargets = targets.slice(this.listLoader.previous.length + 1)\n        .filter((target) => target.item !== this.fallbackPhotoId);\n\n        const target = this.avatars.children[this.listLoader.previous.length] as HTMLElement;\n        const currentItem = this.listLoader.current;\n        const currentPhoto = typeof(currentItem) === 'object' ?\n          getPhotoFromAvatarMessage(currentItem) :\n          this.photosByElement.get(target);\n        freeze = true;\n        openAvatarViewer(\n          target,\n          peerId,\n          () => peerId === this.peerId,\n          currentItem,\n          prevTargets,\n          nextTargets,\n          currentPhoto,\n          this.fallbackPhotoId\n        );\n        freeze = false;\n      } else {\n        const centerX = rect.right - (rect.width / 2);\n        const toRight = x > centerX;\n\n        let distance: number;\n        if(this.listLoader.index === 0 && !toRight) distance = this.listLoader.count - 1;\n        else if(this.listLoader.index === (this.listLoader.count - 1) && toRight) distance = -(this.listLoader.count - 1);\n        else distance = toRight ? 1 : -1;\n\n        this.goWithoutTransition(distance);\n      }\n    }, {listenerSetter: this.listenerSetter});\n\n    const cancelNextClick = () => {\n      cancel = true;\n      getOverlayRoot().addEventListener(IS_TOUCH_SUPPORTED ? 'touchend' : 'click', (e) => {\n        cancel = false;\n      }, {once: true});\n    };\n\n    let width = 0, x = 0, lastDiffX = 0, /* lastIndex = 0, */ minX = 0;\n    const swipeHandler = this.swipeHandler = new SwipeHandler({\n      element: this.avatars,\n      onSwipe: (xDiff, yDiff) => {\n        xDiff *= -1;\n        yDiff *= -1;\n\n        lastDiffX = xDiff;\n        let lastX = x + xDiff * -PeerProfileAvatars.SCALE;\n        if(lastX > 0) lastX = 0;\n        else if(lastX < minX) lastX = minX;\n\n        this.avatars.style.transform = PeerProfileAvatars.TRANSLATE_TEMPLATE.replace('{x}', lastX + 'px');\n        // console.log(xDiff, yDiff);\n        return false;\n      },\n      verifyTouchTarget: (e) => {\n        if(!checkScrollTop()) {\n          cancelNextClick();\n          cancelEvent(e as any as Event);\n          return false;\n        } else if(this.isCollapsed()) {\n          return false;\n        } else if(this.container.classList.contains('is-single') || freeze) {\n          return false;\n        }\n\n        return true;\n      },\n      onFirstSwipe: () => {\n        const rect = this.avatars.getBoundingClientRect();\n        width = rect.width;\n        minX = -width * (this.tabs.childElementCount - 1);\n\n        /* lastIndex = whichChild(this.tabs.querySelector('.active'));\n        x = -width * lastIndex; */\n        x = rect.left - this.container.getBoundingClientRect().left;\n\n        this.avatars.style.transform = PeerProfileAvatars.TRANSLATE_TEMPLATE.replace('{x}', x + 'px');\n\n        this.container.classList.add('is-swiping');\n        this.avatars.classList.add('no-transition');\n        void this.avatars.offsetLeft; // reflow\n      },\n      onReset: () => {\n        const addIndex = Math.ceil(Math.abs(lastDiffX) / (width / PeerProfileAvatars.SCALE)) * (lastDiffX >= 0 ? 1 : -1);\n        cancelNextClick();\n\n        // console.log(addIndex);\n\n        this.avatars.classList.remove('no-transition');\n        fastRaf(() => {\n          this.listLoader.go(addIndex);\n          this.container.classList.remove('is-swiping');\n        });\n      }\n    });\n\n    this.intersectionObserver = new IntersectionObserver((entries) => {\n      entries.forEach((entry) => {\n        if(!entry.isIntersecting) {\n          return;\n        }\n\n        this.loadNearestToTarget(entry.target);\n      });\n    });\n\n    this.setCollapsed(true);\n\n    const o = scrollable.onAdditionalScroll;\n    scrollable.onAdditionalScroll = () => {\n      o?.();\n      fastRaf(this.updateHeaderFilled);\n    };\n\n    this.middlewareHelper.onDestroy(() => {\n      scrollable.onAdditionalScroll = o;\n    });\n\n    createRoot((dispose) => {\n      this.middlewareHelper.onDestroy(() => {\n        dispose();\n        this.unfold = undefined;\n      });\n\n      const {folded, unfold, fold} = useCollapsable({\n        container: () => this.container,\n        listenWheelOn: this.setCollapsedOn,\n        scrollable: () => scrollable.container,\n        disableHoverWhenFolded: false,\n        // Don't let wheel/swipe expand the header while an avatar upload runs.\n        shouldIgnore: () => this.uploadInProgress\n      });\n\n      this.unfold = unfold;\n      this.fold = fold;\n\n      createEffect(() => {\n        if(this.hasNoPhoto && !folded()) {\n          fold();\n          return;\n        }\n\n        this.setCollapsed(folded());\n      });\n    });\n\n    /* this.listenerSetter.add(rootScope)('avatar_update', (peerId) => {\n      if(this.peerId === peerId) {\n        const photo = appPeersManager.getPeerPhoto(peerId);\n        if(photo) {\n          const id = photo.photo_id;\n          const previous = this.listLoader.previous;\n          for(let i = 0; i < previous.length; ++i) {\n            if(previous[i] === id)\n          }\n          this.listLoader.previous.forEach((_id, idx, arr) => {});\n        }\n      }\n    }); */\n  }\n\n  public goWithoutTransition(distance: number) {\n    this.avatars.classList.add('no-transition');\n    void this.avatars.offsetLeft; // reflow\n\n    this.listLoader.go(distance);\n\n    fastRaf(() => {\n      this.avatars.classList.remove('no-transition');\n    });\n  }\n\n  public async setPeer(peerId: PeerId, threadId?: number) {\n    this.peerId = peerId;\n    this.threadId = threadId;\n    this.middlewareHelper.clean();\n\n    // A topic isn't backed by its own photo history — render the topic icon as a\n    // single, collapse-locked avatar, exactly like a chat with no avatar photo.\n    const photo = threadId ? undefined : await this.managers.appPeersManager.getPeerPhoto(peerId);\n    if(!photo && !SHOW_NO_AVATAR) {\n      return;\n    }\n\n    this.hasNoPhoto = !photo;\n\n    await this.applyAppearance();\n\n    // Topics have no photo carousel and no stories: render the topic icon as a\n    // single avatar-120 item (exactly like before) and skip the fake avatar +\n    // list loader entirely. hasNoPhoto keeps the header collapsed and locked, so\n    // the swipe/click paths that need listLoader are never reached.\n    if(threadId) {\n      this.container.classList.add('is-topic');\n      await this.processItem(undefined);\n      return;\n    }\n\n    if(this.fakeAvatar) {\n      this.fakeAvatar.node.remove();\n    }\n    this.fakeAvatar = avatarNew({\n      peerId,\n      isBig: true,\n      middleware: this.middlewareHelper.get(),\n      size: 120,\n      withStories: true,\n      onStoriesStatus: (has) => {\n        this.container.classList.toggle('has-stories', has);\n      },\n      storyColors: {\n        read: 'rgba(255, 255, 255, .3)'\n      }\n    });\n    this.fakeAvatar.node.classList.add('profile-avatars-avatar-fake');\n    await this.fakeAvatar.readyThumbPromise;\n    this.avatars.before(this.fakeAvatar.node);\n\n    // Resolve the public (fallback) photo to append at the END of the carousel.\n    // Only on the user's own profile (fallback_photo is a self concept), and\n    // only when they have avatars. getProfile is normally already cached here.\n    this.fallbackPhotoId = undefined;\n    this.fallbackAppended = false;\n    if(peerId === rootScope.myId && peerId.isUser() && !this.hasNoPhoto) {\n      const userFull = await this.managers.appProfileManager.getProfile(peerId.toUserId());\n      const fallback = (userFull as UserFull.userFull)?.fallback_photo as Photo.photo;\n      if(fallback?._ === 'photo') this.fallbackPhotoId = fallback.id;\n    }\n\n    const listLoader: PeerProfileAvatars['listLoader'] = this.listLoader = new ListLoader({\n      loadCount: 50,\n      loadMore: (anchor, older, loadCount) => {\n        if(!older) return Promise.resolve({count: undefined, items: []});\n\n        if(peerId.isUser()) {\n          const maxId: Photo.photo['id'] = anchor as any;\n          return this.managers.appPhotosManager.getUserPhotos(peerId, maxId, loadCount).then((value) => {\n            const items = value.photos.slice();\n            let count = value.count;\n            if(this.fallbackPhotoId) {\n              // The public photo is one extra item beyond the real ones.\n              if(count !== undefined) count += 1;\n              // Append it once, on the last page (a short page = the end).\n              if(!this.fallbackAppended && value.photos.length < loadCount) {\n                items.push(this.fallbackPhotoId);\n                this.fallbackAppended = true;\n              }\n            }\n\n            return {count, items};\n          });\n        } else {\n          const promises: [Promise<ChatFull> | ChatFull, ReturnType<AppMessagesManager['getHistory']>] = [] as any;\n          if(!listLoader.current) {\n            promises.push(this.managers.appProfileManager.getChatFull(peerId.toChatId()));\n          }\n\n          promises.push(this.managers.appMessagesManager.getHistory({\n            peerId,\n            offsetId: Number.MAX_SAFE_INTEGER,\n            inputFilter: {\n              _: 'inputMessagesFilterChatPhotos'\n            },\n            limit: loadCount,\n            backLimit: 0\n          }));\n\n          return Promise.all(promises).then(async(result) => {\n            const value = result.pop() as typeof result[1];\n\n            let {messages, history} = value;\n            if(!messages) {\n              messages = value.messages = history.map((mid) => apiManagerProxy.getMessageByPeer(peerId, mid));\n            }\n\n            filterChatPhotosMessages(value);\n\n            let count = value.count;\n            if(!listLoader.current) {\n              const chatFull = result[0];\n              const chatPhoto = chatFull?.chat_photo;\n              const message = findAndSplice(messages, (message) => {\n                return ((message as Message.messageService).action as MessageAction.messageActionChannelEditPhoto).photo.id === chatPhoto?.id;\n              }) as Message.messageService;\n\n              const current = listLoader.current = message || (chatPhoto && await this.managers.appMessagesManager.generateFakeAvatarMessage(this.peerId, chatPhoto));\n              count = getChatPhotosCount(value.count, messages.length, !message && !!current);\n            }\n\n            // console.log('avatars loaded:', value);\n            return {\n              count,\n              items: messages\n            };\n          });\n        }\n      },\n      processItem: this.processItem,\n      onJump: (item, older) => {\n        const id = this.listLoader.index;\n        // const nextId = Math.max(0, id);\n        const x = 100 * PeerProfileAvatars.SCALE * id;\n        this.avatars.style.transform = PeerProfileAvatars.TRANSLATE_TEMPLATE.replace('{x}', `-${x}%`);\n\n        [this.tabs, this.avatars].forEach((container) => {\n          const activeTab = container.querySelector('.active');\n          if(activeTab) activeTab.classList.remove('active');\n\n          const tab = container.children[id] as HTMLElement;\n          tab.classList.add('active');\n        });\n\n        this.loadNearestToTarget(this.avatars.children[id]);\n\n        // The active item changed — wake the (possibly self-suspended) progress\n        // loop so the newly-active video's tab fill updates even if it was\n        // already playing and so didn't fire a fresh 'play' event.\n        if(!this.videoProgressRAF) this.startVideoProgressLoop();\n      }\n    });\n\n    if(photo?._ === 'userProfilePhoto') {\n      listLoader.current = photo.photo_id;\n    }\n\n    await this.processItem(listLoader.current);\n\n    // listLoader.loaded\n    listLoader.load(true);\n\n    // Only run the per-frame tab-progress loop when the current photo is an\n    // animated (video) avatar. For static photos it has nothing to do, and a\n    // forever-running rAF needlessly churns the rendering pipeline every frame\n    // (which can visibly interfere with the avatar's load fade-in).\n    if((photo as ChatPhoto.chatPhoto)?.pFlags?.has_video) {\n      this.startVideoProgressLoop();\n    }\n    this.watchAvatarUpload();\n  }\n\n  // Watches the per-peer avatar-upload store; while an upload for THIS peer is in\n  // flight, collapse the header, lock expansion and show a cancellable progress\n  // ring centered on the avatar.\n  private watchAvatarUpload() {\n    const middleware = this.middlewareHelper.get();\n    createRoot((dispose) => {\n      middleware.onDestroy(() => {\n        dispose();\n        this.hideUploadProgress();\n      });\n\n      createEffect(() => {\n        const entry = avatarUploads().get(this.peerId);\n        if(entry) this.showUploadProgress(entry.promise);\n        else this.hideUploadProgress();\n      });\n    });\n  }\n\n  private showUploadProgress(promise: CancellablePromise<any>) {\n    if(this.uploadInProgress) return;\n    this.uploadInProgress = true;\n    this.container.classList.add('is-avatar-uploading');\n\n    // Force the header collapsed (shouldIgnore + the click guard keep it there).\n    this.fold?.();\n\n    if(!this.uploadPreloader) {\n      this.uploadPreloader = new ProgressivePreloader({\n        isUpload: true,\n        cancelable: true,\n        tryAgainOnFail: false\n      });\n    }\n\n    const target = this.fakeAvatar?.node || this.container;\n    this.uploadPreloader.attach(target, true, promise);\n  }\n\n  private hideUploadProgress() {\n    if(!this.uploadInProgress) return;\n    this.uploadInProgress = false;\n    this.container.classList.remove('is-avatar-uploading');\n    this.uploadPreloader?.detach();\n  }\n\n  // Drives the active .profile-avatars-tab fill from the playing video avatar's\n  // currentTime, reusing the stories progress-bar mechanism (--progress + a\n  // bright :before fill) while keeping the profile tab styling.\n  private startVideoProgressLoop() {\n    cancelAnimationFrame(this.videoProgressRAF);\n    // Tie the loop to this setPeer's middleware: it becomes invalid on the next\n    // setPeer (middlewareHelper.clean) or on cleanup(), so a previous profile's\n    // loop can't leak and churn the DOM while the next profile loads. Robust to\n    // transient DOM detachment (unlike an isConnected check).\n    const middleware = this.middlewareHelper.get();\n    const tick = () => {\n      if(!middleware()) {\n        this.videoProgressRAF = 0;\n        return;\n      }\n      // Suspend the loop the moment the active video stops advancing (paused\n      // because the right bar is closed / scrolled off / idle / lite-mode) —\n      // there's nothing to animate, so don't keep churning rAF every frame. The\n      // captured 'play' listener restarts it when the video resumes.\n      if(!this.updateActiveTabProgress()) {\n        this.videoProgressRAF = 0;\n        return;\n      }\n      this.videoProgressRAF = requestAnimationFrame(tick);\n    };\n    this.videoProgressRAF = requestAnimationFrame(tick);\n  }\n\n  // Returns whether the active avatar video is currently playing (so the rAF\n  // progress loop knows whether it's still worth running).\n  private updateActiveTabProgress() {\n    const activeIndex = this.listLoader?.index ?? 0;\n    const tabs = this.tabs.children;\n    const avatars = this.avatars.children;\n    let activePlaying = false;\n    for(let i = 0; i < tabs.length; ++i) {\n      const tab = tabs[i] as HTMLElement;\n      const avatar = avatars[i] as HTMLElement;\n      let video = avatar?.querySelector('video.avatar-video') as HTMLVideoElement;\n      // The first carousel item mirrors the current profile photo, which the\n      // (reliably loaded) fake/main avatar already plays — fall back to it.\n      if(!video && i === 0) {\n        video = this.fakeAvatar?.node.querySelector('video.avatar-video') as HTMLVideoElement;\n      }\n      const isPlaying = tab.classList.contains('is-playing');\n      if(i === activeIndex && video && video.duration && !video.paused) {\n        activePlaying = true;\n        // Only touch the DOM when something actually changed — re-asserting the\n        // class / style every animation frame churns the header (style recalc +\n        // paint) for nothing and can flicker the loading avatar underneath.\n        if(!isPlaying) tab.classList.add('is-playing');\n        const value = Math.min(100, (video.currentTime / video.duration) * 100).toFixed(1) + '%';\n        if(tab.style.getPropertyValue('--progress') !== value) {\n          tab.style.setProperty('--progress', value);\n        }\n      } else if(isPlaying) {\n        tab.classList.remove('is-playing');\n        tab.style.removeProperty('--progress');\n      }\n    }\n\n    return activePlaying;\n  }\n\n  private _applyAppearance() {\n    const middleware = this.middlewareHelper.get();\n    const renderBackgroundEmoji = (docId: DocId, hasBgColor: boolean) => {\n      this.emojiPatternCanvas?.remove();\n      this.emojiPatternCanvas = undefined;\n\n      if(!docId) {\n        return;\n      }\n\n      const CANVAS_WIDTH = 393;\n      const CANVAS_HEIGHT = 258;\n\n      const canvas = this.emojiPatternCanvas = document.createElement('canvas');\n      canvas.classList.add('profile-avatars-pattern');\n      const ctx = canvas.getContext('2d');\n\n      const dpr = window.devicePixelRatio;\n      canvas.width = CANVAS_WIDTH * dpr;\n      canvas.height = CANVAS_HEIGHT * dpr;\n      canvas.style.width = `${CANVAS_WIDTH}px`;\n      canvas.style.height = `${CANVAS_HEIGHT}px`;\n\n      const drawHalo = () => {\n        const centerX = canvas.width / 2;\n        const centerY = canvas.height / 2;\n\n        const radius = 140 * dpr;\n\n        const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, radius);\n        gradient.addColorStop(0, 'rgba(255, 255, 255, 0.18)');\n        gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');\n\n        ctx.fillStyle = gradient;\n\n        ctx.beginPath();\n        ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);\n        ctx.fill();\n      };\n\n      if(hasBgColor) {\n        drawHalo();\n      } else {\n        canvas.style.mixBlendMode = 'unset';\n      }\n\n      const deferred = deferredPromise<void>();\n      const MIN_SIZE = 18;\n      const MIDDLE_SIZE = 20;\n      const MAX_SIZE = 24;\n      const MIN_OPACITY = .16;\n      const MIDDLE_OPACITY = .2;\n      const promise = wrapEmojiPattern({\n        docId,\n        canvasWidth: CANVAS_WIDTH,\n        canvasHeight: CANVAS_HEIGHT,\n        emojiSize: 24,\n        middleware,\n        positions: [\n          [307, 155, MIN_SIZE, MIN_OPACITY],\n          [68, 155, MIN_SIZE, MIN_OPACITY],\n          [317, 95, MIN_SIZE, MIN_OPACITY],\n          [58, 95, MIN_SIZE, MIN_OPACITY],\n          [292, 52, MIN_SIZE, MIN_OPACITY],\n          [83, 52, MIN_SIZE, MIN_OPACITY],\n          [213, 195, MIN_SIZE, MIDDLE_OPACITY],\n          [162, 195, MIN_SIZE, MIDDLE_OPACITY],\n          [273, 204, MIN_SIZE, MIN_OPACITY],\n          [102, 204, MIN_SIZE, MIN_OPACITY],\n          [253, 163, MIDDLE_SIZE, MIDDLE_OPACITY],\n          [120, 163, MIDDLE_SIZE, MIDDLE_OPACITY],\n          [258, 75, MIN_SIZE, MIDDLE_OPACITY],\n          [117, 75, MIN_SIZE, MIDDLE_OPACITY],\n          [269, 113, MAX_SIZE, MIDDLE_OPACITY],\n          [100, 113, MAX_SIZE, MIDDLE_OPACITY],\n          [230, 44, MIDDLE_SIZE, MIDDLE_OPACITY],\n          [143, 44, MIDDLE_SIZE, MIDDLE_OPACITY],\n          [187.5, 34, MIN_SIZE, MIDDLE_OPACITY]\n        ],\n        color: customProperties.getProperty('primary-text-color'),\n        onCacheStatus: (cached) => {\n          if(cached) {\n            promise.then(deferred.resolve.bind(deferred));\n          } else {\n            deferred.resolve();\n          }\n        }\n      }).then((_canvas) => {\n        if(!middleware()) return;\n\n        ctx.drawImage(_canvas, 0, 0);\n      });\n\n      this.container.prepend(this.emojiPatternCanvas);\n\n      return deferred;\n    };\n\n    const setBackgroundColors = (bgColors: number[]) => {\n      let backgroundStr: string;\n      if(bgColors) {\n        const colors = bgColors.map((color) => getHexColorFromTelegramColor(color));\n        if(colors.length === 1) {\n          backgroundStr = colors[0];\n        } else {\n          backgroundStr = `linear-gradient(180deg, ${colors.join(', ')})`;\n        }\n      }\n      this.container.style.background = backgroundStr;\n      this.hasBackgroundColor = !!backgroundStr;\n    };\n\n    const peerProfileAppearance = usePeerProfileAppearance(this.peerId);\n    const deferred = deferredPromise<void>();\n    createEffect(() => {\n      const {bgColors, backgroundEmojiId} = peerProfileAppearance()\n      // const docId = '5301072507598550489';\n\n      setBackgroundColors(bgColors);\n      this.setCollapsed(this.isCollapsed());\n\n      const isNightTheme = useIsNightTheme();\n      createEffect(on(\n        isNightTheme,\n        () => {\n          const promise = renderBackgroundEmoji(backgroundEmojiId, !!bgColors);\n          if(promise) promise.then(deferred.resolve.bind(deferred));\n          else deferred.resolve();\n        }\n      ));\n    });\n\n    return deferred;\n  }\n\n  private applyAppearance() {\n    const middleware = this.middlewareHelper.get();\n    return createRoot((dispose) => {\n      middleware.onDestroy(dispose);\n      return this._applyAppearance();\n    });\n  }\n\n  public addTab() {\n    const tab = document.createElement('div');\n    tab.classList.add(PeerProfileAvatars.BASE_CLASS + '-tab');\n    this.tabs.append(tab);\n\n    if(this.tabs.childElementCount === 1) {\n      tab.classList.add('active');\n    }\n\n    this.container.classList.toggle('is-single', this.tabs.childElementCount <= 1);\n  }\n\n  public processItem = async(photoId: Photo.photo['id'] | Message.messageService) => {\n    const middleware = this.middlewareHelper.get();\n    const avatar = document.createElement('div');\n    avatar.classList.add(PeerProfileAvatars.BASE_CLASS + '-avatar', 'media-container', 'hide');\n\n    const isFirst = this.avatars.childElementCount === 0;\n    this.avatars.append(avatar);\n\n    let photo: Photo.photo;\n    if(photoId) {\n      photo = typeof(photoId) !== 'object' ?\n        await this.managers.appPhotosManager.getPhoto(photoId) :\n        getPhotoFromAvatarMessage(photoId);\n    }\n    if(photo) {\n      this.photosByElement.set(avatar, photo);\n    }\n\n    const isTopic = !!this.threadId;\n    const loadCallback = async() => {\n      const avatarElem = avatarNew({\n        middleware,\n        // A topic has no photo to scale up — render its icon at a fixed avatar-120\n        // (centered via the .is-topic styles), exactly like the old simple avatar.\n        size: isTopic ? 120 : 'full',\n        isDialog: false,\n        isBig: true,\n        // Show the cached small thumb first, then the big — but DON'T fade the\n        // big in. On first open photo_big isn't cached anywhere, so its fade-in\n        // animation makes the avatar's colour gradient show through (the\n        // \"blink\"). No fade => the big just swaps over the small instantly.\n        noFadeIn: true,\n        ...(isTopic && {\n          wrapOptions: {\n            customEmojiSize: makeMediaSize(120, 120),\n            middleware\n          }\n        })\n        // size: isFirst ? 120 : 'full',\n        // withStories: isFirst\n      });\n\n      if(isFirst) {\n        avatarElem.node.classList.add('profile-avatars-avatar-first');\n      }\n\n      // The first carousel item IS the peer's current avatar, which the chat\n      // list already cached (inputPeerPhotoFileLocation). Render it via the\n      // cached-avatar path so it shows INSTANTLY on open/navigation instead of\n      // flashing the solid colour placeholder while the full photo\n      // (inputPhotoFileLocation, uncached) downloads. Older photos still go\n      // through wrapPhoto.\n      if(photo && !isFirst) {\n        const boxSize = 420;\n        const photoSize = choosePhotoSize(photo, boxSize, boxSize, false);\n        await wrapPhotoToAvatar(avatarElem, photo, boxSize, photoSize);\n      } else {\n        avatarElem.render({\n          peerId: this.peerId,\n          threadId: this.threadId\n        });\n\n        await avatarElem.readyThumbPromise;\n      }\n\n      avatar.append(avatarElem.node);\n      avatar.classList.remove('hide');\n\n      return;\n      if(photo) {\n        const res = await wrapPhoto({\n          container: avatar,\n          photo,\n          size: choosePhotoSize(photo, 420, 420, false),\n          withoutPreloader: true\n        });\n\n        [res.images.thumb, res.images.full].filter(Boolean).forEach((img) => {\n          img.classList.add('avatar-photo');\n        });\n      } else {\n        const _avatar = avatarNew({\n          middleware,\n          size: 'full',\n          isBig: true,\n          peerId: this.peerId\n        });\n        await _avatar.readyThumbPromise;\n        avatar.append(_avatar.node);\n      }\n\n      avatar.classList.remove('hide');\n    };\n\n    if(this.avatars.childElementCount <= LOAD_NEAREST) {\n      await loadCallback();\n    } else {\n      this.intersectionObserver.observe(avatar);\n      this.loadCallbacks.set(avatar, loadCallback);\n    }\n\n    this.addTab();\n\n    if(this.tabs.childElementCount === 1) {\n      avatar.classList.add('active');\n    }\n\n    return photoId;\n  };\n\n  private loadNearestToTarget(target: Element) {\n    const children = Array.from(target.parentElement.children);\n    const idx = children.indexOf(target);\n    const slice = children.slice(Math.max(0, idx - LOAD_NEAREST), Math.min(children.length, idx + LOAD_NEAREST));\n\n    slice.forEach((target) => {\n      const callback = this.loadCallbacks.get(target);\n      if(callback) {\n        callback();\n        this.loadCallbacks.delete(target);\n        this.intersectionObserver.unobserve(target);\n      }\n    });\n  }\n\n  private setCollapsed(collapsed: boolean) {\n    // * go to the first avatar\n    if(!this.isCollapsed() && collapsed && this.listLoader?.index) {\n      this.goWithoutTransition(-this.listLoader.index);\n    }\n\n    this.setCollapsedOn.classList.toggle('is-collapsed', collapsed);\n    const needWhite = this.hasBackgroundColor || !collapsed;\n    if(this.setCollapsedOn.classList.contains('need-white') !== needWhite) {\n      this.setCollapsedOn.classList.toggle('need-white', needWhite);\n      this.onNeedWhiteChanged?.(needWhite);\n      changeTitleEmojiColor(this.info, needWhite ? 'white' : 'primary-color');\n    }\n    this.updateHeaderFilled();\n  }\n\n  private isCollapsed() {\n    return this.setCollapsedOn.classList.contains('is-collapsed');\n  }\n\n  updateHeaderFilled = () => {\n    this.setCollapsedOn.classList.toggle(\n      'header-filled',\n      (!this.hasBackgroundColor && this.isCollapsed() && this.scrollable.scrollPosition >= 5) ||\n        this.scrollable.scrollPosition >= 200\n    );\n  }\n\n  public cleanup() {\n    cancelAnimationFrame(this.videoProgressRAF);\n    // Release the avatar videos we registered with the intersector. While the\n    // right sidebar was closed, toggleVideosUnder may have LOCKED them, and a\n    // locked item is NOT auto-removed when it leaves the DOM (checkAnimation\n    // early-returns on locked) — so unregister + free the decoder explicitly.\n    this.container.querySelectorAll<HTMLVideoElement>('video.avatar-video').forEach((video) => {\n      animationIntersector.removeAnimationByPlayer(video);\n      video.pause();\n      video.src = '';\n      video.load();\n    });\n    this.listenerSetter.removeAll();\n    this.swipeHandler.removeListeners();\n    this.intersectionObserver?.disconnect();\n    this.middlewareHelper.destroy();\n  }\n}\n","import {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport StickersTab from '@components/emoticonsDropdown/tabs/stickers';\nimport rootScope from '@lib/rootScope';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport cloneDOMRect from '@helpers/dom/cloneDOMRect';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {createEffect, createRoot, createSignal, onCleanup} from 'solid-js';\nimport {getOverlayRoot} from '@helpers/appWindow';\n\nimport styles from '@components/emojiDropdownButton.module.scss';\n\ntype StickerClickPayload = {\n  docId: DocId,\n  target: HTMLElement\n};\n\nconst createStickersDropdown = ({\n  pivot,\n  onStickerClick,\n  onEmoticonsDropdown,\n  ...rest\n}: {\n  pivot: HTMLElement,\n  onStickerClick: (payload: StickerClickPayload) => void,\n  onEmoticonsDropdown?: (emoticonsDropdown: EmoticonsDropdown) => void\n} & Pick<ConstructorParameters<typeof EmoticonsDropdown>[0], 'customParentElement' | 'animationGroup'>) => createRoot((dispose) => {\n  const stickersTab = new StickersTab(rootScope.managers);\n\n  const emoticonsDropdown = new EmoticonsDropdown({\n    tabsToRender: [stickersTab],\n    customParentElement: getOverlayRoot,\n    getOpenPosition: () => {\n      const rect = pivot.getBoundingClientRect();\n      const cloned = cloneDOMRect(rect);\n      cloned.top = rect.bottom + 8;\n      return cloned;\n    },\n    ...rest\n  });\n\n  // Override the default media click handler from StickersTab so callers\n  // receive the picked sticker instead of it being sent through chatInput.\n  emoticonsDropdown.onMediaClick = async(e) => {\n    const target = findUpTag(e.target as HTMLElement, 'DIV');\n    if(!target) return false;\n\n    const docId = target.dataset.docId;\n    if(!docId) return false;\n\n    onStickerClick({docId, target});\n    emoticonsDropdown.toggle(false);\n    return true;\n  };\n\n  emoticonsDropdown.getElement().classList.add(styles.EmoticonsDropdown);\n  emoticonsDropdown.setTextColor('primary-text-color');\n\n  onEmoticonsDropdown?.(emoticonsDropdown);\n\n  // Open immediately when the dropdown is created.\n  emoticonsDropdown.toggle(true);\n\n  onCleanup(() => {\n    emoticonsDropdown?.hideAndDestroy();\n  });\n\n  return {emoticonsDropdown, dispose};\n});\n\nexport type UseStickersDropdownOptions = {\n  onStickerClick: (payload: StickerClickPayload) => void\n} & Pick<ConstructorParameters<typeof EmoticonsDropdown>[0], 'customParentElement' | 'animationGroup'>;\n\n/**\n * Returns a setter that opens a stickers dropdown anchored to the supplied pivot element.\n * Pass `null` (or any falsy value) to close the dropdown. The dropdown is automatically\n * disposed when the owning reactive scope is cleaned up or when the pivot changes.\n */\nexport const useStickersDropdown = ({onStickerClick, ...rest}: UseStickersDropdownOptions) => {\n  const [pivot, setPivot] = createSignal<HTMLElement | null>(null);\n\n  createEffect(() => {\n    const pivotEl = pivot();\n    if(!pivotEl) return;\n\n    const {emoticonsDropdown, dispose} = createStickersDropdown({\n      pivot: pivotEl,\n      onStickerClick,\n      ...rest\n    });\n\n    subscribeOn(emoticonsDropdown)('close', () => {\n      setPivot(null);\n    });\n\n    onCleanup(dispose);\n  });\n\n  return setPivot;\n};\n\nexport default createStickersDropdown;\n","export const GRID_CORNER_CLASSES = ['is-corner-tl', 'is-corner-tr', 'is-corner-bl', 'is-corner-br'];\n\n/**\n * Tag which corner of a `columns`-wide grid the given item occupies (`is-corner-*`), so CSS can\n * round just that corner of an active selection to match a rounded grid container. Clears any\n * previous tag first; bottom corners account for a (possibly partial) last row. Pass the active item\n * (or null/undefined to no-op). Shared by the Chat Wallpaper and Set-a-color pickers.\n */\nexport default function markGridCornerItem(grid: Element, item: Element | null | undefined, columns = 3) {\n  if(!item) return;\n  item.classList.remove(...GRID_CORNER_CLASSES);\n  const i = Array.prototype.indexOf.call(grid.children, item);\n  if(i < 0) return;\n  const lastRow = Math.floor((grid.children.length - 1) / columns);\n  const row = Math.floor(i / columns);\n  const col = i % columns;\n  if(row === 0 && col === 0) item.classList.add('is-corner-tl');\n  if(row === 0 && col === columns - 1) item.classList.add('is-corner-tr');\n  if(row === lastRow && col === 0) item.classList.add('is-corner-bl');\n  if(row === lastRow && col === columns - 1) item.classList.add('is-corner-br');\n}\n","export default function requestFile(accept?: string) {\n  const input = document.createElement('input');\n  input.type = 'file';\n  input.style.display = 'none';\n\n  if(accept) {\n    input.accept = accept;\n  }\n\n  document.body.append(input);\n\n  const promise = new Promise<File>((resolve, reject) => {\n    input.addEventListener('change', (e: any) => {\n      const file: File = e.target.files[0];\n      if(!file) {\n        reject('NO_FILE_SELECTED');\n        return;\n      }\n\n      resolve(file);\n    }, {once: true});\n  }).finally(() => {\n    input.remove();\n  });\n\n  input.click();\n\n  return promise;\n}\n","import {createEffect, createResource, createSignal, on, onCleanup, onMount, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport {averageColor, averageColorFromCanvas} from '@helpers/averageColor';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport markGridCornerItem, {GRID_CORNER_CLASSES} from '@helpers/dom/markGridCornerItem';\nimport highlightingColor from '@helpers/highlightingColor';\nimport ChatBackgroundGradientRenderer from '@components/chat/gradientRenderer';\nimport {ChatBackground as ChatBackgroundLayer} from '@components/chat/bubbles/chatBackground';\nimport {BaseTheme, Document, WallPaper, WebDocument} from '@layer';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport appDownloadManager, {AppDownloadManager} from '@lib/appDownloadManager';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport {i18n} from '@lib/langPack';\nimport {useAppSettings} from '@stores/appSettings';\nimport {unwrap} from 'solid-js/store';\nimport Section from '@components/section';\nimport Row from '@components/rowTsx';\nimport Button from '@components/buttonTsx';\nimport CheckboxFieldTsx from '@components/checkboxFieldTsx';\nimport ProgressivePreloader from '@components/preloader';\nimport {AppBackgroundColorTab} from '@components/solidJsTabs/tabs';\nimport {AppTheme, AppThemeSettings} from '@config/state';\nimport {blendWallpaperForTinted} from '@config/themePresets';\nimport themeController from '@helpers/themeController';\nimport requestFile from '@helpers/files/requestFile';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport clearMediaElementSource from '@helpers/dom/clearMediaElementSource';\nimport scaleMediaElement from '@helpers/canvas/scaleMediaElement';\nimport {MediaSize} from '@helpers/mediaSize';\nimport {getColorsFromWallPaper} from '@helpers/color';\nimport ChatBackgroundStore from '@lib/chatBackgroundStore';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {useSuperTab} from '@components/solidJsTabs/superTabProvider';\n\nconst needBlur = (wallPaper: WallPaper, respectPattern = true) => {\n  const blur = (wallPaper as WallPaper.wallPaper)?.settings?.pFlags?.blur;\n  return !!(blur && (!respectPattern || !(wallPaper as WallPaper.wallPaper).pFlags.pattern));\n};\n\nconst getWallPaperKey = (wallPaper: WallPaper) => '' + wallPaper.id;\nconst getWallPaperKeyFromTheme = (theme: AppTheme) => '' + (getWallPaperKey(themeController.getThemeSettings(theme)?.wallpaper) || '');\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Static utility surface — kept on `AppBackgroundTab` so callers reaching it\n// through `themeController.AppBackgroundTab` (set in appImManager) and direct\n// imports keep working. Nothing here depends on the tab UI.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport class AppBackgroundTab {\n  public static tempId = 0;\n\n  // Picker thumbnail = the real `<ChatBackground>` component. All compositing knobs\n  // (overlay vs mask, intensity, dark-pattern invert) live inside ChatBackground +\n  // chatBackground.module.scss. We pass a synthetic `theme.name` so the renderer\n  // picks the right style for the slot being previewed — `tinted` triggers\n  // overlay-render, `night` uses the mask path, everything else is plain blend.\n  //\n  // `size` controls the pattern-canvas dimensions inside ChatBackground. Defaults\n  // to the actual .background-item tile (72×96 in the theme-picker / wallpaper-grid),\n  // which is ~250× smaller than the default windowSize-sized canvas — same visual\n  // result via object-fit: cover, but no wasted bitmap memory.\n  //\n  // The tile DOM (sized by a padding-bottom square, independent of content) is created\n  // synchronously so the grid lays out in full at once. The `<ChatBackground>` mount — which is\n  // what downloads the wallpaper file and rasterizes the gradient/pattern/image — is the expensive\n  // part. When `lazyLoadQueue` is passed (the wallpaper grid), that mount is deferred into the\n  // queue so only tiles actually scrolled into view ever download + render; opening the tab no\n  // longer pays for ~70 downloads + rasters up front. Omitted by callers that show a handful of\n  // tiles (theme picker), which mount immediately.\n  public static addWallPaper(\n    wallPaper: WallPaper,\n    container = document.createElement('div'),\n    forBaseTheme?: BaseTheme['_'],\n    size: {width: number, height: number} = {width: 72, height: 96},\n    lazyLoadQueue?: LazyLoadQueue\n  ) {\n    const colors = getColorsFromWallPaper(wallPaper);\n    const hasFile = wallPaper._ === 'wallPaper';\n    const isPattern = hasFile && !!(wallPaper as WallPaper.wallPaper).pFlags.pattern;\n    if((hasFile && isPattern && !colors)) {\n      return;\n    }\n\n    container.classList.add('background-item');\n    container.dataset.id = '' + wallPaper.id;\n\n    const media = document.createElement('div');\n    media.classList.add('background-item-media');\n    // Skeleton: paint the tile with its own wallpaper colours synchronously (cheap CSS — no file\n    // download, no canvas) so the grid is never empty, not even mid-open-animation before the lazy\n    // build runs. The real <ChatBackground> canvas paints opaquely over this when the tile mounts.\n    // Image-only wallpapers carry no colours, so they fall back to a neutral dark fill.\n    const skeletonStops = colors ? colors.split(',') : undefined;\n    media.style.background = skeletonStops ?\n      (skeletonStops.length > 1 ? `linear-gradient(135deg, ${skeletonStops.join(', ')})` : skeletonStops[0]) :\n      '#000';\n    container.append(media);\n\n    const themeName: AppTheme['name'] =\n      forBaseTheme === 'baseThemeTinted' ? 'tinted' :\n      forBaseTheme === 'baseThemeNight' ? 'night' :\n      'day';\n    const theme = {name: themeName} as AppTheme;\n\n    const deferred = deferredPromise<void>();\n    let disposeRoot: (() => void) | undefined;\n    let disposed = false;\n    // Mounting the component is what triggers the wallpaper download + raster, so it's the unit of\n    // work we gate on visibility.\n    const mount = () => {\n      if(disposed) return deferred;\n      disposeRoot = render(() => (\n        <ChatBackgroundLayer\n          theme={theme}\n          wallPaper={wallPaper}\n          transition=\"instant\"\n          width={size.width}\n          height={size.height}\n          onReady={() => deferred.resolve()}\n        />\n      ), media);\n      return deferred;\n    };\n    const dispose = () => {\n      disposed = true;\n      disposeRoot?.();\n    };\n\n    if(lazyLoadQueue) {\n      lazyLoadQueue.push({div: container, load: () => mount()});\n    } else {\n      mount();\n    }\n\n    return {\n      container,\n      media,\n      loadPromise: deferred as Promise<void>,\n      dispose\n    };\n  }\n\n  public static setBackgroundDocument = (\n    wallPaper: WallPaper,\n    themeSettings?: AppThemeSettings\n  ) => {\n    const _tempId = ++AppBackgroundTab.tempId;\n    const middleware = () => _tempId === AppBackgroundTab.tempId;\n\n    const doc = (wallPaper as WallPaper.wallPaper).document as MyDocument;\n    const deferred = deferredPromise<void>();\n    let download: Promise<void> | ReturnType<AppDownloadManager['downloadMediaURL']>;\n    const downloadWallPaper = () => appDownloadManager.downloadMediaURL({\n      media: doc,\n      queueId: appImManager.chat.bubbles ? appImManager.chat.bubbles.lazyLoadQueue.queueId : 0\n    });\n    if(doc) {\n      download = downloadWallPaper();\n      deferred.addNotifyListener = download.addNotifyListener.bind(download);\n      deferred.cancel = download.cancel;\n    } else {\n      download = Promise.resolve();\n    }\n\n    download.then(async() => {\n      if(!middleware()) {\n        deferred.resolve();\n        return;\n      }\n\n      const hadSettings = !!themeSettings;\n      themeSettings ??= themeController.getThemeSettings(themeController.getTheme());\n      // Chat Wallpaper tab grid clicks (and uploads) land here without a pre-blended wallpaper —\n      // applyNewTheme would have already blended its argument, so it's safe to skip when the\n      // caller passed an explicit themeSettings (which it does only from applyNewTheme). For\n      // direct invocations on tinted base, run the same per-accent dark blend so wallpaper picks\n      // sit in the Dark Blue palette like cloud-theme picks do.\n      if(!hadSettings && themeController.getTheme().name === 'tinted') {\n        wallPaper = blendWallpaperForTinted(wallPaper, themeSettings.accent_color);\n      }\n      const onReady = (url?: string) => {\n        let getPixelPromise: Promise<Uint8ClampedArray>;\n        const backgroundColor = getColorsFromWallPaper(wallPaper);\n        if(url && !backgroundColor) {\n          getPixelPromise = averageColor(url);\n        } else {\n          const {canvas} = ChatBackgroundGradientRenderer.create(backgroundColor);\n          getPixelPromise = Promise.resolve(averageColorFromCanvas(canvas));\n        }\n\n        const slug = (wallPaper as WallPaper.wallPaper).slug;\n        Promise.all([\n          getPixelPromise,\n          ChatBackgroundStore.saveWallPaperToCache(slug, url)\n        ]).then(([pixel]) => {\n          if(!middleware()) {\n            deferred.resolve();\n            return;\n          }\n\n          const hsla = highlightingColor(Array.from(pixel) as any);\n\n          if(hadSettings) {\n            // applyNewTheme handed us a plain, mutable settings object (part of the themes\n            // array it persists itself right after) — mutate it in place.\n            themeSettings.wallpaper = wallPaper;\n            themeSettings.highlightingColor = hsla;\n          } else {\n            // Chat Wallpaper tab (grid click / upload): there's no pre-built settings object, so\n            // `themeSettings` is a readonly Solid store node and assigning to it is silently\n            // dropped. Persist the pick through the store setter instead — it updates the store\n            // synchronously (so the applyCurrentTheme read below resolves the new wallpaper) and\n            // saves it to state.\n            themeController.setWallpaperForCurrentTheme(wallPaper, hsla);\n          }\n\n          appImManager.applyCurrentTheme({\n            slug,\n            backgroundUrl: url,\n            broadcastEvent: true\n          }).then(deferred.resolve.bind(deferred));\n        });\n      };\n\n      if(!doc) {\n        onReady();\n        return;\n      }\n\n      const cacheContext = await rootScope.managers.thumbsStorage.getCacheContext(doc);\n      if(needBlur(wallPaper)) {\n        setTimeout(async() => {\n          try {\n            if(!middleware()) {\n              deferred.resolve();\n              return;\n            }\n\n            const currentCacheContext = await rootScope.managers.thumbsStorage.getCacheContext(doc);\n            const sourceUrl = currentCacheContext.url || await downloadWallPaper();\n            if(!middleware()) {\n              deferred.resolve();\n              return;\n            }\n\n            const url = await ChatBackgroundStore.blurWallPaperImage(sourceUrl);\n            if(!middleware()) {\n              deferred.resolve();\n              return;\n            }\n\n            onReady(url);\n          } catch(error) {\n            deferred.reject(error);\n          }\n        }, 200);\n      } else if(middleware()) {\n        onReady(cacheContext.url);\n      }\n    });\n\n    return deferred;\n  };\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Tab UI — Solid component. The buttons open immediately; the wallpaper grid is\n// revealed only after every thumbnail has loaded (built off-DOM meanwhile).\n// ─────────────────────────────────────────────────────────────────────────────\n\nconst ChatBackground = () => {\n  const [tab] = useSuperTab();\n\n  const wallPapersByElement = new Map<HTMLElement, WallPaper>();\n  const elementsByKey = new Map<string, HTMLElement>();\n  const clicked = new Set<DocId>();\n\n  const getTheme = () => themeController.getTheme();\n\n  // True once every wallpaper thumbnail has finished loading — gates the grid section's reveal.\n  const [loaded, setLoaded] = createSignal(false);\n\n  // Built off-DOM and mounted (via <Show> below) only once `loaded()` flips, so the section never\n  // appears empty or half-rendered. Reuses Shared Media → Media's grid look (3 cols, 1px gap,\n  // rounded + clipped): `.search-super-content-media-grid`.\n  const grid = document.createElement('div');\n  grid.classList.add('search-super-content-media-grid');\n\n  const getActiveThemeSettings = () => themeController.getThemeSettings(getTheme());\n  const getBlurDisabled = () => {\n    const wallPaper = getActiveThemeSettings()?.wallpaper;\n    return !wallPaper || wallPaper._ === 'wallPaperNoFile' || !!wallPaper.pFlags.pattern;\n  };\n  const blurSignal = createSignal(needBlur(getActiveThemeSettings()?.wallpaper, false));\n  const [blur, setBlur] = blurSignal;\n  const [blurDisabled, setBlurDisabled] = createSignal(getBlurDisabled());\n\n  const syncBlurControl = () => {\n    setBlur(needBlur(getActiveThemeSettings()?.wallpaper, false));\n    setBlurDisabled(getBlurDisabled());\n  };\n\n  const changeWallPaperBlur = async(wallPaper: WallPaper, blur: boolean) => {\n    (wallPaper.settings ??= {_: 'wallPaperSettings', pFlags: {}}).pFlags.blur = blur || undefined;\n    const [appSettings] = useAppSettings();\n    await rootScope.managers.appStateManager.pushToState('settings', unwrap(appSettings));\n  };\n\n  const setBackgroundDocument = async(\n    wallPaper: WallPaper,\n    themeSettings?: AppThemeSettings\n  ) => {\n    if(!blurDisabled()) {\n      await changeWallPaperBlur(wallPaper, blur());\n    }\n\n    return AppBackgroundTab.setBackgroundDocument(wallPaper, themeSettings);\n  };\n\n  const setActive = () => {\n    syncBlurControl();\n\n    const active = grid.querySelector('.active');\n    const target = elementsByKey.get(getWallPaperKeyFromTheme(getTheme()));\n    if(active === target) return;\n\n    active?.classList.remove('active', ...GRID_CORNER_CLASSES);\n    if(target) {\n      target.classList.add('active');\n      markGridCornerItem(grid, target);\n    }\n  };\n\n  // Each thumbnail mounts its own `<ChatBackground>` Solid root inside `media`.\n  // Track the dispose handles so we tear the roots down (releasing gradient/pattern\n  // renderers) when the picker tab closes.\n  const solidRoots: (() => void)[] = [];\n\n  // Downloading + rasterizing a thumbnail is the expensive part (a file fetch + a full-scale SVG\n  // raster, ~57ms). Feeding each tile's build to a LazyLoadQueue means only the thumbnails actually\n  // scrolled into view ever download + render — opening the tab no longer pays for all ~70 tiles up\n  // front, which is what made it slow regardless of how the reveal was gated.\n  const lazyLoadQueue = new LazyLoadQueue();\n\n  const addWallPaper = (wallPaper: WallPaper, append = true) => {\n    const result = AppBackgroundTab.addWallPaper(wallPaper, undefined, undefined, undefined, lazyLoadQueue);\n    if(result) {\n      const {container, media, dispose} = result;\n      container.classList.add('grid-item');\n      media.classList.add('grid-item-media');\n      solidRoots.push(dispose);\n\n      const key = getWallPaperKey(wallPaper);\n      wallPapersByElement.set(container, wallPaper);\n      elementsByKey.set(key, container);\n\n      if(getWallPaperKeyFromTheme(getTheme()) === key) {\n        container.classList.add('active');\n      }\n\n      grid[append ? 'append' : 'prepend'](container);\n    }\n\n    // Return the tile synchronously — callers (the upload flow) only need its container; the actual\n    // build runs later, lazily, when the tile is visible, so there's nothing to await here.\n    return result;\n  };\n\n  const listenerSetter = new ListenerSetter();\n  onCleanup(() => {\n    listenerSetter.removeAll();\n    solidRoots.forEach((d) => d());\n    lazyLoadQueue.clear();\n  });\n\n  const onUploadClick = () => {\n    requestFile('image/x-png,image/png,image/jpeg').then(async(file) => {\n      if(file.name.endsWith('.png')) {\n        const img = document.createElement('img');\n        const url = URL.createObjectURL(file);\n        try {\n          await renderImageFromUrlPromise(img, url, false);\n          const mimeType = 'image/jpeg';\n          const {blob} = await scaleMediaElement({media: img, size: new MediaSize(img.naturalWidth, img.naturalHeight), mimeType});\n          file = new File([blob], file.name.replace(/\\.png$/, '.jpg'), {type: mimeType});\n        } finally {\n          clearMediaElementSource(img);\n          URL.revokeObjectURL(url);\n        }\n      }\n\n      const wallPaper = await rootScope.managers.appDocsManager.prepareWallPaperUpload(file);\n      // Seed ChatBackgroundStore with the local blob URL so the picker thumbnail\n      // (which now goes through `<ChatBackground>` → ChatBackgroundStore.getBackground)\n      // resolves the in-progress upload preview without trying to hit the network.\n      const uploadDoc = (wallPaper as WallPaper.wallPaper).document as Document.document;\n      if(uploadDoc) {\n        const cacheContext = await rootScope.managers.thumbsStorage.getCacheContext(uploadDoc);\n        ChatBackgroundStore.setBackgroundUrlToCache({\n          slug: (wallPaper as WallPaper.wallPaper).slug,\n          url: cacheContext.url\n        });\n      }\n      const uploadPromise = rootScope.managers.appDocsManager.uploadWallPaper(wallPaper.id);\n      const uploadDeferred: CancellablePromise<any> = appDownloadManager.getNewDeferredForUpload(file.name, uploadPromise);\n\n      const deferred = deferredPromise<void>();\n      deferred.addNotifyListener = uploadDeferred.addNotifyListener.bind(uploadDeferred);\n      deferred.cancel = uploadDeferred.cancel;\n\n      uploadDeferred.then((wallPaper) => {\n        clicked.delete(key);\n        elementsByKey.delete(key);\n        wallPapersByElement.set(container, wallPaper);\n        const newKey = getWallPaperKey(wallPaper);\n        elementsByKey.set(newKey, container);\n\n        setBackgroundDocument(wallPaper).then(deferred.resolve.bind(deferred), deferred.reject.bind(deferred));\n      }, deferred.reject.bind(deferred));\n\n      const key = getWallPaperKey(wallPaper);\n      const releaseUploadPreview = () => {\n        ChatBackgroundStore.deleteBackgroundUrlFromCache({\n          slug: (wallPaper as WallPaper.wallPaper).slug\n        });\n      };\n      deferred.then(releaseUploadPreview, releaseUploadPreview);\n      deferred.catch(() => {\n        container.remove();\n      });\n\n      const preloader = new ProgressivePreloader({\n        isUpload: true,\n        cancelable: true,\n        tryAgainOnFail: false\n      });\n\n      const {container} = await addWallPaper(wallPaper, false);\n      clicked.add(key);\n\n      preloader.attach(container, false, deferred);\n    });\n  };\n\n  const onResetClick = () => {\n    // `theme.settings = copy(...)` was a direct write to a readonly Solid store node (dropped).\n    // resetActiveTheme() rebuilds the active theme from SETTINGS_INIT through the store setter\n    // and re-applies the background itself (applyNewTheme → setBackgroundDocument →\n    // applyCurrentTheme), so we just refresh the blur checkbox once it settles.\n    themeController.resetActiveTheme().then(() => {\n      syncBlurControl();\n    });\n  };\n\n  const onBlurChange = async(blur: boolean) => {\n    await changeWallPaperBlur(getActiveThemeSettings().wallpaper, blur);\n\n    // wait for the animation end before re-applying — matches legacy timing\n    setTimeout(() => {\n      const active = grid.querySelector('.active') as HTMLElement;\n      if(!active) return;\n\n      const wallpaper = wallPapersByElement.get(active);\n      if((wallpaper as WallPaper.wallPaper).pFlags.pattern || wallpaper._ === 'wallPaperNoFile') {\n        return;\n      }\n\n      setBackgroundDocument(wallpaper);\n    }, 100);\n  };\n\n  const onGridClick = (e: MouseEvent | TouchEvent) => {\n    const target = findUpClassName(e.target, 'grid-item') as HTMLElement;\n    if(!target) return;\n\n    const wallPaper = wallPapersByElement.get(target);\n    if(wallPaper._ === 'wallPaperNoFile') {\n      setBackgroundDocument(wallPaper);\n      return;\n    }\n\n    const key = getWallPaperKey(wallPaper);\n    if(clicked.has(key)) return;\n    clicked.add(key);\n\n    const doc = wallPaper.document as MyDocument;\n    const preloader = new ProgressivePreloader({\n      cancelable: true,\n      tryAgainOnFail: false\n    });\n\n    const load = async() => {\n      const promise = setBackgroundDocument(wallPaper);\n      const cacheContext = await rootScope.managers.thumbsStorage.getCacheContext(doc);\n      if(!cacheContext.url || needBlur(wallPaper)) {\n        preloader.attach(target, true, promise);\n      }\n    };\n\n    preloader.construct();\n\n    attachClickEvent(target, (e) => {\n      if(preloader.preloader.parentElement) {\n        preloader.onClick(e);\n        preloader.detach();\n      } else {\n        load();\n      }\n    }, {listenerSetter});\n\n    load();\n  };\n\n  // Lay out every tile's placeholder at once (tiles are sized by CSS, not content) and reveal the\n  // grid. Each tile downloads + renders its content lazily as it scrolls into view (the LazyLoadQueue\n  // above), so this never waits on ~70 downloads + rasters — only on having the wallpaper list.\n  const buildGrid = (wallPapers: WallPaper[]) => {\n    wallPapers.forEach((wallPaper) => addWallPaper(wallPaper));\n    // Tiles exist now; resolve the initially-active item's corner rounding.\n    markGridCornerItem(grid, grid.querySelector('.active'));\n    setLoaded(true);\n  };\n\n  // Build synchronously from the cached list (warmed by the General Settings preload, or a prior\n  // open) so the grid + its skeleton tiles are present in the very first frame of the tab-open\n  // slide, instead of popping in when the async getWallPapers resolves (around when the slide ends).\n  if(ChatBackgroundStore.cachedWallPapers) {\n    buildGrid(ChatBackgroundStore.cachedWallPapers);\n  }\n\n  // Always refresh from the server: keep the cache warm for the next open, and build now if the\n  // cache wasn't there yet (first-ever open, before any preload). The list is stable within a\n  // session, so when we already built from cache we keep that grid rather than rebuilding.\n  const [wallPapersResource] = createResource(() => rootScope.managers.appThemesManager.getWallPapers());\n\n  createEffect(on(wallPapersResource, (wallPapers) => {\n    if(!wallPapers) return;\n    ChatBackgroundStore.cachedWallPapers = wallPapers;\n    if(!loaded()) {\n      buildGrid(wallPapers);\n    }\n  }));\n\n  onMount(() => {\n    attachClickEvent(grid, onGridClick, {listenerSetter});\n    tab.container.classList.add('background-container', 'background-image-container');\n  });\n\n  subscribeOn(rootScope)('background_change', setActive);\n\n  return (\n    <>\n      <Section>\n        <Button\n          class=\"btn-primary btn-transparent\"\n          icon=\"cameraadd\"\n          text=\"ChatBackground.UploadWallpaper\"\n          onClick={onUploadClick}\n        />\n        <Button\n          class=\"btn-primary btn-transparent\"\n          icon=\"colorize\"\n          text=\"SetColor\"\n          onClick={() => tab.slider.createTab(AppBackgroundColorTab).open()}\n        />\n        <Button\n          class=\"btn-primary btn-transparent\"\n          icon=\"favourites\"\n          text=\"Appearance.Reset\"\n          onClick={onResetClick}\n        />\n        <Row disabled={blurDisabled()}>\n          <Row.CheckboxFieldToggle>\n            <CheckboxFieldTsx\n              disabled={blurDisabled()}\n              name=\"blur\"\n              signal={blurSignal}\n              toggle\n              onChange={onBlurChange}\n            />\n          </Row.CheckboxFieldToggle>\n          <Row.Title>{i18n('ChatBackground.Blur')}</Row.Title>\n        </Row>\n      </Section>\n      <Show when={loaded()}>\n        <div>\n          {grid}\n        </div>\n      </Show>\n    </>\n  );\n};\n\nexport default ChatBackground;\n","import {createEffect, createResource, on, onCleanup, Ref} from 'solid-js';\nimport {ScrollableX} from '@components/scrollable';\nimport {AppBackgroundTab} from '@components/sidebarLeft/tabs/background';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport {DEFAULT_THEME} from '@config/state';\nimport {blendWallpaperForTinted} from '@config/themePresets';\nimport {BaseTheme, Theme} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport themeController from '@helpers/themeController';\nimport liteMode from '@helpers/liteMode';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport wrapStickerEmoji from '@components/wrappers/stickerEmoji';\n\ntype ThemeItem = {\n  container: HTMLElement;\n  theme: Theme;\n  player?: LottiePlayer;\n  wallPaperContainers: {[key in BaseTheme['_']]?: HTMLElement};\n};\n\nconst AVAILABLE_BASE_THEMES: Set<BaseTheme['_']> = new Set([\n  'baseThemeClassic',\n  'baseThemeNight',\n  'baseThemeDay',\n  'baseThemeTinted'\n]);\n\n// Inverse of themeController's `themeNameToBaseTheme`. The virtual theme below\n// pins its `name` so that applyTheme's internal `getThemeSettings` —\n// which re-derives the base via `getBaseThemeForName(name)` — lands back on the\n// single entry we hand it. Pinning a bare 'day'/'night' only works for the\n// classic/night bases (the popup's only two), because getBaseThemeForName('day')\n// is 'baseThemeClassic' and ('night') is 'baseThemeNight'. For Day/Light/Tinted\n// bases (which General Settings uses) that lookup misses the entry and applyTheme\n// throws reading `accent_color` off undefined — so map base → its own name.\nconst BASE_THEME_TO_THEME_NAME: {[k in BaseTheme['_']]?: string} = {\n  baseThemeClassic: 'day',\n  baseThemeNight: 'night',\n  baseThemeDay: 'light',\n  baseThemeTinted: 'tinted'\n};\n\nexport type ChatThemesPickerProps = {\n  /** Reactive theme.id of the currently selected theme. Empty string = DEFAULT_THEME. */\n  selectedId: () => string;\n  /** Called when the user picks a tile. */\n  onSelect: (theme: Theme) => void;\n  /**\n   * Reactive base theme for wallpaper rendering. Defaults to the live base from\n   * `themeController`. Override when the picker needs to show a different\n   * brightness than the global app theme (e.g. the My QR popup, where the user\n   * can toggle local night-mode independently of the chat).\n   */\n  baseTheme?: () => BaseTheme['_'];\n  /**\n   * When true, the active tile is scrolled to centre after a base-theme change\n   * (day/night/tinted switch). Opt-in for General Settings (which restores the\n   * legacy auto-centre behaviour); the My QR popup leaves it off so a tile pick\n   * isn't fought by a competing scroll.\n   */\n  recenterOnBaseChange?: boolean;\n  class?: string;\n  ref?: Ref<HTMLDivElement>;\n};\n\n/**\n * Horizontal-scrollable strip of cloud chat themes (emoji-on-wallpaper tiles).\n *\n * Lifted out of `generalSettings.tsx`'s `ThemeSection` so the My QR popup can\n * share the exact same tiles without dragging in `themeController.applyNewTheme`\n * side effects. The component is pure-UI: selection state is owned externally\n * via `selectedId` + `onSelect`; clicking a tile only animates and emits — it's\n * up to the caller to apply the theme globally if that's what they want.\n *\n * Mirrors the legacy picker's behaviour:\n *  - First tile is `DEFAULT_THEME` (the \"no custom theme\" sentinel, id === '').\n *  - Each cloud theme renders its wallpaper for the active base + its emoticon\n *    as a Lottie sticker that scales-pulse-restores on click.\n *  - Wallpaper variants are pre-blended for `baseThemeTinted` on non-curated\n *    themes, matching `themeController.applyNewTheme`'s preview path.\n */\nexport default function ChatThemesPicker(props: ChatThemesPickerProps) {\n  const middleware = createMiddleware().get();\n\n  const themesMap = new Map<HTMLElement, ThemeItem>();\n  const solidRoots: (() => void)[] = [];\n  let lastOnFrameNo: ((frameNo: number) => void) | undefined;\n\n  const getBaseTheme = (): BaseTheme['_'] =>\n    props.baseTheme?.() ?? themeController.getBaseThemeForName(themeController.getTheme().name);\n\n  // Picks the wallpaper container for the currently-active base theme, with a\n  // night fallback so themes that ship only Classic/Night look right when shown\n  // on Tinted as well. Also re-scopes the tile's CSS variables to *its own*\n  // theme so the .theme-bubble pill paints in the theme's accent colour\n  // (purple / green / blue / pink) instead of the globally-applied accent —\n  // without this, every tile reads the global `--primary-color` and ends up\n  // looking the same.\n  //\n  // We don't pass any \"isNight override\" to `applyTheme` — modifying the\n  // controller's signature would risk breaking the global theme-switch View\n  // Transition. Instead we build a *virtual* theme: clone item.theme, pin its\n  // `name` to the theme-name that maps back to the active base (see\n  // BASE_THEME_TO_THEME_NAME — so applyTheme's internal `getThemeSettings` /\n  // `isNightThemeName` / `baseColors` lookups all land on the picker-local\n  // base), and trim `settings[]` to the single entry for that base. applyTheme\n  // then resolves back to that entry through its normal path and applies base\n  // colors reflecting the picker's local brightness, not the global theme.\n  const applyThemeOnItem = (item: ThemeItem) => {\n    const base = getBaseTheme();\n    const isNight = base === 'baseThemeNight' || base === 'baseThemeTinted';\n    const entry = item.theme.settings?.find((s) => s.base_theme._ === base) ??\n      item.theme.settings?.find((s) => s.base_theme._ === (isNight ? 'baseThemeNight' : 'baseThemeClassic')) ??\n      item.theme.settings?.[0];\n    // Pin the name to the one matching the entry's ACTUAL base (it may differ\n    // from the requested `base` when we fell back above), so applyTheme resolves\n    // back to this entry. See BASE_THEME_TO_THEME_NAME.\n    const effectiveBase = entry?.base_theme._ ?? base;\n    const virtualTheme = {\n      ...item.theme,\n      name: BASE_THEME_TO_THEME_NAME[effectiveBase] ?? (isNight ? 'night' : 'day'),\n      settings: entry ? [entry] : item.theme.settings\n    } as unknown as Theme;\n    themeController.applyTheme(virtualTheme, item.container);\n\n    const previous = item.container.querySelector('.background-item');\n    previous?.remove();\n\n    const wallPaperContainer = item.wallPaperContainers[base] ??\n      item.wallPaperContainers[isNight ? 'baseThemeNight' : 'baseThemeClassic'];\n    if(wallPaperContainer) {\n      item.container.prepend(wallPaperContainer);\n    }\n  };\n\n  const scrollable = new ScrollableX(null);\n  scrollable.container.classList.add('themes-container');\n  // Start hidden so the tiles don't pop in for one frame after the async\n  // `getThemes()` resolves. We flip opacity to 1 once `buildThemes` has\n  // finished mounting the containers, letting the CSS transition fade them in.\n  scrollable.container.style.opacity = '0';\n  scrollable.container.style.transition = 'opacity .2s ease';\n\n  const [themesPromise] = createResource(() => rootScope.managers.appThemesManager.getThemes());\n\n  const buildThemes = async() => {\n    const themes = themesPromise();\n    if(!themes) return;\n\n    const defaultThemes = themes.filter((theme) => theme.pFlags.default);\n    defaultThemes.unshift(DEFAULT_THEME);\n\n    const containers = await Promise.all(defaultThemes.map(async(theme) => {\n      const container = document.createElement('div');\n      const k: ThemeItem = {container, theme, wallPaperContainers: {}};\n\n      // Cloud themes (numeric id) get their tinted wallpaper navy-blended;\n      // DEFAULT_THEME (id='') and accent presets keep their curated gradients.\n      const themeId = String(theme.id ?? '');\n      const isCurated = themeId === '' || themeId.startsWith('preset:');\n\n      const results = theme.settings\n      .filter((themeSettings) => AVAILABLE_BASE_THEMES.has(themeSettings.base_theme._))\n      .map((themeSettings) => {\n        const shouldBlend = themeSettings.base_theme._ === 'baseThemeTinted' && !isCurated && themeSettings.wallpaper;\n        const wp = shouldBlend ? blendWallpaperForTinted(themeSettings.wallpaper, themeSettings.accent_color) : themeSettings.wallpaper;\n        const result = AppBackgroundTab.addWallPaper(wp, undefined, themeSettings.base_theme._);\n        // addWallPaper returns undefined for a pattern wallpaper with no colors —\n        // skip rather than deref (matches the tinted-fallback guard below).\n        if(!result) return undefined;\n        k.wallPaperContainers[themeSettings.base_theme._] = result.container;\n        solidRoots.push(result.dispose);\n        return result;\n      })\n      .filter(Boolean);\n\n      // Synthesize a tinted preview from the night entry when the theme ships\n      // only Classic/Night, matching applyNewTheme's blend-on-fallback.\n      if(!k.wallPaperContainers['baseThemeTinted'] && !isCurated) {\n        const nightEntry = theme.settings.find((s) => s.base_theme._ === 'baseThemeNight');\n        if(nightEntry?.wallpaper) {\n          const blendedWp = blendWallpaperForTinted(nightEntry.wallpaper, nightEntry.accent_color);\n          const result = AppBackgroundTab.addWallPaper(blendedWp, undefined, 'baseThemeTinted');\n          if(result) {\n            k.wallPaperContainers['baseThemeTinted'] = result.container;\n            solidRoots.push(result.dispose);\n            results.push(result);\n          }\n        }\n      }\n\n      themesMap.set(container, k);\n      applyThemeOnItem(k);\n\n      if(String(theme.id ?? '') === props.selectedId()) {\n        container.classList.add('active');\n      }\n\n      const loadPromises: Promise<any>[] = [];\n      let emoticonContainer: HTMLElement;\n      if(theme.emoticon) {\n        emoticonContainer = document.createElement('div');\n        emoticonContainer.classList.add('theme-emoticon');\n        const size = 28 * 1.75;\n        wrapStickerEmoji({\n          div: emoticonContainer,\n          width: size,\n          height: size,\n          emoji: theme.emoticon,\n          managers: rootScope.managers,\n          loadPromises,\n          middleware,\n          play: false,\n          group: 'none'\n        }).then(({render}) => render).then((player) => {\n          k.player = player as LottiePlayer;\n        });\n      }\n\n      const bubble = document.createElement('div');\n      bubble.classList.add('theme-bubble');\n      const bubbleIn = bubble.cloneNode() as HTMLElement;\n      bubbleIn.classList.add('is-in');\n      bubble.classList.add('is-out');\n\n      loadPromises.push(...results.map((result) => result.loadPromise));\n      container.classList.add('theme-container');\n\n      await Promise.all(loadPromises);\n\n      if(emoticonContainer) container.append(emoticonContainer);\n      container.append(bubbleIn, bubble);\n\n      return container;\n    }));\n\n    if(!middleware()) return;\n    scrollable.append(...containers);\n    // Reveal in the next frame so the appended DOM has settled (layout +\n    // background-item paints are flushed) before the opacity transition runs.\n    requestAnimationFrame(() => {\n      scrollable.container.style.opacity = '1';\n    });\n  };\n\n  createEffect(on(themesPromise, (themes) => {\n    if(themes) {\n      buildThemes();\n    }\n  }));\n\n  // Reactively re-stripe `.active` when the external selectedId changes.\n  createEffect(() => {\n    const id = props.selectedId();\n    const lastActive = scrollable.container.querySelector('.active');\n    lastActive?.classList.remove('active');\n    themesMap.forEach((item) => {\n      if(String(item.theme.id ?? '') === id) {\n        item.container.classList.add('active');\n      }\n    });\n  });\n\n  // Reactively re-paint thumbnails when the base theme changes (e.g. user\n  // toggles night-mode inside the popup without touching the global theme).\n  createEffect(on(\n    () => props.baseTheme?.(),\n    () => {\n      themesMap.forEach((item) => applyThemeOnItem(item));\n      // Restore the legacy \"scroll active tile to centre on variant change\"\n      // (General Settings only — see recenterOnBaseChange).\n      if(props.recenterOnBaseChange) {\n        const active = scrollable.container.querySelector('.active') as HTMLElement | null;\n        if(active) scrollable.scrollIntoViewNew({element: active, position: 'center', axis: 'x'});\n      }\n    },\n    {defer: true}\n  ));\n\n  const listenerSetter = new ListenerSetter();\n  attachClickEvent(scrollable.container, async(e) => {\n    const container = findUpClassName(e.target, 'theme-container');\n    if(!container) return;\n\n    const item = themesMap.get(container);\n    if(!item) return;\n\n    props.onSelect(item.theme);\n    lastOnFrameNo?.(-1);\n\n    if(!item.player || !liteMode.isAvailable('animations')) return;\n\n    if(IS_SAFARI) {\n      if(item.player.paused) item.player.restart();\n      return;\n    }\n\n    if(item.player.paused) item.player.stop(true);\n    item.player.el[0].style.transform = 'scale(2)';\n\n    const onFrameNo = lastOnFrameNo = (frameNo) => {\n      if(item.player.maxFrame === frameNo || frameNo === -1) {\n        item.player.el[0].style.transform = '';\n        item.player.removeEventListener('enterFrame', onFrameNo);\n        if(lastOnFrameNo === onFrameNo) lastOnFrameNo = undefined;\n      }\n    };\n\n    setTimeout(() => {\n      if(lastOnFrameNo !== onFrameNo) return;\n      item.player.play();\n      item.player.addEventListener('enterFrame', onFrameNo);\n    }, 250);\n  }, {listenerSetter});\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n    solidRoots.forEach((d) => d());\n  });\n\n  return (\n    <div\n      class={props.class}\n      ref={(el) => {\n        el.append(scrollable.container);\n        const ref = props.ref;\n        if(typeof ref === 'function') (ref as (el: HTMLDivElement) => void)(el);\n      }}\n    />\n  );\n}\n","import {\n  createMemo,\n  createEffect,\n  createResource,\n  createSignal,\n  onCleanup,\n  onMount,\n  on\n} from 'solid-js';\nimport PopupElement, {createPopup} from '@components/popups/indexTsx';\nimport {AvatarNewTsx} from '@components/avatarNew';\nimport {ChatBackground as ChatBackgroundLayer} from '@components/chat/bubbles/chatBackground';\nimport Section from '@components/section';\nimport {IconTsx} from '@components/iconTsx';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport themeController from '@helpers/themeController';\nimport {paintQrCode, buildTelegramUserQrUrl} from '@helpers/qrCode/paintQrCode';\nimport {getWallPaperColors, darkenToMaxLuminance} from '@helpers/color';\nimport roundRect from '@helpers/canvas/roundRect';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport {toastNew} from '@components/toast';\nimport {copyTextToClipboard, writeClipboardItem} from '@helpers/clipboard';\nimport classNames from '@helpers/string/classNames';\nimport {BaseTheme, Chat, Theme, User, WallPaper} from '@layer';\nimport {AppTheme, DEFAULT_THEME} from '@config/state';\nimport {useAppSettings} from '@stores/appSettings';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport ChatThemesPicker from '@components/chatThemesPicker';\n\nimport styles from './myQrCode.module.scss';\nimport {FontFamily, FontWeightBold} from '@config/font';\nimport Button from '@components/buttonTsx';\n\n// Geometry numbers are lifted from Telegram-iOS' ChatQrCodeScreen.swift so the\n// card layout matches the iOS sheet 1:1. Source lines are noted next to each\n// constant below.\nconst QR_SIZE = 220;        // ChatQrCodeScreen.swift L1970: `imageSide = 220.0`\nconst AVATAR_SIZE = 100;    // ChatQrCodeScreen.swift L1968: `avatarSize = 100`\n\n/**\n * Looks up the (wallpaper, accent_color) pair from a Theme for the popup-local\n * night mode. Cloud themes ship one ThemeSettings per `BaseTheme`; we pick the\n * entry that matches the popup's brightness toggle, falling back to the first\n * available. The accent color is what the username text and the QR logo\n * follow, so the picked theme owns its own brand colour end-to-end.\n */\nfunction pickThemeSettingsForBase(theme: Theme, base: BaseTheme['_']) {\n  if(!theme.settings?.length) return undefined;\n  const exact = theme.settings.find((s) => s.base_theme?._ === base);\n  return exact ?? theme.settings[0];\n}\n\n// ── QR / username ink darkening ──────────────────────────────────────────────\n// The QR modules and the @username are painted in the wallpaper gradient on an\n// always-white card. Telegram-iOS dims that gradient by a flat 30%/50% black\n// (ChatQrCodeScreen.swift L1936), but several cloud *day* wallpapers ship a\n// pure-WHITE gradient stop — even at 50% that's only ~3.95:1 against white,\n// below what QR scanners reliably accept (and a near-white @username is\n// unreadable). So instead of a flat dim we clamp each stop's relative luminance:\n// already-dark (saturated / night) stops stay vibrant and untouched, while\n// too-light stops are scaled toward black until the ink clears ≥~4.5:1 contrast.\n// Without this the QR does not scan on light themes.\nconst QR_INK_MAX_LUMINANCE = 0.18; // ⇒ ≥ ~4.5:1 contrast on a white card\n\n// Clamp the wallpaper stops toward black until each clears QR_INK_MAX_LUMINANCE,\n// so the wallpaper-gradient ink always scans / reads on the white card. The\n// generic luminance-clamp lives in @helpers/color; the threshold is the local\n// QR-on-white-card policy documented above.\nfunction darkenInkStops(stops: string[]): string[] {\n  return stops.map((s) => darkenToMaxLuminance(s, QR_INK_MAX_LUMINANCE));\n}\n\n/**\n * Shared signals/memos used by every part of the popup. Created once in\n * `showMyQrCodePopup` and passed by reference into each slot — keeps the\n * brightness toggle, picker selection, QR-painter inputs and the copy\n * pipeline reading off the same source of truth without a wrapper component\n * tying them together.\n */\ntype QrPopupShared = ReturnType<typeof createSharedState>;\n\nfunction createSharedState(self: User.user, peerId: PeerId = rootScope.myId, overrideUrl?: string) {\n  const [appSettings, setAppSettings] = useAppSettings();\n  const username = createMemo(() => getPeerActiveUsernames(self)[0]);\n  // iOS shows a temporary `t.me/contact/<token>` for your OWN QR when you have no\n  // username AND phone-discovery (AddedByPhone) is disabled — so the t.me/+phone\n  // codeLink below wouldn't let a stranger add you (PeerInfoScreen.swift L4582-4585).\n  // Fetch it lazily; until it resolves (or when not applicable) the codeLink is\n  // shown — same order as iOS' setContactToken update. Only fetched for self with\n  // no username (the source returns undefined → no request otherwise).\n  const [contactTokenUrl] = createResource(\n    () => (peerId === rootScope.myId && !username()) || undefined,\n    async() => {\n      try {\n        const rules = await rootScope.managers.appPrivacyManager.getPrivacy('inputPrivacyKeyAddedByPhone');\n        if(rules.some((rule) => rule._ === 'privacyValueAllowAll')) return undefined; // phone-discovery on → t.me/+phone is enough\n        const token = await rootScope.managers.appUsersManager.exportContactToken();\n        return token?.url;\n      } catch{\n        return undefined; // any failure → fall back to the codeLink, never break profileUrl\n      }\n    }\n  );\n\n  // `overrideUrl` is for peers whose link isn't a public username — e.g. a private\n  // group's invite link, which PeerProfile.Link already resolved. Otherwise mirror\n  // Telegram-iOS' QR codeLink (ChatQrCodeScreen.swift L1740-1748): username →\n  // t.me/<username>; a user without one → t.me/+<phone>; a channel → t.me/c/<id>.\n  const profileUrl = createMemo(() => {\n    if(overrideUrl) return overrideUrl;\n    const tokenUrl = contactTokenUrl();\n    if(tokenUrl) return tokenUrl;\n    if(username()) return buildTelegramUserQrUrl(username());\n    if(peerId.isUser()) return `https://t.me/+${(self as User.user).phone ?? ''}`;\n    return `https://t.me/c/${peerId.toChatId()}`;\n  });\n\n  // The fallback brightness must stay reactive to a GLOBAL theme change while the\n  // popup is open (auto-night by schedule/system, another surface switching\n  // theme). `themeController.isNight()` is a plain method, not a signal, so mirror\n  // it into one off `theme_changed`.\n  const [globalNight, setGlobalNight] = createSignal(themeController.isNight());\n  subscribeOn(rootScope)('theme_changed', () => setGlobalNight(themeController.isNight()));\n\n  // `appSettings.qrCode` is the persisted (across reloads and across accounts\n  // via MTProto state sync) source of truth. `nightMode` falls back to the\n  // global theme's brightness when never explicitly set so the very first open\n  // matches what the user sees in chat. `selectedThemeId === ''` is the\n  // DEFAULT_THEME sentinel — \"use the current chat theme's wallpaper\".\n  const nightMode = (): boolean => appSettings.qrCode?.nightMode ?? globalNight();\n  const selectedThemeId = (): string => appSettings.qrCode?.selectedThemeId ?? '';\n\n  const setNightMode = (v: boolean) => setAppSettings('qrCode', 'nightMode', v);\n  const setSelectedThemeId = (v: string) => setAppSettings('qrCode', 'selectedThemeId', v);\n\n  // Mirror of the cloud-themes list so the popup can resolve the active theme's\n  // wallpaper without re-fetching what the picker already loaded.\n  const [allThemes] = createResource(() => rootScope.managers.appThemesManager.getThemes());\n\n  // Base theme drives both the popup background and the picker thumbnails;\n  // honors the popup-local night-mode toggle (without touching the global theme).\n  const baseTheme = (): BaseTheme['_'] => nightMode() ? 'baseThemeNight' : 'baseThemeClassic';\n\n  // (theme, wallPaper, accentColor) tuple. The wallpaper drives the\n  // ChatBackground layer; the accent color drives the username text + QR\n  // logo, so picking a tile recolors them in lockstep. Empty selection →\n  // DEFAULT_THEME's day/night variant per the popup-local toggle; otherwise\n  // look up by theme.id and pick the matching base variant.\n  const activeWallPaper = createMemo<{\n    theme: AppTheme | Theme,\n    wallPaper?: WallPaper,\n    /** Wallpaper gradient stops — drives the username CSS background-clip text. */\n    wallpaperStops: string[]\n  }>(() => {\n    const id = selectedThemeId();\n    const base = baseTheme();\n    const resolve = (theme: Theme) => {\n      const s = pickThemeSettingsForBase(theme, base);\n      return {\n        theme,\n        wallPaper: s?.wallpaper,\n        wallpaperStops: getWallPaperColors(s?.wallpaper)\n      };\n    };\n    if(!id) return resolve(DEFAULT_THEME);\n    const themes = allThemes() ?? [];\n    const found = themes.find((t) => String(t.id ?? '') === id);\n    return resolve(found ?? DEFAULT_THEME);\n  });\n\n  // qr-code-styling is lazy-loaded so the popup paints instantly and the QR\n  // appears once the ~25KB library has finished loading.\n  const [QRCodeStylingCtor] = createResource(() =>\n    import('qr-code-styling' as any).then((m) => m.default)\n  );\n\n  return {\n    self,\n    peerId,\n    username,\n    profileUrl,\n    nightMode,\n    setNightMode,\n    selectedThemeId,\n    setSelectedThemeId,\n    baseTheme,\n    activeWallPaper,\n    QRCodeStylingCtor\n  };\n}\n\n// ────────────────────────────────────────────────────────────────────────────\n// TopSection — single canvas hosting wallpaper, card, avatar, QR and username.\n//\n// Live `<ChatBackgroundLayer>` + `<AvatarNewTsx>` are mounted in a 0-size\n// off-screen host so they keep rendering their canvases / loading the photo,\n// and we sample them when repainting our visible canvas. Everything else is\n// Canvas2D primitives — rounded rect for the card, arc for the avatar ring,\n// `paintQrCode` for the QR (then mask through the wallpaper), `createLinear­\n// Gradient` + `fillText` for the username. Copy becomes `canvas.toBlob()`.\n// ────────────────────────────────────────────────────────────────────────────\n\n// Geometry calibrated against Telegram-iOS' ChatQrCodeScreen.swift. iOS uses\n// pt; we use px at 1:1 since both clients run on roughly the same logical\n// canvas (iOS sheet 390pt × 844pt, tweb popup 376px wide).\n//   • card  — 300×330pt rounded rectangle, 42pt corner radius (L2001-2003, L1634)\n//   • avatar — 100pt diameter; 70% overhang above the card top edge (L1968, L2038)\n//   • QR    — 220×220pt black ink on white (L1970, L1754)\n//   • username — SF Pro Rounded Bold ~22-24pt black (L1679, L1683)\n// iOS leaves the card UNshadowed and ALWAYS white, regardless of the global\n// light/dark theme — only the wallpaper varies. We mirror that here so the\n// QR + username stay maximally readable against any wallpaper.\n//\n// Two layouts are baked from the same paint logic:\n//   • DISPLAY_LAYOUT — what we paint into the visible canvas inside the popup.\n//     Compact (376×472 CSS px @ 2× DPR = 752×944) with the requested 2.5rem\n//     top + 2rem bottom wallpaper rails.\n//   • EXPORT_LAYOUT  — what we bake into the PNG blob handed to clipboard.\n//     Matches iOS's `generateImage`: 390×844pt sheet at 3× scale (1170×2532px),\n//     with the white card centered vertically in the sheet, avatar overhanging,\n//     and the wallpaper filling the rest. Display dimensions don't follow this\n//     because the user explicitly asked for a compact in-popup view.\ntype CanvasLayout = {\n  canvasW: number;\n  canvasH: number;\n  dpr: number;\n  cardX: number;\n  cardY: number;\n  cardW: number;\n  cardH: number;\n  cardR: number;\n  avatarCx: number;\n  avatarCy: number;\n  qrX: number;\n  qrY: number;\n  qrSize: number;\n  usernameY: number;\n};\n\n// Shared iOS card dimensions (used by both layouts).\nconst CARD_W = 300;                         // iOS L2001\nconst CARD_H = 330;                         // iOS L2003 (300 × 1.1)\nconst CARD_R = 42;                          // iOS L1634\nconst AVATAR_RING = 4;                      // 4px white halo (user request)\nconst AVATAR_R = AVATAR_SIZE / 2;           // 50\nconst AVATAR_OVERHANG = Math.floor(AVATAR_SIZE * 0.7);  // 70 — L2038\n\n// Display layout — the in-popup compact view.\nconst DISPLAY_CANVAS_W = 376;\nconst DISPLAY_TOP_PAD = 40;                 // 2.5rem rail above the avatar\nconst DISPLAY_BOTTOM_PAD = 32;              // 2rem rail below the card\nconst DISPLAY_CARD_Y = DISPLAY_TOP_PAD + AVATAR_OVERHANG;        // 110\nconst DISPLAY_LAYOUT: CanvasLayout = {\n  canvasW: DISPLAY_CANVAS_W,\n  canvasH: DISPLAY_CARD_Y + CARD_H + DISPLAY_BOTTOM_PAD,         // 472\n  dpr: 2,\n  cardX: (DISPLAY_CANVAS_W - CARD_W) / 2,                        // 38\n  cardY: DISPLAY_CARD_Y,\n  cardW: CARD_W,\n  cardH: CARD_H,\n  cardR: CARD_R,\n  avatarCx: DISPLAY_CANVAS_W / 2,\n  avatarCy: DISPLAY_CARD_Y - AVATAR_OVERHANG + AVATAR_R,         // 90\n  qrX: (DISPLAY_CANVAS_W - QR_SIZE) / 2,                         // 78\n  qrY: DISPLAY_CARD_Y + 50,                                      // 160\n  qrSize: QR_SIZE,\n  usernameY: DISPLAY_CARD_Y + 50 + QR_SIZE + 20                  // 400\n};\n\n// Export layout — iOS-faithful 390×844 sheet at 3× scale. Card centered\n// vertically per ChatQrCodeScreen.swift L2003 (`(size.height - card) / 2`).\nconst EXPORT_CANVAS_W = 390;\nconst EXPORT_CANVAS_H = 844;\nconst EXPORT_CARD_Y = Math.floor((EXPORT_CANVAS_H - CARD_H) / 2);  // 257\nconst EXPORT_LAYOUT: CanvasLayout = {\n  canvasW: EXPORT_CANVAS_W,\n  canvasH: EXPORT_CANVAS_H,\n  dpr: 3,\n  cardX: (EXPORT_CANVAS_W - CARD_W) / 2,                          // 45\n  cardY: EXPORT_CARD_Y,\n  cardW: CARD_W,\n  cardH: CARD_H,\n  cardR: CARD_R,\n  avatarCx: EXPORT_CANVAS_W / 2,                                  // 195\n  avatarCy: EXPORT_CARD_Y - AVATAR_OVERHANG + AVATAR_R,           // 237\n  qrX: (EXPORT_CANVAS_W - QR_SIZE) / 2,                           // 85\n  qrY: EXPORT_CARD_Y + 50,                                        // 307\n  qrSize: QR_SIZE,\n  usernameY: EXPORT_CARD_Y + 50 + QR_SIZE + 20                    // 547\n};\n\n// Same system font stack the rest of the popup uses — no rounded override.\nconst USERNAME_FONT_FAMILY = FontFamily;\n// Floor for the shrink-to-fit below; pathological lengths (e.g. a 64-char first\n// name) ellipsize rather than shrink to an unreadable size.\nconst USERNAME_MIN_FONT = 12;\n\n// iOS length buckets (ChatQrCodeScreen.swift L1973-1978) — used as the *starting*\n// size. iOS then lays the text out in a fixed-width column, wrapping to 2 lines /\n// truncating; our canvas paints a single centred line, so we shrink from this\n// bucket to fit the same column width instead (see fitUsernameFontSize).\nfunction pickUsernameFontSize(text: string): number {\n  const n = text.length;\n  if(n >= 18) return 16;\n  if(n >= 12) return 22;\n  return 24;\n}\n\n// Largest size ≤ the length bucket at which `text` fits `maxWidth` on one line,\n// floored at USERNAME_MIN_FONT. Sets ctx.font to the chosen size as a side effect\n// so the caller can measure/paint without re-assigning it.\nfunction fitUsernameFontSize(ctx: CanvasRenderingContext2D, text: string, maxWidth: number): number {\n  let size = pickUsernameFontSize(text);\n  while(size > USERNAME_MIN_FONT) {\n    ctx.font = `${FontWeightBold} ${size}px ${USERNAME_FONT_FAMILY}`;\n    if(ctx.measureText(text).width <= maxWidth) return size;\n    size--;\n  }\n  ctx.font = `${FontWeightBold} ${USERNAME_MIN_FONT}px ${USERNAME_FONT_FAMILY}`;\n  return USERNAME_MIN_FONT;\n}\n\n// Trim `text` (at the already-set ctx.font) to the longest prefix that fits\n// `maxWidth` with a trailing ellipsis. No-op when it already fits.\nfunction ellipsizeToWidth(ctx: CanvasRenderingContext2D, text: string, maxWidth: number): string {\n  if(ctx.measureText(text).width <= maxWidth) return text;\n  const ellipsis = '…';\n  let lo = 0, hi = text.length;\n  while(lo < hi) {\n    const mid = Math.ceil((lo + hi) / 2);\n    if(ctx.measureText(text.slice(0, mid) + ellipsis).width <= maxWidth) lo = mid;\n    else hi = mid - 1;\n  }\n  return text.slice(0, lo) + ellipsis;\n}\n\nfunction TopSection(props: {\n  shared: QrPopupShared,\n  /** Returns the latest pre-baked PNG blob of the captured canvas, or undefined\n   *  if no paint has completed yet. Used by FooterSlot's copy handler so the\n   *  click can stay fully synchronous — no toBlob round-trip on the click. */\n  blobRef: (getter: () => Blob | undefined) => void,\n  onWallpaperReady?: () => void\n}) {\n  const {activeWallPaper, nightMode, profileUrl, QRCodeStylingCtor, username, self} = props.shared;\n\n  let canvas!: HTMLCanvasElement;\n  let wallpaperHost!: HTMLDivElement;\n  let avatarHost!: HTMLDivElement;\n\n  let qrRepaintId = 0;\n  let latestBlob: Blob | undefined;\n  let blobRepaintId = 0;\n  props.blobRef(() => latestBlob);\n  let wallpaperReady = false;\n  let disposed = false;\n\n  // QR canvas is generated asynchronously by qr-code-styling. We bake it into\n  // a signal so the main canvas repaint stays synchronous — that's what kills\n  // the race where a second effect fire would reset the canvas mid-paint of\n  // a first one that's still awaiting paintQrCode.\n  const [inkQrCanvas, setInkQrCanvas] = createSignal<HTMLCanvasElement | undefined>(undefined);\n\n  const regenerateQr = async() => {\n    const ctor = QRCodeStylingCtor();\n    if(!ctor) return;\n    const id = ++qrRepaintId;\n    const scratch = document.createElement('div');\n    // iOS uses solid black QR ink on the white card (ChatQrCodeScreen.swift\n    // L1754 `color: .black`) and a solid-black logo circle (L2044-2058\n    // `generateFilledCircleImage(... color: .black)`). No theme dependence.\n    await paintQrCode({\n      data: profileUrl(),\n      size: QR_SIZE,\n      host: scratch,\n      background: 'rgba(0,0,0,0)',\n      foreground: '#000000',\n      logoColor: '#000000',\n      // One QR bitmap feeds both the display (2×) and the 1170×2532 export (3×).\n      // Bake it at ≥3× so the export PNG stays crisp on 1×/2× displays.\n      pixelRatio: Math.max(window.devicePixelRatio, EXPORT_LAYOUT.dpr),\n      QRCodeStylingCtor: ctor\n    });\n    if(id !== qrRepaintId) return;\n    const inkQr = scratch.lastChild;\n    if(inkQr instanceof HTMLCanvasElement) setInkQrCanvas(inkQr);\n  };\n\n  // The offscreen canvas we render the export-sized image into. Display and\n  // export share `paintTo` — only the layout differs.\n  const exportCanvas = document.createElement('canvas');\n\n  // SYNC paint to an arbitrary canvas + layout. No awaits inside; the QR\n  // canvas comes pre-baked from `inkQrCanvas()`.\n  // Layering:\n  //   wallpaper → white card (no shadow, iOS L1633-1637) → 4px white ring +\n  //   avatar (iOS uses no ring, we add a 4px halo per design request) → QR\n  //   (wallpaper-gradient-masked, luminance-clamped for scannability) →\n  //   username (same luminance-clamped wallpaper-gradient text).\n  // The card is white regardless of the popup's night-mode toggle (mirrors\n  // iOS) — night mode only flips the wallpaper variant + the popup's bottom\n  // chrome.\n  const paintTo = (target: HTMLCanvasElement, layout: CanvasLayout) => {\n    const ctx = target.getContext('2d');\n    if(!ctx) return;\n\n    const stops = activeWallPaper().wallpaperStops;\n\n    // canvas.width/height assignment also clears + resets the backing store —\n    // do this every paint so DPR changes / first-paint sizing work the same.\n    target.width = layout.canvasW * layout.dpr;\n    target.height = layout.canvasH * layout.dpr;\n    ctx.setTransform(layout.dpr, 0, 0, layout.dpr, 0, 0);\n    ctx.clearRect(0, 0, layout.canvasW, layout.canvasH);\n\n    // 1. Wallpaper\n    drawWallpaper(ctx, wallpaperHost, layout.canvasW, layout.canvasH);\n\n    // 2. Card — always-white, no shadow.\n    ctx.save();\n    ctx.fillStyle = '#ffffff';\n    roundRect(ctx, layout.cardX, layout.cardY, layout.cardW, layout.cardH, layout.cardR, true);\n    ctx.restore();\n\n    // 3. Avatar — 4px white ring + circular photo (or initials fallback).\n    drawAvatar(ctx, avatarHost, layout.avatarCx, layout.avatarCy);\n\n    // 4. QR — black ink baked by qr-code-styling, then re-tinted by masking\n    // through a flat linear gradient built from the wallpaper's stop palette.\n    // We mask the gradient instead of the wallpaper itself so the pattern\n    // doodles don't bleed through and leave the dots see-through.\n    const qr = inkQrCanvas();\n    if(qr) {\n      const maskedQr = composeQrWithGradient(qr, stops, '#000000');\n      ctx.drawImage(maskedQr, layout.qrX, layout.qrY, layout.qrSize, layout.qrSize);\n    }\n\n    // 5. Username — luminance-clamped wallpaper gradient (same darkenInkStops as\n    // the QR ink), so the text reads dark on the white card on every theme.\n    // @username for public peers; else the user's first name or the chat title\n    // (channels/groups have `title`, not `first_name`).\n    const text = username() ?\n      '@' + username().toUpperCase() :\n      (self.first_name || (self as unknown as Chat.channel).title || '');\n    if(text) {\n      ctx.save();\n      ctx.textAlign = 'center';\n      ctx.textBaseline = 'top';\n      // Available text column, mirroring iOS L2032: cardW − floor(qrInsetX × 1.2)\n      // (= 300 − 48 = 252 on the standard card). Shrink the font to fit it on one\n      // line, then ellipsize if even the min size overflows — a long @username or\n      // 64-char first name must never bleed past the card onto the wallpaper.\n      const qrInsetX = (layout.cardW - layout.qrSize) / 2;\n      const maxTextWidth = layout.cardW - Math.floor(qrInsetX * 1.2);\n      const size = fitUsernameFontSize(ctx, text, maxTextWidth); // sets ctx.font\n      const shown = ellipsizeToWidth(ctx, text, maxTextWidth);\n      const width = ctx.measureText(shown).width;\n      const dark = darkenInkStops(stops);\n      if(dark.length >= 2) {\n        const grad = ctx.createLinearGradient(\n          layout.avatarCx - width / 2, layout.usernameY,\n          layout.avatarCx + width / 2, layout.usernameY + size\n        );\n        for(let i = 0; i < dark.length; i++) {\n          grad.addColorStop(i / (dark.length - 1), dark[i]);\n        }\n        ctx.fillStyle = grad;\n        ctx.fillText(shown, layout.avatarCx, layout.usernameY);\n      } else {\n        ctx.fillStyle = dark[0] ?? '#000000';\n        ctx.fillText(shown, layout.avatarCx, layout.usernameY);\n      }\n      ctx.restore();\n    }\n  };\n\n  const paint = () => {\n    // `disposed` guards the late avatar-`load` listener (and any stray callback)\n    // from painting into a detached canvas after the popup closes.\n    if(disposed || !canvas) return;\n    // 1. Paint the visible compact canvas.\n    paintTo(canvas, DISPLAY_LAYOUT);\n\n    // 2. Re-paint the offscreen iOS-dimensioned canvas, then pre-bake its PNG\n    // blob. The Copy click handler ships THIS blob to `clipboard.write` —\n    // synchronously, in the same JS tick as the click event — so we never\n    // race the user-activation / focus window that Chrome enforces for\n    // `clipboard.write`. Each paint bumps `blobRepaintId` so any in-flight\n    // toBlob from a previous frame is discarded. iOS uses 390×844pt @ 3× =\n    // 1170×2532px (ChatQrCodeScreen.swift L1909-1914) — we match exactly.\n    paintTo(exportCanvas, EXPORT_LAYOUT);\n    const id = ++blobRepaintId;\n    exportCanvas.toBlob((b) => {\n      if(id !== blobRepaintId) return;\n      latestBlob = b ?? undefined;\n    }, 'image/png');\n  };\n\n  // Async: regenerate QR canvas whenever its inputs change. NOT nightMode — the\n  // QR is baked with solid #000000 ink; the night/day recolor happens in the\n  // sync repaint below via composeQrWithGradient. Including nightMode here would\n  // needlessly re-run the async qr-code-styling + logo fetch on every toggle.\n  createEffect(on(\n    [QRCodeStylingCtor, profileUrl],\n    () => {\n      regenerateQr();\n    }\n  ));\n\n  // Sync: repaint whenever any visible signal changes (incl. the new QR canvas).\n  createEffect(on(\n    [nightMode, username, inkQrCanvas,\n      () => activeWallPaper().wallpaperStops.join(',')],\n    () => {\n      paint();\n    }\n  ));\n\n  // ChatBackgroundLayer fires onReady after its gradient + pattern canvases\n  // are actually painted — push a fresh sync paint so the wallpaper mask\n  // catches the latest pixels (state-change effect runs before the canvas is\n  // ready on first mount). Only AFTER this does the popup get to fade in:\n  // firing the gate from `paint()` would unfreeze the open transition while\n  // the canvas still has no wallpaper, defeating the \"match the iOS reveal\"\n  // behaviour we want.\n  const onLayerReady = () => {\n    paint();\n    if(!wallpaperReady) {\n      wallpaperReady = true;\n      props.onWallpaperReady?.();\n    }\n  };\n\n  // Safety net: if ChatBackgroundLayer's onReady is ever late or lost (e.g. a\n  // wallpaper build that never settles), reveal the popup anyway rather than\n  // leaving it permanently invisible. onLayerReady is idempotent (guarded by\n  // `wallpaperReady`), so an early real onReady makes this a no-op.\n  const readyFallbackTimer = setTimeout(onLayerReady, 600);\n\n  // Avatar photo loads asynchronously (blob URL gets assigned after the\n  // AvatarNewTsx mount), so the first paint paints the ring with no photo\n  // inside. Watch the host for img mutations and repaint once the photo's\n  // `load` event fires. Same for the avatar gradient swap (no-photo →\n  // photo) when AvatarNewTsx swaps its child.\n  let avatarObserver: MutationObserver | undefined;\n  const attachAvatarPhotoListener = () => {\n    if(!avatarHost) return;\n    const photo = avatarHost.querySelector('img.avatar-photo') as HTMLImageElement | null;\n    if(!photo) return;\n    if(photo.complete && photo.naturalWidth > 0) {\n      paint();\n      return;\n    }\n    photo.addEventListener('load', () => paint(), {once: true});\n  };\n  // Solid mounts the host before AvatarNewTsx writes the img; observe child\n  // mutations so we catch the late img addition without busy-polling.\n  const startAvatarObserver = () => {\n    if(!avatarHost || avatarObserver) return;\n    attachAvatarPhotoListener();\n    avatarObserver = new MutationObserver(() => attachAvatarPhotoListener());\n    avatarObserver.observe(avatarHost, {childList: true, subtree: true, attributes: true, attributeFilter: ['src']});\n  };\n  onCleanup(() => {\n    disposed = true;\n    clearTimeout(readyFallbackTimer);\n  });\n  // Defer to a microtask so refs are populated.\n  queueMicrotask(startAvatarObserver);\n  onCleanup(() => avatarObserver?.disconnect());\n\n  return (\n    <>\n      {/* Off-DOM hosts: ChatBackground keeps mounting / repainting wallpaper\n          canvases, AvatarNew keeps loading the photo. We never display them\n          directly — we just sample their internal canvas / img via `wallpaper­\n          Host` / `avatarHost` refs during repaint. */}\n      <div\n        ref={wallpaperHost}\n        class={styles.hiddenHost}\n        style={{width: EXPORT_LAYOUT.canvasW + 'px', height: EXPORT_LAYOUT.canvasH + 'px'}}\n      >\n        {/* Sized for the larger (export) layout so the gradient + pattern\n            canvases render high-enough resolution for both display sampling\n            AND the iOS-sized export. drawWallpaper scales them down for the\n            smaller display layout. */}\n        <ChatBackgroundLayer\n          theme={activeWallPaper().theme as AppTheme}\n          wallPaper={activeWallPaper().wallPaper}\n          transition=\"instant\"\n          width={EXPORT_LAYOUT.canvasW}\n          height={EXPORT_LAYOUT.canvasH}\n          onReady={onLayerReady}\n        />\n      </div>\n      <div\n        ref={avatarHost}\n        class={styles.hiddenHost}\n        style={{width: AVATAR_SIZE + 'px', height: AVATAR_SIZE + 'px'}}\n      >\n        <AvatarNewTsx peerId={props.shared.peerId} size={AVATAR_SIZE} isBig />\n      </div>\n\n      <canvas\n        ref={(el) => { canvas = el; }}\n        class={styles.captureCanvas}\n        style={{width: DISPLAY_LAYOUT.canvasW + 'px', height: DISPLAY_LAYOUT.canvasH + 'px'}}\n      />\n    </>\n  );\n}\n\n// Safari < 17's 2D canvas exposes `ctx.filter` but silently ignores it. Detect\n// once by setting a known filter and checking it stuck.\nlet _canvasFilterSupported: boolean | undefined;\nfunction supportsCanvasFilter(): boolean {\n  if(_canvasFilterSupported === undefined) {\n    const probe = document.createElement('canvas').getContext('2d');\n    if(probe) {\n      probe.filter = 'invert(1)';\n      _canvasFilterSupported = probe.filter === 'invert(1)';\n    } else {\n      _canvasFilterSupported = false;\n    }\n  }\n  return _canvasFilterSupported;\n}\n\n// Manual `filter: invert(1)` equivalent: draw `src` (with the already-computed\n// object-fit-cover crop) into a w×h buffer and invert its RGB. For browsers\n// whose canvas ignores ctx.filter, so dark-pattern wallpapers still render.\nfunction invertLayer(\n  src: CanvasImageSource,\n  sx: number, sy: number, sw: number, sh: number,\n  w: number, h: number\n): HTMLCanvasElement {\n  const tmp = document.createElement('canvas');\n  tmp.width = w;\n  tmp.height = h;\n  const tctx = tmp.getContext('2d');\n  tctx.drawImage(src, sx, sy, sw, sh, 0, 0, w, h);\n  const image = tctx.getImageData(0, 0, w, h);\n  const d = image.data;\n  for(let i = 0; i < d.length; i += 4) {\n    d[i] = 255 - d[i];\n    d[i + 1] = 255 - d[i + 1];\n    d[i + 2] = 255 - d[i + 2];\n  }\n  tctx.putImageData(image, 0, 0);\n  return tmp;\n}\n\n/**\n * Walks the hidden wallpaper host and composites every active-slot canvas\n * onto `ctx`, honouring CSS opacity / mix-blend-mode / filter so the result\n * matches what ChatBackgroundLayer paints on-screen for its visible peers\n * (gradient + soft-light pattern overlay etc).\n */\nfunction drawWallpaper(ctx: CanvasRenderingContext2D, host: HTMLElement, w: number, h: number) {\n  // Slot backdrop (e.g. IsPattern paints black so dark-pattern designs land on\n  // solid black; IsImage falls back to body bg).\n  const slots = host.querySelectorAll('[class*=\"Slot\"]');\n  for(const slot of slots) {\n    if(!(slot as HTMLElement).className.match(/Active/)) continue;\n    const bg = window.getComputedStyle(slot as HTMLElement).backgroundColor;\n    if(bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {\n      ctx.save();\n      ctx.fillStyle = bg;\n      ctx.fillRect(0, 0, w, h);\n      ctx.restore();\n    }\n    for(const layer of slot.querySelectorAll('canvas, img')) {\n      const isCanvas = layer.tagName === 'CANVAS';\n      const isImg = layer.tagName === 'IMG';\n      if(isCanvas) {\n        const c = layer as HTMLCanvasElement;\n        if(c.width === 0 || c.height === 0) continue;\n      }\n      if(isImg) {\n        const i = layer as HTMLImageElement;\n        if(!i.complete || i.naturalWidth === 0) continue;\n      }\n      const style = window.getComputedStyle(layer as HTMLElement);\n      const alpha = parseFloat(style.opacity || '1');\n      const mix = style.mixBlendMode;\n      const filter = style.filter;\n      const srcW = isCanvas ? (layer as HTMLCanvasElement).width : (layer as HTMLImageElement).naturalWidth;\n      const srcH = isCanvas ? (layer as HTMLCanvasElement).height : (layer as HTMLImageElement).naturalHeight;\n      // Mimic CSS object-fit: cover so the doodle pattern aspect ratio survives\n      // the source→destination scale.\n      let sx = 0, sy = 0, sw = srcW, sh = srcH;\n      const srcA = srcW / srcH, dstA = w / h;\n      if(srcA > dstA) {\n        sw = srcH * dstA;\n        sx = (srcW - sw) / 2;\n      } else if(srcA < dstA) {\n        sh = srcW / dstA;\n        sy = (srcH - sh) / 2;\n      }\n      ctx.save();\n      ctx.globalAlpha = isNaN(alpha) ? 1 : alpha;\n      if(mix && mix !== 'normal') ctx.globalCompositeOperation = mix as GlobalCompositeOperation;\n      const isInvert = filter && /invert\\(\\s*(1|100%)\\s*\\)/.test(filter);\n      if(isInvert && !supportsCanvasFilter()) {\n        // Safari's 2D canvas silently ignores ctx.filter, so a dark-pattern's\n        // `invert(1)` would be dropped — invert manually via an offscreen buffer.\n        ctx.drawImage(invertLayer(layer as CanvasImageSource, sx, sy, sw, sh, w, h), 0, 0);\n      } else {\n        if(filter && filter !== 'none') ctx.filter = filter;\n        ctx.drawImage(layer as CanvasImageSource, sx, sy, sw, sh, 0, 0, w, h);\n      }\n      ctx.restore();\n    }\n  }\n}\n\n/**\n * White ring + circle-clipped avatar photo (or initials+gradient fallback) at\n * the supplied (cx, cy) centre. The ring matches the card surface so the\n * avatar visually \"punches\" through the wallpaper rail above and into the\n * card below. Caller picks the centre to match its layout (display vs export).\n */\nfunction drawAvatar(ctx: CanvasRenderingContext2D, host: HTMLElement, cx: number, cy: number) {\n  // 4px white ring around the avatar — same colour as the card surface.\n  ctx.save();\n  ctx.fillStyle = '#ffffff';\n  ctx.beginPath();\n  ctx.arc(cx, cy, AVATAR_R + AVATAR_RING, 0, Math.PI * 2);\n  ctx.fill();\n  ctx.restore();\n\n  const photo = host.querySelector('img.avatar-photo') as HTMLImageElement | null;\n  if(photo && photo.complete && photo.naturalWidth > 0) {\n    ctx.save();\n    ctx.beginPath();\n    ctx.arc(cx, cy, AVATAR_R, 0, Math.PI * 2);\n    ctx.clip();\n    // object-fit: cover from src to (cx-r, cy-r, 2r, 2r)\n    const src = photo;\n    const srcA = src.naturalWidth / src.naturalHeight;\n    let sx = 0, sy = 0, sw = src.naturalWidth, sh = src.naturalHeight;\n    if(srcA > 1) {\n      sw = src.naturalHeight;\n      sx = (src.naturalWidth - sw) / 2;\n    } else if(srcA < 1) {\n      sh = src.naturalWidth;\n      sy = (src.naturalHeight - sh) / 2;\n    }\n    ctx.drawImage(src, sx, sy, sw, sh, cx - AVATAR_R, cy - AVATAR_R, AVATAR_R * 2, AVATAR_R * 2);\n    ctx.restore();\n    return;\n  }\n\n  // Fallback: gradient tile + initials, mirroring AvatarNew's no-photo state.\n  // AvatarNewTsx paints the placeholder via `.avatar-gradient { background:\n  // linear-gradient(--color-top, --color-bottom) }` (so background-COLOR is\n  // transparent, not the fill) and renders the initials as a bare text node (no\n  // `.avatar-abbreviation` class). So read the resolved gradient off\n  // `background-image` and the initials off the element's text.\n  const avatarEl = host.querySelector('.avatar') as HTMLElement | null;\n  const cs = avatarEl ? window.getComputedStyle(avatarEl) : null;\n  ctx.save();\n  ctx.beginPath();\n  ctx.arc(cx, cy, AVATAR_R, 0, Math.PI * 2);\n  ctx.clip();\n  const gradientColors: string[] = cs ? (cs.backgroundImage.match(/rgba?\\([^)]+\\)|#[0-9a-f]{3,8}/gi) ?? []) : [];\n  if(gradientColors.length >= 2) {\n    const grad = ctx.createLinearGradient(cx, cy - AVATAR_R, cx, cy + AVATAR_R);\n    grad.addColorStop(0, gradientColors[0]);\n    grad.addColorStop(1, gradientColors[gradientColors.length - 1]);\n    ctx.fillStyle = grad;\n  } else {\n    const bg = cs?.backgroundColor;\n    ctx.fillStyle = (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') ? bg : 'rgb(51, 144, 236)';\n  }\n  ctx.fillRect(cx - AVATAR_R, cy - AVATAR_R, AVATAR_R * 2, AVATAR_R * 2);\n  const abbreviation = avatarEl?.textContent?.trim() ?? '';\n  if(abbreviation) {\n    ctx.fillStyle = '#ffffff';\n    ctx.font = `600 ${Math.round(AVATAR_R * 0.8)}px system-ui, -apple-system, sans-serif`;\n    ctx.textAlign = 'center';\n    ctx.textBaseline = 'middle';\n    ctx.fillText(abbreviation, cx, cy);\n  }\n  ctx.restore();\n}\n\n/**\n * Compose the QR ink with a SOLID linear gradient built from the wallpaper's\n * stop palette — NOT the full ChatBackground rendering. The pattern overlay\n * (doodle outlines, mix-blend modes) would otherwise punch holes through every\n * QR dot, leaving them mostly black on dark themes and producing the \"the QR\n * is see-through\" look. By rebuilding the gradient on a flat canvas first and\n * `destination-in`'ing the QR onto it, every ink pixel reads as a pure\n * gradient colour at full opacity — matching the iOS \"QR + logo painted in\n * the wallpaper's accent gradient\" feel the user asked for.\n */\n/**\n * Build the QR ink overlay: a luminance-clamped wallpaper-gradient fill (see\n * darkenInkStops — guarantees the modules clear ≥~4.5:1 on the white card so the\n * code actually scans), masked against the QR canvas so only the dots / squares\n * / logo show through.\n */\nfunction composeQrWithGradient(\n  inkQrCanvas: HTMLCanvasElement,\n  stops: string[],\n  fallback: string\n): HTMLCanvasElement {\n  const masked = document.createElement('canvas');\n  masked.width = inkQrCanvas.width;\n  masked.height = inkQrCanvas.height;\n  const mctx = masked.getContext('2d');\n  if(!mctx) return inkQrCanvas;\n  // Clamp the wallpaper stops to a scannable luminance (see darkenInkStops) —\n  // this replaces the old flat 20% dim, which left light-theme QRs at ~1.6:1\n  // contrast and unscannable.\n  const dark = darkenInkStops(stops);\n  if(dark.length >= 2) {\n    // Diagonal sweep so multi-stop gradients still read as a sweep across the\n    // QR rather than a horizontal band — same direction as the wallpaper's\n    // own gradient renderer.\n    const g = mctx.createLinearGradient(0, 0, masked.width, masked.height);\n    for(let i = 0; i < dark.length; i++) {\n      g.addColorStop(i / (dark.length - 1), dark[i]);\n    }\n    mctx.fillStyle = g;\n  } else {\n    mctx.fillStyle = dark[0] ?? fallback;\n  }\n  mctx.fillRect(0, 0, masked.width, masked.height);\n  mctx.globalCompositeOperation = 'destination-in';\n  mctx.drawImage(inkQrCanvas, 0, 0);\n  return masked;\n}\n\n/**\n * Re-scopes the popup container's CSS variables to the popup-local selected\n * theme + night-mode. Without this the COPY button keeps the globally-applied\n * `--primary-color` even after the user picks a green/blue/pink theme, so the\n * pill stays purple on every tile. Mounted invisibly inside the body; uses\n * `closest('.popup-container')` so it finds the outer popup container the\n * PopupElement renders us into, then drives `applyTheme` reactively.\n *\n * We don't pass an isNight override to `themeController.applyTheme` —\n * modifying the controller's signature would risk breaking the global\n * theme-switch View Transition. Instead we build a *virtual* theme: clone the\n * picked theme, pin its `name` to 'night'/'day' (so applyTheme's internal\n * `themeName` / `isNightThemeName` / `baseColors` lookups all land on the\n * popup-local brightness), and trim `settings[]` to the entry matching the\n * requested base. applyTheme then takes the right path through its normal\n * resolution and CSS variables land on the popup container.\n */\nfunction PopupThemeApplier(props: {\n  theme: () => AppTheme | Theme,\n  isNight: () => boolean\n}) {\n  let sentinel!: HTMLDivElement;\n  onMount(() => {\n    const container = sentinel.closest('.popup') as HTMLElement | null;\n    if(!container) return;\n    createEffect(() => {\n      const theme = props.theme();\n      const isNight = props.isNight();\n      const base: BaseTheme['_'] = isNight ? 'baseThemeNight' : 'baseThemeClassic';\n      const settings = Array.isArray((theme as Theme).settings) ?\n        (theme as Theme).settings :\n        undefined;\n      const entry = settings?.find((s) => s.base_theme._ === base) ?? settings?.[0];\n      const virtualTheme = {\n        ...theme,\n        name: isNight ? 'night' : 'day',\n        settings: entry ? [entry] : (theme as Theme).settings\n      } as unknown as Theme;\n      themeController.applyTheme(virtualTheme, container);\n    });\n  });\n  return <div ref={sentinel} style={{display: 'none'}} />;\n}\n\n/**\n * Body slot — header row (close + title + brightness toggle) lives inside the\n * body, not in `<PopupElement.Header>`, so it sits on the same surface as the\n * picker and footer (the registered Header slot is transparent by default,\n * which broke our seamless lower-panel look). Below the row is a Section with\n * the reusable ChatThemesPicker.\n */\nfunction BodySlot(props: {shared: QrPopupShared}) {\n  const {\n    selectedThemeId, setSelectedThemeId, baseTheme, nightMode, setNightMode,\n    activeWallPaper\n  } = props.shared;\n\n  return (\n    <PopupElement.Body>\n      <PopupThemeApplier\n        theme={() => activeWallPaper().theme}\n        isNight={nightMode}\n      />\n      <PopupElement.Header>\n        <PopupElement.CloseButton />\n        <PopupElement.Title class={styles.title}>{i18n('QRCode.Title')}</PopupElement.Title>\n        <Button.Icon\n          icon={nightMode() ? 'darkmode_filled' : 'darkmode'}\n          onClick={() => setNightMode(!nightMode())}\n        />\n      </PopupElement.Header>\n\n      <Section class={styles.bottomSection} noShadow noMarginBottom>\n        <ChatThemesPicker\n          class={styles.themePicker}\n          selectedId={selectedThemeId}\n          onSelect={(theme) => setSelectedThemeId(String(theme.id ?? ''))}\n          baseTheme={baseTheme}\n        />\n      </Section>\n    </PopupElement.Body>\n  );\n}\n\n/**\n * Footer slot — standard PopupElement.FooterButton with the Copy action.\n *\n * `clipboard.write` is permissive about the *type* of data inside a\n * ClipboardItem (it accepts a Promise<Blob>) but strict about the *click\n * context*: the write must be issued in the same JS tick as the user\n * activation, with the document still focused. The previous \"encode PNG, then\n * call write\" pipeline lost that race — `toBlob` is async, and by the time\n * the encoded Blob landed Chrome had already revoked the activation, throwing\n * `NotAllowedError: Document is not focused`.\n *\n * We sidestep the race by **pre-baking** the blob: TopSection calls\n * `canvas.toBlob` after every paint and stashes the resulting PNG via the\n * `blobRef` getter. By the time the user clicks Copy, the blob is already\n * sitting in memory — the click handler ships it straight to `clipboard.write`\n * synchronously, no `await` between the activation and the write call.\n */\nfunction FooterSlot(props: {shared: QrPopupShared, getBlob: () => Blob | undefined}) {\n  const {profileUrl} = props.shared;\n\n  const onCopyClick = async() => {\n    const blob = props.getBlob();\n    if(blob) {\n      try {\n        await writeClipboardItem({'image/png': blob});\n        toastNew({langPackKey: 'QRCode.Copied'});\n        return;\n      } catch(err) {\n        // Image-write may still fail on Safari (no `image/png` write support)\n        // or if the user denied clipboard permission at the OS / Chrome\n        // policy level. Fall through to the link copy.\n        console.error('QRCode image copy failed', err);\n      }\n    }\n\n    // No blob baked yet (first frame still in flight) OR write was rejected —\n    // copy the profile link instead. `copyTextToClipboard` wraps\n    // `clipboard.writeText` with a `document.execCommand('copy')` fallback,\n    // so this path works even when the modern API is blocked.\n    try {\n      await copyTextToClipboard(profileUrl());\n      toastNew({langPackKey: 'QRCode.CopiedLink'});\n    } catch(fallbackErr) {\n      console.error('QRCode link copy failed', fallbackErr);\n      toastNew({langPackKey: 'Error.AnError'});\n    }\n  };\n\n  return (\n    <PopupElement.Footer>\n      <PopupElement.FooterButton\n        class={styles.copyBtn}\n        iconLeft=\"copy\"\n        langKey=\"QRCode.Copy\"\n        callback={async() => {\n          await onCopyClick();\n        }}\n      />\n    </PopupElement.Footer>\n  );\n}\n\n/**\n * Opens the QR-code popup. Defaults to the current user (the Settings entry);\n * pass a `peerId` to show another peer's QR (the PeerProfile username/link rows),\n * and `options.url` to encode an explicit link instead of `t.me/<username>` (used\n * for a private group's invite link, which PeerProfile.Link already resolved).\n */\nexport default async function showMyQrCodePopup(peerId: PeerId = rootScope.myId, options?: {url?: string}) {\n  const self = peerId === rootScope.myId ?\n    await rootScope.managers.appUsersManager.getSelf() :\n    await rootScope.managers.appPeersManager.getPeer(peerId);\n  if(!self) return;\n\n  createPopup(() => {\n    const shared = createSharedState(self as User.user, peerId, options?.url);\n    let getBlob: () => Blob | undefined = () => undefined;\n\n    // Defer the popup's open animation until the captured canvas has painted\n    // its first frame (wallpaper + card + avatar + QR). PopupElement's slide+\n    // fade transition is ~150ms — without the gate the popup snaps in against\n    // an empty canvas, with the wallpaper popping in a beat later. The first\n    // TopSection repaint signals readiness via `onWallpaperReady`.\n    const [show, setShow] = createSignal(false);\n    const onWallpaperReady = () => {\n      if(show()) return;\n      setShow(true);\n    };\n\n    return (\n      <PopupElement\n        class={styles.popup}\n        containerClass={styles.popupContainer}\n        closable\n        old\n        show={show()}\n      >\n        <TopSection\n          shared={shared}\n          blobRef={(getter) => { getBlob = getter; }}\n          onWallpaperReady={onWallpaperReady}\n        />\n        <BodySlot shared={shared} />\n        <FooterSlot shared={shared} getBlob={() => getBlob()} />\n      </PopupElement>\n    );\n  });\n}\n","\nimport PopupElement, {createPopup} from '@components/popups/indexTsx';\nimport {StarsRating, User, UserFull} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport bigInt from 'big-integer';\nimport {LimitLineTsx} from '@components/limitLineTsx';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport Row from '@components/rowTsx';\nimport classNames from '@helpers/string/classNames';\nimport styles from '@components/popups/starsRating.module.scss';\nimport {createMemo, createSignal, Show, Switch} from 'solid-js';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport formatDuration from '@helpers/formatDuration';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport {Transition} from 'solid-transition-group';\nimport {IconTsx} from '@components/iconTsx';\nimport formatNumber from '@helpers/number/formatNumber';\n\nfunction Badge(props: {\n  active: boolean\n}) {\n  return (\n    <I18nTsx\n      key={props.active ? 'StarsRating.BadgeAdded' : 'StarsRating.BadgeDeducted'}\n      class={classNames(styles.badge, props.active && styles.active)}\n    />\n  );\n}\n\nexport default function showStarsRatingPopup(props: {\n  user: User.user\n  userFull: UserFull.userFull\n}) {\n  const {\n    stars_rating: currentRating,\n    stars_my_pending_rating: futureRating,\n    stars_my_pending_rating_date: futureRatingDate\n  } = props.userFull;\n\n  const isPersonal = props.user.id === rootScope.myId;\n  const pendingStars = Number(futureRating?.stars ?? 0) - Number(currentRating.stars);\n\n  const [isFuture, setIsFuture] = createSignal(false);\n  const rating = () => isFuture() ? futureRating : currentRating;\n  const isNegativeLevel = () => rating().level < 0;\n\n  createPopup(() => {\n    const progress = createMemo(() => {\n      const rating$ = rating();\n      const isMaxLevel = rating$.next_level_stars === undefined;\n      const isNegativeLevel = rating$.level < 0;\n      if(isNegativeLevel) {\n        return 0.5;\n      } else if(isMaxLevel) {\n        return 1;\n      } else {\n        return (Number(rating$.stars) - Number(rating$.current_level_stars)) /\n          (Number(rating$.next_level_stars) - Number(rating$.current_level_stars));\n      }\n    });\n\n    return (\n      <PopupElement class={styles.popup} containerClass={styles.popupContainer}>\n        <PopupElement.Header class={styles.popupHeader}>\n          <PopupElement.CloseButton class={styles.popupCloseButton} />\n        </PopupElement.Header>\n        <PopupElement.Body>\n          <LimitLineTsx\n            class={classNames(styles.limitLine, isNegativeLevel() && styles.limitLineNegative)}\n            progress={progress()}\n            progressFrom={isNegativeLevel() ? i18n('StarsRating.Negative') : i18n('StarsRating.Level', [rating().level])}\n            progressTo={isNegativeLevel() ? <div /> : i18n('StarsRating.Level', [rating().level + 1])}\n            reverse={isNegativeLevel()}\n            hint={isNegativeLevel() && !isPersonal ? undefined : (\n              <div class={styles.hint}>\n                {formatNumber(Number(rating().stars))}\n                {rating().next_level_stars && !isNegativeLevel() && (\n                  <span class={styles.nextLevelStars}>\n                    {' '}\n                    / {formatNumber(Number(rating().next_level_stars))}\n                  </span>\n                )}\n              </div>\n            )}\n            hintIcon={isNegativeLevel() ? 'warning_filled' : 'crownalt_filled'}\n            hintJustIcon={true}\n          />\n\n          <Show when={isNegativeLevel() && !futureRating}>\n            <I18nTsx\n              key={isPersonal ? 'StarsRating.NegativeDescriptionMy' : 'StarsRating.NegativeDescription'}\n              class={classNames(styles.description, styles.negativeDescription)}\n              args={isPersonal ?\n                [Math.abs(Number(rating().stars)).toString()] :\n                [wrapEmojiText(props.user.first_name)]\n              }\n            />\n          </Show>\n\n          <Show when={futureRating}>\n            <div class={styles.description}>\n              <Transition mode=\"outin\">\n                <Show when={!isFuture()}>\n                  <div class={styles.descriptionInner}>\n                    <I18nTsx\n                      key=\"StarsRating.PendingDescription\"\n                      args={[\n                        wrapFormattedDuration(formatDuration(futureRatingDate - Date.now() / 1000, 1)),\n                        pendingStars.toString()\n                      ]}\n                    />\n                    <a class={styles.previewButton} onClick={() => setIsFuture(true)}>\n                      <I18nTsx key=\"StarsRating.Preview\" />\n                      <IconTsx icon=\"next\" />\n                    </a>\n                  </div>\n                </Show>\n                <Show when={isFuture()}>\n                  <div class={styles.descriptionInner}>\n                    <I18nTsx\n                      key=\"StarsRating.FutureDescription\"\n                      args={[\n                        wrapFormattedDuration(formatDuration(futureRatingDate - Date.now() / 1000, 1)),\n                        pendingStars.toString()\n                      ]}\n                    />\n                    <a class={styles.previewButton} onClick={() => setIsFuture(false)}>\n                      <I18nTsx key=\"StarsRating.Back\" />\n                      <IconTsx icon=\"next\" />\n                    </a>\n                  </div>\n                </Show>\n              </Transition>\n            </div>\n          </Show>\n\n          <I18nTsx key=\"StarsRating.Title\" class={styles.title} />\n          <I18nTsx\n            key={isPersonal ? 'StarsRating.SubtitleMy' : 'StarsRating.Subtitle'}\n            class={styles.subtitle}\n            args={[wrapEmojiText(props.user.first_name)]}\n          />\n\n          <div class={styles.list}>\n            <Row class={styles.row}>\n              <Row.Icon class={styles.rowIcon} icon=\"gift_filled\" />\n              <Row.Title class=\"text-bold\">\n                <I18nTsx key=\"StarsRating.Row1Title\" />\n              </Row.Title>\n              <Row.Subtitle class={styles.rowSubtitle}>\n                <Badge active={true} />\n                <I18nTsx key=\"StarsRating.Row1Subtitle\" />\n              </Row.Subtitle>\n            </Row>\n\n            <Row class={styles.row}>\n              <Row.Icon class={styles.rowIcon} icon=\"group_star\" />\n              <Row.Title class=\"text-bold\">\n                <I18nTsx key=\"StarsRating.Row2Title\" />\n              </Row.Title>\n              <Row.Subtitle class={styles.rowSubtitle}>\n                <Badge active={true} />\n                <I18nTsx key=\"StarsRating.Row2Subtitle\" />\n              </Row.Subtitle>\n            </Row>\n\n            <Row class={styles.row}>\n              <Row.Icon class={styles.rowIcon} icon=\"reload_star\" />\n              <Row.Title class=\"text-bold\">\n                <I18nTsx key=\"StarsRating.Row3Title\" />\n              </Row.Title>\n              <Row.Subtitle class={styles.rowSubtitle}>\n                <Badge active={false} />\n                <I18nTsx key=\"StarsRating.Row3Subtitle\" />\n              </Row.Subtitle>\n            </Row>\n          </div>\n        </PopupElement.Body>\n        <PopupElement.FooterButton\n          class={styles.popupButton}\n          iconLeft=\"okay_filled\"\n          langKey=\"StarsRating.Understood\"\n        />\n      </PopupElement>\n    );\n  })\n}\n","import {PollResults} from '@layer';\n\nexport function roundPercents(percents: number[]): number[] {\n  const base = percents.map(Math.floor);\n\n  const remainders = percents.map((p, i) => ({\n    index: i,\n    remainder: p - base[i]\n  }));\n\n  const sum = base.reduce((a, b) => a + b, 0);\n  const diff = 100 - sum;\n\n  remainders.sort((a, b) => {\n    if(a.remainder === b.remainder) return base[b.index] - base[a.index];\n    return b.remainder - a.remainder;\n  });\n\n  const mxI = Math.min(diff, remainders.length);\n\n  for(let i = 0; i < mxI; i++) {\n    base[remainders[i].index]++;\n  }\n\n  return base;\n}\n\nexport const getRoundedPercentsFromResults = (pollResults?: PollResults) => {\n  const results = pollResults?.results;\n  if(!results) return [];\n\n  const totalVotes = results.reduce((acc, r) => acc + (r.voters ?? 0), 0);\n  if(!totalVotes) return new Array(results.length).fill(0);\n\n  return roundPercents(results.map(r => totalVotes ? (r.voters ?? 0) / totalVotes * 100 : 0));\n}\n","import {render} from 'solid-js/web';\nimport {SliderSuperTab} from '@components/slider';\nimport appSidebarRight from '..';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {i18n} from '@lib/langPack';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport Section from '@components/section';\nimport {Message, MessageMedia} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport wrapTextWithEntities from '@lib/richTextProcessor/wrapTextWithEntities';\nimport {Show, untrack} from 'solid-js';\nimport {createLoadableList, MoreButton} from '@components/sidebarRight/tabs/statistics';\nimport {formatFullSentTimeRaw} from '@helpers/date';\nimport {getRoundedPercentsFromResults} from '@components/chat/bubbleParts/pollMessageContent/roundPercents';\n\n\nexport default class AppPollResultsTab extends SliderSuperTab {\n  private dispose: VoidFunction;\n\n  public async init(message: Message.message) {\n    this.container.id = 'poll-results-container';\n    this.container.classList.add('chatlist-container');\n\n    const poll = await this.managers.appPollsManager.getPoll((message.media as MessageMedia.messageMediaPoll).poll.id);\n\n    this.setTitle(poll.poll.pFlags.quiz ? 'PollResults.Title.Quiz' : 'PollResults.Title.Poll');\n\n    this.header.append((\n      <div class=\"sidebar-header__rows\">\n        {this.title}\n        <div class=\"sidebar-header__subtitle\">\n          {i18n('Chat.Poll.MembersVoted', [poll.results.total_voters])}\n        </div>\n      </div>\n    ) as HTMLElement);\n\n    const percents = getRoundedPercentsFromResults(poll.results);\n\n    const getSections = () => poll.results.results.map((result, idx) => {\n      if(!result.voters) {\n        return;\n      }\n\n      const answer = poll.poll.answers[idx];\n\n      const answerTitle = document.createElement('div');\n      const answerText = wrapTextWithEntities(answer.text);\n      const answerTextWrapped = wrapRichText(answerText.text, {entities: answerText.entities, middleware: this.middlewareHelper.get()});\n      setInnerHTML(answerTitle, answerTextWrapped);\n      answerTitle.append(' — ', Math.round(percents[idx]) + '%');\n\n      const answerPercents = i18n('Chat.Poll.MembersVoted', [result.voters]);\n\n      // Humans\n      const list = appDialogsManager.createChatList();\n      list.classList.add('poll-results-voters');\n\n      appDialogsManager.setListClickListener({\n        list,\n        onFound: () => {\n          appSidebarRight.onCloseBtnClick();\n        },\n        openInner: true\n      });\n\n      list.style.minHeight = Math.min(result.voters, 4) * 48 + 'px';\n\n      let offset: string, limit = 4;\n      const load = async() => {\n        if(answer._ !== 'pollAnswer') return;\n\n        const votesList = await this.managers.appPollsManager.getVotes(\n          message,\n          answer.option,\n          offset,\n          limit\n        );\n\n        const elements = votesList.votes.map((vote) => {\n          const {dom} = appDialogsManager.addDialogNew({\n            peerId: getPeerId(vote.peer),\n            container: false,\n            rippleEnabled: false,\n            meAsSaved: false,\n            avatarSize: 'small',\n            withStories: false,\n            wrapOptions: {\n              middleware: this.middlewareHelper.get()\n            },\n            dontSetActive: true\n          });\n          dom.lastMessageSpan.parentElement.remove();\n          const {dateEl, timeEl} = formatFullSentTimeRaw(vote.date);\n          dom.containerEl.append((\n            <span class=\"vote-time-container disable-hover\">\n              <span class=\"vote-time-title secondary\">{dateEl}</span>\n              <span class=\"vote-time-subtitle primary-text\">{timeEl}</span>\n            </span>\n          ) as HTMLElement);\n          return dom.containerEl;\n        });\n\n        setLoader((value) => {\n          value.count = votesList.count;\n          limit = 20;\n          if(!(offset = votesList.next_offset)) {\n            value.loadMore = undefined;\n          }\n\n          list.append(...elements);\n          value.rendered.push(...elements);\n          return value;\n        });\n      };\n\n      const [loader, setLoader] = createLoadableList({loadMore: load});\n      loader().loadMore();\n\n      return (\n        <Section\n          name={answerTitle}\n          nameRight={answerPercents}\n        >\n          {list}\n          <Show when={!!loader().loadMore}>\n            <MoreButton\n              count={loader().count - loader().rendered.length}\n              callback={() => loader().loadMore()}\n            />\n          </Show>\n        </Section>\n      );\n    });\n\n    const questionText = wrapTextWithEntities(poll.poll.question);\n    const questionFragment = wrapRichText(questionText.text, {\n      entities: questionText.entities,\n      middleware: this.middlewareHelper.get()\n    });\n\n    const div = document.createElement('div');\n    div.classList.add('poll-results');\n    this.scrollable.append(div);\n\n    this.dispose = render(() => (\n      <>\n        <h3 dir=\"auto\">{questionFragment}</h3>\n        {untrack(getSections)}\n      </>\n    ), div);\n\n    appSidebarRight.toggleSidebar(true);\n  }\n\n  onCloseAfterTimeout() {\n    super.onCloseAfterTimeout();\n    this.dispose();\n  }\n}\n","\nimport {createEffect, createSignal, For, onCleanup, onMount, Show, JSX} from 'solid-js';\nimport SwipeHandler from '@components/swipeHandler';\nimport styles from '@components/slideshow.module.scss';\nimport classNames from '@helpers/string/classNames';\nimport {fastRaf} from '@helpers/schedulers';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {IconTsx} from '@components/iconTsx';\n\nexport type SlideshowProps<T> = {\n  class?: string;\n  items?: T[];\n  children?: (item: T, index: number) => JSX.Element;\n  initialIndex?: number;\n  activeIndex?: number;\n  onIndexChange?: (index: number) => void;\n  onClick?: (index: number) => void;\n};\n\nconst SCALE = 1;\nconst TRANSLATE_TEMPLATE = 'translate({x}, 0)';\n\nexport default function Slideshow<T>(props: SlideshowProps<T>) {\n  let container: HTMLDivElement;\n  let itemsContainer: HTMLDivElement;\n  let swipeHandler: SwipeHandler;\n\n  const [index, setIndex] = createSignal(props.initialIndex || 0);\n  const [isSwiping, setIsSwiping] = createSignal(false);\n  const [noTransition, setNoTransition] = createSignal(false);\n\n  const getCount = () => props.items.length;\n\n  let width = 0, x = 0, lastDiffX = 0, minX = 0;\n\n  onMount(() => {\n    swipeHandler = new SwipeHandler({\n      element: container,\n      onSwipe: (xDiff, yDiff) => {\n        xDiff *= -1;\n\n        lastDiffX = xDiff;\n        let lastX = x + xDiff * -SCALE;\n        if(lastX > 0) lastX = 0;\n        else if(lastX < minX) lastX = minX;\n\n        itemsContainer.style.transform = TRANSLATE_TEMPLATE.replace('{x}', lastX + 'px');\n        return false;\n      },\n      verifyTouchTarget: (e) => {\n        if(getCount() <= 1) return false;\n        return true;\n      },\n      onFirstSwipe: () => {\n        const rect = itemsContainer.getBoundingClientRect();\n        width = rect.width;\n        minX = -width * (getCount() - 1);\n        x = rect.left - container.getBoundingClientRect().left;\n\n        itemsContainer.style.transform = TRANSLATE_TEMPLATE.replace('{x}', x + 'px');\n\n        setIsSwiping(true);\n        setNoTransition(true);\n        void itemsContainer.offsetLeft; // reflow\n      },\n      onReset: () => {\n        const addIndex = Math.ceil(Math.abs(lastDiffX) / (width / SCALE)) * (lastDiffX >= 0 ? 1 : -1);\n\n        setNoTransition(false);\n        fastRaf(() => {\n          let newIndex = index() + addIndex;\n          if(newIndex < 0) newIndex = 0;\n          if(newIndex >= getCount()) newIndex = getCount() - 1;\n\n          setIndex(newIndex);\n          setIsSwiping(false);\n        });\n      }\n    });\n  });\n\n  onCleanup(() => {\n    swipeHandler?.removeListeners();\n  });\n\n  createEffect(() => {\n    if(props.activeIndex !== undefined && props.activeIndex !== index()) {\n      setIndex(props.activeIndex);\n    }\n  });\n\n  createEffect(() => {\n    const i = index();\n    if(itemsContainer) {\n      itemsContainer.style.transform = TRANSLATE_TEMPLATE.replace('{x}', `${-i * 100}%`);\n    }\n  });\n\n  const handleClick = (e: MouseEvent) => {\n    if(isSwiping()) return;\n\n    // Check if clicked buttons\n    const target = e.target as HTMLElement;\n    if(findUpClassName(target, styles.Arrow)) return;\n\n    const rect = container.getBoundingClientRect();\n    const x = e.clientX - rect.left;\n    const isLeft = x < (rect.width / 3);\n    const isRight = x > (rect.width * 2 / 3);\n\n    if(isLeft) {\n      handlePrev(e);\n    } else if(isRight) {\n      handleNext(e);\n    } else {\n      props.onClick?.(index());\n    }\n  };\n\n  const handlePrev = (e: Event) => {\n    e.stopPropagation();\n    if(index() > 0) {\n      const newIndex = index() - 1;\n      setIndex(newIndex);\n      props.onIndexChange?.(newIndex);\n    }\n  };\n\n  const handleNext = (e: Event) => {\n    e.stopPropagation();\n    if(index() < (getCount() - 1)) {\n      const newIndex = index() + 1;\n      setIndex(newIndex);\n      props.onIndexChange?.(newIndex);\n    }\n  };\n\n  return (\n    <div\n      ref={container}\n      class={classNames(\n        styles.Slideshow,\n        isSwiping() && styles.IsSwiping,\n        getCount() <= 1 && styles.IsSingle,\n        noTransition() && styles.NoTransition,\n        props.class\n      )}\n      onClick={handleClick}\n    >\n      <div\n        ref={itemsContainer}\n        class={styles.Items}\n      >\n        <For each={props.items}>{(item, i) => (\n          <div class={styles.Item}>\n            <Show when={Math.abs(i() - index()) < 5}>\n              {props.children?.(item, i())}\n            </Show>\n          </div>\n        )}</For>\n      </div>\n\n      <div class={styles.Tabs}>\n        <For each={new Array(getCount())}>{(_, i) => (\n          <div class={classNames(styles.Tab, i() === index() && styles.Active)} />\n        )}</For>\n      </div>\n\n      <div class={classNames(styles.Arrow, styles.ArrowPrev)} onClick={handlePrev}>\n        <IconTsx icon=\"avatarprevious\" class={styles.ArrowIcon} />\n      </div>\n      <div class={classNames(styles.Arrow, styles.ArrowNext)} onClick={handleNext}>\n        <IconTsx icon=\"avatarnext\" class={styles.ArrowIcon} />\n      </div>\n    </div>\n  );\n}\n","import {Ref, Show, createResource, splitProps} from 'solid-js';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {Middleware} from '@helpers/middleware';\n\nexport type MediaComponentProps = {\n  class?: string,\n  ref?: Ref<HTMLDivElement>,\n  onClick?: (e: MouseEvent) => void\n};\n\nexport function MediaTsx<T, R>(props: T & {\n  onResult?: (result: R) => void;\n  loader: (options: T & {middleware: Middleware, container: HTMLElement}) => Promise<R>;\n  itemKey: keyof T;\n} & MediaComponentProps) {\n  const [local, others] = splitProps(props, ['class', 'ref', 'onResult', 'loader', 'itemKey', 'onClick']);\n  let ref: HTMLDivElement;\n  const ret = (\n    <div\n      class={local.class}\n      ref={(_ref) => {\n        ref = _ref;\n        (local.ref as any)?.(ref);\n      }}\n      onClick={local.onClick}\n    ></div>\n  );\n\n  const [result] = createResource(() => (others as any)[local.itemKey], (item) => {\n    const middleware = createMiddleware().get();\n    return local.loader({\n      ...others as any,\n      item,\n      middleware,\n      container: ref\n    }).then(async(result: R) => {\n      if(!middleware()) {\n        return;\n      }\n\n      local.onResult?.(result);\n      return result;\n    });\n  });\n\n  return (\n    <Show when={result.latest}>\n      {ret}\n    </Show>\n  );\n}\n","import wrapDocument from '@components/wrappers/document';\nimport {MediaComponentProps, MediaTsx} from '@components/wrappers/mediaTsx';\nimport {Middleware} from '@helpers/middleware';\n\ntype DocumentProps = Omit<Parameters<typeof wrapDocument>[0], 'middleware'>;\n\nconst loader = (options: DocumentProps & {middleware: Middleware, container: HTMLElement}) => {\n  const {container, ...rest} = options;\n  return wrapDocument(rest as any).then((element) => {\n    container.appendChild(element);\n    return element;\n  });\n};\n\nexport default function DocumentTsx(props: DocumentProps & {\n  onResult?: (result: Awaited<ReturnType<typeof wrapDocument>>) => void;\n} & MediaComponentProps) {\n  return (\n    <MediaTsx<DocumentProps, Awaited<ReturnType<typeof wrapDocument>>>\n      {...props}\n      itemKey=\"message\"\n      loader={loader}\n    />\n  );\n}\n","import wrapPhoto from '@components/wrappers/photo';\nimport {MediaComponentProps, MediaTsx} from '@components/wrappers/mediaTsx';\n\nexport default function PhotoTsx(props: Parameters<typeof wrapPhoto>[0] & {\n  onResult?: (result: Awaited<ReturnType<typeof wrapPhoto>>) => void;\n} & MediaComponentProps) {\n  return (\n    <MediaTsx\n      {...props}\n      itemKey=\"photo\"\n      loader={wrapPhoto}\n    />\n  );\n}\n","import getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport wrapTelegramUrlToAnchor from '@lib/richTextProcessor/wrapTelegramUrlToAnchor';\n\ntype WrapTopicThreadAnchorArgs = {\n  peerId: PeerId;\n  threadId: number;\n  lastMsgId: number;\n};\n\nexport default function wrapTopicThreadAnchor({peerId, threadId, lastMsgId}: WrapTopicThreadAnchorArgs) {\n  return wrapTelegramUrlToAnchor(\n    't.me/c/' +\n    peerId.toChatId() +\n    (threadId ? '/' + getServerMessageId(threadId) : '') +\n    (lastMsgId ? '/' + getServerMessageId(lastMsgId) : '')\n  );\n}\n","import wrapTopicThreadAnchor from '@lib/richTextProcessor/wrapTopicThreadAnchor';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\nexport default async function wrapTopicNameButton(\n  options: {\n    lastMsgId?: number,\n    noAvatarAndLink?: boolean\n  } & Pick<Parameters<typeof wrapPeerTitle>[0], 'peerId' | 'threadId' | 'wrapOptions' | 'withIcons' | 'dialog'>\n) {\n  const {peerId, threadId, lastMsgId} = options;\n\n  const loadPromise: Promise<any> = Promise.resolve();\n  let element: HTMLElement;\n\n  if(options.noAvatarAndLink) {\n    element = document.createElement('span');\n  } else {\n    element = wrapTopicThreadAnchor({peerId, threadId, lastMsgId});\n  }\n\n  element.classList.add('topic-name', 'topic-name-button');\n  // if(threadId) {\n  //   const topic = await rootScope.managers.dialogsStorage.getForumTopic(peerId, threadId);\n  //   if(!topic) {\n  //     element.append(i18n('Loading'));\n  //     loadPromise = rootScope.managers.dialogsStorage.getForumTopicById(peerId, threadId)\n  //   }\n  // } else {\n  element.append(await wrapPeerTitle(options));\n  // }\n\n  return {\n    cached: true,\n    element,\n    loadPromise\n  };\n}\n","import wrapVideo from '@components/wrappers/video';\nimport {MediaComponentProps, MediaTsx} from '@components/wrappers/mediaTsx';\n\ntype VideoProps = Omit<Parameters<typeof wrapVideo>[0], 'middleware'>;\n\nexport default function VideoTsx(props: VideoProps & {\n  onResult?: (result: Awaited<ReturnType<typeof wrapVideo>>) => void\n} & MediaComponentProps) {\n  return (\n    <MediaTsx<VideoProps, Awaited<ReturnType<typeof wrapVideo>>>\n      {...props}\n      itemKey=\"doc\"\n      loader={wrapVideo}\n    />\n  );\n}\n","import safePlay from '@helpers/dom/safePlay';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport deepEqual from '@helpers/object/deepEqual';\nimport tsNow from '@helpers/tsNow';\n\nconst ASSETS_PATH = 'assets/audio/';\n\ntype PlayOptions<AssetMap extends Record<string, string>> = {\n  name: keyof AssetMap,\n  loop?: boolean,\n  volume?: number\n};\n\nexport default class AudioAssetPlayer<AssetMap extends Record<string, string>> {\n  private static container: HTMLElement;\n  private audio: HTMLAudioElement;\n  private tempId: number;\n  private assetName: keyof AssetMap;\n  private lastOptions: PlayOptions<AssetMap>;\n  private nextAt: number;\n\n  constructor(private assets: AssetMap) {\n    this.tempId = 0;\n\n    if(!AudioAssetPlayer.container) {\n      AudioAssetPlayer.container = document.createElement('div');\n      AudioAssetPlayer.container.id = 'audio-asset-player';\n      getOverlayRoot().append(AudioAssetPlayer.container);\n    }\n  }\n\n  public play(options: PlayOptions<AssetMap>) {\n    ++this.tempId;\n    this.assetName = options.name;\n    this.lastOptions = options;\n\n    try {\n      const audio = this.createAudio();\n      audio.autoplay = true;\n      audio.src = ASSETS_PATH + this.assets[options.name];\n      audio.loop = options.loop ?? false;\n      audio.volume = options.volume ?? 1;\n      audio.setAttribute('name', options.name as string);\n      AudioAssetPlayer.container.append(audio);\n      safePlay(audio);\n    } catch(e) {\n      console.error('playSound', name, e);\n    }\n  }\n\n  public playWithThrottle(options: PlayOptions<AssetMap>, throttle: number) {\n    const now = tsNow();\n    if(this.nextAt && now < this.nextAt && deepEqual(this.lastOptions, options)) {\n      return;\n    }\n\n    this.nextAt = now + throttle;\n    this.play(options);\n  }\n\n  public playIfDifferent(options: PlayOptions<AssetMap>) {\n    if(this.assetName !== options.name) {\n      this.play(options);\n    }\n  }\n\n  public createAudio() {\n    let {audio} = this;\n    if(audio) {\n      return audio;\n    }\n\n    audio = this.audio = new Audio();\n    safePlay(audio);\n    return audio;\n  }\n\n  public stop() {\n    if(!this.audio) {\n      return;\n    }\n\n    this.audio.pause();\n  }\n\n  public cancelDelayedPlay() {\n    ++this.tempId;\n  }\n\n  public playWithTimeout(options: PlayOptions<AssetMap>, timeout: number) {\n    // timeout = 0;\n    const tempId = ++this.tempId;\n    setTimeout(() => {\n      if(this.tempId !== tempId) {\n        return;\n      }\n\n      this.play(options);\n    }, timeout);\n  }\n}\n","import type {PushNotificationObject} from '@lib/serviceWorker/push';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport wrapMessageForReply from '@components/wrappers/messageForReply';\nimport {FontFamily} from '@config/font';\nimport {NOTIFICATION_BADGE_PATH, NOTIFICATION_ICON_PATH} from '@config/notifications';\nimport {IS_MOBILE} from '@environment/userAgent';\nimport IS_VIBRATE_SUPPORTED from '@environment/vibrateSupport';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport idleController from '@helpers/idleController';\nimport tsNow from '@helpers/tsNow';\nimport {Reaction, User} from '@layer';\nimport I18n, {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport singleInstance from '@lib/singleInstance';\nimport fixEmoji from '@lib/richTextProcessor/fixEmoji';\nimport wrapPlainText from '@lib/richTextProcessor/wrapPlainText';\nimport getMessageThreadId from '@appManagers/utils/messages/getMessageThreadId';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {logger} from '@lib/logger';\nimport LazyLoadQueueBase from '@components/lazyLoadQueueBase';\nimport webPushApiManager from '@lib/webPushApiManager';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport appImManager from '@lib/appImManager';\nimport {getCurrentAccount} from '@lib/accounts/getCurrentAccount';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport apiManagerProxy, {NotificationBuildTaskPayload, NotificationBuildStoryTaskPayload, NotificationBuildStoryReactionTaskPayload} from '@lib/apiManagerProxy';\nimport commonStateStorage from '@lib/commonStateStorage';\nimport type {ActiveAccountNumber} from '@lib/accounts/types';\nimport {createProxiedManagersForAccount, ProxiedManagers} from '@lib/getProxiedManagers';\nimport AccountController from '@lib/accounts/accountController';\nimport {createAppURLForAccount} from '@lib/accounts/createAppURLForAccount';\nimport createNotificationImage from '@helpers/createNotificationImage';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport {FOLDER_ID_ALL} from '@appManagers/constants';\nimport PasscodeLockScreenController from '@components/passcodeLock/passcodeLockScreenController';\nimport {StateSettings} from '@config/state';\nimport {useAppSettings} from '@stores/appSettings';\nimport {unwrap} from 'solid-js/store';\nimport AudioAssetPlayer from '@helpers/audioAssetPlayer';\nimport {createEffect, createRoot, on} from 'solid-js';\nimport appNavigationController from '@components/appNavigationController';\n\ntype MyNotification = Notification & {\n  hidden?: boolean,\n  show?: () => void,\n};\n\nexport type NotifyOptions = Partial<{\n  tag: string;\n  image: string;\n  key: NotificationKey;\n  title: string;\n  message: string;\n  silent: boolean;\n  onclick: () => void;\n  noIncrement: boolean;\n}>;\n\nexport type NotificationSettings = StateSettings['notifications'];\n\nconst SHOW_NOTIFICATIONS_FOR_OTHER_ACCOUNT = false;\n\n// * push loc_key prefix of a reaction to our own story ('REACT_STORY', 'REACT_STORY_HIDDEN')\nconst STORY_REACTION_LOC_KEY = 'REACT_STORY';\n\n// * cancels are fired per message, so batch them into a single storage write\nconst CANCEL_FLUSH_TIMEOUT = 100;\nconst MAX_PENDING_NOTIFICATIONS = 1000;\n\ntype Account = {managers: ProxiedManagers};\ntype NotificationKey = BroadcastEvents['notification_cancel'];\ntype PendingNotifications = Partial<Record<ActiveAccountNumber, NotificationKey[]>>;\n/** peerId -> the message id everything is read up to */\ntype CancelledRanges = Map<PeerId, number>;\n\nfunction matchesCancelledRange(key: NotificationKey, accountNumber: ActiveAccountNumber, ranges: CancelledRanges) {\n  if(!ranges) {\n    return false;\n  }\n\n  const [type, keyAccountNumber, peerId, mid] = key.split('_');\n  if(type !== 'msg' || +keyAccountNumber !== accountNumber) {\n    return false;\n  }\n\n  const maxId = ranges.get(+peerId as PeerId);\n  return maxId !== undefined && +mid <= maxId;\n}\n\nfunction wrapUserName(user: User.user) {\n  let name = user.first_name;\n  if(user.last_name) name += ' ' + user.last_name;\n\n  name = limitSymbols(name, 12, 15);\n  return wrapPlainText(name);\n}\n\nexport class UiNotificationsManager {\n  private notificationsUiSupport: boolean;\n  private notificationsShown: {[key: NotificationKey]: MyNotification | true};\n  private notificationsQueue: LazyLoadQueueBase;\n  private notificationIndex: number;\n  private soundsPlayed: {[tag: string]: number};\n  private vibrateSupport: boolean;\n\n  private faviconElements: HTMLLinkElement[];\n\n  private titleBackup: string;\n  private titleChanged: boolean;\n  private titleMiddlewareHelper: MiddlewareHelper;\n  private prevFavicon: string;\n\n  private stopped: boolean;\n\n  private cancelledKeys: Set<NotificationKey>;\n  private cancelledRanges: Map<ActiveAccountNumber, CancelledRanges>;\n  private cancelTimeout: number;\n\n  private topMessagesDeferred: CancellablePromise<void>;\n\n  private setAppBadge: (contents?: any) => Promise<void>;\n\n  private log: ReturnType<typeof logger>;\n\n  public accounts: Map<ActiveAccountNumber, Account>;\n\n  private audioAssetPlayer: AudioAssetPlayer<Record<'notification', string>>;\n\n  private appSettings: StateSettings;\n\n  private get settings() {\n    return this.appSettings.notifications;\n  }\n\n  private async getPendingNotifications(): Promise<PendingNotifications> {\n    return (await commonStateStorage.get('pendingNotifications', false)) || {};\n  }\n\n  public async getNotificationsCountForAllAccounts(): Promise<Partial<Record<ActiveAccountNumber, number>>> {\n    const pending = await this.getPendingNotifications();\n    const count: Partial<Record<ActiveAccountNumber, number>> = {};\n    for(const key in pending) {\n      const accountNumber = +key as ActiveAccountNumber;\n      count[accountNumber] = pending[accountNumber]?.length || 0;\n    }\n\n    return count;\n  }\n\n  private async getNotificationsCountForAllAccountsForTitle() {\n    const notificationsCount = await this.getNotificationsCountForAllAccounts();\n    const shouldCount = (accountNumber: ActiveAccountNumber) =>\n      accountNumber === getCurrentAccount() ||\n      (SHOW_NOTIFICATIONS_FOR_OTHER_ACCOUNT && !apiManagerProxy.hasTabOpenFor(accountNumber));\n\n    const count = Object.entries(notificationsCount).reduce(\n      (prev, [accountNumber, count]) => prev + (shouldCount(+accountNumber as ActiveAccountNumber) ? count : 0) || 0,\n      0\n    );\n\n    return count;\n  }\n\n  private async modifyPendingNotifications(\n    accountNumber: ActiveAccountNumber,\n    modify: (keys: NotificationKey[]) => NotificationKey[]\n  ) {\n    // * make it safe to call from multiple tabs\n    await navigator.locks.request('notificationsCount', async() => {\n      const pending = await this.getPendingNotifications();\n      const keys = pending[accountNumber] || [];\n\n      let newKeys = modify(keys);\n      if(newKeys.length > MAX_PENDING_NOTIFICATIONS) {\n        newKeys = newKeys.slice(newKeys.length - MAX_PENDING_NOTIFICATIONS);\n      }\n\n      if(newKeys.length === keys.length && newKeys.every((key, idx) => key === keys[idx])) {\n        return;\n      }\n\n      await commonStateStorage.set({\n        pendingNotifications: {\n          ...pending,\n          [accountNumber]: newKeys\n        }\n      });\n      rootScope.dispatchEvent('notification_count_update');\n    });\n  }\n\n  private addPendingNotification(key: NotificationKey, accountNumber: ActiveAccountNumber) {\n    return this.modifyPendingNotifications(accountNumber, (keys) => {\n      return keys.includes(key) ? keys : keys.concat(key);\n    });\n  }\n\n  private clearPendingNotifications(accountNumber: ActiveAccountNumber) {\n    return this.modifyPendingNotifications(accountNumber, () => []);\n  }\n\n  /**\n   * The count is kept in a storage shared by every tab, while the notifications themselves are only\n   * known to the tab that has shown them. Cancelling has to go through that storage too, otherwise\n   * the badge stays stuck whenever the messages are read anywhere else — another tab, another\n   * client, or this very tab before a reload.\n   */\n  private queueNotificationCancel(key: NotificationKey) {\n    this.cancelledKeys.add(key);\n    this.scheduleNotificationCancelFlush();\n  }\n\n  private queueNotificationCancelUpTo({accountNumber, peerId, maxId}: BroadcastEvents['notification_cancel_up_to']) {\n    let ranges = this.cancelledRanges.get(accountNumber);\n    if(!ranges) {\n      this.cancelledRanges.set(accountNumber, ranges = new Map());\n    }\n\n    ranges.set(peerId, Math.max(ranges.get(peerId) || 0, maxId));\n    this.scheduleNotificationCancelFlush();\n  }\n\n  private scheduleNotificationCancelFlush() {\n    if(this.cancelTimeout !== undefined) {\n      return;\n    }\n\n    this.cancelTimeout = window.setTimeout(this.flushNotificationCancels, CANCEL_FLUSH_TIMEOUT);\n  }\n\n  private flushNotificationCancels = () => {\n    this.cancelTimeout = undefined;\n\n    const keys = this.cancelledKeys;\n    const ranges = this.cancelledRanges;\n    this.cancelledKeys = new Set();\n    this.cancelledRanges = new Map();\n\n    const accountNumbers = new Set<ActiveAccountNumber>(ranges.keys());\n    for(const key of keys) {\n      const accountNumber = +key.split('_')[1] as ActiveAccountNumber;\n      if(accountNumber) {\n        accountNumbers.add(accountNumber);\n      }\n    }\n\n    for(const accountNumber of accountNumbers) {\n      const peerRanges = ranges.get(accountNumber);\n      this.modifyPendingNotifications(accountNumber, (pendingKeys) => pendingKeys.filter((key) => {\n        return !keys.has(key) && !matchesCancelledRange(key, accountNumber, peerRanges);\n      }));\n    }\n  };\n\n  construct() {\n    this.notificationsUiSupport = ('Notification' in window) || ('mozNotification' in navigator);\n    this.notificationsShown = {};\n    this.notificationsQueue = new LazyLoadQueueBase(1);\n    this.notificationIndex = 0;\n    this.soundsPlayed = {};\n    this.vibrateSupport = IS_VIBRATE_SUPPORTED;\n\n    this.faviconElements = Array.from(document.head.querySelectorAll<HTMLLinkElement>('link[rel=\"icon\"], link[rel=\"alternate icon\"]'));\n\n    this.titleBackup = document.title;\n    this.titleChanged = false;\n    this.titleMiddlewareHelper = getMiddleware();\n\n    this.stopped = true;\n\n    this.cancelledKeys = new Set();\n    this.cancelledRanges = new Map();\n\n    this.topMessagesDeferred = deferredPromise<void>();\n\n    this.setAppBadge = (navigator as any).setAppBadge?.bind(navigator);\n    this.setAppBadge?.(0);\n\n    this.log = logger('NOTIFICATIONS');\n\n    this.accounts = new Map();\n\n    this.audioAssetPlayer = new AudioAssetPlayer({\n      notification: 'notification.mp3'\n    });\n\n    this.appSettings = useAppSettings()[0];\n\n    // * set listeners\n\n    rootScope.addEventListener('settings_updated', this.updateLocalSettings);\n\n    rootScope.addEventListener('notification_reset', (peerString) => {\n      this.soundReset(peerString);\n    });\n\n    rootScope.addEventListener('notification_cancel', (str) => {\n      this.cancel(str);\n    });\n\n    rootScope.addEventListener('notification_cancel_up_to', (payload) => {\n      const {accountNumber, peerId, maxId} = payload;\n      const ranges: CancelledRanges = new Map([[peerId, maxId]]);\n      for(const key in this.notificationsShown) {\n        if(matchesCancelledRange(key as NotificationKey, accountNumber, ranges)) {\n          this.cancel(key as NotificationKey);\n        }\n      }\n\n      this.queueNotificationCancelUpTo(payload);\n    });\n\n    if(this.setAppBadge) {\n      rootScope.addEventListener('folder_unread', (folder) => {\n        if(folder.id === FOLDER_ID_ALL) {\n          this.setAppBadge(folder.unreadUnmutedPeerIds.size);\n        }\n      });\n    }\n\n    createRoot((dispose) => {\n      createEffect(on(() => this.settings.push, this.onPushConditionsChange));\n    });\n\n    rootScope.addEventListener('dialogs_multiupdate', () => {\n      // unregisterTopMsgs()\n      this.topMessagesDeferred.resolve();\n    }, {once: true});\n\n    webPushApiManager.addEventListener('push_notification_click', async(notificationData) => {\n      if(notificationData.p) { // * decrypt push notification\n        notificationData = await apiManagerProxy.pushSingleManager.decryptPush(notificationData.p, notificationData.keyIdBase64);\n        notificationData = await apiManagerProxy.serviceMessagePort.invoke('fillPushObject', notificationData);\n      }\n\n      if(notificationData.action === 'push_settings') {\n        /* this.topMessagesDeferred.then(() => {\n          $modal.open({\n            templateUrl: templateUrl('settings_modal'),\n            controller: 'SettingsModalController',\n            windowClass: 'settings_modal_window mobile_modal',\n            backdrop: 'single'\n          })\n        }); */\n        return;\n      }\n\n      // * can be undefined if push is decrypted here\n      if(\n        notificationData.accountNumber !== undefined &&\n        notificationData.accountNumber !== getCurrentAccount()\n      ) {\n        return;\n      }\n\n      const {custom} = notificationData;\n      // * a reaction to OUR story ('REACT_STORY' / 'REACT_STORY_HIDDEN'): the story is ours,\n      // * the push peer is whoever reacted — so this must NOT be routed by peer\n      const isStoryReaction = !!notificationData.loc_key?.startsWith(STORY_REACTION_LOC_KEY);\n\n      const peerId = custom && custom.peerId.toPeerId();\n      if(!peerId && !isStoryReaction) {\n        return;\n      }\n\n      this.topMessagesDeferred.then(async() => {\n        const managers = rootScope.managers;\n\n        if(isStoryReaction) {\n          // * the server sends the story id as msg_id, our own notification as story_id\n          const storyId = +(custom?.story_id || custom?.msg_id) || undefined;\n          const self = await managers.appUsersManager.getSelf();\n          appImManager.openStoriesForPeer(self.id.toPeerId(), storyId);\n          return;\n        }\n\n        const chatId = peerId.isAnyChat() ? peerId.toChatId() : undefined;\n        let channelId: ChatId;\n        if(chatId) {\n          if(!(await managers.appChatsManager.hasChat(chatId))) {\n            return;\n          }\n\n          channelId = await managers.appChatsManager.isChannel(chatId) ? chatId : undefined;\n        }\n\n        if(!chatId && !(await managers.appUsersManager.hasUser(peerId.toUserId()))) {\n          return;\n        }\n\n        if(custom.story_id) {\n          appImManager.openStoriesForPeer(peerId);\n          return;\n        }\n\n        const lastMsgId = await managers.appMessagesIdsManager.generateMessageId(+custom.msg_id, channelId);\n\n        appImManager.setInnerPeer({\n          peerId,\n          lastMsgId\n        });\n      });\n    });\n  }\n\n  public onPushConditionsChange = async() => {\n    const needPush = this.settings.push &&\n      webPushApiManager.isAvailable &&\n      Notification.permission === 'granted';\n\n    let tokenData = await webPushApiManager.getSubscription();\n    if(needPush) {\n      tokenData ||= await webPushApiManager.subscribe();\n      if(tokenData) {\n        apiManagerProxy.pushSingleManager.registerDevice(tokenData);\n      }\n    } else if(tokenData) {\n      webPushApiManager.unsubscribe();\n      apiManagerProxy.pushSingleManager.unregisterDevice(tokenData);\n    }\n  };\n\n  public async buildNotificationQueue(options: Parameters<UiNotificationsManager['buildNotification']>[0]) {\n    this.notificationsQueue.push({\n      load: () => this.buildNotification(options)\n    });\n  }\n\n  public async buildNotification(payload: NotificationBuildTaskPayload) {\n    if('story' in payload) {\n      return this.buildStoryNotification(payload);\n    }\n\n    if('storyReaction' in payload) {\n      return this.buildStoryReactionNotification(payload);\n    }\n\n    const {\n      fwdCount,\n      peerReaction,\n      peerTypeNotifySettings,\n      isOtherTabActive,\n      accountNumber\n    } = payload;\n    let {message} = payload;\n    const peerId = message.peerId;\n    const isAnyChat = peerId.isAnyChat();\n    const notification: NotifyOptions = {};\n    const account = this.accounts.get(accountNumber);\n    const [peerString, isForum = false] = await Promise.all([\n      account.managers.appPeersManager.getPeerString(peerId),\n      isAnyChat && account.managers.appPeersManager.isForum(peerId)\n    ]);\n    let notificationMessage: string;\n    let wrappedMessage = false;\n\n    const isLocked = PasscodeLockScreenController.getIsLocked();\n\n    if(peerTypeNotifySettings.show_previews && !isLocked) {\n      if(message._ === 'message' && message.fwd_from && fwdCount > 1) {\n        notificationMessage = I18n.format('Notifications.Forwarded', true, [fwdCount]);\n      } else {\n        notificationMessage = await wrapMessageForReply({message, plain: true, managers: account.managers});\n\n        const emoticon = await this.getReactionEmoticon(account.managers, peerReaction?.reaction);\n        if(emoticon) {\n          const langPackKey: LangPackKey = /* isAnyChat ? 'Notification.Group.Reacted' :  */'Notification.Contact.Reacted';\n          const args: FormatterArguments = [\n            fixEmoji(emoticon), // can be plain heart\n            notificationMessage\n          ];\n\n          /* if(isAnyChat) {\n            args.unshift(appPeersManager.getPeerTitle(message.fromId, true));\n          } */\n\n          notificationMessage = I18n.format(langPackKey, true, args);\n        } else {\n          wrappedMessage = true;\n        }\n      }\n    } else {\n      notificationMessage = I18n.format('Notifications.New', true);\n    }\n\n    if(peerReaction) {\n      notification.noIncrement = true;\n    }\n\n    const peerTitleOptions/* : Partial<Parameters<typeof getPeerTitle>[0]> */ = {\n      plainText: true as const,\n      managers: account.managers\n    };\n\n    const threadId = isForum ? getMessageThreadId(message, {isForum}) : undefined;\n    const notificationFromPeerId = peerReaction ? getPeerId(peerReaction.peer_id) : message.fromId;\n    const peerTitle = notification.title = await getPeerTitle({...peerTitleOptions, peerId, threadId: threadId, managers: account.managers, useManagers: true});\n    if(isForum) {\n      const peerTitle = await getPeerTitle({...peerTitleOptions, peerId});\n      notification.title += ` (${peerTitle})`;\n\n      if(wrappedMessage && notificationFromPeerId !== message.peerId) {\n        notificationMessage = await getPeerTitle({...peerTitleOptions, peerId: notificationFromPeerId, managers: account.managers, useManagers: true}) +\n          ': ' + notificationMessage;\n      }\n    } else if(isAnyChat && notificationFromPeerId !== message.peerId) {\n      notification.title = await getPeerTitle({...peerTitleOptions, peerId: notificationFromPeerId, managers: account.managers, useManagers: true}) +\n        ' @ ' +\n        notification.title;\n    }\n\n    const isDifferentAccount = accountNumber !== getCurrentAccount();\n\n    notification.onclick = () => {\n      if(isDifferentAccount) {\n        const url = createAppURLForAccount(accountNumber, {\n          p: '' + peerId,\n          message: '' + (message.mid || ''),\n          thread: '' + (threadId || '')\n        });\n\n        window.open(url, '_blank');\n      } else {\n        appImManager.setInnerPeer({peerId, lastMsgId: message.mid, threadId});\n      }\n    };\n\n    notification.message = notificationMessage;\n    notification.key = `msg_${accountNumber}_${message.peerId}_${message.mid}`;\n\n    if(!peerReaction) { // ! WARNING, message can be already read\n      message = await account.managers.appMessagesManager.getMessageByPeer(message.peerId, message.mid);\n      if(!message || !message.pFlags.unread) return;\n    }\n\n    const result = await this.finishNotification({\n      notification,\n      account,\n      accountNumber,\n      isDifferentAccount,\n      isOtherTabActive,\n      peerId,\n      peerString,\n      peerTitle,\n      hideContent: isLocked,\n      custom: {\n        msg_id: '' + message.mid,\n        peerId: '' + peerId\n      }\n    });\n\n    if(result && await apiManagerProxy.pushSingleManager.isRegistered()) {\n      webPushApiManager.ignorePushByMid(peerId, message.mid);\n    }\n  }\n\n  private async buildStoryNotification({\n    story: {peerId, storyId},\n    accountNumber,\n    isOtherTabActive\n  }: NotificationBuildStoryTaskPayload) {\n    const account = this.accounts.get(accountNumber);\n    if(!account) {\n      return;\n    }\n\n    const {peerString, peerTitle} = await this.getNotificationPeer(account, peerId);\n    const isDifferentAccount = accountNumber !== getCurrentAccount();\n\n    return this.finishNotification({\n      notification: {\n        title: peerTitle,\n        message: I18n.format('Story.Notification', true),\n        key: `story_${accountNumber}_${peerId}_${storyId}`,\n        // * stories shouldn't play the notification sound nor bump the tab-title counter\n        noIncrement: true,\n        onclick: () => {\n          if(isDifferentAccount) {\n            const url = createAppURLForAccount(accountNumber, {p: '' + peerId, story: '1'});\n            window.open(url, '_blank');\n          } else {\n            appImManager.openStoriesForPeer(peerId);\n          }\n        }\n      },\n      account,\n      accountNumber,\n      isDifferentAccount,\n      isOtherTabActive,\n      peerId,\n      peerString,\n      peerTitle,\n      hideContent: PasscodeLockScreenController.getIsLocked(),\n      custom: {\n        msg_id: '0',\n        story_id: '' + storyId,\n        peerId: '' + peerId\n      }\n    });\n  }\n\n  private async buildStoryReactionNotification({\n    storyReaction: {peerId, storyId, reaction, showPreview},\n    accountNumber,\n    isOtherTabActive\n  }: NotificationBuildStoryReactionTaskPayload) {\n    const account = this.accounts.get(accountNumber);\n    if(!account) {\n      return;\n    }\n\n    const [{peerString, peerTitle}, emoticon, self] = await Promise.all([\n      this.getNotificationPeer(account, peerId),\n      this.getReactionEmoticon(account.managers, reaction),\n      account.managers.appUsersManager.getSelf()\n    ]);\n\n    // * without a preview the notification must not tell who reacted with what\n    const hideContent = !showPreview || !emoticon || PasscodeLockScreenController.getIsLocked();\n    const selfPeerId = self.id.toPeerId();\n    const isDifferentAccount = accountNumber !== getCurrentAccount();\n\n    return this.finishNotification({\n      notification: {\n        title: hideContent ? I18n.format('Story.Notification.ReactedHiddenSender', true) : peerTitle,\n        message: hideContent ?\n          I18n.format('Story.Notification.ReactedHidden', true) :\n          I18n.format('Story.Notification.Reacted', true, [fixEmoji(emoticon)]),\n        key: `storyReaction_${accountNumber}_${peerId}_${storyId}`,\n        // * reactions shouldn't play the notification sound nor bump the tab-title counter\n        noIncrement: true,\n        // * open our own story that was reacted to, as the mobile clients do\n        onclick: () => {\n          if(isDifferentAccount) {\n            const url = createAppURLForAccount(accountNumber, {\n              p: '' + selfPeerId,\n              story: '1',\n              story_id: '' + storyId\n            });\n            window.open(url, '_blank');\n          } else {\n            appImManager.openStoriesForPeer(selfPeerId, storyId);\n          }\n        }\n      },\n      account,\n      accountNumber,\n      isDifferentAccount,\n      isOtherTabActive,\n      peerId,\n      peerString,\n      peerTitle,\n      hideContent,\n      self,\n      locKey: STORY_REACTION_LOC_KEY,\n      custom: {\n        msg_id: '0',\n        story_id: '' + storyId,\n        peerId: '' + selfPeerId\n      }\n    });\n  }\n\n  // * the peer a notification is attributed to: its title is (part of) the notification\n  // * title, its avatar is the image and its string is the tag notifications collapse by\n  private async getNotificationPeer(account: Account, peerId: PeerId) {\n    const [peerString, peerTitle] = await Promise.all([\n      account.managers.appPeersManager.getPeerString(peerId),\n      getPeerTitle({peerId, plainText: true, managers: account.managers, useManagers: true})\n    ]);\n\n    return {peerString, peerTitle};\n  }\n\n  /**\n   * Shared tail of every builder: the other-account title suffix, the peer's avatar, the\n   * passcode-lock override and the push payload boilerplate.\n   */\n  private async finishNotification({\n    notification,\n    account,\n    accountNumber,\n    isDifferentAccount,\n    isOtherTabActive,\n    peerId,\n    peerString,\n    peerTitle,\n    hideContent,\n    self,\n    custom,\n    locKey\n  }: {\n    notification: NotifyOptions,\n    account: Account,\n    accountNumber: ActiveAccountNumber,\n    isDifferentAccount: boolean,\n    isOtherTabActive: boolean,\n    peerId: PeerId,\n    peerString: string,\n    peerTitle: string,\n    /** don't reveal who it's from nor what it says: passcode lock, or previews turned off */\n    hideContent?: boolean,\n    /** pass it when already resolved, otherwise it's fetched only when the suffix is needed */\n    self?: User.user,\n    custom: PushNotificationObject['custom'],\n    /** the server's loc_key this notification stands in for, so a click routes the same way */\n    locKey?: string\n  }) {\n    const hasMoreThanOneAccount = (await AccountController.getTotalAccounts()) > 1;\n    if((hasMoreThanOneAccount && isOtherTabActive) || isDifferentAccount) {\n      // ' ➜ '\n      notification.title += ' ➜ ' + wrapUserName(self ?? await account.managers.appUsersManager.getSelf());\n    }\n\n    notification.title = wrapPlainText(notification.title);\n    notification.tag = peerString;\n    notification.silent = true;// message.pFlags.silent || false;\n\n    if(!hideContent) {\n      notification.image = await createNotificationImage(account.managers, peerId, peerTitle);\n    }\n\n    if(PasscodeLockScreenController.getIsLocked()) {\n      notification.title = I18n.format('PasscodeLock.NotificationTitle', true);\n      notification.message = I18n.format('PasscodeLock.NotificationDescription', true);\n    }\n\n    return this.notify(notification, {\n      custom,\n      // * only routing matters here: the service-worker fallback reads it back on click\n      loc_key: locKey || '',\n      description: '',\n      loc_args: [],\n      mute: '',\n      random_id: 0,\n      title: '',\n      accountNumber\n    });\n  }\n\n  private async getReactionEmoticon(managers: ProxiedManagers, reaction: Reaction) {\n    if(reaction?._ === 'reactionEmoji') {\n      return reaction.emoticon;\n    }\n\n    if(reaction?._ === 'reactionCustomEmoji') {\n      const doc = await managers.appEmojiManager.getCustomEmojiDocument(reaction.document_id);\n      return doc?.stickerEmojiRaw;\n    }\n  }\n\n  private constructAndStartNotificationManagerFor(accountNumber: ActiveAccountNumber) {\n    if(this.accounts.has(accountNumber)) {\n      return;\n    }\n\n    const account: Account = {\n      managers: createProxiedManagersForAccount(accountNumber)\n    };\n    this.accounts.set(accountNumber, account);\n    account.managers.apiUpdatesManager.attach();\n  }\n\n  public constructAndStartAll() {\n    this.construct();\n\n    rootScope.addEventListener('account_logged_in', ({accountNumber}) => {\n      this.constructAndStartNotificationManagerFor(accountNumber);\n    });\n\n    singleInstance.addEventListener('deactivated', () => {\n      this.stop();\n    });\n\n    singleInstance.addEventListener('activated', () => {\n      if(this.stopped) {\n        this.start();\n      }\n    });\n\n    idleController.addEventListener('change', (idle) => {\n      if(this.stopped) {\n        return;\n      }\n\n      if(!idle) {\n        for(const accountNumber of this.accounts.keys()) {\n          if(\n            (SHOW_NOTIFICATIONS_FOR_OTHER_ACCOUNT && !apiManagerProxy.hasTabOpenFor(accountNumber)) ||\n            accountNumber === getCurrentAccount()\n          ) {\n            this.clear(accountNumber);\n          }\n        }\n      }\n\n      this.toggleToggler();\n    });\n\n    // *\n\n    this.start();\n    this.log('start');\n\n    this.updateLocalSettings();\n    rootScope.managers.appStateManager.getState().then(() => {\n      if(this.stopped) {\n        return;\n      }\n\n      webPushApiManager.start();\n    });\n\n    if(!this.notificationsUiSupport) {\n      return false;\n    }\n\n    // if('Notification' in window && Notification.permission !== 'granted' && Notification.permission !== 'denied') {\n    //   window.addEventListener('click', this.requestPermission);\n    // }\n\n    try {\n      if('onbeforeunload' in window) {\n        window.addEventListener('beforeunload', () => this.clear(getCurrentAccount()));\n      }\n    } catch(e) {}\n  }\n\n  public async start() {\n    if(!this.stopped) {\n      return;\n    }\n\n    this.stopped = false;\n\n    const totalAccounts = await AccountController.getTotalAccounts();\n    for(let i = 1; i <= totalAccounts; i++) {\n      const accountNumber = i as ActiveAccountNumber;\n      this.constructAndStartNotificationManagerFor(accountNumber);\n    }\n\n    this.clearPendingNotifications(getCurrentAccount());\n  }\n\n  private onTitleInterval = async() => {\n    const middleware = this.titleMiddlewareHelper.get();\n    const count = await this.getNotificationsCountForAllAccountsForTitle();\n    if(!middleware()) return;\n\n    const titleChanged = this.titleChanged;\n    if(titleChanged) {\n      this.resetTitle(true);\n    }\n\n    if(!count || titleChanged) {\n      return;\n    }\n\n    this.titleChanged = true;\n    document.title = I18n.format('Notifications.Count', true, [count]);\n    // this.setFavicon('assets/img/favicon_unread.ico');\n\n    // fetch('assets/img/favicon.ico')\n    // .then((res) => res.blob())\n    // .then((blob) => {\n    // const img = document.createElement('img');\n    // img.src = URL.createObjectURL(blob);\n\n    const canvas = document.createElement('canvas');\n    canvas.width = 32 * window.devicePixelRatio;\n    canvas.height = canvas.width;\n\n    const ctx = canvas.getContext('2d');\n    ctx.beginPath();\n    ctx.arc(canvas.width / 2, canvas.height / 2, canvas.width / 2, 0, 2 * Math.PI, false);\n    ctx.fillStyle = '#3390ec';\n    ctx.fill();\n\n    let fontSize = 24;\n    let str = '' + count;\n    if(count < 10) {\n      fontSize = 22;\n    } else if(count < 100) {\n      fontSize = 20;\n    } else {\n      str = '99+';\n      fontSize = 16;\n    }\n\n    fontSize *= window.devicePixelRatio;\n\n    ctx.font = `700 ${fontSize}px ${FontFamily}`;\n    ctx.textBaseline = 'middle';\n    ctx.textAlign = 'center';\n    ctx.fillStyle = 'white';\n    ctx.fillText(str, canvas.width / 2, canvas.height * .5625);\n\n    /* const ctx = canvas.getContext('2d');\n      ctx.drawImage(img, 0, 0, canvas.width, canvas.height); */\n\n    this.setFavicon(canvas.toDataURL());\n    // });\n  };\n\n  private resetTitle(isBlink?: boolean) {\n    if(!this.titleChanged) {\n      return;\n    }\n\n    this.titleChanged = false;\n    document.title = this.titleBackup;\n    this.setFavicon();\n  }\n\n  private async toggleToggler(enable = idleController.isIdle) {\n    if(IS_MOBILE) return;\n\n    this.titleMiddlewareHelper.clean();\n    const middleware = this.titleMiddlewareHelper.get();\n\n    if(!enable) {\n      this.resetTitle();\n    } else {\n      const titleInterval = await apiManagerProxy.setInterval(this.onTitleInterval, 1000);\n      middleware.onClean(() => {\n        apiManagerProxy.clearInterval(titleInterval);\n      });\n    }\n  }\n\n  private setFavicon(href?: string) {\n    if(this.prevFavicon === href) {\n      return;\n    }\n\n    this.prevFavicon = href;\n    this.faviconElements.forEach((element, idx, arr) => {\n      const link = element.cloneNode() as HTMLLinkElement;\n      link.dataset.href ||= link.href;\n      link.href = href ?? link.dataset.href;\n      element.replaceWith(arr[idx] = link);\n    });\n  }\n\n  public async notify(data: NotifyOptions, pushData: PushNotificationObject) {\n    this.log('notify', data, idleController.isIdle, this.notificationsUiSupport, this.stopped);\n\n    if(this.stopped) {\n      return;\n    }\n\n    data.image ||= NOTIFICATION_ICON_PATH;\n\n    const idx = ++this.notificationIndex;\n    const key = data.key || 'k' + idx as NotificationKey;\n    this.notificationsShown[key] = true;\n\n    if(!data.noIncrement) {\n      this.addPendingNotification(key, pushData.accountNumber);\n    }\n\n    this.toggleToggler();\n\n    const now = tsNow();\n    if(this.settings.volume > 0 && this.settings.sound && !data.noIncrement) {\n      this.testSound(this.settings.volume);\n      this.soundsPlayed[data.tag] = now;\n    }\n\n    if(!this.notificationsUiSupport ||\n      'Notification' in window && Notification.permission !== 'granted') {\n      return;\n    }\n\n    if(!this.settings.desktop) {\n      if(this.vibrateSupport && !this.settings.novibrate) {\n        navigator.vibrate([200, 100, 200]);\n        return;\n      }\n\n      return;\n    }\n\n    if(!('Notification' in window)) {\n      return;\n    }\n\n    let notification: MyNotification;\n\n    const notificationOptions: NotificationOptions = {\n      badge: NOTIFICATION_BADGE_PATH,\n      icon: data.image || '',\n      body: data.message || '',\n      tag: data.tag || '',\n      silent: data.silent || false,\n      data: pushData\n    };\n\n    try {\n      if(data.tag) {\n        for(const key in this.notificationsShown) {\n          const notification = this.notificationsShown[key as NotificationKey];\n          if(typeof(notification) !== 'boolean' && notification.tag === data.tag) {\n            notification.hidden = true;\n          }\n        }\n      }\n\n      // throw new Error('test');\n      notification = new Notification(data.title, notificationOptions);\n    } catch(e) {\n      try {\n        const registration = await navigator.serviceWorker.ready;\n        await registration.showNotification(data.title, notificationOptions);\n        const notifications = await registration.getNotifications({tag: notificationOptions.tag});\n        notification = notifications[notifications.length - 1];\n      } catch(err) {\n        this.log.error('creating push error', err, data, notificationOptions);\n      }\n\n      if(!notification) {\n        this.notificationsUiSupport = false;\n        webPushApiManager.setLocalNotificationsDisabled();\n        return;\n      }\n    }\n\n    notification.onclick = () => {\n      this.log('notification onclick');\n      notification.close();\n      appNavigationController.focus();\n      this.clear(pushData.accountNumber);\n      data.onclick?.();\n    };\n\n    notification.onclose = () => {\n      this.log('notification onclose');\n      if(!notification.hidden) {\n        delete this.notificationsShown[key];\n        this.clear(pushData.accountNumber);\n      }\n    };\n\n    notification.show?.();\n    this.notificationsShown[key] = notification;\n\n    if(!IS_MOBILE) {\n      setTimeout(() => {\n        this.hide(key);\n      }, 8000);\n    }\n\n    return true;\n  }\n\n  public updateLocalSettings = async() => {\n    webPushApiManager.setSettings(unwrap(this.settings));\n  };\n\n  public getLocalSettings() {\n    return this.settings;\n  }\n\n  private hide(key: NotificationKey) {\n    const notification = this.notificationsShown[key];\n    if(notification) {\n      this.closeNotification(notification);\n    }\n  }\n\n  public soundReset(tag: string) {\n    delete this.soundsPlayed[tag];\n  }\n\n  // private requestPermission = () => {\n  //   Notification.requestPermission();\n  //   window.removeEventListener('click', this.requestPermission);\n  // };\n\n  public testSound(volume: number) {\n    this.audioAssetPlayer.playWithThrottle({name: 'notification', volume}, 1000);\n  }\n\n  public async cancel(key: NotificationKey) {\n    const notification = this.notificationsShown[key];\n    this.log('cancel', key, notification);\n    if(notification) {\n      this.closeNotification(notification);\n      delete this.notificationsShown[key];\n    }\n\n    this.queueNotificationCancel(key);\n  }\n\n  private closeNotification(notification: boolean | MyNotification) {\n    try {\n      if(typeof(notification) !== 'boolean' && notification.close) {\n        this.log('close notification', notification);\n        notification.hidden = true;\n        notification.close();\n      }\n    } catch(e) {}\n  }\n\n  public clear = (accountNumber: ActiveAccountNumber) => {\n    this.log.warn('clear');\n\n    for(const key in this.notificationsShown) {\n      const notification = this.notificationsShown[key as NotificationKey];\n      this.closeNotification(notification);\n    }\n\n    this.notificationsShown = {};\n    this.clearPendingNotifications(accountNumber);\n\n    webPushApiManager.hidePushNotifications();\n  };\n\n  private stop() {\n    if(this.stopped) {\n      return;\n    }\n\n    this.log('stop');\n\n    for(const accountNumber of this.accounts.keys()) {\n      this.clear(accountNumber);\n    }\n\n    this.titleMiddlewareHelper.clean();\n    this.setFavicon();\n    this.stopped = true;\n  }\n}\n\nconst uiNotificationsManager = new UiNotificationsManager();\nexport default uiNotificationsManager;\n","import {ParentProps} from 'solid-js';\n\nimport AppMediaViewer, {onMediaCaptionClick} from '@components/mediaViewer';\nimport AppMediaViewerStatic from '@components/mediaViewer/static';\nimport {AutonomousMonoforumThreadList} from '@components/autonomousDialogList/monoforumThreads';\nimport {avatarNew, AvatarNewTsx, StoriesSegments} from '@components/avatarNew';\nimport BusinessHours from '@components/businessHours';\nimport ButtonMenu, {ButtonMenuSync} from '@components/buttonMenu';\nimport {ChatType} from '@components/chat/chatType';\nimport PaidMessagesInterceptor from '@components/chat/paidMessagesInterceptor';\nimport {pickLanguage} from '@components/chat/translation';\nimport CommunityLinkSection from '@components/communities/communityLinkSection';\nimport confirmationPopup from '@components/confirmationPopup';\nimport createEmojiDropdownButton, {useEmojiDropdown} from '@components/emojiDropdownButton';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport EmoticonsSearch from '@components/emoticonsDropdown/search';\nimport EmojiTab from '@components/emoticonsDropdown/tabs/emoji';\nimport {InputFieldTsx} from '@components/inputFieldTsx';\nimport PasswordMonkey from '@components/monkeys/password';\nimport PasswordInputField from '@components/passwordInputField';\nimport PeerProfileAvatars from '@components/peerProfileAvatars';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport PopupElement from '@components/popups';\nimport showBirthdayPopup, {saveMyBirthday} from '@components/popups/birthday';\nimport {useStickersDropdown} from '@components/popups/createPoll/stickersDropdown';\nimport showLimitPopup from '@components/popups/limit';\nimport showMyQrCodePopup from '@components/popups/myQrCode';\nimport {showSharingPickerPopup} from '@components/popups/pickUser';\nimport PopupPremium from '@components/popups/premium';\nimport PopupSendGift from '@components/popups/sendGift';\nimport showStarsRatingPopup from '@components/popups/starsRating';\nimport PopupToggleReadDate from '@components/popups/toggleReadDate';\nimport {setQuizHint} from '@components/quizHint';\nimport Row from '@components/rowTsx';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport appSidebarRight from '@components/sidebarRight';\nimport AppPollResultsTab from '@components/sidebarRight/tabs/pollResults';\nimport Slideshow from '@components/slideshow';\nimport {AppChatFoldersTab, AppEditFolderTab} from '@components/solidJsTabs/tabs';\nimport {StoriesProvider, useStories} from '@components/stories/store';\nimport {hideToast, toast, toastNew} from '@components/toast';\nimport {TranslatableMessageTsx} from '@components/translatableMessage';\nimport {wrapAdaptiveCustomEmoji} from '@components/wrappers/customEmojiSimple';\nimport DocumentTsx from '@components/wrappers/documentTsx';\nimport wrapFolderTitle from '@components/wrappers/folderTitle';\nimport wrapGeo from '@components/wrappers/geo';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport {wrapTopicIcon} from '@components/wrappers/messageActionTextNewUnsafe';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport wrapPhoto from '@components/wrappers/photo';\nimport PhotoTsx from '@components/wrappers/photoTsx';\nimport wrapReply from '@components/wrappers/reply';\nimport wrapSticker from '@components/wrappers/sticker';\nimport wrapStickerSetThumb from '@components/wrappers/stickerSetThumb';\nimport wrapTopicNameButton from '@components/wrappers/topicNameButton';\nimport VideoTsx from '@components/wrappers/videoTsx';\nimport {formatDate} from '@helpers/date';\nimport {getFileAndOpenEditor} from '@helpers/getFileAndOpenEditor';\nimport themeController from '@helpers/themeController';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport appImManager from '@lib/appImManager';\nimport I18n, {i18n, join} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport rootScope from '@lib/rootScope';\nimport {SolidJSHotReloadGuardContext} from '@lib/solidjs/hotReloadGuard';\nimport uiNotificationsManager from '@lib/uiNotificationsManager';\nimport {useAppSettings} from '@stores/appSettings';\nimport {useAppConfig} from '@stores/appState';\nimport usePremium from '@stores/premium';\n\n\nexport default function SolidJSHotReloadGuardProvider(props: ParentProps) {\n  return (\n    <SolidJSHotReloadGuardContext.Provider value={{\n      HotReloadGuard: SolidJSHotReloadGuardProvider,\n      rootScope,\n      appSidebarLeft,\n      AppEditFolderTab,\n      AppChatFoldersTab,\n      EmoticonsSearch,\n      wrapStickerSetThumb,\n      showLimitPopup,\n      lottieLoader,\n      themeController,\n      appImManager,\n      apiManagerProxy,\n      setQuizHint,\n      InputFieldTsx,\n      PasswordInputField,\n      PasswordMonkey,\n      PopupPremium,\n      EmoticonsDropdown,\n      EmojiTab,\n      appDialogsManager,\n      AutonomousMonoforumThreadList,\n      uiNotificationsManager,\n      I18n,\n      i18n,\n      join,\n      PopupElement,\n      PopupToggleReadDate,\n      wrapSticker,\n      wrapTopicNameButton,\n      wrapRichText,\n      getPeerTitle,\n      wrapPeerTitle,\n      wrapPhoto,\n      wrapEmojiText,\n      wrapGeo,\n      wrapAdaptiveCustomEmoji,\n      confirmationPopup,\n      PeerProfileAvatars,\n      showStarsRatingPopup,\n      toast,\n      toastNew,\n      BusinessHours,\n      avatarNew,\n      PeerTitleTsx,\n      PopupSendGift,\n      showBirthdayPopup,\n      saveMyBirthday,\n      showMyQrCodePopup,\n      useAppSettings,\n      ChatType,\n      wrapReply,\n      wrapTopicIcon,\n      VideoTsx,\n      Row,\n      PhotoTsx,\n      DocumentTsx,\n      Slideshow,\n      AppMediaViewer,\n      onMediaCaptionClick,\n      formatDate,\n      hideToast,\n      wrapFolderTitle,\n      ButtonMenu,\n      ButtonMenuSync,\n      StoriesProvider,\n      useStories,\n      StoriesSegments,\n      appSidebarRight,\n      createEmojiDropdownButton,\n      useEmojiDropdown,\n      useStickersDropdown,\n      getFileAndOpenEditor,\n      AvatarNewTsx,\n      AppMediaViewerStatic,\n      AppPollResultsTab,\n      TranslatableMessageTsx,\n      useAppConfig,\n      usePremium,\n      pickLanguage,\n      usePeerTranslation,\n      showSharingPickerPopup,\n      PaidMessagesInterceptor,\n      CommunityLinkSection\n    }}>\n      {props.children}\n    </SolidJSHotReloadGuardContext.Provider>\n  );\n}\n","import {render} from 'solid-js/web';\nimport SidebarSlider, {SliderSuperTab} from '@components/slider';\nimport rootScope from '@lib/rootScope';\nimport AppSearchSuper, {SearchSuperMediaType} from '@components/appSearchSuper';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {PromiseCollector} from '@components/solidJsTabs/promiseCollector';\nimport {SuperTabProvider} from '@components/solidJsTabs/superTabProvider';\n\nexport type SharedMediaImpl = {\n  setQuery: () => void;\n  fillProfileElements: () => Promise<() => void>;\n  loadSidebarMedia: (single: boolean, justLoad?: boolean) => Promise<any>;\n  setSearchTab: (type: SearchSuperMediaType) => void;\n  setLoadMutex: (promise: Promise<any>) => void;\n};\n\n/**\n * sharedMedia is a stateful per-chat controller, not a payload-rendered tab: its\n * setPeer/fillProfileElements/etc. are called (sometimes synchronously, before\n * open) by chat.ts and others. So this thin class owns the public API + state and\n * bridges to the heavy, dynamically-imported (HMR) Solid component which attaches\n * `_impl` and builds the UI. The only sync-critical op (setQuery) is deferred to\n * the first render; everything else either runs immediately once `_impl` exists\n * or awaits the render.\n */\nexport default class AppSharedMediaTab extends SliderSuperTab {\n  public peerId: PeerId;\n  public threadId: number;\n  public isFirst: boolean;\n  public noProfile: boolean;\n  public peerChanged: boolean;\n  public searchSuper: AppSearchSuper;\n\n  private _impl: SharedMediaImpl;\n  private _renderPromise: Promise<void>;\n  private _dispose: () => void;\n\n  private _render() {\n    if(this._renderPromise) return this._renderPromise;\n\n    const div = document.createElement('div');\n\n    return this._renderPromise = (async() => {\n      const {default: Component} = await import('./sharedMedia');\n\n      const promiseCollectorHelper = PromiseCollector.createHelper();\n\n      this._dispose = render(() => (\n        <SolidJSHotReloadGuardProvider>\n          <PromiseCollector onCollect={promiseCollectorHelper.onCollect}>\n            <SuperTabProvider self={this}>\n              <Component />\n            </SuperTabProvider>\n          </PromiseCollector>\n        </SolidJSHotReloadGuardProvider>\n      ), div);\n\n      this.scrollable.append(div);\n\n      await promiseCollectorHelper.await();\n    })();\n  }\n\n  public init() {\n    return this._render();\n  }\n\n  public setPeer(peerId: PeerId, threadId?: number) {\n    if(this.peerId === peerId && this.threadId === threadId) return false;\n\n    this.peerId = peerId;\n    this.threadId = threadId;\n    this.noProfile ??= peerId === rootScope.myId;\n    this.peerChanged = true;\n\n    if(this._impl) {\n      this._impl.setQuery();\n    } else {\n      this._render().then(() => this._impl.setQuery());\n    }\n\n    return true;\n  }\n\n  public fillProfileElements() {\n    if(this._impl) return this._impl.fillProfileElements();\n    return this._render().then(() => this._impl.fillProfileElements());\n  }\n\n  public loadSidebarMedia(single: boolean, justLoad?: boolean) {\n    if(this._impl) return this._impl.loadSidebarMedia(single, justLoad);\n    return this._render().then(() => this._impl.loadSidebarMedia(single, justLoad));\n  }\n\n  public setSearchTab(type: SearchSuperMediaType) {\n    if(this._impl) return this._impl.setSearchTab(type);\n    this._render().then(() => this._impl.setSearchTab(type));\n  }\n\n  public setLoadMutex(promise: Promise<any>) {\n    if(this._impl) return this._impl.setLoadMutex(promise);\n    this._render().then(() => this._impl.setLoadMutex(promise));\n  }\n\n  onOpenAfterTimeout() {\n    super.onOpenAfterTimeout();\n\n    this.scrollable.onScroll();\n  }\n\n  onCloseAfterTimeout() {\n    super.onCloseAfterTimeout();\n\n    if(this.destroyable) {\n      this.searchSuper?.destroy();\n    }\n\n    this._dispose?.();\n  }\n\n  public destroy() {\n    this.destroyable = true;\n    this.onCloseAfterTimeout();\n  }\n\n  public static async open(slider: SidebarSlider, peerId: PeerId, noProfile?: boolean) {\n    const tab = slider.createTab(AppSharedMediaTab, true);\n    tab.noProfile = noProfile;\n    tab.isFirst = true;\n    tab.setPeer(peerId);\n    (await tab.fillProfileElements())();\n    await tab.loadSidebarMedia(true);\n    return tab.open();\n  }\n}\n","import SwipeHandler, {getEvent} from '@components/swipeHandler';\nimport {toastNew} from '@components/toast';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport rootScope from '@lib/rootScope';\nimport {appSettings, setAppSettings} from '@stores/appSettings';\nimport {\n  MIN_SIDEBAR_WIDTH,\n  SIDEBAR_COLLAPSE_FACTOR,\n  setUserPreferredLeft,\n  setUserPreferredRight\n} from '@helpers/updateColumnWidths';\n\nexport type ColumnResizeSide = 'left' | 'right';\n\nexport type InstallColumnResizeOptions = {\n  /** The column element to attach the handle to. Becomes the handle's `.relative` parent. */\n  columnEl: HTMLElement;\n  side: ColumnResizeSide;\n  /**\n   * Optional left-column-only hooks. Called whenever the drag crosses the\n   * collapse threshold so the caller can toggle the `is-collapsed` class\n   * and any related state.\n   */\n  isCollapsed?: () => boolean;\n  setCollapsed?: (collapsed: boolean) => void;\n  /** Called when the collapsed state actually flips. */\n  onCollapsedChange?: () => void;\n  /**\n   * Optional check used for the collapse threshold. When this returns true,\n   * the drag cannot collapse the column (e.g. tabs are open). Left only.\n   */\n  preventCollapse?: () => boolean;\n  /** Side-effect to run on every swipe tick (after width is updated). */\n  onSwipeTick?: () => void;\n};\n\n/**\n * Attach a `.sidebar-resize-handle` to a column. The handle drives\n * `setUserPreferredLeft` or `setUserPreferredRight` (which own the CSS vars\n * and localStorage). When the user holds Shift during the drag, the OTHER\n * column is resized in lock-step with the dragged one.\n */\nexport default function installColumnResize(opts: InstallColumnResizeOptions): void {\n  const {columnEl, side, isCollapsed, setCollapsed, onCollapsedChange, preventCollapse, onSwipeTick} = opts;\n  const otherBodyClass = side === 'left' ? 'resizing-left-sidebar' : 'resizing-right-sidebar';\n\n  const handle = document.createElement('div');\n  handle.classList.add('sidebar-resize-handle', `sidebar-resize-handle-${side}`);\n  columnEl.append(handle);\n\n  new SwipeHandler({\n    element: handle,\n    setCursorTo: getOverlayRoot(),\n    onStart: () => {\n      handle.classList.add('is-active');\n      document.body.classList.add(otherBodyClass);\n      if(!appSettings.seenTooltips.sidebarResize) {\n        setAppSettings('seenTooltips', 'sidebarResize', true);\n        toastNew({langPackKey: 'Sidebar.Resize.ShiftTip'});\n      }\n    },\n    onSwipe: (_, __, _e) => {\n      const e = getEvent(_e);\n      const rect = columnEl.getBoundingClientRect();\n      // The handle sits on the inner edge of its column; width is the\n      // distance from the OUTER edge to the pointer.\n      const rawWidth = side === 'left' ?\n        Math.round(e.clientX - rect.left) :\n        Math.round(rect.right - e.clientX);\n\n      const isShift = (e as MouseEvent).shiftKey === true;\n\n      if(side === 'left') {\n        const wasCollapsed = !!isCollapsed?.();\n        const collapsed = !preventCollapse?.() && rawWidth < MIN_SIDEBAR_WIDTH * SIDEBAR_COLLAPSE_FACTOR;\n        setUserPreferredLeft(collapsed ? 0 : rawWidth);\n        setCollapsed?.(collapsed);\n        if(collapsed !== wasCollapsed) onCollapsedChange?.();\n        if(isShift) {\n          // Mirror to the right column — clamped to its valid range, no\n          // collapse semantics. setUserPreferredRight handles the clamp.\n          setUserPreferredRight(collapsed ? MIN_SIDEBAR_WIDTH : rawWidth);\n        }\n      } else {\n        setUserPreferredRight(rawWidth);\n        if(isShift) setUserPreferredLeft(rawWidth);\n      }\n\n      rootScope.dispatchEvent('resizing_left_sidebar');\n      onSwipeTick?.();\n    },\n    onReset: () => {\n      handle.classList.remove('is-active');\n      document.body.classList.remove(otherBodyClass);\n    }\n  });\n}\n","import appImManager, {APP_TABS} from '@lib/appImManager';\nimport SidebarSlider from '@components/slider';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {AppManagers} from '@lib/managers';\nimport appNavigationController from '@components/appNavigationController';\nimport rootScope from '@lib/rootScope';\nimport {installColumnWidthsUpdater} from '@helpers/updateColumnWidths';\nimport installColumnResize from '@helpers/installColumnResize';\nimport animationIntersector from '@components/animationIntersector';\n\n\nexport const RIGHT_COLUMN_ACTIVE_CLASSNAME = 'is-right-column-shown';\n\nexport class AppSidebarRight extends SidebarSlider {\n  public sharedMediaTab: AppSharedMediaTab;\n  // public rect: DOMRect;\n\n  constructor() {\n    super({\n      sidebarEl: document.getElementById('column-right') as HTMLElement,\n      canHideFirst: true,\n      navigationType: 'right'\n    });\n\n    this.sidebarEl.inert = !document.body.classList.contains(RIGHT_COLUMN_ACTIVE_CLASSNAME);\n  }\n\n  construct(managers: AppManagers) {\n    this.managers = managers;\n\n    mediaSizes.addEventListener('changeScreen', (from, to) => {\n      if(to === ScreenSize.medium && from !== ScreenSize.mobile) {\n        this.toggleSidebar(false);\n      }\n    });\n\n    installColumnWidthsUpdater();\n    installColumnResize({columnEl: this.sidebarEl, side: 'right'});\n  }\n\n  public createSharedMediaTab() {\n    const tab = this.createTab(AppSharedMediaTab, false, true);\n    tab.slider = this;\n    // this.tabsContainer.prepend(tab.container);\n    return tab;\n  }\n\n  public replaceSharedMediaTab(tab?: AppSharedMediaTab) {\n    const previousTab = this.sharedMediaTab;\n    if(previousTab) {\n      const idx = this.historyTabIds.indexOf(previousTab);\n\n      if(this._selectTab.getFrom() === previousTab.container) {\n        this._selectTab.setFrom(tab?.container);\n      }\n\n      if(tab) {\n        if(idx !== -1) {\n          this.historyTabIds[idx] = tab;\n        }\n\n        const wasActive = previousTab.container.classList.contains('active');\n        if(wasActive) {\n          tab.container.classList.add('active');\n        }\n\n        previousTab.container.replaceWith(tab.container);\n      } else {\n        if(idx !== -1) {\n          this.historyTabIds.splice(idx, 1);\n        }\n\n        previousTab.container.remove();\n      }\n    } else if(tab) {\n      // both undefined means there is nothing to remove and nothing to mount — reaching for\n      // `tab.container` here threw, and the throw aborted whatever peer change was running\n      this.tabsContainer.prepend(tab.container);\n    }\n\n    this.sharedMediaTab = tab;\n  }\n\n  public onCloseTab(id: number, animate: boolean, isNavigation?: boolean) {\n    if(!this.historyTabIds.length) {\n      this.toggleSidebar(false, animate);\n    }\n\n    super.onCloseTab(id, animate, isNavigation);\n  }\n\n  public hide() {\n    this.sidebarEl.inert = true;\n    document.body.classList.remove(RIGHT_COLUMN_ACTIVE_CLASSNAME);\n    appNavigationController.removeByType('right');\n    // The column is hidden with a transform (stays mounted), so pause any video\n    // avatars playing inside it — the IntersectionObserver won't catch the move.\n    animationIntersector.toggleVideosUnder(this.sidebarEl, true);\n    rootScope.dispatchEventSingle('right_sidebar_toggle', false);\n  }\n\n  public toggleSidebar(enable?: boolean, animate?: boolean) {\n    const active = document.body.classList.contains(RIGHT_COLUMN_ACTIVE_CLASSNAME);\n    let willChange: boolean;\n    if(enable !== undefined) {\n      if(enable) {\n        if(!active) {\n          willChange = true;\n        }\n      } else if(active) {\n        willChange = true;\n      }\n    } else {\n      willChange = true;\n    }\n\n    if(!willChange) return Promise.resolve();\n\n    if(!active && !this.historyTabIds.length) {\n      this.sharedMediaTab.open();\n    }\n\n    const animationPromise = appImManager.selectTab(active ? APP_TABS.CHAT : APP_TABS.PROFILE, animate);\n    if(!enable) this.hide();\n    else {\n      document.body.classList.add(RIGHT_COLUMN_ACTIVE_CLASSNAME);\n      this.sidebarEl.inert = false;\n      if(!appNavigationController.findItemByType('right')) {\n        this.pushNavigationItem(this.sharedMediaTab);\n      }\n      // Resume video avatars paused by a previous hide() (see toggleVideosUnder).\n      animationIntersector.toggleVideosUnder(this.sidebarEl, false);\n      rootScope.dispatchEventSingle('right_sidebar_toggle', true);\n    }\n    return animationPromise;\n  }\n}\n\nconst appSidebarRight = new AppSidebarRight();\nMOUNT_CLASS_TO.appSidebarRight = appSidebarRight;\nexport default appSidebarRight;\n","const IS_STANDALONE = window.matchMedia('(display-mode: standalone)').matches;\nexport default IS_STANDALONE;\n","import findUpClassName from '@helpers/dom/findUpClassName';\n\nfunction getBubbleByClassName(element: HTMLElement, className: string) {\n  const bubble = findUpClassName(element, 'bubble');\n  return bubble?.classList.contains(className) ? bubble : undefined;\n}\n\nconst getAlbumBubble = (element: HTMLElement) => getBubbleByClassName(element, 'is-album');\n\n/**\n * A grouped bubble (album, grouped documents) is a single drag unit: its outer bubble carries the\n * group's main mid, so hovering it right after one of its items would count as a second element and\n * start the selection without ever leaving the group. Only an item-to-item move inside the group is\n * a real range.\n */\nexport function isSameGroupedSelectionUnit(anchor: HTMLElement, element: HTMLElement) {\n  const bubble = getBubbleByClassName(anchor, 'is-grouped');\n  if(!bubble || bubble !== getBubbleByClassName(element, 'is-grouped')) {\n    return false;\n  }\n\n  return !(anchor.classList.contains('grouped-item') && element.classList.contains('grouped-item'));\n}\n\nexport function expandAlbumSelectionRange(options: {\n  first: HTMLElement,\n  last: HTMLElement,\n  elements: HTMLElement[],\n  getGroupedItems: (bubble: HTMLElement) => HTMLElement[]\n}) {\n  const {first, last, elements, getGroupedItems} = options;\n  const albums = new Map<HTMLElement, HTMLElement[]>();\n  const firstAlbum = getAlbumBubble(first);\n  const lastAlbum = getAlbumBubble(last);\n  const sharedEndpointAlbum = firstAlbum &&\n    firstAlbum === lastAlbum &&\n    first.classList.contains('grouped-item') &&\n    last.classList.contains('grouped-item') ?\n    firstAlbum :\n    undefined;\n  const addAlbum = (element: HTMLElement) => {\n    const album = getAlbumBubble(element);\n    if(album && album !== sharedEndpointAlbum && !albums.has(album)) {\n      const items = getGroupedItems(album);\n      if(items.length) {\n        albums.set(album, items);\n      }\n    }\n  };\n\n  elements.forEach(addAlbum);\n\n  if(!sharedEndpointAlbum) {\n    addAlbum(first);\n    addAlbum(last);\n  }\n\n  if(!albums.size) {\n    return elements;\n  }\n\n  const expanded = elements.filter((element) => {\n    const album = getAlbumBubble(element);\n    return !album || !albums.has(album);\n  });\n  albums.forEach((items) => expanded.push(...items));\n\n  return [...new Set(expanded)];\n}\n\nexport function setAlbumItemsSelection(options: {\n  album: HTMLElement,\n  selected: boolean,\n  getGroupedItems: (album: HTMLElement) => HTMLElement[],\n  setElementSelection: (element: HTMLElement, selected: boolean) => void\n}) {\n  const {album, selected, getGroupedItems, setElementSelection} = options;\n  if(!album.classList.contains('is-album')) {\n    return false;\n  }\n\n  getGroupedItems(album).forEach((item) => setElementSelection(item, selected));\n  return true;\n}\n","import isEphemeralMessageId from '@appManagers/utils/messageId/isEphemeralMessageId';\n\nexport function getMessageSelectionGroup<K>(\n  selectedMids: ReadonlyMap<K, ReadonlySet<number>>\n) {\n  for(const mids of selectedMids.values()) {\n    const mid = mids.values().next().value;\n    if(mid !== undefined) {\n      return isEphemeralMessageId(mid);\n    }\n  }\n}\n\nexport default function isSameMessageSelectionGroup<K>(\n  selectedMids: ReadonlyMap<K, ReadonlySet<number>>,\n  isEphemeral: boolean\n) {\n  const selectionGroup = getMessageSelectionGroup(selectedMids);\n  return selectionGroup === undefined || selectionGroup === isEphemeral;\n}\n","import type {MessagesStorageKey} from '@appManagers/appMessagesManager';\nimport type ChatBubbles from '@components/chat/bubbles';\nimport type ChatInput from '@components/chat/input';\nimport type Chat from '@components/chat/chat';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport Button from '@components/button';\nimport ButtonIcon from '@components/buttonIcon';\nimport CheckboxField from '@components/checkboxField';\nimport PopupDeleteMessages from '@components/popups/deleteMessages';\nimport showForwardPopup from '@components/popups/forward';\nimport {showSelectedMessagesReport} from '@components/popups/reportAd';\nimport SetTransition from '@components/singleTransition';\nimport getSelectionElementFromTarget from '@components/chat/getSelectionElementFromTarget';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport PopupSendNow from '@components/popups/sendNow';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport {IS_MOBILE_SAFARI} from '@environment/userAgent';\nimport {i18n, _i18n} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {getAppWindow} from '@helpers/appWindow';\nimport cancelSelection from '@helpers/dom/cancelSelection';\nimport getSelectedText from '@helpers/dom/getSelectedText';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport type AppSearchSuper from '@components/appSearchSuper';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport {randomLong} from '@helpers/random';\nimport {attachClickEvent, AttachClickOptions} from '@helpers/dom/clickEvent';\nimport findUpAsChild from '@helpers/dom/findUpAsChild';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport appImManager from '@lib/appImManager';\nimport {Message} from '@layer';\nimport PopupElement from '@components/popups';\nimport flatten from '@helpers/array/flatten';\nimport IS_STANDALONE from '@environment/standalone';\nimport {toastNew} from '@components/toast';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {\n  expandAlbumSelectionRange,\n  isSameGroupedSelectionUnit,\n  setAlbumItemsSelection\n} from '@components/chat/selectionRange';\nimport {ChatType} from './chatType';\nimport ChatInputPlate from '@components/chat/controlPlate';\nimport isSameMessageSelectionGroup, {getMessageSelectionGroup} from '@components/chat/isSameMessageSelectionGroup';\n\nconst accumulateMapSet = <T extends {size: number}>(map: Map<any, T>) => {\n  return [...map.values()].reduce((acc, v) => acc + v.size, 0);\n};\n\n// const MIN_CLICK_MOVE = 32; // minimum bubble height\n\nexport class AppSelection extends EventListenerBase<{\n  toggle: (isSelecting: boolean) => void\n}> {\n  public selectedMids: Map<PeerId, Set<number>> = new Map();\n  public isSelecting = false;\n\n  public selectedText: string;\n\n  protected listenerSetter: ListenerSetter;\n  public isScheduled: boolean;\n  protected listenElement: HTMLElement;\n\n  protected onToggleSelection: (forwards: boolean, animate: boolean) => void | Promise<void>;\n  protected onUpdateContainer: (cantForward: boolean, cantDelete: boolean, cantSend: boolean) => void;\n  protected onCancelSelection: () => void;\n  protected toggleByElement: (bubble: HTMLElement, selected?: boolean) => void;\n\n  protected navigationType: NavigationItem['type'];\n\n  protected getElementFromTarget: (target: HTMLElement) => HTMLElement;\n  protected verifyTarget: (e: MouseEvent, target: HTMLElement) => boolean;\n  protected verifyMouseMoveTarget: (e: MouseEvent, element: HTMLElement, selecting: boolean) => boolean;\n  protected verifyTouchLongPress: () => boolean;\n  protected targetLookupClassName: string;\n  protected lookupBetweenParentClassName: string;\n  protected lookupBetweenElementsQuery: string;\n\n  protected doNotAnimate: boolean;\n  protected managers: AppManagers;\n\n  protected onTouchLongPress: (e: Event) => void;\n\n  constructor(options: {\n    managers: AppManagers,\n    getElementFromTarget: AppSelection['getElementFromTarget'],\n    verifyTarget?: AppSelection['verifyTarget'],\n    verifyMouseMoveTarget?: AppSelection['verifyMouseMoveTarget'],\n    verifyTouchLongPress?: AppSelection['verifyTouchLongPress'],\n    targetLookupClassName: string,\n    lookupBetweenParentClassName: string,\n    lookupBetweenElementsQuery: string,\n    onTouchLongPress?: AppSelection['onTouchLongPress']\n  }) {\n    super(false);\n\n    safeAssign(this, options);\n\n    this.navigationType = 'multiselect-' + randomLong() as any;\n  }\n\n  public attachListeners(listenElement: HTMLElement, listenerSetter: ListenerSetter) {\n    if(this.listenElement) {\n      this.listenerSetter.removeAll();\n    }\n\n    this.listenElement = listenElement;\n    this.listenerSetter = listenerSetter;\n\n    if(!listenElement) {\n      if(this.navigationType) {\n        appNavigationController.removeByType(this.navigationType);\n      }\n      return;\n    }\n\n    if(IS_TOUCH_SUPPORTED) {\n      listenerSetter.add(listenElement)('touchend', () => {\n        if(!this.isSelecting) return;\n        this.selectedText = getSelectedText();\n      });\n\n      attachContextMenuListener({\n        element: listenElement,\n        callback: (e) => {\n          if(\n            this.isSelecting ||\n            (e.target as HTMLElement).closest('reaction-element') ||\n            (this.verifyTouchLongPress && !this.verifyTouchLongPress())\n          ) return;\n\n          this.onTouchLongPress?.(e);\n\n          // * these two lines will fix instant text selection on iOS Safari\n          document.body.classList.add('no-select'); // * need no-select on body because chat-input transforms in channels\n          listenElement.addEventListener('touchend', (e) => {\n            cancelEvent(e); // ! this one will fix propagation to document loader button, etc\n            document.body.classList.remove('no-select');\n\n            // this.chat.bubbles.onBubblesClick(e);\n          }, {once: true, capture: true});\n\n          if(IS_MOBILE_SAFARI && IS_STANDALONE) {\n            listenElement.addEventListener('mousedown', cancelEvent, {once: true, capture: true});\n          }\n\n          cancelSelection();\n          cancelEvent(e as any);\n          const element = this.getElementFromTarget(e.target as HTMLElement);\n          if(element) {\n            this.toggleByElement(element);\n          }\n        },\n        listenerSetter\n      });\n\n      return;\n    }\n\n    listenerSetter.add(listenElement)('mousedown', this.onMouseDown);\n  }\n\n  private onMouseDown = (e: MouseEvent) => {\n    // console.log('selection mousedown', e);\n    const element = findUpClassName(e.target, this.targetLookupClassName);\n    if(e.button !== 0) {\n      return;\n    }\n\n    if(this.verifyTarget && !this.verifyTarget(e, element)) {\n      return;\n    }\n\n    // The drag-end `mouseup` and the post-drag click-swallow must land on whichever window the app is\n    // in (the tab, or the Document PiP window) — otherwise a drag-select started in the PiP never ends\n    // (mouseup fires on the PiP window, not the main document) and the selection sticks.\n    const activeWindow = getAppWindow();\n    const activeDocument = activeWindow.document;\n\n    const seen = new Map<PeerId, Map<number, HTMLElement>>();\n    let selecting: boolean;\n    // * the first element the drag has actually processed — everything belonging to its selection\n    // * unit is not a second element\n    let dragAnchor: HTMLElement;\n\n    /* let good = false;\n    const {x, y} = e; */\n\n    /* const bubbles = appImManager.bubbles;\n    for(const mid in bubbles) {\n      const bubble = bubbles[mid];\n      bubble.addEventListener('mouseover', () => {\n        console.log('mouseover');\n      }, {once: true});\n    } */\n\n    let firstTarget = element;\n\n    const processElement = (element: HTMLElement, checkBetween = true) => {\n      const mid = +element.dataset.mid;\n      if(!mid || !element.dataset.peerId) return;\n      const peerId = element.dataset.peerId.toPeerId();\n\n      if(!isInDOM(firstTarget)) {\n        firstTarget = element;\n      }\n\n      let seenElements = seen.get(peerId);\n      if(!seenElements) {\n        seen.set(peerId, seenElements = new Map());\n      }\n\n      if(seenElements.has(mid)) {\n        return;\n      }\n\n      if(dragAnchor && this.isSameSelectionUnit(dragAnchor, element)) {\n        return;\n      }\n\n      const isSelected = this.isMidSelected(peerId, mid);\n      if(selecting === undefined) {\n        // bubblesContainer.classList.add('no-select');\n        selecting = !isSelected;\n      }\n\n      seenElements.set(mid, element);\n      dragAnchor ??= element;\n\n      if((selecting && !isSelected) || (!selecting && isSelected)) {\n        const seenLength = accumulateMapSet(seen);\n        if(this.toggleByElement && checkBetween) {\n          if(seenLength < 2) {\n            if(findUpAsChild(element, firstTarget)) {\n              firstTarget = element;\n            }\n          }\n\n          const elementsBetween = this.getElementsBetween(firstTarget, element);\n          // console.log(elementsBetween);\n          if(elementsBetween.length) {\n            elementsBetween.forEach((element) => {\n              processElement(element, false);\n            });\n          }\n        }\n\n        if(!this.selectedMids.size) {\n          if(seenLength === 2 && this.toggleByElement) {\n            for(const elements of seen.values()) {\n              for(const element of elements.values()) {\n                this.toggleByElement(element, selecting);\n              }\n            }\n          }\n        } else if(this.toggleByElement) {\n          this.toggleByElement(element, selecting);\n        }\n      }\n    };\n\n    // const foundTargets: Map<HTMLElement, true> = new Map();\n    let canceledSelection = false;\n    const onMouseMove = (e: MouseEvent) => {\n      if(!canceledSelection) {\n        cancelSelection();\n        canceledSelection = true;\n        document.body.classList.add('no-select');\n        // const chat = document.querySelector('.chat');\n        // chat.classList.add('no-select');\n      }\n      /* if(!good) {\n        if(Math.abs(e.x - x) > MIN_CLICK_MOVE || Math.abs(e.y - y) > MIN_CLICK_MOVE) {\n          good = true;\n        } else {\n          return;\n        }\n      } */\n\n      /* if(foundTargets.has(e.target as HTMLElement)) return;\n      foundTargets.set(e.target as HTMLElement, true); */\n      const element = this.getElementFromTarget(e.target as HTMLElement);\n      if(!element) {\n        // console.error('found no bubble', e);\n        return;\n      }\n\n      if(this.verifyMouseMoveTarget && !this.verifyMouseMoveTarget(e, element, selecting)) {\n        this.listenerSetter.removeManual(this.listenElement, 'mousemove', onMouseMove);\n        this.listenerSetter.removeManual(activeDocument, 'mouseup', onMouseUp, documentListenerOptions);\n        return;\n      }\n\n      processElement(element);\n    };\n\n    const onMouseUp = (e: MouseEvent) => {\n      document.body.classList.remove('no-select');\n\n      if(seen.size) {\n        attachClickEvent(activeWindow, cancelEvent, {capture: true, once: true, passive: false});\n      }\n\n      this.listenerSetter.removeManual(this.listenElement, 'mousemove', onMouseMove);\n      // bubblesContainer.classList.remove('no-select');\n\n      // ! CANCEL USER SELECTION !\n      cancelSelection();\n    };\n\n    const documentListenerOptions = {once: true};\n    this.listenerSetter.add(this.listenElement)('mousemove', onMouseMove);\n    this.listenerSetter.add(activeDocument)('mouseup', onMouseUp, documentListenerOptions);\n  };\n\n  /**\n   * Whether `element` is a part of the same selectable unit the drag has started on, and so must not\n   * count as another element of the range\n   */\n  protected isSameSelectionUnit(anchor: HTMLElement, element: HTMLElement) {\n    return false;\n  }\n\n  protected getElementsBetween(first: HTMLElement, last: HTMLElement) {\n    if(first === last) {\n      return [];\n    }\n\n    const firstRect = first.getBoundingClientRect();\n    const lastRect = last.getBoundingClientRect();\n    const difference = (firstRect.top - lastRect.top) || (firstRect.left - lastRect.left);\n    const isHigher = difference < 0;\n\n    const parent = findUpClassName(first, this.lookupBetweenParentClassName);\n    if(!parent) {\n      return [];\n    }\n\n    const elements = Array.from(parent.querySelectorAll(this.lookupBetweenElementsQuery)) as HTMLElement[];\n    let firstIndex = elements.indexOf(first);\n    let lastIndex = elements.indexOf(last);\n\n    if(!isHigher) {\n      [lastIndex, firstIndex] = [firstIndex, lastIndex];\n    }\n\n    const slice = elements.slice(firstIndex + 1, lastIndex);\n\n    // console.log('getElementsBetween', first, last, slice, firstIndex, lastIndex, isHigher);\n\n    return slice;\n  }\n\n  protected isElementShouldBeSelected(element: HTMLElement) {\n    return this.isMidSelected(element.dataset.peerId.toPeerId(), +element.dataset.mid);\n  }\n\n  protected appendCheckbox(element: HTMLElement, checkboxField: CheckboxField) {\n    element.prepend(checkboxField.label);\n  }\n\n  public toggleElementCheckbox(element: HTMLElement, show: boolean) {\n    const hasCheckbox = !!this.getCheckboxInputFromElement(element);\n    if(show) {\n      if(hasCheckbox) {\n        return false;\n      }\n\n      const checkboxField = new CheckboxField({\n        name: element.dataset.mid,\n        round: true\n      });\n\n      // * if it is a render of new message\n      if(this.isSelecting) { // ! avoid breaking animation on start\n        if(this.isElementShouldBeSelected(element)) {\n          checkboxField.input.checked = true;\n          element.classList.add('is-selected');\n        }\n      }\n\n      this.appendCheckbox(element, checkboxField);\n    } else if(hasCheckbox) {\n      this.getCheckboxInputFromElement(element).parentElement.remove();\n      SetTransition({\n        element,\n        className: 'is-selected',\n        forwards: false,\n        duration: 200\n      });\n    }\n\n    return true;\n  }\n\n  protected getCheckboxInputFromElement(element: HTMLElement): HTMLInputElement {\n    const field = element.firstElementChild;\n    const input = field?.firstElementChild;\n    if(!field?.classList.contains('checkbox-field') || !input?.classList.contains('checkbox-field-input')) {\n      return;\n    }\n\n    return input as HTMLInputElement;\n  }\n\n  protected async updateContainer(forceSelection = false) {\n    const size = this.selectedMids.size;\n    if(!size && !forceSelection) return;\n\n    let cantForward = !size;\n    let cantDelete = !size;\n    const cantSend = !size;\n\n    for(const [peerId, mids] of this.selectedMids) {\n      const storageKey = this.getStorageKey(peerId);\n      const r = await this.managers.appMessagesManager.cantForwardDeleteMids(storageKey, Array.from(mids));\n      cantForward ||= r.cantForward;\n      cantDelete ||= r.cantDelete;\n\n      if(cantForward && cantDelete) break;\n    }\n\n    this.onUpdateContainer?.(cantForward, cantDelete, cantSend);\n  }\n\n  private getStorageKey(peerId: PeerId): MessagesStorageKey {\n    return `${peerId}_${this.isScheduled ? 'scheduled' : 'history'}`;\n  }\n\n  public getSelectedMids() {\n    return flatten([...this.selectedMids.values()].map((set) => [...set])).sort((a, b) => a - b);\n  }\n\n  public getSelectedMessages() {\n    const selectedMessagesPromises: Promise<Message.message | Message.messageService>[] = [];\n    this.selectedMids.forEach((mids, peerId) => {\n      const storageKey = this.getStorageKey(peerId);\n      const p = Array.from(mids).map((mid) => this.managers.appMessagesManager.getMessageFromStorage(storageKey, mid));\n      selectedMessagesPromises.push(...p);\n    });\n    return Promise.all(selectedMessagesPromises);\n  }\n\n  public toggleSelection(toggleCheckboxes = true, forceSelection = false) {\n    const wasSelecting = this.isSelecting;\n    const size = this.selectedMids.size;\n    this.isSelecting = !!size || forceSelection;\n\n    if(wasSelecting === this.isSelecting) return false;\n\n    this.dispatchEvent('toggle', this.isSelecting);\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.listenElement.classList.toggle('no-select', this.isSelecting);\n\n      if(wasSelecting) {\n        // ! CANCEL USER SELECTION !\n        cancelSelection();\n      }\n    }/*  else {\n      if(!wasSelecting) {\n        bubblesContainer.classList.add('no-select');\n        setTimeout(() => {\n          cancelSelection();\n          bubblesContainer.classList.remove('no-select');\n          cancelSelection();\n        }, 100);\n      }\n    } */\n\n    blurActiveElement();\n\n    const forwards = !!size || forceSelection;\n    const toggleResult = this.onToggleSelection?.(forwards, !this.doNotAnimate);\n\n    if(!IS_MOBILE_SAFARI) {\n      if(forwards) {\n        appNavigationController.pushItem({\n          type: this.navigationType,\n          onPop: () => {\n            this.cancelSelection();\n          }\n        });\n      } else {\n        appNavigationController.removeByType(this.navigationType);\n      }\n    }\n\n    if(forceSelection) {\n      (toggleResult || Promise.resolve()).then(() => this.updateContainer(forceSelection));\n    }\n\n    return true;\n  }\n\n  public cancelSelection = (doNotAnimate?: boolean) => {\n    if(doNotAnimate) this.doNotAnimate = true;\n    this.onCancelSelection?.();\n    this.selectedMids.clear();\n    this.toggleSelection();\n    cancelSelection();\n    if(doNotAnimate) this.doNotAnimate = undefined;\n  };\n\n  public cleanup() {\n    this.doNotAnimate = true;\n    this.selectedMids.clear();\n    this.toggleSelection(false);\n    this.doNotAnimate = undefined;\n  }\n\n  protected updateElementSelection(element: HTMLElement, isSelected: boolean) {\n    this.toggleElementCheckbox(element, true);\n    const input = this.getCheckboxInputFromElement(element);\n    input.checked = isSelected;\n\n    this.toggleSelection();\n    this.updateContainer();\n    SetTransition({\n      element,\n      className: 'is-selected',\n      forwards: isSelected,\n      duration: 200\n    });\n  }\n\n  public isMidSelected(peerId: PeerId, mid: number) {\n    const set = this.selectedMids.get(peerId);\n    return !!set?.has(mid);\n  }\n\n  public length() {\n    return accumulateMapSet(this.selectedMids);\n  }\n\n  public toggleMid(peerId: PeerId, mid: number, unselect?: boolean) {\n    let set = this.selectedMids.get(peerId);\n    if(unselect || (unselect === undefined && set?.has(mid))) {\n      if(set) {\n        set.delete(mid);\n\n        if(!set.size) {\n          this.selectedMids.delete(peerId);\n        }\n      }\n    } else {\n      // const diff = rootScope.config.forwarded_count_max - this.length() - 1;\n      // if(diff < 0) {\n      //   toast(I18n.format('Chat.Selection.LimitToast', true));\n      //   return false;\n      //   /* const it = this.selectedMids.values();\n      //   do {\n      //     const mid = it.next().value;\n      //     const mounted = this.appImManager.getMountedBubble(mid);\n      //     if(mounted) {\n      //       this.toggleByBubble(mounted.bubble);\n      //     } else {\n      //       const mids = this.appMessagesManager.getMidsByMid(mid);\n      //       for(const mid of mids) {\n      //         this.selectedMids.delete(mid);\n      //       }\n      //     }\n      //   } while(this.selectedMids.size > MAX_SELECTION_LENGTH); */\n      // }\n\n      if(!set) {\n        set = new Set();\n        this.selectedMids.set(peerId, set);\n      }\n\n      set.add(mid);\n    }\n\n    return true;\n  }\n\n  /**\n   * ! Call this method only to handle deleted messages\n   */\n  public deleteSelectedMids(peerId: PeerId, mids: number[], batch?: boolean) {\n    const set = this.selectedMids.get(peerId);\n    if(!set) {\n      return;\n    }\n\n    mids.forEach((mid) => {\n      set.delete(mid);\n    });\n\n    if(!set.size) {\n      this.selectedMids.delete(peerId);\n    }\n\n    const after = () => {\n      this.updateContainer();\n      this.toggleSelection();\n    };\n\n    if(!batch) after();\n    return after;\n  }\n}\n\nexport class SearchSelection extends AppSelection {\n  protected selectionContainer: HTMLElement;\n  protected selectionCountEl: HTMLElement;\n  public selectionForwardBtn: HTMLElement;\n  public selectionDeleteBtn: HTMLElement;\n  public selectionGotoBtn: HTMLElement;\n\n  private isPrivate: boolean;\n\n  // * plate-scoped: the tab's listenerSetter outlives every selection session,\n  // * so plate button listeners must not accumulate there\n  private containerListenerSetter: ListenerSetter;\n\n  constructor(\n    private searchSuper: AppSearchSuper,\n    managers: AppManagers,\n    listenerSetter: ListenerSetter\n  ) {\n    super({\n      managers,\n      verifyTarget: (e, target) => !!target && this.isSelecting,\n      getElementFromTarget: (target) => findUpClassName(target, 'search-super-item'),\n      targetLookupClassName: 'search-super-item',\n      lookupBetweenParentClassName: 'tabs-tab',\n      lookupBetweenElementsQuery: '.search-super-item'\n    });\n\n    this.isPrivate = !searchSuper.showSender;\n    !IS_TOUCH_SUPPORTED && this.attachListeners(searchSuper.container, listenerSetter);\n  }\n\n  /* public appendCheckbox(element: HTMLElement, checkboxField: CheckboxField) {\n    checkboxField.label.classList.add('bubble-select-checkbox');\n\n    if(element.classList.contains('document') || element.classList.contains('audio')) {\n      element.querySelector('.document, .audio').append(checkboxField.label);\n    } else {\n      super.appendCheckbox(bubble, checkboxField);\n    }\n  } */\n\n  public toggleSelection(toggleCheckboxes = true, forceSelection = false) {\n    const ret = super.toggleSelection(toggleCheckboxes, forceSelection);\n\n    if(ret && toggleCheckboxes) {\n      const elements = Array.from(this.searchSuper.tabsContainer.querySelectorAll('.search-super-item')) as HTMLElement[];\n      elements.forEach((element) => {\n        this.toggleElementCheckbox(element, this.isSelecting);\n      });\n    }\n\n    return ret;\n  }\n\n  public toggleByElement = (element: HTMLElement, selected?: boolean) => {\n    const mid = +element.dataset.mid;\n    const peerId = element.dataset.peerId.toPeerId();\n    const isSelected = this.isMidSelected(peerId, mid);\n    if(selected !== undefined && selected === isSelected) {\n      return;\n    }\n\n    if(!this.toggleMid(peerId, mid)) {\n      return;\n    }\n\n    this.updateElementSelection(element, this.isMidSelected(peerId, mid));\n  };\n\n  protected onUpdateContainer = (cantForward: boolean, cantDelete: boolean) => {\n    const length = this.length();\n    replaceContent(this.selectionCountEl, i18n('messages', [length]));\n    this.selectionGotoBtn.classList.toggle('hide', length !== 1);\n    this.selectionForwardBtn.classList.toggle('hide', cantForward);\n    this.selectionDeleteBtn && this.selectionDeleteBtn.classList.toggle('hide', cantDelete);\n  };\n\n  protected onToggleSelection = (forwards: boolean, animate: boolean) => {\n    SetTransition({\n      element: this.searchSuper.navScrollableContainer,\n      className: 'is-selecting',\n      forwards,\n      duration: animate ? 200 : 0,\n      onTransitionEnd: () => {\n        if(!this.isSelecting) {\n          this.containerListenerSetter?.removeAll();\n          this.containerListenerSetter = null;\n          this.selectionContainer.remove();\n          this.selectionContainer =\n            this.selectionForwardBtn =\n            this.selectionDeleteBtn =\n            null;\n          this.selectedText = undefined;\n        }\n      }\n    });\n\n    SetTransition({\n      element: this.searchSuper.container,\n      className: 'is-selecting',\n      forwards,\n      duration: 200\n    });\n\n    if(this.isSelecting) {\n      if(!this.selectionContainer) {\n        const BASE_CLASS = 'search-super-selection';\n        this.selectionContainer = document.createElement('div');\n        this.selectionContainer.classList.add(BASE_CLASS + '-container');\n\n        this.containerListenerSetter = new ListenerSetter();\n\n        const btnCancel = ButtonIcon(`close ${BASE_CLASS}-cancel`, {noRipple: true});\n        attachClickEvent(btnCancel, () => this.cancelSelection(), {listenerSetter: this.containerListenerSetter, once: true});\n\n        this.selectionCountEl = document.createElement('div');\n        this.selectionCountEl.classList.add(BASE_CLASS + '-count');\n\n        const attachClickOptions: AttachClickOptions = {listenerSetter: this.containerListenerSetter};\n\n        this.selectionGotoBtn = ButtonIcon(`message ${BASE_CLASS}-goto`);\n        attachClickEvent(this.selectionGotoBtn, () => {\n          const peerId = [...this.selectedMids.keys()][0];\n          const mid = [...this.selectedMids.get(peerId)][0];\n          this.cancelSelection();\n\n          appImManager.setInnerPeer({\n            peerId,\n            lastMsgId: mid,\n            threadId: this.searchSuper.mediaTab.type === 'saved' ? this.searchSuper.searchContext.peerId : this.searchSuper.searchContext.threadId\n          });\n        }, attachClickOptions);\n\n        this.selectionForwardBtn = ButtonIcon(`forward ${BASE_CLASS}-forward`);\n        attachClickEvent(this.selectionForwardBtn, () => {\n          const obj: {[fromPeerId: PeerId]: number[]} = {};\n          for(const [fromPeerId, mids] of this.selectedMids) {\n            obj[fromPeerId] = Array.from(mids).sort((a, b) => a - b);\n          }\n\n          showForwardPopup(obj, () => {\n            this.cancelSelection();\n          });\n        }, attachClickOptions);\n\n        if(this.isPrivate) {\n          this.selectionDeleteBtn = ButtonIcon(`delete danger ${BASE_CLASS}-delete`);\n          attachClickEvent(this.selectionDeleteBtn, () => {\n            const peerId = this.searchSuper.searchContext.peerId;\n            PopupElement.createPopup(\n              PopupDeleteMessages,\n              peerId,\n              this.getSelectedMids(),\n              ChatType.Chat,\n              () => {\n                this.cancelSelection();\n              }\n            );\n          }, attachClickOptions);\n        }\n\n        this.selectionContainer.append(...[\n          btnCancel,\n          this.selectionCountEl,\n          this.selectionGotoBtn,\n          this.selectionForwardBtn,\n          this.selectionDeleteBtn\n        ].filter(Boolean));\n\n        const transitionElement = this.selectionContainer;\n        transitionElement.style.opacity = '0';\n        this.searchSuper.navScrollableContainer.append(transitionElement);\n\n        void transitionElement.offsetLeft; // reflow\n        transitionElement.style.opacity = '';\n      }\n    }\n  };\n}\n\nexport default class ChatSelection extends AppSelection {\n  protected selectionInputWrapper: HTMLElement;\n  protected selectionContainer: HTMLElement;\n  protected selectionCountEl: HTMLElement;\n  public selectionSendNowBtn: HTMLElement;\n  public selectionForwardBtn: HTMLElement;\n  public selectionDeleteBtn: HTMLElement;\n  public selectionReportBtn: HTMLElement;\n\n  // * \"select messages to report\" mode (entered on MESSAGE_ID_REQUIRED):\n  // * the plate shows a \"Report N Messages\" action instead of forward/delete\n  private reportSelectionData: {option: Uint8Array, text?: string};\n  private selectionContainerForReport: boolean;\n\n  // * plate-scoped: this.listenerSetter lives until peer change, so plate button\n  // * listeners must not accumulate there across selection sessions\n  private containerListenerSetter: ListenerSetter;\n\n  public get isReportSelection() {\n    return !!this.reportSelectionData;\n  }\n\n  constructor(\n    private chat: Chat,\n    private bubbles: ChatBubbles,\n    private input: ChatInput,\n    managers: AppManagers\n  ) {\n    super({\n      managers,\n      getElementFromTarget: getSelectionElementFromTarget,\n      verifyTarget: (e, target) => {\n        // LEFT BUTTON\n        // проверка внизу нужна для того, чтобы не активировать селект если target потомок .bubble\n        const bad = !this.selectedMids.size &&\n          !(e.target as HTMLElement).classList.contains('bubble') &&\n          !(e.target as HTMLElement).classList.contains('document-selection') &&\n          target;\n\n        return !bad;\n      },\n      verifyMouseMoveTarget: (e, element, selecting) => {\n        const bad = e.target !== element &&\n          !(e.target as HTMLElement).classList.contains('document-selection') &&\n          selecting === undefined &&\n          !this.selectedMids.size;\n        return !bad;\n      },\n      verifyTouchLongPress: () => !this.chat.input.recording,\n      targetLookupClassName: 'bubble',\n      lookupBetweenParentClassName: 'bubbles-inner',\n      lookupBetweenElementsQuery: '.bubble:not(.is-multiple-documents), .grouped-item',\n      onTouchLongPress: () => {\n        const {replySwipeHandler} = this.chat.bubbles;\n        replySwipeHandler?.reset();\n      }\n    });\n  }\n\n  protected isSameSelectionUnit(anchor: HTMLElement, element: HTMLElement) {\n    return isSameGroupedSelectionUnit(anchor, element);\n  }\n\n  protected getElementsBetween(first: HTMLElement, last: HTMLElement) {\n    const elements = super.getElementsBetween(first, last);\n    if(first === last) {\n      // * there is no range yet — expanding the endpoints here would pull in the whole album\n      return elements;\n    }\n\n    return expandAlbumSelectionRange({\n      first,\n      last,\n      elements,\n      getGroupedItems: (bubble) => this.bubbles.getBubbleGroupedItems(bubble)\n    });\n  }\n\n  public appendCheckbox(bubble: HTMLElement, checkboxField: CheckboxField) {\n    checkboxField.label.classList.add('bubble-select-checkbox');\n\n    if(bubble.classList.contains('document-container')) {\n      bubble.querySelector('.document, .audio').append(checkboxField.label);\n    } else {\n      super.appendCheckbox(bubble, checkboxField);\n    }\n  }\n\n  public enterReportSelection(data: ChatSelection['reportSelectionData']) {\n    if(this.isSelecting) {\n      // * an unrelated active selection must not become the report payload — start fresh\n      this.cancelSelection(true);\n    }\n\n    this.reportSelectionData = data;\n    if(!this.toggleSelection(true, true)) {\n      // * the previous plate can survive the synchronous cancel — rebuild it for the report mode\n      Promise.resolve(this.onToggleSelection(true, !this.doNotAnimate))\n      .then(() => this.updateContainer(true));\n    }\n  }\n\n  public cleanup() {\n    this.reportSelectionData = undefined;\n    super.cleanup();\n  }\n\n  protected async updateContainer(forceSelection = false) {\n    if(this.isReportSelection) {\n      // * no forward/delete state to compute — only the count matters here\n      this.onUpdateContainer(true, true, true);\n      return;\n    }\n\n    return super.updateContainer(forceSelection);\n  }\n\n  public toggleSelection(toggleCheckboxes = true, forceSelection = false) {\n    // * while choosing messages to report, the selection survives reaching zero\n    // * selected — the mode ends only via cancel or a sent report\n    const ret = super.toggleSelection(toggleCheckboxes, forceSelection || this.isReportSelection);\n\n    if(ret && !this.isSelecting) {\n      this.reportSelectionData = undefined;\n      this.refreshSelectionGroup();\n    }\n\n    if(ret && toggleCheckboxes) {\n      const history = this.bubbles.getRenderedHistory('asc');\n      for(const fullMid of history) {\n        if(this.bubbles.skippedMids.has(fullMid)) {\n          continue;\n        }\n\n        const bubble = this.bubbles.getBubble(fullMid);\n        this.toggleElementCheckbox(bubble, this.isSelecting);\n      }\n    }\n\n    return ret;\n  }\n\n  public toggleElementCheckbox(bubble: HTMLElement, show: boolean) {\n    if(show && !this.canSelectBubble(bubble)) return;\n\n    const ret = super.toggleElementCheckbox(bubble, show);\n    if(ret) {\n      const isGrouped = bubble.classList.contains('is-grouped');\n      if(isGrouped) {\n        this.bubbles.getBubbleGroupedItems(bubble).forEach((item) => this.toggleElementCheckbox(item, show));\n      }\n    }\n\n    return ret;\n  }\n\n  public toggleByElement = (bubble: HTMLElement, selected?: boolean): Promise<void> => {\n    if(!this.canSelectBubble(bubble)) return;\n\n    const mid = +bubble.dataset.mid;\n    const peerId = bubble.dataset.peerId.toPeerId();\n\n    const isGrouped = bubble.classList.contains('is-grouped');\n    if(isGrouped) {\n      if(selected !== undefined && setAlbumItemsSelection({\n        album: bubble,\n        selected,\n        getGroupedItems: (album) => this.bubbles.getBubbleGroupedItems(album),\n        setElementSelection: (element, selected) => this.toggleByElement(element, selected)\n      })) {\n        return;\n      }\n\n      if(!this.isGroupedBubbleSelected(bubble)) {\n        const set = this.selectedMids.get(peerId);\n        if(set) {\n          // const mids = await this.chat.getMidsByMid(mid);\n          const mids = this.getMidsFromGroupContainer(bubble);\n          mids.forEach(({mid}) => set.delete(mid));\n        }\n      }\n\n      /* const promises =  */this.bubbles.getBubbleGroupedItems(bubble).map((item) => this.toggleByElement(item));\n      // await Promise.all(promises);\n      return;\n    }\n\n    const isSelected = this.isMidSelected(peerId, mid);\n    if(selected !== undefined && selected === isSelected) {\n      return;\n    }\n\n    if(!this.toggleMid(peerId, mid)) {\n      return;\n    }\n    this.refreshSelectionGroup();\n\n    const isGroupedItem = bubble.classList.contains('grouped-item');\n    if(isGroupedItem) {\n      const groupContainer = findUpClassName(bubble, 'bubble');\n      const isGroupedSelected = this.isGroupedBubbleSelected(groupContainer);\n      const isGroupedMidsSelected = this.isGroupedMidsSelected(groupContainer);\n\n      const willChange = isGroupedMidsSelected || isGroupedSelected;\n      if(willChange) {\n        this.updateElementSelection(groupContainer, isGroupedMidsSelected);\n      }\n    }\n\n    this.updateElementSelection(bubble, this.isMidSelected(peerId, mid));\n  };\n\n  public isElementShouldBeSelected(element: HTMLElement) {\n    const isGrouped = element.classList.contains('is-grouped');\n    return super.isElementShouldBeSelected(element) && (!isGrouped || this.isGroupedMidsSelected(element));\n  }\n\n  protected isGroupedBubbleSelected(bubble: HTMLElement) {\n    const groupedCheckboxInput = this.getCheckboxInputFromElement(bubble);\n    return groupedCheckboxInput?.checked;\n  }\n\n  protected getMidsFromGroupContainer(groupContainer: HTMLElement) {\n    const elements = this.chat.bubbles.getBubbleGroupedItems(groupContainer);\n    if(!elements.length) {\n      elements.push(groupContainer);\n    }\n\n    return elements.map((element) => {\n      return {\n        mid: +element.dataset.mid,\n        peerId: element.dataset.peerId.toPeerId()\n      }\n    });\n  }\n\n  protected isGroupedMidsSelected(groupContainer: HTMLElement) {\n    const mids = this.getMidsFromGroupContainer(groupContainer);\n    const selectedMids = mids.filter(({peerId, mid}) => this.isMidSelected(peerId, mid));\n    return mids.length === selectedMids.length;\n  }\n\n  protected getCheckboxInputFromElement(bubble: HTMLElement) {\n    return bubble.classList.contains('document-container') ?\n      bubble.querySelector('.bubble-select-checkbox > .checkbox-field-input') as HTMLInputElement :\n      super.getCheckboxInputFromElement(bubble);\n  }\n\n  public canSelectBubble(bubble: HTMLElement) {\n    return bubble &&\n      !bubble.classList.contains('service') &&\n      !bubble.classList.contains('is-outgoing') &&\n      !bubble.classList.contains('is-error') &&\n      !bubble.classList.contains('bubble-first') &&\n      !bubble.classList.contains('avoid-selection') &&\n      isSameMessageSelectionGroup(\n        this.selectedMids,\n        bubble.classList.contains('is-ephemeral')\n      );\n  }\n\n  public refreshSelectionGroup() {\n    const isEphemeral = getMessageSelectionGroup(this.selectedMids);\n\n    const groups = new Map<HTMLElement, boolean>();\n    const history = this.bubbles.getRenderedHistory('asc');\n    for(const fullMid of history) {\n      if(this.bubbles.skippedMids.has(fullMid)) {\n        continue;\n      }\n\n      const bubble = this.bubbles.getBubble(fullMid);\n      if(!bubble) {\n        continue;\n      }\n\n      const isCompatible = isEphemeral === undefined ||\n        isEphemeral === bubble.classList.contains('is-ephemeral');\n      bubble.classList.toggle('selection-group-incompatible', !isCompatible);\n      if(this.isSelecting) {\n        this.toggleElementCheckbox(bubble, isCompatible);\n      }\n\n      const group = findUpClassName(bubble, 'bubbles-group');\n      if(group) {\n        groups.set(group, !!groups.get(group) || isCompatible);\n      }\n    }\n\n    for(const [group, hasCompatibleBubble] of groups) {\n      group.classList.toggle('selection-group-incompatible', !hasCompatibleBubble);\n    }\n  }\n\n  protected onToggleSelection = async(forwards: boolean, animate: boolean) => {\n    // Every plate is the same width now, so this just cross-fades.\n    await this.chat.input.center(animate);\n\n    SetTransition({\n      element: this.input.chatInput,\n      className: 'is-selecting',\n      forwards,\n      duration: animate ? 200 : 0\n    });\n\n    SetTransition({\n      element: this.listenElement,\n      className: 'is-selecting',\n      forwards,\n      duration: animate ? 200 : 0,\n      onTransitionEnd: () => {\n        if(!this.isSelecting) {\n          this.removeSelectionContainer();\n          this.selectedText = undefined;\n        }\n      }\n    });\n\n    // * the plate layout depends on the mode — rebuild it if the mode has changed\n    if(\n      this.isSelecting &&\n      this.selectionContainer &&\n      this.selectionContainerForReport !== !!this.isReportSelection\n    ) {\n      this.removeSelectionContainer();\n    }\n\n    if(this.isSelecting && !this.selectionContainer) {\n      this.selectionContainerForReport = !!this.isReportSelection;\n      this.selectionInputWrapper = document.createElement('div');\n      this.selectionInputWrapper.classList.add('chat-input-wrapper', 'selection-wrapper');\n\n      this.containerListenerSetter = new ListenerSetter();\n      const attachClickOptions: AttachClickOptions = {listenerSetter: this.containerListenerSetter};\n\n      this.selectionCountEl = document.createElement('div');\n      this.selectionCountEl.classList.add('selection-container-count');\n\n      if(this.isReportSelection) {\n        // * report-selection mode (tdesktop's choose-for-report): cancel on the left,\n        // * a \"Report N Messages\" action in the centre, nothing on the right\n        const cancelBtn = ButtonIcon('close selection-container-close');\n        attachClickEvent(cancelBtn, () => this.cancelSelection(), attachClickOptions);\n\n        this.selectionReportBtn = Button('btn-primary btn-transparent text-bold chat-input-plate-button selection-container-report');\n        this.selectionReportBtn.append(this.selectionCountEl);\n        attachClickEvent(this.selectionReportBtn, () => {\n          const mids = this.getSelectedMids();\n          const data = this.reportSelectionData;\n          if(!mids.length || !data) {\n            return;\n          }\n\n          showSelectedMessagesReport(this.chat.peerId, mids, data.option, data.text, () => {\n            this.cancelSelection();\n          });\n        }, attachClickOptions);\n\n        this.selectionContainer = ChatInputPlate({\n          class: 'selection-container',\n          left: cancelBtn,\n          center: this.selectionReportBtn\n        }) as HTMLElement;\n      } else {\n        // Centre slot — the \"N selected\" count, styled as a transparent button;\n        // tapping it clears the selection.\n        const countButton = Button('btn-primary btn-transparent text-bold chat-input-plate-button');\n        countButton.append(this.selectionCountEl);\n        attachClickEvent(countButton, () => this.cancelSelection(), attachClickOptions);\n\n        // Left slot — delete.\n        this.selectionDeleteBtn = ButtonIcon('delete danger selection-container-delete');\n        attachClickEvent(this.selectionDeleteBtn, () => {\n          PopupElement.createPopup(\n            PopupDeleteMessages,\n            this.chat.peerId,\n            this.getSelectedMids(),\n            this.chat.type,\n            () => {\n              this.cancelSelection();\n            }\n          );\n        }, attachClickOptions);\n\n        // Right slot — forward (or \"send now\" for scheduled messages).\n        let rightButton: HTMLElement;\n        if(this.chat.type === ChatType.Scheduled) {\n          rightButton = this.selectionSendNowBtn = ButtonIcon('send2 selection-container-send');\n          attachClickEvent(this.selectionSendNowBtn, () => {\n            PopupElement.createPopup(PopupSendNow, this.chat.peerId, [...this.selectedMids.get(this.chat.peerId)], () => {\n              this.cancelSelection();\n            });\n          }, attachClickOptions);\n        } else {\n          rightButton = this.selectionForwardBtn = ButtonIcon('forward selection-container-forward');\n          attachClickEvent(this.selectionForwardBtn, () => {\n            const obj: {[fromPeerId: PeerId]: number[]} = {};\n            for(const [fromPeerId, mids] of this.selectedMids) {\n              obj[fromPeerId] = Array.from(mids).sort((a, b) => a - b);\n            }\n\n            showForwardPopup(obj, () => {\n              this.cancelSelection();\n            });\n          }, attachClickOptions);\n        }\n\n        this.selectionContainer = ChatInputPlate({\n          class: 'selection-container',\n          left: this.selectionDeleteBtn,\n          center: countButton,\n          right: rightButton\n        }) as HTMLElement;\n      }\n\n      this.selectionInputWrapper.style.opacity = '0';\n      this.selectionInputWrapper.append(this.selectionContainer);\n      this.input.inputContainer.append(this.selectionInputWrapper);\n\n      void this.selectionInputWrapper.offsetLeft; // reflow\n      this.selectionInputWrapper.style.opacity = '';\n    }\n  };\n\n  protected onUpdateContainer = (cantForward: boolean, cantDelete: boolean, cantSend: boolean) => {\n    if(!this.selectionCountEl) {\n      return;\n    }\n\n    const length = this.length();\n    if(this.selectionContainerForReport) {\n      replaceContent(\n        this.selectionCountEl,\n        length ? i18n('Report2MessagesCount', [length]) : i18n('Chat.Menu.SelectMessages')\n      );\n    } else {\n      replaceContent(this.selectionCountEl, i18n('messages', [length]));\n    }\n\n    this.selectionSendNowBtn?.toggleAttribute('disabled', cantSend);\n    this.selectionForwardBtn?.toggleAttribute('disabled', cantForward);\n    this.selectionDeleteBtn?.toggleAttribute('disabled', cantDelete);\n    this.selectionReportBtn?.toggleAttribute('disabled', !length);\n  };\n\n  private removeSelectionContainer() {\n    this.containerListenerSetter?.removeAll();\n    this.containerListenerSetter = null;\n    this.selectionInputWrapper.remove();\n    this.selectionInputWrapper =\n      this.selectionContainer =\n      this.selectionCountEl =\n      this.selectionSendNowBtn =\n      this.selectionForwardBtn =\n      this.selectionDeleteBtn =\n      this.selectionReportBtn =\n      null;\n    this.selectionContainerForReport = undefined;\n  }\n\n  protected onCancelSelection = async() => {\n    this.reportSelectionData = undefined;\n    // return;\n    // const promises: Promise<HTMLElement>[] = [];\n    // for(const [peerId, mids] of this.selectedMids) {\n    //   for(const mid of mids) {\n    //     promises.push(this.bubbles.getMountedBubble(mid).then((m) => m?.bubble));\n    //   }\n    // }\n\n    // const bubbles = filterUnique((await Promise.all(promises)).filter(Boolean));\n    // bubbles.forEach((bubble) => {\n    //   this.toggleByElement(bubble);\n    // });\n  };\n}\n","// https://github.com/evgeny-nadymov/telegram-react/blob/master/src/Components/ColumnMiddle/PinnedMessageBorder.js\n\nenum BAR_HEIGHTS {\n  ONE = 40,\n  TWO = 19,\n  THREE = 12,\n  FOUR = 10,\n  MORE = 10\n};\n\nconst GAP = 2;\nconst WIDTH = 3;\nconst BASE_CLASS = 'pinned-message-border';\n\nexport default class PinnedMessageBorder {\n  private border: HTMLElement;\n  private wrapper: HTMLElement;\n  private svg: SVGSVGElement;\n  private defs: SVGDefsElement;\n  private clipPath: SVGClipPathElement;\n  private path: SVGPathElement;\n  private mark: HTMLElement;\n\n  private count: number;\n  private index: number;\n\n  private drawRect = (x: number, y: number, width: number, height: number, radius: number) => {\n    return `M${x},${y + radius}a${radius},${radius},0,0,1,${width},0v${height - 2 * radius}a${radius},${radius},0,0,1,${-width},0Z`;\n  };\n\n  private getClipPath = (id: string, barHeight: number, count: number) => {\n    const radius = 1.5;\n\n    let d = '';\n    /* if(count === 3) {\n      d = this.drawRect(0, 0, WIDTH, barHeight, radius)\n        + this.drawRect(0, barHeight + GAP, WIDTH, barHeight + 1, radius)\n        + this.drawRect(0, barHeight * 2 + GAP * 2 + 1, WIDTH, barHeight, radius);\n    } */if(count === 2) {\n      d = this.drawRect(0, 0, WIDTH, barHeight, radius) + this.drawRect(0, barHeight + GAP * 2, WIDTH, barHeight, radius);\n    } else {\n      for(let i = 0; i < count; ++i) {\n        d += this.drawRect(0, (barHeight + GAP) * i, WIDTH, barHeight, radius);\n      }\n    }\n\n    if(!this.clipPath) {\n      this.clipPath = document.createElementNS('http://www.w3.org/2000/svg', 'clipPath');\n      this.path = document.createElementNS('http://www.w3.org/2000/svg', 'path');\n\n      this.clipPath.append(this.path);\n    }\n\n    this.clipPath.id = id;\n    this.path.setAttributeNS(null, 'd', d);\n\n    return this.clipPath;\n  };\n\n  private getBarHeight = (count: number, index: number) => {\n    let barHeight: number;\n    if(count <= 1) {\n      barHeight = BAR_HEIGHTS.ONE;\n    } else if(count === 2) {\n      barHeight = BAR_HEIGHTS.TWO;\n    } else if(count === 3) {\n      barHeight = BAR_HEIGHTS.THREE;\n    } else if(count === 4) {\n      barHeight = BAR_HEIGHTS.FOUR;\n    } else {\n      barHeight = BAR_HEIGHTS.MORE;\n    }\n\n    return barHeight;\n  };\n\n  private getMarkHeight = (count: number, index: number) => {\n    let markHeight: number;\n    if(count <= 1) {\n      markHeight = BAR_HEIGHTS.ONE;\n    } else if(count === 2) {\n      markHeight = BAR_HEIGHTS.TWO;\n    } else if(count === 3) {\n      markHeight = BAR_HEIGHTS.THREE;\n    } else if(count === 4) {\n      markHeight = BAR_HEIGHTS.FOUR;\n    } else {\n      markHeight = BAR_HEIGHTS.MORE;\n    }\n\n    return markHeight;\n  };\n\n  private getMarkTranslateY = (index: number, barHeight: number, count: number) => {\n    if(count === 1) {\n      return 0;\n    } else if(count === 2) {\n      return !index ? 0 : barHeight + GAP;\n    }\n\n    if(count === 3) {\n      if(!index) {\n        return 0;\n      } else if(index === 1) {\n        return barHeight + GAP;\n      }\n\n      return barHeight * 2 + GAP * 2 + 1;\n    } else {\n      return (barHeight + GAP) * index;\n    }\n  };\n\n  private getTrackTranslateY = (index: number, count: number, barHeight: number, trackHeight: number) => {\n    if(count <= 3) {\n      return 0;\n    }\n\n    if(index <= 1) {\n      return 0;\n    } else if(index >= (count - 2)) {\n      return trackHeight - BAR_HEIGHTS.ONE/*  - barHeight */;\n    }\n\n    // return (index + 1) * barHeight + index * GAP;\n    return (index - 2) * barHeight + index * GAP;\n    // return (barHeight + GAP * 2) / 2 + (index - 2) * (barHeight + GAP);\n  };\n\n  private getTrackHeight = (count: number, barHeight: number) => {\n    return count <= 3 ? BAR_HEIGHTS.ONE : barHeight * count + GAP * (count - 1);\n  };\n\n  public render(count: number, index: number) {\n    if(!this.border) {\n      this.border = document.createElement('div');\n      this.border.classList.add(BASE_CLASS);\n\n      this.wrapper = document.createElement('div');\n      this.border.append(this.wrapper);\n    }\n\n    if(count === 1) {\n      if(this.count !== count) {\n        this.wrapper.className = BASE_CLASS + '-wrapper-1';\n        this.border.classList.remove(BASE_CLASS + '-mask');\n        this.wrapper.replaceChildren();\n        this.wrapper.style.cssText = '';\n      }\n\n      return this.border;\n    }\n\n    const barHeight = this.getBarHeight(count, index);\n    const markHeight = this.getMarkHeight(count, index);\n    const trackHeight = this.getTrackHeight(count, barHeight);\n\n    const clipPathId = `clipPath_${count}`;\n    const clipPath = this.getClipPath(clipPathId, barHeight, count);\n\n    const markTranslateY = this.getMarkTranslateY(index, barHeight, count);\n    const trackTranslateY = this.getTrackTranslateY(index, count, barHeight, trackHeight);\n\n    this.border.classList.toggle(BASE_CLASS + '-mask', count > 4);\n\n    if(index <= 1) {\n      this.border.classList.add('mask-bottom');\n      this.border.classList.remove('mask-top');\n    } else if(index >= (count - 2)) {\n      this.border.classList.add('mask-top');\n      this.border.classList.remove('mask-bottom');\n    } else {\n      this.border.classList.add('mask-top', 'mask-bottom');\n    }\n\n    this.wrapper.className = BASE_CLASS + '-wrapper';\n    this.wrapper.style.cssText = `clip-path: url(#${clipPathId}); width: ${WIDTH}px; height: ${trackHeight}px; transform: translateY(-${trackTranslateY}px);`;\n\n    if(!this.svg) {\n      this.svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n      this.svg.setAttributeNS(null, 'height', '0');\n      this.svg.setAttributeNS(null, 'width', '0');\n\n      this.defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');\n      this.defs.append(clipPath);\n\n      this.svg.append(this.defs);\n\n      this.mark = document.createElement('div');\n      this.mark.classList.add(BASE_CLASS + '-mark');\n    }\n\n    if(!this.svg.parentElement) {\n      this.wrapper.append(this.svg, this.mark);\n    }\n\n    this.mark.style.cssText = `height: ${markHeight}px; transform: translateY(${markTranslateY}px);`;\n\n    this.count = count;\n    this.index = index;\n\n    return this.border;\n  }\n}\n","import type ListenerSetter from '@helpers/listenerSetter';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\n\nexport default function handleScrollSideEvent(elem: HTMLElement, side: 'top' | 'bottom', callback: () => void, listenerSetter: ListenerSetter) {\n  if(IS_TOUCH_SUPPORTED) {\n    let lastY: number;\n    const options = {passive: true};\n    listenerSetter.add(elem)('touchstart', (e) => {\n      if(e.touches.length > 1) {\n        onTouchEnd();\n        return;\n      }\n\n      lastY = e.touches[0].clientY;\n\n      listenerSetter.add(elem)('touchmove', onTouchMove, options);\n      listenerSetter.add(elem)('touchend', onTouchEnd, options);\n    }, options);\n\n    const onTouchMove = (e: TouchEvent) => {\n      const clientY = e.touches[0].clientY;\n\n      const isDown = clientY < lastY;\n      if(side === 'bottom' && isDown) callback();\n      else if(side === 'top' && !isDown) callback();\n      lastY = clientY;\n      // alert('isDown: ' + !!isDown);\n    };\n\n    const onTouchEnd = () => {\n      listenerSetter.removeManual(elem, 'touchmove', onTouchMove, options);\n      listenerSetter.removeManual(elem, 'touchend', onTouchEnd, options);\n    };\n  } else {\n    listenerSetter.add(elem)('wheel', (e) => {\n      const isDown = e.deltaY > 0;\n      // this.log('wheel', e, isDown);\n      if(side === 'bottom' && isDown) callback();\n      else if(side === 'top' && !isDown) callback();\n    }, {passive: true});\n  }\n}\n","import {WebPage} from '@layer';\nimport {UNSAFE_ANCHOR_LINK_TYPES} from '@helpers/addAnchorListener';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\n\n/**\n * Reproduces the click behaviour the bubble web-page renderer attaches to a\n * preview box (see `bubbles.ts` → `messageMediaWebPage`): derive the internal\n * link handler from the page URL via `wrapUrl`, then on click dispatch it\n * through `window[onclick](anchor, e)` — exactly what the bubble does after\n * storing the handler name in `box.dataset.callback`.\n *\n * Factored out so other surfaces (e.g. the pinned-message bar's \"Join\" button)\n * can offer the same action without re-deriving the dispatch. The anchor the\n * handler needs (it only reads `.href`) is synthesised here, so the caller's\n * element can stay a plain button and never navigates on its own.\n *\n * `allowedTypes` restricts which web-page `type`s are actionable — pass\n * `['telegram_call']` so only call previews produce a handler and every other\n * preview type is ignored.\n *\n * `fromId` is the sender of the message the preview belongs to. A rendered\n * message lets a handler climb to its bubble for that, but a surface like the\n * pinned bar has no bubble to climb — so it travels on the anchor instead (the\n * same channel `setMediaTimestamp` uses for its timestamp).\n *\n * Returns the click handler, or `undefined` when the page isn't an allowed\n * type / has no registered internal handler.\n */\nexport default function getWebPageActionOnClick(\n  webPage: WebPage,\n  allowedTypes: WebPage.webPage['type'][],\n  fromId?: PeerId\n): ((e: Event) => void) | undefined {\n  if(webPage._ !== 'webPage' || !allowedTypes.includes(webPage.type)) {\n    return;\n  }\n\n  const wrapped = wrapUrl(webPage.url);\n  const onclick = wrapped.onclick;\n  // `wrapUrl` already nulls `onclick` when the matching `window[onclick]`\n  // handler isn't registered; the UNSAFE check mirrors the renderer's\n  // `hasSafeUrl` gate so masked-alert types never reach here.\n  if(!onclick || UNSAFE_ANCHOR_LINK_TYPES.has(onclick)) {\n    return;\n  }\n\n  return (e) => {\n    // The internal-link handlers (`window.call`, …) only read `.href` off the\n    // passed element — mirror the renderer's safe box with a detached <a>\n    // carrying the wrapped URL and `safe=\"1\"`. Detached, so it never navigates;\n    // the handler cancels the event and routes the slug into `joinConference`.\n    const anchor = document.createElement('a');\n    anchor.href = wrapped.url;\n    anchor.setAttribute('safe', '1');\n    if(fromId) anchor.dataset.fromId = '' + fromId;\n    (window as any)[onclick](anchor, e);\n  };\n}\n","import type ChatTopbar from '@components/chat/topbar';\nimport PopupPinMessage from '@components/popups/unpinMessage';\nimport PinnedMessageBorder from '@components/chat/pinnedMessageBorder';\nimport {wrapReplyDivAndCaption} from '@components/chat/replyContainer';\nimport rootScope from '@lib/rootScope';\nimport Chat from '@components/chat/chat';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport {i18n, I18n} from '@lib/langPack';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport handleScrollSideEvent from '@helpers/dom/handleScrollSideEvent';\nimport debounce from '@helpers/schedulers/debounce';\nimport throttle from '@helpers/schedulers/throttle';\nimport {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport PopupElement from '@components/popups';\nimport {AnimatedSuper} from '@components/animatedSuper';\nimport {AnimatedCounter} from '@components/animatedCounter';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport ButtonIcon from '@components/buttonIcon';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport {getKeyboardButtonHandler} from '@components/wrappers/keyboardButton';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport {FontFullBold} from '@config/font';\nimport {KeyboardButton, Message} from '@layer';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\nimport {createSignal, JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport getWebPageActionOnClick from '@components/chat/getWebPageActionOnClick';\nimport getMessageThreadId from '@appManagers/utils/messages/getMessageThreadId';\n\n/**\n * Top-level body component so solid-refresh can swap it on HMR. All\n * inputs are stable DOM elements / callbacks owned by the factory's\n * closure — the closure (signals, listeners, pin-list state) is\n * preserved across reloads because the factory isn't re-invoked.\n */\nfunction PinnedMessagePlateBody(props: {\n  menu: HTMLElement,\n  actionContainer: HTMLElement,\n  border: JSX.Element,\n  mediaContainer: HTMLElement,\n  subtitleContainer: HTMLElement,\n  counterContainer: HTMLElement,\n  onFollow: () => void\n}) {\n  return (\n    <>\n      {props.menu}\n      <TopbarPlate.Body class=\"hover-primary-effect\" onClick={props.onFollow}>\n        {props.border}\n        <TopbarPlate.Content>\n          {props.mediaContainer}\n          <TopbarPlate.Title>\n            {i18n('PinnedMessage')}\n            {' '}\n            {props.counterContainer}\n          </TopbarPlate.Title>\n          <TopbarPlate.Subtitle>\n            {props.subtitleContainer}\n          </TopbarPlate.Subtitle>\n        </TopbarPlate.Content>\n      </TopbarPlate.Body>\n      {props.actionContainer}\n    </>\n  );\n}\n\nconst LOAD_COUNT = 50;\nconst LOAD_OFFSET = 5;\n\nexport type ChatPinnedMessageController = TopbarPlateController & {\n  /** Mutable \"user has hidden the plate\" flag (matches old `pinnedMessage.hidden`). */\n  setUserHidden: (hidden: boolean) => void,\n  isUserHidden: () => boolean,\n  /** Read-only \"currently following a click — ignore scroll\" flag. */\n  isLocked: () => boolean,\n\n  /** Push the bottom-visible bubble's mid; recomputes which pin to show. */\n  testMid: (mid: number, lastScrollDirection?: number) => void,\n  setCorrectIndex: (lastScrollDirection?: number) => void,\n  setCorrectIndexThrottled: (lastScrollDirection?: number) => void,\n  handleFollowingPinnedMessage: () => Promise<void>,\n  unsetScrollDownListener: (refreshPosition?: boolean) => void,\n\n  /**\n   * Discussion-mode: forces the plate to display a single static message\n   * (the thread root) without paging or scroll tracking.\n   */\n  setStaticMessage: (mid: number) => void,\n\n  /**\n   * Currently displayed plate state, or undefined when no pin is shown.\n   * Captured on chat exit into `ChatSavedPosition.pinnedMessages` so the\n   * next `prepareInitial` can restore the exact same view (mid + index\n   * within the pinned list + total count) atomically with bubbles.\n   */\n  readonly pinnedMessages: {mid: number, index: number, count: number} | undefined,\n  /**\n   * Populate state and content from a hint (saved plate state or just a\n   * mid from `fullPeer.pinned_msg_id`) but keep the plate visually hidden.\n   * Pair with `revealPrepared`, called sync from `topbar.finishPeerChange`\n   * after `Promise.all(promises)` so plate and bubbles paint together.\n   * Returns a promise that resolves once `prepared` flips true.\n   */\n  prepareInitial: (data: {mid: number, index?: number, count?: number}) => Promise<void>,\n  /** Flip the prepared plate visible. No-op if `prepareInitial` was skipped. */\n  revealPrepared: () => void\n};\n\nexport default function createChatPinnedMessage(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatPinnedMessageController {\n  const log = logger('PM');\n  const debug = true;\n\n  // Imperative animation pieces — kept as-is per refactor scope; only refs are\n  // threaded through JSX below.\n  const animatedSubtitle = new AnimatedSuper();\n  const animatedMedia = new AnimatedSuper();\n  animatedMedia.container.classList.add('pinned-message-media-container');\n  const animatedCounter = new AnimatedCounter({reverse: true});\n  const pinnedMessageBorder = new PinnedMessageBorder();\n  let wasPinnedIndex = 0;\n  let wasPinnedMediaIndex = 0;\n  let customButtonMiddleware: MiddlewareHelper | undefined;\n  /**\n   * Bumped by every `_setPinnedMessage` run. The function awaits content\n   * wrapping, and the debounce can have two runs in flight (first + last), so a\n   * slower earlier run must not commit its pin over the newer one.\n   */\n  let renderSeq = 0;\n  /** Pending `is-leaving` action-button removals, cleared on destroy. */\n  const leavingButtonTimeouts = new Set<number>();\n\n  // Listeners — top-level for the lifetime of this plate, plus a transient\n  // one for the wait-for-bottom-scroll flow.\n  const listenerSetter = new ListenerSetter();\n  let scrollDownListenerSetter: ListenerSetter | undefined;\n\n  // State (closure vars — were class fields).\n  let mids: number[] = [];\n  let offsetIndex = 0;\n  let count = 0;\n  let pinnedIndex = -1;\n  let pinnedMid = 0;\n  let pinnedMaxMid = 0;\n  let loadedTop = false;\n  let loadedBottom = false;\n  let waitForScrollBottom = false;\n  let getCurrentIndexPromise: Promise<any> | undefined;\n  let loading = false;\n  let userHidden = false;\n  let locked = false;\n  const isStatic = !chat.isPinnedMessagesNeeded();\n\n  // Captured from inside the plate's render fn — drives `hide` class.\n  let plateSetHidden!: (hidden: boolean) => void;\n  // True when `prepareInitial` has populated state/content but the visual\n  // reveal is deferred until `revealPrepared` is called — so the plate\n  // flips visible in the same paint frame as bubbles mount.\n  let prepared = false;\n\n  // Reactive flags applied to the plate root via `createTopbarPlate({class})`\n  // so we don't mutate `plate.container.classList` from imperative paths.\n  const [isMedia, setIsMedia] = createSignal(false);\n  const [isMany, setIsMany] = createSignal(false);\n  const [hasCustomActionButton, setHasCustomActionButton] = createSignal(false);\n\n  // ────────────────────────────────────────────────────────────────────────\n  // DOM bits that live as siblings of the Body inside the plate root.\n  // ────────────────────────────────────────────────────────────────────────\n\n  const menu = ButtonMenuToggle({\n    direction: 'bottom-right',\n    buttons: [{\n      icon: 'pinlist',\n      text: 'PinnedMessages',\n      onClick: () => {\n        topbar.openPinned(true);\n      },\n      verify: () => true\n    }, {\n      icon: 'unpin',\n      text: 'UnpinMessage',\n      onClick: () => {\n        PopupElement.createPopup(PopupPinMessage, chat.peerId, pinnedMid, true, undefined, chat.threadId);\n      },\n      verify: () => managers.appPeersManager.canPinMessage(chat.peerId)\n    }, {\n      icon: 'eyecross',\n      text: 'Popup.Unpin.HideTitle',\n      onClick: () => {\n        PopupElement.createPopup(PopupPinMessage, chat.peerId, 0, true, undefined, chat.threadId);\n      },\n      verify: async() => !(await managers.appPeersManager.canPinMessage(chat.peerId))\n    }],\n    listenerSetter,\n    icon: 'pin'\n  });\n  menu.classList.add('pinned-message-menu');\n\n  const btnUnpin = ButtonIcon('close pinned-message-unpin');\n  attachClickEvent(btnUnpin, async(e) => {\n    cancelEvent(e);\n    const canPin = await managers.appPeersManager.canPinMessage(chat.peerId);\n    PopupElement.createPopup(\n      PopupPinMessage,\n      chat.peerId,\n      canPin ? pinnedMid : 0,\n      true,\n      undefined,\n      chat.threadId\n    );\n  }, {listenerSetter});\n\n  const actionContainer = document.createElement('div');\n  actionContainer.classList.add('pinned-message-action');\n  actionContainer.append(btnUnpin);\n\n  // ────────────────────────────────────────────────────────────────────────\n  // Plate\n  // ────────────────────────────────────────────────────────────────────────\n\n  const plate = createTopbarPlate({\n    modifier: 'message',\n    height: 48,\n    initiallyHidden: true,\n    class: () => classNames(\n      isMedia() && 'is-media',\n      isMany() && 'is-many',\n      hasCustomActionButton() && 'has-custom-action-button'\n    ),\n    onVisibilityChange: () => topbar.setFloating(),\n    render: ({setHidden}) => {\n      plateSetHidden = setHidden;\n      return (\n        <PinnedMessagePlateBody\n          menu={menu}\n          actionContainer={actionContainer}\n          border={pinnedMessageBorder.render(1, 0)}\n          mediaContainer={animatedMedia.container}\n          subtitleContainer={animatedSubtitle.container}\n          counterContainer={animatedCounter.container}\n          onFollow={() => followPinnedMessage(pinnedMid)}\n        />\n      );\n    }\n  });\n\n  // ────────────────────────────────────────────────────────────────────────\n  // rootScope listeners\n  // ────────────────────────────────────────────────────────────────────────\n\n  /**\n   * Does a pin update touch the list this plate renders? A thread-scoped update\n   * (unpin-all inside a topic) names its topic; a plain pin/unpin update names\n   * none, so resolve it from the messages themselves — otherwise pinning in one\n   * topic would reset and refetch the plate of every other open topic.\n   */\n  function isOurPinUpdate(threadId: number | undefined, updatedMids: number[] | undefined) {\n    if(threadId) return threadId === chat.threadId;\n    if(!chat.threadId || !chat.isForum || !updatedMids?.length) return true;\n    return updatedMids.some((mid) => {\n      const message = chat.getMessage(mid);\n      // not cached — can't rule it out, so assume it's ours and refetch\n      return !message || getMessageThreadId(message, {isForum: true}) === chat.threadId;\n    });\n  }\n\n  // * `updatedMids`, not `mids`: the closure's own `mids` (this plate's pin list)\n  // * is reset below and must not be shadowed by the event payload\n  listenerSetter.add(rootScope)('peer_pinned_messages', ({peerId, threadId, mids: updatedMids}) => {\n    if(peerId !== chat.peerId || !isOurPinUpdate(threadId, updatedMids)) return;\n    // A pin update clears the persisted hidden state (`resetPinnedMessagesCache`),\n    // so drop the local flag too — but leave the plate hidden: `_setPinnedMessage`\n    // reveals it once we know what to show. Revealing here would flash the\n    // previous pin, or an empty plate when the last one was just removed.\n    userHidden = false;\n\n    // Anchor the post-update display at the pin the user was looking at\n    // — `setCorrectIndex(0)` would derive the new pin from whatever bubble\n    // is at the viewport bottom, and after following a mid-list pin the\n    // bottom-visible bubble usually has a mid greater than every remaining\n    // pin, so the plate would snap to the newest pin (mids[0]) regardless\n    // of where the user was browsing.\n    //\n    // That only applies while the user is actually walking the pin list\n    // (`followPinnedMessage` sets `locked` / `waitForScrollBottom`, and the\n    // plate then deliberately shows an older pin than the viewport implies).\n    // Anywhere else the viewport is the truth — pinning a new message while\n    // sitting at the bottom of the chat must move the plate onto that new\n    // pin, not keep the previous one with a bumped counter.\n    // `waitForScrollBottom` is cleared by the first downward wheel/touch, so it\n    // can still be set while the user is already sitting at the end of the\n    // history (chat opened on an unread message just above the bottom). Reading\n    // the viewport keeps the invariant: at the end of the chat the plate shows\n    // the newest pin.\n    const scrollable = chat.bubbles.scrollable;\n    const atHistoryEnd = scrollable.loadedAll.bottom && scrollable.isScrolledToEnd;\n    const anchorMid = locked || (waitForScrollBottom && !atHistoryEnd) ? pinnedMid : 0;\n\n    loadedTop = loadedBottom = false;\n    pinnedIndex = -1;\n    pinnedMid = 0;\n    count = 0;\n    mids = [];\n    offsetIndex = 0;\n    pinnedMaxMid = 0;\n\n    if(anchorMid) {\n      // Fetch around the anchor so the new mids window contains its\n      // neighbours, then re-position at the anchor. If still pinned,\n      // testMid finds it exactly; if unpinned, it falls onto the\n      // next-older pin (the one now occupying the same slot).\n      const promise = getCurrentIndexPromise ??= getCurrentIndex(anchorMid, false);\n      promise.then(() => {\n        if(count) testMid(anchorMid);\n      });\n    } else {\n      setCorrectIndex(0);\n    }\n  });\n\n  listenerSetter.add(rootScope)('peer_pinned_hidden', ({peerId, threadId}) => {\n    // hiding is per-peer / per-topic, so it must match this plate's scope exactly\n    if(peerId !== chat.peerId || (threadId || undefined) !== (chat.threadId || undefined)) return;\n    userHidden = true;\n    plateSetHidden(true);\n  });\n\n  // ────────────────────────────────────────────────────────────────────────\n  // Implementation\n  // ────────────────────────────────────────────────────────────────────────\n\n  const setPinnedMessageDebounced = debounce(() => _setPinnedMessage(), 100, true, true);\n\n  function setCorrectIndex(lastScrollDirection?: number) {\n    const bound = log.bindPrefix('setCorrectIndex');\n    if(isStatic) {\n      debug && bound('not needed, static');\n      return;\n    }\n\n    if(locked || userHidden) {\n      debug && bound('not needed 1');\n      return;\n    }\n\n    if((loadedBottom || loadedTop) && !count) {\n      debug && bound('not needed 2');\n      return;\n    }\n\n    const el = chat.bubbles.getBubbleByPoint('bottom');\n    if(!el) {\n      debug && bound('no element');\n      return;\n    }\n\n    const mid = el.dataset.mid;\n    debug && bound('direction', lastScrollDirection, 'mid', mid);\n    if(mid !== undefined) {\n      testMid(+mid, lastScrollDirection);\n    }\n  }\n\n  const setCorrectIndexThrottled = throttle(setCorrectIndex, 100, false);\n\n  function testMid(mid: number, lastScrollDirection?: number) {\n    if(isStatic) return;\n    if(userHidden) return;\n    // Same guard as `setCorrectIndex`: the list is loaded and there is nothing\n    // pinned here. Without it every direct `testMid` (the topbar fires one on\n    // each jump-to-message) falls through to another `getCurrentIndex` fetch.\n    if((loadedBottom || loadedTop) && !count) return;\n\n    let currentIndex: number = mids.findIndex((_mid) => _mid <= mid);\n    if(currentIndex !== -1 && !isNeededMore(currentIndex)) {\n      currentIndex += offsetIndex;\n    } else if(loadedTop && mid < mids[mids.length - 1]) {\n      currentIndex = mids.length - 1 + offsetIndex;\n    } else {\n      return getCurrentIndexPromise ??= getCurrentIndex(mid, lastScrollDirection !== undefined);\n    }\n\n    const newPinnedMid = mids.find((_mid) => _mid <= mid) || mids[mids.length - 1];\n    // Also detect pin-mid drift at the same numeric index — e.g. a new pin\n    // pushed the previous \"newest\" down, so `pinnedIndex=0` still matches\n    // but the actual pin at that slot is different. Without this check\n    // the plate would keep rendering the stale hint after the server data\n    // resolves.\n    const changed = pinnedIndex !== currentIndex || pinnedMid !== newPinnedMid;\n    if(changed) {\n      if(waitForScrollBottom && lastScrollDirection !== undefined) {\n        if(pinnedIndex === 0 || pinnedIndex > currentIndex) { // если не скроллил вниз и пытается поставить нижний пиннед - выйти\n          return;\n        }\n      }\n\n      pinnedIndex = currentIndex;\n      pinnedMid = newPinnedMid;\n      return setPinnedMessageDebounced();\n    }\n  }\n\n  function isNeededMore(currentIndex: number) {\n    return (count > LOAD_COUNT &&\n      (\n        (!loadedBottom && currentIndex <= LOAD_OFFSET) ||\n        (!loadedTop && (count - 1 - currentIndex) <= LOAD_OFFSET)\n      )\n    );\n  }\n\n  async function getCurrentIndex(mid: number, correctAfter = true) {\n    if(loading) return;\n    loading = true;\n\n    try {\n      const bound = debug ? log.bindPrefix('getCurrentIndex') : undefined;\n      bound && bound('start', mid, correctAfter);\n\n      let gotRest = false;\n      const promises = [\n        managers.appMessagesManager.getHistory({\n          peerId: chat.peerId,\n          inputFilter: {_: 'inputMessagesFilterPinned'},\n          offsetId: mid,\n          limit: LOAD_COUNT,\n          backLimit: LOAD_COUNT,\n          threadId: chat.threadId,\n          needRealOffsetIdOffset: true\n        }).then((r) => {\n          gotRest = true;\n          return r;\n        })\n      ];\n\n      if(!pinnedMaxMid) {\n        const promise = managers.appMessagesManager.getPinnedMessage(\n          chat.peerId,\n          chat.threadId\n        ).then((p) => {\n          if(!p.maxId) return;\n          pinnedMaxMid = p.maxId;\n\n          if(!gotRest && correctAfter) {\n            mids = [pinnedMaxMid];\n            count = p.count;\n            pinnedIndex = 0;\n            pinnedMid = mids[0];\n            setPinnedMessageDebounced();\n          }\n        });\n\n        promises.push(promise as any);\n      }\n\n      const result = (await Promise.all(promises))[0];\n\n      const history = result.history;\n\n      let backLimited = history.findIndex((_mid) => _mid <= mid);\n      if(backLimited === -1) {\n        backLimited = history.length;\n      }\n\n      offsetIndex = Math.max(0, result.offsetIdOffset) ? result.offsetIdOffset - backLimited : 0;\n      const oldCount = count;\n      const oldPinnedMid = pinnedMid;\n      mids = history.slice();\n      count = result.count;\n\n      if(!count) {\n        // Nothing is pinned in this scope — drop the pin we were showing so\n        // the `pinnedMessages` getter stops reporting a phantom hint into\n        // `ChatSavedPosition`, which would re-seed (and re-flash) the plate\n        // on the next open of this peer/topic.\n        pinnedMid = 0;\n        pinnedIndex = -1;\n        plateSetHidden(true);\n      }\n\n      loadedTop = (offsetIndex + mids.length) === count;\n      loadedBottom = !offsetIndex;\n\n      bound && bound('result', mid, result, backLimited, offsetIndex, loadedTop, loadedBottom);\n\n      // If `prepareInitial` seeded a stale hint (e.g. count=1 from\n      // `fullPeer.pinned_msg_id` while the real pinned count is 2, or a\n      // new pin was added that shifted what mids[0] is), the upcoming\n      // `setCorrectIndex` → `testMid` may not fully reconcile in one\n      // task: it sees the same numeric `pinnedIndex` and skips. Reconcile\n      // `pinnedMid` against the fresh window here so the sync first\n      // `_setPinnedMessage` already paints with the right pin.\n      const reconciledMid = mids[pinnedIndex - offsetIndex];\n      if(oldCount !== count || (reconciledMid && oldPinnedMid !== reconciledMid)) {\n        if(reconciledMid) pinnedMid = reconciledMid;\n        setPinnedMessageDebounced();\n      }\n    } catch(err) {\n      log.error('getCurrentIndex error', err);\n    }\n\n    loading = false;\n    // Clear before the calls below: either of them may start a fresh fetch and\n    // store its promise here — resetting afterwards would drop that reference\n    // and let the next caller kick off a duplicate request.\n    getCurrentIndexPromise = undefined;\n\n    if(locked) {\n      testMid(mid);\n    } else if(correctAfter) {\n      setCorrectIndex(0);\n    }\n  }\n\n  function setScrollDownListener() {\n    waitForScrollBottom = true;\n\n    if(!scrollDownListenerSetter) {\n      scrollDownListenerSetter = new ListenerSetter();\n      handleScrollSideEvent(chat.bubbles.scrollable.container, 'bottom', () => {\n        unsetScrollDownListener();\n      }, scrollDownListenerSetter);\n    }\n  }\n\n  function unsetScrollDownListener(refreshPosition = true) {\n    waitForScrollBottom = false;\n\n    if(scrollDownListenerSetter) {\n      scrollDownListenerSetter.removeAll();\n      scrollDownListenerSetter = undefined;\n    }\n\n    if(refreshPosition) {\n      setCorrectIndex(0);\n    }\n  }\n\n  async function handleFollowingPinnedMessage() {\n    locked = true;\n\n    debug && log('handleFollowingPinnedMessage');\n    try {\n      setScrollDownListener();\n\n      const setPeerPromise = chat.setPeerPromise;\n      if(setPeerPromise instanceof Promise) {\n        await setPeerPromise;\n      }\n\n      await getHeavyAnimationPromise();\n\n      getCurrentIndexPromise && await getCurrentIndexPromise;\n\n      debug && log('handleFollowingPinnedMessage: unlock');\n      locked = false;\n    } catch(err) {\n      log.error('handleFollowingPinnedMessage error:', err);\n\n      locked = false;\n      waitForScrollBottom = false;\n      setCorrectIndex(0);\n    }\n  }\n\n  function followPinnedMessage(mid: number) {\n    const message = chat.getMessage(mid);\n    if(!message) {\n      return;\n    }\n\n    chat.setMessageId({lastMsgId: mid});\n    (chat.setPeerPromise || Promise.resolve()).then(() => { // * debounce fast clicker\n      handleFollowingPinnedMessage();\n      // wrap to the newest pin from the last one. `pinnedMaxMid` is still 0 when\n      // the plate was painted from a hint and nothing has been fetched yet —\n      // `testMid(0)` would land on the OLDEST pin, reversing the cycle.\n      const wrapMid = pinnedMaxMid || mids[0] || mid;\n      testMid(pinnedIndex >= (count - 1) ? wrapMid : mid - 1);\n    });\n  }\n\n  async function _setPinnedMessage(skipReveal = false) {\n    const seq = ++renderSeq;\n    if(count) {\n      const message = chat.getMessage(pinnedMid);\n\n      const isLast = pinnedIndex === 0;\n      animatedCounter.container.classList.toggle('is-last', isLast);\n      if(!isLast) {\n        animatedCounter.setCount(count - pinnedIndex);\n      }\n\n      const fromTop = pinnedIndex > wasPinnedIndex;\n      debug && log('setPinnedMessage: fromTop', fromTop, pinnedIndex, wasPinnedIndex);\n\n      const writeTo = animatedSubtitle.getRow(pinnedIndex);\n      const writeMediaTo = animatedMedia.getRow(pinnedIndex);\n      writeMediaTo.classList.add('pinned-message-media');\n      const loadPromises: Promise<any>[] = [];\n      const isMediaSet = await wrapReplyDivAndCaption({\n        titleEl: null,\n        subtitleEl: writeTo,\n        message,\n        mediaEl: writeMediaTo,\n        loadPromises,\n        animationGroup: chat.animationGroup,\n        isSensitive: chat.isSensitive || isMessageSensitive(message),\n        textColor: 'primary-text-color',\n        canTranslate: !message.pFlags.out,\n        middleware: animatedSubtitle.getRow(pinnedIndex).middlewareHelper.get()\n      });\n\n      await Promise.all(loadPromises);\n\n      // a newer run started while we were wrapping — it owns the plate now\n      if(seq !== renderSeq) {\n        return;\n      }\n\n      setIsMedia(isMediaSet);\n\n      // Flip the plate visible only after content (text + media) is in\n      // the DOM — otherwise the user sees an empty plate for a paint\n      // frame while wrapReplyDivAndCaption is still resolving.\n      if(!skipReveal) {\n        plateSetHidden(false);\n      }\n\n      animatedSubtitle.animate(pinnedIndex, wasPinnedIndex);\n      if(isMediaSet) {\n        animatedMedia.animate(pinnedIndex, wasPinnedMediaIndex);\n        wasPinnedMediaIndex = pinnedIndex;\n      } else {\n        animatedMedia.clearRows();\n      }\n\n      pinnedMessageBorder.render(count, count - pinnedIndex - 1);\n      wasPinnedIndex = pinnedIndex;\n      plate.container.dataset.mid = '' + message.mid;\n      updateActionButton(message as Message.message);\n    } else {\n      plateSetHidden(true);\n      wasPinnedIndex = 0;\n      // nothing to open anymore — `topbar.openPinned(true)` reads this\n      delete plate.container.dataset.mid;\n      updateActionButton();\n    }\n\n    setIsMany(count > 1);\n  }\n\n  function getSingleInlineButton(message?: Message.message): KeyboardButton | undefined {\n    const replyMarkup = message?.reply_markup;\n    if(replyMarkup?._ !== 'replyInlineMarkup') return;\n    const rows = replyMarkup.rows;\n    if(rows.length !== 1 || rows[0].buttons.length !== 1) return;\n    const button = rows[0].buttons[0];\n    return button.text ? button : undefined;\n  }\n\n  function updateActionButton(message?: Message.message) {\n    const oldBtn = actionContainer.querySelector(\n      '.pinned-container-action-button:not(.is-leaving)'\n    ) as HTMLElement | null;\n    const oldMiddleware = customButtonMiddleware;\n    customButtonMiddleware = undefined;\n\n    let newBtn: HTMLElement | undefined;\n    let buttonText: string | undefined;\n\n    // Join-call button: when the pinned message is a `telegram_call` web-page\n    // preview, reuse the exact onclick the bubble web-page renderer attaches\n    // (wrapUrl → internal-link dispatch), gated to that single type so no other\n    // preview type produces an action here. Labelled `PinnedJoinCall`.\n    const media = message?.media;\n    const webPage = media?._ === 'messageMediaWebPage' ? media.webpage : undefined;\n    const onCallClick = webPage && getWebPageActionOnClick(webPage, ['telegram_call'], message.fromId);\n\n    if(onCallClick) {\n      buttonText = I18n.format('PinnedJoinCall', true);\n      newBtn = createCustomActionButton({\n        text: i18n('PinnedJoinCall'),\n        onClick: onCallClick\n      });\n    } else {\n      const button = getSingleInlineButton(message);\n      if(button) {\n        const middleware = getMiddleware();\n        const handler = getKeyboardButtonHandler({\n          button,\n          chat,\n          message,\n          wrapOptions: {\n            middleware: middleware.get(),\n            textColor: 'white'\n          }\n        });\n\n        if(handler) {\n          buttonText = button.text;\n          newBtn = createCustomActionButton({\n            text: handler.text,\n            onClick: handler.onClick,\n            as: handler.as\n          });\n          handler.refCallbacks.forEach((cb) => cb(newBtn));\n          customButtonMiddleware = middleware;\n        } else {\n          middleware.destroy();\n        }\n      }\n    }\n\n    if(newBtn) {\n      actionContainer.append(newBtn);\n\n      // Measure the actual button width: text + horizontal padding (1rem each side = 32px),\n      // capped at the button's max-width (10rem = 160px). Add a small gap so the wrapper\n      // text doesn't run flush against the button.\n      const BUTTON_PADDING_X = 32;\n      const BUTTON_MAX_WIDTH = 160;\n      const TEXT_TO_BUTTON_GAP = 8;\n      const textWidth = getTextWidth(buttonText, FontFullBold);\n      const buttonWidth = Math.min(Math.ceil(textWidth) + BUTTON_PADDING_X, BUTTON_MAX_WIDTH) - 48;\n      plate.container.style.setProperty('--action-button-width', `${buttonWidth + TEXT_TO_BUTTON_GAP}px`);\n    }\n\n    setHasCustomActionButton(!!newBtn);\n\n    if(oldBtn) {\n      oldBtn.classList.add('is-leaving');\n      const timeout = window.setTimeout(() => {\n        leavingButtonTimeouts.delete(timeout);\n        oldBtn.remove();\n        oldMiddleware?.destroy();\n      }, 200);\n      leavingButtonTimeouts.add(timeout);\n    }\n  }\n\n  /**\n   * Build the cross-fading action button. The TopbarPlate.ActionButton primitive\n   * is intentionally JSX-only; here we need an imperative one because the swap\n   * (old.is-leaving + remove after 200ms) is driven from `updateActionButton`.\n   */\n  function createCustomActionButton(opts: {\n    text: HTMLElement | DocumentFragment | string,\n    onClick?: (e: Event) => void,\n    as?: 'button' | 'a'\n  }): HTMLElement {\n    const btn = document.createElement(opts.as || 'button');\n    btn.classList.add(\n      'pinned-container-action-button',\n      'pinned-message-action-button',\n      'text-overflow-no-wrap'\n    );\n    if(typeof opts.text === 'string') {\n      btn.textContent = opts.text;\n    } else {\n      btn.append(opts.text);\n    }\n    if(opts.onClick) {\n      attachClickEvent(btn, opts.onClick, {listenerSetter});\n    }\n    return btn;\n  }\n\n  // ────────────────────────────────────────────────────────────────────────\n  // Controller\n  // ────────────────────────────────────────────────────────────────────────\n\n  const controller: ChatPinnedMessageController = {\n    container: plate.container,\n    height: plate.height,\n    hidden: plate.hidden,\n    setHidden: plate.setHidden,\n    isVisible: plate.isVisible,\n    isUserHidden: () => userHidden,\n    setUserHidden: (v: boolean) => {\n      userHidden = v;\n      if(v) plateSetHidden(true);\n      else if(count > 0) plateSetHidden(false);\n    },\n    isLocked: () => locked,\n    testMid,\n    setCorrectIndex,\n    setCorrectIndexThrottled,\n    handleFollowingPinnedMessage,\n    unsetScrollDownListener,\n    setStaticMessage: (mid: number) => {\n      pinnedMid = mid;\n      count = 1;\n      pinnedIndex = 0;\n      _setPinnedMessage();\n    },\n    get pinnedMessages() {\n      return pinnedMid ? {mid: pinnedMid, index: pinnedIndex, count} : undefined;\n    },\n    prepareInitial: async({mid, index, count: hintCount}) => {\n      if(userHidden || !mid || pinnedMid === mid) return;\n      if(!chat.getMessage(mid)) return;\n      pinnedMid = mid;\n      pinnedIndex = index ?? 0;\n      count = Math.max(hintCount ?? 1, pinnedIndex + 1);\n      await _setPinnedMessage(true);\n      prepared = true;\n    },\n    revealPrepared: () => {\n      if(!prepared) return;\n      prepared = false;\n      // the real list resolved to empty while we were preparing — nothing to show\n      if(!count) return;\n      plateSetHidden(false);\n    },\n    destroy: () => {\n      // deferred work would otherwise run against destroyed rows / a detached plate\n      setPinnedMessageDebounced.clearTimeout();\n      setCorrectIndexThrottled.clear();\n      leavingButtonTimeouts.forEach((timeout) => window.clearTimeout(timeout));\n      leavingButtonTimeouts.clear();\n      animatedMedia.destroy();\n      animatedSubtitle.destroy();\n      animatedCounter.destroy();\n      customButtonMiddleware?.destroy();\n      customButtonMiddleware = undefined;\n      listenerSetter.removeAll();\n      unsetScrollDownListener(false);\n      plate.destroy();\n    }\n  };\n\n  return controller;\n}\n","import AudioAssetPlayer from '@helpers/audioAssetPlayer';\n\nlet audioAsset: AudioAssetPlayer<Record<'connect' | 'end' | 'start' | 'allowtalk', string>>;\nexport default function getGroupCallAudioAsset() {\n  return audioAsset ??= new AudioAssetPlayer({\n    connect: 'group_call_connect.mp3',\n    end: 'group_call_end.mp3',\n    start: 'group_call_start.mp3',\n    allowtalk: 'voip_onallowtalk.mp3'\n  });\n}\n","/*\n * https://github.com/morethanwords/tweb\n * Copyright (C) 2019-2026 Eduard Kuzmenko\n * https://github.com/morethanwords/tweb/blob/master/LICENSE\n */\n\n/**\n * A FIFO promise queue: each enqueued operation starts only after every\n * previously enqueued one has settled. The internal tail swallows rejections —\n * one failed operation must never wedge the queue — while the promise\n * `enqueue` returns still resolves/rejects with that operation's own outcome.\n *\n * This is THE serializer for \"one at a time, in order\" async work (chain block\n * application, media transitions, worker RPC). Hand-rolling the tail is how a\n * copy loses its rejection handler and bricks its queue forever.\n */\nexport interface SerializedQueue {\n  enqueue<T>(operation: () => T | Promise<T>): Promise<T>;\n}\n\nexport default function createSerializedQueue(): SerializedQueue {\n  let tail: Promise<unknown> = Promise.resolve();\n  return {\n    enqueue<T>(operation: () => T | Promise<T>): Promise<T> {\n      const run = tail.then(operation);\n      tail = run.then((): undefined => undefined, (): undefined => undefined);\n      return run;\n    }\n  };\n}\n","export type MyMediaTrackSupportedConstraints = MediaTrackSupportedConstraints & {\n  noiseSuppression?: boolean,\n  autoGainControl?: boolean\n};\n\nexport default function constraintSupported(constraint: keyof MyMediaTrackSupportedConstraints) {\n  return (!!navigator?.mediaDevices?.getSupportedConstraints() as any as MyMediaTrackSupportedConstraints)[constraint];\n}\n","import constraintSupported, {MyMediaTrackSupportedConstraints} from '@environment/constraintSupport';\nimport {appSettings} from '@stores/appSettings';\n\n// `deviceId` opt-in: callers pass the persisted choice from\n// `appSettings.callDevices.microphoneId`; the helper falls back to the store\n// directly so older call sites that built the constraints without explicit\n// args keep using the saved device. Empty string ⇒ no constraint ⇒ OS default.\n//\n// `noiseSuppression` honours the in-call toggle exposed in the settings\n// popup; the other audio-DSP constraints (echo cancellation, auto gain) stay\n// always-on because they have no user-facing switch yet and disabling either\n// makes a call dramatically worse for the remote side.\nexport default function getAudioConstraints(deviceId?: string): MediaTrackConstraints {\n  const constraints: MediaTrackConstraints = {\n    channelCount: 2\n  };\n\n  const desirable: (keyof MyMediaTrackSupportedConstraints)[] = [\n    'echoCancellation',\n    'autoGainControl'\n  ];\n\n  desirable.forEach((constraint) => {\n    if(constraintSupported(constraint)) {\n      // @ts-ignore\n      constraints[constraint] = true;\n    }\n  });\n\n  // `noiseSuppression` defaults to true (legacy behavior) — opt-out via the\n  // call settings toggle when the user wants to capture ambient sound.\n  if(constraintSupported('noiseSuppression')) {\n    const enabled = appSettings.callDevices?.noiseSuppression ?? true;\n    constraints.noiseSuppression = enabled;\n  }\n\n  const id = deviceId ?? appSettings.callDevices?.microphoneId;\n  if(id) {\n    constraints.deviceId = {exact: id};\n  }\n\n  return constraints;\n}\n","export default function getScreenConstraints(skipAudio?: boolean) {\n  const constraints: DisplayMediaStreamOptions = {\n    video: {\n      // @ts-ignore\n      // cursor: 'always',\n      width: {max: 1920},\n      height: {max: 1080},\n      frameRate: {max: 30}\n    }\n  };\n\n  if(!skipAudio) {\n    constraints.audio = true;\n  }\n\n  return constraints;\n}\n","export default async function getScreenStream(constraints: DisplayMediaStreamOptions) {\n  const screenStream = await navigator.mediaDevices.getDisplayMedia(constraints);\n  const track = screenStream.getVideoTracks()[0];\n  track.contentHint = 'text';\n  return screenStream;\n}\n","import DEBUG, {MOUNT_CLASS_TO} from '@config/debug';\nimport getScreenStream from '@lib/calls/helpers/getScreenStream';\nimport getStream from '@lib/calls/helpers/getStream';\n\n/**\n * ! Use multiple constraints together only with first invoke\n */\nexport default function getStreamCached() {\n  const _cache: {\n    main: Partial<{\n      audio: Promise<MediaStream>,\n      video: Promise<MediaStream>\n    }>,\n    screen: Partial<{\n      audio: Promise<MediaStream>,\n      video: Promise<MediaStream>\n    }>\n  } = {\n    main: {},\n    screen: {}\n  };\n\n  return async(options: {\n    isScreen: true,\n    constraints: DisplayMediaStreamOptions,\n  } | {\n    isScreen?: false,\n    constraints: MediaStreamConstraints,\n    muted: boolean\n  }) => {\n    const {isScreen, constraints} = options;\n    const cache = _cache[isScreen ? 'screen' : 'main'];\n    let promise: Promise<MediaStream> = cache[constraints.audio ? 'audio' : 'video'];\n\n    if(!promise) {\n      promise = (isScreen ? getScreenStream : getStream)(constraints, (options as any).muted);\n      if(constraints.audio && !cache.audio) cache.audio = promise.finally(() => cache.audio = undefined);\n      if(constraints.video && !cache.video) cache.video = promise.finally(() => cache.video = undefined);\n    }\n\n    try {\n      return await promise;\n      /* let out: Partial<{\n        audio: MediaStream,\n        video: MediaStream\n      }> = {};\n\n      await Promise.all([\n        constraints.audio && cache.audio.then((stream) => out.audio = stream),\n        constraints.video && cache.video.then((stream) => out.video = stream)\n      ].filter(Boolean));\n\n      return out; */\n    } catch(err) {\n      throw err;\n    }\n  };\n}\n\nDEBUG && (MOUNT_CLASS_TO.getStreamCached = getStreamCached);\n","import {appSettings} from '@stores/appSettings';\n\n// `deviceId` mirrors getAudioConstraints — when the user has picked a camera\n// in the Speakers-and-Camera settings tab, propagate it here so\n// `getUserMedia({video})` picks up the chosen device. Falls back to OS default.\n//\n// Uses `ideal` instead of `min` for resolution/framerate. Strict `min`\n// constraints turn into a hard OverconstrainedError when paired with a\n// `deviceId: {exact: ...}` lookup because the browser can't fall back to a\n// different camera; observed locally with FaceTime HD whose framerate steps\n// don't include the requested 24–30 window. With `ideal` the browser picks\n// the closest mode the chosen device actually supports.\nexport default function getVideoConstraints(deviceId?: string): MediaTrackConstraints {\n  const constraints: MediaTrackConstraints = {\n    width: {ideal: 1280, max: 1920},\n    height: {ideal: 720, max: 1080},\n    frameRate: {ideal: 30, max: 30}\n  };\n\n  const id = deviceId ?? appSettings.callDevices?.cameraId;\n  if(id) {\n    constraints.deviceId = {exact: id};\n  }\n\n  return constraints;\n}\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nexport default class StringFromLineBuilder {\n  private lines: string[];\n  private newLine: string[];\n\n  constructor(private joiner = '\\r\\n') {\n    this.lines = [];\n    this.newLine = [];\n  }\n\n  public add(...strs: string[]) {\n    this.lines.push(...strs);\n    return this;\n  }\n\n  public push(word: string) {\n    this.newLine.push(word);\n    return this;\n  }\n\n  public addJoined(separator = '') {\n    this.add(this.newLine.join(separator));\n    this.newLine = [];\n    return this;\n  }\n\n  public join() {\n    return this.lines.join(this.joiner);\n  }\n\n  public finalize() {\n    return this.join() + this.joiner;\n  }\n}\n","export default function splitStringByLimitWithRest(str: string, separator: string, limit: number) {\n  const splitted = str.split(separator);\n  const out: string[] = [];\n\n  while(limit > 0 && splitted.length) {\n    out.push(splitted.shift());\n    --limit;\n  }\n\n  if(splitted.length) {\n    out.push(splitted.join(separator));\n  }\n\n  return out;\n}\n","import splitStringByLimitWithRest from '@helpers/string/splitStringByLimitWithRest';\n\nexport default class SDPAttributeInner {\n  #key: string;\n  #lines: Array<string>;\n  #prefix: string;\n  #nestedMap: Map<string, SDPAttributeInner>;\n  #missed: boolean;\n  #keys: Array<string>;\n\n  constructor(key: SDPAttributeInner['key'], lines: SDPAttributeInner['lines'], prefix: string = ':', missed = false) {\n    this.#key = key;\n    this.#lines = lines;\n    this.#prefix = prefix;\n    this.#missed = missed;\n    this.#nestedMap = missed ? new Map() : null;\n    this.#keys = missed ? [] : null;\n  }\n\n  public get lines() {\n    return this.#lines;\n  }\n\n  public get value() {\n    return this.#missed || !this.lines.length ? null : this.lines[0];\n  }\n\n  public get exists() {\n    return !this.#missed;\n  }\n\n  public get key() {\n    return this.#key;\n  }\n\n  public get keys() {\n    SDPAttributeInner.fill(this);\n    return this.#keys;\n  }\n\n  public forEach(callback: Parameters<Map<string, SDPAttributeInner>['forEach']>[0]) {\n    SDPAttributeInner.fill(this);\n    this.#nestedMap.forEach(callback);\n  }\n\n  public get(key: string) {\n    SDPAttributeInner.fill(this);\n    return this.#nestedMap.get(key) || new SDPAttributeInner(key, [], ':', true);\n  }\n\n  private static fill(attribute: SDPAttributeInner) {\n    if(attribute.#nestedMap !== null) {\n      return;\n    }\n\n    const map: Map<string, Array<string>> = new Map();\n    attribute.lines.forEach((str) => {\n      const [key, rest] = splitStringByLimitWithRest(str, attribute.#prefix, 1);\n      const values = map.get(key) || [];\n      map.set(key, [...values, rest || '']);\n    });\n\n    const nestedMap = attribute.#nestedMap = SDPAttributeInner.makeAttributes(map);\n    attribute.#keys = Array.from(nestedMap.keys());\n  }\n\n  private static makeAttributes(innerParts: Map<string, Array<string>>) {\n    const out: Map<string, SDPAttributeInner> = new Map();\n\n    innerParts.forEach((lines, key) => {\n      out.set(key, new SDPAttributeInner(key, lines));\n    });\n\n    return out;\n  }\n}\n","import SDPAttributeInner from '@lib/calls/sdp/attributeInner';\nimport SDPLine from '@lib/calls/sdp/line';\n\nexport default class SDPAttributes {\n  #lines: SDPLine[];\n  #attributes: Map<string, SDPAttributeInner>;\n\n  constructor(lines: SDPLine[]) {\n    this.#lines = lines;\n    this.#attributes = new Map();\n    SDPAttributes.fillAttributes(this);\n  }\n\n  public get(key: string) {\n    return this.#attributes.get(key) || new SDPAttributeInner(key, [], ' ', true);\n  }\n\n  private static fillAttributes(attributes: SDPAttributes) {\n    const attributesMap: Map<string, Array<string>> = new Map();\n    attributes.#lines.forEach((line) => {\n      if(line.key === 'a') {\n        const {key, value} = line.parsed;\n\n        let linesArray = attributesMap.get(key);\n        if(!linesArray) {\n          linesArray = [];\n          attributesMap.set(key, linesArray);\n        }\n\n        linesArray.push(value || '');\n      }\n    });\n\n    attributesMap.forEach((linesArray, key) => {\n      attributes.#attributes.set(key, new SDPAttributeInner(key, linesArray, ' ', false));\n    });\n  }\n}\n","import SDPMediaSection from '@lib/calls/sdp/mediaSection';\nimport SDPSessionSection from '@lib/calls/sdp/sessionSection';\n\nexport type AttributeKey = 'group' | 'rtcp' | 'ice-ufrag' |\n  'ice-pwd' | 'ice-options' | 'fingerprint' | 'setup' |\n  'mid' | 'extmap' | 'sendonly' | 'msid' | 'rtcp-mux' |\n  'rtpmap' | 'rtcp-fb' | 'fmtp' | 'ssrc' | 'ssrc-group' |\n  'extmap-allow-mixed' | 'msid-semantic';\n\nexport type AttributeMap = {[k in AttributeKey]?: boolean};\n\nexport default class SDP {\n  #session: SDPSessionSection;\n  #media: SDPMediaSection[];\n\n  constructor(session: SDP['session'], mediaSections: SDP['media']) {\n    this.#session = session;\n    this.#media = mediaSections;\n  }\n\n  public get session() {\n    return this.#session;\n  }\n\n  public get media() {\n    return this.#media;\n  }\n\n  public get bundle() {\n    const bundleLine = this.session.lines.find((line) => line.parsed?.key === 'group');\n    return bundleLine.value.split(' ').slice(1);\n  }\n\n  toString() {\n    return this.session.lines\n    .concat(...this.media.map((section) => section.lines))\n    .map((line) => line.toString()).join('\\r\\n') + '\\r\\n';\n  }\n\n  /* get buggedMedia() {\n    const bundle = this.bundle;\n    type A = {\n      mid: SDPMediaSection['mid'],\n      mediaType: SDPMediaSection['mediaType'],\n      direction: SDPMediaSection['direction']\n    };\n    const out: A[] = [];\n    for(let i = 0, length = this.media.length; i < length; ++i) {\n      const section = this.media[i];\n      const mid = section.mid;\n      if(!bundle.includes(mid)) {\n        out.push(section);\n      }\n    }\n\n    return out;\n  } */\n\n  /* get mediaTypes() {\n    return this.media.map((section) => {\n      return {mid: section.oa.get('mid').oa, type: section.mediaType, direction: section.direction};\n    });\n  } */\n}\n","export default class UniqueNumberGenerator {\n  #set: Set<number>;\n  #min: number;\n  #max: number;\n\n  constructor(min: number, max: number) {\n    this.#set = new Set();\n    this.#min = min;\n    this.#max = max;\n  }\n\n  public generate() {\n    const min = this.#min;\n    const max = this.#max;\n    const set = this.#set;\n\n    const maxTries = max - min + 1;\n    let value = Math.floor(min + maxTries * Math.random()), _try = 0;\n    while(set.has(value)) {\n      if(value < max) {\n        ++value;\n      } else {\n        value = min;\n      }\n\n      if(++_try >= maxTries) {\n        return null;\n      }\n    }\n\n    set.add(value);\n    return value;\n  }\n\n  public add(value: number) {\n    this.#set.add(value);\n  }\n}\n","import {AttributeKey} from '.';\n\nexport default class SDPAttributeSplitted {\n  #key: AttributeKey;\n  #value: string;\n\n  // key = 'ssrc-group', value = 'SIM 1 2 3'\n  constructor(key: AttributeKey, value: string) {\n    this.#key = key;\n    this.#value = value;\n  }\n\n  public get key() {\n    return this.#key;\n  }\n\n  public get value() {\n    return this.#value;\n  }\n}\n","export default class SDPMediaLineParts {\n  #type: 'audio' | 'video' | 'application';\n  #port: string;\n  #protocol: string;\n  #ids: string[];\n\n  constructor(\n    type: SDPMediaLineParts['type'],\n    port: SDPMediaLineParts['port'],\n    protocol: SDPMediaLineParts['protocol'],\n    ids: SDPMediaLineParts['ids']\n  ) {\n    this.#type = type;\n    this.#port = port;\n    this.#protocol = protocol;\n    this.#ids = ids;\n  }\n\n  public get type() {\n    return this.#type;\n  }\n\n  public get port() {\n    return this.#port;\n  }\n\n  public get protocol() {\n    return this.#protocol;\n  }\n\n  public get ids() {\n    return this.#ids;\n  }\n\n  toString() {\n    return this.type + ' ' + this.port + ' ' + this.protocol + ' ' + this.ids.join(' ');\n  }\n}\n","import splitStringByLimitWithRest from '@helpers/string/splitStringByLimitWithRest';\nimport SDPAttributeSplitted from '@lib/calls/sdp/attributeSplitted';\nimport SDPMediaLineParts from '@lib/calls/sdp/mediaLineParts';\n\nexport default class SDPLine {\n  #key: 'm' | 'a' | 'o' | 'v' | 's' | 't' | 'c';\n  #value: string;\n  #mediaLineParts: SDPMediaLineParts;\n  #parsed?: SDPAttributeSplitted;\n\n  // key = 'a', value = 'ssrc-group:SIM 1 2 3'\n  constructor(key: SDPLine['key'], value: string | SDPMediaLineParts | SDPAttributeSplitted) {\n    this.#key = key;\n\n    if(typeof(value) === 'string') {\n      this.#value = value;\n\n      if(key === 'm') {\n        const splitted = value.split(' ');\n        this.#mediaLineParts = new SDPMediaLineParts(splitted[0] as any, splitted[1], splitted[2], splitted.slice(3));\n      } else {\n        if(key === 'a') {\n          const result = splitStringByLimitWithRest(value, ':', 1);\n          value = result[0];\n          this.#parsed = result.length === 1 ? new SDPAttributeSplitted(value as any, null) : new SDPAttributeSplitted(value as any, result[1]);\n        }\n      }\n    } else {\n      if(value instanceof SDPMediaLineParts) {\n        this.#mediaLineParts = value;\n        this.#value = value.toString();\n      } else if(value instanceof SDPAttributeSplitted) {\n        this.#parsed = value;\n        this.#value = value.value ? `${value.key}:${value.value}` : value.key;\n      }\n    }\n  }\n\n  public get key() {\n    return this.#key;\n  }\n\n  public get value() {\n    return this.#value;\n  }\n\n  public get parsed() {\n    return this.#parsed;\n  }\n\n  public get mediaLineParts() {\n    return this.#mediaLineParts;\n  }\n\n  toString() {\n    return `${this.key}=${this.value}`;\n  }\n}\n","import {AttributeMap} from '.';\nimport {NoExtraProperties} from '@types';\nimport SDPAttributes from '@lib/calls/sdp/attributes';\nimport SDPLine from '@lib/calls/sdp/line';\n\nexport type SDPMediaDirection = 'sendonly' | 'recvonly' | 'inactive' | 'sendrecv';\nexport default class SDPMediaSection {\n  #lines: Array<SDPLine>;\n  #mediaLine: SDPLine;\n  #attributes: SDPAttributes;\n  #direction: SDPMediaDirection;\n\n  constructor(lines: Array<SDPLine>) {\n    this.#lines = lines;\n    this.#mediaLine = lines[0];\n    this.#attributes = this.#direction = null;\n  }\n\n  public get lines() {\n    return this.#lines;\n  }\n\n  public get mediaLine() {\n    return this.#mediaLine;\n  }\n\n  public get mediaLineParts() {\n    return this.#mediaLine.mediaLineParts;\n  }\n\n  public get mediaType() {\n    return this.mediaLineParts.type;\n  }\n\n  public get direction() {\n    if(!this.#direction) {\n      const attributes = this.attributes;\n\n      let direction: SDPMediaDirection;\n      if(attributes.get('sendonly').exists) direction = 'sendonly';\n      else if(attributes.get('recvonly').exists) direction = 'recvonly';\n      else if(attributes.get('inactive').exists) direction = 'inactive';\n      else direction = 'sendrecv';\n\n      this.#direction = direction;\n    }\n\n    return this.#direction;\n  }\n\n  public get isSending() {\n    return this.direction === 'sendrecv' || this.direction === 'sendonly';\n  }\n\n  public get isReceiving() {\n    return this.direction === 'sendrecv' || this.direction === 'recvonly';\n  }\n\n  public get attributes() {\n    this.#attributes || (this.#attributes = new SDPAttributes(this.lines));\n    return this.#attributes;\n  }\n\n  public get mid() {\n    return this.attributes.get('mid').value;\n  }\n\n  public lookupAttributeKeys<T extends AttributeMap>(keys: NoExtraProperties<AttributeMap, T>): {[k in keyof T]: T[k] extends true ? string : string[]} {\n    const out: any = {};\n\n    for(const key in keys) {\n      const result = this.attributes.get(key);\n      // @ts-ignore\n      const resultShouldBeArray = !keys[key];\n      if(!result) {\n        out[key] = resultShouldBeArray ? [] : undefined;\n      } else {\n        out[key] = resultShouldBeArray ? result.lines : result.value;\n      }\n    }\n\n    return out;\n  }\n}\n","import SDPLine from '@lib/calls/sdp/line';\n\nexport default class SDPSessionSection {\n  #lines: SDPLine[];\n  #sessionId: string;\n\n  constructor(lines: SDPLine[]) {\n    this.#lines = lines;\n    this.#sessionId = lines.filter((line) => line.key === 'o').map((line) => line.value.split(' ')[1])[0];\n  }\n\n  public get lines() {\n    return this.#lines;\n  }\n\n  public get sessionId() {\n    return this.#sessionId;\n  }\n}\n","import SDP from '.';\nimport splitStringByLimitWithRest from '@helpers/string/splitStringByLimitWithRest';\nimport UniqueNumberGenerator from '@helpers/uniqueNumberGenerator';\nimport SDPLine from '@lib/calls/sdp/line';\nimport SDPMediaSection from '@lib/calls/sdp/mediaSection';\nimport SDPSessionSection from '@lib/calls/sdp/sessionSection';\n\nexport function parseSdp(str: string) {\n  function createSection() {\n    if(sessionSection) {\n      mediaSections.push(new SDPMediaSection(lines));\n    } else {\n      sessionSection = new SDPSessionSection(lines);\n    }\n  }\n\n  let sessionSection: SDPSessionSection = null, lines: SDPLine[] = [];\n  const mediaSections: SDPMediaSection[] = [];\n  str.split(/\\r?\\n/).forEach((lineStr) => {\n    if(!isIncorrectSdpLine(lineStr)) {\n      const line = parseSdpLine(lineStr);\n      if(line.key === 'm') {\n        createSection();\n        lines = [];\n      }\n\n      lines.push(line);\n    }\n  });\n\n  createSection();\n  return new SDP(sessionSection, mediaSections);\n}\n\nexport function isIncorrectSdpLine(str: string) {\n  return /^[\\s\\xa0]*$/.test(str);\n}\n\nexport function parseSdpLine(str: string) {\n  const splitted = splitStringByLimitWithRest(str, '=', 1);\n  return new SDPLine(splitted[0] as any, splitted[1]);\n}\n\nexport function addSimulcast(sdp: SDP) {\n  let generator: UniqueNumberGenerator;\n  sdp.media.forEach((section, idx) => {\n    if(section.mediaType === 'video' && section.isSending && !section.attributes.get('ssrc-group').get('SIM').exists) {\n      if(!generator) {\n        generator = new UniqueNumberGenerator(2, 4294967295);\n      }\n\n      const originalSsrcs = section.attributes.get('ssrc-group').get('FID').value.split(' ');\n      const lines = section.lines;\n      originalSsrcs.forEach((ssrc) => generator.add(+ssrc)); // fix possible duplicates\n      const ssrcs = [originalSsrcs[0], generator.generate(), generator.generate()];\n      const ssrcs2 = [originalSsrcs[1], generator.generate(), generator.generate()];\n\n      lines.push(parseSdpLine('a=ssrc-group:SIM ' + ssrcs.join(' ')));\n\n      const ssrcsStrLines = section.attributes.get('ssrc').get(originalSsrcs[0]).lines;\n\n      ssrcs.forEach((ssrc, idx) => {\n        const ssrc2 = ssrcs2[idx];\n        if(idx > 0) {\n          lines.push(parseSdpLine('a=ssrc-group:FID ' + ssrc + ' ' + ssrc2));\n\n          ssrcsStrLines.forEach((v) => {\n            lines.push(parseSdpLine('a=ssrc:' + ssrc + ' ' + v));\n          });\n\n          ssrcsStrLines.forEach((v) => {\n            lines.push(parseSdpLine('a=ssrc:' + ssrc2 + ' ' + v));\n          });\n        }\n      });\n\n      sdp.media[idx] = new SDPMediaSection(lines);\n    }\n  });\n\n  return !!generator;\n}\n","/*\n * SDP helpers for the tgcalls v2 P2P signaling protocol.\n *\n * The tgcalls-v2 engine (p2pCall.ts) was ported from telegram-tt, which works\n * with flat helper functions. This module keeps that function API but is built\n * entirely on tweb's own SDP parser (@lib/calls/sdp) — section splitting and\n * `a=` attribute grouping are tweb's `parseSdp` / `SDPAttributes`; only the\n * protocol-specific shaping (payload types, fingerprints, ssrc groups) lives here.\n */\n\nimport {P2PFingerprint, P2PPayloadType, RtpHdrexts} from '@lib/calls/types';\nimport SDPAttributes from '@lib/calls/sdp/attributes';\nimport {parseSdp} from '@lib/calls/sdp/utils';\n\n// A media (or session) section, in the flat shape the ported engine consumes,\n// backed by tweb's SDPAttributes for any attribute lookup.\nexport type SdpSection = {\n  kind: string,\n  mid?: string,\n  lines: string[],\n  direction?: string,\n  port: number,\n  attributes: SDPAttributes\n};\n\nexport type SdpSsrcGroup = {\n  semantics: string,\n  ssrcs: number[]\n};\n\nexport type SdpSummarySection = {\n  kind: string,\n  mid?: string,\n  port: number,\n  direction?: string,\n  payloads: string[],\n  ssrcs: number[]\n};\n\nconst SDP_DIRECTIONS = ['sendrecv', 'sendonly', 'recvonly', 'inactive'] as const;\n\n// Split a raw SDP string into its session section + one section per `m=` line,\n// using tweb's SDP parser.\nexport function parseSdpSections(sdp: string): SdpSection[] {\n  const parsed = parseSdp(sdp);\n  const sections: SdpSection[] = [{\n    kind: 'session',\n    mid: undefined,\n    lines: parsed.session.lines.map((line) => line.toString()),\n    direction: undefined,\n    port: 0,\n    attributes: new SDPAttributes(parsed.session.lines)\n  }];\n\n  parsed.media.forEach((section) => {\n    const {attributes} = section;\n    sections.push({\n      kind: section.mediaType,\n      mid: section.mid || undefined,\n      lines: section.lines.map((line) => line.toString()),\n      direction: SDP_DIRECTIONS.find((direction) => attributes.get(direction).exists),\n      port: Number(section.mediaLineParts?.port || 0),\n      attributes\n    });\n  });\n\n  return sections;\n}\n\nexport function parseBundleMids(sdp: string) {\n  const sessionAttributes = new SDPAttributes(parseSdp(sdp).session.lines);\n  const bundle = sessionAttributes.get('group').lines.find((line) => line.startsWith('BUNDLE '));\n  return bundle?.slice('BUNDLE '.length).split(' ').filter(Boolean);\n}\n\nfunction readAttributeValue(section: SdpSection, key: string) {\n  const attribute = section.attributes.get(key);\n  return attribute.exists && attribute.value ? attribute.value : undefined;\n}\n\n// Find an `a=<key>:<value>` value, preferring the given section, falling back to\n// the session. `prefix` is the legacy `a=<key>:` form the engine passes.\nexport function findSdpLineValue(sections: SdpSection[], prefix: string, section?: SdpSection) {\n  const key = prefix.replace(/^a=/, '').replace(/:$/, '');\n\n  if(section) {\n    const value = readAttributeValue(section, key);\n    if(value !== undefined) {\n      return value;\n    }\n\n    const sessionSection = sections.find((item) => item.kind === 'session');\n    return sessionSection && sessionSection !== section ? readAttributeValue(sessionSection, key) : undefined;\n  }\n\n  for(const item of sections) {\n    const value = readAttributeValue(item, key);\n    if(value !== undefined) {\n      return value;\n    }\n  }\n\n  return undefined;\n}\n\nexport function getSdpDirection(section: SdpSection) {\n  return section.direction;\n}\n\nexport function getSdpPort(section: SdpSection) {\n  return section.port;\n}\n\nexport function parseFingerprints(sections: SdpSection[]): P2PFingerprint[] {\n  const values = new Map<string, P2PFingerprint>();\n\n  sections.forEach((section) => {\n    const fingerprint = findSdpLineValue(sections, 'a=fingerprint:', section);\n    if(!fingerprint) {\n      return;\n    }\n\n    const [hash, value] = fingerprint.split(' ');\n    const setup = findSdpLineValue(sections, 'a=setup:', section) || 'actpass';\n    if(!hash || !value) {\n      return;\n    }\n\n    values.set(`${hash}:${value}:${setup}`, {\n      hash,\n      setup,\n      fingerprint: value\n    });\n  });\n\n  return Array.from(values.values());\n}\n\nexport function parseSsrcGroups(section: SdpSection): SdpSsrcGroup[] {\n  return section.attributes.get('ssrc-group').lines.map((line) => {\n    const [semantics, ...ssrcs] = line.split(' ');\n    return {\n      semantics,\n      ssrcs: ssrcs.map(Number)\n    };\n  });\n}\n\nexport function parseSsrcs(section: SdpSection, shouldIncludeGroups = false) {\n  const values = new Set<number>();\n\n  section.attributes.get('ssrc').lines.forEach((line) => {\n    const match = line.match(/^\\d+/);\n    if(match) {\n      values.add(Number(match[0]));\n    }\n  });\n\n  if(shouldIncludeGroups) {\n    section.attributes.get('ssrc-group').lines.forEach((line) => {\n      line.match(/\\d+/g)?.forEach((value) => {\n        values.add(Number(value));\n      });\n    });\n  }\n\n  return Array.from(values);\n}\n\nexport function parseExtmaps(section: SdpSection): RtpHdrexts[] {\n  return section.attributes.get('extmap').lines.map((line) => {\n    const [, rawId, uri] = line.match(/^(\\d+)(?:\\/[^\\s]+)?\\s(.+)$/) || [];\n    if(!rawId || !uri) {\n      throw new Error('Failed parsing SDP RTP extension');\n    }\n\n    return {\n      id: Number(rawId),\n      uri\n    };\n  });\n}\n\nexport function parsePayloadTypes(section: SdpSection): P2PPayloadType[] {\n  const payloadTypes: P2PPayloadType[] = section.attributes.get('rtpmap').lines.map((line) => {\n    const [, rawId, name, rawClockrate, rawChannels] = line.match(/^(\\d+)\\s([^/]+)\\/(\\d+)(?:\\/(\\d+))?/) || [];\n    if(!rawId || !name || !rawClockrate) {\n      throw new Error('Failed parsing SDP payload type');\n    }\n\n    return {\n      id: Number(rawId),\n      name,\n      clockrate: Number(rawClockrate),\n      channels: rawChannels ? Number(rawChannels) : 0\n    };\n  });\n\n  payloadTypes.forEach((payloadType) => {\n    const parameters = parsePayloadParameters(section, payloadType.id);\n    const feedbackTypes = parseFeedbackTypes(section, payloadType.id);\n\n    if(Object.keys(parameters).length) {\n      payloadType.parameters = parameters;\n    }\n    if(feedbackTypes.length) {\n      payloadType.feedbackTypes = feedbackTypes;\n    }\n  });\n\n  return payloadTypes;\n}\n\n// Compact SDP description for debug logging.\nexport function summarizeSdp(sdp: string, shouldIncludeSsrcGroups = false): SdpSummarySection[] {\n  return parseSdpSections(sdp).filter((section) => section.kind !== 'session').map((section): SdpSummarySection => {\n    return {\n      kind: section.kind,\n      mid: section.mid,\n      port: section.port,\n      direction: section.direction,\n      payloads: (section.lines[0] || '').split(' ').slice(3),\n      ssrcs: parseSsrcs(section, shouldIncludeSsrcGroups)\n    };\n  });\n}\n\nfunction parsePayloadParameters(section: SdpSection, payloadId: number) {\n  const parameters: Record<string, string> = {};\n  const prefix = `${payloadId} `;\n  const rawParameters = section.attributes.get('fmtp').lines.find((line) => line.startsWith(prefix))?.slice(prefix.length);\n  if(!rawParameters) {\n    return parameters;\n  }\n\n  rawParameters.split(';').forEach((item) => {\n    const trimmed = item.trim();\n    const separatorIndex = trimmed.indexOf('=');\n    if(separatorIndex === -1) {\n      return;\n    }\n\n    const key = trimmed.slice(0, separatorIndex);\n    const value = trimmed.slice(separatorIndex + 1);\n    if(key && value) {\n      parameters[key] = value;\n    }\n  });\n\n  return parameters;\n}\n\nfunction parseFeedbackTypes(section: SdpSection, payloadId: number): NonNullable<P2PPayloadType['feedbackTypes']> {\n  const prefix = `${payloadId} `;\n  return section.attributes.get('rtcp-fb').lines.filter((line) => line.startsWith(prefix)).map((line) => {\n    const [type, subtype] = line.slice(prefix.length).split(' ');\n    return {\n      type,\n      subtype: subtype || ''\n    };\n  });\n}\n","/*\n * Guards for strings that get interpolated into an SDP we hand to the browser.\n *\n * SDP is line-oriented: a CR or LF inside an attribute value ends that line\n * early and everything after it is parsed as further SDP. On the P2P (1-on-1)\n * path the remote peer supplies ufrag / pwd / fingerprint directly, so without\n * this the peer writes our session description rather than just their half of\n * it (sdpBuilder addTransport interpolates all of them verbatim).\n *\n * These fields have no legitimate use for a line break, so a violation is a\n * signalling error to reject — not something to sanitise and carry on with.\n */\n\nimport type {GroupCallParticipantVideoSourceGroup} from '@layer';\nimport type {GroupCallConnectionTransport, P2PMediaContent, P2PMessage, UpdateGroupCallConnectionData} from '@lib/calls/types';\n\ntype InitialSetup = Extract<P2PMessage, {'@type': 'InitialSetup'}>;\n\nexport function isSdpSafeString(value: unknown): value is string {\n  return typeof value === 'string' && !/[\\r\\n\\0]/.test(value);\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\n\nfunction isNonEmptySdpString(value: unknown): value is string {\n  return isSdpSafeString(value) && value.length > 0;\n}\n\n/**\n * Runtime validation for the peer-controlled InitialSetup JSON.\n *\n * This deliberately validates types as well as line safety. Template-string\n * interpolation calls Array#toString/Object#toString, so merely checking CR/LF\n * when the value happens to be a string lets a JSON array smuggle a second SDP\n * line through (for example, `[\"x\\r\\na=candidate:evil\"]`).\n */\nexport function isSdpSafeSetup(setup: unknown): setup is InitialSetup {\n  if(!isRecord(setup) || setup['@type'] !== 'InitialSetup') {\n    return false;\n  }\n\n  if(!isNonEmptySdpString(setup.ufrag) || !isNonEmptySdpString(setup.pwd)) {\n    return false;\n  }\n  if(typeof setup.renomination !== 'boolean') {\n    return false;\n  }\n  if(!Array.isArray(setup.fingerprints) || !setup.fingerprints.length) {\n    return false;\n  }\n\n  return setup.fingerprints.every((fingerprint) => {\n    return isRecord(fingerprint) &&\n      isNonEmptySdpString(fingerprint.hash) &&\n      isNonEmptySdpString(fingerprint.fingerprint) &&\n      isNonEmptySdpString(fingerprint.setup);\n  });\n}\n\n// ---------------------------------------------------------------------------\n// Field-level guards for the other SDP sources.\n//\n// The InitialSetup check above covers the 1-on-1 transport. Everything else\n// the builders interpolate comes from JSON as well — the peer's\n// NegotiateChannels on the 1-on-1 path, the SFU's join answer and the\n// participants' source groups on the group path — and none of it has a\n// legitimate use for whitespace, let alone a line break. These validate the\n// shape the builders assume (an integer wherever `${n}` is emitted, a\n// printable token wherever a string is) and bound every array, so a value can\n// neither end a line early nor make the builder stringify an object.\n// ---------------------------------------------------------------------------\n\nconst SDP_TOKEN = /^[\\x21-\\x7e]{1,256}$/;\nconst SETUP_ROLES = new Set(['active', 'passive', 'actpass']);\nconst CANDIDATE_FIELDS = ['foundation', 'component', 'protocol', 'priority', 'ip', 'port', 'type', 'generation'] as const;\nconst CANDIDATE_OPTIONAL_FIELDS = ['id', 'network', 'rel-addr', 'rel-port'] as const;\nconst MAX_CONTENTS = 8;\nconst MAX_PAYLOAD_TYPES = 64;\nconst MAX_RTP_EXTENSIONS = 32;\nconst MAX_FEEDBACK_TYPES = 16;\nconst MAX_PARAMETERS = 32;\nconst MAX_SSRC_GROUPS = 8;\nconst MAX_SSRCS_PER_GROUP = 8;\nconst MAX_SERVER_SOURCES = 64;\nconst MAX_CANDIDATES = 64;\nconst MAX_FINGERPRINTS = 8;\n\nfunction isSdpToken(value: unknown): value is string {\n  return typeof value === 'string' && SDP_TOKEN.test(value);\n}\n\n// Optional string fields travel as '' when absent (tgcalls emits\n// `subtype: \"\"` on every feedback type, candidates carry empty rel-addr).\nfunction isOptionalSdpToken(value: unknown): boolean {\n  return value === undefined || value === '' || isSdpToken(value);\n}\n\nfunction isSdpInteger(value: unknown, max = Number.MAX_SAFE_INTEGER): value is number {\n  return Number.isInteger(value) && (value as number) >= 0 && (value as number) <= max;\n}\n\n// An SSRC: a 32-bit integer, as a number or (tgcalls) a decimal string. The\n// server sends its sources as SIGNED int32 (fromTelegramSource turns them back\n// into the unsigned value the SDP carries), so negatives are ordinary here.\nfunction isSdpSsrc(value: unknown): boolean {\n  const n = typeof value === 'string' && /^-?\\d{1,10}$/.test(value) ? Number(value) : value;\n  return Number.isInteger(n) && (n as number) >= -0x80000000 && (n as number) <= 0xffffffff;\n}\n\nfunction isBoundedArray(value: unknown, max: number): value is unknown[] {\n  return Array.isArray(value) && value.length <= max;\n}\n\nfunction isSdpSafeFeedbackTypes(value: unknown): boolean {\n  if(value === undefined) return true;\n  return isBoundedArray(value, MAX_FEEDBACK_TYPES) && value.every((fb) => {\n    return isRecord(fb) && isSdpToken(fb.type) && isOptionalSdpToken(fb.subtype);\n  });\n}\n\nfunction isSdpSafeParameters(value: unknown): boolean {\n  if(value === undefined) return true;\n  if(Array.isArray(value)) return !value.length; // the SFU sends [] for \"none\"\n  if(!isRecord(value)) return false;\n  const keys = Object.keys(value);\n  return keys.length <= MAX_PARAMETERS && keys.every((key) => {\n    const parameter = value[key];\n    return isSdpToken(key) && (isOptionalSdpToken(parameter) || isSdpInteger(parameter));\n  });\n}\n\nfunction isSdpSafePayloadType(value: unknown): boolean {\n  return isRecord(value) &&\n    isSdpInteger(value.id, 127) &&\n    isSdpToken(value.name) &&\n    isSdpInteger(value.clockrate) &&\n    (value.channels === undefined || isSdpInteger(value.channels)) &&\n    isSdpSafeFeedbackTypes(value.feedbackTypes) &&\n    isSdpSafeFeedbackTypes(value['rtcp-fbs']) &&\n    isSdpSafeParameters(value.parameters);\n}\n\nfunction isSdpSafePayloadTypes(value: unknown): boolean {\n  return isBoundedArray(value, MAX_PAYLOAD_TYPES) && value.every(isSdpSafePayloadType);\n}\n\nfunction isSdpSafeRtpExtensions(value: unknown): boolean {\n  return isBoundedArray(value, MAX_RTP_EXTENSIONS) && value.every((extension) => {\n    return isRecord(extension) && isSdpInteger(extension.id) && isSdpToken(extension.uri);\n  });\n}\n\nfunction isSdpSafeSsrcGroups(value: unknown, key: 'ssrcs' | 'sources'): boolean {\n  return isBoundedArray(value, MAX_SSRC_GROUPS) && value.every((group) => {\n    if(!isRecord(group) || !isSdpToken(group.semantics)) return false;\n    const sources = group[key];\n    return isBoundedArray(sources, MAX_SSRCS_PER_GROUP) && sources.every(isSdpSsrc);\n  });\n}\n\n// The group-call validators name the offending field instead of answering\n// false: the SFU's answer is opaque server data, and a rejected join has to say\n// which field it rejected before anyone can tell a hostile relay from an\n// honest one the validator did not anticipate. `undefined` means safe.\nfunction unsafePayloadTypes(value: unknown, path: string): string | undefined {\n  if(!isBoundedArray(value, MAX_PAYLOAD_TYPES)) return path;\n  for(let i = 0; i < value.length; ++i) {\n    const payloadType = value[i];\n    if(!isRecord(payloadType)) return `${path}[${i}]`;\n    if(!isSdpInteger(payloadType.id, 127)) return `${path}[${i}].id`;\n    if(!isSdpToken(payloadType.name)) return `${path}[${i}].name`;\n    if(!isSdpInteger(payloadType.clockrate)) return `${path}[${i}].clockrate`;\n    if(payloadType.channels !== undefined && !isSdpInteger(payloadType.channels)) return `${path}[${i}].channels`;\n    if(!isSdpSafeFeedbackTypes(payloadType['rtcp-fbs'])) return `${path}[${i}].rtcp-fbs`;\n    if(!isSdpSafeParameters(payloadType.parameters)) return `${path}[${i}].parameters`;\n  }\n}\n\nfunction unsafeCodec(value: unknown, path: string): string | undefined {\n  if(!isRecord(value)) return path;\n  const payloadTypes = unsafePayloadTypes(value['payload-types'], `${path}.payload-types`);\n  if(payloadTypes) return payloadTypes;\n  if(!isSdpSafeRtpExtensions(value['rtp-hdrexts'])) return `${path}.rtp-hdrexts`;\n  if(!isOptionalSdpToken(value.endpoint)) return `${path}.endpoint`;\n  if(value.server_sources !== undefined &&\n    !(isBoundedArray(value.server_sources, MAX_SERVER_SOURCES) && value.server_sources.every(isSdpSsrc))) {\n    return `${path}.server_sources`;\n  }\n}\n\nfunction unsafeTransport(value: unknown): string | undefined {\n  if(!isRecord(value)) return 'transport';\n  if(!isSdpToken(value.ufrag)) return 'transport.ufrag';\n  if(!isSdpToken(value.pwd)) return 'transport.pwd';\n  if(!isOptionalSdpToken(value.xmlns)) return 'transport.xmlns';\n  if(value['rtcp-mux'] !== undefined && typeof value['rtcp-mux'] !== 'boolean') return 'transport.rtcp-mux';\n  const fingerprints = value.fingerprints;\n  if(!isBoundedArray(fingerprints, MAX_FINGERPRINTS) || !fingerprints.length) return 'transport.fingerprints';\n  for(let i = 0; i < fingerprints.length; ++i) {\n    const fingerprint = fingerprints[i];\n    if(!isRecord(fingerprint)) return `transport.fingerprints[${i}]`;\n    if(!isSdpToken(fingerprint.hash)) return `transport.fingerprints[${i}].hash`;\n    if(!isSdpToken(fingerprint.fingerprint)) return `transport.fingerprints[${i}].fingerprint`;\n    if(!SETUP_ROLES.has(fingerprint.setup as string)) return `transport.fingerprints[${i}].setup`;\n  }\n  const candidates = value.candidates;\n  if(candidates === undefined) return;\n  if(!isBoundedArray(candidates, MAX_CANDIDATES)) return 'transport.candidates';\n  for(let i = 0; i < candidates.length; ++i) {\n    const candidate = candidates[i];\n    if(!isRecord(candidate)) return `transport.candidates[${i}]`;\n    for(const field of CANDIDATE_FIELDS) {\n      if(!isSdpToken(candidate[field])) return `transport.candidates[${i}].${field}`;\n    }\n    for(const field of CANDIDATE_OPTIONAL_FIELDS) {\n      if(!isOptionalSdpToken(candidate[field])) return `transport.candidates[${i}].${field}`;\n    }\n  }\n}\n\n/**\n * The peer's NegotiateChannels contents (1-on-1): every field SDPBuilder.addP2p\n * emits — rtpmap, fmtp, rtcp-fb, extmap, ssrc-group and the content's ssrc,\n * which doubles as its mid.\n */\nexport function isSdpSafeContents(contents: unknown): contents is P2PMediaContent[] {\n  return isBoundedArray(contents, MAX_CONTENTS) && contents.every((content) => {\n    return isRecord(content) &&\n      (content.type === 'audio' || content.type === 'video') &&\n      isSdpSsrc(content.ssrc) &&\n      (content.ssrcGroups === undefined || isSdpSafeSsrcGroups(content.ssrcGroups, 'ssrcs')) &&\n      (content.payloadTypes === undefined || isSdpSafePayloadTypes(content.payloadTypes)) &&\n      (content.rtpExtensions === undefined || isSdpSafeRtpExtensions(content.rtpExtensions));\n  });\n}\n\n/** A participant's `video` / `presentation` source groups (group calls). */\nexport function isSdpSafeSourceGroups(groups: unknown): groups is GroupCallParticipantVideoSourceGroup[] {\n  return isSdpSafeSsrcGroups(groups, 'sources');\n}\n\n/**\n * The SFU's join answer / updateGroupCallConnection params (group calls): the\n * transport and codec tables SDPBuilder.addConference and fixLocalOffer emit.\n * Also covers the presentation upgrade answer (the same shape minus audio).\n * Returns the path of the first field that cannot be interpolated, or\n * undefined when the whole answer is safe.\n */\nexport function getUnsafeConnectionDataReason(data: unknown): string | undefined {\n  if(!isRecord(data)) return 'data';\n  const transport = unsafeTransport(data.transport);\n  if(transport) return transport;\n  for(const codec of ['audio', 'video', 'screencast'] as const) {\n    if(data[codec] === undefined) continue;\n    const reason = unsafeCodec(data[codec], codec);\n    if(reason) return reason;\n  }\n}\n\nexport function isSdpSafeConnectionData(data: unknown): data is UpdateGroupCallConnectionData {\n  return getUnsafeConnectionDataReason(data) === undefined;\n}\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nimport {IS_FIREFOX} from '@environment/userAgent';\nimport LocalConferenceDescription, {ConferenceEntry} from '@lib/calls/localConferenceDescription';\nimport StringFromLineBuilder from '@lib/calls/stringFromLineBuilder';\nimport {CallSignalingData, GroupCallConnectionTransport, PayloadType, RtpHdrexts, UpdateGroupCallConnectionData} from '@lib/calls/types';\nimport {fromTelegramSource} from '@lib/calls/utils';\nimport {getSdpDirection, getSdpPort, SdpSection} from '@lib/calls/p2P/sdpCommon';\nimport {isSdpSafeSetup} from '@lib/calls/helpers/sdpSafety';\nimport {logger} from '@lib/logger';\n\n// screencast is for Peer-to-Peer only\nexport type WebRTCLineTypeTrue = 'video' | 'audio' | 'application';\nexport type WebRTCLineType = WebRTCLineTypeTrue | 'screencast';\n\nexport const WEBRTC_MEDIA_PORT = '9';\n\nconst log = logger('SDP-BUILDER');\n\nexport function fixMediaLineType(mediaType: WebRTCLineType) {\n  return mediaType === 'screencast' ? 'video' : mediaType;\n}\n\nexport function performCandidate(c: GroupCallConnectionTransport['candidates'][0]) {\n  const arr: string[] = [];\n  arr.push('a=candidate:');\n  arr.push(`${c.foundation} ${c.component} ${c.protocol.toUpperCase()} ${c.priority} ${c.ip} ${c.port} typ ${c.type}`);\n  if(c['rel-addr'] !== undefined) {\n    arr.push(` raddr ${c['rel-addr']} rport ${c['rel-port']}`);\n  }\n  arr.push(` generation ${c.generation}`);\n  return arr.join('');\n}\n\nexport function getConnectionTypeForMediaType(mediaType: WebRTCLineType) {\n  // return mediaType === 'application' ? 'DTLS/SCTP' : 'RTP/SAVPF';\n  return mediaType === 'application' ? 'DTLS/SCTP' : 'UDP/TLS/RTP/SAVPF';\n}\n\nexport function generateMediaFirstLine(mediaType: WebRTCLineType, port = WEBRTC_MEDIA_PORT, payloadIds: (string | number)[]) {\n  const connectionType = getConnectionTypeForMediaType(mediaType);\n  return `m=${fixMediaLineType(mediaType)} ${port} ${connectionType} ${payloadIds.join(' ')}`;\n}\n\ntype ConferenceData = UpdateGroupCallConnectionData | LocalConferenceDescription;\n\n// https://tools.ietf.org/id/draft-ietf-rtcweb-sdp-08.html\n// https://datatracker.ietf.org/doc/html/draft-roach-mmusic-unified-plan-00\nexport class SDPBuilder extends StringFromLineBuilder {\n  public addCandidate(c: GroupCallConnectionTransport['candidates'][0]) {\n    return this.add(performCandidate(c));\n  }\n\n  /* public addDataChannel(mid: string, transport: GroupCallConnectionTransport, isAnswer?: boolean) {\n    this.add(\n      'm=application 9 UDP/DTLS/SCTP webrtc-datachannel',\n      'c=IN IP4 0.0.0.0',\n      'a=ice-options:trickle',\n      `a=mid:${mid}`\n    );\n\n    // if(!isAnswer) {\n      this.add('a=sendrecv');\n    // }\n\n    this.addTransport(transport, isAnswer);\n\n    return this.add(\n      'a=sctp-port:5000',\n      'a=max-message-size:262144'\n    );\n  } */\n\n  public addHeader(sId: string, bundleMids: string[]) {\n    const bundle = bundleMids.join(' ');\n    return this.add(\n      'v=0',                          // version\n      `o=- ${sId} 2 IN IP4 0.0.0.0`,  // sessionId, 2=sessionVersion\n      's=-',                          // name of the session\n      't=0 0',                        // time when session is valid\n      'a=extmap-allow-mixed',\n      `a=group:BUNDLE ${bundle}`,\n      'a=ice-options:trickle',\n      // 'a=ice-lite',                   // ice-lite: is a minimal version of the ICE specification, intended for servers running on a public IP address.\n      'a=msid-semantic:WMS *'\n    );\n  }\n\n  public addTransport(transport: GroupCallConnectionTransport, skipCandidates?: boolean) {\n    this.add(\n      `a=ice-ufrag:${transport.ufrag}`,\n      `a=ice-pwd:${transport.pwd}`,\n      'a=ice-options:trickle'           // ! test\n    );\n\n    for(const fingerprint of transport.fingerprints) {\n      this.add(\n        `a=fingerprint:${fingerprint.hash} ${fingerprint.fingerprint}`,\n        `a=setup:${fingerprint.setup}`\n      );\n    }\n\n    if(!skipCandidates && transport.candidates) {\n      for(const candidate of transport.candidates) {\n        this.addCandidate(candidate);\n      }\n    }\n\n    return this;\n  }\n\n  public addSsrc(entry: ConferenceEntry) {\n    let streamName = 'stream';\n    let {type, sourceGroups} = entry;\n\n    // let source = ssrc.source ?? ssrc.sourceGroups[0].sources[0];\n    // source = fromTelegramSource(source);\n    const source = fromTelegramSource(entry.source);\n\n    streamName += source;\n    type += source as any;\n\n    // streamName += mid;\n    // type += mid as any;\n\n    // streamName = type = entry.transceiver.receiver.track.id as any;\n\n    const addMsid = () => {\n      this.add(`a=msid:${streamName} ${type}`);\n    };\n\n    const addSource = (ssrc: number) => {\n      this.add(\n        `a=ssrc:${ssrc} cname:${streamName}`,\n        `a=ssrc:${ssrc} msid:${streamName} ${type}`,\n        `a=ssrc:${ssrc} mslabel:${streamName}`,\n        `a=ssrc:${ssrc} label:${type}`\n      );\n    };\n\n    addMsid();\n    if(sourceGroups?.length) {\n      sourceGroups.forEach((ssrcGroup) => {\n        if(ssrcGroup.sources.length) {\n          const sources = ssrcGroup.sources.map(fromTelegramSource);\n          this.add(`a=ssrc-group:${ssrcGroup.semantics} ${sources.join(' ')}`);\n          sources.forEach(addSource);\n        }\n      });\n    } else {\n      addSource(source);\n    }\n\n    return this;\n  }\n\n  public addSsrcEntry(entry: ConferenceEntry, data: ConferenceData, isAnswer?: boolean) {\n    const add = (...x: string[]) => this.add(...x);\n\n    const {type, mid, direction, port} = entry;\n    const transport = data.transport;\n\n    /* if(type === 'application') {\n      return this.addDataChannel(mid, transport, isAnswer);\n    } */\n\n    const isApplication = type === 'application';\n    const codec = isApplication ? undefined : data[type];\n\n    const isInactive = direction === 'inactive';\n    if(entry.shouldBeSkipped(isAnswer)) {\n      return add(\n        `m=${fixMediaLineType(type)} 0 ${getConnectionTypeForMediaType(type)} 0`,\n        `c=IN IP4 0.0.0.0`,\n        `a=inactive`,\n        `a=mid:${mid}`\n      );\n    }\n\n    const payloadTypes = !isApplication ? codec['payload-types'] : [{id: 5000} as PayloadType];\n    const ids = payloadTypes.map((type) => type.id);\n    add(\n      generateMediaFirstLine(type, port, ids),\n      'c=IN IP4 0.0.0.0',\n      `a=rtcp:${port} IN IP4 0.0.0.0`\n    );\n\n    if(transport['rtcp-mux']) {\n      add('a=rtcp-mux');\n    }\n\n    add(`a=mid:${mid}`);\n    /* if(type === 'video') {\n      add('b=AS:2500');\n    } */\n\n    let setDirection = direction;\n    if(direction !== 'sendrecv' && isAnswer && !(isInactive || isApplication)) {\n      setDirection = direction === 'sendonly' ? 'recvonly' : 'sendonly';\n    }\n\n    // a=bundle-only\n    add(`a=${setDirection}`);\n\n    // this.addTransport(transport, isAnswer);\n    this.addTransport(transport);\n\n    if(!isApplication) {\n      const hdrexts = codec['rtp-hdrexts'];\n      if(hdrexts?.length) {\n        hdrexts.forEach((hdrext) => {\n          add(`a=extmap:${hdrext.id} ${hdrext.uri}`);\n        });\n      }\n\n      payloadTypes.forEach((type) => {\n        add(`a=rtpmap:${type.id} ${type.name}/${type.clockrate}${type.channels && type.channels > 1 ? `/${type.channels}` : ''}`);\n\n        const parameters = type.parameters;\n        if(Array.isArray(parameters)) {\n          if(parameters.length) {\n            log.error('parameters is array???', parameters);\n          }\n        } else if(parameters && Object.keys(parameters).length) {\n          const p: string[] = [];\n          for(const i in parameters) {\n            p.push(`${i}=${parameters[i]}`);\n          }\n          add(`a=fmtp:${type.id} ${p.join(';')}`);\n        }\n\n        const fbs = type['rtcp-fbs'];\n        if(fbs?.length) {\n          fbs.forEach((fb) => {\n            add(`a=rtcp-fb:${type.id} ${fb.type}${fb.subtype ? ' ' + fb.subtype : ''}`);\n          });\n        }\n      });\n    } else {\n      add(`a=sctpmap:${payloadTypes[0].id} webrtc-datachannel 256`);\n    }\n\n    if(entry.source && (setDirection === 'sendonly' || setDirection === 'sendrecv')) {\n      this.addSsrc(entry);\n    }\n\n    return this;\n  }\n\n  public addConference(options: {\n    conference: LocalConferenceDescription,\n    bundle: string[],\n    entries: ConferenceEntry[],\n    isAnswer?: boolean,\n  }) {\n    const {conference, entries, bundle, isAnswer} = options;\n    this.addHeader(conference.sessionId, bundle);\n\n    if(IS_FIREFOX) {\n      this.addTransport(conference.transport); // support Firefox\n    }\n\n    for(const entry of entries) {\n      // this.addSsrcEntry(entry, conference, isAnswer);\n      this.addSsrcEntry((isAnswer ? entry.recvEntry || entry.sendEntry : entry.sendEntry || entry.recvEntry) || entry, conference, isAnswer);\n    }\n\n    return this;\n  }\n\n  public static fromConference(options: Parameters<SDPBuilder['addConference']>[0]) {\n    return new SDPBuilder().addConference(options).finalize();\n  }\n\n  // ---- tgcalls v2 (1-on-1 / P2P) ----\n  // The flat NegotiateChannels signaling is a different SDP dialect from the\n  // group conference above, so it gets its own builder method — sharing this\n  // class's StringFromLineBuilder line accumulator.\n  public addP2p(options: P2PSdpOptions) {\n    const {\n      setup, mids, isAnswer, entries,\n      audioPayloadTypes, audioExtensions, videoPayloadTypes, videoExtensions,\n      sectionOrder, bundleMids, shouldKeepRemoteReceiveSection\n    } = options;\n\n    // Defence in depth for every SDPBuilder caller. InitialSetup originates in\n    // peer-controlled JSON; static types do not stop arrays/objects from reaching\n    // the template interpolations below and turning their stringification into\n    // injected SDP lines.\n    if(!isSdpSafeSetup(setup)) {\n      throw new Error('Invalid P2P transport setup');\n    }\n\n    const add = (line: string) => {\n      this.add(line);\n    };\n\n    // On an answer, sectionOrder is our own local offer — mirror its DTLS role.\n    const getAnswerSetupRole = (mid: string | undefined, fallback: string) => {\n      const offerSetup = sectionOrder?.find((section) => section.mid === mid)\n      ?.lines.find((line) => line.startsWith('a=setup:'))\n      ?.slice('a=setup:'.length);\n\n      if(offerSetup === 'active') {\n        return 'passive';\n      }\n      if(offerSetup === 'passive') {\n        return 'active';\n      }\n      if(fallback === 'active' || fallback === 'passive') {\n        return fallback;\n      }\n\n      return 'passive';\n    };\n\n    const addTransport = (mid?: string) => {\n      add(`a=ice-ufrag:${setup.ufrag}`);\n      add(`a=ice-pwd:${setup.pwd}`);\n      setup.fingerprints.forEach((fingerprint) => {\n        add(`a=fingerprint:${fingerprint.hash} ${fingerprint.fingerprint}`);\n        const setupRole = isAnswer ? getAnswerSetupRole(mid, fingerprint.setup) : fingerprint.setup;\n        add(`a=setup:${setupRole}`);\n      });\n    };\n\n    const addPayloadType = (payloadType: PayloadType) => {\n      const channels = payloadType.channels ? `/${payloadType.channels}` : '';\n      add(`a=rtpmap:${payloadType.id} ${payloadType.name}/${payloadType.clockrate}${channels}`);\n      if(payloadType.parameters) {\n        const parameters = Object.keys(payloadType.parameters).map((key) => {\n          return `${key}=${(payloadType.parameters as Record<string, string | number>)[key]}`;\n        }).join(';');\n        add(`a=fmtp:${payloadType.id} ${parameters}`);\n      }\n      payloadType['rtcp-fbs']?.forEach((feedback) => {\n        add(`a=rtcp-fb:${payloadType.id} ${feedback.type}${feedback.subtype ? ` ${feedback.subtype}` : ''}`);\n      });\n    };\n\n    const addMedia = (\n      entry: P2PSsrcEntry,\n      payloadTypes: PayloadType[],\n      extensions: RtpHdrexts[],\n      mediaType?: string,\n      shouldRejectRemoved = true,\n      direction?: RTCRtpTransceiverDirection\n    ) => {\n      mediaType = mediaType || (entry.isVideo ? 'video' : 'audio');\n      const port = entry.isRemoved && shouldRejectRemoved ? 0 : 9;\n      add(`m=${mediaType} ${port} UDP/TLS/RTP/SAVPF ${payloadTypes.map((payloadType) => payloadType.id).join(' ')}`);\n      add('c=IN IP4 0.0.0.0');\n      add(`a=mid:${entry.mid}`);\n      if(port === 0) {\n        add('a=inactive');\n        return;\n      }\n\n      add('b=AS:1300');\n      add('a=rtcp-mux');\n      payloadTypes.forEach(addPayloadType);\n      add('a=rtcp:1 IN IP4 0.0.0.0');\n      if(entry.isVideo) {\n        add('a=rtcp-rsize');\n      }\n      extensions.forEach(({id, uri}) => {\n        add(`a=extmap:${id} ${uri}`);\n      });\n      addTransport(entry.mid);\n      if(entry.isRemoved) {\n        add('a=inactive');\n        return;\n      }\n      add(`a=${direction || entry.direction || (isAnswer ? 'recvonly' : 'sendonly')}`);\n      if(isAnswer || direction === 'recvonly') {\n        return;\n      }\n\n      entry.sourceGroups.forEach((sourceGroup) => {\n        if(sourceGroup.semantics) {\n          add(`a=ssrc-group:${sourceGroup.semantics} ${sourceGroup.sources.join(' ')}`);\n        }\n        sourceGroup.sources.forEach((ssrc) => {\n          add(`a=ssrc:${ssrc} cname:${entry.endpoint}`);\n          add(`a=ssrc:${ssrc} msid:${entry.endpoint} ${entry.endpoint}`);\n          add(`a=ssrc:${ssrc} mslabel:${entry.endpoint}`);\n          add(`a=ssrc:${ssrc} label:${entry.endpoint}`);\n        });\n      });\n    };\n\n    const addApplication = (mid: string, shouldReject = false) => {\n      add(`m=application ${shouldReject ? 0 : 1} UDP/DTLS/SCTP webrtc-datachannel`);\n      add('c=IN IP4 0.0.0.0');\n      add(`a=mid:${mid}`);\n\n      if(shouldReject) {\n        add('a=inactive');\n        return;\n      }\n\n      addTransport(mid);\n      add('a=ice-options:trickle');\n      add('a=sctp-port:5000');\n      add('a=max-message-size:262144');\n    };\n\n    const getOrderedMedia = (section: SdpSection) => {\n      const fallbackEntry: P2PSsrcEntry = {\n        isVideo: section.kind === 'video',\n        isPresentation: false,\n        isMain: false,\n        isRemoved: true,\n        userId: '0',\n        endpoint: section.mid || '',\n        mid: section.mid || '',\n        sourceGroups: []\n      };\n      const entry = entries.find((item) => item.mid === section.mid) || fallbackEntry;\n      const shouldKeepLocalSection = !isAnswer && entry.isRemoved && shouldKeepEstablishedLocalSection(section);\n      const shouldKeepRemoteSection = isAnswer && entry.isRemoved && shouldKeepRemoteReceiveSection(section);\n      const keptMediaEntry = shouldKeepLocalSection || shouldKeepRemoteSection ? {...entry, isRemoved: false} : entry;\n      const shouldRejectOfferSection = isAnswer && !canAcceptOfferedBundledSection(section, bundleMids);\n      const mediaEntry = shouldRejectOfferSection ? {...keptMediaEntry, isRemoved: true} : keptMediaEntry;\n      const shouldRejectRemoved = isAnswer && (mediaEntry.isRemoved || shouldRejectOfferSection);\n      const payloadTypes = section.kind === 'audio' ? audioPayloadTypes : videoPayloadTypes;\n      const extensions = section.kind === 'audio' ? audioExtensions : videoExtensions;\n      const direction: RTCRtpTransceiverDirection | undefined = shouldKeepRemoteSection ? 'sendonly' :\n        (mediaEntry.isLocalOnly || shouldKeepLocalSection ? 'recvonly' : undefined);\n\n      return {direction, extensions, mediaEntry, payloadTypes, shouldRejectRemoved};\n    };\n\n    const getBundledOrderedMid = (section: SdpSection) => {\n      const mid = section.mid || (section.kind === 'application' ? mids.data : undefined);\n      if(!mid) {\n        return undefined;\n      }\n\n      if(section.kind === 'application') {\n        if(!isAnswer) {\n          return mid;\n        }\n\n        return canAcceptOfferedBundledSection(section, bundleMids) ? mid : undefined;\n      }\n\n      const {mediaEntry, shouldRejectRemoved} = getOrderedMedia(section);\n      return mediaEntry.isRemoved && shouldRejectRemoved ? undefined : mediaEntry.mid;\n    };\n\n    const addOrderedSection = (section: SdpSection) => {\n      if(section.kind === 'application') {\n        const mid = section.mid || mids.data;\n        const shouldRejectApplication = isAnswer && !canAcceptOfferedBundledSection(section, bundleMids);\n        addApplication(mid, shouldRejectApplication);\n        return;\n      }\n\n      const {direction, extensions, mediaEntry, payloadTypes, shouldRejectRemoved} = getOrderedMedia(section);\n      addMedia(mediaEntry, payloadTypes, extensions, section.kind, shouldRejectRemoved, direction);\n    };\n\n    const rawBundledMids = (sectionOrder?.map(getBundledOrderedMid).filter(Boolean) || [\n      ...entries.filter((entry) => !entry.isRemoved).map((entry) => entry.mid),\n      mids.data\n    ]).concat(isAnswer ? [] : entries.filter((entry) => {\n      return !entry.isRemoved && !sectionOrder?.some((section) => section.mid === entry.mid);\n    }).map((entry) => entry.mid));\n    const seenBundledMids = new Set<string>();\n    const bundledMids = rawBundledMids.filter((mid) => {\n      if(seenBundledMids.has(mid)) {\n        return false;\n      }\n\n      seenBundledMids.add(mid);\n      return true;\n    });\n\n    add('v=0');\n    add(`o=- ${Date.now()} 2 IN IP4 0.0.0.0`);\n    add('s=-');\n    add('t=0 0');\n    add('a=ice-options:trickle');\n    add('a=msid-semantic:WMS *');\n    add(`a=group:BUNDLE ${bundledMids.join(' ')}`);\n\n    if(sectionOrder?.length) {\n      sectionOrder.forEach(addOrderedSection);\n      entries.filter((entry) => {\n        return !sectionOrder.some((section) => section.mid === entry.mid);\n      }).forEach((entry) => {\n        const payloadTypes = entry.isVideo ? videoPayloadTypes : audioPayloadTypes;\n        const extensions = entry.isVideo ? videoExtensions : audioExtensions;\n        addMedia(entry, payloadTypes, extensions, undefined, true, entry.isLocalOnly ? 'recvonly' : undefined);\n      });\n    } else {\n      entries.forEach((entry) => {\n        const payloadTypes = entry.isVideo ? videoPayloadTypes : audioPayloadTypes;\n        const extensions = entry.isVideo ? videoExtensions : audioExtensions;\n        addMedia(entry, payloadTypes, extensions, undefined, true, entry.isLocalOnly ? 'recvonly' : undefined);\n      });\n      addApplication(mids.data);\n    }\n\n    return this;\n  }\n\n  public static fromP2p(options: P2PSdpOptions) {\n    return new SDPBuilder().addP2p(options).finalize();\n  }\n}\n\nexport type P2PSdpSsrcGroup = {\n  semantics?: string,\n  sources: (string | number)[]\n};\n\n// One media section's SSRC/identity data for P2P SDP generation.\nexport type P2PSsrcEntry = {\n  isVideo: boolean,\n  isPresentation: boolean,\n  isMain: boolean,\n  isRemoved?: boolean,\n  userId: string,\n  endpoint: string,\n  mid: string,\n  sourceGroups: P2PSdpSsrcGroup[],\n  direction?: RTCRtpTransceiverDirection,\n  isLocalOnly?: boolean\n};\n\nexport type P2PMediaMids = {\n  audio: string,\n  video: string,\n  presentation: string,\n  data: string\n};\n\nexport type P2PSdpOptions = {\n  setup: CallSignalingData.initialSetup,\n  mids: P2PMediaMids,\n  isAnswer: boolean,\n  entries: P2PSsrcEntry[],\n  audioPayloadTypes: PayloadType[],\n  audioExtensions: RtpHdrexts[],\n  videoPayloadTypes: PayloadType[],\n  videoExtensions: RtpHdrexts[],\n  sectionOrder?: SdpSection[],\n  bundleMids?: string[],\n  // a state-dependent decision the p2pCall engine supplies (it reads live tracks)\n  shouldKeepRemoteReceiveSection: (section: SdpSection) => boolean\n};\n\nfunction hasBundleOnly(section: SdpSection) {\n  return section.lines.includes('a=bundle-only');\n}\n\nfunction isRejectedOfferSection(section: SdpSection) {\n  return getSdpPort(section) === 0 && !hasBundleOnly(section);\n}\n\nfunction isOfferedInBundle(section: SdpSection, bundleMids: string[] | undefined) {\n  return Boolean(section.mid && (!bundleMids || bundleMids.includes(section.mid)));\n}\n\nfunction canAcceptOfferedBundledSection(section: SdpSection, bundleMids: string[] | undefined) {\n  return isOfferedInBundle(section, bundleMids) && !isRejectedOfferSection(section);\n}\n\nfunction shouldKeepEstablishedLocalSection(section: SdpSection) {\n  if(section.kind !== 'audio' && section.kind !== 'video') {\n    return false;\n  }\n\n  const direction = getSdpDirection(section);\n  return getSdpPort(section) !== 0 && (direction === 'recvonly' || direction === 'sendrecv');\n}\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {logger} from '@lib/logger';\nimport {GROUP_CALL_AMPLITUDE_ANALYSE_COUNT_MAX} from '@lib/calls/constants';\nimport stopTrack from '@lib/calls/helpers/stopTrack';\nimport LocalConferenceDescription from '@lib/calls/localConferenceDescription';\nimport {fixMediaLineType, WebRTCLineType} from '@lib/calls/sdpBuilder';\nimport {getAmplitude, toTelegramSource} from '@lib/calls/utils';\n\nexport async function waitForMediaTrackReplacements(replacements: Promise<void>[]): Promise<void> {\n  const results = await Promise.allSettled(replacements);\n  const rejected = results.find((result): result is PromiseRejectedResult => result.status === 'rejected');\n  if(rejected) throw rejected.reason;\n}\n\nexport type StreamItemBase = {\n  type: 'input' | 'output',\n  track: MediaStreamTrack,\n  source: string,\n  stream: MediaStream\n};\n\nexport type StreamItem = StreamAudioItem | StreamVideoItem;\n\nexport type StreamAudioItem = StreamItemBase & {kind: 'audio', streamAnalyser: AudioStreamAnalyser};\nexport type StreamVideoItem = StreamItemBase & {kind: 'video'};\n\nexport type StreamAmplitude = {\n  type: 'input' | 'output';\n  source: string;\n  stream: MediaStream;\n  track: MediaStreamTrack;\n  value: number;\n};\n\nclass AudioStreamAnalyser {\n  public analyser: AnalyserNode;\n  public gain: GainNode;\n  public streamSource: MediaStreamAudioSourceNode;\n\n  constructor(context: AudioContext, stream: MediaStream) {\n    const streamSource = this.streamSource = context.createMediaStreamSource(stream);\n    const analyser = this.analyser = context.createAnalyser();\n    const gain = this.gain = context.createGain();\n    // const streamDestination = context.createMediaStreamDestination();\n\n    analyser.minDecibels = -100;\n    analyser.maxDecibels = -30;\n    analyser.smoothingTimeConstant = 0.05;\n    analyser.fftSize = 1024;\n\n    // connect Web Audio API\n    streamSource.connect(analyser);\n    // analyser.connect(context.destination);\n  }\n\n  public disconnect() {\n    this.streamSource.disconnect();\n    this.analyser.disconnect();\n  }\n}\n\nexport default class StreamManager {\n  public static ANALYSER_LISTENER = new EventListenerBase<{amplitude: (details: {amplitudes: StreamAmplitude[], type: 'all' | 'input'}) => void}>();\n  private context: AudioContext;\n  public outputStream: MediaStream;\n  public inputStream: MediaStream;\n\n  private timer: number;\n  private counter: number;\n\n  private items: StreamItem[];\n\n  private log: ReturnType<typeof logger>;\n\n  public direction: RTCRtpTransceiver['direction'];\n  public canCreateConferenceEntry: boolean;\n  public locked: boolean;\n  public types: WebRTCLineType[];\n\n  constructor(private interval?: number) {\n    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();\n    this.items = [];\n    this.outputStream = new MediaStream();\n    this.inputStream = new MediaStream();\n    this.counter = 0;\n    this.log = logger('SM');\n    this.direction = 'sendonly';\n    this.canCreateConferenceEntry = true;\n    // this.lol = true;\n    this.types = ['audio', 'video'];\n  }\n\n  public addStream(stream: MediaStream, type: StreamItem['type']) {\n    stream.getTracks().forEach((track) => {\n      this.addTrack(stream, track, type);\n    });\n  }\n\n  public addTrack(stream: MediaStream, track: MediaStreamTrack, type: StreamItem['type']) {\n    this.log('addTrack', type, track, stream);\n\n    const {context, items, inputStream, outputStream} = this;\n    const kind: StreamItem['kind'] = track.kind as any;\n    const source = StreamManager.getSource(stream, type);\n\n    // this.removeTrack(track);\n    switch(type) {\n      case 'input': {\n        if(!inputStream) {\n          this.inputStream = stream;\n        } else {\n          inputStream.addTrack(track);\n        }\n\n        break;\n      }\n\n      case 'output': {\n        for(let i = 0; i < items.length; ++i) {\n          const {track: t, type, source: itemSource} = items[i];\n          if(itemSource === source && type === 'input') {\n            this.discardItem(i);\n            outputStream.removeTrack(t);\n            break;\n          }\n        }\n\n        if(kind !== 'video') {\n          outputStream.addTrack(track);\n        }\n\n        break;\n      }\n    }\n\n    // A stopped manager has closed its context; a source node cannot be created\n    // on a closed one. The amplitude reader tolerates a missing analyser.\n    const canAnalyse = kind === 'audio' && context.state !== 'closed';\n    this.finalizeAddingTrack({\n      type,\n      source,\n      stream,\n      track,\n      kind,\n      streamAnalyser: canAnalyse ? new AudioStreamAnalyser(context, stream) : undefined\n    });\n\n    if(kind === 'audio' && this.interval) {\n      this.changeTimer();\n    }\n  }\n\n  private finalizeAddingTrack(item: StreamItem) {\n    const {track} = item;\n    track.addEventListener('ended', () => {\n      this.removeTrack(track);\n    }, {once: true});\n\n    this.items.push(item);\n  }\n\n  // Drops an item and releases its Web Audio nodes. A source node keeps the\n  // context graph (and the track it reads) referenced until it is disconnected.\n  private discardItem(index: number) {\n    const [item] = this.items.splice(index, 1);\n    if(item.kind === 'audio') {\n      item.streamAnalyser?.disconnect();\n    }\n  }\n\n  public hasInputTrackKind(kind: StreamItem['kind']) {\n    return this.items.find((item) => item.type === 'input' && item.kind === kind);\n  }\n\n  public static getSource(stream: MediaStream, type: StreamItem['type']) {\n    return type === 'input' ? (stream.source || stream.id) : '' + toTelegramSource(+stream.id.substring(6));\n  }\n\n  public removeTrack(track: MediaStreamTrack) {\n    this.log('removeTrack', track);\n\n    const {items} = this;\n\n    let handled = false;\n    for(let i = 0, length = items.length; !handled && i < length; ++i) {\n      const {track: t, type} = items[i];\n      switch(type) {\n        case 'output': {\n          if(t === track) {\n            this.discardItem(i);\n            this.outputStream.removeTrack(track);\n            handled = true;\n          }\n\n          break;\n        }\n\n        case 'input': {\n          if(t === track) {\n            this.discardItem(i);\n            this.inputStream.removeTrack(track);\n            handled = true;\n          }\n\n          break;\n        }\n      }\n    }\n\n    if(track.kind === 'audio' && this.interval) {\n      this.changeTimer();\n    }\n  }\n\n  public replaceInputAudio(stream: MediaStream, oldTrack: MediaStreamTrack) {\n    this.removeTrack(oldTrack);\n    this.addStream(stream, 'input');\n  }\n\n  private changeTimer() {\n    if(this.timer !== undefined) {\n      clearInterval(this.timer);\n    }\n\n    if(this.items.length) {\n      this.timer = window.setInterval(this.analyse, this.interval);\n    }\n  }\n\n  public getAmplitude = (item: StreamAudioItem): StreamAmplitude => {\n    const {streamAnalyser, stream, track, source, type} = item;\n    const analyser = streamAnalyser?.analyser;\n    if(!analyser) return;\n\n    const array = new Uint8Array(analyser.frequencyBinCount);\n    analyser.getByteFrequencyData(array);\n    const value = getAmplitude(array);\n\n    return {\n      type,\n      source,\n      stream,\n      track,\n      value\n    };\n  };\n\n  public analyse = () => {\n    const all = this.counter % 3 === 0;\n    const filteredItems = all ? this.items : this.items.filter((x) => x.type === 'input');\n    const audioItems = filteredItems.filter((x) => x.kind === 'audio') as StreamAudioItem[];\n    const amplitudes = audioItems.slice(0, GROUP_CALL_AMPLITUDE_ANALYSE_COUNT_MAX).map(this.getAmplitude);\n    if(++this.counter >= 1000) {\n      this.counter = 0;\n    }\n\n    StreamManager.ANALYSER_LISTENER.dispatchEvent('amplitude', {\n      amplitudes,\n      type: all ? 'all' : 'input'\n    });\n  };\n\n  /* public appendToConnection(connection: RTCPeerConnection) {\n    if(this.inputStream) {\n      this.inputStream.getTracks().forEach((track) => {\n        connection.log('addTrack', track);\n        connection.addTrack(track, this.inputStream);\n\n        if(track.kind === 'video') {\n          track.enabled = true;\n        }\n      });\n    }\n  } */\n\n  // `onSenderCreated` fires the moment a new transceiver is born, BEFORE\n  // `replaceTrack` wires its first frame into the encoder. The conference\n  // path uses this to attach `RTCRtpScriptTransform` early enough that\n  // Chrome doesn't reject it as \"Too late to create encoded streams\" — see\n  // memory tde2e-port.md K-2 for the timing details.\n  public async appendToConference(\n    conference: LocalConferenceDescription,\n    onSenderCreated?: (sender: RTCRtpSender) => void,\n    throwOnReplaceError = false\n  ): Promise<void> {\n    if(this.locked) {\n      return Promise.resolve();\n    }\n\n    const {inputStream, direction, canCreateConferenceEntry} = this;\n    const transceiverInit: RTCRtpTransceiverInit = {direction, streams: [inputStream]};\n    const types = this.types.map((type) => {\n      return [\n        type,\n        /* type === 'video' || type === 'screencast' ?\n          {sendEncodings: [{maxBitrate: 2500000}], ...transceiverInit} :  */\n        transceiverInit\n      ] as const;\n    });\n\n    const tracks = inputStream.getTracks();\n    const replacements: {\n      sender: RTCRtpSender,\n      previousTrack: MediaStreamTrack | null,\n      promise: Promise<void>\n    }[] = [];\n    // const transceivers = conference.connection.getTransceivers();\n    for(const [type, transceiverInit] of types) {\n      let entry = conference.findEntry((entry) => entry.direction === direction && entry.type === type);\n      if(!entry) {\n        if(!canCreateConferenceEntry) {\n          continue;\n        }\n\n        entry = conference.createEntry(type);\n      }\n      /* const entry = conference.findFreeSendRecvEntry(type, true);\n      if(!entry.transceiver) {\n        entry.transceiver = transceivers.find((transceiver) => transceiver.mid === entry.mid);\n      } */\n\n      let {transceiver} = entry;\n      let newlyCreated = false;\n      if(!transceiver) {\n        transceiver = entry.createTransceiver(conference.connection, transceiverInit);\n        newlyCreated = true;\n\n        /* if(this.isScreenSharingManager) {\n          transceiver.sender.setParameters({\n            ...transceiver.sender.getParameters(),\n            degradationPreference: 'maintain-resolution'\n          });\n        } */\n      }\n\n      if(entry.direction !== transceiver.direction) {\n        transceiver.direction = entry.direction;\n      }\n\n      const mediaTrackType = fixMediaLineType(type);\n      const trackIdx = tracks.findIndex((track) => track.kind === mediaTrackType);\n      const track = trackIdx !== -1 ? tracks.splice(trackIdx, 1)[0] : undefined;\n      const sender = transceiver.sender;\n\n      // Critical: attach the e2e script transform IN BETWEEN createTransceiver\n      // and replaceTrack — the only window Chrome's script-transform machinery\n      // accepts. Once `replaceTrack` wires a real track into the sender, the\n      // encoder produces its first frame and Chrome silently rejects any\n      // transform assigned after that (the parallel createEncodedStreams API\n      // surfaces this as an explicit \"Too late to create encoded streams\").\n      //\n      // Fire the hook BEFORE the `sender.track === track` skip below — when\n      // both sides are undefined (e.g. preview without mic / mic denied) the\n      // skip would otherwise hide the hook entirely, and no transform would\n      // ever attach.\n      if(newlyCreated && onSenderCreated) {\n        onSenderCreated(sender);\n      }\n\n      if(sender.track === track) {\n        continue;\n      }\n\n      // Start replacement synchronously so a following createOffer sees the\n      // sender immediately. Runtime media transactions may still await the\n      // returned promise and roll back if the browser rejects replacement;\n      // legacy fire-and-forget callers retain the old logged-error behaviour.\n      const previousTrack = sender.track;\n      let replacement: Promise<void>;\n      try {\n        replacement = sender.replaceTrack(track);\n      } catch(err) {\n        replacement = Promise.reject(err);\n      }\n      replacements.push({\n        sender,\n        previousTrack,\n        promise: throwOnReplaceError ? replacement : replacement.catch((err) => {\n          this.log.error(err);\n        })\n      });\n    }\n\n    try {\n      await waitForMediaTrackReplacements(replacements.map(({promise}) => promise));\n    } catch(err) {\n      // A conference can own several senders. Promise.allSettled tells us only\n      // after every replace completed, so a rejection may coexist with other\n      // senders already carrying the new stream. Restore the complete previous\n      // sender set before the caller removes/stops the rejected local tracks.\n      const rollbackResults = await Promise.allSettled(replacements.map(({sender, previousTrack}) => {\n        return sender.replaceTrack(previousTrack);\n      }));\n      rollbackResults.forEach((result) => {\n        if(result.status === 'rejected') this.log.error('replaceTrack rollback failed', result.reason);\n      });\n      throw err;\n    }\n  }\n\n  public stop() {\n    try {\n      const tracks = this.inputStream.getTracks().concat(this.outputStream.getTracks());\n      tracks.forEach((track) => {\n        stopTrack(track);\n      });\n    } catch(e) {\n      this.log.error(e);\n    }\n\n    // stopTrack's synthetic `ended` removed the listed tracks above; sweep the\n    // rest (output video is never added to outputStream) so no analyser stays\n    // wired, then stop the timer that would read them.\n    while(this.items.length) {\n      this.discardItem(this.items.length - 1);\n    }\n    if(this.timer !== undefined) {\n      clearInterval(this.timer);\n      this.timer = undefined;\n    }\n\n    // Every StreamManager owns an AudioContext and only the tracks were ever\n    // stopped, so each call (and every camera/screen connection within it)\n    // leaked a running context — an audio thread per leftover manager. Close\n    // it; `state` and `close` are guarded for environments without Web Audio.\n    const {context} = this;\n    if(context && context.state !== 'closed' && typeof context.close === 'function') {\n      context.close().catch((err) => {\n        this.log.error('closing the audio context failed', err);\n      });\n    }\n  }\n}\n","// Decide whether a `<video>` element backed by a given track should get the\n// `.call-video-mirror` class. Front-facing (\"user\") and unspecified-facing\n// tracks read as a mirror (selfie expectation: pat hair on the correct side);\n// rear-facing (\"environment\") tracks render in their native orientation\n// because mirroring an outward-pointing camera would invert any text the\n// user holds up, which is the opposite of helpful.\n//\n// Screen / window / tab capture (getDisplayMedia, identifiable by\n// `displaySurface`) is NEVER mirrored: it isn't a selfie, and flipping it\n// would reverse any text on the shared screen. Such tracks carry no\n// `facingMode`, so without this check they'd fall through to the\n// \"unspecified → mirror\" default and come out backwards.\n//\n// `getSettings()` is the standard MediaStreamTrack API and is widely\n// supported in modern browsers; we still wrap it in try/catch because\n// older Safari builds throw on certain track flavours (screen capture,\n// captureStream from canvas, etc.) — in those cases we err toward\n// mirroring, which is the common case.\nexport default function shouldMirrorVideoTrack(track: MediaStreamTrack | undefined | null): boolean {\n  if(!track || track.kind !== 'video') return false;\n\n  let facingMode: string | undefined;\n  try {\n    const settings = track.getSettings();\n    if((settings as {displaySurface?: string})?.displaySurface) return false;\n    facingMode = settings?.facingMode;\n  } catch(_) {}\n\n  // `getSettings().facingMode` is the spec signal, but iOS Safari leaves it\n  // EMPTY when the camera was opened by `deviceId` (exact) instead of a\n  // `facingMode` constraint — which is exactly how the Speakers-and-Camera\n  // picker and an in-call device swap open it. So a rear camera picked from\n  // the list would fall through to the \"unspecified → mirror\" selfie default\n  // and come out backwards. Recover the facing from `getCapabilities()` (its\n  // `facingMode` is an array of the camera's supported modes; a physical\n  // camera advertises exactly one)…\n  if(!facingMode) {\n    try {\n      facingMode = track.getCapabilities?.()?.facingMode?.[0];\n    } catch(_) {}\n  }\n\n  // …and finally from the human-readable label, the most reliable rear signal\n  // on the platforms that actually have two cameras: iOS (\"Back Camera\") and\n  // Android Chrome (\"camera2 0, facing back\"). Desktop webcams advertise no\n  // direction in their label, so they keep falling through to the mirror\n  // default below — no regression for laptop FaceTime/USB cams.\n  if(!facingMode && /\\b(back|rear)\\b/i.test(track.label || '')) return false;\n\n  return facingMode !== 'environment';\n}\n","import safePlay from '@helpers/dom/safePlay';\nimport EventListenerBase, {EventListenerListeners} from '@helpers/eventListenerBase';\nimport createSerializedQueue, {SerializedQueue} from '@helpers/createSerializedQueue';\nimport {logger} from '@lib/logger';\nimport getAudioConstraints from '@lib/calls/helpers/getAudioConstraints';\nimport getScreenConstraints from '@lib/calls/helpers/getScreenConstraints';\nimport getStream from '@lib/calls/helpers/getStream';\nimport getStreamCached from '@lib/calls/helpers/getStreamCached';\nimport getVideoConstraints from '@lib/calls/helpers/getVideoConstraints';\nimport stopTrack from '@lib/calls/helpers/stopTrack';\nimport LocalConferenceDescription from '@lib/calls/localConferenceDescription';\nimport StreamManager, {StreamItem} from '@lib/calls/streamManager';\nimport shouldMirrorVideoTrack from '@lib/calls/helpers/shouldMirrorVideoTrack';\nimport {appSettings} from '@stores/appSettings';\n\nexport type TryAddTrackOptions = {\n  stream: MediaStream,\n  track: MediaStreamTrack,\n  type: StreamItem['type'],\n  source?: string\n};\n\ntype MediaDeviceChangeKind = 'audio' | 'video' | 'output';\n\nexport default abstract class CallInstanceBase<E extends EventListenerListeners> extends EventListenerBase<E> {\n  protected log: ReturnType<typeof logger>;\n  protected outputDeviceId: string;\n\n  private mediaDeviceChangeGenerations: Record<MediaDeviceChangeKind, number> = {\n    audio: 0,\n    video: 0,\n    output: 0\n  };\n  private mediaDeviceChangeQueues: Record<MediaDeviceChangeKind, SerializedQueue> = {\n    audio: createSerializedQueue(),\n    video: createSerializedQueue(),\n    output: createSerializedQueue()\n  };\n  protected pendingInputAudioTracks = new Set<MediaStreamTrack>();\n\n  protected player: HTMLElement;\n  protected elements: Map<string, HTMLMediaElement>;\n\n  protected audio: HTMLAudioElement;\n  // protected fixedSafariAudio: boolean;\n\n  protected getStream: ReturnType<typeof getStreamCached>;\n\n  constructor() {\n    super(false);\n\n    // Keep `outputDeviceId` as the last sink that every owned element actually\n    // accepted. A persisted id is only a requested value until setSinkId\n    // succeeds; seeding the committed field with it made a rejected startup\n    // application roll back to the same unavailable sink and left future\n    // elements believing it was live.\n    const persistedOutputDeviceId = appSettings.callDevices?.speakerId || '';\n    this.outputDeviceId = '';\n\n    const player = this.player = document.createElement('div');\n    player.classList.add('call-player');\n    player.style.display = 'none';\n    document.body.append(player);\n\n    this.elements = new Map();\n\n    // possible Safari fix\n    const audio = this.audio = new Audio();\n    audio.autoplay = true;\n    audio.volume = 1.0;\n    this.player.append(audio);\n    this.elements.set('audio', audio);\n\n    this.fixSafariAudio();\n\n    this.getStream = getStreamCached();\n\n    if(persistedOutputDeviceId) {\n      // Reuse the same generation/serialization path as a live picker change.\n      // This makes an immediate user selection supersede a still-pending saved\n      // sink instead of the late constructor write winning the race.\n      void this.setOutputDeviceId(persistedOutputDeviceId).catch((err) => {\n        this.log?.warn?.('applying persisted call speaker failed', err);\n      });\n    }\n  }\n\n  public get isSharingAudio() {\n    return !!this.streamManager.hasInputTrackKind('audio');\n  }\n\n  public get isSharingVideo() {\n    return !!this.streamManager.hasInputTrackKind('video');\n  }\n\n  public abstract get isMuted(): boolean;\n  public abstract get isClosing(): boolean;\n\n  public fixSafariAudio() {\n    // if(this.fixedSafariAudio) return;\n    safePlay(this.audio);\n    // this.fixedSafariAudio = true;\n  }\n\n  protected isInputTrackAvailable(track: MediaStreamTrack | undefined): boolean {\n    return !!track && track.readyState === 'live' && !track.muted;\n  }\n\n  public async requestAudioSource(muted: boolean): Promise<void> {\n    const currentTrack = this.streamManager?.inputStream?.getAudioTracks()[0];\n    if(currentTrack && !this.isInputTrackAvailable(currentTrack)) {\n      // A live-but-muted source is not producing samples. Leaving it enabled\n      // made every later unmute reuse the same dead capture forever. Keep the\n      // transition fail-closed and reuse the transactional device-swap path so\n      // the sender, StreamManager and cleanup bookkeeping change together.\n      this.setMuted(true);\n      await this.setInputAudioDeviceId(appSettings.callDevices?.microphoneId || '');\n    }\n\n    await this.requestInputSource(true, false, muted);\n\n    const activeTrack = this.streamManager?.inputStream?.getAudioTracks()[0];\n    if(!this.isInputTrackAvailable(activeTrack)) {\n      this.setMuted(true);\n      throw new DOMException('Microphone capture is unavailable', 'NotReadableError');\n    }\n  }\n\n  public requestInputSource(audio: boolean, video: boolean, muted: boolean) {\n    const {streamManager} = this;\n    if(streamManager) {\n      const isAudioGood = !audio || this.isSharingAudio;\n      const isVideoGood = !video || this.isSharingVideo;\n      if(isAudioGood && isVideoGood) {\n        return Promise.resolve();\n      }\n    }\n\n    const constraints: MediaStreamConstraints = {\n      audio: audio && getAudioConstraints(),\n      video: video && getVideoConstraints()\n    };\n\n    return this.getStream({\n      constraints,\n      muted\n    }).then((stream) => {\n      return this.onInputStream(stream);\n    });\n  }\n\n  public requestScreen() {\n    return this.getStream({\n      isScreen: true,\n      constraints: getScreenConstraints(true)\n    }).then((stream) => {\n      return this.onInputStream(stream);\n    });\n  }\n\n  public getElement(endpoint: number | string) {\n    return this.elements.get('' + endpoint);\n  }\n\n  public abstract get streamManager(): StreamManager;\n  public abstract get description(): LocalConferenceDescription;\n  public abstract toggleMuted(): Promise<void>;\n\n  public cleanup() {\n    // Invalidate getUserMedia / setSinkId work that can still resolve after\n    // the call has already released its registered streams and elements.\n    for(const kind of ['audio', 'video', 'output'] as const) {\n      ++this.mediaDeviceChangeGenerations[kind];\n    }\n    this.pendingInputAudioTracks.forEach((track) => stopTrack(track));\n    this.pendingInputAudioTracks.clear();\n\n    this.player.textContent = '';\n    this.player.remove();\n    this.elements.clear();\n\n    // can have no connectionInstance but streamManager with input stream\n    this.streamManager.stop();\n\n    super.cleanup();\n  }\n\n  public onTrack(event: RTCTrackEvent) {\n    this.tryAddTrack({\n      stream: event.streams[0],\n      track: event.track,\n      type: 'output'\n    });\n  }\n\n  public saveInputVideoStream(stream: MediaStream, type?: string) {\n    const track = stream.getVideoTracks()[0];\n    this.tryAddTrack({\n      stream,\n      track,\n      type: 'input',\n      source: type || 'main'\n    });\n  }\n\n  public tryAddTrack({stream, track, type, source}: TryAddTrackOptions) {\n    if(!source) {\n      source = StreamManager.getSource(stream, type);\n    }\n\n    this.log('tryAddTrack', stream, track, type, source);\n\n    const isOutput = type === 'output';\n\n    const {player, elements, streamManager} = this;\n\n    const tagName = track.kind as StreamItem['kind'];\n    const isVideo = tagName === 'video';\n\n    const elementEndpoint = isVideo ? source : tagName;\n    let element = elements.get(elementEndpoint);\n\n    if(isVideo) {\n      track.addEventListener('ended', () => {\n        this.log('[track] onended');\n        elements.delete(elementEndpoint);\n        // element.remove();\n      }, {once: true});\n    }\n\n    if(isOutput) {\n      streamManager.addTrack(stream, track, type);\n    }\n\n    const useStream = isVideo ? stream : streamManager.outputStream;\n    if(!element) {\n      element = document.createElement(tagName);\n      element.autoplay = true;\n      element.srcObject = useStream;\n      element.volume = 1.0;\n\n      this.applyCurrentOutputDeviceToElement(element);\n\n      if(!isVideo) {\n        player.appendChild(element);\n      } else {\n        element.setAttribute('playsinline', 'true');\n        element.muted = true;\n        // Mirror ONLY our own self-view (`type === 'input'`), never the remote\n        // participant's video (`type === 'output'`). This matches every video\n        // client (iOS/tgcalls, FaceTime, Zoom, …): the left/right flip is a\n        // local presentation convenience so you see yourself as in a mirror\n        // (pat your hair on the correct side). It is NOT a property of the\n        // stream — the pixels on the wire are always un-mirrored, so the other\n        // side sees us as in real life (text/gestures un-inverted). Mirroring\n        // their incoming feed too would flip any text they hold up and reverse\n        // their gestures relative to reality. tgcalls enforces this by only\n        // flipping frames from the local camera buffer (TGRTCCVPixelBuffer);\n        // decoded remote frames are never flipped.\n        //\n        // Exception: our own rear-facing camera (`facingMode === 'environment'`)\n        // stays un-mirrored — flipping it would invert any text or sign the\n        // user is pointing the camera at. shouldMirrorVideoTrack handles that.\n        if(type === 'input' && shouldMirrorVideoTrack(track)) {\n          element.classList.add('call-video-mirror');\n        }\n      }\n      // audio.play();\n\n      elements.set(elementEndpoint, element);\n    } else {\n      // ! EVEN IF MEDIASTREAM IS THE SAME NEW TRACK WON'T PLAY WITHOUT REPLACING IT WHEN NEW PARTICIPANT IS ENTERING !\n      // if(element.srcObject !== useStream) {\n      element.srcObject = useStream;\n      // }\n    }\n\n    // The shared audio element is created and play()-primed before it has a\n    // source. Assigning srcObject afterwards does not reliably restart it,\n    // especially when a remote track appears muted and starts producing frames\n    // only after async negotiation/decryption. Always play after the source is\n    // installed, and retry once when that first track becomes live.\n    safePlay(element);\n    if(track.muted) {\n      track.addEventListener('unmute', () => {\n        if(element.srcObject === useStream) {\n          safePlay(element);\n        }\n      }, {once: true});\n    }\n\n    return source;\n  }\n\n  public setMuted(muted?: boolean) {\n    const tracks = new Set<MediaStreamTrack>(this.streamManager.inputStream.getAudioTracks());\n    this.pendingInputAudioTracks.forEach((track) => tracks.add(track));\n    tracks.forEach((track) => {\n      if(track?.kind === 'audio') {\n        track.enabled = muted === undefined ? !track.enabled : !muted;\n      }\n    });\n  }\n\n  /**\n   * Every live media element whose output sink belongs to this call.\n   *\n   * Most call types render through `elements`. P2P owns one additional audio\n   * element in its engine state, so subclasses can extend this iterable while\n   * the base class keeps generation, serialization and rollback in one place.\n   */\n  protected getOutputDeviceElements(): Iterable<HTMLMediaElement> {\n    return this.elements.values();\n  }\n\n  protected applyCurrentOutputDeviceToElement(element: HTMLMediaElement): void {\n    if(typeof((element as any).setSinkId) !== 'function') return;\n\n    // The element can appear while a picker transaction is in flight. Queue\n    // behind it and read the committed id only when this operation runs; an\n    // eager read could apply the old sink after the newer selection committed.\n    void this.serializeMediaDeviceChange('output', async() => {\n      const deviceId = this.outputDeviceId;\n      if(!deviceId) return;\n      try {\n        await (element as any).setSinkId(deviceId);\n      } catch(err) {\n        // A single newly-created media element failing its saved sink must not\n        // reject an unrelated track attachment or become unhandled.\n        this.log?.warn?.('applying call speaker to a new media element failed', err);\n      }\n    });\n  }\n\n  // Apply a new audio output device to every <audio> / <video> element we\n  // own. Used by the in-call settings popup when the user picks a different\n  // speaker — the change must propagate to live elements, not just future\n  // ones (those pick up `this.outputDeviceId` in `tryAddTrack`).\n  public async setOutputDeviceId(deviceId: string): Promise<boolean> {\n    const generation = this.beginMediaDeviceChange('output');\n    const nextDeviceId = deviceId || '';\n\n    return this.serializeMediaDeviceChange('output', async() => {\n      if(!this.isMediaDeviceChangeCurrent('output', generation)) return false;\n\n      const previousDeviceId = this.outputDeviceId;\n      const elements = [...new Set(this.getOutputDeviceElements())].filter((element) => {\n        return typeof (element as any).setSinkId === 'function';\n      });\n      const results = await Promise.allSettled(elements.map((element) => {\n        return Promise.resolve().then(() => (element as any).setSinkId(nextDeviceId) as Promise<void>);\n      }));\n      const rejected = results.find((result): result is PromiseRejectedResult => result.status === 'rejected');\n\n      if(rejected || !this.isMediaDeviceChangeCurrent('output', generation)) {\n        // setSinkId is per-element, so a later element may reject after an\n        // earlier one already switched. Restore the last committed sink before\n        // allowing the next queued selection to run.\n        await Promise.allSettled(elements.map((element) => {\n          return Promise.resolve().then(() => (element as any).setSinkId(previousDeviceId) as Promise<void>);\n        }));\n        if(rejected) throw rejected.reason;\n        return false;\n      }\n\n      this.outputDeviceId = nextDeviceId;\n      return true;\n    });\n  }\n\n  protected beginMediaDeviceChange(kind: MediaDeviceChangeKind): number {\n    return ++this.mediaDeviceChangeGenerations[kind];\n  }\n\n  protected isMediaDeviceChangeCurrent(kind: MediaDeviceChangeKind, generation: number): boolean {\n    return this.mediaDeviceChangeGenerations[kind] === generation;\n  }\n\n  protected serializeMediaDeviceChange<T>(kind: MediaDeviceChangeKind, callback: () => Promise<T>): Promise<T> {\n    return this.mediaDeviceChangeQueues[kind].enqueue(callback);\n  }\n\n  /**\n   * The ONE mid-call input-device swap transaction: acquire the replacement\n   * stream, serialize the sender commit per kind, keep a pending audio track\n   * registered while the swap is in flight, and unwind on every stale/closing\n   * detection. Both the streamManager-backed calls (this class) and P2P (which\n   * keeps its local streams outside StreamManager) run THIS method — they\n   * differ only in the hooks below, never in the transaction shape.\n   */\n  protected async runInputDeviceSwap(opts: {\n    kind: 'audio' | 'video',\n    constraints: MediaStreamConstraints,\n    /**\n     * undefined → proceed; boolean → abandon the swap (the fresh stream is\n     * released) with that result. Sites: 'acquired' (right after getUserMedia),\n     * 'queued' (entering the per-kind serialization queue), 'swapped' (after a\n     * successful sender swap — `false` additionally triggers `rollback`) and\n     * 'failed' (after a rejected swap; undefined rethrows the swap error).\n     * Each caller encodes its own staleness predicates AND their per-site\n     * precedence, which is why this is a function of the site.\n     */\n    shouldAbandon: (site: 'acquired' | 'queued' | 'swapped' | 'failed', generation: number) => boolean | undefined,\n    /**\n     * Resolve the live swap targets once inside the queue. undefined → no\n     * usable sender/track pair (throws the common could-not-replace error).\n     * `rollback` carries its own applicability guards.\n     */\n    resolveSwap: (newTrack: MediaStreamTrack) => {\n      oldTrack: MediaStreamTrack,\n      swap: () => MaybePromise<void>,\n      rollback: () => MaybePromise<void>\n    } | undefined,\n    /**\n     * A multi-sender swap can fail half-applied and must be compensated; a\n     * single-sender replaceTrack that rejects leaves the old track in place\n     * per spec, so compensating would only double the churn.\n     */\n    rollbackOnSwapFailure: boolean,\n    getPendingAudioEnabled: (oldTrack: MediaStreamTrack) => boolean,\n    release?: (stream: MediaStream) => void,\n    commit: (newStream: MediaStream, newTrack: MediaStreamTrack, oldTrack: MediaStreamTrack) => void,\n    acquisitionFailureLogLevel?: 'error' | 'warn'\n  }): Promise<boolean> {\n    const {kind} = opts;\n    const label = `setInput${kind === 'audio' ? 'Audio' : 'Video'}DeviceId`;\n    const release = opts.release ?? ((stream: MediaStream) => stream.getTracks().forEach((t) => stopTrack(t)));\n    const generation = this.beginMediaDeviceChange(kind);\n    let newStream: MediaStream;\n    try {\n      newStream = await getStream(opts.constraints);\n    } catch(err) {\n      if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n      this.log?.[opts.acquisitionFailureLogLevel ?? 'error']?.(`${label} getUserMedia failed`, err);\n      throw err;\n    }\n\n    {\n      const abandon = opts.shouldAbandon('acquired', generation);\n      if(abandon !== undefined) {\n        release(newStream);\n        return abandon;\n      }\n    }\n\n    return this.serializeMediaDeviceChange(kind, async() => {\n      const abandon = opts.shouldAbandon('queued', generation);\n      if(abandon !== undefined) {\n        release(newStream);\n        return abandon;\n      }\n\n      const newTrack = newStream.getTracks().find((track) => track.kind === kind);\n      const resolved = newTrack && opts.resolveSwap(newTrack);\n      if(!resolved) {\n        release(newStream);\n        throw new Error(`Could not replace input ${kind} track`);\n      }\n      const {oldTrack, swap, rollback} = resolved;\n\n      const pendingAudioTrack = kind === 'audio' ? newTrack : undefined;\n      if(pendingAudioTrack) {\n        // getUserMedia returns enabled tracks. Preserve the logical microphone\n        // state before exposing the replacement to a sender. Keep tracking it\n        // until commit/rollback as setMuted can run while replaceTrack waits.\n        pendingAudioTrack.enabled = opts.getPendingAudioEnabled(oldTrack);\n        this.pendingInputAudioTracks.add(pendingAudioTrack);\n      }\n\n      try {\n        try {\n          await swap();\n        } catch(err) {\n          if(opts.rollbackOnSwapFailure && !this.isClosing) {\n            try {\n              await rollback();\n            } catch(rollbackErr) {\n              this.log?.error?.(`${label} rollback failed`, rollbackErr);\n            }\n          }\n          release(newStream);\n          const abandonFailed = opts.shouldAbandon('failed', generation);\n          if(abandonFailed !== undefined) return abandonFailed;\n          throw err;\n        }\n\n        // The swap may finish after hangup or after a newer A→B selection\n        // started. Do not publish that orphan stream after cleanup. A stale but\n        // live call (`false`) is restored to its last committed track before B\n        // proceeds.\n        const abandonSwapped = opts.shouldAbandon('swapped', generation);\n        if(abandonSwapped !== undefined) {\n          if(abandonSwapped === false) {\n            try {\n              await rollback();\n            } catch(rollbackErr) {\n              this.log?.error?.(`${label} stale rollback failed`, rollbackErr);\n            }\n          }\n          release(newStream);\n          return abandonSwapped;\n        }\n\n        opts.commit(newStream, newTrack, oldTrack);\n        return true;\n      } finally {\n        if(pendingAudioTrack) this.pendingInputAudioTracks.delete(pendingAudioTrack);\n      }\n    });\n  }\n\n  private async replaceInputDevice(opts: {\n    kind: 'audio' | 'video',\n    constraints: MediaStreamConstraints,\n    getOldTrack: () => MediaStreamTrack | undefined,\n    commit: (newStream: MediaStream, newTrack: MediaStreamTrack, oldTrack: MediaStreamTrack) => void\n  }): Promise<boolean> {\n    const {kind} = opts;\n    return this.runInputDeviceSwap({\n      kind,\n      constraints: opts.constraints,\n      shouldAbandon: (site, generation) => {\n        if(site === 'acquired') {\n          return this.isClosing ? true : undefined;\n        }\n        if(site === 'swapped') {\n          // Closing wins over staleness here: a closed call must not roll the\n          // sender back (there is nothing to restore into).\n          if(this.isClosing) return true;\n          if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n          return undefined;\n        }\n        if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n        if(this.isClosing) return true;\n        return undefined;\n      },\n      resolveSwap: (newTrack) => {\n        const oldTrack = opts.getOldTrack();\n        if(!oldTrack) return undefined;\n        return {\n          oldTrack,\n          swap: () => this.replaceSenderTrack?.(kind, oldTrack, newTrack) ?? Promise.resolve(),\n          rollback: () => this.replaceSenderTrack?.(kind, newTrack, oldTrack) ?? Promise.resolve()\n        };\n      },\n      // The group override walks multiple senders and can fail half-swapped.\n      rollbackOnSwapFailure: true,\n      getPendingAudioEnabled: (oldTrack) => oldTrack.enabled,\n      commit: opts.commit\n    });\n  }\n\n  // Mid-call mic swap: acquire the new device, hand the resulting track\n  // over to the streamManager, and hot-swap every sender still bound to the\n  // old track. Sender commit is serialized by replaceInputDevice.\n  public setInputAudioDeviceId(deviceId: string): Promise<boolean> {\n    if(!this.isSharingAudio) return Promise.resolve(true);\n    return this.replaceInputDevice({\n      kind: 'audio',\n      constraints: {audio: getAudioConstraints(deviceId)},\n      getOldTrack: () => this.streamManager.inputStream.getAudioTracks()[0],\n      commit: (newStream, _newTrack, oldTrack) => {\n        this.streamManager.replaceInputAudio(newStream, oldTrack);\n        stopTrack(oldTrack);\n      }\n    });\n  }\n\n  // Find every locally-owned <video> whose `srcObject` is the *source*\n  // stream that originally carried `oldTrack` and: (1) splice the new track\n  // in / remove the old one so the MediaStream still represents reality,\n  // (2) re-assign `srcObject` so Chromium re-evaluates the track list —\n  // Chrome silently keeps showing the old (frozen) frame if you only\n  // `addTrack` to an already-attached MediaStream.\n  //\n  // Walks `document.querySelectorAll('video')` (not just `this.elements`)\n  // because group-call participant tiles are *clones* of the main element\n  // created in `groupCallInstance.getVideoElementFromParticipantByType` —\n  // those clones live outside the elements map but share the same\n  // MediaStream reference, so we need to find them all and refresh each.\n  //\n  // Two-pass: identify matching streams first, THEN mutate. A single pass\n  // would race — the first iteration removes oldTrack from the shared\n  // stream, then the `includes(oldTrack)` check fails for every subsequent\n  // clone that points at the same stream, and only one element refreshes.\n  private swapLocalVideoTrack(oldTrack: MediaStreamTrack, newTrack: MediaStreamTrack): void {\n    const allVideos = Array.from(document.querySelectorAll('video'));\n    const targetStreams = new Set<MediaStream>();\n    const targetVideos: HTMLVideoElement[] = [];\n    for(const video of allVideos) {\n      const stream = video.srcObject;\n      if(!(stream instanceof MediaStream)) continue;\n      if(!(stream.getVideoTracks() as MediaStreamTrack[]).includes(oldTrack)) continue;\n      targetStreams.add(stream);\n      targetVideos.push(video);\n    }\n    for(const stream of targetStreams) {\n      stream.removeTrack(oldTrack);\n      stream.addTrack(newTrack);\n    }\n    for(const video of targetVideos) {\n      // Re-assigning `srcObject` (even to the same stream) forces Chrome to\n      // pick up the new track. Setting to null first guarantees a clean\n      // repaint cycle even when the browser is mid-frame.\n      const stream = video.srcObject;\n      video.srcObject = null;\n      video.srcObject = stream;\n    }\n  }\n\n  // Mid-call camera swap. Mirrors setInputAudioDeviceId, sans the\n  // streamManager.replaceInputAudio (which is audio-only) — for video we\n  // mutate the inputStream directly.\n  public setInputVideoDeviceId(deviceId: string): Promise<boolean> {\n    if(!this.isSharingVideo) return Promise.resolve(true);\n    return this.replaceInputDevice({\n      kind: 'video',\n      constraints: {video: getVideoConstraints(deviceId)},\n      getOldTrack: () => this.streamManager.inputStream.getVideoTracks()[0],\n      commit: (newStream, newTrack, oldTrack) => {\n        // Keep items, inputStream, and every cloned local preview in sync.\n        this.streamManager.removeTrack(oldTrack);\n        this.streamManager.addTrack(newStream, newTrack, 'input');\n        this.swapLocalVideoTrack(oldTrack, newTrack);\n        stopTrack(oldTrack);\n      }\n    });\n  }\n\n  // Subclasses (PopupGroupCall via GroupCallInstance / PopupCall via\n  // CallInstance) override to walk their own RTCPeerConnection senders.\n  // Optional — base class is happy with just the streamManager swap.\n  protected replaceSenderTrack?(\n    kind: 'audio' | 'video',\n    oldTrack: MediaStreamTrack,\n    newTrack: MediaStreamTrack\n  ): MaybePromise<void>;\n\n  protected async onInputStream(stream: MediaStream): Promise<void> {\n    if(!this.isClosing) {\n      const videoTracks = stream.getVideoTracks();\n      if(videoTracks.length) {\n        this.saveInputVideoStream(stream, 'main');\n      }\n\n      const {streamManager, description} = this;\n      streamManager.addStream(stream, 'input');\n\n      try {\n        if(description) {\n          await streamManager.appendToConference(description, undefined, true);\n        }\n      } catch(err) {\n        stream.getTracks().forEach((track) => {\n          streamManager.removeTrack(track);\n          stopTrack(track);\n        });\n        throw err;\n      }\n\n      // cleanup() may have run while sender.replaceTrack was pending. Its\n      // first stop pass cannot cover a stream registered after that pass, so\n      // release explicitly before this async continuation returns.\n      if(this.isClosing) {\n        stream.getTracks().forEach((track) => stopTrack(track));\n      }\n    } else { // if call is declined earlier than stream appears\n      stream.getTracks().forEach((track) => {\n        stopTrack(track);\n      });\n    }\n  }\n}\n","import {Logger, logger} from '@lib/logger';\n\nexport default function createDataChannel(connection: RTCPeerConnection, dict?: RTCDataChannelInit, log?: Logger) {\n  // return;\n\n  if(!log) {\n    log = logger('RTCDataChannel');\n  }\n\n  const channel = connection.createDataChannel('data', dict);\n\n  channel.addEventListener('message', (e) => {\n    log('onmessage', e);\n  });\n  channel.addEventListener('open', () => {\n    log('onopen');\n  });\n  channel.addEventListener('close', () => {\n    log('onclose');\n  });\n\n  channel.log = log;\n\n  return channel;\n}\n","import {Logger, logger} from '@lib/logger';\n\nexport default function createPeerConnection(config: RTCConfiguration, log?: Logger) {\n  if(!log) {\n    log = logger('RTCPeerConnection');\n  }\n\n  log('constructor');\n\n  // @ts-ignore\n  const connection = new RTCPeerConnection(config);\n  connection.addEventListener('track', (event) => {\n    log('ontrack', event);\n  });\n  connection.addEventListener('signalingstatechange', () => {\n    log('onsignalingstatechange', connection.signalingState);\n  });\n  connection.addEventListener('connectionstatechange', () => {\n    // Also surface the DTLS transport state + ICE state: the common \"ICE connected\n    // but connectionState stuck at connecting\" failure is a stalled DTLS handshake,\n    // and this is the single signal that pins it in an exported log.\n    const dtlsTransport = connection.sctp?.transport ||\n      connection.getSenders().find((s) => s.transport)?.transport ||\n      connection.getReceivers().find((r) => r.transport)?.transport;\n    log('onconnectionstatechange', connection.connectionState, 'dtls:', dtlsTransport?.state, 'ice:', connection.iceConnectionState);\n  });\n  connection.addEventListener('negotiationneeded', () => { // * will be fired every time input device changes\n    log('onnegotiationneeded', connection.signalingState);\n  });\n  connection.addEventListener('icecandidate', (event) => {\n    log('onicecandidate', event);\n  });\n  connection.addEventListener('iceconnectionstatechange', () => {\n    log('oniceconnectionstatechange', connection.iceConnectionState);\n  });\n  connection.addEventListener('icegatheringstatechange', () => {\n    log('onicegatheringstatechange', connection.iceGatheringState);\n  });\n  connection.addEventListener('datachannel', () => {\n    log('ondatachannel');\n  });\n\n  connection.log = log;\n\n  return {connection};\n}\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {GroupCallParticipantVideoSourceGroup} from '@layer';\nimport {fixMediaLineType, SDPBuilder, WebRTCLineType, WEBRTC_MEDIA_PORT} from '@lib/calls/sdpBuilder';\nimport {AudioCodec, GroupCallConnectionTransport, Ssrc, UpdateGroupCallConnectionData, VideoCodec} from '@lib/calls/types';\n\ntype ResolvedSource = {\n  source: number,\n  sourceGroups?: GroupCallParticipantVideoSourceGroup[]\n};\n\nfunction resolveSource(source: number | GroupCallParticipantVideoSourceGroup[]): ResolvedSource | undefined {\n  if(Array.isArray(source)) {\n    const first = source[0]?.sources?.[0];\n    if(typeof first !== 'number') return;\n    return {source: first, sourceGroups: source};\n  }\n\n  if(typeof source !== 'number') return;\n  return {source};\n}\n\nexport class ConferenceEntry {\n  public source: number;\n  public sourceGroups: GroupCallParticipantVideoSourceGroup[];\n  public transceiver: RTCRtpTransceiver;\n  public originalDirection: RTCRtpTransceiverDirection;\n  public direction: RTCRtpTransceiverDirection;\n  public port: string;\n  public endpoint: string;\n  public peerId: PeerId;\n\n  public sendEntry: ConferenceEntry;\n  public recvEntry: ConferenceEntry;\n\n  constructor(public mid: string, public type: WebRTCLineType) {\n    this.port = WEBRTC_MEDIA_PORT;\n  }\n\n  public setDirection(direction: RTCRtpTransceiverDirection) {\n    if(!this.originalDirection) {\n      this.originalDirection = direction;\n    }\n\n    return this.direction = direction;\n  }\n\n  public setPort(port: string) {\n    return this.port = port;\n  }\n\n  public setEndpoint(endpoint: string) {\n    return this.endpoint = endpoint;\n  }\n\n  public setPeerId(peerId: PeerId) {\n    return this.peerId = peerId;\n  }\n\n  public createTransceiver(connection: RTCPeerConnection, init?: RTCRtpTransceiverInit) {\n    if(init?.direction) {\n      this.setDirection(init.direction);\n    }\n\n    return this.transceiver = connection.addTransceiver(fixMediaLineType(this.type), init);\n  }\n\n  public setSource(source: number | GroupCallParticipantVideoSourceGroup[]) {\n    const resolved = resolveSource(source);\n    if(!resolved) return;\n\n    this.sourceGroups = resolved.sourceGroups;\n    return this.source = resolved.source;\n  }\n\n  public shouldBeSkipped(isAnswer?: boolean) {\n    return isAnswer && this.direction === 'inactive';\n  }\n}\n\nexport function generateSsrc(type: WebRTCLineType, source: number | GroupCallParticipantVideoSourceGroup[], endpoint?: string): Ssrc {\n  const resolved = resolveSource(source);\n  if(!resolved) return;\n\n  return {\n    endpoint,\n    type,\n    source: resolved.source,\n    sourceGroups: resolved.sourceGroups\n  };\n}\n\nexport default class LocalConferenceDescription implements UpdateGroupCallConnectionData {\n  public readonly sessionId: string;\n  // public ssrcs: Ssrc[];\n  public readonly transport: GroupCallConnectionTransport;\n  public readonly audio?: AudioCodec;\n  public readonly video: VideoCodec;\n  public readonly screencast?: VideoCodec;\n\n  private maxSeenId: number;\n  public readonly entries: ConferenceEntry[];\n  private entriesByMid: Map<ConferenceEntry['mid'], ConferenceEntry>;\n  private entriesBySource: Map<ConferenceEntry['source'], ConferenceEntry>;\n  private entriesByPeerId: Map<ConferenceEntry['peerId'], Set<ConferenceEntry>>;\n\n  constructor(public connection: RTCPeerConnection) {\n    this.sessionId = '' + Date.now();\n    // this.ssrcs = [];\n    this.maxSeenId = -1;\n    this.entries = [];\n    this.entriesByMid = new Map();\n    this.entriesBySource = new Map();\n    this.entriesByPeerId = new Map();\n  }\n\n  public setData(data: UpdateGroupCallConnectionData) {\n    return safeAssign(this, data);\n  }\n\n  public createEntry(type: WebRTCLineType) {\n    const mid = '' + ++this.maxSeenId;\n    const entry = new ConferenceEntry(mid, type);\n    this.entries.push(entry);\n    this.entriesByMid.set(mid, entry);\n    return entry;\n  }\n\n  public deleteEntry(entry: ConferenceEntry) {\n    indexOfAndSplice(this.entries, entry);\n    this.entriesByMid.delete(entry.mid);\n    if(this.entriesBySource.get(entry.source) === entry) {\n      this.entriesBySource.delete(entry.source);\n    }\n\n    const set = this.entriesByPeerId.get(entry.peerId);\n    if(set) {\n      set.delete(entry);\n      if(!set.size) {\n        this.entriesByPeerId.delete(entry.peerId);\n      }\n    }\n  }\n\n  public setEntrySource(entry: ConferenceEntry, source: Parameters<ConferenceEntry['setSource']>[0]) {\n    const previousSource = entry.source;\n    const resolvedSource = entry.setSource(source);\n    if(resolvedSource === undefined) return;\n\n    if(previousSource !== undefined && previousSource !== resolvedSource) {\n      if(this.entriesBySource.get(previousSource) === entry) {\n        this.entriesBySource.delete(previousSource);\n      }\n    }\n    this.entriesBySource.set(resolvedSource, entry);\n    return resolvedSource;\n  }\n\n  public setEntryPeerId(entry: ConferenceEntry, peerId: ConferenceEntry['peerId']) {\n    // Drop the old binding first. This used to be called only on freshly\n    // created entries (peerId undefined), so \"an entry appears under exactly\n    // one peerId\" held by construction; re-binding a live entry (an SSRC the\n    // server moved between participants) would otherwise leave it indexed under\n    // both, and getEntriesByPeerId would report the previous owner as still\n    // owning a stream that is no longer theirs.\n    if(entry.peerId !== undefined && entry.peerId !== peerId) {\n      const previous = this.entriesByPeerId.get(entry.peerId);\n      if(previous) {\n        previous.delete(entry);\n        if(!previous.size) {\n          this.entriesByPeerId.delete(entry.peerId);\n        }\n      }\n    }\n\n    entry.setPeerId(peerId);\n    let set = this.entriesByPeerId.get(peerId);\n    if(!set) {\n      this.entriesByPeerId.set(peerId, set = new Set());\n    }\n\n    set.add(entry);\n  }\n\n  public findEntry(verify: Parameters<LocalConferenceDescription['entries']['find']>[0]) {\n    return this.entries.find(verify);\n  }\n\n  public findFreeSendRecvEntry(type: WebRTCLineType, isSending: boolean) {\n    let entry = this.entries.find((entry) => {\n      return entry.direction === 'sendrecv' && entry.type === type && !(isSending ? entry.sendEntry : entry.recvEntry);\n    });\n\n    if(!entry) {\n      entry = this.createEntry(type);\n      entry.setDirection('sendrecv');\n    }\n\n    return entry;\n  }\n\n  public getEntryByMid(mid: ConferenceEntry['mid']) {\n    return this.entriesByMid.get(mid);\n  }\n\n  public getEntryBySource(source: ConferenceEntry['source']) {\n    return this.entriesBySource.get(source);\n  }\n\n  public getEntriesByPeerId(peerId: ConferenceEntry['peerId']) {\n    return this.entriesByPeerId.get(peerId);\n  }\n\n  public generateSdp(options: Omit<Parameters<SDPBuilder['addConference']>[0], 'conference'>) {\n    return SDPBuilder.fromConference({\n      conference: this,\n      ...options\n    });\n  }\n}\n","import safeAssign from '@helpers/object/safeAssign';\nimport {logger} from '@lib/logger';\nimport createDataChannel from '@lib/calls/helpers/createDataChannel';\nimport createPeerConnection from '@lib/calls/helpers/createPeerConnection';\nimport LocalConferenceDescription from '@lib/calls/localConferenceDescription';\nimport StreamManager from '@lib/calls/streamManager';\nimport {Ssrc} from '@lib/calls/types';\n\nexport type CallConnectionInstanceOptions = {\n  streamManager: StreamManager,\n  connection?: RTCPeerConnection,\n  log?: ReturnType<typeof logger>\n};\n\nexport default abstract class CallConnectionInstanceBase {\n  public connection: RTCPeerConnection;\n  public streamManager: StreamManager;\n  public dataChannel: RTCDataChannel;\n  public description: LocalConferenceDescription;\n  public sources: {\n    audio: Ssrc,\n    video?: Ssrc,\n  };\n  protected negotiating: Promise<void>;\n  protected log: ReturnType<typeof logger>;\n\n  constructor(options: CallConnectionInstanceOptions) {\n    safeAssign(this, options);\n\n    if(!this.log) {\n      this.log = this.connection?.log || logger('CALL-CONNECTION-BASE');\n    }\n\n    this.sources = {} as any;\n  }\n\n  public createPeerConnection(config?: RTCConfiguration) {\n    return this.connection || (this.connection = createPeerConnection(config, this.log.bindPrefix('connection')).connection);\n  }\n\n  public createDataChannel(dict?: RTCDataChannelInit) {\n    return this.dataChannel || (this.dataChannel = createDataChannel(this.connection, dict, this.log.bindPrefix('data')));\n  }\n\n  public createDescription() {\n    return this.description || (this.description = new LocalConferenceDescription(this.connection));\n  }\n\n  public appendStreamToConference(\n    onSenderCreated?: (sender: RTCRtpSender) => void,\n    throwOnReplaceError = false\n  ) {\n    return this.streamManager.appendToConference(this.description, onSenderCreated, throwOnReplaceError);\n  }\n\n  public closeConnection() {\n    const {connection} = this;\n    if(!connection) {\n      return;\n    }\n\n    try {\n      connection.log('close');\n      connection.close();\n    } catch(e) {\n      this.log.error(e);\n    }\n  }\n\n  public closeConnectionAndStream(stopStream: boolean) {\n    this.closeConnection();\n    stopStream && this.streamManager.stop();\n  }\n\n  protected abstract negotiateInternal(): CallConnectionInstanceBase['negotiating'];\n\n  public negotiate() {\n    const promise = this.negotiating;\n    if(promise) {\n      return promise;\n    }\n\n    return this.negotiating = this.negotiateInternal().finally(() => {\n      this.negotiating = undefined;\n    });\n  }\n\n  public sendDataChannelData(data: any) {\n    if(this.dataChannel.readyState !== 'open') {\n      return;\n    }\n\n    this.dataChannel.send(JSON.stringify(data));\n  }\n}\n","import forEachReverse from '@helpers/array/forEachReverse';\nimport SDPMediaSection from '@lib/calls/sdp/mediaSection';\nimport {UpdateGroupCallConnectionData, Codec} from '@lib/calls/types';\nimport {logger} from '@lib/logger';\n\nconst log = logger('SDP');\n\nexport default function filterServerCodecs(mainChannels: SDPMediaSection[], data: UpdateGroupCallConnectionData) {\n  // ! Need to filter server's extmap for Firefox\n  const performExtmap = (channel: typeof mainChannels[0]) => {\n    const out: {[id: string]: string} = {};\n    const extmap = channel.attributes.get('extmap');\n    extmap.forEach((extmap) => {\n      const id = extmap.key.split('/', 1)[0];\n      out[id] = extmap.value;\n    });\n\n    return out;\n  };\n\n  const codecsToPerform: [Codec, 'audio' | 'video'][] = /* flatten([data, dataPresentation].filter(Boolean).map((data) => {\n    return  */['audio' as const, 'video' as const].filter((type) => data[type]).map((type) => ([data[type], type]));\n  // }));\n\n  codecsToPerform.forEach(([codec, type]) => {\n    const channel = mainChannels.find((line) => line.mediaType === type);\n    if(!channel) {\n      return;\n    }\n\n    const extmap = performExtmap(channel);\n    forEachReverse(codec['rtp-hdrexts'], (value, index, arr) => {\n      if(extmap[value.id] !== value.uri) {\n        arr.splice(index, 1);\n        log('filtered extmap', value, index, type);\n      }\n    });\n  });\n}\n","import {GroupCallParticipantVideoSourceGroup} from '@layer';\nimport {toTelegramSource} from '@lib/calls/utils';\n\nexport function parseSourceGroups(sdpLines: string[]) {\n  const telegramSourceGroups = sdpLines.map((str) => {\n    const [semantics, ...rest] = str.split(' ');\n\n    const sourceGroup: GroupCallParticipantVideoSourceGroup = {\n      _: 'groupCallParticipantVideoSourceGroup',\n      semantics,\n      // sources: rest.map((ssrc) => +ssrc)\n      sources: rest.map((ssrc) => toTelegramSource(+ssrc))\n    };\n\n    return sourceGroup;\n  });\n\n  /* const simIndex = telegramSourceGroups.findIndex((g) => g.semantics === 'SIM');\n  if(simIndex !== -1) {\n    const sourceGroup = telegramSourceGroups.splice(simIndex, 1)[0];\n    telegramSourceGroups.unshift(sourceGroup);\n  } */\n\n  return telegramSourceGroups.length ? telegramSourceGroups : undefined;\n}\n","import SDP from '@lib/calls/sdp';\nimport SDPMediaSection from '@lib/calls/sdp/mediaSection';\nimport {toTelegramSource} from '@lib/calls/utils';\nimport {parseSourceGroups} from '@lib/calls/helpers/parseSourceGroups';\n\nexport default function parseMediaSectionInfo(sdp: SDP, channel: SDPMediaSection) {\n  const clientInfo = channel.lookupAttributeKeys({\n    'ice-ufrag': true,\n    'ice-pwd': true,\n    'fingerprint': true,\n    'setup': true,\n    'ssrc': true,\n    'mid': true,\n    'ssrc-group': false\n  });\n\n  if(!clientInfo.fingerprint) { // support Firefox\n    const line = sdp.session.lines.find((line) => line.parsed?.key === 'fingerprint');\n    clientInfo.fingerprint = line.parsed.value;\n  }\n\n  const telegramSourceGroups = parseSourceGroups(clientInfo['ssrc-group']);\n  const [hash, fingerprint] = clientInfo.fingerprint.split(' ', 2);\n  const ssrc = clientInfo.ssrc && toTelegramSource(+clientInfo.ssrc.split(' ', 1)[0]);\n  // ssrc = telegramSourceGroups ? telegramSourceGroups[0].sources[0] : ssrc;\n\n  return {\n    raw: clientInfo,\n    ufrag: clientInfo['ice-ufrag'],\n    pwd: clientInfo['ice-pwd'],\n    fingerprint: {\n      fingerprint,\n      setup: clientInfo.setup,\n      hash\n    },\n    source: ssrc,\n    sourceGroups: telegramSourceGroups,\n    mid: clientInfo.mid\n  };\n}\n","import forEachReverse from '@helpers/array/forEachReverse';\nimport copy from '@helpers/object/copy';\nimport {ConferenceEntry} from '@lib/calls/localConferenceDescription';\nimport {parseSdp, addSimulcast} from '@lib/calls/sdp/utils';\nimport {generateMediaFirstLine, SDPBuilder} from '@lib/calls/sdpBuilder';\nimport {UpdateGroupCallConnectionData} from '@lib/calls/types';\nimport parseMediaSectionInfo from '@lib/calls/helpers/parseMediaSectionInfo';\n\nexport default function fixLocalOffer(options: {\n  offer: RTCSessionDescriptionInit,\n  data: UpdateGroupCallConnectionData,\n  skipAddingMulticast?: boolean\n  // mids?: string[]\n}) {\n  const {offer, data} = options;\n  const sdp = parseSdp(offer.sdp);\n  let hasMunged = false;\n\n  if(!options.skipAddingMulticast) {\n    hasMunged = addSimulcast(sdp) || hasMunged;\n  }\n\n  // const bundleLine = parsedSdp.session.lines.find((line) => line.Ha?.key === 'group');\n  // const bundleMids = bundleLine.value.split(' ').slice(1);\n\n  forEachReverse(sdp.media, (section, idx, arr) => {\n    // const mid = section.oa.get('mid').oa;\n\n    // это может случиться при выключении и включении видео. почему-то появится секция уже удалённая\n    // ! нельзя тут модифицировать локальное описание, будет критовать\n    /* if(mids && !mids.includes(mid) && !bundleMids.includes(mid)) {\n      console.error('wtf');\n      hasMunged = true;\n      arr.splice(idx, 1);\n      return;\n    } */\n\n    if(/* section.mediaType !== 'video' ||  */section.isSending) {\n      return;\n    }\n\n    if(section.mediaType === 'application') {\n      return;\n    }\n\n    const mediaLine = section.mediaLine;\n    const mediaLineParts = mediaLine.mediaLineParts;\n    const mediaCodecIds = mediaLineParts.ids;\n    const localMLine = mediaLine.toString();\n\n    const codec = data[section.mediaType];\n    // Pre-added recvonly transceivers (used by the conference path to\n    // receive-side pre-attach RTCRtpScriptTransform before the decoder\n    // exists) leave us with extra audio/video m-lines that the server's\n    // join response has no codec mapping for. Skip munging — Chrome's own\n    // SDP is fine; we only need to munge the sending-side mids whose\n    // codecs we're aligning with the server's list.\n    if(!codec) {\n      return;\n    }\n    const payloadTypes = codec['payload-types'];\n\n    /* forEachReverse(payloadTypes, (payloadType, idx, arr) => {\n      if(!mediaCodecIds.includes('' + payloadType.id) && section.mediaType === 'video') {\n      // if(payloadType.name === 'H265') {\n        console.warn('[sdp] filtered unsupported codec', payloadType, mediaCodecIds, section.mediaType);\n        arr.splice(idx, 1);\n      }\n    }); */\n\n    const codecIds = payloadTypes.map((payload) => '' + payload.id);\n    const correctMLine = generateMediaFirstLine(section.mediaType, undefined, codecIds);\n\n    if(localMLine !== correctMLine) {\n      const sectionInfo = parseMediaSectionInfo(sdp, section);\n\n      const newData = {...data};\n      newData.transport = copy(newData.transport);\n      newData.transport.ufrag = sectionInfo.ufrag;\n      newData.transport.pwd = sectionInfo.pwd;\n      newData.transport.fingerprints = [sectionInfo.fingerprint];\n      newData.transport.candidates = [];\n\n      const entry = new ConferenceEntry(sectionInfo.mid, mediaLineParts.type);\n      entry.setPort(mediaLineParts.port);\n      sectionInfo.source && entry.setSource(sectionInfo.sourceGroups || sectionInfo.source);\n      entry.setDirection(section.direction);\n\n      const newSdp = new SDPBuilder().addSsrcEntry(entry, newData).finalize();\n\n      const newChannel = parseSdp(newSdp).media[0];\n      arr[idx] = newChannel;\n\n      hasMunged = true;\n    }\n  });\n\n  if(hasMunged) {\n    const mungedSdp = sdp.toString();\n    offer.sdp = mungedSdp;\n  }\n\n  return {offer, sdp/* , bundleMids */};\n}\n","import {DataJSON} from '@layer';\nimport {JoinGroupCallJsonPayload} from '@appManagers/appGroupCallsManager';\nimport SDP from '@lib/calls/sdp';\nimport {Ssrc} from '@lib/calls/types';\nimport parseMediaSectionInfo from '@lib/calls/helpers/parseMediaSectionInfo';\n\nexport default function processMediaSection(sdp: SDP, media: SDP['media'][0]) {\n  const sectionInfo = parseMediaSectionInfo(sdp, media);\n\n  const mediaType: Exclude<typeof media['mediaType'], 'application'> = media.mediaType as any;\n  const entry: Ssrc = {\n    source: sectionInfo.source,\n    sourceGroups: sectionInfo.sourceGroups,\n    type: mediaType\n  };\n\n  // DTLS role advertised to the SFU in the phone.joinGroupCall params: we are\n  // `passive` (the DTLS *server*), so the Telegram SFU is the DTLS *client*\n  // (active) and sends the ClientHello. The server echoes this by answering\n  // with setup:active, which makes Chrome (offering actpass) take the passive\n  // role. This matches tdesktop/libtgcalls and Telegram Web A, and holds for\n  // BOTH legacy voice chats and e2e conferences.\n  //\n  // This used to be `active` for legacy calls (client drives DTLS). That\n  // worked on older Chrome, but a Chrome DTLS-stack change (~M124) broke the\n  // \"Chrome is the DTLS client against this SFU\" direction: ICE still reaches\n  // `connected` and a candidate pair is nominated, but the DTLS handshake then\n  // hangs at `connecting` forever — no SRTP keys are derived, so not a single\n  // RTP packet flows and audio + video are both silently dead. Letting the SFU\n  // drive the handshake (it is `active`) makes DTLS complete again. Verified\n  // live: dtlsState connecting→connected, inbound-rtp packets start arriving.\n  sectionInfo.fingerprint.setup = 'passive';\n  const payload: JoinGroupCallJsonPayload = {\n    'fingerprints': [sectionInfo.fingerprint],\n    'pwd': sectionInfo.pwd,\n    'ssrc': sectionInfo.source,\n    'ssrc-groups': sectionInfo.sourceGroups || [],\n    'ufrag': sectionInfo.ufrag\n  };\n  const paramsDataJson = JSON.stringify(payload);\n\n  const params: DataJSON = {\n    _: 'dataJSON',\n    data: paramsDataJson\n  };\n\n  return {\n    params,\n    source: sectionInfo.source,\n    media,\n    sourceGroups: sectionInfo.sourceGroups,\n    entry\n  };\n}\n","// Infer the media kind of a freshly-created RTCRtpSender from its transceiver's\n// receiver track. Used by the onSenderCreated hooks that attach e2e script\n// transforms in the createTransceiver→replaceTrack gap: there `sender.track`\n// isn't bound yet, but a sendonly transceiver's receiver still exposes a track\n// of the correct kind. Replaces a duplicated inline inference in\n// groupCallsController + groupCallConnectionInstance; the previous `_kindHint`\n// fallback was dead code (that property is never assigned anywhere).\nexport default function senderKind(connection: RTCPeerConnection, sender: RTCRtpSender): 'audio' | 'video' {\n  const transceiver = connection.getTransceivers().find((t) => t.sender === sender);\n  return transceiver?.receiver?.track?.kind === 'video' ? 'video' : 'audio';\n}\n","import forEachReverse from '@helpers/array/forEachReverse';\nimport {GroupCallConnectionType, JoinGroupCallJsonPayload} from '@appManagers/appGroupCallsManager';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport CallConnectionInstanceBase, {CallConnectionInstanceOptions} from '@lib/calls/callConnectionInstanceBase';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport filterServerCodecs from '@lib/calls/helpers/filterServerCodecs';\nimport fixLocalOffer from '@lib/calls/helpers/fixLocalOffer';\nimport processMediaSection from '@lib/calls/helpers/processMediaSection';\nimport {getUnsafeConnectionDataReason} from '@lib/calls/helpers/sdpSafety';\nimport sameInputGroupCall from '@lib/calls/helpers/sameInputGroupCall';\nimport senderKind from '@lib/calls/helpers/senderKind';\nimport {E2E_MAIN_CHANNEL_ID, E2E_SCREENCAST_CHANNEL_ID} from '@lib/calls/constants';\nimport {ConferenceEntry} from '@lib/calls/localConferenceDescription';\nimport SDP from '@lib/calls/sdp';\nimport SDPMediaSection from '@lib/calls/sdp/mediaSection';\nimport {WebRTCLineType} from '@lib/calls/sdpBuilder';\nimport {UpdateGroupCallConnectionData} from '@lib/calls/types';\nimport {InputGroupCall} from '@layer';\n\n// The server decides how many video participants it announces, so what we ask\n// it to forward must not scale with that: the pinned tile at full quality, grid\n// tiles at medium, and no more than this many on stage at once (tgcalls\n// requests only the visible tiles, by tier).\nconst MAX_ON_STAGE_VIDEO_ENDPOINTS = 16;\n\nexport default class GroupCallConnectionInstance extends CallConnectionInstanceBase {\n  private groupCall: GroupCallInstance;\n  public updateConstraints?: boolean;\n  private type: GroupCallConnectionType;\n  public options: {\n    type: Extract<GroupCallConnectionType, 'main'>,\n    isMuted?: boolean,\n    joinVideo?: boolean,\n    rejoin?: boolean,\n    // Conference (TdE2E) join: when set, passed to phone.joinGroupCall as\n    // the `public_key` + `block` fields. Server treats the join as a\n    // conference iff BOTH are present.\n    e2ePublicKey?: Uint8Array,\n    e2eBlock?: Uint8Array,\n    // Fresh conference starts submit the same key/block/SDP atomically through\n    // phone.createConferenceCall instead of creating an empty call first.\n    e2eCreateConference?: boolean,\n    // Override the default `inputGroupCall(id, access_hash)` derived from the\n    // GroupCallInstance id. Needed for invite-link / invite-message joins\n    // where the joinee doesn't yet have a personal access_hash — they pass\n    // `inputGroupCallSlug` or `inputGroupCallInviteMessage` and the server\n    // echoes back the real id+access_hash in the join response.\n    e2eCallInput?: InputGroupCall,\n    // Canonical identity obtained while previewing a slug/invite-message. The\n    // original e2eCallInput remains the authorization used by fetch/join; this\n    // value is only the identity the response is allowed to promote to.\n    e2eExpectedCallInput?: InputGroupCall.inputGroupCall,\n    // Called when `phone.joinGroupCall` fails with CONF_WRITE_CHAIN_INVALID\n    // (the chain advanced between our fetch + submit). Should re-fetch the\n    // chain head and return a freshly-built self-add block. WebRTC state\n    // (peer connection, SDP, mic) is preserved across the retry — only the\n    // e2e block and the resulting `phone.joinGroupCall` request change.\n    // Matches tdlib GroupCallManager.cpp:4565-4568 try_join_group_call.\n    e2eRebuildBlock?: () => Promise<Uint8Array>,\n    // Completes the worker-local half of a rebuilt join only after the server\n    // accepted the exact block returned by e2eRebuildBlock. Kept separate from\n    // rebuilding so a rejected proposal can never become the worker's anchor.\n    e2eCommitRebuiltBlock?: () => Promise<void>,\n    // Opens polling, roster reconciliation and verification broadcasts only\n    // after join success, optional reanchor and invite-id promotion.\n    e2eActivate?: () => Promise<void>,\n  } | {\n    type: Extract<GroupCallConnectionType, 'presentation'>,\n  };\n\n  private updateConstraintsInterval: number;\n  private negotiationRequested = false;\n  private negotiationQueue: Promise<void>;\n\n  private managers: AppManagers;\n  /** True once phone.joinGroupCall has accepted this media source server-side. */\n  public joinAccepted = false;\n  /** Exact call reference accepted by phone.joinGroupCall, retained for rollback. */\n  public acceptedCallInput?: InputGroupCall;\n\n  constructor(options: CallConnectionInstanceOptions & {\n    groupCall: GroupCallConnectionInstance['groupCall'],\n    type: GroupCallConnectionInstance['type'],\n    options: GroupCallConnectionInstance['options'],\n    managers: AppManagers\n  }) {\n    super(options);\n  }\n\n  /**\n   * Coalesce negotiationneeded bursts without dropping the Promise or a dirty\n   * event that arrives while an offer is in flight. A rejected attempt leaves\n   * the dirty flag set so the next roster/event can retry or recovery can take\n   * over explicitly.\n   */\n  public requestNegotiation(): Promise<void> {\n    this.negotiationRequested = true;\n    if(this.negotiationQueue) return this.negotiationQueue;\n\n    const queue = Promise.resolve().then(async() => {\n      try {\n        while(this.negotiationRequested) {\n          this.negotiationRequested = false;\n          const joinedExistingNegotiation = !!this.negotiating;\n          try {\n            await this.negotiate();\n          } catch(err) {\n            this.negotiationRequested = true;\n            throw err;\n          }\n\n          // A direct negotiation that was already in flight cannot contain the\n          // mutation represented by this request. Run one owned pass after it.\n          if(joinedExistingNegotiation) this.negotiationRequested = true;\n        }\n      } finally {\n        // Clear before the queue Promise settles. Clearing in an outer finally\n        // leaves a microtask-sized gap where a request can mark the queue dirty,\n        // receive the already-settled Promise and then be lost.\n        this.negotiationQueue = undefined;\n      }\n    });\n    this.negotiationQueue = queue;\n    return queue;\n  }\n\n  public createPeerConnection() {\n    return this.connection || super.createPeerConnection({\n      iceServers: [],\n      iceTransportPolicy: 'all',\n      bundlePolicy: 'max-bundle',\n      rtcpMuxPolicy: 'require',\n      iceCandidatePoolSize: 0\n      // sdpSemantics: \"unified-plan\",\n      // extmapAllowMixed: true,\n    });\n  }\n\n  public createDataChannel() {\n    if(this.dataChannel) {\n      return this.dataChannel;\n    }\n\n    const dataChannel = super.createDataChannel();\n\n    dataChannel.addEventListener('open', () => {\n      this.maybeUpdateRemoteVideoConstraints();\n    });\n\n    dataChannel.addEventListener('close', () => {\n      this.clearUpdateConstraintsInterval();\n    });\n\n    return dataChannel;\n  }\n\n  private clearUpdateConstraintsInterval() {\n    if(this.updateConstraintsInterval) {\n      clearInterval(this.updateConstraintsInterval);\n      this.updateConstraintsInterval = undefined;\n    }\n  }\n\n  public closeConnection() {\n    // The data channel's `close` event was the only thing stopping the\n    // constraints timer, and pc.close() does not reliably fire it — the timer\n    // kept ticking against a dead channel for the rest of the session.\n    this.clearUpdateConstraintsInterval();\n    super.closeConnection();\n  }\n\n  // The SFU's answer is interpolated into the SDP handed to setRemoteDescription\n  // (transport ufrag / pwd / fingerprints, the codec tables), so it gets the same\n  // shape-and-line-safety check as the 1-on-1 signalling. Throwing is the\n  // fail-closed path: an initial join rolls back through rollbackFailedJoin, a\n  // runtime renegotiation ends in hangUpAfterTransportFailure.\n  private parseConnectionData(raw: string): UpdateGroupCallConnectionData {\n    let data: unknown;\n    try {\n      data = JSON.parse(raw);\n    } catch(err) {\n      this.log.error('group call connection data is not JSON', err);\n    }\n\n    const reason = getUnsafeConnectionDataReason(data);\n    if(reason !== undefined) {\n      throw new Error(`Invalid group call connection data: ${reason}`);\n    }\n\n    return data as UpdateGroupCallConnectionData;\n  }\n\n  public createDescription() {\n    if(this.description) {\n      return this.description;\n    }\n\n    const description = super.createDescription();\n\n    /* const perType = 0;\n    const types = ['audio' as const, 'video' as const];\n    const count = types.length * perType;\n    const init: RTCRtpTransceiverInit = {direction: 'recvonly'};\n    types.forEach((type) => {\n      for(let i = 0; i < perType; ++i) {\n        description.createEntry(type).createTransceiver(connection, init);\n      }\n    }); */\n\n    return description;\n  }\n\n  public appendStreamToConference(\n    onSenderCreated?: (sender: RTCRtpSender) => void,\n    throwOnReplaceError = false\n  ) {\n    return super.appendStreamToConference(onSenderCreated, throwOnReplaceError);/* .then(() => {\n      currentGroupCall.connections.main.negotiating = false;\n      this.startNegotiation({\n        type: type,\n        isMuted: muted,\n        rejoin\n      });\n    }); */\n  }\n\n  private async invokeGroupCallConnection(localSdp: SDP, mainChannels: SDPMediaSection[], options: GroupCallConnectionInstance['options']) {\n    const {groupCall, description} = this;\n    const groupCallId = groupCall.id;\n\n    // DTLS role (client = passive, SFU = active) is the same for legacy and\n    // conference calls — see processMediaSection comment.\n    const processedChannels = mainChannels.map((section) => {\n      const processed = processMediaSection(localSdp, section);\n\n      this.sources[processed.entry.type as 'video' | 'audio'] = processed.entry;\n\n      return processed;\n    });\n\n    const audioChannel = processedChannels.find((channel) => channel.media.mediaType === 'audio');\n    const videoChannel = processedChannels.find((channel) => channel.media.mediaType === 'video');\n    let {source, params} = audioChannel || {};\n    const useChannel = videoChannel || audioChannel;\n\n    const channels: {[type in WebRTCLineType]?: typeof audioChannel} = {\n      audio: audioChannel,\n      video: videoChannel\n    };\n\n    description.entries.forEach((entry) => {\n      if(entry.direction === 'sendonly') {\n        const channel = channels[entry.type];\n        if(!channel) return;\n\n        description.setEntrySource(entry, channel.sourceGroups || channel.source);\n        description.setEntryPeerId(entry, rootScope.myId);\n      }\n    });\n\n    // overwrite ssrc with audio in video params\n    if(params !== useChannel.params) {\n      const data: JoinGroupCallJsonPayload = JSON.parse(useChannel.params.data);\n      // data.ssrc = source || data.ssrc - 1; // audio channel can be missed in screensharing\n      if(source) data.ssrc = source;\n      else delete data.ssrc;\n      params = {\n        _: 'dataJSON',\n        data: JSON.stringify(data)\n      };\n    }\n\n    // Existing calls use phone.joinGroupCall. A fresh conference uses the same\n    // SDP/key/block payload in one atomic phone.createConferenceCall request.\n    //\n    // On CONF_WRITE_CHAIN_INVALID — the e2e chain advanced between our fetch\n    // and our submit (a concurrent join, key change, etc.). Refetch chain\n    // head + rebuild the self-add block + resubmit. WebRTC state stays —\n    // only the `block` field changes per attempt. Caps at 5 retries to bound\n    // pathological loops; tdlib doesn't cap but we're conservative.\n    // Strip the rebuild callback before forwarding — `this.managers` is a\n    // worker proxy and `postMessage`'s structured clone refuses functions\n    // (silently hanging the call on some browsers). Keep the callback in\n    // the closure so the retry loop can still invoke it locally.\n    const rebuildBlock = options.type === 'main' && !options.e2eCreateConference ?\n      options.e2eRebuildBlock :\n      undefined;\n    const commitRebuiltBlock = options.type === 'main' ? options.e2eCommitRebuiltBlock : undefined;\n    const activateE2e = options.type === 'main' ? options.e2eActivate : undefined;\n    const stripCallback = <T extends typeof options>(o: T): T =>\n      (o.type === 'main' ? {\n        ...o,\n        e2eRebuildBlock: undefined,\n        e2eCommitRebuiltBlock: undefined,\n        e2eActivate: undefined\n      } : o) as T;\n    const maxRetries = 5;\n    let update: Awaited<ReturnType<typeof this.managers.appGroupCallsManager.joinGroupCall>>;\n    let activeOptions = options;\n    let rebuiltBlock = false;\n    for(let attempt = 0; ; attempt++) {\n      try {\n        if(activeOptions.type === 'main' && activeOptions.e2eCreateConference) {\n          update = await this.managers.appGroupCallsManager.createConferenceCall(\n            params,\n            stripCallback(activeOptions)\n          );\n        } else {\n          update = await this.managers.appGroupCallsManager.joinGroupCall(\n            groupCallId,\n            params,\n            stripCallback(activeOptions)\n          );\n        }\n        break;\n      } catch(err) {\n        const msg = (err as {type?: string} | Error & {type?: string})?.type ??\n          (err instanceof Error ? err.message : String(err));\n        const isChainRace = typeof msg === 'string' && msg.startsWith('CONF_WRITE_CHAIN_INVALID');\n        if(!isChainRace || attempt >= maxRetries - 1) throw err;\n        if(!rebuildBlock) throw err;\n        const newBlock = await rebuildBlock();\n        rebuiltBlock = true;\n        // Build a fresh options bag with the new block — keep WebRTC state.\n        activeOptions = {...activeOptions, e2eBlock: newBlock} as typeof activeOptions;\n      }\n    }\n\n    // Invitee paths (slug / inviteMessage) join under a placeholder instance\n    // id. The server hands back the real id+access_hash in updateGroupCall —\n    // joinGroupCall stitches them onto `update`. Promote them onto the\n    // instance so downstream code (polling, hangUp, leave) works.\n    const extras = update;\n    // Store the accepted identity before canonical promotion, worker commit,\n    // chain replay, activation or SDP parsing. Any of those can throw after\n    // the server has already installed our participant and source.\n    this.acceptedCallInput = extras.acceptedCallInput ??\n      (activeOptions.type === 'main' ? activeOptions.e2eCallInput : undefined);\n    this.joinAccepted = true;\n    const promotedPlaceholder = extras.resolvedCallId != null && extras.resolvedCallId !== this.groupCall.id;\n    if(promotedPlaceholder) {\n      this.groupCall.id = extras.resolvedCallId;\n    }\n\n    // Take the access_hash the join actually returned. `joinGroupCall` stitches\n    // it on beside the id, but only the id was ever read — so a cached call\n    // object left over from an earlier session (state survives a reload, and a\n    // rejoin mints a NEW hash) kept its stale hash forever. Every request built\n    // from it then failed GROUPCALL_INVALID: the chain poll, the roster refresh,\n    // getGroupCallFull. Media already negotiated keeps flowing, so the call\n    // looks fine while it has silently stopped learning about participants —\n    // and because the recv transform is fail-closed, any source a peer starts\n    // AFTER that point is never mapped and is dropped. Observed live as \"I see\n    // their video but hear nothing\".\n    if(extras.resolvedGroupCall) {\n      this.groupCall.groupCall = extras.resolvedGroupCall;\n    }\n    const cachedCall = this.groupCall.groupCall;\n    if(extras.resolvedAccessHash != null && cachedCall?._ === 'groupCall') {\n      cachedCall.access_hash = extras.resolvedAccessHash as typeof cachedCall.access_hash;\n    }\n\n    const canonicalInput = this.groupCall.toInputGroupCall();\n    if(!canonicalInput) {\n      throw new Error('Conference join response did not resolve a canonical group call');\n    }\n\n    const acceptedChainUpdates: NonNullable<typeof extras.resolvedChainUpdates> = [];\n    const acceptedSubChains = new Set<number>();\n    for(const chainUpdate of extras.resolvedChainUpdates || []) {\n      if(!sameInputGroupCall(chainUpdate.call, canonicalInput)) continue;\n      if(acceptedSubChains.has(chainUpdate.sub_chain_id)) {\n        throw new Error('Conference join response contained multiple chain slices for one subchain');\n      }\n      acceptedSubChains.add(chainUpdate.sub_chain_id);\n      acceptedChainUpdates.push(chainUpdate);\n    }\n\n    // A rebuilt proposal becomes the worker anchor only after the exact RPC\n    // carrying it was accepted and the placeholder has been promoted. This\n    // keeps every later poll/broadcast bound to the canonical call identity.\n    if(rebuiltBlock) {\n      if(!commitRebuiltBlock) {\n        throw new Error('Conference join block was rebuilt without a worker commit callback');\n      }\n      await commitRebuiltBlock();\n    }\n\n    // Apply the accepted join response through its authoritative initial path\n    // before activation. Canonical joins may already have buffered the same\n    // slices through apiUpdatesManager; invite placeholders missed that push.\n    // The instance handles both cases without allowing arbitrary later pushes\n    // to rebase the compacted verification cursor.\n    for(const chainUpdate of acceptedChainUpdates) {\n      const accepted = await this.groupCall.deliverAcceptedE2eJoinChainBlocks(\n        chainUpdate.sub_chain_id,\n        chainUpdate.blocks,\n        chainUpdate.next_offset\n      );\n      if(!accepted) {\n        throw new Error('Conference join response contained an invalid chain slice');\n      }\n    }\n\n    await activateE2e?.();\n\n    const data = this.parseConnectionData(update.params.data);\n\n    data.audio = data.audio || groupCall.connections.main.description.audio;\n    description.setData(data);\n    filterServerCodecs(mainChannels, data);\n\n    return data;\n  }\n\n  protected async negotiateInternal() {\n    const {connection, description} = this;\n    const isNewConnection = connection.iceConnectionState === 'new' && !description.getEntryByMid('0').source;\n    const log = this.log.bindPrefix('startNegotiation');\n    log('start');\n\n    const originalOffer = await connection.createOffer({iceRestart: false});\n\n    if(isNewConnection && this.dataChannel) {\n      const dataChannelEntry = description.createEntry('application');\n      dataChannelEntry.setDirection('sendrecv');\n    }\n\n    const {sdp: localSdp, offer} = fixLocalOffer({\n      offer: originalOffer,\n      data: description\n    });\n\n    log('[sdp] setLocalDescription', offer.sdp);\n    await connection.setLocalDescription(offer);\n\n    const mainChannels = localSdp.media.filter((media) => {\n      return media.mediaType !== 'application' && media.isSending;\n    });\n\n    if(isNewConnection) {\n        await this.invokeGroupCallConnection(localSdp, mainChannels, this.options);\n      this.clearE2eJoinSecrets();\n    }\n\n    /* if(!data) {\n      log('abort 0');\n      this.closeConnectionAndStream(connection, streamManager);\n      return;\n    } */\n\n    /* if(connection.iceConnectionState !== 'new') {\n      log(`abort 1 connectionState=${connection.iceConnectionState}`);\n      this.closeConnectionAndStream(connection, streamManager);\n      return;\n    } */\n    /* if(this.currentGroupCall !== currentGroupCall || connectionHandler.connection !== connection) {\n      log('abort', this.currentGroupCall, currentGroupCall);\n      this.closeConnectionAndStream(connection, streamManager);\n      return;\n    } */\n\n    const isAnswer = true;\n    // const _bundleMids = bundleMids.slice();\n    const entriesToDelete: ConferenceEntry[] = [];\n    const bundle = localSdp.bundle;\n    forEachReverse(bundle, (mid, idx, arr) => {\n      const entry = description.getEntryByMid(mid);\n      // Entry may be undefined for mids we addTransceiver'd outside of\n      // the LocalConferenceDescription (e.g. the conference-path's\n      // pre-added recvonly transceivers for receive-side e2e transform\n      // attachment). Leave such mids in the bundle as-is; Chrome's\n      // generated SDP for them is already valid.\n      if(entry && entry.shouldBeSkipped(isAnswer)) {\n        arr.splice(idx, 1);\n        entriesToDelete.push(entry);\n      }\n    });\n\n    /* forEachReverse(description.entries, (entry, idx, arr) => {\n      const mediaSection = _parsedSdp.media.find((section) => section.oa.get('mid').oa === entry.mid);\n      const deleted = !mediaSection;\n      // const deleted = !_bundleMids.includes(entry.mid); // ! can't use it because certain mid can be missed in bundle\n      if(deleted) {\n        arr.splice(idx, 1);\n      }\n    }); */\n\n    const entries = localSdp.media.map((section) => {\n      const mid = section.mid;\n      let entry = description.getEntryByMid(mid);\n      if(!entry) {\n        entry = new ConferenceEntry(mid, section.mediaType);\n        entry.setDirection('inactive');\n      }\n\n      return entry;\n    });\n\n    const answerDescription: RTCSessionDescriptionInit = {\n      type: 'answer',\n      sdp: description.generateSdp({\n        bundle,\n        entries,\n        isAnswer\n      })\n    };\n\n    entriesToDelete.forEach((entry) => {\n      description.deleteEntry(entry);\n    });\n\n    log(`[sdp] setRemoteDescription signaling=${connection.signalingState} ice=${connection.iceConnectionState} gathering=${connection.iceGatheringState} connection=${connection.connectionState}`, answerDescription.sdp);\n    await connection.setRemoteDescription(answerDescription);\n\n    log('end');\n  }\n\n  public negotiate() {\n    let promise = this.negotiating;\n    if(promise) {\n      return promise;\n    }\n\n    promise = super.negotiate();\n\n    // NB: don't try to attach e2e transforms here. Chrome rejects\n    // `RTCRtpScriptTransform` assignments after the codec has produced its\n    // first frame (\"Too late to create encoded streams\" in the parallel\n    // createEncodedStreams API). Senders get their transforms pre-negotiate in\n    // groupCallsController.joinConferenceCommon; receivers get them when their\n    // recvonly transceivers are created in GroupCallInstance.onParticipantUpdate.\n\n    if(this.updateConstraints) {\n      void promise.then(() => {\n        this.maybeUpdateRemoteVideoConstraints();\n        this.updateConstraints = false;\n      }, (): undefined => undefined).catch((err) => {\n        this.log.warn('updating remote video constraints after negotiation failed', err);\n      });\n    }\n\n    if(this.options.type === 'presentation') {\n      void promise.then(async() => {\n        const transceiver = this.connection.getTransceivers().find((transceiver) => {\n          return transceiver.sender?.track?.kind === 'video';\n        });\n        if(transceiver) {\n          await transceiver.sender.setParameters({\n            ...transceiver.sender.getParameters(),\n            degradationPreference: 'maintain-resolution'\n          });\n        }\n      }, (): undefined => undefined).catch((err) => {\n        this.log.warn('setting presentation sender parameters failed', err);\n      });\n    }\n\n    return promise;\n  }\n\n  /** Drop join-scoped rebuild/activation callbacks once SDP is established. */\n  public clearE2eJoinSecrets(): void {\n    if(this.options.type !== 'main') return;\n    this.options.e2eRebuildBlock = undefined;\n    this.options.e2eCommitRebuiltBlock = undefined;\n    this.options.e2eActivate = undefined;\n  }\n\n  public maybeUpdateRemoteVideoConstraints() {\n    if(this.dataChannel.readyState !== 'open') {\n      return;\n    }\n\n    this.log('maybeUpdateRemoteVideoConstraints');\n\n    // * https://github.com/TelegramMessenger/tgcalls/blob/6f2746e04c9b040f8c8dfc64d916a1853d09c4ce/tgcalls/group/GroupInstanceCustomImpl.cpp#L2549\n    type VideoConstraints = {minHeight?: number, maxHeight: number};\n    const obj: {\n      colibriClass: 'ReceiverVideoConstraints',\n      constraints: {[endpoint: string]: VideoConstraints},\n      defaultConstraints: VideoConstraints,\n      onStageEndpoints: string[]\n    } = {\n      colibriClass: 'ReceiverVideoConstraints',\n      constraints: {},\n      defaultConstraints: {maxHeight: 0},\n      onStageEndpoints: []\n    };\n\n    const pinnedSource = this.groupCall?.pinnedSource;\n    const videoEntries = this.description.entries.filter((entry) => {\n      return entry.direction === 'recvonly' && entry.type === 'video';\n    });\n    videoEntries.sort((a, b) => Number(b.source === pinnedSource) - Number(a.source === pinnedSource));\n    for(const entry of videoEntries.slice(0, MAX_ON_STAGE_VIDEO_ENDPOINTS)) {\n      const {endpoint} = entry;\n      obj.onStageEndpoints.push(endpoint);\n      obj.constraints[endpoint] = entry.source === pinnedSource ?\n        {minHeight: 180, maxHeight: 720} :\n        {minHeight: 180, maxHeight: 360};\n    }\n\n    this.sendDataChannelData(obj);\n\n    if(!obj.onStageEndpoints.length) {\n      this.clearUpdateConstraintsInterval();\n    } else if(!this.updateConstraintsInterval) {\n      this.updateConstraintsInterval = window.setInterval(this.maybeUpdateRemoteVideoConstraints.bind(this), 5000);\n    }\n  }\n\n  public addInputVideoStream(stream: MediaStream): Promise<void> {\n    // const {sources} = this;\n    // if(sources?.video) {\n    // const source = this.sources.video.source;\n    // stream.source = '' + source;\n    this.groupCall.saveInputVideoStream(stream, this.type);\n    // }\n\n    this.streamManager.addStream(stream, 'input');\n    return this.appendInputStreamWithE2e();\n  }\n\n  /**\n   * Re-attach the StreamManager's existing input tracks to a freshly-created\n   * presentation connection. Keeping the transform hook here makes initial\n   * screen sharing and presentation-only recovery follow the same critical\n   * createTransceiver -> transform -> replaceTrack ordering.\n   */\n  public appendInputStreamWithE2e(): Promise<void> {\n    // Attach the e2e send transform to any sender created here, in the\n    // createTransceiver→replaceTrack gap (the only window Chrome accepts it).\n    // The MAIN connection's senders are already wired at join\n    // (joinConferenceCommon's onSenderCreated hook), so for that connection the\n    // video transceiver already exists and this hook does not re-fire. It DOES\n    // fire for the PRESENTATION (screen-share) connection, which is created\n    // later with no such wiring — without it, screen-share video would go out\n    // UNENCRYPTED and the SFU/peer couldn't decrypt it. attachE2eSendTransform\n    // no-ops for legacy (non-e2e) calls and for already-transformed senders.\n    return this.appendStreamToConference((sender) => {\n      const kind = senderKind(this.connection, sender);\n      // Screencast video uses its own e2e channel so its per-(sender, channel)\n      // replay window doesn't contend with the main camera/audio. tde2e keys\n      // replay by channel_id; the id value itself isn't validated by the peer\n      // (the mismatch check is disabled), only its distinctness matters.\n      const channelId = this.type === 'presentation' && kind === 'video' ?\n        E2E_SCREENCAST_CHANNEL_ID :\n        E2E_MAIN_CHANNEL_ID;\n      this.groupCall.attachE2eSendTransform(sender, kind, channelId);\n    }, true); // replace sender track and expose browser failures to the transaction\n  }\n}\n","enum GROUP_CALL_STATE {\n  UNMUTED,\n  MUTED,\n  MUTED_BY_ADMIN,\n  CONNECTING,\n  CLOSED\n}\n\nexport default GROUP_CALL_STATE;\n","/*\n * Chain ↔ SFU roster reconciliation for TdE2E conferences.\n *\n * The blockchain — NOT the server's participant list — is the authority on who\n * holds the group's shared key. tdlib's Encryption.md makes surfacing that a\n * client requirement, not an optimisation: \"The blockchain state must be\n * explicitly displayed in the UI, even when the server withholds information\n * about certain participants\".\n *\n * Why it matters: `external_permissions` grants Add|Remove to NON-members (see\n * groupCallsController's zero block, `externalPermissions: 3`), so anyone who\n * can append to the chain can self-add with a key they own — no honest private\n * key required. `applyBlock` then authorises the block's `setSharedKey` against\n * the POST-change group state (blockchain.ts), so that self-add also mints the\n * next shared key and addresses it to the new member. A backend that appends\n * such a block and then omits the identity from `phone.getGroupParticipants`\n * gets a silent listener: the client accepts the block, adopts the key, and\n * — without this reconciliation — renders only the server-reported roster.\n * Matching emoji fingerprints do not expose it either, since a cooperative\n * hidden member completes the commit/reveal round like anyone else.\n *\n * The protocol's answer is stale pruning:\n * core.telegram.org/api/end-to-end/group-calls#stale-pruning-only-left —\n * compare chain membership against a COMPLETE roster, keep chain-only\n * identities visible as having access, then remove them and rotate the key via\n * `phone.deleteConferenceCallParticipants(only_left=true)`.\n *\n * These helpers stay pure so the decision is unit-testable without a worker,\n * an SFU or a live call. Callers live in GroupCallInstance.\n *\n * tdesktop equivalents: `GroupCall::checkStaleParticipants` (data_group_call.cpp)\n * and `GroupCall::removeConferenceParticipants` (calls_group_call.cpp).\n */\n\nimport type {GroupParticipant, GroupState} from './tlTypes';\n\n// Conference participants are always users, so the e2e `user_id` maps straight\n// onto a PeerId. Kept as one function so the chain (bigint) and the UI (PeerId)\n// vocabularies only ever meet here.\n//\n// NB this is for RENDERING only. PeerId is a JS number, so the conversion is\n// lossy above 2^53 — which is fine for a row (the whole app keys peers this\n// way) but must never decide MEMBERSHIP: two distinct chain user_ids can round\n// to the same double, and the server picks both the chain ids and the roster\n// ids. An identity could hide behind a rounding collision with a junk roster\n// row. findChainOnlyMembers therefore compares exact decimal strings.\n//\n// Deliberately never throws: it sits on the reconcile path, and a throw there\n// would skip the removal too. Ids <= 0 (0 is NULL_PEER_ID = \"self\", negatives\n// are chat space) are rejected by validateGroupState before a chain state can\n// reach this, and publishMembersWithAccess refuses to key a row by them.\nexport function conferenceUserIdToPeerId(userId: bigint): PeerId {\n  return Number(userId).toPeerId();\n}\n\n/**\n * Chain participants that a COMPLETE SFU roster does not list.\n *\n * Only meaningful for a complete roster — with a truncated page \"absent\" just\n * means \"on a later page\", and pruning off that would kick real participants.\n * The caller is responsible for that gate (see `refreshConferenceParticipants`'\n * `complete` flag).\n */\nexport function findChainOnlyMembers(opts: {\n  participants: GroupParticipant[];\n  // Exact decimal user ids the SFU listed — NOT PeerIds, see the note above.\n  rosterUserIds: Iterable<string>;\n  selfUserId: bigint;\n}): bigint[] {\n  const present = new Set<string>(opts.rosterUserIds);\n  // Never treat ourselves as stale. Our own SFU row lags the chain on the\n  // invitee path (it only lands after the SDP exchange), and self-removal isn't\n  // representable anyway: the protocol has no self-remove because the leaver\n  // can't mint the successor key for everyone else.\n  present.add(opts.selfUserId.toString());\n\n  const seen = new Set<string>();\n  const stale: bigint[] = [];\n  for(const participant of opts.participants) {\n    if(present.has(participant.userId.toString())) {\n      continue;\n    }\n\n    // validateGroupState already rejects duplicate user_ids, but a participant\n    // set arrives here from the worker snapshot — dedupe so a malformed one\n    // can't produce a removal list with repeats.\n    const key = participant.userId.toString();\n    if(seen.has(key)) {\n      continue;\n    }\n\n    seen.add(key);\n    stale.push(participant.userId);\n  }\n\n  return stale;\n}\n\n/**\n * The group state to submit alongside `only_left`: everyone except the stale\n * identities. `buildChangesForNewState` turns this into a setGroupState +\n * setSharedKey pair, so the removal and the rekey land in the same block — the\n * removed identity cannot follow the call past it.\n */\nexport function pruneGroupState(groupState: GroupState, staleUserIds: Iterable<bigint>): GroupState {\n  const stale = new Set<string>();\n  for(const userId of staleUserIds) {\n    stale.add(userId.toString());\n  }\n\n  return {\n    participants: groupState.participants.filter((p) => !stale.has(p.userId.toString())),\n    // Carry external_permissions through untouched. authorizeSetGroupState\n    // rejects any attempt to RAISE them, and lowering them here would silently\n    // change the call's join policy as a side effect of a cleanup.\n    externalPermissions: groupState.externalPermissions\n  };\n}\n","import getGroupCallAudioAsset from '@components/groupCall/getAudioAsset';\nimport {toastNew} from '@components/toast';\n\n// An admin lifted our forced mute. We stay muted until the user unmutes, so\n// without a cue the lifted restriction is invisible — the sound and the toast\n// are the only signal that the microphone button works again (tdesktop\n// GroupCall::notifyAboutAllowedToSpeak + Toasts::setupAllowedToSpeak).\nexport default function notifyAllowedToSpeak() {\n  getGroupCallAudioAsset().play({name: 'allowtalk'});\n  toastNew({langPackKey: 'VoiceChat.YouCanNowSpeak'});\n}\n","import type {AppGroupCallsManager, GroupCallConnectionType, GroupCallId, GroupCallOutputSource} from '@appManagers/appGroupCallsManager';\nimport {IS_SAFARI} from '@environment/userAgent';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport safeAssign from '@helpers/object/safeAssign';\nimport pause from '@helpers/schedulers/pause';\nimport throttle from '@helpers/schedulers/throttle';\nimport {GroupCall, GroupCallParticipant, InputGroupCall} from '@layer';\nimport {logger} from '@lib/logger';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport rootScope from '@lib/rootScope';\nimport CallInstanceBase, {TryAddTrackOptions} from '@lib/calls/callInstanceBase';\nimport GroupCallConnectionInstance from '@lib/calls/groupCallConnectionInstance';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\nimport getScreenConstraints from '@lib/calls/helpers/getScreenConstraints';\nimport getScreenStream from '@lib/calls/helpers/getScreenStream';\nimport getStream from '@lib/calls/helpers/getStream';\nimport getVideoConstraints from '@lib/calls/helpers/getVideoConstraints';\nimport {findGroupCallChainUpdate, getUpdatesList, groupCallToInput} from '@lib/calls/helpers/groupCallUpdates';\nimport stopTrack from '@lib/calls/helpers/stopTrack';\nimport localConferenceDescription, {ConferenceEntry} from '@lib/calls/localConferenceDescription';\nimport {WebRTCLineType} from '@lib/calls/sdpBuilder';\nimport StreamManager, {waitForMediaTrackReplacements} from '@lib/calls/streamManager';\nimport {Ssrc} from '@lib/calls/types';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {AppManagers} from '@lib/managers';\nimport {generateSelfVideo, makeSsrcFromParticipant, makeSsrcsFromParticipant} from '@lib/calls/groupCallsController';\nimport type {EncryptWorkerHost} from '@lib/calls/e2e/encryptWorkerHost';\nimport type {CallStatusSnapshot} from '@lib/calls/e2e/encryptWorkerProtocol';\nimport {\n  conferenceUserIdToPeerId,\n  findChainOnlyMembers\n} from '@lib/calls/e2e/conferenceMembership';\nimport {GROUP_CALL_PARTICIPANTS_LOAD_LIMIT} from '@lib/calls/constants';\nimport {fromTelegramSource, normalizeSsrc} from '@lib/calls/utils';\nimport createSerializedQueue from '@helpers/createSerializedQueue';\nimport notifyAllowedToSpeak from '@components/groupCall/allowedToSpeakCue';\n\n// Screen capture is requested without tab / system audio. There is no in-app\n// \"share system audio\" toggle yet (tdesktop asks explicitly in its picker), so\n// audio-less is the privacy default: the browser's picker would otherwise offer\n// the audio of whatever else is playing, and the P2P path\n// (callInstanceBase.requestScreen) already asks this way.\nconst getGroupScreenConstraints = () => getScreenConstraints(true);\n\n\n// If a conference poller hasn't reached the server in this long while the call\n// is alive, the watchdog forces recovery. Comfortably past the poll cadences\n// (chain 1.5s, participants 5s) so transient network hiccups don't trip it.\nconst E2E_SYNC_STALL_MS = 15000;\n// Ceiling on active ssrc -> user_id mappings, lifetime conference media\n// allocations and the legacy call's m-lines alike. Each source is\n// server-chosen and costs a transceiver + decoder; real calls are far smaller.\nconst MAX_E2E_SSRC_ENTRIES = 1024;\n// Consecutive incomplete roster polls before we surface it. The roster poll is\n// on a 5s timer, so this is ~15s of a server refusing to say who is in the call.\nconst INCOMPLETE_ROSTER_POLLS_BEFORE_REPORT = 3;\n// Consecutive watchdog recoveries that failed to advance the stale poller\n// clock before the local re-hydrate loop is declared unable to fix the stall\n// and the call escalates to a full controller-owned rejoin. Local recovery can\n// only refresh `groupCall` and re-kick the pollers — it cannot re-anchor a\n// chain cursor the server has compacted past, and tdesktop's answer to that\n// state is likewise a rebuilt call. Without this cap the watchdog re-ran the\n// same unproductive refresh every tick for the rest of the call.\nconst UNPRODUCTIVE_SYNC_RECOVERIES_BEFORE_REJOIN = 3;\n// How many group_state membership changes may re-arm a parked unmapped-SSRC\n// resolution. Bounds a genuinely foreign identity to a handful of targeted\n// lookups over the call's lifetime while covering any realistic chain lag.\nconst MAX_E2E_MEMBERSHIP_RESOLUTION_RETRIES = 3;\n// How long a server-accepted unmute stays armed waiting for a self row that\n// confirms it. A stale muted row can land mid-RPC and win the post-RPC check;\n// without the armed intent the server would keep listing us as unmuted while\n// capture stays disabled — peers see a speaker and hear silence. Short-lived\n// so a much later unmuted row cannot surprise-open the microphone.\nconst UNMUTE_INTENT_TTL_MS = 15000;\n// Consecutive GROUPCALL_INVALID answers before we stop pretending to be in the\n// call. The chain poll runs every 1.5s, so this is a few seconds of the server\n// telling us this call is not ours.\nconst CALL_INVALID_ANSWERS_BEFORE_LEAVING = 8;\n// Verification broadcasts are small and ordered. Keep a pulled message at the\n// head of the host-side queue until it is accepted, but bound the delay so a\n// permanent RPC error cannot wedge later rounds forever.\nconst E2E_OUTBOUND_MAX_ATTEMPTS = 5;\nconst E2E_OUTBOUND_RETRY_BASE_MS = 250;\nconst MEDIA_TEARDOWN_MAX_ATTEMPTS = 3;\nconst MEDIA_TEARDOWN_RETRY_BASE_MS = 250;\n// Keep the nearest gap suffix and refetch anything beyond it. This bounds a\n// relay-controlled sequence of far-future push batches without sacrificing the\n// low indexes needed to restore continuity.\nconst MAX_E2E_PENDING_CHAIN_BLOCKS = 256;\n\n// Every SSRC a participant can actually send on, not just the primary.\n//\n// `generateSsrc` collapses a video source_group list down to\n// `sourceGroups[0].sources[0]`, so registering `ssrc.source` alone covered ONE\n// of a simulcast sender's layers. The SFU switches layers on its own (see\n// maybeUpdateRemoteVideoConstraints) and retransmits over the FID/RTX SSRCs, so\n// frames routinely arrive on a source that was never mapped — and the recv\n// transform is fail-closed, which turns \"the relay picked another layer\" into\n// silence or a frozen tile with an `unmapped SSRC` breadcrumb. Map the whole\n// group: every layer and every retransmission SSRC belongs to the same sender,\n// so they all verify against the same key.\nexport function e2eSourcesOf(ssrc: Ssrc): number[] {\n  const sources: number[] = [];\n  const add = (source: number) => {\n    if(source && !sources.includes(source)) sources.push(source);\n  };\n\n  add(ssrc.source);\n  for(const group of ssrc.sourceGroups || []) {\n    for(const source of group.sources || []) add(source);\n  }\n\n  return sources;\n}\n\n// Conference roster rows are snapshots from independent push/poll paths and a\n// later-arriving row may be older and thinner than one already applied. Build a\n// monotonic per-peer source view: only an explicit `left` proves that a source\n// stopped belonging to the peer. This also keeps pressure sweeps from deleting\n// the verification-key mapping of a still-live omitted stream.\nfunction mergeE2eParticipantSsrcs(previous: Ssrc[], announced: Ssrc[]): Ssrc[] {\n  const merged = previous.slice();\n  for(const current of announced) {\n    const index = merged.findIndex(({source, type}) => source === current.source && type === current.type);\n    if(index === -1) {\n      merged.push(current);\n      continue;\n    }\n\n    const old = merged[index];\n    const sourceGroups = (old.sourceGroups || []).slice();\n    for(const group of current.sourceGroups || []) {\n      const duplicate = sourceGroups.some((candidate) =>\n        candidate.semantics === group.semantics &&\n        candidate.sources.length === group.sources.length &&\n        candidate.sources.every((source, sourceIndex) => source === group.sources[sourceIndex])\n      );\n      if(!duplicate) sourceGroups.push(group);\n    }\n    merged[index] = {\n      ...old,\n      ...current,\n      sourceGroups: sourceGroups.length ? sourceGroups : undefined\n    };\n  }\n\n  return merged;\n}\n// How often the watchdog checks for the stall above.\nconst E2E_WATCHDOG_INTERVAL_MS = 5000;\n\n// How long a chain member must stay absent from COMPLETE SFU rosters before we\n// remove it from the blockchain.\n//\n// tdesktop prunes on the first complete roster (`checkStaleParticipants`), but\n// it only ever compares after re-requesting the participant list. Our roster\n// poll is on a timer, so the same immediacy would race a real joiner: their\n// block reaches the chain the moment `phone.joinGroupCall` accepts it, and the\n// SFU can list them a beat later — pruning that window kicks people out of the\n// call they just joined. The row is published as \"has access\" the instant it's\n// detected, so the disclosure requirement is met immediately; only the removal\n// waits out this window.\nconst CONFERENCE_STALE_GRACE_MS = 10000;\n// Floor between removal attempts. A rejected removal (chain raced ahead — or a\n// server that refuses to prune) must not turn the 5s roster poll into an RPC\n// loop.\nconst CONFERENCE_PRUNE_RETRY_MS = 15000;\n// Consecutive removal failures before we surface a breadcrumb. A server that\n// keeps rejecting the removal while the identity keeps holding the call key is\n// exactly the case the user needs told about.\nconst CONFERENCE_PRUNE_FAILURES_BEFORE_REPORT = 3;\n\nfunction mediaCleanupError(message: string, operationError: unknown, cleanupError: unknown): Error {\n  const error = new Error(message);\n  (error as Error & {cause?: unknown}).cause = {operationError, cleanupError};\n  return error;\n}\n\nexport default class GroupCallInstance extends CallInstanceBase<{\n  state: (state: GROUP_CALL_STATE) => void,\n  pinned: (source?: GroupCallOutputSource) => void,\n  // Fired whenever the e2e worker reports a new snapshot — UI listens for\n  // verification phase + emoji fingerprint changes. Only fires when this\n  // instance is a conference (i.e. `e2e` is set).\n  e2eStatus: (status: CallStatusSnapshot) => void,\n  // Fired when the set of authenticated e2e members that the SFU roster does\n  // NOT list changes. These identities hold the current shared key, so the UI\n  // must show them (see conferenceMembership.ts). `previous` lets the roster\n  // list retire the rows it added.\n  membersWithAccess: (change: {current: PeerId[], previous: PeerId[]}) => void,\n  // A joined conference can lose active-participant authority or its key can\n  // fall out of the accepted membership chain. The controller owns the rejoin.\n  conferenceRecoveryRequired: (reason: string) => void\n}> {\n  public id: GroupCallId;\n  public chatId: ChatId;\n  public handleUpdateGroupCallParticipants: boolean;\n  public updatingSdp: boolean;\n  public isSpeakingMap: Map<any, any>;\n  public connections: {[k in GroupCallConnectionType]?: GroupCallConnectionInstance};\n  public groupCall: GroupCall;\n  public participant: GroupCallParticipant;\n\n  // ===== E2E (conference) mode =====\n  // When set, this instance is a TdE2E-encrypted conference call rather than\n  // a legacy voice chat. The worker owns the private key + per-frame crypto;\n  // the SFU plumbing below stays identical. `selfUserId` identifies us in the\n  // e2e group_state (matches our PrivateKey's publicKey).\n  public e2e?: EncryptWorkerHost;\n  public selfUserId?: bigint;\n  // attachE2e wires status/transforms before phone.joinGroupCall, but no chain\n  // or broadcast traffic may reach the proposed anchor until the server has\n  // accepted the join (and a chain-race replacement has been committed).\n  private e2eActive = false;\n  private e2eActivating = false;\n  private e2eActivationPromise: Promise<void> | undefined;\n  private e2eFatalError: Error | undefined;\n  // Latest snapshot from the worker (height, group state, emoji fingerprint).\n  public e2eStatus?: CallStatusSnapshot;\n  // ssrc → e2e user_id mapping. Populated from SFU signaling so the recv\n  // RTCRtpScriptTransform knows who sent each frame for Ed25519 verify.\n  public e2eUserBySsrc: Map<number, bigint> = new Map();\n  // Cumulative remote ConferenceEntry/transceiver allocations. Inactive\n  // entries remain in the SDP, so an active-map cap alone does not bound churn.\n  private e2eAllocatedRecvEntries: Set<number> = new Set();\n  private e2eSourceResolutions = new Map<number, {\n    attempts: number,\n    retry: boolean,\n    // The row WAS returned but its user was not yet in the e2e group_state —\n    // a deterministic \"chain block still in flight\" miss, not a failed lookup.\n    // Parked instead of terminal; each membership change re-arms one retry\n    // (bounded by membershipRetries so a never-joining identity cannot retry\n    // forever).\n    awaitingMembership?: boolean,\n    membershipRetries?: number\n  }>();\n  private e2eSourceResolutionPromise: Promise<void> | undefined;\n\n  // Set by the transport controller once ICE is connected. Keep the public\n  // property for existing callers, but emit through its setter so UI readiness\n  // cannot miss the exact transition from negotiating to joined.\n  private _joined = false;\n\n  private pinnedSources: Array<GroupCallOutputSource>;\n  private participantsSsrcs: Map<PeerId, Ssrc[]>;\n  private hadAutoPinnedSources: Set<GroupCallOutputSource>;\n  private dispatchPinnedThrottled: () => void;\n  private startVideoSharingPromise: Promise<void>;\n  private startScreenSharingPromise: Promise<void>;\n  private startScreenSharingPromiseGeneration = 0;\n  private videoSharingGeneration = 0;\n  private screenSharingGeneration = 0;\n  private closedPresentationConnections = new WeakSet<GroupCallConnectionInstance>();\n  private completedPresentationLeaves = new WeakSet<GroupCallConnectionInstance>();\n  private presentationLeavePromises = new WeakMap<GroupCallConnectionInstance, Promise<void>>();\n  private pendingPresentationLeaves = new Set<GroupCallConnectionInstance>();\n  private presentationTransitionTail = createSerializedQueue();\n  private presentationRecoveryPromise: Promise<void>;\n  private adminMediaTeardownPromise: Promise<void>;\n  private adminMediaTeardownGeneration = 0;\n  private adminMediaBlocked = false;\n  private selfParticipantRevision = 0;\n  // Monotonic clock of a server-accepted unmute still waiting for capture to\n  // open (see changeSelfMuted / UNMUTE_INTENT_TTL_MS). Undefined = no intent.\n  private pendingUnmuteIntentAt: number | undefined;\n  private selfMuteTransitionTail = createSerializedQueue();\n  private selfParticipantEditTail = createSerializedQueue();\n  private remoteNegotiationPending = false;\n  private fatalHangUpStarted = false;\n  private lifecycleGeneration = 0;\n  private observedInputAudioTracks = new WeakSet<MediaStreamTrack>();\n\n  private managers: AppManagers;\n\n  constructor(options: {\n    id: GroupCallInstance['id'],\n    chatId: GroupCallInstance['chatId'],\n    isSpeakingMap?: GroupCallInstance['isSpeakingMap'],\n    connections?: GroupCallInstance['connections'],\n    managers: AppManagers\n  }) {\n    super();\n\n    safeAssign(this, options);\n\n    if(!this.log) {\n      this.log = logger('GROUP-CALL');\n    }\n\n    if(!this.connections) {\n      this.connections = {};\n    }\n\n    if(!this.isSpeakingMap) {\n      this.isSpeakingMap = new Map();\n    }\n\n    this.pinnedSources = [];\n    this.participantsSsrcs = new Map();\n    this.hadAutoPinnedSources = new Set();\n    this.dispatchPinnedThrottled = throttle(() => {\n      this.dispatchEvent('pinned', this.pinnedSource);\n    }, 0, false);\n\n    this.addEventListener('state', (state) => {\n      if(state === GROUP_CALL_STATE.CLOSED) {\n        this.cleanup();\n      }\n    });\n  }\n\n  public cleanup(): void {\n    ++this.lifecycleGeneration;\n    ++this.videoSharingGeneration;\n    ++this.screenSharingGeneration;\n    this.stopE2eChainPolling();\n    // This one lives on the GLOBAL rootScope, so `super.cleanup()` — which only\n    // clears this instance's own emitter — never touched it. Every conference in\n    // a session left another live listener closing over a torn-down instance.\n    if(this.chainBlocksListener) {\n      rootScope.removeEventListener('group_call_chain_blocks', this.chainBlocksListener);\n      this.chainBlocksListener = undefined;\n    }\n    this.membersWithAccess.clear();\n    this.staleSince.clear();\n    this.e2eOutboundQueue.length = 0;\n    this.e2eOutboundFlushRequested = false;\n    this.e2eChainPending[0].clear();\n    this.e2eChainPending[1].clear();\n    this.e2eAllocatedRecvEntries.clear();\n    this.e2eSourceResolutions.clear();\n    this.e2eSourceResolutionPromise = undefined;\n    // Terminate the e2e worker so its Web Worker thread exits. Best-effort —\n    // the controller may have already done so via its own state listener,\n    // but a double-terminate is harmless (encryptWorkerHost guards).\n    if(this.e2e) {\n      void this.e2e.terminate().catch((): undefined => undefined);\n      this.e2e = undefined;\n    }\n    this.e2eActive = false;\n    this.e2eActivating = false;\n    this.pendingUnmuteIntentAt = undefined;\n    super.cleanup();\n  }\n\n  // ===== E2E (conference) hookup =====\n  //\n  // Called before phone.joinGroupCall so transforms and worker status are ready.\n  // Chain application, polling, roster reconciliation and outbound verification\n  // remain gated until activateE2e() after the server accepts the join.\n  public attachE2e(\n    worker: EncryptWorkerHost,\n    selfUserId: bigint,\n    initialOffsets?: Partial<{0: number; 1: number}>\n  ): void {\n    if(initialOffsets) {\n      this.seedE2eChainOffsets(initialOffsets);\n    }\n    this.e2e = worker;\n    this.selfUserId = selfUserId;\n\n    worker.addEventListener('status', (ev) => {\n      const height = ev.status.verification?.height;\n      if(height !== this.verificationRoundHeight) {\n        this.verificationRoundHeight = height;\n        if(height !== undefined) {\n          // A newer main tip replaces the verification round wholesale. Never\n          // keep retrying a commit/reveal that names the abandoned height.\n          this.e2eOutboundQueue = this.e2eOutboundQueue.filter((item) => item.height === height);\n        }\n      }\n\n      this.e2eStatus = ev.status;\n      this.dispatchEvent('e2eStatus', ev.status);\n\n      // Conference membership lives on the e2e blockchain — the SFU doesn't push\n      // `updateGroupCallParticipants` for conferences the way it does for legacy\n      // voice chats. Every applied chain block re-emits this status, so when the\n      // group_state member set changes (someone joined/left), re-sync the SFU\n      // participant roster + count off it.\n      if(this.e2eActive) this.syncConferenceMembersFromStatus();\n    });\n    worker.addEventListener('pendingOutbound', () => {\n      this.e2eOutboundFlushRequested = true;\n      if(this.e2eActive && !this.e2eActivating) void this.flushE2eOutbound();\n    });\n    worker.addEventListener('callFailed', (ev) => {\n      const message = ev?.message || 'Encryption worker failed';\n      // A newer accepted membership block can replace our public key while two\n      // clients join/rejoin concurrently. The key is no longer usable, but the\n      // canonical call still is: rebuild on the latest head through the same\n      // controller-owned full rejoin as GROUPCALL_FORBIDDEN.\n      if(message.startsWith('NOT_PARTICIPANT:') && this.e2eActive && !this.e2eActivating) {\n        this.log.warn('e2e membership lost — requesting full rejoin', message);\n        this.requestConferenceRecovery('membership-lost');\n        return;\n      }\n\n      this.log.error('e2e: callFailed — leaving; reason:', message);\n      this.e2eFatalError ??= new Error(message);\n      // Leave, do NOT discard. `hangUp(true)` routes to phone.discardGroupCall,\n      // which ends the conference for EVERY participant — so one client failing\n      // to apply a block used to tear down everyone else's call. Our e2e state\n      // being unusable is a statement about this client only; the others may be\n      // perfectly healthy, and if they are not, they will each decide that for\n      // themselves.\n      // Before/during activation the join transaction owns rollback. Let\n      // activateE2e reject into it instead of racing it with a second leave.\n      if(this.e2eActive && !this.e2eActivating) this.hangUpAfterFatalFailure();\n    });\n\n    // Recv-transform breadcrumb (deduped worker-side). A sustained `unmapped`\n    // is the \"seen but not heard\" failure: an inbound SSRC the e2e map never\n    // learned, so its frames stay encrypted → silence. `mappedUser` shows what\n    // WE pushed for that SSRC — '(none)' starts a targeted participant lookup\n    // below because the media path can beat the ordinary roster update.\n    worker.addEventListener('recvDiag', (ev) => {\n      const source = normalizeSsrc(ev.ssrc);\n      const mappedUser = this.e2eUserBySsrc.get(source);\n      this.log.warn(\n        'e2e recv diagnostic:', ev.reason, ev.sustained ? '(SUSTAINED)' : '',\n        'ssrc', source,\n        'mappedUser', mappedUser !== undefined ? mappedUser.toString() : '(none)',\n        ev.message || ''\n      );\n      if(ev.reason === 'unmapped') {\n        // Audio/video SSRCs can appear before their participant row reaches the\n        // roster. Resolve exactly this source through phone.getGroupParticipants\n        // instead of permanently classifying it as foreign and dropping it.\n        this.resolveUnmappedE2eSource(source, !!ev.sustained);\n      } else if(ev.sustained) {\n        this.reportConferenceBug(\n          'inbound media failed to decrypt (stale key?)',\n          {\n            ssrc: source,\n            mappedUser: mappedUser !== undefined ? mappedUser.toString() : null,\n            message: ev.message\n          }\n        );\n      }\n    });\n\n    // Inbound chain delivery — sub_chain_id 0 is the block chain, 1 is the\n    // verification broadcast channel. The server pushes these updates when it\n    // can, but we also poll because conference push delivery is best-effort\n    // (tdlib: TdE2E::Call::joined → shortPoll(0); shortPoll(1)).\n    this.chainBlocksListener = ({callId, subChainId, blocks, nextOffset}) => {\n      if(callId !== this.id || !this.e2e) return;\n      void this.deliverE2eChainBlocks(subChainId, blocks, nextOffset).catch((err) => {\n        // During post-accept activation a main-chain apply failure rejects so\n        // the join transaction can roll back. Push delivery has no direct\n        // caller, so observe that same rejection while the activation queue\n        // retains the exact failed block for the owner to see.\n        this.log.error('pushed e2e chain delivery failed', err);\n      });\n    };\n    rootScope.addEventListener('group_call_chain_blocks', this.chainBlocksListener);\n  }\n\n  /**\n   * Open the conference's network side effects after phone.joinGroupCall has\n   * accepted our exact block and invite placeholders have their canonical id.\n   */\n  public activateE2e(): Promise<void> {\n    if(this.e2eActivationPromise) return this.e2eActivationPromise;\n    if(this.e2eActive) return Promise.resolve();\n    if(!this.e2e) return Promise.reject(new Error('Conference encryption worker is unavailable during activation'));\n\n    const run = this.activateE2eInternal().finally(() => {\n      if(this.e2eActivationPromise === run) this.e2eActivationPromise = undefined;\n    });\n    this.e2eActivationPromise = run;\n    return run;\n  }\n\n  private async activateE2eInternal(): Promise<void> {\n    if(this.e2eFatalError) throw this.e2eFatalError;\n    this.e2eActivating = true;\n    this.e2eActive = true;\n\n    try {\n      // Join-response pushes and retry-head fetches can arrive while the gate is\n      // closed. Restore their indexed order before opening fresh polling, so a\n      // newer network response cannot overtake the accepted join block.\n      await this.drainE2eChainPending();\n      if(this.e2eFatalError) throw this.e2eFatalError;\n      if(!this.e2e || !this.e2eActive) {\n        throw new Error('Conference was closed while activating encryption');\n      }\n\n      this.syncConferenceMembersFromStatus();\n\n      // Opening the flush gate only after the complete accepted backlog has\n      // drained ensures pullOutbound sees the final verification round, not an\n      // intermediate commit from the first buffered main block.\n      this.e2eActivating = false;\n      this.startE2eChainPolling();\n      if(this.e2eOutboundFlushRequested) void this.flushE2eOutbound();\n    } catch(err) {\n      this.e2eActive = false;\n      this.stopE2eChainPolling();\n      throw err;\n    } finally {\n      this.e2eActivating = false;\n    }\n  }\n\n  // ===== TdE2E chain polling =====\n  //\n  // Mirrors tdlib's per-subchain polling (TdE2E::Call::shortPoll). Both\n  // subchains advance independently; we keep the next-offset cursor per\n  // subchain and re-issue `phone.getGroupCallChainBlocks` on a slow tick.\n  // The push from `updateGroupCallChainBlocks` advances the cursor too.\n  private e2eChainPollInterval: ReturnType<typeof setInterval> | undefined;\n  private e2eChainOffsets: {0: number; 1: number} = {0: 0, 1: 0};\n  private e2eChainPending: {0: Map<number, Uint8Array>; 1: Map<number, Uint8Array>} = {\n    0: new Map(),\n    1: new Map()\n  };\n\n  /** Seed already-applied subchain cursors before attachE2e starts polling. */\n  public seedE2eChainOffsets(offsets: Partial<{0: number; 1: number}>): void {\n    if(this.e2e) {\n      this.log.warn('seedE2eChainOffsets: ignored after e2e attach');\n      return;\n    }\n\n    ([0, 1] as const).forEach((subChainId) => {\n      const offset = offsets[subChainId];\n      if(Number.isSafeInteger(offset) && offset >= 0) {\n        this.e2eChainOffsets[subChainId] = offset;\n      }\n    });\n  }\n\n  /**\n   * Buffer the identity-checked chain slices returned by the accepted join RPC.\n   * Unlike an arbitrary push, that response is authoritative for the initial\n   * verification cursor and may contain only Telegram's retained tail.\n   */\n  public deliverAcceptedE2eJoinChainBlocks(\n    subChainId: number,\n    blocks: Uint8Array[],\n    nextOffset: number\n  ): Promise<boolean> {\n    if(!this.e2e || this.e2eActive) {\n      this.log.warn('deliverAcceptedE2eJoinChainBlocks: ignored outside the pre-activation gate');\n      return Promise.resolve(false);\n    }\n\n    const requestedOffset = subChainId === 0 || subChainId === 1 ?\n      this.e2eChainOffsets[subChainId] :\n      0;\n    if(!this.isValidE2eChainBatch(subChainId, blocks, nextOffset, requestedOffset)) {\n      return Promise.resolve(false);\n    }\n\n    const firstOffset = nextOffset - blocks.length;\n    if(subChainId === 1 && requestedOffset === 0 && firstOffset > 0) {\n      this.log('conference: anchored accepted join verification tail at', firstOffset);\n      this.advanceE2eChainOffsets({1: firstOffset});\n    }\n\n    return this.deliverE2eChainBlocks(subChainId, blocks, nextOffset);\n  }\n\n  /**\n   * Move already-attached cursors forward after a join retry re-anchors the\n   * worker on a newer chain tip. Older buffered blocks belong to the abandoned\n   * proposal and must not be applied to the replacement anchor.\n   */\n  public advanceE2eChainOffsets(offsets: Partial<{0: number; 1: number}>): void {\n    ([0, 1] as const).forEach((subChainId) => {\n      const offset = offsets[subChainId];\n      if(!Number.isSafeInteger(offset) || offset < this.e2eChainOffsets[subChainId]) return;\n      this.e2eChainOffsets[subChainId] = offset;\n      const pending = this.e2eChainPending[subChainId];\n      for(const pendingOffset of pending.keys()) {\n        if(pendingOffset < offset) pending.delete(pendingOffset);\n      }\n    });\n  }\n\n  // The one member-set change detector for both the worker `status` listener\n  // and activation. Cheap string-key diff avoids re-polling on unrelated status\n  // churn (e.g. emoji verification phases). On a change it re-syncs the SFU\n  // roster AND re-arms any unmapped-SSRC resolutions that were parked waiting\n  // for exactly this: their owner's chain block applying locally.\n  private syncConferenceMembersFromStatus(): void {\n    const members = (this.e2eStatus?.groupState?.participants || [])\n    .map((participant) => participant.userId.toString())\n    .sort()\n    .join(',');\n    if(members === this.prevConferenceMembers) return;\n    this.prevConferenceMembers = members;\n    this.kickE2eMembershipResolutions();\n    void this.refreshConferenceParticipants();\n  }\n\n  // Re-arm parked unmapped-SSRC resolutions once the e2e group_state gains\n  // members — the condition their targeted lookup deterministically failed on.\n  private kickE2eMembershipResolutions(): void {\n    let kicked = false;\n    for(const state of this.e2eSourceResolutions.values()) {\n      if(!state.awaitingMembership) continue;\n      state.awaitingMembership = false;\n      state.membershipRetries = (state.membershipRetries ?? 0) + 1;\n      state.attempts = 1;\n      state.retry = true;\n      kicked = true;\n    }\n    if(kicked) this.drainE2eSourceResolutions();\n  }\n\n  // Conference participant reconciliation (see refreshConferenceParticipants).\n  // `prevConferenceMembers` is the last e2e group_state member set we synced;\n  // the periodic timer is a backstop for changes the blockchain doesn't surface\n  // promptly (e.g. an ungraceful disconnect that the SFU drops before a removal\n  // block lands). `refreshingConferenceParticipants` de-dupes overlapping runs.\n  private prevConferenceMembers = '';\n  private conferenceParticipantsInterval: ReturnType<typeof setInterval> | undefined;\n  private refreshingConferenceParticipants = false;\n  private selfParticipantHydrationRequested = false;\n  // Consecutive polls that came back with an incomplete roster. Reset by any\n  // complete one; drives the breadcrumb above.\n  private incompleteRosterPolls = 0;\n  // Consecutive GROUPCALL_INVALID answers across the conference API paths.\n  private consecutiveCallInvalid = 0;\n  // Height owns the outbound commit/reveal queue for the current verification\n  // round. A newer height invalidates queued broadcasts from the old round.\n  private verificationRoundHeight: number | undefined;\n\n  // ===== Chain-only members (blockchain ↔ SFU roster reconciliation) =====\n  //\n  // Authenticated e2e members that a COMPLETE SFU roster doesn't list. They\n  // hold the current shared key, so tdlib's Encryption.md requires us to show\n  // them; the protocol additionally requires removing them and rotating the key\n  // (`only_left` pruning). See conferenceMembership.ts for the full rationale.\n  //\n  // Client-side synthetic participants: never saved into the manager cache,\n  // never dispatched as `group_call_participant`, `source: 0` so no SSRC map\n  // ever sees them.\n  private membersWithAccess: Map<PeerId, GroupCallParticipant> = new Map();\n  // user_id → when we first saw it missing, for the grace window.\n  private staleSince: Map<string, number> = new Map();\n  private pruningConferenceMembers = false;\n  private lastPruneAttemptAt: number | undefined;\n  private consecutivePruneFailures = 0;\n  // Set once the media path could not be secured — see failE2eTransform.\n  private failedE2eTransform = false;\n  // Recovery triggers can arrive concurrently from the worker, chain polling,\n  // roster refresh, pruning and verification broadcast. Request one\n  // controller-owned rejoin and stop this instance's traffic immediately.\n  private conferenceRecoveryDispatched = false;\n\n  // ===== Conference-sync watchdog =====\n  //\n  // Both conference pollers (pollE2eChain, refreshConferenceParticipants) bail\n  // SILENTLY when our cached `groupCall` is missing/discarded — getGroupCallInput\n  // throws without it. If that state persists, media keeps flowing but the call\n  // stops learning about unmutes/joins: a participant who unmutes is seen (SFU\n  // speaking signal is plaintext) but not heard — their audio SSRC never enters\n  // the e2e recv map, so the recv transform drops them (silence). Observed\n  // live: a ~19-minute stall that only cleared on a manual re-join. These track\n  // when each poller last actually REACHED the server; the watchdog re-hydrates\n  // `groupCall` and re-kicks the pollers when either goes stale.\n  private lastChainPollAt = 0;\n  private lastParticipantsRefreshAt = 0;\n  private lastPollBailReason = '';\n  private e2eWatchdogInterval: ReturnType<typeof setInterval> | undefined;\n  private recoveringConferenceSync = false;\n  private unproductiveSyncRecoveries = 0;\n  // Cooldown (per reason) for the user-facing bug breadcrumb — see reportConferenceBug.\n  private reportedBugAt: Map<string, number> = new Map();\n\n  private startE2eChainPolling(): void {\n    if(this.e2eChainPollInterval) return;\n    // Seed the watchdog clocks so it grants a full stall window before the\n    // first successful poll lands (invitee/slug joins hydrate `groupCall`\n    // lazily — see pollE2eChain).\n    this.lastChainPollAt = this.lastParticipantsRefreshAt = performance.now();\n    const tick = (): void => { void this.pollE2eChain(); };\n    // Immediate kick — tdlib does this in `joined()`.\n    tick();\n    // Steady-state interval: 1500ms is a balance between latency for emoji\n    // verification (commit/reveal needs both peers' broadcasts) and load.\n    this.e2eChainPollInterval = setInterval(tick, 1500);\n\n    // Backstop SFU participant poll. The blockchain-change trigger (in the\n    // worker `status` handler) covers the common join/leave case; this catches\n    // anything that changes the SFU roster without a chain delta. 5s matches\n    // the official Android conference poll cadence.\n    if(!this.conferenceParticipantsInterval) {\n      this.conferenceParticipantsInterval = setInterval(() => {\n        void this.refreshConferenceParticipants();\n      }, 5000);\n    }\n\n    // Watchdog: detect + self-heal a silent poller stall (see field comment).\n    if(!this.e2eWatchdogInterval) {\n      this.e2eWatchdogInterval = setInterval(() => {\n        this.e2eWatchdogTick();\n      }, E2E_WATCHDOG_INTERVAL_MS);\n    }\n  }\n\n  private stopE2eChainPolling(): void {\n    if(this.e2eChainPollInterval) {\n      clearInterval(this.e2eChainPollInterval);\n      this.e2eChainPollInterval = undefined;\n    }\n    if(this.conferenceParticipantsInterval) {\n      clearInterval(this.conferenceParticipantsInterval);\n      this.conferenceParticipantsInterval = undefined;\n    }\n    if(this.e2eWatchdogInterval) {\n      clearInterval(this.e2eWatchdogInterval);\n      this.e2eWatchdogInterval = undefined;\n    }\n  }\n\n  private requestConferenceRecoveryForForbidden(reason: string, err: unknown): boolean {\n    if((err as ApiError)?.type !== 'GROUPCALL_FORBIDDEN') return false;\n    this.requestConferenceRecovery(reason);\n    return true;\n  }\n\n  private requestConferenceRecovery(reason: string): void {\n    if(this.conferenceRecoveryDispatched) return;\n\n    this.conferenceRecoveryDispatched = true;\n    this.e2eActive = false;\n    this.e2eOutboundFlushRequested = false;\n    this.e2eOutboundQueue.length = 0;\n    this.stopE2eChainPolling();\n    this.log.warn('conference recovery required — requesting full rejoin', {reason});\n    this.dispatchEvent('conferenceRecoveryRequired', reason);\n  }\n\n  public requestSelfParticipantHydration(): void {\n    if(this.participant?.pFlags.self) {\n      this.selfParticipantHydrationRequested = false;\n      return;\n    }\n    this.selfParticipantHydrationRequested = true;\n    void this.refreshConferenceParticipants();\n  }\n\n  // Reconcile the SFU participant roster + count for a conference. No-op for\n  // legacy voice chats (gated on `this.e2e`) and while closed. The heavy\n  // lifting (fresh fetch, leave reconciliation, count) lives in the manager;\n  // here we just guard against overlapping runs and a torn-down call.\n  private async refreshConferenceParticipants(): Promise<void> {\n    if(!this.e2e || this.conferenceRecoveryDispatched || this.refreshingConferenceParticipants) return;\n    if(this.connectionState === 'closed') return;\n    this.refreshingConferenceParticipants = true;\n    try {\n      // `false` => the manager bailed (no cached groupCall), so the roster sync\n      // isn't actually running. Only stamp the watchdog clock on a real fetch.\n      const includeSelf = this.selfParticipantHydrationRequested && !this.participant?.pFlags.self;\n      // Hand the manager our live audio source so it can drop a self row from a\n      // lagging server snapshot instead of feeding it to the self-source kill\n      // switch in onParticipantUpdate (which would end the whole call).\n      const selfSource = this.connections.main?.sources?.audio?.source;\n      const fetched = await this.managers.appGroupCallsManager.refreshConferenceParticipants(\n        this.id,\n        includeSelf ? {includeSelf: true, ...(selfSource !== undefined ? {selfSource} : {})} : undefined\n      );\n      if(!fetched) {\n        return;\n      }\n\n      if(this.participant?.pFlags.self) {\n        this.selfParticipantHydrationRequested = false;\n      }\n\n      this.lastParticipantsRefreshAt = performance.now();\n      // A truncated roster can't tell \"absent\" from \"on a page we never got\", so\n      // it must never drive the access list or a removal.\n      if(fetched.complete) {\n        this.incompleteRosterPolls = 0;\n        await this.reconcileConferenceMembership(fetched.userIds);\n      } else if(++this.incompleteRosterPolls >= INCOMPLETE_ROSTER_POLLS_BEFORE_REPORT) {\n        // Skipping reconciliation is the SAFE response to one truncated roster,\n        // but it is also exactly what a backend wants if it is hiding a chain\n        // participant: no disclosure, no only_left rekey, no noise. A roster\n        // that never completes is not a quiet condition — say so, and keep\n        // saying it, rather than letting the defence stay silently disabled.\n        this.incompleteRosterPolls = 0;\n        this.reportConferenceBug(\n          'the call server will not return a complete participant list — who holds the call key cannot be verified',\n          {userIds: fetched.userIds.length}\n        );\n      }\n    } catch(err) {\n      if(this.requestConferenceRecoveryForForbidden('roster-forbidden', err)) return;\n      this.log.warn('refreshConferenceParticipants', err);\n      this.noteConferenceApiResult(err);\n    } finally {\n      this.refreshingConferenceParticipants = false;\n    }\n  }\n\n  /**\n   * Compare authenticated e2e membership against the complete SFU roster.\n   *\n   * The blockchain is the access list: a participant in `group_state` holds the\n   * current shared key whether or not the server lists them. So anyone on the\n   * chain but off the roster is (a) surfaced to the user right away and (b)\n   * scheduled for the protocol's `only_left` removal, which rotates the key\n   * away from them. Doing only (b) would leave the user blind whenever the\n   * removal is refused; doing only (a) would leave the key shared forever.\n   */\n  private async reconcileConferenceMembership(rosterUserIds: string[]): Promise<void> {\n    const {e2eStatus, selfUserId} = this;\n    if(!this.e2e || !e2eStatus || selfUserId === undefined) return;\n    if(this.connectionState === 'closed') return;\n\n    const chainOnly = findChainOnlyMembers({\n      participants: e2eStatus.groupState.participants,\n      rosterUserIds,\n      selfUserId\n    });\n\n    // Publish BEFORE the grace window: an identity with call access is shown\n    // the moment it's known, and stays shown until the removal AND its rotated\n    // key have actually been accepted (this recomputes off group_state, so the\n    // row clears itself once the removal block lands).\n    this.publishMembersWithAccess(chainOnly);\n\n    // Age each identity. Rebuilding the map drops anyone who reappeared on the\n    // roster, so a member who flaps starts their window over rather than\n    // accumulating time towards removal.\n    const now = performance.now();\n    const staleSince = new Map<string, number>();\n    const prunable: bigint[] = [];\n    for(const userId of chainOnly) {\n      const key = userId.toString();\n      const since = this.staleSince.get(key) ?? now;\n      staleSince.set(key, since);\n      if(now - since >= CONFERENCE_STALE_GRACE_MS) {\n        prunable.push(userId);\n      }\n    }\n    this.staleSince = staleSince;\n\n    if(!prunable.length || this.pruningConferenceMembers) return;\n    if(this.lastPruneAttemptAt !== undefined &&\n       now - this.lastPruneAttemptAt < CONFERENCE_PRUNE_RETRY_MS) return;\n\n    // Detached on purpose: this runs inside the roster poller's\n    // `refreshingConferenceParticipants` guard, and a removal RPC that never\n    // settles (dead connection) would otherwise wedge the roster refresh for\n    // the rest of the call. `pruningConferenceMembers` guards overlap instead.\n    void this.pruneConferenceMembers(prunable);\n  }\n\n  // Swap in the chain-only set and tell the UI, but only on a real change —\n  // this runs on every roster poll.\n  private publishMembersWithAccess(userIds: bigint[]): void {\n    const next = new Map<PeerId, GroupCallParticipant>();\n    for(const userId of userIds) {\n      const peerId = conferenceUserIdToPeerId(userId);\n      // validateGroupState rejects user_ids that are not positive, so on a\n      // validated chain this never fires — but the row list would read 0 as\n      // ourselves (getParticipantByPeerId's NULL_PEER_ID branch) and a negative\n      // id as a chat, naming the wrong party as the key holder. Report instead\n      // of rendering; the identity still goes through the exact-id removal.\n      if(peerId === NULL_PEER_ID || !peerId.isUser()) {\n        this.reportConferenceBug(\n          'an e2e member id cannot be shown as a user — it would render as ourselves or as a chat',\n          {peerId, userIds: userIds.map(String)}\n        );\n        continue;\n      }\n\n      // The roster list is keyed by PeerId, so two chain ids that round to the\n      // same one (only possible above 2^53 — see conferenceMembership.ts) can\n      // only ever be ONE row. Removal still covers both, since that works off\n      // exact ids, but one identity would go undisclosed until it lands. Real\n      // user ids are nowhere near that range, so this means the server is\n      // feeding us ids no real account has: say so rather than show one row.\n      if(next.has(peerId)) {\n        this.reportConferenceBug(\n          'two e2e members share one displayed peer — one of them cannot be shown',\n          {peerId, userIds: userIds.map(String)}\n        );\n        continue;\n      }\n\n      // Reuse the existing synthetic so the row keeps its identity (and its\n      // sort index) across polls.\n      next.set(peerId, this.membersWithAccess.get(peerId) ?? this.makeMemberWithAccess(userId));\n    }\n\n    const previous = [...this.membersWithAccess.keys()];\n    const unchanged = next.size === previous.length && previous.every((peerId) => next.has(peerId));\n\n    // Nothing to show and nothing shown — the common case, stay quiet.\n    if(unchanged && !next.size) {\n      return;\n    }\n\n    this.membersWithAccess = next;\n    // Only announce a genuine change; re-dispatching below is repair, not news.\n    if(next.size && !unchanged) {\n      this.log.warn(\n        'conference: e2e members absent from the SFU roster —', [...next.keys()],\n        '— they hold the current call key; showing them and scheduling removal'\n      );\n    }\n\n    // Re-assert on every poll even when the set is identical. The disclosure is\n    // a security claim, and anything that drops one of these rows — a server\n    // `left` push racing the roster, a list rebuild — would otherwise never be\n    // undone, because \"set unchanged\" used to mean \"don't touch the UI\". The\n    // set is tiny and this only runs while it is non-empty.\n    this.dispatchEvent('membersWithAccess', {current: [...next.keys()], previous});\n  }\n\n  // The roster UI renders chain-only members through the same row widget as\n  // real participants (tdesktop does the same via `updateStateWithAccess`), so\n  // give it the minimal participant shape: muted, no video, `date: 0` so the\n  // descending sort parks them below everyone actually connected.\n  private makeMemberWithAccess(userId: bigint): GroupCallParticipant {\n    return {\n      _: 'groupCallParticipant',\n      peer: {_: 'peerUser', user_id: userId.toString()},\n      pFlags: {muted: true, can_self_unmute: true},\n      source: 0,\n      date: 0\n    };\n  }\n\n  // Build + submit the `only_left` removal. The block carries both the trimmed\n  // group_state and a fresh shared key addressed only to the survivors, so the\n  // removed identity can't decrypt anything past it.\n  private async pruneConferenceMembers(userIds: bigint[]): Promise<void> {\n    const input = this.toInputGroupCall();\n    // Re-check both here, not just at the reconcile call site: this runs\n    // detached, so anything thrown escapes as an unhandled rejection rather\n    // than reaching a caller.\n    if(!input || !this.e2e) return;\n\n    this.pruningConferenceMembers = true;\n    this.lastPruneAttemptAt = performance.now();\n    let ids = userIds.map(String);\n    try {\n      // The worker reads the current state only when this request reaches its\n      // serialized queue, after any already-queued applyBlock. It returns the\n      // exact identities represented by the block so RPC ids and key rotation\n      // can never describe different membership deltas.\n      const removal = await this.e2e.buildRemoveParticipantsBlock({userIds});\n      if(!removal) return;\n      const {block, removedUserIds} = removal;\n      ids = removedUserIds.map(String);\n\n      await this.managers.appCallsManager.deleteConferenceCallParticipants({\n        call: input,\n        ids,\n        block,\n        onlyLeft: true\n      });\n\n      this.consecutivePruneFailures = 0;\n      this.log('conference: removed stale e2e members + rotated the key —', ids);\n    } catch(err) {\n      const type = (err as ApiError)?.type as string | undefined;\n      if(this.requestConferenceRecoveryForForbidden('member-prune-forbidden', err)) return;\n      ++this.consecutivePruneFailures;\n\n      // The chain moved under us between build and submit (someone joined or\n      // another client pruned first). Benign — our own state advances with the\n      // new block and the next pass rebuilds on top of it.\n      if(type === 'CONF_WRITE_CHAIN_INVALID' || type === 'BLOCK_INVALID') {\n        this.log('conference: removal raced the chain, retrying next pass —', type);\n      } else {\n        this.log.error('conference: removal failed', err);\n      }\n\n      // Persistent refusal while the identity keeps holding the key is the\n      // shape a hostile relay would take, so make sure it leaves a trace.\n      if(this.consecutivePruneFailures >= CONFERENCE_PRUNE_FAILURES_BEFORE_REPORT) {\n        this.reportConferenceBug(\n          'could not remove e2e members that are absent from the call roster (they still hold the call key)',\n          {ids, error: type || String(err), attempts: this.consecutivePruneFailures}\n        );\n      }\n    } finally {\n      this.pruningConferenceMembers = false;\n    }\n  }\n\n  /** Peers on the e2e chain that the SFU roster doesn't list. */\n  public get memberWithAccessPeerIds(): PeerId[] {\n    return [...this.membersWithAccess.keys()];\n  }\n\n  /** Whether this row is a chain-only member rather than a real participant. */\n  public isMemberWithAccess(peerId: PeerId): boolean {\n    return this.membersWithAccess.has(peerId);\n  }\n\n  private async pollE2eChain(): Promise<void> {\n    if(!this.e2e || this.conferenceRecoveryDispatched) return;\n    // Lazy-hydrate `groupCall` for invitee paths (slug / inviteMessage join):\n    // the join response carries `updateGroupCall` with the real id+access_hash\n    // and the manager caches it, but the instance's own `groupCall` reference\n    // wasn't set during joinConferenceCommon (we didn't have the id yet).\n    // Pull from the cache here once it lands.\n    if(!this.groupCall) {\n      const cached = await this.managers.appGroupCallsManager\n      .getGroupCall(this.id)\n      .catch((): undefined => undefined);\n      if(cached && cached._ === 'groupCall') {\n        this.groupCall = cached;\n        // For invitee/slug joins the real groupCall (with participants_count,\n        // title, …) only lands here, AFTER the topbar/popup first rendered off\n        // an undefined ref (showing the \"1\" fallback count). The hydration\n        // itself fires no event, so nudge a re-render — otherwise the count\n        // stays frozen at 1 until the next unrelated state/participant change.\n        this.dispatchEvent('state', this.state);\n      }\n    }\n    const input = this.toInputGroupCall();\n    if(!input) {\n      // The silent stall the watchdog exists for. Trace it on transition.\n      this.notePollBail(this.groupCall ? 'groupCall discarded' : 'groupCall missing');\n      return;\n    }\n    this.notePollBail('');\n    // Poll both subchains in parallel. Each returns the slice from\n    // `offset` onward; we advance `offset` by the number of blocks returned.\n    // Outcomes: 'matched' — a cursor-bound slice was validated and delivered;\n    // 'bare' — the server answered our call-bound request without echoing a\n    // chain update (an empty mailbox shape tdlib/tdesktop accept as a healthy\n    // answer — deriving a stall from it would churn the watchdog forever);\n    // 'failed' — error, ambiguous container, or a slice that failed validation\n    // (e.g. a cursor gap), which the watchdog must keep seeing as a stall so\n    // its escalation can re-anchor via a full rejoin.\n    const outcomes = await Promise.all([0, 1].map(async(sub): Promise<'matched' | 'bare' | 'failed'> => {\n      const subChainId = sub as 0 | 1;\n      try {\n        // Bind the response to the exact cursor sent on this request. A push can\n        // advance the live cursor while the RPC is in flight, so validating\n        // against the later mutable value would reject an otherwise sound\n        // response (or accept a batch that never answered this request).\n        const requestedOffset = this.e2eChainOffsets[subChainId];\n        const updates = await this.managers.appCallsManager.getGroupCallChainBlocks(\n          input,\n          subChainId,\n          requestedOffset,\n          // limit must be > 0 — server doesn't auto-pick a default. Pull a\n          // generous window so we catch any backlog from a brief disconnect\n          // but small enough to stay cheap.\n          16\n        );\n        const chainUpdate = findGroupCallChainUpdate(updates, subChainId, input);\n        if(!chainUpdate) {\n          // Keep ordinary update side effects either way. A truly bare answer\n          // (no chain update for this subchain at all) still proves\n          // reachability and call recognition — the server answered our\n          // call-bound request without an error — but an answer that carries\n          // this subchain's update for a DIFFERENT call identity is not ours\n          // to trust and must not feed the liveness clock.\n          await this.managers.apiUpdatesManager.processUpdateMessage(updates);\n          this.log.warn('pollE2eChain: response had no matching update for subchain', subChainId);\n          const hasForeignChainUpdate = getUpdatesList(updates).some((update) => {\n            return update._ === 'updateGroupCallChainBlocks' && update.sub_chain_id === subChainId;\n          });\n          return hasForeignChainUpdate ? 'failed' : 'bare';\n        }\n\n        // A poll has one cursor and therefore exactly one authoritative slice.\n        // Reject an ambiguous container before the ordinary pipeline can echo a\n        // second, unvalidated matching update back through the push listener.\n        const nextMatchingChainUpdate = updates._ === 'updates' || updates._ === 'updatesCombined' ?\n          findGroupCallChainUpdate({\n            ...updates,\n            updates: updates.updates.filter((update) => update !== chainUpdate)\n          }, subChainId, input) :\n          undefined;\n        if(nextMatchingChainUpdate) {\n          this.log.warn('pollE2eChain: response had multiple matching updates for subchain', subChainId);\n          return 'failed';\n        }\n\n        const blocks = chainUpdate.blocks || [];\n        if(!this.isValidE2eChainBatch(subChainId, blocks, chainUpdate.next_offset, requestedOffset)) {\n          // Do not pass this container through the ordinary Updates pipeline:\n          // AppCallsManager would echo the rejected chain slice back to this\n          // instance as a push, bypassing the request-bound validation below.\n          this.log.warn('pollE2eChain: rejected malformed response for subchain', subChainId);\n          return 'failed';\n        }\n\n        // Keep all ordinary update side effects, including updateGroupCall,\n        // once the identity-proven chain slice is structurally sound.\n        await this.managers.apiUpdatesManager.processUpdateMessage(updates);\n        const accepted = await this.deliverE2eChainBlocks(\n          subChainId,\n          blocks,\n          chainUpdate.next_offset,\n          requestedOffset\n        );\n        if(accepted) {\n          this.noteConferenceApiResult();\n          return 'matched';\n        }\n        this.log.warn('pollE2eChain: rejected response for subchain', subChainId);\n        return 'failed';\n      } catch(err) {\n        if(this.requestConferenceRecoveryForForbidden('chain-forbidden', err)) return 'failed';\n        // Transient errors are expected (network blips, brief auth churn).\n        // Log and let the next tick retry.\n        this.log.warn('pollE2eChain: subchain', subChainId, err);\n        this.noteConferenceApiResult(err);\n        return 'failed';\n      }\n    }));\n    // Liveness needs BOTH subchains answered without an error or a rejected\n    // slice. A 'bare' answer still counts: the reference clients derive no\n    // stall signal from the echo's shape, and treating it as one kept the\n    // watchdog recovering every few seconds for the whole call.\n    if(outcomes.every((outcome) => outcome !== 'failed')) this.lastChainPollAt = performance.now();\n  }\n\n  /**\n   * Register the outcome of a conference API call.\n   *\n   * GROUPCALL_INVALID means the server does not recognise this call FOR US —\n   * we were removed, or it ended. Every conference path used to swallow it and\n   * retry forever: the chain poll, the roster refresh and the recovery all\n   * logged and moved on. Meanwhile the media already negotiated keeps flowing,\n   * so the call looks alive while the client has silently stopped learning who\n   * is in it — and since the recv transform is fail-closed, anything a peer\n   * starts after that point is never mapped and is dropped. Observed live as\n   * \"I see their video but hear nothing\", with the roster frozen behind it.\n   *\n   * Continuing in that state also means showing an encrypted-call UI whose\n   * access list we can no longer verify, which is exactly what this stack is\n   * supposed to refuse to do. Surface it and leave.\n   */\n  private noteConferenceApiResult(err?: unknown): void {\n    const type = (err as ApiError)?.type as string | undefined;\n    if(type !== 'GROUPCALL_INVALID') {\n      // Any answer that is not \"this call is not yours\" clears the streak,\n      // including ordinary network failures — those are the transient case the\n      // pollers already retry through.\n      if(!err || type) this.consecutiveCallInvalid = 0;\n      return;\n    }\n\n    if(++this.consecutiveCallInvalid < CALL_INVALID_ANSWERS_BEFORE_LEAVING) {\n      return;\n    }\n\n    this.consecutiveCallInvalid = 0;\n    this.reportConferenceBug(\n      'the call server no longer recognises this call — leaving rather than showing an encrypted call we cannot verify',\n      {callId: String(this.id)}\n    );\n    this.hangUpAfterFatalFailure();\n  }\n\n  // Transition-logged bail tracing for pollE2eChain — logs once when the chain\n  // poll starts (or stops) being unable to reach the server, not every tick.\n  private notePollBail(reason: string): void {\n    if(reason === this.lastPollBailReason) return;\n    const wasBailing = !!this.lastPollBailReason;\n    this.lastPollBailReason = reason;\n    if(reason) this.log.warn('pollE2eChain: not polling —', reason);\n    else if(wasBailing) this.log('pollE2eChain: reached server, resuming');\n  }\n\n  // Runs on E2E_WATCHDOG_INTERVAL_MS. If either conference poller hasn't reached\n  // the server within E2E_SYNC_STALL_MS while the call is alive, force recovery.\n  private e2eWatchdogTick(): void {\n    if(!this.e2e || this.connectionState === 'closed' || this.recoveringConferenceSync) return;\n    const now = performance.now();\n    const chainStall = now - this.lastChainPollAt;\n    const participantsStall = now - this.lastParticipantsRefreshAt;\n    if(chainStall < E2E_SYNC_STALL_MS && participantsStall < E2E_SYNC_STALL_MS) return;\n\n    this.log.warn(\n      'conference sync stalled — chainPoll', Math.round(chainStall / 1000) + 's ago,',\n      'participants', Math.round(participantsStall / 1000) + 's ago;',\n      'lastBail:', this.lastPollBailReason || '(none)', '— forcing recovery'\n    );\n    this.reportConferenceBug('conference sync stalled (pollers not reaching the server)', {\n      chainStallSec: Math.round(chainStall / 1000),\n      participantsStallSec: Math.round(participantsStall / 1000),\n      lastBail: this.lastPollBailReason || '(none)'\n    });\n    this.recoverConferenceSyncDetached('conference watchdog recovery failed');\n  }\n\n  private recoverConferenceSyncDetached(context: string): void {\n    void this.recoverConferenceSync().catch((err) => {\n      this.log.error(context, err);\n    });\n  }\n\n  // Deduped diagnostic for the \"I can't hear someone / had to re-join\" class of\n  // conference bug. The regular logger retains it for exported logs without\n  // adding production globals or a separate console reporting path.\n  private reportConferenceBug(reason: string, details: Record<string, unknown>): void {\n    const monotonicNow = performance.now();\n    const lastReportedAt = this.reportedBugAt.get(reason);\n    if(lastReportedAt !== undefined && monotonicNow - lastReportedAt < 60000) return;\n    this.reportedBugAt.set(reason, monotonicNow);\n\n    const payload = {reason, at: new Date().toISOString(), callId: String(this.id), ...details};\n    this.log.error('CONFERENCE BUG —', reason, payload);\n  }\n\n  // Public surface for the controller's media-transport watchdog\n  // (groupCallsController): ICE reached `connected` but the RTCPeerConnection\n  // never did, i.e. the DTLS handshake didn't complete, so no audio/video ever\n  // flows. Reuses the same user-visible breadcrumb + ring-buffer log path.\n  public reportMediaTransportStall(details: Record<string, unknown>): void {\n    this.reportConferenceBug('media transport stalled — ICE connected but DTLS did not complete (no audio/video)', details);\n  }\n\n  // Re-hydrate `groupCall` (the dependency both pollers silently bail on) and\n  // re-kick them. Re-seeds the manager cache from our own copy first, because\n  // once the manager loses the call `getGroupCallInput` throws and getGroupCallFull\n  // can't bootstrap. Guarded against overlapping runs.\n  private async recoverConferenceSync(): Promise<void> {\n    if(this.recoveringConferenceSync) return;\n    this.recoveringConferenceSync = true;\n    try {\n      const chainWasStale = performance.now() - this.lastChainPollAt >= E2E_SYNC_STALL_MS;\n      const participantsWereStale = performance.now() - this.lastParticipantsRefreshAt >= E2E_SYNC_STALL_MS;\n\n      if(this.groupCall && this.groupCall._ === 'groupCall') {\n        await this.managers.appGroupCallsManager.saveGroupCall(this.groupCall)\n        .catch((err) => this.log.warn('recoverConferenceSync: saveGroupCall', err));\n      }\n\n      const fresh = await this.managers.appGroupCallsManager.getGroupCallFull(this.id, true)\n      .catch((err): undefined => {\n        if(!this.requestConferenceRecoveryForForbidden('sync-refresh-forbidden', err)) {\n          this.log.warn('recoverConferenceSync: getGroupCallFull failed', err);\n        }\n        return undefined;\n      });\n      if(this.conferenceRecoveryDispatched) return;\n      if(fresh && fresh._ === 'groupCall') {\n        this.groupCall = fresh;\n      }\n\n      // Re-kick both pollers now that the cache should be warm. They stamp the\n      // watchdog clocks themselves on success, quieting the next tick.\n      await Promise.all([this.pollE2eChain(), this.refreshConferenceParticipants()]);\n\n      // Did this recovery actually unstick the clock(s) it fired for? A local\n      // re-hydrate cannot fix everything (a chain cursor the server compacted\n      // past, a roster it refuses to serve) — after a few unproductive rounds\n      // stop looping and rebuild the call, which re-anchors both.\n      const now = performance.now();\n      const chainStillStale = chainWasStale && now - this.lastChainPollAt >= E2E_SYNC_STALL_MS;\n      const participantsStillStale = participantsWereStale && now - this.lastParticipantsRefreshAt >= E2E_SYNC_STALL_MS;\n      if(chainStillStale || participantsStillStale) {\n        if(++this.unproductiveSyncRecoveries >= UNPRODUCTIVE_SYNC_RECOVERIES_BEFORE_REJOIN) {\n          this.unproductiveSyncRecoveries = 0;\n          this.requestConferenceRecovery('sync-unrecoverable-locally');\n        }\n      } else {\n        this.unproductiveSyncRecoveries = 0;\n      }\n    } finally {\n      this.recoveringConferenceSync = false;\n    }\n  }\n\n  private e2eOutboundQueue: Array<{bytes: Uint8Array; height: number; attempts: number}> = [];\n  private e2eOutboundFlushPromise: Promise<void> | undefined;\n  private e2eOutboundFlushRequested = false;\n\n  private flushE2eOutbound(): Promise<void> {\n    this.e2eOutboundFlushRequested = true;\n    if(!this.e2eActive || this.e2eActivating) return Promise.resolve();\n    if(this.e2eOutboundFlushPromise) return this.e2eOutboundFlushPromise;\n\n    const run = this.flushE2eOutboundLoop().finally(() => {\n      if(this.e2eOutboundFlushPromise !== run) return;\n      this.e2eOutboundFlushPromise = undefined;\n      if(this.e2eOutboundFlushRequested && this.e2e && this.e2eActive) {\n        void this.flushE2eOutbound();\n      }\n    });\n    this.e2eOutboundFlushPromise = run;\n    return run;\n  }\n\n  private async flushE2eOutboundLoop(): Promise<void> {\n    while(this.e2eOutboundFlushRequested && this.e2e && this.e2eActive) {\n      this.e2eOutboundFlushRequested = false;\n      const input = this.toInputGroupCall();\n      if(!input) return;\n\n      try {\n        const messages = await this.e2e.pullOutbound();\n        this.e2eOutboundQueue.push(...messages.map(({bytes, height}) => ({bytes, height, attempts: 0})));\n      } catch(err) {\n        this.log.error('flushE2eOutbound: pullOutbound failed', err);\n        return;\n      }\n\n      while(this.e2eOutboundQueue.length && this.e2e) {\n        const current = this.e2eOutboundQueue[0];\n        const currentHeight = this.e2eStatus?.verification?.height;\n        if(currentHeight !== undefined && current.height !== currentHeight) {\n          this.e2eOutboundQueue.shift();\n          continue;\n        }\n        try {\n          await this.managers.appCallsManager.sendConferenceCallBroadcast(input, current.bytes);\n          // A status event can discard this stale item while the request is in\n          // flight. Do not shift the newer round that replaced it.\n          if(this.e2eOutboundQueue[0] === current) this.e2eOutboundQueue.shift();\n        } catch(err) {\n          if(this.e2eOutboundQueue[0] !== current) continue;\n          if(this.requestConferenceRecoveryForForbidden('broadcast-forbidden', err)) return;\n          ++current.attempts;\n          if(current.attempts >= E2E_OUTBOUND_MAX_ATTEMPTS) {\n            this.e2eOutboundQueue.shift();\n            this.log.error('flushE2eOutbound: broadcast exhausted retries', err);\n            this.reportConferenceBug(\n              'could not publish the e2e verification broadcast after bounded retries',\n              {attempts: current.attempts, error: (err as Error)?.message || String(err)}\n            );\n            continue;\n          }\n\n          const delay = E2E_OUTBOUND_RETRY_BASE_MS * (2 ** (current.attempts - 1));\n          this.log.warn('flushE2eOutbound: broadcast failed, retrying', {attempt: current.attempts, delay}, err);\n          await pause(delay);\n        }\n      }\n    }\n  }\n\n  // Serialises application after each subchain's indexed buffer has restored a\n  // contiguous prefix. Push and poll can arrive in either order; next_offset\n  // is the authoritative index after the last block in each batch.\n  private e2eDeliveryQueue = createSerializedQueue();\n  // Held so cleanup() can detach it from the global rootScope.\n  private chainBlocksListener: ((payload: {callId: GroupCallId; subChainId: number; blocks: Uint8Array[]; nextOffset: number}) => void) | undefined;\n\n  private isValidE2eChainBatch(\n    subChainId: number,\n    blocks: Uint8Array[],\n    nextOffset: number,\n    requestedOffset?: number\n  ): subChainId is 0 | 1 {\n    if(subChainId !== 0 && subChainId !== 1) {\n      this.log.warn('deliverE2eChainBlocks: unknown sub_chain_id', subChainId);\n      return false;\n    }\n    if(!Number.isSafeInteger(nextOffset) || nextOffset < blocks.length) {\n      this.log.warn('deliverE2eChainBlocks: invalid indexed batch', {subChainId, blocks: blocks.length, nextOffset});\n      return false;\n    }\n\n    if(requestedOffset !== undefined) {\n      const firstOffset = nextOffset - blocks.length;\n      // The verification broadcast chain is an append-only mailbox, not the\n      // authenticated main blockchain. Telegram may compact its old broadcasts\n      // and answer the very first offset=0 poll with the retained tail, so its\n      // `next_offset` can be much larger than `blocks.length`. Official clients\n      // anchor that first response at `next_offset - blocks.length`; rejecting\n      // it forever leaves commit/reveal pending and keeps polling offset 0.\n      // Main-chain gaps and every later verification gap remain rejected.\n      const isInitialVerificationTail =\n        subChainId === 1 &&\n        requestedOffset === 0 &&\n        this.e2eChainOffsets[1] === 0 &&\n        firstOffset > 0;\n      // A push can advance the live cursor while this request is in flight.\n      // The response remains usable when its retained slice covers that live\n      // cursor; only its unseen suffix is applied. This is TDLib's\n      // `next_offset - current_offset <= blocks.size()` rule. Also require the\n      // response not to end before the cursor it was requested for, so an old\n      // unrelated slice cannot masquerade as this request's answer.\n      const currentOffset = this.e2eChainOffsets[subChainId];\n      const coversCurrentOffset = nextOffset <= currentOffset ||\n        nextOffset - currentOffset <= blocks.length;\n      const matchesRequest = nextOffset >= requestedOffset && coversCurrentOffset;\n      if(!Number.isSafeInteger(requestedOffset) ||\n         requestedOffset < 0 ||\n         (!matchesRequest && !isInitialVerificationTail)) {\n        this.log.warn('deliverE2eChainBlocks: response does not match requested cursor', {\n          subChainId,\n          blocks: blocks.length,\n          nextOffset,\n          requestedOffset\n        });\n        return false;\n      }\n    } else if(!blocks.length && nextOffset !== this.e2eChainOffsets[subChainId]) {\n      // A push with no data cannot legitimately move (or rewind) the cursor.\n      // Exact empty polls pass their captured requestedOffset above instead.\n      this.log.warn('deliverE2eChainBlocks: empty batch does not confirm current cursor', {\n        subChainId,\n        nextOffset,\n        currentOffset: this.e2eChainOffsets[subChainId]\n      });\n      return false;\n    }\n\n    return true;\n  }\n\n  private deliverE2eChainBlocks(\n    subChainId: number,\n    blocks: Uint8Array[],\n    nextOffset: number,\n    requestedOffset?: number\n  ): Promise<boolean> {\n    if(!this.isValidE2eChainBatch(subChainId, blocks, nextOffset, requestedOffset)) {\n      return Promise.resolve(false);\n    }\n\n    const firstOffset = nextOffset - blocks.length;\n    if(subChainId === 1 && requestedOffset === 0 && this.e2eChainOffsets[1] === 0 && firstOffset > 0) {\n      this.log('conference: anchored initial verification tail at', firstOffset);\n      this.advanceE2eChainOffsets({1: firstOffset});\n    }\n    const pending = this.e2eChainPending[subChainId];\n    for(let i = 0; i < blocks.length; ++i) {\n      const offset = firstOffset + i;\n      if(offset < this.e2eChainOffsets[subChainId] || pending.has(offset)) continue;\n      if(pending.size >= MAX_E2E_PENDING_CHAIN_BLOCKS) {\n        let farthest = offset;\n        for(const candidate of pending.keys()) farthest = Math.max(farthest, candidate);\n        if(farthest <= offset) {\n          this.reportConferenceBug(\n            'the call server announced too many future e2e chain blocks before filling the gap',\n            {subChainId, offset: this.e2eChainOffsets[subChainId], pending: pending.size}\n          );\n          continue;\n        }\n        pending.delete(farthest);\n      }\n      pending.set(offset, blocks[i]);\n    }\n\n    // The queue itself never rejects — one bad batch must not wedge the rest.\n    return this.e2eDeliveryQueue.enqueue(async() => {\n      await this.deliverE2eChainBlocksLocked(subChainId);\n      return true;\n    });\n  }\n\n  private async deliverE2eChainBlocksLocked(subChainId: 0 | 1): Promise<void> {\n    if(!this.e2e || !this.e2eActive) return;\n    const pending = this.e2eChainPending[subChainId];\n    while(this.e2e) {\n      const offset = this.e2eChainOffsets[subChainId];\n      const block = pending.get(offset);\n      if(!block) return;\n\n      try {\n        if(subChainId === 0) {\n          await this.e2e.applyBlock({serverBlock: block});\n        } else {\n          const result = await this.e2e.receiveInbound({serverMessage: block});\n          if(result.disposition === 'dropped') {\n            // Consumed all the same: the cursor MUST move past it. Parking on a\n            // broadcast the buffer refused re-delivered it on every poll and\n            // queued every later honest commit/reveal behind it — one message\n            // from any participant silenced the emoji fingerprint for good.\n            this.reportConferenceBug(\n              'a verification broadcast was dropped (far-future height or buffer overflow)',\n              {offset, height: result.status.height}\n            );\n          }\n        }\n      } catch(err) {\n        if(this.conferenceRecoveryDispatched) return;\n        this.log.error(\n          subChainId === 0 ?\n            'deliverE2eChainBlocks: applyBlock failed' :\n            'deliverE2eChainBlocks: receiveInbound failed',\n          err\n        );\n        // Keep this exact index queued and keep the cursor in place. Advancing\n        // would turn an application failure into a permanently skipped block.\n        // A main-chain failure while the post-accept gate is opening is fatal:\n        // reject the join transaction synchronously so it owns the one rollback\n        // instead of continuing SDP and racing a worker-event leave.\n        if(subChainId === 0 && this.e2eActivating) {\n          this.e2eFatalError ??= err instanceof Error ? err : new Error(String(err));\n          throw this.e2eFatalError;\n        }\n        return;\n      }\n\n      pending.delete(offset);\n      this.e2eChainOffsets[subChainId] = offset + 1;\n    }\n  }\n\n  private drainE2eChainPending(): Promise<void> {\n    return this.e2eDeliveryQueue.enqueue(async() => {\n      await this.deliverE2eChainBlocksLocked(0);\n      await this.deliverE2eChainBlocksLocked(1);\n    });\n  }\n\n  // Attach a recv transform to ONE receiver. Used by the pre-emptive\n  // `addTransceiver` path in groupCallsController — receivers must have\n  // their transform attached BEFORE the codec produces a frame, or Chrome\n  // silently bypasses them (the parallel createEncodedStreams API throws\n  // \"Too late to create encoded streams\" for the same condition).\n  public attachE2eRecvTransform(\n    receiver: RTCRtpReceiver,\n    kind: 'audio' | 'video',\n    channelId = 0\n  ): void {\n    if(!this.e2e || (receiver as any).transform) return;\n    try {\n      receiver.transform = this.e2e.newRtcScriptTransform({direction: 'recv', channelId, kind});\n    } catch(err) {\n      this.failE2eTransform('recv', err);\n    }\n  }\n\n  /**\n   * Fallback for a remote track whose receiver never got a recv transform at\n   * transceiver-creation time (the normal attach point — see onParticipantUpdate).\n   *\n   * Attaching one now is best-effort ONLY: Chrome binds the decoder before the\n   * `track` event fires and silently bypasses a transform attached after that,\n   * so frames from this receiver may never pass through our decryption at all.\n   * That is security-relevant, not just broken audio — media the relay puts on\n   * an SSRC it never signalled would reach the decoder without being\n   * authenticated. The bypass isn't observable from here, so at least make the\n   * condition loud instead of silent.\n   */\n  public attachE2eRecvTransformLate(receiver: RTCRtpReceiver, kind: 'audio' | 'video'): void {\n    // Attached at creation time — the expected path, nothing to say.\n    if(!this.e2e || (receiver as any).transform) return;\n\n    // The decoder may already be consuming this receiver, so a late transform\n    // assignment cannot establish the badge's authentication claim. Stop the\n    // track synchronously, then use the same fail-closed instance path as an\n    // exception during pre-attachment.\n    receiver.track?.stop();\n    this.failE2eTransform(\n      'recv',\n      new Error(`inbound ${kind} track appeared before its e2e transform was attached`)\n    );\n  }\n\n  // A conference whose media path is missing our transforms is not end-to-end\n  // encrypted, whatever the badge in the header says: outbound frames would\n  // reach the SFU as plaintext, and inbound frames would reach the decoder\n  // unauthenticated. There is no safe degraded mode, so an attach failure ends\n  // the call rather than quietly downgrading it — the previous behaviour was to\n  // log and carry on, which shipped the user's microphone in the clear.\n  //\n  // Leaving (not discarding) is the proportionate response: our client can't\n  // secure its own media, but everyone else's call is unaffected. Deferred a\n  // microtask because this fires from inside the sender/transceiver setup loop,\n  // which must not have the connections torn down under it.\n  private failE2eTransform(direction: 'send' | 'recv', err: unknown): void {\n    this.log.error(`attachE2e${direction === 'send' ? 'Send' : 'Recv'}Transform`, err);\n    this.reportConferenceBug(\n      'end-to-end encryption could not be attached to the media path — leaving the call',\n      {direction, error: (err as Error)?.message || String(err)}\n    );\n    // Attach runs per sender/receiver, so one broken environment fails it many\n    // times over; tear down once.\n    if(this.failedE2eTransform) return;\n    this.failedE2eTransform = true;\n    queueMicrotask(() => this.hangUpAfterFatalFailure());\n  }\n\n  // Attach a send transform to ONE sender. Called from the streamManager's\n  // `onSenderCreated` hook so we slot the transform between addTransceiver\n  // and replaceTrack — the only window where Chrome will accept it without\n  // silently dropping frames.\n  public attachE2eSendTransform(\n    sender: RTCRtpSender,\n    kind: 'audio' | 'video',\n    channelId = 0\n  ): void {\n    if(!this.e2e || (sender as any).transform) return;\n    try {\n      sender.transform = this.e2e.newRtcScriptTransform({direction: 'send', channelId, kind});\n    } catch(err) {\n      this.failE2eTransform('send', err);\n    }\n  }\n\n  // ssrc ↔ user_id mapping is populated externally as the SFU signals\n  // participants. Push the full table to the worker so its recv transform\n  // can dispatch each frame by `frame.getMetadata().synchronizationSource`.\n  // `sync = false` lets registerE2eUserSsrcGroup batch a whole source group\n  // into ONE worker sync — the sync serializes the ENTIRE table into the\n  // worker's rpc queue (behind crypto ops), so per-source syncs turned one\n  // camera participant into ~8 back-to-back full-table posts at join time.\n  public registerE2eUserSsrc(userId: bigint, ssrc: number, sync = true): boolean {\n    const normalized = fromTelegramSource(ssrc);\n    const current = this.e2eUserBySsrc.get(normalized);\n    if(current === userId) return true;\n\n    // Only NEW keys are capped, and the check runs before anything is mutated.\n    // A rebind cannot grow the map, so capping it there would abandon the\n    // update half-applied — moving the entry's peerId and then returning before\n    // the map write — which is precisely the two-structures-disagree state the\n    // rebind below exists to prevent.\n    if(current === undefined && this.e2eUserBySsrc.size >= MAX_E2E_SSRC_ENTRIES) {\n      // Reclaim dead mappings before refusing a legitimate new one — otherwise\n      // a long call that churns sources would wedge permanently at the ceiling.\n      this.sweepE2eSsrcs();\n    }\n\n    if(current === undefined && this.e2eUserBySsrc.size >= MAX_E2E_SSRC_ENTRIES) {\n      this.reportConferenceBug(\n        'the call server announced more media streams than this call can hold',\n        {ssrc: normalized, size: this.e2eUserBySsrc.size}\n      );\n      return false;\n    }\n\n    // Two structures are built from this same untrusted input and they must\n    // never disagree: this map decides which Ed25519 key verifies the frame,\n    // while the ConferenceEntry for the SSRC carries the peerId that decides\n    // whose tile renders it. The entry is created once and was never re-bound,\n    // so a server pointing a second participant at a live SSRC used to leave\n    // X's genuine, correctly-verified media rendering under Y's name — the\n    // frame is authentic, the attribution is not. Move both together.\n    if(current !== undefined) {\n      // Look the entry up by the RAW source. `entriesBySource` is keyed by the\n      // signed int32 Telegram sends, while this map is keyed unsigned (the recv\n      // transform reads an unsigned SSRC off the frame metadata). Normalising\n      // before the lookup missed every source with the high bit set, so the\n      // rebind below silently never ran for half the SSRC space.\n      const entry = this.description?.getEntryBySource(ssrc);\n      if(entry) {\n        this.description.setEntryPeerId(entry, conferenceUserIdToPeerId(userId));\n      }\n\n      // Reassigning a live SSRC is not something an honest SFU does; the\n      // rebinding above keeps us consistent either way, but leave a breadcrumb.\n      this.reportConferenceBug(\n        'the call server moved one media stream to a different participant',\n        {ssrc: normalized, from: current.toString(), to: userId.toString()}\n      );\n    }\n\n    this.e2eUserBySsrc.set(normalized, userId);\n    if(sync) this.syncSsrcMapToWorker();\n    return true;\n  }\n\n  // Reserve every primary/SIM/FID source for one server-announced media entry\n  // before its ConferenceEntry, transceiver and script transform are created.\n  // A per-source check could accept half a simulcast group at the ceiling,\n  // leaving an allocated decoder whose RTX/layer frames can never authenticate.\n  private registerE2eUserSsrcGroup(userId: bigint, ssrc: Ssrc): boolean {\n    const sources = e2eSourcesOf(ssrc);\n    if(!sources.length) {\n      this.reportConferenceBug('the call server announced a media stream with no valid SSRC', {type: ssrc.type});\n      return false;\n    }\n\n    const countNewSources = () => sources.reduce(\n      (count, source) => count + (this.e2eUserBySsrc.has(fromTelegramSource(source)) ? 0 : 1),\n      0\n    );\n    if(this.e2eUserBySsrc.size + countNewSources() > MAX_E2E_SSRC_ENTRIES) {\n      this.sweepE2eSsrcs();\n    }\n    if(this.e2eUserBySsrc.size + countNewSources() > MAX_E2E_SSRC_ENTRIES) {\n      this.reportConferenceBug(\n        'the call server announced more media streams than this call can hold',\n        {ssrc: fromTelegramSource(ssrc.source), sources: sources.length, size: this.e2eUserBySsrc.size}\n      );\n      return false;\n    }\n\n    const normalizedPrimary = fromTelegramSource(ssrc.source);\n    const indexedEntry = this.description?.getEntryBySource(ssrc.source);\n    const exactEntry = indexedEntry?.type === ssrc.type ? indexedEntry :\n      this.description?.findEntry((entry) => entry.source === ssrc.source && entry.type === ssrc.type);\n    if(indexedEntry && indexedEntry !== exactEntry && indexedEntry.direction !== 'inactive') {\n      this.reportConferenceBug(\n        'the call server assigned one active SSRC to both audio and video',\n        {ssrc: normalizedPrimary, from: indexedEntry.type, to: ssrc.type}\n      );\n      return false;\n    }\n\n    // One RTP m-line is allocated per (primary SSRC, media kind). Encoding the\n    // kind into the key keeps the lifetime cap honest when the SFU legitimately\n    // reuses an inactive audio SSRC for video, or vice versa.\n    const allocationKey = normalizedPrimary * 2 + (ssrc.type === 'video' ? 1 : 0);\n    if(!exactEntry && !this.e2eAllocatedRecvEntries.has(allocationKey) &&\n      this.e2eAllocatedRecvEntries.size >= MAX_E2E_SSRC_ENTRIES) {\n      this.reportConferenceBug(\n        'the call server exhausted the conference media allocation limit',\n        {ssrc: normalizedPrimary, allocations: this.e2eAllocatedRecvEntries.size}\n      );\n      return false;\n    }\n\n    // One worker sync for the whole group — including the early-failure path,\n    // which must still publish the sources already inserted.\n    let changed = false;\n    try {\n      for(const source of sources) {\n        const before = this.e2eUserBySsrc.get(fromTelegramSource(source));\n        if(!this.registerE2eUserSsrc(userId, source, false)) return false;\n        if(before !== userId) changed = true;\n      }\n    } finally {\n      if(changed) this.syncSsrcMapToWorker();\n    }\n    if(!exactEntry) this.e2eAllocatedRecvEntries.add(allocationKey);\n    return true;\n  }\n\n  // Drop mappings that belong to no participant we currently know about.\n  //\n  // Runs only when the table is under pressure, and against the UNION of every\n  // participant's sources rather than one row, so a single stale update can\n  // never un-map a live stream. That is the difference that matters: an\n  // over-eager prune costs silence for the rest of the call, while a delayed\n  // one only costs a few map entries.\n  private sweepE2eSsrcs(): void {\n    if(this.e2eUserBySsrc.size < MAX_E2E_SSRC_ENTRIES) {\n      return;\n    }\n\n    const live = new Set<number>();\n    for(const ssrcs of this.participantsSsrcs.values()) {\n      for(const ssrc of ssrcs) {\n        for(const source of e2eSourcesOf(ssrc)) live.add(fromTelegramSource(source));\n      }\n    }\n\n    let changed = false;\n    for(const source of [...this.e2eUserBySsrc.keys()]) {\n      if(!live.has(source) && this.e2eUserBySsrc.delete(source)) changed = true;\n    }\n\n    if(changed) this.syncSsrcMapToWorker();\n  }\n\n  // Does this SSRC belong to a participant the roster has told us about?\n  //\n  // Distinguishes \"we failed to map a real participant\" (our bug) from \"the\n  // relay is sending media from someone who is not in the call\" (correctly\n  // dropped). Checks the per-participant source lists rather than the key map,\n  // since the key map is exactly what is suspected of being incomplete.\n  private isKnownParticipantSource(source: number): boolean {\n    for(const ssrcs of this.participantsSsrcs.values()) {\n      for(const ssrc of ssrcs) {\n        if(e2eSourcesOf(ssrc).some((candidate) => fromTelegramSource(candidate) === source)) return true;\n      }\n    }\n\n    return false;\n  }\n\n  private resolveUnmappedE2eSource(source: number, sustained: boolean): void {\n    source = normalizeSsrc(source);\n    if(!this.e2e || !this.e2eActive || this.isClosing || this.e2eUserBySsrc.has(source)) return;\n\n    let state = this.e2eSourceResolutions.get(source);\n    if(!state) {\n      if(this.e2eSourceResolutions.size >= MAX_E2E_SSRC_ENTRIES) {\n        this.reportConferenceBug(\n          'the call server announced too many unknown media streams to resolve safely',\n          {sources: this.e2eSourceResolutions.size}\n        );\n        return;\n      }\n      // A sustained diagnostic can arrive after the one-shot state was already\n      // released following its negative lookup. Count that earlier lookup so\n      // the sustained event schedules exactly the one permitted retry.\n      state = {attempts: sustained ? 1 : 0, retry: sustained};\n      this.e2eSourceResolutions.set(source, state);\n    }\n    if(sustained) state.retry = true;\n    this.drainE2eSourceResolutions();\n  }\n\n  private drainE2eSourceResolutions(): void {\n    if(this.e2eSourceResolutionPromise || !this.e2e || !this.e2eActive || this.isClosing) return;\n\n    const sources: number[] = [];\n    for(const [source, state] of this.e2eSourceResolutions) {\n      if(this.e2eUserBySsrc.has(source)) {\n        this.e2eSourceResolutions.delete(source);\n        continue;\n      }\n      if(state.attempts >= 2 || (state.attempts > 0 && !state.retry)) continue;\n\n      // Keep a sustained signal received during the first request as the\n      // permission for one immediate retry. Consuming a retry request happens\n      // only when the second attempt is actually selected.\n      if(state.attempts > 0) state.retry = false;\n      ++state.attempts;\n      sources.push(source);\n      if(sources.length >= GROUP_CALL_PARTICIPANTS_LOAD_LIMIT) break;\n    }\n    if(!sources.length) return;\n\n    const generation = this.lifecycleGeneration;\n    const callId = this.id;\n    // Sources whose row WAS returned but whose user is not yet in the e2e\n    // group_state — the chain block is still in flight. Burning the attempt\n    // budget on this deterministic \"too early\" miss wrote real participants\n    // off forever; park them for the membership-change kick instead.\n    const membershipPending = new Set<number>();\n    const request = this.managers.appGroupCallsManager.getGroupCallParticipantsBySources(callId, sources)\n    .then(async(participants) => {\n      if(generation !== this.lifecycleGeneration || !this.e2e || !this.e2eActive || this.isClosing) return;\n\n      const memberIds = new Set(\n        (this.e2eStatus?.groupState?.participants || []).map((participant) => participant.userId.toString())\n      );\n      const selfUserId = this.selfUserId?.toString();\n      const requestedSources = new Set(sources);\n      const claims = new Map<number, GroupCallParticipant[]>();\n      for(const participant of participants) {\n        if(participant.pFlags.left || participant.pFlags.self || participant.peer?._ !== 'peerUser') continue;\n        const userId = String(participant.peer.user_id);\n        if(userId === selfUserId) continue;\n        const membershipMissing = !memberIds.has(userId);\n\n        const claimed = new Set<number>();\n        for(const ssrc of makeSsrcsFromParticipant(participant)) {\n          for(const participantSource of e2eSourcesOf(ssrc)) {\n            const normalized = fromTelegramSource(participantSource);\n            if(requestedSources.has(normalized)) claimed.add(normalized);\n          }\n        }\n\n        if(membershipMissing) {\n          for(const source of claimed) membershipPending.add(source);\n          continue;\n        }\n\n        for(const source of claimed) {\n          const candidates = claims.get(source) || [];\n          candidates.push(participant);\n          claims.set(source, candidates);\n        }\n      }\n\n      const resolvedParticipants = new Set<GroupCallParticipant>();\n      for(const source of sources) {\n        const candidates = claims.get(source) || [];\n        if(candidates.length > 1) {\n          this.reportConferenceBug(\n            'the call server assigned one unknown media stream to multiple e2e members',\n            {ssrc: source, peers: candidates.map(({peer}) => peer._ === 'peerUser' ? String(peer.user_id) : peer._)}\n          );\n          this.e2eSourceResolutions.delete(source);\n        } else if(candidates.length === 1) {\n          resolvedParticipants.add(candidates[0]);\n        }\n      }\n\n      for(const participant of resolvedParticipants) {\n        if(generation !== this.lifecycleGeneration || !this.e2e || !this.e2eActive || this.isClosing) return;\n        const participantSources = makeSsrcsFromParticipant(participant)\n        .flatMap((ssrc) => e2eSourcesOf(ssrc).map((participantSource) => fromTelegramSource(participantSource)));\n        const requestedSourceWasMapped = () => participantSources.some((participantSource) => {\n          return requestedSources.has(participantSource) && this.e2eUserBySsrc.has(participantSource);\n        });\n        // The ordinary roster path may have resolved this source while the\n        // targeted RPC was in flight. That newer binding wins; publishing this\n        // response could otherwise reassign its key/tile to a stale row.\n        if(requestedSourceWasMapped()) continue;\n        await this.managers.appGroupCallsManager.saveApiParticipant(callId, participant);\n        if(generation !== this.lifecycleGeneration || !this.e2e || !this.e2eActive || this.isClosing) return;\n        if(requestedSourceWasMapped()) continue;\n        // Manager events normally route this row back through the controller.\n        // Apply it directly only if that event has not installed the mapping by\n        // the time the proxy resolves, so the first decrypted frame does not\n        // depend on cross-worker event timing.\n        if(participantSources.some((participantSource) =>\n          requestedSources.has(participantSource) && !this.e2eUserBySsrc.has(participantSource))) {\n          this.onParticipantUpdate(participant);\n        }\n      }\n    })\n    .catch((err) => {\n      if(generation === this.lifecycleGeneration) {\n        if(this.requestConferenceRecoveryForForbidden('source-resolution-forbidden', err)) return;\n        this.log.warn('conference source resolution failed', {ssrcs: sources}, err);\n      }\n    })\n    .finally(() => {\n      if(generation === this.lifecycleGeneration && this.e2e && this.e2eActive && !this.isClosing) {\n        for(const source of sources) {\n          const state = this.e2eSourceResolutions.get(source);\n          if(!state) continue;\n          if(this.e2eUserBySsrc.has(source)) {\n            this.e2eSourceResolutions.delete(source);\n          } else if(membershipPending.has(source) && (state.membershipRetries ?? 0) < MAX_E2E_MEMBERSHIP_RESOLUTION_RETRIES) {\n            // The server names an owner for this source; only their chain block\n            // hasn't applied locally yet. Park until the group_state gains\n            // members instead of writing the stream off.\n            state.awaitingMembership = true;\n            state.retry = false;\n          } else if(state.attempts >= 2) {\n            this.reportConferenceBug(\n              this.isKnownParticipantSource(source) ?\n                'inbound media undecryptable — a participant we know is not in the key map (seen but not heard)' :\n                'the call server is forwarding media from an identity that is not in this call — dropping it',\n              {ssrc: source, attempts: state.attempts}\n            );\n            this.e2eSourceResolutions.delete(source);\n          } else if(!state.retry) {\n            // A first-sighting miss with no sustained signal is complete. Keep\n            // no tombstone: otherwise one-frame foreign SSRCs permanently fill\n            // the bounded table and block resolution of later real streams.\n            this.e2eSourceResolutions.delete(source);\n          }\n        }\n      }\n      if(this.e2eSourceResolutionPromise !== request) return;\n      this.e2eSourceResolutionPromise = undefined;\n      if(generation === this.lifecycleGeneration) this.drainE2eSourceResolutions();\n    });\n    this.e2eSourceResolutionPromise = request;\n  }\n\n  // Replace the SSRC table on the worker side. Cheap enough on every\n  // change — the table is small (one entry per active participant).\n  private syncSsrcMapToWorker(): void {\n    if(!this.e2e) return;\n    const entries: Array<[number, bigint]> = [];\n    for(const [ssrc, userId] of this.e2eUserBySsrc) entries.push([ssrc, userId]);\n    void this.e2e.setSsrcUsers(entries).catch((err) => {\n      this.log.warn('syncSsrcMapToWorker failed', err);\n    });\n  }\n\n  // Convenience: build an InputGroupCall from our cached groupCall payload.\n  // Returns undefined for discarded calls (no access_hash).\n  public toInputGroupCall(): InputGroupCall | undefined {\n    const c = this.groupCall;\n    if(!c || c._ === 'groupCallDiscarded') return undefined;\n    return groupCallToInput(c);\n  }\n\n  get connectionState() {\n    // Optional: `connections.main` only exists from createConnectionInstance\n    // onward, but the conference pollers start earlier — attachE2e kicks them\n    // off, and `worker.init` emits its first `status` (→ roster refresh →\n    // membership reconciliation) before the connection is built. Dereferencing\n    // blindly threw a TypeError there, which surfaced as an unhandled rejection\n    // in the poller and skipped the FIRST reconciliation of the call. Undefined\n    // reads as \"not closed\" below and as CONNECTING in `state`, which is what\n    // that window actually is.\n    return this.connections.main?.connection?.iceConnectionState;\n  }\n\n  get state() {\n    const {connectionState} = this;\n    if(connectionState === 'closed') {\n      return GROUP_CALL_STATE.CLOSED;\n    } else if(connectionState !== 'connected' && (!IS_SAFARI || connectionState !== 'completed')) {\n      return GROUP_CALL_STATE.CONNECTING;\n    } else {\n      const {participant} = this;\n      // Conference invitee paths may reach `connected` before the server\n      // sends our self-participant update (the SFU lists us in the next\n      // `phone.getGroupCallParticipants` reply, which lands after the SDP\n      // exchange completes). Treat \"connected but no self yet\" as MUTED —\n      // we asked to join muted, and waiting for the participant payload\n      // is purely informational.\n      if(!participant) {\n        return GROUP_CALL_STATE.MUTED;\n      }\n      if(!participant.pFlags.can_self_unmute) {\n        return GROUP_CALL_STATE.MUTED_BY_ADMIN;\n      }\n\n      // Only claim UNMUTED if the capture track really is live. This getter\n      // drives the microphone indicator, and it used to trust our own\n      // participant row alone — a row the server supplies and\n      // `saveApiParticipant` replaces wholesale, including swapping the whole\n      // `pFlags` object and synthesising `can_self_unmute` when a minimal row\n      // carries neither flag. A `left` row for our own peer therefore dropped\n      // `muted: true` and flipped the button to \"unmuted\" while the track\n      // stayed disabled: the UI told the user their microphone was open when it\n      // was not. Between the row and the track, the track is the truth.\n      return this.isMuted ? GROUP_CALL_STATE.MUTED : GROUP_CALL_STATE.UNMUTED;\n    }\n  }\n\n  // Whether our own audio is actually being captured and sent. `setMuted`\n  // toggles `track.enabled`, so this is what the microphone indicator must\n  // reflect. Undefined-safe: before the connection exists there is no track,\n  // and \"no track\" is not \"transmitting\".\n  private isCaptureLive(): boolean {\n    const tracks = this.connections.main?.streamManager?.inputStream?.getAudioTracks?.();\n    if(!tracks?.length) {\n      return false;\n    }\n\n    tracks.forEach((track) => this.observeInputAudioTrack(track));\n    return tracks.some((track) => track.enabled && this.isInputTrackAvailable(track));\n  }\n\n  private observeInputAudioTrack(track: MediaStreamTrack | undefined): void {\n    if(!track || this.observedInputAudioTracks.has(track)) return;\n    this.observedInputAudioTracks.add(track);\n\n    const dispatchCaptureState = () => {\n      if(!this.isClosing) this.dispatchEvent('state', this.state);\n    };\n    track.addEventListener('mute', dispatchCaptureState);\n    track.addEventListener('unmute', dispatchCaptureState);\n    track.addEventListener('ended', dispatchCaptureState, {once: true});\n  }\n\n  get participants() {\n    return this.managers.appGroupCallsManager.getCachedParticipants(this.id);\n  }\n\n  get isSharingScreen() {\n    return !!this.connections.presentation;\n  }\n\n  public get joined(): boolean {\n    return this._joined;\n  }\n\n  public set joined(joined: boolean) {\n    if(this._joined === joined) return;\n    this._joined = joined;\n    this.dispatchEvent('state', this.state);\n  }\n\n  /**\n   * Camera/screen runtime mutations are safe only after transport join and the\n   * canonical self participant have both arrived. Changes are observable via\n   * the existing `state` event.\n   */\n  public get isMediaRuntimeReady(): boolean {\n    return this.joined && !!this.participant?.pFlags?.self && !this.isClosing;\n  }\n\n  get pinnedSource() {\n    return this.pinnedSources[this.pinnedSources.length - 1];\n  }\n\n  public get isMuted() {\n    const participant = this.participant;\n    return !participant?.pFlags.can_self_unmute ||\n      !!participant.pFlags.muted ||\n      !this.isCaptureLive();\n  }\n\n  public get isClosing() {\n    const {state} = this;\n    return state === GROUP_CALL_STATE.CLOSED;\n  }\n\n  public get streamManager(): StreamManager {\n    return this.connections.main.streamManager;\n  }\n\n  public get description(): localConferenceDescription {\n    return this.connections.main.description;\n  }\n\n  public pinSource(source: GroupCallOutputSource) {\n    indexOfAndSplice(this.pinnedSources, source);\n    this.pinnedSources.push(source);\n    this.dispatchPinnedThrottled();\n  }\n\n  public unpinSource(source: GroupCallOutputSource) {\n    this.hadAutoPinnedSources.delete(source);\n    indexOfAndSplice(this.pinnedSources, source);\n    this.dispatchPinnedThrottled();\n  }\n\n  public unpinAll() {\n    this.pinnedSources.length = 0;\n    this.dispatchPinnedThrottled();\n  }\n\n  public async getParticipantByPeerId(peerId: PeerId) {\n    if(NULL_PEER_ID === peerId) {\n      return this.participant;\n    }\n\n    // Real SFU rows win: once a chain-only member finally shows up on the\n    // roster, their live state takes over the row in place.\n    return (await this.participants).get(peerId) ?? this.membersWithAccess.get(peerId);\n  }\n\n  public toggleMuted() {\n    return this.requestAudioSource(true).then(() => {\n      // Decide from the capture-backed state, not only participant.pFlags.\n      // A delayed/minimal self row can claim \"unmuted\" while the local track\n      // is still disabled; in that state inverting pFlags sends another mute\n      // and makes it impossible for the user to open their microphone.\n      return this.changeUserMuted(NULL_PEER_ID, !this.isMuted);\n    });\n  }\n\n  public changeUserMuted(peerId: PeerId, muted?: boolean): Promise<void> {\n    if(NULL_PEER_ID === peerId) {\n      return this.selfMuteTransitionTail.enqueue(() => this.changeSelfMuted(muted));\n    }\n\n    return this.changeOtherParticipantMuted(peerId, muted);\n  }\n\n  private async changeOtherParticipantMuted(peerId: PeerId, muted?: boolean): Promise<void> {\n    const participant = await this.getParticipantByPeerId(peerId);\n    await this.editParticipant(participant, {muted});\n  }\n\n  private async changeSelfMuted(muted?: boolean): Promise<void> {\n    const participant = await this.getParticipantByPeerId(NULL_PEER_ID);\n    if(participant.pFlags.can_self_unmute) {\n      muted = muted === undefined ? !participant.pFlags.muted : muted;\n    }\n\n    if(muted === undefined) {\n      await this.editParticipant(participant, {muted});\n      return;\n    }\n\n    // Muting is safety-sensitive: cut capture before the worker/RPC roundtrip.\n    // Unmuting is the inverse transaction — keep every track disabled until\n    // phone.editGroupCallParticipant has actually accepted the change. The\n    // worker update processing is deliberately non-optimistic for this path,\n    // so a revision change while the RPC is in flight proves a newer server\n    // row arrived and must win over any rejection rollback.\n    const participantRevision = this.selfParticipantRevision;\n    const previousPFlags = {...participant.pFlags};\n    if(muted) {\n      // An explicit mute always cancels a still-armed unmute intent.\n      this.pendingUnmuteIntentAt = undefined;\n      this.setMuted(true);\n      this.dispatchEvent('state', this.state);\n    }\n\n    try {\n      await this.editParticipant(participant, {muted}, false);\n      // When no self row landed during the RPC, the accepted state lives on\n      // `participant` (editParticipant already applied the accepted pFlags to\n      // it) — trust it. When a row DID land, the newest row wins so a genuinely\n      // newer admin mute stays fail-closed; if that row is a stale \"muted\" echo\n      // computed before our acceptance, the armed intent below lets the next\n      // consistent self row open capture instead of losing the unmute forever.\n      const currentParticipant = this.selfParticipantRevision === participantRevision ?\n        participant :\n        (this.participant || participant);\n      if(!muted) {\n        if(currentParticipant.pFlags.can_self_unmute && !currentParticipant.pFlags.muted) {\n          this.pendingUnmuteIntentAt = undefined;\n          this.setMuted(false);\n          this.dispatchEvent('state', this.state);\n        } else if(currentParticipant.pFlags.can_self_unmute) {\n          this.pendingUnmuteIntentAt = performance.now();\n        }\n      }\n    } catch(err) {\n      // A failed microphone mutation must remain locally fail-closed. This\n      // preserves an explicit mute request and prevents a rejected unmute or a\n      // late thin participant row from opening current/pending capture tracks.\n      this.pendingUnmuteIntentAt = undefined;\n      this.setMuted(true);\n      if(this.selfParticipantRevision === participantRevision && this.participant === participant) {\n        participant.pFlags = {...previousPFlags};\n        try {\n          await this.managers.appGroupCallsManager.saveApiParticipant(this.id, participant);\n        } catch(rollbackError) {\n          this.log.error('mute participant rollback failed', rollbackError);\n        }\n      }\n      this.dispatchEvent('state', this.state);\n      throw err;\n    }\n  }\n\n  public getElement(endpoint: GroupCallOutputSource) {\n    return super.getElement(endpoint);\n  }\n\n  public getVideoElementFromParticipantByType(participant: GroupCallParticipant, type: 'video' | 'presentation') {\n    let source: GroupCallOutputSource;\n    if(participant.pFlags.self) {\n      const connectionType: GroupCallConnectionType = type === 'video' ? 'main' : 'presentation';\n      source = connectionType;\n    } else {\n      const codec = participant[type];\n      source = codec.source_groups[0].sources[0];\n    }\n\n    const element = this.getElement(source) as HTMLVideoElement;\n    if(!element) return;\n\n    const clone = element.cloneNode() as typeof element;\n    clone.srcObject = element.srcObject;\n    return {video: clone, source};\n  }\n\n  public createConnectionInstance(options: {\n    streamManager: StreamManager,\n    type: GroupCallConnectionType,\n    options: GroupCallConnectionInstance['options'],\n  }) {\n    const connection = this.connections[options.type] = new GroupCallConnectionInstance({\n      groupCall: this,\n      log: this.log.bindPrefix(options.type),\n      managers: this.managers,\n      ...options\n    });\n    if(options.type === 'main') {\n      this.observeInputAudioTrack(options.streamManager.inputStream.getAudioTracks()[0]);\n    }\n    return connection;\n  }\n\n  public changeRaiseHand(raise: boolean) {\n    return this.editParticipant(this.participant, {raiseHand: raise});\n  }\n\n  private assertMediaRuntimeReady(): void {\n    if(!this.isMediaRuntimeReady) {\n      throw new Error('Conference media is not ready until join and the self participant are confirmed');\n    }\n    if(!this.participant.pFlags.can_self_unmute) {\n      throw new Error('Conference media cannot start while the participant is muted by an admin');\n    }\n  }\n\n  private enqueuePresentationTransition(operation: () => Promise<void>): Promise<void> {\n    return this.presentationTransitionTail.enqueue(operation);\n  }\n\n  private leavePresentationConnection(connectionInstance: GroupCallConnectionInstance): Promise<void> {\n    if(!connectionInstance.joinAccepted || this.completedPresentationLeaves.has(connectionInstance)) {\n      return Promise.resolve();\n    }\n\n    const pending = this.presentationLeavePromises.get(connectionInstance);\n    if(pending) return pending;\n\n    const acceptedCallInput = connectionInstance.acceptedCallInput ?? this.toInputGroupCall();\n    if(!acceptedCallInput) {\n      return Promise.reject(new Error('Cannot leave presentation without its accepted call identity'));\n    }\n\n    this.pendingPresentationLeaves.add(connectionInstance);\n    const leave = this.managers.appGroupCallsManager.leaveGroupCallPresentation(acceptedCallInput).then(() => {\n      this.completedPresentationLeaves.add(connectionInstance);\n      this.pendingPresentationLeaves.delete(connectionInstance);\n    }).finally(() => {\n      this.presentationLeavePromises.delete(connectionInstance);\n    });\n    this.presentationLeavePromises.set(connectionInstance, leave);\n    return leave;\n  }\n\n  private async drainPendingPresentationLeaves(): Promise<void> {\n    for(const connectionInstance of [...this.pendingPresentationLeaves]) {\n      await this.leavePresentationConnection(connectionInstance);\n    }\n  }\n\n  private async removePresentationConnection(\n    connectionInstance: GroupCallConnectionInstance,\n    leaveServer: boolean\n  ): Promise<void> {\n    const isCurrent = this.connections.presentation === connectionInstance;\n    if(isCurrent) {\n      delete this.connections.presentation;\n      this.unpinSource('presentation');\n    }\n\n    if(!this.closedPresentationConnections.has(connectionInstance)) {\n      this.closedPresentationConnections.add(connectionInstance);\n      connectionInstance.closeConnectionAndStream(true);\n    }\n\n    let saveParticipant: Promise<void> | undefined;\n    if(isCurrent && this.participant?.presentation) {\n      delete this.participant.presentation;\n      saveParticipant = this.managers.appGroupCallsManager.saveApiParticipant(this.id, this.participant);\n    }\n    if(isCurrent) this.dispatchEvent('state', this.state);\n\n    if(saveParticipant) {\n      void saveParticipant.catch((err) => {\n        this.log.error('save detached presentation participant failed', err);\n      });\n    }\n\n    // A failed initial negotiation can happen after phone.joinGroupCall already\n    // accepted the presentation source but before answer SDP was installed.\n    // stopScreenSharing may have already detached the local connection while\n    // that RPC was in flight. Re-check acceptance on the later rollback and\n    // compensate exactly once even though the connection is no longer current.\n    if(leaveServer) await this.leavePresentationConnection(connectionInstance);\n  }\n\n  private bindPresentationRuntimeRecovery(connectionInstance: GroupCallConnectionInstance): void {\n    const recover = (label: string, err?: unknown) => {\n      if(this.connections.presentation !== connectionInstance || this.isClosing) return;\n      if(err) this.log.error(label, err);\n      else this.log.warn(label);\n      void this.recoverPresentationConnection(connectionInstance).catch((recoveryError) => {\n        this.log.error('screen sharing recovery failed', recoveryError);\n      });\n    };\n\n    connectionInstance.connection.addEventListener('negotiationneeded', () => {\n      if(this.connections.presentation !== connectionInstance || this.isClosing) return;\n      void connectionInstance.requestNegotiation().catch((err) => {\n        recover('screen sharing renegotiation failed', err);\n      });\n    });\n    connectionInstance.connection.addEventListener('connectionstatechange', () => {\n      const {connectionState} = connectionInstance.connection;\n      if(connectionState === 'failed' || connectionState === 'closed') {\n        recover(`screen sharing transport ${connectionState}`);\n      }\n    });\n    connectionInstance.connection.addEventListener('iceconnectionstatechange', () => {\n      const {iceConnectionState} = connectionInstance.connection;\n      if(iceConnectionState === 'failed' || iceConnectionState === 'closed') {\n        recover(`screen sharing ICE transport ${iceConnectionState}`);\n      }\n    });\n  }\n\n  public recoverPresentationConnection(expectedConnection: GroupCallConnectionInstance): Promise<void> {\n    if(this.connections.presentation !== expectedConnection || this.isClosing) {\n      return Promise.resolve();\n    }\n    if(this.presentationRecoveryPromise) return this.presentationRecoveryPromise;\n\n    const generation = this.screenSharingGeneration;\n    const recovery = this.enqueuePresentationTransition(() => {\n      return this.recoverPresentationConnectionInternal(expectedConnection, generation);\n    });\n    const trackedRecovery = recovery.finally(() => {\n      if(this.presentationRecoveryPromise === trackedRecovery) {\n        this.presentationRecoveryPromise = undefined;\n      }\n    });\n    this.presentationRecoveryPromise = trackedRecovery;\n    return trackedRecovery;\n  }\n\n  private async recoverPresentationConnectionInternal(\n    expectedConnection: GroupCallConnectionInstance,\n    generation: number\n  ): Promise<void> {\n    if(generation !== this.screenSharingGeneration ||\n       this.connections.presentation !== expectedConnection ||\n       this.isClosing) {\n      return;\n    }\n    await this.drainPendingPresentationLeaves();\n\n    const streamManager = expectedConnection.streamManager;\n    const videoTrack = streamManager.inputStream.getVideoTracks()[0];\n    if(!videoTrack || videoTrack.readyState === 'ended') {\n      await this.removePresentationConnection(expectedConnection, true);\n      return;\n    }\n\n    // Preserve the active capture and rebuild only the missing presentation\n    // transport. Reopening getDisplayMedia here would show a second picker and\n    // discard a perfectly healthy screen track.\n    this.closedPresentationConnections.add(expectedConnection);\n    expectedConnection.closeConnectionAndStream(false);\n\n    let replacement: GroupCallConnectionInstance | undefined;\n    try {\n      replacement = this.createConnectionInstance({\n        streamManager,\n        type: 'presentation',\n        options: {type: 'presentation'}\n      });\n      replacement.createPeerConnection();\n      replacement.createDescription();\n      await replacement.appendInputStreamWithE2e();\n      await replacement.negotiate();\n\n      if(generation !== this.screenSharingGeneration ||\n         this.connections.presentation !== replacement ||\n         !this.isMediaRuntimeReady) {\n        throw new Error('Screen sharing recovery was cancelled during negotiation');\n      }\n      this.bindPresentationRuntimeRecovery(replacement);\n      this.dispatchEvent('state', this.state);\n    } catch(err) {\n      let cleanupError: unknown;\n      if(!replacement) streamManager.stop();\n      if(replacement) {\n        try {\n          await this.removePresentationConnection(replacement, true);\n        } catch(rollbackError) {\n          this.log.error('screen sharing recovery rollback failed', rollbackError);\n          cleanupError = rollbackError;\n        }\n      }\n      if(!replacement?.joinAccepted) {\n        try {\n          await this.removePresentationConnection(expectedConnection, true);\n        } catch(rollbackError) {\n          this.log.error('stale presentation leave failed', rollbackError);\n          cleanupError ??= rollbackError;\n        }\n      }\n      if(cleanupError) {\n        throw mediaCleanupError('Screen sharing recovery and cleanup failed', err, cleanupError);\n      }\n      throw err;\n    }\n  }\n\n  private async removeInputTracks(\n    connectionInstance: GroupCallConnectionInstance,\n    tracks: MediaStreamTrack[]\n  ): Promise<void> {\n    for(const track of tracks) {\n      stopTrack(track);\n      connectionInstance.streamManager.removeTrack(track);\n    }\n    await connectionInstance.streamManager.appendToConference(\n      connectionInstance.description,\n      undefined,\n      true\n    );\n    this.dispatchEvent('state', this.state);\n  }\n\n  public async startScreenSharingInternal(generation = this.screenSharingGeneration, acquiredStream?: MediaStream): Promise<void> {\n    let stream: MediaStream | undefined = acquiredStream;\n    let connectionInstance: GroupCallConnectionInstance | undefined;\n    try {\n      const type: GroupCallConnectionType = 'presentation';\n\n      // Staleness first: a generation bumped while the picker was open (stop,\n      // admin mute, hangUp) must surface as cancellation, not as whatever\n      // runtime-readiness error that later teardown also produced.\n      if(generation !== this.screenSharingGeneration) {\n        throw new Error('Screen sharing request was cancelled before media became ready');\n      }\n      this.assertMediaRuntimeReady();\n      await this.drainPendingPresentationLeaves();\n      stream ??= await getScreenStream(getGroupScreenConstraints());\n      // The screen-picker can stay open for seconds; the user can hang up\n      // before it resolves. hangUp() already walked this.connections and never\n      // saw the presentation connection (it didn't exist yet), so building it\n      // now would leave the screen capture live forever — release and bail.\n      if(generation !== this.screenSharingGeneration || !this.isMediaRuntimeReady) {\n        throw new Error('Screen sharing request was cancelled before media became ready');\n      }\n      const videoTrack = stream.getVideoTracks()[0];\n      if(!videoTrack) throw new Error('Screen capture did not provide a video track');\n      const streamManager = new StreamManager();\n\n      connectionInstance = this.createConnectionInstance({\n        streamManager,\n        type,\n        options: {\n          type\n        }\n      });\n\n      connectionInstance.createPeerConnection();\n\n      videoTrack.addEventListener('ended', () => {\n        if(this.connections.presentation) { // maybe user has stopped screensharing through browser's ui\n          void this.stopScreenSharing().catch((err) => this.log.error('stop screen sharing after capture ended', err));\n        }\n      }, {once: true});\n\n      connectionInstance.createDescription();\n      await connectionInstance.addInputVideoStream(stream);\n      await connectionInstance.negotiate();\n\n      if(generation !== this.screenSharingGeneration || !this.isMediaRuntimeReady) {\n        throw new Error('Screen sharing request was cancelled during negotiation');\n      }\n      this.bindPresentationRuntimeRecovery(connectionInstance);\n    } catch(err) {\n      this.log.error('start screen sharing error', err);\n      let cleanupError: unknown;\n      if(connectionInstance) {\n        try {\n          await this.removePresentationConnection(connectionInstance, true);\n        } catch(rollbackError) {\n          this.log.error('start screen sharing rollback failed', rollbackError);\n          cleanupError = rollbackError;\n        }\n      }\n      // The failure may precede addInputVideoStream, in which case closing the\n      // connection's still-empty StreamManager cannot release the capture.\n      stream?.getTracks().forEach((track) => {\n        if(track.readyState !== 'ended') stopTrack(track);\n      });\n      if(cleanupError) {\n        throw mediaCleanupError('Screen sharing start and cleanup failed', err, cleanupError);\n      }\n      throw err;\n    }\n  }\n\n  public startScreenSharing() {\n    if(this.startScreenSharingPromise &&\n       this.startScreenSharingPromiseGeneration === this.screenSharingGeneration) {\n      return this.startScreenSharingPromise;\n    }\n    const generation = ++this.screenSharingGeneration;\n    // Acquire OUTSIDE the presentation transition tail. getDisplayMedia blocks\n    // until the user acts on the picker, and everything queued behind it —\n    // stopScreenSharing, and through it the hangUp/recovery cleanup that awaits\n    // the tail — would sit frozen exactly as long: a conference recovery fired\n    // while the picker was open used to leave a dead call (transport already\n    // closed, rejoin unable to start) until the picker was dismissed.\n    const start = (async() => {\n      this.assertMediaRuntimeReady();\n      const stream = await getScreenStream(getGroupScreenConstraints());\n      return this.enqueuePresentationTransition(() => this.startScreenSharingInternal(generation, stream));\n    })();\n    const trackedStart = start.finally(() => {\n      if(this.startScreenSharingPromise === trackedStart) {\n        this.startScreenSharingPromise = undefined;\n      }\n    });\n    this.startScreenSharingPromiseGeneration = generation;\n    this.startScreenSharingPromise = trackedStart;\n    return trackedStart;\n  }\n\n  public stopScreenSharing() {\n    ++this.screenSharingGeneration;\n    const connectionInstance = this.connections.presentation;\n    // Detach synchronously so UI/capture state flips at once, but serialize the\n    // source-less leave RPC behind any in-flight join/recovery. A late leave for\n    // an old accepted source must complete before a new presentation can join,\n    // otherwise phone.leaveGroupCallPresentation would tear down the new one.\n    const detach = connectionInstance ?\n      this.removePresentationConnection(connectionInstance, false) :\n      Promise.resolve();\n\n    return this.enqueuePresentationTransition(async() => {\n      await detach;\n      if(connectionInstance) await this.removePresentationConnection(connectionInstance, true);\n      await this.drainPendingPresentationLeaves();\n    });\n  }\n\n  public toggleScreenSharing() {\n    if(this.isSharingScreen) {\n      return this.stopScreenSharing();\n    } else {\n      return this.startScreenSharing();\n    }\n  }\n\n  public async startVideoSharingInternal(generation = this.videoSharingGeneration): Promise<void> {\n    const constraints: MediaStreamConstraints = {\n      video: getVideoConstraints()\n    };\n\n    this.assertMediaRuntimeReady();\n    const participant = this.participant;\n    const previousVideo = participant.video;\n    const hadPreviousVideo = Object.prototype.hasOwnProperty.call(participant, 'video');\n    let participantEditStarted = false;\n    let mediaStoppedDuringCancellation = false;\n    let stream: MediaStream | undefined;\n    let connectionInstance: GroupCallConnectionInstance | undefined;\n    try {\n      stream = await getStream(constraints, false);\n      // The call can be hung up during the `getUserMedia` window. After that\n      // cleanup() has already run streamManager.stop(), so adding this stream\n      // would leak the camera (LED stuck on) — release it instead.\n      if(generation !== this.videoSharingGeneration || !this.isMediaRuntimeReady) {\n        throw new Error('Camera request completed after conference media stopped being ready');\n      }\n      if(!stream.getVideoTracks()[0]) throw new Error('Camera capture did not provide a video track');\n      connectionInstance = this.connections.main;\n      await connectionInstance.addInputVideoStream(stream);\n      await connectionInstance.requestNegotiation();\n\n      if(generation !== this.videoSharingGeneration || !this.isMediaRuntimeReady) {\n        throw new Error('Camera sharing request was cancelled during negotiation');\n      }\n\n      participantEditStarted = true;\n      await this.editParticipant(participant, {\n        videoPaused: false,\n        videoStopped: false\n      });\n      participantEditStarted = false;\n\n      // An admin mute/user stop can land after negotiation but while the\n      // participant RPC is in flight. The start RPC may still be accepted\n      // after that newer stop, so publish a final stopped state and remove the\n      // sender again before reporting cancellation.\n      if(generation !== this.videoSharingGeneration ||\n         !this.isMediaRuntimeReady ||\n         !this.participant.pFlags.can_self_unmute) {\n        const cancellationError = new Error('Camera sharing was cancelled while publishing participant state');\n        try {\n          // An admin mute already owns a retrying stop transaction. Await that\n          // exact compensation instead of publishing a duplicate stopped edit;\n          // an ordinary user cancellation has no such owner and compensates here.\n          if(this.adminMediaTeardownPromise) {\n            await this.adminMediaTeardownPromise;\n          } else {\n            await this.stopVideoSharing(true);\n          }\n          mediaStoppedDuringCancellation = true;\n        } catch(cleanupError) {\n          throw mediaCleanupError('Camera sharing cancellation cleanup failed', cancellationError, cleanupError);\n        }\n        throw cancellationError;\n      }\n    } catch(err) {\n      this.log.error('startVideoSharing error', err, constraints);\n      let participantRollbackPromise: Promise<void> | undefined;\n      if(participantEditStarted && this.participant === participant) {\n        if(hadPreviousVideo) participant.video = previousVideo;\n        else delete participant.video;\n        participantRollbackPromise = (async() => {\n          try {\n            await this.managers.appGroupCallsManager.saveApiParticipant(this.id, participant);\n          } catch(rollbackError) {\n            this.log.error('startVideoSharing participant rollback failed', rollbackError);\n          }\n        })();\n        this.dispatchEvent('state', this.state);\n      }\n      if(connectionInstance && stream && !mediaStoppedDuringCancellation) {\n        try {\n          await this.removeInputTracks(connectionInstance, stream.getTracks());\n        } catch(rollbackError) {\n          this.log.error('startVideoSharing rollback failed', rollbackError);\n        }\n      } else if(stream && !mediaStoppedDuringCancellation) {\n        stream.getTracks().forEach((track) => stopTrack(track));\n      }\n      await participantRollbackPromise;\n      throw err;\n    }\n  }\n\n  public startVideoSharing() {\n    if(this.startVideoSharingPromise) return this.startVideoSharingPromise;\n    const generation = ++this.videoSharingGeneration;\n    return this.startVideoSharingPromise = this.startVideoSharingInternal(generation).finally(() => {\n      this.startVideoSharingPromise = undefined;\n    });\n  }\n\n  public async stopVideoSharing(\n    forceParticipantUpdate = false,\n    shouldContinue: () => boolean = () => true\n  ) {\n    ++this.videoSharingGeneration;\n    const connectionInstance = this.connections.main;\n    const track = connectionInstance.streamManager.inputStream.getVideoTracks()[0];\n    const shouldPublishStopped = forceParticipantUpdate || !!track || !!this.participant?.video;\n    if(!shouldPublishStopped) {\n      return;\n    }\n\n    // `stopTrack` only flips `readyState` to \"ended\"; the StreamItem and the\n    // track stay in `streamManager` until the asynchronous `ended` event\n    // listener fires later. We do it synchronously here so that:\n    //   1. `isSharingVideo` (which reads streamManager.items) flips to\n    //      `false` immediately — without this, a fast follow-up\n    //      toggleVideoSharing() click reads stale `true` and ends up calling\n    //      stopVideoSharing() again instead of startVideoSharing(), and the\n    //      toggle \"does nothing\".\n    //   2. `appendToConference` below iterates `inputStream.getTracks()` to\n    //      pick a replacement; if the stopped track is still listed, it\n    //      replaces senders with the stopped track instead of `undefined`\n    //      (the \"clear sender\" comment) — and remote sees a frozen frame\n    //      until the next negotiation. Removing it makes `findIndex` return\n    //      -1, so `appendToConference` correctly clears the sender.\n    // The async `ended` listener still fires later; removeTrack is idempotent.\n    if(track) await this.removeInputTracks(connectionInstance, [track]);\n\n    // An authoritative unmute can supersede an admin teardown while the\n    // sender replacement above is still in flight. The user may already have\n    // started a newer camera track by the time it resolves; never let the old\n    // transaction publish `videoStopped` after that newer start.\n    if(!shouldContinue()) return;\n\n    await this.editParticipant(this.participant, {\n      videoStopped: true\n    });\n  }\n\n  public toggleVideoSharing() {\n    if(this.isSharingVideo) {\n      return this.stopVideoSharing();\n    } else {\n      return this.startVideoSharing();\n    }\n  }\n\n  // CallInstanceBase hook for mid-call device swap. Walks every connection\n  // we own (main + presentation) so screen-sharing keeps working when the\n  // user picks a different camera while presenting. Quietly skips\n  // connections that aren't up yet — the next negotiation will pick up the\n  // new track from streamManager.appendToConference instead.\n  protected async replaceSenderTrack(\n    kind: 'audio' | 'video',\n    oldTrack: MediaStreamTrack,\n    newTrack: MediaStreamTrack\n  ): Promise<void> {\n    if(kind === 'audio') this.observeInputAudioTrack(newTrack);\n    const replacements: Promise<void>[] = [];\n    for(const type in this.connections) {\n      const connectionInstance = this.connections[type as GroupCallConnectionType];\n      const connection = connectionInstance?.connection;\n      if(!connection) continue;\n      for(const sender of connection.getSenders()) {\n        if(sender.track === oldTrack) {\n          replacements.push(sender.replaceTrack(newTrack));\n        }\n      }\n    }\n    await waitForMediaTrackReplacements(replacements);\n  }\n\n\n  public async hangUp(discard = false, rejoin = false, isDiscarded = false) {\n    const presentationCleanup = this.stopScreenSharing();\n    for(const type in this.connections) {\n      const connection = this.connections[type as GroupCallConnectionType];\n      connection.closeConnectionAndStream(!rejoin);\n    }\n\n    this.dispatchEvent('state', this.state);\n\n    if(isDiscarded) {\n      try {\n        await presentationCleanup;\n      } catch(err) {\n        this.log.error('presentation cleanup during conference recovery failed', err);\n        try {\n          // Recovery replaces the main transport instead of sending a main\n          // leave, so it cannot rely on that RPC to remove a stale presentation\n          // source. Retry the exact accepted presentation identity, but do not\n          // strand the whole main recovery if the presentation RPC stays down.\n          await this.retryMediaTeardown(\n            'presentation cleanup during conference recovery',\n            () => this.stopScreenSharing()\n          );\n        } catch(retryError) {\n          this.log.error('presentation cleanup exhausted during conference recovery', retryError);\n        }\n      }\n      return;\n    }\n\n    if(!rejoin) {\n      let d: Parameters<AppGroupCallsManager['hangUp']>[1];\n      try {\n        d = discard || (/* this.joined ?  */this.connections.main.sources.audio.source/*  : undefined */);\n      } catch(err) {\n        d = 0;\n      }\n\n      const [presentationResult, leaveResult] = await Promise.allSettled([\n        presentationCleanup,\n        this.managers.appGroupCallsManager.hangUp(this.id, d)\n      ]);\n      if(leaveResult.status === 'rejected') throw leaveResult.reason;\n      if(presentationResult.status === 'rejected') {\n        // The main leave removes every source, so a presentation-specific\n        // failure is reconciled once the main RPC succeeds.\n        this.log.error('presentation cleanup failed before main leave', presentationResult.reason);\n      }\n    } else {\n      await presentationCleanup;\n    }\n  }\n\n  private hangUpAfterFatalFailure(): void {\n    if(this.fatalHangUpStarted) return;\n    this.fatalHangUpStarted = true;\n    try {\n      void (this.hangUp() as Promise<void> | undefined)?.catch((err) => {\n        this.log.error('leave after fatal conference failure failed', err);\n      });\n    } catch(err) {\n      this.log.error('leave after fatal conference failure failed', err);\n    }\n  }\n\n  private async retryMediaTeardown(\n    label: string,\n    operation: () => Promise<void>,\n    shouldContinue: () => boolean = () => true\n  ): Promise<void> {\n    let lastError: unknown;\n    for(let attempt = 0; attempt < MEDIA_TEARDOWN_MAX_ATTEMPTS; ++attempt) {\n      if(!shouldContinue()) return;\n      try {\n        await operation();\n        return;\n      } catch(err) {\n        // A newer authoritative self row can restore media permission while an\n        // older admin-mute cleanup is waiting on its RPC. Do not let the retry\n        // wake up later and tear down camera/screen media started after that\n        // unmute.\n        if(!shouldContinue()) return;\n        lastError = err;\n        this.log.error(`${label} failed`, err);\n        if(attempt + 1 < MEDIA_TEARDOWN_MAX_ATTEMPTS) {\n          await pause(MEDIA_TEARDOWN_RETRY_BASE_MS * (attempt + 1));\n        }\n      }\n    }\n    throw lastError;\n  }\n\n  private async enforceAdminMediaTeardown(\n    stopScreen: boolean,\n    stopVideo: boolean,\n    generation: number\n  ): Promise<void> {\n    const shouldContinue = () => {\n      return generation === this.adminMediaTeardownGeneration &&\n        this.adminMediaBlocked &&\n        !this.isClosing;\n    };\n    const teardown: Promise<void>[] = [];\n    if(stopScreen) {\n      teardown.push(this.retryMediaTeardown(\n        'stop screen sharing after admin mute',\n        () => this.stopScreenSharing(),\n        shouldContinue\n      ));\n    }\n    if(stopVideo) {\n      teardown.push(this.retryMediaTeardown(\n        'stop video sharing after admin mute',\n        () => this.stopVideoSharing(true, shouldContinue),\n        shouldContinue\n      ));\n    }\n\n    const results = await Promise.allSettled(teardown);\n    if(shouldContinue() && results.some((result) => result.status === 'rejected')) {\n      // Repeated metadata cleanup failures leave the server believing camera or\n      // presentation media is active. Leaving the call is the only fail-closed\n      // reconciliation that removes every source atomically.\n      this.hangUpAfterFatalFailure();\n    }\n  }\n\n  public tryAddTrack(options: Omit<TryAddTrackOptions, 'streamManager'>) {\n    const {description} = this;\n    const source = super.tryAddTrack(options);\n\n    if(options.type === 'output') {\n      const entry = description.getEntryBySource(+source);\n      const lifecycleGeneration = this.lifecycleGeneration;\n      void this.getParticipantByPeerId(entry.peerId).then((participant) => {\n        if(lifecycleGeneration !== this.lifecycleGeneration ||\n           this.isClosing ||\n           this.connections.main?.description !== description) {\n          return;\n        }\n        if(participant) {\n          rootScope.dispatchEvent('group_call_participant', {groupCallId: this.id, participant});\n        }\n      }).catch((err) => {\n        this.log.warn('output track participant hydration failed', err);\n      });\n    }\n\n    return source;\n  }\n\n  public async editParticipant(participant: GroupCallParticipant, options: Partial<{\n    muted: boolean,\n    volume: number,\n    raiseHand: boolean,\n    videoStopped: boolean,\n    videoPaused: boolean,\n    presentationPaused: boolean\n  }>, optimistic = true) {\n    if(!Object.keys(options).length) {\n      return;\n    }\n\n    // let processUpdate = true;\n    if(participant) {\n      // const {currentGroupCall} = this;\n      // const isCurrentCall = currentGroupCall?.id === groupCallId;\n      const isCurrentCall = true;\n      const isUpdatingMeInCurrentCall = isCurrentCall && participant.pFlags.self;\n\n      if(isUpdatingMeInCurrentCall) {\n        if(options.muted !== undefined && !this.isSharingAudio) {\n          delete options.muted;\n\n          if(!Object.keys(options).length) {\n            return;\n          }\n        }\n      }\n\n      // if(isCurrentCall) {\n      const muted = options.muted;\n      if(muted !== undefined) {\n        /* const isAdmin = appChatsManager.hasRights(currentGroupCall.chatId, 'manage_call');\n          if(isAdmin) {\n            if(muted) {\n              participant.pFlags.muted = true;\n              delete participant.pFlags.can_self_unmute;\n            } else {\n              participant.pFlags.can_self_unmute = true;\n            }\n          } else  */if(participant.pFlags.self) {\n          if(muted) {\n            participant.pFlags.muted = true;\n          } else if(participant.pFlags.can_self_unmute) {\n            delete participant.pFlags.muted;\n          }\n        }/*  else {\n            if(muted) {\n              participant.pFlags.muted_by_you = true;\n            } else {\n              delete participant.pFlags.muted_by_you;\n            }\n          } */\n      }\n      // }\n\n      /* const a: [keyof GroupCallParticipant['pFlags'], keyof typeof options][] = [\n        ['muted', 'muted']\n      ];\n\n      a.forEach(([key, optionKey]) => {\n        const value = options[optionKey];\n        if(value === undefined) {\n          return;\n        }\n\n        if(value) {\n          participant.pFlags[key] = true;\n        } else {\n          delete participant.pFlags[key];\n        }\n      }); */\n\n      if(options.raiseHand !== undefined) {\n        if(options.raiseHand) participant.raise_hand_rating = '1';\n        else delete participant.raise_hand_rating;\n      }\n\n      if(isUpdatingMeInCurrentCall) {\n        if(options.videoStopped !== undefined) {\n          if(options.videoStopped) delete participant.video;\n          else participant.video = generateSelfVideo(this.connections.main.sources.video);\n        }\n\n        this.dispatchEvent('state', this.state);\n      }\n\n      // rootScope.dispatchEvent('group_call_participant', {groupCallId, participant});\n\n      /* if(participant.pFlags.self) {\n        processUpdate = false;\n      } */\n    }\n\n    const isSelf = !!participant?.pFlags.self;\n    const managerParticipant = isSelf ? {\n      ...participant,\n      pFlags: {...participant.pFlags}\n    } : participant;\n    const invoke = () => {\n      return this.managers.appGroupCallsManager.editParticipant(\n        this.id,\n        managerParticipant,\n        options,\n        optimistic\n      );\n    };\n\n    if(!isSelf) return invoke();\n\n    // Every self edit carries a complete participant row into the worker cache.\n    // Serialize those snapshots so an unrelated optimistic video/hand update\n    // cannot echo the in-flight mute's locally-mutated pFlags and masquerade as\n    // a newer authoritative mute revision during rollback.\n    return this.selfParticipantEditTail.enqueue(invoke);\n  }\n\n  private isOwnSendEntry(entry: ConferenceEntry): boolean {\n    const isSending = (direction: RTCRtpTransceiverDirection) => direction === 'sendonly' || direction === 'sendrecv';\n    return isSending(entry.direction) ||\n      isSending(entry.originalDirection) ||\n      (!!rootScope.myId && entry.peerId === rootScope.myId);\n  }\n\n  public onParticipantUpdate(participant: GroupCallParticipant) {\n    const connectionInstance = this.connections.main;\n    const {connection, description} = connectionInstance;\n\n    const peerId = getPeerId(participant.peer);\n    const hasLeft = !!participant.pFlags.left;\n    const oldSsrcs = this.participantsSsrcs.get(peerId) || [];\n\n    if(participant.presentation && !hasLeft) {\n      const {source} = makeSsrcFromParticipant(participant, 'video', participant.presentation.source_groups, participant.presentation.endpoint);\n      if(!this.hadAutoPinnedSources.has(source)) {\n        this.hadAutoPinnedSources.add(source);\n        this.pinSource(participant.pFlags.self ? 'presentation' : source);\n      }\n    }\n\n    if(participant.pFlags.self) {\n      ++this.selfParticipantRevision;\n      this.participant = participant;\n\n      if(hasLeft) {\n        // The server removed us — an admin kicked us, or our slot was taken\n        // over. This row used to be ignored, so the call only ended once ICE\n        // timed out 15-30 s later, and an unmuted microphone kept feeding our\n        // SFU slot meanwhile while the popup still showed \"unmuted\". tdesktop\n        // applySelfUpdate rejoins when the row carries our ssrc and hangs up\n        // otherwise; a rejoin is a separate feature, so fail closed either\n        // way: cut capture synchronously, then leave. A row that arrives while\n        // our own leave is already tearing the connection down changes nothing.\n        if(this.isClosing) return;\n        this.setMuted(true);\n        this.dispatchEvent('state', this.state);\n        this.hangUpAfterFatalFailure();\n        return;\n      }\n\n      const adminMediaBlocked = !participant.pFlags.can_self_unmute;\n      const adminMediaBlockChanged = this.adminMediaBlocked !== adminMediaBlocked;\n      if(adminMediaBlockChanged) {\n        this.adminMediaBlocked = adminMediaBlocked;\n        ++this.adminMediaTeardownGeneration;\n        if(!adminMediaBlocked && this.joined) {\n          // An admin lifted our forced mute. The row still says `muted`, so we\n          // stay muted (below) — the cue is what tells the user the microphone\n          // button works again (tdesktop notifyAboutAllowedToSpeak, gated on\n          // having joined exactly like `_hadJoinedState`).\n          notifyAllowedToSpeak();\n        }\n      }\n\n      if(connectionInstance.sources.audio.source !== participant.source) {\n        this.hangUpAfterFatalFailure();\n      }\n\n      let mute = false;\n      if(adminMediaBlocked) {\n        // Include acquisitions/negotiations that have not published a track or\n        // participant row yet. stop* increments the matching generation\n        // immediately, so their late continuations release capture instead of\n        // starting media after the admin mute.\n        const stopScreen = !!this.startScreenSharingPromise ||\n          this.isSharingScreen ||\n          this.pendingPresentationLeaves.size > 0 ||\n          !!participant.presentation;\n        const stopVideo = !!this.startVideoSharingPromise ||\n          this.isSharingVideo ||\n          !!participant.video;\n        if((stopScreen || stopVideo) && (!this.adminMediaTeardownPromise || adminMediaBlockChanged)) {\n          const generation = this.adminMediaTeardownGeneration;\n          const previousTeardown = this.adminMediaTeardownPromise;\n          const teardown = (async() => {\n            if(previousTeardown) await previousTeardown.catch(() => {});\n            if(generation !== this.adminMediaTeardownGeneration || !this.adminMediaBlocked) return;\n            await this.enforceAdminMediaTeardown(stopScreen, stopVideo, generation);\n          })();\n          const trackedTeardown = teardown.finally(() => {\n            if(this.adminMediaTeardownPromise === trackedTeardown) {\n              this.adminMediaTeardownPromise = undefined;\n            }\n          });\n          this.adminMediaTeardownPromise = trackedTeardown;\n        }\n        mute = true;\n      } else if(participant.pFlags.muted) {\n        mute = true;\n      }\n\n      if(adminMediaBlocked) {\n        // Admin took the floor away — any armed unmute intent is void.\n        this.pendingUnmuteIntentAt = undefined;\n      }\n\n      if(mute) {\n        this.setMuted(true);\n      } else if(\n        this.pendingUnmuteIntentAt !== undefined &&\n        participant.pFlags.can_self_unmute &&\n        this.isMuted\n      ) {\n        // A server-accepted unmute lost the post-RPC check to a stale muted row\n        // (see changeSelfMuted); this consistent self row confirms it. Open\n        // capture only within the intent's TTL so a long-forgotten click can\n        // never surprise-open the microphone.\n        const fresh = performance.now() - this.pendingUnmuteIntentAt < UNMUTE_INTENT_TTL_MS;\n        this.pendingUnmuteIntentAt = undefined;\n        if(fresh) {\n          this.setMuted(false);\n        }\n      }\n\n      this.dispatchEvent('state', this.state);\n\n      return;\n    }\n\n    let ssrcs = hasLeft ? [] : makeSsrcsFromParticipant(participant);\n\n    // A remote row naming one of OUR send sources used to rebind that entry to\n    // the remote peer and, once the row stopped listing it, set it inactive —\n    // the next answer then rejected our own audio m-line. Our send entries\n    // never belong to anyone else, so drop such a source here, before it can\n    // reach the key map, the SDP or this participant's remembered set (which\n    // is what the `left` pass below inactivates).\n    ssrcs = ssrcs.filter((ssrc) => {\n      const entry = description.getEntryBySource(ssrc.source);\n      if(!entry || !this.isOwnSendEntry(entry)) return true;\n      this.reportConferenceBug(\n        'the call server assigned our own media stream to another participant',\n        {source: ssrc.source, type: ssrc.type, to: peerId}\n      );\n      return false;\n    });\n\n    // For e2e conferences: map every SFU SSRC for this participant to their\n    // Telegram user_id so recv RTCRtpScriptTransform handlers can look up\n    // the correct Ed25519 public key for signature verification. The\n    // TdE2E \"user_id\" IS the Telegram user_id — same value namespace.\n    if(this.e2e && participant.peer?._ === 'peerUser') {\n      const userId = BigInt(participant.peer.user_id);\n      if(hasLeft) {\n        let changed = false;\n        for(const ssrc of oldSsrcs) {\n          for(const source of e2eSourcesOf(ssrc)) {\n            const normalized = fromTelegramSource(source);\n            if(this.e2eUserBySsrc.get(normalized) === userId && this.e2eUserBySsrc.delete(normalized)) {\n              changed = true;\n            }\n          }\n        }\n        if(changed) this.syncSsrcMapToWorker();\n      } else {\n        // Register what this update announces. Deliberately do NOT prune the\n        // sources it omits: a participant row is not a reliable statement of\n        // the peer's CURRENT sources. `saveApiParticipant` overwrites the cache\n        // wholesale (safeReplaceObject) with no staleness check, so a roster\n        // page computed before a \"video on\" push lands here after it and omits\n        // that source. Differencing against such a row un-mapped a live SSRC,\n        // and an unmapped SSRC is dropped by the recv transform — the peer is\n        // seen but never heard, for the rest of the call. Explicit `left`\n        // removes the accumulated set; until then the hard\n        // MAX_E2E_SSRC_ENTRIES cap bounds adversarial churn.\n        // Capacity is checked for the whole source group before the SDP loop\n        // below. Rejected entries never allocate a ConferenceEntry,\n        // transceiver, receiver or script transform.\n        ssrcs = ssrcs.filter((ssrc) => this.registerE2eUserSsrcGroup(userId, ssrc));\n      }\n    } else if(this.e2e && !hasLeft && ssrcs.length) {\n      // A conference frame can only be authenticated against a Telegram user\n      // from the e2e group state. Do not allocate decoders for an identity that\n      // cannot ever be installed in the worker's SSRC map.\n      this.reportConferenceBug('the call server announced conference media for a non-user peer', {peerId});\n      ssrcs = [];\n    }\n\n    if(this.e2e && !hasLeft) {\n      ssrcs = mergeE2eParticipantSsrcs(oldSsrcs, ssrcs);\n    }\n\n    if(!hasLeft) {\n      this.participantsSsrcs.set(peerId, ssrcs);\n    } else {\n      this.participantsSsrcs.delete(peerId);\n    }\n\n    // const TEST_OLD = false;\n\n    const modifiedTypes: Set<WebRTCLineType> = new Set();\n    oldSsrcs.forEach((oldSsrc) => {\n      const oldSource = oldSsrc.source;\n      const newSsrc = ssrcs.find((ssrc) => ssrc.source === oldSource && ssrc.type === oldSsrc.type);\n      if(!newSsrc) {\n        // A numeric SSRC can be reused across media kinds after its old m-line\n        // becomes inactive. Removing an audio entry must not unpin the new\n        // video entry that now owns that same number; removing video still\n        // retires its pin as usual.\n        if(oldSsrc.type === 'video' || !ssrcs.some((ssrc) => ssrc.source === oldSource)) {\n          this.unpinSource(oldSource);\n        }\n\n        const oldEntry = description.getEntryBySource(oldSource);\n        if(oldEntry && oldEntry.direction !== 'inactive') {\n          oldEntry.setDirection('inactive');\n          modifiedTypes.add(oldEntry.type);\n        }\n      }\n    });\n\n    ssrcs.forEach((ssrc) => {\n      const indexedEntry = description.getEntryBySource(ssrc.source);\n      let entry = indexedEntry?.type === ssrc.type ? indexedEntry :\n        description.findEntry((candidate) => candidate.source === ssrc.source && candidate.type === ssrc.type);\n      if(indexedEntry && indexedEntry !== entry && indexedEntry.direction !== 'inactive') {\n        this.reportConferenceBug(\n          'the call server assigned one active SSRC to both audio and video',\n          {source: ssrc.source, from: indexedEntry.type, to: ssrc.type}\n        );\n        return;\n      }\n      if(entry) {\n        if(indexedEntry !== entry) {\n          description.setEntrySource(entry, ssrc.sourceGroups || ssrc.source);\n        }\n        // An entry for this SSRC already exists. It may belong to someone else:\n        // either the SFU recycled a source after its previous owner left (the\n        // entry is kept, only set inactive), or it is claiming one live\n        // participant's stream for another. Either way the entry must follow\n        // the identity the key map now uses, or the tile renders under the\n        // previous owner's name while frames are verified against the new\n        // one's key. Re-bind rather than silently inheriting the stale peerId.\n        if(entry.peerId !== peerId) {\n          if(entry.direction !== 'inactive') {\n            // Recycling an INACTIVE source is ordinary; moving a live one\n            // between participants is not something an honest SFU does.\n            this.reportConferenceBug(\n              'the call server assigned one media stream to two participants',\n              {source: ssrc.source, from: entry.peerId, to: peerId}\n            );\n          }\n\n          description.setEntryPeerId(entry, peerId);\n        }\n\n        if(entry.direction === 'inactive') {\n          entry.setDirection(entry.originalDirection);\n          modifiedTypes.add(entry.type);\n        }\n\n        return;\n      }\n\n      // Conference sources are capped up front in registerE2eUserSsrcGroup;\n      // this is the same bound on the legacy SFU path, where nothing else\n      // limited how many decoders one participant list could demand.\n      if(description.entries.length >= MAX_E2E_SSRC_ENTRIES) {\n        this.reportConferenceBug(\n          'the call server announced more media streams than this call can hold',\n          {source: ssrc.source, entries: description.entries.length}\n        );\n        return;\n      }\n\n      entry = description.createEntry(ssrc.type);\n      description.setEntrySource(entry, ssrc.sourceGroups || ssrc.source);\n      description.setEntryPeerId(entry, peerId);\n\n      // if(TEST_OLD) {\n      //   description.bundleMids.push(entry.mid);\n      //   entry.setDirection('recvonly');\n      // } else {\n      ssrc.type === 'video' && entry.setEndpoint(ssrc.endpoint);\n      entry.createTransceiver(connection, {direction: 'recvonly'});\n\n      // Conference (e2e) only: attach the receive-side RTCRtpScriptTransform\n      // RIGHT NOW — in the gap between createTransceiver and the next\n      // negotiate() that binds the decoder. This is the only window Chrome\n      // accepts a recv transform, mirroring the sender-side constraint.\n      // Attaching it later (in the connection's `track` event, after the\n      // decoder has produced its first frame) makes Chrome silently bypass it\n      // — frames reach the decoder still encrypted and the peer hears noise\n      // (the long-standing \"recv pumps ~5 frames then halts\" symptom). One\n      // transceiver per SSRC (this loop) ⇒ one decoder + one transform per\n      // remote stream, exactly like the legacy SFU path: the server signals\n      // only SSRCs, we mint the m-lines. No-op for legacy voice chats —\n      // attachE2eRecvTransform returns early unless `this.e2e` is set.\n      this.attachE2eRecvTransform(entry.transceiver.receiver, entry.type === 'video' ? 'video' : 'audio');\n      // }\n\n      modifiedTypes.add(entry.type);\n    });\n\n    /* if(TEST_OLD) {\n      this.setRemoteOffer({\n        connection,\n        description,\n        ssrcs\n      });\n    } else  */if(modifiedTypes.size || this.remoteNegotiationPending) {\n      if(modifiedTypes.has('video')) {\n        connectionInstance.updateConstraints = true;\n      }\n\n      this.remoteNegotiationPending = true;\n      void connectionInstance.requestNegotiation().then(() => {\n        if(this.connections.main === connectionInstance) {\n          this.remoteNegotiationPending = false;\n        }\n      }, (err) => {\n        this.log.error('remote participant renegotiation failed', err);\n      });\n    }\n  }\n}\n","import {GROUP_CALL_AMPLITUDE_ANALYSE_INTERVAL_MS} from '@lib/calls/constants';\nimport StreamManager from '@lib/calls/streamManager';\nimport getAudioConstraints from '@lib/calls/helpers/getAudioConstraints';\nimport getStream from '@lib/calls/helpers/getStream';\nimport getVideoConstraints from '@lib/calls/helpers/getVideoConstraints';\nimport {logger} from '@lib/logger';\n\nconst log = logger('GROUP-CALL');\n\nexport type MainStreamManager = StreamManager & {\n  // `inputError` remains as the compatibility alias for microphone failures.\n  // Callers that expose media-specific UI should use the two explicit fields.\n  inputError?: unknown,\n  audioInputError?: unknown,\n  videoInputError?: unknown\n};\n\nexport default async function createMainStreamManager(muted?: boolean, joinVideo?: boolean) {\n  const constraints: MediaStreamConstraints = {\n    audio: getAudioConstraints(),\n    video: joinVideo && getVideoConstraints()\n  };\n\n  const streamManager = new StreamManager(GROUP_CALL_AMPLITUDE_ANALYSE_INTERVAL_MS) as MainStreamManager;\n\n  try {\n    const stream = await getStream(constraints, muted);\n    streamManager.addStream(stream, 'input');\n    return streamManager;\n  } catch(err) {\n    log.error('joinGroupCall combined getStream error', err, constraints);\n    if(!joinVideo) {\n      streamManager.inputError = streamManager.audioInputError = err;\n      streamManager.inputStream = new MediaStream();\n      return streamManager;\n    }\n  }\n\n  // getUserMedia is all-or-nothing: a camera-only denial rejects the combined\n  // request without exposing the already-usable microphone. Probe each kind\n  // independently after that failure so migration can continue audio-only (or\n  // video-only) and surface the error for the device that actually failed.\n  const [audioResult, videoResult] = await Promise.allSettled([\n    getStream({audio: constraints.audio}, muted),\n    getStream({video: constraints.video})\n  ]);\n\n  if(audioResult.status === 'fulfilled') {\n    streamManager.addStream(audioResult.value, 'input');\n  } else {\n    streamManager.inputError = streamManager.audioInputError = audioResult.reason;\n    log.error('joinGroupCall audio-only fallback failed', audioResult.reason, constraints.audio);\n  }\n\n  if(videoResult.status === 'fulfilled') {\n    streamManager.addStream(videoResult.value, 'input');\n  } else {\n    streamManager.videoInputError = videoResult.reason;\n    log.error('joinGroupCall video-only fallback failed', videoResult.reason, constraints.video);\n  }\n\n  return streamManager;\n}\n","/*\n * Main-thread proxy to an `encryptWorker.ts` instance. One host per call.\n *\n * Lifecycle:\n *   - `new EncryptWorkerHost()`           — spawns the worker.\n *   - `host.init(...)` / `host.applyBlock(...)` / etc. — typed RPC.\n *   - `host.on('status', cb)`             — subscribe to async events.\n *   - `host.terminate()`                  — clean shutdown.\n *\n * The host never sees the call's private key: the worker generates it\n * (`createKey`) and only the public half comes back — keep that property as\n * the worker integration matures.\n */\n\nimport EventListenerBase from '@helpers/eventListenerBase';\n// Vite's `?worker` suffix bundles encryptWorker.ts into a CLASSIC worker\n// (IIFE). RTCRtpScriptTransform delivery to receivers (recv direction) is\n// flaky in Chrome with module workers — Chrome 146 pumped only ~6 frames\n// before silently stopping under our SFU's setup, even with a no-op\n// passthrough handler. The W3C reference samples + production WebRTC apps\n// use classic workers, so we switch to that path.\nimport EncryptWorker from './encryptWorker.ts?worker';\nimport type {\n  HostRequest,\n  HostResponse,\n  RequestKind,\n  RequestResultMap,\n  WorkerEvent\n} from './encryptWorkerProtocol';\n\ntype Pending = {resolve: (v: unknown) => void; reject: (e: Error) => void};\n\n// Key destruction is best-effort, but thread termination is not. A wedged\n// crypto operation ahead of `destroy` in the worker RPC queue must not retain\n// the worker (and its key material) indefinitely.\nconst DESTROY_TIMEOUT_MS = 500;\n\ntype HostEvents = {\n  status: (event: Extract<WorkerEvent, {kind: 'status'}>) => void;\n  pendingOutbound: (event: Extract<WorkerEvent, {kind: 'pendingOutbound'}>) => void;\n  callFailed: (event: Extract<WorkerEvent, {kind: 'callFailed'}>) => void;\n  recvDiag: (event: Extract<WorkerEvent, {kind: 'recvDiag'}>) => void;\n  [key: string]: (...args: any[]) => any;\n};\n\nexport class EncryptWorkerHost extends EventListenerBase<HostEvents> {\n  private readonly worker: Worker;\n  private readonly pending = new Map<number, Pending>();\n  private nextId = 1;\n  private destroyed = false;\n  private failed = false;\n  private terminating = false;\n  private terminationPromise: Promise<void> | undefined;\n\n  constructor() {\n    super(false);\n    // Classic (IIFE) worker via Vite's `?worker` suffix. See the comment on\n    // the import for why module workers were ditched.\n    this.worker = new EncryptWorker({name: 'tde2e-encrypt'});\n    this.worker.addEventListener('message', this.onMessage);\n    this.worker.addEventListener('error', this.onError);\n  }\n\n  // ===== RPC methods =====\n  //\n  // One method per HostRequest kind. The TS signature mirrors the protocol's\n  // `args` shape and the response type comes from `RequestResultMap`.\n\n  /** Generate the call key inside the worker; only the public key comes back. */\n  public createKey(): Promise<RequestResultMap['createKey']> {\n    return this.invoke('createKey');\n  }\n\n  public createZeroBlock(args: Extract<HostRequest, {kind: 'createZeroBlock'}>['args']): Promise<RequestResultMap['createZeroBlock']> {\n    return this.invoke('createZeroBlock', args);\n  }\n\n  public createSelfAddBlock(args: Extract<HostRequest, {kind: 'createSelfAddBlock'}>['args']): Promise<RequestResultMap['createSelfAddBlock']> {\n    return this.invoke('createSelfAddBlock', args);\n  }\n\n  public init(args: Extract<HostRequest, {kind: 'init'}>['args']): Promise<RequestResultMap['init']> {\n    return this.invoke('init', args);\n  }\n\n  /** Build and retain a rejoin block with the private key already in worker memory. */\n  public prepareRejoinBlock(\n    args: Extract<HostRequest, {kind: 'prepareRejoinBlock'}>['args']\n  ): Promise<RequestResultMap['prepareRejoinBlock']> {\n    return this.invoke('prepareRejoinBlock', args);\n  }\n\n  /** Re-anchor to the exact block returned by the latest prepareRejoinBlock call. */\n  public commitRejoinBlock(): Promise<RequestResultMap['commitRejoinBlock']> {\n    return this.invoke('commitRejoinBlock');\n  }\n\n  public applyBlock(args: Extract<HostRequest, {kind: 'applyBlock'}>['args']): Promise<RequestResultMap['applyBlock']> {\n    return this.invoke('applyBlock', args);\n  }\n\n  public buildRemoveParticipantsBlock(\n    args: Extract<HostRequest, {kind: 'buildRemoveParticipantsBlock'}>['args']\n  ): Promise<RequestResultMap['buildRemoveParticipantsBlock']> {\n    return this.invoke('buildRemoveParticipantsBlock', args);\n  }\n\n  public pullOutbound(): Promise<RequestResultMap['pullOutbound']> {\n    return this.invoke('pullOutbound');\n  }\n\n  public receiveInbound(args: Extract<HostRequest, {kind: 'receiveInbound'}>['args']): Promise<RequestResultMap['receiveInbound']> {\n    return this.invoke('receiveInbound', args);\n  }\n\n  public getStatus(): Promise<RequestResultMap['getStatus']> {\n    return this.invoke('getStatus');\n  }\n\n  // Send `destroy` to the worker (wiping the key) then terminate it.\n  public terminate(): Promise<void> {\n    if(this.terminationPromise) return this.terminationPromise;\n    if(this.destroyed) return Promise.resolve();\n\n    this.terminating = true;\n    this.terminationPromise = this.terminateInternal();\n    return this.terminationPromise;\n  }\n\n  // Construct an `RTCRtpScriptTransform` attached to this worker. The caller\n  // assigns the returned transform to an `RTCRtpSender.transform` (for the\n  // 'send' direction) or `RTCRtpReceiver.transform` ('recv').\n  //\n  // - `channelId` is the e2e logical stream id (0-1023). Pick a stable value\n  //   per (sender, media kind) — see notes/call.md.\n  // - `unencryptedPrefixLength` keeps the leading N codec bytes in the clear\n  //   (still authenticated). Defaults to 0; set to a small value (e.g. 1)\n  //   for VP8 picture-descriptor visibility to the SFU.\n  // - `kind` controls the libtgcalls audio-frame trailer (mandatory on Opus\n  //   for the official client to accept our frames). Pass the actual\n  //   `track.kind` of the sender/receiver. Defaults to 'audio' if omitted.\n  // - 'recv' transforms dispatch per-frame: each encoded frame's\n  //   `synchronizationSource` is looked up in the worker's SSRC → user_id\n  //   table (populated via `setSsrcUsers`) to choose the verification key.\n  //   No per-receiver `fromUserId` is needed — the same transform handles\n  //   every SFU-multiplexed sender on its mid.\n  public newRtcScriptTransform(options: {\n    direction: 'send' | 'recv';\n    channelId: number;\n    unencryptedPrefixLength?: number;\n    // Media kind of the track this transform is attached to. Drives the\n    // libtgcalls audio-frame trailer wrap/strip in the worker — see\n    // encryptWorker.ts (appendAudioTrailer / stripAudioTrailer).\n    // Video frames are passed through raw.\n    kind?: 'audio' | 'video';\n  }): RTCRtpScriptTransform {\n    // RTCRtpScriptTransform may not be in older TS DOM libs; access via\n    // globalThis to avoid build-target issues.\n    const Ctor = (globalThis as unknown as {RTCRtpScriptTransform?: typeof RTCRtpScriptTransform}).RTCRtpScriptTransform;\n    if(!Ctor) throw new Error('RTCRtpScriptTransform is not supported in this browser');\n    return new Ctor(this.worker, options);\n  }\n\n  // Push the SSRC → user_id table to the worker. Call whenever the SFU\n  // participant set changes — the recv transform consults this on every\n  // inbound frame. Unknown SSRCs are dropped silently.\n  public setSsrcUsers(entries: Array<[number, bigint]>): Promise<void> {\n    return this.invoke('setSsrcUsers', {entries});\n  }\n\n  // ===== Internal =====\n\n  private invoke<K extends RequestKind>(\n    kind: K,\n    args?: K extends 'createKey' | 'pullOutbound' | 'getStatus' | 'commitRejoinBlock' | 'destroy' ?\n      undefined :\n      Extract<HostRequest, {kind: K}> extends {args: infer A} ? A : undefined\n  ): Promise<RequestResultMap[K]> {\n    if(this.failed && kind !== 'destroy') {\n      return Promise.reject(new Error('EncryptWorkerHost: failed'));\n    }\n    if(this.destroyed) {\n      return Promise.reject(new Error('EncryptWorkerHost: terminated'));\n    }\n    if(this.terminating && kind !== 'destroy') {\n      return Promise.reject(new Error('EncryptWorkerHost: terminating'));\n    }\n    const id = this.nextId++;\n    return new Promise<RequestResultMap[K]>((resolve, reject) => {\n      this.pending.set(id, {\n        resolve: (v: unknown) => resolve(v as RequestResultMap[K]),\n        reject\n      });\n      const req = {kind, id, ...(args !== undefined ? {args} : {})} as HostRequest;\n      try {\n        this.worker.postMessage(req);\n      } catch(err) {\n        this.pending.delete(id);\n        reject(err instanceof Error ? err : new Error(String(err)));\n      }\n    });\n  }\n\n  private async terminateInternal(): Promise<void> {\n    try {\n      await this.invokeDestroyWithTimeout();\n    } catch{\n      // Best-effort explicit wipe. The finally block always reclaims the worker\n      // thread even when destroy rejects or never reaches the head of its queue.\n    } finally {\n      this.destroyed = true;\n      this.worker.removeEventListener('message', this.onMessage);\n      this.worker.removeEventListener('error', this.onError);\n      this.worker.terminate();\n      this.rejectPending(new Error('Worker terminated'));\n      super.cleanup();\n    }\n  }\n\n  private invokeDestroyWithTimeout(): Promise<void> {\n    return new Promise((resolve) => {\n      let settled = false;\n      const finish = () => {\n        if(settled) return;\n        settled = true;\n        clearTimeout(timer);\n        resolve();\n      };\n      const timer = setTimeout(finish, DESTROY_TIMEOUT_MS);\n      this.invoke('destroy').then(finish, finish);\n    });\n  }\n\n  private rejectPending(error: Error): void {\n    for(const {reject} of this.pending.values()) reject(error);\n    this.pending.clear();\n  }\n\n  private onMessage = (ev: MessageEvent<HostResponse>) => {\n    if(this.destroyed) return;\n    const msg = ev.data;\n    if(msg.kind === 'event') {\n      if(this.failed) return;\n      // @ts-ignore - dispatchEvent's signature is too strict for our union.\n      this.dispatchEvent(msg.event.kind, msg.event);\n      return;\n    }\n    const pending = this.pending.get(msg.id);\n    if(!pending) return;\n    this.pending.delete(msg.id);\n    if(msg.kind === 'ok') pending.resolve(msg.result);\n    else pending.reject(new Error(msg.message));\n  };\n\n  private onError = (ev: ErrorEvent) => {\n    // A worker-level error means the crypto runtime itself is no longer a\n    // trustworthy RPC endpoint, even when no request happened to be pending.\n    // Fail exactly once, stop accepting work and route the call through the\n    // same fail-closed recovery path as an explicit worker `callFailed` event.\n    if(this.failed || this.terminating || this.destroyed) return;\n\n    this.failed = true;\n    const message = ev.message || 'Encryption worker failed';\n    const error = new Error(message);\n    this.rejectPending(error);\n\n    this.dispatchEvent('callFailed', {kind: 'callFailed', message});\n    void this.terminate();\n  };\n}\n","import getGroupCallAudioAsset from '@components/groupCall/getAudioAsset';\nimport {DEBUG, MOUNT_CLASS_TO} from '@config/debug';\nimport {IS_CHROMIUM} from '@environment/userAgent';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport noop from '@helpers/noop';\nimport {GroupCallParticipant, GroupCallParticipantVideo, GroupCallParticipantVideoSourceGroup} from '@layer';\nimport {GroupCallId, GroupCallConnectionType} from '@appManagers/appGroupCallsManager';\nimport {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport type GroupCallConnectionInstance from '@lib/calls/groupCallConnectionInstance';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\nimport createMainStreamManager from '@lib/calls/helpers/createMainStreamManager';\nimport {\n  findGroupCallChainUpdate\n} from '@lib/calls/helpers/groupCallUpdates';\nimport sameInputGroupCall from '@lib/calls/helpers/sameInputGroupCall';\nimport {isSdpSafeSourceGroups, isSdpSafeString} from '@lib/calls/helpers/sdpSafety';\nimport senderKind from '@lib/calls/helpers/senderKind';\nimport {generateSsrc} from '@lib/calls/localConferenceDescription';\nimport {WebRTCLineType} from '@lib/calls/sdpBuilder';\nimport StreamManager from '@lib/calls/streamManager';\nimport {Ssrc} from '@lib/calls/types';\nimport {EncryptWorkerHost} from '@lib/calls/e2e/encryptWorkerHost';\nimport type {GroupParticipant} from '@lib/calls/e2e/tlTypes';\nimport type {InputGroupCall, Updates} from '@layer';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport {toastNew} from '@components/toast';\n\nconst IS_MUTED = true;\n\n// How long after ICE reaches `connected` we still allow the full RTCPeerConnection\n// (which only flips to `connected` once DTLS completes) to come up before we treat\n// the media transport as stalled. DTLS normally finishes in well under a second;\n// 10s is generous and avoids false positives on slow networks.\nconst CONNECTION_ESTABLISH_TIMEOUT_MS = 10000;\nconst MEDIA_LIVENESS_INTERVAL_MS = 5000;\nconst OUTBOUND_MEDIA_BLACKHOLE_PROGRESS_SAMPLES = 3;\nconst OUTBOUND_MEDIA_MIN_PACKETS = 10;\nconst OUTBOUND_MEDIA_MIN_RMS = .01;\nconst OUTBOUND_MEDIA_BLACKHOLE_REASON = 'outbound-media-blackhole';\n\ntype ConferenceRtcStat = RTCStats & {\n  kind?: string,\n  mediaType?: string,\n  packetsSent?: number,\n  remoteId?: string,\n  localId?: string,\n  ssrc?: number,\n  transportId?: string,\n  mediaSourceId?: string,\n  selectedCandidatePairId?: string,\n  selected?: boolean,\n  nominated?: boolean,\n  state?: string,\n  totalAudioEnergy?: number,\n  totalSamplesDuration?: number\n};\n\ntype ConferenceJoinOptions = {\n  input: InputGroupCall;\n  // Slug/invite-message joins keep `input` as their authorization. This is the\n  // canonical identity resolved for preview and used only to validate every\n  // response before promotion.\n  expectedCanonicalInput?: InputGroupCall.inputGroupCall;\n  selfUserId: bigint;\n  chatId?: ChatId;\n  muted?: boolean;\n  joinVideo?: boolean;\n  /** Present only for an automatic recovery that can be cancelled by a new call. */\n  transitionGeneration?: number;\n  /** Prevents an automatic media-blackhole recovery from rejoining in a loop. */\n  outboundMediaRecoveryUsed?: boolean;\n};\ntype ConferenceStartOptions = {\n  chatId?: ChatId;\n  selfUserId: bigint;\n  muted?: boolean;\n  joinVideo?: boolean;\n};\n\nclass ConferenceTransitionCancelledError extends Error {}\n\nexport function makeSsrcsFromParticipant(participant: GroupCallParticipant) {\n  // A source group's semantics goes into `a=ssrc-group:` verbatim and its\n  // sources into every `a=ssrc:` line, the endpoint into the stream name — a\n  // malformed one is dropped here rather than handed to the SDP builder.\n  const isSafeVideo = (video: GroupCallParticipantVideo) => {\n    return video && isSdpSafeSourceGroups(video.source_groups) && isSdpSafeString(video.endpoint);\n  };\n  const video = isSafeVideo(participant.video) ? participant.video : undefined;\n  const presentation = isSafeVideo(participant.presentation) ? participant.presentation : undefined;\n  return [\n    makeSsrcFromParticipant(participant, 'audio', participant.source),\n    video?.audio_source && makeSsrcFromParticipant(participant, 'audio', video.audio_source),\n    video && makeSsrcFromParticipant(participant, 'video', video.source_groups, video.endpoint),\n    presentation?.audio_source && makeSsrcFromParticipant(participant, 'audio', presentation.audio_source),\n    presentation && makeSsrcFromParticipant(participant, 'video', presentation.source_groups, presentation.endpoint)\n  ].filter(Boolean);\n};\n\nexport function makeSsrcFromParticipant(participant: GroupCallParticipant, type: WebRTCLineType, source?: number | GroupCallParticipantVideoSourceGroup[], endpoint?: string): Ssrc {\n  return generateSsrc(type, source, endpoint);\n}\n\nexport function generateSelfVideo(source: Ssrc, audioSource?: number): GroupCallParticipantVideo {\n  return source && {\n    _: 'groupCallParticipantVideo',\n    pFlags: {},\n    endpoint: '',\n    source_groups: source.sourceGroups,\n    audio_source: audioSource\n  };\n}\n\nexport class GroupCallsController extends EventListenerBase<{\n  instance: (instance: GroupCallInstance, isRecovery?: boolean) => void\n}> {\n  private audioAsset: ReturnType<typeof getGroupCallAudioAsset>;\n  private log: ReturnType<typeof logger>;\n  private currentGroupCall: GroupCallInstance;\n  private managers: AppManagers;\n  private pendingConferenceJoin: {\n    key: string,\n    promise: Promise<GroupCallInstance>\n  } | undefined;\n  private recoveringConferences = new WeakSet<GroupCallInstance>();\n  private conferenceRecoveryAuthorizations = new WeakMap<\n    GroupCallInstance,\n    Pick<ConferenceJoinOptions, 'input' | 'expectedCanonicalInput'>\n  >();\n  private conferenceTransitionGeneration = 0;\n  private conferenceRecovery?: {generation: number, promise: Promise<void>};\n  private conferenceTransitionReservations = 0;\n  private pendingConferenceRecovery?: {instance: GroupCallInstance, reason: string};\n  private outboundMediaRecoveryUsed = new WeakSet<GroupCallInstance>();\n\n  public construct(managers: AppManagers) {\n    this.managers = managers;\n    this.audioAsset = getGroupCallAudioAsset();\n    this.log = logger('GCC');\n\n    rootScope.addEventListener('group_call_update', (groupCall) => {\n      const {currentGroupCall} = this;\n      if(currentGroupCall?.id === groupCall.id) {\n        currentGroupCall.groupCall = groupCall;\n\n        if(groupCall._ === 'groupCallDiscarded') {\n          void currentGroupCall.hangUp(false, false, true).catch((err) => {\n            this.log.error('cleanup after discarded group call failed', err);\n          });\n        }\n      }\n    });\n\n    rootScope.addEventListener('group_call_participant', ({groupCallId, participant}) => {\n      const {currentGroupCall} = this;\n      if(currentGroupCall?.id === groupCallId) {\n        currentGroupCall.onParticipantUpdate(participant);\n      }\n    });\n\n    // A closed tab used to linger as a ghost participant until the server timed\n    // it out — still listed, still holding a chain key in a conference. The\n    // SharedWorker outlives this tab, so a leave posted from pagehide reaches\n    // the server. Best-effort by design: not awaited, no UI teardown (the page\n    // is going away), and never a discard.\n    if(typeof window !== 'undefined') {\n      window.addEventListener('pagehide', () => this.leaveOnPageHide());\n    }\n  }\n\n  private leaveOnPageHide(): void {\n    const instance = this.currentGroupCall;\n    if(!instance) return;\n    const target = this.resolveLeaveTarget(instance, instance.connections.main);\n    if(!target) return;\n    void this.managers.appGroupCallsManager.leaveGroupCall(target.input, target.source).catch(noop);\n  }\n\n  // The server-side identity + audio source a leave for `instance` is addressed\n  // with — the reference phone.joinGroupCall accepted when there is one.\n  private resolveLeaveTarget(\n    instance: GroupCallInstance,\n    connectionInstance: GroupCallConnectionInstance | undefined,\n    fallbackInput?: InputGroupCall\n  ): {input: InputGroupCall, source: number} | undefined {\n    const input = connectionInstance?.acceptedCallInput ?? fallbackInput ?? instance.toInputGroupCall();\n    if(!input) return;\n    const source = connectionInstance?.sources.audio?.source;\n    return {input, source: typeof source === 'number' ? source : 0};\n  }\n\n  get groupCall() {\n    return this.currentGroupCall;\n  }\n\n  public setCurrentGroupCall(groupCall: GroupCallInstance, isRecovery = false) {\n    this.currentGroupCall = groupCall;\n\n    if(groupCall) {\n      this.dispatchEvent('instance', groupCall, isRecovery);\n    }\n  }\n\n  /**\n   * Reserve the call-transition window before its first asynchronous step.\n   * While at least one reservation is held, conference liveness cannot start a\n   * replacement join. An already-running recovery is cancelled and fully\n   * cleaned up before the caller receives its release token.\n   */\n  public async reserveConferenceTransition(): Promise<() => void> {\n    ++this.conferenceTransitionReservations;\n    let released = false;\n    const release = () => {\n      if(released) return;\n      released = true;\n      --this.conferenceTransitionReservations;\n      this.drainPendingConferenceRecovery();\n    };\n\n    try {\n      await this.cancelCurrentConferenceRecovery();\n      return release;\n    } catch(err) {\n      release();\n      throw err;\n    }\n  }\n\n  private async cancelCurrentConferenceRecovery(): Promise<void> {\n    const recovery = this.conferenceRecovery;\n    if(!recovery) return;\n    ++this.conferenceTransitionGeneration;\n    await recovery.promise;\n  }\n\n  private drainPendingConferenceRecovery(): void {\n    if(this.conferenceTransitionReservations || this.pendingConferenceJoin || !this.pendingConferenceRecovery) return;\n\n    const pending = this.pendingConferenceRecovery;\n    this.pendingConferenceRecovery = undefined;\n    void this.recoverConference(pending.instance, pending.reason);\n  }\n\n  public startConnectingSound() {\n    this.stopConnectingSound();\n    this.audioAsset.playWithTimeout({name: 'connect', loop: true}, 2500);\n  }\n\n  public stopConnectingSound() {\n    this.audioAsset.stop();\n    this.audioAsset.cancelDelayedPlay();\n  }\n\n  private hangUpAfterTransportFailure(instance: GroupCallInstance): void {\n    void instance.hangUp().catch((err) => {\n      this.log.warn('group call leave after transport failure failed', err);\n    });\n  }\n\n  public async joinGroupCall(chatId: ChatId, groupCallId: GroupCallId, muted = IS_MUTED, rejoin?: boolean, joinVideo?: boolean) {\n    this.audioAsset.createAudio();\n\n    this.log(`joinGroupCall chatId=${chatId} id=${groupCallId} muted=${muted} rejoin=${rejoin}`);\n\n    let streamManager: StreamManager;\n    if(rejoin) {\n      streamManager = this.currentGroupCall.connections.main.streamManager;\n    } else {\n      streamManager = await createMainStreamManager(muted, joinVideo);\n    }\n\n    return this.joinGroupCallInternal(chatId, groupCallId, streamManager, muted, rejoin, joinVideo)\n    .then(() => {\n      // have to refresh participants because of the new connection\n      const {currentGroupCall} = this;\n      if(!currentGroupCall) return;\n      void currentGroupCall.participants.then((participants) => {\n        if(this.currentGroupCall !== currentGroupCall || currentGroupCall.state === GROUP_CALL_STATE.CLOSED) {\n          return;\n        }\n\n        participants.forEach((participant) => {\n          if(!participant.pFlags.self) {\n            currentGroupCall.onParticipantUpdate(participant);\n          }\n        });\n      }).catch((err) => {\n        // The transport join is already accepted. Initial roster hydration is\n        // best-effort and will be refreshed by later participant updates, but\n        // the worker-proxy rejection still needs an observer.\n        this.log.warn('initial group call participant hydration failed', err);\n      });\n    });\n  }\n\n  private async joinGroupCallInternal(chatId: ChatId, groupCallId: GroupCallId, streamManager: StreamManager, muted: boolean, rejoin = false, joinVideo?: boolean) {\n    const log = this.log.bindPrefix('joinGroupCallInternal');\n    log('start', groupCallId);\n\n    const type: GroupCallConnectionType = 'main';\n\n    let {currentGroupCall} = this;\n    if(currentGroupCall && rejoin) {\n      // currentGroupCall.connections.main.connection = connection;\n      currentGroupCall.handleUpdateGroupCallParticipants = false;\n      currentGroupCall.updatingSdp = false;\n      log('update currentGroupCall', groupCallId, currentGroupCall);\n    } else {\n      currentGroupCall = new GroupCallInstance({\n        chatId,\n        id: groupCallId,\n        managers: this.managers\n      });\n\n      try {\n        currentGroupCall.fixSafariAudio();\n\n        currentGroupCall.addEventListener('state', (state) => {\n          if(this.currentGroupCall === currentGroupCall && state === GROUP_CALL_STATE.CLOSED) {\n            this.setCurrentGroupCall(null);\n            this.stopConnectingSound();\n            this.audioAsset.play({name: 'end'});\n            rootScope.dispatchEvent('chat_update', currentGroupCall.chatId);\n          }\n        });\n\n        currentGroupCall.groupCall = await this.managers.appGroupCallsManager.getGroupCallFull(groupCallId);\n\n        const connectionInstance = currentGroupCall.createConnectionInstance({\n          streamManager,\n          type,\n          options: {\n            type,\n            isMuted: muted,\n            joinVideo,\n            rejoin\n          }\n        });\n\n        const connection = connectionInstance.createPeerConnection();\n        let initialNegotiationCompleted = false;\n        connection.addEventListener('negotiationneeded', () => {\n          void connectionInstance.requestNegotiation().catch((err) => {\n            // The explicit initial request below observes its own failure and\n            // lets the join transaction roll back. Later dirty negotiations are\n            // event-owned and must fail closed instead of rejecting unobserved.\n            if(!initialNegotiationCompleted ||\n               this.currentGroupCall !== currentGroupCall ||\n               currentGroupCall.isClosing) {\n              return;\n            }\n            log.error('group call runtime negotiation failed', err);\n            this.hangUpAfterTransportFailure(currentGroupCall);\n          });\n        });\n\n        connection.addEventListener('track', (event) => {\n          log('ontrack', event);\n          currentGroupCall.onTrack(event);\n        });\n\n        // Media-transport watchdog. GroupCallInstance.connectionState (and thus the\n        // call UI) reports the ICE state ONLY, so a call where ICE reaches\n        // `connected` but the RTCPeerConnection never does — the DTLS handshake\n        // stalls, observed on restrictive networks / some VPNs — looks \"connected\"\n        // while NO media ever flows: black video tiles, silence, the SFU data\n        // channel never opens, no error anywhere. Watch the REAL connectionState\n        // (which only flips to `connected` once DTLS completes) and, if it doesn't\n        // get there shortly after ICE does, surface it and end the dead call\n        // instead of leaving the user staring at a silent black call.\n        let connectionWatchdog: number;\n        const clearConnectionWatchdog = () => {\n          if(connectionWatchdog) {\n            clearTimeout(connectionWatchdog);\n            connectionWatchdog = undefined;\n          }\n        };\n        const armConnectionWatchdog = () => {\n          clearConnectionWatchdog();\n          connectionWatchdog = window.setTimeout(() => {\n            connectionWatchdog = undefined;\n            const {connectionState} = connection;\n            if(connectionState === 'connected') return;\n            if(this.currentGroupCall !== currentGroupCall) return;\n            log.warn('media transport stall: ICE connected but connectionState =', connectionState, '— ending call');\n            currentGroupCall.reportMediaTransportStall({connectionState, iceConnectionState: connection.iceConnectionState});\n            this.hangUpAfterTransportFailure(currentGroupCall);\n          }, CONNECTION_ESTABLISH_TIMEOUT_MS);\n        };\n\n        connection.addEventListener('connectionstatechange', () => {\n          const {connectionState} = connection;\n          if(connectionState === 'connected') {\n            clearConnectionWatchdog();\n          } else if(connectionState === 'failed') {\n            // ICE can sit at `connected` while DTLS fails, so the ICE 'failed'\n            // branch below never fires — end the call on a failed transport here.\n            clearConnectionWatchdog();\n            this.hangUpAfterTransportFailure(currentGroupCall);\n          }\n        });\n\n        connection.addEventListener('iceconnectionstatechange', () => {\n          currentGroupCall.dispatchEvent('state', currentGroupCall.state);\n\n          const {iceConnectionState} = connection;\n          if(iceConnectionState === 'disconnected' || iceConnectionState === 'checking' || iceConnectionState === 'new') {\n            this.startConnectingSound();\n          } else {\n            this.stopConnectingSound();\n          }\n\n          switch(iceConnectionState) {\n            case 'checking': {\n              break;\n            }\n\n            case 'closed': {\n              clearConnectionWatchdog();\n              this.hangUpAfterTransportFailure(currentGroupCall);\n              break;\n            }\n\n            case 'completed': {\n              break;\n            }\n\n            case 'connected': {\n              // ICE is up; give DTLS a bounded window to finish (see watchdog above).\n              armConnectionWatchdog();\n\n              if(!currentGroupCall.joined) {\n                currentGroupCall.joined = true;\n                this.audioAsset.play({name: 'start'});\n                void this.managers.appGroupCallsManager.getGroupCallParticipants(groupCallId).catch((err) => {\n                  log.warn('initial group call participant fetch failed', err);\n                });\n              }\n\n              break;\n            }\n\n            case 'disconnected': {\n              break;\n            }\n\n            case 'failed': {\n              clearConnectionWatchdog();\n              // TODO: replace with ICE restart\n              this.hangUpAfterTransportFailure(currentGroupCall);\n              // connection.restartIce();\n              break;\n            }\n\n            case 'new': {\n              break;\n            }\n          }\n        });\n\n        connectionInstance.createDescription();\n        connectionInstance.createDataChannel();\n\n        await connectionInstance.appendStreamToConference();\n\n        this.setCurrentGroupCall(currentGroupCall);\n        log('set currentGroupCall', groupCallId, currentGroupCall);\n\n        this.startConnectingSound();\n\n        await connectionInstance.requestNegotiation();\n        initialNegotiationCompleted = true;\n      } catch(err) {\n        // The microphone (and camera) were captured before this join started\n        // and nothing owns them yet when it fails here — the instance is not\n        // current, so no UI could release them. Undo the whole join instead of\n        // leaving the capture live until a reload.\n        await this.rollbackFailedJoin({\n          instance: currentGroupCall,\n          connectionInstance: currentGroupCall.connections.main,\n          streamManager\n        });\n        throw err;\n      }\n    }\n  }\n\n  // Undo everything a failed join built — close media, release the\n  // microphone/camera, drop the instance — and compensate a\n  // phone.joinGroupCall the server already accepted (it may have installed our\n  // participant and source even though worker commit, SDP parsing or\n  // remote-description setup failed afterwards). Compensates exactly once;\n  // teardown first keeps capture closed while the best-effort leave is in\n  // flight. Shared by the legacy and conference joins.\n  private async rollbackFailedJoin(opts: {\n    instance?: GroupCallInstance,\n    connectionInstance?: GroupCallConnectionInstance,\n    streamManager: StreamManager,\n    acceptedCall?: InputGroupCall,\n    discard?: boolean\n  }): Promise<void> {\n    const {instance, connectionInstance, streamManager} = opts;\n    this.stopConnectingSound();\n    if(!instance) {\n      streamManager.stop();\n      return;\n    }\n\n    const connectionTypes = Object.keys(instance.connections) as GroupCallConnectionType[];\n    for(const type of connectionTypes) {\n      instance.connections[type].closeConnectionAndStream(true);\n    }\n    // A join that failed before createConnectionInstance has no connection to\n    // stop the stream through.\n    if(!connectionTypes.length) streamManager.stop();\n    if(this.currentGroupCall === instance) {\n      instance.dispatchEvent('state', GROUP_CALL_STATE.CLOSED);\n      if(this.currentGroupCall === instance) this.setCurrentGroupCall(null);\n    }\n    instance.cleanup();\n\n    if(!connectionInstance?.joinAccepted) return;\n    const target = this.resolveLeaveTarget(instance, connectionInstance, opts.acceptedCall);\n    if(!target) return;\n    try {\n      if(opts.discard) {\n        await this.managers.appGroupCallsManager.discardGroupCall(target.input);\n      } else {\n        await this.managers.appGroupCallsManager.leaveGroupCall(target.input, target.source);\n      }\n    } catch(leaveError) {\n      this.log.warn('conference post-accept rollback failed', leaveError);\n    }\n  }\n\n  // ===== TdE2E conference call entry points =====\n  //\n  // Fresh starts submit their zero block and SDP atomically through\n  // phone.createConferenceCall(join=true). Joining an existing conference\n  // first polls its current chain tip, then submits a self-add (or zero block\n  // when the chain is empty) through phone.joinGroupCall.\n  // The signing key is born in the worker and never leaves it; this thread only\n  // learns the public key it advertises in the join payload.\n  private async createConferenceCrypto(selfUserId: bigint) {\n    const worker = new EncryptWorkerHost();\n    let publicKey: Uint8Array;\n    try {\n      publicKey = await worker.createKey();\n    } catch(err) {\n      await worker.terminate().catch((): undefined => undefined);\n      throw err;\n    }\n\n    const selfParticipant: GroupParticipant = {\n      userId: selfUserId,\n      publicKey,\n      canAddUsers: true,\n      canRemoveUsers: true,\n      version: 0\n    };\n\n    return {publicKey, selfParticipant, worker};\n  }\n\n  public startConference(opts: ConferenceStartOptions): Promise<GroupCallInstance> {\n    return this.runConferenceAttemptWithRetry(() => this.startConferenceAttempt(opts));\n  }\n\n  private async startConferenceAttempt(opts: ConferenceStartOptions): Promise<GroupCallInstance> {\n    const {publicKey, selfParticipant, worker} = await this.createConferenceCrypto(opts.selfUserId);\n    try {\n      const zeroBlock = await worker.createZeroBlock({\n        groupState: {participants: [selfParticipant], externalPermissions: 3}\n      });\n      return await this.joinConferenceCommon({\n        createConference: true,\n        worker,\n        publicKey,\n        selfUserId: opts.selfUserId,\n        lastBlockServer: zeroBlock,\n        chatId: opts.chatId,\n        muted: opts.muted,\n        joinVideo: opts.joinVideo\n      });\n    } catch(err) {\n      await worker.terminate().catch((): undefined => undefined);\n      throw err;\n    }\n  }\n\n  public inviteConferenceParticipant(userId: UserId, video?: boolean): Promise<Updates> {\n    const call = this.currentGroupCall?.toInputGroupCall();\n    if(!call || !this.currentGroupCall.e2e) {\n      return Promise.reject(new Error('No active conference call'));\n    }\n    return this.managers.appCallsManager.inviteConferenceCallParticipant(call, userId, video);\n  }\n\n  public declineConferenceInvite(messageId: number): Promise<Updates> {\n    return this.managers.appCallsManager.declineConferenceCallInvite(messageId);\n  }\n\n  // Drive an incoming conference (we've been invited or have the invite link).\n  // Fetches the latest block from the server, builds our self-add block,\n  // then joins the SFU.\n  public joinConference(opts: ConferenceJoinOptions): Promise<GroupCallInstance> {\n    const key = this.conferenceInputKey(opts.input);\n    const pending = this.pendingConferenceJoin;\n    if(pending) {\n      if(pending.key === key) return pending.promise;\n      return Promise.reject(new Error('CONFERENCE_JOIN_IN_PROGRESS'));\n    }\n\n    const promise = this.runConferenceAttemptWithRetry(\n      () => this.joinConferenceAttempt(opts),\n      true\n    ).finally(() => {\n      if(this.pendingConferenceJoin?.promise === promise) {\n        this.pendingConferenceJoin = undefined;\n        this.drainPendingConferenceRecovery();\n      }\n    });\n    this.pendingConferenceJoin = {key, promise};\n    return promise;\n  }\n\n  private async runConferenceAttemptWithRetry(\n    runAttempt: () => Promise<GroupCallInstance>,\n    retryMembershipRace = false\n  ): Promise<GroupCallInstance> {\n    const maxAttempts = 3;\n    for(let attempt = 0; ; attempt++) {\n      try {\n        return await runAttempt();\n      } catch(err) {\n        const errorType = this.apiErrorType(err);\n        const isSsrcCollision = errorType === 'GROUPCALL_SSRC_DUPLICATE_MUCH';\n        const isMembershipRace = retryMembershipRace && errorType?.startsWith('NOT_PARTICIPANT:');\n        if((!isSsrcCollision && !isMembershipRace) || attempt >= maxAttempts - 1) {\n          throw err;\n        }\n        this.log.warn(\n          isSsrcCollision ?\n            'conference join SSRC collision; rebuilding the whole media stack' :\n            'conference membership changed during join; rebuilding the whole media stack',\n          {attempt: attempt + 1}\n        );\n      }\n    }\n  }\n\n  private async joinConferenceAttempt(opts: ConferenceJoinOptions): Promise<GroupCallInstance> {\n    this.assertConferenceTransition(opts.transitionGeneration);\n    // All three `InputGroupCall` variants are accepted by\n    // `phone.getGroupCallChainBlocks` + `phone.joinGroupCall` server-side:\n    //   - inputGroupCall(id, access_hash) — the canonical form we already have\n    //   - inputGroupCallSlug(slug)        — invite-link join (no msg)\n    //   - inputGroupCallInviteMessage(msg_id) — invite-message join\n    // The latter two return the real id+access_hash inside the join response.\n    // tdesktop: calls_group_call.cpp:4251 `inputCallSafe`.\n    if(opts.input._ !== 'inputGroupCall' &&\n       opts.input._ !== 'inputGroupCallSlug' &&\n       opts.input._ !== 'inputGroupCallInviteMessage') {\n      throw new Error(`joinConference: unsupported call ref kind ${(opts.input as any)._}`);\n    }\n    if(opts.input._ !== 'inputGroupCall' && !opts.expectedCanonicalInput) {\n      throw new Error('joinConference: non-canonical authorization requires an expected canonical identity');\n    }\n    if(opts.input._ === 'inputGroupCall' && opts.expectedCanonicalInput &&\n       !sameInputGroupCall(opts.input, opts.expectedCanonicalInput)) {\n      throw new Error('joinConference: canonical input does not match its expected identity');\n    }\n    const {publicKey, selfParticipant, worker} = await this.createConferenceCrypto(opts.selfUserId);\n    const initialOffsets: Partial<{0: number; 1: number}> = {};\n    // Build the initial join block by polling the chain head and either making\n    // a self-add block on top of it or a zero block if the chain is empty.\n    const buildJoinBlock = async(): Promise<Uint8Array> => {\n      const head = await this.fetchLastConferenceBlock(opts.input, opts.expectedCanonicalInput);\n      initialOffsets[0] = head.nextOffset;\n      return head.block ?\n        worker.createSelfAddBlock({\n          previousBlockServer: head.block,\n          self: selfParticipant\n        }) :\n        worker.createZeroBlock({\n          groupState: {participants: [selfParticipant], externalPermissions: 3}\n        });\n    };\n\n    // On a chain race the worker is already initialised, so it signs the\n    // replacement with its retained key.\n    const rebuildJoinBlock = async(): Promise<Uint8Array> => {\n      const head = await this.fetchLastConferenceBlock(opts.input, opts.expectedCanonicalInput);\n      initialOffsets[0] = head.nextOffset;\n      if(!head.block) {\n        throw new Error('Conference chain stayed empty after CONF_WRITE_CHAIN_INVALID');\n      }\n      return worker.prepareRejoinBlock({\n        previousBlockServer: head.block,\n        self: selfParticipant\n      });\n    };\n\n    try {\n      // Always poll the chain head first. tdlib does this for both \"create\"\n      // and \"join\" — see GroupCallManager.cpp:4445 try_join_group_call.\n      const joinBlock = await buildJoinBlock();\n      this.assertConferenceTransition(opts.transitionGeneration);\n\n      return await this.joinConferenceCommon({\n        input: opts.input,\n        expectedCanonicalInput: opts.expectedCanonicalInput,\n        worker,\n        publicKey,\n        selfUserId: opts.selfUserId,\n        lastBlockServer: joinBlock,\n        initialOffsets,\n        rebuildBlock: rebuildJoinBlock,\n        commitRebuiltBlock: async() => {\n          await worker.commitRejoinBlock();\n        },\n        chatId: opts.chatId,\n        muted: opts.muted,\n        joinVideo: opts.joinVideo,\n        transitionGeneration: opts.transitionGeneration,\n        outboundMediaRecoveryUsed: opts.outboundMediaRecoveryUsed\n      });\n    } catch(e) {\n      await worker.terminate().catch((): undefined => undefined);\n      throw e;\n    }\n  }\n\n  // Shared tail of both startConference and joinConference: spin up the\n  // GroupCallInstance, attach the worker, drive joinGroupCallInternal with\n  // the e2e extras (public_key + block).\n  private async joinConferenceCommon(opts: {\n    // Reference to the conference. `inputGroupCall` (id+access_hash) for the\n    // creator and previously-resolved joinees; `inputGroupCallSlug` for fresh\n    // invite-link joins (the actual id+access_hash come back in the join\n    // response). `undefined` only in the legacy create-mode path.\n    input?: InputGroupCall;\n    createConference?: boolean;\n    expectedCanonicalInput?: InputGroupCall.inputGroupCall;\n    worker: EncryptWorkerHost;\n    publicKey: Uint8Array;\n    selfUserId: bigint;\n    lastBlockServer: Uint8Array;\n    initialOffsets?: Partial<{0: number; 1: number}>;\n    chatId?: ChatId;\n    muted?: boolean;\n    joinVideo?: boolean;\n    transitionGeneration?: number;\n    outboundMediaRecoveryUsed?: boolean;\n    // Optional rebuild callback — invoked by the connection layer when the\n    // server returns CONF_WRITE_CHAIN_INVALID (chain advanced mid-flight).\n    // Should refetch chain head + return a freshly-built block.\n    rebuildBlock?: () => Promise<Uint8Array>;\n    // Commit the exact rebuilt proposal inside the worker after the server\n    // accepted it. This preserves packet sequence/replay state and never\n    // re-exposes the private seed to the main thread.\n    commitRebuiltBlock?: () => Promise<void>;\n  }): Promise<GroupCallInstance> {\n    this.audioAsset.createAudio();\n    const streamManager = await createMainStreamManager(opts.muted ?? true, opts.joinVideo);\n    try {\n      this.assertConferenceTransition(opts.transitionGeneration);\n    } catch(err) {\n      streamManager.stop();\n      throw err;\n    }\n    if(streamManager.audioInputError) {\n      toastNew({langPackKey: 'NoMicrophoneAccess'});\n    }\n    if(streamManager.videoInputError) {\n      toastNew({langPackKey: 'ConferenceCall.Media.CameraError'});\n    }\n    let instance: GroupCallInstance | undefined;\n    let connectionInstance: GroupCallConnectionInstance | undefined;\n    let joinedSuccessfully = false;\n\n    try {\n      // Pick a stable placeholder id for the instance until the real id arrives\n      // in the join response. For id-form input we already know it; for slug or\n      // create modes we use a synthetic id and let the join flow rewrite it.\n      // For id-form input keep the id in its native (fetchLong) form so it stays\n      // === the manager's cache key; slug/create modes get a synthetic sentinel\n      // that the join response rewrites to the real id.\n      const placeholderId = (opts.input && opts.input._ === 'inputGroupCall') ?\n        opts.input.id :\n        `pending-conf-${Date.now()}`;\n      const createdInstance = new GroupCallInstance({\n        chatId: opts.chatId ?? NULL_PEER_ID,\n        id: placeholderId,\n        managers: this.managers\n      });\n      instance = createdInstance;\n      if(opts.outboundMediaRecoveryUsed) {\n        this.outboundMediaRecoveryUsed.add(createdInstance);\n      }\n      if(opts.input && opts.input._ !== 'inputGroupCall') {\n        this.conferenceRecoveryAuthorizations.set(createdInstance, {\n          input: opts.input,\n          expectedCanonicalInput: opts.expectedCanonicalInput\n        });\n      }\n      createdInstance.addEventListener('conferenceRecoveryRequired', (reason) => {\n        void this.recoverConference(createdInstance, reason);\n      });\n      instance.fixSafariAudio();\n      instance.attachE2e(opts.worker, opts.selfUserId, opts.initialOffsets);\n\n      connectionInstance = instance.createConnectionInstance({\n        streamManager,\n        type: 'main',\n        options: {\n          type: 'main',\n          isMuted: opts.muted ?? true,\n          joinVideo: opts.joinVideo,\n          rejoin: false,\n          e2ePublicKey: opts.publicKey,\n          e2eBlock: opts.lastBlockServer,\n          e2eCreateConference: opts.createConference,\n          // Pass non-id-form input straight through. The default codepath\n          // (getGroupCallInput) would synthesise id+access_hash from our\n          // placeholder id, which the server rejects for invitees.\n          e2eCallInput: (opts.input && opts.input._ !== 'inputGroupCall') ? opts.input : undefined,\n          e2eExpectedCallInput: opts.expectedCanonicalInput,\n          // Wire rebuild callback so the connection layer can recover from\n          // CONF_WRITE_CHAIN_INVALID without tearing down the WebRTC stack.\n          e2eRebuildBlock: opts.rebuildBlock,\n          e2eCommitRebuiltBlock: opts.commitRebuiltBlock && (async() => {\n            await opts.commitRebuiltBlock?.();\n            instance.advanceE2eChainOffsets(opts.initialOffsets || {});\n          }),\n          e2eActivate: () => instance.activateE2e()\n        }\n      });\n\n      // Hydrate the worker against the block we built/fetched; it signs with\n      // the key it generated in createConferenceCrypto.\n      await opts.worker.init({\n        userId: opts.selfUserId,\n        lastBlockServer: opts.lastBlockServer\n      });\n\n      instance.addEventListener('state', (state) => {\n        if(this.currentGroupCall === instance && state === GROUP_CALL_STATE.CLOSED) {\n          this.setCurrentGroupCall(null);\n          this.stopConnectingSound();\n          if(joinedSuccessfully && !this.recoveringConferences.has(instance)) {\n            this.audioAsset.play({name: 'end'});\n          }\n          if(joinedSuccessfully) {\n            void opts.worker.terminate().catch((): undefined => undefined);\n          }\n        }\n      });\n\n      // For id-form input we can hydrate the full call now. For slug-form input\n      // the access_hash is still unknown — we hydrate after joinGroupCall echoes\n      // back the real updateGroupCall with id+access_hash.\n      if(opts.input && opts.input._ === 'inputGroupCall') {\n        instance.groupCall = await this.managers.appGroupCallsManager\n        .getGroupCallFull(opts.input.id)\n        .catch((): GroupCallInstance['groupCall'] => undefined);\n      }\n\n      const connection = connectionInstance.createPeerConnection();\n      connection.addEventListener('negotiationneeded', () => {\n        void connectionInstance.requestNegotiation().catch((err) => {\n          // The explicit initial request below observes the same Promise and\n          // owns transaction rollback. Runtime negotiation failures must never\n          // become an unhandled rejection or a permanently-active dead entry.\n          if(!joinedSuccessfully || instance.isClosing || this.currentGroupCall !== instance) return;\n          this.log.error('conference runtime negotiation failed', err);\n          void this.recoverConference(instance, 'renegotiation-failed');\n        });\n      });\n      connection.addEventListener('track', (event) => instance.onTrack(event));\n      connection.addEventListener('iceconnectionstatechange', () => {\n        instance.dispatchEvent('state', instance.state);\n        // Mirror the legacy joinGroupCallInternal path (line ~192): bracket the\n        // looping `connect` tone around the pre-connected ICE states. Without\n        // this the tone plays forever even after we're fully joined — the UI\n        // reports CONNECTED but the audio asset never stops.\n        const {iceConnectionState} = connection;\n        if(iceConnectionState === 'disconnected' || iceConnectionState === 'checking' || iceConnectionState === 'new') {\n          this.startConnectingSound();\n        } else {\n          this.stopConnectingSound();\n        }\n        // On first transition to connected: fetch participants. The legacy\n        // joinGroupCall path does this (line ~217) — without it the SFU\n        // never sends us our own participant entry, leaving\n        // `instance.participant` undefined and the UI in a half-broken\n        // \"no self info\" state. Also play the join-success chime so the\n        // user has audible feedback that media is live.\n        if(iceConnectionState === 'connected' && !instance.joined) {\n          instance.joined = true;\n          if(opts.transitionGeneration === undefined) {\n            this.audioAsset.play({name: 'start'});\n          }\n          instance.requestSelfParticipantHydration();\n        }\n      });\n\n      connectionInstance.createDescription();\n      connectionInstance.createDataChannel();\n\n      // Senders: attach transform between createTransceiver and replaceTrack\n      // — the only window Chrome's script-transform machinery accepts. The\n      // streamManager hook fires synchronously in that gap; LocalConferenceDescription\n      // iterates audio first so the kind sequence matches `types`.\n      await connectionInstance.appendStreamToConference((sender) => {\n        // sender.track isn't bound yet; infer kind from the transceiver's\n        // receiver track (see senderKind). Main connection → default channel 0.\n        instance.attachE2eSendTransform(sender, senderKind(connection, sender));\n      }, true);\n\n      // Receive-side e2e transforms are attached PER REMOTE SSRC in\n      // GroupCallInstance.onParticipantUpdate, right after each recvonly\n      // transceiver is created and BEFORE its decoder binds — the only window\n      // Chrome accepts a recv transform. The SFU exposes no m-lines, only SSRCs\n      // (one per remote stream); we mint one recvonly m-line per SSRC exactly\n      // like a legacy voice chat. The previous model — pre-adding a single\n      // multiplexed recvonly audio + video m-line here and hoping every\n      // participant funnelled through it — was wrong: the SFU never reused\n      // those mids, and a lone receiver fed many SSRCs is what made Chrome pump\n      // ~5 frames then bypass the transform.\n      //\n      // This `track` listener is a defensive fallback only: the late-attach helper\n      // no-ops when the receiver already carries a transform, so it does anything\n      // at all only for a receiver that somehow wasn't attached at creation time\n      // — which it reports, because a late attach is not reliably honoured and\n      // that receiver's media may reach the decoder unauthenticated.\n      connection.addEventListener('track', (event) => {\n        const kind = event.track.kind === 'video' ? 'video' : 'audio';\n        instance.attachE2eRecvTransformLate(event.receiver, kind);\n      });\n\n      const isRecovery = opts.transitionGeneration !== undefined;\n      this.assertConferenceTransition(opts.transitionGeneration);\n      if(!isRecovery) {\n        this.setCurrentGroupCall(instance);\n      }\n      this.startConnectingSound();\n      await connectionInstance.requestNegotiation();\n      this.assertConferenceTransition(opts.transitionGeneration);\n      joinedSuccessfully = true;\n      if(isRecovery) {\n        this.setCurrentGroupCall(instance, true);\n        if(instance.joined) instance.requestSelfParticipantHydration();\n        // Roster rows dispatched while `currentGroupCall` was null (the whole\n        // recovery join, including the un-awaited activation-triggered walk)\n        // were saved into the manager cache but never routed to this instance —\n        // no recv transceivers, no e2e SSRC mappings. Replay the cache\n        // deterministically instead of waiting for the next complete poll.\n        void Promise.resolve()\n        .then(() => this.managers.appGroupCallsManager.getCachedParticipants(instance.id))\n        .then((cached) => {\n          if(this.currentGroupCall !== instance || instance.isClosing) return;\n          for(const participant of cached.values()) {\n            if(participant.pFlags.self) continue;\n            instance.onParticipantUpdate(participant);\n          }\n        })\n        .catch((err) => {\n          this.log.warn('cached participant replay after recovery failed', err);\n        });\n      }\n      window.setTimeout(() => {\n        if(this.currentGroupCall === instance && !instance.isClosing) {\n          this.startConferenceLiveness(instance);\n        }\n      }, 0);\n      return instance;\n    } catch(err) {\n      await this.rollbackFailedJoin({\n        instance,\n        connectionInstance,\n        streamManager,\n        acceptedCall: opts.input,\n        discard: opts.createConference\n      });\n      await opts.worker.terminate().catch((): undefined => undefined);\n      throw err;\n    }\n  }\n\n  private startConferenceLiveness(instance: GroupCallInstance): void {\n    const connection = instance.connections.main?.connection;\n    if(!connection) return;\n\n    let stopped = false;\n    let transportTimer: number | undefined;\n    let mediaTimer: number | undefined;\n    let mediaProbePending = false;\n    let selectedCandidatePairId: string | undefined;\n    let routeChangeObserved = false;\n    let previousOutboundPackets: number | undefined;\n    let previousSourceEnergy: number | undefined;\n    let previousSamplesDuration: number | undefined;\n    let previousRemoteInboundTimestamp: number | undefined;\n    let outboundProgressSamples = 0;\n\n    const clearTimer = (timer: number | undefined) => {\n      if(timer !== undefined) clearTimeout(timer);\n    };\n    const resetMediaActivity = () => {\n      previousOutboundPackets = undefined;\n      previousSourceEnergy = undefined;\n      previousSamplesDuration = undefined;\n      previousRemoteInboundTimestamp = undefined;\n      outboundProgressSamples = 0;\n    };\n    const resetMediaEvidence = () => {\n      selectedCandidatePairId = undefined;\n      routeChangeObserved = false;\n      resetMediaActivity();\n    };\n    const stopMediaProbe = () => {\n      if(mediaTimer !== undefined) clearInterval(mediaTimer);\n      mediaTimer = undefined;\n      resetMediaEvidence();\n    };\n    const stop = () => {\n      if(stopped) return;\n      stopped = true;\n      clearTimer(transportTimer);\n      transportTimer = undefined;\n      stopMediaProbe();\n    };\n    const recover = (reason: string) => {\n      stop();\n      void this.recoverConference(instance, reason);\n    };\n    const armTransportTimeout = (reason: string) => {\n      clearTimer(transportTimer);\n      transportTimer = window.setTimeout(() => {\n        transportTimer = undefined;\n        if(connection.connectionState !== 'connected') recover(reason);\n      }, CONNECTION_ESTABLISH_TIMEOUT_MS);\n    };\n    const onConnectionState = () => {\n      if(connection.connectionState === 'connected') {\n        clearTimer(transportTimer);\n        transportTimer = undefined;\n      } else if(connection.connectionState === 'failed' || connection.connectionState === 'closed') {\n        recover(`connection-${connection.connectionState}`);\n      }\n    };\n    const onIceState = () => {\n      const {iceConnectionState} = connection;\n      if(iceConnectionState === 'failed' || iceConnectionState === 'closed') {\n        recover(`ice-${iceConnectionState}`);\n      } else if(iceConnectionState === 'disconnected') {\n        armTransportTimeout('ice-disconnected');\n      } else if((iceConnectionState === 'connected' || iceConnectionState === 'completed') &&\n        connection.connectionState !== 'connected') {\n        armTransportTimeout('dtls-timeout');\n      }\n    };\n    const isMediaTransportReady = () => {\n      if(this.currentGroupCall !== instance || instance.isClosing) return false;\n      if(connection.connectionState !== 'connected' ||\n         (connection.iceConnectionState !== 'connected' && connection.iceConnectionState !== 'completed')) {\n        return false;\n      }\n\n      return true;\n    };\n    const isMediaActivityEligible = () => {\n      if(!isMediaTransportReady() || instance.isMuted) return false;\n\n      return instance.description?.entries.some((entry) => {\n        return entry.type === 'audio' && entry.direction === 'recvonly';\n      }) ?? false;\n    };\n    const sampleMediaLiveness = async() => {\n      if(stopped || mediaProbePending) return;\n      if(!isMediaTransportReady()) {\n        if(this.currentGroupCall !== instance || instance.isClosing) stop();\n        else resetMediaActivity();\n        return;\n      }\n\n      mediaProbePending = true;\n      try {\n        const report = await connection.getStats();\n        if(stopped || !isMediaTransportReady()) {\n          if(this.currentGroupCall !== instance || instance.isClosing) stop();\n          else resetMediaActivity();\n          return;\n        }\n\n        const audioSource = instance.connections.main?.sources.audio?.source;\n        // The report can carry hundreds of entries on a big conference (one\n        // recvonly m-line per remote SSRC). RTCStatsReport is a maplike —\n        // collect the few stats this probe needs in ONE pass and look the rest\n        // up by id, instead of cloning the whole report every 5s.\n        let transport: ConferenceRtcStat | undefined;\n        let fallbackPair: ConferenceRtcStat | undefined;\n        let outbound: ConferenceRtcStat | undefined;\n        const candidatePairsById = new Map<string, ConferenceRtcStat>();\n        const mediaSourcesById = new Map<string, ConferenceRtcStat>();\n        const remoteInboundCandidates: ConferenceRtcStat[] = [];\n        report.forEach((value) => {\n          const stat = value as ConferenceRtcStat;\n          if(stat.type === 'transport') {\n            if(!transport && stat.selectedCandidatePairId) transport = stat;\n          } else if(stat.type === 'candidate-pair') {\n            candidatePairsById.set(stat.id, stat);\n            if(!fallbackPair && (stat.selected || (stat.nominated && stat.state === 'succeeded'))) {\n              fallbackPair = stat;\n            }\n          } else if(stat.type === 'media-source') {\n            mediaSourcesById.set(stat.id, stat);\n          } else if(stat.type === 'outbound-rtp') {\n            if(!outbound &&\n              (stat.kind === 'audio' || stat.mediaType === 'audio') &&\n              typeof stat.ssrc === 'number' &&\n              typeof audioSource === 'number' &&\n              (stat.ssrc >>> 0) === (audioSource >>> 0)) {\n              outbound = stat;\n            }\n          } else if(stat.type === 'remote-inbound-rtp') {\n            remoteInboundCandidates.push(stat);\n          }\n        });\n        const selectedPair = transport?.selectedCandidatePairId ?\n          candidatePairsById.get(transport.selectedCandidatePairId) :\n          fallbackPair;\n        if(!selectedPair) {\n          resetMediaEvidence();\n          return;\n        }\n\n        const pairId = selectedPair.id;\n        if(selectedCandidatePairId === undefined) {\n          selectedCandidatePairId = pairId;\n          resetMediaActivity();\n          return;\n        }\n        if(pairId !== selectedCandidatePairId) {\n          selectedCandidatePairId = pairId;\n          routeChangeObserved = true;\n          resetMediaActivity();\n          return;\n        }\n        // While the one-shot recovery latch is held, the probe keeps running in\n        // observe-only mode: a fresh RTCP acknowledgement proves the rebuilt\n        // transport carries media, and only then is the latch released so a\n        // LATER route change can be detected and recovered again. A permanent\n        // latch left the second network flip of a call with no detector at all\n        // (\"mic on, nobody hears me\" with no breadcrumb).\n        const recoveryLatched = this.outboundMediaRecoveryUsed.has(instance);\n        if(!routeChangeObserved && !recoveryLatched) return;\n        if(!isMediaActivityEligible()) {\n          resetMediaActivity();\n          return;\n        }\n\n        const mediaSource = outbound?.mediaSourceId && mediaSourcesById.get(outbound.mediaSourceId);\n        if(!outbound || !mediaSource || mediaSource.type !== 'media-source' ||\n           !Number.isFinite(outbound.packetsSent) ||\n           !Number.isFinite(mediaSource.totalAudioEnergy) ||\n           !Number.isFinite(mediaSource.totalSamplesDuration)) {\n          resetMediaActivity();\n          return;\n        }\n\n        const outboundStat = outbound;\n        const remoteInbound = remoteInboundCandidates.find((stat) => {\n          return stat.localId === outboundStat.id ||\n            outboundStat.remoteId === stat.id ||\n            (typeof stat.ssrc === 'number' && (stat.ssrc >>> 0) === (outboundStat.ssrc! >>> 0));\n        });\n        const packetsSent = outbound.packetsSent!;\n        const sourceEnergy = mediaSource.totalAudioEnergy!;\n        const samplesDuration = mediaSource.totalSamplesDuration!;\n        const remoteInboundTimestamp = remoteInbound?.timestamp;\n        const updateBaseline = () => {\n          previousOutboundPackets = packetsSent;\n          previousSourceEnergy = sourceEnergy;\n          previousSamplesDuration = samplesDuration;\n          previousRemoteInboundTimestamp = remoteInboundTimestamp;\n        };\n\n        if(previousOutboundPackets === undefined ||\n           previousSourceEnergy === undefined ||\n           previousSamplesDuration === undefined) {\n          updateBaseline();\n          return;\n        }\n\n        if(remoteInbound && (previousRemoteInboundTimestamp === undefined ||\n           remoteInbound.timestamp > previousRemoteInboundTimestamp)) {\n          // The SFU acknowledged media on this route.\n          if(recoveryLatched) {\n            this.log('conference media confirmed after blackhole recovery — re-arming the probe');\n            this.outboundMediaRecoveryUsed.delete(instance);\n          }\n          // Keep watching for the NEXT route change instead of stopping the\n          // probe forever; the steady-state sample above is a cheap early\n          // return until one happens.\n          resetMediaEvidence();\n          return;\n        }\n\n        if(recoveryLatched) {\n          // Never chain a second automatic rejoin off the first one before the\n          // rebuilt transport has acknowledged anything — that is the rejoin\n          // loop the latch exists to prevent. Keep sampling for the ack.\n          updateBaseline();\n          return;\n        }\n\n        const packetDelta = packetsSent - previousOutboundPackets!;\n        const energyDelta = sourceEnergy - previousSourceEnergy!;\n        const durationDelta = samplesDuration - previousSamplesDuration!;\n        updateBaseline();\n        const rms = durationDelta > 0 && energyDelta >= 0 ? Math.sqrt(energyDelta / durationDelta) : 0;\n        if(packetDelta < OUTBOUND_MEDIA_MIN_PACKETS || rms < OUTBOUND_MEDIA_MIN_RMS) {\n          outboundProgressSamples = 0;\n          return;\n        }\n\n        if(++outboundProgressSamples < OUTBOUND_MEDIA_BLACKHOLE_PROGRESS_SAMPLES) return;\n\n        recover(OUTBOUND_MEDIA_BLACKHOLE_REASON);\n      } catch(err) {\n        resetMediaEvidence();\n        this.log.warn('conference media liveness sample failed', err);\n      } finally {\n        mediaProbePending = false;\n      }\n    };\n    instance.addEventListener('state', (state) => {\n      if(state === GROUP_CALL_STATE.CLOSED) stop();\n    });\n    connection.addEventListener('connectionstatechange', onConnectionState);\n    connection.addEventListener('iceconnectionstatechange', onIceState);\n    onConnectionState();\n    onIceState();\n    if(connection.connectionState !== 'connected' && transportTimer === undefined) {\n      armTransportTimeout('connection-timeout');\n    }\n    if(IS_CHROMIUM) {\n      // Armed even when the one-shot recovery latch is held: the probe then\n      // runs observe-only until a fresh RTCP ack releases the latch (see\n      // sampleMediaLiveness), restoring detection for later route changes.\n      mediaTimer = window.setInterval(() => {\n        void sampleMediaLiveness();\n      }, MEDIA_LIVENESS_INTERVAL_MS);\n      void sampleMediaLiveness();\n    }\n  }\n\n  private recoverConference(instance: GroupCallInstance, reason: string): Promise<void> {\n    if(reason === OUTBOUND_MEDIA_BLACKHOLE_REASON) {\n      this.outboundMediaRecoveryUsed.add(instance);\n    }\n    if(this.recoveringConferences.has(instance) || this.currentGroupCall !== instance || instance.isClosing) {\n      return Promise.resolve();\n    }\n    if(this.conferenceTransitionReservations || this.pendingConferenceJoin) {\n      this.pendingConferenceRecovery = {instance, reason};\n      return Promise.resolve();\n    }\n    const authorization = this.conferenceRecoveryAuthorizations.get(instance);\n    const input = authorization?.input ?? instance.toInputGroupCall();\n    const selfUserId = instance.selfUserId;\n    if(!input || selfUserId === undefined) {\n      this.log.error('cannot recover conference without canonical input/key identity', reason);\n      return instance.hangUp(false, false, true).then(() => {\n        toastNew({langPackKey: 'Error.AnError'});\n      }).catch((err) => {\n        // All recovery entry points are event/timer driven. Keep this terminal\n        // fallback observable even when local cleanup itself rejects.\n        this.log.error('conference cleanup without recovery identity failed', err);\n        toastNew({langPackKey: 'Error.AnError'});\n      });\n    }\n\n    const generation = ++this.conferenceTransitionGeneration;\n    this.recoveringConferences.add(instance);\n    const muted = instance.isMuted;\n    const joinVideo = instance.isSharingVideo;\n    const chatId = instance.chatId;\n    const outboundMediaRecoveryUsed = this.outboundMediaRecoveryUsed.has(instance);\n    this.log.warn('rejoining conference', {reason, id: instance.id});\n    const promise = (async() => {\n      try {\n        await instance.hangUp(false, false, true);\n        this.assertConferenceTransition(generation);\n        if(this.currentGroupCall === instance) this.setCurrentGroupCall(null);\n        await this.joinConference({\n          input,\n          ...(authorization?.expectedCanonicalInput ? {\n            expectedCanonicalInput: authorization.expectedCanonicalInput\n          } : {}),\n          selfUserId,\n          chatId,\n          muted,\n          joinVideo,\n          transitionGeneration: generation,\n          ...(outboundMediaRecoveryUsed ? {outboundMediaRecoveryUsed: true} : {})\n        });\n      } catch(err) {\n        if(err instanceof ConferenceTransitionCancelledError) {\n          this.log('conference rejoin cancelled by a newer call transition');\n          if(this.currentGroupCall === instance) this.setCurrentGroupCall(null);\n        } else {\n          this.log.error('conference rejoin failed', err);\n          toastNew({langPackKey: 'Error.AnError'});\n        }\n      } finally {\n        this.recoveringConferences.delete(instance);\n        if(this.conferenceRecovery?.generation === generation) {\n          this.conferenceRecovery = undefined;\n        }\n      }\n    })();\n    this.conferenceRecovery = {generation, promise};\n    return promise;\n  }\n\n  private assertConferenceTransition(generation?: number): void {\n    if(generation !== undefined && generation !== this.conferenceTransitionGeneration) {\n      throw new ConferenceTransitionCancelledError('Conference recovery was superseded');\n    }\n  }\n\n  private conferenceInputKey(input: InputGroupCall): string {\n    switch(input._) {\n      case 'inputGroupCall': return `id:${input.id}`;\n      case 'inputGroupCallSlug': return `slug:${input.slug}`;\n      case 'inputGroupCallInviteMessage': return `message:${input.msg_id}`;\n    }\n  }\n\n  private apiErrorType(error: unknown): string | undefined {\n    if(error && typeof error === 'object' && 'type' in error) {\n      const type = (error as {type?: unknown}).type;\n      if(typeof type === 'string') return type;\n    }\n    return error instanceof Error ? error.message : undefined;\n  }\n\n  // Fetch the tip and confirmed next cursor of subchain 0. `block` is absent\n  // when the server returned an empty chain, in which case the caller builds a\n  // zero block. Mirrors tdlib's GetGroupCallLastBlockQuery flow.\n  // Accepts either `inputGroupCall` or `inputGroupCallSlug`.\n  private async fetchLastConferenceBlock(\n    input: InputGroupCall,\n    expectedCanonicalInput?: InputGroupCall.inputGroupCall\n  ): Promise<{\n    block?: Uint8Array,\n    nextOffset: number\n  }> {\n    // sub_chain_id 0 is the block chain. offset=-1, limit=1 fetches the tip\n    // (see schema: phone.getGroupCallChainBlocks → Updates).\n    const updates = await this.managers.appCallsManager.getGroupCallChainBlocks(input, 0, -1, 1);\n    // Surface the embedded updates through the normal pipeline so any side\n    // effects (e.g. updateGroupCall) are applied to local state.\n    await this.managers.apiUpdatesManager.processUpdateMessage(updates);\n    const chainUpdate = findGroupCallChainUpdate(updates, 0, input, expectedCanonicalInput);\n    if(!chainUpdate) {\n      throw new Error('Conference chain response did not contain a matching block update');\n    }\n    const {blocks, next_offset: nextOffset} = chainUpdate;\n    if(!Number.isSafeInteger(nextOffset) || nextOffset < 0 || nextOffset < blocks.length) {\n      throw new Error('Conference chain response contained an invalid next_offset');\n    }\n    if(!blocks.length && nextOffset !== 0) {\n      throw new Error('Conference chain response omitted a non-empty chain tip');\n    }\n    return {\n      block: blocks[blocks.length - 1],\n      nextOffset\n    };\n  }\n}\n\nconst groupCallsController = new GroupCallsController();\nDEBUG && (MOUNT_CLASS_TO.groupCallController = groupCallsController);\nexport default groupCallsController;\n","import type {Chat, User} from '@layer';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport hasRights from './hasRights';\n\n/**\n * Mirrors tdesktop's `Filler::addClearHistory` (`window_peer_menu.cpp`): a private chat\n * always offers it, a channel only while we are still in it and either we may delete its\n * messages or it is a private, non-forum group. Topics, monoforum threads and the saved\n * sublists have no clear-history of their own — the caller rules those out by thread.\n */\nexport default function canClearHistory(peer: Chat | User) {\n  if(peer?._ === 'user') {\n    return true;\n  }\n\n  if(peer?._ === 'chat') {\n    return !peer.pFlags.deactivated;\n  }\n\n  if(peer?._ !== 'channel' || peer.pFlags.left || peer.pFlags.monoforum) {\n    return false;\n  }\n\n  return hasRights(peer, 'delete_messages') || (\n    !!peer.pFlags.megagroup &&\n    !peer.pFlags.forum &&\n    !getPeerActiveUsernames(peer)[0]\n  );\n}\n","import type {AppManagers} from '@lib/managers';\nimport type {LangPackKey} from '@lib/langPack';\nimport type {PopupPeerCheckboxOptions} from '@components/popups/peer';\nimport confirmationPopup from '@components/confirmationPopup';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport canClearHistory from '@appManagers/utils/chats/canClearHistory';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {toastNew} from '@components/toast';\nimport rootScope from '@lib/rootScope';\n\n/**\n * The clear-history confirmation, shaped like tdesktop's `DeleteMessagesBox` in its\n * `justClear` mode. The checkbox is the `PeerData::canRevokeFullHistory` half: a plain\n * private chat (never a bot, never ourselves) and a group we created. A broadcast has no\n * checkbox at all — clearing it is always for everyone, which is why only someone who may\n * delete its messages is offered the item in the first place.\n */\nexport default async function clearHistoryWithConfirmation(options: {\n  peerId: PeerId,\n  managers: AppManagers\n}) {\n  const {peerId, managers} = options;\n  const peer = apiManagerProxy.getPeer(peerId);\n  if(!canClearHistory(peer)) {\n    return false;\n  }\n\n  // `canClearHistory` has already ruled out everything else this peer could be\n  const chat = peer._ === 'chat' || peer._ === 'channel' ? peer : undefined;\n  const isBroadcast = chat?._ === 'channel' && !chat.pFlags.megagroup;\n\n  let descriptionLangKey: LangPackKey,\n    descriptionLangArgs: any[],\n    checkbox: PopupPeerCheckboxOptions;\n  if(peer._ === 'user') {\n    if(peerId === rootScope.myId) {\n      descriptionLangKey = 'AreYouSureClearHistorySavedMessages';\n    } else {\n      descriptionLangKey = 'AreYouSureClearHistoryWithUser';\n      descriptionLangArgs = [await wrapPeerTitle({peerId})];\n\n      if((!peer.pFlags.bot || peer.pFlags.support) && !peer.pFlags.deleted) {\n        checkbox = {\n          text: 'ClearHistoryOptionAlso',\n          textArgs: [await getPeerTitle({peerId, plainText: true, onlyFirstName: true})]\n        };\n      }\n    }\n  } else if(isBroadcast) {\n    descriptionLangKey = 'AreYouSureClearHistoryWithChannel';\n    descriptionLangArgs = [await wrapPeerTitle({peerId})];\n  } else {\n    descriptionLangKey = 'AreYouSureClearHistory';\n\n    if(chat.pFlags.creator) {\n      checkbox = {text: 'DeleteMessagesOptionAlsoChat'};\n    }\n  }\n\n  let revoke: boolean;\n  try {\n    revoke = await confirmationPopup({\n      peerId,\n      titleLangKey: 'AlertClearHistory',\n      descriptionLangKey,\n      descriptionLangArgs,\n      checkbox,\n      button: {\n        langKey: 'AlertClearHistory',\n        isDanger: true\n      }\n    });\n  } catch{\n    return false;\n  }\n\n  try {\n    await managers.appMessagesManager.flushHistory({\n      peerId,\n      justClear: true,\n      revoke: isBroadcast || !!revoke\n    });\n    return true;\n  } catch(error) {\n    console.error('clear history error', error);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n","import {JSX, Show, splitProps} from 'solid-js';\nimport {Transition} from 'solid-transition-group';\nimport classNames from '@helpers/string/classNames';\n\nimport '@components/skeleton/skeleton.scss';\n\nexport interface SkeletonProps {\n  loading: boolean | (() => boolean);\n  secondary?: boolean;\n  class?: string;\n  children?: JSX.Element | (() => JSX.Element);\n}\n\nexport const Skeleton = (props: SkeletonProps) => {\n  const children = () => typeof(props.children) === 'function' ? props.children() : props.children;\n  const loading = () => typeof(props.loading) === 'function' ? props.loading() : props.loading;\n  const inner = (\n    <Show when={loading()} fallback={children() && (\n      <div class=\"skeleton-child\">{children()}</div>\n    )}>\n      <Skeleton.Div textLine secondary={props.secondary} class={props.class} />\n    </Show>\n  );\n\n  return (\n    <Transition name=\"fade\" mode=\"outin\" duration={100}>\n      {inner}\n    </Transition>\n  );\n};\n\nSkeleton.Div = (inProps: JSX.HTMLAttributes<HTMLDivElement> & {\n  textLine?: boolean;\n  secondary?: boolean;\n}) => {\n  const [props, restProps] = splitProps(inProps, ['textLine', 'secondary', 'class']);\n  return (\n    <div class={classNames('skeleton-base', props.textLine && 'skeleton', props.secondary && 'skeleton-base--secondary', props.class)} {...restProps} />\n  );\n};\n","import {Show, createSignal} from 'solid-js';\nimport '@components/rtmp/rtmpData.css';\nimport {IconTsx} from '@components/iconTsx';\nimport {Skeleton} from '@components/skeleton';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\nimport classNames from '@helpers/string/classNames';\nimport {LangPackKey, i18n} from '@lib/langPack';\n\nexport interface RtmpDataProps {\n  key: string;\n  url: string;\n  loading: boolean;\n  contrast?: boolean;\n  showRevoke?: boolean;\n  onRevoke?: () => void;\n}\n\nconst cnRtmpData = (className = '') => `rtmp-data${className}`;\n\nexport const RtmpData = (props: RtmpDataProps) => {\n  const [keyVisible, setKeyVisible] = createSignal(false);\n\n  const keyContent = () => {\n    if(keyVisible()) return props.key;\n    return props.key.slice(0, 20).replace(/./g, '·');\n  };\n  const toggleKeyVisible = (e: MouseEvent) => {\n    e.stopPropagation();\n    setKeyVisible(!keyVisible());\n  };\n\n  const onCopy = (str: string, langPackKey: LangPackKey) => {\n    copyTextToClipboard(str);\n    toastNew({\n      langPackKey\n    });\n  };\n\n  return (\n    <div classList={{\n      [cnRtmpData()]: true,\n      [cnRtmpData('_contrast')]: props.contrast\n    }}>\n      <div\n        onClick={() => onCopy(props.url, 'Rtmp.StreamPopup.URLCopied')}\n        class={cnRtmpData('-row')}\n      >\n        <IconTsx icon=\"link\" class={cnRtmpData('-row-icon')} />\n        <div class={cnRtmpData('-row-item')}>\n          <div class={cnRtmpData('-row-item-text')}>\n            <Skeleton loading={props.loading}>\n              {props.url}\n            </Skeleton>\n          </div>\n          <div class={cnRtmpData('-row-item-label')}>\n            {i18n('Rtmp.StreamPopup.ServerURL')}\n          </div>\n        </div>\n        <IconTsx icon=\"copy\" class={cnRtmpData('-row-icon')} />\n      </div>\n\n      <div\n        onClick={() => onCopy(props.key, 'Rtmp.StreamPopup.KeyCopied')}\n        class={cnRtmpData('-row')}\n      >\n        <IconTsx icon=\"lock\" class={cnRtmpData('-row-icon')} />\n        <div class={cnRtmpData('-row-item')}>\n          <div classList={{\n            [cnRtmpData('-row-item-text')]: true,\n            [cnRtmpData('-row-item-text_hidden')]: !keyVisible()\n          }}>\n            <Skeleton loading={props.loading}>\n              {keyContent()}\n            </Skeleton>\n          </div>\n          <div class={cnRtmpData('-row-item-label')}>\n            {i18n('Rtmp.StreamPopup.StreamKey')}\n\n            <ButtonIconTsx\n              icon={keyVisible() ? 'eye2_filled' : 'eye1_filled'}\n              onClick={toggleKeyVisible}\n              class={cnRtmpData('-row-item-show')}\n            />\n          </div>\n        </div>\n        <IconTsx icon=\"copy\" class={cnRtmpData('-row-icon')} />\n      </div>\n\n      <Show when={props.showRevoke}>\n        <div\n          onClick={props.onRevoke}\n          class={classNames(cnRtmpData('-row'), cnRtmpData('-row_danger'))}\n        >\n          <IconTsx icon=\"rotate_left\" class={cnRtmpData('-row-icon')} />\n          <div class={cnRtmpData('-row-item')}>\n            <div class={cnRtmpData('-row-item-label')}>\n              {i18n('Rtmp.StreamPopup.RevokeStreamKey')}\n            </div>\n          </div>\n        </div>\n      </Show>\n    </div>\n  );\n};\n","import {render} from 'solid-js/web';\nimport PopupElement from '@components/popups';\n\nimport '@components/rtmp/adminPopup.css';\nimport {Show, createRoot, createSignal} from 'solid-js';\nimport {toastNew} from '@components/toast';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport {Ripple} from '@components/rippleTsx';\nimport {RtmpData} from '@components/rtmp/rtmpData';\nimport {i18n} from '@lib/langPack';\nimport appImManager from '@lib/appImManager';\n\nconst cnPopup = (className = '') => `rtmp-popup${className}`;\n\nexport interface RtmpAdminPopupProps {\n  peerId: PeerId\n  active?: boolean\n  onEndStream?: () => void\n}\n\nexport class RtmpStartStreamPopup extends PopupElement {\n  protected _dispose: () => void;\n  private _setLoading: (loading: boolean) => void;\n  private _setUrl: (url: string) => void;\n  private _setKey: (key: string) => void;\n  protected btnMore: HTMLElement;\n\n  constructor(readonly props: RtmpAdminPopupProps) {\n    super(cnPopup(), {\n      overlayClosable: true,\n      closable: true,\n      title: true,\n      body: true\n    });\n\n    const {active} = props;\n\n    if(!active) {\n      this.btnMore = ButtonMenuToggle({\n        buttons: [{\n          icon: 'stop',\n          regularText: 'Revoke',\n          danger: true,\n          onClick: () => this._revokeKey()\n        }],\n        direction: 'bottom-left'\n      });\n      this.header.append(this.btnMore);\n    }\n\n    this.title.append(active ? i18n('Rtmp.StreamPopup.TitleSettings') : i18n('Rtmp.StreamPopup.Title'));\n    // if(!document.documentElement.classList.contains('night')) {\n    //   this.element.classList.remove('night')\n    // }\n    this._render();\n  }\n\n  private _render() {\n    this._dispose = createRoot((dispose) => {\n      const [url, setUrl] = createSignal('');\n      const [key, setKey] = createSignal('');\n      const [loading, setLoading] = createSignal(true);\n\n      this._setLoading = setLoading;\n      this._setUrl = setUrl;\n      this._setKey = setKey;\n\n      const dispose2 = render(() => (\n        <RtmpStartStreamPopupContent\n          url={url()}\n          key={key()}\n          loading={loading()}\n          active={Boolean(this.props.active)}\n          onStreamStart={() => this._onStreamStart()}\n          onRevoked={() => this._revokeKey()}\n        />\n      ), this.body);\n\n      this._fetchData();\n\n      return () => {\n        setUrl('');\n        setKey('');\n        setLoading(false);\n        dispose2();\n        dispose();\n      };\n    });\n  }\n\n  private _revokeKey() {\n    this._setLoading(true);\n    this._fetchData(true);\n  }\n\n  private _fetchData(revoke = false) {\n    this.managers.appGroupCallsManager.fetchRtmpUrl(this.props.peerId, revoke).then(({url, key}) => {\n      this._setUrl(url);\n      this._setKey(key);\n      this._setLoading(false);\n    }).catch(() => {\n      toastNew({\n        langPackKey: 'Error.AnError'\n      });\n      this.forceHide();\n    });\n  }\n\n  private _onStreamStart() {\n    this.forceHide();\n    if(this.props.active) {\n      this.props.onEndStream();\n      return;\n    }\n    const peerId = this.props.peerId;\n    const chatId = peerId.toChatId();\n    this.managers.appGroupCallsManager.createGroupCall(\n      chatId,\n      undefined,\n      undefined,\n      true\n    ).then(() => {\n      appImManager.joinLiveStream(peerId);\n      // rtmpCallsController.joinCall(chatId);\n    });\n  }\n\n  cleanup() {\n    super.cleanup();\n    this._dispose();\n  }\n}\n\ninterface RtmpPopupProps {\n  url: string;\n  key: string;\n  loading: boolean;\n  active: boolean;\n  onStreamStart: () => void;\n  onRevoked: () => void;\n}\n\nconst RtmpStartStreamPopupContent = (props: RtmpPopupProps) => {\n  return (\n    <div class={cnPopup('-content')}>\n      <div class={cnPopup('-text')}>\n        {i18n('Rtmp.StreamPopup.Description')}\n      </div>\n\n      <RtmpData\n        key={props.key}\n        url={props.url}\n        loading={props.loading}\n        showRevoke={props.active}\n        onRevoke={props.onRevoked}\n      />\n\n      <Show when={!props.active}>\n        <div class={cnPopup('-text')}>\n          {i18n('Rtmp.StreamPopup.Hint')}\n        </div>\n      </Show>\n\n      <Ripple>\n        <button onClick={props.onStreamStart}\n          classList={{\n            [cnPopup('-button')]: true,\n            [cnPopup('-button_danger')]: props.active\n          }}\n        >\n          {props.active ? i18n('Rtmp.StreamPopup.EndLiveStream') : i18n('Rtmp.StreamPopup.StartStreaming')}\n        </button>\n      </Ripple>\n    </div>\n  );\n};\n","import callbackify from '@helpers/callbackify';\nimport namedPromises from '@helpers/namedPromises';\nimport {numberThousandSplitterForStars} from '@helpers/number/numberThousandSplitter';\nimport {AppManagers} from '@lib/managers';\nimport {i18n} from '@lib/langPack';\nimport confirmationPopup from '@components/confirmationPopup';\nimport Icon from '@components/icon';\nimport PeerTitle from '@components/peerTitle';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport Chat from '@components/chat/chat';\nimport type ChatTopbar from '@components/chat/topbar';\nimport {AckedResult} from '@lib/superMessagePort';\nimport {Accessor, createSignal, Show} from 'solid-js';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\ntype SetArgs = {\n  peerId: PeerId,\n  monoforumThreadId?: PeerId,\n  starsCharged: number\n};\n\nconst className = 'remove-fee';\n\nexport type ChatRemoveFeePlate = TopbarPlateController & {\n  setPeerId: (peerId: PeerId) => Promise<AckedResult<() => void>>,\n  hide: () => void\n};\n\nfunction RemoveFeePlateBody(props: {\n  args: Accessor<SetArgs | undefined>,\n  chat: Chat,\n  hide: () => void\n}) {\n  return (\n    <Show when={props.args()}>\n      {(a) => {\n        const peerTitle = new PeerTitle();\n        peerTitle.update({\n          peerId: a().monoforumThreadId || a().peerId,\n          onlyFirstName: true,\n          limitSymbols: 20\n        });\n\n        const inlineStars = (\n          <span>\n            {Icon('star', 'inline-icon', 'inline-icon-left')}\n            {numberThousandSplitterForStars(+a().starsCharged)}\n          </span>\n        ) as unknown as HTMLElement;\n\n        const text = i18n('PaidMessages.UserPaysForMessagesNotice', [peerTitle.element, inlineStars]);\n        text.classList.add('pinned-' + className + '-text', 'text-overflow-no-wrap');\n\n        return (\n          <div class={'pinned-' + className + '-content'}>\n            {text}\n            <TopbarPlate.PrimaryButton\n              onClick={async() => {\n                await openRemoveFeePopup({\n                  parentPeerId: a().monoforumThreadId ? a().peerId : undefined,\n                  peerId: a().monoforumThreadId || a().peerId,\n                  managers: props.chat.managers\n                });\n                props.hide();\n              }}\n            >\n              {i18n('PaidMessages.RemoveFee')}\n            </TopbarPlate.PrimaryButton>\n          </div>\n        );\n      }}\n    </Show>\n  );\n}\n\nexport default function createChatRemoveFeePlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatRemoveFeePlate {\n  const [args, setArgs] = createSignal<SetArgs | undefined>();\n\n  const plate = createTopbarPlate({\n    modifier: className,\n    height: 74,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: () => <RemoveFeePlateBody args={args} chat={chat} hide={() => hide()} />\n  });\n\n  const show = (next: SetArgs) => {\n    setArgs(next);\n    plate.setHidden(false);\n  };\n\n  const hide = () => {\n    plate.setHidden(true);\n    setArgs(undefined);\n  };\n\n  const setPeerId = async(peerId: PeerId) => {\n    if(chat.isMonoforum && chat.canManageDirectMessages && chat.monoforumThreadId) {\n      const {ackedChat, ackedDialog} = await namedPromises({\n        ackedChat: managers.acknowledged.appChatsManager.getChat(peerId.toChatId()),\n        ackedDialog: managers.acknowledged.monoforumDialogsStorage.getDialogByParent(peerId, chat.monoforumThreadId)\n      });\n\n      return {\n        cached: ackedChat.cached && ackedDialog.cached,\n        result: callbackify(Promise.all([ackedChat.result, ackedDialog.result]), ([chatPeer, dialog]) => {\n          const starsCharged = chatPeer?._ === 'channel' && +chatPeer.send_paid_messages_stars;\n          if(!starsCharged || dialog?.pFlags?.nopaid_messages_exception) return hide;\n          return () => show({peerId, starsCharged, monoforumThreadId: chat.monoforumThreadId});\n        })\n      };\n    }\n\n    if(!peerId.isUser()) return {\n      cached: true,\n      result: Promise.resolve(hide)\n    };\n\n    const ackedFullUser = await managers.acknowledged.appProfileManager.getProfile(peerId.toUserId());\n\n    return {\n      cached: ackedFullUser.cached,\n      result: callbackify(ackedFullUser.result, (fullUser) => {\n        const starsCharged = +fullUser?.settings?.charge_paid_message_stars;\n        if(!starsCharged) return hide;\n        return () => show({peerId, starsCharged});\n      })\n    };\n  };\n\n  return {\n    ...plate,\n    setPeerId,\n    hide\n  };\n}\n\ntype OpenRemoveFeePopupArgs = {\n  peerId: PeerId,\n  parentPeerId?: PeerId,\n  requirePayment?: boolean,\n  managers: AppManagers\n};\n\nexport async function openRemoveFeePopup({peerId, parentPeerId, managers, requirePayment}: OpenRemoveFeePopupArgs) {\n  const userId = peerId.toUserId();\n  const revenue = !requirePayment ? await managers.appUsersManager.getPaidMessagesRevenue({userId, parentPeerId}) : undefined;\n\n  const shouldRefund = await confirmationPopup({\n    titleLangKey: requirePayment ? 'PaidMessages.ChargeFee' : 'PaidMessages.RemoveFee',\n    descriptionLangKey: requirePayment ? 'PaidMessages.ChargeFeeWarning' : 'PaidMessages.RemoveFeeWarning',\n    descriptionLangArgs: [await wrapPeerTitle({peerId, onlyFirstName: true})],\n    checkbox: revenue ? {\n      text: 'PaidMessages.RemoveFeeRefund',\n      textArgs: [i18n('Stars', [revenue])]\n    } : undefined,\n    button: {\n      langKey: 'Confirm'\n    }\n  });\n\n  await managers.appUsersManager.toggleNoPaidMessagesException({userId, refundCharged: shouldRefund, parentPeerId, requirePayment});\n}\n","import type ChatTopbar from '@components/chat/topbar';\nimport Chat from '@components/chat/chat';\nimport I18n from '@lib/langPack';\nimport {ChatFull} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport StackedAvatars from '@components/stackedAvatars';\nimport appSidebarRight from '@components/sidebarRight';\nimport {AppChatRequestsTab} from '@components/solidJsTabs/tabs';\nimport callbackify from '@helpers/callbackify';\nimport {ONE_DAY} from '@helpers/date';\nimport {MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport {AckedResult} from '@lib/superMessagePort';\nimport {Accessor, createEffect, createSignal, Show} from 'solid-js';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\n/** Matches the plate's buttons — the stack mirrors the close button's slot. */\nconst AVATAR_SIZE = 40;\n\ntype RequestData = {\n  peerId: PeerId,\n  avatars: StackedAvatars,\n  avatarsMiddleware: MiddlewareHelper,\n  length: number\n};\n\nexport type ChatRequestsPlate = TopbarPlateController & {\n  set: (peerId: PeerId, peerIds: PeerId[], length: number) => Promise<() => void>,\n  unset: (peerId: PeerId) => void,\n  setPeerId: (peerId: PeerId) => Promise<AckedResult<() => void>>\n};\n\nfunction RequestsPlateBody(props: {\n  data: Accessor<RequestData | undefined>,\n  onOpen: () => void,\n  onClose: () => void\n}) {\n  const titleElement = new I18n.IntlElement({\n    key: 'Chat.Header.RequestToJoin',\n    args: [0]\n  });\n  // The plate is a fixed 48px — a large pending count has to ellipsize\n  // instead of wrapping the label onto a second line.\n  titleElement.element.classList.add('text-overflow-no-wrap');\n\n  // The label lives outside the `Show`, so it is updated from an effect — every\n  // `set()` writes a fresh `RequestData`, including while the plate is already\n  // on screen (`chat_requests` fires on every pending-count change).\n  createEffect(() => {\n    const d = props.data();\n    if(d) titleElement.compareAndUpdate({args: [d.length]});\n  });\n\n  // Same shape as the translation plate — a centred pill with the close button\n  // floating over the plate's end — with the requesters' faces leading it, the\n  // way every other client puts them in front of the label.\n  return (\n    <>\n      {/* `keyed` so a new `RequestData` swaps the stack: a plain `Show` only\n          re-runs its child when `when` flips truthiness, which would leave the\n          previous requesters' faces on a visible plate. */}\n      <Show when={props.data()} keyed>\n        {(d) => d.avatars.container}\n      </Show>\n      <TopbarPlate.PrimaryButton onClick={props.onOpen}>\n        {titleElement.element}\n      </TopbarPlate.PrimaryButton>\n      <TopbarPlate.CloseButton onClick={props.onClose} />\n    </>\n  );\n}\n\nexport default function createChatRequestsPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatRequestsPlate {\n  const [data, setData] = createSignal<RequestData | undefined>();\n\n  let currentPeerId: PeerId | undefined;\n\n  const onOpen = async() => {\n    if(appSidebarRight.isTabExists(AppChatRequestsTab)) return;\n    const tab = appSidebarRight.createTab(AppChatRequestsTab);\n    await tab.open(chat.peerId.toChatId());\n    appSidebarRight.toggleSidebar(true);\n  };\n\n  const onClose = () => {\n    if(currentPeerId !== undefined) {\n      chat.setAppState('hideChatJoinRequests', currentPeerId, Date.now());\n    }\n    unset(currentPeerId);\n  };\n\n  const plate = createTopbarPlate({\n    modifier: 'requests',\n    height: 48,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: () => <RequestsPlateBody data={data} onOpen={onOpen} onClose={onClose} />\n  });\n\n  const unset = (peerId: PeerId) => {\n    currentPeerId = peerId;\n    const prev = data();\n    if(prev) prev.avatarsMiddleware.destroy();\n    setData(undefined);\n    plate.setHidden(true);\n  };\n\n  const set = async(peerId: PeerId, peerIds: PeerId[], length: number) => {\n    if(!peerIds.length) {\n      return () => unset(peerId);\n    }\n\n    const avatarsMiddleware = getMiddleware();\n    const avatars = new StackedAvatars({avatarSize: AVATAR_SIZE, middleware: avatarsMiddleware.get()});\n    const loadPromises: Promise<any>[] = [];\n    avatars.render(peerIds, loadPromises);\n    await Promise.all(loadPromises);\n\n    return () => {\n      const prev = data();\n      currentPeerId = peerId;\n      setData({peerId, avatars, avatarsMiddleware, length});\n      plate.setHidden(false);\n      if(prev) prev.avatarsMiddleware.destroy();\n    };\n  };\n\n  const setPeerId = (peerId: PeerId) => {\n    return Promise.all([\n      managers.acknowledged.appProfileManager.getProfileByPeerId(peerId)\n    ]).then(([peerFullAcked]) => {\n      return {\n        cached: peerFullAcked.cached,\n        result: callbackify(peerFullAcked.result, (peerFull) => {\n          const recentRequesters = (peerFull as ChatFull.channelFull)?.recent_requesters;\n          const hidden = chat.appState.hideChatJoinRequests[peerId];\n          if(recentRequesters && (!hidden || (Date.now() - hidden) >= ONE_DAY)) {\n            return set(\n              peerId,\n              recentRequesters.slice(0, 3).map((userId) => userId.toPeerId(false)),\n              (peerFull as ChatFull.channelFull).requests_pending\n            );\n          } else {\n            return set(peerId, [], 0);\n          }\n        })\n      };\n    });\n  };\n\n  return {\n    ...plate,\n    set,\n    unset,\n    setPeerId,\n    destroy: () => {\n      const prev = data();\n      if(prev) prev.avatarsMiddleware.destroy();\n      plate.destroy();\n    }\n  };\n}\n","import {formatPhoneNumber} from '@helpers/formatPhoneNumber';\n\nexport default function formatUserPhone(phone: string) {\n  return '+' + formatPhoneNumber(phone).formatted;\n}\n","import {IS_WEBM_SUPPORTED} from '@environment/videoSupport';\nimport {rgbIntToHex} from '@helpers/color';\nimport {MediaSize} from '@helpers/mediaSize';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {EmojiStatus, DocumentAttribute, Document} from '@layer';\nimport rootScope from '@lib/rootScope';\nimport {Sparkles} from '@components/sparkles';\nimport wrapSticker from '@components/wrappers/sticker';\n\nconst RENDER_SPARKLES = false; // performance issues\n\nexport default async function wrapEmojiStatus({\n  wrapOptions,\n  emojiStatus,\n  size = mediaSizes.active.emojiStatus\n}: {\n  wrapOptions: WrapSomethingOptions,\n  emojiStatus: EmojiStatus.emojiStatus | EmojiStatus.emojiStatusCollectible,\n  size?: MediaSize\n}) {\n  const {middleware, animationGroup, textColor} = wrapOptions;\n  const container = document.createElement('span');\n  container.classList.add('emoji-status');\n  const result = await rootScope.managers.acknowledged.appEmojiManager.getCustomEmojiDocument(emojiStatus.document_id);\n  const wrap = async(doc: Document.document) => {\n    if(!middleware()) return;\n    const loadPromises: Promise<any>[] = [];\n\n    const attribute = doc.attributes.find((attr) => attr._ === 'documentAttributeCustomEmoji') as DocumentAttribute.documentAttributeCustomEmoji;\n    if(attribute && attribute.pFlags.text_color) {\n      container.classList.add('emoji-status-text-color');\n    }\n\n    await wrapSticker({\n      doc,\n      div: container,\n      width: size.width,\n      height: size.height,\n      loop: 2,\n      play: true,\n      group: animationGroup || 'EMOJI-STATUS',\n      loadPromises,\n      middleware,\n      static: doc.mime_type === 'video/webm' && !IS_WEBM_SUPPORTED,\n      textColor: textColor || 'primary-color'\n      // group: 'none'\n    });\n\n    if(!middleware()) return;\n    await Promise.all(loadPromises);\n  };\n\n  if(emojiStatus._ === 'emojiStatusCollectible' && RENDER_SPARKLES) {\n    container.appendChild(Sparkles({\n      mode: 'button',\n      isDiv: true,\n      containerSize: size\n    }));\n    container.style.setProperty('--sparkles-color', rgbIntToHex(emojiStatus.center_color));\n  }\n\n  if(!middleware()) {\n    return container;\n  }\n\n  const p = result.result.then(wrap);\n  if(result.cached) {\n    await p;\n  }\n\n  return container;\n}\n","import type ChatTopbar from '@components/chat/topbar';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from '@components/chat/chatType';\nimport {LangPackKey, i18n} from '@lib/langPack';\nimport {DocumentAttribute, EmojiStatus, PeerSettings} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport callbackify from '@helpers/callbackify';\nimport confirmationPopup from '@components/confirmationPopup';\nimport classNames from '@helpers/string/classNames';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport Icon from '@components/icon';\nimport PeerTitle from '@components/peerTitle';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport PopupElement from '@components/popups';\nimport PopupPeer from '@components/popups/peer';\nimport PopupPremium from '@components/popups/premium';\nimport {toastNew} from '@components/toast';\nimport formatUserPhone from '@components/wrappers/formatUserPhone';\nimport {formatFullSentTime} from '@helpers/date';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapEmojiStatus from '@components/wrappers/emojiStatus';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {AckedResult} from '@lib/superMessagePort';\nimport {Accessor, createSignal, For, Show} from 'solid-js';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\ntype PeerSettingsKey = keyof PeerSettings['pFlags'];\n\n/**\n * `reopen_topic` and `set_bot_photo` are not peer settings — they mirror the two\n * sibling bars tdesktop stacks next to the contact status one (`TopicReopenBar`\n * and `ContactStatus::State::Type::SetBotPhoto`, `history_view_contact_status.cpp`).\n */\ntype ActionKey = PeerSettingsKey | 'reopen_topic' | 'set_bot_photo';\n\ntype ActionDef = {\n  key: ActionKey,\n  onClick: () => void,\n  danger?: boolean,\n  icon?: Icon,\n  /** Reads as a prompt rather than a command, so it keeps its own casing. */\n  keepCase?: boolean\n};\n\ntype PeerSettingsActionDef = ActionDef & {key: PeerSettingsKey};\n\n/** The badge next to an unknown sender's name, when it is worth explaining. */\ntype NoteworthyEmojiStatus = EmojiStatus.emojiStatus | EmojiStatus.emojiStatusCollectible;\n\n/**\n * The `request_chat_*` peer settings, which describe the join request that made this\n * stranger able to write to us. Rendered as a tappable info line instead of buttons.\n */\ntype RequestChatInfo = {\n  peerId: PeerId,\n  title: string,\n  date: number,\n  isBroadcast: boolean\n};\n\nconst LANG_KEY_MAP: {[key in ActionKey]?: LangPackKey} = {\n  add_contact: 'AddContact',\n  autoarchived: 'Unarchive',\n  block_contact: 'BlockUser',\n  report_spam: 'DeleteReportSpam',\n  share_contact: 'ShareMyPhoneNoCaps',\n  reopen_topic: 'RestartTopic',\n  set_bot_photo: 'SetProfilePhoto'\n};\n\n/**\n * Session state for the set-photo prompt, keyed by bot. tdesktop keeps the same two\n * fields on `BotInfo`, i.e. for as long as the session lives:\n * - `openedEmpty` — whether that bot's chat was empty the first time we opened it;\n *   only then is the prompt ever offered (`FinalizeSetBotPhotoFirstOpenState`).\n * - `hidden` — the prompt's cross, which dismisses it locally without touching the\n *   server-side settings bar.\n */\nconst botPhotoPromptOpenedEmpty = new Map<PeerId, boolean>();\nconst botPhotoPromptHidden = new Set<PeerId>();\n\nexport type ChatActionsPlate = TopbarPlateController & {\n  set: (peerId: PeerId, settings: PeerSettings) => () => void,\n  unset: (peerId: PeerId) => void,\n  setPeerId: (peerId: PeerId) => Promise<AckedResult<() => void>>\n};\n\nfunction ActionsPlateBody(props: {\n  buttons: Accessor<ActionDef[] | undefined>,\n  requestChat: Accessor<RequestChatInfo | undefined>,\n  emojiStatus: Accessor<NoteworthyEmojiStatus | undefined>,\n  canClose: Accessor<boolean>,\n  onClose: () => void,\n  onRequestChatClick: (info: RequestChatInfo) => void\n}) {\n  return (\n    <Show\n      // keyed: the line is built imperatively, so a switch straight from one\n      // request-chat peer to another has to rebuild it rather than keep the old title\n      keyed\n      when={props.requestChat()}\n      fallback={\n        <>\n          <div class=\"pinned-actions-row\">\n            <Show when={props.buttons()}>\n              {(btns) => (\n                <For each={btns()}>\n                  {(action) => (\n                    <TopbarPlate.PrimaryButton\n                      danger={action.danger}\n                      onClick={action.onClick}\n                    >\n                      {action.icon && Icon(action.icon, 'pinned-actions-primary-button-icon')}\n                      {(() => {\n                        const text = i18n(LANG_KEY_MAP[action.key]);\n                        text.classList.add(\n                          'pinned-actions-primary-button-text',\n                          'text-overflow-no-wrap',\n                          ...(action.keepCase ? [] : ['text-uppercase'])\n                        );\n                        return text;\n                      })()}\n                    </TopbarPlate.PrimaryButton>\n                  )}\n                </For>\n              )}\n            </Show>\n            {/* Nothing to dismiss when the plate only carries the topic-reopen action —\n                tdesktop's reopen bar has no close button either. */}\n            <Show when={props.canClose()}>\n              <TopbarPlate.CloseButton onClick={props.onClose} />\n            </Show>\n          </div>\n          {/* keyed for the same reason as the join-request line: the note is built\n              imperatively, so a swap between two statuses has to rebuild it */}\n          <Show keyed when={props.emojiStatus()}>\n            {(status) => {\n              const middleware = createMiddleware().get();\n              const emoji = document.createElement('span');\n              wrapEmojiStatus({emojiStatus: status, wrapOptions: {middleware}}).then((wrapped) => {\n                if(middleware()) emoji.replaceWith(wrapped);\n              });\n\n              const link = document.createElement('a');\n              link.append(i18n('BoostingPremium'));\n              attachClickEvent(link, () => PopupPremium.show({feature: 'emoji_status'}));\n\n              const text = i18n('ReportSpamUserEmojiStatusHint', [emoji, link]);\n              text.classList.add('pinned-actions-text');\n              return text;\n            }}\n          </Show>\n        </>\n      }\n    >\n      {(info) => {\n        const peerTitle = new PeerTitle();\n        peerTitle.update({peerId: info.peerId});\n\n        return (\n          <TopbarPlate.PrimaryButton\n            quiet\n            class=\"pinned-actions-info rp-overflow\"\n            onClick={() => props.onRequestChatClick(info)}\n          >\n            {i18n(\n              info.isBroadcast ? 'ChatWithChannelAdmin' : 'ChatWithGroupAdmin',\n              [peerTitle.element, wrapEmojiText(info.title)]\n            )}\n          </TopbarPlate.PrimaryButton>\n        );\n      }}\n    </Show>\n  );\n}\n\nexport default function createChatActionsPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers,\n  peerSettingsConsumer?: Pick<ChatActionsPlate, 'set' | 'unset'>\n): ChatActionsPlate {\n  const [buttons, setButtons] = createSignal<ActionDef[] | undefined>();\n  const [requestChat, setRequestChat] = createSignal<RequestChatInfo | undefined>();\n  const [emojiStatus, setEmojiStatus] = createSignal<NoteworthyEmojiStatus | undefined>();\n  const [canClose, setCanClose] = createSignal(false);\n  const [disabled, setDisabled] = createSignal(false);\n\n  let currentPeerId: PeerId | undefined;\n  let currentThreadId: number | undefined;\n  let currentSettings: PeerSettings | undefined;\n  let peerSettingsActions: PeerSettingsActionDef[] = [];\n  let requestChatInfo: RequestChatInfo | undefined;\n  let canReopenTopic = false;\n  let canSetBotPhoto = false;\n\n  const freeze = async(promise: Promise<any>) => {\n    setDisabled(true);\n    try {\n      await promise;\n    } catch(err) {\n\n    }\n    setDisabled(false);\n  };\n\n  const actions: PeerSettingsActionDef[] = [{\n    key: 'autoarchived',\n    onClick: () => {\n      freeze(managers.appProfileManager.unarchiveFromSettingsBar(currentPeerId));\n    }\n  }, {\n    key: 'block_contact',\n    onClick: () => {\n      topbar.blockUser(\n        peerSettingsActions.some((action) => action.key === 'report_spam'),\n        true,\n        (promise) => freeze(promise)\n      );\n    },\n    danger: true\n  }, {\n    key: 'add_contact',\n    onClick: () => topbar.addContact()\n  }, {\n    key: 'share_contact',\n    onClick: async() => {\n      const peerId = currentPeerId;\n      const userId = peerId.toUserId();\n      const myPhone = apiManagerProxy.getUser(rootScope.myId.toUserId())?.phone;\n      await confirmationPopup({\n        titleLangKey: 'ShareYouPhoneNumberTitle',\n        descriptionLangKey: 'AreYouSureShareMyContactInfoUser',\n        descriptionLangArgs: [\n          myPhone ? formatUserPhone(myPhone) : '',\n          await wrapPeerTitle({peerId})\n        ],\n        button: {langKey: 'OK'}\n      });\n\n      const promise = managers.appUsersManager.acceptContact(userId).then(() => {\n        toastNew({\n          langPackKey: 'Conversation.ShareMyPhoneNumber.StatusSuccess',\n          langPackArguments: [new PeerTitle({peerId, onlyFirstName: true}).element]\n        });\n      });\n      freeze(promise);\n    }\n  }, {\n    key: 'report_spam',\n    onClick: async() => {\n      const peerId = currentPeerId;\n      if(peerId.isUser()) {\n        actions.find((action) => action.key === 'block_contact').onClick();\n      } else {\n        await confirmationPopup({\n          titleLangKey: 'Chat.Confirm.ReportSpam.Header',\n          descriptionLangKey: await managers.appPeersManager.isBroadcast(peerId) ?\n            'Chat.Confirm.ReportSpam.Channel' :\n            'Chat.Confirm.ReportSpam.Group',\n          button: {langKey: 'ReportChat'}\n        });\n\n        const promise = Promise.all([\n          managers.appMessagesManager.reportSpam(peerId),\n          managers.appChatsManager.leave(peerId.toChatId())\n        ]);\n        freeze(promise);\n      }\n    },\n    danger: true\n  }];\n\n  const reopenTopicAction: ActionDef = {\n    key: 'reopen_topic',\n    onClick: () => {\n      freeze(managers.appMessagesManager.editForumTopic({\n        peerId: currentPeerId,\n        topicId: currentThreadId,\n        closed: false\n      }));\n    }\n  };\n\n  const setBotPhotoAction: ActionDef = {\n    key: 'set_bot_photo',\n    icon: 'cameraadd',\n    keepCase: true,\n    onClick: () => topbar.editBot()\n  };\n\n  const showRequestChatInfoPopup = (info: RequestChatInfo) => {\n    PopupElement.createPopup(PopupPeer, 'popup-confirmation', {\n      titleLangKey: info.isBroadcast ? 'ChatWithAdminChannelTitle' : 'ChatWithAdminGroupTitle',\n      descriptionLangKey: 'ChatWithAdminMessage',\n      descriptionLangArgs: [wrapEmojiText(info.title), formatFullSentTime(info.date, true, true)],\n      buttons: [{\n        // `isCancel` keeps `addCancelButton` from adding a second button — tdesktop's\n        // box acknowledges and dismisses with this one.\n        langKey: 'IUnderstand',\n        isCancel: true,\n        callback: () => {\n          managers.appProfileManager.hidePeerSettingsBar(info.peerId);\n        }\n      }]\n    }).show();\n  };\n\n  const onClose = () => {\n    // The set-photo prompt is ours alone: tdesktop's cross only sets `setBotPhotoHidden`,\n    // it never hides the server-side settings bar.\n    if(canSetBotPhoto && !peerSettingsActions.length) {\n      botPhotoPromptHidden.add(currentPeerId);\n      canSetBotPhoto = false;\n      applyState();\n      return;\n    }\n\n    if(currentPeerId !== undefined) {\n      managers.appProfileManager.hidePeerSettingsBar(currentPeerId);\n    }\n\n    // Only the peer-settings half is dismissable — a still-closed topic keeps\n    // offering the reopen button.\n    peerSettingsActions = [];\n    applyState();\n  };\n\n  const plate = createTopbarPlate({\n    modifier: 'actions',\n    // 'auto' because the request-chat line wraps; the button rows keep their fixed\n    // height through `min-height` in the stylesheet.\n    height: 'auto',\n    class: () => classNames(\n      disabled() && 'is-disabled',\n      buttons()?.length > 1 && 'is-multiple',\n      buttons()?.length === 1 && !canClose() && 'is-single'\n    ),\n    onVisibilityChange: () => topbar.setFloating(),\n    render: () => (\n      <ActionsPlateBody\n        buttons={buttons}\n        requestChat={requestChat}\n        emojiStatus={emojiStatus}\n        canClose={canClose}\n        onClose={onClose}\n        onRequestChatClick={showRequestChatInfoPopup}\n      />\n    )\n  });\n\n  const applyState = () => {\n    setRequestChat(requestChatInfo);\n    if(requestChatInfo) {\n      setButtons(undefined);\n      setCanClose(false);\n      plate.setHidden(false);\n    } else {\n      let list = canReopenTopic ? [reopenTopicAction, ...peerSettingsActions] : peerSettingsActions;\n      // tdesktop offers the set-photo prompt only when no peer setting claims the bar.\n      if(!list.length && canSetBotPhoto) {\n        list = [setBotPhotoAction];\n      }\n\n      const visible = list.slice(0, 2);\n      setButtons(visible.length ? visible : undefined);\n      setCanClose(!!peerSettingsActions.length || canSetBotPhoto);\n      plate.setHidden(!visible.length);\n    }\n\n    // The plate measures itself ('auto'), and its content height changes with the mode.\n    topbar.setFloating();\n  };\n\n  /** A forum topic is the only thread kind that can be closed and reopened. */\n  const supportsTopicReopen = (peerId: PeerId, threadId: number) => {\n    return !!threadId && !!peerId?.isAnyChat() && chat.type === ChatType.Chat;\n  };\n\n  const ackedCanReopenTopic = (peerId: PeerId, threadId: number): Promise<AckedResult<boolean>> => {\n    if(!supportsTopicReopen(peerId, threadId)) {\n      return Promise.resolve({cached: true, result: Promise.resolve(false)});\n    }\n\n    return managers.acknowledged.dialogsStorage.canReopenTopic(peerId, threadId);\n  };\n\n  const refreshCanReopenTopic = async() => {\n    const peerId = currentPeerId, threadId = currentThreadId;\n    if(!supportsTopicReopen(peerId, threadId)) {\n      return;\n    }\n\n    const value = await managers.dialogsStorage.canReopenTopic(peerId, threadId);\n    if(currentPeerId !== peerId || currentThreadId !== threadId || canReopenTopic === value) {\n      return;\n    }\n\n    canReopenTopic = value;\n    applyState();\n  };\n\n  /**\n   * Everything but \"was the chat empty when first opened\" is on the cached user, so a\n   * chat that can't possibly want the prompt costs no round-trip at all.\n   */\n  const isBotPhotoPromptPossible = (peerId: PeerId) => {\n    if(!peerId?.isUser() || botPhotoPromptHidden.has(peerId)) {\n      return false;\n    }\n\n    const user = apiManagerProxy.getUser(peerId.toUserId());\n    return !!user?.pFlags?.bot && !!user.pFlags.bot_can_edit && !user.photo;\n  };\n\n  const ackedCanSetBotPhoto = async(peerId: PeerId): Promise<AckedResult<boolean>> => {\n    if(!isBotPhotoPromptPossible(peerId)) {\n      return {cached: true, result: Promise.resolve(false)};\n    }\n\n    const remembered = botPhotoPromptOpenedEmpty.get(peerId);\n    if(remembered !== undefined) {\n      return {cached: true, result: Promise.resolve(remembered)};\n    }\n\n    const acked = await managers.acknowledged.appMessagesManager.getDialogOnly(peerId);\n    return {\n      cached: acked.cached,\n      result: acked.result.then((dialog) => {\n        const openedEmpty = !dialog?.top_message;\n        botPhotoPromptOpenedEmpty.set(peerId, openedEmpty);\n        return openedEmpty;\n      })\n    };\n  };\n\n  const refreshCanSetBotPhoto = () => {\n    const value = isBotPhotoPromptPossible(currentPeerId) &&\n      !!botPhotoPromptOpenedEmpty.get(currentPeerId);\n    if(canSetBotPhoto === value) {\n      return;\n    }\n\n    canSetBotPhoto = value;\n    applyState();\n  };\n\n  /**\n   * tdesktop's `ContactStatus::PeerState` is a priority chain, not a flat filter: a\n   * contact only ever gets the share-phone bar, and the join-request line takes the\n   * whole bar from everything below it.\n   */\n  const recomputePeerSettings = () => {\n    const settings = currentSettings;\n    const pFlags = settings?.pFlags;\n    peerSettingsActions = [];\n    requestChatInfo = undefined;\n    if(!pFlags) {\n      return;\n    }\n\n    const isUser = currentPeerId.isUser();\n    if(isUser && apiManagerProxy.getUser(currentPeerId.toUserId())?.pFlags?.contact) {\n      if(pFlags.share_contact) {\n        peerSettingsActions = actions.filter((action) => action.key === 'share_contact');\n      }\n\n      return;\n    }\n\n    if(isUser && settings.request_chat_title !== undefined) {\n      requestChatInfo = {\n        peerId: currentPeerId,\n        title: settings.request_chat_title,\n        date: settings.request_chat_date,\n        isBroadcast: !!pFlags.request_chat_broadcast\n      };\n      return;\n    }\n\n    peerSettingsActions = actions.filter((action) => {\n      return action.key !== 'share_contact' && pFlags[action.key];\n    });\n  };\n\n  /**\n   * The badge is worth a word only when it carries information: a collectible, or a\n   * custom emoji of the sender's own. The recolorable ones every Premium subscriber\n   * picks from say nothing, and tdesktop skips them the same way (its `coloredSetId`\n   * check — here the `text_color` attribute that makes an emoji follow the text).\n   *\n   * Resolving the document can hit the network, so this runs after the plate is up\n   * rather than on the chat-open path, and the note simply appears once it lands.\n   */\n  const refreshEmojiStatusNote = async() => {\n    const peerId = currentPeerId;\n    const status = peerId?.isUser() && peerSettingsActions.length ?\n      apiManagerProxy.getUser(peerId.toUserId())?.emoji_status :\n      undefined;\n\n    let noteworthy: NoteworthyEmojiStatus;\n    if(status && 'document_id' in status) {\n      if(status._ === 'emojiStatusCollectible') {\n        noteworthy = status;\n      } else {\n        const doc = await managers.appEmojiManager.getCustomEmojiDocument(status.document_id);\n        const attribute = doc?.attributes.find((attr) => {\n          return attr._ === 'documentAttributeCustomEmoji';\n        }) as DocumentAttribute.documentAttributeCustomEmoji;\n        if(!attribute?.pFlags?.text_color) {\n          noteworthy = status;\n        }\n      }\n    }\n\n    if(currentPeerId !== peerId || emojiStatus() === noteworthy) {\n      return;\n    }\n\n    setEmojiStatus(noteworthy);\n    // the note is a line of its own, so the plate just got taller or shorter\n    topbar.setFloating();\n  };\n\n  const listenerSetter = new ListenerSetter();\n\n  // The topic's `closed` flag arrives as a `messageActionTopicEdit` service message.\n  listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n    if(!currentThreadId || !dialogs.get(currentPeerId)?.topics?.has(currentThreadId)) {\n      return;\n    }\n\n    refreshCanReopenTopic();\n  });\n\n  // ...and the rights that let us reopen it can change under us (tdesktop watches\n  // `adminRightsValue` for the same reason).\n  listenerSetter.add(rootScope)('chat_update', (chatId) => {\n    if(!currentThreadId || currentPeerId !== chatId.toPeerId(true)) {\n      return;\n    }\n\n    refreshCanReopenTopic();\n  });\n\n  // Becoming a contact swaps the whole branch of the chain (tdesktop watches the\n  // `Contact` user flag).\n  listenerSetter.add(rootScope)('contacts_update', (userId) => {\n    if(currentPeerId !== userId.toPeerId(false)) {\n      return;\n    }\n\n    recomputePeerSettings();\n    applyState();\n    refreshEmojiStatusNote();\n  });\n\n  // The badge itself can be set, swapped or dropped while we sit in the chat.\n  listenerSetter.add(rootScope)('user_update', (userId) => {\n    if(currentPeerId === userId.toPeerId(false)) {\n      refreshEmojiStatusNote();\n    }\n  });\n\n  // Once the bot has a photo the prompt is done — tdesktop drops it on `Photo` updates.\n  listenerSetter.add(rootScope)('avatar_update', ({peerId}) => {\n    if(currentPeerId !== peerId) {\n      return;\n    }\n\n    refreshCanSetBotPhoto();\n  });\n\n  const unsetOwn = (peerId: PeerId) => {\n    currentPeerId = peerId;\n    currentThreadId = undefined;\n    currentSettings = undefined;\n    peerSettingsActions = [];\n    requestChatInfo = undefined;\n    canReopenTopic = false;\n    canSetBotPhoto = false;\n    setEmojiStatus(undefined);\n    applyState();\n  };\n\n  const unset = (peerId: PeerId) => {\n    unsetOwn(peerId);\n    peerSettingsConsumer?.unset(peerId);\n  };\n\n  const set = (peerId: PeerId, settings: PeerSettings) => {\n    const peerSettingsCallback = peerSettingsConsumer?.set(peerId, settings);\n\n    return () => {\n      currentPeerId = peerId;\n      currentSettings = settings;\n      recomputePeerSettings();\n      if(peerSettingsActions.length || requestChatInfo) {\n        chat.bubbles.setPeerSettings(peerId, settings);\n      }\n\n      applyState();\n      refreshEmojiStatusNote();\n      peerSettingsCallback?.();\n    };\n  };\n\n  const setPeerId = (peerId: PeerId) => {\n    const threadId = chat.threadId;\n    return Promise.all([\n      managers.acknowledged.appProfileManager.getPeerSettings(peerId),\n      ackedCanReopenTopic(peerId, threadId),\n      ackedCanSetBotPhoto(peerId)\n    ]).then(([peerSettingsAcked, canReopenAcked, canSetBotPhotoAcked]) => {\n      return {\n        cached: peerSettingsAcked.cached && canReopenAcked.cached && canSetBotPhotoAcked.cached,\n        result: callbackify(\n          Promise.all([peerSettingsAcked.result, canReopenAcked.result, canSetBotPhotoAcked.result]),\n          ([peerSettings, canReopen, canSetPhoto]) => {\n            const setPeerSettings = set(peerId, peerSettings);\n            return () => {\n              currentThreadId = threadId;\n              canReopenTopic = canReopen;\n              canSetBotPhoto = canSetPhoto;\n              setPeerSettings();\n            };\n          }\n        )\n      };\n    });\n  };\n\n  return {\n    ...plate,\n    destroy: () => {\n      listenerSetter.removeAll();\n      plate.destroy();\n    },\n    set,\n    unset,\n    setPeerId\n  };\n}\n","export const cnTopbarLive = (className = '') => `pinned-live${className}`;\n","import {numberThousandSplitterForWatching} from '@helpers/number/numberThousandSplitter';\nimport {cnTopbarLive} from '@components/chat/topbarLive/topbarLive.cn';\n\nimport {Skeleton} from '@components/skeleton';\n\nimport '@components/chat/topbarLive/topbarLive.scss';\nimport {i18n} from '@lib/langPack';\nimport Button from '@components/buttonTsx';\nimport {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\n\nexport const TopbarLive = (props: {\n  watching: number,\n  actionButton: JSX.Element\n}) => {\n  const watching = () => props.watching > 0 ?\n    i18n('Rtmp.Watching', [numberThousandSplitterForWatching(Math.max(0, props.watching))]) :\n    i18n('Rtmp.Topbar.NoViewers');\n\n  const subtitle = (\n    <div>\n      <Skeleton loading={props.watching === undefined}>\n        {watching()}\n      </Skeleton>\n    </div>\n  );\n\n  return (\n    <>\n      <Button.Icon icon=\"livestream\" class=\"danger disable-hover\" />\n      <div class={cnTopbarLive('-content')}>\n        <div class={classNames(cnTopbarLive('-title'), 'primary', 'text-bold')}>\n          {i18n('Rtmp.Topbar.Title')}\n        </div>\n        <div class={classNames(cnTopbarLive('-subtitle'), 'secondary')}>\n          {subtitle}\n        </div>\n      </div>\n      {props.actionButton}\n    </>\n  );\n};\n","enum RTMP_STATE {\n  PLAYING,\n  BUFFERING,\n  CONNECTING,\n  CLOSED\n}\n\nexport default RTMP_STATE;\n","import groupCallsController from '@lib/calls/groupCallsController';\n\ntype ReserveConferenceTransition = () => Promise<() => void>;\n\nexport class CallTransitionCoordinator {\n  // Same serialized-FIFO idiom as @helpers/createSerializedQueue, kept inline\n  // deliberately: the reservation below must be taken EAGERLY — before the\n  // previous transition settles — which enqueue() cannot express without\n  // leaving the reservation promise unobserved while the queue drains.\n  private transitionQueue: Promise<void> = Promise.resolve();\n\n  constructor(\n    private reserveConferenceTransition: ReserveConferenceTransition =\n      () => groupCallsController.reserveConferenceTransition()\n  ) {}\n\n  public run<T>(callback: () => Promise<T>): Promise<T> {\n    const previous = this.transitionQueue;\n    // Reserve immediately, before waiting for the previous transition. This\n    // prevents conference liveness from starting a recovery in the gap while a\n    // user-triggered call switch is already queued.\n    const reservation = this.reserveConferenceTransition();\n    const transition = (async() => {\n      let release: () => void;\n      try {\n        release = await reservation;\n      } catch(err) {\n        // Preserve FIFO ordering even when acquiring this reservation fails.\n        // Otherwise a later transition could overtake the current one.\n        await previous;\n        throw err;\n      }\n\n      try {\n        await previous;\n        return await callback();\n      } finally {\n        release();\n      }\n    })();\n\n    this.transitionQueue = transition.then(\n      (): void => undefined,\n      (): void => undefined\n    );\n    return transition;\n  }\n}\n\nconst callTransitionCoordinator = new CallTransitionCoordinator();\nexport default callTransitionCoordinator;\n","import DEBUG, {MOUNT_CLASS_TO} from '@config/debug';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport noop from '@helpers/noop';\nimport {nextRandomUint} from '@helpers/random';\nimport {DataJSON, GroupCall, InputGroupCall} from '@layer';\nimport {JoinGroupCallJsonPayload} from '@appManagers/appGroupCallsManager';\nimport {AppManagers} from '@lib/managers';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport {RTMP_UNIFIED_CHANNEL_ID, RTMP_UNIFIED_QUALITY} from '@lib/calls/constants';\nimport {groupCallToInput} from '@lib/calls/helpers/groupCallUpdates';\nimport RTMP_STATE from '@lib/calls/rtmpState';\nimport {logger} from '@lib/logger';\nimport callTransitionCoordinator from '@lib/calls/callTransitionCoordinator';\n\nconst log = logger('RTMP');\n\nexport class RtmpCallInstance extends EventListenerBase<{\n  state: (state: RTMP_STATE) => void\n}> {\n  public chatId: ChatId;\n  public peerId: PeerId;\n  public call: GroupCall.groupCall;\n  public inputCall: InputGroupCall.inputGroupCall;\n  public ssrc: number;\n  public pip: boolean;\n  public admin: boolean;\n  public lastKnownTime: string;\n\n  private _state: RTMP_STATE;\n\n  constructor(params: {\n    chatId: ChatId,\n    peerId: PeerId,\n    call: GroupCall.groupCall,\n    inputCall: InputGroupCall.inputGroupCall,\n    ssrc: number,\n    pip: boolean,\n    admin: boolean,\n    lastKnownTime: string\n  }) {\n    super(false);\n    Object.assign(this, params);\n    this._state = RTMP_STATE.CONNECTING;\n  }\n\n  public cleanup() {\n    super.cleanup();\n  }\n\n  public get state() {\n    return this._state;\n  }\n\n  public set state(value: RTMP_STATE) {\n    this._state = value;\n    this.dispatchEvent('state', value);\n  }\n}\n\nexport class RtmpCallsController extends EventListenerBase<{\n  startedJoining: (peerId: PeerId) => void,\n  currentCallChanged: (call: RtmpCallInstance) => void\n}> {\n  private managers: AppManagers;\n\n  private _currentCall: RtmpCallInstance;\n  private currentCallGeneration = 0;\n  private rejoinPromise?: Promise<void>;\n\n  public construct(managers: AppManagers) {\n    this.managers = managers;\n\n    rootScope.addEventListener('group_call_update', this.onGroupCallUpdate);\n\n    apiManagerProxy.serviceMessagePort.addEventListener('rtmpStreamTime', ({callId, time}) => {\n      if(this.currentCall?.call.id === callId) {\n        this.currentCall.lastKnownTime = time;\n      }\n    });\n\n    if(typeof(window) !== 'undefined') {\n      // Watching a stream is a server-side membership (phone.joinGroupCall).\n      // Leave it when the tab goes away — best effort through the manager,\n      // which the SharedWorker keeps alive while any other tab exists — so the\n      // viewer count does not carry a ghost until the server times it out.\n      window.addEventListener('pagehide', () => {\n        const {currentCall} = this;\n        if(currentCall) {\n          void this.managers.appGroupCallsManager.hangUp(currentCall.call.id, currentCall.ssrc).catch(noop);\n        }\n      });\n    }\n  }\n\n  public get currentCall() {\n    return this._currentCall;\n  }\n\n  private set currentCall(value: RtmpCallInstance | undefined) {\n    if(this.currentCall === value) {\n      return;\n    }\n\n    this._currentCall?.cleanup();\n    ++this.currentCallGeneration;\n    this.dispatchEvent('currentCallChanged', this._currentCall = value);\n  }\n\n  private onGroupCallUpdate = (update: GroupCall) => {\n    if(update.id !== this.currentCall?.call.id) return;\n\n    if(update._ === 'groupCallDiscarded') {\n      this.currentCall = undefined;\n      return;\n    }\n\n    this.currentCall.call = update;\n    this.dispatchEvent('currentCallChanged', this.currentCall);\n  };\n\n  private randomSsrc() {\n    // random signed int32\n    return (Math.random() < 0.5 ? -1 : 1) * nextRandomUint(16);\n  }\n\n  private getJoinPayload(ssrc: number): DataJSON {\n    const innerData: JoinGroupCallJsonPayload = {\n      'fingerprints': [],\n      'pwd': '',\n      'ssrc': ssrc,\n      'ssrc-groups': [],\n      'ufrag': ''\n    };\n\n    return {\n      _: 'dataJSON',\n      data: JSON.stringify(innerData)\n    };\n  }\n\n  public async joinCall(chatId: ChatId) {\n    if(this.currentCall) {\n      throw new Error('Already in rtmp call');\n    }\n\n    const peerId = chatId.toPeerId(true);\n    this.dispatchEvent('startedJoining', peerId);\n\n    const ssrc = this.randomSsrc();\n    const data = this.getJoinPayload(ssrc);\n\n    const chat = await this.managers.appProfileManager.getChatFull(chatId);\n    if(chat._ !== 'channelFull') {\n      throw new Error('Not a chat');\n    }\n\n    const callId = (chat.call as InputGroupCall.inputGroupCall)?.id;\n    if(!callId) {\n      throw new Error('No call id');\n    }\n\n    const call = await this.managers.appGroupCallsManager.getGroupCallFull(callId);\n    if(call._ !== 'groupCall') {\n      throw new Error('Not a group call');\n    }\n\n    const update = await this.managers.appGroupCallsManager.joinGroupCall(callId, data, {type: 'main'});\n    let instance: RtmpCallInstance;\n    try {\n      const updateData = JSON.parse(update.params.data);\n      if(updateData.rtmp !== true) {\n        throw new Error('Not an rtmp call');\n      }\n\n      instance = new RtmpCallInstance({\n        call,\n        inputCall: groupCallToInput(call),\n        chatId,\n        peerId,\n        ssrc,\n        pip: false,\n        admin: Boolean(chat.pFlags?.can_delete_channel),\n        lastKnownTime: '0'\n      });\n    } catch(err) {\n      await this.compensateAcceptedJoin(update.acceptedCallInput, ssrc, 'initial RTMP join');\n      throw err;\n    }\n\n    this.currentCall = instance;\n  }\n\n  public async leaveCall(discard = false, expectedCall?: RtmpCallInstance): Promise<boolean> {\n    const currentCall = this.currentCall;\n    if(!currentCall || (expectedCall && currentCall !== expectedCall)) return false;\n\n    this.currentCall = undefined;\n    apiManagerProxy.serviceMessagePort.invokeVoid('leaveRtmpCall', [currentCall.call.id, true]);\n    await this.managers.appGroupCallsManager.hangUp(currentCall.call.id, discard ? true : currentCall.ssrc);\n    return true;\n  }\n\n  public async isCurrentCallDead(checkJoined = false, triedRejoin = false): Promise<'dead' | 'dying' | 'alive'> {\n    if(!this.currentCall) return 'dead';\n\n    const state = await this.managers.appGroupCallsManager.fetchRtmpState(this.currentCall.inputCall);\n    if(!checkJoined) return state.channels.length === 0 ? 'dead' : 'alive';\n\n    // check if we are joined by trying to fetch a part\n    const unified = state.channels.find((it) => it.channel === RTMP_UNIFIED_CHANNEL_ID);\n    if(!unified) return 'dead';\n    try {\n      const time = this.currentCall.lastKnownTime === '0' ? unified.last_timestamp_ms : this.currentCall.lastKnownTime;\n      await this.managers.appGroupCallsManager.fetchRtmpPart({\n        _: 'inputGroupCallStream',\n        call: this.currentCall.inputCall,\n        video_channel: RTMP_UNIFIED_CHANNEL_ID,\n        video_quality: RTMP_UNIFIED_QUALITY,\n        scale: unified.scale,\n        time_ms: time\n      }, state.dcId);\n      return 'alive';\n    } catch(e) {\n      if((e as ApiError).type === 'GROUPCALL_JOIN_MISSING' && !triedRejoin) {\n        try {\n          await this.rejoinCall();\n          return await this.isCurrentCallDead(true, true);\n        } catch(err) {\n          log.error('rejoinCall failed during dead-call check', err);\n        }\n      }\n    }\n\n    return 'dying';\n  }\n\n  public rejoinCall(): Promise<void> {\n    if(this.rejoinPromise) return this.rejoinPromise;\n\n    // Only recovery enters the shared call-transition FIFO here. User joins are\n    // already wrapped by AppImManager; wrapping joinCall itself would enqueue a\n    // transition from inside another transition and deadlock it against itself.\n    const promise = callTransitionCoordinator.run(() => this.rejoinCallInternal()).finally(() => {\n      if(this.rejoinPromise === promise) this.rejoinPromise = undefined;\n    });\n    this.rejoinPromise = promise;\n    return promise;\n  }\n\n  private async rejoinCallInternal(): Promise<void> {\n    const currentCall = this.currentCall;\n    if(!currentCall) return;\n\n    const generation = this.currentCallGeneration;\n    const ssrc = this.randomSsrc();\n    const data = this.getJoinPayload(ssrc);\n    const update = await this.managers.appGroupCallsManager.joinGroupCall(currentCall.call.id, data, {\n      type: 'main',\n      // Preserve the exact call identity used by this recovery so a late accepted\n      // join can be compensated even after caches/currentCall have moved on.\n      e2eCallInput: currentCall.inputCall\n    });\n\n    if(this.currentCall !== currentCall || this.currentCallGeneration !== generation) {\n      await this.compensateAcceptedJoin(update.acceptedCallInput, ssrc, 'late RTMP rejoin');\n      return;\n    }\n\n    // Do not publish the replacement source before acceptance. A concurrent\n    // direct leave must still remove the OLD membership; if this response then\n    // arrives late, the generation branch above removes the newly accepted one.\n    currentCall.ssrc = ssrc;\n  }\n\n  private async compensateAcceptedJoin(call: InputGroupCall, ssrc: number, context: string): Promise<void> {\n    try {\n      await this.managers.appGroupCallsManager.leaveGroupCall(call, ssrc);\n    } catch(err) {\n      log.error(`${context} compensation failed`, err);\n    }\n  }\n}\n\nconst rtmpCallsController = new RtmpCallsController();\nDEBUG && (MOUNT_CLASS_TO.rtmpCallsController = rtmpCallsController);\nexport default rtmpCallsController;\n","import {createSignal} from 'solid-js';\nimport rtmpCallsController, {RtmpCallInstance} from '@lib/calls/rtmpCallsController';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {NULL_PEER_ID} from '@appManagers/constants';\n\nexport function useCurrentRtmpCall() {\n  const [call, setCall] = createSignal<RtmpCallInstance>(rtmpCallsController.currentCall, {equals: false});\n  const [peerId, setPeerId] = createSignal<PeerId>(NULL_PEER_ID);\n\n  subscribeOn(rtmpCallsController)('currentCallChanged', (call) => {\n    setCall(call);\n    setPeerId(call?.peerId);\n  });\n\n  subscribeOn(rtmpCallsController)('startedJoining', (peerId) => {\n    setPeerId(peerId);\n  });\n\n  return {call, peerId};\n}\n","import {Accessor, Show, createEffect, createMemo, createResource, createSignal} from 'solid-js';\nimport {TopbarLive} from '@components/chat/topbarLive/topbarLive';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport rootScope from '@lib/rootScope';\nimport {useCurrentRtmpCall} from '@components/rtmp/hooks';\nimport {AppManagers} from '@lib/managers';\nimport Chat from '@components/chat/chat';\nimport ChatTopbar from '@components/chat/topbar';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport {ChatFull, GroupCall, InputGroupCall, Chat as MTChat} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {useChat} from '@stores/peers';\nimport {useFullPeer} from '@stores/fullPeers';\nimport {i18n} from '@lib/langPack';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\nexport type ChatLivePlate = TopbarPlateController & {\n  setPeerId: (peerId: PeerId) => void\n};\n\n/**\n * Top-level component so solid-refresh can swap it on HMR. Reads its\n * inputs (peerId signal, setHidden) through props so factory-owned state\n * — captured in `createChatLivePlate`'s closure — survives module reloads.\n */\nfunction LivePlateBody(props: {\n  peerId: Accessor<PeerId>,\n  setHidden: (hidden: boolean) => void\n}) {\n  const [watching, setWatching] = createSignal<number>();\n  const peerChat = useChat(() => props.peerId().toChatId());\n  const [fullPeer, setFullPeer] = createSignal<ChatFull | undefined>();\n  createEffect(() => {\n    const fullPeer = useFullPeer(props.peerId());\n    createEffect(() => setFullPeer(fullPeer() as ChatFull));\n  });\n  const currentCall = useCurrentRtmpCall();\n  const isCallActive = createMemo(() => {\n    const c = peerChat();\n    return !!(\n      c &&\n      (c as MTChat.channel).pFlags.broadcast &&\n      (c as MTChat.channel).pFlags.call_active &&\n      (c as MTChat.channel).pFlags.call_not_empty\n    );\n  });\n  const [fullCall] = createResource(\n    fullPeer,\n    async(fullPeer) => {\n      const inputGroupCall = (fullPeer as ChatFull.channelFull)?.call;\n      if(!inputGroupCall) return;\n\n      const fullCall = await rootScope.managers.appGroupCallsManager.getGroupCallFull(\n        (inputGroupCall as InputGroupCall.inputGroupCall).id\n      );\n      return fullCall && (fullCall as GroupCall.groupCall).pFlags.rtmp_stream ?\n        fullCall as GroupCall.groupCall :\n        undefined;\n    }\n  );\n  const shouldShow = createMemo(() => {\n    return !!(isCallActive() && currentCall.peerId() !== props.peerId() && fullCall());\n  });\n\n  subscribeOn(rootScope)('group_call_update', async(call) => {\n    if(!isCallActive() || call._ !== 'groupCall') return;\n    const fullChat = fullPeer();\n    if(fullChat?._ !== 'channelFull') return;\n    if(call.id !== (fullChat.call as InputGroupCall.inputGroupCall)?.id) return;\n    setWatching(call.participants_count);\n  });\n\n  createEffect<PeerId>((wasPeerId) => {\n    if(!peerChat() || !(peerChat() as MTChat.channel).pFlags.broadcast) return;\n\n    if(wasPeerId !== props.peerId()) setWatching();\n\n    createEffect(() => {\n      if(!isCallActive()) setWatching();\n      else setWatching(fullCall()?.participants_count);\n    });\n\n    return props.peerId();\n  });\n\n  createEffect(() => props.setHidden(!shouldShow()));\n\n  return (\n    <Show when={shouldShow()}>\n      <TopbarLive\n        watching={watching()}\n        actionButton={\n          <TopbarPlate.ActionButton\n            onClick={() => appImManager.joinLiveStream(props.peerId())}\n          >\n            {i18n('Rtmp.Topbar.Join')}\n          </TopbarPlate.ActionButton>\n        }\n      />\n    </Show>\n  );\n}\n\nexport default function createChatLivePlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatLivePlate {\n  const [peerId, setPeerIdSignal] = createSignal<PeerId>(NULL_PEER_ID);\n\n  const plate = createTopbarPlate({\n    modifier: 'live',\n    height: 48,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: ({setHidden}) => <LivePlateBody peerId={peerId} setHidden={setHidden} />\n  });\n\n  return {\n    ...plate,\n    setPeerId: (next) => setPeerIdSignal(next)\n  };\n}\n","import {createSignal, onCleanup} from 'solid-js';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport type GroupCallInstance from '@lib/calls/groupCallInstance';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\n\n/**\n * Reactive view of the group call this tab has joined, `undefined` when none.\n *\n * The controller keeps its reference after a hang-up and only dispatches\n * `instance` for a *new* call, so the closing edge has to come from the\n * instance's own `state` event — otherwise a left call would keep looking\n * joined forever.\n */\nexport function useCurrentGroupCall() {\n  const [instance, setInstance] = createSignal<GroupCallInstance | undefined>();\n\n  const instanceListeners = new ListenerSetter();\n  onCleanup(() => instanceListeners.removeAll());\n\n  const track = (newInstance: GroupCallInstance | undefined) => {\n    instanceListeners.removeAll();\n\n    if(newInstance?.state === GROUP_CALL_STATE.CLOSED) {\n      newInstance = undefined;\n    }\n\n    setInstance(newInstance);\n    if(!newInstance) return;\n\n    instanceListeners.add(newInstance)('state', (state) => {\n      if(state === GROUP_CALL_STATE.CLOSED) track(undefined);\n    });\n  };\n\n  track(groupCallsController.groupCall);\n  subscribeOn(groupCallsController)('instance', track);\n\n  return instance;\n}\n","export const cnTopbarGroupCall = (className = '') => `pinned-group-call${className}`;\n","import {JSX} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport Button from '@components/buttonTsx';\nimport {StackedAvatarsTsx} from '@components/stackedAvatars';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {cnTopbarGroupCall} from '@components/chat/topbarGroupCall/topbarGroupCall.cn';\n\nimport '@components/chat/topbarGroupCall/topbarGroupCall.scss';\n\nconst AVATAR_SIZE = 36;\n\n/**\n * Layout follows the group-call bar of the other clients: icon + title on one\n * side, the join button on the other, and a preview of who is already in the\n * call sitting on the plate's horizontal centre.\n *\n * The two sides are equal-width columns rather than plain flex items, so the\n * stack lands on the real centre of the plate (like tdesktop, which paints it\n * at `width / 2`) instead of wherever the text happens to end.\n */\nexport const TopbarGroupCall = (props: {\n  title?: string,\n  participantsCount: number,\n  participantPeerIds: PeerId[],\n  actionButton: JSX.Element\n}) => {\n  return (\n    <>\n      <div class={cnTopbarGroupCall('-side')}>\n        <Button.Icon icon=\"videochat\" class=\"primary disable-hover\" />\n        <div class={cnTopbarGroupCall('-content')}>\n          <div class={classNames(cnTopbarGroupCall('-title'), 'primary', 'text-bold', 'text-overflow-no-wrap')}>\n            {props.title ? wrapEmojiText(props.title) : i18n('PeerInfo.Action.VoiceChat')}\n          </div>\n          <div class={classNames(cnTopbarGroupCall('-subtitle'), 'secondary', 'text-overflow-no-wrap')}>\n            {i18n('VoiceChat.Status.Members', [props.participantsCount])}\n          </div>\n        </div>\n      </div>\n      <StackedAvatarsTsx peerIds={props.participantPeerIds} avatarSize={AVATAR_SIZE} />\n      <div class={classNames(cnTopbarGroupCall('-side'), 'is-end')}>\n        {props.actionButton}\n      </div>\n    </>\n  );\n};\n","import {Accessor, Show, createEffect, createMemo, createResource, createSignal} from 'solid-js';\nimport type Chat from '@components/chat/chat';\nimport type ChatTopbar from '@components/chat/topbar';\nimport {ChatType} from '@components/chat/chatType';\nimport {ChatFull, InputGroupCall, Chat as MTChat} from '@layer';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport appImManager from '@lib/appImManager';\nimport {i18n} from '@lib/langPack';\nimport {useChat} from '@stores/peers';\nimport {useFullPeer} from '@stores/fullPeers';\nimport {useCurrentGroupCall} from '@components/groupCall/hooks';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\nimport {TopbarGroupCall} from '@components/chat/topbarGroupCall/topbarGroupCall';\n\nexport type ChatGroupCallPlate = TopbarPlateController & {\n  setPeerId: (peerId: PeerId) => void\n};\n\n/** How many faces the avatar stack previews — the same three as every other client. */\nconst PREVIEW_AVATARS_COUNT = 3;\n\n/**\n * Top-level component so solid-refresh can swap it on HMR — same split as the\n * live plate: everything the factory owns comes in through props.\n */\nfunction GroupCallPlateBody(props: {\n  peerId: Accessor<PeerId>,\n  setHidden: (hidden: boolean) => void\n}) {\n  const peerChat = useChat(() => props.peerId().toChatId());\n  const currentGroupCall = useCurrentGroupCall();\n\n  // `call_active` + `call_not_empty` is what every client gates this bar on:\n  // an empty (or already finished) call gets no plate. Both flags live on the\n  // cheap peers store, so this settles before anything is fetched.\n  const isCallActive = createMemo(() => {\n    const chat = peerChat() as MTChat.chat | MTChat.channel;\n    return !!(chat?.pFlags?.call_active && chat.pFlags.call_not_empty);\n  });\n\n  // Only chats that actually have a call subscribe to the full peer — that's\n  // where the `inputGroupCall` lives, and nothing else here needs it.\n  const fullPeer = createMemo(() => isCallActive() ? useFullPeer(props.peerId())() as ChatFull : undefined);\n\n  const callId = createMemo(() => {\n    const full = fullPeer();\n    if(!full || !('call' in full)) return;\n    return (full.call as InputGroupCall.inputGroupCall)?.id;\n  });\n\n  const [preview, {refetch}] = createResource(\n    callId,\n    (id) => rootScope.managers.appGroupCallsManager.getGroupCallPreview(id, PREVIEW_AVATARS_COUNT)\n  );\n\n  const groupCall = createMemo(() => {\n    const call = preview()?.call;\n    // RTMP streams belong to the live plate; everything else is a video chat.\n    return call?._ === 'groupCall' && !call.pFlags.rtmp_stream ? call : undefined;\n  });\n\n  const shouldShow = createMemo(() => !!(\n    isCallActive() &&\n    groupCall() &&\n    currentGroupCall()?.chatId !== props.peerId().toChatId()\n  ));\n\n  // Joins and leaves bump `participants_count`, which is exactly when both the\n  // counter and the avatar stack go stale. The refetch is worker-cache-cheap:\n  // the call is already saved, so only the roster read crosses the boundary.\n  subscribeOn(rootScope)('group_call_update', (call) => {\n    // Ids come back as numbers when they fit a safe integer, but are kept as\n    // strings elsewhere — compare stringified or every update slips through.\n    if(callId() !== undefined && String(call.id) === String(callId())) {\n      refetch();\n    }\n  });\n\n  createEffect(() => props.setHidden(!shouldShow()));\n\n  return (\n    <Show when={shouldShow() && groupCall()}>\n      {(call) => (\n        <TopbarGroupCall\n          title={call().title}\n          participantsCount={call().participants_count}\n          participantPeerIds={preview()?.peerIds || []}\n          actionButton={\n            <TopbarPlate.ActionButton\n              onClick={() => appImManager.joinGroupCall(props.peerId())}\n            >\n              {i18n('VoiceChat.Topbar.Join')}\n            </TopbarPlate.ActionButton>\n          }\n        />\n      )}\n    </Show>\n  );\n}\n\nexport default function createChatGroupCallPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatGroupCallPlate {\n  const [peerId, setPeerIdSignal] = createSignal<PeerId>(NULL_PEER_ID);\n\n  const plate = createTopbarPlate({\n    modifier: 'group-call',\n    height: 48,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: ({setHidden}) => <GroupCallPlateBody peerId={peerId} setHidden={setHidden} />\n  });\n\n  return {\n    ...plate,\n    // Same gate as the topbar's video-chat button: real chats only, no\n    // threads, no private peers. Anything else parks the plate on NULL_PEER_ID.\n    setPeerId: (next) => setPeerIdSignal(\n      chat.type === ChatType.Chat && !chat.threadId && !next.isUser() ? next : NULL_PEER_ID\n    )\n  };\n}\n","import {Accessor, createEffect, createSignal, on, Show} from 'solid-js';\nimport {AppManagers} from '@lib/managers';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport Chat from '@components/chat/chat';\nimport ChatTopbar from '@components/chat/topbar';\nimport {SponsoredMessage} from '@layer';\nimport classNames from '@helpers/string/classNames';\n\nimport styles from '@components/chat/topbarSponsored.module.scss';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport wrapRichText from '@lib/richTextProcessor/wrapRichText';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport appImManager from '@lib/appImManager';\nimport PhotoTsx from '@components/wrappers/photoTsx';\nimport {MyPhoto} from '@appManagers/appPhotosManager';\nimport PopupPremium from '@components/popups/premium';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {getSponsoredMessageButtons} from '@components/chat/contextMenu';\nimport {showAdReport} from '@components/popups/reportAd';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport Button from '@components/buttonTsx';\nimport RippleElement from '@components/rippleElement';\nimport {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\n\nexport type ChatSponsoredPlate = TopbarPlateController & {\n  setPeerId: (peerId: PeerId) => void\n};\n\nfunction SponsoredPlateBody(props: {\n  peerId: Accessor<PeerId>,\n  chat: Chat,\n  managers: AppManagers,\n  setHidden: (hidden: boolean) => void\n}) {\n  const [message, setMessage] = createSignal<SponsoredMessage>();\n\n  createEffect(on(props.peerId, (peerId$) => {\n    setMessage(undefined);\n    props.setHidden(true);\n    if(peerId$ === NULL_PEER_ID || !peerId$.isUser()) return;\n    if(!props.chat.isBot) return;\n\n    props.managers.appMessagesManager.getSponsoredMessage(peerId$)\n    .then((m) => {\n      if(props.peerId() !== peerId$) return;\n\n      if(m._ === 'messages.sponsoredMessages' && m.messages.length) {\n        setMessage(m.messages[0]);\n        props.setHidden(false);\n      }\n    });\n  }));\n\n  const photo = () => {\n    const m = message();\n    if(m.photo) return m.photo as MyPhoto;\n    if(m.media && m.media._ === 'messageMediaPhoto') return m.media.photo as MyPhoto;\n    return undefined;\n  };\n\n  const middleware = createMiddleware().get();\n\n  return (\n    <Show when={message()}>\n      <RippleElement\n        component=\"div\"\n        class={/* @once */ classNames(styles.container, 'quote-like-hoverable', 'overflow-hidden')}\n        onClick={() => appImManager.onSponsoredMessageClick(message())}\n        ref={(el) => {\n          createContextMenu({\n            listenTo: el,\n            buttons: getSponsoredMessageButtons({\n              message: message(),\n              handleReportAd: () => {\n                showAdReport(message(), () => props.setHidden(false));\n              },\n              handleCopy: () => {\n                copyTextToClipboard(message().message);\n              }\n            }),\n            middleware\n          });\n        }}\n      >\n        <Show when={photo()}>\n          <div class={/* @once */ classNames(styles.photoWrap, 'disable-hover')}>\n            <PhotoTsx\n              class={/* @once */ styles.photo}\n              photo={photo()}\n              boxWidth={32}\n              boxHeight={32}\n              withoutPreloader\n            />\n          </div>\n        </Show>\n        <div class={/* @once */ classNames(styles.content, 'disable-hover')}>\n          <div class=\"text-bold\">\n            <I18nTsx class=\"primary\" key=\"SponsoredMessageAd\" />\n            {' '}\n            {wrapEmojiText(message().title)}\n          </div>\n          <div class=\"pre-wrap\">\n            {wrapRichText(message().message, {entities: message().entities})}\n          </div>\n        </div>\n      </RippleElement>\n      <Button.Icon\n        icon=\"close\"\n        onClick={(e) => {\n          e.stopPropagation();\n          PopupPremium.show({feature: 'no_ads'});\n        }}\n      />\n    </Show>\n  );\n}\n\nexport default function createChatSponsoredPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatSponsoredPlate {\n  const [peerId, setPeerIdSignal] = createSignal<PeerId>(NULL_PEER_ID);\n\n  const plate = createTopbarPlate({\n    modifier: 'sponsored',\n    height: 'auto',\n    onVisibilityChange: () => topbar.setFloating(),\n    render: ({setHidden}) => (\n      <SponsoredPlateBody\n        peerId={peerId}\n        chat={chat}\n        managers={managers}\n        setHidden={setHidden}\n      />\n    )\n  });\n\n  return {\n    ...plate,\n    setPeerId: (next) => setPeerIdSignal(next)\n  };\n}\n","import {AvatarNewTsx} from '@components/avatarNew';\nimport {ButtonMenuToggleTsx} from '@components/buttonMenuToggleTsx';\nimport Chat from '@components/chat/chat';\nimport ChatTopbar from '@components/chat/topbar';\nimport TopbarPlate, {createTopbarPlate, TopbarPlateController} from '@components/chat/topbarPlate';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport {PeerSettings} from '@layer';\nimport isSameUserId from '@helpers/isSameUserId';\nimport {AppManagers} from '@lib/managers';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {Accessor, createMemo, createSignal, Show} from 'solid-js';\n\ntype AutomationState = {\n  peerId: PeerId,\n  botId: UserId,\n  paused: boolean,\n  canReply: boolean,\n  manageUrl?: string\n};\n\nexport type ChatAutomationPlate = TopbarPlateController & {\n  set: (peerId: PeerId, settings: PeerSettings) => () => void,\n  unset: (peerId: PeerId) => void,\n  handleConnectedBotUpdate: (botId?: UserId) => void\n};\n\nfunction AutomationPlateBody(props: {\n  state: Accessor<AutomationState | undefined>,\n  onToggle: () => void,\n  onManage: () => void,\n  onRemove: () => void\n}) {\n  const statusKey = createMemo<LangPackKey>(() => {\n    const state = props.state();\n    if(state?.paused) return 'ChatAutomation.BotPaused';\n    if(state?.canReply) return 'ChatAutomation.BotManagesChat';\n    return 'ChatAutomation.BotHasAccess';\n  });\n\n  const canToggle = createMemo(() => {\n    const state = props.state();\n    return !!(state?.paused || state?.canReply);\n  });\n\n  return (\n    <TopbarPlate.Body noRipple class=\"person\">\n      <Show when={props.state()}>\n        {(state) => (\n          <>\n            <AvatarNewTsx\n              class=\"person-avatar\"\n              peerId={state().botId.toPeerId(false)}\n              size={40}\n              isDialog\n            />\n            <div class=\"content\">\n              <div class=\"top\">\n                <div class=\"user-title\">\n                  <PeerTitleTsx peerId={state().botId.toPeerId(false)} />\n                </div>\n              </div>\n              <div class=\"bottom\">\n                <div class=\"info\">{i18n(statusKey())}</div>\n              </div>\n            </div>\n            <Show when={canToggle()}>\n              <TopbarPlate.ActionButton onClick={props.onToggle}>\n                {i18n(state().paused ? 'ChatAutomation.Start' : 'ChatAutomation.Stop')}\n              </TopbarPlate.ActionButton>\n            </Show>\n            <ButtonMenuToggleTsx\n              class=\"pinned-automation-menu\"\n              direction=\"bottom-right\"\n              buttons={[{\n                icon: 'settings',\n                text: 'ChatAutomation.ManageBot',\n                onClick: props.onManage,\n                verify: () => !!props.state()?.manageUrl\n              }, {\n                icon: 'delete',\n                text: 'ChatAutomation.RemoveFromChat',\n                danger: true,\n                onClick: props.onRemove,\n                verify: () => !!(props.state()?.paused || props.state()?.canReply)\n              }, {\n                icon: 'delete',\n                text: 'ChatAutomation.RevokeFromChat',\n                danger: true,\n                onClick: props.onRemove,\n                verify: () => !!props.state() && !props.state()?.paused && !props.state()?.canReply\n              }]}\n            />\n          </>\n        )}\n      </Show>\n    </TopbarPlate.Body>\n  );\n}\n\nexport default function createChatAutomationPlate(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): ChatAutomationPlate {\n  const [state, setState] = createSignal<AutomationState>();\n  const [busy, setBusy] = createSignal(false);\n  let stateGeneration = 0;\n\n  const plate = createTopbarPlate({\n    modifier: 'automation',\n    height: 52,\n    onVisibilityChange: () => topbar.setFloating(),\n    render: () => (\n      <AutomationPlateBody\n        state={state}\n        onToggle={async() => {\n          const previous = state();\n          if(!previous || busy()) return;\n\n          const generation = stateGeneration;\n          const paused = !previous.paused;\n          setBusy(true);\n          setState({...previous, paused, canReply: !paused});\n          try {\n            await managers.appBusinessManager.toggleConnectedBotPaused(\n              previous.peerId,\n              paused,\n              previous.botId\n            );\n          } catch(err) {\n            if(stateGeneration === generation) setState(previous);\n          } finally {\n            if(stateGeneration === generation) setBusy(false);\n          }\n        }}\n        onManage={() => {\n          const url = state()?.manageUrl;\n          if(url) chat.appImManager.openUrl(url, true);\n        }}\n        onRemove={async() => {\n          const previous = state();\n          if(!previous || busy()) return;\n\n          const generation = stateGeneration;\n          setBusy(true);\n          setState(undefined);\n          plate.setHidden(true);\n          try {\n            await managers.appBusinessManager.disablePeerConnectedBot(previous.peerId, previous.botId);\n          } catch(err) {\n            if(stateGeneration === generation) {\n              setState(previous);\n              plate.setHidden(false);\n            }\n          } finally {\n            if(stateGeneration === generation) setBusy(false);\n          }\n        }}\n      />\n    )\n  });\n\n  const unset = (peerId: PeerId) => {\n    ++stateGeneration;\n    setBusy(false);\n    setState(undefined);\n    plate.setHidden(true);\n  };\n\n  const set = (peerId: PeerId, settings: PeerSettings) => {\n    const botId = settings?.business_bot_id as UserId;\n    if(!peerId.isUser() || !botId) {\n      return () => unset(peerId);\n    }\n\n    return () => {\n      ++stateGeneration;\n      setBusy(false);\n      setState({\n        peerId,\n        botId,\n        paused: !!settings.pFlags?.business_bot_paused,\n        canReply: !!settings.pFlags?.business_bot_can_reply,\n        manageUrl: settings.business_bot_manage_url\n      });\n      plate.setHidden(false);\n    };\n  };\n\n  const handleConnectedBotUpdate = (botId?: UserId) => {\n    const current = state();\n    if(!current) {\n      if(!busy() && botId && chat.peerId?.isUser()) {\n        managers.appProfileManager.refreshPeerSettings(chat.peerId).catch(() => {});\n      }\n      return;\n    }\n\n    if(!botId || !isSameUserId(current.botId, botId)) {\n      unset(current.peerId);\n    }\n    managers.appProfileManager.refreshPeerSettingsIfNeeded(current.peerId).catch(() => {});\n  };\n\n  return {...plate, set, unset, handleConnectedBotUpdate};\n}\n","/**\n * Single place where every topbar floating plate (except the per-peer\n * `pinnedMessage` plate) is constructed, mounted, and torn down. Topbar\n * holds one `plates` field, lists/peers/destroy go through here.\n *\n * The pinned-message plate is excluded because it is recreated per peer\n * (its prepare/reveal lifecycle is driven from `topbar.setupPinnedMessageForPeer`).\n */\n\nimport type Chat from '@components/chat/chat';\nimport type ChatTopbar from '@components/chat/topbar';\nimport {AppManagers} from '@lib/managers';\nimport IS_LIVE_STREAM_SUPPORTED from '@environment/liveStreamSupport';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport createChatRequestsPlate, {ChatRequestsPlate} from '@components/chat/requests';\nimport createChatActionsPlate, {ChatActionsPlate} from '@components/chat/actions';\nimport createChatRemoveFeePlate, {ChatRemoveFeePlate} from '@components/chat/removeFee';\nimport createChatLivePlate, {ChatLivePlate} from '@components/chat/topbarLive/container';\nimport createChatGroupCallPlate, {ChatGroupCallPlate} from '@components/chat/topbarGroupCall/container';\nimport createChatTranslationPlate, {ChatTranslationPlate} from '@components/chat/translation';\nimport createChatSponsoredPlate, {ChatSponsoredPlate} from '@components/chat/topbarSponsored';\nimport {TopbarPlateController} from '@components/chat/topbarPlate';\nimport createChatAutomationPlate, {ChatAutomationPlate} from '@components/chat/chatAutomation';\n\nexport type TopbarPlates = {\n  requests: ChatRequestsPlate,\n  actions: ChatActionsPlate,\n  automation: ChatAutomationPlate,\n  removeFee: ChatRemoveFeePlate,\n  live: ChatLivePlate | undefined,\n  groupCall: ChatGroupCallPlate | undefined,\n  translation: ChatTranslationPlate,\n  sponsored: ChatSponsoredPlate,\n  /** Ordered list of all constructed plates. Used by `topbar.setFloating`. */\n  all: TopbarPlateController[],\n  /** Mount every plate's container into the given host. */\n  mount: (host: HTMLElement) => void,\n  destroy: () => void\n};\n\nexport function createTopbarPlates(\n  topbar: ChatTopbar,\n  chat: Chat,\n  managers: AppManagers\n): TopbarPlates {\n  const requests = createChatRequestsPlate(topbar, chat, managers);\n  const automation = createChatAutomationPlate(topbar, chat, managers);\n  const actions = createChatActionsPlate(topbar, chat, managers, automation);\n  const live = IS_LIVE_STREAM_SUPPORTED ? createChatLivePlate(topbar, chat, managers) : undefined;\n  const groupCall = IS_GROUP_CALL_SUPPORTED ? createChatGroupCallPlate(topbar, chat, managers) : undefined;\n  const translation = createChatTranslationPlate(topbar, chat, managers);\n  const removeFee = createChatRemoveFeePlate(topbar, chat, managers);\n  const sponsored = createChatSponsoredPlate(topbar, chat, managers);\n\n  // Order matches the visual stack inside `floatingPlatesWrapper`.\n  const all = [requests, actions, automation, live, groupCall, translation, removeFee, sponsored].filter(Boolean);\n\n  return {\n    requests,\n    actions,\n    automation,\n    removeFee,\n    live,\n    groupCall,\n    translation,\n    sponsored,\n    all,\n    mount: (host) => host.append(...all.map((plate) => plate.container)),\n    destroy: () => all.forEach((plate) => plate.destroy())\n  };\n}\n","import showFeatureDetailsPopup from '@components/popups/featureDetails';\nimport {i18n} from '@lib/langPack';\n\nexport default function showNoForwardsPopup(onConfirm: () => void) {\n  showFeatureDetailsPopup({\n    title: i18n('DisableSharing'),\n    rows: [{\n      icon: 'sharingoff_filled',\n      title: i18n('DisableSharing.Row1.Title'),\n      subtitle: i18n('DisableSharing.Row1.Subtitle')\n    }, {\n      icon: 'down_crossed',\n      title: i18n('DisableSharing.Row2.Title'),\n      subtitle: i18n('DisableSharing.Row2.Subtitle')\n    }],\n    buttons: [{\n      text: i18n('DisableSharing'),\n      onClick: onConfirm\n    }],\n    sticker: {\n      name: 'hand_stop'\n    }\n  });\n}\n","import type SidebarSlider from '@components/slider';\nimport type {AppSidebarRight} from '@components/sidebarRight';\nimport PopupElement from '@components/popups';\nimport {FormatterArguments, LangPackKey} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\n\n/**\n * Why the user was sent to boosting — a feature is locked behind a level. Without it the\n * boost popup falls back to its generic \"enable stories\" copy, which is wrong wherever the\n * level is needed for something else.\n */\nexport type BoostReason = {\n  titleLangKey: LangPackKey,\n  descriptionLangKey: LangPackKey,\n  descriptionArgs?: FormatterArguments\n};\n\n/**\n * Sends an admin to the Boosts tab — level progress plus the levers to raise it (boost link,\n * boosts via gifts) — and everyone else to the member-facing \"give your boost\" popup.\n * Every entry into boosting goes through here: the chat topbar's menu item, and the level\n * gates that offer boosting as the way past them.\n */\nexport default async function openBoosts({peerId, slider, reason}: {\n  peerId: PeerId,\n  slider: SidebarSlider,\n  reason?: BoostReason\n}) {\n  if(await rootScope.managers.appProfileManager.canViewStatistics(peerId)) {\n    const {default: AppBoostsTab} = await import('@components/sidebarRight/tabs/boosts');\n    // whatever sent the user here stays reachable with the tab open, so repeated taps must\n    // not stack copies of it\n    const current = slider.getHistory().slice(-1)[0];\n    if(!(current instanceof AppBoostsTab && current.peerId === peerId)) {\n      slider.createTab(AppBoostsTab).open(peerId);\n    }\n\n    // the entry may sit outside the sidebar — the chat topbar's does — so it has to be\n    // revealed; the left sidebar is where the user already is and has nothing to toggle\n    (slider as AppSidebarRight).toggleSidebar?.(true);\n    return;\n  }\n\n  const {default: PopupBoost} = await import('@components/popups/boost');\n  PopupElement.createPopup(PopupBoost, peerId, reason);\n}\n","import AppSelectPeers from '@components/appSelectPeers';\nimport PopupElement from '@components/popups';\nimport showLimitPopup from '@components/popups/limit';\nimport {wrapFormattedDuration} from '@components/wrappers/wrapDuration';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport formatDuration from '@helpers/formatDuration';\nimport {getMiddleware} from '@helpers/middleware';\nimport tsNow from '@helpers/tsNow';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\n\n/**\n * expect chat migration\n */\nexport async function handleChannelsTooMuch(getPromise: () => Promise<any>) {\n  try {\n    return await getPromise();\n  } catch(err) {\n    if((err as ApiError).type === 'CHANNELS_TOO_MUCH') {\n      await showChannelsTooMuchPopup();\n      return handleChannelsTooMuch(getPromise);\n    }\n\n    throw err;\n  }\n}\n\nexport async function showChannelsTooMuchPopup() {\n  const inactiveChannels = await rootScope.managers.appChatsManager.getInactiveChannels();\n  const deferred = deferredPromise<void>();\n  showLimitPopup('channels', async(popup) => {\n    const middlewareHelper = getMiddleware();\n    popup.addEventListener('closeAfterTimeout', () => {\n      deferred.reject();\n      middlewareHelper.destroy();\n    });\n    const datesMap = new Map<PeerId, number>();\n    const selector = new AppSelectPeers({\n      middleware: middlewareHelper.get(),\n      // @ts-ignore\n      appendTo: popup.body,\n      onChange: (value) => {\n        if(!value) {\n          mainButton.element.replaceChildren(...mainButtonChildren);\n          mainButton.callback = mainButtonCallback;\n        } else if(value) {\n          mainButton.element.replaceChildren(i18n('LeaveCommunities', [value]));\n          mainButton.callback = async() => {\n            const peerIds = selector.getSelected();\n            for(const peerId of peerIds) {\n              await rootScope.managers.appChatsManager.leave(peerId.toChatId());\n            }\n            deferred.resolve();\n          };\n        }\n      },\n      onFirstRender: () => {\n        popup.show();\n        selector.checkForTriggers(); // ! due to zero height before mounting\n        selector.scrollable.onAdditionalScroll();\n      },\n      multiSelect: true,\n      noSearch: true,\n      sectionNameLangPackKey: 'LeastActiveCommunities',\n      avatarSize: 'abitbigger',\n      managers: rootScope.managers,\n      peerType: [],\n      getSubtitleForElement: async(peerId) => {\n        const date = datesMap.get(peerId);\n        const duration = tsNow(true) - date;\n        return i18n('InactiveChannel', [\n          await rootScope.managers.appPeersManager.isBroadcast(peerId) ?\n            i18n('InactiveChannel.Broadcast') :\n            i18n('InactiveChannel.Group'),\n          wrapFormattedDuration(formatDuration(duration, 1))\n        ]);\n      }\n    });\n\n    selector.scrollable.attachBorderListeners();\n\n    const peerIds = inactiveChannels.map(({id, date}) => {\n      const peerId = id.toPeerId(true);\n      datesMap.set(peerId, date);\n      return peerId;\n    });\n\n    selector.renderResultsFunc(peerIds);\n\n    // @ts-ignore\n    const mainButton = popup.buttons[0];\n    const mainButtonChildren = [...mainButton.element.children];\n    const mainButtonCallback = mainButton.callback;\n  });\n\n  return deferred;\n}\n","import {toastNew} from '@components/toast';\nimport type {AppManagers} from '@lib/managers';\n\nexport default function handleCommunityChatJoinError(options: {\n  error: ApiError,\n  isBroadcast: boolean,\n  communityId?: ChatId,\n  managers: Pick<AppManagers, 'appProfileManager'>\n}) {\n  switch(options.error.type) {\n    case 'INVITE_REQUEST_SENT': {\n      toastNew({\n        langPackKey: options.isBroadcast ?\n          'Community.ChannelRequestSent' :\n          'Community.GroupRequestSent'\n      });\n      return true;\n    }\n    case 'USERS_TOO_MUCH':\n    case 'GROUP_FULL': {\n      toastNew({langPackKey: 'Community.GroupFull'});\n      return true;\n    }\n    case 'CHANNEL_PRIVATE':\n    case 'CHANNEL_PUBLIC_GROUP_NA':\n    case 'USER_BANNED_IN_CHANNEL':\n    case 'ACCESS_DENIED': {\n      toastNew({\n        langPackKey: options.isBroadcast ?\n          'Community.ChannelNotAccessible' :\n          'Community.GroupNotAccessible'\n      });\n      if(options.communityId) {\n        void Promise.resolve(options.managers.appProfileManager.getChatFull(\n          options.communityId,\n          true\n        )).catch(() => {});\n      }\n      return true;\n    }\n    default:\n      return false;\n  }\n}\n","import {handleChannelsTooMuch} from '@components/popups/channelsTooMuch';\nimport handleCommunityChatJoinError\nfrom '@components/communities/handleCommunityChatJoinError';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport defaultAppImManager, {type AppImManager} from '@lib/appImManager';\nimport type {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\n\n\nexport default async function joinChat(options: {\n  peerId: PeerId,\n  managers: AppManagers,\n  appImManager?: AppImManager,\n  communityId?: ChatId\n}) {\n  const {peerId, managers} = options;\n  const chatId = peerId.toChatId();\n\n  try {\n    const isChannel = await managers.appChatsManager.isChannel(chatId);\n    const result = await handleChannelsTooMuch(() => {\n      return isChannel ?\n        managers.appChatsManager.joinChannel(chatId) :\n        managers.appChatsManager.addChatUser(chatId, rootScope.myId);\n    });\n    if(result?._ === 'chatInviteJoinWebView') {\n      void (options.appImManager ?? defaultAppImManager).openJoinChatWebView(result);\n    }\n  } catch(error) {\n    const chat = apiManagerProxy.getChat(chatId);\n    const isBroadcast = (\n      chat?._ === 'channel' ||\n      chat?._ === 'channelForbidden'\n    ) && !!chat.pFlags.broadcast;\n    if(handleCommunityChatJoinError({\n      error: error as ApiError,\n      isBroadcast,\n      communityId: options.communityId ?? (\n        chat?._ === 'channel' && chat.linked_community_id ?\n          chat.linked_community_id.toChatId() :\n          undefined\n      ),\n      managers\n    })) {\n      return;\n    }\n\n    throw error;\n  }\n}\n","import type {Channel} from '@appManagers/appChatsManager';\nimport type {AppSidebarRight} from '@components/sidebarRight';\nimport type Chat from '@components/chat/chat';\nimport {RIGHT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarRight';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport ButtonIcon from '@components/buttonIcon';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport createChatPinnedMessage, {ChatPinnedMessageController} from '@components/chat/pinnedMessage';\nimport getPinnedMessagesKey from '@appManagers/utils/messages/getPinnedMessagesKey';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport PopupDeleteDialog from '@components/popups/deleteDialog';\nimport {showPeerReport} from '@components/popups/reportAd';\nimport appNavigationController from '@components/appNavigationController';\nimport {LEFT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarLeft';\nimport PeerTitle from '@components/peerTitle';\nimport I18n, {LangPackKey, i18n} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {toastNew} from '@components/toast';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {ChatFull, Chat as MTChat, GroupCall, Dialog, InputGroupCall, User, UserFull} from '@layer';\nimport {showSharingPickerPopup} from '@components/popups/pickUser';\nimport PopupPeer, {PopupPeerCheckboxOptions} from '@components/popups/peer';\nimport {AppEditBotTab, AppEditContactTab} from '@components/solidJsTabs/tabs';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport IS_CALL_SUPPORTED from '@environment/callSupport';\nimport {CallType} from '@lib/calls/types';\nimport PopupMute from '@components/popups/mute';\nimport {AppManagers} from '@lib/managers';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport {FOLDER_ID_ALL} from '@appManagers/constants';\nimport formatNumber from '@helpers/number/formatNumber';\nimport PopupElement from '@components/popups';\nimport {modifyAckedPromise} from '@helpers/modifyAckedResult';\nimport callbackify from '@helpers/callbackify';\nimport confirmationPopup from '@components/confirmationPopup';\nimport clearHistoryWithConfirmation from '@components/clearHistory';\nimport canClearHistory from '@appManagers/utils/chats/canClearHistory';\nimport IS_LIVE_STREAM_SUPPORTED from '@environment/liveStreamSupport';\nimport {avatarNew, findUpAvatar} from '@components/avatarNew';\nimport {Middleware, MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport setBadgeContent from '@helpers/setBadgeContent';\nimport createBadge from '@helpers/createBadge';\nimport AppStatisticsTab from '@components/sidebarRight/tabs/statistics';\nimport {ChatType} from './chatType';\nimport {RtmpStartStreamPopup} from '@components/rtmp/adminPopup';\nimport PopupSendGift from '@components/popups/sendGift';\nimport PaidMessagesInterceptor, {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\nimport {openRemoveFeePopup} from '@components/chat/removeFee';\nimport {createTopbarPlates, TopbarPlates} from '@components/chat/topbarPlates';\nimport pause from '@helpers/schedulers/pause';\nimport appImManager from '@lib/appImManager';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport namedPromises from '@helpers/namedPromises';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {createEffect, createRoot, on, untrack} from 'solid-js';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {AppAdminRecentActionsTab} from '@components/solidJsTabs/tabs';\nimport {setAppSettings} from '@stores/appSettings';\nimport {wrapAsyncClickHandler} from '@helpers/wrapAsyncClickHandler';\nimport liteMode from '@helpers/liteMode';\nimport createSubmenuTrigger from '@components/createSubmenuTrigger';\nimport ButtonMenu, {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {getCachedFullPeer} from '@stores/fullPeers';\nimport Icon from '@components/icon';\nimport {getDefaultOptions} from '@components/sidebarLeft/tabs/autoDeleteMessages/options';\nimport {createAutoDeleteIcon} from '@components/autoDeleteIcon';\nimport PopupPremium from '@components/popups/premium';\nimport showNoForwardsPopup from '@components/popups/noForwards';\nimport showAddBotToChat from '@components/popups/addBotToChat';\nimport openBoosts from '@components/openBoosts';\nimport getAddBotToChatAction from '@appManagers/utils/bots/getAddBotToChatAction';\nimport canReportBot from '@appManagers/utils/bots/canReportBot';\nimport joinChat from '@components/chat/joinChat';\n\ntype ButtonToVerify = {element?: HTMLElement, verify: () => boolean | Promise<boolean>};\n\nexport default class ChatTopbar {\n  public container: HTMLDivElement;\n  public floatingPlatesWrapper: HTMLDivElement;\n  private btnBack: HTMLButtonElement;\n  private btnBackBadge: HTMLElement;\n  private chatInfo: HTMLDivElement;\n  private avatar: ReturnType<typeof avatarNew>;\n  private avatarMiddlewareHelper: MiddlewareHelper;\n  private title: HTMLDivElement;\n  private subtitle: HTMLDivElement;\n  private chatUtils: HTMLDivElement;\n  private btnCall: HTMLButtonElement;\n  private btnGroupCall: HTMLButtonElement;\n  private btnGroupCallMenu: HTMLElement;\n  private btnSearch: HTMLButtonElement;\n  private btnLogFilters: HTMLButtonElement;\n  private btnMore: HTMLElement;\n\n  private autoDeleteBtnMenuOptions: ButtonMenuItemOptionsVerifiable;\n\n  public plates: TopbarPlates;\n  public pinnedMessage: ChatPinnedMessageController;\n\n\n  public listenerSetter: ListenerSetter;\n\n  private menuButtons: Parameters<typeof ButtonMenuToggle>[0]['buttons'];\n  private buttonsToVerify: ButtonToVerify[];\n  private chatInfoContainer: HTMLDivElement;\n  private person: HTMLDivElement;\n\n  private titleMiddlewareHelper: MiddlewareHelper;\n  private status: ReturnType<ChatTopbar['createStatus']>;\n\n  constructor(\n    private chat: Chat,\n    public appSidebarRight: AppSidebarRight,\n    private managers: AppManagers\n  ) {\n    this.listenerSetter = new ListenerSetter();\n\n    this.menuButtons = [];\n    this.buttonsToVerify = [];\n  }\n\n  public construct() {\n    // this.chat.log.error('Topbar construction');\n\n    this.container = document.createElement('div');\n    this.container.classList.add('sidebar-header', 'topbar', 'hide');\n    this.container.dataset.floating = '0';\n\n    // Preview mode swaps the back arrow for a close icon — the popup wires this up to its\n    // own hide() via `chat.onPreviewClose`, and the folder back-unread badge is irrelevant\n    // here (there's no folder navigation behind a floating preview).\n    const backIcon = this.chat.isPreview ? 'close' : 'left';\n    this.btnBack = ButtonIcon(`${backIcon} sidebar-close-button`, {noRipple: true});\n    if(!this.chat.isPreview) {\n      this.btnBackBadge = createBadge('span', 20, 'primary');\n      this.btnBackBadge.classList.add('back-unread-badge');\n      this.btnBack.append(this.btnBackBadge);\n    }\n\n    // * chat info section\n    this.chatInfoContainer = document.createElement('div');\n    this.chatInfoContainer.classList.add('chat-info-container');\n\n    this.chatInfo = document.createElement('div');\n    this.chatInfo.classList.add('chat-info');\n\n    const person = this.person = document.createElement('div');\n    person.classList.add('person');\n\n    const content = document.createElement('div');\n    content.classList.add('content');\n\n    const top = document.createElement('div');\n    top.classList.add('top');\n\n    this.title = document.createElement('div');\n    this.title.classList.add('user-title');\n\n    top.append(this.title);\n\n    const bottom = document.createElement('div');\n    bottom.classList.add('bottom');\n\n    if(this.subtitle) {\n      bottom.append(this.subtitle);\n    }\n\n    content.append(top, bottom);\n\n    person.append(content);\n    this.chatInfo.append(person);\n\n    // * chat utils section\n    this.chatUtils = document.createElement('div');\n    this.chatUtils.classList.add('chat-utils');\n\n    this.plates = createTopbarPlates(this, this.chat, this.managers);\n\n    if(this.menuButtons.length) {\n      this.btnMore = ButtonMenuToggle({\n        listenerSetter: this.listenerSetter,\n        direction: 'bottom-left',\n        buttons: this.menuButtons,\n        positionPadding: {top: 7},\n        onOpenBefore: async() => {\n          const hasAutoDeleteButton = await this.chat.canManageAutoDelete();\n          if(!hasAutoDeleteButton) return;\n\n          const period = await this.chat.getAutoDeletePeriod().then(ackedResult => ackedResult.result);\n          this.autoDeleteBtnMenuOptions.iconElement = createAutoDeleteIcon(period);\n        },\n        onOpen: async(e, element) => {\n          const deleteButton = this.menuButtons[this.menuButtons.length - 1];\n          if(deleteButton?.element) {\n            const deleteButtonText = await this.managers.appPeersManager.getDeleteButtonText(this.chat.monoforumThreadId || this.peerId);\n            deleteButton.element.lastChild.replaceWith(i18n(deleteButtonText));\n          }\n\n          this.autoDeleteBtnMenuOptions.onOpen?.();\n        },\n        onClose: () => {\n          this.autoDeleteBtnMenuOptions.onClose?.();\n        }\n      });\n    }\n\n    this.chatUtils.append(...[\n      // this.chatAudio ? this.chatAudio.divAndCaption.container : null,\n      // this.pinnedMessage ? this.pinnedMessage.pinnedMessageContainer.divAndCaption.container : null,\n      // btnJoin / btnMute / btnDirectMessages moved into the chat-input control plate (see input.ts).\n      this.btnCall,\n      this.btnGroupCall,\n      this.btnGroupCallMenu,\n      this.btnSearch,\n      this.btnLogFilters,\n      this.btnMore\n    ].filter(Boolean));\n\n    this.pushButtonToVerify(this.btnCall, this.verifyCallButton.bind(this, 'voice'));\n    this.pushButtonToVerify(this.btnGroupCall, this.verifyVideoChatButton.bind(this, 'nonadmin'));\n    this.pushButtonToVerify(this.btnGroupCallMenu, this.verifyRtmpButton.bind(this));\n\n    // Preview keeps only the basic header — avatar + title + subtitle. The chat-utils\n    // pane (search / menu buttons) and the floating-plates wrapper (call / pinned /\n    // translation / action bar) are built so the rest of the JS can call methods on\n    // them, but never attached to the live DOM tree. They sit detached, so nothing\n    // visible leaks into the popup.\n    this.chatInfoContainer.append(this.btnBack, this.chatInfo);\n    if(!this.chat.isPreview) this.chatInfoContainer.append(this.chatUtils);\n    this.container.append(this.chatInfoContainer);\n\n    this.floatingPlatesWrapper = document.createElement('div');\n    this.floatingPlatesWrapper.classList.add('topbar-floating-plates', 'hide');\n    if(!this.chat.isPreview) this.container.append(this.floatingPlatesWrapper);\n\n    // the pinned plate is prepended here by `revealPreparedPinnedMessage`, in the\n    // same frame as the bubbles it belongs to\n\n    this.plates.mount(this.floatingPlatesWrapper);\n\n    // * construction end\n\n    // * fix topbar overflow section\n\n    this.listenerSetter.add(window)('resize', this.onResize);\n    this.listenerSetter.add(mediaSizes)('changeScreen', this.onChangeScreen);\n\n    attachClickEvent(this.container, (e) => {\n      if(\n        findUpClassName(e.target, 'topbar-search-container') ||\n        !(e.target as HTMLElement).isConnected ||\n        findUpClassName(e.target, 'chat-search-top')\n      ) {\n        return;\n      }\n\n      const container = findUpClassName(e.target, 'pinned-container');\n      blurActiveElement();\n      if(container) {\n        return;\n      } else {\n        const avatar = findUpAvatar(e.target);\n        if(mediaSizes.activeScreen === ScreenSize.medium && document.body.classList.contains(LEFT_COLUMN_ACTIVE_CLASSNAME)) {\n          onBtnBackClick();\n        } else if(avatar) {\n          if(avatar.classList.contains('has-stories')) {\n            return;\n          }\n\n          this.appSidebarRight.toggleSidebar(!document.body.classList.contains(RIGHT_COLUMN_ACTIVE_CLASSNAME));\n        } else {\n          this.appSidebarRight.toggleSidebar(true);\n        }\n      }\n    }, {listenerSetter: this.listenerSetter});\n\n    const onBtnBackClick = (e?: Event) => {\n      if(e) {\n        cancelEvent(e);\n      }\n\n      if(this.chat.isPreview) {\n        this.chat.onPreviewClose?.();\n        return;\n      }\n\n      if(this.chat.type === ChatType.Search) {\n        this.chat.resetSearch();\n        return;\n      }\n\n      this.chat.pop();\n    };\n\n    attachClickEvent(this.btnBack, onBtnBackClick, {listenerSetter: this.listenerSetter});\n  }\n\n  private pushButtonToVerify(element: HTMLElement, verify: ButtonToVerify['verify']) {\n    if(!element) {\n      return;\n    }\n\n    element.classList.add('hide');\n    this.buttonsToVerify.push({element, verify});\n  }\n\n  private verifyButtons = (e?: Event) => {\n    const isMenuOpen = !!e || !!(this.btnMore && this.btnMore.classList.contains('menu-open'));\n\n    e && cancelEvent(e);\n\n    const r = async() => {\n      const buttons = this.buttonsToVerify.concat(isMenuOpen ? this.menuButtons as any : []);\n      const results = await Promise.all(buttons.map(async(button) => {\n        return {\n          result: await button.verify(),\n          button\n        }\n      }));\n\n      results.forEach(({button, result}) => {\n        button.element?.classList.toggle('hide', !result);\n      });\n    };\n\n    r();\n  };\n\n  private verifyRtmpButton = async() => {\n    if(!this.chat.isBroadcast || this.chat.type !== ChatType.Chat) {\n      return false;\n    }\n\n    const currentGroupCall = groupCallsController.groupCall;\n    const chatId = this.peerId.toChatId();\n    if(currentGroupCall?.chatId === chatId) {\n      return false;\n    }\n\n    const chat = this.chat.peer as MTChat.channel | MTChat.chat;\n    if(!chat) {\n      return false;\n    }\n\n    const isCallActive = !!(chat as MTChat.chat).pFlags?.call_active;\n    if(isCallActive) {\n      return false;\n    }\n\n    return hasRights(chat, 'manage_call');\n  };\n\n  private verifyVideoChatButton = async(type?: 'group' | 'broadcast' | 'nonadmin') => {\n    if(\n      !IS_GROUP_CALL_SUPPORTED ||\n      this.peerId.isUser() ||\n      this.chat.type !== ChatType.Chat ||\n      this.chat.threadId\n    ) return false;\n\n    const currentGroupCall = groupCallsController.groupCall;\n    const chatId = this.peerId.toChatId();\n    if(currentGroupCall?.chatId === chatId) {\n      return false;\n    }\n\n    if(type) {\n      if(((type === 'group' && !this.chat.isAnyGroup)) ||\n        ((type === 'broadcast' && !this.chat.isBroadcast))) {\n        return false;\n      }\n    }\n\n    const chat = this.chat.peer as MTChat.channel | MTChat.chat;\n    const isCallActive = !!(chat as MTChat.chat).pFlags?.call_active;\n    const canManageCall = hasRights(chat, 'manage_call');\n    if(type === 'nonadmin' && canManageCall && this.chat.isBroadcast) {\n      return false; // * hide live stream top button\n    }\n    const needActiveCall = !canManageCall;\n    if(!isCallActive) {\n      return !needActiveCall;\n    }\n\n    const fullChat = await this.managers.appProfileManager.getChatFull(chatId);\n    if(!('call' in fullChat) || !fullChat.call) {\n      return false;\n    }\n    const inputGroupCall = fullChat.call as InputGroupCall.inputGroupCall;\n    const groupCall = await this.managers.appGroupCallsManager.getGroupCallFull(\n      inputGroupCall.id\n    );\n    if(groupCall?._ !== 'groupCall') return false;\n\n    return !groupCall.pFlags.rtmp_stream;\n  };\n\n  private verifyCallButton = async(type?: CallType) => {\n    if(!IS_CALL_SUPPORTED || !this.peerId.isUser() || this.chat.type !== ChatType.Chat) return false;\n    const userId = this.peerId.toUserId();\n    const userFull = await this.managers.appProfileManager.getCachedFullUser(userId);\n\n    return !!userFull && !!(type === 'voice' ? userFull.pFlags.phone_calls_available : userFull.pFlags.video_calls_available);\n  };\n\n  private verifyIfCanReportChat = () => {\n    if(\n      this.chat.type !== ChatType.Chat ||\n      this.chat.threadId ||\n      this.chat.isMonoforum\n    ) {\n      return false;\n    }\n\n    const peer = this.chat.peer;\n    if(peer?._ === 'user') {\n      return canReportBot(this.peerId, peer);\n    }\n\n    return !!peer && (peer._ === 'chat' || peer._ === 'channel') && !peer.pFlags.creator;\n  };\n\n  private verifyIfCanClearHistory = async() => {\n    if(\n      this.chat.type !== ChatType.Chat ||\n      this.chat.threadId ||\n      this.chat.monoforumThreadId ||\n      this.chat.isMonoforum\n    ) {\n      return false;\n    }\n\n    return canClearHistory(this.chat.peer) &&\n      !!(await this.managers.appMessagesManager.getDialogOnly(this.peerId));\n  }\n\n  private verifyIfCanDeleteChat = async() => {\n    if(this.chat.isMonoforum) {\n      const chat = this.chat.peer;\n      return chat?._ === 'channel' && !chat?.pFlags?.creator && !chat?.pFlags?.left;\n    }\n\n    if(this.chat.type === ChatType.Saved) return true;\n\n    return (\n      this.chat.type === ChatType.Chat &&\n      !!(await this.managers.appMessagesManager.getDialogOnly(this.peerId))\n    );\n  }\n\n  public constructUtils() {\n    this.autoDeleteBtnMenuOptions = createSubmenuTrigger({\n      options: {\n        text: 'AutoDeleteMessagesShort',\n        separatorDown: true,\n        verify: this.chat.canManageAutoDelete\n      },\n      createSubmenu: this.createAutoDeleteSubmenu.bind(this),\n      direction: 'left-start'\n    });\n\n    const onBoostClick = () => openBoosts({peerId: this.peerId, slider: this.appSidebarRight});\n\n    const getBotAddToChatAction = () => this.peerId.isUser() && getAddBotToChatAction(\n      this.chat.peer as User.user,\n      this.chat.fullPeer() as UserFull.userFull\n    );\n    const onAddBotToChat = () => showAddBotToChat({botId: this.peerId.toUserId()});\n    const verifyAddBotToChat = (text: LangPackKey) => () => getBotAddToChatAction()?.text === text;\n\n    this.menuButtons = [this.autoDeleteBtnMenuOptions, {\n      icon: 'search',\n      text: 'Search',\n      onClick: () => {\n        this.chat.initSearch();\n      },\n      verify: () => mediaSizes.isMobile\n    }, {\n      icon: 'filter',\n      text: 'FilterActions',\n      onClick: () => {\n        this.onFilterActionsClick();\n      },\n      verify: () => mediaSizes.isMobile && this.chat.type === ChatType.Logs\n    }, /* {\n      icon: 'pinlist',\n      text: 'Pinned Messages',\n      onClick: () => this.openPinned(false),\n      verify: () => mediaSizes.isMobile\n    }, */{\n      icon: 'mute',\n      text: 'ChatList.Context.Mute',\n      onClick: this.onMuteClick,\n      verify: async() => this.chat.type === ChatType.Chat && !this.chat.monoforumThreadId && rootScope.myId !== this.peerId && !(await this.managers.appNotificationsManager.isPeerLocalMuted({peerId: this.peerId, respectType: false, threadId: this.chat.threadId}))\n    }, {\n      icon: 'unmute',\n      text: 'ChatList.Context.Unmute',\n      onClick: this.onUnmuteClick,\n      verify: () => this.chat.type === ChatType.Chat && !this.chat.monoforumThreadId && rootScope.myId !== this.peerId && this.managers.appNotificationsManager.isPeerLocalMuted({peerId: this.peerId, respectType: false, threadId: this.chat.threadId})\n    }, {\n      icon: 'comments',\n      text: 'ViewDiscussion',\n      onClick: () => {\n        const middleware = this.chat.bubbles.getMiddleware();\n        Promise.resolve(this.managers.appProfileManager.getChannelFull(this.peerId.toChatId())).then((channelFull) => {\n          if(middleware() && channelFull.linked_chat_id) {\n            this.chat.appImManager.setInnerPeer({\n              peerId: channelFull.linked_chat_id.toPeerId(true)\n            });\n          }\n        });\n      },\n      verify: async() => {\n        const chatFull = await this.managers.appProfileManager.getCachedFullChat(this.peerId.toChatId());\n        return this.chat.type === ChatType.Chat && !!(chatFull as ChatFull.channelFull)?.linked_chat_id;\n      }\n    }, {\n      icon: 'phone',\n      text: 'Call',\n      onClick: this.onCallClick.bind(this, 'voice'),\n      verify: this.verifyCallButton.bind(this, 'voice')\n    }, {\n      icon: 'videocamera',\n      text: 'VideoCall',\n      onClick: this.onCallClick.bind(this, 'video'),\n      verify: this.verifyCallButton.bind(this, 'video')\n    }, {\n      icon: 'videochat',\n      text: 'PeerInfo.Action.LiveStream',\n      onClick: this.onJoinGroupCallClick,\n      verify: this.verifyVideoChatButton.bind(this, 'broadcast')\n    }, {\n      icon: 'videochat',\n      text: 'PeerInfo.Action.VoiceChat',\n      onClick: this.onJoinGroupCallClick,\n      verify: this.verifyVideoChatButton.bind(this, 'group')\n    }, {\n      icon: 'topics',\n      text: 'TopicViewAsTopics',\n      onClick: () => {\n        this.chat.appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      verify: async() => {\n        // the flag outlives the forum it was set for, so ask the peer too\n        if(!apiManagerProxy.isForum(this.peerId)) {\n          return false;\n        }\n\n        const dialog = await this.managers.appMessagesManager.getDialogOnly(this.peerId);\n        return !!(dialog && (dialog as Dialog.dialog).pFlags.view_forum_as_messages);\n      }\n    }, {\n      icon: 'topics',\n      text: 'SavedViewAsChats',\n      onClick: () => {\n        this.chat.appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      verify: () => this.peerId === rootScope.myId && !this.chat.threadId && !this.chat.appSettings.savedAsForum\n    }, {\n      icon: 'message',\n      text: 'ChannelDirectMessages.ViewChats',\n      onClick: () => {\n        appDialogsManager.toggleForumTabByPeerId(this.peerId, true);\n      },\n      verify: () => this.chat.isMonoforum && !this.chat.monoforumThreadId && this.chat.canManageDirectMessages && !mediaSizes.isLessThanFloatingLeftSidebar && !appDialogsManager.hasForumOpenFor(this.peerId)\n    }, {\n      icon: 'select',\n      text: 'Chat.Menu.SelectMessages',\n      onClick: () => {\n        const selection = this.chat.selection;\n        selection.toggleSelection(true, true);\n        if(this.chat.appSettings.chatContextMenuHintWasShown) {\n          return;\n        }\n\n        const original = selection.toggleByElement.bind(selection);\n        selection.toggleByElement = async(bubble) => {\n          this.chat.setAppSettings('chatContextMenuHintWasShown', true);\n          toastNew({langPackKey: 'Chat.Menu.Hint'});\n\n          selection.toggleByElement = original;\n          selection.toggleByElement(bubble);\n        };\n      },\n      verify: () => !this.chat.selection.isSelecting && !!this.chat.bubbles.getRenderedLength() && !(this.chat.type === ChatType.Logs)\n    }, {\n      icon: 'select',\n      text: 'Chat.Menu.ClearSelection',\n      onClick: () => {\n        this.chat.selection.cancelSelection();\n      },\n      verify: () => this.chat.selection.isSelecting\n    }, {\n      icon: 'adduser',\n      text: 'AddContact',\n      onClick: () => {\n        this.addContact();\n      },\n      verify: async() => !this.chat.isBot && (this.chat.monoforumThreadId || this.peerId).isUser() && !(await this.managers.appPeersManager.isContact(this.chat.monoforumThreadId || this.peerId))\n    }, {\n      icon: 'adduser',\n      text: 'AddToGroup',\n      onClick: onAddBotToChat,\n      verify: verifyAddBotToChat('AddToGroup')\n    }, {\n      icon: 'adduser',\n      text: 'BotAddToGroupOrChannel',\n      onClick: onAddBotToChat,\n      verify: verifyAddBotToChat('BotAddToGroupOrChannel')\n    }, {\n      icon: 'adduser',\n      text: 'AddToChannel',\n      onClick: onAddBotToChat,\n      verify: verifyAddBotToChat('AddToChannel')\n    }, {\n      icon: 'forward',\n      text: 'ShareContact',\n      onClick: () => {\n        const contactPeerId = this.peerId;\n        showSharingPickerPopup({\n          onSelect: async(chosen) => {\n            const {peerId, monoforumThreadId} = chosen[0];\n            const preparedPaymentResult = await PaidMessagesInterceptor.prepareStarsForPayment({messageCount: 1, peerId});\n            if(preparedPaymentResult === PAYMENT_REJECTED) throw new Error();\n\n            const send = () => {\n              this.managers.appMessagesManager.sendContact({peerId, contactPeerId, confirmedPaymentResult: preparedPaymentResult, monoforumThreadId});\n              this.chat.appImManager.setInnerPeer({peerId});\n            };\n\n            if(preparedPaymentResult) return void send();\n\n            return new Promise((resolve, reject) => {\n              PopupElement.createPopup(PopupPeer, '', {\n                titleLangKey: 'SendMessageTitle',\n                descriptionLangKey: 'SendContactToGroupText',\n                descriptionLangArgs: [new PeerTitle({peerId, dialog: true}).element],\n                buttons: [{\n                  langKey: 'Send',\n                  callback: async() => {\n                    resolve();\n                    send();\n                  }\n                }, {\n                  langKey: 'Cancel',\n                  callback: () => {\n                    reject();\n                  },\n                  isCancel: true\n                }],\n                peerId,\n                overlayClosable: true\n              }).show();\n            });\n          }\n        });\n      },\n      verify: async() => rootScope.myId !== this.peerId && this.peerId.isUser() && (await this.managers.appPeersManager.isContact(this.peerId)) && !!(await this.managers.appUsersManager.getUser(this.peerId.toUserId())).phone\n    }, {\n      icon: 'gift',\n      text: 'Chat.Menu.SendGift',\n      onClick: () => PopupElement.createPopup(PopupSendGift, {peerId: this.peerId}),\n      verify: async() => (\n        this.chat.isChannel || (this.chat.peerId.isUser() && !this.chat.isBot && (await this.managers.appUsersManager.isRegularUser(this.peerId)))\n      ) && !(this.chat.type === ChatType.Logs)\n    }, {\n      icon: 'message',\n      text: 'ChannelDirectMessages.Manage',\n      onClick: () => this.onDirectMessagesClick(),\n      verify: () => this.chat.isChannel && this.chat.canManageDirectMessages && !this.chat.isMonoforum && !!(this.chat.peer as MTChat.channel).linked_monoforum_id && this.chat.type !== ChatType.Logs\n    }, {\n      icon: 'statistics_chart',\n      text: 'Statistics',\n      onClick: () => {\n        this.appSidebarRight.createTab(AppStatisticsTab).open(this.peerId.toChatId());\n        this.appSidebarRight.toggleSidebar(true);\n      },\n      verify: () => !this.chat.monoforumThreadId && this.managers.appProfileManager.canViewStatistics(this.peerId)\n    }, {\n      icon: 'addboost',\n      text: 'BoostChannel',\n      onClick: onBoostClick,\n      verify: async() => this.chat.isBroadcast\n    }, {\n      icon: 'addboost',\n      text: 'BoostGroup',\n      onClick: onBoostClick,\n      verify: async() => this.chat.isMegagroup\n    }, {\n      icon: 'bots',\n      text: 'Settings',\n      onClick: () => {\n        // [ ] Bot with paid stars?\n        this.managers.appMessagesManager.sendText({peerId: this.peerId, text: '/settings'});\n      },\n      verify: async() => {\n        try {\n          const attachMenuBot = await this.managers.appAttachMenuBotsManager.getAttachMenuBot(this.peerId.toUserId());\n          return !!attachMenuBot?.pFlags?.has_settings;\n        } catch(err) {\n          return false;\n        }\n      }\n    }, {\n      icon: 'premium_translate',\n      text: 'Translate',\n      onClick: () => {\n        this.managers.appTranslationsManager.togglePeerTranslations(\n          this.peerId,\n          false\n        ).then(() => {\n          if(this.chat.peerTranslation.canTranslate()) {\n            this.chat.peerTranslation.toggle(true);\n          }\n        });\n      },\n      verify: async() => {\n        if(!this.chat.peerTranslation.areTranslationsAvailable()) {\n          return false;\n        }\n\n        const fullPeer = await this.managers.appProfileManager.getCachedProfileByPeerId(this.peerId);\n        return fullPeer && 'pFlags' in fullPeer && !!fullPeer.pFlags.translations_disabled;\n      }\n    }, {\n      icon: 'lock',\n      text: 'BlockUser',\n      onClick: () => {\n        this.blockUser();\n      },\n      verify: async() => {\n        if(!this.peerId.isUser()) return false;\n        const userFull = await this.managers.appProfileManager.getCachedFullUser(this.peerId.toUserId());\n        return this.peerId !== rootScope.myId && userFull && !userFull.pFlags?.blocked;\n      }\n    }, {\n      icon: 'lockoff',\n      text: 'Unblock',\n      onClick: () => {\n        this.managers.appUsersManager.toggleBlock(this.peerId, false).then(() => {\n          toastNew({langPackKey: 'UserUnblocked'});\n        });\n      },\n      verify: async() => {\n        const userFull = await this.managers.appProfileManager.getCachedFullUser(this.peerId.toUserId());\n        return !!userFull?.pFlags?.blocked;\n      }\n    }, {\n      icon: 'sharingoff',\n      text: 'DisableSharing',\n      onClick: () => {\n        if(!rootScope.premium) {\n          PopupPremium.show({feature: 'pm_noforwards'});\n          return;\n        }\n\n        const cb = () => this.managers.appProfileManager.toggleNoForwards(this.peerId, true);\n        if(this.chat.appSettings.seenTooltips.noForwards) {\n          cb();\n        } else {\n          showNoForwardsPopup(() => {\n            setAppSettings('seenTooltips', 'noForwards', true);\n            cb();\n          });\n        }\n      },\n      verify: async() => {\n        if(!this.peerId.isUser() || this.peerId === rootScope.myId || this.chat.isBot) return false;\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        if(!userFull) return false;\n        return !userFull.pFlags.noforwards_my_enabled && !userFull.pFlags.noforwards_peer_enabled;\n      }\n    }, {\n      icon: 'sharingon',\n      text: 'EnableSharing',\n      onClick: async() => {\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        const {peerId} = this;\n\n        if(userFull.pFlags.noforwards_peer_enabled) {\n          await confirmationPopup({\n            titleLangKey: 'EnableSharing',\n            descriptionLangKey: 'EnableSharingCaption',\n            descriptionLangArgs: [new PeerTitle({peerId}).element],\n            button: {\n              langKey: 'SendRequest'\n            }\n          });\n        }\n\n        this.managers.appProfileManager.toggleNoForwards(peerId, false);\n      },\n      verify: async() => {\n        if(!this.peerId.isUser() || this.peerId === rootScope.myId || this.chat.isBot) return false;\n        const userFull = this.chat.fullPeer() as UserFull.userFull;\n        if(!userFull) return false;\n        return !!(userFull?.pFlags?.noforwards_my_enabled || userFull?.pFlags?.noforwards_peer_enabled);\n      }\n    }, {\n      icon: 'dollar_circle',\n      text: 'PaidMessages.ChargeFee',\n      onClick: () => this.onToggleFeeClick(true),\n      verify: () => this.verifyToggleFee(true)\n    }, {\n      icon: 'dollar_circle_x',\n      text: 'PaidMessages.RemoveFee',\n      onClick: () => this.onToggleFeeClick(false),\n      verify: () => this.verifyToggleFee(false)\n    }, {\n      icon: 'clipboard',\n      text: 'CompactDiffView',\n      onClick: wrapAsyncClickHandler(async() => {\n        if(!this.chat.popIfMoreThanOne()) {\n          await this.chat.setPeer({peerId: this.peerId});\n        }\n\n        setAppSettings('logsDiffView', true);\n\n        // awaiting this doesn't help\n        this.appSidebarRight.toggleSidebar(true, true);\n\n        if(liteMode.isAvailable('animations')) await pause(100);\n\n        this.appSidebarRight.createTab(AppAdminRecentActionsTab).open({\n          channelId: this.peerId.toChatId(),\n          isBroadcast: this.chat.isBroadcast\n        });\n      }),\n      verify: () => this.chat.type === ChatType.Logs\n    }, {\n      icon: 'flag',\n      text: 'ReportChat',\n      onClick: () => {\n        showPeerReport(this.peerId);\n      },\n      verify: this.verifyIfCanReportChat\n    }, {\n      icon: 'message_crossed',\n      text: 'ClearHistory',\n      onClick: () => {\n        clearHistoryWithConfirmation({peerId: this.peerId, managers: this.managers});\n      },\n      verify: this.verifyIfCanClearHistory\n    }, {\n      icon: 'delete',\n      danger: true,\n      text: 'Delete',\n      onClick: () => {\n        PopupElement.createPopup(\n          PopupDeleteDialog,\n          this.chat.monoforumThreadId || this.peerId,\n          undefined,\n          undefined,\n          this.chat.threadId,\n          this.chat.monoforumThreadId ? this.peerId : undefined\n        );\n      },\n      verify: this.verifyIfCanDeleteChat\n    }];\n\n    this.btnSearch = ButtonIcon('search');\n    this.attachClickEvent(this.btnSearch, (e) => {\n      this.chat.initSearch();\n    }, true);\n\n    this.btnLogFilters = ButtonIcon('filter');\n    this.attachClickEvent(this.btnLogFilters, () => {\n      this.onFilterActionsClick();\n    });\n  }\n\n  public addContact() {\n    if(!this.appSidebarRight.isTabExists(AppEditContactTab)) {\n      this.appSidebarRight.createTab(AppEditContactTab).open(this.peerId);\n\n      this.appSidebarRight.toggleSidebar(true);\n    }\n  }\n\n  /** Bot we manage — opens the same tab as the profile's edit button. */\n  public editBot() {\n    if(!this.appSidebarRight.isTabExists(AppEditBotTab)) {\n      this.appSidebarRight.createTab(AppEditBotTab).open(this.peerId);\n\n      this.appSidebarRight.toggleSidebar(true);\n    }\n  }\n\n  public async blockUser(showReport?: boolean, showDelete?: boolean, onConfirmed?: (promise: Promise<any>) => void) {\n    const peerId = this.peerId;\n    const checkboxes: PopupPeerCheckboxOptions[] = [\n      showReport && {\n        text: 'DeleteReportSpam',\n        checked: true\n      },\n      showDelete && {\n        text: 'DeleteThisChat',\n        checked: true\n      }\n    ];\n\n    const checked = await confirmationPopup({\n      peerId,\n      titleLangKey: 'BlockUser',\n      descriptionLangKey: 'AreYouSureBlockContact2',\n      descriptionLangArgs: [new PeerTitle({peerId}).element],\n      button: {\n        langKey: 'BlockUser',\n        isDanger: true\n      },\n      checkboxes: checkboxes.filter(Boolean)\n    });\n\n    const [reportSpam, deleteChat] = Array.isArray(checked) ? checked : [];\n\n    const promise = Promise.all([\n      reportSpam && this.managers.appMessagesManager.reportSpam(peerId),\n      deleteChat && this.managers.appMessagesManager.flushHistory({peerId, justClear: false, revoke: true}),\n      this.managers.appUsersManager.toggleBlock(peerId, true)\n    ]);\n\n    onConfirmed?.(promise);\n\n    await promise;\n\n    toastNew({langPackKey: 'UserBlocked'});\n  }\n\n  public attachClickEvent(el: HTMLElement, cb: (e: MouseEvent) => void, noBlur?: boolean) {\n    attachClickEvent(el, (e) => {\n      cancelEvent(e);\n      !noBlur && blurActiveElement();\n      cb(e);\n    }, {listenerSetter: this.listenerSetter});\n  }\n\n  private onCallClick(type: CallType) {\n    this.chat.appImManager.callUser(this.peerId.toUserId(), type);\n  }\n\n  private verifyToggleFee = async(requirePayment: boolean) => {\n    if(!this.chat.monoforumThreadId) return;\n\n    const {chat, dialog} = await namedPromises({\n      chat: this.chat.peer,\n      dialog: this.managers.monoforumDialogsStorage.getDialogByParent(this.peerId, this.chat.monoforumThreadId)\n    });\n\n    if(chat?._ !== 'channel' || !chat?.send_paid_messages_stars) return false;\n\n    return requirePayment ? !!dialog?.pFlags?.nopaid_messages_exception : !dialog?.pFlags?.nopaid_messages_exception;\n  };\n\n  private onToggleFeeClick = async(requirePayment: boolean) => {\n    const peerId = this.chat.monoforumThreadId;\n    const parentPeerId = this.chat.peerId;\n    if(!peerId || !parentPeerId) return;\n\n    try {\n      await openRemoveFeePopup({peerId, parentPeerId, requirePayment, managers: this.managers})\n    } catch{}\n  }\n\n  private onJoinGroupCallClick = () => {\n    this.chat.appImManager.joinGroupCall(this.peerId);\n  };\n\n  private onFilterActionsClick = wrapAsyncClickHandler(async() => {\n    const {default: LogFiltersPopup} = await import('./logFiltersPopup');\n\n    new LogFiltersPopup({\n      channelId: this.peerId.toChatId(),\n      isBroadcast: this.chat.isBroadcast,\n      committedFilters: this.chat.bubbles.committedLogsFilters,\n      HotReloadGuard: SolidJSHotReloadGuardProvider,\n      onFinish: ({committedFilters}) => {\n        this.chat.bubbles.setLogFilters(committedFilters);\n      }\n    }).show();\n  })\n\n  private get peerId() {\n    return this.chat.peerId;\n  }\n\n  public constructPeerHelpers() {\n    this.subtitle = document.createElement('div');\n    this.subtitle.classList.add('info');\n\n    // No plate here: `setupPinnedMessageForPeer` builds one per peer/thread and\n    // installs it in `revealPreparedPinnedMessage`. Creating one eagerly only\n    // produced a throwaway plate (rendered, listened, then destroyed on the\n    // first peer change) whose `isStatic` was decided before the chat had a type.\n\n    this.btnCall = ButtonIcon('phone');\n    this.btnGroupCall = ButtonIcon('videochat');\n    this.btnGroupCallMenu = ButtonMenuToggle({\n      listenerSetter: this.listenerSetter,\n      direction: 'bottom-left',\n      buttons: [{\n        icon: 'videochat',\n        text: 'Rtmp.Topbar.StartVideoChat',\n        onClick: this.onJoinGroupCallClick\n      }, {\n        icon: 'link',\n        text: 'Rtmp.Topbar.StreamWith',\n        onClick: () => {\n          PopupElement.createPopup(RtmpStartStreamPopup, {peerId: this.peerId}).show();\n        },\n        verify: () => IS_LIVE_STREAM_SUPPORTED\n      }],\n      icon: 'videochat'\n    });\n    this.attachClickEvent(this.btnCall, this.onCallClick.bind(this, 'voice'));\n    this.attachClickEvent(this.btnGroupCall, this.onJoinGroupCallClick);\n\n    this.listenerSetter.add(rootScope)('folder_unread', (folder) => {\n      if(!this.btnBackBadge || folder.id !== FOLDER_ID_ALL) {\n        return;\n      }\n\n      const size = folder.unreadUnmutedPeerIds.size;\n      setBadgeContent(this.btnBackBadge, size ? '' + formatNumber(size, 1) : '');\n      // this.btnBack.classList.remove('tgico-left', 'tgico-previous');\n      // this.btnBack.classList.add(size ? 'tgico-previous' : 'tgico-left');\n    });\n\n    this.listenerSetter.add(rootScope)('chat_update', (chatId) => {\n      if(this.peerId === chatId.toPeerId(true)) {\n        const chat = this.chat.peer as Channel/*  | Chat */;\n        if(!chat.pFlags.broadcast) {\n          return;\n        }\n\n        this.verifyButtons();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('peer_full_update', (peerId) => {\n      if(this.peerId === peerId) {\n        this.verifyButtons();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('chat_requests', ({chatId, recentRequesters, requestsPending}) => {\n      if(this.peerId !== chatId.toPeerId(true)) {\n        return;\n      }\n\n      const middleware = this.chat.bubbles.getMiddleware();\n      this.plates.requests.set(\n        this.peerId,\n        recentRequesters.map((userId) => userId.toPeerId(false)),\n        requestsPending\n      ).then((callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n    });\n\n    this.listenerSetter.add(rootScope)('peer_settings', async({peerId, settings}) => {\n      if(this.peerId !== peerId) {\n        return;\n      }\n\n      const callback = this.plates.actions.set(peerId, settings);\n      callback();\n    });\n\n    this.listenerSetter.add(rootScope)('chat_automation_update', (connectedBot) => {\n      this.plates.automation.handleConnectedBotUpdate(connectedBot?.bot_id as UserId);\n    });\n\n    this.listenerSetter.add(rootScope)('right_sidebar_toggle', () => {\n      this.setFloating(); // * to calculate sponsored height\n    });\n\n    this.chat.addEventListener('setPeer', (mid, isTopMessage) => {\n      const middleware = this.chat.bubbles.getMiddleware();\n      if(!middleware() || !this.pinnedMessage) return;\n\n      this.pinnedMessage.setUserHidden(!!this.chat.appState.hiddenPinnedMessages[getPinnedMessagesKey(this.chat.peerId, this.chat.threadId)]);\n\n      if(isTopMessage) {\n        this.pinnedMessage.unsetScrollDownListener();\n        this.pinnedMessage.testMid(mid, 0); // * because slider will not let get bubble by document.elementFromPoint\n      } else if(!this.pinnedMessage.isLocked()) {\n        this.pinnedMessage.handleFollowingPinnedMessage();\n        this.pinnedMessage.testMid(mid);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('peer_pinned_messages', ({peerId, mids}) => {\n      if(this.chat.type !== ChatType.Pinned || peerId !== this.peerId) {\n        return;\n      }\n\n      if(mids) {\n        this.setTitle();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_update', async({dialogs}) => {\n      if(!this.chat.isMonoforum || !this.chat.monoforumThreadId) return;\n\n      const found = dialogs.find(dialog => dialog.parentPeerId === this.chat.peerId && dialog.peerId === this.chat.monoforumThreadId);\n      if(!found) return;\n\n      const callback = await (await this.plates.removeFee.setPeerId(this.chat.peerId)).result;\n      callback();\n    });\n\n    this.listenerSetter.add(rootScope)('auto_delete_period_update', ({peerId, period}) => {\n      if(peerId !== this.peerId || this.chat.type !== ChatType.Chat) return;\n      this.avatar.setAutoDeletePeriod(period);\n    });\n\n    return this;\n  }\n\n  public openPinned(byCurrent: boolean) {\n    const currentMid = byCurrent ? +this.pinnedMessage.container.dataset.mid : 0;\n    this.chat.appImManager.setInnerPeer({\n      peerId: this.peerId,\n      // the pinned list is per-topic in a forum — without the thread the tab\n      // would list every pin of the forum instead of this topic's\n      threadId: this.chat.threadId,\n      lastMsgId: currentMid || 0,\n      type: ChatType.Pinned\n    });\n  }\n\n  public onJoinClick = async(button: HTMLElement) => {\n    const middleware = this.chat.bubbles.getMiddleware();\n    button.setAttribute('disabled', 'true');\n\n    joinChat({\n      peerId: this.peerId,\n      managers: this.managers,\n      appImManager: this.chat.appImManager\n    }).finally(() => {\n      if(!middleware()) {\n        return;\n      }\n\n      button.removeAttribute('disabled');\n    });\n  };\n\n  private canClickOnDirectMessagesBtn = true;\n  private onDirectMessagesClick = async() => {\n    if(!this.canClickOnDirectMessagesBtn || !this.peerId.isAnyChat()) return;\n    this.canClickOnDirectMessagesBtn = false;\n    pause(200).then(() => this.canClickOnDirectMessagesBtn = true);\n\n    const chat = this.chat.peer;\n    if(chat._ !== 'channel') return;\n\n    appImManager.setInnerPeer({\n      peerId: chat.linked_monoforum_id.toPeerId(true)\n    });\n  };\n\n  private onMuteClick = () => {\n    PopupElement.createPopup(PopupMute, this.peerId);\n  };\n\n  private onUnmuteClick = () => {\n    this.managers.appMessagesManager.togglePeerMute({peerId: this.peerId, threadId: this.chat.threadId});\n  };\n\n  private onResize = () => {\n    this.setFloating();\n  };\n\n  private onChangeScreen = (from: ScreenSize, to: ScreenSize) => {\n    this.onResize();\n  };\n\n  public destroy() {\n    // this.chat.log.error('Topbar destroying');\n    this.listenerSetter.removeAll();\n\n    this.status?.destroy();\n    this.titleMiddlewareHelper?.destroy();\n    this.avatarMiddlewareHelper?.destroy();\n    this.pinnedMessage?.destroy();\n    this.plates?.destroy();\n\n    delete this.pinnedMessage;\n    delete this.plates;\n  }\n\n  public cleanup() {\n    if(!this.chat.peerId) {\n      this.container.classList.add('hide');\n    }\n  }\n\n  private appendPinnedMessage(pinnedMessage: ChatPinnedMessageController) {\n    const container = pinnedMessage.container;\n    if(this.pinnedMessage && this.pinnedMessage !== pinnedMessage) {\n      this.pinnedMessage.container.replaceWith(container);\n    } else {\n      this.floatingPlatesWrapper.prepend(container);\n    }\n  }\n\n  private pinnedMessageSetupForKey: string | undefined;\n  /**\n   * Plate swap deferred from `setupPinnedMessageForPeer` until the\n   * bubbles-mount moment inside `bubbles.setPeer`. `kind='install'`\n   * carries a detached new plate and (optionally) a `prepareInitialPromise`\n   * that resolves once the new plate's content is rendered — awaited in\n   * `finishPeerChange`'s `Promise.all`, so by the time\n   * `revealPreparedPinnedMessage` runs the plate and bubbles paint together. `kind='destroy'` means the new peer has no plate,\n   * but the old one must stay visible until bubbles swap.\n   */\n  private pendingPinnedSetup:\n    | {kind: 'install', newPlate: ChatPinnedMessageController, prepareInitialPromise?: Promise<void>}\n    | {kind: 'destroy'}\n    | null = null;\n\n  /**\n   * Prepare the pinned-message plate for the chat's current peer. Called\n   * from `finishPeerChange` alongside the other plates (after\n   * `onChangePeer` has updated `messagesStorageKey` / `this.type` /\n   * etc), so peer-derived lookups inside `prepareInitial` already point\n   * at the new peer.\n   *\n   * Does NOT touch the DOM — the change is staged into\n   * `pendingPinnedSetup` and applied atomically by\n   * `revealPreparedPinnedMessage` right before bubbles mount, so plate\n   * and bubbles paint in the same frame.\n   *\n   * Idempotent per peer + thread. Returns the `prepareInitial` promise\n   * (if any) so callers can await content readiness in parallel with the\n   * other `finishPeerChange` promises.\n   */\n  public setupPinnedMessageForPeer(): Promise<void> | undefined {\n    const peerId = this.chat.peerId;\n    const threadId = this.chat.threadId;\n    // The pinned list is per-topic in a forum, and on mobile the same chat\n    // instance is reused across peer changes — keying on peerId alone would\n    // keep the previous topic's plate on a topic switch.\n    const setupKey = peerId + (threadId ? '_' + threadId : '');\n    if(this.pinnedMessageSetupForKey === setupKey) {\n      return this.pendingPinnedSetup?.kind === 'install' ?\n        this.pendingPinnedSetup.prepareInitialPromise :\n        undefined;\n    }\n    this.pinnedMessageSetupForKey = setupKey;\n\n    // Drop an orphaned pending plate from an even earlier peer change.\n    if(this.pendingPinnedSetup?.kind === 'install') {\n      this.pendingPinnedSetup.newPlate.destroy();\n    }\n    this.pendingPinnedSetup = null;\n\n    const isPinnedMessagesNeeded = this.chat.isPinnedMessagesNeeded();\n    const wantsPlate = isPinnedMessagesNeeded || this.chat.type === ChatType.Discussion;\n    if(!wantsPlate) {\n      if(this.pinnedMessage) {\n        this.pendingPinnedSetup = {kind: 'destroy'};\n      }\n      return;\n    }\n\n    const newPlate = createChatPinnedMessage(this, this.chat, this.managers);\n    let prepareInitialPromise: Promise<void> | undefined;\n\n    if(this.chat.type === ChatType.Discussion) {\n      newPlate.setStaticMessage(this.chat.threadId);\n    } else {\n      newPlate.setUserHidden(!!this.chat.appState.hiddenPinnedMessages[getPinnedMessagesKey(peerId, threadId)]);\n      const savedPosition = this.chat.appImManager.getChatSavedPosition(this.chat);\n      const cachedFull = untrack(() => this.chat.fullPeer());\n      // Prefer the full saved plate state (mid + index + count) so the\n      // plate restores exactly the view the user left on — including the\n      // pin-list border indicator and counter. Fall back to fullPeer's\n      // `pinned_msg_id`, which is always the newest pin (index 0).\n      // `pinned_msg_id` is peer-scoped. In a forum topic the pinned list is\n      // per-topic (the plate fetches it with `threadId`), so seeding from it\n      // would paint a foreign pin — or any pin at all in a topic that has\n      // none — until the thread-scoped fetch resolves and hides it again.\n      const pinnedMessageId = !threadId && cachedFull && 'pinned_msg_id' in cachedFull ?\n        cachedFull.pinned_msg_id :\n        undefined;\n      const hint = savedPosition?.pinnedMessages ||\n        (pinnedMessageId ? {mid: pinnedMessageId, index: 0, count: 1} : undefined);\n      if(hint) {\n        prepareInitialPromise = newPlate.prepareInitial(hint);\n      }\n    }\n\n    this.pendingPinnedSetup = {kind: 'install', newPlate, prepareInitialPromise};\n    return prepareInitialPromise;\n  }\n\n  /**\n   * Apply the deferred plate change synchronously. Called from the\n   * `finishPeerChange` sync callback, *after* `Promise.all(promises)`\n   * already awaited `prepareInitialPromise` — so the new plate's content\n   * is in the DOM by now. The install + reveal lands in the same task as\n   * the surrounding bubbles work, painting together.\n   */\n  public revealPreparedPinnedMessage() {\n    const pending = this.pendingPinnedSetup;\n    if(!pending) {\n      this.pinnedMessage?.revealPrepared();\n      return;\n    }\n    this.pendingPinnedSetup = null;\n\n    const old = this.pinnedMessage;\n    if(pending.kind === 'install') {\n      this.appendPinnedMessage(pending.newPlate);\n      this.pinnedMessage = pending.newPlate;\n      pending.newPlate.revealPrepared();\n    } else {\n      this.pinnedMessage = undefined;\n    }\n    old?.destroy();\n    this.setFloating();\n  }\n\n  public async finishPeerChange(options: Parameters<Chat['finishPeerChange']>[0]) {\n    const {peerId, threadId, monoforumThreadId} = this.chat;\n    const {middleware} = options;\n\n    let newAvatar: ChatTopbar['avatar'], newAvatarMiddlewareHelper: ChatTopbar['avatarMiddlewareHelper'];\n    const isSaved = this.chat.type === ChatType.Saved;\n    const needArrowBack = this.chat.type === ChatType.Search;\n    if([ChatType.Chat, ChatType.Static, ChatType.Logs].includes(this.chat.type) || isSaved) {\n      const usePeerId = monoforumThreadId ||(isSaved ? threadId : peerId);\n      const useThreadId = isSaved ? undefined : threadId;\n      const avatar = this.avatar;\n\n\n      if(\n        !avatar ||\n        avatar.node.dataset.peerId.toPeerId() !== usePeerId ||\n        avatar.node.dataset.threadId !== (useThreadId ? '' + useThreadId : undefined) ||\n        peerId === rootScope.myId\n      ) {\n        newAvatar = avatarNew({\n          middleware: (newAvatarMiddlewareHelper = getMiddleware()).get(),\n          isDialog: true,\n          size: 40,\n          peerId: usePeerId,\n          threadId: useThreadId,\n          wrapOptions: {customEmojiSize: makeMediaSize(30, 30)},\n          withStories: true,\n          withVideoAvatar: true,\n          meAsNotes: isSaved\n        });\n        newAvatar.node.classList.add('person-avatar');\n      } else {\n        newAvatar = this.avatar;\n      }\n    }\n\n    this.status?.destroy();\n    const status = this.status = this.createStatus();\n\n    const promises = [\n      this.managers.appPeersManager.isBroadcast(peerId),\n      this.managers.appPeersManager.isAnyChat(peerId),\n      peerId.isAnyChat() ? this.chat.peer : undefined,\n      newAvatar?.readyThumbPromise,\n      this.setTitleManual(),\n      status?.prepare(true),\n      modifyAckedPromise(this.plates.requests.setPeerId(peerId)),\n      modifyAckedPromise(this.plates.actions.setPeerId(peerId)),\n      modifyAckedPromise(this.plates.removeFee.setPeerId(peerId)),\n      this.chat.type === ChatType.Chat ? await modifyAckedPromise(this.chat.getAutoDeletePeriod()) : undefined,\n      this.setupPinnedMessageForPeer()\n    ] as const;\n\n    const [\n      isBroadcast,\n      isAnyChat,\n      chat,\n      _,\n      setTitleCallback,\n      setStatusCallback,\n      setRequestsCallback,\n      setActionsCallback,\n      setChatRemoveFeeCallback,\n      autoDeletePeriod,\n      _pinnedReady\n    ] = await Promise.all(promises);\n\n    if(!middleware() && newAvatarMiddlewareHelper) {\n      newAvatarMiddlewareHelper.destroy();\n    }\n\n    return () => {\n      const canHaveSomeButtons = !(this.chat.type === ChatType.Pinned || this.chat.type === ChatType.Scheduled || this.chat.type === ChatType.Static || this.chat.type === ChatType.Logs);\n      const canHaveSearch = canHaveSomeButtons || this.chat.type === ChatType.Logs;\n\n      if(this.btnSearch) {\n        this.btnSearch.classList.toggle('hide', !canHaveSearch);\n      }\n\n      if(this.btnLogFilters) {\n        this.btnLogFilters.classList.toggle('hide', this.chat.type !== ChatType.Logs);\n      }\n\n      if(this.avatar !== newAvatar) {\n        if(newAvatar) {\n          this.person.prepend(newAvatar.node);\n        }\n\n        if(this.avatar) {\n          this.avatarMiddlewareHelper.destroy();\n          this.avatar.node.remove();\n        }\n\n        this.avatar = newAvatar;\n        this.avatarMiddlewareHelper = newAvatarMiddlewareHelper;\n        this.container.classList.toggle('has-avatar', !!newAvatar);\n      }\n\n      callbackify(autoDeletePeriod?.result, (value) => {\n        this.avatar?.setAutoDeletePeriod(value);\n      });\n\n      this.verifyButtons();\n\n      const canHaveMore = canHaveSomeButtons || this.chat.type === ChatType.Logs;\n\n      if(this.btnMore) {\n        this.btnMore.classList.toggle('hide', !canHaveMore);\n      }\n\n      this.revealPreparedPinnedMessage();\n      setTitleCallback();\n      setStatusCallback?.();\n\n      this.subtitle.classList.toggle('hide', !setStatusCallback);\n\n      this.container.classList.remove('hide');\n\n      if(setRequestsCallback.result instanceof Promise) {\n        this.plates.requests.unset(peerId);\n      }\n\n      if(setActionsCallback.result instanceof Promise) {\n        this.plates.actions.unset(peerId);\n      }\n\n      if(setChatRemoveFeeCallback.result instanceof Promise) {\n        this.plates.removeFee.hide();\n      }\n\n      this.plates.live?.setPeerId(peerId);\n      this.plates.groupCall?.setPeerId(peerId);\n      this.plates.translation.setPeerId(peerId);\n      this.plates.sponsored.setPeerId(peerId);\n\n      callbackify(setRequestsCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      callbackify(setActionsCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      callbackify(setChatRemoveFeeCallback.result, (callback) => {\n        if(!middleware()) {\n          return;\n        }\n\n        callback();\n      });\n\n      this.container.classList.toggle('show-back-button', needArrowBack);\n    };\n  }\n\n  public async setTitleManual(count?: number) {\n    const {peerId, threadId, monoforumThreadId} = this.chat;\n    let titleEl: HTMLElement, icons: Element[];\n    const oldMiddlewareHelper = this.titleMiddlewareHelper;\n    oldMiddlewareHelper?.destroy();\n    const middlewareHelper = this.titleMiddlewareHelper = getMiddleware();\n    const middleware = middlewareHelper.get();\n    if(this.chat.type === ChatType.Pinned) {\n      if(count === undefined) titleEl = i18n('Loading');\n      else titleEl = i18n('PinnedMessagesCount', [count]);\n\n      if(count === undefined) {\n        // Not `messages.getSearchCounters`: for some peers the server answers it\n        // with an `inexact` count that undercounts badly — in Saved Messages it\n        // returns 5 while 17 messages are pinned (an exact answer there needs\n        // `saved_peer_id`, which the peer-wide pinned tab has no business\n        // sending). `getPinnedMessage` reads the count off the very\n        // `inputMessagesFilterPinned` search this tab's list is built from, so\n        // the title can't disagree with what's rendered under it — the same\n        // source the official clients use for this counter.\n        this.managers.appMessagesManager.getPinnedMessage(peerId, this.chat.threadId).then(({count}) => {\n          if(!middleware()) return;\n          this.setTitle(count);\n\n          // ! костыль х2, это нужно делать в другом месте\n          if(!count) {\n            this.chat.appImManager.setPeer(); // * close tab\n\n            // ! костыль, это скроет закреплённые сообщения сразу, вместо того, чтобы ждать пока анимация перехода закончится\n            const originalChat = this.chat.appImManager.chat;\n            if(originalChat.topbar.pinnedMessage) {\n              originalChat.topbar.pinnedMessage.setHidden(true);\n            }\n          }\n        });\n      }\n    } else if(this.chat.type === ChatType.Scheduled) {\n      titleEl = i18n(peerId === rootScope.myId ? 'Reminders' : 'ScheduledMessages');\n    } else if(this.chat.type === ChatType.Discussion) {\n      const el = this.messagesCounter({\n        middleware,\n        key: 'Chat.Title.Comments',\n        minusFirst: this.chat.isForum\n      });\n      if(count === undefined && middleware()) {\n        const historyStorage = this.chat.getHistoryStorage();\n        el.compareAndUpdate(typeof(historyStorage.count) !== 'number' ?\n          {key: 'Loading', args: undefined} :\n          {args: [historyStorage.count - (this.chat.isForum ? 1 : 0)]}\n        );\n      }\n\n      titleEl = el.element;\n    } else if(this.chat.type === ChatType.Chat || this.chat.type === ChatType.Saved || this.chat.type === ChatType.Static || this.chat.type === ChatType.Logs) {\n      const usePeerId = monoforumThreadId || (this.chat.type === ChatType.Saved ? threadId : peerId);\n\n      [titleEl/* , icons */] = await Promise.all([\n        wrapPeerTitle({\n          peerId: usePeerId,\n          dialog: true,\n          withIcons: !threadId,\n          threadId: threadId,\n          wrapOptions: {middleware},\n          meAsNotes: this.chat.type === ChatType.Saved\n        })\n        // generateTitleIcons(peerId)\n      ]);\n    }\n\n    // Always a callback, never `undefined` — `setPeerCallbacks` and `setTitle`\n    // both call the result unconditionally, so bailing out here used to risk a\n    // 'setTitleCallback is not a function' in the middle of a peer change.\n    return () => {\n      // A newer `setTitleManual` destroyed our helper, so it owns the title now.\n      // Without this the pinned tab could end up stuck on 'Loading': the count\n      // resolves from cache before the caller gets around to invoking this\n      // callback, and the stale 'Loading' element would overwrite the count\n      // that the inner `setTitle(count)` already painted.\n      if(!middleware()) {\n        return;\n      }\n\n      replaceContent(this.title, titleEl);\n      // if(icons) {\n      //   this.title.append(...icons);\n      // }\n    };\n  }\n\n  public setTitle(count?: number) {\n    this.setTitleManual(count).then((setTitleCallback) => setTitleCallback());\n  }\n\n  public setFloating = () => {\n    // Preview omits `floatingPlatesWrapper` from the live DOM (see `construct`). The plate\n    // controllers still exist for the rest of the code, and a peer with a pinned message\n    // would mark the pinnedMessage plate visible — its hardcoded `height: 48` + TOPBAR_GAP\n    // would leak into `--pinned-floating-height` / `pinnedFloatingHeightPx` and inflate\n    // `bubbles-padding-top` from 56 to 112 above the first message. Bail early.\n    if(this.chat.isPreview) return;\n    const containers = [\n      this.pinnedMessage,\n      ...(this.plates?.all || [])\n    ].filter(Boolean);\n    const TOPBAR_GAP = 8;\n    const PLATE_DIVIDER = 1;\n\n    const visible = containers.filter((container) => container.isVisible());\n    const count = visible.length;\n\n    // Un-hide the wrapper BEFORE measuring any 'auto' plate height below. The\n    // wrapper is `display: none` while no plate is visible (count === 0), and an\n    // ancestor's `display: none` zeroes its descendants' offsetHeight — so the\n    // sponsored plate (the only `height: 'auto'` one), exactly when it is the\n    // plate that flips the count 0 → 1, would otherwise be measured at 0 and\n    // never reserve its padding-top, leaving it overlapping the chat content.\n    this.floatingPlatesWrapper.classList.toggle('hide', count === 0);\n\n    let platesHeight = 0;\n    for(const container of visible) {\n      platesHeight += container.height === 'auto' ? container.container.offsetHeight : container.height;\n    }\n\n    const floatingHeight = count > 0 ? platesHeight + Math.max(0, count - 1) * PLATE_DIVIDER + TOPBAR_GAP : 0;\n    const reservedFloatingHeight = this.chat.container.classList.contains('is-search-active') ? 0 : floatingHeight;\n    this.container.dataset.floating = '' + count;\n    this.chat.container.style.setProperty(\n      '--pinned-floating-height',\n      `calc(${reservedFloatingHeight}px + var(--topbar-floating-call-height) + var(--topbar-floating-audio-height))`\n    );\n    this.chat.updatePinnedFloatingHeight(reservedFloatingHeight);\n  };\n\n  private messagesCounter({\n    middleware,\n    key,\n    minusFirst,\n    displayLoading\n  }: {\n    middleware: Middleware,\n    key: LangPackKey,\n    minusFirst?: boolean,\n    displayLoading?: boolean\n  }) {\n    const el = new I18n.IntlElement(displayLoading ? {\n      key: 'Loading'\n    } : {\n      key,\n      args: [1]\n    });\n\n    createRoot((dispose) => {\n      middleware.onDestroy(dispose);\n\n      createEffect(on(\n        () => [this.chat.historyStorage.count, this.chat.historyStorage.wasFetched] as const,\n        ([count]) => {\n          el.compareAndUpdate({key, args: [count - (minusFirst ? 1 : 0)]});\n        },\n        {defer: displayLoading ? !this.chat.historyStorage.wasFetched : true}\n      ));\n    });\n\n    return el;\n  }\n\n  private createStatus() {\n    if(!this.subtitle || (this.chat.type !== ChatType.Chat && this.chat.type !== ChatType.Saved)) return;\n    const middlewareHelper = getMiddleware();\n    const middleware = middlewareHelper.get();\n    const listenerSetter = new ListenerSetter();\n\n    let prepare: (needClear: boolean) => Promise<() => void>;\n    if(this.chat.type === ChatType.Saved || this.peerId === rootScope.myId) {\n      const el = this.messagesCounter({\n        middleware,\n        key: 'messages',\n        displayLoading: this.peerId === rootScope.myId\n      });\n\n      prepare = async() => {\n        const historyStorage = this.chat.getHistoryStorage();\n        el.compareAndUpdate({args: [historyStorage.count]});\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else if(this.chat.threadId) {\n      prepare = async() => {\n        const title = await wrapPeerTitle({peerId: this.peerId, dialog: true});\n        const span = i18n('TopicProfileStatus', [title]);\n\n        return () => replaceContent(this.subtitle, span);\n      };\n    } else if(this.chat.isMonoforum && this.chat.canManageDirectMessages && !this.chat.monoforumThreadId) {\n      listenerSetter.add(rootScope)('monoforum_dialogs_update', ({dialogs}) => {\n        if(!dialogs.find(dialog => dialog.parentPeerId === this.chat.peerId)) return;\n        setAuto();\n      });\n\n      listenerSetter.add(rootScope)('monoforum_dialogs_drop', () => {\n        setAuto();\n      });\n\n      prepare = async() => {\n        const ackedResult = await this.managers.acknowledged.monoforumDialogsStorage.getDialogs({parentPeerId: this.peerId, limit: 1});\n        const initialCount = ackedResult.cached ? (await ackedResult.result).count || 0 : '~';\n\n        const el = new I18n.IntlElement({\n          key: 'ChannelDirectMessages.ThreadsCount',\n          args: [initialCount]\n        });\n\n        if(!ackedResult.cached) ackedResult.result?.then(({count}) => el.compareAndUpdate({\n          key: 'ChannelDirectMessages.ThreadsCount',\n          args: [count]\n        }));\n\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else if(this.chat.isMonoforum) {\n      listenerSetter.add(rootScope)('history_multiappend', (message) => {\n        if(message.peerId !== this.chat.peerId) return;\n        if(this.chat.monoforumThreadId && getPeerId(message?.saved_peer_id) !== this.chat.monoforumThreadId) return;\n        setAuto();\n      });\n\n      listenerSetter.add(rootScope)('history_delete', ({peerId}) => {\n        if(peerId !== this.chat.peerId) return;\n        setAuto();\n      });\n\n      prepare = async() => {\n        const ackedResult = await this.managers.acknowledged.appMessagesManager.getHistory({\n          ...this.chat.requestHistoryOptionsPart,\n          fetchIfWasNotFetched: true,\n          limit: 1\n        });\n\n        const initialCount = ackedResult.cached ? (await ackedResult.result).count || 0 : '~';\n\n        const el = new I18n.IntlElement({\n          key: 'ChannelDirectMessages.MessagesCount',\n          args: [initialCount]\n        });\n\n        if(!ackedResult.cached) ackedResult.result?.then(({count}) => el.compareAndUpdate({\n          key: 'ChannelDirectMessages.MessagesCount',\n          args: [count]\n        }));\n\n        return () => replaceContent(this.subtitle, el.element);\n      };\n    } else {\n      const peerId = this.peerId;\n\n      listenerSetter.add(rootScope)('peer_typings', ({peerId: _peerId}) => {\n        if(peerId === _peerId) {\n          setAuto();\n        }\n      });\n\n      listenerSetter.add(rootScope)('user_update', (userId) => {\n        if(peerId === userId.toPeerId()) {\n          setAuto();\n        }\n      });\n\n      const interval = window.setInterval(() => setAuto(), 60e3);\n\n      middleware.onDestroy(() => {\n        clearInterval(interval);\n      });\n\n      prepare = (needClear) => {\n        return this.chat.appImManager.setPeerStatus({\n          peerId,\n          element: this.subtitle,\n          needClear,\n          useWhitespace: false,\n          middleware\n        });\n      };\n    }\n\n    middleware.onDestroy(() => {\n      listenerSetter.removeAll();\n    });\n\n    const setAuto = () => {\n      prepare(false).then((callback) => middleware() && callback?.());\n    };\n\n    return {\n      prepare,\n      destroy: () => middlewareHelper.destroy()\n    };\n  }\n\n  private async createAutoDeleteSubmenu() {\n    const options = getDefaultOptions({\n      offLabel: () => i18n('Never')\n    });\n\n    const menu = await ButtonMenu({\n      buttons: [\n        ...options.map((option): ButtonMenuItemOptionsVerifiable => ({\n          iconElement: option.value === 0 ? Icon('auto_delete_circle_off') : createAutoDeleteIcon(option.value),\n          regularText: option.label(),\n          onClick: () => {\n            this.managers.appPrivacyManager.setAutoDeletePeriodFor(this.peerId, option.value);\n          }\n        })),\n        {\n          icon: 'tools',\n          text: 'Other',\n          onClick: () => this.chat.openAutoDeleteMessagesCustomTimePopup()\n        }\n      ]\n    });\n\n    return menu;\n  }\n}\n","export default function stringMiddleOverflow(str: string, maxLength: number) {\n  if(str.length <= maxLength) {\n    return str;\n  }\n\n  const ellipsis = '...';\n  const budget = Math.max(0, maxLength - ellipsis.length);\n  const headLength = budget - (budget >> 1); // ceil(budget / 2)\n  const tailLength = budget >> 1; // floor(budget / 2)\n  return str.slice(0, headLength) + ellipsis + (tailLength ? str.slice(-tailLength) : '');\n}\n","/**\n * Schedules a side effect to run in a microtask,\n * outside of the current reactive batch/effect.\n */\nexport default function deferSideEffect(callback: () => void) {\n  queueMicrotask(callback);\n}\n","import type {ReactionsContext} from '@appManagers/appReactionsManager';\nimport type {RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {createEffect, createSignal, onCleanup, JSX, createMemo, onMount, on, untrack, batch, Accessor} from 'solid-js';\nimport InputSearch from '@components/inputSearch';\nimport {ButtonIconTsx} from '@components/buttonIconTsx';\nimport classNames from '@helpers/string/classNames';\nimport PopupElement from '@components/popups';\nimport showDatePickerPopup from '@components/popups/datePicker';\nimport rootScope, {BroadcastEvents} from '@lib/rootScope';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {ChannelsChannelParticipants, Message, MessageReactions, Reaction, ReactionCount, SavedReactionTag} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport placeCaretAtEnd from '@helpers/dom/placeCaretAtEnd';\nimport {createLoadableList} from '@components/sidebarRight/tabs/statistics';\nimport {Middleware, getMiddleware} from '@helpers/middleware';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport whichChild from '@helpers/dom/whichChild';\nimport appImManager from '@lib/appImManager';\nimport attachListNavigation from '@helpers/dom/attachListNavigation';\nimport blurActiveElement from '@helpers/dom/blurActiveElement';\nimport I18n, {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport stringMiddleOverflow from '@helpers/string/stringMiddleOverflow';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport getTextWidth from '@helpers/canvas/getTextWidth';\nimport {FontFull} from '@config/font';\nimport RowTsx from '@components/rowTsx';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport {avatarNew} from '@components/avatarNew';\nimport getPeerActiveUsernames from '@appManagers/utils/peers/getPeerActiveUsernames';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport PeerTitle from '@components/peerTitle';\nimport ReactionsElement from '@components/chat/reactions';\nimport ReactionElement, {ReactionLayoutType} from '@components/chat/reaction';\nimport Scrollable from '@components/scrollable2';\nimport reactionsEqual from '@appManagers/utils/reactions/reactionsEqual';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport Icon from '@components/icon';\nimport PopupPremium from '@components/popups/premium';\nimport usePremium from '@stores/premium';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport Animated from '@helpers/solid/animations';\nimport Chat from '@components/chat/chat';\nimport {ChatType} from './chatType';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport getHistoryStorageKey, {getHistoryStorageType} from '@appManagers/utils/messages/getHistoryStorageKey';\nimport {ScreenSize, useMediaSizes} from '@helpers/mediaSizes';\nimport ButtonCorner from '@components/buttonCorner';\nimport deferSideEffect from '@helpers/solid/deferSideEffect';\n\ntype SearchType = RequestHistoryOptions['hashtagType'];\nconst SEARCH_TYPES: SearchType[] = ['this', 'my', 'public'];\nconst DEFAULT_SEARCH_TYPE: SearchType = undefined;\n\ntype LoadOptions = {\n  middleware: Middleware,\n  peerId: PeerId,\n  threadId: number,\n  monoforumThreadId: PeerId,\n  query: string,\n  fromPeerId?: PeerId,\n  reaction?: Reaction,\n  searchType?: SearchType\n};\n\nconst renderHistoryResult = ({middleware, peerId, fromSavedDialog, messages, query, searchType/* , fromPeerId */}: LoadOptions & {fromSavedDialog: boolean, messages: (Message.message | Message.messageService)[]}) => {\n  const promises = messages.map(async(message) => {\n    const fromPeerId = message.fromId;\n    const loadPromises: Promise<any>[] = [];\n    const {dom} = appDialogsManager.addDialogAndSetLastMessage({\n      peerId: fromSavedDialog ? rootScope.myId : (fromPeerId || peerId),\n      container: false,\n      avatarSize: 'abitbigger',\n      meAsSaved: searchType === 'my',\n      message,\n      query,\n      // noIcons: this.noIcons,\n      wrapOptions: {\n        middleware\n      },\n      loadPromises,\n      threadId: fromSavedDialog ? ((message as Message.message).saved_peer_id ? getPeerId((message as Message.message).saved_peer_id) : rootScope.myId) : undefined,\n      autonomous: true\n    });\n\n    await Promise.all(loadPromises);\n    return dom.containerEl;\n  });\n\n  return Promise.all(promises);\n};\n\nconst createSearchLoader = (options: LoadOptions) => {\n  const {middleware, peerId, threadId, query, fromPeerId, reaction, searchType, monoforumThreadId} = options;\n  const fromSavedDialog = !!(peerId === rootScope.myId && threadId);\n  let lastMessage: Message.message | Message.messageService, loading = false, nextRate: number;\n  const loadMore = async() => {\n    if(loading) {\n      return;\n    }\n    loading = true;\n\n    const offsetId = lastMessage?.mid || 0;\n    const offsetPeerId = lastMessage?.peerId || NULL_PEER_ID;\n    const requestHistoryOptions: RequestHistoryOptions = {\n      peerId: searchType === 'this' || !searchType ? peerId : NULL_PEER_ID,\n      threadId: searchType === 'this' || !searchType ? threadId : undefined,\n      monoforumThreadId,\n      query,\n      inputFilter: {_: 'inputMessagesFilterEmpty'},\n      offsetId,\n      offsetPeerId,\n      limit: 30,\n      fromPeerId,\n      savedReaction: reaction ? [reaction as Reaction.reactionEmoji] : undefined,\n      nextRate,\n      isPublicHashtag: searchType === 'public',\n      isCacheableSearch: !!searchType,\n      hashtagType: searchType\n    };\n\n    const key = getHistoryStorageKey({type: getHistoryStorageType(requestHistoryOptions), ...requestHistoryOptions});\n    rootScope.managers.appMessagesManager.toggleHistoryKeySubscription(key, true);\n    onCleanup(() => {\n      rootScope.managers.appMessagesManager.toggleHistoryKeySubscription(key, false);\n    });\n\n    const result = await rootScope.managers.appMessagesManager.getHistory(requestHistoryOptions);\n    if(!middleware()) {\n      return;\n    }\n\n    let messages: Message.message[];\n    if(result.messages) {\n      messages = result.messages as Message.message[];\n      nextRate = result.nextRate;\n    } else {\n      messages = result.history.map((mid) => apiManagerProxy.getMessageByPeer(peerId, mid)) as Message.message[];\n    }\n\n    // * a mid can have no message behind it (deleted, or a synthetic bound), skip such holes\n    messages = messages.filter(Boolean);\n\n    const rendered = await renderHistoryResult({...options, fromSavedDialog, messages});\n    if(!middleware()) {\n      return;\n    }\n\n    setF((value) => {\n      value.count = result.count;\n      value.values.push(...messages);\n      lastMessage = messages[messages.length - 1];\n      if(result.isEnd.top) {\n        value.loadMore = undefined;\n      }\n\n      value.rendered.push(...rendered);\n      return value;\n    });\n    loading = false;\n  };\n\n  const [f, setF] = createLoadableList<Message.message | Message.messageService>({loadMore});\n  return f;\n};\n\nconst createParticipantsLoader = (options: LoadOptions) => {\n  const {middleware, peerId, query} = options;\n  let loading = false, offset = 0;\n  const loadMore = async() => {\n    if(loading) {\n      return;\n    }\n    loading = true;\n\n    const result = await rootScope.managers.appProfileManager.getParticipants({\n      id: peerId.toChatId(),\n      filter: {_: 'channelParticipantsSearch', q: query},\n      limit: 30,\n      offset,\n      forMessagesSearch: true\n    });\n    if(!middleware()) {\n      return;\n    }\n\n    const peerIds = result.participants.map(getParticipantPeerId);\n    const promises = peerIds.map(async(peerId) => {\n      const title = await wrapPeerTitle({peerId});\n      const peer = apiManagerProxy.getPeer(peerId);\n      const username = getPeerActiveUsernames(peer)[0];\n      const size = 40;\n      const avatar = avatarNew({peerId, size, middleware});\n      const row = wrapSolidComponent(() => (\n        <RowTsx clickable class=\"topbar-search-left-sender\">\n          <RowTsx.Title>\n          <span>\n            <b>{title}</b> {username && <span class=\"secondary\">{`@${username}`}</span>}\n          </span>\n          </RowTsx.Title>\n          <RowTsx.Media size=\"40\">{avatar.node}</RowTsx.Media>\n        </RowTsx>\n      ), middleware);\n      await avatar.readyThumbPromise;\n\n      return row;\n    });\n\n    const rendered = await Promise.all(promises);\n    if(!middleware()) {\n      return;\n    }\n\n    setF((value) => {\n      value.count = (result as ChannelsChannelParticipants.channelsChannelParticipants).count ?? peerIds.length;\n      const newLength = value.values.push(...peerIds);\n      offset = newLength;\n      if(newLength >= value.count) {\n        value.loadMore = undefined;\n      }\n\n      value.rendered.push(...rendered);\n      return value;\n    });\n    loading = false;\n  };\n\n  const [f, setF] = createLoadableList<PeerId>({loadMore});\n  return f;\n};\n\nfunction SearchFooter(props: {\n  index: () => number,\n  count: () => number,\n  pickUserBtn: JSX.Element,\n  pickDateBtn: JSX.Element,\n  resultsShown: () => boolean,\n  onToggle: () => void,\n  choosingSender: () => boolean\n}) {\n  return (\n    <div class={classNames('chat-search-footer', props.choosingSender() && 'hide')}>\n      <div class=\"chat-search-footer-left\">\n        {props.pickDateBtn}\n        {props.pickUserBtn}\n        <span class={classNames('chat-search-footer-count', props.count() === undefined && 'hide')}>\n          {\n            props.count() === 0 ?\n              i18n('NoResult') :\n              props.resultsShown() ? i18n('messages', [props.count()]) : i18n('Of', [props.index() + 1, props.count()])\n          }\n        </span>\n      </div>\n      <div class={classNames('chat-search-footer-right', !props.count() && 'hide')}>\n        <span\n          class=\"chat-search-footer-type\"\n          onClick={() => props.onToggle()}\n        >\n          {i18n(props.resultsShown() ? 'SearchAsChat' : 'SearchAsList')}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nfunction SearchMobileResults(props: {\n  scrollable: JSX.Element\n}) {\n  return (\n    <div class=\"chat-search-results chatlist-container\">\n      {props.scrollable}\n    </div>\n  );\n}\n\nfunction SearchMobileTop(props: {\n  reactionsScrollable: JSX.Element,\n  searchTypesScrollable: JSX.Element,\n  hasReactions: () => boolean,\n  hasSearchTypes: () => boolean\n}) {\n  return (\n    <div class=\"chat-search-top\">\n      {props.hasSearchTypes() ? props.searchTypesScrollable : props.reactionsScrollable}\n    </div>\n  );\n}\n\nfunction SearchMobileButtons(props: {\n  index: () => number,\n  count: () => number,\n  chat: Chat,\n  onArrowButtonClick: (direction: 'up' | 'down') => void\n}) {\n  const makeButton = (icon: 'up' | 'down', onClick: () => void) => {\n    const btn = ButtonCorner({icon, className: 'bubbles-corner-button chat-secondary-button chat-search-go chat-search-go-' + icon});\n    const detach = attachClickEvent(btn, onClick);\n    onCleanup(detach);\n\n    const isEnd = createMemo(() => {\n      if(icon === 'down') {\n        return props.index() === 0;\n      } else {\n        return props.index() === props.count() - 1;\n      }\n    });\n\n    createEffect(() => {\n      btn.classList.toggle('is-end', isEnd());\n      btn.classList.toggle('hide', (props.count() || 0) < 2);\n    });\n\n    return btn;\n  };\n\n  const buttons = [\n    makeButton('up', props.onArrowButtonClick.bind(null, 'up')),\n    makeButton('down', props.onArrowButtonClick.bind(null, 'down'))\n  ];\n\n  props.chat.bubbles.container.after(...buttons);\n  onCleanup(() => {\n    buttons.forEach((button) => {\n      button.remove();\n    });\n  });\n}\n\nexport default function TopbarSearch(props: {\n  chat: Chat,\n  chatType: ChatType,\n  peerId: PeerId,\n  threadId?: number,\n  filterPeerId: Accessor<PeerId>,\n  canFilterSender?: boolean,\n  query?: Accessor<string>,\n  reaction?: Accessor<Reaction>,\n  onClose?: () => void,\n  onDatePick?: (timestamp: number) => void,\n  onActive?: (active: boolean, showingReactions: boolean, isSmallScreen: boolean) => void,\n  onSearchTypeChange?: () => void,\n  onValueChange?: (value: string) => void,\n  noList?: boolean\n}) {\n  const mediaSizes = useMediaSizes();\n  const isSmallScreen = createMemo(() => mediaSizes.activeScreen === ScreenSize.mobile);\n  const [isInputFocused, setIsInputFocused] = createSignal(false);\n  const [value, setValue] = createSignal<string>('');\n  const [count, setCount] = createSignal<number>();\n  const [totalCount, setTotalCount] = createSignal<number>();\n  const [list, setList] = createSignal<{element: HTMLElement, type: 'messages' | 'senders'}>();\n  const [messages, setMessages] = createSignal<(Message.message | Message.messageService)[]>();\n  const [sendersPeerIds, setSendersPeerIds] = createSignal<PeerId[]>();\n  const [loadMore, setLoadMore] = createSignal<() => Promise<void>>();\n  const [target, setTarget] = createSignal<HTMLElement>(undefined, {equals: false});\n  const [filteringSender, setFilteringSender] = createSignal<boolean>(false);\n  const [filterPeerId, setFilterPeerId] = createSignal<PeerId>();\n  const [senderInputEntity, setSenderInputEntity] = createSignal<HTMLElement>();\n  const [savedReactionTags, setSavedReactionTags] = createSignal<SavedReactionTag[]>(undefined, {equals: false});\n  const [reactionsElement, setReactionsElement] = createSignal<ReactionsElement>();\n  const [reaction, setReaction] = createSignal<Reaction>(undefined, {equals: false});\n  const [searchType, setSearchType] = createSignal<SearchType>(DEFAULT_SEARCH_TYPE);\n  const [showingSmallResults, setShowingSmallResults] = createSignal(false);\n  const choosingSender = createMemo(() => filteringSender() && !filterPeerId());\n  const shouldShowResults = createMemo(() => isSmallScreen() ? showingSmallResults() : isInputFocused());\n  const shouldHaveListNavigation = createMemo(() => (shouldShowResults() && count() && list()) || undefined);\n  const lookingHashtag = createMemo(() => {\n    if(filteringSender() || reaction()) return;\n    const _value = value();\n    return _value.startsWith('#') ? _value.slice(1) : undefined;\n  });\n  const isHashtag = createMemo(() => lookingHashtag() !== undefined);\n  const shouldShowReactions = createMemo(() => {\n    if(isHashtag()) return false;\n    const element = reactionsElement();\n    const tags = savedReactionTags();\n    return !!(element && tags?.length);\n  });\n  const shouldShowSearchTypes = createMemo(() => isHashtag());\n  const shouldShowFromPlaceholder = createMemo(() => (!isSmallScreen() || !filterPeerId()) && filteringSender());\n  const isActive = createMemo(() => isSmallScreen() || shouldShowReactions()/*  || shouldShowSearchTypes() */ || shouldShowResults());\n  const isPremium = usePremium();\n\n  if(props.onActive) {\n    createEffect(() => {\n      props.onActive(isActive(), shouldShowReactions(), isSmallScreen());\n    });\n\n    onCleanup(() => {\n      props.onActive(false, false, isSmallScreen());\n    });\n  }\n\n  createEffect(() => {\n    props.onValueChange?.(value());\n  });\n\n  // * full search replacement\n  createEffect(() => {\n    inputSearch.onChange(inputSearch.value = props.query());\n    setFilteringSender(!!props.filterPeerId());\n    setFilterPeerId(props.filterPeerId());\n    setReaction(props.reaction());\n\n    onMount(() => {\n      placeCaretAtEnd(inputSearch.input);\n    });\n  });\n\n  // * list navigation\n  createEffect(() => {\n    const {element} = shouldHaveListNavigation() || {};\n    if(!element) {\n      return;\n    }\n\n    const list = element.firstElementChild as HTMLElement;\n    const activeClassName = 'menu-open';\n    const el = list.querySelector(`.${activeClassName}`);\n    el && el.classList.remove(activeClassName);\n    const {detach} = attachListNavigation({\n      list,\n      type: 'y',\n      onSelect: (target) => {\n        const shouldBlur = !!(!filteringSender() || filterPeerId());\n        setTarget(target as HTMLElement);\n        if(shouldBlur) {\n          blurActiveElement();\n        }\n      },\n      activeClassName,\n      cancelMouseDown: true,\n      target: untrack(target)\n    });\n\n    onCleanup(() => {\n      detach();\n    });\n  });\n\n  const navigationItem: NavigationItem = {\n    type: 'topbar-search',\n    onPop: () => {\n      if(isInputFocused() && value()) {\n        blurActiveElement();\n        return false;\n      }\n\n      props.onClose?.();\n    }\n  };\n  appNavigationController.pushItem(navigationItem);\n  onCleanup(() => {\n    appNavigationController.removeItem(navigationItem);\n  });\n\n  const onInputClear: (e?: MouseEvent, wasEmpty?: boolean) => void = (e, wasEmpty = inputSearch.inputField.isEmpty()) => {\n    if(filterPeerId()) {\n      e && cancelEvent(e);\n      wasEmpty && setFilterPeerId(undefined);\n      return;\n    }\n\n    if(filteringSender()) {\n      e && cancelEvent(e);\n      wasEmpty && setFilteringSender(false);\n      return;\n    }\n\n    if(wasEmpty) {\n      if(isSmallScreen()) {\n        return;\n      }\n\n      props.onClose?.();\n    }\n  };\n\n  const inputSearch: InputSearch = new InputSearch({\n    placeholder: 'Search',\n    onChange: setValue,\n    onClear: onInputClear,\n    onFocusChange: setIsInputFocused,\n    onBack: () => {\n      props.onClose?.();\n    },\n    alwaysShowClear: true,\n    noBorder: true,\n    verifyDebounce: (value) => {\n      return value !== '#' &&\n        !inputSearch.container.classList.contains('show-placeholder') &&\n        !!value.trim(); // skip debounce for hashtag\n    },\n    arrowBack: isSmallScreen()\n  });\n  inputSearch.container.classList.add('topbar-search-input-container');\n  inputSearch.input.classList.add('topbar-search-input');\n  const onKeyDown = (e: KeyboardEvent) => {\n    if(e.key !== 'Backspace') {\n      return;\n    }\n\n    const isEmpty = inputSearch.inputField.isEmpty();\n    if(isEmpty && (filterPeerId() || filteringSender())) {\n      onInputClear(undefined, isEmpty);\n    }\n  };\n  subscribeOn(inputSearch.input)('keydown', onKeyDown);\n  onCleanup(() => {\n    inputSearch.remove();\n  });\n\n  const hashWidth = getTextWidth('#', FontFull);\n  const fromText = I18n.format('Search.From', true) + ' ';\n  const fromWidth = getTextWidth(fromText, FontFull);\n  const fromSpan = (<span class={classNames('topbar-search-input-from', shouldShowFromPlaceholder() && 'is-visible')}>{fromText}</span>);\n  inputSearch.container.append(fromSpan as HTMLElement);\n  createEffect<HTMLElement>((_element) => {\n    const filtering = filteringSender();\n    const _isHashtag = isHashtag();\n    if(_element) {\n      _element.classList.remove('scale-in');\n      void _element.offsetWidth;\n      _element.classList.add('scale-out');\n      setTimeout(() => {\n        _element.remove();\n      }, 200);\n    }\n\n    const element = senderInputEntity();\n    if(element) {\n      element.classList.add('topbar-search-input-entity', 'scale-in');\n      const detach = attachClickEvent(element, (e) => {\n        cancelEvent(e);\n        if(_isHashtag) {\n          setSearchType();\n        } else {\n          setFilterPeerId();\n        }\n      }, {cancelMouseDown: true});\n      onCleanup(detach);\n      inputSearch.container.append(element);\n    }\n\n    inputSearch.container.style.setProperty('--padding-placeholder', (shouldShowFromPlaceholder() ? fromWidth : 0) + 'px');\n    inputSearch.container.style.setProperty('--padding-hashtag', (_isHashtag ? hashWidth : 0) + 'px');\n    inputSearch.container.style.setProperty('--padding-sender', (element ? element.offsetWidth + 6 : 0) + 'px');\n    inputSearch.setPlaceholder(filtering && !element ? 'Search.Member' : (_isHashtag ? 'Search.Hashtag' : 'Search'));\n    return element;\n  });\n\n  // * keep placeholder while input is empty\n  createEffect(() => {\n    inputSearch.container.classList.toggle('show-placeholder', /* !value() ||  */lookingHashtag() === '');\n  });\n\n  const PeerEntity = (props: {\n    peerId?: PeerId | string,\n    fallbackIcon?: Icon,\n    title?: HTMLElement,\n    active?: Accessor<boolean>,\n    onPromises?: (promises: Promise<any>[]) => void,\n    onClick?: () => void,\n  }) => {\n    const middleware = createMiddleware().get();\n    const entity = untrack(() => AppSelectPeers.renderEntity({\n      key: props.peerId,\n      title: props.title,\n      fallbackIcon: props.fallbackIcon,\n      middleware,\n      avatarSize: 30,\n      meAsSaved: false\n    }));\n\n    if(props.active !== undefined) {\n      createEffect(() => {\n        entity.element.classList.toggle('active', props.active());\n      });\n    }\n\n    if(props.onClick) {\n      const detach = attachClickEvent(entity.element, (e) => {\n        cancelEvent(e);\n        props.onClick();\n      }, {cancelMouseDown: true});\n      onCleanup(detach);\n    }\n\n    if(props.onPromises) {\n      props.onPromises(entity.promises);\n    }\n\n    return entity.element;\n  };\n\n  const SearchTypeEntity = (_props: {\n    type: SearchType,\n    notList?: boolean,\n    onPromises?: (promises: Promise<any>[]) => void\n  }) => {\n    const peerId = _props.type === 'this' ? props.peerId : (_props.type === 'my' ? rootScope.myId : 'public');\n    const title = i18n(`Search.Types.${_props.type === 'this' ? 'ThisChat' : _props.type === 'my' ? 'MyMessages' : 'PublicPosts'}`);\n    return (\n      <PeerEntity\n        peerId={peerId}\n        title={title}\n        {...(!_props.notList && {\n          active: () => searchType() === _props.type,\n          onClick: () => setSearchType((type) => type === _props.type ? DEFAULT_SEARCH_TYPE : _props.type)\n        })}\n        fallbackIcon={_props.type === 'public' ? 'newchannel_filled' : undefined}\n        onPromises={_props.onPromises}\n      />\n    );\n  };\n\n  // * handle sender or search type entity\n  createEffect(async() => {\n    const peerId = filterPeerId();\n    const _searchType = searchType();\n    const middleware = createMiddleware().get();\n    let element: HTMLElement;\n    if(peerId || _searchType) {\n      element = await new Promise((resolve) => {\n        let element: HTMLDivElement;\n        const onPromises = async(promises: Promise<any>[]) => {\n          await Promise.all(promises);\n          return resolve(element);\n        };\n\n        if(_searchType) {\n          element = SearchTypeEntity({\n            type: _searchType,\n            notList: true,\n            onPromises\n          }) as HTMLDivElement;\n        } else {\n          element = PeerEntity({\n            peerId,\n            onPromises\n          });\n        }\n      });\n      if(!middleware()) {\n        return;\n      }\n    }\n\n    setSenderInputEntity(element);\n  });\n\n  const MIN_HEIGHT = 43;\n  const MAX_HEIGHT = 271;\n\n  const onArrowButtonClick = (direction: 'up' | 'down') => {\n    // let _target = scrollableDiv.querySelector<HTMLElement>('.active');\n    let _target = target();\n    if(!_target) {\n      _target = scrollableDiv.querySelector<HTMLElement>('.chatlist-chat');\n      setTarget(_target);\n      return;\n    }\n\n    if(direction === 'down') {\n      _target = _target.previousElementSibling as HTMLElement;\n    } else {\n      _target = _target.nextElementSibling as HTMLElement;\n    }\n\n    if(!_target || !_target.classList.contains('chatlist-chat')) {\n      return;\n    }\n\n    // set scroll position to center\n    const top = _target.offsetTop;\n    const clientHeight = MAX_HEIGHT;\n    scrollableDiv.scrollTop = top - clientHeight / 2 + _target.clientHeight / 2;\n\n    setTarget(_target);\n  };\n\n  const ArrowButton = ({direction}: {direction: 'up' | 'down'}) => {\n    return (\n      <ButtonIconTsx\n        icon={direction}\n        class={classNames(\n          'input-search-part',\n          'topbar-search-input-arrow',\n          (!count() || (filteringSender() && !filterPeerId())) && 'hide'\n        )}\n        noRipple\n        onClick={() => {\n          onArrowButtonClick(direction);\n        }}\n      />\n    );\n  };\n\n  const b = inputSearch.clearBtn.previousSibling;\n  let inputSearchTools: HTMLDivElement;\n  (<div ref={inputSearchTools} class=\"topbar-search-input-tools\">\n    {!isSmallScreen() && (\n      <>\n        <ArrowButton direction=\"up\" />\n        <ArrowButton direction=\"down\" />\n      </>\n    )}\n    {inputSearch.clearBtn}\n  </div>);\n  b.after(inputSearchTools);\n\n  const updateChatSearchContext = (searchType: SearchType, query: string) => {\n    appImManager.chat.setMessageId({\n      query: searchType && query || undefined,\n      isPublicHashtag: searchType === 'public' || undefined,\n      isCacheableSearch: !!searchType || undefined,\n      inputFilter: query && searchType ? {_: 'inputMessagesFilterEmpty'} : undefined,\n      type: query && searchType ? ChatType.Search : props.chatType,\n      hashtagType: searchType\n    });\n  };\n\n  // * search\n  createEffect<Partial<{searchType: SearchType, query: string}>>((prev) => {\n    if(props.noList) return;\n\n    prev ||= {};\n    const {peerId, threadId} = props;\n    const query = value();\n    const fromPeerId = filterPeerId();\n    const isSender = choosingSender();\n    const middleware = createMiddleware().get();\n    const isEmptyQuery = !query.trim() || query === '#';\n    const _isHashtag = isHashtag();\n    const _reaction = !isSender && reaction();\n    const _searchType = searchType();\n\n    // * reset search if it's not a hashtag anymore\n    if(_searchType && !query) {\n      setSearchType();\n      updateChatSearchContext(undefined, undefined);\n      return;\n    }\n\n    setLoadMore(() => undefined as any);\n    setMessages();\n    setSendersPeerIds();\n    setTarget();\n\n    const loader = (isSender ? createParticipantsLoader : createSearchLoader)({\n      middleware,\n      peerId,\n      threadId,\n      monoforumThreadId: props.chat.monoforumThreadId,\n      query,\n      fromPeerId,\n      reaction: _reaction,\n      searchType: _searchType\n    });\n\n    const isEmpty = createMemo(() => count() === 0 || (_isHashtag && count() === undefined));\n\n    let ref: HTMLDivElement;\n    const list = (\n      <div\n        ref={ref}\n        class={classNames(!untrack(isSmallScreen) && 'topbar-search-left-chatlist', 'chatlist', isEmpty() && 'is-empty')}\n      >\n        {isEmpty() ? (\n          <div class=\"topbar-search-left-results-empty\">\n            {_isHashtag && (count() === undefined ?\n              i18n('Search.HelpHashtag') :\n              i18n('Search.EmptyHashtag', [wrapEmojiText(stringMiddleOverflow(query, 18))]))}\n            {!_isHashtag && (fromPeerId ?\n              i18n('Search.EmptyFrom', [(() => {\n                const peerTitle = new PeerTitle({peerId: fromPeerId});\n                return peerTitle.element;\n              })()]) :\n              i18n('Search.Empty', [wrapEmojiText(stringMiddleOverflow(query, 18))])\n            )}\n          </div>\n        ) : (\n          <>\n            <div>\n              {loader().rendered}\n            </div>\n            {loader().rendered && <div class=\"topbar-search-left-results-padding\" />}\n          </>\n        )}\n      </div>\n    );\n\n    let first = true;\n    const onLoad = (firstElement?: HTMLElement) => {\n      if(first) {\n        inputSearch.toggleLoading(false);\n        setList({element: ref, type: isSender ? 'senders' : 'messages'});\n        scrollableDiv.scrollTop = 0;\n        first = false;\n\n        // * jump to first target\n        if(untrack(isSmallScreen) && !isSender) {\n          setTarget(untrack(messages) && firstElement);\n        }\n      }\n    };\n\n    if(_searchType !== prev.searchType || (_searchType && query !== prev.query)) {\n      props.onSearchTypeChange?.();\n      updateChatSearchContext(_searchType, query);\n    }\n\n    const current = {searchType: _searchType, query};\n\n    if(!isSender && !fromPeerId && !_reaction && isEmptyQuery) {\n      setCount();\n      setTotalCount();\n      onLoad();\n      return current;\n    }\n\n    createEffect(\n      on(\n        () => loader(),\n        ({rendered, values, count, loadMore}) => {\n          setCount(rendered.length);\n          setTotalCount(count);\n          setLoadMore(() => loadMore);\n          if(isSender) setSendersPeerIds(values as any);\n          else setMessages(values as any);\n          onLoad((rendered as HTMLElement[])[0]);\n        },\n        {defer: true}\n      )\n    );\n\n    inputSearch.toggleLoading(true);\n    untrack(() => loader().loadMore());\n    return current;\n  });\n\n  // * handle target change to jump to message\n  createEffect(\n    on(\n      target,\n      (target) => {\n        const idx = whichChild(target);\n        if(idx === -1) {\n          return;\n        }\n\n        if(choosingSender()) {\n          const peerId = sendersPeerIds()[idx];\n          batch(() => {\n            setFilterPeerId(peerId);\n            inputSearch.onChange(inputSearch.value = '');\n          });\n          return;\n        }\n\n        const previousActive = target.parentElement.querySelector('.active');\n        if(previousActive) {\n          previousActive.classList.remove('active');\n        }\n\n        target.classList.add('active');\n\n        setShowingSmallResults(false);\n\n        const message = messages()[idx];\n        const query = value().trim();\n        deferSideEffect(() => {\n          appImManager.chat.setMessageId({\n            lastMsgId: message.mid,\n            lastMsgPeerId: message.peerId,\n            highlight: query ? {type: 'search', query} : undefined\n          });\n        });\n      },\n      {defer: true}\n    )\n  );\n\n  const tagToReactionCount = (tag: SavedReactionTag): ReactionCount => {\n    return {\n      _: 'reactionCount',\n      count: tag.count,\n      reaction: tag.reaction\n    };\n  };\n\n  const tagsToMessageReactions = (tags: SavedReactionTag[]): MessageReactions => {\n    return {\n      _: 'messageReactions',\n      pFlags: {reactions_as_tags: true},\n      results: tags.map(tagToReactionCount)\n    };\n  };\n\n  const onSavedTags = ({savedPeerId, tags}: BroadcastEvents['saved_tags']) => {\n    if(savedPeerId !== props.threadId) {\n      return;\n    }\n\n    setSavedReactionTags(tags);\n  };\n  subscribeOn(rootScope)('saved_tags', onSavedTags);\n\n  // * render saved reaction tags\n  createEffect<HTMLElement>((previousLock) => {\n    const tags = savedReactionTags();\n    const element = reactionsElement();\n    if(!tags || !element) {\n      return previousLock;\n    }\n\n    const reactionsContext: ReactionsContext = {\n      ...element.getContext(),\n      reactions: tagsToMessageReactions(tags)\n    };\n\n    // * set active\n    const _reaction = reaction();\n    let chosenReactionCount: ReactionCount;\n    if(_reaction) {\n      const reactionCount = reactionsContext.reactions.results.find((reactionCount) => reactionsEqual(reactionCount.reaction, _reaction));\n      if(reactionCount) {\n        chosenReactionCount = reactionCount;\n        reactionCount.chosen_order = 0;\n      }\n    }\n\n    previousLock?.remove();\n    element.update(reactionsContext);\n\n    if(chosenReactionCount) {\n      const reactionElement = element.getSorted().find((element) => reactionsEqual(element.reactionCount.reaction, _reaction));\n      fastSmoothScroll({\n        container: reactionsScrollableDiv,\n        element: reactionElement,\n        position: 'center',\n        axis: 'x'\n      });\n    }\n\n    const premium = isPremium();\n    element.classList.toggle('is-locked', !premium);\n    if(!premium) {\n      const icon: Icon = 'premium_lock';\n      const reaction = new ReactionElement();\n      reaction.init(ReactionLayoutType.Tag, createMiddleware().get());\n      reaction.reactionCount = {\n        _: 'reactionCount',\n        count: 1,\n        reaction: icon as any\n      };\n      reaction.setCanRenderAvatars(false);\n      reaction.renderCounter(undefined, i18n('Unlock'));\n      reaction.classList.add('reaction-tag-lock');\n\n      const allReactionsSticker = document.createElement('div');\n      allReactionsSticker.classList.add('reaction-sticker', 'reaction-sticker-icon');\n      allReactionsSticker.append(Icon(icon));\n      reaction.lastElementChild.before(allReactionsSticker);\n\n      element.prepend(reaction);\n      return reaction;\n    }\n  });\n\n  // * load saved reaction tags\n  createEffect(() => {\n    if(props.peerId !== rootScope.myId) {\n      setReactionsElement();\n      setSavedReactionTags();\n      return;\n    }\n\n    const realMiddleware = createMiddleware().get();\n    const middlewareHelper = getMiddleware();\n    onCleanup(() => {\n      setTimeout(() => {\n        middlewareHelper.destroy();\n      }, 400);\n    });\n    const reactionsElement = new ReactionsElement();\n    reactionsElement.init({\n      context: {peerId: props.peerId, mid: 0, reactions: tagsToMessageReactions([])},\n      type: ReactionLayoutType.Block,\n      middleware: middlewareHelper.get(),\n      forceCounter: true\n    });\n    reactionsElement.classList.remove('has-no-reactions');\n    reactionsElement.classList.add('topbar-search-left-reactions');\n\n    // * reactions listener\n    const detach = attachClickEvent(reactionsElement, (e) => {\n      const reactionElement = findUpClassName(e.target, 'reaction-tag') as ReactionElement;\n      if(!reactionElement) {\n        return;\n      }\n\n      if(!isPremium()) {\n        PopupPremium.show({feature: 'saved_tags'});\n        return;\n      }\n\n      const {reactionCount} = reactionElement;\n      const {reaction} = reactionCount;\n      setReaction((prev) => {\n        if(reactionsEqual(prev, reaction)) {\n          return;\n        }\n\n        return reaction;\n      });\n\n      placeCaretAtEnd(inputSearch.input);\n    }, {cancelMouseDown: true});\n    onCleanup(detach);\n\n    const get = () => {\n      rootScope.managers.appReactionsManager.getSavedReactionTags(props.threadId).then((tags) => {\n        // await pause(1000);\n        if(!realMiddleware()) {\n          return;\n        }\n\n        setReactionsElement(reactionsElement);\n        setSavedReactionTags(tags);\n      });\n    };\n\n    get();\n    rootScope.addEventListener('saved_tags_clear', get);\n    onCleanup(() => {\n      rootScope.removeEventListener('saved_tags_clear', get);\n    });\n  });\n\n  // * handle reaction changing\n  let first = true;\n  createEffect(on(\n    reaction,\n    (reaction) => {\n      if(first) {\n        first = false;\n\n        if(!reaction) {\n          return;\n        }\n      }\n\n      deferSideEffect(() => {\n        appImManager.chat.setMessageId({\n          savedReaction: reaction ? [reaction as Reaction.reactionCustomEmoji | Reaction.reactionEmoji] : undefined\n        });\n      });\n    }\n  ));\n\n  // * reset reaction on close\n  onCleanup(() => {\n    if(!reaction()) {\n      return;\n    }\n\n    deferSideEffect(() => {\n      appImManager.chat.setMessageId({\n        lastMsgId: undefined,\n        lastMsgPeerId: undefined,\n        mediaTimestamp: undefined,\n        savedReaction: undefined\n      });\n    });\n  });\n\n  // * reset search on close\n  onCleanup(() => {\n    if(appImManager.chat.type !== ChatType.Search) {\n      return;\n    }\n\n    updateChatSearchContext(undefined, undefined);\n  });\n\n  // * mobile search\n  createEffect(() => {\n    inputSearch.setArrowBack(isSmallScreen());\n    if(!isSmallScreen()) {\n      return;\n    }\n\n    const index = () => whichChild(target());\n\n    const footerElement = SearchFooter({\n      index,\n      count: totalCount,\n      pickUserBtn,\n      pickDateBtn,\n      resultsShown: shouldShowResults,\n      onToggle: () => {\n        setShowingSmallResults((prev) => !prev);\n      },\n      choosingSender\n    }) as HTMLElement;\n\n    const resultsElement = SearchMobileResults({\n      scrollable\n    }) as HTMLElement;\n\n    const topElement = SearchMobileTop({\n      reactionsScrollable,\n      searchTypesScrollable,\n      hasReactions: () => !!calculateReactionsHeight(),\n      hasSearchTypes: () => !!calculateSearchTypesHeight()\n    }) as HTMLElement;\n\n    SearchMobileButtons({\n      index,\n      count: totalCount,\n      chat: props.chat,\n      onArrowButtonClick\n    });\n\n    const onShowingSmallResultsChange = (value = showingSmallResults()) => {\n      props.chat.bubbles.container.classList.toggle('search-results-active', value);\n      props.chat.bubbles.updateGoDownVisibility();\n      resultsElement.classList.toggle('active', value);\n    };\n\n    const onTopActive = (value?: boolean) => {\n      value ??= !!(calculateReactionsHeight() || calculateSearchTypesHeight());\n      props.chat.topbar.container.classList.toggle('search-top-active', value);\n      resultsElement.classList.toggle('search-top-active', value);\n      if(value) container.after(topElement);\n      else topElement.remove();\n    };\n\n    createEffect(() => onShowingSmallResultsChange());\n    createEffect(() => onTopActive());\n\n    createEffect(() => {\n      if(choosingSender()) {\n        setShowingSmallResults(true);\n      } else if(!filteringSender()) {\n        setShowingSmallResults(false);\n      }\n    });\n\n    onCleanup(() => {\n      footerElement.remove();\n      setShowingSmallResults(false);\n      onShowingSmallResultsChange();\n      onTopActive(false);\n\n      setTimeout(() => {\n        resultsElement.remove();\n      }, 400);\n    });\n\n    props.chat.input.chatInput.before(resultsElement, footerElement);\n  });\n\n  const calculateResultsHeight = createMemo(() => {\n    if(!shouldShowResults()) {\n      return 0;\n    }\n\n    const length = count();\n    if(length === undefined && !isHashtag()) {\n      return 0;\n    }\n\n    const paddingVertical = 8 * 2;\n    let height: number;\n    if(!length) {\n      height = MIN_HEIGHT;\n    } else if(list().type === 'senders') {\n      height = 1 + paddingVertical + length * 48;\n    } else {\n      height = 1 + paddingVertical + length * 56;\n    }\n\n    return Math.min(MAX_HEIGHT, height);\n  });\n\n  const calculateReactionsHeight = createMemo(() => {\n    if(!isActive()) {\n      return 0;\n    }\n\n    return shouldShowReactions() ? 61 : 0;\n  });\n\n  const calculateSearchTypesHeight = createMemo(() => {\n    if(!isActive()) {\n      return 0;\n    }\n\n    return shouldShowSearchTypes() ? 61 : 0;\n  });\n\n  const pickUserBtn = props.canFilterSender && (\n    <ButtonIconTsx\n      class={classNames(!isSmallScreen() && 'topbar-search-right-filter-button')}\n      icon=\"newprivate\"\n      ref={(element) => {\n        const detach = attachClickEvent(element, (e) => {\n          cancelEvent(e);\n          inputSearch.onChange(inputSearch.value = '');\n          setFilteringSender(true);\n          placeCaretAtEnd(inputSearch.input, true);\n        }, {cancelMouseDown: true});\n        onCleanup(detach);\n      }}\n    />\n  );\n\n  const pickDateBtn = props.onDatePick && (\n    <ButtonIconTsx\n      icon=\"calendar\"\n      onClick={() => {\n        showDatePickerPopup({\n          initDate: new Date(),\n          onPick: props.onDatePick\n        });\n      }}\n    />\n  );\n\n  let scrollableDiv: HTMLDivElement;\n  const scrollable = (\n    <Scrollable\n      ref={scrollableDiv}\n      class={!isSmallScreen() ? 'topbar-search-left-results topbar-search-left-collapsable' : undefined}\n      style={!isSmallScreen() && calculateResultsHeight() ? {height: calculateResultsHeight() + 'px'} : undefined}\n      onScrolledBottom={() => {\n        loadMore()?.();\n      }}\n    >\n      {!isSmallScreen() && <div class=\"topbar-search-left-delimiter\"></div>}\n      <Animated type=\"cross-fade\">\n        {list()?.element}\n      </Animated>\n    </Scrollable>\n  );\n\n  let reactionsScrollableDiv: HTMLDivElement;\n  const reactionsScrollable = (\n    <Scrollable axis=\"x\" ref={reactionsScrollableDiv} class=\"topbar-search-left-reactions-scrollable\">\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n      {reactionsElement()}\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n    </Scrollable>\n  );\n\n  let searchTypesScrollableDiv: HTMLDivElement;\n  const searchTypesScrollable = (\n    <Scrollable axis=\"x\" ref={searchTypesScrollableDiv} class=\"topbar-search-left-reactions-scrollable\">\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n      <div class=\"topbar-search-left-search-types\">\n        {SEARCH_TYPES.map((type) => (<SearchTypeEntity type={type} />))}\n      </div>\n      <div class=\"topbar-search-left-reactions-padding\"></div>\n    </Scrollable>\n  );\n\n  let container: HTMLDivElement;\n  return (\n    <div ref={container} class=\"topbar-search-container\">\n      <div\n        class={classNames('topbar-search-left-container', isActive() && 'is-focused')}\n        // style={calculateHeight() ? {height: calculateHeight() + 'px'} : undefined}\n      >\n        <div class=\"topbar-search-left-background\">\n          {/* <div class=\"topbar-search-left-background-shadow\"></div> */}\n        </div>\n        {inputSearch.container}\n        {/* shouldShowReactions() &&  */!isSmallScreen() && (\n          <div\n            class=\"topbar-search-left-reactions-container topbar-search-left-collapsable\"\n            style={calculateReactionsHeight() ? {height: calculateReactionsHeight() + 'px'} : undefined}\n          >\n            <div class=\"topbar-search-left-delimiter\"></div>\n            {reactionsScrollable}\n          </div>\n        )}\n        {/* shouldShowReactions() &&  */!isSmallScreen() && (\n          <div\n            class=\"topbar-search-left-reactions-container topbar-search-left-collapsable\"\n            style={calculateSearchTypesHeight() ? {height: calculateSearchTypesHeight() + 'px'} : undefined}\n          >\n            <div class=\"topbar-search-left-delimiter\"></div>\n            {searchTypesScrollable}\n          </div>\n        )}\n        {!isSmallScreen() && scrollable}\n      </div>\n      {!isSmallScreen() && (\n        <div class=\"topbar-search-right-container\">\n          {pickUserBtn && (\n            <div class={classNames('topbar-search-right-filter', (filteringSender() || isHashtag()) && 'is-hidden')}>\n              {pickUserBtn}\n            </div>\n          )}\n          {pickDateBtn && (\n            <div class={classNames('topbar-search-right-filter', isHashtag() && 'is-hidden')}>\n              {pickDateBtn}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n","import {i18n} from '@lib/langPack';\n\nimport showChatToast from '@components/chat/chatToast';\nimport Button from '@components/buttonTsx';\n\nimport styles from '@components/chat/priceChangedInterceptor/priceChangedTooltip.module.scss';\n\n\ntype ShowPriceChangedTooltipArgs = {\n  starsAmount: number;\n  onResend: () => void;\n  onHide?: () => void;\n};\n\nexport default function showPriceChangedTooltip({starsAmount, onResend, onHide}: ShowPriceChangedTooltipArgs) {\n  // * docked below the topbar and its floating plates by showChatToast. Mounting it on\n  // * .bubbles instead traps it in that transformed z-index:1 stacking context, where it\n  // * paints behind the topbar and gets clipped by it\n  return showChatToast({\n    animation: 'fade',\n    // * without one it hangs until the chat is left or the repay goes through. The message\n    // * itself keeps the failure (a \"failed to pay\" service line + Resend in its context\n    // * menu), so this is a notice, not the only way back to it\n    duration: 10000,\n    onHide,\n    textElement: i18n('PaidMessages.PriceChanged', [i18n('Stars', [starsAmount])]),\n    rightElement: (\n      <Button\n        class={`btn ${styles.Button}`}\n        onClick={onResend}\n      >\n        {i18n('Resend')}\n      </Button>\n    ),\n    class: styles.Tooltip,\n    icon: 'sendingerror_filled'\n  });\n}\n","import accumulate from '@helpers/array/accumulate';\nimport type ListenerSetter from '@helpers/listenerSetter';\nimport memoizeAsyncWithTTL from '@helpers/memoizeAsyncWithTTL';\nimport safeAssign from '@helpers/object/safeAssign';\nimport type {InputPeer} from '@layer';\nimport type {AppManagers} from '@lib/managers';\nimport rootScope from '@lib/rootScope';\nimport {setReservedStars} from '@stores/stars';\n\nimport type Chat from '@components/chat/chat';\nimport {PAYMENT_REJECTED} from '@components/chat/paidMessagesInterceptor';\n\nimport showPriceChangedTooltip from '@components/chat/priceChangedInterceptor/priceChangedTooltip';\n\n\ntype PendingRequest = {\n  id: number;\n  messageCount: number;\n};\n\ntype ConstructorArgs = {\n  managers: AppManagers;\n  chat: Chat;\n  listenerSetter: ListenerSetter;\n};\n\ntype OpenedTooltip = {\n  close: () => void; // * assigned right after showPriceChangedTooltip returns\n  withStarsAmount: number;\n};\n\ntype OpenTooltipArgs = {\n  starsAmount: number;\n  messageCount: number;\n  requestId: number;\n};\n\ntype ConfirmResendArgs = {\n  pendingRequests: PendingRequest[];\n};\n\nclass PriceChangedInterceptor {\n  private chat: Chat;\n  private listenerSetter: ListenerSetter;\n  private managers: AppManagers;\n\n  private pendingRequests: PendingRequest[] = [];\n\n  private openedTooltip?: OpenedTooltip;\n\n  private getStarsAmountForUser: AppManagers['appUsersManager']['getStarsAmount'];\n\n  constructor(args: ConstructorArgs) {\n    safeAssign(this, args);\n\n    this.getStarsAmountForUser = memoizeAsyncWithTTL(\n      (userId: UserId) => this.managers.appUsersManager.getStarsAmount(userId, true),\n      (userId) => userId,\n      1_000\n    );\n  }\n\n  init() {\n    this.listenerSetter.add(rootScope)('insufficent_stars_for_message', async({requestId, messageCount, invokeApiArgs, reservedStars}) => {\n      reservedStars && setReservedStars(prev => Math.max(0, prev - reservedStars));\n\n      const apiCallParams = invokeApiArgs[1];\n\n      const peer = 'peer' in apiCallParams ? apiCallParams.peer : 'to_peer' in apiCallParams ? apiCallParams.to_peer : undefined;\n      if(!peer || !('allow_paid_stars' in apiCallParams)) return;\n\n      const peerId = await this.managers.appPeersManager.getPeerId(peer as InputPeer);\n      if(peerId !== this.chat.peerId) return;\n\n      const starsAmount = await this.getAndUpdateStarsAmountIfNecessary(peerId);\n\n      this.chat.updateStarsAmount(starsAmount);\n\n      this.handleNewRepayRequest({\n        starsAmount,\n        requestId,\n        messageCount\n      });\n    });\n\n    this.listenerSetter.add(rootScope)('fulfill_repaid_message', ({requestId}) => {\n      this.pendingRequests = this.pendingRequests.filter(r => r.id !== requestId);\n      if(!this.pendingRequests.length) this.closeTooltip();\n    });\n  }\n\n  private async getAndUpdateStarsAmountIfNecessary(peerId: PeerId) {\n    if(!peerId.isUser()) return this.managers.appPeersManager.getStarsAmount(peerId);\n\n    const starsAmount = await this.getStarsAmountForUser(peerId.toUserId());\n\n    await this.managers.appUsersManager.updateCachedUserFullStarsAmount(peerId.toUserId(), starsAmount);\n\n    return starsAmount;\n  }\n\n  private handleNewRepayRequest({starsAmount, messageCount, requestId}: OpenTooltipArgs) {\n    if(this.openedTooltip && this.openedTooltip.withStarsAmount !== starsAmount) {\n      this.closeTooltip();\n    }\n\n    if(!this.openedTooltip) this.openTooltip(starsAmount);\n\n    this.pendingRequests.push({\n      id: requestId,\n      messageCount\n    });\n  }\n\n  private openTooltip(starsAmount: number) {\n    const onResend = () => {\n      this.confirmResend({\n        pendingRequests: [...this.pendingRequests]\n      });\n    };\n\n    const entry: OpenedTooltip = this.openedTooltip = {\n      close: undefined,\n      withStarsAmount: starsAmount\n    };\n\n    const {hide} = showPriceChangedTooltip({\n      starsAmount,\n      onResend,\n      // the docked toast can go away on its own (peer change, or a newer toast taking\n      // the dock) - drop our reference so the next repay request opens a fresh one\n      onHide: () => {\n        if(this.openedTooltip === entry) this.openedTooltip = undefined;\n      }\n    });\n\n    entry.close = hide;\n  }\n\n  private closeTooltip() {\n    this.openedTooltip?.close?.();\n    this.openedTooltip = undefined;\n  }\n\n  private async confirmResend({pendingRequests}: ConfirmResendArgs) {\n    const messageCount = accumulate(pendingRequests.map(r => r.messageCount), 0);\n\n    const preparedPaymentResult = await this.chat.input.paidMessageInterceptor.prepareStarsForPayment(messageCount);\n\n    if(preparedPaymentResult === PAYMENT_REJECTED) return;\n\n    await Promise.all(pendingRequests.map(({id}) => this.managers.appMessagesManager.confirmRepayRequest(id, preparedPaymentResult)));\n  }\n\n  cleanup() {\n    this.pendingRequests = [];\n    this.closeTooltip();\n  }\n}\n\nexport default PriceChangedInterceptor;\n","import type {StateSettings} from '@config/state';\nimport type {Chat} from '@layer';\nimport type {useAppSettings} from '@stores/appSettings';\nimport type {usePeer} from '@stores/peers';\n\nexport type ChatAutoDownloadSettings = {\n  photo: number,\n  video: number,\n  file: number\n};\n\nexport default function useAutoDownloadSettings(\n  peer: ReturnType<typeof usePeer<PeerId>>,\n  appSettings: ReturnType<typeof useAppSettings>[0]\n): ChatAutoDownloadSettings {\n  let type: keyof StateSettings['autoDownload'];\n\n  let photoSizeMax = 0, videoSizeMax = 0, fileSizeMax = 0;\n  if(!appSettings.autoDownloadNew.pFlags.disabled && peer) {\n    if(peer._ === 'user') {\n      if(peer.pFlags.contact) {\n        type = 'contacts';\n      } else {\n        type = 'private';\n      }\n    } else if((peer as Chat.channel).pFlags.broadcast) {\n      type = 'channels';\n    } else {\n      type = 'groups';\n    }\n\n    if(appSettings.autoDownload.photo[type]) photoSizeMax = appSettings.autoDownloadNew.photo_size_max;\n    if(appSettings.autoDownload.video[type]) videoSizeMax = appSettings.autoDownloadNew.video_size_max;\n    if(appSettings.autoDownload.file[type]) fileSizeMax = appSettings.autoDownloadNew.file_size_max;\n  }\n\n  return {\n    photo: photoSizeMax,\n    video: videoSizeMax,\n    file: fileSizeMax\n  };\n}\n","import {doubleRaf} from '@helpers/schedulers';\n\nexport default function focusSearchInput(container: HTMLElement) {\n  const focus = (onlyIfBlurred = false) => {\n    const input = container.querySelector<HTMLElement>('.topbar-search-input');\n    if(!input) {\n      return false;\n    }\n\n    const {activeElement, body, documentElement} = input.ownerDocument;\n    if(onlyIfBlurred && activeElement !== input && activeElement !== body && activeElement !== documentElement) {\n      return false;\n    }\n\n    input.focus({preventScroll: true});\n    return true;\n  };\n\n  if(!focus()) {\n    queueMicrotask(focus);\n  }\n\n  doubleRaf().then(() => focus(true));\n}\n","import type {AdminLog, ChatRights} from '@appManagers/appChatsManager';\nimport type {RequestWebViewOptions} from '@appManagers/appAttachMenuBotsManager';\nimport type {HistoryStorageKey, MessageSendingParams, MessagesStorageKey, MyMessage, RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {AppImManager, APP_TABS, ChatSetPeerOptions} from '@lib/appImManager';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport {logger, LogTypes} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport appSidebarRight from '@components/sidebarRight';\nimport ChatBubbles, {FullMid, splitFullMid} from '@components/chat/bubbles';\nimport ChatContextMenu from '@components/chat/contextMenu';\nimport ChatInput from '@components/chat/input';\nimport ChatSelection from '@components/chat/selection';\nimport ChatTopbar from '@components/chat/topbar';\nimport {HIDDEN_PEER_ID, NULL_PEER_ID, REPLIES_HIDDEN_CHANNEL_ID, REPLIES_PEER_ID, SEND_PAID_WITH_STARS_DELAY, SERVICE_PEER_ID, VERIFICATION_CODES_BOT_ID} from '@appManagers/constants';\nimport {AppPrivateSearchTab} from '@components/solidJsTabs/tabs';\nimport mediaSizes, {ScreenSize} from '@helpers/mediaSizes';\nimport ChatSearch from '@components/chat/search';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ChatBackgroundGradientRenderer from '@components/chat/gradientRenderer';\nimport {ChatBackgroundTransition} from '@components/chat/bubbles/chatBackground';\nimport {AppManagers} from '@lib/managers';\nimport SlicedArray from '@helpers/slicedArray';\nimport themeController from '@helpers/themeController';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport noop from '@helpers/noop';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {Message, WallPaper, Chat as MTChat, Reaction, AvailableReaction, ChatFull, MessageEntity, PaymentsPaymentForm, InputPeer, ChatTheme, UserFull, User, StoriesStealthMode} from '@layer';\nimport animationIntersector, {AnimationItemGroup} from '@components/animationIntersector';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport deferredPromise, {CancellablePromise, bindPromiseToDeferred} from '@helpers/cancellablePromise';\nimport {isDialog} from '@appManagers/utils/dialogs/isDialog';\nimport getDialogKey from '@appManagers/utils/dialogs/getDialogKey';\nimport getHistoryStorageKey, {getHistoryStorageType} from '@appManagers/utils/messages/getHistoryStorageKey';\nimport isForwardOfForward from '@appManagers/utils/messages/isForwardOfForward';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {SendReactionOptions} from '@appManagers/appReactionsManager';\nimport {MiddlewareHelper, getMiddleware} from '@helpers/middleware';\nimport {Accessor, createEffect, createMemo, createRoot, createSignal, on, onCleanup, Signal, untrack} from 'solid-js';\nimport TopbarSearch from '@components/chat/topbarSearch';\nimport createUnifiedSignal from '@helpers/solid/createUnifiedSignal';\nimport liteMode from '@helpers/liteMode';\nimport {useFullPeer, type PeerFull} from '@stores/fullPeers';\nimport {useAppConfig, useAppState} from '@stores/appState';\nimport {unwrap} from 'solid-js/store';\nimport callbackify from '@helpers/callbackify';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\nimport useStars, {setReservedStars} from '@stores/stars';\nimport PopupElement from '@components/popups';\nimport PopupStars from '@components/popups/stars';\nimport {getPendingPaidReactionKey, PENDING_PAID_REACTION_SENT_ABORT_REASON, PENDING_PAID_REACTIONS} from '@components/chat/reactions';\nimport showUndoablePaidTooltip, {paidReactionLangKeys} from '@components/chat/undoablePaidTooltip';\nimport namedPromises from '@helpers/namedPromises';\nimport {getCurrentNewMediaPopup} from '@components/popups/newMedia';\nimport PriceChangedInterceptor from '@components/chat/priceChangedInterceptor';\nimport {isVerificationBot} from '@components/chat/utils';\nimport {isSensitive} from '@helpers/restrictions';\nimport {isTempId} from '@appManagers/utils/messages/isTempId';\nimport {usePeer} from '@stores/peers';\nimport {useAppSettings} from '@stores/appSettings';\nimport useHistoryStorage from '@stores/historyStorages';\nimport useAutoDownloadSettings, {ChatAutoDownloadSettings} from '@hooks/useAutoDownloadSettings';\nimport usePeerTranslation from '@hooks/usePeerTranslation';\nimport debounce from '@helpers/schedulers/debounce';\nimport appNavigationController from '@components/appNavigationController';\nimport {LEFT_COLUMN_ACTIVE_CLASSNAME} from '@components/sidebarLeft';\nimport {AckedResult} from '@lib/superMessagePort';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport hasRights from '@appManagers/utils/chats/hasRights';\nimport {ChatType} from '@components/chat/chatType';\nimport {animateSingle} from '@helpers/animation';\nimport focusSearchInput from '@components/chat/focusSearchInput';\n\nexport type ChatSearchKeys = Pick<RequestHistoryOptions, 'query' | 'isCacheableSearch' | 'isPublicHashtag' | 'savedReaction' | 'fromPeerId' | 'inputFilter' | 'hashtagType'>;\nexport const CHAT_SEARCH_KEYS: (keyof ChatSearchKeys)[] = ['query', 'isCacheableSearch', 'isPublicHashtag', 'savedReaction', 'fromPeerId', 'inputFilter', 'hashtagType'];\n\n// * after this long an in-flight peer change is treated as abandoned rather than as a reason to\n// * ignore further attempts to open the same chat\nconst STUCK_SET_PEER_TIMEOUT = 15000;\n\nexport default class Chat extends EventListenerBase<{\n  setPeer: (mid: number, isTopMessage: boolean) => void\n}> {\n  public container: HTMLElement;\n  public bubblesViewport: HTMLElement;\n\n  public topbar: ChatTopbar;\n  public bubbles: ChatBubbles;\n  public input: ChatInput;\n  public selection: ChatSelection;\n  public contextMenu: ChatContextMenu;\n  public search: ChatSearch;\n\n  private priceChangedInterceptor: PriceChangedInterceptor;\n\n  public wasAlreadyUsed: boolean;\n  // public initPeerId = 0;\n\n  // * will be also used for RequestHistoryOptions\n  public peerId: PeerId;\n  public threadId: number;\n  public monoforumThreadId: number;\n  public savedReaction: (Reaction.reactionCustomEmoji | Reaction.reactionEmoji)[];\n  public isPublicHashtag: boolean;\n  public isCacheableSearch: boolean;\n  public query: string;\n  public inputFilter: RequestHistoryOptions['inputFilter'];\n  public hashtagType: 'this' | 'my' | 'public';\n  public peerIdSignal: Signal<PeerId>;\n  public chatPaddingTop: Signal<number>;\n  public chatPaddingBottom: Signal<number>;\n\n  public setPeerPromise: Promise<void>;\n  private setPeerPromiseStartedAt: number;\n  public peerChanged: boolean;\n\n  public log: ReturnType<typeof logger>;\n\n  public type: ChatType;\n  public messagesStorageKey: MessagesStorageKey;\n  public disposeHistoryStorage: () => void;\n  public isStandalone: boolean;\n\n  public noForwards: boolean;\n\n  /**\n   * Preview mode (Shift+Click on a dialog). The chat renders messages and background\n   * but performs no side effects — no readHistory / readMessages / incrementMessageViews,\n   * and no global background swap (the preview popup paints its own).\n   */\n  public isPreview: boolean;\n\n  /**\n   * Set by the preview popup before `setPeer` so the topbar's close button (rendered with a\n   * `close` icon instead of `back` in preview mode) tears down the popup instead of running\n   * `chat.pop()` against `appImManager.chat`.\n   */\n  public onPreviewClose?: () => void;\n\n  public inited: boolean;\n\n  public isRestricted: boolean;\n  public autoDownload: ChatAutoDownloadSettings;\n\n  public sharedMediaTab: AppSharedMediaTab;\n  public sharedMediaTabs: AppSharedMediaTab[];\n\n  public isBot: boolean;\n  public isChannel: boolean;\n  public isBroadcast: boolean;\n  public isLikeGroup: boolean;\n  public isAnyGroup: boolean;\n  public isMegagroup: boolean;\n  public isForum: boolean;\n  public isAllMessagesForum: boolean;\n  public isAnonymousSending: boolean;\n  public isUserBlocked: boolean;\n  public isPremiumRequired: boolean;\n  public isMonoforum: boolean;\n  public isBotforum: boolean;\n  public canManageDirectMessages: boolean;\n  public canManageBotforumTopics: boolean;\n  public isTemporaryThread: boolean;\n  public noInput: boolean;\n\n  public starsAmount: number | undefined;\n  public stealthMode: StoriesStealthMode | undefined;\n\n  public animationGroup: AnimationItemGroup;\n\n  public destroyPromise: CancellablePromise<void>;\n\n  public middlewareHelper: MiddlewareHelper;\n  public destroyMiddlewareHelper: MiddlewareHelper;\n\n  public searchSignal: ReturnType<typeof createUnifiedSignal<Parameters<Chat['initSearch']>[0]>>;\n\n  public currentTheme: Parameters<typeof themeController['getThemeSettings']>[0];\n  public currentWallPaper: WallPaper;\n  public preferredBackgroundTransition?: ChatBackgroundTransition;\n\n  /**\n   * Stashed by `_handleBackgrounds` on the peer-change publish: a bundle of the staging-slot\n   * reveal, container `--message-highlighting-color` apply and `applyContainerTheme` (when\n   * applicable). Invoked by `revealPreparedBackground` from `bubbles.setPeer` in the same sync\n   * block as `scrollable.replaceChildren`, so wallpaper flip, theme vars, and bubble mount land\n   * in one paint frame instead of two.\n   *\n   * `undefined` outside a peer change. Same-bg short-circuits store a no-op (still bundled with\n   * theme/hsla apply), so callers can always invoke unconditionally.\n   */\n  private pendingBackgroundReveal: (() => void) | undefined;\n  /**\n   * True when the currently-stored `pendingBackgroundReveal` carries an actual staging-slot\n   * flip (`reveal !== noop`). Same-bg short-circuits in subsequent publishes during the same\n   * peer-change scope must not downgrade a real flip to a noop one — without this flag,\n   * comparing the bundled callbacks against `noop` directly is impossible.\n   */\n  private pendingBackgroundRevealIsReal: boolean;\n  /**\n   * Set true once `revealPreparedBackground` runs. Lets `deferReveal` callbacks that arrive\n   * after the bubbles mount (not-cached wallpaper path) fire their bundled reveal inline\n   * instead of waiting forever in `pendingBackgroundReveal`.\n   */\n  private bubblesRevealCalled: boolean;\n\n  /**\n   * True while this chat is off-screen on mobile (the chat list or profile tab is shown instead\n   * of the chat). A theme/wallpaper that finishes loading in this window must NOT drive the\n   * global background — otherwise opening a chat, then backing out before its theme loads, still\n   * flips the background once the slow load lands. Reset on peer change, re-asserted when the\n   * chat returns on screen (see `setBackgroundHidden`). Driven by the `tab_changing` listener.\n   */\n  private backgroundHidden = false;\n\n  public ignoreSearchCleaning: boolean;\n\n  public stars: Accessor<Long>;\n  public appState: ReturnType<typeof useAppState>[0];\n  public setAppState: ReturnType<typeof useAppState>[1];\n  public appSettings: ReturnType<typeof useAppSettings>[0];\n  public setAppSettings: ReturnType<typeof useAppSettings>[1];\n  public appConfig: ReturnType<typeof useAppConfig>;\n  public peer: ReturnType<typeof usePeer<PeerId>>;\n  public historyStorage: ReturnType<typeof useHistoryStorage>;\n  public historyStorageNoThreadId: ReturnType<typeof useHistoryStorage>;\n  public peerTranslation: ReturnType<typeof usePeerTranslation>;\n  public fullPeer: Accessor<PeerFull>;\n\n  public staticMessages: MyMessage[] = [];\n\n  // public requestHistoryOptionsPart: RequestHistoryOptions;\n\n  constructor(\n    public appImManager: AppImManager,\n    public managers: AppManagers,\n    public isMainChat: boolean,\n    public excludeParts: Partial<{\n      elements: boolean,\n      sharedMedia: boolean\n    }> = {}\n  ) {\n    super();\n\n    this.log = logger('CHAT', LogTypes.Log | LogTypes.Warn | LogTypes.Debug | LogTypes.Error);\n    // this.log = logger('CHAT', LogTypes.Warn | LogTypes.Error);\n    this.log.warn('constructor');\n\n    this.type = ChatType.Chat;\n    this.animationGroup = `chat-${Math.round(Math.random() * 65535)}`;\n    this.middlewareHelper = getMiddleware();\n    this.destroyMiddlewareHelper = getMiddleware();\n\n    if(!this.excludeParts.elements) {\n      this.container = document.createElement('div');\n      this.container.classList.add('chat', 'tabs-tab');\n    }\n\n    this.peerIdSignal = createSignal(this.peerId = NULL_PEER_ID);\n    this.chatPaddingTop = createSignal(0);\n    this.chatPaddingBottom = createSignal(0);\n    this.recomputePaddings();\n\n    this.sharedMediaTabs = [];\n\n    createRoot((dispose) => {\n      this.destroyMiddlewareHelper.onDestroy(dispose);\n      this.stars = useStars();\n      [this.appState, this.setAppState] = useAppState();\n      [this.appSettings, this.setAppSettings] = useAppSettings();\n      this.appConfig = useAppConfig();\n      this.fullPeer = createMemo(() => useFullPeer(this.peerIdSignal[0]())());\n    });\n  }\n\n  public get gradientRenderer(): ChatBackgroundGradientRenderer | undefined {\n    return this.appImManager.appChatBackground.getActiveGradientRenderer();\n  }\n\n  private chatInputSurplusPx = 0;\n  private pinnedFloatingHeightPx = 0;\n  private preservePaddingScrollAbort?: () => void;\n\n  public updateChatInputHeight(surplus: number) {\n    if(this.chatInputSurplusPx === surplus) return;\n    this.preservePaddingScroll();\n    this.chatInputSurplusPx = surplus;\n    this.container.style.setProperty('--chat-input-height-surplus', surplus + 'px');\n    this.recomputePaddings();\n  }\n\n  public updatePinnedFloatingHeight(value: number) {\n    if(this.pinnedFloatingHeightPx === value) return;\n    const delta = value - this.pinnedFloatingHeightPx;\n    this.pinnedFloatingHeightPx = value;\n    const scrollable = this.bubbles?.scrollable;\n    const wasAtEnd = scrollable?.isScrolledToEnd;\n    this.recomputePaddings();\n    // Mobile-faithful (verified against iOS ListView + Android ChatActivity):\n    // leave a mid-scroll position anchored. recomputePaddings grows the\n    // in-scroller paddingTop, and the browser's own scroll anchoring keeps the\n    // visible content put as it grows — so the plate slides in OVER the content\n    // (which scrolls under it) rather than shoving it down. Both mobile clients\n    // do exactly this; neither shifts the history when a top panel appears.\n    // Only re-pin when the chat was glued to the bottom, so the newest message\n    // stays in view — otherwise the grown paddingTop drifts it off the end.\n    if(scrollable && wasAtEnd && delta > 0) {\n      scrollable.setScrollPositionSilently(scrollable.scrollPosition + delta);\n    }\n  }\n\n  private preservePaddingScroll() {\n    if(\n      !this.bubbles ||\n      !this.bubbles.scrollable.isScrolledToEnd/*  ||\n      true */\n    ) return;\n    this.preservePaddingScrollAbort?.();\n    let finished = false;\n    const timeout = setTimeout(() => {\n      finished = true;\n    }, 250);\n    this.preservePaddingScrollAbort = () => {\n      finished = true;\n      clearTimeout(timeout);\n      this.preservePaddingScrollAbort = undefined;\n    };\n    animateSingle(() => {\n      if(finished) {\n        return false;\n      }\n\n      this.bubbles.scrollable.setScrollPositionSilently(99999);\n      return true;\n    }, this.bubbles.scrollable.container);\n\n    // const scrollSaver = this.bubbles.createScrollSaver(false);\n    // scrollSaver.save();\n    // const promise = new Promise<void>((resolve) => setTimeout(resolve, 250));\n    // this.bubbles.animateSomethingWithScroll(promise, scrollSaver);\n  }\n\n  // Hands scroll control to an imminent new-message reveal (renderNewMessage →\n  // scrollToEnd). Otherwise the pin above slams to the absolute bottom every frame\n  // and swallows the reveal animation — most visibly when forwarding a tall message,\n  // where the input helper collapse that triggers the pin coincides with the new bubble.\n  public cancelPreservePaddingScroll() {\n    this.preservePaddingScrollAbort?.();\n  }\n\n  public recomputePaddings() {\n    // const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);\n    const rem = 16;\n    // Main chat reserves 4.5rem above + 4rem below for the floating topbar / pinned-plate\n    // buffer and the chat-input plate. The preview shows neither — only the basic 3rem\n    // topbar — so collapse to topbar-height + 0.5rem (page-chats-padding) on each side.\n    // Handhelds drop those buffers too: the page inset shrinks to 8px so each floating\n    // plate's inner edge sits at 56px (3rem + 0.5rem). Collapse both spacers to sit flush\n    // (= --chat-padding-top / --chat-padding-bottom) instead of the wider desktop gap. Kept\n    // in sync across mobile<->desktop transitions by the 'changeScreen' listener in init().\n    const collapse = this.isPreview || mediaSizes.isMobile;\n    const topBase = collapse ? 3.5 : 4.5;\n    const bottomBase = collapse ? 3.5 : 4;\n    const top = Math.round(topBase * rem + this.pinnedFloatingHeightPx);\n    const bottom = Math.round(bottomBase * rem + this.chatInputSurplusPx);\n    this.chatPaddingTop[1](top);\n    this.chatPaddingBottom[1](bottom);\n    if(this.bubbles?.paddingTop) this.bubbles.paddingTop.style.height = top + 'px';\n    if(this.bubbles?.paddingBottom) this.bubbles.paddingBottom.style.height = bottom + 'px';\n    this.bubbles?.updateStickyIntersectorRootMargin?.();\n  }\n\n  public applyContainerTheme() {\n    if(!this.container) return;\n    const newTheme = this.currentTheme ?? themeController.getTheme();\n    themeController.applyTheme(newTheme, this.container);\n  }\n\n  public publishBackground(\n    transition: ChatBackgroundTransition = 'auto',\n    onCachedStatus?: (cached: boolean) => void,\n    deferReveal?: (reveal: () => void) => void\n  ): Promise<void> {\n    if(this !== this.appImManager.chat || this.backgroundHidden) {\n      onCachedStatus?.(true);\n      deferReveal?.(noop);\n      return Promise.resolve();\n    }\n\n    const finalTransition = this.preferredBackgroundTransition ?? transition;\n    this.preferredBackgroundTransition = undefined;\n\n    // When `deferReveal` is provided, stash the hsla and apply it as part of the bundled\n    // reveal — otherwise `--message-highlighting-color` lands on the container ahead of the\n    // staging-slot flip, and bubbles read the new highlighting color while the old wallpaper\n    // is still on screen.\n    let pendingHsla: string | undefined;\n    const applyPendingHsla = () => {\n      if(pendingHsla === undefined || !this.container) return;\n      themeController.applyHighlightingColor({hsla: pendingHsla, element: this.container});\n    };\n\n    return this.appImManager.appChatBackground.setBackground({\n      theme: this.currentTheme,\n      wallPaper: this.currentWallPaper,\n      transition: finalTransition,\n      onCachedStatus,\n      // Scope the canvas-computed hsla to this chat's container so each chat's\n      // bubbles see *their* highlighting color. Without this, root would carry\n      // the most recently opened chat's value and leak into other chats whose\n      // containers still inherit from `:root`.\n      onHighlightColor: (hsla) => {\n        if(deferReveal) {\n          pendingHsla = hsla;\n          return;\n        }\n        if(this.container) {\n          themeController.applyHighlightingColor({hsla, element: this.container});\n        }\n      },\n      deferReveal: deferReveal ? (slotReveal) => {\n        // Bundle slot flip and hsla apply into one callback — caller invokes them together,\n        // sync with the bubbles mount.\n        deferReveal(() => {\n          slotReveal();\n          applyPendingHsla();\n        });\n      } : undefined\n    });\n  }\n\n  private setBackgroundHidden(hidden: boolean) {\n    if(this.backgroundHidden === hidden) {\n      return;\n    }\n\n    this.backgroundHidden = hidden;\n    // Coming back on screen: re-assert our background. A theme that finished loading while we\n    // were off-screen had its publish suppressed by `publishBackground`'s guard; surface it now.\n    // `setBackground` short-circuits when the background is already current, so this is cheap.\n    if(!hidden && this === this.appImManager.chat && this.peerId) {\n      this.publishBackground('auto');\n    }\n  }\n\n  private _handleBackgrounds() {\n    const log = this.log.bindPrefix('handleBackgrounds');\n    const deferred = deferredPromise<() => void>();\n    // Wipe any leftover reveal from a previous peer change that errored out before\n    // `bubbles.setPeer` reached `revealPreparedBackground`.\n    this.pendingBackgroundReveal = undefined;\n    this.pendingBackgroundRevealIsReal = false;\n    this.bubblesRevealCalled = false;\n\n    const publish = () => {\n      const applyTheme = () => this.applyContainerTheme();\n      // First publish in this peer-change scope owns the staging-slot reveal — it's the one\n      // racing the bubbles mount. Later re-publishes (night toggle, fullPeer details update)\n      // happen well after bubbles are settled, so they reveal inline as before.\n      const isFirstPublish = !deferred.isFulfilled;\n\n      // For not-cached wallpapers, `onCachedStatus(false)` resolves the deferred early with\n      // `applyTheme` so `finishPeerChange` doesn't block on a slow image download — in that\n      // case `applyTheme` runs via `callbacks.forEach` and must not also run in the bundled\n      // reveal (would double-apply the heavy theme computation).\n      let themeOwnedByCallbacks = false;\n\n      const deferRevealCb = isFirstPublish ? (reveal: () => void) => {\n        const isReal = reveal !== noop;\n        // Bundle slot flip + theme apply so wallpaper, theme vars and `--message-highlighting-color`\n        // (set inside `publishBackground`'s wrapped `onHighlightColor` → bundled into `reveal`)\n        // all land in one sync block alongside the bubbles mount.\n        const bundled = themeOwnedByCallbacks ? reveal : () => {\n          reveal();\n          applyTheme();\n        };\n\n        // Late stage: bubbles already mounted (e.g. not-cached wallpaper path where\n        // `onCachedStatus(false)` resolved the deferred and bubbles ran ahead). Fire the\n        // bundled reveal now — the SCSS fade transition still animates the slot in.\n        if(this.bubblesRevealCalled) {\n          bundled();\n          return;\n        }\n\n        // Don't let a same-bg short-circuit (which hands back the `noop` sentinel) downgrade\n        // a real pending reveal from an earlier publish in this peer-change scope.\n        if(!isReal && this.pendingBackgroundRevealIsReal) {\n          return;\n        }\n        this.pendingBackgroundReveal = bundled;\n        this.pendingBackgroundRevealIsReal = isReal;\n      } : undefined;\n\n      const promise = this.publishBackground('auto', (cached) => {\n        if(!cached && !deferred.isFulfilled) {\n          // Cached canvas not ready yet — let `finishPeerChange` proceed without the bundled\n          // reveal (it'll fire late via `bubblesRevealCalled`); apply theme inline so bubbles\n          // mount against the new vars even before the wallpaper fades in.\n          themeOwnedByCallbacks = true;\n          deferred.resolve(applyTheme);\n        }\n      }, deferRevealCb);\n\n      promise.then(() => {\n        if(!deferred.isFulfilled) {\n          // Cached path: wallpaper fully staged. `applyTheme` is bundled into the reveal —\n          // resolve with `noop` so `callbacks.forEach` doesn't apply it ahead of the slot flip.\n          deferred.resolve(noop);\n        } else {\n          // Subsequent publishes (night toggle, peer details change): canvas\n          // already settled, just apply theme inline now that it's painted.\n          applyTheme();\n        }\n      });\n    };\n\n    const getThemeByEmoticon = (emoticon: string) => {\n      if(!emoticon) {\n        return;\n      }\n\n      const {accountThemes} = appState;\n      return accountThemes.themes?.find((theme) => theme.emoticon === emoticon);\n    };\n\n    const update = () => {\n      const _fullPeer = fullPeer();\n      let wallPaper: WallPaper;\n      let theme: Chat['currentTheme'];\n\n      if(_fullPeer) {\n        wallPaper = unwrap((_fullPeer as ChatFull.channelFull).wallpaper);\n        const emoticon = (_fullPeer as ChatFull.channelFull).theme_emoticon ||\n          ((_fullPeer as UserFull.userFull).theme as ChatTheme.chatTheme)?.emoticon ||\n          (wallPaper && wallPaper.settings?.emoticon);\n\n        theme = unwrap(getThemeByEmoticon(emoticon));\n        if(emoticon && theme) {\n          wallPaper = undefined;\n        }\n      }\n\n      this.currentTheme = theme;\n      this.currentWallPaper = wallPaper;\n\n      log('updating', _fullPeer, theme, wallPaper);\n      publish();\n\n      createEffect(on(isNightTheme, update, {defer: true}));\n    };\n\n    const isNightTheme = useIsNightTheme();\n    const fullPeer = useFullPeer(this.peerId);\n    const [appState] = useAppState();\n    createEffect(() => {\n      update();\n    });\n\n    // Defensive: when the global theme toggles (day↔night, accent change),\n    // chatBackground's own listener fires first and replaces props (dropping\n    // our per-chat onHighlightColor). Re-apply the container theme and copy\n    // the freshly-computed highlighting color from :root (where the canvas\n    // already wrote it) onto our container so per-chat bubbles see the new\n    // value instead of the stale cached one.\n    const onThemeChanged = async() => {\n      this.applyContainerTheme();\n      await this.appImManager.appChatBackground.getReadyPromise();\n      if(!this.container) return;\n      const rootHsla = getComputedStyle(document.documentElement).getPropertyValue('--message-highlighting-color').trim();\n      if(rootHsla) {\n        themeController.applyHighlightingColor({hsla: rootHsla, element: this.container});\n      }\n    };\n    rootScope.addEventListener('theme_changed', onThemeChanged);\n    onCleanup(() => rootScope.removeEventListener('theme_changed', onThemeChanged));\n\n    return deferred;\n  }\n\n  /**\n   * Run the pending wallpaper flip + theme apply + `--message-highlighting-color` apply\n   * bundle, if any, synchronously. Called from `bubbles.setPeer` in the same sync block as\n   * `scrollable.replaceChildren` so all chat-visual state lands with the bubbles mount in one\n   * paint frame instead of bleeding the new highlighting/wallpaper onto the old bubbles first.\n   *\n   * Idempotent: clears the pending bundle after invocation. Setting `bubblesRevealCalled`\n   * also flips `_handleBackgrounds` into late-stage mode for any `deferReveal` callback that\n   * arrives afterwards (not-cached wallpaper path).\n   */\n  public revealPreparedBackground() {\n    const reveal = this.pendingBackgroundReveal;\n    this.pendingBackgroundReveal = undefined;\n    this.pendingBackgroundRevealIsReal = false;\n    this.bubblesRevealCalled = true;\n    reveal?.();\n  }\n\n  private handleBackgrounds() {\n    if(this.type === ChatType.Stories || this.isPreview) {\n      return Promise.resolve(noop);\n    }\n\n    return createRoot((dispose) => {\n      this.middlewareHelper.get().onClean(dispose);\n      return this._handleBackgrounds();\n    });\n  }\n\n  public setType(type: ChatType) {\n    this.type = type;\n  }\n\n  public init(/* peerId: PeerId */) {\n    // this.initPeerId = peerId;\n\n    this.topbar = new ChatTopbar(this, appSidebarRight, this.managers);\n    this.bubbles = new ChatBubbles(this, this.managers);\n    this.input = new ChatInput(this, this.appImManager, this.managers, 'chat-input-main');\n    this.contextMenu = new ChatContextMenu(this, this.managers);\n    this.selection = new ChatSelection(this, this.bubbles, this.input, this.managers);\n\n    this.priceChangedInterceptor = new PriceChangedInterceptor({\n      chat: this,\n      listenerSetter: this.bubbles.listenerSetter,\n      managers: this.managers\n    });\n\n    this.topbar.constructUtils();\n    this.topbar.constructPeerHelpers();\n\n    this.topbar.construct();\n    this.input.construct();\n\n    this.bubbles.constructPeerHelpers();\n    this.input.constructPeerHelpers();\n\n    this.priceChangedInterceptor.init();\n\n    if(!IS_TOUCH_SUPPORTED) {\n      this.bubbles.setReactionsHoverListeners();\n    }\n\n    this.bubbles.attachContainerListeners();\n\n    this.bubblesViewport = document.createElement('div');\n    this.bubblesViewport.classList.add('bubbles-viewport', 'disable-hover');\n\n    this.container.append(this.topbar.container, this.bubbles.container, this.bubblesViewport, this.input.chatInput);\n\n    this.bubbles.listenerSetter.add(rootScope)('dialog_migrate', ({migrateFrom, migrateTo}) => {\n      if(this.peerId === migrateFrom) {\n        this.setPeer({peerId: migrateTo});\n      }\n    });\n\n    // Spacer heights depend on the screen (desktop reserves a wider floating-plate buffer\n    // than handheld), so recompute them when crossing the mobile boundary. See recomputePaddings().\n    this.bubbles.listenerSetter.add(mediaSizes)('changeScreen', () => {\n      this.recomputePaddings();\n    });\n\n    if(!this.isPreview) {\n      // Preview popup owns its own lifecycle — these callbacks talk to the main appImManager\n      // and would close the *real* chat behind the popup if the previewed dialog got dropped.\n      this.bubbles.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n        if(dialog.peerId === this.peerId && (isDialog(dialog) || this.threadId === getDialogKey(dialog))) {\n          this.appImManager.setPeer({isDeleting: true});\n        }\n      });\n\n      this.bubbles.listenerSetter.add(rootScope)('monoforum_dialogs_drop', ({ids, parentPeerId}) => {\n        if(parentPeerId === this.peerId && ids.includes(this.monoforumThreadId)) {\n          this.appImManager.setPeer({isDeleting: true});\n        }\n      });\n    }\n\n    this.bubbles.listenerSetter.add(rootScope)('chat_update', async(chatId) => {\n      const {peerId} = this;\n      if(peerId.isAnyChat() && peerId.toChatId() === chatId) {\n        const {\n          starsAmount,\n          isAnonymousSending,\n          canManageDirectMessages\n        } = await namedPromises({\n          starsAmount: this.managers.appChatsManager.getStarsAmount(chatId),\n          isAnonymousSending: this.managers.appMessagesManager.isAnonymousSending(peerId),\n          canManageDirectMessages: this.managers.appPeersManager.canManageDirectMessages(peerId)\n        });\n\n        if(peerId === this.peerId) {\n          this.canManageDirectMessages = canManageDirectMessages;\n          this.isAnonymousSending = isAnonymousSending;\n          this.updateStarsAmount(starsAmount);\n        }\n      }\n    });\n\n    this.bubbles.listenerSetter.add(rootScope)('botforum_pending_topic_created', ({peerId, tempId, newId}) => {\n      if(peerId !== this.peerId || (this.threadId && this.threadId !== tempId)) return;\n\n      !newId && this.input.clearInput();\n\n      this.setPeer({\n        peerId,\n        threadId: newId || tempId,\n        fromTemporaryThread: !!newId\n      });\n    });\n\n\n    const freezeObservers = (freeze: boolean) => {\n      const cb = () => {\n        this.bubbles.observer?.toggleObservingNew(freeze);\n        animationIntersector.toggleIntersectionGroup(this.animationGroup, freeze);\n        if(freeze) {\n          animationIntersector.checkAnimations(freeze, this.animationGroup);\n        }\n      };\n\n      if(!freeze) {\n        setTimeout(() => {\n          cb();\n        }, 400);\n      } else {\n        cb();\n      }\n    };\n\n    this.bubbles.listenerSetter.add(this.appImManager)('chat_changing', ({to}) => {\n      freezeObservers(to !== this);\n    });\n\n    this.bubbles.listenerSetter.add(this.appImManager)('tab_changing', (tabId) => {\n      const offScreenOnMobile = tabId !== APP_TABS.CHAT && mediaSizes.activeScreen === ScreenSize.mobile;\n      freezeObservers(this.appImManager.chat !== this || offScreenOnMobile);\n      this.setBackgroundHidden(offScreenOnMobile);\n    });\n\n    const setInChatQueryDebounced = debounce((query: string) => {\n      this.bubbles.setInChatQuery(query);\n    }, 300, false, true);\n\n    const hasInChatQuery = () => this.type === ChatType.Logs;\n\n    this.searchSignal = createUnifiedSignal();\n    createRoot((dispose) => {\n      this.middlewareHelper.get().onDestroy(dispose);\n\n      const animateElements = async(topbarSearch: HTMLElement, visible: boolean) => {\n        const animate = liteMode.isAvailable('animations')/*  && !this.setPeerPromise */;\n        const keyframes: Keyframe[] = [{opacity: 0}, {opacity: 1}];\n        const options: KeyframeAnimationOptions = {fill: 'forwards', duration: animate ? 200 : 0, easing: 'ease-in-out'};\n        if(!visible) {\n          keyframes.reverse();\n        }\n\n        const elements = this.topbar.container.querySelectorAll<HTMLElement>('.content, .chat-utils');\n\n        const promises: Promise<any>[] = [];\n        const promise = topbarSearch.animate(keyframes, options).finished;\n        keyframes.reverse();\n        const otherPromises = Array.from(elements).map((element) => element.animate(keyframes, options).finished);\n        promises.push(promise, ...otherPromises);\n        return Promise.all(promises);\n      };\n\n      const [needSearch, setNeedSearch] = createSignal(false);\n      const [query, setQuery] = createSignal('', {equals: false});\n      const [filterPeerId, setFilterPeerId] = createSignal<PeerId>(undefined, {equals: false});\n      const [reaction, setReaction] = createSignal<Reaction>(undefined, {equals: false});\n      createEffect<HTMLElement>((topbarSearch) => {\n        if(!needSearch()) {\n          if(!topbarSearch) {\n            return;\n          }\n\n          animateElements(topbarSearch, false).then(() => {\n            topbarSearch.remove();\n          });\n          return;\n        }\n\n        topbarSearch = untrack(() => TopbarSearch({\n          chat: this,\n          chatType: this.type,\n          peerId: this.peerId,\n          // TODO: Check here for monoforumThreadId\n          threadId: this.threadId,\n          canFilterSender: this.type !== ChatType.Logs && this.isAnyGroup,\n          query,\n          filterPeerId,\n          reaction,\n          noList: hasInChatQuery(),\n          onValueChange: hasInChatQuery() ? setInChatQueryDebounced : undefined,\n          onClose: () => {\n            this.searchSignal(undefined);\n            this.bubbles.setInChatQuery('');\n          },\n          onDatePick: this.type === ChatType.Logs ? undefined : (timestamp) => {\n            this.bubbles.onDatePick(timestamp);\n          },\n          onActive: (active, showingReactions, isSmallScreen) => {\n            const className = 'is-search-active';\n            const isActive = !!(active && (showingReactions || isSmallScreen));\n            const wasActive = this.container.classList.contains(className);\n            if(wasActive === isActive) {\n              return;\n            }\n\n            const scrollSaver = this.bubbles.createScrollSaver();\n            scrollSaver.save();\n            this.container.classList.toggle(className, !isSmallScreen && isActive);\n            this.topbar.setFloating();\n            this.topbar.container.classList.toggle('hide-pinned', isSmallScreen);\n            scrollSaver.restore();\n          },\n          onSearchTypeChange: () => {\n            this.ignoreSearchCleaning = true;\n          }\n        })) as HTMLElement;\n        this.topbar.container.append(topbarSearch);\n        animateElements(topbarSearch, true);\n        return topbarSearch;\n      });\n\n      createEffect(() => {\n        const s = this.searchSignal();\n        setQuery(s?.query);\n        setFilterPeerId(s?.filterPeerId);\n        setReaction(s?.reaction);\n        setNeedSearch(!!s);\n      });\n    });\n  }\n\n  public beforeDestroy() {\n    this.destroyPromise = deferredPromise();\n    this.bubbles.cleanup();\n    this.searchSignal?.(undefined);\n  }\n\n  public destroy() {\n    // const perf = performance.now();\n\n    this.destroyPromise?.resolve();\n    this.destroySharedMediaTab();\n    this.topbar?.destroy();\n    this.bubbles?.destroy();\n    this.input?.destroy();\n    this.contextMenu?.destroy();\n    this.selection?.attachListeners(undefined, undefined);\n    this.destroyMiddlewareHelper.destroy();\n    // * The per-peer helper too, not just the destroy-scoped one: the roots hung off it - the\n    // * theme_changed subscription among them - are disposed by its clean/destroy, and nothing else\n    // * ever calls it once the chat is gone. Its listener stayed on rootScope holding this whole\n    // * chat, container and shared-media tabs included, which is how 4 951 detached nodes ended up\n    // * charged to rootScope in a day-old tab. Peer changes keep cleaning it as before.\n    this.middlewareHelper.destroy();\n\n    this.topbar =\n      this.bubbles =\n      this.input =\n      this.contextMenu =\n      this.selection =\n      undefined;\n\n    this.container?.remove();\n\n    this.changeHistoryStorageKey(undefined, undefined);\n\n    // this.log.error('Chat destroy time:', performance.now() - perf);\n  }\n\n  public cleanup(helperToo = true) {\n    this.input?.cleanup(helperToo);\n    this.topbar?.cleanup();\n    this.selection?.cleanup();\n    this.priceChangedInterceptor?.cleanup();\n\n    if(this.ignoreSearchCleaning) this.ignoreSearchCleaning = undefined;\n    else this.searchSignal?.(undefined);\n  }\n\n  public get isForumTopic() {\n    return !!(this.isForum && this.threadId);\n  }\n\n  public get isSensitive() {\n    return isSensitive((this.peer as User.user).restriction_reason || []);\n  }\n\n  public async onChangePeer(options: ChatSetPeerOptions, m: ReturnType<typeof middlewarePromise>) {\n    // spot\n    const {peerId, threadId} = options;\n\n    if(!this.excludeParts.elements) {\n      const searchTab = appSidebarRight.getTab(AppPrivateSearchTab);\n      searchTab?.close();\n    }\n\n    const isForum = apiManagerProxy.isForum(peerId);\n    const isBotforum = apiManagerProxy.isBotforum(peerId);\n    const canManageBotforumTopics = apiManagerProxy.canManageBotforumTopics(peerId);\n\n    if(threadId && !isForum && !isBotforum) {\n      options.type = options.peerId === rootScope.myId ? ChatType.Saved : ChatType.Discussion;\n    }\n\n    if(options.query) {\n      options.type = ChatType.Search;\n    }\n\n    const type = options.type ?? ChatType.Chat;\n    this.setType(type);\n\n    const {\n      noForwards,\n      isRestricted,\n      isLikeGroup,\n      isRealGroup,\n      isMegagroup,\n      isBroadcast,\n      isChannel,\n      isBot,\n      isAnonymousSending,\n      isUserBlocked,\n      isPremiumRequired,\n      starsAmount,\n      chat,\n      canManageDirectMessages\n    } = await m(namedPromises({\n      noForwards: this.managers.appPeersManager.noForwards(peerId),\n      isRestricted: this.managers.appPeersManager.isPeerRestricted(peerId),\n      isLikeGroup: this._isLikeGroup(peerId),\n      isRealGroup: this.managers.appPeersManager.isAnyGroup(peerId),\n      isMegagroup: this.managers.appPeersManager.isMegagroup(peerId),\n      isBroadcast: this.managers.appPeersManager.isBroadcast(peerId),\n      isChannel: this.managers.appPeersManager.isChannel(peerId),\n      isBot: this.managers.appPeersManager.isBot(peerId),\n      isAnonymousSending: this.managers.appMessagesManager.isAnonymousSending(peerId),\n      isUserBlocked: peerId.isUser() && this.managers.appProfileManager.isCachedUserBlocked(peerId),\n      isPremiumRequired: this.isPremiumRequiredToContact(peerId),\n      starsAmount: this.managers.acknowledged.appPeersManager.getStarsAmount(peerId),\n      chat: peerId.isAnyChat() && this.peer as MTChat,\n      canManageDirectMessages: this.managers.appPeersManager.canManageDirectMessages(peerId)\n    }, this.log));\n\n    // ! WARNING: TEMPORARY, HAVE TO GET TOPIC\n    if(isForum && threadId) {\n      await m(this.managers.dialogsStorage.getForumTopicOrReload(peerId, threadId));\n    }\n\n    this.noForwards = noForwards;\n    this.isLikeGroup = isLikeGroup;\n    this.isAnyGroup = isRealGroup;\n    this.isMegagroup = isMegagroup;\n    this.isBroadcast = isBroadcast;\n    this.isChannel = isChannel;\n    this.isBot = isBot;\n    this.isForum = isForum;\n    this.isAllMessagesForum = isForum && !threadId;\n    this.isAnonymousSending = isAnonymousSending;\n    this.isUserBlocked = isUserBlocked;\n    this.isPremiumRequired = isPremiumRequired;\n    this.isMonoforum = !!(chat?._ === 'channel' && chat?.pFlags?.monoforum);\n    this.isBotforum = isBotforum;\n    this.canManageDirectMessages = canManageDirectMessages;\n    this.canManageBotforumTopics = canManageBotforumTopics;\n\n    if(starsAmount.cached) {\n      this.starsAmount = await starsAmount.result;\n    } else {\n      const middleware = this.middlewareHelper.get();\n      starsAmount.result.then((starsAmount) => {\n        if(!middleware()) {\n          return;\n        }\n        this.updateStarsAmount(starsAmount);\n      });\n    }\n\n    this.isRestricted = isRestricted;\n\n    if(this.selection) {\n      this.selection.isScheduled = type === ChatType.Scheduled;\n    }\n\n    // NB: ChatType.Logs also has its own per-peer box (`${peerId}_logs`, via saveLogsMessage), but it's\n    // intentionally NOT mapped here — it stays `_history`. The logs view works through other paths (bubbles\n    // hold the message objects directly, and getMessageByPeer falls back to `… || _logs`), so wiring it to\n    // `_logs` here would need the whole admin-log read path re-verified. If that's ever done, the scheduled\n    // chokepoint in getMessage() can generalize to \"own-peer non-history box\".\n    this.messagesStorageKey = `${this.peerId}_${this.type === ChatType.Scheduled ? 'scheduled' : 'history'}`;\n\n    // this.container && this.container.classList.toggle('no-forwards', this.noForwards);\n\n    if(!this.excludeParts.sharedMedia) {\n      this.sharedMediaTab = appSidebarRight.createSharedMediaTab();\n      this.sharedMediaTabs.push(this.sharedMediaTab);\n      const linkedMonoforumId = (chat?._ === 'channel' && chat.pFlags?.monoforum && chat.linked_monoforum_id)?.toPeerId?.(true);\n      this.sharedMediaTab.setPeer(this.monoforumThreadId || linkedMonoforumId || peerId, threadId);\n    }\n\n    this.input?.clearHelper(); // костыль\n    this.selection?.cleanup(); // TODO: REFACTOR !!!!!!\n  }\n\n  public get requestHistoryOptionsPart(): RequestHistoryOptions {\n    const options: RequestHistoryOptions = {\n      peerId: this.peerId,\n      threadId: this.threadId,\n      monoforumThreadId: this.monoforumThreadId\n    };\n\n    CHAT_SEARCH_KEYS.forEach((key) => {\n      // @ts-ignore\n      options[key] = this[key];\n    });\n\n    if(this.hashtagType && this.hashtagType !== 'this') {\n      options.peerId = NULL_PEER_ID;\n      options.threadId = undefined;\n      options.monoforumThreadId = undefined;\n    }\n\n    return options;\n  }\n\n  public setPeer(options: ChatSetPeerOptions) {\n    const {peerId, threadId, monoforumThreadId, messages, type} = options;\n    if(!peerId) {\n      this.inited = undefined;\n    } else if(!this.inited) {\n      if(this.init) {\n        this.init(/* peerId */);\n        this.init = null;\n      }\n\n      this.inited = true;\n    }\n\n    const samePeer = this.appImManager.isSamePeer(this, options);\n    if(!samePeer) {\n      this.appImManager.dispatchEvent('peer_changing', this);\n      this.peerIdSignal[1](this.peerId = peerId || NULL_PEER_ID);\n      this.threadId = threadId;\n      this.monoforumThreadId = monoforumThreadId;\n      // `onChangePeer` (async) only assigns `isForum` after awaiting the topic reload. Set it\n      // synchronously here too so the `chat_update` listener in bubbles doesn't compare the new\n      // peer against a stale `isForum` mid-transition and reset us to the forum root — which would\n      // drop the threadId when opening a just-created topic in a cold (not-yet-warm) forum.\n      this.isForum = apiManagerProxy.isForum(this.peerId);\n      this.isTemporaryThread = isTempId(threadId);\n      this.noInput = [ChatType.Static, ChatType.Logs].includes(type);\n      this.middlewareHelper.clean();\n      // A fresh peer change always shows the chat next, so its background must publish normally;\n      // the off-screen suppression only guards a stale load from a peer we've already left.\n      this.backgroundHidden = false;\n\n      createRoot((dispose) => {\n        this.middlewareHelper.get().onClean(dispose);\n        this.peer = usePeer(peerId);\n        this.peerTranslation = usePeerTranslation(peerId);\n\n        createEffect(() => {\n          this.autoDownload = useAutoDownloadSettings(this.peer, this.appSettings);\n        });\n      });\n    } else if(this.setPeerPromise && (Date.now() - this.setPeerPromiseStartedAt) < STUCK_SET_PEER_TIMEOUT) {\n      // Deduplicating a peer change that is already in flight is only correct while that change can\n      // still finish. If it never settles, this early return silently swallows every retry and the\n      // chat can never be opened again for the lifetime of the tab. Past the deadline, fall through\n      // and start a fresh change — `bubbles.setPeer` bumps `setPeerTempId`, which invalidates the\n      // abandoned flow.\n      return;\n    }\n\n    this.staticMessages = messages || [];\n\n    if(!peerId) {\n      this.peerIdSignal[1](this.peerId = 0);\n      let promise: Promise<any>;\n\n      if(this === this.appImManager.chat) {\n        this.currentTheme = undefined;\n        this.currentWallPaper = undefined;\n        promise = this.publishBackground('auto');\n      }\n\n      callbackify(promise, () => {\n        appSidebarRight.toggleSidebar(false);\n        this.cleanup(true);\n        this.bubbles.setPeer({peerId, samePeer: false, sameSearch: false});\n        this.appImManager.dispatchEvent('peer_changed', this);\n\n        if(!this.excludeParts.sharedMedia) {\n          appSidebarRight.replaceSharedMediaTab();\n          this.destroySharedMediaTab();\n          this.sharedMediaTab = undefined;\n        }\n      });\n\n      return;\n    }\n\n    this.peerChanged = samePeer;\n\n    let sameSearch = true;\n    if(!samePeer || CHAT_SEARCH_KEYS.some((key) => options.hasOwnProperty(key))) {\n      CHAT_SEARCH_KEYS.forEach((key) => {\n        // @ts-ignore\n        this[key] = options[key];\n      });\n      sameSearch = false;\n    }\n\n    const {requestHistoryOptionsPart} = this;\n    const forKey: Parameters<typeof getHistoryStorageKey>[0] = {\n      type: getHistoryStorageType(requestHistoryOptionsPart),\n      ...requestHistoryOptionsPart\n    };\n    this.changeHistoryStorageKey(\n      getHistoryStorageKey(forKey),\n      getHistoryStorageKey({...forKey, threadId: undefined})\n    );\n\n    if(options.fromTemporaryThread) {\n      return Promise.resolve({\n        cached: true,\n        promise: this.finishPeerChange({\n          peerId,\n          middleware: () => {\n            return this.peerId === peerId && this.threadId === threadId;\n          }\n        })\n      });\n    }\n\n    const bubblesSetPeerPromise = this.bubbles.setPeer({...options, samePeer, sameSearch});\n    this.setPeerPromiseStartedAt = Date.now();\n    const setPeerPromise = this.setPeerPromise = bubblesSetPeerPromise.then((result) => {\n      return result.promise;\n    }).catch(noop).finally(() => {\n      if(this.setPeerPromise === setPeerPromise) {\n        this.setPeerPromise = null;\n      }\n    });\n\n    return bubblesSetPeerPromise;\n  }\n\n  private changeHistoryStorageKey(key: HistoryStorageKey, keyNoThreadId: HistoryStorageKey) {\n    this.disposeHistoryStorage?.();\n    this.disposeHistoryStorage = undefined;\n    if(!key) {\n      return;\n    }\n\n    this.disposeHistoryStorage = createRoot((dispose) => {\n      this.historyStorage = useHistoryStorage(key);\n      this.historyStorageNoThreadId = useHistoryStorage(keyNoThreadId);\n\n      this.managers.appMessagesManager.toggleHistoryKeySubscription(key, true);\n      onCleanup(() => {\n        this.managers.appMessagesManager.toggleHistoryKeySubscription(key, false);\n      });\n\n      return dispose;\n    });\n  }\n\n  public destroySharedMediaTab(tab = this.sharedMediaTab) {\n    if(!tab) {\n      return;\n    }\n\n    indexOfAndSplice(this.sharedMediaTabs, tab);\n    tab.destroy();\n  }\n\n  public setMessageId(options: Partial<Pick<ChatSetPeerOptions,\n    'lastMsgId' | 'lastMsgPeerId' | 'mediaTimestamp' | 'pollOption' | 'highlight' | 'type'\n  > & ChatSearchKeys> = {}) {\n    return this.setPeer({\n      peerId: this.peerId,\n      threadId: this.threadId,\n      monoforumThreadId: this.monoforumThreadId,\n      ...options\n    });\n  }\n\n  public async finishPeerChange(options: {\n    peerId: PeerId,\n    isTarget?: boolean,\n    isJump?: boolean,\n    lastMsgId?: number,\n    startParam?: string,\n    middleware: () => boolean,\n    text?: string,\n    entities?: MessageEntity[]\n  }) {\n    if(this.peerChanged) return;\n\n    const peerId = this.peerId;\n    this.peerChanged = true;\n    this.wasAlreadyUsed = true;\n\n    const {middleware} = options;\n\n    this.cleanup(false);\n\n    const sharedMediaTab = this.sharedMediaTab;\n\n    const callbacksObj = await namedPromises({\n      topbar: this.topbar?.finishPeerChange(options),\n      bubbles: this.bubbles?.finishPeerChange(),\n      input: this.input?.finishPeerChange(options),\n      sharedMedia: sharedMediaTab?.fillProfileElements(),\n      backgrounds: this.handleBackgrounds()\n    }, this.log);\n\n    const callbacks = Object.values(callbacksObj);\n    sharedMediaTab?.loadSidebarMedia(true);\n\n    if(!middleware()) {\n      return;\n    }\n\n    callbacks.forEach((callback) => {\n      callback?.();\n    });\n\n    if(sharedMediaTab) {\n      appSidebarRight.replaceSharedMediaTab(sharedMediaTab);\n      this.sharedMediaTabs.filter((tab) => tab !== sharedMediaTab).forEach((tab) => this.destroySharedMediaTab(tab));\n    }\n\n    if(this.container) {\n      this.container.dataset.type = this.type === ChatType.Search ? 'chat' : this.type;\n      this.container.classList.toggle('can-click-date', [ChatType.Chat, ChatType.Discussion, ChatType.Saved].includes(this.type));\n    }\n\n    this.log.setPrefix('CHAT-' + peerId + '-' + this.type);\n\n    if(this.isMainChat) {\n      this.appImManager.dispatchEvent('peer_changed', this);\n    }\n  }\n\n  public getMessage(mid: number | FullMid) {\n    if(typeof(mid) === 'string') {\n      const {peerId, mid: _mid} = splitFullMid(mid);\n      // scheduled messages live in a separate per-peer storage; resolving a bare id via\n      // getMessageByPeer would hit history/global and return another chat's message, so for\n      // our own scheduled peer read from this chat's (scheduled) storage instead\n      if(this.type === ChatType.Scheduled && peerId === this.peerId) {\n        return apiManagerProxy.getMessageFromStorage(this.messagesStorageKey, _mid);\n      }\n\n      return apiManagerProxy.getMessageByPeer(peerId, _mid);\n    }\n\n    return apiManagerProxy.getMessageFromStorage(this.messagesStorageKey, mid);\n  }\n\n  public getMessageByPeer(peerId: PeerId, mid: number) {\n    if(!this.query) {\n      return this.getMessage(mid);\n    }\n\n    return apiManagerProxy.getMessageByPeer(peerId, mid);\n  }\n\n  public async getMidsByMid(peerId: PeerId, mid: number) {\n    return this.managers.appMessagesManager.getMidsByMessage(this.getMessageByPeer(peerId, mid));\n  }\n\n  public getHistoryStorage(ignoreThreadId?: boolean) {\n    return ignoreThreadId ? this.historyStorageNoThreadId : this.historyStorage;\n    // return useHistoryStorage(ignoreThreadId ? this.historyStorageKeyNoThreadId : this.historyStorageKey);\n    // return this.managers.appMessagesManager.getHistoryStorageTransferable({\n    //   ...this.requestHistoryOptionsPart,\n    //   threadId: ignoreThreadId ? undefined : this.threadId\n    // }).then((historyStorageTransferable) => {\n    //   return {\n    //     ...historyStorageTransferable,\n    //     history: SlicedArray.fromJSON<number>(historyStorageTransferable.historySerialized),\n    //     searchHistory: historyStorageTransferable.searchHistorySerialized && SlicedArray.fromJSON<string>(historyStorageTransferable.searchHistorySerialized)\n    //   };\n    // });\n  }\n\n  public hasMessages() {\n    const {history} = this.getHistoryStorage(true);\n    return !!history.length;\n  }\n\n  public getDialogOrTopic() {\n    return this.managers.dialogsStorage.getAnyDialog(this.peerId, (this.isForum || this.type === ChatType.Saved) && this.threadId);\n  }\n\n  public getHistoryMaxId() {\n    return this.getHistoryStorage().maxId;\n  }\n\n  // * used to define need of avatars\n  public async _isLikeGroup(peerId: PeerId) {\n    if(peerId === rootScope.myId) return true;\n    if(peerId === REPLIES_PEER_ID) return true;\n    if(this.type === ChatType.Search && this.hashtagType !== 'this') return true;\n    if(this.type === ChatType.Logs) return true;\n\n    const {isBotforum, isLikeGroup} = await namedPromises({\n      isLikeGroup: this.managers.appPeersManager.isLikeGroup(peerId),\n      isBotforum: this.managers.appPeersManager.isBotforum(peerId)\n    });\n\n    return !isBotforum && isLikeGroup;\n  }\n\n  public resetSearch() {\n    this.searchSignal?.(undefined);\n  }\n\n  public initSearch(options: {query?: string, filterPeerId?: PeerId, reaction?: Reaction, focus?: boolean} = {}): void {\n    if(!this.peerId) return;\n    options.query ||= '';\n    this.searchSignal(options);\n    if(options.focus) {\n      focusSearchInput(this.topbar.container);\n    }\n  }\n\n  public canSend(action?: ChatRights) {\n    if(isVerificationBot(this.peerId)) return Promise.resolve(false);\n    if(this.type === ChatType.Saved && this.threadId !== this.peerId) {\n      return Promise.resolve(false);\n    }\n\n    return this.managers.appMessagesManager.canSendToPeer(this.peerId, this.threadId, action);\n  }\n\n  public isStartButtonNeeded() {\n    return Promise.all([\n      this.managers.appPeersManager.isBot(this.peerId),\n      this.managers.appMessagesManager.getDialogOnly(this.peerId),\n      this.getHistoryStorage(true),\n      this.peerId.isUser() ? this.managers.appProfileManager.isCachedUserBlocked(this.peerId.toUserId()) : undefined,\n      this.managers.appPeersManager.isBotforum(this.peerId)\n    ]).then(([isBot, dialog, historyStorage, isUserBlocked, isBotforum]) => {\n      if(!isBot || isVerificationBot(this.peerId) || isBotforum) {\n        return false;\n      }\n\n      return (!dialog && !historyStorage.history.length) || isUserBlocked;\n    });\n  }\n\n  public isPremiumRequiredToContact(peerId = this.peerId) {\n    if(!peerId.isUser()) {\n      return Promise.resolve(false);\n    }\n\n    return this.managers.appUsersManager.getRequirementToContact(peerId.toUserId(), true)\n    .then((requirement) => requirement?._ === 'requirementToContactPremium');\n  }\n\n  public getMessageSendingParams(): MessageSendingParams {\n    return {\n      peerId: this.peerId,\n      threadId: this.threadId,\n      updateStickersetOrder: this.appSettings.stickers.dynamicPackOrder,\n      ...(this.input && {\n        ...(this.input.getReplyTo() || false),\n        ...(this.input.suggestedPost ? {\n          replyToMsgId: this.input.suggestedPost.changeMid\n        } : {}),\n        scheduleDate: this.input.scheduleDate,\n        scheduleRepeatPeriod: this.input.scheduleRepeatPeriod,\n        silent: this.input.sendSilent,\n        sendAsPeerId: this.input.sendAsPeerId,\n        effect: this.input.effect(),\n        suggestedPost: this.input.suggestedPost,\n        ...this.input.getEphemeralSendingParams()\n      }),\n      replyToMonoforumPeerId: this.input?.suggestedPost?.monoforumThreadId || this.input?.getReplyTo()?.replyToMonoforumPeerId || this.monoforumThreadId,\n      savedReaction: this.savedReaction\n    };\n  }\n\n  public isOurMessage(message: Message.message | Message.messageService) {\n    if(this.isMegagroup) {\n      return !!message.pFlags.out;\n    }\n\n    if(message.fromId === rootScope.myId && !message.pFlags.post) {\n      return true;\n    }\n\n    if((message as Message.message).fwd_from?.pFlags?.saved_out) {\n      return true;\n      // const peer = apiManagerProxy.getPeer((message as Message.message).fwdFromId);\n      // return !(peer as MTChat.channel)?.pFlags?.broadcast;\n    }\n\n    return false;\n  }\n\n  public isOutMessage(message: Message.message | Message.messageService) {\n    const fwdFrom = (message as Message.message).fwd_from;\n    const isOut = this.isOurMessage(message) && (!fwdFrom || this.peerId !== rootScope.myId || this.threadId);\n    return !!isOut;\n  }\n\n  public isPinnedMessagesNeeded() {\n    // A forum topic (and the view-as-messages mode) is a `Chat` like any other,\n    // so the type alone decides. The old `|| this.isForum` also matched a\n    // forum's Pinned / Scheduled / Search tabs — which grew `Static` / `Logs`\n    // exclusions one at a time and still put a pinned plate inside the forum's\n    // own pinned-messages list, where no other peer has one.\n    return this.type === ChatType.Chat;\n  }\n\n  public isForwardOfForward(message: Message) {\n    // return isForwardOfForward(message);\n    let is = isForwardOfForward(message);\n    const fwdFrom = (message as Message.message).fwd_from;\n    if(\n      is &&\n      fwdFrom.saved_from_id &&\n      this.type === ChatType.Saved ? getPeerId(fwdFrom.saved_from_id) === this.threadId : false\n      // getPeerId(fwdFrom.saved_from_id) === (this.type === ChatType.Saved ? this.threadId : this.peerId)\n    ) {\n      is = false;\n    }\n\n    return is;\n  }\n\n  public getPostAuthor(message: Message.message) {\n    if(this.isLikeGroup) {\n      return;\n    }\n\n    const fwdFrom = message.fwd_from;\n    const isPost = !!(message.pFlags.post || (fwdFrom?.post_author && !this.isOutMessage(message)));\n    if(!isPost) {\n      return;\n    }\n\n    // if(isForwardOfForward(message) && !message.post_author) {\n    //   return;\n    // }\n\n    // return message.post_author || (fwdFrom && (this.type !== ChatType.Saved || message.fwdFromId !== this.threadId) && fwdFrom.post_author);\n    return message.post_author || fwdFrom?.post_author;\n  }\n\n  public async canGiftPremium() {\n    const peerId = this.peerId;\n    if(!peerId.isUser()) {\n      return false;\n    }\n\n    const [canGiftPremium, isPremiumPurchaseBlocked] = await Promise.all([\n      this.managers.appProfileManager.canGiftPremium(this.peerId.toUserId()),\n      apiManagerProxy.isPremiumPurchaseBlocked()\n    ]);\n\n    return peerId.isUser() && canGiftPremium && !isPremiumPurchaseBlocked;\n  }\n\n  public async openWebApp(options: Partial<RequestWebViewOptions>) {\n    Object.assign(options, this.getMessageSendingParams());\n    options.peerId ??= this.peerId;\n    return this.appImManager.openWebApp(options);\n  }\n\n  public async sendReaction(options: SendReactionOptions) {\n    const isPaidReaction = options.reaction._ === 'reactionPaid';\n    const count = options.count ?? 1;\n    if(isPaidReaction) {\n      const key = getPendingPaidReactionKey(options.message as Message.message);\n      let pending = PENDING_PAID_REACTIONS.get(key);\n      const hadPending = !!pending;\n      const requiredStars = (pending ? pending.count() : 0) + count;\n      if(+this.stars() < requiredStars) {\n        if(pending) {\n          pending.abortController.abort();\n        }\n\n        PopupElement.createPopup(PopupStars, {\n          itemPrice: count,\n          onTopup: () => {\n            this.sendReaction(options);\n          },\n          purpose: 'reaction',\n          peerId: this.peerId,\n          spendPurposePeerId: this.peerId\n        });\n\n        return;\n      }\n\n      if(!pending) {\n        const [count, setCount] = createSignal(0);\n        const [sendTime, setSendTime] = createSignal(0);\n        const abortController = new AbortController();\n        abortController.signal.addEventListener('abort', () => {\n          clearTimeout(pending.sendTimeout);\n          pending.setSendTime(0);\n          PENDING_PAID_REACTIONS.delete(key);\n\n          if(abortController.signal.reason !== PENDING_PAID_REACTION_SENT_ABORT_REASON) {\n            setReservedStars((reservedStars) => reservedStars - pending.count());\n          }\n\n          rootScope.dispatchEventSingle('messages_reactions', [{\n            message: this.getMessageByPeer(options.message.peerId, options.message.mid) as Message.message,\n            changedResults: [],\n            removedResults: []\n          }]);\n        });\n\n        PENDING_PAID_REACTIONS.set(key, pending = {\n          count,\n          setCount,\n          sendTime,\n          setSendTime,\n          sendTimeout: 0,\n          abortController\n        });\n      } else {\n        clearTimeout(pending.sendTimeout);\n      }\n\n      pending.setCount((_count) => _count + count);\n      pending.setSendTime(Date.now() + SEND_PAID_WITH_STARS_DELAY);\n      pending.sendTimeout = window.setTimeout(() => {\n        const count = pending.count();\n        pending.abortController.abort(PENDING_PAID_REACTION_SENT_ABORT_REASON);\n        this.managers.appReactionsManager.sendReaction({\n          ...options,\n          count\n        });\n      }, SEND_PAID_WITH_STARS_DELAY);\n\n      setReservedStars((reservedStars) => reservedStars + count);\n\n      if(!hadPending) {\n        showUndoablePaidTooltip({\n          titleCount: pending.count,\n          subtitleCount: pending.count,\n          sendTime: pending.sendTime,\n          onUndo: () => void pending.abortController.abort(),\n          ...paidReactionLangKeys\n        });\n      }\n    }\n\n    const messageReactions = await this.managers.appReactionsManager.sendReaction({\n      ...options,\n      count: isPaidReaction ? 0 : count,\n      onlyReturn: isPaidReaction\n    });\n\n    if(isPaidReaction) {\n      const {message} = options;\n      message.reactions = messageReactions;\n      rootScope.dispatchEventSingle('messages_reactions', [{\n        message: message as Message.message,\n        changedResults: [messageReactions.results[0]],\n        removedResults: []\n      }]);\n    }\n  }\n\n  public updateStarsAmount(starsAmount: number) {\n    this.starsAmount = starsAmount;\n    this.input.setStarsAmount(starsAmount);\n    getCurrentNewMediaPopup()?.setStarsAmount(starsAmount);\n  }\n\n  public async getAutoDeletePeriod(): Promise<AckedResult<number>> {\n    try {\n      const dialog = await this.managers.dialogsStorage.getDialogOnly(this.peerId);\n      if(dialog) return {\n        cached: true,\n        result: Promise.resolve(dialog.ttl_period)\n      };\n\n      const fullPeer = this.peerId.isUser() ?\n        await this.managers.acknowledged.appProfileManager.getProfile(this.peerId.toUserId()) :\n        await this.managers.acknowledged.appProfileManager.getChatFull(this.peerId.toChatId());\n\n      return {\n        cached: fullPeer.cached,\n        result: fullPeer.result.then((fullPeer) => {\n          return 'ttl_period' in fullPeer ? fullPeer.ttl_period : undefined;\n        })\n      }\n    } catch{\n      return {\n        cached: true,\n        result: Promise.resolve(0)\n      };\n    }\n  }\n\n  public async openAutoDeleteMessagesCustomTimePopup() {\n    const {\n      popup: {default: AutoDeleteMessagesCustomTimePopup},\n      autoDeletePeriod\n    } = await namedPromises({\n      popup: import('../sidebarLeft/tabs/autoDeleteMessages/customTimePopup'),\n      autoDeletePeriod: this.getAutoDeletePeriod().then(ackedResult => ackedResult.result)\n    });\n\n    new AutoDeleteMessagesCustomTimePopup({\n      HotReloadGuard: SolidJSHotReloadGuardProvider,\n      descriptionLangKey: this.isBroadcast ? 'AutoDeleteMessages.InfoChannel' : 'AutoDeleteMessages.InfoChat',\n      period: autoDeletePeriod,\n      onFinish: (period) => {\n        this.managers.appPrivacyManager.setAutoDeletePeriodFor(this.peerId, period);\n      }\n    }).show();\n  }\n\n  public canManageAutoDelete = async() => {\n    const specialChats = [REPLIES_PEER_ID, REPLIES_HIDDEN_CHANNEL_ID.toPeerId(), VERIFICATION_CODES_BOT_ID, HIDDEN_PEER_ID, SERVICE_PEER_ID, rootScope.myId];\n    if(specialChats.includes(this.peerId)) return false;\n\n    if(this.peerId.isUser()) return true;\n\n    const {chat, isMonoforum}  = await namedPromises({\n      chat: this.managers.appChatsManager.getChat(this.peerId.toChatId()),\n      isMonoforum: this.managers.appChatsManager.isMonoforum(this.peerId.toChatId())\n    });\n\n    return !isMonoforum && hasRights(chat, 'change_info');\n  }\n\n  public toggleChatIfMedium() {\n    if(mediaSizes.activeScreen === ScreenSize.medium && document.body.classList.contains(LEFT_COLUMN_ACTIVE_CLASSNAME)) {\n      this.appImManager.setPeer({peerId: this.peerId});\n      return true;\n    }\n\n    return false;\n  }\n\n  public pop() {\n    if(this.toggleChatIfMedium()) return;\n\n    const isFirstChat = this.appImManager.chats.indexOf(this) === 0;\n    appNavigationController.back(isFirstChat ? 'im' : 'chat');\n  }\n\n  /**\n   * returns false if this is the only chat\n   */\n  public popIfMoreThanOne() {\n    if(this.toggleChatIfMedium()) return true;\n\n    const isFirstChat = this.appImManager.chats.indexOf(this) === 0;\n    if(isFirstChat) return false;\n\n    appNavigationController.back('chat');\n    return true;\n  }\n}\n","import {createEffect, createMemo, createSignal, JSX, onCleanup, onMount, untrack, useContext} from 'solid-js';\nimport {unwrap} from 'solid-js/store';\nimport {ChatFull, ChatTheme, UserFull, WallPaper} from '@layer';\nimport PopupElement, {createPopup, PopupContext} from '@components/popups/indexTsx';\nimport Chat from '@components/chat/chat';\nimport {ChatBackground, ChatBackgroundTheme} from '@components/chat/bubbles/chatBackground';\nimport {ChatType} from '@components/chat/chatType';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport themeController from '@helpers/themeController';\nimport mediaSizes from '@helpers/mediaSizes';\nimport {bindActiveWindowListener, getAppWindow, onAppWindowChange} from '@helpers/appWindow';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {useFullPeer} from '@stores/fullPeers';\nimport {appState} from '@stores/appState';\nimport useIsNightTheme from '@hooks/useIsNightTheme';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport ListenerSetter from '@helpers/listenerSetter';\n\nexport type ChatPreviewAnchor = HTMLElement | {x: number, y: number} | {\n  x: number, y: number, left: number, right: number, top: number, bottom: number\n};\n\nexport type ChatPreviewOptions = {\n  peerId: PeerId,\n  threadId?: number,\n  monoforumThreadId?: number,\n  lastMsgId?: number,\n  anchor?: ChatPreviewAnchor\n};\n\n/**\n * Build a preview anchor from a dialog row. Anchors to the LEFT COLUMN's right edge\n * (instead of the row's own right edge) so the 8px gap from the sidebar is constant\n * regardless of the row's internal padding. Shared by Shift+Click and the context-menu\n * \"Preview\" entry — both want the popup pinned the same way.\n */\nexport function chatPreviewAnchorFromDialogRow(li: HTMLElement): ChatPreviewAnchor {\n  const rect = li.getBoundingClientRect();\n  const columnEl = li.closest<HTMLElement>('#column-left, .sidebar-left');\n  const columnRight = columnEl?.getBoundingClientRect().right ?? rect.right;\n  return {\n    x: columnRight,\n    y: rect.top + rect.height / 2,\n    left: rect.left,\n    right: columnRight,\n    top: rect.top,\n    bottom: rect.bottom\n  };\n}\n\nexport const CHAT_PREVIEW_POPUP_KIND = Symbol('chat-preview-popup');\n\nconst PREVIEW_W = 432;\nconst PREVIEW_H = 540;\nconst MARGIN = 8;\n\nexport default function showChatPreviewPopup(options: ChatPreviewOptions): void {\n  if(!options.peerId || options.peerId === NULL_PEER_ID) return;\n\n  // Shift+clicking through several dialogs in a row should swap the preview, not stack them.\n  PopupElement.getPopups(CHAT_PREVIEW_POPUP_KIND).forEach((p) => p.hide());\n\n  const [show, setShow] = createSignal(true);\n  const handle = {hide: () => setShow(false)};\n\n  let containerEl!: HTMLDivElement;\n  // Held in outer scope so `onClose` (fires before the 250ms close animation) can call\n  // `chat.beforeDestroy()` while `onCleanup` (fires after the animation, inside Inner) does\n  // the full teardown.\n  let chatRef: Chat | undefined;\n\n  function Inner() {\n    const context = useContext(PopupContext);\n    const middleware = untrack(() => context.middlewareHelper).get();\n    const managers = untrack(() => context.managers);\n    const listenerSetter = new ListenerSetter();\n\n    let disposeResize: () => void, disposeWindowChange: () => void;\n\n    const chat = new Chat(appImManager, managers, false, {sharedMedia: true});\n    chat.isPreview = true;\n    chat.isStandalone = true;\n    chat.onPreviewClose = () => handle.hide();\n    chat.setType(ChatType.Chat);\n    // `recomputePaddings` runs in the Chat constructor with the default (main-chat)\n    // padding budget. Now that `isPreview` is set, redo the math so `bubbles-padding-top`\n    // collapses from 4.5rem to 3.5rem (only the basic topbar, no pinned/floating plates).\n    chat.recomputePaddings();\n    chat.container.classList.add('chat-preview', 'active');\n    chatRef = chat;\n\n    // Resolve the peer's wallpaper + theme reactively, mirroring `Chat._handleBackgrounds`.\n    // `<ChatBackground peerId>` only consults the *cached* full-user — for a peer not yet\n    // fetched (or a chat/channel with a `theme_emoticon`) it returns {} and we'd render\n    // the global wallpaper forever. `useFullPeer` triggers a fetch on first read and\n    // re-fires the createMemo when the full peer lands, so the popup picks up the proper\n    // wallpaper as soon as it's loaded.\n    const fullPeer = useFullPeer(options.peerId);\n    const resolvedBg = createMemo(() => {\n      const _fullPeer = fullPeer();\n      let wallPaper: WallPaper | undefined;\n      let theme: ChatBackgroundTheme | undefined;\n\n      if(_fullPeer) {\n        wallPaper = unwrap((_fullPeer as ChatFull.channelFull).wallpaper);\n        const emoticon = (_fullPeer as ChatFull.channelFull).theme_emoticon ||\n          ((_fullPeer as UserFull.userFull).theme as ChatTheme.chatTheme)?.emoticon ||\n          (wallPaper && wallPaper.settings?.emoticon);\n        const found = emoticon && appState.accountThemes?.themes?.find((t) => t.emoticon === emoticon);\n        theme = found ? unwrap(found) : undefined;\n        // A theme picked by emoticon brings its own wallpaper; the per-peer override\n        // shouldn't compete with it.\n        if(emoticon && theme) wallPaper = undefined;\n      }\n\n      return {theme, wallPaper};\n    });\n\n    // A preview Chat has `isPreview`, so `Chat.handleBackgrounds()` short-circuits and never runs\n    // `applyContainerTheme` — the per-chat theme's outgoing-bubble vars (`--message-out-*`) are thus\n    // missing on the container and outgoing bubbles fall back to the global :root palette. Mirror the\n    // main chat: stash the resolved theme on the chat and apply it to its container. `isNight()` keeps\n    // the effect re-firing on a day/night toggle while the preview is open so the theme re-resolves to\n    // the right variant — the same role `useIsNightTheme` plays in `Chat._handleBackgrounds`.\n    const isNight = useIsNightTheme();\n    createEffect(() => {\n      isNight();\n      chat.currentTheme = resolvedBg().theme;\n      chat.applyContainerTheme();\n    });\n\n    onMount(() => {\n      positionFromAnchor(options.anchor);\n\n      // setPeer triggers Chat.init() synchronously on the first call, which builds the\n      // ChatInput tree (including the chat-input-control plate). After this returns the\n      // plate exists; injecting now wires up our button into the centre slot before any\n      // visible paint. The finish-peer-change pass later runs `finishPeerChange` which can\n      // un-hide built-in buttons (botStart, joinBtn, …) — `keepOnlyOurButton` re-hides them\n      // every time the plate's child list mutates so ours stays the only visible one.\n      chat.setPeer({\n        peerId: options.peerId,\n        threadId: options.threadId,\n        monoforumThreadId: options.monoforumThreadId,\n        lastMsgId: options.lastMsgId\n      });\n\n      injectMarkUnreadButton();\n\n      // Viewport resize moves the anchored dialog row underneath us — the popup was\n      // positioned for the old layout and would float over the wrong target. Close instead\n      // of trying to re-anchor; the user can Shift+Click again in the new layout. While the\n      // client is popped into a Document PiP window the resize fires on THAT window, so\n      // follow the active window rather than pinning the tab. Popping in/out of PiP itself\n      // jumps the anchored row to a different-sized window — close on that too.\n      disposeResize = bindActiveWindowListener((w) => w, 'resize', () => handle.hide());\n      disposeWindowChange = onAppWindowChange(() => handle.hide());\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n      disposeResize?.();\n      disposeWindowChange?.();\n      chat.destroy();\n      chatRef = undefined;\n    });\n\n    function positionFromAnchor(anchor: ChatPreviewAnchor) {\n      if(!anchor) return;\n      let ax: number, ay: number, rectLeft: number;\n      if(anchor instanceof HTMLElement) {\n        const r = anchor.getBoundingClientRect();\n        ax = r.right;\n        ay = r.top + r.height / 2;\n        rectLeft = r.left;\n      } else if('left' in anchor) {\n        ax = anchor.right;\n        ay = anchor.y;\n        rectLeft = anchor.left;\n      } else {\n        ax = anchor.x;\n        ay = anchor.y;\n        rectLeft = anchor.x;\n      }\n\n      // Read the viewport from the active app window — while popped into a Document PiP\n      // window the popup (and the anchored dialog row whose rect was measured against that\n      // same viewport) lives in the PiP window, so the tab's `window.innerWidth/Height`\n      // would clamp/centre against the wrong (background) size and throw the popup off-anchor.\n      const appWindow = getAppWindow();\n      const vw = appWindow.innerWidth || appWindow.document.documentElement.clientWidth;\n      const vh = appWindow.innerHeight || appWindow.document.documentElement.clientHeight;\n\n      // The popup defaults to a fixed 432×540, but on a handheld viewport that's wider\n      // and/or taller than the screen. Shrink it to fit (leaving a MARGIN gutter on each\n      // side) and expose the result as CSS vars the stylesheet reads. A non-positive\n      // measurement (headless/jsdom) keeps the natural size — `vw - MARGIN * 2` would go\n      // negative and collapse the popup.\n      const width = vw > MARGIN * 2 ? Math.min(PREVIEW_W, vw - MARGIN * 2) : PREVIEW_W;\n      const height = vh > MARGIN * 2 ? Math.min(PREVIEW_H, vh - MARGIN * 2) : PREVIEW_H;\n      containerEl.style.setProperty('--preview-width', width + 'px');\n      containerEl.style.setProperty('--preview-height', height + 'px');\n\n      let left: number, top: number;\n      if(mediaSizes.isMobile) {\n        // On a handheld the left column — and thus the anchor — spans the full width, so\n        // there's nowhere to sit the popup beside the row. Centre it in the viewport on\n        // both axes rather than tracking the anchor (which would leave it floating at a\n        // different height for every row). `width`/`height` are already fitted, so the\n        // gutters come out symmetric; `Math.max` pins it at MARGIN if it can't fit.\n        left = Math.max(MARGIN, (vw - width) / 2);\n        top = Math.max(MARGIN, (vh - height) / 2);\n      } else {\n        left = ax + MARGIN;\n        top = ay - height / 2;\n\n        // Keep the popup fully on-screen, clamping against the *fitted* size. Headless/\n        // zero-size measurements fall through to the natural anchor offset instead of\n        // collapsing to a negative coordinate.\n        const maxLeft = vw > MARGIN * 2 ? vw - width - MARGIN : Infinity;\n        const maxTop = vh > MARGIN * 2 ? vh - height - MARGIN : Infinity;\n        if(left > maxLeft) {\n          const fromLeft = rectLeft - width - MARGIN;\n          left = Math.max(MARGIN, fromLeft);\n        }\n        if(top < MARGIN) top = MARGIN;\n        if(top > maxTop) top = maxTop;\n      }\n\n      containerEl.style.setProperty('--preview-left', left + 'px');\n      containerEl.style.setProperty('--preview-top', top + 'px');\n    }\n\n    /**\n     * Append a Mark-as-Read / Mark-as-Unread button to the chat-input-control plate. Reuses\n     * the same `.chat-input-plate-button` look the existing control buttons (Join, Unblock,\n     * Bot Start, …) get. The built-in buttons get hidden — for some preview peers (bots,\n     * blocked users, unjoined channels) `finishPeerChange` would otherwise un-hide one of\n     * them and we'd end up with two visible buttons in the plate.\n     */\n    function injectMarkUnreadButton() {\n      const plateCenter = chat.container.querySelector('.chat-input-control .chat-input-plate-center');\n      if(!plateCenter) return;\n\n      const btn = document.createElement('button');\n      btn.type = 'button';\n      btn.classList.add('btn-primary', 'btn-transparent', 'text-bold', 'chat-input-control-button', 'chat-input-plate-button');\n      plateCenter.append(btn);\n\n      // ChatInput's `finishPeerChange` toggles built-in buttons (botStart, join, unblock, …)\n      // every time the peer changes — and it runs *after* this synchronous inject. Re-hide\n      // those siblings every time the plate's class list mutates so our button stays the\n      // only visible one.\n      const keepOnlyOurButton = () => {\n        plateCenter.querySelectorAll<HTMLElement>(':scope > button').forEach((b) => {\n          if(b !== btn && !b.classList.contains('hide')) b.classList.add('hide');\n        });\n      };\n      keepOnlyOurButton();\n      const observer = new MutationObserver(keepOnlyOurButton);\n      observer.observe(plateCenter, {attributes: true, attributeFilter: ['class'], subtree: true, childList: true});\n      middleware.onDestroy(() => observer.disconnect());\n\n      const setLabel = (key: LangPackKey) => replaceContent(btn, i18n(key));\n      setLabel('MarkAsRead'); // placeholder until we resolve the actual state\n\n      const refresh = async() => {\n        const dialog = await getDialog();\n        if(!dialog || !middleware()) return;\n        const unread = await managers.appMessagesManager.isDialogUnread(dialog);\n        if(!middleware()) return;\n        setLabel(unread ? 'MarkAsRead' : 'MarkAsUnread');\n      };\n      refresh();\n\n      // Keep the label in sync with state mutations performed elsewhere (other client, this\n      // very button, etc.). `subscribeOn` cleans up automatically when the popup disposes.\n      subscribeOn(rootScope)('dialog_unread', (payload: {peerId: PeerId}) => {\n        if(payload.peerId === options.peerId) refresh();\n      });\n      subscribeOn(rootScope)('dialogs_multiupdate', refresh);\n\n      attachClickEvent(btn, async() => {\n        const dialog = await getDialog();\n        if(!dialog) return;\n        const isUnread = await managers.appMessagesManager.isDialogUnread(dialog);\n        // Same branching as `DialogsContextMenu.onUnreadClick` — keeps mono-forum, thread and\n        // regular dialogs behaving consistently with the rest of the app.\n        if(options.monoforumThreadId) {\n          managers.appMessagesManager.markDialogUnread({\n            peerId: options.peerId,\n            monoforumThreadId: options.monoforumThreadId,\n            read: isUnread\n          });\n        } else if(isUnread) {\n          if(!options.threadId) {\n            managers.appMessagesManager.markDialogUnread({peerId: options.peerId, read: true});\n          } else {\n            const topMessage = (dialog as any).top_message;\n            if(topMessage) {\n              managers.appMessagesManager.readHistory({peerId: options.peerId, maxId: topMessage, threadId: options.threadId});\n            }\n          }\n        } else if(!options.threadId) {\n          managers.appMessagesManager.markDialogUnread({peerId: options.peerId});\n        }\n      }, {listenerSetter});\n    }\n\n    function getDialog() {\n      return managers.dialogsStorage.getAnyDialog(\n        options.peerId,\n        (options.threadId || options.monoforumThreadId) ?? undefined\n      );\n    }\n\n    return (\n      <div class=\"chat-preview-wrapper\">\n        <div class=\"chat-preview-bg\">\n          <ChatBackground\n            theme={resolvedBg().theme}\n            wallPaper={resolvedBg().wallPaper}\n            // `auto` => first render with the cached global theme is instant (no flicker on\n            // open), and the second render — once `useFullPeer` delivers the peer's custom\n            // wallpaper — fades in over 200ms instead of snapping in a single frame.\n            transition=\"auto\"\n            width={PREVIEW_W}\n            height={PREVIEW_H}\n            onHighlightColor={(hsla) => {\n              if(chat?.container) {\n                themeController.applyHighlightingColor({hsla, element: chat.container});\n              }\n            }}\n          />\n        </div>\n        {chat.container}\n      </div>\n    );\n  }\n\n  // On desktop the preview is a tdesktop-style peek anchored next to the chatlist, so it\n  // deliberately skips the dimmed overlay. On a handheld it's a centred modal instead —\n  // bring the standard overlay back, otherwise the popup floats over the chat list with no\n  // backdrop and reads as misplaced.\n  createPopup(() => (\n    <PopupElement\n      class=\"popup-chat-preview\"\n      withoutOverlay={!mediaSizes.isMobile}\n      show={show()}\n      kind={CHAT_PREVIEW_POPUP_KIND}\n      containerProps={{ref: (el: HTMLDivElement) => containerEl = el}}\n      onClose={() => chatRef?.beforeDestroy()}\n    >\n      <Inner />\n    </PopupElement>\n  ));\n}\n","import hasRights from '@appManagers/utils/chats/hasRights';\nimport type {Chat, User} from '@layer';\n\nexport default function canRemoveCommunityPeer(\n  community: Chat,\n  peer: Chat | User\n) {\n  if(\n    community?._ === 'community' &&\n    hasRights(community, 'manage_linked_peers')\n  ) {\n    return true;\n  }\n\n  if(peer?._ === 'user') {\n    return false;\n  }\n\n  return (\n    peer?._ === 'chat' ||\n    peer?._ === 'channel'\n  ) && !!peer.pFlags.creator;\n}\n","import confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport type {AppManagers} from '@lib/managers';\nimport type {Chat} from '@layer';\n\nexport function canLeaveCommunity(community: Chat) {\n  return community?._ === 'community' &&\n    !community.pFlags.left &&\n    !community.pFlags.creator;\n}\n\nexport default async function leaveCommunityWithConfirmation(options: {\n  communityId: ChatId,\n  managers: AppManagers\n}) {\n  const {communityId, managers} = options;\n  const title = await getPeerTitle({\n    peerId: communityId.toPeerId(true),\n    plainText: true\n  });\n\n  try {\n    await confirmationPopup({\n      titleLangKey: 'Community.Leave',\n      descriptionLangKey: 'Community.LeaveConfirm',\n      descriptionLangArgs: [title],\n      button: {\n        langKey: 'Community.Leave',\n        isDanger: true\n      }\n    });\n  } catch{\n    return false;\n  }\n\n  try {\n    await managers.appChatsManager.leave(communityId);\n    return true;\n  } catch(error) {\n    console.error('leave community error', error);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n","import confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport type {AppManagers} from '@lib/managers';\n\n/**\n * Unlinks a chat from a Community, asking first. Shared by every place that offers it —\n * the chat-list context menu and the Community settings list — so the wording, the toast\n * and the error handling can't drift apart.\n *\n * Returns whether the chat was actually removed (false when the user backed out).\n */\nexport default async function removeChatFromCommunityWithConfirmation(options: {\n  communityId: ChatId,\n  peerId: PeerId,\n  managers: AppManagers\n}) {\n  const {communityId, peerId, managers} = options;\n  const title = await getPeerTitle({peerId, plainText: true});\n\n  try {\n    await confirmationPopup({\n      titleLangKey: 'Community.RemoveChat',\n      descriptionLangKey: 'Community.RemoveChatConfirm',\n      descriptionLangArgs: [title],\n      button: {\n        langKey: 'Remove',\n        isDanger: true\n      }\n    });\n  } catch{\n    return false;\n  }\n\n  try {\n    await managers.appCommunitiesManager.togglePeerLink({\n      communityId,\n      peerId,\n      action: 'deleted'\n    });\n    toastNew({langPackKey: 'Community.ChatRemoved'});\n    return true;\n  } catch(error) {\n    console.error('remove chat from community error', error);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n","import PopupElement from '@components/popups';\nimport PopupMute from '@components/popups/mute';\nimport type {AppManagers} from '@lib/managers';\n\n/**\n * Muting a Community is ONE notify setting on the Community itself — not one per chat\n * inside it. Both entry points (the chat-list row and the Community panel menu) go\n * through here so the popup's positional arguments stay in a single place.\n */\nexport function showCommunityMutePopup(communityId: ChatId) {\n  PopupElement.createPopup(PopupMute, undefined, undefined, communityId);\n}\n\nexport function unmuteCommunity(communityId: ChatId, managers: AppManagers) {\n  return managers.appCommunitiesManager.muteCommunity(communityId, 0);\n}\n","import type {Dialog} from '@appManagers/appMessagesManager';\nimport type {ForumTopic} from '@layer';\nimport type {AnyDialog} from '@lib/storages/dialogs';\nimport appDialogsManager, {\n  findDialogListElement\n} from '@lib/appDialogsManager';\nimport rootScope from '@lib/rootScope';\nimport {useAppSettings} from '@stores/appSettings';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport PopupDeleteDialog from '@components/popups/deleteDialog';\nimport {i18n, LangPackKey, _i18n} from '@lib/langPack';\nimport {toastNew} from '@components/toast';\nimport PopupMute from '@components/popups/mute';\nimport {AppManagers} from '@lib/managers';\nimport {CAN_HIDE_TOPIC, FOLDER_ID_ARCHIVE, GENERAL_TOPIC_ID, REAL_FOLDER_ID, REAL_FOLDERS} from '@appManagers/constants';\nimport showLimitPopup from '@components/popups/limit';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport PopupElement from '@components/popups';\nimport showChatPreviewPopup, {chatPreviewAnchorFromDialogRow} from '@components/popups/chatPreview';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport IS_SHARED_WORKER_SUPPORTED from '@environment/sharedWorkerSupport';\nimport appImManager from '@lib/appImManager';\nimport {isDialog, isForumTopic, isMonoforumDialog, isSavedDialog} from '@appManagers/utils/dialogs/isDialog';\nimport createSubmenuTrigger, {CreateSubmenuArgs} from '@components/createSubmenuTrigger';\nimport type AddToFolderDropdownMenu from '@components/addToFolderDropdownMenu';\nimport memoizeAsyncWithTTL from '@helpers/memoizeAsyncWithTTL';\nimport {MonoforumDialog} from '@lib/storages/monoforumDialogs';\nimport {openRemoveFeePopup} from '@components/chat/removeFee';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport canRemoveCommunityPeer from '@appManagers/utils/communities/canRemovePeer';\nimport isCollapsedCommunity from '@appManagers/utils/communities/isCollapsedCommunity';\nimport type {\n  CommunityLinkedPeerKind\n} from '@appManagers/utils/communities/getCommunityLinkedPeerKind';\nimport type {\n  CommunityDialog\n} from '@appManagers/appCommunitiesManager';\nimport leaveCommunityWithConfirmation, {\n  canLeaveCommunity\n} from '@components/communities/leaveCommunity';\nimport clearHistoryWithConfirmation from '@components/clearHistory';\nimport canClearHistory from '@appManagers/utils/chats/canClearHistory';\nimport removeChatFromCommunityWithConfirmation\nfrom '@components/communities/removeChatFromCommunity';\nimport {\n  showCommunityMutePopup,\n  unmuteCommunity\n} from '@components/communities/communityMute';\n\n/**\n * What an item does on a chat row inside a Community panel (`data-community-chat-kind`),\n * on top of its own `verify`:\n * - `undefined` — nothing special, the item behaves as it does for any other dialog\n * - `'only'` — the item exists for Community chats only\n * - `'expanded'` — the item acts on the chat's place in OUR chat list, so it is offered\n *   only while the Community isn't folded into a single row (where those chats have no\n *   place of their own)\n */\ntype CommunityChatMode = 'only' | 'expanded';\n\ntype DialogContextMenuButton = ButtonMenuItemOptionsVerifiable & {\n  communityChat?: CommunityChatMode\n};\n\nexport default class DialogsContextMenu {\n  private buttons: DialogContextMenuButton[];\n\n  private peerId: PeerId;\n  private filterId: number;\n  private threadId: number;\n  private monoforumParentPeerId?: PeerId;\n  private dialog: AnyDialog | MonoforumDialog;\n  private canManageTopics: boolean;\n  private canDelete: boolean;\n  private canRemoveFromCommunity: boolean;\n  private communityId?: ChatId;\n  private communityDialog?: CommunityDialog;\n  private isCommunityDialog = false;\n  private communityChatKind?: CommunityLinkedPeerKind;\n  private isCommunityCollapsed = false;\n  private li: HTMLElement;\n  private addToFolderMenu: InstanceType<typeof AddToFolderDropdownMenu>;\n\n  constructor(private managers: AppManagers) {\n\n  }\n\n  public attach(element: HTMLElement) {\n    createContextMenu({\n      listenTo: element,\n      buttons: this.getButtons(),\n      onOpen: async(e, li) => {\n        this.li = li;\n        li.classList.add('menu-open');\n        this.peerId = li.dataset.peerId.toPeerId();\n        this.communityId = li.dataset.communityId ?\n          (+li.dataset.communityId).toChatId() :\n          undefined;\n        this.communityChatKind = li.dataset.communityChatKind as\n          CommunityLinkedPeerKind | undefined;\n        this.isCommunityDialog = !!this.communityId &&\n          !this.communityChatKind &&\n          this.peerId.toChatId() === this.communityId;\n        this.communityDialog = this.isCommunityDialog ?\n          apiManagerProxy.getCommunityDialog(this.communityId) :\n          undefined;\n        this.isCommunityCollapsed = !!this.communityChatKind &&\n          isCollapsedCommunity(apiManagerProxy.getChat(this.communityId));\n        this.threadId = +li.dataset.threadId || undefined;\n        this.monoforumParentPeerId = +li.dataset.monoforumParentPeerId || undefined;\n\n        if(li.dataset.isAllChats) {\n          throw 'All chats dialog';\n        }\n\n        this.dialog = this.isCommunityDialog ?\n          undefined :\n          this.monoforumParentPeerId ?\n            await this.managers.monoforumDialogsStorage.getDialogByParent(this.monoforumParentPeerId, this.peerId):\n            await this.managers.dialogsStorage.getAnyDialog(this.peerId, this.threadId);\n        this.filterId = this.threadId ? undefined : appDialogsManager.filterId;\n        this.canManageTopics = isForumTopic(this.dialog) ? await this.managers.dialogsStorage.canManageTopic(this.dialog) : undefined;\n        this.canDelete = await this.checkIfCanDelete();\n        this.canRemoveFromCommunity = !!this.communityId &&\n          canRemoveCommunityPeer(\n            apiManagerProxy.getChat(this.communityId),\n            apiManagerProxy.getPeer(this.peerId)\n          );\n      },\n      onOpenBefore: async() => {\n        this.buttons?.forEach(button => button?.onOpen?.());\n        // delete button\n        const langPackKey: LangPackKey = this.threadId ? 'Delete' : await this.managers.appPeersManager.getDeleteButtonText(this.peerId);\n        const lastButton = this.buttons[this.buttons.length - 1];\n        if(lastButton?.element) {\n          lastButton.element.lastChild.replaceWith(i18n(langPackKey));\n        }\n      },\n      onClose: () => {\n        this.buttons?.forEach(button => button?.onClose?.());\n        this.li.classList.remove('menu-open');\n\n        this.li =\n        this.peerId =\n        this.dialog =\n        this.filterId =\n        this.threadId =\n        this.monoforumParentPeerId =\n        this.canManageTopics = undefined;\n        this.canRemoveFromCommunity = undefined;\n        this.communityId = undefined;\n        this.communityDialog = undefined;\n        this.isCommunityDialog = false;\n        this.communityChatKind = undefined;\n        this.isCommunityCollapsed = false;\n      },\n      findElement: (e) => {\n        return findDialogListElement(e.target);\n      }\n    });\n  }\n\n  private getButtons() {\n    if(this.buttons) {\n      return this.buttons;\n    }\n\n    const [appSettings] = useAppSettings();\n    this.buttons = [{\n      icon: 'newtab',\n      text: 'OpenInNewTab',\n      onClick: (e: MouseEvent | TouchEvent) => {\n        appDialogsManager.openDialogInNewTab(this.li);\n        cancelEvent(e);\n      },\n      verify: () => IS_SHARED_WORKER_SUPPORTED &&\n        !this.monoforumParentPeerId &&\n        this.canOpenCommunityChat()\n    }, {\n      icon: 'topics',\n      text: 'Community.View',\n      onClick: () => {\n        appDialogsManager.toggleForumTabByPeerId(\n          this.peerId,\n          true,\n          false\n        );\n      },\n      verify: () => this.isCommunityDialog\n    }, {\n      icon: 'eye',\n      text: 'ChatList.Context.Preview',\n      onClick: this.onPreviewClick,\n      // a Community chat we only watch has no dialog of its own, but its history is\n      // right there in the row — and shift+click already previews it\n      verify: () => !!this.dialog || this.communityChatKind === 'viewable'\n    }, {\n      icon: 'topics',\n      text: 'TopicViewAsTopics',\n      onClick: () => {\n        appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      // the flag outlives the forum it was set for, so ask the peer too\n      verify: () => apiManagerProxy.isForum(this.peerId) &&\n        !!(this.dialog && (this.dialog as Dialog).pFlags.view_forum_as_messages)\n    }, {\n      icon: 'topics',\n      text: 'SavedViewAsChats',\n      onClick: () => {\n        appImManager.toggleViewAsMessages(this.peerId, false);\n      },\n      verify: () => this.peerId === rootScope.myId && !appSettings.savedAsForum && !this.threadId\n    }, {\n      icon: 'message',\n      text: 'SavedViewAsMessages',\n      onClick: () => {\n        appImManager.toggleViewAsMessages(this.peerId, true);\n      },\n      verify: () => this.peerId === rootScope.myId && appSettings.savedAsForum && !this.threadId\n    }, {\n      icon: 'unread',\n      text: 'MarkAsUnread',\n      onClick: this.onUnreadClick,\n      verify: async() => !!this.dialog &&\n        !this.isCommunityDialog &&\n        !this.threadId &&\n        !(await this.managers.appMessagesManager.isDialogUnread(this.dialog))\n    }, {\n      icon: 'readchats',\n      text: 'MarkAsRead',\n      onClick: this.onUnreadClick,\n      verify: () => this.isCommunityDialog ?\n        !!(\n          this.communityDialog?.unreadCount ||\n          this.communityDialog?.unreadMarked\n        ) :\n        !!this.dialog &&\n          this.managers.appMessagesManager.isDialogUnread(this.dialog)\n    }, createSubmenuTrigger({\n      options: {\n        icon: 'folder',\n        text: 'AddToFolder',\n        communityChat: 'expanded',\n        onClose: () => {\n          this.addToFolderMenu?.controls.closeTooltip?.();\n        },\n        verify: () => isDialog(this.dialog) && this.hasFilters()\n      },\n      createSubmenu: this.createAddToFolderSubmenu\n    }), {\n      icon: 'pin',\n      text: 'ChatList.Context.Pin',\n      communityChat: 'expanded',\n      onClick: this.onPinClick,\n      verify: async() => {\n        if(this.isCommunityDialog) {\n          return !this.communityDialog?.pFlags.pinned;\n        }\n        if(!this.dialog) return false;\n        if(isMonoforumDialog(this.dialog)) return false;\n\n        if(isSavedDialog(this.dialog)) {\n          return !this.dialog.pFlags.pinned;\n        }\n\n        if(this.threadId && !this.canManageTopics) {\n          return false;\n        }\n\n        const isPinned = this.filterId !== undefined && this.filterId > 1 ?\n          (await this.managers.appMessagesManager.getFilter(this.filterId)).pinnedPeerIds.includes(this.dialog.peerId) :\n          !!this.dialog.pFlags?.pinned;\n        return !isPinned;\n      }\n    }, {\n      icon: 'unpin',\n      text: 'ChatList.Context.Unpin',\n      communityChat: 'expanded',\n      onClick: this.onPinClick,\n      verify: async() => {\n        if(this.isCommunityDialog) {\n          return !!this.communityDialog?.pFlags.pinned;\n        }\n        if(!this.dialog) return false;\n        if(isMonoforumDialog(this.dialog)) return false;\n\n        if(isSavedDialog(this.dialog)) {\n          return !!this.dialog.pFlags.pinned;\n        }\n\n        if(this.threadId && !this.canManageTopics) {\n          return false;\n        }\n\n        const isPinned = this.filterId !== undefined && this.filterId > 1 ?\n          (await this.managers.appMessagesManager.getFilter(this.filterId)).pinnedPeerIds.includes(this.dialog.peerId) :\n          !!this.dialog.pFlags?.pinned;\n        return isPinned;\n      }\n    }, {\n      icon: 'mute',\n      text: 'ChatList.Context.Mute',\n      onClick: this.onMuteClick,\n      verify: async() => {\n        if(this.isCommunityDialog) {\n          // await it: the managers are async proxies, and `!promise` is always false\n          return !(await this.managers.appCommunitiesManager\n          .isCommunityMuted(this.communityId));\n        }\n        return !!this.dialog &&\n          !this.monoforumParentPeerId &&\n          this.peerId !== rootScope.myId &&\n          !(await this.managers.appNotificationsManager.isPeerLocalMuted({\n            peerId: this.peerId,\n            threadId: this.threadId\n          }));\n      }\n    }, {\n      icon: 'unmute',\n      text: 'ChatList.Context.Unmute',\n      onClick: this.onUnmuteClick,\n      verify: () => {\n        if(this.isCommunityDialog) {\n          return this.managers.appCommunitiesManager\n          .isCommunityMuted(this.communityId);\n        }\n        return !!this.dialog &&\n          !this.monoforumParentPeerId &&\n          this.peerId !== rootScope.myId &&\n          this.managers.appNotificationsManager.isPeerLocalMuted({\n            peerId: this.peerId,\n            threadId: this.threadId\n          });\n      }\n    }, {\n      icon: 'archive',\n      text: 'Archive',\n      communityChat: 'expanded',\n      onClick: this.onArchiveClick,\n      verify: () => isDialog(this.dialog) &&\n        !this.threadId &&\n        !this.monoforumParentPeerId &&\n        this.dialog.folder_id !== FOLDER_ID_ARCHIVE &&\n        this.peerId !== rootScope.myId\n    }, {\n      icon: 'unarchive',\n      text: 'Unarchive',\n      communityChat: 'expanded',\n      onClick: this.onArchiveClick,\n      verify: () => isDialog(this.dialog) &&\n        !this.threadId &&\n        !this.monoforumParentPeerId &&\n        this.dialog.folder_id === FOLDER_ID_ARCHIVE &&\n        this.peerId !== rootScope.myId\n    }, {\n      icon: 'group',\n      text: 'Community.ShowSeparately',\n      onClick: () => {\n        this.managers.appCommunitiesManager.toggleCollapsedInDialogs(\n          this.communityId,\n          false\n        ).catch((error) => {\n          console.error('ungroup community error', error);\n          toastNew({langPackKey: 'Error.AnError'});\n        });\n      },\n      verify: () => this.isCommunityDialog\n    }, {\n      icon: 'logout',\n      className: 'danger',\n      text: 'Community.Leave',\n      onClick: this.onLeaveCommunityClick,\n      verify: () => this.isCommunityDialog && canLeaveCommunity(\n        apiManagerProxy.getChat(this.communityId)\n      )\n    }, CAN_HIDE_TOPIC ? {\n      icon: 'hide',\n      text: 'Hide',\n      onClick: this.onHideTopicClick,\n      verify: () => {\n        return this.canManageTopics && (this.dialog as ForumTopic.forumTopic).id === GENERAL_TOPIC_ID;\n      }\n    } : undefined, {\n      icon: 'lock',\n      text: 'CloseTopic',\n      onClick: this.onToggleTopicClick,\n      verify: () => {\n        return !apiManagerProxy.isBotforum(this.peerId) && this.canManageTopics && !(this.dialog as ForumTopic.forumTopic).pFlags.closed;\n      }\n    }, {\n      icon: 'lockoff',\n      text: 'RestartTopic',\n      onClick: this.onToggleTopicClick,\n      verify: () => {\n        return this.canManageTopics && !!(this.dialog as ForumTopic.forumTopic).pFlags.closed;\n      }\n    }, {\n      icon: 'dollar_circle',\n      text: 'PaidMessages.ChargeFee',\n      onClick: () => this.onToggleFeeClick(true),\n      verify: () => this.verifyToggleFee(true)\n    }, {\n      icon: 'dollar_circle_x',\n      text: 'PaidMessages.RemoveFee',\n      onClick: () => this.onToggleFeeClick(false),\n      verify: () => this.verifyToggleFee(false)\n    }, {\n      // NOT the trash: this unlinks the chat, it doesn't delete it — and the Delete item\n      // right below would otherwise wear the very same icon\n      icon: 'crossround',\n      className: 'danger',\n      text: 'Community.RemoveChat',\n      communityChat: 'only',\n      onClick: this.onRemoveFromCommunityClick,\n      verify: () => this.canRemoveFromCommunity\n    }, {\n      icon: 'message_crossed',\n      text: 'ClearHistory',\n      onClick: this.onClearHistoryClick,\n      verify: () => !!this.dialog &&\n        !this.threadId &&\n        !this.monoforumParentPeerId &&\n        canClearHistory(apiManagerProxy.getPeer(this.peerId))\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Delete',\n      onClick: this.onDeleteClick,\n      verify: () => this.canDelete\n    }].filter(Boolean) as DialogContextMenuButton[];\n\n    // a chat row inside a Community panel is a dialog row like any other, so the items\n    // stay the ones every dialog gets — only those that make no sense there are dropped\n    for(const button of this.buttons) {\n      const verify = button.verify;\n      button.verify = () => {\n        if(this.communityChatKind) {\n          if(button.communityChat === 'expanded' && this.isCommunityCollapsed) {\n            return false;\n          }\n        } else if(button.communityChat === 'only') {\n          return false;\n        }\n\n        return verify ? verify() : true;\n      };\n    }\n\n    return this.buttons;\n  }\n\n  private createAddToFolderSubmenu = async({middleware}: CreateSubmenuArgs) => {\n    if(!isDialog(this.dialog)) return;\n\n    const {default: AddToFolderDropdownMenu, fetchDialogFilters} = await import('./addToFolderDropdownMenu');\n\n    const filters = await fetchDialogFilters();\n\n    if(!middleware()) return;\n\n    const menu = new AddToFolderDropdownMenu;\n    menu.feedProps({\n      dialog: this.dialog,\n      filters,\n      currentFilter: () => appDialogsManager.filterId,\n      onNewDialog: (dialog) => {\n        this.dialog = dialog;\n      },\n      onCleanup: () => {\n        this.addToFolderMenu = undefined;\n      }\n    });\n\n    return this.addToFolderMenu = menu;\n  };\n\n  public hasAddToFolderOpen = () => !!this.addToFolderMenu;\n\n  /**\n   * A Community lists chats we can't open at all: one that would take a join request, or\n   * one hidden behind a private link. Those rows still get the items that act on the LINK\n   * (removing the chat from the Community), never the ones that open or read the chat.\n   */\n  private canOpenCommunityChat = () => {\n    return !this.communityChatKind ||\n      this.communityChatKind === 'joined' ||\n      this.communityChatKind === 'viewable';\n  };\n\n  private hasFilters = memoizeAsyncWithTTL(async() => {\n    const filters = await this.managers.filtersStorage.getDialogFilters();\n    return !!filters.filter(filter => !REAL_FOLDERS.has(filter.id)).length\n  }, () => 1, 5_000);\n\n\n  private async checkIfCanDelete() {\n    if(!this.dialog) {\n      return false;\n    }\n\n    const chat = await this.managers.appChatsManager.getChat(this.peerId.toChatId());\n    if(chat?._ === 'channel' && chat?.pFlags?.monoforum && (chat?.pFlags?.left || chat?.pFlags?.creator)) return false;\n\n    if(this.threadId) {\n      if(isSavedDialog(this.dialog)) {\n        return true;\n      }\n\n      if(!this.canManageTopics) {\n        return false;\n      }\n\n      return (this.dialog as ForumTopic.forumTopic).id !== GENERAL_TOPIC_ID;\n    }\n\n    return true;\n  }\n\n  private onArchiveClick = async() => {\n    const dialog = await this.managers.appMessagesManager.getDialogOnly(this.peerId);\n    if(dialog) {\n      this.managers.appMessagesManager.editPeerFolders([dialog.peerId], +!dialog.folder_id as REAL_FOLDER_ID);\n    }\n  };\n\n  private onHideTopicClick = () => {\n    this.managers.appMessagesManager.editForumTopic({\n      peerId: this.peerId,\n      topicId: this.threadId,\n      hidden: true\n    });\n  };\n\n  private onToggleTopicClick = () => {\n    this.managers.appMessagesManager.editForumTopic({\n      peerId: this.peerId,\n      topicId: this.threadId,\n      closed: !(this.dialog as ForumTopic.forumTopic).pFlags.closed\n    });\n  };\n\n  private onPinClick = () => {\n    const {peerId, filterId, threadId, dialog} = this;\n    if(this.isCommunityDialog) {\n      this.managers.appCommunitiesManager.toggleCommunityPin(\n        this.communityId,\n        !this.communityDialog?.pFlags.pinned\n      ).catch((err: ApiError) => {\n        if(\n          err.type === 'PINNED_DIALOGS_TOO_MUCH' ||\n          err.type === 'PINNED_TOO_MUCH'\n        ) {\n          showLimitPopup('pin');\n        }\n      });\n      return;\n    }\n\n    const isSaved = isSavedDialog(dialog);\n    this.managers.appMessagesManager.toggleDialogPin({\n      peerId,\n      filterId,\n      topicOrSavedId: threadId\n    }).catch(async(err: ApiError) => {\n      if(err.type === 'PINNED_DIALOGS_TOO_MUCH' || err.type === 'PINNED_TOO_MUCH') {\n        if(isSaved) {\n          showLimitPopup('savedPin');\n        } else if(threadId) {\n          this.managers.apiManager.getLimit('topicPin').then((limit) => {\n            toastNew({langPackKey: 'LimitReachedPinnedTopics', langPackArguments: [limit]});\n          });\n        } else if(!REAL_FOLDERS.has(filterId)) {\n          toastNew({langPackKey: 'PinFolderLimitReached'});\n        } else {\n          showLimitPopup('pin');\n        }\n      }\n    });\n  };\n\n  private onUnmuteClick = () => {\n    if(this.isCommunityDialog) {\n      unmuteCommunity(this.communityId, this.managers);\n      return;\n    }\n\n    this.managers.appMessagesManager.togglePeerMute({peerId: this.peerId, mute: false, threadId: this.threadId});\n  };\n\n  private onMuteClick = () => {\n    if(this.isCommunityDialog) {\n      showCommunityMutePopup(this.communityId);\n      return;\n    }\n\n    PopupElement.createPopup(PopupMute, this.peerId, this.threadId);\n  };\n\n  private onPreviewClick = () => {\n    showChatPreviewPopup({\n      peerId: this.monoforumParentPeerId || this.peerId,\n      monoforumThreadId: this.monoforumParentPeerId ? this.peerId : undefined,\n      threadId: this.threadId,\n      anchor: chatPreviewAnchorFromDialogRow(this.li)\n    });\n  };\n\n  private onUnreadClick = async() => {\n    const {peerId, dialog} = this;\n    if(this.isCommunityDialog) {\n      await this.managers.appCommunitiesManager.markCommunityRead(\n        this.communityId\n      );\n      return;\n    }\n\n    if(!isDialog(dialog) && !isForumTopic(dialog) && !isMonoforumDialog(dialog)) return;\n\n    if(this.monoforumParentPeerId) {\n      this.managers.appMessagesManager.markDialogUnread({\n        peerId: this.monoforumParentPeerId,\n        monoforumThreadId: this.peerId,\n        read: !!dialog.unread_count\n      });\n    } else if(dialog.unread_count) {\n      if(!this.threadId) {\n        this.managers.appMessagesManager.markDialogUnread({peerId, read: true});\n      } else {\n        this.managers.appMessagesManager.readHistory({peerId, maxId: dialog.top_message, threadId: this.threadId});\n      }\n    } else if(!this.threadId) {\n      this.managers.appMessagesManager.markDialogUnread({peerId});\n    }\n  };\n\n  private verifyToggleFee = async(requirePayment: boolean) => {\n    if(!this.monoforumParentPeerId || this.dialog._ !== 'monoForumDialog') return false;\n\n    const chat = await this.managers.appChatsManager.getChat(this.monoforumParentPeerId.toChatId());\n    console.log('my-debug', {chat, requirePayment})\n    if(chat?._ !== 'channel' || !chat?.send_paid_messages_stars) return false;\n\n    return requirePayment ? !!this.dialog.pFlags?.nopaid_messages_exception : !this.dialog.pFlags?.nopaid_messages_exception;\n  };\n\n  private onToggleFeeClick = async(requirePayment: boolean) => {\n    const peerId = this.peerId;\n    const parentPeerId = this.monoforumParentPeerId;\n    if(!peerId || !parentPeerId) return;\n\n    try {\n      await openRemoveFeePopup({peerId, parentPeerId, requirePayment, managers: this.managers})\n    } catch{}\n  }\n\n  private onRemoveFromCommunityClick = () => {\n    const communityId = this.communityId;\n    const peerId = this.peerId;\n    if(!communityId || !peerId) {\n      return;\n    }\n\n    void removeChatFromCommunityWithConfirmation({\n      communityId,\n      peerId,\n      managers: this.managers\n    });\n  };\n\n  private onLeaveCommunityClick = () => {\n    void leaveCommunityWithConfirmation({\n      communityId: this.communityId,\n      managers: this.managers\n    });\n  };\n\n  private onClearHistoryClick = () => {\n    void clearHistoryWithConfirmation({\n      peerId: this.peerId,\n      managers: this.managers\n    });\n  };\n\n  private onDeleteClick = () => {\n    PopupElement.createPopup(\n      PopupDeleteDialog,\n      this.peerId,\n      undefined,\n      undefined,\n      this.threadId,\n      this.monoforumParentPeerId\n    );\n  };\n}\n","import type LazyLoadQueue from '@components/lazyLoadQueue';\nimport appDialogsManager, {AppDialogsManager, DialogDom, DialogElement, DialogElementSize} from '@lib/appDialogsManager';\nimport {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {fastRaf} from '@helpers/schedulers';\nimport SortedList, {SortedElementBase} from '@helpers/sortedList';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {AppManagers} from '@lib/managers';\nimport getUserStatusString from '@components/wrappers/getUserStatusString';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport wrapParticipantRank from '@components/wrappers/participantRank';\nimport getParticipantRank from '@appManagers/utils/chats/getParticipantRank';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\n\ninterface SortedUser extends SortedElementBase<PeerId> {\n  dom: DialogDom,\n  dialogElement: DialogElement\n}\n\nexport default class SortedUserList extends SortedList<SortedUser> {\n  protected static SORT_INTERVAL = 30e3;\n  public list: HTMLUListElement;\n  public ranks: Map<PeerId, ReturnType<typeof getParticipantRank>> = new Map();\n\n  protected lazyLoadQueue: LazyLoadQueue;\n  protected avatarSize: DialogElementSize = 'abitbigger';\n  protected rippleEnabled = true;\n  protected autonomous = true;\n  protected createChatListOptions: Parameters<AppDialogsManager['createChatList']>[0];\n  protected onListLengthChange: () => void;\n  protected managers: AppManagers;\n\n  constructor(options: Partial<{\n    lazyLoadQueue: SortedUserList['lazyLoadQueue'],\n    avatarSize: SortedUserList['avatarSize'],\n    rippleEnabled: SortedUserList['rippleEnabled'],\n    createChatListOptions: SortedUserList['createChatListOptions'],\n    autonomous: SortedUserList['autonomous'],\n    onListLengthChange: SortedUserList['onListLengthChange'],\n    getIndex: SortedUserList['getIndex'],\n    onUpdate: SortedUserList['onUpdate']\n  }> & {\n    managers: SortedUserList['managers'],\n    middleware: Middleware\n  }) {\n    super({\n      getIndex: options.getIndex || ((element) => element.id.isAnyChat() ? 0 : this.managers.appUsersManager.getUserStatusForSort(element.id)),\n      onDelete: (element) => {\n        element.dialogElement.remove();\n        this.onListLengthChange?.();\n      },\n      onUpdate: options.onUpdate || (async(element) => {\n        if(element.id.isAnyChat()) {\n          const status = await getChatMembersString(element.id.toChatId(), this.managers);\n          replaceContent(element.dom.lastMessageSpan, status);\n        } else {\n          const status = getUserStatusString(await this.managers.appUsersManager.getUser(element.id));\n          replaceContent(element.dom.lastMessageSpan, status);\n\n          const rank = this.ranks.get(element.id);\n          element.dialogElement.titleRight.replaceChildren(...(rank ? [wrapParticipantRank(rank)] : []));\n        }\n      }),\n      onSort: (element, idx) => {\n        const willChangeLength = element.dom.listEl.parentElement !== this.list;\n        positionElementByIndex(element.dom.listEl, this.list, idx);\n\n        if(willChangeLength && this.onListLengthChange) {\n          this.onListLengthChange();\n        }\n      },\n      onElementCreate: (base) => {\n        const dialogElement = appDialogsManager.addDialogNew({\n          peerId: base.id,\n          container: false,\n          avatarSize: this.avatarSize,\n          autonomous: this.autonomous,\n          meAsSaved: false,\n          rippleEnabled: this.rippleEnabled,\n          wrapOptions: {\n            lazyLoadQueue: this.lazyLoadQueue,\n            middleware: this.middlewareHelper.get()\n          },\n          withStories: true\n        });\n\n        const rank = this.ranks.get(base.id);\n        dialogElement.titleRight.replaceChildren(...[rank ? wrapParticipantRank(rank) : undefined].filter(Boolean));\n\n        (base as SortedUser).dom = dialogElement.dom;\n        (base as SortedUser).dialogElement = dialogElement;\n        return base as SortedUser;\n      },\n      updateElementWith: fastRaf,\n      updateListWith: async(callback) => {\n        if(!Array.from(this.elements.values()).some((element) => element.id.isUser())) {\n          return callback(false);\n        }\n\n        if(!isInDOM(this.list)) {\n          return callback(false);\n        }\n\n        await getHeavyAnimationPromise();\n\n        if(!isInDOM(this.list)) {\n          return callback(false);\n        }\n\n        callback(true);\n      },\n      middleware: options.middleware\n    });\n\n    safeAssign(this, options);\n\n    this.list = appDialogsManager.createChatList(this.createChatListOptions);\n\n    let timeout: number;\n    const doTimeout = () => {\n      timeout = window.setTimeout(() => {\n        this.updateList((good) => {\n          if(good) {\n            doTimeout();\n          }\n        });\n      }, SortedUserList.SORT_INTERVAL);\n    };\n\n    doTimeout();\n  }\n}\n","import {cancelContextMenuOpening} from '@helpers/dom/attachContextMenuListener';\nimport handleHorizontalSwipe, {SwipeHandlerHorizontalOptions} from '@helpers/dom/handleHorizontalSwipe';\n\nexport default function handleTabSwipe(options: SwipeHandlerHorizontalOptions) {\n  return handleHorizontalSwipe({\n    ...options,\n    onSwipe: (xDiff, yDiff, e) => {\n      xDiff *= -1;\n      yDiff *= -1;\n\n      if(Math.abs(xDiff) > 50) {\n        options.onSwipe(xDiff, yDiff, e);\n        cancelContextMenuOpening();\n\n        return true;\n      }\n    }\n  });\n}\n","import {_tgico} from '@helpers/tgico';\nimport {Message} from '@layer';\nimport Icon from '@components/icon';\n/* import findUpClassName from \"@helpers/dom/findUpClassName\";\nimport rootScope from \"@lib/rootScope\";\nimport Transition from \"@components/transition\"; */\n\nexport enum SENDING_STATUS {\n  Error = -1,\n  Pending,\n  Sent,\n  Read\n}\n\nexport function getSendingStatus(message: Message.message | Message.messageService) {\n  return message.pFlags.is_outgoing ?\n    SENDING_STATUS.Pending : (\n      message.pFlags.unread ?\n      SENDING_STATUS.Sent :\n      SENDING_STATUS.Read\n    );\n}\n\ntype C = 'check' | 'checks' | 'sending' | 'sendingerror_filled' | 'premium_lock';\nexport function setSendingStatus(\n  container: HTMLElement,\n  message?: C | Message.message | Message.messageService,\n  disableAnimationIfRippleFound?: boolean\n) {\n  let className: C;\n  if(typeof(message) === 'string') {\n    className = message;\n  } else if(message?.pFlags.out) {\n    if(message.error) {\n      className = 'sendingerror_filled';\n    } else if(message.pFlags.is_outgoing) {\n      className = 'sending';\n    } else if(message.pFlags.unread) {\n      className = 'check';\n    } else {\n      className = 'checks';\n    }\n  }\n\n  if(!className) {\n    container.textContent = '';\n    container.classList.add('hide');\n    return;\n  }\n\n  const lastElement = container.lastElementChild as HTMLElement;\n  if(lastElement && lastElement.classList.contains(_tgico(className))) {\n    return;\n  }\n\n  const statusClassName = className === 'sendingerror_filled' ? 'sendingerror' : className;\n  const element = Icon(className, 'sending-status-icon', 'sending-status-icon-' + statusClassName/* 'transition-item', */);\n  container.append(element);\n  container.classList.remove('hide');\n\n  lastElement?.remove();\n\n  /* if(!lastElement) {\n    element.classList.add('active');\n    return;\n  }\n\n  const select = Transition(container, undefined, 350, () => {\n    lastElement.remove();\n  }, false, true, false);\n\n  let animate = rootScope.settings.animationsEnabled && className !== 'sending' && !lastElement.classList.contains('tgico-sending');\n  if(disableAnimationIfRippleFound && animate) {\n    const parent = findUpClassName(container, 'rp');\n    if(parent.querySelector('.c-ripple__circle') || parent.matches(':hover')) {\n      animate = false;\n    }\n  }\n\n  select(element, animate, lastElement); */\n\n  /* SetTransition(lastElement, 'is-visible', false, 350, () => {\n    // lastElement.remove();\n  }, 2);\n  SetTransition(element, 'is-visible', true, 350, undefined, 2); */\n}\n","import type {MyDraftMessage} from '@appManagers/appDraftsManager';\nimport type {MyMessage} from '@appManagers/appMessagesManager';\nimport Icon from '@components/icon';\nimport type {\n  WrapMessageForReplyOptions\n} from '@components/wrappers/messageForReply';\nimport type {WrapRichTextOptions} from '@lib/richTextProcessor/wrapRichText';\nimport rootScope from '@lib/rootScope';\nimport {i18n} from '@lib/langPack';\n\ntype MiddlewarePromise = <T>(value: T) => T;\ntype MessageRenderer = typeof import(\n  '@components/wrappers/messageForReply'\n)['default'];\ntype PeerTitleRenderer = typeof import(\n  '@components/wrappers/peerTitle'\n)['default'];\n\nexport default async function renderDialogSubtitleParts(options: {\n  peerId: PeerId,\n  isSaved: boolean,\n  lastMessage?: MyMessage,\n  draftMessage?: MyDraftMessage,\n  noForwardIcon?: boolean,\n  mediaParts?: (Promise<HTMLElement> | HTMLElement)[],\n  withoutMediaType?: boolean,\n  prependPeerId?: PeerId,\n  middleware: MiddlewarePromise,\n  textColor: string,\n  messageRenderer?: MessageRenderer,\n  peerTitleRenderer?: PeerTitleRenderer\n}) {\n  const {\n    peerId,\n    isSaved,\n    lastMessage,\n    draftMessage,\n    noForwardIcon,\n    middleware,\n    textColor\n  } = options;\n  const wrapMessageForReply = options.messageRenderer ||\n    (await import('@components/wrappers/messageForReply')).default;\n  const willPrepend: (Promise<HTMLElement> | HTMLElement)[] = [];\n  let icon: Icon;\n\n  if(draftMessage) {\n  } else if(\n    lastMessage?._ === 'message' &&\n    lastMessage.fwdFromId &&\n    !isSaved &&\n    !noForwardIcon\n  ) {\n    icon = 'forward_filled';\n  } else if(\n    lastMessage?._ === 'message' &&\n    lastMessage.reply_to?._ === 'messageReplyStoryHeader'\n  ) {\n    icon = 'storyreply';\n  }\n\n  if(icon) {\n    willPrepend.push(Icon(\n      icon,\n      'dialog-subtitle-ico',\n      'dialog-subtitle-ico-' + icon\n    ));\n  }\n  if(options.mediaParts?.length) {\n    willPrepend.push(...options.mediaParts);\n  }\n\n  // * the names the preview opens with: who wrote, then the chat they wrote in.\n  // * The arrow points from the one into the next and the last of them hands the\n  // * line over to the message with a colon — so a lone chat name keeps the\n  // * arrow (it is not someone speaking) while a lone sender keeps the colon.\n  const names: (Promise<HTMLElement> | HTMLElement)[] = [];\n  const withChatName = !!options.prependPeerId;\n  let draftLabel: HTMLElement;\n\n  if(draftMessage) {\n    const span = document.createElement('span');\n    span.classList.add('danger');\n    span.append(i18n('Draft'), ': ');\n    // * not a name — it labels the message and stays right in front of it\n    draftLabel = span;\n  } else if(\n    lastMessage &&\n    peerId.isAnyChat() &&\n    peerId !== lastMessage.fromId &&\n    lastMessage._ === 'message'\n  ) {\n    const span = document.createElement('span');\n    span.classList.add('primary-text');\n\n    if(lastMessage.fromId === rootScope.myId) {\n      span.append(i18n('FromYou'));\n      names.push(span);\n    } else {\n      const title = Promise.resolve(options.peerTitleRenderer)\n      .then(async(wrapPeerTitle) => {\n        return wrapPeerTitle ||\n          (await import('@components/wrappers/peerTitle')).default;\n      })\n      .then((wrapPeerTitle) => {\n        return middleware(wrapPeerTitle({\n          peerId: lastMessage.fromId,\n          onlyFirstName: true\n        }));\n      })\n      .then((element) => {\n        span.prepend(element);\n        return span;\n      });\n\n      names.push(title);\n    }\n\n    if(!withChatName) span.append(': ');\n  }\n\n  if(withChatName) {\n    const span = document.createElement('span');\n    span.classList.add('primary-text');\n    const title = Promise.resolve(options.peerTitleRenderer)\n    .then(async(wrapPeerTitle) => {\n      return wrapPeerTitle ||\n        (await import('@components/wrappers/peerTitle')).default;\n    })\n    .then((wrapPeerTitle) => {\n      return middleware(wrapPeerTitle({\n        peerId: options.prependPeerId,\n        dialog: true\n      }));\n    })\n    .then((element) => {\n      span.prepend(element);\n      return span;\n    });\n    // * the arrow is a part of its own so it keeps sitting BETWEEN the names —\n    // * inside a name's own isolate an RTL title would push it to the front\n    const arrow = Icon(\n      'next',\n      'inline-icon',\n      'dialog-subtitle-arrow',\n      'primary-text'\n    );\n\n    if(names.length) {\n      names.push(arrow, title);\n      span.append(': ');\n    } else {\n      names.push(title, arrow);\n    }\n  }\n\n  if(draftLabel) {\n    names.push(draftLabel);\n  }\n\n  willPrepend.unshift(...names);\n\n  const wrapOptions: Partial<\n    WrapMessageForReplyOptions & WrapRichTextOptions\n  > = {textColor};\n  let fragment: DocumentFragment;\n  let wrapResult: ReturnType<typeof wrapMessageForReply>;\n  if(draftMessage) {\n    wrapResult = wrapMessageForReply({\n      ...wrapOptions,\n      message: draftMessage\n    });\n  } else if(lastMessage) {\n    wrapResult = wrapMessageForReply({\n      ...wrapOptions,\n      message: lastMessage,\n      withoutMediaType: options.withoutMediaType\n    });\n  } else {\n    fragment = document.createDocumentFragment();\n  }\n\n  if(wrapResult) {\n    fragment = await middleware(wrapResult);\n  }\n  const resolvedPrepend: HTMLElement[] = willPrepend.length ?\n    await middleware(Promise.all(willPrepend)) :\n    [];\n\n  return [...resolvedPrepend, fragment].map((part, idx, parts) => {\n    const span = document.createElement('span');\n    span.classList.add('dialog-subtitle-span');\n    // * every part isolates its own direction, so an RTL name or message reads\n    // * correctly without reordering the parts around it — that is what the\n    // * subtitle used a flex row for, at the cost of a separate ellipsis per\n    // * part; as one inline line it is elided once, at the end\n    span.dir = 'auto';\n    if(idx === parts.length - 1) {\n      span.classList.add('dialog-subtitle-span-last');\n    }\n    span.append(part);\n    return span;\n  });\n}\n","import AudioAssetPlayer from '@helpers/audioAssetPlayer';\n\nexport const CALL_AUDIO_ASSETS: Record<'busy' | 'connect' | 'end' | 'incoming' | 'outgoing' | 'failed', string> = {\n  busy: 'call_busy.mp3',\n  connect: 'call_connect.mp3',\n  end: 'call_end.mp3',\n  incoming: 'call_incoming.mp3',\n  outgoing: 'call_outgoing.mp3',\n  failed: 'voip_failed.mp3'\n};\n\nlet assetPlayer: AudioAssetPlayer<typeof CALL_AUDIO_ASSETS>;\nexport default function getCallAudioAsset() {\n  return assetPlayer ??= new AudioAssetPlayer(CALL_AUDIO_ASSETS);\n}\n","enum CALL_STATE {\n  CONNECTED,\n  CONNECTING,\n  EXCHANGING_KEYS,\n  PENDING,\n  REQUESTING,\n  CLOSING,\n  CLOSED\n}\n\nexport default CALL_STATE;\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nimport {PhoneCallProtocol} from '@layer';\n\n// tgcalls v2 P2P signaling protocol version.\n// '13.0.0' (v3) = structured NegotiateChannels signaling, encryptRawPacket crypto,\n// gzip-compressed payloads and SCTP-framed signaling. See src/lib/calls/p2P.\nexport const CALL_PROTOCOL_LIBRARY_VERSIONS = ['13.0.0'];\n\nexport default function getCallProtocol(): PhoneCallProtocol {\n  return {\n    _: 'phoneCallProtocol',\n    pFlags: {\n      udp_p2p: true,\n      udp_reflector: true\n    },\n    min_layer: 65,\n    max_layer: 92,\n    library_versions: CALL_PROTOCOL_LIBRARY_VERSIONS\n  };\n}\n","/*\n * Originally from:\n * https://github.com/evgeny-nadymov/telegram-react\n * Copyright (C) 2018 Evgeny Nadymov\n * https://github.com/evgeny-nadymov/telegram-react/blob/master/LICENSE\n */\n\nimport bufferConcats from '@helpers/bytes/bufferConcats';\nimport subtle from '@lib/crypto/subtle';\nimport sha256 from '@lib/crypto/utils/sha256';\nimport {P2P_SIGNALING_INCOMING_COUNTERS_KEPT} from '@lib/calls/constants';\n\n// tgcalls EncryptedConnection.cpp: \"don't try decrypting more\". Signaling is a\n// few KiB of gzipped JSON; the old 128 MiB cap only bounded the tab's memory.\nconst kMaxIncomingPacketSize = 128 * 1024;\n\nexport default class P2PEncryptor {\n  private type: 'Signaling';\n  private counter: number;\n  // The replay window, tgcalls `_largestIncomingCounters`: ascending, at most\n  // P2P_SIGNALING_INCOMING_COUNTERS_KEPT entries. A Map of every counter ever\n  // seen grew with the call and let the peer fill the tab's memory one packet\n  // at a time.\n  private largestIncomingCounters: number[];\n\n  constructor(private isOutgoing: boolean, private p2pKey: Uint8Array) {\n    this.type = 'Signaling';\n    this.counter = 0;\n    this.largestIncomingCounters = [];\n  }\n\n  // tgcalls EncryptedConnection::registerIncomingCounter: refuse a counter the\n  // window already holds, or one that fell out of it (older than the largest\n  // seen minus the window), then keep the window trimmed to the largest ones.\n  private registerIncomingCounter(counter: number) {\n    const list = this.largestIncomingCounters;\n    let position = 0;\n    while(position < list.length && list[position] < counter) {\n      ++position;\n    }\n\n    const largest = list.length ? list[list.length - 1] : 0;\n    if(position < list.length && list[position] === counter) {\n      return false;\n    } else if(counter + P2P_SIGNALING_INCOMING_COUNTERS_KEPT <= largest) {\n      return false;\n    }\n\n    let eraseCount = 0;\n    while(eraseCount < list.length && list[eraseCount] + P2P_SIGNALING_INCOMING_COUNTERS_KEPT <= counter) {\n      ++eraseCount;\n    }\n\n    list.splice(0, eraseCount);\n    list.splice(position - eraseCount, 0, counter);\n    return true;\n  }\n\n  private concatSHA256(parts: Uint8Array[]) {\n    return sha256(bufferConcats(...parts));\n  }\n\n  private async encryptPrepared(buffer: Uint8Array) {\n    const result = {\n      counter: 0, // this.counterFromSeq(this.readSeq(buffer)),\n      bytes: new Uint8Array(16 + buffer.length)\n    };\n\n    const x = (this.isOutgoing ? 0 : 8) + (this.type === 'Signaling' ? 128 : 0);\n    const key = this.p2pKey;\n\n    const msgKeyLarge = await this.concatSHA256([key.subarray(x + 88, x + 88 + 32), buffer]);\n    const msgKey = result.bytes;\n    for(let i = 0; i < 16; ++i) {\n      msgKey[i] = msgKeyLarge[i + 8];\n    }\n\n    const aesKeyIv = await this.prepareAesKeyIv(key, msgKey, x);\n\n    const bytes = await this.aesProcessCtr(buffer, buffer.length, aesKeyIv, true);\n\n    result.bytes = new Uint8Array([...result.bytes.subarray(0, 16), ...bytes]);\n\n    return result;\n  }\n\n  public encryptRawPacket(buffer: Uint8Array) {\n    const seq = ++this.counter;\n    const arr = new ArrayBuffer(4);\n    const view = new DataView(arr);\n    view.setUint32(0, seq >>> 0, false); // byteOffset = 0; litteEndian = false\n\n    const result = new Uint8Array([...new Uint8Array(arr), ...buffer]);\n\n    return this.encryptPrepared(result);\n  }\n\n  private async prepareAesKeyIv(key: Uint8Array, msgKey: Uint8Array, x: number) {\n    const [sha256a, sha256b] = await Promise.all([\n      this.concatSHA256([\n        msgKey.subarray(0, 16),\n        key.subarray(x, x + 36)\n      ]),\n\n      this.concatSHA256([\n        key.subarray(40 + x, 40 + x + 36),\n        msgKey.subarray(0, 16)\n      ])\n    ]);\n\n    return {\n      key: new Uint8Array([\n        ...sha256a.subarray(0, 8),\n        ...sha256b.subarray(8, 8 + 16),\n        ...sha256a.subarray(24, 24 + 8)\n      ]),\n      iv: new Uint8Array([\n        ...sha256b.subarray(0, 4),\n        ...sha256a.subarray(8, 8 + 8),\n        ...sha256b.subarray(24, 24 + 4)\n      ])\n    };\n  }\n\n  private async aesProcessCtr(encryptedData: Uint8Array, dataSize: number, aesKeyIv: {key: Uint8Array, iv: Uint8Array}, encrypt = true) {\n    const cryptoKey = await subtle.importKey(\n      'raw',\n      aesKeyIv.key as BufferSource,\n      {name: 'AES-CTR'},\n      false,\n      [encrypt ? 'encrypt' : 'decrypt']\n    );\n\n    const buffer: ArrayBuffer = await subtle[encrypt ? 'encrypt' : 'decrypt']({\n      name: 'AES-CTR',\n      counter: aesKeyIv.iv as BufferSource,\n      length: aesKeyIv.iv.length * 8\n    },\n    cryptoKey,\n    encryptedData as BufferSource\n    );\n\n    return new Uint8Array(buffer);\n  }\n\n  private constTimeIsDifferent(a: Uint8Array, b: Uint8Array, count: number) {\n    let msgKeyEquals = true;\n    for(let i = 0; i < count; ++i) {\n      if(a[i] !== b[i]) {\n        msgKeyEquals = false;\n      }\n    }\n\n    return !msgKeyEquals;\n  }\n\n  public async decryptRawPacket(buffer: Uint8Array) {\n    if(buffer.length < 21 || buffer.length > kMaxIncomingPacketSize) {\n      return;\n    }\n\n    const {isOutgoing, type} = this;\n\n    const x = (isOutgoing ? 8 : 0) + (type === 'Signaling' ? 128 : 0);\n    const key = this.p2pKey;\n\n    const msgKey = buffer.subarray(0, 16);\n    const encryptedData = buffer.subarray(16);\n    const encryptedDataSize = buffer.length - 16;\n\n    const aesKeyIv = await this.prepareAesKeyIv(key, msgKey, x);\n\n    const decryptionBuffer = await this.aesProcessCtr(encryptedData, encryptedDataSize, aesKeyIv, false);\n\n    const msgKeyLarge = await this.concatSHA256([\n      key.subarray(88 + x, 88 + x + 32),\n      decryptionBuffer\n    ]);\n\n    if(this.constTimeIsDifferent(msgKeyLarge.subarray(8), msgKey, 16)) {\n      return;\n    }\n\n    const dataView = new DataView(decryptionBuffer.buffer);\n    const seq = dataView.getUint32(0);\n    if(!this.registerIncomingCounter(seq)) {\n      return;\n    }\n\n    return decryptionBuffer.slice(4);\n  }\n}\n","/*\n * Minimal Node-`Buffer`-compatible view over `Uint8Array` — only the methods the\n * SCTP signaling port needs. tweb runs in the browser, where Node's `Buffer` is\n * absent; this lets `sctpSignaling.ts` stay a near-verbatim port.\n */\n\nexport default class ByteBuf extends Uint8Array {\n  static alloc(size: number): ByteBuf {\n    return new ByteBuf(size);\n  }\n\n  // not named `from` — that would clash with Uint8Array's static `from` signature.\n  static wrap(source: ArrayLike<number> | ArrayBufferLike): ByteBuf {\n    return new ByteBuf(source as ArrayLike<number>);\n  }\n\n  static concat(list: Uint8Array[]): ByteBuf {\n    let total = 0;\n    for(const item of list) {\n      total += item.length;\n    }\n\n    const result = new ByteBuf(total);\n    let offset = 0;\n    for(const item of list) {\n      result.set(item, offset);\n      offset += item.length;\n    }\n\n    return result;\n  }\n\n  private view() {\n    return new DataView(this.buffer, this.byteOffset, this.byteLength);\n  }\n\n  readUInt16BE(offset: number) {\n    return this.view().getUint16(offset, false);\n  }\n\n  readUInt32BE(offset: number) {\n    return this.view().getUint32(offset, false);\n  }\n\n  readUInt32LE(offset: number) {\n    return this.view().getUint32(offset, true);\n  }\n\n  writeUInt16BE(value: number, offset: number) {\n    this.view().setUint16(offset, value, false);\n    return offset + 2;\n  }\n\n  writeUInt32BE(value: number, offset: number) {\n    this.view().setUint32(offset, value, false);\n    return offset + 4;\n  }\n\n  writeUInt32LE(value: number, offset: number) {\n    this.view().setUint32(offset, value, true);\n    return offset + 4;\n  }\n\n  // Node's Buffer.slice returns a VIEW (shared memory) — unlike Uint8Array.slice\n  // which copies. The SCTP code relies on Buffer semantics.\n  slice(start?: number, end?: number): ByteBuf {\n    return this.subarray(start, end) as ByteBuf;\n  }\n\n  copy(target: Uint8Array, targetStart = 0, sourceStart = 0, sourceEnd = this.length) {\n    const sub = this.subarray(sourceStart, sourceEnd);\n    target.set(sub, targetStart);\n    return sub.length;\n  }\n\n  equals(other: Uint8Array) {\n    if(this.length !== other.length) {\n      return false;\n    }\n\n    for(let i = 0; i < this.length; ++i) {\n      if(this[i] !== other[i]) {\n        return false;\n      }\n    }\n\n    return true;\n  }\n}\n","/*\n * Software SCTP framing for tgcalls v3 (13.0.0) call signaling.\n * Ported from Telegram Web A (telegram-tt) — src/api/gramjs/methods/sctpSignaling.ts\n */\n\nimport {logger} from '@lib/logger';\nimport ByteBuf from '@lib/calls/p2P/byteBuf';\n\nconst DEBUG_CALLS = true;\nconst log = logger('CALL-SCTP');\n\ntype SctpChunk = {\n  type: number;\n  flags: number;\n  body: ByteBuf;\n};\n\ntype SctpDataChunk = {\n  flags: number;\n  body: ByteBuf;\n};\n\nconst SCTP_PORT = 5000;\nconst SCTP_RECEIVE_WINDOW = 0x500000;\nconst SCTP_MAX_PENDING_PEER_DATA_CHUNKS = 256;\nconst SCTP_MAX_PENDING_PEER_DATA_BYTES = 0x100000;\nconst SCTP_MAX_PENDING_PEER_TSN_GAP = 1024;\nconst SCTP_INIT_RETRY_DELAY = 1000;\nconst SCTP_MAX_INIT_RETRY_DELAY = 8000;\nconst SCTP_STREAM_ID = 0;\nconst SCTP_BINARY_PPID = 53;\nconst SCTP_INIT = 1;\nconst SCTP_INIT_ACK = 2;\nconst SCTP_SACK = 3;\nconst SCTP_HEARTBEAT = 4;\nconst SCTP_HEARTBEAT_ACK = 5;\nconst SCTP_ABORT = 6;\nconst SCTP_STATE_COOKIE = 7;\nconst SCTP_COOKIE_ECHO = 10;\nconst SCTP_COOKIE_ACK = 11;\nconst SCTP_DATA = 0;\n\nconst CRC32C_TABLE = createCrc32cTable();\n\nexport class SctpSignaling {\n  private localTag = generateUint32();\n\n  private localTsn = generateUint32();\n\n  private localSsn = 0;\n\n  private peerTag?: number;\n\n  private peerInitialTsn?: number;\n\n  private peerCumulativeTsn?: number;\n\n  private initSent = false;\n\n  private initSentAt: number | undefined;\n\n  private initRetryCount = 0;\n\n  private isEstablished = false;\n\n  private cookie = ByteBuf.alloc(0);\n\n  private pendingPayloads: ByteBuf[] = [];\n\n  private pendingPackets: number[][] = [];\n\n  private pendingPeerData = new Map<number, SctpDataChunk>();\n\n  private pendingPeerDataSize = 0;\n\n  private reassembly?: ByteBuf[];\n  private reassemblySize = 0;\n\n  wrapPayload(payload: ByteBuf) {\n    if(this.isEstablished && this.peerTag !== undefined) {\n      return Array.from(this.createDataPacket(payload));\n    }\n\n    this.pendingPayloads.push(payload);\n    if(!this.initSent) {\n      return this.createInitRetryPacket();\n    }\n\n    if(this.shouldRetryInit()) {\n      logSctp('INIT retrying', {\n        retryCount: this.initRetryCount,\n        pendingPayloadCount: this.pendingPayloads.length\n      });\n      return this.createInitRetryPacket();\n    }\n\n    return undefined;\n  }\n\n  private shouldRetryInit() {\n    if(this.initSentAt === undefined || this.peerTag !== undefined) {\n      return false;\n    }\n\n    return performance.now() - this.initSentAt >= this.getInitRetryDelay();\n  }\n\n  private getInitRetryDelay() {\n    if(!this.initRetryCount) {\n      return SCTP_INIT_RETRY_DELAY;\n    }\n\n    return Math.min(SCTP_INIT_RETRY_DELAY * 2 ** (this.initRetryCount - 1), SCTP_MAX_INIT_RETRY_DELAY);\n  }\n\n  private createInitRetryPacket() {\n    this.initSent = true;\n    this.initSentAt = performance.now();\n    this.initRetryCount++;\n    return Array.from(this.createInitPacket());\n  }\n\n  drainPackets() {\n    const result = this.pendingPackets;\n    this.pendingPackets = [];\n    return result;\n  }\n\n  receive(packet: ByteBuf) {\n    const payloads: ByteBuf[] = [];\n    if(packet.length < 12) {\n      logSctp('packet dropped: too short', {\n        length: packet.length\n      });\n      return payloads;\n    }\n\n    if(!hasValidSctpChecksum(packet)) {\n      logSctp('packet dropped: invalid CRC32C', {\n        length: packet.length,\n        sourcePort: packet.readUInt16BE(0),\n        destinationPort: packet.readUInt16BE(2),\n        verificationTag: packet.readUInt32BE(4)\n      });\n      return payloads;\n    }\n\n    const chunks = parseSctpChunks(packet);\n    chunks.forEach((chunk) => {\n      if(!this.validateVerificationTag(packet, chunk.type)) {\n        logSctp('chunk dropped: invalid verification tag', {\n          chunkType: chunk.type,\n          verificationTag: packet.readUInt32BE(4),\n          expectedVerificationTag: chunk.type === SCTP_INIT ? 0 : this.localTag\n        });\n        return;\n      }\n\n      if(chunk.type === SCTP_INIT) {\n        this.handleInit(chunk.body);\n      } else if(chunk.type === SCTP_INIT_ACK) {\n        this.handleInitAck(chunk.body);\n      } else if(chunk.type === SCTP_COOKIE_ECHO) {\n        if(!this.validateCookieEcho(chunk.body)) {\n          logSctp('COOKIE_ECHO ignored: invalid cookie', {\n            cookieLength: chunk.body.length,\n            expectedCookieLength: this.cookie.length\n          });\n          return;\n        }\n        this.pendingPackets.push(Array.from(this.createPacket(SCTP_COOKIE_ACK, 0, ByteBuf.alloc(0))));\n        this.markEstablished();\n      } else if(chunk.type === SCTP_COOKIE_ACK) {\n        this.markEstablished();\n      } else if(chunk.type === SCTP_DATA) {\n        payloads.push(...this.handleData(chunk.flags, chunk.body));\n      } else if(chunk.type === SCTP_SACK) {\n        this.handleSack(chunk.body);\n      } else if(chunk.type === SCTP_HEARTBEAT) {\n        this.pendingPackets.push(Array.from(this.createPacket(SCTP_HEARTBEAT_ACK, 0, chunk.body)));\n      } else if(chunk.type === SCTP_HEARTBEAT_ACK) {\n        // Nothing to do; accepting the chunk prevents Firefox/native peers from being logged as unsupported.\n      } else if(chunk.type === SCTP_ABORT) {\n        logSctp('ABORT received; resetting association', {\n          bodyLength: chunk.body.length\n        });\n        this.resetAssociation();\n      } else {\n        logSctp('chunk ignored: unsupported type', {\n          chunkType: chunk.type,\n          flags: chunk.flags,\n          bodyLength: chunk.body.length\n        });\n      }\n    });\n\n    return payloads;\n  }\n\n  private validateCookieEcho(cookie: ByteBuf) {\n    return Boolean(this.cookie.length && cookie.length === this.cookie.length && cookie.equals(this.cookie));\n  }\n\n  private validateVerificationTag(packet: ByteBuf, chunkType: number) {\n    const verificationTag = packet.readUInt32BE(4);\n    if(chunkType === SCTP_INIT) {\n      return verificationTag === 0;\n    }\n\n    return verificationTag === this.localTag;\n  }\n\n  private handleInit(body: ByteBuf) {\n    if(body.length < 16) {\n      logSctp('INIT ignored: body too short', {\n        bodyLength: body.length\n      });\n      return;\n    }\n\n    this.peerTag = body.readUInt32BE(0);\n    this.peerInitialTsn = body.readUInt32BE(12);\n    this.peerCumulativeTsn = (this.peerInitialTsn - 1) >>> 0;\n    this.initSent = true;\n    this.cookie = this.createCookie();\n    this.pendingPackets.push(Array.from(this.createInitAckPacket()));\n  }\n\n  private handleInitAck(body: ByteBuf) {\n    if(body.length < 16) {\n      logSctp('INIT_ACK ignored: body too short', {\n        bodyLength: body.length\n      });\n      return;\n    }\n\n    this.peerTag = body.readUInt32BE(0);\n    this.peerInitialTsn = body.readUInt32BE(12);\n    this.peerCumulativeTsn = (this.peerInitialTsn - 1) >>> 0;\n\n    const cookie = findSctpParameter(body.slice(16), SCTP_STATE_COOKIE);\n    if(cookie) {\n      this.pendingPackets.push(Array.from(this.createPacket(SCTP_COOKIE_ECHO, 0, cookie)));\n    } else {\n      logSctp('INIT_ACK ignored: missing state cookie', {\n        bodyLength: body.length\n      });\n    }\n  }\n\n  private handleData(flags: number, body: ByteBuf) {\n    if(body.length < 12) {\n      logSctp('DATA ignored: body too short', {\n        bodyLength: body.length\n      });\n      return [];\n    }\n\n    const tsn = body.readUInt32BE(0);\n    const streamId = body.readUInt16BE(4);\n    const ppid = body.readUInt32BE(8);\n    if(streamId !== SCTP_STREAM_ID || ppid !== SCTP_BINARY_PPID) {\n      logSctp('DATA ignored: unsupported stream or PPID', {\n        streamId,\n        ppid,\n        expectedStreamId: SCTP_STREAM_ID,\n        expectedPpid: SCTP_BINARY_PPID\n      });\n      return [];\n    }\n\n    const expectedTsn = this.getNextPeerTsn();\n    if(expectedTsn !== undefined && tsn !== expectedTsn) {\n      if(isTsnAfter(tsn, expectedTsn)) {\n        this.bufferPendingPeerData(tsn, flags, body, expectedTsn);\n      } else {\n        logSctp('DATA ignored: duplicate TSN', {\n          tsn,\n          peerCumulativeTsn: this.peerCumulativeTsn,\n          expectedTsn\n        });\n      }\n      this.pendingPackets.push(Array.from(this.createSackPacket()));\n      return [];\n    }\n\n    return this.acceptData(tsn, flags, body);\n  }\n\n  private acceptData(tsn: number, flags: number, body: ByteBuf) {\n    const payloads: ByteBuf[] = [];\n    let currentTsn = tsn;\n    let currentFlags = flags;\n    let currentBody = body;\n\n    while(true) {\n      const payload = this.readDataPayload(currentTsn, currentFlags, currentBody);\n      if(payload) {\n        payloads.push(payload);\n      }\n\n      const nextTsn = this.getNextPeerTsn();\n      const nextChunk = nextTsn === undefined ? undefined : this.pendingPeerData.get(nextTsn);\n      if(nextTsn === undefined || !nextChunk) {\n        break;\n      }\n\n      this.deletePendingPeerData(nextTsn);\n      currentTsn = nextTsn;\n      currentFlags = nextChunk.flags;\n      currentBody = nextChunk.body;\n    }\n\n    this.pendingPackets.push(Array.from(this.createSackPacket()));\n    return payloads;\n  }\n\n  private readDataPayload(tsn: number, flags: number, body: ByteBuf) {\n    this.markEstablished();\n    this.peerCumulativeTsn = tsn;\n\n    const userData = body.slice(12);\n    const isBegin = Boolean(flags & 0x02);\n    const isEnd = Boolean(flags & 0x01);\n    if(isBegin && isEnd) {\n      return userData;\n    }\n\n    if(isBegin) {\n      this.reassembly = [userData];\n      this.reassemblySize = userData.length;\n      return undefined;\n    }\n\n    if(!this.reassembly) {\n      logSctp('DATA ignored: missing reassembly start', {\n        flags,\n        tsn\n      });\n      return undefined;\n    }\n\n    this.reassembly.push(userData);\n    this.reassemblySize += userData.length;\n\n    // Bound the run. Inbound signaling is SCTP-framed BEFORE it can be\n    // authenticated (processDecryptQueue reassembles, then decrypts), so a peer\n    // — or the relay, which delivers updateNewCallSignalingData — can stream\n    // middle fragments that never set the E flag and grow this buffer until the\n    // tab dies. Same budget the pending-chunk map above already uses.\n    if(this.reassembly.length > SCTP_MAX_PENDING_PEER_DATA_CHUNKS ||\n      this.reassemblySize > SCTP_MAX_PENDING_PEER_DATA_BYTES) {\n      logSctp('DATA reassembly overflow, dropping run', {\n        chunks: this.reassembly.length,\n        bytes: this.reassemblySize\n      });\n      this.reassembly = undefined;\n      this.reassemblySize = 0;\n      return undefined;\n    }\n\n    if(!isEnd) {\n      return undefined;\n    }\n\n    const result = ByteBuf.concat(this.reassembly);\n    this.reassembly = undefined;\n    this.reassemblySize = 0;\n    return result;\n  }\n\n  private handleSack(body: ByteBuf) {\n    if(body.length < 12) {\n      logSctp('SACK ignored: body too short', {\n        bodyLength: body.length\n      });\n      return;\n    }\n\n    this.markEstablished();\n  }\n\n  private getNextPeerTsn() {\n    if(this.peerCumulativeTsn === undefined) {\n      return undefined;\n    }\n\n    return (this.peerCumulativeTsn + 1) >>> 0;\n  }\n\n  private bufferPendingPeerData(tsn: number, flags: number, body: ByteBuf, expectedTsn: number) {\n    if(this.pendingPeerData.has(tsn)) {\n      logSctp('DATA ignored: already buffered TSN', {\n        tsn,\n        expectedTsn,\n        pendingCount: this.pendingPeerData.size,\n        pendingBytes: this.pendingPeerDataSize\n      });\n      return;\n    }\n\n    const tsnGap = getForwardTsnGap(tsn, expectedTsn);\n    if(\n      tsnGap > SCTP_MAX_PENDING_PEER_TSN_GAP ||\n      this.pendingPeerData.size >= SCTP_MAX_PENDING_PEER_DATA_CHUNKS ||\n      this.pendingPeerDataSize + body.length > SCTP_MAX_PENDING_PEER_DATA_BYTES\n    ) {\n      logSctp('DATA ignored: TSN gap buffer full', {\n        tsn,\n        peerCumulativeTsn: this.peerCumulativeTsn,\n        expectedTsn,\n        tsnGap,\n        pendingCount: this.pendingPeerData.size,\n        pendingBytes: this.pendingPeerDataSize\n      });\n      return;\n    }\n\n    this.pendingPeerData.set(tsn, {flags, body});\n    this.pendingPeerDataSize += body.length;\n    logSctp('DATA buffered: TSN gap', {\n      tsn,\n      peerCumulativeTsn: this.peerCumulativeTsn,\n      expectedTsn,\n      tsnGap,\n      pendingCount: this.pendingPeerData.size,\n      pendingBytes: this.pendingPeerDataSize\n    });\n  }\n\n  private deletePendingPeerData(tsn: number) {\n    const chunk = this.pendingPeerData.get(tsn);\n    if(!chunk) {\n      return;\n    }\n\n    this.pendingPeerDataSize -= chunk.body.length;\n    this.pendingPeerData.delete(tsn);\n  }\n\n  private clearPendingPeerData() {\n    this.pendingPeerData.clear();\n    this.pendingPeerDataSize = 0;\n  }\n\n  private flushPendingPayloads() {\n    if(this.peerTag === undefined) {\n      return;\n    }\n\n    const payloads = this.pendingPayloads;\n    this.pendingPayloads = [];\n    payloads.forEach((payload) => {\n      this.pendingPackets.push(Array.from(this.createDataPacket(payload)));\n    });\n  }\n\n  private markEstablished() {\n    if(this.isEstablished) {\n      return;\n    }\n\n    this.isEstablished = true;\n    this.flushPendingPayloads();\n  }\n\n  private resetAssociation() {\n    this.localTag = generateUint32();\n    this.localTsn = generateUint32();\n    this.localSsn = 0;\n    this.peerTag = undefined;\n    this.peerInitialTsn = undefined;\n    this.peerCumulativeTsn = undefined;\n    this.initSent = false;\n    this.initSentAt = undefined;\n    this.initRetryCount = 0;\n    this.isEstablished = false;\n    this.cookie = ByteBuf.alloc(0);\n    this.pendingPayloads = [];\n    this.pendingPackets = [];\n    this.clearPendingPeerData();\n    this.reassembly = undefined;\n    this.reassemblySize = 0;\n  }\n\n  private createInitPacket() {\n    const body = ByteBuf.alloc(16);\n    body.writeUInt32BE(this.localTag, 0);\n    body.writeUInt32BE(SCTP_RECEIVE_WINDOW, 4);\n    body.writeUInt16BE(0xFFFF, 8);\n    body.writeUInt16BE(0xFFFF, 10);\n    body.writeUInt32BE(this.localTsn, 12);\n    return this.createPacket(SCTP_INIT, 0, body, 0);\n  }\n\n  private createInitAckPacket() {\n    const body = ByteBuf.alloc(16);\n    body.writeUInt32BE(this.localTag, 0);\n    body.writeUInt32BE(SCTP_RECEIVE_WINDOW, 4);\n    body.writeUInt16BE(0xFFFF, 8);\n    body.writeUInt16BE(0xFFFF, 10);\n    body.writeUInt32BE(this.localTsn, 12);\n\n    return this.createPacket(SCTP_INIT_ACK, 0, ByteBuf.concat([\n      body,\n      createSctpParameter(SCTP_STATE_COOKIE, this.cookie)\n    ]));\n  }\n\n  private createDataPacket(payload: ByteBuf) {\n    const body = ByteBuf.alloc(12 + payload.length);\n    body.writeUInt32BE(this.localTsn, 0);\n    this.localTsn = (this.localTsn + 1) >>> 0;\n    body.writeUInt16BE(SCTP_STREAM_ID, 4);\n    body.writeUInt16BE(this.localSsn, 6);\n    this.localSsn = (this.localSsn + 1) & 0xFFFF;\n    body.writeUInt32BE(SCTP_BINARY_PPID, 8);\n    payload.copy(body, 12);\n    return this.createPacket(SCTP_DATA, 0x03, body);\n  }\n\n  private createSackPacket() {\n    const body = ByteBuf.alloc(12);\n    body.writeUInt32BE(this.peerCumulativeTsn || 0, 0);\n    body.writeUInt32BE(SCTP_RECEIVE_WINDOW, 4);\n    body.writeUInt16BE(0, 8);\n    body.writeUInt16BE(0, 10);\n    return this.createPacket(SCTP_SACK, 0, body);\n  }\n\n  private createPacket(type: number, flags: number, body: ByteBuf, verificationTag = this.peerTag || 0) {\n    const chunk = createSctpChunk(type, flags, body);\n    const packet = ByteBuf.alloc(12 + chunk.length);\n    packet.writeUInt16BE(SCTP_PORT, 0);\n    packet.writeUInt16BE(SCTP_PORT, 2);\n    packet.writeUInt32BE(verificationTag, 4);\n    chunk.copy(packet, 12);\n    packet.writeUInt32LE(crc32c(packet), 8);\n    return packet;\n  }\n\n  private createCookie() {\n    const cookie = ByteBuf.alloc(16);\n    cookie.writeUInt32BE(this.localTag, 0);\n    cookie.writeUInt32BE(this.peerTag || 0, 4);\n    cookie.writeUInt32BE(this.localTsn, 8);\n    cookie.writeUInt32BE(this.peerInitialTsn || 0, 12);\n    return cookie;\n  }\n}\n\nfunction createSctpChunk(type: number, flags: number, body: ByteBuf) {\n  const length = 4 + body.length;\n  const paddedLength = align4(length);\n  const chunk = ByteBuf.alloc(paddedLength);\n  chunk[0] = type;\n  chunk[1] = flags;\n  chunk.writeUInt16BE(length, 2);\n  body.copy(chunk, 4);\n  return chunk;\n}\n\nfunction createSctpParameter(type: number, value: ByteBuf) {\n  const length = 4 + value.length;\n  const parameter = ByteBuf.alloc(align4(length));\n  parameter.writeUInt16BE(type, 0);\n  parameter.writeUInt16BE(length, 2);\n  value.copy(parameter, 4);\n  return parameter;\n}\n\nfunction findSctpParameter(parameters: ByteBuf, type: number) {\n  let offset = 0;\n  while(offset + 4 <= parameters.length) {\n    const parameterType = parameters.readUInt16BE(offset);\n    const length = parameters.readUInt16BE(offset + 2);\n    if(length < 4 || offset + length > parameters.length) {\n      return undefined;\n    }\n\n    if(parameterType === type) {\n      return parameters.slice(offset + 4, offset + length);\n    }\n\n    offset += align4(length);\n  }\n\n  return undefined;\n}\n\nfunction parseSctpChunks(packet: ByteBuf) {\n  const chunks: SctpChunk[] = [];\n  let offset = 12;\n  while(offset + 4 <= packet.length) {\n    const type = packet[offset];\n    const flags = packet[offset + 1];\n    const length = packet.readUInt16BE(offset + 2);\n    if(length < 4 || offset + length > packet.length) {\n      break;\n    }\n\n    chunks.push({\n      type,\n      flags,\n      body: packet.slice(offset + 4, offset + length)\n    });\n    offset += align4(length);\n  }\n\n  return chunks;\n}\n\nexport function isSctpPacket(packet: ByteBuf) {\n  return packet.length >= 12 &&\n    packet.readUInt16BE(0) === SCTP_PORT &&\n    packet.readUInt16BE(2) === SCTP_PORT;\n}\n\nfunction hasValidSctpChecksum(packet: ByteBuf) {\n  return isSctpPacket(packet) && packet.readUInt32LE(8) === crc32c(packet);\n}\n\nfunction align4(value: number) {\n  return (value + 3) & ~3;\n}\n\nfunction generateUint32() {\n  const values = new Uint32Array(1);\n  crypto.getRandomValues(values);\n\n  return values[0] >>> 0;\n}\n\nfunction isTsnAfter(tsn: number, expectedTsn: number) {\n  return ((tsn - expectedTsn) >>> 0) < 0x80000000;\n}\n\nfunction getForwardTsnGap(tsn: number, expectedTsn: number) {\n  return (tsn - expectedTsn) >>> 0;\n}\n\nfunction createCrc32cTable() {\n  const table: number[] = [];\n  for(let i = 0; i < 256; i++) {\n    let value = i;\n    for(let bit = 0; bit < 8; bit++) {\n      value = value & 1 ? (0x82F63B78 ^ (value >>> 1)) : value >>> 1;\n    }\n    table[i] = value >>> 0;\n  }\n  return table;\n}\n\nfunction crc32c(data: ByteBuf) {\n  const buffer = ByteBuf.wrap(data);\n  buffer.writeUInt32LE(0, 8);\n  let crc = 0xFFFFFFFF;\n  for(let i = 0; i < buffer.length; i++) {\n    crc = CRC32C_TABLE[(crc ^ buffer[i]) & 0xFF] ^ (crc >>> 8);\n  }\n  return (~crc) >>> 0;\n}\n\nfunction logSctp(message: string, data: Record<string, unknown> = {}) {\n  if(!DEBUG_CALLS) {\n    return;\n  }\n\n  log('[SCTP]', message, data);\n}\n","/*\n * Placeholder media streams for the P2P call: a disabled silent audio track and\n * a disabled black video track. Used as the sender track while a real\n * camera/microphone track is absent, so the transceiver direction stays stable.\n */\n\nimport createCanvasStream from '@helpers/canvas/createCanvasStream';\n\nexport function silence(audioContext: AudioContext) {\n  const oscillator = audioContext.createOscillator();\n  const destination = audioContext.createMediaStreamDestination();\n  oscillator.connect(destination);\n  oscillator.start();\n\n  const track = destination.stream.getAudioTracks()[0];\n  track.enabled = false;\n  return new MediaStream([track]);\n}\n\nexport function black({width, height}: {width: number, height: number}) {\n  // createCanvasStream (tweb's helper) already paints the canvas black via the\n  // default fillStyle; we only need to disable the track for a placeholder.\n  const stream = createCanvasStream({width, height});\n  stream.getVideoTracks()[0].enabled = false;\n  return stream;\n}\n","/*\n * Pure helpers for the tgcalls v2 P2P signaling engine: media-stream and ICE\n * candidate utilities, SDP parsing and content/SSRC building. All functions\n * here are `this`-free; everything that touches CallInstance state lives in\n * callInstance.ts.\n */\n\nimport {Logger} from '@lib/logger';\nimport {appSettings} from '@stores/appSettings';\nimport getStream from '@lib/calls/helpers/getStream';\nimport {\n  findSdpLineValue as findLineValue,\n  getSdpDirection,\n  getSdpPort,\n  parseExtmaps,\n  parseFingerprints,\n  parsePayloadTypes,\n  parseSdpSections,\n  parseSsrcGroups,\n  parseSsrcs,\n  summarizeSdp,\n  parseBundleMids,\n  SdpSection\n} from '@lib/calls/p2P/sdpCommon';\nimport {P2PMediaContent, P2PMessage, P2PPayloadType, PayloadType, RtpHdrexts} from '@lib/calls/types';\n\nexport const IS_ECHO_CANCELLATION_SUPPORTED = navigator?.mediaDevices?.getSupportedConstraints().echoCancellation;\nexport const IS_NOISE_SUPPRESSION_SUPPORTED = navigator?.mediaDevices?.getSupportedConstraints().noiseSuppression;\n\n// ===== Types =====\n\nexport type StreamType = 'audio' | 'video' | 'presentation';\n\nexport type Connection = {\n  ip: string,\n  ipv6?: string,\n  port: number,\n  username: string,\n  password: string,\n  isTurn: boolean,\n  isStun: boolean\n};\n\nexport type SsrcGroup = {\n  semantics?: string,\n  sources: (string | number)[]\n};\n\nexport type ConferenceSsrc = {\n  isVideo: boolean,\n  isPresentation: boolean,\n  isMain: boolean,\n  isRemoved?: boolean,\n  userId: string,\n  endpoint: string,\n  mid: string,\n  sourceGroups: SsrcGroup[]\n};\n\nexport type Conference = {\n  audioPayloadTypes: PayloadType[],\n  audioExtensions: RtpHdrexts[],\n  videoPayloadTypes: PayloadType[],\n  videoExtensions: RtpHdrexts[],\n  ssrcs: ConferenceSsrc[]\n};\n\nexport type MediaMids = {\n  audio: string;\n  video: string;\n  presentation: string;\n  data: string;\n};\n\nexport type ActiveLocalMedia = {\n  hasVideo: boolean;\n  hasPresentation: boolean;\n};\n\nexport type SsrcEntry = ConferenceSsrc & {\n  direction?: RTCRtpTransceiverDirection;\n  isLocalOnly?: boolean;\n};\n\ntype CandidatesMessage = Extract<P2PMessage, {'@type': 'Candidates'}>;\n\nexport type QueuedCandidate = CandidatesMessage['candidates'][number] & Pick<CandidatesMessage, 'exchangeId' | 'ufrag'>;\n\n// ===== Payload-type conversion =====\n\n// Convert a signaling payload type (feedbackTypes) into the SDP-builder shape (rtcp-fbs).\nexport function payloadTypeToConference(payloadType: P2PPayloadType): PayloadType {\n  return {\n    'id': payloadType.id,\n    'name': payloadType.name,\n    'clockrate': payloadType.clockrate,\n    'channels': payloadType.channels,\n    'parameters': payloadType.parameters,\n    'rtcp-fbs': payloadType.feedbackTypes\n  };\n}\n\n// ===== Media-stream helpers =====\n\nexport function getUserStream(streamType: StreamType, facing: VideoFacingModeEnum = 'user') {\n  if(streamType === 'presentation') {\n    return (navigator.mediaDevices as any).getDisplayMedia({\n      audio: false,\n      video: true\n    });\n  }\n\n  // Honour the device picked in the in-call settings popup / \"Speakers and\n  // Camera\" tab. Without this, toggling video off/on (or accepting an\n  // incoming call) re-grabs the OS-default camera regardless of what the\n  // user picked. Group calls already route their constraints through the\n  // shared get*Constraints helpers — do the same for P2P so the two paths\n  // stay in sync.\n  const audioId = appSettings.callDevices?.microphoneId;\n  const audio = streamType === 'audio' ? {\n    echoCancellation: IS_ECHO_CANCELLATION_SUPPORTED ? true : undefined,\n    noiseSuppression: IS_NOISE_SUPPRESSION_SUPPORTED ?\n      (appSettings.callDevices?.noiseSuppression ?? true) :\n      undefined,\n    deviceId: audioId ? {exact: audioId} : undefined\n  } : false;\n\n  // `facingMode` only matters on mobile (front vs rear camera) — paired with\n  // an explicit `deviceId: {exact: ...}` it can produce OverconstrainedError\n  // on desktop where the chosen camera doesn't advertise a facingMode. Pick\n  // ONE: prefer the explicit deviceId, fall back to facingMode.\n  const videoId = appSettings.callDevices?.cameraId;\n  const video = streamType === 'video' ? (\n    videoId ?\n      {deviceId: {exact: videoId}} :\n      {facingMode: facing}\n  ) : false;\n\n  // Stale-deviceId recovery and incremental retry live inside `getStream`.\n  return getStream({audio, video});\n}\n\nexport function getStreamTrack(stream: MediaStream | undefined) {\n  return stream?.getTracks()[0];\n}\n\nexport function hasLiveTrack(stream: MediaStream | undefined) {\n  return getStreamTrack(stream)?.readyState === 'live';\n}\n\nexport function stopStream(stream?: MediaStream, except?: MediaStream) {\n  if(!stream || stream === except) {\n    return;\n  }\n\n  stream.getTracks().forEach((track) => {\n    track.stop();\n  });\n}\n\n// ===== ICE servers / candidates =====\n\nexport function buildIceServers(connections: Connection[], isP2p: boolean) {\n  const servers: RTCIceServer[] = [];\n\n  connections.forEach((connection) => {\n    const urls: string[] = [];\n    if(connection.isTurn) {\n      urls.push(buildIceServerUrl('turn', connection.ip, connection.port));\n      if(connection.ipv6) {\n        urls.push(buildIceServerUrl('turn', connection.ipv6, connection.port));\n      }\n    }\n    if(isP2p && connection.isStun) {\n      urls.push(buildIceServerUrl('stun', connection.ip, connection.port));\n      if(connection.ipv6) {\n        urls.push(buildIceServerUrl('stun', connection.ipv6, connection.port));\n      }\n    }\n\n    if(!urls.length) {\n      return;\n    }\n\n    servers.push({\n      urls,\n      username: connection.username,\n      credential: connection.password\n    });\n  });\n\n  return servers;\n}\n\nfunction buildIceServerUrl(protocol: 'stun' | 'turn', host: string, port: number) {\n  const formattedHost = host.includes(':') && !host.startsWith('[') ? `[${host}]` : host;\n  return `${protocol}:${formattedHost}:${port}`;\n}\n\nexport async function addIceCandidate(log: Logger, connection: RTCPeerConnection, candidate: RTCIceCandidateInit) {\n  try {\n    await connection.addIceCandidate(candidate);\n  } catch(error) {\n    log.warn('failed to add ICE candidate', {\n      candidate,\n      remoteSdpSummary: getRemoteSdpSummary(connection),\n      errorName: error instanceof Error ? error.name : undefined,\n      errorMessage: error instanceof Error ? error.message : String(error)\n    });\n  }\n}\n\nexport async function tryAddCandidate(\n  log: Logger,\n  connection: RTCPeerConnection,\n  candidate: QueuedCandidate\n) {\n  const sdpString = normalizeCandidateComponent(candidate.sdpString);\n  if(!sdpString) {\n    return;\n  }\n\n  const rtcCandidate: RTCIceCandidateInit = {\n    candidate: sdpString,\n    sdpMid: candidate.sdpMid,\n    sdpMLineIndex: candidate.sdpMLineIndex,\n    usernameFragment: getCandidateUfrag(candidate)\n  };\n\n  if(\n    !rtcCandidate.sdpMid &&\n    (rtcCandidate.sdpMLineIndex === undefined || rtcCandidate.sdpMLineIndex === null)\n  ) {\n    const fallbackMLineIndex = getLegacyCandidateMLineIndex(connection);\n    if(fallbackMLineIndex === undefined) {\n      log('drop ICE candidate without media id', {\n        candidate: rtcCandidate,\n        remoteSdpSummary: getRemoteSdpSummary(connection)\n      });\n      return;\n    }\n\n    rtcCandidate.sdpMLineIndex = fallbackMLineIndex;\n  }\n\n  await addIceCandidate(log, connection, rtcCandidate);\n}\n\nexport function getCandidateUfrag(candidate: QueuedCandidate) {\n  return candidate.ufrag || candidate.usernameFragment || undefined;\n}\n\nexport function getRemoteDescriptionUfrags(connection: RTCPeerConnection) {\n  const sdp = connection.remoteDescription?.sdp;\n  if(!sdp) {\n    return new Set<string>();\n  }\n\n  const sections = parseSdpSections(sdp);\n  const ufrags = new Set<string>();\n  sections.forEach((section) => {\n    const ufrag = findLineValue(sections, 'a=ice-ufrag:', section);\n    if(ufrag) {\n      ufrags.add(ufrag);\n    }\n  });\n\n  return ufrags;\n}\n\nexport function getRemoteDescriptionMids(connection: RTCPeerConnection) {\n  const sdp = connection.remoteDescription?.sdp;\n  if(!sdp) {\n    return [];\n  }\n\n  const sections = parseSdpSections(sdp);\n  return sections.filter((section) => {\n    return section.kind !== 'session';\n  }).map((section, index) => {\n    return {\n      index,\n      kind: section.kind,\n      mid: section.mid,\n      port: getSdpPort(section),\n      ufrag: findLineValue(sections, 'a=ice-ufrag:', section)\n    };\n  });\n}\n\nexport function getRemoteSdpSummary(connection: RTCPeerConnection) {\n  const sdp = connection.remoteDescription?.sdp;\n  return sdp ? summarizeSdp(sdp) : undefined;\n}\n\nexport function normalizeCandidateComponent(sdpString?: string) {\n  if(!sdpString) {\n    return undefined;\n  }\n\n  const component = sdpString.match(/^candidate:\\S+ (\\d+) /)?.[1];\n  if(component === '2') {\n    return undefined;\n  }\n\n  return sdpString;\n}\n\nexport function getLegacyCandidateMLineIndex(connection: RTCPeerConnection) {\n  const sdp = connection.remoteDescription?.sdp;\n  if(!sdp) {\n    return undefined;\n  }\n\n  const mediaSections = parseSdpSections(sdp).filter((section) => {\n    return section.kind !== 'session';\n  });\n  const activeMediaSections = mediaSections.filter((section) => {\n    return getSdpPort(section) !== 0;\n  });\n  const activeRtpMediaSections = activeMediaSections.filter((section) => {\n    return section.kind === 'audio' || section.kind === 'video';\n  });\n\n  if(activeMediaSections.length === 1) {\n    return mediaSections.indexOf(activeMediaSections[0]);\n  }\n\n  if(activeRtpMediaSections.length === 1 && activeMediaSections.every((section) => {\n    return section.kind === 'application' || section === activeRtpMediaSections[0];\n  })) {\n    return mediaSections.indexOf(activeRtpMediaSections[0]);\n  }\n\n  return undefined;\n}\n\n// ===== SDP / content parsing =====\n\nexport function getDefaultAudioPayloadTypes(): Conference['audioPayloadTypes'] {\n  return [{\n    id: 111,\n    name: 'opus',\n    clockrate: 48000,\n    channels: 2,\n    parameters: {\n      minptime: 10,\n      useinbandfec: 1\n    }\n  }];\n}\n\nexport function getDefaultVideoPayloadTypes(): Conference['videoPayloadTypes'] {\n  return [{\n    id: 96,\n    name: 'VP8',\n    clockrate: 90000,\n    channels: 0\n  }];\n}\n\nexport function orderMediaContents(contents: P2PMediaContent[]) {\n  const audioContent = contents.find((content) => content.type === 'audio');\n  const videoContents = contents.filter((content) => content.type === 'video');\n  return [audioContent, videoContents[0], videoContents[1]];\n}\n\nexport function buildSsrc(\n  content: P2PMediaContent | undefined,\n  mid: string,\n  isVideo: boolean,\n  isPresentation = false\n): SsrcEntry {\n  if(!content) {\n    return {\n      isVideo,\n      isPresentation,\n      isMain: false,\n      isRemoved: true,\n      userId: '0',\n      endpoint: mid,\n      mid,\n      sourceGroups: []\n    };\n  }\n\n  const ssrcGroups = content.ssrcGroups || [];\n  const sourceGroups: SsrcGroup[] = ssrcGroups.length ? ssrcGroups.map((group) => {\n    return {\n      semantics: group.semantics,\n      sources: group.ssrcs\n    };\n  }) : [{\n    sources: [Number(content.ssrc)]\n  }];\n\n  return {\n    isVideo,\n    isPresentation,\n    isMain: false,\n    userId: '0',\n    endpoint: mid,\n    mid,\n    sourceGroups\n  };\n}\n\nexport function parseInitialSetup(sdp: string): Extract<P2PMessage, {'@type': 'InitialSetup'}> {\n  const sections = parseSdpSections(sdp);\n  const ufrag = findLineValue(sections, 'a=ice-ufrag:');\n  const pwd = findLineValue(sections, 'a=ice-pwd:');\n  const fingerprints = parseFingerprints(sections);\n  const iceOptions = findLineValue(sections, 'a=ice-options:');\n\n  if(!ufrag || !pwd || !fingerprints.length) {\n    throw Error('Failed parsing SDP transport setup');\n  }\n\n  return {\n    '@type': 'InitialSetup',\n    ufrag,\n    pwd,\n    'renomination': Boolean(iceOptions?.split(' ').includes('renomination')),\n    fingerprints\n  };\n}\n\nexport function parseMediaContent(\n  section: SdpSection,\n  type: P2PMediaContent['type'],\n  fallbackContent?: P2PMediaContent\n): P2PMediaContent {\n  const ssrcGroups = parseSsrcGroups(section);\n  const ssrc = ssrcGroups[0]?.ssrcs[0] || parseSsrcs(section)[0] || Number(fallbackContent?.ssrc);\n\n  if(!ssrc) {\n    throw Error('Failed parsing SDP media SSRC');\n  }\n\n  return {\n    type,\n    ssrc: fallbackContent?.ssrc || String(ssrc),\n    ssrcGroups: fallbackContent ? fallbackContent.ssrcGroups || [] : ssrcGroups,\n    payloadTypes: parsePayloadTypes(section),\n    rtpExtensions: parseExtmaps(section)\n  };\n}\n\nexport function parseMediaContents(sdp: string, mids: MediaMids, activeMedia?: ActiveLocalMedia): P2PMediaContent[] {\n  const sections = parseSdpSections(sdp);\n  const contents: P2PMediaContent[] = [];\n  const audioSection = sections.find((section) => section.mid === mids.audio);\n  const videoSection = sections.find((section) => section.mid === mids.video);\n  const presentationSection = sections.find((section) => section.mid === mids.presentation);\n\n  if(audioSection) {\n    contents.push(parseMediaContent(audioSection, 'audio'));\n  }\n  if(videoSection && activeMedia?.hasVideo !== false) {\n    contents.push(parseMediaContent(videoSection, 'video'));\n  }\n  if(presentationSection && activeMedia?.hasPresentation !== false) {\n    contents.push(parseMediaContent(presentationSection, 'video'));\n  }\n\n  return contents;\n}\n\nexport function parseMediaContentMids(sdp: string, contents: P2PMediaContent[]) {\n  const sections = parseSdpSections(sdp);\n  const midsBySsrc: Record<string, string> = {};\n\n  contents.forEach((content) => {\n    const section = sections.find((item) => {\n      return item.mid && parseSsrcs(item).includes(Number(content.ssrc));\n    });\n    if(section?.mid) {\n      midsBySsrc[content.ssrc] = section.mid;\n    }\n  });\n\n  return midsBySsrc;\n}\n\nexport function filterRemoteVideoPayloadTypes(content: P2PMediaContent | undefined) {\n  const payloadTypes = content?.payloadTypes;\n  if(!payloadTypes?.length) {\n    return undefined;\n  }\n\n  const supportedCodecs = RTCRtpReceiver.getCapabilities('video')?.codecs || [];\n  const supportedNames = new Set(supportedCodecs.map((codec) => {\n    return codec.mimeType.split('/')[1]?.toUpperCase();\n  }).filter(Boolean));\n  const preferredCodec = payloadTypes.find((payloadType) => {\n    return payloadType.name.toUpperCase() === 'VP8' && supportedNames.has('VP8');\n  }) || payloadTypes.find((payloadType) => {\n    return payloadType.name.toUpperCase() !== 'RTX' && supportedNames.has(payloadType.name.toUpperCase());\n  });\n\n  if(!preferredCodec) {\n    return undefined;\n  }\n\n  const result = [preferredCodec];\n  const rtxPayload = payloadTypes.find((payloadType) => {\n    return payloadType.name.toUpperCase() === 'RTX' && Number(payloadType.parameters?.apt) === preferredCodec.id;\n  });\n  if(rtxPayload) {\n    result.push(rtxPayload);\n  }\n\n  return result;\n}\n\nfunction summarizeValidationMLine(section: SdpSection, bundleMids: Set<string>) {\n  return {\n    kind: section.kind,\n    mid: section.mid,\n    port: getSdpPort(section),\n    direction: getSdpDirection(section),\n    hasRtcpMux: section.lines.includes('a=rtcp-mux'),\n    hasBundleOnly: section.lines.includes('a=bundle-only'),\n    isBundled: Boolean(section.mid && bundleMids.has(section.mid))\n  };\n}\n\nexport function validateRemoteAnswerSdp(log: Logger, offerSdp: string | undefined, answerSdp: string) {\n  if(!offerSdp) {\n    return;\n  }\n\n  const offerBundleMids = new Set(parseBundleMids(offerSdp) || []);\n  const answerBundleMids = new Set(parseBundleMids(answerSdp) || []);\n  const offerSections = parseSdpSections(offerSdp).filter((section) => section.kind !== 'session');\n  const answerSections = parseSdpSections(answerSdp).filter((section) => section.kind !== 'session');\n  const mLines = offerSections.map((offerSection, index) => {\n    const answerSection = answerSections[index];\n    return {\n      index,\n      offer: summarizeValidationMLine(offerSection, offerBundleMids),\n      answer: answerSection ? summarizeValidationMLine(answerSection, answerBundleMids) : undefined\n    };\n  });\n  const issues = mLines.flatMap(({answer, index, offer}) => {\n    if(!answer) {\n      return [`m-line ${index} is missing in answer`];\n    }\n\n    const result: string[] = [];\n    if(answer.mid !== offer.mid) {\n      result.push(`m-line ${index} mid mismatch`);\n    }\n    if(answer.port !== 0 && !answer.isBundled) {\n      result.push(`m-line ${index} is active but not bundled`);\n    }\n    if(offer.port === 0 && !offer.hasBundleOnly && answer.port !== 0) {\n      result.push(`m-line ${index} answer activates rejected offer section`);\n    }\n    if(answer.port !== 0 && answer.hasBundleOnly) {\n      result.push(`m-line ${index} active answer m-line has bundle-only`);\n    }\n    if(answer.port !== 0 && (answer.kind === 'audio' || answer.kind === 'video') && !answer.hasRtcpMux) {\n      result.push(`m-line ${index} is active RTP without rtcp-mux`);\n    }\n    if(answer.port !== 0 && answer.kind === 'video' && answer.direction !== 'recvonly' &&\n      answer.direction !== 'sendrecv') {\n      result.push(`m-line ${index} active video direction is ${answer.direction || 'missing'}`);\n    }\n    if(answer.port !== 0 && offer.port !== 0 && !offer.isBundled) {\n      result.push(`m-line ${index} answers an unbundled offer section`);\n    }\n\n    return result;\n  });\n  const data = {\n    mLines,\n    issues\n  };\n\n  if(issues.length) {\n    log.warn('remote answer SDP validation failed', data);\n  } else {\n    log('remote answer SDP validation passed', data);\n  }\n}\n\n// ===== Summaries / debug =====\n\nexport function summarizeTrack(track: MediaStreamTrack | undefined) {\n  if(!track) {\n    return undefined;\n  }\n\n  return {\n    id: track.id,\n    kind: track.kind,\n    enabled: track.enabled,\n    muted: track.muted,\n    readyState: track.readyState,\n    label: track.label\n  };\n}\n\nexport function summarizeContents(contents: P2PMediaContent[]) {\n  return contents.map((content, index) => {\n    return {\n      index,\n      type: content.type,\n      ssrc: content.ssrc,\n      ssrcGroups: content.ssrcGroups?.map((group) => {\n        return {\n          semantics: group.semantics,\n          count: group.ssrcs.length\n        };\n      }) || [],\n      payloads: content.payloadTypes?.map((payload) => {\n        return `${payload.id}:${payload.name}`;\n      }) || [],\n      extensions: content.rtpExtensions?.map((extension) => {\n        return `${extension.id}:${extension.uri}`;\n      }) || []\n    };\n  });\n}\n","/*\n * 1-on-1 phone call. CallInstance owns the call lifecycle (DH key exchange,\n * accept/confirm, signaling transport) and the tgcalls v2 (13.0.0) P2P engine:\n * RTCPeerConnection setup, ICE, SDP negotiation and media streams. The engine\n * is a port of Telegram Web A (telegram-tt) src/lib/vibecalls/phone/phoneCall.ts —\n * its state lives in `this.p2p` (created in joinPhoneCall, cleared in\n * stopPhoneCall; `!this.p2p` means the engine has not been started / is stopped).\n */\n\nimport {gzipSync} from 'fflate';\nimport gzipUncompress from '@helpers/gzipUncompress';\nimport ctx from '@environment/ctx';\nimport assumeType from '@helpers/assumeType';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {PhoneCall, PhoneCallDiscardReason, PhoneCallProtocol, PhoneConnection} from '@layer';\nimport {emojiFromCodePoints} from '@vendor/emoji';\nimport type {CallId} from '@appManagers/appCallsManager';\nimport type {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport CallInstanceBase from '@lib/calls/callInstanceBase';\nimport getAudioConstraints from '@lib/calls/helpers/getAudioConstraints';\nimport getStream from '@lib/calls/helpers/getStream';\nimport shouldMirrorVideoTrack from '@lib/calls/helpers/shouldMirrorVideoTrack';\nimport callsController from '@lib/calls/callsController';\nimport CALL_STATE from '@lib/calls/callState';\nimport {\n  GROUP_CALL_AMPLITUDE_ANALYSE_INTERVAL_MS,\n  P2P_MAX_PENDING_CANDIDATES,\n  P2P_SIGNALING_MAX_INFLATED_BYTES,\n  P2P_SIGNALING_MAX_QUEUED_PACKETS\n} from '@lib/calls/constants';\nimport getCallProtocol from '@lib/calls/p2P/getCallProtocol';\nimport P2PEncryptor from '@lib/calls/p2P/p2PEncryptor';\nimport ByteBuf from '@lib/calls/p2P/byteBuf';\nimport {isSctpPacket, SctpSignaling} from '@lib/calls/p2P/sctpSignaling';\nimport {black, silence} from '@lib/calls/p2P/fallbackMedia';\nimport {\n  ActiveLocalMedia,\n  buildIceServers,\n  buildSsrc,\n  Conference,\n  Connection,\n  filterRemoteVideoPayloadTypes,\n  getCandidateUfrag,\n  getDefaultAudioPayloadTypes,\n  getDefaultVideoPayloadTypes,\n  getRemoteDescriptionMids,\n  getRemoteDescriptionUfrags,\n  getStreamTrack,\n  getUserStream,\n  hasLiveTrack,\n  MediaMids,\n  normalizeCandidateComponent,\n  orderMediaContents,\n  parseInitialSetup,\n  parseMediaContent,\n  parseMediaContents,\n  parseMediaContentMids,\n  payloadTypeToConference,\n  QueuedCandidate,\n  SsrcEntry,\n  stopStream,\n  StreamType,\n  summarizeContents,\n  summarizeTrack,\n  tryAddCandidate,\n  validateRemoteAnswerSdp\n} from '@lib/calls/p2P/utils';\nimport {\n  getSdpDirection,\n  getSdpPort,\n  parseBundleMids,\n  parseExtmaps,\n  parsePayloadTypes,\n  parseSdpSections,\n  summarizeSdp,\n  SdpSection\n} from '@lib/calls/p2P/sdpCommon';\nimport {SDPBuilder} from '@lib/calls/sdpBuilder';\nimport StreamManager from '@lib/calls/streamManager';\nimport {CallMediaState, DiffieHellmanInfo, P2PMediaContent, P2PMessage} from '@lib/calls/types';\nimport {isSdpSafeContents, isSdpSafeSetup, isSdpSafeString} from '@lib/calls/helpers/sdpSafety';\n\nconst ICE_CANDIDATE_POOL_SIZE = 10;\nconst DEFAULT_AUDIO_MID = '0';\nconst DEFAULT_VIDEO_MID = '1';\nconst DEFAULT_PRESENTATION_MID = '2';\nconst DEFAULT_DATA_MID = '3';\nconst DATA_CHANNEL_ID = 0;\n\ntype RemoteMediaState = {\n  isMuted: boolean;\n  videoState: CallMediaState['videoState'];\n  videoRotation: CallMediaState['videoRotation'];\n  screencastState: CallMediaState['screencastState'];\n  isBatteryLow: boolean;\n};\n\ntype LocalMediaParameters = {\n  audioPayloadTypes: Conference['audioPayloadTypes'];\n  audioExtensions: Conference['audioExtensions'];\n  videoPayloadTypes: Conference['videoPayloadTypes'];\n  videoExtensions: Conference['videoExtensions'];\n};\n\n// A remote ICE candidate waiting for the negotiation it belongs to, stamped\n// with how many remote exchanges had been applied when it was queued — the\n// way to tell a candidate that arrived early from one whose exchange was\n// superseded and would otherwise wait forever.\ntype PendingCandidate = QueuedCandidate & {appliedExchanges: number};\n\ntype HangUpReason = Parameters<CallInstance['hangUp']>[0];\n\n// Live state of the P2P engine: the RTCPeerConnection, its transceivers/senders,\n// the media streams and all the negotiation bookkeeping. Created in joinPhoneCall,\n// cleared in stopPhoneCall.\ntype State = {\n  connection: RTCPeerConnection;\n  dataChannel?: RTCDataChannel;\n  isStarting?: boolean;\n  isMakingOffer?: boolean;\n  isUpdatingExclusiveVideo?: boolean;\n  remoteSetup?: Extract<P2PMessage, {'@type': 'InitialSetup'}>;\n  pendingRemoteNegotiation?: Extract<P2PMessage, {'@type': 'NegotiateChannels'}>;\n  queuedRemoteNegotiation?: Extract<P2PMessage, {'@type': 'NegotiateChannels'}>;\n  pendingLocalExchangeId?: string;\n  localCandidateExchangeId?: string;\n  pendingLocalContentMids?: Record<string, string>;\n  pendingRemoteContentMids?: Record<string, string>;\n  appliedRemoteExchangeId?: string;\n  appliedRemoteExchangeIds: Set<string>;\n  appliedRemoteUfrag?: string;\n  isApplyingRemoteNegotiation?: boolean;\n  handledRemoteExchangeIds: Set<string>;\n  pendingCandidates: PendingCandidate[];\n  transceivers: {\n    audio: RTCRtpTransceiver;\n    remoteAudio?: RTCRtpTransceiver;\n    video?: RTCRtpTransceiver;\n    presentation?: RTCRtpTransceiver;\n    remoteVideo?: RTCRtpTransceiver;\n    remotePresentation?: RTCRtpTransceiver;\n  };\n  senders: {\n    audio: RTCRtpSender;\n    video?: RTCRtpSender;\n    presentation?: RTCRtpSender;\n  };\n  streams: {\n    video?: MediaStream;\n    audio?: MediaStream;\n    presentation?: MediaStream;\n    ownAudio?: MediaStream;\n    ownVideo?: MediaStream;\n    ownPresentation?: MediaStream;\n  };\n  audioContext: AudioContext;\n  silence: MediaStream;\n  blackVideo: MediaStream;\n  blackPresentation: MediaStream;\n  remoteMediaState: RemoteMediaState;\n  audio: HTMLAudioElement;\n  facingMode?: VideoFacingModeEnum;\n  exchangeId: number;\n  lastLocalSetupKey?: string;\n};\n\n// An update emitted by the P2P engine and routed back into the UI.\ntype Update =\n  {'@type': 'updatePhoneCallConnectionState', connectionState: RTCPeerConnectionState} |\n  ({'@type': 'updatePhoneCallMediaState'} & RemoteMediaState);\n\nexport default class CallInstance extends CallInstanceBase<{\n  state: (state: CALL_STATE) => void,\n  id: (id: CallId, prevId: CallId) => void,\n  muted: (muted: boolean) => void,\n  mediaState: (mediaState: CallMediaState) => void,\n  acceptCallOverride: (accept: () => Promise<void>) => Promise<void>,\n}> {\n  public dh: Partial<DiffieHellmanInfo.a & DiffieHellmanInfo.b>;\n  public id: CallId;\n  public call: PhoneCall;\n  public interlocutorUserId: UserId;\n  public protocol: PhoneCallProtocol;\n  public isOutgoing: boolean;\n  public encryptionKey: Uint8Array;\n  // Guards the peer-g_a verification in CallsController: it spans two awaits, and\n  // without a flag a second (forged) `phoneCall` update could race through them.\n  public isVerifyingPeerG_a: boolean;\n  // One P2PEncryptor per call handles BOTH directions — encrypt and decrypt use\n  // complementary `x` key-derivation offsets internally, so a single instance\n  // (constructed with this peer's real isOutgoing) is correct for send + receive.\n  public encryptor: P2PEncryptor;\n\n  // SCTP framing for the 13.0.0 signaling protocol; undefined when the call\n  // negotiated network_signaling_nosctp (then the encrypted blob is sent raw).\n  private sctp: SctpSignaling | undefined;\n\n  public createdParticipantEntries: boolean;\n  public release: () => Promise<void>;\n  public _connectionState: CALL_STATE;\n\n  public createdAt: number;\n  public connectedAt: number;\n  public discardReason: PhoneCallDiscardReason;\n\n  // Kept only to satisfy CallInstanceBase (its cleanup() stops it); the P2P\n  // engine owns the actual RTCPeerConnection, streams and tracks.\n  public streamManager: StreamManager;\n\n  public wasTryingToJoin: boolean;\n\n  private managers: AppManagers;\n  private hangUpTimeout: number;\n  private hangUpStarted = false;\n\n  private joined: boolean;\n  private p2pConnectionState: RTCPeerConnectionState;\n  private outputMediaState: CallMediaState;\n  private videoElements: Map<CallMediaState['type'], HTMLVideoElement>;\n\n  private decryptQueue: Uint8Array[];\n  private decryptQueuePromise: Promise<void>;\n\n  private getEmojisFingerprintPromise: Promise<CallInstance['emojisFingerprint']>;\n  private emojisFingerprint: [string, string, string, string];\n\n  // Live tgcalls v2 P2P engine state; undefined until joinPhoneCall, cleared by\n  // stopPhoneCall. `!this.p2p` means the engine is not running.\n  private p2p: State;\n\n  // P2P keeps its real local streams outside StreamManager, so device swaps\n  // share the base class generation/queue but commit into the live p2p state.\n  // Acquisitions may overlap; sender replacement is serialized per kind.\n  private async replaceP2pInputDevice(\n    kind: 'audio' | 'video',\n    constraints: MediaStreamConstraints\n  ): Promise<boolean> {\n    const initialState = this.p2p;\n    if(!initialState || (kind === 'audio' ? this.isMuted : !this.isSharingVideo)) return true;\n\n    return this.runInputDeviceSwap({\n      kind,\n      constraints,\n      acquisitionFailureLogLevel: 'warn',\n      release: (stream) => stopStream(stream),\n      shouldAbandon: (site, generation) => {\n        if(site === 'acquired') {\n          if(this.p2p !== initialState || this.isClosing) return true;\n          if(!this.isMediaDeviceChangeCurrent(kind, generation) || (kind === 'audio' && this.isMuted)) return false;\n          return undefined;\n        }\n        if(site === 'queued') {\n          if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n          if(this.p2p !== initialState || this.isClosing) return true;\n          if(kind === 'audio' && this.isMuted) return false;\n          return undefined;\n        }\n        if(site === 'failed') {\n          if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n          if(this.p2p !== initialState || this.isClosing) return true;\n          return undefined;\n        }\n        // 'swapped': a replaced/closed call must never be rolled back into.\n        if(this.p2p !== initialState || this.isClosing) return true;\n        if(!this.isMediaDeviceChangeCurrent(kind, generation)) return false;\n        return undefined;\n      },\n      resolveSwap: (newTrack) => {\n        const state = initialState;\n        const sender = state.senders[kind];\n        const oldStream = kind === 'audio' ? state.streams.ownAudio : state.streams.ownVideo;\n        const oldTrack = oldStream?.getTracks().find((track) => track.kind === kind);\n        if(!sender || !oldTrack) return undefined;\n        return {\n          oldTrack,\n          swap: () => sender.replaceTrack(newTrack),\n          rollback: async() => {\n            // Only restore a sender that still belongs to this p2p state and\n            // still carries the replacement track.\n            if(this.p2p === state && !this.isClosing && sender.track === newTrack) {\n              await sender.replaceTrack(oldTrack);\n            }\n          }\n        };\n      },\n      // A rejected single-sender replaceTrack leaves the old track in place\n      // per spec — compensating would only double the churn.\n      rollbackOnSwapFailure: false,\n      getPendingAudioEnabled: () => !this.isMuted,\n      commit: (newStream) => {\n        const state = initialState;\n        const oldStream = kind === 'audio' ? state.streams.ownAudio : state.streams.ownVideo;\n        const fallback = kind === 'audio' ? state.silence : state.blackVideo;\n        stopStream(oldStream, fallback);\n        if(kind === 'audio') {\n          state.streams.ownAudio = newStream;\n        } else {\n          state.streams.ownVideo = newStream;\n          const inputElement = this.videoElements.get('input');\n          if(inputElement) inputElement.srcObject = newStream;\n        }\n\n        this.updateStreams();\n        this.sendLocalMediaState();\n      }\n    });\n  }\n\n  public setInputVideoDeviceId(deviceId: string): Promise<boolean> {\n    return this.replaceP2pInputDevice('video', {\n      video: deviceId ? {deviceId: {exact: deviceId}} : true\n    });\n  }\n\n  public setInputAudioDeviceId(deviceId: string): Promise<boolean> {\n    return this.replaceP2pInputDevice('audio', {\n      audio: getAudioConstraints(deviceId)\n    });\n  }\n\n  protected getOutputDeviceElements(): Iterable<HTMLMediaElement> {\n    const elements = [...super.getOutputDeviceElements()];\n    if(this.p2p?.audio) elements.push(this.p2p.audio);\n    return elements;\n  }\n\n  // Serializes data-channel signaling messages so they are processed in order.\n  private dataChannelSignalingMessagePromise: Promise<void>;\n\n  constructor(options: {\n    isOutgoing: boolean,\n    interlocutorUserId: UserId,\n    managers: CallInstance['managers'],\n    protocol?: PhoneCallProtocol\n  }) {\n    super();\n\n    this.log = logger('CALL');\n\n    if(!this.protocol) {\n      this.protocol = getCallProtocol();\n    }\n\n    safeAssign(this, options);\n\n    this.createdAt = performance.now();\n    this.joined = false;\n    this.decryptQueue = [];\n    this.decryptQueuePromise = Promise.resolve();\n    this.dataChannelSignalingMessagePromise = Promise.resolve();\n    this.videoElements = new Map();\n    this.streamManager = new StreamManager(GROUP_CALL_AMPLITUDE_ANALYSE_INTERVAL_MS);\n\n    this.addEventListener('state', (state) => {\n      this.log('state', CALL_STATE[state]);\n\n      if(state === CALL_STATE.CLOSED) {\n        this.cleanup();\n      }\n    });\n  }\n\n  get connectionState() {\n    if(this._connectionState !== undefined) {\n      return this._connectionState;\n    }\n\n    switch(this.p2pConnectionState) {\n      case 'connected':\n        return CALL_STATE.CONNECTED;\n      case 'failed':\n      case 'closed':\n        return CALL_STATE.CLOSED;\n      default:\n        return CALL_STATE.CONNECTING;\n    }\n  }\n\n  get sortIndex() {\n    const connectionState = this.connectionState;\n    const state = CALL_STATE.CLOSED - connectionState + 1;\n    let index = state * 10000000000000;\n    index += 2147483647000 - (connectionState === CALL_STATE.PENDING && this.isOutgoing ? 0 : this.createdAt);\n    return index;\n  }\n\n  // The P2P engine owns the RTCPeerConnection — there is no LocalConferenceDescription.\n  public get description(): any {\n    return undefined;\n  }\n\n  // Media is acquired by the P2P engine; skip CallInstanceBase's stream pre-prompt.\n  public requestInputSource() {\n    return Promise.resolve();\n  }\n\n  public getVideoElement(type: CallMediaState['type']) {\n    const streams = this.getStreams();\n    if(!streams) {\n      return undefined;\n    }\n\n    const stream = type === 'input' ?\n      (this.isSharingScreen ? streams.ownPresentation : streams.ownVideo) :\n      (streams.presentation || streams.video);\n    if(!stream) {\n      return undefined;\n    }\n\n    let element = this.videoElements.get(type);\n    if(!element) {\n      element = document.createElement('video');\n      element.autoplay = true;\n      element.muted = true;\n      element.setAttribute('playsinline', 'true');\n      // Mirror ONLY our own self-view (`type === 'input'`), never the remote\n      // peer's video — same rule as callInstanceBase.tryAddTrack and every\n      // other client (iOS/tgcalls, FaceTime, …). The flip is a local \"looking\n      // in a mirror\" convenience; the wire carries un-mirrored frames, so the\n      // peer sees us as in real life. Mirroring their feed would invert any\n      // text they hold up. Rear-facing own camera (`facingMode === 'environment'`)\n      // stays un-mirrored — handled by shouldMirrorVideoTrack.\n      const track = stream.getVideoTracks()[0];\n      if(type === 'input' && shouldMirrorVideoTrack(track)) {\n        element.classList.add('call-video-mirror');\n      }\n      this.videoElements.set(type, element);\n    }\n\n    if(element.srcObject !== stream) {\n      element.srcObject = stream;\n    }\n\n    return element;\n  }\n\n  public toggleScreenSharing() {\n    return this.toggleStream('presentation').then(() => {\n      this.dispatchEvent('mediaState', this.getMediaState('input'));\n    });\n  }\n\n  public toggleVideoSharing() {\n    return this.toggleStream('video').then(() => {\n      this.dispatchEvent('mediaState', this.getMediaState('input'));\n    });\n  }\n\n  private getOwnTrackEnabled(streamType: StreamType) {\n    const streams = this.getStreams();\n    const stream = streamType === 'audio' ? streams?.ownAudio :\n      (streamType === 'video' ? streams?.ownVideo : streams?.ownPresentation);\n    return !!stream?.getTracks()[0]?.enabled;\n  }\n\n  public getMediaState(type: CallMediaState['type']): CallMediaState {\n    if(type === 'output') {\n      return this.outputMediaState;\n    }\n\n    return {\n      '@type': 'MediaState',\n      'type': 'input',\n      'muted': this.isMuted,\n      'lowBattery': false,\n      'screencastState': this.isSharingScreen ? 'active' : 'inactive',\n      'videoRotation': 0,\n      'videoState': this.isSharingVideo ? 'active' : 'inactive'\n    };\n  }\n\n  public setMediaState(mediaState: CallMediaState) {\n    this.outputMediaState = mediaState;\n    this.dispatchEvent('mediaState', mediaState);\n  }\n\n  public get isSharingVideo() {\n    return this.getOwnTrackEnabled('video');\n  }\n\n  public get isSharingAudio() {\n    return this.getOwnTrackEnabled('audio');\n  }\n\n  public get isSharingScreen() {\n    return this.getOwnTrackEnabled('presentation');\n  }\n\n  public get isMuted() {\n    return !this.getOwnTrackEnabled('audio');\n  }\n\n  public get isClosing() {\n    const {connectionState} = this;\n    return connectionState === CALL_STATE.CLOSING || connectionState === CALL_STATE.CLOSED;\n  }\n\n  // The reason may be decided when the timer fires: an unanswered incoming\n  // call is \"missed\" — unless another call is still up by then, which makes\n  // it \"busy\".\n  public setHangUpTimeout(timeout: number, reason: HangUpReason | (() => HangUpReason)) {\n    this.clearHangUpTimeout();\n    this.hangUpTimeout = ctx.setTimeout(() => {\n      this.hangUpTimeout = undefined;\n      void this.hangUp(typeof(reason) === 'function' ? reason() : reason).catch((err) => {\n        this.log.error('timed P2P hangup failed', err);\n      });\n    }, timeout);\n  }\n\n  public clearHangUpTimeout() {\n    if(this.hangUpTimeout !== undefined) {\n      clearTimeout(this.hangUpTimeout);\n      this.hangUpTimeout = undefined;\n    }\n  }\n\n  public setPhoneCall(phoneCall: PhoneCall) {\n    this.call = phoneCall;\n\n    const {id} = phoneCall;\n    if(this.id !== id) {\n      const prevId = this.id;\n      this.id = id;\n      this.dispatchEvent('id', id, prevId);\n    }\n  }\n\n  public async acceptCall() {\n    if(this.isClosing) return;\n\n    let acceptPromise: Promise<void> | undefined;\n    const accept = () => acceptPromise ||= this.acceptCallInternal();\n    const overrides = this.dispatchResultableEvent('acceptCallOverride', accept);\n    if(overrides.length) {\n      // The override owns the transaction. AppImManager uses this to run both\n      // leave-current-call and the full accept RPC under one global call-switch\n      // reservation; falling through here would accept outside that lock.\n      await Promise.all(overrides);\n      return;\n    }\n\n    await accept();\n  }\n\n  private async acceptCallInternal(): Promise<void> {\n    if(this.isClosing) return;\n\n    this.overrideConnectionState(CALL_STATE.EXCHANGING_KEYS);\n\n    const call = this.call as PhoneCall.phoneCallRequested;\n    const {g_a_hash} = call;\n    try {\n      const dh = await this.managers.appCallsManager.generateDh();\n      if(this.isClosing) return;\n\n      this.dh = { // ! it is correct\n        g_a_hash,\n        b: dh.a,\n        g_b: dh.g_a,\n        g_b_hash: dh.g_a_hash,\n        p: dh.p\n      };\n\n      const acceptedCall = await this.managers.appCallsManager.acceptCall(\n        this.id,\n        this.protocol,\n        this.dh.g_b,\n        call.pFlags.video\n      );\n      if(this.isClosing && acceptedCall._ !== 'phoneCallEmpty' && acceptedCall._ !== 'phoneCallDiscarded') {\n        // The server accepted while a local hangup was already closing this\n        // instance. Compensate the exact echoed call instead of publishing a\n        // late accepted state that can overlap the next global transition.\n        await this.managers.appCallsManager.discardCall(\n          acceptedCall.id,\n          0,\n          {_: 'phoneCallDiscardReasonHangup'},\n          call.pFlags.video\n        );\n      }\n    } catch(err) {\n      this.log.error('accept call error', err);\n      if(!this.isClosing) {\n        try {\n          await this.hangUp('phoneCallDiscardReasonHangup');\n        } catch(hangUpError) {\n          this.log.error('hang up after accept call error failed', hangUpError);\n        }\n      }\n    }\n  }\n\n  public async confirmCall() {\n    if(this.isClosing) return;\n\n    // A redelivered phoneCallAccepted (getDifference, a second tab's copy of\n    // the update) must not run the exchange twice: the second\n    // phone.confirmCall fails on the server and that would drop a call that is\n    // already connecting. tdesktop bails the same way (`confirmAcceptedCall`:\n    // ExchangingKeys || _instance).\n    if(this.encryptionKey || this.joined || this.connectionState === CALL_STATE.EXCHANGING_KEYS) {\n      this.log.warn('ignoring a repeated phoneCallAccepted', this.id);\n      return;\n    }\n\n    const {protocol, id} = this;\n    const call = this.call as PhoneCall.phoneCallAccepted;\n    const dh = this.dh as DiffieHellmanInfo.a;\n\n    this.overrideConnectionState(CALL_STATE.EXCHANGING_KEYS);\n\n    try {\n      // g_b is the peer value relayed by the server; computeKey rejects a\n      // degenerate/out-of-range one before it can force the call key.\n      const {key, key_fingerprint} = await this.managers.appCallsManager.computeKey(\n        call.g_b,\n        dh.a,\n        dh.p\n      );\n      if(this.isClosing) return;\n\n      const confirmedCall = await this.managers.appCallsManager.confirmCall(\n        id,\n        protocol,\n        dh.g_a,\n        key_fingerprint,\n        call.pFlags.video\n      );\n      if(this.isClosing) {\n        if(confirmedCall._ !== 'phoneCallEmpty' && confirmedCall._ !== 'phoneCallDiscarded') {\n          await this.managers.appCallsManager.discardCall(\n            confirmedCall.id,\n            0,\n            {_: 'phoneCallDiscardReasonHangup'},\n            call.pFlags.video\n          );\n        }\n        return;\n      }\n\n      this.encryptionKey = key;\n      this.joinCall();\n    } catch(err) {\n      this.log.error('confirmCall error', err);\n      if(!this.isClosing) {\n        try {\n          await this.hangUp('phoneCallDiscardReasonHangup');\n        } catch(hangUpError) {\n          this.log.error('hang up after confirm call error failed', hangUpError);\n        }\n      }\n    }\n  }\n\n  public joinCall() {\n    if(this.joined) {\n      return;\n    }\n\n    this.log('joinCall');\n    this.joined = true;\n\n    void Promise.resolve(this.getEmojisFingerprint()).catch((err) => {\n      this.log.error('emoji fingerprint derivation failed', err);\n    });\n\n    const call = this.call as PhoneCall.phoneCall;\n    const {isOutgoing, encryptionKey} = this;\n\n    this.encryptor = new P2PEncryptor(isOutgoing, encryptionKey);\n    this.sctp = this.getCustomParam('network_signaling_nosctp') ? undefined : new SctpSignaling();\n\n    const connections: Connection[] = (call.connections || [])\n    .filter((connection): connection is PhoneConnection.phoneConnectionWebrtc => {\n      return connection._ === 'phoneConnectionWebrtc';\n    })\n    .map((connection) => ({\n      ip: connection.ip,\n      ipv6: connection.ipv6,\n      port: +connection.port,\n      username: connection.username,\n      password: connection.password,\n      isTurn: !!connection.pFlags.turn,\n      isStun: !!connection.pFlags.stun\n    }));\n\n    void this.joinPhoneCall(\n      connections,\n      !!call.pFlags.video,\n      !!call.pFlags.p2p_allowed\n    ).catch(async(err) => {\n      this.log.error('joinPhoneCall error', err);\n      try {\n        await this.hangUp('phoneCallDiscardReasonDisconnect');\n      } catch(hangUpError) {\n        this.log.error('hang up after joinPhoneCall failure failed', hangUpError);\n      }\n    });\n\n    // clear the EXCHANGING_KEYS override → connectionState now follows the p2p engine\n    this.overrideConnectionState();\n\n    this.scheduleDecryptQueueProcessing();\n  }\n\n  public async sendCallSignalingData(data: P2PMessage) {\n    const json = JSON.stringify(data);\n    // 13.0.0 (v3): gzip the JSON payload inside the encrypted packet.\n    const gzipped = gzipSync(new TextEncoder().encode(json));\n    const {bytes} = await this.encryptor.encryptRawPacket(gzipped);\n\n    this.log('sendCallSignalingData', this.id, json);\n\n    if(this.sctp) {\n      // wrap the encrypted blob in an SCTP DATA packet (or an INIT during handshake)\n      const packet = this.sctp.wrapPayload(ByteBuf.wrap(bytes));\n      if(packet) {\n        await this.sendSignalingRaw(packet);\n      }\n\n      await this.drainSctp();\n    } else {\n      await this.sendSignalingRaw(bytes);\n    }\n  }\n\n  private async sendSignalingRaw(packet: number[] | Uint8Array) {\n    await this.managers.appCallsManager.sendSignalingData(\n      this.id,\n      packet instanceof Uint8Array ? packet : new Uint8Array(packet)\n    );\n  }\n\n  private sendCallSignalingDataDetached(data: P2PMessage, context: string): void {\n    void this.sendCallSignalingData(data).catch((err) => {\n      this.log.error(context, err);\n    });\n  }\n\n  // Flush SCTP control packets (INIT/COOKIE/SACK/heartbeat) produced as a side effect.\n  private async drainSctp() {\n    if(!this.sctp) {\n      return;\n    }\n\n    for(const packet of this.sctp.drainPackets()) {\n      await this.sendSignalingRaw(packet);\n    }\n  }\n\n  private getCustomParam(key: string) {\n    const customParameters = (this.call as PhoneCall.phoneCall)?.custom_parameters;\n    if(customParameters?._ !== 'dataJSON') {\n      return undefined;\n    }\n\n    try {\n      return JSON.parse(customParameters.data)?.[key];\n    } catch(err) {\n      return undefined;\n    }\n  }\n\n  private onUpdate(update: Update) {\n    switch(update['@type']) {\n      case 'updatePhoneCallConnectionState': {\n        this.p2pConnectionState = update.connectionState;\n        if(update.connectionState === 'connected' && this.connectedAt === undefined) {\n          this.connectedAt = performance.now();\n        }\n\n        // a live engine state supersedes the EXCHANGING_KEYS override\n        this._connectionState = undefined;\n\n        if(update.connectionState === 'failed') {\n          // hangUpStarted, rather than the derived CLOSED state, owns idempotency:\n          // a failed RTCPeerConnection makes connectionState CLOSED before we\n          // have sent phone.discardCall. Let hangUp capture hasVideo, stop every\n          // local track and publish the server discard as one transaction.\n          void this.hangUp('phoneCallDiscardReasonDisconnect').catch((err) => {\n            this.log.error('discard after P2P transport failure failed', err);\n          });\n          break;\n        }\n\n        this.dispatchEvent('state', this.connectionState);\n\n        if(update.connectionState === 'closed') {\n          // A locally-closed transport may arrive after the call is already\n          // discarded. Release media idempotently without publishing a second\n          // server mutation.\n          try {\n            this.stopPhoneCall();\n          } catch(err) {\n            this.log.error('stopPhoneCall error', err);\n          }\n        }\n        break;\n      }\n\n      case 'updatePhoneCallMediaState': {\n        this.setMediaState({\n          '@type': 'MediaState',\n          'type': 'output',\n          'muted': update.isMuted,\n          'lowBattery': update.isBatteryLow,\n          'screencastState': update.screencastState === 'active' ? 'active' : 'inactive',\n          'videoRotation': update.videoRotation || 0,\n          'videoState': update.videoState === 'active' ? 'active' : 'inactive'\n        });\n        break;\n      }\n    }\n  }\n\n  public getEmojisFingerprint() {\n    if(this.emojisFingerprint) return this.emojisFingerprint;\n    if(this.getEmojisFingerprintPromise) return this.getEmojisFingerprintPromise;\n    const promise = apiManagerProxy.invokeCrypto(\n      'get-emojis-fingerprint',\n      this.encryptionKey,\n      this.dh.g_a\n    ).then((codePoints) => {\n      if(this.getEmojisFingerprintPromise === promise) {\n        this.getEmojisFingerprintPromise = undefined;\n      }\n      return this.emojisFingerprint = codePoints.map(\n        (codePoints) => emojiFromCodePoints(codePoints)\n      ) as [string, string, string, string];\n    }).catch((err) => {\n      // Crypto-worker/proxy failures can be transient. Keep concurrent callers\n      // coalesced onto this rejection, but do not poison the SAS for the rest\n      // of the call: reopening the popup must be able to retry derivation.\n      if(this.getEmojisFingerprintPromise === promise) {\n        this.getEmojisFingerprintPromise = undefined;\n      }\n      throw err;\n    });\n    this.getEmojisFingerprintPromise = promise;\n    return promise;\n  }\n\n  public overrideConnectionState(state?: CALL_STATE) {\n    this._connectionState = state;\n    this.dispatchEvent('state', this.connectionState);\n  }\n\n  public get duration() {\n    return this.connectedAt !== undefined ? (performance.now() - this.connectedAt) / 1000 | 0 : 0;\n  }\n\n  public toggleMuted(): Promise<void> {\n    return this.toggleStream('audio').finally(() => {\n      this.dispatchEvent('muted', this.isMuted);\n      this.dispatchEvent('mediaState', this.getMediaState('input'));\n    });\n  }\n\n  public async hangUp(\n    discardReason?: PhoneCallDiscardReason | Exclude<PhoneCallDiscardReason['_'], PhoneCallDiscardReason.phoneCallDiscardReasonMigrateConferenceCall['_']>,\n    discardedByOtherParty?: boolean\n  ) {\n    if(this.hangUpStarted) {\n      return;\n    }\n    this.hangUpStarted = true;\n\n    discardReason = typeof(discardReason) === 'string' ? {_: discardReason} : discardReason;\n    assumeType<PhoneCallDiscardReason>(discardReason);\n\n    this.discardReason = discardReason;\n    this.log('hangUp', discardReason);\n\n    const hasVideo = this.isSharingVideo || this.isSharingScreen;\n\n    this.overrideConnectionState(CALL_STATE.CLOSED);\n\n    try {\n      this.stopPhoneCall();\n    } catch(err) {\n      this.log.error('stopPhoneCall error', err);\n    }\n\n    if(discardReason && !discardedByOtherParty) {\n      await this.managers.appCallsManager.discardCall(this.id, this.duration, discardReason, hasVideo);\n    }\n  }\n\n  private async processDecryptQueue() {\n    const {encryptor} = this;\n    if(!encryptor) {\n      this.log.warn('got encrypted signaling data before the encryption key');\n      return;\n    }\n\n    const length = this.decryptQueue.length;\n    if(!length) {\n      return;\n    }\n\n    const queue = this.decryptQueue.slice();\n    this.decryptQueue.length = 0;\n\n    for(const data of queue) {\n      // a v3 packet may be SCTP-wrapped and carry several encrypted payloads\n      const incoming = ByteBuf.wrap(data);\n      const bodies = this.sctp && isSctpPacket(incoming) ? this.sctp.receive(incoming) : [incoming];\n\n      for(const body of bodies) {\n        const decryptedData = await encryptor.decryptRawPacket(body);\n        if(!decryptedData) {\n          continue;\n        }\n\n        // 13.0.0 (v3): the payload is gzipped (magic 1f 8b); older protocols send it raw.\n        // Inflate through the size-bounded streaming path: gunzipSync sizes its\n        // output by the trailer's ISIZE, so the peer could make a 1 MiB packet\n        // reserve gigabytes. tgcalls caps the inflated size the same way.\n        const payload = decryptedData[0] === 0x1F && decryptedData[1] === 0x8B ?\n          gzipUncompress(decryptedData, false, P2P_SIGNALING_MAX_INFLATED_BYTES) as Uint8Array :\n          decryptedData;\n        const str = new TextDecoder().decode(payload);\n        let signalingData: P2PMessage;\n        try {\n          signalingData = JSON.parse(str);\n        } catch(err) {\n          this.log.error('wrong signaling data', str);\n          try {\n            await this.hangUp('phoneCallDiscardReasonDisconnect');\n          } catch(hangUpError) {\n            this.log.error('hang up after invalid signaling data failed', hangUpError);\n          }\n          callsController.dispatchEvent('incompatible', this.interlocutorUserId);\n          continue;\n        }\n\n        this.log('[update] updateNewCallSignalingData', signalingData);\n        await this.processSignalingMessage(signalingData);\n      }\n    }\n\n    // SCTP receive() may have produced SACK/ACK packets that must go back to the peer\n    await this.drainSctp();\n  }\n\n  public onUpdatePhoneCallSignalingData(data: Uint8Array) {\n    this.decryptQueue.push(data);\n\n    // Packets wait here only until the key is derived (and while the previous\n    // batch decrypts); the peer must not be able to grow that wait forever.\n    const overflow = this.decryptQueue.length - P2P_SIGNALING_MAX_QUEUED_PACKETS;\n    if(overflow > 0) {\n      this.decryptQueue.splice(0, overflow);\n      this.log.warn('dropping the oldest queued signaling packets', {overflow});\n    }\n\n    this.scheduleDecryptQueueProcessing();\n  }\n\n  private scheduleDecryptQueueProcessing(): void {\n    const processing = this.decryptQueuePromise.catch(() => {}).then(() => {\n      return this.processDecryptQueue();\n    });\n    this.decryptQueuePromise = processing;\n    void processing.catch((err) => {\n      this.log.error('P2P signaling processing failed', err);\n      void this.hangUp('phoneCallDiscardReasonDisconnect').catch((hangUpError) => {\n        this.log.error('hang up after P2P signaling failure failed', hangUpError);\n      });\n    });\n  }\n\n  // ===== tgcalls v2 P2P engine =====\n  // Connection setup + signaling negotiation, folded in from the former\n  // p2P/p2pCall.ts module. The engine reads/writes `this.p2p`; signaling goes out\n  // through this.sendCallSignalingData and engine updates come back via this.onUpdate.\n\n  private getStreams() {\n    return this.p2p?.streams;\n  }\n\n  private updateStreams() {\n    if(!this.p2p) return;\n\n    this.onUpdate({\n      ...this.p2p.remoteMediaState,\n      '@type': 'updatePhoneCallMediaState'\n    });\n  }\n\n  private getSender(streamType: StreamType) {\n    if(!this.p2p) return undefined;\n\n    if(streamType === 'audio') return this.p2p.senders.audio;\n    if(streamType === 'video') return this.p2p.senders.video;\n    return this.p2p.senders.presentation;\n  }\n\n  private getTransceiver(streamType: StreamType) {\n    if(!this.p2p) return undefined;\n\n    if(streamType === 'audio') return this.p2p.transceivers.audio;\n    if(streamType === 'video') return this.p2p.transceivers.video;\n    return this.p2p.transceivers.presentation;\n  }\n\n  private setLocalVideoTransceiver(\n    streamType: Extract<StreamType, 'video' | 'presentation'>,\n    transceiver: RTCRtpTransceiver\n  ) {\n    if(!this.p2p) return;\n\n    if(streamType === 'video') {\n      this.p2p.transceivers.video = transceiver;\n      this.p2p.senders.video = transceiver.sender;\n    } else {\n      this.p2p.transceivers.presentation = transceiver;\n      this.p2p.senders.presentation = transceiver.sender;\n    }\n  }\n\n  private setOwnStream(streamType: StreamType, stream: MediaStream) {\n    if(!this.p2p) return;\n\n    if(streamType === 'audio') {\n      this.p2p.streams.ownAudio = stream;\n    } else if(streamType === 'video') {\n      this.p2p.streams.ownVideo = stream;\n    } else {\n      this.p2p.streams.ownPresentation = stream;\n    }\n  }\n\n  private getOwnStream(streamType: StreamType) {\n    if(!this.p2p) return undefined;\n\n    if(streamType === 'audio') return this.p2p.streams.ownAudio;\n    if(streamType === 'video') return this.p2p.streams.ownVideo;\n    return this.p2p.streams.ownPresentation;\n  }\n\n  private getFallbackStream(streamType: StreamType) {\n    if(!this.p2p) return undefined;\n\n    if(streamType === 'audio') return this.p2p.silence;\n    if(streamType === 'video') return this.p2p.blackVideo;\n    return this.p2p.blackPresentation;\n  }\n\n  public async switchCameraInput() {\n    if(!this.p2p || !this.p2p.facingMode) {\n      return;\n    }\n\n    const sender = this.getSender('video');\n    if(!sender) {\n      this.log('switch camera skipped: missing sender');\n      return;\n    }\n\n    const nextFacingMode = this.p2p.facingMode === 'environment' ? 'user' : 'environment';\n\n    let newStream: MediaStream | undefined;\n    try {\n      newStream = await getUserStream('video', nextFacingMode);\n      const newTrack = getStreamTrack(newStream);\n      if(!newTrack) {\n        stopStream(newStream);\n        return;\n      }\n\n      const oldStream = this.p2p.streams.ownVideo;\n      await sender.replaceTrack(newTrack);\n      this.p2p.facingMode = nextFacingMode;\n      this.p2p.streams.ownVideo = newStream;\n      stopStream(oldStream, this.p2p.blackVideo);\n      this.updateStreams();\n      this.sendLocalMediaState();\n    } catch{\n      stopStream(newStream);\n      this.log('switch camera failed');\n      // Ignore camera switch failures; the previous track stays active.\n    }\n  }\n\n  private async toggleStream(streamType: StreamType, value: boolean | undefined = undefined) {\n    if(!this.p2p) return;\n\n    const initialState = this.p2p;\n    const stream = this.getOwnStream(streamType);\n    const track = getStreamTrack(stream);\n    const sender = this.getSender(streamType);\n\n    if(!track || (streamType === 'audio' && !sender)) {\n      this.log('toggle skipped: missing track or sender', {\n        streamType,\n        track: summarizeTrack(track),\n        hasSender: Boolean(sender)\n      });\n      throw new Error(`Could not toggle ${streamType}: missing local track or sender`);\n    }\n\n    const shouldEnable = value === undefined ? !track.enabled : value;\n    if(streamType === 'audio' && shouldEnable !== track.enabled) {\n      // A mute/unmute action supersedes any microphone picker transaction\n      // that acquired or installed a track from the previous capture state.\n      this.beginMediaDeviceChange('audio');\n    }\n\n    try {\n      let hasChanged = false;\n      let shouldRenegotiate = false;\n      if(shouldEnable && !track.enabled) {\n        const facingMode = streamType === 'video' ? this.p2p.facingMode || 'user' : undefined;\n        const newStream = await getUserStream(streamType, facingMode);\n        const newTrack = getStreamTrack(newStream);\n        if(!newTrack) {\n          stopStream(newStream);\n          throw new Error(`Could not enable ${streamType}: media capture returned no track`);\n        }\n\n        let isNewStreamStopped = false;\n        const stopNewStream = () => {\n          if(isNewStreamStopped) return;\n          isNewStreamStopped = true;\n          stopStream(newStream);\n        };\n\n        try {\n          if(this.p2p !== initialState || this.isClosing) {\n            throw new Error(`Could not enable ${streamType}: call closed during media capture`);\n          }\n\n          newTrack.onended = () => {\n            void this.toggleStream(streamType, false).catch((err) => {\n              this.log('track-ended toggle failed', {streamType, error: err});\n            });\n          };\n\n          let transceiver = this.getTransceiver(streamType);\n          const previousDirection = transceiver?.direction;\n          const previousFacingMode = initialState.facingMode;\n          const shouldCreateVideoTransceiver = streamType !== 'audio' &&\n            (!sender || !transceiver || transceiver.currentDirection === 'stopped');\n          if(shouldCreateVideoTransceiver) {\n            transceiver = this.p2p.connection.addTransceiver(newTrack, {\n              direction: 'sendrecv',\n              streams: [newStream]\n            });\n            this.setLocalVideoTransceiver(streamType, transceiver);\n            shouldRenegotiate = true;\n          } else {\n            await sender!.replaceTrack(newTrack);\n          }\n          // stopPhoneCall clears `this.p2p` and only stops streams already\n          // registered in its state. If hangup wins while replaceTrack is\n          // pending, this newly-acquired stream is otherwise orphaned and can\n          // keep the microphone/camera/screen capture indicator alive.\n          if(this.p2p !== initialState || this.isClosing) {\n            throw new Error(`Could not enable ${streamType}: call closed during sender replacement`);\n          }\n          if(transceiver && streamType !== 'audio') {\n            shouldRenegotiate ||= !transceiver.mid || transceiver.currentDirection === 'inactive';\n            transceiver.direction = 'sendrecv';\n          }\n          this.setOwnStream(streamType, newStream);\n\n          if(streamType === 'video' || streamType === 'presentation') {\n            const enabledSender = this.getSender(streamType);\n            initialState.isUpdatingExclusiveVideo = true;\n            try {\n              await this.toggleStream(streamType === 'video' ? 'presentation' : 'video', false);\n              if(this.p2p !== initialState || this.isClosing) {\n                throw new Error(`Could not enable ${streamType}: call closed during exclusive media update`);\n              }\n            } catch(err) {\n              // End the new capture before attempting an async sender rollback.\n              // Even a stuck/rejected rollback can no longer leave camera and\n              // screen capture live at the same time.\n              stopNewStream();\n\n              // The newly-enabled sender is already live at this point, while\n              // the opposite sender rejected its fallback. Restore our exact\n              // previous stream/direction as well as stopping capture, so the\n              // engine state cannot retain a half-committed exclusive stream.\n              if(this.p2p === initialState) {\n                if(enabledSender) {\n                  try {\n                    await enabledSender.replaceTrack(track);\n                  } catch(rollbackError) {\n                    this.log('exclusive stream rollback failed', {\n                      streamType,\n                      error: rollbackError instanceof Error ? rollbackError.message : String(rollbackError)\n                    });\n                  }\n                }\n                if(transceiver) transceiver.direction = previousDirection || 'inactive';\n                this.setOwnStream(streamType, stream);\n                initialState.facingMode = previousFacingMode;\n              }\n              throw err;\n            } finally {\n              initialState.isUpdatingExclusiveVideo = false;\n            }\n          }\n        } catch(err) {\n          stopNewStream();\n          throw err;\n        }\n        hasChanged = true;\n\n        if(streamType === 'video') {\n          this.p2p.facingMode = facingMode;\n        }\n      } else if(!shouldEnable && track.enabled) {\n        if(streamType === 'audio') {\n          // Fail closed before waiting for sender.replaceTrack. Include a\n          // device replacement already handed to the sender but not committed.\n          track.enabled = false;\n          this.pendingInputAudioTracks.forEach((pendingTrack) => {\n            pendingTrack.enabled = false;\n          });\n        }\n        const fallback = this.getFallbackStream(streamType);\n        const fallbackTrack = getStreamTrack(fallback);\n        if(!fallback || !fallbackTrack) {\n          return;\n        }\n\n        if(!sender) {\n          return;\n        }\n\n        try {\n          await sender.replaceTrack(fallbackTrack);\n        } catch(err) {\n          this.log('toggle failed replacing stream with fallback', {\n            error: err instanceof Error ? err.message : String(err),\n            streamType\n          });\n          throw err;\n        }\n\n        stopStream(stream, fallback);\n        this.setOwnStream(streamType, fallback);\n        hasChanged = true;\n      }\n\n      if(!hasChanged) {\n        return;\n      }\n\n      this.updateStreams();\n      this.sendLocalMediaState();\n      shouldRenegotiate = shouldRenegotiate &&\n        !this.p2p.isStarting &&\n        !this.p2p.isUpdatingExclusiveVideo &&\n        (streamType === 'video' || streamType === 'presentation');\n      if(shouldRenegotiate) {\n        void this.sendOffer();\n      }\n    } catch(err) {\n      this.log('toggle failed', {\n        streamType,\n        shouldEnable,\n        error: err instanceof Error ? {\n          name: err.name,\n          message: err.message\n        } : String(err)\n      });\n      throw err;\n    }\n  }\n\n  private async joinPhoneCall(\n    connections: Connection[],\n    shouldStartVideo: boolean,\n    isP2p: boolean\n  ) {\n    const {isOutgoing} = this;\n    const conn = new RTCPeerConnection({\n      iceServers: buildIceServers(connections, isP2p),\n      iceTransportPolicy: isP2p ? 'all' : 'relay',\n      bundlePolicy: 'max-bundle',\n      rtcpMuxPolicy: 'require',\n      iceCandidatePoolSize: ICE_CANDIDATE_POOL_SIZE\n    });\n\n    const audioContext = new AudioContext();\n    const silentStream = silence(audioContext);\n    const blackVideo = black({width: 640, height: 480});\n    const blackPresentation = black({width: 640, height: 480});\n    const audioTrack = getStreamTrack(silentStream);\n\n    if(!audioTrack) {\n      throw Error('Failed creating phone call placeholder tracks');\n    }\n\n    const audioTransceiver = conn.addTransceiver(audioTrack, {\n      direction: 'sendrecv',\n      streams: [silentStream]\n    });\n\n    const dataChannel = isOutgoing ? conn.createDataChannel('data', {\n      id: DATA_CHANNEL_ID\n    }) : undefined;\n\n    const audio = new Audio();\n    audio.autoplay = true;\n    this.log('join', {\n      isOutgoing,\n      shouldStartVideo,\n      iceTransportPolicy: isP2p ? 'all' : 'relay',\n      iceServers: connections.map((connection) => {\n        return {\n          isTurn: connection.isTurn,\n          isStun: connection.isStun,\n          port: connection.port\n        };\n      })\n    });\n\n    this.p2p = {\n      audio,\n      audioContext,\n      connection: conn,\n      isStarting: true,\n      handledRemoteExchangeIds: new Set<string>(),\n      pendingCandidates: [],\n      appliedRemoteExchangeIds: new Set<string>(),\n      streams: {\n        ownVideo: blackVideo,\n        ownAudio: silentStream,\n        ownPresentation: blackPresentation\n      },\n      remoteMediaState: {\n        isBatteryLow: false,\n        screencastState: 'inactive',\n        videoState: 'inactive',\n        videoRotation: 0,\n        isMuted: true\n      },\n      blackVideo,\n      blackPresentation,\n      silence: silentStream,\n      dataChannel,\n      transceivers: {\n        audio: audioTransceiver\n      },\n      senders: {\n        audio: audioTransceiver.sender\n      },\n      exchangeId: Math.floor(Math.random() * 0xFFFFFFFF)\n    };\n\n    // This element can be created while the constructor is still applying a\n    // saved sink. Queue behind that transaction and read the committed id only\n    // then, so a failed/stale saved id cannot leak into the P2P endpoint and a\n    // successful one is not missed by the creation race.\n    this.applyCurrentOutputDeviceToElement(this.p2p.audio);\n\n    conn.onicecandidate = (event) => {\n      if(!event.candidate || !this.p2p) {\n        return;\n      }\n\n      const serializedCandidate = event.candidate.toJSON();\n      const sdpString = normalizeCandidateComponent(serializedCandidate.candidate);\n      if(!sdpString) {\n        return;\n      }\n\n      this.sendCallSignalingDataDetached({\n        '@type': 'Candidates',\n        'exchangeId': this.p2p.pendingLocalExchangeId || this.p2p.localCandidateExchangeId,\n        'ufrag': serializedCandidate.usernameFragment || undefined,\n        'candidates': [{\n          sdpString,\n          sdpMid: serializedCandidate.sdpMid || undefined,\n          sdpMLineIndex: serializedCandidate.sdpMLineIndex ?? undefined,\n          usernameFragment: serializedCandidate.usernameFragment || undefined\n        }]\n      }, 'sending P2P ICE candidate failed');\n    };\n\n    conn.onconnectionstatechange = () => {\n      this.log('connection state changed', {\n        connectionState: conn.connectionState,\n        iceConnectionState: conn.iceConnectionState,\n        signalingState: conn.signalingState\n      });\n      this.onUpdate({\n        '@type': 'updatePhoneCallConnectionState',\n        'connectionState': conn.connectionState\n      });\n    };\n\n    conn.ontrack = (event) => {\n      if(!this.p2p) return;\n\n      if(conn.iceConnectionState === 'connected' || conn.iceConnectionState === 'completed') {\n        this.onUpdate({\n          '@type': 'updatePhoneCallConnectionState',\n          'connectionState': 'connected'\n        });\n      }\n\n      const stream = event.streams[0] || new MediaStream([event.track]);\n      if(event.track.kind === 'audio') {\n        if(event.transceiver !== this.p2p.transceivers.audio) {\n          this.p2p.transceivers.remoteAudio = event.transceiver;\n        }\n        this.p2p.audio.srcObject = stream;\n        this.p2p.audio.muted = false;\n        this.p2p.audio.setAttribute('playsinline', 'true');\n        this.p2p.audio.play().catch((err) => {\n          this.log('audio playback failed', {\n            error: err instanceof Error ? err.message : String(err)\n          });\n        });\n        event.track.onunmute = () => {\n          if(!this.p2p) return;\n\n          this.p2p.audio.srcObject = stream;\n          this.p2p.audio.play().catch((err) => {\n            this.log('audio playback after unmute failed', {\n              error: err instanceof Error ? err.message : String(err)\n            });\n          });\n        };\n        this.p2p.streams.audio = stream;\n      } else if(\n        event.transceiver === this.p2p.transceivers.remoteVideo || this.isRemoteContentTransceiver(event.transceiver, false)\n      ) {\n        this.p2p.transceivers.remoteVideo = event.transceiver;\n        this.p2p.remoteMediaState.videoState = 'active';\n        this.p2p.streams.video = stream;\n      } else if(\n        event.transceiver === this.p2p.transceivers.remotePresentation ||\n        this.isRemoteContentTransceiver(event.transceiver, true)\n      ) {\n        this.p2p.transceivers.remotePresentation = event.transceiver;\n        this.p2p.remoteMediaState.screencastState = 'active';\n        this.p2p.streams.presentation = stream;\n      } else {\n        this.log('remote video track ignored: unknown transceiver', {\n          track: summarizeTrack(event.track),\n          mid: event.transceiver.mid\n        });\n      }\n\n      this.updateStreams();\n    };\n\n    conn.oniceconnectionstatechange = () => {\n      if(conn.iceConnectionState === 'connected' || conn.iceConnectionState === 'completed') {\n        this.onUpdate({\n          '@type': 'updatePhoneCallConnectionState',\n          'connectionState': 'connected'\n        });\n      }\n      if(!this.p2p || !isOutgoing || conn.iceConnectionState !== 'failed') {\n        return;\n      }\n\n      this.log('ICE restart requested');\n      conn.restartIce();\n      void this.sendOffer();\n    };\n\n    conn.ondatachannel = (event) => {\n      if(event.channel.label === 'data') {\n        this.attachDataChannel(event.channel);\n      }\n    };\n\n    if(dataChannel) {\n      this.attachDataChannel(dataChannel);\n    }\n\n    await this.toggleStream('audio', true);\n\n    if(shouldStartVideo) {\n      await this.toggleStream('video', true);\n    }\n\n    if(this.p2p) {\n      this.p2p.isStarting = false;\n    }\n\n    if(isOutgoing) {\n      await this.sendOffer();\n    }\n  }\n\n  private stopPhoneCall() {\n    if(!this.p2p) return;\n\n    stopStream(this.p2p.streams.ownVideo);\n    stopStream(this.p2p.streams.ownPresentation);\n    stopStream(this.p2p.streams.ownAudio);\n    stopStream(this.p2p.blackVideo);\n    stopStream(this.p2p.blackPresentation);\n    stopStream(this.p2p.silence);\n    this.p2p.dataChannel?.close();\n    this.p2p.connection.close();\n    this.p2p.audio.srcObject = new MediaStream();\n    this.p2p.audioContext.close().catch(() => {});\n    this.p2p = undefined;\n  }\n\n  private isRemoteContentTransceiver(transceiver: RTCRtpTransceiver, isPresentation: boolean) {\n    if(!this.p2p || !transceiver.mid) {\n      return false;\n    }\n\n    const [, mainVideoContent, presentationContent] = orderMediaContents(this.p2p.pendingRemoteNegotiation?.contents || []);\n    const content = isPresentation ? presentationContent : mainVideoContent;\n    return Boolean(content && this.p2p.pendingRemoteContentMids?.[content.ssrc] === transceiver.mid);\n  }\n\n  private attachDataChannel(dataChannel: RTCDataChannel) {\n    if(!this.p2p) return;\n\n    this.p2p.dataChannel = dataChannel;\n    dataChannel.onopen = () => {\n      this.sendLocalMediaState();\n    };\n    dataChannel.onclose = () => undefined;\n    dataChannel.onerror = () => {\n      this.log('data channel error', {\n        id: dataChannel.id,\n        readyState: dataChannel.readyState\n      });\n    };\n    dataChannel.onmessage = (event) => {\n      if(typeof event.data !== 'string') {\n        this.log('data channel non-string message', {\n          dataType: typeof event.data\n        });\n        return;\n      }\n\n      let message: P2PMessage;\n      try {\n        message = JSON.parse(event.data);\n      } catch(err) {\n        this.log('data channel message parse failed', {\n          dataLength: event.data.length,\n          dataType: typeof event.data,\n          error: err instanceof Error ? err.message : String(err)\n        });\n        return;\n      }\n\n      this.enqueueDataChannelSignalingMessage(message).catch((err) => {\n        this.log('data channel signaling message failed', {\n          error: err instanceof Error ? err.message : String(err),\n          messageType: message['@type']\n        });\n      });\n    };\n  }\n\n  private enqueueDataChannelSignalingMessage(message: P2PMessage) {\n    this.dataChannelSignalingMessagePromise = this.dataChannelSignalingMessagePromise\n    .catch(() => {})\n    .then(() => this.processSignalingMessage(message));\n\n    return this.dataChannelSignalingMessagePromise;\n  }\n\n  private sendLocalMediaState() {\n    if(!this.p2p || this.p2p.dataChannel?.readyState !== 'open') return;\n\n    const ownAudioTrack = getStreamTrack(this.p2p.streams.ownAudio);\n    const ownVideoTrack = getStreamTrack(this.p2p.streams.ownVideo);\n    const ownPresentationTrack = getStreamTrack(this.p2p.streams.ownPresentation);\n\n    const message: CallMediaState = {\n      '@type': 'MediaState',\n      'videoRotation': 0,\n      'muted': !ownAudioTrack?.enabled,\n      'lowBattery': false,\n      'videoState': ownVideoTrack?.enabled ? 'active' : 'inactive',\n      'screencastState': ownPresentationTrack?.enabled ? 'active' : 'inactive'\n    };\n\n    this.p2p.dataChannel.send(JSON.stringify(message));\n  }\n\n  private getMediaMids(): MediaMids {\n    if(!this.p2p) {\n      return {\n        audio: DEFAULT_AUDIO_MID,\n        video: DEFAULT_VIDEO_MID,\n        presentation: DEFAULT_PRESENTATION_MID,\n        data: DEFAULT_DATA_MID\n      };\n    }\n\n    const localDescriptionSdp = this.p2p.connection.localDescription?.sdp;\n    const localDataMid = localDescriptionSdp ?\n      parseSdpSections(localDescriptionSdp).find((section) => section.kind === 'application')?.mid :\n      undefined;\n\n    return {\n      audio: this.p2p.transceivers.audio.mid || DEFAULT_AUDIO_MID,\n      video: this.p2p.transceivers.video?.mid || DEFAULT_VIDEO_MID,\n      presentation: this.p2p.transceivers.presentation?.mid || DEFAULT_PRESENTATION_MID,\n      data: localDataMid || DEFAULT_DATA_MID\n    };\n  }\n\n  private sendLocalDescription(\n    description: RTCSessionDescription | RTCSessionDescriptionInit | undefined, exchangeId?: string\n  ) {\n    if(!this.p2p || !description?.sdp) return;\n\n    const contents = parseMediaContents(description.sdp, this.getMediaMids(), this.getActiveLocalMedia());\n    const localExchangeId = exchangeId || String(++this.p2p.exchangeId);\n\n    if(description.type === 'offer') {\n      this.p2p.pendingLocalContentMids = parseMediaContentMids(description.sdp, contents);\n    }\n    this.p2p.localCandidateExchangeId = localExchangeId;\n    this.log('send local negotiation', {\n      exchangeId: localExchangeId,\n      type: description.type,\n      signalingState: this.p2p.connection.signalingState,\n      contents: summarizeContents(contents),\n      contentMids: this.p2p.pendingLocalContentMids,\n      sdp: summarizeSdp(description.sdp),\n      transceivers: this.summarizeTransceivers()\n    });\n    this.sendLocalSetup(description);\n    this.p2p.pendingLocalExchangeId = localExchangeId;\n    this.sendCallSignalingDataDetached({\n      '@type': 'NegotiateChannels',\n      'exchangeId': localExchangeId,\n      contents\n    }, 'sending local P2P negotiation failed');\n  }\n\n  private sendLocalMediaOffer() {\n    if(!this.p2p?.connection.localDescription?.sdp) {\n      return;\n    }\n\n    const {localDescription} = this.p2p.connection;\n    const contents = parseMediaContents(localDescription.sdp, this.getMediaMids(), this.getActiveLocalMedia());\n    if(!contents.length) {\n      return;\n    }\n\n    const exchangeId = String(++this.p2p.exchangeId);\n    this.p2p.pendingLocalExchangeId = exchangeId;\n    this.p2p.localCandidateExchangeId = exchangeId;\n    this.p2p.pendingLocalContentMids = parseMediaContentMids(localDescription.sdp, contents);\n    this.log('send local media negotiation', {\n      exchangeId,\n      type: localDescription.type,\n      contents: summarizeContents(contents),\n      contentMids: this.p2p.pendingLocalContentMids,\n      sdp: summarizeSdp(localDescription.sdp),\n      transceivers: this.summarizeTransceivers()\n    });\n    this.sendCallSignalingDataDetached({\n      '@type': 'NegotiateChannels',\n      exchangeId,\n      contents\n    }, 'sending local P2P media negotiation failed');\n  }\n\n  private async sendOffer() {\n    if(!this.p2p || this.p2p.isMakingOffer || this.p2p.connection.signalingState === 'closed') {\n      return;\n    }\n\n    const {connection} = this.p2p;\n    this.p2p.isMakingOffer = true;\n    this.log('create offer', {\n      signalingState: connection.signalingState,\n      transceivers: this.summarizeTransceivers()\n    });\n\n    try {\n      const offer = await connection.createOffer();\n      if(!this.p2p) {\n        return;\n      }\n\n      const exchangeId = String(++this.p2p.exchangeId);\n      this.p2p.localCandidateExchangeId = exchangeId;\n      await connection.setLocalDescription(offer);\n      this.sendLocalDescription(connection.localDescription || undefined, exchangeId);\n    } catch{\n      this.log('create offer failed', {\n        signalingState: connection.signalingState\n      });\n      // Negotiation errors are recovered by the next signaling exchange or hang-up.\n    } finally {\n      if(this.p2p) {\n        this.p2p.isMakingOffer = false;\n      }\n    }\n  }\n\n  private async applyRemoteNegotiation() {\n    if(!this.p2p || !this.p2p.remoteSetup || !this.p2p.pendingRemoteNegotiation?.contents.length) {\n      return;\n    }\n    if(this.p2p.isApplyingRemoteNegotiation) {\n      this.log('remote negotiation already applying', {\n        exchangeId: this.p2p.pendingRemoteNegotiation.exchangeId\n      });\n      return;\n    }\n\n    const {\n      connection, remoteSetup, pendingLocalExchangeId, pendingRemoteNegotiation\n    } = this.p2p;\n    const isAnswer = pendingRemoteNegotiation.exchangeId === pendingLocalExchangeId;\n    if(isAnswer && connection.signalingState !== 'have-local-offer') {\n      this.log('apply logical remote answer', {\n        exchangeId: pendingRemoteNegotiation.exchangeId,\n        signalingState: connection.signalingState,\n        contents: summarizeContents(pendingRemoteNegotiation.contents)\n      });\n      this.p2p.pendingLocalExchangeId = undefined;\n      this.p2p.pendingLocalContentMids = undefined;\n      this.p2p.handledRemoteExchangeIds.add(pendingRemoteNegotiation.exchangeId);\n      this.p2p.pendingRemoteNegotiation = undefined;\n      return;\n    }\n    if(!isAnswer) {\n      this.prepareTransceiversForRemoteOffer(pendingRemoteNegotiation.contents);\n      this.p2p.pendingRemoteContentMids = this.buildRemoteContentMids(pendingRemoteNegotiation.contents);\n    }\n    const sdp = this.buildRemoteSdp(remoteSetup, pendingRemoteNegotiation.contents, isAnswer);\n    this.log('apply remote negotiation', {\n      exchangeId: pendingRemoteNegotiation.exchangeId,\n      type: isAnswer ? 'answer' : 'offer',\n      signalingState: connection.signalingState,\n      contents: summarizeContents(pendingRemoteNegotiation.contents),\n      sdp: summarizeSdp(sdp),\n      transceivers: this.summarizeTransceivers()\n    });\n\n    this.p2p.isApplyingRemoteNegotiation = true;\n    try {\n      if(!isAnswer && connection.signalingState === 'have-local-offer' && !this.isOutgoing) {\n        this.log('rollback local offer for remote offer glare', {\n          exchangeId: pendingRemoteNegotiation.exchangeId\n        });\n        await connection.setLocalDescription({type: 'rollback'});\n        this.p2p.pendingLocalExchangeId = undefined;\n      }\n\n      if(isAnswer && connection.signalingState !== 'have-local-offer') {\n        this.log('ignore remote answer in wrong signaling state', {\n          exchangeId: pendingRemoteNegotiation.exchangeId,\n          signalingState: connection.signalingState\n        });\n        return;\n      }\n      if(!isAnswer && connection.signalingState !== 'stable') {\n        this.log('ignore remote offer in wrong signaling state', {\n          exchangeId: pendingRemoteNegotiation.exchangeId,\n          signalingState: connection.signalingState\n        });\n        return;\n      }\n\n      if(!isAnswer) {\n        this.log('prepared transceivers for remote offer', {\n          exchangeId: pendingRemoteNegotiation.exchangeId,\n          transceivers: this.summarizeTransceivers()\n        });\n      }\n\n      if(isAnswer) {\n        validateRemoteAnswerSdp(this.log, connection.localDescription?.sdp, sdp);\n      }\n\n      await connection.setRemoteDescription({type: isAnswer ? 'answer' : 'offer', sdp});\n      this.p2p.appliedRemoteExchangeId = pendingRemoteNegotiation.exchangeId;\n      this.p2p.appliedRemoteExchangeIds.add(pendingRemoteNegotiation.exchangeId);\n      this.p2p.appliedRemoteUfrag = remoteSetup.ufrag;\n      this.log('remote description applied', {\n        exchangeId: pendingRemoteNegotiation.exchangeId,\n        type: isAnswer ? 'answer' : 'offer',\n        ufrag: remoteSetup.ufrag,\n        signalingState: connection.signalingState,\n        transceivers: this.summarizeTransceivers()\n      });\n      if(!isAnswer) {\n        this.updateRemoteMediaStateFromOffer(pendingRemoteNegotiation.contents);\n        await this.bindLocalAudioToSharedRemoteOffer();\n      }\n      await this.commitPendingIceCandidates();\n\n      if(isAnswer) {\n        this.p2p.pendingLocalExchangeId = undefined;\n        this.p2p.pendingLocalContentMids = undefined;\n      } else {\n        const answer = await connection.createAnswer();\n        if(!this.p2p) {\n          return;\n        }\n\n        this.p2p.localCandidateExchangeId = pendingRemoteNegotiation.exchangeId;\n        await connection.setLocalDescription(answer);\n\n        const localDescription = connection.localDescription || undefined;\n        const contents = localDescription?.sdp ?\n          this.parseAnswerContents(localDescription.sdp, pendingRemoteNegotiation.contents, this.getMediaMids()) : [];\n\n        this.updateRemoteMediaStateFromOffer(contents);\n        this.log('send local answer negotiation', {\n          exchangeId: pendingRemoteNegotiation.exchangeId,\n          contents: summarizeContents(contents),\n          sdp: localDescription?.sdp ? summarizeSdp(localDescription.sdp) : undefined,\n          transceivers: this.summarizeTransceivers()\n        });\n        this.sendLocalSetup(localDescription);\n        this.sendCallSignalingDataDetached({\n          '@type': 'NegotiateChannels',\n          'exchangeId': pendingRemoteNegotiation.exchangeId,\n          contents\n        }, 'sending P2P negotiation answer failed');\n\n        if(this.shouldSendLocalOfferAfterRemoteAnswer()) {\n          this.log('send local media offer after remote answer', {\n            exchangeId: pendingRemoteNegotiation.exchangeId,\n            transceivers: this.summarizeTransceivers()\n          });\n          this.sendLocalMediaOffer();\n        }\n      }\n\n      this.p2p.handledRemoteExchangeIds.add(pendingRemoteNegotiation.exchangeId);\n    } finally {\n      if(this.p2p) {\n        if(this.p2p.pendingRemoteNegotiation?.exchangeId === pendingRemoteNegotiation.exchangeId) {\n          this.p2p.pendingRemoteNegotiation = undefined;\n          this.p2p.pendingRemoteContentMids = undefined;\n        }\n        this.p2p.isApplyingRemoteNegotiation = false;\n        if(!this.p2p.pendingLocalExchangeId && !this.p2p.pendingRemoteNegotiation && this.p2p.queuedRemoteNegotiation) {\n          this.p2p.pendingRemoteNegotiation = this.p2p.queuedRemoteNegotiation;\n          this.p2p.queuedRemoteNegotiation = undefined;\n        }\n        if(this.p2p.pendingRemoteNegotiation) {\n          void this.applyRemoteNegotiation().catch((err) => {\n            // The caller awaits the negotiation that was current on entry, but\n            // a queued offer is promoted from this finally block and otherwise\n            // has no observer. A failed remote description leaves this peer\n            // connection unusable, so close the exact P2P call after logging.\n            this.log.error('queued remote negotiation failed', err);\n            void this.hangUp('phoneCallDiscardReasonDisconnect').catch((hangUpError) => {\n              this.log.error('hang up after queued remote negotiation failed', hangUpError);\n            });\n          });\n        }\n      }\n    }\n  }\n\n  private sendLocalSetup(description: RTCSessionDescription | RTCSessionDescriptionInit | undefined) {\n    if(!this.p2p || !description?.sdp) return;\n\n    const setup = parseInitialSetup(description.sdp);\n    const setupKey = JSON.stringify(setup);\n    if(this.p2p.lastLocalSetupKey === setupKey) {\n      return;\n    }\n\n    this.p2p.lastLocalSetupKey = setupKey;\n    this.log('send initial setup', {\n      setup: {\n        ufrag: setup.ufrag,\n        fingerprintCount: setup.fingerprints.length,\n        renomination: setup.renomination\n      }\n    });\n    this.sendCallSignalingDataDetached(setup, 'sending initial P2P setup failed');\n  }\n\n  private getActiveLocalMedia(): ActiveLocalMedia {\n    return {\n      hasVideo: Boolean(getStreamTrack(this.p2p?.streams.ownVideo)?.enabled),\n      hasPresentation: Boolean(getStreamTrack(this.p2p?.streams.ownPresentation)?.enabled)\n    };\n  }\n\n  private prepareTransceiversForRemoteOffer(contents: P2PMediaContent[]) {\n    if(!this.p2p) {\n      return;\n    }\n\n    const hasRemoteAudio = contents.some((content) => content.type === 'audio');\n    const hasRemoteVideo = contents.filter((content) => content.type === 'video').length;\n    const shouldUseSharedAudioSection = hasRemoteAudio && !this.p2p.transceivers.audio.mid;\n    if(shouldUseSharedAudioSection) {\n      this.p2p.transceivers.audio.direction = 'sendrecv';\n    } else if(hasRemoteAudio && !this.setRemoteTransceiverDirection('remoteAudio', 'audio', 'recvonly')) {\n      this.p2p.transceivers.remoteAudio = this.p2p.connection.addTransceiver('audio', {direction: 'recvonly'});\n    }\n    if(hasRemoteVideo >= 1 && !this.setRemoteTransceiverDirection('remoteVideo', 'video', 'recvonly')) {\n      this.p2p.transceivers.remoteVideo = this.p2p.connection.addTransceiver('video', {direction: 'recvonly'});\n    }\n    if(hasRemoteVideo >= 2 && !this.setRemoteTransceiverDirection('remotePresentation', 'video', 'recvonly')) {\n      this.p2p.transceivers.remotePresentation = this.p2p.connection.addTransceiver('video', {direction: 'recvonly'});\n    }\n    if(!hasRemoteAudio || shouldUseSharedAudioSection) {\n      this.setRemoteTransceiverDirection('remoteAudio', 'audio', 'inactive');\n    }\n    if(hasRemoteVideo < 1) {\n      this.setRemoteTransceiverDirection('remoteVideo', 'video', 'inactive');\n    }\n    if(hasRemoteVideo < 2) {\n      this.setRemoteTransceiverDirection('remotePresentation', 'video', 'inactive');\n    }\n  }\n\n  private setRemoteTransceiverDirection(\n    name: 'remoteAudio' | 'remoteVideo' | 'remotePresentation',\n    kind: 'audio' | 'video',\n    direction: RTCRtpTransceiverDirection\n  ) {\n    if(!this.p2p?.transceivers[name]) {\n      return false;\n    }\n\n    try {\n      const transceiver = this.p2p.transceivers[name];\n      if(transceiver.receiver.track.kind !== kind) {\n        return false;\n      }\n\n      transceiver.direction = direction;\n      return true;\n    } catch{\n      return false;\n    }\n  }\n\n  private buildRemoteContentMids(contents: P2PMediaContent[]) {\n    if(!this.p2p) {\n      return {};\n    }\n\n    const [audioContent, mainVideoContent, presentationContent] = orderMediaContents(contents);\n    const result: Record<string, string> = {};\n    if(audioContent) {\n      result[audioContent.ssrc] = this.p2p.transceivers.audio.mid ?\n        (this.p2p.transceivers.remoteAudio?.mid || audioContent.ssrc) : this.getMediaMids().audio;\n    }\n    if(mainVideoContent) {\n      result[mainVideoContent.ssrc] = this.p2p.transceivers.remoteVideo?.mid || mainVideoContent.ssrc;\n    }\n    if(presentationContent) {\n      result[presentationContent.ssrc] = this.p2p.transceivers.remotePresentation?.mid || presentationContent.ssrc;\n    }\n\n    return result;\n  }\n\n  private updateRemoteMediaStateFromOffer(contents: P2PMediaContent[]) {\n    if(!this.p2p) {\n      return;\n    }\n\n    const remoteVideoCount = contents.filter((content) => content.type === 'video').length;\n    this.p2p.remoteMediaState.videoState = remoteVideoCount >= 1 ? 'active' : 'inactive';\n    this.p2p.remoteMediaState.screencastState = remoteVideoCount >= 2 ? 'active' : 'inactive';\n    this.updateStreams();\n  }\n\n  private shouldSendLocalOfferAfterRemoteAnswer() {\n    if(!this.p2p || this.isOutgoing || this.p2p.pendingLocalExchangeId) {\n      return false;\n    }\n\n    return Boolean(getStreamTrack(this.p2p.streams.ownAudio)?.enabled ||\n      getStreamTrack(this.p2p.streams.ownVideo)?.enabled ||\n      getStreamTrack(this.p2p.streams.ownPresentation)?.enabled);\n  }\n\n  private async bindLocalAudioToSharedRemoteOffer() {\n    if(!this.p2p || this.p2p.transceivers.audio.mid) {\n      return;\n    }\n\n    const audioTrack = this.p2p.senders.audio.track;\n    if(!audioTrack?.enabled) {\n      return;\n    }\n\n    const audioMid = this.getMediaMids().audio;\n    const transceiver = this.p2p.connection.getTransceivers().find((item) => {\n      return item.mid === audioMid && item.receiver.track.kind === 'audio';\n    });\n    if(!transceiver || transceiver === this.p2p.transceivers.audio) {\n      return;\n    }\n\n    await transceiver.sender.replaceTrack(audioTrack);\n    transceiver.direction = 'sendrecv';\n    this.p2p.transceivers.audio = transceiver;\n    this.p2p.senders.audio = transceiver.sender;\n    this.p2p.transceivers.remoteAudio = undefined;\n    this.log('bound local audio to shared remote offer transceiver', {\n      mid: transceiver.mid,\n      track: summarizeTrack(audioTrack),\n      transceivers: this.summarizeTransceivers()\n    });\n  }\n\n  private buildRemoteSdp(\n    setup: Extract<P2PMessage, {'@type': 'InitialSetup'}>,\n    contents: P2PMediaContent[],\n    isAnswer: boolean\n  ) {\n    const mids = this.getMediaMids();\n    const orderedContents = orderMediaContents(contents);\n    const [audioContent, mainVideoContent, presentationContent] = orderedContents;\n    const videoPayloadSource = mainVideoContent || presentationContent;\n    const localMediaParameters = this.getLocalMediaParameters(mids);\n    const remoteContentMids = this.p2p?.pendingRemoteContentMids || {};\n    const shouldUseSharedAudioSection = !isAnswer && Boolean(audioContent) && !this.p2p?.transceivers.audio.mid;\n    const remoteAudioMid = shouldUseSharedAudioSection || isAnswer ?\n      mids.audio : (audioContent ? remoteContentMids[audioContent.ssrc] : mids.audio);\n    const remoteVideoMid = isAnswer ?\n      mids.video : (mainVideoContent ? remoteContentMids[mainVideoContent.ssrc] : mids.video);\n    const remotePresentationMid = isAnswer ?\n      mids.presentation : (presentationContent ? remoteContentMids[presentationContent.ssrc] : mids.presentation);\n    const localOfferSdp = this.p2p?.connection.localDescription?.type === 'offer' ?\n      this.p2p.connection.localDescription.sdp : undefined;\n    const sharedAudioDirection: RTCRtpTransceiverDirection | undefined = shouldUseSharedAudioSection ?\n      'sendrecv' : undefined;\n    const entries: SsrcEntry[] = isAnswer ?\n      this.buildAnswerSsrcs(contents, mids) :\n      [\n        {\n          ...buildSsrc(audioContent, remoteAudioMid, false),\n          direction: sharedAudioDirection\n        },\n        buildSsrc(mainVideoContent, remoteVideoMid, true),\n        buildSsrc(presentationContent, remotePresentationMid, true, true)\n      ];\n    if(!isAnswer && this.shouldAddLocalAudioOfferSection(entries, mids)) {\n      entries.push({\n        ...buildSsrc(undefined, mids.audio, false),\n        isLocalOnly: true,\n        isRemoved: false\n      });\n    }\n\n    return SDPBuilder.fromP2p({\n      setup,\n      mids,\n      isAnswer,\n      entries,\n      audioPayloadTypes: audioContent?.payloadTypes?.map(payloadTypeToConference) ||\n        localMediaParameters.audioPayloadTypes,\n      audioExtensions: audioContent?.rtpExtensions || localMediaParameters.audioExtensions,\n      videoPayloadTypes: filterRemoteVideoPayloadTypes(videoPayloadSource)?.map(payloadTypeToConference) ||\n        localMediaParameters.videoPayloadTypes,\n      videoExtensions: videoPayloadSource?.rtpExtensions || localMediaParameters.videoExtensions,\n      sectionOrder: isAnswer ? this.getLocalOfferSections() : this.getEstablishedSections(),\n      bundleMids: isAnswer && localOfferSdp ? parseBundleMids(localOfferSdp) : undefined,\n      shouldKeepRemoteReceiveSection: (section) => this.shouldKeepRemoteReceiveSection(section)\n    });\n  }\n\n  private getLocalOfferSections() {\n    if(!this.p2p?.connection.localDescription?.sdp || this.p2p.connection.localDescription.type !== 'offer') {\n      return undefined;\n    }\n\n    return parseSdpSections(this.p2p.connection.localDescription.sdp).filter((section) => section.kind !== 'session');\n  }\n\n  private getEstablishedSections() {\n    const sdp = this.p2p?.connection.remoteDescription?.sdp || this.p2p?.connection.localDescription?.sdp;\n    if(!sdp) {\n      return undefined;\n    }\n\n    return parseSdpSections(sdp).filter((section) => section.kind !== 'session');\n  }\n\n  private getLocalMediaParameters(mids: MediaMids): LocalMediaParameters {\n    const sections = this.p2p?.connection.localDescription?.sdp ?\n      parseSdpSections(this.p2p.connection.localDescription.sdp) : [];\n    const audioSection = sections.find((section) => section.mid === mids.audio);\n    const videoSection = sections.find((section) => section.mid === mids.video) ||\n      sections.find((section) => section.mid === mids.presentation);\n\n    return {\n      audioPayloadTypes: audioSection?.kind === 'audio' ?\n        parsePayloadTypes(audioSection).map(payloadTypeToConference) : getDefaultAudioPayloadTypes(),\n      audioExtensions: audioSection?.kind === 'audio' ? parseExtmaps(audioSection) : [],\n      videoPayloadTypes: videoSection?.kind === 'video' ?\n        parsePayloadTypes(videoSection).map(payloadTypeToConference) : getDefaultVideoPayloadTypes(),\n      videoExtensions: videoSection?.kind === 'video' ? parseExtmaps(videoSection) : []\n    };\n  }\n\n  private shouldAddLocalAudioOfferSection(entries: SsrcEntry[], mids: MediaMids) {\n    const audioTrack = this.p2p?.transceivers.audio.sender.track;\n    const sections = this.getEstablishedSections() || [];\n    return Boolean(audioTrack?.enabled) &&\n      !entries.some((entry) => entry.mid === mids.audio && !entry.isRemoved) &&\n      !sections.some((section) => section.mid === mids.audio);\n  }\n\n  private buildAnswerSsrcs(contents: P2PMediaContent[], mids: MediaMids): SsrcEntry[] {\n    let videoIndex = 0;\n\n    return contents.map((content) => {\n      const mid = this.p2p?.pendingLocalContentMids?.[content.ssrc] ||\n        (content.type === 'audio' ? mids.audio : (videoIndex++ ? mids.presentation : mids.video));\n      return buildSsrc(content, mid, content.type === 'video', mid === mids.presentation);\n    });\n  }\n\n  private parseAnswerContents(sdp: string, offeredContents: P2PMediaContent[], mids: MediaMids) {\n    const sections = parseSdpSections(sdp);\n    const audioSection = sections.find((section) => section.mid === mids.audio);\n    const videoSections = [\n      sections.find((section) => section.mid === mids.video),\n      sections.find((section) => section.mid === mids.presentation)\n    ].filter(Boolean);\n    let videoIndex = 0;\n\n    return offeredContents.map((content) => {\n      const remoteMid = this.p2p?.pendingRemoteContentMids?.[content.ssrc];\n      const section = remoteMid ? sections.find((item) => item.mid === remoteMid) :\n        (content.type === 'audio' ? audioSection : videoSections[videoIndex++]);\n      if(!section || getSdpPort(section) === 0) {\n        return undefined;\n      }\n\n      const direction = getSdpDirection(section);\n      if(direction !== 'recvonly' && direction !== 'sendrecv') {\n        return undefined;\n      }\n\n      const acceptedContent = parseMediaContent(section, content.type, content);\n      if(!acceptedContent.payloadTypes?.length) {\n        return undefined;\n      }\n\n      return acceptedContent;\n    }).filter(Boolean);\n  }\n\n  private shouldKeepRemoteReceiveSection(section: SdpSection) {\n    if(!this.p2p || getSdpDirection(section) !== 'recvonly') {\n      return false;\n    }\n\n    const mid = section.mid;\n    if(section.kind === 'audio') {\n      return mid === this.p2p.transceivers.remoteAudio?.mid && hasLiveTrack(this.p2p.streams.audio);\n    }\n\n    if(section.kind === 'video') {\n      return (mid === this.p2p.transceivers.remoteVideo?.mid && hasLiveTrack(this.p2p.streams.video)) ||\n        (mid === this.p2p.transceivers.remotePresentation?.mid && hasLiveTrack(this.p2p.streams.presentation));\n    }\n\n    return false;\n  }\n\n  private summarizeTransceivers() {\n    if(!this.p2p) {\n      return [];\n    }\n\n    return [\n      {name: 'audio', transceiver: this.p2p.transceivers.audio},\n      {name: 'remoteAudio', transceiver: this.p2p.transceivers.remoteAudio},\n      {name: 'video', transceiver: this.p2p.transceivers.video},\n      {name: 'remoteVideo', transceiver: this.p2p.transceivers.remoteVideo},\n      {name: 'presentation', transceiver: this.p2p.transceivers.presentation},\n      {name: 'remotePresentation', transceiver: this.p2p.transceivers.remotePresentation}\n    ].map(({name, transceiver}) => {\n      if(!transceiver) {\n        return {\n          name\n        };\n      }\n\n      return {\n        name,\n        mid: transceiver.mid,\n        direction: transceiver.direction,\n        currentDirection: transceiver.currentDirection,\n        senderTrack: summarizeTrack(transceiver.sender.track || undefined),\n        receiverTrack: summarizeTrack(transceiver.receiver.track || undefined)\n      };\n    });\n  }\n\n  private async processSignalingMessage(message: P2PMessage) {\n    if(!this.p2p || !message) return;\n\n    switch(message['@type']) {\n      case 'MediaState': {\n        const videoState = message.videoState === 'inactive' && hasLiveTrack(this.p2p.streams.video) ?\n          'active' : message.videoState;\n        const screencastState = message.screencastState === 'inactive' && hasLiveTrack(this.p2p.streams.presentation) ?\n          'active' : message.screencastState;\n        this.p2p.remoteMediaState = {\n          isMuted: message.muted,\n          isBatteryLow: message.lowBattery,\n          videoState,\n          videoRotation: message.videoRotation,\n          screencastState\n        };\n        this.updateStreams();\n        break;\n      }\n      case 'Candidates': {\n        this.log('received ICE candidates', {\n          exchangeId: message.exchangeId,\n          ufrag: message.ufrag,\n          pendingRemoteExchangeId: this.p2p.pendingRemoteNegotiation?.exchangeId,\n          remoteDescriptionMids: getRemoteDescriptionMids(this.p2p.connection),\n          count: message.candidates.length\n        });\n        const appliedExchanges = this.p2p.appliedRemoteExchangeIds.size;\n        this.p2p.pendingCandidates.push(...message.candidates.map((candidate): PendingCandidate => {\n          return {\n            ...candidate,\n            exchangeId: message.exchangeId,\n            ufrag: message.ufrag || candidate.usernameFragment,\n            appliedExchanges\n          };\n        }));\n\n        const overflow = this.p2p.pendingCandidates.length - P2P_MAX_PENDING_CANDIDATES;\n        if(overflow > 0) {\n          this.p2p.pendingCandidates.splice(0, overflow);\n          this.log.warn('dropping the oldest pending ICE candidates', {overflow});\n        }\n\n        await this.commitPendingIceCandidates();\n        break;\n      }\n      case 'InitialSetup': {\n        // This is peer-controlled JSON, so the TypeScript shape proves nothing\n        // at runtime. Validate both the types and the values before keeping the\n        // setup: arrays/objects are especially dangerous because interpolation\n        // invokes toString(), which can turn an array element containing CR/LF\n        // into a second SDP line.\n        if(!isSdpSafeSetup(message)) {\n          this.log.error('InitialSetup has invalid transport fields — dropping');\n          break;\n        }\n\n        this.p2p.remoteSetup = message;\n        await this.applyRemoteNegotiation();\n        break;\n      }\n      case 'NegotiateChannels': {\n        // Peer-controlled JSON again, and every field of it — codec names,\n        // fmtp, rtcp-fb, extmap URIs, ssrc groups and the ssrcs that double as\n        // mids — is interpolated into the SDP by SDPBuilder.addP2p. Rejected\n        // the way an unsafe InitialSetup is: dropped, never negotiated.\n        if(!isSdpSafeString(message.exchangeId) || !isSdpSafeContents(message.contents)) {\n          this.log.error('NegotiateChannels has invalid media fields — dropping');\n          break;\n        }\n\n        if(this.p2p.handledRemoteExchangeIds.has(message.exchangeId)) {\n          this.log('ignore duplicate remote negotiation', {\n            exchangeId: message.exchangeId\n          });\n          return;\n        }\n        if(this.p2p.isApplyingRemoteNegotiation && this.p2p.pendingRemoteNegotiation?.exchangeId === message.exchangeId) {\n          this.log('ignore in-flight duplicate remote negotiation', {\n            exchangeId: message.exchangeId\n          });\n          return;\n        }\n        if(this.p2p.pendingLocalExchangeId && message.exchangeId !== this.p2p.pendingLocalExchangeId) {\n          if(this.isOutgoing) {\n            this.p2p.queuedRemoteNegotiation = message;\n            this.log('queue remote offer until local answer is applied', {\n              exchangeId: message.exchangeId,\n              pendingLocalExchangeId: this.p2p.pendingLocalExchangeId\n            });\n            return;\n          }\n\n          this.p2p.pendingLocalExchangeId = undefined;\n        }\n\n        this.p2p.pendingRemoteNegotiation = message;\n        await this.applyRemoteNegotiation();\n        break;\n      }\n    }\n  }\n\n  private async commitPendingIceCandidates() {\n    if(!this.p2p || !this.p2p.pendingCandidates.length) {\n      return;\n    }\n\n    const {connection, pendingCandidates} = this.p2p;\n    const candidatesToAdd: PendingCandidate[] = [];\n    const queuedCandidates: PendingCandidate[] = [];\n\n    pendingCandidates.forEach((candidate) => {\n      const decision = this.getCandidateCommitDecision(candidate);\n      this.log('ICE candidate routing', {\n        decision,\n        exchangeId: candidate.exchangeId,\n        ufrag: getCandidateUfrag(candidate),\n        pendingRemoteExchangeId: this.p2p?.pendingRemoteNegotiation?.exchangeId,\n        appliedRemoteExchangeId: this.p2p?.appliedRemoteExchangeId,\n        remoteDescriptionMids: getRemoteDescriptionMids(connection)\n      });\n\n      if(decision === 'add') {\n        candidatesToAdd.push(candidate);\n      } else if(decision === 'queue') {\n        queuedCandidates.push(candidate);\n      }\n    });\n\n    this.p2p.pendingCandidates = queuedCandidates;\n\n    await Promise.all(candidatesToAdd.map((candidate) => {\n      return tryAddCandidate(this.log, connection, candidate);\n    }));\n  }\n\n  private getCandidateCommitDecision(candidate: PendingCandidate): 'add' | 'queue' | 'drop' {\n    if(!this.p2p?.connection.remoteDescription) {\n      return 'queue';\n    }\n\n    const candidateExchangeId = candidate.exchangeId;\n    const candidateUfrag = getCandidateUfrag(candidate);\n    const remoteUfrags = getRemoteDescriptionUfrags(this.p2p.connection);\n    const isCurrentUfrag = !candidateUfrag ||\n      remoteUfrags.has(candidateUfrag) ||\n      candidateUfrag === this.p2p.appliedRemoteUfrag;\n\n    if(candidateExchangeId) {\n      if(this.p2p.appliedRemoteExchangeIds.has(candidateExchangeId)) {\n        return isCurrentUfrag ? 'add' : 'drop';\n      }\n\n      if(\n        candidateExchangeId === this.p2p.pendingLocalExchangeId ||\n        candidateExchangeId === this.p2p.pendingRemoteNegotiation?.exchangeId ||\n        candidateExchangeId === this.p2p.queuedRemoteNegotiation?.exchangeId\n      ) {\n        return 'queue';\n      }\n\n      if(this.p2p.handledRemoteExchangeIds.has(candidateExchangeId)) {\n        return 'drop';\n      }\n\n      // Nothing has claimed this exchange, and a newer one has been applied\n      // since the candidate was queued: its negotiation was superseded (or\n      // never existed) and the candidate would otherwise wait forever.\n      if(this.p2p.appliedRemoteExchangeIds.size > candidate.appliedExchanges) {\n        return 'drop';\n      }\n\n      return 'queue';\n    }\n\n    if(isCurrentUfrag) {\n      return 'add';\n    }\n\n    return 'queue';\n  }\n}\n","// TdE2E-encrypted conference calls. The full client-side port lives under\n// src/lib/calls/e2e/ and is byte-compatible with tdlib's reference.\n//\n// Previously GATED off because of an apparent Chrome `RTCRtpScriptTransform`\n// recv-side bypass (\"~5 frames then halt\"). That was re-diagnosed as a\n// MODEL + TIMING bug, not a Chromium limitation: the recv path had been\n// built around a single multiplexed recvonly m-line and attached the recv\n// transform in the `track` event (after the decoder binds — too late, so\n// Chrome silently bypasses it). It now mints one recvonly m-line per remote\n// SSRC (like legacy voice chats — the SFU signals only SSRCs) and attaches\n// the recv transform at createTransceiver time, before the decoder binds —\n// the exact mirror of the proven send-side fix. See onParticipantUpdate in\n// groupCallInstance.ts + joinConferenceCommon in groupCallsController.ts.\n//\n// Enabled so the fix can be verified end-to-end on a live 2-party\n// conference. If recv frames still don't pump through the transform, gate\n// this back to `false` while investigating.\nconst IS_CONFERENCE_CALL_ENABLED = true;\n\n// `RTCRtpScriptTransform` is the ONLY thing that puts our per-frame encryption\n// into the media path — without it every frame reaches the SFU as plaintext.\n// So it is a hard requirement, not a progressive enhancement: a browser that\n// lacks it must not be able to join a call we label end-to-end encrypted.\n// Before this gate, `newRtcScriptTransform` threw, the attach helper caught and\n// logged, and the call carried on shipping the user's microphone in the clear\n// under an E2E badge.\nconst IS_RTC_SCRIPT_TRANSFORM_SUPPORTED =\n  typeof (globalThis as {RTCRtpScriptTransform?: unknown}).RTCRtpScriptTransform === 'function';\n\nconst IS_CONFERENCE_CALL_SUPPORTED = IS_CONFERENCE_CALL_ENABLED && IS_RTC_SCRIPT_TRANSFORM_SUPPORTED;\n\nexport default IS_CONFERENCE_CALL_SUPPORTED;\n","import type {LangPackKey} from '@lib/langPack';\n\nconst CONFERENCE_INVITE_INVALID_ERROR_TYPES = new Set([\n  'GROUPCALL_INVALID',\n  'GROUPCALL_FORBIDDEN',\n  'INVITE_HASH_EXPIRED',\n  'INVITE_SLUG_EXPIRED',\n  'INVITE_SLUG_INVALID'\n]);\n\nexport function isConferenceInviteInvalidError(error: unknown): boolean {\n  return CONFERENCE_INVITE_INVALID_ERROR_TYPES.has((error as ApiError)?.type);\n}\n\nexport default function getConferenceInviteErrorLangKey(error: unknown): LangPackKey {\n  return isConferenceInviteInvalidError(error) ? 'InviteExpired' : 'Error.AnError';\n}\n","import getCallAudioAsset, {CALL_AUDIO_ASSETS} from '@components/call/getAudioAsset';\nimport DEBUG, {MOUNT_CLASS_TO} from '@config/debug';\nimport IS_CALL_SUPPORTED from '@environment/callSupport';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport insertInDescendSortedArray from '@helpers/array/insertInDescendSortedArray';\nimport AudioAssetPlayer from '@helpers/audioAssetPlayer';\nimport bytesCmpConstTime from '@helpers/bytes/bytesCmpConstTime';\nimport bytesToHex from '@helpers/bytes/bytesToHex';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport noop from '@helpers/noop';\nimport tsNow from '@helpers/tsNow';\nimport {PhoneCall, PhoneCallProtocol} from '@layer';\nimport {CallId} from '@appManagers/appCallsManager';\nimport {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport rootScope from '@lib/rootScope';\nimport CallInstance from '@lib/calls/callInstance';\nimport CALL_STATE from '@lib/calls/callState';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\nimport IS_CONFERENCE_CALL_SUPPORTED from '@environment/conferenceCallSupport';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport rtmpCallsController from '@lib/calls/rtmpCallsController';\nimport {toastNew} from '@components/toast';\nimport getConferenceInviteErrorLangKey from '@lib/calls/conferenceInviteError';\nimport callTransitionCoordinator from '@lib/calls/callTransitionCoordinator';\nimport {groupCallToInput} from '@lib/calls/helpers/groupCallUpdates';\nimport {CALL_PROTOCOL_LIBRARY_VERSIONS} from '@lib/calls/p2P/getCallProtocol';\nimport {CALL_REQUEST_TIMEOUT, CALL_WAITING_RING_VOLUME} from '@lib/calls/constants';\n\nexport class CallsController extends EventListenerBase<{\n  instance: (details: {hasCurrent: boolean, instance: CallInstance}) => void,\n  accepting: (instance: CallInstance) => void, // это костыль. используется при параллельном вызове, чтобы заменить звонок в topbarCall\n  incompatible: (userId: UserId) => void,\n  conferenceMigration: (details: {\n    instance: CallInstance,\n    state: 'started' | 'completed' | 'failed'\n  }) => void,\n}> {\n  private log: ReturnType<typeof logger>;\n  private managers: AppManagers;\n  private audioAsset: ReturnType<typeof getCallAudioAsset>;\n  // Call waiting rings through its own player: the shared one may be busy with\n  // the current call's outgoing / connect tone, and stopping that tone with the\n  // waiting call would silence the call that is actually being made.\n  private callWaitingAudioAsset: AudioAssetPlayer<Record<'incoming', string>>;\n  private callWaitingInstance: CallInstance;\n  private instances: Map<CallId, CallInstance>;\n  private sortedInstances: Array<CallInstance>;\n  private tempId: number;\n  private migratingCalls = new WeakSet<CallInstance>();\n\n  public construct(managers: AppManagers) {\n    this.managers = managers;\n    this.log = logger('CC');\n\n    if(!IS_CALL_SUPPORTED) {\n      return;\n    }\n\n    this.audioAsset = getCallAudioAsset();\n    this.tempId = 0;\n    this.instances = new Map();\n    this.sortedInstances = [];\n\n    if(typeof(window) !== 'undefined') {\n      // The tab can go away with a call up. The SharedWorker outlives it while\n      // any other tab exists, so a fire-and-forget discard through the manager\n      // still reaches the server and the peer sees the call end instead of a\n      // stall until the server times it out.\n      window.addEventListener('pagehide', () => this.discardAllOnUnload());\n    }\n\n    rootScope.addEventListener('call_update', (call) => {\n      void this.handleCallUpdate(call).catch((err) => {\n        this.log.error('call update processing failed', err, call);\n\n        const instance = this.instances.get(call.id);\n        if(!instance || instance.isClosing) {\n          return;\n        }\n\n        const discardedByOtherParty = call._ === 'phoneCallDiscarded';\n        const reason = discardedByOtherParty ?\n          call.reason || 'phoneCallDiscardReasonDisconnect' :\n          'phoneCallDiscardReasonDisconnect';\n        void instance.hangUp(reason, discardedByOtherParty).catch((hangUpError) => {\n          this.log.error('call update failure cleanup failed', hangUpError, call);\n        });\n      });\n    });\n\n    rootScope.addEventListener('call_signaling', ({callId, data}) => {\n      const instance = this.instances.get(callId);\n      if(instance?.id !== callId) {\n        return;\n      }\n\n      instance.onUpdatePhoneCallSignalingData(data);\n    });\n\n    // Conference chain delivery (sub_chain_id 0 = blocks, 1 = broadcasts)\n    // is handled by `GroupCallInstance.attachE2e` for the active instance.\n  }\n\n  private async handleCallUpdate(call: PhoneCall): Promise<void> {\n    const instance = this.instances.get(call.id);\n\n    if(instance?.isClosing && call._ !== 'phoneCallDiscarded') {\n      // A request/accept/confirm response can be delivered through the\n      // update channel before the manager proxy resolves to its caller-side\n      // post-await guard. Never let that early delivery revive crypto/media\n      // work for an instance whose close transaction already started.\n      return;\n    }\n\n    // `setPhoneCall` replaces the state the exchange reads (g_a_hash, g_b, the\n    // connections), so every state that has a direction or an order is checked\n    // against the instance before it is taken — tdesktop `checkCallCommonFields`,\n    // tdlib's per-state gating in `do_update_call`. A mismatching update is\n    // ignored, never a reason to hang up.\n    switch(call._) {\n      case 'phoneCallDiscarded': {\n        if(instance) {\n          instance.setPhoneCall(call);\n          // Server-initiated migration to a conference call: the 1-on-1\n          // is being ended specifically so both parties can rejoin via\n          // the new GroupCall. Hand off via the conference path (which\n          // suppresses the \"call ended\" audio and preserves media intent)\n          // instead of the normal hangUp. The support gate guarantees the\n          // browser can attach the per-receiver encryption transforms.\n          if(call.reason?._ === 'phoneCallDiscardReasonMigrateConferenceCall') {\n            if(IS_CONFERENCE_CALL_SUPPORTED) {\n              await this.migrateToConference(instance, call.reason.slug);\n            } else {\n              // This is still a transport handoff attempt, even though this\n              // browser cannot complete it. Do not play a normal \"call\n              // ended\" / \"failed\" tone on top of the capability toast.\n              this.migratingCalls.add(instance);\n              await instance.hangUp(call.reason, true);\n              toastNew({langPackKey: 'ConferenceCall.Unsupported'});\n            }\n            break;\n          }\n          await instance.hangUp(call.reason, true);\n        }\n\n        break;\n      }\n\n      case 'phoneCallAccepted': {\n        if(!instance) {\n          break;\n        }\n\n        // Only the caller confirms, and only once it holds `a` (tdesktop:\n        // \"Unexpected phoneCallAccepted for an incoming call\"; tdlib takes it\n        // in WaitRequestResult alone). Anything else must not touch the\n        // exchange — before this gate the callee crashed on `dh.a` and hung up.\n        if(!instance.isOutgoing || !instance.dh?.a) {\n          this.log.warn('ignoring phoneCallAccepted for a call that is not awaiting acceptance', call.id);\n          break;\n        }\n\n        if(!this.isProtocolCompatible(call.protocol)) {\n          this.log.warn('callee speaks no protocol version this client does', call.id);\n          await instance.hangUp('phoneCallDiscardReasonDisconnect');\n          this.dispatchEvent('incompatible', instance.interlocutorUserId);\n          break;\n        }\n\n        instance.setPhoneCall(call);\n        await instance.confirmCall();\n        break;\n      }\n\n      case 'phoneCallRequested': {\n        if(instance || !this.isIncomingCallRequestPlausible(call)) {\n          break;\n        }\n\n        if(!this.isProtocolCompatible(call.protocol)) {\n          // tdesktop finds this out only once tgcalls refuses to create the\n          // instance after the key exchange (ERROR_INCOMPATIBLE → finish(Failed),\n          // i.e. phoneCallDiscardReasonDisconnect). The request already tells:\n          // end it with the same reason instead of ringing for a call that\n          // cannot connect.\n          this.log.warn('caller speaks no protocol version this client does', call.id);\n          void this.managers.appCallsManager.discardCall(\n            call.id,\n            0,\n            {_: 'phoneCallDiscardReasonDisconnect'},\n            call.pFlags.video\n          ).catch((err) => {\n            this.log.error('discarding an incompatible call request failed', err);\n          });\n          this.dispatchEvent('incompatible', call.admin_id);\n          break;\n        }\n\n        const incoming = this.createCallInstance({\n          isOutgoing: false,\n          interlocutorUserId: call.admin_id\n        });\n\n        incoming.overrideConnectionState(CALL_STATE.PENDING);\n        incoming.setPhoneCall(call);\n        // Unanswered is \"missed\" — unless another call is still up when the\n        // timer fires, which is what \"busy\" means to the caller.\n        incoming.setHangUpTimeout(CALL_REQUEST_TIMEOUT, () => {\n          return this.isOtherCallActive(incoming) ? 'phoneCallDiscardReasonBusy' : 'phoneCallDiscardReasonMissed';\n        });\n\n        // tdesktop sends this before ringing (calls_call.cpp startIncoming): it\n        // is what turns the caller's \"waiting\" into \"ringing\".\n        void this.managers.appCallsManager.receivedCall(call.id).catch((err) => {\n          this.log.error('phone.receivedCall failed', err);\n        });\n        break;\n      }\n\n      case 'phoneCall': {\n        if(!instance) {\n          break;\n        }\n\n        // The caller derived the key from phone.confirmCall's answer; the\n        // update only mirrors it.\n        if(instance.isOutgoing) {\n          instance.setPhoneCall(call);\n          break;\n        }\n\n        // `dh.g_a` is what getEmojisFingerprint hashes into the emoji SAS — the only\n        // human-verifiable MITM defence of the call — so a server-relayed value must\n        // never land there before it is checked against the commitment, and a failed\n        // check has to be fatal instead of leaving a poisoned value behind.\n        // `dh.g_a` being set already means there is nothing to accept, and the\n        // in-flight flag closes the window that the two awaits below open for a\n        // second, forged update.\n        if(instance.encryptionKey || instance.dh?.g_a || instance.isVerifyingPeerG_a) {\n          break;\n        }\n\n        // Not accepted yet, so there is no `b` to derive a key with: tdlib\n        // takes phoneCall in WaitAcceptResult / WaitConfirmResult alone.\n        if(!instance.dh?.b) {\n          this.log.warn('ignoring phoneCall for a call that has not been accepted', call.id);\n          break;\n        }\n\n        instance.setPhoneCall(call);\n        instance.isVerifyingPeerG_a = true;\n\n        // Only what the peer sent in the clear may be logged: `dh` holds the\n        // private exponent, and error-level logs are kept in production.\n        const dh = instance.dh;\n        const g_a = call.g_a_or_b;\n        const g_a_hash = await apiManagerProxy.invokeCrypto('sha256', g_a);\n        if(instance.isClosing) break;\n        if(!bytesCmpConstTime(dh.g_a_hash, g_a_hash)) {\n          this.log.error('Incorrect g_a_hash', {expected: bytesToHex(dh.g_a_hash), actual: bytesToHex(g_a_hash)});\n          await instance.hangUp('phoneCallDiscardReasonDisconnect');\n          break;\n        }\n\n        let key: Uint8Array, key_fingerprint: string;\n        try {\n          ({key, key_fingerprint} = await this.managers.appCallsManager.computeKey(g_a, dh.b, dh.p));\n        } catch(err) {\n          this.log.error('computeKey failed (invalid DH public value)', err, {g_a_length: g_a?.length});\n          await instance.hangUp('phoneCallDiscardReasonDisconnect');\n          break;\n        }\n        if(instance.isClosing) break;\n        // The server's long arrives as a JS number whenever it fits 53 bits\n        // (fetchLong), the local one is always a decimal string — a strict\n        // compare dropped one correct incoming call in a thousand.\n        if(String(call.key_fingerprint) !== key_fingerprint) {\n          this.log.error('Incorrect key fingerprint', {expected: key_fingerprint, actual: String(call.key_fingerprint)});\n          await instance.hangUp('phoneCallDiscardReasonDisconnect');\n          break;\n        }\n\n        // Authenticated against both the commitment and the key fingerprint — only\n        // now may it drive the SAS.\n        instance.dh.g_a = g_a;\n        instance.encryptionKey = key;\n        instance.joinCall();\n\n        break;\n      }\n\n      default: {\n        instance?.setPhoneCall(call);\n        break;\n      }\n    }\n  }\n\n  /**\n   * `Instance::handleCallUpdate` (calls_instance.cpp:676): a request that names\n   * someone else as the callee, or ourselves as the caller, is not ours to ring\n   * for, and one older than the ring window is already over (\"Ignoring too old\n   * call\").\n   */\n  private isIncomingCallRequestPlausible(call: PhoneCall.phoneCallRequested) {\n    const myId = rootScope.myId;\n    if(call.participant_id.toPeerId() !== myId || call.admin_id.toPeerId() === myId) {\n      this.log.warn('ignoring a call request not addressed to this account', call.id);\n      return false;\n    }\n\n    if(call.date + CALL_REQUEST_TIMEOUT / 1000 < tsNow(true)) {\n      this.log.warn('ignoring a call request that is too old', call.id);\n      return false;\n    }\n\n    return true;\n  }\n\n  // This client speaks exactly the tgcalls versions in getCallProtocol; a peer\n  // whose list has none of them cannot be connected to whatever happens next.\n  private isProtocolCompatible(protocol: PhoneCallProtocol) {\n    return !!protocol?.library_versions?.some((version) => CALL_PROTOCOL_LIBRARY_VERSIONS.includes(version));\n  }\n\n  /**\n   * Whether a call other than `exclude` is up — another 1-on-1, a group call\n   * or a live stream. What \"busy\" means to an incoming call or invitation.\n   */\n  public isOtherCallActive(exclude?: CallInstance) {\n    const {currentCall} = this;\n    const {groupCall} = groupCallsController;\n    return !!(\n      (currentCall && currentCall !== exclude) ||\n      rtmpCallsController.currentCall ||\n      (groupCall && groupCall.state !== GROUP_CALL_STATE.CLOSED)\n    );\n  }\n\n  /**\n   * `#?call=<id>` — a tab opened from the notification of a call that rang\n   * while no tab of this account was open. The manager still holds the call\n   * while it rings; anything else (answered, discarded, already ringing here)\n   * is no reason to open a popup.\n   */\n  public async ringRequestedCall(callId: CallId) {\n    if(!this.instances) {\n      return;\n    }\n\n    const call = await this.managers.appCallsManager.getCall(callId);\n    if(call?._ !== 'phoneCallRequested' || this.instances.has(call.id)) {\n      return;\n    }\n\n    rootScope.dispatchEvent('call_update', call);\n  }\n\n  private discardAllOnUnload() {\n    for(const instance of this.instances.values()) {\n      const state = instance.connectionState;\n      if(instance.isClosing) {\n        continue;\n      }\n\n      // A ringing incoming call is not this tab's alone: the other devices keep\n      // ringing, and tdesktop leaves it on quit too (`isQuitPrevent`).\n      if(!instance.isOutgoing && state === CALL_STATE.PENDING) {\n        continue;\n      }\n\n      // tdesktop `Call::hangup`: an outgoing call nobody answered is missed.\n      const reason = state === CALL_STATE.PENDING || state === CALL_STATE.REQUESTING ?\n        'phoneCallDiscardReasonMissed' :\n        'phoneCallDiscardReasonHangup';\n      void this.managers.appCallsManager.discardCall(\n        instance.id,\n        instance.duration,\n        {_: reason},\n        instance.isSharingVideo || instance.isSharingScreen\n      ).catch(noop);\n    }\n  }\n\n  // A second incoming call while another call is current (call waiting): it\n  // has to be heard, quietly, and fall silent as soon as it stops pending —\n  // answered here (it becomes current), answered elsewhere, or given up on.\n  private setCallWaitingRinging(instance: CallInstance, ringing: boolean) {\n    if(ringing) {\n      this.callWaitingInstance = instance;\n      this.callWaitingAudioAsset ??= new AudioAssetPlayer({incoming: CALL_AUDIO_ASSETS.incoming});\n      this.callWaitingAudioAsset.play({name: 'incoming', loop: true, volume: CALL_WAITING_RING_VOLUME});\n    } else if(this.callWaitingInstance === instance) {\n      this.callWaitingInstance = undefined;\n      this.callWaitingAudioAsset.stop();\n    }\n  }\n\n  public get currentCall() {\n    return this.sortedInstances?.[0];\n  }\n\n  public getCallByUserId(userId: UserId) {\n    for(const [callId, instance] of this.instances) {\n      if(instance.interlocutorUserId === userId) {\n        return instance;\n      }\n    }\n  }\n\n  private createCallInstance(options: {\n    isOutgoing: boolean,\n    interlocutorUserId: UserId,\n    protocol?: PhoneCallProtocol\n  }) {\n    const call = new CallInstance({\n      managers: this.managers,\n      ...options\n    });\n\n    call.addEventListener('state', (state) => {\n      const currentCall = this.currentCall;\n      if(state === CALL_STATE.CLOSED) {\n        this.instances.delete(call.id);\n        indexOfAndSplice(this.sortedInstances, call);\n      } else {\n        insertInDescendSortedArray(this.sortedInstances, call, 'sortIndex');\n      }\n\n      if(state === CALL_STATE.EXCHANGING_KEYS) {\n        call.wasTryingToJoin = true;\n      }\n\n      const hasConnected = call.connectedAt !== undefined;\n      if(state === CALL_STATE.EXCHANGING_KEYS || (state === CALL_STATE.CONNECTING && hasConnected)) {\n        call.setHangUpTimeout(CALL_REQUEST_TIMEOUT, 'phoneCallDiscardReasonDisconnect');\n      } else {\n        call.clearHangUpTimeout();\n      }\n\n      this.setCallWaitingRinging(\n        call,\n        !call.isOutgoing && state === CALL_STATE.PENDING && !!currentCall && currentCall !== call\n      );\n\n      if(currentCall === call || !currentCall) {\n        if(state === CALL_STATE.CLOSED) {\n          if(this.migratingCalls.has(call)) {\n            // A migration is a transport handoff, not a user-visible call end.\n            // Keep the controller-wide asset quiet while the conference joins.\n            this.audioAsset.stop();\n          } else if(!call.isOutgoing && !call.wasTryingToJoin) { // incoming call has been accepted on other device or ended\n            this.audioAsset.stop();\n          } else if(call.wasTryingToJoin && !hasConnected) { // something has happened during the key exchanging\n            this.audioAsset.play({name: 'failed'});\n          } else {\n            // `discardReason` is only set by hangUp, and a CLOSED transition can\n            // arrive without it — a transport failure derives CLOSED straight\n            // from the engine state. Dereferencing it unconditionally threw\n            // there, and EventListenerBase swallows listener errors, so the\n            // end-of-call sound was silently skipped instead of anything\n            // visible breaking.\n            this.audioAsset.play(call.discardReason?._ === 'phoneCallDiscardReasonBusy' ? {name: 'busy'} : {name: 'end'});\n          }\n        } else if(state === CALL_STATE.PENDING) {\n          // Incoming during a group call or a live stream: audible, but under\n          // the conversation.\n          this.audioAsset.play({\n            name: call.isOutgoing ? 'outgoing' : 'incoming',\n            loop: true,\n            volume: !call.isOutgoing && this.isOtherCallActive(call) ? CALL_WAITING_RING_VOLUME : 1\n          });\n        } else if(state === CALL_STATE.EXCHANGING_KEYS) {\n          this.audioAsset.playIfDifferent({name: 'connect'});\n        } else if(state === CALL_STATE.CONNECTING) {\n          if(call.duration) {\n            this.audioAsset.play({name: 'connect', loop: true});\n          }\n        } else {\n          this.audioAsset.stop();\n        }\n      }\n    });\n\n    call.addEventListener('id', (id, prevId) => {\n      if(prevId !== undefined) {\n        this.instances.delete(prevId);\n      }\n\n      const hasCurrent = !!this.currentCall;\n      this.instances.set(id, call);\n\n      if(prevId === undefined) {\n        this.dispatchEvent('instance', {instance: call, hasCurrent: hasCurrent});\n      }\n    });\n\n    return call;\n  }\n\n  public async startCallInternal(userId: UserId, isVideo: boolean) {\n    this.log('p2pStartCallInternal', userId, isVideo);\n\n    const fullInfo = await this.managers.appProfileManager.getProfile(userId);\n    if(!fullInfo) return;\n\n    const {video_calls_available} = fullInfo.pFlags;\n\n    const call = this.createCallInstance({\n      isOutgoing: true,\n      interlocutorUserId: userId\n    });\n\n    call.overrideConnectionState(CALL_STATE.REQUESTING);\n    call.setPhoneCall({\n      _: 'phoneCallWaiting',\n      access_hash: '',\n      admin_id: NULL_PEER_ID,\n      date: tsNow(true),\n      id: --this.tempId,\n      participant_id: userId,\n      protocol: call.protocol,\n      pFlags: {\n        video: isVideo || undefined\n      }\n    });\n\n    try {\n      const dh = await this.managers.appCallsManager.generateDh();\n      if(call.isClosing) return;\n\n      call.dh = dh;\n\n      const phoneCall = await this.managers.appCallsManager.requestCall(\n        userId,\n        call.protocol,\n        call.dh.g_a_hash,\n        isVideo && video_calls_available\n      );\n      if(call.isClosing) {\n        if(phoneCall._ !== 'phoneCallEmpty' && phoneCall._ !== 'phoneCallDiscarded') {\n          // requestCall was accepted after a local close won the race. The\n          // manager has already saved the exact echoed id/access_hash, so\n          // discard it before the global transition may release.\n          await this.managers.appCallsManager.discardCall(\n            phoneCall.id,\n            0,\n            {_: 'phoneCallDiscardReasonHangup'},\n            isVideo && video_calls_available\n          );\n        }\n        return;\n      }\n\n      call.overrideConnectionState(CALL_STATE.PENDING);\n      call.setPhoneCall(phoneCall);\n      call.setHangUpTimeout(CALL_REQUEST_TIMEOUT, 'phoneCallDiscardReasonHangup');\n    } catch(err) {\n      this.log.error('outgoing call DH/setup error', err);\n      if(!call.isClosing) {\n        try {\n          await call.hangUp('phoneCallDiscardReasonHangup');\n        } catch(hangUpError) {\n          this.log.error('outgoing call cleanup failed', hangUpError);\n        }\n      }\n    }\n  }\n\n  // ===== 1-on-1 → conference migration =====\n  //\n  // Called when a 1-on-1 PhoneCall is discarded with the migrate reason. We\n  // stop the P2P engine but DO NOT play the \"call ended\" tone, and we\n  // carry over only media intent (mute/video). P2P duration and its emoji\n  // fingerprint do not describe the new conference security context and must\n  // not leak into it. The migration reason's\n  // slug is then resolved to the canonical call and joined through the same\n  // controller path as an invite link.\n  //\n  private migrateToConference(instance: CallInstance, slug: string): Promise<void> {\n    return callTransitionCoordinator.run(() => this.migrateToConferenceInternal(instance, slug));\n  }\n\n  private async migrateToConferenceInternal(instance: CallInstance, slug: string): Promise<void> {\n    this.log('migrateToConference', instance.id);\n    const wasMuted = instance.isMuted;\n    const wasVideo = instance.isSharingVideo;\n\n    // Tear down the 1-on-1 without sending discard or playing audio. The\n    // server already discarded the call; instance.hangUp with no reason\n    // skips the API call but still walks the state machine to CLOSED.\n    this.migratingCalls.add(instance);\n    this.dispatchEvent('conferenceMigration', {instance, state: 'started'});\n    let completed = false;\n    try {\n      await instance.hangUp(undefined, true);\n      const resolved = await this.managers.appGroupCallsManager.resolveConferenceCall({\n        _: 'inputGroupCallSlug',\n        slug\n      });\n      if(resolved._ === 'groupCallDiscarded') {\n        toastNew({langPackKey: 'InviteExpired'});\n        return;\n      }\n      await groupCallsController.joinConference({\n        input: {_: 'inputGroupCallSlug', slug},\n        expectedCanonicalInput: groupCallToInput(resolved),\n        selfUserId: BigInt(rootScope.myId),\n        chatId: NULL_PEER_ID,\n        muted: wasMuted,\n        joinVideo: wasVideo\n      });\n      completed = true;\n    } catch(err) {\n      this.log.error('migrateToConference: conference join failed', err);\n      toastNew({langPackKey: getConferenceInviteErrorLangKey(err)});\n    } finally {\n      this.dispatchEvent('conferenceMigration', {\n        instance,\n        state: completed ? 'completed' : 'failed'\n      });\n    }\n  }\n}\n\nconst callsController = new CallsController();\nDEBUG && (MOUNT_CLASS_TO.callsController = callsController);\nexport default callsController;\n","/*\n * A ringing conference-call invitation. It is not a call yet: there is no\n * media, no key exchange and no server-side call object bound to this client —\n * only the invite service message that authorizes the join.\n *\n * tdesktop models this with the very same `Calls::Call` class it uses for\n * 1-on-1 calls, in \"conference invite\" mode (calls_call.h:125), so the incoming\n * call panel, the ringtone and the accept/decline buttons are shared. We do the\n * same with a small instance the call popup understands, instead of teaching\n * the whole P2P `CallInstance` to be inert.\n */\n\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport CALL_STATE from '@lib/calls/callState';\nimport {logger} from '@lib/logger';\n\nexport type ConferenceInviteInstanceOptions = {\n  interlocutorUserId: UserId,\n  /** Server id of the invite service message — the join/decline authorization. */\n  msgId: number,\n  conferenceId: string,\n  /** Everyone the invite mentions, inviter included, for the panel's userpics. */\n  participants: PeerId[],\n  onAccept: (instance: ConferenceInviteInstance) => Promise<void>,\n  onDecline: (instance: ConferenceInviteInstance) => Promise<void>\n};\n\nexport default class ConferenceInviteInstance extends EventListenerBase<{\n  state: (state: CALL_STATE) => void\n}> {\n  public readonly isOutgoing = false;\n  public readonly wasTryingToJoin = false;\n  public readonly connectedAt: number = undefined;\n  public readonly duration = 0;\n\n  public readonly interlocutorUserId: UserId;\n  public readonly msgId: number;\n  public readonly conferenceId: string;\n  public readonly participants: PeerId[];\n\n  private log: ReturnType<typeof logger>;\n  private state: CALL_STATE;\n  private onAccept: ConferenceInviteInstanceOptions['onAccept'];\n  private onDecline: ConferenceInviteInstanceOptions['onDecline'];\n\n  constructor(options: ConferenceInviteInstanceOptions) {\n    super(false);\n\n    this.interlocutorUserId = options.interlocutorUserId;\n    this.msgId = options.msgId;\n    this.conferenceId = options.conferenceId;\n    this.participants = options.participants;\n    this.onAccept = options.onAccept;\n    this.onDecline = options.onDecline;\n\n    this.log = logger('CONFERENCE-INVITE-' + this.msgId);\n    this.state = CALL_STATE.PENDING;\n  }\n\n  public get connectionState() {\n    return this.state;\n  }\n\n  public get isClosing() {\n    return this.state === CALL_STATE.CLOSED;\n  }\n\n  private setState(state: CALL_STATE) {\n    if(this.state === state) {\n      return;\n    }\n\n    this.state = state;\n    this.dispatchEvent('state', state);\n  }\n\n  /**\n   * Accept — tdesktop's `Call::acceptConferenceInvite` (calls_call.cpp:435):\n   * move out of the ringing state first, then resolve the conference from the\n   * invite message and join it. A failed join closes the invite instead of\n   * leaving a panel that rings forever.\n   */\n  public async acceptCall() {\n    if(this.state !== CALL_STATE.PENDING) {\n      return;\n    }\n\n    this.setState(CALL_STATE.EXCHANGING_KEYS);\n\n    try {\n      await this.onAccept(this);\n    } catch(err) {\n      this.log.error('conference invite accept failed', err);\n      throw err;\n    } finally {\n      this.close();\n    }\n  }\n\n  /**\n   * Decline — tdesktop's `Call::hangup` in invite mode (calls_call.cpp:1540):\n   * declines every incoming invite of this conference, not just this message.\n   */\n  public async hangUp() {\n    if(this.state === CALL_STATE.CLOSED) {\n      return;\n    }\n\n    const wasPending = this.state === CALL_STATE.PENDING;\n    this.close();\n\n    if(wasPending) {\n      await this.onDecline(this);\n    }\n  }\n\n  /**\n   * Retract the invite without declining it — the invite message was revoked,\n   * the call moved on without us, or another call took over.\n   */\n  public close() {\n    this.setState(CALL_STATE.CLOSED);\n  }\n}\n","/*\n * Incoming conference-call invitations.\n *\n * A conference invite arrives as a `messageActionConferenceCall` service\n * message in a private chat, and tdesktop treats it as a ringing incoming call\n * rather than as something you act on inside the chat: `History` shows the\n * invite (history.cpp:1507), `Calls::Instance` keeps a registry of every invite\n * message per conference (calls_instance.cpp:1052) and rings, declines or drops\n * it as the registry changes.\n *\n * This controller is the tweb counterpart of those `Instance::*ConferenceInvite*`\n * methods. It owns the registry and the ringing lifecycle; the popup is created\n * by whoever listens to the `instance` event, exactly like `CallsController`.\n */\n\nimport DEBUG, {MOUNT_CLASS_TO} from '@config/debug';\nimport IS_CONFERENCE_CALL_SUPPORTED from '@environment/conferenceCallSupport';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport getCallAudioAsset from '@components/call/getAudioAsset';\nimport EventListenerBase from '@helpers/eventListenerBase';\nimport tsNow from '@helpers/tsNow';\nimport {Message} from '@layer';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport {FullMid, makeFullMid} from '@appManagers/utils/messages/fullMid';\nimport {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport CALL_STATE from '@lib/calls/callState';\nimport callsController from '@lib/calls/callsController';\nimport ConferenceInviteInstance from '@lib/calls/conferenceInviteInstance';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\nimport {CALL_REQUEST_TIMEOUT} from '@lib/calls/constants';\nimport {getConferenceCallState} from '@lib/calls/helpers/conferenceCallAction';\nimport sameInputGroupCall from '@lib/calls/helpers/sameInputGroupCall';\n\ntype InviteEntry = {\n  peerId: PeerId,\n  /** Local (tweb) mid — the id `history_delete` and `message_edit` speak in. */\n  mid: number,\n  /** Server msg id — the id `phone.declineConferenceCallInvite` speaks in. */\n  serverMsgId: number,\n  conferenceId: string,\n  fromId: PeerId,\n  date: number,\n  participants: PeerId[],\n  isOutgoing: boolean\n};\n\nexport class ConferenceInvitesController extends EventListenerBase<{\n  instance: (instance: ConferenceInviteInstance) => void\n}> {\n  private log: ReturnType<typeof logger>;\n  private managers: AppManagers;\n  private audioAsset: ReturnType<typeof getCallAudioAsset>;\n\n  /** Every known invite message, keyed by its full mid. */\n  private invites: Map<FullMid, InviteEntry>;\n  /** Incoming invite keys per conference — the unit decline works on. */\n  private incoming: Map<string, Set<FullMid>>;\n  /** The conference currently ringing, if any. */\n  private ringing: Map<string, ConferenceInviteInstance>;\n\n  public construct(managers: AppManagers) {\n    this.managers = managers;\n    this.log = logger('CONFERENCE-INVITES');\n    this.invites = new Map();\n    this.incoming = new Map();\n    this.ringing = new Map();\n\n    if(!IS_GROUP_CALL_SUPPORTED) {\n      return;\n    }\n\n    this.audioAsset = getCallAudioAsset();\n\n    rootScope.addEventListener('history_multiappend', (message) => {\n      this.onMessage(message as Message.messageService, true);\n    });\n\n    rootScope.addEventListener('message_edit', ({message}) => {\n      // The server edits the very same service message as the call moves on:\n      // `active` once someone joins, `missed` when nobody did, a duration once\n      // it ends. tdesktop rebuilds the media and drops the registration in\n      // `HistoryItem::applyEdition` (history_item.cpp:2574).\n      this.onMessage(message as Message.messageService, false);\n    });\n\n    rootScope.addEventListener('history_delete', ({peerId, msgs}) => {\n      for(const mid of msgs) {\n        this.unregister(makeFullMid(peerId, mid));\n      }\n    });\n\n    // A call that starts while an invitation is ringing takes the device over,\n    // so the invitation cannot stay pending — it is declined, the same way an\n    // invitation that arrives during a call is (calls_instance.cpp:1193).\n    callsController.addEventListener('instance', () => this.declineWhileBusy());\n    groupCallsController.addEventListener('instance', () => this.declineWhileBusy());\n  }\n\n  private onMessage(message: Message.messageService, isNew: boolean) {\n    const action = message?.action;\n    if(action?._ !== 'messageActionConferenceCall') {\n      return;\n    }\n\n    const key = makeFullMid(message);\n    const conferenceId = '' + action.call_id;\n    const isInvitation = getConferenceCallState(action) === 'invitation';\n\n    // Anything but a pending invitation is no longer actionable: unregister it\n    // and stop ringing for it.\n    if(!isInvitation || !message.peerId.isUser()) {\n      this.unregister(key);\n      return;\n    }\n\n    const isOutgoing = !!message.pFlags.out;\n    const entry: InviteEntry = {\n      peerId: message.peerId,\n      mid: message.mid,\n      serverMsgId: getServerMessageId(message.mid),\n      conferenceId,\n      fromId: message.fromId,\n      date: message.date,\n      participants: this.getParticipants(message),\n      isOutgoing\n    };\n\n    if(this.invites.has(key)) {\n      return;\n    }\n\n    this.invites.set(key, entry);\n    if(isOutgoing) {\n      return;\n    }\n\n    let set = this.incoming.get(conferenceId);\n    if(!set) {\n      this.incoming.set(conferenceId, set = new Set<FullMid>());\n    }\n    set.add(key);\n\n    if(isNew) {\n      this.show(entry);\n    }\n  }\n\n  private getParticipants(message: Message.messageService) {\n    const action = message.action as {other_participants?: Parameters<typeof getPeerId>[0][]};\n    const participants: PeerId[] = [];\n    const add = (peerId: PeerId) => {\n      if(peerId && peerId !== rootScope.myId && !participants.includes(peerId)) {\n        participants.push(peerId);\n      }\n    };\n\n    add(message.fromId);\n    action.other_participants?.forEach((peer) => add(getPeerId(peer)));\n    return participants;\n  }\n\n  private unregister(key: FullMid) {\n    const entry = this.invites.get(key);\n    if(!entry) {\n      return;\n    }\n\n    this.invites.delete(key);\n\n    const {conferenceId} = entry;\n    const set = this.incoming.get(conferenceId);\n    if(set) {\n      set.delete(key);\n      if(!set.size) {\n        this.incoming.delete(conferenceId);\n\n        // The last invite that could still be accepted is gone — the panel\n        // must not keep ringing for it (calls_instance.cpp:1091).\n        this.ringing.get(conferenceId)?.close();\n      }\n    }\n  }\n\n  private isBusy() {\n    return callsController.isOtherCallActive();\n  }\n\n  private isInConference(conferenceId: string) {\n    const groupCall = groupCallsController.groupCall;\n    if(!groupCall || groupCall.state === GROUP_CALL_STATE.CLOSED) {\n      return false;\n    }\n\n    const input = groupCall.toInputGroupCall();\n    return !!input && sameInputGroupCall(input, {\n      _: 'inputGroupCall',\n      id: conferenceId,\n      access_hash: ''\n    });\n  }\n\n  /**\n   * `Instance::showConferenceInvite` (calls_instance.cpp:1166): every reason\n   * not to ring, in the same order — invited by ourselves, calls switched off\n   * for this session, already in this very conference, busy with another call,\n   * or the invitation is simply too old to still be live.\n   */\n  private show(entry: InviteEntry) {\n    const {conferenceId} = entry;\n\n    // Per-frame E2E needs RTCRtpScriptTransform. Without it the invitation\n    // cannot be accepted at all, so stay silent rather than ring or decline on\n    // the user's behalf — the bubble still explains what happened.\n    if(!IS_CONFERENCE_CALL_SUPPORTED) {\n      return;\n    }\n\n    if(entry.fromId === rootScope.myId) {\n      this.log('ignoring a conference invitation from this very account', entry.serverMsgId);\n      return;\n    }\n\n    if(this.ringing.has(conferenceId) || this.isInConference(conferenceId)) {\n      return;\n    }\n\n    // `callsDisabledForSession()` (calls_instance.cpp:1177): the session's own\n    // \"accept calls on this device\" switch. tdesktop reads a cached flag; here\n    // it is one round trip, after which the invitation is checked again.\n    void this.managers.appAccountManager.isCallRequestsDisabled().then((disabled) => {\n      if(disabled) {\n        this.log('ignoring a conference invitation: call requests are disabled for this session', entry.serverMsgId);\n        return;\n      }\n\n      this.ring(entry);\n    });\n  }\n\n  private ring(entry: InviteEntry) {\n    const {conferenceId} = entry;\n\n    // The round trip above may have outlived the invitation.\n    if(\n      !this.invites.has(makeFullMid(entry.peerId, entry.mid)) ||\n      this.ringing.has(conferenceId) ||\n      this.isInConference(conferenceId)\n    ) {\n      return;\n    }\n\n    if(this.isBusy()) {\n      void this.declineIncoming(conferenceId);\n      return;\n    }\n\n    // tdesktop stops offering an invitation older than the server's\n    // `call_ring_timeout_ms` (calls_instance.cpp:1194); that value is not\n    // plumbed into tweb, so the ringing window is the one the 1-on-1 path\n    // already assumes.\n    if((entry.date * 1000 + CALL_REQUEST_TIMEOUT) < tsNow()) {\n      this.log('ignoring a conference invitation that is too old', entry.serverMsgId);\n      void this.declineIncoming(conferenceId);\n      return;\n    }\n\n    const instance = new ConferenceInviteInstance({\n      interlocutorUserId: entry.fromId.toUserId(),\n      msgId: entry.serverMsgId,\n      conferenceId,\n      participants: entry.participants,\n      onAccept: (instance) => this.accept(instance),\n      onDecline: (instance) => this.declineIncoming(instance.conferenceId)\n    });\n\n    this.ringing.set(conferenceId, instance);\n    this.audioAsset.play({name: 'incoming', loop: true});\n\n    instance.addEventListener('state', (state) => {\n      if(state !== CALL_STATE.CLOSED) {\n        return;\n      }\n\n      if(this.ringing.get(conferenceId) === instance) {\n        this.ringing.delete(conferenceId);\n      }\n\n      if(!this.ringing.size) {\n        this.audioAsset.stop();\n      }\n    });\n\n    this.dispatchEvent('instance', instance);\n  }\n\n  private async accept(instance: ConferenceInviteInstance) {\n    // The ringtone belongs to the invitation, not to the call being joined.\n    this.audioAsset.stop();\n\n    // Dynamic import: `appImManager` statically imports the call UI, so a\n    // static import here would close a cycle. It owns the whole join policy —\n    // support gate, dead-link toast, leaving whatever call is current — and\n    // `confirmed` skips the \"join this call?\" prompt, which pressing Accept on\n    // a ringing invitation has already answered.\n    const {default: appImManager} = await import('@lib/appImManager');\n    await appImManager.joinConference({\n      _: 'inputGroupCallInviteMessage',\n      msg_id: instance.msgId\n    }, {confirmed: true});\n  }\n\n  /**\n   * `Instance::declineIncomingConferenceInvites` (calls_instance.cpp:1099):\n   * one conference can have been offered by several invite messages, and\n   * declining the call declines all of them.\n   */\n  public async declineIncoming(conferenceId: string) {\n    const set = this.incoming.get(conferenceId);\n    const keys = set ? [...set] : [];\n\n    this.ringing.get(conferenceId)?.close();\n\n    for(const key of keys) {\n      const entry = this.invites.get(key);\n      this.unregister(key);\n      if(!entry) {\n        continue;\n      }\n\n      try {\n        await this.managers.appCallsManager.declineConferenceCallInvite(entry.serverMsgId);\n      } catch(err) {\n        this.log.error('declineConferenceCallInvite failed', err, entry.serverMsgId);\n      }\n    }\n  }\n\n  private declineWhileBusy() {\n    for(const [conferenceId, instance] of this.ringing) {\n      if(instance.connectionState !== CALL_STATE.PENDING || this.isInConference(conferenceId)) {\n        continue;\n      }\n\n      void this.declineIncoming(conferenceId);\n    }\n  }\n}\n\nconst conferenceInvitesController = new ConferenceInvitesController();\nDEBUG && (MOUNT_CLASS_TO.conferenceInvitesController = conferenceInvitesController);\nexport default conferenceInvitesController;\n","export type DialogMentionBadgeStateOptions = {\n  /**\n   * Whatever the unread badge itself counts: unread topics for a forum, unread\n   * chats for a community, unread messages otherwise.\n   */\n  unreadCount: number,\n  /** Unread messages — differs from `unreadCount` when the badge counts topics/chats. */\n  unreadMessagesCount: number,\n  unreadMentionsCount: number,\n  hasUnreadBadge: boolean\n};\n\n/**\n * A mention is shown either as the unread badge turned into an '@', or as a\n * separate mentions badge next to the unread counter — never as both.\n *\n * Deriving the two from different values (topics for one, messages for the\n * other) made a forum row render both at once — two '@' badges for a single\n * mention (issue #628) — hence the explicit `!isMention`.\n */\nexport default function getDialogMentionBadgeState({\n  unreadCount,\n  unreadMessagesCount,\n  unreadMentionsCount,\n  hasUnreadBadge\n}: DialogMentionBadgeStateOptions) {\n  const hasUnreadMentions = !!unreadMentionsCount;\n\n  // the whole unread state is a single mention — the unread badge becomes the '@'\n  const isMention = hasUnreadBadge && hasUnreadMentions && unreadCount === 1;\n\n  const hasMentionsBadge = hasUnreadMentions &&\n    !isMention &&\n    (unreadMentionsCount > 1 || unreadMessagesCount > 1);\n\n  return {isMention, hasMentionsBadge};\n}\n","import {createRoot, createSignal, Show} from 'solid-js';\nimport type {default as SidebarSlider, SliderSuperTab} from '@components/slider';\nimport type {SliderSuperTabEventable, SliderSuperTabEventableConstructable} from '@components/sliderTab';\nimport Button from '@components/button';\nimport CheckboxField, {CheckboxFieldOptions} from '@components/checkboxField';\nimport Icon from '@components/icon';\nimport Row, {createRowTitle, type RowMediaSizeType} from '@components/rowTsx';\nimport htmlToDocumentFragment from '@helpers/dom/htmlToDocumentFragment';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport type {Middleware} from '@helpers/middleware';\n\nexport type {RowMediaSizeType} from '@components/rowTsx';\n\ntype RowContent = string | HTMLElement | DocumentFragment | true;\n\ntype ConstructorP<T> = T extends {\n  new (...args: any[]): infer U;\n} ? U : never;\n\nexport type RowTsxOptions<T extends SliderSuperTabEventableConstructable = any> = Partial<{\n  icon: Icon,\n  iconClasses: string[],\n  subtitle: RowContent,\n  subtitleLangKey: LangPackKey,\n  subtitleLangArgs: any[],\n  subtitleRight: RowContent,\n  checkboxField: CheckboxField,\n  checkboxFieldOptions: CheckboxFieldOptions,\n  withCheckboxSubtitle: boolean,\n  title: RowContent,\n  titleLangKey: LangPackKey,\n  titleLangArgs: any[],\n  titleRight: RowContent,\n  titleRightSecondary: RowContent,\n  clickable: boolean | ((e: MouseEvent) => void),\n  navigationTab: {\n    constructor: T,\n    slider: SidebarSlider,\n    getInitArgs?: () => Promise<Parameters<ConstructorP<T>['init']>[0]> | Parameters<ConstructorP<T>['init']>[0]\n    args?: any\n  },\n  havePadding: boolean,\n  noRipple: boolean,\n  noWrap: boolean,\n  listenerSetter: ListenerSetter,\n  middleware: Middleware,\n  buttonRight: HTMLElement | boolean,\n  buttonRightLangKey: LangPackKey,\n  rightContent: HTMLElement,\n  rightTextContent: string,\n  asLink: boolean,\n  contextMenu: Omit<Parameters<typeof createContextMenu>[0], 'findElement' | 'listenTo' | 'listenerSetter'>,\n  asLabel: boolean,\n  checkboxKeys: [LangPackKey, LangPackKey]\n}>;\n\nexport type RowTsxController = {\n  container: HTMLElement,\n  readonly titleRow: HTMLElement,\n  readonly titleRight: HTMLElement,\n  media: HTMLElement,\n  readonly subtitleRow: HTMLElement,\n  readonly subtitleRight: HTMLElement,\n  checkboxField: CheckboxField,\n  freezed: boolean,\n  buttonRight: HTMLElement,\n  readonly title: HTMLElement,\n  readonly subtitle: HTMLElement,\n  readonly midtitle: HTMLElement,\n  openContextMenu: ReturnType<typeof createContextMenu>['open'],\n  dispose: () => void,\n  ensureSubtitle: () => HTMLElement,\n  ensureMidtitle: () => HTMLElement,\n  createTitle: () => HTMLElement,\n  createMedia: (size?: RowMediaSizeType) => HTMLElement,\n  applyMediaElement: (media: HTMLElement, size?: RowMediaSizeType) => HTMLElement,\n  isDisabled: () => boolean,\n  toggleDisability: (disable?: boolean) => () => void,\n  disableWithPromise: (promise: Promise<any>) => void,\n  makeSortable: () => void,\n  toggleSorting: (enabled?: boolean) => void\n};\n\nconst resolveRowContent = (content: RowContent) => {\n  return typeof(content) === 'string' ? htmlToDocumentFragment(content) : content;\n};\n\n/** Mounts the Solid Row used by the remaining imperative dialog-row controller. */\nconst mountRowController = <T extends SliderSuperTabEventableConstructable = any>(\n  initialOptions: RowTsxOptions<T> = {}\n): RowTsxController => {\n  const options = {...initialOptions};\n  if(options.checkboxFieldOptions) {\n    options.checkboxField = new CheckboxField({\n      listenerSetter: options.listenerSetter,\n      ...options.checkboxFieldOptions\n    });\n  }\n\n  const checkboxField = options.checkboxField;\n  const isToggle = checkboxField?.label.classList.contains('checkbox-field-toggle');\n  checkboxField?.label.classList.add('disable-hover');\n\n  let clickable = options.clickable;\n  if(options.navigationTab) {\n    let getInitArgs = options.navigationTab.getInitArgs;\n    if(!getInitArgs) {\n      const getArgs = (options.navigationTab.constructor as any as typeof SliderSuperTab).getInitArgs;\n      if(getArgs) {\n        getInitArgs = () => getArgs();\n      }\n    }\n\n    let args = options.navigationTab.args ?? getInitArgs?.();\n    clickable = async() => {\n      if(args instanceof Promise) {\n        args = await args;\n      }\n\n      const tab = options.navigationTab.slider.createTab(options.navigationTab.constructor as any);\n      tab.open(args);\n\n      const eventListener = (tab as SliderSuperTabEventable).eventListener;\n      if(eventListener && getInitArgs) {\n        eventListener.addEventListener('destroyAfter', (promise) => {\n          args = promise.then(() => getInitArgs() as any);\n        });\n      }\n    };\n  }\n\n  let rightContent = options.rightContent;\n  let buttonRight: HTMLElement;\n  if(options.buttonRight || options.buttonRightLangKey) {\n    rightContent = buttonRight = options.buttonRight instanceof HTMLElement ?\n      options.buttonRight :\n      Button('btn-primary btn-color-primary btn-control-small', {text: options.buttonRightLangKey});\n  }\n\n  if(options.rightTextContent) {\n    rightContent = document.createElement('span');\n    rightContent.classList.add('row-title-right-secondary');\n    rightContent.textContent = options.rightTextContent;\n  }\n\n  const initialSubtitle = options.subtitleLangKey ?\n    i18n(options.subtitleLangKey, options.subtitleLangArgs) :\n    resolveRowContent(options.subtitle);\n  const initialTitle = options.titleLangKey ?\n    i18n(options.titleLangKey, options.titleLangArgs) :\n    resolveRowContent(options.title);\n  const titleRight = resolveRowContent(options.titleRight || options.titleRightSecondary);\n  const subtitleRight = resolveRowContent(options.subtitleRight);\n\n  let container: HTMLElement;\n  let openContextMenu: RowTsxController['openContextMenu'];\n  let freezed = false;\n  let currentMedia: HTMLElement;\n  const [hasSubtitle, setHasSubtitle] = createSignal(!!initialSubtitle);\n  const [hasMidtitle, setHasMidtitle] = createSignal(false);\n  const [media, setMedia] = createSignal<{element: HTMLElement, size?: RowMediaSizeType}>();\n  const parts: Partial<Record<\n    'title' | 'titleRow' | 'titleRight' | 'subtitle' | 'subtitleRow' | 'subtitleRight' | 'midtitle',\n    HTMLElement\n  >> = {};\n\n  const getPart = (className: string) => container.querySelector(`.${className}`) as HTMLElement;\n  const getTitle = () => container.querySelector(\n    ':scope > .row-title, :scope > .row-title-row > .row-title:not(.row-title-right)'\n  ) as HTMLElement;\n  const getSubtitle = () => container.querySelector(\n    ':scope > .row-subtitle, :scope > .row-subtitle-row > .row-subtitle:not(.row-subtitle-right)'\n  ) as HTMLElement;\n  const ensureSubtitle = () => {\n    setHasSubtitle(true);\n    return parts.subtitle ||= getSubtitle();\n  };\n  const ensureMidtitle = () => {\n    setHasMidtitle(true);\n    return parts.midtitle ||= getPart('row-midtitle');\n  };\n  let rootDispose: () => void;\n  let disposed = false;\n  const dispose = () => {\n    if(disposed) {\n      return;\n    }\n\n    disposed = true;\n    rootDispose?.();\n  };\n\n  const controller: RowTsxController = {\n    get container() {\n      return container;\n    },\n    get titleRow() {\n      return parts.titleRow;\n    },\n    get titleRight() {\n      return parts.titleRight;\n    },\n    get media() {\n      return currentMedia;\n    },\n    set media(value) {\n      currentMedia = value;\n    },\n    get subtitleRow() {\n      return parts.subtitleRow;\n    },\n    get subtitleRight() {\n      return parts.subtitleRight;\n    },\n    checkboxField,\n    get freezed() {\n      return freezed;\n    },\n    set freezed(value) {\n      freezed = value;\n    },\n    buttonRight,\n    get title() {\n      return parts.title;\n    },\n    get subtitle() {\n      return parts.subtitle;\n    },\n    get midtitle() {\n      return parts.midtitle;\n    },\n    get openContextMenu() {\n      return openContextMenu;\n    },\n    set openContextMenu(open) {\n      openContextMenu = open;\n    },\n    dispose,\n    ensureSubtitle,\n    ensureMidtitle,\n    createTitle: createRowTitle,\n    createMedia: (size?: RowMediaSizeType) => {\n      return controller.applyMediaElement(document.createElement('div'), size);\n    },\n    applyMediaElement: (element: HTMLElement, size?: RowMediaSizeType) => {\n      currentMedia = element;\n      setMedia({element, size});\n      return element;\n    },\n    isDisabled: () => container.classList.contains('is-disabled'),\n    toggleDisability: (disable = !container.classList.contains('is-disabled')) => {\n      container.classList.toggle('is-disabled', disable);\n      return () => controller.toggleDisability(!disable);\n    },\n    disableWithPromise: (promise: Promise<any>) => {\n      const toggle = controller.toggleDisability(true);\n      promise.finally(toggle);\n    },\n    makeSortable: () => {\n      container.classList.add('row-sortable');\n      container.append(Icon('menu', 'row-sortable-icon'));\n    },\n    toggleSorting: (enabled?: boolean) => {\n      container.classList.toggle('cant-sort', !enabled);\n    }\n  };\n\n  const clickHandler = clickable;\n  createRoot((_dispose) => {\n    rootDispose = _dispose;\n    return (\n      <Row\n      ref={(element) => container = element}\n      clickable={typeof(clickHandler) === 'function' ? (event) => {\n        if(!controller.freezed) {\n          clickHandler(event);\n        }\n      } : clickHandler}\n      havePadding={options.havePadding}\n      noRipple={options.noRipple}\n      noWrap={options.noWrap}\n      as={options.asLink ? 'a' : (options.asLabel ? 'label' : undefined)}\n      contextMenu={options.contextMenu}\n      openContextMenuRef={(open) => openContextMenu = open}\n    >\n      <Show when={hasMidtitle()}>\n        <Row.Midtitle>{true}</Row.Midtitle>\n      </Show>\n      <Show when={hasSubtitle()}>\n        <Row.Subtitle subtitleRight={subtitleRight}>{initialSubtitle || true}</Row.Subtitle>\n      </Show>\n      <Show when={options.icon}>\n        <Row.Icon icon={options.icon} class={(options.iconClasses || []).join(' ')} />\n      </Show>\n      <Show when={checkboxField && !isToggle}>\n        <Row.CheckboxField>{checkboxField.label}</Row.CheckboxField>\n      </Show>\n      <Show when={checkboxField && isToggle}>\n        <Row.CheckboxFieldToggle>{checkboxField.label}</Row.CheckboxFieldToggle>\n      </Show>\n      <Show when={rightContent}>\n        <Row.RightContent element={rightContent} />\n      </Show>\n      <Show keyed when={media()}>{(value) => (\n        <Row.Media element={value.element} size={value.size} />\n      )}</Show>\n      <Show when={initialTitle || titleRight || isToggle}>\n        <Row.Title\n          titleRight={titleRight}\n          titleRightSecondary={!!options.titleRightSecondary}\n        >\n          {initialTitle}\n        </Row.Title>\n      </Show>\n      </Row>\n    );\n  });\n\n  parts.title = getTitle();\n  parts.titleRow = getPart('row-title-row');\n  parts.titleRight = getPart('row-title-right');\n  parts.subtitle = getSubtitle();\n  parts.subtitleRow = getPart('row-subtitle-row');\n  parts.subtitleRight = getPart('row-subtitle-right');\n  parts.midtitle = getPart('row-midtitle');\n\n  // a Solid root is a RENDER lifetime, not an event-listener one: when the caller owns a\n  // middleware, that owns the disposal. A `listenerSetter` is only the fallback for callers\n  // without one - it can stop listening well before its owner is done rendering (a popup drops\n  // its listeners the moment it starts closing, 250ms before it leaves the DOM)\n  if(options.middleware) {\n    options.middleware.onDestroy(dispose);\n  } else {\n    options.listenerSetter?.addCleanup(dispose);\n  }\n\n  if(options.withCheckboxSubtitle && checkboxField && !isToggle) {\n    const [enabledKey, disabledKey] = options.checkboxKeys || ['Checkbox.Enabled', 'Checkbox.Disabled'];\n    const onChange = () => {\n      replaceContent(controller.ensureSubtitle(), i18n(checkboxField.checked ? enabledKey : disabledKey));\n    };\n\n    if(options.listenerSetter) options.listenerSetter.add(checkboxField.input)('change', onChange);\n    else checkboxField.input.addEventListener('change', onChange);\n  }\n\n  return controller;\n};\n\nconst ROW_CONTROLLER = Symbol.for('tweb.row-controller');\nconst prototypesWithRowController = new WeakSet<object>();\n\nconst installRowControllerDescriptors = (target: object, controller: RowTsxController) => {\n  const prototype = Object.getPrototypeOf(target);\n  const descriptorTarget = prototype && prototype !== Object.prototype ? prototype : target;\n  if(prototypesWithRowController.has(descriptorTarget)) {\n    return;\n  }\n\n  const descriptors: PropertyDescriptorMap = {};\n  for(const key of Reflect.ownKeys(controller)) {\n    const source = Object.getOwnPropertyDescriptor(controller, key);\n    const writable = source.set || ('writable' in source && source.writable);\n    descriptors[key as any] = {\n      configurable: true,\n      get(this: object) {\n        return (this as any)[ROW_CONTROLLER][key];\n      },\n      set: writable ? function(this: object, value: unknown) {\n        (this as any)[ROW_CONTROLLER][key] = value;\n      } : undefined\n    };\n  }\n\n  Object.defineProperties(descriptorTarget, descriptors);\n  prototypesWithRowController.add(descriptorTarget);\n};\n\nexport const attachRowController = <T extends object>(\n  target: T,\n  options: RowTsxOptions = {}\n): T & RowTsxController => {\n  const controller = mountRowController(options);\n  Object.defineProperty(target, ROW_CONTROLLER, {value: controller});\n  installRowControllerDescriptors(target, controller);\n  return target as T & RowTsxController;\n};\n","import {JSX, createSignal, For, createEffect, Accessor, onMount, createMemo, splitProps, on, Show, onCleanup} from 'solid-js';\nimport Scrollable from '@components/scrollable2';\nimport {createStoriesViewer} from '@components/stories/viewer';\nimport styles from '@components/stories/list.module.scss';\nimport mediaSizes from '@helpers/mediaSizes';\nimport rootScope from '@lib/rootScope';\nimport {fastSmoothScrollToStart} from '@helpers/fastSmoothScroll';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport {AvatarNew} from '@components/avatarNew';\nimport I18n, {i18n} from '@lib/langPack';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {StoriesProvider, useStories} from '@components/stories/store';\nimport appImManager from '@lib/appImManager';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {AppMyStoriesTab} from '@components/solidJsTabs/tabs';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {ChatType} from '@components/chat/chatType';\nimport {subscribeOn} from '@helpers/solid/subscribeOn';\nimport {useCollapsable} from '@hooks/useCollapsable';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport showStoriesStealthModePopup from '@components/popups/storiesStealthMode';\n\nconst TEST_COUNT = 0;\nconst ITEM_MARGIN = 0;\nconst ITEM_WIDTH = 74 + ITEM_MARGIN * 2;\nconst ITEM_AVATAR_SIZE = 54;\nconst STACKED_LENGTH = 3;\nconst SMALL_SIDEBAR_WIDTH = 348;\n\nfunction _StoriesList(props: {\n  foldInto: HTMLElement,\n  setScrolledOn: HTMLElement,\n  getScrollable: () => HTMLElement,\n  listenWheelOn: HTMLElement,\n  archive?: boolean,\n  offsetX?: number,\n  resizeCallback?: (callback: () => void) => void,\n  onExpand?: () => void\n}) {\n  type PeerStories = typeof stories['peers'][0];\n  const [stories, actions] = useStories();\n  const [viewerPeer, setViewerPeer] = createSignal<PeerStories>();\n  const [containerRect, setContainerRect] = createSignal<DOMRect>();\n  const [hasTransition, setHasTransition] = createSignal(true); // to make it smooth when resizing the left sidebar\n\n  const maxStackedItems = createMemo(() =>\n    containerRect()?.width > SMALL_SIDEBAR_WIDTH ? STACKED_LENGTH : 1\n  );\n\n  const peers = createMemo(() => {\n    const peers = stories.peers;\n    if(TEST_COUNT) {\n      return peers.slice(0, TEST_COUNT);\n    }\n    return peers;\n  });\n\n  let toRect: DOMRect, fromRect: DOMRect;\n  const myIndex = createMemo(() => peers().findIndex((peer) => peer.peerId === rootScope.myId));\n  const spaceEvenly = createMemo(() => {\n    const rect = containerRect();\n    if(rect && rect.width > (peers().length * ITEM_WIDTH)) {\n      return (rect.width - (peers().length * ITEM_WIDTH)) / (peers().length + 1);\n    }\n\n    return 0;\n  });\n  const items = new WeakMap<PeerStories, HTMLDivElement>();\n  const itemsTarget = new WeakMap<HTMLDivElement, PeerStories>();\n\n  const onContainerClick = (e: MouseEvent) => {\n    unfold(e);\n    props.onExpand?.();\n  };\n\n  createEffect(() => {\n    const peer = viewerPeer();\n    if(!peer) {\n      return;\n    }\n\n    const onExit = () => {\n      setViewerPeer(undefined);\n    };\n\n    const target = createMemo(() => {\n      const item = items.get(stories.peer);\n      return item?.querySelector('.avatar');\n    });\n\n    createStoriesViewer({onExit, target});\n  });\n\n  const onItemClick = (peer: PeerStories, e?: MouseEvent) => {\n    if(progress() !== STATE_UNFOLDED && e) {\n      return onContainerClick(e);\n    }\n\n    actions.resetIndexes();\n    actions.set({peer});\n    setViewerPeer(peer);\n  };\n\n  const foldedLength = createMemo(() => Math.min(maxStackedItems(), peers().length - (myIndex() !== -1 ? 1 : 0)));\n  const indexes = createMemo(() => {\n    return {\n      min: myIndex() === 0 && peers().length > 1 ? 1 : 0,\n      max: myIndex() === 0 ? foldedLength() : foldedLength() - 1\n    };\n  });\n\n  const isItemOut = (index: number, _indexes: ReturnType<typeof indexes> = indexes()) => {\n    const {min: minIndex, max: maxIndex} = _indexes;\n    return index < minIndex || index > maxIndex;\n  };\n\n  const Item = (peer: PeerStories, idx: Accessor<number>) => {\n    const onClick = onItemClick.bind(null, peer);\n\n    const calculateMovement = createMemo(() => {\n      const rect = containerRect();\n      const value = progress();\n      const index = idx();\n      const marginEvenly = spaceEvenly();\n      const containerPadding = marginEvenly ? 0 : CONTAINER_PADDING;\n\n      const _indexes = indexes();\n      const isOut = isItemOut(index, _indexes);\n      const fromLeft = fromRect.left + containerPadding;\n      const left = fromLeft + index * ITEM_WIDTH + marginEvenly * (index + 1);\n      const realLeft = rect.left + containerPadding + index * ITEM_WIDTH + marginEvenly * (index + 1);\n      if(realLeft > rect.right) {\n        return;\n      }\n\n      const cssProperties: JSX.CSSProperties = {};\n      if(isOut) {\n        cssProperties['z-index'] = 100 - index;\n      } else {\n        cssProperties['z-index'] = 100 + foldedLength() + 1 - index;\n      }\n\n      // if(myIndex() === 0 && index !== 0) {\n      //   index -= 1;\n      // }\n\n      const desiredX = toRect.right + (props.offsetX || 0);\n      const indexOffsetX = isOut ? 0 : (_indexes.max - index) * 16;\n      let distanceX = desiredX - left + 5 - indexOffsetX;\n\n      let _scale: number;\n      if(isOut) {\n        cssProperties['transform-origin'] = 'center 43.75%';\n        distanceX += 8 * (index < _indexes.min ? 1 : -1);\n        _scale = 0.2;\n      } else {\n        _scale = 26.67 / 48;\n      }\n\n      const translateX = distanceX * value;\n      const translate = `translateX(calc(var(--stories-additional-offset, 0px) * ${value} + ${translateX * (I18n.getIsRTL() ? -1 : 1)}px))`;\n      const scaleValue = 1 - (value * (1 - _scale));\n      const scale = `scale(${scaleValue})`;\n      cssProperties.transform = `${translate} ${scale}`;\n      return {\n        isOut,\n        isLastIn: !isOut && index === _indexes.max,\n        cssProperties\n      };\n    });\n\n    const avatar = AvatarNew({\n      peerId: peer.peerId,\n      size: ITEM_AVATAR_SIZE,\n      props: {\n        onClick\n      },\n      isDialog: false,\n      withStories: true,\n      isStoryFolded: shouldStoriesSegmentsBeFolded\n    });\n\n    const isMyStory = peer.peerId === rootScope.myId;\n\n    const ret = (\n      <div\n        ref={(el) => (items.set(peer, el), itemsTarget.set(el, peer))}\n        class={styles.ListItem}\n        classList={{\n          [styles.isRead]: !isMyStory && peer.maxReadId && peer.maxReadId >= peer.stories[peer.stories.length - 1].id,\n          [styles.isMasked]: (() => {\n            const movement = calculateMovement();\n            return movement && !movement.isOut && !movement.isLastIn;\n          })()\n        }}\n        onClick={onClick}\n        style={{\n          ...calculateMovement()?.cssProperties,\n          transition: hasTransition() ? undefined : 'none'\n        }}\n      >\n        {avatar.element}\n        <div class={styles.ListItemName}>\n          {isMyStory ? i18n('MyStory') : <PeerTitleTsx peerId={peer.peerId} onlyFirstName />}\n        </div>\n      </div>\n    );\n\n    return (\n      <Show when={/* isTransition() ||  */calculateMovement() || !folded()}>\n        {ret}\n      </Show>\n    );\n  };\n\n  const MOVE_Y = -69, CONTAINER_PADDING = 6, CONTAINER_HEIGHT = 92;\n  let scrolling = false;\n  const calculateMovement = (): JSX.CSSProperties => {\n    const value = progress();\n\n    const scrollableX = !scrolling && getMenuScrollable();\n    if(scrollableX?.scrollLeft) {\n      scrolling = true;\n      fastSmoothScrollToStart(scrollableX, 'x').then(() => {\n        scrolling = false;\n      });\n    }\n\n    const translateY = value * MOVE_Y;\n    const translate = `translateY(${translateY}px)`;\n    props.setScrolledOn.style.setProperty('--stories-scrolled', (value * CONTAINER_HEIGHT) + 'px');\n\n    return {\n      // 'height': `${containerHeight - (containerHeight * value)}px`,\n      'transform': translate,\n      '--progress': value\n      // '--scale': 1 - (value * (1 - 0.625))\n    };\n  };\n\n  // * fold when stories disappear\n  createEffect(\n    on(\n      () => peers().length,\n      (length) => {\n        if(!length) {\n          fold();\n        }\n      },\n      {defer: true}\n    )\n  );\n\n  const getMenuScrollable = () => container.firstElementChild as HTMLElement;\n\n  // * lock horizontal scroll when folded\n  createEffect(() => {\n    if(folded() || isTransition()) {\n      const onWheel = cancelEvent;\n      const scrollableX = getMenuScrollable();\n      subscribeOn(scrollableX)('wheel', onWheel, {capture: true});\n    }\n  });\n\n  createEffect(() => {\n    if(isTransition()) {\n      return;\n    }\n\n    actions.toggleSorting('list', !folded());\n  });\n\n  const onResize = () => {\n    toRect = props.foldInto.getBoundingClientRect();\n    fromRect = props.foldInto.parentElement.getBoundingClientRect();\n    setContainerRect(props.foldInto.parentElement.parentElement.getBoundingClientRect());\n  };\n  subscribeOn(mediaSizes)('resize', onResize);\n  onResize();\n  props.resizeCallback?.(onResize);\n\n  let container: HTMLDivElement;\n\n  onMount(() => {\n    const listenerSetter = new ListenerSetter();\n    let timeoutId: number;\n    listenerSetter.add(rootScope)('resizing_left_sidebar', () => {\n      onResize();\n      window.clearTimeout(timeoutId);\n      setHasTransition(false);\n      timeoutId = self.setTimeout(() => {\n        setHasTransition(true);\n      }, 100);\n    });\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    })\n  });\n\n  const {folded, unfold, fold, isTransition, progress, STATE_UNFOLDED} = useCollapsable({\n    scrollable: props.getScrollable,\n    container: () => container,\n    listenWheelOn: props.listenWheelOn,\n    shouldIgnore: () => !peers().length,\n    disableHoverWhenFolded: true\n  });\n\n  // * declared before `r`: creating it maps `peers()` through `Item` right away, so a list\n  // * that already has its peers (a provider constructed with them) would read this memo\n  // * before initialization\n  const shouldStoriesSegmentsBeFolded = createMemo(() => progress() !== STATE_UNFOLDED);\n\n  const r = (\n    <div\n      ref={container}\n      class={styles.ListContainer}\n      style={calculateMovement()}\n    >\n      <Scrollable axis=\"x\">\n        <div\n          class={styles.List}\n          classList={{\n            [styles['space-evenly']]: !!spaceEvenly()\n          }}\n        >\n          <For each={peers()}>{Item}</For>\n        </div>\n      </Scrollable>\n    </div>\n  );\n\n  onMount(() => {\n    const toggleMute = async(mute: boolean) => {\n      rootScope.managers.appNotificationsManager.toggleStoriesMute(peer.peerId, mute);\n\n      toastNew({\n        langPackKey: mute ? 'NotificationsStoryMutedHint' : 'NotificationsStoryUnmutedHint',\n        langPackArguments: [await wrapPeerTitle({peerId: peer.peerId})]\n      });\n    };\n\n    const toggleHidden = async(hidden: boolean) => {\n      rootScope.managers.appStoriesManager.toggleStoriesHidden(peer.peerId, hidden);\n\n      toastNew({\n        langPackKey: hidden ? 'StoriesMovedToContacts' : 'StoriesMovedToDialogs',\n        langPackArguments: [await wrapPeerTitle({peerId: peer.peerId})]\n      });\n    };\n\n    let peer: PeerStories, isSelf: boolean;\n    createContextMenu({\n      buttons: [{\n        icon: 'stories',\n        text: 'SavedStories',\n        onClick: () => {\n          appSidebarLeft.createTab(AppMyStoriesTab).open(AppMyStoriesTab.getInitArgs());\n        },\n        verify: () => isSelf\n      }, {\n        icon: 'archive',\n        text: 'ArchivedStories',\n        onClick: () => {\n          appSidebarLeft.createTab(AppMyStoriesTab).open({...AppMyStoriesTab.getInitArgs(), isArchive: true});\n        },\n        verify: () => isSelf\n      }, {\n        icon: 'message',\n        text: 'SendMessage',\n        onClick: () => {\n          appImManager.setInnerPeer({\n            peerId: peer.peerId,\n            type: ChatType.Chat\n          });\n        },\n        verify: () => !isSelf && peer.peerId.isUser()\n      }, {\n        icon: 'channel',\n        text: 'OpenChannel2',\n        onClick: () => {\n          appImManager.setInnerPeer({\n            peerId: peer.peerId,\n            type: ChatType.Chat\n          });\n        },\n        verify: () => !peer.peerId.isUser()\n      }, {\n        icon: 'mute',\n        text: 'NotificationsStoryMute2',\n        onClick: () => toggleMute(true),\n        verify: () => !isSelf && rootScope.managers.appNotificationsManager.isPeerStoriesMuted(peer.peerId).then((isMuted) => !isMuted),\n        multiline: true\n      }, {\n        icon: 'unmute',\n        text: 'NotificationsStoryUnmute2',\n        onClick: () => toggleMute(false),\n        verify: () => !isSelf && rootScope.managers.appNotificationsManager.isPeerStoriesMuted(peer.peerId),\n        multiline: true\n      }, {\n        icon: 'eyecross',\n        text: 'Stories.StealthMode.View',\n        onClick: () => {\n          const {peerId} = peer;\n          showStoriesStealthModePopup({\n            onActivate: () => {\n              const peer = peers().find((p) => p.peerId === peerId);\n              if(!peer) {\n                return;\n              }\n\n              onItemClick(peer);\n            }\n          });\n        }\n      }, {\n        icon: 'archive',\n        text: 'ArchivePeerStories',\n        onClick: () => toggleHidden(true),\n        verify: () => !isSelf && !props.archive\n      }, {\n        icon: 'unarchive',\n        text: 'UnarchiveStories',\n        onClick: () => toggleHidden(false),\n        verify: () => !isSelf && !!props.archive\n      }],\n      listenTo: container,\n      middleware: createMiddleware().get(),\n      findElement: (e) => {\n        return !folded() && findUpClassName(e.target, styles.ListItem);\n      },\n      onOpen: (e, target) => {\n        peer = itemsTarget.get(target as HTMLDivElement);\n        isSelf = peer.peerId === rootScope.myId;\n      },\n      onClose: () => {\n        peer = undefined;\n      }\n    });\n  });\n\n  return (\n    <>\n      {stories.ready && r}\n    </>\n  );\n}\n\nexport default function StoriesList(props: Parameters<typeof StoriesProvider>[0] & Parameters<typeof _StoriesList>[0]) {\n  const [, rest] = splitProps(props, ['foldInto', 'getScrollable', 'listenWheelOn', 'setScrolledOn', 'offsetX', 'resizeCallback']);\n  // return <_StoriesList />;\n  return (\n    <StoriesProvider {...rest}>\n      <_StoriesList {...props} />\n    </StoriesProvider>\n  );\n}\n","import type {AppManagers} from '@lib/managers';\nimport type {AppChatFoldersTab} from '@components/solidJsTabs/tabs';\nimport type {AppEditFolderTab} from '@components/solidJsTabs/tabs';\nimport type {AppSidebarLeft} from '@components/sidebarLeft';\nimport {FOLDER_ID_ALL, REAL_FOLDERS} from '@appManagers/constants';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpClassName from '@helpers/dom/findUpClassName';\n\nexport default function createFolderContextMenu({\n  appSidebarLeft,\n  AppChatFoldersTab: _AppChatFoldersTab,\n  AppEditFolderTab: _AppEditFolderTab,\n  managers,\n  className,\n  listenTo\n}: {\n  appSidebarLeft: AppSidebarLeft,\n  AppChatFoldersTab: typeof AppChatFoldersTab,\n  AppEditFolderTab: typeof AppEditFolderTab,\n  managers: AppManagers,\n  className: string,\n  listenTo: HTMLElement\n}) {\n  async function openSettingsForFilter(filterId: number) {\n    if(REAL_FOLDERS.has(filterId)) return;\n    const filter = await managers.filtersStorage.getFilter(filterId);\n\n    appSidebarLeft.closeTabsBefore(() => {\n      appSidebarLeft.createTab(_AppEditFolderTab).open({..._AppEditFolderTab.getInitArgs(), initFilter: filter});\n    });\n  }\n\n  let clickFilterId: number;\n  const {destroy} = createContextMenu({\n    buttons: [{\n      icon: 'edit',\n      text: 'FilterEdit',\n      onClick: () => {\n        openSettingsForFilter(clickFilterId);\n      },\n      verify: () => clickFilterId !== FOLDER_ID_ALL\n    }, {\n      icon: 'edit',\n      text: 'FilterEditAll',\n      onClick: () => {\n        appSidebarLeft.closeTabsBefore(() => {\n          appSidebarLeft.createTab(_AppChatFoldersTab).open(_AppChatFoldersTab.getInitArgs());\n        });\n      },\n      verify: () => clickFilterId === FOLDER_ID_ALL\n    }, {\n      icon: 'readchats',\n      text: 'MarkAllAsRead',\n      onClick: () => {\n        managers.dialogsStorage.markFolderAsRead(clickFilterId);\n      },\n      verify: async() => !!(await managers.dialogsStorage.getFolderUnreadCount(clickFilterId)).unreadCount\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Delete',\n      onClick: () => {\n        _AppEditFolderTab.deleteFolder(clickFilterId);\n      },\n      verify: () => clickFilterId !== FOLDER_ID_ALL\n    }],\n    listenTo,\n    findElement: (e) => findUpClassName(e.target, className),\n    onOpen: (e, target) => {\n      clickFilterId = +target.dataset.filterId;\n    }\n  });\n\n  return {destroy, openSettingsForFilter};\n}\n","import Button from '@components/buttonTsx';\nimport RippleElement from '@components/rippleElement';\nimport Row from '@components/rowTsx';\nimport styles from '@components/sidebarLeft/pendingSuggestion.module.scss';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport classNames from '@helpers/string/classNames';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {useIsSidebarCollapsed} from '@stores/foldersSidebar';\nimport {JSX, Show} from 'solid-js';\n\nexport const PendingSuggestion = (props: Parameters<typeof Row>[0] & {closable?: () => void}) => {\n  return (\n    <Row\n      {...props}\n      class={classNames(styles.suggestion, props.class)}\n    >\n      {props.children}\n      {props.closable && (\n        <Button.Icon\n          icon=\"close\"\n          class={styles.close}\n          onClick={(e) => {\n            cancelEvent(e);\n            props.closable();\n          }}\n        />\n      )}\n    </Row>\n  );\n};\n\nPendingSuggestion.Title = (props: Parameters<typeof Row.Title>[0]) => {\n  return (\n    <Row.Title {...props}>\n      <span class={classNames('text-bold', styles.suggestionTitle)}>{props.children}</span>\n    </Row.Title>\n  );\n};\n\nPendingSuggestion.Subtitle = (props: Parameters<typeof Row.Subtitle>[0]) => {\n  return (\n    <Row.Subtitle {...props}>\n      <span class={styles.suggestionSubtitle}>{props.children}</span>\n    </Row.Subtitle>\n  );\n};\n\nexport function SimpleSuggestion(props: {\n  emoji: string | (() => DocumentFragment),\n  title: JSX.Element,\n  subtitle: JSX.Element,\n  danger?: boolean,\n  onClick: () => void,\n  onClose?: () => void\n}) {\n  const [isSidebarCollapsed] = useIsSidebarCollapsed();\n  const emoji = typeof(props.emoji) === 'string' ? () => wrapEmojiText(props.emoji as string) : props.emoji;\n\n  return (\n    <Show\n      when={isSidebarCollapsed()}\n      fallback={\n        <PendingSuggestion\n          class={props.danger ? styles.danger : styles.secondary}\n          clickable={props.onClick}\n          closable={props.onClose}\n          color={props.danger ? 'danger' : undefined}\n        >\n          <PendingSuggestion.Title>{props.title}</PendingSuggestion.Title>\n          <PendingSuggestion.Subtitle>{props.subtitle}</PendingSuggestion.Subtitle>\n        </PendingSuggestion>\n      }\n    >\n      <RippleElement\n        component=\"div\"\n        class={classNames(styles.collapsed, props.danger ? 'hover-danger-effect' : 'hover-effect')}\n        onClick={props.onClick}\n      >\n        {documentFragmentToNodes(emoji())}\n      </RippleElement>\n    </Show>\n  );\n}\n","import {createMemo, createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport {MyPromoData} from '@appManagers/appPromoManager';\nimport {createStore, reconcile} from 'solid-js/store';\n\nconst [promoData, setPromoData] = createStore<MyPromoData>({\n  pendingSuggestions: [],\n  dismissedSuggestions: []\n});\nconst [promoDataLoaded, setPromoDataLoaded] = createRoot(() => createSignal(false));\n\nlet _loaded = false;\nfunction loadPromoData() {\n  if(!_loaded) {\n    _loaded = true;\n    rootScope.addEventListener('promo_data_update', (data) => {\n      setPromoData(reconcile(data));\n      setPromoDataLoaded(true);\n    });\n\n    rootScope.managers.appPromoManager.getPromoData().then((data) => {\n      setPromoData(reconcile(data));\n      setPromoDataLoaded(true);\n    }).catch(() => {});\n  }\n}\n\nexport function usePendingSuggestions() {\n  loadPromoData();\n\n  return createMemo(() => new Set(promoData.pendingSuggestions));\n}\n\nexport function useDismissedSuggestions() {\n  loadPromoData();\n\n  return createMemo(() => new Set(promoData.dismissedSuggestions));\n}\n\nexport function usePromoDataLoaded() {\n  loadPromoData();\n\n  return promoDataLoaded;\n}\n","import type {ContactBirthdaysState} from '@appManagers/appPromoManager';\nimport PopupElement from '@components/popups';\nimport showBirthdayPopup, {saveMyBirthday} from '@components/popups/birthday';\nimport showSendGiftPicker from '@components/popups/sendGiftPicker';\nimport PopupSendGift from '@components/popups/sendGift';\nimport RippleElement from '@components/rippleElement';\nimport Row from '@components/rowTsx';\nimport birthdayStyles from '@components/sidebarLeft/birthdaySuggestions.module.scss';\nimport type {PendingSuggestionController} from '@components/sidebarLeft/pendingSuggestionController';\nimport {PendingSuggestion, SimpleSuggestion} from '@components/sidebarLeft/pendingSuggestionItem';\nimport suggestionStyles from '@components/sidebarLeft/pendingSuggestion.module.scss';\nimport {StackedAvatarsTsx} from '@components/stackedAvatars';\nimport {toastNew} from '@components/toast';\nimport getPeerTitle from '@components/wrappers/getPeerTitle';\nimport {IS_PREVIEW} from '@config/debug';\nimport classNames from '@helpers/string/classNames';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport {useAppState} from '@stores/appState';\nimport {useIsSidebarCollapsed} from '@stores/foldersSidebar';\nimport {useDismissedSuggestions, usePendingSuggestions, usePromoDataLoaded} from '@stores/promo';\nimport {createEffect, createMemo, createResource, createSignal, onCleanup, onMount, Show} from 'solid-js';\n\nconst BIRTHDAY_CONTACTS_TODAY_SUGGESTION_KEY = 'BIRTHDAY_CONTACTS_TODAY';\nconst BIRTHDAY_SETUP_SUGGESTION_KEY = 'BIRTHDAY_SETUP';\n\n// Preview-only: 1 opens the gift popup directly, 2+ opens the recipient picker.\n// Leave peer ids empty to use real contacts from the current preview account.\nconst TEST_BIRTHDAY_CONTACTS = IS_PREVIEW && true;\nconst TEST_BIRTHDAY_CONTACTS_TODAY_COUNT = 1;\nconst TEST_BIRTHDAY_CONTACTS_INCLUDE_NEARBY = true;\nconst TEST_BIRTHDAY_CONTACT_PEER_IDS: PeerId[] = [];\n\nconst EMPTY_CONTACT_BIRTHDAYS: ContactBirthdaysState = {\n  contacts: [],\n  yesterday: [],\n  today: [],\n  tomorrow: []\n};\n\nfunction getTestBirthdayContact(peerId: PeerId, dayOffset: number) {\n  const date = new Date();\n  date.setDate(date.getDate() + dayOffset);\n\n  return {\n    peerId,\n    birthday: {\n      _: 'birthday' as const,\n      day: date.getDate(),\n      month: date.getMonth() + 1\n    }\n  };\n}\n\nasync function getTestContactBirthdays(state: ContactBirthdaysState): Promise<ContactBirthdaysState> {\n  const nearbyCount = TEST_BIRTHDAY_CONTACTS_INCLUDE_NEARBY ? 2 : 0;\n  const requiredCount = TEST_BIRTHDAY_CONTACTS_TODAY_COUNT + nearbyCount;\n  const peerIds = [...new Set(TEST_BIRTHDAY_CONTACT_PEER_IDS)];\n\n  if(peerIds.length < requiredCount) {\n    const contactPeerIds = await rootScope.managers.appUsersManager.getContactsPeerIds(\n      '',\n      false,\n      'none',\n      Math.max(requiredCount * 4, 20)\n    );\n    const candidates = [...new Set([\n      ...state.contacts.map(({peerId}) => peerId),\n      ...contactPeerIds\n    ])].slice(0, Math.max(requiredCount * 4, 20));\n    const areRegularUsers = await Promise.all(candidates.map((peerId) => (\n      rootScope.managers.appPeersManager.isRegularUser(peerId)\n    )));\n\n    for(let i = 0; i < candidates.length && peerIds.length < requiredCount; ++i) {\n      const peerId = candidates[i];\n      if(areRegularUsers[i] && !peerIds.includes(peerId)) peerIds.push(peerId);\n    }\n  }\n\n  const today = peerIds\n  .slice(0, TEST_BIRTHDAY_CONTACTS_TODAY_COUNT)\n  .map((peerId) => getTestBirthdayContact(peerId, 0));\n  const yesterday = TEST_BIRTHDAY_CONTACTS_INCLUDE_NEARBY && peerIds[TEST_BIRTHDAY_CONTACTS_TODAY_COUNT] ?\n    [getTestBirthdayContact(peerIds[TEST_BIRTHDAY_CONTACTS_TODAY_COUNT], -1)] : [];\n  const tomorrowPeerId = peerIds[TEST_BIRTHDAY_CONTACTS_TODAY_COUNT + 1];\n  const tomorrow = TEST_BIRTHDAY_CONTACTS_INCLUDE_NEARBY && tomorrowPeerId ?\n    [getTestBirthdayContact(tomorrowPeerId, 1)] : [];\n\n  return {\n    contacts: [...today, ...yesterday, ...tomorrow],\n    yesterday,\n    today,\n    tomorrow\n  };\n}\n\nfunction BirthdaySetupSuggestion() {\n  const emoji = () => wrapEmojiText('🎂');\n\n  const onDismissed = () => {\n    rootScope.managers.appPromoManager.dismissSuggestion(BIRTHDAY_SETUP_SUGGESTION_KEY);\n  };\n\n  const onClick = () => {\n    showBirthdayPopup({\n      onSave: async(date) => {\n        if(await saveMyBirthday(date)) {\n          rootScope.managers.appPromoManager.dismissSuggestion(BIRTHDAY_SETUP_SUGGESTION_KEY);\n          return;\n        }\n        return false;\n      }\n    });\n  };\n\n  return (\n    <SimpleSuggestion\n      emoji={emoji}\n      title={i18n('Suggestion.BirthdaySetup', [emoji()])}\n      subtitle={i18n('Suggestion.BirthdaySetup.Subtitle')}\n      onClick={onClick}\n      onClose={onDismissed}\n    />\n  );\n}\n\nfunction BirthdayContactsSuggestion(props: {\n  state: ContactBirthdaysState,\n  onDismiss: () => void\n}) {\n  const [isSidebarCollapsed] = useIsSidebarCollapsed();\n  const contacts = () => props.state.today;\n  const peerIds = createMemo(() => contacts().slice(0, 3).map(({peerId}) => peerId));\n  const multipleAvatarSize = () => peerIds().length === 3 ? 26 : 30;\n  const [firstName] = createResource(\n    () => contacts().length === 1 ? contacts()[0]?.peerId : undefined,\n    (peerId) => getPeerTitle({peerId, plainText: true, onlyFirstName: true, useManagers: true})\n  );\n\n  const nearbyContacts = createMemo(() => [\n    ...props.state.today,\n    ...props.state.yesterday,\n    ...props.state.tomorrow\n  ]);\n  const birthdayPeerIds = createMemo(() => new Set(nearbyContacts().map(({peerId}) => peerId)));\n  const yesterdayPeerIds = createMemo(() => new Set(props.state.yesterday.map(({peerId}) => peerId)));\n  const todayPeerIds = createMemo(() => new Set(props.state.today.map(({peerId}) => peerId)));\n\n  const openGift = (peerId: PeerId) => {\n    PopupElement.createPopup(PopupSendGift, {peerId, birthday: birthdayPeerIds().has(peerId)});\n  };\n\n  const onClick = () => {\n    if(contacts().length === 1) {\n      openGift(contacts()[0].peerId);\n      return;\n    }\n\n    showSendGiftPicker({\n      prependPeerIds: nearbyContacts().map(({peerId}) => peerId),\n      getSubtitleForElement: (peerId) => {\n        const key = todayPeerIds().has(peerId) ? 'Suggestion.BirthdayContacts.Today' :\n          yesterdayPeerIds().has(peerId) ? 'Suggestion.BirthdayContacts.Yesterday' :\n          birthdayPeerIds().has(peerId) ? 'Suggestion.BirthdayContacts.Tomorrow' : undefined;\n        return key ? i18n(key) : undefined;\n      },\n      onSelect: ([{peerId}]) => openGift(peerId)\n    });\n  };\n\n  return (\n    <Show\n      when={isSidebarCollapsed()}\n      fallback={\n        <PendingSuggestion\n          class={suggestionStyles.secondary}\n          clickable={onClick}\n          closable={props.onDismiss}\n        >\n          <PendingSuggestion.Title>\n            {contacts().length === 1 ? (\n              <Show when={firstName()}>{(name) => i18n('Suggestion.BirthdayContacts.Single', [name()])}</Show>\n            ) : i18n('Suggestion.BirthdayContacts.Multiple', [contacts().length])}\n          </PendingSuggestion.Title>\n          <PendingSuggestion.Subtitle>{i18n('Suggestion.BirthdayContacts.Subtitle')}</PendingSuggestion.Subtitle>\n          <Row.Media size=\"abitbigger\" class={birthdayStyles.media}>\n            <div class={birthdayStyles.avatars}>\n              <StackedAvatarsTsx\n                peerIds={peerIds()}\n                avatarSize={contacts().length === 1 ? 36 : multipleAvatarSize()}\n              />\n            </div>\n          </Row.Media>\n        </PendingSuggestion>\n      }\n    >\n      <RippleElement\n        component=\"div\"\n        class={classNames(suggestionStyles.collapsed, birthdayStyles.collapsed, 'hover-effect')}\n        onClick={onClick}\n      >\n        <div class={birthdayStyles.avatars}>\n          <StackedAvatarsTsx\n            peerIds={peerIds()}\n            avatarSize={contacts().length === 1 ? 32 : multipleAvatarSize()}\n          />\n        </div>\n      </RippleElement>\n    </Show>\n  );\n}\n\nexport default function createBirthdaySuggestions() {\n  const [{appConfig}] = useAppState();\n  const pendingSuggestions = usePendingSuggestions();\n  const dismissedSuggestions = useDismissedSuggestions();\n  const promoDataLoaded = usePromoDataLoaded();\n  const [contactBirthdays, setContactBirthdays] = createSignal<ContactBirthdaysState>();\n  let contactBirthdaysRequest = 0;\n  let midnightTimeout: number;\n  let destroyed = false;\n\n  const canLoadBirthdayContacts = () => TEST_BIRTHDAY_CONTACTS || !appConfig.premium_purchase_blocked;\n  const canShowBirthdayContacts = () => (\n    TEST_BIRTHDAY_CONTACTS || (\n      canLoadBirthdayContacts() &&\n      promoDataLoaded() &&\n      !dismissedSuggestions().has(BIRTHDAY_CONTACTS_TODAY_SUGGESTION_KEY)\n    )\n  );\n\n  const loadContactBirthdays = async(force = false) => {\n    const request = ++contactBirthdaysRequest;\n\n    try {\n      const liveState = await rootScope.managers.appPromoManager.getContactBirthdays(force)\n      .catch(() => EMPTY_CONTACT_BIRTHDAYS);\n      const state = TEST_BIRTHDAY_CONTACTS ? await getTestContactBirthdays(liveState) : liveState;\n      if(!destroyed && request === contactBirthdaysRequest) {\n        setContactBirthdays(state);\n      }\n    } catch(err) {\n      if(!destroyed && request === contactBirthdaysRequest) {\n        setContactBirthdays(EMPTY_CONTACT_BIRTHDAYS);\n      }\n    }\n  };\n\n  const scheduleMidnightRefresh = () => {\n    const now = new Date();\n    const nextMidnight = new Date(now);\n    nextMidnight.setHours(24, 0, 0, 0);\n\n    midnightTimeout = window.setTimeout(() => {\n      setContactBirthdays(undefined);\n      scheduleMidnightRefresh();\n      void Promise.all([\n        rootScope.managers.appPromoManager.getPromoData(true).catch(() => {}),\n        loadContactBirthdays(true)\n      ]);\n    }, nextMidnight.getTime() - now.getTime());\n  };\n\n  onMount(scheduleMidnightRefresh);\n  onCleanup(() => {\n    destroyed = true;\n    ++contactBirthdaysRequest;\n    window.clearTimeout(midnightTimeout);\n  });\n\n  createEffect(() => {\n    if(!canLoadBirthdayContacts()) {\n      ++contactBirthdaysRequest;\n      setContactBirthdays(undefined);\n      return;\n    }\n\n    void loadContactBirthdays();\n  });\n\n  createEffect(() => {\n    if(canShowBirthdayContacts() && contactBirthdays()?.today.length) {\n      void rootScope.managers.appGiftsManager.getStarGiftOptions().catch(() => {});\n    }\n  });\n\n  const dismissBirthdayContacts = () => {\n    ++contactBirthdaysRequest;\n    setContactBirthdays(undefined);\n    if(!TEST_BIRTHDAY_CONTACTS) {\n      rootScope.managers.appPromoManager.dismissSuggestion(BIRTHDAY_CONTACTS_TODAY_SUGGESTION_KEY);\n    }\n    toastNew({langPackKey: 'Suggestion.BirthdayContacts.Dismissed'});\n  };\n\n  const ContactsSuggestion = () => (\n    <Show when={contactBirthdays()}>\n      {(state) => <BirthdayContactsSuggestion state={state()} onDismiss={dismissBirthdayContacts} />}\n    </Show>\n  );\n\n  const contacts: PendingSuggestionController = {\n    available: () => canShowBirthdayContacts() && !!contactBirthdays()?.today.length,\n    component: ContactsSuggestion\n  };\n  const setup: PendingSuggestionController = {\n    available: () => pendingSuggestions().has(BIRTHDAY_SETUP_SUGGESTION_KEY),\n    component: BirthdaySetupSuggestion\n  };\n\n  return {\n    contacts,\n    setup\n  };\n}\n","import {showEmailSetupPopup} from '@components/popups/emailSetup';\nimport {toastNew} from '@components/toast';\nimport rootScope from '@lib/rootScope';\nimport {usePendingSuggestions} from '@stores/promo';\nimport {createEffect} from 'solid-js';\n\nconst EMAIL_SETUP_KEY = 'SETUP_LOGIN_EMAIL';\nconst EMAIL_SETUP_KEY_NOSKIP = 'SETUP_LOGIN_EMAIL_NOSKIP';\n\nexport default function createEmailSetupSuggestion() {\n  const pendingSuggestions = usePendingSuggestions();\n\n  createEffect(() => {\n    const pendingSuggestions$ = pendingSuggestions();\n    if(!pendingSuggestions$.has(EMAIL_SETUP_KEY) && !pendingSuggestions$.has(EMAIL_SETUP_KEY_NOSKIP)) {\n      return;\n    }\n\n    Promise.all([\n      rootScope.managers.appPromoManager.getPromoData(true),\n      rootScope.managers.passwordManager.getState()\n    ]).then(([data, passwordState]) => {\n      if(passwordState.login_email_pattern && !passwordState.email_unconfirmed_pattern) {\n        return;\n      }\n\n      const noskip = data.pendingSuggestions.includes(EMAIL_SETUP_KEY_NOSKIP);\n      if(data.pendingSuggestions.includes(EMAIL_SETUP_KEY) || noskip) {\n        showEmailSetupPopup({\n          noskip,\n          purpose: {_: 'emailVerifyPurposeLoginChange'},\n          onDismiss: () => {\n            if(!noskip) {\n              rootScope.managers.appPromoManager.dismissSuggestion(EMAIL_SETUP_KEY);\n            }\n          },\n          onSuccess: () => {\n            toastNew({langPackKey: 'EmailSetup.SetupToast'});\n          }\n        });\n      }\n    });\n  });\n}\n","import showFrozenPopup from '@components/popups/frozen';\nimport type {PendingSuggestionController} from '@components/sidebarLeft/pendingSuggestionController';\nimport {SimpleSuggestion} from '@components/sidebarLeft/pendingSuggestionItem';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {useAppState} from '@stores/appState';\n\nfunction FrozenSuggestion() {\n  const emoji = () => wrapEmojiText('🚫');\n  const onClick = () => showFrozenPopup();\n\n  return (\n    <SimpleSuggestion\n      emoji={emoji}\n      title={i18n('Suggestion.Frozen.Title', [emoji()])}\n      subtitle={i18n('Suggestion.Frozen.Subtitle')}\n      onClick={onClick}\n    />\n  );\n}\n\nexport default function createFrozenSuggestion(): PendingSuggestionController {\n  const [{appConfig}] = useAppState();\n\n  return {\n    available: () => !!appConfig.freeze_since_date,\n    component: FrozenSuggestion\n  };\n}\n","const IS_NOTIFICATION_SUPPORTED = typeof Notification !== 'undefined' &&\n  typeof Notification.requestPermission === 'function';\n\nexport default IS_NOTIFICATION_SUPPORTED;\n","import type {PendingSuggestionController} from '@components/sidebarLeft/pendingSuggestionController';\nimport {SimpleSuggestion} from '@components/sidebarLeft/pendingSuggestionItem';\nimport {toastNew} from '@components/toast';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport uiNotificationsManager from '@lib/uiNotificationsManager';\nimport {useAppSettings} from '@stores/appSettings';\nimport IS_NOTIFICATION_SUPPORTED from '@environment/notificationSupport';\n\nfunction NotificationsSuggestion() {\n  const [, setAppSettings] = useAppSettings();\n  const emoji = () => wrapEmojiText('🔔');\n\n  const onDismissed = () => {\n    setAppSettings('notifications', 'suggested', true);\n    toastNew({langPackKey: 'Suggestion.Notifications.Dismissed'});\n  };\n\n  const onClick = () => {\n    if(!IS_NOTIFICATION_SUPPORTED) {\n      onDismissed();\n      return;\n    }\n\n    Notification.requestPermission().then((permission) => {\n      if(permission === 'granted') {\n        setAppSettings('notifications', 'suggested', true);\n        uiNotificationsManager.onPushConditionsChange();\n      } else if(permission === 'denied') {\n        throw 1;\n      }\n    }).catch(onDismissed);\n  };\n\n  return (\n    <SimpleSuggestion\n      emoji={emoji}\n      title={i18n('Suggestion.Notifications', [emoji()])}\n      subtitle={i18n('Suggestion.Notifications.Subtitle')}\n      onClick={onClick}\n      onClose={onDismissed}\n    />\n  );\n}\n\nexport default function createNotificationsSuggestion(): PendingSuggestionController {\n  const [appSettings] = useAppSettings();\n\n  return {\n    available: () => IS_NOTIFICATION_SUPPORTED &&\n      !appSettings.notifications.suggested &&\n      Notification.permission !== 'granted',\n    component: NotificationsSuggestion\n  };\n}\n","import IS_WEB_AUTHN_SUPPORTED from '@environment/webAuthn';\nimport {Passkey} from '@layer';\nimport {getInputPasskeyCredential} from '@appManagers/utils/account/getInputPasskeyResponse';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {toastNew} from '@components/toast';\nimport showFeatureDetailsPopup from '@components/popups/featureDetails';\n\nexport async function createPasskey() {\n  const registrationOptions = await rootScope.managers.appAccountManager.initPasskeyRegistration();\n  const publicKeyCredentialCreationOptions = PublicKeyCredential.parseCreationOptionsFromJSON(JSON.parse(registrationOptions.options.data).publicKey);\n\n  // if(IS_BETA) {\n  //   console.log(publicKeyCredentialCreationOptions);\n  //   publicKeyCredentialCreationOptions.rp = {\n  //     id: 'localhost',\n  //     name: 'Telegram Messenger'\n  //   };\n  // }\n\n  try {\n    const credential = await navigator.credentials.create({publicKey: publicKeyCredentialCreationOptions});\n    const passkey = await rootScope.managers.appAccountManager.registerPasskey(getInputPasskeyCredential(credential as PublicKeyCredential));\n    toastNew({langPackKey: 'Passkey.Created'});\n    return passkey;\n  } catch(err) {\n    console.error('passkey error', err);\n    toastNew({langPackKey: 'Passkey.CreationError'});\n    throw err;\n  }\n}\n\nexport default function showPasskeyPopup(onCreation?: (passkey: Passkey) => void) {\n  showFeatureDetailsPopup({\n    rows: [\n      {icon: 'key_filled', title: i18n('Passkey.Row1.Title'), subtitle: i18n('Passkey.Row1.Subtitle')},\n      {icon: 'faceid', title: i18n('Passkey.Row2.Title'), subtitle: i18n('Passkey.Row2.Subtitle')},\n      {icon: 'lock', title: i18n('Passkey.Row3.Title'), subtitle: i18n('Passkey.Row3.Subtitle')}\n    ],\n    sticker: {\n      name: 'key',\n      size: 120\n    },\n    title: i18n('Passkey.Title'),\n    subtitle: i18n('Passkey.Subtitle'),\n    buttons: IS_WEB_AUTHN_SUPPORTED ? [{\n      text: i18n('Passkey.Create'),\n      onClick: async(close) => {\n        try {\n          const passkey = await createPasskey();\n          close();\n          onCreation?.(passkey);\n        } catch(err) {\n          return false;\n        }\n      }\n    }, {\n      text: i18n('Passkey.Skip'),\n      onClick: () => {},\n      isCancel: true,\n      isSecondary: true\n    }] : [{\n      text: i18n('Passkey.Unsupported'),\n      isCancel: true\n    }]\n  });\n}\n","import showPasskeyPopup from '@components/popups/passkey';\nimport type {PendingSuggestionController} from '@components/sidebarLeft/pendingSuggestionController';\nimport {SimpleSuggestion} from '@components/sidebarLeft/pendingSuggestionItem';\nimport IS_WEB_AUTHN_SUPPORTED from '@environment/webAuthn';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport rootScope from '@lib/rootScope';\nimport {usePendingSuggestions} from '@stores/promo';\n\nconst PASSKEY_SETUP_KEY = 'SETUP_PASSKEY';\n\nfunction PasskeySetupSuggestion() {\n  const emoji = () => wrapEmojiText('🔑');\n\n  const onDismissed = () => {\n    rootScope.managers.appPromoManager.dismissSuggestion(PASSKEY_SETUP_KEY);\n  };\n\n  const onClick = () => {\n    showPasskeyPopup(() => {\n      rootScope.managers.appPromoManager.dismissSuggestion(PASSKEY_SETUP_KEY);\n    });\n  };\n\n  return (\n    <SimpleSuggestion\n      emoji={emoji}\n      title={i18n('Suggestion.PasskeySetup', [emoji()])}\n      subtitle={i18n('Suggestion.PasskeySetup.Subtitle')}\n      onClick={onClick}\n      onClose={onDismissed}\n    />\n  );\n}\n\nexport default function createPasskeySetupSuggestion(): PendingSuggestionController {\n  const pendingSuggestions = usePendingSuggestions();\n\n  return {\n    available: () => IS_WEB_AUTHN_SUPPORTED && pendingSuggestions().has(PASSKEY_SETUP_KEY),\n    component: PasskeySetupSuggestion\n  };\n}\n","export const PENDING_SUGGESTION_PRIORITY = [\n  'frozen',\n  'notifications',\n  'passkey',\n  'birthdayContacts',\n  'birthdaySetup'\n] as const;\n\nexport type PendingSuggestionType = typeof PENDING_SUGGESTION_PRIORITY[number];\n\nexport default function selectPendingSuggestion(\n  available: Partial<Record<PendingSuggestionType, boolean>>\n): PendingSuggestionType {\n  return PENDING_SUGGESTION_PRIORITY.find((type) => available[type]);\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport type {BotConnectionReview} from '@appManagers/appBusinessManager';\n\nconst [botConnectionReviews, setBotConnectionReviews] = createRoot(() => (\n  createSignal<BotConnectionReview[]>([])\n));\n\nlet loaded = false;\n\nexport default function useBotConnectionReviews() {\n  if(!loaded) {\n    loaded = true;\n\n    rootScope.managers.appBusinessManager.getBotConnectionReviews()\n    .then(setBotConnectionReviews)\n    .catch(() => {});\n\n    rootScope.addEventListener('bot_connection_reviews_update', setBotConnectionReviews);\n  }\n\n  return botConnectionReviews;\n}\n","import Button from '@components/buttonTsx';\nimport {PeerTitleTsx} from '@components/peerTitleTsx';\nimport RippleElement from '@components/rippleElement';\nimport createBirthdaySuggestions from '@components/sidebarLeft/birthdaySuggestions';\nimport createEmailSetupSuggestion from '@components/sidebarLeft/emailSetupSuggestion';\nimport createFrozenSuggestion from '@components/sidebarLeft/frozenSuggestion';\nimport createNotificationsSuggestion from '@components/sidebarLeft/notificationsSuggestion';\nimport createPasskeySetupSuggestion from '@components/sidebarLeft/passkeySetupSuggestion';\nimport type {PendingSuggestionController} from '@components/sidebarLeft/pendingSuggestionController';\nimport styles from '@components/sidebarLeft/pendingSuggestion.module.scss';\nimport selectPendingSuggestion, {PendingSuggestionType} from '@components/sidebarLeft/selectPendingSuggestion';\nimport {toastNew} from '@components/toast';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport Animated from '@helpers/solid/animations';\nimport classNames from '@helpers/string/classNames';\nimport I18n, {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport useBotConnectionReviews from '@stores/chatAutomation';\nimport {useIsSidebarCollapsed} from '@stores/foldersSidebar';\nimport {createEffect, createMemo, createSignal, JSX, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\n\nfunction BotConnectionReviewSuggestion() {\n  const reviews = useBotConnectionReviews();\n  const review = createMemo(() => reviews()[0]);\n  const details = createMemo(() => [review()?.device, review()?.location].filter(Boolean).join(', '));\n  const [isSidebarCollapsed, setIsSidebarCollapsed] = useIsSidebarCollapsed();\n  const [processing, setProcessing] = createSignal(false);\n\n  const performAction = async(confirm: boolean) => {\n    const currentReview = review();\n    if(!currentReview || processing()) return;\n\n    setProcessing(true);\n    try {\n      const result = await (confirm ?\n        rootScope.managers.appBusinessManager.confirmBotConnection(currentReview.botId) :\n        rootScope.managers.appBusinessManager.rejectBotConnection(currentReview.botId));\n      if(result) {\n        toastNew({\n          langPackKey: confirm ?\n            'ChatAutomation.ConnectionReview.Confirmed' :\n            'ChatAutomation.ConnectionReview.Rejected'\n        });\n      }\n    } catch(err) {\n      toastNew({langPackKey: 'Error.AnError'});\n    } finally {\n      setProcessing(false);\n    }\n  };\n\n  const botTitle = () => (\n    <PeerTitleTsx peerId={review().botId.toPeerId(false)} username />\n  );\n\n  return (\n    <Show when={review()}>\n      <Show\n        when={!isSidebarCollapsed()}\n        fallback={\n          <RippleElement\n            component=\"button\"\n            type=\"button\"\n            class={classNames(styles.collapsed, 'hover-danger-effect')}\n            aria-label={I18n.format('ChatAutomation.ConnectionReview.Title', true)}\n            onClick={() => setIsSidebarCollapsed(false)}\n          >\n            {documentFragmentToNodes(wrapEmojiText('⚠️'))}\n          </RippleElement>\n        }\n      >\n        <div class={styles.connectionReview}>\n          <div class={styles.connectionReviewTitle}>\n            {reviews().length > 1 && `1/${reviews().length} `}\n            {i18n('ChatAutomation.ConnectionReview.Title')}\n          </div>\n          <div class={styles.connectionReviewText}>\n            {botTitle()} {' '}\n            {details() ?\n              i18n('ChatAutomation.ConnectionReview.Text', [details()]) :\n              i18n('ChatAutomation.ConnectionReview.TextNoLocation')}\n          </div>\n          <div class={styles.connectionReviewActions}>\n            <Button\n              primaryTransparent\n              class={styles.connectionReviewButton}\n              disabled={processing()}\n              text=\"ChatAutomation.ConnectionReview.Confirm\"\n              onClick={() => performAction(true)}\n            />\n            <Button\n              primaryTransparent\n              class={classNames(styles.connectionReviewButton, styles.connectionReviewReject)}\n              disabled={processing()}\n              text=\"ChatAutomation.ConnectionReview.Reject\"\n              onClick={() => performAction(false)}\n            />\n          </div>\n        </div>\n      </Show>\n    </Show>\n  );\n}\n\nexport function renderPendingSuggestion(toElement: HTMLElement) {\n  toElement.classList.add(styles.container);\n\n  render(() => {\n    const birthdaySuggestions = createBirthdaySuggestions();\n    const suggestions: Record<PendingSuggestionType, PendingSuggestionController> = {\n      frozen: createFrozenSuggestion(),\n      notifications: createNotificationsSuggestion(),\n      passkey: createPasskeySetupSuggestion(),\n      birthdayContacts: birthdaySuggestions.contacts,\n      birthdaySetup: birthdaySuggestions.setup\n    };\n    createEmailSetupSuggestion();\n\n    const [element, setElement] = createSignal<JSX.Element>();\n    const botConnectionReviews = useBotConnectionReviews();\n    const suggestionConstructor = createMemo(() => {\n      if(botConnectionReviews().length) {\n        return BotConnectionReviewSuggestion;\n      }\n\n      const type = selectPendingSuggestion({\n        frozen: suggestions.frozen.available(),\n        notifications: suggestions.notifications.available(),\n        passkey: suggestions.passkey.available(),\n        birthdayContacts: suggestions.birthdayContacts.available(),\n        birthdaySetup: suggestions.birthdaySetup.available()\n      });\n\n      return type ? suggestions[type].component : undefined;\n    });\n\n    createEffect(() => {\n      const constructor = suggestionConstructor();\n      const element = constructor ? (<div class={styles.suggestionContainer}>{constructor()}</div>) : undefined;\n      setElement(element);\n    });\n\n    createEffect(() => {\n      document.body.classList.toggle('has-pending-suggestion', !!element());\n    });\n\n    return (\n      <Animated\n        type=\"grow-height\"\n        appear\n        mode=\"add-remove\"\n        noItemClass\n      >\n        {element()}\n      </Animated>\n    );\n  }, toElement);\n}\n","import {createRoot, createSignal} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport type {UnconfirmedAuthorization} from '@appManagers/appAccountManager';\n\nconst [authorizations, setAuthorizations] = createRoot(() => {\n  return createSignal<UnconfirmedAuthorization[]>([]);\n});\n\nlet loaded = false;\n\nexport default function useUnconfirmedAuthorizations() {\n  if(!loaded) {\n    loaded = true;\n    let updateVersion = 0;\n\n    rootScope.addEventListener('unconfirmed_authorizations_update', (updated) => {\n      ++updateVersion;\n      setAuthorizations(updated);\n    });\n\n    const version = updateVersion;\n    rootScope.managers.appAccountManager.getUnconfirmedAuthorizations().then((current) => {\n      if(version === updateVersion) {\n        setAuthorizations(current);\n      }\n    });\n  }\n\n  return authorizations;\n}\n","import Button from '@components/buttonTsx';\nimport MediaHeader from '@components/mediaHeader';\nimport PopupElementTsx, {createPopup as createPopupTsx} from '@components/popups/indexTsx';\nimport RippleElement from '@components/rippleElement';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {AppActiveSessionsTab} from '@components/solidJsTabs/tabs';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport Animated from '@helpers/solid/animations';\nimport classNames from '@helpers/string/classNames';\nimport documentFragmentToNodes from '@helpers/dom/documentFragmentToNodes';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {I18n, i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {hideToast, toast, toastNew} from '@components/toast';\nimport {useIsSidebarCollapsed} from '@stores/foldersSidebar';\nimport useUnconfirmedAuthorizations from '@stores/unconfirmedAuthorizations';\nimport type {UnconfirmedAuthorization} from '@appManagers/appAccountManager';\nimport {createEffect, createSignal, JSX, onCleanup, Show} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport styles from '@components/sidebarLeft/newAuthorization.module.scss';\n\nexport function formatAuthorizationOrigin(authorization: UnconfirmedAuthorization) {\n  return [authorization.device, authorization.location].filter(Boolean).join(', ');\n}\n\nfunction makeTitle(total: number) {\n  const title = document.createDocumentFragment();\n  if(total > 1) {\n    title.append(`1/${total} `);\n  }\n  title.append(i18n('UnconfirmedAuthTitle'));\n  return title;\n}\n\nfunction getAuthorizationAccessibleLabel(authorization: UnconfirmedAuthorization, total: number) {\n  const position = total > 1 ? `1/${total}. ` : '';\n  return position + I18n.format('UnconfirmedAuthTitle', true) + ' ' +\n    I18n.format('UnconfirmedAuthSingle', true, [formatAuthorizationOrigin(authorization)]);\n}\n\nfunction AuthorizationPreventedPopup(props: {authorization: UnconfirmedAuthorization}) {\n  const [show, setShow] = createSignal(false);\n  const [remaining, setRemaining] = createSignal(5);\n  let interval: number;\n  let countdownStarted = false;\n\n  const startCountdown = () => {\n    if(countdownStarted) return;\n    countdownStarted = true;\n    window.clearTimeout(readyFallback);\n    setShow(true);\n    interval = window.setInterval(() => {\n      setRemaining((value) => {\n        if(value <= 1) {\n          window.clearInterval(interval);\n          return 0;\n        }\n\n        return value - 1;\n      });\n    }, 1000);\n  };\n\n  const readyFallback = window.setTimeout(startCountdown, 1000);\n  onCleanup(() => {\n    window.clearTimeout(readyFallback);\n    window.clearInterval(interval);\n  });\n\n  return (\n    <PopupElementTsx\n      class={styles.popup}\n      closable={false}\n      show={show()}\n      animationGroup=\"none\"\n      isConfirmationNeededOnClose={() => {\n        if(remaining()) return Promise.reject();\n      }}\n    >\n      <PopupElementTsx.Body class={styles.popupBody}>\n        <MediaHeader>\n          <MediaHeader.Sticker\n            class={styles.popupSticker}\n            name=\"hand_stop\"\n            size={80}\n            onReady={startCountdown}\n          />\n          <MediaHeader.Title>\n            {i18n('UnconfirmedAuthDeniedTitle', [1])}\n          </MediaHeader.Title>\n          <MediaHeader.Subtitle>\n            {i18n('UnconfirmedAuthDeniedMessageSingle', [formatAuthorizationOrigin(props.authorization)])}\n          </MediaHeader.Subtitle>\n        </MediaHeader>\n        <div class={classNames('popup-description-framed', styles.warning)}>\n          {i18n('UnconfirmedAuthDeniedWarning')}\n        </div>\n      </PopupElementTsx.Body>\n      <PopupElementTsx.Footer>\n        <PopupElementTsx.FooterButton\n          confirm\n          disabled={!!remaining()}\n        >\n          {i18n('UnconfirmedAuthDeniedButton')}\n          {remaining() ? ` (${remaining()})` : undefined}\n        </PopupElementTsx.FooterButton>\n      </PopupElementTsx.Footer>\n    </PopupElementTsx>\n  );\n}\n\nfunction showAuthorizationPrevented(authorization: UnconfirmedAuthorization) {\n  createPopupTsx(() => <AuthorizationPreventedPopup authorization={authorization} />);\n}\n\nasync function openActiveSessions() {\n  const authorizations = await rootScope.managers.appAccountManager.getAuthorizations();\n  appSidebarLeft.createTab(AppActiveSessionsTab).open({\n    authorizations: authorizations.authorizations\n  });\n}\n\nfunction showAuthorizationConfirmed() {\n  const devicesLink = anchorCallback(() => {\n    hideToast();\n    openActiveSessions().catch(() => toastNew({langPackKey: 'Error.AnError'}));\n  });\n  devicesLink.append(i18n('Settings'), ' > ', i18n('Devices'));\n\n  const content = document.createDocumentFragment();\n  const title = document.createElement('strong');\n  title.append(i18n('UnconfirmedAuthConfirmed'));\n  content.append(\n    title,\n    document.createElement('br'),\n    i18n('UnconfirmedAuthConfirmedMessage', [devicesLink])\n  );\n  toast(content, undefined, 5000);\n}\n\nexport function NewAuthorization(props: {\n  authorization: UnconfirmedAuthorization,\n  total: number\n}) {\n  const [isSidebarCollapsed] = useIsSidebarCollapsed();\n  const [processing, setProcessing] = createSignal(false);\n\n  const performAction = async(action: 'confirm' | 'deny') => {\n    if(processing()) return false;\n\n    const authorization = props.authorization;\n    setProcessing(true);\n    try {\n      const result = action === 'confirm' ?\n        await rootScope.managers.appAccountManager.confirmUnconfirmedAuthorization(authorization.hash) :\n        await rootScope.managers.appAccountManager.resetAuthorization(authorization.hash);\n\n      if(!result) {\n        throw new Error('Authorization action failed');\n      }\n\n      if(action === 'confirm') {\n        showAuthorizationConfirmed();\n      } else {\n        setTimeout(() => showAuthorizationPrevented(authorization), 0);\n      }\n\n      return true;\n    } catch(err) {\n      const error = err as ApiError;\n      toastNew({\n        langPackKey: error?.type === 'FRESH_RESET_AUTHORISATION_FORBIDDEN' ?\n          'RecentSessions.Error.FreshReset' :\n          'Error.AnError'\n      });\n      return false;\n    } finally {\n      setProcessing(false);\n    }\n  };\n\n  const showActionsPopup = () => {\n    createPopupTsx(() => (\n      <PopupElementTsx closable show>\n        <PopupElementTsx.Header>\n          <PopupElementTsx.Title>{makeTitle(props.total)}</PopupElementTsx.Title>\n        </PopupElementTsx.Header>\n        <PopupElementTsx.Body>\n          <div class=\"popup-description\">\n            {i18n('UnconfirmedAuthSingle', [formatAuthorizationOrigin(props.authorization)])}\n          </div>\n        </PopupElementTsx.Body>\n        <PopupElementTsx.Buttons>\n          <PopupElementTsx.Button\n            confirm\n            langKey=\"UnconfirmedAuthConfirm\"\n            callback={() => performAction('confirm')}\n          />\n          <PopupElementTsx.Button\n            danger\n            langKey=\"UnconfirmedAuthDeny\"\n            callback={() => performAction('deny')}\n          />\n        </PopupElementTsx.Buttons>\n      </PopupElementTsx>\n    ));\n  };\n\n  return (\n    <Show\n      when={isSidebarCollapsed()}\n      fallback={\n        <div\n          class={styles.notice}\n          role=\"alert\"\n          aria-live=\"assertive\"\n          aria-atomic=\"true\"\n        >\n          <div class={styles.title}>\n            {props.total > 1 && `1/${props.total} `}\n            {i18n('UnconfirmedAuthTitle')}\n          </div>\n          <div class={styles.subtitle}>\n            {i18n('UnconfirmedAuthSingle', [formatAuthorizationOrigin(props.authorization)])}\n          </div>\n          <div class={styles.actions}>\n            <Button\n              class={classNames(styles.action, 'rp-overflow', 'hover-primary-effect')}\n              disabled={processing()}\n              onClick={() => performAction('confirm')}\n              text=\"UnconfirmedAuthConfirm\"\n            />\n            <Button\n              class={classNames(styles.action, styles.deny, 'rp-overflow', 'hover-danger-effect')}\n              disabled={processing()}\n              onClick={() => performAction('deny')}\n              text=\"UnconfirmedAuthDeny\"\n            />\n          </div>\n        </div>\n      }\n    >\n      <RippleElement\n        component=\"button\"\n        type=\"button\"\n        class={classNames(styles.collapsed, 'hover-effect')}\n        onClick={showActionsPopup}\n        aria-label={getAuthorizationAccessibleLabel(props.authorization, props.total)}\n      >\n        {documentFragmentToNodes(wrapEmojiText('🔐'))}\n      </RippleElement>\n    </Show>\n  );\n}\n\nexport function renderNewAuthorization(toElement: HTMLElement) {\n  toElement.classList.add(styles.container);\n\n  render(() => {\n    const authorizations = useUnconfirmedAuthorizations();\n    const [element, setElement] = createSignal<JSX.Element>();\n\n    createEffect(() => {\n      const authorization = authorizations()[0];\n      setElement(authorization ? (\n        <div class={styles.noticeContainer}>\n          <NewAuthorization\n            authorization={authorization}\n            total={authorizations().length}\n          />\n        </div>\n      ) : undefined);\n    });\n\n    createEffect(() => {\n      document.body.classList.toggle('has-unconfirmed-authorization', !!element());\n    });\n\n    onCleanup(() => {\n      document.body.classList.remove('has-unconfirmed-authorization');\n    });\n\n    return (\n      <Animated\n        type=\"grow-height\"\n        appear\n        mode=\"add-remove\"\n        noItemClass\n      >\n        {element()}\n      </Animated>\n    );\n  }, toElement);\n}\n","import type {Chat, User} from '@layer';\n\n/**\n * The Community a chat or a user is linked to, if any. Only channels and users can carry\n * the link, so anything else resolves to undefined rather than reading a missing field.\n */\nexport default function getLinkedCommunityId(peer: Chat | User) {\n  return peer?._ === 'channel' || peer?._ === 'user' ?\n    peer.linked_community_id?.toChatId() :\n    undefined;\n}\n","import lastItem from '@helpers/array/lastItem';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {Dialog} from '@layer';\nimport {StoriesSegments} from '@lib/appManagers/appStoriesManager';\nimport {FOLDER_ID_ARCHIVE} from '@lib/appManagers/constants';\nimport getDialogIndex from '@lib/appManagers/utils/dialogs/getDialogIndex';\nimport getDialogIndexKey from '@lib/appManagers/utils/dialogs/getDialogIndexKey';\nimport {isDialog} from '@lib/appManagers/utils/dialogs/isDialog';\nimport defineSolidElement, {PassedProps} from '@lib/solidjs/defineSolidElement';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport {AckedResult} from '@lib/superMessagePort';\nimport {useAppSettings} from '@stores/appSettings';\nimport {\n  useCollapsedCommunityDialogsKey\n} from '@stores/communities';\nimport {usePeers} from '@stores/peers';\nimport {Accessor, createComputed, createEffect, createMemo, createResource, createRoot, createSignal, For, onCleanup, Ref, Setter, Show} from 'solid-js';\nimport {createStore, unwrap} from 'solid-js/store';\nimport getLinkedCommunityId from '@appManagers/utils/communities/getLinkedCommunityId';\nimport isCollapsedCommunity from '@appManagers/utils/communities/isCollapsedCommunity';\nimport styles from './archiveDialog.module.scss';\nimport Badge from './badge';\nimport {IconTsx} from './iconTsx';\nimport {createStoriesStore, StoriesContextValue} from './stories/store';\nimport {createStoriesViewerWithProvider} from './stories/viewer';\n\n// if(import.meta.hot) import.meta.hot.accept(); // screw it\n\n\nconst limit = 10;\nconst limitSymbols = 20;\n\ntype ArchiveDialogProps = {\n  state: DisposableArchiveDialogState['state'];\n};\n\ntype Controls = {\n  openStory: () => void;\n};\n\nexport const archiveDialogTagName = 'archive-dialog';\n\nconst ArchiveDialog = defineSolidElement({\n  name: archiveDialogTagName,\n  component: (props: PassedProps<ArchiveDialogProps>, _, controls: Controls) => {\n    props.element.classList.add('row', 'no-wrap', 'row-with-padding', 'row-clickable', 'hover-effect', 'chatlist-chat', 'chatlist-chat-bigger', 'row-big');\n\n    const [openStoriesTarget, setOpenStoriesTarget] = createSignal<HTMLElement>();\n\n    const sortedDialogs = createMemo(() => props.state.sortedDialogs().slice(0, limit)); // Note: more dialogs can appear if they've been updated\n    const totalUnreadCount = () => props.state.totalUnreadCount();\n    // const totalUnreadCount = () => 403430;\n\n    // Note: we cannot use createStore on dialogs, because it requires reacting to the whole object change and then sending it into\n    // the shared worker thread to compute whether it is unread or not\n    const [cachedDialogUnread, setCachedDialogUnread] = createStore<Record<PeerId, boolean>>({});\n\n    controls.openStory = () => {\n      props.state.openArchiveStories(openStoriesTarget());\n    };\n\n    return (\n      <>\n        <ArchiveAvatar\n          storiesSegments={props.state.segments()}\n          ref={setOpenStoriesTarget}\n        />\n        <div class=\"row-row row-title-row\">\n          <I18nTsx class={styles.Title} key=\"ArchivedChats\" />\n        </div>\n        <div class=\"row-row row-subtitle-row\">\n          <div class={styles.Subtitle}>\n            <For each={sortedDialogs()}>\n              {(dialog, index) => (\n                <>\n                  <PeerTitleItem\n                    dialog={dialog}\n                    cachedIsUnread={cachedDialogUnread[dialog.peerId]}\n                    onIsUnreadChange={isUnread => setCachedDialogUnread(dialog.peerId, isUnread)}\n                  />\n                  {index() !== sortedDialogs().length - 1 && ', '}\n                </>\n              )}\n            </For>\n          </div>\n          <Show when={totalUnreadCount() > 0}>\n            <Badge class={styles.UnreadBadge} tag=\"span\" size={22} color=\"gray\">\n              {formatNumber(totalUnreadCount(), 1)}\n            </Badge>\n          </Show>\n        </div>\n      </>\n    );\n  }\n});\n\ntype CreateArchiveDialogStateArgs = {\n  onHasArchiveDialogChanged: (hasDialogs: boolean) => void;\n};\n\nexport type DisposableArchiveDialogState = ReturnType<typeof createArchiveDialogState>;\n\nexport const createArchiveDialogState = ({onHasArchiveDialogChanged}: CreateArchiveDialogStateArgs) => createRoot((dispose) => {\n  const state = useArchivedDialogsState();\n\n  const [appSettings] = useAppSettings();\n\n  const hasDialogs = createMemo(() => state.sortedDialogs().length > 0);\n  const hasArchiveDialog = createMemo(() => appSettings.showArchiveInChatList && hasDialogs());\n\n  createEffect(() => {\n    if(!state.isReady()) return;\n    onHasArchiveDialogChanged(hasArchiveDialog());\n  });\n\n  return {\n    state,\n    hasArchiveDialog,\n    dispose\n  };\n});\n\nfunction useArchivedDialogsState() {\n  const {rootScope} = useHotReloadGuard();\n  const peers = usePeers();\n\n  let initialPromise: Promise<AckedResult<unknown>>;\n\n  const fetchDialogs = async() => {\n    const typedPromise = rootScope.managers.acknowledged.dialogsStorage.getDialogs({\n      filterId: FOLDER_ID_ARCHIVE,\n      limit\n    });\n\n    initialPromise = typedPromise;\n\n    const ackedResult = await typedPromise;\n    return ackedResult.result;\n  };\n\n  const [canFetch, setCanFetch] = createSignal(false);\n\n  const [fetchedDialogs, {refetch}] = createResource(canFetch, () => fetchDialogs()); // used for initial loading state\n  const [dialogs, setDialogs] = createSignal<Dialog.dialog[]>([]);\n\n  const isReady = createMemo(() => fetchedDialogs.state === 'ready');\n  const fetchedDialogsLength = createMemo(() => isReady() ? fetchedDialogs().dialogs.length : 0);\n  const isEnd = createMemo(() => isReady() && fetchedDialogs().isEnd);\n\n  const sortedDialogs = createMemo(() => dialogs()\n  .filter((dialog) => {\n    const communityId = getLinkedCommunityId(peers[dialog.peerId]);\n    return !isCollapsedCommunity(peers[communityId?.toPeerId(true)]);\n  })\n  .sort((a, b) => getArchivedDialogIndex(b) - getArchivedDialogIndex(a)));\n\n  createComputed(() => {\n    if(fetchedDialogs.state === 'ready') {\n      setDialogs(fetchedDialogs().dialogs.filter(d => isDialog(d)));\n    }\n  });\n\n  useDialogEvents({\n    sortedDialogs,\n    setDialogs,\n    isEnd\n  });\n\n  createEffect(() => {\n    if(\n      isReady() &&\n      !isEnd() &&\n      dialogs().length < fetchedDialogsLength() && // when some dialogs have been removed\n      dialogs().length < limit\n    ) {\n      refetch();\n    }\n  });\n\n  function ensureHydrated() {\n    if(canFetch()) return;\n\n    setCanFetch(true);\n\n    return initialPromise;\n  }\n\n  const storiesContext = createStoriesStore({archive: true});\n\n  return {\n    totalUnreadCount: useTotalUnreadCount(),\n    segments: useStoriesSegments(storiesContext),\n    openArchiveStories: useOpenArchiveStories(storiesContext),\n    ensureHydrated,\n    isReady,\n    sortedDialogs\n  };\n}\n\nconst isArchivedDialog = (dialog: Dialog.dialog) => dialog?.folder_id === FOLDER_ID_ARCHIVE;\nconst getArchivedDialogIndex = (dialog: Dialog.dialog) => getDialogIndex(dialog, getDialogIndexKey(FOLDER_ID_ARCHIVE));\n\ntype UseDialogEventsArgs = {\n  sortedDialogs: Accessor<Dialog.dialog[]>;\n  setDialogs: Setter<Dialog.dialog[]>;\n  isEnd: Accessor<boolean>;\n};\n\nfunction useDialogEvents({sortedDialogs, setDialogs, isEnd}: UseDialogEventsArgs) {\n  const {rootScope} = useHotReloadGuard();\n\n  const listenerSetter = new ListenerSetter;\n\n  const canKeepDialog = (dialog: Dialog.dialog) => {\n    if(!isArchivedDialog(dialog)) return false;\n\n    const last = lastItem(sortedDialogs());\n    const isEmptyList = !last;\n\n    const bottomIndex = getArchivedDialogIndex(last);\n    const dialogIndex = getArchivedDialogIndex(dialog);\n\n    return isEmptyList || dialogIndex >= bottomIndex || isEnd();\n  };\n\n  const addDialog = (dialog: Dialog.dialog) => setDialogs(prev => [\n    ...prev.filter(d => d.peerId !== dialog.peerId),\n    dialog\n  ]);\n\n  const removeDialog = (dialog: Dialog.dialog) => setDialogs(prev => prev.filter(d => d.peerId !== dialog.peerId));\n\n  const updateDialog = (dialog: Dialog.dialog) => {\n    if(canKeepDialog(dialog)) {\n      addDialog(dialog);\n    } else {\n      removeDialog(dialog);\n    }\n  };\n\n  listenerSetter.add(rootScope)('dialog_flush', ({dialog}) => {\n    updateDialog(dialog);\n  });\n\n  listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n    for(const [, {dialog}] of dialogs) {\n      if(!isDialog(dialog)) continue;\n      updateDialog(dialog);\n    }\n  });\n\n  listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n    if(!isDialog(dialog)) return;\n    removeDialog(dialog);\n  });\n\n  listenerSetter.add(rootScope)('dialog_unread', ({dialog}) => {\n    if(!isDialog(dialog)) return;\n    updateDialog(dialog);\n  });\n\n  listenerSetter.add(rootScope)('dialog_draft', ({dialog, drop}) => {\n    if(!isDialog(dialog)) return;\n\n    if(drop) {\n      removeDialog(dialog);\n    } else {\n      updateDialog(dialog);\n    }\n  });\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n}\n\nfunction useTotalUnreadCount() {\n  const {rootScope} = useHotReloadGuard();\n  const projectionKey = useCollapsedCommunityDialogsKey();\n  const [totalUnreadCount, {refetch}] = createResource(\n    projectionKey,\n    () => rootScope.managers.dialogsStorage\n    .getFolderUnreadCount(FOLDER_ID_ARCHIVE, true)\n    .then((result) => result.unreadCount),\n    {initialValue: 0}\n  );\n\n  const listenerSetter = new ListenerSetter;\n\n  listenerSetter.add(rootScope)('folder_unread', (folder) => {\n    if(folder.id === FOLDER_ID_ARCHIVE) {\n      void refetch();\n    }\n  });\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n\n  return totalUnreadCount;\n}\n\nfunction useStoriesSegments(storiesContextValue: StoriesContextValue) {\n  const {rootScope} = useHotReloadGuard();\n\n  const [stories] = storiesContextValue;\n  const storiesPeerIds = createMemo(() => stories.peers?.map(peer => peer.peerId));\n\n  const [storiesSegments, setStoriesSegments] = createSignal<StoriesSegments>();\n\n  const fetchStoriesSegmentsByPeerIds = (peerIds: PeerId[]) => rootScope.managers.appStoriesManager.getPeersStoriesSegments(peerIds);\n\n  const [storiesSegmentsByPeerIds, {refetch}] = createResource(\n    storiesPeerIds,\n    fetchStoriesSegmentsByPeerIds\n  );\n\n  const listenerSetter = new ListenerSetter;\n\n  listenerSetter.add(rootScope)('peer_stories', refetchStoriesSegments);\n  listenerSetter.add(rootScope)('stories_read', refetchStoriesSegments);\n  listenerSetter.add(rootScope)('story_deleted', refetchStoriesSegments);\n  listenerSetter.add(rootScope)('story_new', refetchStoriesSegments);\n  listenerSetter.add(rootScope)('story_update', refetchStoriesSegments);\n\n  function refetchStoriesSegments({peerId}: {peerId: PeerId}) {\n    if(!storiesPeerIds()?.includes(peerId)) return;\n    refetch();\n  }\n\n  onCleanup(() => {\n    listenerSetter.removeAll();\n  });\n\n  createComputed(() => {\n    if(storiesSegmentsByPeerIds.state !== 'ready') return;\n\n    if(!storiesSegmentsByPeerIds()?.length) {\n      setStoriesSegments(undefined);\n      return;\n    }\n\n    // Show only one segment per peer\n    const newStoriesSegments = storiesSegmentsByPeerIds().map(({segments}) => {\n      const segment =\n        segments.find(segment => segment.type === 'close') ||\n        segments.find(segment => segment.type === 'unread') ||\n        segments[0];\n\n      return {\n        ...segment,\n        length: 1\n      };\n    }).filter(Boolean);\n\n    setStoriesSegments(newStoriesSegments);\n  });\n\n  return storiesSegments;\n}\n\nfunction useOpenArchiveStories(storiesContextValue: StoriesContextValue) {\n  const [stories] = storiesContextValue;\n  const [viewerTarget, setViewerTarget] = createSignal<HTMLElement>();\n\n  const canOpenStories = createMemo(() => stories.ready && stories.peers.length > 0);\n\n  const cloneCurrentPeers = () => structuredClone(unwrap(stories.peers));\n\n  createEffect(() => {\n    if(!viewerTarget()) return;\n\n    const onExit = () => {\n      setViewerTarget(undefined);\n    };\n\n    createStoriesViewerWithProvider({\n      onExit,\n      target: viewerTarget\n    }, {\n      peers: cloneCurrentPeers(),\n      archive: true\n    });\n  });\n\n  return (target: HTMLElement) => {\n    if(!canOpenStories()) return;\n    setViewerTarget(target);\n  };\n}\n\nfunction PeerTitleItem(props: {\n  dialog: Dialog.dialog;\n  cachedIsUnread: boolean;\n  onIsUnreadChange: (isUnread: boolean) => void;\n}) {\n  const {PeerTitleTsx, rootScope} = useHotReloadGuard();\n\n  const [isUnread] = createResource(() => props.dialog, (dialog) => rootScope.managers.appMessagesManager.isDialogUnread(dialog));\n\n  createEffect(() => {\n    if(isUnread.state !== 'ready') return;\n\n    if(isUnread() !== props.cachedIsUnread) {\n      props.onIsUnreadChange(isUnread());\n    }\n  });\n\n  return <PeerTitleTsx class={props.cachedIsUnread ? styles.unreadPeerTitle : undefined} peerId={props.dialog.peerId} limitSymbols={limitSymbols} />\n};\n\n\nfunction ArchiveAvatar(props: {\n  storiesSegments: StoriesSegments;\n  ref: Ref<HTMLDivElement>;\n}) {\n  const {StoriesSegments} = useHotReloadGuard();\n\n  const hasStories = createMemo(() => props.storiesSegments?.length > 0);\n\n  const {setStoriesSegments, storyDimensions, storiesCircle} = StoriesSegments({\n    size: 54,\n    colors: {}\n  });\n\n  createComputed(() => {\n    setStoriesSegments(props.storiesSegments);\n  });\n\n  return (\n    <div\n      class={`${styles.Media} row-media row-media-bigger dialog-avatar`}\n      classList={{\n        'archive-dialog-with-stories': hasStories(),\n        [styles.hasStories]: hasStories()\n      }}\n      style={{\n        'padding': storyDimensions() ? (storyDimensions().size - storyDimensions().willBeSize) / 2 + 'px' : undefined\n      }}\n      ref={props.ref}\n    >\n      {storiesCircle()}\n      <div class={styles.MediaContent}>\n        <IconTsx class={styles.MediaIcon} icon=\"archive_filled\" />\n      </div>\n    </div>\n  );\n};\n\nexport default ArchiveDialog;\n","import {animate} from '@helpers/animation';\nimport customProperties from '@helpers/dom/customProperties';\nimport easeInOutSine from '@helpers/easing/easeInOutSine';\nimport mediaSizes from '@helpers/mediaSizes';\nimport roundRect from '@helpers/canvas/roundRect';\n\nconst DPR = window.devicePixelRatio;\nconst SIZE = 20 * DPR;\nconst MARGIN = 2.5 * DPR;\nconst WIDTH = 2 * DPR;\nconst RADIUS = 1 * DPR;\nconst LENGTH = 3;\n\nconst MIN_HEIGHT = 4;\nconst MAX_HEIGHT = 12;\nconst DURATION = 1000;\n\nexport default function groupCallActiveIcon(isActive = false) {\n  const canvas = document.createElement('canvas');\n  canvas.width = canvas.height = SIZE;\n  const context = canvas.getContext('2d');\n\n  const TOTAL_WIDTH = LENGTH * WIDTH + (LENGTH - 1) * MARGIN;\n  const START_X = (SIZE - TOTAL_WIDTH) / 2;\n\n  const startTime = Date.now();\n  let wasMounted = false;\n  // let hadRound = false;\n  const renderFrame = () => {\n    if(!canvas.isConnected) {\n      if(wasMounted) {\n        return false;\n      }\n    } else if(!wasMounted) {\n      wasMounted = canvas.isConnected;\n    }\n\n    const time = Date.now();\n    // if(((time - startTime) / DURATION) >= 1) {\n    //   hadRound = true;\n    // }\n\n    const progress = easeInOutSine((time - startTime) % DURATION, 0, 1, DURATION);\n\n    context.clearRect(0, 0, SIZE, SIZE);\n    context.fillStyle = isActive && !mediaSizes.isMobile ? customProperties.getProperty('primary-color') : '#fff';\n\n    for(let i = 0; i < LENGTH; ++i) {\n      const x = START_X + (i * WIDTH) + (i * MARGIN);\n\n      let itemProgress: number;\n      if(progress >= .5) {\n        itemProgress = i % 2 ? 2 - progress * 2 : (progress - .5) * 2;\n      } else {\n        itemProgress = i % 2 ? progress * 2 : 1 - progress * 2;\n      }\n\n      let height = MIN_HEIGHT + (itemProgress * (MAX_HEIGHT - MIN_HEIGHT));\n      /* if(!hadRound && i === 1) {\n        console.log('call status animation', itemProgress, height, progress, progress >= .5);\n      } */\n\n      height *= DPR;\n      const y = (SIZE - height) / 2;\n\n      roundRect(context, x, y, WIDTH, height, RADIUS, true);\n    }\n\n    return true;\n  };\n\n  return {\n    canvas,\n    startAnimation: () => {\n      animate(renderFrame);\n      renderFrame();\n    },\n    setActive: (active: boolean) => {\n      isActive = active;\n      renderFrame();\n    }\n  };\n}\n","import {Component, createSignal, JSX, onCleanup} from 'solid-js';\n\nimport styles from '@components/loadingDialogSkeleton.module.scss';\n\n\nfunction pseudoRandomRange(seed: number, min: number, max: number) {\n  const x = Math.sin(seed * 10000 + 999999) * 10000;\n  const rand = x - Math.floor(x);\n\n  return min + rand * (max - min);\n}\n\nexport type LoadingDialogSkeletonSize = 72 | 64;\n\nconst LoadingDialogSkeleton: Component<{\n  class?: string;\n  style?: JSX.CSSProperties;\n  noAvatar?: boolean;\n  size: LoadingDialogSkeletonSize;\n  seed: number;\n}> = (props) => {\n  const [animating, setAnimating] = createSignal(false);\n\n  // Add the animation after timeout to save some performance while quickly scrolling\n  const timeout = self.setTimeout(() => {\n    setAnimating(true);\n  }, 1500);\n\n  onCleanup(() => {\n    self.clearTimeout(timeout);\n  });\n\n  return (\n    <div\n      class={`${styles.Container} loading-dialog-skeleton`}\n      classList={{\n        [props.class]: !!props.class,\n        [styles['size' + props.size]]: true,\n        [styles.noAvatar]: props.noAvatar,\n        [styles.shimmer]: animating()\n      }}\n      style={props.style}\n    >\n      <div class={styles.Avatar} />\n      <div class={styles.Content}>\n        <div class={styles.Title}>\n          <div class={styles.TitleLeft} style={{'--width': (pseudoRandomRange(props.seed, 100, 120) | 0) + 'px'}} />\n          <div class={styles.TitleRight} style={{'--width': (pseudoRandomRange(props.seed, 20, 60) | 0) + 'px'}} />\n        </div>\n        <div class={styles.Subtitle} style={{'--width': (pseudoRandomRange(props.seed, 60, 200) | 0) + 'px'}} />\n      </div>\n    </div>\n  );\n};\n\nexport default LoadingDialogSkeleton;\n","import {Accessor, createEffect, createSignal, on, onCleanup} from 'solid-js';\nimport {simpleEasing} from '@helpers/animateValue';\nimport {animate} from '@helpers/animation';\n\n\nexport default function createAnimatedValue(value: Accessor<number>, time: number, easing = simpleEasing, shouldAnimate: Accessor<boolean> = () => true) {\n  const [current, setCurrent] = createSignal(value());\n  const [animating, setAnimating] = createSignal(false);\n\n  createEffect(on(value, () => {\n    if(!shouldAnimate()) {\n      setCurrent(value());\n      return;\n    }\n\n    const startValue = current();\n    const startTime = performance.now();\n    setAnimating(true);\n\n    let cleaned = false;\n\n    animate(() => {\n      if(cleaned) return;\n\n      const progress = easing(Math.min(1, (performance.now() - startTime) / time));\n\n      setCurrent((value() - startValue) * progress + startValue);\n\n      if(progress < 1) return true;\n      setAnimating(false);\n    });\n\n    onCleanup(() => {\n      cleaned = true;\n      setAnimating(false);\n    });\n  }, {\n    defer: true\n  }));\n\n\n  const result = current as Accessor<number> & {animating: Accessor<boolean>};\n\n  result.animating = animating;\n\n  return result;\n}\n","import {Accessor, createMemo, createRenderEffect, createRoot, onCleanup} from 'solid-js';\nimport {createStore, Store} from 'solid-js/store';\n\nimport pickKeys from '@helpers/object/pickKeys';\nimport {requestRAF} from '@helpers/solid/requestRAF';\n\n\ntype SizeRoot = {\n  count: number;\n  store: Store<{width: number, height: number}>;\n  dispose: () => void;\n};\n\nconst NULL_KEY = {};\n\nconst map = new WeakMap<Element | typeof NULL_KEY, SizeRoot>();\n\nconst createSizeRoot = (element: Accessor<Element>) => createRoot(dispose => {\n  const [store, setStore] = createStore({width: 0, height: 0});\n\n  createRenderEffect(() => {\n    if(!element()) return;\n\n    setStore(pickKeys(element().getBoundingClientRect(), ['width', 'height']));\n\n    let callback: () => void, isQueued = false;\n\n    const resizeObserver = new ResizeObserver(([entry]) => {\n      const boxSize = entry.borderBoxSize[0];\n      if(!boxSize) return;\n\n      callback = () => setStore({\n        width: boxSize.inlineSize,\n        height: boxSize.blockSize\n      });\n\n      if(isQueued) return;\n      isQueued = true;\n\n      requestRAF(() => {\n        callback?.();\n        callback = undefined;\n        isQueued = false;\n      });\n    });\n\n    resizeObserver.observe(element());\n\n    onCleanup(() => {\n      resizeObserver.disconnect();\n    });\n  });\n\n  return {\n    count: 0,\n    store,\n    dispose\n  };\n});\n\nexport default function useElementSize(element: Accessor<Element>) {\n  const root = createMemo(() => {\n    const key = element() || NULL_KEY;\n\n    const root = map.get(key) || createSizeRoot(element);\n\n    if(!map.has(key)) map.set(key, root);\n\n    root.count++;\n\n    onCleanup(() => {\n      root.count--;\n      if(!root.count) {\n        root.dispose();\n        map.delete(key);\n      }\n    });\n\n    return root;\n  });\n\n  return {\n    get width() {\n      return root().store.width;\n    },\n    get height() {\n      return root().store.height;\n    }\n  };\n}\n","import {createSignal, onCleanup, onMount, Component, createSelector, createMemo, For, Show, Ref, createComputed, on, Accessor, untrack} from 'solid-js';\n\nimport createAnimatedValue from '@helpers/solid/createAnimatedValue';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport useElementSize from '@hooks/useElementSize';\n\n\nexport type VerticalVirtualListItemProps<T = any> = {\n  item: T;\n  top: number;\n  idx: number;\n  animating: boolean;\n};\n\nconst VerticalVirtualList: Component<{\n  ref: Ref<HTMLUListElement>;\n  list: any[];\n  ListItem: Component<VerticalVirtualListItemProps>;\n\n  class?: string;\n  scrollableHost: HTMLElement;\n\n  itemHeight: number;\n  thresholdPadding: number;\n\n  animate: boolean;\n\n  forceHostHeight?: boolean;\n  extraPaddingBottom?: number;\n}> = (props) => {\n  const totalCount = createMemo(() => props.list.length);\n\n  const [scrollAmount, setScrollAmount] = createSignal(0);\n  const hostSize = useElementSize(() => props.scrollableHost);\n\n  onMount(() => {\n    const listenerSetter = new ListenerSetter();\n\n    listenerSetter.add(props.scrollableHost)('scroll', () => {\n      setScrollAmount(props.scrollableHost.scrollTop);\n    });\n\n    onCleanup(() => {\n      listenerSetter.removeAll();\n    });\n  });\n\n\n  const onScrollShift = (amount: number) => {\n    untrack(() => {\n      props.scrollableHost.scrollTop -= amount;\n    });\n  };\n\n  const shouldAnimate = useShouldAnimate({\n    list: () => props.list,\n    hostHeight: () => hostSize.height,\n    itemHeight: () => props.itemHeight,\n    scrollAmount,\n    onScrollShift\n  });\n\n  const canAnimate = createMemo(() => shouldAnimate() && props.animate);\n\n  const isVisible = createSelector(\n    () => [scrollAmount(), hostSize.height, props.itemHeight, props.thresholdPadding] as const,\n    (\n      idx: number,\n      [scrollAmount, hostHeight, itemHeight, padding]\n    ) => (\n      idx * itemHeight >= scrollAmount - padding &&\n      (idx + 1) * itemHeight <= scrollAmount + hostHeight + padding\n    )\n  );\n\n\n  const Item: Component<{idx: number, item: any}> = (itemProps) => {\n    const animatedTop = createAnimatedValue(() => itemProps.idx * props.itemHeight, 120, undefined, canAnimate);\n\n    return (\n      <props.ListItem\n        idx={itemProps.idx}\n        item={itemProps.item}\n        top={animatedTop()}\n        animating={animatedTop.animating()}\n      />\n    );\n  };\n\n  const computedItemsHeight = () => totalCount() * props.itemHeight + Number(!!totalCount()) * (props.extraPaddingBottom || 0);\n\n  const height = createMemo(() => props.forceHostHeight ? hostSize.height : computedItemsHeight());\n\n  return (\n    <ul\n      ref={props.ref}\n      class={props.class}\n      style={{\n        height: height() + 'px',\n        overflow: props.forceHostHeight ? 'hidden' : undefined\n      }}\n    >\n      <For each={props.list}>\n        {(item, idx) => (\n          <Show when={isVisible(idx())}>\n            <Item idx={idx()} item={item} />\n          </Show>\n        )}\n      </For>\n    </ul>\n  );\n};\n\ntype UseShouldAnimateArgs = {\n  list: Accessor<any[]>;\n  scrollAmount: Accessor<number>;\n  itemHeight: Accessor<number>;\n  hostHeight: Accessor<number>;\n\n  onScrollShift: (amount: number) => void;\n};\n\n/**\n * If all the items from the viewport of the host element shift by the same amount, don't animate them\n *\n * For example when a new chat appears on top, and we have some scroll, prevent all the chats from viewport\n * moving at the same time\n */\nfunction useShouldAnimate({list, scrollAmount, hostHeight, itemHeight, onScrollShift}: UseShouldAnimateArgs) {\n  const [shouldAnimate, setShouldAnimate] = createSignal(true);\n\n  const isActuallyVisible = createSelector(\n    () => [scrollAmount(), hostHeight(), itemHeight()] as const,\n    (\n      idx: number,\n      [scrollAmount, hostHeight, itemHeight]\n    ) => (\n      (idx + 1) * itemHeight >= scrollAmount &&\n      idx * itemHeight <= scrollAmount + hostHeight\n    )\n  );\n\n  createComputed(on(list, (current, prev = []) => {\n    const visiblePrev = prev.filter((_, i) => isActuallyVisible(i));\n    const visibleNow = current.filter((_, i) => isActuallyVisible(i));\n\n    const visiblePrevAndNow = Array.from(new Set([...visibleNow, ...visiblePrev]));\n\n    let allChangedTheSameAmount = true;\n    let prevDiff: number;\n\n    for(const item of visiblePrevAndNow) {\n      const prevIdx = prev.indexOf(item);\n      const currentIdx = current.indexOf(item);\n\n      if(prevIdx === -1 || currentIdx === -1) {\n        allChangedTheSameAmount = false;\n        break;\n      }\n\n      const diff = prevIdx - currentIdx;\n\n      if(typeof prevDiff === 'undefined') {\n        prevDiff = diff;\n        continue;\n      }\n\n      if(prevDiff !== diff) {\n        allChangedTheSameAmount = false;\n        break;\n      }\n    }\n\n    if(!visiblePrevAndNow.length) {\n      allChangedTheSameAmount = false;\n      prevDiff = 0;\n    }\n\n    setShouldAnimate(!allChangedTheSameAmount);\n\n    if(allChangedTheSameAmount) {\n      onScrollShift(prevDiff * itemHeight());\n    }\n\n    return current;\n  }));\n\n  return shouldAnimate;\n}\n\nexport default VerticalVirtualList;\n","import {\n  createSignal,\n  createMemo,\n  createRenderEffect,\n  Show,\n  createEffect,\n  createRoot,\n  batch,\n  untrack,\n  onCleanup,\n  createComputed,\n  on\n} from 'solid-js';\n\nimport LoadingDialogSkeleton, {LoadingDialogSkeletonSize} from '@components/loadingDialogSkeleton';\nimport VerticalVirtualList, {VerticalVirtualListItemProps} from '@components/verticalVirtualList';\n\nimport styles from '@components/deferredSortedVirtualList.module.scss';\n\n\ntype CreateDeferredSortedVirtualListArgs<T> = {\n  scrollable: HTMLElement,\n  getItemElement: (item: T, id: any) => HTMLElement,\n  onItemUnmount?: (item: T) => void,\n  // * Unlike onItemUnmount (the row merely left the rendered window and is kept for re-mounting),\n  // * this fires when the list drops the item for good - removed, trimmed by checkShrink, cleared or\n  // * disposed - and the owner will never see it again. Without it an owner that allocates per-item\n  // * resources (middleware, players, canvases) has no point at which to release them.\n  onItemDiscard?: (item: T) => void,\n  onListShrinked: () => void,\n  requestItemForIdx: (idx: number, itemsLength: number) => void,\n  sortWith: (a: number, b: number) => number,\n  itemSize: LoadingDialogSkeletonSize,\n  noAvatar?: boolean,\n  onListLengthChange?: () => void,\n  extraPaddingBottom?: number\n};\n\nexport type DeferredSortedVirtualListItem<T> = {\n  id: any,\n  index: number,\n  value: T\n};\n\n\nconst EXTRA_ITEMS_TO_KEEP = 50;\n\n\n/**\n * How far the reveal threshold jumps once a batch of loaded-but-hidden rows is ready.\n *\n * Reveal used to advance to (lowest queued index + 1), which let through exactly ONE row\n * per timer: a window of N rows needed N serial ~8ms hops, and every hop is a `setTimeout`,\n * so a main thread busy with scrolling stretches them and the tail of the window keeps\n * showing skeletons for up to a second even though the dialogs are already in memory.\n * The whole ready batch can go at once — the single tick still keeps rows from popping in\n * on the same frame they arrive.\n */\nexport function getNextRevealIdx(queued: number[]) {\n  let max = -1;\n  for(const idx of queued) {\n    if(idx > max) max = idx;\n  }\n\n  return max < 0 ? null : max + 1;\n}\n\n\nexport const createDeferredSortedVirtualList = <T, >(args: CreateDeferredSortedVirtualListArgs<T>) => createRoot(dispose => {\n  const {\n    scrollable,\n    getItemElement,\n    onItemUnmount,\n    onItemDiscard,\n    onListShrinked,\n    requestItemForIdx,\n    sortWith,\n    itemSize,\n    onListLengthChange,\n    noAvatar,\n    extraPaddingBottom = 8\n  } = args;\n\n  const [items, setItems] = createSignal<DeferredSortedVirtualListItem<T>[]>([]);\n  const [pinnedItems, setPinnedItems] = createSignal<DeferredSortedVirtualListItem<T>[]>([]);\n  const [totalCount, setTotalCount] = createSignal(0);\n  const [wasAtLeastOnceFetched, setWasAtLeastOnceFetched] = createSignal(false);\n  const [revealIdx, setRevealIdx] = createSignal(Infinity);\n  const [blockedAnimationCount, setBlockedAnimationCount] = createSignal(0);\n  const blockedAnimationCallbacks = new Set();\n\n  const [visibleItems, setVisibleItems] = createSignal(new Set<number>(), {equals: false});\n\n  // const scrollableSize = useElementSize(() => scrollable);\n\n  const sortedItems = createMemo(() => items().slice().sort((a, b) => sortWith(a.index, b.index)));\n  const itemsMap = createMemo(() => new Map([...pinnedItems(), ...items()].map(item => [item.id, item.value])));\n\n  const fullItems = createMemo(() => {\n    // if(!wasAtLeastOnceFetched()) return new Array((scrollableSize.height + itemSize - 1) / itemSize | 0).fill(null);\n\n    const realItems = [...pinnedItems(), ...sortedItems()];\n\n    return new Array(Math.max(totalCount() + pinnedItems().length, realItems.length))\n    .fill(null)\n    .map((_, idx) => realItems[idx] || null);\n  });\n\n  const itemsLength = createMemo(() => items().length);\n\n  createEffect(() => {\n    if(!wasAtLeastOnceFetched()) return;\n\n    itemsLength();\n    untrack(() => onListLengthChange?.());\n  });\n\n  createComputed(on(wasAtLeastOnceFetched, () => {\n    if(!wasAtLeastOnceFetched()) return;\n\n    setRevealIdx(items().length);\n  }));\n\n  // * Re-adding an id replaces the value behind it, so the previous one is dropped for good - unless\n  // * it is the very same object being re-added, which is the common no-op case\n  const replacedBy = (\n    previous: DeferredSortedVirtualListItem<T>[],\n    newItems: DeferredSortedVirtualListItem<T>[]\n  ) => {\n    const values = new Map(newItems.map(item => [item.id, item.value]));\n    return previous.filter(item => values.has(item.id) && values.get(item.id) !== item.value);\n  };\n\n  const addItems = (newItems: DeferredSortedVirtualListItem<T>[]) => {\n    if(!newItems.length) return;\n    const ids = new Set(newItems.map(item => item.id));\n    const replaced = replacedBy(items(), newItems);\n    setItems(prev => [\n      ...prev.filter(item => !ids.has(item.id)),\n      ...newItems\n    ]);\n    discard(replaced);\n  };\n\n  const addPinnedItems = (newItems: DeferredSortedVirtualListItem<T>[]) => {\n    if(!newItems.length) return;\n    const ids = new Set(newItems.map(item => item.id));\n    const replaced = replacedBy(pinnedItems(), newItems);\n    setPinnedItems(prev => [\n      ...prev.filter(item => !ids.has(item.id)),\n      ...newItems\n    ]);\n    discard(replaced);\n  };\n\n  /**\n   * Doesn't replace if already pinned\n   */\n  const ensurePinnedItems = (newItems: DeferredSortedVirtualListItem<T>[]) => {\n    if(!newItems.length) return;\n\n    setPinnedItems(prev => {\n      const ids = new Set(prev.map(item => item.id));\n      return [\n        ...prev,\n        ...newItems.filter(item => !ids.has(item.id))\n      ];\n    });\n  };\n\n  const discard = (discarded: DeferredSortedVirtualListItem<T>[]) => {\n    if(!onItemDiscard) return;\n    for(const item of discarded) onItemDiscard(item.value);\n  };\n\n  // * Both bail before writing when the id is not theirs: the setter would hand back a fresh array\n  // * either way, invalidating the signal and every memo over it (itemsMap, the rendered list) for a\n  // * removal that did not happen. delete() calls both on every key, so one of them always misses.\n  const removePinnedItem = (id: any) => {\n    const discarded = pinnedItems().filter(item => id === item.id);\n    if(!discarded.length) return false;\n\n    setPinnedItems(prev => prev.filter(item => id !== item.id));\n    discard(discarded);\n    return true;\n  };\n\n  // * Reports what it actually removed. It used to answer from itemsMap(), which merges the pinned\n  // * collection in, so a pinned id got a truthy answer from a call that removed nothing.\n  const removeItem = (id: any) => {\n    const discarded = items().filter(item => id === item.id);\n    if(!discarded.length) return false;\n\n    setItems(prev => prev.filter(item => id !== item.id));\n    discard(discarded);\n    return true;\n  };\n\n  const updateItem = (id: any, index: number) => {\n    setItems(prev => {\n      const foundItem = prev.find(item => item.id === id);\n      if(foundItem) foundItem.index = index; // we're not spreading here as we want to keep the same object reference for the animation to trigger\n      return [...prev];\n    });\n  };\n\n  const has = (id: any) => {\n    return itemsMap().has(id);\n  };\n\n  const get = (id: any) => {\n    return itemsMap().get(id);\n  };\n\n  const clear = () => {\n    const discarded = [...pinnedItems(), ...items()];\n    batch(() => {\n      setItems([]);\n      setPinnedItems([]);\n      setTotalCount(0);\n      setWasAtLeastOnceFetched(false);\n      setRevealIdx(Infinity);\n      blockedAnimationCallbacks.clear();\n      setBlockedAnimationCount(0);\n    });\n    discard(discarded);\n    // onListLengthChange?.();\n  };\n\n\n  let list: HTMLUListElement;\n\n  const InnerItem = (props: {id: any, value: T, top: number, animating: boolean}) => {\n    const element = createMemo(() => {\n      const element = getItemElement(props.value, props.id);\n      element?.classList.add(styles.Item);\n\n      onCleanup(() => {\n        onItemUnmount?.(props.value);\n      });\n\n      return element;\n    });\n\n    createRenderEffect(() => {\n      element()?.style.setProperty('top', props.top + 'px');\n    });\n\n    createEffect(() => {\n      if(props.animating)\n        element()?.style.setProperty('--background', /* 'red' */'var(--surface-color)');\n      else\n        element()?.style.removeProperty('--background');\n    });\n\n    return <>{element()}</>;\n  };\n\n  const [queuedToBeRevealed, setQueuedToBeRevealed] = createSignal<number[]>([]);\n\n  const nextRevealIdx = createMemo(() => getNextRevealIdx(queuedToBeRevealed()));\n\n\n  createEffect(() => {\n    const next = nextRevealIdx();\n\n    if(next === null) return;\n\n    const timeout = self.setTimeout(() => {\n      batch(() => {\n        setRevealIdx(prev => Math.max(next, prev));\n        setQueuedToBeRevealed(prev => prev.filter(n => next <= n));\n      });\n    }, 1000 / 60 / 2);\n\n    onCleanup(() => {\n      self.clearTimeout(timeout);\n    });\n  });\n\n\n  function checkShrink(visibleItems: Set<number>, itemsLength: number) {\n    const maxVisible = Math.max(0, ...Array.from(visibleItems.values()));\n\n    const toKeep = maxVisible - pinnedItems().length + EXTRA_ITEMS_TO_KEEP;\n\n    if(itemsLength > toKeep) {\n      // The trimmed tail is dropped for good - hand it to the owner before it goes out of reach\n      const discarded = sortedItems().slice(toKeep);\n      batch(() => {\n        // Should be sortedItems() here, because the updated cursor is based on the last item from the list, and might skip a few dialogs if wasn't set the right cursor\n        setItems(sortedItems().slice(0, toKeep));\n        setRevealIdx(toKeep);\n      });\n      discard(discarded);\n      onListShrinked();\n    }\n  }\n\n  function blockAnimation() {\n    setBlockedAnimationCount(prev => prev + 1);\n\n    const ref = {};\n    blockedAnimationCallbacks.add(ref);\n\n    return () => {\n      if(blockedAnimationCallbacks.has(ref)) {\n        blockedAnimationCallbacks.delete(ref);\n        setBlockedAnimationCount(prev => Math.max(0, prev - 1));\n      }\n    };\n  }\n\n  let shrinkTimeout: number;\n  let shrinkMovedSinceScheduled = false;\n\n  // Wait for a tick in which nothing moved before shrinking, so the list is never cut\n  // out from under a scroll that is still running. `visibleItems` is written on EVERY\n  // row mount and unmount, though, and re-arming the timer on each of those churned a\n  // clearTimeout + setTimeout pair per row; one pending timer that re-checks on each\n  // tick debounces exactly the same way for a fraction of the timer traffic.\n  const scheduleShrink = () => {\n    shrinkTimeout = self.setTimeout(() => {\n      if(shrinkMovedSinceScheduled) {\n        shrinkMovedSinceScheduled = false;\n        scheduleShrink();\n        return;\n      }\n\n      shrinkTimeout = undefined;\n      checkShrink(visibleItems(), itemsLength());\n    }, 0);\n  };\n\n  createEffect(on(visibleItems, () => {\n    if(shrinkTimeout !== undefined) {\n      shrinkMovedSinceScheduled = true;\n      return;\n    }\n\n    shrinkMovedSinceScheduled = false;\n    scheduleShrink();\n  }));\n\n  <VerticalVirtualList\n    ref={list}\n    itemHeight={itemSize}\n    list={fullItems()}\n    forceHostHeight={!wasAtLeastOnceFetched()}\n    animate={blockedAnimationCount() === 0}\n    ListItem={(props: VerticalVirtualListItemProps<DeferredSortedVirtualListItem<T> | null>) => {\n      const isRevealed = createMemo(() => props.idx < revealIdx());\n      const canShow = createMemo(() => props.item && isRevealed());\n\n      createEffect(() => {\n        if(!props.item || isRevealed()) return;\n\n        const idx = props.idx;\n\n        setQueuedToBeRevealed(prev => [...prev, idx]);\n\n        onCleanup(() => {\n          setQueuedToBeRevealed(prev => prev.filter(n => n !== idx));\n        });\n      });\n\n      createEffect(() => {\n        if(canShow()) return;\n\n        requestItemForIdx(props.idx - pinnedItems().length, items().length);\n      });\n\n      createComputed(() => {\n        const idx = props.idx;\n        setVisibleItems(prev => prev.add(idx));\n\n        onCleanup(() => {\n          setVisibleItems(prev => {\n            prev.delete(idx);\n            return prev;\n          });\n        });\n      });\n\n      return (\n        <Show\n          when={canShow()}\n          fallback={\n            <LoadingDialogSkeleton\n              class={styles.Item}\n              style={{top: props.top + 'px'}}\n              seed={props.idx}\n              size={itemSize}\n              noAvatar={noAvatar}\n            />\n          }\n        >\n          <InnerItem\n            id={props.item?.id}\n            value={props.item?.value}\n            top={props.top}\n            animating={props.animating}\n          />\n        </Show>\n      );\n    }}\n    scrollableHost={scrollable}\n    thresholdPadding={72 * 4}\n    extraPaddingBottom={extraPaddingBottom} // 0.5rem\n  />;\n\n  return {\n    dispose: () => {\n      const discarded = [...pinnedItems(), ...items()];\n      dispose();\n      discard(discarded);\n    },\n\n    list,\n\n    setTotalCount,\n\n    sortedItems,\n    itemsLength,\n    addItems,\n    addPinnedItems,\n    ensurePinnedItems,\n    removePinnedItem,\n    updateItem,\n    removeItem,\n    setWasAtLeastOnceFetched,\n\n    blockAnimation,\n\n    clear,\n    has,\n    get,\n    getAll: () => itemsMap()\n  }\n});\n","import {createMemo, Show} from 'solid-js';\nimport getLinkedCommunityId from '@appManagers/utils/communities/getLinkedCommunityId';\nimport {IconTsx} from '@components/iconTsx';\nimport {i18n} from '@lib/langPack';\nimport classNames from '@helpers/string/classNames';\nimport {usePeer} from '@stores/peers';\nimport styles from '@components/communities/communityDialog.module.scss';\n\nexport default function CommunityChildBadge(props: {\n  peerId: PeerId\n}) {\n  const peer = usePeer(() => props.peerId);\n  const communityId = createMemo(() => getLinkedCommunityId(peer()));\n  const openCommunity = (event: MouseEvent) => {\n    event.preventDefault();\n    event.stopPropagation();\n\n    const id = communityId();\n    if(id) {\n      void import('@lib/appDialogsManager').then(({default: manager}) => {\n        if(manager.forumTab?.peerId === props.peerId) {\n          return manager.toggleForumTab();\n        }\n\n        return manager.toggleForumTabByPeerId(\n          id.toPeerId(true),\n          true,\n          false\n        );\n      });\n    }\n  };\n\n  return (\n    <Show when={communityId()}>\n      <button\n        type=\"button\"\n        class={/* @once */ classNames(\n          styles.ChildBadge,\n          'dialog-avatar-corner-badge'\n        )}\n        data-dialog-list-action=\"true\"\n        aria-label={i18n('Community.Chats').textContent}\n        on:mousedown={(event) => event.stopPropagation()}\n        on:keydown={(event) => event.stopPropagation()}\n        on:click={openCommunity}\n      >\n        <span class={styles.ChildBadgeHitArea} aria-hidden=\"true\" />\n        <IconTsx icon=\"down\" />\n      </button>\n    </Show>\n  );\n}\n","import {createEffect, createRoot} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport createCommunityAvatarElement\nfrom '@components/communities/communityAvatarElement';\nimport CommunityChildBadge from '@components/communities/communityChildBadge';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {i18n} from '@lib/langPack';\nimport type {\n  AppDialogsManager,\n  DialogElement\n} from '@lib/appDialogsManager';\nimport formatNumber from '@helpers/number/formatNumber';\nimport getDialogMentionBadgeState from '@helpers/dialogMentionBadgeState';\nimport {\n  useCommunity,\n  useCommunityDialog\n} from '@stores/communities';\nimport styles from '@components/communities/communityDialog.module.scss';\n\nexport function createCommunityDialogListElement(\n  manager: Pick<AppDialogsManager, 'addDialogNew' | 'setLastMessageN'>,\n  communityId: ChatId\n): DialogElement {\n  const peerId = communityId.toPeerId(true);\n  const avatar = createCommunityAvatarElement(communityId, 54);\n  const dialogElement = manager.addDialogNew({\n    peerId,\n    avatarElement: avatar.element,\n    controlled: true,\n    dontSetActive: true,\n    fromName: apiManagerProxy.getChat(communityId)?.title || '',\n    isMainList: true,\n    rippleEnabled: false,\n    wrapOptions: {}\n  });\n  const {dom} = dialogElement;\n  dom.listEl.dataset.communityDialog = 'true';\n  dom.listEl.dataset.communityId = '' + communityId;\n  dialogElement.middlewareHelper.onDestroy(avatar.dispose);\n\n  const disposeState = createRoot((dispose) => {\n    const community = useCommunity(() => communityId);\n    const dialog = useCommunityDialog(() => communityId);\n    createEffect(() => {\n      void dialogElement.updateTitle(community()?.title || '');\n    });\n    createEffect(() => {\n      const value = dialog();\n      const latestDialog = value?.lastDialogs[0];\n      const lastMessage = latestDialog?.top_message ?\n        apiManagerProxy.getMessageByPeer(\n          latestDialog.peerId,\n          latestDialog.top_message\n        ) :\n        undefined;\n\n      delete dom.listEl.dataset.mid;\n      if(latestDialog) {\n        void manager.setLastMessageN({\n          dialog: latestDialog,\n          dialogElement,\n          lastMessage,\n          setMessageId: false,\n          subtitlePeerId: latestDialog.peerId\n        });\n      } else {\n        dom.setLastMessagePromise?.reject();\n        dom.lastMessageSpan.replaceChildren(i18n(\n          'Chats',\n          [value?.dialogs.length || 0]\n        ));\n        dom.lastTimeSpan.replaceChildren();\n      }\n\n      const unreadCount = value?.unreadCount || 0;\n      const unreadMarked = !!value?.unreadMarked;\n      const unread = unreadCount > 0 || unreadMarked;\n      const {\n        isMention: unreadMention,\n        hasMentionsBadge\n      } = getDialogMentionBadgeState({\n        unreadCount,\n        unreadMessagesCount: value?.unreadMessagesCount || 0,\n        unreadMentionsCount: value?.unreadMentionsCount || 0,\n        hasUnreadBadge: unread\n      });\n      const unreadText = !unread ? undefined :\n        unreadCount === 1 && unreadMarked ? '' :\n        unreadMention ? '@' : formatNumber(unreadCount, 1);\n      // the muted icon follows the Community's own notify settings, exactly like a\n      // forum row follows the forum's; an unmuted Community whose unread chats are\n      // all muted only grays the badge out, the way `no-unmuted-topic` does there\n      const muted = !!value?.muted;\n      dom.listEl.classList.toggle(\n        'no-unmuted-topic',\n        !muted && unread && !value?.unreadUnmutedCount\n      );\n      dialogElement.setBadgeState({\n        muted,\n        pinned: !!value?.pFlags.pinned,\n        unread,\n        unreadText,\n        unreadMention,\n        unreadAvatar: false,\n        mentions: hasMentionsBadge,\n        reactions: !!value?.unreadReactionsCount,\n        pollVotes: !!value?.unreadPollVotesCount,\n        transitionDuration: 0\n      });\n    });\n\n    return dispose;\n  });\n  dialogElement.middlewareHelper.onDestroy(disposeState);\n\n  return dialogElement;\n}\n\n// The badge sits on EVERY row of the main chat list, so its lifetime is tied to\n// the dialog element rather than to DOM connectedness: the virtual list detaches\n// and re-attaches rows on every scroll pass, and a custom element would tear the\n// reactive root down and rebuild it each time — ~20us per row per pass, ~93% of\n// the row's whole mount cost, paid by every user whether or not they are in a\n// single community.\nexport function attachCommunityChildBadge(\n  dialogElement: DialogElement,\n  peerId: PeerId\n) {\n  const host = document.createElement('div');\n  host.classList.add(styles.ChildBadgeHost);\n\n  const dispose = render(() => <CommunityChildBadge peerId={peerId} />, host);\n  dialogElement.middlewareHelper.onDestroy(dispose);\n\n  dialogElement.dom.listEl.append(host);\n}\n","import {batch, onCleanup} from 'solid-js';\nimport namedPromises from '@helpers/namedPromises';\nimport pickKeys from '@helpers/object/pickKeys';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {default as appDialogsManager, DialogElement} from '@lib/appDialogsManager';\nimport {AppManagers} from '@lib/managers';\nimport getDialogIndex from '@appManagers/utils/dialogs/getDialogIndex';\nimport getDialogIndexKey from '@appManagers/utils/dialogs/getDialogIndexKey';\nimport {logger} from '@lib/logger';\nimport {createDeferredSortedVirtualList, DeferredSortedVirtualListItem} from '@components/deferredSortedVirtualList';\nimport {LoadingDialogSkeletonSize} from '@components/loadingDialogSkeleton';\nimport Scrollable from '@components/scrollable';\nimport {attachCommunityChildBadge} from '@components/communities/communityDialog';\nimport rootScope from '@lib/rootScope';\n\nexport default class SortedDialogList {\n  private appDialogsManager: typeof appDialogsManager;\n  public managers: AppManagers;\n  public log: ReturnType<typeof logger>;\n  public list: HTMLElement;\n  public indexKey: ReturnType<typeof getDialogIndexKey>;\n  public onListLengthChange: () => void;\n  public virtualFilterId: PeerId;\n  public monoforumParentPeerId: PeerId;\n\n  private virtualList: ReturnType<typeof createDeferredSortedVirtualList<SortedDialogListItem>>;\n  private totalCount = 0;\n  private totalCountOffset = 0;\n\n  /**\n   * The custom emoji from the last message gets destroyed completely when removing the dialog\n   * element from the DOM, with no easy way of re-initializing them, so we need to forcefully\n   * re-initialize the last message\n   */\n  private unmountedDialogElements = new WeakMap<DialogElement, boolean>;\n\n  constructor(options: {\n    appDialogsManager: SortedDialogList['appDialogsManager'],\n    managers: SortedDialogList['managers'],\n    log?: SortedDialogList['log'],\n    indexKey: SortedDialogList['indexKey'],\n    onListLengthChange?: SortedDialogList['onListLengthChange'],\n    virtualFilterId?: SortedDialogList['virtualFilterId'],\n    monoforumParentPeerId?: SortedDialogList['monoforumParentPeerId'],\n\n    scrollable: Scrollable,\n    requestItemForIdx: (idx: number, itemsLength: number) => void,\n    onListShrinked: () => void,\n    itemSize: LoadingDialogSkeletonSize,\n    noAvatar?: boolean // For the loading skeleton placeholder,\n    extraPaddingBottom?: number\n  }) {\n    safeAssign(this, pickKeys(options, [\n      'appDialogsManager',\n      'managers',\n      'log',\n      'indexKey',\n      'virtualFilterId',\n      'monoforumParentPeerId',\n      'onListLengthChange'\n    ]));\n\n    this.virtualList = createDeferredSortedVirtualList({\n      scrollable: options.scrollable.container,\n      getItemElement: (item, key) => {\n        if(item.type === 'custom-pinned-dialog') {\n          return item.value.render();\n        }\n\n        if(item.type === 'custom-sorted-dialog') {\n          return item.value.render();\n        }\n\n        const dialogElement = item.value;\n\n        if(this.unmountedDialogElements.get(dialogElement)) {\n          const {options} = this.getDialogOptions(key);\n\n          /**\n           * Re-initing the dialog is pretty expensive on performance,\n           * so we wait a little bit before it, in case the user scrolls\n           * like crazy up and down\n           */\n          const timeout = self.setTimeout(() => {\n            this.appDialogsManager.initDialog(dialogElement, options)\n            .then(\n              () => {\n                this.unmountedDialogElements.delete(dialogElement);\n              },\n              () => {}\n            );\n          }, 200);\n\n          onCleanup(() => {\n            self.clearTimeout(timeout);\n          });\n        }\n\n        return dialogElement.dom.listEl;\n      },\n      // * A dropped DialogElement owns a middlewareHelper (getDialogOptions passes controlled: true),\n      // * and everything wrapped under it - the emoji status renderer, its lottie/video players, the\n      // * subtitle's custom emoji - is released only by that helper's destroy. The list used to drop\n      // * elements without it (removeItem, checkShrink's trimmed tail, clear, dispose), so every\n      // * trimmed row leaked its renderer, and the compositor worker kept its OffscreenCanvas forever.\n      // * Only 'dialog' items are ours to destroy: the custom ones are the caller's own objects,\n      // * handed in as the key, and may be re-added later.\n      onItemDiscard: (item) => {\n        if(item.type === 'dialog') {\n          this.unmountedDialogElements.delete(item.value);\n          item.value.destroy();\n        }\n      },\n      onItemUnmount: (item) => {\n        if(item.type === 'dialog') {\n          this.unmountedDialogElements.set(item.value, true);\n          // the nodes survive the unmount but their custom emoji do not, so the\n          // re-init below must rebuild the subtitle rather than recognize it as\n          // already rendered\n          delete item.value.dom.lastMessageRenderKey;\n        }\n      },\n      onListShrinked: options.onListShrinked,\n      requestItemForIdx: options.requestItemForIdx,\n      sortWith: (a, b) => b - a,\n      itemSize: options.itemSize,\n      noAvatar: options.noAvatar,\n      onListLengthChange: options.onListLengthChange,\n      extraPaddingBottom: options.extraPaddingBottom\n    });\n\n    this.list = this.virtualList.list;\n\n    this.list.classList.add('chatlist', 'virtual-chatlist');\n  }\n\n\n  public async getIndexForKey(key: any) {\n    if(key instanceof CustomPinnedDialog) return 0;\n    if(key instanceof CustomSortedDialog) {\n      return key.getIndex({\n        managers: this.managers,\n        indexKey: this.indexKey\n      });\n    }\n    if(key === this.monoforumParentPeerId) return 0;\n    if(key === this.virtualFilterId && key !== rootScope.myId) return 0;\n\n    if(this.monoforumParentPeerId) {\n      const dialog = await this.managers.monoforumDialogsStorage.getDialogByParent(this.monoforumParentPeerId, key);\n      return getDialogIndex(dialog);\n    }\n\n    return this.managers.dialogsStorage.getDialogIndex(\n      this.virtualFilterId ?? key,\n      this.indexKey,\n      this.virtualFilterId ? key : undefined\n    )\n  }\n\n  public async createItemForKey(key: any) {\n    const {index, value} = await namedPromises({\n      index: this.getIndexForKey(key),\n      value: this.createElementForKey(key)\n    });\n\n    return {id: key, index, value};\n  }\n\n  private getDialogOptions(key: any) {\n    const loadPromises: Promise<any>[] = [];\n\n    const options: Parameters<typeof appDialogsManager['addListDialog']>[0] = {\n      peerId: this.virtualFilterId ?? key,\n      loadPromises,\n      isBatch: true,\n      threadId: (this.virtualFilterId && key !== this.virtualFilterId) || rootScope.myId === this.virtualFilterId ? key : undefined,\n      isMainList: this.indexKey === 'index_0',\n      controlled: true,\n      monoforumParentPeerId: key !== this.monoforumParentPeerId ? this.monoforumParentPeerId : undefined,\n      asAllChats: this.getAsAllChats(key),\n      meAsSaved: !this.monoforumParentPeerId,\n      wrapOptions: undefined\n    };\n\n    return {options, loadPromises};\n  }\n\n  private getAsAllChats(key: any) {\n    if(\n      key instanceof CustomPinnedDialog ||\n      key instanceof CustomSortedDialog\n    ) return;\n    if(this.virtualFilterId === rootScope.myId) return;\n    return key === this.monoforumParentPeerId ? 'monoforum' : key === this.virtualFilterId ? 'topics' : undefined;\n  }\n\n  public async createElementForKey(key: any): Promise<SortedDialogListItem> {\n    if(key instanceof CustomPinnedDialog) return {\n      type: 'custom-pinned-dialog',\n      value: key\n    };\n\n    if(key instanceof CustomSortedDialog) return {\n      type: 'custom-sorted-dialog',\n      value: key\n    };\n\n    const {options, loadPromises} = this.getDialogOptions(key);\n\n    const autoDeletePeriod = await this.getDialogAutoDeletePeriod(key);\n    options.autoDeletePeriod = autoDeletePeriod;\n\n    const dialogElement = this.appDialogsManager.addListDialog(options);\n    if(\n      !this.virtualFilterId &&\n      !this.monoforumParentPeerId\n    ) {\n      attachCommunityChildBadge(dialogElement, key);\n    }\n\n    await Promise.all(loadPromises);\n\n    return {\n      type: 'dialog',\n      value: dialogElement\n    };\n  }\n\n  private async getDialogAutoDeletePeriod(key: any) {\n    if(\n      key instanceof CustomPinnedDialog ||\n      key instanceof CustomSortedDialog ||\n      this.virtualFilterId ||\n      this.monoforumParentPeerId\n    ) return;\n\n    const dialog = await this.managers.dialogsStorage.getDialogOnly(key);\n    if(!dialog) return;\n\n    return dialog.ttl_period || undefined;\n  }\n\n  public addDeferredItems(items: DeferredSortedVirtualListItem<SortedDialogListItem>[], totalCount: number) {\n    batch(() => {\n      this.totalCount = totalCount;\n      this.virtualList.setWasAtLeastOnceFetched(true);\n      this.virtualList.addItems(items);\n      this.updateTotalCount();\n    });\n  }\n\n  public async add(key: any, canFinish: () => boolean = () => true) {\n    const item = await this.createItemForKey(key);\n    if(!canFinish()) {\n      return;\n    }\n\n    this.virtualList.addItems([item]);\n    // this.virtualList.setTotalCount(prev => prev + 1);\n  }\n\n  public async addPinned(key: any) {\n    const item = await this.createItemForKey(key);\n    this.virtualList.addPinnedItems([item]);\n  }\n\n  public async ensurePinned(key: any) {\n    const item = await this.createItemForKey(key);\n    this.virtualList.ensurePinnedItems([item]);\n  }\n\n  public removePinned(key: any) {\n    this.virtualList.removePinnedItem(key);\n  }\n\n  public blockAnimation() {\n    return this.virtualList.blockAnimation();\n  }\n\n  public delete(key: any, adjustTotalCount = true) {\n    batch(() => {\n      // * Pinned entries live in their own collection, but every read API merges both - has(),\n      // * getDialogElement() and getAllDialogElementsMap() all see them - so callers routinely\n      // * discover a pinned key and delete it through here (validateListForFilter walks the merged\n      // * map; updateDialog gates on has()). Removing only from the unpinned side left the row on\n      // * screen, took the total count down for a row that never went away, and never reached\n      // * onItemDiscard, so the DialogElement kept its middlewareHelper - and everything under it -\n      // * until the tab was closed. Both sides, so delete means delete.\n      const removedPinned = this.virtualList.removePinnedItem(key);\n      const removedItem = this.virtualList.removeItem(key);\n      if((removedPinned || removedItem) && adjustTotalCount) {\n        this.adjustTotalCount(-1);\n      }\n    });\n  }\n\n  public adjustTotalCount(delta: number) {\n    this.totalCount = Math.max(0, this.totalCount + delta);\n    this.updateTotalCount();\n  }\n\n  public setTotalCountOffset(offset: number, totalCountDelta = 0) {\n    this.totalCount = Math.max(0, this.totalCount + totalCountDelta);\n    this.totalCountOffset = offset;\n    this.updateTotalCount();\n  }\n\n  private updateTotalCount() {\n    this.virtualList.setTotalCount(\n      Math.max(0, this.totalCount + this.totalCountOffset)\n    );\n  }\n\n  public has(key: any) {\n    return this.virtualList.has(key);\n  }\n\n  public getDialogElement(key: any) {\n    const item = this.virtualList.get(key);\n    if(item?.type === 'dialog') return item.value;\n  }\n\n  public getAllDialogElementsMap() {\n    const map = this.virtualList.getAll();\n\n    const filteredEntries = Array.from(map.entries())\n    .map(([key, value]) => value?.type === 'dialog' ? [key, value.value] as [any, DialogElement] : null)\n    .filter(Boolean);\n\n    return new Map(filteredEntries);\n  }\n\n  public getSortedItems() {\n    return this.virtualList.sortedItems();\n  }\n\n  public async update(key: any, canFinish: () => boolean = () => true) {\n    const index = await this.getIndexForKey(key);\n    if(!canFinish()) {\n      return;\n    }\n\n    this.virtualList.updateItem(key, index);\n  }\n\n  public itemsLength() {\n    return this.virtualList.itemsLength();\n  }\n\n  public clear() {\n    this.totalCount = 0;\n    this.totalCountOffset = 0;\n    this.virtualList?.clear();\n  }\n\n  public destroy() {\n    this.virtualList?.dispose();\n  }\n}\n\ninterface CustomPinnedDialogCtorArgs {\n  render: () => HTMLElement;\n};\n\nexport class CustomPinnedDialog {\n  render: () => HTMLElement;\n\n  constructor({render}: CustomPinnedDialogCtorArgs) {\n    this.render = render;\n  }\n}\n\ninterface CustomSortedDialogCtorArgs {\n  render: () => HTMLElement;\n  destroy?: () => void;\n  getIndex: (context: {\n    managers: AppManagers,\n    indexKey: ReturnType<typeof getDialogIndexKey>\n  }) => MaybePromise<number>;\n};\n\n// Unlike CustomPinnedDialog, this row takes part in the regular sorting, so it\n// has to keep the same element across virtual-list remounts.\nexport class CustomSortedDialog {\n  private element?: HTMLElement;\n  private destroyCallback?: () => void;\n  private renderCallback: () => HTMLElement;\n  getIndex: CustomSortedDialogCtorArgs['getIndex'];\n\n  constructor({render, destroy, getIndex}: CustomSortedDialogCtorArgs) {\n    this.renderCallback = render;\n    this.destroyCallback = destroy;\n    this.getIndex = getIndex;\n  }\n\n  public render = () => {\n    return this.element ||= this.renderCallback();\n  };\n\n  public getElement() {\n    return this.element;\n  }\n\n  public destroy() {\n    this.destroyCallback?.();\n    this.destroyCallback = undefined;\n    this.element = undefined;\n  }\n}\n\ntype SortedDialogListItem = {\n  type: 'custom-pinned-dialog',\n  value: CustomPinnedDialog;\n} | {\n  type: 'custom-sorted-dialog',\n  value: CustomSortedDialog;\n} | {\n  type: 'dialog',\n  value: DialogElement;\n}\n","import {createEffect, createRoot} from 'solid-js';\nimport {Dialog} from '@appManagers/appMessagesManager';\nimport {FOLDER_ID_ALL, FOLDER_ID_ARCHIVE, REAL_FOLDERS} from '@appManagers/constants';\nimport getLinkedCommunityId from '@appManagers/utils/communities/getLinkedCommunityId';\nimport isCollapsedCommunity from '@appManagers/utils/communities/isCollapsedCommunity';\nimport getDialogIndex from '@appManagers/utils/dialogs/getDialogIndex';\nimport getDialogIndexKey from '@appManagers/utils/dialogs/getDialogIndexKey';\nimport {isDialog, isForumTopic} from '@appManagers/utils/dialogs/isDialog';\nimport ArchiveDialog, {createArchiveDialogState, DisposableArchiveDialogState} from '@components/archiveDialog';\nimport {AutonomousDialogListBase, BaseConstructorArgs, LoadDialogsInnerArgs} from '@components/autonomousDialogList/base';\nimport {BADGE_TRANSITION_TIME} from '@components/autonomousDialogList/constants';\nimport groupCallActiveIcon from '@components/groupCallActiveIcon';\nimport Scrollable from '@components/scrollable';\nimport SetTransition from '@components/singleTransition';\nimport SortedDialogList, {\n  CustomPinnedDialog,\n  CustomSortedDialog\n} from '@components/sortedDialogList';\nimport {\n  createCommunityDialogListElement\n} from '@components/communities/communityDialog';\nimport IS_GROUP_CALL_SUPPORTED from '@environment/groupCallSupport';\nimport namedPromises from '@helpers/namedPromises';\nimport noop from '@helpers/noop';\nimport {Chat} from '@layer';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {AppDialogsManager, DialogDom} from '@lib/appDialogsManager';\nimport rootScope from '@lib/rootScope';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {runWithHotReloadGuard} from '@lib/solidjs/runWithHotReloadGuard';\nimport {useCommunityDialogs} from '@stores/communities';\nimport {usePeers} from '@stores/peers';\n\n\ntype ConstructorArgs = BaseConstructorArgs & {\n  filterId: number;\n};\n\ntype CommunityProjection = {\n  communityId: ChatId,\n  dialogs: Array<{\n    peerId: PeerId,\n    folderId: number,\n    filterIndex?: number\n  }>,\n  pinned: boolean,\n  pinnedOrderIndex: number,\n  pinnedOrderLength: number,\n  sortDate: number\n};\n\n// A hidden peer that only moves between folders shifts a real folder's count:\n// it leaves the count of the folder it came from and joins the one it went to.\n// Peers that appear or disappear from the projection are already accounted for\n// by the total-count offset, so they contribute nothing here.\nexport function getCommunityProjectionFolderCountDelta(\n  previousPeerFolderIds: ReadonlyMap<PeerId, number>,\n  nextPeerFolderIds: ReadonlyMap<PeerId, number>,\n  folderId: number\n) {\n  let delta = 0;\n  for(const [peerId, previousFolderId] of previousPeerFolderIds) {\n    const nextFolderId = nextPeerFolderIds.get(peerId);\n    if(\n      nextFolderId === undefined ||\n      nextFolderId === previousFolderId\n    ) {\n      continue;\n    }\n\n    if(previousFolderId === folderId) {\n      --delta;\n    }\n    if(nextFolderId === folderId) {\n      ++delta;\n    }\n  }\n\n  return delta;\n}\n\nexport class AutonomousDialogList extends AutonomousDialogListBase<Dialog> {\n  protected filterId: number;\n  private archiveDialogState?: DisposableArchiveDialogState;\n  private customPinnedDialog?: CustomPinnedDialog;\n  private communityProjectionDispose?: () => void;\n  private communityProjectionRows = new Map<ChatId, CustomSortedDialog>();\n  private communityProjectionSnapshot: CommunityProjection[] = [];\n  private communityProjectionPromise = Promise.resolve();\n  private communityProjectionGeneration = 0;\n  private projectedPeerIds = new Set<PeerId>();\n  private projectedPeerFolderIds = new Map<PeerId, number>();\n  private filterPinnedPeerIds = new Set<PeerId>();\n  private communityProjectionDestroyed = false;\n\n  constructor({filterId, ...args}: ConstructorArgs) {\n    super(args);\n\n    this.filterId = filterId;\n\n    if(filterId === FOLDER_ID_ALL) {\n      this.customPinnedDialog = new CustomPinnedDialog({\n        render: () => {\n          const element = new ArchiveDialog;\n          element.HotReloadGuard = SolidJSHotReloadGuardProvider;\n\n          element.feedProps({\n            state: this.archiveDialogState.state\n          });\n\n          return element;\n        }\n      });\n\n      this.archiveDialogState = runWithHotReloadGuard(() => createArchiveDialogState({\n        onHasArchiveDialogChanged: (hasDialogs) => {\n          this.onHasArchiveDialogChanged(hasDialogs);\n        }\n      }));\n    }\n\n    this.needPlaceholderAtFirstTime = true;\n\n    this.listenerSetter.add(rootScope)('peer_typings', async({peerId, typings}) => {\n      const [dialog, isForum] = await Promise.all([\n        this.managers.appMessagesManager.getDialogOnly(peerId),\n        this.managers.appPeersManager.isForum(peerId)\n      ]);\n\n      if(!dialog || isForum) return;\n\n      if(typings.length) {\n        this.setTyping(dialog);\n      } else {\n        this.unsetTyping(dialog);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('user_update', async(userId) => {\n      if(!this.isActive) {\n        return;\n      }\n\n      const peerId = userId.toPeerId();\n      const dom = this.getDialogDom(peerId);\n      if(!dom) {\n        return;\n      }\n\n      const status = await this.managers.appUsersManager.getUserStatus(userId);\n      const online = status?._ === 'userStatusOnline';\n      this.setOnlineStatus(dom.avatarEl.node, online);\n    });\n\n    this.listenerSetter.add(rootScope)('chat_update', async(chatId) => {\n      const peerId = chatId.toPeerId(true);\n      this.processDialogForCallStatus(peerId);\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_flush', ({dialog}) => {\n      if(!this.isActive || !dialog) {\n        return;\n      }\n\n      this.updateDialog(dialog);\n    });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      if(!this.isActive) {\n        return;\n      }\n\n      for(const [peerId, {dialog, topics}] of dialogs) {\n        if(!isDialog(dialog)) {\n          continue;\n        }\n\n        this.updateDialog(dialog);\n        this.appDialogsManager.processContact?.(peerId.toPeerId());\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(!this.isActive || !isDialog(dialog)) {\n        return;\n      }\n\n      const key = this.getDialogKey(dialog);\n      if(\n        REAL_FOLDERS.has(this.filterId) &&\n        this.projectedPeerIds.has(dialog.peerId) &&\n        !this.sortedList.has(key)\n      ) {\n        this.sortedList.adjustTotalCount(-1);\n      } else {\n        this.deleteDialogByKey(key);\n      }\n      this.appDialogsManager.processContact?.(dialog.peerId);\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_unread', ({dialog}) => {\n      if(!this.isActive || !isDialog(dialog)) {\n        return;\n      }\n\n      this.updateDialog(dialog);\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_notify_settings', (dialog) => {\n      if(!this.isActive || !isDialog(dialog)) {\n        return;\n      }\n\n      this.updateDialog(dialog);\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_draft', ({dialog, drop, peerId}) => {\n      if(!this.isActive || isForumTopic(dialog)) {\n        return;\n      }\n\n      if(drop) {\n        this.deleteDialog(dialog);\n      } else {\n        this.updateDialog(dialog);\n      }\n\n      this.appDialogsManager.processContact?.(peerId);\n    });\n\n    this.listenerSetter.add(rootScope)('filter_update', async(filter) => {\n      if(filter.id === this.filterId && !REAL_FOLDERS.has(filter.id)) {\n        this.filterPinnedPeerIds = new Set(filter.pinnedPeerIds);\n        await this.scheduleCommunityProjection();\n      }\n      if(this.isActive && filter.id === this.filterId && !REAL_FOLDERS.has(filter.id)) {\n        const dialogs = await this.managers.dialogsStorage.getCachedDialogs(true);\n        await this.validateListForFilter();\n        for(let i = 0, length = dialogs.length; i < length; ++i) {\n          const dialog = dialogs[i];\n          this.updateDialog(dialog);\n        }\n\n        if(this.appDialogsManager.filterId === this.filterId) {\n          this.appDialogsManager.fetchChatlistUpdates?.();\n        }\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('auto_delete_period_update', ({peerId, period}) => {\n      this.getDialogElement(peerId)?.dom?.avatarEl?.setAutoDeletePeriod(period);\n    });\n  }\n\n  private get isActive() {\n    return this.appDialogsManager.xd === this;\n  }\n\n  public getRectFromForPlaceholder() {\n    return this.filterId === FOLDER_ID_ARCHIVE ? this.appDialogsManager.chatsContainer : this.appDialogsManager.folders.container;\n  }\n\n  protected getFilterId() {\n    return this.filterId;\n  }\n\n  public setOnlineStatus(element: HTMLElement, online: boolean) {\n    const className = 'is-online';\n    const hasClassName = element.classList.contains(className);\n    !hasClassName && online && element.classList.add(className);\n    SetTransition({\n      element: element,\n      className: 'is-visible',\n      forwards: online,\n      duration: 250,\n      onTransitionEnd: online ? undefined : () => {\n        element.classList.remove(className);\n      },\n      useRafs: online && !hasClassName ? 2 : 0\n    });\n  }\n\n  public generateScrollable(filter: Parameters<AppDialogsManager['addFilter']>[0]) {\n    const filterId = filter.id;\n    const pinnedPeerIds = (\n      filter as typeof filter & {pinnedPeerIds?: PeerId[]}\n    ).pinnedPeerIds;\n    this.filterPinnedPeerIds = new Set(pinnedPeerIds || []);\n    const scrollable = new Scrollable(null, 'CL', 500);\n    scrollable.container.dataset.filterId = '' + filterId;\n\n    const indexKey = getDialogIndexKey(filter.localId);\n    const sortedDialogList = new SortedDialogList({\n      appDialogsManager: this.appDialogsManager,\n      managers: rootScope.managers,\n      log: this.log,\n      scrollable: scrollable,\n      indexKey,\n      requestItemForIdx: this.requestItemForIdx,\n      onListShrinked: this.onListShrinked,\n      itemSize: 72,\n      onListLengthChange: () => {\n        scrollable.onSizeChange();\n        this.appDialogsManager.onListLengthChange?.();\n      }\n    });\n\n\n    this.scrollable = scrollable;\n    this.sortedList = sortedDialogList;\n    this.setIndexKey(indexKey);\n    this.bindScrollable();\n    this.setupCommunityProjection();\n\n    // list.classList.add('hide');\n    // scrollable.container.style.backgroundColor = '#' + (Math.random() * (16 ** 6 - 1) | 0).toString(16);\n\n    return {scrollable, list: sortedDialogList.list};\n  }\n\n  public testDialogForFilter(dialog: Dialog) {\n    const collapsedCommunityId = this.getCollapsedCommunityId(dialog.peerId);\n    if(\n      collapsedCommunityId &&\n      (\n        REAL_FOLDERS.has(this.filterId) ||\n        !this.filterPinnedPeerIds.has(dialog.peerId)\n      )\n    ) {\n      return false;\n    }\n\n    if(!REAL_FOLDERS.has(this.filterId) ? getDialogIndex(dialog, this.indexKey) === undefined : this.filterId !== dialog.folder_id) {\n      return false;\n    }\n\n    return true;\n  }\n\n  protected async loadDialogsInner({offsetIndex, canFinish}: LoadDialogsInnerArgs) {\n    const isFirstLoad = !offsetIndex;\n\n    const unblock = isFirstLoad ? this.sortedList.blockAnimation() : noop;\n    try {\n      const {result} = await namedPromises({\n        result: super.loadDialogsInner({\n          offsetIndex,\n          removePlaceholder: false,\n          canFinish\n        }),\n        _ignore: this.ensureArchiveDialogHydrated()\n      });\n\n      await this.scheduleCommunityProjection();\n      this.placeholder?.detach(this.sortedList.itemsLength());\n\n      return {\n        ...result,\n        totalCount: this.sortedList.itemsLength()\n      };\n    } finally {\n      unblock();\n    }\n  }\n\n  private async ensureArchiveDialogHydrated() {\n    if(!this.archiveDialogState) return;\n\n    const promise = this.archiveDialogState.state.ensureHydrated();\n    if(!promise) {\n      await this.onHasArchiveDialogChanged(this.archiveDialogState.hasArchiveDialog());\n      return;\n    }\n\n    const ackedResult = await promise;\n    if(!ackedResult.cached) return;\n\n    return ackedResult.result;\n  }\n\n  private setupCommunityProjection() {\n    if(this.communityProjectionDispose) {\n      return;\n    }\n\n    this.communityProjectionDispose = createRoot((dispose) => {\n      const peers = usePeers();\n      const communityDialogs = useCommunityDialogs();\n\n      createEffect(() => {\n        const projection: CommunityProjection[] = [];\n        for(const id of Object.keys(communityDialogs)) {\n          const communityId = id.toChatId();\n          // read unconditionally: this runs in an effect, and short-circuiting past the\n          // peer would drop its subscription\n          const community = peers[communityId.toPeerId(true)];\n          const dialog = communityDialogs[communityId];\n          if(!dialog || !isCollapsedCommunity(community)) {\n            continue;\n          }\n\n          projection.push({\n            communityId,\n            dialogs: dialog.dialogs\n            .filter((dialog) => {\n              return dialog.migratedTo === undefined;\n            })\n            .map((dialog) => ({\n              peerId: dialog.peerId,\n              folderId: dialog.folder_id,\n              filterIndex: getDialogIndex(dialog, this.indexKey)\n            })),\n            pinned: !!dialog.pFlags.pinned,\n            pinnedOrderIndex: dialog.pinnedOrderIndex,\n            pinnedOrderLength: dialog.pinnedOrderLength,\n            sortDate: dialog.sortDate\n          });\n        }\n\n        this.communityProjectionSnapshot = projection;\n        void this.scheduleCommunityProjection().catch(noop);\n      });\n\n      return dispose;\n    });\n  }\n\n  private getCollapsedCommunityId(peerId: PeerId) {\n    const communityId = getLinkedCommunityId(apiManagerProxy.getPeer(peerId));\n    if(!communityId) {\n      return;\n    }\n\n    const communityDialog = apiManagerProxy.getCommunityDialog(communityId);\n    return communityDialog &&\n      isCollapsedCommunity(apiManagerProxy.getChat(communityId)) ?\n      communityId :\n      undefined;\n  }\n\n  private scheduleCommunityProjection() {\n    if(\n      this.communityProjectionDestroyed ||\n      !this.sortedList\n    ) {\n      return Promise.resolve();\n    }\n\n    const generation = this.communityProjectionGeneration;\n    const canFinish = () => {\n      return !this.communityProjectionDestroyed &&\n        generation === this.communityProjectionGeneration;\n    };\n    this.communityProjectionPromise = this.communityProjectionPromise\n    .catch(noop)\n    .then(async() => {\n      if(!canFinish()) {\n        return;\n      }\n\n      const unblock = this.sortedList.blockAnimation();\n      try {\n        await this.applyCommunityProjection(\n          this.communityProjectionSnapshot,\n          canFinish\n        );\n      } finally {\n        unblock();\n      }\n    });\n\n    return this.communityProjectionPromise;\n  }\n\n  private async applyCommunityProjection(\n    projection: CommunityProjection[],\n    canFinish: () => boolean\n  ) {\n    if(!canFinish()) {\n      return;\n    }\n\n    const hasCommunityRows = this.filterId === FOLDER_ID_ALL;\n    if(hasCommunityRows) {\n      const projectedCommunityIds = new Set(\n        projection.map(({communityId}) => communityId)\n      );\n      for(const [communityId, row] of this.communityProjectionRows) {\n        if(projectedCommunityIds.has(communityId)) {\n          continue;\n        }\n\n        this.sortedList.delete(row, false);\n        row.destroy();\n        this.communityProjectionRows.delete(communityId);\n      }\n    }\n\n    const hiddenPeerIds = new Set<PeerId>();\n    const peerFolderIds = new Map<PeerId, number>();\n    for(const item of projection) {\n      if(hasCommunityRows) {\n        let row = this.communityProjectionRows.get(item.communityId);\n        if(!row) {\n          row = this.createCommunityProjectionRow(item.communityId);\n          this.communityProjectionRows.set(item.communityId, row);\n        }\n\n        if(this.sortedList.has(row)) {\n          await this.sortedList.update(row, canFinish);\n        } else {\n          await this.sortedList.add(row, canFinish);\n        }\n        if(!canFinish()) {\n          return;\n        }\n      }\n\n      for(const {peerId, folderId, filterIndex} of item.dialogs) {\n        peerFolderIds.set(peerId, folderId);\n        const hiddenInFilter = REAL_FOLDERS.has(this.filterId) ?\n          folderId === this.filterId :\n          filterIndex !== undefined &&\n            !this.filterPinnedPeerIds.has(peerId);\n        if(!hiddenInFilter) {\n          continue;\n        }\n\n        hiddenPeerIds.add(peerId);\n        if(this.sortedList.has(peerId)) {\n          this.sortedList.delete(peerId, false);\n        }\n      }\n    }\n\n    for(const peerId of this.projectedPeerIds) {\n      if(hiddenPeerIds.has(peerId)) {\n        continue;\n      }\n\n      const dialog = await this.managers.appMessagesManager\n      .getDialogOnly(peerId);\n      if(!canFinish()) {\n        return;\n      }\n      if(\n        dialog &&\n        this.testDialogForFilter(dialog) &&\n        this.canUpdateDialog(dialog) &&\n        !this.sortedList.has(peerId)\n      ) {\n        await this.sortedList.add(peerId, canFinish);\n        if(!canFinish()) {\n          return;\n        }\n      }\n    }\n\n    const folderCountDelta = REAL_FOLDERS.has(this.filterId) ?\n      getCommunityProjectionFolderCountDelta(\n        this.projectedPeerFolderIds,\n        peerFolderIds,\n        this.filterId\n      ) :\n      0;\n    this.projectedPeerIds = hiddenPeerIds;\n    this.projectedPeerFolderIds = peerFolderIds;\n    // Community rows join the list, their hidden ordinary peers leave it.\n    const communityRowsCount = hasCommunityRows ? projection.length : 0;\n    this.sortedList.setTotalCountOffset(\n      communityRowsCount - hiddenPeerIds.size,\n      folderCountDelta\n    );\n  }\n\n  private createCommunityProjectionRow(communityId: ChatId) {\n    let dialogElement: ReturnType<typeof createCommunityDialogListElement>;\n    return new CustomSortedDialog({\n      render: () => {\n        dialogElement ||= createCommunityDialogListElement(\n          this.appDialogsManager,\n          communityId\n        );\n        const element = dialogElement.dom.listEl;\n        if(\n          this.appDialogsManager.forumTab?.peerId ===\n          communityId.toPeerId(true)\n        ) {\n          element.classList.add('is-forum-open');\n        }\n        return element;\n      },\n      destroy: () => dialogElement?.destroy(),\n      getIndex: () => {\n        const dialog = apiManagerProxy.getCommunityDialog(communityId);\n        if(!dialog) {\n          return 0;\n        }\n\n        if(!dialog.pFlags.pinned) {\n          return dialog.sortDate * 0x10000;\n        }\n\n        const reversePinnedIndex = dialog.pinnedOrderIndex === -1 ?\n          dialog.pinnedOrderLength :\n          dialog.pinnedOrderLength - 1 - dialog.pinnedOrderIndex;\n        const pinnedDate = 0x7fff0000 + (reversePinnedIndex & 0xFFFF);\n        return pinnedDate * 0x10000;\n      }\n    });\n  }\n\n  public getListElement(peerId: PeerId) {\n    const dialogElement = this.getDialogElement(peerId);\n    if(dialogElement) {\n      return dialogElement.dom.listEl;\n    }\n\n    return this.communityProjectionRows\n    .get(peerId.toChatId())\n    ?.getElement();\n  }\n\n  /**\n   * Удалит неподходящие чаты из списка, но не добавит их(!)\n   */\n  public async validateListForFilter() {\n    this.sortedList.getAllDialogElementsMap().forEach(async(_, key) => {\n      const dialog = await rootScope.managers.appMessagesManager.getDialogOnly(key);\n      if(!this.testDialogForFilter(dialog)) {\n        if(\n          REAL_FOLDERS.has(this.filterId) &&\n          this.getCollapsedCommunityId(dialog.peerId)\n        ) {\n          this.sortedList.delete(dialog.peerId, false);\n        } else {\n          this.deleteDialog(dialog);\n        }\n      }\n    });\n  }\n\n  public updateDialog(dialog: Dialog) {\n    const collapsedCommunityId = this.getCollapsedCommunityId(dialog.peerId);\n    if(\n      collapsedCommunityId &&\n      (\n        REAL_FOLDERS.has(this.filterId) ||\n        !this.filterPinnedPeerIds.has(dialog.peerId)\n      )\n    ) {\n      if(\n        REAL_FOLDERS.has(this.filterId) &&\n        this.sortedList.has(dialog.peerId)\n      ) {\n        this.sortedList.delete(dialog.peerId, false);\n      } else if(this.getDialogElement(dialog.peerId)) {\n        this.deleteDialog(dialog);\n      }\n      return;\n    }\n\n    if(!this.testDialogForFilter(dialog)) {\n      if(this.getDialogElement(dialog.peerId)) {\n        this.deleteDialog(dialog);\n      }\n\n      return;\n    }\n\n    return super.updateDialog(dialog);\n  }\n\n  public setCallStatus(dom: DialogDom, visible: boolean) {\n    let {callIcon, listEl} = dom;\n    if(!callIcon && visible) {\n      const {canvas, startAnimation} = dom.callIcon = callIcon = groupCallActiveIcon(listEl.classList.contains('active'));\n      canvas.classList.add('dialog-group-call-icon');\n      listEl.append(canvas);\n\n      listEl.classList.add('has-group-call-icon');\n      startAnimation();\n    }\n\n    if(!callIcon) {\n      return;\n    }\n\n    SetTransition({\n      element: dom.callIcon.canvas,\n      className: 'is-visible',\n      forwards: visible,\n      duration: BADGE_TRANSITION_TIME,\n      onTransitionEnd: visible ? undefined : () => {\n        dom.callIcon.canvas.remove();\n        dom.callIcon = undefined;\n        listEl.classList.remove('has-group-call-icon');\n      },\n      useRafs: visible ? 2 : 0\n    });\n  }\n\n  public processDialogForCallStatus(peerId: PeerId, dom?: DialogDom) {\n    if(!IS_GROUP_CALL_SUPPORTED) {\n      return;\n    }\n\n    if(!dom) dom = this.getDialogDom(peerId);\n    if(!dom) return;\n\n    const chat = apiManagerProxy.getChat(peerId.toChatId()) as Chat.chat | Chat.channel;\n    this.setCallStatus(dom, !!(chat.pFlags.call_active && chat.pFlags.call_not_empty));\n  }\n\n  protected onScrolledBottom() {\n    super.onScrolledBottom();\n\n    if(this.hasReachedTheEnd) {\n      this.appDialogsManager.loadContacts?.();\n    }\n  }\n\n  public toggleAvatarUnreadBadges(value: boolean, useRafs: number) {\n    if(!value) {\n      this.sortedList.getAllDialogElementsMap().forEach((dialogElement) => {\n        const {dom} = dialogElement;\n        if(!dom.unreadAvatarBadge) {\n          return;\n        }\n\n        dialogElement.toggleBadgeByKey('unreadAvatarBadge', false, false, false);\n      });\n\n      return;\n    }\n\n    const reuseClassNames = ['unread', 'mention'];\n    this.sortedList.getAllDialogElementsMap().forEach((dialogElement) => {\n      const {dom} = dialogElement;\n      const unreadContent = dom.unreadBadge?.textContent;\n      if(\n        !unreadContent ||\n        dom.unreadBadge.classList.contains('backwards') ||\n        dom.unreadBadge.classList.contains('dialog-pinned-icon')\n      ) {\n        return;\n      }\n\n      const isUnreadAvatarBadgeMounted = !!dom.unreadAvatarBadge;\n      dialogElement.createUnreadAvatarBadge();\n      dialogElement.toggleBadgeByKey('unreadAvatarBadge', true, isUnreadAvatarBadgeMounted);\n      dom.unreadAvatarBadge.textContent = unreadContent;\n      const unreadAvatarBadgeClassList = dom.unreadAvatarBadge.classList;\n      const unreadBadgeClassList = dom.unreadBadge.classList;\n      reuseClassNames.forEach((className) => {\n        unreadAvatarBadgeClassList.toggle(className, unreadBadgeClassList.contains(className));\n      });\n    });\n  }\n\n  public getDialogKey(dialog: Dialog) {\n    return dialog.peerId;\n  }\n\n  public getDialogKeyFromElement(element: HTMLElement) {\n    return +element.dataset.peerId;\n  }\n\n  public getDialogFromElement(element: HTMLElement) {\n    return rootScope.managers.appMessagesManager.getDialogOnly(element.dataset.peerId.toPeerId());\n  }\n\n  protected canUpdateDialog(dialog: Dialog): boolean {\n    if(dialog.migratedTo !== undefined || !this.testDialogForFilter(dialog)) return false;\n    return super.canUpdateDialog(dialog);\n  }\n\n  private async onHasArchiveDialogChanged(hasArchiveDialog: boolean) {\n    if(!this.customPinnedDialog || !this.archiveDialogState) return;\n\n    if(hasArchiveDialog) {\n      await this.sortedList.ensurePinned(this.customPinnedDialog);\n    } else {\n      this.sortedList.removePinned(this.customPinnedDialog);\n    }\n  }\n\n  public clear(): void {\n    ++this.communityProjectionGeneration;\n    this.communityProjectionPromise = Promise.resolve();\n    for(const row of this.communityProjectionRows.values()) {\n      row.destroy();\n    }\n    this.communityProjectionRows.clear();\n    this.projectedPeerIds.clear();\n    this.projectedPeerFolderIds.clear();\n    super.clear();\n  }\n\n  public destroy(): void {\n    this.communityProjectionDestroyed = true;\n    this.communityProjectionDispose?.();\n    this.communityProjectionDispose = undefined;\n    super.destroy();\n    this.archiveDialogState?.dispose();\n  }\n}\n","type RegisterEntry<ToCheck, Payload> = {\n  check: (value: ToCheck) => boolean;\n  payload: Payload;\n};\n\nexport class Register<ToCheck, Payload> {\n  private entries: RegisterEntry<ToCheck, Payload>[] = [];\n\n  addEntry(entry: RegisterEntry<ToCheck, Payload>): void {\n    this.entries.push(entry);\n  }\n\n  hasEntryFor(value: ToCheck): boolean {\n    return this.entries.some(entry => entry.check(value));\n  }\n\n  getEntry(value: ToCheck): Payload | undefined {\n    for(const entry of this.entries) {\n      if(entry.check(value)) {\n        return entry.payload;\n      }\n    }\n  }\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport handleTabSwipe from '@helpers/dom/handleTabSwipe';\nimport liteMode from '@helpers/liteMode';\nimport safeAssign from '@helpers/object/safeAssign';\nimport pause from '@helpers/schedulers/pause';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {AppManagers} from '@lib/managers';\nimport {logger} from '@lib/logger';\nimport {AutonomousDialogListBase} from '@components/autonomousDialogList/base';\nimport ButtonIcon from '@components/buttonIcon';\nimport Icon from '@components/icon';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {MAX_SIDEBAR_WIDTH} from '@helpers/updateColumnWidths';\nimport SetTransition from '@components/singleTransition';\nimport {SliderSuperTabEventable} from '@components/sliderTab';\nimport {Register} from '@components/forumTab/register';\nimport rootScope from '@lib/rootScope';\nimport {isDialog} from '@lib/appManagers/utils/dialogs/isDialog';\n\n\nexport class ForumTab extends SliderSuperTabEventable {\n  public static register: Register<PeerId, typeof ForumTab> = new Register;\n\n\n  public rows: HTMLElement;\n  public subtitle: HTMLElement;\n  public headerAvatar: HTMLElement;\n\n  public peerId: PeerId;\n  private firstTime: boolean;\n\n  protected log: ReturnType<typeof logger>;\n\n  public xd?: AutonomousDialogListBase;\n\n  public async toggle(value: boolean) {\n    if(this.triggerAsyncInit) {\n      await this.triggerAsyncInit();\n    }\n\n    SetTransition({\n      element: this.container,\n      className: 'is-visible',\n      forwards: value,\n      duration: 300,\n      onTransitionEnd: !value ? () => {\n        this.onCloseAfterTimeout();\n      } : undefined,\n      useRafs: this.firstTime ? (this.firstTime = undefined, 2) : undefined\n    });\n  }\n\n  protected _close = () => {\n    if(!this.slider) {\n      appDialogsManager.toggleForumTab(undefined, this);\n    } else {\n      this.close();\n    }\n  };\n\n  protected syncInit(): void {\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(isDialog(dialog) && this.peerId === dialog.peerId) {\n        this._close();\n      }\n    });\n  }\n\n  protected async asyncInit(): Promise<void> {\n    this.xd?.onChatsScroll();\n  }\n\n  protected async onSearchClick() {\n    appSidebarLeft.closeEverythingInside();\n    if(liteMode.isAvailable('animations')) await pause(400);\n    appSidebarLeft.initSearch().openWithPeerId(this.peerId);\n  }\n\n  public init(options: {\n    peerId: PeerId,\n    managers: AppManagers\n  }) {\n    safeAssign(this, options);\n\n    this.log = logger('FORUM');\n    this.firstTime = true;\n    this.container.classList.add('topics-container');\n\n    const isFloating = !this.slider;\n    if(isFloating) {\n      this.closeBtn.replaceChildren(Icon('close'));\n      this.container.classList.add('active', 'is-floating');\n\n      attachClickEvent(this.closeBtn, this._close, {listenerSetter: this.listenerSetter});\n    }\n\n    this.rows = document.createElement('div');\n    this.rows.classList.add('sidebar-header__rows');\n\n    this.subtitle = document.createElement('div');\n    this.subtitle.classList.add('sidebar-header__subtitle');\n\n    this.title.replaceWith(this.rows);\n    this.rows.append(this.title, this.subtitle);\n\n    if(IS_TOUCH_SUPPORTED) {\n      handleTabSwipe({\n        element: this.container,\n        onSwipe: this._close,\n        middleware: this.middlewareHelper.get()\n      });\n    }\n\n    const searchButton = ButtonIcon('search');\n    attachClickEvent(searchButton, () => this.onSearchClick());\n\n    this.header.append(searchButton);\n\n    this.syncInit();\n\n    if(this.xd) {\n      this.xd.getRectFromForPlaceholder = this.getRectFromForPlaceholder;\n    }\n\n    if(!isFloating) {\n      return this.triggerAsyncInit();\n    }\n  }\n\n  // an avatar slot in front of the header rows, for tabs that want one\n  protected createHeaderAvatar() {\n    const avatar = document.createElement('div');\n    avatar.classList.add('sidebar-header__avatar');\n    this.rows.before(avatar);\n    return this.headerAvatar = avatar;\n  }\n\n  protected getRectFromForPlaceholder = () => {\n    const isFloating = !this.slider;\n\n    return (): DOMRectEditable => {\n      const sidebarRect = appSidebarLeft.rect;\n      const paddingY = 56;\n      const paddingX = isFloating ? 80 : 0;\n      const isCollapsed = appSidebarLeft.isCollapsed();\n      const originalWidth = isCollapsed ? MAX_SIDEBAR_WIDTH : sidebarRect.width;\n      const width = isFloating ? originalWidth - paddingX : originalWidth;\n\n      return {\n        top: paddingY,\n        right: sidebarRect.right,\n        bottom: 0,\n        left: paddingX,\n        width,\n        height: sidebarRect.height - paddingY\n      };\n    };\n  }\n\n  public async triggerAsyncInit() {\n    this.triggerAsyncInit = undefined;\n\n    return this.asyncInit();\n  }\n\n  public onCloseAfterTimeout() {\n    super.onCloseAfterTimeout();\n    this.xd?.destroy();\n  }\n}\n","import {ForumTab} from '@components/forumTab/forumTab';\n\nexport default function findForumTabByPeerId(\n  history: readonly unknown[],\n  peerId: PeerId\n) {\n  return history.find((tab) => {\n    return tab instanceof ForumTab && tab.peerId === peerId;\n  }) as ForumTab | undefined;\n}\n","export const USE_COMMUNITY_NAVIGATION_TAB = true;\n\nexport default function shouldOpenForumAsNavigationTab(options: {\n  hasNavigationHistory: boolean,\n  isCommunity: boolean,\n  isNarrowScreen: boolean,\n  useCommunityNavigationTab?: boolean\n}) {\n  return options.hasNavigationHistory || (\n    options.isCommunity &&\n    (\n      (options.useCommunityNavigationTab ??\n        USE_COMMUNITY_NAVIGATION_TAB) ||\n      options.isNarrowScreen\n    )\n  );\n}\n","import {ForumTopic} from '@appManagers/appMessagesManager';\nimport {isDialog, isForumTopic} from '@appManagers/utils/dialogs/isDialog';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousDialogListBase, BaseConstructorArgs} from '@components/autonomousDialogList/base';\n\n\ntype ConstructorArgs = BaseConstructorArgs & {\n  peerId: PeerId;\n};\n\nexport class AutonomousBotforumTopicList extends AutonomousDialogListBase<ForumTopic> {\n  public peerId: PeerId;\n\n  constructor({peerId, ...args}: ConstructorArgs) {\n    super(args);\n\n    this.peerId = peerId;\n\n    this.placeholderOptions = {\n      avatarSize: 0,\n      marginVertical: 5,\n      totalHeight: 64\n    };\n\n    this.listenerSetter.add(rootScope)('peer_typings', async({peerId, threadId, typings}) => {\n      if(!threadId || this.peerId !== peerId) {\n        return;\n      }\n\n      const dialog = await this.managers.dialogsStorage.getForumTopic(peerId, threadId);\n\n      if(!dialog) return;\n\n      if(typings.length) {\n        this.setTyping(dialog);\n      } else {\n        this.unsetTyping(dialog);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      for(const [peerId, {topics}] of dialogs) {\n        if(peerId !== this.peerId || !topics?.size) {\n          continue;\n        }\n\n        topics.forEach((forumTopic) => {\n          this.updateDialog(forumTopic);\n        });\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_unread', ({dialog}) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      this.appDialogsManager.setUnreadMessagesN({dialog, dialogElement: this.getDialogElement(this.getDialogKey(dialog))});\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      this.deleteDialogByKey(this.getDialogKey(dialog));\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_draft', ({dialog, drop}) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      if(drop) {\n        this.deleteDialog(dialog);\n      } else {\n        this.updateDialog(dialog);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_notify_settings', async(dialog) => {\n      if(dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      if(isDialog(dialog)) {\n        const all = this.sortedList.getAllDialogElementsMap();\n        const entries = [...all.entries()];\n        const promises = entries.map(([id]) => this.managers.dialogsStorage.getForumTopic(this.peerId, id));\n        const topics = await Promise.all(promises);\n        entries.forEach(([id, element], idx) => {\n          this.appDialogsManager.setUnreadMessagesN({dialog: topics[idx], dialogElement: element}); // возможно это не нужно, но нужно менять is-muted\n        });\n\n        return;\n      }\n\n      this.appDialogsManager.setUnreadMessagesN({dialog, dialogElement: this.getDialogElement(this.getDialogKey(dialog))}); // возможно это не нужно, но нужно менять is-muted\n    });\n  }\n\n  public getDialogKey(dialog: ForumTopic) {\n    return dialog.id;\n  }\n\n  public getDialogKeyFromElement(element: HTMLElement) {\n    return +element.dataset.threadId;\n  }\n\n  public getDialogFromElement(element: HTMLElement) {\n    return this.managers.dialogsStorage.getForumTopic(+element.dataset.peerId, +element.dataset.threadId);\n  }\n\n  protected getFilterId() {\n    return this.peerId;\n  }\n\n  protected canUpdateDialog(dialog: ForumTopic): boolean {\n    if(dialog.pFlags.hidden) return false;\n    return super.canUpdateDialog(dialog);\n  }\n}\n","import middlewarePromise from '@helpers/middlewarePromise';\nimport namedPromises from '@helpers/namedPromises';\nimport asyncThrottle from '@helpers/schedulers/asyncThrottle';\nimport {Chat, Dialog} from '@layer';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {isDialog} from '@appManagers/utils/dialogs/isDialog';\nimport {i18n} from '@lib/langPack';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousBotforumTopicList} from '@components/autonomousDialogList/botforumTopics';\nimport SortedDialogList from '@components/sortedDialogList';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {ForumTab} from '@components/forumTab/forumTab';\n\n\nexport class BotforumTab extends ForumTab {\n  private dialogsCountI18nEl: HTMLElement;\n\n  syncInit(): void {\n    super.syncInit();\n\n    this.middlewareHelper.get().onClean(() => {\n      this.updateDialogsCount.clear();\n    });\n\n    this.container.classList.add('topic-dialogs-override');\n\n    const autonomousList = new AutonomousBotforumTopicList({peerId: this.peerId, appDialogsManager});\n    autonomousList.scrollable = this.scrollable;\n\n    const sortedList = autonomousList.sortedList = new SortedDialogList({\n      itemSize: 64,\n      noAvatar: true,\n      appDialogsManager,\n      scrollable: this.scrollable,\n      managers: rootScope.managers,\n      requestItemForIdx: autonomousList.requestItemForIdx,\n      onListShrinked: autonomousList.onListShrinked,\n      indexKey: 'index_0',\n      virtualFilterId: this.peerId\n    });\n\n    sortedList.addPinned(this.peerId);\n\n    const list = autonomousList.sortedList.list;\n    autonomousList.bindScrollable();\n\n    this.xd = autonomousList;\n\n    appDialogsManager.setListClickListener({list, onFound: null, withContext: true});\n    this.scrollable.append(list);\n\n\n    this.listenerSetter.add(rootScope)('history_reload', (peerId) => {\n      if(this.peerId !== peerId) {\n        return;\n      }\n\n      this.xd.fullReset();\n    });\n\n    this.listenerSetter.add(rootScope)('user_update', (userId) => {\n      if(this.peerId !== userId.toPeerId()) {\n        return;\n      }\n\n      const user = apiManagerProxy.getUser(userId);\n      if(user?._ === 'user' && !user?.pFlags?.bot_forum_view) {\n        appDialogsManager.toggleForumTab(undefined, this);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      for(const [peerId, {dialog, topics}] of dialogs) {\n        if(isDialog(dialog) && dialog.peerId === this.peerId) {\n          this.updateAllChatsDialog(dialog);\n        }\n        if(peerId === this.peerId && topics?.size) {\n          this.updateDialogsCount();\n        }\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(this.peerId !== dialog.peerId) return;\n      this.updateDialogsCount();\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_draft', ({dialog}) => {\n      if(!isDialog(dialog) || dialog.peerId !== this.peerId) return;\n      this.updateAllChatsDialog(dialog);\n    });\n  }\n\n  private updateAllChatsDialog(dialog: Dialog.dialog) {\n    const dialogElement = this.xd.getDialogElement(this.peerId);\n    if(!dialogElement) {\n      return;\n    }\n\n    appDialogsManager.setLastMessageN({\n      dialog,\n      dialogElement,\n      setUnread: true\n    });\n  }\n\n  async asyncInit(): Promise<void> {\n    await super.asyncInit();\n\n    const middleware = this.middlewareHelper.get();\n    const peerId = this.peerId;\n\n    const wrapPromiseWithMiddleware = middlewarePromise(middleware);\n\n    try {\n      const {peerTitle, dialogs} = await wrapPromiseWithMiddleware(namedPromises({\n        peerTitle: wrapPeerTitle({\n          peerId,\n          withIcons: true,\n          dialog: true,\n          wrapOptions: {middleware}\n        }),\n        dialogs: this.managers.dialogsStorage.getDialogs({\n          filterId: this.peerId,\n          limit: 1\n        })\n      }));\n\n      this.title.append(peerTitle);\n      this.subtitle.append(this.dialogsCountI18nEl = this.getTopicsCountI18n(dialogs ? dialogs.count : null));\n    } catch{}\n  }\n\n  private getTopicsCountI18n(count: number | null) {\n    if(count === 0) {\n      return i18n('NoTopics');\n    }\n\n    return i18n('TopicsCount', [count ? count + '' : '~']);\n  }\n\n  private updateDialogsCount = asyncThrottle(async() => {\n    if(!this.dialogsCountI18nEl) return;\n    const {count} = await this.managers.dialogsStorage.getDialogs({filterId: this.peerId, limit: 1});\n    this.dialogsCountI18nEl.replaceWith(this.dialogsCountI18nEl = this.getTopicsCountI18n(count));\n  }, 0);\n}\n","import {ForumTopic} from '@appManagers/appMessagesManager';\nimport {isDialog, isForumTopic} from '@appManagers/utils/dialogs/isDialog';\nimport {CAN_HIDE_TOPIC} from '@appManagers/constants';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousDialogListBase, BaseConstructorArgs} from '@components/autonomousDialogList/base';\n\n\ntype ConstructorArgs = BaseConstructorArgs & {\n  peerId: PeerId;\n};\n\nexport class AutonomousForumTopicList extends AutonomousDialogListBase<ForumTopic> {\n  public peerId: PeerId;\n\n  constructor({peerId, ...args}: ConstructorArgs) {\n    super(args);\n\n    this.peerId = peerId;\n\n    this.skipMigrated = !!CAN_HIDE_TOPIC;\n\n    this.placeholderOptions = {\n      avatarSize: 0,\n      marginVertical: 5,\n      totalHeight: 64\n    };\n\n    this.listenerSetter.add(rootScope)('peer_typings', async({peerId, threadId, typings}) => {\n      if(!threadId || this.peerId !== peerId) {\n        return;\n      }\n\n      const dialog = await this.managers.dialogsStorage.getForumTopic(peerId, threadId);\n\n      if(!dialog) return;\n\n      if(typings.length) {\n        this.setTyping(dialog);\n      } else {\n        this.unsetTyping(dialog);\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      for(const [peerId, {topics}] of dialogs) {\n        if(peerId !== this.peerId || !topics?.size) {\n          continue;\n        }\n\n        topics.forEach((forumTopic) => {\n          this.updateDialog(forumTopic);\n        });\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_unread', ({dialog}) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      this.appDialogsManager.setUnreadMessagesN({dialog, dialogElement: this.getDialogElement(this.getDialogKey(dialog))});\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_notify_settings', async(dialog) => {\n      if(dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      if(isDialog(dialog)) {\n        const all = this.sortedList.getAllDialogElementsMap();\n        const entries = [...all.entries()];\n        const promises = entries.map(([id]) => this.managers.dialogsStorage.getForumTopic(this.peerId, id));\n        const topics = await Promise.all(promises);\n        entries.forEach(([id, element], idx) => {\n          this.appDialogsManager.setUnreadMessagesN({dialog: topics[idx], dialogElement: element}); // возможно это не нужно, но нужно менять is-muted\n        });\n\n        return;\n      }\n\n      this.appDialogsManager.setUnreadMessagesN({dialog, dialogElement: this.getDialogElement(this.getDialogKey(dialog))}); // возможно это не нужно, но нужно менять is-muted\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      this.deleteDialogByKey(this.getDialogKey(dialog));\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_draft', ({dialog, drop}) => {\n      if(!isForumTopic(dialog) || dialog.peerId !== this.peerId) {\n        return;\n      }\n\n      if(drop) {\n        this.deleteDialog(dialog);\n      } else {\n        this.updateDialog(dialog);\n      }\n    });\n  }\n\n  public getDialogKey(dialog: ForumTopic) {\n    return dialog.id;\n  }\n\n  public getDialogKeyFromElement(element: HTMLElement) {\n    return +element.dataset.threadId;\n  }\n\n  public getDialogFromElement(element: HTMLElement) {\n    return this.managers.dialogsStorage.getForumTopic(+element.dataset.peerId, +element.dataset.threadId);\n  }\n\n  protected getFilterId() {\n    return this.peerId;\n  }\n\n  protected canUpdateDialog(dialog: ForumTopic): boolean {\n    if(dialog.pFlags.hidden) return false;\n    return super.canUpdateDialog(dialog);\n  }\n}\n","import type {Chat} from '@layer';\nimport getChatMembershipAction, {\n  type ChatMembershipAction\n} from '@appManagers/utils/chats/getChatMembershipAction';\n\n\nexport default function getGroupForumMembershipAction(\n  chat: Chat | undefined\n): ChatMembershipAction | undefined {\n  if(chat?._ !== 'channel' || !chat.pFlags.forum) {\n    return;\n  }\n\n  return getChatMembershipAction(chat);\n}\n","import {Chat} from '@layer';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport appImManager, {AppImManager} from '@lib/appImManager';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousForumTopicList} from '@components/autonomousDialogList/forumTopics';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport {ChatType} from '@components/chat/chatType';\nimport PopupElement from '@components/popups';\nimport PopupDeleteDialog from '@components/popups/deleteDialog';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {AppEditTopicTab} from '@components/solidJsTabs/tabs';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport SortedDialogList from '@components/sortedDialogList';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {ForumTab} from '@components/forumTab/forumTab';\nimport getGroupForumMembershipAction\nfrom '@components/forumTab/getGroupForumMembershipAction';\nimport joinChat from '@components/chat/joinChat';\nimport {toastNew} from '@components/toast';\n\n\nexport class GroupForumTab extends ForumTab {\n  syncInit(): void {\n    super.syncInit();\n\n    this.container.classList.add('topic-dialogs-override');\n\n    this.xd = new AutonomousForumTopicList({peerId: this.peerId, appDialogsManager});\n    this.xd.scrollable = this.scrollable;\n    this.xd.sortedList = new SortedDialogList({\n      itemSize: 64,\n      noAvatar: true,\n      appDialogsManager,\n      scrollable: this.scrollable,\n      managers: this.managers,\n      log: this.log,\n      requestItemForIdx: this.xd.requestItemForIdx,\n      onListShrinked: this.xd.onListShrinked,\n      indexKey: 'index_0',\n      virtualFilterId: this.peerId\n    });\n\n    const list = this.xd.sortedList.list;\n    appDialogsManager.setListClickListener({list, onFound: null, withContext: true});\n    this.scrollable.append(list);\n    this.xd.bindScrollable();\n\n    const getMembershipAction = () => {\n      return getGroupForumMembershipAction(\n        apiManagerProxy.getChat(this.peerId.toChatId())\n      );\n    };\n\n    let joining = false;\n    const join = async() => {\n      if(joining) {\n        return;\n      }\n\n      joining = true;\n      try {\n        await joinChat({\n          peerId: this.peerId,\n          managers: this.managers,\n          appImManager\n        });\n      } catch(error) {\n        console.error('join forum error', error);\n        toastNew({langPackKey: 'Error.AnError'});\n      } finally {\n        joining = false;\n      }\n    };\n\n    const btnMenu = ButtonMenuToggle({\n      listenerSetter: this.listenerSetter,\n      direction: 'bottom-left',\n      buttons: [{\n        icon: 'add',\n        text: 'ForumTopic.Context.New',\n        onClick: () => {\n          appSidebarLeft.createTab(AppEditTopicTab).open({peerId: this.peerId});\n        },\n        separatorDown: true,\n        verify: () => this.managers.appChatsManager.hasRights(this.peerId.toChatId(), 'manage_topics')\n      }, {\n        icon: 'info',\n        text: 'ForumTopic.Context.Info',\n        onClick: () => {\n          AppSharedMediaTab.open(appSidebarLeft, this.peerId);\n        }\n      }, {\n        icon: 'message',\n        text: 'ForumTopic.Context.ShowAsMessages',\n        onClick: this.viewAsMessages,\n        verify: () => {\n          const chat = appImManager.chat;\n          return !chat || !appImManager.isSamePeer(chat, this.getOptionsForMessages());\n        }\n      }, {\n        icon: 'adduser',\n        text: 'ForumTopic.Context.AddMember',\n        onClick: () => {},\n        verify: () => false && this.managers.appChatsManager.hasRights(this.peerId.toChatId(), 'invite_users')\n      }, {\n        icon: 'logout',\n        danger: true,\n        text: 'LeaveMegaMenu',\n        onClick: () => {\n          PopupElement.createPopup(PopupDeleteDialog, this.peerId, undefined, (promise) => {\n            this._close();\n          });\n        },\n        separator: true,\n        verify: () => getMembershipAction() === 'leave'\n      }, {\n        icon: 'adduser',\n        text: 'JoinByPeekGroupTitle',\n        onClick: join,\n        separator: true,\n        verify: () => !joining && getMembershipAction() === 'join'\n      }, {\n        icon: 'adduser',\n        text: 'ForumTopic.Context.ApplyToJoin',\n        onClick: join,\n        separator: true,\n        verify: () => !joining && getMembershipAction() === 'request'\n      }]\n    });\n\n    this.listenerSetter.add(rootScope)('history_reload', (peerId) => {\n      if(this.peerId !== peerId) {\n        return;\n      }\n\n      this.xd.fullReset();\n    });\n\n    this.listenerSetter.add(rootScope)('chat_update', (chatId) => {\n      if(this.peerId !== chatId.toPeerId(true)) {\n        return;\n      }\n\n      const chat = apiManagerProxy.getChat(chatId);\n      if(!(chat as Chat.channel).pFlags.forum) {\n        appDialogsManager.toggleForumTab(undefined, this);\n      }\n    });\n\n    this.header.append(btnMenu);\n  }\n\n  async asyncInit(): Promise<void> {\n    await super.asyncInit();\n\n    const middleware = this.middlewareHelper.get();\n    const peerId = this.peerId;\n\n    this.managers.apiUpdatesManager.subscribeToChannelUpdates(this.peerId.toChatId());\n    middleware.onDestroy(() => {\n      this.managers.apiUpdatesManager.unsubscribeFromChannelUpdates(this.peerId.toChatId());\n    });\n\n    const peerTitlePromise = wrapPeerTitle({\n      peerId,\n      dialog: true,\n      wrapOptions: {middleware}\n    });\n\n    const setStatusPromise = appImManager.setPeerStatus({\n      peerId,\n      element: this.subtitle,\n      needClear: true,\n      useWhitespace: false,\n      middleware,\n      noTyping: true\n    });\n\n    return Promise.all([\n      peerTitlePromise,\n      setStatusPromise\n    ]).then(([\n      peerTitle,\n      setStatus\n      // _\n    ]) => {\n      if(!middleware()) {\n        return;\n      }\n\n      this.title.append(peerTitle);\n      setStatus?.();\n    });\n  }\n\n  public getOptionsForMessages(): Parameters<AppImManager['isSamePeer']>[0] {\n    return {\n      peerId: this.peerId,\n      type: ChatType.Chat\n    };\n  }\n\n  public viewAsMessages = async() => {\n    const chat = appImManager.chat;\n    const peerId = this.peerId;\n    this._close();\n    await this.managers.appChatsManager.toggleViewForumAsMessages(peerId.toChatId(), true);\n    appImManager[chat?.peerId === peerId ? 'setPeer' : 'setInnerPeer'](this.getOptionsForMessages());\n  };\n}\n","import middlewarePromise from '@helpers/middlewarePromise';\nimport namedPromises from '@helpers/namedPromises';\nimport {Dialog} from '@layer';\nimport appDialogsManager from '@lib/appDialogsManager';\nimport {isDialog} from '@appManagers/utils/dialogs/isDialog';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousMonoforumThreadList} from '@components/autonomousDialogList/monoforumThreads';\nimport SortedDialogList from '@components/sortedDialogList';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport {ForumTab} from '@components/forumTab/forumTab';\n\n\nexport class MonoforumTab extends ForumTab {\n  private dialogsCountI18nEl: HTMLElement;\n\n  syncInit(): void {\n    super.syncInit();\n\n\n    const autonomousList = new AutonomousMonoforumThreadList({peerId: this.peerId, appDialogsManager});\n    autonomousList.scrollable = this.scrollable;\n\n    const sortedList = autonomousList.sortedList = new SortedDialogList({\n      itemSize: 72,\n      appDialogsManager,\n      scrollable: this.scrollable,\n      managers: rootScope.managers,\n      requestItemForIdx: autonomousList.requestItemForIdx,\n      onListShrinked: autonomousList.onListShrinked,\n      indexKey: 'index_0',\n      monoforumParentPeerId: this.peerId\n    });\n\n    sortedList.addPinned(this.peerId);\n\n    const list = autonomousList.sortedList.list;\n\n    this.xd = autonomousList;\n\n    appDialogsManager.setListClickListener({list, onFound: null, withContext: true});\n    this.scrollable.append(list);\n    autonomousList.bindScrollable();\n\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_update', ({dialogs}) => {\n      if(!dialogs.find(dialog => dialog.parentPeerId === this.peerId)) return;\n      this.updateDialogsCount();\n    });\n\n    this.listenerSetter.add(rootScope)('monoforum_dialogs_drop', () => {\n      this.updateDialogsCount();\n    });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      for(const [, {dialog}] of dialogs) {\n        if(isDialog(dialog) && dialog.peerId === this.peerId) {\n          this.updateAllChatsDialog(dialog);\n        }\n      }\n    });\n  }\n\n  private updateAllChatsDialog(dialog: Dialog.dialog) {\n    const dialogElement = this.xd.getDialogElement(this.peerId);\n    if(!dialogElement) {\n      return;\n    }\n\n    appDialogsManager.setLastMessageN({\n      dialog,\n      dialogElement,\n      setUnread: true\n    });\n  }\n\n  async asyncInit(): Promise<void> {\n    await super.asyncInit();\n\n    const middleware = this.middlewareHelper.get();\n    const peerId = this.peerId;\n\n    const wrapPromiseWithMiddleware = middlewarePromise(middleware);\n\n    try {\n      const {peerTitle, dialogs} = await wrapPromiseWithMiddleware(namedPromises({\n        peerTitle: wrapPeerTitle({\n          peerId,\n          withIcons: true,\n          dialog: true,\n          wrapOptions: {middleware}\n        }),\n        dialogs: this.managers.monoforumDialogsStorage.getDialogs({parentPeerId: peerId, limit: 1})\n      }));\n\n      this.title.append(peerTitle);\n      this.subtitle.append(this.dialogsCountI18nEl = i18n('ChannelDirectMessages.ThreadsCount', [dialogs ? dialogs.count + '' : '~']))\n    } catch{}\n  }\n\n  private async updateDialogsCount() {\n    if(!this.dialogsCountI18nEl) return;\n    const {count} = await this.managers.monoforumDialogsStorage.getDialogs({parentPeerId: this.peerId, limit: 1});\n    this.dialogsCountI18nEl.replaceWith(i18n('ChannelDirectMessages.ThreadsCount', [count + '']));\n  }\n}\n","import apiManagerProxy from '@lib/apiManagerProxy';\nimport {BotforumTab} from '@components/forumTab/botforumTab';\nimport {ForumTab} from '@components/forumTab/forumTab';\nimport {GroupForumTab} from '@components/forumTab/groupForumTab';\nimport {MonoforumTab} from '@components/forumTab/monoforumTab';\n\n\nexport function fillForumTabRegister() {\n  ForumTab.register.addEntry({\n    check: (peerId) => {\n      const peer = apiManagerProxy.getPeer(peerId);\n      return !!(peer?._ === 'channel' && peer?.pFlags?.forum);\n    },\n    payload: GroupForumTab\n  });\n\n  ForumTab.register.addEntry({\n    check: (peerId) => {\n      const peer = apiManagerProxy.getPeer(peerId);\n      return !!(peer?._ === 'channel' && peer?.pFlags?.monoforum);\n    },\n    payload: MonoforumTab\n  });\n\n  ForumTab.register.addEntry({\n    check: (peerId) => {\n      const peer = apiManagerProxy.getPeer(peerId);\n      return !!(peer?._ === 'user' && peer?.pFlags?.bot_forum_view);\n    },\n    payload: BotforumTab\n  });\n}\n","import anchorCallback from '@helpers/dom/anchorCallback';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport noop from '@helpers/noop';\nimport {FOLDER_ID_ARCHIVE} from '@lib/appManagers/constants';\nimport {i18n} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport {useAppSettings} from '@stores/appSettings';\nimport {archiveDialogTagName} from './archiveDialog';\nimport confirmationPopup from './confirmationPopup';\nimport createFeatureDetailsIconSticker from './featureDetailsIconSticker';\nimport showFeatureDetailsPopup from './popups/featureDetails';\nimport appSidebarLeft from './sidebarLeft';\nimport {AppArchiveSettingsTab} from './solidJsTabs/tabs';\nimport {ButtonMenuItemOptionsVerifiable} from './buttonMenu';\n\n\ntype CreateArchiveDialogContextMenuArgs = {\n  element: HTMLElement;\n};\n\nconst showConfirmationWhenAbove = 1000;\n\nexport const createArchiveDialogContextMenu = ({\n  element\n}: CreateArchiveDialogContextMenuArgs) => {\n  let dialogElement: HTMLElement;\n\n  createContextMenu({\n    listenTo: element,\n    buttons: getArchiveContextMenuButtons(),\n    onOpen: async(_, li) => {\n      dialogElement = li;\n      li.classList.add('menu-open');\n    },\n    onClose: () => {\n      dialogElement.classList.remove('menu-open');\n    },\n    findElement: (e) => {\n      return findUpTag(e.target, archiveDialogTagName);\n    }\n  });\n};\n\nexport const getArchiveContextMenuButtons = (): ButtonMenuItemOptionsVerifiable[] => {\n  const [appSettings, setAppSettings] = useAppSettings();\n\n  const markAllAsRead = createMarkAllAsReadHandler();\n\n  return [\n    {\n      icon: 'movetomenu',\n      text: 'Archive.HideFromChatList',\n      onClick: () => {\n        setAppSettings('showArchiveInChatList', false);\n      },\n      verify: () => appSettings.showArchiveInChatList\n    }, {\n      icon: 'movetochats',\n      text: 'Archive.ShowInChatList',\n      onClick: () => {\n        setAppSettings('showArchiveInChatList', true);\n      },\n      verify: () => !appSettings.showArchiveInChatList\n    },\n    {\n      icon: 'readchats',\n      text: 'MarkAllAsRead',\n      onClick: async() => {\n        const unreadCount = await getUnreadCount();\n        if(unreadCount > showConfirmationWhenAbove) {\n          confirmationPopup({\n            titleLangKey: 'Archive.MarkAllAsRead.ConfirmationTitle',\n            descriptionLangKey: 'Archive.MarkAllAsRead.ConfirmationDescription',\n            button: {\n              langKey: 'Confirm'\n            }\n          }).then(() => {\n            markAllAsRead();\n          }, noop);\n        } else {\n          markAllAsRead();\n        }\n      },\n      verify: async() => !markAllAsRead.isLoading() && (await getUnreadCount() > 0)\n    },\n    {\n      icon: 'tools',\n      text: 'ArchiveSettings',\n      onClick: () => {\n        appSidebarLeft.createTab(AppArchiveSettingsTab).open();\n      }\n    },\n    {\n      icon: 'help',\n      text: 'ArchiveFeatureDetails.MenuOption',\n      onClick: () => {\n        openFeatureDetails();\n      }\n    }\n  ]\n};\n\nfunction createMarkAllAsReadHandler() {\n  let isLoading = false;\n\n  const markAllAsRead = async() => {\n    try {\n      isLoading = true;\n      rootScope.managers.dialogsStorage.markFolderAsRead(\n        FOLDER_ID_ARCHIVE,\n        true\n      );\n    } finally {\n      isLoading = false;\n    }\n  };\n\n  markAllAsRead.isLoading = () => isLoading;\n\n  return markAllAsRead;\n};\n\nasync function getUnreadCount() {\n  const {unreadCount} = await rootScope.managers.dialogsStorage\n  .getFolderUnreadCount(FOLDER_ID_ARCHIVE, true);\n  return unreadCount;\n};\n\nfunction openFeatureDetails() {\n  const close = showFeatureDetailsPopup({\n    title: i18n('ArchiveFeatureDetails.Title'),\n    subtitle: i18n('ArchiveFeatureDetails.Subtitle', [anchorCallback(() => {\n      close();\n      appSidebarLeft.createTab(AppArchiveSettingsTab).open();\n    })]),\n    rows: [\n      {\n        icon: 'archive_filled',\n        title: i18n('ArchiveFeatureDetails.HowTo.Title'),\n        subtitle: i18n('ArchiveFeatureDetails.HowTo.Subtitle', [i18n('Archive'), i18n('Unarchive')])\n      },\n      {\n        icon: 'eyecross',\n        title: i18n('ArchiveFeatureDetails.Hide.Title'),\n        subtitle: i18n('ArchiveFeatureDetails.Hide.Subtitle', [i18n('Archive.HideFromChatList')])\n      },\n      {\n        icon: 'story',\n        title: i18n('ArchiveFeatureDetails.Stories.Title'),\n        subtitle: i18n('ArchiveFeatureDetails.Stories.Subtitle')\n      }\n    ],\n    buttons: [\n      {\n        text: i18n('ArchiveFeatureDetails.Button')\n      }\n    ],\n    sticker: {\n      element: createFeatureDetailsIconSticker('archive_filled', 'background-gradient-archive')\n    }\n  });\n}\n","import {createSignal, JSX, Setter} from 'solid-js';\nimport {render} from 'solid-js/web';\nimport RowTsx from '@components/rowTsx';\n\ntype RowTsxProps = Parameters<typeof RowTsx>[0];\n\nexport type ChatlistTopNotificationController = {\n  setTitle: (title: JSX.Element) => void,\n  setSubtitle: (subtitle: JSX.Element) => void,\n  dispose: VoidFunction\n};\n\nexport function renderChatlistTopNotification(\n  toElement: HTMLElement,\n  props: {\n    onClick: Exclude<RowTsxProps['clickable'], boolean>,\n    contextMenu: NonNullable<RowTsxProps['contextMenu']>\n  }\n): ChatlistTopNotificationController {\n  const [title, setTitle] = createSignal<JSX.Element>(true);\n  const [subtitle, setSubtitle] = createSignal<JSX.Element>(true);\n  const setElement = (setter: Setter<JSX.Element>, element: JSX.Element) => {\n    setter(() => element);\n  };\n\n  const disposeRoot = render(() => (\n    <RowTsx\n      class=\"chatlist-top-notification\"\n      clickable={props.onClick}\n      contextMenu={props.contextMenu}\n    >\n      <RowTsx.Title>{title()}</RowTsx.Title>\n      <RowTsx.Subtitle>{subtitle()}</RowTsx.Subtitle>\n      <RowTsx.Icon icon=\"next\" />\n    </RowTsx>\n  ), toElement);\n  let disposed = false;\n  const dispose = () => {\n    if(disposed) return;\n\n    disposed = true;\n    disposeRoot();\n  };\n\n  return {\n    setTitle: (element) => setElement(setTitle, element),\n    setSubtitle: (element) => setElement(setSubtitle, element),\n    dispose\n  };\n}\n","import type {MyDialogFilter} from '@lib/storages/filters';\nimport type {Dialog, ForumTopic, MyMessage, RequestHistoryOptions, SavedDialog} from '@appManagers/appMessagesManager';\nimport type {MyDocument} from '@appManagers/appDocsManager';\nimport type {State} from '@config/state';\nimport type {AnyDialog} from '@lib/storages/dialogs';\nimport type {CustomEmojiRendererElement} from '@customEmoji/renderer';\nimport PopupElement from '@components/popups';\nimport PopupElementTsx from '@components/popups/indexTsx';\nimport DialogsContextMenu from '@components/dialogsContextMenu';\nimport DotRenderer from '@components/dotRenderer';\nimport {horizontalMenuObjArgs} from '@components/horizontalMenu';\nimport Scrollable from '@components/scrollable';\nimport {ScrollableContextValue} from '@components/scrollable2';\nimport {formatDateAccordingToTodayNew} from '@helpers/date';\nimport {IS_MOBILE_SAFARI} from '@environment/userAgent';\nimport {logger, LogTypes} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport appImManager, {AppImManager, APP_TABS} from '@lib/appImManager';\nimport Button from '@components/button';\nimport SetTransition from '@components/singleTransition';\nimport {MyDraftMessage} from '@appManagers/appDraftsManager';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport PeerTitle, {changeTitleEmojiColor} from '@components/peerTitle';\nimport I18n, {FormatterArguments, i18n, LangPackKey, _i18n} from '@lib/langPack';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport wrapPhoto from '@components/wrappers/photo';\nimport {AppEditFolderTab} from '@components/solidJsTabs/tabs';\nimport appSidebarLeft from '@components/sidebarLeft';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport highlightText, {TextHighlight} from '@helpers/dom/textHighlight';\nimport ConnectionStatusComponent from '@components/connectionStatus';\nimport {renderImageFromUrlPromise} from '@helpers/dom/renderImageFromUrl';\nimport {fastRafPromise} from '@helpers/schedulers';\nimport SortedUserList from '@components/sortedUserList';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport handleTabSwipe from '@helpers/dom/handleTabSwipe';\nimport windowSize from '@helpers/windowSize';\nimport isInDOM from '@helpers/dom/isInDOM';\nimport {setSendingStatus} from '@components/sendingStatus';\nimport {SortedElementBase} from '@helpers/sortedList';\nimport {FOLDER_ID_ALL, FOLDER_ID_ARCHIVE, NULL_PEER_ID, REAL_FOLDERS} from '@appManagers/constants';\nimport groupCallActiveIcon from '@components/groupCallActiveIcon';\nimport {ChatlistsChatlistUpdates, DialogFilter, Message, MessageMedia, MessageReplyHeader, Photo} from '@layer';\nimport mediaSizes from '@helpers/mediaSizes';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport appMediaPlaybackController from '@components/appMediaPlaybackController';\nimport {AppManagers} from '@lib/managers';\nimport appSidebarRight from '@components/sidebarRight';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport renderDialogSubtitleParts from '@components/wrappers/dialogSubtitle';\nimport wrapMessageForReply from '@components/wrappers/messageForReply';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\nimport isMessageRestricted, {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport getMessageSenderPeerIdOrName from '@appManagers/utils/messages/getMessageSenderPeerIdOrName';\nimport wrapStickerEmoji from '@components/wrappers/stickerEmoji';\nimport getProxiedManagers from '@lib/getProxiedManagers';\nimport deferredPromise, {CancellablePromise} from '@helpers/cancellablePromise';\nimport middlewarePromise from '@helpers/middlewarePromise';\nimport appDownloadManager from '@lib/appDownloadManager';\nimport groupCallsController from '@lib/calls/groupCallsController';\nimport callsController from '@lib/calls/callsController';\nimport conferenceInvitesController from '@lib/calls/conferenceInvitesController';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport noop from '@helpers/noop';\nimport pause from '@helpers/schedulers/pause';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport filterAsync from '@helpers/array/filterAsync';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport {getMiddleware, MiddlewareHelper} from '@helpers/middleware';\nimport getDialogMentionBadgeState from '@helpers/dialogMentionBadgeState';\nimport {attachRowController, RowMediaSizeType, type RowTsxController} from '@components/rowTsxController'\nimport SettingSection from '@components/settingSection';\nimport getMessageThreadId from '@appManagers/utils/messages/getMessageThreadId';\nimport formatNumber from '@helpers/number/formatNumber';\nimport AppSharedMediaTab from '@components/sidebarRight/tabs/sharedMediaTab';\nimport {dispatchHeavyAnimationEvent} from '@hooks/useHeavyAnimationCheck';\nimport shake from '@helpers/dom/shake';\nimport getServerMessageId from '@appManagers/utils/messageId/getServerMessageId';\nimport {AppChatFoldersTab} from '@components/solidJsTabs/tabs';\nimport eachTimeout from '@helpers/eachTimeout';\nimport PopupSharedFolderInvite from '@components/popups/sharedFolderInvite';\nimport showChatPreviewPopup, {chatPreviewAnchorFromDialogRow} from '@components/popups/chatPreview';\nimport showLimitPopup from '@components/popups/limit';\nimport StoriesList from '@components/stories/list';\nimport {render} from 'solid-js/web';\nimport {avatarNew} from '@components/avatarNew';\nimport Icon from '@components/icon';\nimport {isDialog, isForumTopic, isMonoforumDialog, isSavedDialog} from '@appManagers/utils/dialogs/isDialog';\nimport {ChatType} from '@components/chat/chatType';\nimport rtmpCallsController from '@lib/calls/rtmpCallsController';\nimport IS_LIVE_STREAM_SUPPORTED from '@environment/liveStreamSupport';\nimport createFolderContextMenu from '@helpers/dom/createFolderContextMenu';\nimport {useAppSettings} from '@stores/appSettings';\nimport {unwrap} from 'solid-js/store';\nimport wrapMediaSpoiler from '@components/wrappers/mediaSpoiler';\nimport type {MonoforumDialog} from '@lib/storages/monoforumDialogs';\nimport {renderPendingSuggestion} from '@components/sidebarLeft/pendingSuggestion';\nimport {renderNewAuthorization} from '@components/sidebarLeft/newAuthorization';\nimport {useHasFolders} from '@stores/foldersSidebar';\nimport {useAppState} from '@stores/appState';\nimport {BADGE_TRANSITION_TIME} from '@components/autonomousDialogList/constants';\nimport {AutonomousDialogList} from '@components/autonomousDialogList/dialogs';\nimport {PossibleDialog, setDialogTyping} from '@components/autonomousDialogList/base';\nimport {ForumTab} from '@components/forumTab/forumTab';\nimport findForumTabByPeerId from '@components/forumTab/findForumTabByPeerId';\nimport shouldOpenForumAsNavigationTab from '@components/forumTab/communityOpenMode';\nimport isCommunityChat from '@appManagers/utils/communities/isCommunity';\nimport {getCommunityPeerSubtitle} from '@components/communities/communityPeerStatus';\nimport {fillForumTabRegister} from '@components/forumTab/fillRegister';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {fastSmoothScrollToStart} from '@helpers/fastSmoothScroll';\nimport ArchiveDialog, {archiveDialogTagName} from '@components/archiveDialog';\nimport {createArchiveDialogContextMenu} from '@components/archiveDialogContextMenu';\nimport {children, createRoot, untrack} from 'solid-js';\nimport useFolders from '@stores/folders';\nimport FoldersTabs from '@components/foldersTabs';\nimport clamp from '@helpers/number/clamp';\nimport confirmationPopup from '@components/confirmationPopup';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport type PopupPeer from '@components/popups/peer';\nimport {toastNew} from '@components/toast';\nimport {\n  renderChatlistTopNotification,\n  type ChatlistTopNotificationController\n} from '@components/sidebarLeft/chatlistTopNotification';\n\n\nexport const DIALOG_LIST_ELEMENT_TAG = 'A';\nconst DIALOG_LOAD_COUNT = 20;\n\nexport function findDialogListElement(target: EventTarget) {\n  return findUpTag(target, DIALOG_LIST_ELEMENT_TAG);\n}\n\nexport type DialogDom = {\n  avatarEl: ReturnType<typeof avatarNew>,\n  captionDiv: HTMLElement,\n  titleSpan: HTMLSpanElement,\n  titleSpanContainer: HTMLSpanElement,\n  statusSpan: HTMLSpanElement,\n  lastTimeSpan: HTMLSpanElement,\n  pinnedBadge?: HTMLElement,\n  unreadBadge?: HTMLElement,\n  unreadAvatarBadge?: HTMLElement,\n  callIcon?: ReturnType<typeof groupCallActiveIcon>,\n  mentionsBadge?: HTMLElement,\n  reactionsBadge?: HTMLElement,\n  pollVotesBadge?: HTMLElement,\n  lastMessageSpan: HTMLSpanElement,\n  containerEl: HTMLElement,\n  listEl: HTMLElement,\n  subtitleEl: HTMLElement,\n  mutedIcon?: HTMLElement,\n\n  titleWrapOptions?: WrapSomethingOptions;\n\n  /**\n   * Signature of the last successfully rendered subtitle. Every dialog event\n   * (read, mark unread, notify settings, filter update) runs the whole\n   * `setLastMessage` pipeline, so without it the subtitle is torn down and\n   * rebuilt — custom emoji, media thumbs and all — for updates that cannot\n   * have changed a single character of it.\n   */\n  lastMessageRenderKey?: string,\n  /**\n   * The nodes that signature was rendered as. Plenty of other places\n   * (community dialogs, search results, sidebar pickers) write their own\n   * subtitle into `lastMessageSpan`, so a matching key alone does not mean the\n   * rendered subtitle is still the one in the DOM.\n   */\n  lastMessageRenderParts?: HTMLElement[],\n  /** search-result rows: the query lit up inside the rendered message text */\n  textHighlight?: TextHighlight,\n\n  setLastMessagePromise?: CancellablePromise<void>,\n  setUnreadMessagePromise?: CancellablePromise<void>\n};\n\ninterface SortedDialog extends SortedElementBase<PeerId> {\n  dom: DialogDom,\n  dialogElement: DialogElement\n}\n\nfunction setPromiseMiddleware<T extends {[smth in K as K]?: CancellablePromise<void>}, K extends keyof T>(obj: T, key: K) {\n  const oldPromise: CancellablePromise<void> = obj[key] as any;\n  oldPromise?.reject();\n\n  // @ts-ignore\n  const deferred = obj[key] = deferredPromise<void>();\n  deferred.catch(() => {}).finally(() => {\n    if((obj[key] as any) === deferred) {\n      delete obj[key];\n    }\n  });\n\n  const middleware = middlewarePromise(() => (obj[key] as any) === deferred);\n  return {deferred, middleware};\n}\n\nfunction disposeTextHighlight(dom: DialogDom) {\n  dom.textHighlight?.dispose();\n  dom.textHighlight = undefined;\n}\n\n/**\n * Whether the subtitle in the DOM is still exactly what `setLastMessage` put\n * there — anyone else writing into `lastMessageSpan` (a community dialog\n * falling back to its chat count, a search result, a sidebar picker) has to\n * invalidate the skip.\n */\nfunction isRenderedSubtitleIntact(dom: DialogDom) {\n  const parts = dom.lastMessageRenderParts;\n  const {childNodes} = dom.lastMessageSpan;\n  return !!parts &&\n    parts.length === childNodes.length &&\n    parts.every((part, idx) => part === childNodes[idx]);\n}\n\nfunction getFolderTitleTextColor(active: boolean) {\n  return active ? 'primary-color' : 'secondary-text-color';\n}\n\nconst BADGE_SIZE = 22;\n\n\nconst avatarSizeMap: {[k in DialogElementSize]?: number} = {\n  bigger: 54,\n  abitbigger: 42,\n  small: 32\n};\n\nexport type DialogElementSize = RowMediaSizeType;\nexport type AsAllChatsType = 'monoforum' | 'topics';\n\nexport type DialogElementOptions = {\n  peerId: PeerId,\n  rippleEnabled?: boolean,\n  onlyFirstName?: boolean,\n  meAsSaved?: boolean,\n  avatarSize?: RowMediaSizeType,\n  autonomous?: boolean,\n  loadPromises?: Promise<any>[],\n  fromName?: string,\n  noIcons?: boolean,\n  threadId?: number,\n  monoforumParentPeerId?: PeerId,\n  wrapOptions: WrapSomethingOptions,\n  isMainList?: boolean,\n  withStories?: boolean,\n  controlled?: boolean,\n  dontSetActive?: boolean,\n  asAllChats?: AsAllChatsType,\n  autoDeletePeriod?: number,\n  avatarElement?: HTMLElement\n};\n\nexport type DialogElementBadgeState = {\n  muted: boolean,\n  pinned: boolean,\n  unread: boolean,\n  unreadText?: string,\n  unreadMention?: boolean,\n  unreadAvatar: boolean,\n  unreadAvatarText?: string,\n  mentions: boolean,\n  reactions: boolean,\n  pollVotes: boolean,\n  transitionDuration?: number\n};\n\ntype DialogElementAppliedBadgeState = {\n  [key in Parameters<DialogElement['toggleBadgeByKey']>[0]]: boolean\n} & {\n  hasOnlyPinnedBadge: boolean,\n  unreadText?: string,\n  unreadAvatarText?: string\n};\n\nexport interface DialogElement extends RowTsxController {}\n\nexport class DialogElement {\n  public dom: DialogDom;\n  public isMainList: boolean;\n  public middlewareHelper: MiddlewareHelper;\n  private peerTitle: PeerTitle;\n  private lastBadgeState: DialogElementAppliedBadgeState;\n\n  constructor({\n    peerId,\n    rippleEnabled = true,\n    onlyFirstName = false,\n    meAsSaved = true,\n    avatarSize = 'bigger',\n    autonomous,\n    loadPromises,\n    fromName,\n    noIcons,\n    threadId,\n    monoforumParentPeerId,\n    wrapOptions = {},\n    isMainList,\n    withStories,\n    controlled,\n    dontSetActive,\n    asAllChats,\n    autoDeletePeriod,\n    avatarElement\n  }: DialogElementOptions) {\n    const wrapMiddleware = wrapOptions?.middleware;\n    this.middlewareHelper = wrapMiddleware ? wrapOptions.middleware.create() : (controlled ? getMiddleware() : undefined);\n\n    attachRowController(this, {\n      clickable: true,\n      noRipple: !rippleEnabled,\n      havePadding: !threadId && asAllChats !== 'topics',\n      title: true,\n      titleRightSecondary: true,\n      subtitle: true,\n      subtitleRight: true,\n      noWrap: true,\n      asLink: true,\n      middleware: this.middlewareHelper?.get()\n    });\n\n    this.isMainList = isMainList;\n    this.subtitleRight.remove();\n\n    const newWrapOptions: WrapSomethingOptions = {\n      ...wrapOptions\n    };\n\n    if(this.middlewareHelper) {\n      newWrapOptions.middleware = this.middlewareHelper.get();\n    }\n\n    const isSavedDialog = !!threadId && peerId === rootScope.myId;\n    const isForumTopic = !!threadId && !isSavedDialog;\n\n    const usePeerId = isSavedDialog ? threadId : peerId;\n\n    const avatar = avatarElement || isForumTopic || asAllChats === 'topics' ?\n      undefined :\n      avatarNew({\n        middleware: this.middlewareHelper.get(),\n        size: avatarSizeMap[avatarSize],\n\n        lazyLoadQueue: newWrapOptions.lazyLoadQueue,\n        isDialog: !!meAsSaved,\n        peerId: fromName ? NULL_PEER_ID : usePeerId,\n        peerTitle: fromName,\n        withStories,\n        // Animate video avatars only in the primary chat list (withStories), not\n        // in compact pickers / search rows.\n        withVideoAvatar: withStories,\n        wrapOptions: newWrapOptions,\n        meAsNotes: isSavedDialog,\n        asAllChats: asAllChats === 'monoforum',\n        autoDeletePeriod\n      });\n    loadPromises?.push(avatar?.readyThumbPromise);\n    const avatarEl = avatarElement || avatar?.node;\n    if(avatarEl) {\n      avatarEl.classList.add('dialog-avatar');\n      this.applyMediaElement(avatarEl, avatarSize);\n    }\n\n    const captionDiv = this.container;\n\n    const titleSpanContainer = this.title;\n    titleSpanContainer.classList.add('user-title');\n\n    this.titleRow.classList.add('dialog-title');\n\n    const isActive = !dontSetActive && !autonomous &&\n      appImManager.chat &&\n      appImManager.isSamePeer(appImManager.chat, {\n        peerId: monoforumParentPeerId || peerId,\n        monoforumThreadId: monoforumParentPeerId ? peerId : undefined,\n        threadId: threadId,\n        type: isSavedDialog ? ChatType.Saved : ChatType.Chat\n      });\n\n    const titleWrapOptions: WrapSomethingOptions = {\n      textColor: appDialogsManager.getTextColor(isActive),\n      ...newWrapOptions\n    };\n\n    const peerTitle = this.peerTitle = new PeerTitle();\n    const peerTitlePromise = peerTitle.update({\n      peerId: usePeerId,\n      fromName,\n      dialog: meAsSaved,\n      onlyFirstName,\n      withIcons: !noIcons,\n      threadId: isSavedDialog ? undefined : threadId,\n      wrapOptions: titleWrapOptions,\n      iconsColor: appDialogsManager.getPrimaryColor(isActive),\n      meAsNotes: isSavedDialog,\n      asAllChats\n    });\n\n    loadPromises?.push(peerTitlePromise);\n    titleSpanContainer.append(peerTitle.element);\n\n    // const titleIconsPromise = generateTitleIcons(peerId).then((elements) => {\n    //   titleSpanContainer.append(...elements);\n    // });\n\n    // if(loadPromises) {\n    //   loadPromises.push(titleIconsPromise);\n    // }\n    // }\n\n    const span = this.subtitle;\n    // span.classList.add('user-last-message');\n\n    const li = this.container;\n    li.classList.add('chatlist-chat', 'chatlist-chat-' + avatarSize);\n    if(!autonomous) {\n      (li as HTMLAnchorElement).href = '#' + peerId;\n    }\n    // if(rippleEnabled) {\n    //   ripple(li);\n    // }\n\n    if(avatarSize === 'bigger') {\n      this.container.classList.add('row-big');\n    } else if(avatarSize === 'small') {\n      this.container.classList.add('row-small');\n    }\n\n    li.dataset.peerId = '' + peerId;\n\n    if(threadId) li.dataset.threadId = '' + threadId;\n    if(monoforumParentPeerId) li.dataset.monoforumParentPeerId = '' + monoforumParentPeerId;\n    if(asAllChats) li.dataset.isAllChats = 'true';\n\n\n    const statusSpan = document.createElement('span');\n    statusSpan.classList.add('message-status', 'sending-status'/* , 'transition', 'reveal' */);\n\n    const lastTimeSpan = document.createElement('span');\n    lastTimeSpan.classList.add('message-time');\n\n    const rightSpan = this.titleRight;\n    rightSpan.classList.add('dialog-title-details');\n    rightSpan.append(statusSpan, lastTimeSpan);\n\n    this.subtitleRow.classList.add('dialog-subtitle', 'has-multiple-badges');\n\n    // if(I18n.isRTL) {\n    //   // this.subtitle.dir = '';\n    //   // this.subtitle.dir = 'rtl';\n    // }\n\n    const dom: DialogDom = this.dom = {\n      avatarEl: avatar,\n      captionDiv,\n      titleSpan: peerTitle.element,\n      titleSpanContainer,\n      statusSpan,\n      lastTimeSpan,\n      lastMessageSpan: span,\n      containerEl: li,\n      listEl: li,\n      subtitleEl: this.subtitleRow,\n      titleWrapOptions\n    };\n\n    // this will never happen for migrated legacy chat\n    if(!autonomous) {\n      (li as any).dialogDom = dom;\n\n      if(isMainList && !asAllChats && appDialogsManager.forumTab?.peerId === peerId && !threadId) {\n        li.classList.add('is-forum-open');\n      }\n    }\n\n    if(isActive) {\n      appDialogsManager.setDialogActive(li, true);\n    }\n  }\n\n  public destroy() {\n    this.dispose();\n    this.middlewareHelper?.destroy();\n    disposeTextHighlight(this.dom);\n  }\n\n  public updateTitle(fromName: string) {\n    return this.peerTitle.update({fromName});\n  }\n\n  public remove() {\n    this.destroy();\n    this.dom.listEl.remove();\n  }\n\n  public setMuted(isMuted: boolean, transitionDuration = 0) {\n    const {dom} = this;\n    const wasMuted = dom.listEl.classList.contains('is-muted') &&\n      !dom.listEl.classList.contains('backwards');\n    if(isMuted === wasMuted) {\n      return;\n    }\n\n    if(isMuted && !dom.mutedIcon) {\n      dom.mutedIcon = Icon('nosound_filled', 'dialog-muted-icon');\n      dom.titleSpanContainer.append(dom.mutedIcon);\n    }\n\n    SetTransition({\n      element: dom.listEl,\n      className: 'is-muted',\n      forwards: isMuted,\n      duration: transitionDuration,\n      onTransitionEnd: !isMuted ? (() => {\n        dom.mutedIcon?.remove();\n        delete dom.mutedIcon;\n      }) : undefined\n    });\n  }\n\n  public createPinnedBadge() {\n    if(this.dom.pinnedBadge) return;\n    const badge = this.dom.pinnedBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-icon badge-${BADGE_SIZE} dialog-subtitle-badge-pinned`;\n    badge.append(Icon('chatspinned'));\n    this.dom.subtitleEl.append(badge);\n  }\n\n  public createUnreadBadge() {\n    if(this.dom.unreadBadge) return;\n    const badge = this.dom.unreadBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-${BADGE_SIZE} dialog-subtitle-badge-unread`;\n    this.dom.subtitleEl.append(badge);\n  }\n\n  public createUnreadAvatarBadge() {\n    if(this.dom.unreadAvatarBadge) return;\n    const badge = this.dom.unreadAvatarBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-${BADGE_SIZE} avatar-badge`;\n    this.dom.listEl.append(badge);\n  }\n\n  public createMentionsBadge() {\n    if(this.dom.mentionsBadge) return;\n    const badge = this.dom.mentionsBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-${BADGE_SIZE} mention mention-badge dialog-subtitle-badge-mention`;\n    badge.innerText = '@';\n    this.dom.subtitleEl.append(badge);\n  }\n\n  public createReactionsBadge() {\n    if(this.dom.reactionsBadge) return;\n    const badge = this.dom.reactionsBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-${BADGE_SIZE} reaction-badge dialog-subtitle-badge-reaction`;\n    badge.append(Icon('reactions_filled'));\n    this.dom.subtitleEl.append(badge);\n  }\n\n  public createPollVotesBadge() {\n    if(this.dom.pollVotesBadge) return;\n    const badge = this.dom.pollVotesBadge = document.createElement('div');\n    badge.className = `dialog-subtitle-badge badge badge-${BADGE_SIZE} poll-vote-badge dialog-subtitle-badge-pollvote`;\n    badge.append(Icon('poll'));\n    this.dom.subtitleEl.append(badge);\n  }\n\n  public setBadgeState(options: DialogElementBadgeState) {\n    const transitionDuration = options.transitionDuration || 0;\n    this.setMuted(options.muted, transitionDuration);\n\n    const previous = this.lastBadgeState;\n\n    const mounted = {\n      pinnedBadge: !!this.dom.pinnedBadge,\n      unreadBadge: !!this.dom.unreadBadge,\n      unreadAvatarBadge: !!this.dom.unreadAvatarBadge,\n      mentionsBadge: !!this.dom.mentionsBadge,\n      reactionsBadge: !!this.dom.reactionsBadge,\n      pollVotesBadge: !!this.dom.pollVotesBadge\n    };\n    if(options.pinned) this.createPinnedBadge();\n    if(options.unread) this.createUnreadBadge();\n    if(options.unreadAvatar) this.createUnreadAvatarBadge();\n    if(options.mentions) this.createMentionsBadge();\n    if(options.reactions) this.createReactionsBadge();\n    if(options.pollVotes) this.createPollVotesBadge();\n\n    const subtitleBadgesLength = [\n      options.pinned,\n      options.unread,\n      options.mentions,\n      options.reactions,\n      options.pollVotes\n    ].filter(Boolean).length;\n    const hasOnlyPinnedBadge = options.pinned && subtitleBadgesLength === 1;\n    // * `SetTransition` keeps `animating` on the element for the whole duration,\n    // * and `.has-only-pinned-badge:not(.animating)` drops the subtitle's trailing\n    // * margin while it is there. Replaying it for an unchanged state makes the\n    // * subtitle of every pinned row widen and snap back — a visible blink.\n    if(!previous || previous.hasOnlyPinnedBadge !== hasOnlyPinnedBadge) {\n      SetTransition({\n        element: this.subtitleRow,\n        className: 'has-only-pinned-badge',\n        forwards: hasOnlyPinnedBadge,\n        duration: transitionDuration\n      });\n    }\n\n    const states: Array<[\n      Parameters<DialogElement['toggleBadgeByKey']>[0],\n      boolean\n    ]> = [\n      ['pinnedBadge', options.pinned],\n      ['unreadBadge', options.unread],\n      ['unreadAvatarBadge', options.unreadAvatar],\n      ['mentionsBadge', options.mentions],\n      ['reactionsBadge', options.reactions],\n      ['pollVotesBadge', options.pollVotes]\n    ];\n    for(const [key, visible] of states) {\n      if(!this.dom[key]) {\n        continue;\n      }\n\n      // an already mounted badge that keeps its visibility needs no transition\n      if(mounted[key] && previous?.[key] === visible) {\n        continue;\n      }\n\n      this.toggleBadgeByKey(key, visible, mounted[key], !transitionDuration);\n    }\n\n    if(options.unread && this.dom.unreadBadge) {\n      if(options.unreadText !== undefined && options.unreadText !== previous?.unreadText) {\n        this.dom.unreadBadge.innerText = options.unreadText;\n        if(this.dom.unreadAvatarBadge) {\n          this.dom.unreadAvatarBadge.innerText = options.unreadText;\n        }\n      }\n      this.dom.unreadBadge.classList.add('unread');\n      this.dom.unreadBadge.classList.toggle('mention', !!options.unreadMention);\n    }\n\n    if(options.unreadAvatar && this.dom.unreadAvatarBadge) {\n      if(options.unreadAvatarText !== undefined && options.unreadAvatarText !== previous?.unreadAvatarText) {\n        this.dom.unreadAvatarBadge.innerText = options.unreadAvatarText;\n      }\n      this.dom.unreadAvatarBadge.classList.add('unread');\n      this.dom.unreadAvatarBadge.classList.toggle('mention', !!options.unreadMention);\n    }\n\n    this.lastBadgeState = {\n      pinnedBadge: options.pinned,\n      unreadBadge: options.unread,\n      unreadAvatarBadge: options.unreadAvatar,\n      mentionsBadge: options.mentions,\n      reactionsBadge: options.reactions,\n      pollVotesBadge: options.pollVotes,\n      hasOnlyPinnedBadge,\n      unreadText: options.unreadText,\n      unreadAvatarText: options.unreadAvatarText\n    };\n  }\n\n  public toggleBadgeByKey(\n    key: Extract<keyof DialogDom, 'unreadBadge' | 'unreadAvatarBadge' | 'mentionsBadge' | 'reactionsBadge' | 'pollVotesBadge' | 'pinnedBadge'>,\n    hasBadge: boolean,\n    justCreated: boolean,\n    batch?: boolean\n  ) {\n    // * `setBadgeState` skips a badge whose visibility `lastBadgeState` says is unchanged, so\n    // * out-of-band toggles (`toggleAvatarUnreadBadges` on sidebar collapse / forum tab) must\n    // * keep it in sync — otherwise reading the last unread topic can't hide the avatar badge\n    if(this.lastBadgeState) {\n      this.lastBadgeState[key] = hasBadge;\n    }\n\n    SetTransition({\n      element: this.dom[key],\n      className: 'is-visible',\n      forwards: hasBadge,\n      duration: batch ? 0 : BADGE_TRANSITION_TIME,\n      onTransitionEnd: hasBadge ? undefined : () => {\n        this.dom[key].remove();\n        delete this.dom[key];\n      },\n      useRafs: !justCreated || !isInDOM(this.dom[key]) ? 2 : 0\n    });\n  }\n}\n\n// const testScroll = false;\n// let testTopSlice = 1;\n\ntype FilterRendered = {\n  id: number,\n  container: HTMLElement,\n  scrollable: Scrollable,\n  topNotification?: ChatlistTopNotificationController,\n  topNotificationContainer?: HTMLElement,\n  topNotificationData?: {\n    _: 'chatlistUpdates',\n    chatlistUpdates: ChatlistsChatlistUpdates\n  }\n};\n\ntype GetDialogOptions = {\n  threadOrSavedId?: number;\n  monoforumParentPeerId?: number;\n};\n\ntype InitDialogAdditionalOptions = {\n  isBatch?: boolean,\n  dialog?: AnyDialog,\n  lastMessage?: MyMessage,\n  onInitPromise?: (promise: Promise<unknown>) => void\n};\n\nconst TEST_TOP_NOTIFICATION = true ? undefined : (): ChatlistsChatlistUpdates => ({\n  _: 'chatlists.chatlistUpdates',\n  chats: [],\n  users: [],\n  missing_peers: [{\n    _: 'peerUser',\n    user_id: rootScope.myId.toUserId()\n  }]\n});\n\n\nexport class AppDialogsManager {\n  public chatsContainer = document.getElementById('chatlist-container') as HTMLDivElement;\n\n  private log = logger('DIALOGS', LogTypes.Log | LogTypes.Error | LogTypes.Warn | LogTypes.Debug);\n\n  public contextMenu: DialogsContextMenu;\n\n  public filterId: number;\n  public folders: {[k in 'menu' | 'container' | 'menuScrollContainer' | 'menuGradient']: HTMLElement} = {\n    menu: undefined,\n    menuScrollContainer: undefined,\n    menuGradient: undefined,\n    container: document.getElementById('folders-container')\n  };\n  private filtersRendered: {\n    [filterId: string]: FilterRendered\n  } = {};\n  private showFiltersPromise: Promise<void>;\n\n  private lastActiveElements: Set<HTMLElement> = new Set();\n\n  public loadContacts: () => void;\n  public processContact: (peerId: PeerId) => void;\n\n  private initedListeners = false;\n\n  public onListLengthChange: () => Promise<void>;\n  private allChatsIntlElement: I18n.IntlElement;\n\n  private emptyDialogsPlaceholderSubtitle: I18n.IntlElement;\n  private updateContactsLengthPromise: Promise<number>;\n\n  private filtersNavigationItem: NavigationItem;\n\n  private managers: AppManagers;\n\n  public doNotRenderChatList: boolean;\n  public isFirstDialogsLoad: boolean;\n\n  private stateMiddlewareHelper: MiddlewareHelper;\n\n  private forumsTabs: Map<PeerId, ForumTab>;\n  private forumsSlider: HTMLElement;\n  private forumTabByPeerIdPromises = new Map<PeerId, Promise<void>>();\n  public forumTab: ForumTab;\n  private forumNavigationItem: NavigationItem;\n\n  public xd: AutonomousDialogList;\n  public xds: {[filterId: number]: AutonomousDialogList} = {};\n\n  public cancelChatlistUpdatesFetching: () => void;\n  public fetchChatlistUpdates: () => void;\n\n  private storiesListContainer: HTMLDivElement;\n  private bottomPart: HTMLDivElement;\n  private disposeStories: () => void;\n  public resizeStoriesList: () => void;\n\n  private suggestionContainer: HTMLElement;\n  private authorizationContainer: HTMLElement;\n  private foldersOverlay: HTMLElement;\n\n  private lazyLoadQueue: LazyLoadQueue;\n\n  private ignoreFolderChange: boolean;\n\n  public start() {\n    const managers = this.managers = getProxiedManagers();\n\n    this.contextMenu = new DialogsContextMenu(managers);\n    this.stateMiddlewareHelper = getMiddleware();\n    this.lazyLoadQueue = new LazyLoadQueue(5, true);\n\n    // this.onListLengthChange = debounce(this._onListLengthChange, 100, false, true);\n    this.onListLengthChange = () => void this._onListLengthChange();\n\n    const bottomPart = this.bottomPart = document.createElement('div');\n    bottomPart.classList.add('connection-status-bottom');\n    bottomPart.append(this.folders.container);\n\n    // Single absolute overlay sitting above the chatlist (#folders-container) that hosts every\n    // panel currently rendered there: pending suggestion, folder tabs scrollable, gradient.\n    // The panels flow naturally inside; only the overlay itself is absolutely positioned, so a\n    // new panel above the tabs just stacks instead of overlapping (see _leftSidebar.scss).\n    this.foldersOverlay = document.createElement('div');\n    this.foldersOverlay.classList.add('chatlist-overlay');\n    bottomPart.prepend(this.foldersOverlay);\n\n    // Surface the overlay's live height to the parent so the chatlist below can leave matching\n    // top padding — .folders-scrollable reads var(--chatlist-overlay-height) for its padding-top.\n    new ResizeObserver((entries) => {\n      const height = entries[0].borderBoxSize?.[0]?.blockSize ?? entries[0].contentRect.height;\n      bottomPart.style.setProperty('--chatlist-overlay-height', height + 'px');\n    }).observe(this.foldersOverlay);\n\n    const storiesListContainer = this.storiesListContainer = document.createElement('div');\n    storiesListContainer.classList.add('stories-list');\n\n    fillForumTabRegister();\n\n    this.forumsTabs = new Map();\n    this.forumsSlider = document.createElement('div');\n    this.forumsSlider.classList.add('topics-slider');\n\n    this.chatsContainer.parentElement.parentElement.append(this.forumsSlider);\n\n    if(IS_TOUCH_SUPPORTED) {\n      handleTabSwipe({\n        element: this.folders.container,\n        onSwipe: (xDiff) => {\n          const folders = useFolders();\n          const prevIndex = folders.selectedFolderIndex();\n          const newIndex = clamp(\n            xDiff < 0 ? prevIndex + 1 : prevIndex - 1,\n            0,\n            folders.folderItems.length - 1\n          );\n          folders.onClick()(newIndex);\n        },\n        verifyTouchTarget: () => {\n          return !this.forumTab;\n        }\n      });\n    }\n\n    this.allChatsIntlElement = new I18n.IntlElement({\n      key: 'FilterAllChatsShort'\n    });\n\n    rootScope.addEventListener('state_cleared', () => {\n      const clearCurrent = REAL_FOLDERS.has(this.filterId);\n      this.xd.loadedDialogsAtLeastOnce = false;\n      this.isFirstDialogsLoad = true;\n      this.showFiltersPromise = undefined;\n\n      if(clearCurrent) {\n        this.xd.clear();\n        this.onTabChange();\n      }\n\n      this.onStateLoaded(useAppState()[0]);\n    });\n\n    createRoot(() => {\n      let scrollableContext: ScrollableContextValue;\n      const element = FoldersTabs({\n        scrollableProps: {\n          class: 'folders-tabs-scrollable hide',\n          ref: (ref) => {\n            this.folders.menuScrollContainer = ref;\n          },\n          scrollableProps: {\n            contextRef: (ref) => scrollableContext = ref\n          }\n        },\n        menuProps: {\n          id: 'folders-tabs',\n          ref: (ref) => {\n            this.folders.menu = ref;\n            this.onRef(scrollableContext);\n          }\n        },\n        gradientProps: {\n          className: 'folders-tabs-gradient',\n          color: 'surface',\n          smaller: true,\n          ref: (ref) => {\n            this.folders.menuGradient = ref;\n            ref.classList.add('hide');\n          }\n        }\n      });\n\n      const resolvedChildren = children(() => element).toArray();\n      this.foldersOverlay.append(...resolvedChildren as any);\n    });\n\n    const [appState] = useAppState();\n    const [appSettings, setAppSettings] = useAppSettings();\n    // * it should've had a better place :(\n    appMediaPlaybackController.setPlaybackParams(unwrap(appSettings.playbackParams));\n    // Persist the normalized params back once — `setPlaybackParams` clamps a stale >1\n    // `volume` to [0, 1] and migrates the excess into the voice-only `boost`, so this\n    // rewrites a corrupted stored value (e.g. volume: 1.04) instead of waiting for a change.\n    setAppSettings('playbackParams', appMediaPlaybackController.getPlaybackParams());\n    appMediaPlaybackController.addEventListener('playbackParams', (params) => {\n      setAppSettings('playbackParams', params);\n    });\n\n    mediaSizes.addEventListener('resize', () => {\n      this.changeFiltersAllChatsKey();\n    });\n\n    this.chatsContainer.append(bottomPart);\n\n    setTimeout(() => {\n      lottieLoader.loadLottieWorkers();\n    }, 200);\n\n    PopupElement.MANAGERS = PopupElementTsx.MANAGERS = rootScope.managers = managers;\n    appDownloadManager.construct(managers);\n    appDownloadManager.showPollCancelConfirmation = (randomId: string) => this.showPollCancelConfirmation(randomId);\n    appSidebarLeft.construct(managers);\n    appSidebarRight.construct(managers);\n    groupCallsController.construct(managers);\n    callsController.construct(managers);\n    conferenceInvitesController.construct(managers);\n    appImManager.construct(managers);\n    if(IS_LIVE_STREAM_SUPPORTED) rtmpCallsController.construct(managers);\n    new ConnectionStatusComponent().construct(managers, this.chatsContainer, appSidebarLeft.inputSearch);\n\n    // start\n\n    this.xd = this.xds[this.filterId];\n\n    appSidebarLeft.onCollapsedChange();\n    this.onStateLoaded(appState);\n  }\n\n  private onRef(scrollableContext: ScrollableContextValue) {\n    this.setFilterId(FOLDER_ID_ALL);\n    this.addFilter({\n      id: FOLDER_ID_ALL,\n      title: {_: 'textWithEntities', text: '', entities: []},\n      localId: FOLDER_ID_ALL\n    });\n\n    const {setSelectedFolderId, onClick, setOnClick, folderItems} = useFolders();\n    const selectFolderByIndex = async(index: number) => {\n      const id = folderItems[index]?.filter.id ?? FOLDER_ID_ALL;\n      const wasFilterId = this.filterId;\n\n      const available = wasFilterId === -1 ||\n        REAL_FOLDERS.has(id) ||\n        (await rootScope.managers.filtersStorage.isFilterIdAvailable(id) ?? true);\n      if(!available) {\n        showLimitPopup('folders');\n        return false;\n      }\n\n      // Switching folders clears whatever is open in the left sidebar — an open\n      // global search and any stacked tabs — mirroring how opening a left-sidebar\n      // tab does it (closeEverythingInside). Both folder UIs (horizontal tabs and\n      // the vertical folders sidebar) funnel through here. Tabs are closed the\n      // natural way (as if via the back arrow), so a tab that needs confirmation\n      // still asks; if the user declines, cancel the folder switch entirely.\n      if(!await appSidebarLeft.closeEverythingInsideNaturally()) {\n        return false;\n      }\n\n      if(!IS_MOBILE_SAFARI) {\n        if(index) {\n          if(!this.filtersNavigationItem) {\n            this.filtersNavigationItem = {\n              type: 'filters',\n              onPop: () => {\n                onClick()(0);\n                this.filtersNavigationItem = undefined;\n              }\n            };\n\n            appNavigationController.spliceItems(1, 0, this.filtersNavigationItem);\n          }\n        } else if(this.filtersNavigationItem) {\n          appNavigationController.removeItem(this.filtersNavigationItem);\n          this.filtersNavigationItem = undefined;\n        }\n      }\n\n      if(wasFilterId === id) {\n        fastSmoothScrollToStart(this.xds[id].scrollable.container, 'y');\n        return;\n      }\n\n      setSelectedFolderId(id);\n\n      this.xds[id].clear();\n      const promise = this.setFilterIdAndChangeTab(id);\n      if(wasFilterId !== -1) {\n        return promise;\n      }\n    };\n\n    this.foldersOverlay.append(this.folders.menuScrollContainer);\n    const selectTab = horizontalMenuObjArgs({\n      tabs: this.folders.menu,\n      content: this.folders.container,\n      onClick: selectFolderByIndex,\n      onTransitionEnd: () => {\n        for(const folderId in this.xds) {\n          if(+folderId !== this.filterId) {\n            this.xds[folderId].clear();\n          }\n        }\n      },\n      scrollableX: scrollableContext,\n      onChange: ({element, active}) => {\n        const renderer: CustomEmojiRendererElement = element?.querySelector('custom-emoji-renderer-element');\n        renderer?.setTextColor(getFolderTitleTextColor(active));\n      }\n    });\n\n    setOnClick(() => selectTab);\n\n    createFolderContextMenu({\n      appSidebarLeft,\n      AppChatFoldersTab,\n      AppEditFolderTab,\n      managers: this.managers,\n      className: 'menu-horizontal-div-item',\n      listenTo: this.folders.menu\n    });\n  }\n\n  private _renderStories() {\n    this.chatsContainer.parentElement.parentElement.firstElementChild.after(this.storiesListContainer);\n    return StoriesList({\n      foldInto: document.querySelector('.item-main .input-search input'),\n      setScrolledOn: this.chatsContainer,\n      getScrollable: () => this.xd.scrollable.container,\n      listenWheelOn: this.bottomPart,\n      offsetX: -1,\n      resizeCallback: (callback) => {\n        this.resizeStoriesList = callback;\n      },\n      onExpand: () => {\n        const container = this.xd.scrollable.container;\n        container.classList.add('scrolled-start');\n        fastSmoothScrollToStart(container, 'y');\n      }\n    });\n  }\n\n  private renderStories() {\n    this.disposeStories = render(() => this._renderStories(), this.storiesListContainer);\n  }\n\n  public get chatList() {\n    return this.xd.sortedList.list;\n  }\n\n  public setFilterId(filterId: number) {\n    this.filterId = filterId;\n  }\n\n  public async setFilterIdAndChangeTab(filterId: number) {\n    this.setFilterId(filterId);\n    return this.onTabChange();\n  }\n\n  private initListeners() {\n    rootScope.addEventListener('folder_unread', async(folder) => {\n      if(folder.id < 0) {\n        const dialogElement = this.xd.getDialogElement(folder.id);\n        if(!dialogElement) {\n          return;\n        }\n\n        this.setUnreadMessagesN({\n          dialog: await this.managers.dialogsStorage.getDialogOnly(folder.id),\n          dialogElement\n        });\n      }\n    });\n\n    rootScope.addEventListener('contacts_update', (userId) => {\n      this.processContact?.(userId.toPeerId());\n    });\n\n    appImManager.addEventListener('peer_changed', ({peerId, threadId, monoforumThreadId, isForum}) => {\n      const options: Parameters<AppImManager['isSamePeer']>[0] = {\n        peerId,\n        monoforumThreadId,\n        threadId: isForum || rootScope.myId ? threadId : undefined\n      };\n\n      const getOptionsForElement = (element: HTMLElement) => {\n        const elementThreadId = +element?.dataset?.threadId || undefined;\n        const elementPeerId = element?.dataset?.peerId?.toPeerId();\n        const monoforumParentPeerId = +element?.dataset?.monoforumParentPeerId || undefined;\n\n        return {\n          peerId: monoforumParentPeerId || elementPeerId,\n          threadId: elementThreadId,\n          monoforumThreadId: monoforumParentPeerId ? elementPeerId : undefined\n        };\n      };\n\n      for(const element of this.lastActiveElements) {\n        if(!appImManager.isSamePeer(getOptionsForElement(element), options)) {\n          this.setDialogActive(element, false);\n        }\n      }\n\n      const dialogElements = [\n        this.xd?.getDialogElement(peerId),\n        this.forumTab?.xd?.getDialogElement(\n          threadId || monoforumThreadId || peerId\n        )\n      ].filter(Boolean);\n\n      dialogElements.forEach(dialogElement => {\n        const element = dialogElement?.dom?.listEl;\n        if(!element) return;\n\n        const optionsForElement = getOptionsForElement(element);\n        if(\n          appImManager.isSamePeer(optionsForElement, options) ||\n          apiManagerProxy.isBotforum(optionsForElement.peerId) && optionsForElement.peerId === options.peerId\n        ) {\n          this.setDialogActive(element, true);\n        }\n      });\n      // this.log('peer_changed total time:', performance.now() - perf);\n    });\n\n    rootScope.addEventListener('filter_update', async(filter) => {\n      if(REAL_FOLDERS.has(filter.id)) {\n        return;\n      }\n\n      if(!this.filtersRendered[filter.id]) {\n        this.addFilter(filter);\n      }\n    });\n\n    rootScope.addEventListener('filter_delete', (filter) => {\n      const elements = this.filtersRendered[filter.id];\n      if(!elements) return;\n\n      elements.topNotification?.dispose();\n      elements.container.remove();\n\n      this.xds[filter.id].destroy();\n      delete this.xds[filter.id];\n      delete this.filtersRendered[filter.id];\n\n      this.onFiltersLengthChange();\n    });\n\n    rootScope.addEventListener('filter_order', async(order) => {\n      order = order.slice();\n      indexOfAndSplice(order, FOLDER_ID_ARCHIVE);\n\n      const r = await Promise.all(order.map(async(filterId) => {\n        const [indexKey, filter] = await Promise.all([\n          this.managers.dialogsStorage.getDialogIndexKeyByFilterId(filterId),\n          this.managers.filtersStorage.getFilter(filterId)\n        ]);\n\n        return {indexKey, filter};\n      }));\n\n      order.forEach((filterId, idx) => {\n        const {indexKey, filter} = r[idx];\n        const renderedFilter = this.filtersRendered[filterId];\n\n        this.xds[filterId].setIndexKey(indexKey);\n\n        positionElementByIndex(renderedFilter.container, this.folders.container, filter.localId);\n      });\n    });\n  }\n\n  public getTextColor(active: boolean) {\n    return active ? 'white' : 'secondary-text-color';\n  }\n\n  public getPrimaryColor(active: boolean) {\n    return active ? 'white' : 'primary-color';\n  }\n\n  public setDialogActiveStatus(listEl: HTMLElement, active: boolean) {\n    listEl.classList.toggle('active', active);\n\n    const customEmojiRenderers = listEl.querySelectorAll<CustomEmojiRendererElement>('.custom-emoji-renderer');\n    customEmojiRenderers.forEach((customEmojiRenderer) => {\n      customEmojiRenderer.setTextColor(this.getTextColor(active));\n    });\n\n    const dom = (listEl as any).dialogDom as DialogDom;\n    if(dom?.titleWrapOptions) {\n      dom.titleWrapOptions.textColor = this.getTextColor(active);\n    }\n\n    changeTitleEmojiColor(listEl, this.getPrimaryColor(active));\n\n    // the subtitle's text spoilers are painted on a canvas — CSS can't recolor them\n    DotRenderer.setInlineSpoilersTextColor(listEl, this.getTextColor(active));\n  }\n\n  public setDialogActive(listEl: HTMLElement, active: boolean) {\n    const dom = (listEl as any).dialogDom as DialogDom;\n    this.setDialogActiveStatus(listEl, active);\n    listEl.classList.toggle(\n      'is-forum-open',\n      this.forumTab?.peerId === listEl.dataset.peerId.toPeerId() &&\n        !listEl.dataset.threadId &&\n        !listEl.dataset.isAllChats);\n    if(active) {\n      this.lastActiveElements.add(listEl);\n    } else {\n      this.lastActiveElements.delete(listEl);\n    }\n\n    if(dom?.callIcon) {\n      dom.callIcon.setActive(active);\n    }\n  }\n\n  private async onStateLoaded(state: State) {\n    this.stateMiddlewareHelper.clean();\n    const middleware = this.stateMiddlewareHelper.get();\n    const filtersArr = state.filtersArr;\n    const haveFilters = filtersArr.length > REAL_FOLDERS.size;\n    // const filter = filtersArr.find((filter) => filter.id !== FOLDER_ID_ARCHIVE);\n\n    this.disposeStories?.();\n    this.disposeStories =\n      this.resizeStoriesList =\n      undefined;\n\n    const {onClick: _onClick, hydrateFilters} = useFolders();\n    const onClick = untrack(_onClick);\n\n    const addFilters = async(filters: MyDialogFilter[]) => {\n      for(const filter of filters) {\n        this.addFilter(filter);\n      }\n\n      await untrack(() => hydrateFilters(filters));\n    };\n\n    let addFiltersPromise: Promise<any>;\n    if(haveFilters) {\n      await addFilters(filtersArr);\n    } else {\n      addFiltersPromise = this.managers.filtersStorage.getDialogFilters().then(addFilters);\n    }\n\n    this.doNotRenderChatList = true;\n    this.isFirstDialogsLoad = true;\n\n    const wrapPromiseWithMiddleware = middlewarePromise(middleware);\n    try {\n      await wrapPromiseWithMiddleware(this.xd.preloadDialogs());\n    } catch(err) {\n\n    }\n\n    // show the placeholder before the filters, and then will reset to the default tab again\n    if(!haveFilters) {\n      onClick(0, false);\n    }\n\n    addFiltersPromise && await wrapPromiseWithMiddleware(addFiltersPromise);\n\n    this.renderStories();\n    this.doNotRenderChatList = undefined;\n\n    this.filterId = -1;\n    onClick(0, false);\n\n    if(!this.initedListeners) {\n      this.initListeners();\n      this.initedListeners = true;\n    }\n\n    haveFilters && this.showFiltersPromise && await wrapPromiseWithMiddleware(this.showFiltersPromise);\n\n    this.managers.appNotificationsManager.getNotifyPeerTypeSettings();\n\n    // await (await m(loadDialogsPromise)).renderPromise.catch(noop);\n    this.managers.appMessagesManager.fillConversations();\n\n    if(!this.suggestionContainer) {\n      this.suggestionContainer = document.createElement('div');\n      this.foldersOverlay.prepend(this.suggestionContainer);\n      renderPendingSuggestion(this.suggestionContainer);\n    }\n\n    if(!this.authorizationContainer) {\n      this.authorizationContainer = document.createElement('div');\n      this.foldersOverlay.prepend(this.authorizationContainer);\n      renderNewAuthorization(this.authorizationContainer);\n    }\n  }\n\n  public onTabChange = () => {\n    const {filterId} = this;\n    this.xd = this.xds[filterId];\n    this.xd.reset();\n\n    this.cancelChatlistUpdatesFetching?.();\n    this.cancelChatlistUpdatesFetching = undefined;\n    this.fetchChatlistUpdates = undefined;\n\n    const promise = this.xd.onChatsScroll();\n\n    if(!REAL_FOLDERS.has(filterId)) {\n      Promise.all([\n        this.managers.filtersStorage.getFilter(filterId),\n        this.managers.apiManager.getAppConfig()\n        // promise.then(({renderPromise}) => renderPromise).catch(() => {})\n      ]).then(([filter, appConfig]) => {\n        if(TEST_TOP_NOTIFICATION ? false : filter?._ !== 'dialogFilterChatlist' || this.filterId !== filterId) {\n          return;\n        }\n\n        const updatePeriod = (appConfig.chatlist_update_period ?? 3600) * 1000;\n        const filterRendered = this.filtersRendered[filterId];\n        let updatedTime = filterRendered.topNotification && !TEST_TOP_NOTIFICATION ?\n          (filter as DialogFilter.dialogFilterChatlist).updatedTime || 0 :\n          0;\n        let fetching = false;\n\n        this.fetchChatlistUpdates = () => {\n          updatedTime = Date.now();\n\n          if(fetching) {\n            return;\n          }\n\n          fetching = true;\n          const promise = TEST_TOP_NOTIFICATION ?\n            Promise.resolve(TEST_TOP_NOTIFICATION()) :\n            this.managers.filtersStorage.getChatlistUpdates(filterId);\n          promise.catch(() => undefined as ChatlistsChatlistUpdates)\n          .then((chatlistUpdates) => {\n            if(this.filterId !== filterId || this.filtersRendered[filterId] !== filterRendered) {\n              return;\n            }\n\n            const length = chatlistUpdates ? chatlistUpdates.missing_peers.length : 0;\n            if(length) {\n              this.createTopNotification(filterRendered);\n              filterRendered.topNotificationData = {\n                _: 'chatlistUpdates',\n                chatlistUpdates\n              };\n\n              const topNotification = filterRendered.topNotification;\n\n              const tt = i18n('ChatsNew', [length]);\n              tt.classList.add('primary');\n              const t = i18n('ChatList.SharedFolder.Title', [tt]);\n              topNotification.setTitle(t);\n              topNotification.setSubtitle(i18n('ChatList.SharedFolder.Subtitle'));\n            }\n\n            this.toggleTopNotification(filterRendered, !!length);\n          }).finally(() => {\n            fetching = false;\n          });\n        };\n\n        this.cancelChatlistUpdatesFetching = eachTimeout(this.fetchChatlistUpdates, () => {\n          const elapsedTime = Date.now() - updatedTime;\n          return updatePeriod - elapsedTime;\n        }, false);\n      });\n    }\n\n    return promise;\n  };\n\n  public l(filter: Parameters<AppDialogsManager['addFilter']>[0]) {\n    const xd = this.xds[filter.id] = new AutonomousDialogList({filterId: filter.id, appDialogsManager: this});\n    const {scrollable, list} = xd.generateScrollable(filter);\n    this.setListClickListener({list, onFound: null, withContext: true, withArchiveContext: filter.id === FOLDER_ID_ALL});\n\n    return {ul: list, xd, scrollable};\n  }\n\n  private createTopNotification(filterRendered: FilterRendered) {\n    if(filterRendered.topNotification) return;\n\n    const topNotificationContainer = filterRendered.topNotificationContainer = document.createElement('div');\n    topNotificationContainer.classList.add('chatlist-top-notification-container');\n    filterRendered.topNotification = renderChatlistTopNotification(topNotificationContainer, {\n      onClick: async() => {\n        const data = filterRendered.topNotificationData;\n        if(data._ === 'chatlistUpdates') {\n          PopupElement.createPopup(PopupSharedFolderInvite, {\n            chatlistInvite: {\n              ...data.chatlistUpdates,\n              already_peers: [],\n              _: 'chatlists.chatlistInviteAlready',\n              filter_id: filterRendered.id\n            },\n            updating: true\n          });\n        }\n      },\n      contextMenu: {\n        buttons: [{\n          icon: 'hide',\n          text: 'HideAboveTheList',\n          onClick: () => {\n            this.managers.filtersStorage.hideChatlistUpdates(filterRendered.id).then(() => {\n              if(this.filterId === filterRendered.id) {\n                this.fetchChatlistUpdates?.();\n              }\n            });\n          },\n          verify: () => filterRendered.topNotificationData?._ === 'chatlistUpdates'\n        }]\n      }\n    });\n  }\n\n  private toggleTopNotification(filterRendered: FilterRendered, forwards: boolean) {\n    if(!forwards && !filterRendered.topNotification) {\n      return;\n    }\n\n    let isMounted = true;\n    if(forwards) {\n      isMounted = !!filterRendered.topNotificationContainer.parentElement;\n      if(!isMounted) {\n        filterRendered.scrollable.prepend(filterRendered.topNotificationContainer);\n      }\n    }\n\n    SetTransition({\n      element: filterRendered.topNotificationContainer,\n      className: 'is-visible',\n      duration: 250,\n      forwards,\n      useRafs: isMounted ? 0 : 2,\n      onTransitionEnd: forwards ? undefined : () => {\n        filterRendered.topNotification.dispose();\n        filterRendered.topNotificationContainer.remove();\n        filterRendered.topNotification =\n          filterRendered.topNotificationContainer =\n          filterRendered.topNotificationData = undefined;\n      }\n    });\n  }\n\n  private addFilter(filter: Pick<MyDialogFilter, 'title' | 'id' | 'localId'>) {\n    const {id} = filter;\n    if(id === FOLDER_ID_ARCHIVE) {\n      return;\n    }\n\n    const renderedFilter = this.filtersRendered[id];\n    if(renderedFilter) {\n      positionElementByIndex(renderedFilter.container, this.folders.container, filter.localId);\n      return;\n    }\n\n    const {ul, scrollable} = this.l(filter);\n    scrollable.container.classList.add('tabs-tab', 'chatlist-parts', 'folders-scrollable');\n    scrollable.attachBorderListeners();\n\n    /* const parts = document.createElement('div');\n    parts.classList.add('chatlist-parts'); */\n\n    const top = document.createElement('div');\n    top.classList.add('chatlist-top');\n\n    const bottom = document.createElement('div');\n    bottom.classList.add('chatlist-bottom');\n\n    top.append(ul);\n    scrollable.append(top, bottom);\n    /* parts.append(top, bottom);\n    scrollable.container.append(parts); */\n\n    const div = scrollable.container;\n    // this.folders.container.append(div);\n    positionElementByIndex(scrollable.container, this.folders.container, filter.localId);\n\n    this.filtersRendered[id] = {\n      id,\n      container: div,\n      scrollable\n    };\n\n    this.onFiltersLengthChange();\n  }\n\n  private changeFiltersAllChatsKey() {\n    const scrollable = this.folders.menuScrollContainer.firstElementChild;\n    const key: LangPackKey = scrollable.scrollWidth > scrollable.clientWidth ? 'FilterAllChatsShort' : 'FilterAllChats';\n    this.allChatsIntlElement.compareAndUpdate({key});\n  }\n\n  private onFiltersLengthChange() {\n    let promise = this.showFiltersPromise;\n    return promise ??= this.showFiltersPromise = pause(0).then(() => {\n      if(this.showFiltersPromise !== promise) {\n        return;\n      }\n\n      const length = Object.keys(this.filtersRendered).length;\n      const show = length > 1;\n      const wasShowing = !this.folders.menuScrollContainer.classList.contains('hide');\n\n      if(show !== wasShowing) {\n        this.folders.menuScrollContainer.classList.toggle('hide', !show);\n        this.folders.menuGradient.classList.toggle('hide', !show);\n        this.chatsContainer.classList.toggle('has-filters', show);\n      }\n\n      const [, setHasFolders] = useHasFolders();\n      setHasFolders(show);\n\n      this.changeFiltersAllChatsKey();\n\n      this.showFiltersPromise = undefined;\n    });\n  }\n\n  private generateEmptyPlaceholder(options: {\n    title: LangPackKey,\n    subtitle?: LangPackKey,\n    subtitleArgs?: FormatterArguments,\n    classNameType: string\n  }) {\n    const BASE_CLASS = 'empty-placeholder';\n    const container = document.createElement('div');\n    container.classList.add(BASE_CLASS, BASE_CLASS + '-' + options.classNameType);\n\n    const header = document.createElement('div');\n    header.classList.add(BASE_CLASS + '-header');\n    _i18n(header, options.title);\n\n    const subtitle = document.createElement('div');\n    subtitle.classList.add(BASE_CLASS + '-subtitle');\n    if(options.subtitle) {\n      _i18n(subtitle, options.subtitle, options.subtitleArgs);\n    }\n\n    container.append(header, subtitle);\n\n    return {container, header, subtitle};\n  }\n\n  private checkIfPlaceholderNeeded() {\n    if(this.filterId === FOLDER_ID_ARCHIVE) {\n      return;\n    }\n\n    const chatList = this.chatList;\n    const part = chatList.parentElement as HTMLElement;\n    let placeholderContainer = (Array.from(part.children) as HTMLElement[]).find((el) => el.matches('.empty-placeholder'));\n    // const needPlaceholder = this.xd.scrollable.loadedAll.bottom && !chatList.childElementCount || true;\n    const needPlaceholder = !this.xd.sortedList.itemsLength();\n    // chatList.style.display = 'none';\n\n    if(needPlaceholder && placeholderContainer) {\n      return;\n    } else if(!needPlaceholder) {\n      if(placeholderContainer) {\n        part.classList.remove('with-placeholder');\n        placeholderContainer.remove();\n      }\n\n      return;\n    }\n\n    let placeholder: ReturnType<AppDialogsManager['generateEmptyPlaceholder']>, type: 'dialogs' | 'folder';\n    if(!this.filterId) {\n      placeholder = this.generateEmptyPlaceholder({\n        title: 'ChatList.Main.EmptyPlaceholder.Title',\n        classNameType: type = 'dialogs'\n      });\n\n      placeholderContainer = placeholder.container;\n\n      const img = document.createElement('img');\n      img.classList.add('empty-placeholder-dialogs-icon');\n\n      this.emptyDialogsPlaceholderSubtitle = new I18n.IntlElement({\n        element: placeholder.subtitle\n      });\n\n      Promise.all([\n        this.updateContactsLength(false),\n        renderImageFromUrlPromise(img, 'assets/img/EmptyChats.svg'),\n        fastRafPromise()\n      ]).then(([usersLength]) => {\n        placeholderContainer.classList.add('visible');\n        part.classList.toggle('has-contacts', !!usersLength);\n      });\n\n      placeholderContainer.prepend(img);\n    } else {\n      placeholder = this.generateEmptyPlaceholder({\n        title: 'FilterNoChatsToDisplay',\n        subtitle: 'FilterNoChatsToDisplayInfo',\n        classNameType: type = 'folder'\n      });\n\n      placeholderContainer = placeholder.container;\n\n      const div = document.createElement('div');\n      const emoji = '📂';\n      const size = 128;\n      wrapStickerEmoji({\n        div,\n        emoji: emoji,\n        width: size,\n        height: size\n      });\n\n      placeholderContainer.prepend(div);\n\n      const button = Button('btn-primary btn-color-primary btn-control', {\n        text: 'FilterHeaderEdit',\n        icon: 'settings'\n      });\n\n      attachClickEvent(button, async() => {\n        const filter = await this.managers.filtersStorage.getFilter(this.filterId);\n        appSidebarLeft.createTab(AppEditFolderTab).open({...AppEditFolderTab.getInitArgs(), initFilter: filter});\n      });\n\n      placeholderContainer.append(button);\n    }\n\n    part.append(placeholderContainer);\n    part.classList.add('with-placeholder');\n    part.dataset.placeholderType = type;\n  }\n\n  private updateContactsLength(updatePartClassName: boolean) {\n    return this.updateContactsLengthPromise ??= this.managers.appUsersManager.getContacts().then((users) => {\n      const subtitle = this.emptyDialogsPlaceholderSubtitle;\n      if(subtitle) {\n        let key: LangPackKey, args: FormatterArguments;\n\n        if(users.length/*  && false */) {\n          key = 'ChatList.Main.EmptyPlaceholder.Subtitle';\n          args = [i18n('Contacts.Count', [users.length])];\n        } else {\n          key = 'ChatList.Main.EmptyPlaceholder.SubtitleNoContacts';\n          args = [];\n        }\n\n        subtitle.compareAndUpdate({\n          key,\n          args\n        });\n      }\n\n      if(updatePartClassName) {\n        const chatList = this.chatList;\n        const part = chatList.parentElement as HTMLElement;\n        part.classList.toggle('has-contacts', !!users.length);\n      }\n\n      this.updateContactsLengthPromise = undefined;\n\n      return users.length;\n    });\n  }\n\n  private removeContactsPlaceholder() {\n    const chatList = this.chatList;\n    const parts = chatList.parentElement.parentElement;\n    const bottom = chatList.parentElement.nextElementSibling as HTMLElement;\n    parts.classList.remove('with-contacts');\n    bottom.replaceChildren();\n    this.loadContacts = undefined;\n    this.processContact = undefined;\n  }\n\n  private _onListLengthChange = () => {\n    this.checkIfPlaceholderNeeded();\n\n    if(this.filterId !== FOLDER_ID_ALL) return;\n\n    // return;\n    const chatList = this.chatList;\n    const count = this.xd?.sortedList.itemsLength() || 0;\n\n    const parts = chatList.parentElement.parentElement;\n    const bottom = chatList.parentElement.nextElementSibling as HTMLElement;\n    const hasContacts = !!bottom.childElementCount;\n\n    if(count >= 10) {\n      if(hasContacts) {\n        this.removeContactsPlaceholder();\n      }\n\n      return;\n    } else if(hasContacts) return;\n\n    parts.classList.add('with-contacts');\n\n    const section = new SettingSection({\n      name: 'Contacts',\n      noDelimiter: true,\n      fakeGradientDelimiter: true\n    });\n\n    section.container.classList.add('sidebar-left-contacts-section', 'hide');\n\n    this.managers.appUsersManager.getContactsPeerIds(undefined, undefined, 'online').then((contacts) => {\n      let ready = false;\n      const onListLengthChange = () => {\n        if(ready) {\n          section.container.classList.toggle('hide', !sortedUserList.list.childElementCount);\n        }\n\n        this.updateContactsLength(true);\n      };\n\n      const sortedUserList = new SortedUserList({\n        avatarSize: 'abitbigger',\n        createChatListOptions: {\n          dialogSize: 48,\n          new: true\n        },\n        autonomous: false,\n        onListLengthChange,\n        managers: this.managers,\n        middleware: undefined\n      });\n\n      this.loadContacts = () => {\n        const pageCount = windowSize.height / 60 | 0;\n        const promise = filterAsync(contacts.splice(0, pageCount), this.verifyPeerIdForContacts);\n\n        promise.then((arr) => {\n          arr.forEach((peerId) => {\n            sortedUserList.add(peerId);\n          });\n        });\n\n        if(!contacts.length) {\n          this.loadContacts = undefined;\n        }\n      };\n\n      this.loadContacts();\n\n      this.processContact = async(peerId) => {\n        if(peerId.isAnyChat()) {\n          return;\n        }\n\n        const good = await this.verifyPeerIdForContacts(peerId);\n        const added = sortedUserList.has(peerId);\n        if(!added && good) sortedUserList.add(peerId);\n        else if(added && !good) sortedUserList.delete(peerId);\n      };\n\n      const list = sortedUserList.list;\n      list.classList.add('chatlist-new');\n      this.setListClickListener({list});\n      section.content.append(list);\n\n      ready = true;\n      onListLengthChange();\n    });\n\n    bottom.append(section.container);\n  };\n\n  private verifyPeerIdForContacts = async(peerId: PeerId) => {\n    const [isContact, dialog] = await Promise.all([\n      this.managers.appPeersManager.isContact(peerId),\n      this.managers.appMessagesManager.getDialogOnly(peerId)\n    ]);\n\n    return isContact && !dialog;\n  };\n\n  public onSomeDrawerToggle?: () => void;\n\n  public async toggleForumTab(newTab?: ForumTab, hideTab = this.forumTab) {\n    if(!hideTab && !newTab) {\n      return;\n    }\n\n    if(hideTab) {\n      this.xd.getListElement(hideTab.peerId)\n      ?.classList.remove('is-forum-open');\n    }\n\n    if(hideTab === newTab) {\n      newTab = undefined;\n    }\n\n    if(newTab) {\n      appSidebarLeft.closeSearch();\n    }\n\n    hideTab?.toggle(false);\n    const promise = newTab?.toggle(true);\n    if(hideTab === this.forumTab) {\n      this.forumTab = newTab;\n      this.onSomeDrawerToggle?.();\n    }\n\n    if(newTab) {\n      this.xd.getListElement(newTab.peerId)\n      ?.classList.add('is-forum-open');\n\n      appImManager.selectTab(APP_TABS.CHATLIST);\n    }\n\n    if(promise) {\n      await promise;\n    }\n\n    if(newTab && !this.forumNavigationItem) {\n      this.forumNavigationItem = {\n        type: 'forum',\n        onPop: () => {\n          this.forumNavigationItem = undefined;\n          this.toggleForumTab();\n        }\n      };\n\n      appNavigationController.pushItem(this.forumNavigationItem);\n    } else if(!newTab && this.forumNavigationItem) {\n      appNavigationController.removeItem(this.forumNavigationItem);\n      this.forumNavigationItem = undefined;\n    }\n\n    const forwards = !!newTab;\n    const useRafs = promise ? 2 : undefined;\n    this.xd.toggleAvatarUnreadBadges(forwards, useRafs);\n\n    this.transitionDrawersParent(forwards, useRafs);\n  }\n\n  private transitionDrawersParent(forwards: boolean, useRafs?: number) {\n    const deferred = deferredPromise<void>();\n    const duration = 300;\n    SetTransition({\n      element: appSidebarLeft.sidebarEl,\n      className: 'is-forum-visible',\n      duration,\n      forwards,\n      useRafs,\n      onTransitionEnd: () => {\n        deferred.resolve();\n      }\n    });\n\n    dispatchHeavyAnimationEvent(deferred, duration).then(() => deferred.resolve());\n  }\n\n  public hasForumOpenFor(peerId: PeerId) {\n    return !!this.forumsTabs.get(peerId);\n  }\n\n  public toggleForumTabByPeerId(\n    peerId: PeerId,\n    show?: boolean,\n    asInnerIfAsMessages?: boolean,\n    ForumTabConstructorOverride?: typeof ForumTab\n  ) {\n    const previousPromise = this.forumTabByPeerIdPromises.get(peerId);\n    const run = () => this.toggleForumTabByPeerIdInternal(\n      peerId,\n      show,\n      asInnerIfAsMessages,\n      ForumTabConstructorOverride\n    );\n    const promise = previousPromise ?\n      previousPromise.then(run, run) :\n      run();\n    this.forumTabByPeerIdPromises.set(peerId, promise);\n\n    const cleanup = () => {\n      if(this.forumTabByPeerIdPromises.get(peerId) === promise) {\n        this.forumTabByPeerIdPromises.delete(peerId);\n      }\n    };\n    promise.then(cleanup, cleanup);\n    return promise;\n  }\n\n  private async toggleForumTabByPeerIdInternal(\n    peerId: PeerId,\n    show?: boolean,\n    asInnerIfAsMessages?: boolean,\n    ForumTabConstructorOverride?: typeof ForumTab\n  ) {\n    if(peerId === rootScope.myId) {\n      const tab = appSidebarLeft.getTab(AppSharedMediaTab);\n      if(show === true || (show === undefined && !tab)) {\n        AppSharedMediaTab.open(appSidebarLeft, peerId, true);\n      } else {\n        if(tab?.peerId === peerId) {\n          tab.close();\n        }\n\n        appImManager.setPeer({peerId});\n      }\n\n      return;\n    }\n\n    const {managers} = this;\n    const chat = !peerId.isUser() ?\n      apiManagerProxy.getChat(peerId.toChatId()) :\n      undefined;\n    const community = isCommunityChat(chat) ? chat : undefined;\n    const isCommunity = !!community;\n    const canOpenCommunity = community?._ === 'communityForbidden' ||\n      (\n        community?._ === 'community' &&\n        !community.pFlags.left\n      );\n    let ForumTabConstructor = ForumTabConstructorOverride;\n    if(!ForumTabConstructor) {\n      if(canOpenCommunity) {\n        ({CommunityForumTab: ForumTabConstructor} = await import(\n          '@components/forumTab/communityForumTab'\n        ));\n      } else {\n        ForumTabConstructor = ForumTab.register.getEntry(peerId);\n      }\n    }\n    if(!ForumTabConstructor) return;\n\n    const dialog = await managers.dialogsStorage.getDialogOnly(peerId);\n    const viewAsMessages = dialog && !!dialog.pFlags.view_forum_as_messages;\n    if(viewAsMessages) {\n      const isSamePeer = appImManager.chat?.peerId === peerId;\n      appImManager[isSamePeer || !asInnerIfAsMessages ? 'setPeer' : 'setInnerPeer']({\n        type: ChatType.Chat,\n        peerId\n      });\n      return;\n    }\n\n    const history = appSidebarLeft.getHistory();\n    const lastTab = history[history.length - 1];\n    let forumTab: ForumTab;\n    const asNavigationTab = shouldOpenForumAsNavigationTab({\n      hasNavigationHistory: !!lastTab,\n      isCommunity,\n      isNarrowScreen: mediaSizes.isLessThanFloatingLeftSidebar\n    });\n    if(asNavigationTab) {\n      const isSameTab = lastTab instanceof ForumTab &&\n        lastTab.peerId === peerId;\n      const existingTab = findForumTabByPeerId(history, peerId);\n      if(show === false) {\n        if(isSameTab) {\n          lastTab.close();\n        }\n        return;\n      }\n\n      if(isSameTab) {\n        appSidebarLeft.closeSearch();\n        if(show) {\n          shake(lastTab.container);\n        }\n        return;\n      }\n\n      if(existingTab) {\n        if(!await appSidebarLeft.closeTabsUntilTab(existingTab)) {\n          return;\n        }\n\n        appSidebarLeft.closeSearch();\n        return;\n      }\n\n      forumTab = appSidebarLeft.createTab(ForumTabConstructor);\n      appSidebarLeft.closeSearch();\n      const openPromise = forumTab.open({peerId, managers});\n      if(isCommunity && mediaSizes.isLessThanFloatingLeftSidebar) {\n        appImManager.selectTab(APP_TABS.CHATLIST);\n      }\n      await openPromise;\n      return;\n    }\n\n    forumTab = this.forumsTabs.get(peerId);\n    const isSameTab = this.forumTab && this.forumTab === forumTab;\n    show ??= !isSameTab;\n    if(show === isSameTab) {\n      if(show) {\n        appSidebarLeft.closeSearch();\n        shake(forumTab.container);\n      }\n\n      return;\n    }\n\n    if(show && !forumTab) {\n      forumTab = new ForumTabConstructor(undefined);\n      forumTab.init({peerId, managers});\n\n      this.forumsTabs.set(peerId, forumTab);\n      this.forumsSlider.append(forumTab.container);\n\n      forumTab.managers = this.managers;\n      forumTab.eventListener.addEventListener('destroy', () => {\n        this.forumsTabs.delete(peerId);\n      });\n    }\n\n    return this.toggleForumTab(forumTab);\n  }\n\n  public openDialogInNewTab(element: HTMLElement) {\n    const peerId = element.dataset.peerId.toPeerId();\n    const lastMsgId = +element.dataset.mid || undefined;\n    const threadId = +element.dataset.threadId || undefined;\n\n    const params = new URLSearchParams();\n    params.set('p', '' + peerId);\n    const communityId = +element.dataset.communityId || undefined;\n    if(communityId && peerId === communityId.toChatId().toPeerId(true)) {\n      params.set('community', '1');\n    }\n    if(lastMsgId) params.set('message', '' + lastMsgId);\n    if(threadId) params.set('thread', '' + threadId);\n    const url = `#/im?${params.toString()}`;\n    window.open(url, '_blank');\n  }\n\n  public setListClickListener({\n    list,\n    onFound,\n    withContext = false,\n    withArchiveContext = false,\n    autonomous = false,\n    openInner = false\n  }: {\n    list: HTMLElement,\n    onFound?: (target: HTMLElement) => void | boolean,\n    withContext?: boolean,\n    withArchiveContext?: boolean,\n    autonomous?: boolean,\n    openInner?: boolean\n  }) {\n    let lastActiveListElement: HTMLElement;\n\n    const setPeerFunc = (openInner ? appImManager.setInnerPeer : appImManager.setPeer).bind(appImManager);\n\n    const findAvatarWithStories = (target: EventTarget) => {\n      return (target as HTMLElement).closest('.avatar.has-stories') as HTMLElement;\n    };\n\n    const getOpenStoryCallback = (target: EventTarget) => {\n      const avatar = findAvatarWithStories(target);\n\n      if(avatar) return () => {\n        appImManager.openStoriesFromAvatar(avatar);\n      };\n\n      const archiveAvatar = (target as HTMLElement).closest('.archive-dialog-with-stories') as HTMLElement;\n      const archiveDialog = (target as HTMLElement).closest(archiveDialogTagName);\n\n      if(archiveAvatar && archiveDialog instanceof ArchiveDialog) return () => {\n        archiveDialog.controls?.openStory?.();\n      };\n    }\n\n    const isOpeningStoriesDisabled = () => appSidebarLeft.isCollapsed() && !appSidebarLeft.hasSomethingOpenInside();\n\n    let willOpenStory = false;\n\n    const setWillOpenStory = (e: Event) => willOpenStory = !isOpeningStoriesDisabled() && !!getOpenStoryCallback(e.target);\n    const isDialogListAction = (target: EventTarget) => {\n      return !!(target as HTMLElement).closest?.('[data-dialog-list-action]');\n    };\n\n    list.dataset.autonomous = '' + +autonomous;\n    list.addEventListener('mousedown', (e) => {\n      if(\n        e.button !== 0 ||\n        setWillOpenStory(e) ||\n        isDialogListAction(e.target)\n      ) {\n        return;\n      }\n\n      this.log('dialogs click list');\n      const target = e.target as HTMLElement;\n\n      const archiveElem = findUpTag(target, archiveDialogTagName);\n      if(archiveElem) {\n        appSidebarLeft.openArchiveTab();\n        return;\n      }\n\n      const elem = findDialogListElement(target);\n\n      if(!elem) {\n        return;\n      }\n\n      const peerId = elem.dataset.peerId.toPeerId();\n      const lastMsgId = +elem.dataset.mid || undefined;\n      const threadId = +elem.dataset.threadId || undefined;\n      const monoforumParentPeerId = +elem.dataset.monoforumParentPeerId || undefined;\n      const searchQuery = lastMsgId ? elem.dataset.searchQuery : undefined;\n\n      const openChat = () => setPeerFunc({\n        peerId: monoforumParentPeerId || peerId,\n        monoforumThreadId: monoforumParentPeerId ? peerId : undefined,\n        lastMsgId,\n        threadId: threadId,\n        highlight: searchQuery ? {type: 'search', query: searchQuery} : undefined\n      });\n\n      const isSponsored = elem.dataset.sponsored === 'true';\n      if(isSponsored) {\n        const chip = elem.querySelector('.sponsored-peer-chip');\n        // if click was inside chip, open menu\n        const rect = chip.getBoundingClientRect();\n        if(e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom) {\n          if(!IS_TOUCH_SUPPORTED) {\n            simulateClickEvent(chip as HTMLElement);\n          }\n          return;\n        }\n      }\n\n      if(onFound?.(elem) === false) {\n        return;\n      }\n\n      const community = !peerId.isUser() ?\n        apiManagerProxy.getChat(peerId.toChatId()) :\n        undefined;\n      if(\n        community?._ === 'community' &&\n        !community.pFlags.left &&\n        !threadId\n      ) {\n        if(e.ctrlKey || e.metaKey) {\n          this.openDialogInNewTab(elem);\n          cancelEvent(e);\n          return;\n        }\n\n        const isFromRightSidebar = appSidebarRight.sidebarEl.contains(elem);\n        this.toggleForumTabByPeerId(\n          peerId,\n          isFromRightSidebar ? true : undefined,\n          false\n        );\n        return;\n      }\n\n      // Shift+click → floating chat preview (tdesktop-style). Bypasses chat selection and\n      // forum-tab toggling. Ctrl/Cmd (new-tab) takes precedence and is handled below.\n      // Snapshot the anchor *now* — virtual scroll reuses DOM nodes and may yank this\n      // element offscreen by the time the popup constructor runs.\n      if(e.shiftKey && !e.ctrlKey && !e.metaKey && !autonomous) {\n        showChatPreviewPopup({\n          peerId: monoforumParentPeerId || peerId,\n          monoforumThreadId: monoforumParentPeerId ? peerId : undefined,\n          threadId,\n          lastMsgId,\n          anchor: chatPreviewAnchorFromDialogRow(elem)\n        });\n        cancelEvent(e);\n        return;\n      }\n\n      const peer = apiManagerProxy.getPeer(peerId);\n\n      const linkedChat = peer?._ === 'channel' && peer?.pFlags?.monoforum && peer?.linked_monoforum_id ?\n        apiManagerProxy.getChat(peer.linked_monoforum_id) :\n        undefined;\n\n      if(\n        linkedChat?._ === 'channel' &&\n        linkedChat?.admin_rights?.pFlags?.manage_direct_messages &&\n        !elem.dataset.isAllChats &&\n        !lastMsgId &&\n        !e.shiftKey\n      ) {\n        this.toggleForumTabByPeerId(peerId).then(() => {\n          if(appImManager.chat?.peerId?.toChatId() !== linkedChat?.id && !mediaSizes.isLessThanFloatingLeftSidebar) openChat();\n        });\n        return;\n      }\n\n\n      if(peer?._ === 'user' && peer?.pFlags?.bot_forum_view && !lastMsgId && !threadId && !elem.dataset.isAllChats && !e.shiftKey) {\n        this.toggleForumTabByPeerId(peerId).then(() => {\n          if(appImManager.chat?.peerId?.toUserId() !== peer.id && !mediaSizes.isLessThanFloatingLeftSidebar) openChat();\n        });\n        return;\n      }\n\n      const isForum = !!elem.querySelector('.is-forum');\n      if(isForum && !e.shiftKey && !lastMsgId) {\n        this.toggleForumTabByPeerId(peerId, undefined, false);\n        return;\n      }\n\n      if(e.ctrlKey || e.metaKey) {\n        // TODO: How about opening a monoforum in new tab?\n        this.openDialogInNewTab(elem);\n        cancelEvent(e);\n        return;\n      }\n\n      if(autonomous) {\n        const sameElement = lastActiveListElement === elem;\n        if(lastActiveListElement && !sameElement) {\n          this.setDialogActiveStatus(lastActiveListElement, false);\n        }\n\n        if(elem) {\n          this.setDialogActiveStatus(elem, true);\n          lastActiveListElement = elem;\n          this.lastActiveElements.add(elem);\n        }\n      }\n\n      if(\n        (!threadId && !monoforumParentPeerId || lastMsgId) &&\n        this.xd.sortedList.list === list &&\n        this.xd !== this.xds[FOLDER_ID_ARCHIVE]\n      ) {\n        this.toggleForumTab();\n      }\n\n      openChat();\n    }, {capture: true});\n\n    // cancel link click\n    // ! do not change it to attachClickEvent\n    list.addEventListener('click', (e) => {\n      if(isDialogListAction(e.target)) {\n        return;\n      }\n\n      if(e.button === 0) {\n        cancelEvent(e);\n      }\n\n      if(!willOpenStory || isOpeningStoriesDisabled()) return;\n\n      const callback = getOpenStoryCallback(e.target);\n      callback?.();\n    }, {capture: true});\n\n    if(withContext) {\n      this.contextMenu.attach(list);\n    }\n\n    if(withArchiveContext) {\n      createArchiveDialogContextMenu({\n        element: list\n      });\n    }\n  }\n\n  public createChatList(options: {\n    // avatarSize?: number,\n    // handheldsSize?: number,\n    // size?: number,\n    new?: boolean,\n    dialogSize?: number,\n    ignoreClick?: boolean\n  } = {}) {\n    const list = document.createElement('ul');\n    list.classList.add('chatlist'/* ,\n      'chatlist-avatar-' + (options.avatarSize || 54) *//* , 'chatlist-' + (options.size || 72) */);\n\n    if(options.new) {\n      list.classList.add('chatlist-new');\n    }\n\n    if(options.dialogSize) {\n      list.classList.add('chatlist-' + options.dialogSize);\n    }\n\n    // if(options.ignoreClick) {\n    //   list.classList.add('disable-hover');\n    // }\n\n    /* if(options.handheldsSize) {\n      list.classList.add('chatlist-handhelds-' + options.handheldsSize);\n    } */\n\n    return list;\n  }\n\n  public setLastMessageN(options: Parameters<AppDialogsManager['setLastMessage']>[0]) {\n    const promise = this.setLastMessage(options);\n    return promise.catch((err: ApiError) => {\n      if(err?.type !== 'MIDDLEWARE') {\n        this.log.error('set last message error', err);\n      }\n    });\n  }\n\n  // what to show instead of the last message when there is none at all\n  private getEmptySubtitle(peerId: PeerId, listEl: HTMLElement) {\n    if(apiManagerProxy.isBotforum(peerId)) {\n      return i18n('NoMessagesYet');\n    }\n\n    if(!listEl.dataset.communityDialog) {\n      return;\n    }\n\n    // a community bot has no history until its chat is started\n    const peer = apiManagerProxy.getPeer(peerId);\n    return peer?._ === 'user' && peer.pFlags.bot ?\n      getCommunityPeerSubtitle(peer) :\n      undefined;\n  }\n\n  private getLastMessageForDialog(dialog: PossibleDialog, lastMessage?: Message.message | Message.messageService) {\n    let draftMessage: MyDraftMessage;\n    const {peerId, draft} = dialog as Dialog;\n    const peer = apiManagerProxy.getPeer(peerId);\n    const isMonoforumParent = peer?._ === 'channel' && peer.pFlags?.monoforum;\n\n    if(!lastMessage) {\n      if(\n        draft?._ === 'draftMessage' && !isMonoforumParent && (\n          !peerId.isAnyChat() ||\n          isForumTopic(dialog) ||\n          !apiManagerProxy.isForum(peerId)\n        )\n      ) {\n        draftMessage = draft;\n      }\n\n      lastMessage = (dialog as Dialog).topMessage;\n      if(lastMessage?.mid !== dialog.top_message) {\n        const trueLastMessage = apiManagerProxy.getMessageByPeer((dialog as MonoforumDialog)?.parentPeerId || peerId, dialog.top_message);\n        if(trueLastMessage && (trueLastMessage as Message.messageService).action?._ !== 'messageActionChannelJoined') {\n          lastMessage = trueLastMessage;\n        }\n      }\n    }\n\n    return {lastMessage, draftMessage};\n  }\n\n  /**\n   * Everything the subtitle is rendered from, flattened into a comparable string.\n   * `textColor` is deliberately left out: `setDialogActiveStatus` recolors the\n   * already rendered custom emoji itself, so becoming (in)active must not cost\n   * a re-render.\n   */\n  private getLastMessageRenderKey(options: {\n    peerId: PeerId,\n    isSaved: boolean,\n    lastMessage?: Message.message | Message.messageService,\n    draftMessage?: MyDraftMessage,\n    highlightWord?: string,\n    noForwardIcon?: boolean,\n    subtitlePeerId?: PeerId,\n    isRestricted?: boolean,\n    isSensitive?: boolean\n  }) {\n    const {lastMessage, draftMessage} = options;\n    const message = lastMessage as Message.message;\n    const media = lastMessage && getMediaFromMessage(lastMessage, true);\n    const messageMedia = message?.media as MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument;\n\n    return [\n      options.peerId,\n      options.isSaved,\n      options.highlightWord,\n      options.noForwardIcon,\n      options.subtitlePeerId,\n      options.isRestricted,\n      options.isSensitive,\n      draftMessage?.date,\n      draftMessage?.message,\n      lastMessage?._,\n      lastMessage?.peerId,\n      lastMessage?.mid,\n      lastMessage?.date,\n      message?.edit_date,\n      message?.fromId,\n      message?.fwdFromId,\n      message?.reply_to?._,\n      (media as Photo.photo | MyDocument)?.id,\n      (media as MyDocument)?.type,\n      messageMedia?.pFlags?.spoiler,\n      (messageMedia as MessageMedia.messageMediaPhoto)?.ttl_seconds,\n      message?.message\n    ].join('\\x01');\n  }\n\n  private async setLastMessage({\n    dialog,\n    lastMessage: _lastMessage,\n    dialogElement,\n    highlightWord,\n    isBatch = false,\n    setUnread = false,\n    noForwardIcon,\n    setMessageId = true,\n    subtitlePeerId\n  }: {\n    dialog: PossibleDialog,\n    lastMessage?: Message.message | Message.messageService,\n    dialogElement?: DialogElement,\n    highlightWord?: string,\n    isBatch?: boolean,\n    setUnread?: boolean,\n    noForwardIcon?: boolean,\n    setMessageId?: boolean,\n    subtitlePeerId?: PeerId\n  }) {\n    if(!dialogElement) {\n      dialogElement = this.xd.getDialogElement(dialog.peerId);\n\n      if(!dialogElement) {\n        return;\n      }\n    }\n\n    const {dom} = dialogElement;\n    const {peerId} = dialog;\n    const isSaved = isSavedDialog(dialog);\n\n    const {deferred: promise, middleware} = setPromiseMiddleware(dom, 'setLastMessagePromise');\n\n    const {draftMessage, lastMessage} = this.getLastMessageForDialog(dialog, _lastMessage);\n\n    const isSearch = setUnread !== null && !setUnread;\n    // * do not uncomment `setUnread` - unsetTyping right after this call will interrupt setting unread badges\n    if(/* setUnread */!isSearch) {\n      this.setUnreadMessagesN({dialog, dialogElement, isBatch, setLastMessagePromise: promise});\n    }\n\n    const isRestricted = !!lastMessage && isMessageRestricted(lastMessage as Message.message);\n    const isSensitive = !!lastMessage && isMessageSensitive(lastMessage as Message.message);\n\n    const renderKey = this.getLastMessageRenderKey({\n      peerId,\n      isSaved,\n      lastMessage,\n      draftMessage,\n      highlightWord,\n      noForwardIcon,\n      subtitlePeerId,\n      isRestricted,\n      isSensitive\n    });\n    // * the key is dropped for the whole render and only restored once the new\n    // * subtitle is in the DOM, so a render interrupted by the middleware can\n    // * never leave a stale key behind\n    const previousRenderParts = dom.lastMessageRenderParts;\n    const canSkipRender = dom.lastMessageRenderKey === renderKey &&\n      isRenderedSubtitleIntact(dom);\n    delete dom.lastMessageRenderKey;\n    delete dom.lastMessageRenderParts;\n\n    if(!lastMessage && !draftMessage && !subtitlePeerId/*  || (lastMessage._ === 'messageService' && !lastMessage.rReply) */) {\n      // * not guarded by the key: the placeholder also depends on the peer being a\n      // * botforum / community dialog, and rendering it costs a single element\n      const emptySubtitle = this.getEmptySubtitle(peerId, dom.listEl);\n\n      disposeTextHighlight(dom);\n      dom.lastMessageSpan.replaceChildren(...(emptySubtitle ? [emptySubtitle] : []));\n      dom.lastTimeSpan.replaceChildren();\n      delete dom.listEl.dataset.mid;\n      delete dom.listEl.dataset.searchQuery;\n\n      promise.resolve();\n      return;\n    }\n\n    // set it before content so won't have bug in appSearch\n    if(isSearch && setMessageId && lastMessage) {\n      dom.listEl.dataset.mid = '' + lastMessage.mid;\n\n      const replyTo = lastMessage.reply_to as MessageReplyHeader.messageReplyHeader;\n      if(replyTo?.pFlags?.forum_topic) {\n        dom.listEl.dataset.threadId = '' + getMessageThreadId(lastMessage);\n      }\n    }\n\n    // * the click on the row carries the query on to the chat, so the found text\n    // * lights up in the bubble too\n    if(highlightWord) dom.listEl.dataset.searchQuery = highlightWord;\n    else delete dom.listEl.dataset.searchQuery;\n\n    let renderedParts = canSkipRender ? previousRenderParts : undefined;\n\n    /* if(!dom.lastMessageSpan.classList.contains('user-typing')) */ if(!canSkipRender) {\n      let mediaContainer: HTMLElement;\n      const mediaParts: (Promise<HTMLElement> | HTMLElement)[] = [];\n\n      if(lastMessage && !draftMessage && !isRestricted) {\n        const media = getMediaFromMessage(lastMessage, true);\n        const videoTypes: Set<MyDocument['type']> = new Set(['video', 'gif', 'round']);\n        if(media && (media._ === 'photo' || videoTypes.has(media.type)) && !(((lastMessage as Message.message).media) as MessageMedia.messageMediaPhoto)?.ttl_seconds) {\n          const spoiler = ((lastMessage as Message.message).media as MessageMedia.messageMediaPhoto | MessageMedia.messageMediaDocument)?.pFlags?.spoiler;\n          const size = choosePhotoSize(media, 20, 20);\n\n          if(size._ !== 'photoSizeEmpty') {\n            mediaContainer = document.createElement('div');\n            mediaContainer.classList.add('dialog-subtitle-media');\n\n            if((media as MyDocument).type === 'round') {\n              mediaContainer.classList.add('is-round');\n            }\n\n            mediaParts.push(wrapPhoto({\n              photo: media,\n              message: lastMessage,\n              container: mediaContainer,\n              withoutPreloader: true,\n              size\n            }).then(() => {\n              if(spoiler || isSensitive) {\n                return wrapMediaSpoiler({\n                  media: media,\n                  width: 20,\n                  height: 20,\n                  multiply: 0.1,\n                  middleware: this.stateMiddlewareHelper.get(),\n                  animationGroup: 'none'\n                }).then((el) => {\n                  mediaContainer.append(el);\n                  return mediaContainer;\n                });\n              }\n\n              return mediaContainer\n            }));\n\n            if(videoTypes.has((media as MyDocument).type)) {\n              const playIcon = Icon('play_filled', 'dialog-subtitle-media-play');\n              mediaContainer.append(playIcon);\n            }\n          }\n        }\n      }\n\n      const withoutMediaType = !!mediaContainer && !!(lastMessage as Message.message)?.message;\n      const parts = await renderDialogSubtitleParts({\n        peerId,\n        isSaved,\n        lastMessage,\n        draftMessage,\n        noForwardIcon,\n        mediaParts,\n        withoutMediaType,\n        prependPeerId: subtitlePeerId,\n        middleware,\n        messageRenderer: wrapMessageForReply,\n        peerTitleRenderer: wrapPeerTitle,\n        textColor: this.getTextColor(\n          dom.listEl.classList.contains('active')\n        )\n      });\n      dom.lastMessageSpan.classList.add('dialog-subtitle-parts');\n      disposeTextHighlight(dom);\n      dom.lastMessageSpan.replaceChildren(...parts);\n      renderedParts = parts;\n\n      // * the last part is the message text itself (the ones before are the sender, the\n      // * draft label, media thumbs) — that is where the query was matched\n      if(highlightWord && lastMessage) {\n        dom.textHighlight = highlightText({\n          container: parts[parts.length - 1],\n          match: {type: 'search', query: highlightWord}\n        });\n      }\n    }\n\n    // * the label is relative to the current day, so it is refreshed even when\n    // * the subtitle itself was left alone\n    if(lastMessage || draftMessage/*  && lastMessage._ !== 'draftMessage' */) {\n      const date = draftMessage ? Math.max(draftMessage.date, lastMessage?.date || 0) : lastMessage.date;\n      replaceContent(dom.lastTimeSpan, formatDateAccordingToTodayNew(new Date(date * 1000)));\n    } else dom.lastTimeSpan.textContent = '';\n\n    dom.lastMessageRenderKey = renderKey;\n    dom.lastMessageRenderParts = renderedParts;\n    promise.resolve();\n  }\n\n  public setUnreadMessagesN(options: Parameters<AppDialogsManager['setUnreadMessages']>[0]) {\n    return this.setUnreadMessages(options).catch(() => {});\n  }\n\n  private async setUnreadMessages({\n    dialog,\n    dialogElement,\n    isBatch = false,\n    setLastMessagePromise\n  }: {\n    dialog: PossibleDialog,\n    dialogElement: DialogElement,\n    isBatch?: boolean,\n    setLastMessagePromise?: Promise<void>\n  }) {\n    const {dom} = dialogElement;\n    if(!dom) {\n      // this.log.error('setUnreadMessages no dom!', dialog);\n      return;\n    }\n\n    const isTopic = isForumTopic(dialog);\n    const isSaved = isSavedDialog(dialog);\n    const isMonoforumThread = isMonoforumDialog(dialog);\n    const isAllChats = !!dialogElement?.dom?.listEl?.dataset?.isAllChats;\n    const {deferred, middleware} = setPromiseMiddleware(dom, 'setUnreadMessagePromise');\n\n    const {peerId} = dialog;\n    const promises = Promise.all([\n      this.managers.appNotificationsManager.isPeerLocalMuted({peerId: peerId, respectType: true, threadId: isTopic ? dialog.id : undefined}),\n      !isSaved ? this.getLastMessageForDialog(dialog) : undefined,\n      isTopic || isSaved ? !!dialog.pFlags.pinned : this.managers.dialogsStorage.isDialogPinned(peerId, this.filterId),\n      this.managers.appMessagesManager.isDialogUnread(dialog),\n      peerId.isAnyChat() && !isTopic ? this.managers.acknowledged.dialogsStorage.getForumUnreadCount(peerId, true).then((result) => {\n        if(result.cached) {\n          return result.result;\n        } else {\n          result.result.then(() => {\n            this.setUnreadMessagesN({dialog, dialogElement});\n          });\n\n          return {count: 0, hasUnmuted: false};\n        }\n      }).catch(() => undefined as {count: number, hasUnmuted: boolean}) : undefined\n    ]);\n\n    let [isMuted, m, isPinned, isDialogUnread, forumUnreadCount] = await middleware(promises);\n    const {count: unreadTopicsCount, hasUnmuted: hasUnmutedTopic} = forumUnreadCount || {};\n\n    const {draftMessage, lastMessage} = m || {};\n    let setStatusMessage: MyMessage;\n    if(!draftMessage && lastMessage && lastMessage.pFlags.out && lastMessage.peerId !== rootScope.myId) {\n      setStatusMessage = lastMessage;\n    }\n\n    const unreadCount = unreadTopicsCount ?? (isSaved ? 0 : dialog.unread_count);\n    if(unreadTopicsCount !== undefined) {\n      isDialogUnread = !!unreadCount;\n    }\n\n    if(isTopic && !isDialogUnread) {\n      isDialogUnread = !getServerMessageId(dialog.read_inbox_max_id);\n    }\n\n    if(isAllChats) {\n      isDialogUnread = false;\n    }\n\n    // dom.messageEl.classList.toggle('has-badge', hasBadge);\n\n    // * have to await all promises before modifying something\n\n    if(setLastMessagePromise) {\n      try {\n        await middleware(setLastMessagePromise);\n      } catch(err) {\n        return;\n      }\n    }\n\n    const transitionDuration = isBatch ? 0 : BADGE_TRANSITION_TIME;\n\n    dom.listEl.classList.toggle('no-unmuted-topic', !isMuted && hasUnmutedTopic !== undefined && !hasUnmutedTopic);\n\n    setSendingStatus(dom.statusSpan, isTopic && dialog.pFlags.closed ? 'premium_lock' : setStatusMessage, true);\n\n    // if(isTopic) {\n    //   dom.statusSpan.parentElement.classList.toggle('is-closed', !!dialog.pFlags.closed);\n    // }\n\n    const hasPinnedBadge = isPinned && !isMonoforumThread && !isAllChats;\n    const hasUnreadBadge = isDialogUnread;\n    const hasUnreadAvatarBadge = dialogElement.isMainList !== false &&\n      this.xd !== this.xds[FOLDER_ID_ARCHIVE] &&\n      !isTopic &&\n      !isMonoforumThread &&\n      !isAllChats &&\n      (!!this.forumTab || appSidebarLeft.isCollapsed()) &&\n      isDialogUnread;\n    // * `unreadCount` counts the unread topics for a forum, so the mention state\n    // * must be derived from it too — not from `dialog.unread_count`\n    const {isMention, hasMentionsBadge} = getDialogMentionBadgeState({\n      unreadCount,\n      unreadMessagesCount: (dialog as Dialog | ForumTopic).unread_count,\n      unreadMentionsCount: isSaved || isMonoforumThread ? 0 : dialog.unread_mentions_count,\n      hasUnreadBadge\n    });\n    const hasReactionsBadge = isSaved ? false : !!dialog.unread_reactions_count;\n    const hasPollVotesBadge = isSaved || isMonoforumThread ? false : !!(dialog as Dialog | ForumTopic).unread_poll_votes_count;\n    let unreadBadgeText: string;\n    if(hasUnreadBadge) {\n      // dom.unreadMessagesSpan.innerText = '' + (unreadCount ? formatNumber(unreadCount, 1) : ' ');\n      unreadBadgeText = isMention ? '@' : '' + (unreadCount ? formatNumber(unreadCount, 1) : ' ');\n    }\n\n    dialogElement.setBadgeState({\n      muted: isMuted,\n      pinned: hasPinnedBadge,\n      unread: hasUnreadBadge,\n      unreadText: unreadBadgeText,\n      unreadMention: isMention,\n      unreadAvatar: hasUnreadAvatarBadge,\n      unreadAvatarText: unreadBadgeText || undefined,\n      mentions: hasMentionsBadge,\n      reactions: hasReactionsBadge,\n      pollVotes: hasPollVotesBadge,\n      transitionDuration\n    });\n\n    if(isTopic && dom.unreadBadge) {\n      const notVisited = isDialogUnread && unreadBadgeText === ' ';\n      dom.unreadBadge.classList.toggle('not-visited', notVisited);\n    }\n\n    // if(isPinned && !isUnread && !isMention) {\n    //   dom.unreadBadge.classList.add('badge-icon', 'dialog-pinned-icon');\n    //   dom.unreadBadge.replaceChildren(Icon('chatspinned'));\n    // } else if(dom.unreadBadge) {\n    //   dom.unreadBadge.classList.remove('badge-icon', 'dialog-pinned-icon');\n    //   if(!unreadBadgeText) {\n    //     dom.unreadBadge.replaceChildren();\n    //   }\n    // }\n\n    deferred.resolve();\n  }\n\n  private async getDialog(dialog: AnyDialog | PeerId, {threadOrSavedId, monoforumParentPeerId}: GetDialogOptions = {}) {\n    if(typeof(dialog) !== 'object') {\n      let originalDialog: AnyDialog | MonoforumDialog;\n      if(monoforumParentPeerId) {\n        originalDialog = await this.managers.monoforumDialogsStorage.getDialogByParent(monoforumParentPeerId, dialog);\n\n        if(!originalDialog) return {\n          peerId: dialog || NULL_PEER_ID,\n          pFlags: {}\n        } as MonoforumDialog;\n      } else if(threadOrSavedId) {\n        if(dialog === rootScope.myId) {\n          originalDialog = await this.managers.dialogsStorage.getAnyDialog(dialog, threadOrSavedId);\n          if(!originalDialog) {\n            const peerId = dialog || NULL_PEER_ID;\n            return {\n              peerId,\n              pFlags: {}\n            } as any as SavedDialog;\n          }\n        } else {\n          originalDialog = await this.managers.dialogsStorage.getForumTopic(dialog, threadOrSavedId);\n          if(!originalDialog) {\n            const peerId = dialog || NULL_PEER_ID;\n            return {\n              peerId,\n              pFlags: {}\n            } as any as ForumTopic;\n          }\n        }\n      } else {\n        originalDialog = await this.managers.appMessagesManager.getDialogOnly(dialog);\n        if(!originalDialog) {\n          const peerId = dialog || NULL_PEER_ID;\n          return {\n            peerId,\n            peer: await this.managers.appPeersManager.getOutputPeer(peerId),\n            pFlags: {}\n          } as any as Dialog;\n        }\n      }\n\n      return originalDialog;\n    }\n\n    return dialog as AnyDialog;\n  }\n\n  public addListDialog(options: Parameters<AppDialogsManager['addDialogNew']>[0] & InitDialogAdditionalOptions) {\n    options.autonomous = false;\n    options.withStories = true;\n\n    const ret = this.addDialogNew(options);\n\n    if(ret) {\n      const promise = this.initDialog(ret, options);\n      options.loadPromises?.push(promise);\n      options.onInitPromise?.(promise);\n    }\n\n    if(ret && this.lazyLoadQueue) {\n      const div = ret.dom.listEl;\n      const lazyLoadElement: Parameters<AppDialogsManager['lazyLoadQueue']['push']>[0] = {\n        div,\n        load: async() => {\n          await pause(200);\n          if(!this.lazyLoadQueue.intersector.isVisible(div)) {\n            this.lazyLoadQueue.push(lazyLoadElement); // * to process again\n            return;\n          }\n\n          const getHistoryOptions: RequestHistoryOptions = {\n            peerId: options.monoforumParentPeerId || options.peerId,\n            threadId: options.threadId,\n            monoforumThreadId: options.monoforumParentPeerId ? options.peerId : undefined,\n            limit: 50\n          };\n\n          const readMaxId = await this.managers.appMessagesManager.getReadMaxIdIfUnread(\n            options.peerId,\n            options.threadId\n          );\n\n          if(readMaxId) {\n            const limit = Math.floor(getHistoryOptions.limit / 2);\n            await this.managers.appMessagesManager.getHistory({\n              ...getHistoryOptions,\n              offsetId: readMaxId || undefined,\n              backLimit: readMaxId ? limit : undefined,\n              limit\n            });\n          }\n\n          return this.managers.appMessagesManager.getHistory(getHistoryOptions);\n        }\n      };\n\n      this.lazyLoadQueue.push(lazyLoadElement);\n      ret.middlewareHelper.onDestroy(() => {\n        this.lazyLoadQueue.delete(lazyLoadElement);\n      });\n    }\n\n    return ret;\n  }\n\n  public initDialog(dialogElement: DialogElement, options: Parameters<AppDialogsManager['addDialogNew']>[0] & InitDialogAdditionalOptions) {\n    const {peerId} = options;\n    const getDialogPromise = this.getDialog(options.dialog || peerId, {\n      threadOrSavedId: options.threadId,\n      monoforumParentPeerId: options.monoforumParentPeerId\n    });\n\n    const promise = getDialogPromise.then((dialog) => {\n      const promises: (Promise<any> | void)[] = [];\n      const isUser = peerId.isUser();\n      if(!isUser && isDialog(dialog)) {\n        promises.push(this.xd.processDialogForCallStatus(peerId, dialogElement.dom));\n      }\n\n      if(peerId !== rootScope.myId && isUser) {\n        promises.push(this.managers.appUsersManager.getUserStatus(peerId.toUserId()).then((status) => {\n          if(status?._ === 'userStatusOnline') {\n            this.xd.setOnlineStatus(dialogElement.dom.avatarEl.node, true);\n          }\n        }));\n      }\n\n      promises.push(this.setLastMessageN({\n        dialog,\n        dialogElement: dialogElement,\n        isBatch: options.isBatch,\n        lastMessage: options.lastMessage,\n        setUnread: true\n      }));\n\n      const allPromise = Promise.all(promises);\n\n      // * a row built while the peer is already typing gets no `peer_typings` event\n      // * of its own, so the indicator has to be restored here — after the subtitle\n      // * is rendered, and off the returned promise so it never delays the row\n      allPromise.then(() => setDialogTyping({\n        dom: dialogElement.dom,\n        peerId,\n        threadId: isForumTopic(dialog) ? dialog.id : undefined\n      })).catch(noop);\n\n      return allPromise;\n    });\n\n    return promise;\n  }\n\n  /**\n   * use for rendering search result\n   */\n  public addDialogAndSetLastMessage(options: Omit<Parameters<AppDialogsManager['addDialogNew']>[0], 'dialog'> & {\n    message: MyMessage,\n    peerId: PeerId,\n    query?: string\n  }) {\n    const {peerId, message, query} = options;\n    const ret = this.addDialogNew({\n      ...options,\n      ...getMessageSenderPeerIdOrName(message),\n      peerId\n    });\n\n    this.setLastMessageN({\n      dialog: {_: 'dialog', peerId} as any,\n      lastMessage: message,\n      dialogElement: ret,\n      highlightWord: query\n    });\n\n    if(message.peerId !== peerId) {\n      ret.dom.listEl.dataset.peerId = '' + message.peerId;\n    }\n\n    return ret;\n  }\n\n  public addDialogNew(options: DialogElementOptions & {container?: HTMLElement | Scrollable | false, append?: boolean}) {\n    const d = new DialogElement({\n      autonomous: !!options.container,\n      avatarSize: 'bigger',\n      ...options\n      // avatarSize: !options.avatarSize || options.avatarSize >= 54 ? 'bigger' : 'abitbigger',\n    });\n    (d.container as any).dialogElement = d;\n\n    if(options.container) {\n      const method = options.append === false ? 'prepend' : 'append';\n      options.container[method](d.container);\n    }\n\n    return d;\n    // return this.addDialog(options.peerId, options.container, options.rippleEnabled, options.onlyFirstName, options.meAsSaved, options.append, options.avatarSize, options.autonomous, options.lazyLoadQueue, options.loadPromises, options.fromName, options.noIcons);\n  }\n\n  private showPollCancelConfirmation(randomId: string) {\n    const listenerSetter = new ListenerSetter;\n    let popup: PopupPeer;\n\n    const onSent = () => {\n      toastNew({\n        langPackKey: 'CancelPollConfirm.Timeout'\n      });\n    }\n\n    listenerSetter.add(rootScope)('message_sent', ({tempMessage}) => {\n      if(tempMessage?.random_id === randomId) {\n        popup?.hide();\n        onSent();\n      }\n    });\n\n    confirmationPopup({\n      titleLangKey: 'CancelPollConfirm.Title',\n      descriptionLangKey: 'CancelPollConfirm.Description',\n      button: {\n        langKey: 'CancelPollConfirm.Button'\n      },\n      onPopup: (p) => {\n        popup = p;\n      }\n    }).then(() => {\n      this.managers.appMessagesManager.cancelPendingMessage(randomId).then((wasCanceled) => {\n        if(!wasCanceled) {\n          onSent();\n        }\n      });\n    }, noop).finally(() => {\n      listenerSetter.removeAll();\n    });\n  }\n}\n\n\nconst appDialogsManager = new AppDialogsManager();\nMOUNT_CLASS_TO.appDialogsManager = appDialogsManager;\nexport default appDialogsManager;\n","import appDialogsManager, {AppDialogsManager} from '@lib/appDialogsManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport Section from '@components/section';\nimport {createMemo, createRoot, createSignal, JSX, Show} from 'solid-js';\nimport classNames from '@helpers/string/classNames';\nimport {Middleware} from '@helpers/middleware';\nimport Scrollable from '@components/scrollable2';\n\nexport type SearchGroupType = 'contacts' | 'globalContacts' | 'messages' | string;\n\nexport type SearchGroup = ReturnType<typeof createSearchGroup>;\n\nexport function createSearchGroup(options: {\n  name?: LangPackKey | boolean,\n  type: string,\n  clearable?: boolean,\n  className?: string,\n  clickable?: boolean,\n  autonomous?: boolean,\n  onFound?: Parameters<AppDialogsManager['setListClickListener']>[0]['onFound'],\n  noIcons?: boolean,\n  middleware?: Middleware,\n  scrollableX?: boolean\n}) {\n  const {\n    name,\n    type,\n    clearable = true,\n    className,\n    clickable = true,\n    autonomous = true,\n    onFound,\n    noIcons,\n    middleware,\n    scrollableX\n  } = options;\n\n  const NameRight = (props: {\n    children: JSX.Element,\n    onClick?: () => void\n  }) => {\n    return (\n      <span\n        class=\"cursor-pointer hover-underline\"\n        onClick={props.onClick}\n      >\n        {props.children}\n      </span>\n    );\n  };\n\n  const [hide, setHide] = createSignal(true);\n  const [showingMore, setShowingMore] = createSignal(false);\n  const [showMoreClassName, setShowMoreClassName] = createSignal<string>();\n  const [_nameRight, setNameRight] = createSignal<Parameters<typeof NameRight>[0]>();\n  const nameRight = createMemo(() => {\n    const _ = _nameRight();\n    if(_) {\n      return NameRight(_);\n    }\n\n    const toggleClassName = showMoreClassName();\n    if(!toggleClassName) {\n      return;\n    }\n\n    return (\n      <NameRight\n        onClick={() => {\n          setShowingMore((v) => !v);\n        }}\n      >\n        {i18n(showingMore() ? 'Separator.ShowLess' : 'Separator.ShowMore')}\n      </NameRight>\n    );\n  });\n  const list = appDialogsManager.createChatList();\n  let container: HTMLDivElement;\n  let nameEl: HTMLDivElement;\n  let placeholder: HTMLElement;\n\n  createRoot((dispose) => {\n    <Section\n      name={name}\n      nameRef={(ref) => nameEl = ref}\n      nameRight={nameRight()}\n      class={classNames(\n        'search-group',\n        'search-group-' + type,\n        className,\n        hide() && 'hide',\n        showMoreClassName() && !showingMore() && showMoreClassName(),\n        scrollableX && 'search-group-with-scroll'\n      )}\n      ref={(ref) => container = ref}\n      innerClass=\"search-group-inner\"\n      contentProps={{\n        class: 'search-group-content'\n      }}\n    >\n      <Show when={scrollableX} fallback={list}>\n        <Scrollable\n          class=\"search-group-scrollable-x\"\n          axis=\"x\"\n        >\n          {list}\n        </Scrollable>\n      </Show>\n    </Section>;\n\n    middleware?.onClean(dispose);\n  });\n\n  if(clickable) {\n    appDialogsManager.setListClickListener({\n      list,\n      onFound,\n      withContext: undefined,\n      autonomous\n    });\n  }\n\n  const group = {\n    container,\n    list,\n    nameEl,\n    autonomous,\n    noIcons,\n    createPlaceholder: undefined as () => HTMLElement,\n    get placeholder() {\n      return placeholder;\n    },\n    addPlaceholder(el: HTMLElement) {\n      group.removePlaceholder();\n      placeholder = el;\n      container.append(el);\n    },\n    removePlaceholder() {\n      placeholder?.remove();\n      placeholder = undefined;\n    },\n    clear() {\n      setHide(true);\n      group.removePlaceholder();\n      if(clearable) {\n        Array.from(list.children).forEach((el) => {\n          const dialogElement = (el as any).dialogElement;\n          if(dialogElement) dialogElement?.remove();\n          else el.remove();\n        });\n      }\n    },\n    setActive() {\n      setHide(false);\n    },\n    toggle() {\n      if(list.childElementCount) {\n        group.setActive();\n      } else {\n        group.clear();\n      }\n    },\n    needShowMoreButton(toggleClassName = 'is-short-5') {\n      setShowMoreClassName(toggleClassName);\n    },\n    setNameRight\n  };\n\n  return group;\n}\n","import {JSX} from 'solid-js';\nimport RowTsx from '@components/rowTsx';\nimport type {Middleware} from '@helpers/middleware';\nimport {wrapSolidComponent} from '@helpers/solid/wrapSolidComponent';\nimport setBlankToAnchor from '@richTextProcessor/setBlankToAnchor';\n\ntype SearchWebPageRowLink = {\n  href: string,\n  onClick?: string,\n  targetBlank?: boolean\n};\n\ntype SearchWebPageRowProps = {\n  title: JSX.Element,\n  titleRight: JSX.Element,\n  subtitle: JSX.Element,\n  media: HTMLElement,\n  link?: SearchWebPageRowLink\n};\n\nfunction SearchWebPageRow(props: SearchWebPageRowProps) {\n  const setRef = (element: HTMLElement) => {\n    if(!props.link) return;\n\n    const anchor = element as HTMLAnchorElement;\n    anchor.href = props.link.href;\n    if(props.link.onClick) {\n      anchor.setAttribute('onclick', props.link.onClick);\n    }\n\n    if(props.link.targetBlank) {\n      setBlankToAnchor(anchor);\n    }\n  };\n\n  return (\n    <RowTsx\n      ref={setRef}\n      as={props.link ? 'a' : undefined}\n      clickable\n      havePadding\n      noRipple\n    >\n      <RowTsx.Title titleRight={props.titleRight}>{props.title}</RowTsx.Title>\n      <RowTsx.Subtitle>{props.subtitle}</RowTsx.Subtitle>\n      <RowTsx.Media element={props.media} size=\"big\" />\n    </RowTsx>\n  );\n}\n\nexport function renderSearchWebPageRow(\n  props: SearchWebPageRowProps & {middleware: Middleware}\n) {\n  return wrapSolidComponent(() => (\n    <SearchWebPageRow\n      title={props.title}\n      titleRight={props.titleRight}\n      subtitle={props.subtitle}\n      media={props.media}\n      link={props.link}\n    />\n  ), props.middleware);\n}\n","import cancelEvent from '@helpers/dom/cancelEvent';\n\nexport default function lockTouchScroll(container: HTMLElement) {\n  const onTouchMove = (e: TouchEvent) => {\n    cancelEvent(e);\n  };\n\n  let lockers = 2;\n  const cb = () => {\n    if(!--lockers) {\n      container.removeEventListener('touchmove', onTouchMove, {capture: true});\n    }\n  };\n\n  container.addEventListener('touchmove', onTouchMove, {capture: true, passive: false});\n  container.addEventListener('touchend', cb, {once: true});\n\n  return cb;\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport {MissingInvitee} from '@layer';\nimport {FormatterArguments, LangPackKey, i18n, join} from '@lib/langPack';\nimport rootScope from '@lib/rootScope';\nimport Button from '@components/button';\nimport {DelimiterWithText} from '@components/chat/giveaway';\nimport PopupElement from '@components/popups';\nimport PopupPeer, {PopupPeerButtonCallbackCheckboxes, PopupPeerCheckboxOptions} from '@components/popups/peer';\nimport showPickUserPopup from '@components/popups/pickUser';\nimport PopupPremium from '@components/popups/premium';\nimport {AppAddMembersTab} from '@components/solidJsTabs';\nimport SidebarSlider from '@components/slider';\nimport {toastNew} from '@components/toast';\nimport wrapPeerTitle from '@components/wrappers/peerTitle';\n\nexport async function handleMissingInvitees(chatId: ChatId, missingInvitees: MissingInvitee[]) {\n  if(!missingInvitees.length) {\n    return;\n  }\n\n  const inviteLink = await rootScope.managers.appProfileManager.getChatInviteLink(chatId);\n  const premiumRequireIds: Set<PeerId> = new Set();\n  const canInviteAsPremiumIds: Set<PeerId> = new Set();\n  const missingInviteeIds = missingInvitees.map((invitee) => {\n    const peerId = invitee.user_id.toPeerId(false);\n    if(invitee.pFlags.premium_required_for_pm) {\n      premiumRequireIds.add(peerId);\n    }\n\n    if(invitee.pFlags.premium_would_allow_invite) {\n      canInviteAsPremiumIds.add(peerId);\n    }\n\n    return peerId;\n  });\n\n  const hasPremiumSection = canInviteAsPremiumIds.size > 0;\n\n  const getTitle = (peerId: PeerId) => wrapPeerTitle({peerId, onlyFirstName: true});\n  const length = missingInviteeIds.length;\n  const title = length > 1 ? undefined : await getTitle(hasPremiumSection ? [...canInviteAsPremiumIds][0] : missingInviteeIds[0]);\n\n  const cantSendMessages = premiumRequireIds.size === missingInviteeIds.length;\n\n  const onPremiumClick = () => {\n    PopupPremium.show();\n    popup.hide();\n  };\n\n  let footerButton: HTMLElement;\n  const onCountUpdate = (count: number) => {\n    footerButton.replaceChildren(i18n(cantSendMessages ? 'InviteViaLink.Premium.Subscribe' : (count ? 'InviteViaLink.Send' : 'InviteViaLink.Skip')));\n  };\n  const initial = missingInviteeIds.filter((peerId) => !premiumRequireIds.has(peerId));\n  const popup = showPickUserPopup(\n    {\n      peerType: ['custom'],\n      getMoreCustom: async() => ({result: missingInviteeIds, isEnd: true}),\n      onSelect: async(chosen) => {\n        const peerIds = chosen.map((c) => c.peerId);\n        if(cantSendMessages) {\n          onPremiumClick();\n          return;\n        }\n\n        const length = peerIds.length;\n        if(!length) {\n          return;\n        }\n\n        peerIds.forEach((peerId) => {\n          rootScope.managers.appMessagesManager.sendText({\n            peerId,\n            text: inviteLink\n          });\n        });\n\n        toastNew({\n          langPackKey: 'InviteViaLink.LinkShared',\n          langPackArguments: [length, length > 1 ? undefined : await getTitle(peerIds[0])]\n        });\n      },\n      onChange: onCountUpdate,\n      multiSelect: true,\n      titleLangKey: hasPremiumSection ? 'InviteViaLink.Premium' : 'InviteViaLink.Title',\n      initial,\n      headerSearch: false,\n      noSearch: true,\n      footerButtonProps: /* cantSendMessages ? undefined :  */{ref: (element) => footerButton = element},\n      chatRightsActions: ['send_messages'],\n      autoHeight: cantSendMessages\n    }\n  );\n\n  onCountUpdate(initial.length);\n  if(hasPremiumSection) {\n    const container = document.createElement('div');\n    container.classList.add('popup-add-members-premium-container');\n\n    const subtitle = i18n('InviteViaLink.Premium.Subtitle', [length, title || length]);\n    subtitle.classList.add('popup-add-members-premium-subtitle');\n\n    container.append(\n      subtitle\n    );\n\n    if(!cantSendMessages) {\n      const header = i18n('InviteViaLink.Title');\n      header.classList.add('popup-add-members-premium-header');\n\n      const subtitle2 = i18n('InviteViaLink.Premium.Subtitle2');\n      subtitle2.classList.add('popup-add-members-premium-subtitle');\n\n      const premiumButton = Button(`btn-primary popup-gift-premium-confirm action-button shimmer`, {text: 'InviteViaLink.Premium.Subscribe'});\n      attachClickEvent(premiumButton, onPremiumClick);\n\n      container.append(\n        premiumButton,\n        DelimiterWithText({langKey: 'PremiumOr'}) as HTMLElement,\n        header,\n        subtitle2\n      );\n    } else {\n      popup.selector.list.remove();\n\n      footerButton.classList.add('popup-gift-premium-confirm', 'action-button', 'shimmer');\n    }\n\n    popup.selector.section.content.prepend(container);\n  } else {\n    const subtitle = i18n('InviteViaLink.Subtitle', [length, title || length]);\n    subtitle.classList.add('popup-add-members-subtitle');\n    popup.selector.section.content.prepend(subtitle);\n  }\n}\n\nexport default async function addChatUsers({\n  peerId,\n  slider,\n  skippable = false\n}: {\n  peerId: PeerId,\n  slider: SidebarSlider,\n  skippable?: boolean\n}) {\n  const id = peerId.toChatId();\n  const isChannel = await rootScope.managers.appChatsManager.isChannel(id);\n  const isBroadcast = await rootScope.managers.appChatsManager.isBroadcast(id);\n\n  const showConfirmation = async(peerIds: PeerId[], callback: (e: MouseEvent, checked: PopupPeerButtonCallbackCheckboxes) => void) => {\n    let titleLangKey: LangPackKey, titleLangArgs: FormatterArguments,\n      descriptionLangKey: LangPackKey, descriptionLangArgs: FormatterArguments,\n      checkboxes: PopupPeerCheckboxOptions[];\n\n    if(peerIds.length > 1) {\n      const titles = await Promise.all(peerIds.map(async(peerId) => {\n        const b = document.createElement('b');\n        b.append(await wrapPeerTitle({peerId}));\n        return b;\n      }));\n      titleLangKey = 'AddMembersAlertTitle';\n      titleLangArgs = [i18n(isBroadcast ? 'Subscribers' : 'Members', [peerIds.length])];\n      descriptionLangKey = 'AddMembersAlertCountText';\n      descriptionLangArgs = [\n        join(titles)\n      ];\n\n      if(!isChannel) {\n        checkboxes = [{\n          text: 'AddMembersForwardMessages',\n          checked: true\n        }];\n      }\n    } else {\n      titleLangKey = 'AddOneMemberAlertTitle';\n      descriptionLangKey = 'AddMembersAlertNamesText';\n      const b = document.createElement('b');\n      b.append(await wrapPeerTitle({peerId: peerIds[0]}));\n      descriptionLangArgs = [b];\n\n      if(!isChannel) {\n        checkboxes = [{\n          text: peerIds.length > 1 ? 'AddMembersForwardMessages' : 'AddOneMemberForwardMessages',\n          textArgs: peerIds.length > 1 ? undefined : [await wrapPeerTitle({peerId: peerIds[0]})],\n          checked: true\n        }];\n      }\n    }\n\n    descriptionLangArgs.push(await wrapPeerTitle({peerId}));\n\n    PopupElement.createPopup(PopupPeer, 'popup-add-members', {\n      peerId,\n      titleLangKey,\n      titleLangArgs,\n      descriptionLangKey,\n      descriptionLangArgs,\n      buttons: [{\n        langKey: 'Add',\n        callback\n      }],\n      checkboxes\n    }).show();\n  };\n\n  const onError = (err: ApiError) => {\n    if(err.type === 'USER_PRIVACY_RESTRICTED') {\n      toastNew({langPackKey: 'InviteToGroupError'});\n    }/*  else if(err.type === 'USER_NOT_MUTUAL_CONTACT') {\n      toastNew({langPackKey: 'InviteToGroupError'});\n    }  */else {\n      throw err;\n    }\n  };\n\n  const tab = slider.createTab(AppAddMembersTab);\n  tab.open({\n    type: 'channel',\n    skippable,\n    takeOut: (peerIds) => {\n      showConfirmation(peerIds, (e, checked) => {\n        const promise = isChannel ?\n          rootScope.managers.appChatsManager.inviteToChannel(id, peerIds) :\n          rootScope.managers.appChatsManager.addChatUser(id, peerIds, checked.size ? undefined : 0);\n        promise.then((missingInvitees) => handleMissingInvitees(id, missingInvitees), onError);\n        tab.payload.attachToPromise(promise);\n      });\n\n      return false;\n    },\n    title: isBroadcast ? 'ChannelAddSubscribers' : 'GroupAddMembers',\n    placeholder: 'SendMessageTo'\n  });\n}\n","import createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {ChannelParticipant, Chat, ChatParticipant} from '@layer';\nimport SidebarSlider from '@components/slider';\nimport rootScope from '@lib/rootScope';\nimport appImManager from '@lib/appImManager';\nimport canEditAdmin from '@appManagers/utils/chats/canEditAdmin';\nimport {openUserPermissionsTab} from '@components/solidJsTabs/tabs';\nimport {Middleware} from '@helpers/middleware';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {handleMissingInvitees} from '@components/addChatUsers';\nimport {isParticipantAdmin, isParticipantCreator} from '@lib/appManagers/utils/chats/isParticipantAdmin';\n\ntype Participant = ChannelParticipant | ChatParticipant;\n\ntype BannedParticipantAdapter = {\n  hasRights: () => MaybePromise<boolean>,\n  unban: (\n    participantPeerId: PeerId,\n    participant: Participant\n  ) => MaybePromise<void>\n};\n\nexport default function createParticipantContextMenu(options: {\n  listenTo: HTMLElement,\n  appendTo?: HTMLElement,\n  onOpen?: () => any,\n  onClose?: () => any,\n  slider: SidebarSlider,\n  chatId: ChatId,\n  participants: Map<PeerId, Participant>,\n  middleware?: Middleware,\n  bannedParticipantAdapter?: BannedParticipantAdapter\n}) {\n  const {\n    listenTo,\n    appendTo,\n    onOpen,\n    onClose,\n    slider,\n    chatId,\n    participants,\n    middleware,\n    bannedParticipantAdapter\n  } = options;\n  let target: HTMLElement,\n    participant: Participant,\n    participantPeerId: PeerId,\n    chat: Chat.chat | Chat.channel,\n    isBroadcast: boolean,\n    isBanned: boolean,\n    canChangePermissions: boolean,\n    canManageAdmins: boolean;\n\n  const openPermissions = (isAdmin?: boolean) => {\n    openUserPermissionsTab(slider, chatId, participant, isAdmin);\n  };\n\n  function getButtons(): ButtonMenuItemOptionsVerifiable[] {\n    return [{\n      icon: 'message',\n      text: 'SendMessage',\n      onClick: () => {\n        appImManager.setInnerPeer({peerId: participantPeerId});\n      }\n    }, {\n      icon: 'adduser',\n      text: isBroadcast ? 'AddToChannel' : 'AddToGroup',\n      onClick: () => {\n        if(isBanned) {\n          rootScope.managers.appChatsManager.addToChat(chatId, participantPeerId)\n          .then((missingInvitees) => {\n            handleMissingInvitees(chatId, missingInvitees);\n          });\n        }\n      },\n      verify: () => {\n        if(bannedParticipantAdapter || !isBanned) {\n          return false;\n        }\n\n        return true;\n      }\n    }, {\n      icon: 'promote',\n      text: 'SetAsAdmin',\n      onClick: () => openPermissions(true),\n      verify: () => !bannedParticipantAdapter &&\n        canManageAdmins &&\n        !isParticipantAdmin(participant)\n    }, {\n      icon: 'admin',\n      text: 'EditAdminRights',\n      onClick: () => openPermissions(true),\n      verify: () => !bannedParticipantAdapter &&\n        isParticipantAdmin(participant) &&\n        canEditAdmin(\n          chat,\n          participant as ChannelParticipant,\n          rootScope.myId\n        )\n    }, {\n      icon: 'restrict',\n      text: 'KickFromSupergroup',\n      onClick: () => openPermissions(false),\n      verify: () => !bannedParticipantAdapter &&\n        canChangePermissions && (\n        participant._ === 'channelParticipant' ||\n        participant._ === 'chatParticipant' ||\n        (participant._ === 'channelParticipantBanned' && !participant.pFlags.left)\n      )\n    }, {\n      icon: 'delete',\n      text: 'Delete',\n      onClick: () => {\n        if(isBanned) {\n          if(bannedParticipantAdapter) {\n            return bannedParticipantAdapter.unban(\n              participantPeerId,\n              participant\n            );\n          }\n\n          rootScope.managers.appChatsManager.editBanned(\n            chatId,\n            participant,\n            {\n              _: 'chatBannedRights',\n              pFlags: {},\n              until_date: 0\n            }\n          );\n        }\n      },\n      verify: () => {\n        if(!isBanned || !canChangePermissions || participantPeerId === rootScope.myId) {\n          return false;\n        }\n\n        return true;\n      }\n    }, {\n      icon: 'delete',\n      text: 'KickFromGroup',\n      onClick: () => {\n        rootScope.managers.appChatsManager.kickFromChat(chatId, participantPeerId);\n      },\n      verify: () => !bannedParticipantAdapter &&\n        canChangePermissions &&\n        participantPeerId !== rootScope.myId &&\n        !isParticipantCreator(participant) &&\n        (!isParticipantAdmin(participant) || canEditAdmin(chat, participant, rootScope.myId)) &&\n        (participant._ === 'channelParticipant' || !isBanned)\n    }];\n  }\n\n  const buttons: ButtonMenuItemOptionsVerifiable[] = [];\n  return createContextMenu({\n    listenTo: listenTo,\n    appendTo,\n    middleware,\n    findElement: (e) => target = findUpClassName(e.target, 'chatlist-chat'),\n    onOpen: async() => {\n      participantPeerId = target.dataset.peerId.toPeerId();\n      participant = participants.get(participantPeerId);\n      if(bannedParticipantAdapter) {\n        isBroadcast = false;\n        canChangePermissions = await bannedParticipantAdapter.hasRights();\n        canManageAdmins = false;\n      } else {\n        [chat, isBroadcast, canChangePermissions, canManageAdmins] = await Promise.all([\n          rootScope.managers.appChatsManager.getChat(chatId) as Promise<typeof chat>,\n          rootScope.managers.appChatsManager.isBroadcast(chatId),\n          rootScope.managers.appChatsManager.hasRights(chatId, 'change_permissions'),\n          rootScope.managers.appChatsManager.hasRights(chatId, 'change_permissions')\n        ]);\n      }\n\n      target.classList.add('menu-open');\n      isBanned = canChangePermissions && participant._ === 'channelParticipantBanned' && participant.pFlags.left;\n      buttons.splice(0, Infinity, ...getButtons());\n      return onOpen?.();\n    },\n    onClose: () => {\n      target.classList.remove('menu-open');\n      return onClose?.();\n    },\n    buttons\n  });\n}\n","import IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {AppManagers} from '@lib/managers';\nimport {toastNew} from '@components/toast';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {AppSelection} from '@components/chat/selection';\nimport {createSignal} from 'solid-js';\nimport {LangPackKey} from '../../lib/langPack';\n\nexport function toastStoryPinnedToProfile(managers: AppManagers, peerId: PeerId, pin: boolean) {\n  if(peerId.isUser()) {\n    return toastNew({langPackKey: pin ? 'StoryPinnedToProfile' : 'StoryArchivedFromProfile'});\n  } else {\n    managers.appChatsManager.isBroadcast(peerId.toChatId()).then((isBroadcast) => {\n      let key: LangPackKey;\n      if(isBroadcast) {\n        key = pin ? 'StoryPinnedToChannel' : 'StoryArchivedFromChannel';\n      } else {\n        key = pin ? 'StoryPinnedToGroup' : 'StoryArchivedFromGroup';\n      }\n\n      toastNew({langPackKey: key});\n    })\n  }\n}\n\nexport class StoriesSelection extends AppSelection {\n  public isStoriesArchive: boolean;\n\n  private mainContainer: HTMLElement;\n\n  private readonly _setSelecting: (v: boolean) => void;\n  private readonly _setCount: (v: number) => void;\n  private readonly _setCantPin: (v: boolean) => void;\n  private readonly _setCantDelete: (v: boolean) => void;\n\n  public readonly selecting: () => boolean;\n  public readonly count: () => number;\n  public readonly cantPin: () => boolean;\n  public readonly cantDelete: () => boolean;\n\n  public forPicker: boolean;\n\n  constructor(options: {\n    container: HTMLElement,\n    managers: AppManagers,\n    chatId?: ChatId,\n    listenerSetter: ListenerSetter,\n    isArchive?: boolean,\n    forPicker?: boolean\n  }) {\n    super({\n      managers: options.managers,\n      verifyTarget: (e, target) => !!target && this.isSelecting,\n      getElementFromTarget: (target) => {\n        let el: HTMLElement = target;\n        while(el && !el.classList.contains('search-super-item')) {\n          el = el.parentElement;\n        }\n        return el;\n      },\n      targetLookupClassName: 'search-super-item',\n      lookupBetweenParentClassName: 'tabs-tab',\n      lookupBetweenElementsQuery: '.search-super-item'\n    });\n\n    this.isStoriesArchive = options.isArchive;\n    this.forPicker = options.forPicker;\n    this.mainContainer = options.container;\n\n    const [selecting, setSelecting] = createSignal(false);\n    const [count, setCount] = createSignal(0);\n    const [cantPin, setCantPin] = createSignal(true);\n    const [cantDelete, setCantDelete] = createSignal(true);\n\n    this.selecting = selecting;\n    this._setSelecting = setSelecting;\n    this.count = count;\n    this._setCount = setCount;\n    this.cantPin = cantPin;\n    this._setCantPin = setCantPin;\n    this.cantDelete = cantDelete;\n    this._setCantDelete = setCantDelete;\n\n    !IS_TOUCH_SUPPORTED && this.attachListeners(options.container, options.listenerSetter);\n  }\n\n  private getSelectedStoriesPeerId() {\n    return [...this.selectedMids.keys()][0];\n  }\n\n  protected async updateContainer(forceSelection = false) {\n    const size = this.selectedMids.size;\n    if(!size && !forceSelection) return;\n\n    // `forceSelection` enters selection mode with nothing selected yet (the album picker opens that\n    // way), so there is no peer and no mids — `cantPinDeleteStories` answers \"can't\" for an empty\n    // list, which is what an empty selection means.\n    const peerId = this.selectedMids.keys().next().value;\n    const r = await this.managers.appStoriesManager.cantPinDeleteStories(peerId, Array.from(this.selectedMids.get(peerId) ?? []));\n    this._setCount(this.length());\n    this._setCantPin(r.cantPin);\n    this._setCantDelete(r.cantDelete);\n  }\n\n  public toggleSelection(toggleCheckboxes = true, forceSelection = false) {\n    const ret = super.toggleSelection(toggleCheckboxes, forceSelection || this.forPicker);\n\n    if(ret && toggleCheckboxes) {\n      const elements = Array.from(this.mainContainer.querySelectorAll('.search-super-item')) as HTMLElement[];\n      elements.forEach((element) => {\n        this.toggleElementCheckbox(element, this.isSelecting);\n      });\n    }\n\n    return ret;\n  }\n\n  public toggleByElement = (element: HTMLElement) => {\n    const mid = +element.dataset.mid;\n    const peerId = element.dataset.peerId.toPeerId();\n\n    if(!this.toggleMid(peerId, mid)) {\n      return;\n    }\n\n    this.updateElementSelection(element, this.isMidSelected(peerId, mid));\n  };\n\n  public getSelectedStoryIds(peerId: PeerId) {\n    const mids = this.selectedMids.get(peerId);\n    if(mids?.size) {\n      return [...mids];\n    }\n\n    return [];\n  }\n\n  public onDeleteStoriesClick = async(ids?: number[], peerId?: PeerId) => {\n    peerId ??= this.getSelectedStoriesPeerId();\n    ids ||= [...this.selectedMids.get(peerId)];\n    await confirmationPopup({\n      titleLangKey: ids.length === 1 ? 'DeleteStoryTitle' : 'DeleteStoriesTitle',\n      descriptionLangKey: ids.length === 1 ? 'DeleteStorySubtitle' : 'DeleteStoriesSubtitle',\n      descriptionLangArgs: [ids.length],\n      button: {\n        langKey: 'Delete',\n        isDanger: true\n      }\n    });\n    this.cancelSelection();\n    this.managers.appStoriesManager.deleteStories(peerId, ids);\n  };\n\n  public onPinStoriesClick = (ids: number[], pin: boolean, peerId?: PeerId) => {\n    peerId ??= this.getSelectedStoriesPeerId();\n    ids ||= [...this.selectedMids.get(peerId)];\n    const promise = this.managers.appStoriesManager.togglePinned(peerId, ids, pin);\n    this.cancelSelection();\n    promise.then(async() => {\n      if(ids.length === 1) {\n        toastStoryPinnedToProfile(this.managers, peerId, pin);\n      } else {\n        let key: LangPackKey;\n        if(peerId.isUser()) {\n          key = pin ? 'StorySavedTitle' : 'StoryArchived';\n        } else {\n          const isBroadcast = await this.managers.appChatsManager.isBroadcast(peerId.toChatId());\n          if(isBroadcast) {\n            key = pin ? 'StorySavedChannelTitle' : 'StoryChannelArchived';\n          } else {\n            key = pin ? 'StorySavedGroupTitle' : 'StoryGroupArchived';\n          }\n        }\n\n        toastNew({langPackKey: key, langPackArguments: [ids.length]});\n      }\n    });\n  };\n\n  public onPinStoriesToTopClick = (ids?: number[], pin: boolean = true, peerId?: PeerId) => {\n    peerId ??= this.getSelectedStoriesPeerId();\n    ids ||= [...this.selectedMids.get(peerId)];\n    const promise = this.managers.appStoriesManager.togglePinnedToTop(peerId, ids, pin);\n    this.cancelSelection();\n    promise.catch((err: ApiError) => {\n      if(err.type === 'STORY_ID_TOO_MANY') {\n        toastNew({langPackKey: 'StoriesPinLimit', langPackArguments: [+err.message]});\n      }\n    });\n  };\n\n  protected onToggleSelection = (forwards: boolean, animate: boolean) => {\n    this._setSelecting(forwards);\n\n    this.mainContainer.classList.toggle('is-selecting', forwards);\n    if(!forwards) {\n      this.selectedText = undefined;\n    }\n  };\n}\n","import PopupElement, {PopupButton} from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport Scrollable from '@components/scrollable';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {StoriesProfileList} from '@components/stories/profileList';\nimport {StoryItem} from '@layer';\nimport {createEffect, createRoot, on} from 'solid-js';\nimport {getFirstChild} from '@solid-primitives/refs';\nimport {i18n} from '@lib/langPack';\nimport replaceContent from '@helpers/dom/replaceContent';\n\nimport styles from '@components/popups/chooseStoryPopup.module.scss';\n\nexport default class PopupChooseStory extends PopupElement<{\n  finish: (result: {added: number[], removed: number[]} | null) => void\n}> {\n  private peerId: PeerId;\n  private albumId: number;\n\n  private finished = false;\n  private getResult: () => {added: number[], removed: number[]};\n\n  constructor(options: {\n    peerId: PeerId,\n    albumId: number\n  }) {\n    const confirmButton: PopupButton = {\n      langKey: 'Confirm',\n      callback: () => {\n        this.finished = true;\n        this.dispatchEvent('finish', this.getResult());\n      }\n    };\n\n    super(styles.popup, {\n      overlayClosable: true,\n      closable: true,\n      title: 'Stories.Albums.AddToAlbum',\n      body: true,\n      buttons: [\n        confirmButton,\n        {\n          langKey: 'Cancel',\n          callback: () => {\n            this.finished = true;\n            this.dispatchEvent('finish', null);\n          }\n        }\n      ]\n    });\n\n    this.addEventListener('close', () => {\n      if(!this.finished) {\n        this.dispatchEvent('finish', null);\n      }\n    });\n\n    safeAssign(this, options);\n    this.construct(confirmButton);\n  }\n\n  protected construct(confirmButton: PopupButton) {\n    const scrollable = new Scrollable(this.body);\n    scrollable.container.classList.add('search-super'); // ! for selection\n    const listenerSetter = new ListenerSetter();\n    this.addEventListener('closeAfterTimeout', () => listenerSetter.removeAll());\n\n    createRoot((dispose) => {\n      this.addEventListener('closeAfterTimeout', dispose as any);\n\n      const {render, state, selection, actions} = StoriesProfileList({\n        peerId: this.peerId,\n        archive: true,\n        scrollable,\n        listenerSetter,\n        withSelection: true,\n        forPicker: true\n      });\n\n      const el = getFirstChild(render, (v) => v instanceof Element) as Element;\n      if(el) scrollable.append(el);\n\n      actions.load();\n\n      selection.toggleSelection(true, true);\n\n      // auto-select stories already in the album as they load\n      const originalIds = new Set<number>();\n      createEffect(on(() => state.peer?.stories, (stories) => {\n        if(!stories) return;\n        for(const story of stories) {\n          if(story._ === 'storyItem' && story.albums?.includes(this.albumId) && !originalIds.has(story.id)) {\n            originalIds.add(story.id);\n            if(!selection.isMidSelected(this.peerId, story.id)) {\n              selection.toggleMid(this.peerId, story.id);\n            }\n          }\n        }\n      }));\n\n      scrollable.onScrolledBottom = () => {\n        actions.load();\n      };\n\n      this.getResult = () => {\n        const currentMids = selection.selectedMids.get(this.peerId);\n        const current = currentMids ? new Set(currentMids) : new Set<number>();\n        const added: number[] = [];\n        const removed: number[] = [];\n        for(const id of current) {\n          if(!originalIds.has(id)) added.push(id);\n        }\n        for(const id of originalIds) {\n          if(!current.has(id)) removed.push(id);\n        }\n        return {added, removed};\n      };\n\n      createEffect(on(selection.count, () => {\n        const {added, removed} = this.getResult();\n        const changed = added.length || removed.length;\n        if(confirmButton.element) {\n          replaceContent(confirmButton.element, i18n('Confirm'));\n          confirmButton.element.toggleAttribute('disabled', changed === 0 && !originalIds.size);\n        }\n      }));\n    });\n  }\n}\n","import {createEffect, createSignal, For, JSX, createMemo, onCleanup, untrack, createReaction, Show, Switch, Match} from 'solid-js';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport {Portal} from 'solid-js/web';\nimport {createStoriesViewer, createStoriesViewerWithPeer} from '@components/stories/viewer';\nimport {Document, MessageMedia, Photo, StoryItem} from '@layer';\nimport {wrapStoryMedia} from '@components/stories/preview';\nimport getMediaThumbIfNeeded from '@helpers/getStrippedThumbIfNeeded';\nimport {StoriesContext, useStories, createStoriesStore, StoriesContextState} from '@components/stories/store';\nimport Icon from '@components/icon';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\nimport {i18n} from '@lib/langPack';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport fastSmoothScroll from '@helpers/fastSmoothScroll';\nimport Scrollable from '@components/scrollable';\nimport {AnimationList} from '@helpers/solid/animationList';\nimport {doubleRaf} from '@helpers/schedulers';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport ButtonTsx from '@components/buttonTsx';\nimport {StoriesSelection, toastStoryPinnedToProfile} from './selection';\nimport {ButtonMenuItemOptions, ButtonMenuSync} from '@components/buttonMenu';\nimport CheckboxField from '@components/checkboxField';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport contextMenuController from '@helpers/contextMenuController';\nimport positionMenu from '@helpers/positionMenu';\nimport rootScope from '@lib/rootScope';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport {attachClickEvent} from '@helpers/dom/clickEvent';\nimport cancelClickOrNextIfNotClick from '@helpers/dom/cancelClickOrNextIfNotClick';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {AppMyStoriesTab} from '@components/solidJsTabs/tabs';\nimport SidebarSlider from '../slider';\nimport InputField from '@components/inputField';\nimport confirmationPopup from '@components/confirmationPopup';\nimport PopupElement from '@components/popups';\nimport PopupChooseStory from '@components/popups/chooseStoryPopup';\nimport createSubmenuTrigger from '@components/createSubmenuTrigger';\nimport showStoriesStealthModePopup from '@components/popups/storiesStealthMode';\nimport {toastNew} from '@components/toast';\nimport {IconTsx} from '@components/iconTsx';\nimport LottieAnimation from '@components/lottieAnimation';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {handleShareStory} from './share';\nimport wrapPeerTitle from '../wrappers/peerTitle';\n\nconst ALL_ALBUMS_ID = -1;\nconst ADD_ALBUM_ID = -2;\n\nconst TEST_ONE = false;\nconst TEST_TWO = false;\n\nclass StoriesContextMenu {\n  private buttons: ButtonMenuItemOptionsVerifiable[];\n  private element: HTMLElement;\n  private target: HTMLElement;\n  private peerId: PeerId;\n  private mid: number;\n  private isSelected: boolean;\n  private storyItem: StoryItem.storyItem;\n\n  constructor(\n    private attachTo: HTMLElement,\n    private selection: StoriesSelection | undefined,\n    private listenerSetter: ListenerSetter,\n    private state: StoriesContextState\n  ) {\n    attachContextMenuListener({\n      element: attachTo,\n      callback: (e) => {\n        if(this.init) {\n          this.init();\n          this.init = null;\n        }\n\n        let item: HTMLElement;\n        try {\n          item = findUpClassName(e.target, 'search-super-item');\n        } catch(e) {}\n\n        if(!item) return;\n\n        if(!('touches' in e)) e.preventDefault(); // cross-realm-safe mouse check (Document PiP window)\n        if(this.element.classList.contains('active')) {\n          return false;\n        }\n        if(!('touches' in e)) e.cancelBubble = true;\n\n        const r = async() => {\n          this.target = item;\n          this.peerId = item.dataset.peerId.toPeerId();\n          this.mid = +item.dataset.mid;\n          this.isSelected = selection?.isMidSelected(this.peerId, this.mid);\n          this.storyItem = await rootScope.managers.appStoriesManager.getStoryById(this.peerId, this.mid);\n\n          const f = await Promise.all(this.buttons.map(async(button) => {\n            const good = button.verify ? !!(await button.verify()) : true;\n            button.element.classList.toggle('hide', !good);\n            return good;\n          }));\n\n          if(!f.some((v) => v)) {\n            return;\n          }\n\n          item.classList.add('menu-open');\n\n          positionMenu(e, this.element);\n          contextMenuController.openBtnMenu(this.element, () => {\n            item.classList.remove('menu-open');\n          });\n        };\n\n        r();\n      },\n      listenerSetter\n    });\n  }\n\n  private init() {\n    const managers = rootScope.managers;\n    const getSelectedIds = () => {\n      if(this.selection && this.selection.isSelecting) {\n        return this.selection.getSelectedStoryIds(this.peerId);\n      }\n      return [this.storyItem.id];\n    }\n    const hasRightsOnSelected = (right: 'send' | 'edit' | 'delete' | 'archive' | 'pin') => {\n      const ids = getSelectedIds();\n      return managers.appStoriesManager.hasRightsMany(this.peerId, ids, right);\n    }\n\n    this.buttons = [{\n      icon: 'archive',\n      text: 'Archive',\n      onClick: () => managers.appStoriesManager.togglePinned(this.peerId, [this.storyItem.id], false).then(() => toastStoryPinnedToProfile(managers, this.peerId, false)),\n      verify: () => !this.state.albumId && this.storyItem?.pFlags.pinned && managers.appStoriesManager.hasRights(this.peerId, this.storyItem.id, 'pin')\n    }, {\n      icon: 'unarchive',\n      text: 'Unarchive',\n      onClick: () => managers.appStoriesManager.togglePinned(this.peerId, [this.storyItem.id], true).then(() => toastStoryPinnedToProfile(managers, this.peerId, true)),\n      verify: () => !this.state.albumId && this.storyItem && !this.storyItem.pFlags.pinned && managers.appStoriesManager.hasRights(this.peerId, this.storyItem.id, 'pin')\n    }, {\n      icon: 'pin',\n      text: 'ChatList.Context.Pin',\n      onClick: () => managers.appStoriesManager.togglePinnedToTop(this.peerId, [this.storyItem.id], true).catch((err: ApiError) => {\n        if(err.type === 'STORY_ID_TOO_MANY') {\n          toastNew({langPackKey: 'StoriesPinLimit', langPackArguments: [+err.message]});\n        }\n      }),\n      verify: () => !this.state.albumId && this.state.pinned && this.storyItem?.pinnedIndex === undefined && managers.appStoriesManager.hasRights(this.peerId, this.storyItem.id, 'pin')\n    }, {\n      icon: 'unpin',\n      text: 'ChatList.Context.Unpin',\n      onClick: () => managers.appStoriesManager.togglePinnedToTop(this.peerId, [this.storyItem.id], false),\n      verify: () => !this.state.albumId && this.state.pinned && this.storyItem?.pinnedIndex !== undefined && managers.appStoriesManager.hasRights(this.peerId, this.storyItem.id, 'pin')\n    }, createSubmenuTrigger({\n      options: {\n        icon: 'folder',\n        text: 'Stories.Albums.AddToAlbum',\n        verify: () => !this.state.albumId && !!(this.state.peer?.albums?.length) && hasRightsOnSelected('edit')\n      },\n      createSubmenu: async() => {\n        const selectedIds = getSelectedIds();\n        const selectedStories = await managers.appStoriesManager.getStoriesById(this.peerId, selectedIds);\n\n        const buttons: ButtonMenuItemOptions[] = this.state.peer?.albums.map((album) => {\n          const checkboxField = new CheckboxField({\n            checked: selectedStories.every((story) => {\n              return story?._ === 'storyItem' && !!story.albums?.includes(album.album_id);\n            })\n          });\n\n          const span = document.createElement('span');\n          span.classList.add('stories-album-title');\n          span.append(wrapEmojiText(album.title));\n\n          return {\n            textElement: span,\n            onClick: () => {\n              const wasChecked = checkboxField.checked;\n              checkboxField.checked = !wasChecked;\n              rootScope.managers.appStoriesManager.updateAlbum(this.peerId, album.album_id, {\n                [wasChecked ? 'deleteStories' : 'addStories']: selectedIds\n              }).catch(() => {\n                checkboxField.checked = wasChecked;\n                toastNew({langPackKey: 'Error.AnError'});\n              });\n            },\n            checkboxField,\n            noCheckboxClickListener: true,\n            keepOpen: true\n          };\n        });\n\n        return ButtonMenuSync({buttons, listenerSetter: this.listenerSetter});\n      }\n    }), {\n      icon: 'crossround',\n      text: 'Stories.Albums.RemoveFromAlbum',\n      onClick: () => {\n        const albumId = this.state.albumId;\n        const storyIds = getSelectedIds()\n        if(this.selection.isSelecting) this.selection.cancelSelection();\n        rootScope.managers.appStoriesManager.updateAlbum(this.peerId, albumId, {deleteStories: storyIds}).then(() => {\n          toastNew({langPackKey: 'Stories.Albums.Removed', langPackArguments: [storyIds.length]});\n        }).catch(() => {\n          toastNew({langPackKey: 'Error.AnError'});\n        });\n      },\n      verify: () => this.state.albumId !== undefined && hasRightsOnSelected('edit')\n    }, {\n      icon: 'link',\n      text: 'CopyLink',\n      onClick: async() => {\n        const username = await rootScope.managers.appPeersManager.getPeerUsername(this.peerId);\n        copyTextToClipboard(`https://t.me/${username}/s/${this.storyItem.id}`);\n        toastNew({langPackKey: 'LinkCopied'});\n      },\n      verify: async() => {\n        const username = await rootScope.managers.appPeersManager.getPeerUsername(this.peerId);\n        return !!username;\n      }\n    }, {\n      icon: 'forward',\n      text: 'ShareFile',\n      onClick: async() => {\n        handleShareStory({\n          story: this.storyItem,\n          peerId: this.peerId,\n          onSend: async(toPeerId: PeerId) => {\n            toastNew({\n              langPackKey: toPeerId === rootScope.myId ? 'StorySharedToSavedMessages' : 'StorySharedTo',\n              langPackArguments: [await wrapPeerTitle({peerId: toPeerId})]\n            })\n          }\n        });\n      },\n      verify: async() => {\n        const username = await rootScope.managers.appPeersManager.getPeerUsername(this.peerId);\n        if(!username) return false;\n\n        const story = this.storyItem;\n        return !!story.pFlags.public && (!story.pFlags.noforwards || !!username)\n      }\n    }, {\n      icon: 'eyecross',\n      text: 'Stories.StealthMode.View',\n      onClick: () => {\n        const {peerId} = this;\n        const id = this.storyItem.id;\n        showStoriesStealthModePopup({\n          onActivate: () => {\n            createStoriesViewerWithPeer({peerId, id});\n          }\n        });\n      },\n      verify: () => this.peerId !== rootScope.myId\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Select',\n      onClick: () => this.selection.toggleByElement(this.target),\n      verify: () => !!this.selection && !this.isSelected && this.state.canEdit\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Selection.Clear',\n      onClick: () => this.selection.cancelSelection(),\n      verify: () => !!this.selection && this.isSelected\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Delete',\n      onClick: () => this.selection.onDeleteStoriesClick([this.storyItem.id], this.peerId),\n      verify: () => managers.appStoriesManager.hasRights(this.peerId, this.storyItem.id, 'delete')\n    }];\n\n    this.element = ButtonMenuSync({buttons: this.buttons, listenerSetter: this.listenerSetter});\n    this.element.classList.add('search-contextmenu', 'contextmenu');\n    getOverlayRoot().append(this.element);\n\n    this.buttons.forEach((button) => button.onOpen?.());\n  }\n}\n\nasync function openCreateAlbumPopup(peerId: PeerId): Promise<number | undefined> {\n  const inputField = new InputField({\n    maxLength: 64,\n    placeholder: 'Stories.Albums.CreatePlaceholder',\n    required: true\n  });\n\n  try {\n    await confirmationPopup({\n      titleLangKey: 'Stories.Albums.CreateTitle',\n      inputField,\n      button: {langKey: 'Create'}\n    });\n  } catch(e) {\n    return;\n  }\n\n  const album = await rootScope.managers.appStoriesManager.createAlbum(peerId, inputField.value);\n  return album.album_id;\n}\n\nfunction StoriesAlbums(props: {\n  selection?: StoriesSelection,\n  onAlbumChange: (albumId: number | undefined) => void,\n  peerId: PeerId\n}) {\n  const [stories] = useStories();\n  const hasAlbums = () => stories.ready && stories.peer.albums && stories.peer.albums.length > 0;\n  const chosenAlbumId = () => stories.albumId === undefined ? ALL_ALBUMS_ID : stories.albumId;\n\n  const handleChange = (value: string) => {\n    const albumId = Number(value);\n    if(albumId === ADD_ALBUM_ID) {\n      openCreateAlbumPopup(props.peerId).then((albumId) => {\n        if(albumId !== undefined) props.onAlbumChange(albumId);\n      });\n      return false;\n    }\n    if(props.selection?.isSelecting) props.selection.cancelSelection()\n    props.onAlbumChange(albumId === ALL_ALBUMS_ID ? undefined : albumId);\n  }\n\n  return (\n    <Show when={hasAlbums()}>\n      <ChipTabs\n        class=\"search-super-content-stories-albums\"\n        value={chosenAlbumId().toString()}\n        onChange={handleChange}\n        view=\"surface\"\n        center\n        needIntersectionObserver\n        contextMenuButtons={async(id_) => {\n          const id = Number(id_);\n          if(id === ALL_ALBUMS_ID || id === ADD_ALBUM_ID) return [];\n\n          const album = stories.peer.albums?.find((a) => a.album_id === id);\n          if(!album) return [];\n\n          return [\n            {\n              icon: 'link',\n              text: 'CopyLink',\n              onClick: async() => {\n                const username = await rootScope.managers.appPeersManager.getPeerUsername(props.peerId);\n                copyTextToClipboard(`https://t.me/${username}/a/${id}`);\n                toastNew({langPackKey: 'LinkCopied'});\n              },\n              verify: async() => {\n                const username = await rootScope.managers.appPeersManager.getPeerUsername(props.peerId);\n                return !!username;\n              }\n            },\n            {\n              icon: 'add',\n              text: 'Stories.Albums.AddStories',\n              verify: () => stories.canEdit,\n              onClick: () => openAddToAlbumPopup(props.peerId, id)\n            },\n            {\n              icon: 'edit',\n              text: 'Stories.Albums.Rename',\n              verify: () => stories.canEdit,\n              onClick: async() => {\n                const inputField = new InputField({\n                  maxLength: 64,\n                  placeholder: 'Stories.Albums.CreatePlaceholder',\n                  required: true\n                });\n                inputField.value = album.title;\n\n                try {\n                  await confirmationPopup({\n                    titleLangKey: 'Stories.Albums.RenameTitle',\n                    inputField,\n                    button: {langKey: 'Edit'}\n                  });\n                } catch(e) {\n                  return;\n                }\n\n                if(inputField.value === album.title) return;\n                rootScope.managers.appStoriesManager.updateAlbum(props.peerId, id, {title: inputField.value}).catch(() => {\n                  toastNew({langPackKey: 'Error.AnError'});\n                });\n              }\n            },\n            {\n              icon: 'delete',\n              text: 'Stories.Albums.Delete',\n              verify: () => stories.canEdit,\n              danger: true,\n              onClick: async() => {\n                try {\n                  await confirmationPopup({\n                    titleLangKey: 'Stories.Albums.Delete',\n                    descriptionLangKey: 'Stories.Albums.DeleteConfirm',\n                    button: {langKey: 'Delete', isDanger: true}\n                  });\n                } catch(e) {\n                  return;\n                }\n\n                rootScope.managers.appStoriesManager.deleteAlbum(props.peerId, id).catch(() => {\n                  toastNew({langPackKey: 'Error.AnError'});\n                });\n              }\n            }\n          ];\n        }}\n      >\n        <ChipTab value={ALL_ALBUMS_ID.toString()}>\n          {i18n('StoryAlbumAll')}\n        </ChipTab>\n        <For each={stories.peer.albums}>\n          {(album) => (\n            <ChipTab class=\"stories-album-chip\" value={album.album_id.toString()}>\n              <span class=\"stories-album-chip-title\">\n                {wrapEmojiText(album.title)}\n              </span>\n            </ChipTab>\n          )}\n        </For>\n        <Show when={stories.canEdit}>\n          <ChipTab value={ADD_ALBUM_ID.toString()}>\n            <IconTsx icon=\"add\" />\n            <I18nTsx key=\"Stories.Albums.AddAlbum\" />\n          </ChipTab>\n        </Show>\n      </ChipTabs>\n    </Show>\n  );\n}\n\nasync function openAddToAlbumPopup(peerId: PeerId, albumId: number) {\n  const popup = PopupElement.createPopup(PopupChooseStory, {peerId, albumId});\n  popup.show();\n\n  const result = await new Promise<{added: number[], removed: number[]} | null>((resolve) => {\n    popup.addEventListener('finish', resolve);\n  });\n\n  if(!result) return;\n  const {added, removed} = result;\n  if(!added.length && !removed.length) return;\n  rootScope.managers.appStoriesManager.updateAlbum(peerId, albumId, {\n    addStories: added.length ? added : undefined,\n    deleteStories: removed.length ? removed : undefined\n  }).catch(() => {\n    toastNew({langPackKey: 'Error.AnError'});\n  });\n}\n\nfunction StoriesGrid(props: {\n  scrollable: Scrollable,\n  onReady?: () => void,\n  peerId: PeerId,\n  selection?: StoriesSelection,\n  pinned: boolean,\n  archive?: boolean,\n  onSetAlbumAnimated?: (fn: (albumId: number | undefined) => void) => void\n}) {\n  const [stories, actions] = useStories();\n  const [viewerId, setViewerId] = createSignal<number>();\n  const items = new Map<number, HTMLElement>();\n\n  createReaction(() => {\n    props.onReady?.();\n  })(() => stories.ready);\n\n  createEffect(() => {\n    const id = viewerId();\n    if(!id) {\n      return;\n    }\n\n    const onExit = () => {\n      setViewerId(undefined);\n    };\n\n    const target = createMemo(() => {\n      const storyId = stories.peer.stories[stories.peer.index].id;\n      return items.get(storyId);\n    });\n\n    untrack(() => {\n      const peer = stories.peer;\n      const index = peer.stories.findIndex((story) => story.id === id);\n      actions.set({peer, index});\n    });\n\n    createStoriesViewer({\n      onExit,\n      target,\n      splitByDays: true\n    });\n  });\n\n  const Item = (storyItem: StoryItem) => {\n    const {container, div, media, thumb} = wrapStoryMedia({\n      peerId: stories.peer.peerId,\n      storyItem: storyItem as StoryItem.storyItem,\n      forPreview: true,\n      noAspecter: true,\n      containerProps: {\n        // @ts-ignore\n        'data-mid': storyItem.id,\n        'data-peer-id': stories.peer.peerId,\n        'data-timestamp': (storyItem as StoryItem.storyItem).date,\n        'class': 'grid-item search-super-item',\n        'onClick': () => {\n          setViewerId(storyItem.id);\n        }\n      },\n      childrenClassName: 'grid-item-media',\n      noPlayButton: true\n    });\n\n    let icon: HTMLElement;\n    let archiveIcon: HTMLElement;\n    createEffect(() => {\n      const t = thumb();\n      const m = media();\n      const element = m || t;\n      if(!element) {\n        return;\n      }\n\n      items.set(storyItem.id, element);\n      onCleanup(() => {\n        items.delete(storyItem.id);\n      });\n\n      if(stories.peer.stories.length === 1) {\n        const messageMedia = (storyItem as StoryItem.storyItem).media;\n        const media = (messageMedia as MessageMedia.messageMediaPhoto).photo as Photo.photo || (messageMedia as MessageMedia.messageMediaDocument).document as Document.document;\n        const gotThumb = getMediaThumbIfNeeded({\n          photo: media,\n          cacheContext: {type: 'x', url: '', downloaded: 0},\n          useBlur: true,\n          ignoreCache: true,\n          onlyStripped: true\n        });\n        const thumb = gotThumb.image as HTMLCanvasElement;\n        element.parentElement.prepend(thumb);\n\n        // need img for clone animation to work\n        gotThumb.loadPromise.then(() => {\n          const img = document.createElement('img');\n          img.className = thumb.className;\n          img.src = thumb.toDataURL();\n          thumb.replaceWith(img);\n        });\n\n        onCleanup(() => {\n          thumb.remove();\n        });\n      }\n\n      if(element.parentElement && props.pinned && !stories.albumId && (storyItem as StoryItem.storyItem).pinnedIndex !== undefined) {\n        icon ??= Icon('pin2_filled', 'grid-item-pin');\n        element.parentElement.append(icon);\n      } else if(icon) {\n        icon.remove();\n      }\n\n      if(element.parentElement && props.archive && !(storyItem as StoryItem.storyItem).pFlags.pinned) {\n        archiveIcon ??= Icon('hide', 'grid-item-archived');\n        element.parentElement.append(archiveIcon);\n      } else if(archiveIcon) {\n        archiveIcon.remove();\n      }\n    });\n\n    if(props.selection?.isSelecting) {\n      props.selection.toggleElementCheckbox(div, true);\n    }\n\n    return container;\n  };\n\n  const isEmpty = () => stories.peer?.stories?.length === 0;\n  const isLoading = () => !stories.ready || (!stories.loaded && isEmpty())\n\n  const SLIDE_DURATION = 250;\n  const SLIDE_EASING = 'cubic-bezier(.4, 0, .2, 1)';\n\n  const [direction, setDirection] = createSignal(0);\n  let scrollDiff = 0;\n\n  const slideKeyframes = (_element: Element, removed: boolean): Keyframe[] => {\n    const dir = direction();\n    const yOffset = scrollDiff ? ` translateY(${scrollDiff}px)` : '';\n    if(removed) {\n      // AnimationList reverses these for exit; Y offset compensates scroll change\n      return [\n        {transform: `translateX(${-dir * 100}%)${yOffset}`},\n        {transform: `translateX(0)${yOffset}`}\n      ];\n    }\n    return [{transform: `translateX(${dir * 100}%)`}, {transform: 'translateX(0)'}];\n  };\n\n  const scrollPositions = new Map<number | undefined, number>();\n  let wrapperRef!: HTMLDivElement;\n\n  const getScrollBase = () => {\n    const searchSuper = wrapperRef?.closest('.search-super') as HTMLElement;\n    if(!searchSuper) return 0;\n    // 0 for \"my stories\" tab\n    return searchSuper.offsetTop === 0 ? 0 : searchSuper.offsetTop - 56;\n  };\n\n  const setAlbumIdAnimated = (albumId: number | undefined) => {\n    const albums = stories.peer?.albums;\n    const oldIndex = stories.albumId === undefined ? -1 :\n      (albums?.findIndex((a) => a.album_id === stories.albumId) ?? -1);\n    const newIndex = albumId === undefined ? -1 :\n      (albums?.findIndex((a) => a.album_id === albumId) ?? -1);\n    const dir = newIndex > oldIndex ? 1 : newIndex < oldIndex ? -1 : 0;\n\n    const scrollable = props.scrollable.container;\n    const scrollBase = getScrollBase();\n    const oldScrollTop = scrollable.scrollTop;\n    const oldScroll = oldScrollTop - scrollBase;\n    if(oldScroll >= 0) {\n      scrollPositions.set(stories.albumId, Math.max(0, oldScroll));\n    }\n\n    if(dir) setDirection(dir);\n    actions.setAlbumId(albumId);\n\n    // restore scroll immediately (before paint) and compensate via keyframes Y offset\n    const newScroll = scrollPositions.get(albumId) ?? 0;\n    const targetScrollTop = scrollBase + newScroll;\n    if(oldScroll >= 0) {\n      scrollDiff = targetScrollTop - oldScrollTop;\n      scrollable.scrollTop = targetScrollTop;\n    } else {\n      scrollDiff = 0;\n      const searchSuper = wrapperRef?.closest('.search-super') as HTMLElement;\n      if(searchSuper) {\n        fastSmoothScroll({\n          element: searchSuper,\n          container: scrollable,\n          position: 'center',\n          axis: 'y',\n          getElementPosition: ({elementPosition}) => {\n            return elementPosition - 24;\n          }\n        });\n      }\n    }\n  };\n\n  props.onSetAlbumAnimated?.(setAlbumIdAnimated);\n\n  // memo keyed on albumId: creates a new element per album so AnimationList can animate the swap\n  const albumContent = createMemo(() => {\n    stories.albumId;\n    return untrack(() => (\n      <div class=\"stories-album-content\">\n        <Switch>\n          <Match when={isLoading()}>\n            <div class=\"grid-album-placeholder\">\n              <PreloaderTsx />\n            </div>\n          </Match>\n          <Match when={isEmpty() && stories.albumId !== undefined}>\n            <div class=\"grid-album-placeholder\">\n              <LottieAnimation\n                lottieLoader={lottieLoader}\n                name=\"UtyanStories\"\n                class=\"sticker-container\"\n              />\n              <I18nTsx key=\"Stories.Albums.EmptyTitle\" class=\"title\" />\n              <I18nTsx key=\"Stories.Albums.EmptySubtitle\" class=\"subtitle\" />\n              <ButtonTsx\n                class=\"btn-primary btn-color-primary btn-control\"\n                text=\"Stories.Albums.AddToAlbum\"\n                onClick={() => openAddToAlbumPopup(props.peerId, stories.albumId)}\n              />\n            </div>\n          </Match>\n          <Match when={true}>\n            <div\n              class=\"grid\"\n              classList={{two: stories.peer.stories.length === 2, one: stories.peer.stories.length === 1}}\n            >\n              <For each={stories.peer.stories}>{Item}</For>\n            </div>\n          </Match>\n        </Switch>\n      </div>\n    ));\n  });\n\n  return (\n    <div ref={wrapperRef} class=\"stories-album-wrapper\">\n      <AnimationList\n        animationOptions={{duration: SLIDE_DURATION, easing: SLIDE_EASING}}\n        keyframes={slideKeyframes}\n        mode=\"replacement\"\n      >\n        {albumContent()}\n      </AnimationList>\n    </div>\n  );\n}\n\nfunction StoriesSelectionToolbar(props: {\n  selection: StoriesSelection,\n  albumId?: number,\n  peerId?: PeerId,\n  pinned?: boolean,\n  mount?: HTMLElement\n}) {\n  const content = (\n    <div class=\"search-super-selection-container\">\n      <ButtonTsx\n        icon=\"close\"\n        class=\"search-super-selection-cancel btn-icon\"\n        onClick={() => props.selection.cancelSelection()}\n      />\n      <div class=\"search-super-selection-count\">\n        <I18nTsx key=\"StoriesCount\" args={[String(props.selection.count())]} />\n      </div>\n      <Show when={props.albumId !== undefined}>\n        <ButtonTsx\n          icon=\"crossround\"\n          class=\"search-super-selection-remove btn-icon\"\n          onClick={() => {\n            const mids = props.selection.selectedMids.get(props.peerId);\n            if(mids?.size) {\n              const count = mids.size;\n              rootScope.managers.appStoriesManager.updateAlbum(props.peerId, props.albumId, {deleteStories: [...mids]}).then(() => {\n                toastNew({langPackKey: 'Stories.Albums.Removed', langPackArguments: [count]});\n              }).catch(() => {\n                toastNew({langPackKey: 'Error.AnError'});\n              });\n            }\n            props.selection.cancelSelection();\n          }}\n        />\n      </Show>\n      <Show when={props.pinned && !props.albumId && !props.selection.cantPin()}>\n        <ButtonTsx\n          icon=\"pin\"\n          class=\"search-super-selection-pintotop btn-icon\"\n          onClick={() => props.selection.onPinStoriesToTopClick(undefined, true)}\n        />\n      </Show>\n      <Show when={!props.selection.cantPin()}>\n        <ButtonTsx\n          icon={props.selection.isStoriesArchive ? 'unarchive' : 'archive'}\n          class=\"search-super-selection-pin btn-icon\"\n          onClick={() => props.selection.onPinStoriesClick(undefined, props.selection.isStoriesArchive)}\n        />\n      </Show>\n      <Show when={!props.selection.cantDelete()}>\n        <ButtonTsx\n          icon=\"delete\"\n          class=\"search-super-selection-delete btn-icon danger\"\n          onClick={() => props.selection.onDeleteStoriesClick()}\n        />\n      </Show>\n    </div>\n  );\n\n  if(props.mount) {\n    createEffect(() => {\n      const selecting = props.selection.selecting();\n      props.mount.classList.toggle('is-selecting', selecting);\n      props.mount.classList.toggle('backwards', !selecting);\n    });\n    return <Portal mount={props.mount}>{content}</Portal>;\n  }\n\n  return (\n    <div\n      class=\"search-super-tabs-scrollable menu-horizontal-scrollable sticky is-single\"\n      classList={{'is-selecting': props.selection.selecting(), 'backwards': !props.selection.selecting()}}\n    >\n      {content}\n    </div>\n  );\n}\n\nexport function profileStoriesButtonMenu(props: {\n  peerId: PeerId,\n  slider: SidebarSlider,\n  verify: () => boolean,\n  isArchive?: boolean,\n  onAlbumCreated?: (albumId: number) => void,\n  canEdit?: () => boolean | Promise<boolean>,\n}): ButtonMenuItemOptionsVerifiable[] {\n  return [{\n    icon: 'archive',\n    text: 'MyStories.ShowArchive',\n    onClick: () => {\n      props.slider.createTab(AppMyStoriesTab).open({\n        ...AppMyStoriesTab.getInitArgs(),\n        isArchive: true,\n        chatId: props.peerId.isAnyChat() ? props.peerId.toChatId() : undefined\n      });\n    },\n    verify: () => Promise.resolve(props.canEdit?.() ?? true).then((canEdit) => (\n      props.verify() &&\n      !props.isArchive &&\n      canEdit\n    ))\n  }, {\n    icon: 'folder',\n    text: 'Stories.Albums.CreateAlbum',\n    onClick: async() => {\n      const albumId = await openCreateAlbumPopup(props.peerId);\n      if(albumId !== undefined) props.onAlbumCreated?.(albumId);\n    },\n    verify: () => Promise.resolve(props.canEdit?.() ?? true).then((canEdit) => (\n      props.verify() &&\n      !props.isArchive &&\n      canEdit\n    ))\n  }];\n}\n\nexport function StoriesProfileList(props: {\n  class?: string,\n  peerId: PeerId\n  pinned?: boolean\n  archive?: boolean\n  initialAlbumId?: number\n  scrollable: Scrollable\n  listenerSetter: ListenerSetter\n  withSelection?: boolean\n  forPicker?: boolean\n  selectionMount?: HTMLElement\n  onCountChange?: (count: number) => void\n  onReady?: () => void\n  onLoad?: (loaded: boolean) => void\n}) {\n  const contextValue = createStoriesStore({\n    peerId: props.peerId,\n    pinned: props.pinned,\n    archive: props.archive,\n    initialAlbumId: props.initialAlbumId,\n    manualLoad: true,\n    onLoad: props.onLoad\n  });\n  const [state, actions] = contextValue;\n\n  createEffect(() => {\n    const count = state.peer?.count ?? 0;\n    if(state.albumId === undefined) {\n      props.onCountChange?.(count);\n    }\n  });\n\n  const selection = props.withSelection ? new StoriesSelection({\n    container: props.scrollable.container,\n    managers: rootScope.managers,\n    listenerSetter: props.listenerSetter,\n    isArchive: props.archive,\n    chatId: props.peerId.isAnyChat() ? props.peerId.toChatId() : undefined,\n    forPicker: props.forPicker\n  }) : undefined;\n\n  let setAlbumAnimated!: (albumId: number | undefined) => void;\n  let containerRef!: HTMLDivElement;\n\n  const render = (\n    <StoriesContext.Provider value={contextValue}>\n      <div ref={containerRef} class=\"search-super-content-container search-super-content-stories\">\n        {props.pinned && !props.forPicker && (\n          <StoriesAlbums\n            selection={selection}\n            onAlbumChange={(id) => setAlbumAnimated?.(id)}\n            peerId={props.peerId}\n          />\n        )}\n        <StoriesGrid\n          scrollable={props.scrollable}\n          onReady={() => {\n            new StoriesContextMenu(\n              containerRef,\n              selection,\n              props.listenerSetter,\n              state\n            );\n\n            if(selection) {\n              attachClickEvent(containerRef, (e) => {\n                if(selection.isSelecting) {\n                  const item = findUpClassName(e.target, 'search-super-item');\n                  if(!item) return;\n                  cancelClickOrNextIfNotClick(e);\n                  selection.toggleByElement(item);\n                }\n              }, {capture: true, passive: false, listenerSetter: props.listenerSetter});\n            }\n            props.onReady?.();\n          }}\n          peerId={props.peerId}\n          selection={selection}\n          pinned={props.pinned}\n          archive={props.archive}\n          onSetAlbumAnimated={(fn) => setAlbumAnimated = fn}\n        />\n        {selection && !props.forPicker && (\n          <StoriesSelectionToolbar\n            selection={selection}\n            albumId={state.albumId}\n            peerId={props.peerId}\n            pinned={props.pinned}\n            mount={props.selectionMount}\n          />\n        )}\n      </div>\n    </StoriesContext.Provider>\n  );\n\n  return {\n    render,\n    state,\n    actions,\n    selection,\n    setAlbum: (albumId: number | undefined, skipAnimation = false) => {\n      if(!skipAnimation) {\n        setAlbumAnimated(albumId);\n        return;\n      }\n      actions.setAlbumId(albumId);\n    }\n  }\n}\n","import CheckboxField from '@components/checkboxField';\n\nexport default function createButtonMenuCheckboxFilters<T extends string>({\n  filterGroups,\n  getState,\n  onChange\n}: {\n  filterGroups: readonly (readonly T[])[],\n  getState: () => Record<T, boolean> | undefined,\n  onChange: (changes: Partial<Record<T, boolean>>) => void\n}) {\n  const filters = filterGroups.flat();\n  const checkboxFields = Object.fromEntries(filters.map((filter) => [\n    filter,\n    new CheckboxField({checked: true})\n  ])) as Record<T, CheckboxField>;\n\n  const toggleFilter = (filter: T) => {\n    const state = getState();\n    if(!state) {\n      return;\n    }\n\n    const changes = {\n      [filter]: !state[filter]\n    } as Partial<Record<T, boolean>>;\n    const nextState = {...state, ...changes};\n\n    for(const group of filterGroups) {\n      if(group.some((filter) => nextState[filter])) {\n        continue;\n      }\n\n      for(const groupFilter of group) {\n        if(groupFilter !== filter) {\n          changes[groupFilter] = true;\n          checkboxFields[groupFilter].checked = true;\n        }\n      }\n    }\n\n    onChange(changes);\n  };\n\n  return {\n    checkboxFields,\n    toggleFilter\n  };\n}\n","import {createEffect, createSignal, Match, on, Switch} from 'solid-js';\nimport PopupElement from '.';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport rootScope from '@lib/rootScope';\n\nimport styles from '@components/popups/chooseGiftPopup.module.scss';\nimport {createProfileGiftsStore} from '@components/stargifts/profileStore';\nimport {StarGiftsGrid} from '@components/stargifts/stargiftsGrid';\nimport Scrollable from '@components/scrollable2';\nimport {unwrap} from 'solid-js/store';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport {Transition} from 'solid-transition-group';\n\nexport default class PopupChooseGift extends PopupElement<{\n  finish: (result: {selected: MyStarGift[], deselected: MyStarGift[]} | null) => void\n}> {\n  private peerId: PeerId;\n  private selectedCollectionId?: number;\n\n  private finished = false;\n  private selected: () => MyStarGift[];\n  private deselected: () => MyStarGift[];\n\n  constructor(options: {\n    peerId: PeerId,\n    selectedCollectionId?: number\n  }) {\n    super(styles.popup, {\n      overlayClosable: true,\n      closable: true,\n      title: 'StarGiftChoose',\n      body: true,\n      buttons: [\n        {\n          langKey: 'Confirm',\n          callback: () => {\n            this.dispatchEvent('finish', {selected: this.selected(), deselected: this.deselected()});\n          }\n        },\n        {\n          langKey: 'Cancel',\n          callback: () => {\n            this.dispatchEvent('finish', null);\n          }\n        }\n      ]\n    });\n\n    this.addEventListener('close', () => {\n      if(!this.finished) {\n        this.dispatchEvent('finish', null);\n      }\n    });\n\n    safeAssign(this, options);\n\n    this.construct()\n  }\n\n  protected async construct() {\n    this.appendSolidBody(() => this._construct());\n  }\n\n  protected _construct() {\n    const [store, actions] = createProfileGiftsStore({peerId: this.peerId});\n    const [selected, setSelected] = createSignal<MyStarGift[]>([]);\n    const [deselected, setDeselected] = createSignal<MyStarGift[]>([]);\n    this.selected = selected;\n    this.deselected = deselected;\n    actions.loadNext();\n\n    const isGiftSelected = (gift: MyStarGift) => {\n      if(this.selectedCollectionId && gift.saved.collection_id?.includes(this.selectedCollectionId)) {\n        return !deselected().includes(gift);\n      }\n      return selected().includes(gift);\n    }\n\n    let scrollableRef!: HTMLDivElement;\n    return (\n      <Transition name=\"fade\" mode=\"outin\">\n        <Switch>\n          <Match when={store.loading && store.items.length === 0}>\n            <PreloaderTsx />\n          </Match>\n          <Match when={store.items.length === 0}>\n            <div class={styles.empty}>\n              <I18nTsx key=\"StarGiftCollectionsEmptyOther\" />\n            </div>\n          </Match>\n          <Match when={true}>\n            <Scrollable ref={scrollableRef} onScrolledBottom={actions.loadNext}>\n              <StarGiftsGrid\n                class={styles.grid}\n                items={unwrap(store.items)}\n                view=\"profile\"\n                autoplay={false}\n                scrollParent={scrollableRef}\n                selected={isGiftSelected}\n                onClick={(clickedItem) => {\n                  if(this.selectedCollectionId && clickedItem.saved.collection_id?.includes(this.selectedCollectionId)) {\n                    const idx = deselected().indexOf(clickedItem);\n                    if(idx !== -1) {\n                      setDeselected(deselected().filter((it, i) => i !== idx));\n                    } else {\n                      setDeselected([...deselected(), clickedItem]);\n                    }\n                  } else {\n                    const idx = selected().indexOf(clickedItem);\n                    if(idx !== -1) {\n                      setSelected(selected().filter((it, i) => i !== idx));\n                    } else {\n                      setSelected([...selected(), clickedItem]);\n                    }\n                  }\n                }}\n              />\n            </Scrollable>\n          </Match>\n        </Switch>\n      </Transition>\n    )\n  }\n}\n","import {createMemo, createSignal, For, Match, onMount, Show, Switch, untrack} from 'solid-js';\nimport rootScope from '@lib/rootScope';\nimport {PreloaderTsx} from '@components/putPreloader';\nimport PopupElement from '@components/popups';\nimport PopupStarGiftInfo from '@components/popups/starGiftInfo';\nimport {StarGiftsGrid} from '@components/stargifts/stargiftsGrid';\nimport {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport createButtonMenuCheckboxFilters from '@components/buttonMenuCheckboxFilters';\nimport {AnimationList} from '@helpers/solid/animationList';\nimport {ChipTab, ChipTabs} from '@components/chipTabs';\nimport {I18nTsx} from '@helpers/solid/i18n';\nimport classNames from '@helpers/string/classNames';\nimport {StickerTsx} from '@components/wrappers/sticker';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport {IconTsx} from '@components/iconTsx';\nimport InputField from '@components/inputField';\nimport confirmationPopup, {PopupConfirmationOptions} from '@components/confirmationPopup';\nimport Button from '@components/buttonTsx';\n\nimport styles from '@components/stargifts/profileList.module.scss';\nimport {ALL_COLLECTIONS_ID, createProfileGiftsStore, StarGiftsProfileActions, StarGiftsProfileStore} from '@components/stargifts/profileStore';\nimport {Chat, StarGiftCollection, User} from '@layer';\nimport {unwrap} from 'solid-js/store';\nimport PopupChooseGift from '@components/popups/chooseGiftPopup';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport {copyTextToClipboard} from '@helpers/clipboard';\nimport {toastNew} from '@components/toast';\n\nasync function openCreateCollectionPopup({actions, peerId}: {\n  actions: StarGiftsProfileActions\n  peerId: PeerId\n}): Promise<void> {\n  const buttonOptions: PopupConfirmationOptions['button'] = {\n    langKey: 'Create'\n  };\n\n  const inputField = new InputField({\n    maxLength: 12,\n    placeholder: 'StarGiftCollectionsAddPlaceholder',\n    required: true\n  });\n\n  try {\n    await confirmationPopup({\n      titleLangKey: 'StarGiftCollectionsAddTitle',\n      descriptionLangKey: 'StarGiftCollectionsAddText',\n      inputField,\n      button: buttonOptions\n    })\n  } catch(err) {\n    return\n  }\n\n  const collection = await rootScope.managers.apiManager.invokeApi('payments.createStarGiftCollection', {\n    title: inputField.value,\n    peer: await rootScope.managers.appPeersManager.getInputPeerById(peerId),\n    stargift: []\n  })\n\n  actions.updateCollection(collection)\n}\n\nasync function openRenameCollectionPopup({actions, collection, peerId}: {\n  actions: StarGiftsProfileActions\n  collection: StarGiftCollection\n  peerId: PeerId\n}): Promise<void> {\n  const buttonOptions: PopupConfirmationOptions['button'] = {\n    langKey: 'Edit'\n  };\n\n  const inputField = new InputField({\n    maxLength: 12,\n    placeholder: 'StarGiftCollectionsAddPlaceholder',\n    required: true\n  });\n  inputField.value = collection.title\n\n  try {\n    await confirmationPopup({\n      titleLangKey: 'StarGiftCollectionsRename',\n      inputField,\n      button: buttonOptions\n    })\n  } catch(err) {\n    return\n  }\n\n  if(inputField.value === collection.title) return\n\n  const newCollection = await rootScope.managers.appGiftsManager.updateCollection({\n    peerId,\n    collectionId: collection.collection_id,\n    title: inputField.value\n  })\n\n  actions.updateCollection(newCollection, {switch: false, reload: false})\n}\n\nasync function openAddGiftsPopup({actions, collectionId, peerId}: {\n  actions: StarGiftsProfileActions\n  collectionId: number\n  peerId: PeerId\n}): Promise<void> {\n  const popup = PopupElement.createPopup(PopupChooseGift, {\n    peerId,\n    selectedCollectionId: collectionId\n  })\n  popup.show()\n\n  const result = await new Promise<{selected: MyStarGift[], deselected: MyStarGift[]} | null>((resolve) => {\n    popup.addEventListener('finish', resolve);\n  })\n\n  if(!result) return\n\n  const collection = await rootScope.managers.appGiftsManager.updateCollection({\n    peerId,\n    collectionId,\n    add: result.selected.map((it) => it.input),\n    delete: result.deselected.map((it) => it.input)\n  })\n\n  actions.updateCollection(collection)\n}\n\nexport function profileStarGiftsButtonMenu(props: {\n  store?: StarGiftsProfileStore\n  actions?: StarGiftsProfileActions\n  verify: () => boolean\n  peerId: PeerId\n}): ButtonMenuItemOptionsVerifiable[] {\n  const FILTER_GROUPS = [['unlimited', 'limited', 'upgradable', 'unique'], ['displayed', 'hidden']] as const\n  type ToggleableFilter = typeof FILTER_GROUPS[number][number]\n  const {checkboxFields, toggleFilter} = createButtonMenuCheckboxFilters<ToggleableFilter>({\n    filterGroups: FILTER_GROUPS,\n    getState: () => props.store,\n    onChange: (changes) => props.actions.setFilters(changes)\n  });\n  return [\n    {\n      icon: 'sort_date',\n      text: 'StarGiftSortByDate',\n      onClick: () => props.actions.setFilters({sort: 'date'}),\n      verify: () => props.verify() && props.store?.sort === 'value'\n    },\n    {\n      icon: 'sort_price',\n      text: 'StarGiftSortByValue',\n      onClick: () => props.actions.setFilters({sort: 'value'}),\n      verify: () => props.verify() && props.store?.sort === 'date'\n    },\n    {\n      icon: 'folder',\n      text: 'StarGiftCollectionsAdd',\n      onClick: () => openCreateCollectionPopup({actions: props.actions, peerId: props.peerId}),\n      verify: () => props.verify() && props.store != null && props.store.canManageGifts\n    },\n    {\n      checkboxField: checkboxFields.unlimited,\n      text: 'StarGiftShowUnlimited',\n      separator: true,\n      onClick: () => toggleFilter('unlimited'),\n      verify: () => props.verify() && props.store != null\n    },\n    {\n      checkboxField: checkboxFields.limited,\n      text: 'StarGiftShowLimited',\n      onClick: () => toggleFilter('limited'),\n      verify: () => props.verify() && props.store != null\n    },\n    {\n      checkboxField: checkboxFields.upgradable,\n      text: 'StarGiftShowUpgradable',\n      onClick: () => toggleFilter('upgradable'),\n      verify: () => props.verify() && props.store != null\n    },\n    {\n      checkboxField: checkboxFields.unique,\n      text: 'StarGiftShowUnique',\n      onClick: () => toggleFilter('unique'),\n      verify: () => props.verify() && props.store != null\n    },\n    {\n      checkboxField: checkboxFields.displayed,\n      text: 'StarGiftShowDisplayed',\n      separator: true,\n      onClick: () => toggleFilter('displayed'),\n      verify: () => props.verify() && props.store != null && props.store.canManageGifts\n    },\n    {\n      checkboxField: checkboxFields.hidden,\n      text: 'StarGiftShowHidden',\n      onClick: () => toggleFilter('hidden'),\n      verify: () => props.verify() && props.store != null && props.store.canManageGifts\n    }\n  ]\n}\n\nconst ADD_COLLECTION_ID = -2\n\nexport function StarGiftsProfileTab(props: {\n  peerId: PeerId\n  scrollParent?: HTMLElement\n  onCountChange?: (count: number) => void\n}) {\n  const [store, actions] = createProfileGiftsStore({\n    peerId: props.peerId,\n    onCountChange: props.onCountChange\n  });\n\n  onMount(() => actions.loadNext())\n\n  const [direction, setDirection] = createSignal(0)\n  let scrollDiff = 0\n  let wrapperRef!: HTMLDivElement\n\n  const scrollPositions = new Map<number, number>()\n\n  const getScrollBase = () => {\n    const searchSuper = wrapperRef?.closest('.search-super') as HTMLElement\n    if(!searchSuper) return 0\n    return searchSuper.offsetTop === 0 ? 0 : searchSuper.offsetTop - 56\n  }\n\n  const slideKeyframes = (_element: Element, removed: boolean): Keyframe[] => {\n    const dir = direction()\n    const yOffset = scrollDiff ? ` translateY(${scrollDiff}px)` : ''\n    if(removed) {\n      // AnimationList reverses these for exit; Y offset compensates scroll change\n      return [\n        {transform: `translateX(${-dir * 100}%)${yOffset}`},\n        {transform: `translateX(0)${yOffset}`}\n      ]\n    }\n    return [{transform: `translateX(${dir * 100}%)`}, {transform: 'translateX(0)'}]\n  }\n\n  const setCollection = (newId: number) => {\n    if(newId === store.chosenCollection) return\n\n    const collections = store.collections\n    const oldIndex = store.chosenCollection === ALL_COLLECTIONS_ID ? -1 :\n      (collections?.findIndex((c) => c.collection_id === store.chosenCollection) ?? -1)\n    const newIndex = newId === ALL_COLLECTIONS_ID ? -1 :\n      (collections?.findIndex((c) => c.collection_id === newId) ?? -1)\n    const dir = newIndex > oldIndex ? 1 : newIndex < oldIndex ? -1 : 0\n\n    const scrollable = props.scrollParent\n    const scrollBase = getScrollBase()\n    const oldScrollTop = scrollable?.scrollTop ?? 0\n    const oldScroll = oldScrollTop - scrollBase\n    if(scrollable && oldScroll >= 0) {\n      scrollPositions.set(store.chosenCollection, Math.max(0, oldScroll))\n    }\n\n    if(dir) setDirection(dir)\n    actions.setFilters({chosenCollection: newId})\n\n    const newScroll = scrollPositions.get(newId) ?? 0\n    const targetScrollTop = scrollBase + newScroll\n    if(scrollable && oldScroll >= 0) {\n      scrollDiff = targetScrollTop - oldScrollTop\n      scrollable.scrollTop = targetScrollTop\n    } else {\n      scrollDiff = 0\n    }\n  }\n\n  const collectionContent = createMemo(() => {\n    store.chosenCollection\n    return untrack(() => (\n      <div class={styles.collectionContent}>\n        <Switch>\n          <Match when={store.loading && store.items.length === 0}>\n            <PreloaderTsx />\n          </Match>\n          <Match when={store.items.length === 0 && store.chosenCollection !== ALL_COLLECTIONS_ID && store.canManageGifts}>\n            <div class={/* @once */ styles.empty}>\n              <I18nTsx class={/* @once */ styles.emptyTitle} key=\"StarGiftCollectionsEmptyTitle\" />\n              <I18nTsx class={/* @once */ styles.emptySubtitle} key=\"StarGiftCollectionsEmptySubtitle\" />\n              <Button\n                class=\"btn-primary btn-color-primary btn-control\"\n                text=\"StarGiftCollectionsAddGifts\"\n                onClick={() => openAddGiftsPopup({\n                  actions,\n                  collectionId: store.chosenCollection,\n                  peerId: props.peerId\n                })}\n              />\n            </div>\n          </Match>\n          <Match when={store.items.length === 0}>\n            <div class={/* @once */ styles.empty}>\n              <I18nTsx class={/* @once */ styles.emptySubtitle} key=\"StarGiftCollectionsEmptyOther\" />\n            </div>\n          </Match>\n          <Match when={true}>\n            <StarGiftsGrid\n              class={/* @once */ styles.grid}\n              items={unwrap(store.items)}\n              view='profile'\n              profilePeerId={props.peerId}\n              canManageGifts={store.canManageGifts}\n              profileCollections={store.collections ? unwrap(store.collections) : undefined}\n              scrollParent={props.scrollParent}\n              autoplay={false}\n              onClick={(item) => {\n                PopupElement.createPopup(PopupStarGiftInfo, {gift: item});\n              }}\n            />\n          </Match>\n        </Switch>\n      </div>\n    ))\n  })\n\n  const render = (\n    <div class={classNames(styles.tab, store.hasCollections && styles.hasCollections)}>\n      <Show when={store.hasCollections}>\n        <ChipTabs\n          class={/* @once */ styles.collections}\n          value={store.chosenCollection.toString()}\n          needIntersectionObserver\n          onChange={(id) => {\n            if(id === ADD_COLLECTION_ID.toString()) {\n              openCreateCollectionPopup({actions, peerId: props.peerId})\n              return false\n            }\n            setCollection(Number(id))\n          }}\n          contextMenuButtons={(id_) => {\n            const id = Number(id_)\n            if(id === ALL_COLLECTIONS_ID || id === ADD_COLLECTION_ID) return []\n\n\n            const buttons: ButtonMenuItemOptionsVerifiable[] = [\n              {\n                icon: 'link',\n                text: 'CopyLink',\n                onClick: async() => {\n                  const username = await rootScope.managers.appPeersManager.getPeerUsername(props.peerId)\n                  copyTextToClipboard(`https://t.me/${username}/c/${id}`)\n                  toastNew({langPackKey: 'LinkCopied'})\n                },\n                verify: async() => {\n                  const username = await rootScope.managers.appPeersManager.getPeerUsername(props.peerId)\n                  return !!username\n                }\n              }\n            ]\n\n            if(store.canManageGifts) {\n              buttons.push(\n                {\n                  icon: 'add',\n                  text: 'StarGiftCollectionsAddGifts',\n                  onClick: () => openAddGiftsPopup({actions, collectionId: id, peerId: props.peerId})\n                },\n                {\n                  icon: 'edit',\n                  text: 'StarGiftCollectionsRename',\n                  onClick: () => {\n                    const collection = store.collections.find((it) => it.collection_id === id)\n                    if(!collection) return\n                    openRenameCollectionPopup({actions, collection, peerId: props.peerId})\n                  }\n                },\n                {\n                  icon: 'delete',\n                  text: 'Delete',\n                  danger: true,\n                  onClick: async() => {\n                    const collection = store.collections.find((it) => it.collection_id === id)\n                    if(!collection) return\n                    await confirmationPopup({\n                      titleLangKey: 'StarGiftCollectionsDeleteTitle',\n                      descriptionLangKey: 'StarGiftCollectionsDeleteAreYouSure',\n                      descriptionLangArgs: [wrapEmojiText(collection.title)],\n                      button: {\n                        langKey: 'Delete',\n                        isDanger: true\n                      }\n                    })\n                    rootScope.managers.apiManager.invokeApi('payments.deleteStarGiftCollection', {\n                      collection_id: id,\n                      peer: await rootScope.managers.appPeersManager.getInputPeerById(props.peerId)\n                    })\n                    actions.deleteCollection(id)\n                  }\n                }\n              )\n            }\n\n            return buttons\n          }}\n          view=\"surface\"\n          center\n        >\n          <ChipTab value={ALL_COLLECTIONS_ID.toString()}>\n            <I18nTsx key=\"StarGiftCollectionsAll\" />\n          </ChipTab>\n          <For each={store.collections}>\n            {(collection) => (\n              <ChipTab value={collection.collection_id.toString()}>\n                {collection.icon && (\n                  <StickerTsx\n                    sticker={unwrap(collection.icon) as MyDocument}\n                    width={24}\n                    height={24}\n                    autoStyle\n                  />\n                )}\n                {wrapEmojiText(collection.title)}\n              </ChipTab>\n            )}\n          </For>\n          <Show when={store.canManageGifts}>\n            <ChipTab value={ADD_COLLECTION_ID.toString()} class={/* @once */ styles.addCollection}>\n              <IconTsx icon=\"add\" />\n              <I18nTsx key=\"StarGiftCollectionsAdd\" />\n            </ChipTab>\n          </Show>\n        </ChipTabs>\n      </Show>\n\n      <div ref={wrapperRef} class={styles.contentWrapper}>\n        <AnimationList\n          animationOptions={{duration: 250, easing: 'cubic-bezier(.4, 0, .2, 1)'}}\n          keyframes={slideKeyframes}\n          mode=\"replacement\"\n        >\n          {collectionContent()}\n        </AnimationList>\n      </div>\n    </div>\n  );\n\n  return {render, store, actions, setCollection};\n}\n","import appDialogsManager from '@lib/appDialogsManager';\nimport {SavedDialog} from '@appManagers/appMessagesManager';\nimport {isSavedDialog} from '@appManagers/utils/dialogs/isDialog';\nimport rootScope from '@lib/rootScope';\nimport {AutonomousDialogListBase, BaseConstructorArgs} from '@components/autonomousDialogList/base';\n\n\nexport class AutonomousSavedDialogList extends AutonomousDialogListBase<SavedDialog> {\n  public onAnyUpdate: () => void;\n\n  constructor({appDialogsManager}: BaseConstructorArgs) {\n    super({appDialogsManager});\n\n    // this.listenerSetter.add(rootScope)('dialog_flush', ({dialog}) => {\n    //   if(!dialog) {\n    //     return;\n    //   }\n\n    //   this.updateDialog(dialog);\n    // });\n\n    this.listenerSetter.add(rootScope)('dialogs_multiupdate', (dialogs) => {\n      let hasAnyUpdate = false;\n      for(const [peerId, {saved}] of dialogs) {\n        saved?.forEach((dialog) => {\n          hasAnyUpdate = true;\n          this.updateDialog(dialog as SavedDialog);\n        });\n      }\n\n      if(hasAnyUpdate) {\n        this.onAnyUpdate?.();\n      }\n    });\n\n    this.listenerSetter.add(rootScope)('dialog_drop', (dialog) => {\n      if(!isSavedDialog(dialog)) {\n        return;\n      }\n\n      this.deleteDialogByKey(this.getDialogKey(dialog));\n      this.onAnyUpdate?.();\n    });\n  }\n\n  public getRectFromForPlaceholder() {\n    return appDialogsManager.chatsContainer;\n  }\n\n  protected getFilterId() {\n    return rootScope.myId;\n  }\n\n  public getDialogKey(dialog: SavedDialog) {\n    return dialog.savedPeerId;\n  }\n\n  public getDialogKeyFromElement(element: HTMLElement) {\n    return +element.dataset.peerId;\n  }\n\n  public getDialogFromElement(element: HTMLElement) {\n    return rootScope.managers.dialogsStorage.getAnyDialog(element.dataset.peerId.toPeerId(), element.dataset.threadId.toPeerId()) as Promise<SavedDialog>;\n  }\n}\n","import {batch, createEffect, createMemo, createSignal, Match, on, onMount, Show, Switch} from 'solid-js';\nimport {wrapSolidComponent} from '../../helpers/solid/wrapSolidComponent';\nimport {Middleware} from '../../helpers/middleware';\n\nimport styles from './globalPostsSearch.module.scss';\nimport {I18nTsx} from '../../helpers/solid/i18n';\nimport rootScope from '../../lib/rootScope';\nimport Section from '../section';\nimport {Message, SearchPostsFlood} from '../../layer';\nimport Button from '../buttonTsx';\nimport {i18n} from '../../lib/langPack';\nimport PopupPremium from '../popups/premium';\nimport classNames from '../../helpers/string/classNames';\nimport {IconTsx} from '../iconTsx';\nimport wrapEmojiText from '../../lib/richTextProcessor/wrapEmojiText';\nimport {NULL_PEER_ID, STARS_CURRENCY} from '../../lib/appManagers/constants';\nimport appDialogsManager from '../../lib/appDialogsManager';\nimport createMiddleware from '../../helpers/solid/createMiddleware';\nimport {PreloaderTsx} from '../putPreloader';\nimport paymentsWrapCurrencyAmount from '../../helpers/paymentsWrapCurrencyAmount';\nimport {createCurrentTime} from '../../helpers/solid/createCurrentTime';\nimport tsNow from '../../helpers/tsNow';\nimport {wrapLeftDuration} from '../wrappers/wrapDuration';\nimport usePremium from '../../stores/premium';\nimport {toastNew} from '../toast';\n\nconst renderHistoryResult = (options: {\n  messages: (Message.message | Message.messageService)[]\n  query: string\n  middleware: Middleware\n}) => {\n  const promises = options.messages.map(async(message) => {\n    const loadPromises: Promise<any>[] = [];\n    const {dom} = appDialogsManager.addDialogAndSetLastMessage({\n      peerId: message.peerId,\n      container: false,\n      avatarSize: 'bigger',\n      message,\n      query: options.query,\n      wrapOptions: {\n        middleware: options.middleware\n      },\n      loadPromises,\n      autonomous: true\n    });\n\n    await Promise.all(loadPromises);\n    return dom.containerEl;\n  });\n\n  return Promise.all(promises);\n};\n\nexport function GlobalPostsSearch(props: {\n  query: string\n  loadMoreRef?: (fn: () => void) => void\n}) {\n  const [flood, setFlood] = createSignal<SearchPostsFlood | null>(null)\n  const [results, setResults] = createSignal<HTMLElement[]>([])\n  const [placeholder, setPlaceholder] = createSignal(true)\n  const [loading, setLoading] = createSignal(false)\n  const [canShowButtonAfterEmpty, setCanShowButtonAfterEmpty] = createSignal(false)\n  const middleware = createMiddleware()\n  const isPremium = usePremium()\n\n  let lastMessage: Message.message | Message.messageService | null = null\n  let nextRate = 0\n  const loadMore = (refetch = false, allowPaid = false) => {\n    if(loading() && !refetch) return\n    if(!props.query) return\n    setLoading(true)\n\n    const offsetId = lastMessage?.mid || 0\n    const offsetPeerId = lastMessage?.peerId || NULL_PEER_ID\n\n    rootScope.managers.appMessagesManager.getHistory({\n      peerId: NULL_PEER_ID,\n      inputFilter: {_: 'inputMessagesFilterEmpty'},\n      offsetId,\n      offsetPeerId,\n      nextRate,\n      limit: 30,\n      isPublicPosts: true,\n      query: props.query,\n      allowStars: allowPaid ? flood()?.stars_amount : 0\n    }).then((res) => {\n      if(allowPaid && !res.flood.pFlags.query_is_free) {\n        toastNew({\n          langPackKey: 'PostsSearch.StarsSpent',\n          langPackArguments: [\n            paymentsWrapCurrencyAmount(res.flood.stars_amount, STARS_CURRENCY, false, false, true)\n          ]\n        })\n      }\n\n      if(!res.messages) {\n        setLoading(false);\n        return;\n      }\n      nextRate = res.nextRate;\n      lastMessage = res.messages[res.messages.length - 1];\n      if(res.flood) setFlood(res.flood);\n      renderHistoryResult({\n        messages: res.messages,\n        query: props.query,\n        middleware: middleware.get()\n      }).then((doms) => {\n        batch(() => {\n          setPlaceholder(false)\n          setResults([...results(), ...doms]);\n          setLoading(false);\n        })\n      }).catch((err) => {\n        console.error(err);\n        setLoading(false);\n      })\n    }).catch((err: ApiError) => {\n      const m = (err.type as string ?? '').match(/^FLOOD_WAIT_(\\d+)_OR_STARS_(\\d+)$/)\n      if(m) {\n        setFlood({\n          _: 'searchPostsFlood',\n          pFlags: {},\n          remains: 0,\n          total_daily: flood()?.total_daily || 0,\n          wait_till: tsNow(true) + parseInt(m[1]),\n          stars_amount: parseInt(m[2])\n        })\n      }\n      console.error(err)\n      setLoading(false)\n    })\n  }\n  props.loadMoreRef?.(loadMore)\n\n  const loadFlood = () => {\n    const myQuery = props.query\n    rootScope.managers.apiManager.invokeApi('channels.checkSearchPostsFlood', {\n      query: myQuery\n    }).then((res) => {\n      if(myQuery !== props.query) return\n      setFlood(res)\n      setCanShowButtonAfterEmpty(true)\n      if(myQuery) {\n        setResults([])\n        setPlaceholder(true)\n        if(res.pFlags.query_is_free) {\n          loadMore(true)\n        }\n      }\n    })\n  }\n\n  createEffect(on(() => props.query, (value, prev) => {\n    // only show the button after we load flood, to avoid blinking for free queries\n    if(prev === '') setCanShowButtonAfterEmpty(false)\n    if(value === '') {\n      setResults([])\n      setPlaceholder(true)\n    }\n    lastMessage = null\n    nextRate = 0\n    loadFlood()\n  }))\n\n  const now = createCurrentTime({\n    fn: () => tsNow(true),\n    updateInterval: 1000\n  })\n  const remainingUntilReset = createMemo(() => {\n    const flood$ = flood()\n    if(!flood$?.wait_till) return null\n\n    return wrapLeftDuration(flood$.wait_till - now())\n  })\n\n  const title = () => {\n    if(!isPremium()) {\n      return 'PostsSearch.Title'\n    }\n    if(flood()?.remains === 0) {\n      return 'PostsSearch.TitleLimited'\n    }\n    return 'PostsSearch.Title'\n  }\n\n  const description = () => {\n    if(!isPremium()) {\n      return <I18nTsx key=\"PostsSearch.Description\" class={styles.description} />\n    }\n    if(flood()?.remains === 0) {\n      return (\n        <I18nTsx\n          key=\"PostsSearch.DescriptionLimited\"\n          args={[String(flood().total_daily)]}\n          class={styles.description}\n        />\n      )\n    }\n    return <I18nTsx key=\"PostsSearch.Description\" class={styles.description} />\n  }\n\n  const button = () => {\n    if(!isPremium()) {\n      return (\n        <Button\n          class={classNames('btn-primary btn-color-primary', styles.button)}\n          onClick={() => PopupPremium.show()}\n        >\n          {i18n('PostsSearch.SubscribeToPremium')}\n        </Button>\n      )\n    }\n\n    if(!props.query || !canShowButtonAfterEmpty()) return null\n\n    if(remainingUntilReset()) {\n      return (\n        <Button\n          class={classNames('btn-primary btn-color-primary', styles.button, styles.buttonPaidSearch)}\n          onClick={() => loadMore(true, true)}\n        >\n          <I18nTsx key=\"PostsSearch.SearchFor\" args={[paymentsWrapCurrencyAmount(flood().stars_amount, STARS_CURRENCY)]} />\n          <I18nTsx key=\"PostsSearch.FreeUnlocksIn\" args={[remainingUntilReset()]} class={styles.remainingUntilReset} />\n        </Button>\n      )\n    }\n\n    return (\n      <Button\n        class={classNames('btn-primary btn-color-primary', styles.button)}\n        onClick={() => loadMore(true)}\n      >\n        <IconTsx icon=\"search\" />\n        {i18n('Search')}\n        <span class={styles.searchQuery}>\n          {wrapEmojiText(props.query)}\n        </span>\n        <IconTsx icon=\"next\" />\n      </Button>\n    )\n  }\n\n  const footer = () => {\n    if(!isPremium()) {\n      return (\n        <I18nTsx key=\"PostsSearch.NeedPremium\" class={styles.footer} />\n      )\n    }\n    if(!flood() || flood().remains === 0) return null\n\n    return (\n      <I18nTsx\n        key=\"PostsSearch.FreeSearches\"\n        args={[String(flood().remains)]}\n        class={styles.footer}\n      />\n    )\n  }\n\n  return (\n    <div>\n      <Switch>\n        <Match when={results().length}>\n          <Section noShadow noDelimiter>\n            <div\n              class={styles.results}\n              ref={(el) => {\n                appDialogsManager.setListClickListener({\n                  list: el,\n                  autonomous: true\n                })\n              }}\n            >\n              {results()}\n            </div>\n          </Section>\n        </Match>\n        <Match when={loading() || !flood()}>\n          <PreloaderTsx />\n        </Match>\n        <Match when={placeholder()}>\n          <div class={styles.placeholder}>\n            <I18nTsx key={title()} class={styles.title} />\n            {description()}\n            {button()}\n            {footer()}\n          </div>\n        </Match>\n        <Match when={true}>\n          <div class={styles.placeholder}>\n            {i18n('Chat.Search.NothingFound')}\n          </div>\n        </Match>\n      </Switch>\n    </div>\n  )\n}\n\nexport function wrapGlobalPostsSearch(options: {\n  middleware: Middleware\n  query: string\n}) {\n  const [query, setQuery] = createSignal(options.query);\n\n  let loadMore!: () => void\n  const dom = wrapSolidComponent(() => (\n    <GlobalPostsSearch\n      query={query()}\n      loadMoreRef={fn => loadMore = fn}\n    />\n  ), options.middleware)\n\n  return {\n    dom,\n    loadMore,\n    setQuery\n  }\n}\n","import {ProfileTab} from '@layer';\n\nexport type ProfileTabMediaType = 'stories' | 'gifts' | 'media' | 'files' |\n  'music' | 'voice' | 'links' | 'gifs';\n\nconst PROFILE_TAB_BY_MEDIA_TYPE: Record<ProfileTabMediaType, ProfileTab> = {\n  stories: {_: 'profileTabPosts'},\n  gifts: {_: 'profileTabGifts'},\n  media: {_: 'profileTabMedia'},\n  files: {_: 'profileTabFiles'},\n  music: {_: 'profileTabMusic'},\n  voice: {_: 'profileTabVoice'},\n  links: {_: 'profileTabLinks'},\n  gifs: {_: 'profileTabGifs'}\n};\n\nconst MEDIA_TYPE_BY_PROFILE_TAB: Record<ProfileTab['_'], ProfileTabMediaType> = {\n  profileTabPosts: 'stories',\n  profileTabGifts: 'gifts',\n  profileTabMedia: 'media',\n  profileTabFiles: 'files',\n  profileTabMusic: 'music',\n  profileTabVoice: 'voice',\n  profileTabLinks: 'links',\n  profileTabGifs: 'gifs'\n};\n\nexport function getProfileTabForMediaType(type: string): ProfileTab | undefined {\n  return PROFILE_TAB_BY_MEDIA_TYPE[type as ProfileTabMediaType];\n}\n\nexport function getMediaTypeForProfileTab(tab?: ProfileTab): ProfileTabMediaType | undefined {\n  return tab ? MEDIA_TYPE_BY_PROFILE_TAB[tab._] : undefined;\n}\n\nexport function canSetMainProfileTabForMediaType(type: string, options: {\n  isSelf: boolean,\n  isSavedMessages: boolean,\n  isEditableBroadcast: boolean\n}) {\n  if(!getProfileTabForMediaType(type)) {\n    return false;\n  }\n\n  return options.isEditableBroadcast ||\n    options.isSavedMessages ||\n    (options.isSelf && (type === 'stories' || type === 'gifts'));\n}\n\nexport function orderMediaTabsByMain<T extends {type: string}>(\n  tabs: readonly T[],\n  mainType?: ProfileTabMediaType,\n  isVisible: (tab: T) => boolean = () => true\n): T[] {\n  const ordered = [...tabs];\n  const mainIndex = ordered.findIndex((tab) => tab.type === mainType && isVisible(tab));\n  if(mainIndex <= 0) {\n    return ordered;\n  }\n\n  const [mainTab] = ordered.splice(mainIndex, 1);\n  ordered.unshift(mainTab);\n  return ordered;\n}\n","export const SHARED_MEDIA_SCROLL_DATE_HIDE_TIMEOUT = 1000;\n\nconst SAME_ROW_TOLERANCE = 1;\n\nexport function supportsSharedMediaScrollDate(type: string) {\n  return type === 'media' || type === 'stories';\n}\n\nexport function findSharedMediaScrollDateItemIndex(\n  itemCount: number,\n  anchorTop: number,\n  getItemBottom: (index: number) => number\n) {\n  let left = 0;\n  let right = itemCount - 1;\n  let result = -1;\n\n  while(left <= right) {\n    const middle = (left + right) >> 1;\n    if(getItemBottom(middle) > anchorTop) {\n      result = middle;\n      right = middle - 1;\n    } else {\n      left = middle + 1;\n    }\n  }\n\n  if(result === -1) {\n    return result;\n  }\n\n  const rowBottom = getItemBottom(result);\n  while(result > 0 && Math.abs(getItemBottom(result - 1) - rowBottom) < SAME_ROW_TOLERANCE) {\n    --result;\n  }\n\n  return result;\n}\n","import createDateBubble from '@components/chat/dateBubble';\nimport {\n  findSharedMediaScrollDateItemIndex,\n  SHARED_MEDIA_SCROLL_DATE_HIDE_TIMEOUT\n} from '@components/sharedMediaScrollDate';\n\nexport default function createSharedMediaScrollDateBadge(options: {\n  mount: (element: HTMLElement) => void,\n  getAnchorTop: () => number,\n  getItems: () => ArrayLike<Element>\n}) {\n  let element: HTMLElement;\n  let timestamp: number;\n  let hideTimeout: number;\n\n  const hide = () => {\n    window.clearTimeout(hideTimeout);\n    hideTimeout = 0;\n    element?.classList.remove('is-visible');\n  };\n\n  const update = (canShow: boolean) => {\n    if(!canShow) {\n      hide();\n      return;\n    }\n\n    const items = options.getItems();\n    if(!items.length) {\n      hide();\n      return;\n    }\n\n    const anchorTop = options.getAnchorTop();\n    const bounds = new Map<number, DOMRect>();\n    const getItemBottom = (index: number) => {\n      let rect = bounds.get(index);\n      if(!rect) {\n        rect = items[index].getBoundingClientRect();\n        bounds.set(index, rect);\n      }\n\n      return rect.bottom;\n    };\n    const index = findSharedMediaScrollDateItemIndex(items.length, anchorTop, getItemBottom);\n    const nextTimestamp = index === -1 ? 0 : +(items[index] as HTMLElement).dataset.timestamp;\n    if(!nextTimestamp) {\n      hide();\n      return;\n    }\n\n    if(timestamp !== nextTimestamp) {\n      const date = new Date(nextTimestamp * 1000);\n      date.setHours(0, 0, 0, 0);\n      const nextElement = createDateBubble(nextTimestamp, date);\n\n      if(element) {\n        element.replaceChildren(...Array.from(nextElement.childNodes));\n      } else {\n        element = nextElement;\n        element.classList.add('search-super-scroll-date');\n        options.mount(element);\n      }\n\n      timestamp = nextTimestamp;\n    }\n\n    window.clearTimeout(hideTimeout);\n    element.classList.add('is-visible');\n    hideTimeout = window.setTimeout(hide, SHARED_MEDIA_SCROLL_DATE_HIDE_TIMEOUT);\n  };\n\n  const reset = () => {\n    hide();\n    timestamp = undefined;\n  };\n\n  const destroy = () => {\n    reset();\n    element?.remove();\n    element = undefined;\n  };\n\n  return {destroy, hide, reset, update};\n}\n","import type {AppMessagesManager, MyInputMessagesFilter, MyMessage, RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport appDialogsManager, {DIALOG_LIST_ELEMENT_TAG, DialogDom} from '@lib/appDialogsManager';\nimport {logger} from '@lib/logger';\nimport rootScope from '@lib/rootScope';\nimport {createSearchGroup, SearchGroup, SearchGroupType} from '@components/searchGroup';\nimport {horizontalMenu} from '@components/horizontalMenu';\nimport LazyLoadQueue from '@components/lazyLoadQueue';\nimport {putPreloader} from '@components/putPreloader';\nimport ripple from '@components/ripple';\nimport Scrollable, {ScrollableX} from '@components/scrollable';\nimport useHeavyAnimationCheck, {getHeavyAnimationPromise} from '@hooks/useHeavyAnimationCheck';\nimport I18n, {LangPackKey, i18n, join} from '@lib/langPack';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {getMiddleware, Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport {BotMenuButton, ChannelParticipant, Chat, ChatFull, ChatParticipant, ChatParticipants, Document, Message, MessageMedia, MessagesChats, MessagesFilter, Peer, Photo, StoryItem, Update, User, UserFull, WebPage} from '@layer';\nimport SortedUserList from '@components/sortedUserList';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport appSidebarRight from '@components/sidebarRight';\nimport mediaSizes from '@helpers/mediaSizes';\nimport appImManager from '@lib/appImManager';\nimport IS_TOUCH_SUPPORTED from '@environment/touchSupport';\nimport handleTabSwipe from '@helpers/dom/handleTabSwipe';\nimport windowSize from '@helpers/windowSize';\nimport {formatPhoneNumber} from '@helpers/formatPhoneNumber';\nimport {ButtonMenuItemOptions, ButtonMenuSync} from '@components/buttonMenu';\nimport showForwardPopup from '@components/popups/forward';\nimport PopupDeleteMessages from '@components/popups/deleteMessages';\nimport {renderSearchWebPageRow} from '@components/searchWebPageRow';\nimport htmlToDocumentFragment from '@helpers/dom/htmlToDocumentFragment';\nimport {SearchSelection} from '@components/chat/selection';\nimport {attachClickEvent, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport AppMediaViewer from '@components/mediaViewer';\nimport lockTouchScroll from '@helpers/dom/lockTouchScroll';\nimport copy from '@helpers/object/copy';\nimport safeAssign from '@helpers/object/safeAssign';\nimport findAndSplice from '@helpers/array/findAndSplice';\nimport {ScrollStartCallbackDimensions} from '@helpers/fastSmoothScroll';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {AppManagers} from '@lib/managers';\nimport choosePhotoSize from '@appManagers/utils/photos/choosePhotoSize';\nimport wrapWebPageDescription from '@components/wrappers/webPageDescription';\nimport wrapWebPageTitle from '@components/wrappers/webPageTitle';\nimport wrapAbbreviation from '@richTextProcessor/wrapAbbreviation';\nimport matchUrl from '@richTextProcessor/matchUrl';\nimport wrapPlainText from '@richTextProcessor/wrapPlainText';\nimport wrapRichText from '@richTextProcessor/wrapRichText';\nimport wrapSenderToPeer from '@components/wrappers/senderToPeer';\nimport wrapSentTime from '@components/wrappers/sentTime';\nimport getMediaFromMessage from '@appManagers/utils/messages/getMediaFromMessage';\nimport filterMessagesByInputFilter from '@appManagers/utils/messages/filterMessagesByInputFilter';\nimport getChatMembersString from '@components/wrappers/getChatMembersString';\nimport getUserStatusString from '@components/wrappers/getUserStatusString';\nimport getParticipantPeerId from '@appManagers/utils/chats/getParticipantPeerId';\nimport {attachContextMenuListener} from '@helpers/dom/attachContextMenuListener';\nimport contextMenuController from '@helpers/contextMenuController';\nimport positionMenu from '@helpers/positionMenu';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport SwipeHandler from '@components/swipeHandler';\nimport wrapDocument from '@components/wrappers/document';\nimport wrapPhoto from '@components/wrappers/photo';\nimport wrapVideo from '@components/wrappers/video';\nimport wrapMediaSpoiler, {hasSensitiveSpoiler, onMediaSpoilerClick} from '@components/wrappers/mediaSpoiler';\nimport filterAsync from '@helpers/array/filterAsync';\nimport ChatContextMenu, {getSponsoredMessageButtons} from '@components/chat/contextMenu';\nimport PopupElement from '@components/popups';\nimport getParticipantRank from '@appManagers/utils/chats/getParticipantRank';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport createParticipantContextMenu from '@helpers/dom/createParticipantContextMenu';\nimport findAndSpliceAll from '@helpers/array/findAndSpliceAll';\nimport deferredPromise from '@helpers/cancellablePromise';\nimport {children, createEffect, createRoot, For, on} from 'solid-js';\nimport {StoriesProfileList} from '@components/stories/profileList';\nimport {StoriesContextActions} from '@components/stories/store';\nimport Button from '@components/button';\nimport anchorCallback from '@helpers/dom/anchorCallback';\nimport PopupPremium from '@components/popups/premium';\nimport {ChatType} from './chat/chatType';\nimport getFwdFromName from '@appManagers/utils/messages/getFwdFromName';\nimport SidebarSlider from '@components/slider';\nimport cancelClickOrNextIfNotClick from '@helpers/dom/cancelClickOrNextIfNotClick';\nimport createElementFromMarkup from '@helpers/createElementFromMarkup';\nimport numberThousandSplitter from '@helpers/number/numberThousandSplitter';\nimport {ALL_COLLECTIONS_ID, StarGiftsProfileActions, StarGiftsProfileStore} from '@components/stargifts/profileStore';\nimport {getFirstChild} from '@solid-primitives/refs';\nimport SortedDialogList from '@components/sortedDialogList';\nimport Icon from '@components/icon';\nimport {showAdReport} from '@components/popups/reportAd';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport {isSensitive} from '@helpers/restrictions';\nimport {isMessageSensitive} from '@appManagers/utils/messages/isMessageRestricted';\nimport {MediaSearchContext} from '@components/appMediaPlaybackController';\nimport {StarGiftsProfileTab} from '@components/stargifts/profileList';\nimport {MyStarGift} from '@appManagers/appGiftsManager';\nimport wrapSticker from '@components/wrappers/sticker';\nimport {unwrap} from 'solid-js/store';\nimport {usePeer} from '@stores/peers';\nimport {useAppState} from '@stores/appState';\nimport {AutonomousSavedDialogList} from '@components/autonomousDialogList/savedDialogs';\nimport SetTransition from '@components/singleTransition';\nimport liteMode from '@helpers/liteMode';\nimport {wrapGlobalPostsSearch} from './sidebarLeft/globalPostsSearch';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport Tabs from '@components/tabs';\nimport Section from '@components/section';\nimport copyMessageMediaWithFeedback from '@components/copyMessageMediaWithFeedback';\nimport createTopPeersList from '@components/topPeersList';\nimport {fastRaf} from '@helpers/schedulers';\nimport {SearchSuperMediaInputFilter} from '@components/sharedMediaFilters';\nimport {getMediaTypeForProfileTab, orderMediaTabsByMain, ProfileTabMediaType} from '@components/sharedMediaProfileTab';\nimport {supportsSharedMediaScrollDate} from '@components/sharedMediaScrollDate';\nimport createSharedMediaScrollDateBadge from '@components/sharedMediaScrollDateBadge';\n\nexport type SearchSuperType = MyInputMessagesFilter/*  | 'members' */;\nexport type SearchSuperContext = {\n  peerId: PeerId,\n  inputFilter: {_: MyInputMessagesFilter},\n  query?: string,\n  maxId?: number,\n  folderId?: number,\n  threadId?: number,\n  monoforumThreadId?: PeerId,\n  date?: number,\n  nextRate?: number,\n  minDate?: number,\n  maxDate?: number\n} & Pick<RequestHistoryOptions, 'chatType' | 'communityId'>;\n\nexport type SearchSuperMediaType = 'stories' | 'members' | 'media' |\n  'files' | 'links' | 'music' | 'chats' | 'voice' | 'groups' | 'similar' |\n  'savedDialogs' | 'saved' | 'channels' | 'apps' | 'gifts' | 'posts';\nexport type SearchSuperMediaTab = {\n  inputFilter?: SearchSuperType,\n  name: LangPackKey,\n  type: SearchSuperMediaType,\n  contentTab?: HTMLElement,\n  itemsTab?: HTMLElement,\n  menuTab?: HTMLElement,\n  menuTabName?: HTMLElement,\n  scroll?: {scrollTop: number, scrollHeight: number},\n  hideOn?: HTMLElement\n};\n\nexport type SearchSuperMediaCounters = {\n  photos: number,\n  videos: number\n};\n\n// * a tab whose visibility follows its message counter — an empty one is hidden (see loadFirstTime)\nexport function isCounterDrivenMediaTab(mediaTab: SearchSuperMediaTab) {\n  return !!mediaTab.inputFilter && mediaTab.inputFilter !== 'inputMessagesFilterEmpty';\n}\n\ntype SearchSuperCommittedMediaFilterState = {\n  inputFilter: SearchSuperMediaInputFilter,\n  loaded: boolean,\n  nextRate: number,\n  counter: number,\n  scroll: SearchSuperMediaTab['scroll']\n};\n\ntype SearchSuperLoadTypeOptions = {\n  mediaTab: SearchSuperMediaTab,\n  justLoad: boolean,\n  loadCount: number,\n  middleware: Middleware,\n  side: 'top' | 'bottom'\n};\n\ntype PerformSearchResultArgs = {\n  messages: (Message.message | Message.messageService)[];\n  mediaTab: SearchSuperMediaTab;\n  canAnimateIn?: boolean;\n  append?: boolean;\n};\n\nclass SearchContextMenu {\n  private buttons: (ButtonMenuItemOptions & {verify?: () => boolean | Promise<boolean>, withSelection?: true})[];\n  private element: HTMLElement;\n  private target: HTMLElement;\n  private peerId: PeerId;\n  private mid: number;\n  private isSelected: boolean;\n  private managers: AppManagers;\n  private noForwards: boolean;\n  private message: MyMessage;\n  private selectedMessages: MyMessage[];\n  private copyMediaButton: ButtonMenuItemOptions & {\n    verify?: () => boolean | Promise<boolean>\n  };\n\n  constructor(\n    private attachTo: HTMLElement,\n    private searchSuper: AppSearchSuper,\n    private listenerSetter: ListenerSetter\n  ) {\n    this.managers = searchSuper.managers;\n\n    const onContextMenu: Parameters<typeof attachContextMenuListener>[0]['callback'] = (e) => {\n      if(this.init) {\n        this.init();\n        this.init = null;\n      }\n\n      let item: HTMLElement;\n      try {\n        item = findUpClassName(e.target, 'search-super-item');\n      } catch(e) {}\n\n      // stories have their own context menu in StoriesProfileTab\n      const isStory = !!findUpClassName(e.target, 'search-super-content-stories');\n      if(isStory) return;\n\n      if(!item) return;\n\n      // cross-realm-safe `instanceof MouseEvent` (excludes touch, survives the Document PiP window)\n      if(!('touches' in e)) e.preventDefault();\n      if(this.element.classList.contains('active')) {\n        return false;\n      }\n      if(!('touches' in e)) e.cancelBubble = true;\n\n      const r = async() => {\n        this.target = item;\n        this.peerId = item.dataset.peerId.toPeerId();\n        this.mid = +item.dataset.mid;\n        this.isSelected = searchSuper.selection.isMidSelected(this.peerId, this.mid);\n        this.message = await this.managers.appMessagesManager.getMessageByPeer(this.peerId, this.mid);\n        this.noForwards = searchSuper.selection.isSelecting ?\n          this.searchSuper.selection.selectionForwardBtn.classList.contains('hide') :\n          !(await this.managers.appMessagesManager.canForward(this.message));\n        this.selectedMessages = searchSuper.selection.isSelecting ? await searchSuper.selection.getSelectedMessages() : undefined;\n        // this.isSavedDialog = !!(searchSuper.searchContext.peerId === rootScope.myId && searchSuper.searchContext.threadId);\n\n        const f = await Promise.all(this.buttons.map(async(button) => {\n          let good: boolean;\n\n          if(this.searchSuper.selection.isSelecting && !button.withSelection) {\n            good = false;\n          } else {\n            good = button.verify ? !!(await button.verify()) : true;\n          }\n\n          button.element.classList.toggle('hide', !good);\n          return good;\n        }));\n\n        if(!f.some((v) => v)) {\n          return;\n        }\n\n        item.classList.add('menu-open');\n\n        positionMenu(e, this.element);\n        contextMenuController.openBtnMenu(this.element, () => {\n          item.classList.remove('menu-open');\n        });\n      };\n\n      r();\n    };\n\n    attachContextMenuListener({\n      element: attachTo,\n      callback: onContextMenu as any,\n      listenerSetter\n    });\n  }\n\n  private init() {\n    this.buttons = [{\n      icon: 'forward',\n      text: 'Forward',\n      onClick: this.onForwardClick,\n      verify: () => !this.noForwards\n    }, {\n      icon: 'forward',\n      text: 'Message.Context.Selection.Forward',\n      onClick: this.onForwardClick,\n      verify: () => this.searchSuper.selection.isSelecting && !this.noForwards,\n      withSelection: true\n    }, this.copyMediaButton = {\n      icon: 'copy',\n      text: 'MediaViewer.Context.Copy',\n      onClick: this.onCopyMediaClick,\n      verify: () => !this.searchSuper.selection.isSelecting &&\n        ChatContextMenu.canCopyMedia(this.message, undefined, this.noForwards, this.attachTo),\n      keepOpen: true\n    }, {\n      icon: 'download',\n      text: 'MediaViewer.Context.Download',\n      onClick: () => ChatContextMenu.onDownloadClick(this.message, this.noForwards, this.attachTo),\n      verify: () => !this.searchSuper.selection.isSelecting && ChatContextMenu.canDownload(this.message, undefined, this.noForwards, this.attachTo)\n    }, {\n      icon: 'download',\n      text: 'Message.Context.Selection.Download',\n      onClick: () => ChatContextMenu.onDownloadClick(this.selectedMessages, this.noForwards, this.attachTo),\n      verify: () => this.searchSuper.selection.isSelecting && ChatContextMenu.canDownload(this.selectedMessages, undefined, this.noForwards, this.attachTo),\n      withSelection: true\n    }, {\n      icon: 'message',\n      text: 'Message.Context.Goto',\n      onClick: this.onGotoClick,\n      withSelection: true\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Select',\n      onClick: this.onSelectClick,\n      verify: () => !this.isSelected,\n      withSelection: true\n    }, {\n      icon: 'select',\n      text: 'Message.Context.Selection.Clear',\n      onClick: this.onClearSelectionClick,\n      verify: () => this.isSelected,\n      withSelection: true\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Delete',\n      onClick: this.onDeleteClick,\n      verify: () => !this.searchSuper.selection.isSelecting && this.managers.appMessagesManager.canDeleteMessage(this.message)\n    }, {\n      icon: 'delete',\n      className: 'danger',\n      text: 'Message.Context.Selection.Delete',\n      onClick: this.onDeleteClick,\n      verify: () => this.searchSuper.selection.isSelecting && this.searchSuper.selection.selectionDeleteBtn && !this.searchSuper.selection.selectionDeleteBtn.classList.contains('hide'),\n      withSelection: true\n    }];\n\n    this.element = ButtonMenuSync({buttons: this.buttons, listenerSetter: this.listenerSetter});\n    this.element.classList.add('search-contextmenu', 'contextmenu');\n    getOverlayRoot().append(this.element);\n  }\n\n  private onGotoClick = () => {\n    appImManager.setInnerPeer({\n      peerId: this.peerId,\n      lastMsgId: this.mid,\n      threadId: this.searchSuper.mediaTab.type === 'saved' ? this.searchSuper.searchContext.peerId : this.searchSuper.searchContext.threadId\n    });\n  };\n\n  private onCopyMediaClick = () => {\n    copyMessageMediaWithFeedback({\n      message: this.message,\n      button: this.copyMediaButton\n    });\n  };\n\n  private onForwardClick = () => {\n    if(this.searchSuper.selection.isSelecting) {\n      simulateClickEvent(this.searchSuper.selection.selectionForwardBtn);\n    } else {\n      showForwardPopup({\n        [this.peerId]: [this.mid]\n      });\n    }\n  };\n\n  private onSelectClick = () => {\n    this.searchSuper.selection.toggleByElement(this.target);\n  };\n\n  private onClearSelectionClick = () => {\n    this.searchSuper.selection.cancelSelection();\n  };\n\n  private onDeleteClick = () => {\n    if(this.searchSuper.selection.isSelecting) {\n      simulateClickEvent(this.searchSuper.selection.selectionDeleteBtn);\n    } else {\n      PopupElement.createPopup(\n        PopupDeleteMessages,\n        this.peerId,\n        [this.mid],\n        ChatType.Chat\n      );\n    }\n  };\n}\n\nexport type ProcessSearchSuperResult = {\n  message: Message.message,\n  middleware: Middleware,\n  promises: Promise<any>[],\n  elemsToAppend: {element: HTMLElement, message: any}[],\n  inputFilter: MyInputMessagesFilter,\n  searchGroup?: SearchGroup,\n  mediaTab: SearchSuperMediaTab\n};\n\nexport default class AppSearchSuper {\n  public tabs: {[t in SearchSuperType]: HTMLDivElement} = {} as any;\n\n  public mediaTab: SearchSuperMediaTab;\n\n  public container: HTMLElement;\n  public nav: HTMLElement;\n  public navScrollableContainer: HTMLDivElement;\n  public tabsContainer: HTMLElement;\n  public navScrollable: ScrollableX;\n  private tabsMenu: HTMLElement;\n  private prevTabId = -1;\n\n  private lazyLoadQueue = new LazyLoadQueue();\n  public middleware = getMiddleware();\n\n  public historyStorage: Partial<{[type in SearchSuperType]: {mid: number, peerId: PeerId}[]}> = {};\n  public usedFromHistory: Partial<{[type in SearchSuperType]: number}> = {};\n\n  public searchContext: SearchSuperContext;\n  public loadMutex: Promise<any>;\n\n  private nextRates: Partial<{[type in SearchSuperMediaType]: number}> = {};\n  private loadPromises: Partial<{[type in SearchSuperMediaType]: Promise<any>}> = {};\n  private loaded: Partial<{[type in SearchSuperMediaType]: boolean}> = {};\n  private loadedChats = false;\n  private firstLoad = true;\n\n  private log = logger('SEARCH-SUPER');\n  public selectTab: ReturnType<typeof horizontalMenu>;\n\n\n  private searchGroupMedia: SearchGroup;\n\n  public mediaTabsMap: Map<SearchSuperMediaType, SearchSuperMediaTab> = new Map();\n\n  private membersList: SortedUserList;\n  private membersParticipantMap: Map<PeerId, ChatParticipant | ChannelParticipant>;\n  private membersMiddlewareHelper: MiddlewareHelper;\n\n  public storiesActions: StoriesContextActions;\n  public storiesSetAlbum: (albumId: number | undefined, skipAnimation?: boolean) => void;\n  private _loadSavedDialogs: (side: 'top' | 'bottom') => Promise<any>;\n\n  private _loadMoreApps: () => Promise<void>;\n\n  private skipScroll: boolean;\n\n  // * arguments\n  public mediaTabs: SearchSuperMediaTab[];\n  private mediaTabsDefaultOrder: SearchSuperMediaTab[];\n  public mainMediaTabType: ProfileTabMediaType;\n  public scrollable: Scrollable;\n  public searchGroups?: {[group in SearchGroupType]: SearchGroup};\n  public asChatList? = false;\n  public hideEmptyTabs? = true;\n  public onChangeTab?: (mediaTab: SearchSuperMediaTab) => void;\n  public showSender? = false;\n  public useMainProfileTab?: boolean;\n\n  private searchContextMenu: SearchContextMenu;\n  public selection: SearchSelection;\n\n  public scrollStartCallback: (dimensions: ScrollStartCallbackDimensions) => void;\n  public scrollOffset: number;\n\n  public managers: AppManagers;\n  private loadFirstTimePromise: Promise<void>;\n  private mediaFilterChangeId = 0;\n  private mediaFilterCommittedInputFilter: SearchSuperMediaInputFilter;\n  private mediaFilterCommittedState: SearchSuperCommittedMediaFilterState;\n  private mediaFilterStagingItemsTab: HTMLDivElement;\n  private mediaCountersRefreshId = 0;\n  private mediaCountersVersion = 0;\n  private scrollDateBadge: ReturnType<typeof createSharedMediaScrollDateBadge>;\n\n  private listenerSetter: ListenerSetter;\n  private swipeHandler: SwipeHandler;\n\n  public storiesArchive: boolean;\n\n  public counters: Partial<{[type in SearchSuperMediaType]: number}> = {};\n  public onLengthChange: (type: SearchSuperMediaType, length: number) => void;\n  public onMediaCountersChange: (counters?: SearchSuperMediaCounters) => void;\n  private mediaCounters: Partial<SearchSuperMediaCounters> = {};\n\n  public openSavedDialogsInner: boolean;\n\n  public slider: SidebarSlider;\n\n  public stargiftsStore: StarGiftsProfileStore;\n  public stargiftsActions: StarGiftsProfileActions;\n  public stargiftsSetCollection: (collectionId: number) => void;\n  private menuGradient: HTMLElement;\n\n  constructor(options: Pick<\n    AppSearchSuper,\n    'mediaTabs' |\n    'scrollable' |\n    'searchGroups' |\n    'asChatList' |\n    'hideEmptyTabs' |\n    'onChangeTab' |\n    'showSender' |\n    'managers' |\n    'scrollOffset'\n  > & Partial<Pick<AppSearchSuper, 'storiesArchive' | 'onLengthChange' | 'onMediaCountersChange' | 'openSavedDialogsInner' | 'slider' | 'useMainProfileTab'>>) {\n    safeAssign(this, options);\n    this.mediaTabsDefaultOrder = [...this.mediaTabs];\n\n    this.slider ??= appSidebarRight;\n\n    this.container = document.createElement('div');\n    this.container.classList.add('search-super');\n\n    this.listenerSetter = new ListenerSetter();\n    this.searchContextMenu = new SearchContextMenu(this.container, this, this.listenerSetter);\n    this.selection = new SearchSelection(this, this.managers, this.listenerSetter);\n\n    const navScrollableContainer = this.navScrollableContainer = document.createElement('div');\n    navScrollableContainer.classList.add('search-super-tabs-scrollable', 'menu-horizontal-scrollable', 'sticky');\n\n    const navScrollable = this.navScrollable = new ScrollableX(navScrollableContainer);\n    navScrollable.container.classList.add('search-super-nav-scrollable');\n\n    const nav = this.nav = document.createElement('nav');\n    nav.classList.add('search-super-tabs', 'menu-horizontal-div');\n    this.tabsMenu = nav;\n\n    navScrollable.container.append(nav);\n\n    for(const mediaTab of this.mediaTabs) {\n      const menuTab = document.createElement('div');\n      menuTab.classList.add('menu-horizontal-div-item');\n      const span = document.createElement('span');\n      span.classList.add('menu-horizontal-div-item-span');\n      const i = document.createElement('i');\n      i.classList.add('menu-horizontal-div-item-background');\n\n      span.append(mediaTab.menuTabName = i18n(mediaTab.name));\n\n      menuTab.append(i, span);\n\n      ripple(menuTab);\n\n      this.tabsMenu.append(menuTab);\n\n      this.mediaTabsMap.set(mediaTab.type, mediaTab);\n\n      mediaTab.menuTab = menuTab;\n    }\n\n    this.tabsContainer = document.createElement('div');\n    this.tabsContainer.classList.add('search-super-tabs-container', 'tabs-container');\n\n    let unlockScroll: ReturnType<typeof lockTouchScroll>;\n    if(IS_TOUCH_SUPPORTED) {\n      this.swipeHandler = handleTabSwipe({\n        element: this.tabsContainer,\n        onSwipe: (xDiff, yDiff, e) => {\n          xDiff *= -1;\n          yDiff *= -1;\n          const prevId = this.selectTab.prevId();\n          const children = Array.from(this.tabsMenu.children) as HTMLElement[];\n\n          const prevChild = this.mediaTabs[prevId];\n          if(prevChild.type === 'gifts' && this.stargiftsActions?.handleSwipe(xDiff, this.stargiftsSetCollection)) {\n            return\n          }\n\n          if(prevChild.type === 'stories' && this.storiesActions?.handleSwipe(xDiff, this.storiesSetAlbum)) {\n            return\n          }\n\n          let idx: number;\n          if(xDiff > 0) {\n            for(let i = prevId + 1; i < children.length; ++i) {\n              if(!children[i].classList.contains('hide')) {\n                idx = i;\n                break;\n              }\n            }\n          } else {\n            for(let i = prevId - 1; i >= 0; --i) {\n              if(!children[i].classList.contains('hide')) {\n                idx = i;\n                break;\n              }\n            }\n          }\n\n          if(idx !== undefined) {\n            unlockScroll = lockTouchScroll(this.tabsContainer);\n            this.selectTab(idx);\n          }\n        },\n        verifyTouchTarget: (e) => {\n          return !findUpClassName(e.target, 'scrollable-x');\n        }\n      });\n    }\n\n    const noSectionTypes: Set<SearchSuperMediaType> = new Set([\n      'stories',\n      'media',\n      'gifts',\n      'chats',\n      'channels',\n      'apps',\n      'posts'\n    ]);\n    for(const mediaTab of this.mediaTabs) {\n      const container = document.createElement('div');\n      container.classList.add('search-super-tab-container', 'search-super-container-' + mediaTab.type, 'tabs-tab');\n\n      const content = document.createElement('div');\n      content.classList.add('search-super-content-container', 'search-super-content-' + mediaTab.type);\n\n      container.append(content);\n\n      const useSection = !noSectionTypes.has(mediaTab.type);\n      let itemsContainer = content;\n      if(useSection) {\n        const items = document.createElement('div');\n        createRoot(() => {\n          Section({\n            noDelimiter: true,\n            class: 'hide',\n            ref: (ref) => {\n              content.append(mediaTab.hideOn = ref);\n            },\n            children: [items]\n          });\n        });\n        itemsContainer = items;\n      } else if(mediaTab.type === 'media') {\n        const grid = document.createElement('div');\n        grid.classList.add('search-super-content-media-grid');\n        content.append(grid);\n        itemsContainer = grid;\n      }\n\n      this.tabsContainer.append(container);\n\n      const {inputFilter} = mediaTab;\n      if(inputFilter) {\n        this.tabs[inputFilter] = itemsContainer;\n      }\n\n      mediaTab.contentTab = content;\n      mediaTab.itemsTab = itemsContainer;\n    }\n\n    this.container.append(\n      this.menuGradient = Tabs.MenuGradient({\n        color: 'background',\n        className: 'search-super-tabs-gradient'\n      }) as HTMLElement,\n      navScrollableContainer,\n      this.tabsContainer\n    );\n\n    // * construct end\n\n    this.searchGroupMedia = createSearchGroup({type: 'messages'});\n\n    // this.scrollable.onScrolledTop = () => {\n    //   if(this.mediaTab.contentTab && this.canLoadMediaTab(this.mediaTab)/* && false */) {\n    //     // this.log('onScrolledTop will load media');\n    //     this.load(true, undefined, 'top');\n    //   }\n    // };\n\n    this.scrollable.onScrolledBottom = () => {\n      if(this.mediaTab.contentTab && this.canLoadMediaTab(this.mediaTab)/* && false */) {\n        // this.log('onScrolledBottom will load media');\n        this.load(true, undefined, 'bottom');\n      }\n    };\n    // this.scroll.attachSentinels(undefined, 400);\n\n    this.selectTab = horizontalMenu(this.tabsMenu, this.tabsContainer, (id, tabContent, animate) => {\n      if(this.prevTabId === id && !this.skipScroll) {\n        this.scrollToStart();\n        return;\n      }\n\n      const newMediaTab = this.mediaTabs[id];\n      this.onChangeTab?.(newMediaTab);\n\n\n      const fromMediaTab = this.mediaTab;\n      this.mediaTab = newMediaTab;\n\n      if(!supportsSharedMediaScrollDate(newMediaTab.type)) {\n        this.scrollDateBadge?.hide();\n      }\n\n      if(this.prevTabId !== -1 && animate) {\n        this.onTransitionStart();\n      }\n\n      if(this.skipScroll) {\n        this.skipScroll = false;\n      } else {\n        const offsetTop = this.container.offsetTop - (this.scrollOffset || 0);\n        let scrollTop = this.scrollable.scrollPosition;\n        if(scrollTop < offsetTop) {\n          this.scrollToStart();\n          scrollTop = offsetTop;\n        }\n\n        fromMediaTab.scroll = {scrollTop: scrollTop, scrollHeight: this.scrollable.scrollSize};\n\n        if(newMediaTab.scroll === undefined) {\n          const rect = this.container.getBoundingClientRect();\n          const rect2 = this.container.parentElement.getBoundingClientRect();\n          const diff = rect.y - rect2.y;\n\n          if(scrollTop > diff) {\n            newMediaTab.scroll = {scrollTop: diff, scrollHeight: 0};\n          }\n        }\n\n        if(newMediaTab.scroll) {\n          const diff = fromMediaTab.scroll.scrollTop - newMediaTab.scroll.scrollTop;\n          // console.log('what you gonna do', this.goingHard, diff);\n\n          // this.scrollable.scrollTop = scrollTop;\n          if(diff/*  && diff < 0 */) {\n            /* if(diff > -(fromMediaTab.contentTab.scrollHeight + this.nav.scrollHeight)) {\n              fromMediaTab.contentTab.style.transform = `translateY(${diff}px)`;\n              this.scrollable.scrollTop = scrollTop - diff;\n            } else { */\n            newMediaTab.contentTab.style.transform = `translateY(${diff}px)`;\n            // }\n          }\n        }\n      }\n\n      /* if(this.prevTabId !== -1 && nav.offsetTop) {\n        this.scrollable.scrollTop -= nav.offsetTop;\n      } */\n\n      /* this.log('setVirtualContainer', id, this.sharedMediaSelected, this.sharedMediaSelected.childElementCount);\n      this.scroll.setVirtualContainer(this.sharedMediaSelected); */\n\n      if(this.prevTabId !== -1 && !newMediaTab.itemsTab.childElementCount) { // quick brown fix\n        // this.contentContainer.classList.remove('loaded');\n        this.load(true);\n      }\n\n      this.prevTabId = id;\n    }, () => {\n      this.scrollable.onScroll();\n\n      // console.log('what y', this.tabSelected.style.transform);\n      if(this.mediaTab.scroll !== undefined) {\n        this.mediaTab.contentTab.style.transform = '';\n        this.scrollable.scrollPosition = this.mediaTab.scroll.scrollTop;\n      }\n\n      if(unlockScroll) {\n        unlockScroll();\n        unlockScroll = undefined;\n      }\n\n      this.onTransitionEnd();\n    }, undefined, navScrollable, this.listenerSetter);\n\n    attachClickEvent(this.tabsContainer, (e) => {\n      if(this.selection.isSelecting) {\n        cancelClickOrNextIfNotClick(e);\n        this.selection.toggleByElement(findUpClassName(e.target, 'search-super-item'));\n      }\n    }, {capture: true, passive: false, listenerSetter: this.listenerSetter});\n\n    const onMediaClick = async(className: string, targetClassName: string, inputFilter: MyInputMessagesFilter, e: MouseEvent) => {\n      const target = findUpClassName(e.target as HTMLDivElement, className);\n      if(!target) return;\n\n      const mid = +target.dataset.mid;\n      if(!mid) {\n        this.log.warn('no messageId by click on target:', target);\n        return;\n      }\n\n      const mediaSpoiler: HTMLElement = target.querySelector('.media-spoiler-container');\n      if(mediaSpoiler) {\n        onMediaSpoilerClick({\n          event: e,\n          mediaSpoiler\n        });\n        return;\n      }\n\n      const peerId = target.dataset.peerId.toPeerId();\n      const message = await this.managers.appMessagesManager.getMessageByPeer(peerId, mid);\n      if(!target.isConnected) {\n        return;\n      }\n\n      const skipSensitive = this.isMessageSensitive(message as Message.message);\n\n      const targets = (Array.from(this.tabs[inputFilter].querySelectorAll('.' + targetClassName)) as HTMLElement[]).map((el) => {\n        const containerEl = findUpClassName(el, className);\n        if(skipSensitive && hasSensitiveSpoiler(containerEl)) {\n          return;\n        }\n\n        return {\n          element: el,\n          mid: +containerEl.dataset.mid,\n          peerId: containerEl.dataset.peerId.toPeerId()\n        };\n      }).filter(Boolean);\n\n      // const ids = Object.keys(this.mediaDivsByIds).map((k) => +k).sort((a, b) => a - b);\n      const idx = targets.findIndex((item) => item.mid === mid && item.peerId === peerId);\n\n      const mediaTab = this.mediaTabs.find((mediaTab) => mediaTab.inputFilter === inputFilter);\n      new AppMediaViewer()\n      .setSearchContext(this.copySearchContext(inputFilter, this.nextRates[mediaTab.type], skipSensitive))\n      .openMedia({\n        message,\n        target: targets[idx].element,\n        fromRight: 0,\n        reverse: false,\n        prevTargets: targets.slice(0, idx),\n        nextTargets: targets.slice(idx + 1)\n      });\n    };\n\n    const mediaTab = this.mediaTabsMap.get('media');\n    mediaTab?.itemsTab && attachClickEvent(\n      mediaTab.itemsTab,\n      (e) => {\n        if(this.mediaFilterStagingItemsTab) return;\n        return onMediaClick('grid-item', 'grid-item', mediaTab.inputFilter, e);\n      },\n      {listenerSetter: this.listenerSetter}\n    );\n    this.tabs.inputMessagesFilterDocument && attachClickEvent(\n      this.tabs.inputMessagesFilterDocument,\n      onMediaClick.bind(null, 'document-with-thumb', 'media-container', 'inputMessagesFilterDocument'),\n      {listenerSetter: this.listenerSetter}\n    );\n\n    /* attachClickEvent(this.tabs.inputMessagesFilterUrl, (e) => {\n      const target = e.target as HTMLElement;\n      if(target.tagName === 'A') {\n        return;\n      }\n\n      try {\n        const a = findUpClassName(target, 'row').querySelector('.anchor-url:last-child') as HTMLAnchorElement;\n        a.click();\n      } catch(err) {}\n    }); */\n\n    this.mediaTab = this.mediaTabs[0];\n\n    useHeavyAnimationCheck(() => {\n      this.lazyLoadQueue.lock();\n    }, () => {\n      this.lazyLoadQueue.unlockAndRefresh(); // ! maybe not so efficient\n    }, this.listenerSetter);\n  }\n\n  private scrollToStart() {\n    this.scrollable.scrollIntoViewNew({\n      element: this.container,\n      position: 'start',\n      startCallback: this.scrollStartCallback,\n      getElementPosition: this.scrollOffset ? ({elementPosition}) => elementPosition - this.scrollOffset : undefined\n    });\n  }\n\n  private onTransitionStart = () => {\n    this.container.classList.add('sliding');\n  };\n\n  private onTransitionEnd = () => {\n    this.container.classList.remove('sliding');\n  };\n\n  public getFirstVisibleMediaTab() {\n    return this.mediaTabs.find((mediaTab) => !mediaTab.menuTab.classList.contains('hide'));\n  }\n\n  public setMainMediaTab(type?: ProfileTabMediaType) {\n    this.mainMediaTabType = type;\n    const ordered = orderMediaTabsByMain(\n      this.mediaTabsDefaultOrder,\n      type,\n      (mediaTab) => !mediaTab.menuTab.classList.contains('hide')\n    );\n    if(ordered.every((mediaTab, index) => this.mediaTabs[index] === mediaTab)) {\n      return;\n    }\n\n    this.mediaTabs.splice(0, this.mediaTabs.length, ...ordered);\n    this.nav.append(...ordered.map((mediaTab) => mediaTab.menuTab));\n    this.tabsContainer.append(...ordered.map((mediaTab) => mediaTab.contentTab.parentElement));\n\n    if(this.prevTabId !== -1) {\n      this.prevTabId = this.mediaTabs.indexOf(this.mediaTab);\n    }\n  }\n\n  public setCounter(type: SearchSuperMediaType, count: number) {\n    this.counters[type] = count;\n\n    if(type === 'media') {\n      const inputFilter = this.mediaTabsMap.get('media')?.inputFilter;\n      if(inputFilter === 'inputMessagesFilterPhotos') {\n        this.setMediaCounters({photos: count});\n      } else if(inputFilter === 'inputMessagesFilterVideo') {\n        this.setMediaCounters({videos: count});\n      }\n    }\n\n    this.updateMediaTabVisibility(type);\n    this.onLengthChange?.(type, count);\n  }\n\n  // * counter-driven tabs are hidden while empty (see loadFirstTime), so they have to appear\n  // * (and disappear) on the fly when their counter crosses zero\n  private updateMediaTabVisibility(type: SearchSuperMediaType) {\n    if(!this.hideEmptyTabs || this.firstLoad) {\n      return;\n    }\n\n    const mediaTab = this.mediaTabsMap.get(type);\n    if(!mediaTab || !isCounterDrivenMediaTab(mediaTab)) {\n      return;\n    }\n\n    const hide = !this.counters[type];\n    if(mediaTab.menuTab.classList.contains('hide') === hide) {\n      return;\n    }\n\n    mediaTab.menuTab.classList.toggle('hide', hide);\n\n    let needChangeActive: boolean;\n    if(hide) {\n      needChangeActive = mediaTab.menuTab.classList.contains('active');\n      mediaTab.menuTab.classList.remove('active');\n    } else {\n      // * there was nothing to select when every tab was empty\n      needChangeActive = !this.mediaTabs.some((tab) => tab.menuTab.classList.contains('active'));\n    }\n\n    this.updateContainerHidden(needChangeActive);\n\n    if(\n      needChangeActive &&\n      this.mediaTab &&\n      !this.mediaTab.menuTab.classList.contains('hide') &&\n      this.canLoadMediaTab(this.mediaTab)\n    ) {\n      this.load(true);\n    }\n  }\n\n  private setMediaCounters(counters: Partial<SearchSuperMediaCounters>) {\n    Object.assign(this.mediaCounters, counters);\n    ++this.mediaCountersVersion;\n    const {photos, videos} = this.mediaCounters;\n    if(photos === undefined || videos === undefined) {\n      return;\n    }\n\n    this.onMediaCountersChange?.({photos, videos});\n  }\n\n  public updateMediaCountersByMessage(message: MyMessage, difference: 1 | -1) {\n    const key = this.filterMessagesByType([message], 'inputMessagesFilterPhotos').length ?\n      'photos' :\n      this.filterMessagesByType([message], 'inputMessagesFilterVideo').length ? 'videos' : undefined;\n    if(!key || this.mediaCounters[key] === undefined) {\n      return;\n    }\n\n    this.setMediaCounters({\n      [key]: Math.max(0, this.mediaCounters[key] + difference)\n    });\n  }\n\n  public async refreshMediaCounters() {\n    const refreshId = ++this.mediaCountersRefreshId;\n    const version = this.mediaCountersVersion;\n    const middleware = this.middleware.get();\n\n    try {\n      const counters = await this.getSearchCounters([{\n        _: 'inputMessagesFilterPhotos'\n      }, {\n        _: 'inputMessagesFilterVideo'\n      }], false);\n      if(\n        refreshId !== this.mediaCountersRefreshId ||\n        version !== this.mediaCountersVersion ||\n        !middleware()\n      ) {\n        return;\n      }\n\n      const photos = counters.find((counter) => counter.filter._ === 'inputMessagesFilterPhotos')?.count;\n      const videos = counters.find((counter) => counter.filter._ === 'inputMessagesFilterVideo')?.count;\n      this.setMediaCounters({photos, videos});\n    } catch(err) {\n      this.log.error('refresh media counters error:', err);\n    }\n  }\n\n  public async setMediaInputFilter(inputFilter: SearchSuperMediaInputFilter): Promise<SearchSuperMediaInputFilter | void> {\n    const changeId = ++this.mediaFilterChangeId;\n    const wasChanging = !!this.mediaFilterCommittedState;\n    await this.loadPromises.media;\n\n    const mediaTab = this.mediaTabsMap.get('media');\n    if(!mediaTab || changeId !== this.mediaFilterChangeId) {\n      return;\n    }\n\n    const committedInputFilter = this.mediaFilterCommittedInputFilter ??= mediaTab.inputFilter as SearchSuperMediaInputFilter;\n    if(!wasChanging && committedInputFilter === inputFilter) {\n      return;\n    }\n\n    const itemsTab = mediaTab.itemsTab as HTMLDivElement;\n    this.mediaFilterCommittedState ??= {\n      inputFilter: committedInputFilter,\n      loaded: this.loaded.media,\n      nextRate: this.nextRates.media,\n      counter: this.counters.media,\n      scroll: mediaTab.scroll\n    };\n\n    if(inputFilter === committedInputFilter || this.mediaTab !== mediaTab) {\n      this.restoreCommittedMediaFilterState(mediaTab, itemsTab);\n      return committedInputFilter;\n    }\n\n    const stagingItemsTab = itemsTab.cloneNode(false) as HTMLDivElement;\n    this.mediaFilterStagingItemsTab = stagingItemsTab;\n    mediaTab.inputFilter = inputFilter;\n    this.tabs[inputFilter] = stagingItemsTab;\n    this.searchContext.inputFilter = {_: inputFilter};\n    this.historyStorage[inputFilter] = [];\n    this.usedFromHistory[inputFilter] = -1;\n    this.loaded.media = false;\n    this.nextRates.media = 0;\n    delete this.counters.media;\n\n    mediaTab.scroll = undefined;\n\n    let loadResult: Awaited<ReturnType<AppSearchSuper['load']>>;\n    try {\n      loadResult = await this.load(true);\n    } catch(err) {\n      this.log.error('media filter load error:', err);\n    }\n\n    if(changeId !== this.mediaFilterChangeId) {\n      this.discardMediaFilterStagingItemsTab(stagingItemsTab);\n      return;\n    }\n\n    if(!Array.isArray(loadResult) || typeof loadResult[0] !== 'number') {\n      this.discardMediaFilterStagingItemsTab(stagingItemsTab);\n      this.restoreCommittedMediaFilterState(mediaTab, itemsTab);\n      return committedInputFilter;\n    }\n\n    await new Promise<void>((resolve) => fastRaf(() => {\n      if(changeId !== this.mediaFilterChangeId) {\n        this.discardMediaFilterStagingItemsTab(stagingItemsTab);\n        resolve();\n        return;\n      }\n\n      this.removeFromLazyLoadQueue(itemsTab);\n      itemsTab.replaceChildren(...Array.from(stagingItemsTab.children));\n      this.tabs[inputFilter] = itemsTab;\n      this.mediaFilterCommittedInputFilter = inputFilter;\n      this.mediaFilterCommittedState = undefined;\n\n      const parent = mediaTab.contentTab.parentElement;\n      Array.from(parent.children).slice(1).forEach((element) => element.remove());\n      if(!itemsTab.childElementCount) {\n        parent.append(this.createNothingFoundElement());\n      }\n\n      if(this.mediaTab === mediaTab) {\n        this.scrollToStart();\n      }\n\n      this.lazyLoadQueue.refresh();\n      this.mediaFilterStagingItemsTab = undefined;\n      resolve();\n    }));\n  }\n\n  private restoreCommittedMediaFilterState(mediaTab: SearchSuperMediaTab, itemsTab: HTMLDivElement) {\n    const state = this.mediaFilterCommittedState;\n    if(!state) {\n      return;\n    }\n\n    const pendingInputFilter = mediaTab.inputFilter;\n    if(pendingInputFilter !== state.inputFilter && this.tabs[pendingInputFilter] !== itemsTab) {\n      delete this.tabs[pendingInputFilter];\n    }\n\n    mediaTab.inputFilter = state.inputFilter;\n    mediaTab.scroll = state.scroll;\n    this.tabs[state.inputFilter] = itemsTab;\n    this.searchContext.inputFilter = {_: state.inputFilter};\n    this.loaded.media = state.loaded;\n    this.nextRates.media = state.nextRate;\n    this.counters.media = state.counter;\n    this.mediaFilterCommittedInputFilter = state.inputFilter;\n    this.mediaFilterCommittedState = undefined;\n  }\n\n  private discardMediaFilterStagingItemsTab(itemsTab: HTMLDivElement) {\n    this.removeFromLazyLoadQueue(itemsTab);\n    if(this.mediaFilterStagingItemsTab === itemsTab) {\n      this.mediaFilterStagingItemsTab = undefined;\n    }\n  }\n\n  private removeFromLazyLoadQueue(container: HTMLElement) {\n    Array.from(container.children).forEach((element) => {\n      this.lazyLoadQueue.delete({div: element as HTMLElement});\n    });\n  }\n\n  private createNothingFoundElement() {\n    const div = document.createElement('div');\n    div.append(i18n('Chat.Search.NothingFound'));\n    div.classList.add('position-center', 'text-center', 'content-empty', 'no-select');\n    return div;\n  }\n\n  public filterMessagesByType(messages: MyMessage[], type: SearchSuperType): MyMessage[] {\n    return filterMessagesByInputFilter({inputFilter: type, messages: messages, limit: messages.length});\n  }\n\n  private async processEmptyFilter({message, searchGroup, mediaTab}: ProcessSearchSuperResult) {\n    const isSaved = mediaTab.type === 'saved';\n\n    let peerId = message.peerId;\n    if(isSaved) {\n      peerId = message.fromId;\n    }\n    peerId = await this.managers.appPeersManager.getPeerMigratedTo(peerId) || peerId;\n\n    const middleware = this.middleware.get();\n\n    const loadPromises: Promise<any>[] = [];\n    const dialogElement = appDialogsManager.addDialogNew({\n      dontSetActive: true,\n      peerId,\n      container: searchGroup?.list || false,\n      avatarSize: 'bigger',\n      loadPromises,\n      wrapOptions: {\n        middleware\n      },\n      withStories: true,\n      meAsSaved: !isSaved,\n      autonomous: isSaved,\n      fromName: !peerId ? getFwdFromName(message.fwd_from) : undefined\n    });\n    const setLastMessagePromise = appDialogsManager.setLastMessageN({\n      dialog: {\n        _: 'dialog',\n        peerId\n      } as any,\n      lastMessage: message,\n      dialogElement,\n      highlightWord: this.searchContext.query,\n      noForwardIcon: isSaved\n    });\n\n    loadPromises.push(setLastMessagePromise);\n    return Promise.all(loadPromises).then(() => {\n      if(searchGroup) {\n        return;\n      }\n\n      return {element: dialogElement.container, message};\n    });\n  }\n\n  private async processPhotoVideoFilter({message, promises, middleware}: ProcessSearchSuperResult) {\n    const media = getMediaFromMessage(message, true);\n\n    const div = document.createElement('div');\n    div.classList.add('grid-item');\n    // this.log(message, photo);\n\n    let wrapped: Awaited<ReturnType<typeof wrapPhoto>>;\n    const size = choosePhotoSize(media, 200, 200);\n    if(media._ !== 'photo') {\n      wrapped = (await wrapVideo({\n        doc: media,\n        message,\n        container: div,\n        boxWidth: 0,\n        boxHeight: 0,\n        lazyLoadQueue: this.lazyLoadQueue,\n        middleware,\n        onlyPreview: true,\n        withoutPreloader: true,\n        noPlayButton: true,\n        photoSize: size\n      })).thumb;\n    } else {\n      wrapped = await wrapPhoto({\n        photo: media,\n        message,\n        container: div,\n        boxWidth: 0,\n        boxHeight: 0,\n        lazyLoadQueue: this.lazyLoadQueue,\n        middleware,\n        withoutPreloader: true,\n        noBlur: true,\n        size\n      });\n    }\n\n    const sensitive = this.isMessageSensitive(message);\n\n    if((message.media as MessageMedia.messageMediaPhoto).pFlags.spoiler || sensitive) {\n      const mediaSpoiler = await wrapMediaSpoiler({\n        animationGroup: 'chat',\n        media,\n        middleware,\n        sensitive,\n        width: 140,\n        height: 140,\n        multiply: 0.3\n      });\n\n      div.append(mediaSpoiler);\n    }\n\n    [\n      wrapped.images.thumb,\n      wrapped.images.full\n    ].filter(Boolean).forEach((image) => {\n      image.classList.add('grid-item-media');\n    });\n\n    promises.push(wrapped.loadPromises.thumb);\n\n    return {element: div, message};\n  }\n\n  private async processDocumentFilter({message, inputFilter, middleware}: ProcessSearchSuperResult) {\n    const document = getMediaFromMessage(message, true) as Document.document;\n    const showSender = this.showSender || (['voice', 'round'] as MyDocument['type'][]).includes(document.type);\n\n    const div = await wrapDocument({\n      message,\n      middleware,\n      withTime: !showSender,\n      fontWeight: 400,\n      voiceAsMusic: true,\n      clickable: true,\n      showSender,\n      searchContext: this.copySearchContext(inputFilter, this.nextRates.files, false),\n      lazyLoadQueue: this.lazyLoadQueue,\n      autoDownloadSize: 0,\n      getSize: () => 320\n    });\n\n    if((['audio', 'voice', 'round'] as MyDocument['type'][]).includes(document.type)) {\n      div.classList.add('audio-48');\n    }\n\n    return {message, element: div};\n  }\n\n  private async processUrlFilter({message, promises, middleware}: ProcessSearchSuperResult) {\n    let webPage = (message.media as MessageMedia.messageMediaWebPage)?.webpage as WebPage.webPage | WebPage.webPageEmpty;\n\n    if(!webPage) {\n      const entity = message.totalEntities ? message.totalEntities.find((e: any) => e._ === 'messageEntityUrl' || e._ === 'messageEntityTextUrl') : null;\n      let url: string, display_url: string, sliced: string;\n\n      if(!entity) {\n        const match = matchUrl(message.message);\n        if(!match) {\n          return;\n        }\n\n        url = match[0];\n      } else {\n        sliced = message.message.slice(entity.offset, entity.offset + entity.length);\n      }\n\n      if(entity?._ === 'messageEntityTextUrl') {\n        url = entity.url;\n        // display_url = sliced;\n      } else {\n        url = url || sliced;\n      }\n\n      display_url = url;\n\n      const same = message.message === url;\n      if(!url.match(/^(ftp|http|https):\\/\\//)) {\n        display_url = 'https://' + url;\n        url = url.includes('@') ? url : 'https://' + url;\n      }\n\n      display_url = new URL(display_url).hostname;\n\n      webPage = {\n        _: 'webPage',\n        pFlags: {},\n        url,\n        display_url,\n        id: '',\n        hash: 0\n      };\n\n      if(!same) {\n        webPage.description = message.message;\n      }\n    }\n\n    if(webPage._ === 'webPageEmpty') {\n      return;\n    }\n\n    const previewDiv = document.createElement('div');\n    previewDiv.classList.add('preview');\n\n    // this.log('wrapping webpage', webpage);\n\n    if(webPage.photo) {\n      const res = wrapPhoto({\n        container: previewDiv,\n        message: null,\n        photo: webPage.photo as Photo.photo,\n        boxWidth: 0,\n        boxHeight: 0,\n        withoutPreloader: true,\n        lazyLoadQueue: this.lazyLoadQueue,\n        middleware,\n        size: choosePhotoSize(webPage.photo as Photo.photo, 60, 60, false),\n        loadPromises: promises,\n        noBlur: true\n      });\n    } else {\n      previewDiv.classList.add('empty');\n      setInnerHTML(previewDiv, wrapAbbreviation(webPage.title || webPage.display_url || webPage.description || webPage.url, true));\n    }\n\n    const title = wrapWebPageTitle(webPage);\n\n    const subtitleFragment = wrapWebPageDescription(webPage);\n    const aFragment = htmlToDocumentFragment(wrapRichText(webPage.url || ''));\n    const a = aFragment.firstElementChild as HTMLAnchorElement;\n    const aIsAnchor = a instanceof HTMLAnchorElement;\n    if(aIsAnchor) {\n      try { // can have 'URIError: URI malformed'\n        a.innerText = decodeURIComponent(a.href);\n      } catch(err) {\n\n      }\n    }\n\n    if(subtitleFragment.firstChild) {\n      subtitleFragment.append('\\n');\n    }\n\n    subtitleFragment.append(a);\n\n    if(this.showSender) {\n      subtitleFragment.append('\\n', await wrapSenderToPeer(message));\n    }\n\n    if(!title.textContent) {\n      // title = new URL(webpage.url).hostname;\n      title.append(wrapPlainText(webPage.display_url.split('/', 1)[0]));\n    }\n\n    const row = renderSearchWebPageRow({\n      title,\n      titleRight: wrapSentTime(message),\n      subtitle: subtitleFragment,\n      media: previewDiv,\n      link: aIsAnchor ? {\n        href: a.href,\n        onClick: a.getAttribute('onclick'),\n        targetBlank: a.target === '_blank'\n      } : undefined,\n      middleware\n    });\n\n    if(row.innerText.trim().length) {\n      return {message, element: row};\n    }\n  }\n\n  public async performSearchResult({messages, mediaTab, canAnimateIn = false, append = true}: PerformSearchResultArgs) {\n    const elemsToAppend: {element: HTMLElement, message: any}[] = [];\n    const sharedMediaDiv: HTMLElement = mediaTab.contentTab;\n    const promises: Promise<any>[] = [];\n    const middleware = this.middleware.get();\n    const isSaved = mediaTab.type === 'saved';\n    let inputFilter = mediaTab.inputFilter;\n\n    await getHeavyAnimationPromise();\n\n    let searchGroup: SearchGroup;\n    if(inputFilter === 'inputMessagesFilterPhotoVideo' && !!this.searchContext.query.trim()) {\n      inputFilter = 'inputMessagesFilterEmpty';\n      searchGroup = this.searchGroupMedia;\n      sharedMediaDiv.append(searchGroup.container);\n    } else if(inputFilter === 'inputMessagesFilterEmpty' && !isSaved) {\n      searchGroup = this.searchGroups.messages;\n    }\n\n    if(canAnimateIn && liteMode.isAvailable('animations') && searchGroup?.container) {\n      searchGroup.container.classList.add('is-hidden');\n\n      setTimeout(() => SetTransition({\n        element: searchGroup.container,\n        className: 'is-visible',\n        forwards: true,\n        duration: 250,\n        onTransitionEnd: () => {\n          searchGroup.container.classList.remove('is-hidden');\n          searchGroup.container.classList.remove('is-visible');\n        }\n      }), 100); // doesn't properly animate without it, even useRafs don't really help\n    }\n\n    const options: ProcessSearchSuperResult = {\n      elemsToAppend,\n      inputFilter,\n      message: undefined,\n      middleware,\n      promises,\n      searchGroup,\n      mediaTab\n    };\n\n    let processCallback: (options: ProcessSearchSuperResult) => any;\n\n    // https://core.telegram.org/type/MessagesFilter\n    switch(inputFilter) {\n      case 'inputMessagesFilterEmpty': {\n        processCallback = this.processEmptyFilter;\n        break;\n      }\n\n      case 'inputMessagesFilterPhotos':\n      case 'inputMessagesFilterPhotoVideo':\n      case 'inputMessagesFilterVideo': {\n        processCallback = this.processPhotoVideoFilter;\n        break;\n      }\n\n      case 'inputMessagesFilterVoice':\n      case 'inputMessagesFilterRoundVoice':\n      case 'inputMessagesFilterMusic':\n      case 'inputMessagesFilterDocument': {\n        processCallback = this.processDocumentFilter;\n        break;\n      }\n\n      case 'inputMessagesFilterUrl': {\n        processCallback = this.processUrlFilter;\n        break;\n      }\n\n      default:\n        // this.log.warn('death is my friend', messages);\n        break;\n    }\n\n    if(processCallback) {\n      processCallback = processCallback.bind(this);\n\n      type K = {element: HTMLElement, message: Message.message | Message.messageService};\n      const results: (Promise<K> | K)[] = messages.map(async(message) => {\n        try {\n          options.message = message as Message.message;\n          return await processCallback(options);\n        } catch(err) {\n          this.log.error('error rendering filter', inputFilter, options, message, err);\n        }\n      });\n\n      const awaited = (await Promise.all(results)).filter(Boolean);\n      elemsToAppend.push(...awaited);\n    }\n\n    const showSearchGroupAnyway = mediaTab.type === 'chats' && searchGroup.createPlaceholder;\n    if(searchGroup && (searchGroup.list.childElementCount || showSearchGroupAnyway)) {\n      searchGroup.setActive();\n\n      if(!searchGroup.list?.childElementCount && searchGroup.createPlaceholder) searchGroup.addPlaceholder(searchGroup.createPlaceholder());\n    }\n\n    if(this.loadMutex) {\n      promises.push(this.loadMutex);\n    }\n\n    if(promises.length) {\n      await Promise.all(promises);\n      if(!middleware()) {\n        // this.log.warn('peer changed');\n        return 0;\n      }\n    }\n\n    const length = elemsToAppend.length;\n\n    if(length) {\n      const method = append ? 'append' : 'prepend';\n      const threadId = isSaved ? this.searchContext.peerId : undefined;\n      const container = this.tabs[inputFilter];\n      elemsToAppend.forEach((details) => {\n        const {element, message} = details;\n        if(!message) {\n          debugger;\n        }\n\n        element.classList.add('search-super-item');\n        element.dataset.mid = '' + message.mid;\n        element.dataset.peerId = '' + message.peerId;\n        element.dataset.timestamp = '' + message.date;\n        threadId && (element.dataset.threadId = '' + threadId);\n        container[method](element);\n\n        if(this.selection?.isSelecting) {\n          this.selection.toggleElementCheckbox(element, true);\n        }\n      });\n\n      if(isSaved) {\n        let chatlist = sharedMediaDiv.querySelector<HTMLElement>('.chatlist');\n        if(!chatlist) {\n          chatlist = appDialogsManager.createChatList({new: true});\n          container.append(chatlist);\n\n          appDialogsManager.setListClickListener({\n            list: chatlist,\n            onFound: (el) => {\n              if(this.selection.isSelecting) {\n                return false;\n              }\n            },\n            withContext: undefined,\n            autonomous: true,\n            openInner: true\n          });\n        }\n      }\n    }\n\n    // if(type !== 'inputMessagesFilterEmpty') {\n    this.afterPerforming(inputFilter === 'inputMessagesFilterEmpty' ? 1 : length, mediaTab);\n    // }\n\n    return length;\n  }\n\n  private afterPerforming(length: number, mediaTab: SearchSuperMediaTab) {\n    const contentTab = mediaTab.contentTab;\n    if(!contentTab) {\n      return;\n    }\n\n    if(mediaTab.type === 'media' && this.mediaFilterStagingItemsTab) {\n      return;\n    }\n\n    if(mediaTab.hideOn) {\n      mediaTab.hideOn.classList.remove('hide');\n    }\n\n    const parent = contentTab.parentElement;\n    Array.from(parent.children).slice(1).forEach((child) => {\n      child.remove();\n    });\n\n    // this.contentContainer.classList.add('loaded');\n\n    if(!length && !mediaTab.itemsTab.childElementCount) {\n      parent.append(this.createNothingFoundElement());\n    }\n  }\n\n  private loadChats() {\n    const renderedPeerIds: Set<PeerId> = new Set();\n    const middleware = this.middleware.get();\n\n    for(const i in this.searchGroups) {\n      const group = this.searchGroups[i as SearchGroupType];\n      group.clear();\n      this.tabs.inputMessagesFilterEmpty.append(group.container);\n    }\n\n    const query = this.searchContext.query;\n    if(query && !this.searchContext.peerId && !this.searchContext.communityId) {\n      const addDialogSubtitle = async(dom: DialogDom, peerId: PeerId) => {\n        const peer = await this.managers.appPeersManager.getPeer(peerId);\n        if(peerId === rootScope.myId) {\n          dom.lastMessageSpan.append(i18n('Presence.YourChat'));\n        } else {\n          let username = await this.managers.appPeersManager.getPeerUsername(peerId);\n          if(!username) {\n            const user = await this.managers.appUsersManager.getUser(peerId);\n            if(user?.phone) {\n              username = '+' + formatPhoneNumber(user.phone).formatted;\n            }\n          } else {\n            username = '@' + username;\n          }\n\n          // if(query) {\n          //   const regExp = new RegExp(`(${escapeRegExp(query)}|${escapeRegExp(cleanSearchText(query))})`, 'gi');\n          //   dom.titleSpan.innerHTML = dom.titleSpan.innerHTML.replace(regExp, '<i>$1</i>');\n          // }\n\n          const toJoin: (Node | string)[] = [\n            username\n          ];\n\n          if(/* showMembersCount &&  */((peer as Chat.channel).participants_count || (peer as any).participants)) {\n            toJoin.push(await getChatMembersString(peerId.toChatId()));\n          }\n\n          dom.lastMessageSpan.append(...join(toJoin.filter(Boolean), false));\n        }\n      }\n\n      const setResults = (results: PeerId[], group: SearchGroup, showMembersCount = false) => {\n        results.map((peerId) => {\n          if(renderedPeerIds.has(peerId)) {\n            return;\n          }\n\n          renderedPeerIds.add(peerId);\n\n          const {dom} = appDialogsManager.addDialogNew({\n            peerId: peerId,\n            container: group.list,\n            avatarSize: 'abitbigger',\n            autonomous: group.autonomous,\n            wrapOptions: {\n              middleware\n            },\n            withStories: true\n          });\n          return {dom, peerId};\n        }).filter(Boolean).forEach(async({dom, peerId}) => addDialogSubtitle(dom, peerId));\n\n        group.toggle();\n      };\n\n      const onLoad = <T>(arg: T) => {\n        if(!middleware()) {\n          return;\n        }\n\n        // this.loadedContacts = true;\n\n        return arg;\n      };\n\n      return Promise.all([\n        this.managers.appUsersManager.getContactsPeerIds(query, true, undefined, 10)\n        .then(onLoad)\n        .then((contacts) => {\n          if(contacts) {\n            setResults(contacts, this.searchGroups.contacts, true);\n          }\n        }),\n\n        this.managers.appChatsManager.getSponsoredPeers(query)\n        .then(onLoad)\n        .then((peers) => {\n          if(!peers?.length) return;\n\n          for(const peer of peers.reverse()) {\n            const {dom} = appDialogsManager.addDialogNew({\n              peerId: peer.peer,\n              container: this.searchGroups.globalContacts.list,\n              append: false,\n              avatarSize: 'abitbigger',\n              autonomous: this.searchGroups.globalContacts.autonomous,\n              wrapOptions: {\n                middleware\n              }\n            });\n\n            dom.containerEl.dataset.sponsored = 'true';\n\n            const chip = ButtonMenuToggle({\n              listenerSetter: this.listenerSetter,\n              appendTo: getOverlayRoot(),\n              buttons: getSponsoredMessageButtons({\n                message: peer,\n                handleReportAd: () => {\n                  showAdReport(peer);\n                }\n              }),\n              onOpen: (e, element) => {\n                // position menu\n                const rect = chip.getBoundingClientRect();\n                const bodyRect = getOverlayRoot().getBoundingClientRect();\n                element.style.right = `${bodyRect.width - (rect.left + rect.width)}px`;\n                element.style.top = `${rect.top + rect.height + 8}px`;\n              },\n              direction: 'bottom-left'\n            });\n            chip.classList.add('sponsored-peer-chip');\n\n            chip.replaceChildren(\n              i18n('SponsoredMessageAd'),\n              Icon('more')\n            )\n\n            dom.lastTimeSpan.appendChild(chip)\n\n            addDialogSubtitle(dom, peer.peer);\n          }\n        }),\n\n        this.managers.appUsersManager.searchContacts(query, 20)\n        .then(onLoad)\n        .then((contacts) => {\n          if(contacts) {\n            setResults(contacts.my_results, this.searchGroups.contacts, true);\n            setResults(contacts.results/* .concat(contacts.results, contacts.results, contacts.results) */, this.searchGroups.globalContacts);\n\n            this.searchGroups.globalContacts.container.classList.add('is-short');\n\n            if(this.searchGroups.globalContacts.nameEl.lastElementChild !== this.searchGroups.globalContacts.nameEl.firstElementChild) {\n              this.searchGroups.globalContacts.nameEl.lastElementChild.remove();\n            }\n\n            if(this.searchGroups.globalContacts.list.childElementCount > 3) {\n              this.searchGroups.globalContacts.needShowMoreButton('is-short');\n            }\n          }\n        }),\n\n        this.managers.dialogsStorage.getDialogs({query, offsetIndex: 0, limit: 20, filterId: 0})\n        .then(onLoad)\n        .then((value) => {\n          if(value) {\n            setResults(value.dialogs.map((d) => d.peerId), this.searchGroups.contacts, true);\n          }\n        })\n      ]);\n    } else if(!this.searchContext.peerId && !this.searchContext.communityId && !this.searchContext.minDate) {\n      const [appState] = useAppState();\n      const renderRecentSearch = (setActive = true) => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.searchGroups.recent.list.replaceChildren();\n\n        createRoot((dispose) => {\n          middleware.onClean(dispose);\n\n          const arr = For({\n            each: appState.recentSearch,\n            children: (peerId) => {\n              const middlewareHelper = createMiddleware();\n              const {dom} = appDialogsManager.addDialogNew({\n                peerId: peerId,\n                container: false,\n                meAsSaved: true,\n                avatarSize: 'abitbigger',\n                autonomous: true,\n                wrapOptions: {\n                  middleware: middlewareHelper.get()\n                },\n                withStories: true\n              });\n              (async() => {\n                dom.lastMessageSpan.append(await (peerId.isUser() ?\n                  Promise.resolve(getUserStatusString(await this.managers.appUsersManager.getUser(peerId.toUserId()))) :\n                  getChatMembersString(peerId.toChatId())));\n              })();\n\n              return dom.containerEl;\n            }\n          });\n\n          const elements = children(() => arr);\n          createEffect(() => {\n            this.searchGroups.recent.list.replaceChildren(...(elements.toArray() as HTMLElement[]));\n          });\n\n          createEffect(() => {\n            if(!appState.recentSearch.length) {\n              this.searchGroups.recent.clear();\n            } else if(setActive) {\n              this.searchGroups.recent.setActive();\n            }\n          });\n        });\n      };\n\n      return Promise.all([\n        createTopPeersList({\n          middleware,\n          onFound: close,\n          group: this.searchGroups.people,\n          modifyPeers: (peers) => {\n            peers = peers.slice(0, 15);\n            const idx = peers.findIndex((peer) => peer.id === rootScope.myId);\n            if(idx !== -1) {\n              peers = peers.slice();\n              peers.splice(idx, 1);\n            }\n\n            return peers;\n          }\n        }).promise,\n\n        renderRecentSearch()\n      ]);\n    } else return Promise.resolve();\n  }\n\n  private async loadMembers({mediaTab}: SearchSuperLoadTypeOptions) {\n    const chatId = mediaTab.type === 'members' ? this.searchContext.peerId.toChatId() : undefined;\n    const userId = mediaTab.type === 'groups' ? this.searchContext.peerId.toUserId() : undefined;\n    const middleware = this.middleware.get();\n    let promise: Promise<void>;\n\n    const renderParticipants = async(participants: (ChatParticipant | ChannelParticipant | Chat)[]) => {\n      if(this.loadMutex) {\n        await this.loadMutex;\n\n        if(!middleware()) {\n          return;\n        }\n      }\n\n      let membersList = this.membersList,\n        membersParticipantMap = this.membersParticipantMap,\n        membersMiddlewareHelper = this.membersMiddlewareHelper;\n      if(!membersList) {\n        membersParticipantMap = this.membersParticipantMap = new Map();\n        membersMiddlewareHelper = this.membersMiddlewareHelper = getMiddleware();\n        membersList = this.membersList = new SortedUserList({\n          lazyLoadQueue: this.lazyLoadQueue,\n          rippleEnabled: false,\n          managers: this.managers,\n          middleware\n        });\n        attachClickEvent(membersList.list, (e) => {\n          if(findUpClassName(e.target, 'has-stories')) {\n            return;\n          }\n\n          const li = findUpTag(e.target, DIALOG_LIST_ELEMENT_TAG);\n          if(!li) {\n            return;\n          }\n\n          const peerId = li.dataset.peerId.toPeerId();\n          let promise: Promise<any> = Promise.resolve();\n          if(this.slider === appSidebarRight && mediaSizes.isMobile) {\n            promise = (this.slider as typeof appSidebarRight).toggleSidebar(false);\n          }\n\n          promise.then(() => {\n            appImManager.setInnerPeer({peerId});\n          });\n        });\n        mediaTab.itemsTab.append(membersList.list);\n        this.afterPerforming(1, mediaTab);\n\n        if(chatId) {\n          const middleware = membersMiddlewareHelper.get();\n          createParticipantContextMenu({\n            chatId,\n            listenTo: membersList.list,\n            participants: this.membersParticipantMap,\n            slider: this.slider,\n            middleware\n          });\n\n          const deleteByPeerId = (peerId: PeerId) => {\n            membersList.ranks.delete(peerId);\n            membersList.delete(peerId);\n            membersParticipantMap.delete(peerId);\n            this.setCounter(mediaTab.type, this.counters[mediaTab.type] - 1);\n          };\n\n          const renderParticipant = (participant: ChannelParticipant | ChatParticipant) => {\n            renderParticipants([participant]);\n            this.setCounter(mediaTab.type, this.counters[mediaTab.type] + 1);\n          };\n\n          if(apiManagerProxy.getChat(chatId)._ === 'chat') {\n            const onChatFullUpdate = async(_chatId: ChatId) => {\n              if(chatId !== _chatId) {\n                return;\n              }\n\n              const chatFull = await this.managers.appProfileManager.getChatFull(chatId) as ChatFull.chatFull;\n              if(!middleware()) {\n                return;\n              }\n\n              const participants = chatFull.participants as ChatParticipants.chatParticipants;\n              const processedPeerIds = new Set<PeerId>();\n              for(const participant of participants.participants) {\n                const peerId = participant.user_id.toPeerId(false);\n                processedPeerIds.add(peerId);\n                renderParticipant(participant);\n              }\n\n              membersParticipantMap.forEach((participant, peerId) => {\n                if(!processedPeerIds.has(peerId)) {\n                  deleteByPeerId(peerId);\n                }\n              });\n            };\n            rootScope.addEventListener('chat_full_update', onChatFullUpdate);\n            middleware.onClean(() => {\n              rootScope.removeEventListener('chat_full_update', onChatFullUpdate);\n            });\n          } else {\n            const onParticipantUpdate = (update: Update.updateChannelParticipant) => {\n              if(chatId !== update.channel_id) {\n                return;\n              }\n\n              const peerId = getParticipantPeerId(update.prev_participant || update.new_participant);\n              const wasRendered = membersList.has(peerId);\n              if(wasRendered || (update.new_participant as ChannelParticipant.channelParticipantBanned).pFlags?.left) {\n                deleteByPeerId(peerId);\n              }\n\n              if((!update.prev_participant || wasRendered) && update.new_participant) {\n                renderParticipant(update.new_participant);\n              }\n            };\n            rootScope.addEventListener('chat_participant', onParticipantUpdate);\n            middleware.onClean(() => {\n              rootScope.removeEventListener('chat_participant', onParticipantUpdate);\n            });\n          }\n        }\n      }\n\n      const peerIds: {\n        peerId: PeerId,\n        rank: ReturnType<typeof getParticipantRank>,\n        participant: typeof participants[0]\n      }[] = participants.map((participant) => {\n        const peerId = userId ? (participant as Chat.chat).id.toPeerId(true) : getParticipantPeerId(participant as ChannelParticipant);\n        if(chatId ? peerId.isAnyChat() : peerId.isUser()) {\n          return;\n        }\n\n        return {\n          peerId,\n          rank: getParticipantRank(participant as ChannelParticipant) as any,\n          participant\n        };\n      }).filter(Boolean);\n\n      const filtered = await filterAsync(peerIds, async({peerId}) => {\n        const peer: User | Chat = await this.managers.appPeersManager.getPeer(peerId);\n        if(!middleware()) {\n          return false;\n        }\n\n        if(!peer || (peer as User.user).pFlags.deleted) {\n          return false;\n        }\n\n        return true;\n      });\n\n      for(const {peerId, rank, participant} of filtered) {\n        if(rank) {\n          membersList.ranks.set(peerId, rank);\n        } else {\n          membersList.ranks.delete(peerId);\n        }\n\n        membersParticipantMap.set(peerId, participant as ChannelParticipant);\n        if(membersList.has(peerId)) {\n          membersList.update(peerId);\n        } else {\n          membersList.add(peerId);\n        }\n      }\n    };\n\n    if(userId) {\n      const LOAD_COUNT = !this.membersList ? 50 : 200;\n      promise = this.managers.appUsersManager.getCommonChats(userId, LOAD_COUNT, this.nextRates[mediaTab.type]).then((messagesChats) => {\n        if(!middleware()) {\n          return;\n        }\n\n        const count = (messagesChats as MessagesChats.messagesChatsSlice).count ?? messagesChats.chats.length;\n        if(!this.counters[mediaTab.type]) {\n          this.setCounter(mediaTab.type, count);\n        }\n\n        // const list = mediaTab.contentTab.firstElementChild as HTMLUListElement;\n        const lastChat = messagesChats.chats[messagesChats.chats.length - 1];\n        this.nextRates[mediaTab.type] = lastChat?.id as number;\n\n        if(messagesChats.chats.length < LOAD_COUNT) {\n          this.loaded[mediaTab.type] = true;\n        }\n\n        return renderParticipants(messagesChats.chats);\n      });\n    } else if(await this.managers.appChatsManager.isChannel(chatId)) {\n      const LOAD_COUNT = !this.membersList ? 50 : 200;\n      promise = this.managers.appProfileManager.getChannelParticipants({\n        id: chatId,\n        limit: LOAD_COUNT,\n        offset: this.nextRates[mediaTab.type]\n      }).then((participants) => {\n        if(!middleware()) {\n          return;\n        }\n\n        const list = mediaTab.itemsTab.firstElementChild as HTMLUListElement;\n        this.nextRates[mediaTab.type] = (list ? list.childElementCount : 0) + participants.participants.length;\n\n        if(participants.participants.length < LOAD_COUNT) {\n          this.loaded[mediaTab.type] = true;\n        }\n\n        this.setCounter(mediaTab.type, participants.count);\n\n        return renderParticipants(participants.participants);\n      });\n    } else {\n      promise = this.managers.appProfileManager.getChatFull(chatId).then((chatFull) => {\n        if(!middleware()) {\n          return;\n        }\n\n        // console.log('anymore', chatFull);\n        this.loaded[mediaTab.type] = true;\n        const participants = (chatFull as ChatFull.chatFull).participants;\n        if(participants._ === 'chatParticipantsForbidden') {\n          return;\n        }\n\n        this.setCounter(mediaTab.type, participants.participants.length);\n\n        return renderParticipants(participants.participants);\n      });\n    }\n\n    return promise;\n  }\n\n  private loadStories({mediaTab}: SearchSuperLoadTypeOptions) {\n    if(this.storiesActions) {\n      return this.storiesActions.load();\n    }\n\n    const middleware = this.middleware.get();\n    const promise = deferredPromise<void>();\n    createRoot((dispose) => {\n      middleware.onClean(() => {\n        this.storiesActions = undefined;\n        this.storiesSetAlbum = undefined;\n        dispose();\n        promise.reject();\n      });\n\n      const {render: storiesList, actions, setAlbum} = StoriesProfileList({\n        peerId: this.searchContext.peerId,\n        pinned: !this.storiesArchive,\n        archive: this.storiesArchive,\n        scrollable: this.scrollable,\n        listenerSetter: this.listenerSetter,\n        withSelection: true,\n        selectionMount: this.navScrollableContainer,\n        onReady: () => {\n          promise.resolve();\n          mediaTab.contentTab.append(getFirstChild(storiesList, v => v instanceof Element) as Element);\n          this.afterPerforming(1, mediaTab);\n        },\n        onLoad: (loaded: boolean) => {\n          this.loaded[mediaTab.type] = loaded;\n        },\n        onCountChange: (length: number) => {\n          this.setCounter(mediaTab.type, length);\n        }\n      });\n      this.storiesActions = actions;\n      this.storiesSetAlbum = setAlbum;\n      this.storiesActions.load();\n    });\n    return promise;\n  }\n\n  private async loadSimilarChannels({mediaTab}: SearchSuperLoadTypeOptions) {\n    const middlewareHelper = this.middleware.get().create();\n\n    const renderChats = async(chats: Chat[], middleware: Middleware) => {\n      const chatlist = appDialogsManager.createChatList({new: true});\n\n      const promises = chats.map(async(chat) => {\n        const loadPromises: Promise<any>[] = [];\n        const {dom} = appDialogsManager.addDialogNew({\n          peerId: chat.id.toPeerId(true),\n          container: chatlist,\n          avatarSize: 'abitbigger',\n          autonomous: false,\n          wrapOptions: {\n            middleware\n          },\n          loadPromises\n        });\n        dom.lastMessageSpan.append(await getChatMembersString(chat.id, this.managers, chat));\n\n        return Promise.all(loadPromises);\n      });\n\n      appDialogsManager.setListClickListener({list: chatlist, autonomous: true});\n\n      await Promise.all(promises);\n      return chatlist;\n    };\n\n    const createPaywall = (limit: number) => {\n      const wall = document.createElement('div');\n      wall.classList.add('similar-channels-paywall');\n      const btn = Button('btn-primary btn-color-primary', {icon: 'premium_unlock_filled', text: 'UnlockSimilar'});\n      btn.classList.add('similar-channels-paywall-button');\n      const onClick = () => PopupPremium.show();\n      const anchor = anchorCallback(onClick);\n      attachClickEvent(btn, onClick);\n      anchor.classList.add('primary');\n      const subtitle = i18n('SimilarChannels.Unlock', [anchor, limit]);\n      subtitle.classList.add('similar-channels-paywall-subtitle');\n      wall.append(btn, subtitle);\n      return wall;\n    };\n\n    let paywall: HTMLElement, wasPremium: boolean;\n    const onPremium = async(isPremium: boolean) => {\n      if(wasPremium === isPremium) {\n        return;\n      }\n\n      middlewareHelper.clean();\n      const middleware = middlewareHelper.get();\n\n      const [messagesChats, premiumLimit, isPremiumFeaturesHidden] = await Promise.all([\n        this.managers.appChatsManager.getChannelRecommendations(this.searchContext.peerId.toChatId()),\n        this.managers.apiManager.getLimit('recommendedChannels', true),\n        apiManagerProxy.isPremiumFeaturesHidden()\n      ]);\n\n      const chatlist = await renderChats(messagesChats.chats, middleware);\n      if(!middleware()) {\n        return;\n      }\n\n      mediaTab.itemsTab.replaceChildren(chatlist);\n      this.afterPerforming(1, mediaTab);\n      this.loaded[mediaTab.type] = true;\n\n      const count = (messagesChats as MessagesChats.messagesChatsSlice).count ?? messagesChats.chats.length;\n      this.setCounter(mediaTab.type, count);\n\n      if(!isPremium && !isPremiumFeaturesHidden) {\n        paywall ||= createPaywall(premiumLimit);\n        mediaTab.itemsTab.append(paywall);\n      }\n    };\n\n    rootScope.addEventListener('premium_toggle', onPremium);\n    this.middleware.get().onClean(() => {\n      rootScope.removeEventListener('premium_toggle', onPremium);\n    });\n\n    return onPremium(rootScope.premium);\n  }\n\n  private async loadSavedDialogs({mediaTab, middleware, side}: SearchSuperLoadTypeOptions) {\n    if(this._loadSavedDialogs) {\n      return this._loadSavedDialogs(side);\n    }\n\n    const xd = new AutonomousSavedDialogList({appDialogsManager});\n    xd.scrollable = this.scrollable;\n    xd.sortedList = new SortedDialogList({\n      appDialogsManager,\n      managers: this.managers,\n      log: this.log,\n      requestItemForIdx: xd.requestItemForIdx,\n      onListShrinked: xd.onListShrinked,\n      itemSize: 72,\n      scrollable: this.scrollable,\n      indexKey: 'index_0',\n      virtualFilterId: rootScope.myId,\n      extraPaddingBottom: 0\n    });\n\n    const list = xd.sortedList.list;\n\n    appDialogsManager.setListClickListener({\n      list,\n      withContext: true,\n      openInner: this.openSavedDialogsInner\n    });\n\n    const getCount = async() => {\n      const result = await this.managers.dialogsStorage.getDialogs({filterId: rootScope.myId});\n      return result.count;\n    };\n\n    const onAnyUpdate = xd.onAnyUpdate = async() => {\n      if(!middleware()) return;\n      const count = await getCount();\n      this.setCounter(mediaTab.type, count);\n    };\n\n    onAnyUpdate();\n\n    mediaTab.itemsTab.append(list);\n    this.afterPerforming(1, mediaTab);\n\n    this._loadSavedDialogs = () => Promise.resolve(xd.onChatsScroll());\n    middleware.onClean(() => {\n      xd.destroy();\n      this._loadSavedDialogs = undefined;\n    });\n\n    return xd.onChatsScroll();\n  }\n\n  private async renderPeerDialogs(peerIds: PeerId[], group: SearchGroup, middleware: Middleware, type?: 'bots' | 'channels') {\n    if(!middleware()) return;\n\n    for(const peerId of peerIds) {\n      const {dom} = appDialogsManager.addDialogNew({\n        peerId,\n        container: group.list,\n        avatarSize: 'abitbigger',\n        wrapOptions: {\n          middleware\n        }\n      });\n      const peer = await this.managers.appPeersManager.getPeer(peerId);\n      const username = await this.managers.appPeersManager.getPeerUsername(peerId);\n\n      if('participants_count' in peer) {\n        dom.lastMessageSpan.append(await getChatMembersString(peerId.toChatId()));\n      } else if('bot_active_users' in peer) {\n        dom.lastMessageSpan.append(i18n('BotUsers', [numberThousandSplitter(peer.bot_active_users)]));\n      } else if(username) {\n        dom.lastMessageSpan.append('@' + username);\n      } else if(type === 'bots') {\n        dom.lastMessageSpan.append(i18n('UnknownBotUsers'));\n      }\n    };\n  }\n\n  private async loadChannels({mediaTab, middleware}: SearchSuperLoadTypeOptions) {\n    if(this.searchContext.query) {\n      const group = createSearchGroup({name: 'Channels', type: 'channels', middleware});\n      group.setActive();\n      group.nameEl.style.display = 'none';\n\n      const SEARCH_LIMIT = 200; // will get filtered anyway\n      const {results: globalResults} = await this.managers.appUsersManager.searchContacts(this.searchContext.query, SEARCH_LIMIT);\n      const filteredResultsWithUndefined = await Promise.all(\n        globalResults.map(async(user) => await this.managers.appPeersManager.isBroadcast(user) ? user : undefined)\n      );\n      const filteredResults = filteredResultsWithUndefined.filter(Boolean);\n\n      this.renderPeerDialogs(filteredResults.map((user) => user.toPeerId(true)), group, middleware);\n\n      if(filteredResults.length) {\n        mediaTab.itemsTab.append(group.container);\n      }\n      this.afterPerforming(filteredResults.length, mediaTab);\n\n      this.loaded[mediaTab.type] = true;\n      return;\n    }\n\n    const dialogs = await this.managers.dialogsStorage.getCachedDialogs();\n    const channelDialogsWithUndefined = await Promise.all(dialogs.map(async(dialog) => await this.managers.appPeersManager.isBroadcast(dialog.peerId) ? dialog : undefined));\n    const channelDialogs = channelDialogsWithUndefined.filter(Boolean);\n\n    if(channelDialogs.length) {\n      const group = createSearchGroup({name: 'Chat.Search.JoinedChannels', type: 'channels', middleware});\n      group.setActive();\n      mediaTab.itemsTab.append(group.container);\n\n      const SHOW_MORE_LIMIT = 5;\n      if(channelDialogs.length > SHOW_MORE_LIMIT) group.needShowMoreButton();\n\n      this.renderPeerDialogs(channelDialogs.map((dialog) => dialog.peerId), group, middleware);\n    }\n\n    const recommendations = await this.managers.appChatsManager.getChannelRecommendations();\n\n    if(recommendations.chats.length) {\n      const group = createSearchGroup({name: 'SimilarChannels', type: 'channels', middleware});\n      group.setActive();\n      mediaTab.itemsTab.append(group.container);\n\n      this.renderPeerDialogs(recommendations.chats.map((chat) => chat.id.toPeerId(true)), group, middleware);\n    }\n\n    this.afterPerforming(1, mediaTab);\n    this.loaded[mediaTab.type] = true;\n  }\n\n  private async loadApps({mediaTab, middleware}: SearchSuperLoadTypeOptions) {\n    if(this._loadMoreApps) {\n      return this._loadMoreApps();\n    }\n\n    const onClick = (el: HTMLElement): boolean => {\n      (async() => {\n        const peerId = el.dataset.peerId.toPeerId();\n        const userFull = await this.managers.appProfileManager.getProfile(peerId);\n        appImManager.openWebApp({\n          botId: peerId.toUserId(),\n          url: (userFull.bot_info.menu_button as BotMenuButton.botMenuButton).url,\n          buttonText: (userFull.bot_info.menu_button as BotMenuButton.botMenuButton).text,\n          fromBotMenu: true,\n          peerId\n        });\n      })();\n      return false;\n    };\n\n    if(this.searchContext.query) {\n      const group = createSearchGroup({name: 'ChatList.Filter.Bots', type: 'apps', onFound: onClick, middleware});\n      group.setActive();\n\n      const SEARCH_LIMIT = 200; // will get filtered anyway\n      const {results: globalResults} = await this.managers.appUsersManager.searchContacts(this.searchContext.query, SEARCH_LIMIT);\n      const filteredResultsWithUndefined = await Promise.all(\n        globalResults.map(async(user) => await this.managers.appPeersManager.isBot(user) ? user : undefined)\n      );\n      const filteredResults = filteredResultsWithUndefined.filter(Boolean);\n\n      this.renderPeerDialogs(filteredResults.map((user) => user.toPeerId(false)), group, middleware, 'bots');\n\n      if(filteredResults.length) {\n        mediaTab.itemsTab.append(group.container);\n      }\n      this.afterPerforming(filteredResults.length, mediaTab);\n\n      this.loaded[mediaTab.type] = true;\n      return;\n    }\n\n    const myTopApps = await rootScope.managers.appUsersManager.getTopPeers('bots_app');\n\n    if(myTopApps.length) {\n      const group = createSearchGroup({name: 'MiniApps.Apps', type: 'apps', onFound: onClick, middleware});\n      group.setActive();\n      mediaTab.itemsTab.append(group.container);\n\n      const SHOW_MORE_LIMIT = 5;\n      if(myTopApps.length > SHOW_MORE_LIMIT) group.needShowMoreButton();\n\n      this.renderPeerDialogs(myTopApps.map((app) => app.id.toPeerId(false)), group, middleware, 'bots');\n    }\n\n    const group = createSearchGroup({name: 'MiniApps.Popular', type: 'apps', onFound: onClick, middleware});\n    group.setActive();\n    mediaTab.itemsTab.append(group.container);\n\n    type GetPopularAppsResult = ReturnType<typeof rootScope.managers.appAttachMenuBotsManager.getPopularAppBots>;\n    let currentOffset: string = '', loadPromise: GetPopularAppsResult;\n    const APPS_LIMIT_PER_LOAD = 20;\n\n    const loadMoreApps = async() => {\n      if(\n        loadPromise ||\n        !middleware() ||\n        currentOffset === undefined\n      ) return;\n\n      loadPromise = rootScope.managers.appAttachMenuBotsManager.getPopularAppBots(currentOffset, APPS_LIMIT_PER_LOAD);\n      const {nextOffset, userIds} = await loadPromise;\n\n      await this.renderPeerDialogs(userIds.map((id) => id.toPeerId(false)), group, middleware, 'bots');\n\n      currentOffset = nextOffset || undefined;\n      loadPromise = undefined;\n\n      if(!currentOffset) {\n        this.loaded[mediaTab.type] = true;\n      }\n    }\n\n    this._loadMoreApps = loadMoreApps;\n    await loadMoreApps();\n\n    middleware.onClean(() => {\n      this._loadMoreApps = undefined;\n    });\n\n    this.afterPerforming(1, mediaTab);\n  }\n\n  globalPostsSearch: ReturnType<typeof wrapGlobalPostsSearch>;\n  private async loadPosts({mediaTab, middleware}: SearchSuperLoadTypeOptions) {\n    if(!this.globalPostsSearch) {\n      this.globalPostsSearch = wrapGlobalPostsSearch({\n        middleware,\n        query: this.searchContext.query\n      });\n      mediaTab.itemsTab.append(this.globalPostsSearch.dom);\n    }\n\n    this.globalPostsSearch.loadMore();\n  }\n\n  private loadGifts(): Promise<void> {\n    const mediaTab = this.mediaTabsMap.get('gifts');\n    if(!mediaTab) return Promise.resolve();\n\n    if(!this.stargiftsStore) {\n      const middleware = this.middleware.get();\n      createRoot((dispose) => {\n        middleware.onClean(() => dispose());\n\n        const scrollTarget = this.scrollable.container;\n\n        const {render: giftsList, store, actions, setCollection} = StarGiftsProfileTab({\n          peerId: this.searchContext.peerId,\n          scrollParent: scrollTarget,\n          onCountChange: (count) => {\n            this.setCounter('gifts', count);\n\n            mediaTab.menuTab.classList.toggle('hide', count === 0);\n            let needChangeActive = false\n            if(count === 0) {\n              needChangeActive = mediaTab.menuTab.classList.contains('active');\n              mediaTab.menuTab.classList.remove('active');\n            }\n            this.updateContainerHidden(needChangeActive);\n          }\n        });\n        createEffect(on(() => store.items, (items) => {\n          if(items.length > 0 && store.chosenCollection === ALL_COLLECTIONS_ID) {\n            this.setPinnedGifts(unwrap(items));\n          }\n        }))\n        this.stargiftsStore = store;\n        this.stargiftsActions = actions;\n        this.stargiftsSetCollection = setCollection;\n\n        mediaTab.itemsTab.append(getFirstChild(giftsList, (v) => v instanceof Element) as Element);\n\n        if(this.mediaTab?.type === 'gifts') {\n          this.onChangeTab?.(this.mediaTab);\n        }\n      });\n      return Promise.resolve();\n    }\n\n    if(this.stargiftsStore.loading || this.stargiftsStore.loaded) {\n      return Promise.resolve();\n    }\n\n    return this.stargiftsActions.loadNext();\n  }\n\n  private loadType(options: SearchSuperLoadTypeOptions) {\n    const {\n      mediaTab,\n      justLoad,\n      loadCount,\n      middleware,\n      side\n    } = options;\n    const {type, inputFilter} = mediaTab;\n\n\n    let promise = this.loadPromises[type];\n    if(promise) {\n      return promise;\n    }\n\n    if(type === 'members' || type === 'groups') {\n      promise = this.loadMembers(options);\n    } else if(type === 'stories') {\n      promise = this.loadStories(options);\n    } else if(type === 'similar') {\n      promise = this.loadSimilarChannels(options);\n    } else if(type === 'savedDialogs') {\n      promise = this.loadSavedDialogs(options);\n    } else if(type === 'channels') {\n      promise = this.loadChannels(options);\n    } else if(type === 'apps') {\n      promise = this.loadApps(options);\n    } else if(type === 'posts') {\n      promise = this.loadPosts(options);\n    } else if(type === 'gifts') {\n      promise = this.loadGifts();\n    }\n\n    if(promise) {\n      return this.loadPromises[type] = promise.finally(() => {\n        if(!middleware()) {\n          return;\n        }\n\n        this.loadPromises[type] = null;\n\n        setTimeout(() => {\n          this.scrollable.checkForTriggers();\n        }, 0);\n      });\n    }\n\n    const history = this.historyStorage[inputFilter] ??= [];\n\n    if(inputFilter === 'inputMessagesFilterEmpty' && !history.length && type !== 'saved') {\n      if(!this.loadedChats) {\n        this.loadChats();\n        this.loadedChats = true;\n      }\n\n      if(\n        !this.searchContext.query.trim() &&\n        !this.searchContext.peerId &&\n        !this.searchContext.communityId &&\n        !this.searchContext.minDate\n      ) {\n        this.loaded[type] = true;\n        return Promise.resolve();\n      }\n    }\n\n    promise = this.loadPromises[type] = Promise.resolve().then(async() => {\n      // render from cache\n      if(history.length && this.usedFromHistory[inputFilter] < history.length && !justLoad) {\n        const messages: any[] = [];\n        let used = Math.max(0, this.usedFromHistory[inputFilter]);\n        let slicedLength = 0;\n\n        do {\n          const ids = history.slice(used, used + loadCount);\n          used += ids.length;\n          slicedLength += ids.length;\n\n          // * a mid can have no message behind it (deleted, or a synthetic bound), skip such holes\n          const notFilteredMessages = ids.map((m) => apiManagerProxy.getMessageByPeer(m.peerId, m.mid)).filter(Boolean);\n          // const notFilteredMessages = await Promise.all(promises);\n\n          messages.push(...this.filterMessagesByType(notFilteredMessages, inputFilter));\n        } while(slicedLength < loadCount && used < history.length);\n\n        // если перебор\n        /* if(slicedLength > loadCount) {\n          let diff = messages.length - loadCount;\n          messages = messages.slice(0, messages.length - diff);\n          used -= diff;\n        } */\n\n        this.usedFromHistory[inputFilter] = used;\n        // if(messages.length) {\n        return this.performSearchResult({messages, mediaTab}).finally(() => {\n          setTimeout(() => {\n            this.scrollable.checkForTriggers();\n          }, 0);\n        });\n        // }\n      }\n\n      const lastItem = history[history.length - 1];\n      const offsetId = lastItem?.mid || 0;\n      const offsetPeerId = lastItem?.peerId || NULL_PEER_ID;\n\n      const options: Parameters<AppMessagesManager['getHistory']>[0] = {\n        ...this.searchContext,\n        inputFilter: {_: inputFilter},\n        offsetId,\n        offsetPeerId,\n        limit: loadCount,\n        nextRate: this.nextRates[type] ??= 0,\n        ...(type === 'saved' ? {inputFilter: undefined, peerId: rootScope.myId, threadId: this.searchContext.peerId} : {})\n      };\n      const value = await this.managers.appMessagesManager.getHistory(options);\n\n      let messages = value.messages;\n      if(!messages && value.history/*  && mediaTab.type === 'saved' */) {\n        messages = value.history.map((mid) => apiManagerProxy.getMessageByPeer(options.peerId, mid));\n      }\n\n      // * a mid can have no message behind it (deleted, or a synthetic bound), skip such holes\n      messages = messages.filter(Boolean);\n\n      history.push(...messages.map((m) => ({mid: m.mid, peerId: m.peerId})));\n\n      if(!this.counters[type]) {\n        this.setCounter(type, value.count);\n      }\n\n      if(!middleware()) {\n        // this.log.warn('peer changed');\n        return;\n      }\n\n      // ! Фикс случая, когда не загружаются документы при открытой панели разработчиков (происходит из-за того, что не совпадают критерии отбора документов в getSearch)\n      if(\n        value.history.length < loadCount ||\n        (this.searchContext.folderId !== undefined && !value.nextRate) ||\n        // value.history.length === value.count\n        value.isEnd.top\n      ) {\n      // if((value.count || history.length === value.count) && history.length >= value.count) {\n        // this.log(logStr + 'loaded all media', value, loadCount);\n        this.loaded[type] = true;\n      }\n\n      this.nextRates[type] = value.nextRate;\n\n      if(justLoad) {\n        return;\n      }\n\n      this.usedFromHistory[inputFilter] = history.length;\n\n      if(!this.loaded[type]) {\n        promise.then(() => {\n          setTimeout(() => {\n            if(!middleware()) return;\n            // this.log('will preload more');\n            if(this.mediaTab === mediaTab) {\n              const promise = this.load(true, true);\n              if(promise) {\n                promise.then(() => {\n                  if(!middleware()) return;\n                  // this.log('preloaded more');\n                  setTimeout(() => {\n                    this.scrollable.checkForTriggers();\n                  }, 0);\n                });\n              }\n            }\n          }, 0);\n        });\n      }\n\n      // if(value.history.length) {\n      return this.performSearchResult({messages: this.filterMessagesByType(messages, inputFilter), mediaTab, canAnimateIn: !offsetId});\n      // }\n    }).catch((err) => {\n      this.log.error('load error:', err);\n    }).finally(() => {\n      this.loadPromises[type] = null;\n    });\n\n    return promise;\n  }\n\n  private canLoadMediaTab(mediaTab: SearchSuperMediaTab) {\n    if(mediaTab.type === 'gifts') {\n      return !this.stargiftsStore || (!this.stargiftsStore.loading && !this.stargiftsStore.loaded);\n    }\n\n    const inputFilter = mediaTab.inputFilter;\n    return !this.loaded[mediaTab.type] || (this.historyStorage[inputFilter] && this.usedFromHistory[inputFilter] < this.historyStorage[inputFilter].length);\n  }\n\n  private isMessageSensitive(message: Message.message) {\n    return isSensitive((usePeer(message.peerId) as User.user).restriction_reason || []) || isMessageSensitive(message);\n  }\n\n  public getSearchCounters(filters: MessagesFilter[], canCache = true) {\n    const {peerId, threadId} = this.searchContext;\n    return this.managers.appMessagesManager.getSearchCounters(peerId, filters, canCache, threadId);\n  }\n\n  private async loadFirstTime() {\n    const middleware = this.middleware.get();\n    const {peerId, threadId} = this.searchContext;\n    if(!this.hideEmptyTabs) {\n      return;\n    }\n\n    const mediaTabs = this.mediaTabs.filter(isCounterDrivenMediaTab);\n    const filterTypes = new Set(mediaTabs.map((mediaTab) => mediaTab.inputFilter));\n    if(this.mediaTabsMap.has('media')) {\n      filterTypes.add('inputMessagesFilterPhotos');\n      filterTypes.add('inputMessagesFilterVideo');\n    }\n    const filters = Array.from(filterTypes, (inputFilter) => ({_: inputFilter} as MessagesFilter));\n\n    const [\n      counters,\n      canViewSavedDialogs,\n      canViewSaved,\n      canViewMembers,\n      canViewGroups,\n      canViewStories,\n      canViewSimilar,\n      canViewGifts,\n      profileTabsData,\n      maybePinnedGifts\n    ] = await Promise.all([\n      this.getSearchCounters(filters),\n      this.canViewSavedDialogs(),\n      this.canViewSaved(),\n      this.canViewMembers(),\n      this.canViewGroups(),\n      this.canViewStories(),\n      this.canViewSimilar(),\n      this.canViewGifts(),\n      this.getProfileTabsData(),\n      peerId === rootScope.myId && this.managers.appGiftsManager.getPinnedGifts(peerId)\n    ]);\n\n    if(!middleware()) {\n      return;\n    }\n\n    if(this.loadMutex) {\n      await this.loadMutex;\n\n      if(!middleware()) {\n        return;\n      }\n    }\n\n    if(this.mediaTabsMap.has('media')) {\n      const photos = counters.find((counter) => counter.filter._ === 'inputMessagesFilterPhotos')?.count;\n      const videos = counters.find((counter) => counter.filter._ === 'inputMessagesFilterVideo')?.count;\n      this.setMediaCounters({photos, videos});\n    }\n\n    let firstMediaTab: SearchSuperMediaTab;\n    let count = 0;\n    mediaTabs.forEach((mediaTab) => {\n      const counter = counters.find((c) => c.filter._ === mediaTab.inputFilter);\n\n      mediaTab.menuTab.classList.toggle('hide', !counter.count);\n      mediaTab.menuTab.classList.remove('active');\n      // mediaTab.contentTab.classList.toggle('hide', !counter.count);\n\n      this.setCounter(mediaTab.type, counter.count);\n\n      if(counter.count) {\n        firstMediaTab ??= mediaTab;\n        ++count;\n      }\n    });\n\n    const savedDialogsTab = this.mediaTabsMap.get('savedDialogs');\n    const savedTab = this.mediaTabsMap.get('saved');\n    const membersTab = this.mediaTabsMap.get('members');\n    const storiesTab = this.mediaTabsMap.get('stories');\n    const groupsTab = this.mediaTabsMap.get('groups');\n    const similarTab = this.mediaTabsMap.get('similar');\n    const giftsTab = this.mediaTabsMap.get('gifts');\n\n    const giftsCount = profileTabsData.giftsCount ?? 0;\n    const showGiftsTab = canViewGifts && giftsCount !== 0;\n\n    const a: [SearchSuperMediaTab, boolean][] = [\n      [savedDialogsTab, canViewSavedDialogs],\n      [savedTab, canViewSaved],\n      [storiesTab, canViewStories],\n      [membersTab, canViewMembers],\n      [groupsTab, canViewGroups],\n      [similarTab, canViewSimilar],\n      [giftsTab, showGiftsTab]\n    ];\n\n    a.forEach(([tab, value]) => {\n      if(!tab) {\n        return;\n      }\n\n      tab.menuTab.classList.toggle('hide', !value);\n\n      if(value) {\n        ++count;\n      }\n    });\n\n    this.setCounter('gifts', giftsCount);\n\n    if(canViewStories) {\n      firstMediaTab = storiesTab;\n\n      const newTitle = i18n(peerId.isUser() ? 'Stories' : 'ProfileStories');\n      storiesTab.menuTabName.replaceWith(storiesTab.menuTabName = newTitle);\n    }\n\n    if(canViewMembers) {\n      firstMediaTab = membersTab;\n    }\n\n    if(canViewSavedDialogs) {\n      firstMediaTab = savedDialogsTab;\n    }\n\n    if(showGiftsTab && !firstMediaTab) {\n      firstMediaTab = giftsTab;\n    }\n\n    if(maybePinnedGifts) {\n      this.setPinnedGifts(maybePinnedGifts);\n    }\n\n    const mainMediaTabType = getMediaTypeForProfileTab(profileTabsData.mainTab);\n    this.setMainMediaTab(mainMediaTabType);\n    const mainMediaTab = this.mediaTabs.find((mediaTab) => mediaTab.type === mainMediaTabType);\n    if(mainMediaTab && !mainMediaTab.menuTab.classList.contains('hide')) {\n      firstMediaTab = mainMediaTab;\n    }\n\n    this.toggleContainerHidden(!firstMediaTab);\n    if(firstMediaTab) {\n      this.skipScroll = true;\n      this.selectTab(this.mediaTabs.indexOf(firstMediaTab), false);\n      // firstMediaTab.menuTab.classList.add('active');\n\n      const isSingle = count <= 1;\n      this.navScrollableContainer.classList.toggle('is-single', isSingle);\n      this.menuGradient.classList.toggle('hide', isSingle);\n    }\n  }\n\n  private toggleContainerHidden(hidden: boolean) {\n    this.container.classList.toggle('hide', hidden);\n    this.container.parentElement.classList.toggle('search-empty', hidden);\n  }\n\n  private updateContainerHidden(changeActive = false) {\n    this.setMainMediaTab(this.mainMediaTabType);\n    const visibleTabs = this.mediaTabs.filter((tab) => !tab.menuTab.classList.contains('hide'));\n    this.toggleContainerHidden(visibleTabs.length === 0);\n    const isSingle = visibleTabs.length <= 1;\n    this.navScrollableContainer.classList.toggle('is-single', isSingle);\n    this.menuGradient.classList.toggle('hide', isSingle);\n    if(changeActive && visibleTabs.length) {\n      this.selectTab(this.mediaTabs.indexOf(visibleTabs[0]), false);\n    }\n  }\n\n  public async load(single = false, justLoad = false, side: 'top' | 'bottom' = 'bottom') {\n    const peerId = this.searchContext.peerId;\n    this.log('load', single, peerId, this.loadPromises);\n    const middleware = this.middleware.get();\n\n    if(this.firstLoad) {\n      await (this.loadFirstTimePromise ??= this.loadFirstTime());\n      if(!middleware()) {\n        return;\n      }\n\n      this.loadFirstTimePromise = undefined;\n      this.firstLoad = false;\n    }\n\n    let toLoad = single ? [this.mediaTab] : this.mediaTabs.filter((t) => t !== this.mediaTab);\n    toLoad = toLoad.filter((mediaTab) => {\n      return this.canLoadMediaTab(mediaTab);\n    });\n\n    if(peerId.isUser()) {\n      findAndSplice(toLoad, (mediaTab) => mediaTab.type === 'members');\n    } else {\n      findAndSpliceAll(toLoad, (mediaTab) => mediaTab.type === 'groups');\n    }\n\n    if(!toLoad.length) {\n      return;\n    }\n\n    const loadCount = justLoad ? 50 : Math.round((windowSize.height / 130 | 0) * 3 * 1.25); // that's good for all types\n\n    const promises: Promise<any>[] = toLoad.map((mediaTab) => {\n      return this.loadType({\n        mediaTab,\n        justLoad,\n        loadCount,\n        middleware,\n        side\n      });\n    });\n\n    return Promise.all(promises).catch((err) => {\n      this.log.error('Load error all promises:', err);\n    });\n  }\n\n\n  public setPinnedGifts(gifts: MyStarGift[]) {\n    const giftsTab = this.mediaTabsMap.get('gifts')\n    const menuTabName = giftsTab?.menuTabName\n    if(!menuTabName) return;\n    menuTabName.classList.add('search-super-pinned-gifts-wrap');\n    Promise.all(gifts.slice(0, 3).map(async(gift) => {\n      const div = document.createElement('div');\n      await wrapSticker({\n        div,\n        static: true,\n        doc: gift.sticker,\n        middleware: this.middleware.get(),\n        width: 18,\n        height: 18\n      }).then(({render}) => render);\n      return div\n    })).then((gifts) => {\n      let wrap = menuTabName.querySelector('.search-super-pinned-gifts')\n      if(gifts.length === 0) {\n        wrap?.remove();\n        return;\n      }\n\n      if(!wrap) {\n        wrap = document.createElement('div');\n        wrap.className = 'search-super-pinned-gifts';\n        menuTabName.append(wrap);\n      }\n      wrap.replaceChildren(...gifts);\n    })\n  }\n\n  public async canViewSavedDialogs() {\n    if(this.searchContext.peerId !== rootScope.myId || this.searchContext.threadId || !this.mediaTabsMap.has('savedDialogs')) {\n      return false;\n    }\n\n    try {\n      await this.managers.dialogsStorage.getDialogs({\n        filterId: rootScope.myId\n      });\n\n      return true;\n    } catch(err) {\n      return false;\n    }\n  }\n\n  public canViewSaved() {\n    const {peerId, threadId} = this.searchContext;\n    if(threadId || rootScope.myId === peerId) {\n      return false;\n    }\n\n    return this.managers.appMessagesManager.getHistory({\n      peerId: rootScope.myId,\n      threadId: this.searchContext.peerId,\n      limit: 50\n    }).then((historyResult) => {\n      return !!historyResult.count;\n    }).catch(() => {\n      return false;\n    });\n  }\n\n  public canViewMembers() {\n    const {peerId} = this.searchContext;\n    const isAnyChat = peerId.isAnyChat();\n    if(!isAnyChat || !this.mediaTabsMap.has('members')) return Promise.resolve(false);\n    const chatId = peerId.toChatId();\n    return Promise.all([\n      this.managers.appChatsManager.isBroadcast(chatId),\n      this.managers.appChatsManager.hasRights(chatId, 'view_participants'),\n      this.managers.appChatsManager.isForum(chatId)\n    ]).then(([isBroadcast, hasRights, isForum]) => {\n      return !isBroadcast && hasRights && (!this.searchContext.threadId || !isForum);\n    });\n  }\n\n  public async canViewGroups() {\n    const {peerId} = this.searchContext;\n    if(!peerId.isUser() || !this.mediaTabsMap.has('groups')) return false;\n    const userFull = await this.managers.appProfileManager.getProfile(peerId.toUserId());\n    return !!userFull.common_chats_count;\n  }\n\n  public async canViewStories() {\n    const {peerId, threadId} = this.searchContext;\n    if(!this.mediaTabsMap.has('stories') || threadId/*  || !this.onStoriesLengthChange */) {\n      return false;\n    }\n\n    if(peerId === rootScope.myId) {\n      return false;\n    }\n\n    if(peerId.isUser()) {\n      const promise = this.storiesArchive ?\n        this.managers.appStoriesManager.getStoriesArchive(peerId, 1) :\n        this.managers.appStoriesManager.getPinnedStories(peerId, 1);\n      return promise.then(({count}) => !!count).catch(() => false);\n    }\n\n    const chatFull = await this.managers.appProfileManager.getChatFull(peerId.toChatId());\n    return !!(chatFull as ChatFull.channelFull).pFlags.stories_pinned_available;\n  }\n\n  public async canViewSimilar() {\n    const {peerId} = this.searchContext;\n    if(peerId.isUser()) {\n      return false;\n    }\n\n    try {\n      const messagesChats = await this.managers.appChatsManager.getChannelRecommendations(peerId.toChatId());\n      return !!messagesChats.chats.length;\n    } catch(err) {\n      return false;\n    }\n  }\n\n  public canViewGifts() {\n    return !this.searchContext.threadId && this.mediaTabsMap.has('gifts');\n  }\n\n  public async getProfileTabsData() {\n    const {peerId, threadId} = this.searchContext;\n    if(threadId) {\n      return {};\n    }\n\n    const full = await this.managers.appProfileManager.getProfileByPeerId(peerId);\n    const profile = full as UserFull.userFull | ChatFull.channelFull;\n    return {\n      giftsCount: profile.stargifts_count ?? 0,\n      mainTab: this.useMainProfileTab ? profile.main_tab : undefined\n    };\n  }\n\n  public cleanup() {\n    ++this.mediaFilterChangeId;\n    ++this.mediaCountersRefreshId;\n    ++this.mediaCountersVersion;\n    this.mediaCounters = {};\n    this.onMediaCountersChange?.();\n    this.mediaFilterCommittedState = undefined;\n    this.mediaFilterStagingItemsTab = undefined;\n    const mediaTab = this.mediaTabsMap.get('media');\n    if(mediaTab?.inputFilter && mediaTab.itemsTab) {\n      this.mediaFilterCommittedInputFilter = mediaTab.inputFilter as SearchSuperMediaInputFilter;\n      this.tabs[mediaTab.inputFilter] = mediaTab.itemsTab as HTMLDivElement;\n    }\n    this.loadPromises = {};\n    this.loaded = {};\n    this.loadedChats = false;\n    this.nextRates = {};\n    this.firstLoad = true;\n    this.prevTabId = -1;\n    this.counters = {};\n    this.setMainMediaTab();\n\n    this.lazyLoadQueue.clear();\n\n    this.mediaTabs.forEach((mediaTab) => {\n      const {inputFilter} = mediaTab;\n      if(!inputFilter) {\n        return;\n      }\n\n      this.usedFromHistory[inputFilter] = -1;\n    });\n\n    if(this.selection?.isSelecting) {\n      this.selection.cancelSelection();\n    }\n\n    // * must go to first tab (это костыль)\n    /* const membersTab = this.mediaTabsMap.get('members');\n    if(membersTab) {\n      const tab = this.canViewMembers() ? membersTab : this.mediaTabs[this.mediaTabs.indexOf(membersTab) + 1];\n      this.mediaTab = tab;\n    } */\n\n    this.middleware.clean();\n    this.loadFirstTimePromise = undefined;\n    this.cleanScrollPositions();\n\n    this.membersList = undefined;\n    this.membersParticipantMap = undefined;\n    this.membersMiddlewareHelper?.destroy();\n    this.membersMiddlewareHelper = undefined;\n    this.globalPostsSearch = undefined;\n  }\n\n  public cleanScrollPositions() {\n    this.mediaTabs.forEach((mediaTab) => {\n      mediaTab.scroll = undefined;\n    });\n  }\n\n  public updateScrollDateBadge(canShow: boolean) {\n    const mediaTab = this.mediaTab;\n    if(!canShow || !supportsSharedMediaScrollDate(mediaTab?.type)) {\n      this.scrollDateBadge?.hide();\n      return;\n    }\n\n    this.scrollDateBadge ??= createSharedMediaScrollDateBadge({\n      mount: (element) => this.tabsContainer.before(element),\n      getAnchorTop: () => this.navScrollableContainer.getBoundingClientRect().bottom,\n      getItems: () => {\n        const mediaTab = this.mediaTab;\n        return mediaTab.type === 'stories' ?\n          mediaTab.contentTab.querySelectorAll<HTMLElement>('.stories-album-content .search-super-item[data-timestamp]') :\n          mediaTab.itemsTab.children;\n      }\n    });\n    this.scrollDateBadge.update(true);\n  }\n\n  public cleanupHTML() {\n    this.scrollDateBadge?.reset();\n\n    this.mediaTabs.forEach((tab) => {\n      tab.itemsTab.replaceChildren();\n\n      if(tab.hideOn) {\n        tab.hideOn.classList.add('hide');\n      }\n\n      if(this.hideEmptyTabs) {\n        // tab.menuTab.classList.add('hide');\n        this.container.classList.add('hide');\n        this.container.parentElement.classList.add('search-empty');\n      }\n\n      if(tab.type === 'chats') {\n        return;\n      }\n\n      if(tab.inputFilter && !this.historyStorage[tab.inputFilter]) {\n        const parent = tab.contentTab.parentElement;\n        if(!parent.querySelector('.preloader')) {\n          putPreloader(parent, true);\n        }\n\n        const empty = parent.querySelector('.content-empty');\n        empty?.remove();\n      }\n    });\n\n    this.searchGroupMedia.clear();\n    this.scrollable.scrollPosition = 0;\n  }\n\n  private copySearchContext(newInputFilter: MyInputMessagesFilter, nextRate: number, skipSensitive: boolean) {\n    const context = copy(this.searchContext) as MediaSearchContext;\n    context.inputFilter = {_: newInputFilter};\n    context.nextRate = nextRate;\n    context.skipSensitive = skipSensitive;\n    return context;\n  }\n\n  public setQuery({peerId, query, threadId, historyStorage, folderId, minDate, maxDate, chatType, communityId}: {\n    peerId: PeerId,\n    query?: string,\n    threadId?: number,\n    historyStorage?: AppSearchSuper['historyStorage'],\n    folderId?: number,\n    minDate?: number,\n    maxDate?: number\n  } & Pick<RequestHistoryOptions, 'chatType' | 'communityId'>) {\n    this.searchContext = {\n      peerId,\n      query: query || '',\n      inputFilter: {_: this.mediaTab.inputFilter},\n      threadId,\n      folderId,\n      minDate,\n      maxDate,\n      chatType,\n      communityId\n    };\n\n    this.historyStorage = historyStorage ?? {};\n\n    this.cleanup();\n  }\n\n  public destroy() {\n    this.cleanup();\n    this.listenerSetter.removeAll();\n    this.scrollable.destroy();\n    this.swipeHandler?.removeListeners();\n    this.selection?.cleanup();\n\n    this.scrollStartCallback =\n      this.onChangeTab =\n      this.selectTab =\n      this.searchContextMenu =\n      this.swipeHandler =\n      this.selection =\n      undefined;\n  }\n}\n","import {MAX_ACCOUNTS_FREE, MAX_ACCOUNTS_PREMIUM} from '@lib/accounts/constants';\nimport {i18n, i18n_} from '@lib/langPack';\n\nimport Button from '@components/button';\nimport {IconTsx} from '@components/iconTsx';\n\nexport default function AccountsLimitPopupContent(props: {onCancel: () => void; onSubmit: () => void}) {\n  return (\n    <div>\n      <div class=\"accounts-limit__pin-container\">\n        <img class=\"accounts-limit__pin-image\" src=\"assets/img/accounts-limit-pin-shape.svg\" />\n        <IconTsx class=\"accounts-limit__pin-icon\" icon=\"person_filled\" />\n        <span class=\"accounts-limit__pin-count\">{MAX_ACCOUNTS_FREE}</span>\n      </div>\n\n      <div class=\"accounts-limit__bar\">\n        <div class=\"accounts-limit__bar-left\">{i18n('LimitFree')}</div>\n        <div class=\"accounts-limit__bar-right\">\n          {i18n('LimitPremium')}\n          <span>{MAX_ACCOUNTS_PREMIUM}</span>\n        </div>\n      </div>\n\n      <div class=\"accounts-limit__description\">{i18n_({key: 'MultiAccount.AccountsLimitDescription'})}</div>\n\n      <div class=\"accounts-limit__actions\">\n        {(() => {\n          const cancelButton = Button('popup-button btn primary', {text: 'Cancel'});\n          cancelButton.addEventListener('click', props.onCancel);\n          return cancelButton;\n        })()}\n        {(() => {\n          const increaseLimitButton = Button('popup-button btn primary');\n          increaseLimitButton.append(i18n('IncreaseLimit'), PlusOneSvg() as HTMLElement);\n          increaseLimitButton.addEventListener('click', props.onSubmit);\n\n          return increaseLimitButton;\n        })()}\n      </div>\n    </div>\n  );\n}\n\nfunction PlusOneSvg() {\n  return (\n    <svg width=\"24\" height=\"18\" viewBox=\"0 0 24 18\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <g clip-path=\"url(#clip0_6002_2313)\">\n        <path\n          d=\"M0 6.4C0 4.15979 0 3.03968 0.435974 2.18404C0.819467 1.43139 1.43139 0.819467 2.18404 0.435974C3.03968 0 4.15979 0 6.4 0H17.6C19.8402 0 20.9603 0 21.816 0.435974C22.5686 0.819467 23.1805 1.43139 23.564 2.18404C24 3.03968 24 4.15979 24 6.4V11.6C24 13.8402 24 14.9603 23.564 15.816C23.1805 16.5686 22.5686 17.1805 21.816 17.564C20.9603 18 19.8402 18 17.6 18H6.4C4.15979 18 3.03968 18 2.18404 17.564C1.43139 17.1805 0.819467 16.5686 0.435974 15.816C0 14.9603 0 13.8402 0 11.6V6.4Z\"\n          fill=\"currentColor\"\n        />\n        <path\n          fill-rule=\"evenodd\"\n          clip-rule=\"evenodd\"\n          d=\"M16.165 12.1651H15.5C15.0388 12.1651 14.665 12.539 14.665 13.0001C14.665 13.4613 15.0388 13.8351 15.5 13.8351H17H18.5C18.9612 13.8351 19.335 13.4613 19.335 13.0001C19.335 12.539 18.9612 12.1651 18.5 12.1651H17.835V4.50011C17.835 4.09058 17.538 3.7415 17.1338 3.6759C16.7295 3.6103 16.3374 3.84755 16.2079 4.23606L16.1551 4.39442C15.902 5.15375 15.4755 5.84371 14.9096 6.40968C14.5835 6.73577 14.5835 7.26446 14.9096 7.59055C15.2357 7.91664 15.7643 7.91664 16.0904 7.59055C16.1155 7.56549 16.1404 7.54024 16.165 7.51481V12.1651ZM8 12.8351C7.53884 12.8351 7.165 12.4613 7.165 12.0001V9.83511H5C4.53884 9.83511 4.165 9.46127 4.165 9.00011C4.165 8.53896 4.53884 8.16511 5 8.16511H7.165V6.00011C7.165 5.53896 7.53884 5.16511 8 5.16511C8.46116 5.16511 8.835 5.53896 8.835 6.00011V8.16511H11C11.4612 8.16511 11.835 8.53896 11.835 9.00011C11.835 9.46127 11.4612 9.83511 11 9.83511H8.835V12.0001C8.835 12.4613 8.46116 12.8351 8 12.8351Z\"\n          fill=\"white\"\n        />\n      </g>\n      <defs>\n        <clipPath id=\"clip0_6002_2313\">\n          <rect width=\"24\" height=\"18\" fill=\"white\" />\n        </clipPath>\n      </defs>\n    </svg>\n  );\n}\n","import PopupElement from '@components/popups';\nimport PopupPremium from '@components/popups/premium';\nimport AccountsLimitPopupContent from '@components/sidebarLeft/accountsLimitPopupContent';\n\nexport default class AccountsLimitPopup extends PopupElement {\n  constructor() {\n    super('accounts-limit-popup', {\n      overlayClosable: true,\n      body: true,\n      title: 'LimitReached'\n    });\n\n    this.body.append(AccountsLimitPopupContent({\n      onCancel: () => {\n        this.hide();\n      },\n      onSubmit: () => {\n        this.hide();\n        PopupPremium.show({feature: 'double_limits'});\n      }\n    }) as HTMLElement)\n  }\n}\n","import {onCleanup} from 'solid-js';\n\nexport function useIsCleaned() {\n  let isCleaned = false;\n\n  onCleanup(() => {\n    isCleaned = true;\n  });\n\n  return () => isCleaned;\n}\n","import wrapSticker from '@components/wrappers/sticker';\nimport noop from '@helpers/noop';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {useIsCleaned} from '@hooks/useIsCleaned';\nimport {Document, DocumentAttribute} from '@layer';\nimport type {AppManagers} from '@lib/managers';\nimport LottiePlayer from '@lib/lottie/lottiePlayer';\nimport {createEffect, createResource, createSignal, untrack} from 'solid-js';\n\n\nfunction useStickerRenderer(options: {\n  container: HTMLDivElement;\n  doc: Document.document;\n  color: () => string;\n  size: () => number;\n  dontAnimate?: () => boolean;\n  onFail?: () => void;\n}) {\n  const {container} = options;\n  const [playerToColor, setPlayerToColor] = createSignal<LottiePlayer>();\n\n  createEffect(() => {\n    playerToColor()?.setColor(options.color(), true);\n  });\n\n  createEffect(() => {\n    const size = options.size();\n    const color = untrack(options.color);\n\n    const middleware = createMiddleware().get();\n    const isCleaned = useIsCleaned();\n\n    container.replaceChildren();\n    setPlayerToColor();\n\n    const animate = !options.dontAnimate?.();\n\n    (async() => {\n      try {\n        const promise = await wrapSticker({\n          doc: options.doc,\n          div: container,\n          group: 'none',\n          width: size,\n          height: size,\n          play: animate,\n          loop: animate,\n          withThumb: false,\n          middleware,\n          textColor: color\n        });\n\n        const attribute = options.doc.attributes.find(\n          (attribute) => attribute._ === 'documentAttributeCustomEmoji'\n        ) as DocumentAttribute.documentAttributeCustomEmoji;\n\n        if(attribute?.pFlags.text_color) {\n          const renderResult = await promise.render.catch(noop);\n          if(isCleaned()) return;\n          if(renderResult instanceof LottiePlayer) setPlayerToColor(renderResult);\n        }\n      } catch{\n        if(isCleaned()) return;\n        options.onFail?.();\n      }\n    })();\n  });\n}\n\nexport default function EmojiDocumentIcon(props: {\n  managers: AppManagers;\n  docId: DocId;\n  color: string;\n  size: number;\n  class?: string;\n  dontAnimate?: boolean;\n  onFail?: () => void;\n}) {\n  const container = (<div class={props.class} />) as HTMLDivElement;\n\n  const [doc] = createResource(\n    () => props.docId,\n    (docId) => props.managers.appEmojiManager.getCustomEmojiDocument(docId)\n  );\n\n  createEffect(() => {\n    if(doc.loading) return;\n\n    const loadedDoc = doc.error ? undefined : doc();\n    if(!loadedDoc) {\n      props.onFail?.();\n      return;\n    }\n\n    useStickerRenderer({\n      container,\n      doc: loadedDoc,\n      color: () => props.color,\n      size: () => props.size,\n      dontAnimate: () => props.dontAnimate,\n      onFail: () => props.onFail?.()\n    });\n  });\n\n  return container;\n}\n","import EmojiDocumentIcon from '@components/emojiDocumentIcon';\nimport type {AppManagers} from '@lib/managers';\nimport wrapSingleEmoji from '@lib/richTextProcessor/wrapSingleEmoji';\nimport {Match, onMount, Switch} from 'solid-js';\n\n\nexport default function FolderAnimatedIcon(props: {\n  managers: AppManagers;\n  docId?: DocId;\n  emoji?: string;\n  color: string;\n  size: number;\n  class?: string;\n  onFail?: () => void;\n  dontAnimate?: boolean;\n}) {\n  const Fallback = () => {\n    onMount(() => props.onFail?.());\n    // Keep the div for maintaining the layout\n    return <div class={props.class}></div>;\n  };\n\n  return (\n    <Switch\n      fallback={<Fallback />}\n    >\n      <Match when={props.docId} keyed>\n        {(docId) => (\n          <EmojiDocumentIcon\n            managers={props.managers}\n            docId={docId}\n            color={props.color}\n            size={props.size}\n            class={props.class}\n            dontAnimate={props.dontAnimate}\n            onFail={props.onFail}\n          />\n        )}\n      </Match>\n      <Match when={props.emoji} keyed>\n        {(emoji) => <div class={props.class}>{wrapSingleEmoji(emoji)}</div>}\n      </Match>\n    </Switch>\n  );\n}\n","import {createComputed, createEffect, createMemo, createSignal, Show} from 'solid-js';\nimport {keepMe} from '@helpers/keepMe';\nimport createMiddleware from '@helpers/solid/createMiddleware';\nimport {CustomEmojiRendererElement} from '@lib/customEmoji/renderer';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport Badge from '@components/badge';\nimport {IconTsx} from '@components/iconTsx';\nimport ripple from '@components/ripple';\nimport FolderAnimatedIcon from '@components/sidebarLeft/foldersSidebarContent/folderAnimatedIcon';\nimport {FolderItemPayload} from '@components/sidebarLeft/foldersSidebarContent/types';\n\nkeepMe(ripple);\n\n\ntype FolderItemProps = FolderItemPayload & {\n  ref?: (el: HTMLDivElement | null) => void,\n  class?: string,\n  selected?: boolean,\n  onClick?: () => void\n};\n\nconst ICON_SIZE = 30;\n\nexport default function FolderItem(props: FolderItemProps) {\n  const {rootScope, wrapFolderTitle} = useHotReloadGuard();\n\n  const [failedToFetchIconDoc, setFailedToFetchIconDoc] = createSignal(false);\n\n  const hasNotifications = () => !!props.notifications?.count;\n\n  const hasCustomIcon = () => props.iconDocId || props.emojiIcon;\n  const showCustomIcon = () => hasCustomIcon() && !failedToFetchIconDoc();\n\n  const title = createMemo(() => {\n    if(props.name) return props.name;\n    if(!props.title) return;\n\n    const middleware = createMiddleware().get();\n\n    const span = document.createElement('span');\n    const fragment = wrapFolderTitle(props.title, middleware, true);\n\n    createEffect(() => {\n      const renderer: CustomEmojiRendererElement = span.querySelector('custom-emoji-renderer-element');\n      renderer?.setTextColor(props.selected ? 'primary-color' : 'folders-sidebar-item-color')\n    });\n\n    span.append(fragment);\n\n    return span;\n  });\n\n  createComputed(() => {\n    hasCustomIcon() && setFailedToFetchIconDoc(false);\n  });\n\n  return (\n    <div\n      use:ripple\n      ref={(el) => {\n        props.ref?.(el);\n      }}\n      class=\"folders-sidebar__folder-item\"\n      classList={{\n        [props.class]: !!props.class,\n        'folders-sidebar__folder-item--selected': props.selected\n      }}\n      {...(props.id !== undefined ?\n        {'data-filter-id': props.id} :\n        {}\n      )}\n      onClick={props.onClick}\n    >\n      <Show\n        when={showCustomIcon()}\n        fallback={<IconTsx icon={props.icon} class=\"folders-sidebar__folder-item-icon\" />}\n      >\n        <FolderAnimatedIcon\n          docId={props.iconDocId}\n          emoji={props.emojiIcon}\n          color={props.selected ? 'primary-color' : 'folders-sidebar-item-color'}\n          managers={rootScope.managers}\n          size={ICON_SIZE}\n          class=\"folders-sidebar__folder-item-animated-icon\"\n          onFail={() => setFailedToFetchIconDoc(true)}\n          dontAnimate={props.dontAnimate}\n        />\n      </Show>\n      <Show when={title()}>\n        <div class=\"folders-sidebar__folder-item-name\">{title()}</div>\n      </Show>\n      <Show when={hasNotifications()}>\n        <Badge\n          class=\"folders-sidebar__folder-item-badge\"\n          tag=\"div\"\n          color={props.notifications.muted/*  && !props.selected */ ? 'gray' : 'primary'}\n          size={18}\n        >\n          {'' + props.notifications.count}\n        </Badge>\n      </Show>\n    </div>\n  );\n}\n","import {MessageEntity, TextWithEntities} from '@layer';\nimport parseEntities from '@lib/richTextProcessor/parseEntities';\n\n\nexport type ExtractEmojiFromFilterTitleResult = {\n  text: TextWithEntities.textWithEntities;\n  docId?: DocId;\n  emoji?: string;\n};\n\nfunction canBeRemoved(len: number, entity: MessageEntity.messageEntityCustomEmoji  | MessageEntity.messageEntityEmoji) {\n  return entity.offset === 0 || entity.offset + entity.length === len;\n}\n\nexport default function extractEmojiFromFilterTitle(textWithEntities: TextWithEntities.textWithEntities): ExtractEmojiFromFilterTitleResult {\n  const {text, entities} = textWithEntities;\n\n  const emojis = entities.filter(entity => entity._ === 'messageEntityCustomEmoji');\n  const otherEmojis = parseEntities(text).filter(entity => entity._ === 'messageEntityEmoji');\n  const includedEmojis = emojis.length ? emojis : otherEmojis;\n  const [emojiEntity] = includedEmojis;\n\n  if(includedEmojis.length !== 1 || !canBeRemoved(text.length, emojiEntity)) return {\n    text: textWithEntities\n  };\n\n  const resultingTextWithEntities: TextWithEntities.textWithEntities = {\n    _: 'textWithEntities',\n    text: (text.slice(0, emojiEntity.offset) + text.slice(emojiEntity.offset + emojiEntity.length)).trim(),\n    entities: []\n  };\n\n  let docId: DocId;\n  let emoji: string;\n\n  if(emojiEntity._ === 'messageEntityCustomEmoji') docId = emojiEntity.document_id;\n  if(emojiEntity._ === 'messageEntityEmoji') emoji = text.slice(emojiEntity.offset, emojiEntity.offset + emojiEntity.length);\n\n  return {\n    text: resultingTextWithEntities,\n    docId,\n    emoji\n  };\n}\n","\nimport {FOLDER_ID_ALL} from '@appManagers/constants';\nimport type {AppManagers} from '@lib/managers';\nimport {MyDialogFilter} from '@lib/storages/filters';\nimport {DialogFilter} from '@layer';\nimport assumeType from '@helpers/assumeType';\n\nimport {FolderItemPayload} from '@components/sidebarLeft/foldersSidebarContent/types';\nimport extractEmojiFromFilterTitle, {ExtractEmojiFromFilterTitleResult} from '@components/sidebarLeft/foldersSidebarContent/extractEmojiFromFilterTitle';\nimport {i18n} from '@lib/langPack';\n\nexport function getFolderTitle(filter: MyDialogFilter) {\n  let cleanTitle: ExtractEmojiFromFilterTitleResult;\n\n  const titleRest = filter.id === FOLDER_ID_ALL ? {\n    name: i18n('FilterAllChats')\n  } : {\n    title: (cleanTitle = extractEmojiFromFilterTitle(filter.title)).text\n  };\n\n  const iconRest: Pick<FolderItemPayload, 'iconDocId' | 'emojiIcon'> = {\n    iconDocId: cleanTitle?.docId,\n    emojiIcon: cleanTitle?.emoji\n  };\n\n  return {\n    icon: getIconForFilter(filter),\n    ...titleRest,\n    ...iconRest,\n    dontAnimate: !!filter?.pFlags?.title_noanimate\n  };\n}\n\nexport function getIconForFilter(filter: MyDialogFilter): Icon {\n  if(filter.id === FOLDER_ID_ALL) return 'round_chats_filled';\n  const matchedIcons: Icon[] = [];\n\n  assumeType<DialogFilter.dialogFilter>(filter);\n  if(filter.pFlags.contacts) matchedIcons.push('person_filled');\n  if(filter.pFlags.bots) matchedIcons.push('bot_filled');\n  if(filter.pFlags.broadcasts) matchedIcons.push('channel_filled');\n  if(filter.pFlags.groups) matchedIcons.push('group_filled');\n  if(filter.pFlags.non_contacts) matchedIcons.push('noncontacts');\n\n  if(matchedIcons.length === 1) return matchedIcons[0];\n  return 'limit_folders';\n}\n","import {Accessor, createEffect, createSelector, createSignal, For, onCleanup, onMount, Show} from 'solid-js';\nimport {createStore} from 'solid-js/store';\nimport {render} from 'solid-js/web';\nimport createFolderContextMenu from '@helpers/dom/createFolderContextMenu';\nimport {keepMe} from '@helpers/keepMe';\nimport {Middleware} from '@helpers/middleware';\nimport pause from '@helpers/schedulers/pause';\nimport Animated from '@helpers/solid/animations';\nimport classNames from '@helpers/string/classNames';\nimport {logger, LogTypes} from '@lib/logger';\nimport {REAL_FOLDERS} from '@appManagers/constants';\nimport {useHotReloadGuard} from '@lib/solidjs/hotReloadGuard';\nimport type SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport useHasFoldersSidebar from '@stores/foldersSidebar';\nimport useFolders from '@stores/folders';\nimport appChatBackground from '@components/chat/bubbles/chatBackground';\nimport {IconTsx} from '@components/iconTsx';\nimport ripple from '@components/ripple';\nimport Scrollable from '@components/scrollable2';\nimport FolderItem from '@components/sidebarLeft/foldersSidebarContent/folderItem';\nimport {getFolderTitle} from '@components/sidebarLeft/foldersSidebarContent/utils';\n\nkeepMe(ripple);\n\nconst log = logger('FoldersSidebarContent', LogTypes.Debug);\n\nexport function FoldersSidebarContent(props: {\n  allNotificationsCount: Accessor<number>\n}) {\n  log.debug('Rendering FoldersSidebarContent');\n  onCleanup(() => log.debug('Cleaning up FoldersSidebarContent'));\n\n  const {\n    rootScope,\n    appSidebarLeft,\n    AppChatFoldersTab,\n    AppEditFolderTab,\n    i18n\n  } = useHotReloadGuard();\n\n  const {selectedFolderId, onClick, folderItems} = useFolders();\n  const [addFoldersOffset, setAddFoldersOffset] = createSignal(0);\n  const [canShowAddFolders, setCanShowAddFolders] = createSignal(false);\n  const [menuTarget, setMenuTarget] = createSignal<HTMLDivElement>();\n\n  const showAddFolders = () => canShowAddFolders() &&\n    selectedFolderId() &&\n    !REAL_FOLDERS.has(selectedFolderId()) &&\n    folderItems.find((item) => item.id === selectedFolderId())?.chatsCount === 0;\n\n  const [folderItemRefs, setFolderItemRefs] = createStore<Record<number, HTMLDivElement>>({});\n  const isSelected = createSelector(selectedFolderId);\n\n  // Tracks whether a gradient renderer is currently active. When false (image-only wallpapers)\n  // we fall back to backdrop-filter via a CSS class so the bar still has some translucency.\n  const [hasGradient, setHasGradient] = createSignal(false);\n  // Night-style dark patterns darken the visible chat via a black mask, but the mirror copies only\n  // the (bright) raw gradient — so the bar needs an extra-dark tint to match. Tinted/light don't.\n  const [isDarkPattern, setIsDarkPattern] = createSignal(false);\n  let backgroundCanvas: HTMLCanvasElement;\n\n  let folderItemsContainer: HTMLDivElement;\n\n  async function _onClick(folderId: number) {\n    const index = folderItems.findIndex(({filter}) => filter.id === folderId);\n    if(!(await onClick()(index))) {\n      return false;\n    }\n\n    const hasSomethingOpen = appSidebarLeft.hasSomethingOpenInside();\n    appSidebarLeft.closeEverythingInside();\n    hasSomethingOpen && await pause(300);\n  }\n\n  createEffect(() => {\n    const _menuTarget = menuTarget();\n    if(!_menuTarget) return;\n\n    appSidebarLeft.createToolsMenu(_menuTarget, {top: 8, left: 48});\n    _menuTarget.classList.add('sidebar-tools-button', 'is-visible');\n  });\n\n  let contextMenu: ReturnType<typeof createFolderContextMenu>;\n  onMount(() => {\n    contextMenu = createFolderContextMenu({\n      appSidebarLeft,\n      AppChatFoldersTab,\n      AppEditFolderTab,\n      managers: rootScope.managers,\n      className: 'folders-sidebar__folder-item',\n      listenTo: folderItemsContainer\n    });\n\n    // Mirror the chat-background gradient into our own canvas — cheap stand-in for\n    // backdrop-filter: blur(40px). The bar always sits over the chat background, so the visible\n    // result of a heavy blur over that area is mathematically close to the gradient itself\n    // (the high-frequency pattern blurs to a near-constant tint that we approximate via the\n    // dark overlay). Falls back to backdrop-filter when no gradient is active.\n    let detachMirror: (() => void) | undefined;\n    const unsubscribeRenderer = appChatBackground.onActiveGradientRendererChange((renderer, meta) => {\n      detachMirror?.();\n      detachMirror = undefined;\n      if(renderer && backgroundCanvas) {\n        detachMirror = renderer.attachMirror(backgroundCanvas);\n        setHasGradient(true);\n      } else {\n        setHasGradient(false);\n      }\n      setIsDarkPattern(!!meta?.isDarkMaskPattern);\n    });\n\n    onCleanup(() => {\n      contextMenu.destroy();\n      unsubscribeRenderer();\n      detachMirror?.();\n    });\n  });\n\n  const updateCanShowAddFolders = () => {\n    const selectedItem = folderItemRefs[selectedFolderId()];\n    if(!selectedItem) return;\n\n    const containerRect = folderItemsContainer.getBoundingClientRect();\n    const itemRect = selectedItem.getBoundingClientRect();\n    const offset = itemRect.top + itemRect.height / 2 - containerRect.top;\n    const MARGIN_PX = 50;\n    setCanShowAddFolders(offset > MARGIN_PX && offset < containerRect.height - MARGIN_PX);\n    setAddFoldersOffset(offset);\n  };\n\n  createEffect(updateCanShowAddFolders);\n\n  let openingChatFolders = false;\n  return (\n    <>\n      <div class={classNames(\n        'folders-sidebar__background',\n        !hasGradient() && 'folders-sidebar__background--no-gradient',\n        isDarkPattern() && 'folders-sidebar__background--dark-pattern'\n      )}>\n        <canvas ref={backgroundCanvas} class=\"folders-sidebar__background-gradient\" />\n        <div class=\"folders-sidebar__background-tint\" />\n      </div>\n      <FolderItem\n        ref={setMenuTarget}\n        class=\"folders-sidebar__menu-button is-first\"\n        icon=\"menu\"\n        notifications={{\n          count: props.allNotificationsCount(),\n          muted: false\n        }}\n      />\n\n      <div class=\"folders-sidebar__scrollable-position\">\n        <Scrollable\n          ref={folderItemsContainer}\n          class=\"folders-sidebar__scrollable no-scrollbar\"\n          onScroll={updateCanShowAddFolders}\n          withBorders=\"both\"\n        >\n          <For each={folderItems}>{(folderItem) => {\n            const {id} = folderItem;\n\n            onCleanup(() => {\n              setFolderItemRefs({[id]: undefined});\n            });\n\n            return (\n              <FolderItem\n                {...folderItem}\n                {...getFolderTitle(folderItem.filter)}\n                ref={(el) => setFolderItemRefs({[id]: el})}\n                selected={isSelected(id)}\n                onClick={() => _onClick(id)}\n              />\n            );\n          }}</For>\n        </Scrollable>\n\n        <Animated type=\"cross-fade\" mode=\"add-remove\">\n          {showAddFolders() && <div\n            use:ripple\n            class=\"folders-sidebar__add-folders-button\"\n            onClick={() => contextMenu.openSettingsForFilter(selectedFolderId())}\n            style={{\n              '--offset': addFoldersOffset()\n            }}\n          >\n            <IconTsx icon=\"plus\" class=\"folders-sidebar__add-folders-button-icon\" />\n            <div class=\"folders-sidebar__add-folders-button-name\">\n              {i18n('ChatList.Filter.Include.AddChat')}\n            </div>\n          </div>}\n        </Animated>\n      </div>\n\n      <FolderItem\n        class=\"folders-sidebar__menu-button is-last\"\n        icon=\"equalizer\"\n        onClick={() => {\n          if(openingChatFolders || appSidebarLeft.getTab(AppChatFoldersTab)) return;\n          openingChatFolders = true;\n          appSidebarLeft.closeTabsBefore(() => {\n            const tab = appSidebarLeft.createTab(AppChatFoldersTab);\n            tab.open(AppChatFoldersTab.getInitArgs()).finally(() => {\n              openingChatFolders = false;\n            });\n          });\n        }}\n      />\n    </>\n  );\n}\n\nexport function renderFoldersSidebarContent(\n  parentEl: HTMLElement,\n  allNotificationsCount: Accessor<number>,\n  HotReloadGuardProvider: typeof SolidJSHotReloadGuardProvider,\n  middleware: Middleware\n) {\n  const [hasFoldersSidebar] = useHasFoldersSidebar();\n\n  const foldersSidebar = document.createElement('div');\n  foldersSidebar.id = 'folders-sidebar';\n  foldersSidebar.className = 'folders-sidebar sidebar-left-common';\n  parentEl.insertBefore(foldersSidebar, parentEl.firstChild);\n\n  const dispose = render(() => (\n    <HotReloadGuardProvider>\n      <Show when={hasFoldersSidebar()}>\n        <FoldersSidebarContent\n          allNotificationsCount={allNotificationsCount}\n        />\n      </Show>\n    </HotReloadGuardProvider>\n  ), foldersSidebar);\n\n  middleware.onDestroy(() => {\n    dispose();\n    foldersSidebar.remove();\n  });\n}\n","import pause from '@helpers/schedulers/pause';\nimport {AppManagers} from '@lib/managers';\nimport PopupElement from '@components/popups';\nimport SidebarSlider, {SidebarSliderOptions} from '@components/slider';\n\nclass SettingsSlider extends SidebarSlider {\n  constructor(options: SidebarSliderOptions & {managers: AppManagers}) {\n    super(options);\n    this.managers = options.managers;\n  }\n}\n\nexport default class SettingsSliderPopup extends PopupElement {\n  slider: SidebarSlider;\n\n  constructor(managers: AppManagers) {\n    super('settings-slider-popup', {\n      overlayClosable: true,\n      body: true,\n      title: false\n    });\n\n    this.middlewareHelper.onDestroy(() => {\n      pause(200).then(() => {\n        this.slider.closeAllTabs();\n      }); // wait for popup to close\n    });\n\n    const element = document.createElement('div');\n    element.classList.add('settings-slider-popup__height-limit');\n    const sliderEl = document.createElement('div');\n    sliderEl.classList.add('sidebar-slider', 'tabs-container');\n\n    // const scrollable = new Scrollable();\n\n    element.append(sliderEl);\n\n    this.slider = new SettingsSlider({\n      navigationType: 'settings-popup',\n      sidebarEl: element,\n      managers\n    });\n\n    this.slider.onTabsCountChange = () => {\n      if(this.slider.hasTabsInNavigation()) return;\n      this.hide();\n    };\n\n    this.body.append(element);\n  }\n}\n","import {bindActiveWindowListener} from '@helpers/appWindow';\n\nconst positionKeyRegexp = /^key[a-zA-Z]$/i;\n\nfunction matchNonMetaKey(event: KeyboardEvent, key: string) {\n  if(positionKeyRegexp.test(key)) return event.code.toLowerCase() === key.toLowerCase();\n\n  return event.key.toLowerCase() === key.toLowerCase();\n}\n\nfunction matchComboKey(event: KeyboardEvent, key: string) {\n  return (\n    (key === 'ctrl' && event.ctrlKey) ||\n    (key === 'shift' && event.shiftKey) ||\n    (key === 'alt' && event.altKey) ||\n    (key === 'meta' && event.metaKey) ||\n    (key === 'anymeta' && (event.ctrlKey || event.shiftKey || event.altKey || event.metaKey)) ||\n    matchNonMetaKey(event, key)\n  );\n}\n\nexport function addShortcutListener(combos: string[], callback: (combo: string, event: KeyboardEvent) => void, preventByDefault = true) {\n  const listener = (event: KeyboardEvent) => {\n    const pairs = combos\n    .map((combo) => [combo, combo.toLowerCase().split('+')] as const)\n    .sort((a, b) => b[1].length - a[1].length);\n\n    for(const [combo, keys] of pairs) {\n      const isComboMatched = keys.every((key) => matchComboKey(event, key));\n\n      if(isComboMatched) {\n        preventByDefault && event.preventDefault();\n        callback(combo, event);\n        break;\n      }\n    }\n  };\n\n  // Follow the active app window so shortcuts keep firing when the client is popped into a Document\n  // PiP window (its key events fire on the PiP document, not the tab's).\n  return bindActiveWindowListener((w) => w.document, 'keydown', listener);\n}\n","import PasscodeLockScreenController from '@components/passcodeLock/passcodeLockScreenController';\nimport showTooltip from '@components/tooltip';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {i18n} from '@lib/langPack';\nimport {createEffect, createRoot, createSignal, onCleanup} from 'solid-js';\n\n\nconst LockIcon = () => {\n  return (\n    <svg width=\"23\" height=\"22\" viewBox=\"0 0 23 22\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n      <path d=\"M1.5 13.8C1.5 12.1198 1.5 11.2798 1.82698 10.638C2.1146 10.0735 2.57354 9.6146 3.13803 9.32698C3.77976 9 4.61984 9 6.3 9H11.7C13.3802 9 14.2202 9 14.862 9.32698C15.4265 9.6146 15.8854 10.0735 16.173 10.638C16.5 11.2798 16.5 12.1198 16.5 13.8V16.2C16.5 17.8802 16.5 18.7202 16.173 19.362C15.8854 19.9265 15.4265 20.3854 14.862 20.673C14.2202 21 13.3802 21 11.7 21H6.3C4.61984 21 3.77976 21 3.13803 20.673C2.57354 20.3854 2.1146 19.9265 1.82698 19.362C1.5 18.7202 1.5 17.8802 1.5 16.2V13.8Z\" stroke=\"currentColor\" stroke-width=\"2\"/>\n      <path class=\"lock-icon-shackle\" d=\"M20.5 8C20.5 8.55228 20.9477 9 21.5 9C22.0523 9 22.5 8.55228 22.5 8H20.5ZM13.5 8V5.5H11.5V8H13.5ZM20.5 5.5V8H22.5V5.5H20.5ZM17 2C18.933 2 20.5 3.567 20.5 5.5H22.5C22.5 2.46243 20.0376 0 17 0V2ZM13.5 5.5C13.5 3.567 15.067 2 17 2V0C13.9624 0 11.5 2.46243 11.5 5.5H13.5Z\" fill=\"currentColor\"/>\n    </svg>\n  )\n};\n\nconst LockButton = () => {\n  let button: HTMLButtonElement;\n  let iconWrapper: HTMLSpanElement;\n\n  let tooltipShowTimeout: number;\n\n  const [isTooltipVisible, setIsTooltipVisible] = createSignal(false);\n\n  const clearTooltipVisible = () => {\n    setIsTooltipVisible(false);\n    window.clearTimeout(tooltipShowTimeout);\n    tooltipShowTimeout = undefined;\n  };\n\n  createEffect(() => {\n    if(!isTooltipVisible()) return;\n\n    const {close} = showTooltip({\n      element: button,\n      mountOn: button.parentElement,\n      vertical: 'bottom',\n      textElement: i18n('PasscodeLock.TapToLock'),\n      onClose: () => {},\n      lighter: true\n    });\n\n    onCleanup(() => {\n      close();\n    });\n  });\n\n  <button\n    ref={button}\n    class=\"btn-icon sidebar-lock-button\"\n    onClick={() => {\n      PasscodeLockScreenController.lock(iconWrapper, () => {\n        apiManagerProxy.lock();\n        clearTooltipVisible();\n      });\n      // PasscodeLockScreenController.lockOtherTabs();\n    }}\n    onMouseEnter={() => {\n      tooltipShowTimeout = window.setTimeout(() => {\n        setIsTooltipVisible(true);\n      }, 500);\n    }}\n    onMouseLeave={() => {\n      clearTooltipVisible();\n    }}\n  >\n    <span ref={iconWrapper} class=\"sidebar-lock-button-icon\">\n      <LockIcon />\n    </span>\n  </button>\n\n  return button;\n};\n\nconst createLockButton = () => {\n  let dispose: () => void;\n\n  const element = createRoot((_dispose) => {\n    dispose = _dispose;\n    return LockButton();\n  });\n\n  return {element, dispose};\n};\n\nexport default createLockButton;\n","import {createEffect, createMemo, createRenderEffect, onCleanup} from 'solid-js';\nimport type {RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport defineSolidElement, {PassedProps} from '@lib/solidjs/defineSolidElement';\nimport {ButtonMenuItemOptions} from '@components/buttonMenu';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport styles from '@components/chatTypeMenu/styles.module.scss';\n\nif(import.meta.hot) import.meta.hot.accept();\n\n\ntype ChatType = RequestHistoryOptions['chatType'];\n\ntype Props = {\n  selected?: ChatType;\n  hidden?: boolean;\n  onChange?: (type: ChatType) => void;\n};\n\nconst langKeyMap: Record<ChatType, LangPackKey> = {\n  'all': 'AllChats',\n  'users': 'UsersOnly',\n  'groups': 'GroupsOnly',\n  'channels': 'ChannelsOnly'\n};\n\nconst keys: ChatType[] = ['all', 'users', 'groups', 'channels'];\n\nconst ChatTypeMenu = defineSolidElement({\n  name: 'chat-type-menu',\n  component: (props: PassedProps<Props>) => {\n    const selected = createMemo(() => props.selected || 'all');\n\n    const options: ButtonMenuItemOptions[] = keys.map(key => ({\n      id: key,\n      emptyIcon: true,\n      text: langKeyMap[key],\n      onClick: () => {\n        props.selected = key;\n        props.onChange?.(key);\n      }\n    }));\n\n    createEffect(() => {\n      const option = options.find(({id}) => id === selected());\n      if(!option) return;\n\n      option.icon = 'check';\n      onCleanup(() => {\n        option.icon = undefined;\n      });\n    });\n\n    const span = <span\n      class={`primary checkable-button-menu ${styles.ButtonMenu}`}\n      classList={{\n        [styles.hidden]: !!props.hidden\n      }}\n    >{i18n(langKeyMap[selected()])}</span> as HTMLSpanElement;\n\n    const buttonMenu = ButtonMenuToggle({\n      container: span,\n      buttons: options,\n      direction: 'bottom-left',\n      onOpen: (_, element) => {\n        element.style.bottom = 'unset';\n      }\n    });\n\n    return <>{buttonMenu}</>;\n  }\n});\n\nexport default ChatTypeMenu;\n","import {Show} from 'solid-js';\nimport {i18n} from '@lib/langPack';\nimport lottieLoader from '@lib/lottie/lottieLoader';\nimport defineSolidElement, {PassedProps} from '@lib/solidjs/defineSolidElement';\nimport LottieAnimation from '@components/lottieAnimation';\nimport ripple from '@components/ripple';\nimport styles from '@components/emptySearchPlaceholder/styles.module.scss';\nripple;\n\nif(import.meta.hot) import.meta.hot.accept();\n\n\ntype Props = {\n  onAllChats?: () => void;\n};\n\nconst EmptySearchPlaceholder = defineSolidElement({\n  name: 'empty-search-placeholder',\n  component: (props: PassedProps<Props>) => {\n    props.element.classList.add(styles.Container);\n\n    return (\n      <>\n        <LottieAnimation\n          class={styles.LottieAnimation}\n          size={156}\n          lottieLoader={lottieLoader}\n          restartOnClick\n          name=\"UtyanSearch\"\n        />\n\n        <div class={styles.NoResults}>\n          <div class={styles.NoResultsTitle}>{i18n('NoResultsTitle')}</div>\n          <div class={styles.NoResultsSubtitle}>{i18n('NoResultsSubtitle')}</div>\n        </div>\n\n\n        <Show when={props.onAllChats}>\n          <button\n            use:ripple\n            class={`btn primary ${styles.ActionButton}`}\n            onClick={props.onAllChats}\n          >\n            {i18n('SearchInAllChats')}\n          </button>\n        </Show>\n      </>\n    );\n  }\n});\n\nexport default EmptySearchPlaceholder;\n","import filterUnique from '@helpers/array/filterUnique';\nimport flatten from '@helpers/array/flatten';\nimport cloneDOMRect from '@helpers/dom/cloneDOMRect';\nimport {AccountEmojiStatuses, EmojiStatus} from '@layer';\nimport {AppManagers} from '@lib/managers';\nimport {EmoticonsDropdown} from '@components/emoticonsDropdown';\nimport EmojiTab from '@components/emoticonsDropdown/tabs/emoji';\nimport Icon, {getIconContent} from '@components/icon';\nimport {getOverlayRoot} from '@helpers/appWindow';\n\nconst openPickers = new WeakMap<HTMLElement, EmoticonsDropdown>();\n\nexport function openEmojiStatusPicker(options: {\n  managers: AppManagers\n  anchorElement: HTMLElement\n  onChosen?: () => void\n}) {\n  const {managers, anchorElement} = options\n\n  const openPicker = openPickers.get(anchorElement);\n  if(openPicker) {\n    openPicker.toggle(false);\n    return;\n  }\n\n  const emojiTab = new EmojiTab({\n    noRegularEmoji: true,\n    managers: managers,\n    mainSets: () => {\n      const defaultStatuses = managers.appStickersManager.getLocalStickerSet('inputStickerSetEmojiDefaultStatuses')\n      .then((stickerSet) => {\n        return stickerSet.documents.map((doc) => doc.id);\n      });\n\n      const convertEmojiStatuses = (emojiStatuses: AccountEmojiStatuses) => {\n        return (emojiStatuses as AccountEmojiStatuses.accountEmojiStatuses)\n        .statuses\n        .map((status) => (status as EmojiStatus.emojiStatus).document_id)\n        .filter(Boolean);\n      };\n\n      return [\n        Promise.all([\n          defaultStatuses,\n          managers.appUsersManager.getRecentEmojiStatuses().then(convertEmojiStatuses),\n          managers.appUsersManager.getDefaultEmojiStatuses().then(convertEmojiStatuses),\n          managers.appEmojiManager.getRecentEmojis('custom')\n        ]).then((arrays) => {\n          return filterUnique(flatten(arrays));\n        })\n      ];\n    },\n    onClick: async(emoji) => {\n      emoticonsDropdown.toggle(false);\n\n      const noStatus = getIconContent('star') === emoji.emoji;\n      let emojiStatus: EmojiStatus;\n      if(noStatus) {\n        emojiStatus = {\n          _: 'emojiStatusEmpty'\n        };\n      } else {\n        emojiStatus = {\n          _: 'emojiStatus',\n          document_id: emoji.docId\n        };\n\n        options.onChosen?.()\n      }\n\n      managers.appUsersManager.updateEmojiStatus(emojiStatus);\n    },\n    canHaveEmojiTimer: true\n  });\n\n  const emoticonsDropdown = new EmoticonsDropdown({\n    tabsToRender: [emojiTab],\n    customParentElement: getOverlayRoot,\n    suppressOutClick: true,\n    getOpenPosition: () => {\n      const rect = anchorElement.getBoundingClientRect();\n      const cloned = cloneDOMRect(rect);\n      cloned.left = rect.left + rect.width / 2;\n      cloned.top = rect.top + rect.height / 2;\n      return cloned;\n    }\n  });\n\n  const textColor = 'primary-color';\n\n  emoticonsDropdown.setTextColor(textColor);\n\n  openPickers.set(anchorElement, emoticonsDropdown);\n\n  emoticonsDropdown.addEventListener('closed', () => {\n    openPickers.delete(anchorElement);\n    emoticonsDropdown.hideAndDestroy();\n  });\n\n  emoticonsDropdown.onButtonClick();\n\n  emojiTab.initPromise.then(() => {\n    const emojiElement = Icon('star', 'super-emoji-premium-icon');\n    emojiElement.style.color = `var(--${textColor})`;\n\n    const category = emojiTab.getCustomCategory();\n\n    emojiTab.addEmojiToCategory({\n      category,\n      element: emojiElement,\n      batch: false,\n      prepend: true\n      // active: !iconEmojiId\n    });\n\n    // if(iconEmojiId) {\n    //   emojiTab.setActive({docId: iconEmojiId, emoji: ''});\n    // }\n  });\n}\n","import {createEffect, createRoot, createSignal, on} from 'solid-js';\nimport appImManager from '@lib/appImManager';\nimport rootScope from '@lib/rootScope';\nimport {createSearchGroup, SearchGroup} from '@components/searchGroup';\nimport Scrollable, {ScrollableX} from '@components/scrollable';\nimport InputSearch from '@components/inputSearch';\nimport SidebarSlider, {SliderSuperTab} from '@components/slider';\nimport TransitionSlider from '@components/transition';\nimport AppSearchSuper, {SearchSuperMediaType} from '@components/appSearchSuper';\nimport {DateData, fillTipDates} from '@helpers/date';\nimport {MOUNT_CLASS_TO} from '@config/debug';\nimport {AppSettingsTab} from '@components/solidJsTabs';\nimport {AppNewChannelTab} from '@components/solidJsTabs/tabs';\nimport {AppContactsTab} from '@components/solidJsTabs/tabs';\nimport {AppArchivedTab} from '@components/solidJsTabs/tabs';\nimport createNewGroupTab from '@components/sidebarLeft/tabs/createNewGroupTab';\nimport I18n, {i18n} from '@lib/langPack';\nimport ButtonMenu, {ButtonMenuItemOptions, ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';\nimport {IS_APPLE, IS_MOBILE_SAFARI} from '@environment/userAgent';\nimport appNavigationController, {NavigationItem} from '@components/appNavigationController';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport findUpTag from '@helpers/dom/findUpTag';\nimport App from '@config/app';\nimport ButtonMenuToggle from '@components/buttonMenuToggle';\nimport sessionStorage from '@lib/sessionStorage';\nimport {attachClickEvent, CLICK_EVENT_NAME, simulateClickEvent} from '@helpers/dom/clickEvent';\nimport cancelEvent from '@helpers/dom/cancelEvent';\nimport ButtonIcon from '@components/buttonIcon';\nimport confirmationPopup from '@components/confirmationPopup';\nimport {replaceButtonIcon} from '@components/button';\nimport noop from '@helpers/noop';\nimport ripple from '@components/ripple';\nimport indexOfAndSplice from '@helpers/array/indexOfAndSplice';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport formatNumber from '@helpers/number/formatNumber';\nimport {AppManagers} from '@lib/managers';\nimport themeController from '@helpers/themeController';\nimport contextMenuController from '@helpers/contextMenuController';\nimport appDialogsManager, {DIALOG_LIST_ELEMENT_TAG} from '@lib/appDialogsManager';\nimport apiManagerProxy from '@lib/apiManagerProxy';\nimport {FOLDER_ID_ARCHIVE, TEST_NO_STORIES} from '@appManagers/constants';\nimport mediaSizes from '@helpers/mediaSizes';\nimport updateColumnWidths, {setOpenTabsLeftSidebar} from '@helpers/updateColumnWidths';\nimport installColumnResize from '@helpers/installColumnResize';\nimport {doubleRaf, fastRaf} from '@helpers/schedulers';\nimport {getInstallPrompt} from '@helpers/dom/installPrompt';\nimport DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED from '@environment/documentPictureInPictureSupport';\nimport openClientPip, {closeClientPip, isClientPipOpen} from '@components/clientPip';\nimport liteMode from '@helpers/liteMode';\nimport {AppPowerSavingTab} from '@components/solidJsTabs/tabs';\nimport {AppMyStoriesTab} from '@components/solidJsTabs/tabs';\nimport Icon from '@components/icon';\nimport AppSelectPeers from '@components/appSelectPeers';\nimport setBadgeContent from '@helpers/setBadgeContent';\nimport createBadge from '@helpers/createBadge';\nimport {MyDocument} from '@appManagers/appDocsManager';\nimport getAttachMenuBotIcon from '@appManagers/utils/attachMenuBots/getAttachMenuBotIcon';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport wrapUrl from '@lib/richTextProcessor/wrapUrl';\nimport flatten from '@helpers/array/flatten';\nimport {AttachMenuBot, EmojiStatus, User} from '@layer';\nimport {Middleware, MiddlewareHelper} from '@helpers/middleware';\nimport wrapEmojiStatus from '@components/wrappers/emojiStatus';\nimport {makeMediaSize} from '@helpers/mediaSize';\nimport ReactionElement from '@components/chat/reaction';\nimport setBlankToAnchor from '@lib/richTextProcessor/setBlankToAnchor';\nimport AccountController from '@lib/accounts/accountController';\nimport {ActiveAccountNumber} from '@lib/accounts/types';\nimport {MAX_ACCOUNTS, MAX_ACCOUNTS_FREE} from '@lib/accounts/constants';\nimport {getCurrentAccount} from '@lib/accounts/getCurrentAccount';\nimport {createProxiedManagersForAccount} from '@lib/getProxiedManagers';\nimport limitSymbols from '@helpers/string/limitSymbols';\nimport filterAsync from '@helpers/array/filterAsync';\nimport pause from '@helpers/schedulers/pause';\nimport AccountsLimitPopup from '@components/sidebarLeft/accountsLimitPopup';\nimport {changeAccount} from '@lib/accounts/changeAccount';\nimport uiNotificationsManager from '@lib/uiNotificationsManager';\nimport {renderFoldersSidebarContent} from '@components/sidebarLeft/foldersSidebarContent';\nimport SolidJSHotReloadGuardProvider from '@lib/solidjs/hotReloadGuardProvider';\nimport {AppChatFoldersTab} from '@components/solidJsTabs/tabs';\nimport {SliderSuperTabConstructable} from '@components/sliderTab';\nimport SettingsSliderPopup from '@components/sidebarLeft/settingsSliderPopup';\nimport {AppEditFolderTab} from '@components/solidJsTabs/tabs';\nimport {addShortcutListener} from '@helpers/shortcutListener';\nimport tsNow from '@helpers/tsNow';\nimport {toastNew} from '@components/toast';\nimport DeferredIsUsingPasscode from '@lib/passcode/deferredIsUsingPasscode';\nimport {saveEncryptionKeyForHandoff} from '@lib/passcode/keyHandoff';\nimport createLockButton from '@components/sidebarLeft/lockButton';\nimport createSubmenuTrigger, {CreateSubmenuArgs} from '@components/createSubmenuTrigger';\nimport ChatTypeMenu from '@components/chatTypeMenu';\nimport {RequestHistoryOptions} from '@appManagers/appMessagesManager';\nimport EmptySearchPlaceholder from '@components/emptySearchPlaceholder';\nimport useHasFoldersSidebar, {\n  useIsSidebarCollapsed,\n  useHasOpenLeftTabs,\n  useIsLeftSearchActive,\n  useFoldersSidebarShown\n} from '@stores/foldersSidebar';\nimport isObject from '@helpers/object/isObject';\nimport {useAppSettings} from '@stores/appSettings';\nimport {useCollapsedCommunityDialogsKey} from '@stores/communities';\nimport {openEmojiStatusPicker} from '@components/sidebarLeft/emojiStatusPicker';\nimport IS_CONFERENCE_CALL_SUPPORTED from '@environment/conferenceCallSupport';\n\nexport const LEFT_COLUMN_ACTIVE_CLASSNAME = 'is-left-column-shown';\n\ntype SearchInitResult = {\n  open: (focus?: boolean) => void;\n  openWithPeerId: (peerId: PeerId) => void;\n  close: () => void;\n}\n\nexport class AppSidebarLeft extends SidebarSlider {\n  private chatListContainer: HTMLElement;\n  private buttonsContainer: HTMLElement;\n  private toolsBtn: HTMLElement;\n  private backBtn: HTMLButtonElement;\n  public inputSearch: InputSearch;\n\n  public archivedCount: HTMLSpanElement;\n  private totalNotificationsCount: HTMLSpanElement;\n  public rect: DOMRect;\n\n  private newBtnMenu: HTMLElement;\n\n  private searchGroups: {[k in 'contacts' | 'globalContacts' | 'messages' | 'people' | 'recent']: SearchGroup} = {} as any;\n  public searchSuper: AppSearchSuper;\n  private searchInitResult: SearchInitResult;\n  private get isSearchActive() {\n    return useIsLeftSearchActive()[0]();\n  }\n  private set isSearchActive(value: boolean) {\n    useIsLeftSearchActive()[1](value);\n  }\n  private searchTriggerWhenCollapsed: HTMLElement;\n\n  private updateBtn: HTMLElement;\n  private hasUpdate: boolean;\n\n  private onResize: () => void;\n\n  constructor() {\n    super({\n      sidebarEl: document.getElementById('column-left') as HTMLDivElement,\n      navigationType: 'left'\n    });\n  }\n\n  construct(managers: AppManagers) {\n    this.managers = managers;\n\n    this.chatListContainer = document.getElementById('chatlist-container');\n    this.inputSearch = new InputSearch({oldStyle: true});\n    (this.inputSearch.input as HTMLInputElement).placeholder = ' ';\n    const sidebarHeader = this.sidebarEl.querySelector('.item-main .sidebar-header');\n    sidebarHeader.append(this.inputSearch.container);\n\n    this.backBtn = this.sidebarEl.querySelector('.sidebar-back-button') as HTMLButtonElement;\n\n    this.toolsBtn = this.createToolsMenu();\n    // .is-visible is owned by the Solid effect below (see \"burger element\n    // has two visual states\") — don't seed it here.\n    this.toolsBtn.classList.add('sidebar-tools-button');\n    this.totalNotificationsCount = createBadge('span', 20, 'primary');\n    this.totalNotificationsCount.classList.add('sidebar-tools-button-notifications');\n    this.toolsBtn.append(this.totalNotificationsCount);\n\n    const [allNotificationsCount, setAllNotificationsCount] = createSignal(0);\n    const mainMiddleware = this.middlewareHelper.get();\n    // renderFoldersSidebarContent creates the #folders-sidebar element\n    // itself and inserts it as the first child of #main-columns.\n    renderFoldersSidebarContent(\n      document.getElementById('main-columns'),\n      allNotificationsCount,\n      SolidJSHotReloadGuardProvider,\n      mainMiddleware\n    );\n\n    // If it has z-index to early, the browser makes it shift a few times before showing it properly in its position (on very large screens)\n    // Doesn't solve the blinking, which doesn't seem to appear when the project is built\n    pause(1000).then(() => {\n      this.sidebarEl.classList.add('can-menu-have-z-index');\n    });\n\n    rootScope.addEventListener('notification_count_update', async() => {\n      const notificationsCount = await uiNotificationsManager.getNotificationsCountForAllAccounts();\n      const count = Object.entries(notificationsCount).reduce(\n        (prev, [accountNumber, count]) =>\n          prev +\n          (+accountNumber !== getCurrentAccount() ? count || 0 : 0),\n         0);\n\n      setAllNotificationsCount(count);\n      [this.totalNotificationsCount].forEach((el) => {\n        setBadgeContent(el, '' + (count || ''));\n      });\n    });\n\n    this.backBtn.parentElement.insertBefore(this.toolsBtn, this.backBtn);\n\n    this.buttonsContainer = this.backBtn.parentElement;\n\n    this.newBtnMenu = this.createNewChatsMenuButton();\n    sidebarHeader.nextElementSibling.append(this.newBtnMenu);\n\n    this.updateBtn = document.createElement('div');\n    this.updateBtn.className = 'btn-circle rp btn-corner z-depth-1 btn-update is-hidden';\n    this.updateBtn.tabIndex = -1;\n    ripple(this.updateBtn);\n    this.updateBtn.append(i18n('Update'));\n\n    attachClickEvent(this.updateBtn, () => {\n      if(this.updateBtn.classList.contains('is-hidden')) {\n        return;\n      }\n\n      appNavigationController.reload();\n    });\n\n    sidebarHeader.nextElementSibling.append(this.updateBtn);\n\n    this.inputSearch.input.addEventListener('focus', () => this.initSearch(), {once: true});\n\n    this.archivedCount = createBadge('span', 24, 'gray');\n    this.archivedCount.classList.add('archived-count');\n\n    let archiveCountGeneration = 0;\n    const updateArchivedCount = async() => {\n      const generation = ++archiveCountGeneration;\n      const {unreadCount} = await rootScope.managers.dialogsStorage\n      .getFolderUnreadCount(FOLDER_ID_ARCHIVE, true);\n      if(generation !== archiveCountGeneration) {\n        return;\n      }\n\n      setBadgeContent(\n        this.archivedCount,\n        unreadCount ? '' + formatNumber(unreadCount, 1) : ''\n      );\n    };\n    rootScope.addEventListener('folder_unread', (folder) => {\n      if(folder.id === FOLDER_ID_ARCHIVE) {\n        void updateArchivedCount().catch(noop);\n      }\n    });\n    createRoot(() => {\n      const projectionKey = useCollapsedCommunityDialogsKey();\n      createEffect(on(projectionKey, () => {\n        void updateArchivedCount().catch(noop);\n      }));\n    });\n\n    let statusMiddlewareHelper: MiddlewareHelper, fireOnNew: boolean;\n    const premiumMiddlewareHelper = this.getMiddleware().create();\n    const statusBtnIcon = ButtonIcon(' sidebar-emoji-status', {noRipple: true});\n\n    const lockButton = createLockButton();\n\n    attachClickEvent(statusBtnIcon, () => {\n      openEmojiStatusPicker({\n        managers: this.managers,\n        anchorElement: statusBtnIcon,\n        onChosen: () => {\n          fireOnNew = true\n        }\n      })\n    });\n\n    const wrapStatus = async(middleware: Middleware) => {\n      const user = apiManagerProxy.getUser(rootScope.myId.toUserId());\n      const emojiStatus = user.emoji_status as EmojiStatus.emojiStatus;\n      if(!emojiStatus) {\n        statusBtnIcon.replaceChildren();\n        replaceButtonIcon(statusBtnIcon, 'star');\n        return;\n      }\n\n      fireOnNew && ReactionElement.fireAroundAnimation({\n        middleware: statusMiddlewareHelper?.get() || this.getMiddleware(),\n        reaction: {\n          _: 'reactionCustomEmoji',\n          document_id: emojiStatus.document_id\n        },\n        sizes: {\n          genericEffect: 26,\n          genericEffectSize: 100,\n          size: 22 + 18,\n          effectSize: 80\n        },\n        stickerContainer: statusBtnIcon,\n        cache: statusBtnIcon as any,\n        textColor: 'primary-color'\n      });\n\n      fireOnNew = false;\n\n      const container = await wrapEmojiStatus({\n        wrapOptions: {\n          middleware\n        },\n        emojiStatus,\n        size: makeMediaSize(24, 24)\n      });\n\n      container.classList.replace('emoji-status', 'sidebar-emoji-status-emoji');\n\n      statusBtnIcon.replaceChildren(container);\n    };\n\n    const onPremium = async(isPremium: boolean) => {\n      premiumMiddlewareHelper.clean();\n      const middleware = premiumMiddlewareHelper.get();\n      if(isPremium) {\n        await wrapStatus((statusMiddlewareHelper = middleware.create()).get());\n        if(!middleware()) return;\n        toggleRightButtons(true, await DeferredIsUsingPasscode.isUsingPasscode());\n\n        const onEmojiStatusChange = () => {\n          const oldStatusMiddlewareHelper = statusMiddlewareHelper;\n          wrapStatus((statusMiddlewareHelper = middleware.create()).get())\n          .finally(() => {\n            oldStatusMiddlewareHelper.destroy();\n          });\n        };\n\n        rootScope.addEventListener('emoji_status_change', onEmojiStatusChange);\n\n        middleware.onClean(() => {\n          rootScope.removeEventListener('emoji_status_change', onEmojiStatusChange);\n        });\n      } else {\n        toggleRightButtons(false, await DeferredIsUsingPasscode.isUsingPasscode());\n      }\n\n      appDialogsManager.resizeStoriesList?.();\n    };\n\n    const toggleRightButtons = (isPremium: boolean, isUsingPasscode: boolean) => {\n      if(isPremium) sidebarHeader.append(statusBtnIcon);\n      else statusBtnIcon.remove();\n\n      if(isUsingPasscode) sidebarHeader.append(lockButton.element);\n      else lockButton.element.remove();\n\n      sidebarHeader.classList.toggle('is-input-the-last-child', !isPremium && !isUsingPasscode);\n    };\n\n    appImManager.addEventListener('premium_toggle', onPremium);\n    rootScope.addEventListener('toggle_using_passcode', (isUsingPasscode) => {\n      toggleRightButtons(rootScope.premium, isUsingPasscode);\n    });\n\n    const [appSettings] = useAppSettings();\n    toggleRightButtons(rootScope.premium, appSettings.passcode?.enabled);\n\n    this.managers.appUsersManager.getTopPeers('correspondents');\n\n    this.initNavigation();\n\n    {\n      const CHECK_UPDATE_INTERVAL = 1800e3;\n      const checkUpdateInterval = setInterval(() => {\n        fetch('version', {cache: 'no-cache'})\n        .then((res) => (res.status === 200 && res.ok && res.text()) || Promise.reject())\n        .then((text) => {\n          if(text !== App.versionFull) {\n            this.hasUpdate = true;\n            clearInterval(checkUpdateInterval);\n\n            if(!this.newBtnMenu.classList.contains('is-hidden')) {\n              this.updateBtn.classList.remove('is-hidden');\n            }\n          }\n        })\n        .catch(noop);\n      }, CHECK_UPDATE_INTERVAL);\n    }\n\n    this.onResize = () => {\n      this.rect = this.tabsContainer.getBoundingClientRect();\n      updateColumnWidths();\n    };\n\n    fastRaf(this.onResize);\n    // mediaSizes.resize subscription happens inside installColumnWidthsUpdater().\n\n    this.searchTriggerWhenCollapsed = document.createElement('div');\n    this.searchTriggerWhenCollapsed.className = 'sidebar-header-search-trigger';\n    this.searchTriggerWhenCollapsed.append(ButtonIcon('search'));\n    this.searchTriggerWhenCollapsed.addEventListener('click', () => {\n      this.initSearch().open();\n    });\n\n    this.buttonsContainer.parentElement.prepend(this.searchTriggerWhenCollapsed);\n\n    // Visibility lives in JS — drives the `.is-visible` class from the\n    // signals that decide whether the icon-only search affordance should\n    // be shown. The CSS only reads that class, no body/parent-selector\n    // cascades.\n    createRoot(() => {\n      const [hasFoldersSidebar] = useHasFoldersSidebar();\n      const [isCollapsed] = useIsSidebarCollapsed();\n      const [hasOpenLeftTabs] = useHasOpenLeftTabs();\n      createEffect(() => {\n        const visible =\n          hasFoldersSidebar() &&\n          isCollapsed() &&\n          !hasOpenLeftTabs();\n        this.searchTriggerWhenCollapsed.classList.toggle('is-visible', visible);\n      });\n    });\n\n    // The burger element has two visual states: the three-line menu icon (a\n    // click on it opens the burger menu) and the back arrow (a click on it\n    // closes the open search). Three classes encode that state — toolsBtn /\n    // backBtn `.is-visible` (which click target is active) and the animated\n    // icon's `.state-back` (which shape it renders as). They all flow from\n    // the same condition, so a single Solid effect owns the truth:\n    //\n    //   showBack = useFoldersSidebarShown OR useIsLeftSearchActive\n    //\n    // When the folders panel is actually shown it has its own menu trigger, so\n    // the in-sidebar burger never serves as a menu — it stays in back state\n    // regardless of search activity. NOTE: gate on the viewport-aware *shown*\n    // value, not the raw useHasFoldersSidebar preference — below 925px the panel\n    // is hidden (its menu trigger with it), so the burger MUST fall back to the\n    // menu icon. Without the panel shown, back state follows search activity.\n    createRoot(() => {\n      const [foldersSidebarShown] = useFoldersSidebarShown();\n      const [isLeftSearchActive] = useIsLeftSearchActive();\n      const animatedMenuIcon = this.buttonsContainer.firstElementChild as HTMLElement;\n      createEffect(() => {\n        const showBack = foldersSidebarShown() || isLeftSearchActive();\n        this.toolsBtn.classList.toggle('is-visible', !showBack);\n        this.backBtn.classList.toggle('is-visible', showBack);\n        animatedMenuIcon.classList.toggle('state-back', showBack);\n      });\n    });\n\n    const sidebarOverlay = document.querySelector('.sidebar-left-overlay');\n    sidebarOverlay.addEventListener('click', () => {\n      this.closeEverythingInside();\n    });\n\n    this.initSidebarResize();\n    appDialogsManager.onSomeDrawerToggle = () => {\n      this.onSomethingOpenInsideChange();\n    };\n\n    addShortcutListener(['ctrl+f', 'alt+f', 'meta+f'], () => {\n      if(appNavigationController.findItemByType('popup')) return;\n      this.initSearch().open();\n    });\n\n    addShortcutListener(['ctrl+0', 'meta+0'], () => {\n      if(appNavigationController.findItemByType('popup') ||\n        appImManager.chat.peerId === appImManager.myId) return;\n      appImManager.setPeer({\n        peerId: appImManager.myId\n      });\n    });\n  }\n\n  /**\n   * Focus search input by pressing Escape\n   */\n  public initNavigation() {\n    const navigationItem: NavigationItem = {\n      type: 'global-search-focus',\n      onPop: () => {\n        setTimeout(() => {\n          if(this.isAnimatingCollapse) return;\n          this.initSearch().open();\n        }, 0);\n\n        return false;\n      },\n      noHistory: true\n    };\n    appNavigationController.removeByType('global-search-focus');\n    appNavigationController.pushItem(navigationItem);\n  }\n\n  public isCollapsed() {\n    // In the floating range the bar is always rendered expanded — the\n    // is-collapsed class is preserved as the remembered preference for\n    // wider viewports, but every consumer should see \"not collapsed\".\n    if(mediaSizes.isLessThanFloatingLeftSidebar) return false;\n    return this.sidebarEl.classList.contains('is-collapsed');\n  }\n\n  public hasFoldersSidebar() {\n    return document.body.classList.contains('has-folders-sidebar');\n  }\n\n  public onCollapsedChange(canShowCtrlFTip = false) {\n    this.chatListContainer.parentElement.classList.toggle('fade', this.isCollapsed());\n    this.chatListContainer.parentElement.classList.toggle('zoom-fade', !this.isCollapsed());\n    appDialogsManager.xd.toggleAvatarUnreadBadges(this.isCollapsed(), undefined);\n\n    const [hasFoldersSidebar] = useHasFoldersSidebar();\n\n    if(canShowCtrlFTip && this.isCollapsed() && !hasFoldersSidebar()) {\n      this.showCtrlFTip();\n    }\n\n    if(!this.isCollapsed()) appDialogsManager.resizeStoriesList?.();\n  }\n\n  public hasSomethingOpenInside() {\n    return this.hasTabsInNavigation() || this.isSearchActive || !!appDialogsManager.forumTab;\n  }\n\n  public closeEverythingInside() {\n    this.closeSearch();\n    appDialogsManager.toggleForumTab();\n\n    return this.closeAllTabs();\n  }\n\n  // Like closeEverythingInside, but closes stacked tabs the \"natural\" way (via\n  // the back arrow) so a tab can still confirm before closing. Returns false —\n  // without touching the search or the forum — if the user declines a tab's\n  // close confirmation, so the caller can cancel whatever triggered the close.\n  public async closeEverythingInsideNaturally() {\n    if(!await this.closeAllTabsNaturally()) {\n      return false;\n    }\n\n    if(this.isSearchActive) {\n      this.closeSearch();\n    }\n    appDialogsManager.toggleForumTab();\n\n    return true;\n  }\n\n  private isAnimatingCollapse = false;\n  private onSomethingOpenInsideChange = (force = false) => {\n    const wasFloating = this.sidebarEl.classList.contains('has-open-tabs');\n    const isFloating = force || this.hasSomethingOpenInside();\n    const isCollapsed = this.isCollapsed();\n    const hasRealTabs = this.hasTabsInNavigation();\n\n    this.sidebarEl.classList.toggle('has-open-tabs', isFloating);\n    this.sidebarEl.classList.toggle('has-real-tabs', hasRealTabs);\n    this.sidebarEl.classList.toggle('has-forum-open', !!appDialogsManager.forumTab);\n    // A floating forum stays mounted under its own management tabs — take it out\n    // of hit-testing so the selected tab gets pointer and keyboard interaction.\n    if(appDialogsManager.forumTab) {\n      appDialogsManager.forumTab.container.inert = hasRealTabs;\n    }\n    useHasOpenLeftTabs()[1](isFloating);\n\n    // Keep the pop-out flag in sync with the actual tabs state regardless of\n    // the early-return paths below. If we only set it inside the\n    // isFloating/!isFloating branches, opening a tab from an expanded sidebar\n    // and then closing it would leave the flag stuck at true — and a later\n    // collapse via the resize handle would render at default width instead of\n    // SIDEBAR_COLLAPSED_WIDTH.\n    setOpenTabsLeftSidebar(isFloating);\n\n    if(!isCollapsed && !this.hasSomethingOpenInside()) {\n      pause(300).then(() => {\n        // Mainly for stories when changing tabs view left <-> top\n        rootScope.dispatchEvent('resizing_left_sidebar');\n      });\n      return;\n    }\n\n    if(wasFloating === isFloating) return;\n\n\n    // Width is animated by CSS (transition on #column-left.is-collapsed\n    // width). The numbers below define how long we hold the auxiliary\n    // class state — they must match the layer-transition duration the CSS\n    // rule uses (currently 200ms).\n    const ANIMATION_TIME = 200;\n    // Wait a touch longer than the width transition before removing the\n    // force-* classes so child layouts don't shift while the bar is still\n    // visually resizing.\n    const DELAY_AFTER_ANIMATION = 150;\n\n    if(isFloating) {\n      this.sidebarEl.classList.add(\n        'force-hide-large-content',\n        'force-hide-menu',\n        'force-chatlist-thin'\n      );\n      !this.isSearchActive && this.sidebarEl.classList.add('force-hide-search');\n\n      this.isAnimatingCollapse = true;\n      pause(ANIMATION_TIME + DELAY_AFTER_ANIMATION).then(() => {\n        this.isAnimatingCollapse = false;\n        this.sidebarEl.classList.remove(\n          'force-hide-large-content',\n          'force-hide-menu',\n          'force-hide-search',\n          'force-chatlist-thin'\n        );\n      });\n      if(!appDialogsManager.forumTab)\n        appDialogsManager.xd?.toggleAvatarUnreadBadges(false, undefined);\n    } else {\n      this.sidebarEl.classList.add(\n        'force-fixed',\n        'hide-add-folders',\n        'force-chatlist-thin'\n      );\n\n      this.isAnimatingCollapse = true;\n      pause(ANIMATION_TIME + DELAY_AFTER_ANIMATION).then(() => {\n        this.sidebarEl.classList.remove(\n          'force-fixed',\n          'hide-add-folders',\n          'force-chatlist-thin'\n        );\n\n        appDialogsManager.xd.toggleAvatarUnreadBadges(true, undefined);\n\n        pause(200).then(() => {\n          this.isAnimatingCollapse = false;\n        });\n      });\n    }\n  }\n\n  public showCtrlFTip() {\n    const DATE_KEY = 'ctrlf-toast-to-show-again';\n    const showAgain = parseInt(localStorage.getItem(DATE_KEY));\n    const now = tsNow(true);\n\n    if(showAgain && now < showAgain) return;\n\n    toastNew({\n      langPackKey: IS_APPLE ? 'CtrlFSearchTipMac' : 'CtrlFSearchTip'\n    });\n    // Show once between 1 week to 2 months\n    const waitSeconds = (Math.round(Math.random() * 7 * 7) + 7) * 24 * 60 * 60;\n    localStorage.setItem(DATE_KEY, now + waitSeconds + '');\n  }\n\n  private initSidebarResize() {\n    this.onTabsCountChange = () => {\n      this.onSomethingOpenInsideChange();\n    }\n\n    installColumnResize({\n      columnEl: this.sidebarEl,\n      side: 'left',\n      isCollapsed: () => this.isCollapsed(),\n      setCollapsed: (collapsed) => {\n        // Drag only fires off-handheld (the resize handle is display:none\n        // at handheld), so the raw drag value is already the effective\n        // one — push it into the signal and the mirror effect in\n        // setSidebarLeftWidth (index.ts) toggles #column-left.is-collapsed.\n        useIsSidebarCollapsed()[1](collapsed);\n      },\n      onCollapsedChange: () => this.onCollapsedChange(true),\n      preventCollapse: () => this.hasSomethingOpenInside(),\n      onSwipeTick: () => appImManager.adjustChatPatternBackground()\n    });\n  }\n\n  public createToolsMenu(mountTo?: HTMLElement, positionPadding?: Parameters<typeof ButtonMenuToggle>[0]['positionPadding']) {\n    const closeTabsBefore = async(clb: () => void) => {\n      this.closeEverythingInside() && await pause(200);\n\n      clb();\n    }\n\n    const btnArchive: typeof menuButtons[0] = {\n      icon: 'archive',\n      text: 'ArchivedChats',\n      onClick: () => {\n        this.openArchiveTab();\n      },\n      verify: async() => {\n        const folder = await this.managers.dialogsStorage.getFolderDialogs(FOLDER_ID_ARCHIVE, false);\n        const hasArchiveStories = await this.managers.appStoriesManager.hasArchive();\n        return !!folder.length || hasArchiveStories || !(await this.managers.dialogsStorage.isDialogsLoaded(FOLDER_ID_ARCHIVE));\n      }\n    };\n\n    const onContactsClick = () => {\n      closeTabsBefore(() => {\n        this.createTab(AppContactsTab).open();\n      });\n    };\n\n    const moreSubmenu = createSubmenuTrigger({\n      options: {\n        text: 'MultiAccount.More',\n        icon: 'more'\n      },\n      createSubmenu: (args) => this.createMoreSubmenu(args, closeTabsBefore)\n    });\n\n    const newSubmenu = createSubmenuTrigger({\n      options: {\n        text: 'CreateANew',\n        icon: 'edit',\n        verify: () => this.isCollapsed(),\n        separator: true\n      },\n      createSubmenu: () => this.createNewChatsSubmenu()\n    });\n\n    const menuButtons: (ButtonMenuItemOptions & {verify?: () => boolean | Promise<boolean>})[] = [{\n      icon: 'plus',\n      text: 'MultiAccount.AddAccount',\n      onClick: this.addAccount,\n      verify: async() => {\n        const totalAccounts = await AccountController.getTotalAccounts();\n        return totalAccounts < MAX_ACCOUNTS;\n      }\n    }, newSubmenu, {\n      icon: 'savedmessages',\n      text: 'SavedMessages',\n      onClick: () => {\n        setTimeout(() => { // menu doesn't close if no timeout (lol)\n          appImManager.setPeer({\n            peerId: appImManager.myId\n          });\n        }, 0);\n      },\n      separator: true\n    }, btnArchive, {\n      icon: 'stories',\n      text: 'MyStories.Title',\n      onClick: () => {\n        closeTabsBefore(() => {\n          this.createTab(AppMyStoriesTab).open(AppMyStoriesTab.getInitArgs());\n        });\n      },\n      verify: () => !TEST_NO_STORIES\n    }, {\n      icon: 'user',\n      text: 'Contacts',\n      onClick: onContactsClick\n    }, {\n      id: 'settings',\n      icon: 'settings',\n      text: 'Settings',\n      separator: true,\n      onClick: () => {\n        closeTabsBefore(() => {\n          this.createTab(AppSettingsTab).open();\n        });\n      }\n    }, moreSubmenu];\n\n    const filteredButtons = menuButtons.filter(Boolean);\n    const filteredButtonsSliced = filteredButtons.slice();\n    const buttonMenuToggle = ButtonMenuToggle({\n      direction: 'bottom-right',\n      buttons: filteredButtons,\n      container: mountTo,\n      positionPadding,\n      onOpenBefore: async() => {\n        const emptyAttachMenuBots: AttachMenuBot[] = [];\n        const attachMenuBots = await Promise.race([\n          pause(30).then(() => emptyAttachMenuBots),\n          this.managers.appAttachMenuBotsManager.getAttachMenuBots().catch(() => emptyAttachMenuBots)\n        ]);\n        const buttons = filteredButtonsSliced.slice();\n        const attachMenuBotsButtons = attachMenuBots.filter((attachMenuBot) => {\n          return attachMenuBot.pFlags.show_in_side_menu;\n        }).map((attachMenuBot) => {\n          const icon = getAttachMenuBotIcon(attachMenuBot);\n          const button: typeof buttons[0] = {\n            regularText: wrapEmojiText(attachMenuBot.short_name),\n            onClick: () => {\n              appImManager.openWebApp({\n                attachMenuBot,\n                botId: attachMenuBot.bot_id,\n                isSimpleWebView: true,\n                fromSideMenu: true\n              });\n            },\n            iconDoc: icon?.icon as MyDocument,\n            new: attachMenuBot.pFlags.side_menu_disclaimer_needed || attachMenuBot.pFlags.inactive\n          };\n\n          return button;\n        });\n\n        function wrapUserName(user: User.user | PeerId) {\n          if(!isObject(user)) {\n            return '' + user;\n          }\n\n          let name = user.first_name;\n          if(user.last_name) name += ' ' + user.last_name;\n\n          name = limitSymbols(name, 15, 18);\n          return wrapEmojiText(name);\n        }\n\n        const targetIdx = buttons.findIndex((btn) => btn.id === 'settings');\n        buttons[targetIdx].separator = !!attachMenuBotsButtons.length;\n        buttons.splice(targetIdx, 0, ...attachMenuBotsButtons);\n        buttons[targetIdx].separator = true;\n\n        const [totalAccounts, notificationsCount] = await Promise.all([\n          AccountController.getTotalAccounts(),\n          uiNotificationsManager.getNotificationsCountForAllAccounts()\n        ]);\n        const accountButtons: typeof buttons = [];\n        for(let i = 1; i <= totalAccounts; i++) {\n          const accountNumber = i as ActiveAccountNumber;\n          if(accountNumber === getCurrentAccount()) {\n            const user = await this.managers.appUsersManager.getSelf();\n            accountButtons.push({\n              avatarInfo: {\n                accountNumber: getCurrentAccount(),\n                peerId: rootScope.myId.toPeerId(),\n                active: true\n              },\n              regularText: wrapUserName(user),\n              onClick: () => {\n                closeTabsBefore(() => {\n                  this.createTab(AppSettingsTab).open();\n                });\n              }\n            });\n          } else {\n            const otherManagers = createProxiedManagersForAccount(accountNumber);\n            const accountData = await AccountController.get(accountNumber);\n            const peerId = accountData.userId?.toPeerId();\n            const user = await otherManagers.appUsersManager.getSelf();\n\n            const content = document.createElement('span');\n            content.append(wrapUserName(user || peerId));\n\n            if(notificationsCount[accountNumber]) {\n              const badge = createBadge('span', 20, 'primary');\n              setBadgeContent(badge, '' + notificationsCount[accountNumber]);\n              content.append(badge);\n            }\n\n            accountButtons.push({\n              avatarInfo: {\n                accountNumber,\n                peerId,\n                peer: user\n              },\n              className: 'btn-menu-account-item',\n              regularText: content,\n              onClick: async(e) => {\n                const newTab = e.ctrlKey || e.metaKey;\n                if(!newTab) {\n                  appImManager.goOffline();\n\n                  const chatListEl = document.querySelector('.chatlist-container')?.firstElementChild;\n                  chatListEl.classList.add('chatlist-exit');\n                  await doubleRaf();\n                  chatListEl.classList.add('chatlist-exiting');\n                  await pause(200);\n\n                  await this.saveEncryptionKeyBeforeSwitchingAccounts();\n                }\n                changeAccount(accountNumber, newTab);\n              }\n            });\n          }\n        }\n\n        buttons.splice(0, 0, ...accountButtons);\n\n        filteredButtons.splice(0, filteredButtons.length, ...buttons);\n      },\n      onOpen: () => {\n        moreSubmenu.onOpen();\n        newSubmenu.onOpen();\n        btnArchive.element?.append(this.archivedCount);\n      },\n      onClose: () => {\n        moreSubmenu.onClose();\n        newSubmenu.onClose();\n      },\n      noIcon: true\n    });\n\n    return buttonMenuToggle;\n  }\n\n  private async saveEncryptionKeyBeforeSwitchingAccounts() {\n    const isUsingPasscode = await DeferredIsUsingPasscode.isUsingPasscode();\n    if(!isUsingPasscode) return;\n\n    const openTabs = apiManagerProxy.getOpenTabsCount();\n\n    openTabs <= 1 && await saveEncryptionKeyForHandoff();\n  }\n\n\n  private async createMoreSubmenu(\n    {middleware}: CreateSubmenuArgs,\n    closeTabsBefore: (clb: () => void) => void\n  ) {\n    const toggleTheme = () => {\n      const item = btns[0].element;\n      const icon = item.querySelector('.tgico');\n      const rect = icon.getBoundingClientRect();\n      themeController.switchTheme(undefined, {\n        x: rect.left + rect.width / 2,\n        y: rect.top + rect.height / 2\n      });\n    };\n\n    const darkModeText = document.createElement('span');\n    darkModeText.append(i18n(themeController.isNight() ? 'DisableDarkMode': 'EnableDarkMode'));\n    const animationsText = document.createElement('span');\n\n    const btns: ButtonMenuItemOptionsVerifiable[] = [{\n      icon: 'darkmode',\n      regularText: darkModeText,\n      onClick: () => {}\n    }, {\n      id: 'animations-toggle',\n      icon: 'animations',\n      regularText: animationsText,\n      onClick: () => {\n        toggleAnimations();\n      },\n      verify: () => !liteMode.isEnabled()\n    }, {\n      icon: 'animations',\n      text: 'LiteMode.Title',\n      onClick: () => {\n        closeTabsBefore(() => {\n          this.createTab(AppPowerSavingTab).open();\n        });\n      },\n      verify: () => liteMode.isEnabled()\n    }, {\n      icon: 'aversion',\n      text: 'ChatList.Menu.SwitchTo.A',\n      onClick: () => {\n        Promise.all([\n          sessionStorage.set({kz_version: 'Z'}),\n          sessionStorage.delete('tgme_sync')\n        ]).then(() => {\n          appNavigationController.navigateToUrl('https://web.telegram.org/a/');\n        });\n      },\n      separator: App.isMainDomain,\n      verify: () => App.isMainDomain\n    }, {\n      icon: 'help',\n      text: 'TelegramFeatures',\n      onClick: () => {\n        const url = I18n.format('TelegramFeaturesUrl', true);\n        appImManager.openUrl(url);\n      },\n      separator: !App.isMainDomain\n    }, {\n      icon: 'bug',\n      text: 'ReportBug',\n      onClick: () => {\n        const a = document.createElement('a');\n        setBlankToAnchor(a);\n        a.href = 'https://bugs.telegram.org/?tag_ids=40&sort=time';\n        document.body.append(a);\n        a.click();\n        setTimeout(() => {\n          a.remove();\n        }, 0);\n      }\n    }, {\n      icon: 'plusround',\n      text: 'PWA.Install',\n      onClick: () => {\n        const installPrompt = getInstallPrompt();\n        installPrompt?.();\n      },\n      verify: () => !!getInstallPrompt()\n    }, {\n      icon: 'pip',\n      // The More submenu is rebuilt on every open (createMoreSubmenu runs per open), so reading the live\n      // pip state here keeps the label in sync: while popped out the entry flips to \"Exit\". The whole app\n      // — including this menu — lives in the pip window when active, so that's where the user sees it.\n      text: isClientPipOpen() ? 'ClientPip.Exit' : 'PictureInPicture',\n      onClick: () => {\n        // The click is the user gesture `requestWindow` needs; closing the menu doesn't consume it.\n        if(isClientPipOpen()) {\n          closeClientPip();\n        } else {\n          openClientPip();\n        }\n      },\n      // Document Picture-in-Picture is Chromium-only — gate the entry on actual support.\n      verify: () => DOCUMENT_PICTURE_IN_PICTURE_SUPPORTED\n    }];\n\n\n    async function hasAnimations() {\n      const [appSettings] = useAppSettings();\n      return !appSettings.liteMode.animations;\n    }\n\n    async function initAnimationsToggleIcon() {\n      updateAnimationsToggleButton(await hasAnimations());\n    }\n\n    async function toggleAnimations() {\n      updateAnimationsToggleButton(!(await hasAnimations()));\n      const [, setAppSettings] = useAppSettings();\n      await setAppSettings('liteMode', 'animations', await hasAnimations());\n    }\n\n    async function updateAnimationsToggleButton(enabled: boolean) {\n      const animationToggleButton = btns.find((button) => button.id === 'animations-toggle')?.element;\n      if(!animationToggleButton) return;\n\n      const icon = animationToggleButton.querySelector('.tgico');\n      enabled ?\n        icon?.classList.add('animations-icon-off') :\n        icon?.classList.remove('animations-icon-off');\n\n      animationsText.replaceChildren(i18n(enabled ? 'DisableAnimations' : 'EnableAnimations'));\n    }\n\n    const filtered = await filterAsync(btns, (button) => button?.verify ? button.verify() ?? false : true);\n    const menu = await ButtonMenu({\n      buttons: filtered\n    });\n\n    menu.append(getVersionLink());\n    menu.classList.add('sidebar-tools-submenu');\n\n    const darkModeBtn = btns[0].element;\n    darkModeBtn.addEventListener(CLICK_EVENT_NAME, (e) => {\n      e.stopPropagation();\n      toggleTheme();\n      pause(20).then(() => contextMenuController.close());\n    }, true);\n\n    initAnimationsToggleIcon();\n\n    if(!middleware()) return;\n\n    return menu;\n  }\n\n  private createNewChatsMenuOptions(closeBefore?: boolean, singular?: boolean): ButtonMenuItemOptionsVerifiable[]  {\n    const closeTabsBefore = async(clb: () => void) => {\n      if(closeBefore) {\n        this.closeEverythingInside() && await pause(200);\n      }\n      clb();\n    }\n\n    const onNewGroupClick = () => {\n      closeTabsBefore(() => {\n        createNewGroupTab(this);\n      });\n    };\n\n    const onContactsClick = () => {\n      closeTabsBefore(() => {\n        this.createTab(AppContactsTab).open();\n      });\n    };\n\n    return [{\n      icon: 'newchannel',\n      text: singular ? 'Channel' : 'NewChannel',\n      onClick: () => {\n        closeTabsBefore(() => {\n          this.createTab(AppNewChannelTab).open({});\n        });\n      }\n    }, {\n      icon: 'newgroup',\n      text: singular ? 'Group' : 'NewGroup',\n      onClick: onNewGroupClick\n    }, {\n      icon: 'phone',\n      text: 'ConferenceCall.New',\n      verify: () => IS_CONFERENCE_CALL_SUPPORTED,\n      onClick: () => {\n        closeTabsBefore(() => {\n          void appImManager.createConference().catch(noop);\n        });\n      }\n    }, {\n      icon: 'newprivate',\n      text: singular ? 'PrivateChat' : 'NewPrivateChat',\n      onClick: onContactsClick\n    }];\n  }\n\n  private createNewChatsMenuButton() {\n    const btnMenu = ButtonMenuToggle({\n      direction: 'top-left',\n      buttons: this.createNewChatsMenuOptions(false),\n      noIcon: true,\n      positionPadding: {bottom: 10},\n      // Runs before the shared toggle's short-lived cached-menu fast path, so\n      // a rapid close/reopen cannot leave the trigger announced as collapsed.\n      onOpenBefore: () => btnMenu.setAttribute('aria-expanded', 'true'),\n      onClose: () => btnMenu.setAttribute('aria-expanded', 'false')\n    });\n    btnMenu.className = 'btn-new-menu btn-circle rp btn-corner z-depth-1 btn-menu-toggle animated-button-icon';\n    btnMenu.tabIndex = 0;\n    btnMenu.setAttribute('role', 'button');\n    btnMenu.setAttribute('aria-label', I18n.format('ChatAutomation.NewChats', true));\n    btnMenu.setAttribute('aria-expanded', 'false');\n    btnMenu.addEventListener('keydown', (e: KeyboardEvent) => {\n      if(e.key !== 'Enter' && e.key !== ' ') return;\n\n      cancelEvent(e);\n      // Use the same synthetic event as pointer activation. On touch-capable\n      // desktops the shared click helper listens to mousedown, not click.\n      simulateClickEvent(btnMenu);\n    });\n    const icons: Icon[] = ['newchat_filled', 'close'];\n    btnMenu.prepend(...icons.map((icon, idx) => Icon(icon, 'animated-button-icon-icon', 'animated-button-icon-icon-' + (idx === 0 ? 'first' : 'last'))));\n    btnMenu.id = 'new-menu';\n\n    return btnMenu;\n  }\n\n  private createNewChatsSubmenu() {\n    return ButtonMenu({\n      buttons: this.createNewChatsMenuOptions(true, true)\n    });\n  }\n\n  public initSearch() {\n    if(this.searchInitResult) return this.searchInitResult;\n\n    const searchContainer = this.sidebarEl.querySelector('#search-container') as HTMLDivElement;\n\n    const scrollable = new Scrollable(searchContainer);\n\n    const close = () => {\n      simulateClickEvent(this.backBtn);\n    };\n\n    const searchListenerSetter = new ListenerSetter();\n    const middleware = this.middlewareHelper.get();\n    this.searchGroups = {\n      contacts: createSearchGroup({name: 'SearchAllChatsShort', type: 'contacts', onFound: close, middleware}),\n      globalContacts: createSearchGroup({name: 'GlobalSearch', type: 'contacts', onFound: close, middleware}),\n      messages: createSearchGroup({name: 'SearchMessages', type: 'messages', middleware}),\n      people: createSearchGroup({name: false, type: 'contacts', className: 'search-group-people', autonomous: false, onFound: close, noIcons: true, middleware, scrollableX: true}),\n      recent: createSearchGroup({name: 'Recent', type: 'contacts', className: 'search-group-recent', onFound: close, middleware})\n    };\n\n    this.searchGroups.messages.createPlaceholder = () => {\n      const placeholder = new EmptySearchPlaceholder;\n      if(chatTypeMenu.props.selected !== 'all' && !chatTypeMenu.props.hidden)\n        placeholder.feedProps({\n          onAllChats: () => {\n            chatTypeMenu.props.selected = 'all';\n            updateSearchQuery({search: this.inputSearch.value, chatType: 'all'})\n          }\n        });\n\n      return placeholder;\n    };\n\n    const chatTypeMenu = new ChatTypeMenu();\n    chatTypeMenu.feedProps({\n      onChange: (chatType) => void updateSearchQuery({search: this.inputSearch.value, chatType}),\n      selected: 'all'\n    });\n\n    this.searchGroups.messages.setNameRight({\n      children: chatTypeMenu\n    });\n\n    const searchSuper = this.searchSuper = new AppSearchSuper({\n      mediaTabs: [{\n        inputFilter: 'inputMessagesFilterEmpty',\n        name: 'FilterChats',\n        type: 'chats'\n      }, {\n        name: 'ChannelsTab',\n        type: 'channels'\n      }, {\n        name: 'MiniApps.AppsSearch',\n        type: 'apps'\n      }, {\n        name: 'PostsSearch.TabName',\n        type: 'posts'\n      }, {\n        inputFilter: 'inputMessagesFilterPhotoVideo',\n        name: 'SharedMediaTab2',\n        type: 'media'\n      }, {\n        inputFilter: 'inputMessagesFilterUrl',\n        name: 'SharedLinksTab2',\n        type: 'links'\n      }, {\n        inputFilter: 'inputMessagesFilterDocument',\n        name: 'SharedFilesTab2',\n        type: 'files'\n      }, {\n        inputFilter: 'inputMessagesFilterMusic',\n        name: 'SharedMusicTab2',\n        type: 'music'\n      }, {\n        inputFilter: 'inputMessagesFilterRoundVoice',\n        name: 'SharedVoiceTab2',\n        type: 'voice'\n      }],\n      scrollable,\n      searchGroups: this.searchGroups,\n      asChatList: true,\n      hideEmptyTabs: false,\n      showSender: true,\n      managers: this.managers,\n      scrollOffset: 16\n    });\n\n    let prevTab: SearchSuperMediaType;\n    searchSuper.onChangeTab = (tab) => {\n      if(prevTab === 'posts') {\n        simulateClickEvent(this.inputSearch.clearBtn);\n      }\n\n      prevTab = tab.type;\n      searchSuper.searchContext.chatType = 'all';\n      if(tab.type === 'posts') {\n        searchSuper.globalPostsSearch?.setQuery(this.inputSearch.value);\n      }\n    };\n\n    this.watchChannelsTabVisibility(searchListenerSetter);\n\n    scrollable.append(searchSuper.container);\n\n    const resetSearch = () => {\n      searchSuper.setQuery({\n        peerId: ''.toPeerId(),\n        folderId: 0\n      });\n      searchSuper.selectTab(0);\n      searchSuper.load(true);\n    };\n\n    resetSearch();\n\n    const pickedElements: HTMLElement[] = [];\n    let selectedPeerId: PeerId = ''.toPeerId();\n    let selectedCommunityId: ChatId;\n    let selectedMinDate = 0;\n    let selectedMaxDate = 0;\n    const updatePicked = () => {\n      // (this.inputSearch.input as HTMLInputElement).placeholder = pickedElements.length ? 'Search' : 'Telegram Search';\n      this.inputSearch.container.classList.toggle('is-picked-twice', pickedElements.length === 2);\n      this.inputSearch.container.classList.toggle('is-picked', !!pickedElements.length);\n      pickedElements.forEach((element, idx) => {\n        element.classList.remove('is-first', 'is-last');\n        element.classList.add(idx === 0 ? 'is-first' : 'is-last');\n      });\n\n      if(pickedElements.length) {\n        pause(0).then(() => chatTypeMenu.props.hidden = true);\n\n        this.inputSearch.input.style.setProperty(\n          '--paddingLeft',\n          (pickedElements[pickedElements.length - 1].getBoundingClientRect().right - this.inputSearch.input.getBoundingClientRect().left) + 'px'\n        );\n      } else {\n        chatTypeMenu.props.hidden = false;\n        this.inputSearch.input.style.removeProperty('--paddingLeft');\n      }\n    };\n\n    const helperMiddlewareHelper = this.middlewareHelper.get().create();\n    const helper = document.createElement('div');\n    helper.classList.add('search-helper', 'hide');\n    helper.addEventListener('click', (e) => {\n      const target = findUpClassName(e.target, 'selector-user');\n      if(!target) {\n        return;\n      }\n\n      target.classList.remove('selector-user-primary');\n      const key = target.dataset.key;\n      if(key.indexOf('date_') === 0) {\n        const [_, minDate, maxDate] = key.split('_');\n        selectedMinDate = +minDate;\n        selectedMaxDate = +maxDate;\n      } else {\n        selectedPeerId = key.toPeerId();\n        selectedCommunityId = undefined;\n      }\n\n      target.addEventListener('click', () => {\n        unselectEntity(target);\n      });\n\n      this.inputSearch.container.append(target);\n      this.inputSearch.onChange(this.inputSearch.value = '');\n      pickedElements.push(target);\n      updatePicked();\n    });\n\n    searchSuper.nav.parentElement.append(helper);\n\n    const getCommunityByPeerId = (peerId: PeerId) => {\n      return peerId.isAnyChat() ?\n        apiManagerProxy.getChat(peerId.toChatId()) :\n        undefined;\n    };\n    const renderEntity = (key: PeerId | string, title?: string | HTMLElement) => {\n      const peerId = key.isPeerId() ? key.toPeerId() : undefined;\n      const community = peerId && getCommunityByPeerId(peerId);\n      const rendered = AppSelectPeers.renderEntity({\n        key,\n        title: title ?? community?.title,\n        middleware: helperMiddlewareHelper.get(),\n        avatarSize: 30,\n        fallbackIcon: 'calendarfilter',\n        primary: true\n      });\n      if(community) {\n        void rendered.avatar.render({\n          peerId,\n          peer: community as any\n        });\n      }\n\n      return rendered.element;\n    };\n\n    const unselectEntity = (target: HTMLElement) => {\n      const key = target.dataset.key;\n      if(key.indexOf('date_') === 0) {\n        selectedMinDate = selectedMaxDate = 0;\n      } else {\n        selectedPeerId = ''.toPeerId();\n        selectedCommunityId = undefined;\n      }\n\n      target.middlewareHelper.destroy();\n      target.remove();\n      indexOfAndSplice(pickedElements, target);\n\n      setTimeout(() => {\n        updatePicked();\n        this.inputSearch.onChange(this.inputSearch.value);\n      }, 0);\n    };\n\n    this.inputSearch.onClear = () => {\n      pickedElements.forEach((el) => {\n        unselectEntity(el);\n      });\n\n      helper.replaceChildren();\n      onHelperLength();\n    };\n\n    const onHelperLength = (hide = !helper.firstElementChild) => {\n      helper.classList.toggle('hide', hide);\n      searchSuper.nav.classList.toggle('hide', !hide);\n    };\n\n    const appendToHelper = (elements: HTMLElement[]) => {\n      helper.append(...elements);\n      onHelperLength();\n    };\n\n    this.inputSearch.onChange = (value) => {\n      if(searchSuper.mediaTab.type !== 'chats') {\n        chatTypeMenu.props.selected = 'all';\n      }\n      updateSearchQuery({search: value, chatType: chatTypeMenu.props.selected});\n    };\n\n    this.inputSearch.onEnter = (value) => {\n      const trimmed = value.trim();\n      if(!trimmed) return;\n      const wrapped = wrapUrl(trimmed);\n      if(!wrapped.onclick) return;\n      this.inputSearch.value = '';\n      this.inputSearch.onChange?.('');\n      simulateClickEvent(this.backBtn);\n      appImManager.openUrl(trimmed);\n    };\n\n    type UpdateSearchQueryArgs = {\n      search?: string;\n      chatType?: RequestHistoryOptions['chatType'];\n    };\n\n    const updateSearchQuery = ({search: value, chatType}: UpdateSearchQueryArgs) => {\n      const globalOnlyTabs: SearchSuperMediaType[] = [\n        'channels',\n        'apps',\n        'posts'\n      ];\n      for(const type of globalOnlyTabs) {\n        searchSuper.mediaTabsMap\n        .get(type)\n        ?.menuTab.classList.toggle('hide', !!selectedCommunityId);\n      }\n      if(\n        selectedCommunityId &&\n        globalOnlyTabs.includes(searchSuper.mediaTab.type)\n      ) {\n        searchSuper.selectTab(\n          searchSuper.mediaTabs.indexOf(searchSuper.mediaTabsMap.get('chats')),\n          false\n        );\n      }\n\n      if(searchSuper.mediaTab.type === 'posts') {\n        searchSuper.globalPostsSearch?.setQuery(value);\n        return\n      }\n\n      // spot input\n      searchSuper.cleanupHTML();\n      searchSuper.setQuery({\n        peerId: selectedPeerId,\n        communityId: selectedCommunityId,\n        folderId: selectedPeerId || selectedCommunityId ? undefined : 0,\n        query: value,\n        chatType,\n        minDate: selectedMinDate,\n        maxDate: selectedMaxDate\n      });\n      searchSuper.load(true);\n\n      helperMiddlewareHelper.clean();\n      onHelperLength(true);\n\n      const promises: MaybePromise<HTMLElement[]>[] = [];\n\n      if(!selectedMinDate && value.trim()) {\n        const dates: DateData[] = [];\n        fillTipDates(value, dates);\n        const elements = dates.map((dateData) => {\n          return renderEntity('date_' + dateData.minDate + '_' + dateData.maxDate, dateData.title);\n        });\n\n        promises.push(elements);\n      }\n\n      if(!selectedPeerId && !selectedCommunityId && value.trim()) {\n        const middleware = searchSuper.middleware.get();\n        const promise = Promise.all([\n          this.managers.dialogsStorage.getDialogs({query: value}).then(({dialogs}) => dialogs.map((d) => d.peerId)),\n          this.managers.appUsersManager.getContactsPeerIds(value, true)\n        ]).then((results) => {\n          if(!middleware()) return;\n          const peerIds = new Set(results[0].concat(results[1]).slice(0, 20));\n\n          return [...peerIds].map((peerId) => renderEntity(peerId));\n        });\n\n        promises.push(promise);\n      }\n\n      Promise.all(promises).then((arrays) => {\n        helper.replaceChildren();\n        const flattened = flatten(arrays);\n        appendToHelper(flattened);\n      });\n    };\n\n    searchSuper.tabs.inputMessagesFilterEmpty.addEventListener('mousedown', (e) => {\n      const target = findUpTag(e.target, DIALOG_LIST_ELEMENT_TAG) as HTMLElement;\n      if(!target) {\n        return;\n      }\n\n      const searchGroup = findUpClassName(target, 'search-group');\n      if(!searchGroup || searchGroup.classList.contains('search-group-recent') || searchGroup.classList.contains('search-group-people')) {\n        return;\n      }\n\n      const peerId = target.getAttribute('data-peer-id').toPeerId();\n      this.managers.appUsersManager.pushRecentSearch(peerId);\n    }, {capture: true});\n\n    let first = true;\n    let hideNewBtnMenuTimeout: number;\n    // const transition = Transition.bind(null, searchContainer.parentElement, 150);\n    const cleanup = () => {\n      pickedElements.forEach((el) => {\n        el.middlewareHelper.destroy();\n        el.remove();\n      });\n      pickedElements.length = 0;\n\n      this.inputSearch.value = '';\n      this.inputSearch.container.classList.remove('is-picked', 'is-picked-twice');\n      this.inputSearch.input.style.removeProperty('--paddingLeft');\n      this.inputSearch.onChange = undefined;\n      this.inputSearch.onClear = undefined;\n\n      searchSuper.destroy();\n      helperMiddlewareHelper.destroy();\n      searchContainer.replaceChildren();\n      searchListenerSetter.removeAll();\n\n      this.searchInitResult = undefined;\n      this.searchSuper = undefined;\n\n      this.inputSearch.input.addEventListener('focus', () => this.initSearch(), {once: true});\n    };\n\n    const transition = TransitionSlider({\n      content: searchContainer.parentElement,\n      type: 'zoom-fade',\n      transitionTime: 150,\n      listenerSetter: searchListenerSetter,\n      onTransitionStart: (id) => {\n        searchContainer.parentElement.parentElement.classList.toggle('is-search-active', id === 1);\n      },\n      onTransitionEnd: (id) => {\n        if(hideNewBtnMenuTimeout) clearTimeout(hideNewBtnMenuTimeout);\n\n        if(id === 0 && !first) {\n          cleanup();\n          hideNewBtnMenuTimeout = window.setTimeout(() => {\n            hideNewBtnMenuTimeout = 0;\n            this.newBtnMenu.classList.remove('is-hidden');\n            this.hasUpdate && this.updateBtn.classList.remove('is-hidden');\n          }, 150);\n        }\n\n        first = false;\n      }\n    });\n\n    transition(0);\n\n    const onFocus = () => {\n      // toolsBtn/backBtn `.is-visible` and the animated icon's `.state-back`\n      // are owned by the Solid effect in init() — flipping `isSearchActive`\n      // below propagates to all three classes.\n      this.newBtnMenu.classList.add('is-hidden');\n      this.updateBtn.classList.add('is-hidden');\n\n      const navigationType: NavigationItem['type'] = 'global-search';\n      if(!IS_MOBILE_SAFARI && !appNavigationController.findItemByType(navigationType)) {\n        appNavigationController.pushItem({\n          onPop: () => {\n            if(this.isAnimatingCollapse) return false;\n            close();\n          },\n          type: navigationType\n        });\n      }\n\n      transition(1);\n\n      // Decide whether the burger should grow/shrink with a transition.\n      // Only set it on the first focus of this open cycle — re-focusing the\n      // input while search is already open would otherwise see the burger's\n      // own `.is-visible` and flip the flag off, breaking the close\n      // animation. Driven structurally off the search trigger's class\n      // because the user prefers checking button presence over proxying\n      // through `.is-collapsed`.\n      if(!this.buttonsContainer.classList.contains('is-visible')) {\n        const triggerIsVisible = this.searchTriggerWhenCollapsed.classList.contains('is-visible');\n        this.buttonsContainer.classList.toggle('appear-animated', !triggerIsVisible);\n      }\n\n      this.buttonsContainer.classList.add('is-visible');\n      this.isSearchActive = true;\n      this.onSomethingOpenInsideChange();\n    };\n\n    searchListenerSetter.add(this.inputSearch.input)('focus', onFocus);\n    onFocus();\n\n    attachClickEvent(this.backBtn, (e) => {\n      // Burger state classes flip back when `isSearchActive` becomes false\n      // — see the init() effect that owns toolsBtn/backBtn/state-back.\n      appNavigationController.removeByType('global-search');\n\n      transition(0);\n      this.buttonsContainer.classList.remove('is-visible');\n      this.isSearchActive = false;\n      this.onSomethingOpenInsideChange();\n\n      chatTypeMenu.props.selected = 'all';\n    }, {listenerSetter: searchListenerSetter});\n\n    this.searchGroups.recent.setNameRight({\n      onClick: () => {\n        confirmationPopup({\n          descriptionLangKey: 'Search.Confirm.ClearHistory',\n          button: {\n            langKey: 'ClearButton',\n            isDanger: true\n          }\n        }).then(() => {\n          return this.managers.appUsersManager.clearRecentSearch().then(() => {\n            this.searchGroups.recent.clear();\n          });\n        });\n      },\n      children: i18n('ClearRecentSearch')\n    });\n\n    const focusInput = () => {\n      this.inputSearch.input.focus({preventScroll: true});\n    };\n\n    return this.searchInitResult = {\n      open: (focus = true) => {\n        onFocus();\n        if(focus) focusInput();\n      },\n      openWithPeerId: (peerId: PeerId) => {\n        onFocus();\n        focusInput();\n\n        selectedCommunityId = getCommunityByPeerId(peerId) ?\n          peerId.toChatId() :\n          undefined;\n        selectedPeerId = selectedCommunityId ?\n          ''.toPeerId() :\n          peerId;\n\n        this.inputSearch.onChange(this.inputSearch.value = '');\n\n        const element = renderEntity(peerId);\n        this.inputSearch.container.append(element);\n\n        element.addEventListener('click', () => {\n          unselectEntity(element);\n        });\n\n        pickedElements.push(element);\n        fastRaf(() => {\n          updatePicked();\n        });\n      },\n      close: () => {\n        close();\n      }\n    };\n  }\n\n  private async watchChannelsTabVisibility(listenerSetter: ListenerSetter) {\n    const checkChannelsVisiblity = async() => {\n      if(!this.searchSuper) return;\n      const dialogs = await this.managers.dialogsStorage.getCachedDialogs();\n\n      if(!this.searchSuper) return;\n      let hasChannels = false;\n      for(const dialog of dialogs) {\n        hasChannels = await this.managers.appPeersManager.isBroadcast(dialog.peerId);\n        if(hasChannels) break;\n      }\n\n      if(!this.searchSuper) return;\n      const channelsTab = this.searchSuper.mediaTabs.find((tab) => tab.type === 'channels');\n      channelsTab.menuTab?.classList.toggle(\n        'hide',\n        !hasChannels || !!this.searchSuper.searchContext.communityId\n      );\n    };\n\n    checkChannelsVisiblity();\n\n    listenerSetter.add(rootScope)('channel_update', () => {\n      pause(200).then(() => checkChannelsVisiblity());\n    });\n    listenerSetter.add(rootScope)('peer_deleted', () => {\n      checkChannelsVisiblity();\n    });\n  }\n\n  public closeSearch() {\n    if(!this.isSearchActive) {\n      return;\n    }\n\n    simulateClickEvent(this.backBtn);\n  }\n\n  public createTab<T extends SliderSuperTab>(\n    ctor: SliderSuperTabConstructable<T>,\n    destroyable = true,\n    doNotAppend?: boolean\n  ) {\n    const ctorsToOpenInPopup = [AppSettingsTab, AppEditFolderTab, AppChatFoldersTab]\n    if(this.isCollapsed() && !mediaSizes.isLessThanFloatingLeftSidebar && ctorsToOpenInPopup.includes(ctor as any)) {\n      const popup = new SettingsSliderPopup(this.managers);\n      popup.show();\n      return popup.slider.createTab(ctor, destroyable, doNotAppend);\n    }\n    return super.createTab(ctor, destroyable, doNotAppend);\n  }\n\n  // Every non-main tab in the left sidebar gets `.item-secondary`. The\n  // chatlist (HTML-declared `.item-main`) keeps its identity; archive /\n  // settings / contacts / etc. (all SliderSuperTab-created) flow through\n  // `addTab` and pick up the marker here, so SCSS rules that target\n  // \"secondary\" tabs don't have to enumerate every subclass.\n  public addTab(tab: SliderSuperTab) {\n    super.addTab(tab);\n    if(!tab.container.classList.contains('item-main')) {\n      tab.container.classList.add('item-secondary');\n    }\n  }\n\n  public async closeTabsBefore(clb: () => void) {\n    this.closeEverythingInside() && await pause(200);\n    clb();\n  }\n\n  public openArchiveTab() {\n    this.closeTabsBefore(() => {\n      this.createTab(AppArchivedTab).open();\n    });\n  }\n\n  public addAccount = async(e?: MouseEvent | TouchEvent) => {\n    const totalAccounts = await AccountController.getTotalAccounts();\n    if(totalAccounts >= MAX_ACCOUNTS) return;\n\n    const hasSomeonePremium = await apiManagerProxy.hasSomeonePremium();\n\n    if(totalAccounts === MAX_ACCOUNTS_FREE && !hasSomeonePremium) {\n      new AccountsLimitPopup().show();\n      return;\n    }\n\n    localStorage.setItem('previous-account', getCurrentAccount() + '');\n    const isUsingPasscode = await DeferredIsUsingPasscode.isUsingPasscode();\n    const openTabs = apiManagerProxy.getOpenTabsCount();\n\n    const newTab = e?.ctrlKey || e?.metaKey || (openTabs <= 1 && isUsingPasscode);\n    if(!newTab) {\n      appImManager.goOffline();\n\n      localStorage.setItem('should-animate-auth', 'true');\n\n      const chatsPageEl = document.querySelector('.page-chats');\n      chatsPageEl.classList.add('main-screen-exit');\n      await doubleRaf();\n      chatsPageEl.classList.add('main-screen-exiting');\n      await pause(200);\n    }\n\n    changeAccount((totalAccounts + 1) as ActiveAccountNumber, newTab);\n  };\n}\n\nconst appSidebarLeft = new AppSidebarLeft();\nMOUNT_CLASS_TO.appSidebarLeft = appSidebarLeft;\nexport default appSidebarLeft;\n\nfunction getVersionLink() {\n  const btnMenuFooter = document.createElement('a');\n  btnMenuFooter.href = 'https://github.com/morethanwords/tweb/blob/master/CHANGELOG.md';\n  setBlankToAnchor(btnMenuFooter);\n  btnMenuFooter.classList.add('btn-menu-footer');\n  btnMenuFooter.addEventListener(CLICK_EVENT_NAME, (e) => {\n    e.stopPropagation();\n    contextMenuController.close();\n  });\n  const t = document.createElement('span');\n  t.classList.add('btn-menu-footer-text');\n  t.textContent = `Telegram Web${App.suffix} ${App.version} (${App.build})`;\n  btnMenuFooter.append(t);\n\n  return btnMenuFooter;\n}\n","import generatePathData from '@helpers/generatePathData';\nimport {FormatterArguments, i18n, LangPackKey} from '@lib/langPack';\nimport Icon from '@components/icon';\n\nexport default class ChatDragAndDrop {\n  container: HTMLDivElement;\n  svg: SVGSVGElement;\n  outlineWrapper: HTMLDivElement;\n  path: SVGPathElement;\n\n  constructor(appendTo: HTMLElement, private options: {\n    icon?: Icon,\n    header: LangPackKey,\n    headerArgs?: FormatterArguments,\n    subtitle?: LangPackKey,\n    onDrop: (e: DragEvent) => void\n  }) {\n    this.container = document.createElement('div');\n    this.container.classList.add('drop', 'z-depth-1');\n\n    this.outlineWrapper = document.createElement('div');\n    this.outlineWrapper.classList.add('drop-outline-wrapper', 'disable-hover');\n\n    this.svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n    this.svg.classList.add('drop-outline');\n\n    this.path = document.createElementNS('http://www.w3.org/2000/svg', 'path');\n    this.path.classList.add('drop-outline-path');\n\n    let dropIcon: HTMLElement;\n    if(options.icon) {\n      dropIcon = document.createElement('div');\n      dropIcon.classList.add('drop-icon', 'disable-hover');\n      dropIcon.append(Icon(options.icon));\n      this.container.classList.add('has-icon');\n    }\n\n    const dropHeader = document.createElement('div');\n    dropHeader.classList.add('drop-header', 'disable-hover');\n    dropHeader.append(i18n(options.header, options.headerArgs));\n\n    let dropSubtitle: HTMLElement;\n    if(options.subtitle) {\n      dropSubtitle = document.createElement('div');\n      dropSubtitle.classList.add('drop-subtitle', 'disable-hover');\n      dropSubtitle.append(i18n(options.subtitle));\n    }\n\n    this.svg.append(this.path);\n    this.outlineWrapper.append(this.svg);\n\n    this.container.append(...[dropIcon, dropHeader, dropSubtitle, this.outlineWrapper].filter(Boolean));\n    appendTo.append(this.container);\n\n    this.container.addEventListener('dragover', this.onDragOver);\n    this.container.addEventListener('dragleave', this.onDragLeave);\n    this.container.addEventListener('drop', this.onDrop);\n  }\n\n  onDragOver = (e: DragEvent) => {\n    this.container.classList.add('is-dragover');\n    // SetTransition(this.container, 'is-dragover', true, 500);\n  };\n\n  onDragLeave = (e: DragEvent) => {\n    this.container.classList.remove('is-dragover');\n    // SetTransition(this.container, 'is-dragover', false, 500);\n  };\n\n  onDrop = (e: DragEvent) => {\n    this.options.onDrop(e);\n  };\n\n  destroy() {\n    delete this.options;\n    this.container.remove();\n    this.container.removeEventListener('dragover', this.onDragOver);\n    this.container.removeEventListener('dragleave', this.onDragLeave);\n    this.container.removeEventListener('drop', this.onDrop);\n  }\n\n  setPath() {\n    const rect = this.outlineWrapper.getBoundingClientRect();\n    this.svg.setAttributeNS(null, 'preserveAspectRatio', 'none');\n    this.svg.setAttributeNS(null, 'viewBox', `0 0 ${rect.width} ${rect.height}`);\n    this.svg.setAttributeNS(null, 'width', `${rect.width}`);\n    this.svg.setAttributeNS(null, 'height', `${rect.height}`);\n\n    const radius = 10;\n    // const strokeWidth = 2;\n    const sizeX = rect.width - radius;\n    const sizeY = rect.height - radius;\n    const pos = radius / 2;\n    const d = generatePathData(pos, pos, sizeX, sizeY, radius, radius, radius, radius);\n    this.path.setAttributeNS(null, 'd', d);\n  }\n}\n","import {doubleRaf} from '@helpers/schedulers';\n\nexport default function disableTransition(elements: HTMLElement[]) {\n  elements.forEach((el) => el.classList.add('no-transition'));\n\n  doubleRaf().then(() => {\n    elements.forEach((el) => el.classList.remove('no-transition'));\n  });\n}\n","import type {GroupCallParticipant} from '@layer';\nimport type {LangPackKey} from '@lib/langPack';\nimport type GroupCallInstance from '@lib/calls/groupCallInstance';\n\ntype MicrophoneCall = Pick<GroupCallInstance, 'participant' | 'changeRaiseHand' | 'toggleMuted'>;\n\nexport enum GROUP_CALL_MICROPHONE_BUTTON_STATE {\n  HAND,\n  MUTED,\n  UNMUTED\n}\n\nexport type MicrophoneControlAccessibility = {\n  disabled: boolean,\n  label: LangPackKey\n};\n\nexport function getGroupCallMicrophoneButtonState(\n  participant: GroupCallParticipant,\n  muted = !!participant.pFlags.muted\n) {\n  if(!participant.pFlags.can_self_unmute) {\n    return GROUP_CALL_MICROPHONE_BUTTON_STATE.HAND;\n  }\n\n  return muted ?\n    GROUP_CALL_MICROPHONE_BUTTON_STATE.MUTED :\n    GROUP_CALL_MICROPHONE_BUTTON_STATE.UNMUTED;\n}\n\nexport function getMicrophoneControlAccessibility(\n  participant?: GroupCallParticipant,\n  muted = !!participant?.pFlags.muted\n): MicrophoneControlAccessibility {\n  if(!participant) {\n    return {\n      disabled: true,\n      label: 'VoiceChat.Status.Connecting'\n    };\n  }\n\n  const state = getGroupCallMicrophoneButtonState(participant, muted);\n  if(state === GROUP_CALL_MICROPHONE_BUTTON_STATE.HAND) {\n    const handRaised = participant.raise_hand_rating !== undefined;\n    return {\n      disabled: handRaised,\n      label: handRaised ? 'ConferenceCall.Controls.HandRaised' : 'ConferenceCall.Controls.RaiseHand'\n    };\n  }\n\n  const isMuted = state === GROUP_CALL_MICROPHONE_BUTTON_STATE.MUTED;\n  return {\n    disabled: false,\n    label: isMuted ? 'VoipUnmute' : 'Call.Mute'\n  };\n}\n\nexport function performMicrophoneControlAction(instance: MicrophoneCall): Promise<void> {\n  const {participant} = instance;\n  if(!participant) return Promise.resolve();\n\n  if(getGroupCallMicrophoneButtonState(participant) === GROUP_CALL_MICROPHONE_BUTTON_STATE.HAND) {\n    if(participant.raise_hand_rating !== undefined) return Promise.resolve();\n    return instance.changeRaiseHand(true);\n  }\n\n  return instance.toggleMuted();\n}\n","import liteMode from '@helpers/liteMode';\nimport noop from '@helpers/noop';\nimport safeAssign from '@helpers/object/safeAssign';\nimport lottieLoader, {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport type LottiePlayer from '@lib/lottie/lottiePlayer';\nimport {LottieColor} from '@lib/lottie/lottiePlayer';\n\nexport type LottieIconOptions = {\n  width: number,\n  height: number,\n  container?: HTMLElement,\n  skipAnimation?: boolean\n};\n\nexport type LottieIconItemPartOptions = {\n  startFrame: number,\n  endFrame: number,\n  name?: string\n};\n\nexport type LottieIconItemOptions = {\n  name: LottieAssetName,\n  parts: LottieIconItemPartOptions[],\n  initFrame?: number,\n  player?: LottiePlayer,\n  autoplay?: boolean,\n  color?: LottieColor\n};\n\nexport class LottieIconItemPart implements LottieIconItemPartOptions {\n  public startFrame: number;\n  public endFrame: number;\n  public name?: string;\n\n  constructor(public item: LottieIconItem, options: LottieIconItemPartOptions) {\n    safeAssign(this, options);\n  }\n\n  public play(callback?: () => void) {\n    return this.item.playPart(this, callback);\n  }\n}\n\n// export type LottieIconItemPart = LottieIconItemPartOptions;\n\nexport class LottieIconItem implements LottieIconItemOptions {\n  public name: LottieAssetName;\n  public parts: LottieIconItemPart[];\n  public player: LottiePlayer;\n  public initFrame: number;\n  public autoplay: boolean;\n  public color: LottieColor;\n  public loadPromise: Promise<void>;\n  public onLoadForPart: () => void;\n  public onLoadForColor: () => void;\n\n  constructor(public icon: LottieIcon, options: LottieIconItemOptions) {\n    this.autoplay = false;\n\n    safeAssign(this, options);\n\n    this.parts = this.parts.map((options) => this.createPart(options));\n  }\n\n  public load() {\n    let loadPromise = this.loadPromise;\n    if(loadPromise) {\n      return loadPromise;\n    }\n\n    const {container, canvas, width, height} = this.icon;\n    loadPromise = lottieLoader.loadAnimationAsAsset({\n      container,\n      canvas,\n      width,\n      height,\n      group: 'none',\n      loop: false,\n      autoplay: this.autoplay ?? false,\n      initFrame: this.initFrame,\n      skipFirstFrameRendering: this.initFrame === undefined,\n      color: this.color\n    }, this.name).then((player) => {\n      return lottieLoader.waitForFirstFrame(player);\n    }).then((player) => {\n      this.player = player;\n\n      if(this.onLoadForColor) {\n        this.onLoadForColor();\n        this.onLoadForColor = undefined;\n      }\n\n      if(this.onLoadForPart) {\n        this.onLoadForPart();\n        this.onLoadForPart = undefined;\n      }\n    });\n\n    this.loadPromise = loadPromise;\n    this.icon.loadPromises.set(this.name, loadPromise);\n    return loadPromise;\n  }\n\n  public createPart(options: LottieIconItemPartOptions) {\n    return new LottieIconItemPart(this, options);\n  }\n\n  public getPart(index: string | number | LottieIconItemPart) {\n    if(index instanceof LottieIconItemPart) return index;\n    else if(typeof(index) === 'string') return this.parts.find((part) => part.name === index);\n    else return this.parts[index];\n  }\n\n  public playPart(part: LottieIconItemPart, callback?: () => void) {\n    return this.icon.playPart(this, part, callback);\n  }\n}\n\nexport default class LottieIcon {\n  public container: HTMLElement;\n  public canvas: HTMLCanvasElement;\n  public width: number;\n  public height: number;\n\n  protected items: Map<LottieAssetName, LottieIconItem>;\n  public loadPromises: Map<LottieAssetName, Promise<void>>;\n\n  protected skipAnimation: boolean;\n\n  constructor(options: LottieIconOptions) {\n    safeAssign(this, options);\n\n    if(!this.container) this.container = document.createElement('div');\n    this.container.classList.add('lottie-icon');\n\n    const {width, height} = this;\n    this.container.style.width = width + 'px';\n    this.container.style.height = height + 'px';\n\n    const canvas = this.canvas = document.createElement('canvas');\n    canvas.classList.add('lottie');\n    canvas.width = width;\n    canvas.height = height;\n\n    this.items = new Map();\n    this.loadPromises = new Map();\n  }\n\n  public get loadPromise() {\n    return Promise.all([...this.loadPromises.values()]).then(noop);\n  }\n\n  public getItem(name?: LottieAssetName): LottieIconItem {\n    return !name && this.items.size === 1 ? this.items.values().next().value : this.items.get(name);\n  }\n\n  public add(options: Omit<LottieIconItemOptions, 'player'>) {\n    const item = new LottieIconItem(this, options);\n    this.items.set(options.name, item);\n\n    return item;\n  }\n\n  public playPart(item: LottieIconItem, index: Parameters<LottieIconItem['getPart']>[0], callback?: () => void) {\n    if(!item.player) {\n      item.onLoadForPart = () => {\n        this.playPart(item, index, callback);\n      };\n\n      return;\n    }\n\n    const part = item.getPart(index);\n    item.player.playPart({\n      from: liteMode.isAvailable('animations') && !this.skipAnimation ? part.startFrame : part.endFrame,\n      to: part.endFrame,\n      callback\n    });\n  }\n\n  /* public playToPart(item: LottieIconItem, index: Parameters<LottieIconItem['getPart']>[0], toEnd: boolean) {\n    if(!item.player) return;\n    const part = item.getPart(index);\n    const toFrame = toEnd ? part.endFrame : part.startFrame;\n    item.player.playToFrame({\n      frame: toFrame\n    });\n  } */\n\n  public static generateEqualParts(length: number, frameCount: number): LottieIconItemPartOptions[] {\n    return new Array(length).fill(0).map((_, idx) => {\n      const startFrame = idx * frameCount;\n      return {startFrame, endFrame: startFrame + frameCount - 1};\n    });\n  }\n}\n","import noop from '@helpers/noop';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {LottieAssetName} from '@lib/lottie/lottieLoader';\nimport LottieIcon, {LottieIconItemPartOptions, LottieIconItemPart} from '@lib/lottie/lottieIcon';\nimport {LottieColor} from '@lib/lottie/lottiePlayer';\n\nexport type SuperLottieIconAddItemOptions = {name: LottieAssetName, parts: LottieIconItemPartOptions};\nexport type SuperLottieIconGetInfoResult = LottieIconItemPart;\nexport class SuperLottieIcon<Options extends {\n  PartState: any,\n  ColorState?: any,\n  Items?: {\n    name: string\n  }[]\n}> extends LottieIcon {\n  protected getPart: (state: Options['PartState'], prevState?: Options['PartState']) => SuperLottieIconGetInfoResult;\n  protected getColor?: (state: Options['ColorState'], prevState?: Options['ColorState']) => LottieColor;\n\n  protected partState: Options['PartState'];\n  protected colorState: Options['ColorState'];\n  protected loaded: boolean;\n\n  constructor(options: {\n    width: number,\n    height: number,\n    skipAnimation?: boolean,\n    getPart: (state: Options['PartState'], prevState?: Options['PartState']) => SuperLottieIconGetInfoResult,\n    getColor?: (state: Options['ColorState'], prevState?: Options['ColorState']) => LottieColor,\n  }) {\n    super({\n      width: options.width,\n      height: options.height\n    });\n\n    safeAssign(this, options);\n\n    // hook the first call\n    /* const originalFunction = this.setState.bind(this);\n    this.setState = (partState, colorState) => {\n      this.setState = originalFunction;\n      this.load(partState, colorState);\n      return originalFunction(partState, colorState);\n    }; */\n  }\n\n  public load(partState: Options['PartState'], colorState?: Options['ColorState']) {\n    if(this.loaded) {\n      return this.loadPromise;\n    }\n\n    this.loaded = true;\n    this.partState = partState;\n    this.colorState = colorState;\n\n    const part = this.getPart(partState);\n    const color = colorState !== undefined && this.getColor && this.getColor(colorState);\n\n    const item = part.item;\n    item.initFrame = part.endFrame;\n    item.color = color;\n\n    const promises = [...this.items.values()].map((item) => item.load());\n    return Promise.all(promises).then(noop);\n  }\n\n  /**\n   * Will redirect setting color state to part callback to synchronize the rendering\n   */\n  public setState(partState: Options['PartState'], colorState?: Options['ColorState'], partCallback?: () => void) {\n    if(!this.loaded) this.load(partState, colorState);\n\n    let changedPartState = false, changedColorState = false;\n    if(partState !== undefined) changedPartState = this.setPartState(partState, colorState, partCallback);\n    else if(colorState !== undefined) changedColorState = this.setColorState(colorState);\n\n    return changedPartState || changedColorState;\n  }\n\n  public setPartState(state: Options['PartState'], colorState?: Options['ColorState'], callback?: () => void) {\n    const {partState: prevState} = this;\n    if(prevState === state) {\n      return colorState !== undefined ? this.setColorState(colorState) : false;\n    }\n\n    if(colorState !== undefined) {\n      this.setColorState(colorState, false);\n    }\n\n    this.partState = state;\n\n    const part = this.getPart(state, prevState);\n    part.play(callback);\n\n    return true;\n  }\n\n  public setColorState(state: Options['ColorState'], renderIfPaused = true) {\n    const {colorState: prevState} = this;\n    if(prevState === state || !this.getColor) {\n      return false;\n    }\n\n    this.colorState = state;\n\n    const item = this.getItem();\n    const color = this.getColor(state, prevState);\n    const invoke = () => {\n      item.player.setColor(color, renderIfPaused);\n    };\n\n    if(item.player) {\n      invoke();\n    } else {\n      item.onLoadForColor = invoke;\n    }\n\n    return true;\n  }\n\n  public destroy() {\n    this.items.forEach((item) => {\n      item.loadPromise.then(() => {\n        item.player.remove();\n      });\n    });\n  }\n}\n","import {LottieIconItemPartOptions} from '@lib/lottie/lottieIcon';\nimport {GROUP_CALL_MICROPHONE_BUTTON_STATE} from '@components/groupCall/microphoneControl';\nimport {SuperLottieIcon} from '@components/superIcon';\n\nexport default class GroupCallMicrophoneIcon extends SuperLottieIcon<{\n  PartState: GROUP_CALL_MICROPHONE_BUTTON_STATE\n}> {\n  constructor() {\n    super({\n      width: 36,\n      height: 36,\n      getPart: (state, prevState) => {\n        const states = GROUP_CALL_MICROPHONE_BUTTON_STATE;\n        let partName: string;\n        switch(state) {\n          case states.HAND:\n            partName = prevState === states.MUTED ? 'muted-to-hand' : 'unmuted-to-hand';\n            break;\n          case states.MUTED:\n            partName = prevState === states.HAND ? 'hand-to-muted' : 'mute';\n            break;\n          case states.UNMUTED:\n            partName = 'unmute';\n            break;\n        }\n\n        return this.getItem().getPart(partName);\n      }\n    });\n\n    const className = 'group-call-microphone-icon';\n    this.container.classList.add(className + '-container');\n\n    const parts: LottieIconItemPartOptions[] = [{\n      startFrame: 0,\n      endFrame: 35,\n      name: 'hand-to-muted'\n    }, {\n      startFrame: 36,\n      endFrame: 68,\n      name: 'unmute'\n    }, {\n      startFrame: 69,\n      endFrame: 98,\n      name: 'mute'\n    }, {\n      startFrame: 99,\n      endFrame: 135,\n      name: 'muted-to-hand'\n    }, {\n      startFrame: 136,\n      endFrame: 172,\n      name: 'unmuted-to-hand'\n    }, {\n      startFrame: 173,\n      endFrame: 201,\n      name: 'scheduled-crossing'\n    }, {\n      startFrame: 202,\n      endFrame: 236,\n      name: 'scheduled-to-muted'\n    }, {\n      startFrame: 237,\n      endFrame: 273,\n      name: 'scheduled-to-hand'\n    }, {\n      startFrame: 274,\n      endFrame: 310,\n      name: 'scheduled-crossed-to-hand'\n    }, {\n      startFrame: 311,\n      endFrame: 343,\n      name: 'scheduled-uncrossing'\n    }, {\n      startFrame: 344,\n      endFrame: 375,\n      name: 'scheduled-to-muted'\n    }, {\n      startFrame: 376,\n      endFrame: 403,\n      name: 'play-to-muted'\n    }];\n\n    this.add({\n      name: 'voip_filled',\n      parts\n    });\n  }\n}\n","import LottieIcon from '@lib/lottie/lottieIcon';\nimport {GROUP_CALL_PARTICIPANT_CLEARED_MUTED_STATE, GROUP_CALL_PARTICIPANT_MUTED_STATE, getColorByMutedState, clearMutedStateModifier} from '.';\nimport {SuperLottieIcon} from '@components/superIcon';\n\nexport default class GroupCallParticipantMutedIcon extends SuperLottieIcon<{\n  PartState: GROUP_CALL_PARTICIPANT_CLEARED_MUTED_STATE,\n  ColorState: GROUP_CALL_PARTICIPANT_MUTED_STATE\n}> {\n  constructor(private colored: boolean) {\n    super({\n      width: 32,\n      height: 32,\n      getPart: (state, prevState) => {\n        const states = GROUP_CALL_PARTICIPANT_MUTED_STATE;\n\n        let index: number;\n        switch(state) {\n          case states.HAND:\n            index = 3;\n            break;\n          case states.MUTED:\n            index = prevState === states.HAND ? 0 : 2;\n            break;\n          case states.UNMUTED:\n            index = 1;\n            break;\n        }\n\n        return this.getItem().getPart(index);\n      },\n      getColor: colored ? (state, prevState) => {\n        return getColorByMutedState(state);\n      } : undefined\n    });\n\n    const className = 'group-call-participant-muted-icon';\n    this.container.classList.add(className + '-container');\n\n    const parts = LottieIcon.generateEqualParts(4, 21);\n    this.add({\n      name: 'voice_outlined2',\n      parts\n    });\n  }\n\n  public setState(state: GROUP_CALL_PARTICIPANT_MUTED_STATE) {\n    return super.setState(clearMutedStateModifier(state), state);\n  }\n}\n","import replaceContent from '@helpers/dom/replaceContent';\nimport setInnerHTML from '@helpers/dom/setInnerHTML';\nimport {GroupCallParticipant} from '@layer';\nimport {i18n} from '@lib/langPack';\nimport {GROUP_CALL_PARTICIPANT_MUTED_STATE} from '.';\nimport {GroupCallParticipantVideoType} from '@components/groupCall/participantVideo';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport Icon from '@components/icon';\n\nconst className = 'group-call-participant-status';\nexport default class GroupCallParticipantStatusElement {\n  public container: HTMLElement;\n\n  constructor(private withIcons: GroupCallParticipantVideoType[]) {\n    this.container = document.createElement('div');\n    this.container.classList.add(className + '-container');\n  }\n\n  /**\n   * @param withAccess the participant is on the call's e2e blockchain but absent\n   * from the SFU roster — it holds the current shared key without being\n   * connected to the media. tdesktop renders the same row as a plain listener\n   * with no status icon (`lng_group_call_blockchain_only_status`,\n   * calls_group_members_row.cpp:702) and never shows `about` for it.\n   */\n  public setState(state: GROUP_CALL_PARTICIPANT_MUTED_STATE, participant: GroupCallParticipant, withAccess?: boolean) {\n    const states = GROUP_CALL_PARTICIPANT_MUTED_STATE;\n    const icons = withAccess ? [] : this.withIcons.filter((type) => !!participant[type]).map((type) => {\n      const iconClassName: Icon = `${type === 'presentation' ? 'listscreenshare_filled' : 'videocamera_filled'}`;\n      const i = Icon(iconClassName, className + '-icon', className + '-icon-' + type);\n      return i;\n    });\n\n    let element2: HTMLElement, actionClassName: string;\n    if(withAccess) {\n      element2 = i18n('VoiceChat.Status.Listening');\n      actionClassName = 'is-listening';\n    } else if(state === states.MUTED_FOR_ME) {\n      element2 = i18n('VoiceChat.Status.MutedForYou');\n      actionClassName = 'is-muted';\n    } else if(state === states.UNMUTED) {\n      element2 = i18n('VoiceChat.Status.Speaking');\n      actionClassName = 'is-speaking';\n    } else if(state === states.HAND) {\n      element2 = i18n('VoiceChat.Status.WantsSpeak');\n      actionClassName = 'is-waiting';\n    } else if(participant.about && !icons.length) {\n      setInnerHTML(this.container, wrapEmojiText(participant.about));\n      return;\n    } else {\n      element2 = i18n('VoiceChat.Status.Listening');\n      actionClassName = 'is-listening';\n    }\n\n    const span = document.createElement('span');\n    span.classList.add(className, actionClassName);\n    span.append(...icons, element2);\n\n    replaceContent(this.container, span);\n  }\n}\n","import positionElementByIndex from '@helpers/dom/positionElementByIndex';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {fastRaf} from '@helpers/schedulers';\nimport SortedList, {SortedElementBase} from '@helpers/sortedList';\nimport appDialogsManager, {DialogDom, AppDialogsManager, DialogElementSize} from '@lib/appDialogsManager';\nimport {getGroupCallParticipantMutedState} from '.';\nimport GroupCallParticipantMutedIcon from '@components/groupCall/participantMutedIcon';\nimport GroupCallParticipantStatusElement from '@components/groupCall/participantStatus';\nimport type GroupCallInstance from '@lib/calls/groupCallInstance';\nimport type LazyLoadQueue from '@components/lazyLoadQueue';\nimport {MiddlewareHelper, getMiddleware} from '@helpers/middleware';\n\ninterface SortedParticipant extends SortedElementBase<PeerId> {\n  dom: DialogDom,\n  mutedIcon: GroupCallParticipantMutedIcon,\n  status: GroupCallParticipantStatusElement,\n  middlewareHelper: MiddlewareHelper\n}\n\nexport default class GroupCallParticipantsList extends SortedList<SortedParticipant> {\n  public list: HTMLUListElement;\n\n  protected lazyLoadQueue: LazyLoadQueue;\n  protected avatarSize: DialogElementSize = 'abitbigger';\n  protected rippleEnabled = true;\n  protected autonomous = true;\n  protected createChatListOptions: Parameters<AppDialogsManager['createChatList']>[0] = {/* new: true,  */dialogSize: 72};\n  private liveElements = new Set<SortedParticipant>();\n  private destroyed = false;\n  private generation = 0;\n\n  constructor(private instance: GroupCallInstance) {\n    super({\n      getIndex: async(element) => (await this.instance.getParticipantByPeerId(element.id)).date,\n      onDelete: (element) => {\n        element.dom.listEl.remove();\n        this.onElementDestroy(element);\n      },\n      onUpdate: async(element) => {\n        const generation = this.generation;\n        try {\n          const participant = await this.instance.getParticipantByPeerId(element.id);\n          if(this.destroyed || this.generation !== generation || this.get(element.id) !== element) return;\n\n          const state = getGroupCallParticipantMutedState(participant);\n          // On the e2e chain but absent from the SFU roster: has the call key,\n          // isn't connected to the media. See conferenceMembership.ts.\n          const withAccess = this.instance.isMemberWithAccess(element.id);\n\n          element.dom.listEl.classList.toggle('is-with-access', withAccess);\n          element.mutedIcon.setState(state);\n          element.status.setState(state, participant, withAccess);\n        } catch(err) {\n          if(!this.destroyed && this.generation === generation && this.get(element.id) === element) {\n            console.error('group call participant row update failed', err);\n          }\n        }\n      },\n      onSort: (element, idx) => {\n        positionElementByIndex(element.dom.listEl, this.list, idx);\n      },\n      onElementCreate: (base) => {\n        const middlewareHelper = getMiddleware();\n        const {dom} = appDialogsManager.addDialogNew({\n          peerId: base.id,\n          container: false,\n          avatarSize: this.avatarSize,\n          autonomous: this.autonomous,\n          meAsSaved: false,\n          rippleEnabled: this.rippleEnabled,\n          wrapOptions: {\n            lazyLoadQueue: this.lazyLoadQueue,\n            middleware: middlewareHelper.get()\n          }\n        });\n\n        const className = 'group-call-participant';\n        dom.listEl.classList.add(className);\n\n        const mutedIcon = new GroupCallParticipantMutedIcon(true);\n        const status = new GroupCallParticipantStatusElement(['presentation', 'video']);\n        replaceContent(dom.lastMessageSpan, status.container);\n        dom.listEl.append(mutedIcon.container);\n        (base as SortedParticipant).mutedIcon = mutedIcon;\n        (base as SortedParticipant).status = status;\n        (base as SortedParticipant).middlewareHelper = middlewareHelper;\n\n        /* instance.getParticipantByPeerId(base.id).then((participant) => {\n          const mutedState = getGroupCallParticipantMutedState(participant);\n\n          mutedIcon.setState(mutedState);\n          status.setState(mutedState, participant);\n        }); */\n\n        (base as SortedParticipant).dom = dom;\n        this.liveElements.add(base as SortedParticipant);\n\n        return base as SortedParticipant;\n      },\n      updateElementWith: fastRaf\n    });\n\n    this.list = appDialogsManager.createChatList(this.createChatListOptions);\n  }\n\n  public destroy() {\n    if(this.destroyed) return;\n    this.destroyed = true;\n    ++this.generation;\n    const elements = Array.from(this.liveElements);\n    super.clear();\n    elements.forEach((element) => {\n      element.dom.listEl.remove();\n      this.onElementDestroy(element);\n    });\n  }\n\n  protected onElementDestroy(element: SortedParticipant) {\n    if(!this.liveElements.delete(element)) return;\n    element.mutedIcon.destroy();\n    element.middlewareHelper.destroy();\n  }\n}\n","import {animate} from '@helpers/animation';\n\nexport default function callVideoCanvasBlur(video: HTMLVideoElement) {\n  const canvas = document.createElement('canvas');\n  canvas.classList.add('call-video-blur');\n  const size = 16;\n  canvas.width = size;\n  canvas.height = size;\n\n  const ctx = canvas.getContext('2d', {alpha: false});\n  ctx.filter = 'blur(2px)';\n  const renderFrame = () => {\n    ctx.drawImage(video, 0, 0, video.videoWidth, video.videoHeight, 0, 0, canvas.width, canvas.height);\n  };\n\n  animate(() => {\n    renderFrame();\n    return canvas.isConnected;\n  });\n\n  renderFrame();\n\n  return canvas;\n}\n","import {GroupCallParticipant} from '@layer';\nimport type {GroupCallOutputSource} from '@appManagers/appGroupCallsManager';\nimport {i18n} from '@lib/langPack';\nimport PeerTitle from '@components/peerTitle';\nimport {getGroupCallParticipantMutedState} from '.';\nimport GroupCallParticipantMutedIcon from '@components/groupCall/participantMutedIcon';\nimport GroupCallParticipantStatusElement from '@components/groupCall/participantStatus';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport callVideoCanvasBlur from '@components/call/videoCanvasBlur';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport {AppManagers} from '@lib/managers';\nimport safePlay from '@helpers/dom/safePlay';\nimport Icon from '@components/icon';\n\nconst className = 'group-call-participant-video';\n\nexport type GroupCallParticipantVideoType = 'video' | 'presentation';\nexport default class GroupCallParticipantVideoElement {\n  public container: HTMLElement;\n  private peerTitle: PeerTitle;\n  private subtitle: HTMLElement;\n  private info: HTMLElement;\n  private left: HTMLElement;\n  private right: HTMLElement;\n  private header: HTMLElement;\n  private groupCallParticipantMutedIcon: GroupCallParticipantMutedIcon;\n  private groupCallParticipantStatus: GroupCallParticipantStatusElement;\n\n  constructor(private managers: AppManagers, private instance: GroupCallInstance, public source: GroupCallOutputSource) {\n    this.container = document.createElement('div');\n    this.container.classList.add(className + '-container');\n\n    this.info = document.createElement('div');\n    this.info.classList.add(className + '-info');\n\n    this.left = document.createElement('div');\n    this.left.classList.add(className + '-info-left');\n\n    this.right = document.createElement('div');\n    this.right.classList.add(className + '-info-right');\n\n    this.info.append(this.left, this.right);\n\n    this.container.append(this.info);\n  }\n\n  public setPinned(value: boolean) {\n    if(!value) {\n      if(this.header) {\n        this.header.remove();\n        this.header = undefined;\n      }\n\n      return;\n    } else if(this.header) {\n      return;\n    }\n\n    // if(!this.header) {\n    this.header = document.createElement('div');\n    this.header.classList.add(className + '-header');\n\n    const icon = Icon('pin', 'group-call-pin-icon');\n    this.header.append(icon);\n\n    this.container.append(this.header);\n    // }\n\n    // this.container.classList.toggle('is-pinned', value);\n  }\n\n  public setParticipant(participant: GroupCallParticipant, type: GroupCallParticipantVideoType, video: HTMLVideoElement) {\n    let peerTitleElement: HTMLElement;\n    if(participant.pFlags.self) {\n      peerTitleElement = i18n('VoiceChat.Status.You');\n      peerTitleElement.classList.add('peer-title');\n    } else {\n      this.peerTitle = new PeerTitle({\n        peerId: getPeerId(participant.peer)\n      });\n\n      peerTitleElement = this.peerTitle.element;\n    }\n\n    this.groupCallParticipantMutedIcon = new GroupCallParticipantMutedIcon(false);\n    this.groupCallParticipantStatus = new GroupCallParticipantStatusElement([type]);\n\n    this.left.append(peerTitleElement, this.groupCallParticipantStatus.container);\n\n    this.right.append(this.groupCallParticipantMutedIcon.container);\n\n    video.classList.add(className, 'call-video');\n\n    if(video.paused) {\n      safePlay(video);\n    }\n\n    const canvas = callVideoCanvasBlur(video);\n    canvas.classList.add(className + '-blur');\n\n    this.container.prepend(canvas, video);\n\n    this.updateParticipant(participant);\n  }\n\n  public updateParticipant(participant: GroupCallParticipant) {\n    const state = getGroupCallParticipantMutedState(participant);\n\n    this.groupCallParticipantMutedIcon.setState(state);\n    this.groupCallParticipantStatus.setState(state, participant);\n  }\n\n  public destroy() {\n    this.groupCallParticipantMutedIcon.destroy();\n  }\n}\n","import {attachClickEvent} from '@helpers/dom/clickEvent';\nimport ControlsHover from '@helpers/dom/controlsHover';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport {GroupCallParticipant} from '@layer';\nimport {GroupCallOutputSource} from '@appManagers/appGroupCallsManager';\nimport {AppManagers} from '@lib/managers';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport rootScope from '@lib/rootScope';\nimport GroupCallParticipantVideoElement, {GroupCallParticipantVideoType} from '@components/groupCall/participantVideo';\n\nexport default class GroupCallParticipantsVideoElement extends ControlsHover {\n  private container: HTMLDivElement;\n  private instance: GroupCallInstance;\n  private participantsElements: Map<PeerId, Map<GroupCallParticipantVideoType, GroupCallParticipantVideoElement>>;\n  private displayPinned: boolean;\n  private containers: Map<HTMLElement, GroupCallParticipantVideoElement>;\n  private onLengthChange: (length: number) => void;\n  private managers: AppManagers;\n\n  constructor(options: {\n    appendTo: HTMLElement,\n    instance: GroupCallInstance,\n    listenerSetter: ListenerSetter,\n    displayPinned: boolean,\n    onLengthChange?: GroupCallParticipantsVideoElement['onLengthChange'],\n    managers: AppManagers\n  }) {\n    super();\n    safeAssign(this, options);\n\n    const className = 'group-call-participants-video';\n    const container = this.container = document.createElement('div');\n    this.container.classList.add(className + '-container');\n\n    options.appendTo.append(container);\n\n    this.participantsElements = new Map();\n    this.containers = new Map();\n\n    const {listenerSetter} = this;\n\n    listenerSetter.add(rootScope)('group_call_participant', ({groupCallId, participant}) => {\n      if(this.instance.id === groupCallId) {\n        this.updateParticipant(participant);\n      }\n    });\n\n    listenerSetter.add(this.instance)('pinned', (source) => {\n      this.participantsElements.forEach((map) => {\n        map.forEach((element) => {\n          this.setElementDisplay(element, source);\n        });\n      });\n    });\n\n    attachClickEvent(this.container, (e) => {\n      const container = findUpClassName(e.target, 'group-call-participant-video-container');\n      if(!container) {\n        return;\n      }\n\n      const element = this.containers.get(container);\n      if(this.instance.pinnedSource === element.source) {\n        this.instance.unpinAll();\n        return;\n      }\n\n      this.instance.pinSource(element.source);\n    }, {listenerSetter});\n\n    this.setInstance(this.instance);\n\n    this.setup({\n      element: container,\n      listenerSetter: listenerSetter,\n      showOnLeaveToClassName: 'group-call-buttons'\n    });\n  }\n\n  private shouldDisplayElement(element: GroupCallParticipantVideoElement, pinnedSource: GroupCallOutputSource) {\n    return this.displayPinned ? !pinnedSource || element.source === pinnedSource : pinnedSource && element.source !== pinnedSource;\n  }\n\n  private setElementDisplay(element: GroupCallParticipantVideoElement, pinnedSource: GroupCallOutputSource) {\n    const shouldDisplay = this.shouldDisplayElement(element, pinnedSource);\n    element.container.classList.toggle('video-hidden', !shouldDisplay);\n\n    const isPinned = element.source === pinnedSource;\n    element.setPinned(isPinned);\n  }\n\n  private updateParticipant(participant: GroupCallParticipant) {\n    const peerId = getPeerId(participant.peer);\n    const types: GroupCallParticipantVideoType[] = ['video', 'presentation'];\n    const hasAnyVideo = types.some((type) => !!participant[type]);\n    let participantElements = this.participantsElements.get(peerId);\n    if(!hasAnyVideo && !participantElements) {\n      return;\n    }\n\n    if(!participantElements) {\n      this.participantsElements.set(peerId, participantElements = new Map());\n    }\n\n    types.forEach((type) => {\n      let element = participantElements.get(type);\n      const participantVideo = participant[type];\n      if(!!participantVideo === !!element) {\n        if(element) {\n          element.updateParticipant(participant);\n        }\n\n        return;\n      }\n\n      if(participantVideo) {\n        const result = this.instance.getVideoElementFromParticipantByType(participant, type);\n        if(!result) {\n          return;\n        }\n\n        const {video, source} = result;\n\n        element = new GroupCallParticipantVideoElement(this.managers, this.instance, source);\n\n        this.containers.set(element.container, element);\n\n        this.setElementDisplay(element, this.instance.pinnedSource);\n        participantElements.set(type, element);\n        element.setParticipant(participant, type, video);\n\n        this.container.prepend(element.container);\n      } else {\n        participantElements.delete(type);\n        element.container.remove();\n\n        if(!participantElements.size) {\n          this.participantsElements.delete(peerId);\n          this.containers.delete(element.container);\n          element.destroy();\n        }\n      }\n\n      this._onLengthChange();\n    });\n  }\n\n  private _onLengthChange() {\n    const length = this.container.childElementCount;\n    this.container.dataset.length = '' + length;\n    this.container.dataset.layout = length <= 2 ? '1' : (length === 3 ? '3' : '4');\n\n    this.onLengthChange && this.onLengthChange(length);\n  }\n\n  public async setInstance(instance: GroupCallInstance) {\n    (await instance.participants).forEach((participant) => {\n      this.updateParticipant(participant);\n    });\n  }\n\n  public destroy() {\n    this.containers.forEach((element) => {\n      element.destroy();\n    });\n  }\n}\n","import PopupGroupCall from '.';\nimport {getOverlayRoot} from '@helpers/appWindow';\nimport createContextMenu from '@helpers/dom/createContextMenu';\nimport findUpClassName from '@helpers/dom/findUpClassName';\nimport {addFullScreenListener, isFullScreen} from '@helpers/dom/fullScreen';\nimport ListenerSetter from '@helpers/listenerSetter';\nimport safeAssign from '@helpers/object/safeAssign';\nimport positionMenu from '@helpers/positionMenu';\nimport ScrollableLoader from '@helpers/scrollableLoader';\nimport {GroupCallParticipant} from '@layer';\nimport appImManager from '@lib/appImManager';\nimport {AppManagers} from '@lib/managers';\nimport getPeerId from '@appManagers/utils/peers/getPeerId';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport rootScope from '@lib/rootScope';\nimport {\n  ButtonMenuItemOptionsVerifiable\n} from '@components/buttonMenu';\nimport confirmationPopup from '@components/confirmationPopup';\nimport PeerTitle from '@components/peerTitle';\nimport PopupElement from '@components/popups';\nimport Scrollable from '@components/scrollable';\nimport GroupCallParticipantsList from '@components/groupCall/participantsList';\nimport GroupCallParticipantsVideoElement from '@components/groupCall/participantVideos';\nimport {toastNew} from '@components/toast';\n\nexport class GroupCallParticipantContextMenu {\n  private buttons: ButtonMenuItemOptionsVerifiable[];\n  private chatId: ChatId;\n  private targetPeerId: PeerId;\n  private participant: GroupCallParticipant;\n  private instance: GroupCallInstance;\n  private canManageCall: boolean;\n  private managers: AppManagers;\n  private listenerSetter = new ListenerSetter();\n  private contextMenu: ReturnType<typeof createContextMenu>;\n  private destroyed = false;\n  private openGeneration = 0;\n  private removeParentCleanup: () => void;\n\n  constructor(options: {\n    listenerSetter: ListenerSetter,\n    onContextElement: HTMLElement,\n    managers: AppManagers,\n    instance: GroupCallInstance,\n  }) {\n    this.buttons = [{\n      icon: 'gc_microphoneoff',\n      text: 'VoiceChat.MutePeer',\n      verify: () => this.canManageCall && this.participant.pFlags.can_self_unmute,\n      onClick: () => this.toggleParticipantMuted(true)\n    }, {\n      icon: 'gc_microphone',\n      text: 'VoiceChat.UnmutePeer',\n      verify: () => this.canManageCall && !this.participant.pFlags.can_self_unmute,\n      onClick: () => this.toggleParticipantMuted(false)\n    }, {\n      icon: 'gc_microphoneoff',\n      text: 'VoiceChat.MuteForMe',\n      verify: () => !this.canManageCall && !this.participant.pFlags.muted_by_you,\n      onClick: () => this.toggleParticipantMuted(true)\n    }, {\n      icon: 'gc_microphone',\n      text: 'VoiceChat.UnmuteForMe',\n      verify: () => !this.canManageCall && this.participant.pFlags.muted_by_you,\n      onClick: () => this.toggleParticipantMuted(false)\n    }, {\n      icon: 'newprivate',\n      text: 'VoiceChat.OpenProfile',\n      verify: () => true,\n      onClick: this.onOpenProfileClick\n    }, {\n      icon: 'deleteuser',\n      className: 'danger',\n      text: 'VoiceChat.RemovePeer',\n      verify: () => this.managers.appChatsManager.hasRights(this.chatId, 'ban_users'),\n      onClick: () => {\n        void this.removeParticipant();\n      }\n    }];\n\n    const {listenerSetter} = this;\n    this.removeParentCleanup = options.listenerSetter.addCleanup(() => this.destroy());\n    this.managers = options.managers;\n    this.instance = options.instance;\n    this.chatId = this.instance.chatId;\n\n    this.contextMenu = createContextMenu({\n      buttons: this.buttons,\n      listenTo: options.onContextElement,\n      listenerSetter,\n      findElement: (e) => findUpClassName(e.target, 'group-call-participant'),\n      resolveAppendTo: () => isFullScreen() ?\n        PopupElement.getPopups(PopupGroupCall)[0]?.getContainer() ?? getOverlayRoot() :\n        getOverlayRoot(),\n      onOpen: async(_e, li) => {\n        const generation = ++this.openGeneration;\n        const peerId = li.dataset.peerId.toPeerId();\n        // A chain-only member has no SFU participant behind them, so every\n        // action here (mute, mute-for-me, kick) would address a row the server\n        // doesn't know about. tdesktop keeps these rows inert too\n        // (calls_group_members_row.cpp:747).\n        if(this.instance.isMemberWithAccess(peerId)) {\n          return false;\n        }\n        this.targetPeerId = peerId;\n\n        const participant = await this.instance.getParticipantByPeerId(peerId);\n        if(this.destroyed || this.openGeneration !== generation) return false;\n        if(!participant || participant.pFlags.self) return false;\n\n        const canManageCall = await this.managers.appChatsManager.hasRights(this.chatId, 'manage_call');\n        if(this.destroyed || this.openGeneration !== generation) return false;\n        this.targetPeerId = peerId;\n        this.participant = participant;\n        this.canManageCall = canManageCall;\n      },\n      onElementReady: (element) => {\n        element.classList.add('group-call-participant-menu', 'night');\n      },\n      position: (e, element) => {\n        positionMenu('touches' in e ? e.touches[0] : e, element, 'right');\n      },\n      reopenOnTrigger: true,\n      cancelOnOpenFalse: true\n    });\n\n    listenerSetter.add(rootScope)('group_call_participant', ({groupCallId, participant}) => {\n      if(this.instance.id === groupCallId) {\n        const peerId = getPeerId(participant.peer);\n        if(this.targetPeerId === peerId) {\n          this.closeContextMenu();\n        }\n      }\n    });\n\n    listenerSetter.add(this.instance)('membersWithAccess', ({current}) => {\n      if(this.targetPeerId !== undefined && current.includes(this.targetPeerId)) {\n        this.closeContextMenu();\n      }\n    });\n\n    addFullScreenListener(document.body, () => {\n      this.closeContextMenu();\n    }, listenerSetter);\n  }\n\n  private closeContextMenu() {\n    ++this.openGeneration;\n    this.contextMenu.close();\n  }\n\n  private onOpenProfileClick = () => {\n    const popup = PopupElement.getPopups(PopupGroupCall)[0];\n    if(popup) {\n      popup.hide();\n    }\n\n    appImManager.setInnerPeer({peerId: this.targetPeerId});\n  };\n\n  private toggleParticipantMuted = (muted: boolean) => {\n    return this.instance.editParticipant(this.participant, {\n      muted\n    }).catch((err) => {\n      if(this.destroyed) return;\n      console.error('edit group call participant failed', err);\n      toastNew({langPackKey: 'Error.AnError'});\n    });\n  };\n\n  private async removeParticipant(): Promise<void> {\n    const chatId = this.chatId;\n    const peerId = this.targetPeerId;\n    const generation = this.openGeneration;\n    let isBroadcast: boolean;\n    try {\n      isBroadcast = await this.managers.appChatsManager.isBroadcast(chatId);\n    } catch(err) {\n      if(!this.destroyed && this.openGeneration === generation) {\n        console.error('load remove-participant confirmation failed', err);\n        toastNew({langPackKey: 'Error.AnError'});\n      }\n      return;\n    }\n    if(this.destroyed || this.openGeneration !== generation) return;\n\n    try {\n      await confirmationPopup({\n        peerId,\n        title: new PeerTitle({peerId}).element,\n        descriptionLangKey: isBroadcast ? 'VoiceChat.RemovePeer.Confirm.Channel' : 'VoiceChat.RemovePeer.Confirm',\n        descriptionLangArgs: [new PeerTitle({peerId}).element],\n        button: {\n          langKey: 'VoiceChat.RemovePeer.Confirm.OK',\n          isDanger: true\n        }\n      });\n    } catch(err) {\n      // Rejection is the confirmation popup's ordinary cancel path.\n      return;\n    }\n\n    try {\n      await this.managers.appChatsManager.kickFromChat(chatId, peerId);\n    } catch(err) {\n      if(this.destroyed) return;\n      console.error('remove group call participant failed', err);\n      toastNew({langPackKey: 'Error.AnError'});\n    }\n  }\n\n  public destroy() {\n    if(this.destroyed) return;\n    this.destroyed = true;\n    ++this.openGeneration;\n    this.contextMenu.destroy();\n    this.removeParentCleanup();\n    this.listenerSetter.removeAll();\n  }\n};\n\nexport default class GroupCallParticipantsElement {\n  private container: HTMLDivElement;\n  private sortedList: GroupCallParticipantsList;\n  private instance: GroupCallInstance;\n  private listenerSetter: ListenerSetter;\n  private groupCallParticipantsVideo: GroupCallParticipantsVideoElement;\n  private contextMenu: GroupCallParticipantContextMenu;\n  private managers: AppManagers;\n  private scrollable: Scrollable;\n  private destroyed = false;\n  private instanceGeneration = 0;\n  private rowMutationGeneration = 0;\n  private rowMutationGenerations = new Map<PeerId, number>();\n\n  constructor(options: {\n    appendTo: HTMLElement,\n    instance: GroupCallInstance,\n    listenerSetter: ListenerSetter,\n    managers: AppManagers\n  }) {\n    safeAssign(this, options);\n\n    const className = 'group-call-participants';\n\n    const scrollable = this.scrollable = new Scrollable(undefined);\n    scrollable.container.classList.add(className + '-scrollable');\n\n    const container = this.container = document.createElement('div');\n    container.classList.add(className);\n\n    // const invite = Button(`btn-primary btn-transparent ${className}-invite`, {icon: 'adduser', text: 'VoiceChat.Invite.InviteMembers'});\n\n    const sortedList = this.sortedList = new GroupCallParticipantsList(this.instance);\n\n    const {instance, listenerSetter} = this;\n    this.contextMenu = new GroupCallParticipantContextMenu({\n      ...options,\n      onContextElement: sortedList.list,\n      listenerSetter,\n      instance\n    });\n\n    this.groupCallParticipantsVideo = new GroupCallParticipantsVideoElement({\n      ...options,\n      appendTo: scrollable.container,\n      displayPinned: false\n    });\n\n    scrollable.append(/* invite,  */sortedList.list);\n    container.append(scrollable.container);\n\n    options.appendTo.append(container);\n\n    listenerSetter.add(rootScope)('group_call_participant', ({groupCallId, participant}) => {\n      if(this.instance.id === groupCallId) {\n        this.updateParticipant(participant);\n      }\n    });\n\n    // Members that the e2e blockchain authorises but the SFU roster omits. They\n    // hold the current call key, so they get a row like anyone else — see\n    // `@lib/calls/e2e/conferenceMembership`.\n    listenerSetter.add(instance)('membersWithAccess', ({current, previous}) => {\n      const currentSet = new Set(current);\n      // A peer leaving the set either joined the SFU for real (a live row takes\n      // over) or was removed from the chain (nothing left to show) — refreshRow\n      // resolves which by re-reading the participant.\n      previous.filter((peerId) => !currentSet.has(peerId)).forEach((peerId) => {\n        this.refreshRow(peerId);\n      });\n      current.forEach((peerId) => this.refreshRow(peerId));\n    });\n\n    const scrollableLoader = new ScrollableLoader({\n      scrollable,\n      getPromise: () => {\n        return this.managers.appGroupCallsManager.getGroupCallParticipants(this.instance.id).then(({participants, isEnd}) => {\n          if(this.destroyed) return true;\n          participants.forEach((participant) => {\n            this.updateParticipant(participant);\n          });\n\n          return isEnd;\n        });\n      }\n    });\n\n    void this.setInstance(instance);\n  }\n\n  // Re-render one row from whatever the instance currently knows about the peer\n  // (a real SFU participant, a chain-only member, or neither). Reading the\n  // participant crosses the manager proxy, so swallow a transient failure\n  // rather than dropping the row — or leaking an unhandled rejection.\n  private async refreshRow(peerId: PeerId): Promise<void> {\n    if(this.destroyed) return;\n    const instance = this.instance;\n    const generation = this.instanceGeneration;\n    try {\n      const participant = await instance.getParticipantByPeerId(peerId);\n      if(this.destroyed || this.instance !== instance || this.instanceGeneration !== generation) return;\n      if(participant) {\n        this.updateParticipant(participant);\n      } else if(this.sortedList.has(peerId)) {\n        this.sortedList.delete(peerId);\n      }\n    } catch(err) {\n      if(!this.destroyed && this.instance === instance && this.instanceGeneration === generation) {\n        console.error('refresh group call participant row failed', err);\n      }\n    }\n  }\n\n  private updateParticipant(participant: GroupCallParticipant) {\n    if(this.destroyed) return;\n    const peerId = getPeerId(participant.peer);\n    const mutationGeneration = ++this.rowMutationGeneration;\n    this.rowMutationGenerations.set(peerId, mutationGeneration);\n    const has = this.sortedList.has(peerId);\n    if(participant.pFlags.left) {\n      // A `left` update says the SFU dropped them, NOT that they lost the call\n      // key — that is the blockchain's word, and it is the one that matters\n      // here. Deleting the row on the server's say-so is how a disclosed\n      // chain-only key holder used to be erased for good: `getParticipantByPeerId`\n      // falls back to the synthetic, but nothing re-added the row afterwards,\n      // because publishMembersWithAccess only dispatches when the chain-only\n      // SET changes and the set is unchanged by a roster push.\n      if(this.instance.isMemberWithAccess(peerId)) {\n        this.refreshRow(peerId);\n        return;\n      }\n\n      if(has) {\n        this.sortedList.delete(peerId);\n      }\n\n      return;\n    }\n\n    if(!has) {\n      this.runListMutation(peerId, mutationGeneration, 'add', this.sortedList.add(peerId));\n      return;\n    }\n\n    this.runListMutation(peerId, mutationGeneration, 'update', this.sortedList.update(peerId));\n  }\n\n  private runListMutation(\n    peerId: PeerId,\n    generation: number,\n    operation: 'add' | 'update',\n    result: MaybePromise<void>\n  ) {\n    void Promise.resolve(result).catch((err) => {\n      if(this.destroyed || this.rowMutationGenerations.get(peerId) !== generation) return;\n      if(operation === 'add' && this.sortedList.has(peerId)) {\n        // SortedList registers the element before its async index lookup. If\n        // that lookup fails, remove the half-created row so a later update can\n        // retry from a clean state.\n        this.sortedList.delete(peerId, true);\n      }\n      console.error(`group call participant row ${operation} failed`, err);\n    });\n  }\n\n  public async setInstance(instance: GroupCallInstance) {\n    const generation = ++this.instanceGeneration;\n    // @ts-ignore\n    /* const users = appUsersManager.users;\n    for(const userId in users) {\n      const participant: GroupCallParticipant = {\n        _: 'groupCallParticipant',\n        date: 0,\n        peer: {_: 'peerUser', user_id: userId.toPeerId()},\n        pFlags: {\n          muted: true\n        },\n        source: 1\n      };\n\n      instance.participants.set(userId.toPeerId(), participant);\n      this.updateParticipant(participant);\n    } */\n    try {\n      const participants = await instance.participants;\n      if(this.destroyed || this.instance !== instance || this.instanceGeneration !== generation) return;\n      participants.forEach((participant) => {\n        this.updateParticipant(participant);\n      });\n\n      // The popup can open mid-call, after reconciliation already ran.\n      instance.memberWithAccessPeerIds.forEach((peerId) => this.refreshRow(peerId));\n    } catch(err) {\n      if(!this.destroyed && this.instance === instance && this.instanceGeneration === generation) {\n        console.error('load group call participants failed', err);\n      }\n    }\n  }\n\n  public destroy() {\n    if(this.destroyed) return;\n    this.destroyed = true;\n    ++this.instanceGeneration;\n    this.rowMutationGenerations.clear();\n    this.contextMenu.destroy();\n    this.scrollable.destroy();\n    this.sortedList.destroy();\n    this.groupCallParticipantsVideo.destroy();\n  }\n}\n","import Icon from '@components/icon';\nimport {GroupCall} from '@layer';\nimport GroupCallInstance from '@lib/calls/groupCallInstance';\nimport GROUP_CALL_STATE from '@lib/calls/groupCallState';\nimport I18n, {LangPackKey, FormatterArguments} from '@lib/langPack';\n\nexport default class GroupCallDescriptionElement {\n  private descriptionIntl: I18n.IntlElement;\n  private shortDescription: HTMLElement;\n  private mounted: HTMLElement;\n\n  constructor(private appendTo: HTMLElement, private useIcon?: boolean) {\n    this.descriptionIntl = new I18n.IntlElement({\n      key: 'VoiceChat.Status.Connecting'\n    });\n\n    this.descriptionIntl.element.classList.add('group-call-description');\n  }\n\n  public detach() {\n    this.mounted.remove();\n  }\n\n  public update(instance: GroupCallInstance) {\n    const {state} = instance;\n    const groupCall = instance.groupCall as GroupCall.groupCall | undefined;\n    const isConnecting = state === GROUP_CALL_STATE.CONNECTING;\n    // Only use the compact \"icon + count\" form while connected — `Connecting`\n    // is text, no count to show, so fall back to the i18n element.\n    const useShort = this.useIcon && !isConnecting;\n\n    let mount: HTMLElement;\n    if(useShort) {\n      if(!this.shortDescription) {\n        this.shortDescription = document.createElement('span');\n        this.shortDescription.classList.add('group-call-description');\n      }\n      this.shortDescription.replaceChildren(\n        Icon('newprivate_filled', 'inline-icon'),\n        '' + (groupCall?.participants_count ?? 1)\n      );\n      mount = this.shortDescription;\n    } else {\n      let key: LangPackKey, args: FormatterArguments;\n      if(isConnecting) {\n        key = 'VoiceChat.Status.Connecting';\n      } else {\n        key = 'VoiceChat.Status.Members';\n        args = [groupCall?.participants_count ?? 1];\n      }\n      this.descriptionIntl.compareAndUpdate({key, args});\n      mount = this.descriptionIntl.element;\n    }\n\n    // The host (`appendTo`) is sometimes cleared externally — e.g. topbarCall's\n    // `clearCurrentInstance` does `statusEl.replaceChildren()`. After such a\n    // clear, `this.mounted` keeps pointing at a detached node, so a plain\n    // `replaceWith` silently no-ops. Re-mount unconditionally when needed.\n    if(this.mounted && this.mounted !== mount) {\n      this.mounted.remove();\n    }\n    if(!mount.parentElement) {\n      this.appendTo.append(mount);\n    }\n    this.mounted = mount;\n  }\n}\n","import setInnerHTML from '@helpers/dom/setInnerHTML';\nimport replaceContent from '@helpers/dom/replaceContent';\nimport {GroupCall} from '@layer';\nimport type GroupCallInstance from '@lib/calls/groupCallInstance';\nimport {NULL_PEER_ID} from '@appManagers/constants';\nimport wrapEmojiText from '@lib/richTextProcessor/wrapEmojiText';\nimport PeerTitle from '@components/peerTitle';\nimport {i18n} from '@lib/langPack';\n\nexport default class GroupCallTitleElement {\n  private peerTitle: PeerTitle;\n\n  constructor(private appendTo: HTMLElement) {\n    this.peerTitle = new PeerTitle({peerId: NULL_PEER_ID});\n  }\n\n  public update(instance: GroupCallInstance) {\n    const {peerTitle, appendTo} = this;\n    const groupCall = instance.groupCall as GroupCall.groupCall;\n    if(groupCall?.title) {\n      setInnerHTML(appendTo, wrapEmojiText(groupCall.title));\n      return;\n    }\n\n    // TdE2E conferences don't have a backing chat — use a plain title.\n    // Eventually this can list participant names.\n    if(instance.e2e && (!instance.chatId || instance.chatId === NULL_PEER_ID)) {\n      replaceContent(appendTo, i18n('ConferenceCall.Title'));\n      return;\n    }\n\n    const peerId = instance.chatId.toPeerId(true);\n    if(peerTitle.options.peerId !== peerId) {\n      peerTitle.options.peerId = peerId;\n      peerTitle.update();\n    }\n\n    if(peerTitle.element.parentElement !== appendTo) {\n      appendTo.append(peerTitle.element);\n    }\n  }\n}\n","import confirmationPopup from '@components/confirmationPopup';\nimport {toastNew} from '@components/toast';\nimport type GroupCallInstance from '@lib/calls/groupCallInstance';\n\nexport default async function requestGroupCallLeave(\n  instance: GroupCallInstance,\n  canManage: boolean\n): Promise<boolean> {\n  let discard = false;\n  if(canManage) {\n    try {\n      discard = !!await confirmationPopup({\n        titleLangKey: 'VoiceChat.End.Title',\n        descriptionLangKey: 'VoiceChat.End.Text',\n        className: 'popup-end-video-chat',\n        checkbox: {text: 'VoiceChat.End.Third'},\n        button: {\n          langKey: 'VoiceChat.End.OK',\n          isDanger: true\n        }\n      });\n    } catch{\n      return false;\n    }\n  }\n\n  try {\n    await instance.hangUp(discard);\n    return true;\n  } catch(err) {\n    console.error('leave group call failed', err);\n    toastNew({langPackKey: 'Error.AnError'});\n    return false;\n  }\n}\n","import ListenerSetter from '@helpers/listenerSetter';\nimport {i18n, LangPackKey} from '@lib/langPack';\nimport Icon from '@components/icon';\nimport ripple from '@components/ripple';\n\nlet nextCallButtonLabelId = 0;\n\ntype CallButtonOptions = {\n  text?: LangPackKey | HTMLElement,\n  ariaLabel?: LangPackKey,\n  isDanger?: boolean,\n  noRipple?: boolean,\n  callback?: () => MaybePromise<void>,\n  icon?: Icon,\n  isConfirm?: boolean,\n  disabled?: boolean\n};\n\nexport function setCallButtonLabel(button: HTMLButtonElement, key: LangPackKey) {\n  const label = i18n(key).textContent;\n  button.setAttribute('aria-label', label);\n  button.title = label;\n}\n\nfunction getCallButton(element: HTMLElement): HTMLButtonElement {\n  const button = element.tagName === 'BUTTON' ?\n    element as HTMLButtonElement :\n    element.querySelector<HTMLButtonElement>('button.call-button');\n  if(!button) {\n    throw new Error('Call button element is missing');\n  }\n\n  return button;\n}\n\nfunction applyCallButtonDisabledState(element: HTMLElement, button: HTMLButtonElement) {\n  const disabled = button.dataset.callDisabled === '1' || button.dataset.busy === '1';\n  button.disabled = disabled;\n  element.classList.toggle('btn-disabled', disabled);\n}\n\nexport function setCallButtonDisabled(element: HTMLElement, disabled: boolean) {\n  const button = getCallButton(element);\n  if(disabled) button.dataset.callDisabled = '1';\n  else delete button.dataset.callDisabled;\n  applyCallButtonDisabledState(element, button);\n}\n\nexport function setCallButtonBusy(element: HTMLElement, busy: boolean) {\n  const button = getCallButton(element);\n  const wasBusy = button.dataset.busy === '1';\n  if(busy && !wasBusy) {\n    if(button.disabled) button.dataset.callDisabled = '1';\n    else delete button.dataset.callDisabled;\n  }\n\n  if(busy) button.dataset.busy = '1';\n  else delete button.dataset.busy;\n  if(busy) button.setAttribute('aria-busy', 'true');\n  else button.removeAttribute('aria-busy');\n  applyCallButtonDisabledState(element, button);\n}\n\nexport default function makeButton(className: string, listenerSetter: ListenerSetter, options: CallButtonOptions) {\n  const _className = className + '-button';\n  const button = document.createElement('button');\n  button.type = 'button';\n  button.classList.add(_className, 'call-button', 'rp-overflow');\n  button.disabled = !!options.disabled;\n\n  if(options.icon) {\n    button.append(Icon(options.icon));\n  }\n\n  if(!options.noRipple) {\n    ripple(button);\n  }\n\n  if(options.isDanger) {\n    button.classList.add(_className + '-red');\n  }\n\n  if(options.isConfirm) {\n    button.classList.add(_className + '-green');\n  }\n\n  if(options.callback) {\n    // A native `click` is intentionally used instead of attachClickEvent.\n    // On touch-capable devices that helper listens for `mousedown`, which a\n    // keyboard-generated button activation never emits.\n    listenerSetter.add(button)('click', options.callback);\n  }\n\n  if(options.ariaLabel) {\n    setCallButtonLabel(button, options.ariaLabel);\n  }\n\n  let ret: HTMLElement = button;\n  if(options.text) {\n    const div = document.createElement('div');\n    div.classList.add(_className + '-container', 'call-button-container');\n\n    const textEl = typeof(options.text) === 'string' ? i18n(options.text) : options.text;\n    textEl.classList.add(_className + '-text', 'call-button-text');\n    textEl.id ||= `call-button-label-${++nextCallButtonLabelId}`;\n    if(!options.ariaLabel) {\n      button.setAttribute('aria-labelledby', textEl.id);\n    }\n\n    div.append(button, textEl);\n\n    ret = div;\n  }\n\n  return ret;\n}\n","/*\n * Render a verification fingerprint (`emoji_hash` bytes) as a short sequence\n * of curated emojis — the human-readable form a user reads aloud to verify\n * their conference is end-to-end-encrypted to the same key on every device.\n *\n * Algorithm: chunks of 8 bytes (clearing the top bit to fit in JS' 53-bit\n * Number safely) are reduced modulo the size of a fixed emoji table. The\n * table is 333 entries — ported as-is from tdesktop's\n * Telegram/SourceFiles/calls/calls_emoji_fingerprint.cpp Data[]/Offsets[]\n * arrays. The output sequence is deterministic for a given input — the\n * point of the protocol — and matches what every other Telegram client\n * displays for the same call, which is THE acceptance test for the e2e\n * crypto port (see Phase 7 in tde2e-port.md).\n *\n * Spec: TdE2E `CallVerificationState::emoji_hash` (32 bytes) → 4 emojis.\n * 1-on-1 fingerprint uses the same algorithm against SHA-256(key + g_a).\n */\n\n// 333-entry emoji list. UTF-16 code units laid out exactly as in tdesktop;\n// each emoji is one or more UTF-16 code units, ranges given by the offset\n// table below. Encoding the list this way (vs. as a JS string array) keeps\n// the source bytes identical to the reference C++ — easy to cross-check.\nconst EMOJI_CODE_UNITS: number[] = [\n  0xd83d, 0xde09, 0xd83d, 0xde0d, 0xd83d, 0xde1b, 0xd83d, 0xde2d, 0xd83d, 0xde31, 0xd83d, 0xde21,\n  0xd83d, 0xde0e, 0xd83d, 0xde34, 0xd83d, 0xde35, 0xd83d, 0xde08, 0xd83d, 0xde2c, 0xd83d, 0xde07,\n  0xd83d, 0xde0f, 0xd83d, 0xdc6e, 0xd83d, 0xdc77, 0xd83d, 0xdc82, 0xd83d, 0xdc76, 0xd83d, 0xdc68,\n  0xd83d, 0xdc69, 0xd83d, 0xdc74, 0xd83d, 0xdc75, 0xd83d, 0xde3b, 0xd83d, 0xde3d, 0xd83d, 0xde40,\n  0xd83d, 0xdc7a, 0xd83d, 0xde48, 0xd83d, 0xde49, 0xd83d, 0xde4a, 0xd83d, 0xdc80, 0xd83d, 0xdc7d,\n  0xd83d, 0xdca9, 0xd83d, 0xdd25, 0xd83d, 0xdca5, 0xd83d, 0xdca4, 0xd83d, 0xdc42, 0xd83d, 0xdc40,\n  0xd83d, 0xdc43, 0xd83d, 0xdc45, 0xd83d, 0xdc44, 0xd83d, 0xdc4d, 0xd83d, 0xdc4e, 0xd83d, 0xdc4c,\n  0xd83d, 0xdc4a, 0x270c, 0x270b, 0xd83d, 0xdc50, 0xd83d, 0xdc46, 0xd83d, 0xdc47, 0xd83d, 0xdc49,\n  0xd83d, 0xdc48, 0xd83d, 0xde4f, 0xd83d, 0xdc4f, 0xd83d, 0xdcaa, 0xd83d, 0xdeb6, 0xd83c, 0xdfc3,\n  0xd83d, 0xdc83, 0xd83d, 0xdc6b, 0xd83d, 0xdc6a, 0xd83d, 0xdc6c, 0xd83d, 0xdc6d, 0xd83d, 0xdc85,\n  0xd83c, 0xdfa9, 0xd83d, 0xdc51, 0xd83d, 0xdc52, 0xd83d, 0xdc5f, 0xd83d, 0xdc5e, 0xd83d, 0xdc60,\n  0xd83d, 0xdc55, 0xd83d, 0xdc57, 0xd83d, 0xdc56, 0xd83d, 0xdc59, 0xd83d, 0xdc5c, 0xd83d, 0xdc53,\n  0xd83c, 0xdf80, 0xd83d, 0xdc84, 0xd83d, 0xdc9b, 0xd83d, 0xdc99, 0xd83d, 0xdc9c, 0xd83d, 0xdc9a,\n  0xd83d, 0xdc8d, 0xd83d, 0xdc8e, 0xd83d, 0xdc36, 0xd83d, 0xdc3a, 0xd83d, 0xdc31, 0xd83d, 0xdc2d,\n  0xd83d, 0xdc39, 0xd83d, 0xdc30, 0xd83d, 0xdc38, 0xd83d, 0xdc2f, 0xd83d, 0xdc28, 0xd83d, 0xdc3b,\n  0xd83d, 0xdc37, 0xd83d, 0xdc2e, 0xd83d, 0xdc17, 0xd83d, 0xdc34, 0xd83d, 0xdc11, 0xd83d, 0xdc18,\n  0xd83d, 0xdc3c, 0xd83d, 0xdc27, 0xd83d, 0xdc25, 0xd83d, 0xdc14, 0xd83d, 0xdc0d, 0xd83d, 0xdc22,\n  0xd83d, 0xdc1b, 0xd83d, 0xdc1d, 0xd83d, 0xdc1c, 0xd83d, 0xdc1e, 0xd83d, 0xdc0c, 0xd83d, 0xdc19,\n  0xd83d, 0xdc1a, 0xd83d, 0xdc1f, 0xd83d, 0xdc2c, 0xd83d, 0xdc0b, 0xd83d, 0xdc10, 0xd83d, 0xdc0a,\n  0xd83d, 0xdc2b, 0xd83c, 0xdf40, 0xd83c, 0xdf39, 0xd83c, 0xdf3b, 0xd83c, 0xdf41, 0xd83c, 0xdf3e,\n  0xd83c, 0xdf44, 0xd83c, 0xdf35, 0xd83c, 0xdf34, 0xd83c, 0xdf33, 0xd83c, 0xdf1e, 0xd83c, 0xdf1a,\n  0xd83c, 0xdf19, 0xd83c, 0xdf0e, 0xd83c, 0xdf0b, 0x26a1, 0x2614, 0x2744, 0x26c4, 0xd83c, 0xdf00,\n  0xd83c, 0xdf08, 0xd83c, 0xdf0a, 0xd83c, 0xdf93, 0xd83c, 0xdf86, 0xd83c, 0xdf83, 0xd83d, 0xdc7b,\n  0xd83c, 0xdf85, 0xd83c, 0xdf84, 0xd83c, 0xdf81, 0xd83c, 0xdf88, 0xd83d, 0xdd2e, 0xd83c, 0xdfa5,\n  0xd83d, 0xdcf7, 0xd83d, 0xdcbf, 0xd83d, 0xdcbb, 0x260e, 0xd83d, 0xdce1, 0xd83d, 0xdcfa, 0xd83d,\n  0xdcfb, 0xd83d, 0xdd09, 0xd83d, 0xdd14, 0x23f3, 0x23f0, 0x231a, 0xd83d, 0xdd12, 0xd83d, 0xdd11,\n  0xd83d, 0xdd0e, 0xd83d, 0xdca1, 0xd83d, 0xdd26, 0xd83d, 0xdd0c, 0xd83d, 0xdd0b, 0xd83d, 0xdebf,\n  0xd83d, 0xdebd, 0xd83d, 0xdd27, 0xd83d, 0xdd28, 0xd83d, 0xdeaa, 0xd83d, 0xdeac, 0xd83d, 0xdca3,\n  0xd83d, 0xdd2b, 0xd83d, 0xdd2a, 0xd83d, 0xdc8a, 0xd83d, 0xdc89, 0xd83d, 0xdcb0, 0xd83d, 0xdcb5,\n  0xd83d, 0xdcb3, 0x2709, 0xd83d, 0xdceb, 0xd83d, 0xdce6, 0xd83d, 0xdcc5, 0xd83d, 0xdcc1, 0x2702,\n  0xd83d, 0xdccc, 0xd83d, 0xdcce, 0x2712, 0x270f, 0xd83d, 0xdcd0, 0xd83d, 0xdcda, 0xd83d, 0xdd2c,\n  0xd83d, 0xdd2d, 0xd83c, 0xdfa8, 0xd83c, 0xdfac, 0xd83c, 0xdfa4, 0xd83c, 0xdfa7, 0xd83c, 0xdfb5,\n  0xd83c, 0xdfb9, 0xd83c, 0xdfbb, 0xd83c, 0xdfba, 0xd83c, 0xdfb8, 0xd83d, 0xdc7e, 0xd83c, 0xdfae,\n  0xd83c, 0xdccf, 0